-- =============================================
-- Author:		GA
-- Create date: 07/27/2010
-- Description:	Recuperar datos por filtros.
-- =============================================


CREATE PROCEDURE [dbo].[spAccessControl_getDataByFilters]
(
	@comp_id			int,
	@bra_id				int,
	@prof_id			int

)
AS

BEGIN




	set nocount ON
	-- -----------------------------------------------------
	-- Testing
	-- -----------------------------------------------------
	/*
	DECLARE 	@comp_id			int,
				@bra_id				int,
				@prof_id			int

	SELECT		@comp_id			= 1,
				@bra_id				= -1,
				@prof_id			= -1

	*/
	-- -----------------------------------------------------



	SELECT  tac.bra_id,
			tb.bra_desc,
			tac.prof_id,
			tp.prof_desc,
			isnull(tac.ip,'')			[ip],
			IsNull(tac.dns,'')			[dns]

	FROM  tbAccessControl				tac			WITH (NOLOCK)

	INNER JOIN tbBranch					tb			WITH (NOLOCK)
	ON	  tb.comp_id	= tac.comp_id
	AND   tb.bra_id		= tac.bra_id

	INNER JOIN tbProfile				tp			WITH (NOLOCK)
	ON    tp.prof_id	= tac.prof_id
	AND   tp.comp_id	= tac.comp_id


	WHERE   tac.comp_id			 =  @comp_id
	AND     (tac.bra_id			 =  @bra_id  OR  @bra_id		= -1)
	AND		(tac.prof_id		 =  @prof_id OR  @prof_id		= -1)
	AND		tac.ac_disabled		 = 'False'




END

























GO





CREATE PROCEDURE spAccountant_AccountGrouping_getCombo
(
	@comp_id	INT
)
AS SET NOCOUNT ON


SELECT
	taag.acgr_id	[Id],
	taag.acgr_desc	[Desc]

FROM tbAccountant_AccountGrouping taag

WHERE taag.comp_id = @comp_id

ORDER BY taag.acgr_desc
GO

CREATE PROCEDURE spAccountant_BalanceGroup_GetCombo
(
	@comp_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			tabg.abl_id												[Id],
			tabg.abl_desc											[Desc]
			FROM tbAccountant_BalanceGroup							tabg	WITH(NOLOCK)
			WHERE	tabg.comp_id						= @comp_id	AND
					ISNULL(tabg.abl_disabled,'False')	= 'False'
	END
GO

