	--ACTIVO
	SELECT

					tabg.abl_desc,
					AC.acc_code,
					LTRIM(RTRIM(AC.acc_code)) + ' ' + AC.acc_desc							[acc_desc],

					--EN LA MONEDA PESOS CHILENOS
