					dbo.fnGetExchange2(@comp_id, SUM(T.dacc_debit),11,2,11,2,0,'False')		[dacc_debit_USD],
					dbo.fnGetExchange2(@comp_id, SUM(T.dacc_credit),11,2,11,2,0,'False')	[dacc_credit_USD],

					--COLUMNA Y ORDEN
					tabg.abl_order															[Order],
					tabgd.abld_columnNumber													[Column],

					SUM(ISNULL(T.dacc_debit,0)) - SUM(ISNULL(T.dacc_credit,0))				[DebitMinusCredit],


