								   tba.ba_id				= tct.ba_id
							LEFT JOIN tbCostCenter									tcc	WITH (NOLOCK)
							ON		tcc.comp_id				= T.comp_id				AND
									tcc.cc_code				= T.cc_code
							INNER JOIN tbAccountant_BalanceGroupDetail				tabgd	WITH(NOLOCK)
							ON	tabgd.comp_id				= AC.comp_id			AND
								tabgd.acc_count_id			= AC.acc_count_id
							INNER JOIN tbAccountant_BalanceGroup					tabg	WITH(NOLOCK)
							ON	tabg.comp_id				= tabgd.comp_id			AND
								tabg.abl_id					= tabgd.abl_id


					WHERE		t.[comp_id]					= @comp_id				AND
								(
									@ap_id					= -1	OR
									A.[ap_id]				= @ap_id
								)													AND
								A.[hacc_date]	BETWEEN @hacc_date_from	AND @hacc_date_to	AND
								AC.[acc_code]	BETWEEN	@acc_code_from	AND @acc_code_to	AND
								(
									@ag_id					= -1	OR
									A.ag_id					= @ag_id
								)															AND

					-- --------------------------------------------------------------------
					-- Deshabilitado por MOS ya que hacia tardar INFINITAMENTE este listado
					-- --------------------------------------------------------------------
					--				AND		(@acc_count_id	= -1 or T.[hacc_transaction] in (select	distinct td.[hacc_transaction]
					--																		from [tbAccountTransactionDetail] td
					--																		where td.[acc_count_id] = @acc_count_id))
					-- --------------------------------------------------------------------

								(
									@cc_code				= -1	OR
									T.cc_code				= @cc_code
								)
				GROUP BY tabg.abl_desc, AC.acc_code, AC.acc_desc, tabg.abl_order, tabgd.abld_columnNumber
				ORDER BY tabg.abl_order


				SELECT
					*
					FROM #tmp
				WHERE [Column] = 1
				ORDER BY	[Order]

				SET @TotalActive	= 0
				SET @TotalActiveUSD = 0
				SELECT
					@TotalActive	= @TotalActive		+ [DebitMinusCredit],
					@TotalActiveUSD = @TotalActiveUSD	+ [DebitMinusCreditUSD]
					FROM #tmp
				WHERE [Column] = 1
				ORDER BY	[Order]


				DROP TABLE #tmp



	--PASIVO
	SELECT
					tabg.abl_desc															[abl_desc_],
					AC.acc_code																[acc_code_],
					LTRIM(RTRIM(AC.acc_code)) + ' ' + AC.acc_desc							[acc_desc_],

					--EN LA MONEDA PESOS CHILENOS
					SUM(T.dacc_debit)														[dacc_debit_],
					SUM(T.dacc_credit)														[dacc_credit_],

					--EN USD
					dbo.fnGetExchange2(@comp_id, SUM(T.dacc_debit),11,2,11,2,0,'False')		[dacc_debit_USD_],
					dbo.fnGetExchange2(@comp_id, SUM(T.dacc_credit),11,2,11,2,0,'False')	[dacc_credit_USD_],

					--COLUMNA Y ORDEN
					tabg.abl_order															[Order_],
					tabgd.abld_columnNumber													[Column_],

					SUM(T.dacc_debit) - SUM(T.dacc_credit)									[DebitMinusCredit_],

					0																		[DebitMinusCreditUSD_]

					--dbo.fnGetExchange2(@comp_id, SUM(ISNULL(T.dacc_debit,0)),11,2,11,2,0,'False')	 -
					--dbo.fnGetExchange2(@comp_id, SUM(ISNULL(T.dacc_credit,0)),11,2,11,2,0,'False')	[DebitMinusCreditUSD_]


					INTO #tmp2

					FROM	dbo.tbAccountTransactionDetail							T	WITH (NOLOCK)
							INNER JOIN @tmpAccountant								tmp
								ON tmp.acc_count_id = t.acc_count_id
							INNER JOIN [tbAccountTransactionHead]					A	WITH (NOLOCK)
								ON	T.[hacc_transaction]	= A.[hacc_transaction]	AND
									T.[comp_id]				= A.[comp_id]
							INNER JOIN tbAccountant									AC	WITH (NOLOCK)
								ON	A.comp_id				= AC.comp_id			AND
									T.acc_count_id			= AC.acc_count_id
							LEFT JOIN tbCommercialTransactions						tct WITH (NOLOCK)
								ON	tct.comp_id				= T.comp_id				AND
									tct.ct_transaction		= T.ct_transaction
							LEFT JOIN tbSupplier									ts	WITH (NOLOCK)
								ON	ts.comp_id				= tct.comp_id			AND
									ts.supp_id				= tct.supp_id
							LEFT JOIN tbCustomer									tc	WITH (NOLOCK)
								ON	tc.comp_id				= tct.comp_id			AND
									tc.cust_id				= tct.cust_id
							LEFT JOIN tbBankingAccounts								tba	WITH (NOLOCK)
								ON tba.comp_id				= tct.comp_id			AND
								   tba.ba_id				= tct.ba_id
							LEFT JOIN tbCostCenter									tcc	WITH (NOLOCK)
							ON		tcc.comp_id				= T.comp_id				AND
									tcc.cc_code				= T.cc_code
							INNER JOIN tbAccountant_BalanceGroupDetail				tabgd	WITH(NOLOCK)
							ON	tabgd.comp_id				= AC.comp_id			AND
								tabgd.acc_count_id			= AC.acc_count_id
							INNER JOIN tbAccountant_BalanceGroup					tabg	WITH(NOLOCK)
							ON	tabg.comp_id				= tabgd.comp_id			AND
								tabg.abl_id					= tabgd.abl_id


					WHERE		t.[comp_id]					= @comp_id				AND
								(
									@ap_id					= -1	OR
									A.[ap_id]				= @ap_id
								)													AND
								A.[hacc_date]	BETWEEN @hacc_date_from	AND @hacc_date_to	AND
								AC.[acc_code]	BETWEEN	@acc_code_from	AND @acc_code_to	AND
								(
									@ag_id					= -1	OR
									A.ag_id					= @ag_id
								)															AND

					-- --------------------------------------------------------------------
					-- Deshabilitado por MOS ya que hacia tardar INFINITAMENTE este listado
					-- --------------------------------------------------------------------
					--				AND		(@acc_count_id	= -1 or T.[hacc_transaction] in (select	distinct td.[hacc_transaction]
					--																		from [tbAccountTransactionDetail] td
					--																		where td.[acc_count_id] = @acc_count_id))
					-- --------------------------------------------------------------------

								(
									@cc_code				= -1	OR
									T.cc_code				= @cc_code
								)
				GROUP BY tabg.abl_desc, AC.acc_code, AC.acc_desc, tabg.abl_order, tabgd.abld_columnNumber
				ORDER BY tabg.abl_order

				SELECT
					*
					FROM #tmp2
				WHERE [Column_] = 2
				ORDER BY	[Order_]



				SET @TotalPasive	= 0
				SET @TotalPasiveUSD = 0
				SELECT
					@TotalPasive	= @TotalPasive		+ [DebitMinusCredit_],
					@TotalPasiveUSD = @TotalPasiveUSD	+ DebitMinusCreditUSD_
					FROM #tmp2
				WHERE [Column_] = 2
				ORDER BY	[Order_]


				DROP TABLE #tmp2


				DECLARE
					@rptColumn5	NVARCHAR(300),
					@rptColumn6	NVARCHAR(300),
					@rptColumn7	NVARCHAR(300)


				SELECT @rptColumn5 = tswn.word_desc	FROM tbSysWordsNew tswn WHERE tswn.lang_id = @lang_id AND tswn.wordsi_id = 16405
				SELECT @rptColumn6 = tswn.word_desc	FROM tbSysWordsNew tswn WHERE tswn.lang_id = @lang_id AND tswn.wordsi_id = 16406
				SELECT @rptColumn7 = tswn.word_desc	FROM tbSysWordsNew tswn WHERE tswn.lang_id = @lang_id AND tswn.wordsi_id = 16407



				SELECT
					@TotalActive		[TotalActive],
					@TotalActiveUSD		[TotalActiveUSD],
					@TotalPasive		[TotalPasive],
					@TotalPasiveUSD		[TotalPasiveUSD],
					@rptColumn5			[rptColumn5],
					@rptColumn6			[rptColumn6],
					@rptColumn7			[rptColumn7]



	END



GO






-- Update: 12-2008 : MOS
-- Para que solo traiga cuentas imputables.


CREATE PROCEDURE [dbo].[spAccountant_getCombo]
(
	@comp_id			INT,
	@acc_imputable		VARCHAR(10)
)
as
set noCOUNT ON


/*
DECLARE	@comp_id			INT,
		@acc_imputable		VARCHAR(10)
SELECT  @comp_id			= 1,
		@acc_imputable		= 'true'
*/


select		acc_count_id									[ID],
			ltrim(rtrim(acc_code)) + '-' + acc_desc			[desc]

from		tbAccountant	WITH (NOLOCK)

where		comp_id = @comp_id
AND			(@acc_imputable = '-1' OR
			(@acc_imputable = 'True' and acc_imputable = 'True') OR
			(@acc_imputable = 'False' and acc_imputable = 'False'))

Order By	[desc]









GO




CREATE PROCEDURE [dbo].spAccountant_getData4TVLoad
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT
)

AS

	SET NOCOUNT ON

	BEGIN


		DECLARE @tmpTable TABLE (Id INT PRIMARY KEY, [DESC] NVARCHAR(200), IdSup INT)

		INSERT INTO @tmpTable (Id, [DESC], IdSup) VALUES (-1,'*',NULL)


		INSERT INTO @tmpTable (Id, [DESC], IdSup)
		SELECT  ta.acc_count_id,
				ta.acc_desc,
				CASE
				    WHEN ta.acc_count_sum IS NULL THEN -1
				    ELSE ta.acc_count_sum
				END
			FROM tbAccountant ta			WITH (NOLOCK)
			WHERE ta.comp_id = @comp_id
			ORDER BY ta.acc_count_sum, ta.acc_imputable DESC,  ta.acc_code

		SELECT * FROM @tmpTable

	END
GO



