CREATE PROCEDURE [dbo].[spAccountant_getDataByFilters]
(
	@comp_id			int,
	@acc_code			Varchar(20),
	@Item_desc1			Varchar(100),
	@Item_desc2			Varchar(100)
)
as
set nocount ON

/*
DECLARE 	@comp_id			int,
			@acc_code			Varchar(20),
			@Item_desc1			Varchar(100),
			@Item_desc2			Varchar(100)

select		@comp_id			= 1,
			@acc_code			= '1101',
			@Item_desc1			= '',
			@Item_desc2			= ''
*/

	select		acc_code,
				acc_desc,
				acc_imputable,
				(select ltrim(rtrim(P.acc_code)) + '-' + P.acc_desc from dbo.tbAccountant P where P.comp_id = tbAccountant.comp_id and P.acc_count_id = tbAccountant.acc_count_sum) [total],
				acc_column,
				acc_enable4CostCenter,
				acc_count_id [ID]


	from	dbo.tbAccountant	WITH (NOLOCK)

	Where   comp_id		=  @comp_id
	AND 	isnull(acc_desc	,'')	like '%'+ @Item_desc1	+ '%'
	AND		isnull(acc_desc	,'')	like '%'+ @Item_desc2	+ '%'
	AND		isnull(acc_code	,'')	like '%'+ @acc_code		+ '%'






























GO




CREATE PROCEDURE [dbo].[spAccountant_getDataById]
(
	@comp_id		INT,
	@acc_count_id	int
)
as
BEGIN

	set nocount on

	select	a.comp_id,
		a.acc_count_id,
		a.acc_code,
		a.acc_desc,
		a.acc_imputable,
		a.acc_count_sum,
		a.acc_column,
		a.acc_enable4CostCenter,
		ISNULL(a.acc_byInflationAdjust,'False')				[acc_byInflationAdjust],
		ISNULL(a.acc_disabled,'False')						[acc_disabled],
		ISNULL(a.acc_available4CollectionMovements,'False') [acc_available4CollectionMovements]

	from	dbo.tbAccountant a		WITH (NOLOCK)
