			a.acc_count_id =  @acc_count_id


END












GO






CREATE PROCEDURE [dbo].[spAccountant_getDataByText]
(
	@text		VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id	 AS int
)
AS

BEGIN

	SET NOCOUNT ON

	/*
	DECLARE
		@text		VARCHAR(300),
		@count		INT,
		@lang_id	INT
	SELECT
		@text		= 'R',
		@count		= 2,
		@lang_id	= 2

	*/

	SELECT		TOP (@count)
				dbo.fnStrPADR(	ta.acc_desc,40,'.') + ' | ' + isnull(convert(varchar,ta.acc_code),'') + ' | ' + isnull(convert(varchar,ta.acc_count_id),'') [acc_desc],
				ta.acc_code

	FROM		tbAccountant ta		WITH (NOLOCK)

	WHERE		comp_id = @comp_id				AND
			   (	ta.acc_desc LIKE '%' + @text + '%'
					OR
					ta.acc_code LIKE @text+'%'
			   )								AND
			   ta.acc_imputable = 'True'		AND
			   ta.acc_disabled  = 'False'

	ORDER BY	ta.acc_desc

END
GO







CREATE PROCEDURE [dbo].[spAccountant_getReport]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,

	@acc_code_from		varchar(20),
	@acc_code_to		varchar(20),
	@bra_id				INT,
	@intBranch4Lang		int




)
as
	BEGIN

		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		/*
		declare	@comp_id			int,
				@acc_code_from		VARCHAR(20),
				@acc_code_to		VARCHAR(20),
				@lang_id			int,
				@page_id			int,
				@bra_id				INT


		select 	@comp_id			=1,
				@acc_code_from		='1100000000',
				@acc_code_to		='1101000000',
				@lang_id			=2,
				@page_id			=10001,
				@bra_id				=-1

		DECLARE @fun_id INT
		SET @fun_id = 1
		*/
		/************************************************************************************************/
		/*Query que recupera los valores que debe mostrar el reporte, esto es diferente de cada reporte*/
		select		a.acc_code,
					a.acc_desc,
					o.[optval_desc] [acc_imputable],
					b.acc_code		[acc_count_sum],
					a.acc_column


		from		[tbAccountant] a

					left join [tbAccountant] b
					on	b.[comp_id]			= a.[comp_id]
					and b.[acc_count_id]	= a.[acc_count_sum]

					INNER JOIN [tbsysOptionsValues] o
					ON	o.[optval_id]	= a.[acc_imputable]

		where		a.comp_id			= @comp_id
		AND			a.[acc_code]		BETWEEN @acc_code_from AND @acc_code_to
		AND			o.[lang_id]			= @lang_id
		AND			o.[optval_class]	= 1

		order by	a.[acc_code]
		/*************************************************************************************************/
		exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


		/* devolución de parámetros recibidos */
		DECLARE @related_page_id INT
		SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
		/*************************************************************************************************************/
		/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
		/*
				SELECT	t.ctrl_id,	t.[text_desc]
				FROM	[tbsysTexts]				t
						inner join [tbsysControls]	c
						on c.[ctrl_id] = t.[ctrl_id]
				where	t.[lang_id]	= @lang_id
				and		t.[page_id]	= @related_page_id
				and		t.[type_id]	= 1
		*/
		/*************************************************************************************************************/

		Select
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 378
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)	  [params1],
				@acc_code_from [params2],
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 379
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],
      			@acc_code_to [params4]


	END
GO






