CREATE PROCEDURE [dbo].[spAccountantGroup_getAll]
(
	@comp_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@return_value	INT OUTPUT
)
AS

BEGIN



	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@bra_id		INT,
		@user_id	INT,
		@return_value INT

	SELECT
		@comp_id	=1,
		@bra_id		=1,
		@user_id	=1
	*/
	-- -----------------------------------------------------------------------------


	SET @return_value = 0


	IF (SELECT	COUNT(*)
		FROM	tbAccountantGroup						tag
		WHERE	tag.comp_id		= @comp_id)
		=
	   (SELECT	COUNT(*)
		FROM	tbUserCompanyProfile					tucp
				INNER JOIN tbAccountantGroupByProfile	tagbp
				ON  tagbp.comp_id = tucp.comp_id
				AND tagbp.prof_id = tucp.prof_id
	   WHERE	tucp.comp_id	= @comp_id
	   AND		tucp.bra_id		= @bra_id
	   AND		tucp.[user_id]	= @user_id)

			SET @return_value = 1





END
GO






-- MOS  09-09


CREATE PROCEDURE [dbo].[spAccountantGroup_getCombo]
(
	@comp_id			INT,
	@user_id			INT
)
AS

BEGIN

	set noCOUNT ON


	DECLARE @tblBranch TABLE(bra_id INT PRIMARY KEY, ag_id INT)
	INSERT INTO @tblBranch(bra_id, ag_id)
		SELECT DISTINCT tb.bra_id , tag.ag_id
			FROM tbAccountantGroup	tag
			INNER JOIN tbBranch		tb
				ON	tb.comp_id	= tag.comp_id AND
					tb.ag_id	= tag.ag_id
			INNER JOIN tbUsers4BranchFilter			tubf		WITH (NOLOCK)
				ON	tubf.comp_id	= @comp_id		AND
					tubf.bra_id		= tb.bra_id		AND
					tubf.[user_id]	= @user_id




	SELECT Distinct
				tag.ag_id						[id],
				ag_desc							[desc]
		from		tbAccountantGroup tag	WITH (NOLOCK)
		INNER JOIN @tblBranch tmo
			ON tmo.ag_id = tag.ag_id
		where		comp_id = @comp_id
		Order By	[desc]


END






GO






