CREATE PROCEDURE [dbo].[spAccountantGroup_getComboByProfile]
(
	@comp_id			INT,
	@bra_id				INT,
	@user_id			INT
)
AS

BEGIN

	SET  NOCOUNT ON

	-- -------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@bra_id		INT,
			@user_id	INT
		SELECT
			@comp_id	=1,
			@bra_id		=1,
			@user_id	=1
	*/
	-- -------------------------------------------------------


	DECLARE @tblBranch TABLE(bra_id INT PRIMARY KEY, ag_id INT)
	INSERT INTO @tblBranch(bra_id, ag_id)
		SELECT DISTINCT tb.bra_id , tag.ag_id
			FROM tbAccountantGroup	tag
			INNER JOIN tbBranch		tb
				ON	tb.comp_id	= tag.comp_id AND
					tb.ag_id	= tag.ag_id
			INNER JOIN tbUsers4BranchFilter			tubf		WITH (NOLOCK)
				ON	tubf.comp_id	= @comp_id		AND
					tubf.bra_id		= tb.bra_id		AND
					tubf.[user_id]	= @user_id



	SELECT distinct
		tag.ag_id							[id],
		tag.ag_desc							[desc]


		FROM tbUserCompanyProfile				tucp		WITH (NOLOCK)

		INNER JOIN tbAccountantGroupByProfile	tagbp		WITH (NOLOCK)
		ON	tagbp.comp_id = tucp.comp_id
		AND tagbp.prof_id = tucp.prof_id

		INNER JOIN tbAccountantGroup			tag			WITH (NOLOCK)
		ON	tag.comp_id = tagbp.comp_id
		AND tag.ag_id	= tagbp.ag_id



		INNER JOIN @tblBranch					tmp
			ON	tmp.bra_id	= tucp.bra_id	AND
				tmp.ag_id	= tag.ag_id

		WHERE	tucp.comp_id	=	@comp_id
		AND		tucp.bra_id		=	@bra_id
		AND		tucp.[user_id]	=	@user_id

END
GO





create  PROCEDURE [dbo].[spAccountantMovementsTMP_deleteData]
(
		@atcmTmp_id			int
)
as
set nocount on


Delete	dbo.tbAccountantMovementsTMP

where	atcmTmp_id			= @atcmTmp_id






