CREATE PROCEDURE [dbo].[spAccountantPeriod_checkBasicData]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			INT
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	/*
	DECLARE @comp_id		INT
	DECLARE @bra_id			INT
	DECLARE @lang_id		INT
	SELECT	@comp_id		=3,
			@bra_id			=1,
			@lang_id		=2
	DROP TABLE #tmpData
	*/

	CREATE TABLE #tmpData ( [check] INT )

	/*
	por cada control que se realice al comienzo de las páginas y no esté correcto,
	hay que hacer un insert en la temporal creada arriba
	con el valor correspondiente al table_id de la tabla tbSysTables (siempre deberá ser un valor negativo)
	y este valor está relacionado con la tabla tbSysHelpPages que si tendrá el mensaje de error
	a mostrar al usuario
	*/

	if NOT EXISTS (select 1 FROM tbAccountantPeriod	WHERE comp_id = @comp_id)														INSERT INTO #tmpData ([check]) VALUES (0)
	if     EXISTS (select 1 FROM tbBranch tb    	WHERE comp_id = @comp_id AND tb.bra_id = @bra_id AND ISNULL(tb.ag_id,-1) = -1)	INSERT INTO #tmpData ([check]) VALUES (-1)
	if NOT EXISTS (select 1 FROM tbAccountantGroup 	WHERE comp_id = @comp_id)														INSERT INTO #tmpData ([check]) VALUES (-2)
	IF NOT EXISTS (SELECT 1 FROM tbAccountantPeriod WHERE comp_id = @comp_id AND ap_blocked = 'True' AND ap_closed = 'False')		INSERT INTO #tmpData ([check]) VALUES (-3)


	SELECT	tut.utexts_desc, tut.utexts_id
	FROM	tbsysUniqueTexts tut
	WHERE	tut.lang_id			= @lang_id
	AND		tut.utexts_id		IN(4, 5, 6)
	AND		EXISTS(SELECT 1 FROM #tmpData)

	UNION

	SELECT	cast(thp.hp_desc AS NVARCHAR(MAX)), thp.page_id
	FROM	tbsysHelpPages			thp
			INNER JOIN #tmpData		td
			ON	td.[check]		= thp.table_id
	WHERE	thp.page_id			= -100080 --este valor está en duro e indica la funcionalidad que se está chequeando
	AND		thp.lang_id			= @lang_id

	ORDER BY 2 DESC


END
GO










CREATE PROCEDURE [dbo].[spAccountantPeriod_getCombo]
(
	@comp_id				int,
	@state					int
)
AS

/*
declare @comp_id			int,
		@state				int
select  @comp_id			=1,
		@state				=0
*/

select	ap_desc		[desc],
		ap_id		[ID]

from	dbo.tbAccountantPeriod

where	comp_id		= @comp_id
and	    (
			@state  = 0															or
			(@state = 1 and ap_closed = 'true')									or
			(@state = 2 and ap_blocked = 'true'		and ap_closed = 'false')	or
			(@state = 3 and ap_blocked = 'false'	and ap_closed = 'false')
		)

order by ap_lastdate Desc -- [ap_closed], ap_desc  ,ap_lastdate asc
--order by [ap_closed], ap_desc

















GO










CREATE PROCEDURE [dbo].[spAccountantPeriod_getComboByAccountantGroup]
(
	@comp_id				INT,
	@bra_id					INT,
	@ag_id					INT
)
AS


--------------------------------------------------------------------------------
/*
declare @comp_id			INT,
		@bra_id				INT,
		@ag_id				INT


select  @comp_id			= 1,
		@bra_id				= 1,
		@ag_id				= 10
*/
-------------------------------------------------------------------------------
BEGIN




	IF EXISTS(
				select
					tap.ap_desc		[desc],
					tap.ap_id		[ID]
					FROM 	dbo.tbAccountantPeriod						tap			WITH (NOLOCK)
					INNER JOIN tbAccountantPeriodByBranch				tapbb		WITH (NOLOCK)
					ON	tapbb.comp_id	= tap.comp_id	AND
						tapbb.ap_id		= tap.ap_id
					INNER JOIN tbBranch									tb			WITH (NOLOCK)
					ON	tb.comp_id		= tapbb.comp_id	AND
						tb.bra_id		= tapbb.bra_id
					where	tap.comp_id	=  @comp_id		AND
							tb.ag_id	=  @ag_id


				)
		BEGIN

			SELECT distinct
				tap.ap_desc		[desc],
				tap.ap_id		[ID]
				FROM 	dbo.tbAccountantPeriod						tap			WITH (NOLOCK)
				INNER JOIN tbAccountantPeriodByBranch				tapbb		WITH (NOLOCK)
				ON	tapbb.comp_id	= tap.comp_id	AND
					tapbb.ap_id		= tap.ap_id
				INNER JOIN tbBranch									tb			WITH (NOLOCK)
				ON	tb.comp_id		= tapbb.comp_id	AND
					tb.bra_id		= tapbb.bra_id
				where	tap.comp_id	=  @comp_id		AND
						tb.ag_id	=  @ag_id

				--ORDER BY tap.ap_desc
				order by tap.ap_desc desc

		END
	ELSE
		BEGIN

			SELECT
				tap.ap_desc		[desc],
				tap.ap_id		[ID]
				FROM 	dbo.tbAccountantPeriod						tap			WITH (NOLOCK)
				WHERE tap.comp_id	=  @comp_id
				--ORDER BY tap.ap_desc
				order by tap.ap_desc Desc

		END


END













GO










