CREATE PROCEDURE [dbo].[spAccountantPeriod_validateData]
(
	@comp_id			int,
	@lang_id			int,
	@ap_id				int,
	@ap_firstdate		datetime,
	@ap_lastdate		datetime,
	@errormessage		varchar(200) output
)
AS

BEGIN

	set nocount ON

	-- -------------------------------------------------
	-- Test
	-- -------------------------------------------------
	/*
	declare 	@comp_id			int,
		@lang_id			int,
		@ap_id				int,
		@ap_firstdate		datetime,
		@ap_lastdate		datetime,
		@errormessage		varchar(200)
	select 	@comp_id			=1,
		@lang_id			=2,
		@ap_id				=-1,
		@ap_firstdate		='2001-01-01',
		@ap_lastdate		='2001-02-02'
		--@errormessage		varchar(200) output
	drop table [#tmp]
	*/
	-- -------------------------------------------------

	declare @return_value int
	set @return_value = 0
	set @errormessage = ''



	--drop table #tmp

	--crear tabla temporal para descripciones de posibles errores
	CREATE TABLE #tmp (	[field_id]				[int]			null,
						[type_id]				[int]			null,
						[type_desc]				[varchar](200)	null,
						[name_desc]				[varchar](200)	null,
						[name_join]				[varchar](200)	null,
						[name_combo]			[varchar](200)	null,
						[name_column]			[varchar](200)	null,
						[name_comboact]			[varchar](200)	null,
						[name_errormessage]		[varchar](200)	null,
						[name_errormessage2]	[varchar](200)	null,
						[ctrl_id]				[int]			null,
						[ctrl_desc]				[varchar](200)	null,
						[prop_id]				[int]			null,
						[prop_desc]				[varchar](200)	null)

	--select * from [#tmp]

	--recuperar las descripciones de los posibles errores que pudieran ocurrir en la validación
	INSERT #tmp
	(	[field_id],[type_id],[type_desc],[name_desc],
		[name_join],[name_combo],[name_column],[name_comboact],[name_errormessage], [name_errormessage2],
		[ctrl_id],[ctrl_desc],[prop_id],[prop_desc])
			exec dbo.spSysNames_getDataByTab @lang_id, 5 , -1 ,-1



	--validar que la fecha fin sea mayor que la fecha inicio
	if @ap_lastdate < @ap_firstdate

		begin
			set	@errormessage = (select [name_errormessage] from #tmp where ctrl_id = 287)
			set @return_value = 287
		end

	else

		begin

			--validar que el período a insertar o modificar no se solape con las fechas de ningún otro
			--período existente
			declare @cap_firstdate	datetime
			declare @cap_lastdate	datetime

			declare cursor_APvD_datos CURSOR LOCAL FAST_FORWARD for
				select	ap_firstdate,
						ap_lastdate
				from	tbAccountantPeriod
				where	comp_id		=	@comp_id
				and		ap_id		<>	@ap_id
				AND		ISNULL(ap_noCheckOverDates,'False') = 'False'

			open cursor_APvD_datos

			FETCH NEXT FROM cursor_APvD_datos INTO @cap_firstdate, @cap_lastdate

			WHILE @@FETCH_STATUS = 0
			BEGIN



				if (@ap_firstdate >= @cap_firstdate and @ap_firstdate <= @cap_lastdate) or
					(@ap_lastdate >= @cap_firstdate and @ap_lastdate <= @cap_lastdate)
				begin

					set	@errormessage = (select [name_errormessage] from #tmp where ctrl_id = 288)
					set @return_value = 288

					break
				end

				FETCH NEXT FROM cursor_APvD_datos INTO @cap_firstdate, @cap_lastdate

			END

			CLOSE cursor_APvD_datos
			DEALLOCATE cursor_APvD_datos

		end

	return @return_value
	--select @return_value

END
GO





CREATE PROCEDURE [dbo].[spAccountantrptFilters_checkBasicData]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	/*
	DECLARE @comp_id		INT
	DECLARE @bra_id			INT
	DECLARE @lang_id		INT
	SELECT	@comp_id		=3,
			@bra_id			=1,
			@lang_id		=2
	DROP TABLE #tmpData
	*/

	CREATE TABLE #tmpData ( [check] INT )

	/*
	por cada control que se realice al comienzo de las páginas y no esté correcto,
	hay que hacer un insert en la temporal creada arriba
	con el valor correspondiente al table_id de la tabla tbSysTables (siempre deberá ser un valor negativo)
	y este valor está relacionado con la tabla tbSysHelpPages que si tendrá el mensaje de error
	a mostrar al usuario
	*/
	IF NOT EXISTS (SELECT 1 FROM tbAccountant		WHERE comp_id = @comp_id)														INSERT INTO #tmpData ([check]) VALUES (0)
	if NOT EXISTS (select 1 FROM tbAccountantPeriod	WHERE comp_id = @comp_id)														INSERT INTO #tmpData ([check]) VALUES (-1)
	if NOT EXISTS (select 1 FROM tbAccountantGroup 	WHERE comp_id = @comp_id)														INSERT INTO #tmpData ([check]) VALUES (-2)


	SELECT	tut.utexts_desc, tut.utexts_id
	FROM	tbsysUniqueTexts tut
	WHERE	tut.lang_id			= @lang_id
	AND		tut.utexts_id		IN(4, 5, 6)
	AND		EXISTS(SELECT 1 FROM #tmpData)

	UNION

	SELECT	cast(thp.hp_desc AS NVARCHAR(MAX)), thp.page_id
	FROM	tbsysHelpPages			thp
			INNER JOIN #tmpData		td
			ON	td.[check]		= thp.table_id
	WHERE	thp.page_id			= -100090 --este valor está en duro e indica la funcionalidad que se está chequeando
	AND		thp.lang_id			= @lang_id

	ORDER BY 2 DESC


END
GO







