CREATE PROCEDURE [dbo].[spAccountantStatusToDate_getReport]
(

   @comp_id					INT,
   @lang_id					INT,
   @page_id					INT,

   @selection_id			INT,
   @dateto					DATETIME,
   @optiondate				INT, --1:fecha del doc , 2 : fecha contable solo para proveedores
   @custsupp				INT,
   @sm_id					INT,
   @dl_id					INT,
   @ck_id					INT,
   @ss_id					INT,
   @country_id				INT,
   @state_id				INT,
   @curr_id					int,
   @orderby					int,
   @balancefrom				BIGINT,
   @balanceto				BIGINT,
   @bra_id					INT,
   @brag_id					INT,
   @OptionOnlyAccounting	INT, -- -1:Todos , 1: Incluir sólo comprobantes contables.
   @ispurchase				BIT,
   @user_id					INT,
   @intBranch4Lang			int
)
AS


BEGIN


	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------





	 --------------------------------------------------------------------------------
	 -- PARAMETROS PARA PRUEBAS -----------------------------------------------------
	 --------------------------------------------------------------------------------
	/*
	 declare
		   @comp_id					INT,
		   @lang_id					INT,
		   @page_id					INT,

		   @selection_id			INT,
		   @dateto					DATETIME,
		   @optiondate				INT, --1:fecha del doc , 2 : fecha contable solo para proveedores
		   @custsupp				INT,
		   @sm_id					INT,
		   @dl_id					INT,
		   @ck_id					INT,
		   @ss_id					INT,
		   @country_id				INT,
		   @state_id				INT,
		   @curr_id					int,
		   @orderby					int,
		   @balancefrom				INT,
		   @balanceto				INT,
		   @bra_id					INT,
		   @brag_id					INT,
		   @OptionOnlyAccounting	INT, -- -1:Todos , 1: Incluir sólo comprobantes contables.
		   @ispurchase				BIT,
		   @user_id					INT,
		   @intBranch4Lang			INT

	 select
			@comp_id   =1,
			@lang_id   =2,
			@page_id   =10077,

			@selection_id  =-1,
			@dateto    ='9999-12-31',
			@custsupp   =-1,
			@sm_id    =-1,
			@dl_id    =-1,
			@ck_id    =-1,
			@bra_id    = 1,
			@country_id   =-1,
			@state_id   =-1,
			@ss_id    =-1,
			@ispurchase   ='false',
			@curr_id   = 1,
			@balancefrom  ='-9999999',
			@balanceto   ='99999999',
			@orderby   = 1,
			@user_id   = 3,
			@brag_id   = 4,
			@OptionOnlyAccounting = -1,
			@optiondate = 1

	 DROP TABLE #tmpSelect
	--DROP TABLE #tmpSelectP
	*/
	 --------------------------------------------------------------------------------



	set @dateto  = dbo.fnGetEnd_or_BeginOfDate(@dateto,'true')

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT bra_id
			FROM tbBranchGroupDetail tbgd
			WHERE tbgd.brag_id = @brag_id



	 DECLARE @fun_id INT

	 SET  @fun_id = 1

	  -- Toma la Fecha de Procesamiento de la sucursal y la moneda.
	  DECLARE @bra_proccesingdate DATETIME
	  DECLARE @bra_curr_id  INT
	  DECLARE @bitAllBranchOfCustomers AS BIT
	  DECLARE @bitAllBranchOfSuppliers AS BIT
	  SELECT  @bra_proccesingdate = tb.bra_processingDate,
			  @bra_curr_id     = tb.curr_id,
			  @bitAllBranchOfCustomers = isnull(tb.bra_CollectionOfAllBranches,'False'),
			  @bitAllBranchOfSuppliers = isnull(tb.bra_PaymentsOfAllBranches,'false')

		   FROM   tbBranch           tb

		   WHERE tb.comp_id = @comp_id
		   AND  tb.bra_id = @bra_id






	IF @ispurchase = 'False'

	BEGIN  /* estado de saldo a fecha de clientes */

		select convert(varchar,c.cust_id)						[ID],
		  c.cust_name											[Name],
		  sum((ct_Atotal - ct_aAdjust) * vwct.PlusOrMinus)		[ct_total],
		  cr2.curr_desc											[curr_desc],
		  ts.sm_name											[sm_name],
		  isnull(c.cust_phone1,'')								[cust_phone1],
		  isnull(c.cust_email4Payments,'')						[cust_email4Payments],
		  c.cust_taxNumber										[cust_taxNumber]

		INTO #tmpSelect

		from dbo.tbCommercialTransactions      ct  WITH (NOLOCK)

		  INNER JOIN @tblBranchs        tmp
		  ON tmp.bra_id   = ct.bra_id

		  INNER JOIN tbBranch         tb  WITH (NOLOCK)
		  ON tb.comp_id   = ct.comp_id
		  AND tb.bra_id   = ct.bra_id

		  inner join dbo.vwCommercialTransactions_forSales vwct WITH (NOLOCK)
		  on  ct.comp_id   = vwct.comp_id
		  and ct.bra_id   = vwct.bra_id
		  and ct.ct_transaction = vwct.ct_transaction


		  inner join dbo.tbCustomer       c  WITH (NOLOCK)
		  on c.comp_id  = ct.comp_id
		  and c.cust_id  = ct.cust_id
		  and (@ck_id   = -1 or c.ck_id   = @ck_id)
		  and (@dl_id   = -1 or c.dl_id   = @dl_id)
		  and (@ck_id   = -1 or c.ck_id   = @ck_id)
		  and (@country_id = -1 or c.country_id = @country_id)
		  and (@state_id  = -1 or c.state_id  = @state_id)
		  and (@ss_id   = -1 or c.ss_id   = @ss_id)


		  left join dbo.tbSalesman       sm  WITH (NOLOCK)
		  on  sm.comp_id    = c.comp_id
		  and sm.sm_id    = c.sm_id

		  LEFT join dbo.tbSalesTerms       st  WITH (NOLOCK)
		  on  st.comp_id    = ct.comp_id
		  and st.st_id    = ct.st_id

		  LEFT join dbo.tbsysCurrency       cr1  WITH (NOLOCK)
		  on  cr1.curr_id    = ct.curr_id_transaction

		  INNER join dbo.tbsysCurrency      cr2  WITH (NOLOCK)
		  on  cr2.curr_id    = ct.ct_ACurrency

		  inner join tbUsers4BranchFilter      vubf WITH (NOLOCK)
		  ON  vubf.comp_id   = CT.comp_id
		  AND vubf.bra_id    = CT.bra_id
		  AND vubf.[user_id]   = @user_id

		  inner JOIN tbsysDocuments       td  WITH (NOLOCK)
		  ON td.sd_id    = ct.sd_id
		  and td.sd_isPurchase  = @ispurchase

		  left JOIN tbSalesman        ts  WITH (NOLOCK)
		  ON  ts.comp_id    = c.comp_id
		  AND ts.sm_id    = c.sm_id



		Where			ct.comp_id    =  @comp_id
				AND		vwct.sd_isInBalance = 'True'
				AND		ct.sd_id NOT IN (43,44)	-- MOS 02-2022: las Nd y Nc x Dif de Cambio NO deben tomarse en cuenta para calculo de saldos a fecha.
				and		cr2.curr_id   =  @curr_id
				AND  CASE
						WHEN @custsupp = -1   THEN 1
						WHEN ct.cust_id = @custsupp THEN 1
						ELSE 0
					 END = 1
		  --(@custsupp = -1 or  ct.cust_id  = @custsupp)
				AND   ct.ct_date  <  @dateto
				AND  CASE
						   WHEN @selection_id = -1   THEN 1
						   WHEN ct.sd_id  = @selection_id THEN 1
						   ELSE           0
					 END  = 1
		  --(@selection_id =  -1    or ct.sd_id  = @selection_id)
				and  CASE
						   WHEN @sm_id    =  -1   THEN 1
						   WHEN c.sm_id   = @sm_id   THEN 1
						   WHEN c.sm_id IS NULL AND c.sm_id = @sm_id THEN 1 -- MIERDA, lo dejo x las dudas
						   ELSE            0
					 END = 1
		  --(@sm_id   =  -1    or (c.sm_id   = @sm_id OR (c.sm_id IS NULL AND c.sm_id = @sm_id)))
				AND  IsNull(c.cust_judMan,'False')   = 'False'
				AND  IsNull(c.cust_4InitialValues,'False') = 'False'
		--AND  (fcgbs.cust_credit_balance BETWEEN @balancefrom AND @balanceto) -- MOS 01-2016, reemplazado x having

			  group by  c.cust_id,
				  c.cust_name,
				  td.sd_isInBalance,
				  cr2.curr_desc,
				  ts.sm_name,
				  c.cust_phone1,
				  c.cust_email4Payments,
				  c.cust_taxNumber

			  HAVING sum((ct_Atotal - ct_aAdjust) * vwct.PlusOrMinus)  BETWEEN @balancefrom AND @balanceto


	 --Ordena por cliente o por saldo 1 - cliente , 2 - saldo
	 IF @orderby = 1
	  BEGIN
	   SELECT * FROM #tmpSelect tmp
		WHERE convert(decimal(19,1),ct_total) <> 0
		ORDER BY tmp.[Name],tmp.[ct_total] asc
	  END
	 ELSE
	  IF @orderby = 2
	   BEGIN
		SELECT * FROM #tmpSelect tmp
		 WHERE convert(decimal(19,1),ct_total) <> 0
		 ORDER BY tmp.[ct_total] asc,tmp.[Name]
	   END


	  --order by [ct_total] asc,c.cust_name







	  --SELECT * FROM  #tmpSelect WHERE convert(decimal(19,1),ct_total) <> 0

	END

 ELSE

	BEGIN  /* estado de saldo a fecha de proveedores */



		   select
			 convert(varchar,s.supp_id)               [ID],
			 s.supp_name                   [Name],
			 CASE WHEN td.sd_isInBalance = 'true' THEN
			  sum((ct_Atotal - ct_aAdjust) * vwct.PlusOrMinus)
			  ELSE 0 END					[ct_total],
			 cr2.curr_desc                  [curr_desc]

		   INTO #tmpSelectP
		   from dbo.tbCommercialTransactions       ct   WITH (NOLOCK)

			 INNER JOIN @tblBranchs         tmp
			 ON tmp.bra_id = ct.bra_id


			 INNER JOIN tbBranch tb   WITH (NOLOCK)
			 ON tb.comp_id = ct.comp_id AND
			  tb.bra_id = ct.bra_id

			 inner join dbo.vwCommercialTransactions_forPurchase  vwct  WITH (NOLOCK)
			 on  ct.comp_id   = vwct.comp_id
			 and ct.bra_id   = vwct.bra_id
			 and ct.ct_transaction = vwct.ct_transaction


			 inner join tbUsers4BranchFilter      vubf WITH (NOLOCK)
			 ON  vubf.comp_id   = CT.comp_id
			 AND vubf.bra_id    = CT.bra_id
			 AND vubf.[user_id]   = @user_id

			 left join dbo.tbSupplier        s   WITH (NOLOCK)
			 on ct.comp_id  = s.comp_id
			 and ct.supp_id  = s.supp_id
			 and (@country_id = -1 or s.country_id = @country_id)
			 and (@state_id  = -1 or s.state_id   = @state_id)

			 --left join dbo.tbSalesman        sm   WITH (NOLOCK)
			 --on  ct.comp_id   = sm.comp_id
			 --and ct.sm_id   = sm.sm_id

			 --left join dbo.tbSalesTerms   st        WITH (NOLOCK)
			 --on  ct.comp_id   = st.comp_id
			 --and ct.st_id   = st.st_id

			 left join dbo.tbsysCurrency        cr1   WITH (NOLOCK)
			 on ct.curr_id_transaction = cr1.curr_id

			 left join dbo.tbsysCurrency        cr2      WITH (NOLOCK)
			 on ct.ct_ACurrency   = cr2.curr_id

			 left JOIN tbsysDocuments       td    WITH (NOLOCK)
			 ON td.sd_id   = ct.sd_id
			 and td.sd_isPurchase = @ispurchase

		   Where ct.comp_id  =  @comp_id
		   --AND   (ct.bra_id  =  @bra_id OR @bitAllBranchOfSuppliers = 'True')
		   AND  vwct.sd_isAnnulment = 'False'
		   AND  (@custsupp  =  -1    or ct.supp_id = @custsupp)
		   --AND  ct.ct_date  <=  @dateto								-- MOS 06-2016  <= x <
		   and  (@selection_id =  -1    or ct.sd_id = @selection_id)
		   AND  @curr_id  = ct.ct_ACurrency  -- MOS

		   AND  ISNULL(ct.supp_id,-1) <> ISNULL(tb.bra_PaymentSupp_Id,-2)  -- que no sean proveedores de Otros Pagos

		   AND  CASE
						WHEN @optiondate = 1	AND ct.ct_date    <=  @dateto THEN 1  -- fecha del doc
						WHEN @optiondate = 2	AND ct.ct_taxDate <=  @dateto THEN 1  -- fecha contable
						ELSE 0
				END = 1

			AND
				CASE
					WHEN @OptionOnlyAccounting = -1 THEN 1

					-- Solo cpmprobantes contablkes
					WHEN @OptionOnlyAccounting =  1 AND ct.sd_id IN (101,103,104,106,125,130,131,140,141,142,143,144,151,153,154,156,161,163,164,166,180,190) THEN 1  -- Solo comprobantes contables
					ELSE 0
				END = 1


		   group by  s.supp_id,
			   s.supp_name ,
			   td.sd_isInBalance,
			   cr2.curr_desc

		--Ordena por proveedor o por saldo 1 - proveedor , 2 - saldo
		 IF @orderby = 1
		  BEGIN
		   SELECT * FROM #tmpSelectP tmp
		   WHERE convert(decimal(19,1),ct_total) <> 0
		   ORDER BY tmp.[Name],tmp.[ct_total] asc
		  END
		 ELSE
		  IF @orderby = 2
		   BEGIN
			SELECT * FROM #tmpSelectP tmp
			WHERE convert(decimal(19,1),ct_total) <> 0
			ORDER BY tmp.[ct_total] asc,tmp.[Name]
		   END



	END



















 DECLARE @is BIT
 set @is = case WHEN @ispurchase = 'true' THEN 0 ELSE 1 END




 exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id, @is





  /* devolución de parámetros recibidos */
  DECLARE @related_page_id INT
  SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

  /*************************************************************************************************************/   /* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros   */   /*     SELECT t.ctrl_id, t.[text_de
sc]
    FROM [tbsysTexts]    t
      inner join [tbsysControls] c
      on c.[ctrl_id] = t.[ctrl_id]
    where t.[lang_id] = @lang_id
    and  t.[page_id] = @related_page_id
    and  t.[type_id] = 1
  */
  /*************************************************************************************************************/




  SELECT
    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 398
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id) [params1],

    CASE @selection_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  tsov.optval_desc
       FROM dbo.tbsysOptionsValues tsov

       WHERE tsov.optval_id  = @selection_id
       AND  tsov.lang_id  = @lang_id
       AND  tsov.optval_class =  6 )
    END  [params2],

    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 384
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params3],
          @dateto [DateParams1],
    --convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))  [params4],

    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 402
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = @is )[params4],

    CASE @custsupp WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id = @lang_id
       AND  tut.utexts_id = 1)
         ELSE
      Case @ispurchase When 'True' THEN
       (Select ts.supp_name
       FROM tbSupplier ts
       WHERE Ts.comp_id = @comp_id
       AND  ts.supp_id = @custsupp)

     ELSE
       (Select Tc.cust_name
       FROM tbCustomer tc
       WHERE Tc.comp_id = @comp_id
       AND  Tc.cust_id = @custsupp)
      End
    END  [params5] ,

   (SELECT tswn.word_desc
     FROM [tbsysTextsNew] t
     INNER JOIN tbSysWordsNew tswn
     ON tswn.lang_id = @lang_id
     and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 172
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = @fun_id)  [params6],

    CASE @sm_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id = @lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  ts.sm_name
       FROM tbSalesman ts
       WHERE ts.comp_id = @comp_id AND ts.sm_id = @sm_id)
    END  [params7] ,

    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 170
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params8],
    CASE @dl_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  td.dl_name
       FROM tbDelivery td
       WHERE td.comp_id = @comp_id AND td.dl_id = @dl_id)
     END                    [params9],

   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 372
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params10],
    CASE @ck_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  tck.ck_name
       FROM tbCustomerKind tck
       WHERE Tck.comp_id = @comp_id AND Tck.ck_id = @ck_id)
    END  [params11] ,



  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 57
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params12],
    CASE @country_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  Tc.country_desc
       FROM tbsysCountry tc
       WHERE tc.country_id= @country_id)
    END  [params13],

    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   WHERE t.ctrl_id = 59
   --AND t.[lang_id] = @lang_id
   and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params14],
   CASE @state_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  ts.state_desc
       FROM tbsysState ts
       WHERE Ts.state_id= @state_id)
    END  [params15],

  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   WHERE t.ctrl_id = 397
   --AND t.[lang_id] = @lang_id
   and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params16],
   CASE @ss_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  tss.ss_desc
       FROM tbSaleSector tss
       WHERE tss.ss_id= @ss_id)
    END  [params17],

     (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   WHERE t.ctrl_id = 106
   --AND t.[lang_id] = @lang_id
   and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params18],
   CASE @curr_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  tc.curr_desc
       FROM tbsysCurrency tc
       WHERE tc.curr_id = @curr_id)
    END  [params19],



 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   WHERE t.ctrl_id = 1467
   --AND t.[lang_id] = @lang_id
   and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params20],

   CASE @ispurchase WHEN 'false' THEN
    (SELECT  tov.optval_desc
     FROM tbsysOptionsValues tov
     WHERE tov.lang_id=@lang_id AND tov.optval_id =@orderby and tov.optval_class=302 )
   else

    (SELECT  tov.optval_desc
     FROM tbsysOptionsValues tov
     WHERE tov.lang_id=@lang_id AND tov.optval_id =@orderby and tov.optval_class=303 )

   end [params21],


   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   WHERE t.ctrl_id = 401
   --AND t.[lang_id] = @lang_id
   and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params22],

   CONVERT(NVARCHAR,@balancefrom) + ' - ' + CONVERT(NVARCHAR,@balanceto)    [params23],

  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   WHERE t.ctrl_id = 639
   --AND t.[lang_id] = @lang_id
   and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params24],
   CASE @brag_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  tbg.brag_desc
       FROM tbBranchGroup tbg
       WHERE tbg.brag_id = @brag_id)
    END  [params25],

     (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   WHERE t.ctrl_id = 4398
   --AND t.[lang_id] = @lang_id
   and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params26],

   CASE @optiondate WHEN -1 THEN
   (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)

   else

    (SELECT  tov.optval_desc
     FROM tbsysOptionsValues tov
     WHERE tov.lang_id=@lang_id AND tov.optval_id =@optiondate and tov.optval_class=555 )

   end [params27],

    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   WHERE t.ctrl_id = 4874
   --AND t.[lang_id] = @lang_id
   and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)  [params28],
   CASE @OptionOnlyAccounting WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
       (SELECT  tsov.optval_desc
       FROM dbo.tbsysOptionsValues tsov

       WHERE tsov.optval_id		= @OptionOnlyAccounting
       AND  tsov.lang_id		= @lang_id
       AND  tsov.optval_class	=  717 )
    END																				[params29]










END





GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2009
-- Description:	Si el 1er parametro es Negativo
--				Pone el Valor Absoluto en el 2do
--				y 0 en el 1ro
-- =============================================
CREATE PROCEDURE spAccountCreditDebitExchange
	@decValue1		 Decimal(19,5) OutPut	,
	@decValue2		 Decimal(19,5) OutPut
AS
BEGIN
	If @decValue1 < 0
		Begin
			Set @decValue2	 = Abs(@decValue1)
			Set @decValue1	 = 0
		End
END
GO







CREATE PROCEDURE [dbo].[spAccounting_checkBasicData]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


	SET NOCOUNT ON


	/*
	DECLARE @comp_id		INT
	DECLARE @bra_id			INT
	DECLARE @lang_id		INT
	SELECT	@comp_id		=3,
			@bra_id			=1,
			@lang_id		=2
	DROP TABLE #tmpData
	*/

	CREATE TABLE #tmpData ( [check] INT )

	/*
	por cada control que se realice al comienzo de las páginas y no esté correcto,
	hay que hacer un insert en la temporal creada arriba
	con el valor correspondiente al table_id de la tabla tbSysTables (siempre deberá ser un valor negativo)
	y este valor está relacionado con la tabla tbSysHelpPages que si tendrá el mensaje de error
	a mostrar al usuario
	*/


	if not exists (select 1 FROM tbAccountantPeriod	WHERE comp_id = @comp_id)														INSERT INTO #tmpData ([check]) VALUES (-1)
	if     exists (select 1 FROM tbBranch tb    	WHERE comp_id = @comp_id AND tb.bra_id = @bra_id AND ISNULL(tb.ag_id,-1) = -1)	INSERT INTO #tmpData ([check]) VALUES (-2)
	if not exists (select 1 FROM tbAccountantGroup 	WHERE comp_id = @comp_id)														INSERT INTO #tmpData ([check]) VALUES (-3)




	SELECT	tut.utexts_desc, tut.utexts_id
	FROM	tbsysUniqueTexts tut
	WHERE	tut.lang_id			= @lang_id
	AND		tut.utexts_id		IN(4, 5, 6)
	AND		EXISTS(SELECT 1 FROM #tmpData)

	UNION

	SELECT	cast(thp.hp_desc AS NVARCHAR(MAX)), thp.page_id
	FROM	tbsysHelpPages			thp
			INNER JOIN #tmpData		td
			ON	td.[check]		= thp.table_id
	WHERE	thp.page_id			= -100060 --este valor está en duro e indica la funcionalidad que se está chequeando
	AND		thp.lang_id			= @lang_id

	ORDER BY 2 DESC


END
GO






-- =============================================
-- Author:
--              MOS  06-3-08
-- Create date: <Create Date,,>
-- =============================================

CREATE  PROCEDURE [dbo].[spAccounting_deleteData]
(
	@comp_id					INT,
	@hacc_transaction			int,
	@dacc_guid					UNIQUEIDENTIFIER,
	@user_id					INT
)
as
set nocount OFF

/*
declare		@hacc_transaction			int,
			@dacc_guid					uniqueidentifier,
			@comp_id					int
*/


BEGIN TRANSACTION
BEGIN TRY



		-- ------------------------------------------------------------
		-- Inserta el HISTORICO de actualizaciones
		-- ------------------------------------------------------------
		INSERT INTO tbAccountTransactionHeadHistory
		(
			comp_id,
			bra_id,
			hacc_transaction,
			hacc_detail,
			hacc_date,
			hacc_number,
			hacc_orderPriority,
			ap_id,
			hacc_blocked,
			hacc_closing,
			ag_id,
			hacc_originalNumber,
			hacch_cd,
			hacch_user_id,
			hacch_type
		)
			SELECT 			comp_id,
							bra_id,
							hacc_transaction,
							hacc_detail,
							hacc_date,
							hacc_number,
							hacc_orderPriority,
							ap_id,
							hacc_blocked,
							hacc_closing,
							ag_id,
							hacc_originalNumber,
							GETDATE(),
							@user_id ,
							2
				FROM tbAccountTransactionHead tath		WITH (NOLOCK)
			WHERE	tath.comp_id			= @comp_id AND
					tath.hacc_transaction	= @hacc_transaction

		DECLARE @intLastHistory AS INT = @@IDENTITY

		INSERT INTO tbAccountTransactionDetailHistory
		(
			comp_id,
			hacch_id,
			bra_id,
			hacc_transaction,
			dacc_transaction,
			acc_count_id,
			cc_code,
			dacc_debit,
			dacc_credit,
			[user_id],
			dacc_cd,
			hacc_software,
			ct_transaction,
			dacc_order,
			dacc_2ndCurrencyExchange,
			acc_detail1,
			acc_detail2
		)
		SELECT
			comp_id,
			@intLastHistory,
			bra_id,
			hacc_transaction,
			dacc_transaction,
			acc_count_id,
			cc_code,
			dacc_debit,
			dacc_credit,
			[user_id],
			dacc_cd,
			hacc_software,
			ct_transaction,
			dacc_order,
			dacc_2ndCurrencyExchange,
			acc_detail1,
			acc_detail2
			FROM tbAccountTransactionDetail tatdh		WITH (NOLOCK)
		WHERE	tatdh.comp_id			= @comp_id					AND
				tatdh.hacc_transaction	= @hacc_transaction

		-- ------------------------------------------------------------



	exec dbo.spAccountTransactionDetailTmp_deleteAllData	@dacc_guid



	if @hacc_transaction <> -1
		BEGIN
			exec dbo.spAccountTransactionDetail_deleteAllData	@hacc_transaction		-- SIN compañia, son unos reverendos HDP !!!!
			exec dbo.spAccountTransactionHead_deleteData		@hacc_transaction
		END



	COMMIT TRANSACTION

END
TRY BEGIN CATCH
	ROLLBACK TRANSACTION
END CATCH






GO






