CREATE PROCEDURE [dbo].[spAccounting_getDataById]
(
	@comp_id				INT,
	@hacc_transaction		int,
	@dacc_guid				uniqueidentifier
)
as
set nocount on

/*
declare @hacc_transaction		int ,
		@dacc_guid				uniqueidentifier
select  @hacc_transaction		= 34,
		@dacc_guid				='1c3569cb-a508-4a92-b0ba-0ccd0ac83b2b'

declare @datetime	datetime
select	@datetime = getdate()
*/


--Controlar que el asiento seleccionado no esté siendo editado por otro usuario
IF exists (select TOP 1 1 from dbo.tbAccountTransactionHead where hacc_transaction = @hacc_transaction and hacc_IsEditing = 'False' )

begin

	--recuperar los valores de la cabecera del asiento seleccionado
	exec dbo.spAccountTransactionHead_getDataById @hacc_transaction

	exec dbo.spAccountTransactionHead_updateIsEditing  @comp_id, @hacc_transaction, 'True'
	--actualizar el estado para indicar que el registro está tomado
--	update	dbo.tbAccountTransactionHead
--	set		hacc_IsEditing			= 'True',
--			hacc_IsEditingDateTime	= getdate()
--	where 	hacc_transaction		= @hacc_transaction


	-- declaración de variables para obtener los datos del cursor
	declare	@lcomp_id				int,
			@lbra_id				int,
			@ldacc_guid				uniqueidentifier,
			@ldacc_transaction		int,
			@lacc_count_id			int,
			@lcc_code				int,
			@ldacc_debit			decimal(18,4),
			@ldacc_credit			decimal(18,4),
			@lUSER_ID				int,
			@ldacc_cd				datetime,
			@lhacc_software			bit,
			@lct_transaction		int,
			@lacc_detail1			nvarchar(200),
			@lacc_detail2			nvarchar(200),
			@ldacc_2ndCurrencyExchange		DECIMAL(19,6),
			@lrv							int


	-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
	declare cursor_AgDBI_items CURSOR LOCAL FAST_FORWARD FOR
		select	comp_id,
				bra_id,
				dacc_transaction,
				acc_count_id,
				cc_code,
				dacc_debit,
				dacc_credit,
				user_id,
				dacc_cd,
				hacc_software,
				ct_transaction,
				IsNull(acc_detail1,'')				[acc_detail1],
				IsNull(acc_detail2,'')				[acc_detail2],
				dacc_2ndCurrencyExchange
		from	tbAccountTransactionDetail					WITH (NOLOCK)
			where	hacc_transaction = @hacc_transaction


	open	cursor_AgDBI_items

	-- lectura anticipada del cursor
	FETCH NEXT FROM cursor_AgDBI_items
	into	@lcomp_id,
			@lbra_id,
			@ldacc_transaction,
			@lacc_count_id,
			@lcc_code,
			@ldacc_debit,
			@ldacc_credit,
			@luser_id,
			@ldacc_cd,
			@lhacc_software,
			@lct_transaction,
			@lacc_detail1,
			@lacc_detail2,
			@ldacc_2ndCurrencyExchange


	-- se recorre el cursor hasta el fin del mismo
	WHILE	@@fetch_status = 0
		BEGIN


			-- por cada registro del cursor se realiza el insert en spAccountTransactionDetailTmp
			exec	dbo.spAccountTransactionDetailTmp_insertData
					@lcomp_id ,		@dacc_guid,			@lacc_count_id,
					@lcc_code,		@luser_id ,			@ldacc_debit,
					@ldacc_credit,	@lhacc_software,	@lct_transaction ,
					@ldacc_2ndCurrencyExchange,
					@lacc_detail1,@lacc_detail2 ,
					@return_value	= @lrv output


			-- próxima lectura del cursor
			FETCH NEXT FROM cursor_AgDBI_items
			into	@lcomp_id,
					@lbra_id,
					@ldacc_transaction,
					@lacc_count_id,
					@lcc_code,
					@ldacc_debit,
					@ldacc_credit,
					@luser_id,
					@ldacc_cd,
					@lhacc_software,
					@lct_transaction,
					@lacc_detail1,
					@lacc_detail2,
					@ldacc_2ndCurrencyExchange

		END

	close cursor_AgDBI_items
	deallocate cursor_AgDBI_items


end

else

BEGIN

	exec dbo.spAccountTransactionHead_getDataById @hacc_transaction

END

GO



CREATE procedure [dbo].[spAccounting_getHeaderData]
(
	@comp_id	int
)
AS

BEGIN



	set nocount on

	-- ----------------------------------------
	-- Test
	-- ----------------------------------------
	/*
	declare @comp_id	int
	select	@comp_id	= 1
	*/
	-- ----------------------------------------



	declare @curr_id_1							int,
			@curr_id_2							int


	select	@curr_id_1			=	tc.curr_id,
			@curr_id_2			=	tc.curr_id_2ndCurrency
	from	tbCompany tc	WITH (NOLOCK)
	where	tc.comp_id			=	@comp_id


	select	@curr_id_1																[CurrId1],
			(select	curr_symbol from tbsysCurrency	WITH (NOLOCK) where curr_id = @curr_id_1)		[Currency1],
			1																		[Value1],

			@curr_id_2																[CurrId2],
			(select	curr_symbol from tbsysCurrency	WITH (NOLOCK) where curr_id = @curr_id_2)		[Currency2],
			(dbo.[fnGetExchange](@comp_id, 1, @curr_id_1, @curr_id_2, 0, 0, 0))		[Value2]


END
GO







CREATE PROCEDURE [dbo].[spAccounting_getReport_Balance]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@acc_code_from		varchar(20),
		@acc_code_to		varchar(20),
		@ap_id				int,
		@hacc_date_from		datetime,
		@hacc_date_to		datetime,
		@ag_id				INT,
		@cc_code			INT,
		@bra_id				INT,
		@option				BIT,
		@acc_grouping		INT,		-- -1, ID Grupo de Cuentas Contables
		@acc_Type			INT,  		-- -1,1 Imputables, 2 No Imputables
		@intBranch4Lang		INT,
		@balanceType		INT


)
as


BEGIN

	SET DATEFORMAT 'ymd'
	set nocount on



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------





-- -------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------
/*
	DECLARE	@comp_id			int,
			@lang_id			int,
			@page_id			int,

			@acc_code_from		varchar(20),
			@acc_code_to		varchar(20),
			@ap_id				int,
			@hacc_date_from		datetime,
			@hacc_date_to		Datetime,
			@ag_id				int,
			@cc_code			NVARCHAR(20),
			@bra_id				INT,
			@option				BIT,
			@acc_grouping		int,	---1,Grupo de Cuentas Contables
			@acc_Type			int	,	--1,0 Imputables.1-No Imputables
			@intBranch4Lang		int,
			@balanceType		INT





	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10004,

			@acc_code_from		='1           ',
			@acc_code_to		='999999999999',
			@ap_id				= 36,
			@hacc_date_from		= '2018-07-01',
			@hacc_date_to		= '2019-06-30',
			@ag_id				= -1,
			@cc_code			= -1,
			@bra_id				=  -1,
			@option				= 'False',
			@acc_grouping		= 1,
			@acc_Type			= -1,
			@intBranch4Lang		= 2,
			@balanceType		= 1




	drop table #tmpFrom
	drop table #tmpTo
	DROP TABLE #tmpSaldosCalculados
	DROP TABLE #tmpSaldosCalculadosFinal
*/
---------------------------------------------------------------------

	set	@hacc_date_from = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_from,'False')
	set	@hacc_date_to = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_to,'True')


	DECLARE @datSAPeriodFirstDate	AS DATETIME
	DECLARE @datSAPeriodLastDate	AS DATETIME
	DECLARE @datPeriodFirstDate		AS DATETIME
	DECLARE @datPeriodLastDate		AS DATETIME


	SELECT @datSAPeriodFirstDate = tap.ap_firstdate,
		   @datSAPeriodLastDate  = DATEADD(DAY,-1,@hacc_date_from),		--tap.ap_lastdate
		   @datPeriodFirstDate	 = tap.ap_firstdate,
		   @datPeriodLastDate	 = tap.ap_lastdate
		FROM tbAccountantPeriod tap			WITH (NOLOCK)
		WHERE	tap.comp_id = @comp_id
			AND tap.ap_id	= @ap_id

	SET @datSAPeriodFirstDate = dbo.fnGetEnd_or_BeginOfDate(@datSAPeriodFirstDate,'false')
	SET @datSAPeriodLastDate  = dbo.fnGetEnd_or_BeginOfDate(@datSAPeriodLastDate,'True')
	SET @datPeriodFirstDate   = dbo.fnGetEnd_or_BeginOfDate(@datPeriodFirstDate,'false')
	SET @datPeriodLastDate    = dbo.fnGetEnd_or_BeginOfDate(@datPeriodLastDate,'True')

	DECLARE @decLastIndice AS DECIMAL(19,6) = 1
	SELECT  @decLastIndice = ISNULL(taii.indice,1)
		FROM tbAccountantInflationIndex taii		WITH (NOLOCK)
		WHERE	taii.comp_id	= @comp_id						AND
				taii.[month]	= MONTH(@datPeriodLastDate)	AND
				taii.[year]		= YEAR( @datPeriodLastDate)

	DECLARE @tblCoeficientes TABLE(mes INT,anio INT,coeficiente DECIMAL(25,8))
	INSERT INTO @tblCoeficientes
	(
		mes,
		anio,
		coeficiente
	)
		SELECT	taii.[month],
				taii.[year],
				@decLastIndice / dbo.fnNoZDiv(ISNULL(taii.indice,1))
			FROM tbAccountantInflationIndex taii
		WHERE	taii.comp_id = @comp_id AND
				taii.[year] BETWEEN YEAR(@datPeriodFirstDate) AND YEAR(@datPeriodLastDate)	AND
				(
					taii.[month] >= MONTH(@datPeriodFirstDate)
						OR
					taii.[month] <= MONTH(@datPeriodLastDate)
				)



--==
--SELECT @decLastIndice, MONTH(@datSAPeriodFirstDate),MONTH(@datSAPeriodLastDate),YEAR(@datSAPeriodFirstDate) , YEAR(@datSAPeriodLastDate)
--SELECT * FROM tbAccountantInflationIndex
--SELECT 'Coef', * FROM @tblCoeficientes
--==


	--SELECT @datSAPeriodFirstDate,@datSAPeriodLastDate,@hacc_date_from,@hacc_date_to

	DECLARE @fun_id INT
	SET @fun_id = 1

	/*obtiene los totales por cuenta del período contable desde su inicio hasta
	la fecha desde seleccionada por el usuario y almacenamos los datos en una
	tabla temporal*/

	SELECT	ATD.acc_count_id,
			sum(
					CASE
						WHEN ta.acc_byInflationAdjust = 'True' AND @balanceType = 2	THEN	dacc_debit * ISNULL(tc.coeficiente,1)
						ELSE									dacc_debit
					END
			   )		dacc_debit,
			sum(
					CASE
						WHEN ta.acc_byInflationAdjust = 'True' AND @balanceType = 2	THEN	dacc_credit * ISNULL(tc.coeficiente,1)
						ELSE									dacc_credit
					END
				)	dacc_credit

		into	#tmpFrom

		FROM 	tbAccountTransactionDetail   ATD					WITH (NOLOCK)
		inner join tbAccountTransactionHead  ATH					WITH (NOLOCK)
			ON		ATD.comp_id				= ATH.comp_id
				and ATD.bra_id				= ATH.bra_id
				and ATD.hacc_transaction	= ATH.hacc_transaction
		inner join tbAccountantPeriod        AP						WITH (NOLOCK)
			ON		AP.comp_id				= ATH.comp_id
				and	AP.ap_id				= ATH.ap_id
		inner join tbAccountant TA									WITH (NOLOCK)
			on		TA.comp_id				= ATH.comp_id
				AND TA.acc_count_id			= ATD.acc_count_id
		LEFT JOIN @tblCoeficientes			 tc
			ON	tc.mes						= MONTH(ath.hacc_date) AND
				tc.anio						= YEAR(ath.hacc_date)
		WHERE		TA.[acc_code]	between	@acc_code_from			and @acc_code_to
			AND		AP.ap_id		= @ap_id
		    AND		ATH.hacc_date	between @datSAPeriodFirstDate	and @datSAPeriodLastDate --DATEADD(DAY,-1,@hacc_date_from)
			AND		(@ag_id			= -1 or ATH.ag_id = @ag_id) --agregue este filtro
			AND		(@cc_code		= -1 or ATD.cc_code = @cc_code)


		GROUP BY ATD.acc_count_id

		--SELECT * FROM #tmpFrom




	/*obtiene los totales por cuenta del período seleccionado por el usuario
	y almacenamos los datos en otra tabla temporal*/
	SELECT 	ATD.acc_count_id,
			sum(
					CASE
						WHEN ta.acc_byInflationAdjust = 'True' AND @balanceType = 2	THEN	dacc_debit * ISNULL(tc.coeficiente,1)
						ELSE																dacc_debit
					END
			   )		dacc_debit,
			sum(
					CASE
						WHEN ta.acc_byInflationAdjust = 'True' AND @balanceType = 2	THEN	dacc_credit * ISNULL(tc.coeficiente,1)
						ELSE																dacc_credit
					END
				)	dacc_credit
			--sum(
			--		CASE
			--			WHEN ta.acc_byInflationAdjust = 1 THEN	dacc_debit * ISNULL(tc.coeficiente,1)
			--			ELSE									dacc_debit
			--		END
			--   )		dacc_debit,
			--sum(
			--		CASE
			--			WHEN ta.acc_byInflationAdjust = 1 THEN	dacc_credit * ISNULL(tc.coeficiente,1)
			--			ELSE									dacc_credit
			--		END
			--	)	dacc_credit

	into	#tmpTo

	FROM 	tbAccountTransactionDetail						ATD			WITH (NOLOCK)

			inner join tbAccountTransactionHead				ATH			WITH (NOLOCK)
				ON	ATD.comp_id				= ATH.comp_id
				and ATD.bra_id				= ATH.bra_id
				and ATD.hacc_transaction	= ATH.hacc_transaction

			inner join tbAccountantPeriod					AP			WITH (NOLOCK)
				ON	AP.comp_id				= ATH.comp_id
				and	AP.ap_id				= ATH.ap_id

			INNER join tbAccountant TA									WITH (NOLOCK)
				on  TA.comp_id				= ATH.comp_id
				AND TA.acc_count_id			= ATD.acc_count_id
			LEFT JOIN @tblCoeficientes			 tc
				ON	tc.mes						= MONTH(ath.hacc_date) AND
					tc.anio						= YEAR(ath.hacc_date)

	WHERE	TA.[acc_code]	between	@acc_code_from	and @acc_code_to
	AND		AP.ap_id		= @ap_id
	and		ATH.hacc_date	between @hacc_date_from and @hacc_date_to
	And		(@ag_id  = -1 or ATH.ag_id = @ag_id) --agregue este filtro
	And		(@cc_code  = -1 or ATD.cc_code = @cc_code)


	GROUP BY ATD.acc_count_id




	/*joineamos las tablas temporales antes generadas para obetener un solo
	conjunto de resultados necesario para cada reporte*/

	select	a.acc_count_id,
			a.acc_code,
			a.acc_desc,

--			isnull(f.dacc_debit,0)					sa_dacc_debit,
--			isnull(f.dacc_credit,0)					sa_dacc_credit,


		 	-- Parte 763

		 	CASE @option
		 		WHEN 'True' THEN isnull(f.dacc_debit,0)
				ELSE CONVERT(DECIMAL(18,4),0)
		    END																sa_dacc_debit,

			CASE @option
				WHEN 'True' THEN isnull(f.dacc_credit,0)
				ELSE CONVERT(DECIMAL(18,4),0)
			END																sa_dacc_credit,

			isnull(t.dacc_debit,CONVERT(DECIMAL(18,4),0))					dacc_debit,
			isnull(t.dacc_credit,CONVERT(DECIMAL(18,4),0))					dacc_credit
	INTO 	#tmpSaldosCalculados
	from	#tmpFrom			f

			full join #tmpTo	t
			on f.acc_count_id = t.acc_count_id

			inner join dbo.tbAccountant	a							WITH (NOLOCK)
			on a.acc_count_id =	isnull(f.acc_count_id, t.acc_count_id)

	order by a.acc_code



	-- ---------------------------------------------------------------------------------------------------------------
	-- Ahora hay que sumarizar en todas las cuentas NO IMPUTABLES que reciben asientos de otras cuentas SI IMPUTABLES
	-- ---------------------------------------------------------------------------------------------------------------
	-- Cursor que selecciona cuentas IMPUTABLES que sumarizen en cuentas NO IMPUTABLES
	DECLARE curSumnariza  CURSOR LOCAL FAST_FORWARD FOR
	SELECT	ta.acc_count_id,
			ta.acc_count_sum,
			tas.acc_code,
			tas.acc_desc,
			tmp.sa_dacc_debit,
			tmp.sa_dacc_credit,
			tmp.dacc_debit,
			tmp.dacc_credit
		FROM tbAccountant ta								WITH (NOLOCK)
		INNER JOIN #tmpSaldosCalculados tmp
			ON tmp.acc_count_id = ta.acc_count_id
		INNER JOIN tbAccountant tas							WITH (NOLOCK)
			ON	tas.comp_id			= @comp_id AND
				tas.acc_count_id	= ta.acc_count_sum
		WHERE	ta.comp_id = @comp_id  AND
				ta.acc_imputable = 'True' AND
				ta.acc_count_sum IS NOT NULL and
				tas.acc_imputable = 'False'
--==
--AND 1 = 2   -- Para testear si esto no estuviese!!
--AND tas.acc_count_id = 4125
--==
		ORDER BY tas.acc_code DESC

	DECLARE @int_sumariza_acc_count_id	AS INT
	DECLARE @int_sumariza_acc_count_sum AS INT
	DECLARE @strCode					AS CHAR(20)
	DECLARE @strDesc					AS NVARCHAR(50)
	DECLARE @decsa_dacc_debit			AS DECIMAL(19,4)
	DECLARE @decsa_dacc_credit			AS DECIMAL(19,4)
	DECLARE @decdacc_debit				AS DECIMAL(19,4)
	DECLARE @decdacc_credit				AS DECIMAL(19,4)

	OPEN curSumnariza
	FETCH NEXT FROM curSumnariza INTO @int_sumariza_acc_count_id,@int_sumariza_acc_count_sum,@strCode,@strDesc,@decsa_dacc_debit,@decsa_dacc_credit,@decdacc_debit,@decdacc_credit
	WHILE @@FETCH_STATUS = 0
		BEGIN
			IF NOT EXISTS(SELECT 1 FROM #tmpSaldosCalculados tmp where tmp.acc_count_id = @int_sumariza_acc_count_sum)
				BEGIN
					INSERT INTO #tmpSaldosCalculados
						(	acc_count_id,
							acc_code,
							acc_desc,
							sa_dacc_debit,
							sa_dacc_credit,
							dacc_debit,
							dacc_credit
							)
						VALUES (@int_sumariza_acc_count_sum,
								@strCode,
								@strDesc,
								0,
								0,
								0,
								0)
				END
				UPDATE #tmpSaldosCalculados
					SET sa_dacc_debit	= sa_dacc_debit		+ @decsa_dacc_debit,
						sa_dacc_credit	= sa_dacc_credit	+ @decsa_dacc_credit,
						dacc_debit		= dacc_debit		+ @decdacc_debit,
						dacc_credit		= dacc_credit		+ @decdacc_credit
					WHERE acc_count_id = @int_sumariza_acc_count_sum

			FETCH NEXT FROM curSumnariza INTO @int_sumariza_acc_count_id,@int_sumariza_acc_count_sum,@strCode,@strDesc,@decsa_dacc_debit,@decsa_dacc_credit,@decdacc_debit,@decdacc_credit
		END
		CLOSE curSumnariza
		DEALLOCATE curSumnariza
	-- ---------------------------------------------------------------------------------------------------------------


	-- ---------------------------------------------------------------------------------------------------------------
	-- Hacer una pasada mas solo por cuentas NO IMPUTABLES de la #tmpSaldosCalculados ordenadas x code desc
	-- que sumen en NO IMPUTABLES tambien.!!  Ej. Activo Corriente en Activo
	-- ---------------------------------------------------------------------------------------------------------------
	DECLARE curSumnariza  CURSOR LOCAL FAST_FORWARD FOR
	SELECT	ta.acc_count_id,
			ta.acc_count_sum,
			tas.acc_code,
			tas.acc_desc,
			IsNull(tmp.sa_dacc_debit,0),
			IsNull(tmp.sa_dacc_credit,0),
			IsNull(tmp.dacc_debit,0),
			IsNull(tmp.dacc_credit,0)
		FROM tbAccountant ta								WITH (NOLOCK)
		LEFT JOIN #tmpSaldosCalculados tmp
			ON tmp.acc_count_id = ta.acc_count_id
		INNER JOIN tbAccountant tas							WITH (NOLOCK)
			ON	tas.comp_id			= @comp_id AND
				tas.acc_count_id	= ta.acc_count_sum
		WHERE	ta.comp_id = @comp_id  AND
				ta.acc_imputable = 'False' AND
				ta.acc_count_sum IS NOT NULL and
				tas.acc_imputable = 'False'
--AND 1 = 2   -- Para testear si esto no estuviese!!
		ORDER BY tas.acc_code DESC


	OPEN curSumnariza
	FETCH NEXT FROM curSumnariza INTO @int_sumariza_acc_count_id,@int_sumariza_acc_count_sum,@strCode,@strDesc,@decsa_dacc_debit,@decsa_dacc_credit,@decdacc_debit,@decdacc_credit
	WHILE @@FETCH_STATUS = 0
		BEGIN

			-- Recarga Variables con datos actualizados
			-- Por si una cuenta no imputable se sumarizo con otra no imputable
			-- que en el cursor no tenia datos aun
			SELECT
					@decsa_dacc_debit	= IsNull(tmp.sa_dacc_debit,0),
					@decsa_dacc_credit	= IsNull(tmp.sa_dacc_credit,0),
					@decdacc_debit		= IsNull(tmp.dacc_debit,0),
					@decdacc_credit		= IsNull(tmp.dacc_credit,0)
			From #tmpSaldosCalculados tmp
			WHERE tmp.acc_count_id = @int_sumariza_acc_count_id



			IF NOT EXISTS(SELECT 1 FROM #tmpSaldosCalculados tmp where tmp.acc_count_id = @int_sumariza_acc_count_sum)
				BEGIN
					INSERT INTO #tmpSaldosCalculados
						(	acc_count_id,
							acc_code,
							acc_desc,
							sa_dacc_debit,
							sa_dacc_credit,
							dacc_debit,
							dacc_credit
							)
						VALUES (@int_sumariza_acc_count_sum,
								@strCode,
								@strDesc,
								0,
								0,
								0,
								0)
				END
				UPDATE #tmpSaldosCalculados
					SET sa_dacc_debit	= sa_dacc_debit		+ @decsa_dacc_debit,
						sa_dacc_credit	= sa_dacc_credit	+ @decsa_dacc_credit,
						dacc_debit		= dacc_debit		+ @decdacc_debit,
						dacc_credit		= dacc_credit		+ @decdacc_credit
					WHERE acc_count_id = @int_sumariza_acc_count_sum

			FETCH NEXT FROM curSumnariza INTO @int_sumariza_acc_count_id,@int_sumariza_acc_count_sum,@strCode,@strDesc,@decsa_dacc_debit,@decsa_dacc_credit,@decdacc_debit,@decdacc_credit
		END
		CLOSE curSumnariza
		DEALLOCATE curSumnariza
	-- ---------------------------------------------------------------------------------------------------------------





	SELECT	tmp.acc_code,
			tmp.acc_desc,
			tmp.sa_dacc_debit,
			tmp.sa_dacc_credit,
			tmp.dacc_debit,
			tmp.dacc_credit,
			ta.acc_imputable,					-- GASTON ES ESTE CAMPO:!!!!  No toques este SP ya que lo estoy modificando
			ta.acc_count_id
		INTO #tmpSaldosCalculadosFinal
		FROM #tmpSaldosCalculados tmp
		INNER JOIN tbAccountant ta					WITH (NOLOCK)
			ON	ta.comp_id		= @comp_id		  AND
				ta.acc_count_id = tmp.acc_count_id
		WHERE	CASE
					WHEN ta.acc_imputable='True'  AND @acc_Type=1	THEN 'TRUE'
					WHEN ta.acc_imputable='False' AND @acc_Type=2	THEN 'TRUE'
					WHEN						      @acc_Type=-1	THEN 'TRUE'
					ELSE												 'False'
				END = 'True'
				AND
				CASE
					WHEN @acc_grouping = -1			THEN 'True'
					WHEN ta.acgr_id = @acc_grouping THEN 'True'
					ELSE								 'False'
				END	= 'True'
	ORDER BY acc_code


	SELECT	REPLICATE(' ',IsNull(ta.acc_column,0) * 1) + dbo.fnStrAllTrim(tmp.acc_code)		[acc_code],
			tmp.acc_desc,
			tmp.sa_dacc_debit,
			tmp.sa_dacc_credit,
			tmp.dacc_debit,
			tmp.dacc_credit,
			ta.acc_imputable					-- GASTON ES ESTE CAMPO:!!!!  No toques este SP ya que lo estoy modificando
		FROM #tmpSaldosCalculadosFinal tmp
			INNER JOIN tbAccountant ta								WITH (NOLOCK)
				ON	ta.comp_id		= @comp_id AND
					ta.acc_count_id = tmp.acc_count_id
		ORDER BY ta.acc_code


    exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	select

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 378
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],
				@acc_code_from [params10],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 379
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],
      			@acc_code_to [params12],


				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 380
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params1],
			 CASE @ap_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				   (SELECT		tap.ap_desc
					FROM	tbAccountantPeriod tap
					WHERE	tap.comp_id = @comp_id
					And     tap.ap_id=@ap_id)
			END																	[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],
			@hacc_date_from [DateParams1],
			--convert(varchar,day(@hacc_date_from)) + '/' + convert(varchar,month(@hacc_date_from)) + '/' + convert(varchar,year(@hacc_date_from))		[params4],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

			@hacc_date_to [DateParams2],
			--convert(varchar,day(@hacc_date_to)) + '/' + convert(varchar,month(@hacc_date_to)) + '/' + convert(varchar,year(@hacc_date_to))		[params6],


				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1027
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params7],
			 CASE @ag_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tag.ag_desc
					 From tbAccountantGroup tag
						WHERE	tag.comp_id= @comp_id
						AND tag.ag_id= @ag_id)
			END		[params8],



				-- MB , Parte 763

		    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 991
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params18],

      		  CASE @option WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc	FROM   tbsysOptionsValues tov

						WHERE	tov.optval_class = 1
						AND     tov.optval_id = @option
						AND     tov.lang_id   = @lang_id)

			END		[params19],

		 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2125
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params20],

      		  CASE @acc_Type WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc	FROM   tbsysOptionsValues tov

						WHERE	tov.optval_class = 308
						AND     tov.optval_id = @acc_Type
						AND     tov.lang_id   = @lang_id)

			END		[params21],


			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2126
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params22],

      		  CASE @acc_grouping WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT taa.acgr_desc
					  	FROM   tbAccountant_AccountGrouping taa

						WHERE	taa.comp_id = @comp_id
						and		taa.acgr_id = @acc_grouping)

			END		[params23],


				 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 5652
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params24],

      		  CASE @balanceType WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc	FROM   tbsysOptionsValues tov

						WHERE	tov.optval_class = 743
						AND     tov.optval_id = @balanceType
						AND     tov.lang_id   = @lang_id)

			END		[params25]



----TOTALES------------------------------------------------------------


	SELECT 	sum(tmp.sa_dacc_debit)			[sa_dacc_debit1],
			sum(tmp.sa_dacc_credit)			[sa_dacc_credit1],
			sum(tmp.dacc_debit)				[dacc_debit1],
			sum(tmp.dacc_credit)			[dacc_credit1],
			(
				(sum(tmp.sa_dacc_debit) - sum(tmp.sa_dacc_credit)) +
				(sum(tmp.dacc_debit)	- sum(tmp.dacc_credit))
			)								[dacc_Saldo]
	FROM #tmpSaldosCalculadosFinal tmp
		INNER JOIN tbAccountant ta
			ON	ta.comp_id			= @comp_id AND
				 ta.acc_count_id	= tmp.acc_count_id
		WHERE (ta.acc_imputable = 'True' AND @acc_Type = 1)  OR
			  (ta.acc_imputable = 'True' AND @acc_Type = -1)
			  --(ta.acc_imputable = 'False' AND @acc_Type = 2)   NOOOOOOOOOOO


----TOTALES------------------------------------------------------------

END
GO



CREATE PROCEDURE [dbo].[spAccounting_getReport_Balance_CHILE]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@acc_code_from		varchar(20),
		@acc_code_to		varchar(20),
		@ap_id				int,
		@hacc_date_from		datetime,
		@hacc_date_to		datetime,
		@ag_id				INT,
		@cc_code			INT,
		@bra_id				INT,
		@option				BIT,
		@acc_grouping		INT,		-- -1, ID Grupo de Cuentas Contables
		@acc_Type			INT,  		-- -1,1 Imputables, 2 No Imputables
		@intBranch4Lang		INT,
		@balanceType		INT


)
as


BEGIN

	SET DATEFORMAT 'ymd'
	set nocount on



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------





-- -------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------
/*
	DECLARE	@comp_id			int,
			@lang_id			int,
			@page_id			int,

			@acc_code_from		varchar(20),
			@acc_code_to		varchar(20),
			@ap_id				int,
			@hacc_date_from		datetime,
			@hacc_date_to		Datetime,
			@ag_id				int,
			@cc_code			NVARCHAR(20),
			@bra_id				INT,
			@option				BIT,
			@acc_grouping		int,	---1,Grupo de Cuentas Contables
			@acc_Type			int	,	--1,0 Imputables.1-No Imputables
			@intBranch4Lang		int,
			@balanceType		INT





	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10004,

			@acc_code_from		='1000000000',
			@acc_code_to		='erwerw',
			@ap_id				= 41,
			@hacc_date_from		= '2019-01-01',
			@hacc_date_to		= '2019-12-31',
			@ag_id				= -1,
			@cc_code			= -1,
			@bra_id				=  -1,
			@option				= 'False',
			@acc_grouping		= -1,
			@acc_Type			= -1,
			@intBranch4Lang		= 2,
			@balanceType		= 1




	drop table #tmpFrom
	drop table #tmpTo
	DROP TABLE #tmpSaldosCalculados
	DROP TABLE #tmpSaldosCalculadosFinal
*/
---------------------------------------------------------------------

	set	@hacc_date_from = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_from,'False')
	set	@hacc_date_to = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_to,'True')


	DECLARE @datSAPeriodFirstDate	AS DATETIME
	DECLARE @datSAPeriodLastDate	AS DATETIME
	DECLARE @datPeriodFirstDate		AS DATETIME
	DECLARE @datPeriodLastDate		AS DATETIME


	SELECT @datSAPeriodFirstDate = tap.ap_firstdate,
		   @datSAPeriodLastDate  = DATEADD(DAY,-1,@hacc_date_from),		--tap.ap_lastdate
		   @datPeriodFirstDate	 = tap.ap_firstdate,
		   @datPeriodLastDate	 = tap.ap_lastdate
		FROM tbAccountantPeriod tap			WITH (NOLOCK)
		WHERE	tap.comp_id = @comp_id
			AND tap.ap_id	= @ap_id

	SET @datSAPeriodFirstDate = dbo.fnGetEnd_or_BeginOfDate(@datSAPeriodFirstDate,'false')
	SET @datSAPeriodLastDate  = dbo.fnGetEnd_or_BeginOfDate(@datSAPeriodLastDate,'True')
	SET @datPeriodFirstDate   = dbo.fnGetEnd_or_BeginOfDate(@datPeriodFirstDate,'false')
	SET @datPeriodLastDate    = dbo.fnGetEnd_or_BeginOfDate(@datPeriodLastDate,'True')

	DECLARE @decLastIndice AS DECIMAL(19,6) = 1
	SELECT  @decLastIndice = ISNULL(taii.indice,1)
		FROM tbAccountantInflationIndex taii		WITH (NOLOCK)
		WHERE	taii.comp_id	= @comp_id						AND
				taii.[month]	= MONTH(@datPeriodLastDate)	AND
				taii.[year]		= YEAR( @datPeriodLastDate)

	DECLARE @tblCoeficientes TABLE(mes INT,anio INT,coeficiente DECIMAL(25,8))
	INSERT INTO @tblCoeficientes
	(
		mes,
		anio,
		coeficiente
	)
		SELECT	taii.[month],
				taii.[year],
				@decLastIndice / dbo.fnNoZDiv(ISNULL(taii.indice,1))
			FROM tbAccountantInflationIndex taii
		WHERE	taii.comp_id = @comp_id AND
				taii.[year] BETWEEN YEAR(@datPeriodFirstDate) AND YEAR(@datPeriodLastDate)	AND
				(
					taii.[month] >= MONTH(@datPeriodFirstDate)
						OR
					taii.[month] <= MONTH(@datPeriodLastDate)
				)



--==
--SELECT @decLastIndice, MONTH(@datSAPeriodFirstDate),MONTH(@datSAPeriodLastDate),YEAR(@datSAPeriodFirstDate) , YEAR(@datSAPeriodLastDate)
--SELECT * FROM tbAccountantInflationIndex
--SELECT 'Coef', * FROM @tblCoeficientes
--==


	--SELECT @datSAPeriodFirstDate,@datSAPeriodLastDate,@hacc_date_from,@hacc_date_to

	DECLARE @fun_id INT
	SET @fun_id = 1

	/*obtiene los totales por cuenta del período contable desde su inicio hasta
	la fecha desde seleccionada por el usuario y almacenamos los datos en una
	tabla temporal*/

	SELECT	ATD.acc_count_id,
			sum(
					CASE
						WHEN ta.acc_byInflationAdjust = 'True' AND @balanceType = 2	THEN	dacc_debit * ISNULL(tc.coeficiente,1)
						ELSE									dacc_debit
					END
			   )		dacc_debit,
			sum(
					CASE
						WHEN ta.acc_byInflationAdjust = 'True' AND @balanceType = 2	THEN	dacc_credit * ISNULL(tc.coeficiente,1)
						ELSE									dacc_credit
					END
				)	dacc_credit

		into	#tmpFrom

		FROM 	tbAccountTransactionDetail   ATD					WITH (NOLOCK)
		inner join tbAccountTransactionHead  ATH					WITH (NOLOCK)
			ON		ATD.comp_id				= ATH.comp_id
				and ATD.bra_id				= ATH.bra_id
				and ATD.hacc_transaction	= ATH.hacc_transaction
		inner join tbAccountantPeriod        AP						WITH (NOLOCK)
			ON		AP.comp_id				= ATH.comp_id
				and	AP.ap_id				= ATH.ap_id
		inner join tbAccountant TA									WITH (NOLOCK)
			on		TA.comp_id				= ATH.comp_id
				AND TA.acc_count_id			= ATD.acc_count_id
		LEFT JOIN @tblCoeficientes			 tc
			ON	tc.mes						= MONTH(ath.hacc_date) AND
				tc.anio						= YEAR(ath.hacc_date)
		WHERE		TA.[acc_code]	between	@acc_code_from			and @acc_code_to
			AND		AP.ap_id		= @ap_id
		    AND		ATH.hacc_date	between @datSAPeriodFirstDate	and @datSAPeriodLastDate --DATEADD(DAY,-1,@hacc_date_from)
			AND		(@ag_id			= -1 or ATH.ag_id = @ag_id) --agregue este filtro
			AND		(@cc_code		= -1 or ATD.cc_code = @cc_code)


		GROUP BY ATD.acc_count_id

		--SELECT * FROM #tmpFrom




	/*obtiene los totales por cuenta del período seleccionado por el usuario
	y almacenamos los datos en otra tabla temporal*/
	SELECT 	ATD.acc_count_id,
			sum(
					CASE
						WHEN ta.acc_byInflationAdjust = 'True' AND @balanceType = 2	THEN	dacc_debit * ISNULL(tc.coeficiente,1)
						ELSE																dacc_debit
					END
			   )		dacc_debit,
			sum(
					CASE
						WHEN ta.acc_byInflationAdjust = 'True' AND @balanceType = 2	THEN	dacc_credit * ISNULL(tc.coeficiente,1)
						ELSE																dacc_credit
					END
				)	dacc_credit
			--sum(
			--		CASE
			--			WHEN ta.acc_byInflationAdjust = 1 THEN	dacc_debit * ISNULL(tc.coeficiente,1)
			--			ELSE									dacc_debit
			--		END
			--   )		dacc_debit,
			--sum(
			--		CASEad
			--			WHEN ta.acc_byInflationAdjust = 1 THEN	dacc_credit * ISNULL(tc.coeficiente,1)
			--			ELSE									dacc_credit
			--		END
			--	)	dacc_credit

	into	#tmpTo

	FROM 	tbAccountTransactionDetail						ATD			WITH (NOLOCK)

			inner join tbAccountTransactionHead				ATH			WITH (NOLOCK)
				ON	ATD.comp_id				= ATH.comp_id
				and ATD.bra_id				= ATH.bra_id
				and ATD.hacc_transaction	= ATH.hacc_transaction

			inner join tbAccountantPeriod					AP			WITH (NOLOCK)
				ON	AP.comp_id				= ATH.comp_id
				and	AP.ap_id				= ATH.ap_id

			INNER join tbAccountant TA									WITH (NOLOCK)
				on  TA.comp_id				= ATH.comp_id
				AND TA.acc_count_id			= ATD.acc_count_id
			LEFT JOIN @tblCoeficientes			 tc
				ON	tc.mes						= MONTH(ath.hacc_date) AND
					tc.anio						= YEAR(ath.hacc_date)

	WHERE	TA.[acc_code]	between	@acc_code_from	and @acc_code_to
	AND		AP.ap_id		= @ap_id
	and		ATH.hacc_date	between @hacc_date_from and @hacc_date_to
	And		(@ag_id  = -1 or ATH.ag_id = @ag_id) --agregue este filtro
	And		(@cc_code  = -1 or ATD.cc_code = @cc_code)

	GROUP BY ATD.acc_count_id




	/*joineamos las tablas temporales antes generadas para obetener un solo
	conjunto de resultados necesario para cada reporte*/

	select	a.acc_count_id,
			a.acc_code,
			a.acc_desc,

--			isnull(f.dacc_debit,0)					sa_dacc_debit,
--			isnull(f.dacc_credit,0)					sa_dacc_credit,


		 	-- Parte 763

		 	CASE @option
		 		WHEN 'True' THEN isnull(f.dacc_debit,0)
				ELSE CONVERT(DECIMAL(18,4),0)
		    END																sa_dacc_debit,

			CASE @option
				WHEN 'True' THEN isnull(f.dacc_credit,0)
				ELSE CONVERT(DECIMAL(18,4),0)
			END																sa_dacc_credit,

			isnull(t.dacc_debit,CONVERT(DECIMAL(18,4),0))					dacc_debit,
			isnull(t.dacc_credit,CONVERT(DECIMAL(18,4),0))					dacc_credit
	INTO 	#tmpSaldosCalculados
	from	#tmpFrom			f

			full join #tmpTo	t
			on f.acc_count_id = t.acc_count_id

			inner join dbo.tbAccountant	a							WITH (NOLOCK)
			on a.acc_count_id =	isnull(f.acc_count_id, t.acc_count_id)

	order by a.acc_code



	-- ---------------------------------------------------------------------------------------------------------------
	-- Ahora hay que sumarizar en todas las cuentas NO IMPUTABLES que reciben asientos de otras cuentas SI IMPUTABLES
	-- ---------------------------------------------------------------------------------------------------------------
	-- Cursor que selecciona cuentas IMPUTABLES que sumarizen en cuentas NO IMPUTABLES
	DECLARE curSumnariza  CURSOR LOCAL FAST_FORWARD FOR
	SELECT	ta.acc_count_id,
			ta.acc_count_sum,
			tas.acc_code,
			tas.acc_desc,
			tmp.sa_dacc_debit,
			tmp.sa_dacc_credit,
			tmp.dacc_debit,
			tmp.dacc_credit
		FROM tbAccountant ta								WITH (NOLOCK)
		INNER JOIN #tmpSaldosCalculados tmp
			ON tmp.acc_count_id = ta.acc_count_id
		INNER JOIN tbAccountant tas							WITH (NOLOCK)
			ON	tas.comp_id			= @comp_id AND
				tas.acc_count_id	= ta.acc_count_sum
		WHERE	ta.comp_id = @comp_id  AND
				ta.acc_imputable = 'True' AND
				ta.acc_count_sum IS NOT NULL and
				tas.acc_imputable = 'False'
--==
--AND 1 = 2   -- Para testear si esto no estuviese!!
--AND tas.acc_count_id = 4125
--==
		ORDER BY tas.acc_code DESC

	DECLARE @int_sumariza_acc_count_id	AS INT
	DECLARE @int_sumariza_acc_count_sum AS INT
	DECLARE @strCode					AS CHAR(20)
	DECLARE @strDesc					AS NVARCHAR(50)
	DECLARE @decsa_dacc_debit			AS DECIMAL(19,4)
	DECLARE @decsa_dacc_credit			AS DECIMAL(19,4)
	DECLARE @decdacc_debit				AS DECIMAL(19,4)
	DECLARE @decdacc_credit				AS DECIMAL(19,4)

	OPEN curSumnariza
	FETCH NEXT FROM curSumnariza INTO @int_sumariza_acc_count_id,@int_sumariza_acc_count_sum,@strCode,@strDesc,@decsa_dacc_debit,@decsa_dacc_credit,@decdacc_debit,@decdacc_credit
	WHILE @@FETCH_STATUS = 0
		BEGIN
			IF NOT EXISTS(SELECT 1 FROM #tmpSaldosCalculados tmp where tmp.acc_count_id = @int_sumariza_acc_count_sum)
				BEGIN
					INSERT INTO #tmpSaldosCalculados
						(	acc_count_id,
							acc_code,
							acc_desc,
							sa_dacc_debit,
							sa_dacc_credit,
							dacc_debit,
							dacc_credit
							)
						VALUES (@int_sumariza_acc_count_sum,
								@strCode,
								@strDesc,
								0,
								0,
								0,
								0)
				END
				UPDATE #tmpSaldosCalculados
					SET sa_dacc_debit	= sa_dacc_debit		+ @decsa_dacc_debit,
						sa_dacc_credit	= sa_dacc_credit	+ @decsa_dacc_credit,
						dacc_debit		= dacc_debit		+ @decdacc_debit,
						dacc_credit		= dacc_credit		+ @decdacc_credit
					WHERE acc_count_id = @int_sumariza_acc_count_sum

			FETCH NEXT FROM curSumnariza INTO @int_sumariza_acc_count_id,@int_sumariza_acc_count_sum,@strCode,@strDesc,@decsa_dacc_debit,@decsa_dacc_credit,@decdacc_debit,@decdacc_credit
		END
		CLOSE curSumnariza
		DEALLOCATE curSumnariza
	-- ---------------------------------------------------------------------------------------------------------------


	-- ---------------------------------------------------------------------------------------------------------------
	-- Hacer una pasada mas solo por cuentas NO IMPUTABLES de la #tmpSaldosCalculados ordenadas x code desc
	-- que sumen en NO IMPUTABLES tambien.!!  Ej. Activo Corriente en Activo
	-- ---------------------------------------------------------------------------------------------------------------
	DECLARE curSumnariza  CURSOR LOCAL FAST_FORWARD FOR
	SELECT	ta.acc_count_id,
			ta.acc_count_sum,
			tas.acc_code,
			tas.acc_desc,
			IsNull(tmp.sa_dacc_debit,0),
			IsNull(tmp.sa_dacc_credit,0),
			IsNull(tmp.dacc_debit,0),
			IsNull(tmp.dacc_credit,0)
		FROM tbAccountant ta								WITH (NOLOCK)
		LEFT JOIN #tmpSaldosCalculados tmp
			ON tmp.acc_count_id = ta.acc_count_id
		INNER JOIN tbAccountant tas							WITH (NOLOCK)
			ON	tas.comp_id			= @comp_id AND
				tas.acc_count_id	= ta.acc_count_sum
		WHERE	ta.comp_id = @comp_id  AND
				ta.acc_imputable = 'False' AND
				ta.acc_count_sum IS NOT NULL and
				tas.acc_imputable = 'False'
--AND 1 = 2   -- Para testear si esto no estuviese!!
		ORDER BY tas.acc_code DESC


	OPEN curSumnariza
	FETCH NEXT FROM curSumnariza INTO @int_sumariza_acc_count_id,@int_sumariza_acc_count_sum,@strCode,@strDesc,@decsa_dacc_debit,@decsa_dacc_credit,@decdacc_debit,@decdacc_credit
	WHILE @@FETCH_STATUS = 0
		BEGIN

			-- Recarga Variables con datos actualizados
			-- Por si una cuenta no imputable se sumarizo con otra no imputable
			-- que en el cursor no tenia datos aun
			SELECT
					@decsa_dacc_debit	= IsNull(tmp.sa_dacc_debit,0),
					@decsa_dacc_credit	= IsNull(tmp.sa_dacc_credit,0),
					@decdacc_debit		= IsNull(tmp.dacc_debit,0),
					@decdacc_credit		= IsNull(tmp.dacc_credit,0)
			From #tmpSaldosCalculados tmp
			WHERE tmp.acc_count_id = @int_sumariza_acc_count_id



			IF NOT EXISTS(SELECT 1 FROM #tmpSaldosCalculados tmp where tmp.acc_count_id = @int_sumariza_acc_count_sum)
				BEGIN
					INSERT INTO #tmpSaldosCalculados
						(	acc_count_id,
							acc_code,
							acc_desc,
							sa_dacc_debit,
							sa_dacc_credit,
							dacc_debit,
							dacc_credit
							)
						VALUES (@int_sumariza_acc_count_sum,
								@strCode,
								@strDesc,
								0,
								0,
								0,
								0)
				END
				UPDATE #tmpSaldosCalculados
					SET sa_dacc_debit	= sa_dacc_debit		+ @decsa_dacc_debit,
						sa_dacc_credit	= sa_dacc_credit	+ @decsa_dacc_credit,
						dacc_debit		= dacc_debit		+ @decdacc_debit,
						dacc_credit		= dacc_credit		+ @decdacc_credit
					WHERE acc_count_id = @int_sumariza_acc_count_sum

			FETCH NEXT FROM curSumnariza INTO @int_sumariza_acc_count_id,@int_sumariza_acc_count_sum,@strCode,@strDesc,@decsa_dacc_debit,@decsa_dacc_credit,@decdacc_debit,@decdacc_credit
		END
		CLOSE curSumnariza
		DEALLOCATE curSumnariza
	-- ---------------------------------------------------------------------------------------------------------------





	SELECT	tmp.acc_code,
			tmp.acc_desc,
			tmp.sa_dacc_debit,
			tmp.sa_dacc_credit,
			tmp.dacc_debit,
			tmp.dacc_credit,
			ta.acc_imputable,					-- GASTON ES ESTE CAMPO:!!!!  No toques este SP ya que lo estoy modificando
			ta.acc_count_id
		INTO #tmpSaldosCalculadosFinal
		FROM #tmpSaldosCalculados tmp
		INNER JOIN tbAccountant ta					WITH (NOLOCK)
			ON	ta.comp_id		= @comp_id		  AND
				ta.acc_count_id = tmp.acc_count_id
		WHERE	CASE
					WHEN ta.acc_imputable='True'  AND @acc_Type=1	THEN 'TRUE'
					WHEN ta.acc_imputable='False' AND @acc_Type=2	THEN 'TRUE'
					WHEN						      @acc_Type=-1	THEN 'TRUE'
					ELSE												 'False'
				END = 'True'
				AND
				CASE
					WHEN @acc_grouping = -1			THEN 'True'
					WHEN ta.acgr_id = @acc_grouping THEN 'True'
					ELSE								 'False'
				END	= 'True'
	ORDER BY acc_code


	SELECT	tmp.acc_count_id,
			REPLICATE(' ',IsNull(ta.acc_column,0) * 1) + dbo.fnStrAllTrim(tmp.acc_code)		[acc_code],
			tmp.acc_desc,
			--tmp.sa_dacc_debit,
			--tmp.sa_dacc_credit,
			tmp.dacc_debit,
			tmp.dacc_credit,

			ta.acc_imputable,					-- GASTON ES ESTE CAMPO:!!!!  No toques este SP ya que lo estoy modificando

			CASE WHEN (tmp.dacc_debit - tmp.dacc_credit) > 0 THEN (tmp.dacc_debit - tmp.dacc_credit)
			ELSE		 0
			END																				[Deudor],
			CASE WHEN (tmp.dacc_debit - tmp.dacc_credit) < 0 THEN (tmp.dacc_debit - tmp.dacc_credit)
			ELSE		 0
			END																				[Acreedor],

			CASE WHEN tabgd.abld_columnNumber = 1 THEN  (tmp.dacc_debit - tmp.dacc_credit)
			ELSE										0
			END																				[Activo],
			CASE WHEN tabgd.abld_columnNumber = 2 THEN  (tmp.dacc_debit - tmp.dacc_credit)
			ELSE										0
			END																				[Pasivo],
			CASE WHEN tabgd.abld_columnNumber = 3 THEN  (tmp.dacc_debit - tmp.dacc_credit)
			ELSE										0
			END																				[Perdida],
			CASE WHEN tabgd.abld_columnNumber = 4 THEN  (tmp.dacc_debit - tmp.dacc_credit)
			ELSE										0
			END																				[Ganancia],


			tabgd.abld_mathOperationSUM, tabgd.abld_columnNumber
		FROM #tmpSaldosCalculadosFinal tmp
			INNER JOIN tbAccountant ta								WITH (NOLOCK)
				ON	ta.comp_id		= @comp_id AND
					ta.acc_count_id = tmp.acc_count_id
			INNER JOIN tbAccountant_BalanceGroupDetail tabgd
			ON	tabgd.comp_id		= ta.comp_id				AND
				tabgd.acc_count_id	= ta.acc_count_id

		ORDER BY ta.acc_code


    exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	select

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 378
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],
				@acc_code_from [params10],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 379
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],
      			@acc_code_to [params12],


				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 380
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params1],
			 CASE @ap_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				   (SELECT		tap.ap_desc
					FROM	tbAccountantPeriod tap
					WHERE	tap.comp_id = @comp_id
					And     tap.ap_id=@ap_id)
			END																	[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],
			@hacc_date_from [DateParams1],
			--convert(varchar,day(@hacc_date_from)) + '/' + convert(varchar,month(@hacc_date_from)) + '/' + convert(varchar,year(@hacc_date_from))		[params4],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

			@hacc_date_to [DateParams2],
			--convert(varchar,day(@hacc_date_to)) + '/' + convert(varchar,month(@hacc_date_to)) + '/' + convert(varchar,year(@hacc_date_to))		[params6],


				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1027
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params7],
			 CASE @ag_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tag.ag_desc
					 From tbAccountantGroup tag
						WHERE	tag.comp_id= @comp_id
						AND tag.ag_id= @ag_id)
			END		[params8],



				-- MB , Parte 763

		    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 991
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params18],

      		  CASE @option WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc	FROM   tbsysOptionsValues tov

						WHERE	tov.optval_class = 1
						AND     tov.optval_id = @option
						AND     tov.lang_id   = @lang_id)

			END		[params19],

		 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2125
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params20],

      		  CASE @acc_Type WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc	FROM   tbsysOptionsValues tov

						WHERE	tov.optval_class = 308
						AND     tov.optval_id = @acc_Type
						AND     tov.lang_id   = @lang_id)

			END		[params21],


			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2126
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params22],

      		  CASE @acc_grouping WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT taa.acgr_desc
					  	FROM   tbAccountant_AccountGrouping taa

						WHERE	taa.comp_id = @comp_id
						and		taa.acgr_id = @acc_grouping)

			END		[params23],


				 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 5652
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params24],

      		  CASE @balanceType WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc	FROM   tbsysOptionsValues tov

						WHERE	tov.optval_class = 743
						AND     tov.optval_id = @balanceType
						AND     tov.lang_id   = @lang_id)

			END		[params25],
			(
				SELECT
					 'Desde: ' + CONVERT(VARCHAR,tap.ap_firstdate,103) +  ' Hasta: '  + CONVERT(VARCHAR,tap.ap_lastdate,103)
				FROM tbAccountantPeriod			tap	WITH(NOLOCK)
				WHERE	tap.comp_id = @comp_id	AND
						tap.ap_id	= @ap_id
			)	[params26]




----TOTALES------------------------------------------------------------

	SELECT 	sum(tmp.sa_dacc_debit)			[sa_dacc_debit1],
			sum(tmp.sa_dacc_credit)			[sa_dacc_credit1],
			sum(tmp.dacc_debit)				[dacc_debit1],
			sum(tmp.dacc_credit)			[dacc_credit1],
			(
				(sum(tmp.sa_dacc_debit) - sum(tmp.sa_dacc_credit)) +
				(sum(tmp.dacc_debit)	- sum(tmp.dacc_credit))
			)								[dacc_Saldo]
	FROM #tmpSaldosCalculadosFinal tmp
		INNER JOIN tbAccountant ta
			ON	ta.comp_id			= @comp_id AND
				 ta.acc_count_id	= tmp.acc_count_id
		WHERE (ta.acc_imputable = 'True' AND @acc_Type = 1)  OR
			  (ta.acc_imputable = 'True' AND @acc_Type = -1)
			  --(ta.acc_imputable = 'False' AND @acc_Type = 2)   NOOOOOOOOOOO


----TOTALES------------------------------------------------------------

END
GO







-- Creado por:
-- Modificado por MOS: 14-8-08 (Para que salgan Ordenados x ct_transaction)




CREATE procedure [dbo].[spAccounting_getReport_daily]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,

	@ap_id				int,
	@hacc_date_from		datetime,
	@hacc_date_to		datetime,
	@hacc_number_from	int,
	@hacc_number_to		int,
	@acc_count_id		Int,
	@ag_id				INT,
	@cc_code			INT,
	@option2			int,		-- 1: Todos los movimientos,    sino soo totales
	@page_index			int,

	@bra_id				INT,
	@intBranch4Lang		int




)
AS


BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount ON

		set	@hacc_date_from = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_from,'False')
		set	@hacc_date_to = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_to,'True')


	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------
	/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			int,
			@ap_id				int,
			@hacc_date_from		datetime,
			@hacc_date_to		datetime,
			@hacc_number_from	int,
			@hacc_number_to		int,
			@acc_count_id		int	,
			@ag_id				INT,
			@cc_code			NVARCHAR(20),
			@bra_id				INT



	SELECT	@comp_id			=1,
			@lang_id			=2,
			@page_id			=10002,
			@ap_id				=1,
			@hacc_date_from		='01-01-2008',
			@hacc_date_to		='31-12-2010',
			@hacc_number_from	=0,
			@hacc_number_to		=99999999,
			@acc_count_id		=-1,
			@ag_id				=-1,
			@cc_code			=-1,
			@bra_id				=-1

		*/
	-- -----------------------------------------------------------------------------


	DECLARE @fun_id INT
	SET @fun_id = 1

	-- Todos los Movimientos
	IF @option2 = 1
		BEGIN

			SELECT

					A.hacc_number,
					A.hacc_detail,
					A.hacc_date,

					AC.acc_code,
					AC.acc_desc,
					T.acc_detail1,
					T.dacc_debit,
					T.dacc_credit

				FROM	dbo.tbAccountTransactionDetail			T				WITH (NOLOCK)

						INNER JOIN [tbAccountTransactionHead]	A				WITH (NOLOCK)
						ON	T.[hacc_transaction]	= A.[hacc_transaction]
						AND T.[comp_id]				= A.[comp_id]

						INNER JOIN tbAccountant					AC				WITH (NOLOCK)
						ON	A.comp_id				= AC.comp_id
						AND T.acc_count_id			= AC.acc_count_id





				WHERE	t.[comp_id]		= @comp_id
				AND		(@ap_id =-1 or A.[ap_id]		= @ap_id)
				AND		A.[hacc_date]	between @hacc_date_from		and @hacc_date_to
				AND		A.[hacc_number]	between	@hacc_number_from	and @hacc_number_to
				AND		(@ag_id		= -1	OR	A.ag_id = @ag_id) --agregue este filtro...
				AND		(@acc_count_id	= -1 or T.[hacc_transaction] in (select	distinct td.[hacc_transaction]
																			from [tbAccountTransactionDetail] td	WITH (NOLOCK)
																			where td.[acc_count_id] = @acc_count_id))

				AND		(@cc_code		= -1	OR	T.cc_code = @cc_code)


				ORDER BY	A.hacc_number,
							T.dacc_transaction,
							CASE
								WHEN t.dacc_credit <> 0 THEN	1
								ELSE							2
							END,
							T.[dacc_credit]		ASC,
							T.[dacc_debit]		ASC,
							T.[dacc_order]
							--, T.[dacc_debit] desc, T.[dacc_credit] asc


		END
	ELSE		-- Solo Totales
		BEGIN

			SELECT

					A.hacc_number,
					(	SELECT tath.hacc_detail
							FROM tbAccountTransactionHead tath
					 		WHERE	tath.comp_id			= A.comp_id AND
					 				tath.bra_id				= A.bra_id AND
					 				tath.hacc_transaction	= a.hacc_transaction
					)													[hacc_detail],
					A.hacc_date,

					AC.acc_code,
					(
						SELECT ta.acc_desc
							FROM tbAccountant ta
							WHERE	ta.comp_id		= A.comp_id AND
									ta.acc_count_id = T.acc_count_id
					)													[acc_desc],
					''	[acc_detail1],				-- T.acc_detail1
					SUM(ISNULL(T.dacc_debit,0))							[dacc_debit],
					SUM(ISNULL(T.dacc_credit,0))						[dacc_credit]

				FROM	dbo.tbAccountTransactionDetail			T				WITH (NOLOCK)

						INNER JOIN [tbAccountTransactionHead]	A				WITH (NOLOCK)
						ON	T.[hacc_transaction]	= A.[hacc_transaction]
						AND T.[comp_id]				= A.[comp_id]

						INNER JOIN tbAccountant					AC				WITH (NOLOCK)
						ON	A.comp_id				= AC.comp_id
						AND T.acc_count_id			= AC.acc_count_id





				WHERE	t.[comp_id]		= @comp_id
				AND		(@ap_id =-1 or A.[ap_id]		= @ap_id)
				AND		A.[hacc_date]	between @hacc_date_from		and @hacc_date_to
				AND		A.[hacc_number]	between	@hacc_number_from	and @hacc_number_to
				AND		(@ag_id		= -1	OR	A.ag_id = @ag_id) --agregue este filtro...
				AND		(@acc_count_id	= -1 or T.[hacc_transaction] in (select	distinct td.[hacc_transaction]
																			from [tbAccountTransactionDetail] td	WITH (NOLOCK)
																			where td.[acc_count_id] = @acc_count_id))

				AND		(@cc_code		= -1	OR	T.cc_code = @cc_code)


				GROUP BY
						A.comp_id,
						A.bra_id,
						A.hacc_transaction,
						A.hacc_number,
						A.hacc_date,
						AC.acc_code,
						t.acc_count_id	,
						t.comp_id,
						t.bra_id,
						t.hacc_transaction


				ORDER BY	A.hacc_number


		END











	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id
	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 380
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params1],

      		 CASE @ap_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					   (SELECT		tap.ap_desc
						FROM	tbAccountantPeriod tap
						WHERE	tap.comp_id = @comp_id
						And     tap.ap_id=@ap_id)
				END															[params2],

      		 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			--convert(varchar,day(@hacc_date_from)) + '/' + convert(varchar,month(@hacc_date_from)) + '/' + convert(varchar,year(@hacc_date_from))		[params4],
			@hacc_date_from [DateParams1],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

			--convert(varchar,day(@hacc_date_to)) + '/' + convert(varchar,month(@hacc_date_to)) + '/' + convert(varchar,year(@hacc_date_to))		[params6],
			@hacc_date_to [DateParams2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 385
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

			@hacc_number_from [params8],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 385
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

			@hacc_number_to [params10],


				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 387
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],
				 CASE @acc_count_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tca.acc_code
						FROM	tbAccountant tca
						WHERE	tca.comp_id= @comp_id
						AND tca.acc_count_id= @acc_count_id)
			END		[params12],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1027
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],
			 CASE @ag_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tag.ag_desc
					 From tbAccountantGroup tag
						WHERE	tag.comp_id= @comp_id
						AND tag.ag_id= @ag_id)
			END		[params14],

			ISNULL(@page_index,1) [params15]



END
GO



CREATE procedure [dbo].[spAccounting_getReport_MajorAccBook]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@acc_code_from		varchar(20),
		@acc_code_to		varchar(20),
		@ap_id				int,
		@hacc_date_from		datetime,
		@hacc_date_to		datetime,
		@acc_count_id		Int,
		@ag_id				INT,
		@cc_code			INT,
		@option				bit,		-- Toma en cuenta saldos anteriores
		@option2			int,		-- Todos los movimientos o solo totales
		@bra_id				INT,
		@intBranch4Lang		INT,
		@strAccountantMultipleSelector VARCHAR(MAX)


)
as



BEGIN

	SET NOCOUNT ON

	set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------





-- ----------------------------------------------------------------------------
-- Testing
-- ----------------------------------------------------------------------------
/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			int,
			@ap_id				int,
			@hacc_date_from		datetime,
			@hacc_date_to		datetime,
			@acc_code_from		varchar(100),
			@acc_code_to		varchar(20),
			@acc_count_id		int,
			@dacc_dc			datetime,
			@ag_id				Int,
			@cc_code			NVARCHAR(20),
			@bra_id				INT,
			@option				bit,									-- Saldos anteriores
			@option2			INT,									-- Opcion todos los movimientos o solo totales
			@intBranch4Lang		INT,
			@strAccountantMultipleSelector VARCHAR(MAX)





	SELECT	@comp_id			=1,
			@lang_id			=2,
			@page_id			=10003,

			@ap_id				=47,
			@hacc_date_from		='2000-01-01',
			@hacc_date_to		='2023-12-31',
			@acc_code_from		='1000000000',
			@acc_code_to		='erwerw',
			@acc_count_id		= -1,
			@ag_id				= -1,
			@cc_code			= -1,
			@bra_id				= 1,
			@option				= 'True',
			@option2			= 1,
			@intBranch4Lang		= 1,
			@strAccountantMultipleSelector = '-1'

			--DROP TABLE #tmp
	*/
-- ----------------------------------------------------------------------------

	set	@hacc_date_from = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_from,'False')
	set	@hacc_date_to	= dbo.fnGetEnd_or_BeginOfDate(@hacc_date_to,'True')



	-- Obtiene la primera fecha valida del periodo contable.-
	DECLARE @hacc_date_Begin	AS DATETIME
	DECLARE @hacc_date_Begin2	AS DATETIME

	SELECT @hacc_date_Begin = TAP.ap_firstdate
	FROM tbAccountantPeriod tap
	WHERE	tap.comp_id = @comp_id
		AND TAP.ap_id	= @ap_id

	SET @hacc_date_Begin  = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_Begin,0)
	SET @hacc_date_Begin2 = dbo.fnGetEnd_or_BeginOfDate( dateadd(DAY,-1, @hacc_date_from),1)


	SET @hacc_date_from   = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_from,0)
	SET @hacc_date_to     = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_to,1)
	-- ------------------------------------------------------



	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbItemClass
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpAccountant TABLE(acc_count_id INT PRIMARY KEY)
	IF @strAccountantMultipleSelector = '-1' OR @strAccountantMultipleSelector = ''
		BEGIN
			INSERT INTO @tmpAccountant (acc_count_id)	SELECT ta.acc_count_id
			                                  				FROM tbAccountant ta	WITH (NOLOCK)
		END
	ELSE
		BEGIN
			INSERT INTO @tmpAccountant ( acc_count_id)	SELECT items
			                                  		FROM dbo.fnSplitTable(@strAccountantMultipleSelector,',') fst
		END
	-- -------------------------------------------------------------------------------------




	DECLARE @fun_id INT
	SET		@fun_id = 1

	IF @option2 = 1

		BEGIN 	/* todos los movimientos */


			SELECT  1																[Order]	,
					convert(VARCHAR(MAX),AC.acc_code)								[acc_code],
					convert(varchar(MAX),AC.acc_desc)								[acc_desc],
					CONVERT(NVARCHAR(MAX),'')										[hacc_number],
					Max(A.hacc_date)												[hacc_date],
					CONVERT(NVARCHAR(MAX),'Acumulado')								[hacc_detail],
					CONVERT(NVARCHAR(MAX),'Acumulado')								[acc_detail1],
					IsNull(Sum(T.dacc_debit),convert(decimal(19,4),0))				[dacc_debit],
					IsNull(Sum(T.dacc_credit),convert(decimal(19,4),0))				[dacc_credit],
					0																[dacc_transaction],
					CONVERT(NVARCHAR(MAX),'Nota')									[acc_Note],
					CONVERT(NVARCHAR(MAX),'Nota Ad')								[acc_NoteAd],
					CONVERT(NVARCHAR(MAX),'Centro de Costo')						[cc_desc],
					GETDATE()														[ct_date]
				INTO #tmp
				FROM	dbo.tbAccountTransactionDetail			T					WITH (NOLOCK)

					INNER JOIN @tmpAccountant tmp
						ON tmp.acc_count_id = t.acc_count_id

					INNER JOIN [tbAccountTransactionHead]	A					WITH (NOLOCK)
						ON	T.[hacc_transaction]	= A.[hacc_transaction]
						AND T.[comp_id]				= A.[comp_id]

					INNER JOIN tbAccountant					AC					WITH (NOLOCK)
						ON	A.comp_id				= AC.comp_id
						AND T.acc_count_id			= AC.acc_count_id



			WHERE		t.[comp_id]		= @comp_id
				AND		(@ap_id =-1 or A.[ap_id]		= @ap_id)
				AND		A.[hacc_date]	between @hacc_date_begin		and @hacc_date_begin2
				AND		AC.[acc_code]	between	@acc_code_from	and @acc_code_to
				And     (@ag_id = -1 OR A.ag_id = @ag_id)
				AND
					CASE	-- Esto esta para que no acumule cuando se pide todo el ejercicio.!
						WHEN @hacc_date_from = @hacc_date_Begin	 THEN 'False'
						ELSE 'True'
					END	   = 'True'
			AND     (@cc_code	= -1 OR T.cc_code = @cc_code)
			AND		@option		= 1	-- Si se toma en cuenta los saldos anteriores.!

			GROUP BY	 AC.acc_code,
						 AC.acc_desc



			INSERT INTO #tmp
				(
					[ORDER],
					acc_code,
					acc_desc,
					hacc_number,
					hacc_date,
					hacc_detail,
					acc_detail1,
					dacc_debit,
					dacc_credit,
					dacc_transaction,
					acc_Note,
					acc_NoteAd,
					cc_desc,
					ct_date
				)

			SELECT  2,
					AC.acc_code,
					AC.acc_desc																	[acc_desc],
					A.hacc_number,
					A.hacc_date,
					CASE
					    WHEN T.ct_transaction	IS NULL		THEN IsNull(A.hacc_detail,'')
					    WHEN tct.cust_id		IS NOT null THEN tc.cust_name
					    WHEN tct.supp_id		IS NOT NULL THEN ts.supp_name
					    WHEN tct.ba_id			IS NOT NULL THEN tba.ba_desc
					    ELSE  IsNull(A.hacc_detail,'')
					END																			[hacc_detail],
					IsNull(T.[acc_detail1],'')													[acc_detail1],
					T.dacc_debit,
					T.dacc_credit,
					t.dacc_transaction,
					IsNull(	(SELECT TOP 1 tctn.ctn_note1
								FROM tbCommercialTransactionNotes		tctn		WITH (NOLOCK)
					       		WHERE	tctn.comp_id		= t.comp_id AND
					       				tctn.ct_transaction = t.ct_transaction),'')				[acc_Note],			-- MOS 15-02-2016
					IsNull(T.acc_detail2,'')													[acc_NoteAd],
					IsNull(tcc.cc_desc,'')														[cc_desc],
					CASE
					    WHEN tct.ct_date	IS NOT NULL		THEN	tct.ct_date
						ELSE										a.hacc_cd
					END																			[ct_date]			--  fecha de carga del comprobante

			FROM	dbo.tbAccountTransactionDetail			T						WITH (NOLOCK)

					INNER JOIN @tmpAccountant tmp
						ON tmp.acc_count_id = t.acc_count_id
					INNER JOIN [tbAccountTransactionHead]	A						WITH (NOLOCK)
						ON	T.[hacc_transaction]	= A.[hacc_transaction]
						AND T.[comp_id]				= A.[comp_id]
					INNER JOIN tbAccountant					AC						WITH (NOLOCK)
						ON	A.comp_id				= AC.comp_id
						AND T.acc_count_id			= AC.acc_count_id
					LEFT JOIN tbCommercialTransactions tct							WITH (NOLOCK)
						ON	tct.comp_id				= T.comp_id			AND
							tct.ct_transaction		= T.ct_transaction
					LEFT JOIN tbSupplier ts											WITH (NOLOCK)
						ON	ts.comp_id				= tct.comp_id AND
							ts.supp_id				= tct.supp_id
					LEFT JOIN tbCustomer tc											WITH (NOLOCK)
						ON	tc.comp_id				= tct.comp_id AND
							tc.cust_id				= tct.cust_id
					LEFT JOIN tbBankingAccounts tba									WITH (NOLOCK)
						ON tba.comp_id				= tct.comp_id AND
						   tba.ba_id				= tct.ba_id
					LEFT JOIN tbCostCenter						tcc					WITH (NOLOCK)
					ON		tcc.comp_id				= T.comp_id AND
							tcc.cc_code				= T.cc_code



			WHERE		t.[comp_id]		= @comp_id
				AND		(@ap_id =-1 or A.[ap_id]		= @ap_id)
				AND		A.[hacc_date]	between @hacc_date_from	and @hacc_date_to
				AND		AC.[acc_code]	between	@acc_code_from	and @acc_code_to
				And     (@ag_id = -1 OR A.ag_id = @ag_id)

-- --------------------------------------------------------------------
-- Deshabilitado por MOS ya que hacia tardar INFINITAMENTE este listado
-- --------------------------------------------------------------------
--				AND		(@acc_count_id	= -1 or T.[hacc_transaction] in (select	distinct td.[hacc_transaction]
--																		from [tbAccountTransactionDetail] td
--																		where td.[acc_count_id] = @acc_count_id))
-- --------------------------------------------------------------------

			AND     (@cc_code = -1 OR T.cc_code = @cc_code)
			ORDER BY /*A.hacc_number,*/A.hacc_date,T.dacc_transaction,t.dacc_credit,t.dacc_debit ASC


			SELECT *

				FROM #tmp

				ORDER BY [Order],hacc_date,dacc_transaction,dacc_credit,dacc_debit
			DROP TABLE #tmp


	END

		ELSE

	BEGIN 	/* solo totales */


			SELECT
						AC.acc_code,
						AC.acc_desc,
						' '							[hacc_number],
					    Max(a.hacc_date)			[hacc_date],
						' '							[hacc_detail],
						' '							[acc_detail1],
						sum(T.dacc_debit)			[dacc_debit],
						sum(T.dacc_credit)			[dacc_credit],
						' '							[acc_Note],
						' '							[acc_NoteAd],
						' '							[cc_desc],
						' '							[ct_date]

				FROM	dbo.tbAccountTransactionDetail			T				WITH (NOLOCK)

						INNER JOIN @tmpAccountant				tmp
						ON tmp.acc_count_id			= t.acc_count_id

						INNER JOIN [tbAccountTransactionHead]	A				WITH (NOLOCK)
						ON	T.[hacc_transaction]	= A.[hacc_transaction]
						AND T.[comp_id]				= A.[comp_id]

						INNER JOIN tbAccountant					AC				WITH (NOLOCK)
						ON	A.comp_id				= AC.comp_id
						AND T.acc_count_id			= AC.acc_count_id






				WHERE	t.[comp_id]		= @comp_id
				AND		(@ap_id =-1 or A.[ap_id]		= @ap_id)
				AND		A.[hacc_date]	between /*@hacc_date_from*/	@hacc_date_Begin	and @hacc_date_to
				AND		AC.[acc_code]	between	@acc_code_from	and @acc_code_to
				And     (@ag_id = -1 OR A.ag_id = @ag_id)

-- --------------------------------------------------------------------
-- Deshabilitado por MOS ya que hacia tardar INFINITAMENTE este listado
-- --------------------------------------------------------------------
--				AND		(@acc_count_id	= -1 or T.[hacc_transaction] in (select	distinct td.[hacc_transaction]
--																		 from [tbAccountTransactionDetail] td
--																		 where td.[acc_count_id] = @acc_count_id))
-- --------------------------------------------------------------------

				AND     (@cc_code = -1 OR T.cc_code = @cc_code)


				GROUP BY AC.acc_code,
						 AC.acc_desc,
						 YEAR(a.hacc_date),
						 MONTH(a.hacc_date)

				ORDER BY AC.acc_code,YEAR(a.hacc_date),month(a.hacc_date)      --/*A.hacc_number,*/A.hacc_date ASC




	END



--RETURN


----------
--'01' + '/' + convert(VARCHAR,datepart(MONTH, a.hacc_date)) + '/' + convert(varchar,datepart(YEAR,a.hacc_date))

	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/



	Select

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  			 WHERE t.ctrl_id = 378
  			 --AND t.[lang_id] = @lang_id
  			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],


			(select ltrim(rtrim(acc_code)) + '-' + acc_desc from tbAccountant where acc_code = @acc_code_from AND comp_id = @comp_id)
																			[params2],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  			 WHERE t.ctrl_id = 379
  			 --AND t.[lang_id] = @lang_id
  			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],


			(select ltrim(rtrim(acc_code)) + '-' + acc_desc from tbAccountant where acc_code = @acc_code_to AND comp_id = @comp_id)
																			[params4],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  			 WHERE t.ctrl_id = 380
  			 --AND t.[lang_id] = @lang_id
  			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],


			CASE @ap_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				   (SELECT		tap.ap_desc
					FROM	tbAccountantPeriod tap
					WHERE	tap.comp_id = @comp_id
					And     tap.ap_id=@ap_id)
			END															[params6],

					'' [params6],
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  			 WHERE t.ctrl_id = 177
  			 --AND t.[lang_id] = @lang_id
  			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)	[params7],

			@hacc_date_from [DateParams1],
			--convert(varchar,day(@hacc_date_from)) + '/' + convert(varchar,month(@hacc_date_from)) + '/' + convert(varchar,year(@hacc_date_from))		[params8],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  			 WHERE t.ctrl_id = 384
  			 --AND t.[lang_id] = @lang_id
  			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

			--convert(varchar,day(@hacc_date_to)) + '/' + convert(varchar,month(@hacc_date_to)) + '/' + convert(varchar,year(@hacc_date_to))		[params10],
			@hacc_date_to [DateParams2],



				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  			 WHERE t.ctrl_id = 387
  			 --AND t.[lang_id] = @lang_id
  			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],
				 CASE @acc_count_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tca.acc_code
						FROM	tbAccountant tca
						WHERE	tca.comp_id= @comp_id
						AND tca.acc_count_id= @acc_count_id)
			END		[params12],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  			 WHERE t.ctrl_id = 1027
  			 --AND t.[lang_id] = @lang_id
  			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params13],
			 CASE @ag_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tag.ag_desc
					 From tbAccountantGroup tag
						WHERE	tag.comp_id= @comp_id
						AND tag.ag_id= @ag_id)
			END		[params14],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  			 WHERE t.ctrl_id = 1515
  			 --AND t.[lang_id] = @lang_id
  			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params15],
			 CASE @cc_code WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tcc.cc_desc
					 From tbCostCenter tcc
						WHERE	tcc.comp_id= @comp_id
						AND tcc.cc_code = @cc_code)
			END		[params16],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  			 WHERE t.ctrl_id = 1633
  			 --AND t.[lang_id] = @lang_id
  			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params17],
			 CASE @option2 WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
					 From tbsysOptionsValues tov
						WHERE	tov.lang_id=@lang_id
						AND		tov.optval_id= @option2 and tov.optval_class = 121)
			END		[params18],



			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  			 WHERE t.ctrl_id = 991
  			 --AND t.[lang_id] = @lang_id
  			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params19],
			 CASE @option WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
					 From tbsysOptionsValues tov
						WHERE	tov.lang_id=@lang_id
						AND		tov.optval_id= @option and tov.optval_class = 1)
			END		[params20]



END
GO






