-- =============================================
-- Author:		MOH
--              MOS  06-3-08
-- Create date: <Create Date,,>
-- Description:	Este procedimiento no graba nada
-- solo llama a otros SP que si hacen los INSERT
-- =============================================

CREATE  PROCEDURE [dbo].[spAccounting_insertData]
(
	@dacc_guid						uniqueidentifier,
	@comp_id						int,
	@bra_id							int,
	@hacc_group						int,
	@hacc_detail					varchar(60),
	@hacc_date						datetime,
	@hacc_number					int,
	@hacc_orderPriority				decimal(5,0),
	@ap_id							int,
	@hacc_blocked					bit,
	@hacc_closing					bit,
	@hacc_opening					bit,
	@hacc_IsEditing					bit,
	@hacc_IsEditingDateTime			datetime,
	@hacc_2ndCurrencyExchange		DECIMAL(19,6),
	@user_id						INT,
	@return_value					int output
)
AS

BEGIN

	-- Es un Insert, el IsEditing debe estar en FALSE.!
	SET @hacc_IsEditing = 'false'

	set nocount on

	BEGIN TRANSACTION
	BEGIN TRY


		declare @lhacc_transaction int


		-- inserto datos en Header
		exec	dbo.spAccountTransactionHead_insertData
 				@comp_id,					@bra_id,			@hacc_group,
 				@hacc_detail,				@hacc_date,			@hacc_number,
 				@hacc_orderPriority,		@ap_id,				@hacc_blocked,
 				@hacc_closing,				@hacc_opening,		@hacc_IsEditing,
 				@hacc_IsEditingDateTime,	@hacc_2ndCurrencyExchange,
 				@return_value		= @lhacc_transaction output


		UPDATE tbAccountTransactionHead
			SET USER_ID			= @user_id,
				hacc_lastUpdate = GETDATE()
			WHERE	comp_id				= @comp_id	AND
					bra_id				= @bra_id	AND
					hacc_transaction	= @lhacc_transaction

		--select	@lhacc_transaction


		-- declareción de variables para obtener los datos del cursor
		declare @lcomp_id					int,
				@ldacc_guid					uniqueidentifier,
				@ldacc_transaction			int,
				@lacc_count_id				int,
				@lcc_code					int,
				@ldacc_debit				decimal(18,4),
				@ldacc_credit				decimal(18,4),
				@lUSER_ID					int,
				@ldacc_cd					datetime,
				@lhacc_software				bit,
				@lct_transaction			int,
				@lacc_detail1				varchar(100),
				@lacc_detail2				varchar(100),
				@ldacc_2ndCurrencyExchange	DECIMAL(19,6),
				@lrv						INT



		-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
		declare cursor_AiD_items CURSOR  LOCAL FAST_FORWARD for

		select	comp_id,
				dacc_guid,
				dacc_transaction,
				acc_count_id,
				cc_code,
				dacc_debit,
				dacc_credit,
				user_id,
				dacc_cd,
				hacc_software,
				ct_transaction,
				dacc_2ndCurrencyExchange,
				acc_detail1,
				acc_detail2

		from	tbAccountTransactionDetailTmp
		where	dacc_guid = @dacc_guid


		open	cursor_AiD_items


		-- lectura anticipada del cursor
		fetch	cursor_AiD_items
		into
				@lcomp_id,
				@dacc_guid,
				@ldacc_transaction,
				@lacc_count_id,
				@lcc_code,
				@ldacc_debit,
				@ldacc_credit,
				@luser_id,
				@ldacc_cd,
				@lhacc_software,
				@lct_transaction,
				@ldacc_2ndCurrencyExchange,
				@lacc_detail1,
				@lacc_detail2


		-- se recorre el cursor hasta el fin del mismo
		while   @@fetch_status = 0
		begin

			-- por cada registro del cursor se realiza el insert en spAccountTransactionDetail
			exec	dbo.spAccountTransactionDetail_insertData
					@lcomp_id,			@bra_id,			@lhacc_transaction,
					@lacc_count_id,		@lcc_code,			@ldacc_debit,
					@ldacc_credit,		@luser_id,			@lhacc_software,
					@lct_transaction,	@lacc_detail1,		@lacc_detail2,
					@ldacc_2ndCurrencyExchange,
					@return_value		= @lrv output

			-- por cada registro del cursor se realiza el delete de spAccountTransactionDetailTmp
			exec	dbo.spAccountTransactionDetailTmp_deleteData  @ldacc_transaction


			-- próxima lectura del cursor
			fetch	cursor_AiD_items
			into	@lcomp_id,
					@dacc_guid,
					@ldacc_transaction,
					@lacc_count_id,
					@lcc_code,
					@ldacc_debit,
					@ldacc_credit,
					@luser_id,
					@ldacc_cd,
					@lhacc_software,
					@lct_transaction,
					@ldacc_2ndCurrencyExchange,
					@lacc_detail1,
					@lacc_detail2


		end

		close cursor_AiD_items
		deallocate cursor_AiD_items


		set	@return_value = @lhacc_transaction


		COMMIT TRANSACTION
	END TRY
	BEGIN CATCH
		ROLLBACK TRANSACTION
	END CATCH



END
GO













