		@ap_id						=1,
		@hacc_blocked				=1,
		@hacc_closing				=0,
		@hacc_opening				=0,
		@hacc_IsEditing				=0,
		@hacc_IsEditingDateTime		= convert(datetime,'07/06/2008'),
		@acc_count_id				=4104,
		@cc_code					=45,
