		@hacc_software				=0,
		@ct_transaction				=null,
		@acc_detail1				=null,
		@acc_detail2				=null
*/
set nocount on

--SELECT convert(varchar(10),hacc_date,111), convert(varchar(10),getdate(),111)
--from dbo.tbAccountTransactionHead
declare @lhacc_transaction int
--select	1 from dbo.tbAccountTransactionHead
