end

-- inserto datos en Detail
	exec dbo.spAccountTransactionDetail_insertData
		 @comp_id,				@bra_id,				@lhacc_transaction,
		 @acc_count_id,			@cc_code,				@dacc_debit,
		 @dacc_credit,			@user_id,				@hacc_software,
		 @ct_transaction,		@acc_detail1,			@acc_detail2,
		 @return_value

--select @lhacc_transaction

set	@return_value = @lhacc_transaction

--
--IF @@Error = 0
--	Commit Transaction [spAccounting_insertData]
--Else
--	ROLLBACK TRANSACTION [spAccounting_insertData]
--
--
--

GO







CREATE PROCEDURE [dbo].[spAccounting_IsEditingPurgeStatus]
AS

BEGIN



	SET  NOCOUNT  ON



	declare @DeleteTime		as	datetime
	set		@DeleteTime		=	DATEADD(minute, -3, getdate())



	-- cabeceras sin actualizar
	UPDATE	tbAccountTransactionHead	WITH(ROWLOCK)
	SET		hacc_IsEditing			= 'False'
	Where   hacc_IsEditing			= 'True'
	AND		hacc_IsEditingDateTime	< @DeleteTime



	-- cabeceras sin actualizar
	UPDATE	tbAccountTransactionHead_Type	WITH(ROWLOCK)
	SET		hacc_IsEditing			= 'False'
	Where   hacc_IsEditing			= 'True'
	AND		hacc_IsEditingDateTime	< @DeleteTime


END
GO







-- =============================================
-- Author:
--              MOS  02-5-08
-- Create date: <Create Date,,>
-- Description:	Este procedimiento no graba nada
-- solo llama a otros SP que si hacen los INSERT
-- =============================================

CREATE  PROCEDURE [dbo].[spAccounting_updateData]
(
	@dacc_guid						uniqueidentifier,
	@comp_id						int,
	@bra_id							int,
	@hacc_transaction				int,
	@hacc_group						int,
	@hacc_detail					varchar(60),
	@hacc_date						datetime,
	@hacc_number					int,
	@hacc_orderPriority				decimal(5,0),
	@ap_id							int,
	@hacc_blocked					bit,
	@hacc_closing					bit,
	@hacc_opening					bit,
	@hacc_IsEditing					bit,
	@hacc_2ndCurrencyExchange		DECIMAL(19,6),
	@user_id						INT,
	@return_value					int		output
)
AS

BEGIN

	set nocount on

	-- -------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------
	/*
	--ver como recuperamos el valor correspondiente
	declare	@dacc_guid					uniqueidentifier,
			@comp_id					int,
			@bra_id						int,
			@hacc_transaction			int,
			@hacc_group					int,
			@hacc_detail				varchar(60),
			@hacc_date					datetime,
			@hacc_number				int,
			@hacc_orderPriority			decimal(5,0),
			@hacc_cd					datetime,
			@ap_id						int,
			@hacc_blocked				bit,
			@hacc_closing				bit,
			@hacc_opening				bit,
			@hacc_IsEditing				bit,
			@hacc_2ndCurrencyExchange		DECIMAL(19,6),
			@return_value				int

	select   @dacc_guid					= 'd9a0a585-ec3e-44af-9d09-fa257c78acea',
			 @comp_id					= 1,
			 @bra_id					= 31,
			 @hacc_transaction			= 22878,
			 @hacc_group				= 10011,
			 @hacc_detail				= 'sdf fsdf wrtwer',
			 @hacc_date					= getdate (),
			 @hacc_number				= 694,
			 @hacc_orderPriority		= 0,
			 @hacc_cd					= getdate (),
			 @ap_id						= 27,
			 @hacc_blocked				= 0,
			 @hacc_closing				= 0,
			 @hacc_opening				= 0,
			 @hacc_IsEditing			= 0,
	 		 @hacc_2ndCurrencyExchange	=1
	*/
	-- -------------------------------------------------------------


	-- Es un Update, el IsEditing debe estar en FALSE.!
	SET @hacc_IsEditing = 'false'

	SET @return_value = 0


	BEGIN TRANSACTION
	BEGIN TRY




		-- ------------------------------------------------------------
		-- Inserta el HISTORICO de actualizaciones
		-- ------------------------------------------------------------
		INSERT INTO tbAccountTransactionHeadHistory
		(
			comp_id,
			bra_id,
			hacc_transaction,
			hacc_detail,
			hacc_date,
			hacc_number,
			hacc_orderPriority,
			ap_id,
			hacc_blocked,
			hacc_closing,
			ag_id,
			hacc_originalNumber,
			hacch_cd,
			hacch_user_id,
			hacch_type
		)
			SELECT 			comp_id,
							bra_id,
							hacc_transaction,
							hacc_detail,
							hacc_date,
							hacc_number,
							hacc_orderPriority,
							ap_id,
							hacc_blocked,
							hacc_closing,
							ag_id,
							hacc_originalNumber,
							GETDATE(),
							@user_id ,
							1
				FROM tbAccountTransactionHead tath		WITH (NOLOCK)
			WHERE	tath.comp_id			= @comp_id AND
					tath.hacc_transaction	= @hacc_transaction

		DECLARE @intLastHistory AS INT = @@IDENTITY

		INSERT INTO tbAccountTransactionDetailHistory
		(
			comp_id,
			hacch_id,
			bra_id,
			hacc_transaction,
			dacc_transaction,
			acc_count_id,
			cc_code,
			dacc_debit,
			dacc_credit,
			[user_id],
			dacc_cd,
			hacc_software,
			ct_transaction,
			dacc_order,
			dacc_2ndCurrencyExchange,
			acc_detail1,
			acc_detail2
		)
		SELECT
			comp_id,
			@intLastHistory,
			bra_id,
			hacc_transaction,
			dacc_transaction,
			acc_count_id,
			cc_code,
			dacc_debit,
			dacc_credit,
			[user_id],
			dacc_cd,
			hacc_software,
			ct_transaction,
			dacc_order,
			dacc_2ndCurrencyExchange,
			acc_detail1,
			acc_detail2
			FROM tbAccountTransactionDetail tatdh		WITH (NOLOCK)
		WHERE	tatdh.comp_id			= @comp_id					AND
				tatdh.hacc_transaction	= @hacc_transaction

		-- ------------------------------------------------------------





		-- ---------------------------------------------------------------------------
		-- MOH - 07-09-2012
		-- recupero el comp_id y bra_id reales del hacc_transaction porque cuando hay
		-- asientos contables de diferentes sucursales cancelaban los sps
		-- ---------------------------------------------------------------------------
		SELECT	@comp_id	= tath.comp_id,
				@bra_id		= tath.bra_id
			FROM	tbAccountTransactionHead tath		WITH (NOLOCK)
			WHERE	tath.hacc_transaction = @hacc_transaction
		-- ---------------------------------------------------------------------------



		declare @hacc_IsEditingDateTime datetime
		set @hacc_IsEditingDateTime = getdate()



		exec dbo.spAccountTransactionHead_updateData
				@comp_id,		@bra_id,				@hacc_transaction,
				@hacc_group,	@hacc_detail,			@hacc_date,
				@hacc_number,	@hacc_orderPriority,	--@hacc_cd,
				@ap_id,			@hacc_blocked,			@hacc_closing,
				@hacc_opening,  'False',				@hacc_IsEditingDateTime,
				@hacc_2ndCurrencyExchange


		UPDATE tbAccountTransactionHead		WITH (ROWLOCK)
			SET USER_ID			= @user_id,
				hacc_lastUpdate = GETDATE()
			WHERE	comp_id				= @comp_id	AND
					bra_id				= @bra_id	AND
					hacc_transaction	= @hacc_transaction


		exec dbo.spAccountTransactionDetail_deleteAllData @hacc_transaction


		-- declaración de variables para obtener los datos del cursor
		declare
				@lcomp_id						int,
				@ldacc_guid						uniqueidentifier,
				@ldacc_transaction				int,
				@lacc_count_id					int,
				@lcc_code						int,
				@ldacc_debit					decimal(18,4),
				@ldacc_credit					decimal(18,4),
				@lUSER_ID						int,
				@ldacc_cd						datetime,
				@lhacc_software					bit,
				@lct_transaction				int,
				@lacc_detail1					nvarchar(200),
				@lacc_detail2					nvarchar(200),
				@ldacc_2ndCurrencyExchange		DECIMAL(19,6),
				@lrv							int

		-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
		declare cursor_AuD_items CURSOR LOCAL FAST_FORWARD for

		select	comp_id,
				dacc_guid,
				dacc_transaction,
				acc_count_id,
				cc_code,
				dacc_debit,
				dacc_credit,
				user_id,
				dacc_cd,
				hacc_software,
				ct_transaction,
				dacc_2ndCurrencyExchange ,
				acc_detail1,
				acc_detail2

			from	tbAccountTransactionDetailTmp
			where	dacc_guid = @dacc_guid

		open	cursor_AuD_items

		-- lectura anticipada del cursor
		fetch	cursor_AuD_items
		into
				@lcomp_id,
				@dacc_guid,
				@ldacc_transaction,
				@lacc_count_id,
				@lcc_code,
				@ldacc_debit,
				@ldacc_credit,
				@luser_id,
				@ldacc_cd,
				@lhacc_software,
				@lct_transaction,
				@ldacc_2ndCurrencyExchange,
				@lacc_detail1,
				@lacc_detail2




		-- se recorre el cursor hasta el fin del mismo
		while   @@fetch_status = 0
		begin


			-- por cada registro del cursor se realiza el insert en spAccountTransactionDetail
			exec	dbo.spAccountTransactionDetail_insertData
					@comp_id,			@bra_id,			@hacc_transaction,
					@lacc_count_id,		@lcc_code,			@ldacc_debit,
					@ldacc_credit,		@luser_id,			--@ldacc_cd,
					@lhacc_software,	@lct_transaction,	@lacc_detail1,
					@lacc_detail2,		@ldacc_2ndCurrencyExchange,
					@return_value		= @lrv output


			-- por cada registro del cursor se realiza el delete de spAccountTransactionDetailTmp
			exec	dbo.spAccountTransactionDetailTmp_deleteData  @ldacc_transaction


			-- próxima lectura del cursor
			fetch	cursor_AuD_items
			into	@lcomp_id,
					@dacc_guid,
					@ldacc_transaction,
					@lacc_count_id,
					@lcc_code,
					@ldacc_debit,
					@ldacc_credit,
					@luser_id,
					@ldacc_cd,
					@lhacc_software,
					@lct_transaction,
					@ldacc_2ndCurrencyExchange,
					@lacc_detail1,
					@lacc_detail2


		end

		close cursor_AuD_items
		deallocate cursor_AuD_items


		UPDATE tbAccountTransactionHead		WITH (ROWLOCK)
			SET	hacc_IsEditing = 'false'
			WHERE   comp_id				= @comp_id AND
					hacc_transaction	= @hacc_transaction





		SET @return_value = @hacc_transaction


		COMMIT TRANSACTION

	END TRY
	BEGIN CATCH
		ROLLBACK TRANSACTION
	END CATCH


END
GO







