-- =============================================

CREATE  PROCEDURE [dbo].[spAccounting_updateNumber]
(
 	@ap_id	INT,
 	@ag_id	INT,
 	@return_value INT OUTPUT
)
as

BEGIN

	set nocount on

	/*
	declare	@ap_id			int,
			@ag_id			int,
			@return_value	INT
	select	@ap_id			= 16,
			@ag_id			= 1

	DROP TABLE #tmpNumber
	*/


	-- declaración de variables para obtener los datos del cursor
--	declare @hacc_transaction		int	,
--			@intnumber				int
--	select  @intnumber = 0


	BEGIN TRANSACTION
	BEGIN TRY





		CREATE TABLE #tmpNumber
		(
			[hacc_transaction]	[int]				NOT NULL,
			[tmpNumber_id]		[int] IDENTITY(1,1) NOT NULL
		)



		INSERT INTO #tmpNumber
		(
			hacc_transaction
		)
		SELECT	hacc_transaction
		FROM 	dbo.tbAccountTransactionHead		WITH (NOLOCK)
		WHERE 	ap_id			= @ap_id
		AND		ag_id			= @ag_id
		AND		hacc_IsEditing	= 'false'
		ORDER BY	CONVERT(DATE, hacc_date),
					hacc_orderPriority



		UPDATE 	tbAccountTransactionHead
		SET 	hacc_number		= n.tmpNumber_id
		FROM	tbAccountTransactionHead tath
				INNER JOIN #tmpNumber  n
				ON	n.hacc_transaction = tath.hacc_transaction



		COMMIT TRANSACTION
		set	@return_value = 0

	END TRY
	BEGIN CATCH
		set	@return_value = -1
		ROLLBACK TRANSACTION
	END CATCH

END
GO






