CREATE PROCEDURE [dbo].[spAccounting_validateData]
(
	@dacc_guid					uniqueidentifier,
	@date						datetime,
	@dateInitPeriod				datetime,
	@dateFinalPeriod			datetime,
	@return_value				int output
)
as

--Begin Transaction [spAccounting_insertData]
set nocount on

/*
declare		@dacc_guid					uniqueidentifier,
			@return_value				int

select @dacc_guid = 'e61b1583-8fb0-4f99-a849-13d72a000ba3'
*/

declare		@dacc_debit					decimal(18,4),
			@dacc_credit				decimal(18,4)

if exists (select 1 from dbo.tbAccountTransactionDetailTmp where	dacc_guid = @dacc_guid)
begin
	set		@dacc_debit = (select	ISNULL(sum(dacc_debit),0)
	from	dbo.tbAccountTransactionDetailTmp
	where	[dacc_guid] = @dacc_guid)
--group by dacc_guid

	set		@dacc_credit = (select	isnull(sum(dacc_credit),0)
	from	dbo.tbAccountTransactionDetailTmp
	where	[dacc_guid] = @dacc_guid)

	--select @dacc_credit, @dacc_debit

	if @dacc_credit = @dacc_debit
		set @return_value = 0
	else
		set @return_value = 1

end

else

begin
	set @return_value = 2
end

/*
set dateformat 'mdy'
