select  @return_value				=0,
		@date						='10/15/2008',
		@dateInitPeriod				='09/10/2008',
		@dateFinalPeriod			='12/31/2008'
*/

if @return_value = 0 and (@date < @dateInitPeriod or @date > @dateFinalPeriod)
	set @return_value = 3

	--SELECT @return_value

GO







-- =================================================================================================================
-- Author		: GA
-- UpdateDate	: 07-02-2013
-- Description	: Reporte para asientos contables.
--cuando generen un nuevo asiento contable sale un reporte con los datos del header del mismo y el detalle.
-- =================================================================================================================





CREATE procedure [dbo].[spAccountingHeader_getReport]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,
	@bra_id				int,
	@hacc_transaction	int,
	@intBranch4Lang		int
)
AS


BEGIN


	SET NOCOUNT ON



		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


-- -------------------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------------------
/*

	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			int,
			@bra_id				int,
			@hacc_transaction	int

	SELECT	@comp_id			=1,
			@lang_id			=2,
			@page_id			=10093,
			@bra_id				=1,
			@hacc_transaction	=989
	*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------


	select	tath.hacc_number														[hacc_number],
			tath.hacc_date															[hacc_date],
			isnull(tath.hacc_detail,'')												[hacc_detail],
			isnull(tap.ap_desc,'')													[ap_desc],
			tov1.optval_desc														[hacc_closing],
			tov2.optval_desc														[hacc_blocked],
			--tath.hacc_closing														[hacc_closing],
			--tath.hacc_blocked														[hacc_blocked],
			isnull(ta.acc_desc,'')													[acc_desc],
			tatd.dacc_debit															[dacc_debit],
			tatd.dacc_credit														[dacc_credit],
			tatd.acc_detail1														[acc_detail1],
			ltrim(rtrim(tb.bra_address)) + ' (' + ltrim(rtrim(tb.bra_zip)) + ')'	[bra_address],
			tb.bra_phone															[bra_phone]



	from tbAccountTransactionHead								tath

	inner join tbAccountTransactionDetail						tatd
	on  tatd.comp_id			= tath.comp_id
	AND tatd.bra_id				= tath.bra_id
	AND tatd.hacc_transaction	= tath.hacc_transaction

	inner join tbBranch											tb
	on  tb.comp_id				= tath.comp_id
	AND tb.bra_id				= tatd.bra_id

	inner join tbAccountant										ta
	on  ta.comp_id				= tatd.comp_id
	AND ta.acc_count_id			= tatd.acc_count_id

	inner join tbAccountantPeriod								tap
	on  tap.comp_id				= tath.comp_id
	and tap.ap_id				= tath.ap_id

	inner join tbsysOptionsValues								tov1
	on  tov1.optval_class		= 137
	and tov1.lang_id			= @lang_id
	and tov1.optval_id			= tath.hacc_closing

	inner join tbsysOptionsValues								tov2
	on  tov2.optval_class		= 137
	and tov2.lang_id			= @lang_id
	and tov2.optval_id			= tath.hacc_blocked


	where tath.comp_id			= @comp_id
	--and tath.bra_id				= @bra_id		-- NO porque pasan la puta sucurtsal de sesion y no la del puto asiento
	and tath.hacc_transaction	= @hacc_transaction




	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id



END


GO





CREATE procedure [dbo].[spAccountingPurchaseWithDifferentDate_getReport]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,

	@ap_id				int,
	@ag_id				INT,

	@bra_id				INT,
	@intBranch4Lang		int

)
AS


BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount ON

		--set	@hacc_date_from = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_from,'False')
		--set	@hacc_date_to = dbo.fnGetEnd_or_BeginOfDate(@hacc_date_to,'True')


----------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------
/*
DECLARE @comp_id			int,
		@lang_id			int,
		@page_id			int,
		@ap_id				int,
		@ag_id				INT,
		@bra_id				INT,
		@intBranch4Lang		int

SELECT	@comp_id			=1,
		@lang_id			=2,
		@page_id			=100962,
		@ap_id				=36,
		@ag_id				=-1,
		@bra_id				= 1,
		@intBranch4Lang		= 1
*/
----------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------

	DECLARE @fun_id INT
	SET @fun_id = 1



	SELECT
		CONVERT(NVARCHAR,tath.hacc_number,100) [hacc_number],
		tath.hacc_detail,
		tath.hacc_date,
		tac.acc_code ,
		tac.acc_desc,
		tatd.acc_detail1,
		tatd.dacc_debit,
		tatd.dacc_credit

		FROM tbCommercialTransactions								tct		WITH (NOLOCK)

		INNER JOIN tbAccountTransactionDetail						tatd	WITH (NOLOCK)
			ON tatd.ct_transaction = tct.ct_transaction

		INNER JOIN tbAccountTransactionHead							tath	WITH (NOLOCK)
			ON tath.hacc_transaction = tatd.hacc_transaction

		INNER JOIN tbAccountant										tac		WITH (NOLOCK)
			ON	tath.comp_id				= tac.comp_id
			AND tatd.acc_count_id			= tac.acc_count_id

		WHERE tct.comp_id	= @comp_id										AND
			  tct.sd_id		= 101											AND
			  tct.bra_id	= @bra_id										AND
			  convert(date,tct.ct_taxDate) <> CONVERT(date,tath.hacc_date)	AND
			  (@ap_id		= -1	OR	tath.ap_id = @ap_id)				AND
			  (@ag_id		= -1	OR	tath.ag_id = @ag_id)


		ORDER BY	tath.hacc_number




	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id
	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 380
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params1],

      		 CASE @ap_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					   (SELECT		tap.ap_desc
						FROM	tbAccountantPeriod tap
						WHERE	tap.comp_id = @comp_id
						And     tap.ap_id=@ap_id)
				END															[params2],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1027
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],
			 CASE @ag_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tag.ag_desc
					 From tbAccountantGroup tag
						WHERE	tag.comp_id= @comp_id
						AND tag.ag_id= @ag_id)
			END		[params14]



END
GO







CREATE PROCEDURE [dbo].[spAccountingType_deleteData]
(
	@hacc_transaction			int,
	@dacc_guid					uniqueidentifier
)
as
set nocount OFF


-- -------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------
/*
declare
	@hacc_transaction			int,
	@dacc_guid					uniqueidentifier,
	@comp_id					int
select
	@hacc_transaction			= 2,
	@dacc_guid					= '6c03c856-fa3b-41b6-9117-4d6fe3e902a6',
	@comp_id					= 1
*/
-- -------------------------------------------------------------

BEGIN TRANSACTION
BEGIN TRY

	exec dbo.spAccountTransactionDetailTmp_deleteAllData		@dacc_guid

	exec dbo.spAccountTransactionDetailType_deleteAllData 		@hacc_transaction

	if @hacc_transaction <> -1
		exec dbo.spAccountTransactionHeadType_deleteData		@hacc_transaction


	COMMIT TRANSACTION

END
TRY BEGIN CATCH
	ROLLBACK TRANSACTION
END CATCH






GO






CREATE PROCEDURE [dbo].[spAccountingType_getDataById]
(
	@hacc_transaction		int,
	@dacc_guid				uniqueidentifier
)
as
set nocount on


-- ------------------------------------------------------------------------
-- Testing
-- ------------------------------------------------------------------------
/*
declare @hacc_transaction		int ,
		@dacc_guid				uniqueidentifier
select  @hacc_transaction		= 2,
		@dacc_guid				='e532c8ea-7cda-473f-b46c-44e81ef06c0a'

declare @datetime	datetime
select	@datetime = getdate()
*/
-- ------------------------------------------------------------------------


--Controlar que el asiento seleccionado no esté siendo editado por otro usuario
IF exists (select 1 from dbo.tbAccountTransactionHead_Type where hacc_transaction = @hacc_transaction and hacc_IsEditing = 'False' )

	begin

		--recuperar los valores de la cabecera del asiento seleccionado
		exec dbo.spAccountTransactionHeadType_getDataById @hacc_transaction


		exec dbo.spAccountTransactionHeadType_updateIsEditing @hacc_transaction, 'True'
		--actualizar el estado para indicar que el registro está tomado
	--	update	dbo.tbAccountTransactionHead
	--	set		hacc_IsEditing			= 'True',
	--			hacc_IsEditingDateTime	= getdate()
	--	where 	hacc_transaction		= @hacc_transaction


		-- declaración de variables para obtener los datos del cursor
		declare	@lcomp_id				int,
				@lbra_id				int,
				@ldacc_guid				uniqueidentifier,
				@ldacc_transaction		int,
				@lacc_count_id			int,
				@lcc_code				int,
				@ldacc_debit			decimal(18,4),
				@ldacc_credit			decimal(18,4),
				@lUSER_ID				int,
				@ldacc_cd				datetime,
				@lhacc_software			bit,
				@lct_transaction		int,
				@lacc_detail1			nvarchar(200),
				@lacc_detail2			nvarchar(200),
				@ldacc_2ndCurrencyExchange		DECIMAL(19,6),
				@lrv							int


		-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
		declare cursor_AgDBI_items CURSOR  LOCAL FAST_FORWARD  for
		select	comp_id,
				bra_id,
				dacc_transaction,
				acc_count_id,
				cc_code,
				dacc_debit,
				dacc_credit,
				user_id,
				dacc_cd,
				hacc_software,
				ct_transaction,
				IsNull(acc_detail1,'')				[acc_detail1],
				IsNull(acc_detail2,'')				[acc_detail2],
				dacc_2ndCurrencyExchange

		from	tbAccountTransactionDetail_Type
		where	hacc_transaction = @hacc_transaction


		open	cursor_AgDBI_items

		-- lectura anticipada del cursor
		fetch	cursor_AgDBI_items
		into	@lcomp_id,
				@lbra_id,
				@ldacc_transaction,
				@lacc_count_id,
				@lcc_code,
				@ldacc_debit,
				@ldacc_credit,
				@luser_id,
				@ldacc_cd,
				@lhacc_software,
				@lct_transaction,
				@lacc_detail1,
				@lacc_detail2,
				@ldacc_2ndCurrencyExchange


		-- se recorre el cursor hasta el fin del mismo
		while   @@fetch_status = 0
		begin


			-- por cada registro del cursor se realiza el insert en spAccountTransactionDetailTmp
			exec	dbo.spAccountTransactionDetailTmp_insertData

					@lcomp_id ,		@dacc_guid,			@lacc_count_id,
					@lcc_code,		@luser_id ,			@ldacc_debit,
					@ldacc_credit,	@lhacc_software,	@lct_transaction ,
					@ldacc_2ndCurrencyExchange,
					@lacc_detail1,@lacc_detail2 ,
					@return_value	= @lrv output


			-- próxima lectura del cursor
			fetch	cursor_AgDBI_items
			into	@lcomp_id,
					@lbra_id,
					@ldacc_transaction,
					@lacc_count_id,
					@lcc_code,
					@ldacc_debit,
					@ldacc_credit,
					@luser_id,
					@ldacc_cd,
					@lhacc_software,
					@lct_transaction,
					@lacc_detail1,
					@lacc_detail2,
					@ldacc_2ndCurrencyExchange

		end

		close cursor_AgDBI_items
		deallocate cursor_AgDBI_items

select * from tbAccountTransactionDetailTmp tatdt where tatdt.dacc_guid = @dacc_guid


	end

else

	BEGIN

		exec dbo.spAccountTransactionHead_getDataById @hacc_transaction

	END

GO





CREATE  PROCEDURE [dbo].[spAccountingType_insertData]
(
	@dacc_guid						uniqueidentifier,
	@comp_id						int,
	@bra_id							int,
	@hacc_group						int,
	@hacc_detail					varchar(60),
	@hacc_date						datetime,
	@hacc_number					int,
	@hacc_orderPriority				decimal(5,0),
	@ap_id							int,
	@hacc_blocked					bit,
	@hacc_closing					bit,
	@hacc_opening					bit,
	@hacc_IsEditing					bit,
	@hacc_IsEditingDateTime			datetime,
	@hacc_2ndCurrencyExchange		DECIMAL(19,6),
	@return_value					int output
)
AS

BEGIN

	-- Es un Insert, el IsEditing debe estar en FALSE.!
	SET @hacc_IsEditing = 'false'

	set nocount on

	BEGIN TRANSACTION
	BEGIN TRY


		declare @lhacc_transaction int


		-- inserto datos en Header
		exec	dbo.spAccountTransactionHeadType_insertData
 				@comp_id,					@bra_id,			@hacc_group,
 				@hacc_detail,				@hacc_date,			@hacc_number,
 				@hacc_orderPriority,		@ap_id,				@hacc_blocked,
 				@hacc_closing,				@hacc_opening,		@hacc_IsEditing,
 				@hacc_IsEditingDateTime,	@hacc_2ndCurrencyExchange,
 				@return_value		= @lhacc_transaction output


		--select	@lhacc_transaction


		-- declareción de variables para obtener los datos del cursor
		declare @lcomp_id					int,
				@ldacc_guid					uniqueidentifier,
				@ldacc_transaction			int,
				@lacc_count_id				int,
				@lcc_code					int,
				@ldacc_debit				decimal(18,4),
				@ldacc_credit				decimal(18,4),
				@lUSER_ID					int,
				@ldacc_cd					datetime,
				@lhacc_software				bit,
				@lct_transaction			int,
				@lacc_detail1				varchar(100),
				@lacc_detail2				varchar(100),
				@ldacc_2ndCurrencyExchange	DECIMAL(19,6),
				@lrv						INT



		-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
		declare cursor_AiD_items cursor for

		select	comp_id,
				dacc_guid,
				dacc_transaction,
				acc_count_id,
				cc_code,
				dacc_debit,
				dacc_credit,
				user_id,
				dacc_cd,
				hacc_software,
				ct_transaction,
				dacc_2ndCurrencyExchange,
				acc_detail1,
				acc_detail2

		from	tbAccountTransactionDetailTmp
		where	dacc_guid = @dacc_guid


		open	cursor_AiD_items


		-- lectura anticipada del cursor
		fetch	cursor_AiD_items
		into
				@lcomp_id,
				@dacc_guid,
				@ldacc_transaction,
				@lacc_count_id,
				@lcc_code,
				@ldacc_debit,
				@ldacc_credit,
				@luser_id,
				@ldacc_cd,
				@lhacc_software,
				@lct_transaction,
				@ldacc_2ndCurrencyExchange,
				@lacc_detail1,
				@lacc_detail2


		-- se recorre el cursor hasta el fin del mismo
		while   @@fetch_status = 0
		begin

			-- por cada registro del cursor se realiza el insert en spAccountTransactionDetail
			exec	dbo.spAccountTransactionDetailType_insertData
					@lcomp_id,			@bra_id,			@lhacc_transaction,
					@lacc_count_id,		@lcc_code,			@ldacc_debit,
					@ldacc_credit,		@luser_id,			@lhacc_software,
					@lct_transaction,	@lacc_detail1,		@lacc_detail2,
					@ldacc_2ndCurrencyExchange,
					@return_value		= @lrv output

			-- por cada registro del cursor se realiza el delete de spAccountTransactionDetailTmp
			exec	dbo.spAccountTransactionDetailTmp_deleteData  @ldacc_transaction


			-- próxima lectura del cursor
			fetch	cursor_AiD_items
			into	@lcomp_id,
					@dacc_guid,
					@ldacc_transaction,
					@lacc_count_id,
					@lcc_code,
					@ldacc_debit,
					@ldacc_credit,
					@luser_id,
					@ldacc_cd,
					@lhacc_software,
					@lct_transaction,
					@ldacc_2ndCurrencyExchange,
					@lacc_detail1,
					@lacc_detail2


		end

		close cursor_AiD_items
		deallocate cursor_AiD_items


		set	@return_value = @lhacc_transaction


		COMMIT TRANSACTION

	END TRY
	BEGIN CATCH
		ROLLBACK TRANSACTION
	END CATCH



END
GO





-- =============================================
-- Author:
--              MOS  02-5-08
-- Create date: <Create Date,,>
-- Description:	Este procedimiento no graba nada
-- solo llama a otros SP que si hacen los INSERT
-- =============================================

CREATE PROCEDURE [dbo].[spAccountingType_updateData]
(
	@dacc_guid						uniqueidentifier,
	@comp_id						int,
	@bra_id							int,
	@hacc_transaction				int,
	@hacc_group						int,
	@hacc_detail					varchar(60),
	@hacc_date						datetime,
	@hacc_number					int,
	@hacc_orderPriority				decimal(5,0),
	@ap_id							int,
	@hacc_blocked					bit,
	@hacc_closing					bit,
	@hacc_opening					bit,
	@hacc_IsEditing					bit,
	@hacc_2ndCurrencyExchange		DECIMAL(19,6),
	@return_value					int		output
)
AS

BEGIN

	set nocount on

	-- -------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------
	/*
	--ver como recuperamos el valor correspondiente
	declare	@dacc_guid					uniqueidentifier,
			@comp_id					int,
			@bra_id						int,
			@hacc_transaction			int,
			@hacc_group					int,
			@hacc_detail				varchar(60),
			@hacc_date					datetime,
			@hacc_number				int,
			@hacc_orderPriority			decimal(5,0),
			@hacc_cd					datetime,
			@ap_id						int,
			@hacc_blocked				bit,
			@hacc_closing				bit,
			@hacc_opening				bit,
			@hacc_IsEditing				bit,
			@hacc_2ndCurrencyExchange		DECIMAL(19,6),
			@return_value				int

	select   @dacc_guid					= 'd9a0a585-ec3e-44af-9d09-fa257c78acea',
			 @comp_id					= 1,
			 @bra_id					= 31,
			 @hacc_transaction			= 22878,
			 @hacc_group				= 10011,
			 @hacc_detail				= 'sdf fsdf wrtwer',
			 @hacc_date					= getdate (),
			 @hacc_number				= 694,
			 @hacc_orderPriority		= 0,
			 @hacc_cd					= getdate (),
			 @ap_id						= 27,
			 @hacc_blocked				= 0,
			 @hacc_closing				= 0,
			 @hacc_opening				= 0,
			 @hacc_IsEditing			= 0,
	 		 @hacc_2ndCurrencyExchange	=1
	*/
	-- -------------------------------------------------------------


	-- Es un Update, el IsEditing debe estar en FALSE.!
	SET @hacc_IsEditing = 'false'

	SET @return_value = 0


	BEGIN TRANSACTION
	BEGIN TRY


		-- ---------------------------------------------------------------------------
		-- MOH - 07-09-2012
		-- recupero el comp_id y bra_id reales del hacc_transaction porque cuando hay
		-- asientos contables de diferentes sucursales cancelaban los sps
		-- ---------------------------------------------------------------------------
		SELECT	@comp_id	= tath.comp_id,
				@bra_id		= tath.bra_id
		FROM	tbAccountTransactionHead_Type tath		WITH (NOLOCK)
		WHERE	tath.hacc_transaction = @hacc_transaction
		-- ---------------------------------------------------------------------------



		declare @hacc_IsEditingDateTime datetime
		set @hacc_IsEditingDateTime = getdate()



		exec dbo.spAccountTransactionHeadType_updateData
				@comp_id,		@bra_id,				@hacc_transaction,
				@hacc_group,	@hacc_detail,			@hacc_date,
				@hacc_number,	@hacc_orderPriority,	--@hacc_cd,
				@ap_id,			@hacc_blocked,			@hacc_closing,
				@hacc_opening,  'False',				@hacc_IsEditingDateTime,
				@hacc_2ndCurrencyExchange


		exec dbo.spAccountTransactionDetailType_deleteAllData @hacc_transaction


		-- declaración de variables para obtener los datos del cursor
		declare
				@lcomp_id						int,
				@ldacc_guid						uniqueidentifier,
				@ldacc_transaction				int,
				@lacc_count_id					int,
				@lcc_code						int,
				@ldacc_debit					decimal(18,4),
				@ldacc_credit					decimal(18,4),
				@lUSER_ID						int,
				@ldacc_cd						datetime,
				@lhacc_software					bit,
				@lct_transaction				int,
				@lacc_detail1					nvarchar(200),
				@lacc_detail2					nvarchar(200),
				@ldacc_2ndCurrencyExchange		DECIMAL(19,6),
				@lrv							int

		-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
		declare cursor_AuD_items CURSOR LOCAL FAST_FORWARD FOR

		select	comp_id,
				dacc_guid,
				dacc_transaction,
				acc_count_id,
				cc_code,
				dacc_debit,
				dacc_credit,
				user_id,
				dacc_cd,
				hacc_software,
				ct_transaction,
				dacc_2ndCurrencyExchange ,
				acc_detail1,
				acc_detail2

		from	tbAccountTransactionDetailTmp		WITH (NOLOCK)
		where	dacc_guid = @dacc_guid

		open	cursor_AuD_items

		-- lectura anticipada del cursor
		fetch	cursor_AuD_items
		into
				@lcomp_id,
				@dacc_guid,
				@ldacc_transaction,
				@lacc_count_id,
				@lcc_code,
				@ldacc_debit,
				@ldacc_credit,
				@luser_id,
				@ldacc_cd,
				@lhacc_software,
				@lct_transaction,
				@ldacc_2ndCurrencyExchange,
				@lacc_detail1,
				@lacc_detail2




		-- se recorre el cursor hasta el fin del mismo
		while   @@fetch_status = 0
		begin


			-- por cada registro del cursor se realiza el insert en spAccountTransactionDetail
			exec	dbo.spAccountTransactionDetailType_insertData
					@comp_id,			@bra_id,			@hacc_transaction,
					@lacc_count_id,		@lcc_code,			@ldacc_debit,
					@ldacc_credit,		@luser_id,			--@ldacc_cd,
					@lhacc_software,	@lct_transaction,	@lacc_detail1,
					@lacc_detail2,		@ldacc_2ndCurrencyExchange,
					@return_value		= @lrv output


			-- por cada registro del cursor se realiza el delete de spAccountTransactionDetailTmp
			exec	dbo.spAccountTransactionDetailTmp_deleteData  @ldacc_transaction


			-- próxima lectura del cursor
			fetch	cursor_AuD_items
			into	@lcomp_id,
					@dacc_guid,
					@ldacc_transaction,
					@lacc_count_id,
					@lcc_code,
					@ldacc_debit,
					@ldacc_credit,
					@luser_id,
					@ldacc_cd,
					@lhacc_software,
					@lct_transaction,
					@ldacc_2ndCurrencyExchange,
					@lacc_detail1,
					@lacc_detail2


		end

		close cursor_AuD_items
		deallocate cursor_AuD_items


		UPDATE tbAccountTransactionHead_Type	WITH (ROWLOCK)
		SET	hacc_IsEditing = 'false'
		WHERE hacc_transaction = @hacc_transaction





		SET @return_value = @hacc_transaction


		COMMIT TRANSACTION

	END TRY
	BEGIN CATCH
		ROLLBACK TRANSACTION
	END CATCH


END
GO






-- =============================================
-- Author:		MOS
-- Create date: 08-2008
-- Verifica si el asiento esta balanceado.
-- De no estar balanceado, hasta 5 centavos,
-- hace una imputacion de ajuste x redondeo.-
-- =============================================
CREATE PROCEDURE [dbo].[spAccountTransaction_CheckInsertBalance]
	(
		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as Int,
		@user_id				as Int,
		@hacc_transaction		as Int,
		@cc_code				as Int,
		@ct_transaction			as int,
		@ctDetail				as varchar(100),
		@ret_XErrorCode			as Int			OutPut,
		@ret_XErrorDescription	as Varchar(200) OutPut
	)
AS
BEGIN
	SET NOCOUNT ON;



	-- Si hay alguna imputacion en NEGATIVO la pasa a positivo e invierte la columna
	UPDATE tbAccountTransactionDetail	WITH (ROWLOCK)
		SET	dacc_credit = dacc_debit * -1,
			dacc_debit	= 0
		WHERE	comp_id			= @comp_id			AND
				ct_transaction	= @ct_transaction	AND
				dacc_debit		< 0


	-- Si hay alguna imputacion en NEGATIVO la pasa a positivo e invierte la columna
	UPDATE tbAccountTransactionDetail		WITH (ROWLOCK)
		SET	dacc_debit  = dacc_credit * -1,
			dacc_credit	= 0
		WHERE	comp_id			= @comp_id			AND
				ct_transaction	= @ct_transaction	AND
				dacc_credit		< 0










	Set @ret_XErrorCode	= 0

	Declare @SumCredit		As Decimal(35,8)
	Declare @SumDebit		As Decimal(35,8)
	Declare @Acc_Count_id	As Int
	Declare @dacc_debit		As Decimal(35,8)
	Declare @dacc_credit	As Decimal(35,8)
	Declare @utexts_desc	as varchar(100)
	Declare @decMaxDifference AS DECIMAL(35,8)

	SET @decMaxDifference =  0.9

	-- Redondea asientos a dos decimales.-
	UPDATE tbAccountTransactionDetail	WITH (ROWLOCK)
		SET
			dacc_debit	= ROUND(dacc_debit,2),
			dacc_credit = ROUND(dacc_credit,2)
		Where   comp_id			= @comp_id
			and	ct_transaction	= @ct_transaction


	Select @SumCredit	= Sum(dacc_credit),
		   @SumDebit	= Sum(dacc_Debit)
		From dbo.tbAccountTransactionDetail
		Where   comp_id			= @comp_id
			and	ct_transaction	= @ct_transaction

	Delete From dbo.tbAccountTransactionDetail	WITH (ROWLOCK)
	Where   comp_id			= @comp_id
		and	ct_transaction	= @ct_transaction
		AND dacc_debit		= 0
		AND dacc_credit     = 0


	-- --------------------------------
	-- Corregir Redondeos
	-- --------------------------------
	IF @SumCredit > 70000000
		BEGIN
			SET @decMaxDifference = 500
		END
	ELSE IF @SumCredit > 50000000
		BEGIN
			SET @decMaxDifference = 300
		END
	ELSE IF @SumCredit > 10000000
		BEGIN
			SET @decMaxDifference = 30
		END
	else IF @SumCredit > 1000000
		BEGIN
			SET @decMaxDifference = 20
		END
	else IF @SumCredit > 500000
		BEGIN
			SET @decMaxDifference = 10
		END
	else IF @SumCredit > 100000
		BEGIN
			SET @decMaxDifference = 5
		END
	else IF @SumCredit > 50000
		BEGIN
			SET @decMaxDifference = 2
		END

	-- --------------------------------





	If (@SumCredit - @SumDebit) <> 0
		Begin
			If Abs(@SumCredit - @SumDebit) <= @decMaxDifference
				Begin
					Select @Acc_Count_id = Acc_Count_id
						From dbo.tbAccountManagementRelations
						Where	comp_id = @comp_id
							and	bra_id  = @bra_id
							and samr_id = 25

					If @Acc_Count_id is Null
						Begin
							Set @ret_XErrorCode = -1
							Select	@ret_XErrorDescription = utexts_desc
								From dbo.tbsysUniqueTexts
								Where lang_id = @lang_id and  utexts_id = 20215
						End
					Else
						-- efectua Imputacion Contable x Redondeo
						Begin

							Select @utexts_desc		= utexts_desc
								From dbo.tbsysUniqueTexts
								Where	lang_id		= @lang_id
									and utexts_id	= 202028

							Set @utexts_desc = @ctDetail + ' ' + @utexts_desc

							If @SumCredit > @SumDebit
								Begin
									Set @dacc_debit		= @SumCredit - @SumDebit
									Set @dacc_Credit	= 0
								End
							Else
								Begin
									Set @dacc_debit		= 0
									Set @dacc_Credit	= @SumDebit - @SumCredit
								End


							INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@dacc_debit,
									@dacc_credit,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									'',
									30)

							Set @ret_XErrorCode = 0

						End
				End
			Else
				Begin
					Set @ret_XErrorCode = -1
					Select @ret_XErrorDescription = utexts_desc + '<br/> @SumCredit:' + CONVERT(NVARCHAR(100),@SumCredit) + ' @SumDebit:' + CONVERT(NVARCHAR(100),@SumDebit) + ' @decMaxDifference:' + CONVERT(NVARCHAR(100),@decMaxDifference)
						From dbo.tbsysUniqueTexts
						Where lang_id = @lang_id and  utexts_id = 20216
				End
		End
	Else
		Begin
			Set @ret_XErrorCode = 0
		End


	-- Verifica que todas las cuentas sean IMPUTABLES
	IF EXISTS(
		SELECT TOP 1  1
			FROM tbAccountTransactionDetail tatd
			INNER JOIN tbAccountant ta	WITH (NOLOCK)
				ON	ta.comp_id			= tatd.comp_id 		AND
					ta.acc_count_id		= tatd.acc_count_id
			Where   tatd.comp_id						= @comp_id			AND
					tatd.ct_transaction					= @ct_transaction	AND
					IsNull(ta.acc_imputable,'False')	= 'False'

			)
		BEGIN
			Set @ret_XErrorCode = -1
					Select @ret_XErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts
						Where lang_id = @lang_id and  utexts_id = 20283
		END



	-- Verifica que todas las cuentas sean HABILITADAS
	DECLARE @strAccountDisabled AS NVARCHAR(3000) = ''
	SELECT  @strAccountDisabled = @strAccountDisabled + ISNULL(ta.acc_code,'') + '; '
			FROM tbAccountTransactionDetail tatd
			INNER JOIN tbAccountant ta	WITH (NOLOCK)
				ON	ta.comp_id			= tatd.comp_id 		AND
					ta.acc_count_id		= tatd.acc_count_id
			Where   tatd.comp_id						= @comp_id			AND
					tatd.ct_transaction					= @ct_transaction	AND
					IsNull(ta.acc_disabled,'False')	= 'True'
	IF @strAccountDisabled <> ''
		BEGIN
			Set @ret_XErrorCode = -1
			Select @ret_XErrorDescription = utexts_desc + '<br/>' + @strAccountDisabled
				From dbo.tbsysUniqueTexts
				Where lang_id = @lang_id and  utexts_id = 20284
		END



	DECLARE @ap_id AS INT
	DECLARE @datFirstDate AS DATE
	DECLARE @datLastDate  AS DATE
	SELECT  @ap_id = tap.ap_id,
			@datFirstDate = tap.ap_firstdate,
			@datLastDate  = tap.ap_lastdate
		FROM tbAccountTransactionHead			tath	WITH (NOLOCK)
		INNER JOIN tbAccountantPeriod			tap		WITH (NOLOCK)
			ON	tap.comp_id = tath.comp_id					AND
				tap.ap_id	= tath.ap_id
		WHERE	tath.comp_id			= @comp_id			AND
				tath.hacc_transaction	= @hacc_transaction


	-- Verifica que el Periodo Contable No Este Cerrado
	IF EXISTS(
				SELECT TOP 1  1
					FROM tbAccountantPeriod tap	WITH (NOLOCK)
					WHERE	tap.comp_id = @comp_id	AND
							tap.ap_id	= @ap_id	AND
						(	tap.ap_closed		= 'True' OR
							tap.ap_blocked		= 'True'
						)
			)
		BEGIN
			Set @ret_XErrorCode		   = -1
			SET @ret_XErrorDescription = @ret_XErrorDescription + '<b> 999. ATENCION: El Período Contable seleccionado está Bloqueado o Cerrado </b> !'
		END



	-- Verifica que no existan periodos contables con fechas solapadas
	IF EXISTS(
				SELECT TOP 1  1
					FROM tbAccountantPeriod tap	WITH (NOLOCK)
					WHERE	tap.comp_id = @comp_id AND
							tap.ap_id <> @ap_id AND
							(
								tap.ap_firstdate BETWEEN @datFirstDate AND @datLastDate
									OR
								tap.ap_lastdate  BETWEEN @datFirstDate AND @datLastDate
							)
			)
		BEGIN
			IF NOT EXISTS (
								SELECT TOP 1 1
									FROM tbAccountantPeriodByBranch tapbb	WITH (NOLOCK)
									WHERE	tapbb.comp_id	= @comp_id	AND
											tapbb.bra_id	= @bra_id		AND
											tapbb.ap_id		= @ap_id
						  )
				BEGIN
					Set @ret_XErrorCode		   = -1
					SET @ret_XErrorDescription = @ret_XErrorDescription + '8998-ATENCION: El Período Contable seleccionado está solapado con otro.<br/>
																		   Relacionar el período contable a la Sucursal.<br/>'	+
																		  'CompID:'		+ CONVERT(VARCHAR(20),ISNULL(@comp_id,-1))			+ '/' +
																		  'BranchID:'	+ CONVERT(VARCHAR(20),ISNULL(@bra_id,-1))			+ '/' +
																		  'APID:'		+ CONVERT(VARCHAR(20),ISNULL(@ap_id,-1))
				END
		END




END
GO





-- =============================================
-- Author:		MOS
-- Create date: 08-2008
-- Invierte parte de un asiento
--         (x si es un credito)
-- =============================================

CREATE PROCEDURE [dbo].[spAccountTransaction_insertAnullment]
	(
		@comp_id		as int,
		@ct_transaction as int
	)
AS
BEGIN

	SET NOCOUNT ON;


	INSERT INTO tbAccountTransactionDetail
	(
		comp_id,
		bra_id,
		hacc_transaction,
		-- dacc_transaction -- this column value is auto-generated,
		acc_count_id,
		cc_code,
		dacc_debit,
		dacc_credit,
		[user_id],
		dacc_cd,
		hacc_software,
		ct_transaction,
		acc_detail1,
		acc_detail2,
		dacc_order,
		dacc_2ndCurrencyExchange
	)
		SELECT	tatd.comp_id,
				tatd.bra_id,
				tatd.hacc_transaction,
				tatd.acc_count_id,
				tatd.cc_code,
				tatd.dacc_credit,		-- Al reves
				tatd.dacc_debit,
				tatd.[user_id],
				tatd.dacc_cd,
				tatd.hacc_software,
				tatd.ct_transaction,
				'*An* ' + ISNULL(tatd.acc_detail1,''),
				'*An* ' + ISNULL(tatd.acc_detail2,''),
				tatd.dacc_order,
				tatd.dacc_2ndCurrencyExchange

			FROM tbAccountTransactionDetail tatd		WITH (NOLOCK)
			WHERE	tatd.comp_id		= @comp_id AND
					tatd.ct_transaction = @ct_transaction


END
GO



-- ------------------------------------
-- MOS: 05-2009
-- Asiento Contable de wfmCashDeposit
-- ------------------------------------


-- Log:
-- MOS 04-20204: púse control de error en transaccion en el sitio y si es transferencia entre cuentas, como se hace con DOS asientos, si es transferencia NO hago el control de balanceo.



CREATE PROCEDURE [dbo].[spAccountTransaction_InsertdataFromCashMovements]
	(
		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as int,
		@IsADeposit				as bit,
		@ba_id					as int,
