		@ret_Identity			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
	)
AS



SET DATEFORMAT 'YMD'

-- -----------------------------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------------------------
/*
		declare
		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as int,
		@IsADeposit				as bit,

		@ba_id					as int,
