		@ba_id					= -1,
		@Total					= 0.15,
		@ct_transaction			= 2425,
		@currency_id			=1,
		@acc_count_id			=4447,
		@processing_Date		= '2013-03-30',

		@user_id				= 1,
		@ret_Identity			= 0,
		@ret_ErrorCode			= 0,
		@ret_ErrorDescription	= ''
*/
-- -----------------------------------------------------------------------------------



-- =================================================================================================================
-- Author		: MOS-G
-- Update Date	: 2011-01-18
-- Parte		: 782
-- Description	: Se cambia la fecha que se graba en la contabilidad de la fecha de proceso por la que recibe por parámetro
-- =================================================================================================================
BEGIN

	SET NOCOUNT ON

	Set @ret_Identity		   = 0
	Set @ret_ErrorCode		   = 0
	Set @ret_ErrorDescription  = ''


	DECLARE @bitIsBankTransfer AS BIT = 'False'
	IF @ct_transaction < 0
		BEGIN
			SET @ct_transaction = @ct_transaction * -1
			SET @bitIsBankTransfer = 'True'
		END

	-- ----------------------------------------------------------------------------------
	-- Verifica si hay Asientos Contables para ésta Sucursal y Asigna el Grupo Contable.-
	-- ----------------------------------------------------------------------------------
	DECLARE		@ag_id AS INT
	SELECT		@ag_id = ag_id
		FROM	tbBranch tb
		WHERE	tb.comp_id = @comp_id
			AND tb.bra_id  = @bra_id
	If @ag_id is NULL RETURN

	-- Agregar cuando busca un asiento existente el grupo contable
	-- ----------------------------------------------------------------------------------


	Declare @hacc_number	as int
	Declare @hacc_detail	as varchar(60)
	Declare @ap_id			as int
	--Declare @Acc_Count_Id	as int


	Declare @dacc_debit		as decimal(19,6)
	set @dacc_debit = 0

	Declare @dacc_credit	as decimal(19,6)
	set @dacc_credit = 0


	Declare @utexts_desc	as varchar(60)
	Declare @tax_desc		as varchar(60)
	Declare @ctDetail  		as varchar(100)

	Declare @cc_code			as int
	Declare @ct_CompanyCurrency	as int
	Set		@cc_Code			= null
	Set		@ct_CompanyCurrency = null
	Declare	@ct_date			as datetime

	DECLARE @acc_count_BankingAccount			AS INT
	DECLARE @acc_count_BankingAccount_ExDiff	AS INT



	-- Recupera la Moneda de la Compañia
	Select @ct_CompanyCurrency = curr_id
		From dbo.tbCompany	WITH (NOLOCK)
		Where   comp_id = @comp_id


	--esta línea es para generar un error
	--set @ct_CompanyCurrency = null


	If @ct_CompanyCurrency is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20218
			Return
		END



	-- ----------------------------------------------------------------------------------
	-- Si el Grupo Contable establece una moneda, toma esa moneda para asientos.
	-- ----------------------------------------------------------------------------------
	DECLARE @bitHasAGCurr AS BIT = 'false'
	SELECT @ct_CompanyCurrency   =	CASE
										WHEN tag.ag_curr_id IS NULL THEN	@ct_CompanyCurrency
										ELSE								tag.ag_curr_id
									END,
			@bitHasAGCurr		 = 	CASE
										WHEN tag.ag_curr_id IS NULL THEN	'False'
										ELSE								'True'
									END
		FROM tbAccountantGroup AS tag	WITH (NOLOCK)
		WHERE	tag.comp_id = @comp_id AND
				tag.ag_id	= @ag_id
	-- ----------------------------------------------------------------------------------
	IF @bitHasAGCurr = 'True'
		BEGIN
			SET @decExchange2BranchCurrency = dbo.fnGetExchange2(@comp_id,1,@currency_id,@ct_CompanyCurrency,0,0,0,'False')
		END






	-- ----------------------------------------------
	-- Recupera el Centro de Costos desde la Sucursal
	Select @cc_code = cc_code
		From dbo.tbBranch
		Where   comp_id = @comp_id
			and	bra_id  = @bra_id
	If @cc_code is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20217
			Return
		End
	-- ----------------------------------------------





	--====================================================================================================
	-- Parte: 782
	--	-- Recupera la fecha de trabajo de la Sucursal
	--	Select @ct_date = bra_processingDate
	--		From dbo.tbBranch
	--		Where   comp_id = @comp_id
	--			and	bra_id  = @bra_id
	SET @ct_date = @processing_Date
	--====================================================================================================




	If @ct_date is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20219
			Return
		End
	-- ----------------------------------------------


	-- Recupera el Nombre del Asiento, si es que es nuevo
	Select @ctDetail = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where   lang_id = @lang_id
							and utexts_id = 202200

	Select @ctDetail = @ctDetail + LTrim(RTrim(ct_docNumber))
		From dbo.tbCommercialTransactions
		where ct_transaction = @ct_transaction
	-- --------------------------------------------------


	-- Recupera el Grupo de Asiento Contable		OK
	Declare @hacc_group as int

	Select @hacc_group = C.hacc_group
		From dbo.tbsysDocuments			C			WITH (NOLOCK)
		Where C.sd_id = 200
	-- --------------------------------------



	-- ------------------------------------------------------------------
	-- Verifica si hay un Asiento de la Compañia y Sucursal con ese Grupo	OK
	-- ------------------------------------------------------------------
	Declare @hacc_transaction as int

	Select @hacc_transaction = hacc_transaction
		From dbo.tbAccountTransactionHead			WITH (NOLOCK)
		Where   comp_id			= @comp_id
			and bra_id			= @bra_id
			and hacc_group		= @hacc_group
			and hacc_date		= @ct_date
			and hacc_IsEditing	= 'False'
			AND ag_id			= @ag_id
			AND dbo.fnGetOnlyDate(hacc_cd)	= dbo.fnGetOnlyDate(GETDATE())
	-- ------------------------------------------------------------------

	--	-----------------------------------------------------------------
	--  Si no hay Cabecera dada de alta, la da de alta
	--	-----------------------------------------------------------------
	If IsNull(@hacc_transaction,0) = 0
		Begin

			-- Obtiene Proximo Numero de Asiento.-
			EXEC dbo.spCounters_getNextValue @comp_id, 0, 3, @counter_value = @hacc_number OUTPUT

			-- -------------------------------
			-- Obtiene Descripcion del Asiento OK
			-- -------------------------------
				Select @hacc_detail = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where   lang_id = @lang_id
						and utexts_id = 202200
			-- -------------------------------

			-- -------------------------------
			-- Obtiene el Periodo
			-- Correspondiente a la fecha			OK
			-- -------------------------------
			SELECT @ap_id = NULL
			Select @ap_id = ap.ap_id
				From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
				INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
					ON	tapbb.comp_id	=	ap.comp_id	AND
						tapbb.bra_id	=	@bra_id		AND
						tapbb.ap_id		=	ap.ap_id
				Where   ap.comp_id		=	@comp_id
					and ap.ap_firstdate <=	@ct_date
					and ap.ap_lastdate  >=	@ct_date
					and ap.ap_closed	=	'False'

			IF @ap_id IS NULL
				BEGIN
					Select @ap_id = ap_id
						From dbo.tbAccountantPeriod			WITH (NOLOCK)
						Where   comp_id = @comp_id
							and ap_firstdate <= @ct_date
							and ap_lastdate  >= @ct_date
							and ap_closed='False'
				END

			If @ap_id is Null
				Begin
					Set @ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20206
					Return
				End

			-- -------------------------------


			-- Inserta Header Nuevo						OK
			Insert Into dbo.tbAccountTransactionHead
				(	comp_id,
					bra_id,
					hacc_group,
					hacc_detail,
					hacc_date,
					hacc_number,
					hacc_orderPriority,
					hacc_cd,
					ap_id,
					hacc_blocked,
					hacc_closing,
					hacc_opening,
					hacc_IsEditing,
					hacc_IsEditingDateTime,
					ag_id
				)
				Values
				(	@comp_id,
					@bra_id,
					@hacc_group,
					@hacc_detail,
					@ct_date,
					@hacc_number,
					0,
					getdate(),
					@ap_id,
					'False',
					'False',
					'False',
					'False',
					GetDate(),
					@ag_id
				)

			Set @hacc_transaction = @@identity
		End
		--	-----------------------------------------------------------------

		-- ------------------------------------------------------------------
		-- Comienza Asiento de Deposito de Efectivo / Retiro
		-- ------------------------------------------------------------------
		Set @acc_count_BankingAccount			= NULL
		SET @acc_count_BankingAccount_ExDiff	= NULL
		-- Busca cuenta de Cuentas Bancarias					OK
		Select	@acc_count_BankingAccount			= A.acc_count_id,
				@acc_count_BankingAccount_ExDiff	= A.acc_count_id_ExDif
			From dbo.tbBankingAccounts A			WITH (NOLOCK)
			Where   comp_id		= @comp_id
				and ba_id		= @ba_id
		-- -----------------------------------
		If IsNull(@ba_id,-1) <> -1 and IsNull(@acc_count_BankingAccount,-1) = -1
			Begin
				Set	@ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20201
					Return
			End
		-- -----------------------------------

		-- Si no se deposita en un banco, toma la que viene x parametro.-
		IF isnull(@ba_id,-1) = -1
			BEGIN
				SET @acc_count_BankingAccount			= @acc_count_id
				SET @acc_count_BankingAccount_ExDiff	= @acc_count_id		-- Ver si es correcto o hay que poner otra diferente...
			END



		-- -----------------------------------
		-- Cuenta Contable Caja de la Sucursal
		-- -----------------------------------
		DECLARE @acc_count_id_caja			AS integer
		DECLARE @acc_count_id_caja_ExDiff	AS integer
		SELECT TOP 1
			   @acc_count_id_caja			= acc_count_id,
			   @acc_count_id_caja_ExDiff	= acc_count_id_ExDif
			From dbo.tbAccountManagementCurrencyRelations tmp			WITH (NOLOCK)
			Where   tmp.comp_id    = @comp_id		AND
				    tmp.curr_id    = @currency_id	AND
			       (tmp.bra_id IS NULL OR tmp.bra_id = @bra_id)
			ORDER BY amcr_order
		--SELECT @acc_count_id_caja			= tamcr.acc_count_id,
		--	   @acc_count_id_caja_ExDiff	= tamcr.acc_count_id_ExDif
		--	FROM tbAccountManagementCurrencyRelations tamcr
		--	WHERE tamcr.comp_id		= @comp_id
		--		AND tamcr.curr_id	= @currency_id

		If IsNull(@acc_count_id_caja,-1) = -1
			Begin
				Set	@ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20227
					Return
			End

		If IsNull(@acc_count_id_caja_ExDiff,-1) = -1 AND @currency_id <> @ct_CompanyCurrency
			Begin
				Set	@ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts				WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20228
					Return
			End
		-- -----------------------------------


		-- Obtiene total en moneda de la compañia, partiendo del importe en la moneda de la sucursal.
		DECLARE @decTotal2Company AS DECIMAL(19,5)

		-- Asiento con Diferencia de Cambio.!!!!   y al tipo de cambio de la cobranza!!!!
		Declare @decDebitInitial					as Decimal(19,5)
		Declare @decDebitExcDif						as Decimal(19,5)
		Declare @decCreditInitial					as Decimal(19,5)
		Declare @decCreditExcDif					as Decimal(19,5)

		Set @decDebitInitial		= 0
		Set @decDebitExcDif			= 0
		Set @decCreditInitial		= 0
		Set @decCreditExcDif		= 0


		SET @decTotal2Company  = @Total * @decExchange2BranchCurrency

		--Set @decTotal2Company = dbo.fnGetExchange(	@comp_id,
		--											@Total,
		--											@currency_id,
		--											@ct_CompanyCurrency,
		--											0,
		--											0,
		--											0)

		Set	@decCreditInitial	= @Total
		Set	@decCreditExcDif	= @decTotal2Company - @Total	-- Debito de Diferencia de Cambio.-




		IF  @IsADeposit = 'true'
			BEGIN

				IF @bitIsBankTransfer = 'False'
					BEGIN
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_caja,
									@cc_code,
									0,
									@decCreditInitial,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)

					END


				INSERT INTO dbo.tbAccountTransactionDetail
						   (comp_id,
							bra_id,
							hacc_transaction,
							acc_count_id,
							cc_code,
							dacc_debit,
							dacc_credit,
							user_id,
							dacc_cd,
							hacc_software,
							ct_transaction,
							acc_detail1,
							acc_detail2,
							dacc_order)
					 VALUES
						   (@comp_id,
							@bra_id,
							@hacc_transaction,
							@acc_count_BankingAccount,
							@cc_code,
							@decCreditInitial,
							0,
							@user_id,
							getdate(),
							'True',
							@ct_transaction,
							@utexts_desc,
							@tax_desc,
							10)

				IF @decCreditExcDif > 0
					BEGIN

						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_caja_ExDiff,
									@cc_code,
									0,
									@decCreditExcDif,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_BankingAccount_ExDiff,
									@cc_code,
									@decCreditExcDif,
									0,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)

					END



			END
		ELSE	-- Transferencia entre Cuentas Bancarias
			BEGIN

				IF @bitIsBankTransfer = 'False'
					BEGIN
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_caja,
									@cc_code,
									@decCreditInitial,
									0,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)

					END


				INSERT INTO dbo.tbAccountTransactionDetail
						   (comp_id,
							bra_id,
							hacc_transaction,
							acc_count_id,
							cc_code,
							dacc_debit,
							dacc_credit,
							user_id,
							dacc_cd,
							hacc_software,
							ct_transaction,
							acc_detail1,
							acc_detail2,
							dacc_order)
					 VALUES
						   (@comp_id,
							@bra_id,
							@hacc_transaction,
							@acc_count_BankingAccount,
							@cc_code,
							0,
							@decCreditInitial,
							@user_id,
							getdate(),
							'True',
							@ct_transaction,
							@utexts_desc,
							@tax_desc,
							10)


				IF @decCreditExcDif > 0
					BEGIN

						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_caja_ExDiff,
									@cc_code,
									@decCreditExcDif,
									0,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_BankingAccount_ExDiff,
									@cc_code,
									0,
									@decCreditExcDif,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)



					END


			END



		-- ------------------------------------------------------------------
		-- Fin      Asiento de Deposito de Cheques
		-- ------------------------------------------------------------------

		IF @bitIsBankTransfer <> 'True'	-- MOS 04-2024: Sin esto fallaba una transferencia ya que controlo el nro de error.  las transf se hacen en DOS PASOS.
			BEGIN
				Exec spAccountTransaction_CheckInsertBalance	@comp_id				,
																@bra_id					,
																@lang_id				,
																@user_id				,
																@hacc_transaction		,
																@cc_code				,
																@ct_transaction			,
																@ctDetail				,
																@ret_XErrorCode			= @ret_ErrorCode		OUTPUT 	,
																@ret_XErrorDescription	= @ret_ErrorDescription	OUTPUT

			END




END
GO





-- =============================================
-- Author:		MOS
-- Fijarse que si se agrega un campo a la BD
-- hay que tocar todos los SP que se llaman
-- parecidos a este.-
-- Create date: 08-2008
-- =============================================
CREATE PROCEDURE [dbo].[spAccountTransaction_InsertdataFromCheckPortfolio]
	(
		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as int,
		@IsACredit				as bit,

		@ba_id					as int,
		@Total					as decimal(19,5),
		@ct_transaction			as int,
		@currency_id			as int,

		@user_id				as int,
		@ret_Identity			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
	)
AS

BEGIN

	SET NOCOUNT ON


	Set @ret_Identity		   = 0
	Set @ret_ErrorCode		   = 0
	Set @ret_ErrorDescription  = ''

	-- ----------------------------------------------------------------------------------
	-- Verifica si hay Asientos Contables para ésta Sucursal y Asigna el Grupo Contable.-
	-- ----------------------------------------------------------------------------------
	DECLARE		@ag_id AS INT
	SELECT		@ag_id = ag_id
		FROM	tbBranch tb			WITH (NOLOCK)
		WHERE	tb.comp_id = @comp_id
			AND tb.bra_id  = @bra_id
	If @ag_id is NULL RETURN

	-- Agregar cuando busca un asiento existente el grupo contable
	-- ----------------------------------------------------------------------------------




	Declare @acc_count_ChechPortfolio	as int
	Declare @acc_count_BankingAccount	as int

	Declare @hacc_number	as int
	Declare @hacc_detail	as varchar(60)
	Declare @ap_id			as int
	Declare @Acc_Count_Id	as int


	Declare @dacc_debit		as decimal(19,6)
	set @dacc_debit = 0

	Declare @dacc_credit	as decimal(19,6)
	set @dacc_credit = 0


	Declare @utexts_desc	as varchar(60)
	Declare @tax_desc		as varchar(60)
	Declare @ctDetail  		as varchar(100)

	Declare @cc_code			as int
	Declare @ct_CompanyCurrency	as int
	Set		@cc_Code			= null
	Set		@ct_CompanyCurrency = null
	Declare	@ct_date			as datetime



	-- Recupera la Moneda de la Compañia
	Select @ct_CompanyCurrency = curr_id
		From dbo.tbCompany			WITH (NOLOCK)
		Where   comp_id = @comp_id


	--esta línea es para generar un error
	--set @ct_CompanyCurrency = null


	If @ct_CompanyCurrency is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20218
			Return
		End
	-- ----------------------------------------------


	-- ----------------------------------------------------------------------------------
	-- Si el Grupo Contable establece una moneda, toma esa moneda para asientos.
	-- ----------------------------------------------------------------------------------
	SELECT @ct_CompanyCurrency =	CASE
										WHEN tag.ag_curr_id IS NULL THEN	@ct_CompanyCurrency
										ELSE								tag.ag_curr_id
									END
		FROM tbAccountantGroup AS tag	WITH (NOLOCK)
		WHERE	tag.comp_id = @comp_id AND
				tag.ag_id	= @ag_id
	-- ----------------------------------------------------------------------------------



	-- Recupera el Centro de Costos desde la Sucursal
	Select @cc_code = cc_code
		From dbo.tbBranch	WITH (NOLOCK)
		Where   comp_id = @comp_id
			and	bra_id  = @bra_id
	If @cc_code is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20217
			Return
		End
	-- ----------------------------------------------


	-- Recupera la fecha de procesamiento de la sucursal.
	Select @ct_date = bra_processingDate
		From dbo.tbBranch	WITH (NOLOCK)
		Where   comp_id = @comp_id
			and	bra_id  = @bra_id
	If @ct_date is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20219
			Return
		End
	-- ----------------------------------------------


	-- Recupera el Nombre del Asiento, si es que es nuevo
	Select @ctDetail = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where   lang_id = @lang_id
							and utexts_id = 202200

	Select @ctDetail = @ctDetail + LTrim(RTrim(ct_docNumber)),
			@ct_date = ct_taxDate	-- MOS 10-2021 x MFix
		From dbo.tbCommercialTransactions			WITH (NOLOCK)
		where ct_transaction = @ct_transaction
	-- --------------------------------------------------


	-- Recupera el Grupo de Asiento Contable		OK
	Declare @hacc_group as int

	Select @hacc_group = C.hacc_group
		From dbo.tbsysDocuments			C			WITH (NOLOCK)
		Where C.sd_id = 200
	-- --------------------------------------



	-- ------------------------------------------------------------------
	-- Verifica si hay un Asiento de la Compañia y Sucursal con ese Grupo	OK
	-- ------------------------------------------------------------------
	Declare @hacc_transaction as int

	Select @hacc_transaction = hacc_transaction
		From dbo.tbAccountTransactionHead			WITH (NOLOCK)
		Where   comp_id			= @comp_id
			and bra_id			= @bra_id
			and hacc_group		= @hacc_group
			and hacc_date		= @ct_date
			and hacc_IsEditing	= 'False'
			AND ag_id			= @ag_id
			AND dbo.fnGetOnlyDate(hacc_cd)	= dbo.fnGetOnlyDate(GETDATE())
	-- ------------------------------------------------------------------

	--	-----------------------------------------------------------------
	--  Si no hay Cabecera dada de alta, la da de alta
	--	-----------------------------------------------------------------
	If IsNull(@hacc_transaction,0) = 0
		Begin

			-- Obtiene Proximo Numero de Asiento.-
			EXEC dbo.spCounters_getNextValue @comp_id, 0, 3, @counter_value = @hacc_number OUTPUT

			-- -------------------------------
			-- Obtiene Descripcion del Asiento OK
			-- -------------------------------
				Select @hacc_detail = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where   lang_id = @lang_id
						and utexts_id = 202200
			-- -------------------------------

			-- -------------------------------
			-- Obtiene el Periodo
			-- Correspondiente a la fecha			OK
			-- -------------------------------
			SELECT @ap_id = NULL
			Select @ap_id = ap.ap_id
				From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
				INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
					ON	tapbb.comp_id	=	ap.comp_id	AND
						tapbb.bra_id	=	@bra_id		AND
						tapbb.ap_id		=	ap.ap_id
				Where   ap.comp_id		=	@comp_id
					and ap.ap_firstdate <=	@ct_date
					and ap.ap_lastdate  >=	@ct_date
					and ap.ap_closed	=	'False'

			IF @ap_id IS NULL
				BEGIN
					Select @ap_id = ap_id
						From dbo.tbAccountantPeriod			WITH (NOLOCK)
						Where   comp_id = @comp_id
							and ap_firstdate <= @ct_date
							and ap_lastdate  >= @ct_date
							and ap_closed='False'
				END

			If @ap_id is Null
				Begin
					Set @ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20206
					Return
				End

			-- -------------------------------


			-- Inserta Header Nuevo						OK
			Insert Into dbo.tbAccountTransactionHead
				(	comp_id,
					bra_id,
					hacc_group,
					hacc_detail,
					hacc_date,
					hacc_number,
					hacc_orderPriority,
					hacc_cd,
					ap_id,
					hacc_blocked,
					hacc_closing,
					hacc_opening,
					hacc_IsEditing,
					hacc_IsEditingDateTime,
					ag_id
				)
				Values
				(	@comp_id,
					@bra_id,
					@hacc_group,
					@hacc_detail,
					@ct_date,
					@hacc_number,
					0,
					getdate(),
					@ap_id,
					'False',
					'False',
					'False',
					'False',
					GetDate(),
					@ag_id
				)

			Set @hacc_transaction = @@identity
		End
		--	-----------------------------------------------------------------










		-- ------------------------------------------------------------------
		-- Comienza Asiento de Deposito de Cheques
		-- ------------------------------------------------------------------

		Set @acc_count_ChechPortfolio	 = null
		Set @acc_count_BankingAccount	 = null

		-- Busca cuenta de Valores a Depositar					OK
		Select @acc_count_ChechPortfolio = acc_count_id
			From dbo.tbAccountManagementRelations A			WITH (NOLOCK)
			Where   comp_id		= @comp_id
				and bra_id		= @bra_id
				and samr_id		= 200

		If IsNull(@acc_count_ChechPortfolio,0) = 0
			Begin
				Set	@ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20200
					Return
			End
		-- -----------------------------------

		-- Busca cuenta de Cuentas Bancarias					OK
		Select @acc_count_BankingAccount = a.acc_count_id_notCollected -- MOS: 12-2010 a.acc_count_id_notPayed
			From dbo.tbBankingAccounts A			WITH (NOLOCK)
			Where   comp_id		= @comp_id
				and ba_id		= @ba_id

		If IsNull(@acc_count_BankingAccount,0) = 0
			Begin
				Set	@ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20201
					Return
			End
		-- -----------------------------------

		Set @Total = dbo.fnGetExchange(	@comp_id,
										@Total,
										@currency_id,
										@ct_CompanyCurrency,
										0,
										0,
										0)

	If @IsACredit = 'False'
		BEGIN

			INSERT INTO dbo.tbAccountTransactionDetail
					   (comp_id,
						bra_id,
						hacc_transaction,
						acc_count_id,
						cc_code,
						dacc_debit,
						dacc_credit,
						user_id,
						dacc_cd,
						hacc_software,
						ct_transaction,
						acc_detail1,
						acc_detail2,
						dacc_order)
				 VALUES
					   (@comp_id,
						@bra_id,
						@hacc_transaction,
						@acc_count_ChechPortfolio,
						@cc_code,
						0,
						@Total,
						@user_id,
						getdate(),
						'True',
						@ct_transaction,
						@utexts_desc,
						@tax_desc,
						10)

			INSERT INTO dbo.tbAccountTransactionDetail
					   (comp_id,
						bra_id,
						hacc_transaction,
						acc_count_id,
						cc_code,
						dacc_debit,
						dacc_credit,
						user_id,
						dacc_cd,
						hacc_software,
						ct_transaction,
						acc_detail1,
						acc_detail2,
						dacc_order)
				 VALUES
					   (@comp_id,
						@bra_id,
						@hacc_transaction,
						@acc_count_BankingAccount,
						@cc_code,
						@Total,
						0,
						@user_id,
						getdate(),
						'True',
						@ct_transaction,
						@utexts_desc,
						@tax_desc,
						10)


		END

	ELSE

		BEGIN

			INSERT INTO dbo.tbAccountTransactionDetail
					   (comp_id,
						bra_id,
						hacc_transaction,
						acc_count_id,
						cc_code,
						dacc_debit,
						dacc_credit,
						user_id,
						dacc_cd,
						hacc_software,
						ct_transaction,
						acc_detail1,
						acc_detail2,
						dacc_order)
				 VALUES
					   (@comp_id,
						@bra_id,
						@hacc_transaction,
						@acc_count_ChechPortfolio,
						@cc_code,
						@Total,
						0,
						@user_id,
						getdate(),
						'True',
						@ct_transaction,
						@utexts_desc,
						@tax_desc,
						10)

			INSERT INTO dbo.tbAccountTransactionDetail
					   (comp_id,
						bra_id,
						hacc_transaction,
						acc_count_id,
						cc_code,
						dacc_debit,
						dacc_credit,
						user_id,
						dacc_cd,
						hacc_software,
						ct_transaction,
						acc_detail1,
						acc_detail2,
						dacc_order)
				 VALUES
					   (@comp_id,
						@bra_id,
						@hacc_transaction,
						@acc_count_BankingAccount,
						@cc_code,
						0,
						@Total,
						@user_id,
						getdate(),
						'True',
						@ct_transaction,
						@utexts_desc,
						@tax_desc,
						10)


		END








		-- ------------------------------------------------------------------
		-- Fin      Asiento de Deposito de Cheques
		-- ------------------------------------------------------------------


--		If @IsACredit = 'True'
--			Begin
--				Exec spAccountTransaction_InvertWith_ccTransaction  @comp_id,
--																	@ct_transaction
--		End


		Exec spAccountTransaction_CheckInsertBalance	@comp_id				,
														@bra_id					,
														@lang_id				,
														@user_id				,
														@hacc_transaction		,
														@cc_code				,
														@ct_transaction			,
														@ctDetail				,
														@ret_XErrorCode			= @ret_ErrorCode		OUTPUT 	,
														@ret_XErrorDescription	= @ret_ErrorDescription	OUTPUT

	Return

END
GO







CREATE PROCEDURE [dbo].[spAccountTransaction_InsertdataFromCheckRejection]
	(
		@comp_id				as INT ,
		@bra_id					as INT ,
		@lang_id				as INT ,
		@chp_id					as INT ,
		@option					AS INT ,
		@userId					AS INT ,

		@ret_Identity			as INT 			OUTPUT ,
		@ret_ErrorCode			as INT 			OUTPUT ,
		@ret_ErrorDescription	as VARCHAR(200) OUTPUT
	)
AS

BEGIN

	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	--DECLARE 		@comp_id				as INT
	--DECLARE 		@bra_id					as INT
	--DECLARE 		@lang_id				as INT
	--DECLARE 		@chp_id					as INT
	--DECLARE 		@option					AS INT
	--DECLARE 		@userId					AS INT
	--DECLARE 		@ret_Identity			as INT
	--DECLARE 		@ret_ErrorCode			as INT
	--DECLARE 		@ret_ErrorDescription	as VARCHAR(200)
	--set				@comp_id					= 1
	--set				@bra_id						= 1
	--set				@lang_id					= 2
	--set				@chp_id						= 1043
	--set				@option						= 2
	--set				@userId						= 1
	--set				@ret_Identity				= 0
	--set				@ret_ErrorCode				= 0
	--set				@ret_ErrorDescription		= ''
	-- ----------------------------------------------------------------


	SET NOCOUNT ON

	Set @ret_Identity		   = 0
	Set @ret_ErrorCode		   = 0
	Set @ret_ErrorDescription  = ''


	/****************************************************************************************/
	/*
		@option = 1 Cheque Rechazado
		@option = 2 Cheque Cancelado
		@option = 3 Deshacer Cheque Rechazado
		@option = 4 Deshacer Cheque Cancelado
	*/
	/****************************************************************************************/


	-- ----------------------------------------------------------------------------------
	-- Verifica si hay Asientos Contables para ésta Sucursal y Asigna el Grupo Contable.-
	-- ----------------------------------------------------------------------------------
	DECLARE		@ag_id				AS INT
	DECLARE		@datProcessingDate	AS DATETIME
	SELECT		@ag_id				= ag_id ,
				@datProcessingDate	= tb.bra_processingDate
		FROM	tbBranch tb			WITH (NOLOCK)
		WHERE	tb.comp_id = @comp_id
			AND tb.bra_id  = @bra_id
	If @ag_id is NULL RETURN
	-- ----------------------------------------------------------------------------------

	-- ----------------------------------------------------------------------------------
	-- Cabecera del Asiento
	-- ----------------------------------------------------------------------------------
	DECLARE @bitIsPayed		AS BIT
	DECLARE @currency_Id	AS INT
	Declare @hacc_number	as int
	Declare @hacc_detail	as varchar(60)
	Declare @ap_id			as INT

	Declare @Acc_Count_Id		AS INT
	Declare @Acc_Count_Id4CR	as int
	Declare @Acc_Count_Id4SupBA	as INT
	DECLARE @decTotal			AS DECIMAL(19,4)
	SET @decTotal	= 0

	Declare @dacc_debit		as decimal(19,6)
	set @dacc_debit = 0

	Declare @dacc_credit	as decimal(19,6)
	set @dacc_credit = 0

	Declare @utexts_desc	as varchar(60)
	Declare @tax_desc		as varchar(60)
	Declare @ctDetail  		as varchar(100)

	Declare @cc_code			as int
	Declare @ct_CompanyCurrency	as int
	Set		@cc_Code			= null
	Set		@ct_CompanyCurrency = Null

	Declare	@ct_date			as Datetime
	Set @ct_date = @datProcessingDate

	-- ----------------------------------------------
	-- Recupera la Moneda de la Compañia
	-- ----------------------------------------------
	Select @ct_CompanyCurrency = curr_id
		From dbo.tbCompany	WITH (NOLOCK)
		Where   comp_id = @comp_id

	If @ct_CompanyCurrency is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20218
			Return
		End
	-- ----------------------------------------------

	-- ----------------------------------------------
	-- Recupera el Centro de Costos desde la Sucursal
	-- ----------------------------------------------
	Select @cc_code = cc_code
		From dbo.tbBranch
		Where   comp_id = @comp_id
			and	bra_id  = @bra_id
	If @cc_code is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20217
			Return
		End
	-- ----------------------------------------------

	-- ----------------------------------------------
	-- Recupera el Nombre del Asiento,
	--  si es que es nuevo
	-- ----------------------------------------------
	Select @ctDetail = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where   lang_id = @lang_id
							and utexts_id = (223800 + @option)
	-- --------------------------------------------------

	-- --------------------------------------------------
	-- Recupera el Grupo de Asiento Contable		OK
	-- --------------------------------------------------
	Declare @hacc_group as int

	Select @hacc_group = C.hacc_group
		From dbo.tbsysDocuments			C			WITH (NOLOCK)
		Where C.sd_id = 206
	-- --------------------------------------------------





	-- ----------------------------------------------------------------------------------
	-- Si el Grupo Contable establece una moneda, toma esa moneda para asientos.
	-- ----------------------------------------------------------------------------------
	SELECT @ct_CompanyCurrency =	CASE
										WHEN tag.ag_curr_id IS NULL THEN	@ct_CompanyCurrency
										ELSE								tag.ag_curr_id
									END
		FROM tbAccountantGroup AS tag	WITH (NOLOCK)
		WHERE	tag.comp_id = @comp_id AND
				tag.ag_id	= @ag_id
	-- ----------------------------------------------------------------------------------







	-- ------------------------------------------------------------------
	-- Verifica si hay un Asiento de la Compañia
	-- y Sucursal con ese Grupo	OK
	-- ------------------------------------------------------------------
	Declare @hacc_transaction as int

	Select @hacc_transaction = hacc_transaction
		From dbo.tbAccountTransactionHead			WITH (NOLOCK)
		Where   comp_id			= @comp_id
			and bra_id			= @bra_id
			and hacc_group		= @hacc_group
			and hacc_date		= @ct_date
			and hacc_IsEditing	= 'False'
			AND ag_id			= @ag_id
			AND dbo.fnGetOnlyDate(hacc_cd)	= dbo.fnGetOnlyDate(GETDATE())
	-- ------------------------------------------------------------------

	--	-----------------------------------------------------------------
	--  Si no hay Cabecera dada de alta, la da de alta
	--	-----------------------------------------------------------------
	If IsNull(@hacc_transaction,0) = 0
		Begin

			-- Obtiene Proximo Numero de Asiento.-
			EXEC dbo.spCounters_getNextValue @comp_id, 0, 3, @counter_value = @hacc_number OUTPUT

			-- -------------------------------
			-- Obtiene Descripcion del Asiento OK
			-- -------------------------------
				Select @hacc_detail = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where   lang_id = @lang_id
						and utexts_id = (223800 + @option)
			-- -------------------------------

			-- -------------------------------
			-- Obtiene el Periodo
			-- Correspondiente a la fecha			OK
			-- -------------------------------
			SELECT @ap_id = NULL
			Select @ap_id = ap.ap_id
				From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
				INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
					ON	tapbb.comp_id	=	ap.comp_id	AND
						tapbb.bra_id	=	@bra_id		AND
						tapbb.ap_id		=	ap.ap_id
				Where   ap.comp_id		=	@comp_id
					and ap.ap_firstdate <=	@ct_date
					and ap.ap_lastdate  >=	@ct_date
					and ap.ap_closed	=	'False'

			IF @ap_id IS NULL
				BEGIN
					Select @ap_id = ap_id
						From dbo.tbAccountantPeriod			WITH (NOLOCK)
						Where   comp_id = @comp_id
							and ap_firstdate <= @ct_date
							and ap_lastdate  >= @ct_date
							and ap_closed='False'
				END

			If @ap_id is Null
				Begin
					Set @ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20206
					Return
				End
			-- --------------------------------------------------


			-- --------------------------------------------------
			-- Inserta Header Nuevo						OK
			-- --------------------------------------------------
			Insert Into dbo.tbAccountTransactionHead
				(	comp_id,
					bra_id,
					hacc_group,
					hacc_detail,
					hacc_date,
					hacc_number,
					hacc_orderPriority,
					hacc_cd,
					ap_id,
					hacc_blocked,
					hacc_closing,
					hacc_opening,
					hacc_IsEditing,
					hacc_IsEditingDateTime,
					ag_id
				)
				Values
				(	@comp_id,
					@bra_id,
					@hacc_group,
					@hacc_detail,
					@ct_date,
					@hacc_number,
					0,
					getdate(),
					@ap_id,
					'False',
					'False',
					'False',
					'False',
					GetDate(),
					@ag_id
				)

			Set @hacc_transaction = @@identity
		End
	-- ----------------------------------------------------------------------------------

	-- ----------------------------------------------------------------------------------
	-- Detalle
	-- ----------------------------------------------------------------------------------

	-- Obtiene Datos del Cheque
	Select @decTotal	= chp_total,
		   @currency_Id = tcp1.curr_id
		From dbo.tbCheckPortfolio tcp1
		Where   tcp1.comp_id = @comp_id
			and tcp1.chp_id  = @chp_id

	-- Setea el Importe de la Imputación Contable
	Set @decTotal	= dbo.fnGetExchange(	@comp_id,
											@decTotal,
											@currency_id,
											@ct_CompanyCurrency,
											0,
											0,
											0)


	-- ---------------------------------------------------------
	-- Obtener la Cuenta del Debe  (@Acc_Count_Id4CR)
	-- ---------------------------------------------------------
	SET @Acc_Count_Id4CR = null
	If IsNull(@Acc_Count_Id4CR,0) = 0
		Begin
			Select @Acc_Count_Id4CR = acc_count_id
				From dbo.tbAccountManagementRelations A			WITH (NOLOCK)
				Where   comp_id		= @comp_id
					and bra_id		= @bra_id
					and samr_id		= CASE @option
										when 1 then 550
										when 2 then 560
										when 3 then 550
										when 4 then 560
									  END
		End


	If IsNull(@Acc_Count_Id4CR,0) = 0
	Begin
		Set	@ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
				From dbo.tbsysUniqueTexts			WITH (NOLOCK)
				Where lang_id = @lang_id and  utexts_id =	CASE @option
																when 1 then 20231
																WHEN 2 THEN 20232
																WHEN 3 THEN 20231
																WHEN 4 THEN 20232
															END
			Return
	End


	Select @utexts_desc		= utexts_desc
		From dbo.tbsysUniqueTexts			WITH (NOLOCK)
		Where	lang_id		= @lang_id
			and utexts_id	=	CASE @option
									WHEN 1 THEN 202501
									WHEN 2 THEN 202502
									WHEN 3 THEN 202501
									WHEN 4 THEN 202502
								END

	Set @utexts_desc		= @ctDetail + ' ' + @utexts_desc




	-- ---------------------------------------------------------
	-- Obtener la Cuenta del Haber:  Es la del Proveedor si se
	-- entrego x o.pago o la del Banco si se depositó (@Acc_Count_Id4SupBA)
	-- ---------------------------------------------------------
	DECLARE @bitIs4Payment AS BIT
	SET @Acc_Count_Id4SupBA = NULL

	-- Primero Busca si se Pagó a un Proveedor
	SELECT TOP 1 @bitIs4Payment =	Case
										When IsNull(tct.ct_transaction ,-1) > 0 THEN 'True'
										ELSE 'False'
									End ,
				 @Acc_Count_Id4SupBA  = ts.acc_count_id
		FROM tbCheckPortfolioMovements tcpm				WITH (NOLOCK)
		INNER JOIN tbCheckPortfolio tcp1				WITH (NOLOCK)
			ON		tcp1.comp_id		= tcpm.comp_id
				AND tcp1.chp_id			= tcpm.chp_id
		INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
			ON		tct.comp_id			= tcpm.comp_id
				AND tct.ct_transaction	= tcpm.ct_transaction
		INNER JOIN tbsysDocuments td					WITH (NOLOCK)
			ON tct.sd_id = td.sd_id
		INNER JOIN tbSupplier ts							WITH (NOLOCK)
			ON		ts.comp_id = tct.comp_id
				AND ts.supp_id = tct.supp_id
		WHERE	td.sd_id		= 106
			and tcp1.comp_id	= @comp_id
			AND tcp1.chp_id		= @chp_id
			ORDER BY tcpm.chpm_id DESC

	-- Si SE PAGÓ pero no hay definida una cuenta contable, hay que ir a buscarla a la definición
	If IsNull(@Acc_Count_Id4SupBA,0) = 0 AND @bitIs4Payment = 'True'
		BEGIN


			Select @Acc_Count_Id4SupBA = acc_count_id
				From dbo.tbAccountManagementRelations A			WITH (NOLOCK)
				Where   comp_id		= @comp_id
					and bra_id		= @bra_id
					and samr_id		= 300 --Proveedores

			If IsNull(@Acc_Count_Id4SupBA,0) = 0
				Begin
					Set	@ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20234
						Return
				End


		End



	-- Si no se encontro una cuenta aún, se supone que el valor fué DEPOSITADO.. vamos a buscar la cuenta..
	If IsNull(@Acc_Count_Id4SupBA,0) = 0
		Begin

			DECLARE @bitIs4Deposit AS BIT
			SELECT TOP 1 @bitIs4Deposit =	Case
												When IsNull(tct.ct_transaction ,-1) > 0 THEN 'True'
												ELSE 'False'
											End ,
						 @Acc_Count_Id4SupBA  = tba.acc_count_id
				FROM tbCheckPortfolioMovements tcpm			WITH (NOLOCK)
				INNER JOIN tbCheckPortfolio tcp1				WITH (NOLOCK)
					ON		tcp1.comp_id		= tcpm.comp_id
						AND tcp1.chp_id			= tcpm.chp_id
				INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
					ON		tct.comp_id			= tcpm.comp_id
						AND tct.ct_transaction	= tcpm.ct_transaction
				INNER JOIN tbsysDocuments td					WITH (NOLOCK)
					ON tct.sd_id = td.sd_id
				INNER JOIN tbBankingAccounts tba					WITH (NOLOCK)
					ON		tba.comp_id = tcpm.comp_id
						AND tba.ba_id	= tcpm.ba_id

				WHERE	td.sd_id		= 200	-- Depósito Bancario
					and tcp1.comp_id	= @comp_id
					AND tcp1.chp_id		= @chp_id
					ORDER BY tcpm.chpm_id DESC
		End

	-- Si aun no se encontro es que está en la Cartera por lo que es la cuenta de Cartera de Valores
	If IsNull(@Acc_Count_Id4SupBA,0) = 0
		Begin
			Select @Acc_Count_Id4SupBA = acc_count_id
				From dbo.tbAccountManagementRelations A			WITH (NOLOCK)
				Where   comp_id		= @comp_id
					and bra_id		= @bra_id
					and samr_id		= 200 --Cartera de Valores
		END
	If IsNull(@Acc_Count_Id4SupBA,0) = 0
		Begin
			Set	@ret_ErrorCode = -1
				Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20233
				Return
		End




	-- Graba imputación para Cuenta cd valores Rechazados
	IF @option = 1 OR @option = 2
		BEGIN
			set @dacc_debit		= @decTotal
			SET @dacc_credit	= 0
			SET @Acc_Count_Id   = @Acc_Count_Id4CR
		END
	ELSE
		BEGIN
			set @dacc_debit		= @decTotal
			SET @dacc_credit	= 0
			SET @Acc_Count_Id   = @Acc_Count_Id4SupBA
		END

	INSERT INTO dbo.tbAccountTransactionDetail
		   (comp_id,
		    bra_id,
		    hacc_transaction,
		    acc_count_id,
		    cc_code,
		    dacc_debit,
		    dacc_credit,
		    user_id,
		    dacc_cd,
		    hacc_software,
		    ct_transaction,
		    acc_detail1,
		    acc_detail2,
			dacc_order)
	 VALUES
		   (@comp_id,
		    @bra_id,
		    @hacc_transaction,
		    @acc_count_id,
		    @cc_code,
		    @dacc_debit,
		    @dacc_credit,
		    @userId,
		    getdate(),
		    'True',
		    NULL,
		    @utexts_desc,
		    '',
			3
		   )


	-- Graba imputación para Cuenta Proveedores o Cta Bancaria
	IF @option = 1 OR @option = 2
		BEGIN
			set @dacc_debit		= 0
			SET @dacc_credit	= @decTotal
			SET @Acc_Count_Id   = @Acc_Count_Id4SupBA
		END
	ELSE
		BEGIN
			set @dacc_debit		= 0
			SET @dacc_credit	= @decTotal
			SET @Acc_Count_Id   = @Acc_Count_Id4CR
		END

	INSERT INTO dbo.tbAccountTransactionDetail
		   (comp_id,
		    bra_id,
		    hacc_transaction,
		    acc_count_id,
		    cc_code,
		    dacc_debit,
		    dacc_credit,
		    user_id,
		    dacc_cd,
		    hacc_software,
		    ct_transaction,
		    acc_detail1,
		    acc_detail2,
			dacc_order)
	 VALUES
		   (@comp_id,
		    @bra_id,
		    @hacc_transaction,
		    @acc_count_id,
		    @cc_code,
		    @dacc_debit,
		    @dacc_credit,
		    @userId,
		    getdate(),
		    'True',
		    NULL,
		    @utexts_desc,
		    '',
			3
		   )



END
GO





-- =============================================
-- Author:		MOS
-- Asiento Contable de wfmChequePayment
-- Create date: 03-2009
-- =============================================
CREATE PROCEDURE [dbo].[spAccountTransaction_InsertdataFromChequePayment]
	(
		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as int,
		@ba_id					as int,
		@ec_id					as int,
		@ec_isPaid				As Bit,
		@processing_date		As Datetime,
		@user_id				as int,
		@ret_Identity			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
	)
AS

BEGIN

	SET NOCOUNT ON


	Set @ret_Identity		   = 0
	Set @ret_ErrorCode		   = 0
	Set @ret_ErrorDescription  = ''

	-- ----------------------------------------------------------------------------------
	-- Verifica si hay Asientos Contables para ésta Sucursal y Asigna el Grupo Contable.-
	-- ----------------------------------------------------------------------------------
	DECLARE		@ag_id AS INT
	SELECT		@ag_id = ag_id
		FROM	tbBranch tb			WITH (NOLOCK)
		WHERE	tb.comp_id = @comp_id
			AND tb.bra_id  = @bra_id
	If @ag_id is NULL RETURN

	-- Agregar cuando busca un asiento existente el grupo contable
	-- ----------------------------------------------------------------------------------


	Declare @acc_count_BankingAccount		as int
	Declare @acc_count_BankingAccountPayed	as Int

	Declare @hacc_number	as int
	Declare @hacc_detail	as varchar(60)
	Declare @ap_id			as int
	Declare @Acc_Count_Id	as int


	Declare @dacc_debit		as decimal(19,6)
	set @dacc_debit = 0

	Declare @dacc_credit	as decimal(19,6)
	set @dacc_credit = 0


	Declare @utexts_desc	as varchar(60)
	Declare @tax_desc		as varchar(60)
	Declare @ctDetail  		as varchar(100)

	Declare @cc_code			as int
	Declare @ct_CompanyCurrency	as int
	Set		@cc_Code			= null
	Set		@ct_CompanyCurrency = Null

	Declare	@ct_date			as Datetime
	Set @ct_date = @processing_date

	-- ----------------------------------------------
	-- Recupera la Moneda de la Compañia
	-- ----------------------------------------------
	Select @ct_CompanyCurrency = curr_id
		From dbo.tbCompany	WITH (NOLOCK)
		Where   comp_id = @comp_id

	If @ct_CompanyCurrency is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20218
			Return
		End
	-- ----------------------------------------------




	-- ----------------------------------------------------------------------------------
	-- Si el Grupo Contable establece una moneda, toma esa moneda para asientos.
	-- ----------------------------------------------------------------------------------
	SELECT @ct_CompanyCurrency =	CASE
										WHEN tag.ag_curr_id IS NULL THEN	@ct_CompanyCurrency
										ELSE								tag.ag_curr_id
									END
		FROM tbAccountantGroup AS tag	WITH (NOLOCK)
		WHERE	tag.comp_id = @comp_id AND
				tag.ag_id	= @ag_id
	-- ----------------------------------------------------------------------------------



	-- ----------------------------------------------
	-- Recupera el Centro de Costos desde la Sucursal
	-- ----------------------------------------------
	Select @cc_code = cc_code
		From dbo.tbBranch
		Where   comp_id = @comp_id
			and	bra_id  = @bra_id
	If @cc_code is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20217
			Return
		End
	-- ----------------------------------------------

	-- ----------------------------------------------
	-- Recupera el Nombre del Asiento,
	--  si es que es nuevo
	-- ----------------------------------------------
	Select @ctDetail = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where   lang_id = @lang_id
							and utexts_id = 202200
	-- --------------------------------------------------

	-- --------------------------------------------------
	-- Recupera el Grupo de Asiento Contable		OK
	-- --------------------------------------------------
	Declare @hacc_group as int

	Select @hacc_group = C.hacc_group
		From dbo.tbsysDocuments			C			WITH (NOLOCK)
		Where C.sd_id = 206
	-- --------------------------------------------------

	---- --------------------------------------------------
	---- Recupera Moneda de la compañia,
	---- para hacer el asiento.-
	---- --------------------------------------------------
	--Select @ct_CompanyCurrency = curr_id
	--	From dbo.tbCompany			WITH (NOLOCK)
	--	Where comp_id = @comp_id
	---- --------------------------------------------------

	-- ------------------------------------------------------------------
	-- Verifica si hay un Asiento de la Compañia
	-- y Sucursal con ese Grupo	OK
	-- ------------------------------------------------------------------
	Declare @hacc_transaction as int

	Select @hacc_transaction = hacc_transaction
		From dbo.tbAccountTransactionHead			WITH (NOLOCK)
		Where   comp_id			= @comp_id
			and bra_id			= @bra_id
			and hacc_group		= @hacc_group
			and hacc_date		= @ct_date
			and hacc_IsEditing	= 'False'
			AND ag_id			= @ag_id
			AND dbo.fnGetOnlyDate(hacc_cd)	= dbo.fnGetOnlyDate(GETDATE())
	-- ------------------------------------------------------------------

	--	-----------------------------------------------------------------
	--  Si no hay Cabecera dada de alta, la da de alta
	--	-----------------------------------------------------------------
	If IsNull(@hacc_transaction,0) = 0
		Begin

			-- Obtiene Proximo Numero de Asiento.-
			EXEC dbo.spCounters_getNextValue @comp_id, 0 , 3, @counter_value = @hacc_number OUTPUT

			-- -------------------------------
			-- Obtiene Descripcion del Asiento OK
			-- -------------------------------
				Select @hacc_detail = utexts_desc
					From dbo.tbsysUniqueTexts			WITH (NOLOCK)
					Where   lang_id = @lang_id
						and utexts_id = 202200
			-- -------------------------------

			-- -------------------------------
			-- Obtiene el Periodo
			-- Correspondiente a la fecha			OK
			-- -------------------------------
			SELECT @ap_id = NULL
			Select @ap_id = ap.ap_id
				From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
				INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
					ON	tapbb.comp_id	=	ap.comp_id	AND
						tapbb.bra_id	=	@bra_id		AND
						tapbb.ap_id		=	ap.ap_id
				Where   ap.comp_id		=	@comp_id
					and ap.ap_firstdate <=	@ct_date
					and ap.ap_lastdate  >=	@ct_date
					and ap.ap_closed	=	'False'

			IF @ap_id IS NULL
				BEGIN
					Select @ap_id = ap_id
						From dbo.tbAccountantPeriod			WITH (NOLOCK)
						Where   comp_id = @comp_id
							and ap_firstdate <= @ct_date
							and ap_lastdate  >= @ct_date
							and ap_closed='False'
				END


			If @ap_id is Null
				Begin
					Set @ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20206
					Return
				End
			-- --------------------------------------------------


			-- --------------------------------------------------
			-- Inserta Header Nuevo						OK
			-- --------------------------------------------------
			Insert Into dbo.tbAccountTransactionHead
				(	comp_id,
					bra_id,
					hacc_group,
					hacc_detail,
					hacc_date,
					hacc_number,
					hacc_orderPriority,
					hacc_cd,
					ap_id,
					hacc_blocked,
					hacc_closing,
					hacc_opening,
					hacc_IsEditing,
					hacc_IsEditingDateTime,
					ag_id
				)
				Values
				(	@comp_id,
					@bra_id,
					@hacc_group,
					@hacc_detail,
					@ct_date,
					@hacc_number,
					0,
					getdate(),
					@ap_id,
					'False',
					'False',
					'False',
					'False',
					GetDate(),
					@ag_id
				)

			Set @hacc_transaction = @@identity
		End
		--	-----------------------------------------------------------------


		-- ------------------------------------------------------------------
		-- Comienza Asiento de Control de Debito
		-- ------------------------------------------------------------------
		Set @acc_count_BankingAccount		= null

		Set @acc_count_BankingAccountPayed	= null
		Set @acc_count_BankingAccount		= null


		-- -----------------------------------
		-- Busca cuenta de Cuentas Bancarias
		-- -----------------------------------
		Select @acc_count_BankingAccount = A.acc_count_id
			From dbo.tbBankingAccounts A			WITH (NOLOCK)
			Where   comp_id		= @comp_id
				and ba_id		= @ba_id

		If IsNull(@acc_count_BankingAccount,0) = 0
			Begin
				Set	@ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20201
					Return
			End
		-- -----------------------------------

		-- -----------------------------------
		-- Busca cuenta de Cuentas Bancarias
		-- -----------------------------------
		Select @acc_count_BankingAccountPayed = A.acc_count_id_notPayed
			From dbo.tbBankingAccounts A
			Where   comp_id		= @comp_id
				and ba_id		= @ba_id

		If IsNull(@acc_count_BankingAccountPayed,0) = 0
			Begin
				Set	@ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20224
					Return
			End
		-- -----------------------------------

		Declare @Total As Decimal(19,5)
		Declare @curr_id As integer
		Select @Total	= tec.ec_total,
			   @curr_id = tec.curr_id
			From tbEmmitedChecks tec			WITH (NOLOCK)
			Where	tec.comp_id = @comp_id
				And tec.ec_id   = @ec_id

		Set @Total = dbo.fnGetExchange(	@comp_id,
												@Total,
												@curr_id,
												@ct_CompanyCurrency,
												0,
												0,
												0)


	If @ec_ispaid='true'
		BEGIN

		if @acc_count_BankingAccountPayed <> @acc_count_BankingAccount
			BEGIN

				INSERT INTO dbo.tbAccountTransactionDetail
						   (comp_id,
							bra_id,
							hacc_transaction,
							acc_count_id,
							cc_code,
							dacc_debit,
							dacc_credit,
							user_id,
							dacc_cd,
							hacc_software,
							ct_transaction,
							acc_detail1,
							acc_detail2,
							dacc_order)
					 VALUES
						   (@comp_id,
							@bra_id,
							@hacc_transaction,
							@acc_count_BankingAccountPayed,
							@cc_code,
							@Total,
							0,
							@user_id,
							getdate(),
							'True',
							null,
							@utexts_desc,
							@tax_desc,
							10)


				INSERT INTO dbo.tbAccountTransactionDetail
						   (comp_id,
							bra_id,
							hacc_transaction,
							acc_count_id,
							cc_code,
							dacc_debit,
							dacc_credit,
							user_id,
							dacc_cd,
							hacc_software,
							ct_transaction,
							acc_detail1,
							acc_detail2,
							dacc_order)
					 VALUES
						   (@comp_id,
							@bra_id,
							@hacc_transaction,
							@acc_count_BankingAccount,
							@cc_code,
							0,
							@Total,
							@user_id,
							getdate(),
							'True',
							null,
							@utexts_desc,
							@tax_desc,
							10)
			END
		END

	Else
		BEGIN

			if @acc_count_BankingAccountPayed <> @acc_count_BankingAccount
				BEGIN
					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_BankingAccountPayed,
								@cc_code,
								0,
								@Total,
								@user_id,
								getdate(),
								'True',
								null,
								@utexts_desc,
								@tax_desc,
								10)


					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_BankingAccount,
								@cc_code,
								@Total,
								0,
								@user_id,
								getdate(),
								'True',
								null,
								@utexts_desc,
								@tax_desc,
								10)
				END

			END

		-- ------------------------------------------------------------------
		-- Fin      Asiento de Deposito de Cheques
		-- ------------------------------------------------------------------

	-- No lleva verificador de balanceo.



	Return

END
GO





-- =============================================
-- Author:		MOS
-- Fijarse que si se agrega un campo a la BD
-- hay que tocar todos los SP que se llaman
-- parecidos a este.-
-- Create date: 01-2009
-- =============================================

CREATE PROCEDURE [dbo].[spAccountTransaction_InsertdataFromManagement_Collection]
	(
		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as int,
		@ct_Transaction			as int,
		@user_id				as int,
		@acc_count_id_4Haber	AS INT,
		@ret_Identity			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
	)
AS

BEGIN
	SET NOCOUNT ON

/*
	-- ---------------------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------------------
	DECLARE 		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as int,
		@ct_Transaction			as int,
		@user_id				as int,
		@ret_Identity			as int			,
		@ret_ErrorCode			as int			,
		@ret_ErrorDescription	as varchar(200)
	SELECT 		@comp_id				=1,
		@bra_id					=1,
		@lang_id				=2,
		@ct_Transaction			=3893,
		@user_id				=1
	-- ---------------------------------------------------------------------------------
*/


	Set @ret_Identity		   = 0
	Set @ret_ErrorCode		   = 0
	Set @ret_ErrorDescription  = ''


	-- --------------------------------------------------------------------------------
	-- Si es un cliente para Carga Inicial de Valores, NO HACE Asiento Contable.-------
	-- --------------------------------------------------------------------------------
	IF EXISTS ( SELECT TOP 1  1
					FROM tbCommercialTransactions	tct			WITH (NOLOCK)
					INNER JOIN tbCustomer			tc			WITH (NOLOCK)
						ON		tc.comp_id			= tct.comp_id
							AND tc.cust_id			= tct.cust_id
					WHERE	tct.comp_id				= @comp_id
						--AND tct.bra_id				= @bra_id
						AND tct.ct_transaction		= @ct_Transaction
						AND tc.cust_4InitialValues	= 'True')
		BEGIN
			UPDATE tbCommercialTransactions	WITH (ROWLOCK)
				SET	ct_ABalance = 0
				WHERE	comp_id				= @comp_id
					AND bra_id				= @bra_id
					AND ct_transaction		= @ct_Transaction
			RETURN
		END
	-- --------------------------------------------------------------------------------



	-- --------------------------------------------------------------------------------
	-- Si es un recibo de carga de valores, pone el saldo en CERO
	-- --------------------------------------------------------------------------------
	DECLARE @sd_id AS int = -1
	SELECT  @sd_id = tdf.sd_id
		FROM tbCommercialTransactions	tct			WITH (NOLOCK)
		INNER JOIN tbDocumentsFile   AS tdf			WITH (NOLOCK)
			ON	tdf.comp_id = tct.comp_id AND
				tdf.df_id	= tct.df_id
		WHERE	tct.comp_id				= @comp_id		AND
				tct.ct_transaction		= @ct_Transaction
	IF @sd_id = 7
		BEGIN
			UPDATE tbCommercialTransactions	WITH (ROWLOCK)
				SET	ct_ABalance = 0
				WHERE	comp_id				= @comp_id
					AND bra_id				= @bra_id
					AND ct_transaction		= @ct_Transaction
		END
	-- --------------------------------------------------------------------------------



	-- ----------------------------------------------------------------------------------
	-- Verifica si hay Asientos Contables para ésta Sucursal y Asigna el Grupo Contable.-
	-- ----------------------------------------------------------------------------------
	DECLARE		@ag_id AS INT
	SELECT		@ag_id = ag_id
		FROM	tbBranch tb					WITH (NOLOCK)
		WHERE	tb.comp_id = @comp_id
			AND tb.bra_id  = @bra_id
	If @ag_id is NULL RETURN

	-- Agregar cuando busca un asiento existente el grupo contable
	-- ----------------------------------------------------------------------------------







	DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT_Acc		-- MOS 06-2020
    --SAVE TRANSACTION traPROTECT
    --BEGIN TRANSACTION
    BEGIN TRY



		Declare @IsACredit      	as bit
		Declare @hacc_number		as int
		Declare @hacc_detail		as varchar(60)
		Declare @ap_id				as int
		Declare @Acc_Count_Id		as int
		Declare @dacc_debit			as decimal(19,6)
		Declare @dacc_credit		as decimal(19,6)
		Declare @utexts_desc		as varchar(60)
		Declare @tax_desc			as varchar(60)
		Declare @ctDetail  			as varchar(100)
		Declare @ct_Date			as DateTime
		Declare @intCompanyCurrency as Int
		Declare @intBranchCurrency	as Int
		Declare @cc_code			as int

		Declare @intForcedExchangeCurrency  AS INT
		Declare @decForcedExchange			AS DECIMAL(19,6)

		Set @cc_Code			   = null

		-- Fecha Impositiva de la Transaccion
		Select @ct_Date                   = ct_taxDate,
			   @decForcedExchange		  = ct_Branch2CompanyCurrencyExchange
			From dbo.tbCommercialTransactions			WITH (NOLOCK)
			Where	comp_id			= @comp_id
				and	ct_transaction  = @ct_transaction


		-- Moneda de la Compañia
		Select @intCompanyCurrency = curr_id
			From dbo.tbCompany			WITH (NOLOCK)
			Where comp_id = @comp_id



	-- ----------------------------------------------------------------------------------
	-- Si el Grupo Contable establece una moneda, toma esa moneda para asientos.
	-- ----------------------------------------------------------------------------------
	SELECT @intCompanyCurrency =	CASE
										WHEN tag.ag_curr_id IS NULL THEN	@intCompanyCurrency
										ELSE								tag.ag_curr_id
									END
		FROM tbAccountantGroup AS tag	WITH (NOLOCK)
		WHERE	tag.comp_id = @comp_id AND
				tag.ag_id	= @ag_id
	-- ----------------------------------------------------------------------------------





		-- Moneda de la Sucursal
		Select @intBranchCurrency = curr_id,
			   @cc_code	    = cc_code
			From dbo.tbBranch			WITH (NOLOCK)
			Where	comp_id = @comp_id
				and	bra_id  = @bra_id

		-- Obtiene el tipo de cambio de la Sucursal a la Compañia
		SET @intForcedExchangeCurrency = @intBranchCurrency
		SET @decForcedExchange		   = @decForcedExchange

		Set @ctDetail = dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)

		--				Set	@ret_ErrorCode = -1
		--				Select	@ret_ErrorDescription = @ctDetail
		--				return

		-- Recupera el Grupo de Asiento Contable
		Declare @hacc_group as int

		Select @hacc_group = C.hacc_group,
			   @IsACredit  = C.	sd_isCredit
			From  dbo.tbCommercialTransactions		A			WITH (NOLOCK)
			Inner join dbo.tbsysDocuments			C			WITH (NOLOCK)
				On	C.sd_id			 = A.sd_id
			Where	A.comp_id		 = @comp_id
				and A.ct_transaction = @ct_transaction
		-- --------------------------------------

		-- ------------------------------------------------------------------
		-- Verifica si hay un Asiento de la Compañia y Sucursal con ese Grupo
		-- ------------------------------------------------------------------
		Declare @hacc_transaction as int

		Select @hacc_transaction = hacc_transaction
			From dbo.tbAccountTransactionHead			WITH (NOLOCK)
			Where   comp_id			= @comp_id
				and bra_id			= @bra_id
				and hacc_group		= @hacc_group
				and hacc_date		= @ct_date
				and hacc_IsEditing	= 'False'
				AND ag_id			= @ag_id
				AND dbo.fnGetOnlyDate(hacc_cd)	= dbo.fnGetOnlyDate(GETDATE())
		-- ------------------------------------------------------------------

		--	-----------------------------------------------------------------
		--  Si no hay Cabecera dada de alta, la da de alta
		--	-----------------------------------------------------------------
		If IsNull(@hacc_transaction,0) = 0
			Begin

				-- Obtiene Proximo Numero de Asiento.-
				EXEC dbo.spCounters_getNextValue @comp_id, 0 , 3, @counter_value = @hacc_number OUTPUT

				-- -------------------------------
				-- Obtiene Descripcion del Asiento
				-- -------------------------------
					Select @hacc_detail = utexts_desc
						From dbo.tbsysUniqueTexts		WITH (NOLOCK)
						Where   lang_id = @lang_id
							and utexts_id = 222001
				-- -------------------------------

				-- -------------------------------
				-- Obtiene el Periodo
				-- Correspondiente a la fecha
				-- -------------------------------
				SELECT @ap_id = NULL
				Select @ap_id = ap.ap_id
					From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
					INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
						ON	tapbb.comp_id	=	ap.comp_id	AND
							tapbb.bra_id	=	@bra_id		AND
							tapbb.ap_id		=	ap.ap_id
					Where   ap.comp_id		=	@comp_id
						and ap.ap_firstdate <=	@ct_date
						and ap.ap_lastdate  >=	@ct_date
						and ap.ap_closed	=	'False'

				IF @ap_id IS NULL
					BEGIN
						Select @ap_id = ap_id
							From dbo.tbAccountantPeriod			WITH (NOLOCK)
							Where   comp_id = @comp_id
								and ap_firstdate <= @ct_date
								and ap_lastdate  >= @ct_date
								and ap_closed='False'
					END


				If @ap_id is Null
					BEGIN
						Set @ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc + '-01'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20206
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
						RETURN
					End

				-- -------------------------------


				-- Inserta Header Nuevo
				Insert Into dbo.tbAccountTransactionHead
					(	comp_id,
						bra_id,
						hacc_group,
						hacc_detail,
						hacc_date,
						hacc_number,
						hacc_orderPriority,
						hacc_cd,
						ap_id,
						hacc_blocked,
						hacc_closing,
						hacc_opening,
						hacc_IsEditing,
						hacc_IsEditingDateTime,
						ag_id
					)
					Values
					(	@comp_id,
						@bra_id,
						@hacc_group,
						@hacc_detail,
						@ct_date,
						@hacc_number,
						0,
						getdate(),
						@ap_id,
						'False',
						'False',
						'False',
						'False',
						GetDate(),
						@ag_id
					)

				Set @hacc_transaction = @@identity
			End
			--	-----------------------------------------------------------------

--***
			DECLARE @intCustId AS INT
			SELECT @intCustId = tct.cust_id
			FROM tbCommercialTransactions tct			WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id AND
						tct.ct_transaction	= @ct_Transaction


			-- ------------------------------------------------------------------
			-- Comienzo de Imputacion de Deudores por Ventas
			-- ------------------------------------------------------------------
			Set		@acc_count_id = null
			Select @acc_count_id  = acc_count_id
				From dbo.tbCustomer			WITH (NOLOCK)
				Where   comp_id = @comp_id
					and cust_id = @intCustId


			-- Si es un cpte de ingreso de valores y tiene asignada una cuenta para el HABER desde wfmCollection, lo reemplaza aquí
			IF @acc_count_id_4Haber > 0
				BEGIN
					SET @Acc_Count_Id = @acc_count_id_4Haber
				END


			If IsNull(@acc_count_id,0) = 0
				Begin
					Select @acc_count_id = acc_count_id
						From dbo.tbCustomer		WITH (NOLOCK)
						Where   comp_id = @comp_id
							and cust_id = @intCustId
				End

			If IsNull(@acc_count_id,0) = 0
				Begin
					Select @acc_count_id = acc_count_id
						From dbo.tbAccountManagementRelations A		WITH (NOLOCK)
						Where   comp_id		= @comp_id
							and bra_id		= @bra_id
							and samr_id		= 1
				End


			If IsNull(@acc_count_id,0) = 0
				Begin
					Set	@ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc + '-02'
						From dbo.tbsysUniqueTexts		WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20207
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
						Return
				End


			Select @dacc_credit = (ct_total - ct_adjust)
				From dbo.tbCommercialTransactions		WITH (NOLOCK)
				Where   comp_id = @comp_id
					and ct_transaction = @ct_transaction

			Set @dacc_debit  = 0

			Set @dacc_credit = dbo.fnGetExchange( 	@comp_id,
													@dacc_credit,
													@intBranchCurrency,
													@intCompanyCurrency,
													@intForcedExchangeCurrency ,
													@decForcedExchange,
													0)


			Select @utexts_desc		= utexts_desc
				From dbo.tbsysUniqueTexts		WITH (NOLOCK)
				Where	lang_id		= @lang_id
					and utexts_id	= 202020

			Set @utexts_desc		= @ctDetail + ' ' + @utexts_desc

	--SELECT @dacc_credit

			INSERT INTO dbo.tbAccountTransactionDetail
				   (comp_id,
					bra_id,
					hacc_transaction,
					acc_count_id,
					cc_code,
					dacc_debit,
					dacc_credit,
					user_id,
					dacc_cd,
					hacc_software,
					ct_transaction,
					acc_detail1,
					acc_detail2,
					dacc_order)
			 VALUES
				   (@comp_id,
					@bra_id,
					@hacc_transaction,
					@acc_count_id,
					@cc_code,
					@dacc_debit,
					@dacc_credit,
					@user_id,
					getdate(),
					'True',
					@ct_transaction,
					@utexts_desc,
					'',
					3
				   )
			-- ------------------------------------------------------------------
			-- FIN de Imputacion de Deudores por Ventas
			-- ------------------------------------------------------------------

	--select 'tax'

			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de tbTaxMovement
			-- ------------------------------------------------------------------
			Declare @curTax_id		as int
			Declare @curTm_Total	as decimal(19,6)
			Declare @curCurr_id		as int

			Set @dacc_debit	 = 0
			Set @dacc_credit = 0

			Declare curTaxMovements
				CURSOR LOCAL FAST_FORWARD For
					Select	tax_id,
							tm_total,
							curr_id
						From dbo.tbTaxMovements			WITH (NOLOCK)
						Where	comp_id			= @comp_id
							and	ct_transaction	= @ct_transaction

			Open		curTaxMovements

			Fetch Next From curTaxMovements
				Into	@curTax_id,
						@curTm_Total,
						@curCurr_id

			While @@Fetch_Status = 0
				Begin

					Set @acc_count_id	 = null
					-- Buscar la Cuenta Contable que Corresponde
					Select @Acc_Count_Id = acc_count_id_forSale
						From dbo.tbAccountByTaxName		WITH (NOLOCK)
						Where   comp_id    = @comp_id
							and bra_id     = @bra_id
							and tax_id	   = @curTax_id


					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = 'ID(' + CONVERT(NVARCHAR(10),@curTax_id) + ') ' + utexts_desc   + '-03'
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20205
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End

					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts	WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202010    -- IMPUESTOS
					Select @tax_desc	= tax_desc		From dbo.tbTaxName			WITH (NOLOCK)	Where comp_id = @comp_id and tax_id = @curTax_id
					Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc
					-- Pone el Tipo de Cambio Correspondiente, de la moneda
					-- de la sucursal a la moneda de la compañia,
					-- ya que la contabilidad se hace en la moneda de la compañia.-
					Set @dacc_credit = 0

					Set @dacc_debit  = dbo.fnGetExchange(	@comp_id,
															@curTm_Total,
															@curCurr_id,
															@intCompanyCurrency,
															@intForcedExchangeCurrency ,
															@decForcedExchange,
															0)

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_id,
								@cc_code,
								@dacc_debit,
								@dacc_credit,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								@tax_desc,
								10)

					Fetch Next From curTaxMovements
						Into	@curTax_id,
								@curTm_Total,
								@curCurr_id

				End



			Close		curTaxMovements
			Deallocate	curTaxMovements
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbTaxMovement
			-- ------------------------------------------------------------------




			-- ------------------------------------------------------------------
			-- Asiento de tbAccounbtTransactions
			-- ------------------------------------------------------------------
			DECLARE @curAM_curr_id			AS INT
			DECLARE @curAM_atcm_total		AS DECIMAL(19,4)
			DECLARE @curAM_acc_count_id		AS INT
			DECLARE @curAM_atcm_reference	AS NVARCHAR(250)
			Declare curAccountantMovements
				CURSOR LOCAL  FAST_FORWARD For
					Select	rr.curr_id,
							rr.atcm_total,
							rr.acc_count_id,
							rr.atcm_reference
						From dbo.tbAccountantMovements	rr		WITH (NOLOCK)
						Where	comp_id			= @comp_id
							and	ct_transaction	= @ct_transaction

			Open curAccountantMovements

			Fetch Next From curAccountantMovements
				Into	@curAM_curr_id,
						@curAM_atcm_total,
						@curAM_acc_count_id,
						@curAM_atcm_reference

			While @@Fetch_Status = 0
				BEGIN

					INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@curAM_acc_count_id,
									NULL,
									@curAM_atcm_total,
									0,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@curAM_atcm_reference,
									'',
									10)



					Fetch Next From curAccountantMovements
						Into	@curAM_curr_id,
								@curAM_atcm_total,
								@curAM_acc_count_id,
								@curAM_atcm_reference

				END
			CLOSE		curAccountantMovements
			DEALLOCATE	curAccountantMovements
			-- ------------------------------------------------------------------
			-- FIN Asiento de tbAccounbtTransactions
			-- ------------------------------------------------------------------




			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de tbMoneyMovements
			-- ------------------------------------------------------------------
			Declare @curCredit 							as decimal(19,6)
			Declare @curDebit  							as decimal(19,6)
			Declare @decTotalCursor						as decimal(19,5)
			Declare @decTotal2Branch					as decimal(19,5)
			Declare @decTotal2Company					as decimal(19,5)
			--Declare @curCurr_id						as int
			Declare @curr_desc							as varchar(50)
			Declare @acc_count_id_ExchDiff				as int
			Declare @decInitial2BranchCurrencyExchange	as decimal(19,6)

			-- Asiento con Diferencia de Cambio.!!!!   y al tipo de cambio de la cobranza!!!!
			Declare @decDebitInitial					as Decimal(19,5)
			Declare @decDebitExcDif						as Decimal(19,5)
			Declare @decCreditInitial					as Decimal(19,5)
			Declare @decCreditExcDif					as Decimal(19,5)


			Set @decDebitInitial		= 0
			Set @decDebitExcDif			= 0
			Set @decCreditInitial		= 0
			Set @decCreditExcDif		= 0

			Set @decTotalCursor			= 0
			Set @decTotal2Branch		= 0
			Set @decTotal2Company		= 0
			Set @curCredit				= 0
			Set @curDebit				= 0


			Declare curCashMovements
				CURSOR LOCAL  FAST_FORWARD For
					Select	curr_id,
							mm_total,
							mm_BranchCurrencyExchange
						From dbo.tbMoneyMovements			WITH (NOLOCK)
						Where	comp_id			= @comp_id
							and	ct_transaction	= @ct_transaction

			Open curCashMovements

			Fetch Next From curCashMovements
				Into	@curCurr_id,
						@curDebit,
						@decInitial2BranchCurrencyExchange

			While @@Fetch_Status = 0
				Begin

					Set @decTotalCursor  = (@curDebit - @curCredit)
					Set @decTotal2Branch = (@curDebit - @curCredit) * @decInitial2BranchCurrencyExchange  --  Importe convertido a la moneda de la sucursal.-

					Set @acc_count_id	       = null
					Set @acc_count_id_ExchDiff = null
					-- Buscar la Cuenta Contable que Corresponde a la Moneda
					SELECT	TOP 1
						   @Acc_Count_Id			= acc_count_id,
						   @acc_count_id_ExchDiff	= acc_count_id_ExDif
						From dbo.tbAccountManagementCurrencyRelations				WITH (NOLOCK)
						Where   comp_id    = @comp_id		AND
							    curr_id    = @curCurr_id	AND
						       (bra_id IS NULL OR bra_id = @bra_id)
						ORDER BY amcr_order
					--Select @Acc_Count_Id			= acc_count_id,
					--	   @acc_count_id_ExchDiff	= acc_count_id_ExDif
					--	From dbo.tbAccountManagementCurrencyRelations		WITH (NOLOCK)
					--	Where   comp_id    = @comp_id
					--		and curr_id    = @curCurr_id




					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + ' id:' + Cast(@curCurr_id as Varchar(9)) + '-04'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 52005
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Si la cuenta de diferencia de cambio no esta definida y ademas la moneda del asiento es diferente
					--		a la moneda de la imputacion, da error.-
					If IsNull(@acc_count_id_ExchDiff,-1)=-1 and ( @intCompanyCurrency <> @curCurr_id )
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-05'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20204
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts			WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202300
					Select @curr_desc	= curr_desc		From dbo.tbsysCurrency				WITH (NOLOCK)	Where curr_id = @curCurr_id
					Set	   @utexts_desc	= @ctDetail + ' ' + @utexts_desc + ' ' + @curr_desc

					-- Obtiene total en moneda de la compañia, partiendo del importe en la moneda de la sucursal.
					Set @decTotal2Company  = dbo.fnGetExchange(	@comp_id,
																@decTotal2Branch,
																@intBranchCurrency,
																@intCompanyCurrency,
																@intForcedExchangeCurrency ,
																@decForcedExchange,
																0)





					Set	@decDebitInitial	= @decTotalCursor						-- Debito de Moneda de Origen.-
					Set	@decDebitExcDif		= @decTotal2Company - @decTotalCursor	-- Debito de Diferencia de Cambio.-
					Set	@decCreditInitial	= 0
					Set @decCreditExcDif	= 0

					-- SELECT @decTotal2Branch,@decTotal2Company,@intBranchCurrency,@intCompanyCurrency,@intForcedExchangeCurrency ,@decForcedExchange,@decDebitExcDif

					Exec dbo.spAccountCreditDebitExchange	@decDebitInitial OutPut, @decCreditInitial OutPut
					Exec dbo.spAccountCreditDebitExchange   @decDebitExcDif	 OutPut, @decCreditExcDif  OutPut

					INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@decDebitInitial,
									@decCreditInitial,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


				If (@decCreditExcDif + @decDebitExcDif) <> 0
					Begin
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_ExchDiff,
									@cc_code,
									@decDebitExcDif,
									@decCreditExcDif,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)
					End

					Fetch Next From curCashMovements
						Into	@curCurr_id,
								@curDebit,
								@decInitial2BranchCurrencyExchange

				End

			Close		curCashMovements
			Deallocate	curCashMovements
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbCashMovement
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de dbo.tbBankingTransactions
			-- ------------------------------------------------------------------
			--Declare @curCurr_id		as int
			Declare @curTotal		as decimal(19,5)
			Declare @curNote		as varchar(100)
			Declare @ba_id			as int

			Set @decDebitInitial		= 0
			Set @decDebitExcDif			= 0
			Set @decCreditInitial		= 0
			Set @decCreditExcDif		= 0

			Set @decTotalCursor			= 0
			Set @decTotal2Branch		= 0
			Set @decTotal2Company		= 0

			Set @dacc_debit	 = 0
			Set @dacc_credit = 0

			Declare curBankingTransactions
				CURSOR LOCAL  FAST_FORWARD For
					Select	curr_id,
							bt_total,
							bt_note,
							ba_id,
							bt_BranchCurrencyExchange
						From dbo.tbBankingTransactions			WITH (NOLOCK)
						Where	comp_id			= @comp_id
							and	ct_transaction	= @ct_transaction

			Open		curBankingTransactions

			Fetch Next From curBankingTransactions
				Into	@curCurr_id,
						@curTotal,
						@curNote,
						@ba_id,
						@decInitial2BranchCurrencyExchange

			While @@Fetch_Status = 0
				Begin

					Set @decTotalCursor			= @curTotal
					Set @decTotal2Branch		= @curTotal * @decInitial2BranchCurrencyExchange
					Set @acc_count_id			= null
					Set @acc_count_id_ExchDiff	= null

					-- Buscar la Cuenta Contable que Corresponde a la Cuenta Bancaria
					Select @Acc_Count_Id		   = acc_count_id,
						   @acc_count_id_ExchDiff  = acc_count_id_ExDif
						From dbo.tbBankingAccounts				WITH (NOLOCK)
						Where   comp_id    = @comp_id
							and ba_id      = @ba_id


					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + ' id:' + Cast(@ba_id as Varchar(9)) + '-06'
								From dbo.tbsysUniqueTexts	WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20201
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End

					If IsNull(@acc_count_id_ExchDiff,-1)=-1 and ( @intCompanyCurrency <> @curCurr_id )
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-07'
								From dbo.tbsysUniqueTexts	WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20204
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts	WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202301
					Select @curr_desc	= curr_desc		From dbo.tbsysCurrency		WITH (NOLOCK)   Where curr_id = @curCurr_id
					Set	   @utexts_desc	= @ctDetail + ' ' + @utexts_desc + ' ' + @curNote


					-- Obtiene total en moneda de la compañia, partiendo del importe en la moneda de la sucursal.
					Set @decTotal2Company  = dbo.fnGetExchange(	@comp_id,
																@decTotal2Branch,
																@intBranchCurrency,
																@intCompanyCurrency,
																@intForcedExchangeCurrency,
																@decForcedExchange,
																0)




					Set	@decDebitInitial	= @decTotalCursor						-- Debito de Moneda de Origen.-
					Set	@decDebitExcDif		= @decTotal2Company - @decTotalCursor	-- Debito de Diferencia de Cambio.-
					Set	@decCreditInitial	= 0
					Set @decCreditExcDif	= 0

					Exec dbo.spAccountCreditDebitExchange	@decDebitInitial OutPut, @decCreditInitial OutPut
					Exec dbo.spAccountCreditDebitExchange   @decDebitExcDif	 OutPut, @decCreditExcDif  OutPut

					INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@decDebitInitial,
									@decCreditInitial,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


				If (@decCreditExcDif + @decDebitExcDif) <> 0
					Begin
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_ExchDiff,
									@cc_code,
									@decDebitExcDif,
									@decCreditExcDif,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)
					End

	/*
					If @dacc_debit < 0
						Begin
							Set @dacc_credit = @dacc_debit
							Set @dacc_debit  = 0
						End

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_id,
								@cc_code,
								@dacc_debit,
								@dacc_credit,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								@tax_desc,
								10)
	*/



					Fetch Next From curBankingTransactions
						Into	@curCurr_id,
								@curTotal,
								@curNote,
								@ba_id,
								@decInitial2BranchCurrencyExchange

				End

			Close		curBankingTransactions
			Deallocate	curBankingTransactions
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbBankingTransactions
			-- ------------------------------------------------------------------


			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de dbo.tbCreditCardMovements
			-- ------------------------------------------------------------------
			--Declare @curCurr_id		as int
			--Declare @curTotal		as decimal(19,5)
			--Declare @curNote		as varchar(100)
			Declare @cc_id			as int

			Set @decDebitInitial		= 0
			Set @decDebitExcDif			= 0
			Set @decCreditInitial		= 0
			Set @decCreditExcDif		= 0

			Set @decTotalCursor			= 0
			Set @decTotal2Branch		= 0
			Set @decTotal2Company		= 0

			Set @dacc_debit	 = 0
			Set @dacc_credit = 0

			Declare curCreditCardMovements
				CURSOR LOCAL  FAST_FORWARD For
					Select	curr_id,
							ccm_Total,
							ccm_cardNumber,
							cc_id,
							ccm_BranchCurrencyExchange
						From dbo.tbCreditCardMovements			WITH (NOLOCK)
						Where	comp_id			= @comp_id
							and	ct_transaction	= @ct_transaction

			Open		curCreditCardMovements

			Fetch Next From curCreditCardMovements
				Into	@curCurr_id,
						@curTotal,
						@curNote,
						@cc_id,
						@decInitial2BranchCurrencyExchange

			While @@Fetch_Status = 0
				Begin

					Set @decTotalCursor			= @curTotal
					Set @decTotal2Branch		= @curTotal * @decInitial2BranchCurrencyExchange
					Set @acc_count_id			= null
					Set @acc_count_id_ExchDiff	= null

					-- Buscar la Cuenta Contable que Corresponde a la T.Credito
					Select @Acc_Count_Id		   = acc_count_id,
						   @acc_count_id_ExchDiff  = acc_count_id_ExDif
						From dbo.tbCreditCard				WITH (NOLOCK)
						Where   comp_id    = @comp_id
							and cc_id      = @cc_id


					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-08'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20202
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End

					If IsNull(@acc_count_id_ExchDiff,-1)=-1 and ( @intCompanyCurrency <> @curCurr_id )
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-09'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20203
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts  	WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202302
					Select @curr_desc	= curr_desc		From dbo.tbsysCurrency	    WITH (NOLOCK)	Where curr_id = @curCurr_id
					Set	   @utexts_desc	= @ctDetail + ' ' + @utexts_desc + ' ' + @curNote


					-- Obtiene total en moneda de la compañia, partiendo del importe en la moneda de la sucursal.
					Set @decTotal2Company  = dbo.fnGetExchange(	@comp_id,
																@decTotal2Branch,
																@intBranchCurrency,
																@intCompanyCurrency,
																@intForcedExchangeCurrency,
																@decForcedExchange,
																0)


					Set	@decDebitInitial	= @decTotalCursor						-- Debito de Moneda de Origen.-
					Set	@decDebitExcDif		= @decTotal2Company - @decTotalCursor	-- Debito de Diferencia de Cambio.-
					Set	@decCreditInitial	= 0
					Set @decCreditExcDif	= 0

					Exec dbo.spAccountCreditDebitExchange	@decDebitInitial OutPut, @decCreditInitial OutPut
					Exec dbo.spAccountCreditDebitExchange   @decDebitExcDif	 OutPut, @decCreditExcDif  OutPut



					INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@decDebitInitial,
									@decCreditInitial,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


				If (@decCreditExcDif + @decDebitExcDif) <> 0
					Begin
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_ExchDiff,
									@cc_code,
									@decDebitExcDif,
									@decCreditExcDif,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)
					End

					Fetch Next From curCreditCardMovements
						Into	@curCurr_id,
								@curTotal,
								@curNote,
								@cc_id,
								@decInitial2BranchCurrencyExchange

				End

			Close		curCreditCardMovements
			Deallocate	curCreditCardMovements
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbCreditCardMovements
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de dbo.tbCheckPortfolio
			-- ------------------------------------------------------------------
			--Declare @curCurr_id		as int
			--Declare @curTotal		as decimal(19,5)
			--Declare @curNote		as varchar(100)
			Declare @chp_id			as int

			Set @decDebitInitial		= 0
			Set @decDebitExcDif			= 0
			Set @decCreditInitial		= 0
			Set @decCreditExcDif		= 0

			Set @decTotalCursor			= 0
			Set @decTotal2Branch		= 0
			Set @decTotal2Company		= 0

			Set @dacc_debit	 = 0
			Set @dacc_credit = 0

			Declare curCheckPortfolio
				CURSOR LOCAL  FAST_FORWARD For
					Select	curr_id,
							chp_total,
							chp_number,
							chp_id,
							chp_BranchCurrencyExchange
						From dbo.tbCheckPortfolio			WITH (NOLOCK)
						Where	comp_id			= @comp_id
							and	ct_transaction	= @ct_transaction

			Open		curCheckPortfolio

			Fetch Next From curCheckPortfolio
				Into	@curCurr_id,
						@curTotal,
						@curNote,
						@chp_id,
						@decInitial2BranchCurrencyExchange

			While @@Fetch_Status = 0
				Begin

					Set @decTotalCursor			= @curTotal
					Set @decTotal2Branch		= @curTotal * @decInitial2BranchCurrencyExchange
					Set @acc_count_id			= null
					Set @acc_count_id_ExchDiff	= null

					-- Buscar la Cuenta Contable que Corresponde a Valores a Depositar
					Set @acc_count_id	       = null
					Set @acc_count_id_ExchDiff = null
					-- Buscar la Cuenta Contable que Corresponde a la Moneda
					Select @Acc_Count_Id			= acc_count_id,
						   @acc_count_id_ExchDiff	= acc_count_id_ExDif
						From dbo.tbAccountManagementCurrencyRelations4CheckPortfolio		WITH (NOLOCK)
						Where   comp_id    = @comp_id
							and curr_id    = @curCurr_id


					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-10'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20221
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End

					If IsNull(@acc_count_id_ExchDiff,-1)=-1 and ( @intCompanyCurrency <> @curCurr_id )
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-11'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20222
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts		WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202303
					Select @curr_desc	= curr_desc		From dbo.tbsysCurrency			WITH (NOLOCK)		Where curr_id = @curCurr_id
					Set	   @utexts_desc	= @ctDetail + ' ' + @utexts_desc + ' ' + @curNote


					-- Obtiene total en moneda de la compañia, partiendo del importe en la moneda de la sucursal.
					Set @decTotal2Company  = dbo.fnGetExchange(	@comp_id,
																@decTotal2Branch,
																@intBranchCurrency,
																@intCompanyCurrency,
																@intForcedExchangeCurrency,
																@decForcedExchange,
																0)


					Set	@decDebitInitial	= @decTotalCursor						-- Debito de Moneda de Origen.-
					Set	@decDebitExcDif		= @decTotal2Company - @decTotalCursor	-- Debito de Diferencia de Cambio.-
					Set	@decCreditInitial	= 0
					Set @decCreditExcDif	= 0

					Exec dbo.spAccountCreditDebitExchange	@decDebitInitial OutPut, @decCreditInitial OutPut
					Exec dbo.spAccountCreditDebitExchange   @decDebitExcDif	 OutPut, @decCreditExcDif  OutPut



					INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@decDebitInitial,
									@decCreditInitial,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


				If (@decCreditExcDif + @decDebitExcDif) <> 0
					Begin
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_ExchDiff,
									@cc_code,
									@decDebitExcDif,
									@decCreditExcDif,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)
					End

					Fetch Next From curCheckPortfolio
						Into	@curCurr_id,
								@curTotal,
								@curNote,
								@chp_id,
								@decInitial2BranchCurrencyExchange

				End

			Close		curCheckPortfolio
			Deallocate	curCheckPortfolio
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbCheckPortfolio
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Ajustes de la Cobranza
			-- ------------------------------------------------------------------
			Set @acc_count_id	 = null
			-- Busca cuenta de Ajuste
			Select @acc_count_id = acc_count_id
				From dbo.tbAccountManagementRelations A		WITH (NOLOCK)
				Where   comp_id		= @comp_id
					and bra_id		= @bra_id
					and samr_id		= 50

			If IsNull(@acc_count_id,-1) = -1
				Begin
					Set	@ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc + '-12'
							From dbo.tbsysUniqueTexts		WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20223
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
						Return
				End

			Select	@dacc_Credit = ct_adjust
						From dbo.tbCommercialTransactions		WITH (NOLOCK)
						Where   comp_id			= @comp_id
							and ct_transaction	= @ct_transaction

			Set		@dacc_debit	= 0

			Set		@dacc_Credit = dbo.fnGetExchange(@comp_id,
													@dacc_Credit,
													@intBranchCurrency,
													@intCompanyCurrency,
													@intForcedExchangeCurrency,
													@decForcedExchange,
													0)

			Exec dbo.spAccountCreditDebitExchange	@dacc_debit OutPut, @dacc_Credit OutPut

			If @dacc_debit <> 0 or @dacc_Credit <> 0
				Begin
					Select	@utexts_desc = utexts_desc
						From	dbo.tbsysUniqueTexts
						Where	lang_id = @lang_id and  utexts_id = 202304

					Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_id,
								@cc_code,
								@dacc_debit,
								@dacc_credit,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								'',
								5
							   )
				End
			-- ------------------------------------------------------------------
			-- FIN Ajustes de la Cobranza
			-- ------------------------------------------------------------------


			Exec spAccountTransaction_CheckInsertBalance	@comp_id				,
															@bra_id					,
															@lang_id				,
															@user_id				,
															@hacc_transaction		,
															@cc_code				,
															@ct_transaction			,
															@ctDetail				,
															@ret_XErrorCode			= @ret_ErrorCode		OUTPUT 	,
															@ret_XErrorDescription	= @ret_ErrorDescription	OUTPUT

			SET @ret_ErrorDescription = @ret_ErrorDescription + '-13'

			SELECT @hacc_transaction
			-- ------------------------------------------------------------------
			-- Actualiza referencia en tbCommercialtransactions
			-- ------------------------------------------------------------------
			UPDATE tbCommercialTransactions
			SET
				hacc_transaction	= @hacc_transaction
			WHERE	comp_id			= @comp_id
				AND ct_transaction	= @ct_Transaction
			-- ------------------------------------------------------------------


    END TRY
    BEGIN CATCH
		IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT_Acc		-- MOS 06-2020
        --ROLLBACK TRANSACTION traPROTECT
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT


END

GO





-- =============================================
-- Author:		MOS
-- Fijarse que si se agrega un campo a la BD
-- hay que tocar todos los SP que se llaman
-- parecidos a este.-
