CREATE PROCEDURE [dbo].[spAccountTransaction_InsertdataFromManagement_Payments]
	(
		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as int,
		@ct_Transaction			as int,
		@user_id				as int,
		@ret_Identity			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
	)
AS


BEGIN
	SET NOCOUNT ON


-- ----------------------------------------------------------------------------------
-- Testing
-- ----------------------------------------------------------------------------------
/*
		DECLARE
			@comp_id				as int,
			@bra_id					as int,
			@lang_id				as int,
			@ct_Transaction			as int,
			@user_id				as int,
			@ret_Identity			as int			,
			@ret_ErrorCode			as int			,
			@ret_ErrorDescription	as varchar(200)
		SELECT
			@comp_id				=1,
			@bra_id					=1,
			@lang_id				=2,
			@ct_Transaction			=5139,
			@user_id				=1
*/
-- ----------------------------------------------------------------------------------

	Set @ret_Identity		   = 0
	Set @ret_ErrorCode		   = 0
	Set @ret_ErrorDescription  = ''



	-- ----------------------------------------------------------------------------------
	-- Verifica si hay Asientos Contables para ésta Sucursal y Asigna el Grupo Contable.-
	-- ----------------------------------------------------------------------------------
	DECLARE		@ag_id AS INT
	SELECT		@ag_id = ag_id
		FROM	tbBranch tb
		WHERE	tb.comp_id = @comp_id
			AND tb.bra_id  = @bra_id
	If @ag_id is NULL RETURN

	-- Agregar cuando busca un asiento existente el grupo contable
	-- ----------------------------------------------------------------------------------



    BEGIN TRY


		Declare @IsACredit      	as bit
		Declare @hacc_number		as int
		Declare @hacc_detail		as varchar(60)
		Declare @ap_id				as int
		Declare @Acc_Count_Id		as int
		Declare @dacc_debit			as decimal(19,6)
		Declare @dacc_credit		as decimal(19,6)
		Declare @utexts_desc		as varchar(60)
		Declare @tax_desc			as varchar(60)
		Declare @ctDetail  			as varchar(100)
		Declare @ct_Date			as DateTime
		Declare @intCompanyCurrency as Int
		Declare @intBranchCurrency	as Int
		Declare @cc_code			as int

		-- Variables para Tipo de Cambio Alternativo.-
		Declare @intForcedExchangeCurrency1		AS INT
		Declare @intForcedExchangeCurrency2		AS INT
		Declare @decForcedExchange				AS DECIMAL(19,6)

		Set @cc_Code			   = null

		-- Moneda de la Compañia
		Select @intCompanyCurrency = curr_id
			From dbo.tbCompany			WITH (NOLOCK)
			Where comp_id = @comp_id


		-- ----------------------------------------------------------------------------------
		-- Si el Grupo Contable establece una moneda, toma esa moneda para asientos.
		-- ----------------------------------------------------------------------------------
		SELECT @intCompanyCurrency =	CASE
											WHEN tag.ag_curr_id IS NULL THEN	@intCompanyCurrency
											ELSE								tag.ag_curr_id
										END
			FROM tbAccountantGroup AS tag	WITH (NOLOCK)
			WHERE	tag.comp_id = @comp_id AND
					tag.ag_id	= @ag_id
		-- ----------------------------------------------------------------------------------





		-- Moneda de la Sucursal
		Select @intBranchCurrency			= curr_id,
			   @intForcedExchangeCurrency1	= curr_id,
			   @cc_code						= cc_code
			From dbo.tbBranch				WITH (NOLOCK)
			Where	comp_id = @comp_id
				and	bra_id  = @bra_id


		--, Tipo de Cambio de Suc. a Compañia.- Fecha Impositiva de la Transaccion
		Select @ct_Date						= ct_taxDate,
			   @decForcedExchange			= ct_Branch2CompanyCurrencyExchange,
			   @intForcedExchangeCurrency2	= ct_CompanyCurrency
			From dbo.tbCommercialTransactions			WITH (NOLOCK)
			Where	comp_id			= @comp_id
				and	ct_transaction  = @ct_transaction



		-- --------------------------------------------------------------
		-- MOS  12-2012
		-- Si es la misma moneda intenta con la moneda forzada a guardar.
		-- --------------------------------------------------------------
		IF @intForcedExchangeCurrency1 = @intForcedExchangeCurrency2
			BEGIN
				Select
					@decForcedExchange			=  ct_curr_IdExchange,
					@intForcedExchangeCurrency1	=  curr_id4Exchange
					From dbo.tbCommercialTransactions			WITH (NOLOCK)
					Where	comp_id			= @comp_id
						and	ct_transaction  = @ct_transaction
			END
		-- --------------------------------------------------------------


		Set @ctDetail = dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)

		--				Set	@ret_ErrorCode = -1
		--				Select	@ret_ErrorDescription = @ctDetail
		--				return

		-- Recupera el Grupo de Asiento Contable
		Declare @hacc_group as int

		Select @hacc_group = C.hacc_group,
			   @IsACredit  = C.	sd_isCredit
			From  dbo.tbCommercialTransactions		A			WITH (NOLOCK)
			Inner join dbo.tbsysDocuments			C			WITH (NOLOCK)
				On	C.sd_id			 = A.sd_id
			Where	A.comp_id		 = @comp_id
				and A.ct_transaction = @ct_transaction
		-- --------------------------------------



		-- ------------------------------------------------------------------
		-- Verifica si hay un Asiento de la Compañia y Sucursal con ese Grupo
		-- ------------------------------------------------------------------
		Declare @hacc_transaction as int

		Select @hacc_transaction = hacc_transaction
			From dbo.tbAccountTransactionHead			WITH (NOLOCK)
			Where   comp_id			= @comp_id
				and bra_id			= @bra_id
				and hacc_group		= @hacc_group
				and hacc_date		= @ct_date
				and hacc_IsEditing	= 'False'
				AND ag_id			= @ag_id
				AND dbo.fnGetOnlyDate(hacc_cd)	= dbo.fnGetOnlyDate(GETDATE())
		-- ------------------------------------------------------------------

		--	-----------------------------------------------------------------
		--  Si no hay Cabecera dada de alta, la da de alta
		--	-----------------------------------------------------------------
		If IsNull(@hacc_transaction,0) = 0
			Begin

				-- Obtiene Proximo Numero de Asiento.-
				EXEC dbo.spCounters_getNextValue @comp_id, 0 , 3, @counter_value = @hacc_number OUTPUT

				-- -------------------------------
				-- Obtiene Descripcion del Asiento
				-- -------------------------------
					Select @hacc_detail = utexts_desc
						From dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where   lang_id = @lang_id
							and utexts_id = 223001
				-- -------------------------------

				-- -------------------------------
				-- Obtiene el Periodo
				-- Correspondiente a la fecha
				-- -------------------------------
				SELECT @ap_id = NULL
				Select @ap_id = ap.ap_id
					From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
					INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
						ON	tapbb.comp_id	=	ap.comp_id	AND
							tapbb.bra_id	=	@bra_id		AND
							tapbb.ap_id		=	ap.ap_id
					Where   ap.comp_id		=	@comp_id
						and ap.ap_firstdate <=	@ct_date
						and ap.ap_lastdate  >=	@ct_date
						and ap.ap_closed	=	'False'

				IF @ap_id IS NULL
					BEGIN
						Select @ap_id = ap_id
							From dbo.tbAccountantPeriod				WITH (NOLOCK)
							Where   comp_id = @comp_id
								and ap_firstdate <= @ct_date
								and ap_lastdate  >= @ct_date
								and ap_closed='False'
					END


				If @ap_id is Null
					Begin
						Set @ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc + '-01'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20206
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
						Return
					End

				-- -------------------------------


				-- Inserta Header Nuevo
				Insert Into dbo.tbAccountTransactionHead
					(	comp_id,
						bra_id,
						hacc_group,
						hacc_detail,
						hacc_date,
						hacc_number,
						hacc_orderPriority,
						hacc_cd,
						ap_id,
						hacc_blocked,
						hacc_closing,
						hacc_opening,
						hacc_IsEditing,
						hacc_IsEditingDateTime,
						ag_id
					)
					Values
					(	@comp_id,
						@bra_id,
						@hacc_group,
						@hacc_detail,
						@ct_date,
						@hacc_number,
						0,
						getdate(),
						@ap_id,
						'False',
						'False',
						'False',
						'False',
						GetDate(),
						@ag_id
					)

				Set @hacc_transaction = @@identity
			End
			--	-----------------------------------------------------------------


			-- ------------------------------------------------------------------
			-- Comienzo de Imputacion de Proveedores
			-- ------------------------------------------------------------------
			IF NOT EXISTS (	SELECT TOP 1  1 --*
								FROM tbCommercialTransactionsOtherPayments tctop
		               			WHERE	tctop.comp_id			= @comp_id
		  				--AND tctop.bra_id			= @bra_id
		               				AND tctop.ct_transaction	= @ct_Transaction)
				BEGIN

					Set @acc_count_id	 = null
					Select @acc_count_id = acc_count_id
						From dbo.tbSupplier			WITH (NOLOCK)
						Where   comp_id = @comp_id
							and supp_id = (Select Supp_id
											From dbo.tbCommercialTransactions		WITH (NOLOCK)
											Where   comp_id			= @comp_id
												and ct_transaction	= @ct_transaction )

					-- Otros Pagos, por favor no cambiar la ubicacion.!!
					If IsNull(@acc_count_id,0) = 0
						Begin
							Select @acc_count_id = acc_count_id
								From dbo.tbCommercialTransactionsOtherPayments tctop		WITH (NOLOCK)
								Where   tctop.comp_id		 = @comp_id
									--and tctop.bra_id		 = @bra_id
									and tctop.ct_transaction = @ct_Transaction
						END
					-- -------------------------------------------------


					If IsNull(@acc_count_id,0) = 0
						Begin
							Select @acc_count_id = acc_count_id
								From dbo.tbAccountManagementRelations A		WITH (NOLOCK)
								Where   comp_id		= @comp_id
									and bra_id		= @bra_id
									and samr_id		= 300
						End


					If IsNull(@acc_count_id,0) = 0
						Begin
							Set	@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-02'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20225
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					SET @dacc_debit		= 0
					SET @dacc_credit	= 0

					Select @dacc_debit = (ct_total - ct_adjust)
						From dbo.tbCommercialTransactions		WITH (NOLOCK)
						Where   comp_id = @comp_id
							and ct_transaction = @ct_transaction

					Set @dacc_debit		= dbo.fnGetExchange2(@comp_id,
															@dacc_debit,
															@intBranchCurrency,
															@intCompanyCurrency,
															@intForcedExchangeCurrency1 ,
															@intForcedExchangeCurrency2 ,
															@decForcedExchange,
															0)


					Select @utexts_desc		= utexts_desc
						From dbo.tbsysUniqueTexts		WITH (NOLOCK)
						Where	lang_id		= @lang_id
							and utexts_id	= 202031

					Set @utexts_desc		= @ctDetail + ' ' + @utexts_desc


					INSERT INTO dbo.tbAccountTransactionDetail
						   (comp_id,
							bra_id,
							hacc_transaction,
							acc_count_id,
							cc_code,
							dacc_debit,
							dacc_credit,
							user_id,
							dacc_cd,
							hacc_software,
							ct_transaction,
							acc_detail1,
							acc_detail2,
							dacc_order)
					 VALUES
						   (@comp_id,
							@bra_id,
							@hacc_transaction,
							@acc_count_id,
							@cc_code,
							@dacc_debit,
							@dacc_credit,
							@user_id,
							getdate(),
							'True',
							@ct_transaction,
							@utexts_desc,
							'',
							3
						   )
				END
					-- ----------------------------------------------------------
			ELSE	-- Otros Pagos.!!
					-- ----------------------------------------------------------
				BEGIN
					DECLARE @curOP_Desc			AS NVARCHAR(4000)
					DECLARE @curOP_puco_Id		AS INT
					DECLARE @curOP_acc_count_id AS INT
					DECLARE @curOP_Total		AS DECIMAL(19,4)
					DECLARE @curOP_cc_code		AS int
					DECLARE curOtherPaymentsImputations
						CURSOR LOCAL FAST_FORWARD FOR
							SELECT	tctopd.ctopd_desc,
									tctopd.ctopd_total,
									tctopd.acc_count_id,
									tctopd.puco_id,
									tctopd.cc_code
							  FROM tbCommercialTransactionsOtherPaymentsDetail tctopd		WITH (NOLOCK)
							WHERE	tctopd.comp_id			= @comp_id
								--AND tctopd.bra_id			= @bra_id
								AND tctopd.ct_transaction	= @ct_Transaction

							OPEN curOtherPaymentsImputations
							Fetch Next From curOtherPaymentsImputations
										Into	@curOP_Desc,
												@curOP_Total,
												@curOP_acc_count_id,
												@curOP_puco_Id,
												@curOP_cc_code
							While @@Fetch_Status = 0
								Begin

									-- Pone el Tipo de Cambio Correspondiente, de la moneda
									-- de la sucursal a la moneda de la compañia,
									-- ya que la contabilidad se hace en la moneda de la compañia.-
									SET @curOP_Desc = @ctDetail + ' ' + @curOP_Desc
									Set @dacc_credit= 0
									Set @dacc_debit	= dbo.fnGetExchange2(@comp_id,
																			@curOP_Total,
																			@intBranchCurrency,
																			@intCompanyCurrency,
																			@intForcedExchangeCurrency1 ,
																			@intForcedExchangeCurrency2 ,
																			@decForcedExchange,
																			0)

									INSERT INTO dbo.tbAccountTransactionDetail	WITH (ROWLOCK)
											   (comp_id,
												bra_id,
												hacc_transaction,
												acc_count_id,
												cc_code,
												dacc_debit,
												dacc_credit,
												user_id,
												dacc_cd,
												hacc_software,
												ct_transaction,
												acc_detail1,
												acc_detail2,
												dacc_order)
										 VALUES
											   (@comp_id,
												@bra_id,
												@hacc_transaction,
												@curOP_acc_count_id,
												isNull(@curOP_cc_code,@cc_code),
												@dacc_debit,
												@dacc_credit,
												@user_id,
												getdate(),
												'True',
												@ct_transaction,
												@curOP_Desc,
												'',
												10)

									Fetch Next From curOtherPaymentsImputations
												Into	@curOP_Desc,
														@curOP_Total,
														@curOP_acc_count_id,
														@curOP_puco_Id,
														@curOP_cc_code
								End

					CLOSE		curOtherPaymentsImputations
					DEALLOCATE	curOtherPaymentsImputations

				END
			-- ------------------------------------------------------------------
			-- FIN de Imputacion de Deudores por Ventas
			-- ------------------------------------------------------------------

			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de tbTaxMovement - Retenciones
			-- ------------------------------------------------------------------
			Declare @curTax_id		as int
			Declare @curTm_Total	as decimal(19,6)
			Declare @curCurr_id		as int

			Set @dacc_debit	 = 0
			Set @dacc_credit = 0

			Declare curTaxMovements
				CURSOR LOCAL FAST_FORWARD For
					Select	tax_id,
							tm_total,
							curr_id
						From dbo.tbTaxMovements			WITH (NOLOCK)
						Where	comp_id			= @comp_id
							and	ct_transaction	= @ct_transaction

			Open		curTaxMovements

			Fetch Next From curTaxMovements
				Into	@curTax_id,
						@curTm_Total,
						@curCurr_id

			While @@Fetch_Status = 0
				Begin

					Set @acc_count_id	 = null
					-- Buscar la Cuenta Contable que Corresponde
					Select @Acc_Count_Id = acc_count_id_forPurchase
						From dbo.tbAccountByTaxName			WITH (NOLOCK)
						Where   comp_id    = @comp_id
							and bra_id     = @bra_id
							and tax_id	   = @curTax_id


					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = 'ID(' + CONVERT(NVARCHAR(10),@curTax_id) + ') ' + utexts_desc  + '-03'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20205
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End

					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts		WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202010    -- IMPUESTOS
					Select @tax_desc	= tax_desc		From dbo.tbTaxName				WITH (NOLOCK)	Where comp_id = @comp_id and tax_id = @curTax_id
					Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc
					-- Pone el Tipo de Cambio Correspondiente, de la moneda
					-- de la sucursal a la moneda de la compañia,
					-- ya que la contabilidad se hace en la moneda de la compañia.-
					Set @dacc_debit		= 0

					Set @dacc_credit	= dbo.fnGetExchange2(@comp_id,
															@curTm_Total,
															@curCurr_id,
															@intCompanyCurrency,
															@intForcedExchangeCurrency1 ,
															@intForcedExchangeCurrency2 ,
															@decForcedExchange,
															0)

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_id,
								@cc_code,
								@dacc_debit,
								@dacc_credit,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								@tax_desc,
								10)

					Fetch Next From curTaxMovements
						Into	@curTax_id,
								@curTm_Total,
								@curCurr_id

				End



			Close		curTaxMovements
			Deallocate	curTaxMovements
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbTaxMovement
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de tbMoneyMovements
			-- ------------------------------------------------------------------
			Declare @curCredit 							as decimal(19,6)
			Declare @curDebit  							as decimal(19,6)
			Declare @decTotalCursor						as decimal(19,5)
			Declare @decTotal2Branch					as decimal(19,5)
			Declare @decTotal2Company					as decimal(19,5)
			--Declare @curCurr_id						as int
			Declare @curr_desc							as varchar(50)
			Declare @acc_count_id_ExchDiff				as int
			Declare @decInitial2BranchCurrencyExchange	as decimal(19,6)

			-- Asiento con Diferencia de Cambio.!!!!   y al tipo de cambio de la cobranza!!!!
			Declare @decDebitInitial					as Decimal(19,5)
			Declare @decDebitExcDif						as Decimal(19,5)
			Declare @decCreditInitial					as Decimal(19,5)
			Declare @decCreditExcDif					as Decimal(19,5)


			Set @decDebitInitial		= 0
			Set @decDebitExcDif			= 0
			Set @decCreditInitial		= 0
			Set @decCreditExcDif		= 0

			Set @decTotalCursor			= 0
			Set @decTotal2Branch		= 0
			Set @decTotal2Company		= 0
			Set @curCredit				= 0
			Set @curDebit				= 0


			Declare curCashMovements
				CURSOR LOCAL  FAST_FORWARD For
					Select	curr_id,
							mm_total,
							mm_BranchCurrencyExchange
						From dbo.tbMoneyMovements			WITH (NOLOCK)
						Where	comp_id			= @comp_id
							and	ct_transaction	= @ct_transaction

			Open curCashMovements

			Fetch Next From curCashMovements
				Into	@curCurr_id,
						@curDebit,
						@decInitial2BranchCurrencyExchange

			While @@Fetch_Status = 0
				Begin

					Set @decTotalCursor  = (@curDebit - @curCredit)
					Set @decTotal2Branch = (@curDebit - @curCredit) * @decInitial2BranchCurrencyExchange  --  Importe convertido a la moneda de la sucursal.-

					Set @acc_count_id	       = null
					Set @acc_count_id_ExchDiff = null
					-- Buscar la Cuenta Contable que Corresponde a la Moneda
					SELECT	TOP 1
						   @Acc_Count_Id			= acc_count_id,
						   @acc_count_id_ExchDiff	= acc_count_id_ExDif
						From dbo.tbAccountManagementCurrencyRelations		WITH (NOLOCK)
						Where   comp_id    = @comp_id		AND
							    curr_id    = @curCurr_id	AND
						       (bra_id IS NULL OR bra_id = @bra_id)
						ORDER BY amcr_order




					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + ' id:' + Cast(@curCurr_id as Varchar(9)) + '-04'
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 52005
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Si la cuenta de diferencia de cambio no esta definida y ademas la moneda del asiento es diferente
					--		a la moneda de la imputacion, da error.-
					If IsNull(@acc_count_id_ExchDiff,-1)=-1 and ( @intCompanyCurrency <> @curCurr_id )
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-05'
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20204
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts		WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202300
					Select @curr_desc	= curr_desc		From dbo.tbsysCurrency			WITH (NOLOCK)	Where curr_id = @curCurr_id
					Set	   @utexts_desc	= @ctDetail + ' ' + @utexts_desc + ' ' + @curr_desc

					-- Obtiene total en moneda de la compañia, partiendo del importe en la moneda de la sucursal.
					Set @decTotal2Company  = dbo.fnGetExchange2(	@comp_id,
																@decTotal2Branch,
																@intBranchCurrency,
																@intCompanyCurrency,
																@intForcedExchangeCurrency1 ,
																@intForcedExchangeCurrency2 ,
																@decForcedExchange,
																0)





					Set	@decDebitInitial	= @decTotalCursor						-- Debito de Moneda de Origen.-
					Set	@decDebitExcDif		= @decTotal2Company - @decTotalCursor	-- Debito de Diferencia de Cambio.-
					Set	@decCreditInitial	= 0
					Set @decCreditExcDif	= 0


					Exec dbo.spAccountCreditDebitExchange	@decDebitInitial OutPut, @decCreditInitial OutPut
					Exec dbo.spAccountCreditDebitExchange   @decDebitExcDif	 OutPut, @decCreditExcDif  OutPut

					INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@decCreditInitial,
									@decDebitInitial ,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


				If (@decCreditExcDif + @decDebitExcDif) <> 0
					Begin
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_ExchDiff,
									@cc_code,
									@decCreditExcDif ,
									@decDebitExcDif,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)
					END

					Fetch Next From curCashMovements
						Into	@curCurr_id,
								@curDebit,
								@decInitial2BranchCurrencyExchange

				End

