			Deallocate	curCashMovements
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbMoneyMovements
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de dbo.tbBankingTransactions
			-- ------------------------------------------------------------------
			--Declare @curCurr_id		as int
			Declare @curTotal		as decimal(19,5)
			Declare @curNote		as varchar(100)
			Declare @ba_id			as int

			Set @decDebitInitial		= 0
			Set @decDebitExcDif			= 0
			Set @decCreditInitial		= 0
			Set @decCreditExcDif		= 0

			Set @decTotalCursor			= 0
			Set @decTotal2Branch		= 0
			Set @decTotal2Company		= 0

			Set @dacc_debit	 = 0
			Set @dacc_credit = 0

			Declare curBankingTransactions
				CURSOR LOCAL  FAST_FORWARD For
					Select	curr_id,
							bt_total,
							bt_note,
							ba_id,
							bt_BranchCurrencyExchange
						From dbo.tbBankingTransactions			WITH (NOLOCK)
						Where	comp_id			= @comp_id
							and	ct_transaction	= @ct_transaction
							AND btt_id			= 1000008		-- Transferencia Bancaria tbsysBankingTransactionTypes

			Open		curBankingTransactions

			Fetch Next From curBankingTransactions
				Into	@curCurr_id,
						@curTotal,
						@curNote,
						@ba_id,
						@decInitial2BranchCurrencyExchange

			While @@Fetch_Status = 0
				Begin

					Set @decTotalCursor			= @curTotal
					Set @decTotal2Branch		= @curTotal * @decInitial2BranchCurrencyExchange
					Set @acc_count_id			= null
					Set @acc_count_id_ExchDiff	= null

					-- Buscar la Cuenta Contable que Corresponde a la Cuenta Bancaria
					Select @Acc_Count_Id		   = acc_count_id,
						   @acc_count_id_ExchDiff  = acc_count_id_ExDif
						From dbo.tbBankingAccounts			WITH (NOLOCK)
						Where   comp_id    = @comp_id
							and ba_id      = @ba_id


					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + ' id:' + Cast(@ba_id as Varchar(9)) + '-06'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20201
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End

					If IsNull(@acc_count_id_ExchDiff,-1)=-1 and ( @intCompanyCurrency <> @curCurr_id )
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-07'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20204
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts		WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202301
					Select @curr_desc	= curr_desc		From dbo.tbsysCurrency			WITH (NOLOCK)	Where curr_id = @curCurr_id
					Set	   @utexts_desc	= @ctDetail + ' ' + @utexts_desc + ' ' + @curNote


					-- Obtiene total en moneda de la compañia, partiendo del importe en la moneda de la sucursal.
					Set @decTotal2Company  = dbo.fnGetExchange2(@comp_id,
																@decTotal2Branch,
																@intBranchCurrency,
																@intCompanyCurrency,
																@intForcedExchangeCurrency1,
																@intForcedExchangeCurrency2 ,
																@decForcedExchange,
																0)




					Set	@decDebitInitial	= @decTotalCursor						-- Debito de Moneda de Origen.-
					Set	@decDebitExcDif		= @decTotal2Company - @decTotalCursor	-- Debito de Diferencia de Cambio.-
					Set	@decCreditInitial	= 0
					Set @decCreditExcDif	= 0

					Exec dbo.spAccountCreditDebitExchange	@decDebitInitial OutPut, @decCreditInitial OutPut
					Exec dbo.spAccountCreditDebitExchange   @decDebitExcDif	 OutPut, @decCreditExcDif  OutPut

					INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@decCreditInitial ,
									@decDebitInitial,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


				If (@decCreditExcDif + @decDebitExcDif) <> 0
					Begin
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_ExchDiff,
									@cc_code,
									@decCreditExcDif,
									@decDebitExcDif ,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)
					End


					Fetch Next From curBankingTransactions
						Into	@curCurr_id,
								@curTotal,
								@curNote,
								@ba_id,
								@decInitial2BranchCurrencyExchange

				End

			Close		curBankingTransactions
			Deallocate	curBankingTransactions
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbBankingTransactions
			-- ------------------------------------------------------------------


			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de dbo.tbCreditCardMovements
			-- ------------------------------------------------------------------
			Declare @cc_id			as int

			Set @decDebitInitial		= 0
			Set @decDebitExcDif			= 0
			Set @decCreditInitial		= 0
			Set @decCreditExcDif		= 0

			Set @decTotalCursor			= 0
			Set @decTotal2Branch		= 0
			Set @decTotal2Company		= 0

			Set @dacc_debit	 = 0
			Set @dacc_credit = 0

			Declare curCreditCardMovements
				CURSOR LOCAL  FAST_FORWARD For
					Select	curr_id,
							ccm_Total,
							ccm_cardNumber,
							cc_id,
							ccm_BranchCurrencyExchange
						From dbo.tbCreditCardMovements			WITH (NOLOCK)
						Where	comp_id			= @comp_id
							and	ct_transaction	= @ct_transaction

			Open		curCreditCardMovements

			Fetch Next From curCreditCardMovements
				Into	@curCurr_id,
						@curTotal,
						@curNote,
						@cc_id,
						@decInitial2BranchCurrencyExchange

			While @@Fetch_Status = 0
				Begin

					Set @decTotalCursor			= @curTotal
					Set @decTotal2Branch		= @curTotal * @decInitial2BranchCurrencyExchange
					Set @acc_count_id			= null
					Set @acc_count_id_ExchDiff	= null

					-- Buscar la Cuenta Contable que Corresponde a la T.Credito
					Select @Acc_Count_Id		   = acc_count_id,
						   @acc_count_id_ExchDiff  = acc_count_id_ExDif
						From dbo.tbCreditCard		WITH (NOLOCK)
						Where   comp_id    = @comp_id
							and cc_id      = @cc_id


					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-08'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20202
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End

					If IsNull(@acc_count_id_ExchDiff,-1)=-1 and ( @intCompanyCurrency <> @curCurr_id )
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-09'
								From dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20203
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts		WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202302
					Select @curr_desc	= curr_desc		From dbo.tbsysCurrency			WITH (NOLOCK)	Where curr_id = @curCurr_id
					Set	   @utexts_desc	= @ctDetail + ' ' + @utexts_desc + ' ' + @curNote


					-- Obtiene total en moneda de la compañia, partiendo del importe en la moneda de la sucursal.
					Set @decTotal2Company  = dbo.fnGetExchange2(@comp_id,
																@decTotal2Branch,
																@intBranchCurrency,
																@intCompanyCurrency,
																@intForcedExchangeCurrency1,
																@intForcedExchangeCurrency2,
																@decForcedExchange,
																0)


					Set	@decDebitInitial	= @decTotalCursor						-- Debito de Moneda de Origen.-
					Set	@decDebitExcDif		= @decTotal2Company - @decTotalCursor	-- Debito de Diferencia de Cambio.-
					Set	@decCreditInitial	= 0
					Set @decCreditExcDif	= 0

					Exec dbo.spAccountCreditDebitExchange	@decDebitInitial OutPut, @decCreditInitial OutPut
					Exec dbo.spAccountCreditDebitExchange   @decDebitExcDif	 OutPut, @decCreditExcDif  OutPut



					INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@decCreditInitial ,
									@decDebitInitial,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


				If (@decCreditExcDif + @decDebitExcDif) <> 0
					Begin
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_ExchDiff,
									@cc_code,
									@decCreditExcDif ,
									@decDebitExcDif,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)
					End

					Fetch Next From curCreditCardMovements
						Into	@curCurr_id,
								@curTotal,
								@curNote,
								@cc_id,
								@decInitial2BranchCurrencyExchange

				End

			Close		curCreditCardMovements
			Deallocate	curCreditCardMovements
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbCreditCardMovements
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de dbo.tbCheckPortfolio
			-- ------------------------------------------------------------------
			Declare @chp_id			as int

			Set @decDebitInitial		= 0
			Set @decDebitExcDif			= 0
			Set @decCreditInitial		= 0
			Set @decCreditExcDif		= 0

			Set @decTotalCursor			= 0
			Set @decTotal2Branch		= 0
			Set @decTotal2Company		= 0

			Set @dacc_debit	 = 0
			Set @dacc_credit = 0

			Declare curCheckPortfolio
				CURSOR LOCAL  FAST_FORWARD For
					Select	tcp1.curr_id,
							tcp1.chp_total,
							tcp1.chp_number,
							tcp1.chp_id,
							tcp1.chp_BranchCurrencyExchange
					FROM tbCheckPortfolioMovements tcpm			WITH (NOLOCK)
					INNER JOIN tbCheckPortfolio tcp1			WITH (NOLOCK)
						ON		tcp1.comp_id	= tcpm.comp_id
							AND tcp1.chp_id		= tcpm.chp_id
					INNER JOIN tbCommercialTransactions tct		WITH (NOLOCK)
						ON	tct.comp_id				= @comp_id
							AND tct.ct_transaction  = @ct_Transaction
					Where	tcpm.comp_id			= @comp_id
						and	tcpm.ct_transaction	    = @ct_transaction

			Open		curCheckPortfolio

			Fetch Next From curCheckPortfolio
				Into	@curCurr_id,
						@curTotal,
						@curNote,
						@chp_id,
						@decInitial2BranchCurrencyExchange



			While @@Fetch_Status = 0
				Begin


	--			SET @decInitial2BranchCurrencyExchange = dbo.fnGetExchange2(@comp_id,
	--																	   1,
	--																	   @curCurr_id,
	--																	   @intBranchCurrency,
	--																	   @intForcedExchangeCurrency1,
	--																	   @intForcedExchangeCurrency2,
	--																	   @decForcedExchange,
	--																	   0)

				SET @decTotal2Branch				  = dbo.fnGetExchange2(@comp_id,
																		   @curTotal,
																		   @curCurr_id ,
																		   @intBranchCurrency,
																		   @intForcedExchangeCurrency1,
																		   @intForcedExchangeCurrency2,
																		   @decForcedExchange,
																		   0)




					Set @decTotalCursor			= @curTotal
					--Set @decTotal2Branch		= @curTotal * @decInitial2BranchCurrencyExchange
					Set @acc_count_id			= null
					Set @acc_count_id_ExchDiff	= null

					-- Buscar la Cuenta Contable que Corresponde a Valores a Depositar
					Set @acc_count_id	       = null
					Set @acc_count_id_ExchDiff = null
					-- Buscar la Cuenta Contable que Corresponde a la Moneda
					Select @Acc_Count_Id			= acc_count_id,
						   @acc_count_id_ExchDiff	= acc_count_id_ExDif
						From dbo.tbAccountManagementCurrencyRelations4CheckPortfolio			WITH (NOLOCK)
						Where   comp_id    = @comp_id
							and curr_id    = @curCurr_id


					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-10'
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20221
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End

					If IsNull(@acc_count_id_ExchDiff,-1)=-1 and ( @intCompanyCurrency <> @curCurr_id )
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-11'
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20222
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts		WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202307
					Select @curr_desc	= curr_desc		From dbo.tbsysCurrency			WITH (NOLOCK)	Where curr_id = @curCurr_id
					Set	   @utexts_desc	= @ctDetail + ' ' + @utexts_desc + ' ' + @curNote


					-- Obtiene total en moneda de la compañia, partiendo del importe en la moneda de la sucursal.
					Set @decTotal2Company  = dbo.fnGetExchange2(@comp_id,
																@decTotal2Branch,
																@intBranchCurrency,
																@intCompanyCurrency,
																@intForcedExchangeCurrency1,
																@intForcedExchangeCurrency2,
																@decForcedExchange,
																0)


					Set	@decDebitInitial	= @decTotalCursor						-- Debito de Moneda de Origen.-
					Set	@decDebitExcDif		= @decTotal2Company - @decTotalCursor	-- Debito de Diferencia de Cambio.-
					Set	@decCreditInitial	= 0
					Set @decCreditExcDif	= 0

					Exec dbo.spAccountCreditDebitExchange	@decDebitInitial OutPut, @decCreditInitial OutPut
					Exec dbo.spAccountCreditDebitExchange   @decDebitExcDif	 OutPut, @decCreditExcDif  OutPut




					INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@decCreditInitial ,
									@decDebitInitial,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


				If (@decCreditExcDif + @decDebitExcDif) <> 0
					Begin
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_ExchDiff,
									@cc_code,
									@decCreditExcDif,
									@decDebitExcDif ,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)
					End

					Fetch Next From curCheckPortfolio
						Into	@curCurr_id,
								@curTotal,
								@curNote,
								@chp_id,
								@decInitial2BranchCurrencyExchange

				End

			Close		curCheckPortfolio
			Deallocate	curCheckPortfolio
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbCheckPortfolio
			-- ------------------------------------------------------------------




			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de tbEmmitedCheque
			-- Cheques Propios o Documentos Emitidos
			-- ------------------------------------------------------------------
			Set @decDebitInitial		= 0
			Set @decDebitExcDif			= 0
			Set @decCreditInitial		= 0
			Set @decCreditExcDif		= 0

			Set @decTotalCursor			= 0
			Set @decTotal2Branch		= 0
			Set @decTotal2Company		= 0

			Set @dacc_debit	 = 0
			Set @dacc_credit = 0

			Declare curEmmitedCheque
				CURSOR LOCAL  FAST_FORWARD For
					Select	tec.curr_id,
							tec.ec_Total,
							tec.ec_Number,
							tec.ec_id,
							tec.ba_id,
							tec.ec_exchangeToBranchCurrency
					FROM tbEmmitedChecks tec		WITH (NOLOCK)
					Where	tec.comp_id			= @comp_id
						and	tec.ct_transaction	= @ct_transaction

			Open		curEmmitedCheque

			Fetch Next From curEmmitedCheque
				Into	@curCurr_id,
						@curTotal,
						@curNote,
						@chp_id,
						@ba_id,
						@decInitial2BranchCurrencyExchange


			While @@Fetch_Status = 0
				Begin

					Set @decTotalCursor			= @curTotal
					Set @decTotal2Branch		= @curTotal * @decInitial2BranchCurrencyExchange
					Set @acc_count_id			= null
					Set @acc_count_id_ExchDiff	= null

					-- Buscar la Cuenta Contable que Corresponde a Valores a Depositar
					Set @acc_count_id	       = null
					Set @acc_count_id_ExchDiff = null
					-- Buscar la Cuenta Contable que Corresponde a la Moneda




					IF @ba_id IS NULL
						-- Si es un Documento Emitido.
						BEGIN
							Select @Acc_Count_Id			= tamcred.acc_count_id,
								   @acc_count_id_ExchDiff	= tamcred.acc_count_id_ExDif
								From dbo.tbAccountManagementCurrencyRelations4EmmitedDocuments tamcred			WITH (NOLOCK)
								Where   tamcred.comp_id    = @comp_id
									and tamcred.curr_id    = @curCurr_id
									--SELECT @Acc_Count_Id,@acc_count_id_ExchDiff,@decCreditInitial,@decDebitInitial
						END
					ELSE
						-- Si es un Cheque Propio Emitido
						BEGIN

							Select @Acc_Count_Id			= acc_count_id_notPayed, --acc_count_id,
								   @acc_count_id_ExchDiff	= acc_count_id_ExDif
								From dbo.tbBankingAccounts			WITH (NOLOCK)
								Where   comp_id    = @comp_id
									and ba_id      = @ba_id
						END




					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-10'
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20221
								Close		curEmmitedCheque
								Deallocate	curEmmitedCheque
								--SELECT @Acc_Count_Id,@acc_count_id_ExchDiff,@decCreditInitial,@decDebitInitial
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End

					If IsNull(@acc_count_id_ExchDiff,-1)=-1 and ( @intCompanyCurrency <> @curCurr_id )
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc + '-11'
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20222
							Close		curEmmitedCheque
							Deallocate	curEmmitedCheque
							--SELECT @Acc_Count_Id,@acc_count_id_ExchDiff,@decCreditInitial,@decDebitInitial
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End


					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts		WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202307
					Select @curr_desc	= curr_desc		From dbo.tbsysCurrency			WITH (NOLOCK)	Where curr_id = @curCurr_id
					Set	   @utexts_desc	= @ctDetail + ' ' + @utexts_desc + ' ' + @curNote


					-- Obtiene total en moneda de la compañia, partiendo del importe en la moneda de la sucursal.
					Set @decTotal2Company  = dbo.fnGetExchange2(@comp_id,
																@decTotal2Branch,
																@intBranchCurrency,
																@intCompanyCurrency,
																@intForcedExchangeCurrency1,
																@intForcedExchangeCurrency2,
																@decForcedExchange,
																0)


					Set	@decDebitInitial	= @decTotalCursor						-- Debito de Moneda de Origen.-
					Set	@decDebitExcDif		= @decTotal2Company - @decTotalCursor	-- Debito de Diferencia de Cambio.-
					Set	@decCreditInitial	= 0
					Set @decCreditExcDif	= 0

					Exec dbo.spAccountCreditDebitExchange	@decDebitInitial OutPut, @decCreditInitial OutPut
					Exec dbo.spAccountCreditDebitExchange   @decDebitExcDif	 OutPut, @decCreditExcDif  OutPut



					INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@decCreditInitial ,
									@decDebitInitial,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)


				If (@decCreditExcDif + @decDebitExcDif) <> 0
					Begin
						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id_ExchDiff,
									@cc_code,
									@decCreditExcDif,
									@decDebitExcDif ,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)
					End


					Fetch Next From curEmmitedCheque
						Into	@curCurr_id,
								@curTotal,
								@curNote,
								@chp_id,
								@ba_id,
								@decInitial2BranchCurrencyExchange

				End

			Close		curEmmitedCheque
			Deallocate	curEmmitedCheque
			-- ------------------------------------------------------------------
			-- Fin Asiento de tbEmmitedCheque
			-- ------------------------------------------------------------------


			-- ------------------------------------------------------------------
			-- Descuento del Pago
			-- ------------------------------------------------------------------
			DECLARE @intTaxId4Discount	AS INT
			DECLARE @decTax4Discount	AS DECIMAL(19,4)
			DECLARE @decDiscount		AS DECIMAL(19,4)

			-- Busca el Iva del descuento x o.Pago
			SELECT @intTaxId4Discount = tctpa.tax_id4Discount
				FROM tbCommercialTransactionsPaymentsAdditionals tctpa
				WHERE	tctpa.comp_id = @comp_id
					AND tctpa.ct_transaction = @ct_Transaction

			-- Calcula el descuento y el IVA del Descuento.
			Select	@decDiscount     =						tct.ct_discount / ( 1 + (ttn.tax_percentage / 100)),
					@decTax4Discount = tct.ct_discount -   (tct.ct_discount / ( 1 + (ttn.tax_percentage / 100)))
						From dbo.tbCommercialTransactions tct			WITH (NOLOCK)
						INNER JOIN tbTaxName ttn						WITH (NOLOCK)
							ON		ttn.comp_id = tct.comp_id
								AND ttn.tax_id	= @intTaxId4Discount
						Where   tct.comp_id			= @comp_id
							and tct.ct_transaction	= @ct_transaction




			IF IsNull(@decDiscount,0) <> 0
				BEGIN



					Set @acc_count_id	 = null
					-- Busca cuenta del Descuento
					Select @acc_count_id = acc_count_id
						From dbo.tbAccountManagementRelations A		WITH (NOLOCK)
						Where   comp_id		= @comp_id
							and bra_id		= @bra_id
							and samr_id		= 451

					If IsNull(@acc_count_id,-1) = -1
						Begin
							Set	@ret_ErrorCode = -1
								Select	@ret_ErrorDescription = utexts_desc + '-12*'
									From dbo.tbsysUniqueTexts		WITH (NOLOCK)
									Where lang_id = @lang_id and  utexts_id = 20235
								--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
								Return
						End


					SET @dacc_debit				= 0
					Set	@dacc_Credit			= @decDiscount
					Set	@dacc_Credit = dbo.fnGetExchange2(	@comp_id,
															@dacc_Credit,
															@intBranchCurrency,
															@intCompanyCurrency,
															@intForcedExchangeCurrency1,
															@intForcedExchangeCurrency2,
															@decForcedExchange,
															0)

					Exec dbo.spAccountCreditDebitExchange @dacc_Credit OutPut, @dacc_debit OUTPUT


					If @dacc_debit <> 0 or @dacc_Credit <> 0
						Begin



							Select	@utexts_desc = utexts_desc
								From	dbo.tbsysUniqueTexts		WITH (NOLOCK)
								Where	lang_id = @lang_id and  utexts_id = 202306

							Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc

							INSERT INTO dbo.tbAccountTransactionDetail
									   (comp_id,
										bra_id,
										hacc_transaction,
										acc_count_id,
										cc_code,
										dacc_debit,
										dacc_credit,
										user_id,
										dacc_cd,
										hacc_software,
										ct_transaction,
										acc_detail1,
										acc_detail2,
										dacc_order)
								 VALUES
									   (@comp_id,
										@bra_id,
										@hacc_transaction,
										@acc_count_id,
										@cc_code,
										@dacc_debit,
										@dacc_Credit,
										@user_id,
										getdate(),
										'True',
										@ct_transaction,
										@utexts_desc,
										'',
										5
									   )

							-- Busca cuenta del IVA del Descuento
							Select @acc_count_id = tabtn.acc_count_id_forPurchase
								FROM tbAccountByTaxName tabtn	WITH (NOLOCK)
									Where   tabtn.comp_id		= @comp_id
										AND tabtn.bra_id        = @bra_id
										and	tabtn.tax_id        = @intTaxId4Discount

							SET @dacc_debit = 0
							SET @dacc_Credit= @decTax4Discount
							Set	@dacc_Credit = dbo.fnGetExchange2(	@comp_id,
																	@dacc_Credit,
																	@intBranchCurrency,
																	@intCompanyCurrency,
																	@intForcedExchangeCurrency1,
																	@intForcedExchangeCurrency2,
																	@decForcedExchange,
																	0)

							Exec dbo.spAccountCreditDebitExchange @dacc_Credit OutPut, @dacc_debit OUTPUT

							INSERT INTO dbo.tbAccountTransactionDetail
									   (comp_id,
										bra_id,
										hacc_transaction,
										acc_count_id,
										cc_code,
										dacc_debit,
										dacc_credit,
										user_id,
										dacc_cd,
										hacc_software,
										ct_transaction,
										acc_detail1,
										acc_detail2,
										dacc_order)
								 VALUES
									   (@comp_id,
										@bra_id,
										@hacc_transaction,
										@acc_count_id,
										@cc_code,
										@dacc_debit,
										@dacc_Credit,
										@user_id,
										getdate(),
										'True',
										@ct_transaction,
										@utexts_desc,
										'',
										5
									   )


						END
					END
			-- ------------------------------------------------------------------
			-- FIN Descuento
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Ajustes de la Pago
			-- ------------------------------------------------------------------
			Set @acc_count_id	 = null
			-- Busca cuenta de Ajuste
			Select @acc_count_id = acc_count_id
				From dbo.tbAccountManagementRelations A	WITH (NOLOCK)
				Where   comp_id		= @comp_id
					and bra_id		= @bra_id
					and samr_id		= 450

			If IsNull(@acc_count_id,-1) = -1
				Begin
					Set	@ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc + '-12'
							From dbo.tbsysUniqueTexts	WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20230
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
						Return
				End

			Select	@dacc_debit = ct_adjust
						From dbo.tbCommercialTransactions	WITH (NOLOCK)
						Where   comp_id			= @comp_id
							and ct_transaction	= @ct_transaction

			Set		@dacc_Credit			= 0

			Set		@dacc_debit = dbo.fnGetExchange2(@comp_id,
													@dacc_debit,
													@intBranchCurrency,
													@intCompanyCurrency,
													@intForcedExchangeCurrency1,
													@intForcedExchangeCurrency2,
													@decForcedExchange,
													0)

			Exec dbo.spAccountCreditDebitExchange	@dacc_debit OutPut, @dacc_Credit OutPut

			If @dacc_debit <> 0 or @dacc_Credit <> 0
				Begin
					Select	@utexts_desc = utexts_desc
						From	dbo.tbsysUniqueTexts	WITH (NOLOCK)
						Where	lang_id = @lang_id and  utexts_id = 202305

					Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_id,
								@cc_code,
								@dacc_debit,
								@dacc_Credit,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								'',
								5
							   )
				End
			-- ------------------------------------------------------------------
			-- FIN Ajustes del Pago
			-- ------------------------------------------------------------------



			Exec spAccountTransaction_CheckInsertBalance	@comp_id				,
															@bra_id					,
															@lang_id				,
															@user_id				,
															@hacc_transaction		,
															@cc_code				,
															@ct_transaction			,
															@ctDetail				,
															@ret_XErrorCode			= @ret_ErrorCode		OUTPUT 	,
															@ret_XErrorDescription	= @ret_ErrorDescription	OUTPUT
			SET @ret_ErrorDescription = @ret_ErrorDescription + '<br/> <br/> -13. ATENCION: Tal vez deba Verificar Tipo de cambio a almacenar en Sucursales.!'


			SELECT @hacc_transaction

			-- ------------------------------------------------------------------
			-- Actualiza referencia en tbCommercialtransactions
			-- ------------------------------------------------------------------
			UPDATE tbCommercialTransactions
			SET
				hacc_transaction	= @hacc_transaction
			WHERE	comp_id			= @comp_id
				AND ct_transaction	= @ct_Transaction
			-- ------------------------------------------------------------------

    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
   -- --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT



END

GO






-- =============================================
-- Author:		MOS
-- Fijarse que si se agrega un campo a la BD
-- hay que tocar todos los SP que se llaman
-- parecidos a este.-
-- Create date: 05-2009
-- =============================================

-- Log
-- MOS 04-2024: puse optimizaciones x q estaba tardando mucho segun un log
--SELECT t.text, qp.query_plan, qs.execution_count, qs.total_elapsed_time
--FROM sys.dm_exec_query_stats AS qs
--CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) AS t
--CROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) AS qp
--WHERE qs.execution_count > 1
--ORDER BY qs.total_elapsed_time DESC;

CREATE PROCEDURE [dbo].[spAccountTransaction_InsertdataFromManagement_Purchases]
	(
		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as int,
		@tis_guid				as uniqueidentifier,
		@ct_Transaction			as int,
		@user_id				as int,
		@ret_Identity			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
	)
AS



BEGIN




	-- -----------------------------------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------------------------------
/*
	--	DELETE FROM tbAccountTransactionDetail
	--	DELETE FROM tbAccountTransactionHead

	Declare @comp_id				as int
	Declare @bra_id					as int
	Declare @lang_id				as int
	Declare @tis_guid				as uniqueidentifier
	Declare @ct_Transaction			as int
	Declare @user_id				as int
	DECLARE @ret_Identity		    AS INT
	declare @ret_ErrorCode		    AS INT
	declare @ret_ErrorDescription   AS VARCHAR(200)

	SET @comp_id = 1
	SET @bra_id = 1
	SET @lang_id = 2
	SET @ct_Transaction = 8633
	SET @user_id = 1
*/
	-- -----------------------------------------------------------------------------------------------------



	BEGIN

		SET NOCOUNT ON

		DECLARE @cc_Code			AS INT
		Declare @IsACredit      	as bit
		Declare @hacc_number		as int
		Declare @hacc_detail		as varchar(60)
		Declare @ap_id				as int
		Declare @Acc_Count_Id		as int
		Declare @dacc_debit			as decimal(19,6)
		Declare @dacc_credit		as decimal(19,6)
		Declare @utexts_desc		as varchar(60)
		Declare @tax_desc			as varchar(60)
		Declare @ctDetail  			as varchar(100)
		Declare @ct_Date			as DateTime
		Declare @ct_CompanyCurrency as Int
		Declare @currency_id		as Int
		DECLARE @supp_id			AS INT
		DECLARE @ba_id				AS INT

		-- Variables para Tipo de Cambio Alternativo.-------
		Declare @intForcedExchangeCurrency1 AS INT
		Declare @intForcedExchangeCurrency2 AS INT
		DECLARE @intBranchCurrency AS INT
		Declare @decForcedExchange			AS DECIMAL(35,10)
		SELECT @intForcedExchangeCurrency1 = tct.curr_id4Exchange,
			   @intForcedExchangeCurrency2 = tct.curr_id_transaction,
			   @decForcedExchange		   = tct.ct_curr_IdExchange,
			   @supp_id					   = tct.supp_id,		-- MOS 04-2024
			   @ba_id					   = tct.ba_id			--  MOS 04-2024
			FROM tbCommercialTransactions tct	WITH (NOLOCK)
			WHERE	tct.comp_id			= @comp_id			AND
					tct.ct_transaction	= @ct_Transaction
		-- -------------------------------------------------



		Set @cc_Code			   = null
		Set @ret_Identity		   = 0
		Set @ret_ErrorCode		   = 0
		Set @ret_ErrorDescription  = ''

		-- ----------------------------------------------------------------------------------
		-- Verifica si hay Asientos Contables para ésta Sucursal y Asigna el Grupo Contable.-
		-- ----------------------------------------------------------------------------------
		DECLARE		@ag_id AS INT
		SELECT		@ag_id = ag_id
			FROM	tbBranch tb				WITH (NOLOCK)
			WHERE	tb.comp_id = @comp_id
				AND tb.bra_id  = @bra_id
		If @ag_id is NULL RETURN


		-- Moneda de la Compañia
		Select @ct_CompanyCurrency = curr_id
			From dbo.tbCompany						WITH (NOLOCK)
			Where comp_id = @comp_id


		-- ----------------------------------------------------------------------------------
		-- Si el Grupo Contable establece una moneda, toma esa moneda para asientos.
		-- ----------------------------------------------------------------------------------
		SELECT @ct_CompanyCurrency =	CASE
											WHEN tag.ag_curr_id IS NULL THEN	@ct_CompanyCurrency
											ELSE								tag.ag_curr_id
										END
			FROM tbAccountantGroup AS tag	WITH (NOLOCK)
			WHERE	tag.comp_id = @comp_id AND
					tag.ag_id	= @ag_id
		-- ----------------------------------------------------------------------------------






		--SAVE TRANSACTION traPROTECT
		--BEGIN TRANSACTION
		BEGIN TRY




			-- Agregar cuando busca un asiento existente el grupo contable
			-- ----------------------------------------------------------------------------------

			-- Fecha Impositiva de la Transaccion
			--Select @ct_Date                   = ct_taxDate,
			--	   @intBranchCurrency		  = curr_id_transaction
			--	From dbo.tbCommercialTransactions		WITH (NOLOCK)
			--	Where	comp_id			= @comp_id
			--		and	ct_transaction  = @ct_transaction

			-- Tipo de Documento a Contabilizar.-
			DECLARE @sd_id AS INT
			--SELECT @sd_id					= tct.sd_id
			--	FROM tbCommercialTransactions tct		WITH (NOLOCK)
			--	WHERE	tct.comp_id			= @comp_id
			--		AND tct.ct_transaction	= @ct_Transaction

			-- MOS 04-2024: Puse toda esta MIERDA junta asi no llamaba 3 veces al PEDO
			-- Fecha Impositiva de la Transaccion
			Select @sd_id						= tct.sd_id,
  				   @ct_Date						= tct.ct_taxDate,
				   @intBranchCurrency			= tct.curr_id_transaction
				From dbo.tbCommercialTransactions	tct	WITH (NOLOCK)
				Where	comp_id			= @comp_id
					and	ct_transaction  = @ct_transaction


			DECLARE @bitIs4Banking AS BIT
			SET @bitIs4Banking = case
									when @sd_id = 140 OR @sd_id = 141 OR @sd_id = 142 OR @sd_id = 143 THEN 'TRUE'
									ELSE 'FALSE'
								  end







			-- Moneda de la Sucursal
			Select @currency_id = curr_id,
				@cc_Code        = cc_code
				From dbo.tbBranch						WITH (NOLOCK)
				Where	comp_id = @comp_id
					and	bra_id  = @bra_id


			Set @ctDetail = dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)

			--				Set	@ret_ErrorCode = -1
			--				Select	@ret_ErrorDescription = @ctDetail
			--				return

			-- Recupera el Grupo de Asiento Contable
			Declare @hacc_group as int

			Select @hacc_group = C.hacc_group,
				   @IsACredit  = C.	sd_isCredit
				From  dbo.tbCommercialTransactions		A			WITH (NOLOCK)
				Inner join dbo.tbsysDocuments			C			WITH (NOLOCK)
					On	C.sd_id			 = A.sd_id
				Where	A.comp_id		 = @comp_id
					and A.ct_transaction = @ct_transaction
			-- --------------------------------------

			-- ------------------------------------------------------------------
			-- Verifica si hay un Asiento de la Compañia y Sucursal con ese Grupo
			-- ------------------------------------------------------------------
			Declare @hacc_transaction as int

			Select @hacc_transaction = hacc_transaction
				From dbo.tbAccountTransactionHead					WITH (NOLOCK)
				Where   comp_id			= @comp_id
					and bra_id			= @bra_id
					and hacc_group		= @hacc_group
					and hacc_date		= @ct_date
					and hacc_IsEditing	= 'False'
					AND ag_id			= @ag_id
					AND dbo.fnGetOnlyDate(hacc_cd)	= dbo.fnGetOnlyDate(GETDATE())
			-- ------------------------------------------------------------------

			--	-----------------------------------------------------------------
			--  Si no hay Cabecera dada de alta, la da de alta
			--	-----------------------------------------------------------------
			If IsNull(@hacc_transaction,0) = 0
				Begin

					-- Obtiene Proximo Numero de Asiento.-
					EXEC dbo.spCounters_getNextValue @comp_id, 0, 3 , @counter_value = @hacc_number OUTPUT

					-- -------------------------------
					-- Obtiene Descripcion del Asiento
					-- -------------------------------
					IF @sd_id = 140 OR @sd_id = 141	OR @sd_id = 143			-- Bancos
							Select @hacc_detail = utexts_desc
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where   lang_id = @lang_id
									and utexts_id = 213001
					ELSE IF @sd_id = 142						-- T. Credito
							Select @hacc_detail = utexts_desc
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where   lang_id = @lang_id
									and utexts_id = 214001
					ELSE IF @sd_id = 130						-- Despacho de Importacion.
							Select @hacc_detail = utexts_desc
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where   lang_id = @lang_id
									and utexts_id = 215001
					ELSE										-- Comprobantes
							Select @hacc_detail = utexts_desc
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where   lang_id = @lang_id
									and utexts_id = 212001
					-- -------------------------------


					-- -------------------------------
					-- Obtiene el Periodo
					-- Correspondiente a la fecha
					-- -------------------------------
					SELECT @ap_id = NULL
					Select @ap_id = ap.ap_id
						From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
						INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
							ON	tapbb.comp_id	=	ap.comp_id	AND
								tapbb.bra_id	=	@bra_id		AND
								tapbb.ap_id		=	ap.ap_id
						Where   ap.comp_id		=	@comp_id
							and ap.ap_firstdate <=	@ct_date
							and ap.ap_lastdate  >=	@ct_date
							and ap.ap_closed	=	'False'

					IF @ap_id IS NULL
						BEGIN
							Select @ap_id = ap_id
								From dbo.tbAccountantPeriod			WITH (NOLOCK)
								Where   comp_id = @comp_id
									and ap_firstdate <= @ct_date
									and ap_lastdate  >= @ct_date
									and ap_closed='False'
						END



					If @ap_id is Null
						Begin
							Set @ret_ErrorCode = -1
							Select	@ret_ErrorDescription = utexts_desc
									From dbo.tbsysUniqueTexts			WITH (NOLOCK)
									Where lang_id = @lang_id and  utexts_id = 20206
						--	IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
							Return
						End
					-- -------------------------------


					-- Inserta Header Nuevo
					Insert Into dbo.tbAccountTransactionHead
						(	comp_id,
							bra_id,
							hacc_group,
							hacc_detail,
							hacc_date,
							hacc_number,
							hacc_orderPriority,
							hacc_cd,
							ap_id,
							hacc_blocked,
							hacc_closing,
							hacc_opening,
							hacc_IsEditing,
							hacc_IsEditingDateTime,
							ag_id
						)
						Values
						(	@comp_id,
							@bra_id,
							@hacc_group,
							@hacc_detail,
							@ct_date,
							@hacc_number,
							0,
							getdate(),
							@ap_id,
							'False',
							'False',
							'False',
							'False',
							GetDate(),
							@ag_id
						)

					Set @hacc_transaction = @@identity
				End
				--	-----------------------------------------------------------------



				-- ------------------------------------------------------------------
				-- Comienza Asiento de parte de Impuestos
				-- ------------------------------------------------------------------
				Declare @curTax_id		as int
				Declare @curTm_amount	as decimal(19,6)
				Declare @curCurr_id		as INT
				DECLARE @curTaxClass	AS INT

				Declare curTmpTax
					CURSOR LOCAL  FAST_FORWARD For
						Select	ttm.tax_id,
								ttm.tm_total,
								ttm.curr_id
							FROM tbTaxMovements			ttm			WITH (NOLOCK)
							Where	ttm.comp_id			= @comp_id
								AND ttm.ct_transaction	= @ct_Transaction

				Open		curTmpTax

				Fetch Next From curTmpTax
					Into	@curTax_id,
							@curTm_amount,
							@curCurr_id

				While @@Fetch_Status = 0
					Begin
						Set @acc_count_id	 = null
						-- Buscar la Cuenta Contable que Corresponde
						SELECT @curTaxClass = ttn.tax_class
							FROM tbTaxName ttn					WITH (NOLOCK)
							WHERE	ttn.comp_id = @comp_id AND
									ttn.tax_id	= @curTax_id

						IF @sd_id = 142 AND (@curTaxClass >= 200 AND @curTaxClass <= 299)	-- MOS Si es Liq de T.Credito y el impuesto es una retencion, lo debe sacar de la definicion de VENTAS ya que es una retencion en el lugar de una Percepcion.!
							BEGIN
								Select @Acc_Count_Id = acc_count_id_forSale
									From dbo.tbAccountByTaxName	WITH (NOLOCK)
									Where   comp_id    = @comp_id
										and bra_id     = @bra_id
										and @curTax_id = tax_id
							END
						ELSE
							BEGIN
								Select @Acc_Count_Id = acc_count_id_forPurchase
									From dbo.tbAccountByTaxName	WITH (NOLOCK)
									Where   comp_id    = @comp_id
										and bra_id     = @bra_id
										and @curTax_id = tax_id
							END


						-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
						-- la cuenta contable que falta definir.-
						If IsNull(@Acc_Count_Id,0)=0
							Begin
								Set		@ret_ErrorCode = -1
								Select	@ret_ErrorDescription = 'ID(' + CONVERT(NVARCHAR(10),@curTax_id) + ') ' + utexts_desc
									From dbo.tbsysUniqueTexts	WITH (NOLOCK)
									Where lang_id = @lang_id and  utexts_id = 20205
							--	IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
								Return
							End

						-- Recupera Leyendas de la Imputacion
						Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts	WITH (NOLOCK)	Where lang_id = @lang_id and utexts_id = 202010
						Select @tax_desc	= tax_desc		From dbo.tbTaxName			WITH (NOLOCK)	Where comp_id = @comp_id and tax_id = @curTax_id
						Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc
						-- Pone el Tipo de Cambio Correspondiente, de la moneda
						-- de la sucursal a la moneda de la compañia,
						-- ya que la
						Set @dacc_credit= 0

						Set @dacc_debit	= dbo.fnGetExchange2(	@comp_id,
																@curTm_amount,
																@curCurr_id,
																@ct_CompanyCurrency,
																@intForcedExchangeCurrency1 ,
																@intForcedExchangeCurrency2 ,
																@decForcedExchange,
																0)

						INSERT INTO dbo.tbAccountTransactionDetail
								   (comp_id,
									bra_id,
									hacc_transaction,
									acc_count_id,
									cc_code,
									dacc_debit,
									dacc_credit,
									user_id,
									dacc_cd,
									hacc_software,
									ct_transaction,
									acc_detail1,
									acc_detail2,
									dacc_order)
							 VALUES
								   (@comp_id,
									@bra_id,
									@hacc_transaction,
									@acc_count_id,
									@cc_code,
									@dacc_debit,
									@dacc_credit,
									@user_id,
									getdate(),
									'True',
									@ct_transaction,
									@utexts_desc,
									@tax_desc,
									10)

						Fetch Next From curTmpTax
							Into	@curTax_id,
									@curTm_amount,
									@curCurr_id

					End

				Close		curTmpTax
				Deallocate	curTmpTax
				-- ------------------------------------------------------------------
				-- Fin Asiento de impuestos
				-- ------------------------------------------------------------------


				-- ------------------------------------------------------------------
				-- Comienzo de Imputacion de Proveedores
				-- ------------------------------------------------------------------
				IF @sd_id = 140 OR @sd_id = 141 OR @sd_id = 143--OR @sd_id = 142
					-- Si es un Movimiento Bancario
					BEGIN

						Set @acc_count_id	 = null
						Select @acc_count_id = acc_count_id
							FROM tbBankingAccounts tba		WITH (NOLOCK)
							Where   tba.comp_id = @comp_id
								and tba.ba_id   = (	Select ba_id
														From dbo.tbCommercialTransactions	WITH (NOLOCK)
														Where   comp_id				= @comp_id
																and ct_transaction	= @ct_transaction )

						If IsNull(@acc_count_id,0) = 0
							Begin
								Set	@ret_ErrorCode = -1
									Select	@ret_ErrorDescription = utexts_desc
										From dbo.tbsysUniqueTexts	WITH (NOLOCK)
										Where lang_id = @lang_id and  utexts_id = 20225
							--		IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
									Return
							END

					END

				ELSE IF @sd_id = 142 -- Liquidacion de Tarjeta de Credito
									 -- Debe poner una imputacion por cada cupon marcado y en la cuenta de cupones pendientes a depositar.
					BEGIN


							DECLARE @ccId			AS INT
							DECLARE @ccTotal		AS DECIMAL(19,4)
							DECLARE @ccCurrId		AS INT
							DECLARE @ccCardNumber	AS NVARCHAR(200)
							DECLARE @cc_Count_Id	AS INT
							DECLARE curCreditCardsMovements  CURSOR LOCAL  FAST_FORWARD FOR
							SELECT	tccm.cc_id,
									tccm.ccm_Total,
									tccm.curr_id,
									tccm.ccm_cardNumber,
									tcc.acc_count_id
								FROM tbCreditCardMovements tccm	WITH (NOLOCK)
								INNER JOIN tbCreditCard tcc		WITH (NOLOCK)
									ON		tcc.comp_id = tccm.comp_id
										AND tcc.cc_id	= tccm.cc_id

								WHERE tccm.cmm_guid		= @tis_guid
							OPEN curCreditCardsMovements
							FETCH NEXT FROM curCreditCardsMovements
								INTO @ccId,@ccTotal,@ccCurrId,@ccCardNumber,@cc_Count_Id
							WHILE @@FETCH_STATUS = 0
								BEGIN

									SET		@dacc_debit		= 0
									SET		@dacc_credit	= 0
									Select	@dacc_credit	= @ccTotal
									Set @dacc_credit = dbo.fnGetExchange2(	@comp_id,
																			@dacc_credit,
																			@ccCurrId,
																			@ct_CompanyCurrency,
																			@intForcedExchangeCurrency1 ,
																			@intForcedExchangeCurrency2 ,
																			@decForcedExchange,
																			0)

									Set @utexts_desc		= 'c' + @ctDetail + ' ' + @ccCardNumber

									INSERT INTO dbo.tbAccountTransactionDetail
										   (comp_id,
											bra_id,
											hacc_transaction,
											acc_count_id,
											cc_code,
											dacc_debit,
											dacc_credit,
											user_id,
											dacc_cd,
											hacc_software,
											ct_transaction,
											acc_detail1,
											acc_detail2,
											dacc_order)
									 VALUES
										   (@comp_id,
											@bra_id,
											@hacc_transaction,
											@cc_Count_Id,
											@cc_code,
											@dacc_debit,
											@dacc_credit,
											@user_id,
											getdate(),
											'True',
											@ct_transaction,
											@utexts_desc,
											'',
											3
										   )

									FETCH NEXT FROM curCreditCardsMovements INTO @ccId,@ccTotal,@ccCurrId,@ccCardNumber,@cc_Count_Id
								END
								CLOSE curCreditCardsMovements
								DEALLOCATE curCreditCardsMovements
					END

				ELSE	-- Si es un Comprobante de Compras

					BEGIN
						Set @acc_count_id	 = null
						Select @acc_count_id = acc_count_id
							FROM tbSupplier ts		WITH (NOLOCK)
							Where   ts.comp_id = @comp_id
								and ts.supp_id = @supp_id	--  MOS 04-2024: No se quien fue el FORRO q hizo esto !  Idem mas abajo
													--(	Select Supp_Id
													--	From dbo.tbCommercialTransactions	WITH (NOLOCK)
													--	Where   comp_id				= @comp_id
													--			and ct_transaction	= @ct_transaction )

						If IsNull(@acc_count_id,0) = 0
							Begin
								Select @acc_count_id = acc_count_id
									From dbo.tbSupplier	WITH (NOLOCK)
									Where   comp_id = @comp_id
										and supp_id = @supp_id
														--(Select Supp_Id
														--From dbo.tbCommercialTransactions	WITH (NOLOCK)
														--Where   comp_id = @comp_id
														--	and ct_transaction = @ct_transaction )
							End

						If IsNull(@acc_count_id,0) = 0
							Begin
								Select @acc_count_id = acc_count_id
									From dbo.tbAccountManagementRelations A	WITH (NOLOCK)
									Where   comp_id		= @comp_id
										and bra_id		= @bra_id
										and samr_id		= 300
							End


						If IsNull(@acc_count_id,0) = 0
							Begin
								Set	@ret_ErrorCode = -1
									Select	@ret_ErrorDescription = utexts_desc
										From dbo.tbsysUniqueTexts	WITH (NOLOCK)
										Where lang_id = @lang_id and  utexts_id = 20225
							--		IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
									Return
							End

					END
				-- ---------------------------------------------------------------------


				IF @sd_id <> 142   -- Si es igual ya lo hizo arriba
				BEGIN


					SET @dacc_debit = 0
					SET @dacc_credit= 0

					Select		@dacc_credit = ct_total
						From	dbo.tbCommercialTransactions
						Where   comp_id = @comp_id
							and ct_transaction = @ct_transaction

					Set @dacc_credit = dbo.fnGetExchange2(	@comp_id,
															@dacc_credit,
															@currency_id,
															@ct_CompanyCurrency,
															@intForcedExchangeCurrency1 ,
															@intForcedExchangeCurrency2 ,
															@decForcedExchange,
															0)

					Select @utexts_desc		= utexts_desc
						From dbo.tbsysUniqueTexts	WITH (NOLOCK)
						Where	lang_id		= @lang_id
							and utexts_id	= 202031

					Set @utexts_desc		= @ctDetail + ' ' + @utexts_desc

					INSERT INTO dbo.tbAccountTransactionDetail
						   (comp_id,
							bra_id,
							hacc_transaction,
							acc_count_id,
							cc_code,
							dacc_debit,
							dacc_credit,
							user_id,
							dacc_cd,
							hacc_software,
							ct_transaction,
							acc_detail1,
							acc_detail2,
							dacc_order)
					 VALUES
						   (@comp_id,
							@bra_id,
							@hacc_transaction,
							@acc_count_id,
							@cc_code,
							@dacc_debit,
							@dacc_credit,
							@user_id,
							getdate(),
							'True',
							@ct_transaction,
							@utexts_desc,
							'',
							3
						   )

				END
				-- ------------------------------------------------------------------
				-- FIN de Imputacion de Proveedores
				-- ------------------------------------------------------------------


				-- ------------------------------------------------------------------
				-- Inicio de Imputacion de COMPRAS
				-- ------------------------------------------------------------------


				-- ------------------------------------------------------------------ GA para vos
				-- x Items
				-- ATENCION!!!  OJO tambien en **sdajfkaesfasdekh654TRDTRD
				-- Trato de sacar las cuentas a las que debo hacer la imputacion
				--		 x totales
				-- ------------------------------------------------------------------
				Select 	 Sum(
  							 dbo.fnGetExchange2(@comp_id,
				   							   A.it_price * A.it_qty * ISNULL(A.it_exchangeToBranchCurrency,1),
											   @intBranchCurrency /*A.curr_id*/,
											   @ct_CompanyCurrency,
    										   @intForcedExchangeCurrency1 ,
											   @intForcedExchangeCurrency2 ,
											   @decForcedExchange,
											   0)
							)						[TotalPriveByAcc],
						 @cc_Code					[cc_Code],
						 CASE
							when B.acc_count_id4Purchase IS NULL THEN tpc.acc_count_id
							else B.acc_count_id4Purchase
						 END						[acc_count_id],
						 CONVERT(NVARCHAR(100),'')   [Note1],
						 CONVERT(NVARCHAR(100),'')   [Note2]
					Into #tbTempItemTransactions
					FROM tbItemTransactions			A		WITH (NOLOCK)
					Left Join	dbo.tbItem			B		WITH (NOLOCK)
						On		A.comp_id		= B.comp_id
							and A.Item_id		= B.Item_Id
					INNER JOIN tbPurchaseConcept tpc		WITH (NOLOCK)
						ON		tpc.comp_id = A.comp_id
							AND tpc.puco_id = A.puco_id

					Where	A.comp_id			= @comp_id
						and A.ct_transaction	= @ct_Transaction
					Group By B.acc_count_id4Purchase	,tpc.acc_count_id


				-- Si no tiene definida ninguna cuenta, busca la 303 x estandard.-
				Update #tbTempItemTransactions
					Set acc_count_id =	(Select acc_count_id
											From dbo.tbAccountManagementRelations A
											Where   comp_id		= @comp_id
												and bra_id		= @bra_id
												and samr_id		= 303
										)
					Where IsNull(acc_count_id,-1) = -1
				-- ------------------------------------------------------------------ GA



				-- x Conceptos de Compra
				INSERT INTO #tbTempItemTransactions
					(   TotalPriveByAcc,
						cc_Code,
						acc_count_id,
						Note1,
						Note2  )
					SELECT SUM(
						dbo.fnGetExchange2( @comp_id,
										   tpcm.pcm_total,
										   tpcm.curr_id,
										   @ct_CompanyCurrency,
										   @intForcedExchangeCurrency1 ,
										   @intForcedExchangeCurrency2 ,
										   @decForcedExchange,
										   0)),
						   tpcm.cc_code,
						   CASE
								WHEN tam.acc_count_id IS NULL THEN	tpc.acc_count_id
								ELSE								tam.acc_count_id
						   END									[acc_count_id],
						   --tpc.acc_count_id,
						   tpcm.pcm_note1,
						   tpcm.pcm_note2
						FROM tbPurchaseConceptMovements tpcm						WITH (NOLOCK)
						INNER JOIN tbPurchaseConcept tpc							WITH (NOLOCK)
							ON		tpc.comp_id = tpcm.comp_id
								AND tpc.puco_id = tpcm.puco_id
						LEFT JOIN tbAccountManagementRelations4PurchaseConcepts tam	WITH (NOLOCK)
							ON	tam.comp_id		= tpcm.comp_id	AND
								tam.bra_id		= tpcm.bra_id	AND
								tam.puco_id		= tpcm.puco_id	AND
								tam.isDisabled	= 'False'
						WHERE	tpcm.comp_id		= @comp_id
							AND tpcm.ct_transaction = @ct_Transaction
						GROUP BY tam.acc_count_id,tpc.acc_count_id,tpcm.cc_code,tpcm.pcm_note1,tpcm.pcm_note2


				If (Select Count(*) From #tbTempItemTransactions Where IsNull(acc_count_id,-1) = -1) > 0
					Begin
						Set	@ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts		WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20220
						--SELECT @ret_ErrorDescription
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
						Return
					End


				DECLARE @strNote1 AS NVARCHAR(100)
				DECLARE @strNote2 AS NVARCHAR(100)

				-- en base a lo anterior, hace las imputaciones correspondientes.-
				Declare crTempItemTransactions
					CURSOR LOCAL  FAST_FORWARD for
						Select	TotalPriveByAcc,
								cc_code,
								acc_count_id,
								Note1,
								Note2
							From #tbTempItemTransactions

				Open crTempItemTransactions

					Fetch Next From crTempItemTransactions
						Into @dacc_debit,
							 @cc_Code,
							 @acc_count_id, @strNote1, @strNote2

					While @@fetch_status = 0
						Begin

							Set		@dacc_Credit		= 0
							-- @dacc_debit desde el cursor

							If @dacc_debit <> 0
								Begin
									Select	@utexts_desc = utexts_desc
										From	dbo.tbsysUniqueTexts		WITH (NOLOCK)
										Where	lang_id = @lang_id and  utexts_id = 202025

									Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc

									INSERT INTO dbo.tbAccountTransactionDetail
											   (comp_id,
												bra_id,
												hacc_transaction,
												acc_count_id,
												cc_code,
												dacc_debit,
												dacc_credit,
												user_id,
												dacc_cd,
												hacc_software,
												ct_transaction,
												acc_detail1,
												acc_detail2,
												dacc_order)
										 VALUES
											   (@comp_id,
												@bra_id,
												@hacc_transaction,
												@acc_count_id,
												@cc_code,
												@dacc_debit,
												@dacc_credit,
												@user_id,
												getdate(),
												'True',
												@ct_transaction,
												@utexts_desc,
												isNull(@strNote1,'') + ' ' + isNull(@strNote2,''),
												8
											   )
								End


							Fetch Next From crTempItemTransactions
								Into @dacc_debit,
									 @cc_Code,
									 @acc_count_id, @strNote1, @strNote2
						End

				Close crTempItemTransactions
				Deallocate crTempItemTransactions
				DROP TABLE #tbTempItemTransactions
				-- ------------------------------------------------------------------
				-- FIN de Imputacion de COMPRAS
				-- ------------------------------------------------------------------

				If ((@IsACredit = 'True' AND  @bitIs4Banking = 'False') OR
					(@IsACredit = 'True' AND  @bitIs4Banking = 'True')
				   )
				   AND @sd_id <> 142 --AND @sd_id <> 143
				   -- (@IsACredit = 'False' AND  @bitIs4Banking = 'True')	-- Segun Celia de MS, deben ir invertidos.! Pedido por AM
					Begin
						Exec spAccountTransaction_InvertWith_ccTransaction  @comp_id,
																			@ct_transaction
					End


				-- -----------------------------------------------------------------
				-- Si es Liquidacion de T. de credito debo asentar la diferencia
				-- con imputacion a la cuenta bancaria
				-- -----------------------------------------------------------------
				IF @sd_id = 142
					BEGIN

						Set @acc_count_id	 = null
						Select @acc_count_id = acc_count_id
							FROM tbBankingAccounts tba		WITH (NOLOCK)
							Where   tba.comp_id = @comp_id
								and tba.ba_id   = @ba_id		-- MOS 04-2024: No se quien Mierda hizo esto
													--(	Select ba_id
													--	From dbo.tbCommercialTransactions
													--	Where   comp_id				= @comp_id
													--			and ct_transaction	= @ct_transaction )

						If IsNull(@acc_count_id,0) = 0
							Begin
								Set	@ret_ErrorCode = -1
									Select	@ret_ErrorDescription = utexts_desc
										From dbo.tbsysUniqueTexts		WITH (NOLOCK)
										Where lang_id = @lang_id and  utexts_id = 20225
									--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
									Return
							END

						DECLARE @decDebit	AS DECIMAL(19,6)
						DECLARE @decCredit	AS DECIMAL(19,6)
						SELECT	@decDebit = IsNull(SUM(tatd.dacc_debit),0),
								@decCredit= IsNull(SUM(tatd.dacc_credit),0)
						FROM tbAccountTransactionDetail tatd
						WHERE	tatd.comp_id		= @comp_id
							AND tatd.ct_transaction = @ct_Transaction
						IF @decCredit <> @decDebit
							BEGIN
								INSERT INTO dbo.tbAccountTransactionDetail
																		   (comp_id,
																			bra_id,
																			hacc_transaction,
																			acc_count_id,
																			cc_code,
																			dacc_debit,
																			dacc_credit,
																			user_id,
																			dacc_cd,
																			hacc_software,
																			ct_transaction,
																			acc_detail1,
																			acc_detail2,
																			dacc_order)
																	 VALUES
																		   (@comp_id,
																			@bra_id,
																			@hacc_transaction,
																			@acc_count_id,
																			@cc_code,
																			/*@decDebit - @decCredit*/    @decCredit - @decDebit,
																			0,
																			@user_id,
																			getdate(),
																			'True',
																			@ct_transaction,
																			@utexts_desc,
																			'',
																			8
																		   )

							END
					END
				-- -----------------------------------------------------------------



				Exec spAccountTransaction_CheckInsertBalance	@comp_id				,
																@bra_id					,
																@lang_id				,
																@user_id				,
																@hacc_transaction		,
																@cc_code				,
																@ct_transaction			,
																@ctDetail				,
																@ret_XErrorCode			= @ret_ErrorCode		OUTPUT 	,
																@ret_XErrorDescription	= @ret_ErrorDescription	OUTPUT

		END TRY
		BEGIN CATCH
			--ROLLBACK TRANSACTION traPROTECT
			DECLARE @ErrorMessage   NVARCHAR(4000)
			DECLARE @ErrorSeverity  INT
			DECLARE @ErrorState     INT
			SELECT  @ErrorMessage    = ERROR_MESSAGE(),
					@ErrorSeverity   = ERROR_SEVERITY(),
					@ErrorState      = ERROR_STATE()
			IF      @ErrorState      = 0 SET @ErrorState = 1
			RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

		END CATCH
		--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT

	END

END
GO



-- Log
-- MOS 05-2024 21228 de casa blanco para cuentas en Factura Anticipada

-- =============================================
-- Author:		MOS
-- Fijarse que si se agrega un campo a la BD
-- hay que tocar todos los SP que se llaman
-- parecidos a este.-
-- Create date: 07-2008
-- =============================================
CREATE PROCEDURE [dbo].[spAccountTransaction_InsertdataFromManagement_Sales]
	(
		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as int,
		@tis_guid				as uniqueidentifier,
		@ct_Transaction			as int,
		@ct_date				as datetime,
		@cc_code				as int,
		@currency_id			as int,
		@ct_CompanyCurrency		as int,
		@user_id				as int,
		@ret_Identity			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
	)
AS

BEGIN

	SET NOCOUNT ON

/*
-- -------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------

-- -------------------------------------------------------------------
*/

	Set @cc_Code			   = null
	Set @ret_Identity		   = 0
	Set @ret_ErrorCode		   = 0
	Set @ret_ErrorDescription  = ''


	-- ----------------------------------------------------------------------------------
	-- Verifica si hay Asientos Contables para esta Sucursal y Asigna el Grupo Contable.-
	-- ----------------------------------------------------------------------------------
	DECLARE		@ag_id AS INT
	SELECT		@ag_id = ag_id
		FROM	tbBranch tb				WITH (NOLOCK)
		WHERE	tb.comp_id = @comp_id
			AND tb.bra_id  = @bra_id
	If @ag_id is NULL RETURN


	-- ----------------------------------------------------------------------------------
	-- Si el Grupo Contable establece una moneda, toma esa moneda para asientos.
	-- ----------------------------------------------------------------------------------
	SELECT @ct_CompanyCurrency =	CASE
										WHEN tag.ag_curr_id IS NULL THEN	@ct_CompanyCurrency
										ELSE								tag.ag_curr_id
									END
		FROM tbAccountantGroup AS tag	WITH (NOLOCK)
		WHERE	tag.comp_id = @comp_id AND
				tag.ag_id	= @ag_id
	-- ----------------------------------------------------------------------------------






	-- Busca si el comprobante a emitir hace asientos contables
	IF NOT EXISTS (SELECT TOP 1  1
					FROM tbCommercialTransactions tct		WITH (NOLOCK)
					INNER JOIN tbsysDocuments td			WITH (NOLOCK)
						ON	tct.sd_id			= td.sd_id
					INNER JOIN tbDocumentsFile tdf	WITH (NOLOCK)
						ON	tdf.comp_id = tct.comp_id AND
							tdf.df_id	= tct.df_id
  					WHERE	tct.comp_id			= @comp_id
						AND tct.ct_transaction	= @ct_Transaction
						AND ISNULL(tdf.df_SaleOrderEmittion_BlockAccountantImputation,'False') = 'False'
						and isnull(td.hacc_group,0) <> 0)
		BEGIN
			RETURN
		END
	-- ----------------------------------------------------------------------------------


	DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT_901		-- MOS 06-2020
    --SAVE TRANSACTION traPROTECT_901
    --BEGIN TRANSACTION
    BEGIN TRY


		Declare @IsACredit      as bit
		Declare @hacc_number	as int
		Declare @hacc_detail	as varchar(60)
		Declare @ap_id			as int
		Declare @Acc_Count_Id	as int
		Declare @dacc_debit		as decimal(19,6)
		Declare @dacc_credit	as decimal(19,6)
		Declare @utexts_desc	as varchar(60)
		Declare @tax_desc		as varchar(60)
		Declare @ctDetail  		as varchar(100)


		--Declare @cc_code		as int
		Set		@cc_Code		= null

		-- Recupera el Centro de Costos desde la Sucursal
		Select @cc_code = cc_code
			From dbo.tbBranch	WITH (NOLOCK)
			Where   comp_id = @comp_id
				and	bra_id  = @bra_id
		If @cc_code is Null
			Begin
				Set @ret_ErrorCode = -1
				Select	@ret_ErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts				WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20217
				--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_901
				Return
			End
		-- ----------------------------------------------




		Set @ctDetail = dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)

		--				Set	@ret_ErrorCode = -1
		--				Select	@ret_ErrorDescription = @ctDetail
		--				return

		-- Recupera el Grupo de Asiento Contable
		Declare @hacc_group as INT
		DECLARE @df_SaleOrder_EmmitionOnlyTaxes AS BIT
		SET		@df_SaleOrder_EmmitionOnlyTaxes = 'False'
		DECLARE @df_SaleOrderEmittion_DoCostAccountant AS BIT
		SET		@df_SaleOrderEmittion_DoCostAccountant = 'False'
		DECLARE @df_id AS INT

		Select	@df_id									= A.df_id,
				@hacc_group								= C.hacc_group,
				@IsACredit								= C.	sd_isCredit,
				@df_SaleOrder_EmmitionOnlyTaxes			= IsNull(b.df_SaleOrder_EmmitionOnlyTaxes,'False'),
				@df_SaleOrderEmittion_DoCostAccountant	= IsNull(B.df_SaleOrderEmittion_DoCostAccountant,'False')	-- Si hace Asiento de CVostos Invierte en el asiernto de costos una NC x ejemplo . . .
			From  dbo.tbCommercialTransactions		A	WITH (NOLOCK)
			Inner join dbo.tbDocumentsFile			B			WITH (NOLOCK)
					On      A.comp_id = B.comp_id
						and A.df_id   = B.df_id    -- MOS 2-2017 df_id en lugar de sd_id
			Inner join dbo.tbsysDocuments			C			WITH (NOLOCK)
					On		B.sd_id = C.sd_id
			Where	A.comp_id		 = @comp_id
				and	A.ct_transaction = @ct_transaction
		-- --------------------------------------

		-- ------------------------------------------------------------------
		-- Verifica si hay un Asiento de la Compañia y Sucursal con ese Grupo
		-- ------------------------------------------------------------------
		Declare @hacc_transaction as int

		Select @hacc_transaction = hacc_transaction
			From dbo.tbAccountTransactionHead				WITH (NOLOCK)
			Where   comp_id			= @comp_id
				and bra_id			= @bra_id
				and hacc_group		= @hacc_group
				and hacc_date		= @ct_date
				and hacc_IsEditing	= 'False'
				AND ag_id			= @ag_id
				AND dbo.fnGetOnlyDate(hacc_cd)	= dbo.fnGetOnlyDate(GETDATE())
		-- ------------------------------------------------------------------

		--	-----------------------------------------------------------------
		--  Si no hay Cabecera dada de alta, la da de alta
		--	-----------------------------------------------------------------
		If IsNull(@hacc_transaction,0) = 0
			Begin

				-- Obtiene Proximo Numero de Asiento.-
				EXEC dbo.spCounters_getNextValue @comp_id,0 , 3, @counter_value = @hacc_number OUTPUT

				-- -------------------------------
				-- Obtiene Descripcion del Asiento
				-- -------------------------------
						Select @hacc_detail = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where   lang_id = @lang_id
								and utexts_id = 202001
				-- -------------------------------

				-- -------------------------------
				-- Obtiene el Periodo
				-- Correspondiente a la fecha
				-- -------------------------------
				SELECT @ap_id = NULL
				Select @ap_id = ap.ap_id
					From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
					INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
						ON	tapbb.comp_id	=	ap.comp_id	AND
							tapbb.bra_id	=	@bra_id		AND
							tapbb.ap_id		=	ap.ap_id
					Where   ap.comp_id		=	@comp_id
						and ap.ap_firstdate <=	@ct_date
						and ap.ap_lastdate  >=	@ct_date
						and ap.ap_closed	=	'False'

				IF @ap_id IS NULL
					BEGIN
						Select @ap_id = ap_id
							From dbo.tbAccountantPeriod				WITH (NOLOCK)
							Where   comp_id = @comp_id
								and ap_firstdate <= @ct_date
								and ap_lastdate  >= @ct_date
								and ap_closed='False'
					END

				If @ap_id is Null
					Begin
						Set @ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20206
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_901
						Return
					End

				-- -------------------------------


				-- Inserta Header Nuevo
				Insert Into dbo.tbAccountTransactionHead
					(	comp_id,
						bra_id,
						hacc_group,
						hacc_detail,
						hacc_date,
						hacc_number,
						hacc_orderPriority,
						hacc_cd,
						ap_id,
						hacc_blocked,
						hacc_closing,
						hacc_opening,
						hacc_IsEditing,
						hacc_IsEditingDateTime,
						ag_id
					)
					Values
					(	@comp_id,
						@bra_id,
						@hacc_group,
						@hacc_detail,
						@ct_date,
						@hacc_number,
						0,
						getdate(),
						@ap_id,
						'False',
						'False',
						'False',
						'False',
						GetDate(),
						@ag_id
					)

				Set @hacc_transaction = @@identity
			End
			--	-----------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Comienza Asiento de parte de Impuestos
			-- ------------------------------------------------------------------
			Declare @curTax_id		as int
			Declare @curTm_amount	as decimal(19,6)
			Declare @curCurr_id		as int

			Declare curTmpTax
				CURSOR LOCAL FAST_FORWARD For
					Select	tax_id,
							Sum(tm_amount),
							curr_id
						From dbo.tbtmpTax	WITH (NOLOCK)
						Where	comp_id  = @comp_id
							and	tis_guid = @tis_guid
						GROUP BY	tax_id,
									curr_id

			Open		curTmpTax

			Fetch Next From curTmpTax
				Into	@curTax_id,
						@curTm_amount,
						@curCurr_id

			While @@Fetch_Status = 0
				Begin

					Set @acc_count_id	 = null
					-- Buscar la Cuenta Contable que Corresponde
					Select @Acc_Count_Id = acc_count_id_forSale
						From dbo.tbAccountByTaxName				WITH (NOLOCK)
						Where   comp_id    = @comp_id
							and bra_id     = @bra_id
							and @curTax_id = tax_id


					-- Si la cuenta Contable NO ESTA DEFINIDA, que CANCELE y ponga en el error
					-- la cuenta contable que falta definir.-
					If IsNull(@Acc_Count_Id,0)=0
						Begin
							Set		@ret_ErrorCode = -1
							Select	@ret_ErrorDescription = 'ID(' + CONVERT(NVARCHAR(10),@curTax_id) + ') ' + utexts_desc
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20205
							--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_901
							Return
						End

					-- Recupera Leyendas de la Imputacion
					Select @utexts_desc = utexts_desc	From dbo.tbsysUniqueTexts	Where lang_id = @lang_id and utexts_id = 202010
					Select @tax_desc	= tax_desc		From dbo.tbTaxName			Where comp_id = @comp_id and tax_id = @curTax_id
					Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc
					-- Pone el Tipo de Cambio Correspondiente, de la moneda
					-- de la sucursal a la moneda de la compañia,
					-- ya que la
					Set @dacc_debit  = 0

					Set @dacc_credit = dbo.fnGetExchange(	@comp_id,
															@curTm_amount,
															@curCurr_id,
															@ct_CompanyCurrency,
															0,
															0,
															0)

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_id,
								@cc_code,
								@dacc_debit,
								@dacc_credit,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								@tax_desc,
								10)


					Fetch Next From curTmpTax
						Into	@curTax_id,
								@curTm_amount,
								@curCurr_id

				End



			Close		curTmpTax
			Deallocate	curTmpTax
			-- ------------------------------------------------------------------
			-- Fin Asiento de impuestos
			-- ------------------------------------------------------------------

			-- ------------------------------------------------------------------
			-- Saca el tipo de relacion para saber si es VENTAS o Rechazos
			-- ------------------------------------------------------------------
			DECLARE @samr_id AS INT
			SET @samr_id = 3
			DECLARE @sctt_id AS INT
			select @sctt_id = tct.sctt_id
				FROM tbCommercialTransactions tct			WITH (NOLOCK)
				WHERE	tct.comp_id				= @comp_id
					AND tct.ct_transaction		= @ct_Transaction
			IF @sctt_id = 102
				BEGIN
					set @samr_id = 550
				END
			-- ------------------------------------------------------------------



			DECLARE @intCustId AS INT
			SELECT @intCustId = tct.cust_id
			FROM tbCommercialTransactions tct	WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id AND
						tct.ct_transaction	= @ct_Transaction


			-- ------------------------------------------------------------------
			-- Comienzo de Imputacion de Deudores por Ventas
			-- ------------------------------------------------------------------
			Set @acc_count_id	 = null
			Select @acc_count_id = acc_count_id
				From dbo.tbCustomer					WITH (NOLOCK)
				Where   comp_id = @comp_id
					and cust_id = @intCustId

			If IsNull(@acc_count_id,0) = 0
				Begin
					Select @acc_count_id = acc_count_id
						From dbo.tbCustomer			WITH (NOLOCK)
						Where   comp_id = @comp_id
							and cust_id = @intCustId
				End

			If IsNull(@acc_count_id,0) = 0
				Begin
					Select @acc_count_id = acc_count_id
						From dbo.tbAccountManagementRelations A		WITH (NOLOCK)
						Where   comp_id		= @comp_id
							and bra_id		= @bra_id
							and samr_id		= 1
				End

			If IsNull(@acc_count_id,0) = 0
				Begin
					Set	@ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20207
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_901
						Return
				End


			Select @dacc_debit = ct_total
				From dbo.tbCommercialTransactions			WITH (NOLOCK)
				Where   comp_id = @comp_id
					and ct_transaction = @ct_transaction

			Set @dacc_debit = dbo.fnGetExchange(	@comp_id,
													@dacc_debit,
													@currency_id,
													@ct_CompanyCurrency,
													0,
													0,
													0)

			Select @utexts_desc		= utexts_desc
				From dbo.tbsysUniqueTexts			WITH (NOLOCK)
				Where	lang_id		= @lang_id
					and utexts_id	= 202020

			Set @utexts_desc		= @ctDetail + ' ' + @utexts_desc

			INSERT INTO dbo.tbAccountTransactionDetail
				   (comp_id,
					bra_id,
					hacc_transaction,
					acc_count_id,
					cc_code,
					dacc_debit,
					dacc_credit,
					user_id,
					dacc_cd,
					hacc_software,
					ct_transaction,
					acc_detail1,
					acc_detail2,
					dacc_order)
			 VALUES
				   (@comp_id,
					@bra_id,
				 @hacc_transaction,
					@acc_count_id,
					@cc_code,
					@dacc_debit,
					0,
					@user_id,
					getdate(),
					'True',
					@ct_transaction,
					@utexts_desc,
					'',
					3
				   )
			-- ------------------------------------------------------------------
			-- FIN de Imputacion de Deudores por Ventas
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- INICIO de Imputacion de Descuentos  Generales
			-- ------------------------------------------------------------------
			Set @acc_count_id	 = null
			-- Busca cuenta de Descuento General
			Select @acc_count_id = acc_count_id
				From dbo.tbAccountManagementRelations A	WITH (NOLOCK)
				Where   comp_id		= @comp_id
					and bra_id		= @bra_id
					and samr_id		= 12

			If IsNull(@acc_count_id,0) = 0
				Begin
					Set	@ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20208
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_901
						Return
				End

			Select	@dacc_debit = Sum(tis_totalDiscountTotal)
						From dbo.tbTempItemStock			WITH (NOLOCK)
						Where   comp_id		= @comp_id
							and tis_guid	= @tis_guid
							AND @df_SaleOrder_EmmitionOnlyTaxes = 'False'

			Set		@dacc_Credit			= 0

			Set		@dacc_debit = dbo.fnGetExchange(@comp_id,
													@dacc_debit,
													@currency_id,
													@ct_CompanyCurrency,
													0,
													0,
													0)



			If @dacc_debit <> 0
				Begin
					Select	@utexts_desc = utexts_desc
						From	dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where	lang_id = @lang_id and  utexts_id = 202021

					Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_id,
								@cc_code,
								@dacc_debit,
								0,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								'',
								5
							   )
				End
			-- ------------------------------------------------------------------
			-- FIN de Imputacion de Descuentos  Generales
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- INICIO de Imputacion de Descuentos  x Items
			-- ------------------------------------------------------------------
			Set @acc_count_id	 = null
			-- Busca cuenta de Descuento x Item
			Select @acc_count_id = acc_count_id
				From dbo.tbAccountManagementRelations A
				Where   comp_id		= @comp_id
					and bra_id		= @bra_id
					and samr_id		= 10

			If IsNull(@acc_count_id,0) = 0
				Begin
					Set	@ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20209
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_901
						Return
				End

			--Select	@dacc_debit = Sum(tis_itemDiscountTotal)
			Select	@dacc_debit = Sum(tis_itemDiscountTotal	+ tis_itemDiscountTotal2)	-- MOS 05-2024: ticket 21542
						From dbo.tbTempItemStock			WITH (NOLOCK)
						Where   comp_id		= @comp_id
							and tis_guid	= @tis_guid
							AND @df_SaleOrder_EmmitionOnlyTaxes = 'False'

			Set		@dacc_Credit			= 0

			Set		@dacc_debit				= dbo.fnGetExchange(@comp_id,
																@dacc_debit,
																@currency_id,
																@ct_CompanyCurrency,
																0,
																0,
																0)


			If @dacc_debit <> 0
				Begin
					Select	@utexts_desc = utexts_desc
						From	dbo.tbsysUniqueTexts	WITH (NOLOCK)
						Where	lang_id = @lang_id and  utexts_id = 202022

					Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_id,
								@cc_code,
								@dacc_debit,
								0,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								'',
								6
							   )
				End
			-- ------------------------------------------------------------------
			-- FIN de Imputacion de Descuentos
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Inicio de Imputacion de Tarjetas de Credito
			-- ------------------------------------------------------------------
			Set @acc_count_id	 = null
			-- Busca cuenta de Interes T.Credito
			Select @acc_count_id = acc_count_id
				From dbo.tbAccountManagementRelations A			WITH (NOLOCK)
				Where   comp_id		= @comp_id
					and bra_id		= @bra_id
					and samr_id		= 15

			If IsNull(@acc_count_id,0) = 0
				Begin
					Set	@ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20210
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_901
						Return
				End


			Select	@dacc_Credit		= Sum(tis_creditInt)
						From dbo.tbTempItemStock			WITH (NOLOCK)
						Where   comp_id		= @comp_id
							and tis_guid	= @tis_guid
							AND @df_SaleOrder_EmmitionOnlyTaxes = 'False'

			Set		@dacc_debit				= 0

			Set		@dacc_Credit			= dbo.fnGetExchange(@comp_id,
																@dacc_Credit,
																@currency_id,
																@ct_CompanyCurrency,
																0,
																0,
																0)

			If @dacc_Credit <> 0
				Begin
					Select	@utexts_desc = utexts_desc
						From	dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where	lang_id = @lang_id and  utexts_id = 202023

					Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_id,
								@cc_code,
								@dacc_debit,
								@dacc_Credit,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								'',
								20
							   )
				End


			-- ------------------------------------------------------------------
			-- FIN de Imputacion de Tarjetas de Credito
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Inicio de Imputacion de Tarjetas de Credito +
			-- ------------------------------------------------------------------
			Set @acc_count_id	 = null
			-- Busca cuenta de Interes T.Credito
			Select @acc_count_id = acc_count_id
				From dbo.tbAccountManagementRelations A	WITH (NOLOCK)
				Where   comp_id		= @comp_id
					and bra_id		= @bra_id
					and samr_id		= 15

			If IsNull(@acc_count_id,0) = 0
				Begin
					Set	@ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20210
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_901
						Return
				End


			Select	@dacc_Credit			= Sum(tis_creditIntPlus)
						From dbo.tbTempItemStock			WITH (NOLOCK)
						Where   comp_id		= @comp_id
							and tis_guid	= @tis_guid
							AND @df_SaleOrder_EmmitionOnlyTaxes = 'False'

			Set		@dacc_debit				= 0

			Set		@dacc_Credit			= dbo.fnGetExchange(@comp_id,
																@dacc_Credit,
																@currency_id,
																@ct_CompanyCurrency,
																0,
																0,
																0)

			If @dacc_Credit <> 0
				Begin
					Select	@utexts_desc = utexts_desc
						From	dbo.tbsysUniqueTexts			WITH (NOLOCK)
						Where	lang_id = @lang_id and  utexts_id = 202024

					Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_id,
								@cc_code,
								@dacc_debit,
								@dacc_Credit,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								'',
								21
							   )
				End
			-- ------------------------------------------------------------------
			-- FIN de Imputacion de Tarjetas de Credito +
			-- ------------------------------------------------------------------


			-- ------------------------------------------------------------------
			-- Inicio de Imputacion de Gastos x Transporte   (Para cuando se haga..
			--	   solo poner aca
			-- ------------------------------------------------------------------
			-- Busca cuenta de Recargo x Transporte
			--		Select @acc_count_id = acc_count_id
			--			From dbo.tbAccountManagementRelations A
			--			Where   comp_id		= @comp_id
			--				and bra_id		= @bra_id
			--				and samr_id		= 20
			--
			--		If IsNull(@acc_count_id,0) = 0
			--			Begin
			--				Set	@ret_ErrorCode = -1
			--					Select	@ret_ErrorDescription = utexts_desc
			--						From dbo.tbsysUniqueTexts
			--						Where lang_id = @lang_id and  utexts_id = 20211
			--					Return
			--			End
			-- ------------------------------------------------------------------
			-- FIN de Imputacion de Gastos x Transporte
			-- ------------------------------------------------------------------



			-- ------------------------------------------------------------------
			-- Inicio de Imputacion de Ventas
			-- ------------------------------------------------------------------

			-- Trato de sacar las cuentas a las que debo hacer la imputacion
			--		 x totales
			Select 	Sum(A.tis_priceInBranchCurrency * A.tis_qty)	[TotalPriveByAcc],
					case
							WHEN A.acc_count_id   IS NOT NULL		THEN A.acc_count_id			-- Si viene del pedido que se haga en una cuenta en particular, lo hace (Por ejemplo, cheque rechazado.)
							WHEN tam.acc_count_id IS NOT NULL		THEN tam.acc_count_id		-- Tiene prioridad esta cuenta, por ejemplo: Venta con Tarjeta de Credito.
							WHEN B.acc_count_id   IS NOT NULL		THEN B.acc_count_id
							WHEN tc.acc_count_id  IS NOT NULL		THEN tc.acc_count_id
							WHEN tsc.acc_count_id IS NOT NULL	    THEN tsc.acc_count_id
							ELSE 										  NULL
					END												[acc_count_id]
				Into #tbTempItemStock
				From		dbo.tbTempItemStock A							WITH (NOLOCK)
				Left Join	dbo.tbItem			B							WITH (NOLOCK)
					On		B.comp_id	= A.comp_id	AND
							B.Item_id	= ISNULL(A.Item_Id,A.item_idfromPreInvoice)	-- A.Item_Id	-- MOS 05-2024 21228 de casa blanco para cuentas en Factura Anticipada
				-- MOS 07-2018
				LEFT JOIN tbCategory			tc							WITH (NOLOCK)
					ON	tc.comp_id		= B.comp_id AND
						tc.cat_id		= B.cat_id
				LEFT JOIN tbSubCategory			tsc							WITH (NOLOCK)
					ON  tsc.comp_id		= B.comp_id AND
						tsc.cat_id		= B.cat_id  AND
						tsc.subcat_id   = B.subcat_id
				-- MOS 07-2018
				LEFT JOIN tbAccountManagementRelations4SalesAccount tam		WITH (NOLOCK)
					ON	tam.comp_id		= A.comp_id AND
						tam.bra_id		= A.bra_id	AND
						tam.st_id		= A.st_id	AND
						tam.df_id		= @df_id
				Where	A.comp_id		= @comp_id
					and A.tis_guid		= @tis_guid
					AND @df_SaleOrder_EmmitionOnlyTaxes = 'False'
				Group By	tam.acc_count_id,
							B.acc_count_id	,
							A.acc_count_id,
							tc.acc_count_id,
							tsc.acc_count_id


			Update #tbTempItemStock
				Set acc_count_id =	(Select acc_count_id
										From dbo.tbAccountManagementRelations A		WITH (NOLOCK)
										Where   comp_id		= @comp_id
											and bra_id		= @bra_id
											and samr_id		= @samr_id     --3
									)
				Where IsNull(acc_count_id,-1) = -1


			If (Select Count(*) From #tbTempItemStock Where IsNull(acc_count_id,-1) = -1) > 0
				Begin
					Set	@ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts		WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20212 --20220
					--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_901
					Return
				End

			-- en base a lo anterior, hace las imputaciones correspondientes.-
			Declare crTempItemStock
				CURSOR LOCAL  FAST_FORWARD for
					Select TotalPriveByAcc, acc_count_id From #tbTempItemStock

			Open crTempItemStock

				Fetch Next From crTempItemStock
					Into @dacc_credit,
						 @acc_count_id

				While @@fetch_status = 0
					Begin

						Set		@dacc_debit				= 0

						Set		@dacc_Credit			= dbo.fnGetExchange(@comp_id,
																			@dacc_Credit,
																			@currency_id,
																			@ct_CompanyCurrency,
																			0,
																			0,
																			0)

						If @dacc_Credit <> 0
							Begin
								Select	@utexts_desc = utexts_desc
									From	dbo.tbsysUniqueTexts		WITH (NOLOCK)
									Where	lang_id = @lang_id and  utexts_id = 202025

								Set @utexts_desc	= @ctDetail + ' ' + @utexts_desc

								INSERT INTO dbo.tbAccountTransactionDetail
										   (comp_id,
											bra_id,
											hacc_transaction,
											acc_count_id,
											cc_code,
											dacc_debit,
											dacc_credit,
											user_id,
											dacc_cd,
											hacc_software,
											ct_transaction,
											acc_detail1,
											acc_detail2,
											dacc_order)
									 VALUES
										   (@comp_id,
											@bra_id,
											@hacc_transaction,
											@acc_count_id,
											@cc_code,
											@dacc_debit,
											@dacc_credit,
											@user_id,
											getdate(),
											'True',
											@ct_transaction,
											@utexts_desc,
											'',
											8
										   )
							End


						Fetch Next From crTempItemStock
							Into @dacc_credit,
								 @acc_count_id
					End

			Close crTempItemStock
			Deallocate crTempItemStock

			-- ------------------------------------------------------------------
			-- FIN de Imputacion de Ventas
			-- ------------------------------------------------------------------


			If @IsACredit = 'True'
				BEGIN
					IF @df_SaleOrderEmittion_DoCostAccountant = 'False'	-- Solo invierte si NO hace asiento de costos. En caso de hacerlo invierte solo al FINAL, o sea, en el asiento de costos.
						BEGIN
							Exec spAccountTransaction_InvertWith_ccTransaction  @comp_id,
																				@ct_transaction
						END
				End


			Exec spAccountTransaction_CheckInsertBalance	@comp_id				,
															@bra_id					,
															@lang_id				,
															@user_id				,
															@hacc_transaction		,
															@cc_code				,
															@ct_transaction			,
															@ctDetail				,
															@ret_XErrorCode			= @ret_ErrorCode		OUTPUT 	,
															@ret_XErrorDescription	= @ret_ErrorDescription	OUTPUT

    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT_901
        IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT_901		-- MOS 06-2020
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_901

END
GO





-- =============================================
-- Author:		MOS
-- Fijarse que si se agrega un campo a la BD
-- hay que tocar todos los SP que se llaman
-- parecidos a este.-
-- Create date: 07-2008
-- =============================================
CREATE PROCEDURE [dbo].[spAccountTransaction_InsertdataFromManagement_SalesCost]
	(
		@comp_id				as int,
		@bra_id					as int,
		@lang_id				as int,
		@tis_guid				as uniqueidentifier,
		@ct_Transaction			as int,
		@ct_date				as datetime,
		@cc_code				as int,
		@currency_id			as int,
		@ct_CompanyCurrency		as int,
		@user_id				as int,
		@ret_Identity			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
	)
AS

BEGIN

	SET NOCOUNT ON

/*
-- -------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------

-- -------------------------------------------------------------------
*/



	-- -------------------------------------------------------------------
	-- Graba aca si es un Remito de Transferencia entre sucursales el sitt_id
	-- -------------------------------------------------------------------
	IF  EXISTS(
						SELECT TOP 1 1
							FROM tbCommercialTransactions	tct WITH (NOLOCK)
							INNER JOIN tbDocumentsFile		tdf	WITH (NOLOCK)
							ON	tdf.comp_id = tct.comp_id  AND
								tdf.df_id	= tct.df_id
							WHERE	tct.comp_id						= @comp_id			AND
									tct.ct_transaction				= @ct_Transaction	AND
									tdf.df_isInterBranchDocument	= 'True'			AND
									tdf.sd_id						= 2
	)
		BEGIN
			UPDATE tbItemTransactions
				SET		sitt_id			= 110
				WHERE	comp_id			= @comp_id			AND
						ct_transaction	= @ct_Transaction
		END
	-- -------------------------------------------------------------------







	Set @cc_Code			   = null
	Set @ret_Identity		   = 0
	Set @ret_ErrorCode		   = 0
	Set @ret_ErrorDescription  = ''

	-- si no hace asiento de costos, sale.-
	IF NOT EXISTS(
						SELECT TOP 1 1
							FROM tbCommercialTransactions tct WITH (NOLOCK)
							INNER JOIN tbDocumentsFile tdf	WITH (NOLOCK)
							ON	tdf.comp_id = tct.comp_id  AND
								tdf.df_id	= tct.df_id
							WHERE	tct.comp_id			= @comp_id			AND
									tct.ct_transaction	= @ct_Transaction	AND
									tdf.df_SaleOrderEmittion_DoCostAccountant	= 'True'
					)
		BEGIN
			RETURN
		END



	-- ----------------------------------------------------------------------------------
	-- Verifica si hay Asientos Contables para esta Sucursal y Asigna el Grupo Contable.-
	-- ----------------------------------------------------------------------------------
	DECLARE		@ag_id AS INT
	SELECT		@ag_id = ag_id
		FROM	tbBranch tb				WITH (NOLOCK)
		WHERE	tb.comp_id = @comp_id
			AND tb.bra_id  = @bra_id
	If @ag_id is NULL RETURN




	-- ----------------------------------------------------------------------------------
	-- Si el Grupo Contable establece una moneda, toma esa moneda para asientos.
	-- ----------------------------------------------------------------------------------
	DECLARE @bitHasAGCurr AS BIT = 'false'
	SELECT @ct_CompanyCurrency   =	CASE
										WHEN tag.ag_curr_id IS NULL THEN	@ct_CompanyCurrency
										ELSE								tag.ag_curr_id
									END,
			@bitHasAGCurr		 = 	CASE
										WHEN tag.ag_curr_id IS NULL THEN	'False'
										ELSE								'True'
									END
		FROM tbAccountantGroup AS tag	WITH (NOLOCK)
		WHERE	tag.comp_id = @comp_id AND
				tag.ag_id	= @ag_id
	-- ----------------------------------------------------------------------------------













	-- Busca si el comprobante a emitir hace asientos contables
	IF NOT EXISTS (SELECT TOP 1  1
					FROM tbCommercialTransactions tct		WITH (NOLOCK)
					INNER JOIN tbsysDocuments td			WITH (NOLOCK)
						ON	tct.sd_id			= td.sd_id
					INNER JOIN tbDocumentsFile tdf	WITH (NOLOCK)
						ON	tdf.comp_id = tct.comp_id AND
							tdf.df_id	= tct.df_id
  					WHERE	tct.comp_id			= @comp_id
						AND tct.ct_transaction	= @ct_Transaction
						AND ISNULL(tdf.df_SaleOrderEmittion_BlockAccountantImputation,'False') = 'False'
						and isnull(td.hacc_group,0) <> 0)
		BEGIN
			RETURN
		END
	-- ----------------------------------------------------------------------------------


	DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT_902		-- MOS 06-2020
    --SAVE TRANSACTION traPROTECT_902
    --BEGIN TRANSACTION
    BEGIN TRY


		Declare @IsACredit      as bit
		Declare @hacc_number	as int
		Declare @hacc_detail	as varchar(60)
		Declare @ap_id			as int
		Declare @Acc_Count_Id	as int
		Declare @dacc_debit		as decimal(19,6)
		Declare @dacc_credit	as decimal(19,6)
		Declare @utexts_desc	as varchar(60)
		Declare @tax_desc		as varchar(60)
		Declare @ctDetail  		as varchar(100)


		--Declare @cc_code		as int
		Set		@cc_Code		= null

		-- Recupera el Centro de Costos desde la Sucursal
		Select @cc_code = cc_code
			From dbo.tbBranch
			Where   comp_id = @comp_id
				and	bra_id  = @bra_id
		If @cc_code is Null
			Begin
				Set @ret_ErrorCode = -1
				Select	@ret_ErrorDescription = utexts_desc
						From dbo.tbsysUniqueTexts				WITH (NOLOCK)
						Where lang_id = @lang_id and  utexts_id = 20217
				--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_902
				Return
			End
		-- ----------------------------------------------




		Set @ctDetail = dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)

		--				Set	@ret_ErrorCode = -1
		--				Select	@ret_ErrorDescription = @ctDetail
		--				return

		-- Recupera el Grupo de Asiento Contable
		Declare @hacc_group as INT
		DECLARE @df_SaleOrder_EmmitionOnlyTaxes AS BIT
		SET @df_SaleOrder_EmmitionOnlyTaxes = 'False'

		Select @hacc_group						= IsNull(C.hacc_group,0) + 1100,
			   @IsACredit						= C.	sd_isCredit,
			   @df_SaleOrder_EmmitionOnlyTaxes	= IsNull(b.df_SaleOrder_EmmitionOnlyTaxes,'False')
			From  dbo.tbCommercialTransactions		A	WITH (NOLOCK)
			Inner join dbo.tbDocumentsFile			B			WITH (NOLOCK)
					On      A.comp_id = B.comp_id
						and A.sd_id   = B.sd_id
			Inner join dbo.tbsysDocuments			C			WITH (NOLOCK)
					On		B.sd_id = C.sd_id
			Where	A.comp_id		 = @comp_id
				and	A.ct_transaction = @ct_transaction
		-- --------------------------------------

		-- ------------------------------------------------------------------
		-- Verifica si hay un Asiento de la Compañia y Sucursal con ese Grupo
		-- ------------------------------------------------------------------
		Declare @hacc_transaction as int

		Select @hacc_transaction = hacc_transaction
			From dbo.tbAccountTransactionHead				WITH (NOLOCK)
			Where   comp_id			= @comp_id
				and bra_id			= @bra_id
				and hacc_group		= @hacc_group
				and hacc_date		= @ct_date
				and hacc_IsEditing	= 'False'
				AND ag_id			= @ag_id
				AND dbo.fnGetOnlyDate(hacc_cd)	= dbo.fnGetOnlyDate(GETDATE())
		-- ------------------------------------------------------------------

		--	-----------------------------------------------------------------
		--  Si no hay Cabecera dada de alta, la da de alta
		--	-----------------------------------------------------------------
		If IsNull(@hacc_transaction,0) = 0
			Begin

				-- Obtiene Proximo Numero de Asiento.-
				EXEC dbo.spCounters_getNextValue @comp_id,0 , 3, @counter_value = @hacc_number OUTPUT

				-- -------------------------------
				-- Obtiene Descripcion del Asiento
				-- -------------------------------
						Select @hacc_detail = utexts_desc
							From dbo.tbsysUniqueTexts			WITH (NOLOCK)
							Where   lang_id = @lang_id
								and utexts_id = 202002
				-- -------------------------------

				-- -------------------------------
				-- Obtiene el Periodo
				-- Correspondiente a la fecha
				-- -------------------------------
				SELECT @ap_id = NULL
				Select @ap_id = ap.ap_id
					From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
					INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
						ON	tapbb.comp_id	=	ap.comp_id	AND
							tapbb.bra_id	=	@bra_id		AND
							tapbb.ap_id		=	ap.ap_id
					Where   ap.comp_id		=	@comp_id
						and ap.ap_firstdate <=	@ct_date
						and ap.ap_lastdate  >=	@ct_date
						and ap.ap_closed	=	'False'

				IF @ap_id IS NULL
					BEGIN
						Select @ap_id = ap_id
							From dbo.tbAccountantPeriod				WITH (NOLOCK)
							Where   comp_id = @comp_id
								and ap_firstdate <= @ct_date
								and ap_lastdate  >= @ct_date
								and ap_closed='False'
					END


				If @ap_id is Null
					Begin
						Set @ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20206
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_902
						Return
					End

				-- -------------------------------


				-- Inserta Header Nuevo
				Insert Into dbo.tbAccountTransactionHead
					(	comp_id,
						bra_id,
						hacc_group,
						hacc_detail,
						hacc_date,
						hacc_number,
						hacc_orderPriority,
						hacc_cd,
						ap_id,
						hacc_blocked,
						hacc_closing,
						hacc_opening,
						hacc_IsEditing,
						hacc_IsEditingDateTime,
						ag_id
					)
					Values
					(	@comp_id,
						@bra_id,
						@hacc_group,
						@hacc_detail,
						@ct_date,
						@hacc_number,
						0,
						getdate(),
						@ap_id,
						'False',
						'False',
						'False',
						'False',
						GetDate(),
						@ag_id
					)

				Set @hacc_transaction = @@identity
			End
			--	-----------------------------------------------------------------


--========================================0

			SELECT @utexts_desc = '',
				   @tax_desc	= ''

			DECLARE @bitUsecostPP AS BIT
			SET		@bitUsecostPP = 'False'
			DECLARE @bitUseCostB  AS BIT
			SET		@bitUseCostB  = 'False'
			DECLARE @acc_count_COST		AS INT = NULL
			DECLARE @acc_count_EXCHDIFF AS INT = NULL
			DECLARE @acc_count_MERCHANT AS INT = NULL


			SELECT @acc_count_COST		= tdf.df_SaleOrderEmittion_COST_acc_count_id,
				   @acc_count_MERCHANT	= tdf.df_SaleOrderEmittion_MERCH_acc_count_id,
				   @acc_count_EXCHDIFF	= tdf.df_SaleOrderEmittion_EXCHDIFF_acc_count_id,
				   @bitUseCostB = isNull(tdf.df_SaleOrderEmittion_DoCostAccountantWithCostB,'False'),
				   @bitUsecostPP= ISNULL(tdf.df_SaleOrderEmittion_DoCostAccountantWithCostPPP,'False'),
				   @utexts_desc = dbo.fnGetCommercialTransactionDescription(tct.comp_id,  2, @ct_Transaction)
				FROM tbCommercialTransactions tct WITH (NOLOCK)
				INNER JOIN tbDocumentsFile tdf	WITH (NOLOCK)
				ON	tdf.comp_id = tct.comp_id  AND
					tdf.df_id	= tct.df_id
				INNER JOIN tbAccountant ta	WITH (NOLOCK)
				ON	ta.comp_id		 = tdf.comp_id AND
					ta.acc_count_id  = tdf.df_SaleOrderEmittion_COST_acc_count_id
				INNER JOIN tbAccountant ta2	WITH (NOLOCK)
				ON	ta2.comp_id		 = tdf.comp_id AND
					ta2.acc_count_id = tdf.df_SaleOrderEmittion_MERCH_acc_count_id
				WHERE	tct.comp_id			= @comp_id			AND
						tct.ct_transaction	= @ct_Transaction	AND
						tdf.df_SaleOrderEmittion_DoCostAccountant	= 'True' AND
						ta.acc_imputable  = 'True' AND
						ta2.acc_imputable = 'True'

				If @acc_count_COST is NULL OR @acc_count_MERCHANT IS null
					Begin
						Set @ret_ErrorCode = -1
						Select	@ret_ErrorDescription = utexts_desc
								From dbo.tbsysUniqueTexts			WITH (NOLOCK)
								Where lang_id = @lang_id and  utexts_id = 20236
						--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_902
						Return
					End



					DECLARE @decTOTAL AS DECIMAL(19,6)
					DECLARE @curr_id AS INT = NULL
					SET		@decTOTAL = 0
					SELECT  @decTOTAL  = SUM(
												CASE
													WHEN @bitUseCostB = 'True'  AND @bitUsecostPP  = 'True'  THEN tit.it_priceBOfCostPP
													WHEN @bitUseCostB = 'True'  AND @bitUsecostPP  = 'False' THEN tit.it_priceBOfCost
													WHEN @bitUseCostB = 'False' AND @bitUsecostPP  = 'True'  THEN tit.it_priceOfCostPP	- (/*tit.it_MPCost +*/ tit.it_MECost + tit.it_MLCost)	-- MOS 03-2021 para que RESTE los costos de MeLi sumados al grabar la transaccion.
													WHEN @bitUseCostB = 'False' AND @bitUsecostPP  = 'False' THEN tit.it_priceOfCost	- (/*tit.it_MPCost +*/ tit.it_MECost + tit.it_MLCost)	-- Si se toca algo hacerlo tambien en [spItemTransactions_InsertData]
												END
												 *
												tit.it_qty
											),
							@curr_id = MAX(tit.curr_id)		-- Todas van a ser en la misma moneda
						FROM tbItemTransactions tit
						WHERE	tit.comp_id			= @comp_id		AND
								tit.ct_transaction	= @ct_Transaction





					-- ----------------------------------------------------------
					-- mos 08:2022
					-- ----------------------------------------------------------
					-- aca para los HDP de s1 habria que sacar la puta suma de los reputos costos a la reputa cotizacion del momento de la reputa compra
					-- para eso  ver de ubicar x serial el ingreso de cada REPUTO SERIAL y ver de sumarlo.  que esten todos los seriales tomados
					-- yo armatia una temporal donde poner cada salida de venta con serial y cada salida sin serial x id, poner el costo y luego hacer el sum sobre esa tabla.
					-- COMO ESTO ES ARA CAGADAS, ponerlo como configuracion y poner texto q es peligroso
					-- ----------------------------------------------------------
					DECLARE @decTOTALCostValued			AS DECIMAL(19,6) = 0
					DECLARE @decTOTALSaleCostValued		AS DECIMAL(19,6) = 0

					SELECT  @decTOTALSaleCostValued  = SUM(
												CASE
													WHEN @bitUseCostB = 'True'  AND @bitUsecostPP  = 'True'  THEN tit.it_priceBOfCostPP
													WHEN @bitUseCostB = 'True'  AND @bitUsecostPP  = 'False' THEN tit.it_priceBOfCost
													WHEN @bitUseCostB = 'False' AND @bitUsecostPP  = 'True'  THEN tit.it_priceOfCostPP	- (/*tit.it_MPCost +*/ tit.it_MECost + tit.it_MLCost)	-- MOS 03-2021 para que RESTE los costos de MeLi sumados al grabar la transaccion.
													WHEN @bitUseCostB = 'False' AND @bitUsecostPP  = 'False' THEN tit.it_priceOfCost	- (/*tit.it_MPCost +*/ tit.it_MECost + tit.it_MLCost)	-- Si se toca algo hacerlo tambien en [spItemTransactions_InsertData]
												END
												* ISNULL(titid.itid_qty,tit.it_qty)
											),
							@decTOTALCostValued		= SUM(
												CASE
													-- Si la MONEDA es la MISMA, que NO calcule dif de cotizacion.  solo x ejemplo para cosas en USD
													WHEN titC.curr_id = tit.curr_id AND @bitUseCostB = 'True'  AND @bitUsecostPP  = 'True'  THEN tit.it_priceBOfCostPP
													WHEN titC.curr_id = tit.curr_id AND @bitUseCostB = 'True'  AND @bitUsecostPP  = 'False' THEN tit.it_priceBOfCost
													WHEN titC.curr_id = tit.curr_id AND @bitUseCostB = 'False' AND @bitUsecostPP  = 'True'  THEN tit.it_priceOfCostPP	- (/*tit.it_MPCost +*/ tit.it_MECost + tit.it_MLCost)	-- MOS 03-2021 para que RESTE los costos de MeLi sumados al grabar la transaccion.
													WHEN titC.curr_id = tit.curr_id AND @bitUseCostB = 'False' AND @bitUsecostPP  = 'False' THEN tit.it_priceOfCost	- (/*tit.it_MPCost +*/ tit.it_MECost + tit.it_MLCost)	-- Si se toca algo hacerlo tambien en [spItemTransactions_InsertData]
													-- Si la compra fue x ejemplo en USD, que tome el precio a la cotizacion de la COMPRA
													WHEN @bitUseCostB = 'True'								THEN titC.it_priceB * titC.it_exchangeToBranchCurrency
													WHEN @bitUseCostB = 'False'								THEN titC.it_price  * titC.it_exchangeToBranchCurrency
												END
												 * ISNULL(titid.itid_qty,tit.it_qty)
											)
						FROM tbItemTransactions					AS	tit		WITH (NOLOCK)
						INNER JOIN tbItemTransactionImportData	AS	titid	WITH (NOLOCK)	-- SIEMPRE DEBE SER INNER.   la dif se calcula SOLO contra los que se ENCUENTRE una compra registrada!!!
							ON	titid.comp_id			= tit.comp_id			AND
								titid.bra_id			= tit.bra_id			AND
								titid.ct_transaction	= tit.ct_transaction	AND
								titid.it_transaction	= tit.it_transaction
						INNER JOIN tbImportData					AS tid		WITH (NOLOCK)
							ON	tid.comp_id				= titid.comp_id			AND
								tid.impData_id			= titid.impData_id
						INNER JOIN tbItemTransactions			AS titC		WITH (NOLOCK)
							ON	titC.comp_id			= tid.comp_id			AND
								titC.it_transaction		= tid.it_transaction
						WHERE	tit.comp_id				= @comp_id				AND
								tit.ct_transaction		= @ct_Transaction

					DECLARE @decExchangeDiff AS DECIMAL(19,6) = ISNULL(@decTOTALSaleCostValued,0)  -  ISNULL(@decTOTALCostValued,0)
					-- ----------------------------------------------------------


					-- El Grupo Contable tiene una moneda particular por lo que debe llevar el importe a esa moneda
					IF	@bitHasAGCurr	= 'True' AND
						@curr_id		<> @ct_CompanyCurrency
						BEGIN
							SET @decTOTAL			= dbo.fnGetExchange2(@comp_id,@decTOTAL,@curr_id,@ct_CompanyCurrency,0,0,0,'False')
							SET @decExchangeDiff	= dbo.fnGetExchange2(@comp_id,@decExchangeDiff,@curr_id,@ct_CompanyCurrency,0,0,0,'False')
						END



					SELECT  @dacc_debit  = @decTOTAL
					SELECT	@dacc_credit = 0

					INSERT INTO dbo.tbAccountTransactionDetail
							   (comp_id,
								bra_id,
								hacc_transaction,
								acc_count_id,
								cc_code,
								dacc_debit,
								dacc_credit,
								user_id,
								dacc_cd,
								hacc_software,
								ct_transaction,
								acc_detail1,
								acc_detail2,
								dacc_order)
						 VALUES
							   (@comp_id,
								@bra_id,
								@hacc_transaction,
								@acc_count_COST,
								@cc_code,
								@dacc_debit,
								@dacc_credit,
								@user_id,
								getdate(),
								'True',
								@ct_transaction,
								@utexts_desc,
								@tax_desc,
								10)


					IF	@acc_count_EXCHDIFF IS NOT NULL  AND
						@decExchangeDiff <> 0
						BEGIN

							SELECT  @dacc_debit  = 0
							SELECT	@dacc_credit = @decTOTAL - @decExchangeDiff

							INSERT INTO dbo.tbAccountTransactionDetail
									   (comp_id,
										bra_id,
										hacc_transaction,
										acc_count_id,
										cc_code,
										dacc_debit,
										dacc_credit,
										user_id,
										dacc_cd,
										hacc_software,
										ct_transaction,
										acc_detail1,
										acc_detail2,
										dacc_order)
								 VALUES
									   (@comp_id,
										@bra_id,
										@hacc_transaction,
										@acc_count_MERCHANT,
										@cc_code,
										@dacc_debit,
										@dacc_credit,
										@user_id,
										getdate(),
										'True',
										@ct_transaction,
										@utexts_desc,
										@tax_desc,
										10)

							INSERT INTO dbo.tbAccountTransactionDetail
									   (comp_id,
										bra_id,
										hacc_transaction,
										acc_count_id,
										cc_code,
										dacc_debit,
										dacc_credit,
										user_id,
										dacc_cd,
										hacc_software,
										ct_transaction,
										acc_detail1,
										acc_detail2,
										dacc_order)
								 VALUES
									   (@comp_id,
										@bra_id,
										@hacc_transaction,
										@acc_count_EXCHDIFF,
										@cc_code,
										0,
										@decExchangeDiff,
										@user_id,
										getdate(),
										'True',
										@ct_transaction,
										@utexts_desc,
										@tax_desc,
										10)


						END
					ELSE	-- Normal como siempre
						BEGIN
							SELECT  @dacc_debit  = 0
							SELECT	@dacc_credit = @decTOTAL

							INSERT INTO dbo.tbAccountTransactionDetail
									   (comp_id,
										bra_id,
										hacc_transaction,
										acc_count_id,
										cc_code,
										dacc_debit,
										dacc_credit,
										user_id,
										dacc_cd,
										hacc_software,
										ct_transaction,
										acc_detail1,
										acc_detail2,
										dacc_order)
								 VALUES
									   (@comp_id,
										@bra_id,
										@hacc_transaction,
										@acc_count_MERCHANT,
										@cc_code,
										@dacc_debit,
										@dacc_credit,
										@user_id,
										getdate(),
										'True',
										@ct_transaction,
										@utexts_desc,
										@tax_desc,
										10)

						END




--========================================0




			If @IsACredit = 'True'
				Begin
					Exec spAccountTransaction_InvertWith_ccTransaction  @comp_id,
																		@ct_transaction
				End


			Exec spAccountTransaction_CheckInsertBalance	@comp_id				,
															@bra_id					,
															@lang_id				,
															@user_id				,
															@hacc_transaction		,
															@cc_code				,
															@ct_transaction			,
															@ctDetail				,
															@ret_XErrorCode			= @ret_ErrorCode		OUTPUT 	,
															@ret_XErrorDescription	= @ret_ErrorDescription	OUTPUT

    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT_902
        IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT_902		-- MOS 06-2020
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_902


END
GO







CREATE PROCEDURE [dbo].[spAccountTransaction_InsertdataFromUpdateIsPayed]
	(
		@comp_id				as INT ,
		@bra_id					as INT ,
		@lang_id				as INT ,
		@chp_id					as INT ,
		@ct_transaction			AS INT ,
		@chp_ispayed			AS bit ,
		@userId					AS INT ,
		@processing_date		AS DATETIME,
		@ret_Identity			as INT 			OUTPUT ,
		@ret_ErrorCode			as INT 			OUTPUT ,
		@ret_ErrorDescription	as VARCHAR(200) OUTPUT
	)
AS
BEGIN

	SET NOCOUNT ON

	Set @ret_Identity		   = 0
	Set @ret_ErrorCode		   = 0
	Set @ret_ErrorDescription  = ''




	/****************************************************************************************/
	/*
		@chp_ispayed = 0   D:acc_count_id_notCollected  H:acc_count_id
		@chp_ispayed = 1   H:acc_count_id_notCollected  D:acc_count_id
	*/
	/****************************************************************************************/


	-- ----------------------------------------------------------------------------------
	-- Verifica si hay Asientos Contables para ésta Sucursal y Asigna el Grupo Contable.-
	-- ----------------------------------------------------------------------------------
	DECLARE		@ag_id				AS INT
	DECLARE		@datProcessingDate	AS DATETIME
	SELECT		@ag_id				= ag_id ,
				@datProcessingDate	= @processing_date  --tb.bra_processingDate
		FROM	tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id = @comp_id
			AND tb.bra_id  = @bra_id
	If @ag_id is NULL RETURN
	-- ----------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------------------
	-- Cabecera del Asiento
	-- ----------------------------------------------------------------------------------
	DECLARE @bitIsPayed		AS BIT
	DECLARE @currency_Id	AS INT
	Declare @hacc_number	as int
	Declare @hacc_detail	as varchar(60)
	Declare @ap_id			as INT
	DECLARE @ba_id			AS INT
	Declare @acc_Count_Id				AS INT
	Declare @acc_Count_Id_notCollected	as INT
	DECLARE @decTotal					AS DECIMAL(19,4)
	SET @decTotal	= 0

	Declare @dacc_debit		as decimal(19,6)
	set @dacc_debit = 0

	Declare @dacc_credit	as decimal(19,6)
	set @dacc_credit = 0

	Declare @utexts_desc	as varchar(60)
	Declare @tax_desc		as varchar(60)
	Declare @ctDetail  		as varchar(100)

	Declare @cc_code			as int
	Declare @ct_CompanyCurrency	as int
	Set		@cc_Code			= null
	Set		@ct_CompanyCurrency = Null

	Declare	@ct_date			as Datetime
	Set @ct_date = @datProcessingDate

	-- ----------------------------------------------
	-- Recupera la Moneda de la Compañia
	-- ----------------------------------------------
	Select @ct_CompanyCurrency = curr_id
		From dbo.tbCompany	WITH (NOLOCK)
		Where   comp_id = @comp_id

	If @ct_CompanyCurrency is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts	WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20218
			Return
		End
	-- ----------------------------------------------


	-- ----------------------------------------------------------------------------------
	-- Si el Grupo Contable establece una moneda, toma esa moneda para asientos.
	-- ----------------------------------------------------------------------------------
	SELECT @ct_CompanyCurrency =	CASE
										WHEN tag.ag_curr_id IS NULL THEN	@ct_CompanyCurrency
										ELSE								tag.ag_curr_id
									END
		FROM tbAccountantGroup AS tag	WITH (NOLOCK)
		WHERE	tag.comp_id = @comp_id AND
				tag.ag_id	= @ag_id
	-- ----------------------------------------------------------------------------------






	-- ----------------------------------------------
	-- Recupera el Centro de Costos desde la Sucursal
	-- ----------------------------------------------
	Select @cc_code = cc_code
		From dbo.tbBranch	WITH (NOLOCK)
		Where   comp_id = @comp_id
			and	bra_id  = @bra_id
	If @cc_code is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts	WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20217
			Return
		End
	-- ----------------------------------------------

	-- ----------------------------------------------
	-- Recupera el Nombre del Asiento,
	--  si es que es nuevo
	-- ----------------------------------------------
	Select @ctDetail = utexts_desc
						From dbo.tbsysUniqueTexts	WITH (NOLOCK)
						Where   lang_id = @lang_id
							and utexts_id = (223805)
	-- --------------------------------------------------

	-- --------------------------------------------------
	-- Recupera el Grupo de Asiento Contable		OK
	-- Lo usual es que se saque de sysDocuments!!!!!!!
	-- --------------------------------------------------
	Declare @hacc_group as int
	Select @hacc_group =	10201
	-- --------------------------------------------------

	-- --------------------------------------------------
	-- Recupera Moneda de la compañia,
	-- para hacer el asiento.-
	-- --------------------------------------------------
	Select @ct_CompanyCurrency	= curr_id
		From dbo.tbCompany	WITH (NOLOCK)
		Where comp_id			= @comp_id
	-- --------------------------------------------------

	-- ------------------------------------------------------------------
	-- Verifica si hay un Asiento de la Compañia
	-- y Sucursal con ese Grupo	OK
	-- ------------------------------------------------------------------
	Declare @hacc_transaction as int

	Select @hacc_transaction = hacc_transaction
		From dbo.tbAccountTransactionHead	WITH (NOLOCK)
		Where   comp_id			= @comp_id
			and bra_id			= @bra_id
			and hacc_group		= @hacc_group
			and hacc_date		= @ct_date
			and hacc_IsEditing	= 'False'
			AND ag_id			= @ag_id
			AND dbo.fnGetOnlyDate(hacc_cd)	= dbo.fnGetOnlyDate(GETDATE())
	-- ------------------------------------------------------------------

	--	-----------------------------------------------------------------
	--  Si no hay Cabecera dada de alta, la da de alta
	--	-----------------------------------------------------------------
	If IsNull(@hacc_transaction,0) = 0
		Begin

			-- Obtiene Proximo Numero de Asiento.-
			EXEC dbo.spCounters_getNextValue @comp_id, 0 , 3, @counter_value = @hacc_number OUTPUT

			-- -------------------------------
			-- Obtiene Descripcion del Asiento OK
			-- -------------------------------
				Select @hacc_detail = utexts_desc
					From dbo.tbsysUniqueTexts	WITH (NOLOCK)
					Where   lang_id = @lang_id
						and utexts_id = (223805)
			-- -------------------------------

			-- -------------------------------
			-- Obtiene el Periodo
			-- Correspondiente a la fecha			OK
			-- -------------------------------
			SELECT @ap_id = NULL
			Select @ap_id = ap.ap_id
				From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
				INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
					ON	tapbb.comp_id	=	ap.comp_id	AND
						tapbb.bra_id	=	@bra_id		AND
						tapbb.ap_id		=	ap.ap_id
				Where   ap.comp_id		=	@comp_id
					and ap.ap_firstdate <=	@ct_date
					and ap.ap_lastdate  >=	@ct_date
					and ap.ap_closed	=	'False'

			IF @ap_id IS NULL
				BEGIN
					Select @ap_id = ap_id
						From dbo.tbAccountantPeriod	WITH (NOLOCK)
						Where   comp_id = @comp_id
							and ap_firstdate <= @ct_date
							and ap_lastdate  >= @ct_date
							and ap_closed='False'
				END


			If @ap_id is Null
				Begin
					Set @ret_ErrorCode = -1
					Select	@ret_ErrorDescription = utexts_desc
							From dbo.tbsysUniqueTexts	WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20206
					Return
				End
			-- --------------------------------------------------


			-- --------------------------------------------------
			-- Inserta Header Nuevo						OK
			-- --------------------------------------------------
			Insert Into dbo.tbAccountTransactionHead
				(	comp_id,
					bra_id,
					hacc_group,
					hacc_detail,
					hacc_date,
					hacc_number,
					hacc_orderPriority,
					hacc_cd,
					ap_id,
					hacc_blocked,
					hacc_closing,
					hacc_opening,
					hacc_IsEditing,
					hacc_IsEditingDateTime,
					ag_id
				)
				Values
				(	@comp_id,
					@bra_id,
					@hacc_group,
					@hacc_detail,
					@ct_date,
					@hacc_number,
					0,
					getdate(),
					@ap_id,
					'False',
					'False',
					'False',
					'False',
					GetDate(),
					@ag_id
				)

			Set @hacc_transaction = @@identity
		End
	-- ----------------------------------------------------------------------------------

--**

	-- ----------------------------------------------------------------------------------
	-- Detalle
	-- ----------------------------------------------------------------------------------

	-- Obtiene Datos del Cheque
	Select @decTotal	= chp_total,
		   @currency_Id = tcp1.curr_id
		From dbo.tbCheckPortfolio tcp1	WITH (NOLOCK)
		Where   tcp1.comp_id = @comp_id
			and tcp1.chp_id  = @chp_id

	-- Setea el Importe de la Imputación Contable
	Set @decTotal	= dbo.fnGetExchange(	@comp_id,
											@decTotal,
											@currency_id,
											@ct_CompanyCurrency,
											0,
											0,
											0)


	-- ---------------------------------------------------------
	-- Obtener la Cuenta Bancaria del Deposito
	-- ---------------------------------------------------------
	SELECT @ba_id					= tbt.ba_id
		FROM	tbBankingTransactions tbt	WITH (NOLOCK)
		WHERE	tbt.comp_id			= @comp_id
			AND tbt.chp_id			= @chp_id
			AND tbt.btt_id			= 1000020
			AND tbt.bt_isCancelled	= 'False'
	If @ba_id is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts	WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20280
			Return
		End


	SELECT	@acc_Count_Id				= tba.acc_count_id,
			@acc_Count_Id_notCollected	= tba.acc_count_id_notCollected
		FROM tbBankingAccounts tba	WITH (NOLOCK)
		WHERE	tba.comp_id				= @comp_id
			AND tba.ba_id				= @ba_id

	If @acc_Count_Id is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts	WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20281
			Return
		End

	If @acc_Count_Id_notCollected is Null
		Begin
			Set @ret_ErrorCode = -1
			Select	@ret_ErrorDescription = utexts_desc
					From dbo.tbsysUniqueTexts	WITH (NOLOCK)
					Where lang_id = @lang_id and  utexts_id = 20282
			Return
		End



	IF @chp_ispayed = 'False'
		BEGIN
			Select @utexts_desc		= utexts_desc
				From dbo.tbsysUniqueTexts	WITH (NOLOCK)
				Where	lang_id		= @lang_id
					and utexts_id	= 202504
		END
	ELSE
		BEGIN
			Select @utexts_desc		= utexts_desc
				From dbo.tbsysUniqueTexts	WITH (NOLOCK)
				Where	lang_id		= @lang_id
					and utexts_id	= 202503
		END

	Set @utexts_desc		= @ctDetail + ' ' + @utexts_desc

	-- ---------------------------------------------------------

	-- ATENCION.!
	-- Aca hay algo en el diseño que no me gusta para nada ya que este movimiento no tiene una contrapartida en
	-- la tabla tbCommercialTransactions.


	IF @chp_ispayed = 'False'
		BEGIN
			SET @dacc_debit		=	@decTotal
			SET @dacc_credit	=	0
		END
	ELSE
		BEGIN
			SET @dacc_debit		=	0
			SET @dacc_credit	=	@decTotal
		END


	INSERT INTO dbo.tbAccountTransactionDetail
		   (comp_id,
		    bra_id,
		    hacc_transaction,
		    acc_count_id,
		    cc_code,
		    dacc_debit,
		    dacc_credit,
		    user_id,
		    dacc_cd,
		    hacc_software,
		    ct_transaction,
		    acc_detail1,
		    acc_detail2,
			dacc_order)
	 VALUES
		   (@comp_id,
		    @bra_id,
		    @hacc_transaction,
		    @acc_count_id,
		    @cc_code,
		    @dacc_credit,
		    @dacc_debit,
		    @userId,
		    getdate(),
		    'True',
		    NULL,
		    @utexts_desc,
		    '',
			3
		   )



	INSERT INTO dbo.tbAccountTransactionDetail
		   (comp_id,
		    bra_id,
		    hacc_transaction,
		    acc_count_id,
		    cc_code,
		    dacc_debit,
		    dacc_credit,
		    user_id,
		    dacc_cd,
		    hacc_software,
		    ct_transaction,
		    acc_detail1,
		    acc_detail2,
			dacc_order)
	 VALUES
		   (@comp_id,
		    @bra_id,
		    @hacc_transaction,
		    @acc_Count_Id_notCollected,
		    @cc_code,
		    @dacc_debit,
		    @dacc_credit,
		    @userId,
		    getdate(),
		    'True',
		    NULL,
		    @utexts_desc,
		    '',
			3
		   )



END
GO





-- =============================================
-- Author:		MOS
-- Create date: 08-2008
-- Invierte parte de un asiento
--         (x si es un credito)
-- =============================================

CREATE PROCEDURE [dbo].[spAccountTransaction_InvertWith_ccTransaction]
	(
		@comp_id		as int,
		@ct_transaction as int
	)
AS
BEGIN

	SET NOCOUNT ON;

/*
DECLARE 		@comp_id		as int,
				@ct_transaction as int
select			@comp_id		= 1,
				@ct_transaction = 15
*/

	Declare @dacc_transaction	as int
	Declare	@dacc_debit			as DECIMAL(19,6)
	Declare	@dacc_credit		as DECIMAL(19,6)

	Declare cursor_AT_IWccT_items
		CURSOR LOCAL  FAST_FORWARD For
			Select dacc_transaction,
				   dacc_debit,
				   dacc_credit
				From dbo.tbAccountTransactionDetail
				Where   comp_id        = @comp_id
					and ct_transaction = @ct_transaction

	Open       cursor_AT_IWccT_items

		Fetch Next From cursor_AT_IWccT_items
		Into	@dacc_transaction,
				@dacc_debit,
				@dacc_credit

		While @@Fetch_Status=0
			Begin

				Update dbo.tbAccountTransactionDetail
					Set dacc_debit  = @dacc_credit,
						dacc_credit = @dacc_debit
					Where   comp_id          = @comp_id
						and dacc_transaction = @dacc_transaction

				Fetch Next From cursor_AT_IWccT_items
				Into	@dacc_transaction,
						@dacc_debit,
						@dacc_credit
			End

	Close	   cursor_AT_IWccT_items
	Deallocate cursor_AT_IWccT_items

END
GO









