CREATE PROCEDURE [dbo].[spAccountTransactionDetailTmp_deleteOldData]
as
set nocount on

/*
declare @comp_id	int
select	@comp_id	= 1
*/

declare @time		int
set		@time		= -120000


declare @comp_id	int

declare cursor_ATDT_dOD_items cursor for
select	comp_id
from	tbCompany

open	cursor_ATDT_dOD_items

fetch next from cursor_ATDT_dOD_items
into	@comp_id

while @@fetch_status = 0
begin

	delete	dbo.tbAccountTransactionDetailTmp
	where	dbo.tbAccountTransactionDetailTmp.comp_id		=	@comp_id
	and		dbo.tbAccountTransactionDetailTmp.dacc_guid in (
											select	distinct tdat.dacc_guid
											from	dbo.tbAccountTransactionDetailTmp tdat
											where	tdat.comp_id		=	@comp_id
											and		tdat.dacc_cd		<	DATEADD(minute, @time, getdate())
											)

	fetch next from cursor_ATDT_dOD_items
	into	@comp_id

end

close		cursor_ATDT_dOD_items
deallocate	cursor_ATDT_dOD_items




GO






CREATE PROCEDURE [dbo].[spAccountTransactionDetailTmp_getData]
(
	@comp_id			int,
	@dacc_guid			uniqueidentifier,
	@ct_transaction		INT,
	@import				DECIMAL(18,4)

)
as


BEGIN

	set nocount on

	-- -----------------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------------
/*
	declare @comp_id			int,
		@dacc_guid			uniqueidentifier
	select @comp_id			=1,
		@dacc_guid			= '90c70b2b-b3d4-48be-9dc3-f49ea8488566'
*/
	-- -----------------------------------------------------------------------------------

	select	' ' [ ], ' ' [ ], ' ' [ ],
			dacc.dacc_guid,
			dacc.acc_count_id,
			a.acc_code,
			a.acc_desc,
			dacc.cc_code,
			dacc.user_id,
			dacc.dacc_debit,
			dacc.dacc_credit,
			dacc.acc_detail1,
			cc.cc_desc,
			dacc.dacc_cd,
			vwc.Name,
			dacc.hacc_software,
			u.user_lastname + ', ' + u.user_firstname [user_name],
			dacc.ct_transaction,
			dacc.dacc_transaction --el id tiene que estar obligatoriamente en última posición

	from	dbo.tbAccountTransactionDetailTmp		dacc

			left join dbo.tbAccountant				a
			on	a.comp_id		= dacc.comp_id
			and	a.acc_count_id	= dacc.acc_count_id

			left join dbo.tbCostCenter				cc
			on	cc.comp_id		= dacc.comp_id
			and cc.cc_code		= dacc.cc_code

			left join dbo.tbUser					u
			on	u.user_id		= dacc.user_id

			LEFT JOIN vwAccountant_ctTransactionGetNames			vwc
				ON		vwc.comp_id			= dacc.comp_id
					AND vwc.ct_transaction	= dacc.ct_transaction

	where	dacc.comp_id		=	@comp_id
	and		dacc.dacc_guid		=	@dacc_guid
	AND		(
				CASE
					WHEN @ct_transaction > 0 AND @ct_transaction = dacc.ct_transaction   THEN 1
					WHEN @ct_transaction = 0											 THEN 1
					ELSE																	  0
				END = 1
			)

	AND		(
				CASE
					WHEN @import = dacc.dacc_debit OR @import = dacc.dacc_credit		THEN 1
					WHEN @import = 0						     						THEN 1
					ELSE																	 0
				END = 1
			)


	order by dacc.dacc_transaction


	select	--dacc.dacc_guid,
			sum(dacc.dacc_debit)	[dacc_debit],
			sum(dacc.dacc_credit)	[dacc_credit]

	from	dbo.tbAccountTransactionDetailTmp		dacc

			left join dbo.tbAccountant				a
			on	a.comp_id		= dacc.comp_id
			and	a.acc_count_id	= dacc.acc_count_id

			left join dbo.tbCostCenter				cc
			on	cc.comp_id		= dacc.comp_id
			and cc.cc_code		= dacc.cc_code

			left join dbo.tbUser					u
			on	u.user_id		= dacc.user_id

	where	dacc.comp_id		=	@comp_id
	and		dacc.dacc_guid		=	@dacc_guid
	AND		(
				CASE
					WHEN @ct_transaction > 0 AND @ct_transaction = dacc.ct_transaction   THEN 1
					WHEN @ct_transaction = 0											 THEN 1
					ELSE																	  0
				END = 1
			)

	AND		(
				CASE
					WHEN @import = dacc.dacc_debit OR @import = dacc.dacc_credit		THEN 1
					WHEN @import = 0						     						THEN 1
					ELSE																	 0
				END = 1
			)

	--group by dacc.dacc_guid



END











GO






CREATE PROCEDURE [dbo].[spAccountTransactionDetailTmp_getDataById]
(
		@dacc_transaction		int
)
AS

BEGIN

	set nocount on

	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*
	declare @dacc_transaction			int
	select @dacc_transaction			=3
	*/
	-- ----------------------------------------------------------------

	select	' ' [ ], ' ' [ ],
			dacc.dacc_guid,
			dacc.acc_count_id,
			a.acc_desc,
			a.acc_code,
			dacc.cc_code,
