CREATE PROCEDURE [dbo].[spAccountTransactionDetailTMP_IsAsientoBalanced]
(
	@comp_id		INT,
	@dacc_guid		UNIQUEIDENTIFIER,	--GUID ORIGINAL
	@ct_transaction	INT,
	@dacc_NewGuid	UNIQUEIDENTIFIER	--NUEVO GUID
)
AS



BEGIN

	SET NOCOUNT ON





	-- -----------------------------------------------
	-- TESTING
	-- -----------------------------------------------
	/*
		DECLARE
			@comp_id		INT,
			@dacc_guid		UNIQUEIDENTIFIER,	--GUID ORIGINAL
			@ct_transaction	INT	,
			@dacc_NewGuid	UNIQUEIDENTIFIER	--NUEVO GUID
		SELECT
			@comp_id		= 1,
			@dacc_guid		= 'B694381B-E2A6-486C-876D-27E44E1392B3',
			@ct_transaction	= 12541,
			@dacc_NewGuid	= 'B69AAA1B-E2A6-486C-876D-27E44E1392B3'
	*/
	-- -----------------------------------------------

	DECLARE
		@ResultDebitMinusCredit	DECIMAL(25,4)
	SET @ResultDebitMinusCredit = 0

	SELECT
		@ResultDebitMinusCredit = SUM(tatdt.dacc_debit) - SUM(tatdt.dacc_credit)
		FROM tbAccountTransactionDetailTmp				tatdt	WITH(NOLOCK)
		WHERE	tatdt.comp_id			= @comp_id		AND
				tatdt.dacc_guid			= @dacc_guid	AND
				tatdt.ct_transaction	= @ct_transaction


	--CHECKEAR EL COUNT
	IF (SELECT COUNT(*)
			FROM tbAccountTransactionDetailTmp tatdt
			WHERE	tatdt.comp_id	= @comp_id					AND
					tatdt.dacc_guid = @dacc_guid)
		<>
	   (SELECT COUNT(*)
			FROM tbAccountTransactionDetailTmp tatdt
			WHERE	tatdt.comp_id			= @comp_id			AND
					tatdt.dacc_guid			= @dacc_guid		AND
					tatdt.ct_transaction	= @ct_transaction)
		BEGIN
			IF @ResultDebitMinusCredit = 0
				BEGIN

					SELECT 'True'

					UPDATE tbAccountTransactionDetailTmp
						SET		dacc_guid		= @dacc_NewGuid
						WHERE	comp_id			= @comp_id		AND
								dacc_guid		= @dacc_guid	AND
								ct_transaction	= @ct_transaction

				END
			ELSE
				BEGIN
					SELECT 'False'
				END
		END
	ELSE
		BEGIN
			SELECT 'False'
		END


END





GO







CREATE  PROCEDURE [dbo].[spAccountTransactionDetailTmp_updateData]
(
	@dacc_transaction			int,
	@acc_count_id				int,
	@cc_code					int,
	@user_id					int,
	@dacc_debit					decimal(18,4),
	@dacc_credit				decimal(18,4),
	@hacc_software				bit,
	@ct_transaction				INT,
	@dacc_2ndCurrencyExchange		DECIMAL(19,6),
	@acc_detail1				VARCHAR(100),
	@acc_detail2				VARCHAR(100)
)
AS

BEGIN



	set nocount on

	--declare
	--		@dacc_transaction	int,
	--		@acc_count_id		int,
	--		@cc_code			int,
	--		@user_id			int,
	--		@dacc_debit			decimal(18,4),
	--		@dacc_credit		decimal(18,4),
	--		@hacc_software		bit,
	--		@ct_transaction		int


	IF @cc_code = -1 SET @cc_code = null


	update	dbo.tbAccountTransactionDetailTmp
		set		acc_count_id				= @acc_count_id,
				cc_code						= @cc_code,
				user_id						= @user_id ,
				dacc_debit					= @dacc_debit,
				dacc_credit					= @dacc_credit,
				hacc_software				=	CASE
													WHEN hacc_software = 1 THEN 1
													ELSE						@hacc_software
												END,
				--ct_transaction				= @ct_transaction,    NOOOO, que deje el original   MOS 06-2016
				dacc_2ndCurrencyExchange	= @dacc_2ndCurrencyExchange,
				acc_detail1					= @acc_detail1,
				acc_detail2					= @acc_detail2

