CREATE PROCEDURE [dbo].[spAccountTransactionHead_getDataByFilters]
(
	@comp_id					INT,
	@bra_id						INT,
	@ap_id						INT,
	@datefrom					datetime,
	@dateto						datetime,
	@ag_id						INT,
	@user_id					INT,
	@option						INT,
	@NumberFrom					VARCHAR(40),
	@optionDesc					INT,
	@DescFrom					VARCHAR(40),
	@ct_transaction				INT,
	@acc_count_id				INT,
	@option_number_original		INT,
	@NumberFromOriginal			VARCHAR(40)
)
AS


BEGIN

	set nocount ON
	set dateformat 'ymd'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET @datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto   = dbo.fnGetEnd_or_BeginOfDate(@dateto  ,'True')


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------

	/*
		declare	@comp_id		int,
				@bra_id			int,
				@ap_id			int,
				@datefrom		datetime,
				@dateto			Datetime,
				@ag_id			INT,
				@user_id		INT,
				@option			INT,
				@NumberFrom		VARCHAR(40),
				@optionDesc		INT,
				@DescFrom		VARCHAR(40)

		select	@comp_id		= 1,
				@bra_id			= 1,
				@ap_id			= 21,
				@datefrom		= convert(datetime,'01/01/2000'),
				@dateto			= convert(datetime,'12/31/2010'),
				@ag_id			= -1,
				@user_id		= 1
		*/
	-- -------------------------------------------------------------------------------

	IF @ct_transaction <> 0

		BEGIN

			SELECT DISTINCT		' ' [ ], ' ' [ ],
					hat.comp_id,
					hat.bra_id,
					hat.hacc_group,
					hat.hacc_date,
					hat.hacc_number,
					hat.hacc_orderPriority,
					hat.hacc_cd,
					hat.ap_id,
					ap.ap_desc,
					hat.hacc_blocked,
					hat.hacc_closing,
					hat.hacc_opening,
					hat.hacc_IsEditing,
					hat.hacc_IsEditingDateTime,
					hat.hacc_detail,
					ISNULL(tu.user_lastname,'') + ', ' + ISNULL(tu.user_firstname,'')		[userName],
					hat.hacc_lastUpdate,
					hat.hacc_transaction [ID]

			FROM 	dbo.tbAccountTransactionHead				hat		WITH(NOLOCK)

					LEFT JOIN dbo.tbAccountantPeriod			ap		WITH(NOLOCK)
					ON  ap.comp_id				= hat.comp_id	AND
						ap.ap_id				= hat.ap_id

					INNER JOIN tbUsers4BranchFilter				vubf	WITH(NOLOCK)
					ON	vubf.comp_id			= hat.comp_id	AND
						vubf.bra_id				= hat.bra_id	AND
						vubf.[user_id]			= @user_id

					LEFT JOIN tbUser							tu		WITH (NOLOCK)
						ON tu.[user_id] = hat.[user_id]

					LEFT JOIN tbAccountTransactionDetail		tatd	WITH (NOLOCK)
						ON	tatd.comp_id			= hat.comp_id		AND
							tatd.bra_id				= hat.bra_id		AND
							tatd.hacc_transaction	= hat.hacc_transaction

			WHERE	hat.comp_id			= @comp_id
			AND		hat.ap_id			= @ap_id
			AND		hat.hacc_date		between @datefrom and @dateto
			AND		tatd.ct_transaction = @ct_transaction
			AND     (hat.ag_id = @ag_id)   --  (@ag_id				= -1	Or   hat.ag_id = @ag_id)
			AND 	(
						(@option = -1)														OR
						(@option = 0 and hat.hacc_number like			@NumberFrom + '%')	OR
						(@option = 1 and hat.hacc_number like '%' +		@NumberFrom + '%')	OR
						(@option = 2 and hat.hacc_number =				@NumberFrom)		OR
						(@option = 3 and hat.hacc_number <>				@NumberFrom)		OR
						(@option = 4 and hat.hacc_number not like '%' +	@NumberFrom + '%')
					)
			AND 	(
						(@option_number_original = -1)														OR
						(@option_number_original = 0 and hat.hacc_originalNumber like			@NumberFromOriginal + '%')	OR
						(@option_number_original = 1 and hat.hacc_originalNumber like '%' +		@NumberFromOriginal + '%')	OR
						(@option_number_original = 2 and hat.hacc_originalNumber =				@NumberFromOriginal)		OR
						(@option_number_original = 3 and hat.hacc_originalNumber <>				@NumberFromOriginal)		OR
						(@option_number_original = 4 and hat.hacc_originalNumber not like '%' +	@NumberFromOriginal + '%')
					)

			AND 	(
						(@optionDesc = -1)													OR
						(@optionDesc = 0 and hat.hacc_detail like			@DescFrom + '%')OR
						(@optionDesc = 1 and hat.hacc_detail like '%' +		@DescFrom + '%')OR
						(@optionDesc = 2 and hat.hacc_detail =				@DescFrom)		OR
						(@optionDesc = 3 and hat.hacc_detail <>				@DescFrom)		OR
						(@optionDesc = 4 and hat.hacc_detail not like '%' +	@DescFrom + '%')
					)

			--AND		hat.hacc_transaction IN (SELECT tatd.hacc_transaction
		 --  									 FROM tbAccountTransactionDetail						tatd		WITH (NOLOCK)
		 --  									 WHERE	hat.comp_id				= @comp_id				AND
		 --  											hat.hacc_transaction	= hat.hacc_transaction	AND
		 --  											tatd.ct_transaction		= @ct_transaction	)
	--		AND		EXISTS (SELECT 1
	--		   		        FROM tbAccountTransactionDetail								tatd
	--		   		        WHERE	hat.comp_id				= @comp_id					AND
	--								hat.hacc_transaction	= hat.hacc_transaction		AND
	--								tatd.ct_transaction		= @ct_transaction)

		END

	ELSE

		BEGIN

			select	' ' [ ], ' ' [ ],
					hat.comp_id,
					hat.bra_id,
					hat.hacc_group,
					hat.hacc_date,
					hat.hacc_number,
					hat.hacc_orderPriority,
					hat.hacc_cd,
					hat.ap_id,
					ap.ap_desc,
					hat.hacc_blocked,
					hat.hacc_closing,
					hat.hacc_opening,
					hat.hacc_IsEditing,
					hat.hacc_IsEditingDateTime,
					hat.hacc_detail,
					ISNULL(tu.user_lastname,'') + ', ' + ISNULL(tu.user_firstname,'')		[userName],
					hat.hacc_lastUpdate,
					hat.hacc_transaction [ID]

			FROM 	dbo.tbAccountTransactionHead				hat		WITH(NOLOCK)

					left JOIN dbo.tbAccountantPeriod			ap		WITH(NOLOCK)
					ON  ap.comp_id		= hat.comp_id
					AND ap.ap_id		= hat.ap_id

					INNER JOIN tbUsers4BranchFilter				vubf	WITH(NOLOCK)
					ON	vubf.comp_id	= hat.comp_id
					AND vubf.bra_id		= hat.bra_id
					AND vubf.[user_id]	= @user_id

					LEFT JOIN tbUser							tu		WITH (NOLOCK)
						ON tu.[user_id] = hat.[user_id]

			WHERE	hat.comp_id			= @comp_id
			AND		hat.ap_id			= @ap_id
			AND		hat.hacc_date		between @datefrom and @dateto
			AND     hat.ag_id			= @ag_id
			AND 	(
						(@option = -1)														OR
						(@option = 0 and hat.hacc_number like			@NumberFrom + '%')	OR
						(@option = 1 and hat.hacc_number like '%' +		@NumberFrom + '%')	OR
						(@option = 2 and hat.hacc_number =				@NumberFrom)		OR
						(@option = 3 and hat.hacc_number <>				@NumberFrom)		OR
						(@option = 4 and hat.hacc_number not like '%' +	@NumberFrom + '%')
					)
			AND 	(
						(@option_number_original = -1)														OR
						(@option_number_original = 0 and hat.hacc_originalNumber like			@NumberFromOriginal + '%')	OR
						(@option_number_original = 1 and hat.hacc_originalNumber like '%' +		@NumberFromOriginal + '%')	OR
						(@option_number_original = 2 and hat.hacc_originalNumber =				@NumberFromOriginal)		OR
						(@option_number_original = 3 and hat.hacc_originalNumber <>				@NumberFromOriginal)		OR
						(@option_number_original = 4 and hat.hacc_originalNumber not like '%' +	@NumberFromOriginal + '%')
					)
			AND 	(
						(@optionDesc = -1)													OR
						(@optionDesc = 0 and hat.hacc_detail like			@DescFrom + '%')OR
						(@optionDesc = 1 and hat.hacc_detail like '%' +		@DescFrom + '%')OR
						(@optionDesc = 2 and hat.hacc_detail =				@DescFrom)		OR
						(@optionDesc = 3 and hat.hacc_detail <>				@DescFrom)		OR
						(@optionDesc = 4 and hat.hacc_detail not like '%' +	@DescFrom + '%')
				)
			AND
			CASE
				WHEN @acc_count_id = -1 THEN 1
				WHEN EXISTS(
								SELECT TOP 1  1
									FROM tbAccountTransactionDetail tatd	WITH (NOLOCK)
									WHERE	tatd.comp_id			= hat.comp_id			AND
											tatd.hacc_transaction	= hat.hacc_transaction	AND
											tatd.acc_count_id		= @acc_count_id
							)
										THEN 1
				ELSE 0
			END	= 1

		END




END
GO













