-- =================================================================
-- Author:		MOH
-- Modif:		MOS  29-2-08
-- Description:	Trae Valores por ID de conf. del sistema
-- Si no encuentra el dato por compañia y por sucursal
-- lo busca solo por compañia y sucursal 1
-- la cual estara cargada por script inicial del sistema
-- Como  lo pide por rango, tiene que respetar esto ultimo
-- =================================================================

CREATE  PROCEDURE [dbo].[spAccountTransactionHead_insertData]
(
	@comp_id						INT,
	@bra_id							INT,
	@hacc_group						INT,
	@hacc_detail					VARCHAR(60),
	@hacc_date						DATETIME,
	@hacc_number					INT,
	@hacc_orderPriority				DECIMAL (5,0),
	@ap_id							INT,
	@hacc_blocked					BIT,
	@hacc_closing					BIT,
	@hacc_opening					BIT,
	@hacc_IsEditing					BIT,
	@hacc_IsEditingDateTime			DATETIME,
	@hacc_2ndCurrencyExchange		DECIMAL(19,6),
	@return_value					INT OUTPUT
)
as
SET NOCOUNT ON


declare @datetime	datetime
select	@datetime = getdate()


	-- Obtiene el Grupo Contable.-
	DECLARE @ag_id AS INT
	SELECT  @ag_id = ag_id
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id


insert into dbo.tbAccountTransactionHead
(
	comp_id,
	bra_id,
	hacc_group,
	hacc_detail,
	hacc_date,
	hacc_number,
	hacc_orderPriority,
	hacc_cd,
	ap_id,
	hacc_blocked,
	hacc_closing,
	hacc_opening,
	hacc_IsEditing,
	hacc_IsEditingDateTime,
	hacc_2ndCurrencyExchange,
	ag_id
)
values
(
	@comp_id,
	@bra_id,
	@hacc_group,
	@hacc_detail,
	@hacc_date,
	@hacc_number,
	@hacc_orderPriority,
	getdate(),
	@ap_id,
	@hacc_blocked,
	@hacc_closing,
	@hacc_opening,
	@hacc_IsEditing,
	@hacc_IsEditingDateTime,
	@hacc_2ndCurrencyExchange,
	@ag_id
)


set	@return_value = @@identity







GO






