	tatht.hacc_cd,
	tatht.hacc_blocked,
	tatht.hacc_IsEditing,
	tatht.hacc_IsEditingDateTime,
	tatht.hacc_2ndCurrencyExchange,
	tatht.ag_id,
	tatht.guid

from tbAccountTransactionHead_Type tatht

where	hacc_transaction = @hacc_transaction











GO





