-- para el libro de iva digital poder hacer una verificacion de los comprobantes que tienen en el sistema cargados y ver si estan todos en afip


CREATE PROCEDURE [dbo].[spAFIPVerifications_getDataByFilters]
(



	@comp_id							INT,
	@lang_id							INT,
	@bra_id								INT,
	@prof_id							INT,
	@user_id							INT,
	@GuidSupp							VARCHAR(50),
	@datefrom							DATETIME,
	@dateto								DATETIME,
	@cuit								VARCHAR(50),
	@option_afipverifications			INT,							-- -1 Todos; 1 Pendientes de Verificar; 2 Verificación ERRONEA; 3 Verificación OK
	@taxdatefrom						DATETIME,
	@taxdateto							DATETIME,
	@AFIPRegistrationDatefrom			DATETIME,
	@AFIPRegistrationDateto				DATETIME

)


AS

BEGIN


	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

-- --------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------
/*
	DECLARE
		@comp_id							INT,
		@lang_id							INT,
		@bra_id								INT,
		@prof_id							INT,
		@user_id							INT,
		@GuidSupp							VARCHAR(50),
		@datefrom							DATETIME,
		@dateto								DATETIME,
		@cuit								VARCHAR(50),
		@option_afipverifications			INT


	SELECT
			@GuidSupp   = '99d5f869-94e9-41b4-9700-ff1182bcad49',
			@datefrom  = '2020-07-01',
			@dateto	   = '2999-07-15',
			@cuit    = '',
			@option_afipverifications = -1
*/
-- --------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')




	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Suppliers TABLE (supp_id INT NULL UNIQUE CLUSTERED)
	INSERT INTO @tblComplexFilter_Suppliers
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf	WITH (NOLOCK)
			WHERE	tcf.sl_guid		= @GuidSupp     AND
					tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Suppliers(supp_id)
				SELECT supp_id
				FROM tbSupplier AS ti	WITH (NOLOCK)
					WHERE ti.comp_id = @comp_id
		END

	-- -------------------------------------------------------------



	-- --------------------------------------------------------------------
	-- Inserta en la tabla las transacciones correspondientes al numero
	-- de serie informado.
	---- --------------------------------------------------------------------
	--DECLARE @tblcuit TABLE (ct_transaction int)
	--IF @cuit <> ''
	--	BEGIN
	--		INSERT INTO @tblCuit (ct_transaction)
	--			SELECT	tis.ct_transaction,
	--					tis.it_transaction
	--				FROM	tbItemSerials tis				WITH (NOLOCK)
	--				WHERE	tis.comp_id		= @comp_id
	--				AND		tis.is_serial	= @cuit
	--	END
	-- --------------------------------------------------------------------


	SELECT
			'' [1], -- Respuesta de AFIP
			'' [2], -- wfmcommercialtransactions de Proveedores
			'' [3], -- gray

			tct.ct_date																					[ct_date],					-- Fecha Comprobante
			tct.ct_taxDate																				[ct_taxDate],				-- Fecha Contable
			ts.supp_name																				[supp_name],				-- Proveedor
			ts.supp_taxNumber																			[supp_taxNumber],			-- CUIT del Proveedor
			tct.ct_total																				[ct_total],
			ta.ctv_AFIPRegistrationDate																	[ctv_AFIPRegistrationDate],
			--dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction)			[Comprobante],
			tct.ct_transaction																			[ID]

	FROM	tbCommercialTransactions								tct					WITH (NOLOCK)

			INNER JOIN tbBranch									 AS tb					WITH (NOLOCK)
				ON	tb.comp_id			= tct.comp_id AND
					tb.bra_id			= tct.bra_id

			INNER JOIN @tblComplexFilter_Suppliers					ttmp
				ON ttmp.supp_id			= tct.supp_id

			INNER JOIN tbSupplier									ts				WITH (NOLOCK)
				ON  ts.comp_id			= tct.comp_id
				AND ts.supp_id			= tct.supp_id

			LEFT JOIN tbAFIPVerifications							ta					WITH (NOLOCK)
				ON  ta.comp_id			= tct.comp_id  AND
					ta.ct_transaction	= tct.ct_transaction


	WHERE		tct.comp_id		= @comp_id
	AND			tct.ct_date		between  @datefrom	and @dateto
	AND			tct.ct_taxDate		between  @taxdatefrom	and @taxdateto
	AND			ta.ctv_AFIPRegistrationDate between  @AFIPRegistrationDatefrom	and @AFIPRegistrationDateto
	AND			(@CUIT	= ''    or ts.supp_taxNumber		= @CUIT)
	AND CASE
			WHEN @option_afipverifications = -1																												THEN 'True'
			WHEN @option_afipverifications =  1 AND isnull(ta.ctv_isVerified,'False')		= 'False'														THEN 'True'		--Pendientes de Verificar
			WHEN @option_afipverifications =  2 AND isnull(ta.ctv_isWithError,'False')		= 'True'														THEN 'True'		-- Erronea
			WHEN @option_afipverifications =  3 AND isnull(ta.ctv_isVerified,'False')		= 'True' AND  isnull(ta.ctv_isWithError,'False')   = 'False'	THEN 'True'		-- OK
			ELSE 'False'
		END	= 'True'
	AND tb.df_id4AFIPConstatacionDeComprobantes IS NOT NULL
	AND tct.sd_id IN (101,103,104)  -- Fc, Nd, Nc x ahora



END
GO












create PROCEDURE [dbo].[spAFIPVerifications_getDataById]
(
	@comp_id				int,
	@bra_id					int,
	@ct_transaction			int
)
as

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on

	/*
		DECLARE 	@comp_id				int,
					@bra_id					int,
					@ct_transaction			int

		SELECT 		@comp_id				=1,
					@bra_id					=1,
					@ct_transaction			=1048
	*/


	SELECT
		ta.ct_transaction,
		ta.ctv_verificationDate,
		ta.ctv_isVerified,
		ta.ctv_isWithError,
		ISNULL(ta.ctv_responseFromAFIP,'')						[ctv_responseFromAFIP],
		ta.ctv_AFIPRegistrationDate

		FROM tbCommercialTransactions									AS tct

		INNER JOIN tbAFIPVerifications									AS ta
		ON	ta.comp_id			= tct.comp_id			 AND
			ta.ct_transaction	= tct.ct_transaction

		Where
			ta.comp_id			=		@comp_id
		AND	ta.ct_transaction	=		@ct_transaction





END
GO


-- Date 03/08/2020
-- para el libro de iva digital poder hacer una verificacion de los comprobantes que tienen en el sistema cargados y ver si estan todos en afip

-- EWl SP de Verificacion se llama: spCommercialTransactions_AFIPPurchasesConciliation_VerificationProcess.  Deberia estar ACA y no con ese nombre !!!

CREATE PROCEDURE [dbo].[spAFIPVerifications_getDataPending2Verify]
AS

BEGIN


	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

-- --------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------
/*
	DECLARE
		@comp_id							INT,
		@lang_id							INT,
		@bra_id								INT,
		@prof_id							INT,
		@user_id							INT,
		@GuidSupp							VARCHAR(50),
		@datefrom							DATETIME,
		@dateto								DATETIME,
		@cuit								VARCHAR(50),
		@option_afipverifications			INT


	SELECT
			@GuidSupp   = '99d5f869-94e9-41b4-9700-ff1182bcad49',
			@datefrom  = '2020-07-01',
			@dateto	   = '2999-07-15',
			@cuit    = '',
			@option_afipverifications = -1
*/
-- --------------------------------------------------------------------


	SELECT	ta.comp_id,
			ta.ct_transaction,
			ta.[user_id],
			ta.ctv_verificationDate,
			ta.ctv_isVerified,
			ta.ctv_isWithError,
			ta.ctv_responseFromAFIP,
			ta.ctv_AFIPRegistrationDate,
			tb.df_id4AFIPConstatacionDeComprobantes,
			tct.ct_date,
			tct.ct_docNumber,
			CASE

				-- Facturas
				WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'A' THEN '001'
				WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'B' THEN '006'
				WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'C' THEN '011'
				WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'M' THEN '051'
				WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'E' THEN '019'		-- ERROR


				-- Notas de Credito
				WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'A' THEN '003'
				WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'B' THEN '008'
				WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'C' THEN '013'
				WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'M' THEN '053'
				WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'E' THEN '021'		-- ERROR

				-- Notas de Debito
				WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'A' THEN '002'
				WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'B' THEN '007'
				WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'C' THEN '012'
				WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'M' THEN '052'
				WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'E' THEN '020'

				-- Liquido Producto
				WHEN tct.sd_id = 131 AND tct.ct_kindOf = 'A' THEN '060'
				WHEN tct.sd_id = 131 AND tct.ct_kindOf = 'B' THEN '061'
				WHEN tct.sd_id = 131 AND tct.ct_kindOf = 'M' THEN '058'

				-- Despacho de Importacion
				WHEN tct.sd_id = 130						 THEN '066'


				-- Liquidación de Tarjetas de Crédito
				WHEN tct.sd_id = 142						 THEN '099'
				WHEN tct.sd_id = 141						 THEN '099'
				WHEN tct.sd_id = 140						 THEN '099'
				ELSE											'000'
			END																[CbteTipo],
			tct.ct_CAI,
			ttnt.tnt_afip,
			ts.supp_taxNumber,
			teip.p12_cuit,
			tct.ct_total,
			tct.ct_pointOfSale,
			tct.bra_id
		FROM tbAFIPVerifications			AS ta	WITH (NOLOCK)
		INNER JOIN tbCommercialTransactions AS tct	WITH (NOLOCK)
			ON	tct.comp_id			= ta.comp_id AND
				tct.ct_transaction	= ta.ct_transaction
		INNER JOIN tbBranch					AS tb	WITH (NOLOCK)
			ON	tb.comp_id			= tct.comp_id AND
				tb.bra_id			= tct.bra_id
		INNER JOIN tbDocumentsFile			AS tdf	WITH (NOLOCK)
			ON	tdf.comp_id			= tb.comp_id	AND
				tdf.bra_id			= tb.bra_id		AND
				tdf.df_id			= tb.df_id4AFIPConstatacionDeComprobantes
		INNER JOIN tbElectronicInvoice_P12Files AS teip	WITH (NOLOCK)
			ON	teip.p12_id			= tdf.p12_id AND
				teip.comp_id		= tdf.comp_id
		INNER JOIN tbsysDocuments			AS td	WITH (NOLOCK)
			ON td.sd_id				= tct.sd_id
		INNER JOIN tbSupplier				AS ts	WITH (NOLOCK)
			ON	ts.comp_id			= tct.comp_id AND
				ts.supp_id			= tct.supp_id
		INNER JOIN tbsysTaxNumberTypes AS ttnt
			ON	ttnt.tnt_id			= ts.tnt_id
		WHERE	ta.ctv_isVerified		= 'False'	AND
				tb.df_id4AFIPConstatacionDeComprobantes IS NOT NULL

END
GO





