CREATE PROCEDURE [dbo].[spAFIPVerifications_InsertData]
(

			@comp_id							INT,
			@lang_id							INT,
			@bra_id								INT,
			@prof_id							INT,
			@user_id							INT,

			@ct_transaction						INT

)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE	  	@comp_id							INT,
				@lang_id							INT,
				@bra_id								INT,
				@prof_id							INT,
				@user_id							INT,


	SELECT		 @comp_id						= 1,
				 @bra_id						= 1

*/
-- ------------------------------------------------------



	IF NOT EXISTS ( SELECT TOP 1 taf.ct_transaction
	                FROM tbAFIPVerifications taf
					WHERE	taf.comp_id					= @comp_id AND
							taf.ct_transaction			= @ct_transaction
					)
		BEGIN

			INSERT INTO tbAFIPVerifications
			(
				comp_id,
				ct_transaction,
				[user_id],
				ctv_verificationDate,
				ctv_isVerified,
				ctv_isWithError,
				ctv_responseFromAFIP,
				ctv_AFIPRegistrationDate
			)
			VALUES
			(

				@comp_id,
				@ct_transaction,
				@user_id,
				GETDATE(),
				0,
				0,
				'',
				GETDATE()
			)




		END


END
GO

