CREATE PROCEDURE spAFIPVerifications_updateStatus
	@comp_id					AS INT,
	@ct_transaction				AS INT ,
	@ctv_isVerified				AS BIT,
	@ctv_isWithError			AS BIT,
	@ctv_responseFromAFIP		AS NVARCHAR(MAX),
	@ctv_AFIPRegistrationDate	AS DATETIME



AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	UPDATE tbAFIPVerifications	WITH (ROWLOCK)
		SET ctv_isVerified				= @ctv_isVerified,
			ctv_isWithError				= @ctv_isWithError,
			ctv_responseFromAFIP		= @ctv_responseFromAFIP,
			ctv_AFIPRegistrationDate	= @ctv_AFIPRegistrationDate
		WHERE	comp_id			= @comp_id			AND
				ct_transaction	= @ct_transaction

END
GO







CREATE PROCEDURE [dbo].[spApplication_deleteAllData]
(
	@ispurchase			BIT,
	@custsupp_id		INT

)
AS
SET NOCOUNT ON


/*
DECLARE @custsupp_id INT, @ispurchase BIT
SELECT @custsupp_id = 21, @ispurchase = 'true'
*/


BEGIN TRANSACTION
BEGIN TRY


		--se ponen todos los ct_ABalance con el valor del ct_ATotal de los comprobantes que se tomana en cuenta en la
		--cuenta corriente y se eliminan todas las aplicaciones para poder volver a realizar la aplicación

		IF @ispurchase = 'true' --compras
			BEGIN

				UPDATE	tbCommercialTransactions
				SET		ct_ABalance = (ct_ATotal - ct_aadjust)
				WHERE	supp_id = @custsupp_id
				AND		sd_id IN (SELECT sd_id FROM tbsysDocuments td WHERE td.sd_isInBalance = 'true' AND sd_id < 150)


				DELETE FROM tbApplication
				WHERE	ct_transaction_Source	IN (SELECT tct.ct_transaction
													FROM tbCommercialTransactions tct WHERE tct.supp_id = @custsupp_id) OR
						ct_transaction_destiny	IN (SELECT tct.ct_transaction
													FROM tbCommercialTransactions tct WHERE tct.supp_id = @custsupp_id)
			END
		ELSE				--ventas
			BEGIN

				UPDATE	tbCommercialTransactions
				SET		ct_ABalance = (ct_ATotal - ct_aadjust)
				WHERE	cust_id = @custsupp_id
				AND		sd_id IN (SELECT sd_id FROM tbsysDocuments td WHERE td.sd_isInBalance = 'true' AND sd_id < 50)



				DELETE FROM tbApplication
				WHERE	ct_transaction_Source	IN (SELECT tct.ct_transaction
													FROM tbCommercialTransactions tct WHERE tct.cust_id = @custsupp_id) OR
						ct_transaction_destiny	IN (SELECT tct.ct_transaction
													FROM tbCommercialTransactions tct WHERE tct.cust_id = @custsupp_id)
			END



	COMMIT TRANSACTION


END
TRY BEGIN CATCH

	ROLLBACK TRANSACTION

END CATCH
GO











CREATE PROCEDURE [dbo].[spApplication_getData]
(
	@comp_id				int,
	@lang_id				int,
	@bra_id					int,
	@ct_transaction			int
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	set nocount ON

	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-11-12
	-- Parte		: s/P referencia: #1
	-- Se quita una condición de inner join para que traiga comprobantes de diferentes sucursales
	-- =================================================================================================================


	/*
	DECLARE 	@comp_id				int,
				@lang_id				int,
				@bra_id					int,
				@ct_transaction			int

	SELECT 		@comp_id				=1,
				@lang_id				=2,
				@bra_id					=1,
				@ct_transaction			=5493
	*/

	--SELECT * FROM tbsysDocuments td


	if exists (select 1 from dbo.[tbApplication] where [ct_transaction_Source] = @ct_transaction)

		begin

			Select		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ap.[ct_transaction_Destiny]) +
						CASE
							WHEN tctl.comp_id IS NULL THEN ''
							ELSE						   ' ' + CONVERT(NVARCHAR(10),tctl.ctl_payNumber) + '/' + CONVERT(NVARCHAR(10),tctl.ctl_payNumberTotalQty)
						END		+
						CASE
							WHEN tctl2.comp_id IS NULL THEN ''
							ELSE						   ' ' + CONVERT(NVARCHAR(10),tctl2.ctl_payNumber) + '/' + CONVERT(NVARCHAR(10),tctl2.ctl_payNumberTotalQty)
						END
													 [doc_number],
						ct.[ct_date],
						ap.[appl_total],
						ap.[appl_coef],
						sc.[curr_symbol],
						ap.appl_excdifchecked,
						ap.[ct_transaction_Destiny]		[ID]

			From		 tbApplication									ap

						inner join dbo.tbCommercialTransactions			ct
						on		ap.[comp_id]				= ct.[comp_id]
						--and		ap.[bra_id]					= ct.[bra_id]	-- Parte		: s/P referencia: #1
						and		ap.[ct_transaction_Destiny]	= ct.[ct_transaction]

						inner join dbo.[tbsysCurrency]					sc
						on	    sc.[curr_id]		=		ap.[appl_currency]

						LEFT JOIN tbCommercialTransactionsLoan tctl
							ON	tctl.comp_id		= ap.comp_id AND
								tctl.ct_transaction = ap.ct_transaction_source AND
								tctl.ctl_id			= ap.ctl_id_source

						LEFT JOIN tbCommercialTransactionsLoan tctl2
							ON	tctl2.comp_id		= ap.comp_id AND
								tctl2.ct_transaction= ap.ct_transaction_destiny AND
								tctl2.ctl_id		= ap.ctl_id_destiny

			Where		ap.comp_id					=		@comp_id
			--AND			ap.bra_id 					=		@bra_id
			AND			ap.[ct_transaction_Source]	=		@ct_transaction


			order by ct.[ct_date], [ID]

		end

	else

		begin

			Select		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ap.[ct_transaction_source]) [doc_number],
						ct.[ct_date],
						ap.[appl_total],
						ap.[appl_coef_] [appl_coef],
						sc.[curr_symbol],
						ap.appl_excdifchecked,
						ap.[ct_transaction_source]	[ID]

			From		 tbApplication			ap

						inner join dbo.tbCommercialTransactions		ct
						on		ap.[comp_id]				= ct.[comp_id]
						--and		ap.[bra_id]					= ct.[bra_id]	-- Parte		: s/P referencia: #1
						and		ap.[ct_transaction_Source]	= ct.[ct_transaction]

						inner join dbo.[tbsysCurrency]					sc
						on	    sc.[curr_id]		=		ap.[appl_currency]

			Where		ap.comp_id					=		@comp_id
			--AND			ap.bra_id 					=		@bra_id
			AND			ap.[ct_transaction_Destiny]	=		@ct_transaction


			order by ct.[ct_date], [ID]

		end

END
GO












CREATE PROCEDURE [dbo].[spApplication_getDataById]
(
	@comp_id				int,
	@bra_id					int,
	@ct_transaction			int
)
as

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on

	/*
		DECLARE 	@comp_id				int,
					@bra_id					int,
					@ct_transaction			int

		SELECT 		@comp_id				=1,
					@bra_id					=1,
					@ct_transaction			=1048
	*/



	Select		ap.[appl_id],
				ap.[appl_total],
				ap.[appl_coef],
				ap.[appl_coef_],
				ap.appl_excdifchecked

	From		dbo.tbCommercialTransactions		ct

				/*INNER JOIN [tbsysTransactionType]	tt
				ON tt.[tt_id]		= ct.[tt_id]*/
				inner join dbo.[tbsysDocuments]		sd
				on	sd.[sd_id]		=	ct.[sd_id]

				INNER JOIN dbo.tbApplication		ap
				ON ap.[comp_id]		= ct.[comp_id]
				AND ap.[bra_id]		= ct.[bra_id]

	Where		ct.comp_id				=		@comp_id
	AND			ct.bra_id 				=		@bra_id
	AND			ct.ct_transaction		=		@ct_transaction

	/*AND			((tt.[tt_DebitOrCredit] = 'false' AND ap.[ct_transaction_destiny] = ct.[ct_transaction]) OR
				 (tt.[tt_DebitOrCredit] = 'true'  AND ap.[ct_transaction_Source]  = ct.[ct_transaction]))*/
	and			((sd.[sd_isCredit] = 'true' AND ap.[ct_transaction_destiny] = ct.[ct_transaction]) OR
				 (sd.[sd_isCredit] = 'false'  AND ap.[ct_transaction_Source]  = ct.[ct_transaction]))









END
GO







CREATE PROCEDURE [dbo].[spApplication_insertData]
(
	@comp_id						int,
	@bra_id							int,
	@ct_transaction_source			int,
	@ct_transaction_destiny			int,
	@appl_currency					int,
	@appl_total						decimal(30,12),
	@appl_coef						decimal(30,18),
	@appl_coef_						decimal(30,18),
	@appl_excdifchecked				BIT,
	@ct_transaction					INT,
	@intCTL_IdSource				INT,
	@intCTL_IdDestiny				INT
)
as

BEGIN

	-- Si viene de una APLICACION
	IF @ct_transaction <= 0 SET @ct_transaction = NULL


	set nocount on

	/*
	DECLARE 	@comp_id					int,
				@bra_id						int,
				@ct_transaction_source		int,
				@ct_transaction_destiny		int,
				@appl_currency				int,
				@appl_total					decimal(19,6),
				@appl_coef					decimal(19,6)

	SELECT 		@comp_id					=1,
				@bra_id						=1,
				@ct_transaction				=20
	*/




	insert into dbo.tbApplication	 WITH (ROWLOCK)
	(
		comp_id,
		bra_id,
		ct_transaction_Source,
		ct_transaction_destiny,
		appl_currency,
		appl_total,
		appl_coef,
		appl_coef_,
		appl_excdifchecked,
		ct_transaction,
		ctl_id_Source,
		ctl_id_Destiny,
		appl_cd
	)
	values
	(
		@comp_id,
		@bra_id,
		@ct_transaction_Source,
		@ct_transaction_destiny,
		@appl_currency,
		@appl_total,
		@appl_coef,
		@appl_coef_,
		@appl_excdifchecked,
		@ct_transaction,
		@intCTL_IdSource,
		@intCTL_IdDestiny,
		GETDATE()
	)


END
GO



