CREATE PROCEDURE [dbo].[spAssembly_Turns4Assembly_AssignUser2Assembly]
(
	@comp_id		INT,
	@lang_id		INT,
	@ta_id			INT,
	@user_id		INT,
	@note			VARCHAR(4000),
	@date			DATETIME,
	@user_id2		INT,
	@user_id3		INT,
	@user_id4		INT,
	@user_id5		INT,
	@assemblyDate	DATETIME,
	@tar_id			INT
)
AS

	SET NOCOUNT ON


		BEGIN

--			DECLARE
--				@comp_id	INT,
--				@lang_id	INT,
--				@ta_id		INT,
--				@user_id	INT
--			SELECT
--				@comp_id	= 1,
--				@lang_id	= 2,
--				@ta_id		= 3,
--				@user_id	= 119




			UPDATE tbAssembly_Turns4Assembly
			SET
				user_id_Assigned4Assembly	= @user_id,
				ta_note						= @note,
				ta_date4begin				= @date,


				user_id_Assigned4Assembly2	= CASE @user_id2 WHEN -1 THEN NULL ELSE @user_id2 END,
				user_id_Assigned4Assembly3	= CASE @user_id3 WHEN -1 THEN NULL ELSE @user_id3 END,
				user_id_Assigned4Assembly4	= CASE @user_id4 WHEN -1 THEN NULL ELSE @user_id4 END,
				user_id_Assigned4Assembly5	= CASE @user_id5 WHEN -1 THEN NULL ELSE @user_id5 END,
				ta_date4Assembly			= @assemblyDate,
				tar_id						= @tar_id



			WHERE	comp_id = @comp_id AND
					ta_id	= @ta_id


			DECLARE
				@item_id	INT,
				@item_desc	VARCHAR(1000),
				@date4assem	DATETIME,
				@Type		INT

			SELECT
				@item_id	= tata.item_id,
				@Type		= ti.item_assemblyType,
				@item_desc	= ti.item_desc,
				@date4assem	= tata.ta_date4Assembly

			FROM tbAssembly_Turns4Assembly			tata
				INNER JOIN tbItem					ti
				ON	ti.comp_id		= tata.comp_id	AND
					ti.item_id		= tata.item_id
			WHERE	tata.comp_id	= @comp_id		AND
					tata.ta_id		= @ta_id


			--ACA VAMOS A MANDAR UN MAIL AL USUARIO QUE DEBE ENSAMBLARLO CON LA INFORMACIÓN!
			--ENVIAMOS EL MAIL CON LA INFORMACIÓN
				DECLARE
					@subject	VARCHAR(200),
					@Recipients	varchar(MAX),
					@MailBody	VARCHAR(500),
					@str1		VARCHAR(100),
					@str2		VARCHAR(100),
					@str3		VARCHAR(100)


			SELECT
				@Recipients = tu.user_email
			FROM tbUser tu
			WHERE tu.[user_id] = @user_id



			--SUBJECT
					SELECT
						@subject = tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE	tut.lang_id		= @lang_id AND
							tut.utexts_id	= 30618


					-- ----------------------------------------------------------
					-- BODY DEL MAIL
					-- ----------------------------------------------------------
					SELECT
						@str1 = tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30614

					SELECT
						@str2 = tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30615

					IF @Type = 2
						SELECT
							@str3 = tut.utexts_desc
						FROM tbsysUniqueTexts tut
						WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30616
					ELSE
						IF @Type = 1
							SELECT
								@str3 = tut.utexts_desc
							FROM tbsysUniqueTexts tut
							WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30617

					-- -----------------------------------------------------------

					SET @MailBody = @str1 + ' ' + @item_desc + ' ,' + @str2 + ' ' + CONVERT(VARCHAR,@date4assem) + ' ' + @str3

					--SELECT @MailBody, @str1, @str2, @str3, @item_desc, @date4assem, @Type, @Recipients


			EXEC spSystem_sendEMail
							@compId				= @comp_id,
							@precipients		= @Recipients,
							@pcopy_recipients	= '',
							@psubject			= @subject,
							@pbody_format		= 'HTML',
							@pbody				= @MailBody,
							@pfile_attachments	= NULL,
							@pReplyTo			= NULL,
							@pblind_copy_recipients='',
							@pUser_Id			= @user_id

		END

GO




