CREATE PROCEDURE [dbo].[spAssembly_Turns4Assembly_CheckOrUncheck]
(
	@comp_id	INT,
	@ta_id		INT,
	@guid		UNIQUEIDENTIFIER
)
AS
	SET NOCOUNT ON

		BEGIN

			-- -------------------------------------------------------------
			-- TESTING
			-- -------------------------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@ta_id		INT,
					@guid		UNIQUEIDENTIFIER
				SELECT
					@comp_id	= 1,
					@ta_id		= 1,
					@guid		= '25892e17-80f6-415f-9c65-7395632f0223'
			*/
			-- -------------------------------------------------------------

			IF NOT EXISTS (SELECT 1 FROM tbAssembly_Turns4Assembly tata WHERE tata.comp_id = @comp_id AND tata.ta_id = @ta_id AND tata.tar_guid4Selection = @guid)

				BEGIN
					--SI NO EXISTE, LE PONE EL GUID
					UPDATE tbAssembly_Turns4Assembly
					SET
						tar_guid4Selection = @guid
					WHERE	comp_id = @comp_id AND
							ta_id	= @ta_id

				END
			ELSE
				BEGIN
					--SI EXISTE, SE LO SACA
					UPDATE tbAssembly_Turns4Assembly
					SET
						tar_guid4Selection = NULL
					WHERE	comp_id = @comp_id AND
							ta_id	= @ta_id

				END



		END


GO

