CREATE PROCEDURE [dbo].[spAssembly_Turns4Assembly_GetDataByFilters]
(
	@comp_id					INT,
	@lang_id					INT,
	@tar_id						INT,
	--@user_id_cd				INT,
	@user_id_Supervisor			INT,
	@user_id_Assigned4Assembly	INT,
	@date4BeginFrom				DATETIME,
	@date4BeginTo				DATETIME,
	@date4EndFrom				DATETIME,
	@date4EndTo					DATETIME,
	@dateAssemblyFrom			DATETIME,
	@dateAssemblyTo				DATETIME,
	@dateCanceledFrom			DATETIME,
	@dateCanceledTo				DATETIME,
	@status						INT,
	@assembly_type				INT,
	@guid						UNIQUEIDENTIFIER,
	@docNumber					INT,
	@item_id					INT
)
AS

BEGIN

	SET DATEFORMAT 'YMD'

	SET NOCOUNT ON



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- ---------------------------------------
	-- Testing
	-- ---------------------------------------
	/*
		DECLARE
			@comp_id					INT,
			@lang_id					INT,
			@tar_id						INT,
			--@user_id_cd				INT,
			@user_id_Supervisor			INT,
			@user_id_Assigned4Assembly	INT,
			@date4BeginFrom				DATETIME,
			@date4BeginTo				DATETIME,
			@date4EndFrom				DATETIME,
			@date4EndTo					DATETIME,
			@dateAssemblyFrom			DATETIME,
			@dateAssemblyTo				DATETIME,
			@dateCanceledFrom			DATETIME,
			@dateCanceledTo				DATETIME,
			@status						INT,
			@assembly_type				INT,
			@guid						UNIQUEIDENTIFIER,
			@docNumber					INT,
			@item_id					INT

		SELECT
			@comp_id					= 1,
			@lang_id					= 2,
			@tar_id						= 5,
			--@user_id_cd				= -1,
			@user_id_Supervisor			= -1,
			@user_id_Assigned4Assembly	= -1,
			@date4BeginFrom				= '2017-01-01',
			@date4BeginTo				= '2018-12-31',
			@date4EndFrom				= '2017-01-01',
			@date4EndTo					= '2018-12-31',
			@dateAssemblyFrom			= '2017-01-01',
			@dateAssemblyTo				= '2018-12-31',
			@dateCanceledFrom			= '2017-01-01',
			@dateCanceledTo				= '2018-12-31',
			@status						= -1,
			@assembly_type				= 1,
			@guid						= '25892e17-80f6-415f-9c65-7395632f0223',
			@docNumber					= 0,
			@item_id					= -1
	*/
	-- ---------------------------------------

	SELECT @date4BeginFrom		= dbo.fnGetEnd_or_BeginOfDate(@date4BeginFrom,'False')
	SELECT @date4BeginTo		= dbo.fnGetEnd_or_BeginOfDate(@date4BeginTo,'True')

	SELECT @date4EndFrom		= dbo.fnGetEnd_or_BeginOfDate(@date4EndFrom,'False')
	SELECT @date4EndTo			= dbo.fnGetEnd_or_BeginOfDate(@date4EndTo,'True')

	SELECT @dateAssemblyFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateAssemblyFrom,'False')
	SELECT @dateAssemblyTo		= dbo.fnGetEnd_or_BeginOfDate(@dateAssemblyTo,'True')

	SELECT @dateCanceledFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateCanceledFrom,'False')
	SELECT @dateCanceledTo		= dbo.fnGetEnd_or_BeginOfDate(@dateCanceledTo,'True')



	--select @date4BeginFrom,@date4BeginTo,@date4EndFrom,@date4EndTo,@dateAssemblyFrom,@dateAssemblyTo,@dateCanceledFrom,@dateCanceledTo



	SELECT
		' '									[ ],							--ASIGNAR USUARIO PARA ARMADO	(ASIGNA UN USUARIO DEL GRUPO QUE TIENE ASIGNADO EL TURNO)
		--' '								[ ],							--INICIO DE ARMADO
		' '									[ ],							--FIN DE ARMADO
		--' '								[ ],							--CANCELAR						(SOLO SI NO SE INICIO EL ARMADO NI SE FINALIZÓ, LIBERA AL USUARIO DEL ARMADO)
		ISNULL(tata.ta_isManual,'False')	[ ],							--BOTON PARA BORRAR SOLO SI ES TURNO MANUAL
		' '									[ ],							--BOTON PARA IMPRESION DEL REPORTE DE GARANTIA
		' '									[ ],							--MARCA O DESMARCA
		CASE  WHEN	(tata.tar_guid4Selection IS NOT NULL AND tata.tar_guid4Selection = @guid)
			THEN
				CONVERT(BIT,'True')
		ELSE
				CONVERT(BIT,'False')
		END														[Selected],
		tat.tar_desc,

		ISNULL(tc.cust_id,'')									[cust_id],
		ISNULL(tc.cust_name,'')									[cust_name],
		dbo.fnGetCommercialTransactionDescription(@comp_id,
												  @lang_id,
												  tct.ct_transaction)
																[Document],

		ti.item_code,
		ti.item_desc,
		ISNULL(tu.user_lastname + ',' + tu.user_firstname,'')	[user_id_cd],
		ISNULL(tu2.user_lastname + ',' + tu2.user_firstname,'')	[user_id_Supervisor],
		ISNULL(tu3.user_lastname + ',' + tu3.user_firstname,'')	[user_id_Assigned4Assembly],

		ISNULL(tu4.user_lastname + ',' + tu4.user_firstname,'')	[user_id_Assigned4Assembly2],

		ISNULL(tu5.user_lastname + ',' + tu5.user_firstname,'')	[user_id_Assigned4Assembly3],

		ISNULL(tu6.user_lastname + ',' + tu6.user_firstname,'')	[user_id_Assigned4Assembly4],

		ISNULL(tu7.user_lastname + ',' + tu7.user_firstname,'')	[user_id_Assigned4Assembly5],

		tata.ta_date4Assembly,
		ISNULL(tata.ta_date4begin,'')							[ta_date4begin],
		ISNULL(tata.ta_date4End,'')								[ta_date4End],
		ISNULL(tata.ta_assignedIndex,0)							[ta_assignedIndex], 	--STL 12-03-2020 a pedido de M.Toyos
		ISNULL(tata.ta_isAssembled,'False')						[ta_isAssembled],
		ISNULL(tata.ta_isCancelled,'False')						[ta_isCancelled],
		ISNULL(tata.ta_note,'')									[ta_note],
		CASE ISNULL(tata.ta_isManual, 'False') WHEN 'False'	THEN
				'Cargado por Ventas'
		ELSE
			    'Manual'
		END														[Type],


		-- ----------------------------------------------------------
		tc.cust_phone1,
		tc.cust_cellPhone,

		(SELECT TOP 1
			tsohh.soh_deliveryDate
		 FROM tbSaleOrderHeaderHistory				tsohh
		 WHERE	tsohh.comp_id	= tata.comp_id		AND
				tsohh.bra_id	= tata.bra_id		AND
				tsohh.soh_id	= tata.soh_id
			ORDER BY tsohh.sohh_id DESC
		)														[soh_deliveryDate],

		(
			SELECT TOP 1
				tsohh1.soh_deliveryAddress
			FROM tbSaleOrderHeaderHistory			tsohh1
			WHERE	tsohh1.comp_id	= tata.comp_id	AND
					tsohh1.bra_id	= tata.bra_id	AND
					tsohh1.soh_id	= tata.soh_id
				ORDER BY tsohh1.sohh_id DESC
		)														[soh_deliveryAddress],

		(
			SELECT TOP 1
				td.dl_name
				FROM tbSaleOrderHeaderHistory			 tsohh2
				INNER JOIN tbDelivery					 td
					ON	td.comp_id		= tsohh2.comp_id AND
						td.dl_id		= tsohh2.dl_id
				WHERE	tsohh2.comp_id	= tata.comp_id	 AND
						tsohh2.bra_id	= tata.bra_id	 AND
						tsohh2.soh_id	= tata.soh_id
				ORDER BY tsohh2.sohh_id DESC
		)														[dl_name],
		(
			SELECT TOP 1
				ts.stor_desc
				FROM tbSaleOrderHeaderHistory			tsohh3
				INNER JOIN tbSaleOrderDetailHistory		tsodh
					ON	tsodh.comp_id	= tsohh3.comp_id	AND
						tsodh.bra_id	= tsohh3.bra_id		AND
						tsodh.soh_id	= tsohh3.soh_id		AND
						tsodh.item_id	= tata.item_id
				INNER JOIN tbStorage					ts
					ON	ts.comp_id		= tsodh.comp_id		AND
						ts.stor_id		= tsodh.stor_id
				WHERE	tsohh3.comp_id	= tata.comp_id	AND
						tsohh3.bra_id	= tata.bra_id	AND
						tsohh3.soh_id	= tata.soh_id
				ORDER BY tsohh3.sohh_id DESC
		)														[stor_desc],
		(
			SELECT TOP 1
				tov.optval_desc
				FROM tbSaleOrderHeaderHistory			tsohh4
				INNER JOIN tbSaleOrderDetailHistory		tsodh2
					ON	tsodh2.comp_id	= tsohh4.comp_id	AND
						tsodh2.bra_id	= tsohh4.bra_id		AND
						tsodh2.soh_id	= tsohh4.soh_id		AND
						tsodh2.item_id	= tata.item_id
				INNER JOIN tbsysOptionsValues			tov
					ON	tov.lang_id		= @lang_id			AND
						tov.optval_class= 520				AND
						tov.optval_id	= tsodh2.sdlmt_id
				WHERE	tsohh4.comp_id	= tata.comp_id	AND
						tsohh4.bra_id	= tata.bra_id	AND
						tsohh4.soh_id	= tata.soh_id
				ORDER BY tsodh2.sohh_id DESC
		)														[DeliveryType],

		-- ----------------------------------------------------------


		tata.ta_id												[ID]

		FROM tbAssembly_Turns4Assembly					tata		WITH(NOLOCK)
			INNER JOIN tbAssembly_Team					tat			WITH(NOLOCK)
				ON	tat.comp_id			= tata.comp_id	AND
					tat.tar_id			= tata.tar_id
			INNER JOIN tbItem							ti			WITH(NOLOCK)
				ON  ti.comp_id			= tata.comp_id	AND
					ti.item_id			= tata.item_id
			--USUARIO CREADOR
			INNER JOIN tbUser							tu			WITH(NOLOCK)
				ON	tu.[user_id]		= tata.user_id_cd
			--USUARIO SUPERVISOR
			LEFT JOIN tbUser							tu2			WITH(NOLOCK)
				ON	tu2.[user_id]		= tata.user_id_Supervisor
			--USUARIO ENCARGADO DEL ARMADO
			LEFT JOIN tbUser							tu3			WITH(NOLOCK)
				ON	tu3.[user_id]		= tata.user_id_Assigned4Assembly
			LEFT JOIN tbUser							tu4			WITH(NOLOCK)
				ON	tu4.[user_id]		= tata.user_id_Assigned4Assembly2
			LEFT JOIN tbUser							tu5			WITH(NOLOCK)
				ON	tu5.[user_id]		= tata.user_id_Assigned4Assembly3
			LEFT JOIN tbUser							tu6			WITH(NOLOCK)
				ON	tu6.[user_id]		= tata.user_id_Assigned4Assembly4
			LEFT JOIN tbUser							tu7			WITH(NOLOCK)
				ON	tu7.[user_id]		= tata.user_id_Assigned4Assembly5


			LEFT JOIN tbCommercialTransactions			tct			WITH(NOLOCK)
				ON	tct.comp_id			= tata.comp_id AND
					tct.ct_transaction	= tata.ct_transaction

			LEFT JOIN tbCustomer						tc			WITH(NOLOCK)
				ON	tc.comp_id			= tct.comp_id	AND
					tc.cust_id			= tct.cust_id


		WHERE	tata.comp_id				= @comp_id																				AND
				(@tar_id					= -1	OR	tata.tar_id						= @tar_id)									AND
				(tata.ta_date4Assembly IS NULL	OR tata.ta_date4Assembly		BETWEEN @dateAssemblyFrom	AND @dateAssemblyTo)	AND
				(tata.ta_date4begin IS NULL		OR tata.ta_date4begin			BETWEEN @date4BeginFrom		AND @date4BeginTo)		AND
				(tata.ta_date4End IS NULL		OR tata.ta_date4End				BETWEEN @date4EndFrom		AND @date4EndTo)		AND
	--					(@user_id_cd				= -1	OR	tata.user_id_cd					= @user_id_cd)					AND
				(@user_id_Supervisor		= -1	OR	tata.user_id_Supervisor			= @user_id_Supervisor)						AND
				(@user_id_Assigned4Assembly	= -1	OR	tata.user_id_Assigned4Assembly	= @user_id_Assigned4Assembly)				AND
				(
					 @status				= -1													OR
					(@status				= 1 AND ISNULL(tata.ta_isAssembled,'False') = 'False')	OR
					(@status				= 2 AND tata.ta_date4End IS NOT NULL)					OR
					(@status				= 3 AND tata.ta_isCancelled = 'False')
				)																													AND
				tat.sreas_id				= @assembly_type																		AND
				--QUE SOLO APAREZCAN LOS TURNOS QUE TENGAN CARGADO UN CT_TRANSACTION (Pedido por Martín 06/07/2015)
				(
					tata.ct_transaction		IS NOT NULL	OR
					tata.ta_isManual		= 'True'
				)																													AND
				(@item_id					= -1	OR tata.item_id		= @item_id)													AND
				(@docNumber					= 0		OR tct.ct_docNumber = @docNumber)												AND
				(
					tct.sd_id					<> 3 --QUE NO MUESTRE TURNOS DE ARMADO DE NOTA DE CREDITO
					OR
					tata.ta_isManual = 'True'
				)


END
GO



CREATE PROCEDURE [dbo].[spAssembly_Turns4Assembly_GetDataById]
(
	@comp_id	INT,
	@ta_id		INT
)
AS
	SET NOCOUNT ON

		BEGIN

			DECLARE
				@tar_id		INT,
				@sreas_id	INT

			SELECT
				@tar_id		= tat.tar_id,
				@sreas_id	= tat.sreas_id
				FROM tbAssembly_Team					tat
				INNER JOIN tbAssembly_Turns4Assembly	tata
				ON	tata.comp_id	= tat.comp_id		AND
					tata.tar_id		= tat.tar_id
				WHERE	tat.comp_id		= @comp_id		AND
						tata.ta_id		= @ta_id

			SELECT
				tata.comp_id,
				tata.ta_id,
				tata.tar_id,
				tata.bra_id,
				tata.soh_id,
				tata.sod_id,
				tata.ct_transaction,
				tata.item_id,
				tata.ta_isAssembled,
				tata.ta_isCancelled,
				tata.ta_note,
				tata.ta_cd,
				tata.user_id_cd,
				tata.ta_date4Assembly,
				tata.user_id_Supervisor,
				tata.user_id_Assigned4Assembly,
				tata.ta_date4begin,
				tata.ta_date4End,
				tata.it_transaction,
				tata.tis_id,
				tata.tar_cd,
				tata.user_id_Assigned4Assembly2,
				tata.user_id_Assigned4Assembly3,
				tata.user_id_Assigned4Assembly4,
				tata.user_id_Assigned4Assembly5,
				tata.tar_guid4Selection,
				tata.ta_order,
				tata.ta_isEditingCD,
				ISNULL(tata.ta_isManual,'False')	[ta_isManual],
				@tar_id								[tar_id],
				@sreas_id							[sreas_id],
				tit.it_deliveryDate,
				(SELECT TOP 1
					tsodh.sdlmt_id
					FROM tbSaleOrderDetailHistory			tsodh	WITH(NOLOCK)
					WHERE	tsodh.comp_id	= tata.comp_id	AND
							tsodh.bra_id	= tata.bra_id	AND
							tsodh.soh_id	= tata.soh_id	AND
							tsodh.sod_id	= tata.sod_id
					ORDER BY tsodh.sod_id DESC)						[sdlmt_id]
				FROM tbAssembly_Turns4Assembly						tata
				LEFT JOIN tbItemTransactions						tit
					ON	tit.comp_id			= tata.comp_id			AND
						tit.it_transaction	= tata.it_transaction
				WHERE	tata.comp_id	= @comp_id	AND
						tata.ta_id		= @ta_id

		END
GO

CREATE PROCEDURE spAssembly_Turns4Assembly_GetDataByID_CustomerData
(
	@comp_id	INT,
	@lang_id	INT,
	@ta_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@ta_id		INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@ta_id		= 347
		*/
		-- -----------------------------------------
		SELECT
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, vctfs.ct_transaction)	[Document],
			ISNULL(tc.cust_name,'')																[Cust_Name],
			'ID ' + CONVERT(VARCHAR,tata.ta_id)													[ID]
			FROM tbAssembly_Turns4Assembly														tata		WITH(NOLOCK)
			LEFT JOIN vwCommercialTransactions_forSales											vctfs
			ON	vctfs.comp_id			= tata.comp_id											AND
				vctfs.ct_transaction	= tata.ct_transaction
			LEFT JOIN tbCustomer																tc			WITH(NOLOCK)
			ON	tc.comp_id				= tata.comp_id											AND
				tc.cust_id				= vctfs.cust_id
			WHERE	tata.comp_id		= @comp_id												AND
					tata.ta_id			= @ta_id

	END
GO




CREATE PROCEDURE [dbo].[spAssembly_Turns4Assembly_getDataBySohAndSod]
(
	@comp_id	INT,
	@tis_id		INT
	--@soh_id		INT,
	--@sod_id		INT
)
AS

	SET NOCOUNT ON

		BEGIN
			--BUSCAR POR TIS_ID YA QUE ES EL UNICO VALOR QUE TENDRA CARGADO
			-- --------------------------
			-- Testing
			-- --------------------------
			/*
				DECLARE
					@comp_id	INT,
					@soh_id		INT,
					@sod_id		INT

				SELECT
					@comp_id	= 1,
					@soh_id		= 33264,
					@sod_id		= 23076--23074
			*/
			-- --------------------------

			SELECT
				tata.comp_id,
				tata.ta_id,
				tata.tar_id,
				tata.bra_id,
				tata.soh_id,
				tata.sod_id,
				tata.ct_transaction,
				tata.item_id,
				tata.ta_isAssembled,
				tata.ta_isCancelled,
				ISNULL(tata.ta_note,'')			[ta_note],
				tata.ta_cd,
				tata.user_id_cd,
				tata.ta_date4Assembly,
				tata.user_id_Supervisor,
				tata.user_id_Assigned4Assembly,
				tata.ta_date4begin,
				tata.ta_date4End,
				ISNULL(ti.item_assemblyType,0)	[item_assemblyType]
			FROM tbAssembly_Turns4Assembly		tata
				INNER JOIN tbItem				ti
				ON	ti.comp_id = tata.comp_id	AND
					ti.item_id = tata.item_id

			WHERE	tata.comp_id	= @comp_id	AND
					tata.tis_id		= @tis_id	--AND
					--tata.soh_id		= @soh_id	AND
					--tata.sod_id		= @sod_id

		END
GO


CREATE PROCEDURE [dbo].[spAssembly_Turns4Assembly_getReport]
(
	@comp_id			INT,
	@lang_id			INT,
	@page_id			INT,

	@sreas_id			INT,
	@tar_id				INT,
	@assembled			BIT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@user_id4Assemble	INT,
	@user_id4Assemble2	INT,
	@user_id4Assemble3	INT,
	@user_id4Assemble4	INT,
	@user_id4Assemble5	INT,
	@intBranch4Lang		INT
)
AS

	SET NOCOUNT ON

		BEGIN

			SET DATEFORMAT	'YMD'
			DECLARE @fun_id INT
			SET @fun_id = 1

			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
			-- -----------------------------------------------------------------------------


			-- -----------------------------------------------
			-- Testing
			-- -----------------------------------------------
			/*
				DECLARE
					@comp_id			INT,
					@lang_id			INT,
					@page_id			INT,
					@tar_id				INT,
					@datefrom			DATETIME,
					@dateto				DATETIME,
					@assembled			BIT,
					@intBranch4Lang		INT,
					@sreas_id			INT,
					@user_id4Assemble	INT,
					@user_id4Assemble2	INT,
					@user_id4Assemble3	INT,
					@user_id4Assemble4	INT,
					@user_id4Assemble5	INT

				SELECT
					@comp_id			= 1,
					@lang_id			= 2,
					@page_id			= 10096,
					@tar_id				= -1,
					@datefrom			= '2017-01-01',
					@dateto				= '2017-12-31',
					@assembled			= 'False',
					@intBranch4Lang		= 1,
					@sreas_id			= 2,
					@user_id4Assemble	= -1,
					@user_id4Assemble2	= -1,
					@user_id4Assemble3	= -1,
					@user_id4Assemble4	= -1,
					@user_id4Assemble5	= -1
			*/
			-- -----------------------------------------------


				SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
				SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


				DECLARE
					@UserMessage	VARCHAR(200)
				SELECT
					@UserMessage = tut.utexts_desc
				FROM tbsysUniqueTexts				tut
				WHERE	tut.lang_id		= @lang_id	AND
						tut.utexts_id	= 30667

				--MOSTRAMOS LOS ARTICULOS PENDIENTES DE ENSAMBLADO QUE TIENEN UN USUARIO ASIGNADO

				IF @assembled = 'False'

					BEGIN

						SELECT --DISTINCT
							ISNULL(tc.cust_name,'')											[cust_name],
							ISNULL(tc.cust_address,'')										[cust_address],
							ISNULL(tc.cust_city,'')											[cust_city],
							ti.item_code,
							ti.item_desc,
							tata.ta_date4Assembly,
							tata.ta_date4begin,
							tata.ta_date4End,
							ISNULL(tu.user_lastname  + ',' + tu.user_firstname,@UserMessage)[user_Assembler],
							ISNULL(tu2.user_lastname + ',' + tu2.user_firstname,'')			[user_Supervisor],
							ISNULL(tata.ta_note,'')											[ta_note],
							ISNULL(tu3.user_lastname + ',' + tu3.user_firstname,'')			[user_Assembler2],
							ISNULL(tu4.user_lastname + ',' + tu4.user_firstname,'')			[user_Assembler3],
							ISNULL(tu5.user_lastname + ',' + tu5.user_firstname,'')			[user_Assembler4],
							ISNULL(tu6.user_lastname + ',' + tu6.user_firstname,'')			[user_Assembler5],
							ISNULL(tc.cust_phone1,'') + '/' +
							ISNULL(tc.cust_phone2,'') + '/' +
							ISNULL(tc.cust_cellPhone,'')									[cust_phone],
							ISNULL(tsoh.soh_observation1,'')								[soh_observation1],
							ISNULL(tsoh.soh_observation2,'')								[soh_observation2],
							ISNULL(tsoh.soh_observation3,'')								[soh_observation3],
							ISNULL(tsoh.soh_observation4,'')								[soh_observation4],
							ISNULL(tsoh.soh_deliveryAddress,'')								[soh_deliveryAddress],


							-- ----------------------------------------------------------
							tsoh.soh_deliveryDate,
							td.dl_name,
							ts.stor_desc,
							tov.optval_desc													[DeliveryType]

							-- ----------------------------------------------------------


						FROM tbAssembly_Turns4Assembly										tata
							LEFT JOIN vwSaleOrderHeaderHistory_OnlyLastSaleOrder			tsoh
								ON	tsoh.comp_id	= tata.comp_id							AND
									tsoh.bra_id		= tata.bra_id							AND
									tsoh.soh_id		= tata.soh_id
							LEFT JOIN tbCustomer											tc
								ON	tc.comp_id		= tsoh.comp_id							AND
									tc.cust_id		= tsoh.cust_id
							INNER JOIN tbItem												ti
								ON	ti.comp_id		= tata.comp_id							AND
									ti.item_id		= tata.item_id
							LEFT JOIN tbUser												tu
								ON	tu.[user_id]	= tata.user_id_Assigned4Assembly
							LEFT JOIN tbUser												tu2
								ON	tu2.[user_id]	= tata.user_id_Supervisor
							LEFT JOIN tbUser												tu3
								ON	tu3.[user_id]	= tata.user_id_Assigned4Assembly2
							LEFT JOIN tbUser												tu4
								ON	tu4.[user_id]	= tata.user_id_Assigned4Assembly3
							LEFT JOIN tbUser												tu5
								ON	tu5.[user_id]	= tata.user_id_Assigned4Assembly4
							LEFT JOIN tbUser												tu6
								ON	tu6.[user_id]	= tata.user_id_Assigned4Assembly5
							INNER JOIN tbAssembly_Team										tat
								ON	tat.comp_id		= tata.comp_id							AND
									tat.tar_id		= tata.tar_id

							-- -------------------------------------------------------------------------------

							LEFT JOIN tbSaleOrderDetailHistory						tsodh
							ON	tsodh.comp_id	= tata.comp_id						AND
								tsodh.soh_id	= tata.soh_id						AND
								tsodh.item_id	= tata.item_id						AND
								tsodh.sohh_id	= tsoh.sohh_id

							LEFT JOIN tbDelivery									td
							ON	td.comp_id		= tsoh.comp_id						AND
								td.dl_id		= tsoh.dl_id

							LEFT JOIN tbStorage										ts
							ON	ts.comp_id		= tsodh.comp_id						AND
								ts.stor_id		= tsodh.stor_id

							LEFT JOIN tbsysOptionsValues							tov
							ON	tov.lang_id		= @lang_id							AND
								tov.optval_class= 520								AND
								tov.optval_id	= tsodh.sdlmt_id

							-- -------------------------------------------------------------------------------


						WHERE	tata.comp_id						= @comp_id										AND
								(@tar_id							= -1	OR	tata.tar_id				= @tar_id)	AND
								tata.ta_date4Assembly				BETWEEN @datefrom AND @dateto					AND
								ISNULL(tata.ta_isAssembled,'False')	= 'False'										AND
								tat.sreas_id						= @sreas_id										AND
								(@user_id4Assemble  = -1 OR tata.user_id_Assigned4Assembly = @user_id4Assemble)		AND
								(@user_id4Assemble2 = -1 OR tata.user_id_Assigned4Assembly2 = @user_id4Assemble2)	AND
								(@user_id4Assemble3 = -1 OR tata.user_id_Assigned4Assembly3 = @user_id4Assemble3)	AND
								(@user_id4Assemble4 = -1 OR tata.user_id_Assigned4Assembly4 = @user_id4Assemble4)	AND
								(@user_id4Assemble5 = -1 OR tata.user_id_Assigned4Assembly5 = @user_id4Assemble5)	AND
								ISNULL(tata.ta_isCancelled,'False') = 'False'


					END
				ELSE
					BEGIN
						--MOSTRAMOS LOS ARTICULOS ENSAMBLADOS, CON SU FECHA DE INICIO Y FIN
						SELECT --DISTINCT
							ISNULL(tc.cust_name,'')											[cust_name],
							ISNULL(tc.cust_address,'')										[cust_address],
							ISNULL(tc.cust_city,'')											[cust_city],
							ti.item_code,
							ti.item_desc,
							tata.ta_date4Assembly,
							tata.ta_date4begin,
							tata.ta_date4End,
							ISNULL(tu.user_lastname  + ',' + tu.user_firstname,@UserMessage)[user_Assembler],
							ISNULL(tu2.user_lastname + ',' + tu2.user_firstname,'')			[user_Supervisor],
							ISNULL(tata.ta_note,'')											[ta_note],
							ISNULL(tu3.user_lastname + ',' + tu3.user_firstname,'')			[user_Assembler2],
							ISNULL(tu4.user_lastname + ',' + tu4.user_firstname,'')			[user_Assembler3],
							ISNULL(tu5.user_lastname + ',' + tu5.user_firstname,'')			[user_Assembler4],
							ISNULL(tu6.user_lastname + ',' + tu6.user_firstname,'')			[user_Assembler5],
							ISNULL(tc.cust_phone1,'') + '/' +
							ISNULL(tc.cust_phone2,'') + '/' +
							ISNULL(tc.cust_cellPhone,'')									[cust_phone],
							ISNULL(tsoh.soh_observation1,'')								[soh_observation1],
							ISNULL(tsoh.soh_observation2,'')								[soh_observation2],
							ISNULL(tsoh.soh_observation3,'')								[soh_observation3],
							ISNULL(tsoh.soh_observation4,'')								[soh_observation4],
							ISNULL(tsoh.soh_deliveryAddress,'')								[soh_deliveryAddress]

						FROM tbAssembly_Turns4Assembly										tata
							LEFT JOIN vwSaleOrderHeaderHistory_OnlyLastSaleOrder			tsoh
								ON	tsoh.comp_id	= tata.comp_id							AND
									tsoh.bra_id		= tata.bra_id							AND
									tsoh.soh_id		= tata.soh_id
							LEFT JOIN tbCustomer											tc
								ON	tc.comp_id		= tsoh.comp_id							AND
									tc.cust_id		= tsoh.cust_id
							INNER JOIN tbItem												ti
								ON	ti.comp_id		= tata.comp_id							AND
									ti.item_id		= tata.item_id
							LEFT JOIN tbUser												tu
								ON	tu.[user_id]	= tata.user_id_Assigned4Assembly
							LEFT JOIN tbUser												tu2
								ON	tu2.[user_id]	= tata.user_id_Supervisor
							LEFT JOIN tbUser												tu3
								ON	tu3.[user_id]	= tata.user_id_Assigned4Assembly2
							LEFT JOIN tbUser												tu4
								ON	tu4.[user_id]	= tata.user_id_Assigned4Assembly3
							LEFT JOIN tbUser												tu5
								ON	tu5.[user_id]	= tata.user_id_Assigned4Assembly4
							LEFT JOIN tbUser												tu6
								ON	tu6.[user_id]	= tata.user_id_Assigned4Assembly5
							INNER JOIN tbAssembly_Team										tat
								ON	tat.comp_id		= tata.comp_id							AND
									tat.tar_id		= tata.tar_id
						WHERE	tata.comp_id						= @comp_id										AND
								(@tar_id							= -1	OR	tata.tar_id				= @tar_id)	AND
								tata.ta_date4End					BETWEEN @datefrom AND @dateto					AND
								tata.ta_isAssembled					= 'True'										AND
								tat.sreas_id						= @sreas_id										AND
								(@user_id4Assemble  = -1 OR tata.user_id_Assigned4Assembly  = @user_id4Assemble)	AND
								(@user_id4Assemble2 = -1 OR tata.user_id_Assigned4Assembly2 = @user_id4Assemble2)	AND
								(@user_id4Assemble3 = -1 OR tata.user_id_Assigned4Assembly3 = @user_id4Assemble3)	AND
								(@user_id4Assemble4 = -1 OR tata.user_id_Assigned4Assembly4 = @user_id4Assemble4)	AND
								(@user_id4Assemble5 = -1 OR tata.user_id_Assigned4Assembly5 = @user_id4Assemble5)	AND
								ISNULL(tata.ta_isCancelled,'False') = 'False'



					END



			EXEC [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

			/* devolución de parámetros recibidos */
			DECLARE @related_page_id INT
			SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

			/*************************************************************************************************************/
			/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
			/*
					SELECT	t.ctrl_id,	t.[text_desc]
					FROM	[tbsysTexts]				t
							inner join [tbsysControls]	c
							on c.[ctrl_id] = t.[ctrl_id]
					where	t.[lang_id]	= @lang_id
					and		t.[page_id]	= @related_page_id
					and		t.[type_id]	= 1
			*/
			/*************************************************************************************************************/

			SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 2822
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params1],

      		CASE @tar_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT
						tat.tar_desc
					 FROM tbAssembly_Team tat
					 WHERE	tat.comp_id = @comp_id AND
							tat.tar_id	= @tar_id)
			END			[params2],

      		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 3227
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params3],

      		(SELECT		tsov.optval_desc
						FROM	dbo.tbsysOptionsValues tsov

						WHERE	tsov.optval_id		= @assembled
						AND		tsov.lang_id		= @lang_id
						AND		tsov.optval_class	= 32 )
																[params4]	,

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177

      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],
      		  @datefrom [DateParams1],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params7],
      		 @dateto [DateParams2]



		END

GO



CREATE PROCEDURE spAssembly_Turns4Assembly_getSelectedTurns
(
	@comp_id	INT,
	@guid	    UNIQUEIDENTIFIER
)
AS
	SET NOCOUNT ON

		BEGIN

			SELECT
				tata.ta_id
			FROM tbAssembly_Turns4Assembly				tata
			WHERE	tata.comp_id			= @comp_id	AND
					tata.tar_guid4Selection = @guid

		END


GO




CREATE PROCEDURE [dbo].[spAssembly_Turns4Assembly_getWarrantyReport]
(
	@comp_id		INT,
	@lang_id		INT,
	@page_id		INT,
	@intBranch4Lang	INT,
	@ta_id			INT
)
AS

	SET NOCOUNT ON

		BEGIN

			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
			-- -----------------------------------------------------------------------------

			-- -------------------------------
			-- TESTING
			-- -------------------------------
			/*
				DECLARE
					@comp_id		INT,
					@lang_id		INT,
					@page_id		INT,
					@intBranch4Lang	INT,
					@ta_id			INT
				SELECT
					@comp_id		= 1,
					@lang_id		= 2,
					@page_id		= 10098,
					@intBranch4Lang	= 1,
					@ta_id			= 109
			*/
			-- -------------------------------

			DECLARE
				@FULLTABLE	NVARCHAR(MAX),
				@HEADER		NVARCHAR(MAX),
				@BODY		NVARCHAR(MAX),
				@FOOTER		NVARCHAR(MAX),
				@ltar_id	INT

			SELECT
				@ltar_id	= tata.tar_id
			FROM tbAssembly_Turns4Assembly		tata
			WHERE	tata.comp_id	= @comp_id	AND
					tata.ta_id		= @ta_id

			SELECT
				@HEADER = ISNULL(tadn.iw_title,''),
				@BODY	= ISNULL(tadn.iw_body,''),
				@FOOTER = ISNULL(tadn.iw_footer,'')

			FROM tbAssembly_DocumentsNotes			tadn
				INNER JOIN tbAssembly_Team			tat
				ON	tat.comp_id		= tadn.comp_id	AND
					tat.iw_id		= tadn.iw_id
			WHERE	tadn.comp_id	= @comp_id		AND
					tat.tar_id		= @ltar_id


			SET @FULLTABLE = @HEADER + ' ' + @BODY + ' ' + @FOOTER


			SELECT
				dbo.fnGetCommercialTransactionDescription(tata.comp_id,@lang_id,tata.ct_transaction)	[Document],
				tata.ta_date4Assembly,
				tata.ta_id,
				tc.cust_name,
				ISNULL(tsohh.soh_deliveryAddress, tc.cust_address)										[cust_address],
				ISNULL(tc.cust_cellPhone, '') + '/' +
				ISNULL(tc.cust_phone1,'') + '/' +
				ISNULL(tc.cust_phone2,'')																[cust_phone],
				ISNULL(tata.ta_note,'')																	[ta_note],
				ti.item_code + ' - ' + ti.item_desc														[item_desc],
				tit.it_qty,
				tct.ct_transaction,
				tat.tar_desc,
				tu.user_lastname  + ' , ' + tu.user_firstname											[user4Assembly],
				tu2.user_lastname + ' , ' + tu2.user_firstname											[user4Assembly2],
				tu3.user_lastname + ' , ' + tu3.user_firstname											[user4Assembly3],
				tu4.user_lastname + ' , ' + tu4.user_firstname											[user4Assembly4],
				tu5.user_lastname + ' , ' + tu5.user_firstname											[user4Assembly5]
			FROM tbAssembly_Turns4Assembly						tata
				INNER JOIN tbCommercialTransactions				tct
				ON	tct.comp_id			= tata.comp_id			AND
					tct.ct_transaction	= tata.ct_transaction
				LEFT JOIN tbSaleOrderHeaderHistory				tsohh
				ON	tsohh.comp_id		= tct.comp_id			AND
					tsohh.ct_transaction= tct.ct_transaction
				INNER JOIN tbCustomer							tc
				ON	tc.comp_id			= tata.comp_id			AND
					tc.cust_id			= tct.cust_id
				INNER JOIN tbItem								ti
				ON	ti.comp_id			= tata.comp_id			AND
					ti.item_id			= tata.item_id
				INNER JOIN  tbItemTransactions					tit
				ON	tit.comp_id			= tata.comp_id			AND
					tit.ct_transaction	= tata.ct_transaction	AND
					tit.it_transaction	= tata.it_transaction
				INNER JOIN tbAssembly_Team						tat
				ON	tat.comp_id			= tata.comp_id			AND
					tat.tar_id			= tata.tar_id
				LEFT JOIN tbUser								tu			--STL19072018 ERA INNER ANTES, SI NO TENIA USUARIO PARA ARMADO ASIGNADO NO TRAIA NADA
				ON	tu.[user_id]		= tata.user_id_Assigned4Assembly
				LEFT JOIN tbUser								tu2
				ON	tu2.[user_id]		= tata.user_id_Assigned4Assembly2
				LEFT JOIN tbUser								tu3
				ON	tu3.[user_id]		= tata.user_id_Assigned4Assembly3
				LEFT JOIN tbUser								tu4
				ON	tu4.[user_id]		= tata.user_id_Assigned4Assembly4
				LEFT JOIN tbUser								tu5
				ON	tu5.[user_id]		= tata.user_id_Assigned4Assembly5
			WHERE	tata.comp_id		= @comp_id				AND
					tata.ta_id			= @ta_id


			--TEXTOS DEL REPORET (COLUMNAS, PARAMETROS, ETC)
			EXEC [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id



			-- DEVOLVEMOS EL HTML QUE FORMARA LAS TABLAS DE CONFORMIDAD EL RESTO DE LOS DATOS SON DINAMICOS Y ESTE ES ESTATICO
			SELECT
				@FULLTABLE	[iw_body]

		END

GO





CREATE PROCEDURE [dbo].[spAssembly_Turns4Assembly_InsertData]
(
	@comp_id						INT,
	@tar_id							INT,
	@bra_id							INT,
	@soh_id							INT,
	@sod_id							INT,
	@ct_transaction					INT,
	@item_id						INT,
	@user_id_cd						INT,
	@ta_date4Assembly				DATETIME,
	@it_transaction					INT,
	@note							VARCHAR(4000),
	@tis_id							INT,
	@return_value					INT OUTPUT
)

AS

	SET NOCOUNT ON

		BEGIN
			SET DATEFORMAT 'YMD'
			-- ---------------------------------
			-- TESTING
			-- ---------------------------------
			/*
				DECLARE
					@comp_id						INT,
					@tar_id							INT,
					@bra_id							INT,
					@soh_id							INT,
					@sod_id							INT,
					@ct_transaction					INT,
					@item_id						INT,
					@user_id_cd						INT,
					@ta_date4Assembly				DATETIME,
					@it_transaction					INT,
					@note							VARCHAR(4000),
					@tis_id							INT,
					@return_value					INT

				SELECT
					@comp_id						= 1,
					@tar_id							= 5,
					@bra_id							= 1,
					@soh_id							= 15,
					@sod_id							= 16,
					@ct_transaction					= 17,
					@item_id						= 496,
					@user_id_cd						= 119,
					@ta_date4Assembly				= '2014-12-09',
					@it_transaction					= 12,
					@note							= 'SABADABA',
					@tis_id							= 12
			*/
			-- ---------------------------------



			DECLARE
				@user_id_Supervisor	INT,
				@lCt_Transaction	INT,
				@lIt_Transaction	INT,
				@lTar_Id			INT

			IF @tar_id = -1
				BEGIN
					SET @lTar_Id = NULL
				END
			ELSE
				BEGIN
					SET @lTar_Id = @tar_id
				END


			SELECT
				@user_id_Supervisor = tat.[user_id]
			FROM tbAssembly_Team							tat		WITH (NOLOCK)
			WHERE	tat.comp_id = @comp_id					AND
					tat.tar_id	= @tar_id



			IF @it_transaction <> -1
				BEGIN

					SELECT
						@lCt_Transaction = tit.ct_transaction
					FROM tbItemTransactions							tit		WITH (NOLOCK)
					WHERE	tit.comp_id			= @comp_id			AND
							tit.it_transaction	= @it_transaction
				END
			ELSE
				BEGIN

					SET @lCt_Transaction = NULL
					SET @lIt_Transaction = NULL

				END




			INSERT INTO tbAssembly_Turns4Assembly
			(
				comp_id,
				-- ta_id -- this column value is auto-generated,
				tar_id,
				bra_id,
				soh_id,
				sod_id,
				ct_transaction,
				item_id,
				ta_isAssembled,
				ta_isCancelled,
				ta_note,
				ta_cd,
				user_id_cd,
				ta_date4Assembly,
				user_id_Supervisor,
				user_id_Assigned4Assembly,
				ta_date4begin,
				ta_date4End,
				it_transaction,
				tis_id,
				tar_cd
			)
			VALUES
			(
				@comp_id,
				@lTar_Id,
				@bra_id,
				CASE @soh_id WHEN -1 THEN NULL ELSE @soh_id END,
				CASE @soh_id WHEN -1 THEN NULL ELSE @sod_id END,
				@lCt_Transaction,
				@item_id,
				'False',
				'False',
				@note,
				GETDATE(),
				@user_id_cd,
				@ta_date4Assembly,
				@user_id_Supervisor,
				NULL,
				NULL,
				NULL,
				@lIt_Transaction,
				@tis_id,
				GETDATE()
			)

			--SELECT @@IDENTITY

			SET @return_value = @@IDENTITY

		END
GO



CREATE PROCEDURE spAssembly_Turns4Assembly_InsertData4ManualTurns
(
	@comp_id			INT,
	@tar_id				INT,
	@bra_id				INT,
	@item_id			INT,
	@ta_date4Assembly	DATETIME,
	@ta_order			INT,
	@user_id			INT,
	@return_value		INT OUTPUT
)
AS
	SET NOCOUNT ON

		BEGIN

			INSERT INTO tbAssembly_Turns4Assembly
			(
				comp_id,
				-- ta_id -- this column value is auto-generated,
				tar_id,
				bra_id,
				item_id,
				ta_isAssembled,
				ta_cd,
				user_id_cd,
				ta_date4Assembly,
				tar_cd,
				ta_order,
				ta_isManual
			)
			VALUES
			(
				@comp_id,
				@tar_id,
				@bra_id,
				@item_id,
				'False',
				GETDATE(),
				@user_id,
				@ta_date4Assembly,
				GETDATE(),
				@ta_order,
				'True'
			)

			SET @return_value = @@IDENTITY

		END








GO




CREATE PROCEDURE [dbo].[spAssembly_Turns4Assembly_updateData]
(
	@comp_id			INT,
	@ta_id				INT,
	@tar_id				INT,
	@ta_date4Assembly	DATETIME,
	@note				VARCHAR(4000),
	@soh_id				INT,
	@sod_id				INT,
	@ct_transaction		INT
)
AS
	SET NOCOUNT ON

		BEGIN

			IF @ct_transaction = 0
				SET @ct_transaction = -1

			UPDATE tbAssembly_Turns4Assembly
			SET
				tar_id				= @tar_id,
				ta_date4Assembly	= @ta_date4Assembly,
				ta_note				= @note	,
				tar_cd				= GETDATE(),
				soh_id				= CASE @soh_id			WHEN -1 THEN NULL ELSE @soh_id END,
				sod_id				= CASE @sod_id			WHEN -1 THEN NULL ELSE @sod_id END,
				ct_transaction		= CASE @ct_transaction	WHEN -1 THEN NULL ELSE @ct_transaction END


			WHERE	comp_id = @comp_id AND
					ta_id	= @ta_id


		END
GO


CREATE PROCEDURE [dbo].[spAssemblyTeam_GetTurnDate]
(
	@comp_id		INT,
	@lang_id		INT,
	@tar_id			INT,
	@Turn_Date		DATETIME,
	@item_id		INT,
	@item_qty		INT,
	@Delivery_Date	DATETIME,
	@sod_id			INT,
	@tis_id			INT
)
AS

BEGIN

	SET NOCOUNT		ON
	SET DATEFORMAT	'YMD'
	SET DATEFIRST	7	-- Domingo x Defecto
	-- -------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------
	/*
		DECLARE
			@comp_id		INT,
			@lang_id		INT,
			@tar_id			INT,
			@Turn_Date		DATETIME,
			@item_id		INT,
			@item_qty		INT,
			@Delivery_Date DATETIME,
			@sod_id			INT,
			@tis_id			INT


		SELECT
			@comp_id		= 1,
			@lang_id		= 2,
			@tar_id			= 9,
			@Turn_Date		= '2019-04-06 13:00:00',
			@item_id		= 6875,
			@item_qty		= 1,
			@Delivery_Date	= '2019-04-05',
			@sod_id			= -1,
			@tis_id			= 13338575
	*/
	-- -------------------------------------------------------

	-- -------------------------------------------------------
	-- Si el turno Ya fue asignado para ese grupo de armadores
	-- retorna el turno ya asignado
	-- -------------------------------------------------------
	IF EXISTS(
				SELECT TOP 1  1
					FROM	tbAssembly_Turns4Assembly tata			WITH (NOLOCK)
	          		WHERE	tata.comp_id	= @comp_id AND
	          				tata.tis_id		= @tis_id  AND
	          				tata.tar_id		= @tar_id
			)
		BEGIN
			DECLARE @Message AS NVARCHAR(200)
			SELECT
				@Message			= tut.utexts_desc
			FROM tbsysUniqueTexts				tut	WITH(NOLOCK)
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 40342

			SELECT
				tata.ta_date4Assembly,
				@Message							[ERROR_MESSAGE]
				FROM	tbAssembly_Turns4Assembly	tata	WITH (NOLOCK)
          		WHERE	tata.comp_id	= @comp_id	AND
          				tata.tis_id		= @tis_id	AND
	          			tata.tar_id		= @tar_id
	        RETURN
		END
	-- -------------------------------------------------------


	DECLARE @intLoopCounter AS INT
	SET		@intLoopCounter = 0


	--VARIABLES DE TRABAJO
	DECLARE
		@lLoop					BIT,
		@lAssemblyWorksByDay	DECIMAL(19,4),
		@lTurnDate				DATETIME,
		@lIsSuggested			BIT,
		@lSuggestedDate			DATETIME,
		@OriginalTurnDate		DATETIME,
		@ErrorMessage			VARCHAR(500),
		@HOUR					VARCHAR(50),
		@sReas_id				INT


	SELECT	@sReas_id = tat.sreas_id			-- 1: Taller    2: Domicilio
		FROM tbAssembly_Team tat			WITH (NOLOCK)
		WHERE	tat.comp_id = @comp_id AND
				tat.tar_id	= @tar_id

	IF @sReas_id = 2	-- Si es Armado en Domicilio, la Fecha de Armado debe ser mayor o igual a la fecha de Entrega
		BEGIN
			IF  dbo.fnGetEnd_or_BeginOfDate(@Turn_Date,'False') < dbo.fnGetEnd_or_BeginOfDate(@Delivery_Date,'False')
				BEGIN
					--==
						--SELECT 'ENTRA POR ACA'
					--==
					SET @Turn_Date = @Delivery_Date
				END
		END


	SET @lLoop = 'False'

	--OBTENEMOS EL MÁXIMO DE TRABAJO DIARIO
	SELECT @lAssemblyWorksByDay = tat.tar_AssemblyIndexByDay
		FROM tbAssembly_Team tat
		WHERE	tat.comp_id = @comp_id AND
				tat.tar_id	= @tar_id

	--SETEAMOS LA FECHA DE HOY COMO LA INICIAL Y LE SACAMOS LAS HORAS
	SET @lTurnDate			= @Turn_Date	--GETDATE()
	SET @OriginalTurnDate	= @Turn_Date	--FECHA ORIGINAL QUE INGRESÓ EL USUARIO


	SET @HOUR = CONVERT(VARCHAR,DATEPART(HOUR,@OriginalTurnDate)) + ':' + CONVERT(VARCHAR,DATEPART(MINUTE,@OriginalTurnDate)) + ':' + CONVERT(VARCHAR,DATEPART(SECOND, @OriginalTurnDate))


	SET @lTurnDate			= dbo.fnGetEnd_or_BeginOfDate(@lTurnDate,'False')

	--OBTENEMOS LA FECHA SUGERIDA EN CASO DE ESTAR CHECKEADA
	SELECT
		@lSuggestedDate		= tat.tar_SuggestDate,
		@lIsSuggested		= tat.tar_Available4SuggestDate
		FROM tbAssembly_Team			tat	WITH (NOLOCK)
		WHERE	tat.comp_id = @comp_id	AND
				tat.tar_id	= @tar_id

	SELECT
		@ErrorMessage			= tut.utexts_desc
		FROM	tbsysUniqueTexts			tut	WITH (NOLOCK)
		WHERE	tut.lang_id		= @lang_id	AND
				tut.utexts_id	= 30620


	/*
		DATEPART (RESULTADOS)
		-----------------------
		LUNES		= 2
		MARTES		= 3
		MIERCOLES	= 4
		JUEVEs		= 5
		VIERNES		= 6
		SABADO		= 7
		DOMINGO		= 1
		-----------------------
	*/

	DECLARE
		@lMonday	BIT,
		@lTuesday	BIT,
		@lWednesday	BIT,
		@lThursday	BIT,
		@lFriday	BIT,
		@lSaturday	BIT,
		@lSunday	BIT

	SELECT
		@lMonday	= 'False',
		@lTuesday	= 'False',
		@lWednesday	= 'False',
		@lThursday	= 'False',
		@lFriday	= 'False',
		@lSaturday	= 'False',
		@lSunday	= 'False'


	SELECT
		--==STL 999
		--ANTES ESTABAN EN TRUE, LOS PASO A FALSE
		@lMonday	= ISNULL(tat.tar_Available4Mon,'False'),
		@lTuesday	= ISNULL(tat.tar_Available4Tue,'False'),
		@lWednesday	= ISNULL(tat.tar_Available4Wed,'False'),
		@lThursday	= ISNULL(tat.tar_Available4Thu,'False'),
		@lFriday	= ISNULL(tat.tar_Available4Fri,'False'),
		@lSaturday	= ISNULL(tat.tar_Available4Sat,'False'),
		@lSunday	= ISNULL(tat.tar_Available4Sun,'False')
		FROM tbAssembly_Team			tat		WITH (NOLOCK)
		WHERE	tat.comp_id = @comp_id	AND
				tat.tar_id	= @tar_id


	DECLARE @tmpDaysAvailable TABLE(Day_Id INT PRIMARY KEY, Is_Available BIT)

	INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(2,@lMonday)
	INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(3,@lTuesday)
	INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(4,@lWednesday)
	INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(5,@lThursday)
	INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(6,@lFriday)
	INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(7,@lSaturday)
	INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(1,@lSunday)


	DECLARE
		@Item_AssemblyIndex		DECIMAL(19,4),
		@Group_AssemblyIndex	DECIMAL(19,4)
	SELECT		@Item_AssemblyIndex = ISNULL(ti.item_AssemblyIndex,0)
		FROM	tbItem ti				WITH (NOLOCK)
		WHERE	ti.comp_id = @comp_id	AND
				ti.item_id = @item_id

	SELECT
		@Group_AssemblyIndex = tat.tar_AssemblyIndexByDay
		FROM tbAssembly_Team tat		WITH (NOLOCK)
		WHERE	tat.comp_id = @comp_id	AND
				tat.tar_id	= @tar_id

	--==
		--SELECT
		--	'HOLA',
		--	GETDATE(),
		--	@Item_AssemblyIndex		[Item_AssemblyIndex],
		--	@lAssemblyWorksByDay	[lAssemblyWorksByDay],
		--	@Group_AssemblyIndex	[Group_AssemblyIndex],
		--	@HOUR					[HOUR],
		--	@lTurnDate				[lTurnDate]
	--==



	-- Entra todo en un solo dia ?
	--SI EL RESULTADO DE LA MULTIPLICACIÓN DE LA CANTIDAD DE ARTICULOS
	--Y EL INDICE DE FABRICACION DE CADA UNO ES MENOR O IGUAL
	--AL INDICE DE FABRICACION PERMITIDO POR EL GRUPO, BUSCAMOS EL PRIMER HUECO
	--EN DONDE ENTRE EL LOTE ENTERO.
	IF ((@Item_Qty * @Item_AssemblyIndex) <= @Group_AssemblyIndex)
		BEGIN
			--SELECT (@Item_Qty * @Item_AssemblyIndex), @Group_AssemblyIndex
			--SELECT 666

			--SELECT * FROM @tmpDaysAvailable
			--SELECT DATEPART(WEEKDAY,@lTurnDate)
			WHILE @lLoop = 'False'
				BEGIN
					--==
						--SELECT 0,@lTurnDate
						--SELECT DATEPART(WEEKDAY,@lTurnDate) [DATE PART]
						--SELECT TMP.Day_Id FROM @tmpDaysAvailable TMP WHERE TMP.Is_Available = 'True'
					--==


					IF DATEPART(WEEKDAY,@lTurnDate) IN (SELECT TMP.Day_Id FROM @tmpDaysAvailable TMP WHERE TMP.Is_Available = 'True')
						BEGIN
							--==
								--SELECT 1
							--==

							DECLARE @lAssemblyIndexByDayUnAvailable AS INT
							SET     @lAssemblyIndexByDayUnAvailable = 0
							SELECT
								@lAssemblyIndexByDayUnAvailable = IsNull(iio.tar_AssemblyIndexByDayUnAvailable,0)
								FROM tbAssembly_TeamDateUnAvailable														iio		WITH (NOLOCK)
								WHERE	comp_id															= @comp_id		AND
										dbo.fnGetEnd_or_BeginOfDate(iio.taru_dateUnAvailable,'False')	= @lTurnDate	AND
										iio.tar_id														= @tar_id

							--NOS FIJAMOS QUE LA DIFERENCIA NOS DE MAYOR O IGUAL QUE CERO PARA ASIGNAR UN TRABAJO MÁS
							--5a4sd65a4sd56a4sd65asd
							IF (
									(@lAssemblyWorksByDay - (SELECT IsNull(SUM(tata.ta_assignedIndex),0)
																FROM tbAssembly_Turns4Assembly				tata		WITH (NOLOCK)
																WHERE	tata.comp_id			= @comp_id	AND
																		tata.tar_id				= @tar_id	AND
																		tata.ta_date4End		IS NULL		AND
																		dbo.fnGetEnd_or_BeginOfDate(tata.ta_date4Assembly,'False')	= @lTurnDate AND
																		ISNULL(tata.ta_isCancelled,'False') = 'False'
									)

														  - (ISNULL(@lAssemblyIndexByDayUnAvailable,0))
									) >= 0
								) AND

									(
										(@Item_Qty * @Item_AssemblyIndex) <= ((@lAssemblyWorksByDay - (SELECT IsNull(SUM(tata.ta_assignedIndex),0)
																										FROM tbAssembly_Turns4Assembly				tata		WITH (NOLOCK)
																										WHERE	tata.comp_id			= @comp_id	AND
																												tata.tar_id				= @tar_id	AND
																												tata.ta_date4End		IS NULL		AND
																												dbo.fnGetEnd_or_BeginOfDate(tata.ta_date4Assembly,'False')	= @lTurnDate	AND
																												ISNULL(tata.ta_isCancelled,'False') = 'False')

																								 - (ISNULL(@lAssemblyIndexByDayUnAvailable,0))))
									)

								BEGIN
									--OBTENEMOS LA FECHA RESULTANTE DISPONIBLE PARA INGRESO
									--==
										--SELECT 2, @lTurnDate [TurnDate],@OriginalTurnDate [OriginalTurnDate]
										 --@lTurnDate <> @OriginalTurnDate
									--==
									IF @lTurnDate <> dbo.fnGetEnd_or_BeginOfDate(@OriginalTurnDate,'False')
										BEGIN
											--==
												--SELECT 3
											--==
											SELECT
												@lTurnDate + @HOUR,
												@ErrorMessage	[ERROR_MESSAGE]
											SET @lLoop = 'True'
										END
									ELSE
										BEGIN
										--==
											--SELECT 4
										--==
											SELECT
												@lTurnDate + @HOUR,
												''				[ERROR_MESSAGE]
											SET @lLoop = 'True'
										END
								END

							ELSE
							BEGIN
								--==
									--SELECT 'PRIMER +1'
								--==
								SET @lTurnDate = @lTurnDate + 1
							END
						END
					ELSE
						BEGIN
							--==
								--SELECT 'SEGUNDO +1'
							--==
							SET @lTurnDate = @lTurnDate + 1
						END


					-- ---------------------------------------------------------------------
					-- Para evitar loops INFINITOS si hicieron cagadas en el re puto calculo
					-- ---------------------------------------------------------------------
					SET @intLoopCounter = @intLoopCounter + 1
					IF @intLoopCounter > 1000
						BEGIN
							SET @lLoop = 'True'
						END
					-- ---------------------------------------------------------------------

				END

		END
			-- -----------------------------------
	ELSE	-- NO Entra todo en un solo dia.
			-- -----------------------------------

		BEGIN
			--==
				--SELECT 777
				--SELECT DATEPART(WEEKDAY,@lTurnDate)
			--==
			/*
				POR CADA ARTICULO TENGO QUE ENCONTRAR UN HUECO, YA QUE EL TOTAL DEL LOTE
				NO PUEDE SER INGRESADO EN UN TURNO ENTERO DE ARMADO
			*/

			--SELECT * FROM @tmpDaysAvailable
			--SELECT DATEPART(WEEKDAY,@lTurnDate)
			WHILE @lLoop = 'False'
				BEGIN
					--==
						--SELECT 0
					--==
					IF DATEPART(WEEKDAY,@lTurnDate) IN (SELECT TMP.Day_Id
															FROM @tmpDaysAvailable TMP
															WHERE TMP.Is_Available = 'True')
						BEGIN
							--==
								--SELECT 1
							--==
							IF NOT EXISTS (SELECT
								   				dbo.fnGetEnd_or_BeginOfDate(tatdua.taru_dateUnAvailable,'False')
												FROM tbAssembly_TeamDateUnAvailable				tatdua		WITH (NOLOCK)
												WHERE	tatdua.comp_id				= @comp_id	AND
														tatdua.tar_id				= @tar_id	AND
														tatdua.taru_dateUnAvailable = @lTurnDate)
								BEGIN
									--NOS FIJAMOS QUE LA DIFERENCIA NOS DE MAYOR O IGUAL QUE CERO PARA ASIGNAR UN TRABAJO MÁS
									--5a4sd65a4sd56a4sd65asd
									IF ((SELECT COUNT(*)
											FROM tbAssembly_Turns4Assembly				tata		WITH (NOLOCK)
											WHERE	tata.comp_id			= @comp_id	AND
													tata.tar_id				= @tar_id	AND
													tata.ta_date4End		IS NULL		AND
		--											NOT EXISTS (SELECT 1
		--															FROM	tbAssembly_TeamDateUnAvailable									iio
		--															WHERE	iio.comp_id														= @comp_id AND
		--																	dbo.fnGetEnd_or_BeginOfDate(iio.taru_dateUnAvailable,'False')	= @lTurnDate AND
		--																	iio.tar_id				= @tar_id)						AND
													dbo.fnGetEnd_or_BeginOfDate(tata.ta_date4Assembly,'False')	= @lTurnDate	AND
													ISNULL(tata.ta_isCancelled,'False') = 'False') = 0)

										BEGIN
											--OBTENEMOS LA FECHA RESULTANTE DISPONIBLE PARA INGRESO
											--SELECT 2, @lTurnDate,@OriginalTurnDate
											IF @lTurnDate <> @OriginalTurnDate
												BEGIN
													--==
														--SELECT 33
													--==
													SELECT
														@lTurnDate + @HOUR,
														@ErrorMessage	[ERROR_MESSAGE]
													SET @lLoop = 'True'
												END
											ELSE
												BEGIN
													SELECT
														@lTurnDate + @HOUR,
														''				[ERROR_MESSAGE]
													SET @lLoop = 'True'
												END
										END

									ELSE
										BEGIN
											SET @lTurnDate = @lTurnDate + 1
										END

								END
							ELSE
								BEGIN
									SET @lTurnDate = @lTurnDate + 1
								END
						END

					ELSE
						BEGIN
							SET @lTurnDate = @lTurnDate + 1
						END

					-- ---------------------------------------------------------------------
					-- Para evitar loops INFINITOS si hicieron cagadas en el re puto calculo
					-- ---------------------------------------------------------------------
					SET @intLoopCounter = @intLoopCounter + 1
					IF @intLoopCounter > 1000
						BEGIN
							SET @lLoop = 'True'
						END
					-- ---------------------------------------------------------------------


				END

		END


END

GO


CREATE PROCEDURE [dbo].[spAssemblyTeam_IsDayAvailable4Update]
(
	@comp_id		INT,
	@lang_id		INT,
	@tar_id			INT,
	@Turn_Date		DATETIME
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		SET DATEFIRST 7		-- Domingo x Defecto

		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@tar_id			INT,
				@Turn_Date		DATETIME
			SELECT
				@comp_id		= 1,
				@lang_id		= 2,
				@tar_id			= 5,
				@Turn_Date		= '2019-01-29'
		*/
		-- -----------------------------------------

		/*
			DATEPART (RESULTADOS)
			-----------------------
			LUNES		= 2
			MARTES		= 3
			MIERCOLES	= 4
			JUEVEs		= 5
			VIERNES		= 6
			SABADO		= 7
			DOMINGO		= 1
			-----------------------
		*/

		-- ----------------------------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- ----------------------------------------------------------------------
			DECLARE
				@lMonday	BIT,
				@lTuesday	BIT,
				@lWednesday	BIT,
				@lThursday	BIT,
				@lFriday	BIT,
				@lSaturday	BIT,
				@lSunday	BIT

			SELECT
				@lMonday	= 'False',
				@lTuesday	= 'False',
				@lWednesday	= 'False',
				@lThursday	= 'False',
				@lFriday	= 'False',
				@lSaturday	= 'False',
				@lSunday	= 'False'
		-- ----------------------------------------------------------------------

		-- ----------------------------------------------------------------------
		-- CARGO LOS DÍAS CON SU DISPONIBILIDAD
		-- ----------------------------------------------------------------------
			SELECT
				@lMonday	= ISNULL(tat.tar_Available4Mon,'False'),
				@lTuesday	= ISNULL(tat.tar_Available4Tue,'False'),
				@lWednesday	= ISNULL(tat.tar_Available4Wed,'False'),
				@lThursday	= ISNULL(tat.tar_Available4Thu,'False'),
				@lFriday	= ISNULL(tat.tar_Available4Fri,'False'),
				@lSaturday	= ISNULL(tat.tar_Available4Sat,'False'),
				@lSunday	= ISNULL(tat.tar_Available4Sun,'False')
				FROM tbAssembly_Team			tat		WITH (NOLOCK)
				WHERE	tat.comp_id = @comp_id	AND
						tat.tar_id	= @tar_id
		-- ----------------------------------------------------------------------

		-- ----------------------------------------------------------------------
		-- TABLA QUE VA A CONTENER LOS DIAS DISPONIBLES PARA RECIBIR UN TURNO
		-- ----------------------------------------------------------------------
			DECLARE @tmpDaysAvailable TABLE(Day_Id INT PRIMARY KEY, Is_Available BIT)

			INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(2,@lMonday)
			INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(3,@lTuesday)
			INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(4,@lWednesday)
			INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(5,@lThursday)
			INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(6,@lFriday)
			INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(7,@lSaturday)
			INSERT INTO @tmpDaysAvailable  ( Day_Id, Is_Available) VALUES(1,@lSunday)
		-- ----------------------------------------------------------------------

		DECLARE
			@isAvailable		BIT,
			@isDateUnavailable	BIT

		-- --------------------------------------------------------------------------------------------------------------------------------------------
		-- Si el día ingresado para modificar no es válido, osea, no está contemplado para ser un día posible de asignar al grupo, devolveremos FALSE
		-- --------------------------------------------------------------------------------------------------------------------------------------------
			IF DATEPART(WEEKDAY,@Turn_Date) IN (SELECT TMP.Day_Id FROM @tmpDaysAvailable TMP WHERE TMP.Is_Available = 'True')
				BEGIN
					--SELECT
					--	'True'	[IsAvailable]
					SET @isAvailable = 'True'
				END
			ELSE
				BEGIN
					--SELECT
					--	'False'	[IsAvailable]
					SET @isAvailable = 'False'
				END
		-- --------------------------------------------------------------------------------------------------------------------------------------------

		-- --------------------------------------------------------------------------------------------------------------------------------------------
		-- Si el día ingresado para modificar no es válido porque está en la tabla de días no disponibles, devolvemos FALSE
		-- --------------------------------------------------------------------------------------------------------------------------------------------
		DECLARE
			@AssemblyIndexByDay					INT,
			@AssemblyIndexByDayUnavailable		INT

			SET @AssemblyIndexByDay				= 0
			SET @AssemblyIndexByDayUnavailable	= 0

			SELECT
				@AssemblyIndexByDay = tat.tar_AssemblyIndexByDay
			FROM tbAssembly_Team			tat
			WHERE	tat.comp_id = @comp_id	AND
					tat.tar_id	= @tar_id

			SELECT
				@AssemblyIndexByDayUnavailable = ISNULL(tatdua.tar_AssemblyIndexByDayUnAvailable,0)
			FROM tbAssembly_TeamDateUnAvailable				tatdua
								WHERE	tatdua.comp_id				= @comp_id	AND
										tatdua.tar_id				= @tar_id	AND
										tatdua.taru_dateUnAvailable = @Turn_Date


			--SI LA FECHA EXISTE, PERO AL REALIZAR LA RESTA ENTRE EL INDICE DE ARMADO DIARIO DEL TALLER Y EL INDICE DE ARMADO NO DISPONIBLE PARA EL DIA EN CUESTION ES MAYOR A CERO
			--INDICA QUE SOLO HAY UNA REDUCCION EN EL INDICE DE ARMADO DISPONIBLE PARA ESE DIA, PERO QUE PUEDE CARGAR ARMADOS, DISTINTO ES SI ES 0, AHI INDICA QUE NO HAY
			--DISPONIBILIDAD ALGUNA PARA TODO ESE DIA DE TALLER
			IF (@AssemblyIndexByDay - @AssemblyIndexByDayUnavailable) > 0
				BEGIN
					SET @isDateUnavailable = 'False'
				END
			ELSE
				BEGIN
					SET @isDateUnavailable = 'True'
				END

			--IF @Turn_Date IN (SELECT
			--						tatdua.taru_dateUnAvailable
			--					FROM tbAssembly_TeamDateUnAvailable				tatdua
			--					WHERE	tatdua.comp_id				= @comp_id	AND
			--							tatdua.tar_id				= @tar_id	AND
			--							tatdua.taru_dateUnAvailable = @Turn_Date)
			--	BEGIN
			--		SET @isDateUnavailable = 'True'
			--	END
			--ELSE
			--	BEGIN
			--		SET @isDateUnavailable = 'False'
			--	END
		-- --------------------------------------------------------------------------------------------------------------------------------------------

		SELECT
			@isAvailable		[IsAvailable],
			@isDateUnavailable	[IsDateUnavailable]

	END
GO


CREATE PROCEDURE [dbo].[spAuthorizationByUser_AuthorizationDisables4SaveSOInCommercial]
(

	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@df_id				INT,
	@option				INT,	-- 1- Emision     2- Pedidos
	@SOInCommercial		BIT

)
AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON;


	IF @option = 2	-- Guardar COMO PEDIDO
		BEGIN

			SELECT aut_id
				FROM tbAuthorizationsDisabled4SaveSOInCommercial	tadssc		WITH (NOLOCK)
				WHERE	tadssc.comp_id	= @comp_id	AND
						tadssc.bra_id	= @bra_id	AND
						tadssc.prof_id	= @prof_id	AND
						@SOInCommercial = 'True'

			UNION

			SELECT aut_id
				FROM tbAuthorizationsDisabled4Documents				tadssc		WITH (NOLOCK)
				WHERE	tadssc.comp_id	= @comp_id	AND
						tadssc.prof_id	= @prof_id	AND
						tadssc.df_id	= @df_id	AND
						tadssc.disabled4SaveAs	= 'True'	 AND
						tadssc.isDisabled		= 'False'

		END
	ELSE			-- EMITIR el comprobante
		BEGIN

			SELECT aut_id
				FROM tbAuthorizationsDisabled4Documents				tadssc		WITH (NOLOCK)
				WHERE	tadssc.comp_id	= @comp_id	AND
						tadssc.prof_id	= @prof_id	AND
						tadssc.df_id	= @df_id	AND
						tadssc.disabled4Emission= 'True'	 AND
						tadssc.isDisabled		= 'False'

		END

END
GO






CREATE PROCEDURE [dbo].[spAuthorizationByUser_getDataByFilters]
(

	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER

)
AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON;



	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
	DECLARE	  	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@guid				UNIQUEIDENTIFIER


	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@prof_id			= 2,
				@user_id			= 4,
				@guid				= '7FA943B5-35DB-496E-A8F1-077AC69161A4'

	*/
	-- ------------------------------------------------------

	-- Si aun NO se puso el usuario que autoriza . . .
	IF @user_id = -1

		BEGIN

			SELECT  ' '				[ ],
					' '				[ ],
					tar.aut_id,
					tar.aure_isok,
					tov.optval_desc		[desc],
					tar.aure_obs_1,
					tar.aure_obs_2,
					--tar.aure_obs_3,
					--tar.aure_obs_4,
					tar.aure_id			[ID]
				FROM tbAutorizationRequest			tar	WITH (NOLOCK)
				INNER JOIN tbsysOptionsValues tov			WITH (NOLOCK)
					ON	tov.lang_id			= @lang_id		AND
						tov.optval_id		= tar.aut_id	AND
						tov.optval_class	= 30
				WHERE	tar.aure_guid		= @guid			AND
						tar.aure_isok		<> 'A'

		END

	ELSE
		-- Solo trae las que el usuario puede autorizar en esa sucursal.
		BEGIN


		select	DISTINCT
				' ' [ ],
				' ' [ ],
					ar.aut_id,
					ar.aure_isok,
					tov.optval_desc		[desc],
					ar.aure_obs_1,
					ar.aure_obs_2,
					ar.aure_obs_3,
					ar.aure_obs_4,
					ar.aure_id			[ID]
		FROM 	dbo.tbProfileAuthorization				pa

				INNER JOIN dbo.tbAutorizationRequest	ar
					on  pa.comp_id	=	ar.comp_id
					AND pa.aut_id	=	ar.aut_id

				INNER JOIN tbsysOptionsValues tov
					ON	tov.lang_id			= @lang_id		AND
						tov.optval_id		= ar.aut_id		AND
						tov.optval_class	= 30

				inner join dbo.tbProfile				p
					on  pa.comp_id	=	p.comp_id
					AND pa.prof_id  =	p.prof_id


				INNER JOIN tbUserCompanyProfile tucp
					ON	tucp.comp_id	= p.comp_id AND
						tucp.bra_id		= @bra_id	AND
						tucp.[user_id]	= @user_id	AND
						tucp.prof_id	= p.prof_id

				inner join dbo.tbUser					u
					on  ar.user_id	=	u.user_id



				inner join dbo.tbsysAuthorizations		sa
					on ar.aut_id	=	sa.aut_id

				LEFT JOIN tbUserAuthorizationBlock4Authorize tuaba
           			ON   	tuaba.comp_id	= ar.comp_id	AND
           					tuaba.bra_id	= ar.bra_id		AND
           					tuaba.aut_id	= ar.aut_id		AND
           					tuaba.[user_id] = @user_id

				LEFT JOIN tbUser tmpu2
					ON tmpu2.[user_id]		= @user_id


		WHERE 		pa.comp_id											= @comp_id	AND
			 		ar.aure_isok										= 'P'		AND	--pendientes
					tuaba.comp_id IS NULL											AND
					ar.aure_guid										= @guid		AND
					IsNull(tmpu2.user_Blocked,'False')					= 'False'	AND
					IsNull(tmpu2.user_authorizationBlock4All,'False')   = 'False'	AND
					 (
						tmpu2.user_mustAuthorizateOwnAuthorizations = 'False'
							OR
						(
							tmpu2.user_mustAuthorizateOwnAuthorizations = 'True'
								AND
							ar.[user_id] <> @user_id
						)
					 )


		END


END
GO






