CREATE PROCEDURE [dbo].[spAuthorizations_getProfiles]
(
	@comp_id			int,
	@lang_id			int,
	@prof_id			int

)
as
set nocount on

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

/*
declare 	@comp_id			int,
			@lang_id			int,
			@prof_id			int


select		@comp_id			= 2,
			@lang_id			= 2,
			@prof_id			= 5

*/
select	A.aut_id		[id],
		REPLACE (REPLACE(B.optval_desc,'<B>',''), '</B>', '') [desc]
--B.optval_desc	[desc]

from dbo.tbsysAuthorizations A	WITH (NOLOCK)

inner join dbo.tbsysOptionsValues b	WITH (NOLOCK)
on B.[optval_id]	    = A.[aut_id]

where	B.lang_id	    = @lang_id
and		B.optval_class  = 30
and		A.aut_id not in (select distinct PA.aut_id
							from	[tbProfileAuthorization]	PA
							where	PA.prof_id			= @prof_id
							and		PA.comp_id			= @comp_id)


order by B.optval_order






GO








