CREATE  PROCEDURE [dbo].[spAutorizationRequest_deleteDataFromGuid]
(
		@comp_id			int,
		@aure_guid			uniqueidentifier,
		@aure_genericId		int ,
		@aure_TransactionId int
)
AS
BEGIN

	set nocount on

	SET LOCK_TIMEOUT 500  -- **JAVIER**
	SET DEADLOCK_PRIORITY LOW  -- **JAVIER**

	delete	dbo.tbAutorizationRequest	WITH (ROWLOCK)
	FROM tbAutorizationRequest tmp
	LEFT JOIN tbTempItemStock ttis
		ON	ttis.comp_id = tmp.comp_id AND
			ttis.aure_id = tmp.aure_id
		where	tmp.comp_id			=	@comp_id	and
				tmp.aure_guid		=	@aure_guid
			and	(		@aure_genericId = -1
					OR  aure_genericId	=	@aure_genericId)
			AND (		@aure_TransactionId = -1
					OR	aure_transactionID	= @aure_TransactionId
				)
			AND
			ttis.comp_id IS NULL

END
GO









