CREATE PROCEDURE [dbo].[spAutorizationRequest_getDataById]
(
	@comp_id				int,
	@aure_id				INT,
	@user_id				INT,
	@bra_id					int
)
AS

BEGIN


	DECLARE @bra_processingDate AS DATETIME
	SELECT @bra_processingDate = tb.bra_processingDate
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id

	set nocount on

	/*
	declare 	@comp_id				int,
				@aure_id				int

	select		@comp_id	=1,
				@aure_id	=1
	*/

	select	ar.comp_id,
			ar.aure_id,
			ar.aut_id,
			ar.user_id,
			ar.aure_cd,
			ar.aure_isok,
			ar.aure_obs_1,
			ar.aure_obs_2,
			ar.aure_image,
			ar.aure_obs_3,
			ar.aure_obs_4,
			ar.sysCode_id,
			ar.aure_user_id,
			ar.aure_guid,
			ar.aure_genericId,
			ar.aure_genericGuid,
			u.user_firstname + u.user_lastname [name],
			ar.aure_isEditing,
			ar.bra_id,
			ar.aure_isEditingCd,
			ar.aure_pageHTML,
			ar.aure_guid_postBack,
			ar.aure_auxValueInt,
			ar.aure_auxValueDecimal,
			ar.aure_auxValueDecimal2,
			ar.aure_auxString,
			IsNull(ar.aure_pageHTMLPlus,'')		[aure_pageHTMLPlus],
			IsNull(tc.cust_name,'')				[cust_name],
			ccte.cust_credit_max,
			ccte.cust_credit_own,
			ccte.cust_credit_cheque_own_used,
			ccte.cust_credit_cheque_3rd_used,
			ccte.cust_credit_SaleOrder,
			ccte.cust_credit_balance,
			ccte.cust_credit_balance_OverCome,
			ccte.cust_credit_balance_NotOverCome,
			ccte.cust_id,
			sc.curr_symbol


		from	dbo.tbAutorizationRequest		ar			WITH (NOLOCK)

				left join dbo.tbUser			u			WITH (NOLOCK)
				on  ar.user_id = u.user_id
				and ar.comp_id = u.comp_id

				LEFT JOIN tbcustomer tc						WITH (NOLOCK)
					ON	tc.comp_id = ar.comp_id AND
						tc.cust_id = ar.cust_id

				cross apply dbo.fnCustomer_getBalanceStatus(tc.comp_id, tc.curr_id, tc.cust_id, @user_id, @bra_processingDate, @bra_id, -1) ccte
				LEFT JOIN tbsysCurrency sc					WITH (NOLOCK)
					ON sc.curr_id = tc.curr_id

		where		ar.comp_id  = @comp_id
				and ar.aure_id  = @aure_id



END
GO



CREATE Procedure [dbo].[spAutorizationRequest_History_getData4Grid]
(
		@comp_id				int,
		@lang_id				int,
		@bra_id					int,
		@soh_id					int,
		@soh_id_bra_id			int,
		@ct_transaction			int
)

as

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	set nocount on
	set dateformat 'ymd'


-- ---------------------------------------------------------------------------
-- Testing
-- ---------------------------------------------------------------------------
/*
	Declare
			@comp_id				int,
			@lang_id				int,
			@bra_id					int,
			@soh_id					int,
			@soh_id_bra_id			int,
			@ct_transaction			int



	Select
			@comp_id				= 1,
			@lang_id				= 2,
			@bra_id					= 1,
			@soh_id					= 33499,
			@soh_id_bra_id			= 1,
			@ct_transaction			= 11944
*/
-- ---------------------------------------------------------------------------



	SELECT
		tsohh.aut_id											[aut_id],
		tu.user_lastname + ', ' + tu.user_firstname				[user_name],
		tsohh.aure_isok											[aure_isok],
		isnull(tsohh.aure_obs_1,'')								[aure_obs_1],
		isnull(tsohh.aure_obs_2,'')								[aure_obs_2],
		isnull(tsohh.aure_obs_3,'')								[aure_obs_3],
		isnull(tsohh.aure_obs_4,'')								[aure_obs_4],
		tuaure.user_lastname + ', ' + tuaure.user_firstname		[AVal1],
		tb.bra_desc												[bra_desc],
		tbsoh.bra_desc											[soh_bra_id],
		tsohh.soh_id											[soh_id],
		tc.cust_name											[cust_name],
		isnull(tsohh.aure_originalURL,'')						[aure_originalURL],
		tsohh.aure_cd											[aure_cd]

		FROM tbAutorizationRequest_History				tsohh			WITH ( NOLOCK )

		LEFT JOIN tbUser								tu				WITH ( NOLOCK )
			ON  tu.[user_id]		=	tsohh.[user_id]

		LEFT JOIN tbUser								tuaure			WITH ( NOLOCK )
			ON  tuaure.[user_id]	=	tsohh.aure_user_id

		LEFT JOIN tbBranch								tb				WITH ( NOLOCK )
			ON	tb.comp_id			= tsohh.comp_id		AND
				tb.bra_id			= tsohh.bra_id

		LEFT JOIN tbBranch								tbsoh			WITH ( NOLOCK )
			ON	tbsoh.comp_id		= tsohh.comp_id		AND
				tbsoh.bra_id		= tsohh.soh_bra_id

		LEFT JOIN tbCustomer							tc				WITH ( NOLOCK )
			ON	tc.comp_id			= tsohh.comp_id		AND
				tc.cust_id			= tsohh.cust_id

		WHERE  (tsohh.comp_id = @comp_id and  tsohh.bra_id = @soh_id_bra_id AND tsohh.soh_id = @soh_id) or tsohh.ct_transaction = @ct_transaction


	ORDER BY tsohh.aut_id desc

END
GO





CREATE PROCEDURE [dbo].[spAutorizationRequest_History_getGenericGridData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@soh_id		INT
)

AS


BEGIN


	-- ----------------------------------------
	-- TESTING
	-- ----------------------------------------
	/*

		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@soh_id		INT


		SELECT
			@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@soh_id		= 33570

	*/
	-- ----------------------------------------

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

		SELECT
			tu.user_lastname + ', ' + tu.user_firstname					[User],
