-- =============================================
-- Author:		MOS
-- Create date: <Create Date,,>
-- Description:	Inserta el Historioal para
-- ser relacionado a un ct_transaction
-- =============================================
CREATE PROCEDURE [dbo].[spAutorizationRequest_History_insertData]
	@comp_id		INT,
	@guid			UNIQUEIDENTIFIER,
	@ct_transaction	INT,
	@soh_bra_id		INT,
	@soh_id			INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	IF @ct_transaction = -1 SET @ct_transaction = NULL
	IF @soh_bra_id     = -1 SET @soh_bra_id		= NULL
	IF @soh_id		   = -1 SET @soh_id			= NULL



	INSERT INTO tbAutorizationRequest_History	--WITH (ROWLOCK)
	(
		comp_id,
		aut_id,
		[user_id],
		aure_cd,
		aure_isok,
		aure_obs_1,
		aure_obs_2,
		aure_obs_3,
		aure_obs_4,
		aure_image,
		sysCode_id,
		aure_user_id,
		aure_genericId,
		bra_id,
		aure_pageHTML,
		prof_id,
		aure_TypeOfReq,
		aure_Link,
		aure_auxValueInt,
		aure_auxValueDecimal,
		aure_auxValueDecimal2,
		aure_auxString,
		aure_transactionID,
		aure_pageHTMLPlus,
		aure_pageHTMLIsSaved,
		aure_pageHTMLIsMailSended,
		aure_originalURL,
		cust_id,
		ct_transaction,
		soh_bra_id,
		soh_id
	)
	SELECT	tar.comp_id,
			tar.aut_id,
			tar.[user_id],
			tar.aure_cd,
			tar.aure_isok,
	        tar.aure_obs_1,
	        tar.aure_obs_2,
	        tar.aure_obs_3,
	        tar.aure_obs_4,
	        tar.aure_image,
	        tar.sysCode_id,
	        tar.aure_user_id,
	        tar.aure_genericId,
	        tar.bra_id,
	        tar.aure_pageHTML,
	        tar.prof_id,
	        tar.aure_TypeOfReq,
	        tar.aure_Link,
	        tar.aure_auxValueInt,
	        tar.aure_auxValueDecimal,
	        tar.aure_auxValueDecimal2,
	        tar.aure_auxString,
	        tar.aure_transactionID,
	        tar.aure_pageHTMLPlus,
	        tar.aure_pageHTMLIsSaved,
	        tar.aure_pageHTMLIsMailSended,
	        tar.aure_originalURL,
	        tar.cust_id,
	        @ct_transaction,
	        @soh_bra_id,
	        @soh_id
	FROM tbAutorizationRequest tar	WITH (NOLOCK)
	WHERE	tar.comp_id		= @comp_id	AND
			tar.aure_guid	= @guid		AND
			tar.aure_isok IN ('A','U')



    -- Pone el ct transaction en autorizaciones de Pedidos Guardados Anteriormente
	IF @soh_id IS NOT NULL AND @ct_transaction IS NOT NULL
		BEGIN
			UPDATE tbAutorizationRequest_History		WITH (ROWLOCK)
				SET	ct_transaction	= @ct_transaction
				WHERE	comp_id		= @comp_id		AND
						soh_bra_id	= @soh_bra_id	AND
						soh_id		= @soh_id
		END




END
GO






CREATE  PROCEDURE [dbo].[spAutorizationRequest_insertData]
(
		@comp_id			int,
		@bra_id				INT,
		@prof_id			INT,
		@aut_id				int,
		@user_id			int, --usuario que solicita la autorización
		@aure_isok			char(1),
		@aure_obs_1			varchar(1000),
		@aure_obs_2			varchar(1000),
		@aure_image			image,
		@aure_obs_3			varchar(1000),
		@aure_obs_4			varchar(1000),
		@sysCode_id			int,
		@aure_user_id		int, --usuario que autoriza la solicitud
		@aure_guid			uniqueidentifier,
		@aure_genericId		int,
		@aure_genericGuid	uniqueidentifier,
		@pageHTML			nTEXT,
		@aure_guid_postBack UNIQUEIDENTIFIER,
		@aure_auxValueInt	INT,
		@aure_auxValueDecimal DECIMAL(19,6),
		@aure_auxValueDecimal2 DECIMAL(19,6),
		@aure_auxString		VARCHAR,
		@aure_TransactionId	INT,
		@pageHTMLPlus		nTEXT,
		@sessionGUID		UNIQUEIDENTIFIER,
		@strValueCheck		NVARCHAR(100),
		@return_value		int output
)

AS

BEGIN


	set nocount ON

	DECLARE @bitMustInsertAuthorization AS BIT
	SET @bitMustInsertAuthorization = 'True'



	-- --------------------------------------------------------
	-- Si la autorizacion ya fue pedida y tiene el mismo
	-- valueCheck que la requerida actualmente no hace nada
	-- y retorna el ID de la autorizacion Original
	-- Si el ValueCheck es DIFERENTE la borra e ingresa
	-- nuevamente segun corresponda
	-- --------------------------------------------------------
	IF @strValueCheck <> ''
		BEGIN
			DECLARE @intAureID				AS INT
			SET		@intAureID				= NULL
			DECLARE @strValueCheckActual	AS NVARCHAR(100)
			SELECT	@intAureID				= tar.aure_id,
					@strValueCheckActual	= tar.aure_valueCheck
				FROM tbAutorizationRequest tar	WITH (NOLOCK)
				WHERE	tar.comp_id		= @comp_id			AND
						tar.aut_id		= @aut_id			AND
						tar.aure_guid	= @aure_guid
			IF @intAureID IS NOT NULL
				BEGIN
					-- Si es la misma no hago nada
					IF	@strValueCheck <> ''				AND
						@strValueCheck = @strValueCheckActual
						BEGIN
							SET @return_value = @intAureID
							RETURN
						END
					-- Si es Diferente borro para que se inserte el nuevo pedido de autorizacion.
					IF	@strValueCheck <> ''				AND
						@strValueCheck <> @strValueCheckActual
						BEGIN
							DELETE FROM tbAutorizationRequest	WITH (ROWLOCK)
								WHERE	comp_id = @comp_id	AND
										aure_id = @intAureID
						END
				END
		END
	-- --------------------------------------------------------




	-- --------------------------------------------------------
	-- Verifica si esta des-habilitada para la sucursal actual
	-- --------------------------------------------------------
	IF EXISTS (	SELECT 1
						FROM tbAuthorizationsQualification taq	WITH (NOLOCK)
               			WHERE	taq.comp_id			= @comp_id
               				AND taq.bra_id			= @bra_id
               				AND taq.aut_id			= @aut_id
               				AND taq.aut_disabled	= 'true')
		BEGIN
			SET @bitMustInsertAuthorization = 'False'
		END
	-- --------------------------------------------------------





	-- --------------------------------------------------------
	-- Si el usuario NO debe pedir autorizacion por las claves que el pueda autorizar . . .
	-- --------------------------------------------------------
	IF	@bitMustInsertAuthorization = 'True' AND

		EXISTS(	SELECT 1
					FROM tbuser WITH (NOLOCK)
	          		WHERE	[user_id]								= @user_id AND
	          				user_mustAuthorizateOwnAuthorizations	= 'False')
		BEGIN

			-- --------------------------------------------------------
			-- Verifica si el perfil esta habilitado para autorizar
			-- --------------------------------------------------------
			IF  EXISTS (	SELECT 1
								FROM tbProfileAuthorization tpa			WITH (NOLOCK)
								WHERE	tpa.comp_id = @comp_id
									AND tpa.prof_id = @prof_id
									AND tpa.aut_id  = @aut_id)
				BEGIN
					SET @bitMustInsertAuthorization = 'False'
				END
			-- --------------------------------------------------------


			-- --------------------------------------------------------
			-- Si en el usuario dice que si tiene permiso en algun perfil
			-- para autorizar esta clave no debe pedirla...
			-- --------------------------------------------------------
			IF  EXISTS (
				Select 1
						From dbo.tbProfileAuthorization					PA			WITH (NOLOCK)

						Inner Join dbo.tbUserCompanyProfile				UCP			WITH (NOLOCK)
							On		UCP.comp_id	= PA.comp_id
								and	UCP.prof_id = PA.prof_id
						INNER JOIN tbUser tu										WITH (NOLOCK)
							ON tu.[user_id]		= ucp.[user_id]

					Where
							PA.comp_id  = @comp_id	AND
							PA.aut_id	= @aut_id	AND
							UCP.comp_id = @comp_id	AND
							UCP.bra_id	= @bra_id	AND
							UCP.user_Id = @user_id	AND
							ISNULL(tu.user_authorization4AllProfileInBranch,'False') = 'True'
							)
				BEGIN
					SET @bitMustInsertAuthorization = 'False'
				END
			-- --------------------------------------------------------


		END
	-- --------------------------------------------------------






	-- --------------------------------------------------------
	-- Si esa clave esta deshabilitada para ese usuario no la pide.
	-- --------------------------------------------------------
	IF @bitMustInsertAuthorization = 'True'
		BEGIN
			IF EXISTS(
						SELECT 1
							FROM  tbAuthorizations_UserNoNeedAuthorization taunna WITH (NOLOCK)
							WHERE	taunna.comp_id		= @comp_id AND
									taunna.bra_id		= @bra_id AND
									taunna.prof_id		= @prof_id AND
									taunna.aut_id		= @aut_id AND
									taunna.[user_id]	= @user_id AND
									taunna.isDisabled	= 'False'
					)

			BEGIN
				SET @bitMustInsertAuthorization = 'False'
			END
		END
	-- --------------------------------------------------------

	--CUSTOM_GN_001
	-- No se porque a veces no llega la sucursal. MOS 05-2019
	DECLARE @bra_ID4Request AS INT = NULL
	SELECT  @bra_ID4Request = tb.bra_id
		FROM tbBranch tb WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id




	-- Si debe Insertar la Autorizacion..
	IF @bitMustInsertAuthorization = 'True'
		BEGIN

			insert into dbo.tbAutorizationRequest WITH (ROWLOCK)
			(comp_id, aut_id, user_id, aure_cd, aure_isok, aure_obs_1, aure_obs_2,
			aure_image, aure_obs_3, aure_obs_4, sysCode_id, aure_user_id, aure_guid,
			aure_genericId, aure_genericGuid, bra_id,aure_pageHTML,aure_guid_postBack,aure_TypeOfReq,
			aure_auxValueInt,aure_auxValueDecimal, aure_auxValueDecimal2, aure_auxString ,aure_transactionID,aure_pageHTMLPlus, sessionGUID,
			aure_valueCheck)

			values
			(@comp_id, @aut_id, @user_id, getdate(), @aure_isok, @aure_obs_1, @aure_obs_2,
			@aure_image, @aure_obs_3, @aure_obs_4, @sysCode_id, @aure_user_id, @aure_guid,
			@aure_genericId, @aure_genericGuid, @bra_ID4Request /*@bra_id*/ ,@pageHTML,@aure_guid_postBack,1,
			@aure_auxValueInt, @aure_auxValueDecimal ,@aure_auxValueDecimal2 ,@aure_auxString,	CASE
																									WHEN @aure_TransactionId = -1 THEN NULL
																									ELSE @aure_TransactionId
																								END,
			@pageHTMLPlus,@sessionGUID,
			@strValueCheck)

			set	@return_value = @@identity

		END

	ELSE
		BEGIN
			set	@return_value = 0
		END


END
GO






-- --------------------------------------------------------------
-- MOS  08-2009
-- Borra las claves no refrescadas por 4 minutos
-- --------------------------------------------------------------

CREATE pROCEDURE [dbo].[spAutorizationRequest_IsEditingPurgeStatus]
as
set nocount on


declare @DeleteTime		as	datetime
set		@DeleteTime		=	DATEADD(minute, -20, getdate())

	-- Claves sin Autorizar.-
		DELETE FROM tbAutorizationRequest	WITH(ROWLOCK)
			Where   IsNull(aure_isEditing,'True') = 'True'
				and	IsNull(aure_isEditingCd,GETDATE()-100) < @DeleteTime
				AND aure_TypeOfReq = 1






GO




CREATE procedure [dbo].[spAutorizationRequest_RefreshBySessionGUID]
(
	@comp_id				INT,
	@sessionGUID			UNIQUEIDENTIFIER

)
AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	BEGIN TRY
		UPDATE tbAutorizationRequest WITH (ROWLOCK)
		SET
			aure_isEditingCd = GETDATE()
			WHERE sessionGUID = @sessionGUID
	END TRY
	BEGIN CATCH
	END CATCH


	-- -----------------------------------------------------------------------------------------
	-- Para el caso en q el spIsEditingPurgeStatus se ejecuta cada mucho tiempo,
	-- Se hace una liberacion mas rapida de usuarios y pedidos q salieron por la X
	-- -----------------------------------------------------------------------------------------
	DECLARE @comp_lastFreeIsEditing   AS DATETIME
	DECLARE @comp_lastFreeIsEditingSO AS DATETIME
	DECLARE @bitFreeAction1 AS BIT = 'False'
	DECLARE @bitFreeAction2 AS BIT = 'False'
	SELECT  @comp_lastFreeIsEditing		= comp_lastFreeIsEditing,
			@comp_lastFreeIsEditingSO	= comp_lastFreeIsEditingSO
		FROM tbCompany AS tc	WITH (NOLOCK)
		WHERE	tc.comp_id						= @comp_id


	IF 	DATEADD(minute,-3,GETDATE()) > @comp_lastFreeIsEditing
		BEGIN
			SET @bitFreeAction1 = 'True'
		END


	IF 	DATEADD(minute,-6,GETDATE()) > @comp_lastFreeIsEditingSO
		BEGIN
			SET @bitFreeAction2 = 'True'
		END


	IF @bitFreeAction1 = 0 AND @bitFreeAction2 = 0 RETURN -- Para no hacer updates al pedo sobvre todo de esta tabla, se hace SOLO si es necesario hacerlo



	UPDATE tbCompany
		SET		comp_lastFreeIsEditingSO	=	CASE
													WHEN  @bitFreeAction2 = 1 THEN GETDATE()
													ELSE  comp_lastFreeIsEditingSO
												END,
				comp_lastFreeIsEditing  	=	CASE
													WHEN  @bitFreeAction1 = 1 THEN GETDATE()
													ELSE  comp_lastFreeIsEditing
												END
		WHERE	comp_id						= @comp_id


	IF @bitFreeAction1 = 'True'
		BEGIN
			BEGIN TRY
				EXEC spUSER_IsEditingPurgeStatus
			END TRY
			BEGIN CATCH
			END CATCH
		END

	IF @bitFreeAction2 = 'True'
		BEGIN
			BEGIN TRY
				EXEC spSaleOrder_IsEditingPurgeStatus
			END TRY
			BEGIN CATCH
			END CATCH

			BEGIN TRY
				EXEC spCustomer_IsEditingPurgeStatus
			END TRY
			BEGIN CATCH
			END CATCH
		END

	-- -----------------------------------------------------------------------------------------

END












GO









