CREATE  PROCEDURE [dbo].[spAutorizationRequest_updateDataAuthorization]
(
		@comp_id			int,
		@aure_id			int,
		@aure_isok			char(1),
		@aure_user_id		int
)
AS

BEGIN

	set nocount on
	SET LOCK_TIMEOUT 500  -- **JAVIER**
	SET DEADLOCK_PRIORITY LOW  -- **JAVIER**


	if		exists (SELECT TOP 1	1
						from	dbo.tbAutorizationRequest		WITH (NOLOCK)
						where	comp_id			=	@comp_id
						and		aure_id			=	@aure_id)
	begin

		update	dbo.tbAutorizationRequest	WITH (ROWLOCK)

			set		aure_isok		=	@aure_isok,
					aure_user_id	=	@aure_user_id

			where	comp_id			=	@comp_id
			and		aure_id			=	@aure_id


	end


END

GO









CREATE  PROCEDURE [dbo].[spAutorizationRequest_updateDataAuthorizationByRemoteGuid]
(
		@aure_remoteGUID	UNIQUEIDENTIFIER,
		@aure_isok			char(1),
		@aure_user_id		INT
)
AS

BEGIN

	set nocount ON
	SET LOCK_TIMEOUT 500  -- **JAVIER**
	SET DEADLOCK_PRIORITY LOW  -- **JAVIER**

	DECLARE @intStatus		INT
	SET		@intStatus = 0




	if		exists (SELECT TOP 1 1
						from	dbo.tbAutorizationRequest		WITH (NOLOCK)
						where	aure_remoteGUID =	@aure_remoteGUID AND aure_isok = 'P')
		begin

			update	dbo.tbAutorizationRequest		WITH (ROWLOCK)

				set		aure_isok		=	@aure_isok,
						aure_user_id	=	@aure_user_id
				where	aure_remoteGUID =	@aure_remoteGUID

			IF @aure_isok='A'	SET @intStatus = 1
			IF @aure_isok='D'	SET @intStatus = 2
		END
	ELSE
		BEGIN
			SET @intStatus = 3
		END


	SELECT @intStatus

END

GO






