-- MOS  09-2009
-- Actualiza Page HTML
-- --------------------------------------------------------------

CREATE PROCEDURE [dbo].[spAutorizationRequest_UpdatePageHTML]
	(	@comp_id					AS INT,
		@aure_guid_postBack			AS UNIQUEIDENTIFIER,
		@pageHTML					AS NTEXT,
		@aure_originalURL			AS NVARCHAR(1000)
		)
AS
BEGIN


	SET NOCOUNT ON
	SET LOCK_TIMEOUT 500		-- **JAVIER**
	SET DEADLOCK_PRIORITY LOW	-- **JAVIER**

	BEGIN TRY

		-- Para que dispare los putos triggers hay que actualizar uno por uno.!
		DECLARE curUPDATE CURSOR LOCAL FAST_FORWARD FOR
			SELECT tar.comp_id,tar.aure_id
				FROM tbAutorizationRequest tar	WITH (NOLOCK)
				WHERE	comp_id				= @comp_id				AND
						aure_guid_postBack	= @aure_guid_postBack

		DECLARE @curComp_id AS INT
		DECLARE @curAure_id AS INT
		OPEN curUPDATE
		FETCH NEXT FROM curUPDATE INTO @curComp_id,@curAure_id
		WHILE @@FETCH_STATUS = 0
			BEGIN

				UPDATE tbAutorizationRequest  WITH (ROWLOCK)
					SET
						aure_pageHTML			= @pageHTML,
						aure_pageHTMLIsSaved	= 'True',
						aure_originalURL		= @aure_originalURL
					WHERE	comp_id				= @curComp_id AND
							aure_id				= @curAure_id

				FETCH NEXT FROM curUPDATE INTO @curComp_id,@curAure_id
			END
		CLOSE		curUPDATE
		DEALLOCATE	curUPDATE

	END TRY

	BEGIN CATCH
	END CATCH





END




GO






