CREATE procedure [dbo].[spBankingAccounts_getComboByProfile]
(
		@comp_id		INT,
		@bra_id			INT,
		@prof_id		INT,
		@user_id		INT

)
AS

BEGIN

	set nocount on

	select
			BA.ba_id	[Id],
			BA.ba_desc	[Desc]
		from	dbo.tbBankingAccounts		BA	WITH (NOLOCK)
		where	BA.comp_id	= @comp_id		AND
				ba.ba_disabled = 'False'	AND
				(
					ba.bra_id IS NULL
						OR
					ba.bra_id = @bra_id
				)							AND
				(
					BA.ba_id IN	(SELECT	tstp.ba_id		-- MIERDA pero esta asi en el resto, no es carga asi que queda igual
	   										FROM	tbBankingAccounts4Profile tstp		WITH (NOLOCK)
	   										WHERE	tstp.comp_id	= @comp_id
											AND		tstp.prof_id	= @prof_id
									)
						OR
						 NOT EXISTS		(SELECT	TOP 1 1
	   										FROM	tbBankingAccounts4Profile tstp		WITH (NOLOCK)
	   										WHERE	tstp.comp_id	= @comp_id
											AND		tstp.prof_id	= @prof_id
										)
				)
		ORDER BY BA.ba_desc

END
