		isnull(ba_extractdef_numberTo,0)					[ba_extractdef_numberTo],
		isnull(ba_extractdef_creditFrom,0)					[ba_extractdef_creditFrom],
		isnull(ba_extractdef_creditTo,0)					[ba_extractdef_creditTo],
		isnull(ba_extractdef_debitFrom,0)					[ba_extractdef_debitFrom],
		isnull(ba_extractdef_debitTo,0)						[ba_extractdef_debitTo],
		isnull(ba_extractdef_Note,'')						[ba_extractdef_Note],
		ba_extractdef_decimalSeparator						[ba_extractdef_decimalSeparator],
		ba_extractdef_milesSeparator						[ba_extractdef_milesSeparator],
		ba_extractdef_dateFormat							[ba_extractdef_dateFormat],
		ISNULL(ba_extractdef_ImportFileType,0)				[ba_extractdef_ImportFileType],
