CREATE procedure [dbo].[spBankingAccounts_getList]
(
	@comp_id		INT
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	-- ------------------------------------
	-- Testing
	-- ------------------------------------
	/*
	DECLARE @comp_id		INT
	SELECT @comp_id		=1
	*/
	-- ------------------------------------


	SELECT 	ltrim(rtrim(convert(varchar(9),BA.ba_id)))		+ '-'	+	convert(varchar(15),BA.curr_id)		[Id],
			ltrim(rtrim(convert(varchar(35),BA.ba_desc))) + /*'-' + tbn.bn_name*/	+ ' - ' + SC.curr_symbol	[Desc]

		FROM	dbo.tbBankingAccounts		BA

				INNER JOIN tbsysCurrency	SC
				ON SC.curr_id = BA.curr_id

				INNER JOIN tbBanksName tbn
				ON tbn.bn_id = BA.bn_id AND tbn.comp_id = BA.comp_id

		WHERE 	BA.comp_id	= @comp_id
		ORDER BY BA.ba_desc


END
GO



