		@prof_id		INT

)
AS

BEGIN



	set nocount on

	select
			ltrim(rtrim(convert(varchar(9),BA.ba_id)))		+ '-'	+	convert(varchar(15),BA.curr_id)		[Id],
			ltrim(rtrim(convert(varchar(35),BA.ba_desc))) + /*'-' + tbn.bn_name*/	+ ' - ' + SC.curr_symbol	[Desc]
		from	dbo.tbBankingAccounts		BA	WITH (NOLOCK)

		INNER JOIN tbsysCurrency			SC
		ON		SC.curr_id = BA.curr_id

		where	BA.comp_id	= @comp_id AND
				(
					ba.bra_id IS NULL
						OR
					ba.bra_id = @bra_id
				)
		ORDER BY BA.ba_desc


END
GO






create procedure [dbo].[spBankingAccounts4Custody_getCombo]
(
		@comp_id		int

)
as
set nocount on

select
		BA.ba_id	[Id],
		BA.ba_desc	[Desc]


from	dbo.tbBankingAccounts		BA


where	BA.comp_id					= @comp_id
AND		ba.ba_IsAvailable4Custody	= 'True'

ORDER BY BA.ba_desc


GO





-- Se deberia pasar el USER_ID de session para que haga join con tbUser4BranchFilter.!!!!

-- --------------------------------------------------------------------------------
-- ATENCION.!  Si se toca algo aca hacerlo tambien en [spGeneralBalance_getReport] y en
-- [spBankingTransactions_getReport] y spCashFlow_getDataByFilters
-- --------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[spBankingTransactions_GenerateData4Reports]
(
	@comp_id	INT,
	@lang_id	INT,
	@page_id	INT,
	@ba_id		INT,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@bt_sold    INT,
	@bra_id     INT,
	@brag_id	INT,
	@user_id	INT
)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	------------------------------------------------------------------------------
	--PARAMETROS PARA PRUEBAS-----------------------------------------------------
	------------------------------------------------------------------------------
/*
	DECLARE
		@comp_id	INT,
		@lang_id	INT,
		@page_id	INT,

		@bra_id     INT,
		@ba_id		INT,
		@datefrom	DATETIME,
		@dateto		DATETIME,
		@bt_sold    INT,
		@brag_id	INT = 4,
		@user_id	INT = 1

	SELECT
		@comp_id	=1,
		@lang_id	=2,
		@page_id	=10043,

		@bra_id     =-1,
		@ba_id		= 2,
		@datefrom	='2010-01-01',
		@dateto		='2999-01-30',
		@bt_sold    = -1

	DROP TABLE #tmp_BankTrans
	DROP TABLE #tmp_BT_TMP
*/
	------------------------------------------------------------------------------


	DECLARE @tmpBankingAccounts TABLE(ba_id INT PRIMARY KEY)
	INSERT INTO @tmpBankingAccounts
		SELECT   tbgba.ba_id
			FROM tbBranchGroup_BankingAccounts tbgba			WITH (NOLOCK)
		WHERE	tbgba.comp_id = @comp_id AND
				tbgba.brag_id = @brag_id




	DECLARE @comp_banking_EmmitedChequeByPaymentDate bit
	SELECT 	@comp_banking_EmmitedChequeByPaymentDate = ISNULL(TC.comp_banking_EmmitedChequeByPaymentDate,'False')
		FROM tbCompany tc
		WHERE tc.comp_id = @comp_id



	DECLARE @fun_id INT
	SET		@fun_id = 1


	DECLARE @decSaldoReal AS DECIMAL(19,5)
	SET		@decSaldoReal = 0

	DECLARE @decSaldoPresupuestado AS DECIMAL(19,5)
	SET		@decSaldoPresupuestado = 0


	INSERT INTO #tmp_BankTrans (ID,
								ID2,
								btt_desc					,
								bt_imputationDate			,
								Number						,
								bt_note						,
								bt_Number					,
								Is_Paid						,
								Total						,
								Is_Credit					,
								isChp						,
								ct_transaction				,
								bt_id,
								btt_id,
								ecct_id,
								chp_isNegociated,
								chp_isCustodia
								)


	-- Valores (Cheques, Documentos) *1
	SELECT
		tbt.bt_id								[ID],
		tcp1.chp_id								[ID2],
		'1-'+ vbtt2.btt_desc					[btt_desc],
		tbt.bt_imputationDate,
		tcp1.chp_number							[Number],
		tbt.bt_note,
		tbt.bt_Number,
		CASE
			WHEN tcp1.chp_IsPayed		= 1 THEN 1
			WHEN tcp1.chp_isRejected	= 1 THEN 1
			WHEN tcp1.chp_isCancelled	= 1 THEN 1
			ELSE 0
		END										[Is_Paid],
		tbt.bt_total							[Total],
		vbtt2.btt_isCredit						[Is_Credit],
		CASE
			WHEN tcp1.chp_id IS NULL THEN 'false'
			ELSE						  'true'
		END										[isChp],
		tbt.ct_transaction,
		tbt.bt_id,
		tbt.btt_id,
		NULL,
		tcp1.chp_isNegociated,
		CASE
		    WHEN tcp1.ba_id IS NOT NULL THEN	'True'
		    ELSE								'False'
		END

	--INTO #tmp_BankTrans

	FROM tbBankingTransactions tbt							WITH (NOLOCK)

		INNER JOIN @tmpBankingAccounts tmpb
			ON tmpb.ba_id = tbt.ba_id

-- MOS 08-2013
--		left JOIN tbCheckPortfolioMovements tcpm
--		ON		tcpm.comp_id		= tbt.comp_id
--			AND tcpm.ct_transaction = tbt.ct_transaction
--			AND tcpm.bra_id			= tbt.bra_id
--			AND tcpm.chp_id			= tbt.chp_id

--		LEFT JOIN tbCheckPortfolio tcp1
--		ON	tcp1.comp_id	= tbt.comp_id
--		AND tcp1.chp_id		= tcpm.chp_id




		INNER JOIN vwBankingTransactionTypes vbtt2			WITH (NOLOCK)
			ON vbtt2.btt_id = tbt.btt_id

		INNER JOIN tbBankingAccounts tba					WITH (NOLOCK)
			ON  tba.comp_id = tbt.comp_id
			AND tba.ba_id	= tbt.ba_id

		LEFT JOIN tbCommercialTransactions tct				WITH (NOLOCK)
			ON	tct.comp_id = tbt.comp_id
			--AND tct.bra_id = tbt.bra_id	-- 08-2013
			AND tct.ct_transaction = tbt.ct_transaction

		INNER JOIN tbUsers4BranchFilter vubf	WITH (NOLOCK) -- el HDP hizo una mierda que en no se que caso no grababa un ct_transaction asociado.
			ON	(	vubf.comp_id	= tct.comp_id		AND	-- Eso se bloqueo pero para que todo siga funcionando se puso esta mierda
					vubf.bra_id		= tct.bra_id		AND	-- Si tarda mucho ver como arreglarlo.
					vubf.[user_id]	= @user_id /*tct.[user_id]*/)
					OR
				tct.comp_id IS NULL

		LEFT JOIN tbCheckPortfolio tcp1						WITH (NOLOCK)
			ON	tcp1.comp_id	= tbt.comp_id AND
				tcp1.chp_id		= tbt.chp_id

		WHERE tbt.comp_id = @comp_id
			AND (@ba_id = -1 or tbt.ba_id = @ba_id)
			AND tbt.bt_imputationDate BETWEEN @datefrom AND @dateto
			AND tbt.btt_id <> 1000001
			AND (@bt_sold = -1 OR  tbt.bt_Sold = @bt_sold)
			AND (	   (tct.sd_id BETWEEN 200 AND 299)
					OR tct.sd_id = 6
					OR tct.sd_id = 13
					OR tct.sd_id = 7						-- MOS 07-2023 x Electromil: Recibo de Ingreso de Valores  ** kn98723984adnqw
					OR  vbtt2.btt_id = 1000002
					OR  vbtt2.btt_id = 1000004				-- Liquidacion de Tarjetas de Credito
					OR  vbtt2.btt_id = 1000008				-- TransferenciA bANCARIA POR pAGOS
					OR  vbtt2.btt_id = 1000009				-- Anulación de Transferencia Bancaria por Pagos
				)	-- Solo Movimientos Bancarios o Rechazo de Valores




	UNION




	-- Valores Emitidos.  *2
	SELECT
		tbt.bt_id								[ID],
		tec.ec_id								[ID2],
		'2-' + vbtt2.btt_desc	 				[btt_desc],
		CASE
			WHEN @comp_banking_EmmitedChequeByPaymentDate = 'True'	THEN tec.ec_PayDate
			WHEN tec.ec_PaymentFinalDate IS NULL					THEN tec.ec_PayDate
			ELSE tec.ec_PaymentFinalDate
		END										[bt_imputationDate], --tbt.bt_imputationDate, MOS 02-2013
		tec.ec_Number							[Number],
		tbt.bt_note,
		tbt.bt_Number,
		tec.ec_isPaid							[Is_Paid],
		tec.ec_Total							[Total],
		vbtt2.btt_isCredit						[Is_Credit],
		case
			when tec.ec_id IS NULL THEN 'false'
			ELSE 'true'
		END [isChp],
		tbt.ct_transaction,
		tbt.bt_id,
		tbt.btt_id,
		tec.ecct_id,
		'False',
		'False'


	FROM tbBankingTransactions tbt						WITH (NOLOCK)

		INNER JOIN @tmpBankingAccounts tmpb
			ON tmpb.ba_id = tbt.ba_id

		INNER  JOIN tbEmmitedChecks tec					WITH (NOLOCK)
			ON tec.ct_transaction = tbt.ct_transaction
			AND tec.ec_id = tbt.ec_id
			AND tec.comp_id = tbt.comp_id

		INNER JOIN vwBankingTransactionTypes vbtt2		WITH (NOLOCK)
			ON vbtt2.btt_id = tbt.btt_id

		INNER JOIN tbBankingAccounts tba				WITH (NOLOCK)
			ON  tba.comp_id = tbt.comp_id	AND tba.ba_id = tbt.ba_id

		INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
			ON	tct.comp_id = tbt.comp_id
			AND tct.bra_id = tbt.bra_id
			AND tct.ct_transaction = tbt.ct_transaction

		INNER JOIN tbUsers4BranchFilter vubf			WITH (NOLOCK)
			ON vubf.comp_id = tct.comp_id
			AND vubf.bra_id = tct.bra_id
			AND vubf.[user_id] = @user_id  /*tct.[user_id]*/

		WHERE tbt.comp_id = @comp_id
		AND (@ba_id = -1 or tbt.ba_id = @ba_id)
		AND
		CASE
			WHEN @comp_banking_EmmitedChequeByPaymentDate = 'True'	AND
														tec.ec_PayDate				BETWEEN @datefrom AND @dateto THEN  1
			WHEN @comp_banking_EmmitedChequeByPaymentDate = 'False'	AND
				 tec.ec_PaymentFinalDate IS NOT NULL AND tec.ec_PaymentFinalDate	BETWEEN @datefrom AND @dateto THEN	1
			WHEN @comp_banking_EmmitedChequeByPaymentDate = 'False'	AND
				 tec.ec_PaymentFinalDate IS     NULL AND tec.ec_PayDate				BETWEEN @datefrom AND @dateto THEN	1
			ELSE																										0
		END = 1

		 --tec.ec_PayDate BETWEEN @datefrom AND @dateto
		AND (@bt_sold = -1 OR  tbt.bt_Sold =@bt_sold)
		AND tct.sd_id <> 143




	UNION




	SELECT --==STL Aca se añadieron todos los movimientos que no se habian tenido en cuenta (Liq. de Tarjeta/Dep. en Efectivo/Mov. Cred y Mov. Deb) *3
		tct.ct_transaction																[ID],
		td.sd_id																		[ID2],
		'3-' + (
			SELECT TOP 1 vbtt2.btt_desc
				FROM tbBankingTransactions tbt					WITH (NOLOCK)
				INNER JOIN vwBankingTransactionTypes vbtt2		WITH (NOLOCK)
					ON	   vbtt2.btt_id = tbt.btt_id
			WHERE tbt.ct_transaction = tct.ct_transaction
		)														[btt_desc],
		--vbtt2.btt_desc	+ '*3'															[btt_desc],
		tct.ct_date,
		dbo.fnGetCommercialTransactionDescription(1,2,tct.ct_transaction)	[Number],
		''      																		[bt_note],
		''																				[bt_Number],
		isnull(vwctbt.is_paid,'false')													[Is_Paid],

			CASE
				-- Liquidacion de T.Credito
				WHEN tct.sd_id = 142 THEN
					(TCT.ct_subtotal -  ISNULL((
									SELECT SUM(TPCM.pcm_total)
										FROM tbPurchaseConceptMovements tpcm	WITH (NOLOCK)
									WHERE TPCM.comp_id = TCT.comp_id AND TPCM.ct_transaction = TCT.ct_transaction
									),0)
					 /  CASE		-- 02-2012 por cambio en compras del campo acurr... para homogeneizar con el resto de las operaciones.-
										WHEN IsNull(tct.ct_ACurrencyExchange,1) = 0 THEN 1 -- Error.!  verificar cuando pasa pls.  MOS
										ELSE IsNull(tct.ct_ACurrencyExchange,1)
						END
					)
				-- Otros Mov. Bancarios

				ELSE	 tct.ct_total / CASE		-- 02-2012 por cambio en compras del campo acurr... para homogeneizar con el resto de las operaciones.-
											WHEN IsNull(tct.ct_ACurrencyExchange,1) = 0 THEN 1 -- Error.!  verificar cuando pasa pls.  MOS
											ELSE IsNull(tct.ct_ACurrencyExchange,1)
										END
			END


																						[Total],
		CASE
			WHEN tct.sd_id = 142 THEN 'True'
			ELSE vwctbt.sd_iscredit
		END																				[Is_Credit],
		'false',
		tct.ct_transaction,
		0,
		0,
		0,
		'False',
		'False'

		FROM tbCommercialTransactions tct											WITH (NOLOCK)




		inner JOIN vwCommercialTransactions_forBankingTransactions	vwctbt		WITH (NOLOCK)
			ON vwctbt.ct_transaction = tct.ct_transaction

		inner JOIN tbBankingAccounts tba										WITH (NOLOCK)
			ON tba.comp_id = tct.comp_id
			AND tba.ba_id  = tct.ba_id

		INNER JOIN @tmpBankingAccounts tmpb
			ON tmpb.ba_id = tba.ba_id

		INNER JOIN tbsysDocuments td											WITH (NOLOCK)
			ON td.sd_id = vwctbt.sd_id

		INNER JOIN tbUsers4BranchFilter vubf									WITH (NOLOCK)
			ON vubf.comp_id = tct.comp_id
			AND vubf.bra_id = tct.bra_id
			AND vubf.[user_id] = @user_id   /*tct.[user_id]*/


		WHERE	tct.comp_id		= @comp_id
		AND		tba.ba_id		= @ba_id
		AND		tct.ct_date	BETWEEN @datefrom AND @dateto

		AND		tct.sd_id		<> 251	-- todos los sd menos cheques rechazados
		AND		tct.sd_id		<> 143  -- Extracto Bancario Resumen
		AND		tct.sd_id		<> 200	-- todos los sd menos Cheques Depositados
		AND
				-- --------------------------------------------------------------------------------------
				-- Este select se puso porque al principio no grababa en tbbanktrans y si en tbcomm
				-- que es lo que busca aqui.  por eso si ahora tiene un btt 1000004 no lo toma en cuenta
				-- --------------------------------------------------------------------------------------
				CASE
					WHEN	tct.sd_id <> 142	THEN 'True'
					WHEN
						(
							tct.sd_id = 142 AND NOT EXISTS(	SELECT 1
		                                    					FROM tbBankingTransactions tbt		WITH (NOLOCK)
		                                    					WHERE	tbt.comp_id			= tct.comp_id			AND
		                                    							tbt.ct_transaction	= tct.ct_transaction	AND
		                                    							tbt.btt_id			= 1000004)

						 )
												THEN 'True'
					ELSE 'False'
				END	= 'True'
				-- --------------------------------------------------------------------------------------

--	AND		(	tct.sd_id <> 142 OR
--				(
--				tct.sd_id = 142 AND NOT EXISTS(	SELECT 1
--		                                    			FROM tbBankingTransactions tbt
--		                                    			WHERE	tbt.comp_id			= tct.comp_id			AND
--		                                    					tbt.ct_transaction	= tct.ct_transaction	AND
--		     					tbt.btt_id			= 1000004)
--		                                    		-- Este select se puso porque al principio no grababa en tbbanktrans y si en tbcomm
--		         )                           		-- que es lo que busca aqui.  por eso si ahora tiene un btt 1000004 no lo toma en cuenta
--			)


			ORDER BY bt_imputationDate,ct_transaction


--==
--SELECT * FROM #tmp_BankTrans WHERE total = 7200
--==
	/*-------------------------------------------------------------------------------------------*/


--SELECT '***********************************'
--SELECT * FROM #tmp_BankTrans
--SELECT '***********************************'




	-- -------------------------------------------------------------------------
	-- Vouchers de Cobranza
	-- -------------------------------------------------------------------------
	INSERT INTO #tmp_BankTrans (ID,
								ID2,
								btt_desc					,
								bt_imputationDate			,
								Number						,
								bt_note						,
								bt_Number					,
								Is_Paid						,
								Total						,
								Is_Credit					,
								isChp						,
								ct_transaction				,
								bt_id,
								btt_id)
	SELECT	-1,
			tbvbtc.v4c_id,
			'4-Voucher',
			tbvbtc.v4c_transferDate,
			tbvbtc.v4c_transactionNumber,
			tbvbtc.v4c_note,
			-1,
			'True',
			tbvbtc.v4c_Total,
			'False',
			'False',
			tbvbtc.ct_transaction,
			-1,
			1000041
		FROM tbBankingVouchers4BanckTransferCollection tbvbtc		WITH (NOLOCK)
	WHERE	tbvbtc.comp_id			= @comp_id						AND
			tbvbtc.v4c_transferDate BETWEEN @datefrom AND @dateto	AND
			tbvbtc.v4c_isCollected	= 'False'						AND
			tbvbtc.v4c_isCancelled  = 'False'						AND
			tbvbtc.ct_transaction IS  NULL							AND
			tbvbtc.ba_id			= @ba_id
	-- -------------------------------------------------------------------------






	-- -------------------------------------------------------------------------
	-- <<<<<<<<<<<<suma los valores para las columnas de saldo y presupuestado.-
	-- -------------------------------------------------------------------------
	/*Cursor*/
	DECLARE
		@id			INT,
		@id2		INT,
		@total		DECIMAL(19,5),
		@is_payed	BIT,
		@is_credit	BIT,
		@value		DECIMAL(19,5),
		@isChp		BIT,
		@ct_transaction	INT,
		@btt_id			INT,
		@bitIsCancelled AS BIT


	DECLARE cursor_BT_gR CURSOR LOCAL FAST_FORWARD FOR
	SELECT	tmp.Id,
			tmp.Id2,
			tmp.Total,
			tmp.Is_Paid,
			tmp.Is_Credit,
			tmp.isChp,
			tmp.ct_transaction,
			tmp.btt_id,
			IsNull(tbt.bt_isCancelled,'False') [bt_isCancelled]
		FROM #tmp_BankTrans	tmp
		LEFT JOIN tbBankingTransactions tbt	WITH (NOLOCK)
			ON tbt.bt_id = tmp.bt_id
		ORDER BY tmp.bt_imputationDate,tmp.bt_id,tmp.ct_transaction

	OPEN cursor_BT_gR

	FETCH NEXT FROM cursor_BT_gR
	INTO @id,
		 @id2,
		 @total,
		 @is_payed,
		 @is_credit,
		 @isChp,
		 @ct_transaction,
		 @btt_id,
		 @bitIsCancelled

	WHILE @@FETCH_STATUS = 0
	BEGIN

--==
--		SELECT @id,
--			 @id2,
--			 @total,
--			 @is_payed,
--			 @is_credit		[is_credit],
--			 @isChp,
--			 @ct_transaction	[ct_transaction],
--			 @btt_id,
--			 @bitIsCancelled [IsCancelled]
--==

		IF @bitIsCancelled = 'False'
			BEGIN

--==
--SELECT ' No Cancelado'
--==

				IF @btt_id = 1000002
					BEGIN
							set @decSaldoReal =  @decSaldoReal -- @total    Saldo
							SET @decSaldoPresupuestado = @decSaldoPresupuestado -- @total

--							Insert into #tmp_BT_TMP
--								(id, Id2, credito, debito,suma, total2,ct_transaction)
--							values
--								(@Id, @id2, @total, 0,@decSaldoPresupuestado,@decSaldoReal,@ct_transaction)
					END

				IF @btt_id = 1000041  -- Vouchers de Cobranza
					BEGIN
							set @decSaldoReal =  @decSaldoReal + @total
							SET @decSaldoPresupuestado = @decSaldoPresupuestado + @total

							Insert into #tmp_BT_TMP
								(id, Id2, credito, debito,suma, total2,ct_transaction)
							values
								(@Id, @id2, @total, 0,@decSaldoPresupuestado,@decSaldoReal,@ct_transaction)
					END
				ELSE IF @btt_id  = 1000021  -- Anulacion de deposito de valores.
					BEGIN
							set @decSaldoReal =  @decSaldoReal  --- @total
							SET @decSaldoPresupuestado = @decSaldoPresupuestado - @total

							Insert into #tmp_BT_TMP
								(id,	Id2, credito, debito, suma,  total2,ct_transaction)
							values
								(@Id,	@id2,0,		  @total, @decSaldoPresupuestado,@decSaldoReal,@ct_transaction)

--							Insert into #tmp_BT_TMP
--								(id, Id2, credito, debito,suma, total2,ct_transaction)
--							values
--								(@Id, @id2, @total, 0,@decSaldoPresupuestado,@decSaldoReal,@ct_transaction)
					END
				ELSE IF @is_payed = 'True'
					BEGIN
						IF @is_credit = 'True'
							BEGIN
								set @decSaldoReal = @decSaldoReal + @total
								SET @decSaldoPresupuestado = @decSaldoPresupuestado + @total

								Insert into #tmp_BT_TMP
								(id, Id2, credito, debito,suma, total2,ct_transaction)
								values
								(@Id, @id2, @total, 0,@decSaldoPresupuestado,@decSaldoReal,@ct_transaction)
							END
						ELSE
							BEGIN
								set @decSaldoReal = @decSaldoReal - @total
								SET @decSaldoPresupuestado = @decSaldoPresupuestado  - @total

								Insert into #tmp_BT_TMP
								(id, id2, credito, debito,suma, total2,ct_transaction)
								values
								(@Id, @id2, 0, @total,@decSaldoPresupuestado,@decSaldoReal,@ct_transaction)
							END
					END
				ELSE
					BEGIN
						IF @is_credit = 'True'
							BEGIN
								if @isChp = 'false' set @decSaldoReal = @decSaldoReal + @total
								SET @decSaldoPresupuestado = @decSaldoPresupuestado + @total
		--SET @decSaldoPresupuestado = 2000
								Insert into #tmp_BT_TMP
								(id, Id2, credito, debito,suma, total2,ct_transaction)
								values
								(@Id, @id2, @total,0, @decSaldoPresupuestado,@decSaldoReal,@ct_transaction)
							END
						ELSE
							BEGIN
								if @isChp = 'false' set @decSaldoReal = @decSaldoReal - @total
								SET @decSaldoPresupuestado = @decSaldoPresupuestado - @total
		--SET @decSaldoPresupuestado = 3000
								Insert into #tmp_BT_TMP
								(id, Id2, credito, debito,suma, total2,ct_transaction)
								values
								(@Id, @id2, 0, @total,@decSaldoPresupuestado,@decSaldoReal,@ct_transaction)
							END
					END
			END

		ELSE	-- IsCanCelled = True
			BEGIN

				IF @btt_id = 1000020	-- Si es un deposito cancelado suma en el presupuestado solamente
					BEGIN
						set @decSaldoPresupuestado = @decSaldoPresupuestado + @total
						Insert into #tmp_BT_TMP
										(id, Id2, credito, debito,suma, total2,ct_transaction)
									values
										(@Id, @id2, @total, 0,@decSaldoPresupuestado,@decSaldoReal,@ct_transaction)
					END
				ELSE IF @btt_id = 1000002	-- Si es un Cheque Rechazado NO Hace Nada
					BEGIN
						set @decSaldoPresupuestado = @decSaldoPresupuestado
					END
				ELSE
					BEGIN
						Insert into #tmp_BT_TMP
										(id, Id2, credito, debito,suma, total2,ct_transaction)
									values
										(@Id, @id2, @total, 0,@decSaldoPresupuestado,@decSaldoReal,@ct_transaction)
					END
			END


		FETCH NEXT FROM cursor_BT_gR
		INTO @id,
			 @id2,
			 @total,
			 @is_payed,
			 @is_credit,
			 @isChp,
			 @ct_transaction,
			 @btt_id,
			 @bitIsCancelled


	END

	CLOSE cursor_BT_gR
	DEALLOCATE cursor_BT_gR
	--/*----------------------------------------------------------------------------------------------*/









END
GO






-- Conciliacion Bancaria.!!!!
CREATE Procedure [dbo].[spBankingTransactions_getDataByFilters]
(
	@comp_id			int,
	@lang_id			int,
	@bn_id				int,
	@datefrom			datetime,
	@dateto				datetime,
	@btt_id				int,
	@ba_id				int,
	@is_conciliated		BIT
)
AS

BEGIN

	set nocount on

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	set dateformat 'ymd'

-- ---------------------------------------------------------------------
-- TESTING
-- ---------------------------------------------------------------------
/*
	Declare	@comp_id			int,
			@lang_id			int,
			@bn_id				int,
			@datefrom			datetime,
			@dateto				datetime,
			@btt_id				int,
			@ba_id				int,
			@is_conciliated		BIT


	Select	@comp_id			=1,
			@lang_id			=2,
			@bn_id				=4,
			@datefrom			='2000-02-01',
			@dateto				='2022-12-31',
			@btt_id				= -1,
			@ba_id				= 19,
			@is_conciliated		='False'

*/
-- ---------------------------------------------------------------------



	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-07-28
	-- Parte		: 410
	-- Description	: Para cumplir el requerimiento solicitado, se agregó el left join tbCheckPortfolio para
	--				  recuperar el chp_number, número de cheque
	-- =================================================================================================================



	Select	' ' [ ],
			BT.bt_imputationDate,
			dbo.fnStrPADL( cast(vbtt.btt_id AS NVARCHAR),4,'0') + '-'+  vbtt.btt_desc [btt_desc],
			isnull(CASE BT.chp_id when NULL
					then BT.ec_id
					else BT.chp_id
					end, 0)							[Nro],
			isnull( CASE
						WHEN bt.ec_id	IS NOT NULL	THEN dbo.fnStrPADL( tec.ec_Number,25,'*')
						WHEN bt.chp_id	IS NOT NULL	THEN dbo.fnStrPADL( tcp1.chp_number,25,'*')
						ELSE '*'
					END

								,'')															[chp_number],	--2010-07-28 - Parte 409
			--dbo.fnStrPADL(cast(cast( BT.bt_total	as DECIMAL(19,2)) AS NVARCHAR(25)),15,'=')	[bt_total],     -- 22/11/18 se saca los =
			BT.bt_total																			[bt_total],
			BN.bn_name																			[bn_name],
			CU.curr_desc																		[curr_desc],
			isnull(BT.bt_note,'')																[bt_note],
			isnull(bt.bt_isAutoConciliated,'False')												[bt_isAutoConciliated],
			vbtt.btt_id																			[btt_id],
			BA.ba_id																			[ba_id],
			isnull(tb.bra_desc,'')																[bra_desc],
			BT.bt_id																			[ID]



	from	dbo.tbBankingTransactions						BT

			LEFT JOIN tbCommercialTransactions				tct
			ON	tct.comp_id			= bt.comp_id		AND
				tct.ct_transaction	= bt.ct_transaction

			LEFT JOIN tbBranch								tb
			ON	tb.comp_id			= tct.comp_id		AND
				tb.bra_id			= tct.bra_id

			inner JOIN vwBankingTransactionTypes			vbtt
			ON	vbtt.btt_id			= BT.btt_id

			inner join  dbo.tbBankingAccounts				BA
			on  BA.comp_id			=	BT.comp_id
			and	BA.ba_id			=	BT.ba_id

			inner join	dbo.tbsysCurrency					CU
			on	BT.curr_id			=	CU.curr_id

			inner join	dbo.tbBanksName						BN
			on	BA.bn_id			=	BN.bn_id

			LEFT JOIN tbCheckPortfolio						tcp1
			ON	tcp1.comp_id		= BT.comp_id AND
				tcp1.chp_id			= BT.chp_id

			LEFT JOIN tbEmmitedChecks						tec
			ON	tec.comp_id			= bt.comp_id AND
				tec.ec_id			= bt.ec_id


	Where	BT.comp_id	= @comp_id
	and		(@bn_id		= -1	or BN.bn_id		= @bn_id)
	and		(@btt_id	= -1	or vbtt.btt_id	= @btt_id)
	and		BA.ba_id	= @ba_id
	and		(BT.bt_imputationDate	between @datefrom and @dateto)
	and		ISNULL(BT.bt_isConciliated,'False') = @is_conciliated
	AND		(tct.sd_id <> 142 OR bt.btt_id = 1000004)

END
GO












CREATE PROCEDURE [dbo].[spBankingTransactions_getDataById]
(
		@comp_id		int,
