GO







CREATE procedure [dbo].[spBankingTransactions_getList]
(
	@comp_id			INT,
	@ba_id				INT,
	@curr_id			INT,
	@bra_id				INT,
	@btt_id				INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@bitIsSold			BIT,
	@optionNumber		INT,
	@numberFrom			nvarchar(50),
	@optionTotal		INT,
	@totalFrom		DECIMAL(19,4),
	@totalTo		DECIMAL(19,4),
	@ct_transaction		INT
)
AS


BEGIN

	set nocount on
	SET DATEFORMAT 'ymd'

	-- -------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------
	/*

	declare	@comp_id		int,
			@ba_id			int,
			@curr_id		int,
			@btt_id			INT,
			@datefrom			DATETIME,
			@dateto				DATETIME

	select	@comp_id		= 1,
			@ba_id			= 31,
			@curr_id		= 1,
			@btt_id			= 10000020,
			@datefrom		= '2013-01-01',
			@dateto			= '2013-12-31'

	*/
	-- -------------------------------------------------------


		---- -----------------------------------------------------------------------------------------------------------------
		---- Pongo en una tabla las Sucursales que pertenecen al grupo de sucursales de la actual sucursal incluida la actual.
		---- -----------------------------------------------------------------------------------------------------------------
		--DECLARE @tbBranchsOfBranchGroup TABLE(bra_id INT PRIMARY KEY)
		--DECLARE @intBragID AS INT
		--SELECT @intBragID = tb.brag_id
		--	FROM tbBranch tb								WITH (NOLOCK)
		--	WHERE	tb.comp_id	= @comp_id AND
		--			tb.bra_id	= @bra_id
		--INSERT INTO @tbBranchsOfBranchGroup (bra_id) VALUES (@bra_id)
		--IF @intBragID IS NOT NULL
		--	BEGIN
		--		INSERT INTO @tbBranchsOfBranchGroup
		--			SELECT DISTINCT tbgd.bra_id
		--				FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
		--				WHERE	tbgd.brag_id = @intBragID AND
		--						tbgd.bra_id <> @bra_id
		--	END
		---- -----------------------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------------------------------
		-- Pongo en una tabla las Sucursales que pertenecen al grupo de sucursales de la actual sucursal incluida la actual.
		-- -----------------------------------------------------------------------------------------------------------------
		DECLARE @bitBranchsOfGroup AS BIT = 'False'
		IF @bra_id < 0
			BEGIN
				SET @bra_id				= @bra_id * -1
				SET @bitBranchsOfGroup	= 'True'
			END
		DECLARE @tbBranchsOfBranchGroup TABLE(bra_id INT PRIMARY KEY)
		DECLARE @intBragID AS INT
		SELECT @intBragID = tb.brag_id
			FROM tbBranch tb	WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id
		INSERT INTO @tbBranchsOfBranchGroup (bra_id) VALUES (@bra_id)
		IF	@intBragID IS NOT NULL AND
			@bitBranchsOfGroup = 'True'
			BEGIN
				INSERT INTO @tbBranchsOfBranchGroup
					SELECT DISTINCT  tbgd.bra_id
						FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
						WHERE	tbgd.comp_id = @comp_id		AND
								tbgd.brag_id = @intBragID	AND
								tbgd.bra_id <> @bra_id
			END
		-- -----------------------------------------------------------------------------------------------------------------


	DECLARE @strDocument AS NVARCHAR(10)
	set @strDocument = 'Planilla:'

	SET @dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'true')


	select	TOP 5000
			ltrim(rtrim(convert(varchar(9),BT.ba_id))) + '-' +	ltrim(rtrim(convert(varchar(9),BT.bt_id))) [ID],
			--BN.bn_name + ' - ' +
			--BA.ba_desc + ' - ' +
			convert(varchar(10),cp.chp_PayDate,103) + ' - ' +
			'#:' + dbo.fnStrPADL( CP.chp_number,12,'0') + ' - ' +

			SC.curr_symbol + ' ' +
			dbo.fnStrPADL( convert(varchar,convert(DECIMAL(18,2),BT.bt_total)),13,'0') + ' - ' +
			@strDocument + tct.ct_docNumber + ' ' +
			convert(varchar(10),BT.bt_imputationDate,103) + ' * ' +
			dbo.fnStrPADR( SUBSTRING(isnull(bn.bn_name,'*'),1,30),30,' ')
			[Desc]


	from	dbo.tbBankingTransactions		BT						WITH (NOLOCK)

			inner join tbCheckPortfolio		CP						WITH (NOLOCK)
				on  CP.comp_id	= BT.comp_id
				and CP.chp_id	= BT.chp_id
				and	cp.chp_isAvailable	= 'False'

			INNER JOIN @tbBranchsOfBranchGroup tmp
				ON tmp.bra_id = cp.bra_id_PortFolio

			inner join tbBankingAccounts	BA						WITH (NOLOCK)
				on  BA.comp_id	= BT.comp_id
				and BA.ba_id	= BT.ba_id

			inner join tbsysCurrency		SC						WITH (NOLOCK)
				on SC.[curr_id]	= BT.curr_id

			INNER JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
				ON	tct.comp_id			= BT.comp_id
				AND tct.ct_transaction	= BT.ct_transaction

			LEFT join tbBanksName			BN						WITH (NOLOCK)
				on BN.bn_id				= cp.bn_id



	WHERE 		BT.comp_id				= @comp_id
		AND 	BT.ba_id				= @ba_id
		AND 	BT.curr_id				= @curr_id
		AND 	BT.btt_id				= @btt_id
		AND     BT.bt_isCancelled		= 'False'
		AND		cp.chp_PayDate BETWEEN @datefrom AND @dateto
		--AND		bt.bt_imputationDate	BETWEEN @datefrom AND @dateto
		and		CASE	-- Solo trae los Vendidos o No Vendidos segun seleccion de la pagina.
					WHEN @bitIsSold = 'False' AND cp.chp_isPayed = 'False' THEN 'True'
					WHEN @bitIsSold = 'True'  AND cp.chp_isPayed = 'True' AND cp.chp_isNegociated = 'True'  THEN 'True'
					ELSE 'False'
				END	= 'True'


	and		(
			(@optionNumber = -1)													or
			(@optionNumber = 0 and CP.chp_number like @numberFrom + '%')			or
			(@optionNumber = 1 and CP.chp_number like '%' +  @numberFrom + '%')	or
			(@optionNumber = 2 and CP.chp_number = @numberFrom)					or
			(@optionNumber = 3 and CP.chp_number <> @numberFrom)					or
			(@optionNumber = 4 and CP.chp_number not like '%' +  @numberFrom + '%')
			)
	and		(
			(@optionTotal = -1)														or
			(@optionTotal = 0 and CP.chp_total = @totalFrom)						or
			(@optionTotal = 1 and CP.chp_total > @totalFrom)						or
			(@optionTotal = 2 and CP.chp_total < @totalFrom)						or
			(@optionTotal = 3 and CP.chp_total between @totalFrom and @totalTo)
			)

	AND CASE
	        WHEN @ct_transaction	= 0					THEN 1
	        WHEN bt.ct_transaction	= @ct_transaction	THEN 1
	        ELSE											 0
	    END = 1
	ORDER BY cp.chp_PayDate DESC ,cp.chp_number ASC

	--ORDER BY bt.bt_imputationDate DESC, bt.ct_transaction ASC


END
GO







-- Verificar porque no trae la lista de Documentos marcados como Acreditados para poder des-acreditarlos.

CREATE procedure [dbo].[spBankingTransactions_getListAcredit]
(
		@comp_id		int,
		@bra_id			INT,
		@ba_id			int,
		@curr_id		int,
		@btt_id			INT,
		@datefrom			DATETIME,
		@dateto				DATETIME,
		@bitIsSold			bit,
		@ct_transaction		INT
)
AS

BEGIN



	set nocount on
	SET DATEFORMAT 'ymd'
	-- ----------------------------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------------------------
	/*
	declare
			@comp_id		int,
			@ba_id			int,
			@curr_id		int,
			@btt_id			INT,
			@datefrom			DATETIME,
			@dateto				DATETIME,
			@bitIsSold			bit

	select
			@comp_id		= 1,
			@ba_id			= 49,
			@curr_id		=1,
			@btt_id			=1000020,
			@datefrom		='2000-01-01',
			@dateto			='2020-12-31',
			@bitIsSold		='False'
	*/
	-- ----------------------------------------------------------------------------------


		---- -----------------------------------------------------------------------------------------------------------------
		---- Pongo en una tabla las Sucursales que pertenecen al grupo de sucursales de la actual sucursal incluida la actual.
		---- -----------------------------------------------------------------------------------------------------------------
		--DECLARE @tbBranchsOfBranchGroup TABLE(bra_id INT PRIMARY KEY)
		--DECLARE @intBragID AS INT
		--SELECT @intBragID = tb.brag_id
		--	FROM tbBranch tb								WITH (NOLOCK)
		--	WHERE	tb.comp_id	= @comp_id AND
		--			tb.bra_id	= @bra_id
		--INSERT INTO @tbBranchsOfBranchGroup (bra_id) VALUES (@bra_id)
		--IF @intBragID IS NOT NULL
		--	BEGIN
		--		INSERT INTO @tbBranchsOfBranchGroup
		--			SELECT DISTINCT tbgd.bra_id
		--				FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
		--				WHERE	tbgd.brag_id = @intBragID AND
		--						tbgd.bra_id <> @bra_id
		--	END
		---- -----------------------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------------------------------
		-- Pongo en una tabla las Sucursales que pertenecen al grupo de sucursales de la actual sucursal incluida la actual.
		-- -----------------------------------------------------------------------------------------------------------------
		DECLARE @bitBranchsOfGroup AS BIT = 'False'
		IF @bra_id < 0
			BEGIN
				SET @bra_id				= @bra_id * -1
				SET @bitBranchsOfGroup	= 'True'
			END
		DECLARE @tbBranchsOfBranchGroup TABLE(bra_id INT PRIMARY KEY)
		DECLARE @intBragID AS INT
		SELECT @intBragID = tb.brag_id
			FROM tbBranch tb	WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id
		INSERT INTO @tbBranchsOfBranchGroup (bra_id) VALUES (@bra_id)
		IF	@intBragID IS NOT NULL AND
			@bitBranchsOfGroup = 'True'
			BEGIN
				INSERT INTO @tbBranchsOfBranchGroup
					SELECT DISTINCT  tbgd.bra_id
						FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
						WHERE	tbgd.comp_id = @comp_id		AND
								tbgd.brag_id = @intBragID	AND
								tbgd.bra_id <> @bra_id
			END
		-- -----------------------------------------------------------------------------------------------------------------


	DECLARE @strDocument AS NVARCHAR(10)
	set @strDocument = 'Planilla:'



	select	TOP 15000
			ltrim(rtrim(convert(varchar(9),BT.ba_id))) + '-' +
			ltrim(rtrim(convert(varchar(9),BT.bt_id))) + '-' +
			ltrim(rtrim(convert(varchar(9),BT.chp_id)))								 [ID],
			convert(varchar(10),cp.chp_PayDate,103) + ' - ' +
			'#:' + dbo.fnStrPADL( CP.chp_number,12,'0') + ' - ' +

			SC.curr_symbol + ' ' +
			dbo.fnStrPADL( convert(varchar,convert(DECIMAL(18,2),BT.bt_total)),13,'0') + ' - ' +
			@strDocument + tct.ct_docNumber + ' ' +
			convert(varchar(10),BT.bt_imputationDate,103) + ' * ' +
			dbo.fnStrPADR( SUBSTRING(IsNull(bn.bn_name,'*'),1,30),30,' ')
			[Desc]

	from	dbo.tbBankingTransactions		BT
			inner join tbBankingAccounts	BA					WITH (NOLOCK)
			on  BA.comp_id	= BT.comp_id
			and BA.ba_id	= BT.ba_id

			inner join tbCheckPortfolio		CP					WITH (NOLOCK)
			on  CP.comp_id	       = BT.comp_id
			and CP.chp_id		   = BT.chp_id

			INNER JOIN @tbBranchsOfBranchGroup tmp
				ON tmp.bra_id = cp.bra_id_PortFolio

			inner join tbsysCurrency		SC					WITH (NOLOCK)
			on SC.[curr_id]	= BT.curr_id

			INNER JOIN tbCommercialTransactions				tct	WITH (NOLOCK)
			ON	tct.comp_id			= BT.comp_id
			AND tct.ct_transaction	= BT.ct_transaction

			LEFT join tbBanksName			BN					WITH (NOLOCK)
				on BN.bn_id		= cp.bn_id

	where	BT.comp_id			= @comp_id
	and		BT.ba_id			= @ba_id
	and		BT.curr_id			= @curr_id
	And		BT.btt_id			= @btt_id
	and	    BT.bt_isCancelled	= 'false'
	and		CP.chp_isAvailable  = 'False'			-- MOS
	and		(CP.chp_isPayed     = 'True' and cp.chp_isNegociated = 'False' )  -- Solo debe informar los DEPOSITADOS y NO los VENDIDOS
	AND		cp.chp_PayDate		BETWEEN @datefrom AND @dateto
	AND CASE
	        WHEN @ct_transaction	= 0					THEN 1
	        WHEN bt.ct_transaction	= @ct_transaction	THEN 1
	        ELSE											 0
	    END = 1

	ORDER BY cp.chp_PayDate DESC ,cp.chp_number ASC


END
GO







