CREATE PROCEDURE [dbo].[spBankingTransactions_getReport]
(
	@comp_id			INT,
	@lang_id			INT,
	@page_id			INT,
	@ba_id				INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@bt_sold			INT,
	@brag_id			INT,
	@optionreport		INT, -- optval_class =325 1 : Reporte Estandar , 2 : Reporte de Saldos Presupuestados(ApplyTo) , 3 : Reporte Estandar sin detalle de liq t.credito
	@bra_id				INT,
	@intBranch4Lang		INT,
	@user_id			INT
)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'
	 --CUSTOM_GN_001

	------------------------------------------------------------------------------
	--PARAMETROS PARA PRUEBAS-----------------------------------------------------
	------------------------------------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@lang_id	INT,
		@page_id	INT,

		@bra_id     INT,
		@ba_id		INT,
		@datefrom	DATETIME,
		@dateto		DATETIME,
		@bt_sold    INT,
		@intBranch4Lang		INT,
		@brag_id				INT

	SELECT
		@comp_id	=1,
		@lang_id	=2,
		@page_id	=10043,

		@bra_id     =1,
		@ba_id		=35,
		@datefrom	='1999-01-01',
		@dateto		='2911-12-31',
		@bt_sold    = -1,
		@intBranch4Lang = 1,
		@brag_id	 = 4

	DROP TABLE #tmp_BankTrans
	DROP TABLE #tmp_BT_TMP
	*/
	------------------------------------------------------------------------------
	------------------------------------------------------------------------------


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	set	@datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	CREATE TABLE #tmp_BT_TMP
		(
			id				INT,
			id2				INT,
			credito			DECIMAL(18,5),
			debito			DECIMAL(18,5),
			suma			DECIMAL(18,5),
			total2			DECIMAL(18,5),
			ct_transaction  INT
		)


	CREATE TABLE #tmp_BankTrans
		(
		ID							INT,
		ID2							INT,
		btt_desc					NVARCHAR(200),
		bt_imputationDate			DATETIME,
		Number						NVARCHAR(200),
		bt_note						NVARCHAR(200),
		bt_Number					NVARCHAR(200),
		Is_Paid						BIT,
		Total						DECIMAL(19,4),
		Is_Credit					BIT,
		isChp						BIT,
		ct_transaction				INT,
		bt_id						INT,
		btt_id						INT,
		ecct_id						INT,
		chp_isNegociated			bit,
		chp_isCustodia				bit
		)

	DECLARE @datFirstDate AS DATETIME
	SET @datFirstDate = convert(DATETIME,'1760-01-01')
	EXEC spBankingTransactions_GenerateData4Reports
													@comp_id	,
													@lang_id	,
													@page_id	,
													@ba_id		,
													@datFirstDate, -- Pide TODOS los Movimientos.!!!  --@datefrom	,
													@dateto		,
													@bt_sold    ,
													@bra_id,
													@brag_id,
													@user_id


--==
--SELECT * FROM #tmp_BankTrans WHERE bt_number LIKE '%77471246%'
--==

	DECLARE @fun_id INT
	SET @fun_id = 1


	DECLARE @suma AS DECIMAL(19,5)
	SET @suma = 0

	DECLARE @suma2 AS DECIMAL(19,5)
	SET @suma2 = 0

	DECLARE @suma3 AS DECIMAL(19,5)
	SET @suma3 = 0






	SELECT
			tmp1.id,
			CASE
			    WHEN tct.sd_id = 200 AND tmp1.chp_isNegociated = 'True' THEN	'1-Venta de Valores'
			    WHEN tct.sd_id = 200 AND tmp1.chp_isCustodia   = 'True'	THEN	'1-Depósito de Custodia'
			    WHEN IsNull(tmp1.ecct_id,0) > 0							THEN	convert(nvarchar(50),teccb.ecct_desc)
			    ELSE															convert(nvarchar(50),tmp1.btt_desc)
			END
															collate database_default	[btt_desc],
			tmp1.bt_imputationDate,
			isnull(tmp1.Number,'')			[Number],

		 	isnull(tmp1.bt_note,'') collate database_default +
			CASE
				WHEN NOT tctop.comp_id IS NULL	THEN tctop.op_paymentTo
				WHEN not tct.cust_id IS NULL	THEN ' // ' + tc.cust_name
				WHEN NOT tct.supp_id IS NULL	THEN ' // ' + ts.supp_name
				ELSE ''
			END								[bt_note],

			isnull(tmp1.bt_Number,'')		[bt_Number],
			tmp1.Total,
			tmp2.credito,
			TMP2.debito,
			tmp2.suma,
			tmp2.total2,
			tmp2.ct_transaction,
			CONVERT(NVARCHAR,
			CASE
			    WHEN tct.cust_id IS NOT NULL	THEN tc.cust_name
			    WHEN tct.supp_id IS NOT NULL	THEN ts.supp_name
			    WHEN tct.ba_id   IS NOT NULL	THEN tba.ba_desc
			    ELSE								 ''
			END	   )													[ApplyTo],
			IDENTITY(int, 0,400) AS printOrder

	INTO	#tmpFinal
	FROM	#tmp_BankTrans								tmp1

			LEFT JOIN #tmp_BT_TMP						tmp2
			ON	tmp2.id				= tmp1.id		AND
				isnull(tmp2.id2,-1) = isnull(tmp1.id2,-1)

			LEFT JOIN tbCommercialTransactions			tct		WITH (NOLOCK)
			ON	tct.comp_id			= @comp_id		AND
				tct.ct_transaction	= tmp2.ct_transaction

			LEFT JOIN tbCustomer						tc		WITH (NOLOCK)
			ON	tc.comp_id			= @comp_id		AND
				tc.cust_id			= tct.cust_id

			LEFT JOIN tbSupplier						ts		WITH (NOLOCK)
			ON	ts.comp_id			= @comp_id		AND
				ts.supp_id			= tct.supp_id

			LEFT JOIN tbBankingAccounts tba						WITH (NOLOCK)
				ON	tba.comp_id		= tct.comp_id		AND
					tba.ba_id		= tct.ba_id

			LEFT JOIN tbEmmitedChecks_CheckBook teccb			WITH (NOLOCK)
				ON	teccb.comp_id = @comp_id AND
					teccb.ecct_id = tmp1.ecct_id

			LEFT JOIN tbCommercialTransactionsOtherPayments tctop	WITH (NOLOCK)
				ON	tctop.comp_id			= tct.comp_id AND
					tctop.ct_transaction	= tct.ct_transaction


	WHERE	tmp1.bt_imputationDate >= @datefrom

	ORDER BY	tmp1.bt_imputationDate,
				tmp1.bt_id,
				tmp1.ct_transaction,
				tmp2.ct_transaction,
				tmp1.ID,
				tmp1.ID2


--==
--SELECT * FROM #tmpFinal WHERE bt_number LIKE '%77471246%'
--==







	-- Inserta detalle de liquidacion de tarjetas de credito
	DECLARE curTmpFinal CURSOR LOCAL FAST_FORWARD FOR
	SELECT tmp.printOrder,

	       ttn.tax_desc													[Desc],
	       CASE
	           WHEN tmp.credito <> 0 THEN ISNULL(ttm.tm_total,0)
	           ELSE	0
	       END															[Credito],
	       CASE
	           WHEN tmp.debito  <> 0 THEN ISNULL(ttm.tm_total,0)
	           ELSE	0
	       END															[Debito],
	       CASE	-- MOS 09-2017
				WHEN tct.supp_id4CreditCardLiquidation IS NOT NULL THEN '(' + CONVERT(NVARCHAR(10),tct.supp_id4CreditCardLiquidation) + ') ' + tmp.bt_Number
				ELSE													tmp.bt_Number
	       END,
	       tc.curr_symbol


		FROM #tmpFinal							tmp
		INNER JOIN tbCommercialTransactions tct					WITH (NOLOCK)
			ON	tct.comp_id			= @comp_id				AND
				tct.ct_transaction	= tmp.ct_transaction
		INNER JOIN tbTaxMovements				ttm				WITH (NOLOCK)
			ON	ttm.comp_id			= tct.comp_id			AND
				ttm.ct_transaction	= tct.ct_transaction
		INNER JOIN tbTaxName						ttn			WITH (NOLOCK)
			ON	ttn.comp_id			= ttm.comp_id			AND
				ttn.tax_id			= ttm.tax_id
		INNER JOIN tbsysCurrency tc								WITH (NOLOCK)
			ON tc.curr_id			= ttm.curr_id

		WHERE tct.sd_id IN (140,141,142)	AND
			 (ttm.comp_id IS NOT NULL )

		UNION

		SELECT tmp.printOrder,
	        tpc.puco_desc													[Desc],
	       CASE
	           WHEN tmp.credito <> 0 THEN ISNULL(tpcm.pcm_total,0)
	           ELSE	0
	       END															[Credito],
	       CASE
	           WHEN tmp.debito  <> 0 THEN ISNULL(tpcm.pcm_total,0)
	           ELSE	0
	       END															[Debito],
	       CASE	-- MOS 09-2017
				WHEN tct.supp_id4CreditCardLiquidation IS NOT NULL THEN '(' + CONVERT(NVARCHAR(10),tct.supp_id4CreditCardLiquidation) + ') ' + tmp.bt_Number
				ELSE													tmp.bt_Number
	       END,
	       tc.curr_symbol


		FROM #tmpFinal							tmp
		INNER JOIN tbCommercialTransactions tct							WITH (NOLOCK)
			ON	tct.comp_id			= @comp_id				AND
				tct.ct_transaction	= tmp.ct_transaction
		INNER JOIN tbPurchaseConceptMovements	tpcm					WITH (NOLOCK)
			ON	tpcm.comp_id		= tct.comp_id			AND
				tpcm.ct_transaction = tct.ct_transaction
		INNER JOIN tbPurchaseConcept				tpc					WITH (NOLOCK)
			ON	tpc.comp_id			= tpcm.comp_id					AND
				tpc.puco_id			= tpcm.puco_id
		INNER JOIN tbsysCurrency tc										WITH (NOLOCK)
			ON tc.curr_id = tpcm.curr_id
		WHERE tct.sd_id IN (140,141,142)	AND
			 (tpcm.comp_id IS NOT NULL)





	SET IDENTITY_INSERT #tmpFinal ON
	DECLARE @intPrintOrder	AS INT
	DECLARE @intLastPrintOrder	AS INT
	DECLARE @strDesc		AS NVARCHAR(45)  -- Si se lo pone mas grande da error en el insert de abajo.!  De ultima crear la remporal a mano y luego hacer inserts
	DECLARE @decCredit		AS DECIMAL(19,2)
	DECLARE @decDebit		AS DECIMAL(19,2)
	DECLARE @intCounter		AS INT
	DECLARE @strBt_Number	AS NVARCHAR(150)
	DECLARE @strCurrency	AS NVARCHAR(3)
	SET		@intCounter		= 1
	OPEN	curTmpFinal

	FETCH NEXT FROM curTmpFinal INTO @intPrintOrder,@strDesc,@decCredit,@decDebit,@strBt_Number,@strCurrency
	SET @intLastPrintOrder = @intPrintOrder
	WHILE @@FETCH_STATUS = 0
		BEGIN
			IF @optionreport <> 3
				BEGIN



					INSERT INTO #tmpFinal
										(	printOrder,
											credito,
											debito,
											Number,
											bt_number,
											btt_desc,
											bt_note
										)
										VALUES (
												@intPrintOrder + @intCounter,
												@decCredit,
												@decDebit,
												'-->>' ,
												@strBt_Number,
												'    ' + @strDesc,
												@strCurrency
												)
				END

			FETCH NEXT FROM curTmpFinal INTO @intPrintOrder,@strDesc,@decCredit,@decDebit,@strBt_Number,@strCurrency
			IF @intLastPrintOrder <> @intPrintOrder
				BEGIN
					SET @intCounter			= 0
					SET @intLastPrintOrder	= @intPrintOrder
				END
			SET	@intCounter	= @intCounter + 1
		END
	CLOSE		curTmpFinal
	DEALLOCATE  curTmpFinal
	SET IDENTITY_INSERT #tmpFinal OFF


--==
--SELECT 'AAA',* FROM #tmpFinal WHERE bt_number LIKE '%77471246%' ORDER BY printOrder
--==


	SELECT *
		FROM #tmpFinal
		ORDER BY printOrder

	DROP TABLE #tmpFinal




	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t 	WITH (NOLOCK) INNER JOIN tbSysWordsNew tswn	WITH (NOLOCK)  ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 406
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params1],



	--
	 CASE @ba_id WHEN -1 THEN
					(SELECT	 tut.utexts_desc
					 FROM	 tbsysUniqueTexts tut	WITH (NOLOCK)
					 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tba.ba_desc
			 FROM tbBankingAccounts tba	WITH (NOLOCK)

			 WHERE tba.comp_id = @comp_id
			 AND   tba.ba_id = @ba_id)
			END		[params2],

	--


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t 	WITH (NOLOCK) INNER JOIN tbSysWordsNew tswn 	WITH (NOLOCK) ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 177
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params3],

			@datefrom [DateParams1],
			--convert(varchar,day(@datefrom))+'/'+convert(varchar,month(@datefrom))+'/'+convert(varchar,year(@datefrom))		[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 384
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params5],

			@dateto [DateParams2],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t 	WITH (NOLOCK) INNER JOIN tbSysWordsNew tswn	WITH (NOLOCK)  ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 556
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params6],


	 CASE @bt_sold WHEN -1 THEN
					(SELECT	 tut.utexts_desc
					 FROM	 tbsysUniqueTexts tut		WITH (NOLOCK)
					 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tov.optval_desc FROM tbsysOptionsValues tov	WITH (NOLOCK)
					 WHERE tov.optval_class = 86
					 and tov.optval_id = @bt_sold
					 AND tov.lang_id = @lang_id
					)
			END		[params7],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t 	WITH (NOLOCK)
						INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 639
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params8],

					(SELECT	tbg.brag_desc FROM tbBranchGroup tbg	WITH (NOLOCK)
					 WHERE tbg.comp_id = @comp_id
					 AND tbg.brag_id = @brag_id			)									[params9]



END
GO






-- --------------------------------------------------------------------------------
-- ATENCION.!  Si se toca algo aca hacerlo tambien en [spGeneralBalance_getReport]
-- --------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[spBankingTransactions_getReportOld]
(
	@comp_id	INT,
	@lang_id	INT,
	@page_id	INT,


	@ba_id		INT,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@bt_sold    INT,
	@bra_id     INT
)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	------------------------------------------------------------------------------
	--PARAMETROS PARA PRUEBAS-----------------------------------------------------
	------------------------------------------------------------------------------
/*
	DECLARE
		@comp_id	INT,
		@lang_id	INT,
		@page_id	INT,

		@bra_id     INT,
		@ba_id		INT,
		@datefrom	DATETIME,
		@dateto		DATETIME,
		@bt_sold    INT

	SELECT
		@comp_id	=1,
		@lang_id	=2,
		@page_id	=10043,

		@bra_id     =-1,
		@ba_id		= 2,
		@datefrom	='2010-01-01',
		@dateto		='2999-01-30',
		@bt_sold    = -1

	DROP TABLE #tmp_BankTrans
	DROP TABLE #tmp_BT_TMP
*/
	------------------------------------------------------------------------------
	------------------------------------------------------------------------------

	DECLARE @fun_id INT
	SET @fun_id = 1


	DECLARE @suma AS DECIMAL(19,5)
	SET @suma = 0

	DECLARE @suma2 AS DECIMAL(19,5)
	SET @suma2 = 0

	DECLARE @suma3 AS DECIMAL(19,5)
	SET @suma3 = 0



	SELECT
		tbt.bt_id								[ID],
		tcp1.chp_id								[ID2],
		vbtt2.btt_desc	+ '*1'					[btt_desc],
		tbt.bt_imputationDate,
		tcp1.chp_number							[Number],
		tbt.bt_note,
		tbt.bt_Number,
		isnull(tcp1.chp_IsPayed,'false')		[Is_Paid],
		tbt.bt_total							[Total],
		vbtt2.btt_isCredit						[Is_Credit],
		case when tcp1.chp_id IS NULL THEN 'false' ELSE 'true' END [isChp],
		tbt.ct_transaction

	INTO #tmp_BankTrans

	FROM tbBankingTransactions tbt

		left JOIN tbCheckPortfolioMovements tcpm
		ON		tcpm.comp_id		= tbt.comp_id
			AND tcpm.ct_transaction = tbt.ct_transaction
			AND tcpm.bra_id			= tbt.bra_id
			AND tcpm.chp_id			= tbt.chp_id

		LEFT JOIN tbCheckPortfolio tcp1
		ON	tcp1.comp_id	= tbt.comp_id
		AND tcp1.chp_id		= tcpm.chp_id

		INNER JOIN vwBankingTransactionTypes vbtt2
		ON vbtt2.btt_id = tbt.btt_id

		INNER JOIN tbBankingAccounts tba
		ON  tba.comp_id = tbt.comp_id
		AND tba.ba_id	= tbt.ba_id

		INNER JOIN tbCommercialTransactions tct
		ON	tct.comp_id = tbt.comp_id
		AND tct.bra_id = tbt.bra_id
		AND tct.ct_transaction = tbt.ct_transaction

		INNER JOIN tbUsers4BranchFilter vubf
		ON vubf.comp_id = tct.comp_id
		AND vubf.bra_id = tct.bra_id
		AND vubf.[user_id] = tct.[user_id]

	WHERE tbt.comp_id = @comp_id
	AND (@ba_id = -1 or tbt.ba_id = @ba_id)
	AND tbt.bt_imputationDate BETWEEN @datefrom AND @dateto
	AND tbt.btt_id <> 1000001
	AND (@bt_sold = -1 OR  tbt.bt_Sold = @bt_sold)
	AND (	   (tct.sd_id BETWEEN 200 AND 299)
			OR  vbtt2.btt_id = 1000002
		)	-- Solo Movimientos Bancarios o Rechazo de Valores


	UNION

	-- Valores Emitidos.  *2
	SELECT
		tbt.bt_id								[ID],
		tec.ec_id								[ID2],
		vbtt2.btt_desc	+ '*2'					[btt_desc],
		tbt.bt_imputationDate,
		tec.ec_Number							[Number],
		tbt.bt_note,
		tbt.bt_Number,
		tec.ec_isPaid							[Is_Paid],
		tec.ec_Total							[Total],
		vbtt2.btt_isCredit						[Is_Credit],
		case when tec.ec_id IS NULL THEN 'false' ELSE 'true' END [isChp],
		tbt.ct_transaction


	FROM tbBankingTransactions tbt

		INNER  JOIN tbEmmitedChecks tec
		ON tec.ct_transaction = tbt.ct_transaction
		AND tec.ec_id = tbt.ec_id
		AND tec.comp_id = tbt.comp_id

		INNER JOIN vwBankingTransactionTypes vbtt2
		ON vbtt2.btt_id = tbt.btt_id

		INNER JOIN tbBankingAccounts tba
		ON  tba.comp_id = tbt.comp_id	AND tba.ba_id = tbt.ba_id

		INNER JOIN tbCommercialTransactions tct
		ON	tct.comp_id = tbt.comp_id
		AND tct.bra_id = tbt.bra_id
		AND tct.ct_transaction = tbt.ct_transaction

		INNER JOIN tbUsers4BranchFilter vubf
		ON vubf.comp_id = tct.comp_id
		AND vubf.bra_id = tct.bra_id
		AND vubf.[user_id] = tct.[user_id]

	WHERE tbt.comp_id = @comp_id
	AND (@ba_id = -1 or tbt.ba_id = @ba_id)
	AND tbt.bt_imputationDate BETWEEN @datefrom AND @dateto
	AND (@bt_sold = -1 OR  tbt.bt_Sold =@bt_sold)



	--==STL Aca se añadieron todos los movimientos que no se habian tenido en cuenta (Liq. de Tarjeta/Dep. en Efectivo/Mov. Cred y Mov. Deb)
	UNION
	SELECT
		tct.ct_transaction																[ID],
		td.sd_id																		[ID2],
		(
			SELECT TOP 1 vbtt2.btt_desc
				FROM tbBankingTransactions tbt
				INNER JOIN vwBankingTransactionTypes vbtt2
					ON	   vbtt2.btt_id = tbt.btt_id
			WHERE tbt.ct_transaction = tct.ct_transaction
		)	+ '*3'													[btt_desc],
		--vbtt2.btt_desc	+ '*3'															[btt_desc],
		tct.ct_date,
		dbo.fnGetCommercialTransactionDescription(1,2,tct.ct_transaction)	[Number],
		''      																		[bt_note],
		''																				[bt_Number],
		isnull(vwctbt.is_paid,'false')													[Is_Paid],
		tct.ct_total																	[Total],
		vwctbt.sd_iscredit																[Is_Credit],
		'false',
		tct.ct_transaction

	FROM tbCommercialTransactions tct

		inner JOIN vwCommercialTransactions_forBankingTransactions	vwctbt
		ON vwctbt.ct_transaction = tct.ct_transaction

		inner JOIN tbBankingAccounts tba
		ON tba.comp_id = tct.comp_id
		AND tba.ba_id = tct.ba_id

		-- mos cambio left por inner  02-2011
--		inner JOIN tbBankingTransactions tbt  --==STL o es solo INNER?
--		ON tbt.comp_id = tct.comp_id
--		AND tbt.bra_id = tct.bra_id
--		AND tbt.ct_transaction = tct.ct_transaction

		INNER JOIN tbsysDocuments td
		ON td.sd_id = vwctbt.sd_id

		INNER JOIN tbUsers4BranchFilter vubf
		ON vubf.comp_id = tct.comp_id
		AND vubf.bra_id = tct.bra_id
		AND vubf.[user_id] = tct.[user_id]

--		INNER JOIN vwBankingTransactionTypes vbtt2
--		ON vbtt2.btt_id = tbt.btt_id



	WHERE	tct.comp_id		=1
	AND		tba.ba_id		= @ba_id
	AND		tct.ct_date	BETWEEN @datefrom AND @dateto
	--AND		(@bt_sold		= -1 OR tbt.bt_Sold = @bt_sold)		NOOO
	AND		tct.sd_id		<> 251	-- todos los sd menos cheques rechazados
	AND		tct.sd_id		<> 200	-- todos los sd menos Cheques Depositados


	ORDER BY bt_imputationDate,ct_transaction
	--bt_imputationDate,ct_transaction

   		         		      		--
	--AND (@bt_sold = -1 OR  isnull(tbt.bt_Sold,'false') = convert(bit,@bt_sold))   NOOO

--==
--SELECT * FROM #tmp_BankTrans
--==
	/*-------------------------------------------------------------------------------------------*/





	/*Cursor*/
	DECLARE
		@id			INT,
		@id2		INT,
		@total		DECIMAL(19,5),
		@is_payed	BIT,
		@is_credit	BIT,
		@value		DECIMAL(19,5),
		@isChp		BIT,
		@ct_transaction	INT


	CREATE TABLE #tmp_BT_TMP
	(
		id				INT,
		id2				INT,
		credito			DECIMAL(18,5),
		debito			DECIMAL(18,5),
		suma			DECIMAL(18,5),
		total2			DECIMAL(18,5),
		ct_transaction  INT
	)



	DECLARE cursor_BT_gR CURSOR FOR
	SELECT Id, Id2, Total, Is_Paid, Is_Credit, isChp,ct_transaction
	FROM #tmp_BankTrans

	OPEN cursor_BT_gR

	FETCH NEXT FROM cursor_BT_gR
	INTO @id,
		 @id2,
		 @total,
		 @is_payed,
		 @is_credit,
		 @isChp,
		 @ct_transaction

	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF @is_payed = 'True'
			BEGIN
				IF @is_credit = 'True'
					BEGIN
						set @suma = @suma + @total
						SET @suma3 = @suma3 + @total

						Insert into #tmp_BT_TMP
						(id, Id2, credito, debito,suma, total2,ct_transaction)
						values
						(@Id, @id2, @total, 0,@suma3,@suma,@ct_transaction)
					END
				ELSE
					BEGIN
						set @suma = @suma - @total
						SET @suma3 = @suma3  - @total

						Insert into #tmp_BT_TMP
						(id, id2, credito, debito,suma, total2,ct_transaction)
						values
						(@Id, @id2, 0, @total,@suma3,@suma,@ct_transaction)
					END
			END
		ELSE
			BEGIN
				IF @is_credit = 'True'
					BEGIN
						if @isChp = 'false' set @suma = @suma + @total
						SET @suma3 = @suma3 + @total

						Insert into #tmp_BT_TMP
						(id, Id2, credito, debito,suma, total2,ct_transaction)
						values
						(@Id, @id2, @total,0, @suma3,@suma,@ct_transaction)
					END
				ELSE
					BEGIN
						if @isChp = 'false' set @suma = @suma - @total
						SET @suma3 = @suma3 - @total

						Insert into #tmp_BT_TMP
						(id, Id2, credito, debito,suma, total2,ct_transaction)
						values
						(@Id, @id2, 0, @total,@suma3,@suma,@ct_transaction)
					END
			END




		FETCH NEXT FROM cursor_BT_gR
		INTO @id,
			 @id2,
			 @total,
			 @is_payed,
			 @is_credit,
			 @isChp,
			 @ct_transaction


	END

	CLOSE cursor_BT_gR
	DEALLOCATE cursor_BT_gR
	--/*----------------------------------------------------------------------------------------------*/



	--SELECT * FROM #tmp_BankTrans
	--SELECT * FROM #tmp_BT_TMP





	SELECT
		tmp1.id,
		tmp1.btt_desc,
		tmp1.bt_imputationDate,
		isnull(tmp1.Number,'')		[Number],
		tmp1.bt_note,
		isnull(tmp1.bt_Number,'')	[bt_Number],
		tmp1.Total,
		tmp2.credito,
		TMP2.debito,
		tmp2.suma,
		tmp2.total2,
		tmp2.ct_transaction

	FROM	#tmp_BankTrans tmp1
			LEFT JOIN #tmp_BT_TMP tmp2
			ON	tmp2.id  = tmp1.id
			AND isnull(tmp2.id2,-1) = isnull(tmp1.id2,-1)
	ORDER BY tmp1.bt_imputationDate,tmp2.ct_transaction
















	exec [spReports_getData3] @comp_id,@bra_id, @lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 406
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params1],



	--
	 CASE @ba_id WHEN -1 THEN
					(SELECT	 tut.utexts_desc
					 FROM	 tbsysUniqueTexts tut
					 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tba.ba_desc
			 FROM tbBankingAccounts tba

			 WHERE tba.comp_id = @comp_id
			 AND   tba.ba_id = @ba_id)
			END		[params2],

	--


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 177
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params3],

			@datefrom [DateParams1],
			--convert(varchar,day(@datefrom))+'/'+convert(varchar,month(@datefrom))+'/'+convert(varchar,year(@datefrom))		[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 384
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params5],

			@dateto [DateParams2],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 556
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params6],


	 CASE @bt_sold WHEN -1 THEN
					(SELECT	 tut.utexts_desc
					 FROM	 tbsysUniqueTexts tut
					 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tov.optval_desc FROM tbsysOptionsValues tov
					 WHERE tov.optval_class = 86
					 and tov.optval_id = @bt_sold
					)
			END		[params7]





END
GO






CREATE  PROCEDURE [dbo].[spBankingTransactions_insertData]
(
	@comp_id							int,
	@ba_id								int,
	@bra_id								int,
	@btt_id								int,
	@ec_id								int,
	@chp_id								int,
	@bt_total							decimal(19,5),
	@curr_id							int,
	@bt_imputationDate					datetime,
	@bt_isConciliated					bit,
	@bt_isCancelled						bit,
	@ct_transaction						int,
	@ccm_id								int,
	@bt_note							VARCHAR(100),
	@bt_Number							VARCHAR(50),
	@bt_BranchCurrencyExchange			DECIMAL(19,5),
	@return_value						int output
)
AS

BEGIN

	SET NOCOUNT ON

	-- Pone como cancelados a movimientos de deposito anteriores si es que estamos anulando un deposito
	IF @btt_id = 1000021
	BEGIN
		UPDATE tbBankingTransactions
			SET
				bt_isCancelled = 'True'
			WHERE	comp_id		= @comp_id
				AND chp_id		= @chp_id
				AND btt_id		= 1000020
	END


	-- Se inserta el nuevo movimiento
	insert into dbo.tbBankingTransactions
	(
		comp_id,
		ba_id,
		bra_id,
		btt_id,
		ec_id,
		chp_id,
		bt_total,
		curr_id,
		bt_imputationDate,
		bt_isConciliated,
		bt_isCancelled,
		ct_transaction,
		ccm_id,
		bt_note,
		bt_Number,
		bt_BranchCurrencyExchange,bt_Sold

	)
	values
	(
		@comp_id,
		@ba_id,
		@bra_id,
		@btt_id,
		@ec_id,
		@chp_id,
		@bt_total,
		@curr_id,
		@bt_imputationDate,
		@bt_isConciliated,
		@bt_isCancelled,
		@ct_transaction,
		@ccm_id,
		@bt_note,
		@bt_Number,
		@bt_BranchCurrencyExchange,'false'
	)

	set	@return_value = @@identity

END
GO






CREATE PROCEDURE [dbo].[spBankingTransactions_insertDataFromDeposit]
(
	@comp_id							INT,
	@ba_id								INT,
	@bra_id								INT,
	@btt_id								INT,
	@ec_id								INT,
	@bt_sold							BIT,
	--@chp_id							int,
	--@bt_total							decimal(19,5),
	@curr_id							INT,
	@bt_imputationDate					DATETIME,
	@bt_isConciliated					BIT,
	@bt_isCancelled						BIT,
	@ct_transaction						INT,
	@ccm_id								INT,
	@bt_note							VARCHAR(100),
	@bt_Number							VARCHAR(50),
	@bt_BranchCurrencyExchange			DECIMAL(19,5),
	@updateprocess						BIT,					--- El HDP puso este nombre para: TRUE-Deposito, FALSE:Venta
	@guid								UNIQUEIDENTIFIER,
	@return_value						INT 		    OUTPUT,
	@ret_ErrorCode						INT 			OUTPUT,
	@ret_ErrorDescription				VARCHAR(200)	OUTPUT
)
AS

BEGIN



	SET NOCOUNT ON


	/*
	DECLARE	@comp_id							int,
			@ba_id								int,
			@bra_id								int,
			@btt_id								int,
			@ec_id								int,
			--@chp_id								int,
			--@bt_total							decimal(19,5),
			@curr_id							int,
			@bt_imputationDate					datetime,
			@bt_isConciliated					bit,
			@bt_isCancelled						bit,
			@ct_transaction						int,
			@ccm_id								int,
			@bt_note							VARCHAR(100),
			@bt_Number							VARCHAR(50),
			@bt_BranchCurrencyExchange			DECIMAL(19,5),
			@return_value						int
	*/



	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''



    SAVE TRANSACTION traPROTECT
    BEGIN TRANSACTION
    BEGIN TRY


		DECLARE	@chp_id			INT,
				@chp_total		DECIMAL(19,6),
				@lbt_id			INT



		DECLARE cursor_cp CURSOR LOCAL FAST_FORWARD FOR
		SELECT	tcp1.chp_id,
				tcp1.chp_total

			FROM	tbCheckPortfolio tcp1	WITH (NOLOCK)

			WHERE	tcp1.comp_id			= @comp_id
			AND 	chp_isAvailable			= 'True'
			AND 	chp_isPayed				= 'False'
			AND		tcp1.chp_isInProcess	= 'true'
			AND		tcp1.chp_guid			= @guid



		OPEN cursor_cp

		FETCH cursor_cp INTO @chp_id, @chp_total

		WHILE @@FETCH_STATUS = 0
		BEGIN


			--actualizo bankingtransactions
			INSERT INTO dbo.tbBankingTransactions
			(comp_id,		ba_id,		bra_id,				btt_id,				ec_id,			chp_id,
			bt_total,		curr_id,	bt_imputationDate,	bt_isConciliated,	bt_isCancelled,
			ct_transaction,	ccm_id,		bt_note,			bt_Number,			bt_BranchCurrencyExchange,
			bt_Sold)

			VALUES
			(@comp_id, 		@ba_id,		@bra_id,			@btt_id,			@ec_id,			@chp_id,
			@chp_total,		@curr_id,	@bt_imputationDate,	@bt_isConciliated,	@bt_isCancelled,
			@ct_transaction,@ccm_id,	@bt_note,			@bt_Number,			@bt_BranchCurrencyExchange,
			@bt_sold)

			SET @lbt_id	= @@IDENTITY



			--actualizo checkportfoliomovements
			INSERT INTO tbCheckPortfolioMovements
			(comp_id,		bra_id,		chp_id,		ct_transaction,
			mm_isCancelled,	svtt_id,	ba_id,		bt_id)
			VALUES
			(@comp_id,		@bra_id,	@chp_id,	@ct_transaction,
			'False',		40,			@ba_id,		@lbt_id)


			FETCH cursor_cp INTO @chp_id, @chp_total

		END

		CLOSE cursor_cp
		DEALLOCATE cursor_cp


		IF @updateprocess = 'true'
			BEGIN
						UPDATE 	dbo.tbCheckPortfolio
						SET 	chp_isAvailable		= 'False',
								chp_guid			= null,
								chp_isNegociated	= 'False'

						WHERE 	comp_id				= @comp_id
						AND		chp_isInProcess		= 'true'
						AND		chp_guid			= @guid
			END


		else
			BEGIN
						UPDATE 	dbo.tbCheckPortfolio
						SET 	chp_isNegociated	= 'True'

						WHERE 	comp_id				= @comp_id
						AND		chp_guid			= @guid
			END


    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION traPROTECT
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 06-2009
-- Description:	Alta desde wfmPurchaseDocs
-- =============================================
CREATE PROCEDURE [dbo].[spBankingTransactions_insertDataFromPurchaseDocs]
	@comp_id							AS INT,
	@ct_transaction						AS INT,
	@guid								AS UNIQUEIDENTIFIER,
	@decImporteLiquidado				AS DECIMAL(19,6),
	@return_value						as int			output,
	@ret_ErrorCode						as int			output,
	@ret_ErrorDescription				as varchar(200) output
AS


BEGIN
	SET NOCOUNT ON;

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''

	DECLARE @ba_id						AS INT
	DECLARE @bra_id						AS int
	DECLARE @btt_id						AS INT
	DECLARE @bt_total					AS DECIMAL(19,4)
	DECLARE @curr_id					AS INT
	DECLARE @bt_ImputationDate			AS DATETIME
	DECLARE @bt_note					AS VARCHAR(100)
	DECLARE @bt_number					AS VARCHAR(50)
	DECLARE @bt_BranchCurrencyExchange	AS DECIMAL(19,6)
	DECLARE @curr_id_Bank				AS INT
	DECLARE @curr_id_Branch				AS INT
	DECLARE @intSd_Id					AS INT


	-- Obtiene Datos de la Transaccion Comercial
	SELECT	@ba_id				= tct.ba_id,
			@bra_id				= tct.bra_id,
			@bt_ImputationDate	= tct.ct_date,
			@intSd_Id			= tct.sd_id
		FROM tbCommercialTransactions tct	WITH (NOLOCK)
	WHERE	tct.comp_id			= @comp_id
		and tct.ct_transaction	= @ct_transaction

	-- MOneda de la Sucursal
	SELECT @curr_id_Branch	= curr_id
		FROM tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id

	-- Moneda de la Cuenta Bancaria
	SELECT @curr_id_Bank	= tba.curr_id
		FROM tbBankingAccounts tba	WITH (NOLOCK)
		WHERE	tba.comp_id = @comp_id
			AND tba.ba_id	= @ba_id

	-- Obtiene el tipo de cambio de la moneda de la cuenta a la
	-- moneda de la sucursal.-
	Set @bt_BranchCurrencyExchange = dbo.fnGetExchange(@comp_id,
													   1,
													   @curr_id_Bank,
													   @curr_id_Branch,
													   0,
													   0,
													   'false')


	DECLARE @strsupp_id4CreditCardLiquidation AS NVARCHAR(50)
	SET		@strsupp_id4CreditCardLiquidation = 'Credit Card Balance'
	SELECT	@strsupp_id4CreditCardLiquidation = convert(nvarchar(50),tct.supp_id4CreditCardLiquidation)
		FROM tbCommercialTransactions	tct	WITH (NOLOCK)
		INNER JOIN tbSupplier			ts	WITH (NOLOCK)
			ON	ts.comp_id = tct.comp_id AND
				ts.supp_id = tct.supp_id4CreditCardLiquidation
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @ct_transaction

	-- -----------------------------------------------------------------------------
	-- Si es una Liquidacion de Tarjeta de credito se ingresa el importe
	-- liquidado
	-- MOS: 05-2013
	-- -----------------------------------------------------------------------------
	IF @intSd_Id = 142 -- Si es Tarjeta de credito SOLO ingresa el importe Liquidado
		BEGIN

			INSERT INTO tbBankingTransactions
			(
				comp_id,
				ba_id,
				bra_id,
				btt_id,
				ec_id,
				chp_id,
				bt_total,
				curr_id,
				bt_imputationDate,
				bt_isConciliated,
				bt_isCancelled,
				ct_transaction,
				ccm_id,
				bt_note,
				bt_Number,
				bt_BranchCurrencyExchange
			)
			VALUES
				(	@comp_id,
					@ba_id,
					@bra_id,
					1000004,
					NULL,
					NULL,
					@decImporteLiquidado,
					@curr_id_Bank,
					@bt_ImputationDate,
					'False',
					'False',
					@ct_transaction,
					NULL,
					'Credit Card Balance' ,
					@strsupp_id4CreditCardLiquidation,		-- Poner aca el proveedor asociado a la transaccion para q salga en el extracto !!!
					@bt_BranchCurrencyExchange
				)

--			SELECT	tpcmt.comp_id,
--					@ba_id,
--					@bra_id,
--					tpc.btt_id,
--					NULL,
--					NULL,
--					@decImporteLiquidado,
--					@curr_id_Bank,
--					@bt_ImputationDate,
--					'False',
--					'False',
--					@ct_transaction,
--					NULL,
--					tpcmt.pcmt_note1,
--					substring(tpcmt.pcmt_note2,1,50),
--					@bt_BranchCurrencyExchange
--				FROM tbPurchaseConceptMovementsTmp tpcmt
--				INNER JOIN tbPurchaseConcept tpc
--					ON	tpc.comp_id		= @comp_id
--					AND tpc.puco_id		= tpcmt.puco_id
--				WHERE	tpcmt.comp_id	= @comp_id
--					and tpcmt.pcmt_guid = @guid

			-- ingresar en banktrans esto como importe liquidado!!
			--SELECT @decImporteLiquidado
		END


		-- Insert From tbPurchaseConceptMovementsTmp en la moneda de la cuenta Bancaria
		INSERT INTO tbBankingTransactions
		(
			comp_id,
			ba_id,
			bra_id,
			btt_id,
			ec_id,
			chp_id,
			bt_total,
			curr_id,
			bt_imputationDate,
			bt_isConciliated,
			bt_isCancelled,
			ct_transaction,
			ccm_id,
			bt_note,
			bt_Number,
			bt_BranchCurrencyExchange
		)

		SELECT	tpcmt.comp_id,
				@ba_id,
				@bra_id,
				tpc.btt_id,
				NULL,
				NULL,
				dbo.fnGetExchange(@comp_id, tpcmt.pcmt_total, tpcmt.curr_id,@curr_id_Bank,0,0,'false') * CASE
																											WHEN @intSd_Id = 143 THEN 1
																											ELSE					   1
				                                                                                         END ,
				@curr_id_Bank,
				@bt_ImputationDate,
				'False',
				'False',
				@ct_transaction,
				NULL,
				tpcmt.pcmt_note1,
				substring(tpcmt.pcmt_note2,1,50),
				@bt_BranchCurrencyExchange
			FROM tbPurchaseConceptMovementsTmp tpcmt	WITH (NOLOCK)
			INNER JOIN tbPurchaseConcept tpc	WITH (NOLOCK)
				ON	tpc.comp_id		= @comp_id
				AND tpc.puco_id		= tpcmt.puco_id
			WHERE	tpcmt.comp_id	= @comp_id
				and tpcmt.pcmt_guid = @guid


		-- Insert From tbTaxMovementTmp
		INSERT INTO tbBankingTransactions
		(
			comp_id,
			ba_id,
			bra_id,
			btt_id,
			ec_id,
			chp_id,
			bt_total,
			curr_id,
			bt_imputationDate,
			bt_isConciliated,
			bt_isCancelled,
			ct_transaction,
			ccm_id,
			bt_note,
			bt_Number,
			bt_BranchCurrencyExchange
		)

		SELECT	@comp_id,
				@ba_id,
				@bra_id,
				tpc.btt_id,
				NULL,
				NULL,
				dbo.fnGetExchange(@comp_id, ttmt.tmt_total, ttmt.curr_id,@curr_id_Bank,0,0,'false')	*	 CASE
																											WHEN @intSd_Id = 143 THEN 1
																											ELSE					   1
				                                                                                         END,
				@curr_id_Bank,
				@bt_ImputationDate,
				'false',
				'false',
				@ct_transaction,
				NULL,
				dbo.fnGetCommercialTransactionDescription(@comp_id,2,@ct_transaction),
				'',
				@bt_BranchCurrencyExchange
			FROM tbTaxMovementsTmp ttmt	WITH (NOLOCK)
			INNER JOIN tbPurchaseConcept tpc	WITH (NOLOCK)
				ON	tpc.comp_id		= @comp_id
				AND tpc.puco_id		= ttmt.puco_id
			WHERE	ttmt.comp_id	= @comp_id
				and	ttmt.tmt_guid	= @guid

		SET @return_value = @@IDENTITY

END

GO







CREATE PROCEDURE [dbo].[spBankingTransactions_TinsertData]
(
	@comp_id							int,
	@ba_id								int,
	@bra_id								int,
	@btt_id								int,
	@ec_id								int,
	@chp_id								int,
	@bt_total							decimal(19,5),
	@curr_id							int,
	@bt_imputationDate					datetime,
	@bt_isConciliated					bit,
	@bt_isCancelled						bit,
	@ct_transaction						int,
	@ccm_id								int,
	@bt_note							VARCHAR(100),
	@bt_Number							VARCHAR(50),
	@bt_BranchCurrencyExchange			DECIMAL(19,5),

	@return_value						int					output,
	@ret_ErrorCode						int					output,
	@ret_ErrorDescription				varchar(200)		output
)
AS

BEGIN



	SET NOCOUNT ON


	-- ----------------------------------------------------
	-- Testing
	-- ----------------------------------------------------
	/*
	DECLARE 	@comp_id							int,
		@ba_id								int,
		@bra_id								int,
		@btt_id								int,
		@ec_id								int,
		@chp_id								int,
		@bt_total							decimal(19,5),
		@curr_id							int,
		@bt_imputationDate					datetime,
		@bt_isConciliated					bit,
		@bt_isCancelled						bit,
		@ct_transaction						int,
		@ccm_id								int,
		@bt_note							VARCHAR(100),
		@bt_Number							VARCHAR(50),
		@bt_BranchCurrencyExchange			DECIMAL(19,5),

		@return_value						int					,
		@ret_ErrorCode						int					,
		@ret_ErrorDescription				varchar(200)


	SELECT 	@comp_id							=1,
		@ba_id								=31,
		@bra_id								=1,
		@btt_id								=6,
		@ec_id								=null,
		@chp_id								=118,
		@bt_total							=100.00,
		@curr_id							=1,
		@bt_imputationDate					='2009-30-06',
		@bt_isConciliated					='False',
		@bt_isCancelled						='False',
		@ct_transaction						=1799,
		@ccm_id								=null,
		@bt_note							='',
		@bt_Number							='',
		@bt_BranchCurrencyExchange			=3.70
	*/
	-- ----------------------------------------------------

    SAVE TRANSACTION traPROTECT
    BEGIN TRANSACTION
    BEGIN TRY

		Set @return_value			= 0
		Set @ret_ErrorCode			= 0
		Set @ret_ErrorDescription	= ''


		EXEC spBankingTransactions_insertData
			@comp_id,
			@ba_id,
			@bra_id,
			@btt_id,
			@ec_id,
			@chp_id,
			@bt_total,
			@curr_id,
			@bt_imputationDate,
			@bt_isConciliated,
			@bt_isCancelled,
			@ct_transaction,
			@ccm_id,
			@bt_note,
			@bt_Number,
			@bt_BranchCurrencyExchange,
			@return_value = @return_value output



    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION traPROTECT
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT




END
GO







CREATE procedure [dbo].[spBankingTransactions_UpdateConciliation]
(
	@comp_id			int,
	@ba_id				int,
	@bt_id				int,
	@date				datetime,
	@is_conciliated		bit
)
as


BEGIN



	SET NOCOUNT ON


-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
	/*
	DECLARE @comp_id			int,
			@ba_id				int,
			@bt_id				int,
			@bra_id				int,
			@date				datetime,
			@is_conciliated		bit


	SELECT	@comp_id			=1,
			@ba_id				=16,
			@bt_id				=582,
			@bra_id				=1,
			@date				='12-12-2008',
			@is_conciliated		='True'
	*/
-- ------------------------------------------------------



			update	dbo.tbBankingTransactions
			set		bt_imputationDate	= @date,
					dbo.tbBankingTransactions.bt_isAutoConciliated = 'False',
					bt_isconciliated	=	CASE
												WHEN bt_isconciliated = 'False' THEN 'True'
												WHEN bt_isconciliated = 'True'  THEN 'False'
												WHEN bt_isconciliated IS NULL   THEN 'True'
											END

			from	dbo.tbBankingTransactions	BT
			where	BT.[comp_id]		= @comp_id
			and		BT.[ba_id]			= @ba_id
			and		BT.[bt_id]			= @bt_id




END
GO






