CREATE  PROCEDURE [dbo].[spBankingTransactionsTmp_insertData]
(
		@comp_id				int,
		@btt_guid				uniqueidentifier,
		@bra_id					int,
		@btt_id					int,
		@ec_id					int,
		@chp_id					int,
		@btt_total				decimal(19,5),
		@curr_id				int,
		@btt_imputationDate		datetime,
		@btt_isConciliated		bit,
		@btt_isCancelled		bit,
		@ct_transaction			int,
		@ccm_id					int,
		@ba_id					int,
		@btt_note				varchar(100),
		@btt_Number				varchar(50),
		@v4c_id					int,
		@return_value			int output
)
as
set nocount on

insert into dbo.tbBankingTransactionsTmp
	(comp_id,
	 ba_id,
	 btt_guid,
	 bra_id,
	 btt_id,
	 ec_id,
	 chp_id,
	 btt_total,
	 curr_id,
	 btt_imputationDate,
	 btt_isConciliated,
	 btt_isCancelled,
	 ct_transaction,
	 ccm_id,
	 btt_note,
	 btt_Number,
	 v4c_id)

values

	(@comp_id,
	 @ba_id,
	 @btt_guid,
	 @bra_id,
	 @btt_id,
	 @ec_id,
	 @chp_id,
	 @btt_total,
	 @curr_id,
	 @btt_imputationDate,
	 @btt_isConciliated,
	 @btt_isCancelled,
	 @ct_transaction,
	 @ccm_id,
	 @btt_note,
	 @btt_Number,
	 @v4c_id)

set	@return_value = @@identity
GO








CREATE  PROCEDURE [dbo].[spBankingTransactionsTmp_updateData]
(
		@bttmp_id				int,
		@btt_guid				uniqueidentifier,
		@ba_id					int,
		@btt_id					int,
		@ec_id					int,
		@chp_id					int,
		@btt_total				decimal(19,5),
		@curr_id				int,
		@btt_imputationDate		datetime,
		@btt_isConciliated		bit,
		@btt_isCancelled		bit,
		@ct_transaction			int,
		@ccm_id					int,
		@btt_note				varchar(100),
		@btt_Number				varchar(50),
		@v4c_id					int

)
as
set nocount on


update	dbo.tbBankingTransactionsTmp

set

		ba_id				=	@ba_id,
		btt_id				=	@btt_id,
		ec_id				=	@ec_id,
		chp_id				=	@chp_id,
		btt_total			=	@btt_total,
		curr_id				=	@curr_id,
		btt_imputationDate	=	@btt_imputationDate,
		btt_isConciliated	=	@btt_isConciliated,
		btt_isCancelled		=	@btt_isCancelled,
		ct_transaction		=	@ct_transaction,
		ccm_id				=	@ccm_id,
		btt_note			=	@btt_note,
		btt_number			=	@btt_Number,
		v4c_id				= @v4c_id

where	btt_guid			= @btt_guid
and	    bttmp_id			= @bttmp_id

GO





