		@ba_id				int,
		@bttc_code			NVARCHAR(50)
)
AS

BEGIN



	set nocount on



	---------------------------------------------------------
	--
	---------------------------------------------------------
	/*

	DECLARE @comp_id			int,
			@ba_id				int,
