-- En Cobranza, en valores, transferencia bancaria se debe seleccionar un Voucher
-- ----------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spBankingVouchers4BanckTransferCollection_getCombo]
(

	@comp_id			int,
	@lang_id			int,
	@guid				UNIQUEIDENTIFIER,
	@bra_id				INT


)
as


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- -----------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------
	/*
	declare @comp_id			int,
			@guid				UNIQUEIDENTIFIER

	select @comp_id = 1

	*/
	-- -----------------------------------------------------------------------------



	set nocount on

	SELECT 	tbvbtc.v4c_id	[id],
			dbo.fnStrPADR(dbo.fnStrAllTrim(tba.ba_desc),40,'-') + ' * ' + dbo.fnStrPADL( CONVERT(NVARCHAR(15),convert(decimal(19,2),tbvbtc.v4c_Total)),12,'0')  + ' * ' +  dbo.fnStrPADR(dbo.fnStrAllTrim(tbvbtc.v4c_transactionNumber),40,'-') + ' ' + CONVERT(NVARCHAR,tbvbtc.v4c_transferDate,106) [desc]

		from		dbo.tbBankingVouchers4BanckTransferCollection		tbvbtc
		inner join tbBankingAccounts									tba
			on		tba.comp_id		= tbvbtc.comp_id
			AND		tba.ba_id		= tbvbtc.ba_id
		where		tbvbtc.comp_id						= @comp_id
		AND			tbvbtc.v4c_isCollected				= 'false'
		and			tbvbtc.v4c_isCancelled				= 'false'
		AND			tbvbtc.v4c_isAvailable4Collection	= 'True'
		and			NOT EXISTS(SELECT 1
								FROM	tbBankingTransactionsTmp tbtt
								WHERE   tbtt.comp_id	 = @comp_id
								and		tbtt.btt_guid	 = @guid
								and		tbtt.v4c_id		 = tbvbtc.v4c_id )	AND
					(
						tba.bra_id IS NULL		OR
						tba.bra_id = @bra_id
					)

		Order By	[desc]




	--declare @fecha			NVARCHAR(50),
	--		@cuenta			NVARCHAR(50),
	--		@num_trans		NVARCHAR(50)
	--
	--select @cuenta = (select tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 6000)
	--
	--select @fecha = (select tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 6001)
	--
	--select @num_trans = (select tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 6002)



END
GO








