CREATE PROCEDURE [dbo].[spBlockPage_getDataById]
(
	@comp_id			as int,
	@page_id			as INT,
	@bra_id				AS INT
)
AS

BEGIN


	SET NOCOUNT ON

	/*
	declare 	@comp_id			as int,
		@cust_id			as int,
		@user_id			as int,
		@cust_isediting		as bit
	select 	@comp_id			=1,
		@cust_id			=19976,
		@user_id			=2,
		@cust_isediting		='False'
	*/


	SELECT	tbp.[USER_ID]								[USER_ID],
			tu.user_lastname + ', ' + tu.user_firstname [user_name]
		FROM	tbBlockPage tbp
				INNER JOIN tbUser tu
				ON tu.[user_id] = tbp.[user_id]
		INNER JOIN tbBranch tb
			ON	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id
		WHERE	tbp.comp_id = @comp_id	AND
				tbp.page_id = @page_id	AND
				IsNull(tb.bra_Payments_DisableConcurrencyBlock,'False') = 'False'




END
GO
