CREATE procedure [dbo].[spBlockPage_IsEditingPurgeStatus]
AS
BEGIN
		
	set nocount on

	declare @DeleteTime		as	datetime
	set		@DeleteTime		=	DATEADD(minute, -2, getdate())

	DELETE FROM tbBlockPage	WITH(ROWLOCK)
	Where  blp_date < @DeleteTime
		
END




GO






