		@cust_id			as int,
		@user_id			as int,
		@cust_isediting		as bit
	select 	@comp_id			=1,
		@cust_id			=19976,
		@user_id			=2,
		@cust_isediting		='False'
	*/

	IF EXISTS (	SELECT	1
	           		FROM tbBlockPage tbp		WITH (NOLOCK)
					WHERE	comp_id					= @comp_id
					and		page_id					= @page_id)
		BEGIN
			Update	dbo.tbBlockPage	WITH (ROWLOCK)
				Set	    blp_date 				= getdate(),
						[USER_ID]				= @user_id
				Where	comp_id					= @comp_id
				and		page_id					= @page_id
		END
	ELSE
		INSERT INTO tbBlockPage WITH (ROWLOCK)
		(
			comp_id,
			page_id,
			[user_id],
			blp_date
		)
		VALUES
		(
			@comp_id,
			@page_id,
			@user_id,
			GETDATE()
		)
END
GO







