CREATE PROCEDURE spBranch_funValidatePaymentSupplier
(
	@comp_id		INT,
	@supp_id		INT,
	@return_value	INT OUTPUT
)
AS SET NOCOUNT ON



-- --------------------------------------------------
-- Testing
-- --------------------------------------------------
/*
	DECLARE
		@comp_id		INT,
		@supp_id		INT,
		@return_value	INT
	SELECT
		@comp_id		=1,
		@supp_id		=8103,
		@return_value	=0
*/
-- --------------------------------------------------

SET @return_value = 0

IF 	(SELECT
		COUNT(*)
	FROM tbBranch				tb
	WHERE tb.comp_id			= @comp_id
	AND	  tb.bra_PaymentSupp_Id	= @supp_id) > 0

	SET @return_value = 1
ELSE
	SET @return_value = 0


	SELECT @return_value


GO


CREATE PROCEDURE spBranch_GetBranchStorage_4PcConfigBranch
(
	@comp_id	INT,
	@bra_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------
		-- TESTING
		-- -----------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1
		*/
		-- -----------------------------------
		--ACA GUARDAMOS EL ID DE LA SUCURSAL PARA ARMADO DE PC
		DECLARE
			@bra_id_4PcConfig INT

		SELECT
			@bra_id_4PcConfig = tb.bra_id4SaleOrderTurn
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id

		IF @bra_id_4PcConfig IS NULL
			BEGIN
				SELECT -1
			END
		ELSE
			BEGIN
				SELECT
					tb.stor_id4PCConfig
				FROM tbBranch tb
				WHERE	tb.comp_id	= @comp_id			AND
						tb.bra_id	= @bra_id_4PcConfig
			END

	END
GO






CREATE PROCEDURE [dbo].[spBranch_GetCombo]
(
	@comp_id			INT,
	@user_id			INT,
	@prof_id			INT
)

as

BEGIN


	-- ---------------------------
	-- Test
	-- El Perfil se pone en -10
	-- en wfmAssignProfileToUser
	-- ---------------------------
	/*
	DECLARE
	@comp_id			INT,
	@user_id			INT,
	@prof_id			INT

	SET 	@comp_id		=144
    SET		@user_id		= 3
	SET 	@prof_id		= -10
	*/
	-- ---------------------------



	set nocount on


	DECLARE @bitProfIdAdmin AS BIT
	SET		@bitProfIdAdmin = 'False'

	SELECT TOP 1 @bitProfIdAdmin = 'True'
		FROM tbProfile tp		WITH (NOLOCK)
		WHERE	tp.comp_id		= @comp_id AND
				( @prof_id = -10 OR  tp.prof_id		= @prof_id) AND
				tp.prof_isSA	= 'True'


	IF @bitProfIdAdmin = 'True'
		BEGIN
			select		bra_id		[id],
						bra_desc	[desc]
				from	dbo.tbBranch	WITH (NOLOCK)
				where	comp_id		 =	@comp_id AND
						bra_disabled = 'False'
				Order By	bra_desc
		END
	ELSE
		BEGIN
			SELECT
				DISTINCT
				tb.bra_id	[id],
				tb.bra_desc	[desc]
				FROM tbBranch tb	WITH (NOLOCK)

				INNER JOIN tbUserCompanyProfile tucp	WITH (NOLOCK)
					ON tucp.comp_id = tb.comp_id
					AND tucp.bra_id = tb.bra_id

				WHERE tb.comp_id	= @comp_id
				AND tucp.[user_id]	= @user_id
				AND tb.bra_disabled = 'False'
			ORDER BY tb.bra_desc
		END


END














GO






CREATE PROCEDURE [dbo].[spBranch_GetComboBranchTransfer]
