GO





CREATE PROCEDURE [dbo].[spBranch_getComboByProfile]
(
	@comp_id	INT,
	@user_id	INT,
	@prof_id	INT
)
AS

BEGIN


	SET NOCOUNT ON


	-- ---------------------------------------------------------------
	-- For Testing
	-- ---------------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@user_id	INT,
			@prof_id	INT

		SELECT
			@comp_id	=1,
			@user_id	=1,
			@prof_id	=1
	*/
	-- ---------------------------------------------------------------

	SELECT	DISTINCT
		tb.bra_id						[Id],
		tb.bra_desc						[Desc]

		FROM tbBranch						tb		WITH (NOLOCK)

		INNER JOIN tbUserCompanyProfile		tucp	WITH (NOLOCK)
		ON	tucp.comp_id	= tb.comp_id
		AND tucp.bra_id		= tb.bra_id


		WHERE	tb.comp_id		= @comp_id
		AND		tucp.[user_id]	= @user_id
		AND		tucp.prof_id	= @prof_id
		AND tb.bra_disabled		= 'False'
	ORDER BY tb.bra_desc


END
GO





CREATE PROCEDURE [dbo].[spBranch_getComboForUser]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@user_id	INT,
	@prof_id	INT
)

AS

BEGIN

	SET NOCOUNT ON


	-- ----------------------------------------------
	-- Testing
	-- ----------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@user_id	INT,
			@prof_id	INT

		SELECT
			@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@user_id	=1,
			@prof_id	=1
	*/
	-- ----------------------------------------------

	SELECT
		DISTINCT
		tb.bra_id	[id],
		tb.bra_desc	[desc]
		FROM tbBranch tb		WITH (NOLOCK)

		INNER JOIN tbUserCompanyProfile tucp		WITH (NOLOCK)
			ON tucp.comp_id = tb.comp_id
			AND tucp.bra_id = tb.bra_id

		WHERE tb.comp_id	= @comp_id
		AND tucp.[user_id]	= @user_id
		AND tb.bra_disabled = 'False'
	ORDER BY tb.bra_desc


END
GO







CREATE PROCEDURE [dbo].[spBranch_getDataById]
(
	@comp_id			int,
	@bra_id				int
)
AS


BEGIN


	set nocount on

	-- --------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------
	/*
	declare	@comp_id		int,
			@bra_id			int
	select 	@comp_id		= 1,
			@bra_id			= 43
	*/
	-- --------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	select	b.comp_id,
			b.bra_id,
			b.bra_desc,
			b.bra_cd,
			b.country_id,
			c.country_desc,
			b.state_id,
			s.state_desc,
			ISNULL(b.curr_id,-1) [curr_id],
			y.curr_desc,
			b.stor_id,
			t.stor_desc,
			b.df_id,
			d.df_desc,
			b.bra_processingDate,
			b.cc_Code,
			cc.[cc_desc],
			b.bra_costlist_type,
			b.coslis_id,
			ic.[coslis_desc],
			ISNULL(b.bra_PriceDecimalPlaces,2)					[bra_PriceDecimalPlaces],
			ISNULL(b.bra_prli_idOfMinimumPriceAllowed,-1)		[bra_prli_idOfMinimumPriceAllowed],
