			ISNULL(b.bra_prli_idOfMinQty_3,0)					[bra_prli_idOfMinQty_3],
			b.bra_CollectionOfAllBranches,
	--		b.bra_enableChangeOfSalesman,
	--		b.bra_enableChangeOfDelivery,
	--		b.bra_enableChangeOfSalesTerms,
	--		b.bra_enableChangeOfCreditCard,
	--		b.bra_enableChangeOfStorage,
	--		b.bra_enableChangeOfPriceList,
	--		b.bra_enableChangeOfGeneralDiscount,
			b.bra_SaleOrderDisposeLimitDays,
			b.bra_SaleOrderEnablePreparation,
	--		b.bra_SaleOrderChangeOfLimitDate,
	--		b.bra_SaleOrderChangeOfDeliveryDate,
			b.bra_SaleOrderProcessingRefreshTime,
			b.bra_PaymentMaximumAdjust,
			b.bra_CashDepositCaId,
			b.bra_CashExtractionCaId,
			tc.curr_id															[CompanyCurrId],
			(dbo.[fnGetExchange](@comp_id, 1, b.curr_id, tc.curr_id, 0, 0, 0)) 	[CompanyCurrExchange],

			b.bra_PaymentCaId_Money,
			b.bra_PaymentCaId_Cheque,
			b.bra_PaymentCaId_ChequePortfolio,
			b.bra_PaymentCaId_Documents,
			b.bra_PaymentCaId_Transfer,

			b.bra_CollectionCaId_Money,
			b.bra_CollectionCaId_Cheque,
			b.bra_CollectionCaId_CreditCard,
			b.bra_CollectionCaId_Documents,
			b.bra_CollectionCaId_Transfer,
			b.bra_PaymentPointOfSale,
			b.bra_CR_dfId4Debit,
			b.bra_CR_taxId4Cheque,
			b.bra_CR_taxId4Charge,
			b.bra_RMA_prli_Id4NoSerialItems,
			b.bra_RMA_PurchaseCostFrom,
			b.bra_RMA_PurchaseCostListName,
			b.bra_SaleOrderSelectStorageFromBranchOrCustomer,
			b.bra_PurDoc_ccCode4Nothing,
			b.bra_PurDoc_MinTaxDate,
			b.bra_PurDoc_MaxTaxDate,

			IsNull(b.bra_minMarkUpLevel1,0)													[bra_minMarkUpLevel1],
			IsNull(b.bra_minMarkUpLevel2,0)													[bra_minMarkUpLevel2],

			y.curr_symbol,
