			ISNULL(b.bra_SaleOrderShowSO_RMA_Pendings,'False')								[bra_SaleOrderShowSO_RMA_Pendings],

			(SELECT tsdv.version
				FROM tbSystem_DatabaseVersion tsdv WITH (NOLOCK))						[dbv],
			ISNULL((	SELECT tsgv.versionOfGeneration
			        		FROM tbSystem_DatabaseVersion tsgv	WITH (NOLOCK)),0)	[genv],


			--==STL
