			b.bra_SaleOrder_AllowCostInCero,
			b.bra_CustomerMailing_emailValidation											[bra_CustomerMailing_emailValidation],
			IsNull(b.bra_SaleOrderDiscountWithSalesTermsAsociated,'False')					[bra_SaleOrderDiscountWithSalesTermsAsociated],
			IsNull(b.bra_CRDirectPrint4Documents,'False')									[bra_CRDirectPrint4Documents],
