			ISNULL(b.bra_Banks_InputOutputCharges_DisableAccounting, 'False')				[bra_Banks_InputOutputCharges_DisableAccounting],
			ISNULL(b.bra_SaleOrderEmittion_CheckInternalAnnotationContains,'')				[bra_SaleOrderEmittion_CheckInternalAnnotationContains],
			ISNULL(b.bra_SaleOrderEmittion_CheckInternalAnnotationNoContains,'')			[bra_SaleOrderEmittion_CheckInternalAnnotationNoContains],
			ISNULL(b.bra_RMA_stor_id4SupplierCreditNote,-1)									[bra_RMA_stor_id4SupplierCreditNote]	,
			ISNULL(b.bra_RMA_Customers_GetPriceOfLastPurchase,'False')						[bra_RMA_Customers_GetPriceOfLastPurchase],
			ISNULL(b.bra_mailing_FromEmail,'')												[bra_mailing_FromEmail],
			ISNULL(b.bra_mailing_DisplayName,'')											[bra_mailing_DisplayName],
			ISNULL(b.bra_purchaseOrder_enableAutoProcess,'False')							[bra_purchaseOrder_enableAutoProcess],--GA 16/04/14
			ISNULL(b.bra_SaleOrder_showCRMNotesOfCustomer,'False')							[bra_SaleOrder_showCRMNotesOfCustomer], --STL 16/04/2014
			ISNULL(b.bra_RMA_SupplierCreditNotePostRMA, 'False')							[bra_RMA_SupplierCreditNotePostRMA],	--STL 05/05/2014
			b.bra_RMA_stor_id4Reparation,
