			isNull(tdc.dc_minDeliveryDate,b.bra_processingDate)								[dc_minDeliveryDate],
			ISNULL(b.bra_PurDoc_TaxDateForcedIfNotInPeriod	,'False')						[bra_PurDoc_TaxDateForcedIfNotInPeriod],
			ISNULL(b.bra_PurDoc_TaxDateIfNotInPeriod	,GETDATE())							[bra_PurDoc_TaxDateIfNotInPeriod],
			ISNULL(b.bra_SaleOrder_DisableCustomerConcurrentCheck,'False')					[bra_SaleOrder_DisableCustomerConcurrentCheck],
			ISNULL(b.bra_CollectionEnablePreLoadByct_transaction,'False')					[bra_CollectionEnablePreLoadByct_transaction],
			b.prli_id4Credit,
			isnull(b.bra_Payments_EnableEMailofPayment,'False')								[bra_Payments_EnableEMailofPayment],
			b.stor_id4PurchasePlan,
			b.brag_id4PurchasePlan,
			ISNULL(b.bra_id4SaleOrderTurn,-1)												[bra_id4SaleOrderTurn],
			IsNull(b.bra_costPriceEdition_decimalPLaces,4)									[bra_costPriceEdition_decimalPLaces],
			IsNull(b.bra_costPriceEdition_decimals2Round,4)									[bra_costPriceEdition_decimals2Round],
			IsNull(b.bra_PurDoc_MustSpecifyLoan,'False')									[bra_PurDoc_MustSpecifyLoan],
			b.st_id4Loan,
			b.stor_id4PCConfig,
			IsNull(b.bra_purchaseDJAILink4FTP,'')											[bra_purchaseDJAILink4FTP],
			ISNULL(b.dc_id,-1)																[dc_id],
			IsNull(b.bra_purchaseDJAIPrefix4FTP,'')											[bra_purchaseDJAIPrefix4FTP],
			IsNull(b.bra_purchaseDJAIUserName4FTP,'')										[bra_purchaseDJAIUserName4FTP],
			IsNull(b.bra_purchaseDJAIPassword4FTP,'')										[bra_purchaseDJAIPassword4FTP],
			ISNULL(b.bra_SaleOrderPricePlusTaxDisabled,'False')								[bra_SaleOrderPricePlusTaxDisabled],
			b.bra_df_id4itemReturn4Change,
			b.item_id4PCConfig,
			ISNULL(b.bra_RMAModel,0)														[bra_RMAModel],
			isnull(b.bra_body4Payorder,'')													[bra_body4Payorder],
			ISNULL(b.bra_saleOrder_PrintWithOutScryptX,'False')								[bra_saleOrder_PrintWithOutScryptX],
			ISNULL(b.prli_id4CreditInCashTEXT,'')											[prli_id4CreditInCashTEXT],
			ISNULL(b.prli_id4CreditTEXT,'')													[prli_id4CreditTEXT],
			ISNULL(b.bra_RMA_useDFIdOfOriginalBranch,'False')								[bra_RMA_useDFIdOfOriginalBranch],
			ISNULL(b.bra_RMA_enableBranchComboIFNoIs_Id,'False')							[bra_RMA_enableBranchComboIFNoIs_Id],
			b.bra_RMA_prli_id4AdditionalItems												[bra_prli_id4RMAAdditionalItems],
			ISNULL(b.bra_PurDoc_coslis_id,-1)												[bra_PurDoc_coslis_id],
			ISNULL(b.bra_PurDoc_coslis_id_blockRules,'False')								[bra_PurDoc_coslis_id_blockRules],
			ISNULL(b.bra_PurDoc_coslis_id_B_blockRules,'False')								[bra_PurDoc_coslis_id_B_blockRules],
			ISNULL(b.coslis_id_B,-1)														[coslis_id_B],
			IsNull(b.coslis_id4PurchasePlanning,-1)											[coslis_id4PurchasePlanning],
			ISNULL(b.ag_id,-1)																[ag_id],
			ISNULL(b.bra_wfmItemGlobalChanges_coslis_id,-1)									[bra_wfmItemGlobalChanges_coslis_id],
			b.df_id4CUITData,
			ISNULL(b.bra_purchaseOrderNote3,'')												[bra_purchaseOrderNote3],
			ISNULL(b.bra_SaleOrderPriceControlMode,2)										[bra_SaleOrderPriceControlMode],
			ISNULL(b.wssql_id4PostOpenPayments,-1)											[wssql_id4PostOpenPayments],
			ISNULL(b.wssql_id4preClosePayments,-1)											[wssql_id4preClosePayments],
			ISNULL(b.wssql_id4PostOpenPurchaseDocs,-1)										[wssql_id4PostOpenPurchaseDocs],
			ISNULL(b.wssql_id4preClosePurchaseDocs,-1)										[wssql_id4preClosePurchaseDocs],
			ISNULL(b.bra_ABM_refreshSeconds,3600)											[bra_ABM_refreshSeconds],
			b.storg_id,
			b.bra_retentionFormat,
			ISNULL(b.bra_purchaseOrderPrintFormat4Quotation	,-1)							[bra_purchaseOrderPrintFormat4Quotation],	--GA 10/02/22 tkt:14373
			b.bra_currencyID4Purchase,
			ISNULL(b.stor_id4ItemsComplexFilter,-1)											[stor_id4ItemsComplexFilter], --tkt 19261
			ISNULL(b.bra_GoogleApiKey,'')													[bra_GoogleApiKey]


	from	dbo.tbBranch						b		WITH (NOLOCK)

			LEFT JOIN tbDistributionCenter tdc			WITH (NOLOCK)
			ON	tdc.comp_id		= b.comp_id AND
				tdc.dc_id		= b.dc_id

			left join dbo.[tbsysCountry]		c		WITH (NOLOCK)
			on	c.[country_id]	=	b.[country_id]

			left join dbo.[tbsysState]			s		WITH (NOLOCK)
			on	s.[country_id]	=	b.[country_id]
			and	s.[state_id]	=	b.[state_id]

			left join dbo.[tbsysCurrency]		y		WITH (NOLOCK)
			on	y.[curr_id]		=	b.[curr_id]

			left join dbo.[tbStorage]			t		WITH (NOLOCK)
			on	t.[stor_id]		=	b.[stor_id]

			left join dbo.[tbDocumentsFile]		d		WITH (NOLOCK)
			on	d.[comp_id]		=	b.[comp_id]
			and	d.[bra_id]		=	b.[bra_id]
			and	d.[df_id]		=	b.[df_id]

			left join dbo.[tbCostCenter]		cc		WITH (NOLOCK)
			on	cc.[comp_id]	=	b.[comp_id]
			and cc.[cc_code]	=	b.[cc_code]

			left join dbo.[tbItemCostListName]	ic		WITH (NOLOCK)
			on	ic.[comp_id]	=	b.[comp_id]
			and ic.[coslis_id]	=	b.coslis_id

			INNER JOIN dbo.tbCompany			tc		WITH (NOLOCK)
			ON tc.comp_id		= b.comp_id

	where	b.comp_id		=	@comp_id
	and	    b.bra_id		=	@bra_id


END
GO





