-- =============================================
-- Author:		MOS
-- Create date: 07-2009
-- Description:	Nuevo Numero de OP
-- =============================================
CREATE PROCEDURE [dbo].[spBranch_GetNewPayOrderNumber]
	@comp_id			AS INT,
	@bra_id				AS INT,
	@processing_date	AS DATETIME
AS
BEGIN

	SET NOCOUNT ON;

	-- Carga valores por defecto
	UPDATE tbBranch
	SET
	    bra_PaymentOrderNumber = 0,
	    bra_PaymentKindOf = 'X'
	WHERE	comp_id = @comp_id
		AND bra_id  = @bra_id
		AND bra_PaymentOrderNumber IS NULL

	DECLARE @intYear					AS INT
	DECLARE @intMonth					AS INT

	SET @intYear	= YEAR(@processing_date)
	SET @intMonth	= MONTH(@processing_date)



	IF EXISTS(	SELECT 1
	          		FROM tbbranch
	          		WHERE	comp_id = @comp_id			AND
	          				bra_id	= @bra_id			AND
	          				bra_Payments_NumberbyMonth = 'True'
			)
		BEGIN -- Si el Numero de OP se pone por Año y Mes...
			IF NOT EXISTS(	SELECT 1
			              		FROM tbBranchPaymentNumber tbpn
			              		WHERE	tbpn.comp_id = @comp_id AND
			              				tbpn.bra_id = @bra_id AND
			              				tbpn.pon_year = @intYear AND
			              				tbpn.pon_month = @intMonth )
				BEGIN -- Si no existe el numerador lo da de alta
					INSERT INTO tbBranchPaymentNumber
					(
						comp_id,
						bra_id,
						pon_year,
						pon_month,
						pon_number
					)
					VALUES
					(
						@comp_id,
						@bra_id,
						@intYear,
						@intMonth,
						0
					)
				END

			UPDATE tbBranchPaymentNumber
				SET	pon_number	= pon_number + 1
				WHERE	comp_id		= @comp_id AND
						bra_id		= @bra_id AND
						pon_year	= @intYear AND
						pon_month	= @intMonth

			-- Retorna Valores a la OP
			SELECT	tb.bra_PaymentKindOf,
					tb.bra_PaymentPointOfSale,
					CONVERT(INT,
						CONVERT(NVARCHAR(4),@intYear)								+
						DBO.fnStrPADL(	CONVERT(NVARCHAR(2),@intMonth),2,'0')		+
						DBO.fnStrPADL(	convert(nvarchar(4),tbpn.pon_number),4,'0')
						   )										[bra_PaymentOrderNumber]
				FROM	tbBranch tb
				INNER JOIN tbBranchPaymentNumber tbpn
					ON	tbpn.comp_id	= tb.comp_id	AND
						tbpn.bra_id		= tb.bra_id		AND
						tbpn.pon_year   = @intYear		AND
						tbpn.pon_month  = @intMonth
				WHERE	tb.comp_id = @comp_id	AND
						tb.bra_id  = @bra_id

		END
	ELSE
		BEGIN

			-- Actualiza Numeracion
			UPDATE tbBranch
				SET
					bra_PaymentOrderNumber = bra_PaymentOrderNumber + 1
				WHERE	comp_id = @comp_id
					AND bra_id = @bra_id

			-- Retorna Valores a la OP
			SELECT	tb.bra_PaymentKindOf,
					tb.bra_PaymentPointOfSale,
					tb.bra_PaymentOrderNumber
				FROM	tbBranch tb
				WHERE	comp_id = @comp_id
					AND bra_id  = @bra_id

		END

END
GO






