-- Log
-- MOS 05-2024: Se pasó el depurado de pedidos AL FINAL ya que puede tardar mucho y bloquear al resto de los procesos de cierre
-- MOS 05-2024: Saque todas las transacciones que estaban AL PEDO en este punto.


-- ------------------------------------------
-- es Cierre Diario de Sucursal!  HD&%$P!!!
-- digo, por el nombre del SP
-- ------------------------------------------

CREATE PROCEDURE  [dbo].[spBranch_updateData]
(
	@comp_id			INT,
	@bra_id				INT,
	@DateUpdate			DATETIME,
	@user_id			INT,
	@prof_id			INT,
	@bitIsAutoClose		BIT,
	@return_value		INT OUTPUT
)
AS

BEGIN


	SET NOCOUNT ON

	SET DATEFIRST	7	-- Domingo x Defecto

	SET DATEFORMAT 'ymd'
	-- CIERRE DIARIO
	-- =================================================================================================================
	-- Author		: MOS
	-- Update Date	: 2010-08-17
	-- Parte		: Sin Parte - Referencia #1
	-- Description	: Pasar a inactivos los clientes (cust_inactive	= 'True') cuando el campo bra_CloseInactiveCustomers = 'True'
	--				  y el saldo de los clientes es mayor de cero
	--				  Como son varios pasos se agrega una transacción interna si hay algún problema se retorna el mensaje de error
	--				  Se agregan comentarios en todos los pasos
	-- =================================================================================================================
	-- =================================================================================================================
	-- Author		: MOS
	-- Update Date	: 2010-09-11
	-- Parte		: 550
	-- Description	: Se agregan los nuevos parámetros necesarios para ejecutar el sp spSecurityLog_insertData
	-- =================================================================================================================



	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
	/*
	DECLARE		@comp_id			INT,
				@bra_id				INT,
				@DateUpdate			DATETIME,
				@user_id			INT,
				@prof_id			INT,
				@bitIsAutoClose		BIT,
				@return_value		INT
	select		@comp_id			= 1,
				@bra_id				= 1,
				@DateUpdate			= '2013-10-06',
				@user_id			= 1,
				@bitIsAutoClose		='True',
				@prof_id			= 1
	*/
	-- -----------------------------------------------------------------------


	DECLARE @datActualProcessingDate AS DATETIME
	SET @datActualProcessingDate = GETDATE()


	-- ========================================================================================================
	-- valida que haya un solo usuario logueado, esto es, uno mismo
	-- ========================================================================================================
	IF ((SELECT COUNT([USER_ID])
			FROM tbUser tu
			WHERE tu.user_login = 'True') = 1) OR @bitIsAutoClose = 'True'
		BEGIN


			--BEGIN TRANSACTION
			BEGIN TRY



				-- ========================================================================================================
				-- actualización de la fecha de proceso de la sucursal solicitada
				-- ========================================================================================================
				SELECT @datActualProcessingDate = tb.bra_processingDate
					FROM tbBranch tb	WITH (NOLOCK)
					WHERE	tb.comp_id = @comp_id AND
							tb.bra_id  = @bra_id

				UPDATE  dbo.tbBranch	WITH (ROWLOCK)
					SET		bra_processingDate	= @DateUpdate
					WHERE 	comp_id				= @comp_id
					AND 	bra_id				= @bra_id
				-- ========================================================================================================


				-- -----------------------------------------------------------
				-- Graba el Historial de Stock a la fecha del cierre.-
				-- -----------------------------------------------------------
				DECLARE @datStorageSave AS DATETIME
				SET		@datStorageSave = DATEADD(dd, 0, DATEDIFF(dd, 0, @datActualProcessingDate))
				IF not EXISTS(	SELECT TOP 1 1
				              		FROM tbItemStorageHistory4CloseDaily		WITH (NOLOCK)
				              		WHERE   comp_id = @comp_id AND
				              				ith_cd  = @datStorageSave
							)
					BEGIN
						--BEGIN TRANSACTION
							INSERT INTO tbItemStorageHistory4CloseDaily
							(
								comp_id,
								stor_id,
								item_id,
								ith_Qty,
								ith_cd,
								bra_id_closed
							)
							SELECT	@comp_id,
									tis.stor_id,
									tis.item_id,
									tis.itst_cant,
									@datStorageSave	,
									@bra_id
								FROM tbItemStorage tis		WITH (NOLOCK)
								INNER JOIN tbItem ti		WITH (NOLOCK)
									ON	ti.comp_id	= tis.comp_id	AND
										ti.item_id	= tis.item_id
								WHERE   tis.comp_id = @comp_id		AND
										--tis.itst_cant <> 0			AND
										tis.itst_cant <> dbo.fnGetStockHistory(tis.comp_id, tis.stor_id, tis.item_id, @datStorageSave)
						--COMMIT TRANSACTION
						--CHECKPOINT
					END
				-- -----------------------------------------------------------


				-- ========================================================================================================
				-- grabación del log por el cierre diario
				-- ========================================================================================================
				DECLARE @rv INT
				EXEC	spSecurityLog_insertData
						@comp_id,		@bra_id,		@user_id,
						'Close Daily',	NULL,			NULL,
						NULL,			NULL,			50,
						NULL,			NULL,			NULL,
						NULL,			NULL,			@prof_id,
						NULL,	-- Parte: 550
						NULL, 	-- Parte: 550
						NULL,			NULL,			NULL,				NULL,
						@return_value	= @rv OUTPUT
				-- ========================================================================================================




				-- ========================================================================================================
				-- deshabilita leyenda que indica que debe realizar cierre diario
				-- ========================================================================================================
				UPDATE tbSystem_DatabaseVersion
					SET	   isUpdated		= 'False'
				-- ========================================================================================================




				-- ========================================================================================================
				-- MOS - #1
				-- Pone como inactivos los clientes que tienen saldo mayor que cero y el la marca bra_CloseInactiveCustomers
				-- de Branch es 'True'
				-- ========================================================================================================
				-- MOS
				-- Primero pone a todos los Clientes como NO INACTIVOS si es que esta seteado ese control en tbBranch
				IF DATEPART( DAY,GETDATE()) = (DATEPART( DAY,GETDATE()) / 2) * 2
					BEGIN


						IF EXISTS(
									SELECT TOP 1 1
				              			FROM tbBranch			tb			WITH (NOLOCK)
										WHERE 	tb.comp_id	= @comp_id	AND
												tb.bra_id	= @bra_id	AND
												ISNULL(tb.bra_CloseInactiveCustomers,'False')	= 'True'
									)
							BEGIN
								--BEGIN TRANSACTION
									UPDATE	tbCustomer							WITH (ROWLOCK)
										SET		cust_inactive	= 'False'
										FROM	tbCustomer					tc
										INNER JOIN tbBranch			tb			WITH (NOLOCK)
											ON		tb.comp_id	= @comp_id
												AND tb.bra_id	= @bra_id
										WHERE   tc.comp_id										= @comp_id
											AND	ISNULL(tb.bra_CloseInactiveCustomers,'False')	= 'True'

									-- Ahora pone a los clientes como INACTIVOS si es que deben y la deuda esta vencida.-
									UPDATE	tbCustomer										WITH (ROWLOCK)
										SET		cust_inactive	= 'True'
										FROM	tbCustomer					tc
										INNER JOIN tbBranch			tb						WITH (NOLOCK)
											ON		tb.comp_id	= @comp_id
												AND tb.bra_id	= @bra_id
										CROSS APPLY dbo.fnCustomer_getBalanceStatus(@comp_id, tb.curr_id, tc.cust_id, @user_id,(GETDATE() - ISNULL(tb.bra_CloseInactiveCustomersOffset,0)),-1,-1) fcgbs
										WHERE   tc.comp_id										= @comp_id
											AND	ISNULL(tb.bra_CloseInactiveCustomers,'False')	= 'True'
											AND EXISTS( SELECT Top 1 1
															FROM tbCommercialTransactions tct		WITH (NOLOCK)
															INNER JOIN vwCommercialTransactions_forSales vctfs	WITH (NOLOCK)
																ON	vctfs.comp_id			= tct.comp_id					AND
																	vctfs.ct_transaction	= tct.ct_transaction
															WHERE	tct.comp_id = tc.comp_id
																AND tct.cust_id = tc.cust_id
																AND tct.ct_ABalance <> 0
																AND tct.sd_id NOT IN (6,13,2,3)
													  )
											AND (		fcgbs.cust_credit_balance_OverCome	> 0
													OR (	fcgbs.cust_credit_max <> 0
																and
															tb.bra_CloseInactiveCustomersCreditMaxCheck = 'True'
																AND
															tb.bra_CloseInactiveCustomersOffset = 0
																and
														   (fcgbs.cust_credit_max < (fcgbs.cust_credit_balance + fcgbs.cust_credit_cheque_own_used + fcgbs.cust_credit_cheque_3rd_used))
													   )
												)
								--COMMIT TRANSACTION
								--CHECKPOINT
							END

					END
				-- ========================================================================================================




				-- ----------------------------------------------
				-- Borra la Temporal de Asientos Contables
				-- ----------------------------------------------
				--DELETE FROM tbAccountTransactionDetailTmp
				-- ----------------------------------------------

				-- Borra los clientes esperando del dia
				--BEGIN TRANSACTION
					DELETE FROM tbCustomerWaiting WHERE comp_id = @comp_id AND bra_id = @bra_id
				--COMMIT TRANSACTION
				--CHECKPOINT
				-- ----------------------------------------------




				-- ----------------------------------------------------------------------
				-- Actualiza Numeros de Comprobantes en Asientos Contables de
				-- Facturas Fiscales.-
				-- NOOOOOO sacar esto de aca !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
				-- ----------------------------------------------------------------------
				IF EXISTS(	SELECT TOP 1 1
								FROM tbDocumentsFile tdf		WITH (NOLOCK)
				          		WHERE	tdf.comp_id		= @comp_id
				          			AND tdf.bra_id		= @bra_id
				          			AND tdf.df_Fiscal_IsFiscalPrinter = 'True')
				BEGIN
					UPDATE tbAccountTransactionDetail
						SET
							acc_detail1 = REPLACE(atd.acc_detail1,'-0000000000', dbo.fnStrPADL(dbo.fnStrAllTrim(ISNULL(tct.ct_docNumber,'')),10,'0'))

						FROM tbAccountTransactionDetail atd						WITH (NOLOCK)
							INNER JOIN tbCommercialTransactions tct				WITH (NOLOCK)
								ON		tct.comp_id			= atd.comp_id
									AND tct.ct_transaction	= atd.ct_transaction
							INNER JOIN tbDocumentsFile tdf						WITH (NOLOCK)
								ON		tdf.comp_id			= tct.comp_id
									AND tdf.df_id			= tct.df_id

						WHERE	atd.comp_id = @comp_id
							AND atd.bra_id	= @bra_id
							AND tdf.df_Fiscal_IsFiscalPrinter = 'True'
							AND atd.acc_detail1 LIKE '%-0000000000%'

				END
				-- ----------------------------------------------------------------------

				-- Saca a todos los usuarios que esten activos
				UPDATE tbUser		WITH (ROWLOCK)
					SET		user_forceLogout = 'True'
					WHERE	user_login		 = 'True'

				SET		@return_value		= 1
				SELECT	1


				---- -------------------------------------------
				---- Depurado de Pedidos
				---- -------------------------------------------
				--BEGIN TRY
				--	EXEC spSaleOrder_PurificationOrders
				--		@comp_id,
				--		@bra_id,
				--		@datActualProcessingDate,
				--		''
				--END TRY
				--BEGIN CATCH
				--END CATCH
				---- -------------------------------------------


				--COMMIT TRANSACTION


			END
			TRY BEGIN CATCH
				--ROLLBACK TRANSACTION
				SET		@return_value		= 0
				SELECT	ERROR_MESSAGE()
			END CATCH


		END
	ELSE
		BEGIN

			SET		@return_value		= 0

			-- ========================================================================================================
			-- si no hay un solo usuario logueado al sistema, se retorna una lista de los usuarios conectados diferentes
			-- de uno mismo
			-- ========================================================================================================
			SELECT	tu.user_lastname + ' ' +  tu.user_firstname
				FROM	tbUser tu	WITH (NOLOCK)
				WHERE	tu.user_login	= 'True'
				AND		tu.[user_id]	<> @user_id
			-- ========================================================================================================


		END



	-- -----------------------------------
	-- PLANILLAS de CONTROL de INVENTARIO
	-- Si se grabo una planilla de control
	-- de inventario
	-- con stock a una fecha determinada
	-- y llego esa fecha, se debe actualizar
	-- el stock con el stock GUARDADO a esa
	-- fecha realizado mas arriba en este
	-- SP
	-- -----------------------------------
		UPDATE tbStockControlOrders_Detail
			SET	tbStockControlOrders_Detail.itstkpld_qtyAtGeneration = dbo.fnGetStockHistory(scd.comp_id, tscoh.stor_id, scd.item_id, scd.itstkpld_StockAt)
			FROM tbStockControlOrders_Detail scd
			INNER JOIN tbStockControlOrders_Header tscoh			WITH (NOLOCK)
				ON	tscoh.comp_id		= scd.comp_id					AND
					tscoh.itstkpl_id	= scd.itstkpl_id
			INNER JOIN tbBranch tb									WITH (NOLOCK)
				ON	tb.comp_id			= tscoh.comp_id					AND
					tb.bra_id			= tscoh.bra_id
			WHERE	tscoh.comp_id		= @comp_id						AND
					tscoh.bra_id		= @bra_id						AND
					ISNULL(tscoh.itstkpl_isClosed,'False') = 'False'	AND
					tscoh.itstkpl_useSavedStock = 'True'				AND
					scd.itstkpld_StockAt IS NOT NULL					AND
					DATEADD(dd, 0, DATEDIFF(dd, 0, scd.itstkpld_StockAt)) = DATEADD(dd, 0, DATEDIFF(dd, 0, tb.bra_processingDate)) AND -- Si tienen la MISMA FECHA a hora 0
					scd.itstkpld_qtyAtGeneration <> dbo.fnGetStockHistory(scd.comp_id, tscoh.stor_id, scd.item_id, scd.itstkpld_StockAt)
	-- -----------------------------------







	-- -------------------------------------------
	-- Pone que el proximno en entrar al ws copie de nuevo las imagenes a la temp
	-- -------------------------------------------
	UPDATE	tbWebSite_Names
		SET		ws_files2TempUpdated				= 'false',
				ws_files2TempUpdated4Development	= 'False'
	UPDATE tbWebSiteII_Names
		SET	ws_files2TempUpdated					= 'False',
			ws_files2TempUpdated4Development		= 'False'
	-- -------------------------------------------



	-- -------------------------------------------
	-- Borra exenciones de impuestos ya vencidas
	-- -------------------------------------------
	--BEGIN TRANSACTION
		DELETE FROM tbTaxFree4Customers
			WHERE	tffc_up2Date IS NOT NULL AND
					tffc_up2Date < @DateUpdate
		DELETE FROM tbTaxFree4Suppliers
			WHERE	tffs_up2Date IS NOT NULL AND
					tffs_up2Date < @DateUpdate
	--COMMIT TRANSACTION
	--CHECKPOINT
	-- -------------------------------------------



	-- -------------------------------------------
	-- Borra los recalculos de potencial para ordenamiento
	-- -------------------------------------------
	--BEGIN TRANSACTION
		UPDATE tbItemStorage
			SET		itst_LastAvailableInRelalculation = NULL
			WHERE	itst_LastAvailableInRelalculation IS NOT NULL
	--COMMIT TRANSACTION
	--CHECKPOINT
	-- -------------------------------------------

	-- Borra los procesos de SQL con mas de 60 minutos de inactividad.!
	EXEC spSystem_FreeProcesses


	-- -------------------------------------------
	-- Efectua el depurado de datos para alivianar
	-- la base de datos SQL
 	-- -------------------------------------------
 	--BEGIN TRANSACTION
		DELETE FROM tbWorkflow
			WHERE	comp_id = @comp_id	AND
					bra_id  = @bra_id	AND
					wf_type = 666
	--COMMIT TRANSACTION
	--CHECKPOINT


 	IF EXISTS(
 				SELECT TOP 1 1
 					FROM tbBranchPurge tbp
 					INNER JOIN tbBranch tb
 						ON	tb.comp_id				= tbp.comp_id	AND
 							tb.bra_id				= tbp.bra_id
 					WHERE	tbp.comp_id				= @comp_id		AND
 							tbp.bra_id				= @bra_id		AND
 							tb.bra_EnablePurgeData	= 'True'
 		)
 		BEGIN
 			DECLARE @intDays		AS INT
 			DECLARE @intUser4Notify AS INT
			SELECT	@intDays		= tbp.bd_days4Purge ,
					@intUser4Notify = tbp.user_id4Notify
				FROM tbBranchPurge tbp
				WHERE	tbp.comp_id = @comp_id AND
						tbp.bra_id	= @bra_id




			-- Selecciona todos los comprobantes para los que la diferencia de dias sea mayor al especificado.
			DECLARE @tblCommercialTransactions TABLE (comp_id	INT, ct_transaction INT)
			INSERT INTO @tblCommercialTransactions
			(
				comp_id,
				ct_transaction
			)
				SELECT      tct.comp_id,
					        tct.ct_transaction
					FROM	tbCommercialTransactions tct
					WHERE	tct.comp_id = @comp_id		AND
							tct.bra_id	= @bra_id		AND
							--(tct.cust_id IS NOT NULL				112017
							--	OR
							-- tct.supp_id IS NOT NULL )	AND
							tct.ct_ABalance = 0			AND
							DATEDIFF(day,tct.ct_date, @datActualProcessingDate) > @intDays


--==
--SELECT * FROM @tblCommercialTransactions
--==

			DECLARE curPurge  CURSOR LOCAL FAST_FORWARD FOR
				SELECT	tbp.comp_id,
						tbp.ct_transaction
					FROM @tblCommercialTransactions tbp
			DECLARE @intPurgeCompId			AS INT
			DECLARE @intPurgeCtTransaction  AS INT
			DECLARE @bitIsOK				AS BIT
			DECLARE @intReturn_value			AS INT
			DECLARE @intRet_ErrorCode			AS INT
			DECLARE @strRet_ErrorDescription	AS NVARCHAR(200)

			SET @bitIsOK = 'True'

			OPEN  curPurge
			FETCH NEXT FROM curPurge INTO   @intPurgeCompId,@intPurgeCtTransaction

			WHILE @@FETCH_STATUS = 0
				BEGIN
					BEGIN TRY

--==
--SELECT @intPurgeCompId,@intPurgeCtTransaction
--==

--==
--SELECT 'Procesando',@intPurgeCtTransaction
--==

						EXEC spCommercialTransactions_deleteAll
							@comp_id				= @intPurgeCompId,
							@ct_transaction			= @intPurgeCtTransaction,
							@lang_id				= 2,
							@bitBalanceEqualTotal	= 'False',
							@return_value			= @intReturn_value			OUTPUT,
							@ret_ErrorCode			= @intRet_ErrorCode			OUTPUT,
							@ret_ErrorDescription	= @strRet_ErrorDescription	OUTPUT




							IF @intRet_ErrorCode <> 0
								BEGIN
--==
--SELECT @intPurgeCompId,@intPurgeCtTransaction,@intRet_ErrorCode,@strRet_ErrorDescription,'ERRORRRR'
--==


									SET @bitIsOK = 'False'
									INSERT INTO tbWorkflow
									(
										comp_id,
										bra_id,
										wf_type,
										wf_isProcessed,
										user_id_from,
										user_id_assigned,
										user_id_processed,
										prof_id_assigned,
										wf_dateOfAssigned,
										wf_dateOfProcessing,
										wf_link,
										wf_message1,
										wf_message2,
										wf_htmlTop,
										wf_htmlBody,
										wf_html_Bottom
									)
									VALUES
									(
										@comp_id,
										@bra_id,
										666,
										'False',
										NULL,
										@intUser4Notify,
										NULL,
										NULL,
										GETDATE(),
										NULL,
										'',
										'ERROR en Depurado de Datos, avisar al administrador del sistema.',
										'',
										@strRet_ErrorDescription,
										'',
										''
									)
									BREAK
								END

					END TRY
					BEGIN CATCH
						SET @bitIsOK = 'False'
						INSERT INTO tbWorkflow
						(
							comp_id,
							bra_id,
							wf_type,
							wf_isProcessed,
							user_id_from,
							user_id_assigned,
							user_id_processed,
							prof_id_assigned,
							wf_dateOfAssigned,
							wf_dateOfProcessing,
							wf_link,
							wf_message1,
							wf_message2,
							wf_htmlTop,
							wf_htmlBody,
							wf_html_Bottom
						)
						VALUES
						(
							@comp_id,
							@bra_id,
							666,
							'False',
							NULL,
							@intUser4Notify,
							NULL,
							NULL,
							GETDATE(),
							NULL,
							'',
							'ERROR en Depurado de Datos - CATCH, Avisar al Administrador de sistemas',
							'',
							'',
							'',
							''
						)
						BREAK
					END CATCH

					FETCH NEXT FROM curPurge INTO   @intPurgeCompId,@intPurgeCtTransaction
				END

			IF @bitIsOK = 'True'
				BEGIN
					INSERT INTO tbWorkflow
						(
							comp_id,
							bra_id,
							wf_type,
							wf_isProcessed,
							user_id_from,
							user_id_assigned,
							user_id_processed,
							prof_id_assigned,
							wf_dateOfAssigned,
							wf_dateOfProcessing,
							wf_link,
							wf_message1,
							wf_message2,
							wf_htmlTop,
							wf_htmlBody,
							wf_html_Bottom
						)
						VALUES
						(
							@comp_id,
							@bra_id,
							666,
							'False',
							NULL,
							@intUser4Notify,
							NULL,
							NULL,
							GETDATE(),
							NULL,
							'',
							'Depurado de Datos OK',
							'',
							'',
							'',
							''
						)
				END


			CLOSE		 curPurge
			DEALLOCATE	 curPurge


 		END
	-- -------------------------------------------



	-- --------------------------------------------------------------------------------------
	-- ATENCION
	-- Modificar tambien en trigger de tbBranch, trUserCompanyProfile y spBranch_UpdateData
	-- --------------------------------------------------------------------------------------
	--BEGIN TRANSACTION
	BEGIN TRY
	   TRUNCATE TABLE	tbUsers4BranchFilter
	   DELETE FROM		tbUsers4BranchFilter
	   INSERT INTO		tbUsers4BranchFilter
						(
							comp_id,
							bra_id,
							[user_id],
							ubf_blocked4Cube
						)
						SELECT DISTINCT		tucp.comp_id,
											tucp.bra_id,
											tucp.user_id,
											'False'
								FROM tbUserCompanyProfile tucp					WITH (NOLOCK)
								INNER JOIN tbBranch tb							WITH (NOLOCK)
									ON	tb.comp_id	= tucp.comp_id AND
										tb.bra_id	= tucp.bra_id
								WHERE tb.bra_disabled = 0
		-- Bloquea usuarios para CUBOS.
		UPDATE tbUsers4BranchFilter
			SET	ubf_blocked4Cube = 'True'
			FROM tbUsers4BranchFilter me							WITH (NOLOCK)
			INNER JOIN tbUsers4BranchFilter_Users2BlockCubes me2	WITH (NOLOCK)
				ON	me2.comp_id		= me.comp_id	AND
					me2.bra_id		= me.bra_id		AND
					me2.[user_id]	= me.[user_id]

	END TRY
	BEGIN CATCH
	END CATCH
	--COMMIT TRANSACTION
	--CHECKPOINT
	-- --------------------------------------------------------------------------------------



	-- --------------------------------------------------------------------------------------
	-- Fuerza el cambio de password
	-- --------------------------------------------------------------------------------------
	DECLARE @intDays2ForcePassword AS INT
	SET @intDays2ForcePassword		= 0
	SELECT @intDays2ForcePassword	= tc.comp_passResetDays
		FROM tbCompany tc
		WHERE tc.comp_id = @comp_id
	IF @intDays2ForcePassword <> 0 AND @intDays2ForcePassword IS NOT NULL
		BEGIN
			UPDATE tbuser
				SET user_passForceChange = 1
				WHERE	upper(user_nick) <> 'ERPADMIN'							AND
						upper(user_nick) <> 'ERPSOPORTE'						AND
						upper(user_nick) <> 'ERPSOPORTE2'						AND
						ISNULL(user_passwordResetDisabled,'False') = 'False'	AND
						--upper(user_nick) <> 'GBPIMPLEMENTADOR'	AND
						DATEDIFF(DAY, user_passLastChange,GETDATE()) > @intDays2ForcePassword
		END

	-- --------------------------------------------------------------------------------------


	-- -----------------------------------
	-- Borra temporal de EasyButtons
	-- -----------------------------------
	BEGIN TRY
		TRUNCATE TABLE tbComplexFilter
		DELETE FROM tbComplexFilter
	END TRY
	BEGIN CATCH
		--BEGIN TRANSACTION
			DELETE FROM tbComplexFilter
		--COMMIT TRANSACTION
		--CHECKPOINT
	END CATCH
	-- -----------------------------------


	-- Pone Items de la Publicacion que se active hoy.
	EXEC spItemPublicationActiveItems @comp_id


	--EXEC spCustomer_SetCreditRating @comp_id,
	--								@bra_id,
	--								@DateUpdate,
	--								@user_id,
	--								@prof_id,
	--								@bitIsAutoClose



	-- -----------------------------------
	-- Paga cheques emitidos en Fecha
	-- Si esta configurado en la Sucursal,
	-- Solapa Cierre Diario
	-- -----------------------------------
	IF EXISTS(	SELECT TOP 1  1
	          		FROM tbbranch	WITH (NOLOCK)
	          		WHERE	comp_id							= @comp_id	AND
	          				bra_id							= @bra_id	AND
	          				bra_payEmmitedChequeOnCloseDay	= 'True')
		BEGIN

			DECLARE @ec_id AS INT
			DECLARE @ba_id AS INT
			DECLARE curEmmitedCheque CURSOR LOCAL FAST_FORWARD FOR
				SELECT	tec.ec_id,
						tec.ba_id
					FROM tbEmmitedChecks tec
					WHERE	tec.comp_id		= @comp_id AND
							tec.bra_id		= @bra_id  AND
							tec.ec_PayDate	< @DateUpdate AND
							ISNULL(tec.ec_isPaid,'False') = 'False'
			OPEN		 curEmmitedCheque
			FETCH NEXT FROM curEmmitedCheque
				INTO	@ec_id,
						@ba_id
			WHILE @@FETCH_STATUS = 0
				BEGIN

					-- Marca el Cheque como PAgo
					EXEC spEmittedChecks_UpdateData @comp_id,
													@ec_id,
													@bra_id,
													@ba_id,
													'True',
													@DateUpdate

					-- Efectúa el Asiento Contable Correspondiente
					EXEC spAccountTransaction_InsertdataFromChequePayment	@comp_id,
																			@bra_id,
																			2,
																			@ba_id,
																			@ec_id,
																			'True',
																			@DateUpdate,
																			@user_id,
																			0,
																			0,
																			''

					FETCH NEXT FROM curEmmitedCheque
						INTO	@ec_id,
								@ba_id
				END
			CLOSE		 curEmmitedCheque
			DEALLOCATE	 curEmmitedCheque
		END
	-- -----------------------------------


	EXEC spBranch_UpdateData_ItemTransactionDeliverySupplyProcess4CloseDaily @comp_id, @bra_id, @datActualProcessingDate




	EXEC spPurchaseOrderDetail_calculatePendingCoeficient @comp_id  -- x las dudas recalcula los coeficientes de recepcion de todas las ordenes de compra.


	-- Depurados Varios
	DELETE FROM tbItemTransactionsTmp
		WHERE tis_CD < DATEADD(DAY, -4, GETDATE()) AND bra_id = @bra_id



	-- Si en copañias dice que se le vence el credito hoy, se pone en 1 el maximo
	IF EXISTS(
				SELECT TOP 1  1
					FROM tbCompany tc WITH (NOLOCK)
					WHERE	tc.comp_id = @comp_id											AND
							tc.comp_cust_credit_max_EnableVerificationOfOvercomeDate = 1
				)

		BEGIN
			--BEGIN TRANSACTION
				UPDATE tbcustomer WITH (ROWLOCK)
					SET cust_credit_max_Last	= cust_credit_max,
						cust_credit_max			= 1
					WHERE	comp_id							= @comp_id			AND
							cust_credit_max					> 1					AND
							cust_credit_max_overComeDate	IS NOT NULL			AND
							cust_credit_max_overComeDate	< @datActualProcessingDate
			--COMMIT TRANSACTION
			--CHECKPOINT
		END



	-- ------------------------------------------------------------------------
	-- Si la Nota de CRM llego a una determinada fecha de revision
	-- y el tipo de nota dice q en esa fecha se cambie a otro tipo, lo hace.
	-- ------------------------------------------------------------------------
	UPDATE tbCRM_Notes									WITH (ROWLOCK)
		SET	crmnt_id = tcnt.crmnt_id2ConvertUpDate
		FROM tbCRM_Notes			crmn
		INNER JOIN tbBranch			tb					WITH (NOLOCK)
		ON	tb.comp_id			= crmn.comp_id AND
			tb.bra_id			= crmn.bra_id
		INNER JOIN tbCRM_NoteType	tcnt				WITH (NOLOCK)
			ON	tcnt.comp_id	= crmn.comp_id		AND
				tcnt.crmnt_id	= crmn.crmnt_id
	WHERE	crmn.cme_validUpToDate		< tb.bra_processingDate	AND
			tcnt.crmnt_id2ConvertUpDate IS NOT NULL
	-- ------------------------------------------------------------------------

	-- ------------------------------------------------------------------------
	-- Los dias 1 de cada mes da de baja todos los modulos en TEST
	-- ------------------------------------------------------------------------
	IF DAY(@DateUpdate) = 1
		BEGIN
			UPDATE tbcustomer WITH (ROWLOCK)
				SET cust_GBPModules = REPLACE(cust_GBPModules,'2','0')
				WHERE cust_GBPModules LIKE '%2%'
		END
	-- ------------------------------------------------------------------------



	-- ------------------------------------------------------------------------
	-- Da de alta tareas agendadas en el CRM y las asigna al usuario
	-- correspondiente
	-- ------------------------------------------------------------------------
	INSERT INTO tbCRM_Task
	(
		comp_id,
		bra_id,
		task_subject,
		task_date4Begin,
		task_date4End,
		task_priority,
		[user_id],
		task_desc,
		cust_id,
		tast_id ,
		task_price,
		curr_id,
		taskt_id,
		task_emailAdditional,
		user_id_Last,
		task_resolution,
		Task_qty1,
		Task_qty2,
		task_advertiseDate,
		task_advertiseCount,
		supp_id,
		task_nextReviewdate,
		pro_id,
		tasch_id
	)

	SELECT	rr.comp_id,
			@bra_id,
			rr.task_subject,
			@DateUpdate,
			@DateUpdate,
			1,
			rr.[user_id],
			rr.task_desc,
			rr.cust_id,
			rr.tast_id,
			rr.task_price,
			rr.curr_id,
			rr.taskt_id,
			rr.task_emailAdditional,
			rr.[user_id],
			'',
			0,
			0,
			@DateUpdate,
			0,
			rr.supp_id,
			DATEADD(DAY, ISNULL(rr.tasch_Days4NextReview,0),  @DateUpdate),
			rr.pro_id,
			rr.tasch_id



	FROM tbCRM_Task4Schedule rr		WITH (NOLOCK)
	WHERE rr.comp_id = @comp_id AND
		(
			rr.bra_id = @bra_id OR
			rr.bra_id IS NULL
		)						AND
		(
			(rr.tasch_Year = YEAR(@DateUpdate)		OR rr.tasch_Year	= 0)
				AND
			(rr.tasch_Month= MONTH(@DateUpdate)		OR rr.tasch_Month	= 0)
				AND
			(rr.tasch_Day  = DAY(@DateUpdate)		OR rr.tasch_Day		= 0)
				AND
			(rr.tasch_DayOfWeek = DATEPART(weekday,@DateUpdate) OR rr.tasch_DayOfWeek = 0 )
		)
	-- ------------------------------------------------------------------------


	-- Des selecciona el campo de Clonado
	UPDATE tbdocumentsfile	WITH (ROWLOCK)
		SET df_isAvailable4DesignClone = 0
		WHERE	comp_id						= @comp_id	AND
				bra_id						= @bra_id	AND
				df_isAvailable4DesignClone	= 1

	-- Deshabilita clonado de sitios web
	UPDATE	tbWebSiteII_Names	WITH (ROWLOCK)
		SET		ws_enable4Clone = 0
		WHERE	ws_enable4Clone = 1


	-- Borra las autoprocesadas con error.-  SACA la MArca para el reordenamiento de procesamiento automatico que las lleva siempre al final.
	UPDATE tbSaleOrderHeader WITH (ROWLOCK)
		SET	soh_autoprocessLastOrder = 'False'
		WHERE comp_id = @comp_id


	-- MOS 06-2023: x tema performance en fnGetAStock, es AL PEDO que quede pod_includeInAvailableStock = 1 si ya está procesada.
	UPDATE tbPurchaseOrderDetail
		SET pod_includeInAvailableStock		= 0
		WHERE	pod_isProcessed				= 1 AND
				pod_includeInAvailableStock = 1


END



-- MOS 04-2022: Ante una RECAGADA de SQL que hace que se cuelque sin interbloqueos este SP, x las dudas lo mando a recompilar
