--	IF EXISTS(SELECT TOP 1 1 FROM tbcompany WITH (NOLOCK) WHERE comp_daylyRecompileSP = 'True')
--		BEGIN
--			EXEC spSystem_SetStoredProceduresRecompilation;
--		END
--END TRY
