-- -------------------------------------------
-- Depurado de Pedidos
-- -------------------------------------------
BEGIN TRY
	EXEC spSaleOrder_PurificationOrders
		@comp_id,
		@bra_id,
		@datActualProcessingDate,
		''
END TRY
BEGIN CATCH
END CATCH
-- -------------------------------------------
GO



CREATE PROCEDURE [dbo].[spBranch_UpdateData_ItemTransactionDeliverySupplyProcess4CloseDaily]
(
	@comp_id				INT,
	@bra_id					INT,
	@ProcessDate			DATETIME
)
AS

	BEGIN
		SET DATEFORMAT 'YMD'
		SET NOCOUNT ON
		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@bra_id			INT,
				@ProcessDate	DATETIME
			SELECT
				@comp_id		= 1,
				@lang_id		= 2,
				@bra_id			= 1,
				@ProcessDate	= '2016-03-18'
		*/
		-- ----------------------------------------------
		DECLARE
			@return_value			INT,
			@ret_ErrorCode			INT,
			@ret_ErrorDescription	VARCHAR(200),
			@datefrom				DATETIME,
			@dateto					DATETIME


		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@ProcessDate,'False')
		SET @datefrom	= DATEADD( MONTH, -5, @datefrom)


		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@ProcessDate,'True')

		--SELECT @datefrom, @dateto

		SET @return_value			=	0
		SET @ret_ErrorCode			=	0
		SET @ret_ErrorDescription	=	''


		BEGIN TRANSACTION
			BEGIN TRY

				-- ----------------------------------------------------------------------
				-- CANTIDAD DE INSUMOS UTILIZADOS DENTRO DE UN RANGO DE FECHAS
				-- GUARDAMOS EN UNA TEMPORAL
				-- ----------------------------------------------------------------------
					DECLARE
					@tblSuppliesData TABLE(
											ItemId			INT,
											stor_id			INT,
											QTY				INT
										   )
					INSERT INTO @tblSuppliesData
					(
						ItemId,
						stor_id,
						QTY
					)
					SELECT
						titds.item_id,
						titds.stor_id,
						COUNT(*)												[Total]
						FROM tbItemTransactionsDeliverySupply					titds
							INNER JOIN tbCommercialTransactions					tct
								ON	tct.comp_id			= titds.comp_id			AND
									tct.ct_transaction	= titds.ct_transaction
						WHERE	titds.comp_id	= @comp_id						AND
								tct.bra_id		= @bra_id						AND
								titds.itds_cd BETWEEN @datefrom AND @dateto		AND
								titds.itds_pending2Stock = 'True'
						GROUP BY titds.item_id, titds.stor_id


				--SELECT * FROM @tblSuppliesData
				-- ----------------------------------------------------------------------

				-- ----------------------------------------------------------------------
				-- ACA GRABAMOS EL CT_TRANSACTION
				-- ----------------------------------------------------------------------

					-- DECLARO VARIABLES DE TRABAJO
						DECLARE
							@curr_id			INT,
							@df_id				INT,
							@sd_id				INT,
							@docNumber			INT,
							@lCt_Transaction	INT


						-- RECUPERAMOS LOS VALORES
						-- MONEDA DE LA SUCURSAL
						-- DOCUMENTO ASIGNADO PARA EL MOVIMIENTO DE INSUMOS
						-- SD_ID CORRESPONDIENTE A ESE DOCUMENTO
						SELECT
							@curr_id	= tb.curr_id,
							@df_id		= tb.df_id4deliverySupply,
							@sd_id		= tdf.sd_id,
							@docNumber	= tdf.df_number + 1
							FROM tbBranch tb
							INNER JOIN tbDocumentsFile						tdf
								ON	tdf.comp_id = tb.comp_id				AND
									tdf.bra_id	= tb.bra_id					AND
									tdf.df_id	= tb.df_id4deliverySupply
							WHERE	tb.comp_id		= @comp_id					AND
									tb.bra_id		= @bra_id


					--SELECT @curr_id, @df_id, @sd_id, @docNumber


					IF @df_id IS NOT NULL
						BEGIN

							UPDATE tbDocumentsFile
							SET
								df_number	= @docNumber
							WHERE	comp_id = @comp_id AND
									df_id	= @df_id


							INSERT INTO tbCommercialTransactions
							(
								comp_id,
								bra_id,
								ct_pointOfSale,
								ct_docNumber,
								ct_date,
								ct_taxDate,
								ct_payDate,
								supp_id,
								cust_id,
								ct_cd,
								ct_subtotal,
								ct_total,
								curr_id_transaction,
								df_id,
								sd_id,
								ct_discount,
								ct_taxes,
								ct_ATotal,
								ct_ABalance
							)
							VALUES
							(
								@comp_id,
								@bra_id,
								0,
								@docNumber,
								@ProcessDate,
								@ProcessDate,
								@ProcessDate,
								NULL,
								NULL,
								GETDATE(),
								0,
								0,
								@curr_id,
								@df_id,
								@sd_id,
								0,
								0,
								0,
								0
							)
							SET @lCt_Transaction = @@IDENTITY

							--SELECT @lCt_Transaction

							--UNA VEZ INSERTADO EL CT_TRANSACTION
							--INSERTAMOS UN IT_TRANSACTION POR CADA REGISTRO EN LA TABLA
							DECLARE
								@ItemId	INT,
								@StorId	INT,
								@Qty	INT

							DECLARE cursor_IT CURSOR LOCAL FAST_FORWARD FOR
								SELECT
									tmp.ItemId,
									tmp.stor_id,
									tmp.QTY * -1
									FROM @tblSuppliesData	tmp

								OPEN	cursor_IT

								-- lectura anticipada del cursor
								FETCH	cursor_IT
									INTO	@ItemId,
											@StorId,
											@Qty


								-- se recorre el cursor hasta el fin del mismo
								WHILE   @@FETCH_STATUS = 0
									BEGIN

										EXEC spItemTransactions_InsertStock4StorageFastAdjustment	@comp_id,
																									@bra_id,
																									@lCt_Transaction,
																									@ItemId,
																									@Qty,
																									@curr_id,
																									@StorId,
																									-1,
																									152,
																									@return_value,
																									@ret_ErrorCode,
																									@ret_ErrorDescription

										SELECT 1
										-- próxima lectura del cursor
										FETCH	cursor_IT
											INTO	@ItemId,
													@StorId,
													@Qty

									END
								CLOSE cursor_IT
								DEALLOCATE cursor_IT

						-- ----------------------------------------------------------------------


						--UNA VEZ QUE SE PROCESARON TODOS LOS INSUMOS PROCEDEMOS A CAMBIARLES EL ESTADO.
						UPDATE tbItemTransactionsDeliverySupply
						SET
							itds_pending2Stock = 'False'
						FROM tbItemTransactionsDeliverySupply					titds
							INNER JOIN tbCommercialTransactions					tct
								ON	tct.comp_id			= titds.comp_id			AND
									tct.ct_transaction	= titds.ct_transaction
						WHERE	titds.comp_id	= @comp_id						AND
								tct.bra_id		= @bra_id						AND
								titds.itds_cd	BETWEEN @datefrom AND @dateto
						END

						COMMIT TRANSACTION

			END TRY
			BEGIN CATCH
				ROLLBACK TRANSACTION
				DECLARE @ErrorMessage   NVARCHAR(4000)
				DECLARE @ErrorSeverity  INT
				DECLARE @ErrorState     INT
				SELECT  @ErrorMessage    = ERROR_MESSAGE(),
						@ErrorSeverity   = ERROR_SEVERITY(),
						@ErrorState      = ERROR_STATE()
				IF      @ErrorState      = 0 SET @ErrorState = 1
				RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)
			END CATCH

	END
GO







CREATE PROCEDURE [dbo].[spBranchGroup_getCombo]
(
	@comp_id			INT,
	@user_id			int
)
as



BEGIN

	-- Retorna los grupos de sucursales para los que el usuario tenga acceso a algujna sucursal del grupo

	set nocount on


--	-----------------------------------------------------------
-- Testing
--	-----------------------------------------------------------
	/*
	declare @comp_id			INT,
			@user_id			INT

	select	@comp_id			=1,
			@user_id			=3
	*/
--	-----------------------------------------------------------


	DECLARE @tblBranchs TABLE(bra_id		INT PRIMARY KEY)

	INSERT INTO @tblBranchs
		(
			bra_id
		)
		SELECT distinct tucp.bra_id
		FROM tbUserCompanyProfile tucp
		WHERE	tucp.comp_id	= @comp_id AND
				tucp.[user_id]	= @user_id


--==
--SELECT * FROM @tblBranchs
--==

	select		brag_id		[id],
				brag_desc	[desc]
		from		dbo.tbBranchGroup bg
		where		comp_id			= @comp_id AND
						EXISTS(
									SELECT 1
										FROM tbBranchGroupDetail tbgd
										inner JOIN @tblBranchs tmp
											ON	tmp.bra_id		= tbgd.bra_id
										WHERE	tbgd.brag_id	= bg.brag_id --and
												--tmp.bra_id IS NULL
								)
		Order By	brag_desc


END











GO







