CREATE PROCEDURE [dbo].[spBranchTransfer_getData]
(
	@comp_id		INT,
	@bra_id			INT,
	@supp_id		INT
)
AS SET NOCOUNT ON


/*
	DECLARE
		@comp_id	INT,
		@bra_id		INT,
		@supp_id	INT
	SELECT
		@comp_id	= 1,
		@bra_id		= 4,
		@supp_id	= 8103
*/

	DECLARE
		@supp_curr INT,
		@bra_curr  INT,
		@exchange  DECIMAL(19,6)

	SELECT
		@supp_curr  = ts.curr_id

		FROM	tbSupplier ts			WITH (NOLOCK)
		WHERE	ts.comp_id = @comp_id
			AND ts.supp_id = @supp_id

	SELECT
		@bra_curr  = tb.curr_id

		FROM tbBranch tb				WITH (NOLOCK)
		WHERE tb.comp_id = @comp_id
		AND tb.bra_id = @bra_id

	SELECT @exchange = dbo.fnGetExchange2(@comp_id,1,@supp_curr,@bra_curr,@supp_curr,@bra_curr,0,0)

	SELECT
		@supp_curr,
		@bra_curr,
		@exchange
GO





