CREATE PROCEDURE [dbo].[spBranchTransferreceptionControl_getData]
(

	@comp_id					INT,
	@ct_transaction				INT


)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE	  	@comp_id				INT,
			@ct_transaction			INT


SELECT		@comp_id						= 1,
			@ct_transaction					= 8336

*/
-- ------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SELECT	' '																			[ ],
			ti.item_code																[item_code],
			ti.item_desc																[item_desc],
			tbtc.itr_qty_Transfered														[itr_qty_Transfered],
			tbtc.itr_qty_Pending2Verify													[itr_qty_Pending2Verify],
			convert(varchar,tbtc.ct_transaction) + '|'+ convert(varchar,ti.item_id)     [ID]


		FROM tbBranchTransferreceptionControl					tbtc		WITH (NOLOCK)
		INNER JOIN tbItem										ti			WITH (NOLOCK)
			ON		ti.comp_id = tbtc.comp_id  AND
					ti.item_id = tbtc.item_id


		WHERE tbtc.comp_id			= @comp_id			AND
			  tbtc.ct_transaction	= @ct_transaction	AND
			  (tbtc.itr_qty_Transfered <> 0 OR tbtc.itr_qty_Pending2Verify <> 0)


END
GO





CREATE PROCEDURE [dbo].[spBranchTransferreceptionControl_getData_SearchCode]
(
	@comp_id				int,
	@bra_id					int,
	@ct_transaction			INT,
	@strCodeToSearch		NVARCHAR(200),
	@qty_entered			DECIMAL(19,4),
	@guid					UNIQUEIDENTIFIER,
	@prof_id				INT

)
as


BEGIN

	set nocount on

	-- --------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------
	/*
	  DECLARE
		@comp_id				int,
		@bra_id					int,
		@ct_transaction			INT,
		@strCodeToSearch		NVARCHAR(200),
		@qty_entered			DECIMAL(19,4),
		@guid					uniqueidentifier

	  SELECT
		@comp_id				= 1,
		@bra_id					= 1,
		@ct_transaction			= 10723,
		@strCodeToSearch		= 'D1',
		@qty_entered			= 1,
		@guid					= '70b9e524-d7a9-4df9-8c31-209aff218a97'
	*/
	-- --------------------------------------------------------------------------

	DECLARE @qty_CheckingTable	AS DECIMAL(19,4) --itemparts
	DECLARE @item_id			AS INT
	DECLARE @is_id				AS INT
	SET		@is_id				= NULL

	IF @strCodeToSearch <> ''
		BEGIN
			exec [spItemPartsCheckingProcess]@comp_id,@guid ,@qty_entered OUTPUT,@strCodeToSearch OUTPUT



			SET @qty_CheckingTable = @qty_entered

			IF @strCodeToSearch = '-1'
				BEGIN
					--ES UNA PARTE.
					SELECT 0
					RETURN
				END
			ELSE
				BEGIN
					DECLARE @bolIsSerial AS BIT
					SET		@bolIsSerial = 'False'
					DECLARE @item_expser  AS BIT
					SET		@item_expser = 'False'



					SELECT
						TOP 1	@item_id		=	ti.item_id,
								@bolIsSerial	=	CASE
														WHEN tis.comp_id IS NULL THEN	'False'
														ELSE							'True'
													END,
								@is_id			= tis.is_id,
								@item_expser	= ti.item_expser
						--SELECT TOP 1  *
						FROM tbItem		ti							WITH(NOLOCK)

						INNER JOIN tbBranchTransferreceptionControl tmp	WITH(NOLOCK)
							ON	tmp.comp_id			= ti.comp_id		AND
								tmp.ct_transaction	= @ct_transaction	AND
								tmp.item_id			= ti.item_id

						LEFT JOIN tbItemEAN tie						WITH (NOLOCK)
							ON	tie.comp_id		= ti.comp_id	AND
								tie.item_id		= ti.item_id	AND
								tie.ie_ean		= @strCodeToSearch

						LEFT JOIN tbItemSerials				tis		WITH(NOLOCK)
							ON	tis.comp_id		= ti.comp_id		AND
								tis.item_id		= ti.item_id		AND
								tis.is_serial   = @strCodeToSearch

						WHERE ti.comp_id		= @comp_id			AND
							  (
							    ti.item_code   = @strCodeToSearch  OR		-- Si es el codigo del articulo o..
							   (/*ti.item_expean = 'True' AND  */	tie.ie_ean		= @strCodeToSearch)  OR		-- Si es un EAN Adicional
							   (ti.item_expser = 'True' AND			tis.is_serial	= @strCodeToSearch)			-- Si es un Nro de Serie
							  )

				END
		END


	IF @item_id IS NULL
		BEGIN
			-- No hay ningun item con ese codigo o numero de serie
			SELECT 0
			RETURN
		END



	IF @bolIsSerial = 'False'
		BEGIN

			-- ------------------------------------------------------------------------------------------
			--Permitir ingreso de articulos serializables solo por numero de serie
			--10/07/2017
			-- ------------------------------------------------------------------------------------------
			if exists (select
						1
						from tbControlProfiles						tc	WITH (NOLOCK)
						where	tc.comp_id	= @comp_id			AND
								tc.bra_id	= @bra_id			AND
								tc.prof_id	= @prof_id			AND
								tc.page_id	= 623				AND
								tc.ctrl_id  = 4872
						)
							AND @item_expser= 'True'

				BEGIN
					SELECT 0
					RETURN
				END
			-- ------------------------------------------------------------------------------------------


			DECLARE @bolIdUpdated			AS BIT -- Para saber si actualizo cantidad o no .
			DECLARE @qty_availablebycode	AS DECIMAL(19,4)
			SET     @bolIdUpdated = 'False'

			SET  @qty_availablebycode = (SELECT
											tmp.itr_qty_Transfered -  tmp.itr_qty_Pending2Verify

											FROM tbBranchTransferreceptionControl		tmp		WITH(NOLOCK)

											INNER JOIN tbItem							ti		WITH(NOLOCK)
											ON	ti.comp_id = tmp.comp_id AND
												ti.item_id = tmp.item_id

											WHERE	tmp.comp_id					= @comp_id			AND
													tmp.ct_transaction			= @ct_transaction	AND
													ti.item_id					= @item_id
										)

			-- Por Código
			IF @qty_entered <= @qty_availablebycode
				BEGIN
					UPDATE tbBranchTransferreceptionControl		WITH (ROWLOCK)
						SET  itr_qty_Pending2Verify = itr_qty_Pending2Verify + @qty_entered
						FROM tbBranchTransferreceptionControl		tmp		--WITH(NOLOCK)

						INNER JOIN tbItem							ti		WITH(NOLOCK)
							ON	ti.comp_id = tmp.comp_id AND
								ti.item_id = tmp.item_id

						WHERE	tmp.comp_id					= @comp_id						AND
								tmp.ct_transaction			= @ct_transaction				AND
								tmp.itr_qty_Pending2Verify  < tmp.itr_qty_Transfered		AND
								ti.item_id					= @item_id						AND
								@qty_entered				<= tmp.itr_qty_Transfered
				END
			ELSE

				BEGIN

					UPDATE tbBranchTransferreceptionControl
						SET  itr_qty_Pending2Verify = itr_qty_Pending2Verify + @qty_availablebycode
						FROM tbBranchTransferreceptionControl		tmp			WITH(NOLOCK)

						INNER JOIN tbItem							ti			WITH(NOLOCK)
							ON	ti.comp_id = tmp.comp_id AND
								ti.item_id = tmp.item_id

						WHERE	tmp.comp_id					= @comp_id						AND
								tmp.ct_transaction			= @ct_transaction				AND
								tmp.itr_qty_Pending2Verify  < tmp.itr_qty_Transfered		AND
								ti.item_id					= @item_id

				END

			IF @@ROWCOUNT > 0 SET @bolIdUpdated = 'True'

		END

	IF @bolIsSerial = 'True'

					--IF @@ROWCOUNT > 0 SET @bolIdUpdated = 'True'

					-- Por Numero de Serie
					--IF @bolIdUpdated = 'False' -- Si sigue en False quiere decir que no actualizo y ahora se hara el chequeo por numero de serie
		BEGIN

			-- ------------------------------------------------------------------------------------------
			-- MOS 12-2016 x Datasoft
			-- Si el NUMERO DE SERIE ingresado NO EXISTE COMO SERIALIZADO en el remito, NO LO TOMA
			-- ------------------------------------------------------------------------------------------
			IF NOT EXISTS(
							SELECT 1
								FROM tbItemTransactionSerials tits	WITH (NOLOCK)
								WHERE	tits.comp_id		= @comp_id			AND
										tits.ct_transaction = @ct_transaction	AND
										tits.is_id			= @is_id
						)
				BEGIN
					SELECT 0
					RETURN
				END
			-- ------------------------------------------------------------------------------------------


			-- ------------------------------------------------------------------------------------------
			-- MOS 06-2017 x Datasoft
			-- No se puede tomar mas de un mismo nro de serie en la recepcion
			-- ------------------------------------------------------------------------------------------
			IF  EXISTS(
							SELECT 1
								FROM tbBranchTransferreceptionControl_ItemSerialsRelated tits	WITH (NOLOCK)
								WHERE	tits.comp_id		= @comp_id AND
										tits.ct_transaction = @ct_transaction AND
										tits.is_id			= @is_id
						)
				BEGIN
					SELECT 0
					RETURN
				END
			IF @is_id IS NOT NULL AND @item_id IS NOT NULL
				BEGIN
					INSERT INTO tbBranchTransferreceptionControl_ItemSerialsRelated		WITH (ROWLOCK)
							(comp_id,
							 ct_transaction,
							 item_id,
							 is_id
							 )
						VALUES(@comp_id, @ct_transaction, @item_id, @is_id)
				END
			-- ------------------------------------------------------------------------------------------







			DECLARE @qty_availablebyserial AS DECIMAL(19,4)

			SET  @qty_availablebyserial = (SELECT
												tmp.itr_qty_Transfered -  tmp.itr_qty_Pending2Verify
												FROM tbBranchTransferreceptionControl	tmp				WITH(NOLOCK)

												INNER JOIN tbItemSerials				tis				WITH(NOLOCK)
												ON	tis.comp_id			= tmp.comp_id			AND
													tis.item_id			= tmp.item_id

												WHERE	tmp.comp_id					= @comp_id						AND
														tmp.ct_transaction			= @ct_transaction				AND
														tis.is_serial				= @strCodeToSearch
											)

			IF @qty_entered <= @qty_availablebyserial
				BEGIN

					UPDATE tbBranchTransferreceptionControl		WITH (ROWLOCK)

						SET	itr_qty_Pending2Verify = itr_qty_Pending2Verify + @qty_entered

						FROM tbBranchTransferreceptionControl	tmp			--WITH(NOLOCK)

						INNER JOIN tbItemSerials				tis			WITH(NOLOCK)
						ON	tis.comp_id			= tmp.comp_id			AND
							tis.item_id			= tmp.item_id

						WHERE	tmp.comp_id					= @comp_id						AND
								tmp.ct_transaction			= @ct_transaction				AND
								tmp.itr_qty_Pending2Verify	< tmp.itr_qty_Transfered		AND
								tis.is_serial				= @strCodeToSearch				AND
								@qty_entered				<= tmp.itr_qty_Transfered
					IF @@ROWCOUNT > 0 SET @bolIdUpdated = 'True'

				END

			ELSE
				BEGIN
					UPDATE tbBranchTransferreceptionControl	WITH (ROWLOCK)

						SET	itr_qty_Pending2Verify = itr_qty_Pending2Verify + @qty_availablebyserial

						FROM tbBranchTransferreceptionControl	tmp			--	WITH(NOLOCK)

						INNER JOIN tbItemSerials				tis				WITH(NOLOCK)
						ON	tis.comp_id			= tmp.comp_id			AND
							tis.item_id			= tmp.item_id

						WHERE	tmp.comp_id					= @comp_id						AND
								tmp.ct_transaction			= @ct_transaction				AND
								tmp.itr_qty_Pending2Verify	< tmp.itr_qty_Transfered		AND
								tis.is_serial				= @strCodeToSearch
					IF @@ROWCOUNT > 0 SET @bolIdUpdated = 'True'

				END


		END






		-- Indica si estan todos los items tomados
		IF @bolIdUpdated = 'True'
			BEGIN
				--'logro incrementar a algun articulo
				exec [spItemPartsCheckingProcess_FreeParts] @comp_id,@guid ,@item_id,@qty_CheckingTable
				SELECT 1
				RETURN
			END
		ELSE
			BEGIN
				--' NO logro incrementar a algun articulo
				SELECT 0
				RETURN
			END


END

GO





create PROCEDURE [dbo].[spBranchTransferreceptionControl_getData_SearchCode_NoItems]
(
	@comp_id				int,
	@bra_id					int,
	@strCodeToSearch		NVARCHAR(200),
	@qty_entered			DECIMAL(19,4)
)
as



BEGIN

	set nocount on

	-- --------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------
	/*
	  DECLARE
		@comp_id				int,
		@bra_id					int,
		@strCodeToSearch		NVARCHAR(200),
		@qty_entered			DECIMAL(19,4)

	  SELECT
		@comp_id				= 1,
		@bra_id					= 1,
		@strCodeToSearch		= 'D124525',
		@qty_entered			= 1
	*/
	-- --------------------------------------------------------------------------


			SELECT
				TOP 1 CONVERT(VARCHAR,@strCodeToSearch) + ' / ' + CONVERT(VARCHAR,isnull(ti.item_desc,'')) + ' / ' + CONVERT(VARCHAR,@qty_entered) [NoItemDesc]

				FROM tbItem		ti							WITH(NOLOCK)

				LEFT JOIN tbItemEAN tie						WITH (NOLOCK)
					ON	tie.comp_id		= ti.comp_id	AND
						tie.item_id		= ti.item_id	AND
						tie.ie_ean		= @strCodeToSearch

				LEFT JOIN tbItemSerials				tis		WITH(NOLOCK)
					ON	tis.comp_id		= ti.comp_id		AND
						tis.item_id		= ti.item_id		AND
						tis.is_serial   = @strCodeToSearch

				WHERE ti.comp_id		= @comp_id			AND
					  (
						ti.item_code   = @strCodeToSearch  OR		-- Si es el codigo del articulo o..
					   (/*ti.item_expean = 'True' AND  */	tie.ie_ean		= @strCodeToSearch)  OR		-- Si es un EAN Adicional
					   (ti.item_expser = 'True' AND			tis.is_serial	= @strCodeToSearch)			-- Si es un Nro de Serie
					  )


END

GO






CREATE PROCEDURE [dbo].[spBranchTransferreceptionControl_getDataById]
(

	@comp_id					INT,
	@ct_transaction				INT


)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE	  	@comp_id				INT,
			@ct_transaction			INT


SELECT		@comp_id						= 1,
			@ct_transaction					= 8336

*/
