	WHERE	tbtc.comp_id		= @comp_id			AND
			tbtc.ct_transaction = @ct_transaction


END
GO







CREATE PROCEDURE [dbo].[spBranchTransferreceptionControl_Initialize_qtyPending]
(
	@comp_id				int,
	@ct_transaction			int,
	@item_id				int,
	@qtyreceived			DECIMAL(19,4),
	@guid					uniqueidentifier
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*
		  DECLARE
  			@comp_id				int,
  			@item_id				int,
  			@ct_transaction			int

		  SELECT
  			@comp_id				= 1,
  			@item_id				= 256,
  			@ct_transaction			= 8336
*/
		-- --------------------------------------------------------------------------




		UPDATE tbBranchTransferreceptionControl

		SET
			 itr_qty_Pending2Verify	= 0,
			 itr_userId4Close		= NULL,
			 itr_closeDate			= NULL



		WHERE  comp_id			= @comp_id			AND
			   ct_transaction	= @ct_transaction	AND
			   item_id			= @item_id



	    UPDATE tbBranchTransferreceptionControl

		SET	 itr_userId4Close		= NULL,
			 itr_closeDate			= NULL



		WHERE  comp_id			= @comp_id			AND
			   ct_transaction	= @ct_transaction


		exec spItemPartsCheckingProcess_MinusParts @comp_id,@guid ,@item_id, @qtyreceived


		-- ------------------------------------------------------------------------------------------
		-- ga 06-2017 x Datasoft
		-- No se puede tomar mas de un mismo nro de serie en la recepcion
		-- borramsos la tabla de nros de series relacionados.
		-- ------------------------------------------------------------------------------------------
		DELETE
			FROM tbBranchTransferreceptionControl_ItemSerialsRelated
			WHERE	comp_id			= @comp_id			AND
					ct_transaction	= @ct_transaction	AND
					item_id			= @item_id





END

GO







CREATE PROCEDURE [dbo].[spBranchTransferreceptionControl_InsertData]
(


	@comp_id					INT,
	@ct_transaction				INT

)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE	  	@comp_id				INT,
				@ct_transaction			INT,
				@item_id				INT,
				@itr_qty_Transfered		decimal(19,4),
			    @itr_qty_Pending2Verify	decimal(19,4)


	SELECT		@comp_id					= 1,
				@item_id					= 256,
				@itr_qty_Transfered			= 20,
				@ct_transaction				= 8336,
				@itr_qty_Pending2Verify		= 0

*/
-- ------------------------------------------------------


	IF not EXISTS ( SELECT tbtc.ct_transaction
						FROM tbBranchTransferreceptionControl tbtc
						WHERE	tbtc.comp_id		= @comp_id AND
								tbtc.ct_transaction = @ct_transaction
				  )
		BEGIN

				INSERT INTO tbBranchTransferreceptionControl
				(
					comp_id,
					ct_transaction,
					item_id,
					itr_qty_Transfered,
					itr_qty_Pending2Verify
				)
				SELECT
							tit.comp_id,
							tit.ct_transaction,
							tit.item_id,
							SUM(tit.it_qty),
							0
					FROM	tbItemTransactions tit		WITH (NOLOCK)
					WHERE	tit.comp_id			= @comp_id			AND
							tit.ct_transaction	= @ct_transaction	AND
							tit.item_id IS NOT NULL
				GROUP BY	tit.comp_id,
							tit.ct_transaction,
							tit.item_id

		END

END
GO







CREATE PROCEDURE [dbo].[spBranchTransferreceptionControl_TransferVerification]
(
	@comp_id				int,
	@ct_transaction			int
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
		/*
		  DECLARE
  			@comp_id				int,
  			@ct_transaction			INT


		  SELECT
  			@comp_id				= 1,
  			@ct_transaction			= 8336
		*/
		-- --------------------------------------------------------------------------



		  Select	tbtc.ct_transaction					[ct_transaction],
  					sum(tbtc.itr_qty_Transfered)		[itr_qty_Transfered],
  					sum(tbtc.itr_qty_Pending2Verify)	[itr_qty_Pending2Verify]
			  From		 tbBranchTransferreceptionControl				tbtc		WITH (NOLOCK)
			  Where			tbtc.comp_id			=		@comp_id
			  AND			tbtc.ct_transaction		=		@ct_transaction
			  GROUP BY tbtc.ct_transaction




END

GO







create PROCEDURE [dbo].[spBranchTransferreceptionControl_UpdateData_qtyPending]
(
	@comp_id				int,
	@ct_transaction			int,
	@item_id				int,
	@itr_qty_Pending2Verify decimal(19,4)
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*
		  DECLARE
  			@comp_id				int,
  			@item_id				int,
  			@ct_transaction			int,
			@itr_qty_Pending2Verify decimal(19,4)

		  SELECT
  			@comp_id				= 1,
  			@item_id				= 256,
  			@ct_transaction			= 8336,
  			@itr_qty_Pending2Verify = 2
*/
		-- --------------------------------------------------------------------------




		UPDATE tbBranchTransferreceptionControl

		SET
			itr_qty_Pending2Verify = @itr_qty_Pending2Verify


		WHERE  comp_id			= @comp_id			AND
			   ct_transaction	= @ct_transaction	AND
			   item_id			= @item_id





END

GO







