CREATE PROCEDURE [dbo].[spBrand_getData4WebSite]
(
	@comp_id				INT,
    @subcat_id				INT,
	@stor_id				INT,
	@showzerostock			BIT,
	@potentialstocklimit	INT,
	@destiny				INT,
	@ws_id					INT
)
AS

SET NOCOUNT ON


/*
DECLARE @comp_id				INT,
		@subcat_id				INT,
		@stor_id				INT,
		@showzerostock			BIT,
		@potentialstocklimit	INT,
		@destiny				INT,
		@ws_id					INT
SELECT	@comp_id				=1,
		@subcat_id				=-1,
		@stor_id				=1,
		@showzerostock			='false',
		@potentialstocklimit	=60,
		@destiny				=2,
		@ws_id					=23
IF NOT OBJECT_ID('tempdb.dbo.#tmpBrand')	IS NULL DROP TABLE #tmpBrand
*/



CREATE TABLE #tmpBrand (brand_id		INT,
						brand_desc		NVARCHAR(200),
						new_id [int]	IDENTITY(0,1))


INSERT INTO #tmpBrand (brand_id, brand_desc)
SELECT  tb.brand_id,
		tb.brand_desc
		--dbo.fnGetWordsCutByChar(tb.brand_desc,' ',15)		[brand_desc]


FROM	tbBrand tb

WHERE	tb.comp_id	= @comp_id
AND		tb.brand_id IN	(SELECT	ti.brand_id
     						FROM 	tbItem ti
     						WHERE	ti.comp_id		= tb.comp_id
							AND		(ti.subcat_id	= @subcat_id OR @subcat_id = -1)
							AND		ISNULL(ti.item_web,'false')			= 'true'
							AND		ISNULL(ti.item_disabled,'false')	= 'false'
							AND		ISNULL(ti.item_not4Sale,'false')	= 'false'

							AND		(
										(@showzerostock = 'true') OR
										(@showzerostock = 'false' AND
										 CONVERT(integer,
											(dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99) *
											@potentialstocklimit / 100)) > 0
										)
									)
							AND		ti.item_id NOT IN (SELECT tia.item_id FROM tbItemAssociation tia WHERE tia.comp_id = @comp_id)
						)


IF @destiny = 1

BEGIN

	SELECT	tb.brand_id,
			dbo.fnGetWordsCutByChar(tb.brand_desc,' ',15)		[brand_desc]
	FROM	tbBrand						tb
			INNER JOIN #tmpBrand		ttb
			ON tb.brand_id = ttb.brand_id
	ORDER BY tb.brand_desc

END

ELSE

BEGIN


	-- ==========================================================================================================
	-- recuperamos el límite de stock potencial y la marca indicadora de como mostrar los precios del web_site seleccionado
	-- ==========================================================================================================
	DECLARE @ws_PotentialStockLimit			INT,
			@ws_showpricewithtax			BIT,
			@ws_showpricelist				INT,
			@ws_cols						INT,
			@ws_rows						INT,
			@ws_decimals4Price				INT,
			@ws_griddesign_maxlength_desc	INT


	SELECT	@ws_PotentialStockLimit			= twsn.ws_PotentialStockLimit,
			@ws_showpricewithtax			= ISNULL(twsn.ws_showpricewithtax,'false'),
			@ws_showpricelist				= ISNULL(twsn.ws_showpricelist,0),

			@ws_cols						= ISNULL(twsn.ws_brand_griddesign_cells,1),
			@ws_rows						= ISNULL(twsn.ws_brand_griddesign_rows,1),
			@ws_decimals4Price				= twsn.ws_decimals4Price,
			@ws_griddesign_maxlength_desc	= ISNULL(twsn.ws_brand_griddesign_maxlength_desc,100)

	FROM	tbWebSite_Names				twsn

	WHERE	twsn.comp_id	= @comp_id
	AND		twsn.ws_id		= @ws_id
	--SELECT @ws_PotentialStockLimit, @ws_showpricewithtax

	IF @ws_cols > 5
	BEGIN
		SET @ws_cols = 5
	END
	-- ==========================================================================================================





	DECLARE @queryfinal		NVARCHAR(4000)


	SELECT	@queryfinal =
	'SELECT	s.[val], ' +

			's.[col1]														[brand_id1]		,
			dbo.fnGetWordsCutByChar(tb1.brand_desc,'' '',13)				[brand_desc1]		' +

			CASE WHEN @ws_cols > 1 then
			',s.[col2]														[brand_id2],
			dbo.fnGetWordsCutByChar(tb2.brand_desc,'' '',13)				[brand_desc2]		'
			ELSE ''
			END		+


			CASE WHEN @ws_cols > 2 then
			',s.[col3]														[brand_id3],
			dbo.fnGetWordsCutByChar(tb3.brand_desc,'' '',13)				[brand_desc3]		'
			ELSE ''
			END		+


			CASE WHEN @ws_cols > 3 then
			',s.[col4]														[brand_id4],
			dbo.fnGetWordsCutByChar(tb4.brand_desc,'' '',13)				[brand_desc4]		'
			ELSE ''
			END		+


			CASE WHEN @ws_cols > 4 then
			',s.[col5]														[brand_id5],
			dbo.fnGetWordsCutByChar(tb5.brand_desc,'' '',13)				[brand_desc5]		'
			ELSE ''
			END		+

	'FROM	(
			SELECT	convert(int,new_id/' + CONVERT(VARCHAR,@ws_cols) + ')									[val] ' +


			',sum(CASE new_id % ' + CONVERT(VARCHAR,@ws_cols) + ' WHEN 0 THEN ISNULL(brand_id, null) END)	[col1] ' +


			CASE WHEN @ws_cols > 1 then
			',sum(CASE new_id % ' + CONVERT(VARCHAR,@ws_cols) + ' WHEN 1 THEN ISNULL(brand_id, null) END)	[col2] '
			ELSE ''
			END		+

			CASE WHEN @ws_cols > 2 then
			',sum(CASE new_id % ' + CONVERT(VARCHAR,@ws_cols) + ' WHEN 2 THEN ISNULL(brand_id, null) END)	[col3] '
			ELSE ''
			END		+

			CASE WHEN @ws_cols > 3 then
			',sum(CASE new_id % ' + CONVERT(VARCHAR,@ws_cols) + ' WHEN 3 THEN ISNULL(brand_id, null) END)	[col4] '
			ELSE ''
			END		+

			CASE WHEN @ws_cols > 4 then
			',sum(CASE new_id % ' + CONVERT(VARCHAR,@ws_cols) + ' WHEN 3 THEN ISNULL(brand_id, null) END)	[col5] '
			ELSE ''
			END		+

			'FROM	#tmpBrand


			GROUP BY convert(int,new_id/' + CONVERT(VARCHAR,@ws_cols) + ')
			) s '  +

										'left join #tmpBrand tb1 on tb1.brand_id = s.col1 ' +
			CASE WHEN @ws_cols > 1 then	'left join #tmpBrand tb2 on tb2.brand_id = s.col2 ' ELSE '' END +
			CASE WHEN @ws_cols > 2 then	'left join #tmpBrand tb3 on tb3.brand_id = s.col3 ' ELSE '' END +
			CASE WHEN @ws_cols > 3 then	'left join #tmpBrand tb4 on tb4.brand_id = s.col4 ' ELSE '' END +
			CASE WHEN @ws_cols > 4 then	'left join #tmpBrand tb5 on tb5.brand_id = s.col5 ' ELSE '' END


		--SELECT @queryfinal
		EXEC (@queryfinal)


END





GO








CREATE  PROCEDURE [dbo].[spBrand_getDataById]
(
	@comp_id		As Int,
	@brand_id		As Int
)
AS

BEGIN

	set nocount ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

-- --------------------------------------------------------
-- Testing
-- --------------------------------------------------------
	/*
	DECLARE @comp_id		INT,
			@brand_id		int


	select	@comp_id		=1,
			@brand_id		=50
*/
-- --------------------------------------------------------


	SELECT  tb.brand_id,
			tb.bra_id,
			tb.brand_desc,
			tb.brand_image,
			tb.brand_commission,
			tb.brand_commission_byReceive,
			tb.brand_WebSite_id,
			isnull(tb.creditI_up2Pays,0)									[creditI_up2Pays],
			isnull(tb.creditI_creditInterest,0)								[creditI_creditInterest],
			isnull(tb.creditII_up2Pays,0)									[creditII_up2Pays],
			isnull(tb.creditII_creditInterest,0)							[creditII_creditInterest],
			isnull(tb.creditIII_up2Pays,0)									[creditIII_up2Pays],
			isnull(tb.creditIII_creditInterest,0)							[creditIII_creditInterest],
			isnull(tb.creditIV_up2Pays, 0)									[creditIV_up2Pays],
			isnull(tb.creditIV_creditInterest,0)							[creditIV_creditInterest],
			isnull(tb.creditOther_creditInterest,0)							[creditOther_creditInterest]

	FROM 	dbo.tbBrand tb


	WHERE 	tb.comp_id		=	@comp_id
	AND 	tb.brand_id		=	@brand_id



END
GO







