CREATE PROCEDURE [dbo].[spBrand_GlobalChangesParameters_UpdateData]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@prof_id						INT,
	@user_id						INT,

	@option							INT,
	@strdesc						NVARCHAR(200),

	@bitcreditI_up2Pays				BIT,
	@creditI_up2Pays				INT,
	@bitcreditI_creditInterest		BIT,
	@creditI_creditInterest			DECIMAL(19,4),
	@bitcreditII_up2Pays			BIT,
	@creditII_up2Pays				INT,
	@bitcreditII_creditInterest		BIT,
	@creditII_creditInterest		DECIMAL(19,4),
	@bitcreditIII_up2Pays			BIT,
	@creditIII_up2Pays				INT,
	@bitcreditIII_creditInterest	BIT,
	@creditIII_creditInterest		DECIMAL(19,4),
	@bitcreditIV_up2Pays			BIT,
	@creditIV_up2Pays				INT,
	@bitcreditIV_creditInterest		BIT,
	@creditIV_creditInterest		DECIMAL(19,4),
	@bitcreditOther_creditInterest	BIT,
	@creditOther_creditInterest		DECIMAL(19,4)

)

AS




---------------------------------------------------
---------------------------------------------------
/*

DECLARE
		@comp_id						INT,
		@lang_id						INT,
		@bra_id							INT,
		@prof_id						INT,
		@user_id						INT,

		@option							INT,
		@strdesc						NVARCHAR(200),
		@creditI_up2Pays				INT,
		@creditI_creditInterest			DECIMAL(19,4),
		@creditII_up2Pays				INT,
		@creditII_creditInterest		DECIMAL(19,4),
		@creditIII_up2Pays				INT,
		@creditIII_creditInterest		DECIMAL(19,4),
		@creditIV_up2Pays				INT,
		@creditIV_creditInterest		DECIMAL(19,4),
		@creditOther_creditInterest		DECIMAL(19,4)
SELECT
		@comp_id			=1,
		@bra_id				=1,
		@Item_Guid			='1242A2A1-D106-4865-A6AB-70C2567B5004',
		@brand_id			=2,
		@pres_id			=-1,
		@cat_id				=3,
		@subcat_id			=2,
		@subcataux_id		=2,
		@bitsubcataux		='False'

*/

---------------------------------------------------
---------------------------------------------------

BEGIN

SET NOCOUNT ON


		IF @bitcreditI_up2Pays = 'True'
			BEGIN
				UPDATE tbBrand

				SET	creditI_up2Pays	= @creditI_up2Pays

				WHERE comp_id	= @comp_id

			END

		IF @bitcreditI_creditInterest = 'True'
			BEGIN
				UPDATE tbBrand
				SET	creditI_creditInterest	= @creditI_creditInterest
				WHERE comp_id	= @comp_id
			END

		IF @bitcreditII_up2Pays = 'True'
			BEGIN
				UPDATE tbBrand
				SET	creditII_up2Pays = @creditII_up2Pays
				WHERE comp_id	= @comp_id
			END

		IF @bitcreditII_creditInterest = 'True'
			BEGIN
				UPDATE tbBrand
				SET	creditII_creditInterest	= @creditII_creditInterest
				WHERE comp_id	= @comp_id
			END

		IF @bitcreditIII_up2Pays = 'True'
			BEGIN
				UPDATE tbBrand
				SET	creditIII_up2Pays	= @creditIII_up2Pays
				WHERE comp_id	= @comp_id
			END

		IF @bitcreditIII_creditInterest = 'True'
			BEGIN
				UPDATE tbBrand
				SET	creditIII_creditInterest= @creditIII_creditInterest
				WHERE comp_id	= @comp_id
			END

		IF @bitcreditIV_up2Pays = 'True'
			BEGIN
				UPDATE tbBrand
				SET	creditIV_up2Pays	= @creditIV_up2Pays
				WHERE comp_id	= @comp_id
			END

		IF @bitcreditIV_creditInterest = 'True'
			BEGIN
				UPDATE tbBrand
				SET	creditIV_creditInterest	= @creditIV_creditInterest
				WHERE comp_id	= @comp_id
			END

		IF @bitcreditOther_creditInterest = 'True'
			BEGIN
				UPDATE tbBrand
				SET creditOther_creditInterest	= @creditOther_creditInterest
				WHERE comp_id	= @comp_id
			END

END
GO






