create Procedure [dbo].[spBuscarCampos]
(	@SearchText  VARCHAR(100)
)
as
--Variable que contentendrá el texto a buscar, nombre de una tabla, columna, etc...
--DECLARE @SearchText AS VARCHAR(100)
--SET @SearchText = 'costlisti'
--Consulta de las tablas con campos con ese nombre
SELECT t.name AS table_name,

SCHEMA_NAME(schema_id) AS schema_name,

c.name AS column_name

FROM sys.tables AS t

INNER JOIN sys.columns c ON t.OBJECT_ID = c.OBJECT_ID

WHERE c.name LIKE '%' + @SearchText + '%'

ORDER BY schema_name, table_name
GO






CREATE Procedure [dbo].[spBuscarLastSPChanged]

as
	SELECT TOP(1000)
					 type_desc, [create_date], [object_id],[name], [modify_date]
		FROM
