-- Retorna si hay una campa;a comercial que este definida en la URL del sitio web ( pasada como parametro por un tag SEO
-- Por Ejemplo: Adwords-ITRIS
CREATE PROCEDURE [dbo].[spCampaign_getDataBySEO]
(
	@comp_id AS INT,
	@txtSEO  AS NVARCHAR(MAX)
)
AS



BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	SELECT TOP 1	tcc.comp_id,
					tcc.camp_id
		FROM	tbCRM_Campaign tcc	WITH (NOLOCK)
		WHERE	tcc.comp_id		= @comp_id	AND
				tcc.camp_SEOTAG <> ''		AND
				@txtSEO			LIKE '%' + dbo.fnStrAllTrim(tcc.camp_SEOTAG)  + '%'
		ORDER BY tcc.camp_id DESC



END
GO








CREATE PROCEDURE [dbo].[spCampaign_getDataByText]
(
	@text	VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id  AS INT
)
AS



BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*

		DECLARE
			@text		VARCHAR(300),
			@count		INT,
			@lang_id	INT,
			@comp_id AS INT,
			@bra_id  AS INT

		SELECT
			@text		='A',
			@count		= 2,
			@lang_id	= 2,
			@comp_id	= 1,
			@bra_id		= 1
	*/
	-- ----------------------------------------------------------------





	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')



	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)
	DECLARE @text6	varchar(300)
	DECLARE @text7	varchar(300)
	DECLARE @text8	varchar(300)
	DECLARE @text9	varchar(300)
	DECLARE @text10	varchar(300)

	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0 else
			IF @text2 IS NULL SET @text2 = @text0 else
			IF @text3 IS NULL SET @text3 = @text0 else
			IF @text4 IS NULL SET @text4 = @text0 else
			IF @text5 IS NULL SET @text5 = @text0 else
			IF @text6 IS NULL SET @text6 = @text0 else
			IF @text7 IS NULL SET @text7 = @text0 else
			IF @text8 IS NULL SET @text8 = @text0 else
			IF @text9 IS NULL SET @text9 = @text0 else
			IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------





	SELECT		TOP (@count)

				Upper(dbo.PadRightString( IsNull(tc.camp_desc,''),'.',50)) + ' | ' + isnull(convert(VARCHAR(10),tc.camp_id),'')	[camp_desc],
				tc.camp_id
	FROM tbCRM_Campaign tc
			WHERE		tc.comp_id = @comp_id
					--AND (tc.bra_id IS NULL OR tc.bra_id = @bra_id)
		AND
			(

						CASE
							WHEN @selection_method = 0 AND tc.camp_desc LIKE @text + '%'	 THEN	'True'
							WHEN @selection_method = 1 AND tc.camp_desc LIKE '%' + @text1 + '%'	 THEN	'True'
							WHEN @selection_method = 2 AND tc.camp_desc LIKE '%' + @text1 + '%' AND tc.camp_desc LIKE '%' + @text2 + '%'		 THEN	'True'
							WHEN @selection_method = 3 AND tc.camp_desc LIKE '%' + @text1 + '%' AND tc.camp_desc LIKE '%' + @text2 + '%' AND tc.camp_desc LIKE '%' + @text3 + '%'	 THEN	'True'
							WHEN @selection_method = 4 AND tc.camp_desc LIKE '%' + @text1 + '%' AND tc.camp_desc LIKE '%' + @text2 + '%' AND tc.camp_desc LIKE '%' + @text3 + '%' AND tc.camp_desc LIKE '%' + @text4 + '%'		 THEN	'True'
							WHEN @selection_method = 5 AND tc.camp_desc LIKE '%' + @text1 + '%' AND tc.camp_desc LIKE '%' + @text2 + '%' AND tc.camp_desc LIKE '%' + @text3 + '%' AND tc.camp_desc LIKE '%' + @text4 + '%' AND tc.camp_desc LIKE '%' + @text5 + '%'		 THEN	'True'
							WHEN @selection_method = 6 AND tc.camp_desc LIKE '%' + @text1 + '%' AND tc.camp_desc LIKE '%' + @text2 + '%' AND tc.camp_desc LIKE '%' + @text3 + '%' AND tc.camp_desc LIKE '%' + @text4 + '%' AND tc.camp_desc LIKE '%' + @text5 + '%' AND tc.camp_desc LIKE '%' + @text6 + '%'	 THEN	'True'
							WHEN @selection_method = 7 AND tc.camp_desc LIKE '%' + @text1 + '%' AND tc.camp_desc LIKE '%' + @text2 + '%' AND tc.camp_desc LIKE '%' + @text3 + '%' AND tc.camp_desc LIKE '%' + @text4 + '%' AND tc.camp_desc LIKE '%' + @text5 + '%' AND tc.camp_desc LIKE '%' + @text6 + '%' AND tc.camp_desc LIKE '%' + @text7 + '%'	 THEN	'True'
							WHEN @selection_method = 8 AND tc.camp_desc LIKE '%' + @text1 + '%' AND tc.camp_desc LIKE '%' + @text2 + '%' AND tc.camp_desc LIKE '%' + @text3 + '%' AND tc.camp_desc LIKE '%' + @text4 + '%' AND tc.camp_desc LIKE '%' + @text5 + '%' AND tc.camp_desc LIKE '%' + @text6 + '%' AND tc.camp_desc LIKE '%' + @text7 + '%' AND tc.camp_desc LIKE '%' + @text8 + '%'		 THEN	'True'
							WHEN @selection_method = 9 AND tc.camp_desc LIKE '%' + @text1 + '%' AND tc.camp_desc LIKE '%' + @text2 + '%' AND tc.camp_desc LIKE '%' + @text3 + '%' AND tc.camp_desc LIKE '%' + @text4 + '%' AND tc.camp_desc LIKE '%' + @text5 + '%' AND tc.camp_desc LIKE '%' + @text6 + '%' AND tc.camp_desc LIKE '%' + @text7 + '%' AND tc.camp_desc LIKE '%' + @text8 + '%' AND tc.camp_desc LIKE '%' + @text9 + '%'		 THEN	'True'
							WHEN @selection_method =10 AND tc.camp_desc LIKE '%' + @text1 + '%' AND tc.camp_desc LIKE '%' + @text2 + '%' AND tc.camp_desc LIKE '%' + @text3 + '%' AND tc.camp_desc LIKE '%' + @text4 + '%' AND tc.camp_desc LIKE '%' + @text5 + '%' AND tc.camp_desc LIKE '%' + @text6 + '%' AND tc.camp_desc LIKE '%' + @text7 + '%' AND tc.camp_desc LIKE '%' + @text8 + '%' AND tc.camp_desc LIKE '%' + @text9 + '%' AND tc.camp_desc LIKE '%' + @text10 + '%'		 THEN 'True'
							ELSE	'False'
						END	= 'True'

			)



			ORDER BY	tc.camp_desc

END
GO





