CREATE PROCEDURE [dbo].[spCashAccountant_getCombo]
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT
)
AS

BEGIN

	set nocount on

	----------------------------------------
	/*
	declare @comp_id	INT,
			@bra_id		INT

	select  @comp_id	=1,
			@bra_id		= 1

	*/
	----------------------------------------


	IF EXISTS(
				SELECT 1
					FROM tbCashAccountantByProfile tcabp	WITH (NOLOCK)
					WHERE	tcabp.comp_id		= @comp_id AND
							tcabp.bra_id		= @bra_id AND
							tcabp.prof_id		= @prof_id AND
							tcabp.cap_disabled	= 'False'
			)
		BEGIN

			select	ca.ca_id		[Id],
					ca.ca_desc		[desc]
				from	dbo.tbCashAccountant		 ca		WITH (NOLOCK)
				INNER JOIN tbCashAccountantByProfile tcabp	WITH (NOLOCK)
					ON	tcabp.comp_id	= ca.comp_id AND
						tcabp.bra_id	= @bra_id AND
						tcabp.prof_id	= @prof_id AND
						tcabp.ca_id		= ca.ca_id
				WHERE	ca.comp_id = @comp_id	AND
						tcabp.cap_disabled = 'False'
				order by ca_desc


		END
	ELSE
		BEGIN

			select	ca_id		[Id],
					ca_desc		[desc]
				from	dbo.tbCashAccountant	WITH (NOLOCK)
				WHERE	comp_id = @comp_id
				and		(bra_id is Null or bra_id = @bra_id)
				order by ca_desc


		END




END


















GO


