	Drop table #tmpC6
	Drop table #tmpC7
	Drop table #tmpC8
	Drop table #tmpC9
	Drop table #tmpC10
	Drop table #tmpC11
	Drop table #tmpC12

	Drop table #tmpA
	Drop table #tmpB
	Drop table #tmpC
	Drop table #tmpD
	DROP TABLE #tmpBancos
--DROP TABLE #tmpBancos
*/
	-- --------------------------------------------------------------------




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	--Recupero la fecha de la sucursal.
	Declare @bra_processingDate Datetime
	Set @bra_processingDate = (Select bra_processingDate tb From tbBranch tb WITH (NOLOCK)
								Where tb.comp_id=@comp_id
								And tb.bra_id	= 1)





	---recuperar la moneda de la compañia
	Declare @comp_curr_id Int
	Select @comp_curr_id = @curr_id From tbCompany tc Where tc.comp_id = @comp_id






	--generar temporal con los dias a tener en cuenta
	Declare @current_date DATETIME, @last_date DATETIME

	Create table #tmpDays ( tmp_day Datetime )

	Set @current_date = @bra_processingDate
	SET @last_date = @bra_processingDate + @resumeday - 1
	SET @last_date = @last_date + 7 - DATEPART(weekday, @last_date)

	If (CAST(@last_date AS FLOAT) - CAST(@bra_processingDate AS FLOAT) + 1) > 0
	Begin

		Insert into #tmpDays (	tmp_day) Values (@current_date)
		While @current_date < @last_date
		Begin
			Set @current_date = @current_date + 1
			Insert into #tmpDays (tmp_day) Values (@current_date)
		end

	END






	--generar temporal con las semanas de los seis meses posteriores a la fecha de proceso + la cantidad de dias seleccionados
	Create table #tmpWeeks ( tmp_week VARCHAR(6) )
	DECLARE @Startdate DATETIME, @FinishDate DATETIME, @Date DATETIME, @dateant DATETIME, @weekant datetime

	SET @Startdate	= @last_date + 1
	SET @Date		= @Startdate

	SET @FinishDate = DATEADD(month, 6, @last_date) + '23:59:59.990'
	SET @FinishDate = @FinishDate + 7 - DATEPART(weekday, @FinishDate)
	--SELECT 'rango de fechas de 3: ', @Date, @FinishDate, convert(varchar,datepart(week, @Date))
	SET @dateant = @Date
	WHILE @Date < 	@FinishDate
	BEGIN

		IF convert(varchar,DATEPART(YEAR,@Date)) <> convert(varchar,DATEPART(YEAR,@dateant))
		BEGIN
			IF convert(varchar,datepart(week,@Date)) > 1
			BEGIN
				Insert into #tmpWeeks (tmp_week)
				Values (convert(varchar,DATEPART(YEAR,@Date)) + '01')

			END
		END
		SET @dateant = @Date

		Insert into #tmpWeeks (tmp_week)
		Values (convert(varchar,DATEPART(YEAR,@Date)) + convert(varchar,datepart(week,@Date)))

		SET @Date = DATEADD(WEEK, 1, @Date)
		--SELECT @date
	END
	--SELECT * FROM #tmpWeeks








	/**********************************************************************************************************/
	/********************************************** " A " *****************************************************/
	/**********************************************************************************************************/

	--Drop table #tmpA

	Create table #tmpA ( [order] VARCHAR collate database_default,
						 [date] DATETIME ,
						 [year] INT		 ,
						 [week] Int		 ,
						 [A1]	Decimal (19,2),
						 [A2]	Decimal (19,2),
						 [A3]	Decimal (19,2),
						 [A4]	Decimal (19,2),
						 [A5]	Decimal (19,2),
						 [A6]	Decimal (19,2),
						 [A7]	Decimal (19,2),
						 [A8]	Decimal (19,2),
						 [A9]	Decimal (19,2),
						 [A10]	Decimal (19,2),
						 [A11]	Decimal (19,2),
						 [A12]	Decimal(19,2))




	--/::::: "1" Cuentas Corrientes Deudoras  / Deuda Clientes :::::/--	OK
	Insert into #tmpA
	Select	'1'																	[order],
			@bra_processingDate													[date],
			0																	[year],
			0																	[week],

			CASE @AccountsPayable WHEN 'true' THEN	round(Isnull(Sum(dbo.fnGetExchange2(@comp_id,tct1.ct_abalance,tct1.ct_ACurrency,@curr_id,tct1.ct_ACurrency,tct1.curr_id_transaction, tct1.ct_ACurrencyExchange,'false')* vctfs.PlusOrMinus),0),2)
				ELSE								CONVERT(DECIMAL,0)
			END																	[A1],




			--::::: "2" Cuentas Documentos Deudoras :::::/--	OK
			(select	CASE @AccountsReceivable
						WHEN 'true' Then	round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tcp1.chp_total,tcp1.curr_id,@curr_id ,0,0,'False')),0),2)
						ELSE				CONVERT(DECIMAL,0)
					END

				 From	tbCheckPortfolio				tcp1	WITH (NOLOCK)
					INNER JOIN tbUsers4BranchFilter vubf2		WITH (NOLOCK)
						ON		vubf2.comp_id	= tcp1.comp_id
							AND	vubf2.bra_id	= tcp1.bra_id
							AND vubf2.[user_id] = @user_id

				 Where
							tcp1.comp_id				=	@comp_id
					 AND   (tcp1.bra_id					=	@bra_id OR @bra_id = -1)
					 And	tcp1.chp_isDocument			=	'True'
					 And    tcp1.chp_isCancelled		=	'False'
					 And    tcp1.chp_IsPayed			=	'False'
					 And    tcp1.chp_isAvailable		=	'True'
					 And	tcp1.chp_PayDate			< 	@bra_processingDate)		[A2],




			--/::::: "3" Cheques en Cartera :::::/--	OK
			(select round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tcp1.chp_total,tcp1.curr_id,@curr_id ,0,0,'False')),0),2)
				From	tbCheckPortfolio				tcp1	WITH (NOLOCK)
				INNER JOIN tbUsers4BranchFilter vubf2			WITH (NOLOCK)
					ON		vubf2.comp_id	= tcp1.comp_id
						AND	vubf2.bra_id	= tcp1.bra_id
						AND vubf2.[user_id] = @user_id

				Where
							tcp1.comp_id				=	@comp_id
					 AND  (tcp1.bra_id					=	@bra_id OR @bra_id = -1)
					 And	tcp1.chp_isDocument			=	'False'
					 And    tcp1.chp_isCancelled		=	'False'
					 And    tcp1.chp_IsPayed			=	'False'
					 And    tcp1.chp_isAvailable		=	'True'
					 And	tcp1.chp_PayDate			< 	@bra_processingDate)		[A3],




			--/::::: "4" Cupones a Acreditar :::::/--	ok
			(Select	round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tccm.ccm_Total,tccm.curr_id,@curr_id,0,0,'False')),0),2)
				 From	tbCreditCardMovements			tccm		WITH (NOLOCK)
				 INNER JOIN tbUsers4BranchFilter vubf2				WITH (NOLOCK)
					ON		vubf2.comp_id	= tccm.comp_id
						AND	vubf2.bra_id	= tccm.bra_id
						AND vubf2.[user_id] = @user_id

				  Where
							tccm.comp_id				=	@comp_id
					 AND   (tccm.bra_id					=	@bra_id OR @bra_id = -1)
					 And	tccm.ccm_isPayed			=	'False'
					 And	tccm.ccm_cardExpirationDate <	@bra_processingDate)		[A4],




			--/::::: "5" Otros Ingresos :::::/--		ok
			(Select round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tcfc1.cfo_debit,tcfc1.curr_id,@curr_id,0,0,'False')),0),2)
				 From	dbo.tbCashFlowOtherConcepts		tcfc1		WITH (NOLOCK)
					INNER JOIN tbUsers4BranchFilter vubf2			WITH (NOLOCK)
						ON		vubf2.comp_id	= tcfc1.comp_id
							AND	vubf2.bra_id	= tcfc1.bra_id
							AND vubf2.[user_id] = @user_id
				 Where
							tcfc1.comp_id				=	@comp_id
					 AND   (tcfc1.bra_id				=	@bra_id OR @bra_id = -1)
					 And	tcfc1.curr_id				=	@curr_id
					 And	tcfc1.cfo_date				<	@bra_processingDate)		[A5],




			--/::::: "6" Cheques a Acreditar :::::/--		OK
		(select round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tcp1.chp_total,tcp1.curr_id,@curr_id ,0,0,'False')),0),2)

			 From	tbCheckPortfolio				tcp1		WITH (NOLOCK)
			 INNER JOIN tbUsers4BranchFilter vubf2				WITH (NOLOCK)
				ON		vubf2.comp_id	= tcp1.comp_id
					AND	vubf2.bra_id	= tcp1.bra_id
					AND vubf2.[user_id] = @user_id
			 Where
						tcp1.comp_id				=	@comp_id
				 AND   (tcp1.bra_id					=	@bra_id OR @bra_id = -1)
				 And	tcp1.chp_isDocument			=	'False'
				 And    tcp1.chp_isCancelled		=	'False'
				 And    tcp1.chp_IsPayed			=	'False'
				 And    tcp1.chp_isAvailable		=	'False'
				 And	tcp1.chp_PayDate			< 	@bra_processingDate)		[A6],





			--/::::: "7" Disponibilidad Inicial :::::/ --		ok
			(Select round(Isnull(sum(dbo.fnGetExchange(@comp_id, tcm.cm_debit-tcm.cm_credit,tcm.curr_id,@curr_id,0/*@comp_curr_id*/,0/*tcm.cm_BranchCurrencyExchange*/,'False')),0),2)
				From	tbCashMovements					tcm		WITH (NOLOCK)
					INNER JOIN tbUsers4BranchFilter vubf2		WITH (NOLOCK)
						ON		vubf2.comp_id	= tcm.comp_id
							AND	vubf2.bra_id	= tcm.bra_id
							AND vubf2.[user_id] = @user_id

						Inner Join tbsysCurrency		tc		WITH (NOLOCK)
						On tc.curr_id = tcm.curr_id
				Where
							 tcm.comp_id				=	@comp_id
					And		(@bra_id					=	-1	or tcm.bra_id = @bra_id)
					AND		 tcm.svt_id					= 1	-- Solo Efectivo
					And		tcm.cm_cd					<	@bra_processingDate)		[A7],



			--/::::: "8" Cuentas Corrientes Acreedoras :::::/--		OK
			(Select round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tct1.ct_abalance,ct_ACurrency,@curr_id,0,0,'False')* vctfs.PlusOrMinus ),0),2)
				From	tbCommercialTransactions		tct1					WITH (NOLOCK)
					Inner Join vwCommercialTransactions_forPurchase		vctfs	WITH (NOLOCK)
						On	vctfs.comp_id			=	tct1.comp_id
						And vctfs.bra_id			=	tct1.bra_id
						And vctfs.ct_transaction	=	tct1.ct_transaction
					inner join tbUsers4BranchFilter vubf						WITH (NOLOCK)
						ON  vubf.comp_id    = tct1.comp_id
						AND vubf.bra_id     = tct1.bra_id
						AND vubf.[user_id]  = @user_id
					INNER JOIN tbBranch tb										WITH (NOLOCK)
						ON tb.comp_id = tct1.comp_id
							AND tb.bra_id = tct1.bra_id
				Where
							 tct1.comp_id				=	@comp_id
					And		(tct1.bra_id				=	@bra_id	OR @bra_id = -1)
					and tb.bra_PaymentSupp_Id			<> tct1.supp_id
					And		tct1.ct_date				<	@bra_processingDate)		[A8],




			--/::::: "9" Cuentas Documentos Acreedoras :::::/--	OK
			(Select	round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tec4.ec_Total,tec4.curr_id,@curr_id,0,0,'False')),0),2)

				From	tbEmmitedChecks					tec4		WITH (NOLOCK)
					inner join tbUsers4BranchFilter vubf			WITH (NOLOCK)
								ON  vubf.comp_id    = tec4.comp_id
								AND vubf.bra_id     = tec4.bra_id
								AND vubf.[user_id]  = @user_id
				Where
							tec4.comp_id				=	@comp_id
					And	   (tec4.bra_id					=	@bra_id OR @bra_id = -1)
					And		tec4.ec_isDocument			=	'True'
					AND		tec4.ec_isPaid				=   'False'
					AND		tec4.ec_isCancelled			=   'False'
					And		tec4.ec_PayDate				<	@bra_processingDate)		[A9],




			--/::::: "10" Otros Egresos :::::/--
			(Select	round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tcfc4.cfo_credit,tcfc4.curr_id,@curr_id,0,0,'False')),0),2)
				From	dbo.tbCashFlowOtherConcepts		tcfc4			WITH (NOLOCK)
					inner join tbUsers4BranchFilter vubf				WITH (NOLOCK)
								ON  vubf.comp_id    = tcfc4.comp_id
								AND vubf.bra_id     = tcfc4.bra_id
								AND vubf.[user_id]  = @user_id
				Where
							tcfc4.comp_id				=	@comp_id
					And	   (tcfc4.bra_id				=	@bra_id OR @bra_id = -1)
					And		tcfc4.cfo_date				< 	@bra_processingDate)		[A10],




			--/::::: "11" Cheques Emitidos :::::/--
			(Select	round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tec1.ec_Total,tec1.curr_id,@curr_id,0,0,'False')),0),2)
				From	tbEmmitedChecks					tec1			WITH (NOLOCK)
					inner join tbUsers4BranchFilter vubf				WITH (NOLOCK)
								ON  vubf.comp_id    = tec1.comp_id
								AND vubf.bra_id     = tec1.bra_id
								AND vubf.[user_id]  = @user_id
				Where
							tec1.comp_id				=	@comp_id
					And	   (tec1.bra_id					=	@bra_id OR @bra_id = -1)
					And		tec1.curr_id				=	@curr_id
					And		tec1.ec_isDocument			=	'False'
					AND		tec1.ec_isPaid				=   'False'
					AND		tec1.ec_isCancelled			=   'False'
					And		tec1.ec_PayDate				<	@bra_processingDate)		[A11],




			--Ordenes de compra
			CASE	@includePurchaseOrder WHEN 'false' THEN
				CONVERT(DECIMAL,0)
			ELSE
				(select round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tpod.pod_qty*tpod.pod_price,tpod.curr_id,@curr_id,0,0,'False')),0),2)

					From	tbPurchaseOrderHeader			tpoh			WITH (NOLOCK)
							inner join tbUsers4BranchFilter vubf			WITH (NOLOCK)
									ON  vubf.comp_id    = tpoh.comp_id
									AND vubf.bra_id     = tpoh.bra_id
									AND vubf.[user_id]  = @user_id
							INNER JOIN tbPurchaseOrderDetail	tpod		WITH (NOLOCK)
							ON  tpod.poh_id				=	tpoh.poh_id
							AND tpod.comp_id			=	tpoh.comp_id
							AND tpod.bra_id				=	tpoh.bra_id

					Where
								tpoh.comp_id				=	@comp_id
						And	   (tpoh.bra_id					=	@bra_id OR @bra_id = -1)
						AND     tpod.pod_isProcessed		=  'False'
						And		tpoh.poh_deliveryDate		< 	@bra_processingDate)
			END																	[A12]

	From	tbCommercialTransactions							tct1			WITH (NOLOCK)
			Inner Join vwCommercialTransactions_forSales		vctfs			WITH (NOLOCK)
				On  vctfs.comp_id			= tct1.comp_id
				--And vctfs.bra_id			= tct1.bra_id
				And vctfs.ct_transaction	= tct1.ct_transaction
				AND vctfs.sd_isInBalance	= 'True'

			INNER JOIN tbCustomer								tc				WITH (NOLOCK)
				ON	tc.comp_id								= tct1.comp_id
				AND tc.cust_id								= tct1.cust_id
				AND isnull(tc.cust_judMan,'False')			= 'False'
				AND IsNull(tc.cust_4InitialValues,'False')	= 'False'
			inner join tbUsers4BranchFilter vubf								WITH (NOLOCK)
				ON  vubf.comp_id    = tct1.comp_id
				AND vubf.bra_id     = tct1.bra_id
				AND vubf.[user_id]  = @user_id

	Where
				tct1.comp_id				= @comp_id
		And	   (tct1.bra_id					= @bra_id OR @bra_id = -1)
		And		tct1.ct_date				< @bra_processingDate

	--Select * From #tmpA

	--/* //////////////////////////////////////////////////////////////////////////////////////////////////////// */
	--/* ////////////////////////////////////////////////////////////////////////////////////////////////////////*/







	/***********************************************************************************************************/
	/********************************************** " B " ******************************************************/

	Declare @finish_processingDate Datetime
	Set @finish_processingDate = @last_date + '23:59:59.990'
	--Select @bra_processingDate, @finish_processingDate


	--/::::: "B1" Cuentas Corrientes Deudoras :::::/--		OK
	Select	CAST(FLOOR(CAST(tct2.ct_date AS FLOAT)) AS DATETIME) [date],
			CASE @AccountsPayable WHEN 'true' THEN	round(Isnull(Sum(dbo.fnGetExchange2(@comp_id,tct2.ct_abalance,tct2.ct_ACurrency,@curr_id,tct2.ct_ACurrency,tct2.curr_id_transaction, tct2.ct_ACurrencyExchange,'false')* CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END),0),2)
				ELSE								CONVERT(DECIMAL,0)
			END																[B1]

		Into	#tmpB1

		From	tbCommercialTransactions						tct2		WITH (NOLOCK)

				Inner Join vwCommercialTransactions_forSales	vctfs		WITH (NOLOCK)
					On  vctfs.comp_id			= tct2.comp_id
					--And vctfs.bra_id			= tct2.bra_id
					And vctfs.ct_transaction	= tct2.ct_transaction

				INNER JOIN tbCustomer							tc			WITH (NOLOCK)
					ON	tc.comp_id						= tct2.comp_id
					AND tc.cust_id						= tct2.cust_id
					AND isnull(tc.cust_judMan,'False')	= 'False'

				inner join tbUsers4BranchFilter vubf						WITH (NOLOCK)
					ON  vubf.comp_id    = tct2.comp_id
					AND vubf.bra_id     = tct2.bra_id
					AND vubf.[user_id]  = @user_id
		Where
				 tct2.comp_id				= @comp_id
			And	(tct2.bra_id				= @bra_id  OR @bra_id = -1)
			And	 tct2.[ct_date]				between @bra_processingDate And @finish_processingDate
		Group By CAST(FLOOR(CAST(tct2.ct_date AS FLOAT)) AS DATETIME)
	--SELECT * FROM #tmpB1




	--/::::: "B2" Cuentas Documentos Deudoras :::::/--		OK
	Select	CAST(FLOOR(CAST(tcp2.chp_PayDate AS FLOAT)) AS DATETIME) [date],
			-- round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tcp2.chp_total,tcp2.curr_id,@curr_id, @comp_curr_id, tcp2.chp_BranchCurrencyExchange,'False')),0),2) [B2]
			CASE @AccountsReceivable WHEN 'true' Then	round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tcp2.chp_total,tcp2.curr_id,@curr_id,0,0,'False')),0),2)
				ELSE									CONVERT(DECIMAL,0)
			END 	[B2]
		Into	#tmpB2

		From	tbCheckPortfolio        tcp2					WITH (NOLOCK)
			 INNER JOIN tbUsers4BranchFilter vubf2				WITH (NOLOCK)
					ON		vubf2.comp_id	= tcp2.comp_id
						AND	vubf2.bra_id	= tcp2.bra_id
						AND vubf2.[user_id] = @user_id
			Where
						tcp2.comp_id			= @comp_id
				And	   (tcp2.bra_id				= @bra_id  OR @bra_id = -1)
				And		tcp2.chp_isDocument     = 'True'
				And     tcp2.chp_isCancelled    = 'False'
				And     tcp2.chp_IsPayed        = 'False'
				And     tcp2.chp_isAvailable    = 'True'
				And		tcp2.chp_PayDate		between @bra_processingDate And @finish_processingDate

		Group By CAST(FLOOR(CAST(tcp2.chp_PayDate AS FLOAT)) AS DATETIME)
	--SELECT * FROM #tmpB2





	--/::::: "B3" Cheques en Cartera :::::/--		OK
	Select	CAST(FLOOR(CAST(tcp3.chp_PayDate AS FLOAT)) AS DATETIME) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id , tcp3.chp_total , tcp3.curr_id , @curr_id , @comp_curr_id, tcp3.chp_BranchCurrencyExchange,'False')),0),2) [B3]

		Into	#tmpB3

		From  tbCheckPortfolio        tcp3						WITH (NOLOCK)
			INNER JOIN tbUsers4BranchFilter vubf2				WITH (NOLOCK)
					ON		vubf2.comp_id	= tcp3.comp_id
						AND	vubf2.bra_id	= tcp3.bra_id
						AND vubf2.[user_id] = @user_id
		Where
					tcp3.comp_id			=  @comp_id
		And		   (tcp3.bra_id				=  @bra_id  OR @bra_id = -1)
		And			tcp3.chp_isDocument     =  'False'
		And         tcp3.chp_isCancelled    =  'False'
		And         tcp3.chp_IsPayed        =  'False'
		And         tcp3.chp_isAvailable    =  'True'
		And			tcp3.chp_PayDate between @bra_processingDate And @finish_processingDate

		Group By CAST(FLOOR(CAST(tcp3.chp_PayDate AS FLOAT)) AS DATETIME)
	--SELECT * FROM #tmpB3





	--/::::: "B4" Cupones a Acreditar :::::/--		OK
	Select	CAST(FLOOR(CAST(tccm.ccm_cardExpirationDate AS FLOAT)) AS DATETIME) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tccm.ccm_Total, tccm.curr_id , @curr_id , @comp_curr_id, tccm.ccm_BranchCurrencyExchange, 'False' )),0),2) [B4]
		Into	#tmpB4
		From	tbCreditCardMovements tccm					WITH (NOLOCK)
		INNER JOIN tbUsers4BranchFilter vubf2				WITH (NOLOCK)
			ON		vubf2.comp_id	= tccm.comp_id
				AND	vubf2.bra_id	= tccm.bra_id
				AND vubf2.[user_id] = @user_id
		Where
					tccm.comp_id			= @comp_id
			And	   (tccm.bra_id				= @bra_id  OR @bra_id = -1)
			And		tccm.ccm_isPayed		= 'False'
			And		tccm.ccm_cardExpirationDate  between @bra_processingDate And @finish_processingDate
		Group By CAST(FLOOR(CAST(tccm.ccm_cardExpirationDate AS FLOAT)) AS DATETIME)



	--/::::: "B5" Otros Ingresos :::::/--		OK
	Select	CAST(FLOOR(CAST(tcfc2.cfo_date AS FLOAT)) AS DATETIME) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tcfc2.cfo_debit, tcfc2.curr_id , @curr_id ,@comp_curr_id, 0 , 'False')),0),2) [B5]

		Into	#tmpB5
		From	dbo.tbCashFlowOtherConcepts tcfc2			WITH (NOLOCK)
			INNER JOIN tbUsers4BranchFilter vubf2			WITH (NOLOCK)
				ON		vubf2.comp_id	= tcfc2.comp_id
					AND	vubf2.bra_id	= tcfc2.bra_id
					AND vubf2.[user_id] = @user_id
		Where	tcfc2.comp_id	= @comp_id
		And	   (tcfc2.bra_id	= @bra_id  OR @bra_id = -1)
		And		tcfc2.cfo_date between @bra_processingDate And @finish_processingDate

		Group By CAST(FLOOR(CAST(tcfc2.cfo_date AS FLOAT)) AS DATETIME)
	--SELECT * FROM #tmpB5




	--/::::: "B6" Cheques a Acreditar :::::/--		ok
	Select	CAST(FLOOR(CAST(tcp8.chp_PayDate AS FLOAT)) AS DATETIME) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tcp8.chp_total, tcp8.curr_id , @curr_id , @comp_curr_id , Tcp8.chp_BranchCurrencyExchange, 'False')),0),2) [B6] --Isnull(Sum(dbo.fnGetExchange(tcp1.comp_id,tcp1.chp_total,tcp1.curr_id,@curr_id,0,0,'False')),0) [value]
		Into	#tmpB6
		From	tbCheckPortfolio        tcp8					WITH (NOLOCK)
				INNER JOIN tbUsers4BranchFilter vubf2			WITH (NOLOCK)
					ON		vubf2.comp_id	= tcp8.comp_id
						AND	vubf2.bra_id	= tcp8.bra_id
						AND vubf2.[user_id] = @user_id
		Where
						tcp8.comp_id			=    @comp_id
			And		   (tcp8.bra_id				=	 @bra_id  OR @bra_id = -1)
			And			tcp8.chp_isDocument     =    'False'
			And         tcp8.chp_isCancelled    =    'False'
			And         tcp8.chp_IsPayed        =    'False'
			And         tcp8.chp_isAvailable    =    'False'
			And			tcp8.chp_PayDate between @bra_processingDate And @finish_processingDate
		Group By CAST(FLOOR(CAST(tcp8.chp_PayDate AS FLOAT)) AS DATETIME)
	--SELECT * FROM #tmpB6




	--/::::: "B7" Disponibilidad Inicial :::::/--		ok
	Select CAST(FLOOR(CAST(tcm.cm_cd AS FLOAT)) AS DATETIME) [date],
		   round(Isnull(sum(dbo.fnGetExchange(@comp_id, tcm.cm_debit-tcm.cm_credit,tcm.curr_id,@curr_id,0/*@comp_curr_id*/,0/*tcm.cm_BranchCurrencyExchange*/,'False')),0),2)      [B7]
		into	#tmpB7
		From	tbCashMovements tcm								WITH (NOLOCK)
				INNER JOIN tbUsers4BranchFilter vubf2			WITH (NOLOCK)
					ON		vubf2.comp_id	= tcm.comp_id
						AND	vubf2.bra_id	= tcm.bra_id
						AND vubf2.[user_id] = @user_id
				Inner Join tbsysCurrency tc						WITH (NOLOCK)
				On tc.curr_id = tcm.curr_id
		Where		tcm.comp_id					= @comp_id
			And	   (tcm.bra_id					= @bra_id  OR @bra_id = -1)
			AND		tcm.svt_id					= 1	-- Solo Efectivo
			And		tcm.cm_cd between @bra_processingDate And @finish_processingDate
		Group By CAST(FLOOR(CAST(tcm.cm_cd AS FLOAT)) AS DATETIME) --,tcm.curr_id
	--Select * From [#tmpB7]





	--/::::: "B8" Cuentas Corrientes Acreedoras :::::/--		ok
	Select  CAST(FLOOR(CAST(tct1.ct_date AS FLOAT)) AS DATETIME) [date],
			round(Isnull(Sum(dbo.fnGetExchange(@comp_id ,tct1.ct_abalance,tct1.ct_ACurrency,@curr_id,0,0,'False')* CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END),0),2) [B8]
		Into	#tmpB8
		From	tbCommercialTransactions					tct1						WITH (NOLOCK)
				Inner Join vwCommercialTransactions_forPurchase	vctfs					WITH (NOLOCK)
					On vctfs.comp_id						= tct1.comp_id
					And vctfs.bra_id						= tct1.bra_id
					And vctfs.ct_transaction				= tct1.ct_transaction

				inner join tbUsers4BranchFilter vubf									WITH (NOLOCK)
					ON  vubf.comp_id    = tct1.comp_id
					AND vubf.bra_id     = tct1.bra_id
					AND vubf.[user_id]  = @user_id

				INNER JOIN tbBranch tb													WITH (NOLOCK)
					ON tb.comp_id = tct1.comp_id
						AND tb.bra_id = tct1.bra_id
		Where		tct1.comp_id				= @comp_id
			And	   (tct1.bra_id					= @bra_id   OR @bra_id = -1)
			and		tb.bra_PaymentSupp_Id <> tct1.supp_id
			And		tct1.ct_date between @bra_processingDate And @finish_processingDate
		Group By CAST(FLOOR(CAST(tct1.ct_date AS FLOAT)) AS DATETIME)





	--/::::: "B9" Cuentas Documentos Acreedoras :::::/--		OK
	Select	CAST(FLOOR(CAST(tec5.ec_PayDate AS FLOAT)) AS DATETIME) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tec5.ec_Total,tec5.curr_id , @curr_id, @comp_curr_id,tec5.ec_exchangeToBranchCurrency, 'False' )),0),2)	[B9]
		Into	#tmpB9
		From	tbEmmitedChecks		tec5									WITH (NOLOCK)
		inner join tbUsers4BranchFilter vubf								WITH (NOLOCK)
				ON  vubf.comp_id = tec5.comp_id
				AND vubf.bra_id     = tec5.bra_id
				AND vubf.[user_id]  = @user_id
		Where		tec5.comp_id			=	@comp_id
			And	   (tec5.bra_id				=   @bra_id  OR @bra_id = -1)
			And		tec5.ec_isDocument		=	'True'
			AND		tec5.ec_isPaid			= 'False'
			AND		tec5.ec_isCancelled		= 'False'
			And		tec5.ec_PayDate between @bra_processingDate And @finish_processingDate
		Group By CAST(FLOOR(CAST(tec5.ec_PayDate AS FLOAT)) AS DATETIME)
	--SELECT * FROM #tmpB9




	--/::::: "B10" Otros Egresos :::::/--		OK
	Select  CAST(FLOOR(CAST(tcfc5.cfo_date AS FLOAT)) AS DATETIME) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tcfc5.cfo_credit,tcfc5.curr_id , @curr_id , @comp_curr_id ,0,'False')),0),2)[B10]
		Into	#tmpB10
		From	dbo.tbCashFlowOtherConcepts tcfc5			WITH (NOLOCK)
			inner join tbUsers4BranchFilter vubf			WITH (NOLOCK)
				ON  vubf.comp_id    = tcfc5.comp_id
				AND vubf.bra_id     = tcfc5.bra_id
				AND vubf.[user_id]  = @user_id
		Where		tcfc5.comp_id		= @comp_id
			And	   (tcfc5.bra_id		= @bra_id  OR @bra_id = -1)
			And		tcfc5.cfo_date  between @bra_processingDate And @finish_processingDate
		Group By CAST(FLOOR(CAST(tcfc5.cfo_date AS FLOAT)) AS DATETIME)
	--SELECT * FROM #tmpB10





	--/::::: "B11" Cheques Emitidos :::::/--   ok
	Select	CAST(FLOOR(CAST(tec2.ec_PayDate AS FLOAT)) AS DATETIME) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tec2.ec_Total,tec2.curr_id, @curr_id, @comp_curr_id, tec2.ec_exchangeToBranchCurrency,'False' )),0),2) [B11]
		Into	#tmpB11
		From	tbEmmitedChecks tec2						WITH (NOLOCK)
			inner join tbUsers4BranchFilter vubf			WITH (NOLOCK)
				ON  vubf.comp_id    = tec2.comp_id
				AND vubf.bra_id     = tec2.bra_id
				AND vubf.[user_id]  = @user_id
		Where		tec2.comp_id		= @comp_id
			AND		tec2.ec_isPaid				=   'False'
			AND		tec2.ec_isCancelled			=   'False'
			And	   (tec2.bra_id			= @bra_id OR @bra_id = -1)
			And		tec2.ec_isDocument	= 'False'
			And		tec2.ec_PayDate between @bra_processingDate And @finish_processingDate
		Group By CAST(FLOOR(CAST(tec2.ec_PayDate AS FLOAT)) AS DATETIME)


	--/::::: "B12" Ordenes de Compra :::::/--   ok
	Select	CAST(FLOOR(CAST(tpoh.poh_cd  AS FLOAT)) AS DATETIME) [date],
			CASE @includePurchaseOrder WHEN 'FALSE' THEN CONVERT(DECIMAL,0)
			ELSE								 		 round(Isnull(Sum(dbo.fnGetExchange(@comp_id ,tpod.pod_qty*tpod.pod_price,tpod.curr_id, @curr_id, @comp_curr_id, tpod.curr_id,'False' )),0),2)
			END [B12]
		Into	#tmpB12
		FROM  tbPurchaseOrderHeader tpoh				WITH (NOLOCK)
		inner join tbUsers4BranchFilter vubf			WITH (NOLOCK)
			ON  vubf.comp_id    = tpoh.comp_id
			AND vubf.bra_id     = tpoh.bra_id
			AND vubf.[user_id]  = @user_id
		INNER JOIN tbPurchaseOrderDetail tpod			WITH (NOLOCK)
			ON  tpod.poh_id  = tpoh.poh_id
			AND tpod.comp_id = tpoh.comp_id
			AND tpod.bra_id  = tpoh.bra_id
		Where		tpoh.comp_id		= @comp_id
			And		tpoh.bra_id			= @bra_id
			AND     tpod.pod_isProcessed= 'False'
			And		tpoh.poh_cd between @bra_processingDate And @finish_processingDate
		Group By CAST(FLOOR(CAST(tpoh.poh_cd AS FLOAT)) AS DATETIME)



	/***********************************************************************************************************/
	/********************************************** " C " ******************************************************/
	/***********************************************************************************************************/

	--select @Startdate, @FinishDate
	--/::::: "C1" Cuentas Corrientes Deudoras :::::/--		ok
	Select	convert(VARCHAR(4),DATEPART(YEAR,tct2.ct_date)) + convert(VARCHAR(2),datepart(week, tct2.ct_date)) [date],
			CASE @AccountsPayable WHEN 'true' THEN
				round(Isnull(Sum(dbo.fnGetExchange2(@comp_id,tct2.ct_abalance,tct2.ct_ACurrency,@curr_id,tct2.ct_ACurrency,tct2.curr_id_transaction, tct2.ct_ACurrencyExchange,'false')*  vctfs.PlusOrMinus ),0),2)
			ELSE CONVERT(DECIMAL,0)
			END [C1]
		Into	#tmpC1
		From	tbCommercialTransactions						tct2		WITH (NOLOCK)
				Inner Join vwCommercialTransactions_forSales	vctfs		WITH (NOLOCK)
					On  vctfs.comp_id			= tct2.comp_id
					--And vctfs.bra_id			= tct2.bra_id
					And vctfs.ct_transaction	= tct2.ct_transaction
				INNER JOIN tbCustomer							tc			WITH (NOLOCK)
					ON	tc.comp_id						= tct2.comp_id
					AND tc.cust_id						= tct2.cust_id
					AND isnull(tc.cust_judMan,'False')	= 'False'
				inner join tbUsers4BranchFilter vubf						WITH (NOLOCK)
					ON  vubf.comp_id    = tct2.comp_id
					AND vubf.bra_id     = tct2.bra_id
					AND vubf.[user_id]  = @user_id
		Where		tct2.comp_id				= @comp_id
			And	   (tct2.bra_id					= @bra_id OR @bra_id = -1)
			And		tct2.[ct_date]				Between @Startdate And @FinishDate
		Group By convert(VARCHAR(4),DATEPART(YEAR,tct2.ct_date)) + convert(VARCHAR(2),datepart(week, tct2.ct_date))
	--SELECT * FROM #tmpC1








	--/::::: "C2" Cuentas Documentos Deudoras :::::/-- OK
	Select	convert(varchar,DATEPART(YEAR,tcp2.chp_PayDate)) + convert(varchar,datepart(week, tcp2.chp_PayDate)) [date],
			CASE @AccountsReceivable WHEN 'true' Then	round(Isnull(Sum(dbo.fnGetExchange( @comp_id , tcp2.chp_total ,tcp2.curr_id,@curr_id , @comp_curr_id ,tcp2.chp_BranchCurrencyExchange  ,'False')),0),2)
				ELSE									CONVERT(DECIMAL,0)
			END 	[C2]
		Into	#tmpC2
		From	tbCheckPortfolio        tcp2								WITH (NOLOCK)
			INNER JOIN tbUsers4BranchFilter vubf2							WITH (NOLOCK)
								ON		vubf2.comp_id	= tcp2.comp_id
									AND	vubf2.bra_id	= tcp2.bra_id
									AND vubf2.[user_id] = @user_id
		Where		tcp2.comp_id			= @comp_id
			And	   (tcp2.bra_id				= @bra_id OR @bra_id = -1)
			And		tcp2.chp_isDocument     = 'True'
			And     tcp2.chp_isCancelled    = 'False'
			And     tcp2.chp_IsPayed        = 'False'
			And     tcp2.chp_isAvailable    = 'True'
			And		tcp2.chp_PayDate		Between @Startdate And @FinishDate
		Group By convert(varchar,DATEPART(YEAR,tcp2.chp_PayDate)) + convert(varchar,datepart(week,tcp2.chp_PayDate))
	--SELECT * FROM #tmpC2




	--/::::: "C3" Cheques en Cartera :::::/--		ok
	Select	convert(varchar,DATEPART(YEAR,tcp3.chp_PayDate)) + convert(varchar,datepart(week, tcp3.chp_PayDate)) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id , tcp3.chp_total ,tcp3.curr_id , @curr_id , @comp_curr_id ,tcp3.chp_BranchCurrencyExchange  ,'False')),0),2) [C3]
		Into	#tmpC3
		From  tbCheckPortfolio        tcp3										WITH (NOLOCK)
			INNER JOIN tbUsers4BranchFilter vubf2								WITH (NOLOCK)
				ON		vubf2.comp_id	= tcp3.comp_id
					AND	vubf2.bra_id	= tcp3.bra_id
					AND vubf2.[user_id] = @user_id
		Where		tcp3.comp_id			=  @comp_id
			And		   (tcp3.bra_id				=  @bra_id OR @bra_id = -1)
			And			tcp3.chp_isDocument     =  'False'
			And         tcp3.chp_isCancelled    =  'False'
			And         tcp3.chp_IsPayed        =  'False'
			And         tcp3.chp_isAvailable    =  'True'
			And			tcp3.chp_PayDate Between @Startdate And @FinishDate
		Group By convert(varchar,DATEPART(YEAR,tcp3.chp_PayDate)) + convert(varchar,datepart(week,tcp3.chp_PayDate))
	--SELECT * FROM #tmpC3





	--/::::: "C4" Cupones a Acreditar :::::/--
	Select	convert(varchar,DATEPART(YEAR,tccm.ccm_cardExpirationDate)) + convert(varchar,datepart(week, tccm.ccm_cardExpirationDate)) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id , tccm.ccm_Total, tccm.curr_id, @curr_id , @comp_curr_id , tccm.ccm_BranchCurrencyExchange,'False' )),0 ),2) [C4]
		Into	#tmpC4
		From	tbCreditCardMovements tccm											WITH (NOLOCK)
		INNER JOIN tbUsers4BranchFilter vubf2										WITH (NOLOCK)
			ON		vubf2.comp_id	= tccm.comp_id
				AND	vubf2.bra_id	= tccm.bra_id
				AND vubf2.[user_id] = @user_id
		Where		tccm.comp_id			= @comp_id
			And	   (tccm.bra_id				= @bra_id OR @bra_id = -1)
			And		tccm.ccm_isPayed		= 'False'
			And		tccm.ccm_cardExpirationDate  Between @Startdate And @FinishDate
		Group By convert(varchar,DATEPART(YEAR,tccm.ccm_cardExpirationDate)) + convert(varchar,datepart(week,tccm.ccm_cardExpirationDate))
	--SELECT * FROM #tmpC4




	--/::::: "C5" Otros Ingresos :::::/--		ok
	Select	convert(varchar,DATEPART(YEAR,tcfc2.cfo_date)) + convert(varchar,datepart(week, tcfc2.cfo_date)) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id , tcfc2.cfo_debit,tcfc2.curr_id, @curr_id, @comp_curr_id, 0 , 'False' )),0),2) [C5]
		Into	#tmpC5
		From	dbo.tbCashFlowOtherConcepts tcfc2				WITH (NOLOCK)
			INNER JOIN tbUsers4BranchFilter vubf2				WITH (NOLOCK)
				ON		vubf2.comp_id	= tcfc2.comp_id
					AND	vubf2.bra_id	= tcfc2.bra_id
					AND vubf2.[user_id] = @user_id
		Where		tcfc2.comp_id	= @comp_id
			And	   (tcfc2.bra_id	= @bra_id OR @bra_id = -1)
			--And		tcfc2.curr_id	= @curr_id
			And		tcfc2.cfo_date Between @Startdate And @FinishDate
		Group By convert(varchar,DATEPART(YEAR,tcfc2.cfo_date)) + convert(varchar,datepart(week,tcfc2.cfo_date))
	--SELECT * FROM #tmpC5




	--/::::: "C6" Cheques a Acreditar :::::/--	ok
	Select	convert(varchar,DATEPART(YEAR,tcp8.chp_PayDate)) + convert(varchar,datepart(week, tcp8.chp_PayDate)) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tcp8.chp_total, tcp8.curr_id, @curr_id, @comp_curr_id,tcp8.chp_BranchCurrencyExchange,'False')),0),2) [C6]
			--Isnull(Sum(dbo.fnGetExchange(tcp1.comp_id,tcp1.chp_total,tcp1.curr_id,@curr_id,0,0,'False')),0) [value]
		Into	#tmpC6
		From	tbCheckPortfolio        tcp8					WITH (NOLOCK)
			INNER JOIN tbUsers4BranchFilter vubf2				WITH (NOLOCK)
				ON		vubf2.comp_id	= tcp8.comp_id
					AND	vubf2.bra_id	= tcp8.bra_id
					AND vubf2.[user_id] = @user_id
		Where			tcp8.comp_id			=    @comp_id
			And		   (tcp8.bra_id				=	 @bra_id OR @bra_id = -1)
			And			tcp8.chp_isDocument     =    'False'
			And         tcp8.chp_isCancelled    =    'False'
			And         tcp8.chp_IsPayed        =    'False'
			And         tcp8.chp_isAvailable    =    'false'
			And			tcp8.chp_PayDate Between @Startdate And @FinishDate
		Group By convert(varchar,DATEPART(YEAR,tcp8.chp_PayDate)) + convert(varchar,datepart(week,tcp8.chp_PayDate))
	--SELECT * FROM #tmpC6


	--/::::: "C7" Disponibilidad Inicial :::::/ --		ok
	Select convert(varchar,DATEPART(YEAR,tcm.cm_cd)) + convert(varchar,datepart(week, tcm.cm_cd)) [date],
		  round(Isnull(sum(dbo.fnGetExchange(@comp_id, tcm.cm_debit-tcm.cm_credit,tcm.curr_id,@curr_id,0/*@comp_curr_id*/,0/*tcm.cm_BranchCurrencyExchange*/,'False')),0),2)      [C7]
		Into	#tmpC7
		From tbCashMovements tcm						WITH (NOLOCK)
		INNER JOIN tbUsers4BranchFilter vubf2			WITH (NOLOCK)
			ON		vubf2.comp_id	= tcm.comp_id
				AND	vubf2.bra_id	= tcm.bra_id
				AND vubf2.[user_id] = @user_id
		Inner Join tbsysCurrency tc
			On tc.curr_id = tcm.curr_id
		Where
						tcm.comp_id			   =    @comp_id
			And		   (tcm.bra_id			   =	 @bra_id OR @bra_id = -1)
			AND			tcm.svt_id			   = 1	-- Solo Efectivo
			And			tcm.cm_cd Between @Startdate And @FinishDate
		--Group By tcm.cm_cd,tcm.curr_id
		Group By  convert(varchar,DATEPART(YEAR,tcm.cm_cd)) + convert(varchar,datepart(week,tcm.cm_cd))	--,tcm.curr_id
	--SELECT * FROM #tmpC7



	--/::::: "C8" Cuentas Corrientes Acreedoras :::::/--		ok
	Select  convert(varchar,DATEPART(YEAR,tct1.ct_date)) + convert(varchar,datepart(week, tct1.ct_date)) [date],
			round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tct1.ct_abalance,tct1.ct_ACurrency,@curr_id,0,0,'False')* vctfs.PlusOrMinus ),0),2) [C8]
	Into	#tmpC8
	From	tbCommercialTransactions					tct1				WITH (NOLOCK)
		Inner Join vwCommercialTransactions_forPurchase	vctfs				WITH (NOLOCK)
			On vctfs.comp_id						= tct1.comp_id
			And vctfs.bra_id						= tct1.bra_id
			And vctfs.ct_transaction				= tct1.ct_transaction
		inner join tbUsers4BranchFilter vubf								WITH (NOLOCK)
			ON  vubf.comp_id    = tct1.comp_id
			AND vubf.bra_id     = tct1.bra_id
			AND vubf.[user_id]  = @user_id
		INNER JOIN tbBranch tb												WITH (NOLOCK)
			ON tb.comp_id = tct1.comp_id
				AND tb.bra_id = tct1.bra_id
	Where		tct1.comp_id					= @comp_id
		And	   (tct1.bra_id						= @bra_id OR @bra_id = -1)
		and		tb.bra_PaymentSupp_Id			<> tct1.supp_id
		And		tct1.ct_date					Between @Startdate And @FinishDate
	Group By convert(varchar,DATEPART(YEAR,tct1.ct_date)) + convert(varchar,datepart(week,tct1.ct_date))
	--SELECT * FROM #tmpC8






	--/::::: "C9" Cuentas Documentos Acreedoras :::::/--	ok
	Select	convert(varchar,DATEPART(YEAR,tec5.ec_PayDate)) + convert(varchar,datepart(week, tec5.ec_PayDate)) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tec5.ec_Total, tec5.curr_id, @curr_id, @comp_curr_id,tec5.ec_exchangeToBranchCurrency, 'False' )),0),2)	[C9]
		Into	#tmpC9
		From	tbEmmitedChecks		tec5						WITH (NOLOCK)
			inner join tbUsers4BranchFilter vubf				WITH (NOLOCK)
				ON  vubf.comp_id    = tec5.comp_id
				AND vubf.bra_id     = tec5.bra_id
				AND vubf.[user_id]  = @user_id
		Where		tec5.comp_id			=	@comp_id
			And	   (tec5.bra_id				=   @bra_id OR @bra_id = -1)
			AND		tec5.ec_isPaid			= 'False'
			AND		tec5.ec_isCancelled		= 'False'
			And		tec5.ec_isDocument		= 'True'
			And		tec5.ec_PayDate Between @Startdate And @FinishDate
		Group By convert(varchar,DATEPART(YEAR,tec5.ec_PayDate)) + convert(varchar,datepart(week,tec5.ec_PayDate))
	--SELECT * FROM #tmpC9




	--/::::: "C10" Otros Egresos :::::/--		ok
	Select   convert(varchar,DATEPART(YEAR,tcfc5.cfo_date)) + convert(varchar,datepart(week, tcfc5.cfo_date)) [date],
			 round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tcfc5.cfo_credit, tcfc5.curr_id, @curr_id, @comp_curr_id, 0, 'False')),0),2) [C10]
		Into	#tmpC10
		From  dbo.tbCashFlowOtherConcepts tcfc5			WITH (NOLOCK)
			inner join tbUsers4BranchFilter vubf		WITH (NOLOCK)
				ON  vubf.comp_id    = tcfc5.comp_id
				AND vubf.bra_id     = tcfc5.bra_id
				AND vubf.[user_id]  = @user_id
		Where	  tcfc5.comp_id		= @comp_id
			And	 (tcfc5.bra_id		= @bra_id OR @bra_id = -1)
			And	  tcfc5.cfo_date  Between @Startdate And @FinishDate
		Group By convert(varchar,DATEPART(YEAR,tcfc5.cfo_date)) + convert(varchar,datepart(week,tcfc5.cfo_date))
	--SELECT * FROM #tmpC10




	--/::::: "C11" Cheques Emitidos :::::/--		ok
	Select	convert(varchar,DATEPART(YEAR,tec2.ec_PayDate)) + convert(varchar,datepart(week, tec2.ec_PayDate)) [date],
			round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tec2.ec_Total, tec2.curr_id , @curr_id, @comp_curr_id, tec2.ec_exchangeToBranchCurrency, 'False')),0),2) [C11]
		Into	#tmpC11
		From  tbEmmitedChecks tec2						WITH (NOLOCK)
		inner join tbUsers4BranchFilter vubf			WITH (NOLOCK)
			ON  vubf.comp_id    = tec2.comp_id
			AND vubf.bra_id     = tec2.bra_id
			AND vubf.[user_id]  = @user_id
		Where	  tec2.comp_id			= @comp_id
			And	 (tec2.bra_id			= @bra_id OR @bra_id = -1)
			AND	  tec2.ec_isPaid		=   'False'
			AND	  tec2.ec_isCancelled	=   'False'
			And   tec2.ec_isDocument	= 'False'
			And   tec2.ec_PayDate Between @Startdate And @FinishDate
		Group By convert(varchar,DATEPART(YEAR,tec2.ec_PayDate)) + convert(varchar,datepart(week,tec2.ec_PayDate))
	--SELECT * FROM #tmpC11


	---/::::: "C12" Orden de compra ::::/--		ok
	Select	convert(varchar,DATEPART(YEAR,tpoh.poh_deliveryDate)) + convert(varchar,datepart(week, tpoh.poh_deliveryDate)) [date],
			CASE @AccountsPayable WHEN 'false' THEN CONVERT(DECIMAL,0)
				ELSE								round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tpod.pod_qty*tpod.pod_price, tpod.curr_id , @curr_id, @comp_curr_id, tpod.curr_id, 'False')),0),2)
			End [C12]
		Into	#tmpC12
			From  tbPurchaseOrderHeader tpoh				WITH (NOLOCK)
			inner join tbUsers4BranchFilter vubf			WITH (NOLOCK)
				ON  vubf.comp_id    = tpoh.comp_id
				AND vubf.bra_id     = tpoh.bra_id
				AND vubf.[user_id]  = @user_id
			 INNER JOIN tbPurchaseOrderDetail tpod			WITH (NOLOCK)
				ON    tpod.poh_id = tpoh.poh_id
				AND tpod.comp_id = tpoh.comp_id
				AND tpod.bra_id = tpoh.bra_id
		Where		tpoh.comp_id		= @comp_id
			And	   (tpoh.bra_id			= @bra_id OR @bra_id = -1)
			AND     tpod.pod_isProcessed= 'False'
			And   tpoh.poh_deliveryDate Between @Startdate And @FinishDate
		Group By convert(varchar,DATEPART(YEAR,tpoh.poh_deliveryDate)) + convert(varchar,datepart(week,tpoh.poh_deliveryDate))








	/**********************************************************************************************/
	/***************************************** " D " **********************************************/
	/**********************************************************************************************/


	--/::::: "D1" Cuentas Corrientes Deudoras :::::/--		ok
	Select	'4' collate database_default [order], @FinishDate [date], 0 [year], 0 [week],
			CASE @AccountsPayable WHEN 'true' THEN 	round(Isnull(Sum(dbo.fnGetExchange2(@comp_id,tct2.ct_abalance,tct2.curr_id_transaction,@curr_id,tct2.ct_ACurrency,tct2.curr_id_transaction, tct2.ct_ACurrencyExchange,'false')*  vctfs.PlusOrMinus ),0),2)
			ELSE									CONVERT(DECIMAL,0)
			END [D1],

			--/::::: "D2" Cuentas Documentos Deudoras :::::/--	OK
			(Select
				CASE @AccountsReceivable WHEN 'true' Then
					round(Isnull(Sum(dbo.fnGetExchange( @comp_id, tcp2.chp_total , tcp2.curr_id , @curr_id , @comp_curr_id , tcp2.chp_BranchCurrencyExchange ,'False')),0),2)
					ELSE CONVERT(DECIMAL,0)
				END 	[D2]
				From	tbCheckPortfolio        tcp2						WITH (NOLOCK)
					INNER JOIN tbUsers4BranchFilter vubf2					WITH (NOLOCK)
						ON		vubf2.comp_id	= tcp2.comp_id
							AND	vubf2.bra_id	= tcp2.bra_id
							AND vubf2.[user_id] = @user_id
				Where		tcp2.comp_id			= @comp_id
					And	   (tcp2.bra_id				= @bra_id OR @bra_id = -1)
					And		tcp2.chp_isDocument     = 'True'
					And     tcp2.chp_isCancelled    = 'False'
					And     tcp2.chp_IsPayed        = 'False'
					And     tcp2.chp_isAvailable    = 'True'
    				And		tcp2.chp_PayDate		> @FinishDate

				) [D2],



			--/::::: "D3" Cheuqes en Cartera :::::/--	OK
			(Select	round(Isnull(Sum(dbo.fnGetExchange( @comp_id,tcp3.chp_total,tcp3.curr_id,@curr_id,@comp_curr_id,tcp3.chp_BranchCurrencyExchange,'False')),0) ,2)
			 From  tbCheckPortfolio        tcp3					WITH (NOLOCK)
				INNER JOIN tbUsers4BranchFilter vubf2			WITH (NOLOCK)
					ON		vubf2.comp_id	= tcp3.comp_id
						AND	vubf2.bra_id	= tcp3.bra_id
						AND vubf2.[user_id] = @user_id
			 Where		tcp3.comp_id			=  @comp_id
				And		   (tcp3.bra_id				=  @bra_id OR @bra_id = -1)
				And			tcp3.chp_isDocument     =  'False'
				And         tcp3.chp_isCancelled    =  'False'
				And  tcp3.chp_IsPayed        =  'False'
				And         tcp3.chp_isAvailable    =  'True'
				And			tcp3.chp_PayDate		>  @FinishDate
				) [D3],



			--/::::: "D4" Cupones a Acreditar :::::/--
			(Select	round(Isnull(Sum(dbo.fnGetExchange( @comp_id, tccm.ccm_Total , tccm.curr_id , @curr_id , @comp_curr_id , tccm.ccm_BranchCurrencyExchange,'False')),0) ,2)
				 From	tbCreditCardMovements tccm				WITH (NOLOCK)
					INNER JOIN tbUsers4BranchFilter vubf2		WITH (NOLOCK)
						ON		vubf2.comp_id	= tccm.comp_id
							AND	vubf2.bra_id	= tccm.bra_id
							AND vubf2.[user_id] = @user_id
					Where		tccm.comp_id			= @comp_id
						And	   (tccm.bra_id				= @bra_id OR @bra_id = -1)
						And		tccm.ccm_isPayed		= 'False'
						And		tccm.ccm_cardExpirationDate  > @FinishDate
			) [D4],



			--/::::: "D5" Otros Ingresos :::::/--		ok
			(Select	round(Isnull(Sum(dbo.fnGetExchange( @comp_id, tcfc2.cfo_debit ,tcfc2.curr_id , @curr_id , @comp_curr_id , 0 ,'False')),0),2)
				From	dbo.tbCashFlowOtherConcepts tcfc2				WITH (NOLOCK)
					INNER JOIN tbUsers4BranchFilter vubf2				WITH (NOLOCK)
					ON		vubf2.comp_id	= tcfc2.comp_id
						AND	vubf2.bra_id	= tcfc2.bra_id
						AND vubf2.[user_id] = @user_id
				Where		tcfc2.comp_id	= @comp_id
					And	   (tcfc2.bra_id	= @bra_id OR @bra_id = -1)
					And		tcfc2.cfo_date > @FinishDate
			) [D5],


			--/::::: "D6" Cheques a Acreditar :::::/--			OK
			(Select	round(Isnull(Sum(dbo.fnGetExchange( @comp_id, tcp8.chp_total ,tcp8.curr_id , @curr_id , @comp_curr_id , tcp8.chp_BranchCurrencyExchange ,'False')),0) ,2)
				 From	tbCheckPortfolio        tcp8				WITH (NOLOCK)
					INNER JOIN tbUsers4BranchFilter vubf2			WITH (NOLOCK)
					ON		vubf2.comp_id	= tcp8.comp_id
						AND	vubf2.bra_id	= tcp8.bra_id
						AND vubf2.[user_id] = @user_id
				 Where			tcp8.comp_id			=    @comp_id
					And		   (tcp8.bra_id				=	 @bra_id OR @bra_id = -1)
					And			tcp8.chp_isDocument     =    'False'
					And         tcp8.chp_isCancelled    = 'False'
					And         tcp8.chp_IsPayed        =    'False'
					And         tcp8.chp_isAvailable    =    'false'
					And			tcp8.chp_PayDate > @FinishDate
				) [D6],



			--/::::: "D7" Disponibilidad Inicial :::::/--
			(Select --isnull(dbo.fnGetExchange(@comp_id,Sum(tcm.cm_debit)-Sum(tcm.cm_credit),tcm.curr_id,@curr_id,0,1,'False') ,0)
			 round(Isnull(sum(dbo.fnGetExchange(@comp_id, tcm.cm_debit-tcm.cm_credit,tcm.curr_id,@curr_id,0/*@comp_curr_id*/,0/*tcm.cm_BranchCurrencyExchange*/,'False')),0),2)
				 From tbCashMovements tcm					WITH (NOLOCK)
 				 INNER JOIN tbUsers4BranchFilter vubf2		WITH (NOLOCK)
					ON		vubf2.comp_id	= tcm.comp_id
						AND	vubf2.bra_id	= tcm.bra_id
						AND vubf2.[user_id] = @user_id
				 Inner Join tbsysCurrency tc
					On tc.curr_id = tcm.curr_id
				 Where		tcm.comp_id			=    @comp_id
					 AND   (tcm.bra_id			=	 @bra_id	OR @bra_id = -1)
					 AND	tcm.svt_id			= 1	-- Solo Efectivo
					 And	tcm.cm_cd > @FinishDate			) [D7],



			--/::::: "D8" Cuentas Corrientes Acreedoras :::::/--
			(Select round(isnull(sum(dbo.fnGetExchange(@comp_id,tct1.ct_abalance,tct1.ct_ACurrency,@curr_id,0,0,'False')* CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END),0),2)
				From	tbCommercialTransactions						tct1		WITH (NOLOCK)
				Inner Join vwCommercialTransactions_forPurchase			vctfs		WITH (NOLOCK)
					On		vctfs.comp_id				= tct1.comp_id
					And		vctfs.bra_id				= tct1.bra_id
					And		vctfs.ct_transaction		= tct1.ct_transaction
				inner join tbUsers4BranchFilter vubf								WITH (NOLOCK)
					ON  vubf.comp_id    = tct1.comp_id
					AND vubf.bra_id     = tct1.bra_id
					AND vubf.[user_id]  = @user_id
				INNER JOIN tbBranch tb												WITH (NOLOCK)
					ON tb.comp_id = tct1.comp_id
						AND tb.bra_id = tct1.bra_id
				Where		tct1.comp_id				= @comp_id
					And	   (tct1.bra_id					= @bra_id OR @bra_id = -1)
					and		tb.bra_PaymentSupp_Id		<> tct1.supp_id
					And		tct1.ct_date				> @FinishDate)[D8],




			--/::::: "D9" Cuentas Documentos Acreedoras :::::/--		ok
			(Select	--Isnull(Sum(tec5.ec_Total),0)
				round(isnull(sum(dbo.fnGetExchange(@comp_id, tec5.ec_Total,tec5.curr_id , @curr_id, @comp_curr_id , tec5.ec_exchangeToBranchCurrency,'False')) ,0),2)
				From	tbEmmitedChecks		tec5			WITH (NOLOCK)
				inner join tbUsers4BranchFilter vubf		WITH (NOLOCK)
					ON  vubf.comp_id    = tec5.comp_id
					AND vubf.bra_id     = tec5.bra_id
					AND vubf.[user_id]  = @user_id
				Where		tec5.comp_id			=	@comp_id
					And	   (tec5.bra_id				=   @bra_id OR @bra_id = -1)
					And		tec5.ec_isDocument		=	'True'
					AND		tec5.ec_isCancelled		= 'false'
					AND		tec5.ec_isPaid			= 'False'
					And		tec5.ec_PayDate			> @FinishDate	)[D9],





			--	--/::::: "D10" Otros Egresos :::::/--
			(Select  -- round(Isnull(Sum(tcfc5.cfo_credit),0) ,2)
				round(isnull(sum(dbo.fnGetExchange(@comp_id, tcfc5.cfo_credit,tcfc5.curr_id , @curr_id, @comp_curr_id , 0,'False')) ,0),2)
				From  dbo.tbCashFlowOtherConcepts tcfc5				WITH (NOLOCK)
				inner join tbUsers4BranchFilter vubf				WITH (NOLOCK)
					ON  vubf.comp_id    = tcfc5.comp_id
					AND vubf.bra_id     = tcfc5.bra_id
					AND vubf.[user_id]  = @user_id
				Where	  tcfc5.comp_id		= @comp_id
					And	 (tcfc5.bra_id		= @bra_id OR @bra_id = -1)
					And	  tcfc5.cfo_date    > @FinishDate) [D10],


				--/::::: "D11" Cheques Emitidos :::::/--
				(Select	--Isnull(Sum(tec2.ec_Total),0)
					round(isnull(sum(dbo.fnGetExchange(@comp_id, tec2.ec_Total,tec2.curr_id , @curr_id, @comp_curr_id , tec2.ec_exchangeToBranchCurrency,'False')) ,0),2)
					From  tbEmmitedChecks tec2						WITH (NOLOCK)
						inner join tbUsers4BranchFilter vubf		WITH (NOLOCK)
							ON  vubf.comp_id    = tec2.comp_id
							AND vubf.bra_id     = tec2.bra_id
							AND vubf.[user_id]  = @user_id
					Where	 tec2.comp_id			= @comp_id
						And	(tec2.bra_id			= @bra_id OR @bra_id = -1)
						AND	 tec2.ec_isPaid			= 'False'
						AND	 tec2.ec_isCancelled	= 'False'
						And  tec2.ec_isDocument		= 'False'
						And  tec2.ec_PayDate		> @FinishDate) [D11],


						--/::::: "D12" ORDEN DE COMPRA:::::/--		ok
			   CASE @includePurchaseOrder WHEN 'false' THEN CONVERT(DECIMAL,0)
					ELSE
						(Select
							round(isnull(sum(dbo.fnGetExchange(@comp_id, tpod.pod_qty*tpod.pod_price,tpod.curr_id , @curr_id, @comp_curr_id ,tpod.curr_id,'False')) ,0),2)
							From   tbPurchaseOrderHeader tpoh			WITH (NOLOCK)
							inner join tbUsers4BranchFilter vubf		WITH (NOLOCK)
								ON  vubf.comp_id    = tpoh.comp_id
								AND vubf.bra_id     = tpoh.bra_id
								AND vubf.[user_id]  = @user_id
							INNER JOIN tbPurchaseOrderDetail tpod		WITH (NOLOCK)
								ON  tpod.poh_id   = tpoh.poh_id
								AND tpod.comp_id  = tpoh.comp_id
								AND tpod.bra_id   = tpoh.bra_id
							Where	 tpoh.comp_id			= @comp_id
								And	(tpoh.bra_id			= @bra_id OR @bra_id = -1)
								AND  tpod.pod_isProcessed    = 'False'
								And  tpoh.poh_deliveryDate> @FinishDate)
			End [D12]
	Into	#tmpD
	From	tbCommercialTransactions						tct2			WITH (NOLOCK)
			Inner Join vwCommercialTransactions_forSales	vctfs			WITH (NOLOCK)
				On  vctfs.comp_id			= tct2.comp_id
				--And vctfs.bra_id			= tct2.bra_id
				And vctfs.ct_transaction	= tct2.ct_transaction
			INNER JOIN tbCustomer								tc			WITH (NOLOCK)
				ON	tc.comp_id						= tct2.comp_id
				AND tc.cust_id						= tct2.cust_id
				AND isnull(tc.cust_judMan,'False')	= 'False'
			inner join tbUsers4BranchFilter vubf							WITH (NOLOCK)
				ON  vubf.comp_id    = tct2.comp_id
				AND vubf.bra_id     = tct2.bra_id
				AND vubf.[user_id]  = @user_id
	Where		tct2.comp_id				= @comp_id
		And	   (tct2.bra_id					= @bra_id OR @bra_id = -1)
		And		tct2.curr_id_transaction	= @curr_id
		And		tct2.[ct_date]				> @FinishDate
	/**********************************************************************************************/



	-----------------------------------------------------------------------------------------------------------
	-----------------------------------------------------------------------------------------------------------


	-- // PARA EL B //
	Select	'2'		collate database_default			 [order],
			z.tmp_day			 [date],
			0					 [year],
			0					 [week],
			Isnull(sum(a.B1),0)  [B1],
			Isnull(sum(b.B2),0)  [B2],
			Isnull(Sum(c.B3),0)  [B3],
			Isnull(sum(d.B4),0)  [B4],
			Isnull(sum(e.B5),0)  [B5],
			Isnull(sum(f.B6),0)  [B6],
			Isnull(sum(g.B7),0)  [B7],
			Isnull(sum(h.B8),0)  [B8],
			Isnull(sum(i.B9),0)  [B9],
			Isnull(sum(j.B10),0) [B10],
			Isnull(sum(K.b11),0) [B11],
			Isnull(sum(l.B12),0) [B12],
			'B'					 [B13]

	Into	#tmpB

	From	#tmpDays	z
			full outer join #tmpB1  a
			On a.date = z.tmp_day

			full outer join #tmpB2  b
			On b.date = z.tmp_day

			full outer join #tmpB3  c
			On c.date = z.tmp_day

			full outer join #tmpB4  d
			On d.date = z.tmp_day

			full outer join #tmpB5  e
			On e.date = z.tmp_day

			full outer join #tmpB6  f
			On f.date = z.tmp_day

			full outer join #tmpB7  g
			On g.date = z.tmp_day

			full outer join #tmpB8  h
			On h.date = z.tmp_day

			full outer join #tmpB9  i
			On i.date = z.tmp_day

			full outer join #tmpB10 j
			On j.date = z.tmp_day

			full outer join #tmpB11 k
			On k.date = z.tmp_day

			full outer join #tmpB12 l
			On l.date = z.tmp_day

	Where	(CAST(@last_date AS FLOAT) - CAST(@bra_processingDate AS FLOAT) + 1) > 0

	Group By z.tmp_day

	--SELECT * FROM #tmpB





	--// PARA EL  "C" //

	Select	'3'  collate database_default [order], convert(DATETIME, '1800-01-01') [date], substring(z.tmp_week,1,4) [year], substring(z.tmp_week,5,2) [week],
			Isnull(sum(a.C1),0)  [C1],
			Isnull(sum(b.C2),0)  [C2],
			Isnull(sum(c.C3),0)  [C3],
			Isnull(sum(d.C4),0)  [C4],
			Isnull(sum(e.C5),0)  [C5],
			Isnull(sum(f.C6),0)  [C6],
			Isnull(sum(g.C7),0)  [C7],
			Isnull(sum(h.C8),0)  [C8],
			Isnull(sum(i.C9),0)  [C9],
			Isnull(sum(j.C10),0) [C10],
			Isnull(sum(K.C11),0) [C11],
			Isnull(sum(l.C12),0) [C12],
			'C'					 [C13]

	Into	#tmpC

	From	#tmpWeeks	z

			full outer join #tmpC1  a
			On a.date collate database_default = z.tmp_week

			full outer join #tmpC2  b
			On b.date collate database_default = z.tmp_week

			full outer join #tmpC3  c
			On c.date collate database_default = z.tmp_week

			full outer join #tmpC4  d
			On d.date collate database_default = z.tmp_week

			full outer join #tmpC5  e
			On e.date collate database_default = z.tmp_week

			full outer join #tmpC6  f
			On f.date collate database_default = z.tmp_week

			full outer join #tmpC7  g
			On g.date collate database_default = z.tmp_week

			full outer join #tmpC8  h
			On h.date collate database_default = z.tmp_week

			full outer join #tmpC9  i
			On i.date collate database_default = z.tmp_week

			full outer join #tmpC10 j
			On j.date collate database_default = z.tmp_week

			full outer join #tmpC11 k
			On k.date collate database_default = z.tmp_week

			full outer join #tmpC12 l
			On l.date collate database_default = z.tmp_week

	Group By z.tmp_week


	-- ------------------------------------
	-- Saca Saldos de Cuewntas Bancarias
	-- ------------------------------------
	  CREATE TABLE #tmpBancos
		(
			ba_desc		NVARCHAR(50),
			curr_desc	NVARCHAR(10),
			Total		DECIMAL(19,2),
			curr_id		int
		)

		CREATE TABLE #tmp_BT_TMP
			(
				id				INT,
				id2				INT,
				credito			DECIMAL(18,2),
				debito			DECIMAL(18,2),
				suma			DECIMAL(18,2),
				total2			DECIMAL(18,2),
				ct_transaction  INT,
				bt_id						INT,
				btt_id						INT,
				tmpID			INT IDENTITY(1,1)
			)


		CREATE TABLE #tmp_BankTrans
			(
			ID							INT,
			ID2							INT,
			btt_desc					NVARCHAR(200),
			bt_imputationDate			DATETIME,
			Number						NVARCHAR(200),
			bt_note						NVARCHAR(200),
			bt_Number					NVARCHAR(200),
			Is_Paid						BIT,
			Total						DECIMAL(19,2),
			Is_Credit					BIT,
			isChp						BIT,
			ct_transaction				INT,
			bt_id						int		,
			btt_id						int,
			ecct_id						INT,
			chp_isNegociated			bit,
			chp_isCustodia				bit
			)

	  DECLARE @curBA_ID		AS INT
	  DECLARE @curBA_DESC	AS NVARCHAR(200)
	  DECLARE @curCURR_ID	AS INT
	  DECLARE @curCURR_DESC	AS NVARCHAR(200)
	  declare @datefrom		AS DATETIME
	  DECLARE @dateto		AS DATETIME
      DECLARE @decTotalCompanyCurrency		AS DECIMAL(19,2)
	  DECLARE @decTotalBranchCurrency			AS DECIMAL(19,2)
	  DECLARE @message VARCHAR(100)
	  SELECT @message = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 150 AND tut.lang_id = @lang_id
	  /*Descripción de Compañía, Sucursal y las monedas de ambas*/
	  -- -------------------------------------------------------
	  -- ATENCION, se desea saber el saldo FINAL .!
	  -- -------------------------------------------------------
	  SET @datefrom = '1800-01-01'
	  SET @dateto	= '2999-01-01'
	  -- -------------------------------------------------------
		--	  SELECT @dateto = tb.bra_processingDate
		--			FROM tbBranch tb
		--			WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id

	  DECLARE curBanckingAccounts CURSOR LOCAL FAST_FORWARD  FOR SELECT
												    tba.ba_id,
	                                                tba.curr_id,
	                                                tba.ba_desc,
	                                                tc.curr_symbol
												FROM tbBankingAccounts tba	WITH (NOLOCK)
												INNER JOIN tbsysCurrency tc
													ON tc.curr_id = tba.curr_id
												WHERE tba.comp_id = @comp_id AND ISNULL(tba.ba_CashFlowExcluded,'False') = 'false'


	  OPEN curBanckingAccounts
  	  FETCH NEXT FROM curBanckingAccounts INTO @curBA_ID,@curCURR_ID,@curBA_DESC,@curCURR_DESC

	  WHILE @@FETCH_STATUS=0
		  BEGIN
			DELETE #tmp_BT_TMP
			DELETE #tmp_BankTrans
			EXEC spBankingTransactions_GenerateData4Reports
													@comp_id	,
													@lang_id	,
													@page_id	,
													@curBA_ID	,
													@datefrom	,
													@dateto		,
													-1     ,
													@bra_id,
													@brag_id,
													@user_id


			  INSERT INTO #tmpBancos
									(
										ba_desc	,
										curr_desc,
										Total,
										curr_id
									)												-- ABAJO difiere del Balance ya que muestra el saldo REAL a Hoy.
									SELECT TOP 1 @curBA_DESC,@curCURR_DESC, isnull(tmp.total2,0),@curCURR_ID FROM  #tmp_BT_TMP tmp ORDER BY tmp.tmpID desc

			  FETCH NEXT FROM curBanckingAccounts INTO @curBA_ID,@curCURR_ID,@curBA_DESC,@curCURR_DESC
		  END

	  CLOSE curBanckingAccounts
	  DEALLOCATE curBanckingAccounts
 	  drop table #tmp_BT_TMP
	  drop table #tmp_BankTrans

	SET @decTotalCompanyCurrency = 0
	SET @decTotalBranchCurrency  = 0
	IF EXISTS (SELECT TOP 1  1 FROM #tmpBancos)
		BEGIN
			-- Este es el que no muestra los totales y si se calculan aca.  GASTON
--			SELECT	*
--			FROM #tmpBancos

			  SELECT @decTotalBranchCurrency = SUM(dbo.fnGetExchange2(@comp_id, tmpst.Total, tmpst.curr_id,@curr_id,0,0,0,'False'))
				FROM #tmpBancos  tmpst
			  SELECT @decTotalCompanyCurrency = SUM(dbo.fnGetExchange2(@comp_id, tmpst.Total, tmpst.curr_id,@curr_id,0,0,0,'False'))
				FROM #tmpBancos  tmpst

		END
--	  ELSE
--			SELECT @message [ba_desc], ' ' [curr_desc], 0.00 [Total]


--	SELECT   @curr_id					[Bra_Curr],
--			 @decTotalBranchCurrency	[Bra_Total],
--			 @curr_id					[Comp_Curr],
--			 @decTotalCompanyCurrency	[Comp_Total]
--			 INTO #tmpTotal2


	--SELECT * FROM #tmpTotal2


	-- ------------------------------------



	-- Select FINAL a Retornar

	DECLARE @text	VARCHAR (100)
	SELECT @text = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 963



		Select	#tmpA.[order],
				#tmpA.[date],
				#tmpA.[year],
				#tmpA.[week],
				ISNULL(#tmpA.[A1],0) [A1],
				ISNULL(#tmpA.[A2],0) [A2],
				ISNULL(#tmpA.[A3],0) [A3],
				ISNULL(#tmpA.[A4],0) [A4],
				ISNULL(#tmpA.[A5],0) [A5],
				ISNULL(#tmpA.[A6],0) [A6],
				ISNULL(#tmpA.[A7],0) [A7],
				ISNULL(#tmpA.[A8],0) [A8],
				ISNULL(#tmpA.[A9],0) [A9],
				ISNULL(#tmpA.[A10],0)[A10],
				ISNULL(#tmpA.[A11],0)[A11],
				ISNULL(#tmpA.[A12],0)[A12],
				@text				 [A13]


		From #tmpA

	UNION

		-- Saldo de Bancos
		Select	'2'	collate database_default	[order],
				0			[date],
				0			[year],
				0			[week],
				0			[A1],
				0			[A2],
				0			[A3],
				0			[A4],
				dbo.fnGetExchange2(@comp_id, tmpb.Total, tmpB.curr_id,@curr_id,0,0,0,'False')	[A5],
				0			[A6],
				0			[A7],
				0			[A8],
				0			[A9],
				0			[A10],
				0			[A11],
				0			[A12],
				tmpB.ba_desc		 [A13]
		FROM #tmpBancos tmpB

	UNION

		Select  #tmpB.[order] collate database_default ,
				#tmpB.[date],
				#tmpB.[year],
				#tmpB.[week],
				ISNULL(#tmpB.[B1],0) [A1],
				ISNULL(#tmpB.[B2],0) [A2],
				ISNULL(#tmpB.[B3],0) [A3],
				ISNULL(#tmpB.[B4],0) [A4],
				ISNULL(#tmpB.[B5],0) [A5],
				ISNULL(#tmpB.[B6],0) [A6],
				ISNULL(#tmpB.[B7],0) [A7],
				ISNULL(#tmpB.[B8],0) [A8],
				ISNULL(#tmpB.[B9],0) [A9],
				ISNULL(#tmpB.[B10],0)[A10],
				ISNULL(#tmpB.[B11],0)[A11],
				ISNULL(#tmpB.[B12],0)[A12] ,
				'B'					 [A13]
				From #tmpb


		--Select * From #tmpB

	UNION

		Select  #tmpC.[order] collate database_default ,
				#tmpC.[date],
				#tmpC.[year],
				#tmpC.[week],
				ISNULL(#tmpC.[C1],0) [A1],
				ISNULL(#tmpC.[C2],0) [A2],
				ISNULL(#tmpC.[C3],0) [A3],
				ISNULL(#tmpC.[C4],0) [A4],
				ISNULL(#tmpC.[C5],0) [A5],
				ISNULL(#tmpC.[C6],0) [A6],
				ISNULL(#tmpC.[C7],0) [A7],
				ISNULL(#tmpC.[C8],0) [A8],
				ISNULL(#tmpC.[C9],0) [A9],
				ISNULL(#tmpC.[C10],0)[A10],
				ISNULL(#tmpC.[C11],0)[A11],
				ISNULL(#tmpC.[C12],0)[A12] ,
				'C'					 [A13]
				From #tmpC

		--Select * From #tmpC

	UNION

		Select  #tmpD.[order] collate database_default ,
				#tmpD.[date],
				#tmpD.[year],
				#tmpD.[week],
				ISNULL(#tmpD.[D1],0) [A1],
				ISNULL(#tmpD.[D2],0) [A2],
				ISNULL(#tmpD.[D3],0) [A3],
				ISNULL(#tmpD.[D4],0) [A4],
				ISNULL(#tmpD.[D5],0) [A5],
				ISNULL(#tmpD.[D6],0) [A6],
				ISNULL(#tmpD.[D7],0) [A7],
				ISNULL(#tmpD.[D8],0) [A8],
				ISNULL(#tmpD.[D9],0) [A9],
				ISNULL(#tmpD.[D10],0)[A10],
				ISNULL(#tmpD.[D11],0)[A11],
				ISNULL(#tmpD.[D12],0)[A12] ,
				'D'					 [A13]

	From #tmpD

	Order By [order]



DROP TABLE #tmpBancos




	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id




	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id


	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 28
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

			CASE @bra_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.bra_desc
						FROM	tbBranch tb
						WHERE	tb.comp_id = @comp_id AND tb.bra_id = @bra_id)
			END		[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 106
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			(SELECT	tc.curr_desc
			 FROM	tbsysCurrency tc
			 WHERE	Tc.curr_id = @curr_id)[params4],

			--Contempla cuentas deudoras
			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		  WHERE t.ctrl_id = 819
      		  --AND t.[lang_id] = @lang_id
      		  and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

			(SELECT	tov.optval_desc
			 From tbsysOptionsValues tov
			 Where tov.lang_id = @lang_id
			 And tov.optval_class = '1'
			 And  tov.optval_id = @AccountsPayable)[params6],

			--Contempla cuentas acreedoras
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			WHERE t.ctrl_id = 820
			--AND t.[lang_id] = @lang_id
			and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

			(SELECT	tov.optval_desc
			From tbsysOptionsValues tov
			Where tov.lang_id = @lang_id
			And tov.optval_class = '1'
			And  tov.optval_id = @AccountsReceivable)[params8],


			--Resumir semanalmente luego de x días
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			WHERE t.ctrl_id = 823
			--AND t.[lang_id] = @lang_id
			and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

			(SELECT	 @resumeday)   [params10],

			--Incluye Orden de Compra
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			WHERE t.ctrl_id = 1003
			--AND t.[lang_id] = @lang_id
			and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],

			(SELECT	tov.optval_desc
			 From tbsysOptionsValues tov
			 Where tov.lang_id = @lang_id
			 And tov.optval_class = '1'
			 And  tov.optval_id = @includePurchaseOrder)   [params12],

			--Incluye Valores recibidos pendientes de acreditar
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			WHERE t.ctrl_id = 1895
			--AND t.[lang_id] = @lang_id
			and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],

			(SELECT	tov.optval_desc
			 From tbsysOptionsValues tov
			 Where tov.lang_id = @lang_id
			 And tov.optval_class = '1'
			 And  tov.optval_id = @PendingToAccredit)   [params14]

END
GO






CREATE procedure [dbo].[spCashFlow_getDataByFilters_original]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			Int,

		@bra_id				Int,
		@curr_id			Int,
		@AccountsPayable	Bit, -- Cuentas Acreedoras
		@AccountsReceivable Bit, -- Cuentas Deudoras
		@resumeday			Int -- Días de resumen semanal
)
as
SET NOCOUNT ON
/*
DECLARE @comp_id			int,
		@lang_id			int,
		@page_id			Int,

		@bra_id				Int,
		@curr_id			Int,
		@AccountsPayable	bit, -- Cuentas Acreedoras
		@AccountsReceivable bit, -- Cuentas Deudoras
		@resumeday			Int -- Días de resumen semanal

SELECT	@comp_id			=1,
		@lang_id			=2,
		@page_id			=10035,

		@bra_id				=1,
		@curr_id			=2,
		@AccountsPayable	=1,
		@AccountsReceivable =1,
		@resumeday			=0


Drop table #tmpB1
Drop table #tmpB2
Drop table #tmpB3
Drop table #tmpB4
Drop table #tmpB5
Drop table #tmpB6
Drop Table #tmpB7
Drop table #tmpB8
Drop table #tmpB9
Drop table #tmpB10
Drop table #tmpB11

Drop table #tmpDays
Drop table #tmpWeeks

Drop table #tmpC1
Drop table #tmpC2
Drop table #tmpC3
Drop table #tmpC4
Drop table #tmpC5
Drop table #tmpC6
Drop table #tmpC7
Drop table #tmpC8
Drop table #tmpC9
Drop table #tmpC10
Drop table #tmpC11

Drop table #tmpA
Drop table #tmpB
Drop table #tmpC
Drop table #tmpD
*/


--Recupero la fecha de la sucursal.
Declare @bra_processingDate Datetime
Set @bra_processingDate = (Select bra_processingDate tb From tbBranch tb
							Where tb.comp_id=@comp_id
							And tb.bra_id	= 1)





---recuperar la moneda de la compañia
Declare @comp_curr_id Int
Select @comp_curr_id = @curr_id From tbCompany tc Where tc.comp_id = @comp_id






--generar temporal con los dias a tener en cuenta
Declare @current_date DATETIME, @last_date DATETIME

Create table #tmpDays ( tmp_day Datetime )

Set @current_date = @bra_processingDate
SET @last_date = @bra_processingDate + @resumeday - 1
SET @last_date = @last_date + 7 - DATEPART(weekday, @last_date)

If (CAST(@last_date AS FLOAT) - CAST(@bra_processingDate AS FLOAT) + 1) > 0
Begin

	Insert into #tmpDays (	tmp_day) Values (@current_date)
	While @current_date < @last_date
	Begin
		Set @current_date = @current_date + 1
		Insert into #tmpDays (tmp_day) Values (@current_date)
	end

END






--generar temporal con las semanas de los seis meses posteriores a la fecha de proceso + la cantidad de dias seleccionados
Create table #tmpWeeks ( tmp_week VARCHAR(6) )
DECLARE @Startdate DATETIME, @FinishDate DATETIME, @Date DATETIME, @dateant DATETIME, @weekant datetime

SET @Startdate	= @last_date + 1
SET @Date		= @Startdate

SET @FinishDate = DATEADD(month, 6, @last_date) + '23:59:59.990'
SET @FinishDate = @FinishDate + 7 - DATEPART(weekday, @FinishDate)
--SELECT 'rango de fechas de 3: ', @Date, @FinishDate, convert(varchar,datepart(week, @Date))
SET @dateant = @Date
WHILE @Date < 	@FinishDate
BEGIN

	IF convert(varchar,DATEPART(YEAR,@Date)) <> convert(varchar,DATEPART(YEAR,@dateant))
	BEGIN
		IF convert(varchar,datepart(week,@Date)) > 1
		BEGIN
			Insert into #tmpWeeks (tmp_week)
			Values (convert(varchar,DATEPART(YEAR,@Date)) + '01')

		END
	END
	SET @dateant = @Date

	Insert into #tmpWeeks (tmp_week)
	Values (convert(varchar,DATEPART(YEAR,@Date)) + convert(varchar,datepart(week,@Date)))

	SET @Date = DATEADD(WEEK, 1, @Date)
	--SELECT @date
END
--SELECT * FROM #tmpWeeks








/**********************************************************************************************************/
/********************************************** " A " *****************************************************/
/**********************************************************************************************************/

--Drop table #tmpA

Create table #tmpA ( [order] Varchar, [date] Datetime, [year] Int, [week] Int,
			  [A1]  Decimal (19,4), [A2]  Decimal (19,4), [A3] Decimal (19,4),
			  [A4]  Decimal (19,4), [A5]  Decimal (19,4), [A6] Decimal (19,4),
			  [A7]  Decimal (19,4), [A8]  Decimal (19,4), [A9] Decimal (19,4),
			  [A10] Decimal (19,4), [A11] Decimal (19,4))




--/::::: "1" Cuentas Corrientes Deudoras :::::/--
Insert into #tmpA
Select	'1' [order], @bra_processingDate [date], 0 [year], 0 [week],

		CASE @AccountsPayable WHEN 'true' THEN
			round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tct1.ct_abalance,tct1.ct_ACurrency,@curr_id,@comp_curr_id,tct1.ct_Branch2CompanyCurrencyExchange,'False')),0),2)
			ELSE CONVERT(DECIMAL,0)
		END [A1],




		--::::: "2" Cuentas Documentos Deudoras :::::/--
		(select CASE @AccountsReceivable WHEN 'true' Then
				round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tcp1.chp_total,tcp1.curr_id,@curr_id , @comp_curr_id ,tcp1.chp_BranchCurrencyExchange  ,'False')),0),2)
				ELSE CONVERT(DECIMAL,0)
				END

		 From  tbCheckPortfolio        tcp1

		 Where	 tcp1.comp_id			 =	@comp_id
		 And	 tcp1.bra_id			 =  @bra_id
		 And	 tcp1.chp_isDocument	 =  'True'
		 And     tcp1.chp_isCancelled    =  'False'
		 And     tcp1.chp_IsPayed        =  'False'
		 And     tcp1.chp_isAvailable    =  'True'
		 And	 tcp1.chp_PayDate		 < 	@bra_processingDate) [A2],




		--/::::: "3" Cheques en Cartera :::::/--
		(Select	--round(Isnull(Sum(dbo.fnGetExchange(@comp_id , tct3.ct_abalance , tct3.curr_id_transaction, @curr_id , @comp_curr_id, tct3.ct_Branch2CompanyCurrencyExchange,'False')),0) ,2)
		round(Isnull(Sum(dbo.fnGetExchange(@comp_id , tct3.ct_abalance , tct3.ct_ACurrency, @curr_id , @comp_curr_id, tct3.ct_Branch2CompanyCurrencyExchange,'False')),0) ,2)
		 From tbCommercialTransactions tct3

		 Inner Join vwCommercialTransactions_forSales vctfs		WITH (NOLOCK)
		 On  vctfs.comp_id					= tct3.comp_id
		 --And vctfs.bra_id					= tct3.bra_id
		 And vctfs.ct_transaction			= tct3.ct_transaction

		 Where	tct3.comp_id				= @comp_id
		 And	tct3.bra_id					= @bra_id
		 And	tct3.ct_date			    < @bra_processingDate)  [A3],




		--/::::: "4" Cupones a Acreditar :::::/--
		(Select	round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tccm.ccm_Total ,tccm.curr_id,@curr_id , @comp_curr_id ,tccm.ccm_BranchCurrencyExchange  ,'False')),0),2)
		 From	tbCreditCardMovements tccm

		 Where	tccm.comp_id				= @comp_id
		 And	tccm.bra_id					= @bra_id
		 And	tccm.ccm_isPayed			= 'False'
		 And	tccm.ccm_cardExpirationDate < @bra_processingDate) [A4],




		--/::::: "5" Otros Ingresos :::::/--
		(Select --round(Isnull(Sum(tcfc1.cfo_debit),0),2)
		round(Isnull(Sum(dbo.fnGetExchange(@comp_id ,tcfc1.cfo_debit,tcfc1.curr_id,@curr_id,@comp_curr_id,0,'False')),0),2)
		 From  dbo.tbCashFlowOtherConcepts tcfc1

		 Where tcfc1.comp_id		= @comp_id
		 And   tcfc1.bra_id			= @bra_id
		 And   tcfc1.curr_id		= @curr_id
		 And   tcfc1.cfo_date		< @bra_processingDate)[A5],




		--/::::: "6" Cheques a Acreditar :::::/--
		 (Select round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tcfc1.cfo_debit,tcfc1.curr_id,@curr_id , @comp_curr_id ,0,'False')),0),2)
		  From  dbo.tbCashFlowOtherConcepts tcfc1

		  Where tcfc1.comp_id		= @comp_id
		  And   tcfc1.bra_id		= @bra_id
		  And   tcfc1.cfo_date	    < @bra_processingDate) [A6],




		    --/::::: "7" Disponibilidad Inicial :::::/ --
			(Select round(Isnull(sum(dbo.fnGetExchange(@comp_id, tcm.cm_debit-tcm.cm_credit,tcm.curr_id,@curr_id,@comp_curr_id,tcm.cm_BranchCurrencyExchange,'False')),0),2)
			From tbCashMovements tcm

			Inner Join tbsysCurrency tc
			On tc.curr_id = tcm.curr_id

			Where	tcm.comp_id			= @comp_id
			And		(@bra_id			= -1		or tcm.bra_id			= @bra_id)
			And		tcm.cm_cd			< @bra_processingDate) [A7],





		    --/::::: "8" Cuentas Corrientes Acreedoras :::::/--
			(Select round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tct1.ct_abalance, ct_ACurrency, @curr_id , @comp_curr_id ,tct1.ct_Branch2CompanyCurrencyExchange,'False')),0),2)
			 From	tbCommercialTransactions					tct1

			 Inner Join vwCommercialTransactions_forPurchase	vctfs
			 On vctfs.comp_id			= tct1.comp_id
			 And vctfs.bra_id			= tct1.bra_id
			 And vctfs.ct_transaction	= tct1.ct_transaction

			 Where	tct1.comp_id		= @comp_id
			 And	tct1.bra_id			= @bra_id
			 And	tct1.ct_date		< @bra_processingDate) [A8],




			--/::::: "9" Cuentas Documentos Acreedoras :::::/--
			(Select  round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tec4.ec_Total,tec4.curr_id, @curr_id , @comp_curr_id ,tec4.ec_exchangeToBranchCurrency,'False')),0),2)
			 From  tbEmmitedChecks tec4

			 Where tec4.comp_id			= @comp_id
			 And   tec4.bra_id			= @bra_id
			 And   tec4.ec_isDocument   = 'True'
			 And   tec4.ec_PayDate		< @bra_processingDate) [A9],





			--/::::: "10" Otros Egresos :::::/--
			(Select round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tcfc4.cfo_credit,tcfc4.curr_id, @curr_id , @comp_curr_id ,0,'False')),0),2)
			 From  dbo.tbCashFlowOtherConcepts tcfc4

			 Where tcfc4.comp_id		= @comp_id
			 And   tcfc4.bra_id			= @bra_id
			 And   tcfc4.cfo_date		< 	@bra_processingDate) [A10],





			--/::::: "11" Cheques Emitidos :::::/--
			(Select round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tec1.ec_Total,tec1.curr_id, @curr_id , @comp_curr_id ,tec1.ec_exchangeToBranchCurrency,'False')),0),2)
			 From  tbEmmitedChecks tec1

			 Where tec1.comp_id			= @comp_id
			 And   tec1.bra_id			= @bra_id
			 And   tec1.curr_id			= @curr_id
			 And   tec1.ec_isDocument	= 'False'
			 And   tec1.ec_PayDate		< @bra_processingDate) [A11]




		From	tbCommercialTransactions				  tct1

		Inner Join vwCommercialTransactions_forSales	  vctfs		WITH (NOLOCK)
		On  vctfs.comp_id			= tct1.comp_id
		--And vctfs.bra_id			= tct1.bra_id
		And vctfs.ct_transaction	= tct1.ct_transaction

		Where	tct1.comp_id		= @comp_id
		And		tct1.bra_id			= @bra_id
		And		tct1.ct_date		< @bra_processingDate

--Select * From #tmpA

