--/* ////////////////////////////////////////////////////////////////////////////////////////////////////////*/







/***********************************************************************************************************/
/********************************************** " B " ******************************************************/

Declare @finish_processingDate Datetime
Set @finish_processingDate = @last_date + '23:59:59.990'
--Select @bra_processingDate, @finish_processingDate


--/::::: "B1" Cuentas Corrientes Deudoras :::::/--
Select	CAST(FLOOR(CAST(tct2.ct_date AS FLOAT)) AS DATETIME) [date],
		CASE @AccountsPayable WHEN 'true' THEN
			round(Isnull(Sum( dbo.fnGetExchange(@comp_id,tct2.ct_abalance,tct2.ct_ACurrency,@curr_id,@comp_curr_id,tct2.ct_Branch2CompanyCurrencyExchange,'False')),0),2)
			ELSE CONVERT(DECIMAL,0)
		END [B1]
Into	#tmpB1

From	tbCommercialTransactions						tct2
		Inner Join vwCommercialTransactions_forSales	vctfs		WITH (NOLOCK)
		On  vctfs.comp_id			= tct2.comp_id
		--And vctfs.bra_id			= tct2.bra_id
		And vctfs.ct_transaction	= tct2.ct_transaction

Where	 tct2.comp_id				= @comp_id
And		 tct2.bra_id				= @bra_id
And		 tct2.[ct_date]				between @bra_processingDate And @finish_processingDate

Group By CAST(FLOOR(CAST(tct2.ct_date AS FLOAT)) AS DATETIME)
--SELECT * FROM #tmpB1




--/::::: "B2" Cuentas Documentos Deudoras :::::/--
Select	 CAST(FLOOR(CAST(tcp2.chp_PayDate AS FLOAT)) AS DATETIME) [date],
		-- round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tcp2.chp_total,tcp2.curr_id,@curr_id, @comp_curr_id, tcp2.chp_BranchCurrencyExchange,'False')),0),2) [B2]
CASE @AccountsReceivable WHEN 'true' Then
				round(Isnull(Sum(dbo.fnGetExchange(@comp_id,tcp2.chp_total,tcp2.curr_id,@curr_id, @comp_curr_id, tcp2.chp_BranchCurrencyExchange,'False')),0),2)
			ELSE CONVERT(DECIMAL,0)
		END 	[B2]
Into	#tmpB2

From	tbCheckPortfolio        tcp2

Where	tcp2.comp_id			= @comp_id
And		tcp2.bra_id				= @bra_id
And		tcp2.chp_isDocument     = 'True'
And     tcp2.chp_isCancelled    = 'False'
And     tcp2.chp_IsPayed        = 'False'
And     tcp2.chp_isAvailable    = 'True'
And		tcp2.chp_PayDate		between @bra_processingDate And @finish_processingDate

Group By CAST(FLOOR(CAST(tcp2.chp_PayDate AS FLOAT)) AS DATETIME)
--SELECT * FROM #tmpB2





--/::::: "B3" Cheques en Cartera :::::/--
Select	CAST(FLOOR(CAST(tcp3.chp_PayDate AS FLOAT)) AS DATETIME) [date],
		round(Isnull(Sum(dbo.fnGetExchange( @comp_id , tcp3.chp_total , tcp3.curr_id , @curr_id , @comp_curr_id, tcp3.chp_BranchCurrencyExchange,'False')),0),2) [B3]

Into	#tmpB3

From  tbCheckPortfolio        tcp3

Where		tcp3.comp_id			=  @comp_id
And			tcp3.bra_id				=  @bra_id
And			tcp3.chp_isDocument     =  'False'
And         tcp3.chp_isCancelled    =  'False'
And         tcp3.chp_IsPayed        =  'False'
And         tcp3.chp_isAvailable    =  'True'
And			tcp3.chp_PayDate between @bra_processingDate And @finish_processingDate

Group By CAST(FLOOR(CAST(tcp3.chp_PayDate AS FLOAT)) AS DATETIME)
--SELECT * FROM #tmpB3





--/::::: "B4" Cupones a Acreditar :::::/--
Select	CAST(FLOOR(CAST(tccm.ccm_cardExpirationDate AS FLOAT)) AS DATETIME) [date],
		round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tccm.ccm_Total, tccm.curr_id , @curr_id , @comp_curr_id, tccm.ccm_BranchCurrencyExchange, 'False' )),0),2) [B4]

Into	#tmpB4

