round(Isnull(Sum(dbo.fnGetExchange( @comp_id ,tcp8.chp_total, tcp8.curr_id , @curr_id , @comp_curr_id , Tcp8.chp_BranchCurrencyExchange, 'False')),0),2) [B6] --Isnull(Sum(dbo.fnGetExchange(tcp1.comp_id,tcp1.chp_total,tcp1.curr_id,@curr_id,0,0,'False')),0) [value]

Into	#tmpB6

