		--round(Isnull(Sum(dbo.fnGetExchange( @comp_id , tcp2.chp_total ,tcp2.curr_id,@curr_id , @comp_curr_id ,tcp2.chp_BranchCurrencyExchange  ,'False')),0),2) [C2]
		CASE @AccountsReceivable WHEN 'true' Then
