		 sum(ISNULL(#tmpA.[A11],0)) [D11] From #tmpA
GROUP BY #tmpA.[order]

	UNION

Select #tmpB.[order],0 [a],0 [b],0 [c],
		 sum(ISNULL(#tmpB.[B1],0)) [D1],sum(ISNULL(#tmpB.[B2],0))[D2],
		 sum(ISNULL(#tmpB.[B3],0)) [D3],sum(ISNULL(#tmpB.[B4],0)) [D4],
		 sum(ISNULL(#tmpB.[B5],0)) [D5],sum(ISNULL(#tmpB.[B6],0)) [D6],
		 sum(ISNULL(#tmpB.[B7],0)) [D7],sum(ISNULL(#tmpB.[B8],0)) [D8],
		 sum(ISNULL(#tmpB.[B9],0)) [D9],sum(ISNULL(#tmpB.[B10],0)) [D10],
		 sum(ISNULL(#tmpB.[B11],0)) [D11] From #tmpB
GROUP BY #tmpB.[order]

	UNION

Select #tmpC.[order],0 [a],0 [b],0 [c],
		 sum(ISNULL(#tmpC.[C1],0)) [D1],sum(ISNULL(#tmpC.[C2],0))[D2],
		 sum(ISNULL(#tmpC.[C3],0)) [D3],sum(ISNULL(#tmpC.[C4],0)) [D4],
		 sum(ISNULL(#tmpC.[C5],0)) [D5],sum(ISNULL(#tmpC.[C6],0)) [D6],
		 sum(ISNULL(#tmpC.[C7],0)) [D7],sum(ISNULL(#tmpC.[C8],0)) [D8],
