		 sum(ISNULL(#tmpC.[C11],0)) [D11] From #tmpC
GROUP bY #tmpC.[order]

	UNION

SeleCt #tmpD.[order],0 [a],0 [b],0 [c],
		 sum(ISNULL(#tmpD.[D1],0)) [D1],sum(ISNULL(#tmpD.[D2],0))[D2],
		 sum(ISNULL(#tmpD.[D3],0)) [D3],sum(ISNULL(#tmpD.[D4],0)) [D4],
		 sum(ISNULL(#tmpD.[D5],0)) [D5],sum(ISNULL(#tmpD.[D6],0)) [D6],
		 sum(ISNULL(#tmpD.[D7],0)) [D7],sum(ISNULL(#tmpD.[D8],0)) [D8],
		 sum(ISNULL(#tmpD.[D9],0)) [D9],sum(ISNULL(#tmpD.[D10],0)) [D10],
		 sum(ISNULL(#tmpD.[D11],0)) [D11] From #tmpD
GROUP bY #tmpD.[order]
*/









exec [spReports_getData3]@comp_id,@bra_id, @lang_id,@page_id




/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/
SELECT
(SELECT t.[text_desc] FROM [tbsysTexts]	t
      	 WHERE t.ctrl_id = 28 AND t.[lang_id] = @lang_id and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],
		CASE @bra_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tb.bra_desc
					FROM	tbBranch tb
					WHERE	tb.comp_id = @comp_id AND tb.bra_id = @bra_id)
		END		[params2],

		(SELECT t.[text_desc] FROM [tbsysTexts]	t
      	 WHERE t.ctrl_id = 106 AND t.[lang_id] = @lang_id and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

		(SELECT	tc.curr_desc
		 FROM	tbsysCurrency tc
		 WHERE	Tc.curr_id = @curr_id)[params4],

		--Contempla cuentas deudoras
		 (SELECT t.[text_desc] FROM [tbsysTexts]	t
      	  WHERE t.ctrl_id = 819 AND t.[lang_id] = @lang_id and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

		(SELECT	tov.optval_desc
		 From tbsysOptionsValues tov
		 Where tov.lang_id = @lang_id
		 And tov.optval_class = '1'
		 And  tov.optval_id = @AccountsPayable)[params6],

		--Contempla cuentas acreedoras
		(SELECT t.[text_desc] FROM [tbsysTexts]	t
		WHERE t.ctrl_id = 820 AND t.[lang_id] = @lang_id and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

		(SELECT	tov.optval_desc
		From tbsysOptionsValues tov
		Where tov.lang_id = @lang_id
		And tov.optval_class = '1'
		And  tov.optval_id = @AccountsReceivable)[params8],


		--Resumir semanalmente luego de x días
		(SELECT t.[text_desc] FROM [tbsysTexts]	t
		WHERE t.ctrl_id = 823 AND t.[lang_id] = @lang_id and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

		(SELECT	 @resumeday)   [params10]

GO






CREATE PROCEDURE [dbo].[spCashMovements_checkBasicData]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			INT,
	@user_id			INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SET NOCOUNT ON

	/*
	DECLARE @comp_id		INT,
			@bra_id			INT,
			 @lang_id		INT,
			 @user_id		INT

	SELECT	@comp_id		= 2,
			@bra_id			= 1,
			@lang_id		= 2,
			@user_id		= -1

	DROP TABLE #tmpData

	*/
	CREATE TABLE #tmpData ( [check] INT )

	/*
	por cada control que se realice al comienzo de las páginas y no esté correcto,
	hay que hacer un insert en la temporal creada arriba
	con el valor correspondiente al table_id de la tabla tbSysTables (siempre deberá ser un valor negativo)
	y este valor está relacionado con la tabla tbSysHelpPages que si tendrá el mensaje de error
	a mostrar al usuario
	*/

	--if NOT EXISTS (select 1 from tbCashMovements		  WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-1)
	if not exists (select 1 from tbCashNumber4Branch4User
				   WHERE comp_id = @comp_id AND bra_id = @bra_id AND [user_id] = @user_id) INSERT INTO #tmpData ([check]) VALUES (0)

	--SELECT * FROM #tmpData


	SELECT	tut.utexts_desc, tut.utexts_id
	FROM	tbsysUniqueTexts tut
	WHERE	tut.lang_id			= @lang_id
	AND		tut.utexts_id		IN(4, 5, 6)
	AND		EXISTS(SELECT 1 FROM #tmpData)

	UNION

	SELECT	cast(thp.hp_desc AS NVARCHAR(MAX)), thp.page_id
	FROM	tbsysHelpPages			thp
			INNER JOIN #tmpData		td
			ON	td.[check]		= thp.table_id
	WHERE	thp.page_id			= -100070 --este valor está en duro e indica la funcionalidad que se está chequeando
										  --debe estar cargado en tbsyspages
	AND		thp.lang_id			= @lang_id

	ORDER BY 2 DESC



END
GO










CREATE  PROCEDURE [dbo].[spCashMovements_deleteData]
(
		@cm_id			int
)
as
set nocount on

Delete	dbo.tbCashMovements

where	cm_id			= @cm_id





GO




CREATE PROCEDURE [dbo].[spCashMovements_getBalance]
(
	@comp_id			INT,
	@bra_id				INT,
	@cn_id				INT,
	@curr_id			INT,
	@svt_id				INT,
	@return_value		DECIMAL(18,5) OUTPUT
)
AS


BEGIN

	-- ------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@bra_id				INT,
			@cn_id		INT,
			@curr_id	INT,
			@svt_id		INT,
			@return_value		DECIMAL(18,5)
	SELECT	@comp_id	=1,
			@bra_id		=1,
			@cn_id		=1,
			@curr_id	=1,
			@svt_id		=1
	*/
	-- ------------------------------------------------------------------


	SET NOCOUNT ON


	SELECT	@return_value  = isnull(SUM(tcm.cm_debit),0) - isnull(SUM(tcm.cm_credit),0)
		FROM	tbCashMovements		tcm	WITH (NOLOCK)
		WHERE	tcm.comp_id		=	@comp_id
		--AND		tcm.bra_id		=	@bra_id
		AND		tcm.cn_id		=	@cn_id
		AND		tcm.curr_id		=	@curr_id
		AND		tcm.svt_id		=	@svt_id


END
GO





CREATE PROCEDURE [dbo].[spCashMovements_getDataByFilters]
(
	@comp_id			int,
	@bra_id				int,
	@datefrom			datetime,
	@dateto				datetime,
	@curr_id			INT,
	@cn_id				INT,
	@user_id			INT
)
as


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


-- -----------------------------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------------------------
/*
	declare 	@comp_id			int,
				@bra_id				int,
				@datefrom			datetime,
				@dateto				DATETIME,
				@curr_id			INT,
				@cn_id				INT,
				@user_id			INT


	select		@comp_id			= 1,
				@bra_id				= -1,
				@datefrom			= '2011/11/24',
				@dateto				= '2011/11/24',
				@curr_id			= 1,
				@cn_id				= 1,
				@user_id			= 1
*/
-- -----------------------------------------------------------------------------------


	select
			' ' [ ],
			' ' [ ],
			cm.comp_id,
			cm.bra_id,
			cm.cm_cd,
			cm.cm_desc,
			cm.ca_id,
			ca.ca_desc,
			cm.cm_debit,
			cm.cm_credit,
			cm.curr_id,
			sc.[curr_desc],
			cm.cn_id,
			cn.cn_desc,
			cm.ct_transaction,
			cm.svt_id,
			svt.svt_desc,
			cm.cm_id [ID]




	from	dbo.tbCashMovements			cm

--			left join dbo.tbCommercialTransactions			ct
--			on  ct.comp_id				= cm.comp_id
--			AND ct.ct_transaction		= cm.ct_transaction

			inner join dbo.tbsysCurrency				sc
			on sc.[curr_id]				= cm.curr_id

			inner join dbo.tbCashNumbers				cn
			on cn.cn_id					= cm.cn_id

			inner join dbo.tbsysValuesTypes				svt
			on svt.svt_id				= cm.svt_id

			inner join dbo.tbCashAccountant				ca
			on ca.ca_id					= cm.ca_id

			/* Numero de Ticket 667 */
			INNER JOIN tbCashNumber4Branch4User			tcnbu
			ON  tcnbu.comp_id			= cm.comp_id
			AND tcnbu.cn_id				= cn.cn_id
			AND (tcnbu.bra_id			= cm.bra_id or @bra_id = -1)
			AND tcnbu.[user_id]			= @user_id


--			INNER JOIN tbUser							tu
--			ON tu.[user_id]				= @user_id



	Where	cm.comp_id	= @comp_id
	AND		(@bra_id = -1 or cm.bra_id	 = @bra_id)
	AND		cm.cm_cd	between  @datefrom and	@dateto
	AND		cm.curr_id	= @curr_id
	AND		cm.cn_id	= @cn_id


	ORDER BY cm.cm_cd, cm.cm_id


END
GO












CREATE PROCEDURE [dbo].[spCashMovements_getDataById]
(
	@cm_id	int
)
as
set nocount on
/*

declare @cm_id			int
select  @cm_id			= 3

*/
select	cm.comp_id,
		cm.bra_id,
		cm.cm_id,
		cm.cm_cd,
		cm.cm_desc,
		cm.ca_id,
		cm.cm_debit,
		cm.cm_credit,
		cm.curr_id,
		cm.cn_id,
		cm.ct_transaction,
		cm.svt_id,
		sc.curr_desc,
		cn.cn_desc,
		svt.svt_desc,
		ca.ca_desc,
		cm.cagt_id


from	dbo.tbCashMovements						cm

		inner join dbo.tbsysCurrency			sc
		on	sc.curr_id	= cm.curr_id

		inner join dbo.tbCashNumbers			cn
		on cn.cn_id		= cm.cn_id

		inner join dbo.tbsysValuesTypes			svt
		on svt.svt_id	= cm.svt_id

		inner join dbo.tbCashAccountant			ca
		on ca.ca_id		= cm.ca_id

where	cm.cm_id = @cm_id






















GO





-- ---------------------------------------------------------
-- Saca cual es el saldo ANTERIOR a la fecha de Inicio.!
-- ---------------------------------------------------------

CREATE procedure [dbo].[spCashMovements_getOldBalance]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,
		@datefrom			datetime,
		@dateto				datetime,
		@cac_id				int,
		@ca_id				int,
		@cn_id				int,
		@curr_id			int,
		@svt_id				int
)
as



BEGIN


	SET NOCOUNT ON
	set dateformat 'ymd'


	-- ---------------------------------------------------------
	-- TEsting
	-- ---------------------------------------------------------
	/*
		DECLARE	@comp_id		int,
				@lang_id		int,
				@page_id		int,

				@pres_id		int,
				@datefrom		datetime,
				@dateto			datetime,
				@cac_id			int,
				@ca_id			int,
				@cn_id			int,
				@curr_id		int,
				@svt_id			int


		SELECT	@comp_id			=1,
				@lang_id			=2,
				@page_id			=10006,

				@datefrom			='2012-05-08',
				@dateto				='2999-05-08',
				@cac_id				=-1,
				@ca_id				=-1,
				@cn_id				=-1,
				@curr_id			=1,
				@svt_id				=-1
	*/
	-- ---------------------------------------------------------






	set	@datefrom	= dbo.fnGetEnd_or_BeginOfDate( @datefrom	,'False')
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate( @dateto		,'True')
	---SELECT @dateto





	SELECT	isnull(sum([cm_debit] - [cm_credit]),0)			[old_balance]

	FROM	dbo.tbCashMovements						CM				WITH (NOLOCK)

			left join dbo.tbCommercialTransactions		CT				WITH (NOLOCK)
			ON	CM.[comp_id]						=	CT.[comp_id]
			and	CM.[bra_id]							=	CT.[bra_id]
			AND CM.[ct_transaction]					=	CT.[ct_transaction]

			inner JOIN dbo.tbCashAccountant		    CA					WITH (NOLOCK)
			on	CM.[comp_id]						=	CA.[comp_id]
			and CM.[ca_id]							=	CA.[ca_id]

			inner JOIN 	dbo.tbCashAccountantCategories	CAC				WITH (NOLOCK)
			on	CM.[comp_id]						=	CAC.[comp_id]
			--and CM.[ca_id]							=	CA.[ca_id]
			and CA.[cac_id]							=	CAC.[cac_id]

			inner JOIN 	dbo.tbsysValuesTypes		SVT					WITH (NOLOCK)
			on SVT.[svt_id]							=	CM.[svt_id]

			/*
			inner join dbo.tbCashNumbers			CN
			on CN.[comp_id]							=   CM.[comp_id]
			and CN.[bra_id]							=	CM.[bra_id]
			and CN.[cn_id]							=	CM.[cn_id]
			*/

			inner JOIN 	dbo.tbsysCurrency			SC					WITH (NOLOCK)
			on SC.[curr_id]							=	CM.[curr_id]


	WHERE		CM.[comp_id]		= @comp_id

	AND			CASE
					WHEN ct.ct_transaction IS NULL THEN cm.cm_cd
					ELSE CT.ct_date
				END					< @datefrom

	AND 		(@cac_id			= -1	OR CAC.[cac_id]	=	@cac_id)
	AND 		(@ca_id				= -1	OR CA.[ca_id]		=	@ca_id)
	AND 		(@cn_id				= -1	OR CM.[cn_id]		=	@cn_id)
	AND 		(@curr_id			= -1	OR SC.[curr_id]	=	@curr_id)
	AND			(@svt_id			= -1	OR SVT.[svt_id]	=	@svt_id)



END
GO



CREATE procedure [dbo].[spCashMovements_getReportOldBalance]
(
		@comp_id			INT,
		@lang_id			INT,
		@page_id			INT,


		@datefrom			DATETIME,
		@dateto				DATETIME,
		@cac_id				INT,
		@ca_id				INT,
		@cn_id				INT,
		@curr_id			INT,
		@svt_id				INT,
		@option				INT,
		@user_id			INT,
		@bra_id				INT,
		@intBranch4Lang		INT,
		@cng_id				INT

)
as


BEGIN



	SET NOCOUNT ON

	set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------
/*
	DECLARE
			@comp_id			int,
			@lang_id			int,
			@page_id			int,


			@pres_id			int,
			@datefrom			datetime,
			@dateto				datetime,
			@cac_id				int,
			@ca_id				int,
			@cn_id				int,
			@curr_id			int,
			@svt_id				int,
			@user_id			int,
			@bra_id				INT,
			@intBranch4Lang		INT,
			@option				int,
			@cng_id				INT


	SELECT

			@comp_id			=1,
			@lang_id			=2,
			@page_id			=10015,


			@datefrom			='2012-01-01',
			@dateto				='2999-05-07',
			@cac_id				=-1,
			@ca_id				=-1,
			@cn_id				= -1,
			@curr_id			= -1,
			@svt_id				=-1,
			@user_id			= 1,
			@bra_id				= 1,
			@option				= 1,
			@cng_id				= -1

	 */
	 -- ------------------------------------------------------------------

	-- -----------------------------------------------------
	-- Pone las cajas a tomer en cuenta para este reporte.
	-- -----------------------------------------------------
	DECLARE @tmpcashNumbers TABLE(cn_id INT PRIMARY KEY)
	IF @cng_id > 0
		BEGIN
			INSERT INTO @tmpcashNumbers(cn_id)
				SELECT DISTINCT tcngr.cn_id
					FROM tbCashNumbersGroupRelation tcngr
					WHERE	tcngr.comp_id	= @comp_id AND
							tcngr.cng_id	= @cng_id
		END
	ELSE IF @cn_id > 0
		BEGIN
			INSERT INTO @tmpcashNumbers(cn_id) VALUES (@cn_id)
		END
	ELSE
		BEGIN
			INSERT INTO @tmpcashNumbers(cn_id)
				SELECT DISTINCT	tcn.cn_id
					FROM tbCashNumbers tcn
					WHERE	tcn.comp_id = @comp_id AND
							tcn.bra_id	= @bra_id
		END
	-- -----------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')



	SELECT
			CASE
				WHEN ct.ct_transaction IS NULL THEN cm.cm_cd
				ELSE ct.ct_date
			END																											[ct_date],
			isnull(CA.ca_desc,'')																						[ca_desc],
			isnull(SVT.svt_desc,'')																						[svt_desc],
			case when not tc.cust_name is null then convert(varchar,tc.cust_id) + '-' + convert(varchar,tc.cust_name)
				when not ts.supp_name is null then convert(varchar,ts.supp_id) + '-' + convert(varchar,ts.supp_name)
				else CM.cm_desc
			end																											[cm_desc],
			isnull(CM.cm_desc,'')																						[cm_desc],
			ISNULL(cm.cm_debit,0)																						[cm_debit],
			ISNULL(cm.cm_credit,0)																						[cm_credit],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,CT.ct_transaction)								[ct_transaction],
			cn.cn_desc																									[cn_desc],
			isnull(CN2.cn_desc,'')																						[cn_related_desc]


		FROM	dbo.tbCashMovements						CM						WITH (NOLOCK)

		INNER JOIN @tmpcashNumbers tmp
			ON tmp.cn_id = cm.cn_id

			left JOIN tbCommercialTransactions		CT						WITH (NOLOCK)
			ON  CT.[comp_id]		= CM.[comp_id]
			AND CT.[bra_id]			= CM.[bra_id]
			AND CT.[ct_transaction] = CM.[ct_transaction]

			left join tbCustomer					tc						WITH (NOLOCK)
			on tc.comp_id			= CT.comp_id
			AND tc.cust_id			= CT.cust_id

			left join tbSupplier					ts						WITH (NOLOCK)
			on ts.comp_id			= CT.comp_id
			AND ts.supp_id			= CT.supp_id

			inner JOIN 	dbo.tbsysValuesTypes		SVT						WITH (NOLOCK)
			on SVT.[svt_id]			= CM.[svt_id]

			inner join dbo.tbCashNumbers			CN						WITH (NOLOCK)
			ON  CN.[comp_id]		= CM.[comp_id]
			and CN.[cn_id]			= CM.[cn_id]

			inner JOIN tbCashAccountant				CA						WITH (NOLOCK)
			on	CA.[comp_id]		= CM.[comp_id]
			and CA.[ca_id]			= CM.[ca_id]

			inner JOIN tbCashAccountantCategories	CAC						WITH (NOLOCK)
			on	CAC.comp_id			= CA.comp_id
			AND CAC.cac_id			= CA.cac_id

			inner JOIN 	dbo.tbsysCurrency			SC						WITH (NOLOCK)
			on SC.[curr_id]			=	CM.[curr_id]

			inner join tbUsers4BranchFilter vubf							WITH (NOLOCK)
			ON  vubf.comp_id		= CM.comp_id
			AND vubf.bra_id			= CM.bra_id
			AND vubf.[user_id]		= @user_id

			left join dbo.tbCashNumbers			CN2						WITH (NOLOCK)
			ON  CN2.[comp_id]		= CM.[comp_id]
			and CN2.[cn_id]			= CM.cn_id_related


	WHERE		CM.[comp_id]		= @comp_id
	and			(@cac_id			= -1	or	CAC.[cac_id]	=	@cac_id)
	and			(@ca_id				= -1	or	CA.[ca_id]		=	@ca_id)
	--and			(
	--			 (@cn_id			= -1 AND cn.bra_id = @bra_id)
	--				or
	--			  CM.[cn_id]		=	@cn_id
	--			)
	and			(@curr_id			= -1	or	SC.[curr_id]	=	@curr_id)
	AND			(@svt_id			= -1	or	SVT.[svt_id]	=	@svt_id)
	and			(@option			= -1	or	@option		=	1 AND ct.ct_transaction IS NOT NULL OR @option		=	2 AND ct.ct_transaction IS NULL)
	AND			case
					WHEN ct.ct_transaction IS NULL THEN cm.cm_cd
					ELSE CT.ct_date
				END					between @datefrom and  @dateto

	/*group by

				ct.ct_transaction,
			CA.ca_desc,
			SVT.svt_desc,
			CM.cm_desc
*/

--	MOS: 12-2010  AND			ct.ct_date			between @datefrom and  @dateto
	order by
				case
					WHEN ct.ct_transaction IS NULL THEN cm.cm_cd
					ELSE CT.ct_date
				END,
				case
					WHEN ct.ct_transaction IS NULL THEN cm.cm_creationDate
					ELSE CT.ct_cd
				END





	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	-- MOs: 12-2010
	-- set	@dateto = @dateto - '23:59:59.990'


	exec dbo.spCashMovements_getOldBalance
	@comp_id, @lang_id, @page_id, @datefrom, @dateto, @cac_id, @ca_id, @cn_id, @curr_id, @svt_id




	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],
      		 @datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom)) 	[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],
      		@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))		[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 428
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],
			CASE @cac_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tcac.cac_desc
						FROM	tbCashAccountantCategories tcac
						WHERE	tcac.comp_id = @comp_id AND tcac.cac_id = @cac_id)
			END		[params6],
			---

			--																								[param6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 363
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params7],
			CASE @ca_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tca.ca_desc
						FROM	tbCashAccountant tca
						WHERE	tca.comp_id = @comp_id AND tca.ca_id = @ca_id)
			END		[params8],
			--@ca_id																												[param8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 360
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params9],
			CASE @cn_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tcn.cn_desc
						FROM	tbCashNumbers tcn
						WHERE	tcn.comp_id = @comp_id AND tcn.cn_id = @cn_id)
			END		[params10],
			--@cn_id																												[param10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 106
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params11],
			CASE @curr_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.curr_desc
						FROM	dbo.tbsysCurrency tsc
						WHERE	tsc.curr_id = @curr_id)
			END		[params12],
			--@curr_id																											[param12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 431
      		--AND t.[lang_id] = @lang_id
     		and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params13],
			CASE @svt_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsv.svt_desc
						FROM	dbo.tbsysValuesTypes tsv
						WHERE	tsv.svt_id = @svt_id)
			END		[params14],
			--@svt_id																												[param14]



			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 991
      		--AND t.[lang_id] = @lang_id
     		and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params15],
			CASE @option WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
						FROM	dbo.tbsysOptionsValues tov
						WHERE	tov.lang_id = @lang_id AND tov.optval_id = @option AND tov.optval_class = 361)
			END		[params16],

			(SELECT tswn.word_desc
			 FROM [tbsysTextsNew] t
			 INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 3878
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params17],
			CASE @cng_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tcng.cng_desc
						FROM	dbo.tbCashNumbersGroup tcng
						WHERE	tcng.comp_id = @comp_id and
								tcng.cng_id = @cng_id)
			END																	[params18]






END






/*
	SELECT
			SUM (cm.cm_debit)  [cm_debit],
			SUM (cm.cm_credit) [cm_credit],

			SUM (cm.cm_debit) - SUM (cm.cm_credit)


