CREATE PROCEDURE [dbo].[spCashMovements_getReportTotals]
(
	@comp_id		INT,
	@lang_id		INT,
	@page_id		INT,

	@date			DATETIME,
	@cn_id			INT,
	@bra_id			INT,
	@intBranch4Lang	INT,
	@cng_id			INT
)
AS



BEGIN





	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- ------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------
/*
	DECLARE	@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@date			datetime,
			@cn_id			int,
			@bra_id			int,
			@intBranch4Lang	INT,
			@cng_id			INT

	SELECT	@comp_id		= 1,
			@lang_id		= 2,
			@page_id		= 10080,

			@date			= '2012-02-10',
			@cn_id			= -1,
			@bra_id			= 1,
			@intBranch4Lang = 1,
			@cng_id			= -1
*/
	--------------------------------------------------------------------


	-- -----------------------------------------------------
	-- Pone las cajas a tomer en cuenta para este reporte.
	-- -----------------------------------------------------
	DECLARE @tmpcashNumbers TABLE(cn_id INT PRIMARY KEY, cn_noOldBalance BIT)
	IF @cng_id > 0
		BEGIN
			INSERT INTO @tmpcashNumbers(cn_id, cn_noOldBalance)
				SELECT DISTINCT tcngr.cn_id,
								isnull(tcn.ca_disablePreviousMovementsOnReports,'False')
					FROM tbCashNumbersGroupRelation tcngr		WITH(NOLOCK)
					INNER JOIN tbCashNumbers		tcn			WITH(NOLOCK)
						ON	tcn.comp_id = tcngr.comp_id AND
							tcn.cn_id	= tcngr.cn_id
					WHERE	tcngr.comp_id	= @comp_id AND
							tcngr.cng_id	= @cng_id
		END
	ELSE IF @cn_id > 0
		BEGIN
			INSERT INTO @tmpcashNumbers(cn_id, cn_noOldBalance)
			SELECT	tcn.cn_id,
					isnull(tcn.ca_disablePreviousMovementsOnReports,'False')
				FROM tbCashNumbers tcn		WITH(NOLOCK)
				WHERE	tcn.comp_id = @comp_id AND
						tcn.cn_id	= @cn_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpcashNumbers(cn_id, cn_noOldBalance)
				SELECT DISTINCT	tcn.cn_id ,
								isnull(tcn.ca_disablePreviousMovementsOnReports,'False')
					FROM tbCashNumbers tcn		WITH(NOLOCK)
					WHERE	tcn.comp_id = @comp_id AND
							tcn.bra_id	= @bra_id
		END
	-- -----------------------------------------------------


	DECLARE @datFromDate AS DATETIME
	DECLARE @datToDate   AS DATETIME
	SET @datFromDate = dbo.fnGetEnd_or_BeginOfDate(@date,'False')
	SET @datToDate   = dbo.fnGetEnd_or_BeginOfDate(@date,'True')

	DECLARE	@saldoanterior	DECIMAL

	SELECT	CASE
				WHEN tcmt.cagt_desc IS NULL THEN	svt.svt_desc
				ELSE								svt.svt_desc + '->' + tcmt.cagt_desc
			END
																						[svt_desc],
			sc.curr_symbol,

			SUM(CASE	WHEN ISNULL(CT.ct_date,cm.cm_cd) BETWEEN @datFromDate AND @datToDate	THEN isnull(cm.cm_debit,0)
						ELSE 0
				END)																	[cm_debit],

			SUM(CASE	WHEN ISNULL(CT.ct_date,cm.cm_cd) BETWEEN @datFromDate AND @datToDate	THEN isnull(cm.cm_credit,0)
						ELSE 0
				END)																	[cm_credit],

			SUM(CASE
					WHEN tmp.cn_noOldBalance = 'True'						THEN 0.0000
					WHEN ISNULL(CT.ct_date,cm.cm_cd) < @datFromDate 		THEN isnull(cm.cm_debit,0) - isnull(cm.cm_credit,0)
					ELSE														 0.0000
				END)																	[oldbalance],

			cn.cn_desc

		INTO #tmpSaldos

		FROM	dbo.tbCashMovements				CM				WITH (NOLOCK)

		INNER JOIN @tmpcashNumbers				tmp
		ON tmp.cn_id			= cm.cn_id

		LEFT JOIN tbCommercialTransactions		CT				WITH (NOLOCK)
		ON  CT.[comp_id]		= CM.[comp_id]
		AND CT.[bra_id]			= CM.[bra_id]
		AND CT.[ct_transaction] = CM.[ct_transaction]

		LEFT JOIN tbCashNumbers					CN				WITH (NOLOCK)
		ON  CN.[comp_id]		= CM.comp_id
		and CN.[cn_id]			= CM.cn_id

		LEFT JOIN tbsysCurrency					SC				WITH (NOLOCK)
		on  SC.curr_id			= CM.curr_id

		LEFT JOIN tbsysValuesTypes				SVT				WITH (NOLOCK)
		ON  SVT.svt_id			= CM.svt_id

		LEFT JOIN tbCashMovementsTypes		 AS tcmt			WITH (NOLOCK)
			ON	tcmt.comp_id	= cm.comp_id AND
				tcmt.cagt_id	= cm.cagt_id

	WHERE	cm.comp_id			= @comp_id
	--AND 	((@cn_id		= -1 AND cn.bra_id = @bra_id)	OR 	cm.cn_id	= @cn_id)


	GROUP BY	cn.cn_desc,
				sc.curr_symbol,
				svt.svt_desc,
				cm.cagt_id,
				tcmt.cagt_desc

	ORDER BY
				sc.curr_symbol,
				cn.cn_desc,
				svt.svt_desc

	--



	SELECT
		curr_symbol,
		Sum(cm_debit)			[cm_debit],
		Sum(cm_credit)			[cm_credit],
		Sum(oldbalance)			[oldbalance]

		INTO #tmpTotals
		FROM #tmpSaldos

		GROUP BY curr_symbol

	-- -----------------------------------------------
	-- Seleccion Final a Mostrar
	-- -----------------------------------------------
		SELECT
			svt_desc,
			curr_symbol,
			cm_debit,
			cm_credit,
			oldbalance,
			dbo.fnStrPADR( ' ' + cn_desc,18,' ')		[cn_desc]

			FROM #tmpSaldos

	UNION

		SELECT
			dbo.fnStrPADR('Total ',30,'-'),
			curr_symbol,
			cm_debit,
			cm_credit,
			oldbalance,
			'*-------------------'
			FROM #tmpTotals

			ORDER BY
					curr_symbol,
					cn_desc,
					svt_desc
	-- -----------------------------------------------


	DROP TABLE #tmpSaldos
	DROP TABLE #tmpTotals

	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*************************************************************************************************************/

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t	WITH(NOLOCK)
				INNER JOIN tbSysWordsNew tswn WITH(NOLOCK) ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],
      		 @date [DateParams1],
			--convert(varchar,day(@date)) + '/' + convert(varchar,month(@date)) + '/' + convert(varchar,year(@date)) 	[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t WITH(NOLOCK)
			INNER JOIN tbSysWordsNew tswn WITH(NOLOCK)
			ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 360
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params2],


			CASE @cn_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut	WITH(NOLOCK)
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tcn.cn_desc
						FROM	tbCashNumbers tcn	WITH(NOLOCK)
						WHERE	tcn.comp_id = @comp_id AND tcn.cn_id = @cn_id)
			END		[params3],

			(SELECT tswn.word_desc
			 FROM [tbsysTextsNew] t
			 INNER JOIN tbSysWordsNew tswn WITH(NOLOCK)	ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 3878
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params4],
			CASE @cng_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut	WITH(NOLOCK)
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT		tcng.cng_desc
						FROM	dbo.tbCashNumbersGroup tcng	WITH(NOLOCK)
						WHERE	tcng.comp_id = @comp_id and
								tcng.cng_id = @cng_id)
			END																	[params5]



END
GO







CREATE PROCEDURE [dbo].[spCashMovements_insertData]
(
	@comp_id			INT,
	@bra_id				INT,
	@cm_cd				DATETIME,
	@cm_desc			VARCHAR(100),
	@ca_id				INT,
	@cm_debit			DECIMAL(19,6),
	@cm_credit			DECIMAL(19,6),
	@curr_id			INT,
	@cn_id				INT,
	@ct_transaction		INT,
	@svt_id				INT,
	@cagt_id			INT,
	@return_value		INT	OUTPUT
)
AS
SET NOCOUNT ON



/*
DECLARE	@comp_id		INT,
		@bra_id			INT
SELECT	@comp_id		=1,
		@bra_id			=1
*/

IF @cagt_id = -1
	BEGIN
		SET @cagt_id = NULL
	END

DECLARE @lcurr_id					INT,
		@lcurr_id4Exchange			INT,
		@lBranchCurrencyExchange	DECIMAL(19,6)


SELECT	@lcurr_id			= tb.curr_id,
		@lcurr_id4Exchange	= tb.curr_id4Exchange
	FROM	tbBranch tb		WITH (NOLOCK)
	WHERE	tb.comp_id	= @comp_id
	AND		tb.bra_id	= @bra_id


SET @lBranchCurrencyExchange = dbo.fnGetExchange2(@comp_id,1,@lcurr_id,@lcurr_id4Exchange,0,0,0,'FALSE')




INSERT INTO dbo.tbCashMovements
(
	comp_id,
	bra_id,
	cm_cd,
	cm_desc,
	ca_id,
	cm_debit,
	cm_credit,
	curr_id,
	cn_id,
	ct_transaction,
	svt_id,
	cm_BranchCurrencyExchange,
	cagt_id
)
VALUES
(
	@comp_id,
	@bra_id,
	@cm_cd,
	@cm_desc,
	@ca_id,
	@cm_debit,
	@cm_credit,
	@curr_id,
	@cn_id,
	@ct_transaction,
	@svt_id,
	@lBranchCurrencyExchange,
	@cagt_id
)

SET @return_value = @@identity
GO









CREATE PROCEDURE [dbo].[spCashMovements_TinsertData]

(
	@comp_id			int,
	@bra_id				int,
	@cm_cd				datetime,
	@cm_desc			varchar(100),
	@ca_id				int,
	@cm_debit			decimal(19,6),
	@cm_credit			decimal(19,6),
	@curr_id			int,
	@cn_id				int,
	@ct_transaction		int,
	@svt_id				int,

	@return_value						int					output,
	@ret_ErrorCode						int					output,
	@ret_ErrorDescription				varchar(200)		output
)
as
SET NOCOUNT ON


Set @return_value			= 0
Set @ret_ErrorCode			= 0
Set @ret_ErrorDescription	= ''


EXEC spCashMovements_insertData
	@comp_id,
	@bra_id,
	@cm_cd,
	@cm_desc,
	@ca_id,
	@cm_debit,
	@cm_credit,
	@curr_id,
	@cn_id,
	@ct_transaction,
	@svt_id,
	-1,
	@return_value = @return_value
GO



CREATE PROCEDURE [dbo].[spCashMovements_transferData]
(
	@comp_id			int,
	@bra_id				int,
	@processing_date	Datetime,
	@cm_desc			varchar(100),
	@import				decimal(19,6),
	@curr_id			int,
	@cn_id_source		int,
	@cn_id_destiny		int,
	@svt_id				INT,
	@return_value		DECIMAL(18,5) OUTPUT
)
As


BEGIN

	Set Nocount On
	SET DATEFORMAT ymd

-- -------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------
/*
	Declare
		@comp_id			int,
		@bra_id				int,
		@processing_date	Datetime,
		@cm_desc			varchar(100),
		@import				decimal(19,6),
		@curr_id			int,
		@cn_id_source		int,
		@cn_id_destiny		int,
		@svt_id				Int,
		@return_value		DECIMAL(18,5)

	Select
		@comp_id			= 1,
		@bra_id				= 1,
		@processing_date	= GETDATE(),
		@cm_desc			= 'PRUEBA SEBASTIAN',
		@import				= 66.66,
		@curr_id			= 1,
		@cn_id_source		= 1,
		@cn_id_destiny		= 2,
		@svt_id				= 4,
		@return_value		= 0
*/
-- -------------------------------------------------------------




	Declare @rv INT


	SET @return_value = -1

	-- -------------------------------------------------------------
	--recupera el cashAccountant para la tranferencia
	-- -------------------------------------------------------------
	Declare @ca_id INT
	SET @ca_id = NULL
	SELECT @ca_id = tcn.ca_id4CashTransfer
		FROM tbCashNumbers tcn		WITH (NOLOCK)
		WHERE	tcn.comp_id = @comp_id AND
				tcn.cn_id	= @cn_id_source

	IF @ca_id IS NULL
	BEGIN
		Select	@ca_id = tb.bra_CollectionCaId_Transfer
			From	tbBranch tb		WITH (NOLOCK)
			Where	tb.comp_id	=	@comp_id
				And	tb.bra_id	=	@bra_id
	END
	-- -------------------------------------------------------------



	-- -------------------------------------------------------------
	-- Recupera las cajas para los Ingresos y Egresos
	-- -------------------------------------------------------------

	-- Egresos
	declare @ca_idSource	INT
	SET     @ca_idSource = 0

	SELECT @ca_idSource = tcn.ca_id4CashTransfer
		FROM tbCashNumbers tcn		WITH (NOLOCK)
		WHERE	tcn.comp_id = @comp_id AND
				tcn.cn_id	= @cn_id_source


	IF @ca_idSource IS NULL
		BEGIN

			select
				@ca_idSource =
				case
					when @svt_id = 1		then	tb.bra_CollectionCaId_Money
					when @svt_id = 2		then	tb.bra_CollectionCaId_Cheque
					when @svt_id = 3		then	tb.bra_CollectionCaId_Cheque
					when @svt_id = 4		then	tb.bra_CollectionCaId_Documents
					when @svt_id = 5		then	tb.bra_CollectionCaId_CreditCard
					when @svt_id = 6		then	tb.bra_CollectionCaId_Transfer
					when @svt_id = 7		then	tb.bra_CollectionCaId_Transfer
					else							@ca_id
				end

			from tbBranch					tb		WITH (NOLOCK)
			where	tb.comp_id	= @comp_id
			and		tb.bra_id	= @bra_id

		END


	--Ingresos
	declare @ca_idDestiny	INT
	set     @ca_idDestiny = 0
	SELECT @ca_idDestiny = tcn.ca_id4CashTransfer
		FROM tbCashNumbers tcn		WITH (NOLOCK)
		WHERE	tcn.comp_id = @comp_id AND
				tcn.cn_id	= @cn_id_destiny

	IF @ca_idDestiny IS NULL
		BEGIN

			select
				@ca_idDestiny =
				case
					when @svt_id = 1		then	tb.bra_CollectionCaId_Money
					when @svt_id = 2		then	tb.bra_CollectionCaId_Cheque
					when @svt_id = 3		then	tb.bra_CollectionCaId_Cheque
					when @svt_id = 4		then	tb.bra_CollectionCaId_Documents
					when @svt_id = 5		then	tb.bra_CollectionCaId_CreditCard
					when @svt_id = 6		then	tb.bra_CollectionCaId_Transfer
					when @svt_id = 7		then	tb.bra_CollectionCaId_Transfer
				else								@ca_id
				end

			from tbBranch					tb		WITH (NOLOCK)
			where	tb.comp_id	= @comp_id
			and		tb.bra_id	= @bra_id

		END

	-- -------------------------------------------------------------


	--SELECT @ca_idSource,@ca_idDestiny



	BEGIN TRANSACTION
	BEGIN TRY




		--saca de caja origen
		Exec spCashMovements_insertData
			@comp_id,
			@bra_id,
			@processing_date,
			@cm_desc,
			@ca_idSource,
			@import,
			'0',
			@curr_id,
			@cn_id_destiny,
			null,
			@svt_id,
			-1,
			@return_value =@rv OUTPUT

		UPDATE tbCashMovements
			SET cn_id_related = @cn_id_source
			WHERE	comp_id = @comp_id	AND
					bra_id	= @bra_id	AND
					cm_id	= @rv




		--ingresa en caja destino
		Exec spCashMovements_insertData
			@comp_id,
			@bra_id,
			@processing_date,
			@cm_desc,
			@ca_idDestiny,
			'0',
			@import,
			@curr_id,
			@cn_id_source,
			null,
			@svt_id,
			-1,
			@return_value = @rv	OUTPUT

		UPDATE tbCashMovements
			SET cn_id_related = @cn_id_destiny
			WHERE	comp_id = @comp_id	AND
					bra_id	= @bra_id	AND
					cm_id	= @rv



		SET @return_value = @rv

		COMMIT TRANSACTION

	END

	TRY BEGIN CATCH
		ROLLBACK TRANSACTION
	END CATCH

END
GO









CREATE  PROCEDURE [dbo].[spCashMovements_updateData]
(
	@cm_id				int,
	@cm_cd				datetime,
	@cm_desc			varchar(100),
	@ca_id				int,
	@cm_debit			decimal(19,6),
	@cm_credit			decimal(19,6),
	@curr_id			int,
	@cn_id				int,
	@ct_transaction		int,
	@svt_id				INT,
	@cagt_id			INT

)
as
set nocount on

/*
declare
			@cm_id				int,
			@cm_cd				datetime,
			@ca_id				int,
			@cm_debit			decimal(19,6),
			@cm_credit			decimal(19,6),
			@curr_id			int,
			@cn_id				int,
			@ct_transaction		int,
			@svt_id				int

*/

IF @cagt_id = -1
	BEGIN
		SET @cagt_id = NULL
	END

update	dbo.tbCashMovements

set
		ca_id				=   @ca_id,
		cm_cd				=	@cm_cd,
		cm_desc				=	@cm_desc,
		cm_debit			=	@cm_debit,
		cm_credit			=	@cm_credit,
		curr_id				=	@curr_id,
		cn_id				=	@cn_id,
		ct_transaction		=	@ct_transaction,
		svt_id				=	@svt_id,
		cagt_id				=	@cagt_id


where	cm_id				= @cm_id


GO






