CREATE PROCEDURE [dbo].[spCashNumbers_getCombo]
(
	@comp_id				INT,
	@bra_id					INT,
	@user_id				INT
)
as

BEGIN


-- --------------------------------------------------
-- Testing
-- --------------------------------------------------
	/*
	declare @comp_id			int,
			@bra_id				int

	select  @comp_id			= 1 ,
			@bra_id				= 1
	*/
-- --------------------------------------------------

	set nocount on

	select	distinct
				cn.cn_id		[Id],
				cn.cn_desc		[desc],
				cn.cn_isAlternative4DirectCollection

	from		dbo.tbCashNumbers	cn	WITH (NOLOCK)

		INNER JOIN tbUsers4BranchFilter vubf		WITH (NOLOCK)		--MOS 09-2012
			ON		vubf.comp_id	= cn.comp_id
				AND vubf.bra_id		= cn.bra_id
				AND vubf.[user_id]	= @user_id

	where		cn.comp_id		= @comp_id
		AND		IsNull(cn.cn_disabled,'False') = 'False'

	order BY cn.cn_isAlternative4DirectCollection, cn_desc	-- ATENCION, NO Cambiar esto.!!

	--and		bra_id		= @bra_id




END

















GO







