CREATE PROCEDURE [dbo].[spCashNumbers4Branch4User_getCombo]
(
	@comp_id	As Int,
	@bra_id		As Int,
	@user_id	As int
)
as

BEGIN

-- al que toque este sp lo cago a patadas en el ortooo!!!!!!!!!

	set nocount on


	/*
	DECLARE		@comp_id	As Int,
				@bra_id		As Int,
				@user_id	As INT

	SELECT		@comp_id	=1,
				@bra_id		=1,
				@user_id	=4

	*/

	select	distinct
			cn.cn_id			[Id],
			cn.cn_desc			[desc],
			cn.cn_isAlternative4DirectCollection

	from	dbo.tbCashNumbers						cn	WITH (NOLOCK)

			Inner Join tbCashNumber4Branch4User		tcnbu	WITH (NOLOCK)
			On			tcnbu.comp_id	=	cn.comp_id
				And		(tcnbu.bra_id	=	cn.bra_id OR @bra_id = -1)
				AND		tcnbu.cn_id		=	cn.cn_id
				And		tcnbu.[user_id]	=	@user_id

			INNER JOIN tbUsers4BranchFilter vubf		WITH (NOLOCK)		--MOS 09-2012
				ON		vubf.comp_id	= cn.comp_id
					AND vubf.bra_id		= cn.bra_id
					AND vubf.[user_id]	= @user_id

	WHERE	cn.comp_id		= @comp_id
	AND		cn.bra_id		= @bra_id     --  NOOOOOOOOO   !!!!   para que mierda tocannnnn tcnbu.bra_id

	order BY cn.cn_isAlternative4DirectCollection,cn_desc	-- ATENCION, NO Cambiar esto.!!

END
GO





