CREATE PROCEDURE [dbo].[spCashNumbers4Collection_getCombo]
(
	@comp_id	As Int,
	@bra_id		As Int,
	@user_id	As int,
	@st_id		as int
)
as



BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


	set nocount on


-- ----------------------------------------------
-- Testing
-- ----------------------------------------------
	/*
	DECLARE		@comp_id	As Int,
				@bra_id		As Int,
				@user_id	As INT,
				@st_id		AS INT

	SELECT		@comp_id	= 1,
				@bra_id		= 1,
				@user_id	= 41,
				@st_id		= 3
	*/
-- ----------------------------------------------


	-- ---------------------------------------------------------------------------
	-- INserta cajas adicionales por condicion de venta para cobranza directa
	-- ---------------------------------------------------------------------------
	DECLARE @tblCashNumbersAdditionals AS TABLE(cn_id		 INT,
												cn_desc		 NVARCHAR(200),
												cn_order	 BIGINT)
	INSERT INTO @tblCashNumbersAdditionals(cn_id, cn_desc, cn_order)
	SELECT	tcn.cn_id,
			tcn.cn_desc,
			CASE	-- MOS 08-2020, ticket #10257,  deben estar las cajas que SON ALTERNATIVAS al FINAL
				WHEN ISNULL(tcn.cn_isAlternative4DirectCollection,'True') = 'True' THEN 9999999 + tcnbu.re_order
				ELSE																	8888888 + tcnbu.re_order
			END
			FROM tbCashNumbersBySalesTerms tcnbst
			INNER JOIN tbCashNumbers tcn
				ON	tcn.comp_id = tcnbst.comp_id	AND
					tcn.bra_id	= @bra_id			AND
					tcn.cn_id	= tcnbst.cn_id
			Inner Join tbCashNumber4Branch4User		tcnbu
				On	tcnbu.comp_id	=	tcn.comp_id	AND
					tcnbu.bra_id	=	tcn.bra_id	AND
					tcnbu.cn_id		=	tcn.cn_id	AND
					tcnbu.[user_id]	=	@user_id
			INNER JOIN  tbUsers4BranchFilter vubf			--MOS 09-2012
				ON	vubf.comp_id	= tcn.comp_id	AND
					vubf.bra_id		= tcn.bra_id	AND
					vubf.[user_id]	= @user_id
		WHERE	tcnbst.comp_id	= @comp_id	AND
				tcnbst.st_id	= @st_id	AND
				ISNULL(tcn.cn_disabled,'False') = 'False'

	-- ---------------------------------------------------------------------------


--==
--SELECT * FROM @tblCashNumbersAdditionals
--==


	-- ---------------------------------------------------------------------------
	-- Selecciona las cajas Normalmente
	-- ---------------------------------------------------------------------------
	select	DISTINCT
			cn.cn_id					[Id],
			cn.cn_desc					[desc],
			ISNULL(tcnbu.re_order,0)	[Order]

	from	dbo.tbCashNumbers						cn

			Inner Join tbCashNumber4Branch4User		tcnbu
			On			tcnbu.comp_id	=	cn.comp_id
				And		(tcnbu.bra_id	=	cn.bra_id OR @bra_id = -1)
				AND		tcnbu.cn_id		=	cn.cn_id
				And		tcnbu.[user_id]	=	@user_id

			INNER JOIN tbUsers4BranchFilter vubf			--MOS 09-2012
				ON		vubf.comp_id	= cn.comp_id
					AND vubf.bra_id		= cn.bra_id
					AND vubf.[user_id]	= @user_id

	WHERE	cn.comp_id		= @comp_id					AND
			cn.bra_id		= @bra_id					AND
			ISNULL(cn.cn_disabled,'False') = 'False'	AND
		   (
			(@st_id = -1 and  ISNULL(cn.cn_isAlternative4DirectCollection,'False') = 'False') -- Si no es cobranza directa que traiga las cajas que no son alternativas
				OR
			(@st_id <> -1)
		   )											AND
			cn.cn_id NOT IN (SELECT tmp.cn_id
								FROM @tblCashNumbersAdditionals tmp)		-- Todas las cajas que NO sean alternativas.



	UNION

	SELECT	tmp.cn_id		[Id],
			tmp.cn_desc		[desc],
			tmp.cn_order	[Order]

		FROM @tblCashNumbersAdditionals tmp

	ORDER BY [Order]



END
GO











CREATE PROCEDURE [dbo].[spCashNumbersGroup_getCombo]
(
	@comp_id				INT,
	@user_id				INT
)
as

BEGIN


-- --------------------------------------------------
-- Testing
-- --------------------------------------------------
	/*
	declare @comp_id			int

	select  @comp_id			= 1
	*/
-- --------------------------------------------------

	set nocount on


	IF EXISTS(
				SELECT TOP 1 1
					FROM tbCashNumbersGroupByUser tcngbu WITH (NOLOCK)
					WHERE	tcngbu.comp_id		= @comp_id	AND
							tcngbu.[user_id]	= @user_id	AND
							tcngbu.cngu_disabled= 'False'
				)
		BEGIN

			select	tcng.cng_id			[Id],
					tcng.cng_desc		[desc]
				from		dbo.tbCashNumbersGroup tcng		WITH (NOLOCK)
				INNER JOIN tbCashNumbersGroupByUser tcngbu	WITH (NOLOCK)
					ON	tcngbu.comp_id		= tcng.comp_id	AND
						tcngbu.cng_id		= tcng.cng_id	AND
						tcngbu.[user_id]	= @user_id
				where	tcng.comp_id			= @comp_id	AND
						tcngbu.cngu_disabled	= 'False'
				order BY	tcng.cng_desc

		END
	ELSE
		BEGIN

			select	tcng.cng_id			[Id],
					tcng.cng_desc		[desc]
				from		dbo.tbCashNumbersGroup tcng		WITH (NOLOCK)
				where		tcng.comp_id		= @comp_id
				order BY	tcng.cng_desc

		END


END

















GO











