CREATE PROCEDURE [dbo].[spCategory_getData]
(
	@comp_id			int
)
as
set nocount on


/*
DECLARE	@comp_id			INT
SELECT	@comp_id			= 1
*/


SELECT	tc.comp_id,
		tc.cat_id,
		tc.cat_desc,
		tc.cat_com,
		isnull(tc.cat_web,'false')			[cat_web],
		tc.bra_id,
		ta.acc_desc,
		tc.cat_image,
		tc.cat_commission,
		REPLACE(dbo.fnGetWordsCutByChar(
				CASE WHEN tc.cat_WebSite_desc IS NULL				 THEN tc.cat_desc
					 WHEN LEN(LTRIM(RTRIM(tc.cat_WebSite_desc))) = 0 THEN tc.cat_desc
					 ELSE tc.cat_WebSite_desc
				END
				,' ',15), '''', ' ')		[cat_WebSite_desc]


FROM tbCategory								tc   WITH (NOLOCK)

LEFT JOIN tbAccountant						ta   WITH (NOLOCK)
ON tc.comp_id			= ta.comp_id
AND tc.acc_count_id		= ta.acc_count_id

WHERE tc.comp_id = @comp_id

ORDER BY tc.cat_desc







GO










CREATE  PROCEDURE [dbo].[spCategory_getDataByItems]
(
	@comp_id				INT,
	@brand_id				INT,
	@pres_id				INT,
	@stor_id				INT,
	@showzerostock			BIT,
	@potentialstocklimit	INT,
	@ws_id					INT
)
as



BEGIN



	set nocount on

	-- ---------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------
	/*
	DECLARE @comp_id		INT,
			@brand_id       INT,
			@pres_id		INT,
			@stor_id		INT,
			@showzerostock	BIT,
			@potentialstocklimit int,
			@ws_id					INT
	SELECT 	@comp_id		=1,
			@brand_id       =-1,
			@pres_id        =-1,
			@stor_id		=1,
			@showzerostock	='true',
			@potentialstocklimit = 60,
			@ws_id			=24
	*/
	-- ---------------------------------------------------------------------


	--isnull(tc.cat_WebSite_desc,tc.cat_desc)
	SELECT	DISTINCT
			tc.cat_id,
			REPLACE(dbo.fnGetWordsCutByChar(
					CASE WHEN tc.cat_WebSite_desc IS NULL				 THEN tc.cat_desc
						 WHEN LEN(LTRIM(RTRIM(tc.cat_WebSite_desc))) = 0 THEN tc.cat_desc
						 ELSE tc.cat_WebSite_desc
					END
					,' ',20), '''', ' ')		[cat_desc],
			CASE WHEN tsc.comp_id IS NULL THEN 'false' ELSE 'true' END			[haveSubCat],
			isnull(tc.cat_web_order,999999999)									[cat_web_order]


	FROM    tbCategory										tc

			inner JOIN tbSubCategory						tsc
			ON		tsc.comp_id		= tc.comp_id
			AND		tsc.cat_id		= tc.cat_id


	WHERE 	tc.comp_id	=	@comp_id
	AND		isnull(tc.cat_web,'false')	= 'true'

	AND		tc.cat_id IN (SELECT	ti.cat_id
   								FROM	tbItem				ti
   								LEFT JOIN tbItemStorage tis
   									ON		tis.comp_id = ti.comp_id
   										AND tis.item_id = ti.item_id
   										AND tis.stor_id = @stor_id
   								--LEFT JOIN tbItemAssociation tia
   								--	ON		tia.comp_id = ti.comp_id
   								--		AND tia.item_id = ti.item_id

   								WHERE	ti.comp_id		= tsc.comp_id
								AND		ti.cat_id		= tsc.cat_id
								AND		ISNULL(ti.item_web,'false')			= 'true'
								AND		ISNULL(ti.item_disabled,'false')	= 'false'
								AND		ISNULL(ti.item_not4Sale,'false')	= 'false'
								--AND		tia.comp_id IS NULL

								AND		(
											(@showzerostock = 'true') OR
											(@showzerostock = 'false' AND tis.itst_cant > 0)
										)
								)

	AND		tc.cat_id NOT IN (SELECT	DISTINCT isnull(twscsd.cat_id, -1)
	   							FROM	tbWebSite_Cat_Subcat_Disabled twscsd
	   							WHERE	twscsd.comp_id	= tc.comp_id
								AND		twscsd.ws_id	= @ws_id
								AND		twscsd.subcat_id IS NULL)


	AND		tsc.subcat_id NOT IN (SELECT	DISTINCT isnull(twscsd.subcat_id, -1)
	   								FROM	tbWebSite_Cat_Subcat_Disabled twscsd
	   								WHERE	twscsd.comp_id = tsc.comp_id
									AND		twscsd.ws_id = @ws_id)


	ORDER BY	[cat_web_order],
				[cat_desc]

END
GO







create procedure [dbo].[spCategory_getDataByText]
(
	@text		VARCHAR(50),
	@count		INT
)
as
SET NOCOUNT ON


/*
DECLARE	@text		VARCHAR(50),
		@count		INT
SELECT	@text		= 'a',
		@count		= 10
*/


SELECT		TOP (@count)
			t.cat_desc,
			t.cat_image

FROM		tbCategory		t

WHERE		t.cat_desc		LIKE	@text + '%'

ORDER BY	t.cat_desc
GO






