CREATE Procedure [dbo].[spCategory_getReport]

		@comp_id		INT,
		@lang_id		INT,
		@page_id		INT,
		@bra_id			INT,
		@intBranch4Lang	INT
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@page_id		INT,
				@bra_id			INT
			SELECT
				@comp_id		=1,
				@lang_id		=2,
				@page_id		=10057,
				@bra_id			=-1
		*/
		--
		--DECLARE @fun_id INT
		--SET @fun_id = 1
		--
		SELECT
			tc.cat_id,
			tc.cat_desc,
			tc.cat_web,
			tc.cat_image,
			tc.cat_commission,
			tc.cat_commission_byReceive,
			tb.bra_desc
			FROM tbCategory							tc
				LEFT JOIN tbBranch					tb
					ON	tb.comp_id	= tc.comp_id	AND
						tb.bra_id	= tc.bra_id
			WHERE		tc.comp_id	= @comp_id
			ORDER BY 1

		EXEC [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	END
GO





