CREATE PROCEDURE [dbo].[spCategory_Process_Auto]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cat_desc					NVARCHAR(50),
	@cat_commission				DECIMAL(19,6),
	@cat_commission_byReceive	DECIMAL(19,6),
	@bra_id						INT,
	@acc_count_id				INT,
	@cat_web					BIT,
	@cat_isAvailable4FullJaus	BIT,
	@cat_web_order				INT,
	@cat_WebSite_desc			NVARCHAR(50),
	@catg_id					INT,
	@cat_WebSite_NOTE1			NVARCHAR(1000),
	@cat_WebSite_NOTE2			NVARCHAR(1000),
	@cat_originalCODE			NVARCHAR(20),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT


)
AS


---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT


SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id4session				= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,


	@bolIsOK					='True',
	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 1000

---------------------------------------------------------------------------------
*/
SET NOCOUNT ON
SET DATEFORMAT 'YMD'


BEGIN
	declare @return_value	INT

	if	@bra_id					= -1  SET @bra_id			= NULL
	if	@acc_count_id			= -1  SET @acc_count_id		= NULL
	if	@catg_id				= -1  SET @catg_id			= NULL


				BEGIN TRY



				INSERT INTO tbCategory
				(
					comp_id,
					cat_desc,
					cat_web,
					bra_id,
					acc_count_id,
					cat_commission,
					cat_commission_byReceive,
					cat_web_order,
					cat_WebSite_desc,
					catg_id,
					cat_WebSite_NOTE1,
					cat_WebSite_NOTE2,
					user_id4Insert,
					user_id4LastUpdate,
					user_LastUpdate,
					cat_isAvailable4FullJaus,
					cat_originalCODE
				)
				VALUES
				(
					@comp_id,
					@cat_desc,
					@cat_web,
					@bra_id,
					@acc_count_id,
					@cat_commission,
					@cat_commission_byReceive,
					@cat_web_order,
					@cat_WebSite_desc,
					@catg_id,
					@cat_WebSite_NOTE1,
					@cat_WebSite_NOTE2,
					@user_id,
					@user_id,
					GETDATE(),
					@cat_isAvailable4FullJaus,
					@cat_originalCODE
				)



			set	@return_value = IDENT_CURRENT('tbCategory')   -- @@identity

			END TRY
			BEGIN CATCH
				set	@return_value = 0
			END CATCH



END


















GO





