-- Date  : 03/10/19
-- Author: GA
-- Data  :Importacion de Categorias - Insert data - Validaciones
--------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spCategory_Process_Auto_Validate]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@acc_count_id				INT,
	@catg_id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@curr_id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT



SELECT
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@curr_id					INT,


	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------


set nocount on

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''


	-----------------------------------------------------------------------------------------------------------------
	--Sucursal
	-----------------------------------------------------------------------------------------------------------------
	if	@bra_id	<> -1
	BEGIN

	IF NOT EXISTS (SELECT tb.bra_id
	               FROM tbBranch tb		WITH (NOLOCK)
						WHERE   tb.comp_id			= @comp_id and
		               			tb.bra_id			= @bra_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Sucursal es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------
	--Cuenta Contable
	-----------------------------------------------------------------------------------------------------------------
	if	@acc_count_id	<> -1
	BEGIN
	IF NOT EXISTS (SELECT ta.acc_count_id
			        FROM tbAccountant ta		WITH (NOLOCK)
						WHERE   ta.comp_id			= @comp_id and
		               			ta.acc_count_id		= @acc_count_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Cuenta Contable es incorrecto'
			END
	END

	-----------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------
	--Grupo de Categorias
	-----------------------------------------------------------------------------------------------------------------
	if	@catg_id	<> -1
	BEGIN
	IF NOT EXISTS (SELECT tcg.catg_id
			        FROM tbCategoryGroup tcg		WITH (NOLOCK)
						WHERE   tcg.comp_id		= @comp_id and
		               			tcg.catg_id		= @catg_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Grupo de Categorías es incorrecto'
			END
	END


	-----------------------------------------------------------------------------------------------------------------




	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Fila],
				@errormessage	[Error],
				'True'			[Exists]
		END
	ELSE
		BEGIN

			--EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Fila],
				@errormessage	[Error],
				'False'			[Exists]
		END


END


















GO






