CREATE PROCEDURE [dbo].[spCheckBoard_Group_getComboByProfile]
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT
)

AS



	BEGIN


		SET NOCOUNT ON


		-- -------------------
		-- TESTING
		-- -------------------
		/*
		DECLARE
			@comp_id	INT,
			@prof_id	INT

		SELECT
			@comp_id	= 1,
			@prof_id	= 1
		*/
		-- -------------------


		SELECT DISTINCT
			tcbg.cbdg_id		[ID],
