CREATE PROCEDURE [dbo].[spCheckBoard_Indicators_getDataByFilters]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@cbdg_id			INT
)
AS





BEGIN

	SET NOCOUNT ON

-- -----------------------------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------------------------
/*
	declare 		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@prof_id			INT,
					@user_id			INT,
					@cbdg_id			INT


	select			@comp_id			= 1,
					@bra_id				= 1,
					@lang_id			= 2,
					@cbdg_id			= -1,
					@prof_id			= 1,
					@user_id			= 1
	*/
-- -----------------------------------------------------------------------------------


	-- Variables de Colores
	DECLARE
		@lRed		AS VARCHAR(10),
		@lYellow	AS VARCHAR(10),
		@lGreen		AS VARCHAR(10),
		@lBlue		AS VARCHAR(10)

	SET	@lRed		= '#FF0000'
	SET @lYellow	= '#FFFF00'
	SET @lGreen		= '#80FF00'
	SET @lBlue		= '#013ADF'


	SELECT DISTINCT 	tcbi.cbd_desc																					[Desc],
						CONVERT(VARCHAR,tcbi.cbd_id)								+ '-' +
						CONVERT(VARCHAR(10),ISNULL(tcbi.cbd_maxQtyOfDataInGrid,1))	+ '-' +
						(SELECT
							TOP 1

								CASE
									WHEN SUM(ISNULL(tcbqhd.cbdhd_valueDecimal1,0)) BETWEEN tcbi.cbd_rangeRedMin		AND tcbi.cbd_rangeRedMax	THEN @lRed
									WHEN SUM(ISNULL(tcbqhd.cbdhd_valueDecimal1,0)) BETWEEN tcbi.cbd_rangeYellowMin	AND tcbi.cbd_rangeYellowMax THEN @lYellow
									WHEN SUM(ISNULL(tcbqhd.cbdhd_valueDecimal1,0)) BETWEEN tcbi.cbd_rangeGreenMin	AND tcbi.cbd_rangeGreenMax	THEN @lGreen
									ELSE
		    							@lBlue
								END										[cbdhd_valueDecimal1]

						FROM tbCheckBoard_QueryHistoryHeader			tcbqhh				WITH (NOLOCK)
							INNER JOIN tbCheckBoard_QueryHistoryDetail	tcbqhd				WITH (NOLOCK)
							ON	tcbqhd.comp_id	= tcbqhh.comp_id		AND
								tcbqhd.cbdh_id	= tcbqhh.cbdh_id

							INNER JOIN tbCheckBoard_Indicator			tcbi				WITH (NOLOCK)
							ON	tcbi.comp_id	= tcbqhh.comp_id		AND
								tcbi.cbd_id		= tcbqhh.cbd_id

						WHERE	tcbqhh.comp_id	= @comp_id				AND
								tcbqhh.cbd_id	= tcbi.cbd_id

						GROUP BY	tcbqhh.cbdh_id,
									cbd_rangeRedMin,
									cbd_rangeRedMax,
									cbd_rangeYellowMin,
									cbd_rangeYellowMax,
									cbd_rangeGreenMin,
									cbd_rangeGreenMax

						ORDER BY tcbqhh.cbdh_id DESC
						)															+ '-' +
						CONVERT(VARCHAR,ISNULL(vcbqc.cbd_type,0))														[ID]


	FROM tbCheckBoard_GroupDetail						tcbgd				WITH (NOLOCK)

	INNER JOIN tbCheckBoard_Group						tcbg				WITH (NOLOCK)
	ON	tcbg.comp_id		= tcbgd.comp_id	AND
		tcbg.cbdg_id		= tcbgd.cbdg_id



	INNER JOIN tbCheckBoard_Indicator					tcbi				WITH (NOLOCK)
	ON  tcbi.comp_id		= tcbgd.comp_id AND
		tcbi.cbd_id			= tcbgd.cbd_id

	LEFT JOIN tbCheckBoard_Importance					tcbi2				WITH (NOLOCK)
	ON	tcbi2.comp_id		= tcbi.comp_id	AND
		tcbi2.cbdi_id		= tcbi.cbdi_id

	LEFT JOIN tbCheckBoard_Kind							tcbk				WITH (NOLOCK)
	ON	tcbk.comp_id		= tcbi.comp_id	AND
		tcbk.cbdk_id		= tcbi.cbdk_id

	INNER JOIN vwCheckBoard_queryCode					vcbqc				WITH (NOLOCK)
	ON	vcbqc.cbdc_id		= tcbi.cbdc_id	-- No por Compañia pls.!

	INNER JOIN tbsysOptionsValues						tov					WITH (NOLOCK)
	ON	tov.lang_id			= @lang_id		 AND
		tov.optval_id		= vcbqc.cbd_type AND
		tov.optval_class	= 323

	INNER JOIN tbCheckBoard_GroupByProfile tcbgbp
		ON	tcbgbp.comp_id	= @comp_id	AND
			tcbgbp.bra_id	= @bra_id	AND
			tcbgbp.prof_id	= @prof_id	AND
			tcbgbp.cbdg_id	= tcbg.cbdg_id


	Where	tcbgd.comp_id	= @comp_id										AND
	   	   (@cbdg_id		= -1			OR tcbg.cbdg_id	= @cbdg_id)		AND
	   		tcbgbp.cbdgp_disabled = 'False'


	ORDER BY tcbi.cbd_desc


END
GO





CREATE PROCEDURE [dbo].[spCheckBoard_IndicatorsOutOfRangeMailing]
(
	@comp_id		INT,
	@cbd_id			INT,		-- ID Indicador
	@cbdg_id		INT,		-- ID de Grupo de Indicadores
	@cbdo_id		INT,		-- ID de One Page Management
	@intCbds_id		INT			-- ID de Schedule de Calculo de Indicadores
)
AS


	BEGIN

		SET NOCOUNT ON
			-- -------------------
			-- Testing
			-- -------------------
			/*
				DECLARE
					@comp_id	INT,
					--@lang_id	INT,
					@cbd_id		INT,
					@cbdg_id	INT,
					@cbdo_id	INT,
					@intCbds_id INT

				SELECT
					@comp_id	= 1,
					--@lang_id	= 2,
					@cbd_id		= 1,
					@cbdg_id	= -1,
					@cbdo_id	= -1,
					@intCbds_id = 1
				--DROP TABLE #tmpUserEmails
				--DROP TABLE #tmpUserEmailsOPM
			*/
			-- -------------------




			-- -----------------------------------------
			-- Variables de Trabajo
			-- -----------------------------------------
				DECLARE
					@lDecTotal			DECIMAL(19,6),
					@lStrIndicatorName	NVARCHAR(MAX),
					@lang_id			INT,
					@lcellColor			VARCHAR(100),
					@lRed				VARCHAR(100),
					@lYellow			VARCHAR(100),
					@lGreen				VARCHAR(100),
					@lBlue				VARCHAR(100),
					@datCD				DATETIME,
					@user_id			INT

					SET	@lRed		= '#FC7272'			-- Rojo
					SET @lYellow	= '#FFFF9A'			-- Amarillo
					SET @lGreen		= '#D2FDA7'			-- Verde
					SET @lBlue		= '#98A3C7'			-- Azul
					SET @lcellColor = ''
				SET @lDecTotal			= -1
				SET @lStrIndicatorName	= ''

				DECLARE @tmpCheckBoard_QueryHistoryHeader TABLE(cbdh_id INT PRIMARY KEY)
			-- -----------------------------------------


			-- ----------------------------------------------------------------------------------
			-- INDICADOR INDIVIDUAL
			-- ----------------------------------------------------------------------------------
			--Obtenemos el Nombre del Indicador  y su TOTAL
			IF (@cbd_id <> -1)
				BEGIN
					SELECT
						@lStrIndicatorName = ISNULL(tcbi.cbd_desc,''),
						@lang_id		   = ISNULL(tcbi.lang_id,2)
					FROM tbCheckBoard_Indicator tcbi	WITH (NOLOCK)
					WHERE tcbi.cbd_id = @cbd_id




					-- -----------------------------------------------------------------
					-- Selecciono los ID de History ULTIMOS del indicador a informar
					-- -----------------------------------------------------------------
					INSERT INTO @tmpCheckBoard_QueryHistoryHeader
						SELECT  MAX(tcbqhh.cbdh_id)
							FROM tbCheckBoard_QueryHistoryHeader tcbqhh	WITH (NOLOCK)
							WHERE	tcbqhh.comp_id	= @comp_id AND
									tcbqhh.cbd_id	= @cbd_id
						--ORDER BY tcbqhh.cbdh_id DESC
					-- -----------------------------------------------------------------




					SELECT
						TOP 1
							@lcellColor =
								CASE
									WHEN SUM(ISNULL(tcbqhd.cbdhd_valueDecimal1,0)) BETWEEN tcbi.cbd_rangeGreenMin	AND tcbi.cbd_rangeGreenMax		THEN @lGreen
									WHEN SUM(ISNULL(tcbqhd.cbdhd_valueDecimal1,0)) BETWEEN tcbi.cbd_rangeYellowMin	AND tcbi.cbd_rangeYellowMax		THEN @lYellow
									WHEN SUM(ISNULL(tcbqhd.cbdhd_valueDecimal1,0)) BETWEEN tcbi.cbd_rangeRedMin	    AND tcbi.cbd_rangeRedMax		THEN @lRed
								ELSE																												     @lBlue
								END,
							@lDecTotal	= SUM(ISNULL(tcbqhd.cbdhd_valueDecimal1,0)) ,
							@datCD		= tcbqhh.cbdh_cd

						FROM tbCheckBoard_QueryHistoryHeader			tcbqhh			WITH (NOLOCK)

							INNER JOIN tbCheckBoard_QueryHistoryDetail	tcbqhd			WITH (NOLOCK)
							ON	tcbqhd.comp_id	= tcbqhh.comp_id		AND
								tcbqhd.cbdh_id	= tcbqhh.cbdh_id

							INNER JOIN tbCheckBoard_Indicator			tcbi			WITH (NOLOCK)
							ON	tcbi.comp_id	= tcbqhh.comp_id		AND
								tcbi.cbd_id		= tcbqhh.cbd_id

							INNER JOIN @tmpCheckBoard_QueryHistoryHeader tmp
								ON tmp.cbdh_id = tcbqhh.cbdh_id

						WHERE	tcbqhh.comp_id	= @comp_id				AND
								tcbqhh.cbd_id	= @cbd_id

						GROUP BY	tcbqhh.cbdh_id,
									tcbi.cbd_rangeGreenMax,
									tcbi.cbd_rangeGreenMin,
									tcbi.cbd_rangeYellowMax,
									tcbi.cbd_rangeYellowMin,
									tcbi.cbd_rangeRedMax,
									tcbi.cbd_rangeRedMin,
									tcbqhh.cbdh_cd

						ORDER BY tcbqhh.cbdh_id DESC

					DELETE FROM  @tmpCheckBoard_QueryHistoryHeader
					-- ----------------------------------------------------------------------------------
					-- Variables de Trabajo para el armado del MAIL
					DECLARE
						@lStringMailSubject			NVARCHAR(MAX),
						@lStringMailIndicatorText	NVARCHAR(MAX),
						@lStringMailIndicatorTotal	NVARCHAR(MAX)
					-- ----------------------------------------------------------------------------------

					SELECT @lStringMailSubject			= tut.utexts_desc
						FROM tbsysUniqueTexts tut		WITH (NOLOCK)
						WHERE tut.lang_id = @lang_id AND tut.utexts_id = 1007
					SELECT @lStringMailIndicatorText	= tut.utexts_desc
						FROM tbsysUniqueTexts tut		WITH (NOLOCK)
						WHERE tut.lang_id = @lang_id AND tut.utexts_id = 1005
					SELECT @lStringMailIndicatorTotal	= tut.utexts_desc
						FROM tbsysUniqueTexts tut		WITH (NOLOCK)
						WHERE tut.lang_id = @lang_id AND tut.utexts_id = 1006



					-- Lista de mails a los que se enviará
					DECLARE @lStringIndicatorMails AS NVARCHAR(MAX)
					SET		@lStringIndicatorMails = ''
					DECLARE @lStringIndicatorMailsCCo AS NVARCHAR(MAX)
					SET		@lStringIndicatorMailsCCo = ''
					DECLARE @lStringIndicatorMailsReplyTo AS NVARCHAR(MAX)
					SET		@lStringIndicatorMailsReplyTo = ''
					IF @intCbds_id IS NOT NULL
						BEGIN
							SELECT	@lStringIndicatorMails			= tcbs.cbds_mailTo,
									@lStringIndicatorMailsCCo		= tcbs.cbds_mailToCCo,
									@lStringIndicatorMailsReplyTo	= tcbs.cbds_mailFrom,
									@user_id						= tcbs.[user_id]
								FROM	tbCheckBoard_Schedule				tcbs	WITH (NOLOCK)
								WHERE	tcbs.comp_id = @comp_id		AND
										tcbs.cbds_id = @intCbds_id
						END
					   --@strEMailToAdditional   --"--==STL" FROM tbCheckBoard_Indicator tcbi WHERE tcbi.comp_id = @comp_id AND tcbi.cbd_id = @cbd_id


					--Nombre del Indicador y el Total que está fuera del rango
					SET @lStringMailIndicatorText	= /*+ @lStringMailIndicatorText	+ ' '*/ + @lStrIndicatorName
					SET @lStringMailIndicatorTotal  =  @lStringMailIndicatorTotal	+ ' ' + CONVERT(VARCHAR,Convert(decimal(19,2),@lDecTotal))

					DECLARE
						@MailTable				NVARCHAR(MAX),
						@MailEndTable			NVARCHAR(MAX),
						@Mailbody				NVARCHAR(MAX)


					SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black;border-radius:8px;cellpadding="3" cellspacing="5" border="6"  BORDERCOLOR="#666666" BORDERCOLORLIGHT="#8c8c8c" BORDERCOLORDARK="#404040">'


					SET @Mailbody = ''




					SET @MailBody =

						'
						<tr>
							<td   style="border-radius:4px;" align="left">' +
								isnull(@lStringMailIndicatorText,'*4') + ' # ' + CONVERT(VARCHAR(19), ISNULL(@datCD,GETDATE()-365)) + ' ' +
							'</td>
						</tr>
						</tr>
							<td   style="border-radius:4px;" align="right" bgcolor="' + @lcellColor + '">' +
								ISNULL(@lStringMailIndicatorTotal,'*5') + ' ' +
							'</td>
						</tr>'


					SET @MailEndTable	= + '</table>'

					SET @lStringMailSubject =	@lStringMailSubject + ' ' + @lStringMailIndicatorText
					SET @Mailbody			=	ISNULL(@MailTable,'') + ' ' +
												CASE
												    WHEN @lcellColor = '' THEN '* No hay datos calculados para la tabla tbCheckBoard_QueryHistoryDetail *'
												    ELSE @Mailbody
												END
												+
												ISNULL(@MailEndTable,'')


					exec spSystem_sendEMail
											@compId					= @comp_id,
											@precipients			= @lStringIndicatorMails ,
											@pcopy_recipients		= null,
											@psubject				= @lStringMailSubject,
											@pbody_format			= 'HTML',
											@pbody					= @Mailbody,
											@pfile_attachments		= null,
											@pReplyTo				= @lStringIndicatorMailsReplyTo,
											@pblind_copy_recipients	= @lStringIndicatorMailsCCo,
											@pUser_Id				= @user_id

----==
--SELECT @lStrIndicatorName, @lDecTotal, @lcellColor
----==

				END
			-- ----------------------------------------------------------------------------------









			-- ----------------------------------------------------------------------------------
			-- inicializa Cabecera y pie de mail
			-- ----------------------------------------------------------------------------------
			DECLARE @strMailHeader AS NVARCHAR(4000)
			DECLARE @strMailFooter AS NVARCHAR(4000)
			set		@strMailHeader = ''
			set		@strMailFooter = ''
			-- ----------------------------------------------------------------------------------





			-- ----------------------------------------------------------------------------------
			-- GRUPO DE INDICADORES
			-- Debe enviar el Nombre del Indicador y la Leyenda de la history con cada valor
			-- Con su color correspondiente
			-- ----------------------------------------------------------------------------------
			-- Obtenemos la lista de usuarios que recibiran el mail del Indicador fuera de Rango
			-- para SCHEDULE BY USER
			IF @cbdg_id	<> -1

				BEGIN



					SET @lang_id = (
									SELECT TOP 1  tcbi.lang_id
										FROM tbCheckBoard_Group tcbg					WITH (NOLOCK)
										INNER JOIN tbCheckBoard_GroupDetail tcbgd		WITH (NOLOCK)
											ON tcbgd.comp_id = tcbg.comp_id AND
										tcbgd.cbdg_id = tcbg.cbdg_id
										INNER JOIN tbCheckBoard_Indicator tcbi			WITH (NOLOCK)
											ON tcbi.cbd_id = tcbgd.cbd_id AND tcbi.comp_id = tcbgd.comp_id
									)





					DECLARE
						@lStringUserMailsSchedule	NVARCHAR(MAX)
					SET @lStringUserMailsSchedule	= ''
					DECLARE
						@lStringUserMailsScheduleReplyTo	NVARCHAR(MAX)
					SET @lStringUserMailsScheduleReplyTo	= ''

						SELECT DISTINCT
							tu.user_email
							INTO #tmpUserEmails
							FROM tbCheckBoard_Group										tcbg		WITH (NOLOCK)

								INNER JOIN tbCheckBoard_GroupDetail						tcbgd		WITH (NOLOCK)
								ON	tcbgd.comp_id		= tcbg.comp_id					AND
									tcbgd.cbdg_id		= tcbg.cbdg_id

								INNER JOIN tbCheckBoard_GroupMailSchedule				tcbgms		WITH (NOLOCK)
								ON	tcbgms.comp_id		= tcbg.comp_id					AND
									tcbgms.cbdg_id		= tcbg.cbdg_id

								INNER JOIN tbCheckBoard_GroupMailScheduleByUser			tcbgmsbu	WITH (NOLOCK)
								ON	tcbgmsbu.comp_id	= tcbgms.comp_id				AND
									tcbgmsbu.cbdgrs_id	= tcbgms.cbdgrs_id

								INNER JOIN tbUser										tu			WITH (NOLOCK)
								ON	tu.[user_id]		= tcbgmsbu.[user_id]

							WHERE	tcbg.comp_id		= @comp_id						AND
									tcbg.cbdg_id		= @cbdg_id						AND
									NOT tu.user_email	IS NULL



						--SELECT * FROM #tmpUserEmails

						WHILE (SELECT COUNT(*) FROM #tmpUserEmails ) > 0
						BEGIN
							SET @lStringUserMailsSchedule = @lStringUserMailsSchedule + ';' + (	SELECT TOP 1 tmp.user_email
																									FROM #tmpUserEmails tmp)
							DELETE FROM #tmpUserEmails
								WHERE user_email = (SELECT TOP 1 tmp.user_email
														FROM #tmpUserEmails tmp)
						END

						SELECT @lStringUserMailsScheduleReplyTo = tmp.cbdgrs_mailFrom
							FROM	tbCheckBoard_GroupMailSchedule tmp
							WHERE	tmp.comp_id		= @comp_id AND
									tmp.cbdgrs_id	= @intCbds_id
						--SELECT @lStringUserMailsSchedule



						-- -----------------------------------------------------------------
						-- Carga Footer y Header de Mail
						-- -----------------------------------------------------------------
						SELECT @strMailHeader = IsNull(tcbg.cbdg_mailHeader,''),
							   @strMailFooter = ISNULL(tcbg.cbdg_mailFooter,'')
						FROM tbCheckBoard_Group tcbg
						WHERE	tcbg.comp_id = @comp_id AND
								tcbg.cbdg_id = @cbdg_id
						-- -----------------------------------------------------------------


						--------------------------------------------------
						-- Variables de Trabajo del Cursor
						--------------------------------------------------
						DECLARE
							@lStringIndicatorDesc			VARCHAR(500),
							@lStringDetailDesc				NVARCHAR(MAX),
							@lStringDetailDesc2				NVARCHAR(MAX),
							@lStringIndicatorColor			VARCHAR(10),
							@lIntegerIndicatorOrder			INT,
							@lDTIndicatorLastExecute		DATETIME,
							@lDecimalIndicatorValue			DECIMAL(19,6),
							@lDecimalIndicatorValue2		DECIMAL(19,6),
							@lStringIndicatorTable			NVARCHAR(MAX),
							@lStringIndicatorBody			NVARCHAR(MAX),
							@lStringIndicatorTableEnd		NVARCHAR(MAX),
							@lStringIndicatorMailSubject	NVARCHAR(MAX)

						SET @lStringIndicatorTable		=	'<table style="font-family:Verdana;font-size:x-small;color:Black;border-radius:8px;cellpadding="3" cellspacing="5" border="6"  BORDERCOLOR="#666666" BORDERCOLORLIGHT="#8c8c8c" BORDERCOLORDARK="#404040">'
						SET @lStringIndicatorBody		=	''
						SET @lStringIndicatorTableEnd	=	'</table>'

						--------------------------------------------------




						-- -----------------------------------------------------------------
						-- Selecciono los ID de History ULTIMOS del GRUPO a Informar
						-- -----------------------------------------------------------------
						INSERT INTO @tmpCheckBoard_QueryHistoryHeader
							SELECT MAX(hh.cbdh_id)
								FROM tbCheckBoard_QueryHistoryHeader hh
								INNER JOIN tbCheckBoard_GroupDetail gd
									ON	gd.comp_id = hh.comp_id	AND
										gd.cbd_id  = hh.cbd_id


							WHERE	hh.comp_id	= @comp_id		AND
									gd.comp_id  = @comp_id		AND
									gd.cbdg_id	= @cbdg_id
							GROUP BY hh.cbd_id
						-- -----------------------------------------------------------------


						DECLARE cursor_Indicators	CURSOR LOCAL FAST_FORWARD FOR

									SELECT

										tcbi.cbd_desc																													[Desc],
										CASE
											WHEN ISNULL(tcbqhd.cbdhd_valueDecimal1,0) BETWEEN tcbi.cbd_rangeRedMin		AND tcbi.cbd_rangeRedMax		THEN @lRed
											WHEN ISNULL(tcbqhd.cbdhd_valueDecimal1,0) BETWEEN tcbi.cbd_rangeYellowMin	AND tcbi.cbd_rangeYellowMax		THEN @lYellow
											WHEN ISNULL(tcbqhd.cbdhd_valueDecimal1,0) BETWEEN tcbi.cbd_rangeGreenMin	AND tcbi.cbd_rangeGreenMax		THEN @lGreen
											ELSE																											 @lBlue
										END																																[Color],
										Round(tcbqhd.cbdhd_valueDecimal1,CASE
										                                     WHEN tcbi.cbd_DecimalPlaces1 >= 0 AND tcbi.cbd_DecimalPlaces1 <= 4  THEN tcbi.cbd_DecimalPlaces1
										                                     ELSE	2
										                                 END
											)																															[cbdhd_valueDecimal1],
										CASE
											WHEN ISNULL(tcbqhd.cbdhd_valueDecimal1,0) BETWEEN tcbi.cbd_rangeRedMin		AND tcbi.cbd_rangeRedMax	THEN 1
											WHEN ISNULL(tcbqhd.cbdhd_valueDecimal1,0) BETWEEN tcbi.cbd_rangeYellowMin	AND tcbi.cbd_rangeYellowMax THEN 2
											WHEN ISNULL(tcbqhd.cbdhd_valueDecimal1,0) BETWEEN tcbi.cbd_rangeGreenMin	AND tcbi.cbd_rangeGreenMax	THEN 3
											ELSE																										 4
										END																																[Order],
										tcbqhh.cbdh_cd	,
										ISNULL(tcbqhd.cbdhd_valueText1,''),
										Round(tcbqhd.cbdhd_valueDecimal2,CASE
										                                     WHEN tcbi.cbd_DecimalPlaces2 >= 0 AND tcbi.cbd_DecimalPlaces2 <= 4  THEN tcbi.cbd_DecimalPlaces2
										                                     ELSE	2
										                                 END
											)																															[cbdhd_valueDecimal2],
										ISNULL(tcbqhd.cbdhd_valueText2,'')



									FROM tbCheckBoard_QueryHistoryHeader			tcbqhh		WITH (NOLOCK)

										INNER JOIN @tmpCheckBoard_QueryHistoryHeader tmp
											ON tmp.cbdh_id = tcbqhh.cbdh_id

										INNER JOIN tbCheckBoard_QueryHistoryDetail	tcbqhd		WITH (NOLOCK)
										ON	tcbqhd.comp_id	= tcbqhh.comp_id		AND
											tcbqhd.cbdh_id	= tcbqhh.cbdh_id

										INNER JOIN tbCheckBoard_Indicator			tcbi		WITH (NOLOCK)
										ON	tcbi.comp_id	= tcbqhh.comp_id		AND
											tcbi.cbd_id		= tcbqhh.cbd_id

										INNER JOIN tbCheckBoard_GroupDetail tcbgd
											ON	tcbgd.comp_id = @comp_id AND
												tcbgd.cbdg_id = @cbdg_id AND
												tcbgd.cbd_id  = tcbqhh.cbd_id

										INNER JOIN tbCheckBoard_Group tcbg
											ON	tcbg.comp_id = tcbgd.comp_id AND
												tcbg.cbdg_id = tcbgd.cbdg_id AND
												tcbg.cbdg_mailDisabled = 'False'

									WHERE	tcbqhh.comp_id	= @comp_id				AND
											tcbqhh.cbd_id	= tcbi.cbd_id
									ORDER BY [Order]





						OPEN cursor_Indicators
						FETCH NEXT FROM cursor_Indicators
						INTO
							@lStringIndicatorDesc,
							@lStringIndicatorColor,
							@lDecimalIndicatorValue,
							@lIntegerIndicatorOrder,
							@lDTIndicatorLastExecute,
							@lStringDetailDesc,
							@lDecimalIndicatorValue2,
							@lStringDetailDesc2

						WHILE @@FETCH_STATUS <> -1

							BEGIN

								BEGIN TRY




									SET @lStringIndicatorBody = @lStringIndicatorBody + '<tr>
																							<td   style="border-radius:4px;" align="left">' +
																								@lStringIndicatorDesc + ' ' +
																							'</td>
																							<td   style="border-radius:4px;" align="right" bgcolor="' + @lStringIndicatorColor + '">' +
																								CONVERT(VARCHAR,@lDecimalIndicatorValue)	+ ' ' +
																							'</td>' +
																							'<td   style="border-radius:4px;" align="left" bgcolor="' + @lStringIndicatorColor + '">' +
																								@lStringDetailDesc + ' ' +
																							'</td>' +
																							'<td   style="border-radius:4px;" align="center">' +
																								CONVERT(VARCHAR,@lDTIndicatorLastExecute) + ' ' +
																							'</td>' +
																							'<td   style="border-radius:4px;" align="right" bgcolor="' + @lStringIndicatorColor + '">' +
																								CONVERT(VARCHAR,@lDecimalIndicatorValue2)	+ ' ' +
																							'</td>' +
																							'<td   style="border-radius:4px;" align="left" bgcolor="' + @lStringIndicatorColor + '">' +
																								@lStringDetailDesc2 + ' ' +
																							'</td>' +

																						'</tr>'



								END TRY
								BEGIN CATCH
								END CATCH

								FETCH NEXT FROM cursor_Indicators
								INTO
									@lStringIndicatorDesc,
									@lStringIndicatorColor,
									@lDecimalIndicatorValue,
									@lIntegerIndicatorOrder,
									@lDTIndicatorLastExecute,
									@lStringDetailDesc,
									@lDecimalIndicatorValue2,
									@lStringDetailDesc2


							END

					Close cursor_Indicators
					Deallocate cursor_Indicators

					BEGIN TRY
						SET @lStringIndicatorBody = dbo.fnSystem_sendEMail_SetBody2HTML(@strMailHeader) +
													@lStringIndicatorTable								+
													@lStringIndicatorBody								+
													@lStringIndicatorTableEnd							+
													dbo.fnSystem_sendEMail_SetBody2HTML(@strMailFooter )
					END TRY
					BEGIN CATCH
					END CATCH

					DECLARE @MailIndicatorsSubject NVARCHAR(MAX)

					SELECT @lStringIndicatorMailSubject	= tut.utexts_desc
						FROM tbsysUniqueTexts tut
						WHERE	tut.lang_id		= @lang_id AND
								tut.utexts_id	= 1008

					SET @lStringIndicatorMailSubject	= @lStringIndicatorMailSubject + ' ' + (SELECT ISNULL(tcbg.cbdg_desc,'')
						                       														FROM tbCheckBoard_Group tcbg
						                       														WHERE tcbg.comp_id = @comp_id AND
						                       																tcbg.cbdg_id = @cbdg_id)


--==
--SELECT @lStringUserMailsSchedule,@lStringUserMailsScheduleReplyTo
--==

					exec spSystem_sendEMail
											@compId					= @comp_id,
											@precipients			= @lStringUserMailsSchedule ,
											@pcopy_recipients		= null,
											@psubject				= @lStringIndicatorMailSubject,
											@pbody_format			= 'HTML',
											@pbody					= @lStringIndicatorBody,
											@pfile_attachments		= null,
											@pReplyTo				= @lStringUserMailsScheduleReplyTo,
											@pblind_copy_recipients	= '',
											@pUser_Id				= NULL

				END
			-- ----------------------------------------------------------------------------------











			-- ----------------------------------------------------------------------------------
			-- ONE PAGE MANAGEMEMNT
			-- Debe enviar el Nombre del Indicador y la Leyenda de la history con cada valor
			-- Con su color correspondiente
			-- ----------------------------------------------------------------------------------
			-- Obtenemos la lista de usuarios que recibiran el mail del Indicador fuera de Rango
			-- para ONE PAGE MANAGEMENT SCHEDULE BY USER

			IF @cbdo_id <> -1
				BEGIN

					SET @lang_id = (
									SELECT TOP 1 tcbi.lang_id
										FROM tbCheckBoard_OnePageManagementGroups tcbopmg										WITH (NOLOCK)
										INNER JOIN tbCheckBoard_OnePageManagementGroupsDetail tcbopmgd							WITH (NOLOCK)
											ON tcbopmgd.comp_id = tcbopmg.comp_id AND tcbopmgd.cbdo_id = tcbopmg.cbdo_id
										INNER JOIN tbCheckBoard_Indicator tcbi													WITH (NOLOCK)
											ON tcbi.comp_id = tcbopmgd.comp_id AND tcbi.cbd_id = tcbopmgd.cbd_id
								   )


					DECLARE
						@lStringUserOPMMailsSchedule	NVARCHAR(MAX)
					SET @lStringUserOPMMailsSchedule	= ''
					DECLARE
						@lStringUserOPMMailsScheduleReplyTo	NVARCHAR(MAX)
					SET @lStringUserOPMMailsScheduleReplyTo	= ''


					SELECT @lStringUserMailsScheduleReplyTo = tmp.cbdos_mailFrom
						FROM tbCheckBoard_OnePageManagementMailSchedule  tmp					WITH (NOLOCK)
							WHERE	tmp.comp_id		= @comp_id AND
									tmp.cbdos_id	= @intCbds_id

					SELECT
						tu.user_email
					INTO #tmpUserEmailsOPM
					FROM tbCheckBoard_OnePageManagementGroups						tcbopmg		WITH (NOLOCK)

						INNER JOIN tbCheckBoard_OnePageManagementGroupsDetail		tcbopmgd	WITH (NOLOCK)
						ON	tcbopmgd.comp_id	= tcbopmg.comp_id					AND
							tcbopmgd.cbdo_id	= tcbopmg.cbdo_id

						INNER JOIN tbCheckBoard_OnePageManagementMailSchedule		tcbopmms	WITH (NOLOCK)
						ON	tcbopmms.cbdo_id	= tcbopmg.cbdo_id					AND
							tcbopmms.comp_id	= tcbopmg.comp_id

						INNER JOIN tbCheckBoard_OnePageManagementMailScheduleByUser tcbopmmsbu	WITH (NOLOCK)
						ON	tcbopmmsbu.comp_id	= tcbopmms.comp_id					AND
							tcbopmmsbu.cbdos_id = tcbopmms.cbdos_id

						INNER JOIN tbUser											tu			WITH (NOLOCK)
						ON	tu.[user_id]		= tcbopmmsbu.[user_id]


					WHERE	tcbopmg.comp_id		= @cbdo_id							AND
							tcbopmg.cbdo_id		= @cbdo_id							AND
							NOT tu.user_email	IS NULL

--==
--SELECT * FROM #tmpUserEmailsOPM
--==
					WHILE (SELECT COUNT(*) FROM #tmpUserEmailsOPM ) > 0
						BEGIN
							SET @lStringUserOPMMailsSchedule = @lStringUserOPMMailsSchedule + ';' + (SELECT TOP 1 tmp.user_email FROM #tmpUserEmailsOPM tmp)
							DELETE FROM #tmpUserEmailsOPM  WHERE user_email = (SELECT TOP 1 tmp.user_email FROM #tmpUserEmailsOPM tmp)
						END

--SELECT @lStringUserOPMMailsSchedule
--SET @lStringUserOPMMailsSchedule  = 'saraccomartin@yahoo.com.ar'


						-- -----------------------------------------------------------------
						-- Carga Footer y Header de Mail
						-- -----------------------------------------------------------------
						SELECT @strMailHeader = IsNull(tcbg.cbdo_mailHeader,''),
							   @strMailFooter = ISNULL(tcbg.cbdo_mailFooter,'')
						FROM tbCheckBoard_OnePageManagementGroups  tcbg
						WHERE	tcbg.comp_id = @comp_id AND
								tcbg.cbdo_id = @cbdo_id
						-- -----------------------------------------------------------------


						--------------------------------------------------
						-- Variables de Trabajo del Cursor
						--------------------------------------------------
						DECLARE
							@lStringIndicatorOPMDesc		VARCHAR(500),
							@lStringIndicatorOPMColor		VARCHAR(10),
							@lIntegerIndicatorOPMOrder		INT,
							@lDTIndicatorOPMLastExecute		DATETIME,
							@lDTIndicatorOPMvalueText1		NVARCHAR(MAX),
							@lDTIndicatorOPMvalueText2		NVARCHAR(MAX),
							@lDecimalIndicatorOPMValue		DECIMAL(19,6),
							@lDecimalIndicatorOPMValue2		DECIMAL(19,6),
							@lStringIndicatorOPMTable		NVARCHAR(MAX),
							@lStringIndicatorOPMBody		NVARCHAR(MAX),
							@lStringIndicatorOPMTableEnd	NVARCHAR(MAX),
							@lStringIndicatorOPMMailSubject	NVARCHAR(500)

						SET @lStringIndicatorOPMTable		=	'<table style="font-family:Verdana;font-size:x-small;color:Black;border-radius:8px;cellpadding="3" cellspacing="5" border="6"  BORDERCOLOR="#666666" BORDERCOLORLIGHT="#8c8c8c" BORDERCOLORDARK="#404040">'
						SET @lStringIndicatorOPMBody		=	''
						SET @lStringIndicatorOPMTableEnd	=	'</table>'

						--------------------------------------------------


						-- -----------------------------------------------------------------
						-- Selecciono los ID de History ULTIMOS del OPM a Informar
						-- -----------------------------------------------------------------
						INSERT INTO @tmpCheckBoard_QueryHistoryHeader
							SELECT MAX(hh.cbdh_id)
								FROM tbCheckBoard_QueryHistoryHeader hh							WITH (NOLOCK)
								INNER JOIN tbCheckBoard_OnePageManagementGroupsDetail gd		WITH (NOLOCK)
									ON	gd.comp_id  = hh.comp_id	AND
										gd.cbd_id   = hh.cbd_id
							WHERE	hh.comp_id	= @comp_id		AND
									gd.comp_id  = @comp_id		AND
									gd.cbdo_id	= @cbdo_id
							GROUP BY hh.cbd_id
						-- -----------------------------------------------------------------


						DECLARE cursor_IndicatorsOPM	CURSOR LOCAL FAST_FORWARD FOR


								SELECT

										tgh.cbdo_desc																													[Desc],
										CASE
											WHEN (ISNULL(tcbqhd.cbdhd_valueDecimal1,0)) BETWEEN tcbi.cbd_rangeRedMin	AND tcbi.cbd_rangeRedMax	THEN @lRed
											WHEN (ISNULL(tcbqhd.cbdhd_valueDecimal1,0)) BETWEEN tcbi.cbd_rangeYellowMin	AND tcbi.cbd_rangeYellowMax THEN @lYellow
											WHEN (ISNULL(tcbqhd.cbdhd_valueDecimal1,0)) BETWEEN tcbi.cbd_rangeGreenMin	AND tcbi.cbd_rangeGreenMax	THEN @lGreen
										ELSE																											 @lBlue
										END																																[Color],
										Round(ISNULL(tcbqhd.cbdhd_valueDecimal1,0),CASE
										                                               WHEN tcbi.cbd_DecimalPlaces1 >= 0 AND tcbi.cbd_DecimalPlaces1 <= 4  THEN tcbi.cbd_DecimalPlaces1
										                                               ELSE 2
										                                           END
											 )																															[cbdhd_valueDecimal1],
										tcbqhh.cbdh_cd,
										ISNULL(tcbqhd.cbdhd_valueText1,''),
										tcbi.cbd_desc,
										Round(ISNULL(tcbqhd.cbdhd_valueDecimal2,0),CASE
										                                               WHEN tcbi.cbd_DecimalPlaces2 >= 0 AND tcbi.cbd_DecimalPlaces2 <= 4  THEN tcbi.cbd_DecimalPlaces2
										                                               ELSE 2
										                                           END
											 )																															[cbdhd_valueDecimal2],
										ISNULL(tcbqhd.cbdhd_valueText2,'')


									FROM tbCheckBoard_QueryHistoryHeader			tcbqhh				WITH (NOLOCK)

										INNER JOIN @tmpCheckBoard_QueryHistoryHeader tmp
											ON tmp.cbdh_id = tcbqhh.cbdh_id

										INNER JOIN tbCheckBoard_QueryHistoryDetail	tcbqhd				WITH (NOLOCK)
										ON	tcbqhd.comp_id	= tcbqhh.comp_id		AND
											tcbqhd.cbdh_id	= tcbqhh.cbdh_id

										INNER JOIN tbCheckBoard_Indicator			tcbi				WITH (NOLOCK)
										ON	tcbi.comp_id	= tcbqhh.comp_id		AND
											tcbi.cbd_id		= tcbqhh.cbd_id

										INNER JOIN tbCheckBoard_OnePageManagementGroupsDetail tgd		WITH (NOLOCK)
											ON	tgd.comp_id = @comp_id AND
												tgd.cbdo_id = @cbdo_id AND
												tgd.cbd_id	= tcbqhh.cbd_id

										INNER JOIN tbCheckBoard_OnePageManagementGroups tgh				WITH (NOLOCK)
											ON	tgh.comp_id = tgd.comp_id AND
												tgh.cbdo_id = tgd.cbdo_id AND
												tgh.cbdo_disabled = 'False'

									WHERE	tcbqhh.comp_id	= @comp_id				AND
											tcbqhh.cbd_id	= tcbi.cbd_id



									ORDER BY tgd.cbdo_order







						OPEN cursor_IndicatorsOPM
						FETCH NEXT FROM cursor_IndicatorsOPM
						INTO
							@lStringIndicatorOPMDesc,
							@lStringIndicatorOPMColor,
							@lDecimalIndicatorOPMValue,
							@lDTIndicatorOPMLastExecute,
							@lDTIndicatorOPMvalueText1,
							@lStringIndicatorDesc,
							@lDecimalIndicatorOPMValue2,
							@lDTIndicatorOPMvalueText2

						WHILE @@FETCH_STATUS <> -1

							BEGIN

								BEGIN TRY




									SET @lStringIndicatorOPMBody = @lStringIndicatorOPMBody + '<tr>
																							<td   style="border-radius:4px;" align="left">' +
																								@lStringIndicatorDesc + ' ' +
																							'</td>
																							<td   style="border-radius:4px;" align="right" bgcolor="' + @lStringIndicatorOPMColor + '">' +
																								CONVERT(VARCHAR,@lDecimalIndicatorOPMValue)	+ ' ' +
																							'</td>' +
																							'<td   style="border-radius:4px;" align="left" bgcolor="' + @lStringIndicatorOPMColor + '">' +
																								@lDTIndicatorOPMvalueText1 + ' ' +
																							'</td>' +
																							'<td   style="border-radius:4px;" align="center">' +
																								CONVERT(VARCHAR,@lDTIndicatorOPMLastExecute) + ' ' +
																							'</td>' +
																							'<td   style="border-radius:4px;" align="right" bgcolor="' + @lStringIndicatorOPMColor + '">' +
																								CONVERT(VARCHAR,@lDecimalIndicatorOPMValue2)	+ ' ' +
																							'</td>' +
																							'<td   style="border-radius:4px;" align="left" bgcolor="' + @lStringIndicatorOPMColor + '">' +
																								@lDTIndicatorOPMvalueText2 + ' ' +
																							'</td>' +

																						'</tr>'


--									SET @lStringIndicatorOPMBody = @lStringIndicatorOPMBody + '<tr>' +
----																							<td align="center">' +
----																								@lStringIndicatorOPMDesc + ' ' +
----																							'</td>' +
--																							'<td align="center">' +
--																								@lStringIndicatorDesc + ' ' +
--																							'</td>
--																							<td align="center" bgcolor="' + @lStringIndicatorOPMColor + '">' +
--																								CONVERT(VARCHAR,@lDecimalIndicatorOPMValue)	+ ' ' +
--																							'</td>
--																							<td align="center">' +
--																								CONVERT(VARCHAR,@lDTIndicatorOPMLastExecute) + ' ' +
--																							'</td>' +
--																							'<td align="center">' +
--																								@lDTIndicatorOPMvalueText1 + ' ' +
--																							'</td>
--																						</tr>'




									FETCH NEXT FROM cursor_IndicatorsOPM
									INTO
										@lStringIndicatorOPMDesc,
										@lStringIndicatorOPMColor,
										@lDecimalIndicatorOPMValue,
										@lDTIndicatorOPMLastExecute,
										@lDTIndicatorOPMvalueText1,
										@lStringIndicatorDesc,
										@lDecimalIndicatorOPMValue2,
										@lDTIndicatorOPMvalueText2



								END TRY
								BEGIN CATCH
								END CATCH

							END

					CLOSE		cursor_IndicatorsOPM
					DEALLOCATE	cursor_IndicatorsOPM

						BEGIN TRY
							SET @lStringIndicatorOPMBody =	dbo.fnSystem_sendEMail_SetBody2HTML(@strMailHeader) +
															@lStringIndicatorOPMTable							+
															@lStringIndicatorOPMBody							+
															@lStringIndicatorOPMTableEnd						+
															dbo.fnSystem_sendEMail_SetBody2HTML(@strMailFooter )
						END TRY
						BEGIN CATCH
						END CATCH

						SELECT @lStringIndicatorOPMMailSubject	= tut.utexts_desc
							FROM tbsysUniqueTexts tut				WITH (NOLOCK)
							WHERE	tut.lang_id		= @lang_id AND
									tut.utexts_id	= 1009

						SET @lStringIndicatorOPMMailSubject		= @lStringIndicatorOPMMailSubject + ' ' + (SELECT ISNULL(tcbopmg.cbdo_desc,'')
						                                   													FROM tbCheckBoard_OnePageManagementGroups tcbopmg
						                       																WHERE tcbopmg.comp_id = @comp_id AND
						                       																	  tcbopmg.cbdo_id = @cbdo_id)


					exec spSystem_sendEMail
											@compId					= @comp_id,
											@precipients			= @lStringUserOPMMailsSchedule ,
											@pcopy_recipients		= null,
											@psubject				= @lStringIndicatorOPMMailSubject,
											@pbody_format			= 'HTML',
											@pbody					= @lStringIndicatorOPMBody,
											@pfile_attachments		= null,
											@pReplyTo				= @lStringUserMailsScheduleReplyTo,
											@pblind_copy_recipients	= '',
											@pUser_Id				= NULL


				END

	END
GO






