CREATE PROCEDURE [dbo].[spCheckBoard_queryCodeExec]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@cbd_id		INT,
	@top		INT,
	@date_from	DATETIME,
	@date_to	DATETIME
)

AS



	BEGIN

		SET NOCOUNT ON


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------

		SET DATEFORMAT 'ymd'

		-- ---------------------
		-- Testing
		-- ---------------------
			/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT,
				@cbd_id		INT,
				@top		INT,
				@date_from	DATETIME,
				@date_to	DATETIME
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@prof_id	= 1,
				@user_id	= 41,
				@cbd_id		= 3,
				@top		= 15,
				@date_from	= CONVERT(DATETIME,'2014-11-01'),
				@date_to	= CONVERT(DATETIME,'2014-12-31')
			*/
		-- ---------------------


		SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from,'False')
		SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to  ,'True')

		-- -------------------------------------------------------------------------------------
		--  Si es un indicador de valores MULTIPLES solo trae el ultimo indicador calculado.
		--  Sino respeta el valor que pide desde el SP
		-- -------------------------------------------------------------------------------------
		SET		@top = 0
		SELECT	@top =	CASE
		             	    WHEN vcbqc.cbd_type = 1 THEN  ISNULL(tcbi.cbd_maxQtyOfDataInGrid,1)
		             	    ELSE						  1  -- Si es de valores multiples solo retorna el Ultimo
		             	END
          	FROM tbCheckBoard_Indicator tcbi
          	INNER JOIN vwCheckBoard_queryCode vcbqc
          		ON vcbqc.cbdc_id = tcbi.cbdc_id
          	WHERE	tcbi.comp_id	= @comp_id	AND
          			tcbi.cbd_id		= @cbd_id

		DECLARE @intcbd_type AS INT
		SET @intcbd_type = 0
		SELECT @intcbd_type = tcbqc.cbd_type
			FROM tbCheckBoard_Indicator tcbi
			INNER JOIN tbCheckBoard_queryCode tcbqc
				ON	tcbqc.comp_id = tcbi.comp_id AND
					tcbqc.cbdc_id = tcbi.cbdc_id
			WHERE	tcbi.comp_id  = @comp_id AND
					tcbi.cbd_id   = @cbd_id

		IF @top = 0 OR @intcbd_type = 2
			BEGIN
				SET @top = 1
			END
		-- -------------------------------------------------------------------------------------




		DECLARE @tblQueryHistoryHeader TABLE (comp_id INT, cbdh_id INT, cbd_id	INT, Reference INT IDENTITY(1,1))

		INSERT INTO @tblQueryHistoryHeader
											(
											 comp_id,
											 cbdh_id,
											 cbd_id
											)
											SELECT
												TOP (@top)
													tcbqhh.comp_id,
													tcbqhh.cbdh_id,
													tcbqhh.cbd_id
												FROM tbCheckBoard_QueryHistoryHeader	tcbqhh
												WHERE	tcbqhh.comp_id	= @comp_id		AND
														tcbqhh.cbd_id	= @cbd_id		AND
														tcbqhh.cbdh_cd BETWEEN @date_from AND @date_to
												ORDER BY tcbqhh.cbdh_id DESC



		SELECT
			ISNULL(tcbqhd.cbdhd_valueText1,'')								[cbdhd_valueText1],
			CASE
			    WHEN tcbi.cbd_DecimalPlaces1 = 0 THEN convert(decimal(25,0),ROUND( tcbqhd.cbdhd_valueDecimal1,tcbi.cbd_DecimalPlaces1))
			    WHEN tcbi.cbd_DecimalPlaces1 = 1 THEN convert(decimal(25,1),ROUND( tcbqhd.cbdhd_valueDecimal1,tcbi.cbd_DecimalPlaces1))
			    WHEN tcbi.cbd_DecimalPlaces1 = 2 THEN convert(decimal(25,2),ROUND( tcbqhd.cbdhd_valueDecimal1,tcbi.cbd_DecimalPlaces1))
			    WHEN tcbi.cbd_DecimalPlaces1 = 3 THEN convert(decimal(25,3),ROUND( tcbqhd.cbdhd_valueDecimal1,tcbi.cbd_DecimalPlaces1))
			    WHEN tcbi.cbd_DecimalPlaces1 = 4 THEN convert(decimal(25,4),ROUND( tcbqhd.cbdhd_valueDecimal1,tcbi.cbd_DecimalPlaces1))
			    ELSE								  convert(decimal(25,2),ROUND( tcbqhd.cbdhd_valueDecimal1,2))
			END																[cbdhd_valueDecimal1],
			tcbqhd.cbdhd_valueDate1,
			ISNULL(tcbqhd.cbdhd_valueText2,'')								[cbdhd_valueText2],
			CASE
			    WHEN tcbi.cbd_DecimalPlaces2 = 00 THEN convert(decimal(25,0),ROUND( tcbqhd.cbdhd_valueDecimal2,tcbi.cbd_DecimalPlaces2))
			    WHEN tcbi.cbd_DecimalPlaces2 = 01 THEN convert(decimal(25,1),ROUND( tcbqhd.cbdhd_valueDecimal2,tcbi.cbd_DecimalPlaces2))
			    WHEN tcbi.cbd_DecimalPlaces2 = 02 THEN convert(decimal(25,2),ROUND( tcbqhd.cbdhd_valueDecimal2,tcbi.cbd_DecimalPlaces2))
			    WHEN tcbi.cbd_DecimalPlaces2 = 03 THEN convert(decimal(25,3),ROUND( tcbqhd.cbdhd_valueDecimal2,tcbi.cbd_DecimalPlaces2))
			    WHEN tcbi.cbd_DecimalPlaces2 = 04 THEN convert(decimal(25,4),ROUND( tcbqhd.cbdhd_valueDecimal2,tcbi.cbd_DecimalPlaces2))
			    ELSE														 ROUND( tcbqhd.cbdhd_valueDecimal1,2)
			END																[cbdhd_valueDecimal2],
			tcbqhd.cbdhd_valueDate2,
			tcbi.cbd_image,
			ROW_NUMBER() OVER (ORDER BY tcbqhd.cbdh_id DESC) AS 			[Reference]	,
			tcbqhh.cbdh_cd													[DateOfCalculation],
			ISNULL(tcbi.cbd_boardDesc,'')									[cbd_boardDesc],
			CONVERT(NVARCHAR(500),'No Set')									[cpo_desc],
			convert(decimal(25,4),0.0)										[cpo_value],
			CONVERT(BIT,'False')											[cpo_WithValue]
			INTO #tmpTable
			FROM tbCheckBoard_QueryHistoryDetail		tcbqhd

				INNER JOIN tbCheckBoard_QueryHistoryHeader tcbqhh
					ON	tcbqhh.comp_id = tcbqhd.comp_id AND
						tcbqhh.cbdh_id = tcbqhd.cbdh_id

				INNER JOIN @tblQueryHistoryHeader		tbl
				ON	tbl.comp_id		= tcbqhd.comp_id	AND
					tbl.cbdh_id		= tcbqhd.cbdh_id

				INNER JOIN tbCheckBoard_Indicator		tcbi
				ON	tcbi.comp_id	= tbl.comp_id		AND
					tcbi.cbd_id		= tbl.cbd_id

				LEFT JOIN tbUsers4BranchFilter tubf
					ON tubf.comp_id		= tcbqhd.comp_id	AND
					   tubf.bra_id		= tcbqhd.bra_id 	AND
					   tubf.[user_id]	= @user_id

			WHERE	tbl.comp_id = @comp_id	AND
					tbl.cbd_id	= @cbd_id	AND
				   (tubf.comp_id IS NOT NULL OR tcbqhd.bra_id IS NULL)

			ORDER BY tcbqhd.cbdh_id ASC




		-- --------------------------------------------------
		-- Verifica si tiene objetivos y los incluye en
		-- la serie
		-- --------------------------------------------------

		-- Obtengo la priner meta relacionada al indicador
		DECLARE @intCPOId AS INT
		DECLARE @strCPODesc AS NVARCHAR(MAX)
		SELECT TOP 1	@intCPOId		= tcbo.cpo_id,
						@strCPODesc		= tcbo.cpo_desc
			FROM tbCheckBoard_Objetives tcbo
			WHERE	tcbo.comp_id		= @comp_id	AND
					tcbo.cbd_id			= @cbd_id	AND
					tcbo.cpo_disabled	= 'False'





		-- -------------------------------------------------------------------------------
		-- por cada indicador calculado debo calcular cual
		-- seria el valor del objetivo y ponerle el nombre
		-- del objetivo y valor
		-- -------------------------------------------------------------------------------
		DECLARE curTemp CURSOR LOCAL FAST_FORWARD FOR
			SELECT	tmp.Reference,
					tmp.cbdhd_valueDecimal1,
					tmp.cbdhd_valueDate1
			FROM #tmpTable tmp


		DECLARE @intReference		AS INT
		DECLARE @decvalueDecimal1	AS DECIMAL(19,4)
		DECLARE @datvalueDate1		AS DATETIME

		DECLARE @objetiveDays		AS INT
		DECLARE @objetiveValueByDay AS DECIMAL(19,4)
		DECLARE @objetiveDaysBetweenIndicatorAndBeginOfObjetive AS INT
		DECLARE @objetiveEndDate	AS DATETIME
		DECLARE @objetibeID			AS INT

		DECLARE @datLastDateOfObjetive AS DATETIME
		DECLARE @intLastDateObjetiveId AS INT
		DECLARE @decLastDateObjetiveFinalValue AS DECIMAL(19,4)



		OPEN		curTemp
		FETCH NEXT FROM curTemp
		INTO	@intReference,
				@decvalueDecimal1,
				@datvalueDate1
		WHILE @@FETCH_STATUS = 0
			BEGIN

				SET @objetiveDaysBetweenIndicatorAndBeginOfObjetive = 0
				SET @objetiveDays									= 0
				SET @objetiveValueByDay								= 0
				SELECT TOP 1	@objetiveDays		= DATEDIFF(DAY, tcbobd.cpor_beginDate,tcbobd.cpor_endDate),
								@objetiveValueByDay = (tcbobd.cpor_endValue - tcbobd.cpor_beginValue) / dbo.fnNoZDiv(DATEDIFF(DAY,tcbobd.cpor_beginDate, tcbobd.cpor_endDate)),
								@objetiveDaysBetweenIndicatorAndBeginOfObjetive
													= DATEDIFF(DAY, tcbobd.cpor_beginDate ,@datvalueDate1 ) ,
								@objetiveEndDate	= dbo.fnGetEnd_or_BeginOfDate( tcbobd.cpor_endDate,'True'),
								@objetibeID			= tcbobd.cpor_id
					FROM tbCheckBoard_ObjetivesByDate tcbobd
					WHERE	tcbobd.comp_id	=  @comp_id		AND
							tcbobd.cpo_id	= @intCPOId		AND
							(@datvalueDate1 BETWEEN tcbobd.cpor_beginDate AND tcbobd.cpor_endDate)
					ORDER BY tcbobd.cpor_beginDate


					IF  @objetiveEndDate > dbo.fnGetEnd_or_BeginOfDate(ISNULL(@datLastDateOfObjetive,GETDATE() - 3000),'True')
						BEGIN
							SET @datLastDateOfObjetive = @objetiveEndDate
							SET @intLastDateObjetiveId = @objetibeID
							SET @decLastDateObjetiveFinalValue = @objetiveDays * @objetiveValueByDay
						END


				-- Si encontro datos en el objetivo guarda por que valor de meta  deberia ir en la fecha en que se realizo el calculo
				IF @objetiveDays <> 0
					BEGIN
						UPDATE #tmpTable
							SET cpo_value	= @objetiveDaysBetweenIndicatorAndBeginOfObjetive * @objetiveValueByDay,
								cpo_desc	= @strCPODesc ,
								cpo_withValue = 'True'
							WHERE Reference	= @intReference





					END


				FETCH NEXT FROM curTemp
				INTO	@intReference,
						@decvalueDecimal1,
						@datvalueDate1
			END

		CLOSE		curTemp
		DEALLOCATE	curTemp


		-- Inserta el Ultimo dia del objetivo con su ultimo valor
		IF @objetiveDays <> 0
			BEGIN


				IF NOT EXISTS(SELECT 1 FROM #tmpTable WHERE cbdhd_valueDate1 = @datLastDateOfObjetive )
					BEGIN
						INSERT INTO #tmpTable(	cbdhd_valueText1,
												cbdhd_valueDate1,
												cbdhd_valueDecimal1,
												cbdhd_valueText2,
												cbdhd_valueDate2,
												cbdhd_valueDecimal2,
												Reference	,
												DateOfCalculation,
												cbd_boardDesc,
												cpo_desc,
												cpo_value,
												cpo_WithValue

						)
						VALUES ('*',
								@datLastDateOfObjetive,
								0,
								'',
								@datLastDateOfObjetive,
								0,
								-1,
								@datLastDateOfObjetive,
								@strCPODesc,
								@strCPODesc,
								@decLastDateObjetiveFinalValue,
								'True')
					END
			END
		-- -------------------------------------------------------------------------------



		SELECT * FROM #tmpTable ORDER BY Reference DESC
		DROP TABLE #tmpTable

	END
GO




