CREATE PROCEDURE [dbo].[spCheckBoard_queryCodeExec4Graphic]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@cbd_id		INT,
	@top		INT
)

AS



	BEGIN

		SET NOCOUNT ON

		-- ---------------------
		-- Testing
		-- ---------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT,
				@cbd_id		INT,
				@top		INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@prof_id	= 1,
				@user_id	= 1,
				@cbd_id		= 1,
				@top		= 3
		*/
		-- ---------------------


		DECLARE @intcbd_type AS INT
		SET @intcbd_type = 0
		SELECT @intcbd_type = tcbqc.cbd_type
			FROM tbCheckBoard_Indicator tcbi
			INNER JOIN tbCheckBoard_queryCode tcbqc
				ON	tcbqc.comp_id = tcbi.comp_id AND
					tcbqc.cbdc_id = tcbi.cbdc_id



		IF @top = 0 OR @intcbd_type = 2
			BEGIN
				SET @top = 1
			END

		DECLARE @tblQueryHistoryHeader TABLE (comp_id INT, cbdh_id INT, cbd_id	INT)

		INSERT INTO @tblQueryHistoryHeader
											(
											 comp_id,
											 cbdh_id,
											 cbd_id
											)
											SELECT
												TOP (@top)
													tcbqhh.comp_id,
													tcbqhh.cbdh_id,
													tcbqhh.cbd_id
												FROM tbCheckBoard_QueryHistoryHeader	tcbqhh
												WHERE	tcbqhh.comp_id	= @comp_id		AND
														tcbqhh.cbd_id	= @cbd_id
												ORDER BY tcbqhh.cbdh_id  DESC



		SELECT
			tcbqhd.cbdhd_valueText1,
			tcbqhd.cbdhd_valueDecimal1--,
			--tcbqhd.cbdhd_valueDate1--,
			--tcbqhd.cbdhd_valueText2,
			--tcbqhd.cbdhd_valueDecimal2,
			--tcbqhd.cbdhd_valueDate2,
			--tcbi.cbd_image

			FROM tbCheckBoard_QueryHistoryDetail		tcbqhd

				INNER JOIN @tblQueryHistoryHeader		tbl
				ON	tbl.comp_id		= tcbqhd.comp_id	AND
					tbl.cbdh_id		= tcbqhd.cbdh_id

				INNER JOIN tbCheckBoard_Indicator		tcbi
				ON	tcbi.comp_id	= tbl.comp_id		AND
					tcbi.cbd_id		= tbl.cbd_id

			WHERE	tbl.comp_id = @comp_id AND
					tbl.cbd_id	= @cbd_id

			ORDER BY tcbqhd.cbdh_id DESC

	END
GO




CREATE PROCEDURE spCheckBoard_QueryHistoryHeader_getLatestDateOfCalculation
(
	@comp_id	INT,
	@cbd_id		INT
)
AS


	BEGIN

		SET NOCOUNT ON

			-- -------------------
			-- Testing
			-- -------------------
			/*
			DECLARE
				@comp_id	INT,
				@cbd_id		INT
			SELECT
				@comp_id	= 1,
				@cbd_id		= 1
			*/
			-- -------------------


			SELECT TOP 1
				tcbqhh.cbdh_cd
			FROM tbCheckBoard_QueryHistoryHeader tcbqhh

			WHERE	tcbqhh.comp_id	= @comp_id	AND
					tcbqhh.cbd_id	= @cbd_id

			ORDER BY tcbqhh.cbdh_cd DESC


	END
GO




-- =============================================
-- Author:		MOS
-- Create date: 10-2013
-- Description:	<Description,,>
-- =============================================


CREATE PROCEDURE [dbo].[spCheckBoard_ScheduleExecution]

AS



BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	DECLARE @intIndicatorCounterCalculated AS INT
	SET		@intIndicatorCounterCalculated = 0


	SET DATEFIRST 7 -- Dom,ingo x Defecto
	DECLARE @intDOW AS INT
	SET		@intDOW = datepart(dw,getdate())

	-- --------------------------------------------------
	-- Cursor con los Indicadores que se deben calcular
	-- --------------------------------------------------
	DECLARE curSchedule CURSOR LOCAL FAST_FORWARD FOR
	SELECT		tcbs.comp_id,
				tcbi.cbd_id,
				vcbqc.cbdc_query1,
				ISNULL(tcbi.cbd_ExecutionMinutes_MaxMinutes,0),
				tcbi.cbd_ExecutionMinutes_Hour4StartIfExceeded,
				ISNULL(tcbi.cbd_ExecutionMinutes_LastExecMinutes,0)		[cbd_ExecutionMinutes_LastExecMinutes],
				tcbs.cbds_id,
				tcbi.cbd_emailAlert,
				ISNULL(tcbs.bra_id,-1),
				ISNULL(tcbs.[user_id],-1),
				ISNULL(tcbs.prof_id,-1),
				ISNULL(tcbs.bra_id_processingDate,-1),
				IsNull(tcbs.cbds_allowMoreThanONEByDay,'False'),
				isnull(tcbs.cbds_forceCalculationDate2BranchDate,'False')
		FROM	tbCheckBoard_Schedule tcbs						WITH (NOLOCK)
		INNER JOIN tbCheckBoard_Indicator tcbi					WITH (NOLOCK)
			ON	tcbi.comp_id = tcbs.comp_id AND
			    tcbi.cbd_id  = tcbs.cbd_id
		INNER JOIN vwCheckBoard_queryCode vcbqc					WITH (NOLOCK)
			ON	vcbqc.cbdc_id = tcbi.cbdc_id
		WHERE (
				(
						GETDATE() >											dbo.fnCheckBoard_ScheduleExecution(	tcbs.comp_id,
																												tcbi.cbd_id,
																												tcbs.cbds_id,
																	 											@intDOW)
					AND
						isNull(tcbi.cbd_LastExecution,GETDATE() - 1000) <=  dbo.fnCheckBoard_ScheduleExecution(	tcbs.comp_id,
																												tcbi.cbd_id,
																												tcbs.cbds_id,
																												@intDOW)
				)
				AND
				CASE
					WHEN tcbs.cbds_disabledOnSunday		= 'True' AND @intDOW = 1  THEN 'True'
				    WHEN tcbs.cbds_disabledOnMonday		= 'True' AND @intDOW = 2  THEN 'True'
				    WHEN tcbs.cbds_disabledOnTuesday	= 'True' AND @intDOW = 3  THEN 'True'
				    WHEN tcbs.cbds_disabledOnWednesday	= 'True' AND @intDOW = 4  THEN 'True'
				    WHEN tcbs.cbds_disabledOnThursday	= 'True' AND @intDOW = 5  THEN 'True'
				    WHEN tcbs.cbds_disabledOnFriday		= 'True' AND @intDOW = 6  THEN 'True'
				    WHEN tcbs.cbds_disabledOnSaturday	= 'True' AND @intDOW = 7  THEN 'True'
				    ELSE	'False'
				END = 'False'
				AND tcbi.cbd_disabled = 'False'
			)
			OR
			tcbi.cbd_forceExecution = 'True'

	OPEN curSchedule

	DECLARE @intCBD_Id					AS INT
	DECLARE @intCbds_id					AS INT
	DECLARE @intComp_Id					AS INT
	DECLARE @intProfileId				AS INT
	DECLARE @intUserId					AS INT
	DECLARE @intBraId					AS INT
	DECLARE @intBraId4ProcessingDate	AS INT

	DECLARE @strQuery   AS VARCHAR(MAX)
	DECLARE @datOfBegin	AS DATETIME
	DECLARE @intExecutionMinutes_MaxMinutes				AS INT
	DECLARE @intExecutionMinutes_Hour4StartIfExceeded	AS INT
	DECLARE @intExecutionMinutes_LastExecMinutes		AS INT
	DECLARE @cbd_emailAlert								AS BIT
	DECLARE @bitAllowMoreThanONEByDay					AS BIT
	SET		@bitAllowMoreThanONEByDay					= 'False'
	DECLARE @bitForceCalculationDate2BranchDate			AS BIT


	FETCH NEXT FROM curSchedule INTO @intComp_Id,
									 @intCBD_Id,
									 @strQuery ,
 									 @intExecutionMinutes_MaxMinutes,
									 @intExecutionMinutes_Hour4StartIfExceeded,
									 @intExecutionMinutes_LastExecMinutes,
									 @intCbds_id,
									 @cbd_emailAlert,
									 @intBraId,
									 @intUserId,
									 @intProfileId,
									 @intBraId4ProcessingDate,
									 @bitAllowMoreThanONEByDay,
									 @bitForceCalculationDate2BranchDate


	WHILE @@FETCH_STATUS = 0
		BEGIN


			-- Solo ejecuta si la ultima ejecucion tardo menos que el maximo o si la hora si se cumplio eso es mayor o igual a la hora definida.
			IF	(
					@intExecutionMinutes_LastExecMinutes > @intExecutionMinutes_MaxMinutes AND
					DATEPART(hour,GETDATE()) >= @intExecutionMinutes_Hour4StartIfExceeded
				)
				OR
				@intExecutionMinutes_LastExecMinutes <= @intExecutionMinutes_MaxMinutes
				OR
				@intExecutionMinutes_MaxMinutes = 0


			BEGIN


				BEGIN TRY

					-- --------------------------------------------------
					-- Ejecuta el Indicador a Calcular
					-- --------------------------------------------------

					SET @datOfBegin = GETDATE()

					-- Dentro del codigo a ejecutar debo recuperar el Indicador a grabar
					set @strQuery = (REPLACE (@strQuery,'@intComp_ID'				,convert(varchar,@intComp_Id)))
					set @strQuery = (REPLACE (@strQuery,'@intCBD_ID'				,convert(varchar,@intCBD_Id)))
					set @strQuery = (REPLACE (@strQuery,'@intProfile_ID'			,convert(varchar,@intProfileId)))
					set @strQuery = (REPLACE (@strQuery,'@intUser_ID'				,convert(varchar,@intUserId)))
					set @strQuery = (REPLACE (@strQuery,'@intBra_ID'				,convert(varchar,@intBraId)))
					set @strQuery = (REPLACE (@strQuery,'@intBra_ID4ProcessingDate' ,convert(varchar,@intBraId4ProcessingDate)))




					-- --------------------------------------------------
					-- Verifica Instrucciones NO VALIDAS!
					-- --------------------------------------------------
					IF	@strQuery LIKE '%DROP%'			OR
						@strQuery LIKE '%TRUNCATE%'		OR
						@strQuery LIKE '%ALTER%'		OR
						@strQuery LIKE '%CREATE%'		OR
						@strQuery LIKE '%PROCEDURE%'	OR
						@strQuery LIKE '%FUNCTION%'		OR
						@strQuery LIKE '%cbdh_LastInserted%'
						BEGIN
							SET @strQuery = 'Select -1'
						END
					-- --------------------------------------------------


					-- Obtiene Fecha de Calculo FORZADO
					DECLARE @datOfCalculation AS DATETIME
					SELECT  @datOfCalculation	= tb.bra_processingDate
						FROM tbBranch tb
						WHERE	tb.comp_id		= @intComp_Id AND
								tb.bra_id		= @intBraId4ProcessingDate
					SET @datOfCalculation		= DATEADD(hour, DATEPART(hour,GETDATE()), @datOfCalculation)
					SET @datOfCalculation		= DATEADD(minute, DATEPART(minute,GETDATE()), @datOfCalculation)
					-- --------------------------------------------------
					-- si NO Permite mas de un calculo por dia.-
					-- --------------------------------------------------
					IF @bitAllowMoreThanONEByDay = 'False'
						BEGIN

							-- Si es forzado a la fecha de la sucursal debe borrar de esta fecha
							IF @bitForceCalculationDate2BranchDate = 'True'
								BEGIN
									DELETE	FROM	tbCheckBoard_QueryHistoryDetail
											FROM	tbCheckBoard_QueryHistoryDetail hd
										INNER JOIN tbCheckBoard_QueryHistoryHeader tcbqhh
											ON	tcbqhh.comp_id	= hd.comp_id	AND
												tcbqhh.cbdh_id	= hd.cbdh_id
										WHERE	tcbqhh.comp_id	= @intComp_Id	AND
												tcbqhh.cbd_id	= @intCBD_Id	AND
												CONVERT(VARCHAR(10),tcbqhh.cbdh_cd,102)	= CONVERT(VARCHAR(10),@datOfCalculation,102)
								END
							ELSE
								BEGIN
									DELETE	FROM	tbCheckBoard_QueryHistoryDetail
											FROM	tbCheckBoard_QueryHistoryDetail hd
										INNER JOIN tbCheckBoard_QueryHistoryHeader tcbqhh
											ON	tcbqhh.comp_id	= hd.comp_id	AND
												tcbqhh.cbdh_id	= hd.cbdh_id
										WHERE	tcbqhh.comp_id	= @intComp_Id	AND
												tcbqhh.cbd_id	= @intCBD_Id	AND
												CONVERT(VARCHAR(10),tcbqhh.cbdh_cd,102)	= CONVERT(VARCHAR(10),@datOfBegin,102)
								END

						END
					-- --------------------------------------------------


					EXEC (@strQuery)

					UPDATE tbCheckBoard_Schedule
						SET
								cbds_lastExecution  = GETDATE(),
								cbds_ErrorMessage	= 'OK'
						WHERE	comp_id = @intComp_Id AND
								cbd_id	= @intCbds_id

					SET @intIndicatorCounterCalculated = @intIndicatorCounterCalculated + 1
					-- --------------------------------------------------


					-- --------------------------------------------------
					-- Si dice ajustar la fecha de calculo a la de la
					-- Sucursal correspondiente debe hacerlo
					-- --------------------------------------------------
					IF @bitForceCalculationDate2BranchDate = 'True'
						BEGIN

							UPDATE tbCheckBoard_QueryHistoryHeader
								SET	cbdh_cd = @datOfCalculation
								WHERE	comp_id				= @intComp_Id	AND
										cbd_id				= @intCBD_Id	AND
										cbdh_LastInserted	= 'True'
						END

					UPDATE tbCheckBoard_QueryHistoryHeader
						SET		cbdh_LastInserted = 'False'
						WHERE
								comp_id				= @intComp_Id	AND
								cbd_id				= @intCBD_Id	AND
								cbdh_LastInserted	= 'True'
					-- --------------------------------------------------



					-- ------------------------------------------------------------
					-- Verifica que no hayan quedado indicadores Header sin Detail.
					-- ------------------------------------------------------------
					DELETE tbCheckBoard_QueryHistoryHeader
						FROM tbCheckBoard_QueryHistoryHeader he
						LEFT JOIN tbCheckBoard_QueryHistoryDetail de
							ON	de.comp_id = he.comp_id AND
								de.cbdh_id = he.cbdh_id
						WHERE de.comp_id IS NULL
					-- ------------------------------------------------------------


					IF @@ROWCOUNT = 0
						BEGIN
							IF @cbd_emailAlert = 'True'
								BEGIN
									EXEC spCheckBoard_IndicatorsOutOfRangeMailing @intComp_Id,  @intCBD_Id, -1 , -1,@intCbds_id

								END
						END


				END TRY
				BEGIN CATCH

					-- --------------------------------------------------
					-- Actualiza datos de Ultima Ejecución del Indicador
					-- --------------------------------------------------
					UPDATE tbCheckBoard_Schedule
						SET
								cbds_lastExecution  = GETDATE(),
								cbds_ErrorMessage	= ERROR_MESSAGE()
						WHERE	comp_id = @intComp_Id AND
								cbd_id	= @intCbds_id
					-- --------------------------------------------------

				END CATCH

				-- --------------------------------------------------
				-- Actualiza datos de Ultima Ejecución del Indicador
				-- --------------------------------------------------
				UPDATE tbCheckBoard_Indicator
					SET
						cbd_ExecutionMinutes_LastExecMinutes		= DATEDIFF(minute, @datOfBegin , GETDATE()),
						cbd_forceExecution							= 'False',
						cbd_LastExecution							= GETDATE()
					WHERE	comp_id = @intComp_Id AND
							cbd_id	= @intCBD_Id
				-- --------------------------------------------------

			END

			FETCH NEXT FROM curSchedule INTO @intComp_Id,
											 @intCBD_Id ,
											 @strQuery,
											 @intExecutionMinutes_MaxMinutes,
											 @intExecutionMinutes_Hour4StartIfExceeded,
											 @intExecutionMinutes_LastExecMinutes,
											 @intCbds_id,
											 @cbd_emailAlert,
											 @intBraId,
											 @intUserId,
											 @intProfileId,
											 @intBraId4ProcessingDate,
											 @bitAllowMoreThanONEByDay,
											 @bitForceCalculationDate2BranchDate


		END

	CLOSE		curSchedule
	DEALLOCATE	curSchedule

	SELECT @intIndicatorCounterCalculated













	-- ------------------------------------------------------------
	-- Ejecutar el Envio de Mail de Grupos de Indicadores.
	-- ------------------------------------------------------------
	DECLARE @intCbdg_id		AS INT
	DECLARE @intCbdgrs_id	AS INT
	DECLARE curSchedule CURSOR LOCAL  FAST_FORWARD FOR
	SELECT		tcbs.comp_id,
				tcbs.cbdg_id ,
				tcbs.cbdgrs_id
		FROM tbCheckBoard_GroupMailSchedule  tcbs						WITH (NOLOCK)


		WHERE (
				(
						GETDATE() >											  dbo.fnCheckBoard_ScheduleGroupMail(	tcbs.comp_id,
																													tcbs.cbdgrs_id ,
																	 												@intDOW)
					AND
						isNull(tcbs.cbdgrs_lastMailing ,GETDATE() - 1000) <=  dbo.fnCheckBoard_ScheduleGroupMail(	tcbs.comp_id,
																													tcbs.cbdgrs_id,
																													@intDOW)
				)
				AND
				CASE
					WHEN tcbs.cbdgrs_envieOnSunday		= 'True' AND @intDOW = 1  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnMonday		= 'True' AND @intDOW = 2  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnTuesday		= 'True' AND @intDOW = 3  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnWednesday	= 'True' AND @intDOW = 4  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnThursday	= 'True' AND @intDOW = 5  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnFriday		= 'True' AND @intDOW = 6  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnSunday		= 'True' AND @intDOW = 7  THEN 'True'
				    ELSE	'False'
				END = 'True'
				AND
				tcbs.cbdgrs_disabled = 'False'
			)
				OR
			tcbs.cbdgrs_scheduleForced = 'True'


	OPEN curSchedule




	FETCH NEXT FROM curSchedule INTO @intComp_Id,
									 @intCbdg_id,
									 @intCbdgrs_id


	WHILE @@FETCH_STATUS = 0
		BEGIN


			BEGIN


				BEGIN TRY

					-- --------------------------------------------------
					-- Ejecuta el Mailing de grupo de Indicadores
					-- --------------------------------------------------

					EXEC spCheckBoard_IndicatorsOutOfRangeMailing @intComp_Id, -1, @intCbdg_id , -1,@intCbdgrs_id

					UPDATE tbCheckBoard_GroupMailSchedule
						SET		cbdgrs_lastMailing 		= GETDATE(),
								cbdgrs_scheduleForced	= 'False'
						WHERE	comp_id					= @intComp_Id	AND
								cbdgrs_id				= @intCbdgrs_id

					-- --------------------------------------------------


				END TRY
				BEGIN CATCH

					-- --------------------------------------------------
					-- Actualiza datos de Ultima Ejecución
					-- --------------------------------------------------
					UPDATE tbCheckBoard_GroupMailSchedule
						SET		cbdgrs_lastMailing 		= GETDATE(),
								cbdgrs_scheduleForced	= 'False'
						WHERE	comp_id				= @intComp_Id	AND
								cbdgrs_id			= @intCbdgrs_id
					-- --------------------------------------------------

				END CATCH

			END

			FETCH NEXT FROM curSchedule INTO @intComp_Id,
											 @intCbdg_id,
											 @intCbdgrs_id


		END

	CLOSE		curSchedule
	DEALLOCATE	curSchedule
	-- ------------------------------------------------------------




	-- ------------------------------------------------------------
	-- Ejecutar el Envio de Mail de One Page Management
	-- ------------------------------------------------------------
	DECLARE @intCbdo_id		AS INT
	DECLARE @intCbdos_id	AS INT
	DECLARE curScheduleOPM CURSOR LOCAL  FAST_FORWARD FOR
	SELECT		tcbs.comp_id,
				tcbs.cbdo_id ,
				tcbs.cbdos_id
		FROM tbCheckBoard_OnePageManagementMailSchedule   tcbs						WITH (NOLOCK)


		WHERE (
				(
						GETDATE() >												dbo.fnCheckBoard_ScheduleOnePageManagementMail(	tcbs.comp_id,
																																tcbs.cbdo_id ,
																	 															@intDOW)
					AND
						isNull(tcbs.cbdgrs_lastMailing ,GETDATE() - 1000) <=	dbo.fnCheckBoard_ScheduleOnePageManagementMail(	tcbs.comp_id,
																																tcbs.cbdo_id ,
																																@intDOW)
				)
				AND
				CASE
					WHEN tcbs.cbdgrs_envieOnSunday		= 'True' AND @intDOW = 1  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnMonday		= 'True' AND @intDOW = 2  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnTuesday		= 'True' AND @intDOW = 3  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnWednesday	= 'True' AND @intDOW = 4  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnThursday	= 'True' AND @intDOW = 5  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnFriday		= 'True' AND @intDOW = 6  THEN 'True'
				    WHEN tcbs.cbdgrs_envieOnSunday		= 'True' AND @intDOW = 7  THEN 'True'
				    ELSE	'False'
				END = 'True'
				AND
				tcbs.cbdos_disabled = 'False'
			)
				OR
			tcbs.cbdos_scheduleForced = 'True'

	OPEN curScheduleOPM




	FETCH NEXT FROM curScheduleOPM INTO @intComp_Id,
									 @intCbdo_id,
									 @intCbdos_id


	WHILE @@FETCH_STATUS = 0
		BEGIN


			BEGIN


				BEGIN TRY

					-- --------------------------------------------------
					-- Ejecuta el Mailing de One Page Management
					-- --------------------------------------------------

					EXEC spCheckBoard_IndicatorsOutOfRangeMailing @intComp_Id, -1, -1 , @intCbdo_id,@intCbdos_id

					UPDATE tbCheckBoard_OnePageManagementMailSchedule
						SET		cbdgrs_lastMailing 		= GETDATE(),
								cbdos_scheduleForced	= 'False'
						WHERE	comp_id				= @intComp_Id	AND
								cbdos_id			= @intCbdos_id

					-- --------------------------------------------------

				END TRY
				BEGIN CATCH

					-- --------------------------------------------------
					-- Actualiza datos de Ultima Ejecución
					-- --------------------------------------------------
					UPDATE tbCheckBoard_OnePageManagementMailSchedule
						SET		cbdgrs_lastMailing 	= GETDATE(),
								cbdos_scheduleForced= 'False'
						WHERE	comp_id				= @intComp_Id	AND
								cbdos_id			= @intCbdos_id
					-- --------------------------------------------------

				END CATCH

			END

			FETCH NEXT FROM curScheduleOPM INTO @intComp_Id,
											 @intCbdo_id,
											 @intCbdos_id


		END

	CLOSE		curScheduleOPM
	DEALLOCATE	curScheduleOPM
	-- ------------------------------------------------------------


END
GO



CREATE PROCEDURE spCheckBoard_ScheduleExecution_DeleteDataFromHeaderAndDetail
(
	@comp_id	INT,
	@cbd_id		INT,
	@cbdh_date	DATETIME
)
AS
	SET NOCOUNT ON
		BEGIN
			SET DATEFORMAT 'YMD'
			-- --------------------------------------
			-- TESTING
			-- --------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@cbd_id		INT,
					@cbdh_date	DATETIME

				SELECT
					@comp_id	= 1,
					@cbd_id		= 3,
					@cbdh_date	= '2015-07-21'
			*/
			-- --------------------------------------


			-- ------------------------------------------------------------------------------------------------------------------------
			-- INICIALIZAMOS LA FECHA PARA QUE BORRE LOS REGISTROS CORRECTAMENTE
			-- ------------------------------------------------------------------------------------------------------------------------
			SET @cbdh_date = dbo.fnGetEnd_or_BeginOfDate(@cbdh_date,'False')
			-- ------------------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------------------
			-- BORRAMOS LOS DETALLES CUYO CBDH_ID ESTE EN EL GRUPO DE SELECCIÓN
			-- DE LA HEADER, UNA VEZ BORRADO EL DETAIL, PASAREMOS A BORRAR LA HEADER
			-- ------------------------------------------------------------------------------------------------------------------------
			DELETE FROM tbCheckBoard_QueryHistoryDetail
			WHERE	comp_id = @comp_id																		AND
					cbdh_id IN (SELECT tcbqhh.cbdh_id
								   FROM tbCheckBoard_QueryHistoryHeader										tcbqhh
								 WHERE	tcbqhh.comp_id										= @comp_id		AND
										tcbqhh.cbd_id										= @cbd_id		AND
										dbo.fnGetEnd_or_BeginOfDate(tcbqhh.cbdh_cd,'False')	= @cbdh_Date)
			-- ------------------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------------------
			-- BORRAMOS LOS DATOS DEL HEADER BASADOS EN EL INDICADOR Y LA FECHA
			-- ------------------------------------------------------------------------------------------------------------------------
			DELETE FROM tbCheckBoard_QueryHistoryHeader
			WHERE	comp_id											= @comp_id				AND
					cbd_id											= @cbd_id				AND
					dbo.fnGetEnd_or_BeginOfDate(cbdh_cd,'False')	= @cbdh_date
			-- ------------------------------------------------------------------------------------------------------------------------
		END

GO





