CREATE PROCEDURE [dbo].[spCheckPortfolio_checkData]
(
	@comp_id				INT,
	@lang_id				INT,
	@datefrom				DATETIME,
	@dateto					DATETIME,
	@optionNumber			INT,
	@numberFrom				VARCHAR(40),
	@optionTotal			INT,
	@totalFrom				DECIMAL(19,5),
	@totalTo				DECIMAL(19,5),
	@curr_id				INT,
	@origin					BIT,
	@guid					UNIQUEIDENTIFIER,
	@ba_id					INT
)
AS


BEGIN




	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-21
	-- Parte		: 499
	-- Description	: Para agregar la cantidad y el importe total de los cheques seleccionados en el depósito de cheques
	--				  se agregan esos valores en el query final
	-- =================================================================================================================




	-- -----------------------------------------------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id				int,
			@lang_id				int,
			@datefrom				datetime,
			@dateto					datetime,
			@optionNumber			int,
			@numberFrom				varchar(40),
			@optionTotal			int,
			@totalFrom				decimal(19,5),
			@totalTo				decimal(19,5),
			@curr_id				int,
			@origin					BIT,
			@guid					UNIQUEIDENTIFIER
	SELECT	@comp_id				=	1,
			@lang_id				=	2,
			@DateFrom				=	'1900-01-01',
			@DateTo					=	'9999-01-01',
			@optionNumber			=	-1,
			@numberFrom				=	'',
			@optionTotal			=	-1,
			@totalFrom				=	0,
			@totalTo				=	0,
			@curr_id				=	1,
			@origin					=	'false',
			@guid					=	'6db77daf-38da-4e5c-9ad7-0b7afaed71df'
	--DROP TABLE #tmpDummy
	*/
	-- -----------------------------------------------------------------------------------------------------------------


	/*si la marca update es true se eliminan las marcas de cheque en proceso*/
	/*IF @update = 'true'
		UPDATE	dbo.tbCheckPortfolio
		SET		chp_isInProcess		= 'False'--,
				--chp_guid			= NULL
		WHERE	comp_id				= @comp_id
		and		chp_isAvailable		= 'True'
		and		chp_isPayed			= 'False'
	*/


	-- --------------------------------------------------------
	-- Si esta deshabilitado el control de concurrencia...
	-- --------------------------------------------------------
	IF EXISTS(
				SELECT 1
					FROM tbBranch tb
					WHERE	tb.comp_id								= @comp_id	AND
							tb.bra_Payments_DisableConcurrencyBlock = 'True'
				)
		BEGIN

				-- A t e n c i o n !!!!!!!!!!!!!!!!!
				-- IDEM en spCheckPortfolio_UnCheckAll
				/*obtenemos una segunda tabla con el total seleccionado en la grilla*/
			SELECT	( SELECT	ISNULL(SUM(tcp1.chp_total),0)
						FROM	tbCheckPortfolio		tcp1
						WHERE 	tcp1.comp_id			= @comp_id
						AND 	tcp1.chp_isAvailable	= 'False'
						AND 	tcp1.chp_isPayed		= 'False'
						AND		tcp1.chp_isInProcess	= 'true'
						AND		tcp1.chp_guid			= @guid),

					-- =====================================================================
					-- Parte : 499
					(	SELECT	COUNT(*)
						FROM	tbCheckPortfolio tcp1
						WHERE	tcp1.comp_id	= @comp_id
						AND		tcp1.chp_guid	= @guid
						AND		tcp1.chp_isInProcess = 'True') ,

					(	SELECT 	ISNULL(SUM(tcp1.chp_total),0.00)
						FROM	tbCheckPortfolio tcp1
						WHERE	tcp1.comp_id	= @comp_id
						AND		tcp1.chp_guid	= @guid
						AND		tcp1.chp_isInProcess = 'True')
					-- =====================================================================
					RETURN
		END
	-- --------------------------------------------------------



	-- =====================================================================================================
	-- 2010-08-21 - MOH - Parte : 499*
	-- Como el spCheckPortfolio_UpdateInProcess ahora devuelve datos se crea una tabla temporal dummy para recuperar
	-- esos datos, y no los devuelva este sp
	--CREATE TABLE #tmpDummy ( qty INT, total DECIMAL(18,6) )
	-- =====================================================================================================



	IF @origin = 'true'
		BEGIN
			DECLARE @lchp_id		INT

			DECLARE cursor_cp CURSOR FOR
			/*obtenemos los cheques habilitados para el depósito*/
			SELECT	tcp1.chp_id

			FROM	dbo.tbCheckPortfolio					tcp1
					INNER JOIN tbsysOptionsValues			tov				WITH (NOLOCK)
					ON	tov.lang_id			= @lang_id
					AND tov.optval_class	= 1
					AND tov.optval_id		= convert(int,ISNULL(tcp1.chp_isToOrder,0))
					LEFT JOIN tbBanksName					tbn				WITH (NOLOCK)
					ON	tbn.comp_id			= tcp1.comp_id
					AND tbn.bn_id			= tcp1.bn_id

			WHERE	tcp1.comp_id		= @comp_id
			and	    tcp1.curr_id		= @curr_id
			and		tcp1.chp_PayDate	between  @datefrom and	@dateto
			and		(
					(@optionNumber = -1)													or
					(@optionNumber = 0 and tcp1.chp_number like @numberFrom + '%')			or
					(@optionNumber = 1 and tcp1.chp_number like '%' +  @numberFrom + '%')	or
					(@optionNumber = 2 and tcp1.chp_number = @numberFrom)					or
					(@optionNumber = 3 and tcp1.chp_number <> @numberFrom)					or
					(@optionNumber = 4 and tcp1.chp_number not like '%' +  @numberFrom + '%')
					)
			and		(
					(@optionTotal = -1)														or
					(@optionTotal = 0 and tcp1.chp_total = @totalFrom)						or
					(@optionTotal = 1 and tcp1.chp_total > @totalFrom)						or
					(@optionTotal = 2 and tcp1.chp_total < @totalFrom)						or
					(@optionTotal = 3 and tcp1.chp_total between @totalFrom and @totalTo)
					)

			and		tcp1.chp_isAvailable	= 'True'
			and		tcp1.chp_isPayed		= 'False'
			AND		ISNULL(tcp1.chp_isCancelled,'False')	= 'False'




			OPEN cursor_cp

			FETCH cursor_cp INTO @lchp_id

			WHILE @@FETCH_STATUS = 0
			BEGIN

				-- Parte : 499*
				--INSERT INTO #tmpDummy (qty,total)
				EXEC spCheckPortfolio_UpdateInProcessFrom_spCheckPortfolio_checkData	@comp_id, @lchp_id, @guid, @origin

				FETCH cursor_cp INTO @lchp_id
			END


			CLOSE cursor_cp
			DEALLOCATE cursor_cp



			/*obtenemos una segunda tabla con el total seleccionado en la grilla*/
			SELECT	(	SELECT	ISNULL(SUM(tcp1.chp_total),0)
						FROM	tbCheckPortfolio		tcp1
						WHERE 	tcp1.comp_id			= @comp_id
						AND 	tcp1.chp_isAvailable	= 'True'
						AND 	tcp1.chp_isPayed		= 'False'
						AND		tcp1.chp_isInProcess	= 'true'
						AND		tcp1.chp_guid			= @guid ),

					-- =====================================================================
					-- Parte : 499
					(	SELECT	COUNT(*)
						FROM	tbCheckPortfolio tcp1
						WHERE	tcp1.comp_id	= @comp_id
						AND		tcp1.chp_guid	= @guid
						AND		tcp1.chp_isInProcess = 'True') ,

					(	SELECT 	ISNULL(SUM(tcp1.chp_total),0.00)
						FROM	tbCheckPortfolio tcp1
						WHERE	tcp1.comp_id	= @comp_id
						AND		tcp1.chp_guid	= @guid
						AND		tcp1.chp_isInProcess = 'True')
					-- =====================================================================

		END

	ELSE

		BEGIN



			DECLARE @lchp_ida		INT

			DECLARE cursor_cpa CURSOR FOR
			SELECT	tcp1.chp_id [id]

			FROM	dbo.tbCheckPortfolio tcp1
			INNER JOIN tbBankingAccounts			tba					WITH (NOLOCK)
					ON		tba.comp_id		= tcp1.comp_id
						AND tba.ba_id		= (SELECT tbt.ba_id
													FROM tbBankingTransactions tbt
													WHERE tbt.bt_id =
														  (	SELECT MAX(tbt2.bt_id)
																FROM tbBankingTransactions tbt2
												   				WHERE
												   					tbt2.comp_id			= tcp1.comp_id
												   					AND tbt2.chp_id			= tcp1.chp_id
												   					and tbt2.bt_isCancelled	= 'false' )
											  )
			WHERE	tcp1.comp_id		= @comp_id
			and	    tcp1.curr_id		= @curr_id
			and		tcp1.chp_PayDate	between  @datefrom and	@dateto
			and		(
					(@optionNumber = -1)												or
					(@optionNumber = 0 and tcp1.chp_number like @numberFrom + '%')			or
					(@optionNumber = 1 and tcp1.chp_number like '%' +  @numberFrom + '%')	or
					(@optionNumber = 2 and tcp1.chp_number = @numberFrom)					or
					(@optionNumber = 3 and tcp1.chp_number <> @numberFrom)					or
					(@optionNumber = 4 and tcp1.chp_number not like '%' +  @numberFrom + '%')
					)
			and		(
					(@optionTotal = -1)													or
					(@optionTotal = 0 and tcp1.chp_total = @totalFrom)						or
					(@optionTotal = 1 and tcp1.chp_total > @totalFrom)						or
					(@optionTotal = 2 and tcp1.chp_total < @totalFrom)						or
					(@optionTotal = 3 and tcp1.chp_total between @totalFrom and @totalTo)
					)

			and		chp_isAvailable = 'false'
			and		chp_IsPayed		= 'false'
			AND		tba.ba_id		= @ba_id		--	' Solo los acreditados de esta cuenta.-




			OPEN cursor_cpa

			FETCH cursor_cpa INTO @lchp_ida

			WHILE @@FETCH_STATUS = 0
			BEGIN

				-- Parte : 499*
				--INSERT INTO #tmpDummy (qty,total)
				EXEC spCheckPortfolio_UpdateInProcessFrom_spCheckPortfolio_checkData	@comp_id, @lchp_ida, @guid, @origin

				FETCH cursor_cpa INTO @lchp_ida
			END


			CLOSE cursor_cpa
			DEALLOCATE cursor_cpa


			/*obtenemos una segunda tabla con el total seleccionado en la grilla*/
			SELECT	( SELECT	ISNULL(SUM(tcp1.chp_total),0)
						FROM	tbCheckPortfolio		tcp1
						WHERE 	tcp1.comp_id			= @comp_id
						AND 	tcp1.chp_isAvailable	= 'False'
						AND 	tcp1.chp_isPayed		= 'False'
						AND		tcp1.chp_isInProcess	= 'true'
						AND		tcp1.chp_guid			= @guid),

					-- =====================================================================
					-- Parte : 499
					(	SELECT	COUNT(*)
						FROM	tbCheckPortfolio tcp1
						WHERE	tcp1.comp_id	= @comp_id
						AND		tcp1.chp_guid	= @guid
						AND		tcp1.chp_isInProcess = 'True') ,

					(	SELECT 	ISNULL(SUM(tcp1.chp_total),0.00)
						FROM	tbCheckPortfolio tcp1
						WHERE	tcp1.comp_id	= @comp_id
						AND		tcp1.chp_guid	= @guid
						AND		tcp1.chp_isInProcess = 'True')
					-- =====================================================================

		END


END
GO






