CREATE PROCEDURE [dbo].[spCheckPortfolio_existsDataByBankBranchNumber]
(
	@comp_id					INT,
	@bn_id						INT,
	@chp_BankBranch				INT,
	@chp_number					NVARCHAR(50),
	@chp_id						INT,
	@cust_id					INT,
	@return_value				INT OUTPUT
)
AS

BEGIN




	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOH
	-- Creation Date: 2010-07-29
	-- Parte		: 419
	-- Description	: Verificar existencia de un cheque, por medio del número de chaque, el id del banco y la sucursal
	--				  del banco recibidos por parámetros, en la tabla de cheques en cartera (tbCheckPortfolio) y en la
	--				  tabla temporal de chques que se están cargando (tbCheckPortfolioTmp)
	-- Return Values: 1 - Cheque existente, 0 - Cheque no existente
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-18
	-- Parte		: sin parte
	-- Description	: Se agrega como parámetro de entrada el @chp_id, donde viene informado el valor del id del cheque
	--				  cuando es una modificación, ya que siempre validaba mal porque se encontraba a si mismo
	-- =================================================================================================================


	-- ----------------------------------------------------
	-- ----------------------------------------------------
	/*
	DECLARE	@comp_id					INT,
			@bn_id						INT,
			@chp_BankBranch				INT,
			@chp_number					NVARCHAR(50),
			@chp_id						INT,
			@return_value				INT
	SELECT 	@comp_id					=1,
			@bn_id						=4,
			@chp_BankBranch				=4444,
			@chp_number					='444',
			@chp_id						=-1
	*/
	-- ----------------------------------------------------


	IF	EXISTS	(	SELECT TOP 1 	1
						FROM	tbCheckPortfolio		tcp1			WITH (NOLOCK)
						INNER JOIN tbCommercialTransactions AS tct		WITH (NOLOCK)
							ON	tct.comp_id				= tcp1.comp_id AND
								tct.ct_transaction		= tcp1.ct_transaction
						INNER JOIN tbBranch				tb				WITH (NOLOCK)
							ON	tb.comp_id				= tcp1.comp_id AND
								tb.bra_id				= tcp1.bra_id_PortFolio
						WHERE	tcp1.comp_id			= @comp_id
						AND		tcp1.bn_id				= @bn_id
						AND		tcp1.chp_BankBranch		= @chp_BankBranch
						AND		tcp1.chp_number			= @chp_number
						AND		tct.cust_id				= @cust_id		-- MOS 08-2022: se debe permitir cargar el mismo cheque si te lo das otro cliente.  hay bancos con la misma numeracion de cheque para cada cliente
						AND		CASE
					   				WHEN tb.bra_checkPortfolio_AllowDuplicatesIfNotAvailable = 'True' AND tcp1.chp_isAvailable ='False'  THEN	'False'
					   				ELSE																										'True'
					   			END	= 'True'
																					)		OR
		EXISTS	(	SELECT TOP 1 	1
						FROM	tbCheckPortfolioTmp		tcpt			WITH (NOLOCK)
						WHERE	tcpt.comp_id			=	@comp_id
						AND		tcpt.bn_id				=	@bn_id
						AND		tcpt.chpt_BankBranch	=	@chp_BankBranch
						AND		tcpt.chpt_number		=	@chp_number
						AND		(	(@chp_id <> -1 AND tcpt.chpt_id <> @chp_id) OR
									(@chp_id = -1)	)							)
			SET @return_value = 1
	ELSE
			SET @return_value = 0
	--SELECT @return_value



	END
GO






