CREATE procedure [dbo].[spCheckPortfolio_getDataByFilters]
(
	@comp_id				INT ,
	@lang_id				INT ,
	@bra_id					INT ,
	@curr_id				INT ,
	@ba_id					INT ,
	@guid					UNIQUEIDENTIFIER,

	@datefrom				DATETIME,
	@dateto					DATETIME,
	@optionNumber			INT,
	@numberFrom				VARCHAR(40),
	@optionTotal			INT,
	@totalFrom				DECIMAL(19,5),
	@totalTo				DECIMAL(19,5)
)
AS


BEGIN



	SET NOCOUNT ON



	------------------------------------------------------------------------------
	--PARAMETROS PARA PRUEBAS-----------------------------------------------------
	------------------------------------------------------------------------------
	/*
	declare		@comp_id			INT ,
				@lang_id			INT ,
				@bra_id				INT ,
				@curr_id			INT	,
				@ba_id				INT ,
				@guid				UNIQUEIDENTIFIER,
				@datefrom			DATETIME,
				@dateto				DATETIME,
				@optionNumber		INT,
				@numberFrom			VARCHAR(40),
				@optionTotal		INT,
				@totalFrom			DECIMAL(19,5),
				@totalTo			DECIMAL(19,5)

	select		@comp_id			= 1 ,
				@lang_id			= 2 ,
				@bra_id				= 1 ,
				@curr_id			= 1 ,
				@ba_id				= 31,
				@guid				= '3FF392FD-8FC9-4ABC-9A78-EC60E5AAD54A',
				@datefrom			='2000-01-01',
				@dateto				='9999-31-12',
				@optionNumber		=-1,
				@numberFrom			='',
				@optionTotal		=-1,
				@totalFrom			=0,
				@totalTo			=0
	*/
	------------------------------------------------------------------------------
	------------------------------------------------------------------------------








	-- -----------------------------------------------------------------------------------------------------------------
	-- Pongo en una tabla las Sucursales que pertenecen al grupo de sucursales de la actual sucursal incluida la actual.
	-- -----------------------------------------------------------------------------------------------------------------
	DECLARE @tbBranchsOfBranchGroup TABLE(bra_id INT)
	DECLARE @intBragID AS INT
	SELECT	@intBragID		= tb.brag_id
		FROM tbBranch tb								WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id
	INSERT INTO @tbBranchsOfBranchGroup (bra_id) VALUES (@bra_id)
	IF @intBragID IS NOT NULL
		BEGIN
			INSERT INTO @tbBranchsOfBranchGroup
				SELECT tbgd.bra_id
					FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
					WHERE	tbgd.comp_id = @comp_id		AND
							tbgd.brag_id = @intBragID	AND
							tbgd.bra_id <> @bra_id
		END
	-- -----------------------------------------------------------------------------------------------------------------



	-- --------------------------------------------------
	-- Permite seleccionar cheques de Otras Sucursales.?
	-- --------------------------------------------------
--	DECLARE @bitChequeOfAllBranches AS BIT
--	SELECT @bitChequeOfAllBranches = IsNull(tb.bra_PaymentsOfAllBranches43rdCheque,'False')
--		FROM tbBranch tb
--		WHERE	tb.comp_id	= @comp_id
--			AND tb.bra_id	= @bra_id
	-- --------------------------------------------------

	SELECT 	' ' [ ],
			cp.chp_isEditing,
			cp.chp_number,
			ct.ct_date,
			tc.curr_desc,
			convert(DECIMAL(19,2),cp.chp_total) [chp_total],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, cp.ct_transaction)	[doc],
			cp.chp_guid,
			cp.chp_PayDate,											--2010-07-28 - Parte 409
			tb.bra_desc,
			ISNULL(tcu.cust_name,'')															[cust_name],
			convert(VARCHAR,cp.comp_id)			+ '-' +
			convert(VARCHAR,cp.bra_id)			+ '-' +
			convert(VARCHAR,cp.ct_transaction)	+ '-' +
			convert(VARCHAR,cp.chp_id)			+ '-' +
			CASE WHEN cp.chp_guid = @guid THEN '1' ELSE '0' END									[ID]


	FROM 	dbo.tbCheckPortfolio							cp							WITH (NOLOCK)

			INNER JOIN dbo.tbCommercialTransactions			ct							WITH (NOLOCK)
			ON  ct.comp_id			= cp.comp_id
			--AND ct.bra_id			= cp.bra_id
			AND ct.ct_transaction	= cp.ct_transaction

			LEFT JOIN tbCustomer							tcu							WITH (NOLOCK)
				ON	tcu.comp_id		= ct.comp_id AND
					tcu.cust_id		= ct.cust_id

			INNER JOIN tbBranch tb														WITH (NOLOCK)
				ON		tb.comp_id	= ct.comp_id
					AND tb.bra_id	= ct.bra_id

			INNER JOIN tbsysCurrency						tc							WITH (NOLOCK)
			ON  cp.curr_id			= tc.curr_id

			INNER JOIN @tbBranchsOfBranchGroup tbg
					ON tbg.bra_id = cp.bra_id_PortFolio

			LEFT JOIN tbPaymentsRequest_CheckPortfolio tprcp							WITH (NOLOCK)
				ON	tprcp.comp_id				= cp.comp_id	AND
					tprcp.chp_id				= cp.chp_id	AND
					tprcp.preqchp_isProcessed	= 'False'

	WHERE   cp.comp_id				= @comp_id	AND
			tprcp.comp_id IS NULL				AND		-- que NO este en una Solicitud de OP. Si esta en la actual no va a aparecer y si lo borran y quieren volver a seleccionarlo, que la graben y vuelvan a entrar por forros !!!!
			ISNULL(cp.chp_isToOrder,'False')	= 'False'	--Agregado por Sebastian  --Ref: #1
	AND		cp.chp_isAvailable					= 'True'	-- Parte		: 753

	AND 	cp.chp_PayDate			between  @datefrom and	@dateto
	AND 	(
			(@optionNumber = -1)													or
			(@optionNumber = 0 and cp.chp_number like			@numberFrom + '%')	or
			(@optionNumber = 1 and cp.chp_number like '%' +		@numberFrom + '%')	or
			(@optionNumber = 2 and cp.chp_number =				@numberFrom)		or
			(@optionNumber = 3 and cp.chp_number <>				@numberFrom)		or
			(@optionNumber = 4 and cp.chp_number not like '%' +	@numberFrom + '%')
			)
	AND 	(
			(@optionTotal = -1)														or
			(@optionTotal = 0 and cp.chp_total = @totalFrom)						or
			(@optionTotal = 1 and cp.chp_total > @totalFrom)						or
			(@optionTotal = 2 and cp.chp_total < @totalFrom)						or
			(@optionTotal = 3 and cp.chp_total between @totalFrom and @totalTo)
			)

	ORDER BY  cp.chp_PayDate		--Ref: #1













	-- ====================================================================================================================
	-- Parte : 500 - ver arriba para detalle de trabajo
	-- ====================================================================================================================
	SELECT	COUNT(*),
			(SELECT ltrim(rtrim(tc2.curr_symbol)) FROM tbsysCurrency tc2 WHERE tc2.curr_id = @curr_id) + ' ' +
			ISNULL(
			convert(VARCHAR,
				convert(DECIMAL(19,2),
					SUM	(
						ISNULL(dbo.fnGetExchange2(@comp_id, cp.chp_total, cp.curr_id, @curr_id, 0, 0, 0, 'True'),0)
						)
					   )
				   ),'')

	FROM 	dbo.tbCheckPortfolio							cp				WITH (NOLOCK)

			INNER JOIN @tbBranchsOfBranchGroup tbg
				ON tbg.bra_id = cp.bra_id_PortFolio

			INNER JOIN dbo.tbCommercialTransactions			ct				WITH (NOLOCK)
			ON  ct.comp_id			= cp.comp_id
			AND ct.bra_id			= cp.bra_id
			AND ct.ct_transaction	= cp.ct_transaction

			INNER JOIN tbBranch tb
				ON		tb.comp_id	= ct.comp_id
					AND tb.bra_id	= ct.bra_id

			INNER JOIN tbsysCurrency						tc				WITH (NOLOCK)
			ON  cp.curr_id			= tc.curr_id


	--MOH - 15-05-2012 - igualé los where para que traigan los mismo + los últimos ands--
	WHERE   cp.comp_id				= @comp_id
	--AND     (cp.bra_id				= @bra_id OR (@bitChequeOfAllBranches = 'True' AND tb.bra_PaymentsOfAllBranches43rdCheque_Included = 'True' ))
	AND		ISNULL(cp.chp_isToOrder,'False')	= 'False'
	AND		cp.chp_isAvailable					= 'True'

	AND 	cp.chp_PayDate			between  @datefrom and	@dateto
	AND 	(
			(@optionNumber = -1)													or
			(@optionNumber = 0 and cp.chp_number like			@numberFrom + '%')	or
			(@optionNumber = 1 and cp.chp_number like '%' +		@numberFrom + '%')	or
			(@optionNumber = 2 and cp.chp_number =				@numberFrom)		or
			(@optionNumber = 3 and cp.chp_number <>				@numberFrom)		or
			(@optionNumber = 4 and cp.chp_number not like '%' +	@numberFrom + '%')
			)
	AND 	(
			(@optionTotal = -1)														or
			(@optionTotal = 0 and cp.chp_total = @totalFrom)						or
			(@optionTotal = 1 and cp.chp_total > @totalFrom)						or
			(@optionTotal = 2 and cp.chp_total < @totalFrom)						or
			(@optionTotal = 3 and cp.chp_total between @totalFrom and @totalTo)
			)

	AND		cp.chp_isEditing	= 'True'
	AND		cp.chp_guid			= @guid


	/*WHERE   cp.comp_id				= @comp_id
	AND     cp.bra_id				= @bra_id
	AND		cp.chp_isToOrder		= 'False'
	AND		cp.chp_isAvailable		= 'True'		-- Parte		: 753

	AND 	cp.chp_PayDate			between  @datefrom and	@dateto
	AND 	(
			(@optionNumber = -1)													or
			(@optionNumber = 0 and cp.chp_number like			@numberFrom + '%')	or
			(@optionNumber = 1 and cp.chp_number like '%' +		@numberFrom + '%')	or
			(@optionNumber = 2 and cp.chp_number =				@numberFrom)		or
			(@optionNumber = 3 and cp.chp_number <>				@numberFrom)		or
			(@optionNumber = 4 and cp.chp_number not like '%' +	@numberFrom + '%')
			)
	AND 	(
			(@optionTotal = -1)														or
			(@optionTotal = 0 and cp.chp_total = @totalFrom)						or
			(@optionTotal = 1 and cp.chp_total > @totalFrom)						or
			(@optionTotal = 2 and cp.chp_total < @totalFrom)						or
			(@optionTotal = 3 and cp.chp_total between @totalFrom and @totalTo)
			)*/

	-- ====================================================================================================================


END
GO







CREATE procedure [dbo].[spCheckPortfolio_getDataByFiltersEdit]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@cust_id				INT,
	@supp_id				INT,
	@datefrom				DATETIME,
	@dateto					DATETIME,
	@optionNumber			INT,
	@numberFrom				VARCHAR(40),
	@totalFrom				DECIMAL(19,5),
	@totalTo				DECIMAL(19,5),
	@optionTotal			INT,
	@ba_id					INT,
	@bn_id					INT,
	@chp_ispayed			INT,
	@chp_isElectronic		INT
)
AS




BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'

	-- ------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------
	/*
	declare		@comp_id			INT ,
				@lang_id			INT ,
				@bra_id				INT ,
				@cust_id			INT	,
				@supp_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME,
				@optionNumber		INT,
				@numberFrom			VARCHAR(40),
				@totalFrom			DECIMAL(19,5),
				@totalTo			DECIMAL(19,5),
				@optionTotal		INT,
				@ba_id				INT,
				@bn_id				INT,
				@chp_ispayed		INT


	select		@comp_id			= 1 ,
				@lang_id			= 2 ,
				@bra_id				= -1 ,
				@cust_id			= -1 ,
				@supp_id			= -1,
				@datefrom			='2000-01-01',
				@dateto				='9999-12-31',
				@optionNumber		=-1,
				@numberFrom			='',
				@totalFrom			=-99999999,
				@totalTo			=999999999,
				@optionTotal		=-1,
				@ba_id				=-1,
				@bn_id				= -1,
				@chp_ispayed		= -1
*/
	-- ------------------------------------------------------------------------------



	SELECT 	' ' [ ],
			' ' [ ],
			cp.chp_number,
			convert(DECIMAL(19,2),cp.chp_total)										[chp_total],
			tc.curr_desc,
			cp.chp_PayDate,
			dbo.fnGetCommercialTransactionDescription(ct.comp_id,2,ct.ct_transaction)	[Description],
			tbn.bn_name,
			cp.chp_BankBranch,

			cp.chp_isNegociated,
			cp.chp_taxNumber1,
			cp.chp_taxNumber2,
			cp.chp_taxNumber3,
			cp.chp_isOwn,
			cp.chp_isToOrder,
			cp.chp_isRejected,
			cp.chp_isCancelled,
			cp.chp_IsPayed,
			cp.chp_isAvailable,
			cp.chp_BankBranchDescription,
			tc2.cust_name,
			CASE WHEN cp.chp_isAvailable = 'true' THEN ''
				 ELSE dbo.fnChequePortfolioPayToBanking(cp.comp_id,cp.chp_id)
			END																		[ba_desc],
			dbo.fnChequePortfolioPayToSupplier(cp.comp_id,cp.chp_id)				[supp_name],
			tbActual.bra_desc														[ActualBranch],
			tb.bra_desc,
			cp.chp_Note,
			tba.ba_desc																[ba_desc4Custody],
			dbo.fnStrPADL( convert(nvarchar(10),IsNull(tprcp.preq_id,0)),10,'0')	[PaymentRequestBranch],

			ISNULL(cp.chp_AccountNumber,'')											[chp_AccountNumber],
			ISNULL(cp.chp_Titular,'')												[chp_Titular],
			cp.chp_isDocument,
			cp.chp_documentNumber,
			ISNULL(cp.chp_isElectronic,'False')										[chp_isElectronic],
			cp.chp_id																[ID]


	FROM 	dbo.tbCheckPortfolio							cp

			INNER JOIN dbo.tbCommercialTransactions			ct
			ON  ct.comp_id			= cp.comp_id
			--AND ct.bra_id			= cp.bra_id
			AND ct.ct_transaction	= cp.ct_transaction

			INNER JOIN tbsysCurrency						tc
			ON  cp.curr_id			= tc.curr_id

			INNER JOIN tbBanksName							tbn
			ON  tbn.comp_id			= cp.comp_id
			AND tbn.country_id		= cp.country_id
			AND tbn.bn_id			= cp.bn_id

			LEFT JOIN tbBankingAccounts						tba
			ON	tba.comp_id			= cp.comp_id
			AND tba.ba_id			= cp.ba_id

			left JOIN tbBankingTransactions					tbt
			ON	tbt.comp_id			= cp.comp_id
			AND tbt.chp_id			= cp.chp_id
			AND tbt.btt_id			= 1000020
			AND IsNull(tbt.bt_isCancelled,'False') = 'False'

			LEFT JOIN tbCustomer							tc2
			ON  tc2.comp_id			= ct.comp_id
			AND tc2.cust_id			= ct.cust_id

			INNER JOIN tbBranch tb
				ON		tb.comp_id	= ct.comp_id
					AND tb.bra_id	= ct.bra_id

			INNER JOIN tbBranch tbActual
				ON		tbActual.comp_id	= cp.comp_id
					AND tbActual.bra_id		= cp.bra_id_PortFolio

			LEFT JOIN tbPaymentsRequest_CheckPortfolio tprcp
				ON	tprcp.comp_id	= cp.comp_id AND
					tprcp.chp_id	= cp.chp_id



	WHERE   cp.comp_id			= @comp_id
	AND		(@cust_id			= -1   OR	 ct.cust_id			= @cust_id	)
	and     (@supp_id			= -1   or    dbo.fnChequePortfolioPayToSupplierId(cp.comp_id,cp.chp_id)	= @supp_id	)
	AND		(@bra_id			= -1   OR	 cp.bra_id			= @bra_id)

	AND 	cp.chp_PayDate			between  @datefrom and	@dateto


	AND 	(
			(@optionNumber = -1)													or
			(@optionNumber = 0 and cp.chp_number like			@numberFrom + '%')	or
			(@optionNumber = 1 and cp.chp_number like '%' +		@numberFrom + '%')	or
			(@optionNumber = 2 and cp.chp_number =				@numberFrom)		or
			(@optionNumber = 3 and cp.chp_number <>				@numberFrom)		or
			(@optionNumber = 4 and cp.chp_number not like '%' +	@numberFrom + '%')
			)
	AND 	(
			(@optionTotal = -1)														or
			(@optionTotal = 0 and cp.chp_total = @totalFrom)						or
			(@optionTotal = 1 and cp.chp_total > @totalFrom)						or
			(@optionTotal = 2 and cp.chp_total < @totalFrom)						or
			(@optionTotal = 3 and cp.chp_total between @totalFrom and @totalTo)
			)
	and		(@bn_id				= -1   or    tbn.bn_id				= @bn_id)
	AND     (@chp_ispayed		= -1   or    cp.chp_IsPayed			= @chp_ispayed)
	and     (@ba_id				= -1   or    tbt.ba_id				= @ba_id)		AND
			(
				@chp_isElectronic	= -1 OR
				cp.chp_isElectronic = @chp_isElectronic
			)


	ORDER BY cp.chp_PayDate, cp.chp_number


END























GO












CREATE PROCEDURE [dbo].[spCheckPortfolio_getDataById]
(
			@chp_id			int
)
as
set nocount on

select
			comp_id,
			chp_id,
			bra_id,
			ct_transaction,
			chp_number,
			chp_total,
			chp_EmissionDate,
			chp_PayDate,
			bn_id,
			chp_BankBranch,
			isnull(chp_BankBranchDescription,'')		[chp_BankBranchDescription],
			isnull(chp_AccountNumber,'')				[chp_AccountNumber],
			chp_taxNumber1,
			chp_taxNumber2,
			chp_taxNumber3,
			chp_isOwn,
			chp_isAvailable,
			chp_IsPayed,
			chp_isRejected,
			chp_isToOrder,
			chp_Note,
			curr_id,
			country_id,
			chp_QtyEndosos,
			bra_id_PortFolio,
			isnull(ba_id,-1)							[ba_id],
			chp_image,
			ISNULL(chp_isElectronic,'False')			[chp_isElectronic]


from	dbo.tbCheckPortfolio

where	chp_id = @chp_id






















GO






CREATE PROCEDURE [dbo].[spCheckPortfolio_GetdataChecks]
(
	@comp_id     INT,
	@lang_id     INT,
	@Option      INT,
	@CustSupp	 INT
)
AS

BEGIN

/*
DECLARE @comp_id     INT,
		@lang_id     INT,
		@Option      INT,
		@valueOreder INT,
		@CustSupp	 INT

SELECT  @comp_id     =  1,
		@lang_id     =  2,
		@Option	     = 0,
		@CustSupp  =  -1
*/

SELECT ' ' [ ],
	   dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)	[DESC],
	   tcp1.chp_EmissionDate,
	   tcp1.chp_PayDate,
	   tcp1.chp_Note,
	   convert(varchar,tcp1.chp_id) + ' | ' + CONVERT(VARCHAR,isnull(tct.cust_id,tct.supp_id)) [ID]


FROM tbCommercialTransactions tct

INNER JOIN tbCheckPortfolio tcp1
ON  tcp1.comp_id		= tct.comp_id
AND tcp1.bra_id			= tct.bra_id
AND tcp1.ct_transaction = tct.ct_transaction

INNER JOIN tbEmmitedChecks tec
ON tec.comp_id = tct.comp_id
AND tec.bra_id = tct.bra_id

WHERE tct.comp_id = @comp_id
AND  (
	   @Option = -1 OR
	   (@Option =  0 AND (@CustSupp = -1  AND not tct.cust_id is NULL) OR (tct.cust_id = @CustSupp) ) OR
	   (@Option =  1 AND (@CustSupp = -1  AND not tct.supp_id is NULL) OR (tct.supp_id = @CustSupp) )
	 )
END
GO








CREATE PROCEDURE [dbo].[spCheckPortfolio_getDataLisAcredit]
(
	@comp_id				INT,
	@lang_id				INT,
	@datefrom				DATETIME,
	@dateto					DATETIME,
	@optionNumber			INT,
	@numberFrom				VARCHAR(40),
	@optionTotal			INT,
	@totalFrom				DECIMAL(19,5),
	@totalTo				DECIMAL(19,5),
	@curr_id				INT,
	@update					BIT,
	@guid					UNIQUEIDENTIFIER,
	@ba_id					INT,
	@bra_id					INT
)
AS


BEGIN

	SET NOCOUNT ON


-- --------------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------------
/*
	DECLARE	@comp_id				int,
			@lang_id				int,
			@datefrom				datetime,
			@dateto					datetime,
			@optionNumber			int,
			@numberFrom				varchar(40),
			@optionTotal			int,
			@totalFrom				decimal(19,5),
			@totalTo				decimal(19,5),
			@curr_id				int,
			@update					BIT,
			@guid					UNIQUEIDENTIFIER,
			@ba_id int,
			@bra_id	int

	SELECT	@comp_id				=	1,
			@lang_id				=	2,
			@DateFrom				=	'1900-01-01',
			@DateTo					=	'9999-01-01',
			@optionNumber			=	-1,
			@numberFrom				=	'',
			@optionTotal			=	-1,
			@totalFrom				=	0,
			@totalTo				=	0,
			@curr_id				=	1,
			@update					='true',
			@guid					='ecbd4168-f466-47fc-9e3d-b5e5018388a8',
			@ba_id					=34,
			@bra_id					= 1
*/
-- --------------------------------------------------------------------------



		-- -----------------------------------------------------------------------------------------------------------------
		-- Pongo en una tabla las Sucursales que pertenecen al grupo de sucursales de la actual sucursal incluida la actual.
		-- -----------------------------------------------------------------------------------------------------------------
		DECLARE @bitBranchsOfGroup AS BIT = 'False'
		IF @bra_id < 0
			BEGIN
				SET @bra_id				= @bra_id * -1
				SET @bitBranchsOfGroup	= 'True'
			END
		DECLARE @tbBranchsOfBranchGroup TABLE(bra_id INT PRIMARY KEY)
		DECLARE @intBragID AS INT
		SELECT @intBragID = tb.brag_id
			FROM tbBranch tb	WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id
		INSERT INTO @tbBranchsOfBranchGroup (bra_id) VALUES (@bra_id)
		IF	@intBragID IS NOT NULL AND
			@bitBranchsOfGroup = 'True'
			BEGIN
				INSERT INTO @tbBranchsOfBranchGroup
					SELECT DISTINCT  tbgd.bra_id
						FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
						WHERE	tbgd.comp_id = @comp_id		AND
								tbgd.brag_id = @intBragID	AND
								tbgd.bra_id <> @bra_id
			END
		-- -----------------------------------------------------------------------------------------------------------------




	/*si la marca update es true se eliminan las marcas de cheque en proceso*/
	IF @update = 'true'

		UPDATE	dbo.tbCheckPortfolio
		SET		chp_isInProcess		= 'False',
				chp_guid			= NULL
		WHERE	comp_id				= @comp_id
		and		chp_isAvailable		= 'False'
		and		chp_isPayed			= 'False'





	/*obtenemos los cheques para acreditar*/
	SELECT	' '																								[ ],
			convert(bit,len(isnull(convert(VARCHAR(36),tcp1.chp_guid),'')))									[state_desc],
			tcp1.chp_PayDate,
			case when len(tbn.bn_name) > 25 THEN SUBSTRING(tbn.bn_name,0,22) + '...' ELSE tbn.bn_name END	[bn_name],
			tcp1.chp_number,
			tcp1.chp_total,

			tcp1.chp_id

	FROM	dbo.tbCheckPortfolio					tcp1

			LEFT JOIN tbBanksName					tbn
			ON	tbn.comp_id			= tcp1.comp_id
			AND tbn.bn_id			= tcp1.bn_id

			INNER JOIN tbBankingAccounts			tba
			ON		tba.comp_id		= tcp1.comp_id
				AND tba.ba_id		= (SELECT tbt.ba_id
											FROM tbBankingTransactions tbt
											WHERE tbt.bt_id =
												  (	SELECT MAX(tbt2.bt_id)
														FROM tbBankingTransactions tbt2
												   		WHERE
												   			tbt2.comp_id			= tcp1.comp_id
												   			AND tbt2.chp_id			= tcp1.chp_id
												   			and tbt2.bt_isCancelled	= 'false' )
									  )

			Inner JOIN tbCommercialTransactions tct
				ON	tct.comp_id			= tcp1.comp_id AND
					tct.ct_transaction	= tcp1.ct_transaction


			INNER JOIN @tbBranchsOfBranchGroup tbg
				ON tbg.bra_id = tcp1.bra_id_PortFolio  --tct.bra_id

	WHERE	tcp1.comp_id		= @comp_id
	and	    tcp1.curr_id		= @curr_id
	and		tcp1.chp_PayDate	between  @datefrom and	@dateto

	and		(
			(@optionNumber = -1)													or
			(@optionNumber = 0 and tcp1.chp_number like @numberFrom + '%')			or
			(@optionNumber = 1 and tcp1.chp_number like '%' +  @numberFrom + '%')	or
			(@optionNumber = 2 and tcp1.chp_number = @numberFrom)					or
			(@optionNumber = 3 and tcp1.chp_number <> @numberFrom)					or
			(@optionNumber = 4 and tcp1.chp_number not like '%' +  @numberFrom + '%')
			)
	and		(
			(@optionTotal = -1)														or
			(@optionTotal = 0 and tcp1.chp_total = @totalFrom)						or
			(@optionTotal = 1 and tcp1.chp_total > @totalFrom)						or
			(@optionTotal = 2 and tcp1.chp_total < @totalFrom)						or
			(@optionTotal = 3 and tcp1.chp_total between @totalFrom and @totalTo)
			)

	and		tcp1.chp_isAvailable					= 'false'
	and		tcp1.chp_IsPayed						= 'false'
	AND     ISNULL(tcp1.chp_isRejected,'False')		= 'False'
	AND     ISNULL(tcp1.chp_isCancelled,'False')	= 'False'
	AND     tba.ba_id				= @ba_id

	ORDER BY tcp1.chp_PayDate,tcp1.chp_total







	/*obtenemos una segunda tabla con el total seleccionado en la grilla*/
	SELECT	COUNT(*)
	--SELECT ISNULL(SUM(tcp1.chp_total),0)
	FROM	tbCheckPortfolio		tcp1

	WHERE 	tcp1.comp_id							= @comp_id
	AND 	tcp1.chp_isAvailable					= 'false'
	AND 	tcp1.chp_isPayed						= 'False'
	--AND		isnull(tcp1.chp_isInProcess,'false')	= 'true'
	AND		tcp1.chp_guid							= @guid
	--23/07/2010 --> el chp_isInProcess si tiene null se le fuerza el false para que traiga datos.



END
GO




-- se agregó la columna chp_isElectronic tkt 21584 . GA . 24/06/24


CREATE PROCEDURE [dbo].[spCheckPortfolio_getDataList]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@datefrom				DATETIME,
	@dateto					DATETIME,
	@optionNumber			INT,
	@numberFrom				VARCHAR(40),
	@optionTotal			INT,
	@totalFrom				DECIMAL(19,5),
	@totalTo				DECIMAL(19,5),
	@curr_id				INT,
	@update					BIT,
	@guid					UNIQUEIDENTIFIER,
	@ba_id					INT,
	@bitIs4Negociate		BIT
)
AS


BEGIN



	SET NOCOUNT ON

	-- -------------------------------------------------------------------------------
	-- Testng
	-- -------------------------------------------------------------------------------
		/*
		DECLARE	@comp_id				int,
				@lang_id				int,
				@datefrom				datetime,
				@dateto					datetime,
				@optionNumber			int,
				@numberFrom				varchar(40),
				@optionTotal			int,
				@totalFrom				decimal(19,5),
				@totalTo				decimal(19,5),
				@curr_id				int,
				@update					BIT,
				@guid					UNIQUEIDENTIFIER,
				@bra_id					int,
				@ba_id					int


		SELECT	@comp_id				=	1,
				@lang_id				=	2,
				@DateFrom				=	'2013-04-05',
				@DateTo					=	'9999-01-01',
				@optionNumber			=	-1,
				@numberFrom				=	'',
				@optionTotal			=	-1,
				@totalFrom				=	0,
				@totalTo				=	0,
				@curr_id				=	1,
				@update					= 'True',
				@bra_id					= 1,
				@ba_id					= 40
	*/
	-- -------------------------------------------------------------------------------





	-- --------------------------------------------------------
	-- Si esta deshabilitado el control de concurrencia...
	-- --------------------------------------------------------
	IF NOT EXISTS(
				SELECT 1
					FROM tbBranch tb					WITH (NOLOCK)
					WHERE	tb.comp_id								= @comp_id	AND
							tb.bra_Payments_DisableConcurrencyBlock = 'True'
				 )
		BEGIN

			/*si la marca update es true se eliminan las marcas de cheque en proceso*/
			IF @update = 'true'
				BEGIN
					UPDATE	dbo.tbCheckPortfolio
						SET		chp_isInProcess		= 'False'--,
								--chp_guid			= NULL
						WHERE	comp_id				= @comp_id
						and		chp_isAvailable		= 'True'
						and		chp_isPayed			= 'False'
				END
		END
	-- --------------------------------------------------------




		-- --------------------------------------------------
		-- Permite seleccionar cheques de Otras Sucursales.?
		-- Solapa PAGOS de Sucursales.!!!!!
		-- --------------------------------------------------
--		DECLARE @bitChequeOfAllBranches AS BIT
--		SELECT @bitChequeOfAllBranches = IsNull(tb.bra_PaymentsOfAllBranches43rdCheque,'False')
--			FROM tbBranch tb
--			WHERE	tb.comp_id	= @comp_id
--				AND tb.bra_id	= @bra_id
		-- --------------------------------------------------

		---- -----------------------------------------------------------------------------------------------------------------
		---- Pongo en una tabla las Sucursales que pertenecen al grupo de sucursales de la actual sucursal incluida la actual.
		---- -----------------------------------------------------------------------------------------------------------------
		--DECLARE @tbBranchsOfBranchGroup TABLE(bra_id INT PRIMARY KEY)
		--DECLARE @intBragID AS INT
		--SELECT @intBragID = tb.brag_id
		--	FROM tbBranch tb								WITH (NOLOCK)
		--	WHERE	tb.comp_id	= @comp_id AND
		--			tb.bra_id	= @bra_id
		--INSERT INTO @tbBranchsOfBranchGroup (bra_id) VALUES (@bra_id)
		--IF @intBragID IS NOT NULL
		--	BEGIN
		--		INSERT INTO @tbBranchsOfBranchGroup
		--			SELECT DISTINCT tbgd.bra_id
		--				FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
		--				WHERE	tbgd.brag_id = @intBragID AND
		--						tbgd.bra_id <> @bra_id
		--	END
		---- -----------------------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------------------------------
		-- Pongo en una tabla las Sucursales que pertenecen al grupo de sucursales de la actual sucursal incluida la actual.
		-- -----------------------------------------------------------------------------------------------------------------
		DECLARE @bitBranchsOfGroup AS BIT = 'False'
		IF @bra_id < 0
			BEGIN
				SET @bra_id				= @bra_id * -1
				SET @bitBranchsOfGroup	= 'True'
			END
		DECLARE @tbBranchsOfBranchGroup TABLE(bra_id INT PRIMARY KEY)
		DECLARE @intBragID AS INT
		SELECT @intBragID = tb.brag_id
			FROM tbBranch tb	WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id
		INSERT INTO @tbBranchsOfBranchGroup (bra_id) VALUES (@bra_id)
		IF	@intBragID IS NOT NULL AND
			@bitBranchsOfGroup = 'True'
			BEGIN
				INSERT INTO @tbBranchsOfBranchGroup
					SELECT DISTINCT  tbgd.bra_id
						FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
						WHERE	tbgd.comp_id = @comp_id		AND
								tbgd.brag_id = @intBragID	AND
								tbgd.bra_id <> @bra_id
			END
		-- -----------------------------------------------------------------------------------------------------------------



		DECLARE @ltext_cantidad AS VARCHAR(80)
		DECLARE @ltext_importe	AS VARCHAR(80)
		--texto "Cantidad:"
		SET @ltext_cantidad = (select tut.utexts_desc FROM tbsysUniqueTexts tut WITH (NOLOCK) WHERE tut.lang_id = @lang_id AND tut.utexts_id = 7000)
		--texto "Importe:"
		SET @ltext_importe  = (select tut.utexts_desc FROM tbsysUniqueTexts tut WITH (NOLOCK) WHERE tut.lang_id = @lang_id AND tut.utexts_id = 7001)





	/*obtenemos los cheques habilitados para el depósito*/
	SELECT	 ' '																											[ ],
			isnull(tcp1.chp_isInProcess,'False')																			[state_desc],
			tcp1.chp_PayDate																								[chp_PayDate],
--			case
--				when len(tbn.bn_name) > 30 THEN SUBSTRING(tbn.bn_name,0,27) + '...'
--				ELSE tbn.bn_name
--			END
			tbn.bn_name																										[bn_name],
			tcp1.chp_number																									[chp_number],
			tcp1.chp_total,
			ISNULL(tcp1.chp_isElectronic,'False')																			[chp_isElectronic],
			tov.optval_desc,
			tb.bra_desc,
			tb1.bra_desc																									[bra_id_PortFolio],
			IsNull(tc.cust_name,'')																							[cust_name],
			CASE
			    WHEN @bitIs4Negociate = 'True' THEN dbo.fnGetCheckPortfolio_ImportCuit(@comp_id,@lang_id,@ba_id,tcp1.chp_taxNumber1,tcp1.chp_taxNumber2,tcp1.chp_taxNumber3,@ltext_importe,@ltext_cantidad)
			    ELSE '*'
			END																												[Cuit_Import],
			tcp1.chp_id

		FROM	dbo.tbCheckPortfolio					tcp1

				INNER JOIN tbsysOptionsValues			tov									WITH (NOLOCK)
					ON	tov.lang_id			= @lang_id
					AND tov.optval_class	= 1
					AND tov.optval_id		= convert(int,ISNULL(tcp1.chp_isToOrder,0))

				LEFT JOIN tbBanksName							tbn							WITH (NOLOCK)
					ON	tbn.comp_id			= tcp1.comp_id
					AND tbn.bn_id			= tcp1.bn_id

				INNER JOIN tbBranch tb														WITH (NOLOCK)
					ON	tb.comp_id	= tcp1.comp_id AND
						tb.bra_id	= tcp1.bra_id

				INNER JOIN tbBranch tb1														WITH (NOLOCK)
					ON	tb1.comp_id	= tcp1.comp_id AND
						tb1.bra_id	= tcp1.bra_id_PortFolio

				LEFT JOIN tbCommercialTransactions tct										WITH (NOLOCK)
					ON	tct.comp_id			= tcp1.comp_id AND
						tct.ct_transaction	= tcp1.ct_transaction

				LEFT JOIN tbCustomer tc														WITH (NOLOCK)
					ON		tc.comp_id = tct.comp_id
						AND tc.cust_id = tct.cust_id

				INNER JOIN @tbBranchsOfBranchGroup tbg
					ON tbg.bra_id = tcp1.bra_id_PortFolio

				LEFT JOIN tbPaymentsRequest_CheckPortfolio tprcp							WITH (NOLOCK)
					ON	tprcp.comp_id				= tcp1.comp_id	AND
						tprcp.chp_id				= tcp1.chp_id	AND
						tprcp.preqchp_isProcessed	= 'False'


		WHERE	tcp1.comp_id		= @comp_id	AND
			    tcp1.curr_id		= @curr_id	AND
			    tprcp.comp_id IS NULL			AND		-- que NO este en una Solicitud de OP
			   (tcp1.chp_PayDate	between  @datefrom and	@dateto) AND
				CASE
		   		    WHEN @optionNumber = -1 THEN 'True'
		   		    WHEN @optionNumber =  0 and tcp1.chp_number like @numberFrom + '%'			THEN 'True'
		   		    WHEN @optionNumber =  1 and tcp1.chp_number like '%' +  @numberFrom + '%'	THEN 'True'
		   		    WHEN @optionNumber =  2 and tcp1.chp_number = @numberFrom					THEN 'True'
		   		    WHEN @optionNumber =  3 and tcp1.chp_number <> @numberFrom					THEN 'True'
		   		    WHEN @optionNumber =  4 and tcp1.chp_number not like '%' + @numberFrom + '%' THEN 'True'
		   		    ELSE	'False'
		   		END	= 'True'	AND



				CASE
				    WHEN @optionTotal = -1														THEN 'True'
				    WHEN @optionTotal = 0 and tcp1.chp_total = @totalFrom						THEN 'True'
				    WHEN @optionTotal = 1 and tcp1.chp_total > @totalFrom						THEN 'True'
				    WHEN @optionTotal = 2 and tcp1.chp_total < @totalFrom						THEN 'True'
				    WHEN @optionTotal = 3 and tcp1.chp_total between @totalFrom and @totalTo	THEN 'True'
				    ELSE																			 'False'
				END	= 'True' AND



		 		tcp1.chp_isAvailable					= 'True'	AND
		 		tcp1.chp_isPayed						= 'False'	AND
				ISNULL(tcp1.chp_isCancelled,'False')	= 'False'	AND
				( tcp1.ba_id IS NULL OR tcp1.ba_id = @ba_id )		-- Custodia en banco

	ORDER BY tcp1.chp_PayDate,tcp1.chp_total








	/*obtenemos una segunda tabla con el total seleccionado en la grilla*/
	SELECT	ISNULL(SUM(tcp1.chp_total),0)
		FROM	tbCheckPortfolio		tcp1				WITH (NOLOCK)
		WHERE 	tcp1.comp_id			= @comp_id
		AND 	tcp1.chp_isAvailable	= 'True'
		AND 	tcp1.chp_isPayed		= 'False'
		AND		tcp1.chp_isInProcess	= 'true'
		AND		tcp1.chp_guid			= @guid



END
GO






CREATE PROCEDURE [dbo].[spCheckPortfolio_getList]
(
		@comp_id				int,
		@lang_id				int,
		@datefrom				datetime,
		@dateto					datetime,
		@optionNumber			int,
		@numberFrom				varchar(40),
		@optionTotal			int,
		@totalFrom				decimal(19,5),
		@totalTo				decimal(19,5),
		@curr_id				int

)
as

set nocount on

/*
DECLARE
				@comp_id				int,
				@lang_id				int,
				@datefrom				datetime,
				@dateto					datetime,
				@optionNumber			int,
				@numberFrom				varchar(40),
				@optionTotal			int,
				@totalFrom				decimal(19,5),
				@totalTo				decimal(19,5),
				@curr_id				int

SELECT
				@comp_id				=	1,
				@lang_id				=	2,
				@DateFrom				=	'2000-01-01',
				@DateTo					=	'9999-01-01',
				@optionNumber			=	-1,
				@numberFrom				=	'',
				@optionTotal			=	3,
				@totalFrom				=	30.5,
				@totalTo				=	128.1,
				@curr_id				=	1
*/

SELECT
			chp_id [id],
			chp_number + ' - ' +
			convert(varchar(10),chp_PayDate,103) + ' - ' +
			convert(varchar(15),chp_total) [desc]


FROM	dbo.tbCheckPortfolio

WHERE	comp_id		= @comp_id
and	    curr_id		= @curr_id
and		chp_PayDate	between  @datefrom and	@dateto
and		(
		(@optionNumber = -1)												or
		(@optionNumber = 0 and chp_number like @numberFrom + '%')			or
		(@optionNumber = 1 and chp_number like '%' +  @numberFrom + '%')	or
		(@optionNumber = 2 and chp_number = @numberFrom)					or
		(@optionNumber = 3 and chp_number <> @numberFrom)					or
		(@optionNumber = 4 and chp_number not like '%' +  @numberFrom + '%')
		)
and		(
		(@optionTotal = -1)													or
		(@optionTotal = 0 and chp_total = @totalFrom)						or
		(@optionTotal = 1 and chp_total > @totalFrom)						or
		(@optionTotal = 2 and chp_total < @totalFrom)						or
		(@optionTotal = 3 and chp_total between @totalFrom and @totalTo)
		)

and chp_isAvailable = 'True'
and chp_isPayed		= 'False'

GO







