CREATE Procedure [dbo].[spCheckPortfolio_getReportChecks]
(
	@comp_id				INT,
	@lang_id				INT,
	@page_id				INT,
	@ct_transaction			INT,
	@bra_id					INT
)
AS
SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


/*
DECLARE @comp_id		INT,
		@lang_id		INT,
		@page_id		INT,
		@curr_id		INT,
		@ct_transaction	INT

SELECT	@comp_id		= 1,
		@lang_id		= 2,
		@page_id		= 10001,
		@ct_transaction = 7227
*/



SELECT  tbn.bn_name													[bn_name2],
		isnull(tba.ba_desc,'')										[ba_desc],
		tct.ct_docNumber,
		tcp1.chp_PayDate,
		tbn.bn_id,
		tbn2.bn_name,
		tcp1.chp_number,
		convert(decimal(18,2),tcp1.chp_total)						[chp_total],
		tcp1.chp_id,
		tc.curr_symbol,
		tc2.cust_taxNumber											[cust_taxnumber],
		tc2.cust_name												[cust_name],
		tcp1.chp_BankBranch											[chp_BankBranch],
		rtrim(convert(varchar,tc.curr_symbol)) + ' ' +
		convert(VARCHAR,(convert(decimal(18,2),tcp1.chp_total)))	[total],
		ISNULL(tba.ba_Note4BankDepositReport,'')					[ba_Note4BankDepositReport]


FROM	tbBankingTransactions							tbt

		INNER JOIN tbCheckPortfolio						tcp1
		ON	tcp1.comp_id		= tbt.comp_id
		AND tcp1.chp_id			= tbt.chp_id

		INNER JOIN tbCommercialTransactions				tct
		ON	tct.comp_id			= tbt.comp_id
		AND tct.ct_transaction	= tbt.ct_transaction

		LEFT  JOIN tbBanksName							tbn2
		ON	tbn2.comp_id		= tcp1.comp_id
		AND tbn2.bn_id			= tcp1.bn_id
		AND tbn2.country_id		= tcp1.country_id

		inner JOIN tbBankingAccounts					tba
		ON  tba.comp_id			= tbt.comp_id
		AND tba.ba_id			= tbt.ba_id

		left join tbBanksName							tbn
		on  tba.comp_id			= tbn.comp_id
		and tba.country_id		= tbn.country_id
		and tba.bn_id			= tbn.bn_id

		INNER JOIN tbsysCurrency						tc
		ON	tc.curr_id			= tcp1.curr_id


		INNER JOIN tbCommercialTransactions tct2
		ON tct2.comp_id = tbt.comp_id
		AND tct2.ct_transaction = tcp1.ct_transaction


		INNER JOIN tbCustomer							tc2
		ON tc2.comp_id		    = tbt.comp_id
		AND tc2.cust_id			= tct2.cust_id


WHERE  tbt.comp_id		  = @comp_id
AND	   tbt.ct_transaction = @ct_transaction

ORDER BY tcp1.chp_isInProcess_Order ASC


exec [spReports_getData3]	@comp_id,	@bra_id ,	@lang_id, @page_id


--exec [spReports_getData]	@comp_id,				@lang_id, @page_id
GO








CREATE Procedure [dbo].[spCheckPortfolio_getReportChecks4GenericGrid]
(
	@comp_id				INT,
	@lang_id				INT,
	@ct_transaction			INT
)
AS

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- --------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------
	/*
	DECLARE @comp_id		INT,
			@lang_id		INT,
			@page_id		INT,
			@curr_id		INT,
			@ct_transaction	INT

	SELECT	@comp_id		= 1,
			@lang_id		= 2,
			@page_id		= 10001,
			@ct_transaction = 7227
	*/
	-- --------------------------------------------------------


	SELECT
			isnull(tba.ba_desc,'')										[ba_desc],
			tbn.bn_id,
			tbn.bn_name													[bn_name2],
			tct.ct_docNumber,
			tbn2.bn_name												[bn_name_Cheque],
			tcp1.chp_EmissionDate,
			tcp1.chp_PayDate,
			tcp1.chp_number,
			tcp1.chp_BankBranch,
			tcp1.chp_BankBranchDescription,
			tcp1.chp_AccountNumber,
			convert(decimal(18,2),tcp1.chp_total)						[chp_total],
			tcp1.chp_id,
			tc.curr_symbol,
			rtrim(convert(varchar,tc.curr_symbol)) + ' ' +
			convert(VARCHAR,(convert(decimal(18,2),tcp1.chp_total)))	[total],
			tcp1.chp_Titular,
			tcp1.chp_taxNumber1,
			tcp1.chp_taxNumber2,
			tcp1.chp_taxNumber3,
			tcp1.chp_isOwn,
			tcp1.chp_Note,
			tcp1.chp_DocumentDescription,
			tc2.cust_taxNumber											[cust_taxnumber],
			tc2.cust_name												[cust_name]


	FROM	tbBankingTransactions							tbt

			INNER JOIN tbCheckPortfolio						tcp1
			ON	tcp1.comp_id		= tbt.comp_id
			AND tcp1.chp_id			= tbt.chp_id

			INNER JOIN tbCommercialTransactions				tct
			ON	tct.comp_id			= tbt.comp_id
			AND tct.ct_transaction	= tbt.ct_transaction

			LEFT  JOIN tbBanksName							tbn2
			ON	tbn2.comp_id		= tcp1.comp_id
			AND tbn2.bn_id			= tcp1.bn_id
			AND tbn2.country_id		= tcp1.country_id

			inner JOIN tbBankingAccounts					tba
			ON  tba.comp_id			= tbt.comp_id
			AND tba.ba_id			= tbt.ba_id

			left join tbBanksName							tbn
			on  tba.comp_id			= tbn.comp_id
			and tba.country_id		= tbn.country_id
			and tba.bn_id			= tbn.bn_id

			INNER JOIN tbsysCurrency						tc
			ON	tc.curr_id			= tcp1.curr_id


			INNER JOIN tbCommercialTransactions tct2
			ON tct2.comp_id = tbt.comp_id
			AND tct2.ct_transaction = tcp1.ct_transaction


			INNER JOIN tbCustomer							tc2
			ON tc2.comp_id		    = tbt.comp_id
			AND tc2.cust_id			= tct2.cust_id


	WHERE  tbt.comp_id		  = @comp_id
	AND	   tbt.ct_transaction = @ct_transaction

	ORDER BY tcp1.chp_isInProcess_Order ASC



END
GO






CREATE PROCEDURE [dbo].[spCheckPortfolio_getValNegociated]
(

		@comp_id				int,
		@lang_id				int,
		@ba_id					int

)
as


BEGIN
		set nocount on


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
/*
		DECLARE		@comp_id				int,
					@lang_id				int,
					@ba_id					int


		SELECT		@comp_id				= 1,
					@ba_id					= 31,
					@lang_id				= 2

*/
	-- -------------------------------------------------------------------------------
	--
	-- -------------------------------------------------------------------------------

		DECLARE		@ltext_importe	VARCHAR(200),
					@ltext_cantidad	VARCHAR(200)

		--texto "Cantidad:"
		SET @ltext_cantidad = (select tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 7000)
		--texto "Importe:"
		SET @ltext_importe = (select tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 7001)


		select  convert(varchar,@ltext_cantidad)+ ' ' + + convert(varchar,count(*)) + ' ' + convert(varchar,@ltext_importe)+ ' ' + + convert(varchar,isnull(sum(tcp1.chp_total),0)) [Importe]


			from tbCheckPortfolio						tcp1		WITH (NOLOCK)

			inner join tbCheckPortfolioMovements		tcpm		WITH (NOLOCK)
			on  tcpm.comp_id	= tcp1.comp_id AND
				tcpm.chp_id		= tcp1.chp_id

			inner join tbBranch							tb			WITH (NOLOCK)
			on  tb.bra_id		= tcp1.comp_id AND
				tb.bra_id		= tcp1.bra_id_PortFolio

			where	tcp1.comp_id			= @comp_id
			and		tcp1.chp_isNegociated	= 'True'
			and		tcpm.ba_id				= @ba_id
			and		(tcp1.chp_PayDate		>=	tb.bra_processingDate - 3 )



END

GO






-- --------------------------------------------------------------
-- MOS  05-2009
-- Borra los temporales que no se estan usando y no se han
-- actualizado, pasados 2 minutos.-
-- --------------------------------------------------------------

CREATE pROCEDURE [dbo].[spCheckPortfolio_IsEditingPurgeStatus]
as
set nocount on


declare @DeleteTime		as	datetime
set		@DeleteTime		=	DATEADD(minute, -3, getdate())




	-- cabeceras sin actualizar
	Update dbo.tbCheckPortfolio	WITH(ROWLOCK)
		Set chp_isEditing = 'False',
			chp_guid = null
			Where   chp_isEditing	= 'True'
				and	chp_isEditingCD < @DeleteTime






GO








CREATE PROCEDURE  [dbo].[spCheckPortfolio_MarkFromText]
(
	@comp_id							INT,
	@bra_id								INT,
	@chp_number							NVARCHAR(50),
	@chp_total							DECIMAL(19,4),
	@chp_guid							UNIQUEIDENTIFIER,
	@return_value						INT OUTPUT
)
AS


BEGIN

	SET NOCOUNT ON


	UPDATE  dbo.tbCheckPortfolio
		SET 	chp_guid		=	@chp_guid,
				chp_isEditing	=	'True',
				chp_isEditingCD =	Getdate(),
				chp_isInProcess =	'True'

		FROM tbCheckPortfolio tcp1
		WHERE	tcp1.comp_id			= @comp_id		AND
				--tcp1.bra_id_PortFolio	= @bra_id		AND
				tcp1.chp_number			= @chp_number	AND
				tcp1.chp_total			= @chp_total	AND
				tcp1.chp_isAvailable	= 'True'


	SET @return_value = @@ROWCOUNT

END



GO



CREATE PROCEDURE  [dbo].[spCheckPortfolio_MarkFromTextById]
(
