)
AS


BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------------
	-- TESTING
	-- -----------------------------------------------------------------------------------
	/*
		DECLARE
			@comp_id							INT,
			@bra_id								INT,
			@chp_id								INT,
			@chp_guid							UNIQUEIDENTIFIER,
			@return_value						INT
		SELECT
			@comp_id							= 1,
			@bra_id								= 1,
