			@chp_guid							= '59e54eed-6d29-4f06-9e7d-e6610f759565',
			@return_value						= 0
	*/
	-- -----------------------------------------------------------------------------------

	UPDATE  dbo.tbCheckPortfolio
		SET 	chp_guid		=	@chp_guid,
