CREATE PROCEDURE [dbo].[spCheckPortfolio_Rejection_getDataByFilters]
(
	@comp_id			INT ,
	@lang_id			INT ,
	@DateEmmitedFrom	DATETIME ,
	@DateEmmitedTo		DATETIME ,
	@import				DECIMAL (18,4),
	@number				VARCHAR (40),
	@option				INT,
	@bra_id			 AS INT
)
AS

BEGIN




	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-01-17
	-- Parte		: 774
	-- Description	: Se agregan la descripción del bankingaccount y el nombre del proveedor en la consulta
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-05-23
	-- TN			: 525
	-- Description	: Se quita la validación de si está disponible para el caso de cheques anulados
	-- =================================================================================================================
	SET NOCOUNT ON


-- ------------------------------------------------------------------------------
-- Testing
-- ------------------------------------------------------------------------------
	/*
	declare @comp_id			INT ,
			@lang_id			INT ,
			@DateEmmitedFrom	DATETIME ,
			@DateEmmitedTo		DATETIME ,
			@import				DECIMAL (18,4),
			@number				VARCHAR (40),
			@option				INT
	select	@comp_id			= 1,
			@lang_id			= 2,
			@DateEmmitedFrom	= '01/01/2000',
			@DateEmmitedTo		= '01/12/9999',
			@import				= 0.00,
			@number				= '',
			@option				= 1
	DROP TABLE #tmpCheckPortfolioMovements
	*/
-- ------------------------------------------------------------------------------





		-- -----------------------------------------------------------------------------------------------------------------
		-- Pongo en una tabla las Sucursales que pertenecen al grupo de sucursales de la actual sucursal incluida la actual.
		-- -----------------------------------------------------------------------------------------------------------------
		DECLARE @tbBranchsOfBranchGroup TABLE(bra_id INT)
		DECLARE @intBragID AS INT
		SELECT @intBragID = tb.brag_id
			FROM tbBranch tb
			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id
		INSERT INTO @tbBranchsOfBranchGroup (bra_id) VALUES (@bra_id)
		IF @intBragID IS NOT NULL
			BEGIN
				INSERT INTO @tbBranchsOfBranchGroup
					SELECT tbgd.bra_id
						FROM tbBranchGroupDetail tbgd
						WHERE	tbgd.brag_id = @intBragID AND
								tbgd.bra_id <> @bra_id
			END
		-- -----------------------------------------------------------------------------------------------------------------






	SELECT	tcpm.comp_id,
			tcpm.bra_id,
			tcpm.chp_id,
			MAX(tcpm.chpm_id) [chpm_id]

	INTO	#tmpCheckPortfolioMovements

	FROM	tbCheckPortfolioMovements tcpm

	WHERE	tcpm.comp_id		= @comp_id
	AND		tcpm.mm_isCancelled = 'false'

	GROUP BY tcpm.comp_id,tcpm.bra_id,tcpm.chp_id
	--SELECT * FROM #tmpCheckPortfolioMovements





	Select	' ' [ ],
			chp.chp_PayDate,
			chp.chp_number,
			chp.chp_total,
			tc.curr_desc,
			chp.chp_BranchCurrencyExchange,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction) [doc],
			chp.chp_EmissionDate,
			tbn.bn_name,
			tc2.cust_name,
			ISNULL(chp.chp_isRejected	,'False')		[chp_isRejected],
			ISNULL(chp.chp_isCancelled	,'False')		[chp_isCancelled],
			ISNULL(chp.chp_IsPayed		,'False')		[chp_IsPayed],
			ISNULL(chp.chp_isElectronic ,'False')		[chp_isElectronic],
			ISNULL(tba.ba_desc			,'')			[ba_desc],
			ISNULL(ts.supp_name			,'')			[supp_name],
			chp.chp_id									[Id]


	from	dbo.tbCheckPortfolio							chp

			left Join tbCommercialTransactions				tct
			On	tct.comp_id				=	chp.comp_id
			And tct.ct_transaction		=	chp.ct_transaction

			left JOIN tbsysCurrency							tc
			ON	tc.curr_id				=	chp.curr_id

			left JOIN tbCustomer							tc2
			ON	tc2.comp_id				=	chp.comp_id
			AND	tc2.cust_id				=	tct.cust_id

			LEFT JOIN tbBanksName							tbn
			ON	tbn.comp_id				=	chp.comp_id
			AND	tbn.bn_id				=	chp.bn_id


			LEFT JOIN #tmpCheckPortfolioMovements			tcpm
			ON	tcpm.comp_id			=	chp.comp_id
			AND tcpm.bra_id				=	chp.bra_id
			AND tcpm.chp_id				=	chp.chp_id

			LEFT JOIN tbCheckPortfolioMovements				tcpm2
			ON	tcpm2.comp_id			=	chp.comp_id
			AND tcpm2.bra_id			=	chp.bra_id
			AND tcpm2.chp_id			=	chp.chp_id
			AND tcpm2.chpm_id			=	tcpm.chpm_id

			LEFT JOIN tbCommercialTransactions				tct2
			ON	tct2.comp_id			=	chp.comp_id
			AND tct2.bra_id				=	chp.bra_id
			AND tct2.ct_transaction		=	tcpm2.ct_transaction

			LEFT JOIN tbBankingAccounts						tba
			ON	tba.comp_id				=	tct.comp_id
			AND tba.ba_id				=	tct2.ba_id

			LEFT JOIN tbSupplier							ts
			ON	ts.comp_id				=	chp.comp_id
			AND ts.supp_id				=	tct2.supp_id


			INNER JOIN @tbBranchsOfBranchGroup tbg
				ON tbg.bra_id = tct.bra_id


	Where	chp.comp_id										= @comp_id
	--AND 	isnull(chp.chp_isAvailable	,'False')			= 'False'	-- TN : 525
	--AND	isnull(chp.chp_IsPayed		,'False')			= 'False'
	AND		isnull(chp.chp_isEditing	,'False')			= 'False'
	AND		isnull(chp.chp_isDocument	,'False')			= 'False'

	AND		(
				--===============================================================================
				-- TN : 525
				(@option = 1 --rechazo
				AND 	isnull(chp.chp_isAvailable	,'False')	= 'False'
				And		isnull(chp.chp_isCancelled	,'False')	= 'False'
				And		isnull(chp.chp_isRejected	,'False')	= 'False') OR

				(@option = 2 --anulación
				And		isnull(chp.chp_isCancelled	,'False')	= 'False'
				And		isnull(chp.chp_isRejected	,'False')	= 'False'
				AND     ISNULL(chp.chp_isAvailable  ,'False')   = 'True' ) OR

				(@option = 3 --cancelar rechazo
				AND 	isnull(chp.chp_isAvailable	,'False')	= 'False'
				AND 	isnull(chp.chp_isRejected	,'False')	= 'True'
				And		isnull(chp.chp_isCancelled	,'False')	= 'False') OR

				(@option = 4 --cancelar anulados
				AND 	isnull(chp.chp_isAvailable	,'False')	= 'False'
				And		isnull(chp.chp_isRejected	,'False')	= 'False'
				AND 	isnull(chp.chp_isCancelled	,'False')	= 'True')
				--===============================================================================
			)

	And		chp.chp_PayDate		Between	@DateEmmitedFrom And @DateEmmitedTo
	And		(@import			= 0		or	chp.chp_total	= @import)
	And		(@number			= ''	or	chp.chp_number	= @number)









	---- Si Selecciona CHEQUE RECHAZADO:
	--If @value = 'true'
	--
	--	Begin
	--
	--		If @number = 'false'
	--		   --Para que traiga uno en especifico, pero q filten por chp_isAvailable,chp_isCancelled,chp_isRejected
	--		   Begin
	--   				(
	--				Select	' ',
	--						--importe, moneda
	--						Isnull(chp.chp_EmissionDate, '') [chp_EmissionDate],
	--						chp.chp_PayDate,
	--						chp.chp_number,
	--						chp.chp_BranchCurrencyExchange,
	--						dbo.fnGetCommercialTransactionDescription(@comp_id, 2,tct.ct_transaction) [chp_number_recibo]
	--
	--				from dbo.tbCheckPortfolio chp
	--
	--				left Join tbCommercialTransactions tct
	--				On	tct.comp_id			=	chp.comp_id
	--				And tct.ct_transaction	=	chp.ct_transaction
	--
	--				Where chp.comp_id			= @comp_id
	--				And   chp.chp_isAvailable	= 'true'
	--				And	  chp.chp_number		= @chp_number
	--				And   chp.chp_isCancelled	= 'true'
	--				And	  chp.chp_isRejected	= 'true'
	--				And   chp.chp_total			= @import
	--				And   chp.chp_EmissionDate Between @DateEmmitedFrom	 And @DateEmmitedTo
	--   				)
	--		   End
	--		else
	--			 --Para que traiga todos, pero q filten por chp_isAvailable,chp_isCancelled,chp_isRejected
	--		   Begin
	--			(
	--			 Select	' ',
	--					Isnull(chp.chp_EmissionDate, '') [chp_EmissionDate],
	--					chp.chp_PayDate,
	--					chp.chp_number,
	--					chp.chp_BranchCurrencyExchange,
	--					dbo.fnGetCommercialTransactionDescription(@comp_id,2,tct.ct_transaction) [chp_number_recibo]
	--
	--			from dbo.tbCheckPortfolio chp
	--
	--			left Join tbCommercialTransactions tct
	--			On	tct.comp_id			=	chp.comp_id
	--			And tct.ct_transaction	=	chp.ct_transaction
	--
	--			Where chp.comp_id	      = @comp_id
	--			And   chp.chp_isAvailable = 'true'
	--			And   chp.chp_isCancelled = 'true'
	--			And	  chp.chp_isRejected  = 'true'
	----			And   chp.chp_total = @import
	--			And   chp.chp_EmissionDate Between @DateEmmitedFrom	 And @DateEmmitedTo
	--		)
	--		END
	--
	--   End
	--
	--Else
	--	--Si selecciona CHEQUE ANULADO:
	--  Begin
	--  	If @number = 'false'
	--  	--Para que traiga uno en especifico, pero q filten por chp_isAvailable
	--  	   BEGIN
	--  	   	   	Select	' ',
	--			Isnull(chp.chp_EmissionDate, '') [chp_EmissionDate],
	--			chp.chp_PayDate,
	--			chp.chp_number,
	--			chp.chp_BranchCurrencyExchange,
	--			dbo.fnGetCommercialTransactionDescription(@comp_id,2,tct.ct_transaction) [chp_number_recibo]
	--
	--  			from dbo.tbCheckPortfolio chp
	--
	--  			inner Join tbCommercialTransactions tct
	--			On	tct.comp_id			=	chp.comp_id
	--			And tct.ct_transaction	=	chp.ct_transaction
	--
	--			Where chp.comp_id					 = @comp_id
	--			And   chp.chp_isAvailable			 = 'false'
	--			And   chp.chp_EmissionDate Between @DateEmmitedFrom	 And @DateEmmitedTo
	--			And	  chp.chp_number				 = @chp_number
	--  	   End
	--  	Else
	--  		 --Para que traiga todos, pero q filten por chp_isAvailable
	--  		BEGIN
	--  				Select	' ',
	--			Isnull(chp.chp_EmissionDate, '') [chp_EmissionDate],
	--			chp.chp_PayDate,
	--			chp.chp_number,
	--			chp.chp_BranchCurrencyExchange,
	--			dbo.fnGetCommercialTransactionDescription(@comp_id,2,tct.ct_transaction) [chp_number_recibo]
	--
	--  			from dbo.tbCheckPortfolio chp
	--
	--  			inner Join tbCommercialTransactions tct
	--			On	tct.comp_id			=	chp.comp_id
