CREATE PROCEDURE  [dbo].[spCheckPortfolio_updateData]
(
		@guid						uniqueidentifier,
		@return_value				as int			output,
		@ret_ErrorCode				as int			output,
		@ret_ErrorDescription		as varchar(200) output

)
AS
set nocount on ;
	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''

	SELECT 1 / 0		-- MOS 08-2024: x si a algun FORRO se le ocurre usarlo, q salte
	RETURN


update dbo.tbCheckPortfolio

SET		chp_isEditing	= 'false',
		chp_isPayed		= 'true',
		chp_guid		= null

where	chp_guid		=	@guid





GO








CREATE PROCEDURE  [dbo].[spCheckPortfolio_updateDataFromNumber]
(
	@comp_id							INT,
	@bn_BankNumber						INT,
	@chp_BankBranch						INT,
	@chp_number							NVARCHAR(50),
	@chp_AccountNumber					NVARCHAR(50),
	@chp_guid							UNIQUEIDENTIFIER,
	@return_value						INT OUTPUT
)
AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------
	/*
	declare	@comp_id							INT,
			@bn_BankNumber						INT,
			@chp_BankBranch						INT,
			@chp_number							NVARCHAR(50),
			@chp_AccountNumber					NVARCHAR(50),
			@chp_guid							UNIQUEIDENTIFIER,
			@return_value						INT OUTPUT
	SELECT 	@comp_id							= 1,
			@bn_BankNumber						= 150,
			@chp_BankBranch						= 191,
			@chp_number							= '81970337',
			@chp_AccountNumber					= '00000019398',
			@chp_guid							= 'a3eee78d-9fb9-487b-ba01-8d468a860d1b'
	*/
	-- -----------------------------------------------------------------------------



	UPDATE  dbo.tbCheckPortfolio

	SET 	chp_guid		=	CASE WHEN ISNULL(chp_isEditing,'False') = 'False' THEN @chp_guid ELSE NULL END,
			chp_isEditing	=	~ ISNULL(chp_isEditing,'False'),
			chp_isEditingCD =	Getdate()

	--SELECT	tcp1.*

	FROM	dbo.tbCheckPortfolio			tcp1		WITH (NOLOCK)
			INNER JOIN tbBanksName			tbn			WITH (NOLOCK)
			ON	tbn.comp_id		= tcp1.comp_id
			AND tbn.bn_id		= tcp1.bn_id

	WHERE 	tcp1.comp_id						=	@comp_id
	AND		tcp1.chp_isAvailable				=	'True'
	AND		tbn.bn_BankNumber					=   @bn_BankNumber
	AND		tcp1.chp_BankBranch					=	@chp_BankBranch
	AND		ltrim(rtrim(tcp1.chp_number))		=   rtrim(ltrim(@chp_number))
	AND		ltrim(rtrim(tcp1.chp_AccountNumber))=	ltrim(rtrim(@chp_AccountNumber))
	AND 	(
				(IsNull(chp_isEditing,'False') = 'False' OR chp_guid	IS	NULL)
				OR chp_guid = @chp_guid
			)


	SET @return_value = @@ROWCOUNT

END



GO






CREATE PROCEDURE [dbo].[spCheckPortfolio_UpdateDataNote]
(
	@comp_id		  INT,
	@chp_id			  INT,
	@chp_EmissionDate DATETIME,
	@chp_PayDate	  DATETIME,
	@chp_Note		  VARCHAR(200)
)
AS
BEGIN

/*
--Parametros de Prueba.
DECLARE @comp_id		  INT,
		@cho_id			  INT,
		@chp_EmissionDate DATETIME,
		@chp_PayDate	  DATETIME,
		@chp_Note		  VARCHAR(200)

SELECT  @comp_id		  = 1,
		@chp_EmissionDate = ''
		@chp_PayDate      = ''
		@chp_Note		  = ''
--Fin Parametros de Prueba.
*/

	UPDATE tbCheckPortfolio
	SET  chp_EmissionDate = @chp_EmissionDate,
