	AND   chp_id  = @chp_id

END
GO







-- ----------------------------------------------------------------------
-- Selecciona el cupon para ser liquidado solo si no esta seleccionado
-- o lo des-selecciona solo si esta seleccionado y pertenece al guid
-- que se paso como parametro
-- esto se usa en wfmPurchaseDocs unicamente.-
-- ----------------------------------------------------------------------
-- MOS  08-2010 x ch BD
CREATE PROCEDURE  [dbo].[spCheckPortfolio_updateDatatoGrid]
(
	@comp_id							int,
	@bra_id								int,
	@ct_transaction						int,
	@chp_id								int,
	@chp_guid							UNIQUEIDENTIFIER
)
As


BEGIN

	set nocount on

	-- -----------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------
/*
	declare	@comp_id							int,
			@bra_id								int,
			@ct_transaction						int,
			@chp_id								int,
			@chp_guid							UNIQUEIDENTIFIER
	SELECT 	@comp_id							= 1,
			@bra_id								= 26,
			@ct_transaction						= 5,
			@chp_id								= 4,
			@chp_guid							= 'a3eee78d-9fb9-487b-ba01-8d468a860d1b'
*/
	-- -----------------------------------------------------------------------------


	Update	dbo.tbCheckPortfolio

	Set		chp_guid		=	CASE WHEN ISNULL(chp_isEditing,'False') = 'False' THEN @chp_guid ELSE NULL END,
			chp_isEditing	=	~ ISNULL(chp_isEditing,'False'),
			chp_isEditingCD =	Getdate()

	Where	comp_id			=	@comp_id
	And		chp_id			=	@chp_id
	And	    ct_transaction	=	@ct_transaction
	And	(  (IsNull(chp_isEditing,'False') = 'False' OR chp_guid	IS	NULL)
				OR chp_guid = @chp_guid )

END



GO






CREATE PROCEDURE [dbo].[spCheckPortfolio_UpdateEditDetail]
(
	@comp_id					INT,
	@chp_id						INT,
	@chp_number					VARCHAR(50),
	@chp_taxNumber1				VARCHAR(50),
	@chp_taxNumber2				VARCHAR(50),
	@chp_taxNumber3				VARCHAR(50),
	@chp_PayDate				DATETIME,
	@chp_isOwn					BIT,
	@chp_isToOrder				BIT,
	@chp_total					DECIMAL(19,5),
	@chp_BankBranchDescription	VARCHAR(50),
	@chp_QtyEndosos				INT,
	@bra_id						INT,
	@ba_id						INT,
	@chp_isElectronic			BIT
)
AS
BEGIN

/*
--Parametros de Prueba.
DECLARE 	@comp_id			INT,
			@chp_id				INT,
			@chp_number			VARCHAR(50),
			@chp_taxNumber1		VARCHAR(50),
			@chp_taxNumber2		VARCHAR(50),
			@chp_taxNumber3		VARCHAR(50),
			@chp_PayDate		DATETIME,
			@chp_isOwn			BIT,
			@chp_isToOrder		BIT

SELECT  @comp_id		  = 1,
		@chp_EmissionDate = ''
		@chp_PayDate      = ''
		@chp_Note		  = ''
--Fin Parametros de Prueba.
*/

	UPDATE tbCheckPortfolio
		SET chp_taxNumber1				= @chp_taxNumber1,
			chp_taxNumber2				= @chp_taxNumber2,
			chp_taxNumber3				= @chp_taxNumber3,
			chp_number					= @chp_number,
			chp_isOwn					= @chp_isOwn,
			chp_isToOrder				= @chp_isToOrder,
			chp_PayDate					= @chp_PayDate,
			chp_total					= @chp_total,
			chp_BankBranchDescription	= @chp_BankBranchDescription,
			chp_QtyEndosos				= @chp_QtyEndosos,
			bra_id_PortFolio			= @bra_id,
			ba_id						= @ba_id,
			chp_isElectronic			= @chp_isElectronic


	WHERE comp_id = @comp_id
	AND   chp_id  = @chp_id

END
GO






