CREATE PROCEDURE [dbo].[spCheckPortfolio_UpdateInProcess]
(
	@comp_id		INT,
	@chp_id			INT,
	@guid			UNIQUEIDENTIFIER,
	@origin			bit
)
AS

BEGIN

	SET NOCOUNT ON
	-- =================================================================================================================

	-- ATENCION!!!   Actualizar tambien - >>>>>>>>>>>>>>>spCheckPortfolio_UpdateInProcessFrom_spCheckPortfolio_checkData

	-- Author		: MOH
	-- Update Date	: 2010-08-21
	-- Parte		: 499
	-- Description	: Para agregar la cantidad y el importe total de los cheques seleccionados en el depósito de cheques
	--				  se agregan esos valores en el query final
	-- =================================================================================================================




	/*

	DECLARE		@comp_id		INT,
				@chp_id			INT,
				@guid			UNIQUEIDENTIFIER,
				@origin			BIT

	SELECT		@comp_id		=1,
				@chp_id			=185,
				@guid			='8b569499-f23f-4a5b-91f8-191c381cf548',
				@origin			= 'FALSE'
	*/


	IF EXISTS(
				SELECT 1
					FROM tbCheckPortfolio tcp1
				WHERE	tcp1.comp_id			= @comp_id	AND
						tcp1.chp_id				= @chp_id	AND
						(
							(tcp1.chp_isInProcess	= 'True' AND tcp1.chp_guid = @guid)	OR
							 tcp1.chp_isInProcess	= 'False'
						)
				)

		BEGIN

			IF @origin = 'true'

				--------DEPÓSITO-------------------
				BEGIN

					UPDATE	tbCheckPortfolio

					SET		chp_isInProcess		= ~chp_isInProcess,
							chp_guid			=	CASE
														WHEN chp_isInProcess = 'TRUE' THEN NULL
														ELSE @guid
													END

					WHERE	comp_id				= @comp_id
					AND		chp_id				= @chp_id

				END

			ELSE

				-------ACREDITACION----------------
				BEGIN

					UPDATE	tbCheckPortfolio

					SET		chp_guid			=	CASE
														WHEN chp_guid IS NULL THEN @guid
														ELSE NULL
													END,
							chp_isInProcess		= ~chp_isInProcess

					WHERE	comp_id				= @comp_id
					AND		chp_id				= @chp_id

				END


		END







	-- =============================================================================
	-- Parte : 499
	SELECT	COUNT(*),
			ISNULL(SUM(tcp1.chp_total),0.00)
		FROM	tbCheckPortfolio tcp1
		WHERE	tcp1.comp_id			= @comp_id
		AND		tcp1.chp_guid			= @guid
		AND		tcp1.chp_isInProcess	= 'True'

	-- =============================================================================


END
GO






CREATE PROCEDURE spCheckPortfolio_UpdateInProcessFrom_spCheckPortfolio_checkData
(
	@comp_id		INT,
	@chp_id			INT,
	@guid			UNIQUEIDENTIFIER,
	@origin			bit
)
AS

BEGIN



	SET NOCOUNT ON
	-- =================================================================================================================
	-- Si se toca spCheckPortfolio_UpdateInProcess modificar tambien este SP
	-- =================================================================================================================




	/*

	DECLARE		@comp_id		INT,
				@chp_id			INT,
				@guid			UNIQUEIDENTIFIER,
				@origin			BIT

	SELECT		@comp_id		=1,
				@chp_id			=185,
				@guid			='8b569499-f23f-4a5b-91f8-191c381cf548',
				@origin			= 'FALSE'
	*/


	IF @origin = 'true'

		--------DEPÓSITO-------------------
		BEGIN

			UPDATE	tbCheckPortfolio

			SET		chp_isInProcess		= ~chp_isInProcess,
					chp_guid			=	CASE
												WHEN chp_isInProcess = 'TRUE' THEN NULL
												ELSE @guid
											END

			WHERE	comp_id				= @comp_id
			AND		chp_id				= @chp_id

		END

	ELSE

		-------ACREDITACION----------------
		BEGIN

			UPDATE	tbCheckPortfolio

			SET		chp_guid			=	CASE
												WHEN chp_guid IS NULL THEN @guid
												ELSE NULL
											END,
					chp_isInProcess		= ~chp_isInProcess

			WHERE	comp_id				= @comp_id
			AND		chp_id				= @chp_id

		END


END
GO






CREATE PROCEDURE [dbo].[spCheckPortfolio_UpdateInProcessFromNumber]
(
	@comp_id							INT,
	@bn_BankNumber						INT,
	@chp_BankBranch						INT,
	@chp_number							NVARCHAR(50),
	@chp_AccountNumber					NVARCHAR(50),
	@chp_guid							UNIQUEIDENTIFIER,
	@origin								BIT,
	@return_value						INT OUTPUT
)
AS
SET NOCOUNT ON


/*

DECLARE		@comp_id		INT,
			@chp_id			INT,
			@guid			UNIQUEIDENTIFIER,
			@origin			BIT

SELECT		@comp_id		=1,
			@chp_id			=185,
			@guid			='8b569499-f23f-4a5b-91f8-191c381cf548',
			@origin			= 'FALSE'
*/



DECLARE @chp_id				INT


SELECT	@chp_id = tcp1.chp_id

FROM	dbo.tbCheckPortfolio			tcp1
		INNER JOIN tbBanksName			tbn
		ON	tbn.comp_id		= tcp1.comp_id
		AND tbn.bn_id		= tcp1.bn_id

WHERE 	tcp1.comp_id						=	@comp_id

AND		(
			(@origin = 'true'  AND tcp1.chp_isAvailable = 'true'  AND tcp1.chp_IsPayed = 'false') OR
			(@origin = 'false' AND tcp1.chp_isAvailable = 'false' AND tcp1.chp_IsPayed = 'false')
		)

AND		tbn.bn_BankNumber					=   @bn_BankNumber
AND		tcp1.chp_BankBranch					=	@chp_BankBranch
AND		ltrim(rtrim(tcp1.chp_number))		=   ltrim(rtrim(@chp_number))
AND		ltrim(rtrim(tcp1.chp_AccountNumber))=	ltrim(rtrim(@chp_AccountNumber))



SET @return_value = 0

IF @origin = 'true'

	--------DEPÓSITO-------------------
	BEGIN

		UPDATE	tbCheckPortfolio

		SET		chp_isInProcess		= ~chp_isInProcess,
				chp_guid			= @chp_guid

		WHERE	comp_id				= @comp_id
		AND		chp_id				= @chp_id


		IF @@ROWCOUNT > 0
			BEGIN
				SET @return_value = 1
			END
		ELSE
			BEGIN
				SET @return_value = 0
			END
	END

ELSE

	-------ACREDITACION----------------
	BEGIN

		UPDATE	tbCheckPortfolio

		SET		chp_guid			= CASE WHEN chp_guid IS NULL THEN @chp_guid ELSE NULL END,
				chp_isInProcess		= ~chp_isInProcess

		WHERE	comp_id				= @comp_id
		AND		chp_id				= @chp_id

	END



-- =============================================================================
-- Parte : 499
SELECT	COUNT(*),
		ISNULL(SUM(tcp1.chp_total),0.00)
FROM	tbCheckPortfolio tcp1
WHERE	tcp1.comp_id			= @comp_id
AND		tcp1.chp_guid			= @chp_guid
AND		tcp1.chp_isInProcess	= 'True'
-- =============================================================================
GO






CREATE PROCEDURE [dbo].[spCheckPortfolio_updateIsAvailable]
(
	@comp_id			int,
	@chp_id				int,
	@chp_isavailable	BIT,
	@ct_transaction		INT,
	@ba_id				INT,
	@bt_id				INT
)
AS

BEGIN

	set nocount on

	update	dbo.tbCheckPortfolio
		set		chp_isAvailable		= @chp_isavailable,
				chp_isNegociated	=	CASE
											WHEN @chp_isavailable = 'True' THEN 'False'
											ELSE								chp_isNegociated
										END,
				chp_IsPayed			= 	CASE
											WHEN @chp_isavailable = 'True' THEN 'False'
											ELSE								chp_IsPayed
										END
		where	comp_id			= @comp_id AND
				chp_id			= @chp_id



	IF @chp_isavailable = 'False'

		INSERT INTO tbCheckPortfolioMovements
		(
			comp_id,
			bra_id,
			chp_id,
			ct_transaction,
			mm_isCancelled,
			svtt_id,
			ba_id,
			bt_id
		)
		SELECT
			@comp_id,
			tcp1.bra_id,
			tcp1.chp_id,
			@ct_transaction,
			'False',
			40,
			@ba_id,
			@bt_id

		FROM	tbCheckPortfolio tcp1
		where	comp_id			= @comp_id
		AND     chp_isInProcess = 'true'
		--and		chp_id			= @chp_id




END
GO












