CREATE  PROCEDURE [dbo].[spCheckPortfolio_updateIsCancelled]
(
	@comp_id					INT						,
	@lang_id					INT						,
	@chp_id						INT						,
	@chp_isCancelled			BIT						,
	@user_id					INT						,
	@bra_id						INT						,
	@return_value				INT 			OUTPUT	,
	@ret_ErrorCode				INT 			OUTPUT	,
	@ret_ErrorDescription		VARCHAR(200)	OUTPUT
)
AS

BEGIN


	SET NOCOUNT ON


-- ------------------------------------------------------------------
-- TEsting
-- ------------------------------------------------------------------
	/*
	declare
		@comp_id					INT						,
		@lang_id					INT						,
		@chp_id						INT						,
		@chp_isRejected				BIT						,
		@user_id					INT						,
		@total						DECIMAL(19,6)			,

		@return_value				INT 			,
		@ret_ErrorCode				INT 			,
		@ret_ErrorDescription		VARCHAR(200)

	SELECT
		@comp_id					=1						,
		@lang_id					=2						,
		@chp_id						=119					,
		@chp_isRejected				='true'					,
		@user_id					=1						,
		@total						=0
	*/
-- ------------------------------------------------------------------


	SET  	@return_value			=	0
	SET 	@ret_ErrorCode			=	0
	SET 	@ret_ErrorDescription	=	' '


	DECLARE		@return_Identity			INT,
				@return_ErrorCode			INT,
				@return_ErrorDescription	VARCHAR(200)





	/*******************************************************************************************************/
	/* rechazar el cheque seleccionado			                                                           */
	BEGIN TRY


		UPDATE	dbo.tbCheckPortfolio

		SET 	chp_isCancelled					=	@chp_isCancelled,
				chp_isAvailable					=   ~@chp_isCancelled

		WHERE	comp_id							=	@comp_id
		AND 	chp_id							=	@chp_id
		AND		ISNULL(chp_isEditing, 'False')	=	'False'


	END TRY
	BEGIN CATCH
		Set @ret_ErrorCode			= -1
		Set	@ret_ErrorDescription	= '01 - ' + ERROR_MESSAGE()
	END CATCH
	/*******************************************************************************************************/





	DECLARE	@bra_idAT		INT
	SELECT	@bra_idAT		= tcp1.bra_id
		FROM	tbCheckPortfolio tcp1			WITH (NOLOCK)
		WHERE	tcp1.comp_id	= @comp_id
		AND		tcp1.chp_id		= @chp_id


	DECLARE @option INT
	SELECT 	@option  = CASE	WHEN @chp_isCancelled =	'True'	THEN 2
							WHEN @chp_isCancelled = 'False' THEN 4
						END





	/*******************************************************************************************************/
	/* actualización de accounttransaction                                                                 */
	EXEC	spAccountTransaction_InsertdataFromCheckRejection
			@comp_id,
			@bra_idAT,
			@lang_id,
			@chp_id,
			@option,
			@user_id,
			@ret_Identity			= @return_Identity			OUTPUT,
			@ret_ErrorCode			= @return_ErrorCode			OUTPUT,
			@ret_ErrorDescription	= @return_ErrorDescription	OUTPUT
	IF @return_ErrorCode < 0
	BEGIN
		SELECT 	@ret_ErrorCode			= @return_ErrorCode,
				@ret_ErrorDescription	= @return_ErrorDescription
		RETURN
	END
	/*******************************************************************************************************/




	IF @ret_ErrorCode = 0
	BEGIN


		DECLARE --@bra_id							INT				,
				@soh_id							INT				,
				@bra_processingDate				DATETIME		,
				@observation1					VARCHAR(100)	,
				@sm_id							INT				,
				@ct_transaction					INT				,
				@cust_id						INT				,
				@df_id							INT				,
				@ssos_id						INT				,
				@ExchangeToCustomerCurrency		DECIMAL(19,5)	,
				@chp_curr_id					INT				,
				@cust_curr_id					INT				,
				@rv								INT				,
				@bra_CR_taxId4Cheque			INT				,
				@bra_CR_taxId4Charge			INT				,
				@bra_CR_taxId4Cheque_acc_count_id	INT			,
				@bra_CR_taxId4Charge_acc_count_id	INT			,
				@total								DECIMAL(19,5),
				@st_id								INT,
				@disc_id							INT




		/*******************************************************************************************************/
		/* obtiene la sucursal del cheque actualizado                                                 */
		SELECT	--@bra_id				=	bra_id,
				@ct_transaction		=	tcp1.ct_transaction,
				@total				=	tcp1.chp_total,
				@chp_curr_id		=	tcp1.curr_id
		FROM	tbCheckPortfolio	tcp1
		WHERE	comp_id				=	@comp_id
		AND		chp_id				=	@chp_id
		/*******************************************************************************************************/



		/*******************************************************************************************************/
		/* obtiene el próximo soh_id des la tabla tbCounters, con id 2                                         */
		EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @soh_id OUTPUT
		/*******************************************************************************************************/



		/*******************************************************************************************************/
		/* obtiener datos de la sucursal                                                                       */
		SELECT	@bra_processingDate		=	bra_processingDate	,
				@bra_CR_taxId4Cheque	=	bra_CR_taxId4Cheque	,
				@bra_CR_taxId4Charge	=	bra_CR_taxId4Charge ,
				@bra_CR_taxId4Cheque_acc_count_id	= bra_CR_taxId4Cheque_acc_count_id,
				@bra_CR_taxId4Charge_acc_count_id	= bra_CR_taxId4Charge_acc_count_id

		FROM	dbo.tbBranch						WITH (NOLOCK)
		WHERE	comp_id					=	@comp_id
		AND		bra_id					=	@bra_id
		/*******************************************************************************************************/



		/*******************************************************************************************************/
		/* obtiene la descripción de la acción a realizar                                                      */
		SELECT	@observation1	= optval_desc
			FROM	dbo.tbsysOptionsValues			WITH (NOLOCK)
			WHERE	optval_class	= 48
			AND		optval_id		= 3
			AND		lang_id			= @lang_id
		/*******************************************************************************************************/



		/*******************************************************************************************************/
		/* obtiene datos de la tabla tbcommercialtransaction relaicionada al cheque que se rechaza             */
		SELECT	@sm_id				=	tct.sm_id,
				@cust_id			=	tct.cust_id,
				@cust_curr_id		=	tc.curr_id,
				@st_id				=	tc.st_id

		FROM	tbCommercialTransactions	tct				WITH (NOLOCK)
				INNER JOIN tbCustomer		tc				WITH (NOLOCK)
				ON tc.comp_id		=	tct.comp_id
				AND tc.cust_id		=	tct.cust_id
		WHERE	tct.comp_id			=	@comp_id
		--AND		tct.bra_id			=	@bra_id
		AND		tct.ct_transaction	=	@ct_transaction
		/*******************************************************************************************************/





		/*******************************************************************************************************/
		/* obtiene el df_id correspondiente para el cliente y el sysdocument correspondiente				   */
		/*******************************************************************************************************/

		DECLARE @sd_id		INT
		IF @chp_isCancelled = 'true' -- cheque anulado
			SET @sd_id = 4		--Nota de Débito
		ELSE -- chaque des anulado
			SET @sd_id = 3		--Nota de Crédito



		IF NOT OBJECT_ID('tempdb.dbo.#tmpDocumentFile')		IS NULL DROP TABLE #tmpDocumentFile
		CREATE TABLE #tmpDocumentFile
		(
			[df_id]			INT,
			[df_desc]		VARCHAR(100)
		)


		INSERT	#tmpDocumentFile	([df_id],	[df_desc])
		EXEC	dbo.spDocumentsFile_getTopOneByCustomerSysDocuments @comp_id, @bra_id, @cust_id, @sd_id


		IF EXISTS (SELECT 1 FROM #tmpDocumentFile)
			--encontró algún documento para los filtros seleccionados
			SELECT @df_id = tmpDF.df_id FROM #tmpDocumentFile tmpDF
		ELSE
			--no encontró ningún documento para los filtros seleccionados entonces debe cancelar
			BEGIN
				SET  	@return_value			=	0
				SET 	@ret_ErrorCode			=	-4

				SELECT 	@ret_ErrorDescription = '04 - ' + utexts_desc + (SELECT td.sd_desc
				       	                                                   FROM tbsysDocuments td WHERE td.sd_id = @sd_id)
				FROM 	dbo.tbsysUniqueTexts		WITH (NOLOCK)
				WHERE 	lang_id		= @lang_id
				AND		utexts_id	= 5200

				RETURN
			END

		/*******************************************************************************************************/






		/*******************************************************************************************************/
		/*SELECT	TOP 1 @ssos_id		= ssos_id
		FROM	dbo.vwsysSaleOrderStatus_IsOkForEmmition*/
		SET @ssos_id = 220
		/*******************************************************************************************************/




		/* obtenemos el tipo de cambio entre la moneda del cheque y la moneda del cliente                      */
		SELECT @ExchangeToCustomerCurrency = dbo.fnGetExchange(@comp_id,@total,@chp_curr_id,@cust_curr_id,0,0,'False')




		/*******************************************************************************************************/
		/* recuperamos un descuento con valor cero                                                             */
		SET @disc_id = NULL

		SELECT	TOP 1 @disc_id = td.disc_id
		FROM	tbDiscount td
		WHERE	td.comp_id = @comp_id
		AND		(td.bra_id IS NULL OR td.bra_id = @bra_id)
		AND		td.disc_coef = 0
		ORDER BY td.disc_desc
		/*******************************************************************************************************/



		/*******************************************************************************************************/
		/* insertar el pedido por cheque rechazado                                                             */
		BEGIN TRY

			EXEC dbo.spSaleOrderHeader_insertData	@comp_id, @bra_id, @soh_id, @bra_processingDate, @bra_processingDate,
													@observation1, '', '', '', 'False', @sm_id, @cust_id, @st_id, @disc_id,
													null, null, @bra_processingDate, null, null, null, 0, @user_id,
													'False', null, @total,
													@df_id, @ssos_id,
													@ExchangeToCustomerCurrency, @cust_curr_id

		END TRY
		BEGIN CATCH
			Set @ret_ErrorCode			= -2
			Set	@ret_ErrorDescription	= '02 - ' + ERROR_MESSAGE()
		END CATCH
		/*******************************************************************************************************/



		DECLARE @date DATETIME
		SET		@date = GETDATE()



		/*******************************************************************************************************/
		/* insertar los ítems por cheque rechazado                                                             */
		IF @ret_ErrorCode = 0
		BEGIN

			BEGIN TRY

				EXEC dbo.[spSaleOrderDetail_insertData] @comp_id, @bra_id, @soh_id,	0, NULL, 'Débito por Cheque Anulado', '',
														@chp_curr_id, 1, 1,	NULL, @total, NULL, @user_id,
														@date, @bra_CR_taxId4Cheque, @total, @rv OUTPUT,
														NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL
				-- Actualiza la Cuenta Contable a Asignar.-
				UPDATE tbSaleOrderDetail
					SET acc_count_id = @bra_CR_taxId4Cheque_acc_count_id
					WHERE sod_id = @rv

			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -3
				Set	@ret_ErrorDescription	= '03 - ' + ERROR_MESSAGE()
			END CATCH

		END
		/*******************************************************************************************************/


	END


END
GO







CREATE PROCEDURE [dbo].[spCheckPortfolio_updateIsEditing]
(
	@guid			AS UNIQUEIDENTIFIER ,
	@isEditing		AS BIT
)
AS


BEGIN


	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	UPDATE	tbCheckPortfolio WITH (ROWLOCK)

		SET	    chp_isEditing 		= @isEditing,
				chp_isEditingCD		= GETDATE()

		WHERE	chp_guid			= @guid




END
GO







CREATE PROCEDURE [dbo].[spCheckPortfolio_updateIsPayed]
(
	@comp_id					INT,
	@bra_id						INT,
	@lang_id					INT,
	@chp_ispayed				BIT,
	@guid						UNIQUEIDENTIFIER,
	@chp_id						INT ,
	@user_id					INT,
	@processing_date			DATETIME,
	@return_value			as	INT 			OUTPUT ,
	@ret_ErrorCode			as	INT 			OUTPUT ,
	@ret_ErrorDescription	as	VARCHAR(200)	OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON

	set @return_value			= 0
	set @ret_ErrorCode			= ''
	set @ret_ErrorDescription	= ''



-- ----------------------------------------------------------------------------------------------
-- Testing
-- ----------------------------------------------------------------------------------------------
	/*
	DECLARE @comp_id			INT,
			@chp_ispayed		BIT,
			@guid				UNIQUEIDENTIFIER,
			@chp_id				INT
	SELECT 	@comp_id			=1,
			@chp_ispayed		='false',
			@guid				='55E3E811-9BC6-4EB9-8AF6-B288DD4FEB4D',
			@chp_id				=-1
	*/
	--SELECT * FROM tbCheckPortfolio tcp1 WHERE tcp1.chp_guid = '571d8dd6-8599-4676-b2a0-ce928de58632'AND tcp1.chp_isInProcess='false'
-- ----------------------------------------------------------------------------------------------


    --SAVE TRANSACTION traPROTECT
    --BEGIN TRANSACTION
	DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT		-- MOS 06-2020
    BEGIN TRY



	IF @chp_id = -1

		BEGIN

			SELECT *
				INTO #tmpCheckPortfolio
				FROM tbCheckPortfolio tcp1
				WHERE 	comp_id				= @comp_id
					AND	chp_isInProcess		= 'true'
					AND	chp_guid			= @guid


			UPDATE 	dbo.tbCheckPortfolio
			SET 	chp_isPayed			= @chp_ispayed,
					chp_isAvailable		= 'False',
					chp_guid			= NULL,
					chp_isInProcess		= 'False'
			WHERE 	comp_id				= @comp_id
			AND		chp_isInProcess		= 'true'
			AND		chp_guid			= @guid

		END

	ELSE

		BEGIN

			SELECT *
				INTO #tmpCheckPortfolioB
				FROM tbCheckPortfolio tcp1
				WHERE 	comp_id			= @comp_id
					AND	chp_id			= @chp_id

			UPDATE 	dbo.tbCheckPortfolio
			SET 	chp_isPayed			= @chp_ispayed,
					chp_isAvailable		= 'False',
					chp_guid			= NULL,
					chp_isInProcess		= 'False'
			WHERE 	comp_id				= @comp_id
			AND		chp_id				= @chp_id

		END


	-- -------------------------------------------------------------
	-- Efectua el asiento contable correspondiente en funcion si fue
	-- una pago definitivo: @IsPayed->True o NO PAGO en False
	-- -------------------------------------------------------------
	IF @chp_id = -1
		BEGIN
			DECLARE curCheckPortfolio CURSOR LOCAL FAST_FORWARD FOR
				SELECT	tmp.chp_id,
						tmp.ct_transaction
					FROM #tmpCheckPortfolio tmp
		END
	ELSE
		BEGIN
			DECLARE curCheckPortfolio CURSOR LOCAL FAST_FORWARD FOR
				SELECT	tmp.chp_id,
						tmp.ct_transaction
					FROM #tmpCheckPortfolioB	tmp
		END

	DECLARE @intCHP_Id AS INT
	DECLARE @ct_transaction AS INT

	OPEN curCheckPortfolio

	FETCH curCheckPortfolio
		INTO	@intCHP_Id,
				@ct_transaction

	WHILE @@FETCH_STATUS = 0
		BEGIN
			EXEC spAccountTransaction_InsertdataFromUpdateIsPayed	@comp_id,
																	@bra_id,
																	@lang_id,
																	@intCHP_Id,
																	@ct_transaction,
																	@chp_ispayed,
																	@user_id,
																	@processing_date,
																	@return_value	OUTPUT,
																	@ret_ErrorCode	OUTPUT,
																	@ret_ErrorDescription	OUTPUT


			FETCH curCheckPortfolio
					INTO	@intCHP_Id,
							@ct_transaction
		END

	CLOSE curCheckPortfolio
	DEALLOCATE curCheckPortfolio

	-- -------------------------------------------------------------

    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT
        IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT_905		-- MOS 06-2020
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT


END
GO








CREATE PROCEDURE [dbo].[spCheckPortfolio_updateIsRejected]
(
	@comp_id					INT						,
	@lang_id					INT						,
	@chp_id						INT						,
	@chp_isRejected				BIT						,
	@user_id					INT						,
	@total						DECIMAL(19,6)			,  --cargos por cheque rechazado
	@chkSetCredit				BIT						,
	@bra_id						INT						,

	@return_value				INT 			OUTPUT	,
	@ret_ErrorCode				INT 			OUTPUT	,
	@ret_ErrorDescription		VARCHAR(200)	OUTPUT
)
AS

BEGIN



	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-01-13
	-- Parte		: 774
	-- Description	: Se agrega la contrapartida del cheque rechazado en la cuenta corriente del proveedor
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-04-04
	-- Parte		: S/P  Referencia: #1
	-- Description	: si el parámetro @chkSetCredit es True se debe generar el Debito o Credito Interno  HDP!!!!!!!
	-- =================================================================================================================
	SET NOCOUNT ON


-- ---------------------------------------------------------------------
-- Testing
-- ---------------------------------------------------------------------
	/*
	declare
		@comp_id					INT						,
		@lang_id					INT						,
		@chp_id						INT						,
		@chp_isRejected				BIT						,
		@user_id					INT						,
		@total						DECIMAL(19,6)			,

		@return_value				INT 			,
		@ret_ErrorCode				INT 			,
		@ret_ErrorDescription		VARCHAR(200)

	SELECT
		@comp_id					=1						,
		@lang_id					=2						,
		@chp_id						=190					,
		@chp_isRejected				='True'				,
		@user_id					=1						,
		@total						=10
	*/
-- ---------------------------------------------------------------------

	SET  	@return_value			=	0
	SET 	@ret_ErrorCode			=	0
	SET 	@ret_ErrorDescription	=	' '



	DECLARE		@return_Identity			INT,
				@return_ErrorCode			INT,
				@return_ErrorDescription	VARCHAR(200)



	--BEGIN TRANSACTION


	BEGIN TRY


	IF @chp_isRejected = 'True'

		BEGIN

			/*******************************************************************************************************/
			/* rechazar el cheque seleccionado			                                                           */
			UPDATE	dbo.tbCheckPortfolio
				SET 	chp_isRejected					=	@chp_isRejected
				WHERE	comp_id							=	@comp_id
				AND 	chp_id							=	@chp_id
				AND		ISNULL(chp_isEditing, 'False')	=	'False'
			/*******************************************************************************************************/


			IF @@ROWCOUNT > 0
			BEGIN


				DECLARE @bra_idAT						INT				,
						@soh_id							INT				,
						@bra_processingDate				DATETIME		,
						@observation1					VARCHAR(100)	,
						@observation2					VARCHAR(100)	,
						@observation3					VARCHAR(100)	,
						@sm_id							INT				,
						@ct_transaction					INT				,
						@cust_id						INT				,
						--@bra_CR_dfId4Debit				INT				,
						@ssos_id						INT				,
						@ExchangeToCustomerCurrency		DECIMAL(19,5)	,
						@bra_curr_id					INT				,
						@cust_curr_id					INT				,
						@rv								INT				,
						@bra_CR_taxId4Cheque				INT			,
						@bra_CR_taxId4Charge				INT			,
						@bra_CR_taxId4Cheque_acc_count_id	INT			,
						@bra_CR_taxId4Charge_acc_count_id	INT			,
						@chp_total						DECIMAL(19,5)	,
						@ba_id							INT				,	-- Parte		: 774
						@supp_id						INT				,	-- Parte		: 774
						@chp_curr_id					INT				,
						@chp_Number						VARCHAR(100)	,
						@st_id							INT				,
						@disc_id						INT


				/*******************************************************************************************************/
				/* obtiene la sucursal del cheque actualizado                                                          */
				SELECT	@bra_idAT			=	tcp1.bra_id_PortFolio,
						@ct_transaction		=	tcp1.ct_transaction	,
						@chp_total			=	tcp1.chp_total		,
						@chp_curr_id		=	tcp1.curr_id		,
						@chp_Number			=   ltrim(rtrim(isnull(tcp1.chp_number,'')))
				FROM	tbCheckPortfolio	tcp1				WITH (NOLOCK)
				WHERE	comp_id				=	@comp_id
				AND		chp_id				=	@chp_id
				/*******************************************************************************************************/



				/*******************************************************************************************************/
				/* obtiene el próximo soh_id des la tabla tbCounters, con id 2                                         */
				EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @soh_id OUTPUT
				/*******************************************************************************************************/



				/*******************************************************************************************************/
				/* obtiener datos de la sucursal                                                                       */
				SELECT	@bra_processingDate		=	bra_processingDate	,
						@bra_curr_id			=	curr_id				,
						@bra_CR_taxId4Cheque	=	bra_CR_taxId4Cheque	,
						@bra_CR_taxId4Charge	=	bra_CR_taxId4Charge ,
						@bra_CR_taxId4Cheque_acc_count_id	= bra_CR_taxId4Cheque_acc_count_id,
						@bra_CR_taxId4Charge_acc_count_id	= bra_CR_taxId4Charge_acc_count_id
					FROM	dbo.tbBranch				WITH (NOLOCK)
					WHERE	comp_id					=	@comp_id
					AND		bra_id					=	@bra_id
				/*******************************************************************************************************/



				/*******************************************************************************************************/
				/* obtiene la descripción de la acción a realizar                                                      */
				SELECT	@observation1			=	tov.optval_desc		,
						@observation2			=	tov2.optval_desc + ' ' + @chp_Number , -- MOSconvert(varchar,@chp_id),
						@observation3			=	tov3.optval_desc

					FROM	dbo.tbsysOptionsValues					tov				WITH (NOLOCK)

					LEFT JOIN	tbsysOptionsValues			tov2			WITH (NOLOCK)
						ON	tov2.lang_id		=	tov.lang_id
						AND	tov2.optval_class	=	tov.optval_class
						AND	tov2.optval_id		=	4

					LEFT JOIN	tbsysOptionsValues			tov3			WITH (NOLOCK)
						ON	tov3.lang_id		=	tov.lang_id
						AND	tov3.optval_class	=	tov.optval_class
						AND	tov3.optval_id		=	5

					WHERE	tov.lang_id				=	@lang_id
					AND		tov.optval_class		=	48
					AND		tov.optval_id			=	3
				/*******************************************************************************************************/



				/*******************************************************************************************************/
				/* obtiene datos de la tabla tbcommercialtransaction relaicionada al cheque que se rechaza             */
				SELECT	@sm_id				=	tct.sm_id	,
						@cust_id			=	tct.cust_id	,
						@cust_curr_id		=	tc.curr_id	,
						@ba_id				=	tct.ba_id	,	-- Parte		: 774
						@st_id				=	tc.st_id

					FROM	tbCommercialTransactions	tct			WITH (NOLOCK)
						INNER JOIN tbCustomer		tc			WITH (NOLOCK)
							ON tc.comp_id		=	tct.comp_id
							AND tc.cust_id		=	tct.cust_id
					WHERE	tct.comp_id			=	@comp_id
					--AND		tct.bra_id			=	@bra_id  NO PONER PLS
					AND		tct.ct_transaction	=	@ct_transaction
				/*******************************************************************************************************/




				/*******************************************************************************************************/
				DECLARE @bt_id	INT, @ct_transaction_new INT, @supp_curr_id INT


				--recuperamos el bt_id de tbCheckPortfolioMovements
				SELECT	TOP 1
						@bt_id				= tcpm.bt_id,
						@ct_transaction_new = tcpm.ct_transaction

					FROM	tbCheckPortfolioMovements tcpm			WITH (NOLOCK)

					WHERE	tcpm.comp_id		= @comp_id
					--AND		tcpm.bra_id			= @bra_id NO USAR PLS
					AND		tcpm.mm_isCancelled = 'false'
					AND		tcpm.chp_id			= @chp_id

					ORDER BY tcpm.chpm_id DESC



				-- Si no lo encuentran debe CANCELAR la transaccion!!!!
				IF @ct_transaction_new IS NULL
					BEGIN
						Set		@ret_ErrorCode			=	-1
						Set		@ret_ErrorDescription	=	'ERROR 18698: No se generó el ct_transaction asociado.!'
						RETURN
					END



				--obtiene datos de la tabla tbcommercialtransaction relacionado al rechazo en si
				SELECT	@ba_id				=	tct.ba_id,
						@supp_id			=	tct.supp_id,		-- Parte		: 774
						@supp_curr_id		=	tct.ct_ACurrency
					FROM	tbCommercialTransactions	tct
					WHERE	tct.comp_id			=	@comp_id
					--AND		tct.bra_id			=	@bra_id
					AND		tct.ct_transaction	=	@ct_transaction_new




				-- Parte		: 774
				-- si el cheque rechazado estaba depositado se genera el contramovimiento en el extracto bancario
				IF (NOT @ba_id IS NULL) AND @supp_id IS NULL
				BEGIN



					DECLARE @ct_transaction_generated	INT

					INSERT INTO tbCommercialTransactions
					(
						comp_id,				bra_id,					ct_pointOfSale,
						ct_kindOf,				ct_docNumber,			ct_date,
						ct_taxDate,				ct_payDate,				supp_id,
						cust_id,				ba_id,					cb_id,
						[user_id],				ct_cd,					ct_subtotal,
						ct_total,				ct_discount,			ct_adjust,
						ct_taxes,				curr_id_transaction,	hacc_transaction,
						sm_id,					disc_id,				ct_ATotal,
						ct_ABalance,			ct_ACurrency,			ct_ACurrencyExchange,
						df_id,					dl_id,					st_id,
						sd_id,					puco_id,				ct_CompanyCurrency,
						ct_Branch2CompanyCurrencyExchange,				ct_Pending,
						country_id,				state_id,				ct_isAvailableForImport,
						ct_soh_bra_id,			ct_soh_id,				ct_CAI,
						ct_CAIDate,				ct_CAIBarCodeImage,		ct_isAvailableForPayment,
						ct_transaction_PackingList,						ct_processingDate,
						ct_AAdjust,				ct_dfExchange,			curr_id4Exchange,
						ct_curr_IdExchange,		curr_id4dfExchange,		ct_AllUseTag1,
						ct_AllUseTag2,			ct_AllUseTag3,			ct_AllUseTag4,
						ct_FEIdNumber,			ct_packagesQty
					)
					SELECT
						comp_id,				bra_id,					ct_pointOfSale,
						ct_kindOf,				ct_docNumber,			@bra_processingDate,
						@bra_processingDate,	@bra_processingDate,	null,
						cust_id,				@ba_id,					cb_id,
						@user_id,				ct_cd,
						dbo.fnGetExchange(@comp_id,@chp_total,@chp_curr_id,@bra_curr_id,0,0,'false'),		--ct_subtotal,
						dbo.fnGetExchange(@comp_id,@chp_total,@chp_curr_id,@bra_curr_id,0,0,'false'),		--ct_total,
						0,						0,
						ct_taxes,				curr_id_transaction,	hacc_transaction,
						sm_id,					disc_id,
						dbo.fnGetExchange(@comp_id,@chp_total,@chp_curr_id,@bra_curr_id,0,0,'false'),		--ct_ATotal,
						dbo.fnGetExchange(@comp_id,@chp_total,@chp_curr_id,@bra_curr_id,0,0,'false'),		--ct_ABalance,
						ct_ACurrency,
						ct_ACurrencyExchange,
						NULL,					dl_id,					st_id,
						251,					puco_id,				ct_CompanyCurrency,
						ct_Branch2CompanyCurrencyExchange,				ct_Pending,
						country_id,				state_id,				ct_isAvailableForImport,
						ct_soh_bra_id,			ct_soh_id,				ct_CAI,
						ct_CAIDate,				ct_CAIBarCodeImage,		ct_isAvailableForPayment,
						ct_transaction_PackingList,						GETDATE(),
						0,						ct_dfExchange,			curr_id4Exchange,
						ct_curr_IdExchange,		curr_id4dfExchange,		ct_AllUseTag1,
						ct_AllUseTag2,			ct_AllUseTag3,			ct_AllUseTag4,
						ct_FEIdNumber,			ct_packagesQty

					FROM	tbCommercialTransactions tct

					WHERE	tct.comp_id			= @comp_id
					--AND		tct.bra_id			= @bra_id
					AND		tct.ct_transaction	= @ct_transaction_new


					SET @ct_transaction_generated = @@IDENTITY




					--recuperamos el texto a agregar en las notas del movimineto bancario
					DECLARE @desc NVARCHAR(100)
					SELECT	@desc			= tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id		= @lang_id
						AND		tut.utexts_id	= 97


					--insertamos la contrapartida del movimiento bancario relacionado al cheque rechazado
					INSERT INTO tbBankingTransactions
					(
						comp_id,
						ba_id,
						bra_id,
						btt_id,
						ec_id,
						chp_id,
						bt_total,
						curr_id,
						bt_imputationDate,
						bt_isConciliated,
						bt_isCancelled,
						ct_transaction,
						ccm_id,
						bt_note,
						bt_Number,
						bt_BranchCurrencyExchange,
						bt_Sold
					)
					SELECT 	comp_id,
							ba_id,
							bra_id,
							1000002,
							ec_id,
							chp_id,
							bt_total,
							curr_id,
							@bra_processingDate,
							'false',
							bt_isCancelled,
							@ct_transaction_generated,
							ccm_id,
							ISNULL(bt_note,'') + ' - ' + @desc + ' (' + @chp_Number + ')',
							bt_Number,
							bt_BranchCurrencyExchange,
							bt_Sold

						FROM	tbBankingTransactions tbt			WITH (NOLOCK)

						WHERE	tbt.comp_id	= @comp_id
						AND		tbt.ba_id	= @ba_id
						AND		tbt.bt_id	= @bt_id


				END


				-- si el cheque rechazado estaba entregado en parte de pago a un proveedor se genera un movimiento
				-- de crédito al proveedor
				IF (@ba_id IS NULL) AND (NOT @supp_id IS NULL) AND @chkSetCredit = 'true'
				BEGIN

					INSERT INTO tbCommercialTransactions
					(
						comp_id,				bra_id,					ct_pointOfSale,
						ct_kindOf,				ct_docNumber,			ct_date,
						ct_taxDate,				ct_payDate,				supp_id,
						cust_id,				ba_id,					cb_id,
						[user_id],				ct_cd,					ct_subtotal,
						ct_total,				ct_discount,			ct_adjust,
						ct_taxes,				curr_id_transaction,	hacc_transaction,
						sm_id,					disc_id,				ct_ATotal,
						ct_ABalance,			ct_ACurrency,			ct_ACurrencyExchange,
						df_id,					dl_id,					st_id,
						sd_id,					puco_id,				ct_CompanyCurrency,
						ct_Branch2CompanyCurrencyExchange,				ct_Pending,
						country_id,				state_id,				ct_isAvailableForImport,
						ct_soh_bra_id,			ct_soh_id,				ct_CAI,
						ct_CAIDate,				ct_CAIBarCodeImage,		ct_isAvailableForPayment,
						ct_transaction_PackingList,						ct_processingDate,
						ct_AAdjust,				ct_dfExchange,			curr_id4Exchange,
						ct_curr_IdExchange,		curr_id4dfExchange,		ct_AllUseTag1,
						ct_AllUseTag2,			ct_AllUseTag3,			ct_AllUseTag4,
						ct_FEIdNumber,			ct_packagesQty
					)
					SELECT
						comp_id,				bra_id,					ct_pointOfSale,
						ct_kindOf,				ct_docNumber,			@bra_processingDate,
						@bra_processingDate,	@bra_processingDate,	@supp_id,
						cust_id,				ba_id,					cb_id,
						@user_id,				ct_cd,
						dbo.fnGetExchange(@comp_id,@chp_total + @total,@chp_curr_id,@bra_curr_id,0,0,'false'),		--ct_subtotal,
						dbo.fnGetExchange(@comp_id,@chp_total + @total,@chp_curr_id,@bra_curr_id,0,0,'false'),		--ct_total,
						0,						0,
						ct_taxes,				curr_id_transaction,	hacc_transaction,
						sm_id,					disc_id,
						dbo.fnGetExchange(@comp_id,@chp_total + @total,@chp_curr_id,@supp_curr_id,0,0,'false'),		--ct_ATotal,
						dbo.fnGetExchange(@comp_id,@chp_total + @total,@chp_curr_id,@supp_curr_id,0,0,'false'),		--ct_ABalance,
						ct_ACurrency,
						ct_ACurrencyExchange,
						df_id,					dl_id,					st_id,
						125,					puco_id,				ct_CompanyCurrency,
						ct_Branch2CompanyCurrencyExchange,				ct_Pending,
						country_id,				state_id,				ct_isAvailableForImport,
						ct_soh_bra_id,			ct_soh_id,				ct_CAI,
						ct_CAIDate,				ct_CAIBarCodeImage,		ct_isAvailableForPayment,
						ct_transaction_PackingList,						GETDATE(),
						0,						ct_dfExchange,			curr_id4Exchange,
						ct_curr_IdExchange,		curr_id4dfExchange,		ct_AllUseTag1,
						ct_AllUseTag2,			ct_AllUseTag3,			ct_AllUseTag4,
						ct_FEIdNumber,			ct_packagesQty

					FROM	tbCommercialTransactions tct			WITH (NOLOCK)

					WHERE	tct.comp_id			= @comp_id
					--AND		tct.bra_id			= @bra_id
					AND		tct.ct_transaction	= @ct_transaction_new


				END
				/*******************************************************************************************************/

				DECLARE @df_id4ChequeRejection		AS INT = NULL
				DECLARE @df_id4RejectionCharges		AS INT = null


				-- Busco el documento para el Valor a Rechazar
				select	top 1 @df_id4ChequeRejection = df_id
					from	dbo.fnDocumentsFile_GetDocumentsForChequeRejection(@comp_id, @bra_id, @cust_id) tmp
					WHERE tmp.sd_id = 21
					ORDER BY df_order

				-- Busco el Documento para los Cargos del Rechazo
				select	top 1 @df_id4RejectionCharges = df_id
					from	dbo.fnDocumentsFile_GetDocumentsForChequeRejection(@comp_id, @bra_id, @cust_id) tmp
					WHERE tmp.sd_id = 4	-- Siempre debe ser una ND
				ORDER BY	CASE
								WHEN tmp.df_favorite4ChequeRejection = 1 THEN 0
								ELSE 1
							END,
							df_order

				-- Si NO se hacen en documentos separados, todo sale en la Misma ND
				IF @df_id4ChequeRejection IS NULL SET @df_id4ChequeRejection = @df_id4RejectionCharges


				-- MOS 08-2020 x PUTA AFIP y su FORRADA MENTAL
				--select	top 1 @bra_CR_dfId4Debit = df_id
				--	from	dbo.fnDocumentsFile_GetDocumentsForChequeRejection(@comp_id, @bra_id, @cust_id)
				--	where	sd_isDebitNote = 'true'
				--	ORDER BY df_order


				/*******************************************************************************************************/
				/* obtiener datos de la sucursal MOS                                                                   */
				--select	top 1 @bra_CR_dfId4Debit = df_id
				--	from	dbo.fnDocumentsFile_GetDocumentsForDebitCreditNotes(@comp_id, @bra_id, @cust_id)
				--	where	sd_isDebitNote = 'true'
				--	ORDER BY df_order


				-- Controlo q haya algun documento definido
				IF /*@bra_CR_dfId4Debit*/ @df_id4ChequeRejection IS NULL
					BEGIN
						SET  	@return_value			=	0
						SET 	@ret_ErrorCode			=	-1
						Select	@ret_ErrorDescription = utexts_desc + cast(@cust_id AS VARCHAR(10))
							From dbo.tbsysUniqueTexts		WITH (NOLOCK)
							Where lang_id = @lang_id and  utexts_id = 20229
						RETURN
					END




				SELECT	@ssos_id		= 220


				DECLARE @soh_total DECIMAL(19,6)
				SET		@soh_total = @total + @chp_total

				SELECT @ExchangeToCustomerCurrency = dbo.fnGetExchange(@comp_id, 1, @bra_curr_id, @cust_curr_id, 0, 0, 'False')


				/* recuperar el próximo id de saleorderheader                                                          */
				EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @soh_id OUTPUT


				/* recuperamos un descuento con valor cero                                                             */
				SET @disc_id = NULL

				SELECT	TOP 1 @disc_id = td.disc_id
					FROM	tbDiscount td		WITH (NOLOCK)
					WHERE	td.comp_id = @comp_id
					AND		(td.bra_id IS NULL OR td.bra_id = @bra_id)
					AND		td.disc_coef = 0
					ORDER BY td.disc_desc



				DECLARE @soh_id4ValoraRechazar AS INT = @soh_id
				IF		@df_id4ChequeRejection <> @df_id4RejectionCharges
					BEGIN
						EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @soh_id4ValoraRechazar OUTPUT
					END



				-- Si se hace en una Sola ND
				IF @df_id4ChequeRejection = @df_id4RejectionCharges
					BEGIN
						/* insertar el pedido por Valores Rechazados														   */
						exec dbo.spSaleOrderHeader_insertData  	@comp_id, @bra_id, @soh_id, @bra_processingDate, @bra_processingDate,
																@observation1, '', '', '', 'False', @sm_id, @cust_id, @st_id, @disc_id,
																null, null, @bra_processingDate, null, null, null, 0, @user_id,
																'False', null, @soh_total, @df_id4ChequeRejection, @ssos_id,
																@ExchangeToCustomerCurrency,@cust_curr_id

					END
				ELSE	-- Si se hace por SEPARADO la ND y el rechazo interno x saldo inicial
					BEGIN
						-- Cheque Rechazado en SI Deuda
						exec dbo.spSaleOrderHeader_insertData  	@comp_id, @bra_id,
																@soh_id4ValoraRechazar, @bra_processingDate, @bra_processingDate,
																@observation1, '', '', '', 'False', @sm_id, @cust_id, @st_id, @disc_id,
																null, null, @bra_processingDate, null, null, null, 0, @user_id,
																'False', null, @chp_total , @df_id4ChequeRejection, @ssos_id,
																@ExchangeToCustomerCurrency,@cust_curr_id

						-- Cargo de Rechazo en ND
						exec dbo.spSaleOrderHeader_insertData  	@comp_id, @bra_id,
																@soh_id, @bra_processingDate, @bra_processingDate,
																@observation1, '', '', '', 'False', @sm_id, @cust_id, @st_id, @disc_id,
																null, null, @bra_processingDate, null, null, null, 0, @user_id,
																'False', null, @total, @df_id4RejectionCharges, @ssos_id,
																@ExchangeToCustomerCurrency,@cust_curr_id
					END



				/*******************************************************************************************************/
				/* actualizar el número de cheque en saleorderheader                                                   */
				UPDATE	tbSaleOrderHeader
					SET		chp_id	= @chp_id
					WHERE	comp_id = @comp_id	AND
							bra_id  = @bra_id	AND
							soh_id	IN (@soh_id,@soh_id4ValoraRechazar)
				/*******************************************************************************************************/



				DECLARE @date	DATETIME
				SET		@date = GETDATE()



				/************************************************************************************* # ch******************/
				/* insertar ítem por cheque rechazado                                                  */
				exec dbo.[spSaleOrderDetail_insertData]	@comp_id, @bra_id, @soh_id4ValoraRechazar, 0,  NULL , @observation2, '',
														@bra_curr_id, 1, 1,	null, @chp_total, null, @user_id,
														@date, @bra_CR_taxId4Cheque, 0, @rv OUTPUT, null, NULL,
														NULL,NULL,NULL,NULL,NULL,'false'

				-- Actualiza la Cuenta Contable a Asignar.-
				UPDATE tbSaleOrderDetail
					SET acc_count_id = @bra_CR_taxId4Cheque_acc_count_id
					WHERE	comp_id = @comp_id					AND
							soh_id	= @soh_id4ValoraRechazar	AND
							bra_id  = @bra_id					AND
							sod_id	= @rv
				/*******************************************************************************************************/



				/*******************************************************************************************************/
				/* insertar ítem por cargos por cheque rechazado                                                       */
				exec dbo.[spSaleOrderDetail_insertData]	@comp_id, @bra_id, @soh_id,	0, null, @observation3, '',
														@bra_curr_id, 1, 1,	null, @total, null, @user_id,
														@date, @bra_CR_taxId4Charge, 0, @rv OUTPUT, null, NULL,
														NULL,NULL,null,NULL,NULL, 'false'

				-- Actualiza la Cuenta Contable a Asignar.-
				UPDATE tbSaleOrderDetail
					SET acc_count_id = @bra_CR_taxId4Charge_acc_count_id
					WHERE		comp_id = @comp_id	AND
								soh_id	= @soh_id	AND
								bra_id  = @bra_id	AND
								sod_id	= @rv
				/*******************************************************************************************************/



				/*******************************************************************************************************/
				/* actualización de accounttransaction                                                                 */
				--IF @chkSetCredit = 'true' -- Referencia: #1    NO ENFERMO HDP!!!!!
				BEGIN
					EXEC spAccountTransaction_InsertdataFromCheckRejection
						@comp_id,
						@bra_idAT,
						@lang_id,
						@chp_id,
						1,
						@user_id,
						@ret_Identity			= @return_Identity			OUTPUT,
						@ret_ErrorCode			= @return_ErrorCode			OUTPUT,
						@ret_ErrorDescription	= @return_ErrorDescription	OUTPUT
					IF @return_ErrorCode < 0
					BEGIN
						SELECT 	@ret_ErrorCode			= @return_ErrorCode,
								@ret_ErrorDescription	= @return_ErrorDescription
						RETURN
					END
				END
				/*******************************************************************************************************/



				/***********************************/
				/* terminado el rechazo del cheque */
				/***********************************/

			END
			ELSE
			BEGIN

				SET		@ret_ErrorCode			= -2

				SELECT	@ret_ErrorDescription	= tut.utexts_desc
				FROM	tbsysUniqueTexts		tut
				WHERE	tut.lang_id				= @lang_id
				AND		tut.utexts_id			= 100

			END


			--COMMIT TRANSACTION


		END
		-- -------------------------------------------------------------------

	ELSE

		-- -------------------------------------------------------------------
		-- Des hacer Pedido de cheque rechazado
		-- -------------------------------------------------------------------
		BEGIN


			DECLARE @bra4Delete AS INT	= NULL,
					@soh4Delete AS INT	= NULL
			SELECT	@bra4Delete = tsoh.bra_id,
					@soh4Delete = tsoh.soh_id
				FROM tbSaleOrderDetail	sod
				INNER JOIN tbSaleOrderHeader AS tsoh
					ON	tsoh.comp_id	= sod.comp_id	AND
						tsoh.soh_id		= sod.soh_id	AND
						tsoh.bra_id		= sod.bra_id
				WHERE	tsoh.comp_id	= @comp_id		AND
						tsoh.chp_id		= @chp_id		AND
						ISNULL(tsoh.soh_isEditing, 'False')	= 'False'



			IF @soh4Delete IS NOT NULL --@@ROWCOUNT > 0
				BEGIN

					EXEC spSaleOrder_deleteDataDirect
						@comp_id ,
						@bra4Delete,
						@soh4Delete,
						@user_id



					-- -------------------------------------------------------
					-- Borrado de POsible Segundo Pedido si es q fueron en DOS
					-- -------------------------------------------------------
					SET @bra4Delete = NULL
					SET @soh4Delete = NULL
					SELECT	@bra4Delete = tsoh.bra_id,
							@soh4Delete = tsoh.soh_id
						FROM tbSaleOrderDetail	sod
						INNER JOIN tbSaleOrderHeader AS tsoh
							ON	tsoh.comp_id	= sod.comp_id	AND
								tsoh.soh_id		= sod.soh_id	AND
								tsoh.bra_id		= sod.bra_id
						WHERE	tsoh.comp_id	= @comp_id		AND
								tsoh.chp_id		= @chp_id		AND
								ISNULL(tsoh.soh_isEditing, 'False')	= 'False'

					IF @soh4Delete IS NOT NULL
						BEGIN
							EXEC spSaleOrder_deleteDataDirect
								@comp_id ,
								@bra4Delete,
								@soh4Delete,
								@user_id
						END
					-- -------------------------------------------------------


					UPDATE	tbCheckPortfolio
						SET		chp_isRejected	= @chp_isRejected
						WHERE	comp_id			= @comp_id
						AND		chp_id			= @chp_id


					-- Pone como CANCELADO el movimiento de RECHAZO
					UPDATE tbBankingTransactions
						SET	bt_isCancelled = 'True'
					WHERE	comp_id = @comp_id	AND
							chp_id	= @chp_id	AND
							btt_id	= 1000002



					/*******************************************************************************************************/
					/* actualización de accounttransaction                                                                 */
					--IF @chkSetCredit = 'true' -- Referencia: #1   NO ENFERMO HDP!!!!!
					BEGIN
						EXEC spAccountTransaction_InsertdataFromCheckRejection
							@comp_id,
							@bra_id,
							@lang_id,
							@chp_id,
							3,
							@user_id,
							@ret_Identity			= @return_Identity			OUTPUT,
							@ret_ErrorCode			= @return_ErrorCode			OUTPUT,
							@ret_ErrorDescription	= @return_ErrorDescription	OUTPUT
						IF @return_ErrorCode < 0
						BEGIN
							SELECT 	@ret_ErrorCode			= @return_ErrorCode,
									@ret_ErrorDescription	= @return_ErrorDescription
							RETURN
						END
					END
					/*******************************************************************************************************/


				END
			ELSE
				BEGIN

					SET		@ret_ErrorCode			= -2

					SELECT	@ret_ErrorDescription =
							tut.utexts_desc +
							CASE WHEN tsoh.soh_isEditing = 'True' THEN
								' - ' +
								'<b>' + tut2.utexts_desc + '</b>' + isnull(CONVERT(VARCHAR,tsoh.soh_id),'') + ' - ' +
								'<b>' + tut3.utexts_desc + '</b>' +
								ISNULL(							CASE
																WHEN LEN(tu.user_lastname) > 2 AND LEN(tu.user_firstname) > 2
																	THEN ' ' + tu.user_lastname + ', ' + tu.user_firstname
																WHEN LEN(tu.user_lastname) < 3 AND LEN(tu.user_firstname) > 2
																	THEN ' ' + tu.user_firstname
																WHEN LEN(tu.user_lastname) > 2 AND LEN(tu.user_firstname) < 3
																	THEN ' ' + tu.user_lastname
																WHEN LEN(tu.user_lastname) < 3 AND LEN(tu.user_firstname) < 3
																	THEN ''
															END, '')
								ELSE
								' - ' + '<b>' + tut4.utexts_desc + '</b>'
							END

					FROM	tbsysUniqueTexts					tut			WITH (NOLOCK)

							LEFT JOIN tbSaleOrderHeader			tsoh			WITH (NOLOCK)
							ON	tsoh.comp_id		= @comp_id
							and	tsoh.soh_id			IN (SELECT	tsoh1.soh_id
														FROM	tbSaleOrderHeader	tsoh1	WITH (NOLOCK)
														WHERE	tsoh1.chp_id		= @chp_id)

							LEFT JOIN tbUser					tu			WITH (NOLOCK)
							ON	tu.[user_id]		= tsoh.[user_id]

							INNER JOIN tbsysUniqueTexts			tut2		WITH (NOLOCK)
							ON	tut2.lang_id		= tut.lang_id
							AND tut2.utexts_id		= 102

							INNER JOIN tbsysUniqueTexts			tut3		WITH (NOLOCK)
							ON	tut3.lang_id		= tut.lang_id
							AND tut3.utexts_id		= 103

							INNER JOIN tbsysUniqueTexts			tut4		WITH (NOLOCK)
							ON	tut4.lang_id		= tut.lang_id
							AND tut4.utexts_id		= 104

					WHERE	tut.lang_id				= @lang_id
					AND		tut.utexts_id			= 101

				END

		/*****************************************/
		/* fin de deshacer cheque rechazado      */
		/*****************************************/

		END


	END TRY

	BEGIN CATCH

		--ROLLBACK TRANSACTION
		Set		@ret_ErrorCode			=	-1
		Set		@ret_ErrorDescription	=	ERROR_MESSAGE()

	END CATCH

END
GO

CREATE PROCEDURE [dbo].[spCheckPortfolioMovements_GetData4GenericGrid]
(
	@comp_id	INT,
	@chp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- --------------------------------------
		-- TESTING
		-- --------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@chp_id		INT
			SELECT
				@comp_id	= 1,
				@chp_id		= 298
		*/
		-- --------------------------------------

		SELECT 
			tb.bra_desc,
			tbn.bn_name,
			tvtt.svtt_desc,
			tcpm.mm_isCancelled,
			tct.ct_transaction,
			tu.user_lastname + ',' + tu.user_firstname		[user_name]
			FROM tbCheckPortfolioMovements			tcpm	WITH(NOLOCK)
			INNER JOIN tbsysValuesTransactionTypes	tvtt	WITH(NOLOCK)
				ON	tvtt.svtt_id	= tcpm.svtt_id
			INNER JOIN tbCommercialTransactions		tct		WITH(NOLOCK)
			ON	tct.comp_id			= tcpm.comp_id	AND
				tct.ct_transaction	= tcpm.ct_transaction
			INNER JOIN tbCheckPortfolio				tcp1	WITH(NOLOCK)
			ON	tcp1.comp_id		= tcpm.comp_id	AND
				tcp1.chp_id			= tcpm.chp_id
			INNER JOIN tbBanksName					tbn		WITH(NOLOCK)
			ON	tbn.comp_id			= tcp1.comp_id	AND
				tbn.bn_id			= tcp1.bn_id
			INNER JOIN tbBranch						tb		WITH(NOLOCK)
			ON	tb.comp_id			= tct.comp_id	AND
				tb.bra_id			= tct.bra_id
			INNER JOIN tbUser						tu		WITH(NOLOCK)
			ON	tu.[user_id]		= tct.[user_id]
			WHERE	tcpm.comp_id	= @comp_id		AND 
					tcpm.chp_id		= @chp_id
			ORDER BY tcp1.chp_id DESC

	END
GO






