as
set nocount on
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-08-19
-- Parte		: 480
-- Description	: Agregado del campo DNI en la carga de cheques en cobranzas
-- =================================================================================================================






select	' ' [ ], ' ' [ ],
		chpt.chpt_guid,
		chpt.bra_id,
		chpt.ct_transaction,
		chpt.chpt_number,
		chpt.chpt_total,
		chpt.chpt_EmissionDate,
		chpt.chpt_PayDate,
		chpt.bn_id,
		bn.bn_name,
		chpt.chpt_BankBranch,
		chpt.chpt_BankBranchDescription,
		chpt.chpt_AccountNumber,
		isnull(chpt.chpt_taxNumber1,'')			[chpt_taxNumber1],
		isnull(chpt.chpt_taxNumber2,'')			[chpt_taxNumber2],
		isnull(chpt.chpt_taxNumber3,'')			[chpt_taxNumber3],
		chpt.chpt_isOwn,
		chpt.chpt_isAvailable,
		chpt.chpt_IsReceived,
		chpt.chpt_isRejected,
		chpt.chpt_isToOrder,
