order by chpt.chpt_id






















GO







CREATE  PROCEDURE [dbo].[spCheckPortfolioTmp_insertData]
(
	@comp_id						int,
	@chpt_guid						uniqueidentifier,
	@bra_id							int,
	@ct_transaction					int,
	@chpt_number					varchar(40),
	@chpt_total						decimal(19,5),
	@chpt_EmissionDate				datetime,
	@chpt_PayDate					datetime,
	@bn_id							int,
	@chpt_BankBranch				varchar(50),
	@chpt_BankBranchDescription		varchar(50),
	@chpt_AccountNumber				varchar(40),
	@chpt_taxNumber1				varchar(20),
	@chpt_taxNumber2				varchar(20),
	@chpt_taxNumber3				varchar(20),
	@chpt_isOwn						bit,
	@chpt_isAvailable				bit,
	@chpt_IsReceived				bit,
	@chpt_isRejected				bit,
	@chpt_isToOrder					bit,
	@chpt_Note						varchar(80),
	@curr_id						int,
	@country_id						int,
	@chpt_isDocument				bit,
	@chpt_DocumentDescription		varchar(50),
	@chpt_documentNumber			NVARCHAR(25),
	@chpt_QtyEndosos				INT,
	@ba_id							INT,
	@chp_isElectronic				BIT,
	--Parte:480
	@return_value					int output
)
as
set nocount on
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-08-19
-- Parte		: 480
-- Description	: Agregado del campo DNI en la carga de cheques en cobranzas
-- =================================================================================================================



insert into dbo.tbCheckPortfolioTmp
( comp_id, chpt_guid, bra_id, ct_transaction, chpt_number,
	chpt_total, chpt_EmissionDate, chpt_PayDate, bn_id, chpt_BankBranch,
	chpt_BankBranchDescription, chpt_AccountNumber, chpt_taxNumber1,
	chpt_taxNumber2, chpt_taxNumber3, chpt_isOwn, chpt_isAvailable,
	chpt_IsReceived, chpt_isRejected, chpt_isToOrder, chpt_Note,
	curr_id, country_id, chpt_isDocument, chpt_DocumentDescription,
	chpt_documentNumber,chpt_QtyEndosos,ba_id,chp_isElectronic)												--Parte:480

values
( @comp_id, @chpt_guid, @bra_id, @ct_transaction, @chpt_number,
	@chpt_total, @chpt_EmissionDate, @chpt_PayDate, @bn_id,
	@chpt_BankBranch, @chpt_BankBranchDescription, @chpt_AccountNumber,
	@chpt_taxNumber1, @chpt_taxNumber2, @chpt_taxNumber3, @chpt_isOwn,
	@chpt_isAvailable, @chpt_IsReceived, @chpt_isRejected,
	@chpt_isToOrder, @chpt_Note, @curr_id, @country_id,
	@chpt_isDocument, @chpt_DocumentDescription,
	@chpt_documentNumber,@chpt_QtyEndosos,@ba_id,@chp_isElectronic)												--Parte:480


set	@return_value = @@identity
GO








CREATE  PROCEDURE [dbo].[spCheckPortfolioTmp_updateData]
(
	@chpt_guid						uniqueidentifier,
	@chpt_id						int,
	@ct_transaction					int,
	@chpt_number					varchar(40),
	@chpt_total						decimal(19,5),
	@chpt_EmissionDate				datetime,
	@chpt_PayDate					datetime,
	@bn_id							int,
	@chpt_BankBranch				varchar(50),
	@chpt_BankBranchDescription		varchar(50),
	@chpt_AccountNumber				varchar(40),
	@chpt_taxNumber1				varchar(20),
	@chpt_taxNumber2				varchar(20),
	@chpt_taxNumber3				varchar(20),
	@chpt_isOwn						bit,
	@chpt_isAvailable				bit,
	@chpt_IsReceived				bit,
	@chpt_isRejected				bit,
	@chpt_isToOrder					bit,
	@chpt_Note						varchar(80),
	@curr_id						int,
	@country_id						int,
	@chpt_isDocument				bit,
	@chpt_DocumentDescription		varchar(50),
	@chpt_documentNumber			NVARCHAR(25),						--Parte:480
	@chpt_QtyEndosos				INT,
	@ba_id							INT,
	@chp_isElectronic				BIT
)
as
set nocount on
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-08-19
-- Parte		: 480
-- Description	: Agregado del campo DNI en la carga de cheques en cobranzas
-- =================================================================================================================

if	(@ba_id			= -1)	set	@ba_id			= NULL


update	dbo.tbCheckPortfolioTmp

set		ct_transaction				= @ct_transaction,
		chpt_number					= @chpt_number,
		chpt_total					= @chpt_total,
		chpt_EmissionDate			= @chpt_EmissionDate,
		chpt_PayDate				= @chpt_PayDate,
		bn_id						= @bn_id,
		chpt_BankBranch				= @chpt_BankBranch,
		chpt_BankBranchDescription	= @chpt_BankBranchDescription,
		chpt_AccountNumber			= @chpt_AccountNumber,
		chpt_taxNumber1				= @chpt_taxNumber1,
		chpt_taxNumber2				= @chpt_taxNumber2,
		chpt_taxNumber3				= @chpt_taxNumber3,
		chpt_isOwn					= @chpt_isOwn,
		chpt_isAvailable			= @chpt_isAvailable,
		chpt_IsReceived				= @chpt_IsReceived,
		chpt_isRejected				= @chpt_isRejected,
		chpt_isToOrder				= @chpt_isToOrder,
		chpt_Note					= @chpt_Note,
		curr_id						= @curr_id,
		country_id					= @country_id,
		chpt_isDocument				= @chpt_isDocument,
		chpt_DocumentDescription	= @chpt_DocumentDescription,
		chpt_documentNumber			= @chpt_documentNumber,			--Parte:480
		chpt_QtyEndosos				= @chpt_QtyEndosos,
		ba_id						= @ba_id,
		chp_isElectronic			= @chp_isElectronic

where	chpt_guid					= @chpt_guid
and	    chpt_id						= @chpt_id
GO







CREATE PROCEDURE [dbo].[spCheckPortfolioTMP_updateIsEditing]
(
	@chpt_guid			AS UNIQUEIDENTIFIER
)
AS

BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	UPDATE	tbCheckPortfolioTMP

	SET	    chpt_isEditing 		= 'True',
			chpt_isEditingCD	= GETDATE()

	WHERE	chpt_guid			= @chpt_guid


END




GO




CREATE Procedure [dbo].[spChequePortfolio_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@selection_id		int,
		@datefromdeposit	datetime,
		@datetodeposit		datetime,
		@datefrommov		datetime,
		@datetomov			datetime,
		@egressDateFrom		DATETIME,
		@egressDateTo		DATETIME,
		@bankacc			int,
		@custsupp			int,
		@curr_id			int,
		@values				INT,
		@chp_isown			INT,
		@chp_isToOrder      INT,
		@bra_id				INT,
		@brag_id			INT,
		@ba_id4custody		int,
		@chp_isElectronic	INT,
		@intBranch4Lang		int
)
AS


BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


	set nocount on
	set dateformat 'ymd'


	-- ----------------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------------
	/*
	Declare
			@comp_id			int,
			@lang_id			int,
			@page_id			int,

			@selection_id		int,
			@datefromdeposit	datetime,
			@datetodeposit		datetime,
			@datefrommov		datetime,
			@datetomov			datetime,
			@bankacc			int,
			@custsupp			int,
			@curr_id			int,
			@bra_id				INT,
			@values				INT,
			@chp_isown			INT,
			@brag_id			INT,
			@chp_isToOrder      INT,
			@ba_id4custody		INT,
			@intBranch4Lang		INT,
			@egressDateFrom		DATETIME,
			@egressDateTo		DATETIME

	Select
			@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10014,
			@selection_id		= -1,
			@datefromdeposit	= '1900-01-01',
			@datetodeposit		= '9999-12-31',
			@datefrommov		= '1900-01-01',
			@datetomov			= '2017-12-26',
			@egressDateFrom		= '2017-12-27',
			@egressDateTo		= '2999-12-31',
			@bankacc			= -1,
			@custsupp			= -1,  --24294
			@curr_id			= 1,
			@bra_id				= 1,
			@values				= 7,
			@chp_isown			= -1,
			@chp_isToOrder		= -1,
			@ba_id4custody		=-1,
			@brag_id			= -1

	*/
	-- ----------------------------------------------------------------------






-- Incorpora las sucursales de las cuales se tomaran los valores a listar.
	DECLARE @tmpBranch AS TABLE (bra_id INT PRIMARY	KEY)
	INSERT INTO @tmpBranch (bra_id) VALUES (@bra_id)
	INSERT INTO @tmpBranch (bra_id)
		SELECT bra_id
			FROM tbBranchGroupDetail tbgd
		WHERE	tbgd.comp_id = @comp_id AND
				tbgd.brag_id = @brag_id AND
				NOT EXISTS ( SELECT TOP 1  1
								FROM @tmpBranch tmp
								WHERE tmp.bra_id = tbgd.bra_id)





	set	@datefromdeposit	= dbo.fnGetEnd_or_BeginOfDate(@datefromdeposit,'False')
	set	@datetodeposit		= dbo.fnGetEnd_or_BeginOfDate(@datetodeposit,'True')

	set	@datefrommov		= dbo.fnGetEnd_or_BeginOfDate(@datefrommov,'False')
	set	@datetomov			= dbo.fnGetEnd_or_BeginOfDate(@datetomov,'True')

	set	@egressDateFrom		= dbo.fnGetEnd_or_BeginOfDate(@egressDateFrom,'False')
	set	@egressDateTo		= dbo.fnGetEnd_or_BeginOfDate(@egressDateTo,'True')






	DECLARE @bra_Credit_AssumeValuesAcreditDays AS INT
	SET		@bra_Credit_AssumeValuesAcreditDays = 4
	DECLARE @bra_processingDate AS DATETIME
	SELECT  @bra_Credit_AssumeValuesAcreditDays = tb.bra_Credit_AssumeValuesAcreditDays,
			@bra_processingDate					= tb.bra_processingDate
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id
	SET @bra_Credit_AssumeValuesAcreditDays = @bra_Credit_AssumeValuesAcreditDays * -1


	DECLARE @fun_id INT
	SET		@fun_id = 1

	Select	--bt.bt_imputationDate,						--ref #20100820
			cp.chp_PayDate	[bt_imputationDate],		--ref #20100820
			cp.chp_number,
			bn.bn_name,
			c.cust_name,
			cp.chp_EmissionDate,
			cp.chp_total,
			cr.curr_desc,
			ba.ba_desc,
			br.bra_desc,
			ct.ct_ACurrencyExchange,
			ov.optval_desc				[DESC],
			bt.btt_id,
			c.cust_id,
			cp.chp_isOwn,
			cp.chp_isToOrder,
			ct.ct_date,
			ba2.ba_desc					[ba_desc4Custody],
			cp.chp_taxNumber1,
			CASE WHEN ISNULL(cp.chp_isElectronic,'False') = 'False' THEN	''
			ELSE															'e'
			END							[chp_isElectronic]


	From	dbo.tbCheckPortfolio						cp			WITH (NOLOCK)

			left join dbo.tbBankingTransactions			bt			WITH (NOLOCK)
			on	bt.comp_id			= cp.comp_id
			and	bt.bra_id			= cp.bra_id
			and	bt.chp_id			= cp.chp_id
			and bt.btt_id			= 1000020
			AND bt.bt_isCancelled   = 'False'

			left join dbo.tbBanksName					bn			WITH (NOLOCK)
			on	cp.comp_id			= bn.comp_id
			and cp.country_id		= bn.country_id
			and cp.bn_id			= bn.bn_id

			left join dbo.tbCommercialTransactions		ct			WITH (NOLOCK)
			on	cp.comp_id			= ct.comp_id
			--and cp.bra_id			= ct.bra_id  MOS 12-2017
			and cp.ct_transaction	= ct.ct_transaction

			left join dbo.tbCustomer					c			WITH (NOLOCK)
			on  ct.comp_id			= c.comp_id
			and c.cust_id			= ct.cust_id

			left join dbo.tbsysCurrency					cr			WITH (NOLOCK)
			on cp.curr_id			= cr.curr_id

			left join dbo.tbBankingAccounts				ba			WITH (NOLOCK)
			on  bt.comp_id			= ba.comp_id
			and bt.ba_id			= ba.ba_id

			left join dbo.tbBankingAccounts				ba2			WITH (NOLOCK)
			on  cp.comp_id			= ba2.comp_id
			and cp.ba_id			= ba2.ba_id

			left join dbo.tbBranch						br			WITH (NOLOCK)
			on  cp.comp_id			= br.comp_id
			and cp.bra_id			= br.bra_id

			inner join dbo.tbsysOptionsValues			ov			WITH (NOLOCK)
			on  ov.optval_class		= 13
			and ov.lang_id			= @lang_id
			and ov.optval_id		= cp.chp_isOwn

			-- Se filtra x la sucursal correcta.
			INNER JOIN @tmpBranch tmpb
				ON tmpb.bra_id = cp.bra_id_PortFolio

	Where	cp.comp_id				= @comp_id


	--	AND		cp.bra_id_PortFolio		= @bra_id	MOS 08-2013
	--	AND		cp.bra_id				= @bra_id   MOS  2-2013

	AND		(ct.ct_date				between @datefrommov and @datetomov OR @values = 7)
	AND		cp.curr_id				= @curr_id
	AND     (@chp_isown				= -1 OR		CP.chp_isOwn		= ~convert(bit,@chp_isown))	--ref #20100820
	AND     (@chp_isToOrder			= -1 OR		CP.chp_isToOrder	= ~convert(bit,@chp_isToOrder))
	AND		(@bankacc				= -1 or		ba.ba_id			= @bankacc)
	AND		(@custsupp				= -1 or		ct.cust_id			= @custsupp)
	AND		(@selection_id			= -1 or 	cp.chp_isDocument	= @selection_id)
	AND		(@ba_id4custody			= -1 OR		@ba_id4custody		= -2 and cp.ba_id is null OR cp.ba_id			= @ba_id4custody)
	AND		cp.chp_PayDate BETWEEN @datefromdeposit and @datetodeposit	AND
			(
				@chp_isElectronic	= -1 OR
				cp.chp_isElectronic = @chp_isElectronic
			)


	AND			CASE @values
					WHEN 0 THEN						-- Valores en Cartera
								CASE
									when cp.chp_isAvailable = 'True'  THEN 'True'
									ELSE 'False'
								END
					WHEN 1 THEN						-- Valores Egresados
								CASE
									WHEN		cp.chp_isAvailable = 'False'
											AND cp.chp_IsPayed     = 'True'
											AND EXISTS (	SELECT TOP 1 1
					            								FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
					            								WHERE	tcpm.comp_id		= cp.comp_id
					            									AND tcpm.chp_id			= cp.chp_id
					            									AND tcpm.svtt_id		= 30			-- Entrega de Valores a Proveedores
					            									AND tcpm.mm_isCancelled	= 'False')		THEN	'True'
									ELSE																			'False'
								END
					WHEN 2 THEN						-- Valores Depositados
								CASE
									WHEN		cp.chp_isAvailable	= 'False'
											AND cp.chp_IsPayed		= 'False'
											AND EXISTS (	SELECT TOP 1 1
					            								FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
					            								WHERE	tcpm.comp_id		= cp.comp_id
					            									AND tcpm.chp_id			= cp.chp_id
					            									AND tcpm.svtt_id		= 40			-- Deposito de Valores
					            									AND tcpm.mm_isCancelled	= 'False')		THEN	'True'
					            	ELSE																			'False'
								END
					WHEN 3 THEN						-- Valores Depositados y Acreditados
								CASE
									WHEN		cp.chp_isAvailable	= 'False'
											AND cp.chp_IsPayed		= 'True'
											AND EXISTS (	SELECT TOP 1 1
					            								FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
					            								WHERE	tcpm.comp_id		= cp.comp_id
					            									AND tcpm.chp_id			= cp.chp_id
					            									AND tcpm.svtt_id		= 40			-- Deposito de Valores
					            									AND tcpm.mm_isCancelled	= 'False')		THEN	'True'
									ELSE																			'False'
								END
					WHEN 4																					THEN	'True'		-- >Todfos
					WHEN 5 THEN						-- Todos sin Acreditar
								CASE
									WHEN	cp.chp_isRejected  = 'False'	AND
											cp.chp_isCancelled = 'False'	AND
										   (DATEDIFF(DAY,@bra_processingDate,cp.chp_PayDate) >= @bra_Credit_AssumeValuesAcreditDays)
																											THEN	'True'
									ELSE																			'False'
								END
					WHEN 6 THEN						-- Negociados
								CASE
									WHEN		cp.chp_isAvailable	= 'False'
											AND cp.chp_IsPayed		= 'True'
											AND cp.chp_isNegociated = 'True'
											AND EXISTS (	SELECT TOP 1 1
					            								FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
					            								WHERE	tcpm.comp_id		= cp.comp_id
					            									AND tcpm.chp_id			= cp.chp_id
					            									AND tcpm.svtt_id		= 40			-- Deposito de Valores
					            									AND tcpm.mm_isCancelled	= 'False')		THEN	'True'
					            	ELSE																			'False'
								END

					WHEN 8 THEN						-- Negociados  ( Mix 6 y 5 )
								CASE
									WHEN		cp.chp_isAvailable	= 'False'
											AND cp.chp_IsPayed		= 'True'
											AND cp.chp_isNegociated = 'True'
											AND cp.chp_isRejected  = 'False'
											AND cp.chp_isCancelled = 'False'
											AND (DATEDIFF(DAY,@bra_processingDate,cp.chp_PayDate) >= @bra_Credit_AssumeValuesAcreditDays)  -- Idem 5
											AND EXISTS (	SELECT TOP 1  1
					            								FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
					            								WHERE	tcpm.comp_id		= cp.comp_id
					            									AND tcpm.chp_id			= cp.chp_id
					            									AND tcpm.svtt_id		= 40			-- Deposito de Valores
					            									AND tcpm.mm_isCancelled	= 'False')		THEN	'True'
					            	ELSE																			'False'
								END
					WHEN 7 THEN -- Cartera a Fecha: Todos los que INGRESARON hasta una fecha y salieron DESPUES de esa fecha
								CASE
									WHEN EXISTS(
													SELECT TOP 1  1
														FROM tbCheckPortfolioMovements tcpm	WITH (NOLOCK)
														-->> Egresó
														INNER JOIN tbcommercialtransactions tct		WITH (NOLOCK)
															ON	tct.comp_id			= tcpm.comp_id			AND
																tct.ct_transaction	= tcpm.ct_transaction
														-->> Ingresó
														INNER JOIN tbCheckPortfolio			tcp1	WITH (NOLOCK)
															ON	tcp1.comp_id		= tcpm.comp_id			AND
																tcp1.chp_id			= tcpm.chp_id
														INNER JOIN tbcommercialtransactions tct2	WITH (NOLOCK)
															ON	tct2.comp_id		= tcp1.comp_id			AND
																tct2.ct_transaction	= tcp1.ct_transaction

														WHERE	tcpm.comp_id	= cp.comp_id							AND
															    tcpm.chp_id		= cp.chp_id								AND
															    tcpm.svtt_id IN (30,40)									AND
															    tct.ct_date		BETWEEN @egressDateFrom AND @egressDateTo	AND
															    tct2.ct_date	BETWEEN @datefrommov	AND @datetomov
												)
											OR
												(
													NOT EXISTS (
																	SELECT TOP 1  1
																		FROM tbCheckPortfolioMovements	tcpm	WITH (NOLOCK)
																		INNER JOIN tbCheckPortfolio		tcp1	WITH (NOLOCK)
																			ON	tcp1.comp_id	= tcpm.comp_id							AND
																				tcp1.chp_id		= tcpm.chp_id
																		INNER JOIN tbcommercialtransactions tct2	WITH (NOLOCK)
																			ON	tct2.comp_id			= tcp1.comp_id					AND
																				tct2.ct_transaction		= tcp1.ct_transaction
																		WHERE	tcpm.comp_id	= cp.comp_id							AND
																				tcpm.chp_id		= cp.chp_id								AND
																				tcpm.svtt_id IN (30,40)									--AND
																				--tcp1.chp_PayDate >= @egressDateFrom
																)
													AND
														ct.ct_date <= @datetomov
												)

																											THEN	'True'
									ELSE																			'False'

								END
					ELSE																							'False'
				END	= 'True'



				-- Se reemplazo por los CASE de arriba.-
				--AND
				--(
				--(@values = 4	)								OR
				--(@values = 0	AND cp.chp_isAvailable = 'True')								OR
				--(@values = 1	-- Entregados a Proveedores
				--	AND cp.chp_isAvailable = 'False'
				--	AND cp.chp_IsPayed     = 'True'
				--	AND EXISTS (	SELECT 1
				--	            		FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
				--	            		WHERE	tcpm.comp_id		= cp.comp_id
				--	            			AND tcpm.chp_id			= cp.chp_id
				--	            			AND tcpm.svtt_id		= 30			-- Entrega de Valores a Proveedores
				--	            			AND tcpm.mm_isCancelled	= 'False')
				--)
				--																				OR
				--(@values = 2
				--	AND cp.chp_isAvailable	= 'False'
				--	AND cp.chp_IsPayed		= 'False'
				--	AND EXISTS (	SELECT 1
				--	            		FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
				--	            		WHERE	tcpm.comp_id		= cp.comp_id
				--	            			AND tcpm.chp_id			= cp.chp_id
				--	            			AND tcpm.svtt_id		= 40			-- Deposito de Valores
				--	            			AND tcpm.mm_isCancelled	= 'False')

				--)																				OR
				--(@values = 3
				--	AND cp.chp_isAvailable	= 'False'
				--	AND cp.chp_IsPayed		= 'True'
				--	AND EXISTS (	SELECT 1
				--	            		FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
				--	            		WHERE	tcpm.comp_id		= cp.comp_id
				--	            			AND tcpm.chp_id			= cp.chp_id
				--	            			AND tcpm.svtt_id		= 40			-- Deposito de Valores
				--	            			AND tcpm.mm_isCancelled	= 'False')

				--)

				--)


			--@values = 0	Valores en Cartera
			--@values = 1	Valores Egresados
			--@values = 2	Valores Depositados
			--@values = 3	Valores Depositados	y Acreditados


	order by	--bt.bt_imputationDate,		--ref #20100820
				cp.chp_PayDate,				--ref #20100820
				c.cust_name




	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id




	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/************************************************************************************************************ */
	Select
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 398
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params1],
			CASE @selection_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				Else
						(Select tcp1.chp_number
						FROM	tbCheckPortfolio tcp1
	--					inner join dbo.tbsysOptionsValues			ov
	--					on  ov.optval_class		= 13
	--					and ov.lang_id			= @lang_id
						--and ov.optval_id		= tcp1.chp_isOwn

						 WHERE	tcp1.comp_id= @comp_id AND
						tcp1.chp_id = @selection_id
						)
			END		[params2],


	--					FROM	tbCheckPortfolio tcp1
	--					WHERE	tcp1.comp_id= @comp_id AND
	--					tcp1.chp_id = @selection_id)

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 411
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params3],

      		 @datefromdeposit[DateParams1],
			--convert(varchar,day(@datefromdeposit)) + '/' + convert(varchar,month(@datefromdeposit)) + '/' + convert(varchar,year(@datefromdeposit)) 	[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 412
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],

      		 @datetodeposit [DateParams2],
			--convert(varchar,day(@datetodeposit)) + '/' + convert(varchar,month(@datetodeposit)) + '/' + convert(varchar,year(@datetodeposit))		[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 413
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params7],

      		 @datefrommov [DateParams3],
			--convert(varchar,day(@datefrommov)) + '/' + convert(varchar,month(@datefrommov)) + '/' + convert(varchar,year(@datefrommov)) 	[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 414
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params9],

      		 @datetomov [DateParams4],
			--convert(varchar,day(@datetomov)) + '/' + convert(varchar,month(@datetomov)) + '/' + convert(varchar,year(@datetomov))		[params10],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 402
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params11],
			CASE @custsupp WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cust_name
						FROM	tbCustomer tc
						WHERE	Tc.comp_id= @comp_id AND tc.cust_id = @custsupp)
			END		[params12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
 		 WHERE t.ctrl_id = 406
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params13],
			CASE @bankacc WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tba.ba_desc
						FROM	tbBankingAccounts tba
						WHERE	tba.comp_id= @comp_id AND tba.ba_id = @bankacc)
			END		[params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 406
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params15],
			CASE @curr_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.curr_desc
						FROM	tbsysCurrency tc
						WHERE	tc.curr_id = @curr_id)
			END		[params16],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 300
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params17],
			(SELECT tov.optval_desc
			 FROM tbsysOptionsValues tov
			 WHERE tov.lang_id = @lang_id
			 AND tov.optval_class = 82
			 AND tov.optval_id = @values) [params18],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 753
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params19],

		 		CASE @chp_isown WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
		 		(SELECT tov.optval_desc
			 FROM tbsysOptionsValues tov
			 WHERE tov.lang_id = @lang_id
			 AND tov.optval_class = 83
			 AND tov.optval_id = @chp_isown) END [params20],

			  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1176
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params21],
		 		CASE @chp_isown WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
		 		(SELECT tov.optval_desc
			 FROM tbsysOptionsValues tov
			 WHERE tov.lang_id = @lang_id
			 AND tov.optval_class = 1
			 AND tov.optval_id = @chp_isown) END [params22],


			  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 639
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params23],
		 		CASE @brag_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
		 		(SELECT tbg.brag_desc
		 		 FROM tbBranchGroup tbg
			 WHERE tbg.comp_id = @comp_id
			 AND tbg.brag_id = @brag_id) END [params24],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2513
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params25],
		 		CASE @ba_id4custody WHEN -2 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 32
					)
					WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 31
					)

				ELSE
		 		(SELECT tba.ba_desc
		 		 FROM tbBankingAccounts tba
				 WHERE tba.comp_id = @comp_id
				 AND tba.ba_id = @ba_id4custody) END [params26],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 5733
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params27],
		 		CASE @chp_isElectronic WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
		 		(SELECT tov.optval_desc
				 FROM tbsysOptionsValues tov
				 WHERE tov.lang_id = @lang_id
				 AND tov.optval_class = 1
				 AND tov.optval_id = @chp_isElectronic) END [params28]









END
GO





-- OJO !!!! SI SE TOCA ALGO EN ESTE SP DE MIERDAAAAAAAAAAAA TAMBIEN
--	HAY QUE TOCAR EXACTAMENTE LO MISMO EN EL OTRO SP DE MIERDA LLAMADO [spChequePortfolio_getReport4Grid](IMPRIMIR REPORTE ) OK ? GRACIAS !

CREATE Procedure [dbo].[spChequePortfolio_getReport4Grid]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@selection_id		int,
		@datefromdeposit	NVARCHAR(30),
		@datetodeposit		NVARCHAR(30),
		@datefrommov		NVARCHAR(30),
		@datetomov			NVARCHAR(30),
		@bankacc			int,
		@custsupp			int,
		@curr_id			int,
		@values				INT,
		@chp_isown			INT,
		@chp_isToOrder      INT,
		@bra_id				INT,
		@brag_id			INT,
		@ba_id4custody		int,
		@chp_isElectronic	INT,
		@intBranch4Lang		int
)
AS


BEGIN




--	 Esto va por Parametro, sacarlo luego!
--	DECLARE @brag_id AS INT
--	SET		@brag_id = -1
--	 ---------------------

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------
set nocount on
set dateformat 'ymd'
DECLARE

		@ldatefromdeposit			 DATETIME,
		@ldatetodeposit				 DATETIME,
		@ldatefrommov				 DATETIME,
		@ldatetomov					 DATETIME


-- Incorpora las sucursales de las cuales se tomaran los valores a listar.
	DECLARE @tmpBranch AS TABLE (bra_id INT PRIMARY	KEY)
	INSERT INTO @tmpBranch (bra_id) VALUES (@bra_id)
	INSERT INTO @tmpBranch (bra_id)
		SELECT bra_id
			FROM tbBranchGroupDetail tbgd
		WHERE	tbgd.comp_id = @comp_id AND
				tbgd.brag_id = @brag_id AND
				NOT EXISTS ( SELECT 1
								FROM @tmpBranch tmp
								WHERE tmp.bra_id = tbgd.bra_id)





	set	@ldatefromdeposit	= dbo.fnGetEnd_or_BeginOfDate(@datefromdeposit,'False')
	set	@ldatetodeposit		= dbo.fnGetEnd_or_BeginOfDate(@datetodeposit,'True')

	set	@ldatefrommov		= dbo.fnGetEnd_or_BeginOfDate(@datefrommov,'False')
	set	@ldatetomov			= dbo.fnGetEnd_or_BeginOfDate(@datetomov,'True')



	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-20
	-- Parte		: ref #20100820
	-- Description	: Se modifica por el valor opuesto la variable @chp_isown en el where y se reemplaza el campo
	--				  bt.bt_imputationDate por cp.chp_PayDate	[bt_imputationDate] y ordenando el query por este último campo
	-- =================================================================================================================


	-- ----------------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------------
/*
	Declare
			@comp_id			int,
			@lang_id			int,
			@page_id			int,

			@selection_id		int,
			@datefromdeposit	datetime,
			@datetodeposit		datetime,
			@datefrommov		datetime,
			@datetomov			datetime,
			@bankacc			int,
			@custsupp			int,
			@curr_id			int,
			@bra_id				INT,
			@values				INT,
			@chp_isown			INT,
			@brag_id			INT,
			@chp_isToOrder      INT,
			@ba_id4custody		INT,
			@intBranch4Lang		int

	Select
			@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10014,

			@selection_id		= -1,
			@datefromdeposit	= '1900-01-01',
			@datetodeposit		= '9999-12-31',
			@datefrommov		= '1900-01-01',
			@datetomov			= '9999-12-31',
			@bankacc			= -1,
			@custsupp			= -1,  --24294
			@curr_id			= 1,
			@bra_id				= 1,
			@values				= 3,
			@chp_isown			= -1,
			@chp_isToOrder		= -1,
			@ba_id4custody		=16,
			@brag_id			= -1

*/
	-- ----------------------------------------------------------------------


	DECLARE @bra_Credit_AssumeValuesAcreditDays AS INT
	SET		@bra_Credit_AssumeValuesAcreditDays = 4
	DECLARE @bra_processingDate AS DATETIME
	SELECT  @bra_Credit_AssumeValuesAcreditDays = tb.bra_Credit_AssumeValuesAcreditDays,
			@bra_processingDate					= tb.bra_processingDate
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id
	SET @bra_Credit_AssumeValuesAcreditDays = @bra_Credit_AssumeValuesAcreditDays * -1


	DECLARE @fun_id INT
	SET @fun_id = 1

	Select	--bt.bt_imputationDate,						--ref #20100820
			cp.chp_PayDate	[bt_imputationDate],		--ref #20100820
			cp.chp_number,
			bn.bn_name,
			c.cust_name,
			cp.chp_EmissionDate,
			cp.chp_total,
			cr.curr_desc,
			ba.ba_desc,
			br.bra_desc,
			ct.ct_ACurrencyExchange,
			ov.optval_desc				[DESC],
			bt.btt_id,
			c.cust_id,
			cp.chp_isOwn,
			cp.chp_isToOrder,
			ct.ct_date,
			ba2.ba_desc					[ba_desc4Custody],
			cp.chp_taxNumber1


	From	dbo.tbCheckPortfolio						cp			WITH (NOLOCK)

			left join dbo.tbBankingTransactions			bt			WITH (NOLOCK)
			on	bt.comp_id			= cp.comp_id
			and	bt.bra_id			= cp.bra_id
			and	bt.chp_id			= cp.chp_id
			and bt.btt_id			= 1000020
			AND bt.bt_isCancelled   = 'False'

			left join dbo.tbBanksName					bn			WITH (NOLOCK)
			on	cp.comp_id			= bn.comp_id
			and cp.country_id		= bn.country_id
			and cp.bn_id			= bn.bn_id

			left join dbo.tbCommercialTransactions		ct			WITH (NOLOCK)
			on	cp.comp_id			= ct.comp_id
			and cp.bra_id			= ct.bra_id
			and cp.ct_transaction	= ct.ct_transaction

			left join dbo.tbCustomer					c			WITH (NOLOCK)
			on  ct.comp_id			= c.comp_id
			and c.cust_id			= ct.cust_id

			left join dbo.tbsysCurrency					cr			WITH (NOLOCK)
			on cp.curr_id			= cr.curr_id

			left join dbo.tbBankingAccounts				ba			WITH (NOLOCK)
			on  bt.comp_id			= ba.comp_id
			and bt.ba_id			= ba.ba_id

			left join dbo.tbBankingAccounts				ba2			WITH (NOLOCK)
			on  cp.comp_id			= ba2.comp_id
			and cp.ba_id			= ba2.ba_id

			left join dbo.tbBranch						br			WITH (NOLOCK)
			on  cp.comp_id			= br.comp_id
			and cp.bra_id			= br.bra_id

			inner join dbo.tbsysOptionsValues			ov			WITH (NOLOCK)
			on  ov.optval_class		= 13
			and ov.lang_id			= @lang_id
			and ov.optval_id		= cp.chp_isOwn

			-- Se filtra x la sucursal correcta.
			INNER JOIN @tmpBranch tmpb
				ON tmpb.bra_id = cp.bra_id_PortFolio

	Where	cp.comp_id				= @comp_id


	--	AND		cp.bra_id_PortFolio		= @bra_id	MOS 08-2013
	--	AND		cp.bra_id				= @bra_id   MOS  2-2013

	AND		ct.ct_date				between @ldatefrommov and @ldatetomov
	AND		cp.curr_id				= @curr_id
	AND     (@chp_isown				= -1 OR		CP.chp_isOwn		= ~convert(bit,@chp_isown))	--ref #20100820
	AND     (@chp_isToOrder			= -1 OR		CP.chp_isToOrder	= ~convert(bit,@chp_isToOrder))
	AND		(@bankacc				= -1 or		ba.ba_id			= @bankacc)
	AND		(@custsupp				= -1 or		ct.cust_id			= @custsupp)
	AND		(@selection_id			= -1 or 	cp.chp_isDocument	= @selection_id)
	AND		(@ba_id4custody			= -1 OR		@ba_id4custody			= -2 and cp.ba_id is null OR cp.ba_id			= @ba_id4custody)
	AND		cp.chp_PayDate BETWEEN @ldatefromdeposit and @ldatetodeposit	AND
			(
				@chp_isElectronic	= -1 OR
				cp.chp_isElectronic = @chp_isElectronic
			)


	AND			CASE @values
					WHEN 0 THEN
								CASE
									when cp.chp_isAvailable = 'True'  THEN 'True'
									ELSE 'False'
								END
					WHEN 1 THEN
								CASE
									WHEN		cp.chp_isAvailable = 'False'
											AND cp.chp_IsPayed     = 'True'
											AND EXISTS (	SELECT 1
					            								FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
					            								WHERE	tcpm.comp_id		= cp.comp_id
					            									AND tcpm.chp_id			= cp.chp_id
					            									AND tcpm.svtt_id		= 30			-- Entrega de Valores a Proveedores
					            									AND tcpm.mm_isCancelled	= 'False')		THEN	'True'
									ELSE																			'False'
								END
					WHEN 2 THEN
								CASE
									WHEN		cp.chp_isAvailable	= 'False'
											AND cp.chp_IsPayed		= 'False'
											AND EXISTS (	SELECT 1
					            								FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
					            								WHERE	tcpm.comp_id		= cp.comp_id
					            									AND tcpm.chp_id			= cp.chp_id
					            									AND tcpm.svtt_id		= 40			-- Deposito de Valores
					            									AND tcpm.mm_isCancelled	= 'False')		THEN	'True'
					            	ELSE																			'False'
								END
					WHEN 3 THEN
								CASE
									WHEN		cp.chp_isAvailable	= 'False'
											AND cp.chp_IsPayed		= 'True'
											AND EXISTS (	SELECT 1
					            								FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
					            								WHERE	tcpm.comp_id		= cp.comp_id
					            									AND tcpm.chp_id			= cp.chp_id
					            									AND tcpm.svtt_id		= 40			-- Deposito de Valores
					            									AND tcpm.mm_isCancelled	= 'False')		THEN	'True'
									ELSE																			'False'
								END
					WHEN 4																					THEN	'True'
					WHEN 5 THEN
								CASE
									WHEN	cp.chp_isRejected  = 'False'	AND
											cp.chp_isCancelled = 'False'	AND
										   (DATEDIFF(DAY,@bra_processingDate,cp.chp_PayDate) >= @bra_Credit_AssumeValuesAcreditDays)
																											THEN	'True'
									ELSE																			'False'
								END
					WHEN 6 THEN  -- Negociados
								CASE
									WHEN		cp.chp_isAvailable	= 'False'
											AND cp.chp_IsPayed		= 'True'
											AND cp.chp_isNegociated = 'True'
											AND EXISTS (	SELECT 1
					            								FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
					            								WHERE	tcpm.comp_id		= cp.comp_id
					            									AND tcpm.chp_id			= cp.chp_id
					            									AND tcpm.svtt_id		= 40			-- Deposito de Valores
					            									AND tcpm.mm_isCancelled	= 'False')		THEN	'True'
					            	ELSE																			'False'
								END
					ELSE																							'False'
				END	= 'True'



				-- Se reemplazo por los CASE de arriba.-
				--AND
				--(
				--(@values = 4	)								OR
				--(@values = 0	AND cp.chp_isAvailable = 'True')								OR
				--(@values = 1	-- Entregados a Proveedores
				--	AND cp.chp_isAvailable = 'False'
				--	AND cp.chp_IsPayed     = 'True'
				--	AND EXISTS (	SELECT 1
				--	            		FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
				--	            		WHERE	tcpm.comp_id		= cp.comp_id
				--	            			AND tcpm.chp_id			= cp.chp_id
				--	            			AND tcpm.svtt_id		= 30			-- Entrega de Valores a Proveedores
				--	            			AND tcpm.mm_isCancelled	= 'False')
				--)
				--																				OR
				--(@values = 2
				--	AND cp.chp_isAvailable	= 'False'
				--	AND cp.chp_IsPayed		= 'False'
				--	AND EXISTS (	SELECT 1
				--	            		FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
				--	            		WHERE	tcpm.comp_id		= cp.comp_id
				--	            			AND tcpm.chp_id			= cp.chp_id
				--	            			AND tcpm.svtt_id		= 40			-- Deposito de Valores
				--	            			AND tcpm.mm_isCancelled	= 'False')

				--)																				OR
				--(@values = 3
				--	AND cp.chp_isAvailable	= 'False'
				--	AND cp.chp_IsPayed		= 'True'
				--	AND EXISTS (	SELECT 1
				--	            		FROM tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
				--	            		WHERE	tcpm.comp_id		= cp.comp_id
				--	            			AND tcpm.chp_id			= cp.chp_id
				--	            			AND tcpm.svtt_id		= 40			-- Deposito de Valores
				--	            			AND tcpm.mm_isCancelled	= 'False')

				--)

				--)


			--@values = 0	Valores en Cartera
			--@values = 1	Valores Egresados
			--@values = 2	Valores Depositados
			--@values = 3	Valores Depositados	y Acreditados


	order by	--bt.bt_imputationDate,		--ref #20100820
				cp.chp_PayDate,				--ref #20100820
				c.cust_name




	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id




	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/************************************************************************************************************ */
	Select
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 398
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params1],
			CASE @selection_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				Else
						(Select tcp1.chp_number
						FROM	tbCheckPortfolio tcp1
	--					inner join dbo.tbsysOptionsValues			ov
	--					on  ov.optval_class		= 13
	--					and ov.lang_id			= @lang_id
						--and ov.optval_id		= tcp1.chp_isOwn

						 WHERE	tcp1.comp_id= @comp_id AND
						tcp1.chp_id = @selection_id
						)
			END		[params2],


	--					FROM	tbCheckPortfolio tcp1
	--					WHERE	tcp1.comp_id= @comp_id AND
	--					tcp1.chp_id = @selection_id)

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 411
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params3],

      		 @datefromdeposit[DateParams1],
			--convert(varchar,day(@datefromdeposit)) + '/' + convert(varchar,month(@datefromdeposit)) + '/' + convert(varchar,year(@datefromdeposit)) 	[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 412
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],

      		 @datetodeposit [DateParams2],
			--convert(varchar,day(@datetodeposit)) + '/' + convert(varchar,month(@datetodeposit)) + '/' + convert(varchar,year(@datetodeposit))		[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 413
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params7],

      		 @datefrommov [DateParams3],
			--convert(varchar,day(@datefrommov)) + '/' + convert(varchar,month(@datefrommov)) + '/' + convert(varchar,year(@datefrommov)) 	[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 414
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params9],

      		 @datetomov [DateParams4],
			--convert(varchar,day(@datetomov)) + '/' + convert(varchar,month(@datetomov)) + '/' + convert(varchar,year(@datetomov))		[params10],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 402
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params11],
			CASE @custsupp WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cust_name
						FROM	tbCustomer tc
						WHERE	Tc.comp_id= @comp_id AND tc.cust_id = @custsupp)
			END		[params12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 406
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params13],
			CASE @bankacc WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tba.ba_desc
						FROM	tbBankingAccounts tba
						WHERE	tba.comp_id= @comp_id AND tba.ba_id = @bankacc)
			END		[params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 406
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params15],
			CASE @curr_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.curr_desc
						FROM	tbsysCurrency tc
						WHERE	tc.curr_id = @curr_id)
			END		[params16],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 300
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params17],
			(SELECT tov.optval_desc
			 FROM tbsysOptionsValues tov
			 WHERE tov.lang_id = @lang_id
			 AND tov.optval_class = 82
			 AND tov.optval_id = @values) [params18],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 753
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params19],

		 		CASE @chp_isown WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
		 		(SELECT tov.optval_desc
			 FROM tbsysOptionsValues tov
			 WHERE tov.lang_id = @lang_id
			 AND tov.optval_class = 83
			 AND tov.optval_id = @chp_isown) END [params20],

			  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1176
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params21],
		 		CASE @chp_isown WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
		 		(SELECT tov.optval_desc
			 FROM tbsysOptionsValues tov
			 WHERE tov.lang_id = @lang_id
			 AND tov.optval_class = 1
			 AND tov.optval_id = @chp_isown) END [params22],


			  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 639
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params23],
		 		CASE @brag_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
		 		(SELECT tbg.brag_desc
		 		 FROM tbBranchGroup tbg
			 WHERE tbg.comp_id = @comp_id
			 AND tbg.brag_id = @brag_id) END [params24],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2513
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params25],
		 		CASE @ba_id4custody WHEN -2 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 32
					)
					WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 31
					)

				ELSE
		 		(SELECT tba.ba_desc
		 		 FROM tbBankingAccounts tba
				 WHERE tba.comp_id = @comp_id
				 AND tba.ba_id = @ba_id4custody) END [params26]









END
GO







CREATE PROCEDURE [dbo].[spCities_getDataById]
(
	@city_id		int
)
AS

BEGIN

	SET NOCOUNT ON

	SELECT	vc.country_id,
			vc.state_id,
			vc.city_id,
			vc.city_desc,
			vc.city_zip,
			vc.city_auxId,
			IsNull(vc.city_isAvailable4StreetSuggest,'False')		[city_isAvailable4StreetSuggest],
			IsNull(vc.city_isAvailable4StreetNumberCheck,'False')	[city_isAvailable4StreetNumberCheck]
		FROM tbCities vc			WITH (NOLOCK)
		WHERE vc.city_id = @city_id



END
GO



