CREATE PROCEDURE [dbo].[spCities_getDataByText]
(
	@comp_id		INT,
	@bra_id			INT,
	@text			VARCHAR(300),
	@count			INT,
	@lang_id		INT,
	@country_id		INT,
	@state_id		INT

)
AS


BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -----------------------------------------
	--
	-- -----------------------------------------
	/*
	DECLARE
			@comp_id		INT,
			@bra_id			INT,
			@text			VARCHAR(300),
			@count			INT,
			@lang_id		INT,
			@country_id		INT,
			@state_id		INT

	SELECT
			@comp_id		= 1,
			@bra_id			= 1,
			@text			= '1650',
			@count			= 10,
			@lang_id		= 2,
			@country_id		= 54,
			@state_id		= 54020
	*/
	-- -----------------------------------------

	DECLARE @bra_city_disableSysCities	AS BIT = 'False'
	DECLARE @bra_city_disableCities		AS BIT = 'False'

	SELECT		@bra_city_disableSysCities	= ISNULL(tb.bra_city_disableSysCities,0),
				@bra_city_disableCities		= ISNULL(tb.bra_city_disableCities,0)
	  FROM tbBranch tb	WITH (NOLOCK)
	  WHERE tb.comp_id	= @comp_id	AND
			tb.bra_id	= @bra_id



--SELECT '@bra_city_disableSysCities',@bra_city_disableSysCities
--SELECT '@bra_city_disableCities',@bra_city_disableCities

	IF @bra_city_disableSysCities = 'True'
		BEGIN

			-- ATENCION.!!!
			-- Si se modifica el separador de Codigo POstal ver en Codigo Postal **ergre876
			SELECT	TOP (@count)
					Replace(ISNULL(vc.city_desc_collated,''),'|','') + ' | (' + IsNull(vc.city_zip_collated,'----') + ')' /*+ ' | ' + isnull(convert(varchar,tc.city_id),'')*/ [city_desc],
					vc.city_id

				FROM	vwCities vc	WITH (NOLOCK)
				WHERE	vc.country_id	=		@country_id
				AND		vc.state_id		=		@state_id
				AND		( vc.city_desc_collated	 LIKE	 '%' + @text + '%' OR
						  vc.city_zip_collated   LIKE    '%' + @text + '%'
						)
				AND		(vc.comp_id = @comp_id OR vc.comp_id = -1)
				AND
				vc.city_Order = 0   -- sin nada de tbSysCities	( SOLO ingresadas x el Usuario )
			ORDER BY vc.city_Order, vc.city_desc

			---- ATENCION.!!!
			---- Si se modifica el separador de Codigo POstal ver en Codigo Postal **ergre876
			--SELECT	TOP (@count)

			--		Replace(ISNULL(vc.city_desc_collated,''),'|','') + ' | (' + IsNull(vc.city_zip_collated,'----') + ')' /*+ ' | ' + isnull(convert(varchar,tc.city_id),'')*/ [city_desc],
			--		vc.city_id

			--	FROM	vwCities vc	WITH (NOLOCK)
			--	WHERE	vc.comp_id		=		@comp_id
			--	AND 	vc.country_id	=		@country_id
			--	AND		vc.state_id		=		@state_id
			--	AND		( vc.city_desc_collated	 LIKE '%' + @text + '%' OR
			--			  vc.city_zip_collated   LIKE '%' + @text + '%'
			--	)	AND
			--	vc.city_Order = 0   -- sin nada de tbSysCities
			--ORDER BY vc.city_desc

		END

	ELSE IF @bra_city_disableCities = 'True'
		BEGIN

			-- ATENCION.!!!
			-- Si se modifica el separador de Codigo POstal ver en Codigo Postal **ergre876
			SELECT	TOP (@count)
					Replace(ISNULL(vc.city_desc_collated,''),'|','') + ' | (' + IsNull(vc.city_zip_collated,'----') + ')' /*+ ' | ' + isnull(convert(varchar,tc.city_id),'')*/ [city_desc],
					vc.city_id

				FROM	vwCities vc	WITH (NOLOCK)
				WHERE	vc.country_id	=		@country_id
				AND		vc.state_id		=		@state_id
				AND		( vc.city_desc_collated	 LIKE	 '%' + @text + '%' OR
						  vc.city_zip_collated   LIKE    '%' + @text + '%'
						)
				AND		(vc.comp_id = @comp_id OR vc.comp_id = -1)
				AND
				vc.city_Order = 1   -- sin nada de tbCities	( Solo las de tbsysCities )
			ORDER BY vc.city_Order, vc.city_desc

		END
	ELSE
		BEGIN

			SELECT	TOP (@count)
					Replace(ISNULL(vc.city_desc_collated,''),'|','') + ' | (' + IsNull(vc.city_zip_collated,'----') + ')' /*+ ' | ' + isnull(convert(varchar,tc.city_id),'')*/ [city_desc],
					vc.city_id

				FROM	vwCities vc	WITH (NOLOCK)
				WHERE	vc.country_id	=		@country_id
				AND		vc.state_id		=		@state_id
				AND		( vc.city_desc_collated	 LIKE	 '%' + @text + '%' OR
						  vc.city_zip_collated   LIKE    '%' + @text + '%'
						)
				AND		(vc.comp_id = @comp_id OR vc.comp_id = -1)
			ORDER BY vc.city_Order, vc.city_desc

		END

END
GO







CREATE PROCEDURE [dbo].[spCities_getIdByDesc]
(
	@comp_id		INT,
	@bra_id			INT,
	@country_id		int,
	@state_id       INT,
	@desc			NVARCHAR(4000)
)
AS

BEGIN

	SET NOCOUNT ON

	/*


	DECLARE		@country_id		int,
				@state_id       INT,
				@desc			NVARCHAR(4000)

	SELECT		@country_id		=226,
				@state_id       =226001,
				@desc			='m'
	*/

	-- Saco posibles intrusiones del Codigo Postal **ergre876
	IF CHARINDEX(' | (',@desc) > 0
		BEGIN
			SET @desc =  dbo.fnSplitPosition(@desc,' | (',1)
		END


	IF EXISTS (SELECT TOP 1  1
				   FROM vwCities vc		WITH (NOLOCK)
				   WHERE LTRIM(RTRIM(vc.city_desc_collated )) = LTRIM(RTRIM(@desc))
					AND vc.country_id				= @country_id
					AND vc.state_id					= @state_id
					AND (vc.comp_id					= @comp_id OR vc.comp_id = -1)
				)

		BEGIN

			SELECT	top 1 vc.city_id		[ID]
				FROM	vwCities vc			WITH (NOLOCK)
				WHERE	LTRIM(RTRIM(vc.city_desc_collated)) = LTRIM(RTRIM(@desc))
				AND		vc.country_id	= @country_id
				AND		vc.state_id		= @state_id
				AND    (vc.comp_id      = @comp_id OR vc.comp_id = -1)
			ORDER BY vc.city_Order

		END

	ELSE

		BEGIN

			DECLARE @id AS INT

			IF ltrim(rtrim(@desc)) = ''
				BEGIN
					SET @id = -1
				END
			ELSE
				BEGIN

					IF EXISTS( SELECT 1
								  FROM tbBranch tb	WITH (NOLOCK)
								  WHERE tb.comp_id	= @comp_id	AND
										tb.bra_id	= @bra_id	AND
										IsNull(tb.bra_city_disableCitiesInsert,'False') = 'False') OR @bra_id = -10

						BEGIN


							INSERT INTO tbCities
							(
								comp_id,
								country_id,
								state_id,
								city_desc
							)
							VALUES
							(
								@comp_id,
								@country_id,
								@state_id,
								@desc
							)

							SET		@id = @@IDENTITY

						END

				END

			SELECT	@id

		END


END
GO





CREATE PROCEDURE [dbo].[spCitiesStreets_getDataByText]
(
	@text	VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id	AS INT,
	@bra_id		AS INT,
	@country_id	AS INT,
	@state_id	AS INT,
	@city_id	AS INT
)
AS

BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*

		DECLARE
			@text		VARCHAR(300),
			@count		INT,
			@lang_id	INT,
			@comp_id AS INT,
			@bra_id  AS INT

		SELECT
			@text		='A',
			@count		= 2,
			@lang_id	= 2,
			@comp_id	= 1,
			@bra_id		= 1
	*/
	-- ----------------------------------------------------------------


	SELECT	TOP (@count)
			(dbo.fnStrPADR ( Replace(ISNULL(tcs.street_desc,''),'|','') ,100,'.'))  + ' | ' + CONVERT(NVARCHAR(10),tcs.street_id)  [city_desc],
			tcs.street_id	[city_id]

		FROM tbCities_Streets tcs
		WHERE	tcs.comp_id			= @comp_id			AND
				tcs.country_id		= @country_id		AND
				tcs.state_id		= @state_id			AND
				tcs.street_desc LIKE '%' + @text + '%'	AND
			   (tcs.city_id         = @city_id OR @city_id = -1)

END
GO







CREATE PROCEDURE [dbo].[spCollection_checkBasicData]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			INT,
	@user_id			INT
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	SET NOCOUNT ON

	/*

	DECLARE @comp_id		INT
	DECLARE @bra_id			INT
	DECLARE @lang_id		INT
	DECLARE @user_id		INT
	SELECT	@comp_id		=1,
			@bra_id			=1,
			@lang_id		=2,
			@user_id		=8
	DROP TABLE #tmpData
	*/


	CREATE TABLE #tmpData ( [check] INT )

	/*
	por cada control que se realice al comienzo de las páginas y no esté correcto,
	hay que hacer un insert en la temporal creada arriba
	con el valor correspondiente al table_id de la tabla tbSysTables (siempre deberá ser un valor negativo)
	y este valor está relacionado con la tabla tbSysHelpPages que si tendrá el mensaje de error
	a mostrar al usuario
	*/


	if not exists (select 1 from tbSalesman					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-1)
	if not exists (select 1 from tbSalesTerms				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-2)
	if not exists (select 1 from tbDelivery					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-3)
	if not exists (select 1 from tbDiscount					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-4)
	if not exists (select 1 from tbPriceList				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-5)
	if not exists (select 1 from tbCustomer					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-6)
	IF NOT EXISTS (SELECT 1 FROM tbDocumentsFile df
							inner join dbo.[tbsysDocuments]	sd on sd.[sd_id] = df.[sd_id]
				   where df.comp_id	= @comp_id and df.bra_id = @bra_id
				   and sd.[sd_isReceipt] = 'True' and sd.[sd_isPurchase] = 'False')	  INSERT INTO #tmpData ([check]) VALUES (-7)
	if not exists (select 1 from tbCashNumbers				WHERE comp_id = @comp_id and bra_id = @bra_id )
															INSERT INTO #tmpData ([check]) VALUES (-8)
	if not exists (select 1 from tbCurrencyExchange			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-9)
	if not exists (select 1 from tbCashNumber4Branch4User
				   WHERE comp_id = @comp_id AND bra_id = @bra_id AND [user_id] = @user_id) INSERT INTO #tmpData ([check]) VALUES (-10)
	if not exists (select 1 from tbCashAccountant			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-11)
	--if not exists (select 1 from tbCreditCard				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-12)
	if not exists (select 1 FROM tbBankingAccounts			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-13)
	if not exists (select 1 FROM tbTaxName					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-14)
	IF NOT EXISTS (SELECT 1 FROM tbCurrencyExchange tce
				   WHERE	tce.comp_id = @comp_id
				   AND		tce.curr_id_1 = (	SELECT	tc.curr_id
												FROM	tbCompany tc
												WHERE	tc.comp_id	= @comp_id)
				   AND		tce.curr_id_2 = (	SELECT	curr_id
												FROM	tbBranch tb
												WHERE	tb.comp_id	= @comp_id
												AND		tb.bra_id	= @bra_id))
	AND
	   NOT EXISTS (SELECT 1 FROM tbCurrencyExchange tce
				   WHERE	tce.comp_id = @comp_id
				   AND		tce.curr_id_2 = (	SELECT	tc.curr_id
												FROM	tbCompany tc
												WHERE	tc.comp_id	= @comp_id)
				   AND		tce.curr_id_1 = (	SELECT	curr_id
												FROM	tbBranch tb
												WHERE	tb.comp_id	= @comp_id
												AND		tb.bra_id	= @bra_id))		INSERT INTO #tmpData ([check]) VALUES (-16)

	if not exists (select 1 from tbBranchGroupDetail		WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-17)


	SELECT	tut.utexts_desc, tut.utexts_id
	FROM	tbsysUniqueTexts tut
	WHERE	tut.lang_id			= @lang_id
	AND		tut.utexts_id		IN(4, 5, 6)
	AND		EXISTS(SELECT 1 FROM #tmpData)

	UNION

	SELECT	cast(thp.hp_desc AS NVARCHAR(MAX)), thp.page_id
	FROM	tbsysHelpPages			thp
			INNER JOIN #tmpData		td
			ON	td.[check]		= thp.table_id
	WHERE	thp.page_id			= -100010 --este valor está en duro e indica la funcionalidad que se está chequeando
	AND		thp.lang_id			= @lang_id

	ORDER BY 2 DESC



END
GO


CREATE PROCEDURE spCollection_CheckBlockedMethods
(
	@comp_id	INT,
	@lang_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@guid		UNIQUEIDENTIFIER
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@guid		= 'BEAC69EF-B943-495D-8765-452EAC6AFF3D'
		*/
		-- -----------------------------------------------------------------




		-- ---------------------------------------------
		-- VARIABLES DE TRABAJO
		-- ---------------------------------------------
			DECLARE
				@blockInCash		BIT,
				@blockInCheque		BIT,
				@blockInDocuments	BIT,
				@blockInCreditCard	BIT,
				@blockInTransfer	BIT,
				@ErrorMessage		VARCHAR(1000),
				@ErrorTitle			VARCHAR(200),
				@CashMessage		VARCHAR(50),
				@ChequeMessage		VARCHAR(50),
				@DocumentsMessage	VARCHAR(50),
				@CreditCardMessage	VARCHAR(50),
				@TransferMessage	VARCHAR(50)

			SET @blockInCash		= 'False'
			SET @blockInCheque		= 'False'
			SET @blockInDocuments	= 'False'
			SET @blockInCreditCard	= 'False'
			SET @blockInTransfer	= 'False'
			SET @ErrorMessage		= ''
			SET @ErrorTitle			= ''
			SET @CashMessage		= ''
			SET @ChequeMessage		= ''
			SET @DocumentsMessage	= ''
			SET @CreditCardMessage	= ''
			SET @TransferMessage	= ''
		-- ---------------------------------------------

		-- ---------------------------------------------------------------------------------------------------------------------
		-- SETEAMOS LOS VALORES DE LAS VARIABLES PARA SABER QUE BLOQUEOS ESTAN ACTIVOS (TRUE) Y SE CONSIDERARAN PARA CONFORMAR
		-- EL MENSAJE DE ERROR
		-- ---------------------------------------------------------------------------------------------------------------------

			SELECT
				DISTINCT
					@blockInCash		=	CASE
												tst.st_blockCollectionInCASH WHEN 'True' THEN tst.st_blockCollectionInCASH
											END,
					@blockInCheque		=	CASE
												tst.st_blockCollectionInCHEQUE WHEN 'True' THEN tst.st_blockCollectionInCHEQUE
											END,
					@blockInDocuments	=	CASE
												tst.st_blockCollectionInDOCUMENTS WHEN 'True' THEN tst.st_blockCollectionInDOCUMENTS
											END,
					@blockInCreditCard	=	CASE
												tst.st_blockCollectionInCreditCard WHEN 'True' THEN tst.st_blockCollectionInCreditCard
											END,
					@blockInTransfer	=	CASE
												tst.st_blockCollectionInTransfer WHEN 'True' THEN tst.st_blockCollectionInTransfer
											END

			FROM tbCommercialTransactionsTmp							tctt	WITH(NOLOCK)
				INNER JOIN tbCommercialTransactions						tct		WITH(NOLOCK)
					ON	tctt.comp_id			= tct.comp_id			AND
						tctt.ctct_transaction	= tct.ct_transaction
				INNER JOIN tbSalesTerms									tst		WITH(NOLOCK)
					ON	tst.comp_id				= tct.comp_id			AND
						tst.st_id				= tct.st_id
			WHERE	tctt.comp_id				= @comp_id				AND
					tctt.ctct_guid				= @guid					AND
					(
						tst.st_blockCollectionInCASH		= 'True'	OR
						tst.st_blockCollectionInCHEQUE		= 'True'	OR
						tst.st_blockCollectionInDOCUMENTS	= 'True'	OR
						tst.st_blockCollectionInCreditCard	= 'True'	OR
						tst.st_blockCollectionInTransfer	= 'True'
					)

		-- ---------------------------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------
		-- CARGAMOS LAS VARIABLES CON LOS TEXTOS PARA EL MENSAJE DE ERROR EN CASO DE HABERLO
		-- -----------------------------------------------------------------------------------

			--Alguno de los Comprobantes no permite la carga de Cobranzas a realizarse en : <br>
			SELECT
				@ErrorTitle = tut.utexts_desc
			FROM tbsysUniqueTexts				tut	WITH(NOLOCK)
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30846

			--Efectivo <br>
			SELECT
				@CashMessage = tut.utexts_desc
			FROM tbsysUniqueTexts				tut	WITH(NOLOCK)
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30847

			--Cheques <br>
			SELECT
				@ChequeMessage = tut.utexts_desc
			FROM tbsysUniqueTexts				tut	WITH(NOLOCK)
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30848


			--Documentos <br>
			SELECT
				@DocumentsMessage = tut.utexts_desc
			FROM tbsysUniqueTexts				tut	WITH(NOLOCK)
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30849

			--Tarjetas de Crédito <br>
			SELECT
				@CreditCardMessage = tut.utexts_desc
			FROM tbsysUniqueTexts				tut	WITH(NOLOCK)
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30850

			--Transferencias <br>
			SELECT
				@TransferMessage = tut.utexts_desc
			FROM tbsysUniqueTexts				tut	WITH(NOLOCK)
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30851

		-- -----------------------------------------------------------------------------------





		-- -----------------------------------------------------------------------------
		-- SI HAY COBRANZA EN EFECTIVO
		-- -----------------------------------------------------------------------------
			IF (@blockInCash = 'True') AND EXISTS(SELECT
														1
													  FROM tbCashMovementsTmp			tcmt	WITH(NOLOCK)
													  WHERE tcmt.comp_id	= @comp_id	AND
															tcmt.cmt_guid	= @guid)
				BEGIN
					SET @ErrorMessage = @CashMessage
				END
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- SI HAY COBRANZA CON CHEQUES
		-- -----------------------------------------------------------------------------
			IF (@blockInCheque = 'True') AND EXISTS(SELECT
														1
													FROM tbCheckPortfolioTmp					tcpt	WITH(NOLOCK)
													WHERE	tcpt.comp_id			= @comp_id	AND
															tcpt.chpt_guid			= @guid		AND
															tcpt.chpt_isDocument	= 'False')

				BEGIN
					SET @ErrorMessage = @ErrorMessage + @ChequeMessage
				END
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- SI HAY COBRANZA CON DOCUMENTOS
		-- -----------------------------------------------------------------------------
			IF (@blockInDocuments = 'True') AND EXISTS(SELECT
														1
														FROM tbCheckPortfolioTmp					tcpt	WITH(NOLOCK)
														WHERE	tcpt.comp_id			= @comp_id	AND
																tcpt.chpt_guid			= @guid		AND
																tcpt.chpt_isDocument	= 'True')
				BEGIN
					SET @ErrorMessage = @ErrorMessage + @DocumentsMessage
				END
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- SI HAY COBRANZA CON TARJETAS DE CRÉDITO
		-- -----------------------------------------------------------------------------
			IF (@blockInCreditCard = 'True') AND EXISTS(SELECT
														1
														FROM tbCreditCardMovementsTmp		tccmt	WITH(NOLOCK)
														WHERE	tccmt.comp_id	= @comp_id	AND
																tccmt.ccmt_guid = @guid)
				BEGIN
					SET @ErrorMessage = @ErrorMessage + @CreditCardMessage
				END
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- SI HAY COBRANZA CON TRANSFERENCIAS
		-- -----------------------------------------------------------------------------
			IF (@blockInTransfer = 'True') AND EXISTS(SELECT
														1
													  FROM tbBankingTransactionsTmp		tbtt	WITH(NOLOCK)
													  WHERE tbtt.comp_id	= @comp_id	AND
															tbtt.btt_guid	= @guid)
				BEGIN
					SET @ErrorMessage = @ErrorMessage + @TransferMessage
				END
		-- -----------------------------------------------------------------------------


		IF @ErrorMessage = ''
			BEGIN
				--SI EL MENSAJE DE ERROR ES '' SIGNIFICA QUE NO HAY BLOQUEOS, ENTONCES DEVOLVEMOS EL MENSAJE VACÍO
				SELECT
					@ErrorMessage	[ErrorMessage]
			END

		ELSE
			BEGIN
				--SINO, SIGNIFICA QUE EL MENSAJE TIENE AL MENOS UN BLOQUEO Y LE AGREGO EL ENCABEZADO DEL MENSAJE DE ERROR
				SET @ErrorMessage = @ErrorTitle + @ErrorMessage
				SELECT
					@ErrorMessage [ErrorMessage]
			END




	END
GO







CREATE PROCEDURE [dbo].[spCollection_getDataById]
(
	@comp_id				int,
	@lang_id				int,
	@ct_transaction			int
)
AS



BEGIN



	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2010-12-09
	-- Parte		: 723
	-- Description	: Se agrega la opción para cheques de terceros
	-- =================================================================================================================



	-- ---------------------------------------------
	-- Testing
	-- ---------------------------------------------
	/*
	declare		@comp_id				int,
				@lang_id				int,
				@ct_transaction			int
	select		@comp_id				=1,
				@lang_id				=2,
				@ct_transaction			=28220515
	*/
	-- ---------------------------------------------


	SELECT distinct	vct.description										[type],
			case vct.class
				when '1'	then vct.[type]
				when '2'	then vct.[type]
				when '3'	then vct.[type]
				when '4'	then vct.[type]
				when '5'	then vct.[type]
				when '7'	then vct.[type]
				when '100'	then vct.[type]
				when '10'	then vct.[type]		-- Parte		: 723
			end		+
			CASE
				WHEN ttm.tm_isManualTax = 'True' THEN	' (Manual)'
				ELSE							''
			END
			[obs],
			vct.curr_symbol,
			convert(decimal(18,2),isnull(vct.amount,0) *
									CASE WHEN ct.sd_id in(6,13) AND vct.chp_isRejected = 'true'
											THEN -1
											ELSE 1
									END
													)			[amount],
			vct.[desc]											[detail],
			vct.Date											[Date],
			convert(decimal(18,2),ISNULL(SUM(ttm.tm_total),0))	[tax]	,


			tc.curr_symbol										[Acurr_symbol],

			convert(decimal(18,2),ISNULL(dbo.fnGetExchange2(@comp_id,vct.amount,
													vct.curr_id, ct.curr_id_transaction,  vct.curr_id,  ct.curr_id_transaction,
													vct.[CurrencyExchange],'false'),0)  *
									CASE WHEN ct.sd_id in(6,13) AND vct.chp_isRejected = 'true'
											THEN -1
											ELSE 1
									END )						[AAmount],
									tb2.bra_desc				[OriginalBranch],
									tb.bra_desc					[ActualBranch],
									tccm.ccm_receiptNumber,
									tccm.ccm_customerName,
									tccm.ccm_lote,
									tcp1.chp_isToOrder,
									tcp1.chp_isOwn,
									tcp1.chp_isAvailable		[chp_isAvailable],
									tcp1.chp_IsPayed			[chp_IsPayed],
									tcp1.chp_isRejected			[chp_isRejected],
									tcp1.chp_isCancelled		[chp_isCancelled],
									ttm.tm_subtotal,	--MOS 09-2022: x los FORROS de CM que tienen un MONO haciendo pagos.  Si mnolestase en algun lugar sacar esto y el group by de abajo
									ttm.percentaje,		--MOS 09-2022: x los FORROS de CM que tienen un MONO haciendo pagos.  Solo se usa para que en ver valores de un pago puedan ver la base imponible de cada impuesto calculado y su %
									tcp1.chp_id					[Id]




	from	vwCollection								vct		WITH (NOLOCK)

			inner join dbo.[tbCommercialTransactions]	ct		WITH (NOLOCK)
			on	ct.[comp_id]		=	vct.comp_id
			and ct.[bra_id]			=	vct.bra_id
			and ct.[ct_transaction] =	vct.ct_transaction

			LEFT JOIN tbTaxMovements					ttm		WITH (NOLOCK)
			ON	ttm.comp_id			=	vct.comp_id
			AND ttm.bra_id			=	vct.bra_id
			AND ttm.ct_transaction	=	vct.ct_transaction
			AND ttm.tm_transaction	=   vct.tm_transaction

			LEFT JOIN tbsysCurrency						tc		WITH (NOLOCK)
			ON tc.curr_id			=	ct.curr_id_transaction

			LEFT JOIN tbCheckPortfolio tcp1						WITH (NOLOCK)
				ON	tcp1.comp_id	= vct.comp_id AND
					tcp1.chp_id		= vct.ID

			LEFT JOIN tbBranch tb								WITH (NOLOCK)
				ON	tb.comp_id		= vct.comp_id AND
					tb.bra_id		= vct.bra_id_PortFolio

			LEFT JOIN tbBranch tb2								WITH (NOLOCK)
				ON	tb2.comp_id		= vct.comp_id AND
					tb2.bra_id		= vct.bra_id

			-- MOS 07-2023 x Recibo de MP, para saber quien cuernos pago y con q numero de operacion de MP
			LEFT JOIN tbCreditCardMovements AS tccm				WITH (NOLOCK)
				ON	tccm.comp_id		= vct.comp_id			AND
					tccm.ct_transaction = vct.ct_transaction	AND
					tccm.ccm_id			= vct.ccm_id

	where	vct.comp_id				=	@comp_id
	and		vct.lang_id				=	@lang_id
	and		vct.ct_transaction		=	@ct_transaction


	GROUP BY	vct.description,
				vct.class, vct.[type],
				vct.curr_symbol,
				vct.amount,
				vct.[desc],
				vct.Date,
				ct.curr_id_transaction,
				tc.curr_symbol,
				vct.curr_id,
				vct.[CurrencyExchange],
				ct.sd_id,
				vct.chp_isRejected,
				tcp1.chp_isAvailable	,
				tcp1.chp_IsPayed	,
				tcp1.chp_isRejected,
				tcp1.chp_isCancelled,
				tb.bra_desc,
				tcp1.chp_id,
				tb2.bra_desc,
				tcp1.chp_isToOrder,
				tcp1.chp_isOwn,
				ttm.tm_isManualTax,
				ttm.tm_subtotal,	--MOS 09-2022: x los FORROS de CM que tienen un MONO haciendo pagos
				ttm.percentaje,		--MOS 09-2022: x los FORROS de CM que tienen un MONO haciendo pagos
				tccm.ccm_receiptNumber,
				tccm.ccm_customerName,
				tccm.ccm_lote



END
GO








CREATE procedure [dbo].[spCollection_getHeaderData]
(
	@comp_id	int,
	@bra_id		int,
	@cust_id	int
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	set nocount on



	/*
	declare @comp_id	int,
			@bra_id		int,
			@cust_id	int

	select	@comp_id	= 1,
			@bra_id		= 1,
			@cust_id	= 0
	*/


	declare @curr_id_1							int,
			@curr_id_2							int,
			@bra_CollectionMaximumAdjust		decimal(19,6),
			@bra_CollectionMaximumAdjustNoPass	DECIMAL(19,6),
			@bra_CollectionDefaultDocument		int



	select	@curr_id_1							= b.curr_id							,
			@bra_CollectionMaximumAdjust		= ISNULL(b.bra_CollectionMaximumAdjust,0)		,
			@bra_CollectionDefaultDocument		= b.bra_CollectionDefaultDocument,
			@bra_CollectionMaximumAdjustNoPass	= ISNULL(b.bra_CollectionMaximumAdjustNoPass,0)
		from	[tbBranch] b
				--inner join [tbsysCurrency] c
				--on c.[curr_id] = b.[curr_id]
		where	b.comp_id	= @comp_id	AND
				b.bra_id	= @bra_id


	select	@curr_id_2 = b.curr_id
		from	[tbCustomer] b
				--inner join [tbsysCurrency] c
				--on c.[curr_id] = b.[curr_id]
		where	b.comp_id   = @comp_id	AND
				b.[cust_id] = @cust_id




	select
		ISNULL(@curr_id_2,'')												[CurrIdCust],
		RTRIM(LTRIM(ISNULL((select	c.[curr_symbol]
								from [tbCustomer] b
								inner join [tbsysCurrency] c
									on c.[curr_id] = b.[curr_id]
								where	b.comp_id	= @comp_id AND
										b.[cust_id] = @cust_id),'')))		[Currency Customer],
		1																	[Value Customer],
		@curr_id_1															[CurrIdBranch],
		(
			select c.[curr_symbol]
				from [tbBranch] b
				inner join [tbsysCurrency] c
					on c.[curr_id] = b.[curr_id]
				where	b.comp_id = @comp_id AND
						b.bra_id = @bra_id
		)											[Currency Branch],
		(dbo.[fnGetExchange](@comp_id, 1, @curr_id_2, @curr_id_1, 0, 0, 0)) [Value Branch],
		@bra_CollectionMaximumAdjust										[CollectionMaximumAdjust],
		@bra_CollectionDefaultDocument										[CollectionDefaultDocument],
		@bra_CollectionMaximumAdjustNoPass									[bra_CollectionMaximumAdjustNoPass]



END
GO







CREATE PROCEDURE [dbo].[spCollection_getMailData]
(
		@comp_id			INT,
		@lang_id			INT	,
		@ct_transaction		INT,
		@bra_id				INT

)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON




	/*

	DECLARE	@comp_id			INT,
			@lang_id			INT	,
			@ct_transaction		INT,
			@bra_id				INT

	SELECT	@comp_id				=1,
			@lang_id				=2,
			@ct_transaction			=7696,
			@bra_id					=1

	*/



	SELECT	tb.bra_MainDesc			[comp_desc],
			tc.smtp_host,
			tc.smtp_port,
			tc.smtp_ssc,
			tc.smtp_user,
			tc.smtp_password,
			tdf.df_eMail2Customer_emailFrom					[from],
			tdf.df_eMail2Customer_emailFromName,
			tdf.df_eMail2Customer_emailTextBody,
			IsNull(tdf.df_eMail2Customer_emailToTest,'')	[df_eMail2Customer_emailToTest],
			tdf.df_eMail2Customer,
			isnull(tc2.cust_email,'')						[to]	,
			dbo.fnGetCommercialTransactionDescription(tct.comp_id,	@lang_id,tct.ct_transaction) [DocumentNumber]

	FROM	tbCompany										tc

			inner join tbCommercialTransactions				tct
			on  tct.comp_id			= tct.comp_id
			AND tct.bra_id			= tct.bra_id
			AND tct.ct_transaction	= tct.ct_transaction

			Inner Join tbsysDocuments						td
			On  td.sd_id			= tct.sd_id

			inner join tbDocumentsFile						tdf
			on  tdf.comp_id			= tct.comp_id
			AND tdf.bra_id			= tct.bra_id
			AND tdf.df_id			= tct.df_id

			inner join tbCustomer							tc2
			on  tc2.comp_id			= tct.comp_id
			AND tc2.cust_id			= tct.cust_id

			INNER JOIN tbBranch tb
				ON	tb.comp_id		= @comp_id AND
					tb.bra_id		= @bra_id


	WHERE	tc.comp_id			=   @comp_id
	and		tct.ct_transaction	=   @ct_transaction
	and		tct.bra_id			=	@bra_id


END
GO


-- UNUSED - NO SE USA MAS, se usa V2


CREATE  PROCEDURE [dbo].[spCollection_getTotals]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@cust_id			int,
	@forcedCurrId1		INT,
	@forcedCurrId2		INT,
	@exchange			decimal(30,10),
	@guid				UNIQUEIDENTIFIER,
	@df_id				INT


)
AS


BEGIN


	set nocount on


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------
	/*
	declare	@comp_id	int,
			@lang_id	int,
			@bra_id		int,
			@cust_id	int,
			@forcedCurrId1  AS INT,
			@forcedCurrId2  AS INT,
			@exchange	decimal(19,6),
			@guid		uniqueidentifier,
			@df_id		INT
	select	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@cust_id	= 85,
			@forcedCurrId1  =1,
			@forcedCurrId2  =1,
			@exchange	= 1,
			@guid		= 'B71E005D-B49E-4E7D-99D5-60413AD0507E',
			@df_id		= 8
	*/
	-- --------------------------------------------------------------------------



	SET DATEFORMAT ymd



	declare @d int
	set		@d = 2


	-- --------------------------------------------------------------------------
	/*** recuperar la moneda de la sucursal pasada como parametro
			(sucursal de donde se ejecuta la consulta)****/
	-- --------------------------------------------------------------------------
	declare @bra_curr_id	INT
	DECLARE @processingDate AS DATETIME
	select	@bra_curr_id	= b.curr_id,
			@processingDate = b.bra_processingDate
		from	[tbBranch] b			WITH (NOLOCK)
		where	b.bra_id = @bra_id
	-- --------------------------------------------------------------------------



	/*** recuperar la moneda del cliente pasada como parametro 		****/
	declare @cust_curr_id	int
	set		@cust_curr_id = ISNULL((select	b.curr_id
										from	[tbCustomer] b	WITH (NOLOCK)
										where	b.comp_id = @comp_id	AND
												b.cust_id = @cust_id)
									,@bra_curr_id)




	-- --------------------------------------------------------------------------
	-- Recupera el Interes si se pagan CUOTAS con Tarjeta de Credito
	-- --------------------------------------------------------------------------
	DECLARE @decInterest4PayLoanWithCreditCard AS DECIMAL(19,2)
	SET		@decInterest4PayLoanWithCreditCard = 0
	DECLARE @decPercent4PayLoanWithCreditCard AS DECIMAL(19,2)
	SET		@decPercent4PayLoanWithCreditCard = 0

	SELECT	@decPercent4PayLoanWithCreditCard  = Max(IsNull(tcclp.ccp_percentage4QuotePay,0)),
			@decInterest4PayLoanWithCreditCard = sum(tctm.ctct_total)
		FROM tbCreditCardMovementsTmp tmp				WITH (NOLOCK)
		inner JOIN tbCreditCardLoanPlan tcclp			WITH (NOLOCK)
		ON	tcclp.comp_id	= tmp.comp_id	AND
			tcclp.cc_id		= tmp.cc_id		AND
			tcclp.ccp_id	= tmp.ccp_id
		INNER JOIN tbCommercialTransactionsTmp	tctm	WITH (NOLOCK)
			ON tctm.ctct_guid	= tmp.ccmt_guid
		WHERE	tmp.ccmt_guid	= @guid AND
				tctm.ctl_id IS NOT NULL
	GROUP BY tmp.ccmt_guid

	SET @decInterest4PayLoanWithCreditCard = @decInterest4PayLoanWithCreditCard * @decPercent4PayLoanWithCreditCard / 100

	-- --------------------------------------------------------------------------


	-- --------------------------------------------------------------------------
	-- Recupera el Interes por diferencia de cotizacion
	-- --------------------------------------------------------------------------
	DECLARE @decInterest4ExchDif   DECIMAL(19,2)
	SET		@decInterest4ExchDif   = 0
	DECLARE @bitEnableInterest4CreditNote	AS BIT = 'False'
	DECLARE @intCurrID4ExchangeControl		AS INT
	SELECT 	@intCurrID4ExchangeControl =	CASE
												WHEN	tb.curr_id = tc.curr_id									AND
														tdf.curr_id4ExchangeDifferenceInterest IS NOT NULL		AND
														tdf.curr_id4ExchangeDifferenceInterest <> tb.curr_id		THEN	tdf.curr_id4ExchangeDifferenceInterest
												ELSE																	NULL
											END,
			@bitEnableInterest4CreditNote = ISNULL(df_enableExchangeDifferenceInterestCN,'False')

		FROM tbDocumentsFile tdf			WITH (NOLOCK)
		INNER JOIN tbbranch tb				WITH (NOLOCK)
			ON	tb.comp_id	= tdf.comp_id	AND
				tb.bra_id	= tdf.bra_id
		INNER JOIN tbcustomer tc			WITH (NOLOCK)
			ON	tc.comp_id	= @comp_id AND
				tc.cust_id	= @cust_id
		WHERE	tdf.comp_id = @comp_id AND
				tdf.df_id	= @df_id



	IF @intCurrID4ExchangeControl IS NOT NULL
		BEGIN

			-- --------------------------------------------------------------------------------
			-- MOS 06-01-2021, Fiesa, se calcula el NETO SIN percepciones ni II
			-- --------------------------------------------------------------------------------
			DECLARE @tblCoeficient4Neto TABLE(ct_transaction INT PRIMARY KEY,
											  coeficient DECIMAL(38,15))

			INSERT INTO @tblCoeficient4Neto
			(
				ct_transaction,
				coeficient
			)
				SELECT	ct.ct_transaction,
						 dbo.fnNoZDiv(	(
						 					ct.ct_total - (	SELECT SUM(ttm.tm_total)
						 					               		FROM		tbTaxMovements AS ttm	WITH (NOLOCK)
						 					               		INNER JOIN	tbTaxName AS ttn	WITH (NOLOCK)
						 					               		ON	ttn.tax_id	= ttm.tax_id					AND
						 					               			ttn.comp_id = ttm.comp_id
						 					               		WHERE	ttm.comp_id			= ct.comp_id		AND
						 					               				ttm.ct_transaction	= ct.ct_transaction AND
						 					               				ttn.tax_class		<> 1
						 								  )
										) / dbo.fnNoZDiv(ct.ct_subtotal - ISNULL(ct.ct_discount,0)))	-- MOS 02-2022 x FIESA y sus descuentos   - ISNULL(ct.ct_discount,0)
					FROM 	dbo.[tbCommercialTransactionsTmp]						ctct					WITH (NOLOCK)
					inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)	-- MOS 03-2022 x LEF
						on	VCTFS.comp_id					=	ctct.comp_id
						and VCTFS.ct_transaction			=	ctct.ctct_transaction
					inner join [tbCommercialTransactions]							ct						WITH (NOLOCK)
						on	ct.comp_id			= ctct.comp_id AND
							ct.[ct_transaction] = ctct.[ctct_transaction]
					INNER JOIN tbDocumentsFile									 AS tdf						WITH (NOLOCK)
						ON	tdf.comp_id = ct.comp_id AND
							tdf.df_id	= ct.df_id
					--inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
					--	on	VCTFS.comp_id					=	ct.comp_id
					--	--and VCTFS.bra_id					=	ct.bra_id
					--	and VCTFS.ct_transaction			=	ct.ct_transaction
					LEFT JOIN tbCommercialTransactionsLoan							tctl					WITH (NOLOCK)
						ON	tctl.comp_id		= ctct.comp_id			AND
							tctl.ct_transaction = ctct.ctct_transaction	AND
							tctl.ctl_id			= ctct.ctl_id
					where	ctct.ctct_guid	=	@guid
					AND tdf.df_DisableExchangeDifferenceInterest	=   'False'
					AND ct.ct_DisableExchangeDifferenceInterest		=   'False'	-- MOS 03-2022, estaban abajo y los puse arriba x LEF
					and     VCTFS.[sd_isInBalance]					=	'True'
					and	    VCTFS.[sd_isCredit]						=	'False' -- MOS 02-2020, se pone el lutimo where x def deshab en updatedatabase
					and	    VCTFS.[sd_isReceipt]					=	'False'
			-- --------------------------------------------------------------------------------


--==
--SELECT * FROM @tblCoeficient4Neto

			SET		@decInterest4ExchDif   =	ISNULL(
														(
															SELECT
																SUM(
																	(
																		dbo.fnGetExchange2(	ct.comp_id,
																							ctct.ctct_total,
																							ct.ct_ACurrency,
																							@intCurrID4ExchangeControl,
																							@forcedCurrId1,
																							@forcedCurrId2,
																							@exchange,
																							'FALSE')
																		-
																		dbo.fnGetExchange2(	ct.comp_id,
																							ctct.ctct_total,
																							ct.ct_ACurrency,
																							@intCurrID4ExchangeControl,
																							ct.curr_id4Exchange,
																							ct.curr_id_transaction,
																							ct.ct_curr_IdExchange,
																							0)
																	)

																		/

																		CASE
																			WHEN cfn.coeficient IS NULL THEN	dbo.fnNoZDiv(ct.ct_total / dbo.fnNoZDiv(ct.ct_subtotal - ISNULL(ct.ct_discount,0)))     -- MOS 02-2022 x FIESA y sus descuentos   - ISNULL(ct.ct_discount,0)
																			ELSE								dbo.fnNoZDiv(cfn.coeficient)
																		END
																	    --MOS 06-01-2021 Fiesa dbo.fnNoZDiv(ct.ct_total / dbo.fnNoZDiv(ct.ct_subtotal))

																   )

																from	dbo.[tbCommercialTransactionsTmp]						ctct					WITH (NOLOCK)
																INNER JOIN @tblCoeficient4Neto									cfn
																	ON cfn.ct_transaction = ctct.ctct_transaction
																inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)	-- MOS 03-2022 mas arriba  x LEF
																	on	VCTFS.comp_id					=	ctct.comp_id
																	and VCTFS.ct_transaction			=	ctct.ctct_transaction
																inner join [tbCommercialTransactions]							ct						WITH (NOLOCK)
																	on	ct.comp_id			= ctct.comp_id AND
																		ct.[ct_transaction] = ctct.[ctct_transaction]
																INNER JOIN tbDocumentsFile									 AS tdf						WITH (NOLOCK)
																	ON	tdf.comp_id = ct.comp_id AND
																		tdf.df_id	= ct.df_id
																INNER JOIN tbSalesTerms tst																WITH (NOLOCK)
																	ON	tst.st_id	= ct.st_id AND
																		tst.comp_id = ct.comp_id
																--inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
																--	on	VCTFS.comp_id					=	ct.comp_id
																--	--and VCTFS.bra_id					=	ct.bra_id
																--	and VCTFS.ct_transaction			=	ct.ct_transaction
																LEFT JOIN tbCommercialTransactionsLoan							tctl					WITH (NOLOCK)
																	ON	tctl.comp_id		= ctct.comp_id			AND
																		tctl.ct_transaction = ctct.ctct_transaction	AND
																		tctl.ctl_id			= ctct.ctl_id
																where	ctct.ctct_guid	=	@guid
																AND tdf.df_DisableExchangeDifferenceInterest=   'False'	-- MOS 03-2022: Estaba abajo y lo pase arriba x lef
																and     VCTFS.[sd_isInBalance]				=	'True'
																and	    VCTFS.[sd_isCredit]					=	'False' -- MOS 02-2020, se pone el lutimo where x def deshab en updatedatabase
																and	    VCTFS.[sd_isReceipt]				=	'False'

														)
													,0)



--==
--SELECT @decInterest4ExchDif

			DELETE FROM tbCollection_ExchDiffTMPValues --WITH (ROWLOCK)
				WHERE [guid] = @guid
			INSERT INTO tbCollection_ExchDiffTMPValues(	[guid],
														comp_id,
														tax_id,
														Neto,
														IVA,
														Coef)

					SELECT		@guid,
								ttn.comp_id,
								ttn.tax_id,
								SUM(ttm.tm_subtotal)			[Neto],
								SUM(ttm.tm_total)				[Iva],
								0

						from	dbo.[tbCommercialTransactionsTmp]						ctct					WITH (NOLOCK)
						inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)	-- MOS 03-2022 mas arriba x LEF
							on	VCTFS.comp_id					=	ctct.comp_id
							and VCTFS.ct_transaction			=	ctct.ctct_transaction
						inner join [tbCommercialTransactions]							ct						WITH (NOLOCK)
							on	ct.comp_id			= ctct.comp_id AND
								ct.[ct_transaction]	= ctct.[ctct_transaction]
						--inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
						--	on	VCTFS.comp_id					=	ct.comp_id
						--	--and VCTFS.bra_id					=	ct.bra_id
						--	and VCTFS.ct_transaction			=	ct.ct_transaction
						INNER JOIN tbDocumentsFile									 AS tdf						WITH (NOLOCK)
							ON	tdf.comp_id = ct.comp_id AND
								tdf.df_id	= ct.df_id
						INNER JOIN tbTaxMovements ttm															WITH (NOLOCK)
							ON	ttm.comp_id			= ct.comp_id AND
								ttm.ct_transaction	= ct.ct_transaction
						INNER JOIN tbTaxName ttn																WITH (NOLOCK)
							ON	ttn.comp_id = ttm.comp_id AND
								ttn.tax_id	= ttm.tax_id

						INNER JOIN tbSalesTerms tst																WITH (NOLOCK)
							ON	tst.st_id	= ct.st_id AND
								tst.comp_id = ct.comp_id

						LEFT JOIN tbCommercialTransactionsLoan							tctl					WITH (NOLOCK)
							ON	tctl.comp_id		= ctct.comp_id			AND
								tctl.ct_transaction = ctct.ctct_transaction	AND
								tctl.ctl_id			= ctct.ctl_id
						where	ctct.ctct_guid	=	@guid									AND
								tdf.df_DisableExchangeDifferenceInterest		=   'False' AND
								ttn.tax_class = 1											AND	-- MOS 03-2022: estaban abajo y los pase arriba x LEF
								VCTFS.[sd_isInBalance]							=	'True'	AND
							    VCTFS.[sd_isCredit]								=	'False'	AND		-- MOS 02-2020, se pone el lutimo where x def deshab en updatedatabase
							    VCTFS.[sd_isReceipt]							=	'False'
						GROUP BY ttn.comp_id, ttn.tax_id, ttn.tax_id




			DECLARE @intACurrency AS INT
			SELECT 	@intACurrency = tc.curr_id
				FROM tbCustomer tc	WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @cust_id
			SET @decInterest4ExchDif = @decInterest4ExchDif * -1
			SET @decInterest4ExchDif = dbo.fnGetExchange2(	@comp_id,
															@decInterest4ExchDif,
															@intCurrID4ExchangeControl,
															@intACurrency,
															@forcedCurrId1,
															@forcedCurrId2,
															@exchange,
															'FALSE')

			IF @decInterest4ExchDif < 0 AND @bitEnableInterest4CreditNote = 'False'
				BEGIN
					SET @decInterest4ExchDif = 0
				END

		END
	-- --------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Recupera el Interes por MORA
	-- --------------------------------------------------------------------------

	DECLARE @decInterest4QuoteMora DECIMAL(19,2)
	SET		@decInterest4QuoteMora = 0
	SET		@decInterest4QuoteMora =
		isnull((select	convert(decimal(18,2),round(sum(round(ctct.[ctct_total],@d) *
																ct.[ct_ACurrencyExchange] *
																CASE
																	WHEN
																		(
																			CASE
																				WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																				ELSE tctl.ctl_payDate
																			END < @processingDate
																		)
																			AND
																		(
																	   		(
																	   			DATEDIFF(DAY,	CASE
													   												WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
													   												ELSE tctl.ctl_payDate
													   											END,@processingDate
																	   					)
																   					-
																   				dbo.fngetDiasDePandemia2(CASE
																   											WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   											ELSE tctl.ctl_payDate
																   										END,
																   										@processingDate,
																										tdf.df_pandemyDaysFrom,
																										tdf.df_pandemyDaysTo)
																	   		)

																	   				>

													   										CASE
													   											WHEN tctl.comp_id IS NULL THEN	tst.st_collectionInterestFromDays
													   											ELSE							tst.st_collectionLoanInterestFromDays
													   										END
																		)
																			THEN
																				   (
																				   		(
																						CASE
																							WHEN tctl.comp_id IS NULL THEN tst.st_collectionInterest
																							ELSE tst.st_collectionLoanInterest
																						END
																						 / 30
																				   		)
																				   		*
																				   		(
																				   			DATEDIFF(DAY,	CASE
																   												WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   												ELSE tctl.ctl_payDate
																   											END,@processingDate)
																   								-
																   							dbo.fngetDiasDePandemia2(CASE
																   														WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   														ELSE tctl.ctl_payDate
																   													END,
																   													@processingDate,
																													tdf.df_pandemyDaysFrom,
																													tdf.df_pandemyDaysTo)
																   						)
																				   ) / 100
																	ELSE			0
																END
													),@d))
				from	dbo.[tbCommercialTransactionsTmp]						ctct					WITH (NOLOCK)
				inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
					on	VCTFS.comp_id					=	ctct.comp_id
					and VCTFS.ct_transaction			=	ctct.ctct_transaction
				-- MOS 03-2022, lo pase arriba y el join contra la tmp x LEF
				--inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
				--	on	VCTFS.comp_id					=	ct.comp_id
				--	and VCTFS.ct_transaction			=	ct.ct_transaction
				inner join [tbCommercialTransactions]							ct						WITH (NOLOCK)
					on	ct.comp_id			= ctct.comp_id AND
						ct.[ct_transaction] = ctct.[ctct_transaction]

				INNER JOIN tbDocumentsFile									AS tdf						WITH (NOLOCK)
					ON	tdf.comp_id = ct.comp_id	AND
						tdf.bra_id	= ct.bra_id		AND
						tdf.df_id	= ct.df_id
				INNER JOIN tbSalesTerms tst																WITH (NOLOCK)
					ON	tst.comp_id = ct.comp_id AND
						tst.st_id	= ct.st_id

				LEFT JOIN tbCommercialTransactionsLoan							tctl					WITH (NOLOCK)
					ON	tctl.comp_id		= ctct.comp_id			AND
						tctl.ct_transaction = ctct.ctct_transaction	AND
						tctl.ctl_id			= ctct.ctl_id
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.[sd_isInBalance]				=	'True'
				and	    VCTFS.[sd_isCredit]					=	'False'
				and	    VCTFS.[sd_isReceipt]				=	'False'),0)

	-- --------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Si es que hay algun interes busca el documento asociado al debito
	-- y el articulo para poder generar el pedido
	-- si no lo encuentra pone el interes en CERO
	-- --------------------------------------------------------------------------
	DECLARE @df_Collection_Interest_Minimum AS DECIMAL(19,4)
	DECLARE @decInterestTaxes			AS DECIMAL(19,2)
	SET		@decInterestTaxes			= 0
	DECLARE @df_id4Interest				AS INT
	DECLARE @item_id4Interest			AS INT
	IF	@decInterest4QuoteMora				<> 0	OR
		@decInterest4PayLoanWithCreditCard	<> 0
		BEGIN

			SELECT
			       @item_id4Interest				= tdf.df_Collection_item_id4InterestDebit,
			       @df_Collection_Interest_Minimum	= tdf.df_Collection_Interest_Minimum
				FROM tbDocumentsFile tdf				WITH (NOLOCK)
				WHERE	tdf.comp_id = @comp_id AND
						tdf.df_id	= @df_id

			SELECT @df_id4Interest =  tdf.df_id
				FROM fnDocumentsFile_GetDocumentsForDebitCreditNotes(@comp_id, @bra_id, @cust_id) tdf
				INNER JOIN tbDocumentsFile tdf2			WITH (NOLOCK)
					ON	tdf2.comp_id	= @comp_id AND
						tdf2.df_id		= tdf.df_id
				WHERE	--tdf.sd_isDebitNote						= 1		AND
					( -- MOS 10-2021 x q el NABO q lo hizo no tomo en cuenta si era NC o ND
						((@decInterest4QuoteMora + @decInterest4PayLoanWithCreditCard) > 0	AND tdf.sd_isDebitNote	= 'True')
							OR
						((@decInterest4QuoteMora + @decInterest4PayLoanWithCreditCard) <= 0	AND tdf.sd_isCreditNote = 'True')
					)													AND
						tdf.Is4ExchangeDifference				= 0		AND
						tdf2.df_Collection_Interest_isDebitNoteDocument = 1
				ORDER BY tdf.df_order



			-- Si NO estan configurados que NO calcule los Intereses !
			IF @df_id4Interest		IS NULL OR
			   @item_id4Interest	IS NULL
				BEGIN
					SET @decInterest4QuoteMora				= 0
					SET @decInterest4PayLoanWithCreditCard	= 0
				END

			-- Si el MINIMO INteres es mayor que lo calculado lo pone en CERO
			IF @df_Collection_Interest_Minimum > (@decInterest4QuoteMora + @decInterest4PayLoanWithCreditCard)
				BEGIN
					SET @decInterest4QuoteMora				= 0
					SET @decInterest4PayLoanWithCreditCard	= 0
				END



				DECLARE @decCoefAux AS DECIMAL(25,6)
				SET @decCoefAux = dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id4Interest)

				SET @decInterestTaxes = (
											(
												@decInterest4QuoteMora
												+
												@decInterest4PayLoanWithCreditCard
											 )
										 * @decCoefAux
										)

										-

										(
											@decInterest4QuoteMora
											+
											@decInterest4PayLoanWithCreditCard
										 )


		END



	-- Suma el impuesto por diferencia de cambio.
	IF @decInterest4ExchDif				<> 0
		BEGIN

			DECLARE @intItemID4ExchangeInterest AS INT
			SELECT	@intItemID4ExchangeInterest = tdf.item_idExchangeDifferenceInterest
				FROM tbDocumentsFile tdf				WITH (NOLOCK)
				WHERE	tdf.comp_id = @comp_id AND
						tdf.df_id	= @df_id
			IF @intItemID4ExchangeInterest IS NOT NULL
				BEGIN

					DECLARE @decTMPTotal AS DECIMAL(29,4)
					SET		@decTMPTotal = 0
					SELECT 	@decTMPTotal = SUM(tmp.Neto)
						FROM tbCollection_ExchDiffTMPValues tmp	WITH (NOLOCK)
						WHERE tmp.guid = @guid

					SELECT @decInterestTaxes = @decInterestTaxes +	(
																		(tmp.Neto / dbo.fnNoZDiv(@decTMPTotal)) * @decInterest4ExchDif * ttn.tax_percentage / 100
																	)
						FROM tbCollection_ExchDiffTMPValues tmp	WITH (NOLOCK)
						INNER JOIN tbTaxName				ttn	WITH (NOLOCK)
							ON	ttn.comp_id = tmp.comp_id AND
								ttn.tax_id	= tmp.tax_id
						WHERE tmp.guid = @guid


					--SET @decInterestTaxes = @decInterestTaxes +  ( (@decInterest4ExchDif  * dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @intItemID4ExchangeInterest) - @decInterest4ExchDif) )
				END
			ELSE
				BEGIN
					SET @decInterest4ExchDif = 0
				END
		END
	-- --------------------------------------------------------------------------




	-- Select General
	select

		isnull((select	convert(decimal(18,2),round(sum(round(ctct.[ctct_total],@d)			*
																ct.[ct_ACurrencyExchange]
													),@d))
				from	dbo.[tbCommercialTransactionsTmp]								ctct		WITH (NOLOCK)
				inner join [tbCommercialTransactions]							ct					WITH (NOLOCK)
					ON	ct.comp_id			= ctct.comp_id				AND
						ct.[ct_transaction] = ctct.[ctct_transaction]
				inner join dbo.vwCommercialTransactions_forSales				VCTFS				WITH (NOLOCK)
					on	VCTFS.comp_id					=	ct.comp_id
					and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.[sd_isInBalance]				=	'True'
				and	    VCTFS.[sd_isCredit]					=	'False'
				and	    VCTFS.[sd_isReceipt]				=	'False'),0)							[totalCustomer],



		isnull((select	convert(decimal(18,2),sum(round(dbo.fnGetExchange2(ct.comp_id,
																			ctct.ctct_total,
																			ct.ct_ACurrency,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	dbo.[tbCommercialTransactionsTmp]								ctct		WITH (NOLOCK)
						inner join [tbCommercialTransactions]							ct			WITH (NOLOCK)
						ON	ct.comp_id			= ctct.comp_id				AND
							ct.[ct_transaction] = ctct.[ctct_transaction]
						inner join dbo.vwCommercialTransactions_forSales				VCTFS		WITH (NOLOCK)
						on	VCTFS.comp_id					=	ct.comp_id
						--and VCTFS.bra_id					=	ct.bra_id
						and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.[sd_isInBalance]				=	'True'
				and	    VCTFS.[sd_isCredit]					=	'False'
				and	    VCTFS.[sd_isReceipt]				=	'False'),0)							[totalPay],



		isnull((select  convert(decimal(18,2),sum(round(dbo.fnGetExchange2(@comp_id,
																			vct.amount,
																			vct.curr_id,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	vwCollectionTmp												vct		WITH (NOLOCK)
				where	vct.guid		=	@guid and vct.lang_id = @lang_id),0)					[totalHow],



		isnull((select	convert(decimal(18,2),sum(round(dbo.fnGetExchange2(tmt.comp_id,
																			tmt.tmt_total,
																			tmt.curr_id,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	dbo.tbTaxMovementsTmp										tmt		WITH (NOLOCK)
				where	tmt.tmt_guid	=	@guid),0)												[totalRetention],



		isnull((select  convert(decimal(18,2),sum(round(dbo.fnGetExchange2(ctct.comp_id,
																		   ctct.[ctct_total],
																		   ct.curr_id_transaction,
																		   ct.ct_ACurrency,
																		   ct.curr_id_transaction,
																		   ct.ct_ACurrency,
																		   ctct.ctct_exchange,
																		   'FALSE')
														,@d)))
				from	dbo.[tbCommercialTransactionsTmp]	ctct			WITH (NOLOCK)
						inner join [tbCommercialTransactions]	ct			WITH (NOLOCK)
						ON	ct.comp_id			= ctct.comp_id				AND
							ct.[ct_transaction] = ctct.[ctct_transaction]
						inner join dbo.[vwCommercialTransactions_PaymentOnAccount]	VCTFS	WITH (NOLOCK)
						on	VCTFS.comp_id					=	ct.comp_id
						--and VCTFS.bra_id					=	ct.bra_id
						and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid),0)												[totalOnAccount],






		isnull((select  convert(decimal(18,2),sum(round(ctct.[ctct_total],@d)))
				from	dbo.[tbCommercialTransactionsTmp]	ctct			WITH (NOLOCK)
				where	ctct.ctct_guid			=	@guid
				AND		upper(ctct.ctct_origin)	=	UPPER('s')),0)									[totalACta],





		@decInterest4QuoteMora						[totalInterest]	,





		isnull((select	convert(decimal(18,2),round(sum(
												   		DATEDIFF(DAY,	CASE
								   											WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
								   											ELSE tctl.ctl_payDate
								   										END,@processingDate
												   		        )
														)
												,@d)
								)
				from	dbo.[tbCommercialTransactionsTmp]								ctct		WITH (NOLOCK)
				inner join dbo.vwCommercialTransactions_forSales				VCTFS				WITH (NOLOCK)		-- MOS 03-2022 x LEF
					on	VCTFS.comp_id					=	ctct.comp_id
					and VCTFS.ct_transaction			=	ctct.ctct_transaction
				inner join [tbCommercialTransactions]							ct					WITH (NOLOCK)
					ON	ct.comp_id			= ctct.comp_id				AND
						ct.[ct_transaction] = ctct.[ctct_transaction]
				INNER JOIN tbSalesTerms tst															WITH (NOLOCK)
					ON	tst.comp_id			= ct.comp_id AND
						tst.st_id			= ct.st_id

				--inner join dbo.vwCommercialTransactions_forSales				VCTFS				WITH (NOLOCK)
				--	on	VCTFS.comp_id					=	ct.comp_id
				--	--and VCTFS.bra_id					=	ct.bra_id
				--	and VCTFS.ct_transaction			=	ct.ct_transaction
				LEFT JOIN tbCommercialTransactionsLoan							tctl				WITH (NOLOCK)
					ON	tctl.comp_id		= ctct.comp_id			AND
						tctl.ct_transaction = ctct.ctct_transaction	AND
						tctl.ctl_id			= ctct.ctl_id
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.[sd_isInBalance]				=	'True'
				and	    VCTFS.[sd_isCredit]					=	'False'
				and	    VCTFS.[sd_isReceipt]				=	'False'
		),0)																							[moraDays],
		@decInterest4PayLoanWithCreditCard																[Interest4PayLoanWithCreditCard],
		@decInterestTaxes																				[InterestTaxes],
		@decInterest4ExchDif																			[InterestExchangeDifference]





END



GO


-- Log
--  MOS 04-2024:  x q sino tomaba los pedidos seleccionados a cuenta en cobranzas que no se quien fue el reverendo hijo de recontra re mil reputas q puso el id de saleorder dentro de el campo de ctct_transaction


CREATE  PROCEDURE [dbo].[spCollection_getTotalsV2]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@cust_id			int,
	@forcedCurrId1		INT,
	@forcedCurrId2		INT,
	@exchange			decimal(30,10),
	@guid				UNIQUEIDENTIFIER,
	@df_id				INT,
	@prof_id			INT,
	@user_id			INT
)	--   with Recompile    NO, pone re lento todo ya que recompila cada puta vez q entra aca.
AS


BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED

	-- MOS 03-2022.   Puede ser peligroso dejar esto aca.  x tema LEF
	--SET LOCK_TIMEOUT 500
	--SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------
	/*
	declare	@comp_id	int,
			@lang_id	int,
			@bra_id		int,
			@cust_id	int,
			@forcedCurrId1  AS INT,
			@forcedCurrId2  AS INT,
			@exchange	decimal(19,6),
			@guid		uniqueidentifier,
			@df_id		INT
	select	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 26,
			@cust_id	= 641,
			@forcedCurrId1  =1,
			@forcedCurrId2  =1,
			@exchange	= 1,
			@guid		= '7C83649C-F87D-4DBA-B7A0-989D015FBCAC',
			@df_id		= 69
	*/
	-- --------------------------------------------------------------------------


	SET NOCOUNT		ON
	SET DATEFORMAT	YMD



	DECLARE @d INT = 2	-- FORROOOOOOOO


	-- --------------------------------------------------------------------------
	/*** recuperar la moneda de la sucursal pasada como parametro
			(sucursal de donde se ejecuta la consulta)****/
	-- --------------------------------------------------------------------------
	DECLARE @bra_curr_id	INT	= null
	DECLARE @processingDate AS DATETIME
	select	@bra_curr_id	= b.curr_id,
			@processingDate = b.bra_processingDate
		from	dbo.tbBranch b			WITH (NOLOCK)
		where	b.comp_id	= @comp_id AND
				b.bra_id	= @bra_id
	-- --------------------------------------------------------------------------



	/*** recuperar la moneda del cliente pasada como parametro 		****/
	DECLARE @cust_curr_id	INT = NULL

	-- MOS 04-2022
	SELECT	@cust_curr_id =	b.curr_id
		FROM 	dbo.tbCustomer b	WITH (NOLOCK)
		WHERE 	b.comp_id = @comp_id	AND
				b.cust_id = @cust_id
	IF @cust_curr_id IS NULL SET @cust_curr_id = @bra_curr_id

	--set		@cust_curr_id = ISNULL((select	b.curr_id
	--									from	dbo.tbCustomer b	WITH (NOLOCK)
	--									where	b.comp_id = @comp_id	AND
	--											b.cust_id = @cust_id)
	--								,@bra_curr_id)



	-- --------------------------------------------------------------------------
	-- Recupera el Interes si se pagan CUOTAS con Tarjeta de Credito
	-- --------------------------------------------------------------------------
	DECLARE @decInterest4PayLoanWithCreditCard AS DECIMAL(19,2)
	SET		@decInterest4PayLoanWithCreditCard = 0
	DECLARE @decPercent4PayLoanWithCreditCard AS DECIMAL(19,2)
	SET		@decPercent4PayLoanWithCreditCard = 0

	SELECT	@decPercent4PayLoanWithCreditCard  = MAX(IsNull(tcclp.ccp_percentage4QuotePay,0)),
			@decInterest4PayLoanWithCreditCard = SUM(ISNULL(tctm.ctct_total,0))
		FROM dbo.tbCreditCardMovementsTmp tmp				WITH (NOLOCK)
		INNER JOIN dbo.tbCreditCardLoanPlan tcclp			WITH (NOLOCK)
		ON	tcclp.comp_id	= tmp.comp_id	AND
			tcclp.cc_id		= tmp.cc_id		AND
			tcclp.ccp_id	= tmp.ccp_id
		INNER JOIN dbo.tbCommercialTransactionsTmp	tctm	WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
			ON tctm.ctct_guid	= tmp.ccmt_guid
		WHERE	tmp.ccmt_guid	= @guid AND
				tctm.ctl_id IS NOT NULL
		GROUP BY tmp.ccmt_guid

	SET @decInterest4PayLoanWithCreditCard = @decInterest4PayLoanWithCreditCard * @decPercent4PayLoanWithCreditCard / 100

	-- --------------------------------------------------------------------------


	-- --------------------------------------------------------------------------
	-- Recupera el Interes por diferencia de cotizacion
	-- --------------------------------------------------------------------------
	DECLARE @decInterest4ExchDif   DECIMAL(19,2)
	SET		@decInterest4ExchDif   = 0
	DECLARE @decInterest4ExchDifonAccountReceipt	DECIMAL(19,2) = 0
	DECLARE @bitEnableInterest4CreditNote	AS BIT = 'False'
	DECLARE @intCurrID4ExchangeControl		AS INT
	SELECT 	@intCurrID4ExchangeControl =	CASE
												WHEN	tb.curr_id = tc.curr_id									AND
														tdf.curr_id4ExchangeDifferenceInterest IS NOT NULL		AND
														tdf.curr_id4ExchangeDifferenceInterest <> tb.curr_id		THEN	tdf.curr_id4ExchangeDifferenceInterest
												ELSE																	NULL
											END,
			@bitEnableInterest4CreditNote = ISNULL(df_enableExchangeDifferenceInterestCN,'False')
		FROM dbo.tbDocumentsFile tdf			WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
		INNER JOIN dbo.tbbranch tb				WITH (NOLOCK)
			ON	tb.comp_id	= tdf.comp_id	AND
				tb.bra_id	= tdf.bra_id
		INNER JOIN dbo.tbcustomer tc			WITH (NOLOCK)
			ON	tc.comp_id	= @comp_id AND
				tc.cust_id	= @cust_id
		WHERE	tdf.comp_id = @comp_id AND
				tdf.df_id	= @df_id



	IF @intCurrID4ExchangeControl IS NOT NULL
		BEGIN
		-- no
			-- --------------------------------------------------------------------------------
			-- MOS 06-01-2021, Fiesa, se calcula el NETO SIN percepciones ni II
			-- --------------------------------------------------------------------------------
			DECLARE		@tblCoeficient4Neto TABLE(	ct_transaction	INT				PRIMARY KEY,
													coeficient		DECIMAL(38,15))

			INSERT INTO @tblCoeficient4Neto
			(
				ct_transaction,
				coeficient
			)
				SELECT	ct.ct_transaction,
						 dbo.fnNoZDiv(	(
						 					ct.ct_total - ISNULL(
						 											(	SELECT SUM(ttm.tm_total)
						 					               					FROM		dbo.tbTaxMovements	AS ttm	WITH (NOLOCK)
						 					               					INNER JOIN	dbo.tbTaxName		AS ttn	WITH (NOLOCK)
						 					               					ON	ttn.tax_id	= ttm.tax_id					AND
						 					               						ttn.comp_id = ttm.comp_id
						 					               					WHERE	ttm.comp_id			= ct.comp_id		AND
						 					               							ttm.ct_transaction	= ct.ct_transaction AND
						 					               							ttn.tax_class		<> 1
						 											)
						 									   ,0)
										) / dbo.fnNoZDiv(ct.ct_subtotal - ISNULL(ct.ct_discount,0)))	-- MOS 02-2022 x FIESA y sus descuentos   - ISNULL(ct.ct_discount,0)
					FROM 	dbo.tbCommercialTransactionsTmp							ctct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
					inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))	-- MOS 03-2022 x LEF
						on	VCTFS.comp_id					=	ctct.comp_id
						and VCTFS.ct_transaction			=	ctct.ctct_transaction
					inner join dbo.tbCommercialTransactions							ct						WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
						on	ct.comp_id			= ctct.comp_id AND
							ct.ct_transaction   = ctct.ctct_transaction
					INNER JOIN dbo.tbDocumentsFile									tdf						WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
						ON	tdf.comp_id = ct.comp_id AND
							tdf.df_id	= ct.df_id
					LEFT JOIN dbo.tbCommercialTransactionsLoan						tctl					WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
						ON	tctl.comp_id		= ctct.comp_id			AND
							tctl.ct_transaction = ctct.ctct_transaction	AND
							tctl.ctl_id			= ctct.ctl_id
					where	ctct.ctct_guid	=	@guid
					AND tdf.df_DisableExchangeDifferenceInterest	=   'False'
					AND ct.ct_DisableExchangeDifferenceInterest		=   'False'	-- MOS 03-2022, estaban abajo y los puse arriba x LEF
					and     VCTFS.sd_isInBalance					=	'True'
					-- MOS 09-2023: Lo saque para que tome en cta las NC a cuenta ahora aplicadas.  and	    VCTFS.sd_isCredit						=	'False' -- MOS 02-2020, se pone el lutimo where x def deshab en updatedatabase
					and	    VCTFS.sd_isReceipt						=	'False'
			-- --------------------------------------------------------------------------------


--==
--SELECT '@tblCoeficient4Neto',* FROM @tblCoeficient4Neto



			SET		@decInterest4ExchDif   =	ISNULL(
														(
															SELECT
																SUM(
																	(
																		dbo.fnGetExchange2(	ct.comp_id,
																							ctct.ctct_total * VCTFS.PlusOrMinus,
																							ct.ct_ACurrency,
																							@intCurrID4ExchangeControl,
																							@forcedCurrId1,
																							@forcedCurrId2,
																							@exchange,
																							'FALSE')
																		-
																		dbo.fnGetExchange2(	ct.comp_id,
																							ctct.ctct_total * VCTFS.PlusOrMinus,
																							ct.ct_ACurrency,
																							@intCurrID4ExchangeControl,
																							ct.curr_id4Exchange,
																							ct.curr_id_transaction,
																							ct.ct_curr_IdExchange,
																							0)
																	)

																		/

																		CASE
																			WHEN cfn.coeficient IS NULL THEN	dbo.fnNoZDiv(ct.ct_total / dbo.fnNoZDiv(ct.ct_subtotal - ISNULL(ct.ct_discount,0)))     -- MOS 02-2022 x FIESA y sus descuentos   - ISNULL(ct.ct_discount,0)
																			ELSE								dbo.fnNoZDiv(cfn.coeficient)
																		END
																	    --MOS 06-01-2021 Fiesa dbo.fnNoZDiv(ct.ct_total / dbo.fnNoZDiv(ct.ct_subtotal))

																   )

																from	dbo.tbCommercialTransactionsTmp							ctct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
																INNER JOIN @tblCoeficient4Neto									cfn
																	ON cfn.ct_transaction = ctct.ctct_transaction
																inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))	-- MOS 03-2022 mas arriba  x LEF
																	on	VCTFS.comp_id					=	ctct.comp_id
																	and VCTFS.ct_transaction			=	ctct.ctct_transaction
																inner join dbo.tbCommercialTransactions							ct						WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
																	on	ct.comp_id			= ctct.comp_id AND
																		ct.ct_transaction	= ctct.ctct_transaction
																INNER JOIN dbo.tbDocumentsFile									 AS tdf					WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
																	ON	tdf.comp_id = ct.comp_id AND
																		tdf.df_id	= ct.df_id
																LEFT JOIN dbo.tbCommercialTransactionsLoan							tctl				WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
																	ON	tctl.comp_id		= ctct.comp_id			AND
																		tctl.ct_transaction = ctct.ctct_transaction	AND
																		tctl.ctl_id			= ctct.ctl_id
																WHERE 	ctct.ctct_guid						=	@guid
																AND tdf.df_DisableExchangeDifferenceInterest=   'False'	-- MOS 03-2022: Estaba abajo y lo pase arriba x lef
																and     VCTFS.sd_isInBalance				=	'True'
																-- MOS 09-2023: Lo saque para que tome en cta las NC a cuenta ahora aplicadas.  and	    VCTFS.sd_isCredit					=	'False' -- MOS 02-2020, se pone el lutimo where x def deshab en updatedatabase
																and	    VCTFS.sd_isReceipt					=	'False'

														)
													,0)


			-- -------------------------------------------------------------------------------------------------------------
			-- MOS 09-2023: Se hozo que los recibos a cuenta CALCULEN diferencia de cotizacion pero se lo va a dejar apagado
			--  si hace falta activarlo, ponerlo conf desde el DOCUMENTO.
			-- -------------------------------------------------------------------------------------------------------------
			SET		@decInterest4ExchDifonAccountReceipt   =	ISNULL(
														(
															SELECT
																SUM(
																	(
																		dbo.fnGetExchange2(	ct.comp_id,
																							ctct.ctct_total * VCTFS.PlusOrMinus,
																							ct.ct_ACurrency,
																							@intCurrID4ExchangeControl,
																							@forcedCurrId1,
																							@forcedCurrId2,
																							@exchange,
																							'FALSE')
																		-
																		dbo.fnGetExchange2(	ct.comp_id,
																							ctct.ctct_total * VCTFS.PlusOrMinus,
																							ct.ct_ACurrency,
																							@intCurrID4ExchangeControl,
																							ct.curr_id4Exchange,
																							ct.curr_id_transaction,
																							ct.ct_curr_IdExchange,
																							0)
																	)

																		/

																		dbo.fnNoZDiv(ct.ct_total / dbo.fnNoZDiv(ct.ct_subtotal - ISNULL(ct.ct_discount,0)))
																		--CASE
																		--	WHEN cfn.coeficient IS NULL THEN	dbo.fnNoZDiv(ct.ct_total / dbo.fnNoZDiv(ct.ct_subtotal - ISNULL(ct.ct_discount,0)))     -- MOS 02-2022 x FIESA y sus descuentos   - ISNULL(ct.ct_discount,0)
																		--	ELSE								dbo.fnNoZDiv(cfn.coeficient)
																		--END
																	    --MOS 06-01-2021 Fiesa dbo.fnNoZDiv(ct.ct_total / dbo.fnNoZDiv(ct.ct_subtotal))

																   )

																from	dbo.tbCommercialTransactionsTmp							ctct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
																--INNER JOIN @tblCoeficient4Neto									cfn
																--	ON cfn.ct_transaction = ctct.ctct_transaction
																inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))	-- MOS 03-2022 mas arriba  x LEF
																	on	VCTFS.comp_id					=	ctct.comp_id
																	and VCTFS.ct_transaction			=	ctct.ctct_transaction
																inner join dbo.tbCommercialTransactions							ct						WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
																	on	ct.comp_id			= ctct.comp_id AND
																		ct.ct_transaction	= ctct.ctct_transaction
																INNER JOIN dbo.tbDocumentsFile									 AS tdf					WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
																	ON	tdf.comp_id = ct.comp_id AND
																		tdf.df_id	= ct.df_id
																LEFT JOIN dbo.tbCommercialTransactionsLoan							tctl				WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
																	ON	tctl.comp_id		= ctct.comp_id			AND
																		tctl.ct_transaction = ctct.ctct_transaction	AND
																		tctl.ctl_id			= ctct.ctl_id
																WHERE 	ctct.ctct_guid						=	@guid
																AND tdf.df_DisableExchangeDifferenceInterest=   'False'	-- MOS 03-2022: Estaba abajo y lo pase arriba x lef
																and     VCTFS.sd_isInBalance				=	'True'
																-- MOS 09-2023: Lo saque para que tome en cta las NC a cuenta ahora aplicadas.   and	    VCTFS.sd_isCredit					=	'False' -- MOS 02-2020, se pone el lutimo where x def deshab en updatedatabase
																and	    VCTFS.sd_isReceipt					=	'True'

														)
													,0)

			SET @decInterest4ExchDifonAccountReceipt = 0 -- MOS 09-2023: Al final dejar que los RECIBOS NO calculen dif de cotizacion.  si se activa ponerlo x configuracion.
			-- -------------------------------------------------------------------------------------------------------------



--==
--SELECT 'decInterest4ExchDif',@decInterest4ExchDif,'@decInterest4ExchDifonAccountReceipt',@decInterest4ExchDifonAccountReceipt

			DELETE FROM tbCollection_ExchDiffTMPValues	WHERE [guid] = @guid
			INSERT INTO tbCollection_ExchDiffTMPValues(	[guid],
														comp_id,
														tax_id,
														Neto,
														IVA,
														Coef)

					SELECT		@guid,
								ttn.comp_id,
								ttn.tax_id,
								SUM(ttm.tm_subtotal * VCTFS.PlusOrMinus)			[Neto],
								SUM(ttm.tm_total    * VCTFS.PlusOrMinus)			[Iva],
								0

						from	dbo.tbCommercialTransactionsTmp							ctct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
						inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))	-- MOS 03-2022 mas arriba x LEF
							on	VCTFS.comp_id					=	ctct.comp_id
							and VCTFS.ct_transaction			=	ctct.ctct_transaction
						inner join dbo.tbCommercialTransactions							ct						WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
							on	ct.comp_id			= ctct.comp_id AND
								ct.ct_transaction	= ctct.ctct_transaction
						--inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
						--	on	VCTFS.comp_id					=	ct.comp_id
						--	--and VCTFS.bra_id					=	ct.bra_id
						--	and VCTFS.ct_transaction			=	ct.ct_transaction
						INNER JOIN dbo.tbTaxMovements ttm															WITH (NOLOCK)
							ON	ttm.comp_id			= ct.comp_id AND
								ttm.ct_transaction	= ct.ct_transaction
						INNER JOIN dbo.tbTaxName ttn																WITH (NOLOCK)
							ON	ttn.comp_id = ttm.comp_id AND
								ttn.tax_id	= ttm.tax_id
						INNER JOIN dbo.tbSalesTerms tst																WITH (NOLOCK,INDEX(PK__tbSalesTerms__07C12930))
							ON	tst.st_id	= ct.st_id AND
								tst.comp_id = ct.comp_id
						INNER JOIN dbo.tbDocumentsFile									 AS tdf						WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
							ON	tdf.comp_id = ct.comp_id AND
								tdf.df_id	= ct.df_id
						LEFT JOIN dbo.tbCommercialTransactionsLoan							tctl					WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
							ON	tctl.comp_id		= ctct.comp_id			AND
								tctl.ct_transaction = ctct.ctct_transaction	AND
								tctl.ctl_id			= ctct.ctl_id
						WHERE 	ctct.ctct_guid	=	@guid									AND
								ttn.tax_class									= 1			AND	-- MOS 03-2022: estaban abajo y los pase arriba x LEF
								tdf.df_DisableExchangeDifferenceInterest		=   'False' AND
								VCTFS.sd_isInBalance							=	'True'	AND
							    -- MOS 09-2023: Lo saque para que tome en cta las NC a cuenta ahora aplicadas.    VCTFS.sd_isCredit								=	'False'	AND		-- MOS 02-2020, se pone el lutimo where x def deshab en updatedatabase
							    VCTFS.sd_isReceipt								=	'False'
						GROUP BY ttn.comp_id, ttn.tax_id, ttn.tax_id

			-- MOS 09-2022
			-- ATENCION: Dif de Cotizacvion sobre Saldos Iniciales o Comprobantes Importados sin tbTaxMovements.
			-- Si NO tiene tbTaxMovements NO calcula diferencia de cotizacion.  Si llega a hacer falta hay q poner otro insert que ponga los totales de ct_transactions sin el Inner  y verificando que sean saldos iniciales.

			-- MOS 09-2023:  INserta para Recibos a cuenta: NO debe insertar ya que un importe a cuenta debe tomar las proporciones de IVA de los cptes a los que aplica




--==
--SELECT 'tbCollection_ExchDiffTMPValues',* FROM tbCollection_ExchDiffTMPValues


			DECLARE @intACurrency AS INT
			SELECT 	@intACurrency = tc.curr_id
				FROM tbCustomer tc	WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @cust_id
			SET @decInterest4ExchDif = @decInterest4ExchDif * -1
			SET @decInterest4ExchDif = dbo.fnGetExchange2(	@comp_id,
															@decInterest4ExchDif,
															@intCurrID4ExchangeControl,
															@intACurrency,
															@forcedCurrId1,
															@forcedCurrId2,
															@exchange,
															'FALSE')

			-- MOS 09-2023
			SET @decInterest4ExchDifonAccountReceipt = @decInterest4ExchDifonAccountReceipt * -1
			SET @decInterest4ExchDifonAccountReceipt = dbo.fnGetExchange2(	@comp_id,
															@decInterest4ExchDifonAccountReceipt,
															@intCurrID4ExchangeControl,
															@intACurrency,
															@forcedCurrId1,
															@forcedCurrId2,
															@exchange,
															'FALSE')



			IF @decInterest4ExchDif < 0 AND @bitEnableInterest4CreditNote = 'False'
				BEGIN
					SET @decInterest4ExchDif = 0
				END

		END
	-- --------------------------------------------------------------------------


--==
--SELECT 'decInterest4ExchDif',@decInterest4ExchDif,'@decInterest4ExchDifonAccountReceipt',@decInterest4ExchDifonAccountReceipt


	-- --------------------------------------------------------------------------
	-- Recupera el Interes por MORA
	-- --------------------------------------------------------------------------

	DECLARE @decInterest4QuoteMora DECIMAL(19,2)
	SET		@decInterest4QuoteMora = 0
	SET		@decInterest4QuoteMora =
		isnull((select	convert(decimal(18,2),round(sum(round(ctct.ctct_total,@d) *
																ct.ct_ACurrencyExchange *
																CASE
																	WHEN
																		(
																			CASE
																				WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																				ELSE tctl.ctl_payDate
																			END < @processingDate
																		)
																			AND
																		(
																	   		(
																	   			DATEDIFF(DAY,	CASE
													   												WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
													   												ELSE tctl.ctl_payDate
													   											END,@processingDate
																	   					)
																   					-
																   				dbo.fngetDiasDePandemia2(CASE
																   											WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   											ELSE tctl.ctl_payDate
																   										END,
																   										@processingDate,
																										tdf.df_pandemyDaysFrom,
																										tdf.df_pandemyDaysTo)
																	   		)

																	   				>

													   										CASE
													   											WHEN tctl.comp_id IS NULL THEN	tst.st_collectionInterestFromDays
													   											ELSE							tst.st_collectionLoanInterestFromDays
													   										END
																		)
																			THEN
																				   (
																				   		(
																						CASE
																							WHEN tctl.comp_id IS NULL THEN tst.st_collectionInterest
																							ELSE tst.st_collectionLoanInterest
																						END
																						 / 30
																				   		)
																				   		*
																				   		(
																				   			DATEDIFF(DAY,	CASE
																   												WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   												ELSE tctl.ctl_payDate
																   											END,@processingDate)
																   								-
																   							dbo.fngetDiasDePandemia2(CASE
																   														WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   														ELSE tctl.ctl_payDate
																   													END,
																   													@processingDate,
																													tdf.df_pandemyDaysFrom,
																													tdf.df_pandemyDaysTo)
																   						)
																				   ) / 100
																	ELSE			0
																END
													),@d))
				from	dbo.tbCommercialTransactionsTmp							ctct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
				inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))
					on	VCTFS.comp_id					=	ctct.comp_id
					and VCTFS.ct_transaction			=	ctct.ctct_transaction
				-- MOS 03-2022, lo pase arriba y el join contra la tmp x LEF
				--inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
				--	on	VCTFS.comp_id					=	ct.comp_id
				--	and VCTFS.ct_transaction			=	ct.ct_transaction
				inner join dbo.tbCommercialTransactions							ct						WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
					on	ct.comp_id			= ctct.comp_id AND
						ct.ct_transaction	= ctct.ctct_transaction
				INNER JOIN dbo.tbSalesTerms tst																WITH (NOLOCK,INDEX(PK__tbSalesTerms__07C12930))
					ON	tst.comp_id = ct.comp_id AND
						tst.st_id	= ct.st_id
				INNER JOIN dbo.tbDocumentsFile									AS tdf						WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
					ON	tdf.comp_id = ct.comp_id	AND
						--tdf.bra_id	= ct.bra_id		AND    MOS 03-2022: NO POner x LEF ( Lentitud )
						tdf.df_id	= ct.df_id
				LEFT JOIN dbo.tbCommercialTransactionsLoan							tctl					WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
					ON	tctl.comp_id		= ctct.comp_id			AND
						tctl.ct_transaction = ctct.ctct_transaction	AND
						tctl.ctl_id			= ctct.ctl_id
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.sd_isInBalance				=	'True'
				and	    VCTFS.sd_isCredit					=	'False'
				and	    VCTFS.sd_isReceipt					=	'False'),0)

	-- --------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Si es que hay algun interes busca el documento asociado al debito
	-- y el articulo para poder generar el pedido
	-- si no lo encuentra pone el interes en CERO
	-- --------------------------------------------------------------------------
	DECLARE @df_Collection_Interest_Minimum AS DECIMAL(19,4)
	DECLARE @decInterestTaxes			AS DECIMAL(19,2)
	SET		@decInterestTaxes			= 0
	DECLARE @df_id4Interest				AS INT
	DECLARE @item_id4Interest			AS INT
	IF	@decInterest4QuoteMora				<> 0	OR
		@decInterest4PayLoanWithCreditCard	<> 0
		BEGIN
		-- no
			SELECT
			       @item_id4Interest				= tdf.df_Collection_item_id4InterestDebit,
			       @df_Collection_Interest_Minimum	= tdf.df_Collection_Interest_Minimum
				FROM dbo.tbDocumentsFile tdf				WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
				WHERE	tdf.comp_id = @comp_id AND
						tdf.df_id	= @df_id

			SELECT @df_id4Interest =  tdf.df_id
				FROM dbo.fnDocumentsFile_GetDocumentsForDebitCreditNotes(@comp_id, @bra_id, @cust_id) tdf
				INNER JOIN dbo.tbDocumentsFile tdf2			WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
					ON	tdf2.comp_id	= @comp_id AND
						tdf2.df_id		= tdf.df_id
				WHERE	--tdf.sd_isDebitNote						= 1		AND
					( -- MOS 10-2021 x q el NABO q lo hizo no tomo en cuenta si era NC o ND
						((@decInterest4QuoteMora + @decInterest4PayLoanWithCreditCard) > 0	AND tdf.sd_isDebitNote	= 'True')
							OR
						((@decInterest4QuoteMora + @decInterest4PayLoanWithCreditCard) <= 0	AND tdf.sd_isCreditNote = 'True')
					)													AND
						tdf.Is4ExchangeDifference				= 0		AND
						tdf2.df_Collection_Interest_isDebitNoteDocument = 1
				ORDER BY tdf.df_order



			-- Si NO estan configurados que NO calcule los Intereses !
			IF @df_id4Interest		IS NULL OR
			   @item_id4Interest	IS NULL
				BEGIN
					SET @decInterest4QuoteMora				= 0
					SET @decInterest4PayLoanWithCreditCard	= 0
				END

			-- Si el MINIMO INteres es mayor que lo calculado lo pone en CERO
			IF @df_Collection_Interest_Minimum > (@decInterest4QuoteMora + @decInterest4PayLoanWithCreditCard)
				BEGIN
					SET @decInterest4QuoteMora				= 0
					SET @decInterest4PayLoanWithCreditCard	= 0
				END



				DECLARE @decCoefAux AS DECIMAL(25,6)
				SET		@decCoefAux	  = dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id4Interest)

				SET @decInterestTaxes = (
											(
												@decInterest4QuoteMora
												+
												@decInterest4PayLoanWithCreditCard
											 )
										 * @decCoefAux
										)

										-

										(
											@decInterest4QuoteMora
											+
											@decInterest4PayLoanWithCreditCard
										 )


		END



--==
--SELECT 'decInterest4ExchDif',@decInterest4ExchDif,'@decInterest4ExchDifonAccountReceipt',@decInterest4ExchDifonAccountReceipt

	-- MOS 09-2023: Suma Dif Cot de Recibos a cuenta
	IF @decInterest4ExchDifonAccountReceipt <> 0
		BEGIN
			DECLARE @intItemID4ExchangeInterestRc AS INT
			SELECT	@intItemID4ExchangeInterestRc = tdf.item_idExchangeDifferenceInterest
				FROM tbDocumentsFile tdf				WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
				WHERE	tdf.comp_id = @comp_id AND
						tdf.df_id	= @df_id


			-- Le saco a @decInterest4ExchDifonAccountReceipt el IVA que le va a recargar la NC x Dif Cot
			SELECT @decInterest4ExchDifonAccountReceipt = @decInterest4ExchDifonAccountReceipt / dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @intItemID4ExchangeInterestRc))
			--SELECT 'coef',dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @intItemID4ExchangeInterestRc)

			IF @intItemID4ExchangeInterestRc IS NOT NULL
				BEGIN
					SET @decInterestTaxes	= @decInterestTaxes +  ( (@decInterest4ExchDifonAccountReceipt  * dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @intItemID4ExchangeInterestRc) - @decInterest4ExchDifonAccountReceipt) )
				END
		END




	-- Suma el impuesto por diferencia de cambio.
	IF @decInterest4ExchDif				<> 0
		BEGIN
		-- no
			DECLARE @intItemID4ExchangeInterest AS INT
			SELECT	@intItemID4ExchangeInterest = tdf.item_idExchangeDifferenceInterest
				FROM tbDocumentsFile tdf				WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
				WHERE	tdf.comp_id = @comp_id AND
						tdf.df_id	= @df_id
			IF @intItemID4ExchangeInterest IS NOT NULL
				BEGIN

					DECLARE @decTMPTotal AS DECIMAL(29,4)
					SET		@decTMPTotal = 0
					SELECT 	@decTMPTotal = SUM(tmp.Neto)
						FROM dbo.tbCollection_ExchDiffTMPValues tmp	WITH (NOLOCK)
						WHERE tmp.guid = @guid


--SELECT 'tbCollection_ExchDiffTMPValues',* FROM tbCollection_ExchDiffTMPValues

					SELECT @decInterestTaxes = @decInterestTaxes +	(
																		(tmp.Neto / dbo.fnNoZDiv(@decTMPTotal)) * @decInterest4ExchDif * ttn.tax_percentage / 100
																	)
						FROM dbo.tbCollection_ExchDiffTMPValues tmp	WITH (NOLOCK)
						INNER JOIN dbo.tbTaxName				ttn	WITH (NOLOCK)
							ON	ttn.comp_id = tmp.comp_id AND
								ttn.tax_id	= tmp.tax_id
						WHERE tmp.guid = @guid AND tmp.Neto IS NOT NULL AND tmp.IVA IS NOT NULL


					--SET @decInterestTaxes = @decInterestTaxes +  ( (@decInterest4ExchDif  * dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @intItemID4ExchangeInterest) - @decInterest4ExchDif) )
				END
			ELSE
				BEGIN
					SET @decInterest4ExchDif = 0
				END
		END
	-- --------------------------------------------------------------------------

	--SELECT '@decInterestTaxes',@decInterestTaxes


	-- Select General
	select

		isnull((select	convert(decimal(18,2),round(sum(round(ctct.[ctct_total],@d)			*
																ct.[ct_ACurrencyExchange]
													),@d))
				from	dbo.tbCommercialTransactionsTmp							ctct		WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
				inner join dbo.tbCommercialTransactions							ct			WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
					ON	ct.comp_id			= ctct.comp_id				AND
						ct.ct_transaction	= ctct.ctct_transaction
				inner join dbo.vwCommercialTransactions_forSales				VCTFS		WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))
					on	VCTFS.comp_id					=	ct.comp_id
					and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.sd_isInBalance				=	'True'
				and	    VCTFS.sd_isCredit					=	'False'
				and	    VCTFS.sd_isReceipt				=	'False'),0)							[totalCustomer],



		isnull((select	convert(decimal(18,2),sum(round(dbo.fnGetExchange2(ct.comp_id,
																			ctct.ctct_total,
																			ct.ct_ACurrency,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	dbo.tbCommercialTransactionsTmp								ctct		WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
						INNER  JOIN  dbo.tbCommercialTransactions					ct			WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
						ON	ct.comp_id			= ctct.comp_id				AND
							ct.ct_transaction	= ctct.ctct_transaction
						INNER  JOIN  dbo.vwCommercialTransactions_forSales			VCTFS		WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))
						on	VCTFS.comp_id					=	ct.comp_id
						--and VCTFS.bra_id					=	ct.bra_id
						and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid			AND
						ctct.ctct_isSaleOrderPreCollection = 'False'		-- MOS 04-2024: Porque sino, por como el HDRMP hizo esta mierda usando el mismo campo de ct_trans para trans y pedidos, si justo habia un ct_trans con el mismo numero de pedido lo tomaba como a cobrar en subtotal.
				and     VCTFS.sd_isInBalance				=	'True'
				and	    VCTFS.sd_isCredit					=	'False'
				and	    VCTFS.sd_isReceipt				=	'False'),0)							[totalPay],



		isnull((select  convert(decimal(18,2),sum(round(dbo.fnGetExchange2(@comp_id,
																			vct.amount,
																			vct.curr_id,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	vwCollectionTmp												vct		WITH (NOLOCK)
				where	vct.guid		=	@guid AND
						vct.lang_id		= @lang_id),0)												[totalHow],



		isnull((select	convert(decimal(18,2),sum(round(dbo.fnGetExchange2(tmt.comp_id,
																			tmt.tmt_total,
																			tmt.curr_id,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	dbo.tbTaxMovementsTmp										tmt		WITH (NOLOCK)
				where	tmt.tmt_guid	=	@guid),0)												[totalRetention],



		isnull((select  convert(decimal(18,2),sum(round(dbo.fnGetExchange2(ctct.comp_id,
																		   ctct.ctct_total,
																		   ct.curr_id_transaction,
																		   ct.ct_ACurrency,
																		   ct.curr_id_transaction,
																		   ct.ct_ACurrency,
																		   ctct.ctct_exchange,
																		   'FALSE')
														,@d)))
				from	dbo.tbCommercialTransactionsTmp								ctct	WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
						INNER  JOIN  dbo.tbCommercialTransactions					ct		WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
						ON	ct.comp_id			= ctct.comp_id				AND
							ct.ct_transaction	= ctct.ctct_transaction
						INNER  JOIN  dbo.vwCommercialTransactions_PaymentOnAccount	VCTFS	WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_PaymentOnAccount)) -- WITH (NOLOCK) MOS 08-2023
						on	VCTFS.comp_id					=	ct.comp_id
						and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid AND
						ctct.ctct_isSaleOrderPreCollection = 'False'	-- MOS 04-2024: x q sino tomaba los pedidos seleccionados a cuenta en cobranzas que no se quien fue el reverendo hijo de recontra re mil reputas q puso el id de saleorder dentro de el campo de ctct_transaction
																	),0)							[totalOnAccount],

		isnull((select  convert(decimal(18,2),sum(round(ctct.ctct_total,@d)))
				from	dbo.tbCommercialTransactionsTmp	ctct			WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
				where	ctct.ctct_guid			=	@guid
				AND		upper(ctct.ctct_origin)	=	'S'),0)											[totalACta],
		@decInterest4QuoteMora																		[totalInterest]	,
		isnull((select	convert(decimal(18,2),round(sum(
												   		DATEDIFF(DAY,	CASE
								   											WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
								   											ELSE tctl.ctl_payDate
								   										END,@processingDate
												   		        )
														)
												,@d)
								)
				from	dbo.tbCommercialTransactionsTmp									ctct		WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
				inner join dbo.vwCommercialTransactions_forSales				VCTFS				WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))		-- MOS 03-2022 x LEF
					on	VCTFS.comp_id					=	ctct.comp_id
					and VCTFS.ct_transaction			=	ctct.ctct_transaction
				inner join dbo.tbCommercialTransactions							ct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
					ON	ct.comp_id			= ctct.comp_id				AND
						ct.ct_transaction = ctct.ctct_transaction
				INNER JOIN dbo.tbSalesTerms tst														WITH (NOLOCK,INDEX(PK__tbSalesTerms__07C12930))
					ON	tst.comp_id			= ct.comp_id AND
						tst.st_id			= ct.st_id

				--inner join dbo.vwCommercialTransactions_forSales				VCTFS				WITH (NOLOCK)
				--	on	VCTFS.comp_id					=	ct.comp_id
				--	--and VCTFS.bra_id					=	ct.bra_id
				--	and VCTFS.ct_transaction			=	ct.ct_transaction
				LEFT JOIN dbo.tbCommercialTransactionsLoan							tctl			WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
					ON	tctl.comp_id		= ctct.comp_id			AND
						tctl.ct_transaction = ctct.ctct_transaction	AND
						tctl.ctl_id			= ctct.ctl_id
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.sd_isInBalance				=	'True'
				and	    VCTFS.sd_isCredit					=	'False'
				and	    VCTFS.sd_isReceipt					=	'False'
		),0)																							[moraDays],
		@decInterest4PayLoanWithCreditCard																[Interest4PayLoanWithCreditCard],
		@decInterestTaxes																				[InterestTaxes],
		@decInterest4ExchDif +
		ISNULL(@decInterest4ExchDifonAccountReceipt,0)	-- MOS 09-2023
																										[InterestExchangeDifference]


END
GO


create  PROCEDURE [dbo].[spCollection_getTotalsV2Old]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@cust_id			int,
	@forcedCurrId1		INT,
	@forcedCurrId2		INT,
	@exchange			decimal(30,10),
	@guid				UNIQUEIDENTIFIER,
	@df_id				INT,
	@prof_id			INT,
	@user_id			INT
)	--   with Recompile    NO, pone re lento todo ya que recompila cada puta vez q entra aca.
AS


BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED

	-- MOS 03-2022.   Puede ser peligroso dejar esto aca.  x tema LEF
	--SET LOCK_TIMEOUT 500
	--SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------
	/*
	declare	@comp_id	int,
			@lang_id	int,
			@bra_id		int,
			@cust_id	int,
			@forcedCurrId1  AS INT,
			@forcedCurrId2  AS INT,
			@exchange	decimal(19,6),
			@guid		uniqueidentifier,
			@df_id		INT
	select	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@cust_id	= 44708,
			@forcedCurrId1  =1,
			@forcedCurrId2  =1,
			@exchange	= 1,
			@guid		= 'CEC8C54C-1E09-4E2A-882B-49A76BC60754',
			@df_id		= 8
	*/
	-- --------------------------------------------------------------------------


	SET NOCOUNT		ON
	SET DATEFORMAT	YMD



	DECLARE @d INT = 2	-- FORROOOOOOOO


	-- --------------------------------------------------------------------------
	/*** recuperar la moneda de la sucursal pasada como parametro
			(sucursal de donde se ejecuta la consulta)****/
	-- --------------------------------------------------------------------------
	DECLARE @bra_curr_id	INT	= null
	DECLARE @processingDate AS DATETIME
	select	@bra_curr_id	= b.curr_id,
			@processingDate = b.bra_processingDate
		from	dbo.tbBranch b			WITH (NOLOCK)
		where	b.comp_id	= @comp_id AND
				b.bra_id	= @bra_id
	-- --------------------------------------------------------------------------



	/*** recuperar la moneda del cliente pasada como parametro 		****/
	DECLARE @cust_curr_id	INT = NULL

	-- MOS 04-2022
	SELECT	@cust_curr_id =	b.curr_id
		FROM 	dbo.tbCustomer b	WITH (NOLOCK)
		WHERE 	b.comp_id = @comp_id	AND
				b.cust_id = @cust_id
	IF @cust_curr_id IS NULL SET @cust_curr_id = @bra_curr_id

	--set		@cust_curr_id = ISNULL((select	b.curr_id
	--									from	dbo.tbCustomer b	WITH (NOLOCK)
	--									where	b.comp_id = @comp_id	AND
	--											b.cust_id = @cust_id)
	--								,@bra_curr_id)



	-- --------------------------------------------------------------------------
	-- Recupera el Interes si se pagan CUOTAS con Tarjeta de Credito
	-- --------------------------------------------------------------------------
	DECLARE @decInterest4PayLoanWithCreditCard AS DECIMAL(19,2)
	SET		@decInterest4PayLoanWithCreditCard = 0
	DECLARE @decPercent4PayLoanWithCreditCard AS DECIMAL(19,2)
	SET		@decPercent4PayLoanWithCreditCard = 0

	SELECT	@decPercent4PayLoanWithCreditCard  = MAX(IsNull(tcclp.ccp_percentage4QuotePay,0)),
			@decInterest4PayLoanWithCreditCard = SUM(ISNULL(tctm.ctct_total,0))
		FROM dbo.tbCreditCardMovementsTmp tmp				WITH (NOLOCK)
		INNER JOIN dbo.tbCreditCardLoanPlan tcclp			WITH (NOLOCK)
		ON	tcclp.comp_id	= tmp.comp_id	AND
			tcclp.cc_id		= tmp.cc_id		AND
			tcclp.ccp_id	= tmp.ccp_id
		INNER JOIN dbo.tbCommercialTransactionsTmp	tctm	WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
			ON tctm.ctct_guid	= tmp.ccmt_guid
		WHERE	tmp.ccmt_guid	= @guid AND
				tctm.ctl_id IS NOT NULL
		GROUP BY tmp.ccmt_guid

	SET @decInterest4PayLoanWithCreditCard = @decInterest4PayLoanWithCreditCard * @decPercent4PayLoanWithCreditCard / 100

	-- --------------------------------------------------------------------------


	-- --------------------------------------------------------------------------
	-- Recupera el Interes por diferencia de cotizacion
	-- --------------------------------------------------------------------------
	DECLARE @decInterest4ExchDif   DECIMAL(19,2)
	SET		@decInterest4ExchDif   = 0
	DECLARE @bitEnableInterest4CreditNote	AS BIT = 'False'
	DECLARE @intCurrID4ExchangeControl		AS INT
	SELECT 	@intCurrID4ExchangeControl =	CASE
												WHEN	tb.curr_id = tc.curr_id									AND
														tdf.curr_id4ExchangeDifferenceInterest IS NOT NULL		AND
														tdf.curr_id4ExchangeDifferenceInterest <> tb.curr_id		THEN	tdf.curr_id4ExchangeDifferenceInterest
												ELSE																	NULL
											END,
			@bitEnableInterest4CreditNote = ISNULL(df_enableExchangeDifferenceInterestCN,'False')
		FROM dbo.tbDocumentsFile tdf			WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
		INNER JOIN dbo.tbbranch tb				WITH (NOLOCK)
			ON	tb.comp_id	= tdf.comp_id	AND
				tb.bra_id	= tdf.bra_id
		INNER JOIN dbo.tbcustomer tc			WITH (NOLOCK)
			ON	tc.comp_id	= @comp_id AND
				tc.cust_id	= @cust_id
		WHERE	tdf.comp_id = @comp_id AND
				tdf.df_id	= @df_id



	IF @intCurrID4ExchangeControl IS NOT NULL
		BEGIN
		-- no
			-- --------------------------------------------------------------------------------
			-- MOS 06-01-2021, Fiesa, se calcula el NETO SIN percepciones ni II
			-- --------------------------------------------------------------------------------
			DECLARE @tblCoeficient4Neto TABLE(ct_transaction INT PRIMARY KEY,
											  coeficient DECIMAL(38,15))

			INSERT INTO @tblCoeficient4Neto
			(
				ct_transaction,
				coeficient
			)
				SELECT	ct.ct_transaction,
						 dbo.fnNoZDiv(	(
						 					ct.ct_total - ISNULL(
						 											(	SELECT SUM(ttm.tm_total)
						 					               					FROM		dbo.tbTaxMovements	AS ttm	WITH (NOLOCK)
						 					               					INNER JOIN	dbo.tbTaxName		AS ttn	WITH (NOLOCK)
						 					               					ON	ttn.tax_id	= ttm.tax_id					AND
						 					               						ttn.comp_id = ttm.comp_id
						 					               					WHERE	ttm.comp_id			= ct.comp_id		AND
						 					               							ttm.ct_transaction	= ct.ct_transaction AND
						 					               							ttn.tax_class		<> 1
						 											)
						 									   ,0)
										) / dbo.fnNoZDiv(ct.ct_subtotal - ISNULL(ct.ct_discount,0)))	-- MOS 02-2022 x FIESA y sus descuentos   - ISNULL(ct.ct_discount,0)
					FROM 	dbo.tbCommercialTransactionsTmp							ctct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
					inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))	-- MOS 03-2022 x LEF
						on	VCTFS.comp_id					=	ctct.comp_id
						and VCTFS.ct_transaction			=	ctct.ctct_transaction
					inner join dbo.tbCommercialTransactions							ct						WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
						on	ct.comp_id			= ctct.comp_id AND
							ct.ct_transaction   = ctct.ctct_transaction
					INNER JOIN dbo.tbDocumentsFile									tdf						WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
						ON	tdf.comp_id = ct.comp_id AND
							tdf.df_id	= ct.df_id
					LEFT JOIN dbo.tbCommercialTransactionsLoan						tctl					WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
						ON	tctl.comp_id		= ctct.comp_id			AND
							tctl.ct_transaction = ctct.ctct_transaction	AND
							tctl.ctl_id			= ctct.ctl_id
					where	ctct.ctct_guid	=	@guid
					AND tdf.df_DisableExchangeDifferenceInterest	=   'False'
					AND ct.ct_DisableExchangeDifferenceInterest		=   'False'	-- MOS 03-2022, estaban abajo y los puse arriba x LEF
					and     VCTFS.sd_isInBalance					=	'True'
					and	    VCTFS.sd_isCredit						=	'False' -- MOS 02-2020, se pone el lutimo where x def deshab en updatedatabase
					and	    VCTFS.sd_isReceipt						=	'False'
			-- --------------------------------------------------------------------------------


--==
--SELECT * FROM @tblCoeficient4Neto

			SET		@decInterest4ExchDif   =	ISNULL(
														(
															SELECT
																SUM(
																	(
																		dbo.fnGetExchange2(	ct.comp_id,
																							ctct.ctct_total,
																							ct.ct_ACurrency,
																							@intCurrID4ExchangeControl,
																							@forcedCurrId1,
																							@forcedCurrId2,
																							@exchange,
																							'FALSE')
																		-
																		dbo.fnGetExchange2(	ct.comp_id,
																							ctct.ctct_total,
																							ct.ct_ACurrency,
																							@intCurrID4ExchangeControl,
																							ct.curr_id4Exchange,
																							ct.curr_id_transaction,
																							ct.ct_curr_IdExchange,
																							0)
																	)

																		/

																		CASE
																			WHEN cfn.coeficient IS NULL THEN	dbo.fnNoZDiv(ct.ct_total / dbo.fnNoZDiv(ct.ct_subtotal - ISNULL(ct.ct_discount,0)))     -- MOS 02-2022 x FIESA y sus descuentos   - ISNULL(ct.ct_discount,0)
																			ELSE								dbo.fnNoZDiv(cfn.coeficient)
																		END
																	    --MOS 06-01-2021 Fiesa dbo.fnNoZDiv(ct.ct_total / dbo.fnNoZDiv(ct.ct_subtotal))

																   )

																from	dbo.tbCommercialTransactionsTmp							ctct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
																INNER JOIN @tblCoeficient4Neto									cfn
																	ON cfn.ct_transaction = ctct.ctct_transaction
																inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))	-- MOS 03-2022 mas arriba  x LEF
																	on	VCTFS.comp_id					=	ctct.comp_id
																	and VCTFS.ct_transaction			=	ctct.ctct_transaction
																inner join dbo.tbCommercialTransactions							ct						WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
																	on	ct.comp_id			= ctct.comp_id AND
																		ct.ct_transaction	= ctct.ctct_transaction
																INNER JOIN dbo.tbDocumentsFile									 AS tdf					WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
																	ON	tdf.comp_id = ct.comp_id AND
																		tdf.df_id	= ct.df_id
																INNER JOIN dbo.tbSalesTerms tst															WITH (NOLOCK,INDEX(PK__tbSalesTerms__07C12930))
																	ON	tst.st_id	= ct.st_id AND
																		tst.comp_id = ct.comp_id
																--inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
																--	on	VCTFS.comp_id					=	ct.comp_id
																--	--and VCTFS.bra_id					=	ct.bra_id
																--	and VCTFS.ct_transaction			=	ct.ct_transaction
																LEFT JOIN dbo.tbCommercialTransactionsLoan							tctl				WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
																	ON	tctl.comp_id		= ctct.comp_id			AND
																		tctl.ct_transaction = ctct.ctct_transaction	AND
																		tctl.ctl_id			= ctct.ctl_id
																WHERE 	ctct.ctct_guid						=	@guid
																AND tdf.df_DisableExchangeDifferenceInterest=   'False'	-- MOS 03-2022: Estaba abajo y lo pase arriba x lef
																and     VCTFS.sd_isInBalance				=	'True'
																and	    VCTFS.sd_isCredit					=	'False' -- MOS 02-2020, se pone el lutimo where x def deshab en updatedatabase
																and	    VCTFS.sd_isReceipt					=	'False'

														)
													,0)



--==
--SELECT @decInterest4ExchDif

			DELETE FROM tbCollection_ExchDiffTMPValues	WHERE [guid] = @guid
			INSERT INTO tbCollection_ExchDiffTMPValues(	[guid],
														comp_id,
														tax_id,
														Neto,
														IVA,
														Coef)

					SELECT		@guid,
								ttn.comp_id,
								ttn.tax_id,
								SUM(ttm.tm_subtotal)			[Neto],
								SUM(ttm.tm_total)				[Iva],
								0

						from	dbo.tbCommercialTransactionsTmp							ctct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
						inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))	-- MOS 03-2022 mas arriba x LEF
							on	VCTFS.comp_id					=	ctct.comp_id
							and VCTFS.ct_transaction			=	ctct.ctct_transaction
						inner join dbo.tbCommercialTransactions							ct						WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
							on	ct.comp_id			= ctct.comp_id AND
								ct.ct_transaction	= ctct.ctct_transaction
						--inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
						--	on	VCTFS.comp_id					=	ct.comp_id
						--	--and VCTFS.bra_id					=	ct.bra_id
						--	and VCTFS.ct_transaction			=	ct.ct_transaction
						INNER JOIN dbo.tbTaxMovements ttm															WITH (NOLOCK)
							ON	ttm.comp_id			= ct.comp_id AND
								ttm.ct_transaction	= ct.ct_transaction
						INNER JOIN dbo.tbTaxName ttn																WITH (NOLOCK)
							ON	ttn.comp_id = ttm.comp_id AND
								ttn.tax_id	= ttm.tax_id
						INNER JOIN dbo.tbSalesTerms tst																WITH (NOLOCK,INDEX(PK__tbSalesTerms__07C12930))
							ON	tst.st_id	= ct.st_id AND
								tst.comp_id = ct.comp_id
						INNER JOIN dbo.tbDocumentsFile									 AS tdf						WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
							ON	tdf.comp_id = ct.comp_id AND
								tdf.df_id	= ct.df_id
						LEFT JOIN dbo.tbCommercialTransactionsLoan							tctl					WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
							ON	tctl.comp_id		= ctct.comp_id			AND
								tctl.ct_transaction = ctct.ctct_transaction	AND
								tctl.ctl_id			= ctct.ctl_id
						WHERE 	ctct.ctct_guid	=	@guid									AND
								ttn.tax_class									= 1			AND	-- MOS 03-2022: estaban abajo y los pase arriba x LEF
								tdf.df_DisableExchangeDifferenceInterest		=   'False' AND
								VCTFS.sd_isInBalance							=	'True'	AND
							    VCTFS.sd_isCredit								=	'False'	AND		-- MOS 02-2020, se pone el lutimo where x def deshab en updatedatabase
							    VCTFS.sd_isReceipt								=	'False'
						GROUP BY ttn.comp_id, ttn.tax_id, ttn.tax_id

			-- MOS 09-2022
			-- ATENCION: Dif de Cotizacvion sobre Saldos Iniciales o Comprobantes Importados sin tbTaxMovements.
			-- Si NO tiene tbTaxMovements NO calcula diferencia de cotizacion.  Si llega a hacer falta hay q poner otro insert que ponga los totales de ct_transactions sin el Inner  y verificando que sean saldos iniciales.






			DECLARE @intACurrency AS INT
			SELECT 	@intACurrency = tc.curr_id
				FROM tbCustomer tc	WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @cust_id
			SET @decInterest4ExchDif = @decInterest4ExchDif * -1
			SET @decInterest4ExchDif = dbo.fnGetExchange2(	@comp_id,
															@decInterest4ExchDif,
															@intCurrID4ExchangeControl,
															@intACurrency,
															@forcedCurrId1,
															@forcedCurrId2,
															@exchange,
															'FALSE')

			IF @decInterest4ExchDif < 0 AND @bitEnableInterest4CreditNote = 'False'
				BEGIN
					SET @decInterest4ExchDif = 0
				END

		END
	-- --------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Recupera el Interes por MORA
	-- --------------------------------------------------------------------------

	DECLARE @decInterest4QuoteMora DECIMAL(19,2)
	SET		@decInterest4QuoteMora = 0
	SET		@decInterest4QuoteMora =
		isnull((select	convert(decimal(18,2),round(sum(round(ctct.ctct_total,@d) *
																ct.ct_ACurrencyExchange *
																CASE
																	WHEN
																		(
																			CASE
																				WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																				ELSE tctl.ctl_payDate
																			END < @processingDate
																		)
																			AND
																		(
																	   		(
																	   			DATEDIFF(DAY,	CASE
													   												WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
													   												ELSE tctl.ctl_payDate
													   											END,@processingDate
																	   					)
																   					-
																   				dbo.fngetDiasDePandemia2(CASE
																   											WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   											ELSE tctl.ctl_payDate
																   										END,
																   										@processingDate,
																										tdf.df_pandemyDaysFrom,
																										tdf.df_pandemyDaysTo)
																	   		)

																	   				>

													   										CASE
													   											WHEN tctl.comp_id IS NULL THEN	tst.st_collectionInterestFromDays
													   											ELSE							tst.st_collectionLoanInterestFromDays
													   										END
																		)
																			THEN
																				   (
																				   		(
																						CASE
																							WHEN tctl.comp_id IS NULL THEN tst.st_collectionInterest
																							ELSE tst.st_collectionLoanInterest
																						END
																						 / 30
																				   		)
																				   		*
																				   		(
																				   			DATEDIFF(DAY,	CASE
																   												WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   												ELSE tctl.ctl_payDate
																   											END,@processingDate)
																   								-
																   							dbo.fngetDiasDePandemia2(CASE
																   														WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   														ELSE tctl.ctl_payDate
																   													END,
																   													@processingDate,
																													tdf.df_pandemyDaysFrom,
																													tdf.df_pandemyDaysTo)
																   						)
																				   ) / 100
																	ELSE			0
																END
													),@d))
				from	dbo.tbCommercialTransactionsTmp							ctct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
				inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))
					on	VCTFS.comp_id					=	ctct.comp_id
					and VCTFS.ct_transaction			=	ctct.ctct_transaction
				-- MOS 03-2022, lo pase arriba y el join contra la tmp x LEF
				--inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
				--	on	VCTFS.comp_id					=	ct.comp_id
				--	and VCTFS.ct_transaction			=	ct.ct_transaction
				inner join dbo.tbCommercialTransactions							ct						WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
					on	ct.comp_id			= ctct.comp_id AND
						ct.ct_transaction	= ctct.ctct_transaction
				INNER JOIN dbo.tbSalesTerms tst																WITH (NOLOCK,INDEX(PK__tbSalesTerms__07C12930))
					ON	tst.comp_id = ct.comp_id AND
						tst.st_id	= ct.st_id
				INNER JOIN dbo.tbDocumentsFile									AS tdf						WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
					ON	tdf.comp_id = ct.comp_id	AND
						--tdf.bra_id	= ct.bra_id		AND    MOS 03-2022: NO POner x LEF ( Lentitud )
						tdf.df_id	= ct.df_id
				LEFT JOIN dbo.tbCommercialTransactionsLoan							tctl					WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
					ON	tctl.comp_id		= ctct.comp_id			AND
						tctl.ct_transaction = ctct.ctct_transaction	AND
						tctl.ctl_id			= ctct.ctl_id
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.sd_isInBalance				=	'True'
				and	    VCTFS.sd_isCredit					=	'False'
				and	    VCTFS.sd_isReceipt					=	'False'),0)

	-- --------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Si es que hay algun interes busca el documento asociado al debito
	-- y el articulo para poder generar el pedido
	-- si no lo encuentra pone el interes en CERO
	-- --------------------------------------------------------------------------
	DECLARE @df_Collection_Interest_Minimum AS DECIMAL(19,4)
	DECLARE @decInterestTaxes			AS DECIMAL(19,2)
	SET		@decInterestTaxes			= 0
	DECLARE @df_id4Interest				AS INT
	DECLARE @item_id4Interest			AS INT
	IF	@decInterest4QuoteMora				<> 0	OR
		@decInterest4PayLoanWithCreditCard	<> 0
		BEGIN
		-- no
			SELECT
			       @item_id4Interest				= tdf.df_Collection_item_id4InterestDebit,
			       @df_Collection_Interest_Minimum	= tdf.df_Collection_Interest_Minimum
				FROM dbo.tbDocumentsFile tdf				WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
				WHERE	tdf.comp_id = @comp_id AND
						tdf.df_id	= @df_id

			SELECT @df_id4Interest =  tdf.df_id
				FROM dbo.fnDocumentsFile_GetDocumentsForDebitCreditNotes(@comp_id, @bra_id, @cust_id) tdf
				INNER JOIN dbo.tbDocumentsFile tdf2			WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
					ON	tdf2.comp_id	= @comp_id AND
						tdf2.df_id		= tdf.df_id
				WHERE	--tdf.sd_isDebitNote						= 1		AND
					( -- MOS 10-2021 x q el NABO q lo hizo no tomo en cuenta si era NC o ND
						((@decInterest4QuoteMora + @decInterest4PayLoanWithCreditCard) > 0	AND tdf.sd_isDebitNote	= 'True')
							OR
						((@decInterest4QuoteMora + @decInterest4PayLoanWithCreditCard) <= 0	AND tdf.sd_isCreditNote = 'True')
					)													AND
						tdf.Is4ExchangeDifference				= 0		AND
						tdf2.df_Collection_Interest_isDebitNoteDocument = 1
				ORDER BY tdf.df_order



			-- Si NO estan configurados que NO calcule los Intereses !
			IF @df_id4Interest		IS NULL OR
			   @item_id4Interest	IS NULL
				BEGIN
					SET @decInterest4QuoteMora				= 0
					SET @decInterest4PayLoanWithCreditCard	= 0
				END

			-- Si el MINIMO INteres es mayor que lo calculado lo pone en CERO
			IF @df_Collection_Interest_Minimum > (@decInterest4QuoteMora + @decInterest4PayLoanWithCreditCard)
				BEGIN
					SET @decInterest4QuoteMora				= 0
					SET @decInterest4PayLoanWithCreditCard	= 0
				END



				DECLARE @decCoefAux AS DECIMAL(25,6)
				SET		@decCoefAux	  = dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id4Interest)

				SET @decInterestTaxes = (
											(
												@decInterest4QuoteMora
												+
												@decInterest4PayLoanWithCreditCard
											 )
										 * @decCoefAux
										)

										-

										(
											@decInterest4QuoteMora
											+
											@decInterest4PayLoanWithCreditCard
										 )


		END



	-- Suma el impuesto por diferencia de cambio.
	IF @decInterest4ExchDif				<> 0
		BEGIN
		-- no
			DECLARE @intItemID4ExchangeInterest AS INT
			SELECT	@intItemID4ExchangeInterest = tdf.item_idExchangeDifferenceInterest
				FROM tbDocumentsFile tdf				WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
				WHERE	tdf.comp_id = @comp_id AND
						tdf.df_id	= @df_id
			IF @intItemID4ExchangeInterest IS NOT NULL
				BEGIN

					DECLARE @decTMPTotal AS DECIMAL(29,4)
					SET		@decTMPTotal = 0
					SELECT 	@decTMPTotal = SUM(tmp.Neto)
						FROM dbo.tbCollection_ExchDiffTMPValues tmp	WITH (NOLOCK)
						WHERE tmp.guid = @guid

					SELECT @decInterestTaxes = @decInterestTaxes +	(
																		(tmp.Neto / dbo.fnNoZDiv(@decTMPTotal)) * @decInterest4ExchDif * ttn.tax_percentage / 100
																	)
						FROM dbo.tbCollection_ExchDiffTMPValues tmp	WITH (NOLOCK)
						INNER JOIN dbo.tbTaxName				ttn	WITH (NOLOCK)
							ON	ttn.comp_id = tmp.comp_id AND
								ttn.tax_id	= tmp.tax_id
						WHERE tmp.guid = @guid


					--SET @decInterestTaxes = @decInterestTaxes +  ( (@decInterest4ExchDif  * dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @intItemID4ExchangeInterest) - @decInterest4ExchDif) )
				END
			ELSE
				BEGIN
					SET @decInterest4ExchDif = 0
				END
		END
	-- --------------------------------------------------------------------------




	-- Select General
	select

		isnull((select	convert(decimal(18,2),round(sum(round(ctct.[ctct_total],@d)			*
																ct.[ct_ACurrencyExchange]
													),@d))
				from	dbo.tbCommercialTransactionsTmp							ctct		WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
				inner join dbo.tbCommercialTransactions							ct			WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
					ON	ct.comp_id			= ctct.comp_id				AND
						ct.ct_transaction	= ctct.ctct_transaction
				inner join dbo.vwCommercialTransactions_forSales				VCTFS		WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))
					on	VCTFS.comp_id					=	ct.comp_id
					and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.sd_isInBalance				=	'True'
				and	    VCTFS.sd_isCredit					=	'False'
				and	    VCTFS.sd_isReceipt				=	'False'),0)							[totalCustomer],



		isnull((select	convert(decimal(18,2),sum(round(dbo.fnGetExchange2(ct.comp_id,
																			ctct.ctct_total,
																			ct.ct_ACurrency,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	dbo.tbCommercialTransactionsTmp								ctct		WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
						INNER  JOIN  dbo.tbCommercialTransactions					ct			WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
						ON	ct.comp_id			= ctct.comp_id				AND
							ct.ct_transaction	= ctct.ctct_transaction
						INNER  JOIN  dbo.vwCommercialTransactions_forSales			VCTFS		WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))
						on	VCTFS.comp_id					=	ct.comp_id
						--and VCTFS.bra_id					=	ct.bra_id
						and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.sd_isInBalance				=	'True'
				and	    VCTFS.sd_isCredit					=	'False'
				and	    VCTFS.sd_isReceipt				=	'False'),0)							[totalPay],



		isnull((select  convert(decimal(18,2),sum(round(dbo.fnGetExchange2(@comp_id,
																			vct.amount,
																			vct.curr_id,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	vwCollectionTmp												vct		WITH (NOLOCK)
				where	vct.guid		=	@guid AND
						vct.lang_id		= @lang_id),0)												[totalHow],



		isnull((select	convert(decimal(18,2),sum(round(dbo.fnGetExchange2(tmt.comp_id,
																			tmt.tmt_total,
																			tmt.curr_id,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	dbo.tbTaxMovementsTmp										tmt		WITH (NOLOCK)
				where	tmt.tmt_guid	=	@guid),0)												[totalRetention],



		isnull((select  convert(decimal(18,2),sum(round(dbo.fnGetExchange2(ctct.comp_id,
																		   ctct.ctct_total,
																		   ct.curr_id_transaction,
																		   ct.ct_ACurrency,
																		   ct.curr_id_transaction,
																		   ct.ct_ACurrency,
																		   ctct.ctct_exchange,
																		   'FALSE')
														,@d)))
				from	dbo.tbCommercialTransactionsTmp								ctct	WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
						INNER  JOIN  dbo.tbCommercialTransactions					ct		WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
						ON	ct.comp_id			= ctct.comp_id				AND
							ct.ct_transaction	= ctct.ctct_transaction
						INNER  JOIN  dbo.vwCommercialTransactions_PaymentOnAccount	VCTFS	WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_PaymentOnAccount)) -- WITH (NOLOCK) MOS 08-2023
						on	VCTFS.comp_id					=	ct.comp_id
						and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid),0)												[totalOnAccount],

		isnull((select  convert(decimal(18,2),sum(round(ctct.ctct_total,@d)))
				from	dbo.tbCommercialTransactionsTmp	ctct			WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
				where	ctct.ctct_guid			=	@guid
				AND		upper(ctct.ctct_origin)	=	'S'),0)											[totalACta],
		@decInterest4QuoteMora																		[totalInterest]	,
		isnull((select	convert(decimal(18,2),round(sum(
												   		DATEDIFF(DAY,	CASE
								   											WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
								   											ELSE tctl.ctl_payDate
								   										END,@processingDate
												   		        )
														)
												,@d)
								)
				from	dbo.tbCommercialTransactionsTmp									ctct		WITH (NOLOCK,INDEX(IX_tbCommercialTransactionsTmp_4ctct_guidV2))
				inner join dbo.vwCommercialTransactions_forSales				VCTFS				WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forSalesII))		-- MOS 03-2022 x LEF
					on	VCTFS.comp_id					=	ctct.comp_id
					and VCTFS.ct_transaction			=	ctct.ctct_transaction
				inner join dbo.tbCommercialTransactions							ct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))
					ON	ct.comp_id			= ctct.comp_id				AND
						ct.ct_transaction = ctct.ctct_transaction
				INNER JOIN dbo.tbSalesTerms tst														WITH (NOLOCK,INDEX(PK__tbSalesTerms__07C12930))
					ON	tst.comp_id			= ct.comp_id AND
						tst.st_id			= ct.st_id

				--inner join dbo.vwCommercialTransactions_forSales				VCTFS				WITH (NOLOCK)
				--	on	VCTFS.comp_id					=	ct.comp_id
				--	--and VCTFS.bra_id					=	ct.bra_id
				--	and VCTFS.ct_transaction			=	ct.ct_transaction
				LEFT JOIN dbo.tbCommercialTransactionsLoan							tctl			WITH (NOLOCK,INDEX(PK_tbCommercialTransactionsLoan_1))
					ON	tctl.comp_id		= ctct.comp_id			AND
						tctl.ct_transaction = ctct.ctct_transaction	AND
						tctl.ctl_id			= ctct.ctl_id
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.sd_isInBalance				=	'True'
				and	    VCTFS.sd_isCredit					=	'False'
				and	    VCTFS.sd_isReceipt					=	'False'
		),0)																							[moraDays],
		@decInterest4PayLoanWithCreditCard																[Interest4PayLoanWithCreditCard],
		@decInterestTaxes																				[InterestTaxes],
		@decInterest4ExchDif																			[InterestExchangeDifference]


END
GO



CREATE PROCEDURE [dbo].[spCollection_insertApplicationByCTTransaction]
(
	@comp_id						int,
	@intCollectionTransaction		int,
	@intCCV_ID						INT
)
as

BEGIN


	-- ---------------------------------------------------
	-- Testing
	-- ---------------------------------------------------
	/*
	DECLARE 	@comp_id						INT = 1,
				@intCollectionTransaction		INT	= 23363438,
				@intCCV_ID						INT = 139
	*/
	-- ---------------------------------------------------





	SET NOCOUNT ON

	DECLARE @bra_id				  AS INT
	DECLARE @curr_id			  AS INT
	DECLARE @decCollectionBalance AS DECIMAL(19,4)	= 0
	DECLARE @decInvoiceBalance    AS DECIMAL(19,4)	= 0
	DECLARE @decInvoiceTotal      AS DECIMAL(19,4)  = 0
	DECLARE @isTotalVoucher		  AS BIT = 'False'
	DECLARE @voucherPreference    AS NVARCHAR(50)

	SELECT	@decCollectionBalance	= tct.ct_ABalance,
			@bra_id					= tct.bra_id	,
			@curr_id				= tct.ct_ACurrency
		FROM tbCommercialTransactions AS tct	WITH (NOLOCK)
		INNER JOIN tbCustomer		  AS tc		WITH (NOLOCK)
			ON	tc.comp_id			= tct.comp_id AND
				tc.cust_id			= tct.cust_id
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @intCollectionTransaction


	SELECT	 @isTotalVoucher		= tccv.ccv_MPBotonDePagoIsTotalButton,
			 @voucherPreference		= tccv.ccv_MPPreference
		FROM tbCreditCard_Voucher AS tccv	WITH (NOLOCK)
			WHERE	tccv.comp_id	= @comp_id AND
					tccv.ccv_id		= @intCCV_ID



	DECLARE @tblPreference2Expire TABLE(ccv_id INT,preference NVARCHAR(50))

	DECLARE @intInvoiceTransaction  AS INT
	DECLARE @intInvoiceLoan			AS INT
	DECLARE @decInvoiceAppliedTotal	AS DECIMAL(19,4)

	DECLARE curVouchersApplied CURSOR LOCAL FAST_FORWARD FOR
		SELECT	tccvr.ct_transaction,
				tccvr.ctl_id,
				tccvr.ctr_total
			FROM tbCreditCard_VoucherRelations AS tccvr			WITH (NOLOCK)
			WHERE	tccvr.comp_id	= @comp_id AND
					tccvr.ccv_id	= @intCCV_ID

	OPEN curVouchersApplied
	FETCH NEXT FROM curVouchersApplied INTO @intInvoiceTransaction,
											@intInvoiceLoan,
											@decInvoiceAppliedTotal

	WHILE @@FETCH_STATUS = 0
		BEGIN

			-- si @decInvoiceAppliedTotal = 0 es porque vino de la manera VIEJA y debo REcalcularlo al importe de la COBRANZA
			IF @decInvoiceAppliedTotal = 0
				BEGIN
					SET @decInvoiceAppliedTotal = @decCollectionBalance
				END




			-- Obtengo el saldo de la Factura o Cuota a pagar
			IF @intInvoiceLoan > 0
				BEGIN
					SELECT	@decInvoiceBalance  = tctl.ct_ABalance,
							@decInvoiceTotal	= tct.ct_ATotal
						FROM		tbCommercialTransactions		AS tct		WITH (NOLOCK)
						INNER JOIN	tbCommercialTransactionsLoan	AS tctl		WITH (NOLOCK)
							ON	tctl.comp_id		= tct.comp_id			AND
								tctl.ct_transaction = tct.ct_transaction
						WHERE	tct.comp_id			= @comp_id					AND
								tct.ct_transaction	= @intInvoiceTransaction	AND
								tctl.ctl_id			= @intInvoiceLoan
				END
			ELSE
				BEGIN
					SELECT	@decInvoiceBalance  = tct.ct_ABalance,
							@decInvoiceTotal	= tct.ct_ATotal
						FROM		tbCommercialTransactions		AS tct		WITH (NOLOCK)
						WHERE	tct.comp_id			= @comp_id					AND
								tct.ct_transaction	= @intInvoiceTransaction
				END


			-- Si ese saldo es Mayor o igual al que dice el cupon, LO APLICO
			IF @decInvoiceBalance >= @decInvoiceAppliedTotal
				BEGIN

					-- Cancelo Saldo del Recibo
					UPDATE tbCommercialTransactions		WITH (ROWLOCK)
						SET ct_ABalance = ct_ABalance  - @decInvoiceAppliedTotal
						WHERE	comp_id			= @comp_id AND
								ct_transaction	= @intCollectionTransaction

					-- Cancelo Saldo de la Factura
					UPDATE tbCommercialTransactions		WITH (ROWLOCK)
						SET ct_ABalance = ct_ABalance - @decInvoiceAppliedTotal
						WHERE	comp_id			= @comp_id AND
								ct_transaction	= @intInvoiceTransaction

					-- Cancelo Saldo de la Cuota
					IF @intInvoiceLoan > 0
						BEGIN
							UPDATE tbCommercialTransactionsLoan		WITH (ROWLOCK)
								SET ct_ABalance			= ct_ABalance - @decInvoiceAppliedTotal,
								    ctl_lastPayDate 	= GETDATE()
								WHERE	comp_id			= @comp_id AND
										ct_transaction	= @intInvoiceTransaction AND
										ctl_id			= @intInvoiceLoan
						END

					-- Guardo la Aplicación.
					IF @intInvoiceLoan <= 0 SET @intInvoiceLoan = NULL


					INSERT INTO tbApplication	WITH (ROWLOCK)
					(
						comp_id,
						bra_id,
						ct_transaction_Source,
						ct_transaction_destiny,
						appl_currency,
						appl_total,
						appl_coef,
						appl_coef_,
						appl_excdifchecked,
						ct_transaction,
						ctl_id_Source
					)
					VALUES
					(
						@comp_id,
						@bra_id,
						@intInvoiceTransaction,
						@intCollectionTransaction,
						@curr_id,
						@decInvoiceAppliedTotal,
						@decInvoiceAppliedTotal / dbo.fnNoZDiv(@decInvoiceTotal) * 100,
						100,
						'False',
						NULL,
						@intInvoiceLoan
					)



					-- Baja de Voucher de Proceso  (no hay drama si se pone mas de una vez, abajo hago un distinct y es mas rapido)
					INSERT INTO @tblPreference2Expire
					(
						ccv_id,
						preference
					)
					VALUES
					(
						@intCCV_ID,
						@voucherPreference
					)

					-- Si mi actual Voucher es de TOTAL, debo dar de BAJA mi cupon y los INDIVIDUALES relacionados a Esta Factura Aplicada.
					IF @isTotalVoucher = 'True'
						BEGIN

							-- Todos lo vouchers de NO total relacionados a esta factura paga.
							INSERT INTO @tblPreference2Expire
							(
								ccv_id,
								preference
							)
								SELECT	tccv.ccv_id,tccv.ccv_MPPreference
									FROM		tbCreditCard_VoucherRelations		AS tccvr	WITH (NOLOCK)
									INNER JOIN	tbCreditCard_Voucher				AS tccv		WITH (NOLOCK)
										ON	tccv.comp_id			= tccvr.comp_id				AND
											tccv.ccv_id				= tccvr.ccv_id
									WHERE	tccvr.comp_id			= @comp_id					AND
											tccvr.ct_transaction	= @intInvoiceTransaction	AND
											tccv.ccv_MPBotonDePagoIsTotalButton = 'False'		AND
											(@intInvoiceLoan IS NULL OR tccvr.ctl_id = @intInvoiceLoan)

						END

				END

			FETCH NEXT FROM curVouchersApplied INTO @intInvoiceTransaction,
													@intInvoiceLoan,
													@decInvoiceAppliedTotal
		END

	CLOSE		curVouchersApplied
	DEALLOCATE	curVouchersApplied


	-- ------------------------------------------------------------------------------------------
	-- Si detecta que DEBE GEnerarse un Pedido por Intereses, Lo Hace.
	-- ------------------------------------------------------------------------------------------
	BEGIN TRY

			DECLARE 	@decTotal					DECIMAL(19,4) = 0,
						@decOriginalTotal			DECIMAL(19,4) = 0,
						@cust_id					INT,
						@user_id					INT,
						@df_id						INT,
						@decNeto					DECIMAL(19,4)	 = 0,
						@guid						UNIQUEIDENTIFIER = NEWID(),
						@decExchange2CustomerCurrency decimal(38,15) = 1,
						@intBranchCurrID			INT,
						@intCustCurrID				INT,
						@df_Collection_item_id4InterestDebit	INT,
						@decIvaPercOfItem			DECIMAL(19,4)	 = 0

			SELECT	@decTotal			= ISNULL(tccv.ccv_GrandTotal,0),
					@decOriginalTotal	= ISNULL(tccv.ccv_GrandTotalOriginal,0)
				FROM tbCreditCard_Voucher AS tccv		WITH (NOLOCK)
				WHERE	tccv.comp_id	= @comp_id AND
						tccv.ccv_id		= @intCCV_ID
			IF  @decTotal <> @decOriginalTotal
				BEGIN
					SELECT	@bra_id				= tct.bra_id,
							@cust_id			= tct.cust_id,
							@user_id			= tct.[user_id],
							@intbranchCurrID	= tb.curr_id,
							@intcustCurrID		= tc.curr_id,
							@df_Collection_item_id4InterestDebit = tdf.df_Collection_item_id4InterestDebit,
							@df_id				= tct.df_id
						FROM tbCommercialTransactions	AS tct		WITH (NOLOCK)
						INNER JOIN tbCustomer			AS tc		WITH (NOLOCK)
							ON	tc.comp_id = tct.comp_id		AND
								tc.cust_id = tct.cust_id
						INNER JOIN tbBranch				AS tb		WITH (NOLOCK)
							ON	tb.comp_id	= tct.comp_id	AND
								tb.bra_id	= tct.bra_id
						INNER JOIN tbDocumentsFile		AS tdf		WITH (NOLOCK)
							ON	tdf.comp_id = tct.comp_id	AND
								tdf.bra_id	= tct.bra_id	AND
								tdf.df_id	= tct.df_id
						WHERE	tct.comp_id			= @comp_id AND
								tct.ct_transaction	= @intCollectionTransaction

					SET @decExchange2CustomerCurrency = dbo.fnGetExchange2(@comp_id,1,@intcustCurrID,@intbranchCurrID,0,0,0,'False')

					SELECT @decIvaPercOfItem = ISNULL(ttn.tax_percentage,0)
						FROM vwItemTaxesOnlyOneIvaTax AS vitooit		WITH (NOLOCK)
						INNER JOIN tbTaxName		  AS ttn			WITH (NOLOCK)
							ON	ttn.comp_id		= vitooit.comp_id AND
								ttn.tax_id		= vitooit.tax_id
						WHERE	vitooit.comp_id = @comp_id AND
								vitooit.item_id = @df_Collection_item_id4InterestDebit


					SET @decNeto = @decTotal - @decOriginalTotal

					SET @decNeto = @decNeto / dbo.fnNoZDiv( 1 + (@decIvaPercOfItem / 100) )

					EXEC spCollection_InsertSaleOrder4Interests @comp_id,
																2,
																@bra_id,
																@cust_id,
																@intcollectionTransaction,
																@user_id,
																@decExchange2CustomerCurrency,
																@df_id,
																@decNeto,
																0,
																@guid,
																'',
																0,
																''

				END
	END TRY
	BEGIN CATCH
	END CATCH
	-- ------------------------------------------------------------------------------------------


	SELECT DISTINCT tm.preference
		FROM @tblPreference2Expire tm


END

GO



CREATE PROCEDURE [dbo].[spCollection_insertApplicationByCTTransactionLoan]
(
	@comp_id						int,
	@intCollectionTransaction		INT,
	@intct_transaction_Invoice		INT,
	@intCTL_Id						INT,
	@guid							UNIQUEIDENTIFIER
)
as

BEGIN


	-- ---------------------------------------------------
	-- Testing
	-- ---------------------------------------------------
	/*
	DECLARE 	@comp_id						INT = 1,
				@intCollectionTransaction		INT	= 23363438,
				@intCCV_ID						INT = 139
	*/
	-- ---------------------------------------------------





	SET NOCOUNT ON

	DECLARE @bra_id AS INT
	DECLARE @cust_id AS INT
	DECLARE @cust_id_2Apply AS INT
	DECLARE @appl_currency AS INT
	DECLARE @return_value AS INT
	DECLARE @ret_ErrorCode AS INT
	DECLARE @ret_ErrorDescription AS VARCHAR(200)
	DECLARE @decCollectionTotal AS DECIMAL(19,4)


	SELECT	@bra_id					= tct.bra_id,
			@cust_id				= tct.cust_id,
			@appl_currency			= tct.ct_ACurrency,
			@decCollectionTotal		= tct.ct_ABalance
		FROM tbCommercialTransactions AS tct	WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @intCollectionTransaction


	DECLARE @decInvoiceBalance AS DECIMAL(19,4)
	DECLARE @bra_id_Invoice AS INT
	SELECT	@decInvoiceBalance		= tct.ct_ABalance,
			@bra_id_Invoice			= tct.bra_id,
			@cust_id_2Apply			= tct.cust_id
		FROM tbCommercialTransactions AS tct	WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @intct_transaction_Invoice

	SELECT	@decInvoiceBalance		= tct.ct_ABalance
		FROM tbCommercialTransactionsLoan AS tct	WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @intct_transaction_Invoice AND
				tct.ctl_id			= @intCTL_Id


	-- ----------------------------------------------------------------------------------------------
	-- MOS 02-2022
	-- Si en IMPORTACION de cobranzas ponen un ct_transaction de Factura Equivocado, NO aplica nada.!
	-- ----------------------------------------------------------------------------------------------
	IF @cust_id <> @cust_id_2Apply
		BEGIN
			RETURN
		END
	-- ----------------------------------------------------------------------------------------------


	-- --------------------------------------------------------
	-- Controlar aquí si hace falta, si debe el importe del SALDO ser MAYOR o igual a importe del recibo, por si se puede dejar importes a CUENTA o no...
	-- --------------------------------------------------------
	    -- Supongamos que no hace falta, pero x las dudas...
	-- --------------------------------------------------------


	-- Inserto el comprobante a Aplicar
	INSERT INTO tbCommercialTransactionsTmp(	comp_id,
												bra_id,
												ctct_guid,
												ctct_transaction,
												ctct_total,
												ctct_origin,
												ctct_exchange,
												ctl_id,
												ctct_cd
											)
	VALUES	(
				@comp_id,
				@bra_id_Invoice,
				@guid,
				@intct_transaction_Invoice,
				CASE
					WHEN @decCollectionTotal <= @decInvoiceBalance THEN @decCollectionTotal
					ELSE												@decInvoiceBalance
				END,
				'h',
				1,
				CASE
					WHEN @intCTL_Id > 0 THEN @intCTL_Id
					ELSE NULL
				END,
				GETDATE()
			)



	EXEC spCollection_insertApplications
		@comp_id						,
		@bra_id							,
		@cust_id						,
		@guid							,
		@intCollectionTransaction		,
		@appl_currency					,
		@return_value					output,
		@ret_ErrorCode					output,
		@ret_ErrorDescription			OUTPUT



	-- Ajusto el SALDO del recibo para que cuadre.
	IF @decCollectionTotal <= @decInvoiceBalance
		BEGIN
			UPDATE tbCommercialTransactions
				SET		ct_ABalance		= 0
				WHERE	comp_id			= @comp_id AND
						ct_transaction	= @intCollectionTransaction
		END
	ELSE
		BEGIN
			UPDATE tbCommercialTransactions
				SET		ct_ABalance		= ct_ABalance - @decInvoiceBalance
				WHERE	comp_id			= @comp_id AND
						ct_transaction	= @intCollectionTransaction
		END




END

GO



CREATE PROCEDURE [dbo].[spCollection_insertApplications]
(
	@comp_id						int,
	@bra_id							int,
	@cust_id						int,
	@guid							uniqueidentifier,
	@ct_transaction					int,
	@appl_currency					int,
	@return_value					int				output,
	@ret_ErrorCode					int				output,
	@ret_ErrorDescription			varchar(200)	OUTPUT
)
as

BEGIN




	set nocount ON
	-- =================================================================================================================
	-- Author		: HDP Y LA RE PUTA MADRE QUE TE PARIO ENFERMO MENTAL!!!
	-- Cuando tengamos tiempo habria que rehacer esto por completo en mo mas de 40 lineas y de manera que se cualquiera lo entienda

	-- Como el ENFERMO HIJO DE RE MIL PUTAS Y LA RE MIL PUTA MADRE QUE TE REMOIL PARIO FORRO DE MIERDA!!!!.
	-- HIZO ESTE sp DE MANERA QUE NI EL SEPA QUE MIERDA PUSO SE LIMITA LA CANTIDAD DE cOMPROBANTES APLICABLES A 1 SI
	-- ES UN RECIBO DE DEVOLUCION.!!!!!  Este SP se hace en 40 lineas aproximadamente sion todas las preguntas al pedo que CONFUNDEN
	--
	-- Update Date	: 2010-11-12
	-- Parte		: s/P referencia: #1
	-- Se quita una condición de inner join para que traiga comprobantes de diferentes sucursales y se recuperan las
	-- sucursales correspondientes en los insert en tbCOmmercialtransactions
	-- =================================================================================================================


	-- -------------------------------------------------------------------
	-- Test
	-- -------------------------------------------------------------------
	/*
	declare 	@comp_id						int,
				@bra_id							int,
				@cust_id						int,
				@guid							uniqueidentifier,
				@ct_transaction					int,
				@appl_currency					int,
				@return_value					int				,
				@ret_ErrorCode					int				,
				@ret_ErrorDescription			varchar(200)
	select		@comp_id						=1,
				@bra_id							=1,
				@cust_id						=24454,
				@guid							='fd2be8f2-ab98-451b-8af8-78cd39c6b157',
				@ct_transaction					=0,
				@appl_currency					=1
	*/
    -- -------------------------------------------------------------------



	set 	@return_value			= 0
	set		@ret_ErrorCode			= 0
	set		@ret_ErrorDescription	= ' '



	-- MOS 04-2023: Se agranda la cantidad de decimales para guardar APLICACIONES ya que con 2, como estaba redondeado, molesta para algunos procesos en los que se necesita mas presición
	DECLARE @decDecimals4ApplicationCoeficient AS INT = 10


	/*************************************************************************************************************/
	/* Recuperar el valor del recibo generado                                                                    */
	/*************************************************************************************************************/

	declare @ct_Atotal					decimal(19,5),
			@ct_Atotal_Final			decimal(19,5),
			@ct_ACurrencyExchange		decimal(19,5),
			@decTotalAplicated			DECIMAL(19,5),
			@intSuppCustID				INT,
			@bitSuppCust				BIT


	SELECT	@intSuppCustID = IsNull(tct.cust_id,tct.supp_id),
			@bitSuppCust   = CASE
								WHEN tct.cust_id IS NULL THEN 'True'
								ELSE						  'False'
							 END
		FROM tbCommercialTransactions tct					WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id
			AND tct.ct_transaction	= @ct_transaction



	-- MOS 06-2020: AUto PUTEADA: soy un IDIOTA, QUE MIERDA QUIERO VER SI YA SE APLICO
	-- ESTO ABAJO CAUSABA LA DOBLE EJECUCION, AL PEDO, DE ESTE SP
	-- y en la 2da, como YA ESTABA TODO APLICADO, daba Igual mas abajo.
	---- ------------------------------------------------------------------
	---- Sumo en bruto todo para comparar lo mismo al final de la cobranza.
	---- Si al final da diferente es que hubo un error de calculo.
	---- ------------------------------------------------------------------
	--IF @bitSuppCust = 'True'   -- Proveedor
	--	BEGIN
	--		SELECT @decTotalAplicated = SUM(tct.ct_ABalance * vctfs.PlusOrMinus)
	--			FROM tbCommercialTransactions tct							WITH (NOLOCK)
	--			INNER JOIN vwCommercialTransactions_forPurchase vctfs		WITH (NOLOCK)
	--				ON		vctfs.comp_id		 = tct.comp_id
	--					AND vctfs.ct_transaction = tct.ct_transaction
	--			WHERE	tct.comp_id = @comp_id
	--				AND tct.supp_id = @intSuppCustID
	--	END
	--ELSE	-- Cliente
	--	BEGIN
	--		SELECT @decTotalAplicated = SUM(tct.ct_ABalance * vctfs.PlusOrMinus)
	--			FROM tbCommercialTransactions tct							WITH (NOLOCK)
	--			INNER JOIN vwCommercialTransactions_forSales vctfs			WITH (NOLOCK)
	--				ON		vctfs.comp_id		 = tct.comp_id
	--					AND vctfs.ct_transaction = tct.ct_transaction
	--			WHERE	tct.comp_id = @comp_id
	--				AND tct.cust_id = @intSuppCustID
	--	END
	---- ------------------------------------------------------------------

	select	@ct_Atotal					= round(ct_Atotal,2),
			@ct_ACurrencyExchange		= round(ct_ACurrencyExchange,2)
		from	dbo.[tbCommercialTransactions]								WITH (NOLOCK)
		WHERE	comp_id					= @comp_id AND
				ct_transaction			= @ct_transaction

	set		@ct_ACurrencyExchange		= round(dbo.fnNoZDiv(@ct_ACurrencyExchange),2)
	set		@ct_Atotal_Final			= @ct_Atotal
	-- ------------------------------------------------------------------


	-- --------------------------------------------------------------------------------------------------
	-- Controla que si es un Recibo de Devolucion se pueda aplicar como maximo UN solo documento por vez
	-- --------------------------------------------------------------------------------------------------
	IF @bitSuppCust = 'False' AND @ct_Atotal < 0 AND	(SELECT COUNT(*)
	                                                        FROM tbCommercialTransactionsTmp tctt	WITH (NOLOCK)
	                                                        WHERE tctt.ctct_guid = @guid ) > 1
		BEGIN
			DECLARE @lang_id AS INT
			SELECT @lang_id = tb.lang_id
				FROM tbBranch tb			WITH (NOLOCK)
				WHERE	tb.comp_id	= @comp_id AND
						tb.bra_id	= @bra_id
			DECLARE @strErrorMsg AS NVARCHAR(MAX)
			SELECT  @strErrorMsg  = tut.utexts_desc
				FROM tbsysUniqueTexts tut	WITH (NOLOCK)
				WHERE tut.lang_id = @lang_id AND tut.utexts_id = 226
			set 	@return_value			= -10
			set		@ret_ErrorCode			= -10
			set		@ret_ErrorDescription	= @strErrorMsg
			RETURN
		END
	-- --------------------------------------------------------------------------------------------------




	/*************************************************************************************************************/
	/* Declaración de variables de trabajo                                                                       */
	/*************************************************************************************************************/

	declare @h_ctct_transaction			integer,
			@h_ctct_total				decimal(19,5),
			@h_ctct_exchange			decimal(19,5),
			@h_ct_ATotal				decimal(19,5),
			@h_ct_ABalance				decimal(19,5),

			@a_ctct_transaction			integer,
			@a_ctct_total				decimal(19,5),
			@a_ctct_exchange			decimal(19,5),
			@a_ct_ATotal				decimal(19,5),
			@a_ct_ABalance				decimal(19,5),

			@total_to_applic			decimal(30,12),
			@appl_coef					decimal(30,18),
			@appl_coef_					decimal(30,18),

			@h_to_applic				decimal(19,5),
			@a_to_applic				decimal(19,5),

			@h_pending					decimal(19,5),
			@a_pending					decimal(19,5)

	declare @h_fetch_status				int,
			@a_fetch_status				int
	DECLARE @h_CTLId					INT
	DECLARE @a_CTLId					INT
	/*************************************************************************************************************/




	/*************************************************************************************************************/
	/* Declaración de cursores de los documentos a cancelar y de documentos a aplicar                            */
	/*************************************************************************************************************/
	-- La verdad que a veces sos taaaaaaaaaaaaaaaan hijo de re mil putas que me sorprendes!!!!!

	declare cursor_applic_coll CURSOR LOCAL  FAST_FORWARD for
		select	ctct.ctct_transaction,
				CASE WHEN ctct.ctct_origin	= 'a' THEN ctct.ctct_total * -1
					ELSE ctct.ctct_total
				END															[ctct_total],
				ctct_exchange,
				CASE WHEN ctct.ctct_origin	= 'a' THEN ct.ct_Atotal * -1
					ELSE ct.ct_Atotal
				END															[ct_Atotal],
				CASE WHEN ctct.ctct_origin	= 'a' THEN ct.ct_ABalance * -1
					ELSE ct.ct_ABalance
				END															[ct_ABalance],
				ctct.ctl_id
			from	dbo.[tbCommercialTransactionsTmp]			ctct			WITH (NOLOCK)
			inner join dbo.[tbCommercialTransactions]		ct					WITH (NOLOCK)
				on	ct.[comp_id]			=	ctct.[comp_id]
				and	ct.[ct_transaction]		=	ctct.[ctct_transaction]
			where	ctct.ctct_guid		=	@guid
			and		(ctct.ctct_origin	=	'h' OR
					(ctct.ctct_origin	=	'a' AND ct.ct_Atotal < 0))
			order by ctct.[ctct_transaction]




	declare cursor_applic_toacc CURSOR LOCAL   FAST_FORWARD for
		select	ctct.ctct_transaction,
				ctct.ctct_total,
				ctct_exchange,
				ct.ct_Atotal,
				ct.ct_ABalance,
				ctct.ctl_id

			from	dbo.[tbCommercialTransactionsTmp]			ctct			WITH (NOLOCK)
			inner join dbo.[tbCommercialTransactions]		ct					WITH (NOLOCK)
				on	ct.[comp_id]			=	ctct.[comp_id]
				and	ct.[ct_transaction]		=	ctct.[ctct_transaction]
			where	ctct.ctct_guid		=	@guid
			and		ctct.ctct_origin	=	'a' AND ct.ct_Atotal > 0
			order by ctct.[ctct_transaction]



	open cursor_applic_coll
	open cursor_applic_toacc

	/*************************************************************************************************************/
	/*************************************************************************************************************/



	DECLARE @getdate DATETIME
	SET @getdate = GETDATE()



	/*************************************************************************************************************/
	/* Lectura anticipada de los cursores antes definidos                                                        */
	/*************************************************************************************************************/

	fetch cursor_applic_coll
		into	@h_ctct_transaction,
				@h_ctct_total,
				@h_ctct_exchange,
				@h_ct_ATotal,
				@h_ct_ABalance,
				@h_CTLId
	set @h_fetch_status = @@fetch_status
	if @h_fetch_status = 0
		BEGIN
			set @h_to_applic	= ROUND(@h_ct_ATotal,2)
			set @h_pending		= ROUND(@h_ctct_total,2)
		end


	fetch cursor_applic_toacc
		into	@a_ctct_transaction,
				@a_ctct_total,
				@a_ctct_exchange,
				@a_ct_ATotal,
				@a_ct_ABalance,
				@a_CTLId
	set @a_fetch_status = @@fetch_status
	if @a_fetch_status = 0
		begin
			set @a_to_applic	= ROUND(@a_ct_ATotal,2)
			set @a_pending		= ROUND(@a_ctct_total,2)

		end

	/*************************************************************************************************************/
	/*************************************************************************************************************/




	DECLARE @bra_id_dummy INT	-- Parte		: s/P referencia: #1


	/*************************************************************************************************************/
	/* Apareo entre los registros recuperados de los cursores para su aplicación                                 */
	/*************************************************************************************************************/

	while @h_fetch_status = 0 and @a_fetch_status = 0
	begin


		if @h_pending < @a_pending
			BEGIN

				set @a_pending	= round(@a_pending - @h_pending,2)

				set @appl_coef	= round(@h_pending * 100 / dbo.fnNoZDiv(@h_to_applic),@decDecimals4ApplicationCoeficient)

				set @appl_coef_	= round(@h_pending * 100 / dbo.fnNoZDiv(@a_to_applic),@decDecimals4ApplicationCoeficient)


				exec dbo.[spApplication_insertData]	@comp_id,
													@bra_id,
													@h_ctct_transaction,
													@a_ctct_transaction,
													@appl_currency,
													@h_pending,
													@appl_coef,
													@appl_coef_,
													'False',
													@ct_transaction,
													@h_CTLId,
													@a_CTLId


				SELECT	@bra_id_dummy = tct.bra_id
					FROM tbCommercialTransactions tct	WITH (NOLOCK)		-- Parte		: s/P referencia: #1
					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @h_ctct_transaction		-- Parte		: s/P referencia: #1

				--select 'a12' [ ],									@comp_id, @bra_id_dummy, @h_ctct_transaction, @h_pending
				exec dbo.[spCommercialTransactions_updateABalance]	@comp_id, @bra_id_dummy, @h_ctct_transaction, @h_pending, @h_CTLId


				SELECT	@bra_id_dummy = tct.bra_id
					FROM tbCommercialTransactions tct	WITH (NOLOCK)		-- Parte		: s/P referencia: #1
					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @a_ctct_transaction		-- Parte		: s/P referencia: #1

				--select 'a13' [ ],									@comp_id, @bra_id_dummy, @a_ctct_transaction, @h_pending
				exec dbo.[spCommercialTransactions_updateABalance]	@comp_id, @bra_id_dummy, @a_ctct_transaction, @h_pending, @a_CTLId  -- @h_CTLId


				fetch cursor_applic_coll
					into	@h_ctct_transaction,
							@h_ctct_total,
							@h_ctct_exchange,
							@h_ct_ATotal,
							@h_ct_ABalance,
							@h_CTLId
				set @h_fetch_status = @@fetch_status
				if @h_fetch_status = 0
					begin
						set @h_to_applic	= ROUND(@h_ct_ATotal,2)
						set @h_pending		= ROUND(@h_ctct_total,2)

					END

			END

		else

			begin

				if @h_pending > @a_pending
				begin

					set @h_pending	= round(@h_pending - @a_pending,2)

					set @appl_coef	= round(@a_pending * 100 / dbo.fnNoZDiv(@h_to_applic),@decDecimals4ApplicationCoeficient)

					set @appl_coef_	= round(@a_pending * 100 / dbo.fnNoZDiv(@a_to_applic),@decDecimals4ApplicationCoeficient)


					--select 'a21' [ ],									@comp_id,@bra_id,@h_ctct_transaction,@a_ctct_transaction,@appl_currency,@a_pending,@appl_coef,@appl_coef_
					exec dbo.[spApplication_insertData]		@comp_id,
															@bra_id,
															@h_ctct_transaction,
															@a_ctct_transaction,
															@appl_currency,
															@a_pending,
															@appl_coef,
															@appl_coef_,
															'False',
															@ct_transaction,
															@h_CTLId,
															@a_CTLId

					SELECT	@bra_id_dummy			= tct.bra_id
						FROM tbCommercialTransactions tct	WITH (NOLOCK)		-- Parte		: s/P referencia: #1
						WHERE	tct.comp_id			= @comp_id AND
								tct.ct_transaction	= @h_ctct_transaction		-- Parte		: s/P referencia: #1

					--select 'a22' [ ],									@comp_id, @bra_id_dummy, @h_ctct_transaction, @a_pending
					exec dbo.[spCommercialTransactions_updateABalance]	@comp_id, @bra_id_dummy, @h_ctct_transaction, @a_pending, @h_CTLId --@a_CTLId

					SELECT	@bra_id_dummy			= tct.bra_id
						FROM tbCommercialTransactions tct	WITH (NOLOCK)		-- Parte		: s/P referencia: #1
						WHERE	tct.comp_id			= @comp_id AND
								tct.ct_transaction	= @a_ctct_transaction		-- Parte		: s/P referencia: #1

					--select 'a23' [ ],									@comp_id, @bra_id_dummy, @a_ctct_transaction, @a_pending
					exec dbo.[spCommercialTransactions_updateABalance]	@comp_id, @bra_id_dummy, @a_ctct_transaction, @a_pending, @a_CTLId


					fetch cursor_applic_toacc
						into	@a_ctct_transaction,
								@a_ctct_total,
								@a_ctct_exchange,
								@a_ct_ATotal,
								@a_ct_ABalance,
								@a_CTLId
					set @a_fetch_status = @@fetch_status
					if @a_fetch_status = 0
						begin
							set @a_to_applic	= round(@a_ct_ATotal,2)
							set @a_pending		= round(@a_ctct_total,2)
						end
				end

			else

				begin

					if @h_pending = @a_pending and @a_pending > 0
						begin

							set @a_pending	= round(@a_pending,2)

							set @appl_coef	= round(@a_pending * 100 / dbo.fnNoZDiv(@h_to_applic),@decDecimals4ApplicationCoeficient)

							set @appl_coef_	= round(@a_pending * 100 / dbo.fnNoZDiv(@a_to_applic),@decDecimals4ApplicationCoeficient)


							--select 'a31' [ ],									@comp_id,@bra_id,@h_ctct_transaction,@a_ctct_transaction,@appl_currency,@a_pending,@appl_coef,@appl_coef_
							exec dbo.[spApplication_insertData]		@comp_id,
																	@bra_id,
																	@h_ctct_transaction,
																	@a_ctct_transaction,
																	@appl_currency,
																	@a_pending,
																	@appl_coef,
																	@appl_coef_,
																	'False',
																	@ct_transaction,
																	@h_CTLId,
																	@a_CTLId

							SELECT	@bra_id_dummy = tct.bra_id
								FROM tbCommercialTransactions tct	WITH (NOLOCK)		-- Parte		: s/P referencia: #1
								WHERE	tct.comp_id			= @comp_id AND
										tct.ct_transaction	= @h_ctct_transaction		-- Parte		: s/P referencia: #1

							--select 'a32' [ ],									@comp_id, @bra_id_dummy, @h_ctct_transaction, @a_pending
							exec dbo.[spCommercialTransactions_updateABalance]	@comp_id, @bra_id_dummy, @h_ctct_transaction, @a_pending, @h_CTLId -- @a_CTLId

							SELECT	@bra_id_dummy			= tct.bra_id
								FROM tbCommercialTransactions tct	WITH (NOLOCK)		-- Parte		: s/P referencia: #1
								WHERE	tct.comp_id			= @comp_id AND
										tct.ct_transaction	= @a_ctct_transaction		-- Parte		: s/P referencia: #1

							--select 'a33' [ ],									@comp_id, @bra_id_dummy, @a_ctct_transaction, @a_pending
							exec dbo.[spCommercialTransactions_updateABalance]	@comp_id, @bra_id_dummy, @a_ctct_transaction, @a_pending, @a_CTLId

							fetch cursor_applic_coll
								into	@h_ctct_transaction,
										@h_ctct_total,
										@h_ctct_exchange,
										@h_ct_ATotal,
										@h_ct_ABalance,
										@h_CTLId
							set @h_fetch_status = @@fetch_status
							if @h_fetch_status = 0
								begin
									set @h_to_applic	= ROUND(@h_ct_ABalance,2)
									set @h_pending		= ROUND(@h_ctct_total,2)
								end

							fetch cursor_applic_toacc
								into	@a_ctct_transaction,
										@a_ctct_total,
										@a_ctct_exchange,
										@a_ct_ATotal,
										@a_ct_ABalance,
										@a_CTLId
							set @a_fetch_status = @@fetch_status
							if @a_fetch_status = 0
								begin
									set @a_to_applic	= ROUND(@a_ct_ABalance,2)
									set @a_pending		= ROUND(@a_ctct_total,2)
								end
						end
					end
		end
	end


	/*************************************************************************************************************/
	/*************************************************************************************************************/





	/*************************************************************************************************************/
	/* Aplicar los valores a cobrar a los documentos a cancelar                                                  */
	/*************************************************************************************************************/

	while @h_fetch_status = 0 and @ct_Atotal > 0
		begin

			if @h_ctct_total > @h_pending
				begin
					set @h_to_applic	= round(@h_pending,2)
					set @h_pending		= 0
				end
			else
				begin
					set @h_to_applic	= round(@h_ctct_total,2)
					set @h_pending		= round(@h_pending - @h_ctct_total,2)
				end


			set @appl_coef	= round(@h_to_applic * 100 / dbo.fnNoZDiv(@h_ct_Atotal),@decDecimals4ApplicationCoeficient)

			set @appl_coef_	= round(@h_to_applic * 100 / dbo.fnNoZDiv(@ct_Atotal),@decDecimals4ApplicationCoeficient)


			--select 'a41' [ ],	*888					  @comp_id,@bra_id,@h_ctct_transaction,@ct_transaction,@appl_currency,@h_to_applic,@appl_coef,@appl_coef_
			exec dbo.[spApplication_insertData]		@comp_id,
													@bra_id,
													@h_ctct_transaction,
													@ct_transaction,
													@appl_currency,
													@h_to_applic,
													@appl_coef,
													@appl_coef_,
													'False',
													@ct_transaction,
													@h_CTLId,
													NULL

			--select 'a42' [ ],									   @comp_id, @bra_id, @h_ctct_transaction, @h_to_applic
			SELECT @bra_id_dummy = tct.bra_id
				FROM tbCommercialTransactions tct	WITH (NOLOCK) -- Parte		: s/P referencia: #1
				WHERE	tct.comp_id			= @comp_id AND
						tct.ct_transaction	= @h_ctct_transaction	-- Parte		: s/P referencia: #1

			exec dbo.[spCommercialTransactions_updateABalance] @comp_id, @bra_id_dummy, @h_ctct_transaction, @h_to_applic, @h_CTLId

			----select 'a43' [ ],										 @comp_id, @bra_id, @ct_transaction, @h_to_applic
			----exec dbo.[spCommercialTransactions_updateABalance] @comp_id, @bra_id, @ct_transaction, @h_to_applic

			fetch cursor_applic_coll
				into	@h_ctct_transaction,
						@h_ctct_total,
						@h_ctct_exchange,
						@h_ct_ATotal,
						@h_ct_ABalance,
						@h_CTLId
			set @h_fetch_status = @@fetch_status
			if @h_fetch_status = 0
				begin
					set @h_to_applic	= ROUND(@h_ct_ABalance,2)
					set @h_pending		= ROUND(@h_ctct_total,2)
				end

		end

	/**********************************************************************************************************************/






	/*************************************************************************************************************/
	/* Aplicar los valores a cobrados a los documentos a cuenta                                                  */
	/*************************************************************************************************************/

	while @a_fetch_status = 0 and @ct_Atotal < 0
	begin

		if @a_ctct_total > @a_pending
			begin
				set @a_to_applic	= round(@a_pending,2)
				set @a_pending		= 0
			end
		else
			begin
				set @a_to_applic	= round(@a_ctct_total,2)
				set @a_pending		= round(@a_pending - @a_ctct_total,2)
			end


		set @appl_coef	= round(@a_to_applic * 100 / dbo.fnNoZDiv(@a_ct_Atotal),@decDecimals4ApplicationCoeficient)

		set @appl_coef_	= round(@a_to_applic * 100 / dbo.fnNoZDiv(@ct_Atotal),@decDecimals4ApplicationCoeficient)


		--select 'a51' [ ],						  @comp_id,@bra_id,@h_ctct_transaction,@ct_transaction,@appl_currency,@h_to_applic,@appl_coef,@appl_coef_
		exec dbo.[spApplication_insertData] @comp_id,
											@bra_id,
											@a_ctct_transaction,
											@ct_transaction,
											@appl_currency,
											@a_to_applic,
											@appl_coef,
											@appl_coef_,
											'False',
											@ct_transaction,
											@a_CTLId,
											NULL

		--select 'a52' [ ],									   @comp_id, @bra_id, @h_ctct_transaction, @h_to_applic
		SELECT @bra_id_dummy = tct.bra_id
			FROM tbCommercialTransactions tct	WITH (NOLOCK) -- Parte		: s/P referencia: #1
			WHERE	tct.comp_id			= @comp_id AND
					tct.ct_transaction	= @a_ctct_transaction	-- Parte		: s/P referencia: #1

		exec dbo.[spCommercialTransactions_updateABalance] @comp_id, @bra_id_dummy, @a_ctct_transaction, @a_to_applic, @a_CTLId

		----select 'a53' [ ],										 @comp_id, @bra_id, @ct_transaction, @h_to_applic
		----exec dbo.[spCommercialTransactions_updateABalance] @comp_id, @bra_id, @ct_transaction, @h_to_applic

		fetch cursor_applic_toacc
			into	@a_ctct_transaction,
					@a_ctct_total,
					@a_ctct_exchange,
					@a_ct_ATotal,
					@a_ct_ABalance,
					@a_CTLId
		set @a_fetch_status = @@fetch_status
		if @a_fetch_status = 0
			begin
				set @a_to_applic	= ROUND(@a_ct_ABalance,2) --set @a_to_applic	= round(@a_ctct_total,2)
				set @a_pending		= ROUND(@a_ctct_total,2)
			end

	end

	/**********************************************************************************************************************/







	/*************************************************************************************************************/
	/* Liberar los cursores definidos                                                                   */
	/*************************************************************************************************************/

	close cursor_applic_coll
	deallocate cursor_applic_coll

	close cursor_applic_toacc
	deallocate cursor_applic_toacc

	/*************************************************************************************************************/
	/*************************************************************************************************************/










	-- --------------------------------------------------------------------------------------------
	-- Para CUOTAS, verificar que si las cuptas quedaron en 0 el total del cpte quede en CERO !!!
	-- Esto pasa porque a veces quedan centavos a favor y en contra en los cptes.
	-- Verificar si se aplico por completo el ct_ATotal del Recibo Original, cancela la transaccion
	-- --------------------------------------------------------------------------------------------
	DECLARE
		@tblCommTrans2Update TABLE	(
										Comp_id			INT,
										Ct_Transaction	INT ,
										UNIQUE CLUSTERED (comp_id,Ct_Transaction)
									)


	-- Sala los ct_transaction involucrados
	DECLARE @tblApplication TABLE(ct_transaction INT PRIMARY KEY CLUSTERED)

	INSERT INTO @tblApplication(ct_transaction)
		SELECT DISTINCT	 ta.ct_transaction_Source
			FROM tbApplication ta		WITH (NOLOCK)
			WHERE	ta.comp_id			= @comp_id			AND
					ta.ct_transaction	= @ct_transaction

	INSERT INTO @tblApplication(ct_transaction)
		SELECT DISTINCT  ta.ct_transaction_destiny
			FROM tbApplication ta		WITH (NOLOCK)
			LEFT JOIN @tblApplication tmp2
				ON tmp2.ct_transaction = ta.ct_transaction_destiny
			WHERE	ta.comp_id			= @comp_id			AND
					ta.ct_transaction	= @ct_transaction	AND
					tmp2.ct_transaction IS NULL



	-- Selecciona los que tengan diferencias
	INSERT INTO @tblCommTrans2Update
	(
		Comp_id,
		Ct_Transaction
	)
	SELECT
		tct.comp_id,
		tct.ct_transaction
		FROM tbCommercialTransactions						tct		WITH (NOLOCK)
		INNER JOIN @tblApplication tmp
			ON tmp.ct_transaction = tct.ct_transaction
		INNER JOIN tbCommercialTransactionsLoan				tctl	WITH (NOLOCK)
			ON	tctl.comp_id		= tct.comp_id			AND
				tctl.ct_transaction = tct.ct_transaction
		WHERE	tct.ct_ABalance			<> 0
		GROUP BY tct.comp_id,tct.ct_transaction
		HAVING	SUM(tctl.ct_ABalance)	= 0	AND
				COUNT(tctl.comp_id)		> 0


	-- Pone el saldo en CERO para los que tienen diferencias
	UPDATE tbCommercialTransactions	WITH (ROWLOCK)
		SET	ct_Abalance = 0
		FROM tbCommercialTransactions					tct
		INNER JOIN @tblCommTrans2Update					tct2
			ON	tct2.comp_id		= tct.comp_id	AND
				tct2.ct_transaction = tct.ct_transaction
		WHERE tct.ct_Abalance <> 0
	-- --------------------------------------------------------------------------------------------




	-- MOS 06-2020: AUto PUTEADA: soy un IDIOTA, QUE MIERDA QUIERO VER SI YA SE APLICO
	-- ESTO ABAJO CAUSABA LA DOBLE EJECUCION, AL PEDO, DE ESTE SP
	-- y en la 2da, como YA ESTABA TODO APLICADO, daba Igual mas abajo.
	-- --------------------------------------------------------------------------------------------
	-- Verificar si se aplico por completo el ct_ATotal del Recibo Original, cancela la transaccion
	-- --------------------------------------------------------------------------------------------
	--DECLARE @decTotalAplicatedNew AS DECIMAL(19,5)

	--IF @bitSuppCust = 'True'   -- Proveedor
	--	BEGIN
	--		SELECT @decTotalAplicatedNew = SUM(tct.ct_ABalance * vctfs.PlusOrMinus)
	--			FROM tbCommercialTransactions tct							WITH (NOLOCK)
	--			INNER JOIN vwCommercialTransactions_forPurchase vctfs		WITH (NOLOCK)
	--				ON		vctfs.comp_id		 = tct.comp_id
	--					AND vctfs.ct_transaction = tct.ct_transaction
	--			WHERE	tct.comp_id = @comp_id
	--				AND tct.supp_id = @intSuppCustID
	--	END
	--ELSE	-- Cliente
	--	BEGIN
	--		SELECT @decTotalAplicatedNew = SUM(tct.ct_ABalance * vctfs.PlusOrMinus)
	--			FROM tbCommercialTransactions tct							WITH (NOLOCK)
	--			INNER JOIN vwCommercialTransactions_forSales vctfs			WITH (NOLOCK)
	--				ON		vctfs.comp_id		 = tct.comp_id
	--					AND vctfs.ct_transaction = tct.ct_transaction
	--			WHERE	tct.comp_id = @comp_id
	--				AND tct.cust_id = @intSuppCustID
	--	END




	----IF  @decTotalAplicated <> @decTotalAplicatedNew
	----	BEGIN
	----		SELECT 1 / 0
	----	END
	---- --------------------------------------------------------------------------------------------


	-- MOS 04-2022: $$wefjwl.hfj)(/ se pasó de SP

	-- --------------------------------------------------------------------------------------------
	-- MOS 05-2021 x FIESA ticket 10952
	-- Marca como APROBADOS todos los estados de Remitos de Facturas Adelantadas que digan que deben Auto-Aprobarse.
	-- --------------------------------------------------------------------------------------------
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbSaleOrderStatusConcept tmp			WITH (NOLOCK)
					WHERE tmp.sosc_approveIfPreInvoiceCollection = 1
			)
		BEGIN
			UPDATE tbSaleOrderStatus
				SET	sos_ok = 1
				FROM tbSaleOrderStatus					sos		WITH (NOLOCK)
				INNER JOIN tbCommercialTransactionsTmp	tmp		WITH (NOLOCK)
					ON	tmp.ctct_guid			= @guid				AND
						tmp.ctct_origin			= 'h'
				INNER JOIN tbCommercialTransactions  AS tct		WITH (NOLOCK)
					ON	tct.comp_id				= tmp.comp_id			AND
						tct.ct_transaction		= tmp.ctct_transaction	AND
						tct.ct_soh_bra_id		= sos.bra_id			AND
						tct.ct_soh_id			= sos.soh_id
				INNER JOIN tbDocumentsFile			 AS tdf		WITH (NOLOCK)
					ON	tdf.comp_id				= tct.comp_id		AND
						tdf.bra_id				= tct.bra_id		AND
						tdf.df_id				= tct.df_id
				INNER JOIN tbSaleOrderStatusConcept  AS tsosc	WITH (NOLOCK)
					ON	tsosc.comp_id			= sos.comp_id		AND
						tsosc.sosc_id			= sos.sosc_id
			WHERE	tmp.comp_id					= @comp_id			AND
					tmp.ctct_guid				= @guid				AND
					tmp.ctct_origin				= 'h'				AND
					tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL AND
					tsosc.sosc_approveIfPreInvoiceCollection = 1	AND
					tct.ct_soh_bra_id			= sos.bra_id		AND
					tct.ct_soh_id				= sos.soh_id
		END
	-- --------------------------------------------------------------------------------------------







	-- --------------------------------------------------------------------------------------------
	delete	dbo.tbCommercialTransactionsTmp	--WITH (ROWLOCK)
		where	ctct_guid		=	@guid
	-- --------------------------------------------------------------------------------------------



END
GO



