-- MOH
-- MOS: 02-2009
-- Inserta Movimientos desde
-- temporales a definitivos.-
-- Se utiliza tanto para PAGOS como para COBRANZAS
-- -------------------------------

-- Log
-- MOS 09-2024
-- Marca como APROBADOS todos los estados de pedidos que digan que si se cobra un pedido deben Auto-Aprobarse.	siempre y cuando el RECIBO NO esté aplicado a NADA y sea por el importe mayor o igual al del pedido.







CREATE PROCEDURE [dbo].[spCollection_insertHow]
(
	@comp_id					INT,
	@guid						uniqueidentifier,
	@ct_transaction				int,
	@cn_id						INT,
	@intForcedExchangeCurrency1 AS INT,
	@intForcedExchangeCurrency2 AS INT,
	@decForcedExchange		    AS DECIMAL(19,6),
	@return_value				int				output,
	@ret_ErrorCode				int				output,
	@ret_ErrorDescription		varchar(200)	output
)
AS


BEGIN


	set nocount on
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-19
	-- Parte		: 480
	-- Description	: Agregado del campo DNI en la carga de cheques en cobranzas
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-05-03
	-- TN			: 85
	-- Description	: Se agrega la condición de where para que excluya los documentos en la actualización de tbBankingTransaction
	--				  que la haber cambiado la condición de inserción tomaba los documentos
	-- =================================================================================================================



	-- -------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------
	/*
	declare	@guid						uniqueidentifier,
			@ct_transaction				int,
			@cn_id						INT,
			@intForcedExchangeCurrency1 AS INT,
			@intForcedExchangeCurrency2 AS INT,
			@decForcedExchange		    AS DECIMAL(19,6),
			@return_value				int,
			@ret_ErrorCode				int,
			@ret_ErrorDescription		varchar(200)

	select	@guid						='dfc441e4-1895-497a-b1c8-f6487752b029',
			@ct_transaction				=6444,
			@cn_id						=1,
			@intForcedExchangeCurrency1	=1,
			@intForcedExchangeCurrency2 =1,
			@decForcedExchange		    =1
	*/
	-- -------------------------------------------------------


	--begin try


	set 	@return_value			= 0
	set		@ret_ErrorCode			= 0
	set		@ret_ErrorDescription	= ' '


	DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT		-- MOS 06-2020
    --SAVE TRANSACTION traPROTECT
    --BEGIN TRANSACTION
    BEGIN TRY


	-- ---------------------------------------------------------------------
	-- Como fuiste un reverendo HDP hay que hacer las cosas así . . .
	-- obtener fecha y sucursal del comprobante
		-- ---------------------------------------------------------------------
	declare @bra_curr_id	int,
			@cust_curr_id	int,
			@exchange		decimal(19,6)
	declare @isPurchase		bit
	DECLARE @now			DATETIME,
			@bra_id			INT
	DECLARE @decTotalOfReceiptUnapplied DECIMAL(19,4) = 0

	SELECT	@now			= tct.ct_date,	--tb2.bra_processingDate,
			@bra_id			= tct.bra_id,
			@isPurchase		= td.sd_isPurchase,
			@bra_curr_id	= curr_id_transaction,
			@cust_curr_id	= ct_ACurrency,
			@exchange		= ct_ACurrencyExchange	,
			@decTotalOfReceiptUnapplied	=
									CASE
										WHEN tct.ct_ATotal = tct.ct_ABalance THEN tct.ct_total
										ELSE									  0
									END
		FROM	tbCommercialTransactions tct					WITH (NOLOCK)
		INNER JOIN tbsysDocuments		AS td					WITH (NOLOCK)
			ON td.sd_id = tct.sd_id
		INNER JOIN tbBranch tb2									WITH (NOLOCK)
			ON	tb2.comp_id		= tct.comp_id
			AND tb2.bra_id		= tct.bra_id
		WHERE 	tct.comp_id			= @comp_id			AND
				tct.ct_transaction  = @ct_transaction
	/*******************************************************************************************************/



	/*******************************************************************************************************/
	/* setear la cantidad de decimales                                                                     */
	declare @intDecimal2Round int
	set		@intDecimal2Round = 2
	/*******************************************************************************************************/




	/*******************************************************************************************************/
	/* recuperar sd_isPurchase de transacción                                                                */
	/* si @isPurchase es False es una COBRANZA FORRO, NO PAGO!!!  y si es True es un  PAGO!!!!				*/
	--PD: quen fue el ENFERMO HIJO DE RE MIL PUTAS QUE NO PASO LA PUTA COMPAÑÍA!!!!!!!
	--declare @isPurchase bit
	--SELECT	@isPurchase = td.sd_isPurchase
	--	FROM tbsysDocuments td										WITH (NOLOCK)
	--	WHERE	td.sd_id = (SELECT	tct.sd_id
	--    							FROM	tbCommercialTransactions tct	WITH (NOLOCK)
	--	     					WHERE   tct.ct_transaction = @ct_transaction)
	-- A veces pienso que se puede sewr muuyyy HDP prograsmando pero evidentemente me quedo corto! ! !
	/*******************************************************************************************************/




	/*******************************************************************************************************/
	/* recuperar la moneda de la transacción, la moneda del cliente y el cambio entre ellas                */
	--declare @bra_curr_id	int,
	--		@cust_curr_id	int,
	--		@exchange		decimal(19,6)

	--select	@bra_curr_id	= curr_id_transaction,
	--		@cust_curr_id	= ct_ACurrency,
	--		@exchange		= ct_ACurrencyExchange
	--	from	dbo.[tbCommercialTransactions]			WITH (NOLOCK)
	--	where	ct_transaction = @ct_transaction

	--select	@bra_curr_id, @cust_curr_id, @exchange
	/*******************************************************************************************************/


	-- ----------------------------------------------------------------------------------------
	-- Movimientos de Cuenta Contable
	-- ----------------------------------------------------------------------------------------
	INSERT INTO tbAccountantMovements
	(
		comp_id,
		-- atcm_id -- this column value is auto-generated
		ct_transaction,
		acc_count_id,
		atcm_total,
		curr_id,
		atcm_reference
	)
		SELECT	tamt.comp_id,
				@ct_transaction,
				tamt.acc_count_id,
				tamt.atcm_total,
				tamt.curr_id,
				tamt.atcm_reference
			FROM tbAccountantMovementsTMP AS tamt
			WHERE	tamt.comp_id		= @comp_id AND
					tamt.atcmTmp_guid	= @guid

	BEGIN TRY
		delete	dbo.[tbAccountantMovementsTMP]	WITH (ROWLOCK)
			where	[atcmTmp_guid]				=	@guid
	END TRY
	BEGIN CATCH
		Set @ret_ErrorCode			= -1
		Set	@ret_ErrorDescription	= '53 - ' + ERROR_MESSAGE()
	END CATCH
	-- ----------------------------------------------------------------------------------------





	-- ----------------------------------------------------------------------------------------
	-- Movimientos de EFECTIVO
	-- ----------------------------------------------------------------------------------------
	BEGIN TRY
		Insert into tbMoneyMovements	WITH (ROWLOCK)
		(
				comp_id,
				bra_id,
				ct_transaction,
				mm_total,
				curr_id,
				mm_BranchCurrencyExchange,
				mm_isCancelled,
				svtt_id,
				mm_desc
		)
		select	cmt.[comp_id],
				cmt.[bra_id],
				@ct_transaction,
				cmt.[cmt_amount],
				cmt.[curr_id],
				convert(decimal(19,6),
				round(dbo.fnGetExchange2(	cmt.comp_id,
											1,
											cmt.curr_id,
											@bra_curr_id,
											@intForcedExchangeCurrency1,
											@intForcedExchangeCurrency2,
											@decForcedExchange,
											'FALSE'),6)),
				'false',
				1,
				cmt.cmt_desc
		from	dbo.[tbCashMovementsTmp]	cmt			WITH (NOLOCK)
		where	cmt.[cmt_guid]			=	@guid


	END TRY
	BEGIN CATCH
		Set @ret_ErrorCode			= -1
		Set	@ret_ErrorDescription	= '01 - ' + ERROR_MESSAGE()+ '* 111'
		RETURN
	END CATCH


	-- ----------------------------------------------------------------------------------------
	-- Movimientos de Efectivo en CAJA
	-- ----------------------------------------------------------------------------------------
	DECLARE @intErrorTryCount AS INT
	SET		@intErrorTryCount = 0
	GoToMe:
	BEGIN TRY
		insert into dbo.[tbCashMovements]		WITH (ROWLOCK)
		(
				[comp_id],
				[bra_id],
				[cm_cd],
				[ca_id],
				[cm_debit],
				[cm_credit],
				[curr_id],
				[cm_desc],
				[cn_id],
				[ct_transaction],
				[svt_id],
				[cm_BranchCurrencyExchange]
		)
		select	cmt.[comp_id],
				cmt.[bra_id],
				@now,
				cmt.[ca_id],
				case @isPurchase
					when 0 then cmt.[cmt_amount]
					ELSE 0
				END,
				case @isPurchase
					when 1 then cmt.[cmt_amount]
					ELSE 0
				END,
				cmt.[curr_id],
				cmt.[cmt_desc],
				@cn_id,
				@ct_transaction,
				1 /* Efectivo  */,
				convert(decimal(19,6),round(
					dbo.fnGetExchange2(	    cmt.comp_id,
											1,
											cmt.curr_id,
											@bra_curr_id,
											@intForcedExchangeCurrency1,
											@intForcedExchangeCurrency2,
											@decForcedExchange,
											'FALSE'),6))
		from	dbo.[tbCashMovementsTmp]	cmt							WITH (NOLOCK)
		where	cmt.[cmt_guid]			=	@guid


	END TRY
	BEGIN CATCH
		SET @intErrorTryCount = @intErrorTryCount + 1
		IF @intErrorTryCount < 50
			BEGIN
				GOTO GoToMe	--Chanchadita
			END
		Set @ret_ErrorCode			= -1
		Set	@ret_ErrorDescription	= '02 - ' + ERROR_MESSAGE() + '* 222'
		RETURN
	END CATCH


	-- ----------------------------------------------------------------------------------------
	BEGIN TRY
		delete	dbo.[tbCashMovementsTmp]	WITH (ROWLOCK)
		where	[cmt_guid]				=	@guid
	END TRY
	BEGIN CATCH
		Set @ret_ErrorCode			= -1
		Set	@ret_ErrorDescription	= '03 - ' + ERROR_MESSAGE()
	END CATCH
	-- ----------------------------------------------------------------------------------------







	IF @isPurchase = 'False' --Cobranza
		BEGIN
			-- ----------------------------------------------------------------------------------------
			-- Movimientos de Cheques a Cartera
			-- ----------------------------------------------------------------------------------------
			BEGIN TRY
				insert into dbo.[tbCheckPortfolio]		WITH (ROWLOCK)
				(
						[comp_id],
						[bra_id],
						[ct_transaction],
						[chp_number],
						[chp_total],
						[chp_EmissionDate],
						[chp_PayDate],
						[bn_id],
						[chp_BankBranch],
						[chp_BankBranchDescription],
						[chp_AccountNumber],
						[chp_taxNumber1],
						[chp_taxNumber2],
						[chp_taxNumber3],
						[chp_isOwn],
						[chp_isAvailable], --en pagos en false tbcheckportfoliomovements
						[chp_IsPayed],
						[chp_isRejected],
						[chp_isCancelled],
						[chp_isToOrder],
						[chp_Note],
						[curr_id],
						[country_id],
						[chp_isDocument],
						[chp_DocumentDescription],
						[chp_BranchCurrencyExchange],
						[chp_documentNumber],				--Parte:480
						[chp_QtyEndosos],
						bra_id_PortFolio,
						ba_id,
						chp_isElectronic
				)
				select	cpt.[comp_id],
						cpt.[bra_id],
						@ct_transaction,
						cpt.[chpt_number],
						cpt.[chpt_total],
						cpt.[chpt_EmissionDate],
						cpt.[chpt_PayDate],
						cpt.[bn_id],
						case cpt.[chpt_BankBranch]
							WHEN 0 THEN NULL
							ELSE cpt.[chpt_BankBranch]
						end,
						cpt.[chpt_BankBranchDescription],
						cpt.[chpt_AccountNumber],
						cpt.[chpt_taxNumber1],
						cpt.[chpt_taxNumber2],
						cpt.[chpt_taxNumber3],
						cpt.[chpt_isOwn],
						cpt.[chpt_isAvailable],
						'False',
						cpt.[chpt_isRejected],
						'False',
						cpt.[chpt_isToOrder],
						cpt.[chpt_Note],
						cpt.[curr_id],
						cpt.[country_id],
						cpt.[chpt_isDocument],
						cpt.[chpt_DocumentDescription],
						convert(decimal(19,6),round(
							dbo.fnGetExchange2(	cpt.comp_id,
													1,
													cpt.curr_id,
													@bra_curr_id,
													@intForcedExchangeCurrency1,
													@intForcedExchangeCurrency2,
													@decForcedExchange,
													'FALSE'),6)),
						cpt.chpt_documentNumber,				--Parte:480
						cpt.chpt_QtyEndosos,
						cpt.[bra_id],
						cpt.ba_id,
						ISNULL(cpt.chp_isElectronic,'False')

				from	dbo.[tbCheckPortfolioTmp]	cpt				WITH (NOLOCK)
				where   cpt.[chpt_guid]			=	@guid
			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '04 - ' + ERROR_MESSAGE()
			END CATCH



			-- Asiento de Caja ------------------------------------------------------------------------
			BEGIN TRY
				insert into dbo.[tbCashMovements]		WITH (ROWLOCK)
				(
						[comp_id],
						[bra_id],
						[cm_cd],
						[ca_id],
						[cm_debit],
						[cm_credit],
						[curr_id],
						[cm_desc],
						[cn_id],
						[ct_transaction],
						[svt_id],
						[cm_BranchCurrencyExchange]
				)
				select	cpt.[comp_id],
						cpt.[bra_id],
						@now,
						(Select bra_CollectionCaId_Cheque from tbBranch  br
						 Where br.comp_id = cpt.comp_id And br.bra_id = cpt.bra_id),
						cpt.[chpt_total],
						0,
						cpt.[curr_id],
						cpt.[chpt_number],
						@cn_id,
						@ct_transaction,
						CASE
							WHEN cpt.chpt_isDocument = 'true' THEN 4    /* Cheques de Terceros */
							ELSE 2										/* Documentos */
						END ,
						convert(decimal(19,6),round(
							dbo.fnGetExchange2(	cpt.comp_id,
													1,
													cpt.curr_id,
													@bra_curr_id,
													@intForcedExchangeCurrency1,
													@intForcedExchangeCurrency2,
													@decForcedExchange,
													'FALSE'),6))
				from	dbo.[tbCheckPortfolioTmp]	cpt										WITH (NOLOCK)
				where   cpt.[chpt_guid]			=	@guid
			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '05 - ' + ERROR_MESSAGE()
			END CATCH


			-- Borrado de Temporal --------------------------------------------------------------------
			BEGIN TRY
				delete	dbo.[tbCheckPortfolioTmp]	WITH (ROWLOCK)
				where   [chpt_guid]				=	@guid
			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '06 - ' + ERROR_MESSAGE()
			END CATCH

		END

	ELSE  --Pagos

		BEGIN
			-- --------------------------------------------------------------------------
			-- Pago con Valores de Cartera.
			-- --------------------------------------------------------------------------
			BEGIN TRY

				INSERT INTO tbCheckPortfolioMovements	WITH (ROWLOCK)
				(
					comp_id,
					bra_id,
					chp_id,
					ct_transaction,
					mm_isCancelled,
					svtt_id,
					ba_id,
					bt_id
				)
					SELECT	tbcp.comp_id,
							@bra_id,
							tbcp.chp_id,
							@ct_transaction,
							'False',
							30,
							NULL,
							NULL
					FROM	tbCheckPortfolio tbcp						WITH (NOLOCK)
					WHERE	tbcp.chp_guid	= @guid

			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '07 - ' + ERROR_MESSAGE()
			END CATCH

			BEGIN TRY
				UPDATE	tbCheckPortfolio
				SET		chp_isAvailable		= 'False',
						chp_isEditing		= 'False',
						chp_IsPayed			= 'True'
				WHERE	chp_guid			= @guid
			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '08 - ' + ERROR_MESSAGE()
			END CATCH



			-- Asiento de Caja ------------------------------------------------------------------------
			BEGIN TRY
				insert into dbo.[tbCashMovements]	WITH (ROWLOCK)
				(
						[comp_id],
						[bra_id],
						[cm_cd],
						[ca_id],
						[cm_debit],
						[cm_credit],
						[curr_id],
						[cm_desc],
						[cn_id],
						[ct_transaction],
						[svt_id],
						[cm_BranchCurrencyExchange]
				)
				select	cpt.[comp_id],
						@bra_id,
						@now,
						(Select br.bra_PaymentCaId_ChequePortfolio from tbBranch  br
						 Where br.comp_id = cpt.comp_id And br.bra_id = @bra_id),
						0,
						cpt.[chp_total],
						cpt.[curr_id],
						cpt.[chp_number],
						@cn_id,
						@ct_transaction,
						2 /* Cheques de Terceros */,
						convert(decimal(19,6),round(
							dbo.fnGetExchange2(	cpt.[comp_id],
													1,
													cpt.[curr_id],
													@bra_curr_id,
													@intForcedExchangeCurrency1,
													@intForcedExchangeCurrency2,
													@decForcedExchange,
													'FALSE'),6))
				from	dbo.[tbCheckPortfolio]	cpt							WITH (NOLOCK)
				where   cpt.[chp_guid]			=	@guid

				-- Borra el guid unicamente.  Dejar esto aca pls.
				UPDATE	tbCheckPortfolio		WITH (ROWLOCK)
					SET		chp_guid			= NULL
					WHERE	chp_guid			= @guid


			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '09 - ' + ERROR_MESSAGE()
			END CATCH

		END




	IF @isPurchase = 'True' -- Pagos, Documentos Emitidos.-
		BEGIN
			-- ----------------------------------------------------------------------------------------
			-- Documentos Emitidos
			-- ----------------------------------------------------------------------------------------
			BEGIN TRY

			INSERT INTO dbo.tbEmmitedChecks		WITH (ROWLOCK)
						(	comp_id,
							bra_id,
							ba_id,
							ec_Number,
							ec_Total,
							curr_id,
							ec_EmissionDate,
							ec_PayDate,
							ct_transaction,
							ec_Note,
							ec_isCancelled,
							ec_isPaid,
							ec_isPrinted,
							ec_exchangeToBranchCurrency,
							ec_not_to_order,
							ec_isDocument
						)
				select	cpt.[comp_id],
						cpt.[bra_id],
						NULL,
						cpt.[chpt_number],
						cpt.[chpt_total],
						cpt.curr_id,
						cpt.[chpt_EmissionDate],
						cpt.[chpt_PayDate],
						@ct_transaction,
						cpt.[chpt_Note] +
						CASE WHEN cpt.[chpt_Note] <> '' AND cpt.chpt_DocumentDescription <> '' THEN ' // ' ELSE '' END +
						cpt.chpt_DocumentDescription,
						'False',
						'False',
						'False',
						convert(decimal(19,6),round(
							dbo.fnGetExchange2(	cpt.comp_id,
													1,
													cpt.curr_id,
													@bra_curr_id,
													@intForcedExchangeCurrency1,
													@intForcedExchangeCurrency2,
													@decForcedExchange,
													'FALSE'),6)),
						'False',
						'True'

				from	dbo.[tbCheckPortfolioTmp]	cpt				WITH (NOLOCK)
				where   cpt.[chpt_guid]			=	@guid
				AND		cpt.chpt_isDocument		=	'true'

			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '04 - ' + ERROR_MESSAGE()
			END CATCH



			-- Asiento de Caja ------------------------------------------------------------------------
			BEGIN TRY
				insert into dbo.[tbCashMovements]		WITH (ROWLOCK)
				(
						[comp_id],
						[bra_id],
						[cm_cd],
						[ca_id],
						[cm_debit],
						[cm_credit],
						[curr_id],
						[cm_desc],
						[cn_id],
						[ct_transaction],
						[svt_id],
						[cm_BranchCurrencyExchange]
				)
				select	cpt.[comp_id],
						cpt.[bra_id],
						@now,
						(Select bra_PaymentCaId_Documents from tbBranch  br
						 Where br.comp_id = cpt.comp_id And br.bra_id = cpt.bra_id),
						cpt.[chpt_total],
						cpt.[chpt_total],
						cpt.[curr_id],
						cpt.[chpt_number],
						@cn_id,
						@ct_transaction,
						CASE
							WHEN cpt.chpt_isDocument = 'true' THEN 4    /* Cheques de Terceros */
							ELSE 2										/* Documentos */
						END ,
						convert(decimal(19,6),round(
							dbo.fnGetExchange2(	    cpt.comp_id,
													1,
													cpt.curr_id,
													@bra_curr_id,
													@intForcedExchangeCurrency1,
													@intForcedExchangeCurrency2,
													@decForcedExchange,
													'FALSE'),6))
				from	dbo.[tbCheckPortfolioTmp]	cpt							WITH (NOLOCK)
				where   cpt.[chpt_guid]			=	@guid
				AND		cpt.chpt_isDocument		=	'true'

			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '05 - ' + ERROR_MESSAGE()
			END CATCH

			-- Borrado de Temporal --------------------------------------------------------------------
			BEGIN TRY
				delete	dbo.[tbCheckPortfolioTmp]	WITH (ROWLOCK)
				where   [chpt_guid]				=	@guid
				AND		chpt_isDocument			=	'true'
			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '06 - ' + ERROR_MESSAGE()
			END CATCH

		END







	IF @isPurchase = 'False' --Cobranza
		BEGIN

			-- ----------------------------------------------------------------------------------------
			-- Movimientos de Tarjetas de Credito
			-- ----------------------------------------------------------------------------------------
			BEGIN TRY
				insert into dbo.[tbCreditCardMovements]		WITH (ROWLOCK)
				(
						[comp_id],
						[bra_id],
						[ct_transaction],
						[cc_id],
						[ccm_Total],
						[ccm_cardNumber],
						[ccm_cardEmissionDate],
						[ccm_cardExpirationDate],
						[ccm_customerDocumentNumber],
						[ccm_customerName],
						[ccm_receiptNumber],
						[ccm_AutorizationCode],
						[cccm_id],
						[ccm_BranchCurrencyExchange],
						curr_id,
						ccm_lote,
						ccp_id,
						cct_id,
						ccv_id,
						mlo_id,
						JSonData
				)
				select	ccmt.[comp_id],
						ccmt.[bra_id],
						@ct_transaction,
						ccmt.[cc_id],
						ccmt.[ccmt_Total],
						ccmt.[ccmt_cardNumber],
						ccmt.[ccmt_cardEmissionDate],
						ccmt.[ccmt_cardExpirationDate],
						ccmt.[ccmt_customerDocumentNumber],
						ccmt.[ccmt_customerName],
						ccmt.[ccmt_receiptNumber],
						dbo.fnStrAllTrim (ccmt.[ccmt_AutorizationCode]),
						ccmt.[cccm_id],
						convert(decimal(19,6),round(
							dbo.fnGetExchange2(	    ccmt.comp_id,
													1,
													cc.curr_id,
													@bra_curr_id,
													@intForcedExchangeCurrency1,
													@intForcedExchangeCurrency2,
													@decForcedExchange,
													'FALSE'),6)),
						cc.curr_id,
						ccmt.ccmt_lote,
						ccmt.ccp_id,
						ccmt.cct_id,
						ccmt.ccv_id,
						ccmt.mlo_id,
						ccmt.JSonData

				from    dbo.tbCreditCardMovementsTmp		ccmt						WITH (NOLOCK)
						inner join dbo.tbCreditCard		cc							WITH (NOLOCK)
							on	cc.comp_id			=	ccmt.comp_id	AND
								cc.cc_id			=	ccmt.cc_id
						-- MOS 12-2017
						LEFT JOIN tbCreditCard_Voucher tccv							WITH (NOLOCK)
							ON	tccv.comp_id	= ccmt.comp_id	AND
								tccv.ccv_id		= ccmt.ccv_id
				where	ccmt.ccmt_guid			=	@guid	AND
						ISNULL(tccv.ccv_status,4)	IN (4,104)					--** wekfbwekfbwejkfbwekj 345634   SON 3


				-- Marca el voucher como APLICADO
				UPDATE tbCreditCard_Voucher		WITH (ROWLOCK)
					SET	ccv_status =	CASE									--** wekfbwekfbwejkfbwekj 345634   SON 3
											WHEN ccv_status = 4		THEN 5
											WHEN ccv_status = 104	THEN 105
											ELSE						 ccv_status
										END
					FROM tbCreditCard_Voucher				tccv
					INNER JOIN tbCreditCardMovementsTmp		ccmt	WITH (NOLOCK)
						ON	ccmt.comp_id	= tccv.comp_id AND
							ccmt.ccv_id		= tccv.ccv_id
					where	ccmt.ccmt_guid	= @guid AND
							tccv.ccv_status	IN (4,104)
					--==
					--IF @@ROWCOUNT = 0
					--	BEGIN
					--		SELECT 1 / 0
					--	END


			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '10 - ' + ERROR_MESSAGE()
			END CATCH


			-- Asiento de Caja ------------------------------------------------------------------------
			BEGIN TRY
				insert into dbo.[tbCashMovements]		WITH (ROWLOCK)
				(
						[comp_id],
						[bra_id],
						[cm_cd],
						[ca_id],
						[cm_debit],
						[cm_credit],
						[curr_id],
						[cm_desc],
						[cn_id],
						[ct_transaction],
						[svt_id],
						[cm_BranchCurrencyExchange],
						cagt_id
				)
				select	ccmt.[comp_id],
						ccmt.[bra_id],
						@now,
						(Select bra_CollectionCaId_CreditCard
							from tbBranch						br WITH (NOLOCK)
							Where	br.comp_id	= ccmt.comp_id And
									br.bra_id	= ccmt.bra_id),
						ccmt.[ccmt_Total],
						0,
						cc.curr_id,
						ccmt.[ccmt_receiptNumber],
						@cn_id,
						@ct_transaction,
						5 /* Tarjeta de Credito */,
						convert(decimal(19,6),round(
							dbo.fnGetExchange2(	    ccmt.comp_id,
													1,
													cc.curr_id,
													@bra_curr_id,
													@intForcedExchangeCurrency1,
													@intForcedExchangeCurrency2,
													@decForcedExchange,
													'FALSE'),6)),
						cc.cagt_id
				from    dbo.[tbCreditCardMovementsTmp]		ccmt			WITH (NOLOCK)
						inner join dbo.[tbCreditCard]		cc				WITH (NOLOCK)
						on	cc.comp_id			=	ccmt.comp_id
						and	cc.cc_id			=	ccmt.cc_id

				where	ccmt.[ccmt_guid]		=	@guid
			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '11 - ' + ERROR_MESSAGE()
			END CATCH


			-- Borrado de Temporal --------------------------------------------------------------------
			BEGIN TRY
				delete	dbo.[tbCreditCardMovementsTmp]		WITH (ROWLOCK)
				where	[ccmt_guid]				=	@guid
			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '12 - ' + ERROR_MESSAGE()
			END CATCH


		END







	-- ----------------------------------------------------------------------------------------
	-- Movimientos de Depositos Bancarios (Transferencia Bancaria)
	-- ----------------------------------------------------------------------------------------

	BEGIN TRY
		insert into dbo.[tbBankingTransactions]		WITH (ROWLOCK)
		(
				[comp_id],
				[ba_id],
				[bra_id],
				[btt_id],
				[ec_id],
				[chp_id],
				[bt_total],
				[curr_id],
				[bt_imputationDate],
				[bt_isConciliated],
				[bt_isCancelled],
				[ct_transaction],
				[ccm_id],
				[bt_note],
				[bt_Number],
				[bt_BranchCurrencyExchange]
		)
		select	btt.[comp_id],
				btt.[ba_id],
				btt.[bra_id],
				btt.[btt_id],
				btt.[ec_id],
				btt.[chp_id],
				btt.[btt_total],
				btt.[curr_id],
				btt.[btt_imputationDate],
				btt.[btt_isConciliated],
				btt.[btt_isCancelled],
				@ct_transaction,
				btt.[ccm_id],
				ISNULL(btt.[btt_note],''),
				ISNULL(btt.[btt_Number],''),
				convert(decimal(19,6),round(
					dbo.fnGetExchange2(	    btt.comp_id,
											1,
											btt.curr_id,
											@bra_curr_id,
											@intForcedExchangeCurrency1,
											@intForcedExchangeCurrency2,
											@decForcedExchange,
											'FALSE'),6))
		from	dbo.[tbBankingTransactionsTmp]		btt				WITH (NOLOCK)
		where   btt.[btt_guid]			=	@guid
	END TRY
	BEGIN CATCH
		Set @ret_ErrorCode			= -1
		Set	@ret_ErrorDescription	= '13 - ' + ERROR_MESSAGE()
	END CATCH


	-- Verifica que si hay algun voucher asignado no este ya como Procesado,
	-- por si otro usuario lo uso, ya que no tiene control x isEditing
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbBankingTransactionsTmp tbtt					WITH (NOLOCK)
					INNER JOIN tbBankingVouchers4BanckTransferCollection tbvbtc		WITH (NOLOCK)
						ON	tbvbtc.comp_id	= tbtt.comp_id AND
							tbvbtc.v4c_id	= tbtt.v4c_id
					where   tbtt.btt_guid = @guid AND
						   (tbvbtc.v4c_isCollected='True' OR tbvbtc.v4c_isCancelled = 'True')
			)
		BEGIN
			Set @ret_ErrorCode			= -1
			Set	@ret_ErrorDescription	= '1331 - ' + 'Voucher Used'
			RETURN
		END
	ELSE
		BEGIN
			UPDATE tbBankingVouchers4BanckTransferCollection	WITH (ROWLOCK)
				SET v4c_isCollected												= 'True',
					tbBankingVouchers4BanckTransferCollection.ct_transaction	= @ct_transaction
				FROM tbBankingTransactionsTmp tbtt						WITH (NOLOCK)
				INNER JOIN tbBankingVouchers4BanckTransferCollection tbvbtc
					ON	tbvbtc.comp_id	= tbtt.comp_id AND
						tbvbtc.v4c_id	= tbtt.v4c_id
				where   tbtt.btt_guid   = @guid
		END
	-- ---




	-- Asiento de Caja ------------------------------------------------------------------------
	BEGIN TRY
		insert into dbo.[tbCashMovements]		WITH (ROWLOCK)
		(
				[comp_id],
				[bra_id],
				[cm_cd],
				[ca_id],
				[cm_debit],
				[cm_credit],
				[curr_id],
				[cm_desc],
				[cn_id],
				[ct_transaction],
				[svt_id],
				[cm_BranchCurrencyExchange],
				cagt_id
		)
		select	btt.[comp_id],
				btt.[bra_id],
				@now,
				CASE @isPurchase
					WHEN 'False'	THEN
						(Select bra_CollectionCaId_Transfer from tbBranch  br
						Where br.comp_id = btt.comp_id And br.bra_id = btt.bra_id)
					WHEN 'True'		THEN
						(SELECT br.bra_PaymentCaId_Transfer from tbBranch  br
						Where br.comp_id = btt.comp_id And br.bra_id = btt.bra_id)
				END,
				btt.btt_total,
				btt.btt_total,
				btt.curr_id,
				ltrim(rtrim(btt_note)) + '/' + ltrim(rtrim(btt_Number)),
				@cn_id,
				@ct_transaction,
				6 /* Transferencia Bancaria */,
				convert(decimal(19,6),round(
					dbo.fnGetExchange2(	    btt.comp_id,
											1,
											btt.curr_id,
											@bra_curr_id,
											@intForcedExchangeCurrency1,
											@intForcedExchangeCurrency2,
											@decForcedExchange,
											'FALSE'),6)),
				tba.cagt_id

		from	dbo.[tbBankingTransactionsTmp]		btt			WITH (NOLOCK)
		LEFT JOIN tbBankingAccounts				 AS tba			WITH (NOLOCK)
			ON	tba.comp_id		= btt.comp_id AND
				tba.ba_id		= btt.ba_id
		where   btt.[btt_guid]	=	@guid
	END TRY
	BEGIN CATCH
		Set @ret_ErrorCode			= -1
		Set	@ret_ErrorDescription	= '14 - ' + ERROR_MESSAGE()
	END CATCH


	-- Eliminar temporal de transacciones bancarias -------------------------------------------
	BEGIN TRY
		delete	dbo.[tbBankingTransactionsTmp]	WITH (ROWLOCK)
		where   [btt_guid]				=	@guid
	END TRY
	BEGIN CATCH
		Set @ret_ErrorCode			= -1
		Set	@ret_ErrorDescription	= '15 - ' + ERROR_MESSAGE()
	END CATCH




	-----------------------------------------------------------------------------------------------
	-- Se saca un nuevo numero de Retencion para cada retencion generada por el sistema
	-- (NO Manuales.!!)
	-----------------------------------------------------------------------------------------------
	IF @isPurchase = 'True'
		BEGIN

			DECLARE @intTmt_transaction		AS INT
			DECLARE @strNumber				AS NVARCHAR(200)
			DECLARE @intTaxId				AS INT
			DECLARE @intBraId				AS INT
			DECLARE @intCompId				AS INT
			DECLARE @strPrefijo				AS NVARCHAR(150)
			DECLARE curSetRetentionNumber CURSOR LOCAL  FAST_FORWARD FOR
				SELECT	tmt.comp_id,
						tmt.bra_id,
						tmt.tax_id,
						tmt.tmt_transaction
				from	dbo.[tbTaxMovementsTmp]			tmt			WITH (NOLOCK)
				LEFT JOIN tbTaxName4RetentionRelations ttnrr		WITH (NOLOCK)
					ON ttnrr.comp_id	= tmt.comp_id	AND
					   ttnrr.bra_id		= tmt.bra_id	AND
					   ttnrr.tax_id		= tmt.tax_id
				where   tmt.[tmt_guid]	= @guid			AND
						(tmt.tmt_docNumber IS NULL	 OR ttnrr.ret_AutoNumberManualRetentions = 'True')	AND
						(tmt.isCalculated	= 'True' OR ttnrr.ret_AutoNumberManualRetentions = 'True')

			OPEN		curSetRetentionNumber
			FETCH NEXT FROM curSetRetentionNumber
				INTO	@intCompId,
						@intBraId,
						@intTaxId,
						@intTmt_transaction
			WHILE @@FETCH_STATUS = 0
				BEGIN

					EXEC spTaxNameRetentionCounters_getNextValue
						@intCompId,
						@intBraId,
						@intTaxId,
						@strNumber OUTPUT

					SET @strNumber = DBO.fnStrAllTrim(@strNumber)
					SET @strNumber = DBO.fnStrPADL(@strNumber,8,'0')

					SELECT		@strPrefijo		=  IsNull(ttnrr.ret_prefijo,'')
						FROM	tbTaxName4RetentionRelations ttnrr					WITH (NOLOCK)
						WHERE	ttnrr.comp_id	= @intCompId	AND
								ttnrr.bra_id	= @intBraId		AND
								ttnrr.tax_id	= @intTaxId

					UPDATE tbTaxMovementsTmp	WITH (ROWLOCK)
						SET
							tmt_docPointOfSale	= 0,
							tmt_docNumber		= @strPrefijo + @strNumber,
							tmt_docDate			= @now
						WHERE	comp_id			= @intCompId			AND
								tmt_transaction = @intTmt_transaction

					FETCH NEXT FROM curSetRetentionNumber
						INTO	@intCompId,
								@intBraId,
								@intTaxId,
								@intTmt_transaction

				END
			CLOSE		curSetRetentionNumber
			DEALLOCATE	curSetRetentionNumber

		END
	-----------------------------------------------------------------------------------------------



	-- ----------------------------------------------------------------------------------------
	-- Movimientos de Retenciones
	-- ----------------------------------------------------------------------------------------
	BEGIN TRY

		IF @isPurchase = 'True'
			BEGIN

				insert into dbo.[tbTaxMovements]	WITH (ROWLOCK)
				(
						[comp_id],
						[bra_id],
						[ct_transaction],
						[it_transaction],
						[pcm_id],
						[tm_cd],
						[tax_id],
						[tm_subtotal],
						[percentaje],
						[tm_total],
						[curr_id],
						[tm_docKindOf],
						[tm_docPointOfSale],
						[tm_docNumber],
						[tm_docDate],
						[tm_originalDocument],
						[State_Id],
						[Country_Id],
						[tm_originalDocumentTypeOf],
						[puco_id],
						tm_isManualTax
				)
				select	tmt.comp_id,
						tmt.bra_id,
						@ct_transaction,
						null,
						null,
						@now,
						tmt.tax_id,
						tmt.tmt_subtotal,
						tmt.percentaje,
						tmt.tmt_total,
						tmt.curr_id,
						tmt.tmt_docKindOf,
						CASE
							WHEN tmt.tmt_docPointOfSale IS NOT NULL THEN tmt.tmt_docPointOfSale
							ELSE 0
						END,
						CASE
							WHEN tmt.tmt_docNumber IS NOT NULL THEN tmt.tmt_docNumber
							ELSE ''
						END,
						CASE
							WHEN tmt.tmt_docDate IS NOT NULL  THEN tmt.tmt_docDate
							ELSE @now
						END,
						tmt.tmt_originalDocument,
						tmt.State_Id,
						tmt.Country_Id,
						tmt.tmt_originalDocumentTypeOf,
						NULL,
						CASE
							WHEN tmt.isCalculated = 'True' THEN 'False'
							ELSE								'True'
						END

					from	dbo.[tbTaxMovementsTmp]			tmt				WITH (NOLOCK)
--					INNER JOIN tbTaxName4RetentionRelations tmp3  -- NOOOOOOOOOOOO
--						ON	tmp3.comp_id	= tmt.comp_id	AND
--							tmp3.bra_id		= tmt.bra_id	AND
--							tmp3.tax_id		= tmt.tax_id
					where   tmt.[tmt_guid]		= @guid


			END

		ELSE

			BEGIN

				insert into dbo.[tbTaxMovements]	WITH (ROWLOCK)
				(
						[comp_id],
						[bra_id],
						[ct_transaction],
						[it_transaction],
						[pcm_id],
						[tm_cd],
						[tax_id],
						[tm_subtotal],
						[percentaje],
						[tm_total],
						[curr_id],
						[tm_docKindOf],
						[tm_docPointOfSale],
						[tm_docNumber],
						[tm_docDate],
						[tm_originalDocument],
						[State_Id],
						[Country_Id],
						[tm_originalDocumentTypeOf],
						[puco_id]
				)
				select	tmt.comp_id,
						tmt.bra_id,
						@ct_transaction,
						null,
						null,
						@now,
						tmt.tax_id,
						tmt.tmt_subtotal,
						tmt.percentaje,
						tmt.tmt_total,
						tmt.curr_id,
						tmt.tmt_docKindOf,
						CASE
							WHEN tmt.tmt_docPointOfSale IS NOT NULL THEN tmt.tmt_docPointOfSale
							ELSE 0
						END,
						CASE
							WHEN tmt.tmt_docNumber IS NOT NULL THEN tmt.tmt_docNumber
							ELSE ''
						END,
						CASE
							WHEN tmt.tmt_docDate IS NOT NULL  THEN tmt.tmt_docDate
							ELSE @now
						END,
						tmt.tmt_originalDocument,
						tmt.State_Id,
						tmt.Country_Id,
						tmt.tmt_originalDocumentTypeOf,
						NULL

					from	dbo.[tbTaxMovementsTmp]			tmt			WITH (NOLOCK)
					where   tmt.[tmt_guid]		= @guid


			END






	END TRY
	BEGIN CATCH
		Set @ret_ErrorCode			= -1
		Set	@ret_ErrorDescription	= '16 - ' + ERROR_MESSAGE()
	END CATCH



