							(Select br.bra_CollectionCaId_Cheque	from tbBranch  br
							Where br.comp_id = btt.comp_id And br.bra_id = btt.bra_id)
						WHEN 'True'		THEN
							(SELECT br.bra_PaymentCaId_Cheque		from tbBranch  br
							Where br.comp_id = btt.comp_id And br.bra_id = btt.bra_id)
					END,
					btt.ect_Total,
					btt.ect_Total,
					btt.curr_id,
					ltrim(rtrim(btt.ect_Note)) + '/' + ltrim(rtrim(btt.ect_Number)),
					@cn_id,
					@ct_transaction,
					6 /* Transferencia Bancaria */,
					convert(decimal(19,6),round(
						dbo.fnGetExchange2(	    btt.comp_id,
												1,
												btt.curr_id,
												@bra_curr_id,
