	IF @isPurchase = 'False' --Cobranza
		BEGIN

			BEGIN TRY

				DECLARE @curr_id4SaleOrderCollection_fixExchange AS INT = NULL
				DECLARE @intCustomerCurrency	AS INT = NULL
				DECLARE @intBranchCurrency		AS INT = NULL
				DECLARE @curr_id4Exchange	AS INT = NULL
				DECLARE @ct_dfExchange			AS DECIMAL(25,12) = 0
				SELECT  @curr_id4SaleOrderCollection_fixExchange	= tdf.curr_id4SaleOrderCollection_fixExchange,
						@intCustomerCurrency						= tc.curr_id,
						@intBranchCurrency							= tb.curr_id,
						@curr_id4Exchange							= tct.curr_id4Exchange,
						@ct_dfExchange								= tct.ct_curr_IdExchange
					FROM tbCommercialTransactions	AS tct	WITH (NOLOCK)
					INNER JOIN  tbDocumentsFile		AS tdf	WITH (NOLOCK)
						ON	tdf.comp_id = tct.comp_id	AND
							tdf.df_id	= tct.df_id
					INNER JOIN tbBranch				AS tb	WITH (NOLOCK)
						ON	tb.comp_id	= tct.comp_id	AND
							tb.bra_id	= tct.bra_id
					INNER JOIN tbCustomer			AS tc	WITH (NOLOCK)
						ON	tc.comp_id = tct.comp_id	AND
							tc.cust_id = tct.cust_Id
					WHERE	tct.comp_id			= @comp_id			AND
							tct.ct_transaction	= @ct_transaction


				IF	@curr_id4SaleOrderCollection_fixExchange IS NOT NULL AND
					@curr_id4SaleOrderCollection_fixExchange <> @curr_id4Exchange
					BEGIN
						SET @curr_id4SaleOrderCollection_fixExchange = NULL
					END

				UPDATE tbSaleOrderHeader	WITH (ROWLOCK)			-- MOS: 03-2020, reremplazo de MIERDA de abajo
					SET		soh_WithCollection		= 'True',
							soh_WithCollectionGUID	= @guid,

							-- ---------------------------------------------------------------------------------------------------
							-- MOS 05-2022: Para que quede guardado el Tipo de cambio al cual se cobró el pedido.
							-- SOLO GUARDAR si el RECIBO tiene el campo df_curr_id4SaleOrderCollection_fixExchange en NOT NULL
							-- ---------------------------------------------------------------------------------------------------
							 soh_Currency4Total			=	CASE
																WHEN @curr_id4SaleOrderCollection_fixExchange IS NOT NULL THEN  @curr_id4SaleOrderCollection_fixExchange
																ELSE soh_Currency4Total
															END,
							 soh_exchange2Currency4Total =	CASE
																WHEN @curr_id4SaleOrderCollection_fixExchange IS NOT NULL THEN  @ct_dfExchange
																ELSE soh_exchange2Currency4Total
															END,
							 curr_id4Exchange			=	CASE
																WHEN @curr_id4SaleOrderCollection_fixExchange IS NOT NULL THEN  @curr_id4SaleOrderCollection_fixExchange
																ELSE curr_id4Exchange
															END,
							 curr_idExchange =				CASE
																WHEN @curr_id4SaleOrderCollection_fixExchange IS NOT NULL THEN  1 / dbo.fnNoZDiv( @ct_dfExchange)
																ELSE curr_idExchange
															END,
							 soh_CustomerCurrency			=
															CASE
																WHEN @curr_id4SaleOrderCollection_fixExchange IS NOT NULL THEN  @curr_id4SaleOrderCollection_fixExchange
																ELSE soh_CustomerCurrency
															END,
							 soh_ExchangeToCustomerCurrency =
															CASE
																WHEN @curr_id4SaleOrderCollection_fixExchange IS NOT NULL THEN  1 / dbo.fnNoZDiv( @ct_dfExchange)
																ELSE soh_ExchangeToCustomerCurrency
															END,
							soh_persistExchange				= 'True',
							ct_transaction_preCollection	= @ct_transaction
							-- ---------------------------------------------------------------------------------------------------


					FROM tbSaleOrderHeader AS tsoh
					INNER JOIN tbCommercialTransactionsTmp tctt	WITH (NOLOCK)
						ON	tctt.comp_id			= tsoh.comp_id	AND
							tctt.bra_id				= tsoh.bra_id	AND
							tctt.ctct_transaction	= tsoh.soh_id
					WHERE	tctt.ctct_guid			= @guid	AND
							LOWER(tctt.ctct_origin) = 's'


				-- MOS 03-2020: No se quien fue el REVERENDO HIJO DE PUTA que hizo esto, lo hago bien arriba.
				--UPDATE tbSaleOrderHeader	WITH (ROWLOCK)			-- HDPPPPPP, ARREGLAR !!!!!!!!!!!!!!!!!!!
				--	SET		soh_WithCollection		= 'True',
				--			soh_WithCollectionGUID	= @guid
				--WHERE	soh_id IN	(
				--					SELECT	tctt.ctct_transaction --que en realidad es soh_id
				--						FROM	tbCommercialTransactionsTmp tctt		WITH (NOLOCK)
				--						WHERE	tctt.ctct_guid = @guid
				--						AND		UPPER(tctt.ctct_origin) = UPPER('s')
				--					)

			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '22 - ' + ERROR_MESSAGE()
			END CATCH



	-- --------------------------------------------------------------------------------------------
	-- MOS 05-2021 x FIESA	ticket 10952
	-- Marca como APROBADOS todos los estados de pedidos que digan que si se cobra un pedido deben Auto-Aprobarse.
	-- MOS 04-2022: $$wefjwl.hfj)(/ se pasó de SP
	-- --------------------------------------------------------------------------------------------
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbSaleOrderStatusConcept tmp			WITH (NOLOCK)
					WHERE tmp.sosc_approveIfSOCollection = 'True'
			)
		BEGIN


			UPDATE tbSaleOrderStatus
				SET	sos_ok = 'True'
				FROM tbSaleOrderStatus					sos		WITH (NOLOCK)
				INNER JOIN tbCommercialTransactionsTmp	tmp		WITH (NOLOCK)
					ON	tmp.ctct_guid			= @guid				AND
						tmp.bra_id				= sos.bra_id		AND
						tmp.ctct_transaction	= sos.soh_id		AND  -- algun HDP puso q se grabe el soh_id en el ctct_transaction para la cobranza Sobre un Pedido.  Ahh ya se quien fue, el REVERENDO hijo de re mil reputas !!!
						tmp.ctct_origin			= 's'
				INNER JOIN tbSaleOrderStatusConcept  AS tsosc	WITH (NOLOCK)
					ON	tsosc.comp_id			= sos.comp_id AND
						tsosc.sosc_id			= sos.sosc_id
			WHERE	tmp.comp_id					= @comp_id			AND
					tmp.ctct_guid				= @guid				AND
					tmp.ctct_origin				= 's'				AND
					tmp.bra_id					= sos.bra_id		AND
					tmp.ctct_transaction		= sos.soh_id		AND
					tsosc.sosc_approveIfSOCollection = 1

		END
		-- --------------------------------------------------------------------------------------------

	-- --------------------------------------------------------------------------------------------
	-- MOS 09-2024
	-- Marca como APROBADOS todos los estados de pedidos que digan que si se cobra un pedido deben Auto-Aprobarse.	siempre y cuando el RECIBO NO esté aplicado a NADA y sea por el importe mayor o igual al del pedido.
	-- --------------------------------------------------------------------------------------------
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbSaleOrderStatusConcept tmp			WITH (NOLOCK)
					WHERE tmp.sosc_approveIfSOCollectionTotal  = 'True'
			)
		BEGIN


			UPDATE tbSaleOrderStatus
				SET	sos_ok = 'True'
				FROM tbSaleOrderStatus					sos		WITH (NOLOCK)
				INNER JOIN tbCommercialTransactionsTmp	tmp		WITH (NOLOCK)
					ON	tmp.ctct_guid			= @guid				AND
						tmp.bra_id				= sos.bra_id		AND
						tmp.ctct_transaction	= sos.soh_id		AND  -- algun HDP puso q se grabe el soh_id en el ctct_transaction para la cobranza Sobre un Pedido.  Ahh ya se quien fue, el REVERENDO hijo de re mil reputas !!!
						tmp.ctct_origin			= 's'
				INNER JOIN tbSaleOrderStatusConcept  AS tsosc	WITH (NOLOCK)
					ON	tsosc.comp_id			= sos.comp_id		AND
						tsosc.sosc_id			= sos.sosc_id
				INNER JOIN tbSaleOrderHeader		 AS tsoh	WITH (NOLOCK)
					ON	tsoh.comp_id			= sos.comp_id		AND
						tsoh.bra_id				= sos.bra_id		AND
						tsoh.soh_id				= sos.soh_id
			WHERE	tmp.comp_id					= @comp_id			AND
					tmp.ctct_guid				= @guid				AND
					tmp.ctct_origin				= 's'				AND
					tmp.bra_id					= sos.bra_id		AND
					tmp.ctct_transaction		= sos.soh_id		AND
					tsosc.sosc_approveIfSOCollection = 1			AND
					tsoh.soh_total				<= @decTotalOfReceiptUnapplied

		END
		-- --------------------------------------------------------------------------------------------






			BEGIN TRY
				DELETE	FROM tbCommercialTransactionsTmp		WITH (ROWLOCK)
					WHERE	ctct_guid = @guid
					AND		LOWER(ctct_origin) = 's'
			END TRY
			BEGIN CATCH
				Set @ret_ErrorCode			= -1
				Set	@ret_ErrorDescription	= '23 - ' + ERROR_MESSAGE()
			END CATCH

		END



	-- --------------------------------------------------------------
	-- Actualizo el Coeficiente de Plan de Descuentos MOS 10-2020
	-- --------------------------------------------------------------
	IF @isPurchase = 'False'
		BEGIN

			DECLARE @st_discountPlanCoeficient					AS DECIMAL(19,4) = 1
			DECLARE @st_discountPlanCoeficient4Cheque			AS DECIMAL(19,4) = 1
			DECLARE @st_discountPlanCoeficient4BankTransfers	AS DECIMAL(19,4) = 1
			DECLARE @st_discountPlanCoeficient4Document			AS DECIMAL(19,4) = 1
			DECLARE @bitHasDiscountPlan AS BIT = 'False'
			SELECT  @bitHasDiscountPlan = 'true',
					@st_discountPlanCoeficient					= tst.st_discountPlanCoeficient,
					@st_discountPlanCoeficient4Cheque			= tst.st_discountPlanCoeficient4Cheque,
					@st_discountPlanCoeficient4BankTransfers	= tst.st_discountPlanCoeficient4BankTransfers,
					@st_discountPlanCoeficient4Document			= tst.st_discountPlanCoeficient4Document
				FROM tbCommercialTransactions	AS tct WITH (NOLOCK)
				INNER JOIN  tbDocumentsFile		AS tdf WITH (NOLOCK)
				ON	tdf.comp_id = tct.comp_id AND
					tdf.df_id	= tct.df_id
				INNER JOIN tbSalesTerms			AS tst WITH (NOLOCK)
				ON	tst.comp_id = tdf.comp_id AND
					tst.st_id	= tdf.st_id4DiscountPlan
				WHERE	tct.comp_id			= @comp_id			AND
						tct.ct_transaction	= @ct_transaction	AND
						tst.st_collectionDiscountsAvailable = 'True'

			IF @bitHasDiscountPlan = 'True'
				BEGIN

					-- Saco Cuando Pago y Como lo pago

					DECLARE @decTotalPayments				AS DECIMAL(19,4) = 0
					DECLARE @decTotalByCoeficientPayment	AS DECIMAL(19,4) = 0

					SELECT	@decTotalPayments			 = @decTotalPayments + vwc.amount,
							@decTotalByCoeficientPayment = @decTotalByCoeficientPayment + (
																							CASE
																								WHEN vwc.class = 1 THEN @st_discountPlanCoeficient
																								WHEN vwc.class = 2 THEN @st_discountPlanCoeficient4Cheque
																								WHEN vwc.class = 3 THEN @st_discountPlanCoeficient4Document
																								WHEN vwc.class = 5 THEN @st_discountPlanCoeficient4BankTransfers
																								WHEN vwc.class = 4 THEN tcclp.ccp_discountPlanCoeficient
																							END  *  vwc.amount
																						   )
						FROM vwCollection vwc						WITH (NOLOCK)
						LEFT JOIN tbCreditCardLoanPlan AS tcclp		WITH (NOLOCK)
							ON	tcclp.comp_id	= vwc.comp_id	AND
								tcclp.cc_id		= vwc.cc_id		AND
								tcclp.ccp_id	= vwc.ccp_id
						WHERE	vwc.comp_id			= @comp_id AND
								vwc.ct_transaction	= @ct_transaction

					UPDATE tbCommercialTransactions		WITH (ROWLOCK)
						SET ct_discountPlanCoeficient = ISNULL(@decTotalByCoeficientPayment,0) / dbo.fnNoZDiv(@decTotalPayments)
					WHERE	comp_id			= @comp_id AND
							ct_transaction	= @ct_transaction


				END
		END
	-- --------------------------------------------------------------








    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT
        IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT		-- MOS 06-2020
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT

END
GO




CREATE PROCEDURE [dbo].[spCollection_InsertSaleOrder4Interests]
(
		@comp_id					INT,
		@lang_id					INT,
		@bra_id						INT,
		@cust_id					INT,
		@ct_transaction				INT,
		@user_id					INT,
		@ExchangeToCustomerCurrency DECIMAL(19,5),
		@df_id						INT,
		@neto						DECIMAL(19,5),
		@neto4ExchangeDifference	DECIMAL(19,5),
		@guid						UNIQUEIDENTIFIER,
		@return_value				VARCHAR(100)	OUTPUT,
		@ret_ErrorCode				INT				OUTPUT,
		@ret_ErrorDescription		VARCHAR(200)	OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------------------------------------------------------------
		-- Testing
		-- ------------------------------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id						INT = 1,
				@bra_id							INT = 1,
				@cust_id						INT = 309,
				@ct_transaction					INT = 44975,
				@user_id						INT = 1,
				@return_value					INT,
				@ret_ErrorCode					INT,
				@ret_ErrorDescription			VARCHAR(200),
				@lang_id						INT = 2,
				@ExchangeToCustomerCurrency		DECIMAL(19,5) = 1,
				@df_id							INT = 8,
				@neto						DECIMAL(19,5) = 0,
				@neto4ExchangeDifference	DECIMAL(19,5) = -10.5,
				@guid						UNIQUEIDENTIFIER = NEWID()
		*/
		-- ------------------------------------------------------------------------------------------------------







		SET 	@return_value			= 0
		SET		@ret_ErrorCode			= 0
		SET		@ret_ErrorDescription	= ' '

		-- ------------------------------------------------------------------------------------------------------
		/* declaración de variables de trabajo                                                                 */
			DECLARE
				@diference			DECIMAL(18,2),
				@perc_diference		DECIMAL(19,6),
				@curr_id			INT
		-- ------------------------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------------------------
		/* obtener la fecha actual                                                                             */
			DECLARE
				@now	DATETIME
			SET @now	= GETDATE()
		-- ------------------------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------------------------
		/* setear la cantidad de decimales                                                                     */
			DECLARE
				@d INT
			SET	@d = 2
		-- ------------------------------------------------------------------------------------------------------

		-- Obtenemos la moneda en la que se calcula la dif. de cambio. o sea, la de la sucursal del recibo hecho.
			SELECT
				@curr_id = tct.curr_id_transaction
				FROM tbCommercialTransactions			tct		WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id	AND
						tct.ct_transaction	= @ct_transaction
		-- ------------------------------------------------------------------------------------------------------
		/* declaración de variables de trabajo                                                                 */
			DECLARE
				@lsoh_id				INT,
				@bra_processingDate		DATETIME,
				@sm_id					INT,
				@rv						INT,
				@observation1			VARCHAR(100),
				@ssos_id				INT,
				@stor_id				INT
		-- ------------------------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------------------------
		/* obtiene el próximo soh_id des la tabla tbCounters, con id 2                                         */
			EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @lsoh_id OUTPUT
		-- ------------------------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------------------------
		/* obtiene la fecha de proceso y el df_id de la sucursal que realizó la cobranza                       */
			SELECT
				@stor_id			= stor_id,
				@bra_processingDate = [bra_processingDate]
				FROM	dbo.[tbBranch]				WITH (NOLOCK)
				WHERE	comp_id				= @comp_id	AND
						[bra_id]			= @bra_id
		-- ------------------------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------------------------
		/* obtiene el código de vendedor del cliente                                                           */
			SELECT
				@sm_id				= sm_id
				FROM	dbo.[tbCustomer]			WITH (NOLOCK)
				WHERE	comp_id = @comp_id	AND
						cust_id	= @cust_id
		-- ------------------------------------------------------------------------------------------------------

		--OBTENGO LOS VALORES DEL DF Y DEL ITEM_ID PARA EL NUEVO PEDIDO
		--== MIRA ACA EL DF_ID MOS
		DECLARE
			@df_id4InterestDebit	INT,
			@item_id4InterestDebit	INT,
			@item_id4ExchangeDiff	INT
		SELECT
			@item_id4InterestDebit	= tdf.df_Collection_item_id4InterestDebit,
			@item_id4ExchangeDiff	= tdf.item_idExchangeDifferenceInterest
			FROM tbDocumentsFile			tdf			WITH (NOLOCK)
			WHERE	tdf.comp_id = @comp_id	AND
					tdf.df_id	= @df_id


		-- Busca 1ro a la ND favorita para Intereses
		SELECT @df_id4InterestDebit =  NULL
		SELECT	 TOP 1
				 @df_id4InterestDebit =  tdf.df_id
			FROM fnDocumentsFile_GetDocumentsForDebitCreditNotes(@comp_id, @bra_id, @cust_id) tdf
			INNER JOIN tbDocumentsFile tdf2				WITH (NOLOCK)
				ON	tdf2.comp_id	= @comp_id AND
					tdf2.df_id		= tdf.df_id
			WHERE	--tdf.sd_isDebitNote						= 1	AND
					tdf.Is4ExchangeDifference				= 0 AND
					(
						((@neto + @neto4ExchangeDifference) > 0	AND tdf.sd_isDebitNote	= 'True')
							OR
						((@neto + @neto4ExchangeDifference) <= 0	AND tdf.sd_isCreditNote = 'True')
					)
			ORDER BY	CASE
							WHEN tdf2.df_Collection_Interest_isDebitNoteDocument = 'True' THEN 0		-- OK, es para ND o NC, campo FAVORITO
							ELSE 1
						END,
						tdf.df_order


		DECLARE
			@lItem_Desc						VARCHAR(150),
			@lItem_Desc4ExchangeDifference	VARCHAR(150)

		SELECT
			@lItem_Desc = ti.item_desc
			FROM tbItem									ti			WITH (NOLOCK)
			WHERE	ti.comp_id = @comp_id				AND
					ti.item_id = @item_id4InterestDebit

		SELECT
			@lItem_Desc4ExchangeDifference = ti.item_desc
			FROM tbItem									ti			WITH (NOLOCK)
			WHERE	ti.comp_id = @comp_id				AND
					ti.item_id = @item_id4ExchangeDiff

		-- Se upone que va a estar definido ya que calculo los intereses como para que entre hasta aca.
		--IF  @df_id4InterestDebit IS NOT NULL
			BEGIN

				-- ------------------------------------------------
				-- Busca Variables del Pedido
				-- ------------------------------------------------
					DECLARE @st_id		AS INT
					DECLARE @disc_id	AS INT
					DECLARE @dl_id		AS INT
					DECLARE @strCTDescription AS NVARCHAR(100)

					SET @strCTDescription = dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)

					SELECT
						TOP 1 @st_id = st_id
						FROM tbSalesTerms tst		WITH (NOLOCK)
						WHERE tst.comp_id = @comp_id
						ORDER BY tst.st_desc

					SELECT
						TOP 1 @disc_id = disc_id
						FROM tbDiscount td			WITH (NOLOCK)
						WHERE td.comp_id = @comp_id AND td.disc_coef = 0
						ORDER BY td.disc_desc

					SELECT
						TOP 1 @dl_id = td.dl_id
						FROM tbDelivery td			WITH (NOLOCK)
						WHERE td.comp_id = @comp_id
						ORDER BY td.dl_name
				-- ------------------------------------------------


					SELECT	@ssos_id		= 50

					DECLARE @customerCurrencyId AS integer
					SELECT @customercurrencyId = curr_id
						FROM tbCustomer tc			WITH (NOLOCK)
						WHERE	tc.comp_id = @comp_id
							AND tc.cust_id = @cust_id


				-- ------------------------------------------------------------------------------------------------------
					/* insertar el pedido                                                       */

					SET @diference = ABS(@diference)

					EXEC dbo.spSaleOrderHeader_insertData	@comp_id,
															@bra_id,
															@lsoh_id,
															@bra_processingDate,
															@bra_processingDate,
															@strCTDescription ,
															'',
															'',
															'',
															'False',
															@sm_id,
															@cust_id,
															@st_id,
															@disc_id,
															@dl_id,
															NULL ,
															@bra_processingDate,
															@bra_processingDate,
															NULL,
															NULL,
															0,
															@user_id,
															'False',
															@bra_processingDate,
															@diference,
															@df_id4InterestDebit,
															@ssos_id,
															@ExchangeToCustomerCurrency,
															@customerCurrencyId


					-- ------------------------------------------------------------------------------------------------------

					SET @neto = ABS(@neto)	-- NO PASARLO MAS ARRIBA !!!!!!

					-- NETO

					IF @neto <> 0
						BEGIN
							EXEC dbo.[spSaleOrderDetail_insertData] @comp_id,
																	@bra_id,
																	@lsoh_id,
																	0,
																	@item_id4InterestDebit,
																	@lItem_Desc,
																	@strCTDescription,
																	@curr_id,
																	1,
																	1,
																	NULL,
																	@neto,
																	@stor_id,
																	@user_id,
																	@now,
																	NULL,
																	@neto,
																	@rv OUTPUT,
																	NULL,
																	NULL,
																	NULL,
																	NULL,
																	NULL,
																	NULL,
																	NULL,
																	'False'
						END

					IF @neto4ExchangeDifference <> 0
						BEGIN

							DECLARE @tmpInteres		AS DECIMAL(19,4)
							DECLARE @tmpTaxID		AS INT
							DECLARE @decTMPTotal	AS DECIMAL(29,4)
							SET		@decTMPTotal = 0
							SELECT 	@decTMPTotal = SUM(tmp.Neto)
								FROM tbCollection_ExchDiffTMPValues tmp		WITH (NOLOCK)
								WHERE tmp.guid = @guid

							DECLARE curByTaxes CURSOR LOCAL FAST_FORWARD FOR
								SELECT 	(tmp.Neto / dbo.fnNoZDiv(@decTMPTotal)) * @neto4ExchangeDifference ,
										ttn.tax_id
									FROM tbCollection_ExchDiffTMPValues tmp			WITH (NOLOCK)
									INNER JOIN tbTaxName				ttn			WITH (NOLOCK)
										ON	ttn.comp_id = tmp.comp_id AND
											ttn.tax_id	= tmp.tax_id
									WHERE tmp.guid = @guid

							OPEN curByTaxes
							FETCH NEXT FROM curByTaxes INTO @decTMPTotal,@tmpTaxID
							WHILE @@FETCH_STATUS = 0
								BEGIN

									-- ------------------------------------------------------------------------------------
									-- MOS 09-2022: SONE q querian q en la nd se haga el aso contable x la cta del item
									-- @intItemID4DN
									-- ------------------------------------------------------------------------------------
									DECLARE @intItemID4DN AS INT = @item_id4ExchangeDiff
									IF NOT EXISTS(
												SELECT TOP 1 1
													FROM tbDocumentsFile AS tdf	WITH (NOLOCK)
													WHERE	tdf.comp_id											= @comp_id				AND
															tdf.df_id											= @df_id4InterestDebit	AND
															tdf.df_Collection_InterestDebit_InsertItemIDinSO	= 'True'
											 )
										BEGIN
											SET @intItemID4DN = NULL
										END
									-- ------------------------------------------------------------------------------------

									SET @decTMPTotal = ABS(@decTMPTotal)	-- MOS 10-2021 para q no de negativo en una NC
									EXEC dbo.[spSaleOrderDetail_insertData]  @comp_id,
																			@bra_id,
																			@lsoh_id,
																			0 ,
																			 NULL /*@item_id4ExchangeDiff*/,
																			@lItem_Desc4ExchangeDifference,
																			@strCTDescription,
																			@curr_id,
																			1,
																			1,
																			NULL,
																			@decTMPTotal/*@neto4ExchangeDifference*/,
																			@stor_id,
																			@user_id,
																			@now,
																			@tmpTaxID /*NULL*/ ,
																			@decTMPTotal/*@neto4ExchangeDifference*/,
																			@rv OUTPUT ,
																			NULL,
																			NULL,
																			NULL,
																			NULL,
																			NULL,
																			NULL,
																			NULL,
																			'False'


									--MOS 09-2022 x SONE q querian q en la nd se haga el aso contable x la cta del item
									IF @intItemID4DN IS NOT NULL
										BEGIN
											UPDATE tbSaleOrderDetail
												SET acc_count_id	= ti.acc_count_id
												FROM tbSaleOrderDetail	AS tsod		WITH (NOLOCK)
												INNER JOIN tbItem		AS ti		WITH (NOLOCK)
												ON	ti.comp_id		= tsod.comp_id	AND
													ti.item_id		= @intItemID4DN
											WHERE	tsod.comp_id	= @comp_id		AND
													tsod.bra_id		= @bra_id		AND
													tsod.soh_id		= @lsoh_id		AND
													tsod.sod_id		= @rv
										END




									FETCH NEXT FROM curByTaxes INTO @decTMPTotal,@tmpTaxID

							END

							CLOSE		curByTaxes
							DEALLOCATE	curByTaxes

						END




				-- ATENCION
				-- Esto es solo para INTERESES y se emite al toque por eso se elimina esto que hace generar INTERBLOQUEOS en Authogar

				---- Si NO es N.Debito x Intereses recalcula los importes totales del pedido
				--IF NOT EXISTS(	SELECT 1
				--					FROM tbDocumentsFile tdf	WITH (NOLOCK)
				--              		WHERE	tdf.comp_id										= @comp_id AND
				--              				tdf.df_id										= @df_id4InterestDebit AND
				--              				tdf.df_Collection_Interest_isDebitNoteDocument	= 'True')
				--	BEGIN
				--		EXEC spSaleOrder_RecalculateTaxes
				--				@comp_id	= @comp_id,
				--				@bra_id		= @bra_id,
				--				@soh_id		= @lsoh_id,
				--				@user_id	= @user_id,
				--				@lang_id	= @lang_id
				--	END





				-- Pone este valor asi luego se puede grabar la tabla de relaciones al emitirse la nota de debito con relacion 5
				UPDATE tbsaleorderheader
					SET aux_collectionInterest_lastCTTransaction = @ct_transaction
					WHERE	comp_id = @comp_id	AND
							bra_id	= @bra_id	AND
							soh_id	= @lsoh_id




				SET @return_value = @lsoh_id


			END

	END




GO









CREATE PROCEDURE [dbo].[spCollection_insertValues]
(
	@guid						uniqueidentifier,
	@ct_transaction				int,
	@return_value				int				output,
	@ret_ErrorCode				int				output,
	@ret_ErrorDescription		varchar(200)	output
)
as

BEGIN



	set nocount on

	/*
	declare	@guid						uniqueidentifier,
			@ct_transaction				int,
			@ret_Identity				int,
			@ret_ErrorCode				int,
			@ret_ErrorDescription		varchar(200)

	select	@guid						='45b7f584-70ae-4d17-981d-392a3b8c75e9',
			@ct_transaction				=30
	*/


	DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT		-- MOS 06-2020
    --SAVE TRANSACTION traPROTECT
    --BEGIN TRANSACTION
    BEGIN TRY

		set 	@return_value			= 0
		set		@ret_ErrorCode			= 0
		set		@ret_ErrorDescription	= ' '


		declare @now	datetime
		set @now = getdate()


		insert into dbo.[tbCashMovements]
		(
				[comp_id],
				[bra_id],
				[cm_cd],
				[ca_id],
				[cm_debit],
				[cm_credit],
				[curr_id],
				[cm_desc],
				[cn_id],
				[ct_transaction],
				[svt_id]
		)
		select	cmt.[comp_id],
				cmt.[bra_id],
				@now,
				cmt.[ca_id],
				cmt.[cmt_amount],
				0,
				cmt.[curr_id],
				cmt.[cmt_desc],
				cmt.[cn_id],
				@ct_transaction,
				1
		from	dbo.[tbCashMovementsTmp]	cmt
		where	cmt.[cmt_guid]			=	@guid


		delete	dbo.[tbCashMovementsTmp]
		where	[cmt_guid]				=	@guid





		insert into dbo.[tbCheckPortfolio]
		(
				[comp_id],
				[bra_id],
				[ct_transaction],
				[chp_number],
				[chp_total],
				[chp_EmissionDate],
				[chp_PayDate],
				[bn_id],
				[chp_BankBranch],
				[chp_BankBranchDescription],
				[chp_AccountNumber],
				[chp_taxNumber1],
				[chp_taxNumber2],
				[chp_taxNumber3],
				[chp_isOwn],
				[chp_isAvailable],
				[chp_IsPayed],
				[chp_isRejected],
				[chp_isCancelled],
				[chp_isToOrder],
				[chp_Note],
				[curr_id],
				[country_id],
				[chp_isDocument],
				[chp_DocumentDescription]
		)
		select	cpt.[comp_id],
				cpt.[bra_id],
				@ct_transaction,
				cpt.[chpt_number],
				cpt.[chpt_total],
				cpt.[chpt_EmissionDate],
				cpt.[chpt_PayDate],
				cpt.[bn_id],
				cpt.[chpt_BankBranch],
				cpt.[chpt_BankBranchDescription],
				cpt.[chpt_AccountNumber],
				cpt.[chpt_taxNumber1],
				cpt.[chpt_taxNumber2],
				cpt.[chpt_taxNumber3],
				cpt.[chpt_isOwn],
				cpt.[chpt_isAvailable],
				'False',
				cpt.[chpt_isRejected],
				'False',
				cpt.[chpt_isToOrder],
				cpt.[chpt_Note],
				cpt.[curr_id],
				cpt.[country_id],
				cpt.[chpt_isDocument],
				cpt.[chpt_DocumentDescription]

		from	dbo.[tbCheckPortfolioTmp]	cpt
		where   cpt.[chpt_guid]			=	@guid


		delete	dbo.[tbCheckPortfolioTmp]
		where   [chpt_guid]				=	@guid




		insert into dbo.[tbCreditCardMovements]
		(
				[comp_id],
				[bra_id],
				[ct_transaction],
				[cc_id],
				[ccm_Total],
				[ccm_cardNumber],
				[ccm_cardEmissionDate],
				[ccm_cardExpirationDate],
				[ccm_customerDocumentNumber],
				[ccm_customerName],
				[ccm_receiptNumber],
				[ccm_AutorizationCode],
				[cccm_id]
		)
		select	ccmt.[comp_id],
				ccmt.[bra_id],
				@ct_transaction,
				ccmt.[cc_id],
				ccmt.[ccmt_Total],
				ccmt.[ccmt_cardNumber],
				ccmt.[ccmt_cardEmissionDate],
				ccmt.[ccmt_cardExpirationDate],
				ccmt.[ccmt_customerDocumentNumber],
				ccmt.[ccmt_customerName],
				ccmt.[ccmt_receiptNumber],
				ccmt.[ccmt_AutorizationCode],
				ccmt.[cccm_id]
		from    dbo.[tbCreditCardMovementsTmp]	ccmt
		where	ccmt.[ccmt_guid]		=	@guid


		delete	dbo.[tbCreditCardMovementsTmp]
		where	[ccmt_guid]				=	@guid




		insert into dbo.[tbBankingTransactions]
		(
				[comp_id],
				[ba_id],
				[bra_id],
				[btt_id],
				[ec_id],
				[chp_id],
				[bt_total],
				[curr_id],
				[bt_imputationDate],
				[bt_isConciliated],
				[bt_isCancelled],
				[ct_transaction],
				[ccm_id],
				[bt_note],
				[bt_Number]
		)
		select	btt.[comp_id],
				btt.[ba_id],
				btt.[bra_id],
				btt.[btt_id],
				btt.[ec_id],
				btt.[chp_id],
				btt.[btt_total],
				btt.[curr_id],
				btt.[btt_imputationDate],
				btt.[btt_isConciliated],
				btt.[btt_isCancelled],
				@ct_transaction,
				btt.[ccm_id],
				btt.[btt_note],
				btt.[btt_Number]
		from	dbo.[tbBankingTransactionsTmp]		btt
		where   btt.[btt_guid]			=	@guid


		delete	dbo.[tbBankingTransactionsTmp]
		where   [btt_guid]				=	@guid



    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT
        IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT		-- MOS 06-2020
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT


END
GO


-- Log
-- GA 25-1-2024. en TOTAL Crystal Reports NO soporta esa cantidad, se le agregó más cantidad de decimales .
-- MAXTREND reportó que no funcionaba la reimpresion de comprobante,. NO hay ticket . REF : 25-1-2024
-- realcolor tmb lo reporta con una orden de pago . tkt : 20760
-- MOS 09-2024: Para que traiga los datos de la suc de emision.



CREATE PROCEDURE [dbo].[spCollection_order]
(
	@comp_id				INT,
	@lang_id				INT,
	@page_id				INT,
	@ct_transaction			INT,
	@bra_id					INT,
	@intBranch4Lang			int
)
AS



BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON



	-- -----------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------
	/*
	DECLARE
		@comp_id				INT = 1,
		@lang_id				INT	= 2,
		@page_id				INT = 10037,
		@ct_transaction			INT = 5570664,
		@bra_id					INT = 59,
		@intBranch4Lang			INT = 59
	*/
	-- -----------------------------------------------------------------


	IF @lang_id = 1  -- como podes ser tan hijo de puta ????
		BEGIN
			SET DATEFORMAT 'mdy'
		END




	--recuperamos el valor en letras
	--DECLARE @eng_TotalLetters VARCHAR(8000)
	DECLARE @text VARCHAR(8000)
	DECLARE @ct_total	DECIMAL(25,5)
	Select	@ct_total			=	tct.ct_total,
			@bra_id				=	tct.bra_id		-- MOS 09-2024: Para que traiga los datos de la suc de emision.
		From	tbCommercialTransactions tct					WITH (NOLOCK)
		WHERE	tct.comp_id			=	@comp_id
		AND		tct.ct_transaction	=	@ct_transaction

	IF @lang_id = 1
		BEGIN
			--==**MOS

			--SELECT @eng_TotalLetters = dbo.fnStrNumbers2Words_Eng(@ct_total)
			SELECT @text = dbo.fnStrNumbers2Words_Eng(@ct_total)

		END
	ELSE
		BEGIN
			EXEC spSysTexts_convertNumberToLetters @lang_id, @ct_total, @letters = @text output
		END

	--DECLARE @text VARCHAR(1000)
	--EXEC spSysTexts_convertNumberToLetters @lang_id, @ct_total, @letters = @text output
	--SELECT @text
	/*****************************************************************************************/

	-- True si es Pago, False si es Cobranza
	Declare @bitIsPayment As Bit

	Select @bitIsPayment			= td.sd_isPurchase

		From tbCommercialTransactions	tct				WITH (NOLOCK)
		Inner Join tbsysDocuments		td			WITH (NOLOCK)
			On td.sd_id	= tct.sd_id

		Where  tct.comp_id		   = @comp_id
		And    tct.ct_transaction  = @ct_transaction
	--------------------------------------------------

	--SELECT @bitIsPayment
	--SET @bitIsPayment = 'True'

	If @bitIsPayment = 'FALSE'

		Begin
				/****************************/
				/*  COBRANZAS	            */
				/****************************/



				/*::::::::::::::::::::CABECERA::::::::::::::::::::*/
				SELECT -- tct.ct_transaction,
						TB.bra_MainDesc																						[bra_MainDesc],
						tc.comp_desc,
						tb.bra_desc,
						tct.ct_docNumber,
						dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)															[Comp],
						tb.bra_address																															[domicilio1],
						tb.bra_address1 + ' ' + ts.state_desc + ' ' + tc2.country_desc																			[domicilio2],
						tb.bra_zip																																[bra_zip],
						tb.bra_phone																															[bra_phone],
						tb.bra_taxNumber																														[cuit],
						-- se cambio tct.curr_id4Exchange por tb.curr_id ;
						dbo.fnGetExchange2(@comp_id,tct.ct_adjust,tb.curr_id,tb.curr_id,tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')			[ct_adjust],
						dbo.fnGetExchange2(@comp_id,tct.ct_ABalance,tb.curr_id,tb.curr_id,tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')		[ct_ABalance3],
						tct.ct_payDate,	convert(int,@bitIsPayment)																								[IsPayment],
						tct.ct_discount,			-- Parte		: 481
						tb.bra_taxNumber,
						tb.bra_taxNumber2,
						tb.bra_taxNumber3,
						tb.bra_taxFiscalClass,
						CONVERT(DECIMAL(30,2),	-- GA 25-1-2024.Crystal Reports NO soporta esa cantidad, se le agregó más cantidad de decimales . MAXTREND reportó que no funcionaba la reimpresion de comprobante,.
						(SELECT dbo.fnGetExchange2(@comp_id, SUM(vph.amount),tct.curr_id4Exchange,tb.curr_id, tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')
					       					    FROM	vwPaymentsHow vph		WITH (NOLOCK)
												WHERE	vph.comp_id			=	@comp_id
												AND		vph.lang_id			=	@lang_id
												AND		vph.ct_transaction	=	@ct_transaction))							[TOTAL],
						tct.ct_date,
						tb.bra_Payment_retentionManagerSign
				FROM	tbCommercialTransactions				tct		WITH (NOLOCK)

						INNER JOIN tbCompany					tc		WITH (NOLOCK)
						ON	tc.comp_id		= tct.comp_id

						INNER JOIN tbBranch						tb		WITH (NOLOCK)
						ON	tb.comp_id		= tct.comp_id
						AND tb.bra_id		= tct.bra_id

						INNER JOIN tbsysState					ts		WITH (NOLOCK)
						ON	ts.state_id		= tb.state_id

						INNER JOIN tbsysCountry					tc2		WITH (NOLOCK)
						ON 	tc2.country_id	= tb.country_id



				WHERE	tct.comp_id			= @comp_id			AND
						tct.ct_transaction	= @ct_transaction



				/*::::::::::::::DATOS DEL CLIENTE:::::::::::::::::*/
				Select	tc3.cust_name					[cust_name]   ,
						tc3.cust_address				[cust_address],
						tc3.cust_Phone1					[cust_phone1] ,
						tc3.cust_city					[cust_city]   ,
						ISNULL(ts2.state_desc,'')		[state_desc]  ,
						tfc.fc_desc,
						ttnt.tnt_desc,
						Replace(convert(VARCHAR(200),rtrim(tc2.curr_symbol)	+ ' ' + convert(VARCHAR(200),convert(Decimal(25,2),tct.ct_total))),'.',',') [ct_total1], --+ ' ' +'(' + rtrim(TC2.curr_desc) + ')'[ct_total1],
						tc2.curr_desc + ' :'			[curr_desc1]  ,
						tc2.curr_symbol					[curr_symbol1],
						tct.ct_ACurrencyExchange                      ,
						tct.ct_ATotal                                 ,
						@text							[importInLetters],
						tc3.cust_zip					[cust_zip]       ,
						tc3.cust_taxNumber				[cust_taxNumber] ,
						'(' + TC2.curr_desc + ')'		[Sup_curr_desc],

						tc7.curr_desc					[curr_customer],
						tc4.curr_desc					[curr_branch],

						tc5.curr_desc					[curr_id4Exchange],
						tc6.curr_desc					[curr_idExchange],

						dbo.fnGetExchange2(@comp_id,1,tc3.curr_id , tb.curr_id, tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')	 [exchange1],

						dbo.fnGetExchange2(@comp_id,1,tb.curr_id4Exchange, tct.curr_id4Exchange,tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')	 [exchange2],
						tc4.curr_symbol					[curr_symbol_branch],		-- Parte		: 481
						convert(VARCHAR(20),tct.cust_id)	[ID],
						ISNULL(tctn.ctn_note1,'')		[note1],
						ISNULL(tctn.ctn_note2,'')		[note2],
						ISNULL(tctn.ctn_note3,'')		[note3],
						ISNULL(tctn.ctn_note4,'')		[note4],
						''								[supp_paymentsNote1],
						''								[supp_paymentsNote2]

				From	tbCustomer tc3	WITH (NOLOCK)

						Inner Join tbCommercialTransactions tct		WITH (NOLOCK)
						On	tct.comp_id		= tc3.comp_id
						AND tct.cust_id		= tc3.cust_id

						LEFT JOIN tbCommercialTransactionNotes tctn		WITH (NOLOCK)
						ON  tctn.comp_id	    = tct.comp_id
						AND tctn.bra_id		    = tct.bra_id
						AND tctn.ct_transaction = tct.ct_transaction

						LEFT JOIN tbBranch tb		WITH (NOLOCK)
						ON  tb.comp_id = tc3.comp_id
						AND tb.bra_id  = tc3.bra_id

						INNER Join tbsysState				ts2		WITH (NOLOCK)
						On	ts2.state_id	= tc3.state_id

						Inner Join  tbsysFiscalClass		tfc		WITH (NOLOCK)
						On	tfc.fc_id		= tc3.fc_id

						Inner Join tbsysTaxNumberTypes		ttnt		WITH (NOLOCK)
						On	ttnt.tnt_id		= tc3.tnt_id

						left JOIN tbsysCurrency				tc2		WITH (NOLOCK)
						ON	tc2.curr_id		= tct.curr_id_transaction

						LEFT JOIN tbsysCurrency				tc4		WITH (NOLOCK)
						ON tc4.curr_id = tb.curr_id

						LEFT JOIN tbsysCurrency				tc5		WITH (NOLOCK)
						ON tc5.curr_id = tb.curr_id4Exchange

						LEFT JOIN tbsysCurrency				tc6		WITH (NOLOCK)
						ON tc6.curr_id = tct.curr_id4Exchange

						LEFT  JOIN tbsysCurrency				tc7		WITH (NOLOCK)
						ON tc7.curr_id = tc3.curr_Id

				WHERE	tct.comp_id			= @comp_id
				AND		tct.ct_transaction	= @ct_transaction



				exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


				DECLARE @strQuote AS NVARCHAR(50)
				SET		@strQuote = ' / Cuota #: '


				-----------------------------
				 --- ::: SUBREPORTES ::: ---
				-----------------------------
				-- Que se cobro
				SELECT
					dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) +
					CASE
						WHEN tctl.comp_id IS NOT NULL THEN @strQuote + CONVERT(VARCHAR(8), ISNULL(tctl.ctl_payNumber,0)) + '/' + convert(varchar(8),ISNULL(tctl.ctl_payNumberTotalQty,0))
						ELSE ''
					END																			[Comprobante1],
					tc2.curr_desc [ct_CompanyCurrency1],
					tct.ct_ATotal,  --total comprobante
					tc.curr_desc	[ct_CompanyCurrency2],
					ta.appl_total,	--importe saldado
					(Select Replace(convert(VARCHAR(200),tc3.curr_symbol	+ convert(VARCHAR(200),convert(Decimal(25,2),tct2.ct_abalance))),'.',',')
						From tbCommercialTransactions tct2	WITH (NOLOCK)
						Inner Join tbsyscurrency tc3	WITH (NOLOCK)
							On	tc3.curr_id			=	tct.ct_ACurrency
						Where	tct2.comp_id		=	@comp_id And
								tct2.ct_transaction =	@ct_transaction)						[ct_ABalance]
					--Replace(convert(varchar,tc3.curr_symbol	+ convert(varchar,convert(Decimal(10,2),tct.ct_abalance))),'.',',')[ct_ABalance]        --tct.ct_ABalance,


					FROM	tbApplication									ta		WITH (NOLOCK)

					INNER JOIN tbCommercialTransactions						tct		WITH (NOLOCK)
					ON	tct.comp_id			= ta.comp_id
					AND tct.ct_transaction	= ta.ct_transaction_Source

					LEFT JOIN tbCommercialTransactionsLoan					tctl		WITH (NOLOCK)
					ON	tctl.comp_id		= ta.comp_id				AND
						tctl.ct_transaction = ta.ct_transaction_Source	AND
						tctl.ctl_id			= ta.ctl_id_Source

					Inner Join tbsysCurrency								tc		WITH (NOLOCK)
					On	tc.curr_id			= ta.appl_currency

					Inner Join tbsysCurrency								tc2		WITH (NOLOCK)
					On	tc2.curr_id			= tct.ct_ACurrency

					Inner Join tbsyscurrency								tc3		WITH (NOLOCK)
					On	tc3.curr_id			= tct.ct_ACurrency

					WHERE	ta.comp_id					= @comp_id
					AND		ta.ct_transaction_destiny	= @ct_transaction
					--And     ta.ct_transaction			= @ct_transaction --GA/MOS 27/04/2016 : SE COMENTÓ XQ NO TRAIA TODOS LOS COMPR.APLICADOS(LE PASO A NISUTA )




				--Como se COBRÓ
				Select vc.[Description],
					   vc.[type] + '//' + vc.[desc] [type] ,
					   vc.amount,
					   vc.currency

					From vwCollection vc		WITH (NOLOCK)
					WHERE	vc.comp_id			=	@comp_id
					AND		vc.lang_id			=	@lang_id
					AND		vc.ct_transaction	=	@ct_transaction
					AND		vc.class <> 100
					ORDER BY vc.class,vc.Date




				--Retenciones
				SELECT  ttn.tax_desc		,
						ttm.tm_subtotal		,
						ttm.percentaje		,
						ttm.tm_total		,
						tc.curr_desc [curr_desc3]
					FROM	tbTaxMovements						ttm		WITH (NOLOCK)

							INNER JOIN tbTaxName				ttn		WITH (NOLOCK)
							ON	ttn.comp_id		=	ttm.comp_id
							AND	ttn.tax_id		=	ttm.tax_id

							INNER JOIN tbsysCurrency			tc		WITH (NOLOCK)
							ON	tc.curr_id		=	ttm.curr_id

					WHERE	ttm.comp_id			=	@comp_id
					AND		ttm.ct_transaction	=	@ct_transaction

				--documentos a cuenta
				--modificado STL 06/04/2011 cambie el CT.CT_TRANSACTION por el TA.CT_TRANSACTION_DESTINY

				SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,ta.ct_transaction_destiny) +
						CASE
							WHEN tctl.comp_id IS NOT NULL THEN @strQuote + CONVERT(VARCHAR(8), ISNULL(tctl.ctl_payNumber,0)) + '/' + convert(varchar(8),ISNULL(tctl.ctl_payNumberTotalQty,0))
							ELSE ''
						END																									[Comp2],
						ISNULL(dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,ta.ct_transaction_Source),'')	[Comp3],
      					ta.appl_total [appl_total2],
      					tc.curr_desc  [curr_desc2],
      					tc.curr_desc  [curr_symbol2],
						tct.ct_date	  [ct_date]
					FROM	tbApplication													ta		WITH (NOLOCK)
					Inner Join tbCommercialTransactions								tct		WITH (NOLOCK)
						ON	tct.comp_id				=	ta.comp_id
						AND tct.ct_transaction		=	ta.ct_transaction_Source
					LEFT JOIN tbCommercialTransactionsLoan tctl		WITH (NOLOCK)
						ON	tctl.comp_id		= ta.comp_id				AND
							tctl.ct_transaction = ta.ct_transaction_Source	AND
							tctl.ctl_id			= ta.ctl_id_Source


					Inner Join tbsysCurrency										tc		WITH (NOLOCK)
					On	tc.curr_id				=	tct.ct_ACurrency

					WHERE	ta.comp_id					=	@comp_id
					AND		ta.ct_transaction			=	@ct_transaction
					--AND		ta.ct_transaction_Source	<>	@ct_transaction
					-- MOS 11-2019
					AND		ta.ct_transaction_destiny	<>	@ct_transaction




				-- =================================================================================================================
				--Parte:473 -- Dummy para que no cancele
				-- =================================================================================================================
				SELECT	tctopd.ctopd_desc,
						tctopd.ctopd_total,
						ta.acc_code,
						ta.acc_desc,
						tpc.puco_desc

				FROM	tbCommercialTransactionsOtherPaymentsDetail		tctopd		WITH (NOLOCK)

						LEFT JOIN tbAccountant							ta		WITH (NOLOCK)
						ON	ta.comp_id			= tctopd.comp_id
						AND ta.acc_count_id		= tctopd.acc_count_id
						LEFT JOIN tbPurchaseConcept						tpc		WITH (NOLOCK)
						ON	tpc.comp_id			= tctopd.comp_id
						AND tpc.puco_id			= tctopd.puco_id

				WHERE	tctopd.comp_id			= @comp_id
				AND		tctopd.ct_transaction	= @ct_transaction
				-- =================================================================================================================

		End

	Else

		Begin

				/****************************/
				/*  PAGOS	                */
				/****************************/





				/*::::::::::::::::::::CABECERA::::::::::::::::::::*/
				SELECT  TB.bra_MainDesc																						[bra_MainDesc],
						tc.comp_desc,
						tb.bra_desc,
						tct.ct_docNumber,
						dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)						[Comp],
						tb.bra_address																						[domicilio1],
						tb.bra_address1 + ' ' + ts.state_desc + ' ' + tc2.country_desc										[domicilio2],
						tb.bra_zip																							[bra_zip],
						tb.bra_phone																						[bra_phone],
						tb.bra_taxNumber																					[cuit],


						--dbo.fnGetExchange2(@comp_id,tct.ct_adjust,	tct.curr_id4Exchange,tb.curr_id,tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')		[ct_adjust],
						dbo.fnGetExchange2(@comp_id,tct.ct_adjust,		tct.curr_id_transaction, tct.ct_ACurrency,		tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')		[ct_adjust],

						--dbo.fnGetExchange2(@comp_id,tct.ct_ABalance,tct.curr_id4Exchange,tb.curr_id,tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')		[ct_ABalance3],
						dbo.fnGetExchange2(@comp_id,tct.ct_ABalance,	tct.curr_id_transaction, tct.ct_ACurrency,		tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')		[ct_ABalance3],



						tct.ct_payDate,convert(int,@bitIsPayment)															[IsPayment],
						tct.ct_discount,			-- Parte		: 481
						tb.bra_taxNumber,
						tb.bra_taxNumber2,
						tb.bra_taxNumber3,
						tb.bra_taxFiscalClass,
						CONVERT(DECIMAL(30,2),	-- MOS 12-2023 x Grupo NUcleo, Crystal Reports NO se fuma un decimal con esa dimension.
						(SELECT dbo.fnGetExchange2(@comp_id,SUM(vph.amount),tct.curr_id4Exchange,tb.curr_id,tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')
							FROM	vwPaymentsHow vph	WITH (NOLOCK)
							WHERE	vph.comp_id			=	@comp_id
							AND		vph.lang_id			=	@lang_id
							AND		vph.ct_transaction	=	@ct_transaction)) 							[TOTAL],
						tct.ct_date,
						tb.bra_Payment_retentionManagerSign

				FROM	tbCommercialTransactions			tct			WITH (NOLOCK)

						INNER JOIN tbCompany				tc			WITH (NOLOCK)
						ON	tc.comp_id		= tct.comp_id

						INNER JOIN tbBranch					tb			WITH (NOLOCK)
						ON	tb.comp_id		= tct.comp_id
						AND tb.bra_id		= tct.bra_id

						INNER JOIN tbsysState				ts			WITH (NOLOCK)
						ON	ts.state_id		= tb.state_id

						INNER JOIN tbsysCountry				tc2			WITH (NOLOCK)
						ON	tc2.country_id	= tb.country_id

				WHERE tct.comp_id			= @comp_id
				AND   tct.ct_transaction	= @ct_transaction




				/*::::::::::::::DATOS DEL PROVEEDOR:::::::::::::::::*/
				SELECT 	CASE WHEN tb.bra_PaymentSupp_Id = tct.supp_id THEN tctop.op_paymentTo ELSE ts.supp_name END		[cust_name],
						CASE WHEN tb.bra_PaymentSupp_Id = tct.supp_id THEN '' ELSE ts.supp_address END					[cust_address],
						CASE WHEN tb.bra_PaymentSupp_Id = tct.supp_id THEN '' ELSE ts.supp_Phone1 END					[cust_phone1],
						CASE WHEN tb.bra_PaymentSupp_Id = tct.supp_id THEN '' ELSE ts.supp_city END						[cust_city],
						CASE WHEN tb.bra_PaymentSupp_Id = tct.supp_id THEN '' ELSE ISNULL(ts2.state_desc,'') END		[state_desc],
						CASE WHEN tb.bra_PaymentSupp_Id = tct.supp_id THEN '' ELSE tfc.fc_desc END						[fc_desc],
						ISNULL(ttnt.tnt_desc, '')																		[tnt_desc],

						Replace(convert(VARCHAR(200),rtrim(tc2.curr_symbol) + ' ' + convert(VARCHAR(200),convert(Decimal(25,2),tct.ct_total))),'.',',') [ct_total1], --+ ' ' +'(' + TC2.curr_desc + ')'[ct_total1],
						tc2.curr_desc + ' :'			[curr_desc1],
						tc2.curr_symbol					[curr_symbol1],
						tct.ct_ACurrencyExchange,
						tct.ct_ATotal,
						@text							[importInLetters],
						ts.supp_zip						[cust_zip],
						ts.supp_taxNumber				[cust_taxNumber],
						'(' + TC2.curr_desc + ')'		[Sup_curr_desc],

						tc7.curr_desc					[curr_customer],
						tc4.curr_desc					[curr_branch],

						tc5.curr_desc [curr_id4Exchange],
						tc6.curr_desc [curr_idExchange],

						dbo.fnGetExchange2(@comp_id,1,ts.curr_id , tb.curr_id,tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')	 [exchange1],

						dbo.fnGetExchange2(@comp_id,1,tb.curr_id4Exchange, tct.ct_curr_IdExchange, tct.curr_id4Exchange,tb.curr_id,tct.ct_curr_IdExchange,'False')	[exchange2],
						tc4.curr_symbol																					[curr_symbol_branch],			-- Parte		: 481
						CASE WHEN tb.bra_PaymentSupp_Id = tct.supp_id THEN '' ELSE CONVERT(VARCHAR(20),tct.supp_id) END		[ID],
						ISNULL(tctn.ctn_note1,'')		[note1],
						ISNULL(tctn.ctn_note2,'')		[note2],
						ISNULL(tctn.ctn_note3,'')		[note3],
						ISNULL(tctn.ctn_note4,'')		[note4],
						ISNULL(ts.supp_paymentsNote1,'')[supp_paymentsNote1],
						ISNULL(ts.supp_paymentsNote2,'')[supp_paymentsNote2]


				From	tbCommercialTransactions tct								WITH (NOLOCK)

						INNER JOIN tbSupplier ts									WITH (NOLOCK)
							ON		ts.comp_id = tct.comp_id
								AND ts.supp_id = tct.supp_id

						LEFT JOIN tbCommercialTransactionNotes tctn					WITH (NOLOCK)
						ON  tctn.comp_id	    = tct.comp_id
						AND tctn.bra_id		    = tct.bra_id
						AND tctn.ct_transaction = tct.ct_transaction

						LEFT JOIN tbBranch tb										WITH (NOLOCK)
						ON tb.comp_id = tct.comp_id
						AND tb.bra_id = tct.bra_id

						INNER Join tbsysState				ts2						WITH (NOLOCK)
						On	ts2.state_id	= TS.state_id

						INNER JOIN tbsysFiscalClass			tfc						WITH (NOLOCK)
						On	tfc.fc_id		= ts.fc_id

						left Join tbsysTaxNumberTypes		ttnt					WITH (NOLOCK)
						On	ttnt.tnt_id		= ts.tnt_id

						Inner JOIN tbsysCurrency			tc2						WITH (NOLOCK)
						ON	tc2.curr_id		=	tct.curr_id_transaction

						LEFT JOIN tbsysCurrency tc4									WITH (NOLOCK)
						ON tc4.curr_id = tb.curr_id

						LEFT JOIN tbsysCurrency tc5									WITH (NOLOCK)
						ON tc5.curr_id = tb.curr_id4Exchange

						LEFT JOIN tbsysCurrency tc6									WITH (NOLOCK)
						ON tc6.curr_id = tct.ct_curr_IdExchange

						LEFT JOIN tbsysCurrency tc7									WITH (NOLOCK)
						ON tc7.curr_id = ts.curr_Id

						LEFT JOIN tbCommercialTransactionsOtherPayments tctop		WITH (NOLOCK)
						ON tct.comp_id = tctop.comp_id
						AND tct.bra_id = tctop.bra_id
						AND tct.ct_transaction = tctop.ct_transaction

				WHERE	tct.comp_id			= @comp_id
				AND		tct.ct_transaction	= @ct_transaction






				--Datos genéricos del reporte principal
				exec [spReports_getData3]@comp_id,@bra_id,@lang_id, @page_id



				SELECT 	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction)											[Comprobante1],
						tc2.curr_desc																											[ct_CompanyCurrency1],
						tct.ct_ATotal,  --total comprobante
						tc.curr_desc																											[ct_CompanyCurrency2],
						ta.appl_total,	--importe saldado
				--Select tct2.ct_abalance From tbCommercialTransactions tct2
						(	Select Replace(convert(VARCHAR(200),tc3.curr_symbol	+ convert(VARCHAR(200),convert(Decimal(25,2),tct2.ct_abalance))),'.',',')
								From tbCommercialTransactions tct2	WITH (NOLOCK)
								Inner Join tbsyscurrency tc3	WITH (NOLOCK)
									On tc3.curr_id			=	tct.ct_ACurrency
								Where	tct2.comp_id		= @comp_id And
										tct2.ct_transaction = @ct_transaction)												[ct_ABalance],
							--Replace(convert(varchar,tc3.curr_symbol	+ convert(varchar,convert(Decimal(10,2),tct.ct_abalance))),'.',',')[ct_ABalance]        --tct.ct_ABalance,
					  /*aaaa*/

				--Parte 595, se agrega la descripción si el pago es TOTAL o PARCIAL

				CASE WHEN tct.ct_ATotal = ta.appl_total THEN
					(SELECT tov.optval_desc FROM tbsysOptionsValues tov	WITH (NOLOCK)   WHERE tov.lang_id = @lang_id AND tov.optval_class = 96 AND tov.optval_id = 2)
				ELSE
					(SELECT tov.optval_desc FROM tbsysOptionsValues tov	WITH (NOLOCK)   WHERE tov.lang_id = @lang_id AND tov.optval_class = 96 AND tov.optval_id = 1)
				END																																[Tipo],

				tct.ct_payDate



				FROM	tbApplication ta											WITH (NOLOCK)

						INNER JOIN tbCommercialTransactions tct						WITH (NOLOCK)
						ON tct.comp_id			= ta.comp_id
						--==AND tct.bra_id			= ta.bra_id
						AND tct.ct_transaction	= ta.ct_transaction_source

						Inner Join tbsysCurrency tc									WITH (NOLOCK)
						On tc.curr_id			= ta.appl_currency

						Inner Join tbsysCurrency tc2								WITH (NOLOCK)
						On tc2.curr_id			= tct.ct_ACurrency

						Inner Join tbsyscurrency tc3								WITH (NOLOCK)
						On tc3.curr_id=tct.ct_ACurrency


				WHERE	ta.comp_id					= @comp_id
				AND		ta.ct_transaction_destiny	= @ct_transaction
				--== Para traer los comprobantes aplicados, comentar la linea de abajo VER MOS
				And     ta.ct_transaction			= @ct_transaction








				--Datos para el primer subreporte: Como se pagó
				SELECT	vph.description											[description],
						CONVERT(VARCHAR,vph.[Date],107) + ': ' + vph.type  		[type],
						vph.amount,
						vph.currency
					FROM	vwPaymentsHow vph		WITH (NOLOCK)
					-- MOS 12-2023, NO se usaba y esto es lo MAS LENTO de este SP
					--inner join tbCommercialTransactions tct		WITH (NOLOCK)
					--	on	tct.comp_id			= vph.comp_id
					--	AND tct.ct_transaction	= vph.ct_transaction
					WHERE	vph.comp_id			=	@comp_id
					AND		vph.ct_transaction	=	@ct_transaction
					AND		vph.lang_id			=	@lang_id
					order BY vph.class,vph.[Date] asc




				--Datos para el segundo subreporte: Retenciones
				SELECT  ttn.tax_desc		,
						ttm.tm_subtotal		,
						ttm.percentaje		,
						ttm.tm_total		,
						tc.curr_desc [curr_desc3]
				FROM	tbTaxMovements						ttm		WITH (NOLOCK)
						INNER JOIN tbTaxName				ttn		WITH (NOLOCK)
						ON	ttn.comp_id		=	ttm.comp_id
						AND	ttn.tax_id		=	ttm.tax_id
						INNER JOIN tbsysCurrency			tc		WITH (NOLOCK)
						ON	tc.curr_id		=	ttm.curr_id
				WHERE	ttm.comp_id			=	@comp_id
				AND		ttm.ct_transaction	=	@ct_transaction




				--........
				SELECT	--funncion que devuelve el comp 222
						dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,ta.ct_transaction_destiny)	[Comp2],
						dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,ta.ct_transaction_Source)	[Comp3],
      					ta.appl_total																			[appl_total2],
      					tc.curr_desc																			[curr_desc2],
      					tc.curr_symbol																			[curr_symbol2],
      					tct.ct_date	  [ct_date]
					FROM	tbApplication							ta		WITH (NOLOCK)
					Inner Join tbCommercialTransactions				tct		WITH (NOLOCK)
						ON	tct.comp_id				=	ta.comp_id
						AND tct.ct_transaction		=	ta.ct_transaction_Source
					Inner Join tbsysCurrency						tc		WITH (NOLOCK)
						On	tc.curr_id				=	ta.appl_currency
					WHERE	-- MOS: 16-10-2019, aca se listan los comprobantes APLICADOS a todos los comprobantes seleccionados para PAGO que NO sean esta OP.
							ta.comp_id					=	@comp_id
					AND		ta.ct_transaction			=	@ct_transaction
					AND		ta.ct_transaction_destiny	<>	@ct_transaction




				-- =================================================================================================================
				--Parte:473
				-- =================================================================================================================
				SELECT	tctopd.ctopd_desc,
						tctopd.ctopd_total,
						ta.acc_code,
						ta.acc_desc,
						tpc.puco_desc

					FROM	tbCommercialTransactionsOtherPaymentsDetail		tctopd		WITH (NOLOCK)

					LEFT JOIN tbAccountant							ta		WITH (NOLOCK)
						ON	ta.comp_id			= tctopd.comp_id
						AND ta.acc_count_id		= tctopd.acc_count_id
					LEFT JOIN tbPurchaseConcept						tpc		WITH (NOLOCK)
						ON	tpc.comp_id			= tctopd.comp_id
						AND tpc.puco_id			= tctopd.puco_id

					WHERE	tctopd.comp_id			= @comp_id
					AND		tctopd.ct_transaction	= @ct_transaction
				-- =================================================================================================================

			------------------------------------------------------------------------------------------------------------------------
			--Agregado para el armado del cheque en el nuevo reporte de OP para USA
			------------------------------------------------------------------------------------------------------------------------
		DECLARE
			@textNumber VARCHAR(8000),
			@ec_Total	DECIMAL(25,5)

		-- ---------------------------------------------------------------
		-- Guardamos el total del cheque en la variable DECIMAL
		-- ---------------------------------------------------------------
			SELECT
				@ec_Total = tec.ec_Total

				FROM tbEmmitedChecks									tec	WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions					tct	WITH (NOLOCK)
					ON tct.comp_id = tec.comp_id
					AND tct.bra_id = tec.bra_id
					AND tct.ct_transaction = tec.ct_transaction

				INNER JOIN tbSupplier								ts	WITH (NOLOCK)
					ON ts.comp_id = tct.comp_id
					AND ts.supp_id = tct.supp_id

				INNER JOIN tbBankingAccounts						tba	WITH (NOLOCK)
					ON tba.comp_id = tec.comp_id
					AND tba.ba_id = tec.ba_id

				INNER JOIN tbBanksName								tbn	WITH (NOLOCK)
					ON  tbn.comp_id = tba.comp_id
					AND tbn.bn_id = tba.bn_id
					AND tbn.country_id = tba.country_id

				INNER JOIN tbsysCurrency							tc	WITH (NOLOCK)
					ON tc.curr_id = tec.curr_id

				WHERE	tec.comp_id			= @comp_id
				AND		tec.ct_transaction	= @ct_transaction
		-- ---------------------------------------------------------------



		-- ---------------------------------------------------------------
		-- Obtenemos el valor en LETRAS de la variable DECIMAL
		-- ---------------------------------------------------------------
		--	EXEC spSysTexts_convertNumberToLetters @lang_id, @ct_total, @letters = @textNumber output
		-- ---------------------------------------------------------------



		-- ---------------------------------------------------------------
		-- Select final que armará el cheque en el reporte
		-- ---------------------------------------------------------------

			SELECT
				tec.ec_Number,
				tec.ec_Total,
				--tec.ec_PayDate,

				CONVERT(VARCHAR(10),MONTH(tec.ec_PayDate)) + '/' + CONVERT(VARCHAR(10),DAY(tec.ec_PayDate)) + '/' + CONVERT(VARCHAR(10),YEAR(tec.ec_PayDate))	[ec_PayDate],

				tba.ba_desc,
				tbn.bn_name,
				tc.curr_desc,
				CASE WHEN tec.ec_payto = NULL THEN
					ts.supp_name
				ELSE
					tec.ec_payto
				END													[Name],
				tec.ec_memo,
				@text/*@eng_TotalLetters*/							[Total_Letters],
				tec.ec_Note




			FROM tbEmmitedChecks									tec	WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions					tct	WITH (NOLOCK)
				ON tct.comp_id = tec.comp_id
				AND tct.bra_id = tec.bra_id
				AND tct.ct_transaction = tec.ct_transaction

				INNER JOIN tbSupplier								ts	WITH (NOLOCK)
				ON ts.comp_id = tct.comp_id
				AND ts.supp_id = tct.supp_id

				INNER JOIN tbBankingAccounts						tba	WITH (NOLOCK)
				ON tba.comp_id = tec.comp_id
				AND tba.ba_id = tec.ba_id

				INNER JOIN tbBanksName								tbn	WITH (NOLOCK)
				ON  tbn.comp_id = tba.comp_id
				AND tbn.country_id = tba.country_id
				AND tbn.bn_id = tba.bn_id

				INNER JOIN tbsysCurrency							tc	WITH (NOLOCK)
				ON tc.curr_id = tec.curr_id


			WHERE	tec.comp_id			= @comp_id
			AND		tec.ct_transaction	= @ct_transaction
		-- ---------------------------------------------------------------

		END


END
GO



CREATE PROCEDURE [dbo].spCollection_SelectSaleOrder_PreSetExchangeAndRecalculate
(
	@comp_id		INT,
	@bra_id			INT,
	@soh_id			INT,
	@curr_id_from	INT,
	@cur_id_to		INT,
	@decExchange	FLOAT,
	@df_id			INT
)

AS

SET NOCOUNT ON

BEGIN

	-- --------------------------------------------------------------
	-- --------------------------------------------------------------
	/*
	DECLARE	@comp_id		INT,
			@bra_id			INT,
			@soh_id			INT,
			@guid			UNIQUEIDENTIFIER,
			@user_id		INT,
			@lang_id		INT
	*/
	-- --------------------------------------------------------------


	-- MOS 05-2022: PCR, para que recalcule el TOTAL del pedido
	-- SOLO si el DOCUMENTO tipo RECIBO tiene asignada una moneda para hacer el recalculo...

		IF EXISTS(
					SELECT TOP 1 1
						FROM tbDocumentsFile AS tdf WITH (NOLOCK)
						WHERE	tdf.comp_id = @comp_id	AND
								tdf.df_id	= @df_id	AND
								tdf.curr_id4SaleOrderCollection_fixExchange IS NOT NULL AND
								tdf.curr_id4SaleOrderCollection_fixExchange = @cur_id_to
				)
		BEGIN

			-- Actualizar el Tipo de Cambio del pedido al de la Cobranza.

			UPDATE tbSaleOrderHeader
				SET soh_ExchangeToCustomerCurrency	= @decExchange ,
					soh_CustomerCurrency			= @cur_id_to
				WHERE	comp_id = @comp_id	AND
						bra_id	= @bra_id	AND
						soh_id	= @soh_id

			-- cambiar soh_ExchangeToCustomerCurrency y soh_CustomerCurrency al tipo de cambio del combo...
			EXEC spSaleOrder_RecalculateTaxes
				@comp_id ,
				@bra_id ,
				@soh_id ,
				@user_id = -1,
				@lang_id = 1




		END

		SELECT tsoh.soh_total	[Total]
			FROM tbSaleOrderHeader AS tsoh WITH (NOLOCK)
			WHERE comp_id	= @comp_id	AND
					bra_id	= @bra_id	AND
					soh_id	= @soh_id


END
GO







