CREATE procedure [dbo].[spCollection_setExchangeDifference]
(
		@comp_id					int,
		@lang_id					int,
		@bra_id						int,
		@cust_id					int,
		@ct_transaction				int,
		@user_id					int,
		@ExchangeToCustomerCurrency Decimal(19,5),

		@return_value				int				output,
		@ret_ErrorCode				int				output,
		@ret_ErrorDescription		varchar(200)	output
)
AS



BEGIN


	set nocount on

	-- ------------------------------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------------------------------
	/*
	declare	@comp_id						int,
			@bra_id							int,
			@cust_id						int,
			@ct_transaction					int,
			@user_id						int,
			@return_value					int,
			@ret_ErrorCode					int,
			@ret_ErrorDescription			varchar(200),
			@lang_id						Int,
			@ExchangeToCustomerCurrency		Decimal(19,5)

	select	@comp_id						=1,
			@bra_id							=1,
			@cust_id						=6329,
			@ct_transaction					=66127,
			@user_id						=1,
			@lang_id						=2,
			@ExchangeToCustomerCurrency		=914
	*/
	-- ------------------------------------------------------------------------------------------------------





	set 	@return_value			= 0
	set		@ret_ErrorCode			= 0
	set		@ret_ErrorDescription	= ' '



	/*******************************************************************************************************/
	/* declaración de variables de trabajo                                                                 */
	declare	@diference			decimal(18,2),
			@perc_diference		decimal(19,6),
			@curr_id			int
	/*******************************************************************************************************/




	/*******************************************************************************************************/
	/* obtener la fecha actual                                                                             */
	declare @now	datetime
	set		@now = getdate()
	/*******************************************************************************************************/




	/*******************************************************************************************************/
	/* setear la cantidad de decimales                                                                     */
	declare @d int
	set		@d = 2
	/*******************************************************************************************************/




	/*******************************************************************************************************/
	/* recuperar la diferencia de cambio y la moneda en que realizó la cobranza                            */
	Select 	@diference			=   Sum( a.appl_total * ctd.ct_ACurrencyExchange ) - Sum( a.appl_total * ct.ct_ACurrencyExchange),

			@perc_diference		= ((Sum( a.appl_total * ctd.ct_ACurrencyExchange ) /
									  dbo.fnNoZDiv( Sum(a.appl_total * ct.ct_ACurrencyExchange))) -1) * 100


		FROM 	dbo.[tbApplication]											a		WITH (NOLOCK)

		inner join dbo.[tbCommercialTransactions]							ct		WITH (NOLOCK)
			on		ct.comp_id				=	a.comp_id				AND
					ct.bra_id				=	a.bra_id				AND
					ct.ct_transaction		=	a.ct_transaction_Source
		LEFT JOIN tbDocumentsFile										AS tdf		WITH (NOLOCK)	-- MOS 07-2024: para que no lo tome en cuenta tal como hace en el calculo.
			ON	tdf.comp_id					= @comp_id					AND
				tdf.df_id					= ct.df_id

		inner join dbo.[tbCommercialTransactions]							ctd		WITH (NOLOCK)
		on		a.[comp_id]					=	ctd.[comp_id]					AND
				a.[bra_id]					=	ctd.[bra_id]					AND
				a.ct_transaction_destiny	=	ctd.[ct_transaction]
		where   a.ct_transaction_destiny					=	@ct_transaction	AND
				tdf.df_DisableExchangeDifferenceInterest	= 'False'			AND
				(
					a.appl_excdifchecked				   <> 'true'
						OR
					a.appl_excdifchecked				is	NULL
				)
		Group By a.ct_transaction_destiny
		--select	@diference, @perc_diference
	/*******************************************************************************************************/





	-- Obtenemos la moneda en la que se calcula la dif. de cambio. o sea, la de la sucursal del recibo hecho.
	SELECT @curr_id = tct.curr_id_transaction
	FROM tbCommercialTransactions tct		WITH (NOLOCK)
	WHERE	tct.comp_id			= @comp_id
		AND tct.ct_transaction	= @ct_transaction



	-- -------------------------------------------------------------------------------------------------------
	-- FORRO HIJO DE RECONTRA RE MIL PUTAS:   Primso tenias que calcular el total de NETO por cada transaccion
	-- -------------------------------------------------------------------------------------------------------
	select	tm.tax_id,
			ct.ct_transaction,
			sum(tm.tm_subtotal  )	[tm_subtotal]
		INTO #tmpFile
		from	dbo.[tbApplication]												a		WITH (NOLOCK)

				inner join	dbo.[tbCommercialTransactions]						ct		WITH (NOLOCK)
				on		a.[comp_id]					=	ct.[comp_id]
				AND		a.[bra_id]					=	ct.[bra_id]
				AND		a.[ct_transaction_Source]	=	ct.[ct_transaction]

				inner join dbo.[vwCommercialTransactions_forSales]				ctfs		WITH (NOLOCK)
				on		ct.[comp_id]				=	ctfs.comp_id
				and		ct.[bra_id]					=	ctfs.bra_id
				and		ct.[ct_transaction]			=	ctfs.ct_transaction

				inner join dbo.[tbItemTransactions]								it		WITH (NOLOCK)
				on		ct.[comp_id]				=	it.comp_id
				and		ct.[bra_id]					=	it.bra_id
				and		ct.[ct_transaction]			=	it.ct_transaction

				inner join dbo.[tbTaxMovements]									tm		WITH (NOLOCK)
				on		ct.[comp_id]				=	tm.comp_id
				and		ct.[bra_id]					=	tm.bra_id
				and		ct.[ct_transaction]			=	tm.ct_transaction
				and		it.[it_transaction]			=	tm.it_transaction

				inner join	dbo.[tbCommercialTransactions]						ct1		WITH (NOLOCK)
				on		a.[comp_id]					=	ct1.[comp_id]
				AND		a.[bra_id]					=	ct1.[bra_id]
				AND		a.[ct_transaction_destiny]	=	ct1.[ct_transaction]

				inner join	dbo.[tbTaxName]										tn		WITH (NOLOCK)
				on		tn.[comp_id]				=	tm.comp_id
				and		tn.[tax_id]					=	tm.tax_id

				inner join	dbo.[vwsysTaxClassIVA_Taxes]						tcit		WITH (NOLOCK)
				on		tn.[tax_class]				=	tcit.[tax_class]


		where   a.ct_transaction_destiny			=	@ct_transaction AND
				(
					a.appl_excdifchecked				<>	'true'
						OR
					a.appl_excdifchecked				is	NULL
				)
		group by tm.tax_id, tn.[tax_percentage],ct.ct_transaction


		DECLARE @decSumaNetosTotalesParaPoderPonderar AS DECIMAL(19,2) = 0
		SELECT  @decSumaNetosTotalesParaPoderPonderar = SUM(tm_subtotal)
			FROM #tmpFile

		SELECT @decSumaNetosTotalesParaPoderPonderar


		SELECT 	tn.tax_id,
				convert(decimal(18,2),round(
												sum(
													@diference * (a.tm_subtotal  ) / dbo.fnNoZDiv(@decSumaNetosTotalesParaPoderPonderar)
													)
												/
													(
														1 + (tn.[tax_percentage] / 100)
													)
											,2))														[tmpNeto],
				convert(decimal(18,2),round(
												sum(
													@diference * (a.tm_subtotal  ) / dbo.fnNoZDiv(@decSumaNetosTotalesParaPoderPonderar)
													)
												/
													(
														1 + (tn.[tax_percentage] / 100)
													)
												* tn.[tax_percentage] / 100,2))							[tmpTaxes]
		INTO #tmpFileFINAL
		from	#tmpFile														a		WITH (NOLOCK)

				inner join	dbo.[tbCommercialTransactions]						ct		WITH (NOLOCK)
				on		@comp_id					=	ct.[comp_id]
				AND		a.ct_transaction			=	ct.[ct_transaction]


				inner join	dbo.[tbTaxName]										tn		WITH (NOLOCK)
				on		tn.[comp_id]				=	@comp_id
				and		tn.[tax_id]					=	a.tax_id

				inner join	dbo.[vwsysTaxClassIVA_Taxes]						tcit		WITH (NOLOCK)
				on		tn.[tax_class]				=	tcit.[tax_class]

		GROUP BY tn.tax_id,tn.tax_percentage

		DROP TABLE #tmpFile
	-- -------------------------------------------------------------------------------------------------------



	/*******************************************************************************************************/
	/* declaración de cursor para obtención de los montos asignados a cada tipo de de impuesto             */
	declare @tax_id	 int,
			@neto	decimal(18,2),
			@tax	decimal(18,2)


	DECLARE  cursor_data cursor LOCAL FAST_FORWARD  FOR
		SELECT * FROM #tmpFileFINAL	-- MOS 06-2024: hice el calculo mas arriba y aca lo pongo en el cursor para que siga funcionando como antes esta parte


	---- MOS 06-2024: MALDITO ENFERMO HIJO DE RECONTRA RE MIL REPUTAS; FORRRROOOOOOOOOOOOOOOOOOOOOOOOOOOOOO.  no solo NO SABES PROGRAMAS sino que tampoco SABES MATEMATICA.  FORRROOOOOOO
	----select	tm.tax_id,
	----		convert(decimal(18,2),round((
	----			@diference * sum(tm.tm_subtotal) * 100 / sum(ct.[ct_subtotal]) / 100) / (1 + (tn.[tax_percentage] / 100)),2)),
	----		convert(decimal(18,2),round((
	----			@diference * sum(tm.tm_subtotal) * 100 / sum(ct.[ct_subtotal]) / 100) / (1 + (tn.[tax_percentage] / 100))
	----																					* tn.[tax_percentage] / 100,2))
	--select	tm.tax_id,
	--		convert(decimal(18,2),round(
	--										(
	--											@diference * sum(tm.tm_subtotal / dbo.fnNoZDiv(ct.[ct_subtotal]) )
	--										)
	--										/
	--										(
	--											1 + (tn.[tax_percentage] / 100)
	--										)
	--									,2)),
	--		convert(decimal(18,2),round(
	--										(
	--											@diference * sum(tm.tm_subtotal / dbo.fnNoZDiv(ct.[ct_subtotal]) )
	--										)
	--										/
	--										(
	--											1 + (tn.[tax_percentage] / 100)
	--										)
	--										* tn.[tax_percentage] / 100,2))
	--from	dbo.[tbApplication]												a		WITH (NOLOCK)

	--		inner join	dbo.[tbCommercialTransactions]						ct		WITH (NOLOCK)
	--		on		a.[comp_id]					=	ct.[comp_id]
	--		AND		a.[bra_id]					=	ct.[bra_id]
	--		AND		a.[ct_transaction_Source]	=	ct.[ct_transaction]

	--		inner join dbo.[vwCommercialTransactions_forSales]				ctfs		WITH (NOLOCK)
	--		on		ct.[comp_id]				=	ctfs.comp_id
	--		and		ct.[bra_id]					=	ctfs.bra_id
	--		and		ct.[ct_transaction]			=	ctfs.ct_transaction

	--		inner join dbo.[tbItemTransactions]								it		WITH (NOLOCK)
	--		on		ct.[comp_id]				=	it.comp_id
	--		and		ct.[bra_id]					=	it.bra_id
	--		and		ct.[ct_transaction]			=	it.ct_transaction

	--		inner join dbo.[tbTaxMovements]									tm		WITH (NOLOCK)
	--		on		ct.[comp_id]				=	tm.comp_id
	--		and		ct.[bra_id]					=	tm.bra_id
	--		and		ct.[ct_transaction]			=	tm.ct_transaction
	--		and		it.[it_transaction]			=	tm.it_transaction

	--		inner join	dbo.[tbCommercialTransactions]						ct1		WITH (NOLOCK)
	--		on		a.[comp_id]					=	ct1.[comp_id]
	--		AND		a.[bra_id]					=	ct1.[bra_id]
	--		AND		a.[ct_transaction_destiny]	=	ct1.[ct_transaction]

	--		inner join	dbo.[tbTaxName]										tn		WITH (NOLOCK)
	--		on		tn.[comp_id]				=	tm.comp_id
	--		and		tn.[tax_id]					=	tm.tax_id

	--		inner join	dbo.[vwsysTaxClassIVA_Taxes]						tcit		WITH (NOLOCK)
	--		on		tn.[tax_class]				=	tcit.[tax_class]


	--where   a.ct_transaction_destiny			=	@ct_transaction
	--and		(a.appl_excdifchecked				<>	'true'
	--	or	a.appl_excdifchecked				is	null)

	--group by tm.tax_id, tn.[tax_percentage]
	/*******************************************************************************************************/




	/*******************************************************************************************************/
	/* declaración de variables de trabajo                                                                 */
	declare		@lsoh_id				int,
				@bra_processingDate		datetime,
				@sm_id					int,
				@df_id					int,
				@rv						int,
				@observation1			varchar(100),
				@ssos_id				int
	/*******************************************************************************************************/




	/*******************************************************************************************************/
	/* obtiene el próximo soh_id des la tabla tbCounters, con id 2                                         */
	EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @lsoh_id OUTPUT
	/*******************************************************************************************************/




	/*******************************************************************************************************/
	/* obtiene la fecha de proceso y el df_id de la sucursal que realizó la cobranza                       */
	select	@bra_processingDate = [bra_processingDate]--,
			--@df_id				= case	when @diference > 0 then bra_Collection_ExDiCN_df_id
			--							when @diference	< 0 then bra_Collection_ExDiDN_df_id
			--						end

		from	dbo.[tbBranch]	WITH (NOLOCK)
		where	bra_id			= @bra_id AND
				comp_id			= @comp_id
	/*******************************************************************************************************/




	/*******************************************************************************************************/
	/* obtiene el código de vendedor del cliente                                                           */
	select	@sm_id				= sm_id
		from	dbo.[tbCustomer]		WITH (NOLOCK)
		WHERE	comp_id		= @comp_id AND
				cust_id		= @cust_id
	/*******************************************************************************************************/





	/*******************************************************************************************************/
	/* obtener descripción para pedido                                                                     */
	declare @optval_id			int

	if @diference < 0
	begin
		set @optval_id = 1

		select	top 1 @df_id	=	df_id
			from	dbo.fnDocumentsFile_GetDocumentsForDebitCreditNotes(@comp_id, @bra_id, @cust_id)
			where	sd_isCreditNote = 'true' AND Is4ExchangeDifference = 1
		ORDER BY df_order

		if @df_id is null
		begin

			set @return_value = -1
			set @ret_ErrorCode = 1001

			select	@ret_ErrorDescription = utexts_desc from	dbo.tbsysUniqueTexts
			where	lang_id	= @lang_id and utexts_id = @ret_ErrorCode
			return
		end

	end

	if @diference > 0
	begin
		set @optval_id = 2

		select	top 1 @df_id	=	df_id
			from	dbo.fnDocumentsFile_GetDocumentsForDebitCreditNotes(@comp_id, @bra_id, @cust_id)
			where	sd_isDebitNote	= 'true' AND Is4ExchangeDifference = 1
		ORDER BY df_order

		if @df_id is null
		begin

			set @return_value = -1
			set @ret_ErrorCode = 1002

			select	@ret_ErrorDescription = utexts_desc from	dbo.tbsysUniqueTexts		WITH (NOLOCK)
				where	lang_id	= @lang_id and utexts_id = @ret_ErrorCode
			return
		end

	end

	--select @observation1
	/*******************************************************************************************************/


	if not @df_id is null

		begin

			select	@observation1		= [optval_desc]
				from	dbo.[tbsysOptionsValues]		WITH (NOLOCK)
				where	[optval_class]		= 48
				and		[optval_id]			= @optval_id
				AND		lang_id				= @lang_id




			-- ------------------------------------------------
			-- Busca Variables del Pedido
			-- ------------------------------------------------
			DECLARE @st_id		AS INT
			DECLARE @disc_id	AS INT
			DECLARE @dl_id		AS INT
			DECLARE @strCTDescription AS NVARCHAR(100)

			SET @strCTDescription = dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)

			SELECT TOP 1 @st_id = st_id
				FROM tbSalesTerms tst		WITH (NOLOCK)
				WHERE tst.comp_id = @comp_id
				ORDER BY tst.st_desc

			SELECT TOP 1 @disc_id = disc_id
				FROM tbDiscount td		WITH (NOLOCK)
			WHERE td.comp_id = @comp_id AND td.disc_coef = 0
			ORDER BY td.disc_desc

			SELECT TOP 1 @dl_id = td.dl_id
				FROM tbDelivery td		WITH (NOLOCK)
				WHERE td.comp_id = @comp_id
				ORDER BY td.dl_name
			-- ------------------------------------------------





			/*cambio solicitado por MOS el 10-08-2009															   */
			/* original
			select	top 1 @ssos_id = ssos_id
			from	dbo.vwsysSaleOrderStatus_IsOkForEmmition*/
			SELECT	@ssos_id		= 210

			DECLARE @customerCurrencyId AS integer
			SELECT @customercurrencyId = curr_id
				FROM tbCustomer tc		WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id
					AND tc.cust_id = @cust_id


			SET @observation1 = @observation1 + ':' + @strCTDescription

			/*******************************************************************************************************/
			/* insertar el pedido por diferencia de cambio                                                         */

			SET @diference = ABS(@diference)

			exec dbo.spSaleOrderHeader_insertData	@comp_id,
													@bra_id,
													@lsoh_id,
													@bra_processingDate,
													@bra_processingDate,
													@observation1 ,
													'',
													'',
													'',
													'False',
													@sm_id,
													@cust_id,
													@st_id,
													@disc_id,
													@dl_id,
													null,
													@bra_processingDate,
													@bra_processingDate,
													null,
													null,
													0,
													@user_id,
													'False',
													@bra_processingDate,
													@diference,
													@df_id,
													@ssos_id,
													@ExchangeToCustomerCurrency,
													@customerCurrencyId
			/*******************************************************************************************************/





			/*******************************************************************************************************/
			/* insertar los ítems por dif de cambio por cada tipo de impuesto                                      */
			open cursor_data

			fetch cursor_data into @tax_id, @neto, @tax


			while @@FETCH_STATUS = 0
			begin

				SET @neto = ABS(@neto)

				exec dbo.[spSaleOrderDetail_insertData] @comp_id,
														@bra_id,
														@lsoh_id,
														0,
														NULL,
														'Diferencia de Cambio',	 --- Poner en lenguajes
														'',
														@curr_id,
														1,
														1,
														null,
														@neto,
														null,
														@user_id,
														@now,
														@tax_id,
														@neto,
														@rv OUTPUT,
														NULL,
														NULL,
														NULL,
														NULL,
														NULL,
														NULL,
														NULL,
														'false'

				--select @rv

				fetch cursor_data into @tax_id, @neto, @tax

			end

			close cursor_data
			deallocate cursor_data
			/*******************************************************************************************************/

			DROP TABLE #tmpFileFINAL




			-- -------------------------------------------------------------------------------------
			-- MOS 07-2024: Control FINAL del cálculo de DC.  si NO DA, CANCELA TODO
			-- -------------------------------------------------------------------------------------
			EXEC spSaleOrder_RecalculateTaxes
					@comp_id	= @comp_id,
					@bra_id		= @bra_id,
					@soh_id		= @lsoh_id,
					@user_id	= @user_id,
					@lang_id	= @lang_id


			DECLARE @decDifference AS DECIMAL(19,4) = 0
			SELECT  @decDifference = tsoh.soh_total
				FROM tbSaleOrderHeader	AS tsoh WITH (NOLOCK)
				WHERE	tsoh.comp_id	= @comp_id	AND
						tsoh.bra_id		= @bra_id	AND
						tsoh.soh_id		= @lsoh_id

			IF ABS(@diference - @decDifference) > 5
				BEGIN
					set @return_value				= -1
					set @ret_ErrorCode				= 1003
					select	@ret_ErrorDescription	= 'ERROR (65487345): Problema en el cálculo de los totales de los Items de Diferencia de cambio: @diference:' + CONVERT(VARCHAR(50),@diference) + ' @decDifference:' +CONVERT(VARCHAR(50),@decDifference)
					return
				END
			-- -------------------------------------------------------------------------------------



		end



END
GO






CREATE procedure [dbo].[spCollectionManagementContactMethod_getCombo]
(
		@comp_id		int

)
as
set nocount on

select
		tcmcm.cmcm_id	[Id],
