CREATE PROCEDURE [dbo].[spCollectionManagementDetail_GetData4Grid]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@cust_id	INT

)
AS

	SET NOCOUNT ON

		BEGIN
	-- -------------------------------------------------------------
	-- TESTING
	-- -------------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@prof_id	INT,
			@user_id	INT,

			@cmde_id	INT,
			@cust_id	INT
		SELECT
			@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@prof_id	= 1,
			@user_id	= 3,

			@cmde_id	= 46,
			@cust_id	= 24719
	*/
	-- -------------------------------------------------------------

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


			SELECT
				tc2.cust_name											[cust_name],
				tcmh.cmh_note											[note1],
				tcmh.cmh_cd												[Date],
				tcmh.cmh_id												[ID]
				FROM tbCollectionManagementDetail								tcmd	WITH (NOLOCK)

				INNER JOIN tbCollectionManagementHeader							tcmh	WITH (NOLOCK)
				ON	tcmh.comp_id				= tcmd.comp_id			AND
					tcmh.cmh_id					= tcmd.cmh_id

				INNER JOIN tbUser												tu		WITH (NOLOCK)
					ON	tu.[user_id]			= tcmd.user_id4LastUpdate

				INNER JOIN tbCustomer											tc2		WITH (NOLOCK)
					ON	tc2.comp_id				= tcmd.comp_id			AND
						tc2.cust_id				= tcmd.cust_id

				WHERE	tcmd.comp_id			= @comp_id				AND
					--	tcmd.cmde_id			= @cmde_id				AND
						tcmd.cust_id			= @cust_id				AND
						tcmh.cmh_closed			= 'True'

			ORDER BY tcmh.cmh_cd desc


		END
GO




CREATE PROCEDURE [dbo].[spCollectionmanagementDetail_GetDataByCMHID]
(
	@comp_id	INT,
	@lang_id	INT,
	@cmh_id		INT,
	@guid		UNIQUEIDENTIFIER,
	@cmcm_id	INT,
	@rating_id	INT,
	@def_id		INT,
	@intIsProcessed	INT
)
AS

	SET NOCOUNT ON

		BEGIN
	-- -------------------------------------------------------------
	-- TESTING
	-- -------------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@cmh_id		INT,
			@guid		UNIQUEIDENTIFIER,
			@cmcm_id	INT,
			@rating_id	INT,
			@def_id		INT
		SELECT
			@comp_id	= 1,
			@cmh_id		= 42,
			@guid		= '19c49d87-2947-4051-8a76-dbeb1fb28ef1',
			@cmcm_id	= -1,
			@rating_id	= -1,
			@def_id		= -1
	*/
	-- -------------------------------------------------------------

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros
	-- NOTA: Para buscar todas las incidencias
	-- de este método ejecutar el "BuscarTexto" en la base de datos
	-- con el valor de referencia "#8600"
	-- Página de EJEMPLO:App_Reports_App_WebForms_wfmRptFilters_PriceLists2_Testing
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter TABLE (cust_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf      WITH (NOLOCK)
			WHERE	tcf.sl_guid = @guid      AND
					tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter
				SELECT su.cust_id
					FROM tbCustomer su
					WHERE su.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

			DECLARE
				@strYes	VARCHAR(10),
				@strNo	VARCHAR(10)

			SELECT
				@strYes = tov.optval_desc
				FROM tbsysOptionsValues			tov
				WHERE	tov.lang_id			= 2 AND
						tov.optval_class	= 1	AND
						tov.optval_id		= 1

			SELECT
				@strNo = tov.optval_desc
				FROM tbsysOptionsValues			tov
				WHERE	tov.lang_id			= 2 AND
						tov.optval_class	= 1	AND
						tov.optval_id		= 0



			SELECT
				' '													[ ], --MODIFICAR REGISTRO
				' '													[ ], --ACCEDER A LA FICHA DEL CLIENTE
				' '													[ ], --ACCEDER A NOTAS DE CRM
				' '													[ ], --Grilla generica - Detalle de Notas.
				tc2.cust_name,
				ISNULL(tc2.cust_phone1,'')							[cust_phone1],			-- Telefono
				ISNULL(tc2.cust_cellPhone2,'')						[cust_cellPhone2],		-- Telefono Celular
				ISNULL(tc2.cust_cellPhone2_notes,'')				[cust_cellPhone2_notes], -- Notas Telefono Celular
				ISNULL(tc2.cust_cellPhone,'')						[cust_cellPhoneAd],		-- Telefonos celulares adicionales
				ISNULL(tc2.cust_cellPhone1_notes,'')			[cust_cellPhone1_notes],	-- NotasTelefono Celular
				ISNULL(tcmcm.cmcm_desc,'')							[cmcm_desc],


				CASE WHEN ISNULL(tcmd.cmde_noAction,'False') = 'False' THEN
					@strNo
				ELSE
					@strYes
				END													[cmde_noAction],

				--ISNULL(tcmd.cmde_noAction,'False')					[cmde_noAction],



				tu.user_lastname + ',' + tu.user_firstname			[user_name],
				tccr.rating_desc,
				tcmd.cmde_quoteQtyOnDefault,
				tcmd.cmde_totalOnDefault,
				tcmd.cmde_dateOfLastPay,
				tcmd.cmde_totalOfLastPay,
				tc.curr_symbol,
				ISNULL(tcc.case_subject,'')							[case_subject],
				ISNULL(tcn.crmn_note1,'')							[crmn_note1],
				ISNULL(tcmcm2.cmcm_desc,'')							[cmcm_desc2],

				--ISNULL(tcmd.cmde_isProcessed,'False')				[cmde_isProcessed],

				CASE WHEN ISNULL(tcmd.cmde_isProcessed,'False') = 'False' THEN
					@strNo
				ELSE
					@strYes
				END													[cmde_isProcessed],

				tu2.user_lastname + ',' + tu2.user_lastname			[User_Processor],
				tcmd.cmde_dateProcess,
				tu3.user_lastname + ',' + tu3.user_lastname			[User_UnProcessor],
				tcmd.cmde_dateUnProcess,

				CONVERT(VARCHAR,tcmd.cmde_id)	+ '-' +
				CONVERT(VARCHAR,tcmd.cust_id)						[ID]

				FROM tbCollectionManagementDetail					tcmd
					LEFT JOIN tbCollectionManagementContactMethod	tcmcm
						ON	tcmcm.comp_id	= tcmd.comp_id			AND
							tcmcm.cmcm_id	= tcmd.cmcm_id
					INNER JOIN tbUser								tu
						ON	tu.[user_id]	= tcmd.user_id4LastUpdate
					INNER JOIN tbsysCurrency						tc
						ON	tc.curr_id		= tcmd.curr_id
					INNER JOIN @tblComplexFilter					tcf
						ON	tcf.cust_id		= tcmd.cust_id
					INNER JOIN tbCustomer							tc2
						ON	tc2.comp_id		= tcmd.comp_id			AND
							tc2.cust_id		= tcf.cust_id
					INNER JOIN tbCustomerCreditRating				tccr
						ON	tccr.comp_id	= tcmd.comp_id			AND
							tccr.rating_id	= tcmd.rating_id
					LEFT JOIN tbCRM_Case							tcc
						ON	tcc.comp_id		= tcmd.comp_id			AND
							tcc.case_id		= tcmd.case_id
					LEFT JOIN tbCRM_Notes							tcn
						ON	tcn.comp_id		= tcmd.comp_id			AND
							tcn.crmn_id		= tcmd.crmn_id
					LEFT JOIN tbCollectionManagementContactMethod	tcmcm2
						ON	tcmcm2.comp_id	= tcmd.comp_id			AND
							tcmcm2.cmcm_id	= tcmd.cmcm_id_Last
					LEFT JOIN tbUser						tu2
						ON	tu2.[user_id]	= tcmd.cmde_user_id_process
					LEFT JOIN tbUser						tu3
						ON	tu3.[user_id]	= tcmd.cmde_user_id_unProcess

				WHERE	tcmd.comp_id		= @comp_id								AND
						tcmd.cmh_id			= @cmh_id								AND
						(@cmcm_id			= -1 OR tcmd.cmcm_id			= @cmcm_id)		AND
						(@rating_id			= -1 OR tcmd.rating_id			= @rating_id)	AND
						(@def_id			= -1 OR tc2.def_id				= @def_id)		AND
						(@intIsProcessed	= -1 OR tcmd.cmde_isProcessed	= @intIsProcessed)

			ORDER BY 	tcmd.cmde_isProcessed, tcmd.cmcm_id,tcmd.cmde_quoteQtyOnDefault,tc2.cust_name


		END
GO






-- NO SE USA MAS, se cambio a [spCollectionmanagementDetail_GetDataByCMHID]
CREATE PROCEDURE [dbo].[spCollectionManagementDetail_GetDataByFilters]
(
	@comp_id	INT,
	@cmh_id		INT
)
AS
	SET NOCOUNT ON


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


		BEGIN

			--TRAE EL DETALLE DE CADA GESTION DE COBRANZA

			SELECT
				' ' [ ], --MODIFICAR
				' ' [ ], --ACCEDER A LA FICHA DEL CLIENTE
				' ' [ ], --ACCEDER A NOTAS DE CRM

				tc.cust_name,
				tcmd.cmde_lastUpdate,
				ISNULL(tu.user_lastname + ',' + tu.user_firstname,'')	[user_LastUpdate],
				tcmd.cmde_quoteQtyOnDefault,
				tcmd.cmde_dateOfLastPay,
				tcmd.cmde_totalOfLastPay,
				tc2.curr_symbol,
				tcmcm.cmcm_desc,
				tccr.rating_desc,

				ISNULL(tcmd.cmde_isProcessed,'False')					[cmde_isProcessed],
				tu2.user_lastname + ',' + tu2.user_lastname				[User_Processor],
				tcmd.cmde_dateProcess,
				tu3.user_lastname + ',' + tu3.user_lastname				[User_UnProcessor],
				tcmd.cmde_dateUnProcess,

				CONVERT(VARCHAR,tcmd.cmde_id)							+ '-' +
				CONVERT(VARCHAR,tc.cust_id)								[ID]

			FROM tbCollectionManagementDetail			tcmd

				INNER JOIN tbCustomer					tc
					ON	tc.comp_id		= tcmd.comp_id	AND
						tc.cust_id		= tcmd.cust_id

				INNER JOIN tbsysCurrency				tc2
					ON	tc2.curr_id		= tcmd.curr_id

				INNER JOIN tbCustomerCreditRating		tccr
					ON	tccr.comp_id	= tcmd.comp_id	AND
						tccr.rating_id	= tcmd.rating_id

				INNER JOIN tbUser						tu
					ON	tu.[user_id]	= tcmd.user_id4LastUpdate

				LEFT JOIN tbCollectionManagementContactMethod	tcmcm
					ON	tcmcm.comp_id = tcmd.comp_id			AND
						tcmcm.cmcm_id = tcmd.cmcm_id_Last

				LEFT JOIN tbUser						tu2
					ON	tu2.[user_id]	= tcmd.cmde_user_id_process

				LEFT JOIN tbUser						tu3
					ON	tu3.[user_id]	= tcmd.cmde_user_id_unProcess

			WHERE	tcmd.comp_id	= @comp_id			AND
					tcmd.cmh_id		= @cmh_id

		END



GO



CREATE PROCEDURE [dbo].[spCollectionManagementDetail_GetDataById]
(
	@comp_id	INT,
	@cmde_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN

			SELECT
				tcmd.comp_id,
				tcmd.cmh_id,
				tcmd.cmde_id,
				tcmd.cust_id,
				tc.cust_name,
				tcmd.cmcm_id,
				tcmd.cmde_lastUpdate,
				tcmd.user_id4LastUpdate,
				tcmd.cmde_quoteQtyOnDefault,
				tcmd.cmde_dateOfLastPay,
				tcmd.cmde_totalOfLastPay,
				tcmd.curr_id,
				tcmd.cmde_dateOfLastAdvertisement,
				tcmd.cmcm_id_Last,
				tcmd.crmn_id,
				tcmd.rating_id,
				tcmd.ctl_id,
				tcmd.cmde_noAction,
				tcmd.cmde_note,
				tcmd.cmde_image,
				tcmd.case_id,
				tcmd.cmde_isProcessed

				FROM tbCollectionManagementDetail	tcmd		WITH (NOLOCK)
				INNER JOIN tbCustomer				tc			WITH (NOLOCK)
					ON	tc.comp_id = tcmd.comp_id	AND
						tc.cust_id = tcmd.cust_id
				WHERE	tcmd.comp_id = @comp_id		AND
						tcmd.cmde_id = @cmde_id

		END

GO





CREATE PROCEDURE [dbo].[spCollectionManagementDetail_InsertData]
(
	@comp_id		INT,
	@lang_id		INT,
	@user_id		INT,
	@cmh_id			INT,
	@cmdc_id		INT,
	@guid			UNIQUEIDENTIFIER,
	@return_value	INT OUTPUT
)
AS


		BEGIN

			SET NOCOUNT ON

			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
			-- -----------------------------------------------------------------------------








			-- -----------------------------------------------------------------
			-- TESTING
			-- -----------------------------------------------------------------
			/*
				DECLARE
					@comp_id		INT,
					@lang_id		INT,
					@user_id		INT,
					@cmh_id			INT,
					@cmdc_id		INT,
					@guid			UNIQUEIDENTIFIER,
					@return_value	INT
				SELECT
					@comp_id		= 1,
					@lang_id		= 2,
					@user_id		= 39,
					@cmh_id			= 67,
					@cmdc_id		= 1,
					@guid			= 'B44ADE2A-9DA2-49AD-942C-E8348EE3F668'


				DELETE FROM tbCollectionManagementDetail WHERE cmh_id = 67
				DELETE FROM tbComplexFilter
				INSERT INTO tbComplexFilter
				(
					sl_guid,
					sl_id,
					sl_order,
					sl_selected
				)
				SELECT 'B44ADE2A-9DA2-49AD-942C-E8348EE3F668',
					   tc.cust_id,0,1
					FROM tbCustomer tc


				--DECLARE
				--	@comp_id		INT,
				--	@lang_id		INT,
				--	@user_id		INT,
				--	@cmh_id			INT,
				--	@cmdc_id		INT,
				--	@guid			UNIQUEIDENTIFIER,
				--	@return_value	INT
				--SELECT
				--	@comp_id		= 1,
				--	@lang_id		= 2,
				--	@user_id		= 39,
				--	@cmh_id			= 43,
				--	@cmdc_id		= 1,
				--	@guid			= 'B44ADE2A-9DA2-49AD-942C-E8348EE3F668'


				--DELETE FROM tbCollectionManagementDetail WHERE cmh_id = 43
				--DELETE FROM tbComplexFilter
				--INSERT INTO tbComplexFilter
				--(
				--	sl_guid,
				--	sl_id,
				--	sl_order,
				--	sl_selected
				--)
				--VALUES
				--(
				--	'B44ADE2A-9DA2-49AD-942C-E8348EE3F668',
				--	212850,
				--	0,
				--	1
				--)

				--INSERT INTO tbComplexFilter
				--(
				--	sl_guid,
				--	sl_id,
				--	sl_order,
				--	sl_selected
				--)
				--VALUES
				--(
				--	'B44ADE2A-9DA2-49AD-942C-E8348EE3F668',
				--	920392,
				--	0,
				--	1
				--)

				--INSERT INTO tbComplexFilter
				--(
				--	sl_guid,
				--	sl_id,
				--	sl_order,
				--	sl_selected
				--)
				--VALUES
				--(
				--	'B44ADE2A-9DA2-49AD-942C-E8348EE3F668',
				--	600082,
				--	0,
				--	1
				--)

			*/
			-- -----------------------------------------------------------------




			SET @return_value = 0


			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			-- -----------------------------------------------------------------------------

			DECLARE
				@CMCM_ID_ERROR_MESSAGE VARCHAR(300)

			SELECT
				@CMCM_ID_ERROR_MESSAGE	= tut.utexts_desc
				FROM tbsysUniqueTexts						tut		WITH(NOLOCK)
				WHERE	tut.lang_id		= @lang_id			AND
						tut.utexts_id	= 30717

			-- ------------------------------------------------------------------------
			-- SI TIENE ALGO EN LA COMPLEX FILTERS CARGAMOS LOS CLIENTES QUE ESTEN AHÍ
			-- ------------------------------------------------------------------------
			DECLARE
				@tblCustomersDebt TABLE(
										CustId			INT primary KEY CLUSTERED,
										QuotasOnDefault	INT DEFAULT 0,
										Cust_Debt		DECIMAL(19,4) DEFAULT (0)
										)

			IF EXISTS (SELECT 1
							FROM tbComplexFilter tcf		WITH (NOLOCK)
							WHERE tcf.sl_guid = @guid)
				BEGIN
					INSERT INTO @tblCustomersDebt
					(
						CustId
					)
					SELECT
						tcf.sl_id
      					FROM tbComplexFilter tcf	WITH(NOLOCK)
      					WHERE tcf.sl_guid = @guid
				END
			ELSE
				BEGIN
					--SI NO HAY NADA EN LA COMPLEXFILTERS CARGAMOS TODOS LOS CLIENTES
					INSERT INTO @tblCustomersDebt (CustId)
					SELECT tc.cust_id
						FROM tbCustomer tc		WITH(NOLOCK)
					    WHERE tc.comp_id = @comp_id
				END
			-- ------------------------------------------------------------------------


--MOs poner aca los dias en mora
			-- ------------------------------------------------------------------------
			-- CARGAMOS TODOS LOS TOTALES DE DEUDA DE CLIENTES
			-- ------------------------------------------------------------------------
			DECLARE
				@tblCTL_DEBT TABLE(
									CustId			INT  primary KEY CLUSTERED,
									QuotasOnDefault	INT DEFAULT (0),
									CTL_Debt		DECIMAL(19,4) DEFAULT (0)
								   )

			INSERT INTO @tblCTL_DEBT
			(
				CustId,
				QuotasOnDefault,
				CTL_Debt
			)
			SELECT
				tct.cust_id,
				COUNT(*),
				SUM(
					CASE
						WHEN tctl.comp_id IS NULL THEN	tct.ct_ABalance
						ELSE							tctl.ct_ABalance
					END * vctfs.PlusOrMinus
					)
				FROM tbCommercialTransactions						tct		WITH(NOLOCK)
				INNER JOIN tbBranch									tb		WITH (NOLOCK)
					ON	tb.comp_id				= tct.comp_id AND
						tb.bra_id				= tct.bra_id
				INNER JOIN vwCommercialTransactions_forSales		vctfs	WITH(NOLOCK)
					ON	vctfs.comp_id			= tct.comp_id	AND
						--vctfs.bra_id			= tct.bra_id	AND
						vctfs.ct_transaction	= tct.ct_transaction
				LEFT JOIN tbCommercialTransactionsLoan				tctl	WITH(NOLOCK)
					ON	tctl.comp_id			= tct.comp_id		AND
						tctl.ct_transaction		= tct.ct_transaction
				INNER JOIN @tblCustomersDebt						TMP
					ON tmp.CustId				= tct.cust_id
				LEFT JOIN vwCommercialTransactions_PaymentOnAccount vctpoa	WITH(NOLOCK)
					ON	vctpoa.comp_id			= tct.comp_id		AND
						vctpoa.ct_transaction	= tct.ct_transaction
				WHERE	tct.comp_id					=	@comp_id		AND
						vctpoa.comp_id				IS NULL				AND
						vctfs.sd_isInBalance		= 'True'			AND
						vctfs.sd_isReceipt			= 'False'			AND
						CASE
							WHEN tctl.comp_id IS NULL and tct.ct_payDate < GETDATE()										THEN 1
							WHEN tctl.comp_id IS NULL AND tb.bra_collectionManagement_enableNoLoanTransactions = 'False'	THEN 0
							WHEN tctl.comp_id IS NULL AND tb.bra_collectionManagement_enableNoLoanTransactions = 'True'		THEN tct.ctl_daysPastDue
							ELSE																								 tctl.ctl_daysPastDue
						END	 > 0										AND
						CASE
							WHEN tctl.comp_id IS NULL and tct.ct_ABalance <> 0								THEN 1
							WHEN tctl.comp_id IS NULL														THEN 0
							WHEN tctl.comp_id IS NOT NULL AND (tctl.ct_ABalance <= (tctl.ct_ATotal * 0.1))	THEN 0		-- MOS 05-2016 Si el saldo de la cuota es MENOR al 10% del total que no la incluya para el calculo de mora.
							ELSE																				 tctl.ct_ABalance
						END	 <> 0
				GROUP BY tct.cust_id


			-- ------------------------------------------------------------------------
			-- ACTUALIZAMOS LA DEUDA PARA LOS CLIENTES QUE CUMPLEN NUESTROS CRITERIOS
			-- ------------------------------------------------------------------------
			-- QUE CUERNOS ES ESTO ??????????
			UPDATE @tblCustomersDebt
				SET
					QuotasOnDefault = tmp2.QuotasOnDefault,
					Cust_Debt		= tmp2.CTL_Debt
				FROM @tblCustomersDebt		tmp
					INNER JOIN @tblCTL_DEBT tmp2
						ON tmp2.CustId = tmp.CustId
			-- ------------------------------------------------------------------------



			-- ------------------------------------------------------------------------
			-- BORRAMOS TODOS LOS REGISTROS QUE NO TENGAN CUOTAS DEUDORAS
			-- OSEA CANTIDAD DE CUOTAS ADEUDADAS = 0
			-- ------------------------------------------------------------------------
			DELETE FROM @tblCustomersDebt WHERE QuotasOnDefault = 0
			-- ------------------------------------------------------------------------


			--STL 16/12/2015
			-- ------------------------------------------------------------------------
			-- BORRAMOS TODOS LOS REGISTROS QUE TENGAN UNA DEUDA INFERIOR A $2
			-- ------------------------------------------------------------------------
			DELETE FROM @tblCustomersDebt WHERE Cust_Debt < 2
			-- ------------------------------------------------------------------------



			INSERT INTO tbCollectionManagementDetail
			(
				comp_id,
				cmh_id,
				cust_id,
				cmcm_id,
				cmde_lastUpdate,
				user_id4LastUpdate,
				cmde_dateOfLastPay,
				cmde_totalOfLastPay,
				curr_id,
				cmde_dateOfLastAdvertisement,
				cmcm_id_Last,
				rating_id,
				cmde_quoteQtyOnDefault,
				cmde_totalOnDefault,
				cmd_id,
				cmde_noAction,
				cmde_isProcessed,
				cmde_isProcessed_last
			)
			SELECT
				@comp_id,
				@cmh_id,
				tmp.CustId,
				(SELECT
					 TOP 1
						tcmp.cmcm_id
					 FROM tbCollectionManagementParameters						tcmp		WITH(NOLOCK)
						INNER JOIN tbCollectionManagementParametersClassDetail	tcmpcd		WITH(NOLOCK)
							ON	tcmp.comp_id	= tcmpcd.comp_id				AND
								tcmp.cmd_id		= tcmpcd.cmd_id
						INNER JOIN tbCollectionManagementParametersClass		tcmpc		WITH(NOLOCK)
							ON  tcmpc.comp_id	= tcmpcd.comp_id				AND
								tcmpc.cmdc_id	= tcmpcd.cmdc_id
					 WHERE	tcmp.comp_id		= @comp_id						AND
							tcmpc.cmdc_id		= @cmdc_id						AND
							tcmp.cmd_disabled4Calculation = 'False'				AND
							(SELECT
								MAX(tctl.ctl_daysPastDue)
								FROM tbCommercialTransactionsLoan				tctl		WITH(NOLOCK)
									INNER JOIN tbCommercialTransactions			tct			WITH(NOLOCK)
									ON	tct.comp_id			= tctl.comp_id		AND
										tct.ct_transaction	= tctl.ct_transaction
								WHERE	tct.cust_id			= tmp.CustId		AND
										tctl.ct_ABalance	<> 0				AND
									   (
									   		tctl.ct_ABalance > (tctl.ct_ATotal * 0.1)		-- que el saldo sea mas del 10% del total de la cuota
									   )
							)		BETWEEN tcmp.cmd_fromDefaultDays AND tcmp.cmd_toDefaultDays)	[cmcm_id],

				GETDATE(),
				@user_id,

				--cmde_dateOfLastPay
				(SELECT
					ISNULL((
					SELECT
						TOP 1	tct2.ct_payDate
						FROM tbCommercialTransactions			tct2			WITH(NOLOCK)
						INNER JOIN tbCustomer					tc2				WITH(NOLOCK)
							ON	tc2.comp_id	= tct2.comp_id	AND
								tc2.cust_id = tct2.cust_id
						WHERE	tct2.comp_id	= @comp_id		AND
								tct2.cust_id	= tmp.CustId	AND
								tct2.sd_id		IN (6,13)
						ORDER BY TCT2.ct_payDate DESC),(SELECT
															tc.cust_lastPaymentDatefromOtherERP
															FROM tbCustomer					tc
															WHERE	tc.comp_id = @comp_id	AND
																	tc.cust_id = tmp.CustId))),	--FECHA DE ULTIMO PAGO

				--cmde_totalOfLastPay
				(SELECT
					TOP 1
						tct3.ct_total
					 FROM tbCommercialTransactions			tct3			WITH(NOLOCK)
					 WHERE	tct3.comp_id	= @comp_id		AND
							tct3.cust_id	= tmp.CustId	AND
							tct3.sd_id		IN (6,13)
					 ORDER BY TCT3.ct_transaction DESC),					--MONTO DEL ULTIMO PAGO


				-- curr_id
				(SELECT TOP 1
					 ISNULL(tctl.curr_id,tct.curr_id_transaction)
					 FROM tbCommercialTransactions					tct			WITH(NOLOCK)
					 LEFT JOIN tbCommercialTransactionsLoan			tctl		WITH(NOLOCK)
						ON	tct.comp_id			= tctl.comp_id	AND
							tct.ct_transaction	= tctl.ct_transaction
					 WHERE	tct.comp_id = @comp_id AND
							tct.cust_id = tmp.CustId),							--CURR_ID,  Arreglar esta MIERDA!!!!

				-- cmde_dateOfLastAdvertisement
				(SELECT TOP 1
					tcmh.cmh_cd
					FROM tbCollectionManagementHeader			tcmh		WITH(NOLOCK)
						INNER JOIN tbCollectionManagementDetail tcmd		WITH(NOLOCK)
							ON	tcmd.comp_id	= tcmh.comp_id	AND
								tcmd.cmh_id		= tcmh.cmh_id	AND
								tcmd.cust_id	= tmp.CustId
					WHERE tcmh.comp_id = @comp_id
					ORDER BY tcmd.cmde_id DESC),							--ULTIMA FECHA DE AVISO


				-- cmcm_id_Last
				(SELECT TOP 1
					tcmd.cmcm_id
					 FROM tbCollectionManagementHeader			tcmh		WITH(NOLOCK)
						INNER JOIN tbCollectionManagementDetail tcmd		WITH(NOLOCK)
							ON	tcmd.comp_id	= tcmh.comp_id	AND
								tcmd.cmh_id		= tcmh.cmh_id	AND
								tcmd.cust_id	= tmp.CustId
					 WHERE		tcmh.comp_id    = @comp_id		AND
								tcmd.cmcm_id	IS NOT NULL
					 ORDER BY tcmd.cmde_id DESC),							--ULTIMO Metodfo de Contacto CMCM_ID SOLO DE GESTION CERRADA (ULTIMA GESTION NO IMPORTA SI ESTA CERRADA O ABIERTA)
				tccr.rating_id,
				tmp.QuotasOnDefault,
				tmp.Cust_Debt,
				-- cmd_id
				(SELECT
					 TOP 1
						tcmp.cmd_id
						 FROM tbCollectionManagementParameters						tcmp	WITH(NOLOCK)
							INNER JOIN tbCollectionManagementParametersClassDetail	tcmpcd	WITH(NOLOCK)
								ON	tcmp.comp_id	= tcmpcd.comp_id				AND
									tcmp.cmd_id		= tcmpcd.cmd_id
							INNER JOIN tbCollectionManagementParametersClass		tcmpc	WITH(NOLOCK)
								ON  tcmpc.comp_id	= tcmpcd.comp_id				AND
									tcmpc.cmdc_id	= tcmpcd.cmdc_id
						 WHERE	tcmp.comp_id					= @comp_id			AND
								tcmpc.cmdc_id					= @cmdc_id			AND
								tcmp.cmd_disabled4Calculation	= 'False'			AND
								(SELECT
									MAX(tctl.ctl_daysPastDue)
									FROM tbCommercialTransactionsLoan				tctl	WITH(NOLOCK)
									INNER JOIN tbCommercialTransactions				tct		WITH(NOLOCK)
										ON	tct.comp_id			= tctl.comp_id			AND
											tct.ct_transaction	= tctl.ct_transaction	AND
											tctl.ct_ABalance	<> 0					AND
									   (
									   		tctl.ct_ABalance > (tctl.ct_ATotal * 0.1)		-- que el saldo sea mas del 10% del total de la cuota
									   )
									WHERE	tct.comp_id			= @comp_id				AND
											tct.cust_id			= tmp.CustId
						) BETWEEN tcmp.cmd_fromDefaultDays AND tcmp.cmd_toDefaultDays)	[cmd_id],	--CMD_ID	CAMPO NUEVO,
				ISNULL(tc.cmde_noAction,'False'),
				'False',  -- isProcessed
				--cmde_isProcessed_last
				(SELECT TOP 1
					tcmd.cmde_isProcessed
					 FROM tbCollectionManagementHeader			tcmh		WITH(NOLOCK)
						INNER JOIN tbCollectionManagementDetail tcmd		WITH(NOLOCK)
							ON	tcmd.comp_id	= tcmh.comp_id	AND
								tcmd.cmh_id		= tcmh.cmh_id	AND
								tcmd.cust_id	= tmp.CustId
					 WHERE		tcmh.comp_id    = @comp_id		AND
								tcmd.cmcm_id	IS NOT NULL
					 ORDER BY tcmd.cmde_id DESC)


			FROM @tblCustomersDebt								tmp
				INNER JOIN tbCustomer							tc		WITH(NOLOCK)
					ON  tc.cust_id			= tmp.CustId
				INNER JOIN tbCustomerCreditRating				tccr	WITH(NOLOCK)
					ON	tccr.comp_id		= tc.comp_id		AND
						tccr.rating_id		= tc.rating_id




			-- ----------------------------------------------------------------------------------------------------------------------------------
			-- BORRA LOS QUE NO SE PASEN DE LA CANTIDAD DE DIAS ESTIMADOS PARA ULTIMO PAGO cmd_noProcessIfPayInLastNDays
			-- ----------------------------------------------------------------------------------------------------------------------------------

				UPDATE tbCollectionManagementDetail										WITH (ROWLOCK)
					SET	tbCollectionManagementDetail.cmcm_id			= NULL
					FROM tbCollectionManagementDetail tbp
					INNER JOIN tbCollectionManagementParameters				tcmp		WITH(NOLOCK)
						ON	tcmp.comp_id	= tbp.comp_id AND
							tcmp.cmd_id		= tbp.cmd_id
					WHERE	tbp.comp_id = @comp_id	AND
							tbp.cmh_id	= @cmh_id	AND
							DATEDIFF(DAY,cmde_dateOfLastPay,GETDATE()) <=  tcmp.cmd_noProcessIfPayInLastNDays --@cmd_noProcessIfPayInLastNDays

			-- ----------------------------------------------------------------------------------------------------------------------------------





			-- ----------------------------------------------------------------------------------------------------------------------------------
			-- ACA BORRAMOS TODOS LOS QUE TENGAN UN TIPO DE NOTA DE CRM QUE LOS EXCLUYA Y QUE NO ESTEN VENCIDOS
			-- ----------------------------------------------------------------------------------------------------------------------------------

				DECLARE @crmTABLE AS TABLE (comp_id INT, cmh_id INT, cmde_id INT)
				INSERT INTO @crmTABLE
				(
					comp_id,
					cmh_id,
					cmde_id
				)
				SELECT DISTINCT
					tcmd.comp_id,
					tcmd.cmh_id,
					tcmd.cmde_id
					FROM tbCollectionManagementHeader							tcmh		WITH(NOLOCK)
						INNER JOIN tbCollectionManagementDetail					tcmd		WITH(NOLOCK)
							ON	tcmd.comp_id	= tcmh.comp_id					AND
								tcmd.cmh_id		= tcmh.cmh_id
						INNER JOIN tbCollectionManagementParametersClassDetail	tcmpcd		WITH(NOLOCK)
							ON	tcmpcd.comp_id	= tcmh.comp_id					AND
								tcmpcd.cmdc_id	= tcmh.cmdc_id
						INNER JOIN tbCollectionManagementParameters tcmp					WITH(NOLOCK)
							ON	tcmp.comp_id	= tcmd.comp_id AND
								tcmp.cmd_id		= tcmd.cmd_id
						INNER JOIN tbCRM_Notes									tcn			WITH(NOLOCK)
							ON	tcn.comp_id		  = tcmd.comp_id				AND
								tcn.cust_id		  = tcmd.cust_id
					WHERE	tcmh.comp_id		  = tcmh.comp_id				AND
							tcmd.cmh_id			  = @cmh_id						AND
							tcn.crmnt_id		  = tcmp.crmnt_id_NoProcess		AND
							tcn.cme_validUpToDate > GETDATE()


				---- Al pedo en dos pasos pero bue . . .
				UPDATE tbCollectionManagementDetail			WITH (ROWLOCK)
					SET
						cmcm_id			= NULL
					WHERE	comp_id = @comp_id				AND
							cmh_id	= @cmh_id				AND
							cmde_id IN (SELECT
											tbl.cmde_id
											FROM @crmTABLE tbl)
			-- ----------------------------------------------------------------------------------------------------------------------------------






			-- ----------------------------------------------------------------------------------------------------------------------------------
			-- ACA SACAMOS TODOS LOS QUE TENGAN UN CMCM_ID DENTRO DEL RANGO DE DIAS CONFIGURADO EN LA TABLA DE PARAMETROS
			-- cmd_noProcessIfEqualCmCmIdInLastNDays
			-- ----------------------------------------------------------------------------------------------------------------------------------

				UPDATE tbCollectionManagementDetail							WITH (ROWLOCK)
				SET
					tbCollectionManagementDetail.cmcm_id					= NULL
					FROM tbCollectionManagementDetail		tcmd
					INNER JOIN tbCollectionManagementParameters kkl			WITH (NOLOCK)
						ON	kkl.comp_id = tcmd.comp_id AND
							kkl.cmd_id	= tcmd.cmd_id
					WHERE	tcmd.comp_id				= @comp_id	AND
							tcmd.cmh_id					= @cmh_id	AND
							tcmd.cmcm_id_Last			= tcmd.cmcm_id					AND		-- SI EL CMCM_ID ES IGUAL AL ANTERIOR CMCM_ID
							tcmd.cmde_isProcessed_last	= 'True'						AND
							DATEDIFF(DAY, tcmd.cmde_dateOfLastAdvertisement,GETDATE()) <= kkl.cmd_noProcessIfEqualCmCmIdInLastNDays	-- y pasaron mas de X dias segun la configuracion

			-- ----------------------------------------------------------------------------------------------------------------------------------




			-- ----------------------------------------------------------------------------------------------------------------------------------
			-- PONEMOS QUE NO REALICE ACCIÓN SI EL CLIENTE ESTÁ DEFINIDO EN FALSE EN EL CAMPO "cmde_NoAction"
			-- ----------------------------------------------------------------------------------------------------------------------------------

				UPDATE tbCollectionManagementDetail		WITH (rowlock)
					SET cmcm_id			= NULL
					FROM tbCollectionManagementDetail								tcmd
					WHERE	tcmd.comp_id							= @comp_id		AND
							tcmd.cmh_id								= @cmh_id		AND
							tcmd.cmde_noAction						= 'True'




		END




GO



CREATE PROCEDURE [dbo].[spCollectionManagementDetail_UpdateData]
(
	@comp_id			INT,
	@cmh_id				INT,
	@cmde_id			INT,
	@user_id			INT,
	@cmrn_id			INT,
	@cmde_isProcessed	BIT,
	@cmde_note			NVARCHAR(4000),
	@cmde_image			IMAGE,
	@case_id			INT,
	@cmcm_id			INT
)
AS
	SET NOCOUNT ON

		BEGIN

			UPDATE tbCollectionManagementDetail
			SET
				cmde_lastUpdate			= GETDATE(),
				user_id4LastUpdate		= @user_id,
				crmn_id					= CASE @cmrn_id WHEN -1 THEN NULL ELSE @cmrn_id END,
				--cmde_noAction			= @cmde_noAction,
				cmde_note				= @cmde_note,
				cmde_image				= @cmde_image,
				case_id					= CASE @case_id WHEN -1 THEN NULL ELSE @case_id END,
				cmcm_id_Last			= cmcm_id,
				cmcm_id					= @cmcm_id,
				cmde_isProcessed		= @cmde_isProcessed,
				cmde_user_id_process	= CASE WHEN (@cmde_isProcessed = 'True')	AND (ISNULL(cmde_isProcessed,'False') = 'False') THEN @user_id		ELSE cmde_user_id_process	END,
				cmde_dateProcess		= CASE WHEN (@cmde_isProcessed = 'True')	AND (ISNULL(cmde_isProcessed,'False') = 'False') THEN GETDATE()		ELSE cmde_dateProcess		END,
				cmde_user_id_unProcess	= CASE WHEN (@cmde_isProcessed = 'False')	AND (ISNULL(cmde_isProcessed,'False') = 'True' ) THEN @user_id		ELSE cmde_user_id_unProcess	END,
				cmde_dateUnProcess		= CASE WHEN (@cmde_isProcessed = 'False')	AND (ISNULL(cmde_isProcessed,'False') = 'True' ) THEN GETDATE()		ELSE cmde_dateUnProcess		END

			WHERE	comp_id			= @comp_id	AND
					cmh_id			= @cmh_id	AND
					cmde_id			= @cmde_id

		END
GO






