CREATE PROCEDURE [dbo].[spCollectionManagementHeader_GetDataByFilters]
(
	@comp_id	INT,
	@cmdc_id	INT,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@status		INT
)
AS
	SET NOCOUNT ON

		BEGIN

			SET DATEFORMAT 'YMD'

			--TRAE TODOS LOS HEADERS CORRESPONDIENTES A LAS GESTIONES DE COBRANZAS

			-- ---------------------------------------------------
			-- TESTING
			-- ---------------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@cmdc_id	INT,
					@datefrom	DATETIME,
					@dateto		DATETIME
				SELECT
					@comp_id	= 1,
					@cmdc_id	= 1,
					@datefrom	= '2015-01-01',
					@dateto		= '2015-04-01'
			*/
			-- ---------------------------------------------------

			SELECT
				' '															[ ],	-- MODIFICAR
				' '															[ ],	-- CERRAR / ABRIR
				' '															[ ],	-- BORRAR
				ISNULL(tcmh.cmh_closed,'False')								[cmh_closed],
				'* ' + ISNULL(tcmh.cmh_desc,'')						[cmh_desc],
				tcmh.cmh_cd,
				ISNULL(tu.user_lastname + ',' + tu.user_firstname, '')		[User_Creator],
				ISNULL(tu2.user_lastname + ',' + tu2.user_firstname, '')	[User_LastUpdate],
				ISNULL(tcmh.cmh_note,'')									[cmh_note],
				tcmh.cmh_id													[ID]

			FROM tbCollectionManagementHeader			tcmh

				INNER JOIN tbUser						tu
					ON tu.[user_id]		= tcmh.user_id_4Create

				LEFT JOIN tbUser						tu2
					ON tu2.[user_id]	= tcmh.user_id4LastUpdate

			WHERE	tcmh.comp_id	= @comp_id								AND
					(@cmdc_id		= -1		OR tcmh.cmdc_id	= @cmdc_id) AND
					tcmh.cmh_cd		BETWEEN @datefrom	AND @dateto			AND
					(
						(@status	= -1)									OR
						(@status	= 0		AND tcmh.cmh_closed = 'False')	OR
						(@status	= 1		AND tcmh.cmh_closed	= 'True')
					)

		END
GO



