CREATE PROCEDURE spCollectionManagementHeader_InsertData
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@cmdc_id		INT,
	@cmh_desc		NVARCHAR(250),
	@cmh_note		NVARCHAR(4000),
	@return_value	INT OUTPUT
)
AS
	SET NOCOUNT ON

		BEGIN

			INSERT INTO tbCollectionManagementHeader
			(
				comp_id,
				-- cmh_id -- this column value is auto-generated,
				bra_id,
				cmh_closed,
				user_id_4Create,
				cmh_cd,
				user_id4LastUpdate,
				cmh_lastUpdate,
				cmdc_id,
				cmh_desc,
				cmh_note

			)
			VALUES
			(
				@comp_id,
				@bra_id,
				'False',
				@user_id,
				GETDATE(),
				@user_id,
				GETDATE(),
				@cmdc_id,
				@cmh_desc,
				@cmh_note
			)

			SET @return_value = @@IDENTITY

		END
GO



CREATE PROCEDURE spCollectionManagementHeader_UpdateStatus
(
	@comp_id	INT,
	@cmh_id		INT,
	@user_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN

			UPDATE tbCollectionManagementHeader
			SET
				cmh_closed			= ~cmh_closed,
				user_id4LastUpdate	= @user_id,
				cmh_lastUpdate		= GETDATE()

			WHERE	comp_id			= @comp_id AND
					cmh_id			= @cmh_id

		END
GO






