CREATE PROCEDURE [dbo].[spCollectionTmp_getDataByFilters]
(
	@lang_id			int,
	@guid				uniqueidentifier
)
as

BEGIN

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 300
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	set nocount on


-- --------------------------------------------------
-- Testing
-- --------------------------------------------------
	/*
	declare	@lang_id		int,
			@guid			uniqueidentifier
	select	@lang_id		=2,
			@guid			='643d1432-0d21-4a1d-a193-d81295cd4e52'
	*/
-- --------------------------------------------------





	declare @d int
	set		@d = 2


	select	' ' [ ], ' ' [ ],
			vct.guid,
			vct.description										[function],
			case vct.class
				when '1' then vct.[type]
				when '2' then (	select ov.[optval_desc]
									from dbo.[tbsysOptionsValues] ov	WITH (NOLOCK)
									where	ov.[optval_class]	= 28 and
											ov.[optval_id]		= vct.type and
											ov.[lang_id]		= @lang_id)
				when '3' then vct.[type]
				when '4' then vct.[type]
				when '5' then vct.[type]
			end													[type],
			convert(decimal(18,2),round(vct.amount,@d))			[amount],
			vct.currency,
			vct.[desc],
			vct.payDate											[payDate],
			vct.class + '-' + convert(varchar,vct.ID)			[ID]

	from	vwCollectionTmp		vct	WITH (NOLOCK)

	where	vct.guid	=	@guid
	and		vct.lang_id =	@lang_id


END
GO








