CREATE PROCEDURE [dbo].[spCollectionTmp_getDataToAccount]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@cust_id			int,
	@curr_id			int,
	@currExchange		decimal(19,6),
	@guid				UNIQUEIDENTIFIER,
	@user_id			int
)
AS



BEGIN



	set nocount on

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- -----------------------------------------
	-- -----------------------------------------
	/*
	declare	@comp_id			int,
			@lang_id			int,
			@bra_id				int,
			@cust_id			int,
			@curr_id			int,
			@currExchange		decimal(19,6),
			@guid				uniqueidentifier,
			@user_id			int
	select	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@cust_id			=24482,
			@curr_id			=1,
			@currExchange		=4.1,
			@guid				='267EB466-AA48-4124-A2CB-CED7FD00491F',
			@user_id			=1
	*/
	-- -----------------------------------------


	declare @d int
	set		@d = 2
	--CUSTOM_GN_001

	SELECT
			dbo.fnGetItemTransactions(ct.comp_id,ct.ct_transaction)		[1],
			' '															[2],
			' '															[3],
			dbo.fnGetCommercialTransactionDescription(ct.[comp_id],@lang_id,ct.[ct_transaction]) +
			CASE
				WHEN tctl.comp_id IS NULL THEN ''
				ELSE ' / ' + convert(nvarchar(3),tctl.ctl_payNumber)
			END																						[doc],
			ct.[ct_date],
			--CONVERT(DECIMAL(18,2),ROUND(ct.[ct_total],@d))											[ct_total],
			--CONVERT(DECIMAL(18,2),ROUND(ct.[ct_ATotal],@d))											[ct_ATotal],

			CASE
				WHEN tctl.comp_id IS NULL THEN	convert(decimal(18,2),round(		ct.[ct_total],		@d))
				ELSE							convert(decimal(18,2),round(		tctl.ct_ATotal,		@d))
			END																						[ct_total],
			CASE
				WHEN tctl.comp_id IS NULL THEN	convert(decimal(18,2),round(		ct.[ct_ATotal],		@d))
				ELSE							convert(decimal(18,2),round(		tctl.ct_ATotal,		@d))
			END																						[ct_ATotal],


			CASE
				WHEN tctl.comp_id IS NULL THEN	convert(decimal(18,2),round(		ct.[ct_ABalance],	@d))
				ELSE							convert(decimal(18,2),round(		tctl.ct_ABalance,	@d))
			END																						[ct_ABalance],

			--CONVERT(DECIMAL(18,2),ROUND(ct.[ct_ABalance],@d))										[ct_ABalance],

			CASE
				-- Si el un Comprobante
				WHEN tctl.comp_id IS NULL THEN	convert(decimal(18,2),round(isnull(	ctct.ctct_total,0)    ,	@d))
				-- Si son CUOTAS
				ELSE							convert(decimal(18,2),round(isnull(	ctctLoan.ctct_total,0),	@d))
			END																						[aCtaTotal],


			--CONVERT(DECIMAL(18,2),ROUND(ISNULL(ctct.ctct_total,0),@d))								[aCtaTotal],

			ct.[ct_ACurrencyExchange],
			CONVERT(DECIMAL(18,2),ROUND(dbo.[fnGetExchange](@comp_id, ct.[ct_ABalance],
						ct.ct_ACurrency, ct.curr_id_transaction, 0, @currExchange, 0),@d))			[ct_Balance],
			ISNULL(tcb.[custb_name],ISNULL(tcf.custf_name,''))										[custb_name],
			b2.[bra_desc],



			CASE
				WHEN tctl.comp_id IS NULL THEN	 ct.[ct_transaction]
				ELSE							-1 * tctl.ctl_id
			END																						[ID]			-- Count - 1


	FROM	dbo.tbCommercialTransactions								ct					WITH (NOLOCK)

			LEFT JOIN dbo.[tbCommercialTransactionsTmp]					ctct				WITH (NOLOCK)
			on	ctct.comp_id					=	ct.[comp_id]
			--and	ctct.bra_id						=	ct.[bra_id]
			and	ctct.ctct_transaction			=	ct.[ct_transaction]
			and	ctct.ctct_guid					=	@guid
			AND ctct.ctl_id						IS NULL

			INNER JOIN dbo.[vwCommercialTransactions_PaymentOnAccount]	VCTFS				WITH (NOLOCK)
			On	VCTFS.comp_id					=	ct.comp_id
			--and VCTFS.bra_id					=	ct.bra_id
			and VCTFS.ct_transaction			=	ct.ct_transaction

			INNER JOIN [tbsysCurrency]									sct					WITH (NOLOCK)
			on  sct.[curr_id]					=	ct.[curr_id_transaction]

			INNER JOIN	[tbBranch]										b1
			on	b1.[comp_id]					=	ct.[comp_id]
			and b1.[bra_id]						=	@bra_id
			--CUSTOM_GN_002
			INNER JOIN tbUsers4BranchFilter								vubf				WITH (NOLOCK)
			ON	vubf.comp_id					=	ct.comp_id
			AND	vubf.bra_id						=	ct.bra_id
			AND	vubf.[user_id]					=	@user_id

			INNER JOIN tbbranch												b2				WITH (NOLOCK)
				ON	b2.comp_id					= ct.comp_id AND
					b2.bra_id					= ct.bra_id

			left JOIN tbCustomerBranch									tcb			WITH (NOLOCK)
			ON  tcb.cb_id						=	ct.cb_id
			AND tcb.cust_id						=	ct.cust_id
			AND tcb.comp_id						=	ct.comp_id

			LEFT JOIN tbCommercialTransactionsLoan				tctl				WITH (NOLOCK)
				ON	tctl.comp_id		= ct.comp_id			AND
					tctl.ct_transaction = ct.ct_transaction		AND
					tctl.ct_ABalance	<> 0

			LEFT join dbo.tbCommercialTransactionsTmp			ctctLoan			WITH (NOLOCK)
				on	ctctLoan.comp_id		=	tctl.comp_id
				and	ctctLoan.ctl_id			=	tctl.ctl_id
				and	ctctLoan.ctct_guid		=	@guid

			LEFT JOIN tbCustomerFamily tcf											WITH (NOLOCK)
				ON	tcf.comp_id = ct.comp_id AND
					tcf.cust_id = ct.cust_id AND
					tcf.custf_id= ct.custf_id


	WHERE	ct.[comp_id]						=	@comp_id
	AND		ct.[cust_id]						=	@cust_id
	AND 	ct.[curr_id_transaction]			=   b1.curr_id
	AND     ct.[ct_Abalance]					<>	0
	AND 	ct.[ct_docNumber]					<>	''

	and		(
				(	b1.bra_CollectionOfAllBranches		=	'True'		AND
					b2.curr_id							=	@curr_id
				)
				OR
				(
					b1.bra_CollectionOfAllBranches		=	'False'		AND
					ct.bra_id							=	@bra_id
				)
			)
	--AND 	(
	--			(b1.bra_CollectionOfAllBranches	=	'True'
	--			AND ct.bra_id in (SELECT bra_id FROM [tbBranch] WITH (NOLOCK) WHERE curr_id = @curr_id))
	--			OR
	--			(b1.bra_CollectionOfAllBranches		=	'False'
	--			AND ct.bra_id						=	@bra_id)
	--		)
	AND		NOT ct.sd_id IN (56,66,156,166)

	ORDER BY ctct.ctct_total DESC, ct.[ct_payDate],ct.ct_transaction,tctl.ctl_id --[ID]



END
GO








CREATE  PROCEDURE [dbo].[spCollectionTmp_getDataToPay]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@cust_id			int,
	@curr_id			int,
	@guid				UNIQUEIDENTIFIER,
	@user_id			int
)
AS


BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	set nocount on
	-- =================================================================================================================
	-- Author		: MOS
	-- Update Date	: 2010-11-12
	-- Parte		: s/P referencia: #1
	-- Se quita una condición de inner join para que traiga comprobantes de diferentes sucursales
	-- =================================================================================================================


	-- ---------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------
	/*
	declare	@comp_id	int,
			@lang_id	int,
			@bra_id		int,
			@cust_id	int,
			@curr_id	int,
			@guid		UNIQUEIDENTIFIER,
			@user_id	int

	select	@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@cust_id	=24482,
			@curr_id	=1,
			@guid		='267EB466-AA48-4124-A2CB-CED7FD00491F',
			@user_id    =1
	*/
	-- ---------------------------------------------------------------------

	declare @d int
	set		@d = 2


	-- --------------------------------------------------
	-- Sucursales de la moneda informada como parametro
	-- --------------------------------------------------
	DECLARE @tmpBranch TABLE(bra_id INT PRIMARY KEY CLUSTERED)
	INSERT INTO @tmpBranch(bra_id)
		SELECT	tb.bra_id
			FROM tbBranch tb		WITH (NOLOCK)
			WHERE	tb.comp_id						= @comp_id	AND
					tb.curr_id						= @curr_id	AND
					tb.bra_disabled					= 'False'	AND
				   (tb.bra_CollectionOfAllBranches  = 'True' OR tb.bra_id = @bra_id)


	-- Agregamos Sucursales del Grupo de Sucursales para Cobranzas configurado en la sucursal actual.
	INSERT INTO @tmpBranch(bra_id)
		SELECT tbgd.bra_id
			FROM	tbBranch tb						WITH (NOLOCK)
			INNER JOIN tbBranchGroupDetail tbgd		WITH (NOLOCK)
				ON	tbgd.comp_id	= tb.comp_id				AND
					tbgd.brag_id	= tb.brag_id4Collection
			WHERE	tb.comp_id		= @comp_id					AND
					tb.bra_id		= @bra_id					AND
					tb.curr_id		= @curr_id					AND
					tb.bra_disabled = 'False'					AND
					(
						NOT EXISTS(
										SELECT TOP 1  1
											FROM @tmpBranch tmp2
											WHERE tbgd.bra_id = tmp2.bra_id
									)
					)

	-- --------------------------------------------------



	-- ATENCION
	-- Si se toca el Orden mirar en:
	--		VB *frhkewsjbfw8868 y
	--		SQL la tabla TEMPORAL del sp: spCollectionTmp_insertAllData
	-- ahora el SALDO esta en posicion 11

	SELECT

			dbo.fnGetItemTransactions(ct.comp_id,ct.ct_transaction)		[ ],
			' '															[ ],
			' '															[ ],
			dbo.fnGetCommercialTransactionDescription(ct.[comp_id],@lang_id,ct.[ct_transaction])	+
			CASE
				WHEN tctl.comp_id IS NULL THEN ''
				ELSE ' - ' + convert(nvarchar(3),ISNULL(tctl.ctl_payNumber,0)) + '/' + convert(nvarchar(3),ISNULL(tctl.ctl_payNumberTotalQty,0))
			END
																									[doc],
			CASE
				WHEN tctl.comp_id IS NULL THEN	ct.[ct_payDate]
				ELSE							tctl.ctl_payDate
			END																						[ct_payDate],

			CASE
				WHEN tctl.comp_id IS NULL THEN DATEDIFF(day, ct.ct_payDate,b.bra_processingDate)
				WHEN tctl.comp_id IS NOT NULL AND tctl.ctl_daysPastDue < 0 THEN 0
				ELSE tctl.ctl_daysPastDue
			END																						[moraDays],


			CASE
				WHEN tctl.comp_id IS NULL THEN	convert(decimal(18,2),round(		ct.[ct_ATotal],		@d))
				ELSE							convert(decimal(18,2),round(		tctl.ct_ATotal,		@d))
			END																						[ct_ATotal],
			CASE
				WHEN tctl.comp_id IS NULL THEN	convert(decimal(18,2),round(		ct.[ct_ABalance],	@d))
				ELSE							convert(decimal(18,2),round(		tctl.ct_ABalance,	@d))
			END																						[ct_ABalance],
			CASE
				-- Si el un Comprobante
				WHEN tctl.comp_id IS NULL THEN	convert(decimal(18,2),round(isnull(	ctct.ctct_total,0)    ,	@d))
				-- Si son CUOTAS
				ELSE							convert(decimal(18,2),round(isnull(	ctctLoan.ctct_total,0),	@d))
			END																						[payTotal],

			ISNULL(tcb.[custb_name],ISNULL(tcf.custf_name,''))										[custb_name],
			tst.st_desc,
			s.[sm_name],
			CASE	-- MOS 03-2022: Estaba debajo del tipo de cambio entre el cambio y la moneda.  daba para confusion..
				WHEN tctl.comp_id IS NULL THEN	convert(decimal(18,2),round(		ct.[ct_total],		@d))
				ELSE							convert(decimal(18,2),round(		tctl.ct_ATotal,		@d))
			END																						[ct_total],
			CONVERT(DECIMAL(25,8),
								case
									WHEN IsNull(ct.ct_ACurrencyExchange,1) <> 1 THEN  round(ct.[ct_ACurrencyExchange],@d)
									ELSE IsNull(ct.ct_dfExchange,0)
								end
					)																				[ct_ACurrencyExchange],
			tc.curr_symbol																			[curr_id2Print],
			ct.ct_cd																				[OrigDate],


			b.[bra_desc],
			CASE
				WHEN tctl.comp_id IS NULL THEN	 ct.[ct_transaction]
				ELSE							-1 * tctl.ctl_id
			END																						[ID]


	FROM	dbo.tbCommercialTransactions								ct			WITH (NOLOCK)

			INNER JOIN @tmpBranch tmpb
				ON tmpb.bra_id = ct.bra_id

			INNER JOIN tbUsers4BranchFilter								vubf		WITH (NOLOCK)
			ON	vubf.comp_id					=	ct.comp_id
			AND	vubf.bra_id						=	ct.bra_id
			AND	vubf.[user_id]					=	@user_id

			LEFT join dbo.[tbCommercialTransactionsTmp]					ctct		WITH (NOLOCK)
			on	ctct.comp_id					=	ct.[comp_id]
			and	ctct.ctct_transaction			=	ct.[ct_transaction]
			and	ctct.ctct_guid					=	@guid
			AND ctct.ctl_id						IS NULL

			inner join dbo.vwCommercialTransactions_forSales			VCTFS		WITH (NOLOCK)
			On	VCTFS.comp_id					=	ct.comp_id
			--and VCTFS.bra_id					=	ct.bra_id
			and VCTFS.ct_transaction			=	ct.ct_transaction

			inner join [tbsysCurrency]									sct			WITH (NOLOCK)
			on  sct.[curr_id]					=	ct.[curr_id_transaction]

			inner join [tbsysCurrency]									scat		WITH (NOLOCK)
			on  scat.[curr_id]					=	ct.[ct_ACurrency]

			left join [tbSalesman]										s			WITH (NOLOCK)
			on	s.[comp_id]						=	ct.[comp_id]
			and	s.[sm_id]						=	ct.[sm_id]

			inner join	[tbBranch]										b			WITH (NOLOCK)
			on	b.[comp_id]						=	ct.[comp_id]
			and b.[bra_id]						=	ct.[bra_id]

			INNER JOIN	[tbBranch]										b1			WITH (NOLOCK)
			on	b1.[comp_id]					=	ct.[comp_id]
			and b1.[bra_id]						=	@bra_id



			INNER JOIN [tbDocumentsFile]								tdf			WITH (NOLOCK)
			ON	tdf.comp_id						=	ct.comp_id
			AND	tdf.df_id						=	ct.df_id

			INNER JOIN [tbBranch]										tb			WITH (NOLOCK)
			ON	tb.comp_id						=	ct.comp_id
			AND tb.bra_id						=	ct.bra_id

			INNER JOIN tbsysCurrency									tc			WITH (NOLOCK)
			ON	tc.curr_id						=	isnull(tdf.df_curr_id2Print,tb.curr_id)



			INNER JOIN tbSalesTerms tst												WITH (NOLOCK)
				ON		tst.comp_id				= ct.comp_id
					AND tst.st_id				= ct.st_id

			LEFT JOIN tbCommercialTransactionsLoan				tctl				WITH (NOLOCK)
				ON	tctl.ct_transaction = ct.ct_transaction		AND
					tctl.ct_ABalance	<> 0

			LEFT join dbo.[tbCommercialTransactionsTmp]			ctctLoan			WITH (NOLOCK)
				on	ctctLoan.comp_id		=	tctl.[comp_id]
				and	ctctLoan.ctl_id			=	tctl.ctl_id
				and	ctctLoan.ctct_guid		=	@guid

			left JOIN tbCustomerBranch									tcb			WITH (NOLOCK)
			ON  tcb.comp_id						=	ct.comp_id	AND
				tcb.cust_id						=	ct.cust_id	AND
				tcb.cb_id						=	ct.cb_id

			LEFT JOIN tbCustomerFamily tcf											WITH (NOLOCK)
				ON	tcf.comp_id = ct.comp_id AND
					tcf.cust_id = ct.cust_id AND
					tcf.custf_id= ct.custf_id


	where	ct.[comp_id]						=	@comp_id
	and	    ct.[cust_id]						=	@cust_id
	and		ct.[curr_id_transaction]			=   b1.curr_id

	and     VCTFS.[sd_isInBalance]				=	'True'
	and	    VCTFS.[sd_isCredit]					=	'False'
	and	    VCTFS.[sd_isReceipt]				=	'False'
	and     ct.[ct_Abalance]					<>	0
	and		ct.[ct_docNumber]					<>	''

	--and

	--		(
	--			tmpb.bra_CollectionOfAllBranches		=	'True'
	--			OR
	--			(
	--				tmpb.bra_CollectionOfAllBranches	=	'False'		and
	--				tmpb.bra_id							=	@bra_id
	--			)
	--		)



	order by	[payTotal] desc,
				CASE
					WHEN tctl.comp_id IS NULL THEN	ct.ct_payDate
					ELSE							tctl.ctl_payDate
				END,
				ct.ct_transaction,
				tctl.ctl_id


END
GO







CREATE PROCEDURE [dbo].[spCollectionTmp_insertAllData]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@cust_id			INT,
	@curr_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@origin				VARCHAR(1),
	@user_id			INT
)
AS



BEGIN



	set nocount on


-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
	/*
	declare	@comp_id	int,
			@lang_id	int,
			@bra_id		int,
			@cust_id	int,
			@curr_id	int,
			@guid		UNIQUEIDENTIFIER,
			@origin		varchar(1),
			@user_id	INT

	select	@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@cust_id	=24454,
			@curr_id	=1,
			@guid		='12b1fdec-2ea9-4134-9c6f-6513ac7d5d66',
			@origin		='h',
			@user_id	=1
	--DROP TABLE #tmpDataToPay
	*/
-- ------------------------------------------------------







	CREATE TABLE #tmpDataToPay
	(
		column1					NVARCHAR(4000),
		column2					NVARCHAR(4000),
		column3					NVARCHAR(4000),
		doc						VARCHAR(150),
		ct_payDate				DATETIME,
		moradays				INT,
		ct_ATotal				DECIMAL(18,2),
		ct_ABalance				DECIMAL(18,2),
		payTotal				DECIMAL(18,2),
		custb_name				NVARCHAR(1000),
		st_desc					NVARCHAR(1000),
		sm_name					NVARCHAR(1000),
		ct_ACurrencyExchange	DECIMAL(18,2),
		ct_total				DECIMAL(18,2),
		curr_id2Print			NVARCHAR(10),
		OrigDate				DATETIME,
		bra_desc				NVARCHAR(4000),
		ID						INT
	)




	INSERT INTO #tmpDataToPay
		EXEC spCollectionTmp_getDataToPay
                          		@comp_id,
                          		@lang_id,
                          		@bra_id,
                          		@cust_id,
                          		@curr_id,
                          		@guid,
                          		@user_id



	DECLARE 	@lcolumn1					NVARCHAR(4000),
				@lcolumn2					NVARCHAR(4000),
				@lcolumn3					NVARCHAR(4000),
				@ldoc						VARCHAR(150),
				@lct_total					DECIMAL(18,2),
				@lBranchCurrency			VARCHAR(150),
				@lct_ATotal					DECIMAL(18,2),
				@lct_ABalance				DECIMAL(18,2),
				@lpayTotal					DECIMAL(18,2),
				@lct_payDate				DATETIME,
				@lCustomerCurrency			VARCHAR(50),
				@lct_ACurrencyExchange		DECIMAL(18,2),
				@lsm_name					VARCHAR(150),
				@lbra_desc					VARCHAR(150),
				@lID					    INT,
				@lsuppa_name				VARCHAR(150),
				@lreturn_value 				INT


	DECLARE cursor_PT_iAD_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT 	doc,
				ct_total,
				--BranchCurrency,
				ct_ATotal,
				ct_ABalance,
				payTotal,
				ct_payDate,
				--CustomerCurrency,
				ct_ACurrencyExchange,
				sm_name,
				bra_desc,
				ID
			FROM #tmpDataToPay
		--WHERE pds_isOk = 1   -- Que NO tengan autorizaciones de pago pendientes!!!




	OPEN cursor_PT_iAD_data

	fetch cursor_PT_iAD_data into
							@ldoc,
							@lct_total,
							--@lBranchCurrency,
							@lct_ATotal,
							@lct_ABalance,
							@lpayTotal,
							@lct_payDate,
							--@lCustomerCurrency,
							@lct_ACurrencyExchange,
							@lsm_name,
							@lbra_desc,
							@lID



	while @@FETCH_STATUS = 0
	BEGIN



		EXEC spCommercialTransactionsTmp_insertData
			@comp_id,
			@bra_id,
			@guid,
			@lID,
			@lct_ABalance,
			@origin,
			@lct_ACurrencyExchange,
			@lreturn_value

		fetch cursor_PT_iAD_data
			into	@ldoc,
					@lct_total,
					--@lBranchCurrency,
					@lct_ATotal,
					@lct_ABalance,
					@lpayTotal,
					@lct_payDate,
					--@lCustomerCurrency,
					@lct_ACurrencyExchange,
					@lsm_name,
					@lbra_desc,
					@lID

	END

	close cursor_PT_iAD_data
	deallocate cursor_PT_iAD_data


	DROP TABLE #tmpDataToPay




END
GO




