CREATE PROCEDURE [dbo].[spColor_GetDataById]
(
	@comp_id	INT,

	@color_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN

			SELECT
				tc.comp_id,
				tc.color_id,
				tc.color_desc,
				tc.color_code

			FROM tbColor						tc			 WITH (NOLOCK)
			WHERE	tc.comp_id	= @comp_id		AND
					tc.color_id = @color_id

		END
GO






CREATE PROCEDURE [dbo].[spColor_getDataByText]
(
	@text		VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id	 AS int
)
AS

BEGIN

	SET NOCOUNT ON

	-- ------------------------------------
	-- Test
	-- ------------------------------------
	/*
	DECLARE
		@text		VARCHAR(300),
		@count		INT,
		@lang_id	INT
	SELECT
		@text		= 'R',
		@count		= 2,
		@lang_id	= 2

	*/
	-- ------------------------------------




	SELECT		TOP (@count)
				dbo.fnStrPADR(	ta.color_desc,40,'.') + ' | ' + isnull(convert(varchar,ta.color_code),'') + ' | ' + isnull(convert(varchar,ta.color_id),'') [acc_desc],
				ta.color_id
		FROM tbColor  ta		WITH (NOLOCK)
		WHERE		comp_id = @comp_id				AND
				   (	ta.color_desc LIKE '%' + @text + '%'
						OR
						ta.color_code LIKE @text+'%'
				   )
		ORDER BY	ta.color_desc

END
GO


CREATE PROCEDURE [dbo].[spCommercialTransaction_ArchivoFC_Chile_TEST]
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT

			SELECT
				@comp_id		= 18,
				@ct_transaction	= 8962
		*/
		-- ---------------------------------------------

		SELECT
			CASE
				WHEN tct.sd_id	= 1 AND tdf.df_isElectronicInvoice		= 'False'	THEN 30	--FC
				WHEN tct.sd_id	= 1 AND tdf.df_isElectronicInvoice		= 'True'	THEN 35	--FC ELECTRONICA
				WHEN tct.sd_id	= 2	OR  tct.sd_id						= 12		THEN 50	--GUIA DESPACHO
				WHEN tct.sd_id	= 3													THEN 60	--NOTA DE CREDITO
				WHEN tct.sd_id	= 4													THEN 55 --NOTA DE DEBITO
				WHEN tct.sd_id	= 101 AND tdf.df_isElectronicInvoice	= 'False'	THEN 45	--FC DE COMPRA
				WHEN tct.sd_id  = 101 AND tdf.df_isElectronicInvoice	= 'True'	THEN 46 --FC ELECTRONICA DE COMPRA
			ELSE 9999
			END															[TipoDTE],
			tct.ct_pointOfSale											[Folio],
			tct.ct_date													[FechaEmision],
			0															[TipoDespacho],
			1															[IndTraslado],
			tc.cust_taxNumber											[RUTCliente], --(TIENE QUE TENER EL GUION Y EL DIGITO VERIFICADOR 11111111-1 )
			tc.cust_name												[RSCliente],
			''															[GiroCliente],
			tc.cust_address												[DirCliente],
			'COMUNA'													[ComCliente],
			ISNULL(tsc.city_desc,'')									[CiuCliente],
			ISNULL(tc.cust_email,'')									[Email]
		FROM tbCommercialTransactions			tct	WITH(NOLOCK)
		INNER JOIN tbDocumentsFile				tdf WITH(NOLOCK)
		ON	tdf.df_id		= tct.df_id			AND
			tdf.comp_id		= tct.comp_id
		INNER JOIN tbCustomer					tc	WITH(NOLOCK)
		ON	tc.comp_id		= tct.comp_id		AND
			tc.cust_id		= tct.cust_id
		LEFT JOIN tbSysCities					tsc	WITH(NOLOCK)
		ON	tsc.country_id	= tc.country_id		AND
			tsc.state_id	= tc.state_id		AND
			tsc.city_id		= tc.city_id
		WHERE	tct.comp_id			= @comp_id	AND
				tct.ct_transaction	= @ct_transaction

		--TOTALES
		--IVA TAX
		DECLARE @decTasaIVA AS DECIMAL(19,2)
		SELECT TOP 1
			 @decTasaIVA			= ttn.tax_percentage
		FROM tbItemTransactions					tit		WITH(NOLOCK)
		INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
		ON	tit2.comp_id			= tit.comp_id AND
			tit2.item_id			= tit.item_id
		INNER JOIN tbTaxName					ttn		WITH(NOLOCK)
		ON	ttn.comp_id				= tit2.comp_id AND
			ttn.tax_id				= tit2.tax_id
		WHERE	tit.comp_id			= @comp_id	AND
				tit.ct_transaction	= @ct_transaction



		SELECT
			ISNULL(td.disc_coef,0)				[PorcDesctoTot],
			ISNULL(tct.ct_discount,0)			[ValorDesctoTot],
			0									[PorcRecgoTot],
			0									[ValorRecgoTot],
			tct.ct_Atotal						[Neto],
			0									[Exento],
			@decTasaIVA							[TasaIVA], --ESTO DE DONDE LO SACO A NIVEL GENERAL?
			tct.ct_taxes						[IVA],
			tct.ct_ATotal						[Total],
			0									[Retención],
			0									[ImpuestoEspecifico]

		FROM tbCommercialTransactions			tct	WITH(NOLOCK)
		LEFT JOIN tbDiscount					td
		ON td.comp_id = tct.comp_id AND td.disc_id = tct.disc_id
		WHERE	tct.comp_id			= @comp_id	AND
				tct.ct_transaction	= @ct_transaction





		--ARTICULOS
		SELECT
			tit.it_order				[NroLinea],
			ti.item_code				[Código],
			ti.item_desc				[Descripcion],
			tit.it_qty					[Cantidad],
			tit.it_price				[Precio],
			0							[PorcDescto],
			tit.it_totalDiscountTotal	[ValorDescto],
			0							[PorcRecgo],
			0							[ValorRecgo],
			0							[ValorExento],
			0							[Valor],
			'INT1'						[TipoCodigo],
			ISNULL(tmu.mu_shortDesc,'')	[UniMedida],
			ti.item_detail				[DescLarga]
		FROM tbItemTransactions tit
		INNER JOIN tbItem						ti		WITH(NOLOCK)
		ON	ti.comp_id			= tit.comp_id	AND
			ti.item_id			= tit.item_id
		LEFT JOIN tbMetricUnits					tmu		WITH(NOLOCK)
		ON	tmu.comp_id			= ti.comp_id	AND
			tmu.mu_id			= ti.mu_id
		INNER JOIN tbCommercialTransactions		tct		WITH(NOLOCK)
		ON	tct.comp_id			= tit.comp_id	AND
			tct.ct_transaction	= tit.ct_transaction
		INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
		ON	tit2.comp_id		= ti.comp_id	AND
			tit2.item_id		= ti.item_id
		INNER JOIN tbTaxName					ttn
		ON	ttn.tax_id			= tit2.tax_id	AND
			ttn.comp_id			= tit2.comp_id
		WHERE	tit.comp_id			= @comp_id	AND
				tit.ct_transaction	= @ct_transaction



		--OBSERVACIONES
		SELECT
			tctn.ctn_note1								[Linea1],
			tctn.ctn_note2								[Linea2],
			tctn.ctn_note3								[Linea3]
		FROM tbCommercialTransactionNotes				tctn	WITH(NOLOCK)
		WHERE	tctn.comp_id		= @comp_id			AND
				tctn.ct_transaction = @ct_transaction

	END
GO






CREATE PROCEDURE [dbo].[spCommercialTransaction_CustUpdate]
(
	@comp_id						AS INT,
	@ct_transaction					AS INT,
	@date							AS DATETIME,
	@sm_id							AS INT,
	@ct_date						AS DATETIME,
	@ct_docNumber					AS NVARCHAR(50),
	@ct_PointOfSale					AS int,
	@st_id							as INT,
	@ct_taxDate						as DATETIME,
	@state_id						AS INT,
	@cb_id							AS INT,
	@custf_id						AS INT,
	@dl_id							AS INT,
	@ctn_note1						VARCHAR(350),
	@ctn_note2						VARCHAR(350),
	@ctn_note3						VARCHAR(350),
	@ctn_note4						VARCHAR(350),
	@bra_id							INT,
	@deliveryDate					AS DATETIME,
	@ctn_deliveryAddressOfSaleOrder	VARCHAR(700),
	@pro_id							AS INT







)
AS
SET NOCOUNT ON

SET DATEFORMAT 'ymd'


-------------------------------------------------
/*
DECLARE
	@comp_id		AS INT,
	@ct_transaction AS INT,
	@date			AS DATETIME,
	@sm_id			AS INT,
	@ct_date		AS DATETIME,
	@ct_docNumber	AS NVARCHAR(50),
	@ct_PointOfSale AS INT,
	@state_id		AS INT



SELECT
	@comp_id		=1,
	@ct_transaction	=5481,
	@date			='2009-06-21',
	@sm_id			= 4

*/

-------------------------------------------------

if	(@cb_id			= -1)	set	@cb_id			= NULL
if	(@custf_id		= -1)	set	@custf_id		= NULL
if	(@dl_id			= -1)	set	@dl_id			= NULL
if	(@pro_id		= -1)	set	@pro_id			= NULL



UPDATE dbo.tbCommercialTransactions

	SET ct_payDate		= @date,
		sm_id			= @sm_id,
		ct_date			= @ct_date,
	    ct_docNumber	= @ct_docNumber,
	    ct_pointOfSale	= @ct_PointOfSale,
	    st_id			= @st_id,
	    ct_taxDate		= @ct_taxDate,
	    state_id		= @state_id,
	    cb_id			= @cb_id,
	    custf_id		= @custf_id,
	    dl_id			= @dl_id,
	    ct_deliveryDate = @deliveryDate,
	    pro_id			= @pro_id



WHERE comp_id			= @comp_id
AND	  ct_transaction	= @ct_transaction




		--Actualiza las notas.

		IF not EXISTS(SELECT TOP 1  1
						FROM tbCommercialTransactionNotes tctn
						WHERE	tctn.comp_id		= @comp_id	AND
								tctn.ct_transaction = @ct_transaction)
			BEGIN

				INSERT INTO tbCommercialTransactionNotes
					(	comp_id,
						bra_id,
						ct_transaction,
						ctn_note1,
						ctn_note2,
						ctn_note3,
						ctn_note4,
						ctn_internalAnnotation,
						ctn_deliveryAddressOfSaleOrder)

					Values
					(	@comp_id,
						@bra_id,
						@ct_transaction,
						@ctn_note1,
						@ctn_note2,
						@ctn_note3,
						@ctn_note4,
						'',
						@ctn_deliveryAddressOfSaleOrder)


			END
		ELSE
			BEGIN
					UPDATE tbCommercialTransactionNotes
				SET

					ctn_note1						= @ctn_note1,
					ctn_note2						= @ctn_note2,
					ctn_note3						= @ctn_note3,
					ctn_note4						= @ctn_note4,
					ctn_deliveryAddressOfSaleOrder  = @ctn_deliveryAddressOfSaleOrder

				WHERE	comp_id			= @comp_id
				AND		ct_transaction	= @ct_transaction

			END



GO



CREATE PROCEDURE [dbo].[spCommercialTransaction_ElectronicInvoice_Boleta_Chile_GetData]
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT

			SELECT
				@comp_id		= 18,
				@ct_transaction	= 9305
		*/
		-- ---------------------------------------------


		-- ------------------------------------------------------------------------------------
		-- ->Boleta<-
		-- ------------------------------------------------------------------------------------

			SELECT
				39												[TIPODTE],		--TIPODTE					--REVISAR
				0												[Folio],		--Folio tct.ct_docNumber	--REVISAR
				tct.ct_date										[FechaEmision],	--FechaEmision
				3												[IndServicio],	--IndServicio				--REVISAR
				0												[IndMntNeto],	--IndMntNeto				--REVISAR
				CONVERT(DATE, GETDATE(), 101)					[PeriodoDesde],	--PeriodoDesde				--REVISAR
				CONVERT(DATE, GETDATE(), 101)					[PeriodoHasta],	--PeriodoHasta				--REVISAR
				tct.ct_payDate									[FechaVenc],	--FechaVenc
				tc.cust_taxNumber								[RUTCliente],	--RUTCliente
				tc.cust_id										[CodInterno],	--CodInterno
				CONVERT(VARCHAR(100),tc.cust_name)				[RSCliente],	--RSCliente
				CONVERT(VARCHAR(40),ttca.stca_desc)				[GiroCliente],	--GiroCliente				--REVISAR
				CONVERT(VARCHAR(60),tc.cust_address)			[DirCliente],	--DirCliente
				--'COMUNA'										[ComCliente],	--ComCliente				--REVISAR
				--ISNULL(tsc.city_desc,'')						[CiuCliente],	--CiuCliente

				CONVERT(VARCHAR(20),ISNULL(tc.cust_city,''))	[ComCliente],
				CONVERT(VARCHAR(20),ISNULL(tc.cust_city,''))	[CiuCliente],
				CONVERT(VARCHAR(200),tc.cust_email)				[Email]			--Email
				FROM tbCommercialTransactions				tct	WITH(NOLOCK)
					INNER JOIN tbCustomer					tc	WITH(NOLOCK)
					ON	tc.comp_id			= tct.comp_id	AND
						tc.cust_id			= tct.cust_id
					LEFT JOIN tbsysTax_ChileActividad		ttca WITH(NOLOCK)
					ON	ttca.stca_id		= tc.stca_id
				WHERE	tct.comp_id			= @comp_id		AND
						tct.ct_transaction	= @ct_transaction

		-- ------------------------------------------------------------------------------------


		-- ------------------------------------------------------------------------------------
		-- ->BoletaTotales<-
		-- ------------------------------------------------------------------------------------

			--IVA TAX
			DECLARE @decTasaIVA AS DECIMAL(19,0)
			SELECT TOP 1
				@decTasaIVA					= ttn.tax_percentage
				FROM tbItemTransactions						tit		WITH(NOLOCK)
					INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
					ON	tit2.comp_id		= tit.comp_id	AND
						tit2.item_id		= tit.item_id
					INNER JOIN tbTaxName					ttn		WITH(NOLOCK)
					ON	ttn.comp_id			= tit2.comp_id	 AND
						ttn.tax_id			= tit2.tax_id
				WHERE	tit.comp_id			= @comp_id		AND
						tit.ct_transaction	= @ct_transaction


			SELECT
				CONVERT(DECIMAL(19,0),tct.ct_subtotal - tct.ct_discount)								[NETO],			--NETO
				0																						[EXCENTO],		--EXCENTO		--REVISAR
				/*CONVERT(DECIMAL(19,0),((tct.ct_subtotal - tct.ct_discount) * @decTasaIVA/100))		[IVA],			--IVA*/
				/*ESTO DE ARRIBA ESTABA ANTES HAY CIERTOS REDONDEOS QUE LOS HACE HACIA ARRIBA Y TIRA ERROR AL EMITIR*/
				/*FLOOR(CONVERT(DECIMAL(19,2),((tct.ct_subtotal - tct.ct_discount) * @decTasaIVA/100)))	[IVA],			--IVA*/
				tct.ct_taxes																			[IVA],
				CONVERT(DECIMAL(19,0),tct.ct_total)														[Total],		--Total
				0																						[MontoNF],		--MontoNF		--REVISAR
				CONVERT(DECIMAL(19,0),tct.ct_total)														[TotalPeriodo],	--TotalPeriodo
				0																						[SaldoAnterior],--SaldoAnterior	--REVISAR
				0																						[ValorAPagar]	--ValorAPagar	--REVISAR
				FROM tbCommercialTransactions					tct	WITH(NOLOCK)
				WHERE	tct.comp_id			= @comp_id			AND
						tct.ct_transaction	= @ct_transaction

		-- ------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------
		-- ->BoletaDetalle<-
		-- ------------------------------------------------------------------------------------

			SELECT
				tit.it_order																			[NroLinea],
				ti.item_code																			[Codigo],
				ti.item_desc																			[Descripcion],
				0																						[IndExencion],	--IndExencion	--REVISAR
				CONVERT(DECIMAL(19,0),tit.it_qty)														[Cantidad],
				CONVERT(DECIMAL(19,0),	tit.it_price *
										dbo.[fnGetPriceListItemTaxesCoeficient](tit.comp_id,tit.item_id))
																										[Precio],

				0																						[ValorExento],	--ValorExento	--REVISAR
				CONVERT(DECIMAL(19,0),	tit.it_price *
										dbo.[fnGetPriceListItemTaxesCoeficient](tit.comp_id,tit.item_id)) *
										tit.it_qty														[Valor],		--VALOR esto es el precio con IVA incluido (como sacarlo??)

				'INT1'																					[TipoCodigo],	--TipoCodigo
				ISNULL(tmu.mu_shortDesc,'')																[UniMedida],	--UniMedida
				ti.item_detail																			[DescLarga]		--DescLarga
				FROM tbItemTransactions						tit	WITH(NOLOCK)
					INNER JOIN tbItem						ti	WITH(NOLOCK)
					ON	ti.comp_id			= tit.comp_id	AND
						ti.item_id			= tit.item_id
					LEFT JOIN tbMetricUnits		tmu		WITH(NOLOCK)
					ON	tmu.comp_id			= ti.comp_id	AND
						tmu.mu_id			= ti.mu_id
				WHERE	tit.comp_id			= @comp_id		AND
						tit.ct_transaction	= @ct_transaction

		-- ------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------
		--  ->BoletaDescRec<-
		-- ------------------------------------------------------------------------------------
		/*
		Indica el o los descuentos y/o recargos globales que se realizan para una transacción tributaria en un documento electrónico con el formato de Boleta.
		Una Boleta puede tener o no descuentos y/o recargos globales.
		*/

		-- ------------------------------------------------------------------------------------
			SELECT 'NOTHING'			--REVISAR

		-- ------------------------------------------------------------------------------------
		-- ->BoletaReferencia<-
		-- ------------------------------------------------------------------------------------
			SELECT 'NOTHING'			--REVISAR
		-- ------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------
		-- ->Observacion<-
		-- ------------------------------------------------------------------------------------

			SELECT
				CONVERT(VARCHAR(60),tctn.ctn_note1)			[Linea1],
				CONVERT(VARCHAR(60),tctn.ctn_note2)			[Linea2],
				CONVERT(VARCHAR(60),tctn.ctn_note3)			[Linea3]
				FROM tbCommercialTransactionNotes			tctn	WITH(NOLOCK)
				WHERE	tctn.comp_id		= @comp_id		AND
						tctn.ct_transaction = @ct_transaction

		-- ------------------------------------------------------------------------------------
	END
GO



CREATE PROCEDURE [dbo].[spCommercialTransaction_ElectronicInvoice_Factura_Chile_GetData]
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT

			SELECT
				@comp_id		= 18,
				@ct_transaction	= 9281
		*/
		-- ---------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		-- ENCABEZADO
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			CASE
				WHEN tct.sd_id	= 1 AND tdf.df_isElectronicInvoice		= 'True'	THEN 33	--FC ELECTRONICA ANTES ERA 35 ahhora 33
			ELSE 33
			END															[TipoDTE],
			--4500000														[Folio],
			tdf.df_number												[Folio],
			tct.ct_date													[FechaEmision],
			1															[TipoDespacho], --ANTES PUSE 0
			1															[IndTraslado],

			tc.cust_taxNumber											[RUTCliente], --(TIENE QUE TENER EL GUION Y EL DIGITO VERIFICADOR 11111111-1 )
			CONVERT(VARCHAR(100),tc.cust_name)							[RSCliente],
			CONVERT(VARCHAR(40),ttca.stca_desc)							[GiroCliente],
			CONVERT(VARCHAR(60),tc.cust_address)						[DirCliente],
			ISNULL(tc.cust_city,'')										[ComCliente],
			--ISNULL(CONVERT(VARCHAR(20),tsc.city_desc),'Ciudad')			[CiuCliente],
			CONVERT(VARCHAR(20),ISNULL(tc.cust_city,''))				[CiuCliente],
			ISNULL(tc.cust_email,'')									[Email],


			ISNULL(tc.cust_contact,'')									[Contacto],

			--EMISOR
			tc2.comp_desc,																--RAZON SOCIAL
			CONVERT(VARCHAR(20),tb.bra_desc)							[bra_desc],		--SUCURSAL
			CONVERT(VARCHAR(60),tb.bra_address)							[bra_address],	--DIRECCION
			tb.bra_taxNumber,											--RUT			--TIENE QUE TENER GUION Y DIGITO VERIFICADOR
			tdf.df_electronicInvoiceChile_Emisor_Giro					[GiroEmisor],
			tdf.df_electronicInvoiceChile_Emisor_Comuna					[ComunaEmisor],
			tdf.df_electronicInvoiceChile_Emisor_Ciudad					[CiudadEmisor],
			tdf.stca_id													[ActEcoEmisor]


			FROM tbCommercialTransactions								tct	WITH(NOLOCK)
			INNER JOIN tbDocumentsFile									tdf WITH(NOLOCK)
			ON	tdf.df_id				= tct.df_id						AND
				tdf.comp_id				= tct.comp_id
			INNER JOIN tbCustomer										tc	WITH(NOLOCK)
			ON	tc.comp_id				= tct.comp_id					AND
				tc.cust_id				= tct.cust_id
			--LEFT JOIN tbSysCities										tsc	WITH(NOLOCK)
			--ON	tsc.country_id			= tc.country_id					AND
			--	tsc.state_id			= tc.state_id					AND
			--	tsc.city_id				= tc.city_id
			LEFT JOIN tbsysTax_ChileActividad							ttca WITH(NOLOCK)
			ON	ttca.stca_id			= tc.stca_id




			INNER JOIN tbCompany										tc2 WITH(NOLOCK)
			ON	tc2.comp_id				= tct.comp_id
			INNER JOIN tbBranch											tb	WITH(NOLOCK)
			ON	tb.comp_id				= tct.comp_id AND
				tb.bra_id				= tct.bra_id


			LEFT JOIN tbsysTax_ChileActividad							AS ttca2 WITH(NOLOCK)
			ON	ttca2.stca_id			= tdf.stca_id



			WHERE	tct.comp_id			= @comp_id						AND
					tct.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------------------
		--TOTALES
		-- -----------------------------------------------------------------------------------------------------
		--IVA TAX
		DECLARE @decTasaIVA AS DECIMAL(19,0)
		SELECT TOP 1
			 @decTasaIVA			= ttn.tax_percentage
		FROM tbItemTransactions					tit		WITH(NOLOCK)
		INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
		ON	tit2.comp_id			= tit.comp_id AND
			tit2.item_id			= tit.item_id
		INNER JOIN tbTaxName					ttn		WITH(NOLOCK)
		ON	ttn.comp_id				= tit2.comp_id AND
			ttn.tax_id				= tit2.tax_id
		WHERE	tit.comp_id			= @comp_id	AND
				tit.ct_transaction	= @ct_transaction



		SELECT
			CONVERT(DECIMAL(19,0),ISNULL(td.disc_coef,0))					[PorcDesctoTot],
			CONVERT(DECIMAL(19,0),ISNULL(tct.ct_discount,0))				[ValorDesctoTot],
			0																[PorcRecgoTot],
			0																[ValorRecgoTot],
			--tct.ct_Atotal						[Neto],
			CONVERT(DECIMAL(19,0),tct.ct_subtotal - tct.ct_discount)		[Neto],
			0																[Exento],
			@decTasaIVA														[TasaIVA], --ESTO DE DONDE LO SACO A NIVEL GENERAL?
			CONVERT(DECIMAL(19,0),tct.ct_taxes)								[IVA],
			CONVERT(DECIMAL(19,0),tct.ct_total)								[Total],
			--tct.ct_ATotal						[Total],
			0																[Retención],
			0																[ImpuestoEspecifico]
			FROM tbCommercialTransactions				tct	WITH(NOLOCK)
			LEFT JOIN tbDiscount						td	WITH(NOLOCK)
			ON	td.comp_id				= tct.comp_id	AND
				td.disc_id				= tct.disc_id
			WHERE	tct.comp_id			= @comp_id		AND
					tct.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		--ARTICULOS
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			tit.it_order										[NroLinea],
			ti.item_code										[Código],
			ti.item_desc										[Descripcion],
			CONVERT(DECIMAL(19,0),tit.it_qty)					[Cantidad],
			CONVERT(DECIMAL(19,0),tit.it_price)					[Precio],
			0													[PorcDescto],
			CONVERT(DECIMAL(19,0),tit.it_totalDiscountTotal)	[ValorDescto],
			0													[PorcRecgo],
			0													[ValorRecgo],
			0													[ValorExento],
			0													[Valor],
			'INT1'												[TipoCodigo],
			ISNULL(tmu.mu_shortDesc,'MTS')						[UniMedida],
			ti.item_detail										[DescLarga],
			--CONVERT(DECIMAL(19,0),tit.it_qty * tit.it_price)	[MontoItem],
			tit.it_qty * CONVERT(DECIMAL(19,0),tit.it_price)	[MontoItem],



			tit.it_itemDiscountTotal +
			tit.it_totalDiscountTotal							[DescuentoTotal],
			0 /*tit.it_Discount1*/								[PorcDescto]

			FROM tbItemTransactions					tit		WITH(NOLOCK)
			INNER JOIN tbItem						ti		WITH(NOLOCK)
			ON	ti.comp_id			= tit.comp_id	AND
				ti.item_id			= tit.item_id
			LEFT JOIN tbMetricUnits					tmu		WITH(NOLOCK)
			ON	tmu.comp_id			= ti.comp_id	AND
				tmu.mu_id			= ti.mu_id
			INNER JOIN tbCommercialTransactions		tct		WITH(NOLOCK)
			ON	tct.comp_id			= tit.comp_id	AND
				tct.ct_transaction	= tit.ct_transaction
			INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
			ON	tit2.comp_id		= ti.comp_id	AND
				tit2.item_id		= ti.item_id
			INNER JOIN tbTaxName					ttn		WITH(NOLOCK)
			ON	ttn.tax_id			= tit2.tax_id	AND
				ttn.comp_id			= tit2.comp_id
			WHERE	tit.comp_id			= @comp_id	AND
					tit.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		--OBSERVACIONES
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			tctn.ctn_note1								[Linea1],
			tctn.ctn_note2								[Linea2],
			tctn.ctn_note3								[Linea3]--,
			--tctn.ctn_note4								[Linea4]
			FROM tbCommercialTransactionNotes			tctn	WITH(NOLOCK)
			WHERE	tctn.comp_id		= @comp_id		AND
					tctn.ct_transaction = @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

	END
GO


CREATE PROCEDURE [dbo].[spCommercialTransaction_ElectronicInvoice_GuiaDeDespacho_Chile_GetData]
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT

			SELECT
				@comp_id		= 1,
				@ct_transaction	= 28519
		*/
		-- ---------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		-- ENCABEZADO
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			/*CASE
				WHEN tct.sd_id	= 1 AND tdf.df_isElectronicInvoice		= 'True'	THEN 33	--FC ELECTRONICA ANTES ERA 35 ahhora 33
			ELSE 33
			END*/ 52													[TipoDTE],
			--4500000														[Folio],
			tdf.df_number												[Folio],
			tct.ct_date													[FechaEmision],
			1															[TipoDespacho], /*  0 = Sin Despacho /
																							1 = Despacho por cuenta del Receptor del Doc /
																							2 = Despacho por cuenta del emisor a Instalaciones del Cliente  /
																							3 = Despacho por cuenta del emisor a otras instalaciones (Ejemplo: entrega en Obra).*/
			1															[IndTraslado],  /*	1 = Operación constituye venta.
																							2 = Ventas por efectuar.
																							3 = Consignaciones.
																							4 = Entrega gratuita.
																							5 = Traslados internos.
																							6 = Otros traslados no venta.
																							7 = Guía de devolución.
																						*/


			--EMISOR
			tb.bra_taxNumber											[RUTEmisor],	--TIENE QUE TENER GUION Y DIGITO VERIFICADOR
			tc2.comp_desc												[RznSoc],		--RAZON SOCIAL
			CONVERT(VARCHAR(20),tb.bra_desc)							[bra_desc],		--SUCURSAL
			tdf.df_electronicInvoiceChile_Emisor_Giro					[GiroEmis],
			tdf.stca_id													[Acteco],
			CONVERT(VARCHAR(60),tb.bra_address)							[DirOrigen],
			tdf.df_electronicInvoiceChile_Emisor_Comuna					[CmnaOrigen],
			tdf.df_electronicInvoiceChile_Emisor_Ciudad					[CiudadOrigen],






			--RECEPTOR
			tc.cust_taxNumber											[RUTRecep], --(TIENE QUE TENER EL GUION Y EL DIGITO VERIFICADOR 11111111-1 )
			CONVERT(VARCHAR(100),tc.cust_name)							[RznSocRecep],
			CONVERT(VARCHAR(40),ISNULL(ttca.stca_desc,''))				[GiroRecep],
			CONVERT(VARCHAR(60),tc.cust_address)						[DirRecep],
			ISNULL(tc.cust_city,'')										[CmnaRecep],
			--ISNULL(tsc.city_desc,'')									[CiudadRecep]
			ISNULL(tc.cust_city,'')										[CiudadRecep]


			FROM tbCommercialTransactions								tct	WITH(NOLOCK)
			INNER JOIN tbDocumentsFile									tdf WITH(NOLOCK)
			ON	tdf.df_id				= tct.df_id						AND
				tdf.comp_id				= tct.comp_id
			INNER JOIN tbCustomer										tc	WITH(NOLOCK)
			ON	tc.comp_id				= tct.comp_id					AND
				tc.cust_id				= tct.cust_id
			--LEFT JOIN tbSysCities										tsc	WITH(NOLOCK)
			--ON	tsc.country_id			= tc.country_id					AND
			--	tsc.state_id			= tc.state_id					AND
			--	tsc.city_id				= tc.city_id
			LEFT JOIN tbsysTax_ChileActividad							ttca WITH(NOLOCK)
			ON	ttca.stca_id			= tc.stca_id

			INNER JOIN tbCompany										tc2 WITH(NOLOCK)
			ON	tc2.comp_id				= tct.comp_id
			INNER JOIN tbBranch											tb	WITH(NOLOCK)
			ON	tb.comp_id				= tct.comp_id AND
				tb.bra_id				= tct.bra_id
			INNER JOIN tbsysState										AS ts	WITH(NOLOCK)
			ON	ts.country_id			= tb.country_id					AND
				ts.state_id				= tb.state_id

			LEFT JOIN tbsysTax_ChileActividad							AS ttca2	WITH(NOLOCK)
			ON	ttca2.stca_id			= tdf.stca_id


			WHERE	tct.comp_id			= @comp_id						AND
					tct.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------------------
		--TOTALES
		-- -----------------------------------------------------------------------------------------------------
		--IVA TAX
		DECLARE @decTasaIVA AS DECIMAL(19,0)
		SELECT TOP 1
			 @decTasaIVA			= ttn.tax_percentage
		FROM tbItemTransactions					tit		WITH(NOLOCK)
		INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
		ON	tit2.comp_id			= tit.comp_id AND
			tit2.item_id			= tit.item_id
		INNER JOIN tbTaxName					ttn		WITH(NOLOCK)
		ON	ttn.comp_id				= tit2.comp_id AND
			ttn.tax_id				= tit2.tax_id
		WHERE	tit.comp_id			= @comp_id	AND
				tit.ct_transaction	= @ct_transaction



		SELECT
			CONVERT(DECIMAL(19,0),tct.ct_subtotal)							[Neto],
			@decTasaIVA														[TasaIVA], --ESTO DE DONDE LO SACO A NIVEL GENERAL?
			CONVERT(DECIMAL(19,0),tct.ct_taxes)								[IVA],
			CONVERT(DECIMAL(19,0),tct.ct_subtotal + 0 + tct.ct_taxes - 0)	[Total]
			FROM tbCommercialTransactions				tct	WITH(NOLOCK)
			LEFT JOIN tbDiscount						td
			ON	td.comp_id				= tct.comp_id	AND
				td.disc_id				= tct.disc_id
			WHERE	tct.comp_id			= @comp_id		AND
					tct.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		--ARTICULOS
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			tit.it_order										[NroLinea],
			ti.item_code										[Código],
			ti.item_desc										[NmbItem],
			ti.item_detail										[DscItem],
			CONVERT(DECIMAL(19,0),tit.it_qty)					[QtyItem],
			CONVERT(DECIMAL(19,0),tit.it_price)					[PrcItem],
			'INT1'												[TpoCodigo],
			ISNULL(tmu.mu_shortDesc,'MTS')						[UnmdItem],
			CONVERT(DECIMAL(19,0),tit.it_qty * tit.it_price)	[MontoItem],
			tit.it_transaction_original

			FROM tbItemTransactions					tit		WITH(NOLOCK)
			INNER JOIN tbItem						ti		WITH(NOLOCK)
			ON	ti.comp_id			= tit.comp_id	AND
				ti.item_id			= tit.item_id
			LEFT JOIN tbMetricUnits					tmu		WITH(NOLOCK)
			ON	tmu.comp_id			= ti.comp_id	AND
				tmu.mu_id			= ti.mu_id
			INNER JOIN tbCommercialTransactions		tct		WITH(NOLOCK)
			ON	tct.comp_id			= tit.comp_id	AND
				tct.ct_transaction	= tit.ct_transaction
			INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
			ON	tit2.comp_id		= ti.comp_id	AND
				tit2.item_id		= ti.item_id
			INNER JOIN tbTaxName					ttn		WITH(NOLOCK)
			ON	ttn.tax_id			= tit2.tax_id	AND
				ttn.comp_id			= tit2.comp_id
			WHERE	tit.comp_id			= @comp_id	AND
					tit.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		-- ADICIONAL	(Màximo de 20 lineas, son anotaciones o aclaraciones que se quieran agregar
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			tctn.ctn_note1								[Linea1],
			tctn.ctn_note2								[Linea2],
			tctn.ctn_note3								[Linea3],
			tctn.ctn_note4								[Linea4]
			FROM tbCommercialTransactionNotes			tctn	WITH(NOLOCK)
			WHERE	tctn.comp_id		= @comp_id		AND
					tctn.ct_transaction = @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

	END
GO


CREATE PROCEDURE [dbo].[spCommercialTransaction_ElectronicInvoice_NotaDeCredito_Chile_GetData]
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT

			SELECT
				@comp_id		= 1,
				@ct_transaction	= 28519
		*/
		-- ---------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		-- ENCABEZADO
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			61															[TipoDTE],
			tdf.df_number												[Folio],
			tct.ct_date													[FechaEmision],

			1															[TipoDespacho], --ANTES PUSE 0
			1															[IndTraslado],

			tc.cust_taxNumber											[RUTCliente], --(TIENE QUE TENER EL GUION Y EL DIGITO VERIFICADOR 11111111-1 )
			CONVERT(VARCHAR(100),tc.cust_name)							[RSCliente],
			CONVERT(VARCHAR(40),ISNULL(ttca.stca_desc,''))				[GiroCliente],
			CONVERT(VARCHAR(60),tc.cust_address)						[DirCliente],
			ISNULL(tc.cust_city,'')										[ComCliente],
			--ISNULL(CONVERT(VARCHAR(20),tsc.city_desc),'Ciudad')			[CiuCliente],
			CONVERT(VARCHAR(20),ISNULL(tc.cust_city,''))				[CiuCliente],
			ISNULL(tc.cust_email,'')									[Email],


			ISNULL(tc.cust_contact,'')									[Contacto],

			--EMISOR
			tc2.comp_desc,																--RAZON SOCIAL
			CONVERT(VARCHAR(20),tb.bra_desc)							[bra_desc],		--SUCURSAL
			CONVERT(VARCHAR(60),tb.bra_address)							[bra_address],	--DIRECCION
			tb.bra_taxNumber,											--RUT			--TIENE QUE TENER GUION Y DIGITO VERIFICADOR
			ISNULL(tdf.df_electronicInvoiceChile_Emisor_Giro,'')		[GiroEmisor],
			ISNULL(tdf.df_electronicInvoiceChile_Emisor_Comuna,'')		[ComunaEmisor],
			ISNULL(tdf.df_electronicInvoiceChile_Emisor_Ciudad,'')		[CiudadEmisor],
			tdf.stca_id													[ActEcoEmisor]


			FROM tbCommercialTransactions								tct	WITH(NOLOCK)
			INNER JOIN tbDocumentsFile									tdf WITH(NOLOCK)
			ON	tdf.df_id				= tct.df_id						AND
				tdf.comp_id				= tct.comp_id
			INNER JOIN tbCustomer										tc	WITH(NOLOCK)
			ON	tc.comp_id				= tct.comp_id					AND
				tc.cust_id				= tct.cust_id
			--LEFT JOIN tbSysCities										tsc	WITH(NOLOCK)
			--ON	tsc.country_id			= tc.country_id					AND
			--	tsc.state_id			= tc.state_id					AND
			--	tsc.city_id				= tc.city_id
			LEFT JOIN tbsysTax_ChileActividad							ttca WITH(NOLOCK)
			ON	ttca.stca_id			= tc.stca_id

			INNER JOIN tbCompany										tc2 WITH(NOLOCK)
			ON	tc2.comp_id				= tct.comp_id
			INNER JOIN tbBranch											tb	WITH(NOLOCK)
			ON	tb.comp_id				= tct.comp_id AND
				tb.bra_id				= tct.bra_id

			LEFT JOIN tbsysTax_ChileActividad							AS ttca2 WITH(NOLOCK)
			ON	ttca2.stca_id			= tdf.stca_id

			WHERE	tct.comp_id			= @comp_id						AND
					tct.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------------------
		--TOTALES
		-- -----------------------------------------------------------------------------------------------------
		--IVA TAX
		DECLARE @decTasaIVA AS DECIMAL(19,0)
		SELECT TOP 1
			 @decTasaIVA			= ttn.tax_percentage
		FROM tbItemTransactions					tit		WITH(NOLOCK)
		INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
		ON	tit2.comp_id			= tit.comp_id AND
			tit2.item_id			= tit.item_id
		INNER JOIN tbTaxName					ttn		WITH(NOLOCK)
		ON	ttn.comp_id				= tit2.comp_id AND
			ttn.tax_id				= tit2.tax_id
		WHERE	tit.comp_id			= @comp_id	AND
				tit.ct_transaction	= @ct_transaction



		SELECT
			CONVERT(DECIMAL(19,0),ISNULL(td.disc_coef,0))					[PorcDesctoTot],
			CONVERT(DECIMAL(19,0),ISNULL(tct.ct_discount,0))				[ValorDesctoTot],
			0																[PorcRecgoTot],
			0																[ValorRecgoTot],
			--tct.ct_Atotal						[Neto],
			CONVERT(DECIMAL(19,0),tct.ct_subtotal - tct.ct_discount)		[Neto],
			0																[Exento],
			@decTasaIVA														[TasaIVA], --ESTO DE DONDE LO SACO A NIVEL GENERAL?
			CONVERT(DECIMAL(19,0),tct.ct_taxes)								[IVA],
			CONVERT(DECIMAL(19,0),tct.ct_total)	[Total],
			--tct.ct_ATotal						[Total],
			0																[Retención],
			0																[ImpuestoEspecifico]
			FROM tbCommercialTransactions				tct	WITH(NOLOCK)
			LEFT JOIN tbDiscount						td	WITH(NOLOCK)
			ON	td.comp_id				= tct.comp_id	AND
				td.disc_id				= tct.disc_id
			WHERE	tct.comp_id			= @comp_id		AND
					tct.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		--ARTICULOS
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			tit.it_order										[NroLinea],
			ti.item_code										[Código],
			ti.item_desc										[Descripcion],
			CONVERT(DECIMAL(19,0),tit.it_qty)					[Cantidad],
			CONVERT(DECIMAL(19,0),tit.it_price)					[Precio],
			0													[PorcDescto],
			CONVERT(DECIMAL(19,0),tit.it_totalDiscountTotal)	[ValorDescto],
			0													[PorcRecgo],
			0													[ValorRecgo],
			0													[ValorExento],
			0													[Valor],
			'INT1'												[TipoCodigo],
			ISNULL(tmu.mu_shortDesc,'MTS')						[UniMedida],
			ti.item_detail										[DescLarga],
			--CONVERT(DECIMAL(19,0),tit.it_qty * tit.it_price)	[MontoItem],
			tit.it_qty * CONVERT(DECIMAL(19,0),tit.it_price)	[MontoItem],

			tit.it_itemDiscountTotal +
			tit.it_totalDiscountTotal							[DescuentoTotal],
			0 /*tit.it_Discount1*/									[PorcDescto],
			tit.it_transaction_original

			FROM tbItemTransactions					tit		WITH(NOLOCK)
			INNER JOIN tbItem						ti		WITH(NOLOCK)
			ON	ti.comp_id			= tit.comp_id	AND
				ti.item_id			= tit.item_id
			LEFT JOIN tbMetricUnits					tmu		WITH(NOLOCK)
			ON	tmu.comp_id			= ti.comp_id	AND
				tmu.mu_id			= ti.mu_id
			INNER JOIN tbCommercialTransactions		tct		WITH(NOLOCK)
			ON	tct.comp_id			= tit.comp_id	AND
				tct.ct_transaction	= tit.ct_transaction
			INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
			ON	tit2.comp_id		= ti.comp_id	AND
				tit2.item_id		= ti.item_id
			INNER JOIN tbTaxName					ttn		WITH(NOLOCK)
			ON	ttn.tax_id			= tit2.tax_id	AND
				ttn.comp_id			= tit2.comp_id
			WHERE	tit.comp_id			= @comp_id	AND
					tit.ct_transaction	= @ct_transaction



		-- -----------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		-- REFERENCIAS
		-- -----------------------------------------------------------------------------------------------------
		DECLARE
			@intCodRef		INT,
			@strCodeRefText	NVARCHAR(150),
			@intTOP			INT

		SET @intTOP = 40

		SELECT
			@intCodRef		= ISNULL(tdf.df_electronicInvoiceChile_codReferencia,0),
			@strCodeRefText = ISNULL(tdf.df_electronicInvoiceChile_codReferencia_Texto,'')
			FROM tbCommercialTransactions			AS tct	WITH(NOLOCK)
				INNER JOIN tbDocumentsFile			AS tdf	WITH(NOLOCK)
					ON	tdf.comp_id = tct.comp_id	AND
						tdf.df_id	= tct.df_id
			WHERE	tct.comp_id			= @comp_id	AND
					tct.ct_transaction	= @ct_transaction

		IF (@intCodRef = 1) OR (@intCodRef = 2)
			BEGIN
				SET @intTOP = 1
			END

		SELECT TOP (@intTOP)
			tit.it_order										[NroLinea],
			CASE tct2.ct_kindOf
				WHEN 'Fc.Cl'	THEN 33
				WHEN 'Bo.Cl'	THEN 39
			ELSE
				33
			END													[TipoDTE],
			tct2.ct_docNumber									[FolioRef],
			tct2.ct_date										[FchRef],
			@intCodRef											[CodRef],
			@strCodeRefText										[RazonRef]

			FROM tbItemTransactions					tit		WITH(NOLOCK)
			INNER JOIN tbCommercialTransactions		tct		WITH(NOLOCK)
			ON	tct.comp_id			= tit.comp_id	AND
				tct.ct_transaction	= tit.ct_transaction
			LEFT JOIN tbItemTransactions			AS tit2	WITH(NOLOCK)
			ON	tit2.comp_id		= tit.comp_id	AND
				tit2.it_transaction	= tit.it_transaction_original --ARREGLAR ESTO QUE ESTA MAL ESTE JOIN
			LEFT JOIN tbCommercialTransactions		AS tct2	WITH(NOLOCK)
			ON	tct2.comp_id		= tit2.comp_id	AND
				tct2.ct_transaction	= tit2.ct_transaction
			WHERE	tit.comp_id			= @comp_id	AND
					tit.ct_transaction	= @ct_transaction




		-- -----------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		--OBSERVACIONES
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			tctn.ctn_note1								[Linea1],
			tctn.ctn_note2								[Linea2],
			tctn.ctn_note3								[Linea3]--,
			--tctn.ctn_note4								[Linea4]
			FROM tbCommercialTransactionNotes			tctn	WITH(NOLOCK)
			WHERE	tctn.comp_id		= @comp_id		AND
					tctn.ct_transaction = @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

	END
GO

CREATE PROCEDURE [dbo].[spCommercialTransaction_ElectronicInvoice_NotaDeDebito_Chile_GetData]
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT

			SELECT
				@comp_id		= 1,
				@ct_transaction	= 3111
		*/
		-- ---------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		-- ENCABEZADO
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			56															[TipoDTE], --ND ELECTRONICA
			--4500000														[Folio],
			tdf.df_number												[Folio],
			CONVERT(VARCHAR(30),CONVERT(DATE,tct.ct_date,23))			[FechaEmision],
			--tct.ct_date													[FechaEmision],
			1															[TipoDespacho], --ANTES PUSE 0
			1															[IndTraslado],

			tc.cust_taxNumber											[RUTCliente], --(TIENE QUE TENER EL GUION Y EL DIGITO VERIFICADOR 11111111-1 )
			CONVERT(VARCHAR(100),tc.cust_name)							[RSCliente],
			CONVERT(VARCHAR(40),ttca.stca_desc)							[GiroCliente],
			CONVERT(VARCHAR(60),tc.cust_address)						[DirCliente],
			ISNULL(tc.cust_city,'')										[ComCliente],
			--ISNULL(CONVERT(VARCHAR(20),tsc.city_desc),'Ciudad')			[CiuCliente],
			CONVERT(VARCHAR(20),ISNULL(tc.cust_city,''))				[CiuCliente],
			ISNULL(tc.cust_email,'')									[Email],


			ISNULL(tc.cust_contact,'')									[Contacto],

			--EMISOR
			tc2.comp_desc,																--RAZON SOCIAL
			CONVERT(VARCHAR(20),tb.bra_desc)							[bra_desc],		--SUCURSAL
			CONVERT(VARCHAR(60),tb.bra_address)							[bra_address],	--DIRECCION
			tb.bra_taxNumber,											--RUT			--TIENE QUE TENER GUION Y DIGITO VERIFICADOR
			tdf.df_electronicInvoiceChile_Emisor_Giro					[GiroEmisor],
			tdf.df_electronicInvoiceChile_Emisor_Comuna					[ComunaEmisor],
			tdf.df_electronicInvoiceChile_Emisor_Ciudad					[CiudadEmisor],
			tdf.stca_id													[ActEcoEmisor]


			FROM tbCommercialTransactions								tct	WITH(NOLOCK)
			INNER JOIN tbDocumentsFile									tdf WITH(NOLOCK)
			ON	tdf.df_id				= tct.df_id						AND
				tdf.comp_id				= tct.comp_id
			INNER JOIN tbCustomer										tc	WITH(NOLOCK)
			ON	tc.comp_id				= tct.comp_id					AND
				tc.cust_id				= tct.cust_id
			--LEFT JOIN tbSysCities										tsc	WITH(NOLOCK)
			--ON	tsc.country_id			= tc.country_id					AND
			--	tsc.state_id			= tc.state_id					AND
			--	tsc.city_id				= tc.city_id
			LEFT JOIN tbsysTax_ChileActividad							ttca WITH(NOLOCK)
			ON	ttca.stca_id			= tc.stca_id




			INNER JOIN tbCompany										tc2 WITH(NOLOCK)
			ON	tc2.comp_id				= tct.comp_id
			INNER JOIN tbBranch											tb	WITH(NOLOCK)
			ON	tb.comp_id				= tct.comp_id AND
				tb.bra_id				= tct.bra_id


			LEFT JOIN tbsysTax_ChileActividad							AS ttca2 WITH(NOLOCK)
			ON	ttca2.stca_id			= tdf.stca_id



			WHERE	tct.comp_id			= @comp_id						AND
					tct.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------------------
		--TOTALES
		-- -----------------------------------------------------------------------------------------------------
		--IVA TAX
		DECLARE @decTasaIVA AS DECIMAL(19,0)
		SELECT TOP 1
			 @decTasaIVA			= ttn.tax_percentage
		FROM tbItemTransactions					tit		WITH(NOLOCK)
		INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
		ON	tit2.comp_id			= tit.comp_id AND
			tit2.item_id			= tit.item_id
		INNER JOIN tbTaxName					ttn		WITH(NOLOCK)
		ON	ttn.comp_id				= tit2.comp_id AND
			ttn.tax_id				= tit2.tax_id
		WHERE	tit.comp_id			= @comp_id	AND
				tit.ct_transaction	= @ct_transaction



		SELECT
			CONVERT(DECIMAL(19,0),ISNULL(td.disc_coef,0))					[PorcDesctoTot],
			CONVERT(DECIMAL(19,0),ISNULL(tct.ct_discount,0))				[ValorDesctoTot],
			0																[PorcRecgoTot],
			0																[ValorRecgoTot],
			--tct.ct_Atotal						[Neto],
			CONVERT(DECIMAL(19,0),tct.ct_subtotal - tct.ct_discount)		[Neto],
			0																[Exento],
			@decTasaIVA														[TasaIVA], --ESTO DE DONDE LO SACO A NIVEL GENERAL?
			CONVERT(DECIMAL(19,0),tct.ct_taxes)								[IVA],
			CONVERT(DECIMAL(19,0),tct.ct_total)								[Total],
			--tct.ct_ATotal						[Total],
			0																[Retención],
			0																[ImpuestoEspecifico]
			FROM tbCommercialTransactions				tct	WITH(NOLOCK)
			LEFT JOIN tbDiscount						td	WITH(NOLOCK)
			ON	td.comp_id				= tct.comp_id	AND
				td.disc_id				= tct.disc_id
			WHERE	tct.comp_id			= @comp_id		AND
					tct.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		--ARTICULOS
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			tit.it_order										[NroLinea],
			ti.item_code										[Código],
			ti.item_desc										[Descripcion],
			CONVERT(DECIMAL(19,0),tit.it_qty)					[Cantidad],
			CONVERT(DECIMAL(19,0),tit.it_price)					[Precio],
			0													[PorcDescto],
			CONVERT(DECIMAL(19,0),tit.it_totalDiscountTotal)	[ValorDescto],
			0													[PorcRecgo],
			0													[ValorRecgo],
			0													[ValorExento],
			0													[Valor],
			'INT1'												[TipoCodigo],
			ISNULL(tmu.mu_shortDesc,'MTS')						[UniMedida],
			ti.item_detail										[DescLarga],
			--CONVERT(DECIMAL(19,0),tit.it_qty * tit.it_price)	[MontoItem],
			tit.it_qty * CONVERT(DECIMAL(19,0),tit.it_price)	[MontoItem],



			tit.it_itemDiscountTotal +
			tit.it_totalDiscountTotal							[DescuentoTotal],
			0 /*tit.it_Discount1*/								[PorcDescto]

			FROM tbItemTransactions					tit		WITH(NOLOCK)
			INNER JOIN tbItem						ti		WITH(NOLOCK)
			ON	ti.comp_id			= tit.comp_id	AND
				ti.item_id			= tit.item_id
			LEFT JOIN tbMetricUnits					tmu		WITH(NOLOCK)
			ON	tmu.comp_id			= ti.comp_id	AND
				tmu.mu_id			= ti.mu_id
			INNER JOIN tbCommercialTransactions		tct		WITH(NOLOCK)
			ON	tct.comp_id			= tit.comp_id	AND
				tct.ct_transaction	= tit.ct_transaction
			INNER JOIN tbItemTaxes					tit2	WITH(NOLOCK)
			ON	tit2.comp_id		= ti.comp_id	AND
				tit2.item_id		= ti.item_id
			INNER JOIN tbTaxName					ttn		WITH(NOLOCK)
			ON	ttn.tax_id			= tit2.tax_id	AND
				ttn.comp_id			= tit2.comp_id
			WHERE	tit.comp_id			= @comp_id	AND
					tit.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		--OBSERVACIONES
		-- -----------------------------------------------------------------------------------------------------
		SELECT
			tctn.ctn_note1								[Linea1],
			tctn.ctn_note2								[Linea2],
			tctn.ctn_note3								[Linea3]--,
			--tctn.ctn_note4								[Linea4]
			FROM tbCommercialTransactionNotes			tctn	WITH(NOLOCK)
			WHERE	tctn.comp_id		= @comp_id		AND
					tctn.ct_transaction = @ct_transaction
		-- -----------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		-- REFERENCIAS - PREGUNTAR A MOS COMO ES ESTA MOVIDA
		-- -----------------------------------------------------------------------------------------------------
			DECLARE
				@intCodRef		INT,
				@strCodeRefText	NVARCHAR(150),
				@intTOP			INT

		SET @intTOP = 40


		SELECT
			@intCodRef		= ISNULL(tdf.df_electronicInvoiceChile_codReferencia,0),
			@strCodeRefText = ISNULL(tdf.df_electronicInvoiceChile_codReferencia_Texto,'')
			FROM tbCommercialTransactions			AS tct	WITH(NOLOCK)
				INNER JOIN tbDocumentsFile			AS tdf	WITH(NOLOCK)
					ON	tdf.comp_id = tct.comp_id	AND
						tdf.df_id	= tct.df_id
			WHERE	tct.comp_id			= @comp_id	AND
					tct.ct_transaction	= @ct_transaction

			IF (@intCodRef = 1) OR (@intCodRef = 2)
			BEGIN
				SET @intTOP = 1
			END

			SELECT TOP (@intTOP)
				tit2.it_order											[NroLinRef],
				CASE tct.sd_id
					WHEN 1 THEN	CASE tct.ct_kindOf
									WHEN 'Fc.cl' THEN	33
									WHEN 'Bo.cl' THEN	39
								ELSE					-1
								END
					WHEN 2	THEN						52
					WHEN 3	THEN						61
				ELSE									-1
				END														[TpoDocRef],
				tct.ct_docNumber										[FolioRef],
				CONVERT(VARCHAR(30),CONVERT(DATE,tct.ct_date,23))		[FchRef],
				@intCodRef												[CodRef],
				@strCodeRefText											[RazonRef]
				FROM tbItemTransactions					tit		WITH(NOLOCK)
				INNER JOIN tbItemTransactions			AS tit2	WITH(NOLOCK)
				ON	tit2.comp_id		= tit.comp_id	AND
					tit2.it_transaction	= tit.it_transaction_original
				INNER JOIN tbCommercialTransactions		AS tct	WITH(NOLOCK)
				ON	tct.comp_id			= tit2.comp_id	AND
					tct.ct_transaction	= tit2.ct_transaction
				WHERE	tit.comp_id			= @comp_id	AND
						tit.ct_transaction	= @ct_transaction




		-- -----------------------------------------------------------------------------------------------------

	END
GO






