--
  CREATE PROCEDURE [dbo].[spCommercialTransaction_Factura]
  (
  			@comp_id			Int,
  			@lang_id			Int,
  			@page_id			Int,
  			@ct_transaction		Int
  )
  as
  set nocount on
  --set dateformat 'ymd'
  /*
  declare 	@comp_id			int,
  			@lang_id			Int,
  			@page_id			Int,
  			@ct_transaction		Int
  select		@comp_id			= 1,
  			@lang_id			= 2,
  			@page_id			=10044,
  			@ct_transaction		= 2109
  */
  /*:::Datos de la Sucursal:::*/
  Select	tb.bra_MainDesc,
  		tb.bra_desc,
  		tb.bra_address,
  		tb.bra_address1,
  		tb.bra_phone,
  		tb.bra_taxNumber,
  		tct.ct_kindOf,
  		tdf.df_fromDate,
  		isnull(tb.bra_taxNumber2,'')[bra_taxNumber2],
  		isnull(tb.bra_taxNumber3,'') [bra_taxNumber3],
  		tct.ct_subtotal,
  		tct.ct_taxes,
  		tct.ct_total

  From tbCommercialTransactions tct	WITH (NOLOCK)
  	Inner Join tbBranch tb	WITH (NOLOCK)
  	On  tb.bra_id  = tct.bra_id
  	AND tb.comp_id = tct.comp_id
  	Inner Join tbDocumentsFile tdf	WITH (NOLOCK)
  	On  tdf.comp_id	= tct.comp_id
  	And tdf.bra_id	= tct.bra_id
  	And tdf.df_id	= tct.df_id

  Where tct.comp_id		 = @comp_id
  And	  tct.ct_transaction = @ct_transaction


  /*:::::Datos del Cliente:::::*/
  Select tc.cust_name,
  	   tc.cust_address,
  	   tc.cust_city,
  	   tc.cust_zip,
  	   tc.cust_phone1,
  	   tc.cust_fax,
  	   tc2.country_desc,
  	   ts.state_desc,
  	   tc.cust_taxNumber
  	   --Condición de venta

  From tbCommercialTransactions tct	WITH (NOLOCK)
  		Inner Join tbCustomer tc	WITH (NOLOCK)
  		On tc.comp_id  = tct.comp_id
  		and tc.cust_id = tct.cust_id
  		and tc.cust_id = tct.cust_id
  		Inner Join tbsysCountry tc2	WITH (NOLOCK)
  		On tc2.country_id = tc.country_id
  		Inner Join tbsysState ts	WITH (NOLOCK)
  		On  ts.country_id = tc.country_id
  		and ts.state_id   = tc.state_id

  Where tct.comp_id		 = @comp_id
  And   tct.ct_transaction = @ct_transaction


  /*:::Otros:::*/
  Select tst.st_desc,
  	   isnull(tctn.ctn_note1,'') [ctn_note1],
  	   isnull(tctn.ctn_note2,'') [ctn_note2],
  	   isnull(tctn.ctn_note3,'') [ctn_note3]
  	   --campo en ct pk que cuando sea <> null pongo remito

  From tbCommercialTransactions tct	WITH (NOLOCK)
  		Inner Join tbSalesTerms tst	WITH (NOLOCK)
  		On  tst.comp_id = tct.comp_id
  		And tst.bra_id = tct.bra_id
  		And tst.st_id  = tct.st_id

  left Join tbCommercialTransactionNotes tctn	WITH (NOLOCK)
  On tctn.comp_id			= tct.comp_id
  And tctn.bra_id			= tct.bra_id
  And tctn.ct_transaction = tct.ct_transaction

  Where tct.comp_id		 = @comp_id
  And   tct.ct_transaction = @ct_transaction


  /*:::Detalles::: */
  Select tit.it_qty,
  	   ti.item_desc,
  	   ti.item_detail,
  	   tit.it_price,
  	   titid.impData_Custom_local		[Despacho],
  	   tit.it_guarantee,
  	   tit.it_qty * tit.it_price		[Total],
  	   isnull(ttn.tax_percentage,0)		[tax_percentage],
  	   isnull(tis.is_serial,'')			[is_serial]

  From	tbCommercialTransactions tct	WITH (NOLOCK)

  		Inner Join tbItemTransactions tit	WITH (NOLOCK)
  		On  tit.comp_id        = tct.comp_id
  		And tit.bra_id		   = tct.bra_id
  		and tit.ct_transaction = tct.ct_transaction

  		Inner Join tbItem ti	WITH (NOLOCK)
  		On  ti.comp_id = tit.comp_id
  		And ti.item_id = tit.item_id

  		left Join tbTaxMovements ttm	WITH (NOLOCK)
  		On ttm.comp_id = tct.comp_id
  		And ttm.bra_id = tct.bra_id
  		And ttm.ct_transaction = tct.ct_transaction
  		And ttm.it_transaction = tit.it_transaction

  		left Join tbTaxName ttn	WITH (NOLOCK)
  		On ttn.comp_id = tct.comp_id
  		And ttn.tax_id = ttm.tax_id

  		left Join tbItemTransactionImportData titid	WITH (NOLOCK)
  		On titid.comp_id = tit.comp_id
  		And titid.ct_transaction = tit.ct_transaction
  		And titid.it_transaction = tit.it_transaction

  		left Join tbItemSerials tis	WITH (NOLOCK)
  		On  tis.comp_id			= tct.comp_id
  		And tis.ct_transaction	= tct.ct_transaction
  		And tis.it_transaction	= tit.it_transaction
  		And tis.item_id			= tit.item_id

  Where tct.comp_id		 = @comp_id
  And   tct.ct_transaction = @ct_transaction


  /*delivery*/

  /*:::recuperamos el valor en letras:::*/

DECLARE @ct_total	DECIMAL(19,5)

  Select	@ct_total			=	 tct.ct_total
  From	tbCommercialTransactions tct	WITH (NOLOCK)

  WHERE	tct.comp_id			=	@comp_id
  AND		tct.ct_transaction	=	@ct_transaction

  DECLARE @text VARCHAR(1000)
  EXEC spSysTexts_convertNumberToLetters @lang_id, @ct_total, @letters = @text output

  Select  td.dl_name,
  		td.dl_address,
  		td.dl_city,
  		td.dl_zip,
  		isnull(td.dl_taxNumber,'') [dl_taxNumber],
  		@text [Letter],
  		convert(varchar,tc.curr_desc) + ' :'   [curr_desc],
  		isnull(tct.ct_transaction_PackingList,'') [ct_transaction_PackingList],
  		tct.ct_CAI
  		--isnull(tis.is_serial,'')[is_serial]

  From tbCommercialTransactions tct	WITH (NOLOCK)

  		Inner join tbDelivery td	WITH (NOLOCK)
  		On  td.comp_id = tct.comp_id
  		AND td.dl_id   = tct.dl_id

  		Inner Join tbsysCurrency tc	WITH (NOLOCK)
  		On tc.curr_id = tct.curr_id_transaction
  		/*inner JOIN tbItemTransactions tit
  		On TIT.comp_id = TCT.comp_id
  		And TIT.ct_transaction = TCT.ct_transaction
  		left Join tbItemSerials tis
  		On  tis.comp_id			= tct.comp_id
  		And tis.ct_transaction	= tct.ct_transaction
  		And tis.it_transaction	= tit.it_transaction
  		And tis.item_id			= tit.item_id*/

  Where	tct.comp_id			= @comp_id
  And		tct.ct_transaction	= @ct_transaction
  exec [spReports_getData]@comp_id, @lang_id,	@page_id


  /*::::::Para el subreporte::::::*/

  Select
	TCT.ct_total,
    tct.ct_subtotal,
    tct.ct_discount,
    ttm.tm_total,
    ttm.percentaje  [tax_percentage],
    ttm2.percentaje [tax_percentage2],
    ttn.tax_desc + ': ' [tax_desc]

  From tbCommercialTransactions tct	WITH (NOLOCK)

  inner  Join tbTaxMovements ttm	WITH (NOLOCK)
  On  ttm.comp_id = tct.comp_id
  And ttm.ct_transaction = tct.ct_transaction

  left Outer Join vwsysTaxClassIVA_Taxes vtcit	WITH (NOLOCK)
  On vtcit.tax_class = ttm.tax_id

  inner  Join tbTaxMovements ttm2	WITH (NOLOCK)
  On  ttm2.comp_id = tct.comp_id
  And ttm2.ct_transaction = tct.ct_transaction

  inner Join vwsysTaxClassIVA_Taxes vtcit2	WITH (NOLOCK)
  On vtcit2.tax_class = ttm2.tax_id

  left Join tbTaxName ttn	WITH (NOLOCK)
  On ttn.comp_id = tct.comp_id
  And ttn.tax_id = ttm.tax_id
  --
  --left Join tbTaxName ttn2
  --On ttn2.comp_id = tct.comp_id
  --And ttn2.tax_id = ttm2.tax_id

  Where tct.comp_id		 = @comp_id
  And	  tct.ct_transaction = @ct_transaction
  --Select ttm.tm_total From tbCommercialTransactions tct
  --
  --inner  Join tbTaxMovements ttm
  --On  ttm.comp_id = tct.comp_id
  --And ttm.ct_transaction = tct.ct_transaction
  --
  --left Outer Join vwsysTaxClassIVA_Taxes vtcit
  --On vtcit.tax_class = ttm.tax_id
  --Where tct.comp_id		 = @comp_id
  --And	  tct.ct_transaction = @ct_transaction
  ----
GO





CREATE PROCEDURE [dbo].[spCommercialTransaction_getComboForProcess]
(
	@comp_id	INT,
	@lang_id	INT
)
AS SET NOCOUNT ON


-- -----------------------------------------------
-- Testing
-- -----------------------------------------------
/*
DECLARE
	@comp_id	INT,
	@bra_id		INT,
	@lang_id	INT,
	@prof_id	INT,
	@user_id	INT
*/
-- -----------------------------------------------




SELECT
	TOP 100
	dbo.fnGetCommercialTransactionDescription(tct.comp_id,2,tct.ct_transaction) [Desc],
	tct.ct_transaction [Id]
FROM tbCommercialTransactions tct

WHERE tct.sd_id IN (101,102)
AND NOT tct.supp_id IS NULL

ORDER BY [Id] DESC
GO







CREATE PROCEDURE [dbo].[spCommercialTransaction_getComboFromCreditNotes]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@item_id		INT,
	@supp_id		INT
)
AS


BEGIN


	SET NOCOUNT ON



	/*
	DECLARE @comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@item_id	INT,
			@supp_id	INT
	SELECT	@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@item_id	=316,
			@supp_id	=12
	*/



	SELECT	convert(varchar,tit.it_transaction)
			--+ '-'
			--+ convert(varchar,convert(decimal(18,2),isnull(tit.it_qty,0)-isnull(tit.it_qty_rma,0)))
			[id],

			dbo.fnGetCommercialTransactionDescription(tit.comp_id, @lang_id,tit.ct_transaction)
			+ ' - '
			+ REPLACE( ti.item_desc,'#',' ')
			+ ' - Qty # '
			+ convert(varchar,convert(decimal(18,2),isnull(tit.it_qty,0)-isnull(tit.it_qty_rma,0)))
			[desc]


	FROM	tbItemTransactions											tit

			INNER JOIN tbCommercialTransactions							tct
			ON	tct.comp_id				= tit.comp_id
			AND tct.bra_id				= tit.bra_id
			AND tct.ct_transaction		= tit.ct_transaction

			INNER JOIN vwCommercialTransactions_forPurchaseCreditNotes	vctfp
			ON	vctfp.comp_id			= tit.comp_id
			AND vctfp.bra_id			= tit.bra_id
			AND vctfp.ct_transaction	= tit.ct_transaction

			INNER JOIN tbItem											ti
			ON	ti.comp_id				= tit.comp_id
			AND ti.item_id				= tit.item_id


	WHERE	tit.comp_id			= @comp_id
	AND		tit.bra_id			= @bra_id
	AND		tit.item_id			= @item_id
	AND		vctfp.sd_isCredit	= 'true'
	AND		tct.supp_id			= @supp_id --is NOT NULL
	AND		(tit.it_qty_rma is null or tit.it_qty_rma < tit.it_qty )
	AND		tit.it_isRMASupplierCreditNote = 'True'



END
GO






CREATE PROCEDURE [dbo].[spCommercialTransaction_getDataForSerialOrCustom]
(
	@comp_id		as INT,
	@ct_transaction	as INT,
	@lang_id		AS INT,
	@option			as BIT
)
AS

BEGIN



	SET NOCOUNT ON



	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
			@comp_id		INT,
			@ct_transaction	INT,
			@option			BIT,
			@lang_id        int
		SELECT
			@comp_id		= 1,
			@ct_transaction	= 1303557,
			@option			= 'True',
			@lang_id        = 2
*/
	-- -----------------------------------------------------------------------



	IF @option = 'True'  -- Despachos

			SELECT
				ti.item_code,
				ti.item_desc,
				dbo.fnGetCommercialTransactionDescription(tct.comp_id,2,tct.ct_transaction)			[Comprobante],
				CASE
					WHEN tct.sd_id > 100 THEN	isnull(idC.impData_Custom_local, '')
					ELSE						isnull(idV.impData_Custom_local, '') + IsNull(titid.impData_Custom_local,'')
				END																					[impData_Custom_local],
				CASE
					WHEN tct.sd_id > 100 THEN	isnull(idC.impData_Number_local, '')
					ELSE						isnull(idV.impData_Number_local, '') + ISNULL(titid.impData_Number_local,'')
				END																					[impData_Number_local],
				CASE
					when tct.sd_id > 100 THEN	isnull(idC.impData_Origin, '')
					ELSE 						isnull(idV.impData_Origin, '')
				END																					[impData_Origin],
				CASE
					when tct.sd_id > 100 THEN	isnull(idC.impData_From, '')
					ELSE						isnull(idV.impData_From, '')
				END																					[impData_From],
				CASE
					when tct.sd_id > 100 THEN	isnull(idC.impData_Stamp, '')
					ELSE						isnull(idV.impData_Stamp, '')
				END																					[impData_Stamp],
				tct.ct_CAI,
				tct.ct_CAIDate



			FROM tbCommercialTransactions tct

				LEFT JOIN tbItemTransactions tit
					ON		tit.comp_id			= tct.comp_id
						--AND tit.bra_id			= tct.bra_id
						AND tit.ct_transaction	= tct.ct_transaction

				LEFT JOIN tbItem ti
					ON		ti.comp_id = tit.comp_id
						AND ti.item_id = tit.item_id


				LEFT JOIN tbItemTransactionImportData titid
					ON		titid.comp_id			= tit.comp_id
						AND titid.bra_id			= tit.bra_id
						AND titid.ct_transaction	= tit.ct_transaction
						AND titid.it_transaction	= tit.it_transaction

				LEFT JOIN tbImportData idC
					ON		idC.comp_id			= tct.comp_id
						AND idC.ct_transaction	= tct.ct_transaction


				LEFT JOIN tbImportData idV
					ON		idV.comp_id			= titid.comp_id
						AND idV.ct_transaction	= titid.ct_transaction


			WHERE	tct.comp_id			= @comp_id
			and		tct.ct_transaction	= @ct_transaction



	ELSE -- Numeros de Serie

			SELECT
					ti.item_code,
					ti.item_desc,
					dbo.fnGetCommercialTransactionDescription(tct.comp_id,@lang_id,tct.ct_transaction)			[Comprobante],
					isnull(tis.is_serial,'')
																				[is_serial]
				FROM tbCommercialTransactions tct
				LEFT JOIN tbItemTransactions tit
					ON		tit.comp_id			= tct.comp_id
						AND tit.ct_transaction	= tct.ct_transaction

				LEFT JOIN tbItem ti
					ON		ti.comp_id = tit.comp_id
						AND ti.item_id = tit.item_id

				LEFT JOIN tbItemTransactionSerials tits
					ON		tits.comp_id		= tit.comp_id
						AND tits.bra_id			= tit.bra_id
						AND tits.ct_transaction = tit.ct_transaction
						AND tits.it_transaction = tit.it_transaction

				LEFT JOIN tbItemSerials tis
					ON	tis.comp_id		= tits.comp_id
					AND tis.is_id		= tits.is_id

				WHERE	tct.comp_id			= @comp_id
				and		tct.ct_transaction	= @ct_transaction


END
GO






CREATE PROCEDURE [dbo].[spCommercialTransaction_getDataItemTransactions]
(
	@comp_id			as INT,
	@lang_id			as INT,
	@ct_transaction		as INT
)

AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
				@comp_id		as INT,
				@lang_id		as INT,
				@ct_transaction	as INT


		SELECT
				@comp_id		= 1,
				@ct_transaction	= 8983,
				@lang_id        = 2

*/
	-- -----------------------------------------------------------------------


	select  ''												[ ],
			ITEM.item_code									[item_code],
			ITEM.item_desc									[item_desc],
			isnull(it.it_loanNumberOfPays,0)				[it_loanNumberOfPays],
			isnull(tov_sdlmt.optval_desc,'')				[sdlmt],
			isnull(tov_sreas.optval_desc,'')				[sreas],
			ts.stor_desc									[stor_desc],
			IT.it_deliveryDate								[it_deliveryDate],
			isnull(it.it_isBlocked4Delivery,'False')		[it_isBlocked4Delivery],
			isnull(it.it_isCompensed,'False')				[it_isCompensed],
			it.it_priceOfCost								[it_priceOfCost],
			it.it_priceBOfCost								[it_priceBOfCost],
			it.it_transaction								[ID]


	FROM 	dbo.tbItemTransactions						IT			 WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions				tct			 WITH (NOLOCK)
		ON	tct.comp_id			=	IT.comp_id
		AND tct.bra_id			=	IT.bra_id
		AND tct.ct_transaction	=	IT.ct_transaction

		left join dbo.tbItem							ITEM		 WITH (NOLOCK)
		on  item.comp_id		=	IT.comp_id
		AND item.item_id		=	IT.item_id

		left join tbsysOptionsValues					tov_sdlmt	 WITH (NOLOCK)
		on  tov_sdlmt.optval_class		= 520
		and tov_sdlmt.lang_id			= @lang_id
		and tov_sdlmt.optval_id			= it.sdlmt_id

		left join tbsysOptionsValues					tov_sreas	 WITH (NOLOCK)
		on  tov_sreas.optval_class		= 370
		and tov_sreas.lang_id			= @lang_id
		and tov_sreas.optval_id			= it.sreas_id

		LEFT JOIN tbStorage								ts			WITH (NOLOCK)
		ON  ts.comp_id = IT.comp_id		AND
			ts.stor_id = IT.stor_id


	where	IT.comp_id			= @comp_id
	and		IT.ct_transaction	= @ct_transaction






END

GO






CREATE PROCEDURE [dbo].[spCommercialTransaction_getDataItemTransactionsDelivery]
(
	@comp_id			as INT,
	@lang_id			as INT,
	@ct_transaction		as INT
)

AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
				@comp_id		as INT,
				@lang_id		as INT,
				@ct_transaction	as INT


		SELECT
				@comp_id		= 1,
				@ct_transaction	= 8983,
				@lang_id        = 2

*/
	-- -----------------------------------------------------------------------


	select  ''											[ ],
			ITEM.item_code								[item_code],
			ITEM.item_desc								[item_desc],
			ts.stor_desc								[stor_desc],
			tit.it_deliveryDate							[it_deliveryDate],
			isnull(it.itd_isBlocked4Delivery,'false')	[it_isBlocked4Delivery],
			it.itd_id									[ID]


	FROM 	dbo.tbItemTransactionsDelivery				IT			 WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions				tct			 WITH (NOLOCK)
		ON	tct.comp_id			=	IT.comp_id
		AND tct.bra_id			=	IT.bra_id
		AND tct.ct_transaction	=	IT.ct_transaction

		INNER JOIN tbItemTransactions					tit			WITH (NOLOCK)
		ON	tit.comp_id			= IT.comp_id		AND
			tit.bra_id			= IT.bra_id			AND
			tit.ct_transaction	= IT.ct_transaction AND
			tit.it_transaction	= IT.it_transaction

		left join dbo.tbItem							ITEM		 WITH (NOLOCK)
		on  item.comp_id		=	tit.comp_id
		AND item.item_id		=	tit.item_id

			LEFT JOIN tbStorage							ts			WITH (NOLOCK)
		ON  ts.comp_id			= tit.comp_id		AND
			ts.stor_id			= tit.stor_id

	where	IT.comp_id			= @comp_id
	and		IT.ct_transaction	= @ct_transaction






END

GO








CREATE PROCEDURE [dbo].[spCommercialTransaction_getDataPurchaseConceptMovements]
(
	@comp_id			as INT,
	@lang_id			as INT,
	@ct_transaction		as INT
)

AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
				@comp_id		as INT,
				@lang_id		as INT,
				@ct_transaction	as INT
		SELECT
				@comp_id		= 1,
				@ct_transaction	= 6125,
				@lang_id        = 2
*/
	-- -----------------------------------------------------------------------


	select
		' '												[ ],
		tcc.cc_desc										[cc_desc],
		tpc.puco_desc									[puco_desc],
		ttm.pcm_total									[total],
		ttm.pcm_id										[ID]


		FROM tbPurchaseConceptMovements 				ttm		WITH (NOLOCK)

		inner JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
		ON  tct.comp_id			= ttm.comp_id	AND
			tct.bra_id			= ttm.bra_id	AND
			tct.ct_transaction	= ttm.ct_transaction

		inner JOIN tbPurchaseConcept					tpc		WITH (NOLOCK)
		ON	tpc.comp_id			= ttm.comp_id	AND
			tpc.puco_id			= ttm.puco_id

		LEFT JOIN tbCostCenter							tcc		WITH (NOLOCK)
		ON	tcc.comp_id			= ttm.comp_id	AND
			tcc.cc_code			= ttm.cc_code


		where	ttm.comp_id			= @comp_id
		and		ttm.ct_transaction	= @ct_transaction






END

GO



