CREATE PROCEDURE [dbo].[spCommercialTransaction_getDataTaxMovements]
(
	@comp_id			as INT,
	@lang_id			as INT,
	@ct_transaction		as INT
)

AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
				@comp_id		as INT,
				@lang_id		as INT,
				@ct_transaction	as INT
		SELECT
				@comp_id		= 1,
				@ct_transaction	= 6125,
				@lang_id        = 2
*/
	-- -----------------------------------------------------------------------


	select  '' [ ],
			ttn.tax_desc,
			ttm.tm_total [total],


			-- No agregar NADA despues de esta linea
			ttn.tax_class,				-- Count - 2
			ttm.tm_transaction [ID]		-- Count - 1


		from tbTaxMovements								ttm		WITH (NOLOCK)

		inner join tbCommercialTransactions				tct		WITH (NOLOCK)
		on  tct.comp_id			= ttm.comp_id
		and tct.bra_id			= ttm.bra_id
		and tct.ct_transaction	= ttm.ct_transaction

		inner join tbTaxName							ttn		WITH (NOLOCK)
		on  ttn.comp_id			= ttm.comp_id
		AND ttn.tax_id			= ttm.tax_id



	where	ttm.comp_id			= @comp_id
	and		ttm.ct_transaction	= @ct_transaction






END

GO







CREATE PROCEDURE [dbo].[spCommercialTransaction_getDataTaxMovements2]
(
	@comp_id			as INT,
	@lang_id			as INT,
	@ct_transaction		as INT
)

AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
	/*
		DECLARE
				@comp_id		as INT,
				@lang_id		as INT,
				@ct_transaction	as INT
		SELECT
				@comp_id		= 1,
				@ct_transaction	= 10897,
				@lang_id        = 2
	*/
	-- -----------------------------------------------------------------------


	select  '' [ ],
			IsNull(sc.strcv_desc,'NO Asignado')		[SIAP_Desc],
			IsNull(sc.strcv_value,-1)				[SIAP_Value],
			ISNULL(sc.strcv_percentage,-1)			[SIAP_Porcentaje],

			CASE
			    WHEN sc.strcv_desc IS NULL  THEN	ttc.taxcl_desc
			    ELSE								sc.strcv_desc
			END 									[tax_desc],
			sum(ttm.tm_subtotal)					[tm_subtotal],
			ttm.percentaje							[tm_percentaje],
			Sum(ttm.tm_total)						[tm_total],
			CASE
				WHEN ttn.tax_class = 1	THEN	ttn.strcv_id
				ELSE							ttc.taxcl_FETipoTributo
			END										[taxcl_FETipoTributo],

			-- No agregar NADA despues de esta linea
			ttn.tax_class--,				-- Count - 2
			--ttm.tm_transaction [ID]		-- Count - 1


		from tbTaxMovements								ttm		WITH (NOLOCK)

		inner join tbCommercialTransactions				tct		WITH (NOLOCK)
		on  tct.comp_id			= ttm.comp_id
		and tct.bra_id			= ttm.bra_id
		and tct.ct_transaction	= ttm.ct_transaction

		inner join tbTaxName							ttn		WITH (NOLOCK)
		on  ttn.comp_id			= ttm.comp_id
		AND ttn.tax_id			= ttm.tax_id

		INNER JOIN tbsysTaxClass ttc
			ON ttc.tax_class	= ttn.tax_class

		LEFT JOIN tbsysSIAP_RG3685V_AlicuotaCode		sc		WITH (NOLOCK)
			ON sc.strcv_id = ttn.strcv_id


	where	ttm.comp_id			= @comp_id
	and		ttm.ct_transaction	= @ct_transaction
	AND		ttm.tm_subtotal     <> 0

	GROUP BY	ttc.taxcl_desc,
				sc.strcv_desc,
				sc.strcv_value,
				sc.strcv_percentage,
				--ttn.tax_desc,
				ttm.percentaje,
				--ttm.tm_total,
				ttn.tax_class,
				ttn.strcv_id,
				ttc.taxcl_FETipoTributo















END

GO

CREATE PROCEDURE [dbo].[spCommercialTransaction_GetDocumentKindOf]
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------
		-- TESTING
		-- ------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT
			SELECT
				@comp_id		= 18,
				@ct_transaction	= 8962
		*/
		-- ------------------------------
		SELECT
			tct.sd_id,
			ISNULL(tct.ct_kindOf,'')								[ct_kindOf],
			ISNULL(tdf.df_electronicInvoiceChile_enabled,'False')	[df_electronicInvoiceChile_enabled],
			ISNULL(tdf.df_electronicInvoiceChile_usuario,'')		[df_electronicInvoiceChile_usuario],
			ISNULL(tdf.df_electronicInvoiceChile_clave,'')			[df_electronicInvoiceChile_clave],
			ISNULL(tdf.df_electronicInvoiceChile_RUT,'')			[df_electronicInvoiceChile_RUT],
			ISNULL(tdf.df_electronicInvoiceChile_puerto,'')			[df_electronicInvoiceChile_puerto]
			FROM tbCommercialTransactions	tct	WITH(NOLOCK)
			INNER JOIN tbDocumentsFile		tdf	WITH(NOLOCK)
			ON	tdf.comp_id = tct.comp_id	AND
				tdf.df_id	= tct.df_id
			WHERE	tct.comp_id			= @comp_id AND
					tct.ct_transaction	= @ct_transaction
	END
GO








