CREATE PROCEDURE [dbo].[spCommercialTransaction_SuppUpdate]
(
	@comp_id				  INT,
	@ct_transaction			  INT,
	@ct_pointOfSale			  INT,
	@ct_kindOf				  VARCHAR(10),
	@ct_docNumber			  VARCHAR(40),
	@ct_isAvailableForPayment BIT,
	@ct_date				  DATETIME,
	@ct_payDate				  DATETIME,
	@ct_taxDate				  DATETIME,
	@supp_id				  INT,
	@ctn_note1				  VARCHAR(350),
	@ctn_note2				  VARCHAR(350),
	@ctn_note3				  VARCHAR(350),
	@ctn_note4				  VARCHAR(350),
	@bra_id					  INT,
	@ct_cai					  VARCHAR(50),
	@ct_CAIDate				  DATETIME,
	@ct_isAvailableForImport  BIT,
	@pro_id					  INT


)
AS


BEGIN



	set nocount on


	SET DATEFORMAT 'ymd'

	-------------------------------------------------------
	/*
	DECLARE
				@comp_id				  INT,
				@ct_transaction			  INT,
				@ct_pointOfSale			  INT,
				@ct_kindOf				  VARCHAR(10),
				@ct_docNumber			  VARCHAR(40),
				@ct_isAvailableForPayment BIT,
				@ct_date				  DATETIME,
				@ct_payDate				  DATETIME,
				@ct_taxDate				  DATETIME,
				@supp_id				  INT,
				@ctn_note1				  VARCHAR(100),
				@ctn_note2				  VARCHAR(100),
				@ctn_note3				  VARCHAR(100),
				@ctn_note4				  VARCHAR(100)


	SELECT		@comp_id		= 1,
				@ct_transaction	= 1301,
				@ct_pointOfSale	= 19,
				@ct_kindOf		= 'B',
				@ct_docNumber	= '0',
				@ct_isAvailableForPayment		= 'False',
				@ct_date		= '2009-07-08',
				@ct_payDate		= '2009-07-08',
				@ct_taxDate		= '2009-07-08',
				@supp_id		= 8103
	*/
	-------------------------------------------------------
	if	(@pro_id		= -1)	set	@pro_id			= NULL

	UPDATE tbCommercialTransactions
	SET
		ct_pointOfSale					= @ct_pointOfSale,
		ct_kindOf						= @ct_kindOf,
		ct_docNumber					= @ct_docNumber,
		ct_date							= @ct_date,
		ct_taxDate						= @ct_taxDate,
		ct_payDate						= @ct_payDate,
		ct_isAvailableForPayment		= @ct_isAvailableForPayment,
		supp_id							= @supp_id,
		ct_CAI							= @ct_cai,
		ct_CAIDate						= @ct_CAIDate,
		ct_isAvailableForImport			= @ct_isAvailableForImport,
		pro_id							= @pro_id


	WHERE	comp_id			= @comp_id
	AND		ct_transaction	= @ct_transaction


	--Actualiza las notas.

		IF not EXISTS(SELECT 1
						FROM tbCommercialTransactionNotes tctn
						WHERE	tctn.comp_id		= @comp_id	AND
								tctn.ct_transaction = @ct_transaction)
			BEGIN

				INSERT INTO tbCommercialTransactionNotes
					(	comp_id,
						bra_id,
						ct_transaction,
						ctn_note1,
						ctn_note2,
						ctn_note3,
						ctn_note4,
						ctn_internalAnnotation)

					Values
					(	@comp_id,
						@bra_id,
						@ct_transaction,
						@ctn_note1,
						@ctn_note2,
						@ctn_note3,
						@ctn_note4,
						'')


			END
		ELSE
			BEGIN
					UPDATE tbCommercialTransactionNotes
				SET

					ctn_note1 = @ctn_note1,
					ctn_note2 = @ctn_note2,
					ctn_note3 = @ctn_note3,
					ctn_note4 = @ctn_note4

				WHERE	comp_id			= @comp_id
				AND		ct_transaction	= @ct_transaction

			END




	-- Control Contable
	DECLARE @hacc_transaction	INT
	DECLARE @hacc_date			DATETIME
	DECLARE @ap_id				INT
	-- Saca el ultimo asiento efectuado para cambiarlo de fecha.
	SELECT	@hacc_transaction		= tath.hacc_transaction,
			@hacc_date				= tath.hacc_date,
			@ap_id					= tath.ap_id
		FROM tbAccountTransactionHead tath
		INNER JOIN tbAccountTransactionDetail tatd
		ON	tatd.comp_id			= tath.comp_id	AND
			tatd.bra_id				= tath.bra_id	AND
			tatd.hacc_transaction	= tath.hacc_transaction
		WHERE	tath.comp_id		= @comp_id AND
				tatd.ct_transaction = @ct_transaction
		ORDER BY tath.hacc_transaction



	-- Si se cambio la fecha del ultimo asiento que tenga este ct_transaction
	IF	@hacc_transaction IS NOT NULL AND
		@hacc_date <> @ct_taxDate
		BEGIN


			-- MOS 10-2020
			SELECT @ap_id = NULL
			Select @ap_id = ap.ap_id
				From dbo.tbAccountantPeriod	ap					WITH (NOLOCK)
				INNER JOIN tbAccountantPeriodByBranch tapbb		WITH (NOLOCK)
					ON	tapbb.comp_id	=	ap.comp_id	AND
						tapbb.bra_id	=	@bra_id		AND
						tapbb.ap_id		=	ap.ap_id
				Where   ap.comp_id		=	@comp_id
					and ap.ap_firstdate <=	@ct_taxDate
					and ap.ap_lastdate  >=	@ct_taxDate
					and ap.ap_closed	=	'False'

			IF @ap_id IS NULL
				BEGIN
					Select @ap_id = ap_id
						From dbo.tbAccountantPeriod			WITH (NOLOCK)
						Where   comp_id = @comp_id
							and ap_firstdate <= @ct_taxDate
							and ap_lastdate  >= @ct_taxDate
							and ap_closed='False'
				END

			--SELECT @ap_id = tap.ap_id
			--	FROM tbAccountantPeriod tap
			--	WHERE	tap.comp_id						= @comp_id					AND
			--			@ct_taxDate BETWEEN tap.ap_firstdate AND tap.ap_lastdate	AND
			--			IsNull(tap.ap_closed,'False')	= 'False'
			-- MOS 10-2020





			DECLARE @hacc_transactionNEW AS INT
			INSERT INTO tbAccountTransactionHead
			(
				comp_id,
				bra_id,
				-- hacc_transaction -- this column value is auto-generated,
				hacc_group,
				hacc_detail,
				hacc_date,
				hacc_number,
				hacc_orderPriority,
				hacc_cd,
				ap_id,
				hacc_blocked,
				hacc_closing,
				hacc_opening,
				hacc_IsEditing,
				hacc_IsEditingDateTime,
				hacc_2ndCurrencyExchange,
				ag_id
			)
			SELECT	tath.comp_id,
					tath.bra_id,
					--tath.hacc_transaction,
					tath.hacc_group,
					tath.hacc_detail,
					@ct_taxDate,  -- Igual HEADER pero Con la nueva fecha
					tath.hacc_number,
					tath.hacc_orderPriority,
					tath.hacc_cd,
					@ap_id,
					tath.hacc_blocked,
					tath.hacc_closing,
					tath.hacc_opening,
					tath.hacc_IsEditing,
					tath.hacc_IsEditingDateTime,
					tath.hacc_2ndCurrencyExchange,
					tath.ag_id
				FROM tbAccountTransactionHead tath
				WHERE	tath.comp_id			= @comp_id AND
						tath.hacc_transaction	= @hacc_transaction

			SET @hacc_transactionNEW = @@IDENTITY


			-- Todo el detail
			INSERT INTO tbAccountTransactionDetail
			(
				comp_id,
				bra_id,
				hacc_transaction,
				-- dacc_transaction -- this column value is auto-generated,
				acc_count_id,
				cc_code,
				dacc_debit,
				dacc_credit,
				[user_id],
				dacc_cd,
				hacc_software,
				ct_transaction,
				acc_detail1,
				acc_detail2,
				dacc_order,
				dacc_2ndCurrencyExchange
			)
			SELECT	tatd.comp_id,
					tatd.bra_id,
					@hacc_transactionNEW,
					--tatd.dacc_transaction,
					tatd.acc_count_id,
					tatd.cc_code,
					tatd.dacc_debit,
					tatd.dacc_credit,
					tatd.[user_id],
					tatd.dacc_cd,
					tatd.hacc_software,
					tatd.ct_transaction,
					tatd.acc_detail1,
					tatd.acc_detail2,
					tatd.dacc_order,
					tatd.dacc_2ndCurrencyExchange
				FROM tbAccountTransactionDetail tatd
				WHERE	tatd.comp_id			= @comp_id			AND
						tatd.hacc_transaction	= @hacc_transaction AND
						tatd.ct_transaction		= @ct_transaction


			-- Borro las imputaciones del asiento original.
			DELETE
				FROM tbAccountTransactionDetail
				WHERE	comp_id				= @comp_id			AND
						hacc_transaction	= @hacc_transaction AND
						ct_transaction		= @ct_transaction

			-- Si el Head Original se quedo sin movimientos porque era el unico, lo borro.
			IF NOT EXISTS(
							SELECT 1
							FROM tbAccountTransactionDetail tatd
								WHERE	tatd.comp_id			= @comp_id AND
										tatd.hacc_transaction	= @hacc_transaction
							)
				BEGIN
					DELETE FROM tbAccountTransactionHead
						WHERE	comp_id				= @comp_id AND
								hacc_transaction	= @hacc_transaction
				END






		END





END
GO






create PROCEDURE [dbo].[spCommercialTransaction_SuppUpdate_getDataItemTransactions]
(
	@comp_id			as INT,
	@lang_id			as INT,
	@ct_transaction		as INT
)

AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
				@comp_id		as INT,
				@lang_id		as INT,
				@ct_transaction	as INT


		SELECT
				@comp_id		= 1,
				@ct_transaction	= 8983,
				@lang_id        = 2

*/
	-- -----------------------------------------------------------------------


	select  ''												[ ],
			ITEM.item_code									[item_code],
			ITEM.item_desc									[item_desc],
			tpc.puco_desc									[puco_desc],
			it.it_transaction								[ID]


	FROM 	dbo.tbItemTransactions						IT			 WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions				tct			 WITH (NOLOCK)
		ON	tct.comp_id			=	IT.comp_id
		AND tct.bra_id			=	IT.bra_id
		AND tct.ct_transaction	=	IT.ct_transaction

		left join dbo.tbItem							ITEM		 WITH (NOLOCK)
		on  item.comp_id		=	IT.comp_id
		AND item.item_id		=	IT.item_id

		left JOIN tbPurchaseConcept						tpc			WITH (NOLOCK)
		ON	tpc.comp_id = IT.comp_id
		AND tpc.puco_id = IT.puco_id

	where	IT.comp_id			= @comp_id
	and		IT.ct_transaction	= @ct_transaction






END

GO







CREATE PROCEDURE [dbo].[spCommercialTransaction_update_curr_id4Exchange]
(
	@comp_id							int,
	@bra_id								int,
	@ct_transaction					AS  INT,
	@curr_id_from						int,				-- 1
	@curr_id_to							int,				--44
	@currency_exchange					DECIMAL(35,15)		-- 0.02
)
AS


BEGIN

	SET NOCOUNT ON

	-- =================================================================================================================
	-- Author		: MOZ + MOS
	-- Update Date	: 2011-11-04
	-- Parte		: Actualiza el tipo de cambio a grabar que esta cargado en Sucursal.
	-- Description	: Usar al final de las transacciones, vuelve a recalcular todo por si se grabo cualquier cosa antes
	--                Esto se basa en el tipo de cambio que se fija con el control wucExchange de las paginas.
	-- =================================================================================================================

-- -------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------
/*
	declare @comp_id							int,
			@bra_id								int,
			@ct_transaction					    INT,
			@curr_id_from						int,
			@curr_id_to							int,
			@currency_exchange					DECIMAL(19,6)

	SET     @comp_id							= 1
	SET		@bra_id								= 32
	SET		@ct_transaction						= 514844
	SET		@curr_id_from						= 1
	SET		@curr_id_to							= 44
	SET		@currency_exchange					= 0.02
*/
-- -------------------------------------------------------------



	DECLARE @intCurrency2Save	AS INT
	DECLARE @intBranchCurrency	AS INT
	declare @intCompanyCurrency AS INT
	SELECT  @intCurrency2Save	= tb.curr_id4Exchange,
			@intBranchCurrency  = tb.curr_id,
			@intCompanyCurrency = tc.curr_id
		FROM tbBranch tb			WITH (NOLOCK)
		INNER JOIN tbCompany tc		WITH (NOLOCK)
			ON tc.comp_id = tb.comp_id
		WHERE	tb.comp_id		= @comp_id
			AND tb.bra_id		= @bra_id


	-- -------------------------------------------------------------------------------------------------------------------------
	-- 12-2012
	-- Si se selecciono un tipo de cambio en el control de tipos de cambio, SE DEBE GRABAR EL MISMO y no el que dice la sucursal
	-- -------------------------------------------------------------------------------------------------------------------------
	IF @curr_id_from <> @curr_id_to
		BEGIN
			SET @intCurrency2Save = @curr_id_to
		END
	-- -------------------------------------------------------------------------------------------------------------------------

	DECLARE @decExchange					AS DECIMAL(35,15)
	DECLARE @decExchange2CompanyCurrency	AS DECIMAL(35,15)

	SET @decExchange				= dbo.fnGetExchange2(@comp_id,
					   									1 ,
					   									@intCurrency2Save,
					   									@intBranchCurrency,
					   									@curr_id_from,
														@curr_id_to,
														@currency_exchange,
														'false')

	SET @decExchange2CompanyCurrency = dbo.fnGetExchange2(@comp_id,
					   									1 ,
					   									@intBranchCurrency,
					   									@intCompanyCurrency,
					   									@curr_id_from,
														@curr_id_to,
														@currency_exchange,
														'false')




	UPDATE tbCommercialTransactions	WITH (ROWLOCK)
	SET
		curr_id4Exchange					= @intCurrency2Save,
		ct_curr_IdExchange					= @decExchange,
		ct_CompanyCurrency					= @intCompanyCurrency,
		ct_Branch2CompanyCurrencyExchange	= @decExchange2CompanyCurrency
	WHERE	comp_id			= @comp_id
		--AND bra_id			= @bra_id
		and ct_transaction	= @ct_transaction




END
GO







CREATE PROCEDURE [dbo].[spCommercialTransaction_updateAdditionalData]
(
	@comp_id							int,
	@bra_id								int,
	@ct_transaction						int,
	@ct_soh_bra_id						int,
	@ct_soh_id							int,
	@tis_guid							UNIQUEIDENTIFIER,
	@custf_id							INT,
	@cust_id_guarantor					INT,
	@decInCash							DECIMAL(19,5),
	@deliveryDate						DATETIME,
	@DocumentNumber						SMALLINT ,
	@DocumentTotal						SMALLINT,
	@ccp_id								INT,
	@st_id								INT,
	@Is4ManualEmitting					BIT,
	@strDocumentNumber					VARCHAR(50),
	@pro_id								INT,
	@return_value						int				output,
	@ret_ErrorCode						int				output,
	@ret_ErrorDescription				varchar(200)	output
)
AS

BEGIN



	SET NOCOUNT ON

	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-01-10
	-- Parte		: 749
	-- Description	: Actualizar el ct_packagesQty desde el soh_packagesQty
	-- =================================================================================================================


	IF @custf_id			= -1	SET @custf_id			= NULL
	IF @cust_id_guarantor	= -1	SET @cust_id_guarantor	= NULL



	SET @return_value			= 0
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''


	DECLARE @soh_packagesQty INT	-- Parte: 749


	BEGIN TRY
		DECLARE @ssos_id AS INT

		DECLARE @ws_IPFrom		AS NVARCHAR(50)
		DECLARE @ws_internalID	AS INT
		DECLARE @ws_cust_Id		AS INT
		-- =================================================================================================================
		-- Parte: 749
		SELECT	@soh_packagesQty	= ISNULL(tsoh.soh_packagesQty,0),
				@ws_IPFrom			= tsoh.ws_IPFrom,
		      	@ws_internalID		= tsoh.ws_internalID,
		      	@ws_cust_Id			= tsoh.ws_cust_Id,
		      	@ssos_id			= tsoh.ssos_id
			FROM	tbSaleOrderHeader	tsoh		WITH (NOLOCK)
			WHERE	tsoh.comp_id		= @comp_id
			AND		tsoh.bra_id			= @bra_id
			AND		tsoh.soh_id			= @ct_soh_id

		-- a esto le sumo los paqueres que vienen por remitir facturas (algono de los dos SIEMPRE va a estar en CERO.-)
		DECLARE @intPackagesQty AS INT
		SELECT  @intPackagesQty = SUM(IsNull(ttis.tis_PackagesQty,0))
			FROM tbTempItemStock ttis		WITH (NOLOCK)
			WHERE ttis.tis_guid = @tis_guid



		SET @soh_packagesQty = IsNull(@soh_packagesQty,0) + IsNull(@intPackagesQty,0)
		-- =================================================================================================================




		-- ----------------------------------------------------------------------
		-- Deja grabado si el movimiento es de RMA, Cheque Rechazado, Dif.Cambio, etc
		-- ----------------------------------------------------------------------
		DECLARE @sctt_id AS INT
		SET		@sctt_id = 100			-- Valor por Defecto


		--SELECT @ssos_id = tsoh.ssos_id
		--	FROM tbSaleOrderHeader tsoh		WITH (NOLOCK)
		--	WHERE	tsoh.comp_id	= @comp_id
		--		AND tsoh.bra_id		= @ct_soh_bra_id
		--		AND tsoh.soh_id		= @ct_soh_id

		-- RMA.-
		IF @ssos_id = 200 OR @ssos_id = 201 OR @ssos_id = 205
			BEGIN
				 set @sctt_id = 101
			END

		-- Cheque Rechazado.-
		IF @ssos_id = 220
			BEGIN
				 set @sctt_id = 102
			END

		-- Diferencia de Cambio.-
		IF @ssos_id = 210
			BEGIN
				 set @sctt_id = 103
			END
		-- ----------------------------------------------------------------------

		IF @ct_soh_bra_id = -1
			BEGIN
				SET @ct_soh_bra_id = NULL
				SET @ct_soh_id = NULL
			END



		DECLARE @mlo_id		AS INT
		DECLARE @ws_st_id	AS INT
		DECLARE @ws_dl_id	AS INT
		SELECT	@ws_st_id	= tsoh.ws_st_id,
				@ws_dl_id	= tsoh.ws_dl_id,
				@mlo_id		= tsoh.mlo_id
			FROM	tbSaleOrderHeader tsoh	WITH (NOLOCK)
			WHERE	tsoh.comp_id	= @comp_id		AND
					tsoh.bra_id		= @ct_soh_bra_id	AND
					tsoh.soh_id		= @ct_soh_id



		UPDATE	tbCommercialTransactions	WITH (ROWLOCK)
			SET		ct_soh_bra_id		= @ct_soh_bra_id,
					ct_soh_id			= @ct_soh_id,
					ct_packagesQty		= (IsNull(ct_packagesQty,0) + IsNull(@soh_packagesQty,0)),		-- Parte: 749
					sctt_id				= @sctt_id,
					custf_id			= @custf_id,
					cust_id_guarantor	= @cust_id_guarantor,
					ct_inCash			= @decInCash,
					ct_deliveryDate		= @deliveryDate,
					ws_cust_Id			= @ws_cust_Id,
					ws_internalID		= @ws_internalID,
					ws_st_id			= @ws_st_id,
					ws_dl_id			= @ws_dl_id,
					mlo_id				= @mlo_id,
					ct_documentNumber	=	@DocumentNumber,
					ct_documentTotal	= @DocumentTotal,
					ct_docNumber		= CASE
												WHEN @Is4ManualEmitting = 'True' THEN	@strDocumentNumber	-- MOS x MundoFix y sus &$%$#$%%...
												ELSE									ct_docNumber        -- 03-2022
											END
			WHERE	comp_id				= @comp_id
			AND 	bra_id				= @bra_id
			AND		ct_transaction		= @ct_transaction


		-- MOS 01-2023
		IF @pro_id > 0
			BEGIN
				UPDATE	tbCommercialTransactions	WITH (ROWLOCK)
					SET pro_id = @pro_id
					WHERE	comp_id				= @comp_id
					AND 	bra_id				= @bra_id
					AND		ct_transaction		= @ct_transaction
			END




		-- ---------------------------------------------------------------------
		-- Actualiza Tabla de Cuotas
		-- ---------------------------------------------------------------------
		IF EXISTS(
					SELECT TOP 1  1
						FROM tbSaleOrderLoanTMP tsolt		WITH (NOLOCK)
						WHERE tsolt.tis_guid = @tis_guid
		)
			BEGIN

				DECLARE @ct_ATotal	AS DECIMAL(19,5) = 0
				DECLARE @curr_id	AS INT
				SELECT	@curr_id	= tct.ct_ACurrency,
						@ct_ATotal	= tct.ct_ATotal
					FROM tbCommercialTransactions tct		WITH (NOLOCK)
					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ct_transaction

				DECLARE @intTotalCuote AS INT	= 0
				--SET		@intTotalCuote		= 0

				SELECT	@intTotalCuote		= MAX(tsolt.ln_loanPayNumber)  --COUNT(*)
					FROM tbSaleOrderLoanTMP					tsolt		WITH (NOLOCK)
						INNER JOIN tbTempItemStock			ttis		WITH (NOLOCK)
						ON	ttis.comp_id	= tsolt.comp_id AND
							ttis.tis_id		= tsolt.tis_id
					WHERE	tsolt.comp_id	= @comp_id		AND
							tsolt.tis_guid	= @tis_guid		AND
							tsolt.ln_loanPayNumber <> 0
					--GROUP BY tsolt.ln_loanPayDate,tsolt.ln_loanPayNumber
					--ORDER BY tsolt.ln_loanPayDate ASC



				INSERT INTO tbCommercialTransactionsLoan	WITH (ROWLOCK)
				(
					comp_id,
					ct_transaction,
					-- ctl_id -- this column value is auto-generated,
					ctl_payNumber,
					ctl_payDate,
					ct_ATotal,
					ct_ABalance,
					curr_id,
					ctl_isOriginalMovement,
					user_id4updatePay,
					updatePay_cd,
					ctl_id_master,
					ctl_payNumberTotalQty
				)
					SELECT
						@comp_id,
						@ct_transaction,
						tsolt.ln_loanPayNumber,
						tsolt.ln_loanPayDate,
						SUM (tsolt.ln_loanPayTotal),
						SUM (tsolt.ln_loanPayTotal),
						1,
						'True',
						NULL,
						NULL,
						NULL,
						@intTotalCuote
					FROM tbSaleOrderLoanTMP					tsolt		WITH (NOLOCK)
					INNER JOIN tbTempItemStock				ttis		WITH (NOLOCK)
						ON	ttis.comp_id	= tsolt.comp_id AND
							ttis.tis_id		= tsolt.tis_id
					WHERE	tsolt.comp_id	= @comp_id		AND
							tsolt.tis_guid	= @tis_guid
					GROUP BY tsolt.ln_loanPayDate,tsolt.ln_loanPayNumber
					ORDER BY tsolt.ln_loanPayDate ASC


				-- -------------------------------------------------------------------------------------------------------------------
				-- MOS  03-2021  Ticket 7408
				-- TOYOS: dice que a veces le queda un centavo de diferencia entre la suma de las cuotas y commercialtransactions
				-- -------------------------------------------------------------------------------------------------------------------
				DECLARE @decTotalCheck AS DECIMAL(19,5)
				SELECT	@decTotalCheck			= SUM(tctl.ct_ATotal)
					FROM tbCommercialTransactionsLoan AS tctl	WITH (NOLOCK)
					WHERE	tctl.comp_id		= @comp_id			AND
							tctl.ct_transaction = @ct_transaction

				IF @ct_ATotal <> @decTotalCheck
					BEGIN
						UPDATE tbCommercialTransactionsLoan		WITH (ROWLOCK)
							SET ct_ATotal	= ct_ATotal		+ (@ct_ATotal - @decTotalCheck),
								ct_ABalance = ct_ABalance	+ (@ct_ATotal - @decTotalCheck)
							WHERE	comp_id			= @comp_id			AND
									ct_transaction	= @ct_transaction	AND
									ctl_payNumber	= 1
					END
				-- -------------------------------------------------------------------------------------------------------------------




			END

		-- ---------------------------------------------------------------------


		-- ---------------------------------------------------------------------
		-- Si NO tiene plan de pagos y tiene una T.Credito asociada y la cond de
		--   venta pide que la precargue, la guarda para que la precargue.
		-- ---------------------------------------------------------------------
		IF EXISTS(
					SELECT TOP 1 1
						FROM tbSalesTerms tst WITH (NOLOCK)
						WHERE	tst.comp_id = @comp_id	AND
								tst.st_id	= @st_id	AND
								tst.cc_id IS NOT NULL	AND
								tst.st_directCollectionWithCC_LoadCCIfNoPlan = 'True'
				)
			BEGIN
				IF NOT EXISTS (
								SELECT TOP 1 1
									FROM tbSaleOrderCreditCards tsocc	 WITH (NOLOCK)
									WHERE	tsocc.comp_id			= @comp_id AND
											tsocc.ct_transaction	= @ct_transaction
								)
					BEGIN

						IF @ccp_id <= 0 SET @ccp_id = NULL

						DECLARE			@cc_id AS INT = NULL
						SELECT TOP 1	@cc_id = tst.cc_id
							FROM tbSalesTerms tst WITH (NOLOCK)
							WHERE	tst.comp_id = @comp_id	AND
									tst.st_id	= @st_id
						DECLARE			@decTOTAL AS DECIMAL(35,6) = 0
						SELECT TOP 1	@decTOTAL = ISNULL(tct.ct_total,0) - ISNULL(@decInCash,0)
							FROM tbCommercialTransactions tct	WITH (NOLOCK)
							WHERE	tct.comp_id			= @comp_id	AND
									tct.bra_id			= @bra_id	AND
									tct.ct_transaction	= @ct_transaction

						-- T.Credito
						INSERT INTO tbSaleOrderCreditCards
						(
							comp_id,
							tis_guid,
							bra_id,
							soh_id,
							cc_id,
							ccp_id,
							sohp_total,
							sohp_percentage,
							sohp_position,
							ct_transaction
						)
						VALUES
						(
							@comp_id,
							@tis_guid ,
							@bra_id,
							NULL,
							@cc_id,
							@ccp_id,
							@decTOTAL,
							0,
							1,
							@ct_transaction
						)


						-- Efecvtivo
						IF @decInCash > 0
							BEGIN
								INSERT INTO tbSaleOrderCreditCards
								(
									comp_id,
									tis_guid,
									bra_id,
									soh_id,
									cc_id,
									ccp_id,
									sohp_total,
									sohp_percentage,
									sohp_position,
									ct_transaction
								)
								VALUES
								(
									@comp_id,
									@tis_guid ,
									@bra_id,
									NULL,
									NULL,
									NULL,
									@decinCash,
									0,
									7,
									@ct_transaction
								)
							END


					END
			END
		ELSE IF @ccp_id IS NOT NULL AND @ccp_id > 0	-- Si tiene un plan de cuotas guardo el coeficiente del plan.
			BEGIN

				DECLARE		 @decCoeficient AS DECIMAL(19,4) = 1
				SELECT TOP 1 @decCoeficient =	CASE
													WHEN ISNULL(tcclp.ccp_discountPlanCoeficient,0) = 0 THEN 1
													ELSE													 tcclp.ccp_discountPlanCoeficient
												END
					FROM tbCommercialTransactions	AS tct		WITH (NOLOCK)
					INNER JOIN tbCreditCardLoanPlan AS tcclp	WITH (NOLOCK)
						ON	tcclp.comp_id		= tct.comp_id AND
							tcclp.ccp_id		= tct.ccp_id
					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ct_transaction

				UPDATE tbCommercialTransactions		WITH (ROWLOCK)
					SET ct_discountPlanCoeficient = @decCoeficient
					WHERE	comp_id			= @comp_id AND
							ct_transaction	= @ct_transaction

			END
		-- ---------------------------------------------------------------------




	END TRY
	BEGIN CATCH
		SET @return_value			= -1
		SET @ret_ErrorCode			= -1
		SET @ret_ErrorDescription	= '01 - ' + ERROR_MESSAGE()
	END CATCH



END
GO

CREATE PROCEDURE spCommercialTransaction_UpdateCAI_And_CAIDate_4ElectronicInvoice_Chile
(
	@comp_id		INT,
	@ct_transaction	INT,
	@ct_CAI			NVARCHAR(50),
	@ct_CAIDate		DATETIME
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------
		-- TESTING
		-- -----------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT,
				@ct_CAI			NVARCHAR(50),
				@ct_CAIDate		DATETIME
		*/
