CREATE PROCEDURE spCommercialTransactionNotes_GetDataByID_4ChileElectronicInvoice
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------
		-- TESTING
		-- ---------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@ct_transaction	INT
			SELECT
				@comp_id		= 1,
				@bra_id			= 1,
