	END
GO

CREATE PROCEDURE spCommercialTransactionNotes_GetLink4ReprintExternalElectronicInvoice
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------
		-- TESTING
		-- -------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT
			SELECT
				@comp_id		= 1,
				@ct_transaction	= 6813
		*/
		-- -------------------------------

		SELECT
			ISNULL(tctn.ctn_link4ReprintExternalElectronicInvoice,'')	[ctn_link4ReprintExternalElectronicInvoice]
			FROM tbCommercialTransactionNotes				tctn		WITH(NOLOCK)
			WHERE	tctn.comp_id		= @comp_id			AND
					tctn.ct_transaction = @ct_transaction
	END
GO

