		IF EXISTS(SELECT 1 FROM tbCommercialTransactionNotes AS tctn WHERE tctn.comp_id = @comp_id AND tctn.bra_id = @bra_id AND tctn.ct_transaction = @ct_transaction)
			BEGIN
				UPDATE tbCommercialTransactionNotes
