--Desc: Grilla generica - Ver Asiento Contable
--      Compras y Ventas
------------------------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spCommercialTransactions_Accounting_GetData4GenericGrid]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@ct_transaction		INT
)

AS



BEGIN


	-- ----------------------------------------
	-- TESTING
	-- ----------------------------------------
/*
		DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@ct_transaction		INT
		SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@ct_transaction		= 4923
*/
	-- ----------------------------------------

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	SELECT
			A.hacc_number,
			A.hacc_detail,
			A.hacc_date,
			AC.acc_code,
			AC.acc_desc,
			T.acc_detail1,
			T.dacc_debit,
			T.dacc_credit
		FROM	dbo.tbAccountTransactionDetail			T				WITH (NOLOCK)
		INNER JOIN [tbAccountTransactionHead]	A				WITH (NOLOCK)
			ON	T.[hacc_transaction]	= A.[hacc_transaction]
			AND T.[comp_id]				= A.[comp_id]

		INNER JOIN tbAccountant					AC				WITH (NOLOCK)
			ON	A.comp_id				= AC.comp_id
			AND T.acc_count_id			= AC.acc_count_id

		WHERE	t.[comp_id]		= @comp_id		AND
				T.ct_transaction = @ct_transaction

		ORDER BY	A.hacc_number,
					CASE
						WHEN t.dacc_credit <> 0 THEN	2
						ELSE							1
					END,
					T.[dacc_order]







	END
GO


