-- Log
-- MOS 08-2024: Agregar verificacion de cosas cargadas en el sistema y que NO están en afip



CREATE PROCEDURE [dbo].[spCommercialTransactions_AFIPPurchasesConciliation_GetDataByFilters]
(
	@comp_id				INT,
	@lang_id				INT,
	@brag_id				INT,
	@intRecordType			INT, -- -1 TODOS // 1 Con Contabilización Verificada // 2 con Contabilización Pendiente
	@datFromDate			DATETIME,
	@datToDate				DATETIME,
	@strTaxNumber			CHAR(20),
	@strDenominacionEmisor	NVARCHAR(250)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT = 1,
				@lang_id		INT = 2,
				@brag_id		INT = 4,
				@intRecordType	INT = 2, -- -1 TODOS // 1 Con Contabilización Verificada // 2 con Contabilización Pendiente
				@datFromDate	DATETIME = '2020-01-01',
				@datToDate		DATETIME = '2029-12-31',
				@strTaxNumber	CHAR(20) = '',
				@strDenominacionEmisor CHAR(50)	= ''
		*/
		-- ---------------------------------------------------------------


		DECLARE @tblBranches TABLE(bra_id INT)
		INSERT INTO @tblBranches
		(
			bra_id
		)
			SELECT bra_id
				FROM tbBranchGroupDetail AS tbgd	WITH (NOLOCK)
				WHERE	tbgd.comp_id = @comp_id AND
						tbgd.brag_id = @brag_id

		SET @datFromDate	= dbo.fnGetEnd_or_BeginOfDate(@datFromDate,'False')
		SET @datToDate		= dbo.fnGetEnd_or_BeginOfDate(@datToDate  ,'True')

		SELECT
			' '																						[ ],
			'1.AFIP'																				[AFIP],
			dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[Comprobante],
			tctac.afipFecha,
			tctac.afipTIPO,
			tctac.afipPuntoVenta,
			tctac.afipNumeroDesde,
			tctac.afipNumeroHasta,
			tctac.afipCodAutorizacion,
			tctac.afipTipoDocEmisor,
			tctac.afipNumeroDocEmisor,
			tctac.afipDenominacionEmisor,
			tctac.afipTipoCambio,
			tctac.afipMoneda,
			tctac.afipNetoGravado,
			tctac.afipNetoNoGravado,
			tctac.afipExento,
			tctac.afipOtrosTributos,
			tctac.afipIVA,
			tctac.afipTOTAL,
			tctac.afipcpte_id											[ID]
			FROM tbCommercialTransactions_AFIPPurchasesConciliation		AS tctac	WITH(NOLOCK)
			LEFT JOIN tbCommercialTransactions						AS tct WITH(NOLOCK)
				ON	tct.comp_id			= tctac.comp_id				AND
					tct.ct_transaction	= tctac.ct_transaction		AND
					EXISTS ( SELECT 1 FROM @tblBranches AS tb2 WHERE tb2.bra_id = tct.bra_id)		-- Mierda pero como es de poco uso mejor q quede asi y es MAS SIMPLE de entender.
			WHERE	tctac.comp_id			= @comp_id					AND
					tctac.brag_id			= @brag_id					AND
					(	-- -1 TODOS // 1 Con Contabilización Verificada // 2 con Contabilización Pendiente
						@intRecordType = -1
						OR
						@intRecordType = 1 AND tctac.ct_transaction IS NOT NULL
						OR
						@intRecordType = 2 AND tctac.ct_transaction IS NULL
					)													AND
					tctac.afipFecha BETWEEN @datFromDate AND @datToDate	AND
					(
						@strTaxNumber = ''
						OR
						tctac.afipNumeroDocEmisor = @strTaxNumber
					)													AND
					(
						@strDenominacionEmisor	= ''
						OR
						tctac.afipDenominacionEmisor	LIKE '%' + @strDenominacionEmisor + '%'
					)
			--ORDER BY	tctac.afipFecha,
			--			tctac.afipNumeroDocEmisor


		-- MOS 08-2024
		UNION

		SELECT
			' '																						[ ],
			'2.ERP'																					[AFIP],
			'-->> ' + dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[Comprobante],
			tct.ct_taxDate,
			tctac.afipTIPO,
			tctac.afipPuntoVenta,
			tctac.afipNumeroDesde,
			tctac.afipNumeroHasta,
			tctac.afipCodAutorizacion,
			tctac.afipTipoDocEmisor,
			ts2.supp_taxNumber,
			CONVERT(CHAR(10),ts2.supp_id) + ' -> ' +  ts2.supp_name,
			tctac.afipTipoCambio,
			tctac.afipMoneda,
			tct.ct_subtotal,
			tctac.afipNetoNoGravado,
			tctac.afipExento,
			tctac.afipOtrosTributos,
			tctac.afipIVA,
			tct.ct_total,
			tctac.afipcpte_id											[ID]
			FROM tbCommercialTransactions										AS tct		WITH (NOLOCK)
			INNER JOIN @tblBranches												AS tb
				ON tb.bra_id = tct.bra_id
			INNER JOIN vwCommercialTransactions_forPurchase						AS vctfp	WITH (NOLOCK)
				ON	vctfp.comp_id		= tct.comp_id AND
					vctfp.ct_transaction= tct.ct_transaction
			INNER JOIN tbSupplier												AS ts2		WITH (NOLOCK)
				ON	ts2.comp_id			= tct.comp_id AND
					ts2.supp_id			= tct.supp_id
			LEFT JOIN  tbCommercialTransactions_AFIPPurchasesConciliation		AS tctac	WITH (NOLOCK)
				ON	tct.comp_id			= tctac.comp_id					AND
					tct.ct_transaction	= tctac.ct_transaction
			WHERE	tct.comp_id			= @comp_id						AND
					tct.sd_id  IN (101,103,104,130,131)								AND
					(	 -- -1 TODOS // 1 Con Contabilización Verificada // 2 con Contabilización Pendiente
						@intRecordType = -1
						OR
						@intRecordType = 1 AND tctac.ct_transaction IS NOT NULL
						OR
						@intRecordType = 2 AND tctac.ct_transaction IS NULL
					)													AND
					tct.ct_taxDate BETWEEN @datFromDate AND @datToDate	AND
					(
						@strTaxNumber = ''
						OR
						tctac.afipNumeroDocEmisor = @strTaxNumber
						OR
						ts2.supp_taxNumber = @strTaxNumber
					)													AND
					(
						@strDenominacionEmisor	= ''
						OR
						ts2.supp_name	LIKE '%' + @strDenominacionEmisor + '%'
					)
			ORDER BY	AFIP,
						tctac.afipFecha,
						tctac.afipNumeroDocEmisor
						--ORDER BY	tct.ct_taxDate,
						--			ts2.supp_taxNumber







	END
GO

CREATE PROCEDURE spCommercialTransactions_AFIPPurchasesConciliation_InsertData
(
	@comp_id				INT,
	@brag_id				INT,
	@datFecha				DATETIME,
	@strTipo				CHAR(20),
	@intPuntoDeVenta		INT,
	@strNumeroDesde			CHAR(20),
	@strNumeroHasta			CHAR(20),
	@strCodAutorizacion		CHAR(30),
	@strTipoDocEmisor		CHAR(10),
	@strNroDocEmisor		CHAR(20),
	@strDenominacionEmisor	NVARCHAR(250),
	@decTipoDeCambio		DECIMAL(19,4),
	@strMonedaSymbol		CHAR(10),
	@decImpNetoGravado		DECIMAL(19,4),
	@decImpNetoNoGravado	DECIMAL(19,4),
	@decImpOPExentas		DECIMAL(19,4),
	@decOtrosTributos		DECIMAL(19,4),
	@decIVA					DECIMAL(19,4),
	@decImpTotal			DECIMAL(19,4)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@brag_id				INT,
				@datFecha				DATETIME,
				@strTipo				CHAR(20),
				@intPuntoDeVenta		INT,
				@strNumeroDesde			CHAR(20),
				@strNumeroHasta			CHAR(20),
				@strCodAutorizacion		CHAR(30),
				@strTipoDocEmisor		CHAR(10),
				@strNroDocEmisor		CHAR(20),
				@strDenominacionEmisor	NVARCHAR(250),
				@decTipoDeCambio		DECIMAL(19,4),
				@strMonedaSymbol		CHAR(10),
				@decImpNetoGravado		DECIMAL(19,4),
				@decImpNetoNoGravado	DECIMAL(19,4),
				@decImpOPExentas		DECIMAL(19,4),
				@decOtrosTributos		DECIMAL(19,4),
				@decIVA					DECIMAL(19,4),
				@decImpTotal			DECIMAL(19,4)
		*/
		-- ----------------------------------------------------------

		IF NOT EXISTS(SELECT
					TOP 1 1
					FROM tbCommercialTransactions_AFIPPurchasesConciliation		AS tctac	WITH(NOLOCK)
					WHERE	tctac.comp_id				= @comp_id				AND
							tctac.brag_id				= @brag_id				AND
							tctac.afipTIPO				= @strTipo				AND
							tctac.afipPuntoVenta		= @intPuntoDeVenta		AND
							tctac.afipNumeroDesde		= @strNumeroDesde		AND
							tctac.afipCodAutorizacion	= @strCodAutorizacion	AND
							tctac.afipNumeroDocEmisor	= @strNroDocEmisor)
			BEGIN
				INSERT INTO tbCommercialTransactions_AFIPPurchasesConciliation
				(
					comp_id,
					brag_id,
					afipFecha,
					afipTIPO,
					afipPuntoVenta,
					afipNumeroDesde,
					afipNumeroHasta,
					afipCodAutorizacion,
					afipTipoDocEmisor,
					afipNumeroDocEmisor,
					afipDenominacionEmisor,
					afipTipoCambio,
					afipMoneda,
					afipNetoGravado,
					afipNetoNoGravado,
					afipExento,
					afipOtrosTributos,
					afipIVA,
					afipTOTAL
				)
				VALUES
				(
					@comp_id,
					@brag_id,
					@datFecha,
					@strTipo,
					@intPuntoDeVenta,
					@strNumeroDesde,
					@strNumeroHasta,
					@strCodAutorizacion,
					@strTipoDocEmisor,
					@strNroDocEmisor,
					@strDenominacionEmisor,
					@decTipoDeCambio,
					@strMonedaSymbol,
					@decImpNetoGravado,
					@decImpNetoNoGravado,
					@decImpOPExentas,
					@decOtrosTributos,
					@decIVA,
					@decImpTotal
				)
				-- SI INSERTO ALGO DEVUELVE UN ID
				SELECT @@IDENTITY [ID]
			END
		ELSE
			BEGIN
				-- SI YA EXISTE DEVUELVE -1
				SELECT -1 [ID]
			END
	END
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactions_AFIPPurchasesConciliation_VerificationProcess]
	@comp_id		AS INT,
	@brag_id		AS INT,
	@datFromDate	AS DATETIME,
	@datToDate		AS DATETIME

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	SET @datFromDate	= dbo.fnGetEnd_or_BeginOfDate(@datFromDate,'False')
	SET @datToDate		= dbo.fnGetEnd_or_BeginOfDate(@datToDate,'True')


	DECLARE @tmpBranch TABLE(bra_id INT PRIMARY KEY)
	INSERT INTO @tmpBranch
	(
		bra_id
	)
		SELECT bra_id
			FROM tbBranchGroupDetail AS tbgd	WITH (NOLOCK)
			WHERE	tbgd.comp_id = @comp_id AND
					tbgd.brag_id =  @brag_id


	DECLARE		@tmpAFIPTransactions TABLE(comp_id INT,afipcpte_id INT)
	INSERT INTO @tmpAFIPTransactions
	(
		comp_id,
		afipcpte_id
	)
		SELECT	tctac.comp_id,
				tctac.afipcpte_id
			FROM tbCommercialTransactions_AFIPPurchasesConciliation AS tctac WITH (NOLOCK)
			WHERE	tctac.comp_id = @comp_id AND
					tctac.brag_id = @brag_id AND
					tctac.afipFecha BETWEEN @datFromDate AND @datToDate	AND
					tctac.ct_transaction IS NULL

	DECLARE @intRecordCount AS INT = 0
	SELECT	@intRecordCount = COUNT(*)
		FROM @tmpAFIPTransactions AS ta

	DECLARE @intCounter		AS INT = 1	-- MOS 07-2024: estaba en cero y lo puse en 1
	DECLARE @afipcpte_id	AS INT = 0

	DECLARE @afipFecha					AS DATETIME
	DECLARE @afipTIPO					AS VARCHAR(50)
	DECLARE @afipPuntoVenta				AS INT
	DECLARE @afipNumeroDesde			AS VARCHAR(30)
	DECLARE @afipNumeroHasta			AS VARCHAR(30)
	DECLARE @afipCodAutorizacion		AS VARCHAR(50)
	DECLARE @afipTipoDocEmisor			AS VARCHAR(20)
	DECLARE @afipNumeroDocEmisor		AS VARCHAR(20)
	DECLARE @afipDenominacionEmisor		AS VARCHAR(250)
	DECLARE @afipTipoCambio				AS DECIMAL(19,4)
	DECLARE @afipMoneda					AS VARCHAR(10)
	DECLARE @afipNetoGravado			AS DECIMAL(19,4)
	DECLARE @afipNetoNoGravado			AS DECIMAL(19,4)
	DECLARE @afipExento					AS DECIMAL(19,4)
	DECLARE @afipOtrosTributos			AS DECIMAL(19,4)
	DECLARE @afipIVA					AS DECIMAL(19,4)
	DECLARE @afipTOTAL					AS DECIMAL(19,4)

	DECLARE @ct_transaction				AS INT
	DECLARE @intSDId					AS INT
	DECLARE @strClase					AS CHAR(1)

	WHILE @intCounter <= @intRecordCount
		BEGIN

			SELECT @afipcpte_id = afipcpte_id
				FROM (
					SELECT ROW_NUMBER() OVER (ORDER BY (SELECT NULL))	AS rownum, TMP.afipcpte_id
					FROM tbCommercialTransactions_AFIPPurchasesConciliation	AS TMP		WITH (NOLOCK)
					INNER JOIN @tmpAFIPTransactions							AS ta
						ON ta.afipcpte_id = TMP.afipcpte_id
				) AS subquery
				WHERE rownum = @intCounter;


			SELECT
					@afipFecha				 = tctac.afipFecha,
					@afipTIPO				 = dbo.fnStrAllTrim(LOWER(tctac.afipTIPO)),
					@afipPuntoVenta			 = tctac.afipPuntoVenta,
		      		@afipNumeroDesde		 = LTRIM(RTRIM(TRY_CAST(TRY_CAST(dbo.fnStrAllTrim(tctac.afipNumeroDesde) AS BIGINT) AS VARCHAR(20)))),
		      		@afipNumeroHasta		 = tctac.afipNumeroHasta,
		      		@afipCodAutorizacion	 = tctac.afipCodAutorizacion,
		      		@afipTipoDocEmisor		 = tctac.afipTipoDocEmisor,
		      		@afipNumeroDocEmisor	 = dbo.fnStrAllTrim(tctac.afipNumeroDocEmisor),
		      		@afipDenominacionEmisor	 = tctac.afipDenominacionEmisor,
		      		@afipTipoCambio			 = tctac.afipTipoCambio,
		      		@afipMoneda				 = tctac.afipMoneda,
		      		@afipNetoGravado		 = tctac.afipNetoGravado,
		      		@afipNetoNoGravado		 = tctac.afipNetoNoGravado,
		      		@afipExento				 = tctac.afipExento,
		      		@afipOtrosTributos		 = tctac.afipOtrosTributos,
		      		@afipIVA				 = tctac.afipIVA,
		      		@afipTOTAL				 = tctac.afipTOTAL
				FROM tbCommercialTransactions_AFIPPurchasesConciliation AS tctac WITH (NOLOCK)
				WHERE	tctac.comp_id		= @comp_id		AND
						tctac.afipcpte_id	= @afipcpte_id


			SET @intsdId =
				CASE
					WHEN @afipTIPO LIKE '%factura%' THEN 101
					WHEN @afipTIPO LIKE '%crédito%' THEN 103
					WHEN @afipTIPO LIKE '%débito%'  THEN 104
					ELSE -1
				END

			SET @strClase = RIGHT(@afipTIPO, 1)
			SET @ct_transaction = NULL

			SELECT @ct_transaction = tct.ct_transaction
				FROM tbCommercialTransactions	AS tct	WITH (NOLOCK)
				INNER JOIN @tmpBranch			AS tb
					ON	tb.bra_id	= tct.bra_id
				INNER JOIN tbSupplier			AS ts	WITH (NOLOCK)
					ON	ts.comp_id	= tct.comp_id AND
						ts.supp_id	= tct.supp_id
				WHERE	LTRIM(Rtrim(REPLACE(ts.supp_taxNumber,'-',''))) = @afipNumeroDocEmisor	AND
						tct.ct_pointOfSale						= @afipPuntoVenta		AND
						LTRIM(RTRIM(TRY_CAST(TRY_CAST(dbo.fnStrAllTrim(tct.ct_docNumber) AS BIGINT) AS VARCHAR(20)))) = @afipNumeroDesde AND
						-- LTRIM(RTRIM(tct.ct_docNumber))			= @afipNumeroDesde		AND
						tct.ct_kindOf							= @strClase				AND
						tct.sd_id								= @intSDId


			IF	@intsdId > 0				AND
				@ct_transaction IS NOT NULL AND
				@ct_transaction > 0
				BEGIN
					UPDATE tbCommercialTransactions_AFIPPurchasesConciliation
						SET ct_transaction		= @ct_transaction
						WHERE	comp_id			= @comp_id AND
								afipcpte_id		= @afipcpte_id
				END

			SET @intCounter = @intCounter + 1
		END


END
GO







-- MOS, Transacciones Verificadas, NO HACE RETRY
CREATE PROCEDURE [dbo].[spCommercialTransactions_annuApplication]
(
	@comp_id		INT,
	@bra_id			INT,
	@source			INT,
	@destiny		INT,
	@appl_id		INT,
	@return_value	INT OUTPUT
)
AS


BEGIN



	SET NOCOUNT ON

	-- -------------------------------------------------
	-- Testing
	-- -------------------------------------------------
	/*
	DECLARE	@comp_id	INT,	@bra_id		INT,	@source		INT,	@destiny	INT,	@appl_id	INT,	@return_value	INT
	SELECT	@comp_id	=1,		@bra_id		=1,		@source		=1222459,	@destiny	=1222458,	@appl_id	=11701
	*/
	-- -------------------------------------------------


	SET @return_value = 0


	DECLARE @ammount			DECIMAL(19,6),
			@apply_currency		INT,
			@ct_ACurrency		INT,
			@ct_ABalance		DECIMAL(19,6),
			@appl_coef			DECIMAL(38,18),
			@appl_coef_			DECIMAL(38,18)



	DECLARE @intApplId AS INT
	SET		@intApplId = NULL
	/*obtener el monto aplicado y la moneda de la aplicación para actualizar el ABalance de la transacción origen*/
	SELECT	@ammount		= ta.appl_total,
			@apply_currency = ta.appl_currency,
			@appl_coef		= ta.appl_coef,
			@appl_coef_		= ta.appl_coef_,
			@intApplId		= ta.appl_id
		FROM	tbApplication ta			WITH (NOLOCK)
		WHERE	ta.comp_id		= @comp_id
		AND		ta.appl_id		= @appl_id


	-- Por las dudas entre mas de una vez
	IF @intApplId IS NULL
		BEGIN
			SET @return_value = -1
			RETURN
		END


	BEGIN TRANSACTION
	BEGIN TRY


			-- ------------------------------------
			-- Bloquear la base antes de hacer nada
			-- ------------------------------------
			DECLARE @intLock AS INT
			SELECT @intLock = tce.sb_id
				FROM tbsysBlockPage4IsoTran  tce
			-- ------------------------------------


			/*obtener la moneda del cliente de la transacción origen*/
			SELECT	@ct_ACurrency		= tct.ct_ACurrency
				FROM	tbCommercialTransactions tct			WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id
				AND		tct.ct_transaction	= @source




			/*obtener el monto aplicado en la moneda del cliente de la aplicación origen*/
			--SELECT	@ct_ABalance = dbo.fnGetExchange(@comp_id,@ammount,@apply_currency,@ct_ACurrency,0,0,'False')


			-- MOS   28-06-2019, No se porqué se hace esta MIERDA cuando las monedas de la transaccion ( ABALANCE ) siempre sera igual a la del cliente...
			IF @apply_currency = @ct_ACurrency
				BEGIN
					SELECT	@ct_ABalance = @ammount
				END
			ELSE
				BEGIN
					SELECT	@ct_ABalance = dbo.fnGetExchange(@comp_id,@ammount,@apply_currency,@ct_ACurrency,0,0,'False')  -- Viejo, me parece al pedo pero lo dejo x las dudas
				END



			/*sumar el monto aplicado al monto adeudado de la transacción origen*/
			UPDATE	tbCommercialTransactions		WITH (ROWLOCK)
				SET		ct_ABalance		= ct_ABalance +
														(
															CASE
																WHEN ct_ATotal < 0 AND sd_id = 6	THEN (	CASE
																												WHEN @appl_coef > 0 then @ct_ABalance
																												ELSE @ct_ABalance * -1
															                                	      		END) * -1
																ELSE (	CASE
																			WHEN @appl_coef >= 0 then @ct_ABalance
																			ELSE @ct_ABalance * -1
															      		END)
															END
															*
															-- Si es un Recibo de Devolucion...
															CASE
																WHEN ct_aTotal < 0 THEN -1
																ELSE					1
															END
														)
				WHERE	comp_id			= @comp_id	AND
						ct_transaction	= @source








			/*obtener la moneda del cliente de la transacción destino*/
			SELECT	@ct_ACurrency = tct.ct_ACurrency
				FROM	tbCommercialTransactions tct			WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id
				AND		tct.ct_transaction	= @destiny



			/*obtener el monto aplicado en la moneda del cliente de la aplicación destino*/
			--SELECT	@ct_ABalance = dbo.fnGetExchange(@comp_id,@ammount,@apply_currency,@ct_ACurrency,0,0,'False')

			-- MOS   28-06-2019, No se porqué se hace esta MIERDA cuando las monedas de la transaccion ( ABALANCE ) siempre sera igual a la del cliente...
			IF @apply_currency = @ct_ACurrency
				BEGIN
					SELECT	@ct_ABalance = @ammount
				END
			ELSE
				BEGIN
					SELECT	@ct_ABalance = dbo.fnGetExchange(@comp_id,@ammount,@apply_currency,@ct_ACurrency,0,0,'False')
				END




			/*sumar el monto aplicado al monto adeudado de la transacción origen*/
			UPDATE	tbCommercialTransactions	WITH (ROWLOCK)
				SET		ct_ABalance		= ct_ABalance +
														(
															CASE
																-- MOS 05-2023: Para que se tome como recibo de devolucion el 13 y el 106 ademas del 6.!!!
																WHEN ct_ATotal < 0 AND sd_id IN (6,13,106)	THEN (CASE WHEN @appl_coef_ > 0 then @ct_ABalance ELSE @ct_ABalance * -1 END) * -1
																--WHEN ct_ATotal < 0 AND sd_id = 6	THEN (CASE WHEN @appl_coef_ > 0 then @ct_ABalance ELSE @ct_ABalance * -1 END) * -1
																ELSE (	CASE
																			WHEN @appl_coef_ >= 0 then @ct_ABalance
																			ELSE @ct_ABalance * -1
															      		END
																	  )
															END

															*
															-- Si es un Recibo de Devolucion...
															CASE
																WHEN ct_aTotal < 0 THEN -1
																ELSE					1
															END
														 )
				WHERE	comp_id			= @comp_id
				AND		ct_transaction	= @destiny


			/*eliminar la aplicación propiamente dicha*/
			DELETE FROM tbApplication		WITH (ROWLOCK)
				WHERE	comp_id = @comp_id	AND
						appl_id = @appl_id

			-- ---------------------------------------------------------------------------------------------------------------
			-- MOS 02-2020: Se puso esto y se puso (@appl_coef_ >= 0) mas arriba para que al anular recibos
			--				aplicados a varios comprobantes y con ajuste deje correctamente los campos aTotal y aBalance
			--				Quedana antes el saldo bien de la cta pero los atotal y abalance se autocompensaban pero estaban MAL.
			--				lo que podia hacer que en ciertas ocaciones no se puedan anular comprobantes.
			--				NOTA: Se verificó eficacia tanto en clientes como en proveedores, Test Aplica en los dos casos de dbGBP
			-- ---------------------------------------------------------------------------------------------------------------
			IF EXISTS (
								SELECT TOP 1 1
									FROM tbCommercialTransactions AS tct		WITH (NOLOCK)
									WHERE	tct.comp_id			= @comp_id	AND
											tct.ct_transaction	= @destiny	AND
											tct.ct_adjust <> 0				AND
											ABS(tct.ct_ATotal - tct.ct_ABalance) = ABS(tct.ct_adjust)
							)
				BEGIN
					UPDATE tbCommercialTransactions	WITH (ROWLOCK)
						SET		ct_abalance		= (ct_abalance + ct_adjust),
								ct_adjust		= 0
						WHERE	comp_id			= @comp_id AND
								ct_transaction	= @destiny
				END
			-- ---------------------------------------------------------------------------------------------------------------


--SELECT 1 / 0

		COMMIT TRANSACTION


	END
	TRY BEGIN CATCH

		ROLLBACK TRANSACTION
		SET @return_value = -1

	END CATCH



END
GO





-- TRANSACCIONES OK MOS
CREATE PROCEDURE [dbo].[spCommercialTransactions_annuCollPay]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@ct_transaction					INT,
	@user_id						INT,		-- MOS 11-2023
	@return_value					INT				OUTPUT,
	@ret_ErrorCode					INT 			OUTPUT,
	@ret_ErrorDescription			VARCHAR(200)	OUTPUT
)
AS


BEGIN

	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2010-08-18
	-- Parte		: 486
	-- Description	: Se dehabilitan las validaciones para el caso en que es un pago de 'Otros Pagos', que se reconoce si el
	--				  proveedor es el que está informado en la sucursal como proveedor de otros pagos.
	-- =================================================================================================================
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-20
	-- Parte		: 498
	-- Description	: Se cambia el manejo de los cheques emitidos para el caso de Ordenes de pago, como se genera un error
	--				  de FK con el delete se cambia la operatoria a un update
	-- =================================================================================================================


	-- -----------------------------------------------------
	-- Testing
	-- -----------------------------------------------------
	/*
	DECLARE @comp_id					INT,
			@lang_id					INT,
			@bra_id						INT,
			@ct_transaction				INT,
			@return_value				INT,
			@ret_ErrorCode				INT,
			@ret_ErrorDescription		VARCHAR(200)

	SELECT 	@comp_id					=1,
			@lang_id					=2,
			@bra_id						=1,
			@ct_transaction				= 1306014
	*/
	-- -----------------------------------------------------


	Set		@return_value			= 0
	Set		@ret_ErrorCode			= 0
	Set		@ret_ErrorDescription	= ''


    --SAVE TRANSACTION traPROTECT
    --BEGIN TRANSACTION
    BEGIN TRY


			-- ------------------------------------
			-- Bloquear la base antes de hacer nada
			-- ------------------------------------
			DECLARE @intLock AS INT
			SELECT @intLock = tce.sb_id
				FROM tbsysBlockPage4IsoTran  tce
			-- ------------------------------------



	/************************************************************************************************/
	/* recuperación de la fecha de proceso, fecha actual e indicación de Cobranza o Pago            */
	DECLARE @bra_processingDate		DATETIME,
			@new_ct_transaction		INT,
			@isPayment				BIT,
			@bra_PaymentSupp_Id		INT,					--Parte:486
			@supp_id				INT						--Parte:486


	SELECT	@bra_processingDate		=	tb.bra_processingDate,
			@bra_PaymentSupp_Id		=	ISNULL(tb.bra_PaymentSupp_Id,-1)	--Parte:486
	FROM	tbBranch					tb		WITH (NOLOCK)
	WHERE	tb.comp_id				=	@comp_id
	AND		tb.bra_id				=	@bra_id


	DECLARE @actual_date			DATETIME
	--SET		@actual_date			=  GETDATE()   NOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOO
	select @actual_date = tb.bra_processingDate
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id


	SELECT	@isPayment				=	td.sd_isPurchase,
			@supp_id				=	ISNULL(tct.supp_id,-1)				--Parte:486
	FROM	tbCommercialTransactions	tct		WITH (NOLOCK)
			INNER JOIN tbsysDocuments	td		WITH (NOLOCK)
			ON td.sd_id				=	tct.sd_id
	WHERE	tct.comp_id				=	@comp_id
	AND		tct.ct_transaction		=	@ct_transaction
	--SELECT	@isPayment
	/************************************************************************************************/




	-- Si el PERIODO CONTABLE esta CERRADO, NO debe permitir anular el recibo u OP
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbAccountTransactionDetail		AS tatd		WITH (NOLOCK)
					INNER JOIN tbAccountTransactionHead AS tath		WITH (NOLOCK)
						ON	tath.comp_id			= tatd.comp_id AND
							tath.hacc_transaction	= tatd.hacc_transaction
					INNER JOIN tbAccountantPeriod		AS tap		WITH (NOLOCK)
						ON	tap.comp_id				= tath.comp_id AND
							tap.ap_id				= tath.ap_id
					WHERE	tatd.comp_id		= @comp_id			AND
							tatd.ct_transaction = @ct_transaction	AND
							(
								tath.hacc_blocked	= 'True'
									OR
								tath.hacc_closing	= 'True'
									OR
								tap.ap_closed		= 'True'
									OR
								tap.ap_blocked		= 'True'
							)
			 	)
		BEGIN
			SET 	@ret_ErrorCode			= -36
			SET		@return_value			= -36

			-- El comprobante seleccionado no se puede anular porque el Período Contable esta CERRADO o BLOQUEADO.
			SELECT 	@ret_ErrorDescription = utexts_desc
				FROM 	dbo.tbsysUniqueTexts		WITH (NOLOCK)
				WHERE 	lang_id	= @lang_id and utexts_id = 135

			--IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION traPROTECT
			RETURN
		END


	-- Si el ASIENTO CONTABLE esta CERRADO o BLOQUEADO, NO debe permitir anular el recibo u OP
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbAccountTransactionDetail		AS tatd		WITH (NOLOCK)
					INNER JOIN tbAccountTransactionHead AS tath		WITH (NOLOCK)
						ON	tath.comp_id			= tatd.comp_id AND
							tath.hacc_transaction	= tatd.hacc_transaction
					WHERE	tatd.comp_id		= @comp_id			AND
							tatd.ct_transaction = @ct_transaction	AND
							(
								tath.hacc_blocked	= 'True'
									OR
								tath.hacc_closing	= 'True'
							)
			 	)
		BEGIN
			SET 	@ret_ErrorCode			= -36
			SET		@return_value			= -36

			-- El comprobante seleccionado no se puede anular porque el Período Contable esta CERRADO o BLOQUEADO.
			SELECT 	@ret_ErrorDescription = utexts_desc
				FROM 	dbo.tbsysUniqueTexts		WITH (NOLOCK)
				WHERE 	lang_id	= @lang_id and utexts_id = 135

			--IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION traPROTECT
			RETURN
		END



	/* Parte:486, si los valores comparados son diferentes significa que no es un pago generado por otros pagos */
	IF @bra_PaymentSupp_Id <> @supp_id		--Parte:486
		BEGIN

			-- ----------------------------------------------------
			-- -- era 0.01 MOS 06-2017  **wejhfweqjn897
			-- ----------------------------------------------------
			DECLARE @decAdjustByError AS DECIMAL(19,6)
			SET		@decAdjustByError = 0
			IF EXISTS(

				SELECT TOP 1	1
					FROM	tbCommercialTransactions				tct		WITH (NOLOCK)
					WHERE	tct.comp_id				=	@comp_id
					AND		tct.ct_transaction		=	@ct_transaction
					AND		(ABS(tct.ct_ATotal - isnull(tct.ct_AAdjust,0) - tct.ct_ABalance) > 0.01)
					AND		(ABS(tct.ct_ATotal - isnull(tct.ct_AAdjust,0) - tct.ct_ABalance) < 1)

					)
				BEGIN

					SELECT	@decAdjustByError =  (ct_ATotal - isnull(ct_AAdjust,0) - ct_ABalance)
						FROM	tbCommercialTransactions				tct		WITH (NOLOCK)
						WHERE	tct.comp_id				=	@comp_id
						AND		tct.ct_transaction		=	@ct_transaction
						AND		(ABS(tct.ct_ATotal - isnull(tct.ct_AAdjust,0) - tct.ct_ABalance) > 0.01)
						AND		(ABS(tct.ct_ATotal - isnull(tct.ct_AAdjust,0) - tct.ct_ABalance) < 1)


					UPDATE tbCommercialTransactions
						SET ct_adjust = ct_adjust + @decAdjustByError
						WHERE	comp_id				=	@comp_id
						AND		ct_transaction		=	@ct_transaction
				END
			-- ----------------------------------------------------




			/************************************************************************************************/
			--01-	Debe estar des-aplicado, o sea, a_total y a_balance deben ser iguales.
			IF NOT EXISTS	(
								SELECT TOP 1 	1
								FROM	tbCommercialTransactions				tct		WITH (NOLOCK)
								WHERE	tct.comp_id				=	@comp_id
								AND		tct.ct_transaction		=	@ct_transaction
								AND		(ABS(tct.ct_ATotal - isnull(tct.ct_AAdjust,0) - tct.ct_ABalance) <= 0.3  /* MOS 05-2022: era 0.01*/)
										--CONVERT(DECIMAL(18,2),tct.ct_ATotal) =
										--(CONVERT(DECIMAL(18,2),tct.ct_ABalance) + CONVERT(DECIMAL(18,2),tct.ct_AAdjust))
							)
			BEGIN

				SET 	@ret_ErrorCode			= -10
				SET		@return_value			= -10


				SELECT 	@ret_ErrorDescription = utexts_desc +
												'<br><b>[' +
												CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),tct.ct_ATotal	 ))	+ '] <> [(' +
												CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),tct.ct_ABalance))	+ ')+(' +
												CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),tct.ct_AAdjust ))	+ ')]</b>'
				FROM 	dbo.tbsysUniqueTexts		WITH (NOLOCK)
						inner join tbCommercialTransactions				tct		WITH (NOLOCK)
						ON 		tct.comp_id				=	@comp_id
						AND		tct.ct_transaction		=	@ct_transaction

				WHERE 	lang_id	= @lang_id and utexts_id = 131

				--IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION traPROTECT
				RETURN

			END
			/************************************************************************************************/



			/************************************************************************************************/
			--02-	Si hay algún chp_id con IsPayed en TRUE o con movimientos en tbChequePortfolioMovements
			--	NO se puede Anular
			IF  @isPayment = 'False' -- COBRANZA
				BEGIN

					IF EXISTS (	SELECT TOP 1 	1
       							FROM	tbCommercialTransactions					tct		WITH (NOLOCK)

       									INNER JOIN tbCheckPortfolio					tcp1		WITH (NOLOCK)
       									ON	tcp1.comp_id		=	tct.comp_id
       									AND tcp1.ct_transaction	=	tct.ct_transaction
       									AND tcp1.chp_IsPayed	=	'True'

       									INNER JOIN tbCheckPortfolioMovements		tcpm		WITH (NOLOCK)
       									ON	tcpm.comp_id		=	tct.comp_id
       									AND tcpm.bra_id			=	tct.bra_id
       									AND tcpm.chp_id			=	tcp1.chp_id

								WHERE	tct.comp_id				=	@comp_id
								AND		tct.ct_transaction		=	@ct_transaction

								UNION

								SELECT	1
       							FROM	tbCommercialTransactions					tct		WITH (NOLOCK)

       									INNER JOIN tbCheckPortfolio					tcp1		WITH (NOLOCK)
       									ON	tcp1.comp_id		=	tct.comp_id
       									AND tcp1.ct_transaction	=	tct.ct_transaction
       									AND tcp1.chp_isAvailable	=	'false'

								WHERE	tct.comp_id				=	@comp_id
								AND		tct.ct_transaction		=	@ct_transaction	)
					BEGIN

						SET 	@ret_ErrorCode			= -20
						SET		@return_value			= -20

						SELECT 	@ret_ErrorDescription = utexts_desc
							FROM 	dbo.tbsysUniqueTexts		WITH (NOLOCK)
						WHERE 	lang_id	= @lang_id and utexts_id = 132

						--IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION traPROTECT
						RETURN

					END

				END
			/************************************************************************************************/



			/************************************************************************************************/
			--03-	Si hay algún ec_id con IsPayed en TRUE, no se puede anular.
			IF EXISTS (	SELECT TOP 1 	1
       					FROM	tbCommercialTransactions					tct		WITH (NOLOCK)
       							INNER JOIN tbEmmitedChecksMovements			tecm		WITH (NOLOCK)
       							ON	tecm.comp_id		=	tct.comp_id
       							AND tecm.bra_id			=	tct.bra_id
       							AND tecm.ct_transaction	=	tct.ct_transaction
       							INNER JOIN tbEmmitedChecks					tec		WITH (NOLOCK)
       							ON	tec.comp_id			=	tct.comp_id
       							AND tec.ec_id			=	tecm.ec_id
       							AND tec.ec_isPaid		=	'True'
						WHERE	tct.comp_id				=	@comp_id
						AND		tct.ct_transaction		=	@ct_transaction	)
				BEGIN

					SET 	@ret_ErrorCode			= -30
					SET		@return_value			= -30

					SELECT 	@ret_ErrorDescription = utexts_desc
						FROM 	dbo.tbsysUniqueTexts		WITH (NOLOCK)
						WHERE 	lang_id	= @lang_id and utexts_id = 133

					--IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION traPROTECT
					RETURN

				END
			/************************************************************************************************/







			/************************************************************************************************/
			--04-	Si es una cobranza, además se debe verificar que si tiene cupones de t.credito (ccm_id),
			--	hay que ver si tbCreditCardMovements isPayed este en false
			IF EXISTS (	SELECT TOP 1 	1
       					FROM	tbCommercialTransactions					tct		WITH (NOLOCK)
       							INNER JOIN tbsysDocuments					td		WITH (NOLOCK)
								ON	td.sd_id			=	tct.sd_id
								AND td.sd_isSales		=	'True'
								AND td.sd_isCredit		=	'True'
								AND td.sd_isReceipt		=	'True'
								INNER JOIN tbCreditCardMovements			tccm		WITH (NOLOCK)
								ON	tccm.comp_id		=	tct.comp_id
								AND tccm.bra_id			=	tct.bra_id
								AND tccm.ct_transaction	=	tct.ct_transaction
								AND tccm.ccm_isPayed	=	'True'
						WHERE	tct.comp_id				=	@comp_id
						AND		tct.ct_transaction		=	@ct_transaction	)
			BEGIN

				SET 	@ret_ErrorCode			= -40
				SET		@return_value			= -40

				SELECT 	@ret_ErrorDescription = utexts_desc
				FROM 	dbo.tbsysUniqueTexts
				WHERE 	lang_id	= @lang_id and utexts_id = 134

				--IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION traPROTECT
				RETURN

			END
			/************************************************************************************************/


		END



	--05-	Se debe generar un nuevo ct_transaction y cambiar el sd_id del ct_transaction original
	--		según lo siguiente:  106->156 y 166   y 6->56 y 66 y 13->56 y 66
	--		el 13 tratalo como si fuese un 6
	/************************************************************************************************/
	/* actualización de sd_id de tbCommercialTransactions                                           */
	UPDATE	tbCommercialTransactions
	SET		sd_id				=	CASE
										WHEN sd_id = 13 THEN 6
										ELSE sd_id
	   		     				 	END + 50,
			ct_ABalance			=	CONVERT(DECIMAL(19,6),0)
	FROM	tbCommercialTransactions
	WHERE	comp_id				=	@comp_id
	AND		ct_transaction		=	@ct_transaction
	/************************************************************************************************/


	-- --------------------------------------------------------------------------------
	-- Si la cobranza tenia asociada algun voucher, lo vuelve a poner como disponible.-
	-- --------------------------------------------------------------------------------
	UPDATE tbBankingVouchers4BanckTransferCollection
	SET
		v4c_transactionNumber = NULL,
		v4c_isCollected = 'False',
		v4c_isCancelled = 'False'
	WHERE	comp_id			= @comp_id			AND
			ct_transaction	= @ct_transaction
	-- --------------------------------------------------------------------------------




	/************************************************************************************************/
	/* agregar la transacción relacionada a la anulación                                            */
	INSERT INTO tbCommercialTransactions
	(
	comp_id,				bra_id,										ct_pointOfSale,				ct_kindOf,
	ct_docNumber,			ct_date,			ct_taxDate,				ct_payDate,					supp_id,
	cust_id,				ba_id,				cb_id,					[user_id],					ct_cd,
	ct_subtotal,			ct_total,			ct_discount,			ct_adjust,					ct_taxes,
	curr_id_transaction,	hacc_transaction,	sm_id,					disc_id,					ct_ATotal,
	ct_ABalance,			ct_ACurrency,		ct_ACurrencyExchange,	df_id,						dl_id,
	st_id,					sd_id,				puco_id,				ct_CompanyCurrency,			ct_Branch2CompanyCurrencyExchange,
	ct_Pending,				country_id,			state_id,				ct_isAvailableForImport,	ct_soh_bra_id,
	ct_soh_id,				ct_CAI,				ct_CAIDate,				ct_isAvailableForPayment
	)
	SELECT
		comp_id,				bra_id,										ct_pointOfSale,				ct_kindOf,
		ct_docNumber,			@bra_processingDate,ct_taxDate,				ct_payDate,					supp_id,
		cust_id,				ba_id,				cb_id,					@user_id,					GETDATE() /*;MOS 11-2023@actual_date*/,
		ct_subtotal,			ct_total,			ct_discount,			ct_adjust,					ct_taxes,
		curr_id_transaction,	hacc_transaction,	sm_id,					disc_id,					ct_ATotal,
		ct_ABalance - ISNULL(@decAdjustByError,0),  -- **wejhfweqjn897
													ct_ACurrency,		ct_ACurrencyExchange,	df_id,						dl_id,
		st_id,					sd_id + 10,			puco_id,				ct_CompanyCurrency,			ct_Branch2CompanyCurrencyExchange,
		ct_Pending,				country_id,			state_id,				ct_isAvailableForImport,	ct_soh_bra_id,
		ct_soh_id,				ct_CAI,				ct_CAIDate,				ct_isAvailableForPayment
		FROM	tbCommercialTransactions		WITH (NOLOCK)

		WHERE	comp_id				=	@comp_id
		AND		ct_transaction		=	@ct_transaction


	SET @new_ct_transaction = @@IDENTITY
	/************************************************************************************************/





	/************************************************************************************************/
	/* agregar aplicación de la transaccion original con la nueva que es el contramovimiento        */
	INSERT INTO tbApplication
	(
			comp_id,					bra_id,
			ct_transaction_Source,		ct_transaction_destiny,
			appl_currency,				appl_total,
			appl_coef,					appl_coef_,
			appl_excdifchecked,			ct_transaction
	)
	SELECT
			@comp_id,					@bra_id,
			@ct_transaction,			@new_ct_transaction,
			tct.curr_id_transaction,	tct.ct_total,
			CONVERT(DECIMAL(18,6),100), CONVERT(DECIMAL(18,6),100),
			'False',					@ct_transaction

	FROM	tbCommercialTransactions				tct		WITH (NOLOCK)
	WHERE	tct.comp_id			= @comp_id
	AND		tct.ct_transaction	= @ct_transaction
	/************************************************************************************************/





	--06-Las imputaciones en tbCashMovement, tbMoneyMovement, tbBankingTransacions, etc. Se deben
	--	 insertar con el nuevo ct_transaction pero invertidos
	INSERT INTO tbCashMovements
	(
		comp_id,		bra_id,			cm_cd,			ca_id,
		cm_debit,		cm_credit,		curr_id,		cm_desc,		cn_id,
		ct_transaction,					svt_id,			cm_BranchCurrencyExchange
	)
	SELECT
		tcm.comp_id,	tcm.bra_id,		@actual_date,	tcm.ca_id,
		tcm.cm_credit,	tcm.cm_debit,	tcm.curr_id,	tcm.cm_desc,	tcm.cn_id,
		@new_ct_transaction,			tcm.svt_id,		tcm.cm_BranchCurrencyExchange
	FROM	tbCashMovements				tcm		WITH (NOLOCK)
	WHERE	tcm.comp_id			=	@comp_id
	--AND		tcm.bra_id			=	@bra_id
	AND		tcm.ct_transaction	=	@ct_transaction



	INSERT INTO tbMoneyMovements
	(
		comp_id,		bra_id,			ct_transaction,			mm_total,
		curr_id,		mm_BranchCurrencyExchange,				mm_isCancelled,		svtt_id
	)
	SELECT
		tmm.comp_id,	tmm.bra_id,		@new_ct_transaction,	tmm.mm_total,
		tmm.curr_id,	tmm.mm_BranchCurrencyExchange,			tmm.mm_isCancelled, tmm.svtt_id
	FROM	tbMoneyMovements			tmm		WITH (NOLOCK)
	WHERE	tmm.comp_id			=	@comp_id
	--AND		tmm.bra_id			=	@bra_id
	AND		tmm.ct_transaction	=	@ct_transaction




	INSERT INTO tbBankingTransactions
	(
		comp_id,		ba_id,			bra_id,
		btt_id,
		ec_id,
		chp_id,			bt_total,		curr_id,		bt_imputationDate,
		bt_isConciliated,				bt_isCancelled,					ct_transaction,
		ccm_id,			bt_note,		bt_Number,		bt_BranchCurrencyExchange
	)
	SELECT
		tbt.comp_id,	tbt.ba_id,		tbt.bra_id,

		/********************************************************************************************/
		--Ticket : 399 - MOH
		CASE
			WHEN tbt.btt_id = 1000001 THEN 1000010
			WHEN tbt.btt_id = 1000008 THEN 1000009
			ELSE tbt.btt_id
		END,
		/********************************************************************************************/

		tbt.ec_id,
		tbt.chp_id,		tbt.bt_total,	tbt.curr_id,	tbt.bt_imputationDate,
		tbt.bt_isConciliated,			tbt.bt_isCancelled,				@new_ct_transaction,
		tbt.ccm_id,		tbt.bt_note,	tbt.bt_Number,	tbt.bt_BranchCurrencyExchange
	FROM	tbBankingTransactions		tbt		WITH (NOLOCK)
	WHERE	tbt.comp_id			=	@comp_id
	--AND		tbt.bra_id			=	@bra_id
	AND		tbt.ct_transaction	=	@ct_transaction




	--08-	Para la anulación de  un ccm_id, BORRARLO de tbCreditCardMovements.
	--SELECT	'6',*
	--FROM	tbCreditCardMovements		tccm

	-- MercadoPoint
	-- Lo pone NUEVAMENTE como DISPONIBLE
	UPDATE tbCreditCard_Voucher						WITH (ROWLOCK)
		SET	ccv_status = 4
		FROM tbCreditCard_Voucher			vou
		INNER JOIN tbCreditCardMovements	ccm		WITH (NOLOCK)
			ON	ccm.comp_id			= vou.comp_id AND
				ccm.ccv_id			= vou.ccv_id
		WHERE	ccm.comp_id			= @comp_id	AND
				ccm.ct_transaction	= @ct_transaction


	-- Borra la Tarjeta de credito ingresada.
	DELETE FROM tbCreditCardMovements		WITH (ROWLOCK)
		WHERE	comp_id			=	@comp_id	AND
				ct_transaction	=	@ct_transaction




	--07-	El Asiento contable se debe anular igual que como se hizo con el de facturas de compras.
	/************************************************************************************************/
	/* actualización del asiento contable con los contramovimientos de la transacción original      */
	--SELECT '7'
	INSERT INTO tbAccountTransactionDetail
	(
		comp_id,			bra_id,				hacc_transaction,
		acc_count_id,		cc_code,			dacc_debit,				dacc_credit,
		[user_id],			dacc_cd,			hacc_software,			ct_transaction,
		acc_detail1,		acc_detail2,		dacc_order,				dacc_2ndCurrencyExchange
	)
	SELECT
		comp_id,			bra_id,				hacc_transaction,
		acc_count_id,		cc_code,			dacc_credit,			dacc_debit,
		@user_id,			@actual_date,		hacc_software,			@new_ct_transaction,
		acc_detail1,		acc_detail2,		dacc_order,				dacc_2ndCurrencyExchange
	FROM	tbAccountTransactionDetail		WITH (NOLOCK)
	WHERE	comp_id			=	@comp_id
	--AND		bra_id			=	@bra_id
	AND		ct_transaction	=	@ct_transaction
	/************************************************************************************************/



	IF @isPayment = 'True'
		BEGIN

			--09-	Si es una OP, y hay un chp_id, ya que se pago con un valor de terceros, se debe poner el campo
			--		isAvailable en true y el isPayed en False en tbCheckPortfolio y borrar su tbChequePortfolioMovements
			UPDATE 	tbCheckPortfolio
			SET		chp_isAvailable		=	'True',
					chp_IsPayed			=	'False'
			WHERE	comp_id		=	@comp_id
			AND		chp_id IN	(
								SELECT	tcpm.chp_id
								FROM	tbCheckPortfolioMovements tcpm		WITH (NOLOCK)
								WHERE	tcpm.comp_id		=	@comp_id
								--AND		tcpm.bra_id			=	@bra_id
								AND		tcpm.ct_transaction	=	@ct_transaction
								)


			DELETE FROM tbCheckPortfolioMovements
			WHERE	comp_id			=	@comp_id
			--AND		bra_id			=	@bra_id
			AND		ct_transaction	=	@ct_transaction



			--************************************************************************************************
			-- 2010-08-20 - MOH - Parte 498 (ver detalle arriba)
			--************************************************************************************************
			UPDATE  tbEmmitedChecks
			SET		ec_Total		= 0,
					ec_isCancelled	= 'True',
					ec_isPaid		= 'False'
			WHERE	comp_id			=	@comp_id
			--AND		bra_id			=	@bra_id
			AND		ct_transaction	=	@ct_transaction

			--10-	Si es un ec_id en una OP, BORRARLO de tbemmitedCheques
			--DELETE 	FROM	tbEmmitedChecks
			--WHERE		comp_id			=	@comp_id
			--AND		bra_id			=	@bra_id
			--AND		ct_transaction	=	@ct_transaction
			--************************************************************************************************


		END
	ELSE
		BEGIN


			--SI EXISTEN, BORRAR DE tbBankingTransaction también?


		/*
			DELETE	FROM tbCheckPortfolioMovements
			WHERE	comp_id	=	@comp_id
			AND		bra_id	=	@bra_id
			AND		chp_id 	IN	(	SELECT	chp_id
	   		       	  				FROM	tbCheckPortfolio
									WHERE	comp_id			=	@comp_id
									AND		ct_transaction	=	@ct_transaction		)


			--11-	Si es un chp_id en Cobranzas, Borrarlo de tbChequePortfolio
			DELETE 	FROM	tbCheckPortfolio
			WHERE	comp_id			=	@comp_id
			AND		ct_transaction	=	@ct_transaction
		*/

			UPDATE	tbCheckPortfolio

			SET		chp_number			= '(' + LTRIM(RTRIM(chp_number)) + ')',
					chp_originalTotal	= chp_total,
					chp_total			= 0,
					chp_isCancelled		= 'true',
					chp_isAvailable		= 'false',
					chp_Note			= 'RC Anulado -' + chp_Note

			WHERE	comp_id			= @comp_id
			AND		ct_transaction	= @ct_transaction





		END


		 UPDATE tbTaxMovements

		 SET	tm_subtotal		= 0,
 				tm_total		= 0

		 WHERE	comp_id			= @comp_id
		 --AND	bra_id			= @bra_id
		 AND	ct_transaction	= @ct_transaction



--SELECT 1 / 0


    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT


END



GO




-- TRANSACCIONES OK MOS
CREATE PROCEDURE [dbo].[spCommercialTransactions_Annulment]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@ct_transaction					INT,
	@user_id						INT,		-- MOS 11-2023
	@return_value					INT				OUTPUT,
	@ret_ErrorCode					INT 			OUTPUT,
	@ret_ErrorDescription			VARCHAR(200)	OUTPUT
)
AS

BEGIN



	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-01-18
	-- Parte		: 771
	-- Description	: Si es una factura de un proveedor se deben eliminar los seriales generados cuando se ingresó el
	--				  comprobante
	-- =================================================================================================================
	SET NOCOUNT ON

	-- ---------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------
	/*
	DECLARE @comp_id					INT,
			@lang_id					INT,
			@bra_id						INT,
			@ct_transaction				INT,
			@return_value				INT,
			@ret_ErrorCode				INT,
			@ret_ErrorDescription		VARCHAR(200)

	SELECT 	@comp_id					= 1,
			@lang_id					= 2,
			@bra_id						= 1,
			@ct_transaction				= 3819
	*/
	-- ---------------------------------------------------------


	Set		@return_value			= 0
	Set		@ret_ErrorCode			= 0
	Set		@ret_ErrorDescription	= ''



    --SAVE TRANSACTION traPROTECT
    --BEGIN TRANSACTION  Si ya tiene una transaccion abierta solo grabar el SavePoint
    BEGIN TRY


	-- COntrola si ya existe.
	IF EXISTS(
				SELECT TOP 1  1
					FROM tbCommercialTransactions tct WITH (NOLOCK)
					WHERE	tct.comp_id			= @comp_id			AND
							tct.ct_transaction	= @ct_transaction	AND
							tct.sd_id NOT IN (1, 3, 4, 101, 103, 104, 102, 130)
			)
		BEGIN
			Set		@return_value			= -58
			Set		@ret_ErrorCode			= -58
			Select	@ret_ErrorDescription	= tut.utexts_desc
				FROM tbsysUniqueTexts tut WITH (NOLOCK) WHERE tut.lang_id = @lang_id AND tut.utexts_id = 353
			Return
		END


		-- Recuperar aca en variables datos para no hacer al PEDO 1000 busquedas... no sean HDP !!!
		DECLARE @sd_id AS INT
		SELECT  @sd_id	= tct.sd_id,
				@bra_id = tct.bra_id  -- MOS, por cosas del reverendo hijo de recontra mil putas
			FROM tbCommercialTransactions tct			WITH (NOLOCK)
			WHERE	tct.comp_id			= @comp_id AND
					tct.ct_transaction	= @ct_transaction




		-- ---------------------------------------------------
		-- recuperación de la fecha de proceso
		-- ---------------------------------------------------
		DECLARE @bra_processingDate DATETIME,
				@new_ct_transaction INT,
				@bra_PurDoc_Anullment_disableCheckAbailableStatus AS BIT
		SELECT	@bra_processingDate	= tb.bra_processingDate,
				@bra_PurDoc_Anullment_disableCheckAbailableStatus = isnull(tb.bra_PurDoc_Anullment_disableCheckAbailableStatus,'False')
			FROM	tbBranch							tb		WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id
			AND		tb.bra_id	= @bra_id
		-- ---------------------------------------------------






			-- ------------------------------------
			-- Bloquear la base antes de hacer nada
			-- ------------------------------------
			DECLARE @intLock AS INT
			SELECT @intLock = tce.sb_id
				FROM tbsysBlockPage4IsoTran  tce
			-- ------------------------------------



		/************************************************************************************************/
		/* Validando que el comprobante seleccionado sea el correspondiente								*/
		IF EXISTS (	SELECT TOP 1 	1
						FROM	tbCommercialTransactions tct
						WHERE	tct.comp_id			=	@comp_id
						AND		tct.bra_id			=	@bra_id
						AND		tct.ct_transaction	=	@ct_transaction
						AND		tct.sd_id			NOT IN (101,102,103,104,130))
		BEGIN

			SET 	@ret_ErrorCode			= -3
			SET		@return_value			= -3

			SELECT 	@ret_ErrorDescription = utexts_desc
			FROM 	dbo.tbsysUniqueTexts					WITH (NOLOCK)
			WHERE 	lang_id	= @lang_id and utexts_id = 112

			--IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION traPROTECT
			RETURN

		END
		/************************************************************************************************/










		/************************************************************************************************/
		/* Validación que el saldo sea igual al total del comprobante                                   */
		IF EXISTS (	SELECT TOP 1 	1
						FROM	tbCommercialTransactions tct		WITH (NOLOCK)
						WHERE	tct.comp_id			=	@comp_id
						--AND		tct.bra_id			=	@bra_id
						AND		tct.ct_transaction	=	@ct_transaction
						AND		abs(tct.ct_ATotal -	tct.ct_ABalance) > 0.04)
		BEGIN

			SET 	@ret_ErrorCode			= -1
			SET		@return_value			= -1

			SELECT 	@ret_ErrorDescription = utexts_desc
				FROM 	dbo.tbsysUniqueTexts						WITH (NOLOCK)
				WHERE 	lang_id	= @lang_id and utexts_id = 110

			--IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION traPROTECT
			RETURN

		END
		/************************************************************************************************/





		/************************************************************************************************/
		/* Validando que las cantidades de lo ítems ingresados no hayan sido tomados                    */
		IF	@bra_PurDoc_Anullment_disableCheckAbailableStatus = 'False' AND
			EXISTS (	SELECT	1
							FROM	tbItemTransactions						tit		WITH (NOLOCK)
									INNER JOIN tbImportData					tid		WITH (NOLOCK)
									ON	tid.comp_id				=	tit.comp_id
									AND tid.bra_id				=	tit.bra_id
									AND tid.ct_transaction		=	tit.ct_transaction
									AND tid.it_transaction		=	tit.it_transaction
									AND tid.impData_InitialQty	<>	tid.impData_ActualQty
							WHERE	tit.comp_id					=	@comp_id
							--AND		tit.bra_id					=	@bra_id
							AND		tit.ct_transaction			=	@ct_transaction)
		BEGIN

			SET 	@ret_ErrorCode			= -2
			SET		@return_value			= -2

			SELECT 	@ret_ErrorDescription = utexts_desc
				FROM 	dbo.tbsysUniqueTexts				WITH (NOLOCK)
				WHERE 	lang_id	= @lang_id and utexts_id = 111

   		    --ROLLBACK TRANSACTION traPROTECT
			RETURN

		END
		/************************************************************************************************/



		-- Hay Numeros de Serie Utilizados . . .
		IF  @bra_PurDoc_Anullment_disableCheckAbailableStatus = 'False' AND
			@sd_id >= 100 AND
			EXISTS (	SELECT TOP 1 1
						FROM tbItemSerials tis	WITH (NOLOCK)
						WHERE	tis.comp_id					= @comp_id			AND
								tis.ct_transaction			= @ct_transaction	AND
							(
								tis.is_available			= 'True'
							or	isnull(tis.is_serial,'')	<> ''
							)
					)
			BEGIN

				SET 	@ret_ErrorCode			= -2
				SET		@return_value			= -2

				SELECT 	@ret_ErrorDescription = utexts_desc
					FROM 	dbo.tbsysUniqueTexts				WITH (NOLOCK)
					WHERE 	lang_id	= @lang_id and utexts_id = 113

				RETURN

			END


		-- Si ya es FACTURA convertida desde el remito originado por la recepcion de una OC NO permite anularla.
		IF	@sd_id = 101 AND
			EXISTS(
			SELECT TOP 1 1
				FROM tbItemTransactions tit
				INNER JOIN tbPurchaseorderReceptionDetail tprd	WITH (NOLOCK)
					ON	tprd.comp_id	= @comp_id			AND
						tprd.poh_bra_id = tit.it_poh_bra_id AND
						tprd.poh_id		= tit.it_poh_id		AND
						tprd.pod_id		= tit.it_pod_id
				WHERE	tit.comp_id			= @comp_id		AND
						tit.ct_transaction	= @ct_transaction
			)
			BEGIN
				SET 	@ret_ErrorCode			= -2
				SET		@return_value			= -2

				SELECT 	@ret_ErrorDescription = utexts_desc
					FROM 	dbo.tbsysUniqueTexts				WITH (NOLOCK)
					WHERE 	lang_id	= @lang_id and utexts_id = 114

				RETURN
			END



		-- Si  es REMITO que tiene una FACTURA asociada tampoco lo permite.
		IF	@sd_id = 102 AND
			EXISTS(
			SELECT TOP 1  1
				FROM tbItemTransactions tit	WITH (NOLOCK)
				INNER JOIN tbItemTransactions tit2	WITH (NOLOCK)
					ON	tit2.comp_id					= tit.comp_id		AND
						tit2.it_transaction_original	= tit.it_transaction
				INNER JOIN tbCommercialTransactions tct	WITH (NOLOCK)
					ON	tct.comp_id = tit2.comp_id				AND
						tct.ct_transaction = tit2.ct_transaction
				-- Lo saco MOS en 03-2017, no se usa para nada y caga la verificacion !!!!!!
				-- NO se que mierda tiene que ver si esta recibido o no con esto...
				-- La idea es que si tiene asociada una FACTURA NO PERMITA ANUILARLO, primero hay q anular la re puta factura !!!
				--INNER JOIN tbPurchaseorderReceptionDetail tprd
				--	ON	tprd.comp_id	= @comp_id				AND
				--		tprd.poh_bra_id = tit2.it_poh_bra_id	AND
				--		tprd.poh_id		= tit2.it_poh_id		AND
				--		tprd.pod_id		= tit2.it_pod_id
				WHERE	tit.comp_id			= @comp_id			AND
						tit.ct_transaction	= @ct_transaction	AND
						tct.sd_id			= 101
			)
			BEGIN
				SET 	@ret_ErrorCode			= -2
				SET		@return_value			= -2

				SELECT 	@ret_ErrorDescription = utexts_desc
					FROM 	dbo.tbsysUniqueTexts				WITH (NOLOCK)
					WHERE 	lang_id	= @lang_id and utexts_id = 115

				RETURN
			END





		-- MOS 09-2023: Si el PERIODO CONTABLE esta CERRADO, NO debe permitir anular
		IF EXISTS(
					SELECT TOP 1 1
						FROM tbAccountTransactionDetail		AS tatd		WITH (NOLOCK)
						INNER JOIN tbAccountTransactionHead AS tath		WITH (NOLOCK)
							ON	tath.comp_id			= tatd.comp_id AND
								tath.hacc_transaction	= tatd.hacc_transaction
						WHERE	tatd.comp_id		= @comp_id			AND
								tatd.ct_transaction = @ct_transaction	AND
								(
									tath.hacc_blocked	= 'True'
										OR
									tath.hacc_closing	= 'True'
								)
			 	 )
			BEGIN
				SET 	@ret_ErrorCode			= -36
				SET		@return_value			= -36

				-- El comprobante seleccionado no se puede anular porque el Período Contable esta CERRADO o BLOQUEADO.
				SELECT 	@ret_ErrorDescription = utexts_desc
					FROM 	dbo.tbsysUniqueTexts		WITH (NOLOCK)
					WHERE 	lang_id	= @lang_id and utexts_id = 135

				--IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION traPROTECT
				RETURN
			END






		-- Si es REMITO originado por la recepcion de una OC marca pada dejar anulada la recepcion
		DECLARE @bitSetPurchaseReceptionAsAnnuled AS BIT
		SET		@bitSetPurchaseReceptionAsAnnuled = 'False'
		DECLARE @por_id AS INT
		SET		@por_id = NULL
		IF	@sd_id = 102
			BEGIN
				SELECT @por_id = tprd.por_id
					FROM tbItemTransactions tit
					INNER JOIN tbPurchaseorderReceptionDetail tprd	WITH (NOLOCK)
						ON	tprd.comp_id	= @comp_id AND
							tprd.poh_id		= tit.it_poh_id AND
							tprd.pod_id		= tit.it_pod_id
					WHERE	tit.comp_id			= @comp_id AND
							tit.ct_transaction	= @ct_transaction
					IF @por_id IS NOT NULL
						BEGIN
							set @bitSetPurchaseReceptionAsAnnuled = 'True'
						END
			END

















		DECLARE @actual_date	DATETIME,
				@sd_isCredit	BIT

		SET		@actual_date		=  @bra_processingDate

		SELECT	@sd_isCredit		=	td.sd_isCredit
			FROM	tbCommercialTransactions						WITH (NOLOCK)
					INNER JOIN tbsysDocuments td					WITH (NOLOCK)
					ON td.sd_id = tbCommercialTransactions.sd_id
			WHERE	comp_id				=	@comp_id
			--AND		bra_id				=	@bra_id
			AND		ct_transaction		=	@ct_transaction







		/************************************************************************************************/
		/* actualización de sd_id de tbCommercialTransactions                                           */
		UPDATE	tbCommercialTransactions
			SET		sd_id				=	sd_id + 50,
					ct_ABalance			=	CONVERT(DECIMAL(19,6),0)
			--SELECT * FROM tbCommercialTransactions
			WHERE	comp_id				=	@comp_id
			--AND		bra_id				=	@bra_id
			AND		ct_transaction		=	@ct_transaction
		/************************************************************************************************/





		/************************************************************************************************/
		/* inicialización de impData_ActualQty en tbImportData                                          */
		UPDATE	tbImportData		WITH (ROWLOCK)
			SET		impData_ActualQty	=	0
			--SELECT * FROM tbImportData
			WHERE	comp_id				=	@comp_id
			--AND		bra_id				=	@bra_id
			AND		ct_transaction		=	@ct_transaction
		/************************************************************************************************/




		/************************************************************************************************/
		/* agregar la transacción relacionada a la anulación                                            */
		INSERT INTO tbCommercialTransactions
		(
		comp_id,				bra_id,										ct_pointOfSale,				ct_kindOf,
		ct_docNumber,			ct_date,			ct_taxDate,				ct_payDate,					supp_id,
		cust_id,				ba_id,				cb_id,					[user_id],					ct_cd,
		ct_subtotal,			ct_total,			ct_discount,			ct_adjust,					ct_taxes,
		curr_id_transaction,	hacc_transaction,	sm_id,					disc_id,					ct_ATotal,
		ct_ABalance,			ct_ACurrency,		ct_ACurrencyExchange,	df_id,						dl_id,
		st_id,					sd_id,				puco_id,				ct_CompanyCurrency,			ct_Branch2CompanyCurrencyExchange,
		ct_Pending,				country_id,			state_id,				ct_isAvailableForImport,	ct_soh_bra_id,
		ct_soh_id,				ct_CAI,				ct_CAIDate,				ct_isAvailableForPayment
		)
			SELECT
			comp_id,				bra_id,										ct_pointOfSale,				ct_kindOf,
			ct_docNumber,			@bra_processingDate,ct_taxDate,				ct_payDate,					supp_id,
			cust_id,				ba_id,				cb_id,					@user_id,					GETDATE()  /* MOS 11-2023 @actual_date*/,
			ct_subtotal,			ct_total,			ct_discount,			ct_adjust,					ct_taxes,
			curr_id_transaction,	hacc_transaction,	sm_id,					disc_id,					ct_ATotal,
			ct_ABalance,			ct_ACurrency,		ct_ACurrencyExchange,	df_id,						dl_id,
			st_id,					sd_id + 10,			puco_id,				ct_CompanyCurrency,			ct_Branch2CompanyCurrencyExchange,
			ct_Pending,				country_id,			state_id,				ct_isAvailableForImport,	ct_soh_bra_id,
			ct_soh_id,				ct_CAI,				ct_CAIDate,				ct_isAvailableForPayment
				FROM	tbCommercialTransactions			WITH (NOLOCK)
				WHERE	comp_id				=	@comp_id
				--AND		bra_id				=	@bra_id
				AND		ct_transaction		=	@ct_transaction


		SET @new_ct_transaction = @@IDENTITY
		/************************************************************************************************/






		/************************************************************************************************/
		/* agregar aplicación de la transaccion original con la nueva que es el contramovimiento        */
		INSERT INTO tbApplication
		(
				comp_id,					bra_id,
				ct_transaction_Source,		ct_transaction_destiny,
				appl_currency,				appl_total,
				appl_coef,					appl_coef_,
				appl_excdifchecked,			ct_transaction
		)
		SELECT
				@comp_id,					@bra_id,
				@ct_transaction,			@new_ct_transaction,
				tct.curr_id_transaction,	tct.ct_total,
				CONVERT(DECIMAL(18,6),100), CONVERT(DECIMAL(18,6),100),
				'False',					@ct_transaction

			FROM	tbCommercialTransactions				tct		WITH (NOLOCK)
			WHERE	tct.comp_id			= @comp_id
			--AND		tct.bra_id			= @bra_id
			AND		tct.ct_transaction	= @ct_transaction
		/************************************************************************************************/






		/************************************************************************************************/
		/* actualización del stock y de los items relacionados a la transacción generada                */
		DECLARE	@it_transaction		INT,
				@it_storePrevious	DECIMAL(19,6),
				@it_qty				DECIMAL(19,6),
				@item_id			INT,
				@stor_id			INT,
				@it_transaction_NoStockDiscount BIT


		DECLARE cursor_items CURSOR LOCAL FAST_FORWARD FOR
		SELECT	it_transaction,
				it_qty,
				item_id,
				stor_id,
				ISNULL(it_transaction_NoStockDiscount,'False')
			FROM	tbItemTransactions										WITH (NOLOCK)
			WHERE	comp_id				=	@comp_id
			AND		ct_transaction		=	@ct_transaction
			ORDER BY it_transaction

		OPEN cursor_items

		FETCH NEXT FROM cursor_items INTO	@it_transaction,
											@it_qty,
											@item_id,
											@stor_id,
											@it_transaction_NoStockDiscount

		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET		@it_storePrevious = 0
			SELECT	@it_storePrevious = ISNULL(tis.itst_cant,0)
				FROM	tbItemStorage tis
				WHERE	tis.comp_id =	@comp_id
				AND		tis.stor_id	=	@stor_id
				AND		tis.item_id	=	@item_id

			-- Solo si se desconto stock.
			-- esto es para: si ingresan un remito, luego una fc asociando al remito,
			-- anulaban la fc y anulaban el rm solo debe compensar el stock al anular el REMITO.
			IF @it_transaction_NoStockDiscount = 'False'
				BEGIN
					/* obtener el stock previo*/


					/* actualizar el stock con la cantidad del item de itemtransaction */
					UPDATE		tbItemStorage	WITH (ROWLOCK)
						SET		itst_cant = CASE @sd_isCredit
												WHEN 'True'	THEN	itst_cant + @it_qty
												ELSE				itst_cant - @it_qty
	   										END
						--SELECT	itst_cant, CASE @sd_isCredit WHEN 'True'	THEN itst_cant + @it_qty
						--													ELSE itst_cant - @it_qty	END
						FROM	tbItemStorage tis
						WHERE	comp_id =	@comp_id
						AND		stor_id	=	@stor_id
						AND		item_id	=	@item_id
				END



			/*insertar itemtransaction*/
			INSERT INTO tbItemTransactions
			(
			comp_id,				bra_id,					ct_transaction,			item_id,					it_qty,
			it_priceWithOutOthers,	it_price,				curr_id,				it_exchangeToBranchCurrency,it_priceOfCost,
			it_priceOfCostPP,		it_priceOfCostLastPurchase,it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
			it_OriginalPrice,		it_OriginalPriceCurrency,it_exchangeToOriginalPriceCurrency,stor_id,		it_storePrevious,
			prli_id,				byor_id,				it_isProduction,		it_isAssociation,			it_isAssociationGroup,
			it_cd,					it_packingInvoicePend,	it_order,				so_id,						it_guarantee,
			it_itemDiscountTotal,	it_totalDiscountTotal,	it_CreditInt,			it_CreditIntPlus,			puco_id,
			it_poh_bra_id,			it_poh_id,				it_soh_id,				it_sod_id,					rmah_id,
			rmad_id,				it_qty_rma,				it_tis_id_aux,			it_transaction_NoStockDiscount
			)
				SELECT
					comp_id,				bra_id,					@new_ct_transaction,	item_id,					it_qty,
					it_priceWithOutOthers,	it_price,				curr_id,				it_exchangeToBranchCurrency,it_priceOfCost,
					it_priceOfCostPP,		it_priceOfCostLastPurchase,it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
					it_OriginalPrice,		it_OriginalPriceCurrency,it_exchangeToOriginalPriceCurrency,stor_id,		@it_storePrevious,
					prli_id,				byor_id,				it_isProduction,		it_isAssociation,			it_isAssociationGroup,
					@actual_date,			it_packingInvoicePend,	it_order,				so_id,						it_guarantee,
					it_itemDiscountTotal,	it_totalDiscountTotal,	it_CreditInt,			it_CreditIntPlus,			puco_id,
					it_poh_bra_id,			it_poh_id,				it_soh_id,				it_sod_id,					rmah_id,
					rmad_id,				it_qty_rma,				it_tis_id_aux,	@it_transaction_NoStockDiscount
					FROM	tbItemTransactions tit		WITH (NOLOCK)
					WHERE	comp_id				=	@comp_id
					--AND		bra_id				=	@bra_id
					AND		ct_transaction		=	@ct_transaction
					AND		tit.it_transaction	=	@it_transaction


			FETCH NEXT FROM cursor_items INTO	@it_transaction,
												@it_qty,
												@item_id,
												@stor_id,
												@it_transaction_NoStockDiscount
		END

		CLOSE cursor_items
		DEALLOCATE cursor_items
		/************************************************************************************************/






		/************************************************************************************************/
		/* actualización del asiento contable con los contramovimientos de la transacción original      */
		INSERT INTO tbAccountTransactionDetail
		(
		comp_id,			bra_id,				hacc_transaction,
		acc_count_id,		cc_code,			dacc_debit,				dacc_credit,
		[user_id],			dacc_cd,			hacc_software,			ct_transaction,
		acc_detail1,		acc_detail2,		dacc_order,				dacc_2ndCurrencyExchange
		)
			SELECT
			comp_id,			bra_id,				hacc_transaction,
			acc_count_id,		cc_code,			dacc_credit,			dacc_debit,
			@user_id ,			@actual_date,		hacc_software,			@new_ct_transaction,
			acc_detail1,		acc_detail2,		dacc_order,				dacc_2ndCurrencyExchange
				FROM	tbAccountTransactionDetail		WITH (NOLOCK)
				WHERE	comp_id			=	@comp_id
				AND		ct_transaction	=	@ct_transaction
		/************************************************************************************************/



		-- =====================================================================================================
		-- parte: 771
		DELETE	FROM tbItemSerials
		WHERE	--comp_id			= @comp_id		Mas rapido por los indices que estan actualmente
				ct_transaction	= @ct_transaction
		-- =====================================================================================================



		-- Si venia desde una recepcion de o.compra debo marcarla como cancelada..
		IF @bitSetPurchaseReceptionAsAnnuled = 'True'
			BEGIN
				UPDATE tbPurchaseorderReceptionHeader
					SET	por_isCancelled = 'True'
					WHERE	comp_id = @comp_id AND
							por_id = @por_id
			END




		-- Si los ItTransactions tienen una Orden de Compra asociada la deja como NO PROCESADA
		UPDATE tbPurchaseOrderDetail
			SET	tbPurchaseOrderDetail.pod_isProcessed = 'False'
			FROM tbPurchaseOrderDetail pod			WITH (NOLOCK)
			INNER JOIN tbItemTransactions tit		WITH (NOLOCK)
			ON	tit.comp_id			= pod.comp_id	AND
				tit.it_poh_bra_id	= pod.bra_id	AND
				tit.it_poh_id		= pod.poh_id	AND
				tit.it_pod_id		= pod.pod_id
			WHERE	tit.comp_id			= @comp_id	AND
					tit.ct_transaction	= @ct_transaction



		-- -----------------------------------------------------------------------------------------------
		-- MOS 08-2022  	**lwqhf973249%&$#%$#%lkjnlkh  CM y LRCDTPM!
		-- Si los ItTransactions tienen una Orden de Compra asociada deja a todas los Pedidos de esa O Compra como que NO se incluye en disponible ( tildado ) y no pendiente de relacionar a o compra ( destildado )
		-- -----------------------------------------------------------------------------------------------
		UPDATE tbSaleOrderDetail
			SET sod_exclude4AvailableStock = 'True',
				sod_pending4pod_IdRelation = 'False'
			FROM tbSaleOrderDetail								AS	tsod	WITH (NOLOCK)
			INNER JOIN tbSaleOrderHeader_PurchaseOrderRelation	AS	tsor	WITH (NOLOCK)
				ON	tsor.comp_id	= tsod.comp_id AND
					tsor.so_bra_id	= tsod.bra_id AND
					tsor.so_soh_id	= tsod.soh_id AND
					tsor.so_sod_id	= tsod.sod_id
			INNER JOIN tbItemTransactions							tit		WITH (NOLOCK)
			ON	tit.comp_id			= tsor.comp_id AND
				tit.it_poh_bra_id	= tsor.po_bra_id AND
				tit.it_poh_id		= tsor.po_poh_id AND
				tit.it_pod_id		= tsor.po_pod_id
			WHERE	tit.comp_id			= @comp_id AND
					tit.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------
		-- MOS 08-2022  	**lwqhf973249%&$#%$#%lkjnlkh  CM y LRCDTPM!
		-- Si los ItTransactions tienen una Orden de Compra asociada deja a todas los Pedidos de esa O Compra como que NO se incluye en disponible ( tildado ) y no pendiente de relacionar a o compra ( destildado )
		-- -----------------------------------------------------------------------------------------------
		UPDATE tbSaleOrderHeader_PurchaseOrderRelation
			SET posor_POReceived = 'False'
			FROM tbSaleOrderHeader_PurchaseOrderRelation		AS	tsor	WITH (NOLOCK)
			INNER JOIN tbItemTransactions							tit		WITH (NOLOCK)
			ON	tit.comp_id			= tsor.comp_id AND
				tit.it_poh_bra_id	= tsor.po_bra_id AND
				tit.it_poh_id		= tsor.po_poh_id AND
				tit.it_pod_id		= tsor.po_pod_id
			WHERE	tit.comp_id			= @comp_id AND
					tit.ct_transaction	= @ct_transaction
		-- -----------------------------------------------------------------------------------------------





    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
				@ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT


END
GO







-- TRANSACCIONES OK MOS
CREATE PROCEDURE [dbo].[spCommercialTransactions_annulPackingList]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@ct_transaction					INT,
	@user_id						INT,		-- MOS 11-2023
	@return_value					INT				OUTPUT,
	@ret_ErrorCode					INT 			OUTPUT,
	@ret_ErrorDescription			VARCHAR(200)	OUTPUT
)
AS

BEGIN



	-- =================================================================================================================
	-- Author		: HDP recontraaaaaaaaaaaaaa
	-- Creation Date: 2011-02-02
	-- Parte		: 784
	-- Description	: Anulación de remitos de ventas
	-- =================================================================================================================

	SET NOCOUNT ON



	/*
	------------------------------------------------------------------------------
	--PARAMETROS PARA PRUEBAS-----------------------------------------------------
	------------------------------------------------------------------------------
	DECLARE @comp_id					INT,
			@lang_id					INT,
			@bra_id						INT,
			@ct_transaction				INT,
			@return_value				INT,
			@ret_ErrorCode				INT,
			@ret_ErrorDescription		VARCHAR(200)

	SELECT 	@comp_id					=1,
			@lang_id					=2,
			@bra_id						=1,
			@ct_transaction				=6032
	------------------------------------------------------------------------------
	*/





	Set		@return_value			= 0
	Set		@ret_ErrorCode			= 0
	Set		@ret_ErrorDescription	= ''




	-- -----------------------------------------------------------------------------------
	-- Verifica si es un rm de transferencia entre suc q ya fue recibido.
	-- -----------------------------------------------------------------------------------
	IF EXISTS(
				SELECT TOP 1  1
					FROM tbItemTransactions tit					WITH (NOLOCK)
					INNER JOIN tbCommercialTransactions tct		WITH (NOLOCK)
						ON	tct.comp_id			= tit.comp_id AND
							tct.ct_transaction	= tit.ct_transaction
					WHERE	tit.comp_id			= @comp_id			AND
							tit.ct_transaction	= @ct_transaction	AND
							tit.sitt_id			= 110				AND
							tct.ct_Pending		= 'False'

			)
		BEGIN
			Set		@return_value			= -1
			Set		@ret_ErrorCode			= -1
			--Set	@ret_ErrorDescription	= 'El Remito de Transferencia entre Sucursales ya fue Recibido !
			Set		@ret_ErrorDescription	= (SELECT TOP 1  tut.utexts_desc
			   		                     			FROM tbsysUniqueTexts tut	WITH (NOLOCK)
			   		                     			WHERE tut.lang_id = @lang_id AND tut.utexts_id = 40137)
			RETURN
		END
	-- -----------------------------------------------------------------------------------




	/************************************************************************************************/
	/* recuperación de la fecha de proceso                                                          */
	DECLARE @bra_processingDate			DATETIME,
			@lct_transaction_new		INT


	SELECT	@bra_processingDate		=	tb.bra_processingDate
		FROM	tbBranch					tb					WITH (NOLOCK)
		WHERE	tb.comp_id				=	@comp_id
		AND		tb.bra_id				=	@bra_id
	/************************************************************************************************/




    SAVE TRANSACTION traPROTECT
    BEGIN TRANSACTION
    BEGIN TRY

			-- ------------------------------------
			-- Bloquear la base antes de hacer nada
			-- ------------------------------------
			DECLARE @intLock AS INT
			SELECT @intLock = tce.sb_id
				FROM tbsysBlockPage4IsoTran  tce
			-- ------------------------------------



			/************************************************************************************************/
			/* agregar la transacción relacionada a la anulación del remito, que es igual al remito original
			* sólo actualizando el df_id y el sd_id                                                         */
			INSERT INTO tbCommercialTransactions
			(
			comp_id,				bra_id,										ct_pointOfSale,				ct_kindOf,
			ct_docNumber,			ct_date,			ct_taxDate,				ct_payDate,					supp_id,
			cust_id,				ba_id,				cb_id,					[user_id],					ct_cd,
			ct_subtotal,			ct_total,			ct_discount,			ct_adjust,					ct_taxes,
			curr_id_transaction,	hacc_transaction,	sm_id,					disc_id,					ct_ATotal,
			ct_ABalance,			ct_ACurrency,		ct_ACurrencyExchange,	df_id,						dl_id,
			st_id,					sd_id,				puco_id,				ct_CompanyCurrency,			ct_Branch2CompanyCurrencyExchange,
			ct_Pending,				country_id,			state_id,				ct_isAvailableForImport,	ct_soh_bra_id,
			ct_soh_id,				ct_CAI,				ct_CAIDate,				ct_isAvailableForPayment
			)
			SELECT
				tbCommercialTransactions.comp_id,				tbCommercialTransactions.bra_id,				ct_pointOfSale,				ct_kindOf,
				ct_docNumber, 			@bra_processingDate,ct_taxDate,				ct_payDate,					supp_id,
				cust_id,				ba_id,				cb_id,					@user_id,					GETDATE() /*MOS 11-2023 @bra_processingDate*/,
				ct_subtotal,			ct_total,			ct_discount,			ct_adjust,					ct_taxes,
				curr_id_transaction,	hacc_transaction,	sm_id,					disc_id,					ct_ATotal,
				ct_ABalance,			ct_ACurrency,		ct_ACurrencyExchange,	tdf.df_id4PLAnnulment,		dl_id,
				st_id,					tdf2.sd_id,			puco_id,				ct_CompanyCurrency,			ct_Branch2CompanyCurrencyExchange,
				ct_Pending,				country_id,			state_id,				ct_isAvailableForImport,	ct_soh_bra_id,
				ct_soh_id,				ct_CAI,				ct_CAIDate,				ct_isAvailableForPayment

				FROM	tbCommercialTransactions		WITH (NOLOCK)  --- HDP y el puto alias ???

						INNER JOIN tbDocumentsFile								tdf			WITH (NOLOCK)
						ON	tdf.comp_id		= tbCommercialTransactions.comp_id
						AND tdf.bra_id		= tbCommercialTransactions.bra_id
						AND tdf.df_id		= tbCommercialTransactions.df_id

						INNER JOIN tbDocumentsFile								tdf2			WITH (NOLOCK)
						ON	tdf2.comp_id	= tbCommercialTransactions.comp_id
						AND tdf2.bra_id		= tbCommercialTransactions.bra_id
						AND tdf2.df_id		= tdf.df_id4PLAnnulment


				WHERE	tbCommercialTransactions.comp_id	=	@comp_id
				--AND		tbCommercialTransactions.bra_id		=	@bra_id
				AND		ct_transaction						=	@ct_transaction


			SET @lct_transaction_new = @@IDENTITY
			/************************************************************************************************/



			--Ga,09/12-/15 se agrego pending en false para que no aparezca mas el remito en trans entre suc.
			UPDATE 	tbCommercialTransactions		WITH (ROWLOCK)
				SET		ct_isCancelled	= 'true',
						ct_Pending		= 'False'
				WHERE	comp_id			=	@comp_id
				--AND		bra_id			=	@bra_id
				AND		ct_transaction	=	@ct_transaction




			/************************************************************************************************/
			/* generamos un cursor que recupera todos los it_transaction relacionados al remito original    */
			DECLARE @lit_itemtransaction		INT,
					@lit_itemtransaction_new	INT


			DECLARE cursor_itemtransactions CURSOR LOCAL FAST_FORWARD  FOR
			SELECT	it_transaction
				FROM	tbItemTransactions	tit					WITH (NOLOCK)
				WHERE	tit.comp_id			= @comp_id
				--AND		tit.bra_id			= @bra_id
				AND		tit.ct_transaction	= @ct_transaction


			OPEN	cursor_itemtransactions


			FETCH	cursor_itemtransactions
			INTO	@lit_itemtransaction


			/* loop por cada item */
			WHILE @@FETCH_STATUS = 0
			BEGIN

				/* generar los items para el nuevo remito a partir de los items del remito original */
				INSERT INTO tbItemTransactions
				(
					comp_id,						bra_id,										ct_transaction,
					item_id,						it_qty,										it_priceWithOutOthers,
					it_price,						curr_id,									it_exchangeToBranchCurrency,
					it_priceOfCost,					it_priceOfCostPP,							it_priceOfCostLastPurchase,
					it_priceBOfCost,				it_priceBOfCostPP,							it_priceBOfCostLastPurchase,
					it_OriginalPrice,				it_OriginalPriceCurrency,					it_exchangeToOriginalPriceCurrency,
					stor_id,						it_storePrevious,							prli_id,
					byor_id,						it_isProduction,							it_isAssociation,
					it_isAssociationGroup,			it_cd,										it_packingInvoicePend,
					it_order,						so_id,										it_guarantee,
					it_itemDiscountTotal,			it_totalDiscountTotal,						it_CreditInt,
					it_CreditIntPlus,				puco_id,									it_poh_bra_id,
					it_poh_id,						it_soh_id,									it_sod_id,
					rmah_id,						rmad_id,									it_qty_rma,
					it_tis_id_aux,					it_note1,									it_note2,
					it_packingInvoiceSelected,		it_cancelled,								it_priceB,
					it_isMade,						it_item_id_origin,							tmp_tis_id,
					it_packingInvoicePendOriginal,	it_packingInvoiceSelectedGuid,				it_transaction_original,
					it_transaction_NoStockDiscount,	it_SalesCurrId4exchangeToBranchCurrency,	it_AllUseTag1,
					it_AllUseTag2,					it_AllUseTag3,								it_AllUseTag4
				)
				SELECT	tit.comp_id,						tit.bra_id,										@lct_transaction_new,
						tit.item_id,						tit.it_qty,										tit.it_priceWithOutOthers,
						tit.it_price,						tit.curr_id,									tit.it_exchangeToBranchCurrency,
						tit.it_priceOfCost,					tit.it_priceOfCostPP,							tit.it_priceOfCostLastPurchase,
						tit.it_priceBOfCost,				tit.it_priceBOfCostPP,							tit.it_priceBOfCostLastPurchase,
						tit.it_OriginalPrice,				tit.it_OriginalPriceCurrency,					tit.it_exchangeToOriginalPriceCurrency,
						tit.stor_id,
									/*tit.it_storePrevious*/
															ISNULL(tis.itst_cant,0), /* MOS 01-2022*/					tit.prli_id,
						tit.byor_id,						tit.it_isProduction,							tit.it_isAssociation,
						tit.it_isAssociationGroup,			tit.it_cd,										tit.it_packingInvoicePend,
						tit.it_order,						tit.so_id,										tit.it_guarantee,
						tit.it_itemDiscountTotal,			tit.it_totalDiscountTotal,						tit.it_CreditInt,
						tit.it_CreditIntPlus,				tit.puco_id,									tit.it_poh_bra_id,
						tit.it_poh_id,						tit.it_soh_id,									tit.it_sod_id,
						tit.rmah_id,						tit.rmad_id,									tit.it_qty_rma,
						tit.it_tis_id_aux,					tit.it_note1,									tit.it_note2,
						tit.it_packingInvoiceSelected,		tit.it_cancelled,								tit.it_priceB,
						tit.it_isMade,						tit.it_item_id_origin,							tit.tmp_tis_id,
						tit.it_packingInvoicePendOriginal,	tit.it_packingInvoiceSelectedGuid,				tit.it_transaction_original,
						tit.it_transaction_NoStockDiscount,	tit.it_SalesCurrId4exchangeToBranchCurrency,	tit.it_AllUseTag1,
						tit.it_AllUseTag2,					tit.it_AllUseTag3,								tit.it_AllUseTag4

					FROM	tbItemTransactions				tit			WITH (NOLOCK)
					LEFT JOIN tbItemStorage				 AS tis			WITH (NOLOCK)
						ON	tis.comp_id = tit.comp_id AND
							tis.stor_id = tit.stor_id AND
							tis.item_id = tit.item_id

					WHERE	tit.comp_id			= @comp_id
					--AND		tit.bra_id			= @bra_id
					AND		tit.ct_transaction	= @ct_transaction
					AND		tit.it_transaction	= @lit_itemtransaction

				SET @lit_itemtransaction_new = @@IDENTITY



				/* generar los itemstransactionserials para los items del nuevo remito a partir de lo datos del original*/
				INSERT INTO tbItemTransactionSerials
				(
					comp_id,
					bra_id,
					it_transaction,
					is_id,
					impData_id,
					import_id,
					ct_transaction
				)
					SELECT	comp_id,
							bra_id,
							@lit_itemtransaction_new,
							is_id,
							impData_id,
							import_id,
							@lct_transaction_new
						FROM	tbItemTransactionSerials			tits
						WHERE	tits.comp_id		= @comp_id
						--AND		tits.bra_id			= @bra_id
						AND		tits.it_transaction	= @lit_itemtransaction



				/* actualizar como disponibles los itemserials relacionados a los items original y que ahora también están
				* relacionados a los nuevos items                                                                         */
				UPDATE	tbitemserials		WITH (ROWLOCK)
					SET		tbitemserials.is_available = 'true'
					FROM	tbItemSerials				tis
					WHERE	tis.comp_id	= @comp_id
					AND		tis.is_id IN	(
												SELECT	tits.is_id
													FROM	tbItemTransactionSerials		tits	WITH (NOLOCK)
													WHERE	tits.comp_id		= @comp_id
													--AND		tits.bra_id			= @bra_id
													AND		tits.it_transaction	= @lit_itemtransaction
											)





				/* actualizar el stock */
				UPDATE	tbItemStorage	WITH (ROWLOCK)
					SET 	itst_cant = tis.itst_cant + tit.it_qty
					FROM 	tbItemStorage						tis
							INNER JOIN tbItemTransactions		tit
							ON	tit.item_id = tis.item_id
							AND tit.stor_id = tis.stor_id
							AND tit.comp_id = tis.comp_id
					WHERE	tit.comp_id			= @comp_id
					--AND		tit.bra_id			= @bra_id
					AND		tit.ct_transaction	= @ct_transaction
					AND		tit.it_transaction	= @lit_itemtransaction






				FETCH cursor_itemtransactions
				INTO @lit_itemtransaction


			END


			CLOSE		cursor_itemtransactions
			DEALLOCATE	cursor_itemtransactions
			/************************************************************************************************/


--SELECT 1 / 0

    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION traPROTECT

		SET		@return_value			=	-1
		SET 	@ret_ErrorCode			=	-1
		SET 	@ret_ErrorDescription	=	ERROR_MESSAGE()

        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT



	--
	--END TRY
	--BEGIN CATCH
	--	SET		@return_value			=	-1
	--	SET 	@ret_ErrorCode			=	-1
	--	SET 	@ret_ErrorDescription	=	ERROR_MESSAGE()
	--END CATCH



END
GO


CREATE PROCEDURE [dbo].[spCommercialTransactions_Audit_getDataByFilters]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@user_id		INT,

	@cust_id		INT,
	@dateFrom		DATETIME,
	@dateTo			DATETIME,
	@df_id			INT,
	@GuidCust		VARCHAR(50)

)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@bra_id			INT,
				@prof_id		INT,
				@user_id		INT,

				@cust_id		INT,
				@dateFrom		DATETIME,
				@dateTo			DATETIME,
				@df_id			INT,
				@GuidCust		VARCHAR(50)

			SELECT
				@comp_id		= 1,
				@lang_id		= 2,

				@GuidCust		= '7B370139-75C6-425A-B9CB-7C900057E31E',
				@dateFrom		= '2017-01-01',
				@dateTo			= '2017-12-31',
				@cust_id		= -1,
				@df_id			= -1
	*/
		-- -----------------------------------------------------

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de clientes para Filtros
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Cust TABLE (cust_id INT NULL UNIQUE CLUSTERED)
		INSERT INTO @tblComplexFilter_Cust
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf	WITH (NOLOCK)
				WHERE	tcf.sl_guid		= @Guidcust     AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				IF @cust_id > 0
					BEGIN
						INSERT INTO @tblComplexFilter_Cust(cust_id) VALUES (@cust_id)
					END
				ELSE
					BEGIN
						INSERT INTO @tblComplexFilter_Cust(cust_id)
							SELECT cust_id
							FROM tbCustomer tc	WITH (NOLOCK)
								WHERE tc.comp_id = @comp_id
						--INSERT INTO @tblComplexFilter_Items( item_id) VALUES (NULL)
					END
			END

		-- -------------------------------------------------------------

		-- Toma la moneda de la sucursal
		DECLARE @bra_curr_id		INT
		SELECT
			@bra_curr_id		   = tb.curr_id
			FROM tbBranch tb		WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id
			AND		tb.bra_id	= @bra_id

		SET @dateFrom		= dbo.fnGetEnd_or_BeginOfDate(@dateFrom,0)
		SET @dateTo			= dbo.fnGetEnd_or_BeginOfDate(@dateTo,0)


		SELECT
			'' [1],
			dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[Document],
			tct.ct_date																				[ct_date],
			tct.ct_payDate																			[ct_payDate],
			tc.cust_name																			[cust_name],
			tc.cust_taxNumber																		[cust_taxNumber],
			tct.ct_subtotal																			[subtotal],
			tct.ct_total																			[total],
			tct.ct_taxes																			[tax],
			tc2.curr_desc																			[Curr_desc],
			tct.ct_transaction																		[ID]

			FROM tbCommercialTransactions														tct			WITH(NOLOCK)

			INNER JOIN tbUsers4BranchFilter														tbu			WITH(NOLOCK)
			ON	tbu.comp_id				= tct.comp_id											AND
				tbu.bra_id				= tct.bra_id											AND
				tbu.[user_id]			= @user_id

			INNER JOIN vwCommercialTransactions_forSales										vctfs		WITH(NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id											AND
				vctfs.ct_transaction	= tct.ct_transaction

			INNER JOIN @tblComplexFilter_Cust													tmp
			ON	tmp.cust_id				= tct.cust_id

			INNER JOIN tbCustomer																tc			WITH(NOLOCK)
			ON	tc.comp_id				= tct.comp_id											AND
				tc.cust_id				= tmp.cust_id

			INNER JOIN tbsysCurrency															tc2			WITH(NOLOCK)
			ON	tc2.curr_id				= tct.curr_id_transaction

			INNER JOIN tbsysDocuments															td			WITH (NOLOCK)
			ON	td.sd_id				= tct.sd_id

			INNER JOIN tbDocumentsFile															tdf			WITH (NOLOCK)
				ON	tdf.comp_id			= tct.comp_id	AND
					tdf.bra_id			= tct.bra_id	AND
					tdf.df_id			= tct.df_id


			WHERE	tct.comp_id		= @comp_id										AND
					(tct.ct_Date	BETWEEN @dateFrom	AND @dateTo)				AND
					(@df_id		= -1	OR tct.df_id	= @df_id)					AND
					tdf.df_salesAuditEnabled			= 1

			ORDER BY tct.ct_date desc


	END
GO

CREATE PROCEDURE [dbo].[spCommercialTransactions_Audit4AllMovements_GetDataByFilters]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@sd_id			INT,
	@CustGuid		UNIQUEIDENTIFIER,
	@SuppGuid		UNIQUEIDENTIFIER,
	@ItemGuid		UNIQUEIDENTIFIER,
	@kindOf			NVARCHAR(50),
	@pointOfSale	INT,
	@ct_docNumber	NVARCHAR(50),
	@dateFrom		DATETIME,
	@dateTo			DATETIME,
	@TotalFrom		DECIMAL(19,5),
	@TotalTo		DECIMAL(19,5)
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@sd_id			INT,
				@CustGuid		UNIQUEIDENTIFIER,
				@SuppGuid		UNIQUEIDENTIFIER,
				@ItemGuid		UNIQUEIDENTIFIER,
				@kindOf			NVARCHAR(50),
				@pointOfSale	INT,
				@ct_docNumber	INT
			SELECT
				@comp_id		= 1,
				@lang_id		= 2,
				@sd_id			= 1,
				@CustGuid		= '4bf17802-0bdb-461f-8d9c-ed18a8fc013a',
				@SuppGuid		= '4bf17802-0bdb-461f-8d9c-ed18a8fc013a',
				@ItemGuid		= '4bf17802-0bdb-461f-8d9c-ed18a8fc013a',
				@kindOf			= '',
				@pointOfSale	= 0,
				@ct_docNumber	= 0
		*/
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros
		-- -----------------------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @ItemGuid     AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Clientes para Filtros
		-- -----------------------------------------------------------------------------
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @CustGuid    AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT tc.cust_id
						FROM tbCustomer tc
						WHERE tc.comp_id = @comp_id
			END
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Proveedores para Filtros
		-- -----------------------------------------------------------------------------
		DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Supplier
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid =@SuppGuid   AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Supplier
					SELECT ts.supp_id
						FROM tbSupplier ts
						WHERE ts.comp_id = @comp_id
			END
		-- -----------------------------------------------------------------------------

		SET @dateFrom		= dbo.fnGetEnd_or_BeginOfDate(@dateFrom,0)
		SET @dateTo			= dbo.fnGetEnd_or_BeginOfDate(@dateTo,0)

		IF @sd_id <= 100
			BEGIN
				SELECT
					''																						[1],	--REIMPRESION
					''																						[2],	--CTA CTE
					''																						[3],	--A DEFINIR 1
					''																						[4],	--A DEFINIR 2
					tc.cust_id,
					tc.cust_name,
					dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[Description],
					tct.ct_date,
					tct.ct_subtotal																			[subtotal],
					tct.ct_total																			[total],
					tct.ct_taxes																			[tax],
					tc2.curr_desc																			[Curr_desc],
					tdf.df_desc,
					CONVERT(VARCHAR,tct.ct_transaction) + '-' + CONVERT(VARCHAR,tct.sd_id)					[ID]
					FROM tbCommercialTransactions			tct		WITH(NOLOCK)
					INNER JOIN tbUsers4BranchFilter			tubf	WITH(NOLOCK)
					ON	tubf.comp_id	= tct.comp_id		AND
						tubf.bra_id		= tct.bra_id		AND
						tubf.[user_id]	= tct.[user_id]
					INNER JOIN @tblComplexFilter_Customer	tmp
					ON	tmp.cust_id		= tct.cust_id
					INNER JOIN tbCustomer					tc		WITH(NOLOCK)
					ON	tc.cust_id		= tmp.cust_id
					INNER JOIN tbsysCurrency				tc2		WITH(NOLOCK)
					ON	tc2.curr_id		= tct.curr_id_transaction
					INNER JOIN tbBranch						tb		WITH(NOLOCK)
					ON	tb.comp_id		= tct.comp_id		AND
						tb.bra_id		= tct.bra_id
					INNER JOIN tbDocumentsFile				tdf		WITH(NOLOCK)
					ON	tdf.comp_id		= tct.comp_id		AND
						tdf.df_id		= tct.df_id
				WHERE	tct.comp_id = @comp_id				AND
						tct.sd_id	= @sd_id				AND
						(
							@kindOf				= ''	OR
							tct.ct_kindOf		= @kindOf
						)									AND
						(
							@pointOfSale		= 0		OR
							tct.ct_pointOfSale	= @pointOfSale
						)									AND
						(
							@ct_docNumber		= ''	OR
							tct.ct_docNumber	= @ct_docNumber
						)									AND
						tct.ct_Date	BETWEEN @dateFrom		AND @dateTo
															AND
						tct.ct_total	BETWEEN @TotalFrom	AND @TotalTo

				ORDER BY tct.ct_date DESC
			END
		ELSE
			BEGIN
				SELECT
					''																						[1],	--REIMPRESION
					''																						[2],	--CTA CTE
					''																						[3],	--A DEFINIR 1
					''																						[4],	--A DEFINIR 2
					ts.supp_id,
					ts.supp_name,
					dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[Description],
					tct.ct_date,
					tct.ct_subtotal																			[subtotal],
					tct.ct_total																			[total],
					tct.ct_taxes																			[tax],
					tc2.curr_desc																			[Curr_desc],
					CONVERT(VARCHAR,tct.ct_transaction) + '-' + CONVERT(VARCHAR,tct.sd_id)					[ID]
					FROM tbCommercialTransactions			tct		WITH(NOLOCK)
					INNER JOIN tbUsers4BranchFilter			tubf	WITH(NOLOCK)
					ON	tubf.comp_id	= tct.comp_id		AND
						tubf.bra_id		= tct.bra_id		AND
						tubf.[user_id]	= tct.[user_id]
					INNER JOIN @tblComplexFilter_Supplier	tmp
					ON	tmp.supp_id		= tct.supp_id
					INNER JOIN tbSupplier					ts		WITH(NOLOCK)
					ON	ts.supp_id		= tmp.supp_id
					INNER JOIN tbsysCurrency				tc2		WITH(NOLOCK)
					ON	tc2.curr_id		= tct.curr_id_transaction
					INNER JOIN tbBranch						tb		WITH(NOLOCK)
					ON	tb.comp_id		= tct.comp_id		AND
						tb.bra_id		= tct.bra_id
				WHERE	tct.comp_id = @comp_id				AND
						tct.sd_id	= @sd_id				AND
						(
							@kindOf				= ''	OR
							tct.ct_kindOf		= @kindOf
						)									AND
						(
							@pointOfSale		= 0		OR
							tct.ct_pointOfSale	= @pointOfSale
						)									AND
						(
							@ct_docNumber		= ''	OR
							tct.ct_docNumber	= @ct_docNumber
						)									AND
						tct.ct_Date	BETWEEN @dateFrom		AND @dateTo
															AND
						tct.ct_total	BETWEEN @TotalFrom	AND @TotalTo
				ORDER BY tct.ct_date DESC
			END

	END

GO






CREATE PROCEDURE [dbo].[spCommercialTransactions_AvailableForImport]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int
)
as
set nocount on

/*
Declare
		@comp_id		int,
		@lang_id		int,
		@bra_id			int

Select
		@comp_id		=1,
		@lang_id		=2,
		@bra_id			=1
*/
Select
		CT.ct_transaction [Id],
		isnull(substring(S.supp_name,0,20),'') + ' - ' +  dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.ct_transaction) as [Desc]

From	dbo.tbCommercialTransactions							CT

		inner join dbo.vwCommercialTransactions_forPurchase		VP
		on	CT.ct_transaction	=	VP.ct_Transaction

		inner join dbo.tbSupplier								S
		on	CT.supp_id			=	S.supp_id

where	CT.comp_id	=	@comp_id
and		CT.bra_id	=	@bra_id
and		CT.ct_isAvailableForImport = 'True'
and		CT.ct_transaction not in (Select ct_transaction
								  from dbo.tbImportDetail)
GO





-- --------------------------------------------------------------------------------------------------------
-- NOTA: Mailing de Deuda a Clientes
-- En el server debe figurar la carpeta y archivo: C:\GlobalBluePoint.PictureFiles\GBPPoweredBy.png
-- El nombre del adjunto debe estar en tbSysUniqueTexts utextt_id=100 y -1

-- Para Forzar la ejecucion correr este comando
-- UPDATE tbbranch SET bra_Mailing4CustOverdueDebt_LastExecution = GETDATE() - 365
-- --------------------------------------------------------------------------------------------------------



CREATE  PROCEDURE  [dbo].[spCommercialTransactions_BalanceMails]
(
	@intCompID AS INT,
	@intBraID  AS INT
)
AS


BEGIN





	SET NOCOUNT ON
	SET DATEFIRST 7		-- Domingo x Defecto

	-- -----------------------------------------------------
	-- Testing
	-- -----------------------------------------------------
	/*
	DECLARE @intCompID AS INT = 1
	DECLARE @intBraID  AS INT = 1
	UPDATE tbbranch SET bra_Mailing4CustOverdueDebt_LastExecution = GETDATE() - 2000
	*/
	-- -----------------------------------------------------


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- Arranca servicio de email
	--exec msdb.dbo.sysmail_start_sp

	--variables para cursor principal
	DECLARE	@comp_id						INT,
			@bra_id							INT,
			@cust_id						INT,
			@cust_name						nVARCHAR(2000),
			@cust_contact					NVARCHAR(2000),
			@cust_email						nVARCHAR(2000),
			@curr_id						INT,
			@user_id						INT,
			@lang_id						INT



	--variables para datos de la sucursal
	DECLARE @bra_Mailing4CustOverdueDebt_BodyInitialMessage		NVARCHAR(4000),
			@bra_Mailing4CustOverdueDebt_BodyFinalMessage		NVARCHAR(4000),
			@bra_Mailing4CustOverdueDebt_Subject				NVARCHAR(4000),
			@bra_Mailing4CustOverdueDebt_FromEmail				NVARCHAR(4000),
			@bra_Mailing4CustOverdueDebt_BlindCopy				NVARCHAR(4000),
			@bra_MainDesc										NVARCHAR(200),
			@bra_address										NVARCHAR(100),
			@bra_address1										NVARCHAR(100),
			@bra_phone											NVARCHAR(100),
			@bra_zip											NVARCHAR(50),
			@country_desc										NVARCHAR(50),
			@state_desc											NVARCHAR(50)



	--variables para el formateo del html email
	DECLARE	@subject						NVARCHAR(MAX),
			@bodyHeader						NVARCHAR(MAX),
			@body							NVARCHAR(MAX),
			@bodyCustOverdueDebt			NVARCHAR(MAX),
			@bodyCustNotOverdueDebt			NVARCHAR(MAX),
			@bodyFooter						NVARCHAR(MAX)



	--variables para la actualización del logueo de seguridad
	DECLARE @seclog_obs_1					VARCHAR(8000),
			@prof_id						INT,
			@comp_id_ant					INT,
			@bra_id_ant						INT,
			@rv								INT



	--variables de trabajo
	DECLARE @tableheader					NVARCHAR(MAX),
			@lCustOverdueDebt				NVARCHAR(MAX),
			@lCustNotOverdueDebt			NVARCHAR(MAX),
			@lFirstTime						BIT


	DECLARE @strBra_Mailing4CustOverdueDebt_Mail4AdditionalSend AS VARCHAR(200)



	--verificación que ya no se haya ejecutado ese día
	--IF NOT EXISTS	(
	--					SELECT	1
	--					FROM	tbSecurityLog			tsl
	--					WHERE	tsl.sysCode_id = 1000
	--					AND		dbo.fnGetEnd_or_BeginOfDate(tsl.seclog_cd,'false') = dbo.fnGetEnd_or_BeginOfDate(GETDATE(),'false')
	--				)
	--BEGIN





	--verificación de la existencia de alguna sucursal que tenga habilitado el mailing para clientes con deuda vencida
	--y que tenga configurado un usuario para ese mailing
	IF EXISTS	(SELECT		TOP 1 1
					FROM	tbBranch							tb		WITH (NOLOCK)
					WHERE	ISNULL(tb.bra_Mailing4CustOverdueDebt_Available,'false')= 'true'
					AND		ISNULL(tb.bra_disabled,'false') = 'false'
					AND		NOT tb.bra_Mailing4CustOverdueDebt_User_id				IS NULL)
	BEGIN


		DECLARE @tblBranch TABLE(bra_id INT PRIMARY KEY)

		INSERT INTO @tblBranch(bra_id)
			SELECT tb.bra_id
				FROM tbbranch	tb	WITH (NOLOCK)
				WHERE
					(
						(
								DATEDIFF(DAY,ISNULL(tb.bra_Mailing4CustOverdueDebt_LastExecution,GETDATE()-365),GETDATE())
																	>= ISNULL(tb.bra_Mailing4CustOverdueDebt_Periodicity,10)
								AND
								(
									tb.bra_Mailing4CustOverdueDebt_dayOfWeek = -1
										OR
									tb.bra_Mailing4CustOverdueDebt_dayOfWeek IS NULL
										OR
									DATEPART(weekday,tb.bra_processingDate)  = tb.bra_Mailing4CustOverdueDebt_dayOfWeek
										OR
									DATEPART(weekday,tb.bra_processingDate)  = tb.bra_Mailing4CustOverdueDebt_dayOfWeek2
								)
						)
						OR @intBraID > 0
					)
					-- si la diferencia en dias entre la última ejecución del mailing y la fecha actual es mayor o igual
					-- a la periodicidad se ejecuta para esa sucursal

					AND		ISNULL(tb.bra_Mailing4CustOverdueDebt_Available,'false') = 'true'
					AND     (@intBraID = -1 OR @intBraID = tb.bra_id)  -- que sea automatico con -1 o pedido desde el sistema
					AND		ISNULL(tb.bra_disabled,'false') = 'false'


				--recuperamos todos los clientes que tienen documentos pendientes de pago vencidos, que estén activos y no estén en
				--gestión judicial
		DECLARE CURSOR_CUSTOMERS CURSOR LOCAL  FAST_FORWARD FOR
				SELECT	DISTINCT
						tct.comp_id,
						tct.bra_id,
						tct.cust_id,
						tc.cust_name,
						CASE
							WHEN bra_Mailing4CustOverdueDebt_only2PaymentMail = 1 THEN  tc.cust_contact4Payments
							ELSE														dbo.fnSTRContactJoin(tc.cust_contact,tc.cust_contact4Payments,tc.cust_contact4Administration,'','')
						END,
						CASE
							WHEN bra_Mailing4CustOverdueDebt_only2PaymentMail = 1 THEN	tc.cust_email4Payments
							ELSE														dbo.fnSTREmailJoin(tc.cust_email,tc.cust_email4Payments,tc.cust_email4Administration,'','')
						END	,
						tc.curr_id,
						tu.user_lastlanguage

				FROM	tbCommercialTransactions						tct			WITH (NOLOCK)

						INNER JOIN @tblBranch							tmpb
							ON tmpb.bra_id = tct.bra_id

						INNER JOIN tbDocumentsFile						tdf			WITH (NOLOCK)
							ON	tdf.comp_id = tct.comp_id	AND
								tdf.bra_id	= tct.bra_id	AND
								tdf.df_id	= tct.df_id

						INNER JOIN tbCustomer							tc			WITH (NOLOCK)
						ON	tc.comp_id				= tct.comp_id  AND
							tc.cust_id				= tct.cust_id

						INNER JOIN tbBranch								tb			WITH (NOLOCK)
						ON	tb.comp_id				= tct.comp_id
						AND tb.bra_id				= tct.bra_id

						INNER JOIN tbUser								tu			WITH (NOLOCK)
						ON	tu.[user_id]			= tb.bra_Mailing4CustOverdueDebt_User_id

						INNER JOIN vwCommercialTransactions_forSales	vctfs		WITH (NOLOCK)
						ON vctfs.comp_id			= tct.comp_id
						AND vctfs.bra_id			= tct.bra_id
						AND vctfs.ct_transaction	= tct.ct_transaction

						INNER JOIN tbUsers4BranchFilter					vubf		WITH (NOLOCK)
						ON  vubf.comp_id			= tct.comp_id
						AND vubf.bra_id				= tct.bra_id
						AND vubf.[user_id]			= tb.bra_Mailing4CustOverdueDebt_User_id

						CROSS APPLY dbo.fnCustomer_getBalanceStatus(tct.comp_id, tc.curr_id, tc.cust_id,
																	tb.bra_Mailing4CustOverdueDebt_User_id,
																	tb.bra_processingDate - tb.bra_Mailing4CustOverdueDebt_DateOffset , -1, -1)  fcgbs


				WHERE
				tct.cust_id IS NOT NULL																	AND
				tct.ct_ABalance			<> 0															AND
				CASE -- MOS 01-2023 x FIE y sus forradas Ticket 18153
					WHEN tct.sd_id IN (6,13) AND tct.ct_ATotal < 0 AND tct.ct_ABalance > 0 THEN 0
					WHEN tct.sd_id IN (6,13) AND tct.ct_ATotal > 0 AND tct.ct_ABalance < 0 THEN 0
					ELSE																		1
				END = 1																					AND
				tct.sd_id				< 50															AND
				vctfs.sd_isInBalance	= 'true'														AND
				tdf.bra_Mailing4CustOverdueDebt_ExcludeThisDocument <> 'True'							AND
				IsNull(tc.cust_email,'') <> ''															AND
				tc.cust_email LIKE '%@%'																AND
				tc.cust_email LIKE '%.%'																AND
				(tb.bra_processingDate -  tb.bra_Mailing4CustOverdueDebt_DateOffset) > tct.ct_payDate	AND
				IsNull(tc.cust_judMan,'False')							 = 'false'						AND
				ISNULL(tc.cust_Mailing4CustOverdueDebt_Excluded,'False') = 'False'						AND
				CASE
					WHEN tb.bra_Mailing4CustOverdueDebt_only2PaymentMail <> 1												THEN 1
					WHEN tb.bra_Mailing4CustOverdueDebt_only2PaymentMail = 1 AND ISNULL(tc.cust_email4Payments,'') <> ''	THEN 1
					ELSE																										 0
				END = 1																					AND
				fcgbs.cust_credit_balance_OverCome	> ISNULL(tb.bra_Mailing4CustOverdueDebt_MinValue,0)
				ORDER BY	tct.comp_id,
							tct.bra_id,
							tc.cust_name
							--tct.cust_id



			--SELECT	DISTINCT
			--		tct.comp_id,
			--		tct.bra_id,
			--		tct.cust_id,
			--		tc.cust_name,
			--		CASE
			--			WHEN bra_Mailing4CustOverdueDebt_only2PaymentMail = 1 THEN  tc.cust_contact4Payments
			--			ELSE														dbo.fnSTRContactJoin(tc.cust_contact,tc.cust_contact4Payments,tc.cust_contact4Administration,'','')
			--		END,
			--		CASE
			--			WHEN bra_Mailing4CustOverdueDebt_only2PaymentMail = 1 THEN	tc.cust_email4Payments
			--			ELSE														dbo.fnSTREmailJoin(tc.cust_email,tc.cust_email4Payments,tc.cust_email4Administration,'','')
			--		END	,
			--		tc.curr_id,
			--		tu.user_lastlanguage

			--FROM	tbCommercialTransactions						tct			WITH (NOLOCK)

			--		INNER JOIN tbDocumentsFile						tdf			WITH (NOLOCK)
			--			ON	tdf.comp_id = tct.comp_id	AND
			--				tdf.bra_id	= tct.bra_id	AND
			--				tdf.df_id	= tct.df_id

			--		INNER JOIN tbCustomer							tc			WITH (NOLOCK)
			--		ON	tc.comp_id				= tct.comp_id  AND
			--			tc.cust_id				= tct.cust_id
			--			--IsNull(tc.cust_inactive,'False')						 = 'false'	AND

			--		INNER JOIN tbBranch								tb			WITH (NOLOCK)
			--		ON	tb.comp_id				= tct.comp_id
			--		AND tb.bra_id				= tct.bra_id


			--		INNER JOIN tbUser								tu			WITH (NOLOCK)
			--		ON	tu.[user_id]			= tb.bra_Mailing4CustOverdueDebt_User_id

			--		INNER JOIN vwCommercialTransactions_forSales	vctfs		WITH (NOLOCK)
			--		ON vctfs.comp_id			= tct.comp_id
			--		AND vctfs.bra_id			= tct.bra_id
			--		AND vctfs.ct_transaction	= tct.ct_transaction
			--		AND vctfs.sd_isInBalance	= 'true'


			--		INNER JOIN tbUsers4BranchFilter					vubf		WITH (NOLOCK)
			--		ON  vubf.comp_id			= tct.comp_id
			--		AND vubf.bra_id				= tct.bra_id
			--		AND vubf.[user_id]			= tb.bra_Mailing4CustOverdueDebt_User_id


			--		CROSS APPLY dbo.fnCustomer_getBalanceStatus(tct.comp_id, tc.curr_id, tc.cust_id,
			--													tb.bra_Mailing4CustOverdueDebt_User_id,
			--													tb.bra_processingDate - tb.bra_Mailing4CustOverdueDebt_DateOffset , -1, -1)  fcgbs


			--WHERE
			---- si la diferencia en dias entre la última ejecución del mailing y la fecha actual es mayor o igual
			---- a la periodicidad se ejecuta para esa sucursal

			--(
			--	(
			--			DATEDIFF(DAY,ISNULL(tb.bra_Mailing4CustOverdueDebt_LastExecution,GETDATE()-365),GETDATE())
			--												>= ISNULL(tb.bra_Mailing4CustOverdueDebt_Periodicity,10)
			--			AND
			--			(
			--				tb.bra_Mailing4CustOverdueDebt_dayOfWeek = -1
			--					OR
			--				DATEPART(weekday,tb.bra_processingDate)  = tb.bra_Mailing4CustOverdueDebt_dayOfWeek
			--					OR
			--				DATEPART(weekday,tb.bra_processingDate)  = tb.bra_Mailing4CustOverdueDebt_dayOfWeek2
			--		    )
			--	)
			--	OR @intBraID > 0
			--)

			--AND		CASE
			--			WHEN tb.bra_Mailing4CustOverdueDebt_only2PaymentMail <> 1												THEN 1
			--			WHEN tb.bra_Mailing4CustOverdueDebt_only2PaymentMail = 1 AND ISNULL(tc.cust_email4Payments,'') <> ''	THEN 1
			--			ELSE																										 0
			--		END = 1
			--AND		tct.ct_ABalance						<> 0
			--AND		(tb.bra_processingDate -  tb.bra_Mailing4CustOverdueDebt_DateOffset) > tct.ct_payDate
			--AND		tct.sd_id							< 50
			--AND		fcgbs.cust_credit_balance_OverCome	> ISNULL(tb.bra_Mailing4CustOverdueDebt_MinValue,0)
			--AND		ISNULL(tdf.bra_Mailing4CustOverdueDebt_ExcludeThisDocument,'False') = 'False'
			--AND		ISNULL(tb.bra_Mailing4CustOverdueDebt_Available,'false') = 'true'
			--AND     (@intBraID = -1 OR @intBraID = tb.bra_id)  -- que sea automatico con -1 o pedido desde el sistema
			--AND		ISNULL(tb.bra_disabled,'false') = 'false'
			--AND		IsNull(tc.cust_email,'') <> ''
			--AND		tc.cust_email LIKE '%@%'
			--AND		tc.cust_email LIKE '%.%'
			--AND		IsNull(tc.cust_judMan,'False')							 = 'false'
			--AND		ISNULL(tc.cust_Mailing4CustOverdueDebt_Excluded,'False') = 'False'

			--ORDER BY	tct.comp_id,
			--			tct.bra_id,
			--			tct.cust_id



			OPEN		CURSOR_CUSTOMERS
			FETCH		CURSOR_CUSTOMERS
				INTO		@comp_id, @bra_id, @cust_id, @cust_name,@cust_contact, @cust_email, @curr_id,
							@lang_id



			--se genera la fila de títulos de las grillas de comprobantes
			SET		@tableheader =					'<tr style="font-weight:bold;">'
			SELECT	@tableheader = @tableheader +	'<td style="border-radius:4px;" align="center">' + isnull(tut.utexts_desc,'') + '</td>' FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id =  10103
			SELECT	@tableheader = @tableheader +	'<td style="border-radius:4px;" align="center">' + isnull(tut.utexts_desc,'') + '</td>' FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id =  10104
			SELECT	@tableheader = @tableheader +	'<td style="border-radius:4px;" align="center">' + isnull(tut.utexts_desc,'') + '</td>' FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id =  10105
			SELECT	@tableheader = @tableheader +	'<td style="border-radius:4px;" align="right">'  + isnull(tut.utexts_desc,'') + '</td>' FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id =  10106
			SELECT	@tableheader = @tableheader +	'<td style="border-radius:4px;" align="right">'  + isnull(tut.utexts_desc,'') + '</td>' FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id =  10107
			SELECT	@tableheader = @tableheader +	'<td style="border-radius:4px;" align="center">' + isnull(tut.utexts_desc,'') + '</td>' FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id =  10108
			SELECT	@tableheader = @tableheader +	'<td></td></tr>'





			SET @comp_id_ant	= 0
			SET @bra_id_ant		= 0


			DECLARE @bitMustSendEmail AS BIT = 'False'
			WHILE @@FETCH_STATUS = 0
			BEGIN

				SET @bitMustSendEmail = 'False'

				---------------------------------------------------------------------------------------------------------
				--enviar correo a cada cliente con deuda pendiente vencida

--==
--SELECT @cust_id,@cust_name,@cust_contact
--==

				DECLARE @bra_Mailing4CustOverdueDebt_curr_id_Additional AS INT = 2		-- Conf en Sucursal


				--recuperamos todos los datos necesarios de la sucursal
				SELECT	@bra_Mailing4CustOverdueDebt_BodyInitialMessage	= isnull(tb.bra_Mailing4CustOverdueDebt_BodyInitialMessage,''),
						@bra_Mailing4CustOverdueDebt_BodyFinalMessage	= isnull(tb.bra_Mailing4CustOverdueDebt_BodyFinalMessage,''),
						@bra_Mailing4CustOverdueDebt_Subject            = tb.bra_Mailing4CustOverdueDebt_Subject,
						@bra_Mailing4CustOverdueDebt_FromEmail			= tb.bra_Mailing4CustOverdueDebt_FromEmail,
						@bra_Mailing4CustOverdueDebt_BlindCopy			= ISNULL(tb.bra_Mailing4CustOverdueDebt_blind_copy_recipients,''),
						@bra_MainDesc									= isnull(tb.bra_MainDesc2,''),
						@bra_address									= isnull(tb.bra_address,''),
						@bra_address1									= isnull(tb.bra_address1,''),
						@bra_phone										= isnull(tb.bra_phone,''),
						@bra_zip										= ISNULL(tb.bra_zip,''),
						@country_desc									= ISNULL(tc.country_desc,''),
						@state_desc										= ISNULL(ts.state_desc,''),
						@user_id										= tb.bra_Mailing4CustOverdueDebt_User_id ,
						@strbra_Mailing4CustOverdueDebt_Mail4AdditionalSend =	IsNull(tb.bra_Mailing4CustOverdueDebt_Mail4AdditionalSend,''),
						@bra_Mailing4CustOverdueDebt_curr_id_Additional =	CASE
																				WHEN tb.bra_Mailing4CustOverdueDebt_curr_id_Additional =	tb.curr_id THEN NULL
																				ELSE																		tb.bra_Mailing4CustOverdueDebt_curr_id_Additional
																			END


				FROM	tbBranch								tb		WITH (NOLOCK)
						LEFT JOIN tbsysCountry					tc		WITH (NOLOCK)
						ON	tc.country_id	= tb.country_id
						LEFT JOIN tbsysState					ts		WITH (NOLOCK)
						ON	ts.country_id	= tb.country_id
						AND ts.state_id		= tb.state_id

				WHERE	tb.comp_id	= @comp_id
				AND		tb.bra_id	= @bra_id




				--armamos el subject con la descripción de la sucursal + el texto 10101 de la tbsysUniqueTexts
				SELECT	@subject	= IsNull(@bra_Mailing4CustOverdueDebt_Subject,@bra_MainDesc + ' - ' + tut.utexts_desc)
					FROM	tbsysUniqueTexts		tut		WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id
					AND		tut.utexts_id	= 10101
					--SELECT	'1' [ ], @subject




				--armamos el header del correo con la descripción sucursal y un par de renglones en blanco
				SET	@bodyHeader		=	'<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
										'<b>' + @bra_MainDesc + '</b><br /><br /><br />'




				--agregamos al header el nombre del cliente
				SELECT	@bodyHeader		=	@bodyHeader + tut.utexts_desc + dbo.fnSTRContactJoin( @cust_name,@cust_contact,'','','') + '<br /><br />'
					FROM	tbsysUniqueTexts	tut			WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id
					AND		tut.utexts_id	= 10109




				--se agrega un mensaje del tipo: "se detallan los comprobantes pendientes de pago"
				SET	@bodyHeader		=	@bodyHeader + @bra_Mailing4CustOverdueDebt_BodyInitialMessage + '<br /><br /><br />'
				--SELECT '2' [ ], @bodyHeader





				SET @lFirstTime = 'true'




				--nro compobante, fecha emision, fecha vencimiento, importe total, saldo y moneda
				DECLARE CURSOR_CustOverdueDebt CURSOR LOCAL FAST_FORWARD FOR
				SELECT	'<tr><td style="border-radius:4px;" align="center">' +
						dbo.fnGetCommercialTransactionDescription(tct.comp_id, 2, tct.ct_transaction) +
						'</td><td style="border-radius:4px;"  align="center">' +
						convert(varchar,DATEPART(DAY  ,tct.ct_date)) + '/' +
						convert(varchar,DATEPART(MONTH,tct.ct_date)) + '/' +
						convert(varchar,DATEPART(YEAR ,tct.ct_date)) +
						'</td><td style="border-radius:4px;"  align="center">' +
						convert(varchar,DATEPART(DAY  ,tct.ct_payDate)) + '/' +
						convert(varchar,DATEPART(MONTH,tct.ct_payDate)) + '/' +
						convert(varchar,DATEPART(YEAR ,tct.ct_payDate)) +
						--



						-- --------------------------------------
						CASE	-- FIESA 05-2021, ticket 11892
						-- --------------------------------------
							-- Si tiene definido una Moneda Alternativa y es la del tipo de cambio del documento . . .
							WHEN @bra_Mailing4CustOverdueDebt_curr_id_Additional IS NOT NULL AND
								 @bra_Mailing4CustOverdueDebt_curr_id_Additional =
																					CASE
																						WHEN tct.sd_id IN (6,7,13) THEN	tct.curr_id4Exchange
																						ELSE							tct.curr_id4dfExchange
																					END
								     THEN
											'</td><td style="border-radius:4px;"  align="right">' +
											CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),
											vctfs.PlusOrMinus *
											(
												tct.ct_ATotal
												/ dbo.fnNoZDiv(	-- FIESA  05-2021  11891
																	CASE
																		WHEN tct.sd_id IN (6,7,13) THEN	ct_curr_IdExchange
																		ELSE							tct.ct_dfExchange
																	END
															  )
											))) +
											'</td><td style="border-radius:4px;"  align="right">' +
											CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),
											vctfs.PlusOrMinus *
											(
												tct.ct_ABalance
												/ dbo.fnNoZDiv(	-- FIESA  05-2021  11891
																	CASE
																		WHEN tct.sd_id IN (6,7,13) THEN	ct_curr_IdExchange
																		ELSE							tct.ct_dfExchange
																	END
															  )
											))) +
											'</td><td style="border-radius:4px;"  align="center">' +
											ltrim(rtrim(tc2.curr_symbol))
							ELSE			-- Modo Normal del Maiuling de Deuda
											'</td><td style="border-radius:4px;"  align="right">' +
											CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),
											vctfs.PlusOrMinus *
											dbo.fnGetExchange2(tct.comp_id, tct.ct_ATotal,   tct.ct_ACurrency, tct.curr_id_transaction, 0, 0, 0, 'false'))) +
											'</td><td style="border-radius:4px;"  align="right">' +
											CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),
											vctfs.PlusOrMinus *
											dbo.fnGetExchange2(tct.comp_id, tct.ct_ABalance, tct.ct_ACurrency, tct.curr_id_transaction, 0, 0, 0, 'false')))	+
											'</td><td style="border-radius:4px;"  align="center">' +
											ltrim(rtrim(tc.curr_symbol))
						END +
						-- --------------------------------------
						-- FIESA 05-2021, ticket 11892
						-- --------------------------------------

						'</td>' +
						 CASE
							WHEN EXISTS(
											SELECT TOP 1 1
												FROM tbCreditCard_VoucherRelations	AS tccvr	WITH (NOLOCK)
												INNER JOIN tbCreditCard_Voucher		AS tccv		WITH (NOLOCK)
													ON	tccv.comp_id			= tccvr.comp_id			AND
														tccv.ccv_id				= tccvr.ccv_id
												WHERE	tccvr.comp_id			= tct.comp_id			AND
														tccvr.ct_transaction	= tct.ct_transaction	AND
														tccv.ccv_MPBotonDePagoIsExpired = 0				AND
														tdf.sd_id IN (1,4)
							)
								THEN REPLACE('<td style="border-radius:4px;" align="center">&nbsp;<a href="init_point" target="_blank"  ><img width="90px" src="https://www.globalbluepoint.com/App_Images/PagarAqui.png" title="Pagar mediante Botón de Pago. El pago ingresará automáticamente a su cuenta." alt="Pagar mediante Botón de Pago. El pago ingresará automáticamente a su cuenta." /></a>&nbsp;</td>' ,  'init_point',
									          dbo.fnStrAllTrim( (
																	SELECT TOP 1 tccv.ccv_MPBotonDePagoLinkButton
																		FROM tbCreditCard_VoucherRelations	AS tccvr	WITH (NOLOCK)
																		INNER JOIN tbCreditCard_Voucher		AS tccv		WITH (NOLOCK)
																			ON	tccv.comp_id			= tccvr.comp_id			AND
																				tccv.ccv_id				= tccvr.ccv_id
																		WHERE	tccvr.comp_id			= tct.comp_id			AND
																				tccvr.ct_transaction	= tct.ct_transaction	AND
																				tccv.ccv_MPBotonDePagoIsExpired = 0
																		ORDER BY	CASE
																						WHEN tccvr.ctl_id IS NOT NULL THEN  0
																						ELSE								1
																					END

											        		  ))
											)
								ELSE '<td></td>'
						 END +
						'</tr>'

				FROM	tbCommercialTransactions						tct		WITH (NOLOCK)

						INNER JOIN tbBranch								tb		WITH (NOLOCK)
						ON	tb.comp_id				= tct.comp_id
						AND tb.bra_id				= tct.bra_id


						INNER JOIN tbsysCurrency						tc		WITH (NOLOCK)
						ON tc.curr_id = tct.curr_id_transaction

						-- --------------------------
						-- FIESA
						-- --------------------------
						LEFT JOIN tbsysCurrency AS tc2
							ON	 @bra_Mailing4CustOverdueDebt_curr_id_Additional =
																					CASE
																						WHEN tct.sd_id IN (6,7,13) THEN	tct.curr_id4Exchange
																						ELSE							tct.curr_id4dfExchange
																					END AND
								tc2.curr_id = @bra_Mailing4CustOverdueDebt_curr_id_Additional
						-- --------------------------

						INNER JOIN vwCommercialTransactions_forSales	vctfs	WITH (NOLOCK)
						ON	vctfs.comp_id			= tct.comp_id
						AND vctfs.bra_id			= tct.bra_id
						AND vctfs.ct_transaction	= tct.ct_transaction


						INNER JOIN tbUsers4BranchFilter					vubf	WITH (NOLOCK)
						ON  vubf.comp_id			= tct.comp_id
						AND vubf.bra_id				= tct.bra_id
						AND vubf.[user_id]			= tb.bra_Mailing4CustOverdueDebt_User_id

						INNER JOIN tbDocumentsFile tdf							WITH (NOLOCK)
							ON	tdf.comp_id = tct.comp_id	AND
								tdf.bra_id	= tct.bra_id	AND
								tdf.df_id	= tct.df_id

						INNER JOIN tbCustomer AS tc3							WITH (NOLOCK)
							ON	tc3.comp_id = tct.comp_id AND
								tc3.cust_id = tct.cust_Id

				WHERE	tct.comp_id			= @comp_id
				AND		tct.bra_id			= @bra_id
				AND		vctfs.sd_isInBalance= 'true'
				AND 	tct.ct_ABalance		<> 0
				AND		CASE -- MOS 01-2023 x FIE y sus forradas Ticket 18153
							WHEN tct.sd_id IN (6,13) AND tct.ct_ATotal < 0 AND tct.ct_ABalance > 0 THEN 0
							WHEN tct.sd_id IN (6,13) AND tct.ct_ATotal > 0 AND tct.ct_ABalance < 0 THEN 0
							ELSE																		1
						END = 1
				AND		tct.ct_payDate		< tb.bra_processingDate
				AND		tct.cust_id			= @cust_id
				AND		tct.sd_id			< 50
				AND     ISNULL(tb.bra_Mailing4CustOverdueDebt_Available,'false')= 'true'
				AND		ISNULL(tb.bra_disabled,'false') = 'false'
				AND		ISNULL(tdf.bra_Mailing4CustOverdueDebt_ExcludeThisDocument,'False') = 'False'
				AND		ISNULL(tc3.cust_Mailing4CustOverdueDebt_Excluded,'False') = 'False'

				ORDER BY	tct.ct_payDate



				OPEN CURSOR_CustOverdueDebt

				FETCH CURSOR_CustOverdueDebt INTO @lCustOverdueDebt

				SET @bodyCustOverdueDebt = ''

				WHILE @@FETCH_STATUS = 0
				BEGIN

					IF @lFirstTime = 'true'
					BEGIN

						--título comprobantes vencidos
						SELECT	@bodyCustOverdueDebt	= '<b>' + tut.utexts_desc + '</b><br />'
							FROM	tbsysUniqueTexts		tut		WITH (NOLOCK)
							WHERE	tut.lang_id		= @lang_id
							AND		tut.utexts_id	= 10101


						BEGIN TRY
							SET @bodyCustOverdueDebt = @bodyCustOverdueDebt +
								'<table style="font-family:Verdana;font-size:x-small;color:Black;border-radius:8px;cellpadding="3" cellspacing="5" border="6"  BORDERCOLOR="#666666" BORDERCOLORLIGHT="#8c8c8c" BORDERCOLORDARK="#404040">' + ltrim(rtrim(@tableheader))

								--'<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
								--'cellpadding="1" cellspacing="1" border="1">' + ltrim(rtrim(@tableheader))
						END TRY
						BEGIN CATCH
						END CATCH

						SET @lFirstTime = 'false'

					END

					SET @bitMustSendEmail = 'True'

					BEGIN TRY
						SET @bodyCustOverdueDebt = @bodyCustOverdueDebt + @lCustOverdueDebt
					END TRY
					BEGIN CATCH
					END CATCH


					FETCH CURSOR_CustOverdueDebt INTO @lCustOverdueDebt

				END


				IF @lFirstTime = 'false'
					BEGIN
						BEGIN TRY
							SET @bodyCustOverdueDebt = @bodyCustOverdueDebt + '</table><br /><br />'
						END TRY
						BEGIN CATCH
						END CATCH
					END



				CLOSE CURSOR_CustOverdueDebt
				DEALLOCATE CURSOR_CustOverdueDebt



				SET @lFirstTime = 'true'




				--nro componabte, fecha emision, fecha vencimiento, importe total, saldo y moneda
				DECLARE CURSOR_CustOverdueDebt CURSOR LOCAL  FAST_FORWARD FOR
				SELECT	'<tr><td style="border-radius:4px;"  align="center">' +
						dbo.fnGetCommercialTransactionDescription(tct.comp_id, 2, tct.ct_transaction) +
						'</td><td style="border-radius:4px;"  align="center">' +
						convert(varchar,DATEPART(DAY  ,tct.ct_date)) + '/' +
						convert(varchar,DATEPART(MONTH,tct.ct_date)) + '/' +
						convert(varchar,DATEPART(YEAR ,tct.ct_date)) +
						'</td><td style="border-radius:4px;"  align="center">' +
						convert(varchar,DATEPART(DAY  ,tct.ct_payDate)) + '/' +
						convert(varchar,DATEPART(MONTH,tct.ct_payDate)) + '/' +
						convert(varchar,DATEPART(YEAR ,tct.ct_payDate)) +
						--'</td><td style="border-radius:4px;"  align="right">' +
						--CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),
						--dbo.fnGetExchange2(tct.comp_id, tct.ct_ATotal,   tct.ct_ACurrency, tct.curr_id_transaction, 0, 0, 0, 'false'))) +
						--'</td><td style="border-radius:4px;"  align="right">' +
						--CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),
						--dbo.fnGetExchange2(tct.comp_id, tct.ct_ABalance, tct.ct_ACurrency, tct.curr_id_transaction, 0, 0, 0, 'false'))) +


						-- --------------------------------------
						CASE	-- FIESA 05-2021, ticket 11892
						-- --------------------------------------
							-- Si tiene definido una Moneda Alternativa y es la del tipo de cambio del documento . . .
							WHEN @bra_Mailing4CustOverdueDebt_curr_id_Additional IS NOT NULL AND
								 @bra_Mailing4CustOverdueDebt_curr_id_Additional =
																					CASE
																						WHEN tct.sd_id IN (6,7,13) THEN	tct.curr_id4Exchange
																						ELSE							tct.curr_id4dfExchange
																					END
								     THEN
											'</td><td style="border-radius:4px;"  align="right">' +
											CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),
											vctfs.PlusOrMinus *
											(
												tct.ct_ATotal
												/ dbo.fnNoZDiv(	-- FIESA  05-2021  11891
																	CASE
																		WHEN tct.sd_id IN (6,7,13) THEN	ct_curr_IdExchange
																		ELSE							tct.ct_dfExchange
																	END
															  )
											))) +
											'</td><td style="border-radius:4px;"  align="right">' +
											CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),
											vctfs.PlusOrMinus *
											(
												tct.ct_ABalance
												/ dbo.fnNoZDiv(	-- FIESA  05-2021  11891
																	CASE
																		WHEN tct.sd_id IN (6,7,13) THEN	ct_curr_IdExchange
																		ELSE							tct.ct_dfExchange
																	END
															  )
											))) +
											'</td><td style="border-radius:4px;"  align="center">' +
											ltrim(rtrim(tc2.curr_symbol))
							ELSE			-- Modo Normal del Maiuling de Deuda
											'</td><td style="border-radius:4px;"  align="right">' +
											CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),
											vctfs.PlusOrMinus *
											dbo.fnGetExchange2(tct.comp_id, tct.ct_ATotal,   tct.ct_ACurrency, tct.curr_id_transaction, 0, 0, 0, 'false'))) +
											'</td><td style="border-radius:4px;"  align="right">' +
											CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),
											vctfs.PlusOrMinus *
											dbo.fnGetExchange2(tct.comp_id, tct.ct_ABalance, tct.ct_ACurrency, tct.curr_id_transaction, 0, 0, 0, 'false')))	+
											'</td><td style="border-radius:4px;"  align="center">' +
											ltrim(rtrim(tc.curr_symbol))
						END +
						-- --------------------------------------
						-- FIESA 05-2021, ticket 11892
						-- --------------------------------------


						'</td>' +
						 CASE
							WHEN EXISTS(
											SELECT TOP 1 1
												FROM tbCreditCard_VoucherRelations	AS tccvr	WITH (NOLOCK)
												INNER JOIN tbCreditCard_Voucher		AS tccv		WITH (NOLOCK)
													ON	tccv.comp_id			= tccvr.comp_id			AND
														tccv.ccv_id				= tccvr.ccv_id
												WHERE	tccvr.comp_id			= tct.comp_id			AND
														tccvr.ct_transaction	= tct.ct_transaction	AND
														tccv.ccv_MPBotonDePagoIsExpired = 0				AND
														tdf.sd_id IN (1,4)
							)
								THEN REPLACE('<td style="border-radius:4px;" align="center">&nbsp;<a href="init_point" target="_blank"  ><img width="90px" src="https://www.globalbluepoint.com/App_Images/PagarAqui.png" title="Pagar mediante Botón de Pago. El pago ingresará automáticamente a su cuenta." alt="Pagar mediante Botón de Pago. El pago ingresará automáticamente a su cuenta." /></a>&nbsp;</td>' ,  'init_point',
									          dbo.fnStrAllTrim( (
																	SELECT TOP 1 tccv.ccv_MPBotonDePagoLinkButton
																		FROM tbCreditCard_VoucherRelations	AS tccvr	WITH (NOLOCK)
																		INNER JOIN tbCreditCard_Voucher		AS tccv		WITH (NOLOCK)
																			ON	tccv.comp_id			= tccvr.comp_id			AND
																				tccv.ccv_id				= tccvr.ccv_id
																		WHERE	tccvr.comp_id			= tct.comp_id			AND
																				tccvr.ct_transaction	= tct.ct_transaction	AND
																				tccv.ccv_MPBotonDePagoIsExpired = 0
																		ORDER BY	CASE
																						WHEN tccvr.ctl_id IS NOT NULL THEN  0
																						ELSE								1
																					END

											        		  ))
											)
							ELSE '<td></td>'
						 END +
						'</tr>'

				FROM	tbCommercialTransactions						tct		WITH (NOLOCK)

						INNER JOIN tbBranch								tb		WITH (NOLOCK)
						ON	tb.comp_id				= tct.comp_id
						AND tb.bra_id				= tct.bra_id


						INNER JOIN tbsysCurrency						tc		WITH (NOLOCK)
						ON tc.curr_id = tct.curr_id_transaction
						-- --------------------------
						-- FIESA
						-- --------------------------
						LEFT JOIN tbsysCurrency AS tc2
							ON	 @bra_Mailing4CustOverdueDebt_curr_id_Additional =
																					CASE
																						WHEN tct.sd_id IN (6,7,13) THEN	tct.curr_id4Exchange
																						ELSE							tct.curr_id4dfExchange
																					END AND
								tc2.curr_id = @bra_Mailing4CustOverdueDebt_curr_id_Additional
						-- --------------------------


						INNER JOIN vwCommercialTransactions_forSales	vctfs	WITH (NOLOCK)
						ON	vctfs.comp_id			= tct.comp_id
						AND vctfs.bra_id			= tct.bra_id
						AND vctfs.ct_transaction	= tct.ct_transaction


						INNER JOIN tbUsers4BranchFilter					vubf	WITH (NOLOCK)
						ON  vubf.comp_id			= tct.comp_id
						AND vubf.bra_id				= tct.bra_id
						AND vubf.[user_id]			= tb.bra_Mailing4CustOverdueDebt_User_id

						INNER JOIN tbDocumentsFile tdf							WITH (NOLOCK)
							ON	tdf.comp_id = tct.comp_id	AND
								tdf.bra_id	= tct.bra_id	AND
								tdf.df_id	= tct.df_id

				WHERE	tct.comp_id			= @comp_id
				AND		tct.bra_id			= @bra_id
				AND		vctfs.sd_isInBalance= 'true'
				AND		tct.ct_ABalance		<> 0
				AND		tct.ct_payDate	    >= tb.bra_processingDate
				AND		tct.cust_id			=  @cust_id
				AND		tct.sd_id			<  50
				AND     ISNULL(tb.bra_Mailing4CustOverdueDebt_Available,'false')= 'true'
				AND		ISNULL(tb.bra_disabled,'false') = 'false'
				AND		ISNULL(tdf.bra_Mailing4CustOverdueDebt_ExcludeThisDocument,'False') = 'False'

				ORDER BY	tct.ct_payDate


				OPEN CURSOR_CustOverdueDebt

				FETCH CURSOR_CustOverdueDebt INTO @lCustNotOverdueDebt


				SET @bodyCustNotOverdueDebt = ''


				WHILE @@FETCH_STATUS = 0
				BEGIN

					IF @lFirstTime = 'true'
					BEGIN


						--título comprobantes no vencidos
						SELECT	@bodyCustNotOverdueDebt	= '<b>' + tut.utexts_desc + '</b><br />'
							FROM	tbsysUniqueTexts		tut			WITH (NOLOCK)
							WHERE	tut.lang_id		= @lang_id
							AND		tut.utexts_id	= 10102


						BEGIN TRY
							SET @bodyCustNotOverdueDebt = @bodyCustNotOverdueDebt +
								'<table style="font-family:Verdana;font-size:x-small;color:Black;border-radius:8px;cellpadding="3" cellspacing="5" border="6"  BORDERCOLOR="#666666" BORDERCOLORLIGHT="#8c8c8c" BORDERCOLORDARK="#404040">' + ltrim(rtrim(@tableheader))



								--'<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
								--'cellpadding="1" cellspacing="1" border="1">' + ltrim(rtrim(@tableheader))
						END TRY
						BEGIN CATCH
						END CATCH

						SET @lFirstTime = 'false'

					END

					SET @bitMustSendEmail = 'True'

					BEGIN TRY
						SET @bodyCustNotOverdueDebt = @bodyCustNotOverdueDebt + @lCustNotOverdueDebt
					END TRY
					BEGIN CATCH
					END CATCH

					FETCH CURSOR_CustOverdueDebt INTO @lCustNotOverdueDebt
				END


				IF @lFirstTime = 'false'
					BEGIN
						BEGIN TRY
							SET @bodyCustNotOverdueDebt = @bodyCustNotOverdueDebt + '</table><br /><br />'
						END TRY
						BEGIN CATCH
						END CATCH
					END





				CLOSE CURSOR_CustOverdueDebt
				DEALLOCATE CURSOR_CustOverdueDebt

				--SELECT @bodyCustNotOverdueDebt





				--datos de la sucursal que se cargan en el footer
				BEGIN TRY
					SELECT	@bodyFooter =	@bra_Mailing4CustOverdueDebt_BodyFinalMessage + '<br /><br /><br />' +
											'<b>' + @bra_MainDesc + '</b><br />' +
	--										@bra_address			+ '<br />' +
	--										@bra_address1			+ '<br />' +
	--										@bra_zip + ' - ' + @state_desc + ' - ' + @country_desc + '<br />' +
											@bra_phone				+ '<br /><br /><br />'
				END TRY
				BEGIN CATCH
				END CATCH




				--se envía el correo si se recuperaron direcciones de emails
				SET @body = ''
				BEGIN TRY
					SET @body = @bodyHeader + @bodyCustOverdueDebt + @bodyCustNotOverdueDebt + @bodyFooter
				END TRY
				BEGIN CATCH
				END CATCH
				--SELECT LEN(@bodyHeader),LEN(@bodyCustOverdueDebt),LEN(@bodyCustNotOverdueDebt),LEN(@bodyFooter), LEN(@body), LEN(@tableheader)



				-- MOS 02-2022: Es al PEDO ya que ahora TODO va x Cola de envío y ahí va ael tiempo entre emails.
				-- -----------------------------------------
				-- Setea el tiempo de espera entre emails
				-- -----------------------------------------
				--DECLARE @intWaitTime AS INT
				--DECLARE @strWaitTime AS CHAR(8)
				--SELECT  @intWaitTime = ISNULL(tb.bra_Mailing4CustOverdueDebt_WaitTimeBetweenMailsInSeconds,0)
				--	FROM tbBranch tb		WITH (NOLOCK)
				--	WHERE	tb.comp_id	= @comp_id AND
				--			tb.bra_id	= @bra_id

				--IF  @intWaitTime > 30 SET @intWaitTime = 30
				--SET @strWaitTime = CONVERT(CHAR(2),@intWaitTime)
				--SET @strWaitTime = dbo.fnStrAllTrim(@strWaitTime)
				--SET @strWaitTime = dbo.fnStrPADL(@strWaitTime,2,'0')
				--SET @strWaitTime = '00:00:' + @strWaitTime
				-- -----------------------------------------

				SET @bra_Mailing4CustOverdueDebt_FromEmail = LOWER(dbo.fnStrAllTrim(ISNULL(@bra_Mailing4CustOverdueDebt_FromEmail,'')))

--==
--SELECT @cust_id, @cust_name
--==


				BEGIN TRY
					--si el email del cliente está informado se envía el correo
					IF NOT	@cust_email IS NULL AND
							@bitMustSendEmail = 'True'
						BEGIN
							EXEC spSystem_sendEMail
													@comp_id,
													@cust_email ,
													@strbra_Mailing4CustOverdueDebt_Mail4AdditionalSend  ,
													@subject,
													'HTML',
													@body ,
													'',
													@bra_Mailing4CustOverdueDebt_FromEmail,
													@bra_Mailing4CustOverdueDebt_BlindCopy,
													@user_id

							 --WAITFOR DELAY @strWaitTime;
						END
				END TRY
				BEGIN CATCH
					-- gRABAR EN EL LOG LOS EMAILS QUE POR EEORES NO SE ENVIAN.-
					-- Variables disponibles: @cust_id,@cust_email

					declare
						@msg1		varchar(200),
						@msg2		varchar(200),
						@lCustName	varchar(200)

						set @msg1		= ''
						set @msg2		= ''
						set @lCustName	= ''
					--OBTENEMOS LOS MENSAJES Y DATOS DEL CLIENTE AL QUE NO SE LE PUDO ENVIAR
					select @msg1		= tut.utexts_desc	from tbsysUniqueTexts	tut	where tut.lang_id = @lang_id and tut.utexts_id = 224035
					select @msg2		= tut.utexts_desc	from tbsysUniqueTexts	tut	where tut.lang_id = @lang_id and tut.utexts_id = 224036
					select @lCustName	= tc.cust_name		from tbCustomer			tc	where tc.cust_id  = @cust_id

					set @msg1 = @msg1 + ' ' + @lCustName
					set @msg2 = @msg2 + ' ' + @cust_email


					insert into tbSecurityLog
					(
						comp_id,
						bra_id,
						user_id,
						-- seclog_id -- this column value is auto-generated,
						seclog_obs_1,
						seclog_obs_2,
						seclog_obs_3,
						seclog_obs_4,
						seclog_cd,
						--aut_id,
						sysCode_id,
						--menu_id,
						--menu_ts,
						--request_ip,
						--request_name,
						--aure_isok,
						--aure_user_id,
						--seclog_pageHTML,
						prof_id
						--aure_cd,
						--aure_id,
						--seclog_id1,
						--seclog_id2,
						--seclog_id3
					)
					VALUES
					(
						@comp_id,
						@bra_id,
						@user_id,
						@msg1,
						@msg2,
						NULL,
						NULL,
						getdate(),
						1500,			--ID PARA ERRORES DE ENVIO DE CORRECO ELECTRONICO
						@prof_id
					)


				END CATCH


				--actualizar la tbsecuritylog y tbbranch para cada compañía / sucursal
				IF @comp_id <> @comp_id_ant OR @bra_id <> @bra_id_ant
				BEGIN

					SELECT	@prof_id	= tucp.prof_id
						FROM	tbUser		tu							WITH (NOLOCK)
								INNER JOIN tbUserCompanyProfile tucp	WITH (NOLOCK)
								ON	tucp.[user_id]	= tu.[user_id]
								AND tucp.bra_id		= @bra_id
								AND tucp.comp_id	= @comp_id
						WHERE	tu.[user_id]	= @user_id



					SELECT	@seclog_obs_1	= tut.utexts_desc
						FROM	tbsysUniqueTexts		tut				WITH (NOLOCK)
						WHERE	tut.lang_id		= @lang_id
						AND		tut.utexts_id	= 10110



					EXEC dbo.spSecurityLog_insertData @comp_id, @bra_id, @user_id,
													  @seclog_obs_1, '',
													  '', '', NULL,
													  1000, NULL, NULL,
													  NULL, NULL, NULL,
													  @prof_id,
													  NULL,	NULL,
													  NULL,	NULL, NULL,	NULL,
													  @return_value	= @rv OUTPUT




					UPDATE	tbBranch		WITH (ROWLOCK)
					SET		bra_Mailing4CustOverdueDebt_LastExecution = GETDATE()
					WHERE	comp_id		= @comp_id
					AND		bra_id		= @bra_id



					SET @comp_id_ant	= @comp_id
					SET @bra_id_ant		= @bra_id

				END




				---------------------------------------------------------------------------------------------------------
				FETCH	CURSOR_CUSTOMERS
				INTO	@comp_id, @bra_id, @cust_id, @cust_name,@cust_contact, @cust_email, @curr_id,
						@lang_id



			END

			CLOSE		CURSOR_CUSTOMERS
			DEALLOCATE	CURSOR_CUSTOMERS



	END

	ELSE

	BEGIN

		IF EXISTS	(SELECT TOP 1  1	FROM	tbBranch tb		WITH (NOLOCK)
					  WHERE		ISNULL(tb.bra_Mailing4CustOverdueDebt_Available,'false')	= 'true'
					    AND		ISNULL(tb.bra_disabled,'false') = 'false'
						AND		tb.bra_Mailing4CustOverdueDebt_User_id						IS NULL)
		BEGIN





			--si está habilitado el envío de mailing para clientes con deuda vencida y no tiene definido un usuario
			--se genera un log del para dejar constancia del error

			SELECT	@comp_id	= tu.user_lastcompany,
					@bra_id		= tu.user_lastbranch,
					@user_id	= tu.[user_id],
					@lang_id	= tu.user_lastlanguage,
					@prof_id	= tu.user_lastprofile
				FROM	tbUser					tu			WITH (NOLOCK)
				WHERE	UPPER(tu.user_nick) = UPPER('erpadmin')



			SELECT	@seclog_obs_1	= tut.utexts_desc
				FROM	tbsysUniqueTexts		tut		WITH (NOLOCK)
				WHERE	tut.lang_id		= @lang_id
				AND		tut.utexts_id	= 10100



			EXEC dbo.spSecurityLog_insertData	@comp_id,
												@bra_id,
												@user_id,
												@seclog_obs_1,
												'',
												'',
												'',
												null,
												1000,
												null,
												null,
												null, null, null,
												@prof_id,
												NULL,	NULL,
												NULL,	NULL, NULL,	NULL,
												@return_value	= @rv OUTPUT


		END

	END

	--END

END
GO







CREATE PROCEDURE [dbo].[spCommercialTransactions_CheckBalance]
AS

SET NOCOUNT ON


DECLARE	@cust_id	INT,
		@comp_id	INT,
		@bra_id		INT,
		@balance1	DECIMAL(19,5),
		@balance2	DECIMAL(19,5),
		@id			VARCHAR(20)
SELECT @comp_id = 1, @bra_id = -1


--IF NOT OBJECT_ID('tempdb.dbo.#tmpresultados')		IS NULL DROP TABLE #tmpresultados
--CREATE TABLE #tmpresultados
--(
--	[cust_id]				INT,
--	[resultado]				VARCHAR(5),
--	[balance]				DECIMAL(18,5),
--	[sumatoria_Abalance]	DECIMAL(18,5)
--)


DELETE FROM tbSystem_FixDatabase_1


IF NOT OBJECT_ID('tempdb.dbo.#tmpprueba')		IS NULL DROP TABLE #tmpprueba
CREATE TABLE #tmpprueba (
	[1] int,[2] int,[3] int,[4] int,[5] int,[6] int,[7] VARCHAR,[8] VARCHAR,
	[comp_id] int,[bra_id] int,[sd_desc] VARCHAR(500),[ct_transaction] int,[doc_number] VARCHAR(500),[ct_docNumber] VARCHAR(50),
	[ct_date] datetime,	[ct_taxDate] datetime,
	[ct_payDate] datetime,[supp_id] int,[cust_id] int,[cb_id] int,[user_id] int,[ct_subtotal] DECIMAL(18,5),[ct_total] DECIMAL(18,5),
	[ct_discount] DECIMAL(18,5),[ct_taxes] DECIMAL(18,5),
	[curr_id_transaction] int,[hacc_transaction] int,[disc_id] int,[ct_ATotal] DECIMAL(18,5),[ct_Credits] DECIMAL(18,5),[ct_ABalance] DECIMAL(18,5),
	[Balance] DECIMAL(18,5),
	[ct_ACurrency] int,[ct_ACurrencyExchange] DECIMAL(18,5),[branch_ACurrency] DECIMAL(18,5),[doc_ACurrencyExchange] DECIMAL(18,5),
	[doc_dfExchange] VARCHAR(500),
	[ct_A_Total_dfExchange] VARCHAR(500),[df_id] int,[dl_id] int,[st_id] int,[sd_id] int,[puco_id] int,[sm_id] int,[sm_name] VARCHAR(500),
	[st_desc] VARCHAR(500),
	[ct_CompanyCurrency] int,[ct_Branch2CompanyCurrencyExchange] DECIMAL(18,5),[ct_adjust] DECIMAL(18,5),[custb_name] VARCHAR(500),
	[ct_cd] datetime,[user_name] VARCHAR(500),
	[soh_id_fromGenerated] VARCHAR(500),[ID] VARCHAR(50), [dl_name] NVARCHAR(500)
)



DECLARE @datetime	DATETIME
SET		@datetime	= GETDATE()


DECLARE cursor_clientes cursor FOR
SELECT  DISTINCT
		tct.cust_id--,
		--tct.comp_id,
		--tct.bra_id
FROM	tbCommercialTransactions tct

		--no toma en cuenta los clientes que está marcados para carga inicial de valores
		INNER JOIN tbCustomer tc
		ON tc.comp_id = tct.comp_id
		AND tc.cust_id = tct.cust_id
		AND ISNULL(tc.cust_4InitialValues,'false') = 'false'

WHERE not tct.cust_id IS NULL
ORDER BY tct.cust_id

OPEN	cursor_clientes

FETCH	cursor_clientes INTO @cust_id

SELECT ' Verificando cuentas de clientes, por favor espere . . .'

WHILE @@FETCH_STATUS = 0
BEGIN


	SET @balance1 = 0
	SET @balance2 = 0

	DELETE FROM #tmpprueba

	--SELECT 'Verificando Cta. Cte. Cliente:' + CONVERT(VARCHAR,@cust_id)


--	INSERT #tmpprueba
--		(
--		[1],[2],[3],[4],[5],[6],[7],[8],
--		[comp_id],[bra_id],[sd_desc],[ct_transaction],[doc_number],[ct_docNumber],[ct_date],[ct_taxDate],
--		[ct_payDate],[supp_id],[cust_id],[cb_id],[user_id],[ct_subtotal],[ct_total],[ct_discount],[ct_taxes],
--		[curr_id_transaction],[hacc_transaction],[disc_id],[ct_ATotal],[ct_Credits],[ct_ABalance],[Balance],
--		[ct_ACurrency],[ct_ACurrencyExchange],[branch_ACurrency],[doc_ACurrencyExchange],[doc_dfExchange],
--		[ct_A_Total_dfExchange],[df_id],[dl_id],[st_id],[sd_id],[puco_id],[sm_id],[sm_name],[st_desc],
--		[dl_name],
--		[ct_CompanyCurrency],[ct_Branch2CompanyCurrencyExchange],[ct_adjust],[custb_name],[ct_cd],[user_name],
--		[soh_id_fromGenerated],[ID]
--		)

	INSERT #tmpprueba
		(	[ID],
			[Balance],
			[ct_ABalance]
		)



	EXEC [spCommercialTransactions_getDataByFilters4FixAccount]
		@comp_id,
		2,
		@bra_id,
		@cust_id,
		'1800-01-01',
		'2999-01-01',
		'1800-01-01',
		'2999-01-01',
		-2,
		'false',
		1,
		@bra_id


	/*
	SELECT [ct_transaction],CONVERT(NVARCHAR(21),[doc_number]) [doc_number],CONVERT(NVARCHAR(7),[ct_docNumber]) [ct_docNumber],[supp_id],[cust_id],
		[ct_ATotal],[ct_ABalance],[Balance],[ID] FROM #tmpprueba
	*/

--SELECT * FROM #tmpprueba
--RETURN

	SELECT @id			= ID FROM #tmpprueba
	SELECT @balance1	= Balance FROM #tmpprueba WHERE id = @id
	SELECT @balance2	= SUM(a.ct_ABalance) FROM #tmpprueba a


	IF NOT (@balance1 - @balance2) BETWEEN -0.40 AND 0.40
		INSERT INTO tbSystem_FixDatabase_1
		(	    fix_isPurchase,	fix_custsupp_id,	fix_balance,	fix_sumbalance, fix_cd	 	)
		SELECT	'false',		@cust_id,			@balance1,		@balance2,		@datetime


	DELETE FROM #tmpprueba


	FETCH	cursor_clientes INTO @cust_id


END


CLOSE cursor_clientes
DEALLOCATE cursor_clientes




--return






-- proveedores


DECLARE cursor_clientes CURSOR FAST_FORWARD FOR
SELECT  DISTINCT
		tct.supp_id--,
		--tct.comp_id,
		--tct.bra_id
FROM	tbCommercialTransactions tct
WHERE not tct.supp_id IS NULL
ORDER BY tct.supp_id

OPEN	cursor_clientes

FETCH	cursor_clientes INTO @cust_id--, @comp_id, @bra_id

SELECT ' Verificando cuentas de Proveedores, por favor espere . . .'

WHILE @@FETCH_STATUS = 0
BEGIN

--SELECT @cust_id

	SET @balance1 = 0
	SET @balance2 = 0

	DELETE FROM #tmpprueba

	--SELECT 'Verificando Cta. Cte. Proveedor:' + CONVERT(VARCHAR,@cust_id)

--	INSERT #tmpprueba
--		(
--		[1],[2],[3],[4],[5],[6],[7],[8],
--		[comp_id],[bra_id],[sd_desc],[ct_transaction],[doc_number],[ct_docNumber],[ct_date],[ct_taxDate],
--		[ct_payDate],[supp_id],[cust_id],[cb_id],[user_id],[ct_subtotal],[ct_total],[ct_discount],[ct_taxes],
--		[curr_id_transaction],[hacc_transaction],[disc_id],[ct_ATotal],[ct_Credits],[ct_ABalance],[Balance],
--		[ct_ACurrency],[ct_ACurrencyExchange],[branch_ACurrency],[doc_ACurrencyExchange],[doc_dfExchange],
--		[ct_A_Total_dfExchange],[df_id],[dl_id],[st_id],[sd_id],[puco_id],[sm_id],[sm_name],[st_desc],
--		[ct_CompanyCurrency],[ct_Branch2CompanyCurrencyExchange],[ct_adjust],[custb_name],[ct_cd],[user_name],
--		[soh_id_fromGenerated],[ID]
--		)
--	EXEC spCommercialTransactions_getDataByFilters_prueba
--		@comp_id		= @comp_id,
--		@lang_id		= 2,
--		@bra_id			= @bra_id,
--		@selection_id	= @cust_id,
--		@datefrom		= '2000-01-01',
--		@dateto			= '2013-01-01',
--		@paydatefrom	= '2000-01-01',
--		@paydateto		= '2013-01-01',
--		@sd_id			= -2,
--		@ispurchase		= 'true',
--		@user_id		= 1


	INSERT #tmpprueba
		(	[ID],
			[Balance],
			[ct_ABalance]
		)



	EXEC [spCommercialTransactions_getDataByFilters4FixAccount]
		@comp_id,
		2,
		@bra_id,
		@cust_id,
		'1800-01-01',
		'2999-01-01',
		'1800-01-01',
		'2999-01-01',
		-2,
		'True',
		1,
		@bra_id



	--SELECT * FROM #tmpprueba
	SELECT @id			= ID FROM #tmpprueba
	--SELECT @id
	SELECT @balance1	= Balance FROM #tmpprueba WHERE id = @id
	SELECT @balance2	= SUM(a.ct_ABalance) FROM #tmpprueba a


	IF not (@balance1 - @balance2) BETWEEN -0.40 AND 0.40
		--INSERT INTO #tmpresultados
		--([cust_id],[resultado],[balance],[sumatoria_Abalance])
		INSERT INTO tbSystem_FixDatabase_1
		(		fix_isPurchase,	fix_custsupp_id,	fix_balance,	fix_sumbalance, fix_cd		)
		SELECT	'true',			@cust_id,			@balance1,		@balance2,		@datetime


	FETCH	cursor_clientes INTO @cust_id--, @comp_id, @bra_id


END


CLOSE cursor_clientes
DEALLOCATE cursor_clientes




SELECT * FROM tbSystem_FixDatabase_1
GO



CREATE PROCEDURE [dbo].[spCommercialTransactions_CollectionImport_ValidateTransaction]
(
	@comp_id		as	int,
	@ct_transaction	as	INT,
	@ctl_id			AS  INT,
	@cust_id		AS  INT,
	@UserId			AS	INT,
	@prof_id		AS  INT,
	@lang_id		AS  INT
)
AS


BEGIN

	-- Verifica que la CUOTA sea del CT_transaction informado y del cliente informado y tenga saldo
	IF @ctl_id > 0
		BEGIN
			SELECT TOP 1  1				[isOK]
				FROM tbCommercialTransactions			AS tct		WITH (NOLOCK)
				INNER JOIN tbCommercialTransactionsLoan AS tctl		WITH (NOLOCK)
					ON	tctl.comp_id		= tct.comp_id			AND
						tctl.ct_transaction = tct.ct_transaction	AND
						tctl.ctl_id			= @ctl_id
				WHERE	tct.comp_id			= @comp_id				AND
						tct.ct_transaction	= @ct_transaction		AND
						tct.cust_id			= @cust_id				AND
						tctl.ct_ABalance    > 0
		END
	ELSE	-- Verifica el CT_transaction informado y el cliente informado y tenga saldo.
		BEGIN
			SELECT TOP 1  1				[isOK]
				FROM tbCommercialTransactions			AS tct		WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id				AND
						tct.ct_transaction	= @ct_transaction		AND
						tct.cust_id			= @cust_id				AND
						tct.ct_ABalance		> 0
		END


END

GO



CREATE PROCEDURE [dbo].[spCommercialTransactions_CreditCardLiquidation_UpdateData]
(
	@comp_id		INT,
	@bra_id			INT,
	@ct_transaction	INT,
	@DataGridType	INT,		-- 2 = Conceptos / 3 = Impuestos
	@pcm_id			INT,
	@puco_id		INT,
	@tm_transaction INT,
	@tax_id			INT

)
AS

	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT,
				@DataGridType	INT	--1 = Cupones / 2 = Conceptos / 3 = Impuestos
			SELECT
				@comp_id		= 1,
				@ct_transaction	= 12783,
				@DataGridType	= 1
		*/
		-- ---------------------------------------------------------------

		--CONCEPTOS
		IF @DataGridType = 2
			BEGIN

				UPDATE tbPurchaseConceptMovements
				SET
					puco_id = @puco_id

				WHERE comp_id = @comp_id	AND
					  bra_id  = @bra_id		AND
					  pcm_id  = @pcm_id

			END


		--IMPUESTOS
		IF @DataGridType = 3
			BEGIN
				UPDATE tbTaxMovements
				SET
					tax_id = @tax_id

				WHERE comp_id			= @comp_id		AND
					  bra_id			= @bra_id		AND
					  tm_transaction	= @tm_transaction

			END
	END










GO





CREATE PROCEDURE [dbo].[spCommercialTransactions_Customer_UserSalesmanRelationVerification]
(

	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,

	@cust_id			INT


)
as

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE
		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,

		@cust_id			INT


SELECT		@comp_id					= 1,
			@user_id					= 1,
			@cust_id					= 24292

*/
-- ------------------------------------------------------




	IF NOT EXISTS ( SELECT  TOP 1
						tc.cust_id
						FROM tbCustomer											tc			WITH (NOLOCK)

	     --           	inner JOIN tbCustomerFilterByUser						tcfbu		WITH (NOLOCK)
						--ON	tcfbu.comp_id		= tc.comp_id
						--AND tcfbu.[user_id]		= @user_id
						--AND tcfbu.sm_id			= tc.sm_id

						inner JOIN tbUserSalesmanRelation						tusr		WITH (NOLOCK)
						ON	tusr.comp_id		= tc.comp_id
						AND tusr.[user_id]		= @user_id
						AND tusr.sm_id			= tc.sm_id

						WHERE	tc.comp_id		= @comp_id AND
								tc.cust_id		= @cust_id
					)

		BEGIN
			 --'Este usuario no tiene relacionado al vendedor del cliente'
			 SELECT 0 [Isok]
		END
	ELSE

	BEGIN
			--'OK, Este usuario tiene relacionado al vendedor del cliente'
			SELECT 1 [Isok]
		END







END
GO



-- Log
-- MOS 07-2024: saqué los with ROWLOCK en actualizaciones para que decida la BD

-- =============================================
-- Author:		MOS
-- Create date: 07-2012
-- Description:	Aplica Automaticamente una
-- cuenta de Clientes de todas las sucursales
-- donde la actual este incluida en tbBranchGroup
-- =============================================

CREATE PROCEDURE [dbo].[spCommercialTransactions_CustomerBalanceAutomaticAplication]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@cust_id	AS INT,
	@CTR_Id		AS INT
AS


BEGIN

	SET NOCOUNT ON;
	-- ----------------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------------
	/*
	DECLARE @comp_id	AS INT,
			@cust_id	AS INT,
			@bra_id		AS INT
	SET		@comp_id	= 1
	SET		@cust_id	= 24294
	SET		@bra_id		= 1
	*/
	-- ----------------------------------------------------------------------



	-- ----------------------------------------------------------------------
	-- Sucursales para hacer la aplicacion
	-- ----------------------------------------------------------------------
	DECLARE @tmpBranchs TABLE(bra_id INT PRIMARY KEY CLUSTERED)
	INSERT INTO @tmpBranchs(bra_id)
		SELECT DISTINCT bd2.bra_id
			FROM		tbBranchGroupDetail bd1	WITH (NOLOCK)
			CROSS JOIN	tbBranchGroupDetail bd2	WITH (NOLOCK)
		WHERE	bd1.comp_id = @comp_id
			AND	bd1.bra_id  = @bra_id
			AND bd2.brag_id = bd1.brag_id
	IF NOT EXISTS(
					SELECT TOP 1  1
						FROM @tmpBranchs
						WHERE bra_id = @bra_id
					)
		BEGIN
			INSERT INTO @tmpBranchs(bra_id) VALUES (@bra_id)
		END
	-- ----------------------------------------------------------------------




	DECLARE @intCtTransaction_Credit AS INT
	DECLARE @intCtTransaction_Debit  AS INT
	DECLARE @decABalance_Credit		 AS DECIMAL(19,6)
	DECLARE @decABalance_Debit 		 AS DECIMAL(19,6)
	DECLARE @decATotal_Credit		 AS DECIMAL(19,6)
	DECLARE @decATotal_Debit 		 AS DECIMAL(19,6)
	DECLARE @intCurrId				 AS INT
	DECLARE @decApplicationPercentajeSource		AS DECIMAL(19,6)
	DECLARE @decApplicationPercentajeDestiny	AS DECIMAL(19,6)

	SELECT @intCurrId = tc.curr_id
		FROM tbCustomer tc						WITH (NOLOCK)
		WHERE	tc.comp_id = @comp_id
			AND tc.cust_id = @cust_id


	-- Arma una temporal con todos los ct_transaction que se pueden autoaplicar
	SELECT	tct.comp_id,
			tct.bra_id,
			tct.ct_transaction,
			tct.cust_id,
			td.sd_isCredit
		INTO #tmpJobTable
		FROM tbCommercialTransactions tct		WITH (NOLOCK)
		INNER JOIN @tmpBranchs tmp
			ON tmp.bra_id = tct.bra_id
		INNER JOIN tbsysDocuments td			WITH (NOLOCK)
			ON td.sd_id = tct.sd_id
	WHERE	tct.comp_id = @comp_id
		AND tct.cust_id = @cust_id
		AND td.sd_isInBalance = 'True'
		AND tct.ct_ABalance <> 0
		AND tct.ct_ATotal	<> 0
		AND tct.ct_ACurrency = @intCurrId
	ORDER BY tct.ct_transaction



	IF @CTR_Id > 0
		BEGIN
			DELETE	FROM #tmpJobTable
					FROM #tmpJobTable tmp
				LEFT JOIN tbCommercialTransactions_Relations tctr			WITH (NOLOCK)
				ON	tctr.comp_id	= tmp.comp_id	AND
					tctr.class		= 5				AND
					tctr.ctr_id		= @CTR_Id		AND
					(
						tctr.ct_transaction_1 = tmp.ct_transaction
							OR
						tctr.ct_transaction_2 = tmp.ct_transaction
					)
				WHERE tctr.comp_id IS NULL
		END


	-- Borra todas las que tenga cuotas ya que no esta preparado para aplicar cuotas
	DELETE	FROM #tmpJobTable
			FROM #tmpJobTable tmp
		LEFT JOIN tbCommercialTransactionsLoan tctl			WITH (NOLOCK)  -- nolock mos 05-2020
			ON	tctl.comp_id		= @comp_id AND
				tctl.ct_transaction = tmp.ct_transaction
		WHERE tctl.comp_id IS NOT NULL



--==
--SELECT * FROM #tmpJobTable
--==




	-- Verifica si quedan pendientes alguna de tipo debito y credito
	WHILE EXISTS(	SELECT TOP 1  1
	             		FROM #tmpJobTable tmp1
	             		INNER JOIN tbCommercialTransactions tct1	WITH (NOLOCK)
	             			ON tct1.ct_transaction = tmp1.ct_transaction
	             	WHERE	tct1.ct_ABalance <> 0
	             		AND tmp1.sd_isCredit = 'False'
				)
		AND
		  EXISTS(	SELECT TOP 1  1
	             		FROM #tmpJobTable tmp2
	             		INNER JOIN tbCommercialTransactions tct2	WITH (NOLOCK)
	             			ON tct2.ct_transaction = tmp2.ct_transaction
	             	WHERE	tct2.ct_ABalance <> 0
	             		AND tmp2.sd_isCredit = 'True'
				)
		BEGIN

			SELECT TOP 1	@intCtTransaction_Debit = tct1.ct_transaction,
							@decABalance_Debit		= tct1.ct_ABalance,
							@decATotal_Debit		= tct1.ct_ATotal
	             			FROM #tmpJobTable tmp1
	             			INNER JOIN tbCommercialTransactions tct1	WITH (NOLOCK)
	             				ON tct1.ct_transaction	= tmp1.ct_transaction
	             		WHERE	tct1.ct_ABalance		<> 0
	             			AND	tct1.ct_ATotal			<> 0
	             			AND tmp1.sd_isCredit = 'False'
						ORDER BY tct1.ct_transaction

			SELECT TOP 1	@intCtTransaction_Credit = tct2.ct_transaction,
							@decABalance_Credit		 = tct2.ct_ABalance,
							@decATotal_Credit		 = tct2.ct_ATotal
	             			FROM #tmpJobTable tmp2
	             			INNER JOIN tbCommercialTransactions tct2	WITH (NOLOCK)
	             				ON tct2.ct_transaction	= tmp2.ct_transaction
	             		WHERE	tct2.ct_ABalance		<> 0
	             			AND	tct2.ct_ATotal			<> 0
	             			AND tmp2.sd_isCredit = 'True'
						ORDER BY tct2.ct_transaction

			-- Chequeo x las dudas!!!! ( para que no haga loop infinito )
			IF @decABalance_Credit IS NULL OR  @decABalance_Debit IS NULL BREAK

	--==
	--SELECT @decATotal_Debit,@decATotal_Credit,@intCtTransaction_Debit,@intCtTransaction_Credit

			IF @decABalance_Debit >= @decABalance_Credit
				BEGIN

					UPDATE tbCommercialTransactions			WITH (ROWLOCK)
						SET ct_ABalance			= 0
						WHERE ct_transaction	= @intCtTransaction_Credit

					UPDATE tbCommercialTransactions			WITH (ROWLOCK)
						SET ct_ABalance			= ct_ABalance - @decABalance_Credit
						WHERE ct_transaction	= @intCtTransaction_Debit

					SET @decApplicationPercentajeSource	 = (@decABalance_Credit / @decATotal_Debit)  * 100
					SET @decApplicationPercentajeDestiny = (@decABalance_Credit / @decATotal_Credit) * 100

					INSERT INTO tbApplication	-- MOS 07-2024 WITH (ROWLOCK)
					(
						comp_id,
						bra_id,
						ct_transaction_Source,
						ct_transaction_destiny,
						appl_currency,
						appl_total,
						appl_coef,
						appl_coef_,
						appl_excdifchecked,
						ct_transaction
					)
					VALUES
					(
						@comp_id,
						@bra_id,
						@intCtTransaction_Debit,
						@intCtTransaction_Credit,
						@intCurrId,
						@decABalance_Credit,
						@decApplicationPercentajeSource,
						@decApplicationPercentajeDestiny,
						'False',
						NULL
					)

					CONTINUE
				END
			ELSE	--  @decABalance_Debit < @decABalance_Credit
				BEGIN
					UPDATE tbCommercialTransactions		-- MOS 07-2024 WITH (ROWLOCK)
						SET ct_ABalance			= ct_ABalance - @decABalance_Debit
						WHERE ct_transaction	= @intCtTransaction_Credit

					UPDATE tbCommercialTransactions		-- MOS 07-2024 WITH (ROWLOCK)
						SET ct_ABalance			= 0
						WHERE ct_transaction	= @intCtTransaction_Debit

					SET @decApplicationPercentajeSource	 = (@decABalance_Debit / @decATotal_Debit)  * 100
					SET @decApplicationPercentajeDestiny = (@decABalance_Debit / @decATotal_Credit) * 100

					INSERT INTO tbApplication			WITH (ROWLOCK)
					(
						comp_id,
						bra_id,
						ct_transaction_Source,
						ct_transaction_destiny,
						appl_currency,
						appl_total,
						appl_coef,
						appl_coef_,
						appl_excdifchecked,
						ct_transaction
					)
					VALUES
					(
						@comp_id,
						@bra_id,
						@intCtTransaction_Debit,
						@intCtTransaction_Credit,
						@intCurrId,
						@decABalance_Credit,
						@decApplicationPercentajeSource,
						@decApplicationPercentajeDestiny,
						'False',
						NULL
					)

					CONTINUE
				END

			BREAK
		END


	-- Borra Tablas Temporales
	DROP TABLE #tmpJobTable

END

GO





-- =============================================
-- Author:		MOS
-- Create date: 07-2012
-- Description:	Auto-Aplicacion de toda la cuenta corriente de Clientes.!
-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactions_CustomerBalanceAutomaticAplication4AllCustomers]

AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @intCompId AS INT
	DECLARE @intBraId  AS INT
	DECLARE @intCustID AS INT


	DECLARE curCommercialTransaction CURSOR LOCAL FAST_FORWARD FOR

	SELECT tct.comp_id,tct.bra_id,tct.cust_id
		FROM tbCommercialTransactions tct
		INNER JOIN vwCommercialTransactions_forSales vctfs	WITH (NOLOCK)
			ON	vctfs.comp_id		 = tct.comp_id			AND
				vctfs.ct_transaction = tct.ct_transaction
		INNER JOIN tbsysDocuments td						WITH (NOLOCK)
			ON td.sd_id = tct.sd_id
		where	tct.cust_id IS NOT NULL	AND
				tct.ct_ABalance <> 0	AND
				td.sd_isInBalance	= 'True'
		GROUP BY	tct.comp_id,
					tct.bra_id,
					tct.cust_id
		ORDER BY tct.cust_id

	OPEN		curCommercialTransaction
	FETCH NEXT FROM curCommercialTransaction INTO @intCompId,@intBraId,@intCustID

	WHILE @@FETCH_STATUS = 0
		BEGIN
			EXEC spCommercialTransactions_CustomerBalanceAutomaticAplication
				@intCompId,
				@intBraId,
				@intCustID,
				-1
			SELECT @intCompId,@intBraId,@intCustID
			FETCH NEXT FROM curCommercialTransaction INTO @intCompId,@intBraId,@intCustID
		END


	CLOSE		curCommercialTransaction
	DEALLOCATE	curCommercialTransaction

END
GO





--Convierte la factura en remito en CtaCte - modificacion de datos ( Clientes )

CREATE PROCEDURE [dbo].[spCommercialTransactions_CustUpdateSysDocument]
(
	@comp_id				INT,
	@ct_transaction			INT
)
AS

BEGIN

	SET NOCOUNT ON


	DECLARE @return_value		INT
	DECLARE @bra_id				INT
	DECLARE @df_id				INT


	SET	@return_value = 1



	SELECT @bra_id = ( SELECT tct.bra_id
						FROM tbCommercialTransactions tct
							WHERE	comp_id							=	@comp_id				AND
									ct_transaction					=	@ct_transaction
					  )



	SET @df_id = NULL

	SELECT TOP 1 @df_id = tdf.df_id
					   FROM tbDocumentsFile				tdf
					   WHERE  tdf.bra_id = @bra_id										AND
							  tdf.df_PackingList_IsAvailable4InvoiceAnullment ='True'	AND
							  tdf.sd_id	= 2
					   ORDER BY tdf.df_order


	IF @df_id IS NOT NULL

		BEGIN

				UPDATE tbCommercialTransactions

					SET		sd_id = 2,
							df_id = @df_id

					WHERE	comp_id							=	@comp_id
					AND		ct_transaction					=	@ct_transaction



			-- Anula el posible asiento contable generado.
			EXEC spAccountTransaction_insertAnullment @comp_id, @ct_transaction

		END

	ELSE


		BEGIN
			SET	@return_value = 0
		END



	SELECT	@return_value [Value]


END
GO








