CREATE PROCEDURE [dbo].[spCommercialTransactions_Digitalizations_GetDataById]
(
	@comp_id	INT,
	@mloim_id	INT
)



AS




/*
DECLARE @comp_id	INT,
	@mloim_id	INT

	SELECT @comp_id	= 1 ,
	@mloim_id	= 18

	*/
	BEGIN
		SET NOCOUNT ON

		SELECT
			tctd.comp_id,
			tctd.mloim_id,
			tctd.mlo_id,
			tctd.ct_transaction,
			ISNULL(tctd.mloim_Desc,'')						[mloim_Desc],
			tctd.cust_id,
			tctd.supp_id,
			tctd.mloim_pdf,
			tctd2.ctd_image									[ctd_image],
			ISNULL(tctd.mloim_note,'')						[mloim_note],
			tctd.ba_id,
			tctd.cmdc_id

			FROM tbCommercialTransactions_Digitalizations			tctd	WITH (NOLOCK)


			LEFT JOIN tbCommercialTransactionsDelivery				tctd2	WITH (NOLOCK)
			ON	tctd2.comp_id			= tctd.comp_id					AND
				tctd2.ct_transaction	= tctd.ct_transaction

			WHERE	tctd.comp_id		= @comp_id				AND
					tctd.mloim_id		= @mloim_id

	END
GO

CREATE PROCEDURE [dbo].[spCommercialTransactions_Digitalizations_InsertData]
(
	@comp_id			INT,
	@mlo_id				INT,
	@ct_transaction		INT,
	@mloim_Desc			NVARCHAR(200),
	@cust_id			INT,
	@supp_id			INT,
	@mloim_pdf			IMAGE,
	@mloim_note			NTEXT,
	@ba_id				INT,
	@cmdc_id			INT,
	@return_value		INT OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON

		IF @mlo_id = 0
			BEGIN
				SET @mlo_id = NULL
			END

		IF @ct_transaction = 0
			BEGIN
				SET @ct_transaction = NULL
			END

		IF @cust_id = -1
			BEGIN
				SET @cust_id = NULL
			END

		IF @supp_id = -1
			BEGIN
				SET @supp_id = NULL
			END

		IF @ba_id = -1
			BEGIN
				SET @ba_id = NULL
			END

		IF @cmdc_id = -1
			BEGIN
				SET @cmdc_id = NULL
			END

		INSERT INTO tbCommercialTransactions_Digitalizations
		(
			comp_id,
			-- mloim_id -- this column value is auto-generated,
			mlo_id,
			ct_transaction,
			mloim_Desc,
			cust_id,
			supp_id,
			--mloim_pdf,
			mloim_note,
			ba_id,
			cmdc_id
		)
		VALUES
		(
			@comp_id,
			@mlo_id,
			@ct_transaction,
			@mloim_Desc,
			@cust_id,
			@supp_id,
			--@mloim_pdf,
			@mloim_note,
			@ba_id,
			@cmdc_id
		)

		SET @return_value = @@IDENTITY

	END
GO

CREATE PROCEDURE [dbo].[spCommercialTransactions_Digitalizations_UpdateData]
(
	@comp_id			INT,
	@mloim_id			INT,
	@mlo_id				INT,
	@ct_transaction		INT,
	@mloim_Desc			NVARCHAR(200),
	@cust_id			INT,
	@supp_id			INT,
	@mloim_pdf			IMAGE,
	@mloim_note			NTEXT,
	@ba_id				INT,
	@cmdc_id			INT
)
AS
	SET NOCOUNT ON
		BEGIN

			IF @mlo_id = 0
			BEGIN
				SET @mlo_id = NULL
			END

			IF @ct_transaction = 0
				BEGIN
					SET @ct_transaction = NULL
				END

			IF @cust_id = -1
				BEGIN
					SET @cust_id = NULL
				END

			IF @supp_id = -1
				BEGIN
					SET @supp_id = NULL
				END

			IF @ba_id = -1
				BEGIN
					SET @ba_id = NULL
				END


			UPDATE tbCommercialTransactions_Digitalizations
			SET
				mlo_id			= @mlo_id,
				ct_transaction	= @ct_transaction,
				mloim_Desc		= @mloim_Desc,
				cust_id			= @cust_id,
				supp_id			= @supp_id,
				mloim_note		= @mloim_note,
				ba_id			= @ba_id,
				cmdc_id			= @cmdc_id
			WHERE	comp_id		= @comp_id			AND
					mloim_id	= @mloim_id

	END
GO

