CREATE PROCEDURE [dbo].[spCommercialTransactions_DigitalizationsGetDataByFilters]
(
	@comp_id		INT,
	@lang_id		INT,
	@cust_id		INT,
	@supp_id		INT,
	@mlo_id			INT,
	@ct_transaction	INT,
	@description	NVARCHAR(200),
	@ba_id			INT,
	@cmdc_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------
		-- Testing
		-- -----------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@cust_id		INT,
				@supp_id		INT,
				@mlo_id			INT,
				@ct_transaction	INT,
				@description	NVARCHAR(200),
				@ba_id			INT,
				@cmdc_id		INT

			SELECT
				@comp_id		= 1,
				@cust_id		= -1,
				@supp_id		= -1,
				@mlo_id			= 0,
				@ct_transaction	= 0,
				@description	= '',
				@ba_id			= -1,
				@cmdc_id		= -1
		*/
		-- -----------------------------------------------------------------

		SELECT
			' '																[ ],	--UPDATE
			' '																[ ],	--DELETE
			ISNULL(tctd.mlo_id,'')											[mlo_id],
			ISNULL(tctd.ct_transaction,'')									[ct_transaction],
			tctd.mloim_Desc,
			ISNULL(tc.cust_name,'')											[cust_name],
			ISNULL(ts.supp_name,'')											[supp_name],
			tctd.mloim_note,
			tba.ba_desc,
			tctdc.cmdc_desc,
			tctd.mloim_id													[ID]
			FROM tbCommercialTransactions_Digitalizations					tctd		WITH(NOLOCK)

				left JOIN tbCommercialTransactions_DigitalizationsClass	tctdc		WITH(NOLOCK)
					ON	tctdc.comp_id		= tctd.comp_id					AND
						tctdc.cmdc_id		= tctd.cmdc_id
				LEFT JOIN tbCustomer										tc			WITH(NOLOCK)
					ON	tc.cust_id			= tctd.cust_id					AND
						tc.comp_id			= tctd.comp_id
				LEFT JOIN tbSupplier										ts			WITH(NOLOCK)
					ON	ts.supp_id			= tctd.supp_id					AND
						ts.comp_id			= tctd.comp_id
				LEFT JOIN tbMercadoLibre_ordersHeader						tmloh		WITH(NOLOCK)
					ON	tmloh.mlo_id		= tctd.mlo_id					AND
						tmloh.comp_id		= tctd.comp_id
				LEFT JOIN tbCommercialTransactions							tct			WITH(NOLOCK)
					ON	tct.comp_id			= tctd.comp_id					AND
						tct.ct_transaction	= tctd.ct_transaction
				LEFT JOIN tbBankingAccounts									tba			WITH(NOLOCK)
					ON	tba.comp_id			= tctd.comp_id					AND
						tba.ba_id			= tctd.ba_id
			WHERE		tctd.comp_id		= @comp_id						AND
						(
							@cust_id = -1				OR
							@cust_id = tctd.cust_id
						)													AND
						(
							@supp_id = -1				OR
							@supp_id = tctd.supp_id
						)													AND
						(
							@mlo_id = 0					OR
							@mlo_id = tctd.mlo_id
						)													AND
						(
							@ct_transaction = 0			OR
							@ct_transaction = tctd.ct_transaction
						)													AND
						(
							(@description = '')			OR
							(tctd.mloim_Desc	LIKE '%'+ @description +'%')
						)													AND
						(
							@ba_id = -1					OR
							@ba_id = tctd.ba_id
						)													AND
						(
							@cmdc_id = -1				OR
							@cmdc_id = tctd.cmdc_id
						)


	END
GO






