-------------------------------------------------------------------------------



CREATE PROCEDURE [dbo].[spCommercialTransactions_DirectCollection_GetdataById]
(
	@comp_id			INT,
	@bra_id				INT,
	@guid				UNIQUEIDENTIFIER,
	@decExchange		DECIMAL(19,4),
	@lang_id			INT,
	@ct_transaction		INT

)
AS


BEGIN



	set nocount on



	-------------------------------------------------------------------------------
	-- Parametros de Test
	-------------------------------------------------------------------------------
	/*

	Declare			@comp_id			INT,
					@ct_transaction		INT

	Select			@comp_id			= 1,
					@ct_transaction		= 8336

	*/
	-------------------------------------------------------------------------------
	-------------------------------------------------------------------------------
	BEGIN

			DECLARE @cust_id			AS INT
			DECLARE @intCTTransaction	AS INT
			DECLARE @decTotal			AS DECIMAL(19,4)
			DECLARE @intBraId			AS INT
			SET		@cust_id			= -1

			IF EXISTS(	SELECT 1
							FROM tbCommercialTransactionsLoan tctl
		          			WHERE	tctl.comp_id		= @comp_id			AND
		          					tctl.ct_transaction = @ct_transaction	AND
									tctl.ct_ABalance <> 0)
				BEGIN

					SELECT TOP 1	@intCTTransaction	= tctl.ctl_id * -1,
									@intBraId			= tct.bra_id,
									@decTotal			= tctl.ct_ABalance,
									@cust_id			= tct.cust_id
						FROM tbCommercialTransactionsLoan tctl				WITH (NOLOCK)
						INNER JOIN tbCommercialTransactions tct				WITH (NOLOCK)
						ON	tct.comp_id			= tctl.comp_id AND
							tct.ct_transaction	= tctl.ct_transaction
	          			WHERE	tctl.comp_id		= @comp_id			AND
	          					tctl.ct_transaction = @ct_transaction	AND
								tctl.ct_ABalance <> 0


				END

			ELSE

				BEGIN

					SET @intCTTransaction	= @ct_transaction
					SELECT	@intBraId		= ct.bra_id ,
							@decTotal		= ct.ct_ABalance,
							@cust_id		= ct.cust_id
						From	dbo.tbCommercialTransactions	CT	WITH (NOLOCK)
						where	CT.comp_id			= @comp_id
						and		CT.ct_transaction	= @ct_transaction

				END

			IF @cust_id > 0
				BEGIN
					EXEC spCommercialTransactionsTmp_insertData @comp_id,
																@intBraId,
																@guid,
																@intCTTransaction,
																@decTotal,
																'a',
																@decExchange,
																''
				END

			SELECT	@cust_id			[cust_id],
					@ct_transaction		[ct_transaction],
					@decTotal			[Total]

	END


END
GO




-- =============================================
-- Author:		Retorna si hay algun item que requiera la impresion de un documento adicional
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[spCommercialTransactions_DocumentsAdditionalsByItem]
	@comp_id		AS INT,
	@ct_transaction AS INT
AS


BEGIN

	SET NOCOUNT ON;


	-- ----------------------------------------------------
	-- Testing
	-- ----------------------------------------------------
	/*
	DECLARE @comp_id		AS INT,
			@ct_transaction AS INT
	SET		@comp_id		= 1
	SET		@ct_transaction = 9612
	*/
	-- ----------------------------------------------------

	DECLARE @bolIsItemType1 AS BIT
	DECLARE @bolIsItemType2 AS BIT
	DECLARE @bolIsItemType3 AS BIT
	DECLARE @bolIsItemType4 AS BIT
	SET		@bolIsItemType1 = 'False'
	SET		@bolIsItemType2 = 'False'
	SET		@bolIsItemType3 = 'False'
	SET		@bolIsItemType4 = 'False'


	SELECT
			@bolIsItemType1 =	CASE
									   WHEN ti.item_df_id_additional1 = 'True' THEN 'True'
									   ELSE				@bolIsItemType1
								END,
			@bolIsItemType2 =	CASE
									   WHEN ti.item_df_id_additional2 = 'True' THEN 'True'
									   ELSE				@bolIsItemType2
								END,
			@bolIsItemType3 =	CASE
									   WHEN ti.item_df_id_additional3 = 'True' THEN 'True'
									   ELSE				@bolIsItemType3
								END,
			@bolIsItemType4 =	CASE
									   WHEN ti.item_df_id_additional4 = 'True' THEN 'True'
									   ELSE				@bolIsItemType4
								END

		FROM tbItemTransactions tit							WITH (NOLOCK)
		INNER JOIN tbItem		ti							WITH (NOLOCK)
			ON	ti.comp_id = tit.comp_id AND
				ti.item_id = ISNULL(tit.item_id,tit.item_idfromPreInvoice)		-- MOS 06-2023: Si es x Fc Anticipada, que ponga el item q la origina.
		WHERE	tit.comp_id = @comp_id					AND
				tit.ct_transaction = @ct_transaction


	SELECT	@bolIsItemType1  [bolIsItemType1],
			@bolIsItemType2  [bolIsItemType2],
			@bolIsItemType3  [bolIsItemType3],
			@bolIsItemType4  [bolIsItemType4]


END
GO






CREATE PROCEDURE [dbo].[spCommercialTransactions_existsData]
(
	@comp_id		INT,
	@ct_transaction	INT,
	@ct_pointOfSale	INT,
	@ct_kindOf		VARCHAR(10),
	@ct_docNumber	VARCHAR(40),
	@sd_id			INT,
	@df_id			INT,
	@return_value	INT OUTPUT
)
AS


BEGIN



	set nocount on

	/*
	DECLARE
		@comp_id		INT,
		@ct_transaction	INT,
		@ct_pointOfSale	INT,
		@ct_kindOf		VARCHAR(10),
		@ct_docNumber	VARCHAR(40),
		@return_value	INT


	SELECT
		@comp_id		= 1,
		@ct_transaction = 1857,
		@ct_pointOfSale	= 1,
		@ct_kindOf		= 'X',
		@ct_docNumber	= '60'
	*/

	IF exists (SELECT 1
				   FROM  tbCommercialTransactions tct		WITH (NOLOCK)
				   WHERE	tct.comp_id			= @comp_id
				   AND		tct.ct_pointOfSale	= @ct_pointOfSale
				   AND		tct.ct_kindOf		= @ct_kindOf
				   AND		tct.ct_docNumber	= @ct_docNumber
				   AND		tct.ct_transaction	<> @ct_transaction
				   AND		CASE
								WHEN @df_id = -1			THEN	1
								WHEN tct.df_id = @df_id		THEN	1
								ELSE								0
							END	= 1
				   AND      CASE
								WHEN @sd_id		= -1		THEN	1
								WHEN tct.sd_id	= @sd_id	THEN	1
								ELSE								0
							END	= 1
			  )

			   SET @return_value = 1
	ELSE
			   SET @return_value = 0

	SELECT @return_value





END
GO







CREATE PROCEDURE [dbo].[spCommercialTransactions_FixData]
AS
SET NOCOUNT ON



BEGIN


	IF EXISTS (SELECT 1 FROM tbSystem_DatabaseVersion tsdv WHERE isnull(tsdv.isFixed_1,'false') = 'false')
		BEGIN



			EXEC spCommercialTransactions_CheckBalance



			IF EXISTS(SELECT 1 FROM tbSystem_FixDatabase_1 tsfd)
			BEGIN

				-- ========================================================================================================================================
				-- con lo cargado en la tabla tbSystem_FixDatabase_1 donde están cargados todos los datos de los clientes/proveedores con problemas
				-- en las cuentas corrientes
				-- ========================================================================================================================================

				DECLARE	@fix_isPurchase		BIT,
						@fix_custsupp_id	INT


				DECLARE cursor_fix CURSOR FOR
				SELECT	tsfd.fix_isPurchase, tsfd.fix_custsupp_id
				FROM	tbSystem_FixDatabase_1 tsfd
				ORDER BY tsfd.fix_id


				OPEN cursor_fix

				FETCH cursor_fix INTO @fix_isPurchase, @fix_custsupp_id

				WHILE @@FETCH_STATUS = 0
				BEGIN

					SELECT	'Eliminando Aplicaciones de ' +
							CASE WHEN @fix_isPurchase = 'true' THEN 'Proveedor' ELSE 'Cliente' END +
							': ' +
							CONVERT(VARCHAR,@fix_custsupp_id)


					EXEC dbo.spApplication_deleteAllData @fix_isPurchase, @fix_custsupp_id


					FETCH cursor_fix INTO @fix_isPurchase, @fix_custsupp_id

				END

				CLOSE cursor_fix
				DEALLOCATE cursor_fix



				EXEC spCommercialTransactions_CheckBalance



			END

			ELSE

			BEGIN

				SELECT 'No se encontraron problemas de balanceo en las cuentas corrientes.'

			END




			UPDATE	tbSystem_DatabaseVersion
			SET		isFixed_1 = 'true'



		END

	-- ---------------------------------------------------
	-- MOS 06-2024: Fix NC y ND x Dif Cambio del RHDRRMRP
	-- ---------------------------------------------------
	IF EXISTS (SELECT 1 FROM tbSystem_DatabaseVersion tsdv WHERE isnull(tsdv.isFixed_3,'false') = 'false')
		BEGIN

			DECLARE @intComp_id		AS INT
			DECLARE @intBra_id		AS INT
			DECLARE @intSoh_id		AS INT
			DECLARE @intUSER_ID			AS INT
			DECLARE curFIXSO CURSOR LOCAL  FAST_FORWARD FOR
				SELECT tsoh.comp_id, tsoh.bra_id, tsoh.soh_id,tsoh.[user_id]
					FROM tbSaleOrderHeader AS tsoh
					INNER JOIN tbDocumentsFile AS tdf
						ON	tdf.comp_id = tsoh.comp_id AND
							tdf.df_id	= tsoh.df_id
					WHERE tdf.sd_id IN (43,44)


			OPEN		curFIXSO
			FETCH NEXT FROM curFIXSO  INTO @intComp_id,@intBra_id,@intSoh_id,@intUSER_ID
			WHILE @@FETCH_STATUS = 0
				BEGIN
					EXEC spSaleOrder_RecalculateTaxes_FixByTotal
							@intComp_id,
							@intBra_id,
							@intSoh_id,
							@intUSER_ID,
							2
					FETCH NEXT FROM curFIXSO  INTO @intComp_id,@intBra_id,@intSoh_id,@intUSER_ID
				END

			CLOSE		curFIXSO
			DEALLOCATE  curFIXSO


			UPDATE	tbSystem_DatabaseVersion
			SET		isFixed_3 = 'true'

		END

	-- ---------------------------------------------------
















END


GO


CREATE procedure [dbo].[spCommercialTransactions_GetApplData]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@ispurchase			BIT,
	@custsupp			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@appl				BIT,
	@user_id			AS INT,
	@prof_id			AS INT,
	@ct_transOrigin		INT,
	@ct_transDestiny	INT
)
as


BEGIN



	set nocount ON
	set dateformat 'ymd'

	-- -------------------------------------------------
	-- Testing
	-- -------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@lang_id	INT,
		@bra_id		INT,
		@ispurchase	BIT,
		@custsupp	INT,
		@datefrom	DATETIME,
		@dateto		DATETIME,
		@appl		BIT	,
		@user_id AS INT,
		@prof_id AS INT

	SELECT
		@comp_id	=1,
		@lang_id	=2,
		@bra_id		=1,
		@ispurchase	= 'false',
		@custsupp	=3243,
		@datefrom	='2000-01-01',
		@dateto		='9999-12-31',
		@appl		= 'False',
		@user_id	= 1,
		@prof_id	= 1
	*/
	-- -------------------------------------------------

	SET	@dateFrom	=  dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'False')
	SET	@dateto		=  dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	-- -----------------------------------------------------------------------------------
	-- SI PONE 0 EN LOS FILTROS POR TRANSACCION, LO SETEO COMO -1 PARA QUE TRAIGA TODOS
	-- -----------------------------------------------------------------------------------
	IF @ct_transOrigin = 0
		BEGIN
			SET @ct_transOrigin = -1
		END

	IF @ct_transDestiny = 0
		BEGIN
			SET @ct_transDestiny = -1
		END
	-- -----------------------------------------------------------------------------------

	/*Recupera los datos de los documentos aplicados en la tbApplication*/
	SELECT
		' '																					[ ],
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)	[doc_number],
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct1.ct_transaction)	[doc_number_destiny],
		CASE @ispurchase WHEN 'True' THEN	ISNULL(ts.supp_name,'')
		ELSE								ISNULL(tc.cust_name,'')
		END																					[Name],
		tct.ct_date,
		tct.ct_ATotal,
		tct.ct_ABalance,
		tc2.curr_desc,
		CONVERT(VARCHAR,tct.comp_id) + '-' + CONVERT(VARCHAR,tct.bra_id)+ '-' +
		CONVERT(VARCHAR,ta.ct_transaction_Source) + '-' +
		CONVERT(VARCHAR,ta.ct_transaction_Destiny) + '-' +
		CONVERT(VARCHAR,ta.appl_id)															[ID]

		FROM dbo.tbApplication									ta		WITH (NOLOCK)
			INNER JOIN dbo.tbCommercialTransactions				tct		WITH (NOLOCK)
				ON	ta.comp_id					= tct.comp_id	AND
					ta.ct_transaction_Source	= tct.ct_transaction
			INNER JOIN tbUsers4BranchFilter						tubf	WITH (NOLOCK)
				ON	tubf.comp_id				= tct.comp_id	AND
					tubf.bra_id					= tct.bra_id	AND
					tubf.[user_id]				= @user_id
			INNER JOIN dbo.tbCommercialTransactions				tct1	WITH (NOLOCK)
				ON	ta.comp_id					= tct1.comp_id	AND
					ta.ct_transaction_destiny	= tct1.ct_transaction
			INNER JOIN tbUsers4BranchFilter						tubf1	WITH (NOLOCK)
				ON	tubf1.comp_id				= tct1.comp_id	AND
					tubf1.bra_id				= tct1.bra_id	AND
					tubf1.[user_id]				= @user_id
			LEFT JOIN	dbo.tbSupplier							ts		WITH (NOLOCK)
				ON	ts.comp_id					= tct.comp_id	AND
					ts.supp_id					= tct.supp_id	AND
					@ispurchase					= 'True'
			LEFT JOIN	dbo.tbCustomer							tc		WITH (NOLOCK)
				ON	tc.comp_id					= tct.comp_id AND
					tc.cust_id					= tct.cust_id AND
					@ispurchase					= 'False'
			INNER JOIN dbo.tbsysCurrency						tc2		WITH (NOLOCK)
				ON	tc2.curr_id					= ta.appl_currency
			LEFT JOIN tbCommercialTransactionsLoan				tctl
				ON  tctl.ct_transaction			= tct.ct_transaction
		WHERE	ta.comp_id		=	@comp_id					AND
		--AND		ta.bra_id	=	@bra_id  NO MAS, MOS, 04-2015
				tct.ct_date		BETWEEN @datefrom AND @dateto	AND
				(
					(@ispurchase = 'True'  AND (@custsupp = -1 OR tct.supp_id = @custsupp) AND (tct.supp_id IS NOT NULL)) OR
					(@ispurchase = 'False' AND (@custsupp = -1 OR tct.cust_id = @custsupp) AND (tct.cust_id IS NOT NULL))
				)												AND
				ta.appl_excdifchecked =  @appl					AND
				NOT (tct.sd_id	BETWEEN 150  AND 200)			AND	-- No traiga comprobantes anulados
				NOT (tct.sd_id	BETWEEN 50	AND  70)			AND -- No traiga comprobantes anulados
				tctl.comp_id	IS NULL							AND -- QUE NO traiga comprobantes que tengas  CUOTAS!!!!!
				(
					@ct_transOrigin				= -1 OR
					ta.ct_transaction_Source	= @ct_transOrigin
				)												AND
				(
					@ct_transDestiny			= -1 OR
					ta.ct_transaction_destiny	= @ct_transdestiny
				)
		ORDER BY ID
END
GO

CREATE PROCEDURE spCommercialTransactions_GetAvailableDocumentes2Assign2Import
(
	@comp_id	INT,
	@lang_id	INT,
	@supp_id	INT,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@docNumber	NVARCHAR(50)
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------

		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@supp_id	INT,
				@datefrom	DATETIME,
				@dateto		DATETIME,
				@docNumber	NVARCHAR(50)
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@supp_id	= -1,
				@datefrom	= '2015-01-01',
				@dateto		= '2016-01-31',
				@docNumber	= ''
		*/
		-- -------------------------------------------------

		SET	@datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

		SELECT
			ISNULL(SUBSTRING(ts.supp_name,0,20),'') + ' - ' +
			dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[Desc],
			tct.ct_transaction																		[ID]
			FROM tbCommercialTransactions								tct
			INNER JOIN vwCommercialTransactions_forPurchase				vctfp
				ON	vctfp.comp_id			= tct.comp_id				AND
					vctfp.ct_transaction	= tct.ct_transaction
			INNER JOIN tbSupplier										ts
				ON  ts.comp_id				= tct.comp_id				AND
					ts.supp_id				= tct.supp_id
			LEFT JOIN tbImportDetail									tid
				ON	tid.comp_id = tct.comp_id							AND
					tid.ct_transaction = tct.ct_transaction
			WHERE	tct.comp_id = @comp_id								AND
					tct.ct_isAvailableForImport	 = 'True'				AND
					(@supp_id	= - 1 OR tct.supp_id = @supp_id)		AND
					tct.ct_date BETWEEN @datefrom AND @dateto			AND
					(@docNumber = '' OR tct.ct_docNumber = @docNumber)	AND
					tid.comp_id	IS NULL

	END

GO

CREATE PROCEDURE spCommercialTransactions_GetBlockData4SaleTerms
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT
			SELECT
				@comp_id		= 1,
				@ct_transaction	= 3035
		*/
		-- -------------------------------------------------
		SELECT
			tct.ct_ABalance,
			ISNULL(tst.st_blockPage168IfHasBalance, 'False')	[st_blockPage168IfHasBalance],
			ISNULL(tst.st_blockPage640IfHasBalance, 'False')	[st_blockPage640IfHasBalance]
			FROM tbCommercialTransactions	AS tct	WITH(NOLOCK)
				INNER JOIN tbSalesTerms		AS tst	WITH(NOLOCK)
				ON	tst.comp_id = tct.comp_id	AND
					tst.st_id	= tct.st_id
			WHERE	tct.comp_id =  @comp_id		AND
					tct.ct_transaction = @ct_transaction

	END
GO



-- NOTA, Cuando Marina pida el tema de Intereses, usar los Grises de la 2da solapa de tbSalesTerms retornando el importe del boton como el importe mas esos intereses SOLO si la cuota esta vencida.

CREATE PROCEDURE [dbo].[spCommercialTransactions_GetCommercialTransactions4MercadoPagoButtons]
(
	@comp_id					INT,
	@guidCust					UNIQUEIDENTIFIER,
	@guidItem					UNIQUEIDENTIFIER,
	@docExpirationDateFrom		DATETIME,
	@docExpirationDateTo		DATETIME,
	@CuotaExpirationDateFrom	DATETIME,
	@CuotaExpirationDateTo		DATETIME,
	@brag_id					INT,
	@intDebt2Inform				INT, --1 Total del Comprobante / 2 Cuotas Vencidas
	@st_id						INT,
	@df_id						INT,
	@docNumber					INT,
	@bitRegenerateLinks			BIT,
	@st_it4Filter				INT  ,
	@user_id					INT,
	@prof_id					INT,
	@bra_id						INT
)
AS
	BEGIN

		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'

		-- -------------------------------------------------------------------------------------------
		-- TEST    SELECT dbo.fnGetCollectionInterest(1,22172700,21912584)
		-- -------------------------------------------------------------------------------------------
		/*
		DECLARE
		@comp_id					INT = 1,
		@guidCust					UNIQUEIDENTIFIER = 'DB758F19-EBE5-482D-8C1B-F931FF3E0C21' ,
		@guidItem					UNIQUEIDENTIFIER = NEWID(),
		@docExpirationDateFrom		DATETIME = '1900-01-01',
		@docExpirationDateTo		DATETIME = '2999-01-01',
		@CuotaExpirationDateFrom	DATETIME = '1900-01-01',
		@CuotaExpirationDateTo		DATETIME = '2999-01-01',
		@brag_id					INT = -1,
		@intDebt2Inform				INT = 2, --1 Total del Comprobante / 2 Cuotas Vencidas
		@st_id						INT = 189,
		@df_id						INT = -1,
		@docNumber					INT = 0,
		@bitRegenerateLinks			BIT = 1,
		@st_it4Filter				INT = -1  ,
		@user_id					INT = 1,
		@prof_id					INT = 1,
		@bra_id						INT = 1
		*/
		-- -------------------------------------------------------------------------------------------



		SET @docExpirationDateFrom		= dbo.fnGetEnd_or_BeginOfDate(@docExpirationDateFrom, 'False')
		SET @docExpirationDateTo		= dbo.fnGetEnd_or_BeginOfDate(@docExpirationDateTo	, 'True')

		SET @CuotaExpirationDateFrom	= dbo.fnGetEnd_or_BeginOfDate(@CuotaExpirationDateFrom, 'False')
		SET @CuotaExpirationDateTo		= dbo.fnGetEnd_or_BeginOfDate(@CuotaExpirationDateTo	, 'True')


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de CLIENTES para Filtros
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf		WITH (NOLOCK)
				WHERE tcf.sl_guid = @guidCust     AND
					  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT
						tc.cust_id
					FROM tbCustomer AS tc	WITH (NOLOCK)
					WHERE tc.comp_id  = @comp_id
			END

		--SELECT * FROM @tblComplexFilter_Items
		-- -------------------------------------------------------------


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @bitAllItems AS BIT = 'False'
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf		WITH (NOLOCK)
				WHERE tcf.sl_guid = @guidItem     AND
					  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
					SET @bitAllItems = 'True'
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti	WITH (NOLOCK)
						WHERE ti.comp_id = @comp_id
			END

		--SELECT * FROM @tblComplexFilter_Items
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------------------------
		-- Saldos de Facturas
		-- -------------------------------------------------------------------------------
		IF @intDebt2Inform = 1
			BEGIN
				SELECT

					tct.ct_transaction,
					0																								[ctl_id],
					dbo.fnGetCommercialTransactionDescription(tct.comp_id,2,tct.ct_transaction)		+ ' ' +
					ISNULL(	(SELECT TOP 1  dbo.fnstrFirstWordOfString(	CASE
																			WHEN titd.itm_desc IS NOT NULL	THEN titd.itm_desc
																			WHEN ti.comp_id IS NOT NULL		THEN ti.item_desc
																			ELSE ''
																		END
																		)
								FROM tbItemTransactions AS tit					WITH (NOLOCK)
								LEFT JOIN tbItem		AS ti					WITH (NOLOCK)
									ON	ti.comp_id			= tit.comp_id AND
										ti.item_id			= tit.item_id
								LEFT JOIN tbItemTransactionDetails AS titd		WITH (NOLOCK)
									ON	titd.comp_id		= tit.comp_id			AND
										titd.bra_id			= tit.bra_id			AND
										titd.ct_transaction = tit.ct_transaction	AND
										titd.it_transaction = tit.it_transaction
					       		WHERE	tit.comp_id			= tct.comp_id AND
					       				tit.ct_transaction	= tct.ct_transaction),'')								[Description],
					CONVERT(DECIMAL(19,2),
					dbo.fnGetExchange2( tct.comp_id, tct.ct_ABalance,tct.ct_ACurrency,tb.curr_id,0,0,0,'False')) 	[originalBalance] ,
					CONVERT(DECIMAL(19,2),
					dbo.fnGetExchange2( tct.comp_id, tct.ct_ABalance,tct.ct_ACurrency,tb.curr_id,0,0,0,'False')
						+
					dbo.fnGetCollectionInterest(tct.comp_id,tct.ct_transaction,NULL))								[Balance] ,
					CASE
						WHEN tcf.comp_id IS NOT NULL THEN tcf.custf_name
						ELSE tc.cust_name
					END																								[Customer],
					tct.ct_payDate																					[PayDate],
					tct.cust_id,
					tb.curr_id,
					CASE
						WHEN tcf.comp_id IS NOT NULL THEN   tc.cust_email
						ELSE								tc.cust_email
					END																								[email],
					CASE
						WHEN tcf.comp_id IS NOT NULL THEN   tcf.custf_cellPhone
						ELSE								tc.cust_phone1
					END																								[phone]	,
					0																								[isTotalGrouping]	,
					ISNULL(tcc.DECIDIRBP_byDefaultCustomerEMail,'')													[DECIDIRBP_byDefaultCustomerEMail]
				FROM tbCommercialTransactions			AS tct			WITH (NOLOCK)
				INNER JOIN tbUsers4BranchFilter			AS tubf			WITH (NOLOCK)
					ON	tubf.comp_id	= tct.comp_id	AND
						tubf.bra_id		= tct.bra_id	AND
						tubf.[user_id]  = @user_id
				INNER JOIN @tblComplexFilter_Customer	AS tmp
					ON tmp.cust_id = tct.cust_id
				INNER JOIN tbBranch						AS tb			WITH (NOLOCK)
					ON	tb.comp_id		= tct.comp_id	AND
						tb.bra_id		= tct.bra_id
				INNER JOIN tbCustomer					AS tc			WITH (NOLOCK)
					ON	tc.comp_id		= tct.comp_id	AND
						tc.cust_id		= tct.cust_id
				LEFT JOIN tbCustomerFamily				AS tcf			WITH (NOLOCK)
					ON	tcf.comp_id		= tct.comp_id	AND
						tcf.custf_id	= tct.custf_id	AND
						tcf.cust_id		= tct.cust_id
				INNER JOIN tbSalesTerms					AS tst			WITH (NOLOCK)
					ON	tst.st_id		= @st_id		AND
						tst.comp_id		= @comp_id
				INNER JOIN tbCreditCard					AS tcc			WITH (NOLOCK)
					ON	tcc.comp_id		= tst.comp_id	AND
						tcc.cc_id		= tst.cc_id
				INNER JOIN tbMercadoLibre_Stores		AS tmls			WITH (NOLOCK)
					ON tmls.comp_id		= tcc.comp_id	AND
						tmls.mls_id		= tcc.mls_id
				WHERE	tct.comp_id		= @comp_id		AND
						( @df_id = -1 OR tct.df_id = @df_id) AND
						( @docNumber = 0 OR tct.ct_docNumber = CONVERT(NVARCHAR(50),@docNumber)) AND

						(	-- MOS 07-2022 x Decidir
							(
								tcc.cc_MPIsEnabled		= 1
								    AND
								tcc.mls_id IS NOT NULL
							)
							OR
								tcc.DECIDIRBP_enabled	= 1
						)																		AND


						tct.ct_payDate BETWEEN @docExpirationDateFrom AND @docExpirationDateTo AND
						tct.ct_ABalance > 0				AND
						tct.sd_id		IN (1,4,21) 	AND
						tmls.mls_disabled		= 0		AND
						(@st_it4Filter = -1 OR @st_it4Filter = tct.st_id)	AND
						(@bitRegenerateLinks	= 1 OR (@bitRegenerateLinks = 0 AND  NOT EXISTS (	-- Mierda Lenta pero sino hay que hacer otro CAOS MAYOR al que ya pidieron y ESTOY REPODRIDO DE ESTE TEMA YA !!!
																									SELECT TOP 1 1
																										FROM tbCreditCard_VoucherRelations	AS tccvr		WITH (NOLOCK)
																										INNER JOIN tbCreditCard_Voucher		AS tccv			WITH (NOLOCK)
																											ON	tccv.comp_id			= tccvr.comp_id			AND
																												tccv.ccv_id				= tccvr.ccv_id
																										WHERE	tccvr.comp_id			= tct.comp_id			AND
																												tccvr.ct_transaction	= tct.ct_transaction	AND
																												tccvr.ctl_id			IS NULL					AND
																												tccv.ccv_MPBotonDePagoIsTotalButton = 'False'	AND
																												tccv.ccv_MPBotonDePagoIsExpired = 0
																								))	) AND
						CASE
							WHEN @bitAllItems = 'True'				THEN 1
							WHEN @bitAllItems = 'False' AND EXISTS(	SELECT TOP 1 1
							                                       		FROM tbItemTransactions AS tit					WITH (NOLOCK)
							                                       		INNER JOIN @tblComplexFilter_Items AS tcfi
							                                       			ON tcfi.item_id = tit.item_id
							                                       		WHERE	tit.comp_id			= tct.comp_id			AND
							                                       				tit.ct_transaction	= tct.ct_transaction
																)	THEN 1
							ELSE										 0
						END	 = 1

			END


		-- -------------------------------------------------------------------------------
		-- Saldos AGRUPADOS
		-- -------------------------------------------------------------------------------
		ELSE IF @intDebt2Inform = 5
			BEGIN
				SELECT
					tct.ct_transaction,
					tctl.ctl_id,
					dbo.fnGetCommercialTransactionDescription(tct.comp_id,2,tct.ct_transaction) +
					CASE
						WHEN tctl.comp_id IS NOT NULL THEN	' #' + CONVERT(NVARCHAR(5),ISNULL(tctl.ctl_payNumber,0)) + 'de' + CONVERT(NVARCHAR(5),ISNULL(tctl.ctl_payNumberTotalQty,0))
						ELSE ''
					END + ' ' +
					ISNULL(	(SELECT TOP 1  dbo.fnstrFirstWordOfString(	CASE
																			WHEN titd.itm_desc IS NOT NULL	THEN titd.itm_desc
																			WHEN ti.comp_id IS NOT NULL		THEN ti.item_desc
																			ELSE ''
																		END
																		)
								FROM tbItemTransactions AS tit		WITH (NOLOCK)
								LEFT JOIN tbItem		AS ti		WITH (NOLOCK)
									ON	ti.comp_id			= tit.comp_id AND
										ti.item_id			= tit.item_id
								LEFT JOIN tbItemTransactionDetails AS titd	WITH (NOLOCK)
									ON	titd.comp_id		= tit.comp_id			AND
										titd.bra_id			= tit.bra_id			AND
										titd.ct_transaction = tit.ct_transaction	AND
										titd.it_transaction = tit.it_transaction
					       		WHERE	tit.comp_id			= tct.comp_id AND
					       				tit.ct_transaction	= tct.ct_transaction),'')
																													[Description],
					CONVERT(DECIMAL(19,2),
					dbo.fnGetExchange2( tct.comp_id,
													CASE
														WHEN tctl.comp_id IS NOT NULL THEN	tctl.ct_ABalance
														ELSE								tct.ct_ABalance
													END
													,
													CASE
														WHEN tctl.comp_id IS NOT NULL THEN	tctl.curr_id
														ELSE								tct.ct_ACurrency
													END

													,tb.curr_id,0,0,0,'False'))										[originalBalance] ,
					CONVERT(DECIMAL(19,2),
					dbo.fnGetExchange2( tct.comp_id,
													CASE
														WHEN tctl.comp_id IS NOT NULL THEN	tctl.ct_ABalance
														ELSE								tct.ct_ABalance
													END
													,
													CASE
														WHEN tctl.comp_id IS NOT NULL THEN	tctl.curr_id
														ELSE								tct.ct_ACurrency
													END
													
													,tb.curr_id,0,0,0,'False')
						+
					dbo.fnGetCollectionInterest(tct.comp_id,tct.ct_transaction,tctl.ctl_id))						[Balance] ,
					tc.cust_name																					[Customer],
					CASE
						WHEN tctl.comp_id IS NULL THEN	tct.ct_payDate
						ELSE							tctl.ctl_payDate
					END																								[PayDate],
					tct.cust_id																						[cust_id],
					tb.curr_id																						[curr_id],
					tc.cust_email																					[email],
					tc.cust_phone1																					[phone],
					1																								[isTotalGrouping],
					''																								[transactionsDetail],
					ISNULL(tcc.DECIDIRBP_byDefaultCustomerEMail,'')													[DECIDIRBP_byDefaultCustomerEMail]
				INTO #tmpTable
				FROM tbCommercialTransactions				AS tct			WITH (NOLOCK)
				INNER JOIN tbUsers4BranchFilter			AS tubf			WITH (NOLOCK)
					ON	tubf.comp_id	= tct.comp_id	AND
						tubf.bra_id		= tct.bra_id	AND
						tubf.[user_id]  = @user_id
				INNER JOIN @tblComplexFilter_Customer	AS tmp
					ON tmp.cust_id = tct.cust_id
				INNER JOIN tbBranch							AS tb			WITH (NOLOCK)
					ON	tb.comp_id			= tct.comp_id	AND
						tb.bra_id			= tct.bra_id
				INNER JOIN tbCustomer						AS tc			WITH (NOLOCK)
					ON	tc.comp_id			= tct.comp_id	AND
						tc.cust_id			= tct.cust_id
				LEFT JOIN tbCustomerFamily					AS tcf			WITH (NOLOCK)
					ON	tcf.comp_id			= tct.comp_id	AND
						tcf.custf_id		= tct.custf_id	AND
						tcf.cust_id			= tct.cust_id
				INNER JOIN tbSalesTerms						AS tst			WITH (NOLOCK)
					ON	tst.st_id			= @st_id		AND
						tst.comp_id			= @comp_id
				INNER JOIN tbCreditCard						AS tcc			WITH (NOLOCK)
					ON	tcc.comp_id			= tst.comp_id	AND
						tcc.cc_id			= tst.cc_id
				INNER JOIN tbMercadoLibre_Stores			AS tmls			WITH (NOLOCK)
					ON tmls.comp_id			= tcc.comp_id	AND
						tmls.mls_id			= tcc.mls_id
				LEFT JOIN tbCommercialTransactionsLoan		AS tctl			WITH (NOLOCK)
					ON  tctl.comp_id		= tct.comp_id	AND
						tctl.ct_transaction = tct.ct_transaction
				WHERE	tct.comp_id = @comp_id				AND
						( @df_id = -1 OR tct.df_id = @df_id) AND
						( @docNumber = 0 OR tct.ct_docNumber = CONVERT(NVARCHAR(50),@docNumber)) AND
						(
							(	-- MOS 07-2022 x Decidir
								tcc.cc_MPIsEnabled		= 1
								    AND
								tcc.mls_id IS NOT NULL
							)
							OR
								tcc.DECIDIRBP_enabled	= 1
						)																		AND
						--tcc.cc_MPIsEnabled = 1				AND
						--tcc.mls_id IS NOT NULL				AND
						(
							( tctl.comp_id IS NOT NULL AND  tctl.ctl_payDate BETWEEN @CuotaExpirationDateFrom AND @CuotaExpirationDateTo)
							OR
							( tctl.comp_id IS     NULL AND  tct.ct_payDate   BETWEEN @docExpirationDateFrom   AND @docExpirationDateTo)
						)  AND
						CASE
							WHEN tctl.comp_id IS NOT NULL AND tctl.ct_ABalance > 0 THEN 1
							WHEN tctl.comp_id IS NOT NULL AND tctl.ct_ABalance = 0 THEN 0
							WHEN tctl.comp_id IS NULL     AND tct.ct_ABalance  > 0 THEN 1
							ELSE 0
						END = 1								AND
						tct.sd_id		IN (1,4,21)			AND
						tmls.mls_disabled = 0				AND
						(@st_it4Filter = -1 OR @st_it4Filter = tct.st_id)	AND

						(@bitRegenerateLinks	= 1 OR (@bitRegenerateLinks = 0 AND  NOT EXISTS (	-- Mierda Lenta pero sino hay que hacer otro CAOS MAYOR al que ya pidieron y ESTOY REPODRIDO DE ESTE TEMA YA !!!
																									SELECT TOP 1 1
																										FROM tbCreditCard_VoucherRelations	AS tccvr		WITH (NOLOCK)
																										INNER JOIN tbCreditCard_Voucher		AS tccv			WITH (NOLOCK)
																											ON	tccv.comp_id			= tccvr.comp_id			AND
																												tccv.ccv_id				= tccvr.ccv_id
																										WHERE	tccvr.comp_id			= tct.comp_id			AND
																												tccvr.ct_transaction	= tct.ct_transaction	AND
																												(
																													(tctl.comp_id IS NOT NULL AND tccvr.ctl_id = tctl.ctl_id)
																														OR
																													 tctl.comp_id IS NULL
																												)												AND
																												tccv.ccv_MPBotonDePagoIsTotalButton = 'True'	AND
																												tccv.ccv_MPBotonDePagoIsExpired = 0
																								))	) AND
						CASE
							WHEN 1 = 1 THEN 1
							WHEN @bitAllItems = 'True'				THEN 1
							WHEN @bitAllItems = 'False' AND EXISTS(	SELECT TOP 1 1
							                                       		FROM tbItemTransactions				AS tit	WITH (NOLOCK)
							                                       		INNER JOIN @tblComplexFilter_Items	AS tcfi
							                                       			ON tcfi.item_id = tit.item_id
							                                       		WHERE	tit.comp_id			= tct.comp_id			AND
							                                       				tit.ct_transaction	= tct.ct_transaction
																)	THEN 1
							ELSE										 0
						END	 = 1




						-- Agrupa esta tabla Temporal por el TOTAL de Cupones y CLiente
						-- Toda esta MIERDA porque a los FORROS de SQL se les ocurrió RECIEN hacer la PUTA funcion de agregado de cosas para SQL 2017 (string_agg )
						-- y por PUTA compatibilidad no lo podemos usar.

						declare @FinalTable	 table	(	cust_id INT PRIMARY KEY,
													ct_transaction	INT,
													ctl_id			INT,
													[Description]	VARCHAR(MAX),
													originalBalance DECIMAL(19,2) ,
													Balance			DECIMAL(19,2) ,
													Customer		VARCHAR(MAX),
													PayDate			DATETIME,
													curr_id			INT,
													email			VARCHAR(MAX),
													phone			VARCHAR(MAX),
													isTotalGrouping	BIT,
												    transactionsCount   INT	,
													transactionsDetail	VARCHAR(MAX)
												)


						INSERT INTO @FinalTable
						(
							cust_id,
							ct_transaction,
							ctl_id,
							[Description],
							originalBalance,
							Balance,
							Customer,
							PayDate,
							curr_id,
							email,
							phone,
							isTotalGrouping,
							transactionsDetail
						)
						SELECT	cust_id								[cust_id],
								0									[ct_transaction],
								0									[ctl_id],
								''									[Description],
								CONVERT(DECIMAL(19,2),SUM(originalBalance))	[originalBalance] ,
								CONVERT(DECIMAL(19,2),SUM(Balance))			[Balance] ,
								Customer							[Customer],
								MAX(PayDate)						[PayDate],
								MAX(curr_id)						[curr_id],
								email								[email],
								phone								[phone],
								1									[isTotalGrouping],
								CONVERT(VARCHAR(8000),'')			[transactionsDetail]
							FROM #tmpTable
						WHERE cust_id IS NOT NULL
							GROUP BY cust_id,Customer,email,phone


						DECLARE @strTransactionsDetail		VARCHAR(MAX) = ''
						DECLARE @strDESCRIPTION				VARCHAR(MAX) = ''
						DECLARE @curCust_id					INT
						DECLARE @curDESCRIPTION				VARCHAR(MAX)
						DECLARE @curCt_transaction			INT
						DECLARE @curCtl_id					INT
						DECLARE @intTransactionCounter			    INT = 0
						DECLARE curPutoUpdate CURSOR LOCAL FAST_FORWARD FOR
							SELECT cust_id,[DESCRIPTION],ct_transaction,ISNULL(ctl_id,0)
								FROM  #tmpTable
								ORDER BY cust_id ASC


						OPEN			curPutoUpdate
						FETCH NEXT FROM curPutoUpdate INTO @curCust_id,
														   @curDESCRIPTION,
														   @curCt_transaction,
														   @curCtl_id

						DECLARE @intCustID AS INT = @curCust_id
						WHILE @@FETCH_STATUS = 0
							BEGIN


								SET @strTransactionsDetail = @strTransactionsDetail + CONVERT(NVARCHAR(10),@curCt_transaction) + '-' + CONVERT(NVARCHAR(10),ISNULL(@curCtl_id,0)) + ','

								IF @intTransactionCounter = 0
									BEGIN
										SET @strDESCRIPTION        = @strDESCRIPTION        + dbo.fnStrAllTrim(@curDESCRIPTION)
									END
								ELSE IF @intTransactionCounter = 1
									BEGIN
										SET @strDESCRIPTION        = @strDESCRIPTION        + ' y otros'
									END

								SET @intTransactionCounter = @intTransactionCounter + 1


								FETCH NEXT FROM curPutoUpdate INTO @curCust_id,
																   @curDESCRIPTION,
																   @curCt_transaction,
																   @curCtl_id

								IF @curCust_id <> @intCustID
									BEGIN
										UPDATE @FinalTable
											SET [Description]		= @strDESCRIPTION + ' ' +
																							CASE
																								WHEN @intTransactionCounter > 1 THEN CONVERT(NVARCHAR(10),@intTransactionCounter - 1)
																								ELSE ''
																							END,
												transactionsDetail	= @strTransactionsDetail ,
												transactionsCount	= @intTransactionCounter
											WHERE cust_id			= @intCustID

										SET @intCustID = @curCust_id
										SET @strDESCRIPTION			= ''
										SET @strTransactionsDetail	= ''
										SET @intTransactionCounter	= 0
									END

							END
						CLOSE		curPutoUpdate
						DEALLOCATE	curPutoUpdate

						IF @curCust_id = @intCustID
							BEGIN
								UPDATE @FinalTable
									SET [Description]		= @strDESCRIPTION + ' ' +
																							CASE
																								WHEN @intTransactionCounter > 1 THEN CONVERT(NVARCHAR(10),@intTransactionCounter - 1)
																								ELSE ''
																							END,
										transactionsDetail	= @strTransactionsDetail  ,
										transactionsCount	= @intTransactionCounter
									WHERE cust_id			= @intCustID

								SET @intCustID = @curCust_id
								SET @strDESCRIPTION = ''
								SET @strTransactionsDetail = ''
							END



						SELECT * FROM    @FinalTable

			END

		ELSE
		-- -------------------------------------------------------------------------------
		-- Saldos de Cuotas Unicamente
		-- -------------------------------------------------------------------------------
			BEGIN
				SELECT
					tct.ct_transaction,
					tctl.ctl_id,
					dbo.fnGetCommercialTransactionDescription(tct.comp_id,2,tct.ct_transaction) + ' #' + CONVERT(NVARCHAR(5),tctl.ctl_payNumber) + 'de' + CONVERT(NVARCHAR(5),tctl.ctl_payNumberTotalQty)	+ ' ' +
					ISNULL(	(SELECT TOP 1  dbo.fnstrFirstWordOfString(	CASE
																			WHEN titd.itm_desc IS NOT NULL	THEN titd.itm_desc
																			WHEN ti.comp_id IS NOT NULL		THEN ti.item_desc
																			ELSE ''
																		END
																		)
								FROM tbItemTransactions AS tit		WITH (NOLOCK)
								LEFT JOIN tbItem		AS ti		WITH (NOLOCK)
									ON	ti.comp_id			= tit.comp_id AND
										ti.item_id			= tit.item_id
								LEFT JOIN tbItemTransactionDetails AS titd	WITH (NOLOCK)
									ON	titd.comp_id		= tit.comp_id			AND
										titd.bra_id			= tit.bra_id			AND
										titd.ct_transaction = tit.ct_transaction	AND
										titd.it_transaction = tit.it_transaction
					       		WHERE	tit.comp_id			= tct.comp_id AND
					       				tit.ct_transaction	= tct.ct_transaction),'')
																													[Description],
					CONVERT(DECIMAL(19,2),
					dbo.fnGetExchange2( tct.comp_id, tctl.ct_ABalance,tctl.curr_id,tb.curr_id,0,0,0,'False'))		[originalBalance] ,
					CONVERT(DECIMAL(19,2),
					dbo.fnGetExchange2( tct.comp_id, tctl.ct_ABalance,tctl.curr_id,tb.curr_id,0,0,0,'False')
											+
					dbo.fnGetCollectionInterest(tct.comp_id,tct.ct_transaction,tctl.ctl_id))						[Balance] ,
					CASE
						WHEN tcf.comp_id IS NOT NULL THEN tcf.custf_name
						ELSE tc.cust_name
					END																								[Customer],
					tctl.ctl_payDate																				[PayDate],
					tct.cust_id,
					tb.curr_id,
					CASE
						WHEN tcf.comp_id IS NOT NULL THEN   tc.cust_email
						ELSE								tc.cust_email
					END																								[email],
					CASE
						WHEN tcf.comp_id IS NOT NULL THEN   tcf.custf_cellPhone
						ELSE								tc.cust_phone1
					END																								[phone],
					0																								[isTotalGrouping],
					ISNULL(tcc.DECIDIRBP_byDefaultCustomerEMail,'')													[DECIDIRBP_byDefaultCustomerEMail]
				FROM tbCommercialTransactions				AS tct			WITH (NOLOCK)
				INNER JOIN tbUsers4BranchFilter				AS tubf			WITH (NOLOCK)
					ON	tubf.comp_id	= tct.comp_id	AND
						tubf.bra_id		= tct.bra_id	AND
						tubf.[user_id]  = @user_id
				INNER JOIN @tblComplexFilter_Customer	AS tmp
					ON tmp.cust_id = tct.cust_id
				INNER JOIN tbBranch							AS tb			WITH (NOLOCK)
					ON	tb.comp_id			= tct.comp_id	AND
						tb.bra_id			= tct.bra_id
				INNER JOIN tbCustomer						AS tc			WITH (NOLOCK)
					ON	tc.comp_id			= tct.comp_id	AND
						tc.cust_id			= tct.cust_id
				LEFT JOIN tbCustomerFamily					AS tcf			WITH (NOLOCK)
					ON	tcf.comp_id			= tct.comp_id	AND
						tcf.custf_id		= tct.custf_id	AND
						tcf.cust_id			= tct.cust_id
				INNER JOIN tbSalesTerms						AS tst			WITH (NOLOCK)
					ON	tst.st_id			= @st_id		AND
						tst.comp_id			= @comp_id
				INNER JOIN tbCreditCard						AS tcc			WITH (NOLOCK)
					ON	tcc.comp_id			= tst.comp_id	AND
						tcc.cc_id			= tst.cc_id
				INNER JOIN tbMercadoLibre_Stores			AS tmls			WITH (NOLOCK)
					ON tmls.comp_id			= tcc.comp_id	AND
						tmls.mls_id			= tcc.mls_id
				INNER JOIN tbCommercialTransactionsLoan		AS tctl			WITH (NOLOCK)
					ON  tctl.comp_id		= tct.comp_id	AND
						tctl.ct_transaction = tct.ct_transaction
				WHERE	tct.comp_id = @comp_id				AND
						( @df_id = -1 OR tct.df_id = @df_id) AND
						( @docNumber = 0 OR tct.ct_docNumber = CONVERT(NVARCHAR(50),@docNumber)) AND
						(
							(	-- MOS 07-2022 x Decidir
								tcc.cc_MPIsEnabled		= 1
								    AND
								tcc.mls_id IS NOT NULL
							)
							OR
								tcc.DECIDIRBP_enabled	= 1
						)																		AND
						--tcc.cc_MPIsEnabled = 1				AND
						--tcc.mls_id IS NOT NULL				AND
						tctl.ctl_payDate BETWEEN @CuotaExpirationDateFrom AND @CuotaExpirationDateTo AND
						tctl.ct_ABalance > 0				AND
						tct.sd_id		IN (1,4,21)			AND
						tmls.mls_disabled = 0				AND
						(@st_it4Filter = -1 OR @st_it4Filter = tct.st_id)	AND

						(@bitRegenerateLinks	= 1 OR (@bitRegenerateLinks = 0 AND  NOT EXISTS (	-- Mierda Lenta pero sino hay que hacer otro CAOS MAYOR al que ya pidieron y ESTOY REPODRIDO DE ESTE TEMA YA !!!
																									SELECT TOP 1 1
																										FROM tbCreditCard_VoucherRelations	AS tccvr		WITH (NOLOCK)
																										INNER JOIN tbCreditCard_Voucher		AS tccv			WITH (NOLOCK)
																											ON	tccv.comp_id			= tccvr.comp_id			AND
																												tccv.ccv_id				= tccvr.ccv_id
																										WHERE	tccvr.comp_id			= tctl.comp_id			AND
																												tccvr.ct_transaction	= tctl.ct_transaction	AND
																												tccvr.ctl_id			= tctl.ctl_id			AND
																												tccv.ccv_MPBotonDePagoIsTotalButton = 'False'	AND
																												tccv.ccv_MPBotonDePagoIsExpired = 0
																								))	) AND
						CASE
							WHEN @bitAllItems = 'True'				THEN 1
							WHEN @bitAllItems = 'False' AND EXISTS(	SELECT TOP 1 1
							                                       		FROM tbItemTransactions				AS tit	WITH (NOLOCK)
							                                       		INNER JOIN @tblComplexFilter_Items	AS tcfi
							                                       			ON tcfi.item_id = tit.item_id
							                                       		WHERE	tit.comp_id			= tct.comp_id			AND
							                                       				tit.ct_transaction	= tct.ct_transaction
																)	THEN 1
							ELSE										 0
						END	 = 1			AND
						CASE
							WHEN @intDebt2Inform = 2									THEN 1
							WHEN @intDebt2Inform = 3 AND tctl.ctl_payDate <  GETDATE()	THEN 1
							WHEN @intDebt2Inform = 4 AND tctl.ctl_payDate >= GETDATE()	THEN 1
							ELSE 0
						END		= 1
			END




	END


GO




CREATE PROCEDURE [dbo].[spCommercialTransactions_getDataByFilters]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@selection_id		INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@paydatefrom		DATETIME,
	@paydateto			DATETIME,
	@sd_id				INT,
	@ispurchase			BIT,
	@user_id			INT,
	@bra_id_user		INT,
	@iscompensed		INT,					--  Compensado					-1 : Todos , 0 : No compensado , 1 : Compensado ( Si es compras llega -1)
	@cb_id				INT,					--  Sucursal del Cliente		-1 : Ninguno ( Si es compras llega -1)
	@brag_id			INT,
	@ct_docNumber		NVARCHAR(50),			-- Número de Comprobante -1 = Todos
	@OptionBalance		INT						-- Tipo de Saldo. -1 Todos, 1 Solo Comprobantes con Saldo Pendiente,  2 Solo Comprobantes Sin Saldo Pendiente


)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	/********************************************************************************************************
	si @ispurchase es True significa que la consulta está relacionada a una compra por lo tanto
	se debe considerar el @selection_id como proveedor o sea supp_id, si @ispurchase es False
	significa que la consulta está relacionada a una venta, en éste caso se debe considerar el
	@selection_id como cliente o sea cust_id
	*********************************************************************************************************/





-- -----------------------------------------------------------
-- Testing
-- -----------------------------------------------------------
/*
	declare 	@comp_id			int,
				@lang_id			int,
				@bra_id				int,
				@selection_id		int,
				@datefrom			datetime,
				@dateto				datetime,
				@paydatefrom		datetime,
				@paydateto			datetime,
				@sd_id				int,
				@ispurchase			bit,
				@user_id			int,
				@bra_id_user		INT,
				@iscompensed		INT,
			   	@cb_id				INT ,
			   	@brag_id			INT = -1
	select		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@selection_id		= 19,
				@datefrom			= convert(datetime,'1900-01-01'),
				@dateto				= convert(datetime,'9999-12-13'),
				@paydatefrom		= convert(datetime,'1900-01-01'),
				@paydateto			= convert(datetime,'9999-12-31'),
				@sd_id				= -2,
				@ispurchase			= 'False',
				@user_id			= 1,
				@bra_id_user		= -1,
				@iscompensed		= -1,
				@cb_id				= -1


IF NOT OBJECT_ID('tempdb.dbo.#tmpIT')				IS NULL DROP TABLE #tmpIT
IF NOT OBJECT_ID('tempdb.dbo.#tmpAPP')				IS NULL DROP TABLE #tmpAPP
IF NOT OBJECT_ID('tempdb.dbo.#tmpTCTN')				IS NULL DROP TABLE #tmpTCTN
IF NOT OBJECT_ID('tempdb.dbo.#tmpRetentions')		IS NULL DROP TABLE #tmpRetentions
IF NOT OBJECT_ID('tempdb.dbo.#tmpData')				IS NULL DROP TABLE #tmpData
*/
-- -----------------------------------------------------------



	SET @ct_docNumber = dbo.fnStrAllTrim(@ct_docNumber)

	-- -----------------------------------------------------------
	-- Selecciona las Sucursales a tener en cuenta segun filtros
	-- -----------------------------------------------------------
	DECLARE		@tmpBranchs TABLE (bra_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchs(bra_id)
		SELECT tbgd.bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE	tbgd.comp_id = @comp_id AND
					tbgd.brag_id = @brag_id
	DECLARE @intBranchsInserted AS INT = @@ROWCOUNT
	IF @intBranchsInserted = 0 AND @bra_id_user = -1
		BEGIN
			INSERT INTO @tmpBranchs(bra_id)
				SELECT tb.bra_id
					FROM tbBranch tb		WITH (NOLOCK)
					WHERE	tb.comp_id						= @comp_id AND
							ISNULL(tb.bra_disabled,'False') = 'False'
		END
	IF @intBranchsInserted = 0 AND @bra_id_user > 0
		BEGIN
			INSERT INTO @tmpBranchs(bra_id)
				VALUES(@bra_id_user)
		END
	-- -----------------------------------------------------------






	-- Fantastica idea de poner en este nombre de variable la cantidad de decimales a redondear.
	-- Quien se IMAGINA que quiere decir @d?
	declare @d int
	set		@d = 2


	-- ---------------------------------------------------------------
	-- Se usa para acelerar un poco esto... ya que tarda DEMASIADOOOO
	-- ---------------------------------------------------------------
	DECLARE @tblSpeedQuery AS TABLE(ct_transaction INT primary key)
	IF @ispurchase = 'TRUE'
		BEGIN
			INSERT INTO @tblSpeedQuery
			(
				ct_transaction
			)
			SELECT tct.ct_transaction
				FROM tbCommercialTransactions tct					WITH (NOLOCK)
				INNER JOIN @tmpBranchs	tmp
					ON tmp.bra_id			= tct.bra_id
				INNER JOIN tbUsers4BranchFilter				vubf	WITH (NOLOCK)
					ON	vubf.comp_id		=	tct.comp_id
					AND vubf.bra_id			=	tct.bra_id
					AND vubf.[user_id]		=	@user_id
				WHERE	tct.comp_id			=	@comp_id		AND
						tct.supp_id			=   @selection_id	AND
						(@ct_docNumber = '-1' OR tct.ct_docNumber = @ct_docNumber)	AND
						CASE
							WHEN @OptionBalance	 = -1 THEN 1						-- Tipo de Saldo. -1 Todos, 1 Solo Comprobantes con Saldo Pendiente,  2 Solo Comprobantes Sin Saldo Pendiente
							WHEN @OptionBalance  = 1 AND tct.ct_ABalance <> 0 THEN  1
							WHEN @OptionBalance  = 2 AND tct.ct_ABalance =  0 THEN  1
							ELSE													0
						END = 1
		END
	ELSE IF @ispurchase = 'False'
		BEGIN

			INSERT INTO @tblSpeedQuery
			(
				ct_transaction
			)
			SELECT tct.ct_transaction
				FROM tbCommercialTransactions tct					WITH (NOLOCK)
				INNER JOIN @tmpBranchs	tmp
					ON tmp.bra_id			= tct.bra_id
				INNER JOIN tbUsers4BranchFilter				vubf	WITH (NOLOCK)
					ON	vubf.comp_id		=	tct.comp_id
					AND vubf.bra_id			=	tct.bra_id
					AND vubf.[user_id]		=	@user_id
			WHERE	tct.comp_id = @comp_id		AND
					tct.cust_id = @selection_id AND
					(@ct_docNumber = '-1' OR tct.ct_docNumber = @ct_docNumber)	AND
					CASE
						WHEN @OptionBalance	 = -1 THEN 1						-- Tipo de Saldo. -1 Todos, 1 Solo Comprobantes con Saldo Pendiente,  2 Solo Comprobantes Sin Saldo Pendiente
						WHEN @OptionBalance  = 1 AND tct.ct_ABalance <> 0 THEN  1
						WHEN @OptionBalance  = 2 AND tct.ct_ABalance =  0 THEN  1
						ELSE													0
					END = 1



			-- Borra las gtrabsacciones que no correcpondan a la sucursal del cliente requerida.
			IF @cb_id <> -1
				BEGIN

					DELETE FROM @tblSpeedQuery
						FROM @tblSpeedQuery tmp
						INNER JOIN tbCommercialTransactions tct
							ON	tct.comp_id			= @comp_id AND
								tct.ct_transaction	= tmp.ct_transaction
						WHERE ISNULL(tct.cb_id,-1) <> @cb_id

				END


			-- Borra las gtrabsacciones que no correcpondan al estado de compensacion requerido.
			IF @iscompensed <> -1
				BEGIN
					IF @iscompensed = 0  -- NO COMPENSADOS
						BEGIN
							DELETE FROM @tblSpeedQuery
								FROM @tblSpeedQuery tmp
								WHERE EXISTS(
												SELECT TOP 1  1
													FROM tbItemTransactions tit	WITH (NOLOCK)
													WHERE
															tit.comp_id			= @comp_id				AND
															tit.ct_transaction	= tmp.ct_transaction	AND
															tit.it_isCompensed  = 'True'
											)
										AND
										NOT EXISTS(
												SELECT  TOP 1  1
													FROM tbItemTransactions tit		WITH (NOLOCK)
													WHERE
															tit.comp_id			= @comp_id				AND
															tit.ct_transaction	= tmp.ct_transaction	AND
															tit.it_isCompensed  = 'False'
													)
						END

					IF @iscompensed = 1  -- COMPENSADOS
						BEGIN
							DELETE FROM @tblSpeedQuery
								FROM @tblSpeedQuery tmp
								WHERE EXISTS(
												SELECT  TOP 1  1
													FROM tbItemTransactions tit WITH  (NOLOCK)
													WHERE
															tit.comp_id			= @comp_id				AND
															tit.ct_transaction	= tmp.ct_transaction	AND
															tit.it_isCompensed  = 'False'
											)
						END




					--DELETE FROM @tblSpeedQuery
					--	FROM @tblSpeedQuery tmp
					--	INNER JOIN tbItemTransactions tit
					--		ON	tit.comp_id			= @comp_id AND
					--			tit.ct_transaction	= tmp.ct_transaction
					--	WHERE tit.it_isCompensed <> @iscompensed

				END

		END
	-- ---------------------------------------------------------------



	/****************************************************************************************************/
	/*recuperar el cambio actual entre la moneda de la sucursal con respesto a la del cliente/proveedor */
	DECLARE	@current_exchange			DECIMAL(18,6),
			@curr_id_branch				INT,
			@curr_id_2					INT,
			@bra_PaymentSupp_Id			INT					--Parte:486


	SELECT	@curr_id_branch		= tb.curr_id,
			@bra_PaymentSupp_Id	= ISNULL(tb.bra_PaymentSupp_Id,-1)		--Parte:486
		FROM	tbBranch	tb				WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
		AND		tb.bra_id	= @bra_id



	IF @ispurchase = 'false'
		SELECT	@curr_id_2 =tc.curr_id
			FROM	tbCustomer tc			WITH (NOLOCK)
			WHERE	tc.comp_id = @comp_id AND
					tc.cust_id = @selection_id
	ELSE
		SELECT	@curr_id_2 = tc.curr_id
			FROM	tbSupplier tc			WITH (NOLOCK)
			WHERE	tc.comp_id = @comp_id AND
					tc.supp_id = @selection_id



	SELECT	@current_exchange = dbo.fnGetExchange(@comp_id, 1, @curr_id_2, @curr_id_branch, 0, 0, 'False')
	/****************************************************************************************************/
	--SELECT @curr_id_branch, @curr_id_2
	--SELECT * FROM tbsysCurrency tc




	/****************************************************************************************************/
	/* Agregamos horas para que tome el dia completo a las fechas hasta *********************************/
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,1)
	set	@paydateto	= dbo.fnGetEnd_or_BeginOfDate(@paydateto,1)
	--select @dateto, @paydateto
	/****************************************************************************************************/





	/****************************************************************************************************/
	/* Generacion de temporal para determinar si cada CommercialTransaction tiene items *****************/
	declare @bitBlockIT_TransOfOtherBranch BIT
	select @bitBlockIT_TransOfOtherBranch = isnull(tu.user_authorizationBlockIT_TransOfOtherBranch,'true')
		from tbUser tu
		where tu.user_id = @user_id





	/****************************************************************************************************/
	/****************************************************************************************************/
	SELECT	DISTINCT
			tctn.comp_id,
			tctn.bra_id,
			tctn.ct_transaction,
			1 [value]
	INTO	#tmpTCTN
	FROM	dbo.tbCommercialTransactionNotes			tctn					WITH (NOLOCK)


			INNER JOIN @tblSpeedQuery sq
				ON sq.ct_transaction = tctn.ct_transaction

			INNER JOIN dbo.tbCommercialTransactions		ct						WITH (NOLOCK)
			ON	ct.comp_id			= tctn.comp_id
			AND ct.bra_id			= tctn.bra_id
			AND ct.ct_transaction	= tctn.ct_transaction

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb						WITH (NOLOCK)
			ON	tb.comp_id			=	tctn.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	tctn.bra_id
			--INNER JOIN vwUsers4BranchFilter				vubf
			--ON	vubf.comp_id		=	tctn.comp_id
			--AND vubf.bra_id			=	tb.bra_id
			--AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	tctn.comp_id			=	@comp_id
	--AND	tctn.bra_id				=	@bra_id		--TN : 621
	AND		(len(rtrim(ltrim(tctn.ctn_note1))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note2))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note3))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note4))) > 0)
	--and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or **88
	--		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301

	--SELECT * FROM #tmpTCTN
	/****************************************************************************************************/



	DECLARE @tblSysDocuments AS TABLE(sd_id				INT PRIMARY KEY,
								      sd_isInBalance	bit)
	INSERT INTO @tblSysDocuments	SELECT	td.sd_id,
											td.sd_isInBalance
										FROM tbsysDocuments td		WITH (NOLOCK)
	                            		--WHERE td.sd_isInBalance = 'True'






	/****************************************************************************************************/
	/* Genracion de temporal para determinar retenciones para cada CT ***********************************/
	SELECT	COUNT(*) [count],
			ttm.ct_transaction
	INTO	#tmpRetentions
	FROM	tbTaxMovements								ttm						WITH (NOLOCK)


			INNER JOIN @tblSpeedQuery sq
				ON sq.ct_transaction = ttm.ct_transaction


			INNER JOIN tbTaxName						ttn						WITH (NOLOCK)
			ON	ttn.comp_id			= ttm.comp_id
			AND ttn.tax_id			= ttm.tax_id

			INNER JOIN vwsysTaxClassALL_Retentions		vtcar					WITH (NOLOCK)
			ON	vtcar.tax_class		= ttn.tax_class

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb			WITH (NOLOCK)
			ON	tb.comp_id			=	ttm.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	ttm.bra_id
			--INNER JOIN vwUsers4BranchFilter				vubf
			--ON	vubf.comp_id		=	ttm.comp_id
			--AND vubf.bra_id			=	tb.bra_id
			--AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	ttm.comp_id				= @comp_id
	--AND	ttm.bra_id				= @bra_id	--TN : 621
	AND		ttm.tm_total			> 0
	GROUP BY ttm.ct_transaction

	--SELECT * FROM #tmpRetentions ORDER BY 2
	/****************************************************************************************************/


	-- Para Compras, se fija cual es el proveedor para OTROS PAGOS
	DECLARE @supp_id4OtherPayments AS INT
	SELECT	@supp_id4OtherPayments = tb.bra_PaymentSupp_Id
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id




	/****************************************************************************************************/
	/****************************************************************************************************/
	-- REF *9988* en wfmCommercialTransactions
	--TENER EN CUENTA QUE SI SE AGREGAN COLUMNAS AL QUERY FINAL DE SP SE DEBERÁ MODIFICAR EL CÓDIGO DE LA
	--PÁGINA EN LA RUTINA grdData_RowDataBound PARA EL CASO EN QUE SEA UNA ROW DEL TIPO Case DataControlRowType.Footer
	--Y MODIFICAR LOS COLUMNS SPANS CORRESPONDIENTES PARA QUE LOS TOTALES DE LA GRILLA COINCIDAN CON EL
	--NUEVO ENCOLUMNAMIENTO
	--TAMBIEN SE DEBRÁN VERIFICAR EN EL CODIGO DE LA PÁGINA EN EL grdData_RowDataBound TODOS LOS ÍNDICES
	--QUE SE VEAN AFECTADOS POR LA MODIFICACIÓN DE LAS COLUMNAS DUMMY PARA LOS BOTONES.

	/****************************************************************************************************/
	/****************************************************************************************************/

	select
			--ct.ct_ATotal ATotal,ct.ct_AAdjust AAdjust,ct.ct_ABalance ABalance,

			/*ISNULL(tit.value,0)*/	1	[1],	-- cells(8)


			--ISNULL(app.value,0)		[2],
			CASE WHEN EXISTS (	SELECT TOP 1 1
									FROM tbApplication ta	WITH (NOLOCK)
									WHERE ta.comp_id = ct.comp_id	AND
										 (ta.ct_transaction_Source = ct.ct_transaction OR
										  ta.ct_transaction_destiny = ct.ct_transaction))
					THEN 1
					ELSE 0
			END						[2],


			ISNULL(tctn.value,0)	[3],
			CASE
				WHEN ct.ct_note <> '' THEN	1
				ELSE						0
			END						[4],			-- Cells(11)
			ISNULL(ret.[count],0)	[5],

			-- --------------------------------------------------------------------------------------
			-- Boton de Anulacion
			-- --------------------------------------------------------------------------------------
			CASE

				WHEN
					-- =====================================================================================================
					-- parte: 746
					(
						@ispurchase = 'True'	AND
						(ct.ct_taxDate  BETWEEN	isnull(bra.bra_PurDoc_MinTaxDate,GETDATE()) AND
													isnull(bra.bra_PurDoc_MaxTaxDate,GETDATE()))
												AND
						(ct.sd_id IN (106, 103, 104))
					)
					AND
					-- =====================================================================================================
					(
						(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
						(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.02)
					)
					THEN 1  --NC, ND de proveedores --habilita la anulación



				WHEN
					-- =====================================================================================================
					-- FACTURA DE COMPRA o DESPACHO DE IMPORTACION 02-2013
					(
						@ispurchase	= 'True'									AND
						(ct.ct_taxDate  BETWEEN	ISNULL(bra.bra_PurDoc_MinTaxDate,GETDATE()-100) AND
												ISNULL(bra.bra_PurDoc_MaxTaxDate,GETDATE()+100))
																				AND
						(ct.sd_id = 101 OR ct.sd_id = 130	)					AND
						(
							(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
							(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.03)
						)														AND
						--NOT EXISTS (SELECT TOP 1 1 FROM tbItemSerials tis WHERE tis.comp_id = ct.comp_id
						--			AND tis.ct_transaction = ct.ct_transaction AND tis.is_available = 'False')
						NOT EXISTS (SELECT TOP 1 1 FROM tbItemSerials tis	WITH (NOLOCK)
									WHERE	tis.comp_id					= ct.comp_id
									AND		tis.ct_transaction			= ct.ct_transaction
									AND		(
												tis.is_available			= 'True'
											or	isnull(tis.is_serial,'')	<> ''
											)
									)
					)
					THEN 4  --FC de proveedores --habilita la anulación
					-- =====================================================================================================


						-- ---------------------------------------------------------------------------------
				WHEN	-- RECIBO DE COBRANZA (Si no esta aplicado y los valores figuran como disponibles)
						-- ---------------------------------------------------------------------------------
			 		 ct.sd_id IN (6,7, 13)
					 THEN
							CASE
								WHEN NOT (
											(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
											(ct.ct_ATotal                           = ct.ct_ABalance) or
											(ABS(ct.ct_ATotal - ct.ct_ABalance) <= 0.8 ) or
											(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.99) -- era 0.01 MOS 06-2017  **wejhfweqjn897
				 						 )																		THEN 190
								WHEN EXISTS(SELECT  TOP 1 1
												FROM tbCheckPortfolio tcp1	WITH (NOLOCK)
			 									WHERE	tcp1.comp_id			= ct.comp_id
			 										AND tcp1.ct_transaction		= ct.ct_transaction
			 										and tcp1.chp_isavailable	= 'False')						THEN 191
																												ELSE 2
							END

					  -- ---------------------------------------------------------------------------------
				WHEN  -- Orden de Pago
					  -- ---------------------------------------------------------------------------------
			 	      ct.sd_id IN (106)
					  THEN --2  --OP a proveedores, --habilita la anulación
							CASE
								WHEN not	(
												(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
												(ct.ct_ATotal                           = ct.ct_ABalance) or
												(ABS(ct.ct_ATotal - ct.ct_ABalance) <= 0.02 ) or
												(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.02)
											)
									 AND         @supp_id4OtherPayments <> ct.supp_id
																												THEN 195
								WHEN @supp_id4OtherPayments = ct.supp_id										THEN 2
																												ELSE 2
							END

				WHEN
					(
			 			 ct.sd_id IN (6,7,13,106) and
			 			 @bra_PaymentSupp_Id = ct.supp_id
					) THEN 2	--Parte:486 --habilita la anulación


				-- =====================================================================================================
				-- Parte: 784
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT TOP 1  1 FROM [tbItemTransactions]	WITH (NOLOCK) WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT TOP 1  1 FROM tbDocumentsFile tdf	WITH (NOLOCK) WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND EXISTS (SELECT TOP 1  1 FROM tbItemTransactions tit2	WITH (NOLOCK) WHERE tit2.comp_id = ct.comp_id
													AND tit2.bra_id = ct.bra_id AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
									 AND ISNULL(ct.ct_isCancelled,'false') = 'false'
					) THEN 3 --RM de clientes que tengan algún registro en tbItemsTransactions y
							 --que el remito tenga asignado un documento de rechazo y
							 --que el remito no tenga algún artículo facturado y
							 --que ya no haya sido anulado anteriormente

				WHEN
					(
						ct.sd_id = 2 AND NOT EXISTS (SELECT TOP 1  1 FROM [tbItemTransactions]	WITH (NOLOCK) WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
					) THEN 94 --RM de clientes NO tiene artículos asignados
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT TOP 1  1 FROM [tbItemTransactions] WITH (NOLOCK) WHERE comp_id = ct.[comp_id]
													AND ct_transaction = ct.[ct_transaction])
									 AND NOT EXISTS (SELECT TOP 1  1 FROM tbDocumentsFile tdf	WITH (NOLOCK)WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
					) THEN 95 --RM de clientes NO tiene asigando un documento de rechazo
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT TOP 1  1 FROM [tbItemTransactions]	WITH (NOLOCK) WHERE comp_id = ct.[comp_id]
													 AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT TOP 1  1 FROM tbDocumentsFile tdf	WITH (NOLOCK)WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND NOT EXISTS (SELECT TOP 1  1 FROM tbItemTransactions tit2 WHERE tit2.comp_id = ct.comp_id
													AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
					) THEN 96 --RM de clientes YA tiene algún artículo facturado
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT TOP 1  1 FROM [tbItemTransactions]	WITH (NOLOCK) WHERE comp_id = ct.[comp_id]
													AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT TOP 1  1 FROM tbDocumentsFile tdf	WITH (NOLOCK) WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND EXISTS (SELECT TOP 1  1 FROM tbItemTransactions tit2	WITH (NOLOCK)	WHERE tit2.comp_id = ct.comp_id
													AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
									 AND ISNULL(ct.ct_isCancelled,'false') = 'true'
					) THEN 93 --RM de clientes YA ha sido anulado anteriormente


				WHEN
					(
						ct.sd_id = 52
					) THEN 92 --No se permiten anular la anulación de Remitos


				WHEN
					(
						ct.sd_id = 102
					) THEN 3 --RM de proveedores
				-- =====================================================================================================


				ELSE	0 --deshabilita la anulación
			END						[6],
			-- --------------------------------------------------------------------------------------


			' '						[7], --Parte 631
			' '						[8], --Parte 631


			ct.comp_id,
			ct.bra_id,
			sd.sd_desc,
			ct.ct_transaction,
			--'(' + dbo.fnStrPADL(	CONVERT(NVARCHAR(20),IsNull(ct.df_id,0)),3,'0')	+ ') ' +
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.[ct_transaction]) 	[doc_number],
			ct.ct_docNumber,
			ct.ct_date,
			ct.ct_taxDate,
			ct.ct_payDate,
			ct.supp_id,
			ct.cust_id,
			ct.cb_id,

			--cb.custb_name,	--REF:#1
			ct.user_id,
			--ct.ct_cd,			--REF:#1

			CASE WHEN sd.sd_isInBalance = 'true' THEN
				convert(decimal(18,2),round(ct.ct_subtotal	,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END		[ct_subtotal],

			CASE WHEN sd.sd_isInBalance = 'true' THEN
				convert(decimal(18,2),round(ct.ct_total - ct.ct_adjust,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END		[ct_total],

			ct.ct_discount,
			ct.ct_taxes,
			ct.curr_id_transaction,
			ct.hacc_transaction,
			ct.disc_id,




	-- ====================================================================================
	-- ATENCIOOOON, NO PONER NADA !!!!!!!!!!!!!!!!!!!!
	-- NO CAMBIAR EL ORDEN DE ESTOS CAMPOS !!!!!!!
	-- **&%$wefbwefwefbwefwef
	-- ====================================================================================




			--  18
			CONVERT(DECIMAL(18,2),
			CASE	WHEN sd.sd_isInBalance = 'true' THEN
															CONVERT (DECIMAL (18,2),ROUND((ct.ct_ATotal - isnull(ct.ct_AAdjust,0)),@d)) *
															CASE
																WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN 0 ELSE 1 END
																ELSE						   CASE WHEN vctfs.sd_isCredit = 'True' THEN 0 ELSE 1 END
															END
					WHEN sd.sd_id IN (44) THEN ct.ct_ATotal * CASE WHEN vctfp.sd_isCredit = 'True' THEN 0 ELSE 1 END
					ELSE 0
			END	)	[ct_ATotal],

			-- 19
			CONVERT(DECIMAL(18,2),
			CASE
				WHEN sd.sd_isInBalance = 'true' THEN
															CONVERT (DECIMAL (18,2),ROUND((ct.ct_ATotal - isnull(ct.ct_AAdjust,0)),@d)) *
															CASE
																WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 0 END
																ELSE						   CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 0 END
															END
					WHEN sd.sd_id IN (43) THEN ct.ct_ATotal *	CASE
																	WHEN vctfp.sd_isCredit = 'True' THEN 0
																	ELSE 1
					                                         	END
					ELSE 0
			END	)	[ct_Credits],

			-- 20

			CASE
				WHEN sd.sd_isInBalance = 'true'		THEN	CONVERT (DECIMAL (18,2),ROUND (ct.ct_ABalance	,@d)) *
					CASE
						WHEN @ispurchase = 'True'	THEN
							CASE
								WHEN vctfp.sd_isCredit = 'True' THEN -1
								ELSE 1
							END
						ELSE
							CASE
								WHEN vctfs.sd_isCredit = 'True' THEN -1
								ELSE 1
							END
					END
				ELSE 0
			END 	[ct_ABalance],


			-- 21 Saldo Acumulado
			CONVERT( decimal(19,2),0) [Balance],

			-- 22
			ct.ct_ACurrency,


			-- 23 Pendiente Cotización Actual (ARS)
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * @current_exchange,@d)) *
						CASE
							WHEN @ispurchase = 'True' THEN
								CASE
									WHEN vctfp.sd_isCredit = 'True' THEN -1
									ELSE 1
								END
							ELSE
								CASE
									WHEN vctfs.sd_isCredit = 'True' THEN -1
									ELSE 1
								END
						END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END [branch_ACurrency],


			-- 24 Pendiente	Cotización	Comprobante	(ARS)
			CASE
				-- MOS 02-2022
				WHEN sd.sd_isInBalance = 'true' AND ct.ct_ACurrency <> 1 AND  ct.curr_id_transaction = 1 THEN round(ct.ct_ABalance * ct.ct_ACurrencyExchange ,@d) * vctfs.PlusOrMinus
				WHEN sd.sd_isInBalance = 'true' THEN
					CONVERT(DECIMAL(18,2),round(ct.ct_ABalance / dbo.fnNoZDiv(ct.ct_ACurrencyExchange),@d)) *				--Referencia: #3
						CASE	-- se puede ser tan HDP cuando solo hay q multiplicar x un puto valor de la puta vista ?
							WHEN @ispurchase = 'True' THEN
								CASE
									WHEN vctfp.sd_isCredit = 'True' THEN -1
									ELSE 1
								END
							ELSE
								CASE
									WHEN vctfs.sd_isCredit = 'True' THEN -1
									ELSE 1
								END
						END
				ELSE  CONVERT(DECIMAL(18,2), 0)
			END [doc_ACurrencyExchange],



			-- 25 Moneda
			ltrim(rtrim(
							CASE
								WHEN ct.sd_id IN (6,7,13) THEN  ISNULL(tc2.curr_symbol,'---')
								ELSE							ISNULL(tc.curr_symbol,'***')
							END
						))
			 		[Currency],



			-- 26 Tipo Cambio
			CONVERT(DECIMAL(19,5),
			CASE
				WHEN ct.ct_ACurrency <> ct.curr_id_transaction	THEN ct.ct_ACurrencyExchange
				ELSE												 ct.ct_curr_IdExchange
			END		)																			[ct_ACurrencyExchange],



			-- 27 TMCD (#) ct_A_Total_dfExchange
			CONVERT(VARCHAR,
			CASE
				WHEN tdf.df_hideFromBalanceMA	= 'True'	THEN 0	--Ref: #2MOS 14-06-2021 FIESA, los FORROS quieren q tambien salga esto en CERO
				WHEN ct.sd_id			IN (43,44)			THEN 0  -- MOS 02-2022
				WHEN sd.sd_isInBalance			= 'true'	THEN
					--CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d))				--Ref: #2
					CONVERT(DECIMAL(18,2),round(

						dbo.fnGetExchange2(@comp_id,ct.ct_ATotal,ct.ct_ACurrency,
						--ct.curr_id4dfExchange,	--Ref: #2MOS 28-05-2021 FIESA
							CASE
								WHEN ct.sd_id IN (6,7,13) THEN  ct.curr_id4Exchange
								ELSE							ct.curr_id4dfExchange
							END,
							CASE
								WHEN ct.sd_id IN (6,7,13) THEN  ct.curr_id4Exchange
								ELSE							ct.curr_id4dfExchange
							END		,
							--ct.curr_id4dfExchange, MOS 28-05-2021 FIESA
							ct.curr_id_transaction,
							CASE
								WHEN ct.sd_id IN (6,7,13) THEN 	ct_curr_IdExchange
								ELSE							ct.ct_dfExchange
							END
							--ct.ct_dfExchange MOS 28-05-2021 FIESA
							,'false')
							,@d))		--Ref: #2

							*

						CASE
							WHEN @ispurchase = 'True' THEN
								CASE
									WHEN vctfp.sd_isCredit = 'True' THEN -1
									ELSE 1
								END
							ELSE
								CASE
									WHEN vctfs.sd_isCredit = 'True' THEN -1
									ELSE 1
								END
						END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END)
				--+ ' (' +
				----ltrim(rtrim(ISNULL(tc.curr_symbol,tc2.curr_symbol)))
				--ltrim(rtrim(
				--				CASE
				--					WHEN ct.sd_id IN (6,7,13) THEN  ISNULL(tc2.curr_symbol,'---')
				--					ELSE							ISNULL(tc.curr_symbol,'***')
				--				END
				--			))
				-- + ')'
					[ct_A_Total_dfExchange],





			-- 28 PMCD (*) [doc_dfExchange]
			CONVERT(VARCHAR,
			CASE
				WHEN ct.sd_id IN (43,44)		THEN 0	-- MOS 02-2022
				WHEN sd.sd_isInBalance = 'true' THEN
					--CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d))				--Ref: #2
					CONVERT(DECIMAL(18,2),round(

						dbo.fnGetExchange2(@comp_id,ct.ct_ABalance,ct.ct_ACurrency,
						--ct.curr_id4dfExchange,	--Ref: #2  MOS 28-05-2021 FIESA
							CASE
								WHEN ct.sd_id IN (6,7,13) THEN  ct.curr_id4Exchange
								ELSE							ct.curr_id4dfExchange
							END,
							CASE
								WHEN ct.sd_id IN (6,7,13) THEN  ct.curr_id4Exchange
								ELSE							ct.curr_id4dfExchange
							END		,
							--ct.curr_id4dfExchange, MOS 28-05-2021 FIESA
							ct.curr_id_transaction,
							CASE
								WHEN ct.sd_id IN (6,7,13) THEN 	ct_curr_IdExchange
								ELSE							ct.ct_dfExchange
							END
							--ct.ct_dfExchange MOS 28-05-2021 FIESA
							,'false')
							,@d))		--Ref: #2

							*

						CASE
							WHEN @ispurchase = 'True' THEN
								CASE
									WHEN vctfp.sd_isCredit = 'True' THEN -1
									ELSE 1
								END
							ELSE
								CASE
									WHEN vctfs.sd_isCredit = 'True' THEN -1
									ELSE 1
								END
						END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END)
				--+ ' (' +
				----ltrim(rtrim(ISNULL(tc.curr_symbol,tc2.curr_symbol)))
				--ltrim(rtrim(
				--				CASE
				--					WHEN ct.sd_id IN (6,7,13) THEN  ISNULL(tc2.curr_symbol,'---')
				--					ELSE							ISNULL(tc.curr_symbol,'***')
				--				END
				--			))
				-- + ')'
					[doc_dfExchange],








			-- 29 Saldo Acumulado (*)
			CONVERT(DECIMAL(19,2),0)  [BalanceMA],    -- MOS FIESA  Balance en USD, 05-2021



	-- ====================================================================================


			ct.df_id,
			ct.dl_id,
			ct.st_id,
			ct.sd_id,
			ct.puco_id,
			ct.sm_id,
			sm.sm_name,
			ISNULL(tst.st_desc,'')  +
							CASE
								WHEN tcclp.comp_id IS NOT NULL THEN ' / ' + ISNULL(tcclp.ccp_desc,'')
								ELSE ''
							END				[st_desc],

			td3.dl_name,

			ct.ct_CompanyCurrency,
			ct.ct_Branch2CompanyCurrencyExchange,
			ct.ct_adjust,
			--ct.ct_aadjust,

			bra.bra_desc + '->' + IsNull(cb.custb_name,'')	+ '/' +
			IsNull(tcf.custf_name,'') + '/' +
			IsNull(tcg.cust_name,'')
															 			[custb_name],	--REF:#1
			ct.ct_cd,		--REF:#1

			dbo.fnSaleOrderHistory_GetUserName(ct.comp_id,ct.ct_soh_bra_id,ct.ct_soh_id) + ' --> ' + us.user_lastname + ', ' + user_firstname  														[user_name],

			tdf.df_desc + ' -> (' +
			CASE
				WHEN ct.ct_soh_id IS NULL	THEN ''
				WHEN ct.ct_soh_id = -1		THEN ''
				ELSE convert(varchar,IsNull(ct.ct_soh_bra_id,0)) + '-' + convert(varchar,IsNull(ct.ct_soh_id,0))
			END
		 		+')'	[soh_id_fromGenerated],

			convert(varchar,ct.ct_transaction) + '-' + convert(varchar,ct.sd_id)							[ID]


	INTO	#tmpData


	FROM 	dbo.tbCommercialTransactions					ct						WITH (NOLOCK)

			--INNER JOIN @tmpBranchs	tmp
			--	ON tmp.bra_id = ct.bra_id

			INNER JOIN @tblSpeedQuery sq
				ON sq.ct_transaction = ct.ct_transaction


			INNER JOIN @tblSysDocuments td2
				ON td2.sd_id = ct.sd_id


			LEFT JOIN vwCommercialTransactions_forSales		vctfs					WITH (NOLOCK)
			ON	vctfs.comp_id			=	ct.comp_id
			AND vctfs.ct_transaction	=	ct.ct_transaction
			AND vctfs.cust_id			=	ct.cust_id
			AND @ispurchase				=	'False'

			LEFT JOIN vwCommercialTransactions_forPurchase	vctfp					WITH (NOLOCK)
			ON	vctfp.comp_id			=	ct.comp_id
			--AND vctfp.bra_id			=	ct.bra_id
			AND vctfp.ct_transaction	=	ct.ct_transaction
			AND vctfp.supp_id			=	ct.supp_id
			AND @ispurchase				=	'True'

			LEFT JOIN dbo.tbBranch							bra						WITH (NOLOCK)
			ON	bra.comp_id				=	ct.comp_id
			AND bra.bra_id				=	ct.bra_id
			AND bra.curr_id				=	@curr_id_branch		--TN : 621

			LEFT JOIN tbCustomerFamily tcf											WITH (NOLOCK)
				ON	tcf.comp_id			= ct.comp_id AND
					tcf.cust_id			= ct.cust_id AND
					tcf.custf_id		= ct.custf_id

			LEFT JOIN tbCustomer tcG												WITH (NOLOCK)
				ON	TCG.comp_id = CT.comp_id AND
					TCG.cust_id = ct.cust_id_guarantor

			LEFT JOIN dbo.tbSalesman						sm						WITH (NOLOCK)
			on	sm.sm_id				=	ct.sm_id
			and	ct.comp_id				=	sm.comp_id

			left join dbo.tbUser							us						WITH (NOLOCK)
			on		us.user_id			=	ct.user_id

			left join dbo.tbCustomerBranch					cb						WITH (NOLOCK)
			on		cb.comp_id			=	ct.comp_id
			and		cb.cust_id			=	ct.cust_id
			and		cb.cb_id			=	ct.cb_id

			left join dbo.tbsysDocuments					sd						WITH (NOLOCK)
			on		sd.sd_id			=	ct.sd_id
			and		sd.sd_isPurchase	=	@ispurchase

			LEFT JOIN dbo.tbSalesTerms						tst						WITH (NOLOCK)
			ON		tst.comp_id			=	ct.comp_id
			AND		tst.st_id			=	ct.st_id

			LEFT JOIN tbCreditCardLoanPlan AS				tcclp					WITH (NOLOCK)
			ON	tcclp.comp_id	= ct.comp_id AND
				tcclp.ccp_id	= ct.ccp_id

			LEFT JOIN #tmpTCTN								tctn					WITH (NOLOCK)
			ON		tctn.comp_id		=	ct.comp_id
			AND		tctn.ct_transaction	=	ct.ct_transaction

			LEFT JOIN #tmpRetentions						ret						WITH (NOLOCK)
			ON		ret.ct_transaction	=	ct.ct_transaction

			LEFT JOIN tbsysCurrency							tc
			ON		tc.curr_id			=	ct.curr_id4dfExchange --ct.curr_id4Exchange


			LEFT JOIN tbsysCurrency							tc2
			ON		tc2.curr_id			=	ct.curr_id4Exchange --ct.curr_id4Exchange

			LEFT JOIN tbDocumentsFile tdf											WITH (NOLOCK)
				ON	tdf.comp_id = ct.comp_id	AND
					tdf.bra_id	= ct.bra_id		AND
					tdf.df_id	= ct.df_id

			LEFT JOIN tbDelivery td3												WITH (NOLOCK)
				ON	td3.comp_id = ct.comp_id AND
					td3.dl_id	= ct.dl_id

			-- =========================================================
			-- TN : 621
			--INNER JOIN vwUsers4BranchFilter				vubf
			--ON	vubf.comp_id		=	ct.comp_id
			--AND vubf.bra_id			=	bra.bra_id
			--AND vubf.[user_id]		=	@user_id
			-- =========================================================


	where	ct.comp_id			=	@comp_id
	--and		ct.bra_id			=	@bra_id		--TN : 621
	--and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or **88
	--		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))


	--si se seleccionan sólo facturas trae sólo las que tienen ítems cargados
	and     (
			 (@sd_id	= -1)

			 OR

			 (@sd_id	= 1			AND EXISTS		(	SELECT TOP 1  1
															FROM [tbItemTransactions]	WITH (NOLOCK)
															WHERE	comp_id			= ct.[comp_id]
																--AND bra_id			= ct.[bra_id]
																AND ct_transaction	= ct.[ct_transaction])
			 )

			 OR

			 (@sd_id	= -2		AND   td2.sd_isInBalance='True' --   ct.sd_id IN (SELECT sd_id FROM tbsysDocuments td WHERE td.sd_isInBalance = 'true')
			 )

			 OR

			 (@sd_id	= 2			AND ct.sd_id IN (2,52))

			 OR

			 (ct.sd_id	= @sd_id	AND @sd_id > 1)
			)

	and		ct.ct_docNumber			<> ''
	AND		ct.sd_id				<>	301
	--AND		(@bra_id_user			= -1 OR ct.bra_id = @bra_id_user)


--	order by ct.ct_date, ct.ct_transaction   No hace falta, se hace un Inner Join abajo y se vuelkve a ordenar.  hace que tarde mucho





	-- ------------------------------------------
	-- Recalculo del saldo acumulado ct_dfExchange
	-- ------------------------------------------
	DECLARE @decBalance AS DECIMAL(19,4)
	SET		@decBalance = 0;

	DECLARE @decBalanceMA AS DECIMAL(19,4)
	SET		@decBalanceMA = 0;


	DECLARE @tblTmp AS TABLE(	ct_date			datetime,
								ct_transaction	int,
								ct_ATotal		DECIMAL(19,6),
								ct_Credits		DECIMAL(19,6),
								ct_AAdjust		DECIMAL(19,6),
								balance			DECIMAL(19,6),
								sd_id			INT,
								balanceMA		DECIMAL(19,2),-- FIESA  05-2021  11891
								ct_dfExchange	DECIMAL(35,15),-- FIESA  05-2021  11891
								df_hideFromBalanceMA BIT,
								curr_id_Customer	 INT,
								curr_id_transaction  INT
							)

	INSERT INTO  @tblTmp (ct_date,ct_transaction,ct_ATotal,ct_Credits,ct_AAdjust,balance,sd_id,balanceMA,ct_dfExchange,df_hideFromBalanceMA,
						  curr_id_Customer,
						  curr_id_transaction)
		SELECT				tmp.ct_date,
							tmp.ct_transaction,
							tmp.ct_ATotal ,
							tmp.ct_Credits ,
							IsNull(tct.ct_AAdjust,0) ,
							balance,
							tct.sd_id,
							balance / dbo.fnNoZDiv(	-- FIESA  05-2021  11891
													CASE
														WHEN tct.sd_id IN (6,7,13) THEN	ct_curr_IdExchange
														ELSE							tct.ct_dfExchange
													END
												   ),
							dbo.fnNoZDiv(			CASE -- FIESA  05-2021  11891
														WHEN tct.sd_id IN (6,7,13) THEN	ct_curr_IdExchange
														ELSE							tct.ct_dfExchange
													END
										),
							ISNULL(tdf.df_hideFromBalanceMA,'False'),
							tct.ct_ACurrency,
							tct.curr_id_transaction
						FROM #tmpData tmp	WITH (NOLOCK)
						INNER JOIN tbCommercialTransactions		tct	WITH (NOLOCK)
							ON tct.ct_transaction = tmp.ct_transaction
						LEFT JOIN tbDocumentsFile			AS	tdf	WITH (NOLOCK)
							ON	tdf.comp_id = tct.comp_id	AND
								tdf.bra_id	= tct.bra_id	AND
								tdf.df_id	= tct.df_id
						ORDER BY tmp.ct_date, tmp.ct_transaction








		-- ----------------------------------------------------------------
		-- Hay que ordenar de esta manera la actualizacion de la tabla temporal ya que al parecer en versiones nuevas de sql no quedan ordenadas de la misma manera en que fueron creadas...
		-- ----------------------------------------------------------------

		-- MOS 01-2023: x las dudas no lo toco pero está actualizando un CTE que se evapora luego del update.   me parece que deberia ser: @tblTmp
		;with tblTmpAux as
					(
						select top 10000000000 *
							from @tblTmp tmp
								ORDER BY tmp.ct_date, tmp.ct_transaction
					)

		UPDATE tblTmpAux
				SET @decBalance = (@decBalance +
					CASE
						WHEN sd_id IN (43,44)				THEN 0	-- MOS 02-2022
						WHEN sd_id > 100  and sd_id < 150	THEN (ct_ATotal + ct_Credits  /*-IsNull(ct_AAdjust,0)*/ )
						WHEN sd_id < 100  and sd_id < 50	THEN (ct_ATotal + ct_Credits  /*-IsNull(ct_AAdjust,0)*/ )
						ELSE 0
					END
								   ),
					Balance = Balance + @decBalance,
					-- Para FIESA, columna de Balance en USD  -- FIESA  05-2021  11891
					@decBalanceMA = (@decBalanceMA +
					CASE
						WHEN sd_id IN (43,44)				THEN 0	-- MOS 02-2022
						WHEN df_hideFromBalanceMA = 'True'	THEN 0
						-- MOS 02-2022: Si es una Cuenta Corriente en DOLARES q no divida.
						WHEN sd_id > 100  and sd_id < 150 AND curr_id_Customer <>  curr_id_transaction 	THEN (ct_ATotal + ct_Credits) --
						WHEN sd_id < 100  and sd_id < 50  AND curr_id_Customer <>  curr_id_transaction 	THEN (ct_ATotal + ct_Credits) --/ ct_dfExchange
						-- MOS 02-2022: Si es una Cuenta Corriente en DOLARES q no divida.
						WHEN sd_id > 100  and sd_id < 150	THEN (ct_ATotal + ct_Credits) / ct_dfExchange
						WHEN sd_id < 100  and sd_id < 50	THEN (ct_ATotal + ct_Credits) / ct_dfExchange
						ELSE 0
					END
								   ),
					BalanceMA = BalanceMA + @decBalanceMA
		-- ----------------------------------------------------------------





--==
--select * from @tblTmp
--==

		UPDATE #tmpData
			SET Balance = tmp1.balance
		FROM #tmpData	tmp
		INNER JOIN @tblTmp tmp1
			ON tmp1.ct_transaction = tmp.ct_transaction

		-- FIESA, Balance en USD  05-2021 -- FIESA  05-2021  11891
		UPDATE #tmpData
			SET BalanceMA = tmp1.balanceMA
		FROM #tmpData	tmp
		INNER JOIN @tblTmp tmp1
			ON tmp1.ct_transaction = tmp.ct_transaction



	SELECT *
		FROM #tmpData ct	WITH (NOLOCK)
		WHERE 	ct.ct_date			between		@datefrom		and		@dateto
					AND
				ct.ct_payDate		between		@paydatefrom	and		@paydateto
		ORDER BY ct.ct_date, ct.ct_transaction

	/****************************************************************************************************/






	SELECT 	isnull(sum([ct_ATotal]			),0)		[ct_ATotal],
			isnull(sum([ct_ABalance]		),0)		[ct_ABalance],
			@current_exchange							[current_exchange],
			--0											[BalanceMA],
			isnull(sum([branch_ACurrency]	),0)		[branch_ACurrency],
			isnull(sum([ct_Credits]			),0)		[ct_Credits]
	FROM	#tmpData		WITH (NOLOCK)

			INNER JOIN tbsysDocuments td		WITH (NOLOCK)
			ON	td.sd_id			= #tmpData.sd_id
			AND td.sd_isInBalance	= 'True'

	TRUNCATE TABLE #tmpData -- JAVIER
	--DELETE FROM #tmpData
	DROP TABLE #tmpData






	-- -------------------------------------------------------------------------------------
	-- MOS: Trae el Estado de Credito del Cliente y lo
	-- devuelve en una nueva tabla con los siguientes campos
	-- -------------------------------------------------------------------------------------
	--	cust_credit_max							Credito Maximo
	--	cust_credit_own							Credito Maximo en Valores Propios
	--	cust_credit_cheque_own_used				Cheques Propios
	--	cust_credit_cheque_3rd_used				Cheques de Terceros
	--	cust_credit_SaleOrder					Pedidos Pendientes
	--	cust_credit_balance						Saldo de Cta Corriente
	--	cust_credit_balance_OverCome			Saldo Vencido de Cuenta Corriente
	--	cust_credit_balance_NotOverCome			Saldo NO VENCIDO de Cuenta Corriente
	IF @ispurchase = 'False'
		BEGIN
			DECLARE	@branch_curr_id INT, @branch_processingdata DATETIME

			SELECT	@branch_curr_id			= tb.curr_id,
					@branch_processingdata	= tb.bra_processingDate
			FROM	tbBranch tb
			WHERE	tb.comp_id				= @comp_id
			AND		tb.bra_id				= @bra_id

			SELECT * From dbo.fnCustomer_getBalanceStatus(@comp_id,@branch_curr_id,@selection_id,@user_id,@branch_processingdata,-1,-1)
		END
	-- -------------------------------------------------------------------------------------



END
GO









-- --------------------------------------------------------------------------------------------------------------------------------------
-- --------------------------------------------------------------------------------------------------------------------------------------
-- COPIA EXACTA DE SP [spCommercialTransactions_getDataByFilters] SIN LOS 2 ULTIMOS RESULTSETS
-- SE UTILIZA PARA EL CHEQUEO DE LOS SALDOS DE LAS APLICACIONES DE CUENTAS CORRIENTES spCommercialTransactions_CheckBalance-
--  y para sysGenericCustomExports
-- --------------------------------------------------------------------------------------------------------------------------------------
-- --------------------------------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[spCommercialTransactions_getDataByFilters_CustomExport]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@selection_id		INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@paydatefrom		DATETIME,
	@paydateto			DATETIME,
	@sd_id				INT,
	@ispurchase			BIT,
	@user_id			INT
)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	/********************************************************************************************************
	si @ispurchase es True significa que la consulta está relacionada a una compra por lo tanto
	se debe considerar el @selection_id como proveedor o sea supp_id, si @ispurchase es False
	significa que la consulta está relacionada a una venta, en éste caso se debe considerar el
	@selection_id como cliente o sea cust_id
	*********************************************************************************************************/


	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2010-08-18
	-- Parte		: 486
	-- Description	: En la columna [6] que es donde se envía la marca que indica si se puede o no anular el comprobante,
	--				  se habilita la anulación para el caso en que es un pago de 'Otros Pagos' que se reconoce si el
	--				  proveedor es el que está informado en la sucursal como proveedor de otros pagos.
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2010-09-30
	-- Parte		: sin parte Referencia: #1
	-- Description	: Se agregan las comunas [doc_ACurrencyExchange] informa el importe pendiente en la moneda del
	-- cliente/proveedor con la cotización del momento de generación del comprobante y [doc_dfExchange] informa el
	-- importe pendiente en la moneda del comprobante en la cotización del momento de la generación del comprobante
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2010-10-18
	-- Parte		: sin parte Referencia: #2
	-- Description	: Se modifica la fórmula para el cálculo del campo [doc_dfExchange] de:
	-- CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d)) a:
	-- dbo.fnGetExchange2(@comp_id,ct.ct_ABalance,ct.ct_ACurrency,ct.curr_id4dfExchange,
	--							ct.curr_id_transaction,ct.curr_id4dfExchange,ct.ct_dfExchange,'false')
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-01-03
	-- Parte		: 746
	-- Description	: Control que permite anular compras a proveedores u órdenes de pago qué solo estén dentro del rango
	--				  de fechas de los campos bra_PurDoc_MinTaxDate y bra_PurDoc_MaxTaxDate de la tabla tbBranch
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-01-18
	-- Parte		: 784
	-- Description	: Se habilita la opción de anular remitos de proveedores siempre que tengan artículos cargados
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-01-18
	-- Parte		: 771
	-- Description	: Se habilita la opción de anular facturas de proveedores si no tiene items con serialización tomada
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-02-03
	-- Parte		: 784
	-- Description	: Se habilita la opción de anular remitos de clientes siempre que tengan artículos cargados y
	--				  que el remito tenga asignado un documento de rechazo y que el remito no tenga algún artículo
	--				  facturado y que ya no haya sido anulado anteriormente
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-03-28
	-- Parte		: S/N -  Referencia: #3
	-- Description	: Se cambia el cálculo de la columna [doc_ACurrencyExchange]
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-04-11
	-- Parte		: S/N -  Referencia: #4
	-- Description	: Se agrega una condición para mostrar en el campo [ct_ACurrencyExchange]
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-04-11
	-- Parte		: S/N -  Referencia: #5
	-- Description	: Se agrega un nuevo campo [ct_ATotal_dfExchange] a la consulta general
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2011-05-26
	-- TN			: 621
	-- Description	: se modifica el filtro por sucursal recibida por parámetro por un filtro a través de la vista
	--
	-- =================================================================================================================



-- -----------------------------------------------------------
-- Testing
-- -----------------------------------------------------------
/*
	declare 	@comp_id			int,
				@lang_id			int,
				@bra_id				int,
				@selection_id		int,
				@datefrom			datetime,
				@dateto				datetime,
				@paydatefrom		datetime,
				@paydateto			datetime,
				@sd_id				int,
				@ispurchase			bit,
				@user_id			int
	select		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@selection_id		= 24294,
				@datefrom			= convert(datetime,'2000-01-01'),
				@dateto				= convert(datetime,'9999-12-31'),
				@paydatefrom		= convert(datetime,'2000-01-01'),
				@paydateto			= convert(datetime,'9999-12-31'),
				@sd_id				= -2,
				@ispurchase			= 'false',
				@user_id			= 1

	DROP TABLE #tmpIT
	DROP TABLE #tmpAPP
	DROP TABLE #tmpTCTN
	DROP TABLE #tmpRetentions
	DROP TABLE #tmpData

	----DROP TABLE #tmpAdd
	----DROP TABLE #tmpSustract
	----DROP TABLE #tmpRetentions2
*/
-- -----------------------------------------------------------


	-- Fantastica idea de poner en este nombre de variable la cantidad de decimales a redondear.
	-- Quien se IMAGINA que quiere decir @d?
	declare @d int
	set		@d = 2






	/****************************************************************************************************/
	/*recuperar el cambio actual entre la moneda de la sucursal con respesto a la del cliente/proveedor */
	DECLARE	@current_exchange			DECIMAL(18,6),
			@curr_id_branch				INT,
			@curr_id_2					INT,
			@bra_PaymentSupp_Id			INT					--Parte:486


	SELECT TOP 1	@curr_id_branch		= tb.curr_id,
			@bra_PaymentSupp_Id	= ISNULL(tb.bra_PaymentSupp_Id,-1)		--Parte:486
	FROM	tbBranch	tb
	WHERE	tb.comp_id	= @comp_id
	--AND		tb.bra_id	= @bra_id



	IF @ispurchase = 'false'
		SELECT	@curr_id_2 =tc.curr_id
		FROM	tbCustomer tc
		WHERE	tc.comp_id = @comp_id AND tc.cust_id = @selection_id
	ELSE
		SELECT	@curr_id_2 = tc.curr_id
		FROM	tbSupplier tc
		WHERE	tc.comp_id = @comp_id AND tc.supp_id = @selection_id



	SELECT	@current_exchange = dbo.fnGetExchange(@comp_id, 1, @curr_id_2, @curr_id_branch, 0, 0, 'False')
	/****************************************************************************************************/
	--SELECT @curr_id_branch, @curr_id_2
	--SELECT * FROM tbsysCurrency tc




	/****************************************************************************************************/
	/* Agregamos horas para que tome el dia completo a las fechas hasta *********************************/
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,1)
	set	@paydateto	= dbo.fnGetEnd_or_BeginOfDate(@paydateto,1)
	--select @dateto, @paydateto
	/****************************************************************************************************/





	/****************************************************************************************************/
	/* Generacion de temporal para determinar si cada CommercialTransaction tiene items *****************/
	SELECT	DISTINCT	tit.comp_id,	tit.bra_id,		tit.ct_transaction,		1	[value]
	INTO	#tmpIT
	FROM	dbo.tbItemTransactions						tit
			INNER JOIN dbo.tbCommercialTransactions		ct
			ON	ct.comp_id			=	tit.comp_id
			AND ct.bra_id			=	tit.bra_id
			AND ct.ct_transaction	=	tit.ct_transaction

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	tit.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	tit.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	tit.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	tit.comp_id						=	@comp_id
	--AND		(@bra_id  = -1 or tit.bra_id	=	@bra_id)
	AND 	((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301


	UNION

	SELECT 	DISTINCT	vct.comp_id,	vct.bra_id,		vct.ct_transaction,		1	[value]
	FROM 	vwCollection								vct
			inner join dbo.[tbCommercialTransactions]	ct
			on	ct.[comp_id]		=	vct.comp_id
			and ct.[bra_id]			=	vct.bra_id
			and ct.[ct_transaction] =	vct.ct_transaction

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	vct.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	vct.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	vct.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	vct.comp_id				=	@comp_id
		--AND		(@bra_id  = -1 or vct.bra_id	=	@bra_id)
	AND 	((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301


	UNION


	SELECT	DISTINCT	tpcm.comp_id,	tpcm.bra_id,	tpcm.ct_transaction,	1 [value]
	FROM	tbPurchaseConceptMovements					tpcm
			INNER JOIN tbCommercialTransactions			tct
			ON	tct.comp_id			=	tpcm.comp_id
			AND tct.bra_id			=	tpcm.bra_id
			AND tct.ct_transaction	=	tpcm.ct_transaction

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	tpcm.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	tpcm.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	tpcm.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	tpcm.comp_id			=	@comp_id
	--AND		(@bra_id = -1 or tpcm.bra_id	=	@bra_id)
	AND 	((@ispurchase = 'True'	AND (@selection_id = -1 or tct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	AND (@selection_id = -1 or tct.cust_id = @selection_id)))

	--SELECT * FROM #tmpIT
	/****************************************************************************************************/






	/****************************************************************************************************/
	/****************************************************************************************************/
	SELECT	DISTINCT
			ta.comp_id,
			ta.bra_id,
			ta.ct_transaction_Source	[ct_transaction],
			1							[value]
	INTO	#tmpAPP
	FROM	dbo.tbApplication							ta
			INNER JOIN dbo.tbCommercialTransactions		ct
			ON	ct.comp_id			=	ta.comp_id
			AND ct.bra_id			=	ta.bra_id
			AND ct.ct_transaction	=	ta.ct_transaction_Source

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	ta.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	ta.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	ta.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	ta.comp_id				=	@comp_id
	--AND	ta.bra_id				=	@bra_id		TN : 621
	and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301


	UNION


	SELECT	DISTINCT
			ta.comp_id,
			ta.bra_id,
			ta.ct_transaction_destiny [ct_transaction],
			1 [value]
	FROM	dbo.tbApplication							ta
			INNER JOIN dbo.tbCommercialTransactions		ct
			ON	ct.comp_id			=	ta.comp_id
			AND ct.bra_id			=	ta.bra_id
			AND ct.ct_transaction	=	ta.ct_transaction_destiny

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	ta.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	ta.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	ta.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	ta.comp_id				=	@comp_id
	--AND	ta.bra_id				=	@bra_id		--TN : 621
	AND 	((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301

	--SELECT * FROM #tmpAPP
	/****************************************************************************************************/







	/****************************************************************************************************/
	/****************************************************************************************************/
	SELECT	DISTINCT
			tctn.comp_id,
			tctn.bra_id,
			tctn.ct_transaction,
			1 [value]
	INTO	#tmpTCTN
	FROM	dbo.tbCommercialTransactionNotes			tctn
			INNER JOIN dbo.tbCommercialTransactions		ct
			ON	ct.comp_id			= tctn.comp_id
			AND ct.bra_id			= tctn.bra_id
			AND ct.ct_transaction	= tctn.ct_transaction

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	tctn.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	tctn.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	tctn.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	tctn.comp_id			=	@comp_id
	--AND	tctn.bra_id				=	@bra_id		--TN : 621
	AND		(len(rtrim(ltrim(tctn.ctn_note1))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note2))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note3))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note4))) > 0)
	and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301

	--SELECT * FROM #tmpTCTN
	/****************************************************************************************************/







	/****************************************************************************************************/
	/* Genracion de temporal para determinar retenciones para cada CT ***********************************/
	SELECT	COUNT(*) [count],
			ttm.ct_transaction
	INTO	#tmpRetentions
	FROM	tbTaxMovements								ttm
			INNER JOIN tbTaxName						ttn
			ON	ttn.comp_id			= ttm.comp_id
			AND ttn.tax_id			= ttm.tax_id
			INNER JOIN vwsysTaxClassALL_Retentions		vtcar
			ON	vtcar.tax_class		= ttn.tax_class

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	ttm.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	ttm.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	ttm.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	ttm.comp_id				= @comp_id
	--AND	ttm.bra_id				= @bra_id	--TN : 621
	AND		ttm.tm_total			> 0
	GROUP BY ttm.ct_transaction

	--SELECT * FROM #tmpRetentions ORDER BY 2
	/****************************************************************************************************/







	/****************************************************************************************************/
	/****************************************************************************************************/

	--TENER EN CUENTA QUE SI SE AGREGAN COLUMNAS AL QUERY FINAL DE SP SE DEBERÁ MODIFICAR EL CÓDIGO DE LA
	--PÁGINA EN LA RUTINA grdData_RowDataBound PARA EL CASO EN QUE SEA UNA ROW DEL TIPO Case DataControlRowType.Footer
	--Y MODIFICAR LOS COLUMNS SPANS CORRESPONDIENTES PARA QUE LOS TOTALES DE LA GRILLA COINCIDAN CON EL
	--NUEVO ENCOLUMNAMIENTO
	--TAMBIEN SE DEBRÁN VERIFICAR EN EL CODIGO DE LA PÁGINA EN EL grdData_RowDataBound TODOS LOS ÍNDICES
	--QUE SE VEAN AFECTADOS POR LA MODIFICACIÓN DE LAS COLUMNAS DUMMY PARA LOS BOTONES.

	/****************************************************************************************************/
	/****************************************************************************************************/

	select
			--ct.ct_ATotal ATotal,ct.ct_AAdjust AAdjust,ct.ct_ABalance ABalance,

			ISNULL(tit.value,0)		[1],
			ISNULL(app.value,0)		[2],
			ISNULL(tctn.value,0)	[3],
			' '						[4],
			ISNULL(ret.[count],0)	[5],

			CASE

				WHEN
					-- =====================================================================================================
					-- parte: 746
					(
						@ispurchase = 'True'	AND
						(ct.ct_taxDate  BETWEEN	isnull(bra.bra_PurDoc_MinTaxDate,GETDATE()) AND
													isnull(bra.bra_PurDoc_MaxTaxDate,GETDATE()))
												AND
						(ct.sd_id IN (106, 103, 104))
					)
					AND
					-- =====================================================================================================
					(
						(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
						(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
					)
					THEN 1  --NC, ND de proveedores --habilita la anulación



				WHEN
					-- =====================================================================================================
					-- parte: 771
					(
						@ispurchase	= 'True'									AND
						(ct.ct_taxDate  BETWEEN	ISNULL(bra.bra_PurDoc_MinTaxDate,GETDATE()) AND
												ISNULL(bra.bra_PurDoc_MaxTaxDate,GETDATE()))
																				AND
						ct.sd_id	= 101										AND
						(
							(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
							(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
						)														AND
						--NOT EXISTS (SELECT TOP 1 1 FROM tbItemSerials tis WHERE tis.comp_id = ct.comp_id
						--			AND tis.ct_transaction = ct.ct_transaction AND tis.is_available = 'False')
						NOT EXISTS (SELECT TOP 1 1 FROM tbItemSerials tis
									WHERE	tis.comp_id					= ct.comp_id
									AND		tis.ct_transaction			= ct.ct_transaction
									AND		(
												tis.is_available			= 'True'
											or	isnull(tis.is_serial,'')	<> ''
											)
									)
					)
					THEN 4  --FC de proveedores --habilita la anulación
					-- =====================================================================================================



				WHEN
					(
			 			ct.sd_id IN (6, 13)
			 			AND
			 			(
							(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
							(ct.ct_ATotal                           = ct.ct_ABalance) or
							(ABS(ct.ct_ATotal - ct.ct_ABalance) <= 0.01 ) or
							(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
			 			)
			 			AND
			 			NOT EXISTS (SELECT 1 FROM tbCheckPortfolio tcp1
			 			            WHERE tcp1.comp_id = ct.comp_id
			 			            AND tcp1.ct_transaction = ct.ct_transaction)

					) THEN 2  --RC de clientes --habilita la anulación


				WHEN
					(
			 			ct.sd_id IN (106)
			 			AND
			 			(
							(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
							(ct.ct_ATotal                           = ct.ct_ABalance) or
							(ABS(ct.ct_ATotal - ct.ct_ABalance) <= 0.01 ) or
							(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
						)

					) THEN 2  --OP a proveedores, --habilita la anulación


				WHEN
					(
			 			 ct.sd_id IN (6,13,106) and
			 			 @bra_PaymentSupp_Id = ct.supp_id
					) THEN 2	--Parte:486 --habilita la anulación


				-- =====================================================================================================
				-- Parte: 784
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND EXISTS (SELECT 1 FROM tbItemTransactions tit2 WHERE tit2.comp_id = ct.comp_id
													AND tit2.bra_id = ct.bra_id AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
									 AND ISNULL(ct.ct_isCancelled,'false') = 'false'
					) THEN 3 --RM de clientes que tengan algún registro en tbItemsTransactions y
							 --que el remito tenga asignado un documento de rechazo y
							 --que el remito no tenga algún artículo facturado y
							 --que ya no haya sido anulado anteriormente

				WHEN
					(
						ct.sd_id = 2 AND NOT EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
					) THEN 94 --RM de clientes NO tiene artículos asignados
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
									 AND NOT EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
					) THEN 95 --RM de clientes NO tiene asigando un documento de rechazo
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND NOT EXISTS (SELECT 1 FROM tbItemTransactions tit2 WHERE tit2.comp_id = ct.comp_id
													AND tit2.bra_id = ct.bra_id AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
					) THEN 96 --RM de clientes YA tiene algún artículo facturado
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND EXISTS (SELECT 1 FROM tbItemTransactions tit2 WHERE tit2.comp_id = ct.comp_id
													AND tit2.bra_id = ct.bra_id AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
									 AND ISNULL(ct.ct_isCancelled,'false') = 'true'
					) THEN 93 --RM de clientes YA ha sido anulado anteriormente


				WHEN
					(
						ct.sd_id = 52
					) THEN 92 --No se permiten anular la anulación de Remitos


				WHEN
					(
						ct.sd_id = 102
					) THEN 3 --RM de proveedores
				-- =====================================================================================================


				ELSE	0 --deshabilita la anulación
			END						[6],

			' '						[7], --Parte 631
			' '						[8], --Parte 631


			ct.comp_id,
			ct.bra_id,
			sd.sd_desc,
			ct.ct_transaction,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.[ct_transaction])		[doc_number],
			ct.ct_docNumber,
			ct.ct_date,
			ct.ct_taxDate,
			ct.ct_payDate,
			ct.supp_id,
			ct.cust_id,
			ct.cb_id,

			--cb.custb_name,	--REF:#1
			ct.user_id,
			--ct.ct_cd,			--REF:#1

			CASE WHEN sd.sd_isInBalance = 'true' THEN
				convert(decimal(18,2),round(ct.ct_subtotal	,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END		[ct_subtotal],

			CASE WHEN sd.sd_isInBalance = 'true' THEN
				convert(decimal(18,2),round(ct.ct_total - ct.ct_adjust,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END		[ct_total],

			ct.ct_discount,
			ct.ct_taxes,
			ct.curr_id_transaction,
			ct.hacc_transaction,
			ct.disc_id,

-- -------------------------------------------------------
-- Se modifico para que sirva ex Exportacion Personalizada
-- -------------------------------------------------------

			-- 19
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					CONVERT (DECIMAL (18,2),ROUND((ct.ct_ATotal - isnull(ct.ct_AAdjust,0)),@d)) *
					CASE
						WHEN @ispurchase = 'True' THEN	CASE
															WHEN vctfp.sd_isCredit = 'True' AND vctfs.sd_id		IN (106) THEN 0
															WHEN vctfp.sd_isCredit = 'True' AND vctfs.sd_id	not	IN (106) THEN -1
															ELSE 1
														END
						ELSE							CASE
															WHEN vctfs.sd_isCredit = 'True' AND vctfs.sd_id     IN (6,13) THEN 0
															WHEN vctfs.sd_isCredit = 'True' AND vctfs.sd_id not IN (6,13) THEN -1
															ELSE 1
														END
					END
				 ELSE 0
			END		[ct_ATotal],		-- Debitos

			-- 20
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					CONVERT (DECIMAL (18,2),ROUND((ct.ct_ATotal - isnull(ct.ct_AAdjust,0)),@d)) *
					CASE
						WHEN @ispurchase = 'True' THEN
														CASE
															WHEN vctfp.sd_isCredit = 'True' AND vctfs.sd_id		IN (106) THEN -1
															WHEN vctfp.sd_isCredit = 'True' AND vctfs.sd_id	not	IN (106) THEN 0
															ELSE 0
														END
						ELSE							CASE
															WHEN vctfs.sd_isCredit = 'True'  AND vctfs.sd_id		IN (6,13) THEN -1
															WHEN vctfs.sd_isCredit = 'True'  AND vctfs.sd_id not	IN (6,13) THEN 0
															ELSE 0
														END
					END
				 ELSE 0
			END		[ct_Credits],		-- Solo Recibos

-- -------------------------------------------------------

			-- 21
			CASE WHEN sd.sd_isInBalance = 'true' THEN
				CONVERT (DECIMAL (18,2),ROUND (ct.ct_ABalance	,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END 	[ct_ABalance],
			CONVERT( decimal(19,2),0) [Balance],


			ct.ct_ACurrency,


			--=================================================================================================================
			-- Ref: #4
			CASE WHEN ct.ct_ACurrency <> ct.curr_id_transaction
					THEN ct.ct_ACurrencyExchange
					ELSE ct.ct_curr_IdExchange
				END	[ct_ACurrencyExchange],
			--=================================================================================================================


			CASE WHEN sd.sd_isInBalance = 'true' THEN
					CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * @current_exchange,@d)) *
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END [branch_ACurrency],



			--=================================================================================================================
			-- Referencia: #1
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					CONVERT(DECIMAL(18,2),round(ct.ct_ABalance / dbo.fnNoZDiv(ct.ct_ACurrencyExchange),@d)) *				--Referencia: #3
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END [doc_ACurrencyExchange],


			CONVERT(VARCHAR,
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					--CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d))				--Ref: #2
					CONVERT(DECIMAL(18,2),round(
						dbo.fnGetExchange2(@comp_id,ct.ct_ABalance,ct.ct_ACurrency,ct.curr_id4dfExchange,	--Ref: #2
							ct.curr_id4dfExchange,ct.curr_id_transaction,ct.ct_dfExchange,'false'),@d))		--Ref: #2
					*
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END)
			+ ' (' + ltrim(rtrim(tc.curr_symbol)) + ')'
					[doc_dfExchange],
			--=================================================================================================================



			--=================================================================================================================
			-- Referencia: #5
			CONVERT(VARCHAR,
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					--CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d))				--Ref: #2
					CONVERT(DECIMAL(18,2),round(
						dbo.fnGetExchange2(@comp_id,ct.ct_ATotal,ct.ct_ACurrency,ct.curr_id4dfExchange,	--Ref: #2
							ct.curr_id4dfExchange,ct.curr_id_transaction,ct.ct_dfExchange,'false'),@d))		--Ref: #2
					*
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END)
			+ ' (' + ltrim(rtrim(tc.curr_symbol)) + ')'
					[ct_A_Total_dfExchange],
			--=================================================================================================================



			ct.df_id,
			ct.dl_id,
			ct.st_id,
			ct.sd_id,
			ct.puco_id,
			ct.sm_id,
			sm.sm_name,
			tst.st_desc,

			ct.ct_CompanyCurrency,
			ct.ct_Branch2CompanyCurrencyExchange,
			ct.ct_adjust,
			--ct.ct_aadjust,

			cb.custb_name,	--REF:#1
			ct.ct_cd,		--REF:#1

			us.user_lastname + ', ' + user_firstname														[user_name],
			convert(varchar,IsNull(ct.ct_soh_bra_id,0)) + '-' + convert(varchar,IsNull(ct.ct_soh_id,0))		[soh_id_fromGenerated],
			convert(varchar,ct.ct_transaction) + '-' + convert(varchar,ct.sd_id)							[ID]


	INTO	#tmpData


	FROM 	dbo.tbCommercialTransactions					ct

			LEFT JOIN vwCommercialTransactions_forSales		vctfs
			ON	vctfs.comp_id			=	ct.comp_id
			AND vctfs.bra_id			=	ct.bra_id
			AND vctfs.ct_transaction	=	ct.ct_transaction
			AND vctfs.cust_id			=	ct.cust_id
			AND @ispurchase				=	'False'

			LEFT JOIN vwCommercialTransactions_forPurchase	vctfp
			ON	vctfp.comp_id			=	ct.comp_id
			AND vctfp.bra_id			=	ct.bra_id
			AND vctfp.ct_transaction	=	ct.ct_transaction
			AND vctfp.supp_id			=	ct.supp_id
			AND @ispurchase				=	'True'

			LEFT JOIN dbo.tbBranch							bra
			ON	bra.comp_id				=	ct.comp_id
			AND bra.bra_id				=	ct.bra_id
			AND bra.curr_id				=	@curr_id_branch		--TN : 621

			LEFT JOIN dbo.tbSalesman						sm
			on	sm.sm_id				=	ct.sm_id
			and	ct.comp_id				=	sm.comp_id

			left join dbo.tbUser							us
			on		us.user_id			=	ct.user_id

			left join dbo.tbCustomerBranch					cb
			on		cb.comp_id			=	ct.comp_id
			and		cb.cust_id			=	ct.cust_id
			and		cb.cb_id			=	ct.cb_id

			left join dbo.tbsysDocuments					sd
			on		sd.sd_id			=	ct.sd_id
			and		sd.sd_isPurchase	=	@ispurchase

			LEFT JOIN dbo.tbSalesTerms						tst
			ON		tst.comp_id			=	ct.comp_id
			AND		tst.st_id			=	ct.st_id

			LEFT JOIN #tmpIT								tit
			ON		tit.comp_id			=	ct.comp_id
			AND		tit.bra_id			=	ct.bra_id
			AND		tit.ct_transaction	=	ct.ct_transaction

			LEFT JOIN #tmpAPP								app
			ON		app.comp_id			=	ct.comp_id
			AND		app.bra_id			=	ct.bra_id
			AND		app.ct_transaction	=	ct.ct_transaction

			LEFT JOIN #tmpTCTN								tctn
			ON		tctn.comp_id		=	ct.comp_id
			AND		tctn.bra_id			=	ct.bra_id
			AND		tctn.ct_transaction	=	ct.ct_transaction

			LEFT JOIN #tmpRetentions						ret
			ON		ret.ct_transaction	=	ct.ct_transaction

			LEFT JOIN tbsysCurrency							tc
			ON		tc.curr_id			=	ct.curr_id4dfExchange --ct.curr_id4Exchange

			-- =========================================================
			-- TN : 621
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	ct.comp_id
			AND vubf.bra_id			=	bra.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================


	where	ct.comp_id			=	@comp_id
	AND		(@bra_id  = -1 or ct.bra_id	=	@bra_id)
	and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))

-- MOS, se pasa a temporal
--	and		ct.ct_date			between		@datefrom		and		@dateto
--	and		ct.ct_payDate		between		@paydatefrom	and		@paydateto

	--si se seleccionan sólo facturas trae sólo las que tienen ítems cargados
	and     (
			 (@sd_id	= -1)																								OR
			 (@sd_id	= 1			AND EXISTS		(SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
														AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])) OR
			 (@sd_id	= -2		AND ct.sd_id IN (SELECT sd_id FROM tbsysDocuments td WHERE td.sd_isInBalance = 'true')) OR
			 (@sd_id	= 2			AND ct.sd_id IN (2,52)) OR
			 (ct.sd_id	= @sd_id	AND @sd_id > 1)
			)

	and		ct.ct_docNumber			<> ''
	AND		ct.sd_id				<>	301


	order by ct.ct_date, ct.ct_transaction

	-- ------------------------------------------
	-- Recalculo del saldo acumulado
	-- ------------------------------------------
	DECLARE @decBalance AS DECIMAL(19,4)
	SET @decBalance = 0;

	DECLARE @tblTmp AS TABLE(	ct_transaction int,
								ct_ATotal DECIMAL(19,6),
								ct_Credits DECIMAL(19,6),
								ct_AAdjust DECIMAL(19,6),
								balance DECIMAL(19,6),
								sd_id int)

	INSERT INTO  @tblTmp (ct_transaction,ct_ATotal,ct_Credits,ct_AAdjust,balance,sd_id)
		SELECT				tmp.ct_transaction,
							tmp.ct_ATotal ,
							tmp.ct_Credits ,
							IsNull(tct.ct_AAdjust,0) ,
							balance,
							tct.sd_id
						FROM #tmpData tmp
						INNER JOIN tbCommercialTransactions tct
						ON tct.ct_transaction = tmp.ct_transaction
						ORDER BY tmp.ct_date, tmp.ct_transaction

		UPDATE @tblTmp
				SET @decBalance = (@decBalance +
					CASE
						WHEN sd_id > 100  and sd_id < 150 THEN (ct_ATotal + ct_Credits  /*-IsNull(ct_AAdjust,0)*/ )
						WHEN sd_id < 100  and sd_id < 50  THEN (ct_ATotal + ct_Credits  /*-IsNull(ct_AAdjust,0)*/ )
						ELSE 0
					END
								   ),
				Balance = Balance + @decBalance

		UPDATE #tmpData
			SET Balance = tmp1.balance
		FROM #tmpData	tmp
		INNER JOIN @tblTmp tmp1
			ON tmp1.ct_transaction = tmp.ct_transaction


	SELECT *
		FROM #tmpData ct
	WHERE 	ct.ct_date			between		@datefrom		and		@dateto
		and	ct.ct_payDate		between		@paydatefrom	and		@paydateto
	ORDER BY ct.ct_date, ct.ct_transaction

	/****************************************************************************************************/


END
GO








CREATE PROCEDURE [dbo].[spCommercialTransactions_getDataByFilters_new]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@selection_id		INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@paydatefrom		DATETIME,
	@paydateto			DATETIME,
	@sd_id				INT,
	@ispurchase			BIT,
	@user_id			INT
)
AS

SET NOCOUNT ON
SET DATEFORMAT 'ymd'


/********************************************************************************************************
si @ispurchase es True significa que la consulta está relacionada a una compra por lo tanto
se debe considerar el @selection_id como proveedor o sea supp_id, si @ispurchase es False
significa que la consulta está relacionada a una venta, en éste caso se debe considerar el
@selection_id como cliente o sea cust_id
*********************************************************************************************************/


-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-08-18
-- Parte		: 486
-- Description	: En la columna [6] que es donde se envía la marca que indica si se puede o no anular el comprobante,
--				  se habilita la anulación para el caso en que es un pago de 'Otros Pagos' que se reconoce si el
--				  proveedor es el que está informado en la sucursal como proveedor de otros pagos.
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-09-30
-- Parte		: sin parte Referencia: #1
-- Description	: Se agregan las comunas [doc_ACurrencyExchange] informa el importe pendiente en la moneda del
-- cliente/proveedor con la cotización del momento de generación del comprobante y [doc_dfExchange] informa el
-- importe pendiente en la moneda del comprobante en la cotización del momento de la generación del comprobante
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-10-18
-- Parte		: sin parte Referencia: #2
-- Description	: Se modifica la fórmula para el cálculo del campo [doc_dfExchange] de:
-- CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d)) a:
-- dbo.fnGetExchange2(@comp_id,ct.ct_ABalance,ct.ct_ACurrency,ct.curr_id4dfExchange,
--							ct.curr_id_transaction,ct.curr_id4dfExchange,ct.ct_dfExchange,'false')
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2011-01-03
-- Parte		: 746
-- Description	: Control que permite anular compras a proveedores u órdenes de pago qué solo estén dentro del rango
--				  de fechas de los campos bra_PurDoc_MinTaxDate y bra_PurDoc_MaxTaxDate de la tabla tbBranch
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2011-01-18
-- Parte		: 784
-- Description	: Se habilita la opción de anular remitos de clientes/proveedores siempre que tengan artículos cargados
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2011-01-18
-- Parte		: 771
-- Description	: Se habilita la opción de anular facturas de proveedores si no tiene items con serialización tomada
-- =================================================================================================================




/*
declare 	@comp_id			int,
			@lang_id			int,
			@bra_id				int,
			@selection_id		int,
			@datefrom			datetime,
			@dateto				datetime,
			@paydatefrom		datetime,
			@paydateto			datetime,
			@sd_id				int,
			@ispurchase			bit,
			@user_id			int

select		@comp_id			= 1,
			@lang_id			= 2,
			@bra_id				= 1,
			@selection_id		= 24288,
			@datefrom			= convert(datetime,'2000-01-01'),
			@dateto				= convert(datetime,'9999-12-31'),
			@paydatefrom		= convert(datetime,'2000-01-01'),
			@paydateto			= convert(datetime,'9999-12-31'),
			@sd_id				= 2,
			@ispurchase			= 'false',
			@user_id			= 1

DROP TABLE #tmpData
--DROP TABLE #tmpAdd
--DROP TABLE #tmpSustract
DROP TABLE #tmpIT
DROP TABLE #tmpAPP
DROP TABLE #tmpTCTN
DROP TABLE #tmpRetentions
--DROP TABLE #tmpRetentions2
*/






declare @d int
set		@d = 2






/****************************************************************************************************/
/*recuperar el cambio actual entre la moneda de la sucursal con respesto a la del cliente/proveedor */
DECLARE	@current_exchange			DECIMAL(18,6),
		@curr_id_1					INT,
		@curr_id_2					INT,
		@bra_PaymentSupp_Id			INT					--Parte:486


SELECT	@curr_id_1			= tb.curr_id,
		@bra_PaymentSupp_Id	= ISNULL(tb.bra_PaymentSupp_Id,-1)		--Parte:486
FROM	tbBranch	tb
WHERE	tb.comp_id	= @comp_id
AND		tb.bra_id	= @bra_id


IF @ispurchase = 'False'
	BEGIN
		SELECT	@curr_id_2 =tc.curr_id
		FROM	tbCustomer tc
   		WHERE	tc.comp_id = @comp_id AND tc.cust_id = @selection_id
	END
ELSE
	BEGIN
		SELECT	@curr_id_2 = tc.curr_id
		FROM	tbSupplier tc
   		WHERE	tc.comp_id = @comp_id AND tc.supp_id = @selection_id
	END


SELECT	@current_exchange = dbo.fnGetExchange(@comp_id, 1, @curr_id_2, @curr_id_1, 0, 0, 'False')
/****************************************************************************************************/





/****************************************************************************************************/
/* Agregamos horas para que tome el dia completo a las fechas hasta *********************************/
set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,1)
set	@paydateto	= dbo.fnGetEnd_or_BeginOfDate(@paydateto,1)
--select @dateto, @paydateto
/****************************************************************************************************/





/****************************************************************************************************/
/* Generacion de temporal para determinar si cada CommercialTransaction tiene items *****************/
SELECT	DISTINCT	tit.comp_id,	tit.bra_id,		tit.ct_transaction,		1	[value]
INTO	#tmpIT
FROM	dbo.tbItemTransactions						tit
		INNER JOIN dbo.tbCommercialTransactions		ct
		ON	ct.comp_id			=	tit.comp_id
		AND ct.bra_id			=	tit.bra_id
		AND ct.ct_transaction	=	tit.ct_transaction
WHERE	tit.comp_id				=	@comp_id
AND		tit.bra_id				=	@bra_id
AND 	((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
AND		ct.sd_id				<>	301

UNION

SELECT 	DISTINCT	vct.comp_id,	vct.bra_id,		vct.ct_transaction,		1	[value]
FROM 	vwCollection								vct
		inner join dbo.[tbCommercialTransactions]	ct
		on	ct.[comp_id]		=	vct.comp_id
		and ct.[bra_id]			=	vct.bra_id
		and ct.[ct_transaction] =	vct.ct_transaction
WHERE	vct.comp_id				=	@comp_id
AND		vct.bra_id				=	@bra_id
AND 	((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
AND		ct.sd_id				<>	301

UNION

SELECT	DISTINCT	tpcm.comp_id,	tpcm.bra_id,	tpcm.ct_transaction,	1 [value]
FROM	tbPurchaseConceptMovements					tpcm
		INNER JOIN tbCommercialTransactions			tct
		ON	tct.comp_id			=	tpcm.comp_id
		AND tct.bra_id			=	tpcm.bra_id
		AND tct.ct_transaction	=	tpcm.ct_transaction
WHERE	tpcm.comp_id			=	@comp_id
AND		tpcm.bra_id				=	@bra_id
and		((@ispurchase = 'True'	AND (@selection_id = -1 or tct.supp_id = @selection_id)) or
		 (@ispurchase = 'False'	AND (@selection_id = -1 or tct.cust_id = @selection_id)))

--SELECT * FROM #tmpIT
/****************************************************************************************************/






/****************************************************************************************************/
/****************************************************************************************************/
SELECT	DISTINCT
		ta.comp_id,
		ta.bra_id,
		ta.ct_transaction_Source	[ct_transaction],
		1							[value]
INTO	#tmpAPP
FROM	dbo.tbApplication							ta
		INNER JOIN dbo.tbCommercialTransactions		ct
		ON	ct.comp_id			=	ta.comp_id
		AND ct.bra_id			=	ta.bra_id
		AND ct.ct_transaction	=	ta.ct_transaction_Source
WHERE	ta.comp_id				=	@comp_id
AND		ta.bra_id				=	@bra_id
and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
AND		ct.sd_id				<>	301

UNION

SELECT	DISTINCT
		ta.comp_id,
		ta.bra_id,
		ta.ct_transaction_destiny [ct_transaction],
		1 [value]
FROM	dbo.tbApplication							ta
		INNER JOIN dbo.tbCommercialTransactions		ct
		ON	ct.comp_id			=	ta.comp_id
		AND ct.bra_id			=	ta.bra_id
		AND ct.ct_transaction	=	ta.ct_transaction_destiny
WHERE	ta.comp_id				=	@comp_id
AND		ta.bra_id				=	@bra_id
and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
AND		ct.sd_id				<>	301
--SELECT * FROM #tmpAPP
/****************************************************************************************************/







/****************************************************************************************************/
/****************************************************************************************************/
SELECT	DISTINCT
		tctn.comp_id,
		tctn.bra_id,
		tctn.ct_transaction,
		1 [value]
INTO	#tmpTCTN
FROM	dbo.tbCommercialTransactionNotes tctn
		INNER JOIN dbo.tbCommercialTransactions ct
		ON	ct.comp_id			= tctn.comp_id
		AND ct.bra_id			= tctn.bra_id
		AND ct.ct_transaction	= tctn.ct_transaction
WHERE	tctn.comp_id			=	@comp_id
AND		tctn.bra_id				=	@bra_id
AND		(len(rtrim(ltrim(tctn.ctn_note1))) > 0	OR
		len(rtrim(ltrim(tctn.ctn_note2))) > 0	OR
		len(rtrim(ltrim(tctn.ctn_note3))) > 0	OR
		len(rtrim(ltrim(tctn.ctn_note4))) > 0)
and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
AND		ct.sd_id				<>	301
--SELECT * FROM #tmpTCTN
/****************************************************************************************************/







/****************************************************************************************************/
/* Genracion de temporal para determinar retenciones para cada CT ***********************************/
SELECT	COUNT(*) [count],
		ttm.ct_transaction
INTO	#tmpRetentions
FROM	tbTaxMovements								ttm
		INNER JOIN tbTaxName						ttn
		ON	ttn.comp_id			= ttm.comp_id
		AND ttn.tax_id			= ttm.tax_id
		INNER JOIN vwsysTaxClassALL_Retentions		vtcar
		ON	vtcar.tax_class		= ttn.tax_class
WHERE	ttm.comp_id				= @comp_id
AND		ttm.bra_id				= @bra_id
AND		ttm.tm_total			> 0
group BY ttm.ct_transaction
--SELECT * FROM #tmpRetentions ORDER BY 2
/****************************************************************************************************/








/****************************************************************************************************/
/****************************************************************************************************/
select	ISNULL(tit.value,0)		[1],
		ISNULL(app.value,0)		[2],
		ISNULL(tctn.value,0)	[3],
		' '						[4],
		ISNULL(ret.[count],0)	[5],

		CASE

			WHEN
				-- =====================================================================================================
				-- parte: 746
				(
					@ispurchase = 'True'	AND
					(ct.ct_taxDate  BETWEEN	isnull(bra.bra_PurDoc_MinTaxDate,GETDATE()) AND
												isnull(bra.bra_PurDoc_MaxTaxDate,GETDATE()))
											AND
					(ct.sd_id IN (106, 103, 104))
				)
				AND
				-- =====================================================================================================
				(
					ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance
				)
				THEN 1  --NC, ND de proveedores --habilita la anulación



			WHEN
				-- =====================================================================================================
				-- parte: 771
				(
					@ispurchase	= 'True'									AND
					(ct.ct_taxDate  BETWEEN	ISNULL(bra.bra_PurDoc_MinTaxDate,GETDATE()) AND
											ISNULL(bra.bra_PurDoc_MaxTaxDate,GETDATE()))
																			AND
					ct.sd_id	= 101										AND
					ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance AND
					NOT EXISTS (SELECT TOP 1 1 FROM tbItemSerials tis WHERE tis.comp_id = ct.comp_id
								AND tis.ct_transaction = ct.ct_transaction AND tis.is_available = 'False')
				)
				THEN 4  --FC de proveedores --habilita la anulación
				-- =====================================================================================================



			WHEN
				(
			 		 ct.sd_id IN (6, 13, 106)									AND
			 		 ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance
				) THEN 2  --OP a proveedores, RC de clientes --habilita la anulación


			WHEN
				(
			 		 ct.sd_id IN (6,13,106) and
			 		 @bra_PaymentSupp_Id = ct.supp_id
				) THEN 2	--Parte:486 --habilita la anulación


			-- =====================================================================================================
			-- Parte: 784
			WHEN
				(
					ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
												AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
								 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
												AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
												AND NOT tdf.df_id4PLAnnulment IS NULL)
								 AND EXISTS (SELECT 1 FROM tbItemTransactions tit2 WHERE tit2.comp_id = ct.comp_id
												AND tit2.bra_id = ct.bra_id AND tit2.ct_transaction =ct.ct_transaction
												AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
				) THEN 3 --RM de clientes que tengan algún registro en tbItemsTransactions

			WHEN
				(
					ct.sd_id = 2 AND NOT EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
												AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
				) THEN 94 --RM de clientes que tengan algún registro en tbItemsTransactions
			WHEN
				(
					ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
												AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
								 AND NOT EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
												AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
												AND NOT tdf.df_id4PLAnnulment IS NULL)
				) THEN 95 --RM de clientes que tengan algún registro en tbItemsTransactions
			WHEN
				(
					ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
												AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
								 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
												AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
												AND NOT tdf.df_id4PLAnnulment IS NULL)
								 AND NOT EXISTS (SELECT 1 FROM tbItemTransactions tit2 WHERE tit2.comp_id = ct.comp_id
												AND tit2.bra_id = ct.bra_id AND tit2.ct_transaction =ct.ct_transaction
												AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
				) THEN 96 --RM de clientes que tengan algún registro en tbItemsTransactions


			WHEN
				(
					ct.sd_id = 102
				) THEN 3 --RM de proveedores
			-- =====================================================================================================


			ELSE	0 --deshabilita la anulación
		END						[6],


		ct.comp_id,
		ct.bra_id,
		sd.sd_desc,
		ct.ct_transaction,
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.[ct_transaction])		[doc_number],
		ct.ct_docNumber,
		ct.ct_date,
		ct.ct_taxDate,
		ct.ct_payDate,
		ct.supp_id,
		ct.cust_id,
		ct.cb_id,

		--cb.custb_name,	--REF:#1
		ct.user_id,
		--ct.ct_cd,			--REF:#1

		CASE WHEN sd.sd_isInBalance = 'true' THEN
			convert(decimal(18,2),round(ct.ct_subtotal	,@d)) *
				CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
				ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
			ELSE 0
		END		[ct_subtotal],

		CASE WHEN sd.sd_isInBalance = 'true' THEN
			convert(decimal(18,2),round(ct.ct_total - ct.ct_adjust,@d)) *
				CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
				ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
			ELSE 0
		END		[ct_total],

		ct.ct_discount,
		ct.ct_taxes,
		ct.curr_id_transaction,
		ct.hacc_transaction,
		ct.disc_id,

		CASE WHEN sd.sd_isInBalance = 'true' THEN
			CONVERT (DECIMAL (18,2),ROUND((ct.ct_ATotal - isnull(ct.ct_AAdjust,0)),@d)) *
				CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
				ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
			ELSE 0
		END		[ct_ATotal],

		CASE WHEN sd.sd_isInBalance = 'true' THEN
			CONVERT (DECIMAL (18,2),ROUND (ct.ct_ABalance	,@d)) *
				CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
				ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
			ELSE 0
		END 	[ct_ABalance],


		ct.ct_ACurrency,

		ct.ct_ACurrencyExchange,

		CASE WHEN sd.sd_isInBalance = 'true' THEN
				CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * @current_exchange,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
						ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE  CONVERT(DECIMAL(18,2), 0)
			END [branch_ACurrency],



		--=================================================================================================================
		-- Referencia: #1
		CASE WHEN sd.sd_isInBalance = 'true' THEN
				CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_ACurrencyExchange,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
						ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE  CONVERT(DECIMAL(18,2), 0)
			END [doc_ACurrencyExchange],


		CONVERT(VARCHAR,
		CASE WHEN sd.sd_isInBalance = 'true' THEN
				--CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d))				--Ref: #2
				CONVERT(DECIMAL(18,2),round(
					dbo.fnGetExchange2(@comp_id,ct.ct_ABalance,ct.ct_ACurrency,ct.curr_id4dfExchange,	--Ref: #2
						ct.curr_id4dfExchange,ct.curr_id_transaction,ct.ct_dfExchange,'false'),@d))		--Ref: #2
				*
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
						ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE  CONVERT(DECIMAL(18,2), 0)
			END)
		+ ' (' + ltrim(rtrim(tc.curr_symbol)) + ')'
				[doc_dfExchange],
		--=================================================================================================================


		ct.df_id,
		ct.dl_id,
		ct.st_id,
		ct.sd_id,
		ct.puco_id,
		ct.sm_id,
		sm.sm_name,
		tst.st_desc,

		ct.ct_CompanyCurrency,
		ct.ct_Branch2CompanyCurrencyExchange,
		ct.ct_adjust,

		cb.custb_name,	--REF:#1
		ct.ct_cd,		--REF:#1

		us.user_lastname + ', ' + user_firstname														[user_name],
		convert(varchar,IsNull(ct.ct_soh_bra_id,0)) + '-' + convert(varchar,IsNull(ct.ct_soh_id,0))		[soh_id_fromGenerated],
		convert(varchar,ct.ct_transaction) + '-' + convert(varchar,ct.sd_id)							[ID]


INTO	#tmpData


FROM 	dbo.tbCommercialTransactions					ct

		LEFT JOIN vwCommercialTransactions_forSales		vctfs
		ON	vctfs.comp_id			=	ct.comp_id
		AND vctfs.bra_id			=	ct.bra_id
		AND vctfs.ct_transaction	=	ct.ct_transaction
		AND vctfs.cust_id			=	ct.cust_id
		AND @ispurchase				=	'False'

		LEFT JOIN vwCommercialTransactions_forPurchase	vctfp
		ON	vctfp.comp_id			=	ct.comp_id
		AND vctfp.bra_id			=	ct.bra_id
		AND vctfp.ct_transaction	=	ct.ct_transaction
		AND vctfp.supp_id			=	ct.supp_id
		AND @ispurchase				=	'True'

		LEFT JOIN dbo.tbBranch							bra
		on	bra.bra_id				=	ct.bra_id
		and	ct.comp_id				=	bra.comp_id

		LEFT JOIN dbo.tbSalesman						sm
		on	sm.sm_id				=	ct.sm_id
		and	ct.comp_id				=	sm.comp_id

		left join dbo.tbUser							us
		on		us.user_id			=	ct.user_id

		left join dbo.tbCustomerBranch					cb
		on		cb.comp_id			=	ct.comp_id
	    and		cb.cust_id			=	ct.cust_id
		and		cb.cb_id			=	ct.cb_id

		left join dbo.tbsysDocuments					sd
		on		sd.sd_id			=	ct.sd_id
		and		sd.sd_isPurchase	=	@ispurchase

		LEFT JOIN dbo.tbSalesTerms						tst
		ON		tst.comp_id			=	ct.comp_id
		AND		tst.st_id			=	ct.st_id

		LEFT JOIN #tmpIT								tit
		ON		tit.comp_id			=	ct.comp_id
		AND		tit.bra_id			=	ct.bra_id
		AND		tit.ct_transaction	=	ct.ct_transaction

		LEFT JOIN #tmpAPP								app
		ON		app.comp_id			=	ct.comp_id
		AND		app.bra_id			=	ct.bra_id
		AND		app.ct_transaction	=	ct.ct_transaction

		LEFT JOIN #tmpTCTN								tctn
		ON		tctn.comp_id		=	ct.comp_id
		AND		tctn.bra_id			=	ct.bra_id
		AND		tctn.ct_transaction	=	ct.ct_transaction

		LEFT JOIN #tmpRetentions						ret
		ON		ret.ct_transaction	=	ct.ct_transaction

		LEFT JOIN tbsysCurrency							tc
		ON		tc.curr_id			=	ct.curr_id4dfExchange --ct.curr_id4Exchange


where	ct.comp_id			=	@comp_id
and		ct.bra_id			=	@bra_id
and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
and		ct.ct_date			between		@datefrom		and		@dateto
and		ct.ct_payDate		between		@paydatefrom	and		@paydateto

--si se seleccionan sólo facturas trae sólo las que tienen ítems cargados
and     (
		 (@sd_id	= -1)						OR
		 (@sd_id	= 1			AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
												AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])) OR
		 (ct.sd_id	= @sd_id	AND @sd_id > 1) OR
		 (@sd_id	= -2		AND ct.sd_id IN (SELECT sd_id FROM tbsysDocuments td
		        									WHERE td.sd_isInBalance = 'true'))
		)

and		ct.ct_docNumber <> ''
AND		ct.sd_id				<>	301


order by ct.ct_date, ct.ct_transaction




SELECT * FROM #tmpData
/****************************************************************************************************/






SELECT 	isnull(sum([ct_ATotal]			),0)		[ct_ATotal],
		isnull(sum([ct_ABalance]		),0)		[ct_ABalance],
		@current_exchange							[current_exchange],
		isnull(sum([branch_ACurrency]	),0)		[branch_ACurrency]
FROM	#tmpData
		INNER JOIN tbsysDocuments td
		ON	td.sd_id			= #tmpData.sd_id
		AND td.sd_isInBalance	= 'True'









-- -------------------------------------------------------------------------------------
-- MOS: Trae el Estado de Credito del Cliente y lo
-- devuelve en una nueva tabla con los siguientes campos
-- -------------------------------------------------------------------------------------
--	cust_credit_max							Credito Maximo
--	cust_credit_own							Credito Maximo en Valores Propios
--	cust_credit_cheque_own_used				Cheques Propios
--	cust_credit_cheque_3rd_used				Cheques de Terceros
--	cust_credit_SaleOrder					Pedidos Pendientes
--	cust_credit_balance						Saldo de Cta Corriente
--	cust_credit_balance_OverCome			Saldo Vencido de Cuenta Corriente
--	cust_credit_balance_NotOverCome			Saldo NO VENCIDO de Cuenta Corriente
IF @ispurchase = 'False'
	BEGIN
		DECLARE	@branch_curr_id INT, @branch_processingdata DATETIME

		SELECT	@branch_curr_id			= tb.curr_id,
				@branch_processingdata	= tb.bra_processingDate
		FROM	tbBranch tb
		WHERE	tb.comp_id				=  @comp_id
		AND		tb.bra_id				= @bra_id

		SELECT * From dbo.fnCustomer_getBalanceStatus(@comp_id,@branch_curr_id,@selection_id,@user_id,@branch_processingdata,-1,-1)
	END
-- -------------------------------------------------------------------------------------
GO








-- NO SE USA MAS !!!!!!!!

-- --------------------------------------------------------------------------------------------------------------------------------------
-- --------------------------------------------------------------------------------------------------------------------------------------
-- COPIA EXACTA DE SP [spCommercialTransactions_getDataByFilters] SIN LOS 2 ULTIMOS RESULTSETS
-- SE UTILIZA PARA EL CHEQUEO DE LOS SALDOS DE LAS APLICACIONES DE CUENTAS CORRIENTES spCommercialTransactions_CheckBalance-
--  y para sysGenericCustomExports
-- --------------------------------------------------------------------------------------------------------------------------------------
-- --------------------------------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[spCommercialTransactions_getDataByFilters_prueba]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@selection_id		INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@paydatefrom		DATETIME,
	@paydateto			DATETIME,
	@sd_id				INT,
	@ispurchase			BIT,
	@user_id			INT
)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	/********************************************************************************************************
	si @ispurchase es True significa que la consulta está relacionada a una compra por lo tanto
	se debe considerar el @selection_id como proveedor o sea supp_id, si @ispurchase es False
	significa que la consulta está relacionada a una venta, en éste caso se debe considerar el
	@selection_id como cliente o sea cust_id
	*********************************************************************************************************/


	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-18
	-- Parte		: 486
	-- Description	: En la columna [6] que es donde se envía la marca que indica si se puede o no anular el comprobante,
	--				  se habilita la anulación para el caso en que es un pago de 'Otros Pagos' que se reconoce si el
	--				  proveedor es el que está informado en la sucursal como proveedor de otros pagos.
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-09-30
	-- Parte		: sin parte Referencia: #1
	-- Description	: Se agregan las comunas [doc_ACurrencyExchange] informa el importe pendiente en la moneda del
	-- cliente/proveedor con la cotización del momento de generación del comprobante y [doc_dfExchange] informa el
	-- importe pendiente en la moneda del comprobante en la cotización del momento de la generación del comprobante
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-10-18
	-- Parte		: sin parte Referencia: #2
	-- Description	: Se modifica la fórmula para el cálculo del campo [doc_dfExchange] de:
	-- CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d)) a:
	-- dbo.fnGetExchange2(@comp_id,ct.ct_ABalance,ct.ct_ACurrency,ct.curr_id4dfExchange,
	--							ct.curr_id_transaction,ct.curr_id4dfExchange,ct.ct_dfExchange,'false')
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-01-03
	-- Parte		: 746
	-- Description	: Control que permite anular compras a proveedores u órdenes de pago qué solo estén dentro del rango
	--				  de fechas de los campos bra_PurDoc_MinTaxDate y bra_PurDoc_MaxTaxDate de la tabla tbBranch
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-01-18
	-- Parte		: 784
	-- Description	: Se habilita la opción de anular remitos de proveedores siempre que tengan artículos cargados
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-01-18
	-- Parte		: 771
	-- Description	: Se habilita la opción de anular facturas de proveedores si no tiene items con serialización tomada
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-02-03
	-- Parte		: 784
	-- Description	: Se habilita la opción de anular remitos de clientes siempre que tengan artículos cargados y
	--				  que el remito tenga asignado un documento de rechazo y que el remito no tenga algún artículo
	--				  facturado y que ya no haya sido anulado anteriormente
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-03-28
	-- Parte		: S/N -  Referencia: #3
	-- Description	: Se cambia el cálculo de la columna [doc_ACurrencyExchange]
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-04-11
	-- Parte		: S/N -  Referencia: #4
	-- Description	: Se agrega una condición para mostrar en el campo [ct_ACurrencyExchange]
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-04-11
	-- Parte		: S/N -  Referencia: #5
	-- Description	: Se agrega un nuevo campo [ct_ATotal_dfExchange] a la consulta general
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-05-26
	-- TN			: 621
	-- Description	: se modifica el filtro por sucursal recibida por parámetro por un filtro a través de la vista
	--
	-- =================================================================================================================



-- -----------------------------------------------------------
-- Testing
-- -----------------------------------------------------------
/*
	declare 	@comp_id			int,
				@lang_id			int,
				@bra_id				int,
				@selection_id		int,
				@datefrom			datetime,
				@dateto				datetime,
				@paydatefrom		datetime,
				@paydateto			datetime,
				@sd_id				int,
				@ispurchase			bit,
				@user_id			int
	select		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@selection_id		= 24294,
				@datefrom			= convert(datetime,'2000-01-01'),
				@dateto				= convert(datetime,'9999-12-31'),
				@paydatefrom		= convert(datetime,'2000-01-01'),
				@paydateto			= convert(datetime,'9999-12-31'),
				@sd_id				= -2,
				@ispurchase			= 'false',
				@user_id			= 1

	DROP TABLE #tmpIT
	DROP TABLE #tmpAPP
	DROP TABLE #tmpTCTN
	DROP TABLE #tmpRetentions
	DROP TABLE #tmpData

	----DROP TABLE #tmpAdd
	----DROP TABLE #tmpSustract
	----DROP TABLE #tmpRetentions2
*/
-- -----------------------------------------------------------


	-- Fantastica idea de poner en este nombre de variable la cantidad de decimales a redondear.
	-- Quien se IMAGINA que quiere decir @d?
	declare @d int
	set		@d = 2






	/****************************************************************************************************/
	/*recuperar el cambio actual entre la moneda de la sucursal con respesto a la del cliente/proveedor */
	DECLARE	@current_exchange			DECIMAL(18,6),
			@curr_id_branch				INT,
			@curr_id_2					INT,
			@bra_PaymentSupp_Id			INT					--Parte:486


	SELECT TOP 1	@curr_id_branch		= tb.curr_id,
			@bra_PaymentSupp_Id	= ISNULL(tb.bra_PaymentSupp_Id,-1)		--Parte:486
	FROM	tbBranch	tb
	WHERE	tb.comp_id	= @comp_id
	--AND		tb.bra_id	= @bra_id



	IF @ispurchase = 'false'
		SELECT	@curr_id_2 =tc.curr_id
		FROM	tbCustomer tc
		WHERE	tc.comp_id = @comp_id AND tc.cust_id = @selection_id
	ELSE
		SELECT	@curr_id_2 = tc.curr_id
		FROM	tbSupplier tc
		WHERE	tc.comp_id = @comp_id AND tc.supp_id = @selection_id



	SELECT	@current_exchange = dbo.fnGetExchange(@comp_id, 1, @curr_id_2, @curr_id_branch, 0, 0, 'False')
	/****************************************************************************************************/
	--SELECT @curr_id_branch, @curr_id_2
	--SELECT * FROM tbsysCurrency tc




	/****************************************************************************************************/
	/* Agregamos horas para que tome el dia completo a las fechas hasta *********************************/
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,1)
	set	@paydateto	= dbo.fnGetEnd_or_BeginOfDate(@paydateto,1)
	--select @dateto, @paydateto
	/****************************************************************************************************/





	/****************************************************************************************************/
	/* Generacion de temporal para determinar si cada CommercialTransaction tiene items *****************/
	SELECT	DISTINCT	tit.comp_id,	tit.bra_id,		tit.ct_transaction,		1	[value]
	INTO	#tmpIT
	FROM	dbo.tbItemTransactions						tit
			INNER JOIN dbo.tbCommercialTransactions		ct
			ON	ct.comp_id			=	tit.comp_id
			AND ct.bra_id			=	tit.bra_id
			AND ct.ct_transaction	=	tit.ct_transaction

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	tit.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	tit.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	tit.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	tit.comp_id						=	@comp_id
	--AND		(@bra_id  = -1 or tit.bra_id	=	@bra_id)
	AND 	((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301


	UNION

	SELECT 	DISTINCT	vct.comp_id,	vct.bra_id,		vct.ct_transaction,		1	[value]
	FROM 	vwCollection								vct
			inner join dbo.[tbCommercialTransactions]	ct
			on	ct.[comp_id]		=	vct.comp_id
			and ct.[bra_id]			=	vct.bra_id
			and ct.[ct_transaction] =	vct.ct_transaction

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	vct.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	vct.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	vct.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	vct.comp_id				=	@comp_id
		--AND		(@bra_id  = -1 or vct.bra_id	=	@bra_id)
	AND 	((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301


	UNION


	SELECT	DISTINCT	tpcm.comp_id,	tpcm.bra_id,	tpcm.ct_transaction,	1 [value]
	FROM	tbPurchaseConceptMovements					tpcm
			INNER JOIN tbCommercialTransactions			tct
			ON	tct.comp_id			=	tpcm.comp_id
			AND tct.bra_id			=	tpcm.bra_id
			AND tct.ct_transaction	=	tpcm.ct_transaction

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	tpcm.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	tpcm.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	tpcm.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	tpcm.comp_id			=	@comp_id
	--AND		(@bra_id  = -1 or tpcm.bra_id	=	@bra_id)
	AND 	((@ispurchase = 'True'	AND (@selection_id = -1 or tct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	AND (@selection_id = -1 or tct.cust_id = @selection_id)))

	--SELECT * FROM #tmpIT
	/****************************************************************************************************/






	/****************************************************************************************************/
	/****************************************************************************************************/
	SELECT	DISTINCT
			ta.comp_id,
			ta.bra_id,
			ta.ct_transaction_Source	[ct_transaction],
			1							[value]
	INTO	#tmpAPP
	FROM	dbo.tbApplication							ta
			INNER JOIN dbo.tbCommercialTransactions		ct
			ON	ct.comp_id			=	ta.comp_id
			AND ct.bra_id			=	ta.bra_id
			AND ct.ct_transaction	=	ta.ct_transaction_Source

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	ta.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	ta.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	ta.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	ta.comp_id				=	@comp_id
	--AND	ta.bra_id				=	@bra_id		TN : 621
	and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301


	UNION


	SELECT	DISTINCT
			ta.comp_id,
			ta.bra_id,
			ta.ct_transaction_destiny [ct_transaction],
			1 [value]
	FROM	dbo.tbApplication							ta
			INNER JOIN dbo.tbCommercialTransactions		ct
			ON	ct.comp_id			=	ta.comp_id
			AND ct.bra_id			=	ta.bra_id
			AND ct.ct_transaction	=	ta.ct_transaction_destiny

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	ta.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	ta.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	ta.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	ta.comp_id				=	@comp_id
	--AND	ta.bra_id				=	@bra_id		--TN : 621
	AND 	((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301

	--SELECT * FROM #tmpAPP
	/****************************************************************************************************/







	/****************************************************************************************************/
	/****************************************************************************************************/
	SELECT	DISTINCT
			tctn.comp_id,
			tctn.bra_id,
			tctn.ct_transaction,
			1 [value]
	INTO	#tmpTCTN
	FROM	dbo.tbCommercialTransactionNotes			tctn
			INNER JOIN dbo.tbCommercialTransactions		ct
			ON	ct.comp_id			= tctn.comp_id
			AND ct.bra_id			= tctn.bra_id
			AND ct.ct_transaction	= tctn.ct_transaction

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	tctn.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	tctn.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	tctn.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	tctn.comp_id			=	@comp_id
	--AND	tctn.bra_id				=	@bra_id		--TN : 621
	AND		(len(rtrim(ltrim(tctn.ctn_note1))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note2))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note3))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note4))) > 0)
	and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301

	--SELECT * FROM #tmpTCTN
	/****************************************************************************************************/







	/****************************************************************************************************/
	/* Genracion de temporal para determinar retenciones para cada CT ***********************************/
	SELECT	COUNT(*) [count],
			ttm.ct_transaction
	INTO	#tmpRetentions
	FROM	tbTaxMovements								ttm
			INNER JOIN tbTaxName						ttn
			ON	ttn.comp_id			= ttm.comp_id
			AND ttn.tax_id			= ttm.tax_id
			INNER JOIN vwsysTaxClassALL_Retentions		vtcar
			ON	vtcar.tax_class		= ttn.tax_class

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	ttm.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	ttm.bra_id
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	ttm.comp_id
			AND vubf.bra_id			=	tb.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================

	WHERE	ttm.comp_id				= @comp_id
	--AND	ttm.bra_id				= @bra_id	--TN : 621
	AND		ttm.tm_total			> 0
	GROUP BY ttm.ct_transaction

	--SELECT * FROM #tmpRetentions ORDER BY 2
	/****************************************************************************************************/







	/****************************************************************************************************/
	/****************************************************************************************************/

	--TENER EN CUENTA QUE SI SE AGREGAN COLUMNAS AL QUERY FINAL DE SP SE DEBERÁ MODIFICAR EL CÓDIGO DE LA
	--PÁGINA EN LA RUTINA grdData_RowDataBound PARA EL CASO EN QUE SEA UNA ROW DEL TIPO Case DataControlRowType.Footer
	--Y MODIFICAR LOS COLUMNS SPANS CORRESPONDIENTES PARA QUE LOS TOTALES DE LA GRILLA COINCIDAN CON EL
	--NUEVO ENCOLUMNAMIENTO
	--TAMBIEN SE DEBRÁN VERIFICAR EN EL CODIGO DE LA PÁGINA EN EL grdData_RowDataBound TODOS LOS ÍNDICES
	--QUE SE VEAN AFECTADOS POR LA MODIFICACIÓN DE LAS COLUMNAS DUMMY PARA LOS BOTONES.

	/****************************************************************************************************/
	/****************************************************************************************************/

	select
			--ct.ct_ATotal ATotal,ct.ct_AAdjust AAdjust,ct.ct_ABalance ABalance,

			ISNULL(tit.value,0)		[1],
			ISNULL(app.value,0)		[2],
			ISNULL(tctn.value,0)	[3],
			' '						[4],
			ISNULL(ret.[count],0)	[5],

			CASE

				WHEN
					-- =====================================================================================================
					-- parte: 746
					(
						@ispurchase = 'True'	AND
						(ct.ct_taxDate  BETWEEN	isnull(bra.bra_PurDoc_MinTaxDate,GETDATE()) AND
													isnull(bra.bra_PurDoc_MaxTaxDate,GETDATE()))
												AND
						(ct.sd_id IN (106, 103, 104))
					)
					AND
					-- =====================================================================================================
					(
						(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
						(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
					)
					THEN 1  --NC, ND de proveedores --habilita la anulación



				WHEN
					-- =====================================================================================================
					-- parte: 771
					(
						@ispurchase	= 'True'									AND
						(ct.ct_taxDate  BETWEEN	ISNULL(bra.bra_PurDoc_MinTaxDate,GETDATE()) AND
												ISNULL(bra.bra_PurDoc_MaxTaxDate,GETDATE()))
																				AND
						ct.sd_id	= 101										AND
						(
							(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
							(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
						)														AND
						--NOT EXISTS (SELECT TOP 1 1 FROM tbItemSerials tis WHERE tis.comp_id = ct.comp_id
						--			AND tis.ct_transaction = ct.ct_transaction AND tis.is_available = 'False')
						NOT EXISTS (SELECT TOP 1 1 FROM tbItemSerials tis
									WHERE	tis.comp_id					= ct.comp_id
									AND		tis.ct_transaction			= ct.ct_transaction
									AND		(
												tis.is_available			= 'True'
											or	isnull(tis.is_serial,'')	<> ''
											)
									)
					)
					THEN 4  --FC de proveedores --habilita la anulación
					-- =====================================================================================================



				WHEN
					(
			 			ct.sd_id IN (6, 13)
			 			AND
			 			(
							(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
							(ct.ct_ATotal                           = ct.ct_ABalance) or
							(ABS(ct.ct_ATotal - ct.ct_ABalance) <= 0.01 ) or
							(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
			 			)
			 			AND
			 			NOT EXISTS (SELECT 1 FROM tbCheckPortfolio tcp1
			 			            WHERE tcp1.comp_id = ct.comp_id
			 			            AND tcp1.ct_transaction = ct.ct_transaction)

					) THEN 2  --RC de clientes --habilita la anulación


				WHEN
					(
			 			ct.sd_id IN (106)
			 			AND
			 			(
							(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
							(ct.ct_ATotal                           = ct.ct_ABalance) or
							(ABS(ct.ct_ATotal - ct.ct_ABalance) <= 0.01 ) or
							(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
						)

					) THEN 2  --OP a proveedores, --habilita la anulación


				WHEN
					(
			 			 ct.sd_id IN (6,13,106) and
			 			 @bra_PaymentSupp_Id = ct.supp_id
					) THEN 2	--Parte:486 --habilita la anulación


				-- =====================================================================================================
				-- Parte: 784
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND EXISTS (SELECT 1 FROM tbItemTransactions tit2 WHERE tit2.comp_id = ct.comp_id
													AND tit2.bra_id = ct.bra_id AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
									 AND ISNULL(ct.ct_isCancelled,'false') = 'false'
					) THEN 3 --RM de clientes que tengan algún registro en tbItemsTransactions y
							 --que el remito tenga asignado un documento de rechazo y
							 --que el remito no tenga algún artículo facturado y
							 --que ya no haya sido anulado anteriormente

				WHEN
					(
						ct.sd_id = 2 AND NOT EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
					) THEN 94 --RM de clientes NO tiene artículos asignados
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
									 AND NOT EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
					) THEN 95 --RM de clientes NO tiene asigando un documento de rechazo
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND NOT EXISTS (SELECT 1 FROM tbItemTransactions tit2 WHERE tit2.comp_id = ct.comp_id
													AND tit2.bra_id = ct.bra_id AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
					) THEN 96 --RM de clientes YA tiene algún artículo facturado
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND EXISTS (SELECT 1 FROM tbItemTransactions tit2 WHERE tit2.comp_id = ct.comp_id
													AND tit2.bra_id = ct.bra_id AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
									 AND ISNULL(ct.ct_isCancelled,'false') = 'true'
					) THEN 93 --RM de clientes YA ha sido anulado anteriormente


				WHEN
					(
						ct.sd_id = 52
					) THEN 92 --No se permiten anular la anulación de Remitos


				WHEN
					(
						ct.sd_id = 102
					) THEN 3 --RM de proveedores
				-- =====================================================================================================


				ELSE	0 --deshabilita la anulación
			END						[6],

			' '						[7], --Parte 631
			' '						[8], --Parte 631


			ct.comp_id,
			ct.bra_id,
			sd.sd_desc,
			ct.ct_transaction,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.[ct_transaction])		[doc_number],
			ct.ct_docNumber,
			ct.ct_date,
			ct.ct_taxDate,
			ct.ct_payDate,
			ct.supp_id,
			ct.cust_id,
			ct.cb_id,

			--cb.custb_name,	--REF:#1
			ct.user_id,
			--ct.ct_cd,			--REF:#1

			CASE WHEN sd.sd_isInBalance = 'true' THEN
				convert(decimal(18,2),round(ct.ct_subtotal	,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END		[ct_subtotal],

			CASE WHEN sd.sd_isInBalance = 'true' THEN
				convert(decimal(18,2),round(ct.ct_total - ct.ct_adjust,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END		[ct_total],

			ct.ct_discount,
			ct.ct_taxes,
			ct.curr_id_transaction,
			ct.hacc_transaction,
			ct.disc_id,

-- -------------------------------------
			-- 19
			CASE WHEN sd.sd_isInBalance = 'true' THEN
				CONVERT (DECIMAL (18,2),ROUND((ct.ct_ATotal - isnull(ct.ct_AAdjust,0)),@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN 0 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN 0 ELSE 1 END	END
				ELSE 0
			END		[ct_ATotal],
			-- 20
			CASE WHEN sd.sd_isInBalance = 'true' THEN
				CONVERT (DECIMAL (18,2),ROUND((ct.ct_ATotal - isnull(ct.ct_AAdjust,0)),@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 0 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 0 END	END
				ELSE 0
			END		[ct_Credits],
-- -------------------------------------

			-- 21
			CASE WHEN sd.sd_isInBalance = 'true' THEN
				CONVERT (DECIMAL (18,2),ROUND (ct.ct_ABalance	,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END 	[ct_ABalance],
			CONVERT( decimal(19,2),0) [Balance],

			ct.ct_ACurrency,


			--=================================================================================================================
			-- Ref: #4
			CASE WHEN ct.ct_ACurrency <> ct.curr_id_transaction
					THEN ct.ct_ACurrencyExchange
					ELSE ct.ct_curr_IdExchange
				END	[ct_ACurrencyExchange],
			--=================================================================================================================


			CASE WHEN sd.sd_isInBalance = 'true' THEN
					CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * @current_exchange,@d)) *
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END [branch_ACurrency],



			--=================================================================================================================
			-- Referencia: #1
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					CONVERT(DECIMAL(18,2),round(ct.ct_ABalance / dbo.fnNoZDiv(ct.ct_ACurrencyExchange),@d)) *				--Referencia: #3
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END [doc_ACurrencyExchange],


			CONVERT(VARCHAR,
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					--CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d))				--Ref: #2
					CONVERT(DECIMAL(18,2),round(
						dbo.fnGetExchange2(@comp_id,ct.ct_ABalance,ct.ct_ACurrency,ct.curr_id4dfExchange,	--Ref: #2
							ct.curr_id4dfExchange,ct.curr_id_transaction,ct.ct_dfExchange,'false'),@d))		--Ref: #2
					*
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END)
			+ ' (' + ltrim(rtrim(tc.curr_symbol)) + ')'
					[doc_dfExchange],
			--=================================================================================================================



			--=================================================================================================================
			-- Referencia: #5
			CONVERT(VARCHAR,
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					--CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d))				--Ref: #2
					CONVERT(DECIMAL(18,2),round(
						dbo.fnGetExchange2(@comp_id,ct.ct_ATotal,ct.ct_ACurrency,ct.curr_id4dfExchange,	--Ref: #2
							ct.curr_id4dfExchange,ct.curr_id_transaction,ct.ct_dfExchange,'false'),@d))		--Ref: #2
					*
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END)
			+ ' (' + ltrim(rtrim(tc.curr_symbol)) + ')'
					[ct_A_Total_dfExchange],
			--=================================================================================================================



			ct.df_id,
			ct.dl_id,
			ct.st_id,
			ct.sd_id,
			ct.puco_id,
			ct.sm_id,
			sm.sm_name,
			tst.st_desc,

			ct.ct_CompanyCurrency,
			ct.ct_Branch2CompanyCurrencyExchange,
			ct.ct_adjust,
			--ct.ct_aadjust,

			cb.custb_name,	--REF:#1
			ct.ct_cd,		--REF:#1

			us.user_lastname + ', ' + user_firstname														[user_name],
			convert(varchar,IsNull(ct.ct_soh_bra_id,0)) + '-' + convert(varchar,IsNull(ct.ct_soh_id,0))		[soh_id_fromGenerated],
			convert(varchar,ct.ct_transaction) + '-' + convert(varchar,ct.sd_id)							[ID]


	INTO	#tmpData


	FROM 	dbo.tbCommercialTransactions					ct

			LEFT JOIN vwCommercialTransactions_forSales		vctfs
			ON	vctfs.comp_id			=	ct.comp_id
			AND vctfs.bra_id			=	ct.bra_id
			AND vctfs.ct_transaction	=	ct.ct_transaction
			AND vctfs.cust_id			=	ct.cust_id
			AND @ispurchase				=	'False'

			LEFT JOIN vwCommercialTransactions_forPurchase	vctfp
			ON	vctfp.comp_id			=	ct.comp_id
			AND vctfp.bra_id			=	ct.bra_id
			AND vctfp.ct_transaction	=	ct.ct_transaction
			AND vctfp.supp_id			=	ct.supp_id
			AND @ispurchase				=	'True'

			LEFT JOIN dbo.tbBranch							bra
			ON	bra.comp_id				=	ct.comp_id
			AND bra.bra_id				=	ct.bra_id
			AND bra.curr_id				=	@curr_id_branch		--TN : 621

			LEFT JOIN dbo.tbSalesman						sm
			on	sm.sm_id				=	ct.sm_id
			and	ct.comp_id				=	sm.comp_id

			left join dbo.tbUser							us
			on		us.user_id			=	ct.user_id

			left join dbo.tbCustomerBranch					cb
			on		cb.comp_id			=	ct.comp_id
			and		cb.cust_id			=	ct.cust_id
			and		cb.cb_id			=	ct.cb_id

			left join dbo.tbsysDocuments					sd
			on		sd.sd_id			=	ct.sd_id
			and		sd.sd_isPurchase	=	@ispurchase

			LEFT JOIN dbo.tbSalesTerms						tst
			ON		tst.comp_id			=	ct.comp_id
			AND		tst.st_id			=	ct.st_id

			LEFT JOIN #tmpIT								tit
			ON		tit.comp_id			=	ct.comp_id
			AND		tit.bra_id			=	ct.bra_id
			AND		tit.ct_transaction	=	ct.ct_transaction

			LEFT JOIN #tmpAPP								app
			ON		app.comp_id			=	ct.comp_id
			AND		app.bra_id			=	ct.bra_id
			AND		app.ct_transaction	=	ct.ct_transaction

			LEFT JOIN #tmpTCTN								tctn
			ON		tctn.comp_id		=	ct.comp_id
			AND		tctn.bra_id			=	ct.bra_id
			AND		tctn.ct_transaction	=	ct.ct_transaction

			LEFT JOIN #tmpRetentions						ret
			ON		ret.ct_transaction	=	ct.ct_transaction

			LEFT JOIN tbsysCurrency							tc
			ON		tc.curr_id			=	ct.curr_id4dfExchange --ct.curr_id4Exchange

			-- =========================================================
			-- TN : 621
			INNER JOIN tbUsers4BranchFilter				vubf
			ON	vubf.comp_id		=	ct.comp_id
			AND vubf.bra_id			=	bra.bra_id
			AND vubf.[user_id]		=	@user_id
			-- =========================================================


	where	ct.comp_id			=	@comp_id
	AND		(@bra_id  = -1 or ct.bra_id	=	@bra_id)
	and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or
			 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))

-- MOS, se pasa a temporal
--	and		ct.ct_date			between		@datefrom		and		@dateto
--	and		ct.ct_payDate		between		@paydatefrom	and		@paydateto

	--si se seleccionan sólo facturas trae sólo las que tienen ítems cargados
	and     (
			 (@sd_id	= -1)																								OR
			 (@sd_id	= 1			AND EXISTS		(SELECT 1 FROM [tbItemTransactions] WHERE comp_id = ct.[comp_id]
														AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])) OR
			 (@sd_id	= -2		AND ct.sd_id IN (SELECT sd_id FROM tbsysDocuments td WHERE td.sd_isInBalance = 'true')) OR
			 (@sd_id	= 2			AND ct.sd_id IN (2,52)) OR
			 (ct.sd_id	= @sd_id	AND @sd_id > 1)
			)

	and		ct.ct_docNumber			<> ''
	AND		ct.sd_id				<>	301


	order by ct.ct_date, ct.ct_transaction

	-- ------------------------------------------
	-- Recalculo del saldo acumulado
	-- ------------------------------------------
	DECLARE @decBalance AS DECIMAL(19,4)
	SET @decBalance = 0;

	DECLARE @tblTmp AS TABLE(	ct_transaction int,
								ct_ATotal DECIMAL(19,6),
								ct_Credits DECIMAL(19,6),
								ct_AAdjust DECIMAL(19,6),
								balance DECIMAL(19,6),
								sd_id int)

	INSERT INTO  @tblTmp (ct_transaction,ct_ATotal,ct_Credits,ct_AAdjust,balance,sd_id)
		SELECT				tmp.ct_transaction,
							tmp.ct_ATotal ,
							tmp.ct_Credits ,
							IsNull(tct.ct_AAdjust,0) ,
							balance,
							tct.sd_id
						FROM #tmpData tmp
						INNER JOIN tbCommercialTransactions tct
						ON tct.ct_transaction = tmp.ct_transaction
						ORDER BY tmp.ct_date, tmp.ct_transaction

		UPDATE @tblTmp
				SET @decBalance = (@decBalance +
					CASE
						WHEN sd_id > 100  and sd_id < 150 THEN (ct_ATotal + ct_Credits  /*-IsNull(ct_AAdjust,0)*/ )
						WHEN sd_id < 100  and sd_id < 50  THEN (ct_ATotal + ct_Credits  /*-IsNull(ct_AAdjust,0)*/ )
						ELSE 0
					END
								   ),
				Balance = Balance + @decBalance

		UPDATE #tmpData
			SET Balance = tmp1.balance
		FROM #tmpData	tmp
		INNER JOIN @tblTmp tmp1
			ON tmp1.ct_transaction = tmp.ct_transaction


	SELECT *
		FROM #tmpData ct
	WHERE 	ct.ct_date			between		@datefrom		and		@dateto
		and	ct.ct_payDate		between		@paydatefrom	and		@paydateto
	ORDER BY ct.ct_date, ct.ct_transaction

	/****************************************************************************************************/


END
GO


-- Copiar el contenido de spCommercialTransactions_getDataByFilters y que solo retorne los campos necesarios

CREATE PROCEDURE [dbo].[spCommercialTransactions_getDataByFilters4FixAccount]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@selection_id		INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@paydatefrom		DATETIME,
	@paydateto			DATETIME,
	@sd_id				INT,
	@ispurchase			BIT,
	@user_id			INT,
	@bra_id_user		INT
)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	/********************************************************************************************************
	si @ispurchase es True significa que la consulta está relacionada a una compra por lo tanto
	se debe considerar el @selection_id como proveedor o sea supp_id, si @ispurchase es False
	significa que la consulta está relacionada a una venta, en éste caso se debe considerar el
	@selection_id como cliente o sea cust_id
	*********************************************************************************************************/




-- -----------------------------------------------------------
-- Testing
-- -----------------------------------------------------------
/*
	declare 	@comp_id			int,
				@lang_id			int,
				@bra_id				int,
				@selection_id		int,
				@datefrom			datetime,
				@dateto				datetime,
				@paydatefrom		datetime,
				@paydateto			datetime,
				@sd_id				int,
				@ispurchase			bit,
				@user_id			int,
				@bra_id_user		INT

	select		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@selection_id		= 694,
				@datefrom			= convert(datetime,'2000-01-01'),
				@dateto				= convert(datetime,'9999-12-31'),
				@paydatefrom		= convert(datetime,'2000-01-01'),
				@paydateto			= convert(datetime,'9999-12-31'),
				@sd_id				= -2,
				@ispurchase			= 'True',
				@user_id			= 1,
				@bra_id_user		= -1

IF NOT OBJECT_ID('tempdb.dbo.#tmpIT')				IS NULL DROP TABLE #tmpIT
IF NOT OBJECT_ID('tempdb.dbo.#tmpAPP')				IS NULL DROP TABLE #tmpAPP
IF NOT OBJECT_ID('tempdb.dbo.#tmpTCTN')				IS NULL DROP TABLE #tmpTCTN
IF NOT OBJECT_ID('tempdb.dbo.#tmpRetentions')		IS NULL DROP TABLE #tmpRetentions
IF NOT OBJECT_ID('tempdb.dbo.#tmpData')				IS NULL DROP TABLE #tmpData
*/
-- -----------------------------------------------------------


	-- Fantastica idea de poner en este nombre de variable la cantidad de decimales a redondear.
	-- Quien se IMAGINA que quiere decir @d?
	declare @d int
	set		@d = 2


	-- ---------------------------------------------------------------
	-- Se usa para ascelerar un poco esto... ya que tarda DEMASIADOOOO
	-- ---------------------------------------------------------------
	DECLARE @tblSpeedQuery AS TABLE(ct_transaction INT primary key)
	IF @ispurchase = 'TRUE'
		BEGIN
			INSERT INTO @tblSpeedQuery
			(
				ct_transaction
			)
			SELECT tct.ct_transaction
				FROM tbCommercialTransactions tct					WITH (NOLOCK)
				INNER JOIN tbUsers4BranchFilter				vubf	WITH (NOLOCK)
					ON	vubf.comp_id		=	tct.comp_id
					AND vubf.bra_id			=	tct.bra_id
					AND vubf.[user_id]		=	@user_id
				WHERE tct.supp_id = @selection_id
		END
	ELSE IF @ispurchase = 'False'
		BEGIN
			INSERT INTO @tblSpeedQuery
			(
				ct_transaction
			)
			SELECT tct.ct_transaction
				FROM tbCommercialTransactions tct					WITH (NOLOCK)
				INNER JOIN tbUsers4BranchFilter				vubf	WITH (NOLOCK)
					ON	vubf.comp_id		=	tct.comp_id
					AND vubf.bra_id			=	tct.bra_id
					AND vubf.[user_id]		=	@user_id
				WHERE tct.cust_id = @selection_id
		END
	-- ---------------------------------------------------------------



	/****************************************************************************************************/
	/*recuperar el cambio actual entre la moneda de la sucursal con respesto a la del cliente/proveedor */
	DECLARE	@current_exchange			DECIMAL(18,6),
			@curr_id_branch				INT,
			@curr_id_2					INT,
			@bra_PaymentSupp_Id			INT					--Parte:486


	SELECT	@curr_id_branch		= tb.curr_id,
			@bra_PaymentSupp_Id	= ISNULL(tb.bra_PaymentSupp_Id,-1)		--Parte:486
	FROM	tbBranch	tb				WITH (NOLOCK)
	WHERE	tb.comp_id	= @comp_id
	AND		tb.bra_id	= @bra_id



	IF @ispurchase = 'false'
		SELECT	@curr_id_2 =tc.curr_id
		FROM	tbCustomer tc			WITH (NOLOCK)
		WHERE	tc.comp_id = @comp_id AND tc.cust_id = @selection_id
	ELSE
		SELECT	@curr_id_2 = tc.curr_id
		FROM	tbSupplier tc			WITH (NOLOCK)
		WHERE	tc.comp_id = @comp_id AND tc.supp_id = @selection_id



	SELECT	@current_exchange = dbo.fnGetExchange(@comp_id, 1, @curr_id_2, @curr_id_branch, 0, 0, 'False')
	/****************************************************************************************************/
	--SELECT @curr_id_branch, @curr_id_2
	--SELECT * FROM tbsysCurrency tc




	/****************************************************************************************************/
	/* Agregamos horas para que tome el dia completo a las fechas hasta *********************************/
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,1)
	set	@paydateto	= dbo.fnGetEnd_or_BeginOfDate(@paydateto,1)
	--select @dateto, @paydateto
	/****************************************************************************************************/





	/****************************************************************************************************/
	/* Generacion de temporal para determinar si cada CommercialTransaction tiene items *****************/
	declare @bitBlockIT_TransOfOtherBranch BIT
	select @bitBlockIT_TransOfOtherBranch = isnull(tu.user_authorizationBlockIT_TransOfOtherBranch,'true')
	  from tbUser tu where tu.user_id = @user_id


-- ENFERMO MENTAL no podes ser un REVERENDO HIJO DE PUTA ASI !!!!!!!

--	SELECT	DISTINCT	tit.comp_id,	tit.bra_id,		tit.ct_transaction,		1	[value]
--	INTO	#tmpIT
--	FROM	dbo.tbItemTransactions						tit
--
--
--			INNER JOIN @tblSpeedQuery sq
--				ON sq.ct_transaction = tit.ct_transaction
--
--
--			INNER JOIN dbo.tbCommercialTransactions		ct
--			ON	ct.comp_id			=	tit.comp_id
--			AND ct.bra_id			=	tit.bra_id
--			AND ct.ct_transaction	=	tit.ct_transaction
--
--			-- =========================================================
--			-- TN : 621
--			INNER JOIN tbBranch							tb
--			ON	tb.comp_id			=	tit.comp_id
--			AND tb.curr_id			=	@curr_id_branch
--			AND tb.bra_id			=	tit.bra_id
--			-- =========================================================
--
--
--	WHERE	tit.comp_id				=	@comp_id
--	--AND	tit.bra_id				=	@bra_id		-- TN : 621
--	--AND 	((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or **88
--	--		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
--	AND		ct.sd_id				<>	301
--
--	and		(
--				--si está en true debe bloquear entonces solo habilita las que tengan misma sucursal --==STL
--				(@bitBlockIT_TransOfOtherBranch = 'true' and tit.bra_id = @bra_id )  or
--				(@bitBlockIT_TransOfOtherBranch = 'true' and tit.bra_id <> @bra_id AND ct.sd_id IN (2,3) )  or
--				(@bitBlockIT_TransOfOtherBranch = 'false')
--			)
--
--
--
--
--	--UNION
--
----	SELECT 	DISTINCT	vct.comp_id,	vct.bra_id,		vct.ct_transaction,		1	[value]
----	FROM 	vwCollection								vct
----
----			INNER JOIN @tblSpeedQuery SQ
----				ON sq.ct_transaction = vct.ct_transaction
----
----			inner join dbo.[tbCommercialTransactions]	ct
----			on	ct.[comp_id]		=	vct.comp_id
----			and ct.[bra_id]			=	vct.bra_id
----			and ct.[ct_transaction] =	vct.ct_transaction
----
----			-- =========================================================
----			-- TN : 621
----			INNER JOIN tbBranch							tb
----			ON	tb.comp_id			=	vct.comp_id
----			AND tb.curr_id			=	@curr_id_branch
----			AND tb.bra_id			=	vct.bra_id
----			-- =========================================================
----
----	WHERE	vct.comp_id				=	@comp_id
----	--AND	vct.bra_id				=	@bra_id		-- TN : 621
----	--AND 	((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or **88
----	--		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
----	AND		ct.sd_id				<>	301
--
--
--	UNION
--
--
--	SELECT	DISTINCT	tpcm.comp_id,	tpcm.bra_id,	tpcm.ct_transaction,	1 [value]
--	FROM	tbPurchaseConceptMovements					tpcm
--
--			INNER JOIN @tblSpeedQuery sq
--				ON sq.ct_transaction = tpcm.ct_transaction
--
--			INNER JOIN tbCommercialTransactions			tct
--			ON	tct.comp_id			=	tpcm.comp_id
--			AND tct.bra_id			=	tpcm.bra_id
--			AND tct.ct_transaction	=	tpcm.ct_transaction
--
--			-- =========================================================
--			-- TN : 621
--			INNER JOIN tbBranch							tb
--			ON	tb.comp_id			=	tpcm.comp_id
--			AND tb.curr_id			=	@curr_id_branch
--			AND tb.bra_id			=	tpcm.bra_id
--			-- =========================================================
--
--	WHERE	tpcm.comp_id			=	@comp_id
--	--AND	tpcm.bra_id				=	@bra_id		--TN : 621
--	--AND 	((@ispurchase = 'True'	AND (@selection_id = -1 or tct.supp_id = @selection_id)) or **88
--	--		 (@ispurchase = 'False'	AND (@selection_id = -1 or tct.cust_id = @selection_id)))
--
--	--SELECT * FROM #tmpIT
--	/****************************************************************************************************/



	/****************************************************************************************************/
	/****************************************************************************************************/
	SELECT	DISTINCT
			tctn.comp_id,
			tctn.bra_id,
			tctn.ct_transaction,
			1 [value]
	INTO	#tmpTCTN
	FROM	dbo.tbCommercialTransactionNotes			tctn					WITH (NOLOCK)


			INNER JOIN @tblSpeedQuery sq
				ON sq.ct_transaction = tctn.ct_transaction

			INNER JOIN dbo.tbCommercialTransactions		ct						WITH (NOLOCK)
			ON	ct.comp_id			= tctn.comp_id
			AND ct.bra_id			= tctn.bra_id
			AND ct.ct_transaction	= tctn.ct_transaction

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb						WITH (NOLOCK)
			ON	tb.comp_id			=	tctn.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	tctn.bra_id
			-- =========================================================

	WHERE	tctn.comp_id			=	@comp_id
	--AND	tctn.bra_id				=	@bra_id		--TN : 621
	AND		(len(rtrim(ltrim(tctn.ctn_note1))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note2))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note3))) > 0	OR
			len(rtrim(ltrim(tctn.ctn_note4))) > 0)
	--and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or **88
	--		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))
	AND		ct.sd_id				<>	301

	--SELECT * FROM #tmpTCTN
	/****************************************************************************************************/



	DECLARE @tblSysDocuments AS TABLE(sd_id				INT PRIMARY KEY,
								      sd_isInBalance	bit)
	INSERT INTO @tblSysDocuments	SELECT	td.sd_id,
											td.sd_isInBalance
										FROM tbsysDocuments td		WITH (NOLOCK)
	                            		--WHERE td.sd_isInBalance = 'True'






	/****************************************************************************************************/
	/* Genracion de temporal para determinar retenciones para cada CT ***********************************/
	SELECT	COUNT(*) [count],
			ttm.ct_transaction
	INTO	#tmpRetentions
	FROM	tbTaxMovements								ttm						WITH (NOLOCK)


			INNER JOIN @tblSpeedQuery sq
				ON sq.ct_transaction = ttm.ct_transaction


			INNER JOIN tbTaxName						ttn						WITH (NOLOCK)
			ON	ttn.comp_id			= ttm.comp_id
			AND ttn.tax_id			= ttm.tax_id

			INNER JOIN vwsysTaxClassALL_Retentions		vtcar					WITH (NOLOCK)
			ON	vtcar.tax_class		= ttn.tax_class

			-- =========================================================
			-- TN : 621
			INNER JOIN tbBranch							tb
			ON	tb.comp_id			=	ttm.comp_id
			AND tb.curr_id			=	@curr_id_branch
			AND tb.bra_id			=	ttm.bra_id
			-- =========================================================

	WHERE	ttm.comp_id				= @comp_id
	--AND	ttm.bra_id				= @bra_id	--TN : 621
	AND		ttm.tm_total			> 0
	GROUP BY ttm.ct_transaction

	--SELECT * FROM #tmpRetentions ORDER BY 2
	/****************************************************************************************************/


	-- Para Compras, se fija cual es el proveedor para OTROS PAGOS
	DECLARE @supp_id4OtherPayments AS INT
	SELECT	@supp_id4OtherPayments = tb.bra_PaymentSupp_Id
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id




	/****************************************************************************************************/
	/****************************************************************************************************/
	-- REF *9988* en wfmCommercialTransactions
	--TENER EN CUENTA QUE SI SE AGREGAN COLUMNAS AL QUERY FINAL DE SP SE DEBERÁ MODIFICAR EL CÓDIGO DE LA
	--PÁGINA EN LA RUTINA grdData_RowDataBound PARA EL CASO EN QUE SEA UNA ROW DEL TIPO Case DataControlRowType.Footer
	--Y MODIFICAR LOS COLUMNS SPANS CORRESPONDIENTES PARA QUE LOS TOTALES DE LA GRILLA COINCIDAN CON EL
	--NUEVO ENCOLUMNAMIENTO
	--TAMBIEN SE DEBRÁN VERIFICAR EN EL CODIGO DE LA PÁGINA EN EL grdData_RowDataBound TODOS LOS ÍNDICES
	--QUE SE VEAN AFECTADOS POR LA MODIFICACIÓN DE LAS COLUMNAS DUMMY PARA LOS BOTONES.

	/****************************************************************************************************/
	/****************************************************************************************************/

	select
			--ct.ct_ATotal ATotal,ct.ct_AAdjust AAdjust,ct.ct_ABalance ABalance,

			/*ISNULL(tit.value,0)*/	1	[1],


			--ISNULL(app.value,0)		[2],
			CASE WHEN EXISTS (	SELECT TOP 1 1
									FROM tbApplication ta	WITH (NOLOCK)
									WHERE ta.comp_id = ct.comp_id	AND
										 (ta.ct_transaction_Source = ct.ct_transaction OR
										  ta.ct_transaction_destiny = ct.ct_transaction))
					THEN 1
					ELSE 0
			END						[2],


			ISNULL(tctn.value,0)	[3],
			' '						[4],
			ISNULL(ret.[count],0)	[5],

			-- --------------------------------------------------------------------------------------
			-- Boton de Anulacion
			-- --------------------------------------------------------------------------------------
			CASE

				WHEN
					-- =====================================================================================================
					-- parte: 746
					(
						@ispurchase = 'True'	AND
						(ct.ct_taxDate  BETWEEN	isnull(bra.bra_PurDoc_MinTaxDate,GETDATE()) AND
													isnull(bra.bra_PurDoc_MaxTaxDate,GETDATE()))
												AND
						(ct.sd_id IN (106, 103, 104))
					)
					AND
					-- =====================================================================================================
					(
						(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
						(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
					)
					THEN 1  --NC, ND de proveedores --habilita la anulación



				WHEN
					-- =====================================================================================================
					-- FACTURA DE COMPRA o DESPACHO DE IMPORTACION 02-2013
					(
						@ispurchase	= 'True'									AND
						(ct.ct_taxDate  BETWEEN	ISNULL(bra.bra_PurDoc_MinTaxDate,GETDATE()-100) AND
												ISNULL(bra.bra_PurDoc_MaxTaxDate,GETDATE()+100))
																				AND
						(ct.sd_id = 101 OR ct.sd_id = 130	)					AND
						(
							(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
							(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
						)														AND
						--NOT EXISTS (SELECT TOP 1 1 FROM tbItemSerials tis WHERE tis.comp_id = ct.comp_id
						--			AND tis.ct_transaction = ct.ct_transaction AND tis.is_available = 'False')
						NOT EXISTS (SELECT TOP 1 1 FROM tbItemSerials tis	WITH (NOLOCK)
									WHERE	tis.comp_id					= ct.comp_id
									AND		tis.ct_transaction			= ct.ct_transaction
									AND		(
												tis.is_available			= 'True'
											or	isnull(tis.is_serial,'')	<> ''
											)
									)
					)
					THEN 4  --FC de proveedores --habilita la anulación
					-- =====================================================================================================


						-- ---------------------------------------------------------------------------------
				WHEN	-- RECIBO DE COBRANZA (Si no esta aplicado y los valores figuran como disponibles)
						-- ---------------------------------------------------------------------------------
			 		 ct.sd_id IN (6, 13)
					 THEN
							CASE
								WHEN NOT (
											(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
											(ct.ct_ATotal                           = ct.ct_ABalance) or
											(ABS(ct.ct_ATotal - ct.ct_ABalance) <= 0.01 ) or
											(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
				 						 )																		THEN 190
								WHEN EXISTS(SELECT 1
												FROM tbCheckPortfolio tcp1	WITH (NOLOCK)
			 									WHERE	tcp1.comp_id			= ct.comp_id
			 										AND tcp1.ct_transaction		= ct.ct_transaction
			 										and tcp1.chp_isavailable	= 'False')						THEN 191
																												ELSE 2
							END

					  -- ---------------------------------------------------------------------------------
				WHEN  -- Orden de Pago
					  -- ---------------------------------------------------------------------------------
			 	      ct.sd_id IN (106)
					  THEN --2  --OP a proveedores, --habilita la anulación
							CASE
								WHEN not	(
												(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) = ct.ct_ABalance) or
												(ct.ct_ATotal                           = ct.ct_ABalance) or
												(ABS(ct.ct_ATotal - ct.ct_ABalance) <= 0.01 ) or
												(ABS(ct.ct_ATotal - isnull(ct.ct_AAdjust,0) - ct.ct_ABalance) <= 0.01)
											)
									 AND         @supp_id4OtherPayments <> ct.supp_id
																												THEN 195
								WHEN @supp_id4OtherPayments = ct.supp_id										THEN 2
																												ELSE 2
							END

				WHEN
					(
			 			 ct.sd_id IN (6,13,106) and
			 			 @bra_PaymentSupp_Id = ct.supp_id
					) THEN 2	--Parte:486 --habilita la anulación


				-- =====================================================================================================
				-- Parte: 784
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions]	WITH (NOLOCK) WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf	WITH (NOLOCK) WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND EXISTS (SELECT 1 FROM tbItemTransactions tit2	WITH (NOLOCK) WHERE tit2.comp_id = ct.comp_id
													AND tit2.bra_id = ct.bra_id AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
									 AND ISNULL(ct.ct_isCancelled,'false') = 'false'
					) THEN 3 --RM de clientes que tengan algún registro en tbItemsTransactions y
							 --que el remito tenga asignado un documento de rechazo y
							 --que el remito no tenga algún artículo facturado y
							 --que ya no haya sido anulado anteriormente

				WHEN
					(
						ct.sd_id = 2 AND NOT EXISTS (SELECT 1 FROM [tbItemTransactions]	WITH (NOLOCK) WHERE comp_id = ct.[comp_id]
													AND bra_id = ct.[bra_id] AND ct_transaction = ct.[ct_transaction])
					) THEN 94 --RM de clientes NO tiene artículos asignados
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions] WITH (NOLOCK) WHERE comp_id = ct.[comp_id]
													AND ct_transaction = ct.[ct_transaction])
									 AND NOT EXISTS (SELECT 1 FROM tbDocumentsFile tdf	WITH (NOLOCK)WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
					) THEN 95 --RM de clientes NO tiene asigando un documento de rechazo
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions]	WITH (NOLOCK) WHERE comp_id = ct.[comp_id]
													 AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf	WITH (NOLOCK)WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND NOT EXISTS (SELECT 1 FROM tbItemTransactions tit2 WHERE tit2.comp_id = ct.comp_id
													AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
					) THEN 96 --RM de clientes YA tiene algún artículo facturado
				WHEN
					(
						ct.sd_id = 2 AND EXISTS (SELECT 1 FROM [tbItemTransactions]	WITH (NOLOCK) WHERE comp_id = ct.[comp_id]
													AND ct_transaction = ct.[ct_transaction])
									 AND EXISTS (SELECT 1 FROM tbDocumentsFile tdf	WITH (NOLOCK) WHERE tdf.comp_id = ct.comp_id
													AND tdf.bra_id = ct.bra_id AND tdf.df_id = ct.df_id
													AND NOT tdf.df_id4PLAnnulment IS NULL)
									 AND EXISTS (SELECT 1 FROM tbItemTransactions tit2	WITH (NOLOCK)	WHERE tit2.comp_id = ct.comp_id
													AND tit2.ct_transaction =ct.ct_transaction
													AND tit2.it_packingInvoicePendOriginal = tit2.it_packingInvoicePend)
									 AND ISNULL(ct.ct_isCancelled,'false') = 'true'
					) THEN 93 --RM de clientes YA ha sido anulado anteriormente


				WHEN
					(
						ct.sd_id = 52
					) THEN 92 --No se permiten anular la anulación de Remitos


				WHEN
					(
						ct.sd_id = 102
					) THEN 3 --RM de proveedores
				-- =====================================================================================================


				ELSE	0 --deshabilita la anulación
			END						[6],
			-- --------------------------------------------------------------------------------------


			' '						[7], --Parte 631
			' '						[8], --Parte 631


			ct.comp_id,
			ct.bra_id,
			sd.sd_desc,
			ct.ct_transaction,
			--'(' + dbo.fnStrPADL(	CONVERT(NVARCHAR(20),IsNull(ct.df_id,0)),3,'0')	+ ') ' +
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.[ct_transaction]) 	[doc_number],
			ct.ct_docNumber,
			ct.ct_date,
			ct.ct_taxDate,
			ct.ct_payDate,
			ct.supp_id,
			ct.cust_id,
			ct.cb_id,

			--cb.custb_name,	--REF:#1
			ct.user_id,
			--ct.ct_cd,			--REF:#1

			CASE WHEN sd.sd_isInBalance = 'true' THEN
				convert(decimal(18,2),round(ct.ct_subtotal	,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END		[ct_subtotal],

			CASE WHEN sd.sd_isInBalance = 'true' THEN
				convert(decimal(18,2),round(ct.ct_total - ct.ct_adjust,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END		[ct_total],

			ct.ct_discount,
			ct.ct_taxes,
			ct.curr_id_transaction,
			ct.hacc_transaction,
			ct.disc_id,

-- -------------------------------------
			-- 19
			CASE	WHEN sd.sd_isInBalance = 'true' THEN
															CONVERT (DECIMAL (18,2),ROUND((ct.ct_ATotal - isnull(ct.ct_AAdjust,0)),@d)) *
															CASE
																WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN 0 ELSE 1 END
																ELSE						   CASE WHEN vctfs.sd_isCredit = 'True' THEN 0 ELSE 1 END
															END
					WHEN sd.sd_id IN (44) THEN ct.ct_ATotal * CASE WHEN vctfp.sd_isCredit = 'True' THEN 0 ELSE 1 END
					ELSE 0
			END		[ct_ATotal],
			-- 20
			CASE	WHEN sd.sd_isInBalance = 'true' THEN
															CONVERT (DECIMAL (18,2),ROUND((ct.ct_ATotal - isnull(ct.ct_AAdjust,0)),@d)) *
															CASE
																WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 0 END
																ELSE						   CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 0 END
															END
					WHEN sd.sd_id IN (43) THEN ct.ct_ATotal * CASE WHEN vctfp.sd_isCredit = 'True' THEN 0 ELSE 1 END
					ELSE 0
			END		[ct_Credits],
-- -------------------------------------

			-- 21
			CASE WHEN sd.sd_isInBalance = 'true' THEN
				CONVERT (DECIMAL (18,2),ROUND (ct.ct_ABalance	,@d)) *
					CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
					ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
				ELSE 0
			END 	[ct_ABalance],
			CONVERT( decimal(19,2),0) [Balance],


			ct.ct_ACurrency,


			--=================================================================================================================
			-- Ref: #4
			CASE WHEN ct.ct_ACurrency <> ct.curr_id_transaction
					THEN ct.ct_ACurrencyExchange
					ELSE ct.ct_curr_IdExchange
				END	[ct_ACurrencyExchange],
			--=================================================================================================================


			CASE WHEN sd.sd_isInBalance = 'true' THEN
					CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * @current_exchange,@d)) *
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END [branch_ACurrency],



			--=================================================================================================================
			-- Referencia: #1
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					CONVERT(DECIMAL(18,2),round(ct.ct_ABalance / dbo.fnNoZDiv(ct.ct_ACurrencyExchange),@d)) *				--Referencia: #3
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END [doc_ACurrencyExchange],


			CONVERT(VARCHAR,
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					--CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d))				--Ref: #2
					CONVERT(DECIMAL(18,2),round(
						dbo.fnGetExchange2(@comp_id,ct.ct_ABalance,ct.ct_ACurrency,ct.curr_id4dfExchange,	--Ref: #2
							ct.curr_id4dfExchange,ct.curr_id_transaction,ct.ct_dfExchange,'false'),@d))		--Ref: #2
					*
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END)
			+ ' (' + ltrim(rtrim(tc.curr_symbol)) + ')'
					[doc_dfExchange],
			--=================================================================================================================



			--=================================================================================================================
			-- Referencia: #5
			CONVERT(VARCHAR,
			CASE WHEN sd.sd_isInBalance = 'true' THEN
					--CONVERT(DECIMAL(18,2),round(ct.ct_ABalance * ct.ct_dfExchange,@d))				--Ref: #2
					CONVERT(DECIMAL(18,2),round(
						dbo.fnGetExchange2(@comp_id,ct.ct_ATotal,ct.ct_ACurrency,ct.curr_id4dfExchange,	--Ref: #2
							ct.curr_id4dfExchange,ct.curr_id_transaction,ct.ct_dfExchange,'false'),@d))		--Ref: #2
					*
						CASE WHEN @ispurchase = 'True' THEN CASE WHEN vctfp.sd_isCredit = 'True' THEN -1 ELSE 1 END
							ELSE								CASE WHEN vctfs.sd_isCredit = 'True' THEN -1 ELSE 1 END	END
					ELSE  CONVERT(DECIMAL(18,2), 0)
				END)
			+ ' (' + ltrim(rtrim(tc.curr_symbol)) + ')'
					[ct_A_Total_dfExchange],
			--=================================================================================================================



			ct.df_id,
			ct.dl_id,
			ct.st_id,
			ct.sd_id,
			ct.puco_id,
			ct.sm_id,
			sm.sm_name,
			tst.st_desc,

			td3.dl_name,

			ct.ct_CompanyCurrency,
			ct.ct_Branch2CompanyCurrencyExchange,
			ct.ct_adjust,
			--ct.ct_aadjust,

			bra.bra_desc + ' -> ' + IsNull(cb.custb_name,'')				[custb_name],	--REF:#1
			ct.ct_cd,		--REF:#1

			dbo.fnSaleOrderHistory_GetUserName(ct.comp_id,ct.ct_soh_bra_id,ct.ct_soh_id) + ' --> ' + us.user_lastname + ', ' + user_firstname  														[user_name],

			tdf.df_desc + ' -> (' +
			CASE
				WHEN ct.ct_soh_id IS NULL	THEN ''
				WHEN ct.ct_soh_id = -1		THEN ''
				ELSE convert(varchar,IsNull(ct.ct_soh_bra_id,0)) + '-' + convert(varchar,IsNull(ct.ct_soh_id,0))
			END
		 		+')'	[soh_id_fromGenerated],

			convert(varchar,ct.ct_transaction) + '-' + convert(varchar,ct.sd_id)							[ID]


	INTO	#tmpData


	FROM 	dbo.tbCommercialTransactions					ct						WITH (NOLOCK)


			INNER JOIN @tblSpeedQuery sq
				ON sq.ct_transaction = ct.ct_transaction


			INNER JOIN @tblSysDocuments td2
				ON td2.sd_id = ct.sd_id


			LEFT JOIN vwCommercialTransactions_forSales		vctfs					WITH (NOLOCK)
			ON	vctfs.comp_id			=	ct.comp_id
			AND vctfs.ct_transaction	=	ct.ct_transaction
			AND vctfs.cust_id			=	ct.cust_id
			AND @ispurchase				=	'False'

			LEFT JOIN vwCommercialTransactions_forPurchase	vctfp					WITH (NOLOCK)
			ON	vctfp.comp_id			=	ct.comp_id
			--AND vctfp.bra_id			=	ct.bra_id
			AND vctfp.ct_transaction	=	ct.ct_transaction
			AND vctfp.supp_id			=	ct.supp_id
			AND @ispurchase				=	'True'

			LEFT JOIN dbo.tbBranch							bra						WITH (NOLOCK)
			ON	bra.comp_id				=	ct.comp_id
			AND bra.bra_id				=	ct.bra_id
			AND bra.curr_id				=	@curr_id_branch		--TN : 621

			LEFT JOIN dbo.tbSalesman						sm						WITH (NOLOCK)
			on	sm.sm_id				=	ct.sm_id
			and	ct.comp_id				=	sm.comp_id

			left join dbo.tbUser							us						WITH (NOLOCK)
			on		us.user_id			=	ct.user_id

			left join dbo.tbCustomerBranch					cb						WITH (NOLOCK)
			on		cb.comp_id			=	ct.comp_id
			and		cb.cust_id			=	ct.cust_id
			and		cb.cb_id			=	ct.cb_id

			left join dbo.tbsysDocuments					sd						WITH (NOLOCK)
			on		sd.sd_id			=	ct.sd_id
			and		sd.sd_isPurchase	=	@ispurchase

			LEFT JOIN dbo.tbSalesTerms						tst						WITH (NOLOCK)
			ON		tst.comp_id			=	ct.comp_id
			AND		tst.st_id			=	ct.st_id

--			LEFT JOIN #tmpIT								tit
--			ON		tit.comp_id			=	ct.comp_id
--			--AND		tit.bra_id			=	ct.bra_id
--			AND		tit.ct_transaction	=	ct.ct_transaction

			/*
			LEFT JOIN #tmpAPP								app
			ON		app.comp_id			=	ct.comp_id
			--AND		app.bra_id			=	ct.bra_id
			AND		app.ct_transaction	=	ct.ct_transaction
			*/

			LEFT JOIN #tmpTCTN								tctn					WITH (NOLOCK)
			ON		tctn.comp_id		=	ct.comp_id
			--AND		tctn.bra_id			=	ct.bra_id
			AND		tctn.ct_transaction	=	ct.ct_transaction

			LEFT JOIN #tmpRetentions						ret						WITH (NOLOCK)
			ON		ret.ct_transaction	=	ct.ct_transaction

			LEFT JOIN tbsysCurrency							tc
			ON		tc.curr_id			=	ct.curr_id4dfExchange --ct.curr_id4Exchange


			LEFT JOIN tbDocumentsFile tdf											WITH (NOLOCK)
				ON	tdf.comp_id = ct.comp_id	AND
					tdf.bra_id	= ct.bra_id		AND
					tdf.df_id	= ct.df_id

			LEFT JOIN tbDelivery td3												WITH (NOLOCK)
				ON	td3.comp_id = ct.comp_id AND
					td3.dl_id	= ct.dl_id

			-- =========================================================
			-- TN : 621
			--INNER JOIN vista				vubf
			--ON	vubf.comp_id		=	ct.comp_id
			--AND vubf.bra_id			=	bra.bra_id
			--AND vubf.[user_id]		=	@user_id
			-- =========================================================


	where	ct.comp_id			=	@comp_id
	--and		ct.bra_id			=	@bra_id		--TN : 621
	--and		((@ispurchase = 'True'	and (@selection_id = -1 or ct.supp_id = @selection_id)) or **88
	--		 (@ispurchase = 'False'	and (@selection_id = -1 or ct.cust_id = @selection_id)))


	--si se seleccionan sólo facturas trae sólo las que tienen ítems cargados
	and     (
			 (@sd_id	= -1)

			 OR

			 (@sd_id	= 1			AND EXISTS		(	SELECT 1
															FROM [tbItemTransactions]	WITH (NOLOCK)
															WHERE	comp_id			= ct.[comp_id]
																--AND bra_id			= ct.[bra_id]
																AND ct_transaction	= ct.[ct_transaction])
			 )

			 OR

			 (@sd_id	= -2		AND   td2.sd_isInBalance='True' --   ct.sd_id IN (SELECT sd_id FROM tbsysDocuments td WHERE td.sd_isInBalance = 'true')
			 )

			 OR

			 (@sd_id	= 2			AND ct.sd_id IN (2,52))

			 OR

			 (ct.sd_id	= @sd_id	AND @sd_id > 1)
			)

	and		ct.ct_docNumber			<> ''
	AND		ct.sd_id				<>	301
	AND		(@bra_id_user			= -1 OR ct.bra_id = @bra_id_user)


--	order by ct.ct_date, ct.ct_transaction   No hace falta, se hace un Inner Join abajo y se vuelkve a ordenar.  hace que tarde mucho





	-- ------------------------------------------
	-- Recalculo del saldo acumulado
	-- ------------------------------------------
	DECLARE @decBalance AS DECIMAL(19,4)
	SET @decBalance = 0;

	DECLARE @tblTmp AS TABLE(	ct_transaction int,
								ct_ATotal DECIMAL(19,6),
								ct_Credits DECIMAL(19,6),
								ct_AAdjust DECIMAL(19,6),
								balance DECIMAL(19,6),
								sd_id int)

	INSERT INTO  @tblTmp (ct_transaction,ct_ATotal,ct_Credits,ct_AAdjust,balance,sd_id)
		SELECT				tmp.ct_transaction,
							tmp.ct_ATotal ,
							tmp.ct_Credits ,
							IsNull(tct.ct_AAdjust,0) ,
							balance,
							tct.sd_id
						FROM #tmpData tmp	WITH (NOLOCK)
						INNER JOIN tbCommercialTransactions tct	WITH (NOLOCK)
						ON tct.ct_transaction = tmp.ct_transaction
						ORDER BY tmp.ct_date, tmp.ct_transaction

		UPDATE @tblTmp
				SET @decBalance = (@decBalance +
					CASE
						WHEN sd_id > 100  and sd_id < 150 THEN (ct_ATotal + ct_Credits  /*-IsNull(ct_AAdjust,0)*/ )
						WHEN sd_id < 100  and sd_id < 50  THEN (ct_ATotal + ct_Credits  /*-IsNull(ct_AAdjust,0)*/ )
						ELSE 0
					END
								   ),
				Balance = Balance + @decBalance

		UPDATE #tmpData
			SET Balance = tmp1.balance
		FROM #tmpData	tmp
		INNER JOIN @tblTmp tmp1
			ON tmp1.ct_transaction = tmp.ct_transaction


	SELECT ID,Balance,ct_ABalance
		FROM #tmpData ct	WITH (NOLOCK)
	WHERE 	ct.ct_date			between		@datefrom		and		@dateto
		and	ct.ct_payDate		between		@paydatefrom	and		@paydateto
	ORDER BY ct.ct_date, ct.ct_transaction

	/****************************************************************************************************/






--	SELECT 	isnull(sum([ct_ATotal]			),0)		[ct_ATotal],
--			isnull(sum([ct_ABalance]		),0)		[ct_ABalance],
--			@current_exchange							[current_exchange],
--			isnull(sum([branch_ACurrency]	),0)		[branch_ACurrency],
--			isnull(sum([ct_Credits]			),0)		[ct_Credits]
--	FROM	#tmpData		WITH (NOLOCK)
--
--			INNER JOIN tbsysDocuments td		WITH (NOLOCK)
--			ON	td.sd_id			= #tmpData.sd_id
--			AND td.sd_isInBalance	= 'True'


	DELETE FROM #tmpData
	DROP TABLE #tmpData







END
GO


CREATE PROCEDURE [dbo].[spCommercialTransactions_GetDataByFilters4Microsites]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@user_id	INT,
	@prof_id	INT,
	@ws_id		UNIQUEIDENTIFIER,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@cust_id	INT,
	@subcat_id	INT,
	@item_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------



		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@user_id	INT,
				@prof_id	INT,
				@ws_id		INT,
				@datefrom	DATETIME,
				@dateto		DATETIME,
				@cust_id	INT,
				@subcat_id	INT,
				@item_id	INT,
				@guid		UNIQUEIDENTIFIER

			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@user_id	= 119,
				@prof_id	= 1,
				@ws_id		= 1,
				@datefrom	= '',
				@dateto		= '',
				@cust_id	= -1,
				@subcat_id	= -1,
				@item_id	= -1,
				@guid		= '25892e17-80f6-415f-9c65-7395632f0223'
		*/
		-- ------------------------------------------------

		DECLARE
			 @lws_InternalId	INT
		SELECT
			@lws_InternalId			= twsin.ws_internalID
			FROM tbWebSiteII_Names				twsin
			WHERE	twsin.comp_id	= @comp_id	AND
					twsin.ws_id		= @ws_id


		SELECT
			' '																								[ ],	--UPDATE
			' '																								[ ],	-- RE IMPRESIÓN
			' '																								[ ],	--SELECT
			CASE
				WHEN tts.tmpGUID IS NULL THEN CONVERT(BIT,'False')
				ELSE CONVERT(BIT,'True')
			END																								[Is_Selected],
			ISNULL(twsin.ws_desc,'')																		[ws_desc],
			ISNULL(tc.cust_name,'')																			[cust_name],
			dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)			[Document],
			tc2.curr_symbol,
			tct.ct_total,
			tct.ct_date,
			ISNULL(tct.ws_isLiquidated,'False')																[ws_isLiquidated],
			ws_isLiquidatedCD,
			tct.ct_transaction																				[ID]
			FROM tbCommercialTransactions						tct		WITH(NOLOCK)
			INNER JOIN tbCustomer								tc		WITH(NOLOCK)
				ON	tc.comp_id			= tct.comp_id			AND
					tc.cust_id			= tct.cust_id
			INNER JOIN tbsysCurrency							tc2
				ON	tc2.curr_id			= tct.curr_id_transaction
			INNER JOIN tbWebSiteII_Names						twsin	WITH(NOLOCK)
				ON	twsin.comp_id		= tct.comp_id			AND
					twsin.ws_internalID = tct.ws_internalID
			LEFT JOIN tbTemporarySelection						tts		WITH(NOLOCK)
				ON	tts.tmpID			= tct.ct_transaction	AND
					tts.tmpGUID			= @guid
			WHERE	tct.comp_id = @comp_id												AND
					tct.ws_internalID					= @lws_InternalId				AND
					(@cust_id	= -1 OR tct.cust_id		= @cust_id)						AND
					tct	.ws_is4Liquidation				= 'True'						AND
					twsin.user_id4MicroSites			= @user_id						AND
					ISNULL(tct.ws_isLiquidatedCD,'')	BETWEEN @datefrom AND @dateto	AND
					tct.ct_date							BETWEEN @datefrom AND @dateto	AND
					CASE
						WHEN @subcat_id = -1 THEN	1
						WHEN @subcat_id >  0 AND EXISTS(
														SELECT TOP 1 1
															FROM tbItemTransactions				tit
															INNER JOIN	tbItem					ti
																ON	tit.comp_id = ti.comp_id	AND
																	tit.item_id = ti.item_id
															WHERE	tct.comp_id			= tct.comp_id			AND
																	tit.ct_transaction	= tct.ct_transaction	AND
																	ti.subcat_id		= @subcat_id) THEN 1
						ELSE						0
					END = 1																AND
					CASE
						WHEN @item_id = -1 THEN 1
						WHEN @item_id > 0 AND EXISTS(
													  SELECT TOP 1 1
													  FROM tbItemTransactions							tit
													  WHERE tit.comp_id			= tct.comp_id			AND
															tit.ct_transaction	= tct.ct_transaction	AND
															tit.item_id			= @item_id) THEN 1
						ELSE 0
					END = 1


	END


GO


CREATE PROCEDURE spCommercialTransactions_GetDataByFilters4Sales
(
	@comp_id		INT,
	@lang_id		INT,
	@custGuid		UNIQUEIDENTIFIER,
	@dateFrom		DATETIME,
	@dateTo			DATETIME,
	@dateVencFrom	DATETIME,
	@dateVencTo		DATETIME,
	@sd_id			INT,
	@user_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@custGuid		UNIQUEIDENTIFIER,
				@dateFrom		DATETIME,
				@dateTo			DATETIME,
				@dateVencFrom	DATETIME,
				@dateVencTo		DATETIME,
				@sd_id			INT

			SELECT
				@comp_id		= 1,
				@lang_id		= 2,
				@custGuid		= '7B370139-75C6-425A-B9CB-7C900057E31E',
				@dateFrom		= '2017-01-01',
				@dateTo			= '2017-12-31',
				@dateVencFrom	= '2017-01-01',
				@dateVencTo		= '2017-12-31',
				@sd_id			= -1
		*/
		-- -----------------------------------------------------


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Customers TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customers
			SELECT
				tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @custGuid     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customers
				SELECT
					tc.cust_id
					FROM tbCustomer tc
					WHERE tc.comp_id = @comp_id
			END
		-- -------------------------------------------------------------


		SET @dateFrom		= dbo.fnGetEnd_or_BeginOfDate(@dateFrom,0)
		SET @dateTo			= dbo.fnGetEnd_or_BeginOfDate(@dateTo,0)

		SET @dateVencFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateVencFrom,0)
		SET @dateVencTo		= dbo.fnGetEnd_or_BeginOfDate(@dateVencTo,0)


		SELECT
			' '																						[ ],	--MODIFICAR
			' '																						[ ],	--ENVIAR POR MAIL
			tc.cust_name,
			dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[Document],
			tct.ct_date,
			tct.ct_payDate,
			ISNULL(ts.sm_name,'')																	[sm_name],
			ISNULL(tst.st_desc,'')																	[st_desc],
			ISNULL(td.disc_desc,'')																	[disc_desc],
			CONVERT(VARCHAR,tct.ct_transaction) + '-' + CONVERT(VARCHAR,tct.sd_id)					[ID]
			FROM tbCommercialTransactions															tct			WITH(NOLOCK)
				INNER JOIN tbUsers4BranchFilter														tbu			WITH(NOLOCK)
				ON	tbu.comp_id				= tct.comp_id											AND
					tbu.bra_id				= tct.bra_id											AND
					tbu.[user_id]			= @user_id
				INNER JOIN vwCommercialTransactions_forSales										vctfs		WITH(NOLOCK)
				ON	vctfs.comp_id			= tct.comp_id											AND
					vctfs.ct_transaction	= tct.ct_transaction
				INNER JOIN @tblComplexFilter_Customers												tmp
				ON	tmp.cust_id				= tct.cust_id
				INNER JOIN tbCustomer																tc			WITH(NOLOCK)
				ON	tc.comp_id				= tct.comp_id											AND
					tc.cust_id				= tmp.cust_id
				LEFT JOIN tbSalesman																ts			WITH(NOLOCK)
				ON	ts.comp_id				= tct.comp_id											AND
					ts.sm_id				= tct.sm_id
				LEFT JOIN tbSalesTerms																tst			WITH(NOLOCK)
				ON	tst.comp_id				= tct.comp_id											AND
					tst.st_id				= tct.st_id
				LEFT JOIN tbDiscount																td			WITH(NOLOCK)
				ON	td.comp_id				= tct.comp_id											AND
					td.disc_id				= tct.disc_id
				INNER JOIN tbsysCurrency															tc2			WITH(NOLOCK)
				ON	tc2.curr_id				= tct.curr_id_transaction

			WHERE	tct.comp_id		= @comp_id														AND
					(tct.ct_Date	BETWEEN @dateFrom		AND @dateTo)							AND
					(tct.ct_payDate BETWEEN  @dateVencFrom	AND @dateVencTo)						AND
					(
						@sd_id		= -1			OR
						tct.sd_id	= @sd_id
					)


	END
GO



-- Log:
-- MOS 07-2024 x JFC: 22092
-- FORRADA 22217


-- -----------------------------------------------------
--
-- ATENCION: SOLO USAR con wfmDocumentsPrint !!!!!!!!
