--SELECT * FROM #tmpTaxes


	-- Si se ajusto algun centavo por redondeo, se re-ajusta
	DECLARE @decTMPAdjust AS DECIMAL(19,4)
	SET @decTMPAdjust		= 0
	SELECT @decTMPAdjust	= sum(SubTotalNoTax) FROM #tmpTaxes
	SET @decTMPAdjust		= ISNULL(@decTMPAdjust,0)
	IF @decTMPAdjust > 0 AND @decTMPAdjust < 0.06
		BEGIN
			Update #tmpTaxes Set	Subtotal = (Subtotal + SubTotalNoTax),
									SubTotalNoTax =  0
		END





