	-- --------------------------------------------------------------------------------------------------------------
	-- Calculo el total de Percepciones x Provincia en una nueva temporal.-
	-- --------------------------------------------------------------------------------------------------------------
	Create Table #tmpIBPerceptions
				(	ib  			 decimal (19,5) NOT NULL,
					tax_id			 decimal (19,5) NOT NULL,
					tax_text		 varchar (50)   NOT NULL,
					subtotal	     decimal (19,5) NOT NULL,
					[percentage]	 DECIMAL(19,5)
				)

	Insert #tmpIBPerceptions
		Select
				Round(sum(TM.tm_total),2)			[ib],
				TM.tax_id,
				TC.taxcl_desc,
				Round(Sum(isnull(TM.tm_subtotal,0)),2)		[Subtotal],
				ISNULL(TM.percentaje,0)						[percentage]
			From dbo.tbTaxMovements					TM				WITH (NOLOCK)
			Inner Join dbo.tbTaxName				TN				WITH (NOLOCK)
				On	TN.comp_id	= TM.comp_id
				and TN.tax_id	= TM.tax_id
			Inner Join dbo.vwsysTaxClassIB_Perceptions  TC			WITH (NOLOCK)
				On TC.tax_class = TN.tax_class
			Where	TM.comp_id			= @comp_id
				and	TM.ct_transaction	= @ct_transaction
			Group By TM.tax_id,TC.taxcl_desc,TM.percentaje

	Declare @ib					as Decimal(19,5)
	Declare @taxcl_desc			as Varchar(60)
	Declare @intIBPerceptions	as int
	Set		@intIBPerceptions	= 1
	Declare curIBPerceptions	   CURSOR LOCAL  FAST_FORWARD For
			Select	ib,								-- FIESA, MOS 09-2021, para q salga el % de percepcion de IIBB
					dbo.fnStrAllTrim (tax_text) + ' (' + dbo.fnStrAllTrim (CONVERT(VARCHAR(10),CONVERT(DECIMAL(10,2),[percentage]))) + '%)'
				From #tmpIBPerceptions

	Open		curIBPerceptions
	Fetch Next From	curIBPerceptions Into @ib,@taxcl_desc

	While @@Fetch_Status <> -1
		Begin
			If @intIBPerceptions = 1  Update #tmpTaxes Set Perception_IB1  = @ib, Perception_IB1_Text  = @taxcl_desc
			If @intIBPerceptions = 2  Update #tmpTaxes Set Perception_IB2  = @ib, Perception_IB2_Text  = @taxcl_desc
			If @intIBPerceptions = 3  Update #tmpTaxes Set Perception_IB3  = @ib, Perception_IB3_Text  = @taxcl_desc
			If @intIBPerceptions = 4  Update #tmpTaxes Set Perception_IB4  = @ib, Perception_IB4_Text  = @taxcl_desc
			If @intIBPerceptions = 5  Update #tmpTaxes Set Perception_IB5  = @ib, Perception_IB5_Text  = @taxcl_desc
			If @intIBPerceptions = 6  Update #tmpTaxes Set Perception_IB6  = @ib, Perception_IB6_Text  = @taxcl_desc
			If @intIBPerceptions = 7  Update #tmpTaxes Set Perception_IB7  = @ib, Perception_IB7_Text  = @taxcl_desc
			If @intIBPerceptions = 8  Update #tmpTaxes Set Perception_IB8  = @ib, Perception_IB8_Text  = @taxcl_desc
			If @intIBPerceptions = 9  Update #tmpTaxes Set Perception_IB9  = @ib, Perception_IB9_Text  = @taxcl_desc
			If @intIBPerceptions = 10 Update #tmpTaxes Set Perception_IB10 = @ib, Perception_IB10_Text = @taxcl_desc
			Set @intIBPerceptions = @intIBPerceptions + 1
			Fetch Next From	curIBPerceptions Into @ib,@taxcl_desc
		End
	Close		curIBPerceptions
	Deallocate	curIBPerceptions
