	SET @strInvoiceNumber = dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)
	SET @strPackingList = dbo.fnGetCommercialTransactionRelatedCT(@comp_id,@lang_id,@ct_transaction)
