	DECLARE @strLeyenda4MonotributoinA AS NVARCHAR(200) = ''
	DECLARE @prli_id AS INT = NULL
	DECLARE @strPriceListName AS VARCHAR(250) = ''



	-- FORRADA 22217
	SELECT TOP 1 @prli_id = tit.prli_id
		FROM tbItemTransactions AS tit	WITH (NOLOCK)
		WHERE	tit.comp_id			= @comp_id			AND
				tit.ct_transaction	= @ct_transaction	AND
				tit.prli_id IS NOT NULL



	SELECT	@strCustomerFiscalClass = tfc.fc_desc,
			@dl_id					= tct.dl_id,
			--@prli_id				= tc.prli_id,
			@intCustomerCurrID		= tc.curr_id,
			@strCustomerCurrency	= tc2.curr_symbol,
			@intCustomerID			= tc.cust_id,
			@strLeyenda4MonotributoinA =
											CASE	--RG (AFIP) N° 5003/21   Si es MONOTRIBUTO en Fc A
												WHEN tct.fc_id = 3 AND tct.ct_kindOf	=	'A' THEN 'El crédito fiscal discriminado en el presente comprobante, sólo podrá ser computado a efectos del Régimen de Sostenimiento e Inclusión Fiscal para Pequeños Contribuyentes de la Ley Nº 27.618'
												ELSE ''
											END
		FROM tbCommercialTransactions tct						WITH (NOLOCK)
		INNER JOIN tbCustomer tc								WITH (NOLOCK)
			ON		tc.comp_id = @comp_id
				AND tc.cust_id = tct.cust_id
		INNER JOIN tbsysFiscalClass tfc							WITH (NOLOCK)
			ON tfc.fc_id	   = tc.fc_id
		INNER JOIN tbsysCurrency tc2							WITH (NOLOCK)
			ON tc2.curr_id = tc.curr_id
		WHERE	tct.comp_id			= @comp_id
			AND tct.ct_transaction	= @ct_transaction

	SELECT @strDeliveryFiscalClass = tfc.fc_desc
		FROM tbDelivery td										WITH (NOLOCK)
		INNER JOIN tbsysFiscalClass tfc							WITH (NOLOCK)
			ON tfc.fc_id	= td.fc_id
		WHERE	td.comp_id	= @comp_id
			and td.dl_id	= @dl_id

	SET @strPriceListName = '*'
	SELECT @strPriceListName = tpl.prli_desc
		FROM tbPriceList AS tpl	WITH (NOLOCK)		-- FORRADA 22217
		WHERE	tpl.comp_id = @comp_id AND
				tpl.prli_id = @prli_id


