	-- ---------------------------------------------------------
	-- Pone en una REPUTA temporal los REPUTOS ct_transaction
	-- para que los FORROS de mierda que quieren los REPUTOS
	-- despachos del remito en la REPUTA factura los tengan
	-- de paso nos gastan REPUTOS recursos sl PEDO!!  LCDSPM
	-- ---------------------------------------------------------
	DECLARE @tmpCTTransactions TABLE(ct_transaction INT PRIMARY	KEY)
	INSERT INTO @tmpCTTransactions
		(
			ct_transaction
		)
		SELECT DISTINCT titO.ct_transaction
			FROM tbCommercialTransactions AS tct	WITH (NOLOCK)
			INNER JOIN tbItemTransactions AS tit	WITH (NOLOCK)
				ON	tit.comp_id			= tct.comp_id AND
					tit.ct_transaction	= tct.ct_transaction
			INNER JOIN tbItemTransactions AS titO	WITH (NOLOCK)
				ON	titO.comp_id		= tit.comp_id AND
					titO.it_transaction = tit.it_transaction_original
			WHERE	tct.comp_id			= @comp_id AND
					tct.ct_transaction	= @ct_transaction

		IF NOT EXISTS (
						SELECT TOP 1 1
							FROM @tmpCTTransactions AS tc
							WHERE tc.ct_transaction = @ct_transaction
						)
			BEGIN
				INSERT INTO @tmpCTTransactions
				(
					ct_transaction
				)
				VALUES
				(
					@ct_transaction
				)
			END
	-- ---------------------------------------------------------


