								  dbo.fnAddStringIfNotExists(@strCustoms		, dbo.fnStrAllTrim( IsNull(titid.impData_Custom_local,''))),
			@strCustomNumber	= @strCustomNumber + '*' +
								  dbo.fnAddStringIfNotExists(@strCustomNumber	, dbo.fnStrAllTrim( IsNull(IMPORT.impData_number,ISNULL(tid.impData_Number_local,'')))) + '*' +
								  dbo.fnAddStringIfNotExists(@strCustomNumber	, dbo.fnStrAllTrim( IsNull(titid.impData_Number_local ,'')))
		FROM tbItemTransactionImportData titid						WITH (NOLOCK)
		INNER JOIN @tmpCTTransactions					TMP			-- MOS 09-2021 para que traiga los DESPACHOS de este cpte y de los posibles relacionados.
			ON TMP.ct_transaction       = titid.ct_transaction
