	-- ---------------------------------------------------------
	-- Le agrega los del comprobante MADRE por si es un REMITO
	-- ---------------------------------------------------------
	DECLARE @ct_Transaction_PackingList AS INT
	SELECT @ct_Transaction_PackingList = tct.ct_transaction_PackingList
		FROM tbCommercialTransactions tct							WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id
			AND tct.ct_transaction	= @ct_transaction
	--
	SELECT
		@strCustoms			= @strCustoms	   + '*' +
							  dbo.fnAddStringIfNotExists(@strCustoms		, dbo.fnStrAllTrim( IsNull(IMPORT.impData_Custom,''))) + '*' +
							  dbo.fnAddStringIfNotExists(@strCustoms		, dbo.fnStrAllTrim( IsNull(titid.impData_Custom_local,''))),
		@strCustomNumber	= @strCustomNumber + '*' +
							  dbo.fnAddStringIfNotExists(@strCustomNumber	, dbo.fnStrAllTrim( IsNull(IMPORT.impData_number,''))) + '*' +
							  dbo.fnAddStringIfNotExists(@strCustomNumber	, dbo.fnStrAllTrim( IsNull(titid.impData_Number_local ,'')))
			--@strCustoms			= @strCustoms		+ '*' + dbo.fnAddStringIfNotExists(@strCustoms		, IsNull(IMPORT.impData_Custom,IsNull(titid.impData_Custom_local,''))),
			--@strCustomNumber	= @strCustomNumber	+ '*' + dbo.fnAddStringIfNotExists(@strCustomNumber	, IsNull(IMPORT.impData_number,IsNull(titid.impData_Number_local ,'')))
		FROM tbItemTransactionImportData titid						WITH (NOLOCK)
		Left Join 	dbo.tbImport						IMPORT		WITH (NOLOCK)
			ON	IMPORT.comp_id			=	@comp_id
			and	IMPORT.import_id		=	titid.import_id
		WHERE	titid.comp_id			= @comp_id
			AND titid.ct_transaction	= @ct_Transaction_PackingList
	-- ---------------------------------------------------------



	-- ---------------------------------------------------------
	-- Saca los * repetidos de la consulta de arriba
	-- ---------------------------------------------------------
	DECLARE @intLength AS INT = -1
	WHILE LEN(@strCustoms) <> @intLength
		BEGIN
			SET @intLength	= LEN(@strCustoms)
			SET @strCustoms = REPLACE(@strCustoms,'**','*')
		END
	SET		@intLength		= -1
	WHILE LEN(@strCustoms) <> @intLength
		BEGIN
			SET @intLength	= LEN(@strCustoms)
			SET @strCustoms = REPLACE(@strCustoms,' ','')
		END
	SET		@intLength		= -1
	WHILE LEN(@strCustomNumber) <> @intLength
		BEGIN
			SET @intLength			= LEN(@strCustomNumber)
			SET @strCustomNumber	= REPLACE(@strCustomNumber,'**','*')
		END
	SET		@intLength		= -1
	WHILE LEN(@strCustomNumber) <> @intLength
		BEGIN
			SET @intLength			= LEN(@strCustomNumber)
			SET @strCustomNumber	= REPLACE(@strCustomNumber,' ','')
		END
	-- ---------------------------------------------------------


