	-- ---------------------------------------------------------
	-- Calcula Importe Equivalente
	-- ---------------------------------------------------------
	DECLARE @strCurrId4Equivalence			AS VARCHAR(10)
	DECLARE @strCurrId4EquivalenceOriginal	AS VARCHAR(10)
	DECLARE @strCurrId4EquivalenceNote		AS NVARCHAR(2000)
	DECLARE @strCurrId4EquivalenceNoteMax	AS NVARCHAR(2000)
	DECLARE @decCurrId4Equivalence			AS DECIMAL(19,2)
	DECLARE @decCurrId4EquivalenceExchange	AS DECIMAL(19,6)
	IF @intCurrId4Equivalence IS NOT NULL
		BEGIN




			SELECT  @decCurrId4Equivalence = dbo.fnGetExchange2(tct.comp_id,
																tct.ct_total,
																tct.curr_id_transaction,
																tdf.df_curr_id4EquivalentTotal,
																tct.curr_id4dfExchange,
																tct.curr_id_transaction,
																tct.ct_dfExchange,
																'False'),
					@decCurrId4EquivalenceExchange = dbo.fnGetReciprocoIfNeed(
													  dbo.fnGetExchange2(tct.comp_id,
																		1,
																		tct.curr_id_transaction,
																		tdf.df_curr_id4EquivalentTotal,
																		tct.curr_id4dfExchange,
																		tct.curr_id_transaction,
																		tct.ct_dfExchange,
																		'False')),
					@strCurrId4Equivalence			= tc.curr_symbol,
					@strCurrId4EquivalenceOriginal	= tcOriginal.curr_symbol,
					@strCurrId4EquivalenceNote		= tut.utexts_desc,
					@strCurrId4EquivalenceNoteMax	= tutm.utexts_desc
				FROM tbCommercialTransactions	tct					WITH (NOLOCK)
				INNER JOIN tbDocumentsFile		tdf					WITH (NOLOCK)
					ON	tdf.comp_id			= tct.comp_id	AND
						tdf.df_id			= tct.df_id
				INNER JOIN tbsysCurrency		tc					WITH (NOLOCK)
					ON	tc.curr_id			= tdf.df_curr_id4EquivalentTotal
				INNER JOIN tbsysCurrency		tcOriginal			WITH (NOLOCK)
					ON	tcOriginal.curr_id	= tct.curr_id_transaction
				INNER JOIN tbsysUniqueTexts		tut					WITH (NOLOCK)
					ON	tut.lang_id			= @lang_id AND
						tut.utexts_id		= 224038
				INNER JOIN tbsysUniqueTexts		tutm				WITH (NOLOCK)
					ON	tutm.lang_id		= @lang_id AND
						tutm.utexts_id		= 224040
				WHERE	tct.comp_id			= @comp_id			AND
						tct.ct_transaction	= @ct_transaction

			SET @strCurrId4EquivalenceNoteMax = replace(@strCurrId4EquivalenceNoteMax, '#TXTIMPORTEEQUIVALENTE#',	dbo.fnStrAllTrim(	convert(nvarchar,CONVERT(DECIMAL(19,2),@decCurrId4Equivalence))))
			SET @strCurrId4EquivalenceNoteMax = replace(@strCurrId4EquivalenceNoteMax, '#TXTMONEDAEQUIVALENTE#',	dbo.fnStrAllTrim(	@strCurrId4Equivalence))
			SET @strCurrId4EquivalenceNoteMax = replace(@strCurrId4EquivalenceNoteMax, '#TXTMONEDAORIGINAL#',		dbo.fnStrAllTrim(@strCurrId4EquivalenceOriginal))
			SET @strCurrId4EquivalenceNoteMax = replace(@strCurrId4EquivalenceNoteMax, '#TXTTIPODECAMBIO#',			dbo.fnStrAllTrim(convert(nvarchar,CONVERT(DECIMAL(19,2),@decCurrId4EquivalenceExchange))))
		END

