	DECLARE @strCAEQRJsonAutoPrint  AS NVARCHAR(500) = ''
	DECLARE @strQRDate				AS NVARCHAR(20) = ''
	DECLARE @strQREmCUIT			AS NVARCHAR(20) = ''
	DECLARE @strQRNroCpte			AS NVARCHAR(50) = ''
	DECLARE @strQRImporte			AS NVARCHAR(50) = ''
	DECLARE @strQRMoneda			AS NVARCHAR(10) = 'PES'
	DECLARE @strQRCotizacion		AS NVARCHAR(50) = ''
	DECLARE @strQRTipoCodAut		AS NVARCHAR(10) = ''
	DECLARE @strQRtipoDocRec		AS VARCHAR(2)   = ''
	DECLARE @strQRnroDocRec			AS VARCHAR(20)  = ''





	-- Authogar
	DECLARE @strCAIBarCodeAutoPrint AS NVARCHAR(50)

	SET		@strCAIBarCodeAutoPrint = ''
	SELECT	@strCAIBarCodeAutoPrint = REPLACE( dbo.fnStrAllTrim( ISNULL( tb.bra_taxNumber,'')),'-',''),
		    @strQREmCUIT			= REPLACE( dbo.fnStrAllTrim( dbo.fnGetOnlyNumbers(  ISNULL( tb.bra_taxNumber,''))     ),'-','')
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id




	SET @strCAIBarCodeAutoPrint = @strCAIBarCodeAutoPrint +
		CASE
			WHEN @sd_id = 1 AND @Kind_Of = 'A' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '201'
			WHEN @sd_id = 4 AND @Kind_Of = 'A' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '202'
			WHEN @sd_id = 3 AND @Kind_Of = 'A' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '203'
			WHEN @sd_id = 1 AND @Kind_Of = 'B' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '206'
			WHEN @sd_id = 4 AND @Kind_Of = 'B' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '207'
			WHEN @sd_id = 3 AND @Kind_Of = 'B' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '208'
			WHEN @sd_id = 1 AND @Kind_Of = 'C' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '211'
			WHEN @sd_id = 4 AND @Kind_Of = 'C' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '212'
			WHEN @sd_id = 3 AND @Kind_Of = 'C' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '213'

			WHEN @sd_id = 1 AND @Kind_Of = 'A' THEN '01'
			WHEN @sd_id = 4 AND @Kind_Of = 'A' THEN '02'
			WHEN @sd_id = 3 AND @Kind_Of = 'A' THEN '03'
			WHEN @sd_id = 1 AND @Kind_Of = 'B' THEN '06'
			WHEN @sd_id = 4 AND @Kind_Of = 'B' THEN '07'
			WHEN @sd_id = 3 AND @Kind_Of = 'B' THEN '08'
			WHEN @sd_id = 1 AND @Kind_Of = 'C' THEN '11'
			WHEN @sd_id = 4 AND @Kind_Of = 'C' THEN '12'
			WHEN @sd_id = 3 AND @Kind_Of = 'C' THEN '13'
			ELSE '00'
		END

	SET @strCAIBarCodeAutoPrint = @strCAIBarCodeAutoPrint + dbo.fnStrPADL( CONVERT(nvarchar(10),@pointOfSale),4,'0')


	SELECT	@strPointOfSale = dbo.fnStrPADL(isNull(tct.ct_pointOfSale,''),5,'0'),
			@strCAI			= tct.ct_CAI,
			@strCAIDate		= Convert(varchar(4),year(tct.ct_CAIDate)) + dbo.fnStrPADL(CONVERT(VARCHAR(2),MONTH(tct.ct_CAIDate)),2,'0') + dbo.fnStrPADL(CONVERT(VARCHAR(2),DAY(tct.ct_CAIDate)),2,'0'),
			-- MOS 03-2021, se cambió a TaxDate  @strQRDate		= Convert(varchar(4),year(tct.ct_CAIDate)) + '-' + dbo.fnStrPADL(CONVERT(VARCHAR(2),MONTH(tct.ct_CAIDate)),2,'0') + '-' + dbo.fnStrPADL(CONVERT(VARCHAR(2),DAY(tct.ct_CAIDate)),2,'0'),
			@strQRDate		= Convert(varchar(4),year(tct.ct_taxDate)) + '-' + dbo.fnStrPADL(CONVERT(VARCHAR(2),MONTH(tct.ct_taxDate)),2,'0') + '-' + dbo.fnStrPADL(CONVERT(VARCHAR(2),DAY(tct.ct_taxDate)),2,'0'),
			@strQRNroCpte	= tct.ct_docNumber ,
			@strQRImporte	= REPLACE(REPLACE(CONVERT(NVARCHAR(20),CONVERT(DECIMAL(15,2),tct.ct_total)),',','.'),'.','.'),
			@strQRMoneda    =	CASE
									WHEN tdf.curr_id4ElectronicInvoice = 1 THEN 'PES'
									WHEN tdf.curr_id4ElectronicInvoice = 2 THEN 'DOL'
									ELSE										'PES'
								END,
			@strQRCotizacion= REPLACE(REPLACE(CONVERT(NVARCHAR(20),CONVERT(DECIMAL(15,2),tct.ct_dfExchange)),',','.'),'.','.'),
			@strQRTipoCodAut=	CASE
									WHEN tdf.df_CAEA_isAvailable = 'True' THEN 'A'
									ELSE									   'E'
								END	,

			@strQRtipoDocRec= CONVERT(VARCHAR(10),tnt.tnt_afip)		,
			@strQRnroDocRec	= REPLACE(dbo.fnStrAllTrim (tc.cust_taxNumber),'-','')


		FROM tbCommercialTransactions tct		WITH (NOLOCK)
		INNER JOIN tbCustomer AS tc				WITH (NOLOCK)
			ON	tc.comp_id	= tct.comp_id AND
				tc.cust_id	= tct.cust_id
		INNER JOIN tbsysTaxNumberTypes AS tnt
			ON tnt.tnt_id = tc.tnt_id
		INNER JOIN tbDocumentsFile AS tdf		WITH (NOLOCK)
			ON	tdf.comp_id = tct.comp_id AND
				tdf.df_id	= tct.df_id
	WHERE	tct.comp_id				= @comp_id
		AND tct.ct_transaction		= @ct_transaction


	SET @strCAIBarCodeAutoPrint = @strCAIBarCodeAutoPrint + @strCAI + @strCAIDate
	--El digito verificador lo calculamos en VB que es mas facil...
	-- Authogar


	--SET @strCAIBarCodeAutoPrint = @strCUIT + @strFEDocCode + @strPointOfSale + @strCAI + @strCAIDate
	SET @strCAIBarCodeAutoPrint = @strCAIBarCodeAutoPrint + CONVERT(NVARCHAR(1),dbo.fnGetAFIPChecksumVerification(@strCAIBarCodeAutoPrint))



	SET @strCAEQRJsonAutoPrint =	'{"ver":1,"fecha":"'
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + @strQRDate + '"'
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"cuit":' + @strQREmCUIT
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"ptoVta":' + CONVERT(VARCHAR(10),@intPointOfSale)     --MOS 08-2022  @strPointOfSale
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"tipoCmp":' +	CASE
																					WHEN @sd_id = 1 AND @Kind_Of = 'A' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '201'
																					WHEN @sd_id = 4 AND @Kind_Of = 'A' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '202'
																					WHEN @sd_id = 3 AND @Kind_Of = 'A' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '203'
																					WHEN @sd_id = 1 AND @Kind_Of = 'B' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '206'
																					WHEN @sd_id = 4 AND @Kind_Of = 'B' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '207'
																					WHEN @sd_id = 3 AND @Kind_Of = 'B' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '208'
																					WHEN @sd_id = 1 AND @Kind_Of = 'C' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '211'
																					WHEN @sd_id = 4 AND @Kind_Of = 'C' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '212'
																					WHEN @sd_id = 3 AND @Kind_Of = 'C' AND @df_electronicInvoiceFCCredito_Enabled = 'True' THEN '213'
																					WHEN @sd_id = 1 AND @Kind_Of = 'A' THEN '1'
																					WHEN @sd_id = 4 AND @Kind_Of = 'A' THEN '2'
																					WHEN @sd_id = 3 AND @Kind_Of = 'A' THEN '3'
																					WHEN @sd_id = 1 AND @Kind_Of = 'B' THEN '6'
																					WHEN @sd_id = 4 AND @Kind_Of = 'B' THEN '7'
																					WHEN @sd_id = 3 AND @Kind_Of = 'B' THEN '8'
																					WHEN @sd_id = 1 AND @Kind_Of = 'C' THEN '11'
																					WHEN @sd_id = 4 AND @Kind_Of = 'C' THEN '12'
																					WHEN @sd_id = 3 AND @Kind_Of = 'C' THEN '13'
																					ELSE '00'
																				END
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"nroCmp":'		+ @strQRNroCpte
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"importe":'		+ @strQRImporte
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"moneda":"'		+ @strQRMoneda + '"'
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"ctz":'			+	CASE
																						WHEN @strQRMoneda <> 'PES' THEN @strQRCotizacion
																						ELSE '1'
																					END
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"tipoDocRec":'   + @strQRtipoDocRec --null'
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"nroDocRec":'    + @strQRnroDocRec --null'
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"tipoCodAut":"'	+ @strQRTipoCodAut + '"'
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + ',"codAut":'		+ @strCAI
	SET	@strCAEQRJsonAutoPrint =	@strCAEQRJsonAutoPrint + '}'

















	DECLARE @dec1RSTQuote AS DECIMAL(19,2)
	SET		@dec1RSTQuote		= 0
	DECLARE @str1RSTQuoteMoneda AS NVARCHAR(20)
	SET		@str1RSTQuoteMoneda = ''
	DECLARE @dat1RSTQuote DATETIME
	SET		@dat1RSTQuote	    = GETDATE()
	DECLARE @decInCash4Loan		AS DECIMAL(29,2)
	SET		@decInCash4Loan		= 0

	SELECT  TOP 1
			@dec1RSTQuote		=	CASE
										WHEN tctl.comp_id IS NULL THEN	tct.ct_ATotal
										ELSE							tctl.ct_ATotal
									END,
			@str1RSTQuoteMoneda = tc.curr_symbol,
			@dat1RSTQuote		=	CASE
										WHEN tctl.comp_id IS NULL THEN	tct.ct_payDate
										ELSE							tctl.ctl_payDate
									END ,
			@decInCash4Loan		=	ISNULL(
									CASE
			               		 	    WHEN tctl.comp_id IS NOT NULL AND tctl.ctl_payDate = tct.ct_date	THEN tctl.ct_ATotal
			               		 	    WHEN tctl.comp_id IS NOT NULL AND tctl.ctl_payDate > tct.ct_date	THEN 0
			               		 	    WHEN tctl.comp_id IS NULL											THEN tct.ct_ATotal
			               		 	    ELSE																   0
			               		 	END,0)
		FROM tbCommercialTransactions tct				WITH (NOLOCK)
		INNER JOIN tbsysCurrency tc						WITH (NOLOCK)
			ON tc.curr_id = tct.ct_ACurrency
		LEFT JOIN tbCommercialTransactionsLoan tctl		WITH (NOLOCK)
		ON	tctl.comp_id		= tct.comp_id			AND
			tctl.ct_transaction = tct.ct_transaction
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @ct_transaction
		ORDER BY tctl.ctl_payNumber ASC


	DECLARE @datLastQuote DATETIME

	SELECT  TOP 1
			@datLastQuote = CASE
								WHEN tctl.comp_id IS NULL THEN	tct.ct_payDate
								ELSE							tctl.ctl_payDate
							END
		FROM tbCommercialTransactions tct				WITH (NOLOCK)
		INNER JOIN tbsysCurrency tc						WITH (NOLOCK)
			ON tc.curr_id = tct.ct_ACurrency
		LEFT JOIN tbCommercialTransactionsLoan tctl		WITH (NOLOCK)
		ON	tctl.comp_id		= tct.comp_id			AND
			tctl.ct_transaction = tct.ct_transaction
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @ct_transaction
		ORDER BY tctl.ctl_payNumber DESC



--SELECT CONVERT(VARCHAR(10),GETDATE(), 101)		01/09/2019

--SELECT CONVERT(VARCHAR(10),GETDATE(), 111)		2019/01/09

--SELECT CONVERT(VARCHAR(10),GETDATE(), 103)		09/01/2019

--SELECT CONVERT(VARCHAR(10),GETDATE(), 8)			18:11:24



	SELECT	ct.*,
			tmpTAXES.*,
			tb.*,
			sm.*,
			us.*,
			cust.*,
			tcf.*,
			tcg.*,
			tfcp.*,
			tdf.*,
			tst.*,
			tcc.*,
			tcclp.*,
			td.*,
			td2.*,
			tft.*,
			tfi.*,
			ts.*,
			tc.*,
			ctn.*,
			tcb.*,
			ttnt.*,
			cha	.*,
			@FOOTER_COMPANY_NAME			[FOOTER_COMPANY_NAME],
			@FOOTER_COMPANY_ADDRESS			[FOOTER_COMPANY_ADDRESS],
			@FOOTER_COMPANY_CITY			[FOOTER_COMPANY_CITY],
			@FOOTER_COMPANY_ZIP				[FOOTER_COMPANY_ZIP],
			@FOOTER_COMPANY_PHONE			[FOOTER_COMPANY_PHONE],
			@FOOTER_COMPANY_STATE			[FOOTER_COMPANY_STATE],
			@FOOTER_COMPANY_TAXNUMBER		[FOOTER_COMPANY_TAXNUMBER],
			@FOOTER_COMPANY_IB				[FOOTER_COMPANY_IB],
			@FOOTER_COMPANY_BEGACT			[FOOTER_COMPANY_BEGACT],
			@FOOTER_COMPANY_FC				[FOOTER_COMPANY_FC],
			@FOOTER_COMPANY_COUNTRY			[FOOTER_COMPANY_COUNTRY],
			@lang_id						[lang_id],
			@strDfCurrencyText				[dfCurrencyText],
			@strBranchCurrencyText			[dfBranchCurrencyText],
			@strDfExchangeCurrencyText		[df2BranchExchangeCurrencyText],
			@decTotal						[total2Text],
			@decDfExchange2Branch			[dfExchange2Branch],
			@strCustomerFiscalClass			[CustomerFiscalClass],
			@strDeliveryFiscalClass			[DeliveryFiscalClass],
			@strSaleOrder					[SaleOrder],
			@strInvoiceNumber				[InvoiceNumber],
			@strPackingList					[PackingList],
			@serialNumbers					[SerialNumbers],
			dbo.fnGetCommercialTransactionDescription( @comp_id,@lang_id,@ct_transaction )
											[TransactionDescription],
			tc.country_desc					[cust_Country],
			ts.state_desc					[cust_state],
			tc2.country_desc				[custb_Country],
			ts2.state_desc					[custb_State],
			CASE
				WHEN ctn.ctn_deliveryAddressOfSaleOrder IS NOT NULL AND
					 ctn.ctn_deliveryAddressOfSaleOrder <> ''		THEN ctn.ctn_deliveryAddressOfSaleOrder
			    WHEN tcf.comp_id IS NOT NULL						THEN tcf.custf_address
			    WHEN tcb.comp_id IS NOT NULL						THEN tcb.custb_address
			    WHEN ISNULL(cust.cust_address4Delivery,'') <> ''	THEN cust.cust_address4Delivery
			    ELSE													 cust.cust_address
			END															[DeliveryAddress],

			CASE
			    WHEN IsNull(cust.cust_address4Payments,'') = '' THEN  cust.cust_address
			    ELSE cust.cust_address4Payments
			END															[PaymentAddress],
			(ct.ct_subtotal - ct.ct_discount)							[ct_subtotalWithDiscount],

			(
				(
					ct.ct_taxes / dbo.fnNoZDiv(ct.ct_subtotal - ct.ct_discount /*MOS 01-2019 tkt 4767-3*/)  * ct.ct_discount
				)  + ct.ct_discount
			)															[ct_discountWithTaxes],
			((ISNULL(ct.ct_discount,0) / dbo.fnNoZDiv(ISNULL(ct.ct_subtotal,1))) * 100) [totalDiscountPercentage],	-- MOS 03-2023: % FINAL de Descuento
			ISNULL(ct.ct_discount,0)													[totalDiscountTotal],		-- MOS 03-2023: IMPORTE FINAL de Descuento
			CONVERT(INT,
			CASE																	-- Si tiene el remito una factura asociada pone los bultos grabados en la factura, sino, pone lo que figura en el remito.-
				WHEN ISNULL(tct1.ct_packagesQty,0) > 0 THEN tct1.ct_packagesQty
				Else IsNull(ct.ct_packagesQty,1)
			END		)									[intPackagesQty],
			cust.cust_name								[cust_nameOwn],
			CONVERT(VARCHAR(10),@datDeliveryDate, @df_documentsPrintDateStyle)
														[DeliveryDate],
			@decTOTALWEIGHT								[TOTALWEIGHT],
			@decTotalVOLUME								[TOTALVOLUME],
			@strCustoms									[CUSTOMS],
			@strCustomNumber							[CUSTOM_NUMBER],
			IsNull(@strCAEBarCode,'')					[CAE_BarCode],
			@strCAI										[CAE_Number],
			@strCAIDate									[CAE_Date],
			CONVERT(VARCHAR(10),ct.ct_CAIDate, @df_documentsPrintDateStyle)
														[CAE_Date2Date],
			@decItemQTY									[ct_itemQty],
			tb.spof_id,
			@decTMPAdjust								[SubTotalAdjust],
			ISNULL(tfcp.fex_cuit,'')					[strFEX_cuit],
			ISNULL(cust.fecountry_id,'')				[strFEcountry_id],
			ISNULL(tfi.fecountry_desc,'')				[strFEcountry_Desc],
			ISNULL(tft.inco_Id,'')						[strInco_ID],
			ISNULL(tft.inco_desc,'')					[strInco_Desc],
			@bitIsPermisoEmbarque						[bitIsPermisoEmbarque],
			@decDfExchange																	[decDFExchange]				,	-- Total expresado en la moneda de tipo de cambio del documento
			@strDfExchangeCurrencySym														[decDFExchangeCurrency]		,	-- Moneda del tipo de cambio del documento.
			cha.stca_desc																	[Chile_Actividad],
			ct.st_id,
			convert(decimal(19,0),Round(@decTotal,0))										[TotalWithOutDecimals],
			@strCurrId4Equivalence															[strCurrId4Equivalence],
			@strCurrId4EquivalenceNote														[strCurrId4EquivalenceNote],
			@decCurrId4Equivalence															[decCurrId4Equivalence],
			@decCurrId4EquivalenceExchange													[decCurrId4EquivalenceExchange],
			@strCurrId4EquivalenceNoteMax													[strCurrId4EquivalenceNoteMax],
			isnull(CTN.ctn_note1,'')														[observation1],
			isnull(CTN.ctn_note2,'')														[observation2],
			isnull(CTN.ctn_note3,'')														[observation3],
			isnull(CTN.ctn_note4,'')														[observation4],
			isnull(CTN.ctn_deliveryAddressOfSaleOrder,'')									[ctn_deliveryAddressOfSaleOrder],
			ct.ct_guid																		[ct_guid],
			ct.bra_id																		[BranchId],
			IsNull(tcG.cust_name,'')														[GC_Name],
			IsNull(tcG.cust_id,0)															[GC_ID],
			IsNull(tcG.cust_taxNumber,'')													[GC_TaxNumber],
			@decInCash4Loan																	[CT_InCashValue],
			convert(decimal(19,2),IsNull(ct.ct_total,0) - IsNull(
																	CASE	-- Si TIENE Anticipo UNICAMENTE, debe restarlo segun tbsysCreditTypes
																		WHEN tst.sct_id IN (1,2,4,21) THEN @dec1RSTQuote  -- MOS 06-2017, agregue la 1
																		ELSE 0
																	END

																			,0))			[CT_inLoan],  -- MOS 03-2017		convert(decimal(19,2),IsNull(ct.ct_total,0) - IsNull(@dec1RSTQuote,0))			[CT_inLoan]
			CONVERT(VARCHAR(10),@datLastQuote, @df_documentsPrintDateStyle)					[datLastQuote],
			CONVERT(VARCHAR(10),@dat1RSTQuote, @df_documentsPrintDateStyle)					[dat1RSTQuote],
			CONVERT(VARCHAR(10),DATEADD(MONTH,2,@dat1RSTQuote), @df_documentsPrintDateStyle)	[dat1RSTQuotePlus60],
			CONVERT(VARCHAR(10),ct.ct_payDate, @df_documentsPrintDateStyle)					[dateOfPayment],
			CASE
				WHEN tcf.custf_picture IS NOT NULL THEN tcf.custf_picture
				WHEN tcb.custb_picture IS NOT NULL THEN tcb.custb_picture
				ELSE cust.cust_picture
			END																				[customer_photo],
			ISNULL(@strCAIBarCodeAutoPrint,'')												[CAIBarCodeAutoPrint],
			ISNULL(@strCAEQRJsonAutoPrint,'')												[CAIQRCodeAutoPrint],
			/*@comp_ServerFULLURL2Acces +*/ 'wfmQRCode.aspx?QRParameter=' +
			dbo.fnConvertStringToBase64( 'https://www.afip.gob.ar/fe/qr/?p=' + dbo.fnConvertStringToBase64(@strCAEQRJsonAutoPrint))		[CAIQRCodeAutoPrint4CR],
			@comp_ServerFULLURL2Acces + 'Temp/QR/' + CONVERT(VARCHAR(30),ct.ct_transaction) + '.jpg'									[CAIQRCodeAutoPrint4CRJPGFileName],
			tctq.ctQR_Image																	[CAIQRCodeAutoPrint4CR_IMAGE],

			tctq.ctQR_Image4Logistic														[LogisticQRCode4CR_IMAGE],

			IsNull(@dec1RSTQuote,0)															[CT_1RSTQuote],
			IsNull(@str1RSTQuoteMoneda,'')													[CT_1RSTQuoteCurrency],


			ISNULL(
			CASE
				WHEN tcf.comp_id IS NOT NULL THEN	tcf.custf_name
				WHEN tcb.comp_id IS NOT NULL THEN	tcb.custb_name
				ELSE								cust.cust_name
			END	,'')																			[Cust_M_Name],

			ISNULL(
			CASE
				WHEN tcf.comp_id IS NOT NULL THEN	tcf.custf_address
				WHEN tcb.comp_id IS NOT NULL THEN	tcb.custb_address
				ELSE								cust.cust_address
			END	,'')																			[Cust_M_Address],
			ISNULL(cust.cust_address,'')														[cust_defaultAddress],
			ISNULL(
			CASE
				WHEN tcf.comp_id IS NOT NULL THEN	tcf.custf_city
				WHEN tcb.comp_id IS NOT NULL THEN	tcb.custb_city
				ELSE								cust.cust_city
			END	,'')																			[Cust_M_City],

			ISNULL(
			CASE
				WHEN tcf.comp_id IS NOT NULL THEN	tcf.custf_cellPhone
				WHEN tcb.comp_id IS NOT NULL THEN	tcb.custb_Phone1
				ELSE								cust.cust_phone1
			END	,'')																			[Cust_M_Phone],
			ISNULL(
			CASE
				WHEN tcf.comp_id IS NOT NULL THEN	tcf.custf_cellPhone
				WHEN tcb.comp_id IS NOT NULL THEN	tcb.custb_Phone1
				ELSE								cust.cust_cellPhone
			END	,'')																			[Cust_CellPhone],
			ISNULL(
			CASE
				WHEN tcf.comp_id IS NOT NULL THEN	tcf.custf_taxNumber
				WHEN tcb.comp_id IS NOT NULL THEN	cust.cust_taxNumber
				ELSE								cust.cust_taxNumber
			END	,'')																			[Cust_M_DocumentNumber],
			CASE
				WHEN tcclp.comp_id IS NOT NULL THEN IsNull(tcclp.ccp_desc,'')
				WHEN tcc.comp_id   IS NOT NULL THEN ISNULL(tcc.cc_desc,'')
				ELSE								''
			END																					[mainCreditCardDescription],

			CONVERT(VARCHAR(10),
								DATEADD(second, DATEPART(second,ct.ct_cd),
								DATEADD(minute, DATEPART(minute,ct.ct_cd),
								DATEADD(hour,	DATEPART(hour, ct.ct_cd),
										dbo.fnGetEnd_or_BeginOfDate( ct.ct_taxDate,'False'))))
								, @df_documentsPrintDateStyle)	-- Fecha

																								[DateOfEmission] ,
			CONVERT(VARCHAR(10),
								DATEADD(second, DATEPART(second,ct.ct_cd),
								DATEADD(minute, DATEPART(minute,ct.ct_cd),
								DATEADD(hour,	DATEPART(hour, ct.ct_cd),
										dbo.fnGetEnd_or_BeginOfDate( ct.ct_taxDate,'False'))))
								, @df_documentsPrintDateStyle)	-- Fecha
								 +	' ' +
			CONVERT(VARCHAR(10),
								DATEADD(second, DATEPART(second,ct.ct_cd),
								DATEADD(minute, DATEPART(minute,ct.ct_cd),
								DATEADD(hour,	DATEPART(hour, ct.ct_cd),
										dbo.fnGetEnd_or_BeginOfDate( ct.ct_taxDate,'False'))))
								, 8)		-- Hora
																								[HourDateOfEmission] ,
			tb.bra_desc																			[branchInternalName],
			IsNull(us.user_lastname,'') + ', ' + IsNull(us.user_firstname,'')					[user_completeName],
			IsNull(tdf.df_reportAdditional,0)													[crystal_df_reportAdditional],
			IsNull(tdf.df_reportAdditionalName,'')												[crystal_df_reportAdditionalName],
			IsNull(tdf.df_reportAdditionalKindOf,'')											[crystal_df_reportAdditionalKindOf],
			IsNull(tdf.df_reportAdditionalFooter,'')											[crystal_df_reportAdditionalFooter],
			ISNULL(tdf.df_reportAdditionalCode,'')												[df_reportAdditionalCode],
			ISNULL(ct.ct_ABalance,0)															[RECEIPT_aBalance],
			ISNULL(ct.ct_ATotal,0) -  ISNULL(ct.ct_ABalance,0)									[RECEIPT_aTotalMinusaBalance],
			ISNULL(ct.ct_adjust,0)																[RECEIPT_adjust],
			ISNULL(ct.ct_total,0)																[RECEIPT_TOTAL],
			'*' + ' ' + dbo.fnStrPADL(ct.ct_transaction,10, '0') + ' ' + '*'					[ct_transaction4Code],
			IsNull(tdf.df_reportAdditionalTOPCenter,'')											[crystal_df_reportAdditionalTOPCenter],
			@soh_MLId																			[MERCADO_NUMBER],
			@soh_MLGUIA																			[MERCADO_GUIDE],
			ISNULL(cust.cust_MercadoLibreNickName,'')											[MERCADO_NICKNAME],
			CASE
				WHEN tdf.curr_id4ElectronicInvoice = 1		THEN 'PES'
				WHEN tdf.curr_id4ElectronicInvoice = 2		THEN 'DOL'
				--WHEN tdf.curr_id4ElectronicInvoice = 162	THEN 'DOL'
				ELSE										'PES'
			END																					[currency4ElectronicInvoice],
			ISNULL(ct.supp_id4CreditCardLiquidation,0)											[supp_id4CreditCardLiquidation],
			ISNULL(@mlo_id,0)																	[mlo_id],
			dbo.fnStrAllTrim( (
								SELECT TOP 1 tccv.ccv_MPBotonDePagoLinkButton
									FROM tbCreditCard_VoucherRelations	AS tccvr	WITH (NOLOCK)
									INNER JOIN tbCreditCard_Voucher		AS tccv		WITH (NOLOCK)
										ON	tccv.comp_id			= tccvr.comp_id			AND
											tccv.ccv_id				= tccvr.ccv_id
									WHERE	tccvr.comp_id			= ct.comp_id			AND
											tccvr.ct_transaction	= ct.ct_transaction	AND
											tccv.ccv_MPBotonDePagoIsExpired = 0
									ORDER BY	CASE
													WHEN tccvr.ctl_id IS NOT NULL THEN  0
													ELSE								1
												END

							))																	[MPct_MPButtonURL],
			ISNULL(@strPresentation01,'')														[strPresentation01],
			ISNULL(@strPresentation02,'')														[strPresentation02],
			ISNULL(@strPresentation03,'')														[strPresentation03],
			ISNULL(@strPresentation04,'')														[strPresentation04],
			ISNULL(@strPresentation05,'')														[strPresentation05],
			ISNULL(@strPresentation06,'')														[strPresentation06],
			ISNULL(@strPresentation07,'')														[strPresentation07],
			ISNULL(@strPresentation08,'')														[strPresentation08],
			ISNULL(@strPresentation09,'')														[strPresentation09],
			ISNULL(@strPresentation10,'')														[strPresentation10],
			ISNULL(@strPresentation11,'')														[strPresentation11],
			ISNULL(@strPresentation12,'')														[strPresentation12],
			ISNULL(@strPresentation13,'')														[strPresentation13],
			ISNULL(@strPresentation14,'')														[strPresentation14],
			ISNULL(@strPresentation15,'')														[strPresentation15],
			ISNULL(@strPresentation16,'')														[strPresentation16],
			ISNULL(@strPresentation17,'')														[strPresentation17],
			ISNULL(@strPresentation18,'')														[strPresentation18],
			ISNULL(@strPresentation19,'')														[strPresentation19],
			ISNULL(@strPresentation20,'')														[strPresentation20],
			ISNULL(@strPresentationTOTAL,'')													[strPresentationTOTAL],
			Convert( NVARCHAR ,@decBalance_TOTAL)		+ ' ' + @strCustomerCurrency			[BalanceTotal],
			Convert( NVARCHAR ,@decBalance_EXPIRED)		+ ' ' + @strCustomerCurrency			[BalanceTotalExpired]		,
			Convert( NVARCHAR ,@decBalance_UNEXPIRED)	+ ' ' + @strCustomerCurrency			[BalanceTotalUnExpired]		,
			Convert( NVARCHAR ,@decBranchBalance_TOTAL)		+ ' ' + @strCustomerCurrency		[BranchBalanceTotal],
			Convert( NVARCHAR ,@decBranchBalance_EXPIRED)	+ ' ' + @strCustomerCurrency		[BranchBalanceTotalExpired]		,
			Convert( NVARCHAR ,@decBranchBalance_UNEXPIRED)	+ ' ' + @strCustomerCurrency		[BranchBalanceTotalUnExpired]	,
			ISNULL(ct.ct_documentNumber,1)														[intDocumentNumber],
			ISNULL(ct.ct_documentTotal,1)														[intDocumentTotal]	,
			@intCopyQty																			[intCopyQty],
			CONVERT(VARCHAR(10),
				DATEADD( day,ISNULL(tst.st_creditInvoice_chequeDays,0), ct.ct_taxDate),
				@df_documentsPrintDateStyle	)													[chequeLimitDate]	,
			ISNULL(tp.pro_desc,'')																[pro_desc]	,
			(
			SELECT TOP 1 CONVERT(NVARCHAR(40),tctlp.ct_date)
				FROM tbCommercialTransactions AS tctLP	WITH (NOLOCK)
				WHERE	tctLP.comp_id = ct.comp_id	AND
						tctLP.cust_id = ct.cust_id	AND
						tctlp.sd_id   = 1
				ORDER BY tctLP.ct_transaction DESC
			)																					[lastPurchase]	,
			ISNULL(cust.cust_cellPhone2,'')														[strCust_cellPhone2],
			ISNULL(cust.cust_cellPhone2_notes,'')												[strCust_cellPhone2_notes],
			ISNULL(cust.cust_cellPhone1_notes,'')												[strCust_cellPhone1_notes],
			@totaltext																			[TotalinLetter],
			@strLeyenda4MonotributoinA															[strLeyenda4MonotributoinA],
			ISNULL(tdf.df_note1,'')																[df_note1],
			ISNULL(tdf.df_note2,'')																[df_note2],
			ISNULL(tdf.df_note3,'')																[df_note3],
			ISNULL(tdf.df_note4,'')																[df_note4],
			ISNULL(tdf.df_electronicInvoiceFCCredito_CBU,'')									[df_electronicInvoiceFCCredito_CBU],
			@strPreInvoiceNumber																[strPreInvoiceNumber],
			ISNULL(
			CASE
				WHEN tcf.comp_id IS NOT NULL THEN	tcf.custf_zip
				WHEN tcb.comp_id IS NOT NULL THEN	tcb.custb_zip
				ELSE								cust.cust_zip
			END	,'')																			[Cust_M_zip],
			tsd.sd_desc																			[sd_desc],
			CASE
				WHEN ISNULL(tdf.df_documentsPrint_HtmlViewerWidth,0) > 0 THEN tdf.df_documentsPrint_HtmlViewerWidth
				ELSE 300
			END																					[documentsPrint_HtmlViewerWidth],
			-- MOS 03-2023, nuevos campos
			ISNULL(CTN.ctn_link4ReprintExternalElectronicInvoice,'')							[ctn_link4ReprintExternalElectronicInvoice],
			ISNULL(@decTotalCost,0)																[decTotalCost],
			ISNULL(@decTotalCostB,0)															[decTotalCostB],
			ISNULL(@decTotalCostPP,0)															[decTotalCostPP],
			ISNULL(@decTotalCostPPB,0)															[decTotalCostPPB],
			ISNULL(tdf.df_desc,'')																[df_desc]	,
			--ISNULL(cust.cust_city,'')															[cust_city],
			--ISNULL(cust.cust_phone1,'')															[cust_phone1],
			--ISNULL(cust.cust_taxNumber,'')														[cust_taxNumber]
			@strPaymentButtonLink																[strPaymentButtonLink],
			ISNULL(ctn.ctn_userDecimalValue1,0)													[userDecimalValue1],
			ISNULL(ctn.ctn_userDecimalValue2,0)													[userDecimalValue2],
			ISNULL(ctn.ctn_userDecimalValue3,0)													[userDecimalValue3],

			-- -----------------------------------------
			-- Logistica de Ventas
			-- -----------------------------------------
			CASE	-- Repetir ABAJO si se cambia algo !
				WHEN	dbo.fnStrAllTrim( ISNULL(ctn.ctn_link4Reprint,''))	<> ''	AND
						@comp_ServerFULLURL4DeliveryConfirmation			<> ''			THEN @comp_ServerFULLURL4DeliveryConfirmation + '' + REPLACE(ctn.ctn_link4Reprint,'wfmPrintMyDocument.aspx','wfmDeliverySheet_DeliveryConfirmation.aspx')
				ELSE ''
			END																					[comp_ServerFULLURL4DeliveryConfirmation],
			'wfmQRCode.aspx?QRParameter=' +
			dbo.fnConvertStringToBase64(
											CASE
												WHEN	dbo.fnStrAllTrim( ISNULL(ctn.ctn_link4Reprint,''))	<> ''	AND
														@comp_ServerFULLURL4DeliveryConfirmation			<> ''			THEN @comp_ServerFULLURL4DeliveryConfirmation + '' + REPLACE(ctn.ctn_link4Reprint,'wfmPrintMyDocument.aspx','wfmDeliverySheet_DeliveryConfirmation.aspx')
												ELSE ''
											END
										)											[comp_ServerFULLURL4DeliveryConfirmation_Parameter],
			-- -----------------------------------------
			ISNULL(tdf.df_ElectronicInvoice_MiPyme_blockApplicationData,'False')	[ElectronicInvoice_MiPyme_blockApplicationData],
			ISNULL(tdf.sdfpt_id,-1)													[sdfpt_id],



			-- FORRADA de GB de ticket 22217
			--@decTotalDiscountI_II  [decTotalDiscountI_II],
			CONVERT(DECIMAL(19,2),
			@decTotalDiscountI_II)														[totalDiscountI_II],

			CONVERT(DECIMAL(19,2),
			ct.ct_subtotal  - @decTotalDiscountI_II	)									[subTotalWithDiscountI_II] ,

			CONVERT(DECIMAL(19,2),
			ct.ct_discount - @decTotalDiscountI_II)										[totalDiscountWithOutDiscountI_II] ,

			-- MISMA MIERDA MAS IMPUESTOS PRORRATEADOS

			CONVERT(DECIMAL(19,2),
			@decTotalDiscountI_II
			* (ct.ct_total / dbo.fnNoZDiv(ct.ct_total - ct.ct_taxes)))					[totalDiscountI_IIPlusTAXES],

			CONVERT(DECIMAL(19,2),
			(ct.ct_subtotal  - @decTotalDiscountI_II)
			* (ct.ct_total / dbo.fnNoZDiv(ct.ct_total - ct.ct_taxes)))                   [subTotalWithDiscountI_IIPlusTAXES] ,

			CONVERT(DECIMAL(19,2),
			(ct.ct_discount - @decTotalDiscountI_II)
			* (ct.ct_total / dbo.fnNoZDiv(ct.ct_total - ct.ct_taxes)))                   [totalDiscountWithOutDiscountI_IIPlusTAXES] ,


			@strPriceListName															[customerPriceListName]
			-- FORRADA de GB de ticket 22217



		-- MOS 01-2023
		-- ATENCION!!!!!!!
		-- Si se agregan JOIND a tbCommercialtransactions hay que SI O SI agregar campos del join al INCLUDE del indice IX_tbCommercialTransactions_1OLP tal como está en **wnfk129847laknfqwf
	from	dbo.tbCommercialTransactions					ct					WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))	-- MOS 01-2023: Se fuerza a usar este indice ya que tiene los campos de JOIN usados en el INCLUDE y asi no hay que ir a cada registro de la BD para hacer los JOINS

			LEFT JOIN tbsysDocuments						tsd					WITH (NOLOCK)
			ON tsd.sd_id				= ct.sd_id

			LEFT JOIN tbCommercialTransactions				tct1				WITH (NOLOCK)					-- Busca la posible factura de este posible remito
			ON	tct1.comp_id			= ct.comp_id
			AND tct1.ct_transaction		= ct.ct_transaction_PackingList

			inner join #tmpTaxes							tmpTAXES
			on	tmpTAXES.comp_id		= ct.comp_id
			and tmpTAXES.ct_transaction	= ct.ct_transaction

			INNER JOIN tbBranch								tb					WITH (NOLOCK)
			ON tb.comp_id = ct.comp_id
			AND tb.bra_id = ct.bra_id

			left join dbo.tbSalesman						sm					WITH (NOLOCK)
			on	sm.comp_id				= ct.comp_id	AND
				sm.sm_id				= ct.sm_id

			left join dbo.tbUser							us					WITH (NOLOCK)
			on us.user_id				= ct.user_id

			left join dbo.tbCustomer						cust				WITH (NOLOCK)
			on  cust.comp_id				= ct.comp_id AND
				cust.cust_id				= ct.cust_id


			LEFT JOIN tbCustomerFamily						tcf					WITH (NOLOCK)
				ON	tcf.comp_id		= ct.comp_id AND
					tcf.cust_id		= ct.cust_id AND
					tcf.custf_id	= ct.custf_id

			LEFT JOIN tbcustomer							tcG					WITH (NOLOCK)
				ON	tcG.comp_id = ct.comp_id AND
					tcG.cust_id = ct.cust_id_guarantor


			LEFT JOIN tbsysFEX_CUIT2Country					tfcp				WITH (NOLOCK)
				ON tfcp.fex_cuitID = cust.fex_cuitID

			left join [dbo].[tbDocumentsFile]				TDF					WITH (NOLOCK)
			on	ct.comp_id					= tdf.comp_id	AND
				ct.df_id					= tdf.[df_id]

			left join [dbo].[tbSalesTerms]					TST					WITH (NOLOCK)
			on	tst.comp_id				= ct.comp_id AND
				tst.[st_id]				= ct.st_id

			LEFT JOIN tbCreditCard							tcc					WITH (NOLOCK)
				ON	tcc.comp_id = TST.comp_id AND
					tcc.cc_id	= TST.cc_id

			LEFT JOIN tbCreditCardLoanPlan					tcclp				WITH (NOLOCK)
				ON	tcclp.comp_id	= ct.comp_id AND
					tcclp.ccp_id    = ct.ccp_id


			left join [dbo].[tbDiscount]					TD					WITH (NOLOCK)
			on	td.comp_id					= ct.comp_id	AND
				td.[disc_id]				= ct.[disc_id]

			left join [dbo].[tbDelivery]					TD2					WITH (NOLOCK)
			on	td2.comp_id				= ct.comp_id  AND
				td2.[dl_id]				= ct.dl_id

			LEFT JOIN tbsysFEIncoTerms						tft					WITH (NOLOCK)
				ON tft.id = td2.incoid

			LEFT JOIN tbsysFECountryID						tfi					WITH (NOLOCK)
				ON tfi.fecountry_id = cust.fecountry_id

			left join [dbo].[tbsysState]					TS					WITH (NOLOCK)
			on	ts.country_id			= CUST.country_id	 AND
				TS.[state_id]			= CUST.[state_id]

			left join [dbo].[tbsysCountry]					TC					WITH (NOLOCK)
			on TC.[country_id]			= CUST.[country_id]

			left join dbo.tbCommercialTransactionNotes		CTN					WITH (NOLOCK)
			on	CTN.comp_id				= CT.comp_id
			and	CTN.bra_id				= CT.bra_id
			and CTN.ct_transaction		= CT.ct_transaction

			LEFT JOIN tbCustomerBranch						tcb					WITH (NOLOCK)
				ON		tcb.comp_id = ct.comp_id
					AND tcb.cust_id = ct.cust_id
					AND tcb.cb_id	= ct.cb_id

			left JOIN tbsysState							ts2					WITH (NOLOCK)
			ON	ts2.country_id	= tcb.country_id AND
				ts2.state_id	= tcb.state_id

			left JOIN tbsysCountry							tc2					WITH (NOLOCK)
			ON tc2.country_id = tcb.country_id

			LEFT JOIN tbsysTaxNumberTypes					ttnt				WITH (NOLOCK)
				ON ttnt.tnt_id			= cust.tnt_id

			LEFT JOIN vwsysTax_ChileActividad				cha					WITH (NOLOCK)
				ON cha.stca_id = cust.stca_id

			--LEFT JOIN tbSaleOrderHeaderHistory tsohh
			--	ON	tsohh.comp_id			= @comp_id AND
			--		tsohh.ct_transaction	= @ct_transaction

			LEFT JOIN tbProject							AS tp					WITH (NOLOCK)
				ON	tp.comp_id	= ct.comp_id		AND
					tp.pro_id	= ct.pro_id

			LEFT JOIN tbCommercialTransactions_QRImage	AS tctq					WITH (NOLOCK)
				ON	tctq.comp_id		= @comp_id	AND
					tctq.ct_transaction = @ct_transaction

	where	ct.comp_id					= @comp_id
	and		ct.ct_transaction			= @ct_transaction




	Drop Table #tmpTaxMovements
	Drop Table #tmpTaxes
	Drop Table #tmpIBPerceptions

END
GO






CREATE PROCEDURE [dbo].spCommercialTransactions_getDataById_4AdditionalDocumentsPrintOrMail
(
	@comp_id		as	int,
	@ct_transaction	as	INT,
	@df_id			AS INT,
	@UserId			AS	INT,
	@prof_id		AS  INT,
	@lang_id		AS  INT
)
AS


BEGIN


	SELECT
			dbo.fnGetCommercialTransactionDescription4DF_ID(@comp_id,
															@lang_id,
															@ct_transaction,
															@df_id)		[InvoiceNumber]

END
GO






CREATE PROCEDURE [dbo].[spCommercialTransactions_getDataById_Fastest]
(
	@comp_id		as	int,
	@ct_transaction	as	INT,
	@UserId			AS	INT,
	@prof_id		AS  INT,
	@lang_id		AS  INT
)
AS


BEGIN

	--declare @decDfExchange2Branch		as DECIMAL(19,6) --

	-- ----------------------------------------------
	-- Datos para Factura Electronica de Exportacion.
	-- ----------------------------------------------
	DECLARE @bitIsPermisoEmbarque AS BIT
	IF EXISTS(SELECT 	TOP 1 1
				FROM tbCommercialTransactionsEmbarkOK tcteo			WITH (NOLOCK)
					WHERE	tcteo.comp_id			= @comp_id
						AND tcteo.ct_transaction	= @ct_transaction)

		set @bitIsPermisoEmbarque = 'True'
	ELSE
		set @bitIsPermisoEmbarque = 'False'
	-- ----------------------------------------------


	SELECT TOP 1
	       tct.ct_docNumber,
	       tct.ct_kindOf,
	       tct.ct_pointOfSale,
	       tc.cust_taxNumber
	    INTO #tmpApplied
	    FROM tbItemTransactions tit             WITH (NOLOCK)
	    INNER JOIN tbCommercialTransactions tct WITH (NOLOCK)
	    ON tct.comp_id           = tit.comp_id        AND
	       tct.bra_id            = tit.bra_id         AND
	       tct.ct_transaction    = tit.ct_transaction
	    INNER JOIN tbCustomer tc   WITH (NOLOCK)
	    ON tc.cust_id            = tct.ws_cust_Id AND
	       tc.comp_id            = tct.comp_id
	    WHERE tit.comp_id        = @comp_id AND
	          tit.ct_transaction = @ct_transaction AND
	          tit.it_transaction_original IS NOT NULL






	SELECT	tct.* ,
			ISNULL(tct.ct_payDate,GETDATE())								[PaymentDate],
			ttnt.tnt_afip,
			CASE
				WHEN tdf.curr_id4ElectronicInvoice = 1		THEN 'PES'
				WHEN tdf.curr_id4ElectronicInvoice = 2		THEN 'DOL'
				--WHEN tdf.curr_id4ElectronicInvoice = 162	THEN 'DOL'
				ELSE										'PES'
			END																[currency4ElectronicInvoice],
			tct.ct_dfExchange												[dfExchange2Branch],
			tdf.fedt_id													    [fedt_id],
			cust.cust_taxNumber,
			(tct.ct_subtotal - tct.ct_discount)								[ct_subtotalWithDiscount],
			ISNULL(tct.mlo_id,-1)											[_MLO_Id]	,
			dbo.fnGetCommercialTransactionDescription(@comp_id,
													  @lang_id,
													  @ct_transaction)		[InvoiceNumber]	,
			dbo.fnGetCommercialTransactionRelatedCT(  @comp_id,
													  @lang_id,
													  @ct_transaction)		[PackingListNumber]	,
			ISNULL(tfcp.fex_cuit,'')					[strFEX_cuit],
			ISNULL(cust.fecountry_id,'')				[strFEcountry_id],
			cust.cust_name,
			cust.cust_address	,
			ISNULL(tfi.fecountry_desc,'')				[strFEcountry_Desc],
			ISNULL(tft.inco_Id,'')						[strInco_ID],
			ISNULL(tft.inco_desc,'')					[strInco_Desc],
			@bitIsPermisoEmbarque						[bitIsPermisoEmbarque]	,
			ISNULL(tst.st_desc,'')						[st_desc],
			tdf.df_FEXPEP,
			tdf.df_FEXCpto	,
			cust.cust_address,
			cust.cust_city	,
			cust.comp_id,
			ts.state_desc								[cust_state]	,
			tdf.df_MercadoLibre_BlockInvoiceAttachment		,
			ISNULL(tdf.df_electronicInvoiceFCCredito_Enabled,'False')					[df_electronicInvoiceFCCredito_Enabled],
			ISNULL(tdf.df_electronicInvoiceFCCredito_ESANULACION,'')					[df_electronicInvoiceFCCredito_ESANULACION],
			ISNULL(tdf.df_electronicInvoiceFCCredito_ALIAS,'')							[df_electronicInvoiceFCCredito_ALIAS],
			ISNULL(tdf.df_electronicInvoiceFCCredito_CBU,'')							[df_electronicInvoiceFCCredito_CBU],
			DATEADD(DAY,ISNULL(tst.st_creditInvoice_chequeDays,1),tct.ct_taxDate)		[ctc_MiPymeVto],
			ISNULL(tct.ct_note,'')														[ct_note],
			ISNULL(tdf.df_ElectronicInvoice_MiPyme_Mode,-1)								[df_ElectronicInvoice_MiPyme_Mode]

		FROM tbCommercialTransactions					tct					WITH (NOLOCK)
		LEFT JOIN tbDocumentsFile						tdf					WITH (NOLOCK)
			ON	tdf.comp_id = tct.comp_id AND
				tdf.df_id	= tct.df_id

		left join dbo.tbCustomer						cust				WITH (NOLOCK)
		on  cust.comp_id				= tct.comp_id AND
			cust.cust_id				= tct.cust_id

		left join [dbo].[tbsysState]					TS					WITH (NOLOCK)
		on	ts.country_id			= CUST.country_id	 AND
			TS.[state_id]			= CUST.[state_id]

		LEFT JOIN tbsysFEX_CUIT2Country					tfcp				WITH (NOLOCK)
			ON tfcp.fex_cuitID = cust.fex_cuitID

		LEFT JOIN tbsysFECountryID						tfi					WITH (NOLOCK)
			ON tfi.fecountry_id = cust.fecountry_id

		LEFT JOIN tbsysTaxNumberTypes					ttnt				WITH (NOLOCK)
			ON ttnt.tnt_id			= cust.tnt_id

		left join [dbo].[tbDelivery]					TD2					WITH (NOLOCK)
		on	td2.comp_id				= tct.comp_id  AND
			td2.[dl_id]				= tct.dl_id

		LEFT JOIN tbsysFEIncoTerms						tft					WITH (NOLOCK)
			ON tft.id = td2.incoid

		left join [dbo].[tbSalesTerms]					TST					WITH (NOLOCK)
		on	tst.comp_id				= tct.comp_id AND
			tst.[st_id]				= tct.st_id



		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @ct_transaction


END
GO







