CREATE PROCEDURE [dbo].[spCommercialTransactions_getDataById4Loan]
(
	@comp_id		as	int,
	@ct_transaction	as	INT,
	@UserId			AS	INT
)
AS

BEGIN


	SELECT	tctl.ctl_payNumber,
			tctl.ctl_payDate,
			tctl.ct_ATotal,
			tctl.ct_ABalance,
	 		'#' + dbo.fnStrPADL( convert(nvarchar(5),tctl.ctl_payNumber), 2, '0') + ' ' +
	 		CONVERT(NVARCHAR(20),tctl.ctl_payDate,3) + '   $ ' +
	 		dbo.fnStrAllTrim( dbo.fnStrPADL(CONVERT(NVARCHAR(50),CONVERT(DECIMAL(19,2),tctl.ct_ABalance)),12,' '))	[Print]
		FROM tbCommercialTransactions tct							WITH (NOLOCK)
		INNER JOIN tbCommercialTransactionsLoan tctl				WITH (NOLOCK)
			ON	tctl.comp_id		= tct.comp_id			AND
				tctl.ct_transaction = tct.ct_transaction

		WHERE	tct.comp_id			= @comp_id				AND
				tct.ct_transaction	= @ct_transaction
		ORDER BY tctl.ctl_payNumber


END
GO



CREATE PROCEDURE [dbo].[spCommercialTransactions_GetDataBySerial4PCConfigRMA]
(
	@comp_id	INT,
	@lang_id	INT,
	@ItemSerial	NVARCHAR(100)
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@ItemSerial	NVARCHAR(100)
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@ItemSerial	= 'ZZ9900'
		*/
		-- -----------------------------------------------------------

		DECLARE
			@ct_transaction	INT



		SELECT
			@ct_transaction = tct.ct_transaction
			FROM tbCommercialTransactions							tct		WITH (NOLOCK)
				INNER JOIN tbItemTransactionSerials					tits	WITH (NOLOCK)
					ON	tits.comp_id		= tct.comp_id			AND
						tits.ct_transaction = tct.ct_transaction
				INNER JOIN tbItemSerials							tis	WITH (NOLOCK)
					ON	tis.comp_id			= tits.comp_id			AND
						tis.is_id			= tits.is_id
				INNER JOIN tbItemTransactions						tit	WITH (NOLOCK)
					ON	tit.comp_id			= tct.comp_id			AND
						tit.ct_transaction	= tct.ct_transaction
			WHERE		tct.comp_id			= @comp_id				AND
						tis.is_serial		= @ItemSerial			AND
						(
							tct.sd_id	= 1 OR
							tct.sd_id	= 2
						)											AND
						tit.it_isFromPCConfigCTRLId	IS NOT NULL


		SELECT
			ti.item_code,
			ti.item_desc,
			tit.it_qty,
			tit.it_guarantee
		FROM tbCommercialTransactions							tct	WITH (NOLOCK)
			INNER JOIN tbItemTransactions						tit	WITH (NOLOCK)
				ON	tit.comp_id			= tct.comp_id			AND
					tit.ct_transaction	= tct.ct_transaction
			INNER JOIN tbItem									ti	WITH (NOLOCK)
				ON	ti.comp_id			= tct.comp_id			AND
					ti.item_id			= tit.item_id
		WHERE	tct.comp_id				= @comp_id				AND
				tct.ct_transaction		= @ct_transaction		AND
				tit.it_isFromPCConfigCTRLId IS NOT NULL




	END






GO



CREATE PROCEDURE [dbo].[spCommercialTransactions_GetDataBySerial4PCConfigRMA_ExistsItem]
(
	@comp_id	INT,
	@lang_id	INT,
	@ItemSerial	NVARCHAR(100)
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@ItemSerial	NVARCHAR(100)
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@ItemSerial	= 'XX9900'
		*/
		-- -----------------------------------------------------------

		IF EXISTS(SELECT TOP 1  1
					FROM tbCommercialTransactions							tct	WITH (NOLOCK)
						INNER JOIN tbItemTransactionSerials					tits	WITH (NOLOCK)
							ON	tits.comp_id		= tct.comp_id			AND
								tits.ct_transaction = tct.ct_transaction
						INNER JOIN tbItemSerials							tis	WITH (NOLOCK)
							ON	tis.comp_id			= tits.comp_id			AND
								tis.is_id			= tits.is_id
						INNER JOIN tbItemTransactions						tit	WITH (NOLOCK)
							ON	tit.comp_id			= tct.comp_id			AND
								tit.ct_transaction	= tct.ct_transaction
					WHERE		tct.comp_id			= @comp_id				AND
								tis.is_serial		= @ItemSerial			AND
								(
									tct.sd_id	= 1 OR
									tct.sd_id	= 2
								)											AND
								tit.it_isFromPCConfigCTRLId IS NOT NULL)
			BEGIN
				SELECT 'True'
			END
		ELSE
			BEGIN
				SELECT 'False'
			END

	END

GO


