CREATE PROCEDURE [dbo].[spCommercialTransactions_getDataForBranchTransfer]
(
  	@comp_id			INT,
  	@lang_id			INT,
  	@bra_id				INT,
	@docNumber			NVARCHAR(50),
	@ct_bra_id			INT,
	@prof_id			INT,
	@ct_transaction		INT
)
AS


BEGIN

--SELECT * FROM tbBranch tb
--SELECT * FROM tbBranchTransferreceptionControl tbtc



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- -----------------------------------------------------
/*
	DECLARE	@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@docNumber	NVARCHAR(50),
			@ct_bra_id	int,
			@prof_id	INT


	SELECT	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@docNumber	= '0',
			@ct_bra_id	= -1,
			@prof_id	= 1

DROP TABLE #tmpBranchTransfers
*/
-- ------------------------------------------------------


	SELECT	convert(bit,isnull(tctt.ctct_origin,0))											[state],
  			tct.ct_date																		[ct_date],
  			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [doc_Number],
  			tb.bra_desc																		[bra_desc],



  			(SELECT TOP 1 ISNULL(ts.stor_desc,'')
  					FROM tbItemTransactions					 tit		WITH (NOLOCK)
  					INNER JOIN tbStorage					 ts			WITH (NOLOCK)
  					 ON ts.comp_id			= tit.comp_id AND
  						ts.stor_id			= tit.stor_id
  					WHERE   tit.comp_id					= tct.comp_id
  					AND		tit.bra_id					= tct.bra_id
  					AND		tit.ct_transaction			= tct.ct_transaction


  			)																				[stor_desc_ori],			-- deposito de origen tkt 18354

			 tu2.user_lastname + ', ' + tu2.user_firstname									[user_branchtransfer],		-- MOS 10-2023 fix de abajo, bien hecho.

			-- que ES ESTO GA ????????????????????  en serio ?????????????????????????????????????  Encima con el where INCOMPLETO, sin la PK... LENTISIMOOO, imposible trabajar y reventaba toda la BD
			-- el de arriba estaba ok.. igual era al PEDO poner el join si el usuario lo sacabas de la tct que ya estaba abajo...
  			 --(SELECT TOP 1 tu2.user_lastname + ', ' + tu2.user_firstname
  				--	FROM  tbItemTransactions						 tit		WITH (NOLOCK)
  				--	INNER JOIN tbUser 								 tu2		WITH (NOLOCK)
  				--	ON tu2.[user_id] = tct.[user_id]
  				--	WHERE   tit.ct_transaction			= tct.ct_transaction
  			 --)																				[user_branchtransfer],	-- usuario de la transferencia tkt 18354


  			-- NO poner NADA despues de esta seccion
  			tct.ct_transaction																[ct_transaction],
  			convert(varchar,tct.ct_transaction) + '|'+ convert(varchar,tbcsi.supp_id)		[ID]

	INTO	#tmpBranchTransfers
	FROM	tbCommercialTransactions							tct			WITH (NOLOCK)

  			INNER JOIN tbBranch2Customer4StockImport			tbcsi		WITH (NOLOCK)
  				ON  tbcsi.comp_id					= tct.comp_id
  				AND	tbcsi.bra_id					= @bra_id
  				AND tbcsi.bra_id_original			= tct.bra_id
  				AND tbcsi.cust_id					= tct.cust_id
  				AND tbcsi.cb_id						= tct.cb_id

			INNER JOIN tbBranch									tb			WITH (NOLOCK)
				ON	tb.comp_id						= tct.comp_id AND
					tb.bra_id						= tct.bra_id

  			INNER JOIN tbDocumentsFile							tdf			WITH (NOLOCK)
  				ON  tdf.comp_id						= tct.comp_id
  				AND tdf.bra_id						= tct.bra_id
  				AND tdf.df_id						= tct.df_id

  			LEFT JOIN tbCommercialTransactionsTmp				tctt		WITH (NOLOCK)
  				ON  tctt.comp_id					= tct.comp_id
  				AND tctt.bra_id						= tct.bra_id
  				AND tctt.ctct_transaction			= tct.ct_transaction
  				AND tctt.ctct_origin				= '1'

  			LEFT JOIN tbUser								AS tu2			WITH (NOLOCK)
  				ON tu2.[user_id] = tct.[user_id]

	WHERE		tct.comp_id							= @comp_id
		AND		tct.sd_id							= 2				--==Solia ser (1,2) Solo se hara sobre remitos por el tema de los asientos.
		AND	    tct.ct_Pending						= 'True'
		AND		ISNULL(tct.ct_isCancelled,'False')  = 'False'
		AND		tdf.df_isInterBranchDocument		= 'True'	-- estaba en el inner, lo pase aca 9-2017
		AND		tbcsi.supp_id				IS NOT NULL
		AND		(@ct_bra_id = -1		OR tct.bra_id		= @ct_bra_id  )
		AND		(tbcsi.prof_id IS NULL	OR tbcsi.prof_id	= @prof_id )
		AND		(@docNumber = 0			OR  tct.ct_docNumber LIKE '%' + @docNumber + '%')
		AND		CASE
					WHEN @ct_transaction	= 0					THEN 1
					WHEN tct.ct_transaction	= @ct_transaction	THEN 1
					ELSE											 0
				END = 1


	ORDER BY tct.ct_date



	DELETE #tmpBranchTransfers
		FROM #tmpBranchTransfers			tmpbt
		WHERE NOT EXISTS(
			SELECT TOP 1  1
				FROM	tbItemTransactions			tit			WITH (NOLOCK)
				where	tit.comp_id			= @comp_id
				AND		tit.ct_transaction	= tmpbt.ct_transaction
				AND     tit.item_id IS NOT NULL)

	SELECT
		' ' [ ],
		' ' [ ],
		' ' [ ],
		' ' [ ],
		[state],
		[ct_date],
		[doc_Number],
		[bra_desc],
		[stor_desc_ori],
		[user_branchtransfer],
		[ID]

  		FROM #tmpBranchTransfers

		ORDER BY [ct_date]

	DROP TABLE #tmpBranchTransfers

END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactions_GetDataOfReceiptDetail]
	@comp_id			INT,
	@ct_transaction		INT,
	@option				INT,
	@lang_id			INT
AS
BEGIN




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @strQuote AS NVARCHAR(50)
	SET		@strQuote = ' / Cuota #:'

	--Como se COBRÓ
	SELECT	'Valores Entregados'						[Description],
			''											[Description2],
			0											[Total],
			''											[Currency],
			-1											[ID],
			5											[Order],
			''											[Item]

	UNION ALL

	Select vc.[Description]								[Description],
		   vc.[type] + ': ' + vc.[desc]					[Description2] ,
		   vc.amount									[Total],
		   vc.currency									[Currency],
		   vc.ID										[ID],
		   10											[Order],
		   ''											[Item]

		From vwCollection vc				WITH (NOLOCK)
		WHERE	vc.comp_id			=	@comp_id
		AND		vc.lang_id			=	@lang_id
		AND		vc.ct_transaction	=	@ct_transaction
		AND		vc.class <> 100
	--	ORDER BY vc.class,vc.Date









	UNION ALL








	--Retenciones
	SELECT	'Retenciones / Impuestos'					[Description],
			''											[Description2],
			0											[Total],
			''											[Currency],
			-1											[ID],
			15											[Order],
			''											[Item]
	WHERE EXISTS( -- Pone el titulo si hay algo en lo que busca abajo
					SELECT  ttn.tax_desc								[Description],
							''											[Description2],
							ttm.tm_total								[Total],
							tc.curr_desc								[Currency],
							ttm.tm_transaction							[ID],
							20											[Order]
						FROM	tbTaxMovements						ttm	WITH (NOLOCK)
						INNER JOIN tbTaxName				ttn	WITH (NOLOCK)
							ON	ttn.comp_id		=	ttm.comp_id
							AND	ttn.tax_id		=	ttm.tax_id

						INNER JOIN tbsysCurrency			tc	WITH (NOLOCK)
							ON	tc.curr_id		=	ttm.curr_id

						WHERE	ttm.comp_id			=	@comp_id
						AND		ttm.ct_transaction	=	@ct_transaction
				)

	UNION ALL

	SELECT  ttn.tax_desc								[Description],
			''											[Description2],
			ttm.tm_total								[Total],
			tc.curr_desc								[Currency],
			ttm.tm_transaction							[ID],
			20											[Order],
			''											[Item]
		FROM	tbTaxMovements						ttm	WITH (NOLOCK)
		INNER JOIN tbTaxName				ttn
			ON	ttn.comp_id		=	ttm.comp_id
			AND	ttn.tax_id		=	ttm.tax_id

		INNER JOIN tbsysCurrency			tc	WITH (NOLOCK)
			ON	tc.curr_id		=	ttm.curr_id

		WHERE	ttm.comp_id			=	@comp_id
		AND		ttm.ct_transaction	=	@ct_transaction








	UNION ALL








	-- Aplicado a
	SELECT	'Comprobantes Aplicados'					[Description],
			''											[Description2],
			0											[Total],
			''											[Currency],
			-1											[ID],
			25											[Order],
			''											[Item]

	UNION ALL

	SELECT 	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) +
			CASE
				WHEN tctl.comp_id IS NOT NULL THEN	@strQuote +
													CONVERT(NVARCHAR(5), tctl.ctl_payNumber)		+ '/' +
													CONVERT(NVARCHAR(5), tctl.ctl_payNumberTotalQty)
				ELSE ''
			END																			[Description],
			'Vencimiento:' +
			CASE
				WHEN tctl.comp_id IS NOT NULL THEN CONVERT(NVARCHAR(50),tctl.ctl_payDate,103)
				ELSE							   CONVERT(NVARCHAR(50),tct.ct_payDate,103)
			END																			[Description2],
			ta.appl_total																[Total],
			tc.curr_desc																[Currency],
			tct.ct_transaction	+ ISNULL(tctl.ctl_id,0)									[ID],
			30																			[Order],
			ISNULL( -- Detalle del Primer Item de la Factura . . .
				   (
				   	SELECT TOP 1  titd.itm_desc
						FROM tbItemTransactions tit
						LEFT JOIN tbItemTransactionDetails titd
						ON	titd.comp_id		= tit.comp_id			AND
							titd.bra_id			= tit.bra_id			AND
							titd.ct_transaction = tit.ct_transaction	AND
							titd.it_transaction = tit.it_transaction
						WHERE	tit.comp_id			= @comp_id AND
								tit.ct_transaction	= ta.ct_transaction_Source
						ORDER BY tit.it_order
				   )
					,ISNULL(
						(
				   		SELECT TOP 1  ti.item_desc
							FROM tbItemTransactions tit
							INNER JOIN tbItem ti
								ON	ti.comp_id = tit.comp_id AND
									ti.item_id = tit.item_id
							WHERE	tit.comp_id			= @comp_id AND
									tit.ct_transaction	= ta.ct_transaction_Source
							ORDER BY tit.it_order)
						,''))																[Item]

		FROM	tbApplication ta		WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions tct	WITH (NOLOCK)
				ON tct.comp_id			= ta.comp_id
				AND tct.ct_transaction	= ta.ct_transaction_Source

				LEFT JOIN tbCommercialTransactionsLoan tctl	WITH (NOLOCK)
					ON	tctl.comp_id		= ta.comp_id				AND
						tctl.ct_transaction = ta.ct_transaction_Source	AND
						tctl.ctl_id			= ta.ctl_id_Source



				Inner Join tbsysCurrency tc	WITH (NOLOCK)
				On tc.curr_id			= ta.appl_currency

				Inner Join tbsysCurrency tc2	WITH (NOLOCK)
				On tc2.curr_id			= tct.ct_ACurrency

				Inner Join tbsyscurrency tc3	WITH (NOLOCK)
				On tc3.curr_id			= tct.ct_ACurrency

		WHERE	ta.comp_id					= @comp_id
		AND		ta.ct_transaction_destiny	= @ct_transaction
		And     ta.ct_transaction			= @ct_transaction

		ORDER BY [Order],[ID]



	--	END

	--ELSE IF @option = 4
	--	BEGIN
	--		--documentos a cuenta
	--		--modificado STL 06/04/2011 cambie el CT.CT_TRANSACTION por el TA.CT_TRANSACTION_DESTINY

	--		DECLARE @strQuote AS NVARCHAR(50)
	--		SET		@strQuote = ' / Cuota #:'


	--		SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,ta.ct_transaction_destiny) +
	--				CASE
