CREATE PROCEDURE spCommercialTransactions_GetDocumentesAssigned2Import
(
	@comp_id	INT,
	@lang_id	INT,
	@import_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------

		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@import_id	INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@import_id	= 366

		*/
		-- -------------------------------------------------

		SELECT
			ISNULL(SUBSTRING(ts.supp_name,0,20),'') + ' - ' +
			dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tid.ct_transaction)	[Desc],
			tct.ct_transaction																		[ID]
			FROM tbCommercialTransactions								tct
			INNER JOIN vwCommercialTransactions_forPurchase				vctfp
				ON	vctfp.comp_id			= tct.comp_id				AND
					vctfp.ct_transaction	= tct.ct_transaction
			INNER JOIN tbSupplier										ts
				ON  ts.comp_id				= tct.comp_id				AND
					ts.supp_id				= tct.supp_id
			INNER JOIN tbImportDetail									tid
				ON	tid.comp_id = tct.comp_id							AND
					tid.ct_transaction = tct.ct_transaction
			WHERE	tct.comp_id						= @comp_id			AND
					tct.ct_isAvailableForImport		= 'True'			AND
					tid.import_id					= @import_id



	END
GO



CREATE PROCEDURE [dbo].[spCommercialTransactions_GetMovements4CreditCardLiquidation]
(
	@comp_id		INT,
	@ct_transaction	INT,
	@DataGridType	INT		--1 = Cupones / 2 = Conceptos / 3 = Impuestos
)
AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON

	-- ---------------------------------------------------------------
	-- TESTING
	-- ---------------------------------------------------------------
	/*
		DECLARE
			@comp_id		INT,
			@ct_transaction	INT,
			@DataGridType	INT	--1 = Cupones / 2 = Conceptos / 3 = Impuestos
		SELECT
			@comp_id		= 1,
			@ct_transaction	= 12783,
			@DataGridType	= 1
	*/
	-- ---------------------------------------------------------------

	--CUPONES
	IF @DataGridType = 1
		BEGIN
			SELECT
				' '											[ ],
				tccm.ccm_cardNumber,
				tccm.ccm_cardEmissionDate,
				tccm.ccm_cardExpirationDate,
				tccm.ccm_customerDocumentNumber,
				tccm.ccm_customerName,
				tccm.ccm_receiptNumber,
				tccm.ccm_Total,
				tc.curr_symbol,
				tccm.ccm_lote,
				tccg.ccg_desc								[ccg_desc],
				tcc.cc_desc									[creditcard_desc],
				tccm.ccm_id									[ID]

				FROM tbCreditCardLiquidationsMovements		tcclm	WITH(NOLOCK)

				INNER JOIN tbCommercialTransactions			tct		WITH(NOLOCK)
					ON	tct.comp_id			= tcclm.comp_id	AND
						tct.ct_transaction	= tcclm.ct_transaction
				INNER JOIN tbCreditCardMovements			tccm	WITH(NOLOCK)
					ON	tccm.comp_id		= tcclm.comp_id AND
						tccm.ccm_id			= tcclm.ccm_id

				LEFT JOIN tbCreditCard						tcc		WITH (NOLOCK)
					ON	tcc.comp_id			= tccm.comp_id			AND
						tcc.cc_id			= tccm.cc_id

				LEFT JOIN tbCreditCard_Group				tccg	WITH (NOLOCK)
					ON	tccg.comp_id		= tcc.comp_id			AND
						tccg.ccg_id			= tcc.ccg_id

				INNER JOIN tbsysCurrency				tc			WITH(NOLOCK)
					ON	tc.curr_id			= tccm.curr_id
				WHERE	tcclm.comp_id			= @comp_id AND
						tcclm.ct_transaction	= @ct_transaction
		END


	--CONCEPTOS
	IF @DataGridType = 2
		BEGIN
			SELECT
				' '											[ ],
				tcc.cc_desc,
				tpc.puco_desc,
				tc.curr_symbol,
				tpcm.pcm_total,
				tpcm.pcm_note1,
				tpcm.pcm_note2,
				tpcm.pcm_id 								[ID]
				FROM tbPurchaseConceptMovements				tpcm	WITH(NOLOCK)
				INNER JOIN tbsysCurrency					tc		WITH(NOLOCK)
					ON	tc.curr_id			= tpcm.curr_id
				INNER JOIN tbCostCenter						tcc		WITH(NOLOCK)
					ON	tcc.comp_id			= tpcm.comp_id	AND
						tcc.cc_code			= tpcm.cc_code
				INNER JOIN tbPurchaseConcept				tpc		WITH(NOLOCK)
					ON	tpc.comp_id			= tpcm.comp_id	AND
						tpc.puco_id			= tpcm.puco_id
				WHERE	tpcm.comp_id		= @comp_id		AND
						tpcm.ct_transaction = @ct_transaction
		END


	--IMPUESTOS
	IF @DataGridType = 3
		BEGIN
			SELECT
				' '											[ ],
				ttn.tax_desc,
				tc.curr_symbol,
				ttm.tm_subtotal,
				ttm.tm_total,
				ttm.percentaje,
				ttm.tm_transaction							[ID]
				FROM tbTaxMovements							ttm		WITH(NOLOCK)
				INNER JOIN tbTaxName						ttn		WITH(NOLOCK)
					ON	ttn.comp_id			= ttm.comp_id	AND
						ttn.tax_id			= ttm.tax_id
				INNER JOIN tbsysCurrency					tc		WITH(NOLOCK)
					ON	tc.curr_id			= ttm.curr_id
				WHERE	ttm.comp_id			= @comp_id		AND
						ttm.ct_transaction	= @ct_transaction
		END
END










GO



