CREATE PROCEDURE [dbo].[spCommercialTransactions_getReport]
(
			@comp_id			INT,
			@lang_id			INT,
			@page_id			INT,

			@selection_id		INT,
			@datefrom			DATETIME,
			@dateto				DATETIME,
			@datefromvto		DATETIME,
			@datetovto			DATETIME,
			@custsupp			INT,
			@sm_id				INT,
			@dl_id				INT,
			@ck_id				INT,
			@bra_id				INT,
			@country_id			INT,
			@state_id			INT,
			@ss_id				INT,
			@balancefrom		DECIMAL(19,2),
			@balanceto			DECIMAL(19,2),
			@ispurchase			BIT,
			@option				INT,
			@user_id			INT,
			@curr_id			int,
			@orderby			int,
			@sk_id				INT,
			@pt_id				INT,
			@intBranch4Lang		int,
			@brag_id			INT,
			@guid				VARCHAR(50)
)
AS

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-----------------------------------------------------------------
	-- Testing
	-----------------------------------------------------------------
	/*
	declare		@comp_id			int,
				@lang_id			int,
				@page_id			int,

				@selection_id		int,
				@datefrom			datetime,
				@dateto				datetime,
				@datefromvto		datetime,
				@datetovto			datetime,
				@custsupp			int,
				@sm_id				int,
				@dl_id				int,
				@ck_id				int,
				@bra_id				int,
				@brag_id			int,
				@country_id			int,
				@state_id			int,
				@ss_id				int,
				@balance			decimal,
				@balancefrom		DECIMAL(19,2),
				@balanceto			DECIMAL(19,2),
				@ispurchase			bit,
				@user_id			int,
				@option				INT,
				@curr_id			int,
				@orderby			int,
				@sk_id				INT,
				@pt_id				INT,
				@intBranch4Lang		INT,
				@guid				UNIQUEIDENTIFIER

	select 		@comp_id			=1,
				@lang_id			=2,
				@page_id			=10009,

				@selection_id		=-1,
				@datefrom			='2000-06-01',
				@dateto				='2915-06-30',
				@datefromvto		='2000-06-01',
				@datetovto			='2915-06-30',
				@custsupp			=-1,
				@sm_id				=-1,
				@dl_id				=-1,
				@ck_id				=-1,
				@bra_id				=-1,
				@brag_id			=-1,
				@country_id			=-1,
				@state_id			=-1,
				@ss_id				=-1,
				@balancefrom		='-99999999',
				@balanceto			= '99999999',
				@ispurchase			='True',
				@user_id			=3,
				@option				=1,
				@curr_id			= 1,
				@sk_id				= -1,
				@pt_id				=-1,
				@orderby			= 2,
				@intBranch4Lang		= 1,
				@guid				 = 'a2a4b276-5873-4e09-a1cc-6f495ed4ecc0'
	*/
	-- -------------------------------------------------------------------------------


	set	@datefrom		= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto			= dbo.fnGetEnd_or_BeginOfDate(@dateto	,'True')

	set	@datefromvto	= dbo.fnGetEnd_or_BeginOfDate(@datefromvto,'False')
	set	@datetovto		= dbo.fnGetEnd_or_BeginOfDate(@datetovto,'True')

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros
	-- NOTA: Para buscar todas las incidencias
	-- de este método ejecutar el "BuscarTexto" en la base de datos
	-- con el valor de referencia "#8600"
	-- Página de EJEMPLO:App_Reports_App_WebForms_wfmRptFilters_PriceLists2_Testing
	-- -------------------------------------------------------------
	DECLARE @objGUID AS UNIQUEIDENTIFIER
	SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@guid)
	DECLARE @tblComplexFilter_CustSupp TABLE (custsupp_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_CustSupp
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf      WITH (NOLOCK)
			WHERE tcf.sl_guid = @objGUID      AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			IF @ispurchase = 'True'
				BEGIN
					INSERT INTO @tblComplexFilter_CustSupp
						SELECT su.supp_id
							FROM tbSupplier su     WITH (NOLOCK)
							WHERE su.comp_id = @comp_id
				END
			ELSE
				BEGIN
					INSERT INTO @tblComplexFilter_CustSupp
						SELECT su.cust_id
							FROM tbCustomer su     WITH (NOLOCK)
							WHERE su.comp_id = @comp_id
				END
		END
	-- -------------------------------------------------------------




	DECLARE @fun_id INT
	SET @fun_id = 1

--	-- Para que sea mas rapido si no se usa filtro por saldo de cuenta corriente
--	DECLARE @bitIsAmmountFilter AS BIT
--	SET @bitIsAmmountFilter =	case
--									when @balancefrom = -99999999 AND @balanceto = 99999999 THEN 'False'
--									ELSE 'True'
--								END



	-- Toma la Fecha de Procesamiento de la sucursal y la moneda
	DECLARE @bra_proccesingdate	DATETIME
	DECLARE @bra_curr_id		INT
	SELECT @bra_proccesingdate = tb.bra_processingDate,
		   @bra_curr_id		   = tb.curr_id
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @intBranch4Lang


	-- ---------------------------------------------
	-- Selecciona las sucursales a tener en cuenta
	-- Si se informa un Grupo, son las del grupo
	-- y sino la informada o
	-- ---------------------------------------------
	DECLARE @tmpBranchs AS TABLE(bra_id INT PRIMARY KEY)
	IF @brag_id = -1
		BEGIN
			IF @ispurchase = 'True'
				BEGIN
					INSERT INTO @tmpBranchs ( bra_id)
						SELECT DISTINCT bra_id
						FROM tbBranch tb	WITH (NOLOCK)
						WHERE tb.comp_id		= @comp_id	AND
		    				  CASE
	    					      WHEN @bra_id <> -1 AND tb.bra_id						= @bra_id	THEN	1
	    					      WHEN @bra_id =  -1 AND tb.rep_SuppAccStatusIncluded	= 'True'	THEN	1
	    					      ELSE																		0
		    				  END = 1
				END
			ELSE
				BEGIN
					INSERT INTO @tmpBranchs ( bra_id)
						SELECT DISTINCT bra_id
						FROM tbBranch tb	WITH (NOLOCK)
						WHERE	tb.comp_id		= @comp_id	AND
		    				  CASE
	    					      WHEN @bra_id <> -1 AND tb.bra_id						= @bra_id	THEN	1
	    					      WHEN @bra_id =  -1 AND tb.rep_CustAccStatusIncluded	= 'True'	THEN	1
	    					      ELSE																		0
		    				  END = 1

				END

		END
	ELSE -- Todas las del grupo de sucursales
		BEGIN
			INSERT INTO @tmpBranchs (bra_id)
				SELECT DISTINCT tbg.bra_id
					FROM tbBranchGroupDetail tbg	WITH (NOLOCK)
					WHERE	tbg.comp_id = @comp_id AND
							tbg.brag_id = @brag_id
		END
	-- ---------------------------------------------


	-- para arreglar lko que un REVERENDO HIJO DE RE MIL PUTAS ENFERMO se le ocurrio hacer.
	DECLARE @t7 AS NVARCHAR(2000)
	SELECT  @t7 = tn7.word_desc
		FROM  [tbsysTextsNew]	t7									WITH (NOLOCK)
		INNER JOIN tbSysWordsNew	tn7									WITH (NOLOCK)
		ON tn7.wordsi_id = t7.wordsi_id
		AND tn7.lang_id	= @lang_id
		WHERE 	--t7.[lang_id]=@lang_id and
		t7.[page_id]=@page_id	and
		t7.[type_id]=32 AND
		t7.fun_id = 7

	DECLARE @t8 AS NVARCHAR(2000)
	SELECT  @t8 = tn8.word_desc
		FROM  [tbsysTextsNew]	t8									WITH (NOLOCK)
		INNER JOIN tbSysWordsNew tn8									WITH (NOLOCK)
		ON tn8.wordsi_id = t8.wordsi_id
		AND tn8.lang_id = @lang_id
		WHERE 	--t8.[lang_id]=@lang_id
			t8.[page_id]=@page_id			and
			t8.[type_id]=32 AND t8.fun_id = 8


	DECLARE @t10 AS NVARCHAR(2000)
	SELECT  @t10 = tn10.word_desc
		FROM  [tbsysTextsNew]	t10									WITH (NOLOCK)
		INNER JOIN tbSysWordsNew tn10									WITH (NOLOCK)
		ON tn10.wordsi_id = t10.wordsi_id
		AND tn10.lang_id = @lang_id
		WHERE	--t10.[lang_id]=@lang_id
		t10.[page_id]=@page_id and t10.[type_id]=32 AND t10.fun_id = 10


	DECLARE @t11 AS NVARCHAR(2000)
	SELECT  @t11 = tn11.word_desc
		FROM [tbsysTextsNew]	t11									WITH (NOLOCK)
		INNER JOIN tbSysWordsNew tn11									WITH (NOLOCK)
		ON tn11.wordsi_id = t11.wordsi_id
		AND tn11.lang_id = @lang_id
		WHERE	--t11.[lang_id]=@lang_id
		t11.[page_id]=@page_id and t11.[type_id]=32 AND t11.fun_id = 11



	DECLARE @t16 AS NVARCHAR(2000)
	SELECT  @t16 = tn16.word_desc
		FROM  [tbsysTextsNew]	t16									WITH (NOLOCK)
		INNER JOIN tbSysWordsNew tn16									WITH (NOLOCK)
		ON tn16.wordsi_id = t16.wordsi_id
		AND tn16.lang_id = @lang_id
		WHERE	--t16.[lang_id]=@lang_id
		t16.[page_id]=@page_id and t16.[type_id]=32 AND t16.fun_id = 16


	IF @ispurchase = 'False'

		BEGIN 	/* estado de cuentas de clientes */

			select	--ct.sd_id,
					CONVERT(VARCHAR,c.cust_id)					[ID],
					c.cust_name									[Name],
					c.cust_phone1								[Phone],
					CASE WHEN ct.sd_id = 6 OR ct.sd_id = 13	 THEN
						isnull(sm2.sm_name,'')
						ELSE
						isnull(sm.sm_name,'')
					END											[sm_name],
					c.cust_address								[Address],
					st.st_desc,
					ct_date,
					dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.ct_transaction)		[Comprobante],
					CASE WHEN td.sd_isInBalance = 'true' THEN
						ct_total		* vwct.PlusOrMinus
						ELSE 0
					END																						[ct_total],
					ct_payDate,

					CASE WHEN td.sd_isInBalance = 'true' THEN
						CONVERT(DECIMAL(19,2),
						dbo.fnGetExchange2(	@comp_id,
											CT.ct_abalance,
											CT.ct_ACurrency,
											@bra_curr_id ,
											ct.ct_ACurrency ,
											ct.curr_id_transaction ,
											ct.ct_ACurrencyExchange,
											'False')
																	* vwct.PlusOrMinus)
						 ELSE 0
					END																						[Balance],



					cr1.curr_desc																			[Curr_CT],

					CASE WHEN td.sd_isInBalance = 'true' THEN
						ct_ATotal		* vwct.PlusOrMinus
						ELSE 0
					END																						[ct_ATotal],

					CASE WHEN td.sd_isInBalance = 'true' THEN
						ct_ABalance		* vwct.PlusOrMinus
						ELSE 0
					END																						[ct_ABalance],


					fcgbs.cust_credit_balance																[cust_credit_balance],
					cr2.curr_desc																			[Curr_C_S],

					ct_ACurrencyExchange,
					replace(replace(replace(@t7 /*tn7.word_desc*/,'(MS)','('+sym.cb+')'),'(MC)','('+sym.cc+')'),'(MC)','('+sym.cc+')') [t7],
					replace(replace(replace(@t8 /*tn8.word_desc*/,'(MS)','('+sym.cb+')'),'(MC)','('+sym.cc+')'),'(MC)','('+sym.cc+')') [t8],
					replace(replace(replace(@t10/*tn10.word_desc*/,'(MS)','('+sym.cb+')'),'(MC)','('+sym.cc+')'),'(MC)','('+sym.cc+')') [t10],
					replace(replace(replace(@t11/*tn11.word_desc*/,'(MS)','('+sym.cb+')'),'(MC)','('+sym.cc+')'),'(MC)','('+sym.cc+')') [t11],
					replace(replace(replace(@t16/*tn16.word_desc*/,'(MS)','('+sym.cb+')'),'(MC)','('+sym.cc+')'),'(MC)','('+sym.cc+')') [t16],

					-- -------------------------------------------
					-- FIESA MOS 09-2021
					-- -------------------------------------------
					dbo.fnStrAllTrim (ISNULL(tc4.curr_symbol,''))											[curr_symbol4Option4],
					ct.ct_ATotal	*	CASE	-- Para que SOLO convierta los saldos grabados en la MONEDA DE LA SUCURSAL ya que NO funciona para otras..
											WHEN c.curr_id = tb.curr_id THEN 1
											ELSE 0
										END	* vwct.PlusOrMinus
									 / dbo.fnNoZDiv(	-- FIESA  09-2021  TK:12773
													CASE
														WHEN ct.sd_id IN (6,7,13) THEN	ct_curr_IdExchange
														ELSE							ct.ct_dfExchange
													END
													)														[ct_ATotal4Option4],
					ct.ct_ABalance	*	CASE	-- Para que SOLO convierta los saldos grabados en la MONEDA DE LA SUCURSAL ya que NO funciona para otras..
											WHEN c.curr_id = tb.curr_id THEN 1
											ELSE 0
										END	* vwct.PlusOrMinus
									 / dbo.fnNoZDiv(	-- FIESA  09-2021  Tk:12773
													CASE
														WHEN ct.sd_id IN (6,7,13) THEN	ct_curr_IdExchange
														ELSE							ct.ct_dfExchange
													END
												   )														[ct_ABalance4Option4]
					-- -------------------------------------------

			from	dbo.tbCommercialTransactions						ct			WITH (NOLOCK)

					INNER JOIN @tblComplexFilter_CustSupp rtmp
						ON rtmp.custsupp_id = ct.cust_id


					INNER JOIN @tmpBranchs ttb
						ON ttb.bra_id = ct.bra_id

					INNER JOIN tbBranch tb											WITH (NOLOCK)
						ON		tb.comp_id = ct.comp_id
							AND tb.bra_id = ct.bra_id


					LEFT JOIN tbsysCurrency AS tc4									WITH (NOLOCK)
						ON	tc4.curr_id =
						 	CASE
								WHEN ct.sd_id IN (6,7,13) THEN  ct.curr_id4Exchange
								ELSE							ct.curr_id4dfExchange
							END

					inner join dbo.vwCommercialTransactions_forSales	vwct		WITH (NOLOCK)
					on  ct.comp_id			= vwct.comp_id
					and ct.bra_id			= vwct.bra_id
					and ct.ct_transaction	= vwct.ct_transaction
					--AND vwct.sd_isInBalance = 'True'

					INNER join dbo.tbCustomer							c			WITH (NOLOCK)
					on	c.comp_id		= ct.comp_id
					and	c.cust_id		= ct.cust_id
					--and (@dl_id			= -1 or c.dl_id			= @dl_id)
					--and (@ck_id			= -1 or c.ck_id			= @ck_id)
					--and (@country_id	= -1 or c.country_id	= @country_id)
					--and (@state_id		= -1 or c.state_id		= @state_id)
					--and (@ss_id			= -1 or c.ss_id			= @ss_id)
					--AND isnull(c.cust_judMan,'False')			= 'False'
					--AND ISNULL(c.cust_4InitialValues,'False')	= 'False'

					left join dbo.tbSalesman							sm			WITH (NOLOCK)
					on  sm.comp_id			= ct.comp_id
					and sm.sm_id			= ct.sm_id

					left join dbo.tbSalesman							sm2			WITH (NOLOCK)
					on  sm2.comp_id			= c.comp_id
					and sm2.sm_id			= c.sm_id

					LEFT join dbo.tbSalesTerms							st			WITH (NOLOCK)
					on  st.comp_id			= ct.comp_id
					and st.st_id			= ct.st_id

					LEFT join dbo.tbsysCurrency							cr1			WITH (NOLOCK)
					on cr1.curr_id	= ct.curr_id_transaction

					INNER join dbo.tbsysCurrency						cr2			WITH (NOLOCK)
					on cr2.curr_id			= ct.ct_ACurrency

					inner join tbUsers4BranchFilter						vubf		WITH (NOLOCK)
					ON  vubf.comp_id		= CT.comp_id
					AND vubf.bra_id			= CT.bra_id
					AND vubf.[user_id]		= @user_id


					inner JOIN tbsysDocuments							td			WITH (NOLOCK)
					ON	td.sd_id			= ct.sd_id
					and	td.sd_isPurchase	= @ispurchase

					--INNER JOIN [tbsysTextsNew]	t7									WITH (NOLOCK)
					--ON	--t7.[lang_id]=@lang_id and
					--	t7.[page_id]=@page_id	and
					--	t7.[type_id]=32 AND
					--	t7.fun_id = 7

					--INNER JOIN tbSysWordsNew	tn7									WITH (NOLOCK)
					--ON tn7.wordsi_id = t7.wordsi_id
					--AND tn7.lang_id	= @lang_id

					--INNER JOIN [tbsysTextsNew]	t8									WITH (NOLOCK)
					--ON	--t8.[lang_id]=@lang_id
					--t8.[page_id]=@page_id	and	t8.[type_id]=32 AND t8.fun_id = 8

					--INNER JOIN tbSysWordsNew tn8									WITH (NOLOCK)
					--ON tn8.wordsi_id = t8.wordsi_id
					--AND tn8.lang_id = @lang_id



					--INNER JOIN [tbsysTextsNew]	t10									WITH (NOLOCK)
					--ON	--t10.[lang_id]=@lang_id
					--t10.[page_id]=@page_id and t10.[type_id]=32 AND t10.fun_id = 10
					--INNER JOIN tbSysWordsNew tn10									WITH (NOLOCK)
					--ON tn10.wordsi_id = t10.wordsi_id
					--AND tn10.lang_id = @lang_id

					--INNER JOIN [tbsysTextsNew]	t11									WITH (NOLOCK)
					--ON	--t11.[lang_id]=@lang_id
					--t11.[page_id]=@page_id and t11.[type_id]=32 AND t11.fun_id = 11
					--INNER JOIN tbSysWordsNew tn11									WITH (NOLOCK)
					--ON tn11.wordsi_id = t11.wordsi_id
					--AND tn11.lang_id = @lang_id



					--INNER JOIN [tbsysTextsNew]	t16									WITH (NOLOCK)
					--ON	--t16.[lang_id]=@lang_id
					--t16.[page_id]=@page_id and t16.[type_id]=32 AND t16.fun_id = 16
					--INNER JOIN tbSysWordsNew tn16									WITH (NOLOCK)
					--ON tn16.wordsi_id = t16.wordsi_id
					--AND tn16.lang_id = @lang_id

					/*Permite joinear contra una función que devuelve como resultado una tabla, los valores de la misma se iran modificando
					* a medida que los campos de la selección varian*/
					CROSS APPLY	fnSysCurrency_getAllSymbols(@comp_id,@intBranch4Lang/*@bra_id*/,ct.cust_id,NULL) sym
					--CROSS APPLY dbo.fnCustomer_getBalanceStatus(ct.comp_id , @bra_curr_id, ct.cust_id,@user_id,@bra_proccesingdate,-1,-1) fcgbs
					CROSS APPLY dbo.fnCustomer_getBalanceStatus(ct.comp_id ,
																tb.curr_id,
																c.cust_id,
																@user_id,
																tb.bra_processingDate,
																-1,
																CASE
																	when @balancefrom = -9999999999 and @balanceto = 9999999999 then -2
																	else -1
																END) fcgbs


				Where	 ct.comp_id		=		@comp_id
				AND      vwct.sd_isInBalance = 'True'
				--AND		 (@bra_id		= -1 OR (ct.bra_id		=		@bra_id OR IsNull(tb.rep_CustAccStatusIncluded,'False') = 'True'))

				--AND		 ct_Abalance	<>		0
				and		(
							(@option	 = 1 And  ct_Abalance <> 0) or
							(@option	 = 2 and  ct_Abalance =  ct_Abalance)	-- Es ridiculo pero anda mas rapido asi.-
						)
				AND 	(@custsupp = -1 or		ct.cust_id		=	@custsupp)
				AND		 ct.ct_date		between @datefrom		and @dateto
				AND		 ct.ct_paydate	between @datefromvto	and @datetovto
				AND 	(@selection_id	=		-1				or	ct.sd_id		= @selection_id)
				and		(@sm_id			=		-1				or (ct.sm_id		= @sm_id OR (ct.sm_id IS NULL AND c.sm_id = @sm_id)))
				AND		(fcgbs.cust_credit_balance BETWEEN @balancefrom AND @balanceto)

				AND c.curr_id = @curr_id
				AND IsNull(c.cust_judMan,'False')			= 'False'
				AND IsNull(c.cust_4InitialValues,'False')	= 'False'
				--and ct.ct_ABalance > ct.ct_ATotal


					and (@dl_id			= -1 or c.dl_id			= @dl_id)
					and (@ck_id			= -1 or c.ck_id			= @ck_id)
					and (@country_id	= -1 or c.country_id	= @country_id)
					and (@state_id		= -1 or c.state_id		= @state_id)
					and (@ss_id			= -1 or c.ss_id			= @ss_id)
					AND isnull(c.cust_judMan,'False')			= 'False'
					AND ISNULL(c.cust_4InitialValues,'False')	= 'False'




				ORDER BY

				CASE

					when @orderby = 1 then (RANK() OVER (order by c.cust_name, ct.ct_payDate))

					WHEN @orderby = 2 THEN (RANK() OVER (order by c.cust_id, ct.ct_payDate))

				END





				--ORDER BY c.cust_name, ct.ct_payDate, ct.ct_transaction


		END

	ELSE

		-- COMPRAS, Proveedores
		BEGIN 	/* estado de cuentas de proveedores */


			select
					CONVERT(VARCHAR,s.supp_id)	[ID],
					s.supp_name					[Name],
					s.supp_phone1				[Phone],
					tctn.ctn_note1				[sm_name],-- como no tenemos vendedor mostramos la nota 1
					s.supp_address				[Address],
					isnull(tpt.pt_desc,'')		[st_desc], -- condicion de compra
					ct_date,
					dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.ct_transaction)	[Comprobante],
					CASE WHEN td.sd_isInBalance = 'true' THEN
						ct_total	* vwct.PlusOrMinus
						ELSE 0 END																		[ct_total],
					CASE WHEN tctpl.comp_id IS NOT NULL THEN
							tctpl.ctpl_payDate
					ELSE
							ct_payDate
					END																					[ct_payDate],

					CASE WHEN td.sd_isInBalance = 'true' THEN
						CONVERT(DECIMAL(19,2),
						dbo.fnGetExchange2(	@comp_id,
											CT.ct_abalance,
											CT.ct_ACurrency,
											@bra_curr_id ,
											ct.ct_ACurrency ,
											ct.curr_id_transaction ,
											ct.ct_ACurrencyExchange,
											'False')
										* vwct.PlusOrMinus)
						 ELSE 0
					END																					[Balance],

	--				CASE WHEN td.sd_isInBalance = 'true' THEN
	--					dbo.fnGetExchange(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,0,0,'False')
	--								* vwct.PlusOrMinus
	--					ELSE 0 END																		[Balance],
					cr1.curr_desc																		[Curr_CT],
					CASE WHEN td.sd_isInBalance = 'true' THEN
						ct.ct_ATotal	* vwct.PlusOrMinus
						ELSE 0 END																		[ct_ATotal],

					CASE
						WHEN td.sd_isInBalance = 'true' THEN
							CASE
								WHEN tctpl.comp_id IS NOT NULL		THEN	tctpl.ctpl_balance	* vwct.PlusOrMinus
																	ELSE	ct.ct_ABalance		* vwct.PlusOrMinus
							END
						ELSE												0
					END																		[ct_ABalance],

					cr2.curr_desc																		[Curr_C_S],
					ct_ACurrencyExchange,
					--t7.text_desc,t8.text_desc,t10.text_desc,t11.text_desc,t16.text_desc,sym.cb,sym.cc,sym.cs,
					replace(replace(replace(@t7/*tn7.word_desc*/,'(MS)','('+sym.cb+')'),'(MC)','('+sym.cs+')'),'(MC)','('+sym.cs+')') [t7],
					replace(replace(replace(@t8/*tn8.word_desc*/,'(MS)','('+sym.cb+')'),'(MC)','('+sym.cs+')'),'(MC)','('+sym.cs+')') [t8],
					replace(replace(replace(@t10/*tn10.word_desc*/,'(MS)','('+sym.cb+')'),'(MC)','('+sym.cs+')'),'(MC)','('+sym.cs+')') [t10],
					replace(replace(replace(@t11/*tn11.word_desc*/,'(MS)','('+sym.cb+')'),'(MC)','('+sym.cs+')'),'(MC)','('+sym.cs+')') [t11],
					replace(replace(replace(@t16/*tn16.word_desc*/,'(MS)','('+sym.cb+')'),'(MC)','('+sym.cs+')'),'(MC)','('+sym.cs+')') [t16],ct.ct_transaction

			from	dbo.tbCommercialTransactions							ct				WITH (NOLOCK)


					INNER JOIN @tblComplexFilter_CustSupp rtmp
						ON rtmp.custsupp_id = ct.supp_id

					INNER JOIN @tmpBranchs ttb
						ON ttb.bra_id = ct.bra_id

					inner join dbo.vwCommercialTransactions_forPurchase		vwct			WITH (NOLOCK)
					on  ct.comp_id			= vwct.comp_id
					and ct.bra_id			= vwct.bra_id
					and ct.ct_transaction	= vwct.ct_transaction

					INNER JOIN tbBranch										tb				WITH (NOLOCK)
					ON  tb.comp_id			= ct.comp_id
					AND tb.bra_id			= ct.bra_id


					inner join dbo.tbSupplier								s				WITH (NOLOCK)
					on	ct.comp_id		= s.comp_id
					and	ct.supp_id		= s.supp_id


					left join dbo.tbsysCurrency		cr1										WITH (NOLOCK)
					on ct.curr_id_transaction	= cr1.curr_id

					left join dbo.tbsysCurrency		cr2										WITH (NOLOCK)
					on ct.ct_ACurrency			= cr2.curr_id

					left JOIN tbsysDocuments							td					WITH (NOLOCK)
					ON	td.sd_id			= ct.sd_id
					and	td.sd_isPurchase	= @ispurchase

					--INNER JOIN [tbsysTextsNew]	t7											WITH (NOLOCK)
					--ON	--t7.[lang_id]=@lang_id and
					--t7.[page_id]=@page_id	and	t7.[type_id]=32 AND t7.fun_id = 7
					--INNER JOIN tbSysWordsNew	tn7											WITH (NOLOCK)
					--ON tn7.wordsi_id = t7.wordsi_id
					--AND tn7.lang_id	= @lang_id

					--INNER JOIN [tbsysTextsNew]	t8											WITH (NOLOCK)
					--ON	--t8.[lang_id]=@lang_id
					--t8.[page_id]=@page_id	and	t8.[type_id]=32 AND t8.fun_id = 8
					--INNER JOIN tbSysWordsNew tn8											WITH (NOLOCK)
					--ON tn8.wordsi_id = t8.wordsi_id
					--AND tn8.lang_id = @lang_id

					--INNER JOIN [tbsysTextsNew]	t10											WITH (NOLOCK)
					--ON	--t10.[lang_id]=@lang_id
					--t10.[page_id]=@page_id and t10.[type_id]=32 AND t10.fun_id = 10
					--INNER JOIN tbSysWordsNew tn10											WITH (NOLOCK)
					--ON tn10.wordsi_id = t10.wordsi_id
					--AND tn10.lang_id = @lang_id

					--INNER JOIN [tbsysTextsNew]	t11											WITH (NOLOCK)
					--ON	--t11.[lang_id]=@lang_id
					--t11.[page_id]=@page_id and t11.[type_id]=32 AND t11.fun_id = 11
					--INNER JOIN tbSysWordsNew tn11											WITH (NOLOCK)
					--ON tn11.wordsi_id = t11.wordsi_id
					--AND tn11.lang_id = @lang_id

					--INNER JOIN [tbsysTextsNew]	t16											WITH (NOLOCK)
					--ON	--t16.[lang_id]=@lang_id
					--t16.[page_id]=@page_id and t16.[type_id]=32 AND t16.fun_id = 16
					--INNER JOIN tbSysWordsNew tn16											WITH (NOLOCK)
					--ON tn16.wordsi_id = t16.wordsi_id
					--AND tn16.lang_id = @lang_id

					CROSS APPLY	fnSysCurrency_getAllSymbols(@comp_id, @bra_id, ct.supp_id, ct.supp_id) sym

					CROSS APPLY dbo.fnSupplier_getBalanceStatus(@comp_id,@bra_curr_id,ct.supp_id,@bra_proccesingdate) fsgbs

					inner join tbUsers4BranchFilter						vubf				WITH (NOLOCK)
					ON  vubf.comp_id		= CT.comp_id
					AND vubf.bra_id			= CT.bra_id
					AND vubf.[user_id]		= @user_id

					LEFT JOIN tbPurchaseTerms							tpt					WITH (NOLOCK)
					ON	tpt.comp_id			= ct.comp_id			AND
						tpt.pt_id			= ct.pt_id

					LEFT JOIN tbCommercialTransactionNotes				tctn				WITH (NOLOCK)
					ON	tctn.comp_id		= ct.comp_id			AND
						tctn.bra_id			= ct.bra_id				AND
						tctn.ct_transaction = ct.ct_transaction

					LEFT JOIN tbCommercialTransactionsPurchaseLoan 		tctpl				WITH (NOLOCK)
					ON	tctpl.comp_id		 = ct.comp_id			AND
						tctpl.ct_transaction = ct.ct_transaction



			Where ct.comp_id		=		@comp_id
			--AND		(@bra_id		= -1 OR (ct.bra_id		=		@bra_id OR IsNull(tb.rep_SuppAccStatusIncluded,'False') = 'True' ))
			AND		vwct.sd_isAnnulment = 'False'
			--AND		ct_Abalance		<>		0
			and		(
						(@option	 = 1 And  ct.ct_Abalance <> 0) or
						(@option	 = 2 and  ct.ct_Abalance =  ct.ct_Abalance)
					)
			AND		(@custsupp		=		-1				or	ct.supp_id	= @custsupp)
			AND		(@pt_id			=		-1				or	tpt.pt_id	= @pt_id)
			AND		ct.ct_date		between @datefrom		and @dateto




			AND (	CASE
						WHEN tctpl.comp_id IS NOT NULL THEN		tctpl.ctpl_payDate
						ELSE									ct.ct_paydate
					END		between @datefromvto	AND @datetovto
				 )




			and		(@selection_id	=		-1				or	ct.sd_id	= @selection_id)
			AND		ct.ct_ABalance BETWEEN @balancefrom AND @balanceto
			AND		IsNull(tb.bra_PaymentSupp_Id,-1) <> ct.supp_id
			and		not td.sd_id between 151 and 169
			AND		s.curr_id		= @curr_id
			AND	CASE
					WHEN tctpl.comp_id IS NULL									THEN	'True'
					WHEN tctpl.comp_id IS NOT NULL AND tctpl.ctpl_balance <> 0	THEN	'True'
					ELSE																'False'
				END	 = 'True'
			--AND		tb.bra_PaymentSupp_Id <> ct.supp_id			-- No Incluir a Otros Pagos.!!!

			and (@country_id	= -1 or s.country_id = @country_id)
			and (@state_id		= -1 or s.state_id   = @state_id)
			AND (@sk_id			= -1 OR s.sk_id		 = @sk_id)

			ORDER BY

					CASE
						--nombre
						WHEN @orderby = 1 THEN (RANK() OVER (order by s.supp_name,	CASE
						                                                          	    WHEN tctpl.ctpl_payDate IS NULL  THEN ct.ct_payDate
						                                                          	    ELSE tctpl.ctpl_payDate
						                                                          	END
																					))
						--numer
						WHEN @orderby = 2 THEN (RANK() OVER (order by s.supp_id,	CASE
						                                                          	    WHEN tctpl.ctpl_payDate IS NULL  THEN ct.ct_payDate
						                                                          	    ELSE tctpl.ctpl_payDate
						                                                          	END))

					END

			--order by ct.supp_id, ct.ct_payDate, ct.ct_transaction


		END



	DECLARE @is BIT
	set @is = case WHEN @ispurchase = 'true' THEN 0 ELSE 1 END



	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id, @is



	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/




	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 398
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params1],
			CASE @selection_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsov.optval_desc
						FROM	dbo.tbsysOptionsValues tsov

						WHERE	tsov.optval_id		= @selection_id
						AND		tsov.lang_id		= @lang_id
						AND		tsov.optval_class	=  6 )
			END		[params2]	,

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params3],
      		 @datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom)) 	[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],
      		@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))		[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
     		 WHERE t.ctrl_id = 399
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		        [params7],

      		@datefromvto [DateParams3],
			--convert(varchar,day(@datefromvto)) + '/' + convert(varchar,month(@datefromvto)) + '/' + convert(varchar,year(@datefromvto)) [params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 400
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)			      [params9],

      		@datetovto [DateParams4],
			--convert(varchar,day(@datefromvto)) + '/' + convert(varchar,month(@datefromvto)) + '/' + convert(varchar,year(@datetovto)) [params10],

	--		(SELECT case when @ispurchase = 0 THEN t.[text_desc] ELSE '' END FROM [tbsysTexts]	t
			(SELECT case when @ispurchase = 0 THEN tswn.word_desc ELSE '' END
			 FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn
				ON tswn.lang_id = @lang_id
				and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 172
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id = @fun_id)		[params11],

			CASE @sm_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.sm_name
						FROM	tbSalesman ts
						WHERE	ts.comp_id = @comp_id AND ts.sm_id = @sm_id)
			END		[params12]	,


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 402
      			and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id = @is )[params13], --@ispurchase



			CASE @custsupp WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id = @lang_id
						AND		tut.utexts_id = 1)
	     		ELSE
					Case @ispurchase When 'True' THEN
						(Select ts.supp_name
						FROM	tbSupplier ts
						WHERE	Ts.comp_id = @comp_id
						AND		ts.supp_id = @custsupp)

				ELSE
						(Select Tc.cust_name
						FROM	tbCustomer tc
						WHERE	Tc.comp_id = @comp_id
						AND		Tc.cust_id = @custsupp)



					End
			END		[params14]	,

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 170
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params15],
			CASE @dl_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		td.dl_name
						FROM	tbDelivery td
						WHERE	td.comp_id = @comp_id AND td.dl_id = @dl_id)
			END																					[params16],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 372
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params17],
			CASE @ck_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tck.ck_name
						FROM	tbCustomerKind tck
						WHERE	Tck.comp_id = @comp_id AND Tck.ck_id = @ck_id)
			END		[params18] ,


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 57
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params19],
			CASE @country_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		Tc.country_desc
						FROM	tbsysCountry tc
						WHERE	tc.country_id= @country_id)
			END		[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 59
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params21],
		CASE @state_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.state_desc
						FROM	tbsysState ts
						WHERE	Ts.state_id= @state_id)
			END		[params22],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 397
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params23],
		CASE @ss_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tss.ss_desc
						FROM	tbSaleSector tss
						WHERE	tss.ss_id= @ss_id)
			END		[params24],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 401
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)		[params25],

		CONVERT(VARCHAR,@balancefrom) + ' - ' + CONVERT(VARCHAR,@balanceto)  [params26],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 991
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)[params27],
			(SELECT		tov.optval_desc
				FROM	tbsysOptionsValues tov
				WHERE	tov.lang_id = @lang_id
				And     tov.optval_class = 119
				And tov.optval_order = @option)		 [params28],



			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 106
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params29],
				CASE @curr_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT		tc.curr_desc
								FROM	tbsysCurrency tc
								WHERE	tc.curr_id= @curr_id)
					END		[params30],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						WHERE t.ctrl_id = 1467
						--AND t.[lang_id] = @lang_id
						and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params31],
							(SELECT		tov.optval_desc
								FROM	tbsysOptionsValues tov
								WHERE	tov.lang_id = @lang_id
								And     tov.optval_class = 307
								And tov.optval_id = @orderby)		 [params32],


					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						WHERE t.ctrl_id = 2238
						--AND t.[lang_id] = @lang_id
						and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params33],
						CASE @sk_id WHEN -1 THEN
									(SELECT		tut.utexts_desc
										FROM	tbsysUniqueTexts tut
										WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
								ELSE
									(SELECT		tsk.sk_desc
									 FROM		tbSupplierKind tsk
									 WHERE		tsk.comp_id = @comp_id AND tsk.sk_id= @sk_id)
							END		[params34],


				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						WHERE t.ctrl_id = 435
						--AND t.[lang_id] = @lang_id
						and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params35],
						CASE @pt_id WHEN -1 THEN
									(SELECT		tut.utexts_desc
										FROM	tbsysUniqueTexts tut
										WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
								ELSE
									(SELECT		tpt.pt_desc
									 FROM	tbPurchaseTerms tpt
									 WHERE tpt.comp_id = @comp_id and tpt.pt_id= @pt_id)
							END		[params36],


				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						WHERE t.ctrl_id = 28
						--AND t.[lang_id] = @lang_id
						and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params37],
						CASE @bra_id WHEN -1 THEN
									(SELECT		tut.utexts_desc
										FROM	tbsysUniqueTexts tut
										WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
								ELSE
									(SELECT		tb.bra_desc
									 FROM tbBranch tb
									 WHERE tb.comp_id = @comp_id and tb.bra_id= @bra_id)
							END		[params38]










--ticket 1080 se agrego en el where not td.sd_id between 151 and 169 - GA


-- Lunes 09/08/13 . Se agrega condicion de compra para proveedores - GA


-- Miercoles 06/11/13 . se agrego filtro de sucursal

END
GO




