--****ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION****
--****  Si se modifica algo en la consulta principal hacerla en el subreporte tambien - Referencia : *2*
--****ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION****
---------------------------------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spCommercialTransactions_getReportCollection]
(

	@comp_id				INT,
	@lang_id				INT,
	@page_id				INT,

	@selection_id			INT,
	@datefrom				DATETIME,
	@dateto					DATETIME,
	@custsupp				INT,
	@sm_id					INT,
	@country_id				INT,
	@state_id				INT,
	@optval_id				INT,		-- Con ASaldos (@optval_id		= 0	) o todos -1  o Sin Saldo 1
	@user_id				INT,
	@bra_id					INT,
	@intBranch4Lang			INT,
	@brag_id				INT,
	@def_id					INT,
	@optionCreditBehavior	INT,  -- -1 : TODOS  0 : No Incluidos en Entidad Crediticia , 1 : Incluidos en Entidad Crediticia
								  --  2 : Incluidos en Informes de ProtCom por AU  , 3 : Incluidos en Informes de Créditos
	@def_id_CT				INT,
	@guid					VARCHAR(50),
	@user_id_Session					INT,
	@includeSVP							INT,
	@IncludeSummaryPaymentsMethods		INT		-- 0 No 1 Si . Informar resumen de forma de pagos. 12/06/2020


)
AS

BEGIN



	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'
	-- ----------------------------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------------------------
	/*
		DECLARE
			@comp_id				INT,
			@lang_id				INT,
			@page_id				INT,

			@selection_id			INT,
			@datefrom				DATETIME,
			@dateto					DATETIME,
			@custsupp				INT,
			@sm_id					INT,
			@country_id				INT,
			@state_id				INT,
			@optval_id				INT,
			@user_id				INT,
			@bra_id					INT,
			@brag_id				INT,
			@intBranch4Lang			INT,
			@def_id					INT,
			@optionCreditBehavior	INT,  -- -1 : TODOS  0 : No Incluidos en Entidad Crediticia , 1 : Incluidos en Entidad Crediticia
										  --  2 : Incluidos en Informes de ProtCom por AU  , 3 : Incluidos en Informes de Créditos
			@def_id_CT				INT,
			@guid					VARCHAR(50),
			@user_id_Session		INT,
			@includeSVP				INT



		SELECT
			@comp_id				= 1,
			@lang_id				= 2,
			@page_id				= 10018,

			@selection_id			= -1,
			@datefrom				= '2020-05-01',
			@dateto					= '9999-12-31',
			@custsupp				= -1,
			@sm_id					= -1,
			@bra_id					= 1,
			@country_id				= -1,
			@state_id				= -1,
			@user_id				= -1,
			@optval_id				= -1,
			@brag_id				= -1,
			@intBranch4Lang			= 1 ,
			@def_id					= -1,
			@optionCreditBehavior	= -1,  -- -1 : TODOS  0 : No Incluidos en Entidad Crediticia , 1 : Incluidos en Entidad Crediticia
										  --  2 : Incluidos en Informes de ProtCom por AU  , 3 : Incluidos en Informes de Créditos
			@def_id_CT				= -1,
			@guid					='f5ffb8ad-4404-4de8-96f0-5c0511ca805c',
			@user_id_Session		=1,
			@includeSVP				=0
*/
	-- ----------------------------------------------------------------------------------






-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



--------------------------------------------------------------------------------------------------------------------------------
--****ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION****
--****  Si se modifica algo en la consulta principal hacerla en el subreporte tambien - Referencia : *2*
--****ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION****
---------------------------------------------------------------------------------------------------------------------------------


	SET	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')



	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Customer
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf			WITH (NOLOCK)
			WHERE tcf.sl_guid = @lGuid     AND
							tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Customer
				SELECT tc.cust_id
				FROM tbCustomer tc				WITH (NOLOCK)
					WHERE tc.comp_id = @comp_id
		END
	-- -------------------------------------------------------------



	-- -------------------------------------------------------------------
	-- Sucursales para listar
	-- -------------------------------------------------------------------
	DECLARE @tmpBranchGroupDetail TABLE(bra_id int PRIMARY	 KEY)
	INSERT INTO @tmpBranchGroupDetail (bra_id)
		SELECT tbgd.bra_id
			FROM tbBranchGroupDetail tbgd				WITH (NOLOCK)
			WHERE	tbgd.comp_id = @comp_id AND
					tbgd.brag_id = @brag_id

	IF @brag_id = -1
		BEGIN
			INSERT INTO @tmpBranchGroupDetail (bra_id)
				VALUES(
						@bra_id )
		END
	-- -------------------------------------------------------------------


	--SELECT * FROM #tmpBranchGroupDetail

	--DROP TABLE #tmpBranchGroupDetail

	-- -----------------------------------------------------------
	-- RECUPERO LA MONEDA DE LA SUCURSAL PARA EL CROSS APPLY
	-- Y LA FECHA DE PROCESO
	-- -----------------------------------------------------------
		DECLARE
			@bra_curr_id			INT,
			@bra_processing_date	DATETIME
		SELECT
			@bra_curr_id			= tb.curr_id,
			@bra_processing_date	= tb.bra_processingDate
			FROM tbBranch					tb	WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id
	-- -----------------------------------------------------------


	-- -----------------------------------------------------------
	-- Por Performance SOLO se pone la columna Saldo Vencido
	-- Pendiente Si se selecciona Cobranza: Con Saldos
	-- -----------------------------------------------------------
	DECLARE @intGetBalanceOption AS INT = -2
	IF @optval_id = 0
		BEGIN
			SET @intGetBalanceOption = -1
		END
	IF @includeSVP = 1
		BEGIN
			SET @intGetBalanceOption = -1
		END
	-- -----------------------------------------------------------



	SELECT
		ct.cust_id,
		c.cust_name,
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.ct_transaction) [Comprobante],
		ct_date,
		ct_payDate,
		isnull(sm.sm_name,'')					[sm_name],
		-- [MB , Parte 755 ];
		CASE ct.sd_id WHEN 66 THEN
 		ISNULL(ct.ct_total,0) * (-1)
		ELSE
		ISNULL(ct.ct_total,0)
		END						 [ct_total],
		--ct_total,
		(ct_Abalance * ct_AcurrencyExchange)	[Balance],
		 CASE ct.sd_id WHEN 66 THEN
 		ISNULL(ct.ct_Atotal,0) * (-1)
		ELSE
		ISNULL(ct.ct_Atotal,0)
		END										[ct_ATotal],
		 tc.curr_symbol							[curr_symbol],
		fcgbs.cust_credit_balance_OverCome		[cust_credit_balance_OverCome],
		tcdl.def_desc							[def_desc],
		--ct.ct_cd 								[ct_cd], -- fecha de proceso

		(SELECT
			TOP 1 tct.ct_date
			FROM	tbApplication											ta		WITH (NOLOCK)
			Inner Join tbCommercialTransactions								tct		WITH (NOLOCK)
			ON	tct.comp_id			= ta.comp_id
			AND tct.ct_transaction	= ta.ct_transaction_Source
			LEFT JOIN tbCommercialTransactionsLoan							tctl	WITH (NOLOCK)
			ON	tctl.comp_id		= ta.comp_id				AND
				tctl.ct_transaction = ta.ct_transaction_Source	AND
				tctl.ctl_id			= ta.ctl_id_Source
			Inner Join tbsysCurrency										tc		WITH (NOLOCK)
			On	tc.curr_id			=	tct.ct_ACurrency

			WHERE	ta.comp_id					=	@comp_id
			AND		ta.ct_transaction			=	ct.ct_transaction
			AND		ta.ct_transaction_Source	<>	ct.ct_transaction
		)																[ct_cd],-- Fecha de documento aplicado 21/08 infostyle
		(SELECT
			TOP 1 tbt.bt_imputationDate
			FROM tbBankingTransactions										tbt		WITH (NOLOCK)
			Inner Join tbCommercialTransactions								tct		WITH (NOLOCK)
			ON	tct.comp_id				= tbt.comp_id		AND
				tct.ct_transaction		= tbt.ct_transaction
			WHERE	tbt.comp_id			=	@comp_id
			AND		tbt.ct_transaction	=	ct.ct_transaction
			ORDER BY tbt.bt_id desc

		)																[bt_imputationDate] -- Fecha de imputacion bancaria  17/01/2020 infostyle

		FROM	dbo.tbCommercialTransactions											ct					WITH (NOLOCK,INDEX(IX201511_tbCommercialTransactions))

				INNER JOIN @tblComplexFilter_Customer									tempCustomer
					ON tempCustomer.cust_id		= CT.cust_id
				--LEFT JOIN @tblComplexFilter_Customer									tempCustomer	-- MOS 06-2020, ILOGICAMENTE ANDA rapido asi en authigar
				--	ON	tempCustomer.cust_id  = CT.cust_id AND
				--		tempCustomer.cust_id  IS NOT NULL


				INNER JOIN dbo.tbCustomer												c					WITH (NOLOCK)
					ON	ct.comp_id				= c.comp_id								AND
						ct.cust_id				= c.cust_id

				INNER JOIN tbsysCurrency												tc					WITH (NOLOCK)
					ON	tc.curr_id				= c.curr_id
				INNER JOIN 	dbo.tbDocumentsFile											df					WITH (NOLOCK)
					ON	ct.comp_id				= df.comp_id							AND
						ct.bra_id				= df.bra_id								AND
						ct.df_id				= df.df_id
				INNER JOIN dbo.tbSalesman												sm					WITH (NOLOCK)
					ON  sm.comp_id				= ct.comp_id							AND
						sm.sm_id				= c.sm_id
				--Agregado...Join a la vista de la tabla Commercial Transactions
				INNER  JOIN  dbo.vwCommercialTransactions_forSales						vwct				WITH (NOLOCK)
					ON  ct.comp_id				= vwct.comp_id							AND
						ct.bra_id				= vwct.bra_id							AND
						ct.ct_transaction		= vwct.ct_transaction

				INNER JOIN tbUsers4BranchFilter											vubf				WITH (NOLOCK)
					ON  vubf.comp_id			= CT.comp_id							AND
						vubf.bra_id			    = CT.bra_id								AND
						vubf.[user_id]			= @user_id_Session
				INNER JOIN @tmpBranchGroupDetail										tmp
					ON	tmp.bra_id				= ct.bra_id
				--STL CAMBIE EL @USER_ID del CROSS APPLY porque venía con "-1" y de esa
				--forma no traía nada. Dejé el USER_ID = 1 por default de momento.    QUE MIERDA ES ESTO ??????????????????
				CROSS APPLY dbo.fnCustomer_getBalanceStatus(ct.comp_id ,
															@bra_curr_id,
															c.cust_id,
															@user_id_Session,
															@bra_processing_date,
															-1 ,
															@intGetBalanceOption)		fcgbs

				LEFT JOIN tbCustomerDefaultLevel										tcdl				WITH (NOLOCK)
					ON	tcdl.comp_id			= ct.comp_id							AND
						tcdl.def_id				= ct.def_id




		WHERE	    ct.comp_id				=	@comp_id								AND
					vwct.sd_isReceipt		= 'True'									AND
					vwct.sd_isInBalance		= 'True'									AND
					--and		ct.bra_id		=	@bra_id
					(@custsupp		= -1 OR ct.cust_id		= @custsupp)				AND
					ct.ct_date		BETWEEN @datefrom AND @dateto						AND
					(@sm_id			= -1 OR c.sm_id			= @sm_id)					AND
					(@country_id	= -1 OR c.country_id	= @country_id)				AND
					(@state_id		= -1 OR c.state_id		= @state_id)				AND
					(@selection_id	= -1 OR df.sd_id		= @selection_id)			AND
					(
						@optval_id		= -1							OR
						@optval_id		= 0	 AND ct_Abalance	<> 0	OR
						@optval_id		= 1	 AND ct_Abalance	= 0
					)																	AND
		 			(@user_id		= -1 OR ct.[user_id]	= @user_id)					AND
					ct.sd_id		IN (6,13)											AND
					(@def_id		= -1 OR c.def_id		= @def_id)					AND
					(@def_id_CT		= -1 OR ct.def_id		= @def_id_CT)				AND	--PEDIDO POR MT FILTRA POR EL DEF_ID QUE TENIA EL CLIENTE AL MOMENTO DE REALIZAR EL MOVIMIENTO

					(	-- ATENCION si se modifica algo aca hacerlo en el sub reporte !!!!
						CASE
							WHEN @optionCreditBehavior = -1 THEN 1
							WHEN @optionCreditBehavior = 1 AND
								(
									EXISTS(
											SELECT TOP 1  1
												FROM tbCreditBehavior_Arg_Protcom tcbap	WITH (NOLOCK)
												WHERE	tcbap.comp_id			= @comp_id			AND
														tcbap.protcom_taxNumber = c.cust_taxNumber	AND
														tcbap.protcom_endDate	IS NULL
											)
									OR
									EXISTS(
											SELECT TOP 1  1
												FROM tbCreditBehavior_GeneralInfo tcbgi	WITH (NOLOCK)
												INNER JOIN tbCreditBehavior_Status tcbs	WITH (NOLOCK)
													ON	tcbs.comp_id	= tcbgi.comp_id AND
														tcbs.cis_id		= tcbgi.cis_id
												WHERE	tcbgi.comp_id	= @comp_id		AND
														tcbgi.cust_id	= ct.cust_id	AND
														tcbs.cis_isAlert= 'True'
											)
								)							THEN 1
							WHEN @optionCreditBehavior = 0 AND
								(
									NOT EXISTS(
											SELECT TOP 1  1
												FROM tbCreditBehavior_Arg_Protcom tcbap		WITH (NOLOCK)
												WHERE	tcbap.comp_id			= @comp_id			AND
														tcbap.protcom_taxNumber = c.cust_taxNumber	AND
														tcbap.protcom_endDate	IS NULL
											)
									AND
									NOT EXISTS(
											SELECT TOP 1 1
												FROM tbCreditBehavior_GeneralInfo tcbgi	WITH (NOLOCK)
												INNER JOIN tbCreditBehavior_Status tcbs	WITH (NOLOCK)
													ON	tcbs.comp_id	= tcbgi.comp_id AND
														tcbs.cis_id		= tcbgi.cis_id
												WHERE	tcbgi.comp_id	= @comp_id		AND
														tcbgi.cust_id	= ct.cust_id	AND
														tcbs.cis_isAlert= 'True'
											)
								)							THEN 1

							-- Solo para Authogar, no vamos a hacer otra mierda para esto
							-- Ver clientes incluidos en el padron pero reportados por ellos mismos.
							WHEN @optionCreditBehavior = 2 AND
								(
									EXISTS(
											SELECT TOP 1  1
												FROM tbCreditBehavior_Arg_Protcom tcbap	WITH (NOLOCK)
												WHERE	tcbap.comp_id			= @comp_id			AND
														tcbap.protcom_taxNumber = c.cust_taxNumber	AND
														tcbap.protcom_infoName  LIKE  '%AUTHOGAR%'	AND
														tcbap.protcom_endDate	IS NULL
											)

								)							THEN 1
							WHEN @optionCreditBehavior = 3 AND
								(

									EXISTS(
											SELECT TOP 1  1
												FROM tbCreditBehavior_GeneralInfo tcbgi	WITH (NOLOCK)
												INNER JOIN tbCreditBehavior_Status tcbs	WITH (NOLOCK)
													ON	tcbs.comp_id	= tcbgi.comp_id AND
														tcbs.cis_id		= tcbgi.cis_id
												WHERE	tcbgi.comp_id	= @comp_id		AND
														tcbgi.cust_id	= ct.cust_id	AND
														tcbs.cis_isAlert= 'True'
											)
								)							THEN 1
							ELSE								 0
						END		= 1
					)																AND
					(@country_id			= -1 OR c.country_id	= @country_id)	AND
					(@state_id				= -1 OR c.state_id		= @state_id)








	ORDER BY ct.ct_date, ct.sd_id ,dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.ct_transaction)


	EXEC [spReports_getData3] @comp_id,@intBranch4Lang , @lang_id, @page_id

	DECLARE @fun_id INT
	SET @fun_id = 1
	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		 WHERE	t.ctrl_id = 398
		 --AND t.[lang_id] = @lang_id
		 and t.[page_id] = @related_page_id
		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params1],


		CASE @selection_id WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		ELSE
			(SELECT	 ov.optval_desc
				from dbo.tbsysOptionsValues	ov
				WHERE	ov.optval_class			= 112
				AND		ov.lang_id				= @lang_id
				AND		ov.optval_id	= @selection_id)
		END																											[params2],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		 WHERE t.ctrl_id = 177
		 --AND t.[lang_id] = @lang_id
		 and t.[page_id] = @related_page_id
		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params3],

		 @datefrom [DateParams1],
		--convert(varchar,day(@datefrom))+'/'+convert(varchar,month(@datefrom))+'/'+convert(varchar,year(@datefrom))	[params4],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		 WHERE t.ctrl_id = 384
		 --AND t.[lang_id] = @lang_id
		 and t.[page_id] = @related_page_id
		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params5],

		 @dateto [DateParams2],
		--convert(varchar,day(@dateto))+'/'+convert(varchar,month(@dateto))+'/'+convert(varchar,year(@dateto))		[params6],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		 WHERE t.ctrl_id = 402
		 --AND t.[lang_id] = @lang_id
		 and t.[page_id] = @related_page_id
		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params7],


		CASE @custsupp WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		ELSE
			(SELECT		tc.cust_name
				FROM	tbCustomer tc
				WHERE	Tc.comp_id = @comp_id AND tc.cust_id= @custsupp)
		END																											[params8],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		 WHERE t.ctrl_id = 172
		 --AND t.[lang_id] = @lang_id
		 and t.[page_id] = @related_page_id
		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params9],


		CASE @sm_id WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		ELSE
			(SELECT		ts.sm_name
				FROM	tbSalesman ts
				WHERE	TS.comp_id = @comp_id AND Ts.sm_id= @sm_id)
		END																											[params10],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		 WHERE t.ctrl_id = 57
		 --AND t.[lang_id] = @lang_id
		 and t.[page_id] = @related_page_id
		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params11],


		CASE @country_id WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		ELSE
			(SELECT		tc.country_desc
				FROM	tbsysCountry tc
				WHERE	Tc.country_id= @country_id)
		END																											[params12],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 59
   		 --AND t.[lang_id] = @lang_id
   		 and t.[page_id] = @related_page_id
   		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params13],


		CASE @state_id WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		ELSE
			(SELECT		ts.state_desc
				FROM	tbsysState ts
				WHERE	ts.country_id= @country_id
				AND     ts.state_id=@state_id)
		END																											[params14],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 991
   		 --AND t.[lang_id] = @lang_id
   		 and t.[page_id] = @related_page_id
   		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params15],

		 CASE @optval_id WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		 ELSE
			(SELECT		tov.optval_desc
				FROM	tbsysOptionsValues tov
				WHERE	tov.lang_id = @lang_id
				AND     tov.optval_class = 80
				and		tov.optval_id = @optval_id)
		END																											[params16],


	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 1
   		 --AND t.[lang_id] = @lang_id
   		 and t.[page_id] = @related_page_id
   		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params17],

		 CASE @user_id WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		 ELSE
			(SELECT tu.user_lastname + ', ' + tu.user_firstname [User_Name]
				from tbUser tu
				where tu.[user_id] = @user_id)
		END																											[params18],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 639
   		 --AND t.[lang_id] = @lang_id
   		 and t.[page_id] = @related_page_id
   		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params19],

		 CASE @brag_id WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 50)
		 ELSE
			(SELECT tbg.brag_desc
			 FROM tbBranchGroup tbg
				where tbg.comp_id   = @comp_id
				and  tbg.brag_id	= @brag_id)
		END																											[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 4010
   		 --AND t.[lang_id] = @lang_id
   		 and t.[page_id] = @related_page_id
   		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params21],

		 CASE @def_id WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		 ELSE
			(SELECT tcdl.def_desc
			 FROM tbCustomerDefaultLevel tcdl
				where tcdl.comp_id   = @comp_id
				and  tcdl.def_id	= @def_id)
		END																											[params22],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 4049
   		 --AND t.[lang_id] = @lang_id
		 and t.[page_id] = @related_page_id
   		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params23],

		 CASE @optionCreditBehavior WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		 ELSE
			(SELECT TOV.optval_desc
			 FROM tbsysOptionsValues tov
				where tov.lang_id = @lang_id
				AND  tov.optval_class = 539
				AND tov.optval_id = @optionCreditBehavior)
		END																											[params24],

		CONVERT(NVARCHAR,@IncludeSummaryPaymentsMethods)  [params25] -- para usarlo como condicion en el rpt para mostrar o no el resumen









	  -- ---------------------------------------------------------------------------------------------------
	  /* SubReporte Detalle de Formas de Pago*/  --
	  -- ---------------------------------------------------------------------------------------------------
	  -- Referencia : *2* SI SE MODIFICA ESTE SUBQUERY HACERLO EN EL QUERY PRINCIPAL TAMBIEN



	  IF @IncludeSummaryPaymentsMethods = 1 -- Mostrar resumen = Sí
		  BEGIN
			SELECT
				CASE
      				WHEN vc.Class=5 THEN vc.[description]  + ' * ' + tba.ba_desc
      				WHEN vc.Class=7 THEN vc.[description]  + ' * ' + tba.ba_desc
      				ELSE vc.[description]
      			END				[description],
				sum(vc.amount)		[amount],
				vc.currency			[currency]

				FROM dbo.tbCommercialTransactions												ct					WITH(NOLOCK,INDEX(IX201511_tbCommercialTransactions))

					--INNER JOIN @tblComplexFilter_Customer									tempCustomer
					--	ON tempCustomer.cust_id		= CT.cust_id
					LEFT JOIN @tblComplexFilter_Customer									tempCustomer	-- MOS 06-2020, ILOGICAMENTE ANDA rapido asi en authigar
						ON	tempCustomer.cust_id  = CT.cust_id AND
							tempCustomer.cust_id  IS NOT NULL

					INNER JOIN dbo.tbCustomer													c					WITH(NOLOCK)
						ON	ct.comp_id				= c.comp_id									AND
							ct.cust_id				= c.cust_id									--AND  MOS 06-2020
						   --(@country_id				= -1 OR c.country_id	= @country_id)		AND
						   --(@state_id				= -1 OR c.state_id		= @state_id)


					INNER JOIN tbsysCurrency													tc					WITH(NOLOCK)
						ON tc.curr_id				= c.curr_id
					INNER JOIN 	dbo.tbDocumentsFile												df					WITH(NOLOCK)
						ON	ct.comp_id				= df.comp_id								AND
							ct.bra_id				= df.bra_id									AND
							ct.df_id				= df.df_id
					INNER JOIN dbo.tbSalesman													sm					WITH(NOLOCK)
						ON   sm.comp_id				= ct.comp_id								AND
							 sm.sm_id				= c.sm_id
					--Agregado...Join a la vista de la tabla Commercial Transactions
					INNER  JOIN  dbo.vwCommercialTransactions_forSales							vwct				WITH(NOLOCK)
						ON  ct.comp_id				= vwct.comp_id								AND
							ct.bra_id				= vwct.bra_id								AND
							ct.ct_transaction		= vwct.ct_transaction						AND
							vwct.sd_isReceipt		= 'True'									AND
							vwct.sd_isInBalance		= 'True'
					INNER JOIN tbUsers4BranchFilter												vubf				WITH(NOLOCK)
						ON  vubf.comp_id			= CT.comp_id								AND
							vubf.bra_id			    = CT.bra_id									AND
							vubf.[user_id]			= @user_id_Session
					INNER JOIN dbo.vwCollection													vc					WITH(NOLOCK)
						ON	vc.comp_id				= ct.comp_id								AND
							vc.ct_transaction		= ct.ct_transaction							AND
							vc.lang_id				= @lang_id
					LEFT JOIN tbBankingAccounts													tba					WITH(NOLOCK)
						ON	vc.class			IN (5,7)										AND
							tba.comp_id			= vc.comp_id									AND
							tba.ba_id			= vc.GroupClass
					INNER JOIN @tmpBranchGroupDetail											tmp
						ON	tmp.bra_id					= ct.bra_id
				WHERE			ct.comp_id		=	@comp_id									AND
								--and		ct.bra_id		=	@bra_id
								(@custsupp		= -1 OR ct.cust_id		= @custsupp)			AND
								 ct.ct_date		BETWEEN @datefrom AND @dateto					AND
								(@sm_id			= -1 OR c.sm_id			= @sm_id)				AND
								(@country_id	= -1 OR c.country_id	= @country_id)			AND
								(@state_id		= -1 OR c.state_id		= @state_id)			AND
								(@selection_id	= -1 OR df.sd_id		= @selection_id)		AND
								(
									@optval_id		= -1 OR
									@optval_id		= 0	 AND ct_Abalance	<> 0 OR
									@optval_id		= 1	 AND ct_Abalance	= 0
								)																AND
				 				(@user_id		= -1 OR ct.[user_id]	= @user_id)				AND
								ct.sd_id		IN (6,13)										AND
								(@def_id		= -1 OR c.def_id		= @def_id)				AND
								(@def_id_CT		= -1 OR ct.def_id		= @def_id_CT)			AND --PEDIDO POR MT FILTRA POR EL DEF_ID QUE TENIA EL CLIENTE AL MOMENTO DE REALIZAR EL MOVIMIENTO

						(
							CASE
								WHEN @optionCreditBehavior = -1 THEN 1
								WHEN @optionCreditBehavior = 1 AND
									(
										EXISTS(
												SELECT TOP 1  1
													FROM tbCreditBehavior_Arg_Protcom tcbap	WITH(NOLOCK)
													WHERE	tcbap.comp_id			= @comp_id			AND
															tcbap.protcom_taxNumber = c.cust_taxNumber	AND
															tcbap.protcom_endDate	IS NULL
												)
										OR
										EXISTS(
												SELECT TOP 1  1
													FROM tbCreditBehavior_GeneralInfo tcbgi	WITH(NOLOCK)
													INNER JOIN tbCreditBehavior_Status tcbs	WITH(NOLOCK)
														ON	tcbs.comp_id	= tcbgi.comp_id AND
															tcbs.cis_id		= tcbgi.cis_id
													WHERE	tcbgi.comp_id	= @comp_id		AND
															tcbgi.cust_id	= ct.cust_id	AND
															tcbs.cis_isAlert= 'True'
												)
									)							THEN 1
								WHEN @optionCreditBehavior = 0 AND
									(
										NOT EXISTS(
												SELECT TOP 1  1
													FROM tbCreditBehavior_Arg_Protcom tcbap	WITH(NOLOCK)
													WHERE	tcbap.comp_id			= @comp_id			AND
															tcbap.protcom_taxNumber = c.cust_taxNumber	AND
															tcbap.protcom_endDate	IS NULL
												)
										AND
										NOT EXISTS(
												SELECT TOP 1  1
													FROM tbCreditBehavior_GeneralInfo tcbgi	WITH(NOLOCK)
													INNER JOIN tbCreditBehavior_Status tcbs	WITH(NOLOCK)
														ON	tcbs.comp_id	= tcbgi.comp_id AND
															tcbs.cis_id		= tcbgi.cis_id
													WHERE	tcbgi.comp_id	= @comp_id		AND
															tcbgi.cust_id	= ct.cust_id	AND
															tcbs.cis_isAlert= 'True'
												)
									)							THEN 1

								-- Solo para Authogar, no vamos a hacer otra mierda para esto
								-- Ver clientes incluidos en el padron pero reportados por ellos mismos.
								WHEN @optionCreditBehavior = 2 AND
									(
										EXISTS(
												SELECT TOP 1  1
													FROM tbCreditBehavior_Arg_Protcom tcbap	WITH(NOLOCK)
													WHERE	tcbap.comp_id			= @comp_id			AND
															tcbap.protcom_taxNumber = c.cust_taxNumber	AND
															tcbap.protcom_infoName  LIKE  '%AUTHOGAR%'	AND
															tcbap.protcom_endDate	IS NULL
												)

									)							THEN 1
								WHEN @optionCreditBehavior = 3 AND
									(

										EXISTS(
												SELECT TOP 1  1
													FROM tbCreditBehavior_GeneralInfo tcbgi	WITH(NOLOCK)
													INNER JOIN tbCreditBehavior_Status tcbs	WITH(NOLOCK)
														ON	tcbs.comp_id	= tcbgi.comp_id AND
															tcbs.cis_id		= tcbgi.cis_id
													WHERE	tcbgi.comp_id	= @comp_id		AND
															tcbgi.cust_id	= ct.cust_id	AND
															tcbs.cis_isAlert= 'True'
												)
									)							THEN 1
								ELSE								 0
							END		= 1
						)


			GROUP BY	vc.class,
						vc.GroupClass,
						vc.[description],
						vc.currency,
						tba.ba_desc
		  -- ---------------------------------------------------------------------------------------------------
		  --Si se modifica algo en la consulta hacerla en el subreporte tambien - Referencia : *2* -

		  END

		  ELSE
		  	BEGIN
		  		SELECT 	''		[description],
						0		[amount],
						0		[currency]

		  	END


end
GO







CREATE  PROCEDURE [dbo].[spCommercialTransactions_getReportCollectionCommission]
(
	@comp_id				INT,
	@lang_id				INT,
	@page_id				INT,

	@option					INT,
	@item_desc				VARCHAR(200),
	@date_from				DATETIME,
	@date_to				DATETIME,
	@cust_id				INT,
	@sm_id					INT,
	@bra_id					INT,
	@cat_id					INT,
	@subcat_id				INT,
	@brand_id				INT,
	@dl_id					INT,
	@ck_id					INT,
	@intSubTotalOrUtility	INT,
	@intCostOrCostAW		INT,
	@user_id				INT,
	@bra_id_session			INT,
	@intBranch4Lang			int
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'




	-- -----------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------
	/*
	DECLARE @comp_id				INT,
			@lang_id				INT,
			@page_id				INT,
			@option					INT,
			@item_desc				VARCHAR(200),
			@date_from				DATETIME,
			@date_to				DATETIME,
			@sm_id					INT,
			@bra_id					INT,
			@dl_id					INT,
			@cust_id				INT,
			@cat_id					INT,
			@subcat_id				INT,
			@brand_id				INT,
			@ck_id					INT,
			@intSubTotalOrUtility	INT,
			@intCostOrCostAW		INT,
			@user_id				INT,
			@type_import			INT,
			@bra_id_session			INT,
			@intBranch4Lang			INT = 1
	SELECT	@comp_id				=1,
			@lang_id				=2,
			@page_id				=10064,
			@option					=-1,
			@item_desc				='',
			@date_from				='2021-02-01',
			@date_to				='2999-05-31',
			@sm_id					=22,
			@bra_id					=-1,
			@dl_id					=-1,
			@cust_id				=-1,
			@cat_id					=-1,
			@subcat_id				=-1,
			@brand_id				=-1,
			@ck_id					=-1,
			@intSubTotalOrUtility	=0,
			@intCostOrCostAW		=0,
			@user_id				=1,
			@bra_id_session			=1
	*/
	-- -----------------------------------------------------------------------------



	set	@date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from,'False')
	set	@date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to	,'True')




	DECLARE @fun_id				INT,
			@curr_id_branch		INT,
			@curr_symbol		NVARCHAR(4)

	SET		@fun_id = 1




	SELECT	@curr_id_branch		= curr_id
		FROM	tbBranch			tb			WITH (NOLOCK)
		WHERE	tb.comp_id			= @comp_id
		AND		tb.bra_id			= @bra_id_session


	SELECT	@curr_symbol		= CR.curr_symbol
		FROM	tbsysCurrency		CR			WITH (NOLOCK)
		WHERE	CR.[curr_id]		= @curr_id_branch



	SELECT	SM.[sm_name],

			CT.ct_date										[ct_date],

			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, CT.ct_transaction)	[Comprobante],


			sum(dbo.fnGetExchange2(	@comp_id,
									dbo.fnGetCommissionBySubtotalOrUtility(	@intSubTotalOrUtility,
																			@intCostOrCostAW,
																			IT.it_price * TA.appl_coef / 100,
																			IT.it_priceBOfCost,
																			IT.it_priceBOfCostPP,
																			IT.it_qty,
																			B.brand_commission_byReceive,
																			VIT.vw_itemUnitPriceWithTaxes * TA.appl_coef / 100),
									IT.curr_id,
									@curr_id_branch,
									IT.curr_id,
									IT.curr_id, 1, 'false'))									[brand_commission],

			sum(dbo.fnGetExchange2(	@comp_id,
									dbo.fnGetCommissionBySubtotalOrUtility(	@intSubTotalOrUtility,
																			@intCostOrCostAW,
																			IT.it_price * TA.appl_coef / 100,
																			IT.it_priceBOfCost,
																			IT.it_priceBOfCostPP,
																			IT.it_qty,
																			CK.ck_commission_byReceive,
																			VIT.vw_itemUnitPriceWithTaxes * TA.appl_coef / 100),
									IT.curr_id,
									@curr_id_branch,
									IT.curr_id,
									IT.curr_id, 1, 'false'))
				+		-- MOS 04-2021 ARG y DF
			sum(dbo.fnGetExchange2(	@comp_id,
									dbo.fnGetCommissionBySubtotalOrUtility(	@intSubTotalOrUtility,
																			@intCostOrCostAW,
																			IT.it_price * TA.appl_coef / 100,
																			IT.it_priceBOfCost,
																			IT.it_priceBOfCostPP,
																			IT.it_qty,
																			tst.st_commission_byReceive,
																			VIT.vw_itemUnitPriceWithTaxes * TA.appl_coef / 100),
									IT.curr_id,
									@curr_id_branch,
									IT.curr_id,
									IT.curr_id, 1, 'false'))
																								[ck_commission],

			sum(dbo.fnGetExchange2(	@comp_id,
									dbo.fnGetCommissionBySubtotalOrUtility(	@intSubTotalOrUtility,
																			@intCostOrCostAW,
																			IT.it_price * TA.appl_coef / 100,
																			IT.it_priceBOfCost,
																			IT.it_priceBOfCostPP,
																			IT.it_qty,
																			SM.sm_commission_byReceive,
																			VIT.vw_itemUnitPriceWithTaxes * TA.appl_coef / 100),
									IT.curr_id,
									@curr_id_branch,
									IT.curr_id,
									IT.curr_id, 1, 'false'))									[sm_commission_bySale],

			sum(dbo.fnGetExchange2(	@comp_id,
									dbo.fnGetCommissionBySubtotalOrUtility(	@intSubTotalOrUtility,
																			@intCostOrCostAW,
																			IT.it_price * TA.appl_coef / 100,
																			IT.it_priceBOfCost,
																			IT.it_priceBOfCostPP,
																			IT.it_qty,
																			C.cat_commission_byReceive,
																			VIT.vw_itemUnitPriceWithTaxes * TA.appl_coef / 100),
									IT.curr_id,
									@curr_id_branch,
									IT.curr_id,
									IT.curr_id, 1, 'false'))									[cat_commission],

			sum(dbo.fnGetExchange2(	@comp_id,
									dbo.fnGetCommissionBySubtotalOrUtility(	@intSubTotalOrUtility,
																			@intCostOrCostAW,
																			IT.it_price * TA.appl_coef / 100,
																			IT.it_priceBOfCost,
																			IT.it_priceBOfCostPP,
																			IT.it_qty,
																			SC.subcat_commission_byReceive,
																			VIT.vw_itemUnitPriceWithTaxes * TA.appl_coef / 100),
									IT.curr_id,
									@curr_id_branch,
									IT.curr_id,
									IT.curr_id, 1, 'false'))									[subcat_commission],

			sum(dbo.fnGetExchange2(	@comp_id,
									dbo.fnGetCommissionBySubtotalOrUtility(	@intSubTotalOrUtility,
																			@intCostOrCostAW,
																			IT.it_price * TA.appl_coef / 100,
																			IT.it_priceBOfCost,
																			IT.it_priceBOfCostPP,
																			IT.it_qty,
																			I.item_commission_byReceive,
																			VIT.vw_itemUnitPriceWithTaxes * TA.appl_coef / 100),
									IT.curr_id,
									@curr_id_branch,
									IT.curr_id,
									IT.curr_id, 1, 'false'))									[item_commission],


			isnull(CT.ct_total,0)																[ct_total],

			@curr_symbol, --i.cat_id, --i.subcat_id,
			CT.ct_transaction



	FROM		tbCommercialTransactions									CT			WITH (NOLOCK)

				INNER JOIN tbApplication									TA			WITH (NOLOCK)
				ON	TA.comp_id						=	CT.comp_id
				AND TA.bra_id						=	CT.bra_id
				AND TA.ct_transaction_destiny		=	CT.ct_transaction

				INNER JOIN tbCommercialTransactions							TCT			WITH (NOLOCK)
				ON	TCT.comp_id						=	CT.comp_id
				AND	TCT.bra_id						=	CT.bra_id
				AND	TCT.ct_transaction				=	TA.ct_transaction_Source
				AND	NOT TCT.sm_id IS NULL

				inner join tbCustomer										CU			WITH (NOLOCK)
				ON	CU.[comp_id]					=	TCT.[comp_id]
				and CU.[cust_id]					=	TCT.[cust_id]

				inner join tbItemTransactions								IT				WITH (NOLOCK)	-- Para que funcione con Fc Adelantada.
				on	IT.[comp_id]					=	TCT.[comp_id]
				--and IT.[bra_id]						=	TCT.[bra_id]
				and IT.[ct_transaction]				=	TCT.[ct_transaction]
				AND	 (	it.item_id IS NOT NULL
						OR
						it.item_idfromPreInvoice IS NOT NULL
					 )

				INNER JOIN vwItemTransactions								VIT			WITH (NOLOCK)
				ON	VIT.comp_id						=	IT.comp_id
				AND VIT.bra_id						=	IT.bra_id
				AND VIT.ct_transaction				=	IT.ct_transaction
				AND VIT.it_transaction				=	IT.it_transaction

				INNER join tbItem											I			WITH (NOLOCK)
				on  I.[comp_id]						=	IT.[comp_id]
				and		(
							I.[item_id]						=	IT.[item_id]
							OR
							I.item_id						=	IT.item_idfromPreInvoice
						)

				left JOIN tbBrand											B			WITH (NOLOCK)
				ON	B.[comp_id]						=	I.[comp_id]
				AND B.[brand_id]					=	I.[brand_id]

				INNER join tbCustomerKind									CK			WITH (NOLOCK)
				on  CK.[comp_id]					=	CU.[comp_id]
				and CK.[ck_id]						=	CU.[ck_id]

				INNER join tbSalesman										SM			WITH (NOLOCK)
				ON	SM.[comp_id]					=	TCT.[comp_id]
				and SM.[sm_id]						=	TCT.[sm_id]

				INNER JOIN tbCategory										C			WITH (NOLOCK)
				ON	C.[comp_id]						=	I.[comp_id]
				AND C.[cat_id]						=	I.[cat_id]

				INNER JOIN tbSubCategory									SC			WITH (NOLOCK)
				ON	SC.[comp_id]					=	I.[comp_id]
				AND SC.[cat_id]						=	I.[cat_id]
				AND SC.[subcat_id]					=	I.[subcat_id]

				INNER join tbUsers4BranchFilter								VUBF			WITH (NOLOCK)
				ON  VUBF.comp_id					=	CT.comp_id
				AND VUBF.bra_id						=	CT.bra_id
				AND VUBF.[user_id]					=	@user_id

				INNER JOIN tbSalesTerms						tst				WITH (NOLOCK)			--GRUPONUCLEO
				ON	tst.comp_id						= TCT.comp_id	AND
					tst.st_id						= TCT.st_id

	WHERE		CT.[comp_id]		=	@comp_id
	AND			CT.sd_id			IN (6,13)
	AND 		CT.ct_date			between  @date_from	  and @date_to
	AND			(@bra_id			= -1 or CT.bra_id		=	@bra_id)
	AND			(@sm_id				= -1 or TCT.[sm_id]		=	@sm_id)
	AND			(@dl_id				= -1 or TCT.[dl_id]		=	@dl_id)
	AND			(@brand_id			= -1 or I.[brand_id]	=	@brand_id)
	AND			(@cat_id			= -1 or I.[cat_id]		=	@cat_id)
	AND			(@subcat_id			= -1 or I.[subcat_id]	=	@subcat_id)
	AND			(@ck_id				= -1 or CK.[ck_id]		=	@ck_id)

	and			(
					(@option	 = -1													)	or
					(@option	 = 0 and I.item_desc like				@item_desc + '%')	or
					(@option	 = 1 and I.item_desc like		'%' +	@item_desc + '%')	or
					(@option	 = 2 and I.item_desc =					@item_desc )		or
					(@option	 = 3 and I.item_desc <>					@item_desc )		or
					(@option	 = 4 and I.item_desc not LIKE	'%' +	@item_desc + '%')
				)
	AND ISNULL(i.item_excluded4Commission,'False') = 'False'

	GROUP BY	SM.[sm_name],
				CT.ct_date,
				CT.ct_transaction,
				CT.ct_total--, --it.it_transaction
				--i.cat_id--, i.subcat_id

	ORDER BY 1,2,3











	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id




	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

	select
	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 43
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params1],

			CASE @option WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tov.optval_desc + ISNULL(@item_desc,'')
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 2
					AND		tov.optval_id		= @option
					AND		tov.lang_id			= @lang_id)
			END																																	[params2],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 174
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params3],

			CASE @cust_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tc.cust_name
					 FROM	dbo.tbCustomer tc
					 WHERE	tc.cust_id  = @cust_id)
				END																																[params4],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 172
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params5],

				CASE @sm_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.sm_name
						FROM	dbo.tbSalesman ts
						WHERE	ts.sm_id = @sm_id)
				END																													[params6],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 36
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params7],

				CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cat_desc
						FROM	dbo.tbCategory tc
						WHERE	tc.cat_id = @cat_id)
				END																																[params8],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 38
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params9],

				CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
						FROM	dbo.tbSubCategory tsc
						WHERE	tsc.subcat_id = @subcat_id)
				END																																[params10],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 73
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params11],

				CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.brand_desc
						FROM	dbo.tbBrand tb
						WHERE	tb.brand_id = @brand_id)
				END																																[params12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 170
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params13],

				CASE @dl_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		td.dl_name
						FROM	dbo.tbDelivery td
						WHERE	td.dl_id = @dl_id)
				END																																[params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 372
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params15],

				CASE @ck_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tck.ck_name
						FROM	dbo.tbCustomerKind tck
						WHERE	tck.ck_id = @ck_id)
				END																																[params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 558
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params17],

			(SELECT  tov.optval_desc
			FROM dbo.tbsysOptionsValues tov
			WHERE	tov.lang_id = @lang_id
			AND		tov.optval_class = 35
			AND		tov.optval_id = @intSubTotalOrUtility)																						[params18],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 559
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params19],

			(SELECT  tov.optval_desc
			FROM dbo.tbsysOptionsValues tov
			WHERE	tov.lang_id = @lang_id
			AND		tov.optval_class = 36
			AND		tov.optval_id = @intCostOrCostAW)																							[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 177
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params21],

			@date_from [DateParams1],
			--convert(varchar,day(@date_from)) + '/' + convert(varchar,month(@date_from)) + '/' + convert(varchar,year(@date_from))					[params22],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 384
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params23],

			@date_to [DateParams2],
			--convert(varchar,day(@date_to)) + '/' + convert(varchar,month(@date_to)) + '/' + convert(varchar,year(@date_to))						[params24],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 991
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params25],

			(SELECT  tov.optval_desc
			FROM dbo.tbsysOptionsValues tov
			WHERE	tov.lang_id = @lang_id
			AND		tov.optval_class = 76
			AND		tov.optval_id = 1)																			[params26],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 28
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params27],

				CASE @bra_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.bra_desc
					 FROM	dbo.tbBranch tb
					 WHERE tb.comp_id=@comp_id
					 and   tb.bra_id= @bra_id)
				END																									[params28],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 214
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id = 1 )		[params29]




END
GO




