CREATE PROCEDURE [dbo].[spCommercialTransactions_getReportComisionLiquidation]
(
		@comp_id				int,
		@lang_id				int,
		@page_id				int,

		@option_value			INT,				-- 2-Venta 1-Cobranza
		@option					INT,				-- Si el texto del articulo comienza con ...
		@item_desc				VARCHAR(200),
		@date_from				DATETIME,
		@date_to				DATETIME,
		@cust_id				INT,
		@sm_id					INT,
	    @sm_id2					INT,
		@bra_id					INT,
		@cat_id					INT,
		@subcat_id				INT,
		@brand_id				INT,
		@dl_id					INT,
		@ck_id					INT,
		@intSubTotalOrUtility	AS INT,
		@intCostOrCostAW		AS INT,
		@sd_id					INT,				-- Algun ENFERMO puso aca el reputo SD_ID la concha de tu madreeeee
		@OptionWithCom          INT,				-- -1: TODOS  , 1 : Sólo Artículos que tengan cargada la comisión en el Artículo
		@prli_id				INT,
		@pricetype				INT,				-- 1 : Importe , 2 : Importe menos intereses
		@guidItem				VARCHAR(50),
		@guidCust				VARCHAR(50),
		@user_id				INT,
		@intBranch4Lang			int





)

AS



BEGIN


    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'

	-- -------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------
	/*
		DECLARE @comp_id				INT,
				@lang_id				INT,
				@page_id				INT,

				@option_value			INT,
				@option					INT,
				@item_desc				VARCHAR(200),
				@cust_id				INT,
				@date_from				DATETIME,
				@date_to				DATETIME,
				@sm_id					INT,
				@sm_id2					INT,
				@bra_id					INT,
				@dl_id					INT,
				@cat_id					INT,
				@subcat_id				INT,
				@brand_id				INT,
				@ck_id					INT,
				@intSubTotalOrUtility	AS INT,
				@intCostOrCostAW		AS INT,
				@user_id				INT,
				@type_import			INT,
				@sd_id					INT,
				@intBranch4Lang			int,
				@OptionWithCom          INT, -- -1: TODOS  , 1 : Sólo Artículos que tengan cargada la comisión en el Artículo
				@guidItem				VARCHAR(50),
				@guidCust				VARCHAR(50)	,
				@pricetype				INT = 1,
				@prli_id				INT = -1



		SELECT	@comp_id				= 1,
				@lang_id				= 2,
				@page_id				= 10029,
				@option_value			=  2,
				@option					=  -1,
				@item_desc				= '' ,
				@date_from				= '2021-08-01',
				@date_to				= '2021-09-30',
				@sm_id					= 24,
				@sm_id2					= -1,
				@bra_id					= -1,
				@dl_id					= -1,
				@cust_id				= -1,
				@cat_id					= -1,
				@subcat_id				= -1,
				@brand_id				= -1,
				@ck_id					= -1,
				@intSubTotalOrUtility	=  0,
				@intCostOrCostAW		=  0,
				@user_id				=  1,
				@sd_id					=  -1,
				@intBranch4Lang			=  1 ,
				@OptionWithCom			= -1,
				@guidItem				= '74a32d8a-58b6-47df-8fb9-35b5d6e4e32e',
				@guidCust				= '74a32d8a-58b6-47df-8fb9-35b5d6e4e32e'
*/
	-- -------------------------------------------------------------------------
		DECLARE @lGuidItem AS UNIQUEIDENTIFIER

		SET @lGuidItem = CONVERT(UNIQUEIDENTIFIER,@guidItem)


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf			WITH (NOLOCK)
				WHERE tcf.sl_guid = @lGuidItem     AND
					  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT tc.item_id
					FROM tbItem tc			WITH (NOLOCK)
						WHERE tc.comp_id = @comp_id
			END
		-- -------------------------------------------------------------


		DECLARE @lGuidCust AS UNIQUEIDENTIFIER

		SET @lGuidCust = CONVERT(UNIQUEIDENTIFIER,@guidCust)


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf			WITH (NOLOCK)
				WHERE tcf.sl_guid = @lGuidCust     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT tc.cust_id
					FROM tbCustomer tc			WITH (NOLOCK)
						WHERE tc.comp_id = @comp_id
			END
		-- -------------------------------------------------------------

	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')



	DECLARE @fun_id INT
	SET @fun_id = 1

	SELECT	sm.[sm_name],ct.ct_transaction,
			CT.[ct_date],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, CT.ct_transaction) [Comprobante],
			I.item_id		[item_id],   -- it.item_id  [item_id], MOS 12-2021
			i.[item_code],
			i.[item_desc],
			--IT.[it_qty],
			--IT.[it_price],



			dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value
					WHEN 1 THEN B.brand_commission_byReceive
					ELSE B.brand_commission
				END, vit.vw_itemUnitPriceWithTaxes)	* vwct.PlusOrMinus													[brand_commission],

			(
			dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value
					WHEN 1 THEN CK.ck_commission_byReceive
					ELSE CK.ck_commission_bySale
				END, vit.vw_itemUnitPriceWithTaxes)

			+

			dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value
					WHEN 1 THEN		tst.st_commission_byReceive
					ELSE			tst.st_commission_bySale
				END, vit.vw_itemUnitPriceWithTaxes)
			) * vwct.PlusOrMinus																						[ck_commission],

			dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value
					WHEN 1 THEN sm.sm_commission_byReceive
					ELSE SM.sm_commission_bySale
				END, vit.vw_itemUnitPriceWithTaxes)	* vwct.PlusOrMinus													[sm_commission_bySale],

			dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value
					WHEN 1 THEN C.cat_commission_byReceive
					ELSE C.cat_commission
				END, vit.vw_itemUnitPriceWithTaxes)	* vwct.PlusOrMinus													[cat_commission],

			dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value
					WHEN 1 THEN SC.subcat_commission_byReceive
					ELSE SC.subcat_commission
				END, vit.vw_itemUnitPriceWithTaxes) * vwct.PlusOrMinus													[subcat_commission],

			dbo.fnGetCommissionBySubtotalOrUtility( @intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value
					WHEN 1 THEN I.item_commission_byReceive
					ELSE dbo.fnGetItemCustomCommission4Sales(	@comp_id,		 --I.item_commission
																ct.bra_id,
																ct.cust_id,
																I.cat_id,
																I.subcat_id,
																I.item_id,
																I.brand_id,
																ct.sm_id,
																ct.st_id,
																it.prli_id,
																ct.ct_date,
																CASE
																	WHEN @pricetype = 2 THEN	vitpam.MarkUpPPPPSI
																	ELSE						vitpam.MarkUpPPPP
																END
																)
				END, vit.vw_itemUnitPriceWithTaxes)	* vwct.PlusOrMinus													[item_commission],

			(
			CASE
				WHEN NOT tplbr.prli_id IS NULL THEN																															 --Parte 599

				dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,					 --Parte 599
				CASE @option_value
					WHEN 1 THEN isnull(tplbr.rbp_commission_byReceive,0)
					ELSE ISNULL(tplbr.rbp_commission,0) END,vit.vw_itemUnitPriceWithTaxes)						 --Parte 599
				ELSE																																								 --Parte 599

				dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,					 --Parte 599
				CASE @option_value
					WHEN 1 THEN isnull(mb.prli_commission_byReceive,0)
					ELSE ISNULL(mb.prli_commission,0)
				END,vit.vw_itemUnitPriceWithTaxes)
			END
			) *  vwct.PlusOrMinus																						[pricelist_commission],--Parte 599

			--CASE @type_import WHEN 0 THEN it.it_price ELSE vit.vw_itemUnitPriceWithTaxes  END [it_price],

			ISNULL(ct.ct_total,0)  * vwct.PlusOrMinus				 [ct_total],

			CR.curr_symbol [curr_desc]


	FROM	tbCommercialTransactions									CT		WITH (NOLOCK)

			INNER join tbCustomer										CU		WITH (NOLOCK)
			ON	CU.[comp_id]					=	CT.[comp_id]
			and CU.[cust_id]					=	CT.[cust_id]

			INNER JOIN @tblComplexFilter_Customer						tmpcfc
			ON tmpcfc.cust_id					= CU.cust_id

			LEFT join tbItemTransactions								IT		WITH (NOLOCK)
			on  IT.[comp_id]					=   CT.[comp_id]
			and IT.[bra_id]						=	CT.[bra_id]
			and IT.[ct_transaction]				=	CT.[ct_transaction]

			LEFT JOIN vwItemTransactions								vit		WITH (NOLOCK)
			ON  vit.comp_id						= IT.comp_id
			AND vit.bra_id						= IT.bra_id
			AND vit.ct_transaction				= IT.ct_transaction
			AND vit.it_transaction				= IT.it_transaction

			LEFT JOIN vwItemTransactionsProfitAndMarckup vitpam		WITH (NOLOCK)
			ON	vitpam.comp_id				= it.comp_id AND
				vitpam.bra_id				= it.bra_id  AND
				vitpam.ct_transaction		= it.ct_transaction AND
				vitpam.it_transaction		= it.it_transaction

			LEFT join tbItem					I		WITH (NOLOCK)
			on  I.[comp_id]						=	IT.[comp_id]
			and I.[item_id]						=	ISNULL(IT.[item_id],it.item_idfromPreInvoice)

			INNER JOIN @tblComplexFilter_Items 						tmpcfi
			ON tmpcfi.item_id					= I.item_id

			LEFT JOIN tbBrand					B		WITH (NOLOCK)
			ON	B.[comp_id]						=	I.[comp_id]
			AND B.[brand_id]					=	I.[brand_id]

			INNER join vwCommercialTransactions_forSales   vwct		WITH (NOLOCK)
			on  ct.comp_id						=	vwct.comp_id
			--and ct.bra_id						=	vwct.bra_id
			and ct.ct_transaction				=	vwct.ct_transaction

			LEFT join tbCustomerKind			CK		WITH (NOLOCK)
			on  CK.[comp_id]					=	CT.[comp_id]
			and CK.[ck_id]						=	CU.[ck_id]

			LEFT join tbSalesman				SM		WITH (NOLOCK)
			ON	SM.[comp_id]					=	CT.[comp_id]
			and SM.[sm_id]						=	CT.[sm_id]

			LEFT join tbSalesman							SM2		WITH (NOLOCK)
			ON	SM2.[comp_id]					=	CT.[comp_id]
			and SM2.[sm_id]						=	CU.sm_id_2

			LEFT JOIN tbCategory							C		WITH (NOLOCK)
			ON	C.[comp_id]						=	I.[comp_id]
			AND C.[cat_id]						=	I.[cat_id]

			LEFT JOIN tbSubCategory							SC		WITH (NOLOCK)
			ON	SC.[comp_id]					=	I.[comp_id]
			AND SC.[cat_id]						=	I.[cat_id]
			AND SC.[subcat_id]					=	I.[subcat_id]

			LEFT join tbDelivery							DL		WITH (NOLOCK)
			on DL.[comp_id]						=	CT.[comp_id]
			and DL.[dl_id]						=	CT.[dl_id]

			LEFT join tbsysCurrency							CR		WITH (NOLOCK)
			on  CR.[curr_id]					= IT.[curr_id]

			INNER join tbUsers4BranchFilter					vubf		WITH (NOLOCK)
			ON  vubf.comp_id					= CT.comp_id
			AND vubf.bra_id						= CT.bra_id
			AND vubf.[user_id]					= @user_id

			INNER JOIN tbPriceList							MB		WITH (NOLOCK)
			ON  mb.comp_id						= IT.comp_id
			AND mb.prli_id 					    = IT.prli_id


			INNER JOIN tbsysDocuments						td		WITH (NOLOCK)
			ON td.sd_id							 = CT.sd_id


			LEFT JOIN tbPriceList2BrandRelation			tplbr   		WITH (NOLOCK)   --Parte 599
			ON  ct.bra_id						= tplbr.bra_id
 			AND	i.brand_id						= tplbr.brand_id
			AND it.prli_id						= tplbr.prli_id

			LEFT JOIN tbPriceListItems					tpli			WITH (NOLOCK)   --Parte 599
			ON  tplbr.prli_id					= tpli.prli_id
			AND tpli.item_id					= I.item_id
			AND tpli.comp_id					= I.comp_id

			INNER JOIN tbSalesTerms						tst				WITH (NOLOCK)	--GRUPONUCLEO
			ON	tst.comp_id						= CT.comp_id	AND
				tst.st_id						= CT.st_id



	--		LEFT JOIN dbo.tbsysOptionsValues			ov
	--		on ov.optval_id			= df.sd_id
	--		and ov.optval_class		= 1


	WHERE				 CT.[comp_id]						=	@comp_id
			AND			(@bra_id = -1  or CT.bra_id			=   @bra_id)
			AND			vwct.sd_isInBalance = 'True'
			AND			vwct.sd_isAnnulment = 'False'
			AND			vwct.sd_isReceipt   = 'False'
			AND			(@sm_id			= -1 or CT.[sm_id]		=	@sm_id)
			AND			(@sm_id2	    = -1 or cu.sm_id_2		=	@sm_id2)
			AND			(@dl_id			= -1 or CT.[dl_id]		=	@dl_id)
			AND			(@ck_id			= -1 or CK.[ck_id]		=	@ck_id)
			AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
			AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
			AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
			AND			(@cust_id	    = -1 OR	cu.cust_id		=	@cust_id)
			AND			CT.ct_date	BETWEEN  @date_from	  AND @date_to
			AND
						(
							(@option	 = -1 ) OR
							(@option	 = 0 and I.item_desc like @item_desc + '%') or
							(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
							(@option	 = 2 and I.item_desc = @item_desc )  or
							(@option	 = 3 and I.item_desc <> @item_desc ) or
							(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
						)
			AND			(@sd_id		 = -1	 OR		ct.sd_id = @sd_id)
			AND			ct.sd_id IN (1,3) --Facturas y notas de credito
			AND			CASE
							WHEN @option_value = 2 THEN 1
							WHEN @option_value = 1  AND ct.ct_ATotal <> ct.ct_ABalance THEN 1
							ELSE 0
						END	= 1
						--ct.ct_ATotal <> ct.ct_ABalance
			AND			CASE
							WHEN @OptionWithCom	= -1 THEN 1
							WHEN @OptionWithCom	= 1 AND i.comp_id IS NULL THEN 1
							WHEN @OptionWithCom	= 1 AND ISNULL(I.item_commission,0) <> 0 THEN 1
							ELSE 0
						END = 1
						  	-- -1: TODOS  , 1 : Sólo Artículos que tengan cargada la comisión en el Artículo
			AND
						(@prli_id = -1 OR it.prli_id = @prli_id)
			AND ISNULL(i.item_excluded4Commission,'False') = 'False'

	ORDER BY			1,2,3



	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/

	--		SELECT	t.ctrl_id,	t.
	--		FROM	[tbsysTextsNew]				t
	--				inner join [tbsysControls]	c
	--				on c.[ctrl_id] = t.[ctrl_id]
	--		where t.[page_id]	= @related_page_id
	--		and		t.[type_id]	= 1

	/*************************************************************************************************************/
	select
	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 43
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params1],

			CASE @option WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tov.optval_desc + ISNULL(@item_desc,'')
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 2
					AND		tov.optval_id		= @option
					AND		tov.lang_id			= @lang_id)
			END																																	[params2],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 174
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params3],

			CASE @cust_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tc.cust_name
					 FROM	dbo.tbCustomer tc
					 WHERE	tc.cust_id  = @cust_id)
				END																																[params4],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 172
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params5],

				CASE @sm_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.sm_name
						FROM	dbo.tbSalesman ts
						WHERE	ts.sm_id = @sm_id)
				END																													[params6],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 36
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params7],

				CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cat_desc
						FROM	dbo.tbCategory tc
						WHERE	tc.cat_id = @cat_id)
				END																																[params8],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 38
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params9],

				CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
						FROM	dbo.tbSubCategory tsc
						WHERE	tsc.subcat_id = @subcat_id)
				END																																[params10],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 73
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params11],

				CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.brand_desc
						FROM	dbo.tbBrand tb
						WHERE	tb.brand_id = @brand_id)
				END																																[params12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 170
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params13],

				CASE @dl_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		td.dl_name
						FROM	dbo.tbDelivery td
						WHERE	td.dl_id = @dl_id)
				END																																[params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 372
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params15],

				CASE @ck_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tck.ck_name
						FROM	dbo.tbCustomerKind tck
						WHERE	tck.ck_id = @ck_id)
				END																																[params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 558
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params17],

			(SELECT  tov.optval_desc
			FROM dbo.tbsysOptionsValues tov
			WHERE	tov.lang_id = @lang_id
			AND		tov.optval_class = 35
			AND		tov.optval_id = @intSubTotalOrUtility)																						[params18],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 559
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params19],

			(SELECT  tov.optval_desc
			FROM dbo.tbsysOptionsValues tov
			WHERE	tov.lang_id = @lang_id
			AND		tov.optval_class = 36
			AND		tov.optval_id = @intCostOrCostAW)																							[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 177
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params21],

			@date_from [DateParams1],
			--convert(varchar,day(@date_from)) + '/' + convert(varchar,month(@date_from)) + '/' + convert(varchar,year(@date_from))					[params22],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 384
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params23],

			@date_to [DateParams2],
			--convert(varchar,day(@date_to)) + '/' + convert(varchar,month(@date_to)) + '/' + convert(varchar,year(@date_to))						[params24],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 991
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params25],

			(SELECT  tov.optval_desc
			FROM dbo.tbsysOptionsValues tov
			WHERE	tov.lang_id = @lang_id
			AND		tov.optval_class = 76
			AND		tov.optval_id = @option_value)																[params26],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 28
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params27],

				CASE @bra_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.bra_desc
					 FROM	dbo.tbBranch tb
					 WHERE tb.comp_id=@comp_id
					 and   tb.bra_id= @bra_id)
				END																									  [params28],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 1458
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						   [params29],

				CASE @sm_id2 WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts2.sm_name
						FROM	dbo.tbSalesman ts2
						WHERE	ts2.sm_id = @sm_id2)
				END																									   [params30],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 521
				 --AND t.[lang_id] = @lang_id
				 AND t.[page_id] = @related_page_id
				 AND t.[type_id]	= 1
				 AND t.fun_id = @fun_id)																				[params31],


				(SELECT		tov.optval_desc
				 FROM		dbo.tbsysOptionsValues tov
				 WHERE		tov.lang_id = @lang_id
				 AND		tov.optval_class = 115
				 AND		tov.optval_id = @sd_id)
																														[params33],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 4108
				 --AND t.[lang_id] = @lang_id
				 AND t.[page_id] = @related_page_id
				 AND t.[type_id]	= 1
				 AND t.fun_id = @fun_id)																				[params34],


			CASE @OptionWithCom WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
						(SELECT		tov.optval_desc
				 FROM		dbo.tbsysOptionsValues tov
				 WHERE		tov.lang_id = @lang_id
				 AND		tov.optval_class = 540
				 AND		tov.optval_id = @OptionWithCom)
			END																											[params35]






	  -- ---------------------------------------------------------------------------------------------------
	  /* SubReporte Resumen x Vendedor*/  --
	  -- ---------------------------------------------------------------------------------------------------
	   -- Referencia : *2* SI SE MODIFICA ESTE SUBQUERY HACERLO EN EL QUERY PRINCIPAL TAMBIEN
	  --------------------------------------------------------------------------------------------------------------------------------
	  --****ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION****
	  --****  Si se modifica algo en la consulta principal hacerla en el subreporte tambien - Referencia : *2*
	  --****ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION****
	  ---------------------------------------------------------------------------------------------------------------------------------

	  -- -------------------------------------------------------------------------------------
		DECLARE @tmpCommissionTotals TABLE(sm_name NVARCHAR(200),
										 brand_com DECIMAL(19,6),
										   ck_com DECIMAL(19,6),
										   sm_com DECIMAL(19,6),
										   cat_com DECIMAL(19,6),
										   subcat_com DECIMAL(19,6),
										   item_com DECIMAL(19,6),
										   prli_com DECIMAL(19,6),
										   ct_tot DECIMAL(19,6),
										   it_tot DECIMAL(19,6)
											)

		INSERT INTO @tmpCommissionTotals (sm_name,
										   brand_com,
										   ck_com,
										   sm_com,
										   cat_com,
										   subcat_com,
										   item_com,
										   prli_com,
										   ct_tot,
										   it_tot
											)

			 SELECT
				sm.[sm_name],
				sum(dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value WHEN 1 THEN B.brand_commission_byReceive ELSE B.brand_commission END, vit.vw_itemUnitPriceWithTaxes)		* vwct.PlusOrMinus)		[brand_commission],

				sum(dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value WHEN 1 THEN CK.ck_commission_byReceive ELSE CK.ck_commission_bySale END, vit.vw_itemUnitPriceWithTaxes)	* vwct.PlusOrMinus)

				+

				sum(dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value WHEN 1 THEN tst.st_commission_bySale ELSE tst.st_commission_byReceive END, vit.vw_itemUnitPriceWithTaxes) * vwct.PlusOrMinus)		[ck_commission],

				sum(dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value WHEN 1 THEN sm.sm_commission_byReceive ELSE SM.sm_commission_bySale END, vit.vw_itemUnitPriceWithTaxes)	* vwct.PlusOrMinus)	[sm_commission_bySale],

				sum(dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value WHEN 1 THEN C.cat_commission_byReceive ELSE C.cat_commission END, vit.vw_itemUnitPriceWithTaxes)			* vwct.PlusOrMinus)			[cat_commission],

				sum(dbo.fnGetCommissionBySubtotalOrUtility(@intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
				CASE @option_value WHEN 1 THEN SC.subcat_commission_byReceive ELSE SC.subcat_commission END, vit.vw_itemUnitPriceWithTaxes)	* vwct.PlusOrMinus)[subcat_commission],

				sum(dbo.fnGetCommissionBySubtotalOrUtility( @intSubTotalOrUtility, @intCostOrCostAW, (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ), IT.it_priceBOfCost,IT.[it_priceBOfCostPP],IT.it_qty,
														CASE @option_value
															WHEN 1 THEN I.item_commission_byReceive
															ELSE dbo.fnGetItemCustomCommission4Sales(	@comp_id,		 --I.item_commission
																										ct.bra_id,
																										ct.cust_id,
																										I.cat_id,
																										I.subcat_id,
																										I.item_id,
																										I.brand_id,
																										ct.sm_id,
																										ct.st_id,
																										it.prli_id,
																										ct.ct_date,
																										CASE
																											WHEN @pricetype = 2 THEN	vitpam.MarkUpPPPPSI
																											ELSE						vitpam.MarkUpPPPP
																										END)
														END, vit.vw_itemUnitPriceWithTaxes)	* vwct.PlusOrMinus)		[item_commission],

				CASE WHEN NOT tplbr.prli_id IS NULL THEN																																 --Parte 599
					sum(dbo.fnGetCommissionBySubtotalOrUtility(	@intSubTotalOrUtility,
															@intCostOrCostAW,
															 (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ),
															IT.it_priceBOfCost,
															IT.[it_priceBOfCostPP],
															IT.it_qty,
															CASE @option_value WHEN 1 THEN
																isnull(tplbr.rbp_commission_byReceive,0)
															ELSE
																ISNULL(tplbr.rbp_commission,0)
															END,
															vit.vw_itemUnitPriceWithTaxes)	* vwct.PlusOrMinus	)				 --Parte 599
				ELSE																																									 --Parte 599
					sum(dbo.fnGetCommissionBySubtotalOrUtility(	@intSubTotalOrUtility,
															@intCostOrCostAW,
															 (IT.it_price - CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END ),
															IT.it_priceBOfCost,
															IT.[it_priceBOfCostPP],
															IT.it_qty,
															CASE @option_value WHEN 1 THEN
																ISNULL(mb.prli_commission_byReceive,0)
															ELSE
																ISNULL(mb.prli_commission,0)
															END,
															vit.vw_itemUnitPriceWithTaxes)	* vwct.PlusOrMinus )

				END																									[pricelist_commission],--Parte 599


					sum(ISNULL(ct.ct_total,0) * vwct.PlusOrMinus)
				 [ct_total],
				 sum(IT.it_price /*- CASE WHEN @pricetype = 2 THEN	IT.it_CreditInt ELSE 0 END*/  * IT.it_qty 	* vwct.PlusOrMinus)	[it_tot]




		FROM	tbCommercialTransactions			CT										WITH (NOLOCK)

				INNER join tbCustomer				CU			WITH (NOLOCK)
				ON	CU.[comp_id]					=	CT.[comp_id]
				and CU.[cust_id]					=	CT.[cust_id]

				INNER JOIN @tblComplexFilter_Customer						tmpcfc
				ON tmpcfc.cust_id					= CU.cust_id

				LEFT join tbItemTransactions		IT			WITH (NOLOCK)
				on  IT.[comp_id]					=   CT.[comp_id]
				and IT.[bra_id]						=	CT.[bra_id]
				and IT.[ct_transaction]				=	CT.[ct_transaction]

				LEFT JOIN vwItemTransactions vit			WITH (NOLOCK)
				ON  vit.comp_id						= IT.comp_id
				AND vit.bra_id						= IT.bra_id
				AND vit.ct_transaction				= IT.ct_transaction
				AND vit.it_transaction				= IT.it_transaction

				LEFT JOIN vwItemTransactionsProfitAndMarckup vitpam			WITH (NOLOCK)
				ON	vitpam.comp_id				= it.comp_id AND
					vitpam.bra_id				= it.bra_id  AND
					vitpam.ct_transaction		= it.ct_transaction AND
					vitpam.it_transaction		= it.it_transaction

				LEFT join tbItem					I			WITH (NOLOCK)
				on  I.[comp_id]						=	IT.[comp_id]
				and I.[item_id]						=	ISNULL(IT.[item_id],it.item_idfromPreInvoice)

				INNER JOIN @tblComplexFilter_Items 						tmpcfi
				ON tmpcfi.item_id					= I.item_id

				LEFT JOIN tbBrand					B			WITH (NOLOCK)
				ON	B.[comp_id]						=	I.[comp_id]
				AND B.[brand_id]					=	I.[brand_id]

				INNER join vwCommercialTransactions_forSales   vwct			WITH (NOLOCK)
				on  ct.comp_id						=	vwct.comp_id
				--and ct.bra_id						=	vwct.bra_id
				and ct.ct_transaction				=	vwct.ct_transaction

				LEFT join tbCustomerKind			CK			WITH (NOLOCK)
				on  CK.[comp_id]					=	CT.[comp_id]
				and CK.[ck_id]						=	CU.[ck_id]

				LEFT join tbSalesman				SM			WITH (NOLOCK)
				ON	SM.[comp_id]					=	CT.[comp_id]
				and SM.[sm_id]						=	CT.[sm_id]

				LEFT join tbSalesman							SM2			WITH (NOLOCK)
				ON	SM2.[comp_id]					=	CT.[comp_id]
				and SM2.[sm_id]						=	CU.sm_id_2

				LEFT JOIN tbCategory							C			WITH (NOLOCK)
				ON	C.[comp_id]						=	I.[comp_id]
				AND C.[cat_id]						=	I.[cat_id]

				LEFT JOIN tbSubCategory							SC			WITH (NOLOCK)
				ON	SC.[comp_id]					=	I.[comp_id]
				AND SC.[cat_id]						=	I.[cat_id]
				AND SC.[subcat_id]					=	I.[subcat_id]

				LEFT join tbDelivery							DL			WITH (NOLOCK)
				on DL.[comp_id]						=	CT.[comp_id]
				and DL.[dl_id]						=	CT.[dl_id]

				LEFT join tbsysCurrency							CR			WITH (NOLOCK)
				on  CR.[curr_id]					= IT.[curr_id]

				INNER join tbUsers4BranchFilter					vubf			WITH (NOLOCK)
				ON  vubf.comp_id					= CT.comp_id
				AND vubf.bra_id						= CT.bra_id
				AND vubf.[user_id]					= @user_id

				INNER JOIN tbPriceList							MB			WITH (NOLOCK)
				ON  mb.comp_id						= IT.comp_id
				AND mb.prli_id 					    = IT.prli_id


				INNER JOIN tbsysDocuments						td			WITH (NOLOCK)
				ON td.sd_id							 = CT.sd_id

				LEFT JOIN tbPriceList2BrandRelation			tplbr    			WITH (NOLOCK)  --Parte 599
				ON  ct.bra_id						= tplbr.bra_id
 				AND	i.brand_id						= tplbr.brand_id
				AND it.prli_id						= tplbr.prli_id

				LEFT JOIN tbPriceListItems					tpli				WITH (NOLOCK)  --Parte 599
				ON  tplbr.prli_id					= tpli.prli_id
				AND tpli.item_id					= I.item_id
				AND tpli.comp_id					= I.comp_id

				INNER JOIN tbSalesTerms						tst					WITH (NOLOCK)	--GRUPONUCLEO
				ON	tst.comp_id						= CT.comp_id	AND
					tst.st_id						= CT.st_id


		WHERE				 CT.[comp_id]						=	@comp_id
				AND			(@bra_id = -1  or CT.bra_id			=   @bra_id)
				AND			vwct.sd_isInBalance = 'True'
				AND			vwct.sd_isAnnulment = 'False'
				AND			vwct.sd_isReceipt   = 'False'
				AND			(@sm_id			= -1 or CT.[sm_id]		=	@sm_id)
				AND			(@sm_id2	    = -1 or cu.sm_id_2		=	@sm_id2)
				AND			(@dl_id			= -1 or CT.[dl_id]		=	@dl_id)
				AND			(@ck_id			= -1 or CK.[ck_id]		=	@ck_id)
				AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
				AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
				AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
				AND			(@cust_id	    = -1 OR	cu.cust_id		=	@cust_id)
				AND			CT.ct_date	BETWEEN  @date_from	  AND @date_to
				AND			(
								(@option	 = -1 ) OR
								(@option	 = 0 and I.item_desc like @item_desc + '%') or
								(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
								(@option	 = 2 and I.item_desc = @item_desc )  or
								(@option	 = 3 and I.item_desc <> @item_desc ) or
								(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
							)
				AND			(@sd_id		 = -1	 OR		ct.sd_id = @sd_id)
				AND			ct.sd_id IN (1,3) --Facturas y notas de credito
				AND		CASE
							WHEN @option_value = 2 THEN 1
							WHEN @option_value = 1  AND ct.ct_ATotal <> ct.ct_ABalance THEN 1
							ELSE 0
						END	= 1
				AND			CASE
							WHEN @OptionWithCom	= -1 THEN 1
							WHEN @OptionWithCom	= 1 AND i.comp_id IS NULL THEN 1
							WHEN @OptionWithCom	= 1 AND ISNULL(I.item_commission,0) <> 0 THEN 1
							ELSE 0
						END = 1
			AND
						(@prli_id = -1 OR it.prli_id = @prli_id)


		 GROUP BY sm.sm_name,ct.sd_id,tplbr.prli_id


		  -- Se guardan los datos en una tabla temporal para poder agrupar por vendedor xq podian haber de varias prli_id o sd para mismo vendedor.
			DECLARE @DECtotal		AS DECIMAL(19,2) = 0
			DECLARE @decSubTotal	AS DECIMAL(19,4) = 0
			;WITH ctrTotal AS(

							SELECT DISTINCT ct.ct_transaction,
											ISNULL(ct.ct_total,0)		* vwct.PlusOrMinus [Total],
											ISNULL(ct.ct_subtotal,0)	* vwct.PlusOrMinus [Subtotal]
								FROM	tbCommercialTransactions			CT										WITH (NOLOCK)

				INNER join tbCustomer				CU			WITH (NOLOCK)
				ON	CU.[comp_id]					=	CT.[comp_id]
				and CU.[cust_id]					=	CT.[cust_id]

				INNER JOIN @tblComplexFilter_Customer						tmpcfc
				ON tmpcfc.cust_id					= CU.cust_id

				LEFT join tbItemTransactions		IT			WITH (NOLOCK)
				on  IT.[comp_id]					=   CT.[comp_id]
				and IT.[bra_id]						=	CT.[bra_id]
				and IT.[ct_transaction]				=	CT.[ct_transaction]

				LEFT JOIN vwItemTransactions vit			WITH (NOLOCK)
				ON  vit.comp_id						= IT.comp_id
				AND vit.bra_id						= IT.bra_id
				AND vit.ct_transaction				= IT.ct_transaction
				AND vit.it_transaction				= IT.it_transaction

				LEFT JOIN vwItemTransactionsProfitAndMarckup vitpam			WITH (NOLOCK)
				ON	vitpam.comp_id				= it.comp_id AND
					vitpam.bra_id				= it.bra_id  AND
					vitpam.ct_transaction		= it.ct_transaction AND
					vitpam.it_transaction		= it.it_transaction

				LEFT join tbItem					I			WITH (NOLOCK)
				on  I.[comp_id]						=	IT.[comp_id]
				and I.[item_id]						=	ISNULL(IT.[item_id],it.item_idfromPreInvoice)

				INNER JOIN @tblComplexFilter_Items 						tmpcfi
				ON tmpcfi.item_id					= I.item_id

				LEFT JOIN tbBrand					B			WITH (NOLOCK)
				ON	B.[comp_id]						=	I.[comp_id]
				AND B.[brand_id]					=	I.[brand_id]

				INNER join vwCommercialTransactions_forSales   vwct			WITH (NOLOCK)
				on  ct.comp_id						=	vwct.comp_id
				--and ct.bra_id						=	vwct.bra_id
				and ct.ct_transaction				=	vwct.ct_transaction

				LEFT join tbCustomerKind			CK			WITH (NOLOCK)
				on  CK.[comp_id]					=	CT.[comp_id]
				and CK.[ck_id]						=	CU.[ck_id]

				LEFT join tbSalesman				SM			WITH (NOLOCK)
				ON	SM.[comp_id]					=	CT.[comp_id]
				and SM.[sm_id]						=	CT.[sm_id]

				LEFT join tbSalesman							SM2			WITH (NOLOCK)
				ON	SM2.[comp_id]					=	CT.[comp_id]
				and SM2.[sm_id]						=	CU.sm_id_2

				LEFT JOIN tbCategory							C			WITH (NOLOCK)
				ON	C.[comp_id]						=	I.[comp_id]
				AND C.[cat_id]						=	I.[cat_id]

				LEFT JOIN tbSubCategory							SC			WITH (NOLOCK)
				ON	SC.[comp_id]					=	I.[comp_id]
				AND SC.[cat_id]						=	I.[cat_id]
				AND SC.[subcat_id]					=	I.[subcat_id]

				LEFT join tbDelivery							DL			WITH (NOLOCK)
				on DL.[comp_id]						=	CT.[comp_id]
				and DL.[dl_id]						=	CT.[dl_id]

				LEFT join tbsysCurrency							CR			WITH (NOLOCK)
				on  CR.[curr_id]					= IT.[curr_id]

				INNER join tbUsers4BranchFilter					vubf			WITH (NOLOCK)
				ON  vubf.comp_id					= CT.comp_id
				AND vubf.bra_id						= CT.bra_id
				AND vubf.[user_id]					= @user_id

				INNER JOIN tbPriceList							MB			WITH (NOLOCK)
				ON  mb.comp_id						= IT.comp_id
				AND mb.prli_id 					    = IT.prli_id


				INNER JOIN tbsysDocuments						td			WITH (NOLOCK)
				ON td.sd_id							 = CT.sd_id

				LEFT JOIN tbPriceList2BrandRelation			tplbr    			WITH (NOLOCK)  --Parte 599
				ON  ct.bra_id						= tplbr.bra_id
 				AND	i.brand_id						= tplbr.brand_id
				AND it.prli_id						= tplbr.prli_id

				LEFT JOIN tbPriceListItems					tpli				WITH (NOLOCK)  --Parte 599
				ON  tplbr.prli_id					= tpli.prli_id
				AND tpli.item_id					= I.item_id
				AND tpli.comp_id					= I.comp_id

				INNER JOIN tbSalesTerms						tst					WITH (NOLOCK)	--GRUPONUCLEO
				ON	tst.comp_id						= CT.comp_id	AND
					tst.st_id						= CT.st_id


		WHERE				 CT.[comp_id]						=	@comp_id
				AND			(@bra_id = -1  or CT.bra_id			=   @bra_id)
				AND			vwct.sd_isInBalance = 'True'
				AND			vwct.sd_isAnnulment = 'False'
				AND			vwct.sd_isReceipt   = 'False'
				AND			(@sm_id			= -1 or CT.[sm_id]		=	@sm_id)
				AND			(@sm_id2	    = -1 or cu.sm_id_2		=	@sm_id2)
				AND			(@dl_id			= -1 or CT.[dl_id]		=	@dl_id)
				AND			(@ck_id			= -1 or CK.[ck_id]		=	@ck_id)
				AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
				AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
				AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
				AND			(@cust_id	    = -1 OR	cu.cust_id		=	@cust_id)
				AND			CT.ct_date	BETWEEN  @date_from	  AND @date_to
				AND			(
								(@option	 = -1 ) OR
								(@option	 = 0 and I.item_desc like @item_desc + '%') or
								(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
								(@option	 = 2 and I.item_desc = @item_desc )  or
								(@option	 = 3 and I.item_desc <> @item_desc ) or
								(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
							)
				AND			(@sd_id		 = -1	 OR		ct.sd_id = @sd_id)
				AND			ct.sd_id IN (1,3) --Facturas y notas de credito
				AND		CASE
							WHEN @option_value = 2 THEN 1
							WHEN @option_value = 1  AND ct.ct_ATotal <> ct.ct_ABalance THEN 1
							ELSE 0
						END	= 1
				AND			CASE
							WHEN @OptionWithCom	= -1 THEN 1
							WHEN @OptionWithCom	= 1 AND i.comp_id IS NULL THEN 1
							WHEN @OptionWithCom	= 1 AND ISNULL(I.item_commission,0) <> 0 THEN 1
							ELSE 0
						END = 1
			AND
						(@prli_id = -1 OR it.prli_id = @prli_id)


						)
			SELECT	@dectotal		= SUM(Total),
					@decSubTotal	= SUM(Subtotal)
				FROM ctrTotal


		  SELECT
			tctcc.sm_name			[sm_name],
			sum(tctcc.brand_com)	[brand_com],
			sum(tctcc.ck_com)		[ck_com],
			sum(tctcc.sm_com)		[sm_com],
			sum(tctcc.cat_com)		[cat_com],
			sum(tctcc.subcat_com)	[subcat_com],
			sum(tctcc.item_com)		[item_com],
			sum(tctcc.prli_com)		[prli_com],
			/*sum(tctcc.ct_tot)*/
			@dectotal				[ct_tot],
			@decSubTotal			[ct_subtot]

			FROM @tmpCommissionTotals tctcc

			GROUP BY tctcc.sm_name

			ORDER BY 1

	   -- ---------------------------------------------------------------------------------------------------
	   -- ---------------------------------------------------------------------------------------------------

--==
--SELECT * FROM @tmpCommissionTotals

END
GO


CREATE PROCEDURE [dbo].[spCommercialTransactions_getReportForBranchTransfer]
(
	@comp_id			int,
	@lang_id			Int,
	@page_id			Int,
	@ct_transaction		Int
)
AS


BEGIN




    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------


	SET NOCOUNT ON



	-------------------------------------------------------------
	/*
	DECLARE
		@comp_id			INT,
		@lang_id			INT,
		@page_id			INT,
		@ct_transaction		INT

	SELECT
		@comp_id			= 1,
		@lang_id			= 2,
		@page_id			= 10061,
		@ct_transaction		= 27620
	*/
	-------------------------------------------------------------

	--------------------------------------------------------------------------------------------------
	--Variables en las cuales se guarda la cotización
	----------------------------------------------------------------------------------------------------

		DECLARE
			@curr_id_transaction		INT,
			@curr_id4Exchange			INT,
			@ct_curr_id4Exchange		DECIMAL(19,6)



		SELECT
			@curr_id_transaction	= tct.curr_id_transaction,
			@curr_id4Exchange		= tct.curr_id4Exchange,
			@ct_curr_id4Exchange	= tct.ct_curr_IdExchange


		  FROM  tbCommercialTransactions							tct

	--  			INNER JOIN tbItemTransactions						tit
	--  			ON  tit.comp_id        = tct.comp_id
	--  			AND tit.bra_id		   = tct.bra_id
	--  			AND tit.ct_transaction = tct.ct_transaction
	--
	--  			LEFT JOIN tbBranch									tb
	--  			ON  tb.comp_id = tct.comp_id
	--  			AND tb.bra_id  = tct.bra_id
	--
	--  			INNER JOIN tbItem									ti
	--  			ON  ti.comp_id = tit.comp_id
	--  			AND ti.item_id = tit.item_id
	--
	--  			LEFT JOIN tbTaxMovements							ttm
	--  			ON  ttm.comp_id = tct.comp_id
	--  			AND ttm.bra_id = tct.bra_id
	--  			AND ttm.ct_transaction = tct.ct_transaction
	--  			AND ttm.it_transaction = tit.it_transaction
	--
	--  			LEFT JOIN tbTaxName									ttn
	--  			ON  ttn.comp_id = tct.comp_id
	--  			And ttn.tax_id = ttm.tax_id
	--
	--  			LEFT JOIN tbItemTransactionImportData				titid
	--  			ON 	titid.comp_id = tit.comp_id
	--  			AND titid.ct_transaction = tit.ct_transaction
	--  			AND titid.it_transaction = tit.it_transaction
	--
	--  			LEFT JOIN tbImportData								tid
	--  			ON tid.comp_id = tct.comp_id
	--  			AND tid.bra_id = tct.bra_id
	--  			AND tid.ct_transaction = tct.ct_transaction
	--  			AND tid.it_transaction = tit.it_transaction
	--
	--  			LEFT JOIN tbItemSerials								tis
	--  			ON  tis.comp_id			= tct.comp_id
	--  			AND tis.ct_transaction	= tct.ct_transaction
	--  			AND tis.it_transaction	= tit.it_transaction
	--  			AND tis.item_id			= tit.item_id
	--
	--  			INNER JOIN tbsysDocuments							td
	--  			ON td.sd_id = tct.sd_id
	--
	--			left join tbItemTransactions						tit2
	--			on  tit2.comp_id		= tit.comp_id
	--			and tit2.ct_transaction = tit.it_transaction_original
	--
	--			left join tbCommercialTransactions					tct2
	--			on  tct2.comp_id		= tit2.comp_id
	--			and tct2.bra_id			= tit2.bra_id
	--			and tct2.ct_transaction = tit2.ct_transaction
	--
	--			INNER JOIN tbItemStorage tis2
	--			ON  tis2.comp_id = tit.comp_id
	--			AND tis2.stor_id = tit.stor_id
	--			AND tis2.item_id = tit.item_id
	--
	--			INNER JOIN tbStorage ts
	--			ON  ts.comp_id = tis2.comp_id
	--			AND ts.stor_id = tis2.stor_id

		  Where tct.comp_id		   = @comp_id
		  And   tct.ct_transaction = @ct_transaction
	--------------------------------------------------------------------------------------------------





	/*:::Datos de la Sucursal:::*/

		Select
		tb.bra_MainDesc,
		tb.bra_desc,
		tb.bra_address,
		tb.bra_address1,
		tb.bra_phone,
		tb.bra_taxNumber,
		tct.ct_kindOf,
		--tdf.df_fromDate,
		isnull(tb.bra_taxNumber2,'')				[bra_taxNumber2],
		isnull(tb.bra_taxNumber3,'')				[bra_taxNumber3],
		isnull(td.sd_desc,'')						[sd_desc],
		convert(varchar,tct.ct_date,103)			[ct_date],
		convert(varchar,tb.bra_processingDate,103)	[bra_datep],
		convert(varchar,tct.ct_taxDate,103)			[ct_taxDate],
		convert(varchar,tct.ct_payDate,103)			[ct_payDate],
		tu.user_lastname + ', ' + tu.user_firstname [user_name],
		isnull(tpt.pt_desc,'')						[pt_desc]





		From tbCommercialTransactions tct			WITH (NOLOCK)

			Inner Join tbBranch tb					WITH (NOLOCK)
			On  tb.comp_id = tct.comp_id
			AND tb.bra_id  = tct.bra_id

			Inner JOIN tbsysDocuments td			WITH (NOLOCK)
			ON td.sd_id = tct.sd_id

			LEFT JOIN tbUser tu						WITH (NOLOCK)
			ON tu.[user_id] = tct.[user_id]

			LEFT JOIN tbPurchaseTerms tpt			WITH (NOLOCK)
			ON	tpt.comp_id = tct.comp_id AND
				tpt.pt_id	= tct.pt_id


		Where tct.comp_id		 = @comp_id
		And	  tct.ct_transaction = @ct_transaction


	/*:::::Datos del Proveedor:::::*/
		SELECT

			ts2.supp_name,
			ts2.supp_address,
			ts2.supp_city,
			ts2.supp_zip,
			ts2.supp_phone1,
			ts2.supp_fax,
			tc2.country_desc,
			ts.state_desc,
			ts2.supp_taxNumber,

			tc3.curr_desc [curr_supplier],
			tc4.curr_desc [curr_branch],

			tc5.curr_desc [curr_id4Exchange],
			tc6.curr_desc [curr_idExchange],
	--		tct.curr_id4Exchange,

			dbo.fnGetExchange2(@comp_id,1 ,ts2.curr_id ,   @curr_id_transaction,@curr_id4Exchange,tb.curr_id, @ct_curr_id4Exchange,  0) [exchange1],

			dbo.fnGetExchange2(@comp_id,1,tb.curr_id4Exchange, tct.curr_id4Exchange, @curr_id_transaction,@curr_id4Exchange, @ct_curr_id4Exchange,   0) [exchange2],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)		[ct_transaction],
			ISNULL(tctn.ctn_note1,'')		[note1],
			ISNULL(tctn.ctn_note2,'')		[note2],
			ISNULL(tctn.ctn_note3,'')		[note3],
			ISNULL(tctn.ctn_note4,'')		[note4],
			tprh.por_id						[por_id]



		--Condición de venta

		From tbCommercialTransactions tct					WITH (NOLOCK)


			INNER JOIN tbSupplier ts2						WITH (NOLOCK)
			ON  ts2.comp_id = tct.comp_id
			AND ts2.supp_id = tct.supp_id

			Inner Join tbsysCountry tc2						WITH (NOLOCK)
			On  tc2.country_id = ts2.country_id

			Inner Join tbsysState ts						WITH (NOLOCK)
			On  ts.country_id = ts2.country_id
			and ts.state_id   = ts2.state_id

			INNER JOIN tbBranch tb							WITH (NOLOCK)
			ON  tb.comp_id = tct.comp_id
			AND tb.bra_id = tct.bra_id

			LEFT JOIN tbsysCurrency tc3						WITH (NOLOCK)
			ON tc3.curr_id = ts2.curr_id

			LEFT JOIN tbsysCurrency tc4						WITH (NOLOCK)
			ON tc4.curr_id = tb.curr_id

			LEFT JOIN tbsysCurrency tc5						WITH (NOLOCK)
			ON tc5.curr_id = tb.curr_id4Exchange

			LEFT JOIN tbsysCurrency tc6						WITH (NOLOCK)
			ON tc6.curr_id = tct.curr_id4Exchange

			LEFT JOIN tbCommercialTransactionNotes tctn		WITH (NOLOCK)
			ON  tctn.comp_id	    = tct.comp_id
			AND tctn.bra_id		    = tct.bra_id
			AND tctn.ct_transaction = tct.ct_transaction

			LEFT JOIN tbPurchaseorderReceptionHeader tprh	WITH (NOLOCK)
			ON	tprh.comp_id		= tct.comp_id	AND
				tprh.ct_transaction = tct.ct_transaction

	--		INNER JOIN tbItemTransactions tit
	--		ON  tit.comp_id = tct.comp_id
	--		AND tit.bra_id = tct.bra_id
	--		AND tit.ct_transaction = tct.ct_transaction


		Where tct.comp_id		 = @comp_id
		And   tct.ct_transaction = @ct_transaction




	/************************/
	DECLARE @total		DECIMAL(18,6)
	DECLARE @subtotalb	DECIMAL(18,6)
	SELECT 	@total		= sum(tit.it_qty * tit.it_price),
			@subtotalb	= sum(tit.it_qty * tit.it_priceB)

		  FROM		tbCommercialTransactions							tct		WITH (NOLOCK)

  					INNER JOIN tbItemTransactions						tit		WITH (NOLOCK)
  					ON  tit.comp_id        = tct.comp_id
					--AND tit.bra_id		   = tct.bra_id
  					AND tit.ct_transaction = tct.ct_transaction

		  Where		tct.comp_id		   = @comp_id
		  And		tct.ct_transaction = @ct_transaction
	/************************/


	/*:::Detalles::: */
	  SELECT DISTINCT
		tit.it_qty,
		right(ti.item_code,20) [item_code],
		ti.item_desc,
		ti.item_detail,
		tit.it_price,
		ISNULL(tid.impData_Number_local,'') + ' ' + ISNULL(tid.impData_Custom_local,'')			    [Despacho],
		ISNULL(tit.it_guarantee,0)																	[it_guarantee],
		tit.it_qty * tit.it_price																	[Total],
		(SELECT TOP 1 ttn.tax_percentage
					FROM tbTaxMovements ttm			WITH (NOLOCK)
						INNER JOIN tbTaxName ttn	WITH (NOLOCK)
							ON		ttn.comp_id	= ttm.comp_id
								and ttn.tax_id	= ttm.tax_id
					 WHERE  ttm.comp_id			= tit.comp_id
						AND ttm.bra_id			= tit.bra_id
						AND ttm.ct_transaction	= tit.ct_transaction
						AND ttm.it_transaction	= tit.it_transaction
						AND ttn.tax_class = 1

				)																					[tax_percentage3],
		/*ISNULL(tis.is_serial,'')*/ ''																[is_serial],
		tit.it_priceB,
		tit.it_qty * tit.it_priceB																	[subtotalb],
		ts.stor_desc,

		CASE WHEN td.sd_isCredit = 'false'
			THEN (SELECT tov.optval_desc FROM tbsysOptionsValues tov	WITH (NOLOCK)
					WHERE tov.optval_class = 81 AND tov.lang_id = @lang_id AND tov.optval_id = 0)
			ELSE (SELECT tov.optval_desc FROM tbsysOptionsValues tov	WITH (NOLOCK)
					WHERE tov.optval_class = 81 AND tov.lang_id = @lang_id AND tov.optval_id = 1)
		END [movement],
		case when tct2.ct_transaction is null then ''
		else	dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct2.ct_transaction)
		end		[ct_transaction],

		@total																						[totalcosto],
		@subtotalb																					[totalcostoadic],
		tc.curr_symbol,
		tit.it_transaction,
		ISNULL(tid.impData_Origin,'')																[impData_Origin],
		ISNULL(tid.impData_From,'')																	[impData_From]


	  FROM  tbCommercialTransactions							tct			WITH (NOLOCK)

  			INNER JOIN tbItemTransactions						tit			WITH (NOLOCK)
  			ON  tit.comp_id        = tct.comp_id
  			AND tit.bra_id		   = tct.bra_id
  			AND tit.ct_transaction = tct.ct_transaction

  			LEFT JOIN tbBranch									tb			WITH (NOLOCK)
  			ON  tb.comp_id = tct.comp_id
  			AND tb.bra_id  = tct.bra_id

  			INNER JOIN tbItem									ti			WITH (NOLOCK)
  			ON  ti.comp_id = tit.comp_id
  			AND ti.item_id = tit.item_id

	--  		LEFT JOIN tbTaxMovements							ttm
	--  		ON  ttm.comp_id = tct.comp_id
	--  		AND ttm.bra_id = tct.bra_id
	--  		AND ttm.ct_transaction = tct.ct_transaction
	--  		AND ttm.it_transaction = tit.it_transaction
	--
	--  		LEFT JOIN tbTaxName									ttn
	--  		ON  ttn.comp_id		= tct.comp_id
	--  		And ttn.tax_id		= ttm.tax_id
	--  		AND ttn.tax_class	= 1							-- Esto puede llegar a duplicar un item en el listado si hay mas de un impuesto del mismo tipo x renglon.!!!!

  			LEFT JOIN tbItemTransactionImportData				titid		WITH (NOLOCK)
  			ON 	titid.comp_id = tit.comp_id
  			AND titid.ct_transaction = tit.ct_transaction
  			AND titid.it_transaction = tit.it_transaction

  			LEFT JOIN tbImportData								tid			WITH (NOLOCK)
  			ON tid.comp_id = tct.comp_id
  			AND tid.bra_id = tct.bra_id
  			AND tid.ct_transaction = tct.ct_transaction
  			AND tid.it_transaction = tit.it_transaction

	--  		LEFT JOIN tbItemSerials								tis
	--  		ON  tis.comp_id			= tct.comp_id
	--  		AND tis.ct_transaction	= tct.ct_transaction
	--  		AND tis.it_transaction	= tit.it_transaction
	--  		AND tis.item_id			= tit.item_id

  			INNER JOIN tbsysDocuments							td			WITH (NOLOCK)
  			ON td.sd_id = tct.sd_id

			--Parte 816 . se agregan los left join para recuperar la descripción(nº de remito correspodiente)__ GA
			left join tbItemTransactions						tit2		WITH (NOLOCK)
			on  tit2.comp_id		= tit.comp_id
			and tit2.ct_transaction = tit.it_transaction_original

			left join tbCommercialTransactions					tct2		WITH (NOLOCK)
			on  tct2.comp_id		= tit2.comp_id
			and tct2.bra_id			= tit2.bra_id
			and tct2.ct_transaction = tit2.ct_transaction

			INNER JOIN tbItemStorage tis2									WITH (NOLOCK)
			ON  tis2.comp_id = tit.comp_id
			AND tis2.stor_id = tit.stor_id
			AND tis2.item_id = tit.item_id

			INNER JOIN tbStorage ts											WITH (NOLOCK)
			ON  ts.comp_id = tis2.comp_id
			AND ts.stor_id = tis2.stor_id

			left join tbsysCurrency tc										WITH (NOLOCK)
			on	tc.curr_id = tit.curr_id



	/*		--Agregado...Join a la vista de la tabla Commercial Transactions
			inner join dbo.vwCommercialTransactions_forSales					vwct
			on  tct.comp_id			= vwct.comp_id
			and tct.bra_id			= vwct.bra_id
			and tct.ct_transaction	= vwct.ct_transaction
			and vwct.sd_isReceipt	= 'false'
			and vwct.sd_isInBalance	= 'true'*/


	  Where tct.comp_id		   = @comp_id
	  And   tct.ct_transaction = @ct_transaction


	--Ticket 224 STL
	--ORDER BY ti.item_desc ASC

	UNION

		select DISTINCT
				NULL,
				NULL,
				isnull(tpc.puco_desc,''),
				NULL,
				NULL,
				NULL,
				NULL,
				tpcm.pcm_total,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				tc.curr_symbol,
				NULL,
				'',
				''


		from tbCommercialTransactions					tct			WITH (NOLOCK)

		inner join tbPurchaseConceptMovements			tpcm		WITH (NOLOCK)
		on	tpcm.comp_id		= tct.comp_id	AND
			tpcm.bra_id			= tct.bra_id	AND
			tpcm.ct_transaction = tct.ct_transaction

		left join tbPurchaseConcept						tpc			WITH (NOLOCK)
		on  tpc.comp_id			= tpcm.comp_id   AND
			tpc.puco_id			= tpcm.puco_id

		left join tbsysCurrency							tc			WITH (NOLOCK)
		on	tc.curr_id			= tpcm.curr_id


		Where	tct.comp_id		   = @comp_id	AND
				tct.ct_transaction = @ct_transaction


	ORDER BY tit.it_transaction ASC


	  exec [spReports_getData]@comp_id, @lang_id,	@page_id

	  /*::::::Para el subreporte::::::*/

		SELECT ISNULL(tct.ct_total,0)				[ct_total],
			   ISNULL(tct.ct_subtotal,0)			[ct_subtotal],
			   ISNULL(tct.ct_discount,0)			[ct_discount],
			   ISNULL(ttm.tm_total,0)				[tm_total],
			   ISNULL(ttm.percentaje,0)				[tax_percentage],
			   ISNULL(ttm2.percentaje,0)			[tax_percentage2],
			   isnull(ttn.tax_desc + ': ',' ')		[tax_desc],
			   tc.curr_symbol,

				-- ---------------------------------------------------------
				-- MOS 12-2021 x Maxi PL para quesalga con el Tipo de cambio del cpte.
				-- ---------------------------------------------------------
			   dbo.fnGetExchange2(tct.comp_id,
								  tct.ct_Atotal,
								  tct.ct_ACurrency,
								  ts.curr_id,
								  ts.curr_id,
								  tct.ct_ACurrency,

								 tct.ct_ACurrencyExchange,
								 'False')			[ct_total_supplier],
			   --dbo.fnGetExchange(tct.comp_id,
						--		 tct.ct_total,
						--		 tct.curr_id_transaction,
						--		 ts.curr_id,
						--		 0,
						--		 0,
						--		 'False')			[ct_total_supplier],
				-- ---------------------------------------------------------


				tc2.curr_symbol						[curr_symbol_supplier],
				ISNULL(tct.ct_taxes,0)				[ct_taxes]


		From tbCommercialTransactions tct							WITH (NOLOCK)

			LEFT JOIN tbBranch tb									WITH (NOLOCK)
			ON tb.comp_id = tct.comp_id
			AND tb.bra_id = tct.bra_id

			LEFT  Join tbTaxMovements ttm							WITH (NOLOCK)
			On  ttm.comp_id = tct.comp_id
			And ttm.ct_transaction = tct.ct_transaction

			left Outer Join vwsysTaxClassIVA_Taxes vtcit			WITH (NOLOCK)
			On vtcit.tax_class = ttm.tax_id

			LEFT  Join tbTaxMovements ttm2						WITH (NOLOCK)
			On  ttm2.comp_id = tct.comp_id
			And ttm2.ct_transaction = tct.ct_transaction

			LEFT Join vwsysTaxClassIVA_Taxes vtcit2				WITH (NOLOCK)
			On vtcit2.tax_class = ttm2.tax_id

			left Join tbTaxName ttn								WITH (NOLOCK)
			On ttn.comp_id = tct.comp_id
			And ttn.tax_id = ttm.tax_id

			left join tbsysCurrency tc							WITH (NOLOCK)
			on tc.curr_id = tct.curr_id_transaction

			LEFT JOIN tbSupplier				ts				WITH(NOLOCK)
			ON	ts.comp_id = tct.comp_id		AND
				ts.supp_id = tct.supp_id

			LEFT JOIN tbsysCurrency				tc2				WITH(NOLOCK)
			ON tc2.curr_id = ts.curr_id

		Where tct.comp_id		 = @comp_id
		And	  tct.ct_transaction = @ct_transaction


		--------------------------------------------------
		/*:::::: Subreporte - Resumen de Impuestos ::::::*/


		SELECT	ISNULL(ttn.tax_desc,'')			[tax_desc],
				sum(ttm.tm_total)				[tm_total],
				count(ttm.tm_total)				[record_number]

			From tbCommercialTransactions						tct			WITH (NOLOCK)

				LEFT  Join tbTaxMovements						ttm			WITH (NOLOCK)
				On  ttm.comp_id			= tct.comp_id
				And ttm.ct_transaction	= tct.ct_transaction

				left Join tbTaxName								ttn			WITH (NOLOCK)
				On ttn.comp_id = tct.comp_id
				And ttn.tax_id = ttm.tax_id

				left join tbsysCurrency							tc			WITH (NOLOCK)
				on tc.curr_id = tct.curr_id_transaction

			Where tct.comp_id		 = @comp_id
			And	  tct.ct_transaction = @ct_transaction

			GROUP BY ttn.tax_desc,
					 tc.curr_id

			ORDER BY ttn.tax_desc

		------------------------------------------------
		------------------------------------------------



		--------------------------------------------------
		/*:::::: Subreporte - Resumen Contable ::::::*/


		SELECT  ISNULL(ta.acc_desc,'')	[acc_desc],
				sum(tatd.dacc_debit)	[dacc_debit],
				sum(tatd.dacc_credit)	[dacc_credit],
				count(tatd.dacc_debit)	[record_number],
				tath.hacc_date,
				tath.hacc_number,
				ta.acc_code

			From tbCommercialTransactions							tct			WITH (NOLOCK)

				LEFT  JOIN tbAccountTransactionDetail				tatd		WITH (NOLOCK)
				ON	tatd.comp_id			= tct.comp_id		AND
					tatd.bra_id				= tct.bra_id		AND
					tatd.ct_transaction		= tct.ct_transaction

				LEFT JOIN tbAccountTransactionHead tath							WITH (NOLOCK)
				ON	tath.comp_id			= tatd.comp_id		AND
					tath.bra_id				= tatd.bra_id		AND
					tath.hacc_transaction	= tatd.hacc_transaction

				LEFT JOIN tbAccountant								ta			WITH (NOLOCK)
				ON	ta.comp_id				= tatd.comp_id		AND
					ta.acc_count_id			= tatd.acc_count_id

			Where tct.comp_id		 = @comp_id
			And	  tct.ct_transaction = @ct_transaction

			GROUP BY ta.acc_desc,
					 tatd.acc_count_id,
					 tath.hacc_date,
					 tath.hacc_number,
					 ta.acc_code

			ORDER BY ta.acc_desc


		------------------------------------------------
		------------------------------------------------


		--------------------------------------------------
		/*:::::: Subreporte - Recepcion  - Notas ::::::*/


			SELECT  tov_supp.optval_desc						[por_charge2Supplier],
					isnull(tprh.por_charge2Supplier_Note,'')	[por_charge2Supplier_Note],
					isnull(tov_dl.optval_desc,'')				[por_charge2Delivery],
					isnull(tprh.por_charge2Delivery_Note,'')	[por_charge2Delivery_Note],
					ISNULL(tpt.ptr_name,'')						[ptr_name],
					ISNULL(tut.utexts_desc,'')					[por_title]

			FROM tbPurchaseorderReceptionHeader										tprh		WITH (NOLOCK)

			LEFT JOIN tbsysUniqueTexts												tut			WITH (NOLOCK)
			ON  tut.lang_id		= @lang_id
			AND tut.utexts_id	= 30664

			LEFT JOIN tbsysOptionsValues											tov_supp	WITH (NOLOCK)
			ON	tov_supp.lang_id			= @lang_id					AND
				tov_supp.optval_class		= 1							AND
				tov_supp.optval_id			= tprh.por_charge2Supplier

			LEFT JOIN tbsysOptionsValues											tov_dl		WITH (NOLOCK)
			ON	tov_dl.lang_id			= @lang_id						AND
				tov_dl.optval_class		= 1								AND
				tov_dl.optval_id		= tprh.por_charge2Delivery

			LEFT JOIN tbPurchaseTransport											tpt			WITH (NOLOCK)
			ON	tpt.comp_id				= tprh.comp_id					AND
				tpt.ptr_id				= tprh.ptr_id


			Where tprh.comp_id		  = @comp_id
			And	  tprh.ct_transaction = @ct_transaction




		------------------------------------------------
		------------------------------------------------






END
GO






CREATE PROCEDURE [dbo].[spCommercialTransactions_getReportForBranchTransfer_4POR]
(
	@comp_id			int,
	@lang_id			Int,
	@page_id			Int,
	@ct_transaction		Int
)
AS


BEGIN




    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------


	SET NOCOUNT ON



	-------------------------------------------------------------
	/*
	DECLARE
		@comp_id			INT,
		@lang_id			INT,
		@page_id			INT,
		@ct_transaction		INT

	SELECT
		@comp_id			= 1,
		@lang_id			= 2,
		@page_id			= 10061,
		@ct_transaction		= 11688
*/
	-------------------------------------------------------------

	--------------------------------------------------------------------------------------------------
	--Variables en las cuales se guarda la cotización
	----------------------------------------------------------------------------------------------------

		DECLARE
			@curr_id_transaction		INT,
			@curr_id4Exchange			INT,
			@ct_curr_id4Exchange		DECIMAL(19,6)



		SELECT
			@curr_id_transaction	= tct.curr_id_transaction,
			@curr_id4Exchange		= tct.curr_id4Exchange,
			@ct_curr_id4Exchange	= tct.ct_curr_IdExchange


		  FROM  tbCommercialTransactions							tct

	--  			INNER JOIN tbItemTransactions						tit
	--  			ON  tit.comp_id        = tct.comp_id
	--  			AND tit.bra_id		   = tct.bra_id
	--  			AND tit.ct_transaction = tct.ct_transaction
	--
	--  			LEFT JOIN tbBranch									tb
	--  			ON  tb.comp_id = tct.comp_id
	--  			AND tb.bra_id  = tct.bra_id
	--
	--  			INNER JOIN tbItem									ti
	--  			ON  ti.comp_id = tit.comp_id
	--  			AND ti.item_id = tit.item_id
	--
	--  			LEFT JOIN tbTaxMovements							ttm
	--  			ON  ttm.comp_id = tct.comp_id
	--  			AND ttm.bra_id = tct.bra_id
	--  			AND ttm.ct_transaction = tct.ct_transaction
	--  			AND ttm.it_transaction = tit.it_transaction
	--
	--  			LEFT JOIN tbTaxName									ttn
	--  			ON  ttn.comp_id = tct.comp_id
	--  			And ttn.tax_id = ttm.tax_id
	--
	--  			LEFT JOIN tbItemTransactionImportData				titid
	--  			ON 	titid.comp_id = tit.comp_id
	--  			AND titid.ct_transaction = tit.ct_transaction
	--  			AND titid.it_transaction = tit.it_transaction
	--
	--  			LEFT JOIN tbImportData								tid
	--  			ON tid.comp_id = tct.comp_id
	--  			AND tid.bra_id = tct.bra_id
	--  			AND tid.ct_transaction = tct.ct_transaction
	--  			AND tid.it_transaction = tit.it_transaction
	--
	--  			LEFT JOIN tbItemSerials								tis
	--  			ON  tis.comp_id			= tct.comp_id
	--  			AND tis.ct_transaction	= tct.ct_transaction
	--  			AND tis.it_transaction	= tit.it_transaction
	--  			AND tis.item_id			= tit.item_id
	--
	--  			INNER JOIN tbsysDocuments							td
	--  			ON td.sd_id = tct.sd_id
	--
	--			left join tbItemTransactions						tit2
	--			on  tit2.comp_id		= tit.comp_id
	--			and tit2.ct_transaction = tit.it_transaction_original
	--
	--			left join tbCommercialTransactions					tct2
	--			on  tct2.comp_id		= tit2.comp_id
	--			and tct2.bra_id			= tit2.bra_id
	--			and tct2.ct_transaction = tit2.ct_transaction
	--
	--			INNER JOIN tbItemStorage tis2
	--			ON  tis2.comp_id = tit.comp_id
	--			AND tis2.stor_id = tit.stor_id
	--			AND tis2.item_id = tit.item_id
	--
	--			INNER JOIN tbStorage ts
	--			ON  ts.comp_id = tis2.comp_id
	--			AND ts.stor_id = tis2.stor_id

		  Where tct.comp_id		   = @comp_id
		  And   tct.ct_transaction = @ct_transaction
	--------------------------------------------------------------------------------------------------





	/*:::Datos de la Sucursal:::*/

		Select
		tb.bra_MainDesc,
		tb.bra_desc,
		tb.bra_address,
		tb.bra_address1,
		tb.bra_phone,
		tb.bra_taxNumber,
		tct.ct_kindOf,
		--tdf.df_fromDate,
		isnull(tb.bra_taxNumber2,'')				[bra_taxNumber2],
		isnull(tb.bra_taxNumber3,'')				[bra_taxNumber3],
		isnull(td.sd_desc,'')						[sd_desc],
		convert(varchar,tct.ct_date,103)			[ct_date],
		convert(varchar,tb.bra_processingDate,103)	[bra_datep],
		convert(varchar,tct.ct_taxDate,103)			[ct_taxDate],
		convert(varchar,tct.ct_payDate,103)			[ct_payDate],
		tu.user_lastname + ', ' + tu.user_firstname [user_name]





		From tbCommercialTransactions tct			WITH (NOLOCK)

			Inner Join tbBranch tb					WITH (NOLOCK)
			On  tb.comp_id = tct.comp_id
			AND tb.bra_id  = tct.bra_id

			Inner JOIN tbsysDocuments td			WITH (NOLOCK)
			ON td.sd_id = tct.sd_id

			LEFT JOIN tbUser tu						WITH (NOLOCK)
			ON tu.[user_id] = tct.[user_id]


		Where tct.comp_id		 = @comp_id
		And	  tct.ct_transaction = @ct_transaction


	/*:::::Datos del Proveedor:::::*/
		SELECT

			ts2.supp_name,
			ts2.supp_address,
			ts2.supp_city,
			ts2.supp_zip,
			ts2.supp_phone1,
			ts2.supp_fax,
			tc2.country_desc,
			ts.state_desc,
			ts2.supp_taxNumber,

			tc3.curr_desc [curr_supplier],
			tc4.curr_desc [curr_branch],

			tc5.curr_desc [curr_id4Exchange],
			tc6.curr_desc [curr_idExchange],
	--		tct.curr_id4Exchange,

			dbo.fnGetExchange2(@comp_id,1 ,ts2.curr_id , tb.curr_id,  @curr_id_transaction,@curr_id4Exchange, @ct_curr_id4Exchange,  0) [exchange1],

			dbo.fnGetExchange2(@comp_id,1,tb.curr_id4Exchange, tct.curr_id4Exchange, @curr_id_transaction,@curr_id4Exchange, @ct_curr_id4Exchange,   0) [exchange2],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)		[ct_transaction],
			ISNULL(tctn.ctn_note1,'')		[note1],
			ISNULL(tctn.ctn_note2,'')		[note2],
			ISNULL(tctn.ctn_note3,'')		[note3],
			ISNULL(tctn.ctn_note4,'')		[note4],
			tprh.por_id						[por_id]



		--Condición de venta

		From tbCommercialTransactions tct					WITH (NOLOCK)


			INNER JOIN tbSupplier ts2						WITH (NOLOCK)
			ON  ts2.comp_id = tct.comp_id
			AND ts2.supp_id = tct.supp_id

			Inner Join tbsysCountry tc2						WITH (NOLOCK)
			On  tc2.country_id = ts2.country_id

			Inner Join tbsysState ts						WITH (NOLOCK)
			On  ts.country_id = ts2.country_id
			and ts.state_id   = ts2.state_id

			INNER JOIN tbBranch tb							WITH (NOLOCK)
			ON  tb.comp_id = tct.comp_id
			AND tb.bra_id = tct.bra_id

			LEFT JOIN tbsysCurrency tc3						WITH (NOLOCK)
			ON tc3.curr_id = ts2.curr_id

			LEFT JOIN tbsysCurrency tc4						WITH (NOLOCK)
			ON tc4.curr_id = tb.curr_id

			LEFT JOIN tbsysCurrency tc5						WITH (NOLOCK)
			ON tc5.curr_id = tb.curr_id4Exchange

			LEFT JOIN tbsysCurrency tc6						WITH (NOLOCK)
			ON tc6.curr_id = tct.curr_id4Exchange

			LEFT JOIN tbCommercialTransactionNotes tctn		WITH (NOLOCK)
			ON  tctn.comp_id	    = tct.comp_id
			AND tctn.bra_id		    = tct.bra_id
			AND tctn.ct_transaction = tct.ct_transaction

			LEFT JOIN tbPurchaseorderReceptionHeader tprh	WITH (NOLOCK)
			ON	tprh.comp_id		= tct.comp_id	AND
				tprh.ct_transaction = tct.ct_transaction

	--		INNER JOIN tbItemTransactions tit
	--		ON  tit.comp_id = tct.comp_id
	--		AND tit.bra_id = tct.bra_id
	--		AND tit.ct_transaction = tct.ct_transaction


		Where tct.comp_id		 = @comp_id
		And   tct.ct_transaction = @ct_transaction




	/************************/
		DECLARE @total		DECIMAL(18,6)
		DECLARE @subtotalb	DECIMAL(18,6)
	  SELECT 	@total		= sum(tit.it_qty * tit.it_price),
				@subtotalb	= sum(tit.it_qty * tit.it_priceB)

	  FROM		tbCommercialTransactions							tct		WITH (NOLOCK)

  				INNER JOIN tbItemTransactions						tit		WITH (NOLOCK)
  				ON  tit.comp_id        = tct.comp_id
  				--AND tit.bra_id		   = tct.bra_id
  				AND tit.ct_transaction = tct.ct_transaction

	  Where		tct.comp_id		   = @comp_id
	  And		tct.ct_transaction = @ct_transaction
	/************************/


	/*:::Detalles::: */
	  SELECT DISTINCT
					sum(tit.it_qty) [it_qty],
					right(ti.item_code,20) [item_code],
					ti.item_desc,
					ts.stor_desc

	  FROM  tbCommercialTransactions							tct			WITH (NOLOCK)

  			INNER JOIN tbItemTransactions						tit			WITH (NOLOCK)
  			ON  tit.comp_id        = tct.comp_id
  			AND tit.bra_id		   = tct.bra_id
  			AND tit.ct_transaction = tct.ct_transaction

  			LEFT JOIN tbBranch									tb			WITH (NOLOCK)
  			ON  tb.comp_id = tct.comp_id
  			AND tb.bra_id  = tct.bra_id

  			INNER JOIN tbItem									ti			WITH (NOLOCK)
  			ON  ti.comp_id = tit.comp_id
  			AND ti.item_id = tit.item_id

	--  		LEFT JOIN tbTaxMovements							ttm
	--  		ON  ttm.comp_id = tct.comp_id
	--  		AND ttm.bra_id = tct.bra_id
	--  		AND ttm.ct_transaction = tct.ct_transaction
	--  		AND ttm.it_transaction = tit.it_transaction
	--
	--  		LEFT JOIN tbTaxName									ttn
	--  		ON  ttn.comp_id		= tct.comp_id
	--  		And ttn.tax_id		= ttm.tax_id
	--  		AND ttn.tax_class	= 1							-- Esto puede llegar a duplicar un item en el listado si hay mas de un impuesto del mismo tipo x renglon.!!!!

  			LEFT JOIN tbItemTransactionImportData				titid		WITH (NOLOCK)
  			ON 	titid.comp_id = tit.comp_id
  			AND titid.ct_transaction = tit.ct_transaction
  			AND titid.it_transaction = tit.it_transaction

  			LEFT JOIN tbImportData								tid			WITH (NOLOCK)
  			ON tid.comp_id = tct.comp_id
  			AND tid.bra_id = tct.bra_id
  			AND tid.ct_transaction = tct.ct_transaction
  			AND tid.it_transaction = tit.it_transaction

	--  		LEFT JOIN tbItemSerials								tis
	--  		ON  tis.comp_id			= tct.comp_id
	--  		AND tis.ct_transaction	= tct.ct_transaction
	--  		AND tis.it_transaction	= tit.it_transaction
	--  		AND tis.item_id			= tit.item_id

  			INNER JOIN tbsysDocuments							td			WITH (NOLOCK)
  			ON td.sd_id = tct.sd_id

			--Parte 816 . se agregan los left join para recuperar la descripción(nº de remito correspodiente)__ GA
			left join tbItemTransactions						tit2		WITH (NOLOCK)
			on  tit2.comp_id		= tit.comp_id
			and tit2.ct_transaction = tit.it_transaction_original

			left join tbCommercialTransactions					tct2		WITH (NOLOCK)
			on  tct2.comp_id		= tit2.comp_id
			and tct2.bra_id			= tit2.bra_id
			and tct2.ct_transaction = tit2.ct_transaction

			INNER JOIN tbItemStorage tis2									WITH (NOLOCK)
			ON  tis2.comp_id = tit.comp_id
			AND tis2.stor_id = tit.stor_id
			AND tis2.item_id = tit.item_id

			INNER JOIN tbStorage ts											WITH (NOLOCK)
			ON  ts.comp_id = tis2.comp_id
			AND ts.stor_id = tis2.stor_id

			left join tbsysCurrency tc										WITH (NOLOCK)
			on	tc.curr_id = tit.curr_id



	/*		--Agregado...Join a la vista de la tabla Commercial Transactions
			inner join dbo.vwCommercialTransactions_forSales					vwct
			on  tct.comp_id			= vwct.comp_id
			and tct.bra_id			= vwct.bra_id
			and tct.ct_transaction	= vwct.ct_transaction
			and vwct.sd_isReceipt	= 'false'
			and vwct.sd_isInBalance	= 'true'*/


	  Where tct.comp_id		   = @comp_id
	  And   tct.ct_transaction = @ct_transaction

	  GROUP by ti.item_code,
			ti.item_desc,
			ts.stor_desc

	--Ticket 224 STL
	--ORDER BY ti.item_desc ASC

	UNION

		select DISTINCT
				NULL,
				NULL,
				isnull(tpc.puco_desc,''),
				NULL


		from tbCommercialTransactions					tct			WITH (NOLOCK)

		inner join tbPurchaseConceptMovements			tpcm		WITH (NOLOCK)
		on	tpcm.comp_id		= tct.comp_id	AND
			tpcm.bra_id			= tct.bra_id	AND
			tpcm.ct_transaction = tct.ct_transaction

		left join tbPurchaseConcept						tpc			WITH (NOLOCK)
		on  tpc.comp_id			= tpcm.comp_id   AND
			tpc.puco_id			= tpcm.puco_id

		left join tbsysCurrency							tc			WITH (NOLOCK)
		on	tc.curr_id			= tpcm.curr_id


		Where	tct.comp_id		   = @comp_id	AND
				tct.ct_transaction = @ct_transaction


	--ORDER BY tit.it_transaction ASC


	  exec [spReports_getData]@comp_id, @lang_id,	@page_id

--	  /*::::::Para el subreporte::::::*/
--
--		SELECT tct.ct_total,
--			   tct.ct_subtotal,
--			   tct.ct_discount,
--			   ISNULL(ttm.tm_total,0)				[tm_total],
--			   ISNULL(ttm.percentaje,0)				[tax_percentage],
--			   ISNULL(ttm2.percentaje,0)			[tax_percentage2],
--			   isnull(ttn.tax_desc + ': ',' ')		[tax_desc],
--			   tc.curr_symbol
--
--		From tbCommercialTransactions tct							WITH (NOLOCK)
--
--			LEFT JOIN tbBranch tb									WITH (NOLOCK)
--			ON tb.comp_id = tct.comp_id
--			AND tb.bra_id = tct.bra_id
--
--			LEFT  Join tbTaxMovements ttm							WITH (NOLOCK)
--			On  ttm.comp_id = tct.comp_id
--			And ttm.ct_transaction = tct.ct_transaction
--
--			left Outer Join vwsysTaxClassIVA_Taxes vtcit
--			On vtcit.tax_class = ttm.tax_id
--
--			LEFT  Join tbTaxMovements ttm2						WITH (NOLOCK)
--			On  ttm2.comp_id = tct.comp_id
--			And ttm2.ct_transaction = tct.ct_transaction
--
--			LEFT Join vwsysTaxClassIVA_Taxes vtcit2
--			On vtcit2.tax_class = ttm2.tax_id
--
--			left Join tbTaxName ttn								WITH (NOLOCK)
--			On ttn.comp_id = tct.comp_id
--			And ttn.tax_id = ttm.tax_id
--
--			left join tbsysCurrency tc							WITH (NOLOCK)
--			on tc.curr_id = tct.curr_id_transaction
--
--		Where tct.comp_id		 = @comp_id
--		And	  tct.ct_transaction = @ct_transaction
--
--
--		--------------------------------------------------
--		/*:::::: Subreporte - Resumen de Impuestos ::::::*/
--
--
--		SELECT	ttn.tax_desc					[tax_desc],
--				sum(ttm.tm_total)				[tm_total],
--				count(ttm.tm_total)				[record_number]
--
--			From tbCommercialTransactions						tct			WITH (NOLOCK)
--
--				LEFT  Join tbTaxMovements						ttm			WITH (NOLOCK)
--				On  ttm.comp_id			= tct.comp_id
--				And ttm.ct_transaction	= tct.ct_transaction
--
--				left Join tbTaxName								ttn			WITH (NOLOCK)
--				On ttn.comp_id = tct.comp_id
--				And ttn.tax_id = ttm.tax_id
--
--				left join tbsysCurrency							tc			WITH (NOLOCK)
--				on tc.curr_id = tct.curr_id_transaction
--
--			Where tct.comp_id		 = @comp_id
--			And	  tct.ct_transaction = @ct_transaction
--
--			GROUP BY ttn.tax_desc,
--					 tc.curr_id
--
--			ORDER BY ttn.tax_desc
--
--		------------------------------------------------
--		------------------------------------------------
--
--
--
--		--------------------------------------------------
--		/*:::::: Subreporte - Resumen Contable ::::::*/
--
--
--		SELECT  ta.acc_desc				[acc_desc],
--				sum(tatd.dacc_debit)	[dacc_debit],
--				sum(tatd.dacc_credit)	[dacc_credit],
--				count(tatd.dacc_debit)	[record_number],
--				tath.hacc_date,
--				tath.hacc_number,
--				ta.acc_code
--
--			From tbCommercialTransactions							tct			WITH (NOLOCK)
--
--				LEFT  JOIN tbAccountTransactionDetail				tatd		WITH (NOLOCK)
--				ON	tatd.comp_id			= tct.comp_id		AND
--					tatd.bra_id				= tct.bra_id		AND
--					tatd.ct_transaction		= tct.ct_transaction
--
--				LEFT JOIN tbAccountTransactionHead tath							WITH (NOLOCK)
--				ON	tath.comp_id			= tatd.comp_id		AND
--					tath.bra_id				= tatd.bra_id		AND
--					tath.hacc_transaction	= tatd.hacc_transaction
--
--				LEFT JOIN tbAccountant								ta			WITH (NOLOCK)
--				ON	ta.comp_id				= tatd.comp_id		AND
--					ta.acc_count_id			= tatd.acc_count_id
--
--			Where tct.comp_id		 = @comp_id
--			And	  tct.ct_transaction = @ct_transaction
--
--			GROUP BY ta.acc_desc,
--					 tatd.acc_count_id,
--					 tath.hacc_date,
--					 tath.hacc_number,
--					 ta.acc_code
--
--			ORDER BY ta.acc_desc
--
--
--		------------------------------------------------
--		------------------------------------------------
--

		--------------------------------------------------
		/*:::::: Subreporte - Recepcion  - Notas ::::::*/


			SELECT  tov_supp.optval_desc						[por_charge2Supplier],
					isnull(tprh.por_charge2Supplier_Note,'')	[por_charge2Supplier_Note],
					tov_dl.optval_desc							[por_charge2Delivery],
					isnull(tprh.por_charge2Delivery_Note,'')	[por_charge2Delivery_Note],
					tpt.ptr_name								[ptr_name],
					tut.utexts_desc								[por_title]

			FROM tbPurchaseorderReceptionHeader										tprh		WITH (NOLOCK)

			LEFT JOIN tbsysUniqueTexts												tut			WITH (NOLOCK)
			ON  tut.lang_id		= @lang_id
			AND tut.utexts_id	= 30664

			LEFT JOIN tbsysOptionsValues											tov_supp	WITH (NOLOCK)
			ON	tov_supp.lang_id			= @lang_id					AND
				tov_supp.optval_class		= 1							AND
				tov_supp.optval_id			= tprh.por_charge2Supplier

			LEFT JOIN tbsysOptionsValues											tov_dl		WITH (NOLOCK)
			ON	tov_dl.lang_id			= @lang_id						AND
				tov_dl.optval_class		= 1								AND
				tov_dl.optval_id		= tprh.por_charge2Delivery

			LEFT JOIN tbPurchaseTransport											tpt			WITH (NOLOCK)
			ON	tpt.comp_id				= tprh.comp_id					AND
				tpt.ptr_id				= tprh.ptr_id


			Where tprh.comp_id		  = @comp_id
			And	  tprh.ct_transaction = @ct_transaction




		------------------------------------------------
		------------------------------------------------






END
GO








CREATE  PROCEDURE [dbo].[spCommercialTransactions_getReportMysales]
(
	@comp_id			INT,
	@lang_id			INT,
    @page_id			INT,

    @ct_datefrom		DATETIME,
    @ct_dateto			DATETIME,
    @bra_id				INT,
	@user_id			INT,
	@prof_id			INT,
	@intBranch4Lang		int
)

AS



BEGIN




	SET NOCOUNT ON
    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------


	SET DATEFORMAT 'ymd'

	--------------------------------------------------------------------------------
	-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
	--------------------------------------------------------------------------------
	/*
	DECLARE

			@comp_id      AS INT,
			@lang_id      AS INT,
			@page_id      AS INT,

			@ct_dateto    AS DATETIME,
			@ct_datefrom  AS DATETIME,
			@bra_id       AS INT,
			@user_id      AS INT,
			@intBranch4Lang		int


	SELECT  @comp_id		= 1,
			@lang_id		= 2,
			@page_id		= 10067,


			@ct_datefrom	= '2013-09-01',
			@ct_dateto		= '2013-09-30',
			@bra_id			= -1,
			@user_id		= 41,
			@intBranch4Lang = 1
	drop table #tmpMySales
	*/
	--------------------------------------------------------------------------------


	SET @ct_datefrom = dbo.fnGetEnd_or_BeginOfDate(@ct_datefrom,0)
	SET @ct_dateto   = dbo.fnGetEnd_or_BeginOfDate(@ct_dateto,0)

	DECLARE @fun_id INT
	SET     @fun_id = 1




	declare
		@lmarkup	INT,
		@lmarkuppp	INT


	set @lmarkup = 1
	if exists (	select 1
	           		from tbControlProfiles tc	WITH (NOLOCK)
					WHERE	tc.comp_id	= @comp_id AND
							tc.bra_id	= @intBranch4Lang AND
							tc.prof_id	= @prof_id AND
							tc.page_id	= 211 and
							tc.ctrl_id	= 1885)
		begin
			set @lmarkup = 0
		end

	set @lmarkuppp = 1
	if exists (	select 1
	           		from tbControlProfiles tc	WITH (NOLOCK)
					where tc.comp_id = @comp_id AND tc.bra_id = @intBranch4Lang AND tc.prof_id = @prof_id AND
														tc.page_id = 211 and tc.ctrl_id = 1908)
		begin
			set @lmarkuppp = 0
		end


	set	@ct_dateto = dbo.fnGetEnd_or_BeginOfDate(@ct_dateto,1)

	SELECT     tct.ct_date												[ct_date],
			   tc.cust_name																				[cust_name],
			   dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)		[ct_transaction],
			   tct.ct_total		* vctfs.PlusOrMinus														[ct_total],
			   tc2.curr_desc																			[curr_desc],
			   ts.sm_name																				[sm_name],
			  (tct.ct_subtotal	* vctfs.PlusOrMinus)-  tct.ct_discount									[ct_subtotal],
			   IsNull(vctpam.MarkUp,0)			* @lmarkup												[MarkUp],
			   IsNull(vctpam.MarkUpPPPP,0)		* @lmarkuppp											[MarkUpPP],
			   vctpam.SumOfCost		* vctfs.PlusOrMinus													[Costo],
			   vctpam.SumOfCostPP	* vctfs.PlusOrMinus													[CostoPP],
			   vctpam.SumOfSale		* vctfs.PlusOrMinus													[Venta],
			   tct.ct_discount																			[ct_discount]


		INTO #tmpMySales
			FROM	tbCommercialTransactions						tct			WITH (NOLOCK)


			left JOIN tbCustomerFilterByUser						tcfbu		WITH (NOLOCK)
			ON	tcfbu.comp_id		= tct.comp_id
			AND tcfbu.bra_id		= tct.bra_id
			AND tcfbu.[user_id]		= @user_id
			AND tcfbu.sm_id			= tct.sm_id

			LEFT JOIN tbUserSalesmanRelation						tusr		WITH (NOLOCK)
			ON	tusr.comp_id		= tct.comp_id
			AND tusr.bra_id			= tct.bra_id
			AND tusr.[user_id]		= @user_id
			AND tusr.sm_id			= tct.sm_id

			INNER JOIN vwCommercialTransactions_forSales			vctfs		WITH (NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id
					--AND vctfs.bra_id			= tct.bra_id
			and vctfs.ct_transaction	= tct.ct_transaction

			left join vwCommercialTransactionsProfitAndMarckup		vctpam		WITH (NOLOCK)
			on	vctpam.comp_id			= tct.comp_id
			and vctpam.bra_id			= tct.bra_id
			and vctpam.ct_transaction	= tct.ct_transaction

			INNER JOIN tbCustomer									tc			WITH (NOLOCK)
			ON  tc.comp_id			 = tct.comp_id
			AND tc.cust_id			 = tct.cust_id

			INNER JOIN tbsysCurrency								tc2			WITH (NOLOCK)
			on tc2.curr_id			= tct.curr_id_transaction

			INNER JOIN tbSalesman									ts			WITH (NOLOCK)
			ON  ts.comp_id			= tct.comp_id
			AND ts.sm_id			= tct.sm_id

			inner JOIN tbUsers4BranchFilter							vubf		WITH (NOLOCK)
			ON	vubf.comp_id		= tct.comp_id
			AND vubf.bra_id			= tct.bra_id
			AND vubf.[user_id]		= @user_id

	WHERE	tct.comp_id			= @comp_id
	AND     (@bra_id			= -1  OR tct.bra_id	= @bra_id )
	AND		tct.sd_id			IN (1,3)
	AND 	tct.ct_date			BETWEEN   @ct_datefrom		AND    @ct_dateto
	AND		(tcfbu.sm_id IS not NULL  OR tusr.sm_id IS NOT NULL)


	ORDER BY  tct.ct_date,tct.ct_transaction


	SELECT *
		FROM #tmpMySales



	exec [spReports_getData3]@comp_id,@intBranch4Lang ,@lang_id, @page_id


	---//////////************///////////*****************////////////////***********************/////////////////////////////////*********

	/* devolución de parámetros recibidos */


	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

	SELECT	(SELECT top 1 tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 177
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1) [params1],
      		 --@ct_datefrom  [DateParams7],
      		 convert(varchar,day(@ct_datefrom))+'/'+convert(varchar,month(@ct_datefrom))+'/'+convert(varchar,year(@ct_datefrom))		[DateParams1],


	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[Params2],
			 --@ct_dateto  [DateParams8],
			  convert(varchar,day(@ct_dateto))+'/'+convert(varchar,month(@ct_dateto))+'/'+convert(varchar,year(@ct_dateto))		[DateParams2],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 28
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[Params3],


			CASE @bra_id  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE

					(SELECT tb.bra_desc
					 FROM tbBranch tb
					 WHERE tb.comp_id = @comp_id
					 AND   tb.bra_id  = @bra_id)

			END		[Params4]



	-- ----------------------------------------------------------------------
	-- Totales Generales de MarkUp Sin NC ya que falsean los porcentajes.
	-- ----------------------------------------------------------------------
	SELECT	dbo.fnGetMarkUp(Sum(Costo)	,Sum(Venta)) * @lmarkup			[Markup],
			dbo.fnGetMarkUp(Sum(CostoPP),Sum(Venta)) * @lmarkuppp		[MarkupPP]
		FROM #tmpMySales tmp
	WHERE ct_total > 0
	-- ----------------------------------------------------------------------



END
GO







--parte 805 , Se agrego en el select el "distinct" para eliminar los registros duplicados. GA


CREATE PROCEDURE [dbo].[spCommercialTransactions_getReportPackingList]
(

		@comp_id					int,
		@lang_id					int,
		@page_id					int,
		@cust_id					int,
		@sm_id						int,
		@datefrom					datetime,
		@dateto						datetime,
		@datefromvto				datetime,
		@datetovto					datetime,
		@deliverydatefrom			DATETIME,		--	 fecha de entrega desde tkt 20352
		@deliverydateto				DATETIME,		--	 fecha de entrega hasta tkt 20352
		@ct_Pending					INT,			--	 Pendientes de Facturación
		@doc_number					NVARCHAR(20),	--   Núm. de Documento
		@RemitTypes					int,			--   Tipo de Remito
		@guidCust					VARCHAR(50),
		@user_id					INT,
		@bra_id						INT,
		@intBranch4Lang				int


)

as


BEGIN


    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------



	set nocount on

	set dateformat 'ymd'


	-------------------------------------------------------------
	--------------------parametros de prueba---------------------
	-------------------------------------------------------------
	/*
	DECLARE			@comp_id		int,
					@lang_id		int,
					@page_id		int,
					@cust_id		int,
					@sm_id			int,
					@datefrom		datetime,
					@dateto			datetime,
					@datefromvto	datetime,
					@datetovto		datetime,
				    @deliverydatefrom		DATETIME,		--	 fecha de entrega desde tkt 20352
		            @deliverydateto			DATETIME,		--	 fecha de entrega hasta tkt 20352
					@ct_Pending		INT,
					@doc_number		NVARCHAR(20),
					@RemitTypes		int,
					@user_id		int,
					@bra_id			INT,
					@intBranch4Lang INT,
					@guidCust UNIQUEIDENTIFIER




	SELECT			@comp_id		= 1,
					@lang_id		= 2,
					@page_id		= 10021,
					@cust_id		= 24300,
					@sm_id			= -1,
					@datefrom		='2000-01-01',
					@dateto			='9999-12-31',
					@datefromvto	='2000-01-01',
					@datetovto		='9999-12-31',
					@ct_Pending		=1,
					@doc_number		=0,
					@RemitTypes		=-1,
					@user_id		=1,
					@bra_id			=-1,
					@intBranch4Lang = 1

	*/
	-------------------------------------------------------------
	-------------------------------------------------------------


		DECLARE @lGuidCust AS UNIQUEIDENTIFIER

		SET @lGuidCust = CONVERT(UNIQUEIDENTIFIER,@guidCust)


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuidCust     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT tc.cust_id
					FROM tbCustomer tc
						WHERE tc.comp_id = @comp_id
			END
		-- -------------------------------------------------------------


	set	@dateto					= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')
	set	@datetovto				= dbo.fnGetEnd_or_BeginOfDate(@datetovto,'True')
	SET @datefrom				= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @datefromvto			= dbo.fnGetEnd_or_BeginOfDate(@datefromvto,'False')

	SET @deliverydatefrom		= dbo.fnGetEnd_or_BeginOfDate(@deliverydatefrom,'False')
	SET @deliverydateto			= dbo.fnGetEnd_or_BeginOfDate(@deliverydateto,'True')


	DECLARE @Bra_curr_id	INT

	SELECT		@Bra_curr_id	= tb.curr_id
		FROM	tbBranch tb
		WHERE	tb.comp_id		= @comp_id AND
				tb.bra_id		= @bra_id

	DECLARE @fun_id INT
	SET @fun_id = 1

	SELECT DISTINCT
		CU.[cust_id],
		CU.[cust_name],
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, CT.ct_transaction) [Comprobante],
		CT.[ct_date],
		CT.[ct_payDate],
		ct.ct_deliveryDate [ct_deliveryDate],
		SM.sm_name,
		--CT.[ct_total],
		dbo.fnGetExchange2(@comp_id,ct.ct_total, ct.curr_id_transaction, @Bra_curr_id, ct.curr_id_transaction, @Bra_curr_id,0,'False')	[ct_total]


	FROM	tbCommercialTransactions						CT


			INNER JOIN tbCustomer							CU
			ON	CU.[comp_id]			=	CT.[comp_id]
			AND CU.[cust_id]			=	CT.[cust_id]

			INNER JOIN @tblComplexFilter_Customer		tempCustomer
			ON tempCustomer.cust_id						= CU.cust_id

			LEFT JOIN tbSalesman							SM
			ON	SM.[comp_id]			=	CT.[comp_id]
			AND SM.[sm_id]				=	CT.[sm_id]

			INNER JOIN tbsysDocuments						TD
			ON	td.sd_id					= CT.sd_id	AND
				td.sd_isPackingList			= 'True'

			INNER join tbUsers4BranchFilter					vubf
			ON  vubf.comp_id			= ct.comp_id
			AND vubf.bra_id				= ct.bra_id
			AND vubf.[user_id]			= @user_id

--			left JOIN tbItemTransactions					tit
--			ON  tit.comp_id				= ct.comp_id
--			AND tit.bra_id				= ct.bra_id
--			AND	tit.ct_transaction		= ct.ct_transaction

			--parte 639 ,GA
			LEFT JOIN vwItemTransactionsPackingPending		vwitpp		WITH (NOLOCK)
			on  vwitpp.comp_id			= ct.comp_id
			and vwitpp.bra_id			= ct.bra_id
			and vwitpp.ct_transaction	= ct.ct_transaction

			--para el filtro de remito o remito de transf.
			inner join tbDocumentsFile						tdf
			on  tdf.comp_id				= ct.comp_id
			and tdf.df_id				= ct.df_id


	WHERE	CT.[comp_id]		= @comp_id
	AND		(@cust_id			= -1	OR	 CU.[cust_id]		= @cust_id)
	AND		(@sm_id				= -1	OR	 SM.[sm_id]			= @sm_id)
	AND		(ct.ct_date					BETWEEN      @datefrom				AND @dateto)
	AND		((ct.ct_deliveryDate		BETWEEN      @deliverydatefrom		AND @deliverydateto) OR ct.ct_deliveryDate IS NULL)
	--AND		(ct.ct_deliveryDate	IS NOT NULL	AND (ct.ct_deliveryDate			BETWEEN      @deliverydatefrom AND @deliverydateto)) --	 fecha de entrega desdey hasta tkt 20352
	AND		(ct.ct_paydate				BETWEEN      @datefromvto		    AND @datetovto)
	AND
			CASE																	-- Pendientes de Facturación
			    WHEN @ct_Pending = -1 THEN	1										-- Ambos
			    WHEN @ct_Pending = 0 AND vwitpp.comp_id IS NULL		THEN	1		-- NO
			    WHEN @ct_Pending = 1 AND vwitpp.comp_id IS NOT NULL THEN	1		-- Sí
			    ELSE 0
			END	= 1

--	AND		(@ct_Pending		= -1	OR   tit.it_packingInvoicePend =  @ct_Pending)

	AND     (
			(@doc_number = 0) OR
			( ct.ct_docNumber IS not null AND ct.ct_docNumber = @doc_number)
	   		)
	AND		(@RemitTypes		= -1	OR   ISNULL(tdf.df_isInterBranchDocument,0) =  @RemitTypes)
	-- MOS 06-2024: 21578    que NO salgan los cancelados.
	AND		(
				ct.ct_isCancelled IS NULL
					OR
			    ct.ct_isCancelled = 0
			)





	ORDER BY ct.ct_date,3

	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

	----------------------------------------------------------------------------------------------------------------------------------------

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 177
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id) [params1],
			@datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))[params2],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 384
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)[params3],
			@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))	[params4],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 473
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id) [params5],

			@datefromvto [DateParams3],
			--convert(varchar,day(@datefromvto)) + '/' + convert(varchar,month(@datefromvto)) + '/' + convert(varchar,year(@datefromvto))[params6],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 474
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)[params7],

			@datetovto [DateParams4],
			--convert(varchar,day(@datetovto)) + '/' + convert(varchar,month(@datetovto)) + '/' + convert(varchar,year(@datetovto))	[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 174
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params9],
				CASE @cust_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tc.cust_name
						FROM dbo.tbCustomer tc
						WHERE tc.cust_id = @cust_id)
				END																											[params10],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 172
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params11],
				CASE @sm_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT ts.sm_name
						FROM dbo.tbSalesman ts
						WHERE ts.sm_id = @sm_id )
				END																											[params12],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 475
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params13],
				CASE @ct_Pending WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 3)
				ELSE
					(SELECT		tov.optval_desc
						FROM	dbo.tbsysOptionsValues tov
						WHERE	tov.lang_id = @lang_id
						AND		tov.optval_class = 17
						AND		tov.optval_id = @ct_Pending)
				END														[params14],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 509
  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)							[params17],
  			   			CASE @doc_number  WHEN 0 THEN
  				'---'
  			ELSE
  				@doc_number
  			END [params18],

  			(SELECT tswn.word_desc FROM tbSysWordsNew tswn WHERE tswn.lang_id = @lang_id and tswn.wordsi_id = 3632)		[params19],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 2025
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params20],
				CASE @RemitTypes WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
						FROM	dbo.tbsysOptionsValues tov
						WHERE	tov.lang_id = @lang_id
						AND		tov.optval_class = 145
						AND		tov.optval_id = @RemitTypes)
				END												[params21],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						WHERE t.ctrl_id = 3288
						--AND t.[lang_id] = @lang_id
						and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id = @fun_id) [params22],

				@deliverydatefrom [DateParams5],

				--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))[params2],
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						WHERE t.ctrl_id = 3289
						--AND t.[lang_id] = @lang_id
						and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id = @fun_id)[params23],

				@deliverydateto [DateParams6]



END
GO








CREATE procedure [dbo].[spCommercialTransactions_getReportPaymentOrder]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@ct_transaction		int
)
as


    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------



SET NOCOUNT ON

/*
DECLARE @comp_id			int,
		@lang_id			int,
		--@page_id			int,
		@ct_transaction INT


SELECT	@comp_id			=1,
		@lang_id			=2,
		--@page_id			=10006
		@ct_transaction =1508
*/



SELECT	--Para la cabecera
		convert(varchar,tct.supp_id) + ' - ' + ts.supp_name [supp_name],
		tsd.sd_desc,
		--tdf.df_desc,
		cn.cn_desc,
		tct.ct_docNumber,
		tct.ct_payDate,
		tc.curr_symbol,
		--moneda de la sucursal

		--Para el detalle
		dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction) [Comprobante],
		tct.ct_total,
		tc.curr_desc,
		tct.ct_subtotal,
		tct.ct_ABalance,
		TCT.ct_taxes,
		tct.ct_payDate,
		--moneda
		tct.ct_ACurrencyExchange,
		isnull(ts2.sm_name,'') [sm_name],
		tb.bra_desc,
		tct.ct_transaction


FROM	dbo.tbCommercialTransactions TCT

Left Join tbSupplier ts
On TS.comp_id = TCT.comp_id
And TS.supp_id = TCT.supp_id

Left Join tbDocumentsFile tdf
On tdf.comp_id = tct.comp_id
And tdf.bra_id = tct.bra_id
And tdf.df_id = tct.df_id

left join dbo.tbCashNumbers cn
On cn.comp_id = tct.comp_id
And cn.bra_id = tct.bra_id

left join dbo.tbApplication ta
on ta.comp_id = tct.comp_id
and ta.bra_id = tct.bra_id

Inner Join tbsysCurrency tc
On tc.curr_id = ts.curr_id

left join dbo.tbsysDocuments tsd
on tsd.sd_id = tct.sd_id

Left Join tbBranch tb
On tb.comp_id = tct.comp_id
And tb.bra_id = tct.bra_id
And tb.curr_id=tc.curr_id

left Join tbSalesman ts2
On ts2.comp_id = tct.comp_id
And ts2.sm_id=tct.sm_id

Where TCT.comp_id = @comp_id
 and tct.ct_transaction= @ct_transaction

GO









CREATE Procedure [dbo].[spCommercialTransactions_getReportSalesStats]
(
			@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@country_id		int,
			@state_id		int,
			@dateto			datetime,
			@datefrom		datetime,
			@bra_id			Int,
			@user_id		INT,
			@Option			INT,		-- 1-Total  2-Neto
			@intBranch4Lang int
)
as


BEGIN


    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------


	set nocount on
	set dateformat 'ymd'

	set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

-- ------------------------------------------------------------
-- Testing
-- ------------------------------------------------------------
	/*
	declare
				@comp_id		int,
				@lang_id		int,
				@page_id		int,

				@country_id		int,
				@state_id		int,
				@dateto			datetime,
				@datefrom		datetime,
				@bra_id			int,
				@user_id		Int,
				@Option			INT

	select
				@comp_id		=1,
				@lang_id		=2,
				@page_id		=10028,

				@country_id		=-1,
				@state_id		=-1,
				@datefrom		='1900-01-01',
				@dateto			='9999-12-31',
				@bra_id			=1,
				@user_id		=1,
				@Option			= 1

				drop table #tmpTotalSales
				drop table #tmpSalesProfit
				drop table #tmpSalesMarkUp
	*/
-- ------------------------------------------------------------

	DECLARE @fun_id INT
	SET @fun_id = 1


	Select	convert(nvarchar(10),Year(ct_date))[Año],
			C.country_desc,
			ST.state_desc,
			'1' [label],
			Sum(Case  when  Month (CT.ct_date) = '01' then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Enero],
			Sum(Case  when Month (CT.ct_date) = '02'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Febrero],
			Sum(Case  when Month (CT.ct_date) = '03'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Marzo],
			Sum(Case  when Month (CT.ct_date) = '04'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Abril],
			Sum(Case  when Month (CT.ct_date) = '05'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Mayo],
			Sum(Case  when Month (CT.ct_date) = '06'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Junio],
			Sum(Case  when Month (CT.ct_date) = '07'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Julio],
			Sum(Case  when Month (CT.ct_date) = '08'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Agosto],
			Sum(Case  when Month (CT.ct_date) = '09'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Septiembre],
			Sum(Case  when Month (CT.ct_date) = '10'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Octubre],
			Sum(Case  when Month (CT.ct_date) = '11'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Noviembre],
			Sum(Case  when Month (CT.ct_date) = '12'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Diciembre]

	into	#tmpTotalSales

	From dbo.tbCommercialTransactions		CT

		inner join dbo.tbsysCountry			C
		on  C.country_id	= CT.country_id

		inner join dbo.tbsysState			ST
		on  ST.country_id	= CT.country_id
		and ST.state_id		= CT.state_id

		INNER JOIN vwCommercialTransactions_forSalesStats vctfss
		ON	vctfss.comp_id			= ct.comp_id
		--AND vctfss.bra_id			= ct.bra_id
		AND vctfss.ct_transaction	= ct.ct_transaction

		inner join tbUsers4BranchFilter vubf
		ON  vubf.comp_id    = CT.comp_id
		AND vubf.bra_id     = CT.bra_id
		AND vubf.[user_id]  = @user_id


	Where	CT.comp_id		= @comp_id
	and		CT.bra_id		= @bra_id
	and		(CT.country_id	= @country_id or @country_id	=-1)
	AND		(CT.state_id	= @state_id	  OR @state_id		=-1)
	and		ct.ct_date between @datefrom and @dateto
	AND		ct.sd_id in (1,3,4)

	Group By  country_desc, state_desc, Year(ct_date)
	--Select *
	--From #tmpTotalSales
	/****************************************************************************/

	--union

	/****************************************************************************/

	Select	Year(ct_date)[Año],
			C.country_desc,
			ST.state_desc,
			'2' [label],
			isnull(Case  when Month (CT.ct_date) = '01' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [EneroProfit],
			isnull(Case  when Month (CT.ct_date) = '02' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [FebreroProfit],
			isnull(Case  when Month (CT.ct_date) = '03' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [MarzoProfit],
			isnull(Case  when Month (CT.ct_date) = '04' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [AbrilProfit],
			isnull(Case  when Month (CT.ct_date) = '05' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [MayoProfit],
			isnull(Case  when Month (CT.ct_date) = '06' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [JunioProfit],
			isnull(Case  when Month (CT.ct_date) = '07' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [JulioProfit],
			isnull(Case  when Month (CT.ct_date) = '08' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [AgostoProfit],
			isnull(Case  when Month (CT.ct_date) = '09' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [SeptiembreProfit],
			isnull(Case  when Month (CT.ct_date) = '10' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [OctubreProfit],
			isnull(Case  when Month (CT.ct_date) = '11' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [NoviembreProfit],
			isnull(Case  when Month (CT.ct_date) = '12' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [DiciembreProfit]

	into	#tmpSalesProfit

	From	dbo.tbCommercialTransactions			CT

			inner join dbo.tbItemTransactions							IT
			on  IT.comp_id			= CT.comp_id
			and IT.bra_id			= CT.bra_id
			and IT.ct_transaction	= CT.ct_transaction

			INNER JOIN vwCommercialTransactions_forSalesStats vctfss
				ON		vctfss.comp_id			= ct.comp_id
					--AND vctfss.bra_id			= ct.bra_id
					AND vctfss.ct_transaction	= ct.ct_transaction


			inner join dbo.tbsysCountry			C
			on  C.country_id	= CT.country_id

			inner join dbo.tbsysState			ST
			on  ST.country_id	= CT.country_id
			and ST.state_id		= CT.state_id

			inner join tbUsers4BranchFilter vubf
			ON  vubf.comp_id    = CT.comp_id
			AND vubf.bra_id     = CT.bra_id
			AND vubf.[user_id]  = @user_id

	Where	CT.comp_id		= @comp_id
	and		CT.bra_id		= @bra_id
	and		(CT.country_id	= @country_id or @country_id	=-1)
	AND		(CT.state_id	= @state_id	  OR @state_id		=-1)
	and		ct.ct_date between @datefrom and @dateto
	AND		ct.sd_id in (1,3,4)
	Group By country_desc, state_desc, ct_Date, Year(ct_date)
	--Select *
	--from #tmpSalesProfit
	/****************************************************************************/

	/****************************************************************************/

	Select	Year(ct_date)[Año],
			C.country_desc,
			ST.state_desc,
			'3' [label],
			isnull(Case  when Month (CT.ct_date) = '01' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [EneroMarkup],
			isnull(Case  when Month (CT.ct_date) = '02' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [FebreroMarkup],
			isnull(Case  when Month (CT.ct_date) = '03' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [MarzoMarkup],
			isnull(Case  when Month (CT.ct_date) = '04' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [AbrilMarkup],
			isnull(Case  when Month (CT.ct_date) = '05' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [MayoMarkup],
			isnull(Case  when Month (CT.ct_date) = '06' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [JunioMarkup],
			isnull(Case  when Month (CT.ct_date) = '07' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [JulioMarkup],
			isnull(Case  when Month (CT.ct_date) = '08' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [AgostoMarkup],
			isnull(Case  when Month (CT.ct_date) = '09' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [SeptiembreMarkup],
			isnull(Case  when Month (CT.ct_date) = '10' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [OctubreMarkup],
			isnull(Case  when Month (CT.ct_date) = '11' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [NoviembreMarkup],
			isnull(Case  when Month (CT.ct_date) = '12' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost * vctfss.PlusOrMinus), Sum(IT.it_qty * IT.it_price * vctfss.PlusOrMinus))
				else 0 end,0) [DiciembreMarkup]

	into	#tmpSalesMarkUp

	From	dbo.tbCommercialTransactions			CT

			inner join dbo.tbItemTransactions							IT
			on  IT.comp_id			= CT.comp_id
			and IT.bra_id			= CT.bra_id
			and IT.ct_transaction	= CT.ct_transaction


			INNER JOIN vwCommercialTransactions_forSalesStats vctfss
				ON		vctfss.comp_id			= ct.comp_id
					--AND vctfss.bra_id			= ct.bra_id
					AND vctfss.ct_transaction	= ct.ct_transaction


			inner join dbo.tbsysCountry			C
			on  C.country_id	= CT.country_id

			inner join dbo.tbsysState			ST
			on  ST.country_id	= CT.country_id
			and ST.state_id		= CT.state_id

			inner join tbUsers4BranchFilter vubf
			ON  vubf.comp_id    = CT.comp_id
			AND vubf.bra_id     = CT.bra_id
			AND vubf.[user_id]  = @user_id

	Where	CT.comp_id		= @comp_id
	and		CT.bra_id		= @bra_id
	and		(CT.country_id	= @country_id or @country_id	=-1)
	AND		(CT.state_id	= @state_id	  OR @state_id		=-1)
	and		ct.ct_date between @datefrom and @dateto
	AND		ct.sd_id  IN (1,3,4)
	Group By country_desc, state_desc, ct_Date, Year(ct_date)
	--Select *
	--from #tmpSalesMarUp
	/****************************************************************************/


	--Group By	ct.country_id,
	--			ct.state_id,
	--			year(ct.ct_date),
	--			month(ct.ct_date)


	--order by country_desc, state_desc



	select  a.Año,
			a.country_desc,
			a.state_desc,
			a.Enero,
			a.Febrero,
			a.Marzo,
			a.Abril,
			a.Mayo,
			a.Junio,
			a.Julio,
			a.Agosto,
			a.Septiembre,
			a.Octubre,
			a.Noviembre,
			a.Diciembre,

			sum(b.EneroProfit) [EneroProfit],
			sum(b.FebreroProfit) [FebreroProfit],
			sum(b.MarzoProfit) [MarzoProfit],
			sum(b.AbrilProfit) [AbrilProfit],
			sum(b.MayoProfit) [MayoProfit],
			sum(b.JunioProfit) [JunioProfit],
			sum(b.JulioProfit) [JulioProfit],
			sum(b.AgostoProfit) [AgostoProfit],
			sum(b.SeptiembreProfit) [SeptiembreProfit],
			sum(b.OctubreProfit) [OctubreProfit],
			sum(b.NoviembreProfit) [NoviembreProfit],
			sum(b.DiciembreProfit) [DiciembreProfit],

			sum(c.EneroMarkup) [EneroMarkup],
			sum(c.FebreroMarkup) [FebreroMarkup],
			sum(c.MarzoMarkup) [MarzoMarkup],
			sum(c.AbrilMarkup) [AbrilMarkup],
			sum(c.MayoMarkup) [MayoMarkup],
			sum(c.JunioMarkup) [JunioMarkup],
			sum(c.JulioMarkup) [JulioMarkup],
			sum(c.AgostoMarkup) [AgostoMarkup],
			sum(c.SeptiembreMarkup) [SeptiembreMarkup],
			sum(c.OctubreMarkup) [OctubreMarkup],
			sum(c.NoviembreMarkup) [NoviembreMarkup],
			sum(c.DiciembreMarkup) [DiciembreMarkup]

	from	#tmpTotalsales				a

			inner join #tmpSalesProfit	b
			on	b.country_desc	= a.country_desc
			and	b.state_desc	= a.state_desc
			and b.Año			= a.Año

			inner join #tmpSalesMarkUp	c
			on	c.country_desc	= a.country_desc
			and	c.state_desc	= a.state_desc
			and c.Año			= a.Año

	group by a.Año,
			a.country_desc,
			a.state_desc,
			a.Enero,
			a.Febrero,
			a.Marzo,
			a.Abril,
			a.Mayo,
			a.Junio,
			a.Julio,
			a.Agosto,
			a.Septiembre,
			a.Octubre,
			a.Noviembre,
			a.Diciembre
	order by a.Año


	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	select
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 529
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )						[params1],

			(SELECT tov.optval_desc
			 FROM dbo.tbsysOptionsValues tov
			 WHERE tov.lang_id = @lang_id
			 AND	tov.optval_class = 34
			 AND	tov.optval_id = 5)
																															[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 177
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id ) [params3],

			@datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 384
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )[params5],

			@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))	[params6],



			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 57
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )	[params7],

				CASE @country_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.country_desc
						FROM	dbo.tbsysCountry tc
						WHERE	tc.country_id = @country_id)
				END																											[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 59
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )	[params9],

				CASE @state_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.state_desc
						FROM	dbo.tbsysState ts
						WHERE	ts.state_id = @state_id)
				END																											[params10],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
							 WHERE t.ctrl_id = 991
							 --AND t.[lang_id] = @lang_id
							 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )						[params11],

						(SELECT tov.optval_desc
						 FROM dbo.tbsysOptionsValues tov
						 WHERE tov.lang_id = @lang_id
						 AND	tov.optval_class = 135
						 AND	tov.optval_id = @Option)
																															[params12]




END
GO






CREATE Procedure [dbo].[spCommercialTransactions_getReportSalesStats2]
(
			@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@country_id		int,
			@state_id		int,
			@dateto			datetime,
			@datefrom		datetime,
			@bra_id			int,
			@intBranch4Lang int
)
as

    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------



set nocount on
set dateformat 'ymd'

	set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

/*
declare
			@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@country_id		int,
			@state_id		int,
			@dateto			datetime,
			@datefrom		datetime,
			@bra_id			int

select
			@comp_id		=1,
			@lang_id		=2,
			@page_id		=10028,

			@country_id		=-1,
			@state_id		=-1,
			@datefrom		='2000-01-01',
			@dateto			='2010-12-31',
			@bra_id			=1
*/
/****************************************************************************/

Select	Year(ct_date)[Año],
		C.country_desc,
		ST.state_desc,
		Month(CT.ct_date) [Mes],
		ov.[optval_desc],
		CT.ct_total

From dbo.tbCommercialTransactions		CT
WITH (NOLOCK)

	inner join dbo.tbsysCountry			C
	on  C.country_id	= CT.country_id

	inner join dbo.tbsysState			ST
	on  ST.country_id	= CT.country_id
	and ST.state_id		= CT.state_id

	inner join dbo.[tbsysOptionsValues] ov
	on ov.[lang_id] = @lang_id
	and ov.[optval_class] = 37
	and ov.[optval_id] = month(ct.[ct_date])

Where	CT.comp_id		= @comp_id
and		CT.bra_id		= @bra_id
and		(CT.country_id	= @country_id or @country_id	=-1)
AND		(CT.state_id	= @state_id	  OR @state_id		=-1)
and		ct.ct_date between @datefrom and @dateto

order by 1,2,3,4

/****************************************************************************/
exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/
select
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 529
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)						[params1],

		(SELECT tov.optval_desc
		 FROM dbo.tbsysOptionsValues tov
		 WHERE tov.lang_id = @lang_id
		 AND	tov.optval_class = 34
		 AND	tov.optval_id = 5)
																														[params2],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 177
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1) [params3],

		convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))[params4],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 384
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)[params5],

		convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))	[params6],



		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 57
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)	[params7],

			CASE @country_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tc.country_desc
					FROM	dbo.tbsysCountry tc
					WHERE	tc.country_id = @country_id)
			END																											[params8],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 59
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)	[params9],

			CASE @state_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		ts.state_desc
					FROM	dbo.tbsysState ts
					WHERE	ts.state_id = @state_id)
			END																											[params10]


GO









CREATE Procedure [dbo].[spCommercialTransactions_getReportSalesStatsCK]
(
			@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@ck_id			int,
			@dateto			datetime,
			@datefrom		datetime,
			@bra_id			Int,
			@user_id		Int,
			@Option			INT,		-- 1-Total  2-Neto
			@intBranch4Lang int
)
as

    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------


set nocount on
set dateformat 'ymd'

	set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


------------------------------------------------------------------------------------
/*

declare
			@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@ck_id			int,
			@dateto			datetime,
			@datefrom		datetime,
			@bra_id			INT,
			@user_id        INT,
			@Option			INT


select
			@comp_id		=1,
			@lang_id		=2,
			@page_id		=10031,

			@ck_id			=-1,
			@datefrom		='2000-01-01',
			@dateto			='9999-31-12',
			@bra_id			=1,
			@user_id        =1,
			@Option			=1


			drop table #tmpTotalSales2
			drop table #tmpSalesProfit2
			drop table #tmpSalesMarkUp2

*/

/****************************************************************************/



	DECLARE @fun_id INT
	SET @fun_id = 1



Select	convert(nvarchar(10),Year(ct_date))[Año],
		CK.ck_name,
		'1' [label],

			Sum(Case  when  Month (CT.ct_date) = '01' then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Enero],
			Sum(Case  when Month (CT.ct_date) = '02'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Febrero],
			Sum(Case  when Month (CT.ct_date) = '03'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Marzo],
			Sum(Case  when Month (CT.ct_date) = '04'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Abril],
			Sum(Case  when Month (CT.ct_date) = '05'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Mayo],
			Sum(Case  when Month (CT.ct_date) = '06'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Junio],
			Sum(Case  when Month (CT.ct_date) = '07'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Julio],
			Sum(Case  when Month (CT.ct_date) = '08'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Agosto],
			Sum(Case  when Month (CT.ct_date) = '09'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Septiembre],
			Sum(Case  when Month (CT.ct_date) = '10'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Octubre],
			Sum(Case  when Month (CT.ct_date) = '11'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Noviembre],
			Sum(Case  when Month (CT.ct_date) = '12'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
				else 0 end) [Diciembre]


into	#tmpTotalSales2

From dbo.tbCommercialTransactions		CT

	inner join dbo.tbsysCountry			C
	on  C.country_id	= CT.country_id

	inner join dbo.tbsysState			ST
	on  ST.country_id	= CT.country_id
	and ST.state_id		= CT.state_id

	INNER JOIN vwCommercialTransactions_forSalesStats vctfss
	ON	vctfss.comp_id			= ct.comp_id
	--AND vctfss.bra_id			= ct.bra_id
	AND vctfss.ct_transaction	= ct.ct_transaction

	inner join dbo.tbCustomer			CM
	on CM.cust_id		= CT.cust_id

	inner join dbo.tbCustomerKind		CK
	on CK.ck_id			= CM.ck_id

	inner join tbUsers4BranchFilter vubf
    ON  vubf.comp_id    = CT.comp_id
    AND vubf.bra_id     = CT.bra_id
    AND vubf.[user_id]  = @user_id

Where	CT.comp_id		= @comp_id
and		CT.bra_id		= @bra_id
and		(CM.ck_id		= @ck_id or @ck_id	=-1)
and		ct.ct_date between @datefrom and @dateto

Group By  ck_name, Year(ct_date)
--Select *
--From #tmpTotalSales
/****************************************************************************/

--union

/****************************************************************************/

Select	Year(ct_date)[Año],
		CK.ck_name,
		'2' [label],
		isnull(Case  when Month (CT.ct_date) = '01' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [EneroProfit],
		isnull(Case  when Month (CT.ct_date) = '02' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [FebreroProfit],
		isnull(Case  when Month (CT.ct_date) = '03' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [MarzoProfit],
		isnull(Case  when Month (CT.ct_date) = '04' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [AbrilProfit],
		isnull(Case  when Month (CT.ct_date) = '05' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [MayoProfit],
		isnull(Case  when Month (CT.ct_date) = '06' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [JunioProfit],
		isnull(Case  when Month (CT.ct_date) = '07' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [JulioProfit],
		isnull(Case  when Month (CT.ct_date) = '08' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [AgostoProfit],
		isnull(Case  when Month (CT.ct_date) = '09' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [SeptiembreProfit],
		isnull(Case  when Month (CT.ct_date) = '10' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [OctubreProfit],
		isnull(Case  when Month (CT.ct_date) = '11' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [NoviembreProfit],
		isnull(Case  when Month (CT.ct_date) = '12' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [DiciembreProfit]

into	#tmpSalesProfit2

From	dbo.tbCommercialTransactions			CT

		inner join dbo.tbItemTransactions							IT
		on  IT.comp_id			= CT.comp_id
		and IT.bra_id			= CT.bra_id
		and IT.ct_transaction	= CT.ct_transaction

		inner join dbo.tbsysCountry			C
		on  C.country_id	= CT.country_id

		inner join dbo.tbsysState			ST
		on  ST.country_id	= CT.country_id
		and ST.state_id		= CT.state_id

		inner join dbo.tbCustomer			CM
		on CM.cust_id		= CT.cust_id

		inner join dbo.tbCustomerKind		CK
		on CK.ck_id			= CM.ck_id

		inner join tbUsers4BranchFilter vubf
		ON  vubf.comp_id    = CT.comp_id
		AND vubf.bra_id     = CT.bra_id
		AND vubf.[user_id]  = @user_id

Where	CT.comp_id		= @comp_id
and		CT.bra_id		= @bra_id
and		(CM.ck_id		= @ck_id or @ck_id	=-1)
and		ct.ct_date between @datefrom and @dateto

Group By ck_name, ct_Date, Year(ct_date)
--Select *
--from #tmpSalesProfit
/****************************************************************************/

/****************************************************************************/

Select	Year(ct_date)[Año],
		CK.ck_name,
		'3' [label],
		isnull(Case  when Month (CT.ct_date) = '01' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [EneroMarkup],
		isnull(Case  when Month (CT.ct_date) = '02' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [FebreroMarkup],
		isnull(Case  when Month (CT.ct_date) = '03' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [MarzoMarkup],
		isnull(Case  when Month (CT.ct_date) = '04' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [AbrilMarkup],
		isnull(Case  when Month (CT.ct_date) = '05' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [MayoMarkup],
		isnull(Case  when Month (CT.ct_date) = '06' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [JunioMarkup],
		isnull(Case  when Month (CT.ct_date) = '07' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [JulioMarkup],
		isnull(Case  when Month (CT.ct_date) = '08' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [AgostoMarkup],
		isnull(Case  when Month (CT.ct_date) = '09' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [SeptiembreMarkup],
		isnull(Case  when Month (CT.ct_date) = '10' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [OctubreMarkup],
		isnull(Case  when Month (CT.ct_date) = '11' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [NoviembreMarkup],
		isnull(Case  when Month (CT.ct_date) = '12' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [DiciembreMarkup]

into	#tmpSalesMarkUp2

From	dbo.tbCommercialTransactions			CT

		inner join dbo.tbItemTransactions		IT
		on  IT.comp_id			= CT.comp_id
		and IT.bra_id			= CT.bra_id
		and IT.ct_transaction	= CT.ct_transaction

		inner join dbo.tbsysCountry				C
		on  C.country_id	= CT.country_id

		inner join dbo.tbsysState				ST
		on  ST.country_id	= CT.country_id
		and ST.state_id		= CT.state_id

		inner join dbo.tbCustomer			CM
		on CM.cust_id		= CT.cust_id

		inner join dbo.tbCustomerKind		CK
		on CK.ck_id			= CM.ck_id

		inner join tbUsers4BranchFilter vubf
		ON  vubf.comp_id    = CT.comp_id
		AND vubf.bra_id     = CT.bra_id
		AND vubf.[user_id]  = @user_id

Where	CT.comp_id		= @comp_id
and		CT.bra_id		= @bra_id
and		(CM.ck_id		= @ck_id or @ck_id	=-1)
and		ct.ct_date between @datefrom and @dateto

Group By ck_name, ct_Date, Year(ct_date)
--Select *
--from #tmpSalesMarUp
/****************************************************************************/


--Group By	ct.country_id,
--			ct.state_id,
--			year(ct.ct_date),
--			month(ct.ct_date)


--order by country_desc, state_desc



select  a.Año,
        a.ck_name,
		a.Enero,
		a.Febrero,
		a.Marzo,
		a.Abril,
		a.Mayo,
		a.Junio,
        a.Julio,
        a.Agosto,
        a.Septiembre,
        a.Octubre,
        a.Noviembre,
        a.Diciembre,

		sum(b.EneroProfit) [EneroProfit],
		sum(b.FebreroProfit) [FebreroProfit],
		sum(b.MarzoProfit) [MarzoProfit],
		sum(b.AbrilProfit) [AbrilProfit],
		sum(b.MayoProfit) [MayoProfit],
		sum(b.JunioProfit) [JunioProfit],
		sum(b.JulioProfit) [JulioProfit],
		sum(b.AgostoProfit) [AgostoProfit],
		sum(b.SeptiembreProfit) [SeptiembreProfit],
		sum(b.OctubreProfit) [OctubreProfit],
		sum(b.NoviembreProfit) [NoviembreProfit],
		sum(b.DiciembreProfit) [DiciembreProfit],

		sum(c.EneroMarkup) [EneroMarkup],
		sum(c.FebreroMarkup) [FebreroMarkup],
		sum(c.MarzoMarkup) [MarzoMarkup],
		sum(c.AbrilMarkup) [AbrilMarkup],
		sum(c.MayoMarkup) [MayoMarkup],
		sum(c.JunioMarkup) [JunioMarkup],
		sum(c.JulioMarkup) [JulioMarkup],
		sum(c.AgostoMarkup) [AgostoMarkup],
		sum(c.SeptiembreMarkup) [SeptiembreMarkup],
		sum(c.OctubreMarkup) [OctubreMarkup],
		sum(c.NoviembreMarkup) [NoviembreMarkup],
		sum(c.DiciembreMarkup) [DiciembreMarkup]

from	#tmpTotalsales2				a

		inner join #tmpSalesProfit2	b
		on	b.ck_name		= a.ck_name
		and b.Año			= a.Año

		inner join #tmpSalesMarkUp2	c
		on	c.ck_name		= a.ck_name
		and c.Año			= a.Año

group by a.Año,
        a.ck_name,
		a.Enero,
		a.Febrero,
		a.Marzo,
		a.Abril,
		a.Mayo,
		a.Junio,
        a.Julio,
        a.Agosto,
        a.Septiembre,
        a.Octubre,
        a.Noviembre,
        a.Diciembre
order by a.Año


exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id

		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/
select
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 529
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)[params1],

		(SELECT tov.optval_desc
		 FROM dbo.tbsysOptionsValues tov
		 WHERE tov.lang_id = @lang_id
		 AND	tov.optval_class = 34
		 AND	tov.optval_id = 7)
																														[params2],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 177
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1) [params3],

		@datefrom [DateParams1],
		--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))[params4],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 384
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)[params5],

		@dateto [DateParams2],
		--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))	[params6],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 172
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)[params7],

		CASE @ck_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tck.ck_name
				 FROM dbo.tbCustomerKind tck
				 WHERE tck.ck_id = @ck_id)
			END																											[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 991
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )						[params9],

				(SELECT tov.optval_desc
				 FROM dbo.tbsysOptionsValues tov
				 WHERE tov.lang_id = @lang_id
				 AND	tov.optval_class = 135
				 AND	tov.optval_id = @Option)
																											[params10]
GO








CREATE Procedure [dbo].[spCommercialTransactions_getReportSalesStatsSM]
(

			@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@sm_id			int,
			@dateto			datetime,
			@datefrom		datetime,
			@bra_id			Int,
			@user_id		Int,
			@Option			INT,		-- 1-Total  2-Neto
			@intBranch4Lang int

)
as


    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------



set nocount on
set dateformat 'ymd'

	set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

-------------------------------------------------------------------
/*
declare
			@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@sm_id			int,
			@dateto			datetime,
			@datefrom		datetime,
			@bra_id			INT,
			@user_id		Int,
			@option			int

select
			@comp_id		=1,
			@lang_id		=2,
			@page_id		=10030,

			@sm_id			=-1,
			@datefrom		='2000-01-01',
			@dateto			='9999-12-31',
			@bra_id			=1,
			@user_id		=1,
			@option			= 2

			drop table #tmpTotalSales1
			drop table #tmpSalesProfit1
			drop table #tmpSalesMarkUp1

*/
/****************************************************************************/

DECLARE @fun_id INT
SET @fun_id = 1


Select	convert(nvarchar(10),Year(ct_date))[Año],
		SM.sm_name,
		'1' [label],
		Sum(Case  when  Month (CT.ct_date) = '01' then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Enero],
		Sum(Case  when Month (CT.ct_date) = '02'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Febrero],
		Sum(Case  when Month (CT.ct_date) = '03'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Marzo],
		Sum(Case  when Month (CT.ct_date) = '04'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Abril],
		Sum(Case  when Month (CT.ct_date) = '05'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Mayo],
		Sum(Case  when Month (CT.ct_date) = '06'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Junio],
		Sum(Case  when Month (CT.ct_date) = '07'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Julio],
		Sum(Case  when Month (CT.ct_date) = '08'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Agosto],
		Sum(Case  when Month (CT.ct_date) = '09'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Septiembre],
		Sum(Case  when Month (CT.ct_date) = '10'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Octubre],
		Sum(Case  when Month (CT.ct_date) = '11'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Noviembre],
		Sum(Case  when Month (CT.ct_date) = '12'  then case when @Option =1 then CT.ct_total ELSE ct.ct_subtotal END * vctfss.PlusOrMinus
			else 0 end) [Diciembre]

into	#tmpTotalSales1

From dbo.tbCommercialTransactions		CT

	inner join dbo.tbsysCountry			C
	on  C.country_id	= CT.country_id

	inner join dbo.tbsysState			ST
	on  ST.country_id	= CT.country_id
	and ST.state_id		= CT.state_id

	INNER JOIN vwCommercialTransactions_forSalesStats vctfss
	ON	vctfss.comp_id			= ct.comp_id
	--AND vctfss.bra_id			= ct.bra_id
	AND vctfss.ct_transaction	= ct.ct_transaction

	inner join dbo.tbSalesman			SM
	on SM.sm_id			= CT.sm_id

	inner join tbUsers4BranchFilter vubf
    ON  vubf.comp_id    = CT.comp_id
    AND vubf.bra_id     = CT.bra_id
    AND vubf.[user_id]  = @user_id

Where	CT.comp_id		= @comp_id
and		CT.bra_id		= @bra_id
and		(CT.sm_id		= @sm_id or @sm_id	=-1)
and		ct.ct_date between @datefrom and @dateto

Group By  sm_name, Year(ct_date)
--Select *
--From #tmpTotalSales
/****************************************************************************/

--union

/****************************************************************************/

Select	Year(ct_date)[Año],
		SM.sm_name,
		'2' [label],
		isnull(Case  when Month (CT.ct_date) = '01' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [EneroProfit],
		isnull(Case  when Month (CT.ct_date) = '02' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [FebreroProfit],
		isnull(Case  when Month (CT.ct_date) = '03' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [MarzoProfit],
		isnull(Case  when Month (CT.ct_date) = '04' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [AbrilProfit],
		isnull(Case  when Month (CT.ct_date) = '05' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [MayoProfit],
		isnull(Case  when Month (CT.ct_date) = '06' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [JunioProfit],
		isnull(Case  when Month (CT.ct_date) = '07' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [JulioProfit],
		isnull(Case  when Month (CT.ct_date) = '08' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [AgostoProfit],
		isnull(Case  when Month (CT.ct_date) = '09' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [SeptiembreProfit],
		isnull(Case  when Month (CT.ct_date) = '10' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [OctubreProfit],
		isnull(Case  when Month (CT.ct_date) = '11' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [NoviembreProfit],
		isnull(Case  when Month (CT.ct_date) = '12' then dbo.fngetProfit(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [DiciembreProfit]

into	#tmpSalesProfit1

From	dbo.tbCommercialTransactions			CT

		inner join dbo.tbItemTransactions							IT
		on  IT.comp_id			= CT.comp_id
		and IT.bra_id			= CT.bra_id
		and IT.ct_transaction	= CT.ct_transaction

		inner join dbo.tbsysCountry			C
		on  C.country_id	= CT.country_id

		inner join dbo.tbsysState			ST
		on  ST.country_id	= CT.country_id
		and ST.state_id		= CT.state_id

		inner join dbo.tbSalesman			SM
		on SM.sm_id			=CT.sm_id

		inner join tbUsers4BranchFilter vubf
		ON  vubf.comp_id    = CT.comp_id
		AND vubf.bra_id     = CT.bra_id
		AND vubf.[user_id]  = @user_id

Where	CT.comp_id		= @comp_id
and		CT.bra_id		= @bra_id
and		(CT.sm_id		= @sm_id or @sm_id	=-1)
and		ct.ct_date between @datefrom and @dateto

Group By sm_name, ct_Date, Year(ct_date)
--Select *
--from #tmpSalesProfit
/****************************************************************************/

/****************************************************************************/

Select	Year(ct_date)[Año],
		SM.sm_name,
		'3' [label],
		isnull(Case  when Month (CT.ct_date) = '01' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [EneroMarkup],
		isnull(Case  when Month (CT.ct_date) = '02' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [FebreroMarkup],
		isnull(Case  when Month (CT.ct_date) = '03' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [MarzoMarkup],
		isnull(Case  when Month (CT.ct_date) = '04' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [AbrilMarkup],
		isnull(Case  when Month (CT.ct_date) = '05' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [MayoMarkup],
		isnull(Case  when Month (CT.ct_date) = '06' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [JunioMarkup],
		isnull(Case  when Month (CT.ct_date) = '07' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [JulioMarkup],
		isnull(Case  when Month (CT.ct_date) = '08' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [AgostoMarkup],
		isnull(Case  when Month (CT.ct_date) = '09' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [SeptiembreMarkup],
		isnull(Case  when Month (CT.ct_date) = '10' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [OctubreMarkup],
		isnull(Case  when Month (CT.ct_date) = '11' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [NoviembreMarkup],
		isnull(Case  when Month (CT.ct_date) = '12' then dbo.fngetMarkUp(Sum(IT.it_qty * it_priceOfCost), Sum(IT.it_qty * IT.it_price))
			else 0 end,0) [DiciembreMarkup]

into	#tmpSalesMarkUp1

From	dbo.tbCommercialTransactions			CT

		inner join dbo.tbItemTransactions		IT
		on  IT.comp_id			= CT.comp_id
		and IT.bra_id			= CT.bra_id
		and IT.ct_transaction	= CT.ct_transaction

		inner join dbo.tbsysCountry				C
		on  C.country_id	= CT.country_id

		inner join dbo.tbsysState				ST
		on  ST.country_id	= CT.country_id
		and ST.state_id		= CT.state_id

		inner join dbo.tbSalesman				SM
		on SM.sm_id			=CT.sm_id

		inner join tbUsers4BranchFilter vubf
		ON  vubf.comp_id    = CT.comp_id
		AND vubf.bra_id     = CT.bra_id
		AND vubf.[user_id]  = @user_id

Where	CT.comp_id		= @comp_id
and		CT.bra_id		= @bra_id
and		(CT.sm_id		= @sm_id or @sm_id	=-1)
and		ct.ct_date between @datefrom and @dateto

Group By sm_name, ct_Date, Year(ct_date)
--Select *
--from #tmpSalesMarUp
/****************************************************************************/


--Group By	ct.country_id,
--			ct.state_id,
--			year(ct.ct_date),
--			month(ct.ct_date)


--order by country_desc, state_desc



select  a.Año,
        a.sm_name,
		a.Enero,
		a.Febrero,
		a.Marzo,
		a.Abril,
		a.Mayo,
		a.Junio,
        a.Julio,
        a.Agosto,
        a.Septiembre,
        a.Octubre,
        a.Noviembre,
        a.Diciembre,

		sum(b.EneroProfit) [EneroProfit],
		sum(b.FebreroProfit) [FebreroProfit],
		sum(b.MarzoProfit) [MarzoProfit],
		sum(b.AbrilProfit) [AbrilProfit],
		sum(b.MayoProfit) [MayoProfit],
		sum(b.JunioProfit) [JunioProfit],
		sum(b.JulioProfit) [JulioProfit],
		sum(b.AgostoProfit) [AgostoProfit],
		sum(b.SeptiembreProfit) [SeptiembreProfit],
		sum(b.OctubreProfit) [OctubreProfit],
		sum(b.NoviembreProfit) [NoviembreProfit],
		sum(b.DiciembreProfit) [DiciembreProfit],

		sum(c.EneroMarkup) [EneroMarkup],
		sum(c.FebreroMarkup) [FebreroMarkup],
		sum(c.MarzoMarkup) [MarzoMarkup],
		sum(c.AbrilMarkup) [AbrilMarkup],
		sum(c.MayoMarkup) [MayoMarkup],
		sum(c.JunioMarkup) [JunioMarkup],
		sum(c.JulioMarkup) [JulioMarkup],
		sum(c.AgostoMarkup) [AgostoMarkup],
		sum(c.SeptiembreMarkup) [SeptiembreMarkup],
		sum(c.OctubreMarkup) [OctubreMarkup],
		sum(c.NoviembreMarkup) [NoviembreMarkup],
		sum(c.DiciembreMarkup) [DiciembreMarkup]

from	#tmpTotalsales1				a

		inner join #tmpSalesProfit1	b
		on	b.sm_name		= a.sm_name
		and b.Año			= a.Año

		inner join #tmpSalesMarkUp1	c
		on	c.sm_name		= a.sm_name
		and c.Año			= a.Año

group by a.Año,
        a.sm_name,
		a.Enero,
		a.Febrero,
		a.Marzo,
		a.Abril,
		a.Mayo,
		a.Junio,
        a.Julio,
        a.Agosto,
        a.Septiembre,
        a.Octubre,
        a.Noviembre,
        a.Diciembre
order by a.Año


exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/
select
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 529
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)						[params1],

		(SELECT tov.optval_desc
		 FROM dbo.tbsysOptionsValues tov
		 WHERE tov.lang_id = @lang_id
		 AND	tov.optval_class = 34
		 AND	tov.optval_id = 6)
																							[params2],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 177
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1) [params3],
	@datefrom [DateParams1],
		--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))[params4],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 384
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)[params5],
		@dateto [DateParams2],
		--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))	[params6],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 372
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)						[params7],

		CASE @sm_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT ts.sm_name
				 FROM dbo.tbSalesman ts
				 WHERE ts.sm_id = @sm_id )
			END																											[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 991
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )						[params9],

				(SELECT tov.optval_desc
				 FROM dbo.tbsysOptionsValues tov
				 WHERE tov.lang_id = @lang_id
				 AND	tov.optval_class = 135
				 AND	tov.optval_id = @Option)
																											[params10]
GO




CREATE PROCEDURE [dbo].[spCommercialTransactions_getReportTaxEngineOverPurchase]


(
	@comp_id		int,
	@lang_id		int,
	@page_id		int,
	@guid			uniqueidentifier,
	@ten_id			int,
	@datefrom		datetime,
	@dateto			datetime,
	@brag_id		int,
	@bra_id			Int,
	@tax_id			int,
	@country_id		INT,
	@state_id		INT,
	@user_id		INT,
	@strCUIT		VARCHAR(30),
	@intBranch4Lang	int,
	@page_index		INT,
	@guid_supp  	VARCHAR(50)
)
AS




BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------





	-- ------------------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------------------
	/*

	    DECLARE 	@comp_id		int,
					@lang_id		int,
					@page_id		int,
					@guid			uniqueidentifier,
					@ten_id			int,
					@datefrom		datetime,
					@dateto			datetime,
					@brag_id		int,
					@bra_id			Int,
					@tax_id			int,
					@country_id		INT,
					@state_id		INT,
					@user_id		INT,
					@strCUIT		VARCHAR(30),
					@intBranch4Lang	int,
					@page_index		INT,
					@guid_supp  	VARCHAR(50)	= NEWID()

	SELECT 		@guid			='fd82d14d-7c3b-4bb8-a04c-511d3f4fe4b7',--'45b7f584-70ae-4d17-981d-392a3b8c75e9',
				@comp_id		= 1,
				@lang_id		= 2,
				@page_id		= 10033,
				@ten_id			= 7,
				@datefrom		='2020-08-01',
				@dateto			='2020-12-31',
				@brag_id		=8,
				@bra_id			=-1,
				@user_id		= 1,
				@tax_id			= -1,
				@intBranch4Lang	= 2,
				@page_index		= -1,
				@country_id		= -1,
				@state_id		= -1,
				@strCUIT		= ''

	DROP TABLE IF EXISTS  #tmpFinalData
	DROP TABLE IF EXISTS  #tmpCommercialTransactions
	DROP TABLE IF EXISTS  #tmpColumns
	DROP TABLE IF EXISTS  #tmp1
	DROP TABLE IF EXISTS  #tmp2
	DROP TABLE IF EXISTS  #tmpColumnsNames

	*/
	-- ---------------------------------------------------------------------------------------------

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @bitAllSuppliers AS BIT = 'False'
	DECLARE @lGuid_Supp AS UNIQUEIDENTIFIER
	SET @lGuid_Supp = CONVERT(UNIQUEIDENTIFIER,@guid_supp)
	DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Supplier
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf		WITH (NOLOCK)
			WHERE tcf.sl_guid = @lGuid_Supp     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			SET @bitAllSuppliers = 'True'
			INSERT INTO @tblComplexFilter_Supplier
				SELECT ts.supp_id
				FROM tbSupplier ts	WITH (NOLOCK)
					WHERE ts.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

	SET @datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateTo   = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')



	DECLARE @fun_id INT
	SET @fun_id = 1

	CREATE TABLE #tmpColumns (id INT IDENTITY, tent_column INT)

	INSERT INTO #tmpColumns		(tent_column)
	SELECT						tent_column
		FROM	tbTaxEngineName_Taxes ttent			WITH (NOLOCK)
		WHERE	ttent.comp_id	= @comp_id
			AND	ttent.ten_id	= @ten_id
			AND ttent.tent_id4Summary IS NULL		--== Aca Modifique
		ORDER BY ttent.tent_column


	--SELECT * FROM #tmpColumns
	CREATE TABLE #tmpColumnsNames ( id INT IDENTITY, [colname] VARCHAR(100) )


	/*Creamos la tabla*/
	CREATE TABLE #tmpFinalData
					(
					ct_transaction		INT,
					tmp_id				INT IDENTITY,
					ct_date				DATETIME,
					supp_name			VARCHAR(100),
					supp_number			VARCHAR(20),
					[document]			VARCHAR(100),

					ct_CAI				NVARCHAR(50), --STL 12/11/2010
					ct_CAIDate			DATETIME,

					gravado				DECIMAL(19,2) DEFAULT 0 NULL,
					nogravado			DECIMAL(19,2) DEFAULT 0	NULL,
					exento				DECIMAL(19,2) DEFAULT 0	NULL
					)

	CREATE INDEX #tmpFinalData_I  ON #tmpFinalData(ct_transaction)
	CREATE INDEX #tmpFinalData_II ON #tmpFinalData(tmp_id)

	DECLARE	@column_name		VARCHAR(100),
			@tent_column		INT,
			@auxTotal		AS	DECIMAL(19,6)
			--@tent_isHidden		BIT



	DECLARE @message VARCHAR(100)
	SELECT @message = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 150 AND tut.lang_id = @lang_id



--== Aca MOdifique
	/*Cursor que Modifica la tabla y le agrega las columnas de la TaxEngineName_Taxes*/
	DECLARE cursor_columns CURSOR LOCAL  FAST_FORWARD FOR
	SELECT	distinct
			ttent.tent_columnName,
			tmpc.id
		FROM	tbTaxEngineName_Taxes			ttent			WITH (NOLOCK)
		INNER JOIN #tmpColumns						tmpc
			ON	ttent.tent_column			= tmpc.tent_column
		where	ttent.ten_id				= @ten_id
			AND ttent.comp_id				= @comp_id
		ORDER BY tmpc.id


	OPEN cursor_columns


	FETCH NEXT FROM cursor_columns
	INTO	@column_name,
			@tent_column


	WHILE @@FETCH_STATUS = 0
	BEGIN

		EXEC ('alter table #tmpFinalData add [Columna' + @tent_column + '] decimal(19,6) default 0')

		INSERT INTO #tmpColumnsNames (colname) VALUES ( '[Columna' + convert(varchar,@tent_column) + ']')

		FETCH NEXT FROM cursor_columns
		INTO	@column_name,
				@tent_column

	END


	EXEC ('alter table #tmpFinalData add total decimal(19,6) default 0')




	CLOSE cursor_columns
	DEALLOCATE cursor_columns

	DECLARE @ten_sdIdGroup INT
	SELECT	@ten_sdIdGroup	= isnull(tten.ten_sdIdGroup,1)
	FROM	tbTaxEngineName tten
	WHERE	tten.comp_id	= @comp_id
	AND		tten.ten_id		= @ten_id


	DECLARE @tmpCommercialTransactions TABLE(ct_transaction INT PRIMARY KEY)





	/*Select del Stored Procedure Original que trae los datos de la COMMERCIAL TRANSACTIONS y los inserta en la tabla #tmpFinalData*/
	SELECT	CT.ct_transaction,
			CASE
			    WHEN	tb.bra_TaxEngineOverPurchase_ShowTaxDate = 'True'  THEN	CT.ct_taxDate
			    ELSE															ct.ct_date
			END																							[ct_date],
			ct.ct_CAI,
			ct.ct_CAIDate,
			CASE
				WHEN tsb.comp_id IS NOT NULL THEN	tsb.supp_name
				ELSE								SUBSTRING(IsNull(TS.supp_name,IsNull(tba.ba_desc,'*CB')),1,30)
			END																							[Name],		-- MOS 06-2016 ISNULL(TSB.supp_name,'')
			CASE
				WHEN tsb.comp_id IS NOT NULL THEN	tsb.supp_taxNumber
				ELSE								IsNull(TS.supp_taxNumber,ISNULL(tba.ba_taxNumber,'*CB'))
			END																							[Number],
			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,CT.ct_transaction)				[Comprobante],
			ct.ct_kindOf, ct.ct_pointOfSale, ct.ct_docNumber,
			CASE
				WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN CT.ct_subtotal
				ELSE CT.ct_subtotal * -1
			END																							[ct_subtotal],
			CASE
				WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN 'False'
				ELSE 'True'
			END																							[sd_isCredit],
			ct.sd_id,
			tfc.fc_desc

			INTO #tmpCommercialTransactions

	FROM 	dbo.tbCommercialTransactions							CT						WITH (NOLOCK)

			INNER JOIN dbo.vwCommercialTransactions_forPurchase_TaxEngine		vwctp		WITH (NOLOCK)
			ON 	vwctp.ct_Transaction	= CT.ct_transaction
			AND vwctp.bra_id			= CT.bra_id
			AND vwctp.comp_id			= CT.comp_id
			--AND vwctp.sd_isTaxable		= 'True'

			LEFT JOIN tbTaxMovements								TM						WITH (NOLOCK)
			ON 	TM.comp_id				= CT.comp_id
			AND TM.bra_id				= CT.bra_id
			AND TM.ct_transaction		= CT.ct_transaction

			INNER JOIN tbBranch tb															WITH (NOLOCK)
				ON	tb.comp_id	= ct.comp_id AND
					tb.bra_id	= ct.bra_id

			INNER JOIN tbUsers4BranchFilter							vubf					WITH (NOLOCK)
			ON  vubf.comp_id			= CT.comp_id
			AND vubf.bra_id				= CT.bra_id
			AND vubf.[user_id]			= @user_id


			LEFT JOIN @tblComplexFilter_Supplier ttr
				ON ttr.supp_id = ct.supp_id

			Left JOIN vwSupplier									TS						WITH (NOLOCK)
			ON	TS.comp_id				= CT.comp_id		AND
				ts.bra_id				= CT.bra_id			AND
			    TS.ct_transaction		= CT.ct_transaction	AND
			    TS.supp_id				= CT.supp_id

			LEFT JOIN tbsysFiscalClass tfc
				ON tfc.fc_id = ts.fc_id

			LEFT JOIN tbBankingAccounts tba													WITH (NOLOCK)
				ON		tba.comp_id		= ct.comp_id
					AND tba.ba_id		= ct.ba_id


			left JOIN tbSupplier									TSB								WITH (NOLOCK)
			ON	TSB.comp_id				= CT.comp_id
			AND TSB.supp_id				= CT.supp_id4CreditCardLiquidation


	WHERE	CT.comp_id	= @comp_id
	AND 	CT.ct_taxDate between @datefrom and @dateto
	AND 	((@brag_id	= -1
				AND (@bra_id = -1 OR CT.bra_id = @bra_id)) OR
			(@brag_id <> -1
				and CT.bra_id IN (SELECT bgd.bra_id
									  FROM tbBranchGroupDetail bgd	WITH (NOLOCK)
									  WHERE bgd.brag_id = @brag_id)))

	AND		(
			 (@ten_sdIdGroup = 1 and (vwctp.sd_isTaxable	= 'True'  OR vwctp.sd_isReceipt = 'True' AND ct.ct_discount <> 0)) OR
			 (@ten_sdIdGroup = 2 and vwctp.sd_isReceipt		= 'True') OR
			 (@ten_sdIdGroup = 3 and vwctp.sd_isReceipt		= 'True'))
	AND (
			 @tax_id = -1 OR
			 EXISTS(	SELECT TOP 1  1
		            		FROM tbTaxMovements tmz	WITH (NOLOCK)
		            		WHERE	tmz.comp_id			= ct.comp_id
		            			AND tmz.ct_transaction	= ct.ct_transaction
		            			AND tmz.tax_id			= @tax_id
					)
		)
	AND ( @strCUIT		= '' OR ts.supp_taxNumber LIKE '%' + @strCUIT + '%')
	AND CASE
	        WHEN @country_id = -1 AND	@state_id		= -1					THEN 1
	        WHEN						ct.state_id		= @state_id				THEN 1
	        WHEN @state_id   = -1 AND   ct.country_id	= @country_id			THEN 1
	        ELSE 0
	    END = 1
	AND (ttr.supp_id IS NOT NULL OR @bitAllSuppliers = 'True')   -- verifica filtro de Proveedores
	AND (ts.supp_excludeFromTaxReport IS NULL OR ts.supp_excludeFromTaxReport = 'False')

--==
--and ct.ct_transaction between 26993 AND 26993
--==
	GROUP BY CT.ct_transaction,ct_date,ct_TaxDate,ts.supp_name,ts.supp_taxNumber,vwctp.sd_isCredit,vwctp.sd_isReceipt,CT.ct_subtotal,ct.sd_id,ct.ct_CAI,ct.ct_CAIDate,tba.ba_desc,tba.ba_taxNumber,tb.bra_TaxEngineOverPurchase_ShowTaxDate,ct_kindof,ct_pointOfSale,ct_docNumber,tfc.fc_desc,TSB.supp_name,tsb.comp_id,tsb.supp_taxNumber
	ORDER BY CT.ct_transaction


	CREATE INDEX #tmpCommercialTransactionsIndex_I ON #tmpCommercialTransactions(ct_transaction)


	-- -------------------------------------------------------------
	-- Borrar Todas las OP que no tengan descuento gravado con IVA
	-- OJO, Idem en Temporal mas Abajo!
	-- -------------------------------------------------------------
	IF @ten_sdIdGroup = 1
	BEGIN
		DELETE FROM #tmpCommercialTransactions
			FROM #tmpCommercialTransactions tmp
			INNER JOIN tbCommercialTransactions tct								WITH (NOLOCK)
				ON		tct.comp_id			= @comp_id
					AND tct.ct_transaction	= tmp.ct_transaction
			INNER JOIN tbCommercialTransactionsPaymentsAdditionals tctpa		WITH (NOLOCK)
				ON		tctpa.comp_id		= tct.comp_id
					AND tctpa.ct_transaction= tct.ct_transaction
			INNER JOIN tbTaxName ttn											WITH (NOLOCK)
				ON		ttn.comp_id			= tct.comp_id
					AND ttn.tax_id			= tctpa.tax_id4Discount
			WHERE ttn.tax_percentage = 0
				AND tct.sd_id IN (6,13,106)
	END
	-- -------------------------------------------------------------





	/*Aca llamamos al STORED PROCEDURE que maneja toda la logica de insersion en la temporal*/
	EXEC spCommercialTransactions_getTaxEngineOverAll @comp_id, @ten_id




	INSERT INTO @tmpCommercialTransactions(ct_transaction)
		SELECT DISTINCT tmp.ct_transaction FROM #tmpFinalData tmp


	-- ------------------------------------------------
	-- IMpresion de Datos del Subdiario
	-- ------------------------------------------------
	SELECT	tmp.*,
			ISNULL(@page_index,0) [page_index],
			tct.sd_id,
			tct.ct_kindOf,
			tct.ct_pointOfSale,
			tct.ct_docNumber,
			tct.ct_date										[tra_Date],
			tct.ct_taxDate									[tra_TaxDate]
		FROM #tmpFinalData	tmp
		INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
		ON	tct.comp_id = @comp_id			AND
			tct.ct_transaction = tmp.ct_transaction
		ORDER BY tmp.ct_Date,tmp.[DOCUMENT]
	-- ------------------------------------------------





	exec [spReports_getData2] @comp_id,@intBranch4Lang, @lang_id, @ten_id, @page_id

	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id






	SELECT	(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 529 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = @fun_id )			[params1],

			(	SELECT tov.optval_desc 	FROM dbo.tbsysOptionsValues tov
				WHERE tov.lang_id = @lang_id AND tov.optval_class = 43 AND tov.optval_id = 9 )									[params2],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 638 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params3],

			CASE @ten_id WHEN -1 THEN
				(SELECT tut.utexts_desc	FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 2 )
			ELSE
				(SELECT tten.ten_desc	FROM tbTaxEngineName tten WHERE tten.ten_id = @ten_id )
			END																													[params4],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 177 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params5],

				@datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))	[params6],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 384 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params7],

				@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))		[params8],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 639 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params9],

			CASE @brag_id WHEN -1 THEN
				(SELECT	tut.utexts_desc	FROM tbsysUniqueTexts tut	WHERE tut.lang_id=@lang_id AND tut.utexts_id = 2 )
			ELSE
				(SELECT tbg.brag_desc	FROM tbBranchGroup tbg		WHERE tbg.brag_id = @brag_id )
			END																													[params10],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 28 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )				[params11],

			CASE @bra_id WHEN -1 THEN
				(SELECT	tut.utexts_desc	FROM tbsysUniqueTexts tut	WHERE tut.lang_id = @lang_id AND tut.utexts_id = 1 )
			ELSE
				(SELECT tb.bra_desc		FROM tbBranch tb			WHERE tb.bra_id = @bra_id )
			END																													[params12],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 577 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )			[params13],

			CASE @tax_id WHEN -1 THEN
				(SELECT	tut.utexts_desc	FROM tbsysUniqueTexts tut	WHERE tut.lang_id = @lang_id AND tut.utexts_id = 1 )
			ELSE
				(SELECT ttn.tax_desc	FROM tbTaxName ttn			WHERE ttn.tax_id = @tax_id)
			END																													[params14]



-- (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1))

	SELECT	DISTINCT
			CT.ct_transaction,
			CT.ct_date,
			TS.supp_taxNumber																																		[Number],
			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,CT.ct_transaction)																			[Comprobante],
			CASE WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN CT.ct_subtotal ELSE CT.ct_subtotal * -1 END		[ct_subtotal],
			CASE
				WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN 'False'
				ELSE 'True'
			END																																						[sd_isCredit],
			tm.tm_transaction,
			tfc.fc_desc,
			td.sd_desc,
			ct.ct_kindOf,
  			isnull(ISNULL(tn.tax_desc, ttent.tent_columnName),'*')																									[tax_desc],
			CASE	WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN 1
					ELSE -1
			END																																						[PlusOrMinus],
			CASE WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN cast(ISNULL(tm.tm_total,0) AS DECIMAL(19,2))
				 ELSE (ISNULL(tm.tm_total,0   ) * -1)
			END																																						[taxAnt],
			CASE
				WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN ISNULL(tm.tm_subtotal,0)
				ELSE (ISNULL(tm.tm_subtotal,0) * -1)
			END																												[gravadoAnt],
			CAST(0 AS DECIMAL(19,2))																						[tax],
			CAST(0 AS DECIMAL(19,2))																						[gravado],
			CAST(0 AS DECIMAL(19,2))																						[nogravado],
			NEWID()																											[Id],
			tm.tax_id		[tax_id],	/*tn.tax_id MOS 05-2017*/
			ct.sd_id,
			tm.tax_id																										[Only4Order],
			-1																												[state_Id4Resume],
			ISNULL(ISNULL(ISNULL(ct.supp_id,ct.suppa_id),ct.supp_id4CreditCardLiquidation),-1)								[suppID4Resume]
	INTO	#tmp1

	FROM 	dbo.tbCommercialTransactions							CT								WITH (NOLOCK)

			INNER JOIN @tmpCommercialTransactions kkk
				ON kkk.ct_transaction = CT.ct_transaction

			LEFT JOIN #tmpFinalData fd																WITH (NOLOCK)
			ON fd.ct_transaction = CT.ct_transaction

			INNER JOIN dbo.vwCommercialTransactions_forPurchase_TaxEngine		vwctp				WITH (NOLOCK)
			ON 	vwctp.ct_Transaction	= CT.ct_transaction
			AND vwctp.bra_id			= CT.bra_id
			AND vwctp.comp_id			= CT.comp_id
			--AND vwctp.sd_isTaxable		= 'True'

			LEFT JOIN tbTaxMovements								TM								WITH (NOLOCK)
			ON 	TM.comp_id				= CT.comp_id
			AND TM.bra_id				= CT.bra_id
			AND TM.ct_transaction		= CT.ct_transaction
			AND ((@ten_sdIdGroup = 1 AND not ct.sd_id IN (6,13,106)) OR (@ten_sdIdGroup <> 1 ))

			INNER JOIN tbUsers4BranchFilter							vubf							WITH (NOLOCK)
			ON  vubf.comp_id			= CT.comp_id
			AND vubf.bra_id				= CT.bra_id
			AND vubf.[user_id]			= @user_id

			left JOIN tbSupplier									TS								WITH (NOLOCK)
			ON	TS.comp_id				= CT.comp_id
			AND TS.supp_id				= CT.supp_id


			--left JOIN tbSupplier									TS4Res							WITH (NOLOCK)
			--ON	TS.comp_id				= CT.comp_id
			--AND TS.supp_id				= ISNULL(ISNULL(ISNULL(ct.supp_id,ct.suppa_id),ct.supp_id4CreditCardLiquidation),-1)


			LEFT JOIN dbo.[tbTaxName]								tn								WITH (NOLOCK)
			on	tn.comp_id				= TM.comp_id
			and tn.tax_id				= TM.tax_id
			and tn.tax_class			= 1


			LEFT JOIN tbsysFiscalClass								tfc								WITH (NOLOCK)
			ON	tfc.fc_id				= TS.fc_id

			LEFT JOIN tbsysDocuments								td								WITH (NOLOCK)
			ON	td.sd_id				= CT.sd_id

			LEFT JOIN tbTaxEngineName_Taxes							ttent							WITH (NOLOCK)
			ON	ttent.comp_id			= CT.comp_id
			AND ttent.tax_id			= TM.tax_id
			AND ttent.ten_id			= @ten_id


	WHERE	CT.comp_id	= @comp_id
	AND 	CT.ct_taxDate between @datefrom and @dateto
	AND 	((@brag_id	= -1
				AND (@bra_id = -1 OR CT.bra_id = @bra_id)) OR
			(@brag_id <> -1
				and CT.bra_id IN (SELECT bgd.bra_id
								  FROM tbBranchGroupDetail bgd
								  WHERE bgd.brag_id = @brag_id)))

	AND		(
			 (@ten_sdIdGroup = 1 and (vwctp.sd_isTaxable	= 'True'  OR vwctp.sd_isReceipt = 'True' AND ct.ct_discount <> 0)) OR
			 (@ten_sdIdGroup = 2 and vwctp.sd_isReceipt		= 'True') OR
			 (@ten_sdIdGroup = 3 and vwctp.sd_isReceipt		= 'True'))

	ORDER BY CT.ct_transaction

	DECLARE @intRowCount AS INT
	SET @intRowCount = @@ROWCOUNT


	-- x velocidad se hace fuera del select anterior
	UPDATE #tmp1
		SET state_Id4Resume = ISNULL(ts.state_id,-1)		-- MOS, 11-2020, ticket 11215
		FROM #tmp1 tmp
		INNER JOIN tbSupplier AS ts		WITH (NOLOCK)
			ON	ts.comp_id = @comp_id AND
				ts.supp_id = tmp.suppID4Resume



	-- -------------------------------------------------------------
	-- Borrar Todas las OP que no tengan descuento gravado con IVA
	-- OJO, Idem en Temporal mas Abajo!
	-- -------------------------------------------------------------
	IF @ten_sdIdGroup = 1
	BEGIN
		DELETE FROM #tmp1
			FROM #tmp1 tmp
			INNER JOIN tbCommercialTransactions tct									WITH (NOLOCK)
				ON		tct.comp_id			= @comp_id
					AND tct.ct_transaction	= tmp.ct_transaction
			INNER JOIN tbCommercialTransactionsPaymentsAdditionals tctpa			WITH (NOLOCK)
				ON		tctpa.comp_id		= tct.comp_id
					AND tctpa.ct_transaction= tct.ct_transaction
			INNER JOIN tbTaxName ttn												WITH (NOLOCK)
				ON		ttn.comp_id			= tct.comp_id
					AND ttn.tax_id			= tctpa.tax_id4Discount
			WHERE ttn.tax_percentage = 0
				AND tct.sd_id IN (6,13,106)
	END
	-- -------------------------------------------------------------


	CREATE NONCLUSTERED INDEX #tmpIndex1 ON #tmp1
						(
						ID
						)
						INCLUDE ( ct_transaction)
						WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]

	CREATE NONCLUSTERED INDEX #tmpIndex2 ON #tmp1
						(
						ct_transaction
						)
						INCLUDE ( ID)
						WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]




--==
--select '#tmpFinalData',* from #tmpFinalData
--==


	-- MOS  08-2010
	-- -----------------------------------------------------------------------
	-- Pone los netos NO Grabados en el resumen
	-- Se genera en CERO arriba para que no se dupliquen en todas las filas
	-- -----------------------------------------------------------------------
	DECLARE @curCT_Transaction  AS INT
	DECLARE @curLastTransaction AS INT

	DECLARE @curTM_Transaction  AS INT
	DECLARE @curLTMTransaction  AS INT

	DECLARE @curCT_TaxId		AS INT
	DECLARE @curLastTaxId		AS INT

	DECLARE @curTCT_TaxId		AS INT
	DECLARE @curTLastTaxId		AS INT



	DECLARE @curCT_Id		    AS UNIQUEIDENTIFIER
	SET @curLastTransaction = 0
	SET @curLTMTransaction  = 0
	SET @curLastTaxId		= 0
	DECLARE curTMP1 CURSOR LOCAL  FAST_FORWARD FOR
									SELECT	ct_transaction,
											Id,
											tm_transaction,
											Tmp.tax_id,
											Tmp.tax_id
										FROM #tmp1 Tmp
										--Left JOIN tbTaxName ttn
										--	ON	ttn.comp_id = @comp_id	 AND
										--		ttn.tax_id  = Tmp.tax_Id
										--ORDER BY Tmp.ct_transaction,IsNull(ttn.tax_class,9999999),ttn.tax_id
										ORDER BY Tmp.ct_transaction,
													CASE
														WHEN Tmp.tax_id IS NULL THEN 1
														else 0
													END,
													--Tmp.tm_transaction,			--MOS: 01-2020 ATENCION, NO SACAR ya que esto varia el orden y puede hacer que ante quilombos de orden por temposales calcule diferentes los IMPUESTOS en diferentes ejecuciones del cursor.
													--Tmp.tax_id
													Tmp.tax_id,
													Tmp.tm_transaction				-- MOS : 02-2020 x q no calculaba en el cursot correctamente los gravados



	OPEN curTMP1
	FETCH NEXT FROM curTMP1 INTO @curCT_Transaction,@curCT_Id,@curTM_Transaction,@curCT_TaxId,@curTCT_TaxId
	WHILE @@FETCH_STATUS = 0
	BEGIN



		IF @curCT_Transaction <> @curLastTransaction or @curCT_TaxId <> @curLastTaxId
			BEGIN

				IF @curCT_Transaction <> @curLastTransaction
					BEGIN

						UPDATE #tmp1
						SET nogravado = isnull((SELECT Sum(isnull(FD1.nogravado /* * Tmp1.PlusOrMinus*/,0))
													FROM #tmpFinalData FD1
													inner join #tmp1 Tmp1
														on	Tmp1.ID				= @curCT_Id
													WHERE	FD1.ct_transaction	= @curCT_Transaction
													GROUP BY FD1.ct_transaction),0)

						WHERE ID = @curCT_Id

					END


				SET @curLastTransaction = @curCT_Transaction
				SET @curLastTaxId		= @curCT_TaxId



				UPDATE #tmp1
--				SET nogravado = isnull((SELECT Sum(isnull(FD1.nogravado /** Tmp1.PlusOrMinus*/,0))
--											FROM #tmpFinalData FD1
--											inner join #tmp1 Tmp1
--												on	Tmp1.ID				= @curCT_Id
--											WHERE	FD1.ct_transaction	= @curCT_Transaction
--											GROUP BY FD1.ct_transaction),0),

					SET gravado   = isnull((

										SELECT IsNull(SUM(ttm.tm_subtotal *
																			CASE
																				WHEN tct.sd_id IN (103,106) THEN -1
																				ELSE 1
																			END
																			) ,0)
											FROM tbTaxMovements ttm										WITH (NOLOCK)
											INNER JOIN tbCommercialTransactions tct						WITH (NOLOCK)
												ON		tct.comp_id			= ttm.comp_id
													AND tct.ct_transaction	= ttm.ct_transaction
											WHERE	ttm.comp_id			= @comp_id
												AND ttm.ct_transaction	= @curCT_Transaction
												AND ttm.tax_id			= @curTCT_TaxId
											GROUP BY ttm.comp_id,ttm.ct_transaction,ttm.tax_id

										),0)
				WHERE ID = @curCT_Id AND sd_id NOT IN (140,141,142, /*Nuevo Extracto Bancario*/ 143,144)
			END

		IF @curTM_Transaction <> @curLTMTransaction or @curTCT_TaxId <> @curTLastTaxId
			BEGIN
				SET @curLTMTransaction = @curTM_Transaction
				SET @curTLastTaxId	   = @curTCT_TaxId
				UPDATE #tmp1
				SET tax = isnull((	SELECT taxAnt /** PlusOrMinus */
										FROM #tmp1
				                  		WHERE #tmp1.Id = @curCT_Id),0)
				WHERE ID = @curCT_Id --NO!AND sd_id NOT IN (140,141,142)
			END

		FETCH NEXT FROM curTMP1 INTO @curCT_Transaction,@curCT_Id,@curTM_Transaction,@curCT_TaxId,@curTCT_TaxId

	END
	CLOSE curTMP1
	DEALLOCATE curTMP1



	-- ------------------------------------------------------
	-- Graba Neto de Descuentos por Recibo u Ordenes de Pago
	-- ------------------------------------------------------
	UPDATE #tmp1
		SET tax = (tfd.total - tfd.gravado),
			gravado = tfd.gravado
		FROM #tmp1				 tmp
		INNER JOIN #tmpFinalData tfd
			ON tfd.ct_transaction		= tmp.ct_transaction
		INNER JOIN tbCommercialTransactions tct							WITH (NOLOCK)
			ON		tct.comp_id			= @comp_id
				AND tct.ct_transaction	= tmp.ct_transaction
		INNER JOIN tbCommercialTransactionsPaymentsAdditionals tctpa	WITH (NOLOCK)
			ON		tctpa.comp_id			= tct.comp_id
				AND tctpa.ct_transaction	= tct.ct_transaction
		WHERE		@ten_sdIdGroup = 1
				AND tct.sd_id IN (6,13,106)
	-- ------------------------------------------------------




	-- ------------------------------------------------------
	-- Actualiza para Transacciones Bancarias y Liq.T.Credito
	-- ------------------------------------------------------
	SELECT * -- Para que no de ambiguous abajo
		INTO #tmpBanking
		FROM #tmp1 tt
		WHERE tt.sd_id IN (140,141,142,/*Nuevo Extracto Bancario*/ 143,144)

	UPDATE #tmp1
		SET gravado		=	CASE
								WHEN A1.tm_transaction = A3.tm_transaction THEN A2.gravado
								ELSE 0
							END,
			nogravado	=	CASE
								WHEN A1.tm_transaction = A3.tm_transaction THEN (A2.nogravado + A2.exento )
								ELSE 0
							END
	FROM #tmp1					A1
	INNER JOIN #tmpFinalData	A2
		ON A2.ct_transaction = A1.ct_transaction
	INNER JOIN #tmpBanking	as		A3					-- Esto se hace para que no sume si es que tiene mas de un impuesto
		ON	A3.ct_transaction = A1.ct_transaction
	WHERE A1.sd_id IN (140,141,142,/*Nuevo Extracto Bancario*/ 143,144)
	DROP TABLE #tmpBanking
	-- ------------------------------------------------------



--	--SELECT ' --------------'
--	SELECT ' ****************************'
	--SELECT * FROM #tmpFinalData
--	--SELECT ' --------------'

--SELECT * FROM #tmpFinalData
--SELECT 'Help1:',* FROM #tmp1

	-- -----------------------------------------------------------------------

	IF @intRowCount > 0
		BEGIN

			-- ----------------------------------------------------------------------
			-- Prepara Resumen
			-- ----------------------------------------------------------------------
			SELECT	tmp.fc_desc		,
					tmp.sd_desc		,
					tmp.ct_kindOf	,
					tmp.tax_desc	,
  					sum(tmp.tax)													[tax],
  					CASE WHEN sum(tmp.tax) <> 0 THEN SUM(tmp.gravado)	ELSE 0 END	[gravado],
  					SUM([nogravado])												[nogravado],
  					CASE
  						WHEN tmp.sd_id IN (140,141,142,/*Nuevo Extracto Bancario*/ 143,144) THEN -1
  						WHEN tmp.state_Id4Resume > 0										THEN state_Id4Resume		-- MOS 07-2020, se cambia de Provincia de la Sucursal q contabiliza a la provincia del proveedor relacionado.
  						ELSE tct.state_id
  					end																[state_id],
  					ISNULL(tba.ba_desc,'')											[ba_Desc]
			INTO	#tmp2
			FROM	#tmp1			tmp
			INNER JOIN tbCommercialTransactions tct							WITH (NOLOCK)
				ON tct.comp_id				= @comp_id
					AND tct.ct_transaction	= tmp.ct_transaction
			LEFT JOIN tbBankingAccounts tba									WITH (NOLOCK)
				ON	tba.comp_id = tct.comp_id AND
					tba.ba_id	= tct.ba_id
			WHERE	NOT tmp.tax_desc IS NULL
			GROUP BY	tmp.fc_desc,
  						tmp.sd_desc,
  						tmp.ct_kindOf,
  						tmp.tax_desc,
  						CASE
  							WHEN tmp.sd_id IN (140,141,142,/*Nuevo Extracto Bancario*/ 143,144) THEN -1
  							WHEN tmp.state_Id4Resume > 0										THEN state_Id4Resume
  							ELSE tct.state_id
  						end
  						/*tct.state_id*/,
  						tmp.sd_id,
  						tba.ba_desc



			-- ----------------------------------------------------------------------
			-- Resumen Uno
			-- ----------------------------------------------------------------------

  			SELECT	fc_desc		,
  					sd_desc		,
  					ct_kindOf	,
  					tax_desc	,
  					tax	[total]	,
  					[gravado]	,
  					[nogravado]
  			FROM	#tmp2
  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0

			-- ----------------------------------------------------------------------
			-- Resumen DOS
			-- ----------------------------------------------------------------------

			SELECT
				CASE
					WHEN tmp.state_id = -1 THEN 'Banking . . .'
					ELSE ts.state_desc
				end																	[state_desc],
				sum(Tmp.tax)														[total],
  				CASE WHEN sum(Tmp.tax) <> 0 THEN SUM(Tmp.gravado)	ELSE 0 END		[gravado],
  				SUM(Tmp.nogravado)													[nogravado]

			FROM #tmp2 Tmp

				LEFT JOIN tbsysState ts
				ON	ts.state_id = Tmp.state_id

  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0
			GROUP BY ts.state_desc,tmp.state_id

			-- ----------------------------------------------------------------------
			-- Resumen Tres
			-- ----------------------------------------------------------------------
  			SELECT
				tax_desc,
				SUM(#tmp2.tax)			[total],
				SUM(#tmp2.gravado)		[gravado],
				SUM(#tmp2.nogravado)	[nogravado]

  			FROM	#tmp2

  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0

  			GROUP BY tax_desc


			-- ----------------------------------------------------------------------
			-- Resumen Cuatro RESUMEN POR CONCEPTO DE COMPRAS
			-- ----------------------------------------------------------------------

			-- Obtiene Importes EXENTOS para restarlos del total de NETOS hallado
			DECLARE @decTotalesExentos AS DECIMAL(19,4)
			SELECT  @decTotalesExentos = SUM(IsNull(exento,0)) FROM #tmpFinalData
			--SELECT @decTotalesExentos

			-- Pone en una Temporal los Conceptos de compra hallados.-
			SELECT	ct.comp_id,
					CT.ct_transaction,
					ct.ct_subtotal,
					NULL		/*tpc1*/									[pucoId4itemTransaction],
					NULL													[it_transaction],
					tpcm.puco_id   /*tpc2*/								[pucoId4purchaseConcept],
					tpcm.pcm_id,
					0
																		[itemTransactionTotal],
					dbo.fnGetExchange2(ct.comp_id,tpcm.pcm_total * vwctp.PlusOrMinus,tpcm.curr_id,ct.curr_id_transaction,ct.curr_id4Exchange,ct.curr_id_transaction,CT.ct_curr_IdExchange,'false')
																		[purchaseConceptTotal],
					CONVERT(DECIMAL(19,4),0)							[netoGravado],
					CONVERT(DECIMAL(19,4),0)							[netoNoGravado],
					CONVERT(DECIMAL(19,4),0)							[Exento],
					0													[pucoId4Unique]

			INTO	#tmpRC
			FROM 	dbo.tbCommercialTransactions							CT				WITH (NOLOCK)
					INNER JOIN dbo.vwCommercialTransactions_forPurchase_TaxEngine /*vwCommercialTransactions_forPurchase*/		vwctp			WITH (NOLOCK)
						ON 	vwctp.ct_Transaction	= CT.ct_transaction
						AND vwctp.bra_id			= CT.bra_id
						AND vwctp.comp_id			= CT.comp_id
					INNER JOIN tbUsers4BranchFilter							vubf			WITH (NOLOCK)
						ON  vubf.comp_id			= CT.comp_id
						AND vubf.bra_id				= CT.bra_id
						AND vubf.[user_id]			= @user_id
					INNER JOIN tbSupplier									TS				WITH (NOLOCK)
						ON	TS.comp_id				= CT.comp_id
						AND TS.supp_id				= CT.supp_id
					LEFT JOIN tbsysFiscalClass								tfc				WITH (NOLOCK)
						ON	tfc.fc_id				= TS.fc_id
					LEFT JOIN tbsysDocuments								td				WITH (NOLOCK)
						ON	td.sd_id				= CT.sd_id
					LEFT JOIN tbPurchaseConceptMovements tpcm								WITH (NOLOCK)
						ON		tpcm.comp_id		= ct.comp_id
							AND tpcm.ct_transaction = ct.ct_transaction
			WHERE	CT.comp_id	= @comp_id
			AND 	CT.ct_taxDate between @datefrom and @dateto
			AND 	((@brag_id	= -1
						AND (@bra_id = -1 OR CT.bra_id = @bra_id)) OR
					(@brag_id <> -1
						and CT.bra_id IN (SELECT bgd.bra_id
										  FROM tbBranchGroupDetail bgd		WITH (NOLOCK)
										  WHERE bgd.brag_id = @brag_id)))
			AND		(
					 (@ten_sdIdGroup = 1 and (vwctp.sd_isTaxable	= 'True'  OR vwctp.sd_isReceipt = 'True' AND ct.ct_discount <> 0)) OR
					 (@ten_sdIdGroup = 2 and vwctp.sd_isReceipt		= 'True') OR
					 (@ten_sdIdGroup = 3 and vwctp.sd_isReceipt		= 'True'))
			--ORDER BY CT.ct_transaction


			UNION ALL

			-- Pone en una Temporal los Items de compra hallados.-
			SELECT	ct.comp_id,
					CT.ct_transaction,
					ct.ct_subtotal,
					tit.puco_id		/*tpc1*/							[pucoId4itemTransaction],
					tit.it_transaction,
					NULL  /*tpc2*/										[pucoId4purchaseConcept],
					NULL,
					tit.it_qty * tit.it_price *	vwctp.PlusOrMinus *
					CASE
						WHEN tit.curr_id <> tb.curr_id THEN tit.it_exchangeToBranchCurrency
						ELSE 1
					END
																		[itemTransactionTotal],
					0													[purchaseConceptTotal],
					CONVERT(DECIMAL(19,4),0)							[netoGravado],
					CONVERT(DECIMAL(19,4),0)							[netoNoGravado],
					CONVERT(DECIMAL(19,4),0)							[Exento],
					0													[pucoId4Unique]

			FROM 	dbo.tbCommercialTransactions							CT				WITH (NOLOCK)
				INNER JOIN tbBranch										 AS tb				WITH (NOLOCK)
					ON	tb.comp_id					= CT.comp_id AND
						tb.bra_id					= CT.bra_id
				INNER JOIN dbo.vwCommercialTransactions_forPurchase_TaxEngine /*vwCommercialTransactions_forPurchase*/		vwctp			WITH (NOLOCK)
					ON 	vwctp.ct_Transaction	= CT.ct_transaction
					AND vwctp.bra_id			= CT.bra_id
					AND vwctp.comp_id			= CT.comp_id
				INNER JOIN tbUsers4BranchFilter							vubf			WITH (NOLOCK)
					ON  vubf.comp_id			= CT.comp_id
					AND vubf.bra_id				= CT.bra_id
					AND vubf.[user_id]			= @user_id
				INNER JOIN tbSupplier									TS				WITH (NOLOCK)
					ON	TS.comp_id				= CT.comp_id
					AND TS.supp_id				= CT.supp_id
				LEFT JOIN tbsysFiscalClass								tfc				WITH (NOLOCK)
					ON	tfc.fc_id				= TS.fc_id
				LEFT JOIN tbsysDocuments								td				WITH (NOLOCK)
					ON	td.sd_id				= CT.sd_id
				LEFT JOIN tbItemTransactions tit										WITH (NOLOCK)
					ON		tit.comp_id			= ct.comp_id
						AND tit.ct_transaction	= ct.ct_transaction
			WHERE	CT.comp_id	= @comp_id
			AND 	CT.ct_taxDate between @datefrom and @dateto
			AND 	((@brag_id	= -1
						AND (@bra_id = -1 OR CT.bra_id = @bra_id)) OR
					(@brag_id <> -1
						and CT.bra_id IN (SELECT bgd.bra_id
										  FROM tbBranchGroupDetail bgd		WITH (NOLOCK)
										  WHERE bgd.brag_id = @brag_id)))
			AND		(
					 (@ten_sdIdGroup = 1 and (vwctp.sd_isTaxable	= 'True'  OR vwctp.sd_isReceipt = 'True' AND ct.ct_discount <> 0)) OR
					 (@ten_sdIdGroup = 2 and vwctp.sd_isReceipt		= 'True') OR
					 (@ten_sdIdGroup = 3 and vwctp.sd_isReceipt		= 'True'))
			ORDER BY CT.ct_transaction





--==
--select 'lll',* from #tmpRC
--==

			-- Lo pongo en otra temporal por si mas adelante hay que sacar el neto gravado y exento de cada uno
			-- De tener que hacerlo hay que recorrer la tabla #tmpRC y poner en los campos que se generaron para eso que ahora
			-- estan en CERO.
			-- Unifico el Concepto de compra para poder sumar agrupados.-
			UPDATE #tmpRC
				SET pucoId4Unique = CASE
										WHEN pucoId4itemTransaction IS NOT NULL THEN pucoId4itemTransaction
										WHEN pucoId4purchaseConcept IS NOT NULL THEN pucoId4purchaseConcept
										ELSE -1
									END

--==
--select '222',* from #tmpRC
--==

			SELECT
				dbo.fnStrPADR(ISNULL( ta.acc_code,''),20,' ') + ' ->' +	ISNULL(tpc.puco_desc ,'')		[tax_desc],
				0																	[total],
				Convert(decimal(19,2),SUM(ISNULL(purchaseConceptTotal,0)))
				+
				Convert(decimal(19,2),SUM(ISNULL(ItemTransactionTotal,0)))			[gravado],
				0																	[nogravado]
				INTO #tmpRC2
				FROM #tmpRC						tmp
				Left JOIN tbPurchaseConcept tpc						WITH (NOLOCK)
					ON tpc.puco_id = tmp.pucoId4Unique
				LEFT JOIN tbAccountant ta							WITH (NOLOCK)
					ON ta.acc_count_id = tpc.acc_count_id
			GROUP BY tmp.pucoId4Unique,tpc.puco_desc,ta.acc_code

			-- Resta los importes EXENTOS ya que esto los incluye para que coincidan con el total de conceptos que los tiene incluidos.-
			INSERT INTO #tmpRC2 (gravado,total,nogravado,tax_desc) VALUES (-@decTotalesExentos,0,0,'Exentos')

			SELECT * FROM #tmpRC2
--==
--	SELECT SUM([gravado]) FROM #tmpRC2
--==




			-- ----------------------------------------------------------------------
			-- Resumen Cinco, por Comprobante
			-- ----------------------------------------------------------------------

  			SELECT
  					sd_desc		,
  					ct_kindOf	,
  					tax_desc	,
  					SUM(tax)		[total]	,
  					SUM(gravado)    [gravado],
  					SUM(nogravado)  [nogravado]
  			FROM	#tmp2
  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0
  			GROUP BY
  				  	sd_desc		,
  					ct_kindOf	,
  					tax_desc


			-- ----------------------------------------------------------------------
			-- Resumen 6, por Provincia e Impuesto  08-2020
			-- ----------------------------------------------------------------------
			SELECT
				ts.state_desc,
				sum(Tmp.tax)														[total],
  				CASE
  					WHEN sum(Tmp.tax) <> 0 THEN SUM(Tmp.gravado)
  					ELSE 0
  				END																	[gravado],
  				SUM(Tmp.nogravado)													[nogravado],
  				 0																	[exento],
  				Tmp.tax_desc
				FROM #tmp2 Tmp
				LEFT JOIN tbsysState ts					WITH (NOLOCK)
					ON	ts.state_id = Tmp.state_id
  				WHERE	[tax]		<> 0 OR
  						[gravado]	<> 0 OR
  						[nogravado] <> 0
				GROUP BY ts.state_desc,Tmp.tax_desc



			DROP TABLE #tmpRC2
			DROP TABLE #tmpRC


			--
			--  			SELECT
			--				tax_desc,
			--				SUM(#tmp2.tax)			[total],
			--				SUM(#tmp2.gravado)		[gravado],
			--				SUM(#tmp2.nogravado)	[nogravado]
			--  			FROM	#tmp2
			--  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0
			--  			GROUP BY tax_desc
			-- ----------------------------------------------------------------------



		END
	ELSE
		BEGIN
			SELECT	@message	[fc_desc]	,
					' '			[sd_desc]	,
					' '			[ct_kindOf]	,
					' '			[tax_desc]	,
					0.00		[tax]
		END
	/***************************************************************************************************************************************/


	delete dbo.tbTaxEngineTmp1 where guid = @guid
	delete dbo.tbTaxEngineTmp2 where guid = @guid


END
GO




CREATE PROCEDURE [dbo].[spCommercialTransactions_getReportTaxEngineOverPurchaseOLD012020]


(
	@comp_id		int,
	@lang_id		int,
	@page_id		int,
	@guid			uniqueidentifier,
	@ten_id			int,
	@datefrom		datetime,
	@dateto			datetime,
	@brag_id		int,
	@bra_id			Int,
	@tax_id			int,
	@country_id		INT,
	@state_id		INT,
	@user_id		INT,
	@strCUIT		VARCHAR(30),
	@intBranch4Lang	int,
	@page_index		INT,
	@guid_supp  	VARCHAR(50)
)
AS




BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------





	-- ------------------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------------------
	/*
	    DECLARE 		@comp_id		int,
					@lang_id		int,
					@page_id		int,
					@guid			uniqueidentifier,
					@ten_id			int,
					@datefrom		datetime,
					@dateto			datetime,
					@brag_id		int,
					@bra_id			Int,
					@tax_id			int,
					@country_id		INT,
					@state_id		INT,
					@user_id		INT,
					@strCUIT		VARCHAR(30),
					@intBranch4Lang	int,
					@page_index		INT

	SELECT 		@guid			='fd82d14d-7c3b-4bb8-a04c-511d3f4fe4b7',--'45b7f584-70ae-4d17-981d-392a3b8c75e9',
				@comp_id		= 1,
				@lang_id		= 2,
				@page_id		= 10033,
				@ten_id			= 9,
				@datefrom		='2017-04-06',
				@dateto			='2017-04-30',
				@brag_id		=4,
				@bra_id			=1,
				@user_id		= 1,
				@tax_id			= -1,
				@intBranch4Lang	= 2,
				@page_index		= -1,
				@country_id		= -1,
				@state_id		= -1,
				@strCUIT		= ''

	DROP TABLE #tmpFinalData
	DROP TABLE #tmpCommercialTransactions
	DROP TABLE #tmpColumns
	DROP TABLE #tmp1
	DROP TABLE #tmp2
	DROP TABLE #tmpColumnsNames
	*/
	-- ---------------------------------------------------------------------------------------------

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @bitAllSuppliers AS BIT = 'False'
	DECLARE @lGuid_Supp AS UNIQUEIDENTIFIER
	SET @lGuid_Supp = CONVERT(UNIQUEIDENTIFIER,@guid_supp)
	DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Supplier
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf		WITH (NOLOCK)
			WHERE tcf.sl_guid = @lGuid_Supp     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			SET @bitAllSuppliers = 'True'
			INSERT INTO @tblComplexFilter_Supplier
				SELECT ts.supp_id
				FROM tbSupplier ts	WITH (NOLOCK)
					WHERE ts.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

	SET @datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateTo   = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')



	DECLARE @fun_id INT
	SET @fun_id = 1

	CREATE TABLE #tmpColumns (id INT IDENTITY, tent_column INT)

	INSERT INTO #tmpColumns		(tent_column)
	SELECT						tent_column
		FROM	tbTaxEngineName_Taxes ttent			WITH (NOLOCK)
		WHERE	ttent.comp_id	= @comp_id
			AND	ttent.ten_id	= @ten_id
			AND ttent.tent_id4Summary IS NULL		--== Aca Modifique
		ORDER BY ttent.tent_column


	--SELECT * FROM #tmpColumns
	CREATE TABLE #tmpColumnsNames ( id INT IDENTITY, [colname] VARCHAR(100) )


	/*Creamos la tabla*/
	CREATE TABLE #tmpFinalData
					(
					ct_transaction		INT,
					tmp_id				INT IDENTITY,
					ct_date				DATETIME,
					supp_name			VARCHAR(100),
					supp_number			VARCHAR(20),
					[document]			VARCHAR(100),

					ct_CAI				NVARCHAR(50), --STL 12/11/2010
					ct_CAIDate			DATETIME,

					gravado				DECIMAL(19,2) DEFAULT 0 NULL,
					nogravado			DECIMAL(19,2) DEFAULT 0	NULL,
					exento				DECIMAL(19,2) DEFAULT 0	NULL
					)

	CREATE INDEX #tmpFinalData_I  ON #tmpFinalData(ct_transaction)
	CREATE INDEX #tmpFinalData_II ON #tmpFinalData(tmp_id)

	DECLARE	@column_name		VARCHAR(100),
			@tent_column		INT,
			@auxTotal		AS	DECIMAL(19,6)
			--@tent_isHidden		BIT



	DECLARE @message VARCHAR(100)
	SELECT @message = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 150 AND tut.lang_id = @lang_id



--== Aca MOdifique
	/*Cursor que Modifica la tabla y le agrega las columnas de la TaxEngineName_Taxes*/
	DECLARE cursor_columns CURSOR LOCAL FAST_FORWARD FOR
	SELECT	distinct
			ttent.tent_columnName,
			tmpc.id
		FROM	tbTaxEngineName_Taxes			ttent			WITH (NOLOCK)
		INNER JOIN #tmpColumns						tmpc
			ON	ttent.tent_column			= tmpc.tent_column
		where	ttent.ten_id				= @ten_id
			AND ttent.comp_id				= @comp_id
		ORDER BY tmpc.id


	OPEN cursor_columns


	FETCH NEXT FROM cursor_columns
	INTO	@column_name,
			@tent_column


	WHILE @@FETCH_STATUS = 0
	BEGIN

		EXEC ('alter table #tmpFinalData add [Columna' + @tent_column + '] decimal(19,6) default 0')

		INSERT INTO #tmpColumnsNames (colname) VALUES ( '[Columna' + convert(varchar,@tent_column) + ']')

		FETCH NEXT FROM cursor_columns
		INTO	@column_name,
				@tent_column

	END


	EXEC ('alter table #tmpFinalData add total decimal(19,6) default 0')




	CLOSE cursor_columns
	DEALLOCATE cursor_columns

	DECLARE @ten_sdIdGroup INT
	SELECT	@ten_sdIdGroup	= isnull(tten.ten_sdIdGroup,1)
	FROM	tbTaxEngineName tten
	WHERE	tten.comp_id	= @comp_id
	AND		tten.ten_id		= @ten_id


	DECLARE @tmpCommercialTransactions TABLE(ct_transaction INT PRIMARY KEY)


	/*Select del Stored Procedure Original que trae los datos de la COMMERCIAL TRANSACTIONS y los inserta en la tabla #tmpFinalData*/
	SELECT	CT.ct_transaction,
			CASE
			    WHEN	tb.bra_TaxEngineOverPurchase_ShowTaxDate = 'True'  THEN	CT.ct_taxDate
			    ELSE															ct.ct_date
			END																							[ct_date],
			ct.ct_CAI,
			ct.ct_CAIDate,
			CASE
				WHEN tsb.comp_id IS NOT NULL THEN	tsb.supp_name
				ELSE								SUBSTRING(IsNull(TS.supp_name,IsNull(tba.ba_desc,'*CB')),1,30)
			END																							[Name],		-- MOS 06-2016 ISNULL(TSB.supp_name,'')
			CASE
				WHEN tsb.comp_id IS NOT NULL THEN	tsb.supp_taxNumber
				ELSE								IsNull(TS.supp_taxNumber,ISNULL(tba.ba_taxNumber,'*CB'))
			END																							[Number],
			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,CT.ct_transaction)				[Comprobante],
			ct.ct_kindOf, ct.ct_pointOfSale, ct.ct_docNumber,
			CASE
				WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN CT.ct_subtotal
				ELSE CT.ct_subtotal * -1
			END																							[ct_subtotal],
			CASE
				WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN 'False'
				ELSE 'True'
			END																							[sd_isCredit],
			ct.sd_id,
			tfc.fc_desc

			INTO #tmpCommercialTransactions

	FROM 	dbo.tbCommercialTransactions							CT						WITH (NOLOCK)

			INNER JOIN dbo.vwCommercialTransactions_forPurchase_TaxEngine		vwctp		WITH (NOLOCK)
			ON 	vwctp.ct_Transaction	= CT.ct_transaction
			AND vwctp.bra_id			= CT.bra_id
			AND vwctp.comp_id			= CT.comp_id
			--AND vwctp.sd_isTaxable		= 'True'

			LEFT JOIN tbTaxMovements								TM						WITH (NOLOCK)
			ON 	TM.comp_id				= CT.comp_id
			AND TM.bra_id				= CT.bra_id
			AND TM.ct_transaction		= CT.ct_transaction

			INNER JOIN tbBranch tb															WITH (NOLOCK)
				ON	tb.comp_id	= ct.comp_id AND
					tb.bra_id	= ct.bra_id

			INNER JOIN tbUsers4BranchFilter							vubf					WITH (NOLOCK)
			ON  vubf.comp_id			= CT.comp_id
			AND vubf.bra_id				= CT.bra_id
			AND vubf.[user_id]			= @user_id


			LEFT JOIN @tblComplexFilter_Supplier ttr
				ON ttr.supp_id = ct.supp_id

			Left JOIN vwSupplier									TS						WITH (NOLOCK)
			ON	TS.comp_id				= CT.comp_id		AND
				ts.bra_id				= CT.bra_id			AND
			    TS.ct_transaction		= CT.ct_transaction	AND
			    TS.supp_id				= CT.supp_id

			LEFT JOIN tbsysFiscalClass tfc
				ON tfc.fc_id = ts.fc_id

			LEFT JOIN tbBankingAccounts tba													WITH (NOLOCK)
				ON		tba.comp_id		= ct.comp_id
					AND tba.ba_id		= ct.ba_id


			left JOIN tbSupplier									TSB								WITH (NOLOCK)
			ON	TSB.comp_id				= CT.comp_id
			AND TSB.supp_id				= CT.supp_id4CreditCardLiquidation


	WHERE	CT.comp_id	= @comp_id
	AND 	CT.ct_taxDate between @datefrom and @dateto
	AND 	((@brag_id	= -1
				AND (@bra_id = -1 OR CT.bra_id = @bra_id)) OR
			(@brag_id <> -1
				and CT.bra_id IN (SELECT bgd.bra_id
									  FROM tbBranchGroupDetail bgd	WITH (NOLOCK)
									  WHERE bgd.brag_id = @brag_id)))

	AND		(
			 (@ten_sdIdGroup = 1 and (vwctp.sd_isTaxable	= 'True'  OR vwctp.sd_isReceipt = 'True' AND ct.ct_discount <> 0)) OR
			 (@ten_sdIdGroup = 2 and vwctp.sd_isReceipt		= 'True') OR
			 (@ten_sdIdGroup = 3 and vwctp.sd_isReceipt		= 'True'))
	AND (
			 @tax_id = -1 OR
			 EXISTS(	SELECT 1
		            		FROM tbTaxMovements tmz	WITH (NOLOCK)
		            		WHERE	tmz.comp_id			= ct.comp_id
		            			AND tmz.ct_transaction	= ct.ct_transaction
		            			AND tmz.tax_id			= @tax_id
					)
		)
	AND ( @strCUIT		= '' OR ts.supp_taxNumber LIKE '%' + @strCUIT + '%')
	AND CASE
	        WHEN @country_id = -1 AND	@state_id		= -1					THEN 1
	        WHEN						ct.state_id		= @state_id				THEN 1
	        WHEN @state_id   = -1 AND   ct.country_id	= @country_id			THEN 1
	        ELSE 0
	    END = 1
	AND (ttr.supp_id IS NOT NULL OR @bitAllSuppliers = 'True')  -- verifica filtro de Proveedores

--==
--and ct.ct_transaction between 26993 AND 26993
--==
	GROUP BY CT.ct_transaction,ct_date,ct_TaxDate,ts.supp_name,ts.supp_taxNumber,vwctp.sd_isCredit,vwctp.sd_isReceipt,CT.ct_subtotal,ct.sd_id,ct.ct_CAI,ct.ct_CAIDate,tba.ba_desc,tba.ba_taxNumber,tb.bra_TaxEngineOverPurchase_ShowTaxDate,ct_kindof,ct_pointOfSale,ct_docNumber,tfc.fc_desc,TSB.supp_name,tsb.comp_id,tsb.supp_taxNumber
	ORDER BY CT.ct_transaction


	CREATE INDEX #tmpCommercialTransactionsIndex_I ON #tmpCommercialTransactions(ct_transaction)


	-- -------------------------------------------------------------
	-- Borrar Todas las OP que no tengan descuento gravado con IVA
	-- OJO, Idem en Temporal mas Abajo!
	-- -------------------------------------------------------------
	IF @ten_sdIdGroup = 1
	BEGIN
		DELETE FROM #tmpCommercialTransactions
			FROM #tmpCommercialTransactions tmp
			INNER JOIN tbCommercialTransactions tct								WITH (NOLOCK)
				ON		tct.comp_id			= @comp_id
					AND tct.ct_transaction	= tmp.ct_transaction
			INNER JOIN tbCommercialTransactionsPaymentsAdditionals tctpa		WITH (NOLOCK)
				ON		tctpa.comp_id		= tct.comp_id
					AND tctpa.ct_transaction= tct.ct_transaction
			INNER JOIN tbTaxName ttn											WITH (NOLOCK)
				ON		ttn.comp_id			= tct.comp_id
					AND ttn.tax_id			= tctpa.tax_id4Discount
			WHERE ttn.tax_percentage = 0
				AND tct.sd_id IN (6,13,106)
	END
	-- -------------------------------------------------------------





	/*Aca llamamos al STORED PROCEDURE que maneja toda la logica de insersion en la temporal*/
	EXEC spCommercialTransactions_getTaxEngineOverAll @comp_id, @ten_id


	INSERT INTO @tmpCommercialTransactions(ct_transaction)
		SELECT DISTINCT tmp.ct_transaction FROM #tmpFinalData tmp


	-- ------------------------------------------------
	-- IMpresion de Datos del Subdiario
	-- ------------------------------------------------
	SELECT	tmp.*,
			ISNULL(@page_index,0) [page_index],
			tct.sd_id,
			tct.ct_kindOf,
			tct.ct_pointOfSale,
			tct.ct_docNumber,
			tct.ct_date										[tra_Date],
			tct.ct_taxDate									[tra_TaxDate]
		FROM #tmpFinalData	tmp
		INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
		ON	tct.comp_id = @comp_id			AND
			tct.ct_transaction = tmp.ct_transaction
		ORDER BY tmp.ct_Date,tmp.[DOCUMENT]
	-- ------------------------------------------------





	exec [spReports_getData2] @comp_id,@intBranch4Lang, @lang_id, @ten_id, @page_id

	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id


	SELECT	(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 529 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = @fun_id )			[params1],

			(	SELECT tov.optval_desc 	FROM dbo.tbsysOptionsValues tov
				WHERE tov.lang_id = @lang_id AND tov.optval_class = 43 AND tov.optval_id = 9 )									[params2],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 638 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params3],

			CASE @ten_id WHEN -1 THEN
				(SELECT tut.utexts_desc	FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 2 )
			ELSE
				(SELECT tten.ten_desc	FROM tbTaxEngineName tten WHERE tten.ten_id = @ten_id )
			END																													[params4],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 177 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params5],

				@datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))	[params6],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 384 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params7],

				@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))		[params8],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 639 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params9],

			CASE @brag_id WHEN -1 THEN
				(SELECT	tut.utexts_desc	FROM tbsysUniqueTexts tut	WHERE tut.lang_id=@lang_id AND tut.utexts_id = 2 )
			ELSE
				(SELECT tbg.brag_desc	FROM tbBranchGroup tbg		WHERE tbg.brag_id = @brag_id )
			END																													[params10],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 28 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )				[params11],

			CASE @bra_id WHEN -1 THEN
				(SELECT	tut.utexts_desc	FROM tbsysUniqueTexts tut	WHERE tut.lang_id = @lang_id AND tut.utexts_id = 1 )
			ELSE
				(SELECT tb.bra_desc		FROM tbBranch tb			WHERE tb.bra_id = @bra_id )
			END																													[params12],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 577 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )			[params13],

			CASE @tax_id WHEN -1 THEN
				(SELECT	tut.utexts_desc	FROM tbsysUniqueTexts tut	WHERE tut.lang_id = @lang_id AND tut.utexts_id = 1 )
			ELSE
				(SELECT ttn.tax_desc	FROM tbTaxName ttn			WHERE ttn.tax_id = @tax_id)
			END																													[params14]



-- (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1))

	SELECT	DISTINCT
			CT.ct_transaction,
			CT.ct_date,
			TS.supp_taxNumber																																		[Number],
			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,CT.ct_transaction)																			[Comprobante],
			CASE WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN CT.ct_subtotal ELSE CT.ct_subtotal * -1 END		[ct_subtotal],
			CASE
				WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN 'False'
				ELSE 'True'
			END																																						[sd_isCredit],
			tm.tm_transaction,
			tfc.fc_desc,
			td.sd_desc,
			ct.ct_kindOf,
  			isnull(ISNULL(tn.tax_desc, ttent.tent_columnName),'*')																									[tax_desc],
			CASE	WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN 1
					ELSE -1
			END																																						[PlusOrMinus],
			CASE WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN cast(ISNULL(tm.tm_total,0) AS DECIMAL(19,2))
				 ELSE (ISNULL(tm.tm_total,0   ) * -1)
			END																																						[taxAnt],
			CASE
				WHEN (vwctp.sd_isCredit = 'false' OR (vwctp.sd_isReceipt = 'True' AND @ten_sdIdGroup = 1)) THEN ISNULL(tm.tm_subtotal,0)
				ELSE (ISNULL(tm.tm_subtotal,0) * -1)
			END																												[gravadoAnt],
			CAST(0 AS DECIMAL(19,2))																						[tax],
			CAST(0 AS DECIMAL(19,2))																						[gravado],
			CAST(0 AS DECIMAL(19,2))																						[nogravado],
			NEWID()																											[Id],
			tm.tax_id		[tax_id],	/*tn.tax_id MOS 05-2017*/
			ct.sd_id,
			tm.tax_id																										[Only4Order]

	INTO	#tmp1

	FROM 	dbo.tbCommercialTransactions							CT								WITH (NOLOCK)

			INNER JOIN @tmpCommercialTransactions kkk
				ON kkk.ct_transaction = CT.ct_transaction

			LEFT JOIN #tmpFinalData fd																WITH (NOLOCK)
			ON fd.ct_transaction = CT.ct_transaction

			INNER JOIN dbo.vwCommercialTransactions_forPurchase_TaxEngine		vwctp				WITH (NOLOCK)
			ON 	vwctp.ct_Transaction	= CT.ct_transaction
			AND vwctp.bra_id			= CT.bra_id
			AND vwctp.comp_id			= CT.comp_id
			--AND vwctp.sd_isTaxable		= 'True'

			LEFT JOIN tbTaxMovements								TM								WITH (NOLOCK)
			ON 	TM.comp_id				= CT.comp_id
			AND TM.bra_id				= CT.bra_id
			AND TM.ct_transaction		= CT.ct_transaction
			AND ((@ten_sdIdGroup = 1 AND not ct.sd_id IN (6,13,106)) OR (@ten_sdIdGroup <> 1 ))

			INNER JOIN tbUsers4BranchFilter							vubf							WITH (NOLOCK)
			ON  vubf.comp_id			= CT.comp_id
			AND vubf.bra_id				= CT.bra_id
			AND vubf.[user_id]			= @user_id

			left JOIN tbSupplier									TS								WITH (NOLOCK)
			ON	TS.comp_id				= CT.comp_id
			AND TS.supp_id				= CT.supp_id


			LEFT JOIN dbo.[tbTaxName]								tn								WITH (NOLOCK)
			on	tn.comp_id				= TM.comp_id
			and tn.tax_id				= TM.tax_id
			and tn.tax_class			= 1


			LEFT JOIN tbsysFiscalClass								tfc								WITH (NOLOCK)
			ON	tfc.fc_id				= TS.fc_id

			LEFT JOIN tbsysDocuments								td								WITH (NOLOCK)
			ON	td.sd_id				= CT.sd_id

			LEFT JOIN tbTaxEngineName_Taxes							ttent							WITH (NOLOCK)
			ON	ttent.comp_id			= CT.comp_id
			AND ttent.tax_id			= TM.tax_id
			AND ttent.ten_id			= @ten_id


	WHERE	CT.comp_id	= @comp_id
	AND 	CT.ct_taxDate between @datefrom and @dateto
	AND 	((@brag_id	= -1
				AND (@bra_id = -1 OR CT.bra_id = @bra_id)) OR
			(@brag_id <> -1
				and CT.bra_id IN (SELECT bgd.bra_id
								  FROM tbBranchGroupDetail bgd
								  WHERE bgd.brag_id = @brag_id)))

	AND		(
			 (@ten_sdIdGroup = 1 and (vwctp.sd_isTaxable	= 'True'  OR vwctp.sd_isReceipt = 'True' AND ct.ct_discount <> 0)) OR
			 (@ten_sdIdGroup = 2 and vwctp.sd_isReceipt		= 'True') OR
			 (@ten_sdIdGroup = 3 and vwctp.sd_isReceipt		= 'True'))

	ORDER BY CT.ct_transaction

	DECLARE @intRowCount AS INT
	SET @intRowCount = @@ROWCOUNT


	-- -------------------------------------------------------------
	-- Borrar Todas las OP que no tengan descuento gravado con IVA
	-- OJO, Idem en Temporal mas Abajo!
	-- -------------------------------------------------------------
	IF @ten_sdIdGroup = 1
	BEGIN
		DELETE FROM #tmp1
			FROM #tmp1 tmp
			INNER JOIN tbCommercialTransactions tct									WITH (NOLOCK)
				ON		tct.comp_id			= @comp_id
					AND tct.ct_transaction	= tmp.ct_transaction
			INNER JOIN tbCommercialTransactionsPaymentsAdditionals tctpa			WITH (NOLOCK)
				ON		tctpa.comp_id		= tct.comp_id
					AND tctpa.ct_transaction= tct.ct_transaction
			INNER JOIN tbTaxName ttn												WITH (NOLOCK)
				ON		ttn.comp_id			= tct.comp_id
					AND ttn.tax_id			= tctpa.tax_id4Discount
			WHERE ttn.tax_percentage = 0
				AND tct.sd_id IN (6,13,106)
	END
	-- -------------------------------------------------------------


--==
--select '#tmpFinalData',* from #tmpFinalData
--==


	-- MOS  08-2010
	-- -----------------------------------------------------------------------
	-- Pone los netos NO Grabados en el resumen
	-- Se genera en CERO arriba para que no se dupliquen en todas las filas
	-- -----------------------------------------------------------------------
	DECLARE @curCT_Transaction  AS INT
	DECLARE @curLastTransaction AS INT

	DECLARE @curTM_Transaction  AS INT
	DECLARE @curLTMTransaction  AS INT

	DECLARE @curCT_TaxId		AS INT
	DECLARE @curLastTaxId		AS INT

	DECLARE @curTCT_TaxId		AS INT
	DECLARE @curTLastTaxId		AS INT



	DECLARE @curCT_Id		    AS UNIQUEIDENTIFIER
	SET @curLastTransaction = 0
	SET @curLTMTransaction  = 0
	SET @curLastTaxId		= 0
	DECLARE curTMP1 CURSOR LOCAL FAST_FORWARD FOR
									SELECT	ct_transaction,
											Id,
											tm_transaction,
											Tmp.tax_id,
											Tmp.tax_id
										FROM #tmp1 Tmp
										Left JOIN tbTaxName ttn
											ON	ttn.comp_id = @comp_id	 AND
												ttn.tax_id  = Tmp.tax_Id
										ORDER BY Tmp.ct_transaction,IsNull(ttn.tax_class,9999999),ttn.tax_id


	OPEN curTMP1
	FETCH NEXT FROM curTMP1 INTO @curCT_Transaction,@curCT_Id,@curTM_Transaction,@curCT_TaxId,@curTCT_TaxId
	WHILE @@FETCH_STATUS = 0
	BEGIN



		IF @curCT_Transaction <> @curLastTransaction or @curCT_TaxId <> @curLastTaxId
			BEGIN

				IF @curCT_Transaction <> @curLastTransaction
					BEGIN

						UPDATE #tmp1
						SET nogravado = isnull((SELECT Sum(isnull(FD1.nogravado /* * Tmp1.PlusOrMinus*/,0))
													FROM #tmpFinalData FD1
													inner join #tmp1 Tmp1
														on	Tmp1.ID				= @curCT_Id
													WHERE	FD1.ct_transaction	= @curCT_Transaction
													GROUP BY FD1.ct_transaction),0)

						WHERE ID = @curCT_Id

					END


				SET @curLastTransaction = @curCT_Transaction
				SET @curLastTaxId		= @curCT_TaxId



				UPDATE #tmp1
--				SET nogravado = isnull((SELECT Sum(isnull(FD1.nogravado /** Tmp1.PlusOrMinus*/,0))
--											FROM #tmpFinalData FD1
--											inner join #tmp1 Tmp1
--												on	Tmp1.ID				= @curCT_Id
--											WHERE	FD1.ct_transaction	= @curCT_Transaction
--											GROUP BY FD1.ct_transaction),0),

					SET gravado   = isnull((

										SELECT IsNull(SUM(ttm.tm_subtotal *
																			CASE
																				WHEN tct.sd_id IN (103,106) THEN -1
																				ELSE 1
																			END
																			) ,0)
											FROM tbTaxMovements ttm										WITH (NOLOCK)
											INNER JOIN tbCommercialTransactions tct						WITH (NOLOCK)
												ON		tct.comp_id			= ttm.comp_id
													AND tct.ct_transaction	= ttm.ct_transaction
											WHERE	ttm.comp_id			= @comp_id
												AND ttm.ct_transaction	= @curCT_Transaction
												AND ttm.tax_id			= @curTCT_TaxId
											GROUP BY ttm.comp_id,ttm.ct_transaction,ttm.tax_id

										),0)
				WHERE ID = @curCT_Id AND sd_id NOT IN (140,141,142, /*Nuevo Extracto Bancario*/ 143,144)
			END

		IF @curTM_Transaction <> @curLTMTransaction or @curTCT_TaxId <> @curTLastTaxId
			BEGIN
				SET @curLTMTransaction = @curTM_Transaction
				SET @curTLastTaxId	   = @curTCT_TaxId
				UPDATE #tmp1
				SET tax = isnull((	SELECT taxAnt /** PlusOrMinus */
										FROM #tmp1
				                  		WHERE #tmp1.Id = @curCT_Id),0)
				WHERE ID = @curCT_Id --NO!AND sd_id NOT IN (140,141,142)
			END

		FETCH NEXT FROM curTMP1 INTO @curCT_Transaction,@curCT_Id,@curTM_Transaction,@curCT_TaxId,@curTCT_TaxId

	END
	CLOSE curTMP1
	DEALLOCATE curTMP1



	-- ------------------------------------------------------
	-- Graba Neto de Descuentos por Recibo u Ordenes de Pago
	-- ------------------------------------------------------
	UPDATE #tmp1
		SET tax = (tfd.total - tfd.gravado),
			gravado = tfd.gravado
		FROM #tmp1				 tmp
		INNER JOIN #tmpFinalData tfd
			ON tfd.ct_transaction		= tmp.ct_transaction
		INNER JOIN tbCommercialTransactions tct							WITH (NOLOCK)
			ON		tct.comp_id			= @comp_id
				AND tct.ct_transaction	= tmp.ct_transaction
		INNER JOIN tbCommercialTransactionsPaymentsAdditionals tctpa	WITH (NOLOCK)
			ON		tctpa.comp_id			= tct.comp_id
				AND tctpa.ct_transaction	= tct.ct_transaction
		WHERE		@ten_sdIdGroup = 1
				AND tct.sd_id IN (6,13,106)
	-- ------------------------------------------------------




	-- ------------------------------------------------------
	-- Actualiza para Transacciones Bancarias y Liq.T.Credito
	-- ------------------------------------------------------
	SELECT * -- Para que no de ambiguous abajo
		INTO #tmpBanking
		FROM #tmp1 tt
		WHERE tt.sd_id IN (140,141,142,/*Nuevo Extracto Bancario*/ 143,144)

	UPDATE #tmp1
		SET gravado		=	CASE
								WHEN A1.tm_transaction = A3.tm_transaction THEN A2.gravado
								ELSE 0
							END,
			nogravado	=	CASE
								WHEN A1.tm_transaction = A3.tm_transaction THEN (A2.nogravado + A2.exento )
								ELSE 0
							END
	FROM #tmp1					A1
	INNER JOIN #tmpFinalData	A2
		ON A2.ct_transaction = A1.ct_transaction
	INNER JOIN #tmpBanking	as		A3					-- Esto se hace para que no sume si es que tiene mas de un impuesto
		ON	A3.ct_transaction = A1.ct_transaction
	WHERE A1.sd_id IN (140,141,142,/*Nuevo Extracto Bancario*/ 143,144)
	DROP TABLE #tmpBanking
	-- ------------------------------------------------------



--	--SELECT ' --------------'
--	SELECT ' ****************************'
	--SELECT * FROM #tmpFinalData
--	--SELECT ' --------------'

--SELECT * FROM #tmpFinalData
--SELECT 'Help1:',* FROM #tmp1

	-- -----------------------------------------------------------------------

	IF @intRowCount > 0
		BEGIN

			-- ----------------------------------------------------------------------
			-- Prepara Resumen
			-- ----------------------------------------------------------------------
			SELECT	tmp.fc_desc		,
					tmp.sd_desc		,
					tmp.ct_kindOf	,
					tmp.tax_desc	,
  					sum(tmp.tax)													[tax],
  					CASE WHEN sum(tmp.tax) <> 0 THEN SUM(tmp.gravado)	ELSE 0 END	[gravado],
  					SUM([nogravado])												[nogravado],
  					CASE
  						WHEN tmp.sd_id IN (140,141,142,/*Nuevo Extracto Bancario*/ 143,144) THEN -1
  						ELSE tct.state_id
  					end																[state_id],
  					ISNULL(tba.ba_desc,'')											[ba_Desc]
			INTO	#tmp2
			FROM	#tmp1			tmp
			INNER JOIN tbCommercialTransactions tct							WITH (NOLOCK)
				ON tct.comp_id				= @comp_id
					AND tct.ct_transaction	= tmp.ct_transaction
			LEFT JOIN tbBankingAccounts tba									WITH (NOLOCK)
				ON	tba.comp_id = tct.comp_id AND
					tba.ba_id	= tct.ba_id
			WHERE	NOT tmp.tax_desc IS NULL
			GROUP BY	tmp.fc_desc,
  						tmp.sd_desc,
  						tmp.ct_kindOf,
  						tmp.tax_desc,
  						tct.state_id,
  						tmp.sd_id,
  						tba.ba_desc



			-- ----------------------------------------------------------------------
			-- Resumen Uno
			-- ----------------------------------------------------------------------

  			SELECT	fc_desc		,
  					sd_desc		,
  					ct_kindOf	,
  					tax_desc	,
  					tax	[total]	,
  					[gravado]	,
  					[nogravado]
  			FROM	#tmp2
  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0

			-- ----------------------------------------------------------------------
			-- Resumen DOS
			-- ----------------------------------------------------------------------

			SELECT
				CASE
					WHEN tmp.state_id = -1 THEN 'Banking . . .'
					ELSE ts.state_desc
				end																	[state_desc],
				sum(Tmp.tax)														[total],
  				CASE WHEN sum(Tmp.tax) <> 0 THEN SUM(Tmp.gravado)	ELSE 0 END		[gravado],
  				SUM(Tmp.nogravado)													[nogravado]

			FROM #tmp2 Tmp

				LEFT JOIN tbsysState ts
				ON	ts.state_id = Tmp.state_id

  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0
			GROUP BY ts.state_desc,tmp.state_id

			-- ----------------------------------------------------------------------
			-- Resumen Tres
			-- ----------------------------------------------------------------------
  			SELECT
				tax_desc,
				SUM(#tmp2.tax)			[total],
				SUM(#tmp2.gravado)		[gravado],
				SUM(#tmp2.nogravado)	[nogravado]

  			FROM	#tmp2

  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0

  			GROUP BY tax_desc


			-- ----------------------------------------------------------------------
			-- Resumen Cuatro RESUMEN POR CONCEPTO DE COMPRAS
			-- ----------------------------------------------------------------------

			-- Obtiene Importes EXENTOS para restarlos del total de NETOS hallado
			DECLARE @decTotalesExentos AS DECIMAL(19,4)
			SELECT  @decTotalesExentos = SUM(IsNull(exento,0)) FROM #tmpFinalData
			--SELECT @decTotalesExentos

			-- Pone en una Temporal los Conceptos de compra hallados.-
			SELECT	ct.comp_id,
					CT.ct_transaction,
					ct.ct_subtotal,
					NULL		/*tpc1*/									[pucoId4itemTransaction],
					NULL													[it_transaction],
					tpcm.puco_id   /*tpc2*/								[pucoId4purchaseConcept],
					tpcm.pcm_id,
					0
																		[itemTransactionTotal],
					dbo.fnGetExchange2(ct.comp_id,tpcm.pcm_total * vwctp.PlusOrMinus,tpcm.curr_id,ct.curr_id_transaction,ct.curr_id4Exchange,ct.curr_id_transaction,CT.ct_curr_IdExchange,'false')
																		[purchaseConceptTotal],
					CONVERT(DECIMAL(19,4),0)							[netoGravado],
					CONVERT(DECIMAL(19,4),0)							[netoNoGravado],
					CONVERT(DECIMAL(19,4),0)							[Exento],
					0													[pucoId4Unique]

			INTO	#tmpRC
			FROM 	dbo.tbCommercialTransactions							CT				WITH (NOLOCK)
					INNER JOIN dbo.vwCommercialTransactions_forPurchase_TaxEngine /*vwCommercialTransactions_forPurchase*/		vwctp			WITH (NOLOCK)
						ON 	vwctp.ct_Transaction	= CT.ct_transaction
						AND vwctp.bra_id			= CT.bra_id
						AND vwctp.comp_id			= CT.comp_id
					INNER JOIN tbUsers4BranchFilter							vubf			WITH (NOLOCK)
						ON  vubf.comp_id			= CT.comp_id
						AND vubf.bra_id				= CT.bra_id
						AND vubf.[user_id]			= @user_id
					INNER JOIN tbSupplier									TS				WITH (NOLOCK)
						ON	TS.comp_id				= CT.comp_id
						AND TS.supp_id				= CT.supp_id
					LEFT JOIN tbsysFiscalClass								tfc				WITH (NOLOCK)
						ON	tfc.fc_id				= TS.fc_id
					LEFT JOIN tbsysDocuments								td				WITH (NOLOCK)
						ON	td.sd_id				= CT.sd_id
					LEFT JOIN tbPurchaseConceptMovements tpcm								WITH (NOLOCK)
						ON		tpcm.comp_id		= ct.comp_id
							AND tpcm.ct_transaction = ct.ct_transaction
			WHERE	CT.comp_id	= @comp_id
			AND 	CT.ct_taxDate between @datefrom and @dateto
			AND 	((@brag_id	= -1
						AND (@bra_id = -1 OR CT.bra_id = @bra_id)) OR
					(@brag_id <> -1
						and CT.bra_id IN (SELECT bgd.bra_id
										  FROM tbBranchGroupDetail bgd		WITH (NOLOCK)
										  WHERE bgd.brag_id = @brag_id)))
			AND		(
					 (@ten_sdIdGroup = 1 and (vwctp.sd_isTaxable	= 'True'  OR vwctp.sd_isReceipt = 'True' AND ct.ct_discount <> 0)) OR
					 (@ten_sdIdGroup = 2 and vwctp.sd_isReceipt		= 'True') OR
					 (@ten_sdIdGroup = 3 and vwctp.sd_isReceipt		= 'True'))
			--ORDER BY CT.ct_transaction


			UNION ALL

			-- Pone en una Temporal los Items de compra hallados.-
			SELECT	ct.comp_id,
					CT.ct_transaction,
					ct.ct_subtotal,
					tit.puco_id		/*tpc1*/							[pucoId4itemTransaction],
					tit.it_transaction,
					NULL  /*tpc2*/										[pucoId4purchaseConcept],
					NULL,
					tit.it_qty * tit.it_price *	vwctp.PlusOrMinus
																		[itemTransactionTotal],
					0													[purchaseConceptTotal],
					CONVERT(DECIMAL(19,4),0)							[netoGravado],
					CONVERT(DECIMAL(19,4),0)							[netoNoGravado],
					CONVERT(DECIMAL(19,4),0)							[Exento],
					0													[pucoId4Unique]

			FROM 	dbo.tbCommercialTransactions							CT				WITH (NOLOCK)
					INNER JOIN dbo.vwCommercialTransactions_forPurchase_TaxEngine /*vwCommercialTransactions_forPurchase*/		vwctp			WITH (NOLOCK)
						ON 	vwctp.ct_Transaction	= CT.ct_transaction
						AND vwctp.bra_id			= CT.bra_id
						AND vwctp.comp_id			= CT.comp_id
					INNER JOIN tbUsers4BranchFilter							vubf			WITH (NOLOCK)
						ON  vubf.comp_id			= CT.comp_id
						AND vubf.bra_id				= CT.bra_id
						AND vubf.[user_id]			= @user_id
					INNER JOIN tbSupplier									TS				WITH (NOLOCK)
						ON	TS.comp_id				= CT.comp_id
						AND TS.supp_id				= CT.supp_id
					LEFT JOIN tbsysFiscalClass								tfc				WITH (NOLOCK)
						ON	tfc.fc_id				= TS.fc_id
					LEFT JOIN tbsysDocuments								td				WITH (NOLOCK)
						ON	td.sd_id				= CT.sd_id
					LEFT JOIN tbItemTransactions tit										WITH (NOLOCK)
						ON		tit.comp_id			= ct.comp_id
							AND tit.ct_transaction	= ct.ct_transaction
			WHERE	CT.comp_id	= @comp_id
			AND 	CT.ct_taxDate between @datefrom and @dateto
			AND 	((@brag_id	= -1
						AND (@bra_id = -1 OR CT.bra_id = @bra_id)) OR
					(@brag_id <> -1
						and CT.bra_id IN (SELECT bgd.bra_id
										  FROM tbBranchGroupDetail bgd		WITH (NOLOCK)
										  WHERE bgd.brag_id = @brag_id)))
			AND		(
					 (@ten_sdIdGroup = 1 and (vwctp.sd_isTaxable	= 'True'  OR vwctp.sd_isReceipt = 'True' AND ct.ct_discount <> 0)) OR
					 (@ten_sdIdGroup = 2 and vwctp.sd_isReceipt		= 'True') OR
					 (@ten_sdIdGroup = 3 and vwctp.sd_isReceipt		= 'True'))
			ORDER BY CT.ct_transaction





--==
--select 'lll',* from #tmpRC
--==

			-- Lo pongo en otra temporal por si mas adelante hay que sacar el neto gravado y exento de cada uno
			-- De tener que hacerlo hay que recorrer la tabla #tmpRC y poner en los campos que se generaron para eso que ahora
			-- estan en CERO.
			-- Unifico el Concepto de compra para poder sumar agrupados.-
			UPDATE #tmpRC
				SET pucoId4Unique = CASE
										WHEN pucoId4itemTransaction IS NOT NULL THEN pucoId4itemTransaction
										WHEN pucoId4purchaseConcept IS NOT NULL THEN pucoId4purchaseConcept
										ELSE -1
									END

--==
--select '222',* from #tmpRC
--==

			SELECT
				dbo.fnStrPADR( ta.acc_code,20,' ') + ' ->' +	tpc.puco_desc 		[tax_desc],
				0																	[total],
				Convert(decimal(19,2),SUM(ISNULL(purchaseConceptTotal,0)))
				+
				Convert(decimal(19,2),SUM(ISNULL(ItemTransactionTotal,0)))			[gravado],
				0																	[nogravado]
				INTO #tmpRC2
				FROM #tmpRC						tmp
				Left JOIN tbPurchaseConcept tpc						WITH (NOLOCK)
					ON tpc.puco_id = tmp.pucoId4Unique
				LEFT JOIN tbAccountant ta							WITH (NOLOCK)
					ON ta.acc_count_id = tpc.acc_count_id
			GROUP BY tmp.pucoId4Unique,tpc.puco_desc,ta.acc_code

			-- Resta los importes EXENTOS ya que esto los incluye para que coincidan con el total de conceptos que los tiene incluidos.-
			INSERT INTO #tmpRC2 (gravado,total,nogravado,tax_desc) VALUES (-@decTotalesExentos,0,0,'Exentos')

			SELECT * FROM #tmpRC2
--==
--	SELECT SUM([gravado]) FROM #tmpRC2
--==




			-- ----------------------------------------------------------------------
			-- Resumen Cinco, por Comprobante
			-- ----------------------------------------------------------------------

  			SELECT
  					sd_desc		,
  					ct_kindOf	,
  					tax_desc	,
  					SUM(tax)		[total]	,
  					SUM(gravado)    [gravado],
  					SUM(nogravado)  [nogravado]
  			FROM	#tmp2
  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0
  			GROUP BY
  				  	sd_desc		,
  					ct_kindOf	,
  					tax_desc




			DROP TABLE #tmpRC2
			DROP TABLE #tmpRC


			--
			--  			SELECT
			--				tax_desc,
			--				SUM(#tmp2.tax)			[total],
			--				SUM(#tmp2.gravado)		[gravado],
			--				SUM(#tmp2.nogravado)	[nogravado]
			--  			FROM	#tmp2
			--  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0
			--  			GROUP BY tax_desc
			-- ----------------------------------------------------------------------



		END
	ELSE
		BEGIN
			SELECT	@message	[fc_desc]	,
					' '			[sd_desc]	,
					' '			[ct_kindOf]	,
					' '			[tax_desc]	,
					0.00		[tax]
		END
	/***************************************************************************************************************************************/


	delete dbo.tbTaxEngineTmp1 where guid = @guid
	delete dbo.tbTaxEngineTmp2 where guid = @guid


END
GO





-- NO SE USAAAAAAAAAAAAAAAAAAA, ver el 2

CREATE Procedure [dbo].[spCommercialTransactions_getReportTaxEngineOverSales]
(
			@comp_id		int,
			@lang_id		int,
			@page_id		int,

			--@ten_id			int,
			@datefrom		datetime,
			@dateto			datetime,
			@brag_id		int,
			@bra_id			int

)
as


set nocount on
set dateformat 'ymd'

/*
declare
			@comp_id		int,
			@lang_id		int,
			@page_id		int,
			--@ten_id			int,
			@datefrom		datetime,
			@dateto			datetime,
			@brag_id		int,
			@bra_id			int


Select
			@comp_id		=1,
			@lang_id		=2,
			@page_id		=10033,
			--@ten_id			=2,
			@datefrom		='2000-01-01',
			@dateto			='2008-12-31',
			@brag_id		=-1,
			@bra_id			=-1



drop table #tmpColBasicas
drop table #tmpColumna1
drop table #tmpFinal
--drop table #tmpColumna3
--drop table #tmpColumna4
--drop table #tmpColumna5
drop table #tmpColumnas
*/

/*---------------------Creacion de la temporal con las columnas base---------------------*/

--Esta tabla es la que se utiliza en el cursor que esta mas abajo

create table #tmpFinal		(ct_transaction int,
							 tax_id int,
							 orden int)


/*Tabla temporal que almacena los campos que son obligatorios*/

create table #tmpColBasicas (	comp_id			int,
							 	bra_id			int,
							 	ct_date			datetime,
								ct_transaction	int,
								Nombre			Varchar(200),
						   		CUIT			Varchar(20),
								Comprobante		Varchar(30),
								Subtotal		Decimal(18,6))


Insert Into [#tmpColBasicas] ([comp_id],
							  [bra_id],
							  [ct_date],
							  [ct_transaction],
					    	  [Nombre],
							  [CUIT],
							  [Comprobante],
							  [Subtotal])

SELECT	CT.comp_id,
		CT.bra_id,
		CT.ct_date,
		CT.ct_transaction,
		isnull(case CT.cust_id when NULL
				then S.supp_name
				else C.cust_name
				end, '-') [Nombre],
		isnull(case CT.cust_id when NULL
				then S.supp_taxNumber
				else C.cust_taxNumber
				end, '-') [CUIT],
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, CT.ct_transaction) [Comprobante],
		SUM(CT.ct_subtotal)					[ct_subtotal]

From	dbo.tbCommercialTransactions CT

		left join tbCustomer			C
		on CT.cust_id = c.cust_id

		left join tbSupplier			S
		on CT.supp_id = s.supp_id

		inner join dbo.vwCommercialTransactions_forSales	VWFS
		on	VWFS.ct_Transaction	= CT.ct_transaction
		and VWFS.sd_isTaxable	= 'True'

where	CT.comp_id		= @comp_id
and		CT.ct_date		between @datefrom and @dateto
and		((@brag_id = -1
			and (@bra_id = -1 or CT.bra_id = @bra_id)) or

		(@brag_id <> -1
			and CT.bra_id in (select bgd.bra_id
								from tbBranchGroupDetail bgd
								where bgd.brag_id = @brag_id)))

group by	CT.comp_id,
			CT.bra_id,
			CT.ct_date,
			CT.ct_transaction,
			cust_name,
			cust_taxNumber


--select * from #tmpColBasicas order by ct_transaction


/*----------------------------------------------------------------------*/




/*------------Creacion de la temporal con la Primer columna-------------*/

Select 	TM.ct_transaction,
		TM.tax_id,
		sum(TM.tm_total)	[tm_total],
		0					[Orden]

into	#tmpColumna1

from	tbTaxMovements TM

		inner join #tmpColBasicas		tmp
		on	TM.comp_id			= tmp.comp_id
		and	TM.bra_id			= tmp.bra_id
		and	TM.ct_transaction	= tmp.ct_transaction

		inner join dbo.[tbTaxName]		tn
		on	tn.comp_id			= TM.comp_id
		and tn.tax_id			= TM.tax_id
		and tn.tax_class		= 1


group by	TM.ct_transaction,
			TM.tax_id

--select * from #tmpColumna1 order by ct_transaction


/*--------------------------CursorTableFinal--------------------------*/

declare @ct_transaction_tmp		int
declare @ct_transaction			int
declare @tax_id					int
declare @orden					int


set @ct_transaction_tmp = -1

/*Cursor en donde se genera una tabla temporal en la cual se le asigna un
orden a cada Movimiento*/


declare cursor_CT_gRTEOS cursor for
	select	ct_transaction,
			tax_id,
			orden

	from	#tmpColumna1  tmp1

	order by ct_transaction

open cursor_CT_gRTEOS

FETCH NEXT FROM cursor_CT_gRTEOS
INTO	@ct_transaction,
		@tax_id,
		@orden

WHILE @@FETCH_STATUS = 0
BEGIN

	if @ct_transaction <> @ct_transaction_tmp --Corte de Control
	begin
		set @orden = 1
		set @ct_transaction_tmp = @ct_transaction
	end

	insert into #tmpFinal
		(ct_transaction, tax_id, orden)
	values
		(@ct_transaction, @tax_id, @orden)


	FETCH NEXT FROM cursor_CT_gRTEOS
	INTO	@ct_transaction,
			@tax_id,
			@orden

end

close cursor_CT_gRTEOS
deallocate cursor_CT_gRTEOS

--select * from #tmpColumna1 order by ct_transaction
--select * from #tmpFinal

/*---------------------------------------------------------------------------*/


/*Hay que declarar una tabla temporal por el total de las columnas que tenga */


/*Variables para el armado dinamico de las tablas/columnas/titulos*/
declare @innerjoins varchar(1000)
set @innerjoins = ' '
declare @fields varchar(1000)
set @fields = ' '
declare @char_tax_id varchar(4)
declare	@tax_id1 integer
declare @column_name varchar(100)


/*Cursor en donde se van insertando los valores en los campos pertinentes para
poder llenar las tablas temporales*/

declare cursor_taxes1 cursor for
	select	tax_id, tent_columnName
	from	dbo.tbTaxEngineName_Taxes
	order by tent_column


Create table #tmpColumnas ( ct_transaction int, tax_id int, total decimal(18,6), id int )


open cursor_taxes1


fetch cursor_taxes1
into @tax_id1, @column_name


WHILE @@FETCH_STATUS = 0
BEGIN

	set @char_tax_id = convert(varchar(4),@tax_id1)

	--exec('IF EXISTS (SELECT 1 FROM ##tmpColumna' + @char_tax_id + ') drop table ##tmpColumna' + @char_tax_id)

	--exec('Create table ##tmpColumna' + @char_tax_id + ' (ct_transaction int, tax_id int, total decimal(18,6))')

--' + @char_tax_id + '
	exec('insert into #tmpColumnas (ct_transaction, tax_id, total, id)
			Select 	TM.ct_transaction,
					TM.tax_id,
					sum(TM.tm_total)	[total],' + @char_tax_id + ' [id]
			from	tbTaxMovements TM

			inner join #tmpColBasicas		tmp
			on	TM.comp_id			= tmp.comp_id
			and	TM.bra_id			= tmp.bra_id
			and	TM.ct_transaction	= tmp.ct_transaction

			where	TM.tax_id	= ''' + @char_tax_id + ''' group by	TM.ct_transaction,	TM.tax_id')



/*Variable que va armando el JOIN del SELECT final a medida que va cargando las temporales*/
	set @innerjoins = @innerjoins + ' left join #tmpColumnas dos'+ @char_tax_id +
						' on dos' + @char_tax_id + '.ct_transaction = C.ct_transaction
						  and dos' + @char_tax_id + '.id = ' + @char_tax_id + '
						  and	F.orden				= 1 '


/*Variable que acumula los nombres de las COLUMNAS y asigna un 0 si el valor de la misma es NULO*/
	set @fields = @fields + ', isnull(dos' + @char_tax_id + '.total,0)[' + @column_name + ']'

	fetch cursor_taxes1
	into @tax_id1, @column_name

end

close cursor_taxes1
deallocate cursor_taxes1

--select * from ##tmpColumna3
--select * from ##tmpColumna4
--select * from ##tmpColumna5
--select @innerjoins [inner join loco]



/***********************************************
*    Select Final que arma la tabla general    *
*    en base a las tablas temporales		   *
*    que se generaron con anterioridad		   *
************************************************/

declare	@query2				varchar(8000)

set @query2 = 'select * from #tmpColBasicas'
--set @query2 = 'select	C.comp_id,
--		C.bra_id,
--		C.ct_transaction,
--		C.ct_date,
--		C.nombre,
--		C.CUIT,
--		C.Comprobante,
--		C.Subtotal,
--		O.tm_total,
--		F.orden ' + @fields + '
--from	#tmpColBasicas			C
--		inner join #tmpColumna1	O
--		on	O.ct_transaction	=	C.ct_transaction
--		inner join #tmpFinal	F
--		on	F.ct_transaction	=	C.ct_transaction
--		and	F.tax_id			=	O.tax_id ' +
--		@innerjoins +
--'order by C.ct_transaction, F.orden desc'
exec (@query2)


exec [spReports_getData3] @comp_id,@bra_id, @lang_id, @page_id





GO


-- --------------------------------------------------------------------------------------------------------------------
-- Version MOS :	06-2014
--					Se modifico el orden de calculo de neto asi como el sd_iscredit directo y no puesto fijo por sd_id
--                  02-2016   se pone la clase fiscal segun lo guardado en tbCommercisaltransactions y no lo que dice ahora el cliente.
-- --------------------------------------------------------------------------------------------------------------------

-- Agregue las columnas para RES - 09-2015


CREATE PROCEDURE [dbo].[spCommercialTransactions_getReportTaxEngineOverSales2]


(
	@comp_id		int,
	@lang_id		int,
	@page_id		int,

	@guid			uniqueidentifier,
	@ten_id			int,
	@datefrom		datetime,
	@dateto			datetime,
	@brag_id		int,
	@bra_id			Int,
	@tax_id			int,
	@country_id		int,
	@state_id		INT,
	@user_id		INT,
	@strCUIT		VARCHAR(30),
	@intBranch4Lang	INT,
	@page_index		INT,			--STL
	@guid_cust		VARCHAR(50)
)

AS



BEGIN

	set dateformat 'ymd'
    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------




	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------

	-- ------------------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------------------
	/*
	DECLARE 		@comp_id		int,
					@lang_id		int,
					@page_id		int,

					@guid			uniqueidentifier,
					@ten_id			int,
					@datefrom		datetime,
					@dateto			datetime,
					@brag_id		int,
					@bra_id			Int,
					@tax_id			int,
					@country_id		int,
					@state_id		INT,
					@user_id		INT,
					@strCUIT		VARCHAR(30),
					@intBranch4Lang	INT,
					@page_index		INT,
					@guid_cust		VARCHAR(50)

	SELECT 		@guid			='fd82d14d-7c3b-4bb8-a04c-511d3f4fe4b7',
				@comp_id		= 1,
				@lang_id		= 2,
				@page_id		= 10033,
				@ten_id			= 8,
				@datefrom		='2020-04-01',
				@dateto			='2020-04-30',
				@brag_id		= -1,
				@bra_id			= 31,
				@tax_id			=-1,
				@user_id		= 1,
				@strCUIT		= '',
					@intBranch4Lang	= 2,
					@page_index		 = -1,
					@country_id=-1,
					@state_id=-1,
					@guid_cust = newid()


	DROP TABLE #tmpFinalData
	DROP TABLE #tmpCommercialTransactions
	DROP TABLE #tmpColumns
	DROP TABLE #tmp1
	DROP TABLE #tmp2
	DROP TABLE #tmpColumnsNames

	DECLARE @ctTest AS INT
	--SET @ctTest = 610837
	*/
	-- ---------------------------------------------------------------------------------------------


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @lGuid_Cust AS UNIQUEIDENTIFIER
	SET @lGuid_Cust = CONVERT(UNIQUEIDENTIFIER,@guid_cust)
	DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Customer
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf		WITH (NOLOCK)
			WHERE tcf.sl_guid = @lGuid_Cust     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Customer
				SELECT tc.cust_id
				FROM tbCustomer tc	WITH (NOLOCK)
					WHERE tc.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

    -- -----------------------------------------------------------------------------
    -- Grupo de Sucursales
    -- -----------------------------------------------------------------------------
	DECLARE @tmpBranchs TABLE(bra_id INT PRIMARY KEY)
	IF @brag_id = -1
		BEGIN
			INSERT INTO @tmpBranchs(bra_id) SELECT DISTINCT tb.bra_id
												FROM tbBranch tb		WITH (NOLOCK)
												WHERE tb.comp_id	= @comp_id AND
													 (tb.bra_id		= @bra_id
														OR
													  @bra_id = -1)
		END
	ELSE
		BEGIN
			INSERT INTO @tmpBranchs(bra_id)
				SELECT tbgd.bra_id
					FROM tbBranchGroupDetail tbgd
					WHERE	tbgd.comp_id = @comp_id AND
							tbgd.brag_id = @brag_id
		END
    -- -----------------------------------------------------------------------------



	set	@datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	DECLARE @fun_id INT
	SET @fun_id = 1

	CREATE TABLE #tmpColumns (id INT IDENTITY, tent_column INT)

	INSERT INTO #tmpColumns		(tent_column)
	SELECT						tent_column
	FROM	tbTaxEngineName_Taxes ttent
	WHERE	ttent.comp_id	= @comp_id
	AND		ttent.ten_id	= @ten_id
	ORDER BY ttent.tent_column


	--SELECT * FROM #tmpColumns
	CREATE TABLE #tmpColumnsNames ( id INT IDENTITY, [colname] VARCHAR(100) )


	/*Creamos la tabla*/
	CREATE TABLE #tmpFinalData
					(
					ct_transaction		INT ,
					tmp_id				INT IDENTITY,
					ct_date				DATETIME,
					supp_name			VARCHAR(100),
					supp_number			VARCHAR(20),
					[document]			VARCHAR(100),

					ct_CAI				NVARCHAR(50), --STL 12/11/2010
					ct_CAIDate			DATETIME,

					gravado				DECIMAL(19,2) DEFAULT 0 NULL,
					nogravado			DECIMAL(19,2) DEFAULT 0	NULL,
					exento				DECIMAL(19,2) DEFAULT 0	NULL)

	CREATE INDEX #tmpFinalData_I	ON #tmpFinalData(ct_transaction)
	CREATE INDEX #tmpFinalData_II	ON #tmpFinalData(tmp_id)

	DECLARE	@column_name		VARCHAR(100),
			@tent_column		INT--,
			--@tent_isHidden		BIT



	DECLARE @message VARCHAR(100)
	SELECT @message = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 150 AND tut.lang_id = @lang_id




	/*Cursor que Modifica la tabla y le agrega las columnas de la TaxEngineName_Taxes*/
	DECLARE cursor_columns CURSOR LOCAL  FAST_FORWARD FOR
	SELECT	distinct
			ttent.tent_columnName,
			tmpc.id--,
			--ttent.tent_isHidden
	FROM	tbTaxMovements								ttm					WITH (NOLOCK)
			INNER JOIN tbTaxEngineName_Taxes			ttent				WITH (NOLOCK)
			ON	ttm.comp_id			= ttent.comp_id
			AND ttm.tax_id			= ttent.tax_id
			AND ttent.ten_id		= @ten_id
			INNER JOIN #tmpColumns						tmpc
			ON	ttent.tent_column	= tmpc.tent_column
	ORDER BY tmpc.id


	OPEN cursor_columns


	FETCH NEXT FROM cursor_columns
	INTO	@column_name,
			@tent_column--,
			--@tent_isHidden


	WHILE @@FETCH_STATUS = 0
	BEGIN

	--	IF isnull(@tent_isHidden,'false') = 'false'
	--	BEGIN
	--
			EXEC ('alter table #tmpFinalData add [Columna' + @tent_column + '] decimal(19,2) default 0')

			INSERT INTO #tmpColumnsNames (colname) VALUES ( '[Columna' + convert(varchar,@tent_column) + ']')
	--
	--	END


		FETCH NEXT FROM cursor_columns
		INTO	@column_name,
				@tent_column--,
				--@tent_isHidden

	END


	EXEC ('alter table #tmpFinalData add total decimal(19,2) default 0')


	CLOSE cursor_columns
	DEALLOCATE cursor_columns


	DECLARE @ten_sdIdGroup INT
	SELECT	@ten_sdIdGroup	= isnull(tten.ten_sdIdGroup,1)
		FROM	tbTaxEngineName tten
		WHERE	tten.comp_id	= @comp_id
		AND		tten.ten_id		= @ten_id


	DECLARE @tmpCommercialTransactions TABLE(ct_transaction INT PRIMARY KEY)


	/*Select del Stored Procedure Original que trae los datos de la COMMERCIAL TRANSACTIONS y los inserta en la tabla #tmpFinalData*/
	SELECT	CT.ct_transaction,
			CT.ct_date,
			' '																							[ct_CAI],
			ct.ct_CAIDate,
			SUBSTRING(TC.cust_name,1,30)																[Name],
			Tc.cust_taxNumber																			[Number],
			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,CT.ct_transaction)				[Comprobante],
			ct.ct_kindOf, ct.ct_pointOfSale, ct.ct_docNumber,
			CASE
				WHEN vwctp.sd_isCredit = 'false' THEN CT.ct_subtotal
				ELSE CT.ct_subtotal * -1
			END																							[ct_subtotal],
			vwctp.sd_isCredit																			[sd_isCredit],
			ct.sd_id,
			tfc.fc_desc

			INTO #tmpCommercialTransactions

	FROM 	dbo.tbCommercialTransactions							CT				WITH (NOLOCK)

			INNER JOIN @tmpBranchs tmpb
				ON tmpb.bra_id = ct.bra_id

			INNER JOIN @tblComplexFilter_Customer ttu
				ON ttu.cust_id = ct.cust_id

			INNER JOIN dbo.vwCommercialTransactions_forSales_TaxEngine		vwctp			WITH (NOLOCK)
			ON 	vwctp.ct_Transaction	= CT.ct_transaction
			AND vwctp.bra_id			= CT.bra_id
			AND vwctp.comp_id			= CT.comp_id

			LEFT JOIN tbTaxMovements								TM				WITH (NOLOCK)
			ON 	TM.comp_id				= CT.comp_id
			AND TM.bra_id				= CT.bra_id
			AND TM.ct_transaction		= CT.ct_transaction

			INNER JOIN tbUsers4BranchFilter							vubf			WITH (NOLOCK)
			ON  vubf.comp_id			= CT.comp_id
			AND vubf.bra_id				= CT.bra_id
			AND vubf.[user_id]			= @user_id

			INNER JOIN tbCustomer									TC				WITH (NOLOCK)
			ON	TC.comp_id				= CT.comp_id
			AND TC.cust_id				= CT.cust_id

			LEFT JOIN tbsysFiscalClass tfc
				ON tfc.fc_id = ct.fc_id		--tc.fc_id

			LEFT JOIN tbDocumentsFile tdf											WITH (NOLOCK)
				ON		tdf.comp_id = ct.comp_id
					AND tdf.df_id	= ct.df_id

	WHERE	CT.comp_id	= @comp_id
	AND 	CT.ct_date	between @datefrom and @dateto
	--AND 	((@brag_id	= -1
	--			AND (@bra_id = -1 OR CT.bra_id = @bra_id)) OR
	--		(@brag_id <> -1
	--			and CT.bra_id IN (SELECT bgd.bra_id
	--								  FROM tbBranchGroupDetail bgd			WITH (NOLOCK)
	--								  WHERE bgd.comp_id = @comp_id AND
	--										bgd.brag_id = @brag_id))
	--		)

	AND		((@ten_sdIdGroup = 1 and vwctp.sd_isTaxable		= 'True') OR
			 (@ten_sdIdGroup = 2 and vwctp.sd_isReceipt		= 'True') OR
			 (@ten_sdIdGroup = 3 and vwctp.sd_isReceipt		= 'True'))
	AND IsNull(tdf.df_excludereportsTaxEngine,'False')		= 'False'
	AND (
			 CASE
				WHEN @tax_id = -1						THEN 1
				WHEN EXISTS(	SELECT TOP 1 1
		            				FROM tbTaxMovements tmz							WITH (NOLOCK)
		            				WHERE	tmz.comp_id			= ct.comp_id
		            					AND tmz.ct_transaction	= ct.ct_transaction
		            					AND tmz.tax_id			= @tax_id
							)							THEN 1
				ELSE										 0
			 END = 1


			 --@tax_id = -1 OR
			 --EXISTS(	SELECT 1
		  --          		FROM tbTaxMovements tmz							WITH (NOLOCK)
		  --          		WHERE	tmz.comp_id			= ct.comp_id
		  --          			AND tmz.ct_transaction	= ct.ct_transaction
		  --          			AND tmz.tax_id			= @tax_id
				--	)
		)
	AND ( @strCUIT		= '' OR tc.cust_taxNumber LIKE '%' + @strCUIT + '%')
	AND CASE
	        WHEN @country_id = -1 AND	@state_id		= -1					THEN 1
	        WHEN						ct.state_id		= @state_id				THEN 1
	        WHEN @state_id   = -1 AND   ct.country_id	= @country_id			THEN 1
	        ELSE 0
	    END = 1



	--AND ct.ct_transaction IN ( 49333,49379)

	GROUP BY ct.ct_taxDate,ct.bra_id,ct.ct_pointOfSale,ct.ct_kindOf,ct.ct_docNumber,CT.ct_transaction,ct_date,TC.cust_name,TC.cust_taxNumber,vwctp.sd_isCredit,CT.ct_subtotal,ct.sd_id,ct.ct_CAI,ct.ct_CAIDate,ct_kindof,ct_pointOfSale,ct_docNumber,tfc.fc_desc
	ORDER BY CT.ct_transaction
	--ORDER BY ct.ct_taxDate,ct.bra_id,ct.ct_pointOfSale,ct.sd_id,ct.ct_kindOf,ct.ct_docNumber-- CT.ct_transaction


	CREATE INDEX #tmpCommercialTransactionsIndex_I ON #tmpCommercialTransactions(ct_transaction)

	/*Aca llamamos al STORED PROCEDURE que maneja toda la logica de insersion en la temporal*/
	EXEC spCommercialTransactions_getTaxEngineOverAll @comp_id, @ten_id


	INSERT INTO @tmpCommercialTransactions(ct_transaction)
		SELECT DISTINCT tmp.ct_transaction FROM #tmpFinalData tmp

	-- -----------------------------------------------------------------
	-- IMpresion del Reporte
	-- -----------------------------------------------------------------
	SELECT	tmp.*,
			ISNULL(@page_index,0) [page_index],
			tct.sd_id,
			tct.ct_kindOf,
			tct.ct_pointOfSale,
			tct.ct_docNumber,tfc.fc_desc,tct.country_id,tct.state_id


		FROM #tmpFinalData tmp
		INNER JOIN tbcommercialtransactions tct					WITH (NOLOCK)
			ON	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= tmp.ct_transaction
		INNER JOIN tbCustomer				tc					WITH (NOLOCK)
			ON	tc.comp_id = tct.comp_id AND
				tc.cust_id = tct.cust_id
		INNER JOIN tbsysFiscalClass			tfc					WITH (NOLOCK)
			ON tfc.fc_id = tct.fc_id --tc.fc_id
		ORDER BY tmp.ct_Date,tmp.[DOCUMENT]-- CT.ct_transaction
	-- -----------------------------------------------------------------


	exec [spReports_getData2] @comp_id,@intBranch4Lang,@lang_id, @ten_id, @page_id

	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id


	SELECT	(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 529 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = @fun_id )			[params1],

			(	SELECT tov.optval_desc 	FROM dbo.tbsysOptionsValues tov
				WHERE tov.lang_id = @lang_id AND tov.optval_class = 43 AND tov.optval_id = 8 )									[params2],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 638 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params3],

			CASE @ten_id WHEN -1 THEN
				(SELECT tut.utexts_desc	FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 2 )
			ELSE
				(SELECT tten.ten_desc	FROM tbTaxEngineName tten WHERE tten.ten_id = @ten_id )
			END																													[params4],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 177 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params5],

				@datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))	[params6],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 384 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params7],

				@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))		[params8],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 639 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )			[params9],

			CASE @brag_id WHEN -1 THEN
				(SELECT	tut.utexts_desc	FROM tbsysUniqueTexts tut	WHERE tut.lang_id=@lang_id AND tut.utexts_id = 2 )
			ELSE
				(SELECT tbg.brag_desc	FROM tbBranchGroup tbg		WHERE tbg.brag_id = @brag_id )
			END																													[params10],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 28 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )				[params11],

			CASE @bra_id WHEN -1 THEN
				(SELECT	tut.utexts_desc	FROM tbsysUniqueTexts tut	WHERE tut.lang_id = @lang_id AND tut.utexts_id = 1 )
			ELSE
				(SELECT tb.bra_desc		FROM tbBranch tb			WHERE tb.bra_id = @bra_id)
			END																													[params12],

			(	SELECT tswn.word_desc	FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 577 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )			[params13],

			CASE @tax_id WHEN -1 THEN
				(SELECT	tut.utexts_desc	FROM tbsysUniqueTexts tut	WHERE tut.lang_id = @lang_id AND tut.utexts_id = 1 )
			ELSE
				(SELECT ttn.tax_desc	FROM tbTaxName ttn			WHERE ttn.tax_id = @tax_id)
			END																													[params14]

	SELECT	DISTINCT
			CT.ct_transaction,
			CT.ct_date,
			TS.cust_taxNumber																			[Number],
			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,CT.ct_transaction)				[Comprobante],
			CASE
				WHEN vwctp.sd_isCredit = 'false' THEN CT.ct_subtotal
				ELSE CT.ct_subtotal * -1
			END																							[ct_subtotal],
			vwctp.sd_isCredit																			[sd_isCredit],
			tm.tm_transaction,
			tfc.fc_desc,
			td.sd_desc,
			ct.ct_kindOf,
  			isnull(ISNULL(tn.tax_desc, ttent.tent_columnName),'*')															[tax_desc],
			CASE WHEN vwctp.sd_isCredit = 'false' THEN 1						ELSE -1								 END	[PlusOrMinus],
			CASE WHEN vwctp.sd_isCredit = 'false' THEN ISNULL(tm.tm_total,0   ) ELSE (ISNULL(tm.tm_total,0   ) * -1) END	[taxAnt],
			CASE WHEN vwctp.sd_isCredit = 'false' THEN ISNULL(tm.tm_subtotal,0) ELSE (ISNULL(tm.tm_subtotal,0) * -1) END	[gravadoAnt],
			CAST(0 AS DECIMAL(19,4))	/*MOS 03-2017 cambio a 4 x cambio en tax_calculate de @inDecimals4Taxes*/			[tax],
			CAST(0 AS DECIMAL(19,2))																						[gravado],
			CAST(0 AS DECIMAL(19,2))																						[nogravado],
			CAST(fd.exento AS DECIMAL(19,2))																				[exento],
			NEWID()																											[Id],
			tn.tax_id																										[tax_id],
			ct.state_id,
			tm.tax_id																										[Only4Order]	-- PLs, NO SACARRRRR!!!!!!!!!

	INTO	#tmp1

	FROM 	dbo.tbCommercialTransactions							CT			WITH (NOLOCK)

			INNER JOIN @tmpCommercialTransactions kkk
				ON kkk.ct_transaction = CT.ct_transaction

			LEFT JOIN #tmpFinalData									fd			WITH (NOLOCK)
			ON fd.ct_transaction = CT.ct_transaction

			INNER JOIN dbo.vwCommercialTransactions_forSales_TaxEngine		vwctp		WITH (NOLOCK)
			ON 	vwctp.ct_Transaction	= CT.ct_transaction
			AND vwctp.bra_id			= CT.bra_id
			AND vwctp.comp_id			= CT.comp_id
			AND vwctp.sd_isTaxable		= 'True'

			LEFT JOIN tbTaxMovements								TM			WITH (NOLOCK)
			ON 	TM.comp_id				= CT.comp_id
			AND TM.bra_id				= CT.bra_id
			AND TM.ct_transaction		= CT.ct_transaction

			INNER JOIN tbUsers4BranchFilter							vubf		WITH (NOLOCK)
			ON  vubf.comp_id			= CT.comp_id
			AND vubf.bra_id				= CT.bra_id
			AND vubf.[user_id]			= @user_id

			INNER JOIN tbCustomer									TS			WITH (NOLOCK)
			ON	TS.comp_id				= CT.comp_id
			AND TS.cust_id				= CT.cust_id


			LEFT JOIN dbo.[tbTaxName]								tn			WITH (NOLOCK)
			on	tn.comp_id				= TM.comp_id
			and tn.tax_id				= TM.tax_id
			and tn.tax_class			= 1


			LEFT JOIN tbsysFiscalClass								tfc			WITH (NOLOCK)
			ON	tfc.fc_id				= ct.fc_id --TS.fc_id

			LEFT JOIN tbsysDocuments								td			WITH (NOLOCK)
			ON	td.sd_id				= CT.sd_id

			LEFT JOIN tbTaxEngineName_Taxes							ttent		WITH (NOLOCK)
			ON	ttent.comp_id			= CT.comp_id
			AND ttent.tax_id			= TM.tax_id
			AND ttent.ten_id			= @ten_id


	WHERE	CT.comp_id	= @comp_id
	AND 	CT.ct_taxDate between @datefrom and @dateto
	AND 	((@brag_id	= -1
				AND (@bra_id = -1 OR CT.bra_id = @bra_id)) OR
			(@brag_id <> -1
				and CT.bra_id IN (SELECT bgd.bra_id
									  FROM tbBranchGroupDetail bgd		WITH (NOLOCK)
									  WHERE bgd.brag_id = @brag_id)))

	AND		((@ten_sdIdGroup = 1 and vwctp.sd_isTaxable		= 'True') OR
			 (@ten_sdIdGroup = 2 and vwctp.sd_isReceipt		= 'True') OR
			 (@ten_sdIdGroup = 3 and vwctp.sd_isReceipt		= 'True'))


	ORDER BY CT.ct_transaction,tm.tax_id			-- Importante, NO SACARRRRRRRRRR.-

	DECLARE @intRowCount AS INT
	SET @intRowCount = @@ROWCOUNT



	CREATE NONCLUSTERED INDEX #tmpIndex1 ON #tmp1
						(
						ID
						)
						INCLUDE ( ct_transaction)
						WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]

	CREATE NONCLUSTERED INDEX #tmpIndex2 ON #tmp1
						(
						ct_transaction
						)
						INCLUDE ( ID)
						WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]





	-- MOS  08-2010
	-- -----------------------------------------------------------------------
	-- Pone los netos NO Grabados en el resumen
	-- Se genera en CERO arriba para que no se dupliquen en todas las filas
	-- -----------------------------------------------------------------------
	DECLARE @curCT_Transaction  AS INT
	DECLARE @curLastTransaction AS INT

	DECLARE @curTM_Transaction  AS INT
	DECLARE @curLTMTransaction  AS INT

	DECLARE @curCT_TaxId		AS INT
	DECLARE @curLastTaxId		AS INT

	DECLARE @curTCT_TaxId		AS INT
	DECLARE @curTLastTaxId		AS INT


	DECLARE @curCT_Id		    AS UNIQUEIDENTIFIER
	SET @curLastTransaction = 0
	SET @curLTMTransaction  = 0
	SET @curLastTaxId		= 0
	DECLARE curTMP1 CURSOR LOCAL  FAST_FORWARD FOR SELECT ct_transaction,Id,tm_transaction,tax_id,tax_id [id2]
												FROM #tmp1
												ORDER BY ct_transaction,
														 CASE
															WHEN tax_id IS NULL THEN	1
															else						0
														 END,
												-- MOS: 02-2020: NOOO, NO ANDA en VENTAS ASI	--	 tm_transaction,			--MOS: 01-2020 ATENCION, NO SACAR ya que esto varia el orden y puede hacer que ante quilombos de orden por temposales calcule diferentes los IMPUESTOS en diferentes ejecuciones del cursor.
														 tax_id
	OPEN curTMP1--
	FETCH NEXT FROM curTMP1 INTO @curCT_Transaction,@curCT_Id,@curTM_Transaction,@curCT_TaxId,@curTCT_TaxId
	WHILE @@FETCH_STATUS = 0
	BEGIN



		IF @curCT_Transaction <> @curLastTransaction or @curCT_TaxId <> @curLastTaxId
			BEGIN
				SET @curLastTransaction = @curCT_Transaction
				SET @curLastTaxId		= @curCT_TaxId

				UPDATE #tmp1
				SET nogravado = isnull((SELECT Sum(isnull(FD1.nogravado /** Tmp1.PlusOrMinus*/,0))
											FROM #tmpFinalData FD1
											inner join #tmp1 Tmp1
												on	Tmp1.ID				= @curCT_Id
											WHERE	FD1.ct_transaction	= @curCT_Transaction
											GROUP BY FD1.ct_transaction),0),
					exento	  = isnull((SELECT Sum(isnull(FD1.exento /** Tmp1.PlusOrMinus*/,0))
											FROM #tmpFinalData FD1
											inner join #tmp1 Tmp1
												on	Tmp1.ID				= @curCT_Id
											WHERE	FD1.ct_transaction	= @curCT_Transaction
											GROUP BY FD1.ct_transaction),0),
					gravado   = isnull((

										SELECT IsNull(SUM(ttm.tm_subtotal *
																			CASE
																				--WHEN tct.sd_id IN (3,6) THEN -1  --888
																				when sd.sd_isCredit = 'True' then -1
																				ELSE 1
																			END
																			) ,0)
											FROM tbTaxMovements ttm							WITH (NOLOCK)
											INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
												ON		tct.comp_id			= ttm.comp_id
													AND tct.ct_transaction	= ttm.ct_transaction
											inner join tbsysDocuments sd
												on sd.sd_id = tct.sd_id
											WHERE	ttm.comp_id			= @comp_id
												AND ttm.ct_transaction	= @curCT_Transaction
												AND ttm.tax_id			= @curTCT_TaxId
											GROUP BY ttm.comp_id,ttm.ct_transaction,ttm.tax_id

										),0)

					WHERE ID = @curCT_Id
			END

		IF @curTM_Transaction <> @curLTMTransaction or @curTCT_TaxId <> @curTLastTaxId
			BEGIN
				SET @curLTMTransaction = @curTM_Transaction
				SET @curTLastTaxId	   = @curTCT_TaxId
				UPDATE #tmp1
					SET tax = isnull((	SELECT taxAnt /** PlusOrMinus */
											FROM #tmp1
				                  			WHERE #tmp1.Id = @curCT_Id),0)
					WHERE ID = @curCT_Id
			END

		FETCH NEXT FROM curTMP1 INTO @curCT_Transaction,@curCT_Id,@curTM_Transaction,@curCT_TaxId,@curTCT_TaxId

	END
	CLOSE curTMP1
	DEALLOCATE curTMP1

	--SELECT * FROM #tmpFinalData
	--SELECT * FROM #tmp1

	-- -----------------------------------------------------------------------

	-- MOS 02-2020: Se puso porque ante algunos comprobantes ponia mal el importe NETO cuando habia mas de dos IVAS iguales en diferentes tm_transactios ya que el #tmp1 DISCRIMINA los tm_transaction x tema de orden en la re puta temporal.
	-- MOS 12-02-2020: NO ANDA ASI, se puso x el orden de arriba --UPDATE #tmp1 SET gravado = gravadoant


--==
--seleCT 'Ctrl1',* FROM #tmp1 --where ct_transaction = 610837
--==

	IF @intRowCount > 0
		BEGIN




			-- 2- Idem en OverAll  MOS 08-2014 para Gromanti
			-- -------------------------------------------------------
			-- Si es un comprobante de SOLO IMPUESTOS, pone en cero
			-- los netos.
			-- -------------------------------------------------------
			UPDATE #tmp1
				SET gravado		= 0,
					nogravado	= 0,
					exento		= 0
				FROM #tmp1 tmp
				INNER JOIN tbCommercialTransactions tct				WITH (NOLOCK)
					ON	tct.comp_id			= @comp_id AND
						tct.ct_transaction	= tmp.ct_transaction
				INNER JOIN tbDocumentsFile tdf						WITH (NOLOCK)
					ON	tdf.comp_id = tct.comp_id AND
						tdf.df_id	= tct.df_id
				WHERE	tdf.df_SaleOrder_EmmitionOnlyTaxes = 'True'
			-- -------------------------------------------------------




--SELECT 'FROM	#tmp1			tmp',* FROM	#tmp1			tmp



			-- ----------------------------------------------------------------------
			-- Prepara Resumen
			-- ----------------------------------------------------------------------
			SELECT	tmp.fc_desc		,
					tmp.sd_desc		,
					tmp.ct_kindOf	,
					tmp.tax_desc	,
  					sum(tmp.tax)													[tax],
  					CASE WHEN sum(tmp.tax) <> 0 THEN SUM(tmp.gravado)	ELSE 0 END	[gravado],
  					SUM([nogravado])												[nogravado],
  					SUM(
  						CASE		-- MOS 06-2020: Dohko, en la suc de EXENTOS si habia items con DOS renglones le duplicaba . Probar DOHKO,  suc 31 Abril 2020
  							WHEN exento = gravado THEN exento
  							ELSE 0
  						END
  						)													[exento],
  					tct.state_id
			INTO	#tmp2
			FROM	#tmp1			tmp
			INNER JOIN tbCommercialTransactions tct						WITH (NOLOCK)
				ON	tct.comp_id				= @comp_id	AND
					tct.ct_transaction		= tmp.ct_transaction
			WHERE	NOT tmp.tax_desc IS NULL
			GROUP BY	tmp.fc_desc,
  						tmp.sd_desc,
  						tmp.ct_kindOf,
  						tmp.tax_desc,
  						tmp.tax_id,  -- MOS 05-2017
  						tct.state_id











			-- ----------------------------------------------------------------------
			-- Resumen Uno
			-- ----------------------------------------------------------------------

  			SELECT	fc_desc		,
  					sd_desc		,
  					ct_kindOf	,
  					tax_desc	,
  					sum(tax)		[total]	,
  					SUM(gravado)	[gravado]	,
  					SUM(nogravado)	[nogravado],
  					SUM(exento)		[exento]
  			FROM	#tmp2
  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0 OR [exento] <> 0
  			GROUP BY fc_desc,sd_desc,ct_kindof,tax_desc

			-- ----------------------------------------------------------------------
			-- Resumen DOS, por Provincia
			-- ----------------------------------------------------------------------

			SELECT
				ts.state_desc,
				sum(Tmp.tax)														[total],
  				CASE WHEN sum(Tmp.tax) <> 0 THEN SUM(Tmp.gravado)	ELSE 0 END		[gravado],
  				SUM(Tmp.nogravado)													[nogravado],
  				SUM(Tmp.exento)														[exento]

			FROM #tmp2 Tmp

				LEFT JOIN tbsysState ts					WITH (NOLOCK)
				ON	ts.state_id = Tmp.state_id

  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0 OR [exento] <> 0
			GROUP BY ts.state_desc

			-- ----------------------------------------------------------------------
			-- Resumen Tres, por impuet y clase
			-- ----------------------------------------------------------------------

  			SELECT
				tax_desc,
				SUM(#tmp2.tax)			[total],
				SUM(#tmp2.gravado)		[gravado],
				SUM(#tmp2.nogravado)	[nogravado],
				SUM(#tmp2.exento)		[exento]

  			FROM	#tmp2

  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0 OR [exento] <> 0

  			GROUP BY tax_desc


			-- ----------------------------------------------------------------------
			-- Resumen Cuatro (No Usado Aun)
			-- ----------------------------------------------------------------------
  			SELECT
				'*'						[tax_desc],
				SUM(#tmp2.tax)			[total],
				SUM(#tmp2.gravado)		[gravado],
				SUM(#tmp2.nogravado)	[nogravado],
				SUM(#tmp2.exento)		[exento]

				INTO    #tmpRC
  				FROM	#tmp2

  				WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0 OR [exento] <> 0

			SELECT * FROM #tmpRC
			DROP TABLE #tmpRC
			-- ----------------------------------------------------------------------


			-- ----------------------------------------------------------------------
			-- Resumen Cinco, por Comprobante
			-- ----------------------------------------------------------------------

  			SELECT
  					sd_desc		,
  					ct_kindOf	,
  					tax_desc	,
  					SUM(tax)		[total]	,
  					SUM(gravado)    [gravado],
  					SUM(nogravado)  [nogravado],
  					SUM(exento)		[exento]
  			FROM	#tmp2
  			WHERE	[tax] <> 0 OR	[gravado] <> 0 OR [nogravado] <> 0 OR [exento] <> 0
  			GROUP BY
  				  	sd_desc		,
  					ct_kindOf	,
  					tax_desc
			-- ----------------------------------------------------------------------



			-- ----------------------------------------------------------------------
			-- Resumen 6, por Provincia e Impuesto  08-2020
			-- ----------------------------------------------------------------------
			SELECT
				ts.state_desc,
				sum(Tmp.tax)														[total],
  				CASE
  					WHEN sum(Tmp.tax) <> 0 THEN SUM(Tmp.gravado)
  					ELSE 0
  				END																	[gravado],
  				SUM(Tmp.nogravado)													[nogravado],
  				SUM(Tmp.exento)														[exento],
  				Tmp.tax_desc
				FROM #tmp2 Tmp
				LEFT JOIN tbsysState ts					WITH (NOLOCK)
					ON	ts.state_id = Tmp.state_id
  				WHERE	[tax]		<> 0 OR
  						[gravado]	<> 0 OR
  						[nogravado] <> 0 OR
  						[exento]	<> 0
				GROUP BY ts.state_desc,Tmp.tax_desc



				-- LEER ! ! !
				-- LEER ! ! !
				-- ATENCION: Si se agregan Sub Resumenes se debera agregar el vacio correspondiente MAS ABAJO ! ! !
				-- LEER ! ! !
				-- LEER ! ! !


		END
	ELSE
		-- No Hay Datos
		BEGIN

			-- ATENCION:  Si se agregan Sub Resumenes se DEBERA AGREGAR AQUI SI O SI
			--		      un SubResumen VACIO EQUIVALENTE ! ! !

			-- ----------------------------------------------------------------------
			-- Resumen Uno
			-- ----------------------------------------------------------------------
			SELECT	@message	[fc_desc]	,
					' '			[sd_desc]	,
					' '			[ct_kindOf]	,
					' '			[tax_desc]	,
					0			[total]	,
					0			[gravado],
					0			[nogravado],
					0			[exento]




			-- ----------------------------------------------------------------------
			-- Resumen DOS, por Provincia
			-- ----------------------------------------------------------------------

			SELECT
				''														[state_desc],
				0														[total],
  				0													  [gravado],
  				0													[nogravado],
  				0														[exento]



			-- ----------------------------------------------------------------------
			-- Resumen Tres, por impuet y clase
			-- ----------------------------------------------------------------------

  			SELECT
				''							[tax_desc],
				0							[total],
				0							[gravado],
				0							[nogravado],
				0							[exento]



			-- ----------------------------------------------------------------------
			-- Resumen Cuatro (No Usado Aun)
			-- ----------------------------------------------------------------------
  			SELECT
				'*'						[tax_desc],
				0						[total],
				0						[gravado],
				0						[nogravado],
				0						[exento]
			-- ----------------------------------------------------------------------


			-- ----------------------------------------------------------------------
			-- Resumen Cinco, por Comprobante
			-- ----------------------------------------------------------------------
  			SELECT
  					''				[sd_desc]		,
  					''				[ct_kindOf]	,
  					''				[tax_desc]	,
  					0				[total]	,
  					0				[gravado],
  					0				[nogravado],
  					0				[exento]
			-- ----------------------------------------------------------------------



			-- ----------------------------------------------------------------------
			-- Resumen 6, por Provincia e Impuesto  08-2020
			-- ----------------------------------------------------------------------
			SELECT
				''														[state_desc],
				0														[total],
  				0														[gravado],
  				0														[nogravado],
  				0														[exento],
  				''														[tax_desc]


		END
	/***************************************************************************************************************************************/


	delete dbo.tbTaxEngineTmp1 where guid = @guid
	delete dbo.tbTaxEngineTmp2 where guid = @guid


END
GO




CREATE procedure [dbo].[spCommercialTransactions_getReportTotalPayment]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,

	@datefrom			datetime,
	@dateto				datetime,
	@cust				int,
	@bra_id				int,
	@country_id			int,
	@state_id			INT,
	@optval_id			int,
	@OptionSupp			INT,
	@pro_id				INT,
--	@ba_id				INT,
	@guid				VARCHAR(50),
	@user_id			int,
	@intBranch4Lang		int
)
AS


BEGIN

    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------



	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	------------------------------------------------------------------------
	----------------------TESTING-------------------------------------------
	------------------------------------------------------------------------
	/*
	declare		@comp_id			int,
				@lang_id			int,
				@page_id			int,

				@datefrom			datetime,
				@dateto				datetime,
				@cust				int,
				@bra_id				int,
				@country_id			int,
				@state_id			INT,
				@optval_id			int,
				@OptionSupp			INT,
				@user_id			int,
				@intBranch4Lang		int,
				@guid				UNIQUEIDENTIFIER
	Select
				@comp_id			= 1,
				@lang_id			= 2,
				@page_id			= 10012,
				@optval_id			=-1,
				--@selection_id		=-1,
				@datefrom			='1900-01-01',
				@dateto				='2018-07-31',
				@cust				=-1,
				@bra_id				=1,
				@country_id			=-1,
				@state_id			=-1,
				@user_id			=3,
				@OptionSupp			= 1,
				@guid				= 'f2899339-8de8-463f-9f50-8ef42945d887'

*/
	------------------------------------------------------------------------
	------------------------------------------------------------------------
	------------------------------------------------------------------------

	--------------------------------------------------------------------------------------------------------------------------------
	--****ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION****
	--****  Si se modifica algo en la consulta principal hacerla en el subreporte tambien - Referencia : *2* y *3*
	--****ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION****
	---------------------------------------------------------------------------------------------------------------------------------


	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Supplier
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Supplier
				SELECT ts.supp_id
				FROM tbSupplier ts
					WHERE ts.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

	set	@datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	DECLARE @fun_id INT
	SET		@fun_id = 1



	Select	ts.supp_id			[cust_id],
			ts.supp_name        [cust_name],
			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
			tct.ct_date,
			--tct.ct_payDate,
			vph.Date											[ct_payDate],
			--vph.amount [ct_total],
			(vph.amount * vph.exchange) 							[ct_total],
			(tct.ct_Abalance * tct.ct_AcurrencyExchange)			[Balance],
			ISNULL(vph.[description],'') + ' ' + ISNULL(vph.[type],'')	[description],
			tc.curr_desc,
			tc.curr_symbol,
			tb.bra_desc,
			isnull(tctop.op_paymentTo,ts.supp_name)				[op_paymentTo],
			tct.ct_total										[Total],
			tct.ct_taxDate										[ct_taxDate]

	From	tbCommercialTransactions								tct

			INNER JOIN dbo.vwCommercialTransactions_forPurchase		vctfp
			on  tct.comp_id				= vctfp.comp_id
			and tct.bra_id				= vctfp.bra_id
			and tct.ct_transaction		= vctfp.ct_transaction
			and vctfp.sd_isReceipt		= 'True'
			and vctfp.sd_isInBalance	= 'True'

			INNER JOIN tbSupplier									ts
			ON	ts.comp_id				= tct.comp_id
			AND	ts.supp_id				= tct.supp_id

			INNER JOIN @tblComplexFilter_Supplier					tempSupplier
			ON tempSupplier.supp_id					= ts.supp_id

			INNER JOIN dbo.vwPaymentsHow							vph
			ON	vph.comp_id				= tct.comp_id
			AND vph.ct_transaction		= tct.ct_transaction
			AND vph.lang_id				= @lang_id

			INNER JOIN tbsysCurrency								tc
			ON	tc.curr_id				= tct.curr_id_transaction

			INNER JOIN tbBranch										tb
			ON	tb.comp_id				= tct.comp_id
			And tb.bra_id				= @bra_id

			INNER JOIN tbUsers4BranchFilter							vubf
			ON  vubf.comp_id			= tct.comp_id
			AND vubf.bra_id				= tct.bra_id
			AND vubf.[user_id]			= @user_id

			LEFT JOIN tbCommercialTransactionsOtherPayments			tctop
			ON	tctop.comp_id			= tct.comp_id				AND
				tctop.bra_id			= tct.bra_id				AND
				tctop.ct_transaction	= tct.ct_transaction


	WHERE 	 tct.comp_id		= @comp_id
	AND 	 tct.bra_id		    = @bra_id

	--and		 tct.ct_Abalance    <> 0	13-05-2010 MOH
	AND 	(@cust			    = -1 or tct.supp_id		= @cust)
	AND 	(@pro_id			= -1 or tct.pro_id		= @pro_id)
	AND 	 tct.ct_date		between  @datefrom	  and @dateto
	AND 	(@country_id	    = -1 or ts.country_id	= @country_id)
	AND 	(@state_id		    = -1 or ts.state_id		= @state_id)
	AND 	 tct.sd_id			= 106						--Pago a Proveedores
	AND     (@optval_id = -1							OR
			 @optval_id = 0		AND ct_Abalance <> 0	OR
			 @optval_id = 1		AND ct_Abalance =  0)

	AND     (@OptionSupp = 1				OR -- todos los proveedores
			 @OptionSupp = 2		AND IsNull(tb.bra_PaymentSupp_Id,1) <> ts.supp_id	OR -- proveedores
			 @OptionSupp = 3		AND IsNull(tb.bra_PaymentSupp_Id,1) = ts.supp_id)	   -- otros pagos
	AND		tct.sd_id = 106
	--@OptionSupp 1 - todos los proveedores
	--			  2 - proveedores
	--			  3 - otros pagos


	ORDER BY tct.ct_date, tct.ct_transaction			-- MOS 08.2016 Estaba con 1, Como Mierda ????



	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id




	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	select
	--		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
	--			 WHERE t.ctrl_id = 398
	--			 --AND t.[lang_id] = @lang_id
	--			 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params1],
	--
	--		CASE @selection_id WHEN -1 THEN
	--			(SELECT		tut.utexts_desc
	--				FROM	tbsysUniqueTexts tut
	--				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
	--		ELSE
	--			(SELECT		vsdc.sd_desc
	--				FROM	dbo.vwSysDocumentsCustomer vsdc
	--				WHERE	vsdc.sd_id = @selection_id)
	--		END																																	[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 177
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params1],

			@datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))					[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 384
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params3],

			@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))						[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 402
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =0)					[params5],

				CASE @cust WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT ts.supp_name
					 FROM	dbo.tbSupplier ts
					 WHERE	ts.supp_id  = @cust)
				END																																[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 57
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params7],

				CASE @country_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.country_desc
						FROM	dbo.tbsysCountry tc
						WHERE	tc.country_id = @country_id)
				END																																[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 59
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params9],

				CASE @state_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.state_desc
						FROM	dbo.tbsysState ts
						WHERE	ts.state_id = @state_id)
				END							[params10]		,

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 991
   		 --AND t.[lang_id] = @lang_id
   		 and t.[page_id] = @related_page_id
   		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params11],

		 CASE @optval_id WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		 ELSE
			(SELECT		tov.optval_desc
				FROM	tbsysOptionsValues tov
				WHERE	tov.lang_id = @lang_id
				AND     tov.optval_class = 80
				and		tov.optval_id = @optval_id)
		END																											[params12],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 2468
   		 --AND t.[lang_id] = @lang_id
   		 and t.[page_id] = @related_page_id
   		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params13],

		(SELECT		tov.optval_desc
				FROM	tbsysOptionsValues tov
				WHERE	tov.lang_id = @lang_id
				AND     tov.optval_class = 324
				and		tov.optval_id = @OptionSupp	)																[params14],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 4241
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params15],

				CASE @pro_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tp.pro_desc
					 FROM	tbProject tp
					 WHERE	tp.pro_id  = @pro_id)
				END																																[params16]




		  -- ---------------------------------------------------------------------------------------------------
		  /* SubReporte Detalle de Formas de Pago*/  --
		  -- ---------------------------------------------------------------------------------------------------
		  -- Referencia : *2* SI SE MODIFICA ESTE SUBQUERY HACERLO EN EL QUERY PRINCIPAL TAMBIEN



			SELECT
					CASE
		      			WHEN vph.Class=2 THEN vph.[description]  + ' * ' + tba.ba_desc
		      			WHEN vph.Class=6 THEN vph.[description]  + ' * ' + tba.ba_desc
		      			ELSE vph.[description]
		      		END					[description],
					sum(vph.amount)		[amount],
					vph.currency		[currency]


			From	tbCommercialTransactions								tct

					INNER JOIN dbo.vwCommercialTransactions_forPurchase		vctfp
					on  tct.comp_id				= vctfp.comp_id
					and tct.bra_id				= vctfp.bra_id
					and tct.ct_transaction		= vctfp.ct_transaction
					and vctfp.sd_isReceipt		= 'True'
					and vctfp.sd_isInBalance	= 'True'

					INNER JOIN tbSupplier									ts
					ON	ts.comp_id				= tct.comp_id
					AND	ts.supp_id				= tct.supp_id

					INNER JOIN @tblComplexFilter_Supplier					tempSupplier
					ON tempSupplier.supp_id					= ts.supp_id

					INNER JOIN dbo.vwPaymentsHow							vph
					ON	vph.comp_id				= tct.comp_id
					AND vph.lang_id				= @lang_id
					AND vph.ct_transaction		= tct.ct_transaction

					INNER JOIN tbsysCurrency								tc
					ON	tc.curr_id				= tct.curr_id_transaction

					INNER JOIN tbBranch										tb
					ON	tb.comp_id				= tct.comp_id
					And tb.bra_id				= @bra_id

					INNER JOIN tbUsers4BranchFilter							vubf
					ON  vubf.comp_id			= tct.comp_id
					AND vubf.bra_id				= tct.bra_id
					AND vubf.[user_id]			= @user_id

					LEFT JOIN tbBankingAccounts tba
						ON	vph.class			IN (2,6)			AND
							tba.comp_id			= vph.comp_id		AND
							tba.ba_id			= vph.GroupClass


			WHERE 	 tct.comp_id		= @comp_id
			AND 	 tct.bra_id		    = @bra_id
			AND 	(@cust			    = -1 or tct.supp_id		= @cust)
			AND 	 tct.ct_date		between  @datefrom	  and @dateto
			AND 	(@country_id	    = -1 or ts.country_id	= @country_id)
			AND 	(@state_id		    = -1 or ts.state_id		= @state_id)
			AND 	 tct.sd_id			= 106						--Pago a Proveedores
			AND     (@optval_id = -1							OR
					 @optval_id = 0		AND ct_Abalance <> 0	OR
					 @optval_id = 1		AND ct_Abalance =  0)

			AND     (@OptionSupp = 1				OR -- todos los proveedores
					 @OptionSupp = 2		AND IsNull(tb.bra_PaymentSupp_Id,1) <> ts.supp_id	OR -- proveedores
					 @OptionSupp = 3		AND IsNull(tb.bra_PaymentSupp_Id,1) = ts.supp_id)	   -- otros pagos
			AND		tct.sd_id = 106

			GROUP BY	vph.class,
						vph.GroupClass,
						vph.[description],
						vph.currency,
						tba.ba_desc

			ORDER BY 1



		 --  Referencia : *3* SI SE MODIFICA ESTE SUBQUERY HACERLO EN EL QUERY PRINCIPAL TAMBIEN
		 -- ---------------------------------------------------------------------------------------------------
		  /* Detalle de concepto por otros pagos*/  --
		  -- ---------------------------------------------------------------------------------------------------




			Select	tctopd.ctopd_desc		[ctopd_desc],
					sum(tctopd.ctopd_total) [ctopd_total],
					tpc.puco_desc			[puco_desc],
					ta.acc_desc				[acc_desc]


			From	tbCommercialTransactions								tct

					INNER JOIN dbo.vwCommercialTransactions_forPurchase		vctfp
					on  tct.comp_id				= vctfp.comp_id
					and tct.bra_id				= vctfp.bra_id
					and tct.ct_transaction		= vctfp.ct_transaction
					and vctfp.sd_isReceipt		= 'True'
					and vctfp.sd_isInBalance	= 'True'

					INNER JOIN tbCommercialTransactionsOtherPaymentsDetail tctopd
					ON	tctopd.comp_id			= tct.comp_id				AND
						tctopd.bra_id			= tct.bra_id				AND
						tctopd.ct_transaction	= tct.ct_transaction

					LEFT JOIN tbPurchaseConcept								tpc
					ON  tpc.comp_id			= tctopd.comp_id
					and tpc.puco_id			= tctopd.puco_id

					LEFT JOIN tbAccountant									ta
					ON	ta.comp_id			= tctopd.comp_id AND
						ta.acc_count_id		= tctopd.acc_count_id

					INNER JOIN tbSupplier									ts
					ON	ts.comp_id				= tct.comp_id
					AND	ts.supp_id				= tct.supp_id

					INNER JOIN @tblComplexFilter_Supplier					tempSupplier
					ON tempSupplier.supp_id					= ts.supp_id

					INNER JOIN tbsysCurrency								tc
					ON	tc.curr_id				= tct.curr_id_transaction

					INNER JOIN tbBranch										tb
					ON	tb.comp_id				= tct.comp_id
					And tb.bra_id				= @bra_id

					INNER JOIN tbUsers4BranchFilter							vubf
					ON  vubf.comp_id			= tct.comp_id
					AND vubf.bra_id				= tct.bra_id
					AND vubf.[user_id]			= @user_id


			WHERE 	 tct.comp_id		= @comp_id
			AND 	 tct.bra_id		    = @bra_id
			AND 	(@cust			    = -1 or tct.supp_id		= @cust)
			AND 	 tct.ct_date		between  @datefrom	  and @dateto
			AND 	(@country_id	    = -1 or ts.country_id	= @country_id)
			AND 	(@state_id		    = -1 or ts.state_id		= @state_id)
			AND 	 tct.sd_id			= 106						--Pago a Proveedores
			AND     (@optval_id = -1							OR
					 @optval_id = 0		AND ct_Abalance <> 0	OR
					 @optval_id = 1		AND ct_Abalance =  0)
			AND     (@OptionSupp = 1				OR -- todos los proveedores
					 @OptionSupp = 2		AND IsNull(tb.bra_PaymentSupp_Id,1) <> ts.supp_id	OR -- proveedores
					 @OptionSupp = 3		AND IsNull(tb.bra_PaymentSupp_Id,1) = ts.supp_id)	   -- otros pagos
			AND		tct.sd_id = 106

			GROUP BY	tctopd.ctopd_desc,tpc.puco_desc,ta.acc_desc

			ORDER BY 1



		  --Si se modifica algo en la consulta hacerla en el subreporte tambien - Referencia : *2* -
		  -- ---------------------------------------------------------------------------------------------------

END
GO




CREATE procedure [dbo].[spCommercialTransactions_getReportTotalPayment_NewFormat]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,

	@datefrom			datetime,
	@dateto				datetime,
	@cust				int,
	@bra_id				int,
	@country_id			int,
	@state_id			INT,
	@optval_id			int,
	@OptionSupp			INT,
	@pro_id				INT,
	@guid				VARCHAR(50),
	@user_id			int,
	@intBranch4Lang		int
)
AS


BEGIN

    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------



	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	------------------------------------------------------------------------
	----------------------TESTING-------------------------------------------
	------------------------------------------------------------------------
	/*
	declare		@comp_id			int,
				@lang_id			int,
				@page_id			int,

				@datefrom			datetime,
				@dateto				datetime,
				@cust				int,
				@bra_id				int,
				@country_id			int,
				@state_id			INT,
				@optval_id			int,
				@OptionSupp			INT,
				@user_id			int,
				@intBranch4Lang		int,
	@pro_id				INT,
				@guid				UNIQUEIDENTIFIER
	Select
				@comp_id			= 1,
				@lang_id			= 2,
				@page_id			= 10012,
				@optval_id			=-1,
				--@selection_id		=-1,
				@datefrom			='2016-06-01',
				@dateto				='2016-06-30',
				@cust				=-1,
				@bra_id				=1,
				@country_id			=-1,
				@state_id			=-1,
				@user_id			=1,
				@OptionSupp			= 1,@pro_id = -1,
				@guid				= 'f2899339-8de8-463f-9f50-8ef72945d887'
	*/
	------------------------------------------------------------------------
	------------------------------------------------------------------------
	------------------------------------------------------------------------

	--------------------------------------------------------------------------------------------------------------------------------
	--****ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION****
	--****  Si se modifica algo en la consulta principal hacerla en el subreporte tambien - Referencia : *2* y *3*
	--****ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION********ATENCION****
	---------------------------------------------------------------------------------------------------------------------------------


	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Supplier
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Supplier
				SELECT ts.supp_id
				FROM tbSupplier ts
					WHERE ts.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

	set	@datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	DECLARE @fun_id INT
	SET		@fun_id = 1



	Select	ts.supp_id			[cust_id],
			ts.supp_name        [cust_name],
			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
			tct.ct_date,
			--tct.ct_payDate,
		--	vph.Date											[ct_payDate],
			--vph.amount [ct_total],
		--	(vph.amount * vph.exchange)					[ct_total],
			(tct.ct_Abalance * tct.ct_AcurrencyExchange)		[Balance],
		--	vph.[description],
			tc.curr_desc,
			tc.curr_symbol,
			tb.bra_desc,
			isnull(tctop.op_paymentTo,ts.supp_name)				[op_paymentTo],
			tct.ct_total										[Total],
			tct.ct_taxDate										[ct_taxDate]

	From	tbCommercialTransactions								tct

			INNER JOIN dbo.vwCommercialTransactions_forPurchase		vctfp
			on  tct.comp_id				= vctfp.comp_id
			and tct.bra_id				= vctfp.bra_id
			and tct.ct_transaction		= vctfp.ct_transaction
			and vctfp.sd_isReceipt		= 'True'
			and vctfp.sd_isInBalance	= 'True'

			INNER JOIN tbSupplier									ts
			ON	ts.comp_id				= tct.comp_id
			AND	ts.supp_id				= tct.supp_id

			INNER JOIN @tblComplexFilter_Supplier					tempSupplier
			ON tempSupplier.supp_id					= ts.supp_id

			--INNER JOIN dbo.vwPaymentsHow							vph
			--ON	vph.comp_id				= tct.comp_id
			--AND vph.ct_transaction		= tct.ct_transaction
			--AND vph.lang_id				= @lang_id

			INNER JOIN tbsysCurrency								tc
			ON	tc.curr_id				= tct.curr_id_transaction

			INNER JOIN tbBranch										tb
			ON	tb.comp_id				= tct.comp_id
			And tb.bra_id				= @bra_id

			INNER JOIN tbUsers4BranchFilter							vubf
			ON  vubf.comp_id			= tct.comp_id
			AND vubf.bra_id				= tct.bra_id
			AND vubf.[user_id]			= @user_id

			LEFT JOIN tbCommercialTransactionsOtherPayments			tctop
			ON	tctop.comp_id			= tct.comp_id				AND
				tctop.bra_id			= tct.bra_id				AND
				tctop.ct_transaction	= tct.ct_transaction


	WHERE 	 tct.comp_id		= @comp_id
	AND 	 tct.bra_id		    = @bra_id
	--and		 tct.ct_Abalance    <> 0	13-05-2010 MOH
	AND 	(@cust			    = -1 or tct.supp_id		= @cust)
	AND 	(@pro_id			= -1 or tct.pro_id		= @pro_id)
	AND 	 tct.ct_date		between  @datefrom	  and @dateto
	AND 	(@country_id	    = -1 or ts.country_id	= @country_id)
	AND 	(@state_id		    = -1 or ts.state_id		= @state_id)
	AND 	 tct.sd_id			= 106						--Pago a Proveedores
	AND     (@optval_id = -1							OR
			 @optval_id = 0		AND ct_Abalance <> 0	OR
			 @optval_id = 1		AND ct_Abalance =  0)

	AND     (@OptionSupp = 1				OR -- todos los proveedores
			 @OptionSupp = 2		AND IsNull(tb.bra_PaymentSupp_Id,1) <> ts.supp_id	OR -- proveedores
			 @OptionSupp = 3		AND IsNull(tb.bra_PaymentSupp_Id,1) = ts.supp_id)	   -- otros pagos
	AND		tct.sd_id = 106
	--@OptionSupp 1 - todos los proveedores
	--			  2 - proveedores
	--			  3 - otros pagos


	ORDER BY tct.ct_date, tct.ct_transaction			-- MOS 08.2016 Estaba con 1, Como Mierda ????



	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id




	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	select
	--		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
	--			 WHERE t.ctrl_id = 398
	--			 --AND t.[lang_id] = @lang_id
	--			 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params1],
	--
	--		CASE @selection_id WHEN -1 THEN
	--			(SELECT		tut.utexts_desc
	--				FROM	tbsysUniqueTexts tut
	--				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
	--		ELSE
	--			(SELECT		vsdc.sd_desc
	--				FROM	dbo.vwSysDocumentsCustomer vsdc
	--				WHERE	vsdc.sd_id = @selection_id)
	--		END																																	[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 177
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params1],

			@datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))					[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 384
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params3],

			@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))						[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 402
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =0)					[params5],

				CASE @cust WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT ts.supp_name
					 FROM	dbo.tbSupplier ts
					 WHERE	ts.supp_id  = @cust)
				END																																[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 57
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params7],

				CASE @country_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.country_desc
						FROM	dbo.tbsysCountry tc
						WHERE	tc.country_id = @country_id)
				END																																[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 59
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params9],

				CASE @state_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.state_desc
						FROM	dbo.tbsysState ts
						WHERE	ts.state_id = @state_id)
				END							[params10]		,

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 991
   		 --AND t.[lang_id] = @lang_id
   		 and t.[page_id] = @related_page_id
   		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params11],

		 CASE @optval_id WHEN -1 THEN
			(SELECT		tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
		 ELSE
			(SELECT		tov.optval_desc
				FROM	tbsysOptionsValues tov
				WHERE	tov.lang_id = @lang_id
				AND     tov.optval_class = 80
				and		tov.optval_id = @optval_id)
		END																											[params12],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 2468
   		 --AND t.[lang_id] = @lang_id
   		 and t.[page_id] = @related_page_id
   		 and t.[type_id] = 1 AND t.fun_id =@fun_id)																	[params13],

		(SELECT		tov.optval_desc
				FROM	tbsysOptionsValues tov
				WHERE	tov.lang_id = @lang_id
				AND     tov.optval_class = 324
				and		tov.optval_id = @OptionSupp	)																[params14],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 4241
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params15],

				CASE @pro_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tp.pro_desc
					 FROM	tbProject tp
					 WHERE	tp.pro_id  = @pro_id)
				END																																[params16]




		  -- ---------------------------------------------------------------------------------------------------
		  /* SubReporte Detalle de Formas de Pago*/  --
		  -- ---------------------------------------------------------------------------------------------------
		  -- Referencia : *2* SI SE MODIFICA ESTE SUBQUERY HACERLO EN EL QUERY PRINCIPAL TAMBIEN



			SELECT
					CASE
		      			WHEN vph.Class=2 THEN vph.[description]  + ' * ' + tba.ba_desc
		      			WHEN vph.Class=6 THEN vph.[description]  + ' * ' + tba.ba_desc
		      			ELSE vph.[description]
		      		END					[description],
					sum(vph.amount)		[amount],
					vph.currency		[currency]


			From	tbCommercialTransactions								tct

					INNER JOIN dbo.vwCommercialTransactions_forPurchase		vctfp
					on  tct.comp_id				= vctfp.comp_id
					and tct.bra_id				= vctfp.bra_id
					and tct.ct_transaction		= vctfp.ct_transaction
					and vctfp.sd_isReceipt		= 'True'
					and vctfp.sd_isInBalance	= 'True'

					INNER JOIN tbSupplier									ts
					ON	ts.comp_id				= tct.comp_id
					AND	ts.supp_id				= tct.supp_id

					INNER JOIN @tblComplexFilter_Supplier					tempSupplier
					ON tempSupplier.supp_id					= ts.supp_id

					INNER JOIN dbo.vwPaymentsHow							vph
					ON	vph.comp_id				= tct.comp_id
					AND vph.lang_id				= @lang_id
					AND vph.ct_transaction		= tct.ct_transaction

					INNER JOIN tbsysCurrency								tc
					ON	tc.curr_id				= tct.curr_id_transaction

					INNER JOIN tbBranch										tb
					ON	tb.comp_id				= tct.comp_id
					And tb.bra_id				= @bra_id

					INNER JOIN tbUsers4BranchFilter							vubf
					ON  vubf.comp_id			= tct.comp_id
					AND vubf.bra_id				= tct.bra_id
					AND vubf.[user_id]			= @user_id

					LEFT JOIN tbBankingAccounts tba
						ON	vph.class			IN (2,6)			AND
							tba.comp_id			= vph.comp_id		AND
							tba.ba_id			= vph.GroupClass


			WHERE 	 tct.comp_id		= @comp_id
			AND 	 tct.bra_id		    = @bra_id
			AND 	(@cust			    = -1 or tct.supp_id		= @cust)
			AND 	 tct.ct_date		between  @datefrom	  and @dateto
			AND 	(@country_id	    = -1 or ts.country_id	= @country_id)
			AND 	(@state_id		    = -1 or ts.state_id		= @state_id)
			AND 	 tct.sd_id			= 106						--Pago a Proveedores
			AND     (@optval_id = -1							OR
					 @optval_id = 0		AND ct_Abalance <> 0	OR
					 @optval_id = 1		AND ct_Abalance =  0)

			AND     (@OptionSupp = 1				OR -- todos los proveedores
					 @OptionSupp = 2		AND IsNull(tb.bra_PaymentSupp_Id,1) <> ts.supp_id	OR -- proveedores
					 @OptionSupp = 3		AND IsNull(tb.bra_PaymentSupp_Id,1) = ts.supp_id)	   -- otros pagos
			AND		tct.sd_id = 106

			GROUP BY	vph.class,
						vph.GroupClass,
						vph.[description],
						vph.currency,
						tba.ba_desc

			ORDER BY 1



		 --  Referencia : *3* SI SE MODIFICA ESTE SUBQUERY HACERLO EN EL QUERY PRINCIPAL TAMBIEN
		 -- ---------------------------------------------------------------------------------------------------
		  /* Detalle de concepto por otros pagos*/  --
		  -- ---------------------------------------------------------------------------------------------------




			Select	tctopd.ctopd_desc		[ctopd_desc],
					sum(tctopd.ctopd_total) [ctopd_total],
					tpc.puco_desc			[puco_desc],
					ta.acc_desc				[acc_desc]


			From	tbCommercialTransactions								tct

					INNER JOIN dbo.vwCommercialTransactions_forPurchase		vctfp
					on  tct.comp_id				= vctfp.comp_id
					and tct.bra_id				= vctfp.bra_id
					and tct.ct_transaction		= vctfp.ct_transaction
					and vctfp.sd_isReceipt		= 'True'
					and vctfp.sd_isInBalance	= 'True'

					INNER JOIN tbCommercialTransactionsOtherPaymentsDetail tctopd
					ON	tctopd.comp_id			= tct.comp_id				AND
						tctopd.bra_id			= tct.bra_id				AND
						tctopd.ct_transaction	= tct.ct_transaction

					LEFT JOIN tbPurchaseConcept								tpc
					ON  tpc.comp_id			= tctopd.comp_id
					and tpc.puco_id			= tctopd.puco_id

					LEFT JOIN tbAccountant									ta
					ON	ta.comp_id			= tctopd.comp_id AND
						ta.acc_count_id		= tctopd.acc_count_id

					INNER JOIN tbSupplier									ts
					ON	ts.comp_id				= tct.comp_id
					AND	ts.supp_id				= tct.supp_id

					INNER JOIN @tblComplexFilter_Supplier					tempSupplier
					ON tempSupplier.supp_id					= ts.supp_id

					INNER JOIN tbsysCurrency								tc
					ON	tc.curr_id				= tct.curr_id_transaction

					INNER JOIN tbBranch										tb
					ON	tb.comp_id				= tct.comp_id
					And tb.bra_id				= @bra_id

					INNER JOIN tbUsers4BranchFilter							vubf
					ON  vubf.comp_id			= tct.comp_id
					AND vubf.bra_id				= tct.bra_id
					AND vubf.[user_id]			= @user_id


			WHERE 	 tct.comp_id		= @comp_id
			AND 	 tct.bra_id		    = @bra_id
			AND 	(@cust			    = -1 or tct.supp_id		= @cust)
			AND 	 tct.ct_date		between  @datefrom	  and @dateto
			AND 	(@country_id	    = -1 or ts.country_id	= @country_id)
			AND 	(@state_id		    = -1 or ts.state_id		= @state_id)
			AND 	 tct.sd_id			= 106						--Pago a Proveedores
			AND     (@optval_id = -1							OR
					 @optval_id = 0		AND ct_Abalance <> 0	OR
					 @optval_id = 1		AND ct_Abalance =  0)
			AND     (@OptionSupp = 1				OR -- todos los proveedores
					 @OptionSupp = 2		AND IsNull(tb.bra_PaymentSupp_Id,1) <> ts.supp_id	OR -- proveedores
					 @OptionSupp = 3		AND IsNull(tb.bra_PaymentSupp_Id,1) = ts.supp_id)	   -- otros pagos
			AND		tct.sd_id = 106

			GROUP BY	tctopd.ctopd_desc,tpc.puco_desc,ta.acc_desc

			ORDER BY 1



		  --Si se modifica algo en la consulta hacerla en el subreporte tambien - Referencia : *2* -
		  -- ---------------------------------------------------------------------------------------------------

END
GO








CREATE procedure [dbo].[spCommercialTransactions_getReportTotalPurchase]
(

			@comp_id			int,
			@lang_id			int,
			@page_id			int,
			@selection_id		int,
			@datefrom			datetime,
			@dateto				datetime,
			@supp_id			int,
			@country_id			int,
			@state_id			Int,
			@option				INT,
			@purch_concept      INT,
			@puco_is4result		INT,
			@brag_id			INT,
			@cc_code			int,
			@guid				VARCHAR(50),
			@bra_id				int,
			@user_id			INT,
			@intBranch4Lang		int




)
AS


BEGIN




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-------------------------------------------------------------------------------
	/*
	DECLARE		@comp_id			int,
				@lang_id			int,
				@page_id			int,

				@selection_id		int,
				@datefrom			datetime,
				@dateto				datetime,
				@supp_id			int,
				--@sm_id			int,
				@bra_id				int,
				@country_id			int,
				@state_id			Int,
				@option				Int,
				@user_id			int,
				@purch_concept		INT,
				@puco_is4result		INT


	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@page_id			= 10041,

				@selection_id		=-1,
				@datefrom			='1900-01-01',
				@dateto				='9999-12-31',
				@supp_id			= -1,
				--@sm_id			=-1,
				@bra_id				= 1,
				@country_id			=-1,
				@state_id			=-1,
				@option				=1,
				@user_id			=1,
				@purch_concept		=-1,
				@puco_is4result		=-1
	*/
	-------------------------------------------------------------------------------



	DECLARE @tblBranch TABLE(bra_id INT PRIMARY KEY CLUSTERED)
	IF @brag_id <> -1
		BEGIN
			INSERT INTO @tblBranch(bra_id)
				SELECT tbgd.bra_id
					FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
					WHERE	tbgd.comp_id = @comp_id AND
							tbgd.brag_id = @brag_id
		END
	ELSE
		BEGIN
			INSERT INTO @tblBranch(bra_id) VALUES (@bra_id)
		END



		DECLARE @lGuid AS UNIQUEIDENTIFIER

		SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Supplier
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf	WITH (NOLOCK)
				WHERE tcf.sl_guid = @lGuid     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Supplier
					SELECT ts.supp_id
					FROM tbSupplier ts	WITH (NOLOCK)
						WHERE ts.comp_id = @comp_id
			END
		-- -------------------------------------------------------------




	set	@datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')



	DECLARE @fun_id INT
	SET @fun_id = 1

	Declare @bra_curr_id Int

	Select @bra_curr_id = curr_id
		From tbBranch tb		WITH (NOLOCK)
		Where tb.comp_id = @comp_id
		And tb.bra_id = @bra_id


	--////////


	IF @selection_id = -1
		BEGIN
			Select ts.supp_id,
				   ts.supp_name,
				   dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction) [Comprobante],
				   tct.ct_date,
				   tct.ct_payDate,

				   ltrim(rtrim(tc1.curr_symbol)) + ' ' +
				   replace(convert(varchar,convert(decimal(18,2),round(tct.ct_total,2))		* Case When vctfp.sd_isCredit = 'False' Then 1 Else -1 End),'.',',')	[ct_total],

				   ltrim(rtrim(tc2.curr_symbol)) + ' ' +
				   replace(convert(varchar,convert(decimal(18,2),round(tct.ct_Abalance,2))	* Case When vctfp.sd_isCredit = 'False' Then 1 Else -1 End),'.',',')	[Balance],

				   tct.ct_taxDate,

				  (dbo.fnGetExchange(@comp_id, tct.ct_total, tct.curr_id_transaction,@bra_curr_id, 0,0,'False') * Case When vctfp.sd_isCredit = 'False' Then 1 Else -1 End) [curr_bra_ct_total],

				  (dbo.fnGetExchange(@comp_id, tct.ct_Abalance,tct.ct_ACurrency,@bra_curr_id,0,0,'False')	 * Case When vctfp.sd_isCredit = 'False' Then 1 Else -1 End) [curr_bra_ct_ABalance],

				   tc3.curr_symbol,tc3.curr_desc						[curr_desc3],
				   tpc.puco_desc										[PUCO],
				   CASE
						WHEN CONVERT(INT,tpc.puco_is4Result) = 1 THEN	'True'
						ELSE											'False'
 				   END													[puco_is4Result]




			From	tbCommercialTransactions tct		WITH (NOLOCK)

					INNER JOIN @tblBranch tmpb
						ON tmpb.bra_id = tct.bra_id

					Inner Join vwCommercialTransactions_forPurchase vctfp		WITH (NOLOCK)
					On  vctfp.comp_id			= tct.comp_id
					And vctfp.bra_id			= tct.bra_id
					And vctfp.ct_transaction	= tct.ct_transaction
					And vctfp.supp_id			= tct.supp_id

					Inner Join tbSupplier							ts		WITH (NOLOCK)
					on	ts.comp_id		= tct.comp_id
					and	ts.supp_id		= tct.supp_id

					INNER JOIN @tblComplexFilter_Supplier		tempSupplier
					ON tempSupplier.supp_id					= ts.supp_id


					inner join dbo.vwSysDocumentsSupplier vsds		WITH (NOLOCK)
					On	vsds.sd_id			= tct.sd_id
					and	vsds.sd_isQuotation	= 'False'
					and vsds.sd_isReceipt	= 'False'


					Inner Join tbsysCurrency tc1		WITH (NOLOCK)
					On tc1.curr_id = tct.curr_id_transaction


					Inner Join tbsysCurrency tc2		WITH (NOLOCK)
					On tc2.curr_id = tct.ct_ACurrency


					Inner Join tbsysCurrency tc3		WITH (NOLOCK)
					On tc3.curr_id = @bra_curr_id


					inner join tbUsers4BranchFilter vubf		WITH (NOLOCK)
					ON  vubf.comp_id    = tct.comp_id
					AND vubf.bra_id     = tct.bra_id
					AND vubf.[user_id]  = @user_id


					LEFT JOIN tbPurchaseConcept tpc		WITH (NOLOCK)
					ON  tpc.comp_id		= ts.comp_id
					AND tpc.puco_id		= ts.puco_id
			Where	tct.comp_id		= @comp_id
			--AND		tct.bra_id		= @bra_id
			AND		(
						(@option	 = 1 AND  tct.ct_abalance =  tct.ct_abalance) or
						(@option	 = 2 AND  tct.ct_abalance <> 0)               or
						(@option	 = 3 AND  tct.ct_abalance =  0)
					)

			AND		(@supp_id		= -1 or tct.supp_id		= @supp_id)
			AND		tct.ct_date		between  @datefrom	  and @dateto
			AND		(@country_id	= -1 or ts.country_id	= @country_id)
			AND		(@state_id		= -1 or ts.state_id		= @state_id)
			AND		(@selection_id	= -1 or vsds.sd_id		= @selection_id)
			AND		(@purch_concept  = -1 OR isnull(tpc.puco_id,-1)				= @purch_concept)
			AND		(@puco_is4result = -1 OR isnull(tpc.puco_is4Result,'false') = @puco_is4result)
			AND		(@cc_code		 = -1 OR isnull(ts.cc_code,-1)				= @cc_code) -- Centro de Costos
			order by tct.ct_taxDate, tct.ct_transaction
		END
	ELSE
	BEGIN




			Select ts.supp_id,
				   ts.supp_name,
				   dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction) [Comprobante],
				   tct.ct_date,
				   tct.ct_payDate,

				   ltrim(rtrim(tc1.curr_symbol)) + ' ' +
				   replace(convert(varchar,convert(decimal(18,2),round(tct.ct_total,2))		* Case When vctfp.sd_isCredit = 'False' Then 1 Else -1 End),'.',',')	[ct_total],

				   ltrim(rtrim(tc2.curr_symbol)) + ' ' +
				   replace(convert(varchar,convert(decimal(18,2),round(tct.ct_Abalance,2))	* Case When vctfp.sd_isCredit = 'False' Then 1 Else -1 End),'.',',')	[Balance],

				   tct.ct_taxDate,

				  (dbo.fnGetExchange(@comp_id, tct.ct_total, tct.curr_id_transaction,@bra_curr_id, 0,0,'False') * Case When vctfp.sd_isCredit = 'False' Then 1 Else -1 End) [curr_bra_ct_total],

				  (dbo.fnGetExchange(@comp_id, tct.ct_Abalance,tct.ct_ACurrency,@bra_curr_id,0,0,'False')	 * Case When vctfp.sd_isCredit = 'False' Then 1 Else -1 End) [curr_bra_ct_ABalance],

				   tc3.curr_symbol,tc3.curr_desc						[curr_desc3],
				   tpc.puco_desc										[PUCO],
				   CASE
						WHEN CONVERT(INT,tpc.puco_is4Result) = 1 THEN	'True'
						ELSE											'False'
 				   END													[puco_is4Result]
				From	tbCommercialTransactions tct		WITH (NOLOCK)

					INNER JOIN @tblBranch tmpb
						ON tmpb.bra_id = tct.bra_id

					Inner Join vwCommercialTransactions_forPurchase_AllPlusStock AS  vctfp		WITH (NOLOCK)
					On  vctfp.comp_id			= tct.comp_id
					And vctfp.bra_id			= tct.bra_id
					And vctfp.ct_transaction	= tct.ct_transaction
					And vctfp.supp_id			= tct.supp_id

					Inner Join tbSupplier							ts		WITH (NOLOCK)
					on	ts.comp_id		= tct.comp_id
					and	ts.supp_id		= tct.supp_id

					INNER JOIN @tblComplexFilter_Supplier		tempSupplier
					ON tempSupplier.supp_id					= ts.supp_id


					inner join dbo.vwSysDocumentsSupplier vsds		WITH (NOLOCK)
					On	vsds.sd_id			= tct.sd_id
					and	vsds.sd_isQuotation	= 'False'
					and vsds.sd_isReceipt	= 'False'


					Inner Join tbsysCurrency tc1		WITH (NOLOCK)
					On tc1.curr_id = tct.curr_id_transaction


					Inner Join tbsysCurrency tc2		WITH (NOLOCK)
					On tc2.curr_id = tct.ct_ACurrency


					Inner Join tbsysCurrency tc3		WITH (NOLOCK)
					On tc3.curr_id = @bra_curr_id


					inner join tbUsers4BranchFilter vubf		WITH (NOLOCK)
					ON  vubf.comp_id    = tct.comp_id
					AND vubf.bra_id     = tct.bra_id
					AND vubf.[user_id]  = @user_id


					LEFT JOIN tbPurchaseConcept tpc		WITH (NOLOCK)
					ON  tpc.comp_id		= ts.comp_id
					AND tpc.puco_id		= ts.puco_id
			Where	tct.comp_id		= @comp_id
			--AND		tct.bra_id		= @bra_id
			AND		(
						(@option	 = 1 AND  tct.ct_abalance =  tct.ct_abalance) or
						(@option	 = 2 AND  tct.ct_abalance <> 0)               or
						(@option	 = 3 AND  tct.ct_abalance =  0)
					)

			AND		(@supp_id		= -1 or tct.supp_id		= @supp_id)
			AND		tct.ct_date		between  @datefrom	  and @dateto
			AND		(@country_id	= -1 or ts.country_id	= @country_id)
			AND		(@state_id		= -1 or ts.state_id		= @state_id)
			AND		(@selection_id	= -1 or vsds.sd_id		= @selection_id)
			AND		(@purch_concept  = -1 OR isnull(tpc.puco_id,-1)				= @purch_concept)
			AND		(@puco_is4result = -1 OR isnull(tpc.puco_is4Result,'false') = @puco_is4result)
			AND		(@cc_code		 = -1 OR isnull(ts.cc_code,-1)				= @cc_code) -- Centro de Costos
			order by tct.ct_taxDate, tct.ct_transaction
		END


















	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	SELECT


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 398
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params1],

			CASE @selection_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		vsdc.sd_desc
					FROM	dbo.vwSysDocumentsSupplier vsdc
					WHERE	vsdc.sd_id = @selection_id)
			END																																	[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 177
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params3],

			@datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))					[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 384
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params5],

			@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))						[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 402
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params7],

				CASE @supp_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT ts.supp_name
					 FROM	dbo.tbSupplier ts
					 WHERE	ts.supp_id  = @supp_id)
				END																																[params8],

	--		(SELECT t.[text_desc] FROM [tbsysTexts]	t
	--			 WHERE t.ctrl_id = 172 AND t.[lang_id] = @lang_id and t.[page_id] = @related_page_id and t.[type_id]	= 1)						[params9],
	--
	--			CASE @sm_id WHEN -1 THEN
	--				(SELECT		tut.utexts_desc
	--					FROM	tbsysUniqueTexts tut
	--					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
	--			ELSE
	--				(SELECT		ts.sm_name
	--					FROM	dbo.tbSalesman ts
	--					WHERE	ts.sm_id = @sm_id)
	--			END																																[params10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 57
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params9],

				CASE @country_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.country_desc
						FROM	dbo.tbsysCountry tc
						WHERE	tc.country_id = @country_id)
				END																																[params10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 653
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params11],

				CASE @state_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.state_desc
						FROM	dbo.tbsysState ts
						WHERE	ts.state_id = @state_id)
				END							[params12],

				--
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 991
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)[params13],
				(SELECT		tov.optval_desc
					FROM	tbsysOptionsValues tov
					WHERE	tov.lang_id = @lang_id
					And     tov.optval_class = 65
					And tov.optval_order = @option)		 [params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 1379
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params15],


				CASE @purch_concept  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tpc.puco_desc
					 FROM       tbPurchaseConcept tpc
						WHERE	tpc.puco_id = @purch_concept)
				END		[params16],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 1612
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params17],



				/*Numero de Ticket 714 ; Programador : Martin Bloise(gay :P LOL )*/
				CASE @puco_is4result  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
			 		 FROM	tbsysOptionsValues tov
							WHERE	tov.lang_id = @lang_id
							And     tov.optval_class = 120
							And		tov.optval_order = @puco_is4result)
				END																				[params18],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 639
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params19],

				CASE @brag_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT		tbg.brag_desc
						FROM	dbo.tbBranchGroup tbg
						WHERE	tbg.brag_id = @brag_id)
				END																																[params20],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 298
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params21],

				CASE @cc_code WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tcc.cc_desc
						FROM	dbo.tbCostCenter tcc
						WHERE	tcc.comp_id = @comp_id and tcc.cc_code = @cc_code)
				END																																[params22]









END
GO


CREATE procedure [dbo].[spCommercialTransactions_getReportTotalSales]
(
	@comp_id			INT,
	@lang_id			INT,
	@page_id			INT,
	@selection_id		INT,		--SD_ID
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@custsupp			INT,
	@sm_id				INT,
	@country_id			INT,
	@state_id			INT,
	@bra_id				INT,
	@option_saldo		INT,
	@Taxes				INT,
	@ck_id				INT,
	@brand_id			INT,
	@act_id				INT,
	@pro_id				INT,
	@sm2_id				INT,
	@user_idfilter		INT,
	@guid				VARCHAR(50),
	@user_id			INT,
	@prof_id			INT,
	@intBranch4Lang		INT,
	@st_id				INT,
	@disc_id			INT,
	@dl_id				INT,
	@df_id				INT,
	@FromDocumentTotalImport	DECIMAL(19,2),
	@ToDocumentTotalImport		DECIMAL(19,2)

)
as

BEGIN




    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------



	set nocount on

	set dateformat 'ymd'





	-- ------------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------------
		/*
		declare		@comp_id			int,
					@lang_id			int,
					@page_id			int,

					@selection_id		int,
					@datefrom			datetime,
					@dateto				datetime,
					@custsupp			int,
					@sm_id				int,
					@bra_id				int,
					@country_id			int,
					@state_id			int,
					@option_saldo		INT,
					@user_id			INT,
					@Taxes				INT,
					@ck_id				int,
					@brand_id			int,
					@prof_id			int,
					@intBranch4Lang		INT,
					@act_id				INT,
					@pro_id				INT,
					@sm2_id				int,
					@user_idfilter		int,
					@guid				VARCHAR(50),
					@st_id				INT,
					@disc_id			INT,
					@dl_id				INT,
					@FromDocumentTotalImport	DECIMAL(19,2) = 0,
					@ToDocumentTotalImport		DECIMAL(19,2) = 999999999999

		Select		@comp_id			=1,
					@lang_id			=2,
					@page_id			=10012,
					@selection_id		=-1,
					@datefrom			='2000-01-01',
					@dateto				='2911-10-31',
					@custsupp			=-1,
					@sm_id				=-1,
					@bra_id				= 1,
					@country_id			=-1,
					@state_id			=-1,
					@option_saldo		=-1,
					@user_id			=1,
					@Taxes				=1,
					@ck_id				=-1,
					@brand_id			=-1,
					@prof_id			=1,
					@act_id				=-1,
					@pro_id				= -1,
					@sm2_id				= -1,
					@user_idfilter		= 1,
					@guid				= '6DDE0A8F-0F09-49A8-A31C-98AA69934363',
					@st_id				= -1,
					@disc_id			= -1,
					@dl_id				= -1
*/
	-- ------------------------------------------------------------------------------------



	set	@datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf		WITH (NOLOCK)
				WHERE tcf.sl_guid = @lGuid     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT tc.cust_id
					FROM tbCustomer tc			WITH (NOLOCK)
						WHERE tc.comp_id = @comp_id
			END
		-- -------------------------------------------------------------




	DECLARE @bitWithProfit AS BIT
	Set @bitWithProfit = 'False'
	IF  EXISTS(
				SELECT 1
					FROM tbControlProfiles tcp1				WITH (NOLOCK)
               		WHERE	tcp1.ctrl_id = 1749
               			AND tcp1.comp_id = @comp_id
               			AND tcp1.bra_id  = @bra_id
               			AND tcp1.prof_id = @prof_id
				)
	BEGIN
		Set @bitWithProfit = 'True'
	END


	DECLARE @fun_id INT
	SET @fun_id = 1





	Select	/*DISTINCT  NOOOOO, bloquea todas las bases */
			ct.cust_id,
			c.cust_name,

			ov.optval_desc + ' ' +
			ISNULL(ct.ct_kindOf,'*') + ' ' +
			dbo.PadString(ISNULL(ct.ct_pointOfSale,''),'0',4) + '-' +
			dbo.PadString(ISNULL(ct.ct_docNumber,''),'0',8)


			/*Se reemplazo por velocidad dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.ct_transaction)*/								 [Comprobante],
			ct_date,
			ct_payDate,
			sm.sm_name,

			CASE WHEN @Taxes = 1 THEN
					 (CASE WHEN vwct.sd_isCredit  = 'false' THEN ct.ct_total	  ELSE ct.ct_total		* -1 END)
			ELSE
					 (CASE WHEN vwct.sd_isCredit  = 'false' THEN (ct.ct_subtotal - ct.ct_discount)   ELSE (ct.ct_subtotal - ct.ct_discount)  * -1 END)
			END 																									[ct_total],

			(CASE WHEN vwct.sd_isCredit = 'false' THEN ct.ct_Abalance ELSE ct.ct_Abalance   * -1 END * ct_AcurrencyExchange) [Balance],
			ct.ct_kindOf,ct.ct_pointOfSale,ct.ct_docNumber,convert(int,@Taxes)	[sd_isCredit],
			case
				when @bitWithProfit = 'True' then vctpam.ProfitPPP
				ELSE	 0
			END																	[Profit],	--,Profit contra Costo Promedio Ponderado A. Si quierte contra otros que lo vea por los cubos.
			--tb.brand_id,tb.brand_desc
			isnull(tst.st_desc,'')												[st_desc]

	From	dbo.tbCommercialTransactions										ct		WITH (NOLOCK)

			inner join tbUsers4BranchFilter										vubf	WITH (NOLOCK)
			ON  vubf.comp_id		= ct.comp_id
			AND vubf.bra_id			= ct.bra_id
			AND vubf.[user_id]		= @user_id

			--Agregado...Join a la vista de la tabla Commercial Transactions
			inner join dbo.vwCommercialTransactions_forSales					vwct	WITH (NOLOCK)
			on  ct.comp_id			= vwct.comp_id
			and ct.bra_id			= vwct.bra_id
			and ct.ct_transaction	= vwct.ct_transaction

			INNER JOIN vwCommercialTransactionsProfitAndMarckup vctpam					WITH (NOLOCK)
				ON		vctpam.comp_id			= ct.comp_id
					AND vctpam.bra_id			= ct.bra_id
					AND vctpam.ct_transaction	= ct.ct_transaction


			INNER JOIN @tblComplexFilter_Customer		tempCustomer
			ON tempCustomer.cust_id						= Ct.cust_id


			INNER JOIN tbDocumentsFile											tdf		WITH (NOLOCK)
			ON  tdf.comp_id = ct.comp_id
			AND tdf.bra_id = ct.bra_id
			AND tdf.df_id  = ct.df_id

			inner join dbo.tbCustomer											c		WITH (NOLOCK)
			on	ct.comp_id			= c.comp_id
			and	ct.cust_id			= c.cust_id


			--inner join 	dbo.tbDocumentsFile										df		WITH (NOLOCK)
			--on	ct.comp_id			= df.comp_id
			----and ct.bra_id			= df.bra_id
			--and ct.df_id			= df.df_id

			inner join dbo.tbsysOptionsValues									ov		WITH (NOLOCK)
			on
				ov.lang_id			= @lang_id	AND
				ov.optval_id		= ct.sd_id	AND
				ov.optval_class		= 6


			inner join dbo.tbSalesman											sm		WITH (NOLOCK)
			on  sm.comp_id			= ct.comp_id
			and sm.sm_id			= ct.sm_id


			INNER join tbCustomerKind											ck		WITH (NOLOCK)
			on  ck.comp_id			= c.comp_id
			and ck.ck_id			= c.ck_id


			LEFT JOIN tbSalesTerms												tst		WITH (NOLOCK)
			ON  tst.comp_id = ct.comp_id AND
				tst.st_id   = ct.st_id

			LEFT JOIN tbActivity												ta		WITH (NOLOCK)
			ON  ta.comp_id	= c.comp_id AND
				ta.act_id	= c.act_id


	Where	ct.comp_id		=	@comp_id
	and		vwct.sd_isReceipt	= 'false'
	and		vwct.sd_isInBalance	= 'true'
	and		(@bra_id		=	-1 or ct.bra_id			= @bra_id)
	and		(@custsupp		=	-1 or ct.cust_id		= @custsupp)
	and		 ct.ct_date		between	@datefrom			and @dateto
	and		(@sm_id			=	-1 or ct.sm_id			= @sm_id)
	AND 	(@pro_id			= -1 or ct.pro_id		= @pro_id)
	and		(@act_id		=	-1 or ta.act_id			= @act_id)
	AND		CASE
	   		    WHEN @selection_id	=	-1 AND (ct.sd_id = 1 OR ct.sd_id = 3 OR ct.sd_id = 4) /*ct.sd_id IN (1,3,4)*/			THEN 1
	   		    WHEN @selection_id	=	-1									THEN 0
	   		    WHEN tdf.sd_id			= @selection_id						THEN 1
	   		    WHEN @selection_id	=   -5 AND (ct.sd_id = 1 OR ct.sd_id = 3 OR ct.sd_id = 4 OR ct.sd_id = 21 OR ct.sd_id = 23) /*ct.sd_id IN (1,3,4,21,23)*/	THEN 1
	   		    ELSE															 0
	   		END = 1

	--and		(@selection_id	=	-1 or df.sd_id			= @selection_id)
	And		(
			(@option_saldo	=	-1)								or
			(@option_saldo	=	0	and ct_Abalance		<> 0)	or
			(@option_saldo	=	1	and ct_Abalance		= 0)
			)
	and   (@ck_id			= -1 or ck.ck_id			= @ck_id  )

	AND		CASE
	   		    WHEN @brand_id = -1 THEN 1
	   		    WHEN EXISTS(	SELECT TOP 1 1									-- MOS 532
										FROM tbItemTransactions tit					WITH (NOLOCK)
										INNER JOIN tbitem	 it						WITH (NOLOCK)
											ON		it.comp_id = tit.comp_id
												AND it.item_id = ISNULL(tit.item_id,tit.item_idfromPreInvoice) -- MOS 01-2022, para que tome las marcas de los items de factura anticipada
	                              		WHERE	tit.comp_id			= ct.comp_id
	                              			AND tit.ct_transaction	= ct.ct_transaction
	                              			AND it.brand_id			= @brand_id
									) THEN 1
	   		    ELSE	0
	   		END	= 1
	AND		CASE	-- MOS 10-2023: INterno para poder tirar rango de importes de COMPROBANTES en general, no importa si es FC o NC
				WHEN @Taxes = 1 AND  ct_total							BETWEEN @FromDocumentTotalImport AND @ToDocumentTotalImport THEN 1
				WHEN @Taxes = 0 AND  (ct.ct_subtotal - ct.ct_discount)	BETWEEN @FromDocumentTotalImport AND @ToDocumentTotalImport THEN 1
				ELSE 0
			END	  = 1


	--AND (@brand_id = -1 OR EXISTS(	SELECT TOP 1 1									-- MOS 532
	--									FROM tbItemTransactions tit					WITH (NOLOCK)
	--									INNER JOIN tbitem	 it						WITH (NOLOCK)
	--										ON		it.comp_id = tit.comp_id
	--											AND it.item_id = tit.item_id
	--                              		WHERE	tit.comp_id			= ct.comp_id
	--                              			AND tit.ct_transaction	= ct.ct_transaction
	--                              			AND it.brand_id			= @brand_id
	--								) )



	and (@country_id		= -1	or c.country_id		= @country_id)
	and (@state_id			= -1	or c.state_id		= @state_id)
	and	(@df_id				=-1		or tdf.df_id		= @df_id)
	and (@sm2_id			= -1	or c.sm_id_2		= @sm2_id)
	and (@user_idfilter		= -1	or ct.[user_id]		= @user_idfilter)
	AND ISNULL(tdf.df_excludereports, 'False') = 'False'					AND
		(@st_id				= -1	OR ct.st_id			= @st_id)			AND
		(@disc_id			= -1	OR ct.disc_id		= @disc_id)			AND
		(@dl_id				= -1	OR ct.dl_id			= @dl_id)

	order BY ct.ct_date, Comprobante  --  ct.ct_kindOf,ct.ct_pointOfSale,ct.ct_docNumber
OPTION ( MAXDOP 1 )



	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id




	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id


	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/


	select
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 398
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1  AND t.fun_id =@fun_id)		[params1],

			CASE @selection_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		vsdc.sd_desc
					FROM	dbo.vwSysDocumentsCustomer vsdc
					WHERE	vsdc.sd_id = @selection_id)
			END																																[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 177
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)				[params3],

			@datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))				[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 384
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)				[params5],

			@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))					[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 402
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id) [params7],

				CASE @custsupp WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tc.cust_name
