						 WHERE t.ctrl_id = 173
						 --AND t.[lang_id] = @lang_id
						 and t.[page_id] = @related_page_id and t.[type_id]	= 1  AND t.fun_id =@fun_id)							[params31],

						CASE @disc_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
