							(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						 WHERE t.ctrl_id = 170
						 --AND t.[lang_id] = @lang_id
						 and t.[page_id] = @related_page_id and t.[type_id]	= 1  AND t.fun_id =@fun_id)							[params33],

						CASE @dl_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT td2.dl_name
							 FROM tbDelivery td2
							 WHERE td2.comp_id = @comp_id AND 	td2.dl_id  = @dl_id)
						END																										[params34],


					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						 WHERE t.ctrl_id = 1324
						 --AND t.[lang_id] = @lang_id
						 and t.[page_id] = @related_page_id and t.[type_id]	= 1  AND t.fun_id =@fun_id)							[params35],

						CASE @df_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
						(SELECT		tdf.df_desc
							FROM	dbo.tbDocumentsFile tdf
							WHERE	tdf.df_id = @df_id)
						END																										[params36]




