CREATE PROCEDURE [dbo].[spCommercialTransactions_getReportTotalSalesDetail]
(
	@comp_id			INT,
	@lang_id			INT,
	@page_id			INT,
	@selection_id		INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@item_id			INT,
	@custsupp			INT,
	@sm_id				INT,
	@bra_id				INT,
	@country_id			INT,
	@state_id			INT,
	@option_saldo		INT,
	@user_id			INT,
	@prof_id			INT,
	@doc_number			NVARCHAR(50),
	@df_id				INT,
	@guidItem			VARCHAR(50),
	@guidCust			VARCHAR(50),
	@pointOfSale        INT,
	@pricetype			INT,				-- 1 : Importe , 2 : Importe menos intereses
	@option_cost		INT,				-- 1 = Costos , 2 = Costos Adicionales
	@intBranch4Lang		int

)

AS

BEGIN


    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------



	SET NOCOUNT ON




-- ----------------------------------------------------------------
-- Testing
-- ----------------------------------------------------------------
	/*
	DECLARE	@comp_id			int,
			@lang_id			int,
			@page_id			int,
			@selection_id		int,
			@datefrom			datetime,
			@dateto				datetime,
			@item_id			int,
			@custsupp			int,
			@sm_id				int,
			@bra_id				int,
			@country_id			int,
			@state_id			int,
			@option_saldo		INT,
			@user_id			INT,
			@prof_id			INT,
			@doc_number			NVARCHAR(50),
			@df_id				INT,
			@guidItem			VARCHAR(50),
			@guidCust			VARCHAR(50),
			@pointOfSale        INT,
			@pricetype			INT,
			@intBranch4Lang		int




	SELECT	@comp_id			=1,
			@lang_id			=2,
			@page_id			=10060,
			@selection_id		=-1,
			@datefrom			='2016-05-01',
			@dateto				='2016-12-05',
			@item_id			= -1,
			@custsupp			=-1,
			@sm_id				=-1,
			@bra_id				= 1,
			@country_id			=-1,
			@state_id			=-1,
			@option_saldo		=-1,
			@user_id			= 1,
			@doc_number			= 0,
			@prof_id			= 1,
			@df_id				= -1,
			@guidItem			= '3850F92F-8956-49F7-A873-CAE8A476D85B',
			@guidCust			= '7E1D83C1-BD0C-4781-A423-BF1BBEAD43D5',
			@pointOfSale        = -1,
			@pricetype			=1,
			@intBranch4Lang		= 1
*/
-- ----------------------------------------------------------------

	SET DATEFORMAT 'ymd'

	set	@datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	DECLARE @lGuidCust AS UNIQUEIDENTIFIER

	SET @lGuidCust = CONVERT(UNIQUEIDENTIFIER,@guidCust)


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf		WITH (NOLOCK)
				WHERE tcf.sl_guid = @lGuidCust     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT tc.cust_id
					FROM tbCustomer tc		WITH (NOLOCK)
						WHERE tc.comp_id = @comp_id
			END
		-- -------------------------------------------------------------


		DECLARE @lGuidItem AS UNIQUEIDENTIFIER

	    SET @lGuidItem = CONVERT(UNIQUEIDENTIFIER,@guidItem)


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Artículos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT ,UNIQUE  NONCLUSTERED (item_id))
		IF @item_id > 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items(item_id) VALUES (@item_id)
			END
		ELSE
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT tcf.sl_id
						FROM tbComplexFilter tcf		WITH (NOLOCK)
						WHERE tcf.sl_guid = @lGuidItem     AND
									  tcf.sl_selected = 'True'
			END

		IF @@ROWCOUNT = 0 AND @item_id <= 0
			BEGIN
				INSERT  INTO  @tblComplexFilter_Items values (-1)
				INSERT  INTO  @tblComplexFilter_Items values (-2)
				INSERT  INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti		WITH (NOLOCK)
							WHERE ti.comp_id = @comp_id
			END

		-- -------------------------------------------------------------


		--Recupero en una variable el estado en controles por perfil . Con "(*)" Por defecto deshabilitado.
		-- (*) Ocultar columnas de profit,costos y markup.

		Declare @ctrl_hidecolumns INT
		Set @ctrl_hidecolumns = 0
		IF EXISTS(

						select 1
							from tbControlProfiles			WITH (NOLOCK)
							where	comp_id			= @comp_id			AND
									bra_id			= @intBranch4Lang	AND
									prof_id			= @prof_id			AND
									page_id			= 191				AND
									ctrl_id			= 5566

					 )

				BEGIN

					Set @ctrl_hidecolumns = 1

				END



--SELECT * FROM @tblComplexFilter_Items
	DECLARE @fun_id INT
	DECLARE @suma1  DECIMAL(19,6)

	SET @fun_id = 1

	SELECT

		c.cust_name,
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.ct_transaction)								 [Comprobante],
		ct_date,
		ct_payDate,
		sm.sm_name,

		isnull(ti.item_code,'')
																		[item_code],
		isnull(ti.item_desc,isnull(titd.itm_desc,''))		+
									CASE
										WHEN tit.it_item_id_origin IS NOT NULL AND tit.item_id IS NULL THEN ' (combo)'
										WHEN ISNULL(ISNULL(tit.item_id,tit.item_idfromPreInvoice),tit.it_item_id_origin) IS NULL THEN ' (Manual)'
										ELSE ''
									END									[item_desc],

		tit.it_qty * vwct.PlusOrMinus									[it_qty],
		tc.curr_symbol,
		(tit.it_price - CASE
							WHEN @pricetype = 2 THEN	tit.it_CreditInt
							ELSE						0
		                END )	* vwct.PlusOrMinus	* tit.it_qty		[it_price],

		case
			when @ctrl_hidecolumns = 0 then
					CASE
						WHEN @option_cost = 1 THEN  tit.it_priceOfCost
						ELSE						tit.it_priceBOfCost
					END						* vwct.PlusOrMinus	* tit.it_qty
			ELSE	0
		END																[it_priceOfCost],

		case
			when @ctrl_hidecolumns = 0 then
					CASE
						WHEN @option_cost = 1 THEN  tit.it_priceOfCostPP
						ELSE						tit.it_priceBOfCostPP
					END						* vwct.PlusOrMinus	* tit.it_qty
			ELSE		0
		END																[it_priceOfCostPP],

		case when @ctrl_hidecolumns = 0 then
			CASE
				WHEN	CASE
							WHEN @option_cost = 1 THEN  tit.it_priceOfCost
							ELSE						tit.it_priceBOfCost
						END  > 0 THEN
			(((tit.it_price  -	CASE
									WHEN @pricetype = 2 THEN	tit.it_CreditInt
									ELSE						0
								END ) / dbo.fnNoZDiv(	CASE
															WHEN @option_cost = 1 THEN  tit.it_priceOfCost
															ELSE						tit.it_priceBOfCost
														END
													) )-1) *  100
				ELSE 0
			END


		ELSE
				0
		END																		[Marckup],

		case when @ctrl_hidecolumns = 0 then
			CASE
				WHEN tit.it_price > 0		THEN
			((	CASE
					WHEN @option_cost = 1 THEN  tit.it_priceOfCost
					ELSE						tit.it_priceBOfCost
				END
								 / dbo.fnNoZDiv((tit.it_price - CASE
																	WHEN @pricetype = 2 THEN	tit.it_CreditInt
																	ELSE						0
																END )) )-1)  * -100
				ELSE 0
			END
		ELSE
				0
		END																			[Profit],

		ct.ct_total	    * vwct.PlusOrMinus			   					[ct_total],
		(ct.ct_Abalance * vwct.PlusOrMinus * ct_AcurrencyExchange)		[Balance],
		vwct.sd_id


		From	dbo.tbCommercialTransactions								ct			WITH (NOLOCK)


		--Agregado...Join a la vista de la tabla Commercial Transactions
		INNER JOIN dbo.vwCommercialTransactions_forSales					vwct		WITH (NOLOCK)
			on  ct.comp_id			= vwct.comp_id
			and ct.bra_id			= vwct.bra_id
			and ct.ct_transaction	= vwct.ct_transaction


		INNER join tbUsers4BranchFilter										vubf		WITH (NOLOCK)
			ON  vubf.comp_id		= ct.comp_id
			AND vubf.bra_id			= ct.bra_id
			AND vubf.[user_id]		= @user_id



		INNER JOIN @tblComplexFilter_Customer								tempCustomer
			ON tempCustomer.cust_id		= Ct.cust_id

		INNER JOIN dbo.tbCustomer											c			WITH (NOLOCK)
			on	ct.comp_id			= c.comp_id
			and	ct.cust_id			= c.cust_id

		INNER JOIN 	dbo.tbDocumentsFile										df			WITH (NOLOCK)
			on	ct.comp_id			= df.comp_id
			and ct.df_id			= df.df_id


		INNER JOIN dbo.tbSalesman											sm			WITH (NOLOCK)
			on  ct.comp_id			= sm.comp_id
			and ct.sm_id			= sm.sm_id

		INNER JOIN tbItemTransactions										tit			WITH (NOLOCK)
			ON	tit.comp_id			= ct.comp_id
			AND tit.bra_id			= ct.bra_id
			AND tit.ct_transaction	= ct.ct_transaction

		INNER JOIN @tblComplexFilter_Items								tempItem
			ON (tempItem.item_id		= ISNULL(ISNULL(tit.item_id,tit.item_idfromPreInvoice),tit.it_item_id_origin))		-- MOS 10-2021 para que incluya COMBOS ( con importe en cero, solo cantidades )
					OR
			   (
			   		ISNULL(ISNULL(tit.item_id,tit.item_idfromPreInvoice),tit.it_item_id_origin) IS NULL
			   			AND
			   		tit.item_id IS NULL
			   			AND
			   		tempItem.item_id = -2
			   ) -- Items MANUALES  MOS 11-2021 x Pampa

			--ON tempItem.item_id		= ISNULL(tit.item_id,tit.item_idfromPreInvoice)		-- MOS 08-2021 tit.item_id

		INNER JOIN tbsysCurrency											tc			WITH (NOLOCK)
			ON  tc.curr_id			= tit.curr_id

		LEFT JOIN tbItem													ti			WITH (NOLOCK)
			ON	ti.comp_id			= tit.comp_id	AND
				ti.item_id			= ISNULL(ISNULL(tit.item_id,tit.item_idfromPreInvoice),tit.it_item_id_origin)	-- MOS 10-2021
			--AND (
			--		ti.item_id		= tit.item_id
			--			OR
			--		ti.item_id		= tit.item_idfromPreInvoice
			--	)


		LEFT JOIN tbItemTransactionDetails									titd		WITH (NOLOCK)
			ON	titd.comp_id		= tit.comp_id
			AND titd.bra_id			= tit.bra_id
			AND titd.ct_transaction = tit.ct_transaction
			AND titd.it_transaction = tit.it_transaction




	Where	ct.comp_id				=	@comp_id
	--and		ct.bra_id		=	@bra_id
		and vwct.sd_isReceipt		= 'false'
		and vwct.sd_isInBalance		= 'true'
		and df.df_excludereports	= 'False'
		and (@country_id			= -1	or c.country_id		= @country_id)
		and (@state_id				= -1	or c.state_id		= @state_id)
		and		(@bra_id			=	-1 or ct.bra_id			= @bra_id) --ga , seleccion de suc 14/01/16
		and		(@custsupp			=	-1 or ct.cust_id		= @custsupp)
		and		 ct.ct_date		between	@datefrom			and @dateto
		and		(@sm_id				=	-1 or ct.sm_id			= @sm_id)
		and		(@df_id				=	-1 or df.df_id			= @df_id)
		and		(@pointOfSale		=	-1 or ct.ct_pointOfSale	= @pointOfSale)

		and		(@selection_id		=	-1 or df.sd_id			= @selection_id)
		And		(
					(@option_saldo	=	-1)								or
					(@option_saldo	=	0	and ct_Abalance		<> 0)	or
					(@option_saldo	=	1	and ct_Abalance			= 0)
		)
		AND    (
				(@doc_number = 0) OR
				( not ct.ct_docNumber IS null AND ct.ct_docNumber	= @doc_number)
	   			)
		--and		(ti.item_id			= @item_id		or @item_id		= -1)
		and		(
					@item_id		= -1 OR
					ti.item_id			= ISNULL(ISNULL(tit.item_id,tit.item_idfromPreInvoice),tit.it_item_id_origin)
				)

	ORDER BY	c.cust_name,
				ct.ct_date,
				ct.ct_kindOf,
				ct.ct_pointOfSale,
				ct.ct_docNumber






	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	/* devolución de parámetros recibidos */
	  DECLARE @related_page_id INT
	  SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	  /*************************************************************************************************************/
	 /* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	 /*
 			SELECT	t.ctrl_id,	t.[text_desc]
  			FROM	[tbsysTexts]				t
  					inner join [tbsysControls]	c
  					on c.[ctrl_id] = t.[ctrl_id]
  			where	t.[lang_id]	= @lang_id
  			and		t.[page_id]	= @related_page_id
  			and		t.[type_id]	= 1
	  */
	  /*************************************************************************************************************/
	  select
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 398
  				 --AND t.[lang_id] = @lang_id
  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1  AND t.fun_id =@fun_id)		[params1],
  			CASE @selection_id WHEN -1 THEN
  				(SELECT		tut.utexts_desc
  					FROM	tbsysUniqueTexts tut
  					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
  			ELSE
  				(SELECT		vsdc.sd_desc
  					FROM	dbo.vwSysDocumentsCustomer vsdc
  					WHERE	vsdc.sd_id = @selection_id)
  			END																																[params2],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 177
  				 --AND t.[lang_id] = @lang_id
  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)				[params3],

			@datefrom [DateParams1],

  			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))				[params4],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 384
  				 --AND t.[lang_id] = @lang_id
  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)				[params5],

  			@dateto [DateParams2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 402

  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id) [params7],
  				CASE @custsupp WHEN -1 THEN
  					(SELECT	tut.utexts_desc
  					 FROM	tbsysUniqueTexts tut
  					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
  				ELSE
  					(SELECT tc.cust_name
  					 FROM	dbo.tbCustomer tc
  					 WHERE	tc.cust_id  = @custsupp)
  				END																																	[params8],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 172

  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1  AND t.fun_id =@fun_id)						[params9],
  				CASE @sm_id WHEN -1 THEN
  					(SELECT		tut.utexts_desc
  						FROM	tbsysUniqueTexts tut
  						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
  				ELSE
  					(SELECT		ts.sm_name
  						FROM	dbo.tbSalesman ts
  						WHERE	ts.sm_id = @sm_id)
  				END																																	[params10],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 57

  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1  AND t.fun_id =@fun_id)							[params11],
  				CASE @country_id WHEN -1 THEN
  					(SELECT		tut.utexts_desc
  						FROM	tbsysUniqueTexts tut
  						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
  				ELSE
  					(SELECT		tc.country_desc
  						FROM	dbo.tbsysCountry tc
  						WHERE	tc.country_id = @country_id)
  				END																																	[params12],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 59
  				 --AND t.[lang_id] = @lang_id
  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)							[params13],
  				CASE @state_id WHEN -1 THEN
  					(SELECT		tut.utexts_desc
  						FROM	tbsysUniqueTexts tut
  						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
  				ELSE
  					(SELECT		ts.state_desc
  						FROM	dbo.tbsysState ts
  						WHERE	ts.state_id = @state_id)
  				END																																	[params14],
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 1040
  				 --AND t.[lang_id] = @lang_id
  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)							[params15],
  				CASE @option_saldo WHEN -1 THEN
  					(SELECT		tut.utexts_desc
  						FROM	tbsysUniqueTexts				tut
  						WHERE	tut.lang_id			= @lang_id
  						AND		tut.utexts_id		= 1)
  				ELSE
  					(SELECT		tov.optval_desc
  						FROM	dbo.tbsysOptionsValues			tov
  						WHERE	tov.optval_class	= 69
  						And		tov.optval_order	= @option_saldo
  						AND		tov.lang_id			= @lang_id)
  				END		[params16],

  				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 509
  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id = @fun_id)							[params17],
  			   			CASE @doc_number  WHEN 0 THEN
  				'---'
  			ELSE
  				@doc_number
  			END [params18],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 103
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params19],
			CASE @item_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ti.item_desc
						FROM	tbItem ti
						WHERE	ti.comp_id = @comp_id AND ti.item_id= @item_id)
			END		[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 28
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params21],

			CASE @bra_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tb.bra_desc
					FROM	dbo.tbBranch tb
					WHERE	tb.bra_id = @bra_id)
			END																									[params22],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
			 WHERE t.ctrl_id = 1324
			 --AND t.[lang_id] = @lang_id
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params23],

			CASE @df_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tdf.df_desc
					FROM	dbo.tbDocumentsFile tdf
					WHERE	tdf.df_id = @df_id)
			END																									[params24],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 5332
  				 --AND t.[lang_id] = @lang_id
  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)							[params25],
  				CASE @pricetype WHEN -1 THEN
  					(SELECT		tut.utexts_desc
  						FROM	tbsysUniqueTexts				tut
  						WHERE	tut.lang_id			= @lang_id
  						AND		tut.utexts_id		= 1)
  				ELSE
  					(SELECT		tov.optval_desc
  						FROM	dbo.tbsysOptionsValues			tov
  						WHERE	tov.optval_class	= 736
  						And		tov.optval_order	= @pricetype
  						AND		tov.lang_id			= @lang_id)
  				END		[params26]







END
GO


CREATE PROCEDURE [dbo].[spCommercialTransactions_getReportTotalSalesLoanDetail]
(
	@comp_id			INT,
	@lang_id			INT,
	@page_id			INT,

	@selection_id		INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@custsupp			INT,
	@sm_id				INT,
	@bra_id				INT,
	@country_id			INT,
	@state_id			INT,
	@option_saldo		INT,
	@user_id			INT,
	@Taxes				INT,
	@ck_id				INT,
	@brand_id			INT,
	@prof_id			INT,
	@intBranch4Lang		INT,
	@act_id				INT,
	@pro_id				INT,
	@sm2_id				INT,
	@user_idfilter		INT,
	@guid				VARCHAR(50)	,
	@dueDatefrom			DATETIME,
	@dueDateto				DATETIME
)
AS

	BEGIN
		SET NOCOUNT ON

		/*
		--PARA NO CARGAR 10 VECES LOS MISMOS TEXTOS DE PARÁMETROS, COMO USA EXACTAMENTE LOS MISMOS QUE EN REPORTE DE VENTAS, LE PUSE EN DURO LA PÄGINA PARA NO HACER DOBLE CARGA DE LO MISMO
		*/

		DECLARE @fun_id INT
		SET		@fun_id = 1

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------
		-- Testing
		-- ------------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@lang_id			INT,
				@page_id			INT,

				@selection_id		INT,
				@datefrom			DATETIME,
				@dateto				DATETIME,
				@custsupp			INT,
				@sm_id				INT,
				@bra_id				INT,
				@country_id			INT,
				@state_id			INT,
				@option_saldo		INT,
				@user_id			INT,
				@Taxes				INT,
				@ck_id				INT,
				@brand_id			INT,
				@prof_id			INT,
				@intBranch4Lang		INT,
				@act_id				INT,
				@pro_id				INT,
				@sm2_id				INT,
				@user_idfilter		INT,
				@guid				VARCHAR(50),
				@dueDatefrom		as date	='2000-01-01',
				@dueDateto			as date ='2911-10-31'

			SELECT
				@comp_id			=1,
				@lang_id			=2,
				@page_id			=100964,
				@selection_id		=-1,
				@datefrom			='2000-01-01',
				@dateto				='2911-10-31',
				@custsupp			=-1,
				@sm_id				=-1,
				@bra_id				= 1,
				@country_id			=-1,
				@state_id			=-1,
				@option_saldo		=-1,
				@user_id			= 119,
				@Taxes				= 1,
				@ck_id				= -1,
				@brand_id			= -1,
				@prof_id			= 1,
				@act_id				= -1,
				@pro_id				= -1,
				@sm2_id				= -1,
				@user_idfilter		= 1,
				@guid				= '6DDE0A8F-0F09-49A8-A31C-98AA69934363'
		*/
		-- ------------------------------------------------------------------------------------

			SET DATEFORMAT 'YMD'

			SET	@datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
			SET	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')
			DECLARE @lGuid	AS UNIQUEIDENTIFIER
			SET @lGuid		= CONVERT(UNIQUEIDENTIFIER,@guid)

			-- ------------------------------------------------------------------------
			-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
			-- ------------------------------------------------------------------------
				DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
				INSERT INTO @tblComplexFilter_Customer
					SELECT tcf.sl_id
						FROM tbComplexFilter tcf		WITH (NOLOCK)
						WHERE tcf.sl_guid = @lGuid     AND
									  tcf.sl_selected = 'True'
				IF @@ROWCOUNT = 0
					BEGIN
						INSERT INTO @tblComplexFilter_Customer
							SELECT tc.cust_id
							FROM tbCustomer tc			WITH (NOLOCK)
								WHERE tc.comp_id = @comp_id
					END
			-- ------------------------------------------------------------------------


			SELECT
				tct.ct_date,
				tc.cust_id,
				tctl.ctl_payDate,
				dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[Comprobante],
				tc.cust_taxNumber,
				tc.cust_name,
				tst.st_desc,
				tctl.ct_ATotal,
				tctl.ct_ABalance

				FROM tbCommercialTransactions						tct
				INNER JOIN tbUsers4BranchFilter						vubf	WITH (NOLOCK)
					ON  vubf.comp_id		= tct.comp_id			AND
						vubf.bra_id			= tct.bra_id			ANd
						vubf.[user_id]		= @user_id
				INNER JOIN dbo.vwCommercialTransactions_forSales	vwct	WITH (NOLOCK)
					ON  tct.comp_id			= vwct.comp_id			AND
						tct.bra_id			= vwct.bra_id			AND
						tct.ct_transaction	= vwct.ct_transaction
				INNER JOIN @tblComplexFilter_Customer				tmp
					ON	tmp.cust_id			= tct.cust_id
				INNER JOIN tbCommercialTransactionsLoan				tctl
					ON	tctl.comp_id		= tct.comp_id			AND
						tctl.ct_transaction = tct.ct_transaction
				INNER JOIN tbDocumentsFile							tdf		WITH (NOLOCK)
					ON	tdf.comp_id			= tct.comp_id			AND
						tdf.bra_id			= tct.bra_id			AND
						tdf.df_id			= tct.df_id
				INNER JOIN tbCustomer								tc
					ON	tc.comp_id			= tct.comp_id			AND
						tc.cust_id			= tct.cust_id
				INNER JOIN tbSalesman								sm		WITH (NOLOCK)
					ON  sm.comp_id			= tct.comp_id			AND
						sm.sm_id			= tct.sm_id
				INNER join tbCustomerKind							ck		WITH (NOLOCK)
					ON  ck.comp_id			= tc.comp_id			AND
						ck.ck_id			= tc.ck_id
				LEFT JOIN tbSalesTerms								tst		WITH (NOLOCK)
					ON  tst.comp_id			= tct.comp_id			AND
						tst.st_id			= tct.st_id
				LEFT JOIN tbActivity								ta		WITH (NOLOCK)
					ON  ta.comp_id			= tc.comp_id AND
						ta.act_id			= tc.act_id
			WHERE	tct.comp_id				=	@comp_id							AND
					vwct.sd_isReceipt		= 'False'								AND
					vwct.sd_isInBalance		= 'True'								AND
					(@bra_id		= -1	OR tct.bra_id		= @bra_id)			AND
					(@custsupp		= -1	OR tct.cust_id		= @custsupp)		AND
					tct.ct_date			BETWEEN	@datefrom			AND @dateto		AND
					tctl.ctl_payDate	BETWEEN	@dueDatefrom		AND @dueDateto	AND
					(@sm_id			= -1	OR tct.sm_id		= @sm_id)			AND
					(@pro_id		= -1	OR tct.pro_id		= @pro_id)			AND
					(@act_id		= -1	OR ta.act_id		= @act_id)			AND
					CASE
	   					WHEN @selection_id	=	-1 AND (tct.sd_id = 1 OR tct.sd_id = 3 OR tct.sd_id = 4)										THEN 1
	   					WHEN @selection_id	=	-1																								THEN 0
	   					WHEN tdf.sd_id		=	@selection_id																					THEN 1
	   					WHEN @selection_id	=   -5 AND (tct.sd_id = 1 OR tct.sd_id = 3 OR tct.sd_id = 4 OR tct.sd_id = 21 OR tct.sd_id = 23)	THEN 1
	   					ELSE															 0
	   				END																															= 1	AND
					(
					(@option_saldo	=	-1)									OR
					(@option_saldo	=	0	AND /* MOS 09-2022: son CUOTAS!!!!!!!   tct.ct_Abalance*/	 tctl.ct_ABalance	<>	0)	OR
					(@option_saldo	=	1	AND /* MOS 09-2022: son CUOTAS!!!!!!!   tct.ct_Abalance*/	 tctl.ct_ABalance	=	0)
					)															AND
					(@ck_id			= -1 or ck.ck_id				= @ck_id  )	AND
					CASE
	   					WHEN @brand_id = -1 THEN 1
	   					WHEN EXISTS(	SELECT TOP 1 1									-- MOS 532
												FROM tbItemTransactions tit					WITH (NOLOCK)
												INNER JOIN tbitem	 it						WITH (NOLOCK)
													ON		it.comp_id = tit.comp_id
														AND it.item_id = ISNULL(tit.item_id,tit.item_idfromPreInvoice) -- MOS 01-2022, para que tome las marcas de los items de factura anticipada
														--AND it.item_id = tit.item_id
	                              				WHERE	tit.comp_id			= tct.comp_id
	                              					AND tit.ct_transaction	= tct.ct_transaction
	                              					AND it.brand_id			= @brand_id
											) THEN 1
	   					ELSE	0
	   				END	= 1																	AND
					(@country_id		= -1	OR tc.country_id		= @country_id)		AND
					(@state_id			= -1	OR tc.state_id			= @state_id)		AND
					(@sm2_id			= -1	OR tc.sm_id_2			= @sm2_id)			AND
					(@user_idfilter		= -1	OR tct.[user_id]		= @user_idfilter)	AND
					ISNULL(tdf.df_excludereports, 'False')				= 'False'			AND
					tct.sd_id			= 1

			ORDER BY tct.ct_date, Comprobante
			OPTION ( MAXDOP 1 )


			EXEC [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id



			/* devolución de parámetros recibidos */
			DECLARE @related_page_id INT
			SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = 10012


			/*************************************************************************************************************/
			/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
			/*
					SELECT	t.ctrl_id,	t.[text_desc]
					FROM	[tbsysTexts]				t
							inner join [tbsysControls]	c
							on c.[ctrl_id] = t.[ctrl_id]
					where	t.[lang_id]	= @lang_id
					and		t.[page_id]	= @related_page_id
					and		t.[type_id]	= 1
			*/
			/*************************************************************************************************************/


			SELECT
				(SELECT
					tswn.word_desc
					FROM [tbsysTextsNew]				t
					INNER JOIN tbSysWordsNew			tswn
						ON	tswn.lang_id	= @lang_id	AND
							tswn.wordsi_id	= t.wordsi_id
					WHERE	t.ctrl_id		= 398				AND
							t.[page_id]		= @related_page_id	AND
							t.[type_id]		= 1					AND
							t.fun_id		= @fun_id)			[params1],

				CASE @selection_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		vsdc.sd_desc
						FROM	dbo.vwSysDocumentsCustomer vsdc
						WHERE	vsdc.sd_id = @selection_id)
				END																																[params2],

				(SELECT
					tswn.word_desc
					FROM [tbsysTextsNew]						t
					INNER JOIN tbSysWordsNew					tswn
						ON	tswn.lang_id	= @lang_id			AND
							tswn.wordsi_id	= t.wordsi_id
					 WHERE	t.ctrl_id		= 6366				AND	--177				AND
							t.[page_id]		= @related_page_id	AND
							t.[type_id]		= 1					AND
							t.fun_id		= @fun_id)				[params3],

				@datefrom [DateParams1],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
					 WHERE t.ctrl_id = 6367--384
					 --AND t.[lang_id] = @lang_id
					 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)				[params5],

					@dateto [DateParams2],
					--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))					[params6],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						 WHERE t.ctrl_id = 402
						 --AND t.[lang_id] = @lang_id
						 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id) [params7],

						CASE @custsupp WHEN -1 THEN
							(SELECT	tut.utexts_desc
							 FROM	tbsysUniqueTexts tut
							 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT tc.cust_name
							 FROM	dbo.tbCustomer tc
							 WHERE tc.comp_id = @comp_id AND 	tc.cust_id  = @custsupp)
						END																																	[params8],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						 WHERE t.ctrl_id = 172
						 --AND t.[lang_id] = @lang_id
						 and t.[page_id] = @related_page_id and t.[type_id]	= 1  AND t.fun_id =@fun_id)						[params9],

						CASE @sm_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT		ts.sm_name
								FROM	dbo.tbSalesman ts
								WHERE	ts.comp_id = @comp_id AND ts.sm_id = @sm_id)
						END																																	[params10],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						 WHERE t.ctrl_id = 57
						 --AND t.[lang_id] = @lang_id
						 and t.[page_id] = @related_page_id and t.[type_id]	= 1  AND t.fun_id =@fun_id)							[params11],

						CASE @country_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT		tc.country_desc
								FROM	dbo.tbsysCountry tc
								WHERE	tc.country_id = @country_id)
						END																																	[params12],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						 WHERE t.ctrl_id = 59
						 --AND t.[lang_id] = @lang_id
						 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)							[params13],

						CASE @state_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT		ts.state_desc
								FROM	dbo.tbsysState ts
								WHERE	ts.state_id = @state_id)
						END																																	[params14],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						 WHERE t.ctrl_id = 1040
						 --AND t.[lang_id] = @lang_id
						 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)							[params15],

						CASE @option_saldo WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts				tut
								WHERE	tut.lang_id			= @lang_id
								AND		tut.utexts_id		= 1)
						ELSE
							(SELECT		tov.optval_desc
								FROM	dbo.tbsysOptionsValues			tov
								WHERE	tov.optval_class	= 69
								And		tov.optval_order	= @option_saldo
								AND		tov.lang_id			= @lang_id)
						END		[params16],

						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
						 WHERE t.ctrl_id = 241
						 --AND t.[lang_id] = @lang_id
						 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)							[params17],


							(SELECT		tov.optval_desc
								FROM	dbo.tbsysOptionsValues			tov
								WHERE	tov.optval_class	= 1
								And		tov.optval_id	= @Taxes
								AND		tov.lang_id			= @lang_id)			[params18],


						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
								 WHERE t.ctrl_id = 372
								 --AND t.[lang_id] = @lang_id
								 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)					[params19],

								CASE @ck_id WHEN -1 THEN
									(SELECT		tut.utexts_desc
										FROM	tbsysUniqueTexts tut
										WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
								ELSE
									(SELECT		tck.ck_name
										FROM	dbo.tbCustomerKind tck
										WHERE	tck.comp_id = @comp_id AND  tck.ck_id = @ck_id)
								END																									[params20],


							(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
								 WHERE t.ctrl_id = 73
								 --AND t.[lang_id] = @lang_id
								 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params21],

								CASE @brand_id WHEN -1 THEN
									(SELECT		tut.utexts_desc
										FROM	tbsysUniqueTexts tut
										WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
								ELSE
									(SELECT		tb.brand_desc
										FROM	dbo.tbBrand tb
										WHERE	tb.comp_id = @comp_id AND  tb.brand_id = @brand_id)
								END																									[params22],


									(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
								 WHERE t.ctrl_id = 28
								 --AND t.[lang_id] = @lang_id
								 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params23],

								CASE @bra_id WHEN -1 THEN
									(SELECT		tut.utexts_desc
										FROM	tbsysUniqueTexts tut
										WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
								ELSE
									(SELECT		tb.bra_desc
										FROM	dbo.tbBranch tb
									 WHERE tb.comp_id= @comp_id AND 	tb.bra_id = @bra_id)
								END																									[params24],



							(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
								 WHERE t.ctrl_id = 2379
								 --AND t.[lang_id] = @lang_id
								 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params25],

								CASE @act_id WHEN -1 THEN
									(SELECT		tut.utexts_desc
										FROM	tbsysUniqueTexts tut
										WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
								ELSE
									(SELECT		ta.act_desc
										FROM	dbo.tbActivity ta
										WHERE	ta.comp_id = @comp_id  and ta.act_id	= @act_id)
								END																									[params26],


								(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
									 WHERE t.ctrl_id = 4241
									 --AND t.[lang_id] = @lang_id
									 and t.[page_id] = @related_page_id and t.[type_id]	= 1  AND t.fun_id =@fun_id)							[params27],

									CASE @pro_id WHEN -1 THEN
										(SELECT		tut.utexts_desc
											FROM	tbsysUniqueTexts tut
											WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
									ELSE
										(SELECT tp.pro_desc
											 FROM	tbProject tp
										 WHERE tp.comp_id = @comp_id AND 	tp.pro_id  = @pro_id)
									END																																	[params28],

								(SELECT
									tswn.word_desc
									FROM [tbsysTextsNew]						t
									INNER JOIN tbSysWordsNew					tswn
										ON	tswn.lang_id	= @lang_id			AND
											tswn.wordsi_id	= t.wordsi_id
									 WHERE	t.ctrl_id		= 6368				AND
											t.[page_id]		= @related_page_id	AND
											t.[type_id]		= 1					AND
											t.fun_id		= @fun_id)				[params29],

								@dueDatefrom [DateParams3],

								(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
									 WHERE t.ctrl_id = 6369
									 --AND t.[lang_id] = @lang_id
									 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)				[params30],

									@dueDateto [DateParams4]

	END
GO







CREATE PROCEDURE [dbo].[spCommercialTransactions_getReprint]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@ct_transaction		INT,
	@user_id			INT
)
AS

BEGIN



    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	-- ---------------------------------------------
	-- Testing
	-- ---------------------------------------------
	/*
	declare @comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@ct_transaction		INT
	SELECT	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@ct_transaction		=1827
	*/
	-- ---------------------------------------------


		SELECT	'0'																				[ ],
				dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)	[doc_number],
				convert(decimal(18,2),round(tct.ct_total,2))									[amount],
				convert(varchar,tct.ct_transaction) + '-' + '0'	+ '-' + '0'						[ID]

			FROM	tbCommercialTransactions tct

					INNER JOIN tbUsers4BranchFilter							vubf
					ON		vubf.comp_id			=  tct.comp_id
					AND		vubf.bra_id				=  tct.bra_id
					AND		vubf.[user_id]			=  @user_id

			WHERE	tct.comp_id			= @comp_id
			--AND		tct.bra_id			= @bra_id
			AND		tct.ct_transaction	= @ct_transaction

	UNION

		SELECT	CONVERT(VARCHAR,ttn.tax_class)													[ ],
				ttn.tax_desc																	[doc_number],
				convert(decimal(18,2),round(ttm.tm_total,2))									[amount],
				convert(varchar,ttm.ct_transaction) + '-' +
				convert(varchar,
								CASE
									WHEN ttn.tax_class = 280 THEN 14							-- GANANCIAS
									WHEN ttn.tax_class = 281 THEN 12							-- IVA
									WHEN ttn.tax_class = 282 THEN 16							-- SUSS
									WHEN ttn.tax_class = 283 THEN 17							-- OTRAS
									WHEN ttn.tax_class > 200 AND ttn.tax_class <= 250 THEN 13	-- IIBB
									ELSE 13
								END
						)							+ '-' + convert(varchar,ttm.tm_transaction)
																								[ID]

			FROM	tbTaxMovements								ttm
					INNER JOIN tbTaxName						ttn
					ON	ttn.comp_id		= ttm.comp_id
					AND ttn.tax_id		= ttm.tax_id
					INNER JOIN vwsysTaxClassALL_Retentions		vtcar
					ON	vtcar.tax_class = ttn.tax_class

			WHERE	ttm.comp_id			= @comp_id
			--AND		ttm.bra_id			= @bra_id
			AND		ttm.ct_transaction	= @ct_transaction
			AND		ttm.tm_total		> 0


			ORDER BY 1


END
GO









CREATE PROCEDURE [dbo].[spCommercialTransactions_getTaxEngineOverAll]
(
	@comp_id	INT,
	@ten_id		INT
)
AS


BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	SET DATEFORMAT 'ymd'


	DECLARE @printTotalByCt			BIT,
			@ten_FilterByValue		BIT,
			@ten_sdldGroup			int


	SELECT	@printTotalByCt			= ISNULL(tten.ten_printTotalByCt,'false'),
			@ten_FilterByValue		= ISNULL(tten.ten_FilterByValue, 'false'),
			@ten_sdldGroup			= ISNULL(tten.ten_sdIdGroup,1)
		FROM	tbTaxEngineName			tten
		WHERE	tten.comp_id			= @comp_id
			AND	tten.ten_id				= @ten_id





	--Variables del Primer Cursor
	/******************************************/
	DECLARE
		@ct_transaction	INT,
		@tax_id			INT,
		@date			DATETIME,
		@name			VARCHAR(100),
		@cuit			VARCHAR(20),
		@document		VARCHAR(100),
		@subtotal		DECIMAL(19,2),
		@total			DECIMAL(19,2),
		@decTotalByCT   DECIMAL(19,2),
		@column_name	VARCHAR(100),
		@sd_isCredit	BIT,
		@nogravado		DECIMAL(19,2),

		--STL 12/11/2010
		@ct_CAI			NVARCHAR(50),
		@ct_CAIDate		DATETIME,
		@decDiscount    DECIMAL(19,4)
	DECLARE @bitHaveIvaTax AS BIT


	--Variables del Segundo Cursor
	/******************************************/
	DECLARE
		@tm_subtotal	DECIMAL(19,2),
		@percentaje		DECIMAL(19,2),
		@tm_total		DECIMAL(19,2),
		@tm_totalIVA	DECIMAL(19,2),
		@newRow			BIT,
		@printSubtotal	BIT,
		@printTaxSubTot	BIT,
		@column_name2	VARCHAR(50),
		@tent_column2	INT,
		@time			BIT,
		@identity		INT,
		@total_total	DECIMAL(19,2),
		@sd_id			INT,
		@tax_class		INT,
		@ct_discount	DECIMAL(19,2)
		--@tent_isHidden	BIT




	/*	cursor que recupera las transacciones comerciales que se seleccionaron en [spCommercialTransactions_getReportTaxEngineOverSales2]
		or en [spCommercialTransactions_getReportTaxEngineOverPurchase]																		*/
	declare cursor_CT_gRTEOP CURSOR LOCAL  FAST_FORWARD FOR
	SELECT	tmpct.ct_transaction,
			tmpct.ct_date,
			tmpct.name,
			tmpct.Number,

			--STL 12/11/2010
			tmpct.ct_CAI,
			tmpct.ct_CAIDate,
			----------------

			tmpct.Comprobante,
			tmpct.ct_subtotal,
			tmpct.sd_isCredit,
			sd_id
		FROM #tmpCommercialTransactions		tmpct

	OPEN cursor_CT_gRTEOP

	FETCH NEXT FROM cursor_CT_gRTEOP
	INTO	@ct_transaction,
			@date,
			@name,
			@cuit,

			--STL 12/11/2010
			@ct_CAI,
			@ct_CAIDate,
			----------------

			@document,
			@subtotal,
			@sd_isCredit,
			@sd_id


	/* loop por transacciones comerciales */
	WHILE @@FETCH_STATUS = 0
	BEGIN

		SET @bitHaveIvaTax			= 'False'
		SELECT TOP 1 @bitHaveIvaTax = 'True'
			FROM tbTaxMovements ttm
			INNER JOIN tbTaxName ttn
				ON		ttn.comp_id = ttm.comp_id
					AND ttn.tax_id	= ttm.tax_id
			WHERE	ttm.comp_id			= @comp_id
				AND ttm.ct_transaction	= @ct_transaction
				AND ttn.tax_class		= 1



		-- Si NO es una Orden de Pago o mas adelante un recibo de Cobranza con Descuento.
		IF not @sd_id IN (6,13,106) OR @ten_sdldGroup <> 1
			BEGIN

				SET @decTotalByCT = @subtotal - (	SELECT IsNull(tct.ct_discount,0) * CASE WHEN @sd_isCredit='True' THEN -1 ELSE 1 END
														FROM tbCommercialTransactions tct
		                                 				WHERE	tct.comp_id				= @comp_id
		                                 					AND tct.ct_transaction		= @ct_transaction)	-- Pone el NETO Sin Impuestos de cada ct_Transaction.-

				/* con cada documento recuperado se hace un insert en la temporal con los datos fijos */
				INSERT INTO [#tmpFinalData]	(ct_transaction,	ct_date,	supp_name,	supp_number,	[document]	, ct_CAI ,  ct_CAIDate)
				VALUES						(@ct_transaction,	@date,		@name,		@cuit,			@document	, @ct_CAI, @ct_CAIDate)


				/* se recupera el valor del indentity del insert recién efectuado y se incializa la variable de totales */
				SET @identity		= @@identity
				SET @total_total	= 0

				-- ------------------------------------------------------------------------------------
				-- Se calculan los conceptos e items que no tienen ningun impuesto asociado
				-- ------------------------------------------------------------------------------------
				SET		@nogravado = 0

				--obtenemos la sumatoria de los movimientos de conceptos de compra que no tienen impuestos asociados
				--y lo almacenamos en @nogravado


				-- MOS- 01-2012
				-- se puso la funcion de tipo de cambio
				--		  (IsNull(SUM(tpcm.pcm_total),0) *  CASE WHEN @sd_isCredit='True' THEN -1 ELSE 1 END),
				SELECT	@nogravado				= (IsNull(SUM(
												  dbo.fnGetExchange2( tpcm.comp_id,
																	  tpcm.pcm_total,
																	  tpcm.curr_id,
																	  tct.curr_id_transaction,
																	  tct.curr_id4Exchange,
																	  tct.curr_id_transaction,
																	  tCT.ct_curr_IdExchange,
																	  'false')
														      ),0) *	CASE
																			WHEN @sd_isCredit='True' THEN -1
																			ELSE 1
																		END)
					FROM	tbPurchaseConceptMovements		tpcm	WITH (NOLOCK)
					INNER JOIN tbCommercialTransactions		tct		WITH (NOLOCK)
						ON		tct.comp_id			= tpcm.comp_id
							AND tct.ct_transaction	= tpcm.ct_transaction
					WHERE	tpcm.comp_id		= @comp_id
						AND	tpcm.ct_transaction	= @ct_transaction
						AND	tpcm.pcm_id			NOT	IN	(				-- LENTOOOOOOO, arreglar pls
															SELECT	ttm.pcm_id
																FROM	tbTaxMovements		ttm		WITH (NOLOCK)
																INNER JOIN tbTaxName		ttn		WITH (NOLOCK)  --MOS 05-2016
																	ON		ttn.comp_id		= ttm.comp_id
																		AND ttn.tax_id		= ttm.tax_id
																WHERE	ttm.comp_id			= tpcm.comp_id
																	AND	ttm.bra_id			= tpcm.bra_id
																	AND	ttm.ct_transaction	= tpcm.ct_transaction
																	AND	NOT ttm.pcm_id IS NULL
																	AND ttn.tax_class = 1   -- Del Tipo IVA
																	AND ttn.tax_TaxEngineColumn4ThisTaxIsNoGravado = 'False'
														)

				--obtenemos la sumatoria de los items de transacciones que no tienen impuestos del tipo IVA asociados y lo almacenamos en @nogravado
				SELECT	@nogravado				= @nogravado + (ISNULL(SUM(tit.it_price * tit.it_qty *	CASE
																											when tct.sd_id < 100 THEN	1
																											ELSE						tit.it_exchangeToBranchCurrency
																										END
																			),0) *	CASE
																						WHEN @sd_isCredit='True' THEN -1
																						ELSE 1
																					END)
					FROM	tbItemTransactions				tit
					INNER JOIN tbCommercialTransactions tct
						ON		tct.comp_id			= tit.comp_id
							AND tct.ct_transaction	= tit.ct_transaction
					WHERE	tit.comp_id			= @comp_id
						AND	tit.ct_transaction	= @ct_transaction
						-- --------------------------------------------------------------------------------------------------------------------
						-- Si es una NC de RMA y lo procesaron se generaba en el mismo IT_Transaction por lo que NO se deben tomar en cuenta
						-- --------------------------------------------------------------------------------------------------------------------
						AND		CASE
						   		    WHEN tct.sd_id =  103 AND tit.it_qty < 0	THEN	0
						   		    ELSE												1
						   		END	 = 1
						-- --------------------------------------------------------------------------------------------------------------------
						-- OJOOOO, esto hace re LENTO!
						AND	tit.it_transaction	NOT IN	(		-- LENTOOOOOOO, arreglar pls
															SELECT	ttm.it_transaction
																FROM	tbTaxMovements		ttm		WITH (NOLOCK)
																INNER JOIN tbTaxName		ttn		WITH (NOLOCK)
																	ON		ttn.comp_id		= ttm.comp_id
																		AND ttn.tax_id		= ttm.tax_id
                                  								WHERE	ttm.comp_id			= tit.comp_id
                                  									AND	ttm.bra_id			= tit.bra_id
                                  									AND	ttm.ct_transaction	= tit.ct_transaction
               														AND	ttm.it_transaction IS NOT NULL
                                  									AND ttn.tax_class = 1   -- Del Tipo IVA
                                  									AND ttn.tax_TaxEngineColumn4ThisTaxIsNoGravado = 'False'
														)

--==
--SELECT @nogravado = 0
--==


				--si la variable @nogravado es diferente de 0, se actualiza el campo nogravado en la tabla temporal con los datos finales
				IF @nogravado <> 0
					UPDATE	#tmpFinalData
						SET nogravado = nogravado + ISNULL(@nogravado,0)
						WHERE tmp_id  = @identity

				SET @total_total	  = @total_total + isnull(@nogravado,0)
				-- ------------------------------------------------------------------------------------

				-- ------------------------------------------------------------------------------------
				-- Comienzo del Cursor de Impuestos de cada transacción comercial
				-- MOS: Agregue el left Join y los IsNull con tbTaxEngineName_Taxes
				-- ------------------------------------------------------------------------------------
				DECLARE cursor_Calc CURSOR LOCAL  FAST_FORWARD FOR
				SELECT	sum(case
								when @sd_isCredit = 'False' THEN isnull(ttm.tm_subtotal,0)
								ELSE							(isnull(ttm.tm_subtotal,0) * -1)
							END)														[tm_subtotal],
						ttm.percentaje,
						sum(case
								when @sd_isCredit = 'False' THEN isnull(ttm.tm_total,0)
								ELSE							(isnull(ttm.tm_total,0) * -1)
							END)														[tm_total],
						isnull(ttent.tent_newRow,1)										[tent_newRow]	,
						IsNull(ttent.tent_printSubtotal,'False')						[tent_printSubtotal],
						IsNull(ttent.tent_printTAXSubTot,'False')						[tent_printTAXSubTot],
						IsNull(ttent.tent_columnName,'Total')							[tent_columnName],
						tmpc.id,
						ttn.tax_class

					FROM	tbTaxMovements									ttm		WITH (NOLOCK)
							LEFT JOIN tbTaxEngineName_Taxes					ttent	WITH (NOLOCK)
								ON	ttm.comp_id			= ttent.comp_id
								AND ttm.tax_id			= ttent.tax_id
								AND ttent.ten_id		= @ten_id
							LEFT JOIN tbTaxEngineName_Taxes					ttent1	WITH (NOLOCK)
								ON		ttent1.comp_id = @comp_id
									AND ttent1.tent_id = ttent.tent_id4Summary
							LEFT JOIN #tmpColumns							tmpc
								ON	 tmpc.tent_column = IsNull(ttent1.tent_column,ttent.tent_column)
							INNER JOIN tbTaxName							ttn		WITH (NOLOCK)
								ON		ttn.comp_id		= ttm.comp_id
									AND ttn.tax_id		= ttm.tax_id
					WHERE	ttm.comp_id			= @comp_id
						AND	ttm.ct_transaction	= @ct_transaction
					GROUP BY	ttm.percentaje,
								ttent.tent_newRow,
								ttent.tent_printSubtotal,
								ttent.tent_printTAXSubTot,
								ttent.tent_columnName,
								ttent.tent_column,
								tmpc.id,
								ttn.tax_class
					ORDER BY	ttent.tent_column

				-- ------------------------------------------------------------------------------------
				-- ATENCION: para sistemas viejos anteriores a Agosto de 2010 se debe correr el script
				--			 que figura
				--           debajo de spSystem_generateDatabaseUpdate
				-- ------------------------------------------------------------------------------------

				OPEN cursor_Calc
				SET @time = 'true'

				FETCH NEXT FROM cursor_Calc
				INTO @tm_subtotal,
					 @percentaje,
					 @tm_total,
					 @newRow,
					 @printSubtotal,
					 @printTaxSubTot,
					 @column_name,
					 @tent_column2,
					 @tax_class

				WHILE @@FETCH_STATUS = 0
				BEGIN

					--SELECT @ct_transaction, @tm_subtotal,@percentaje,@tm_total,@newRow [@newRow],@printSubtotal [@printSubtotal],@printTaxSubTot [@printTaxSubTot],@column_name,@tent_column2
					-- MOS: se elimina ya que se hace el left join arriba, contra la taxengine_taxes
					IF @time = 'true'
						BEGIN
							/* si es el primer registro leido se hace el update con el valor del primer impuestro encontrado */

							--IF ISNULL(@tent_isHidden,'false') = 'false'
							--BEGIN
								SET @time = 'false'
								IF not @tent_column2 IS NULL
									BEGIN
										SET @tm_total		= ROUND(@tm_total,2)
										SET @decTotalByCT	= @decTotalByCT + @tm_total
										EXEC ('update #tmpFinalData set [Columna' + @tent_column2 + '] = [Columna' + @tent_column2 + '] + ' +   @tm_total    + ' where tmp_id = ' + @identity  )
									END
						END
					ELSE
						BEGIN
							--SELECT @newRow
							/* si no es el primer registro */
							IF @newRow = 'true' AND @sd_id NOT IN (140,141,142,  /*Nuevo Extracto Bancario*/ 143,144)  -- OJO se puso esto porque sino duplicaba en los mov. bancarios con un negativo y positivo.!!!
								BEGIN

									/* si el impuesto tiene la marca de nueva fila se realiza un nuevo insert */
									INSERT INTO [#tmpFinalData]
										(ct_transaction,
										 ct_date,
										 supp_name,
										 supp_number,
										 [document],
										 ct_CAI,
										 ct_CAIDate	)
									VALUES
										(@ct_transaction,
										 @date,
										 @name,
										 @cuit,
										 @document,
										 @ct_CAI,
										 @ct_CAIDate)

									/* se recupera el valor del indentity del insert recién efectuado y se incializa la variable de totales */
									SET @identity		= @@identity

								END

							IF not @tent_column2 IS NULL
								BEGIN

									SET @decTotalByCT = @decTotalByCT + @tm_total
									EXEC ('update #tmpFinalData set [Columna'+ @tent_column2 + '] = [Columna' + @tent_column2 + '] + ' + @tm_total + ' where tmp_id = ' + @identity  )
								END

						END


					/* ver si esto va acá o al principio de este loop */
					SELECT @total_total = @total_total +  isnull(@tm_subtotal,0) + isnull(@tm_total,0)
						--BEGIN

					-- Si No es NO GRAVADA en su totalidad
					IF		@tm_subtotal <> 0 AND @tm_total <> 0
						AND ( (@sd_id < 100 and @tm_subtotal <> @nogravado) OR @sd_id >= 100)   -- MOS 10-2011
						BEGIN

							-- Si es una Venta y no tiene IVA
							IF @sd_id < 100 AND @tax_class <> 1
								BEGIN
									-- si no hay impiestos del tipo de iva, grabar 1 solo importe neto
									--SELECT '1'
									--update #tmpFinalData set gravado	= isnull(@tm_subtotal,0) where tmp_id = @identity
									update #tmpFinalData set gravado	= IsNull(gravado,0) where tmp_id = @identity
									IF @bitHaveIvaTax='False'
										BEGIN
											SET @bitHaveIvaTax = 'False'	-- Para que solo lo haga una sola vez.-
											update #tmpFinalData set exento	= ISNULL(exento,0)	+ isnull(@tm_subtotal,0) where tmp_id = @identity

										END
								END

							-- Si es una Venta y SI tiene IVA
							ELSE IF @sd_id < 100 AND @tax_class = 1
								BEGIN
									--SELECT '2'
									update #tmpFinalData set gravado	= isnull(gravado,0)	+ isnull(@tm_subtotal,0) where tmp_id = @identity
								END
							ELSE
								BEGIN
								--SELECT '3'
									update #tmpFinalData set gravado	= ISNULL(gravado,0)	+ isnull(@tm_subtotal,0) where tmp_id = @identity
								END

						END
					ELSE
						BEGIN	-- Pone como EXENTO si Hubo Impuestos del tipo IVA y el importe era CERO

							IF @tm_subtotal <> 0 AND @tm_total = 0 AND (@sd_id >= 100 OR (@tax_class = 1))
								BEGIN
									update #tmpFinalData set exento	= ISNULL(exento,0) + (isnull(@tm_subtotal,0) /*- ISNULL(@nogravado,0)*/) where tmp_id = @identity
								END
						END
						--END
					-- MOS: Se paso a cada Update
					--SET @decTotalByCT = @decTotalByCT + @tm_total








					FETCH NEXT FROM cursor_Calc
					INTO	@tm_subtotal,
							@percentaje,
							@tm_total,
							@newRow,
							@printSubtotal,
							@printTaxSubTot,
							@column_name,
							@tent_column2,
							@tax_class

				END



				CLOSE cursor_Calc
				DEALLOCATE cursor_Calc
				-- ------------------------------------------------------------------------------------
				-- Fin Cursor de tbTaxMovements (lo recorre x cada ct_transaction
				-- ------------------------------------------------------------------------------------


				-- ------------------------------------------------------------------------------------
				-- Pone en el Ultimo total de cada ct_transaction el total general del mismo.-
				-- ------------------------------------------------------------------------------------
				UPDATE 	#tmpFinalData
					SET 	total		= @decTotalByCT
					WHERE	tmp_id		= @identity
				-- ------------------------------------------------------------------------------------


				-- 1-  MOS 08-2014 para Gromanti
				-- ------------------------------------------------------------------------------------
				-- Verifica si hay algun error en la definicion del reporte de impuestos
				-- por ejemplo, que falte algun impuesto para algun comprobante
				-- Solo lo hace si el documento NO es para solo calculo de impuestos (Ventas)
				-- ------------------------------------------------------------------------------------
				DECLARE @decCommercialTransactionTotal		AS DECIMAL(19,4)
				DECLARE @bitCommercialTransactionOnlyTaxes	AS BIT
				SET		@bitCommercialTransactionOnlyTaxes	= 'false'

				SELECT @decCommercialTransactionTotal		= tct.ct_total ,
					   @bitCommercialTransactionOnlyTaxes	= ISNULL(tdf.df_SaleOrder_EmmitionOnlyTaxes,'False')
					FROM tbCommercialTransactions tct WITH (NOLOCK)
					LEFT JOIN tbDocumentsFile tdf
						ON	tdf.comp_id = tct.comp_id AND
							tdf.df_id	= tct.df_id
					WHERE	tct.comp_id			= @comp_id
						AND tct.ct_transaction	= @ct_transaction

				IF @bitCommercialTransactionOnlyTaxes	= 'False'
					BEGIN
						IF Abs(Abs(@decTotalByCT) - ABS((@decCommercialTransactionTotal))) > 0.5
							BEGIN
								UPDATE 	#tmpFinalData
									--CUSTOM_GN_001
									SET 	document	= '* Error* ' + DOCUMENT
									--CUSTOM_GN_002
									WHERE	tmp_id		= @identity
							END
					END
				-- ------------------------------------------------------------------------------------


				-- 2- Idem en OverSales2  MOS 08-2014 para Gromanti
				-- -------------------------------------------------------
				-- Si es un comprobante de SOLO IMPUESTOS, pone en cero
				-- los netos.
				-- -------------------------------------------------------
				UPDATE #tmpFinalData
					SET gravado=0,nogravado=0,exento=0
					FROM #tmpFinalData tmp
					INNER JOIN tbCommercialTransactions tct
						ON tct.ct_transaction = tmp.ct_transaction
					INNER JOIN tbDocumentsFile tdf
						ON	tdf.comp_id = tct.comp_id AND
							tdf.df_id	= tct.df_id
					WHERE	tmp.tmp_id	= @identity AND
							tdf.df_SaleOrder_EmmitionOnlyTaxes = 'True'
				-- -------------------------------------------------------




				-- ----------------------------------------------------
				-- Arregla si es una Liquidacion de Tarjeta de Credito
				-- ----------------------------------------------------
				IF @sd_id IN (140,141,142,  /*Nuevo Extracto Bancario*/ 143,144 )
					BEGIN
						DECLARE @decCreditCardLiqTaxTotal  AS DECIMAL(19,2)
						DECLARE @decCreditCardLiqGravado   AS DECIMAL(19,2)
						DECLARE @decCreditCardLiqNoGravado AS DECIMAL(19,2)
						DECLARE @decCreditCardLiqExento    AS DECIMAL(19,2)

						SELECT  @decCreditCardLiqGravado =	SUM(
																CASE
																	WHEN IsNull(tpc.puco_TaxEngineColumn4Bancking,1) = 1 THEN ISNULL(tpcm.pcm_total,0)
																	ELSE 0
																END),
								@decCreditCardLiqNoGravado =SUM(
																CASE
																	WHEN IsNull(tpc.puco_TaxEngineColumn4Bancking,1) = 2 THEN ISNULL(tpcm.pcm_total,0)
																	ELSE 0
																END),
								@decCreditCardLiqExento =	SUM(
																CASE
																	WHEN IsNull(tpc.puco_TaxEngineColumn4Bancking,1) = 3 THEN ISNULL(tpcm.pcm_total,0)
																	ELSE 0
																END)
						FROM tbPurchaseConceptMovements tpcm
						INNER JOIN tbPurchaseConcept tpc
							ON	tpc.comp_id = tpcm.comp_id			AND
								tpc.puco_id = tpcm.puco_id
						WHERE	tpcm.comp_id		= @comp_id		AND
								tpcm.ct_transaction = @ct_transaction

						SELECT @decCreditCardLiqTaxTotal = SUM(ttm.tm_total)
							FROM tbTaxMovements ttm
							WHERE	ttm.comp_id			= @comp_id	AND
									ttm.ct_transaction	= @ct_transaction

						IF @sd_id = 140 OR @sd_id = 143  -- Entrada o extracto bancario  (Se puso el 144 x un problema en Nucleo para que no se alteren los mov. anteriores)
							BEGIN
								SET @decCreditCardLiqGravado	= @decCreditCardLiqGravado		* -1
								SET @decCreditCardLiqNoGravado	= @decCreditCardLiqNoGravado	* -1
								SET @decCreditCardLiqExento		= @decCreditCardLiqExento		* -1
								SET @decCreditCardLiqTaxTotal   = @decCreditCardLiqTaxTotal		* -1
							END

						UPDATE #tmpFinalData
							SET  gravado	= ISNULL(@decCreditCardLiqGravado,0),
								 nogravado	= ISNULL(@decCreditCardLiqNoGravado,0),
								 exento     = ISNULL(@decCreditCardLiqExento,0),
								 Total		= ISNULL(@decCreditCardLiqGravado,0) + ISNULL(@decCreditCardLiqNoGravado,0) + ISNULL(@decCreditCardLiqExento,0) + ISNULL(@decCreditCardLiqTaxTotal,0)
							where tmp_id	= @identity
					END
				-- ----------------------------------------------------



			END

				-- ------------------------------------------------------------------------------------
		ELSE	-- Es una Orden de Pago o Recibo con Descuento
				-- ------------------------------------------------------------------------------------

			BEGIN

				/* con cada documento recuperado se hace un insert en la temporal con los datos fijos */
				INSERT INTO [#tmpFinalData]	(ct_transaction,	ct_date,	supp_name,	supp_number,	[document]	, ct_CAI ,  ct_CAIDate)
				VALUES						(@ct_transaction,	@date,		@name,		@cuit,			@document	, @ct_CAI, @ct_CAIDate)


				/* se recupera el valor del indentity del insert recién efectuado y se incializa la variable de totales */
				SET @identity		= @@identity

				-- Obtiene el Neto Gravado y lo pone en @tm_total
				SELECT @tm_total	= IsNull( tct.ct_discount  / ((ttn.tax_percentage / 100) + 1),0),
					   @decDiscount = tct.ct_discount
     				FROM tbCommercialTransactions tct
     				INNER JOIN tbCommercialTransactionsPaymentsAdditionals tctpa
     					ON	tctpa.comp_id			= tct.comp_id
     					AND tctpa.ct_transaction	= tct.ct_transaction
     				INNER JOIN tbTaxName ttn
     					ON		ttn.comp_id			= tctpa.comp_id
     						AND ttn.tax_id			= tctpa.tax_id4Discount
     		   		WHERE tct.ct_transaction = @ct_transaction


				SET 	@decDiscount = -@decDiscount
				SET	    @tm_total    = -@tm_total

				-- Actualiza Neto Grabado y Total
				UPDATE 	#tmpFinalData
					SET 	total		= @decDiscount,
							gravado     = @tm_total
					WHERE	tmp_id		= @identity




				-- Obtiene la Columna Correspondiente al IVA
				SET @tent_column2 = ''
				SELECT @tent_column2 = tmpc.id --ttent.tent_column
					FROM tbCommercialTransactionsPaymentsAdditionals tctpa
					INNER JOIN tbTaxName ttn
						ON		ttn.comp_id = tctpa.comp_id
							AND ttn.tax_id	= tctpa.tax_id4Discount
					INNER JOIN tbTaxEngineName_Taxes ttent
						ON		ttent.comp_id = ttn.comp_id
							AND ttent.ten_id  = @ten_id
							AND ttent.tax_id  = ttn.tax_id
						LEFT JOIN #tmpColumns							tmpc
							ON	 tmpc.tent_column = ttent.tent_column



				-- Pone cuando fué de IVA
				IF NOT @tent_column2 IS NULL
					BEGIN
						SET @tm_total = @decDiscount - @tm_total
						EXEC ('update #tmpFinalData set [Columna' + @tent_column2 + '] = [Columna' + @tent_column2 + '] + ' +   @tm_total   + ' where tmp_id = ' + @identity  )
					END



		END


		FETCH NEXT FROM cursor_CT_gRTEOP
		INTO @ct_transaction,
			 @date,
			 @name,
			 @cuit,

			 --STL 12/11/2010
			 @ct_CAI,
			 @ct_CAIDate,
			 ----------------

			 @document,
			 @subtotal,
			 @sd_isCredit,
			 @sd_id


	END
	CLOSE		cursor_CT_gRTEOP
	DEALLOCATE	cursor_CT_gRTEOP





	/* si la marca de filtar valores es true, se deben eliminar las transacciones que tienen la sumatoria de impuestos en 0 (cero) */
	IF @ten_FilterByValue = 'true'
	BEGIN

			DECLARE @query NVARCHAR(4000), @queryColumns NVARCHAR(4000),@indice INT
			SET @query = ''
			SET @indice = 0

			WHILE @indice < (select MAX(id) from #tmpColumnsNames)
			BEGIN
				SET @indice = @indice + 1
				select @query = @query + colname + ' + ' from #tmpColumnsNames WHERE id = @indice
			END

			SET @queryColumns = SUBSTRING(@query,1,LEN(@query)-2)

			CREATE TABLE #tmpFinalData2 (ct_transaction INT,sumatoria DECIMAL(19,2))

			INSERT INTO #tmpFinalData2
			EXEC ('SELECT	ct_transaction, SUM(' + @queryColumns + ' + gravado + nogravado + exento ' + ') [sumatoria]
					FROM	#tmpFinalData fd
					GROUP BY ct_transaction')


			DELETE FROM #tmpFinalData
				FROM	#tmpFinalData		FD
				INNER JOIN #tmpFinalData2	FD2
					ON 		FD2.ct_transaction	= FD.ct_transaction
				WHERE	FD2.[sumatoria]		= 0

	END


END




GO



CREATE PROCEDURE [dbo].[spCommercialTransactions_GetTransactionsRelatedByCtTransactionOriginal]
(
	@comp_id		as	int,
	@ct_transaction	as	INT,
	@UserId			AS	INT,
	@prof_id		AS  INT,
	@lang_id		AS  INT
)
AS


BEGIN

	SELECT DISTINCT
	       tct.ct_docNumber,
	       tct.ct_kindOf,
	       tct.ct_pointOfSale,
	       tc.cust_taxNumber,
	       tct.ct_taxDate,
	       ISNULL(teip.p12_cuit,'')		[p12_cuit],
	       tct.sd_id
	    FROM	   tbItemTransactions		tit     WITH (NOLOCK)
	    INNER JOIN tbItemTransactions		titOri	WITH (NOLOCK)
			ON	titOri.comp_id			= tit.comp_id AND
				titOri.it_transaction	= tit.it_transaction_original
	    INNER JOIN tbCommercialTransactions tct		WITH (NOLOCK)
			ON tct.comp_id				= titOri.comp_id			AND
			   tct.ct_transaction		= titOri.ct_transaction
		INNER JOIN tbDocumentsFile			tdf		WITH (NOLOCK)
			ON	tdf.comp_id				= tct.comp_id	AND
				tdf.bra_id				= tct.bra_id	AND
				tdf.df_id				= tct.df_id
		INNER JOIN tbElectronicInvoice_P12Files teip	WITH (NOLOCK)
			ON	teip.comp_id			= tdf.comp_id AND
				teip.p12_id				= tdf.p12_id
	    INNER JOIN tbCustomer				tc		WITH (NOLOCK)
			ON	tc.comp_id				= tct.comp_id				AND
				tc.cust_id				= tct.cust_Id
	    WHERE tit.comp_id				= @comp_id					AND
	          tit.ct_transaction		= @ct_transaction			AND
	          tit.it_transaction_original IS NOT NULL

END

GO

-- =============================================
-- Author:		MOS
-- Create date: Inserta las publicaciones de las que se debe actualizar la disponibilidad o pausarlas.
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactions_hasMercadoLibreOrder]
	@comp_id		INT,
	@ct_transaction	INT,
	@guid			UNIQUEIDENTIFIER
AS
BEGIN

	SET NOCOUNT ON;

	SELECT	TOP 1
			tmloh.comp_id,
			tmloh.mlo_id,
			tmloh.MLUser_Id,
			tmloh.MLorder_id,
			ISNULL(tmlod.mlp_id,-1)													[mlp_id],
			dbo.fnGetCommercialTransactionDescription(@comp_id,2,@ct_transaction)	[InvoiceNumber],
			ISNULL(tdf.df_mercadoLibreInvoiceMessage,'')							[df_mercadoLibreInvoiceMessage]
		FROM tbItemTransactions					tit		WITH (NOLOCK)
		INNER JOIN tbCommercialTransactions		tct		WITH (NOLOCK)
			ON  tct.comp_id			= tit.comp_id	AND
				--tct.bra_id			= tit.bra_id	AND
				tct.ct_transaction	= tit.ct_transaction
		INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
			ON	tdf.comp_id			= tct.comp_id	AND
				--tdf.bra_id			= tct.bra_id	AND
				tdf.df_id			= tct.df_id
		INNER JOIN tbMercadoLibre_ordersHeader	tmloh	WITH (NOLOCK)
			ON	tmloh.comp_id		= tit.comp_id	AND
				(
					tmloh.mlo_id		= tit.mlo_id
				  OR
					tmloh.mlo_id		= tct.mlo_id
				)
		INNER JOIN tbMercadoLibre_ordersDetail	tmlod	WITH (NOLOCK)
			ON	tmlod.comp_id		= tmloh.comp_id	AND
				tmlod.mlo_id		= tmloh.mlo_id
		WHERE	tit.comp_id			= @comp_id		AND
				tit.ct_transaction	= @ct_transaction


END
GO





-- =============================================
-- MOS
-- Actualiza Commercial Transactions
-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactions_InsertData]
	(
		@comp_id							as int,
		@bra_id								as int,
		@ct_docNumber						as varchar(40),
		@ct_date							as datetime,
		@supp_id							as int,
		@cust_id							as int,
		@cb_id								as int,
		@user_id							as int,
		@ct_subtotal						as decimal(19,5),
		@ct_total							as decimal(19,5),
		@ct_discount						as decimal(19,5),
		@ct_taxes							as decimal(19,5),
		@curr_id_transaction				as int,
		@sm_id								as int,
		@disc_id							as int,
		@ct_ATotal							as decimal(19,5),
		@ct_ABalance						as decimal(19,5),
		@ct_ACurrency						as int,
		@ct_ACurrencyExchange				as decimal(19,6),
		@df_id								as int,
		@dl_id								as int,
		@st_id								as int,
		@tis_guid			    			as uniqueidentifier,
		@ct_CompanyCurrency					as int,
		@ct_Branch2CompanyCurrencyExchange	as decimal(19,6),
		@sd_id_Alternative					as int,
		@note1								as varchar(350),
		@note2								as varchar(350),
		@note3								as varchar(350),
		@note4								as varchar(350),
		@ct_adjust							as decimal(19,6),
		@return_value						as int			output,
		@ret_ErrorCode						as int			output,
		@ret_ErrorDescription				as varchar(200) output
	)

AS
BEGIN

	SET NOCOUNT ON;


	-- ------------------------------------------------------------------
	-- Verifica que Ya no se haya disparado una transaccion de este tipo.
	-- ------------------------------------------------------------------
	IF EXISTS(	SELECT TOP 1  1
					FROM tbCommercialTransactions2Guid tctg WITH (NOLOCK)
	          		WHERE tctg.guid = @tis_guid) --OR 'true' = 'true'
		BEGIN
			Set @return_value			= -1
			Set @ret_ErrorCode			= -9878
			Set @ret_ErrorDescription	= 'Posible Doble Postback, la Transaccion YA FUE Realizada.!'
			Return
		END
	-- ------------------------------------------------------------------

	--DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	--IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT_906		-- MOS 06-2020
    --SAVE TRANSACTION traPROTECT_906
    --BEGIN TRANSACTION
    BEGIN TRY




		-- ------------------------------------
		-- Bloquear la base antes de hacer nada
		-- ------------------------------------
		DECLARE @intLock AS INT
		SELECT  @intLock = tce.sb_id
			FROM tbsysBlockPage4IsoTran  tce
		-- ------------------------------------



		DECLARE @intOptionalValue AS INT
		SET @intOptionalValue	  = 0

		-- -----------------------------------------
		-- wfmChequeAssignment
		-- -----------------------------------------
		IF @sd_id_Alternative = -200
			BEGIN
				SET @sd_id_Alternative = 200
				SET @intOptionalValue  = 2		-- Valores Negociados
			END
		-- -----------------------------------------



		Declare @intDecimalPlaces as int
		Set		@intDecimalPlaces = dbo.fnGetBranchDecimalPlaces(@comp_id,@bra_id)


		Set @return_value			= 0
		Set @ret_ErrorCode			= 0
		Set @ret_ErrorDescription	= ''





		-- OJO, Asignarlos
		Declare @ct_cd					as datetime
		Declare @ct_pointOfSale			as int
		Declare @ct_taxDate				as datetime
		Declare @ct_payDate				as datetime
		Declare @sd_id					as int
		Declare @sd_Kindof				as varchar(10)
		Declare @country_id				as int
		Declare @state_id				as int

		Set @country_id	 = Null
		Set @state_id	 = Null

		DECLARE @fc_id AS INT	-- X Trigger !!!!

		If @cust_id IS NOT Null
			Begin
				Select @country_id	= country_id,
					   @state_id	= state_id,
					   @fc_id		= fc_id
					from dbo.tbCustomer				WITH (NOLOCK)
					Where	comp_id = @comp_id
						and cust_id = @cust_id
			END

		IF @cb_id IS NOT NULL	-- Si es la la Sucursal de un Cliente saca la provincia de la Sucursal del Cliente
			BEGIN
				Select @country_id	= country_id,
					   @state_id	= state_id
					from dbo.tbCustomerBranch				WITH (NOLOCK)
					Where	comp_id = @comp_id	AND
							cust_id = @cust_id	AND
							cb_id	= @cb_id

			END



		-- Recupera tbSysDocuments (Tipo de Documento del Sistema.-)
		SELECT @sd_id = A.sd_id
			From dbo.tbDocumentsFile A			WITH (NOLOCK)
	        WHERE	a.comp_id	= @comp_id and
	          		A.df_Id		= @df_id


		-- Si viene un @sd_id_Alternative, lo hace igual
		If not @sd_id_Alternative is Null
			Begin
				Set @sd_id = @sd_id_Alternative
			End


		-- Recupera Punto de Venta de la tabla de Documentos de Ventas
		if exists(	SELECT TOP 1  1
	          			from dbo.tbDocumentsFile A						WITH (NOLOCK)
						Where	A.comp_id = @comp_id and
								A.df_id   = @df_id)
			BEGIN
				Select @ct_pointOfSale	= A.df_pointOfSale ,
					   @sd_Kindof		= A.df_Kindof
										From dbo.tbDocumentsFile A		WITH (NOLOCK)
										Where   A.comp_id = @comp_id
											and A.df_id   = @df_id
			END
		ELSE
			begin
				SELECT @ct_pointOfSale	= tb.bra_PaymentPointOfSale
					FROM tbBranch tb									WITH (NOLOCK)
					WHERE	tb.comp_id	= @comp_id AND
							tb.bra_id	= @bra_id
				SET @sd_Kindof = 'X'
			END



		Set @ct_cd = getdate()

		Set @ct_taxDate = @ct_date
		Set @ct_payDate = (@ct_date + IsNull((Select A.st_days2Pay
												From dbo.tbSalesTerms A		WITH (NOLOCK)
												Where   A.comp_id = @comp_id
													and A.st_id   = @st_id)
											,0)
						  )


		SET @ct_payDate = dbo.fnGetEnd_or_BeginOfDate(@ct_payDate,'True')


		Insert Into dbo.tbCommercialTransactions		WITH (ROWLOCK)
			(	comp_id,
				bra_id,
				ct_kindOf,
				ct_pointOfSale,
				ct_docNumber,
				ct_date,
				ct_taxDate,
				ct_payDate,
				supp_id,
				cust_id,
				cb_id,
				user_id,
				ct_cd,
				ct_subtotal,
				ct_total,
				ct_discount,
				ct_taxes,
				curr_id_transaction,
				sm_id,
				disc_id,
				ct_ATotal,
				ct_ABalance,
				ct_ACurrency,
				ct_ACurrencyExchange,
				df_id,
				dl_id,
				st_id,
				sd_id,
				ct_CompanyCurrency,
				ct_Branch2CompanyCurrencyExchange,
				country_id,
				state_id,
				ct_Pending,
				ct_adjust,
				ct_optionalValue
				--fc_id
			)
			Values
			(
				@comp_id,
				@bra_id,
				@sd_Kindof,
				@ct_pointOfSale,
				@ct_docNumber,
				@ct_date,
				@ct_taxDate,
				@ct_payDate,
				@supp_id,
				@cust_id,
				@cb_id,
				@user_id,
				@ct_cd,
				Round(@ct_subtotal,@intDecimalPlaces),
				Round(@ct_total,@intDecimalPlaces),
				Round(@ct_discount,@intDecimalPlaces),
				Round(@ct_taxes,@intDecimalPlaces),
				@curr_id_transaction,
				@sm_id,
				@disc_id,
				Round(@ct_ATotal,@intDecimalPlaces),
				Round(@ct_ABalance,@intDecimalPlaces),
				@ct_ACurrency,
				@ct_ACurrencyExchange,
				@df_id,
				@dl_id,
				@st_id,
				@sd_id,
				@ct_CompanyCurrency,
				@ct_Branch2CompanyCurrencyExchange,
				@country_id,
				@state_id,
				'True',
				@ct_adjust,
				@intOptionalValue
				--@fc_id
			)

		--@hacc_transaction,

		Set @return_value = @@IDENTITY


		INSERT INTO tbCommercialTransactionNotes	WITH (ROWLOCK)
		(
			comp_id,
			bra_id,
			ct_transaction,
			ctn_note1,
			ctn_note2,
			ctn_note3,
			ctn_note4
		)
		VALUES
		(
			@comp_id,
			@bra_id,
			@return_value,
			@note1,
			@note2,
			@note3,
			@note4
		)


		-- Inserta cual es el Guid.
		-- Esto se usa para no recargar la tabla original ya que solo
		-- En si se usa finalmente para verificar un posible
		-- Doble Postback que duplique la transaccion.-
		INSERT INTO tbCommercialTransactions2Guid	WITH (ROWLOCK)
		(
			comp_id,
			ct_transaction,
			guid
		)
		VALUES
		(
			@comp_id,
			@return_value,
			@tis_guid
		)


    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT_906
        --IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT_906		-- MOS 06-2020
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_906



END
GO





-- =============================================
-- MOS
-- Actualiza Commercial Transactions
-- OJO, solo TRANSACCIONAL!!!!!!!!!!
-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactions_InsertData_NoTransactional]
	(
		@comp_id							as int,
		@bra_id								as int,
		@ct_docNumber						as varchar(40),
		@ct_date							as datetime,
		@supp_id							as int,
		@cust_id							as int,
		@cb_id								as int,
		@user_id							as int,
		@ct_subtotal						as decimal(19,5),
		@ct_total							as decimal(19,5),
		@ct_discount						as decimal(19,5),
		@ct_taxes							as decimal(19,5),
		@curr_id_transaction				as int,
		@sm_id								as int,
		@disc_id							as int,
		@ct_ATotal							as decimal(19,5),
		@ct_ABalance						as decimal(19,5),
		@ct_ACurrency						as int,
		@ct_ACurrencyExchange				as decimal(19,6),
		@df_id								as int,
		@dl_id								as int,
		@st_id								as int,
		@tis_guid			    			as uniqueidentifier,
		@ct_CompanyCurrency					as int,
		@ct_Branch2CompanyCurrencyExchange	as decimal(19,6),
		@sd_id_Alternative					as int,
		@note1								as varchar(350),
		@note2								as varchar(350),
		@note3								as varchar(350),
		@note4								as varchar(350),
		@ct_adjust							as int,
		@return_value						as int			output
	)

AS
BEGIN

	SET NOCOUNT ON;

	Set @return_value			= 0


--	-- Controla un Posible Doble Postback.-
--	IF EXISTS( SELECT 1 FROM tbCommercialTransactions2Guid tctg WHERE tctg.guid = @tis_guid) --OR 'true' = 'true'
--		BEGIN
--			Set @return_value			= -1
--			Return
--		END



	-- OJO, Asignarlos
	Declare @ct_cd					as datetime
	Declare @ct_pointOfSale			as int
	Declare @ct_taxDate				as datetime
	Declare @ct_payDate				as datetime
	Declare @sd_id					as int
	Declare @sd_Kindof				as varchar(10)
	Declare @country_id				as int
	Declare @state_id				as int

	Set @country_id	 = Null
	Set @state_id	 = Null


	If Not (@cust_id is Null)
		Begin
			Select @country_id = country_id,
				   @state_id   = state_id
				from dbo.tbCustomer
				Where	comp_id = @comp_id
					and cust_id = @cust_id
		End


	-- Recupera tbSysDocuments (Tipo de Documento del Sistema.-)
	Set @sd_id			= (	Select A.sd_id
								From dbo.tbDocumentsFile A
								Where A.df_Id = @df_id
						   )


	-- Si viene un @sd_id_Alternative, lo hace igual
	If not @sd_id_Alternative is Null
		Begin
			Set @sd_id = @sd_id_Alternative
		End


	-- Recupera Punto de Venta de la tabla de Documentos de Ventas
	if exists(select 1 from dbo.tbDocumentsFile A
				Where A.comp_id = @comp_id and A.df_id   = @df_id)

		Select @ct_pointOfSale	= A.df_pointOfSale ,
			   @sd_Kindof		= A.df_Kindof
								From dbo.tbDocumentsFile A
								Where   A.comp_id = @comp_id
									and A.df_id   = @df_id
	else
		set @ct_pointOfSale = 0



	Set @ct_cd = getdate()

	Set @ct_taxDate = @ct_date
	Set @ct_payDate = (@ct_date + IsNull((Select A.st_days2Pay
											From dbo.tbSalesTerms A
											Where   A.comp_id = @comp_id
												and A.st_id   = @st_id)
										,0)
					  )


	Insert Into dbo.tbCommercialTransactions
		(	comp_id,
			bra_id,
			ct_kindOf,
			ct_pointOfSale,
			ct_docNumber,
			ct_date,
			ct_taxDate,
			ct_payDate,
			supp_id,
			cust_id,
			cb_id,
			user_id,
			ct_cd,
			ct_subtotal,
			ct_total,
			ct_discount,
			ct_taxes,
			curr_id_transaction,
			sm_id,
			disc_id,
			ct_ATotal,
			ct_ABalance,
			ct_ACurrency,
			ct_ACurrencyExchange,
			df_id,
			dl_id,
			st_id,
			sd_id,
			ct_CompanyCurrency,
			ct_Branch2CompanyCurrencyExchange,
			country_id,
			state_id,
			ct_Pending,
			ct_adjust
		)
		Values
		(
			@comp_id,
			@bra_id,
			@sd_Kindof,
			@ct_pointOfSale,
			@ct_docNumber,
			@ct_date,
			@ct_taxDate,
			@ct_payDate,
			@supp_id,
			@cust_id,
			@cb_id,
			@user_id,
			@ct_cd,
			@ct_subtotal,
			@ct_total,
			@ct_discount,
			@ct_taxes,
			@curr_id_transaction,
			@sm_id,
			@disc_id,
			@ct_ATotal,
			@ct_ABalance,
			@ct_ACurrency,
			@ct_ACurrencyExchange,
			@df_id,
			@dl_id,
			@st_id,
			@sd_id,
			@ct_CompanyCurrency,
			@ct_Branch2CompanyCurrencyExchange,
			@country_id,
			@state_id,
			'True',
			@ct_adjust
		)

	--@hacc_transaction,

	Set @return_value = @@IDENTITY


--	-- Inserta cual es el Guid.
--	-- Esto se usa para no recargar la tabla original ya que solo
--	-- En si se usa finalmente para verificar un posible
--	-- Doble Postback que duplique la transaccion.-
--	INSERT INTO tbCommercialTransactions2Guid
--	(
--		comp_id,
--		ct_transaction,
--		guid
--	)
--	VALUES
--	(
--		@comp_id,
--		@return_value,
--		@tis_guid
--	)


END
GO








CREATE PROCEDURE [dbo].[spCommercialTransactions_insertDataPackingList]
(
	@comp_id				INT,
	@bra_id					INT,
	@ct_transaction			INT,
	@dfPackingList			INT,
	@updateCT				BIT,
	@decDOCUMENT_NUMBER		DECIMAL(19),
	@return_value			INT 			OUTPUT,
	@ret_ErrorCode			INT 			OUTPUT,
	@ret_ErrorDescription	VARCHAR(200)	OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON

	/*
	DECLARE @comp_id			INT,
			@bra_id				INT,
			@ct_transaction		INT,
			@dfPackingList		INT
	SELECT	@comp_id			=1,
			@bra_id				=1,
			@ct_transaction		=3002,
			@dfPackingList		=10
	*/

	SET	@return_value			= 0
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''

	DECLARE @sd_id AS INT
	DECLARE @kindof AS CHAR(1)
	DECLARE @pointOfSale AS INT
	DECLARE @docNumber AS nVARCHAR(50)

	 --dario -06/02/2020
	declare @df_CAI		as VARCHAR(50)
	declare @df_CAIDate as datetime
	------------------------

	-- ---------------------------------------------------------
	-- Si se debe obtener la numeración de otro documento
	-- se hace en ésta sección
	-- ---------------------------------------------------------
	DECLARE @df_id_getNumber AS INT -- De donde tomara el numero del comprobante
	DECLARE @isFiscalPrinter AS BIT
	SET		@isFiscalPrinter = 'False'

	SELECT		@sd_id			= tdf.sd_id,
				@kindof			= tdf.df_Kindof,
				@pointOfSale	= tdf.df_pointOfSale,
				@docNumber		= tdf.df_number,
				@df_id_getNumber = isnull(tdf.df_id_getNumber,@dfPackingList),
				@isFiscalPrinter = ISNULL(tdf.df_Fiscal_IsFiscalPrinter,'False'),
				 --dario -06/02/2020
				@df_CAI			= tdf.df_cai,
				@df_CAIDate		= df_caiVto
				--------------------------
		FROM	tbDocumentsFile tdf					-- NO poner with nolock!
		WHERE	tdf.comp_id = @comp_id
			AND tdf.df_id	= @dfPackingList

	-- Vuelta a Preguntar el DocNumber x si toma el de otro comprobante
	IF @df_id_getNumber <> @dfPackingList
		BEGIN
			SELECT @docNumber = tdf.df_number
				FROM tbDocumentsFile tdf			-- NO poner with nolock!
				WHERE	tdf.comp_id = tdf.comp_id
					AND tdf.df_id	= @df_id_getNumber
		END
	-- ---------------------------------------------------------

	-- ---------------------------------------------------------------------------------------
	-- Si es una impresora fiscal toma el numero de comprobante del informado por parametros.-
	-- ---------------------------------------------------------------------------------------
	IF @isFiscalPrinter = 'True' AND @decDOCUMENT_NUMBER <> 0
		BEGIN
			SET @docNumber = CONVERT(VARCHAR(50),@decDOCUMENT_NUMBER)
		END
	-- ---------------------------------------------------------------------------------------

	INSERT INTO tbCommercialTransactions	WITH (ROWLOCK)
	(		comp_id,							bra_id,							ct_pointOfSale,
			ct_kindOf,							ct_docNumber,					ct_date,
			ct_taxDate,							ct_payDate,						supp_id,
			cust_id,							ba_id,							cb_id,
			[user_id],							ct_cd,							ct_subtotal,
			ct_total,							ct_discount,					ct_adjust,
			ct_taxes,							curr_id_transaction,			hacc_transaction,
			sm_id,								disc_id,						ct_ATotal,
			ct_ABalance,						ct_ACurrency,					ct_ACurrencyExchange,
			df_id,								dl_id,							st_id,
			sd_id,								puco_id,						ct_CompanyCurrency,
			ct_Branch2CompanyCurrencyExchange,	ct_Pending,						country_id,
			state_id,							ct_isAvailableForImport,		ct_soh_bra_id,
			ct_soh_id,							ct_CAI,							ct_CAIDate,
			ct_CAIBarCodeImage,					ct_isAvailableForPayment,		ct_transaction_PackingList,
			ct_processingDate,					ct_AAdjust,						ct_dfExchange		,
			curr_id4Exchange,					ct_curr_IdExchange,				curr_id4dfExchange
	)
	SELECT	comp_id,							bra_id,							@pointOfSale,
			@kindof,							@docNumber,						ct_date,
			ct_taxDate,							ct_payDate,						supp_id,
			cust_id,							ba_id,							cb_id,
			[user_id],							ct_cd,							ct_subtotal,
			ct_total,							ct_discount,					ct_adjust,
			ct_taxes,							curr_id_transaction,			hacc_transaction,
			sm_id,								disc_id,						0,
			0,									ct_ACurrency,					ct_ACurrencyExchange,
			@dfPackingList,						dl_id,							st_id,
			@sd_id,								puco_id,						ct_CompanyCurrency,
			ct_Branch2CompanyCurrencyExchange,	'false',						country_id,
			state_id,							ct_isAvailableForImport,		ct_soh_bra_id,
			ct_soh_id,							@df_CAI /*ct_CAI*/,				@df_CAIDate /*	ct_CAIDate*/,
			ct_CAIBarCodeImage,					ct_isAvailableForPayment,		@ct_transaction,
			ct_processingDate,					0,								ct_dfExchange,
			curr_id4Exchange,					ct_curr_IdExchange,				curr_id4dfExchange

	FROM	tbCommercialTransactions			tct	WITH (NOLOCK)
	WHERE	tct.comp_id			= @comp_id
	AND		tct.bra_id			= @bra_id
	AND		tct.ct_transaction	= @ct_transaction


	SET @return_value = @@IDENTITY


	UPDATE	tbCommercialTransactions		WITH (ROWLOCK)
		SET		ct_transaction_PackingList = @return_value
		WHERE	comp_id			= @comp_id
			AND	ct_transaction	= @ct_transaction


END
GO





-- =============================================
-- MOS
-- Actualiza Commercial Transactions
-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactions_InsertPurchaseData]
	(
		@comp_id								int,
		@bra_id									int,
		@ct_pointOfSale							int,
		@ct_kindOf								varchar(10),
		@ct_docNumber							varchar(40),
		@ct_date								datetime,
		@ct_taxDate								datetime,
		@ct_payDate								datetime,
		@supp_id								int,
		@cust_id								int,
		@ba_id									INT,
		@cb_id									int,
		@user_id								int,
		@ct_subtotal							decimal(19,5),
		@ct_total								decimal(19,5),
		@ct_discount							decimal(19,5),
		@ct_adjust								decimal(19,5),
		@ct_taxes								decimal(19,5),
		@curr_id_transaction					int,
		@hacc_transaction						int,
		@sm_id									int,
		@disc_id								int,
		@ct_ATotal								decimal(19,5),
		@ct_ABalance							decimal(19,5),
		@ct_ACurrency							int,
		@ct_ACurrencyExchange					decimal(38,15),
		@df_id									int,
		@dl_id									int,
		@st_id									int,
		@sd_id									int,
		@puco_id								int,
		@ct_CompanyCurrency						int,
		@ct_Branch2CompanyCurrencyExchange		decimal(38,15),
		@ct_Pending								bit,
		@country_id								int,
		@state_id								int,
		@ct_isAvailableForImport				bit,
		@ct_CAI									VARCHAR(50),
		@ct_CAIDate								DATETIME,
		@observation1							as varchar(350),
		@observation2							as varchar(350),
		@observation3							as varchar(350),
		@observation4							as varchar(350),
		@curr_id4Exchange						AS INT,
		@ct_curr_IdExchange						AS DECIMAL(19,4),
		@return_value							as int			output,
		@ret_ErrorCode							as int			output,
		@ret_ErrorDescription					as varchar(200) output
)
AS

BEGIN




		set nocount ON
		-- =================================================================================================================
		-- Author		: MOS
		-- Update Date	: 2011-05-30
		-- TN			: 881
		-- Description	: Se efectúa el chequeo del documento a cargar para evitar una posible doble carga de los datos
		-- =================================================================================================================
		Set @return_value			= 0
		Set @ret_ErrorCode			= 0
		Set @ret_ErrorDescription	= ''
		-- =================================================================================================================
		-- TN : 881
		DECLARE @rv		INT

		BEGIN TRY

			IF @sd_id <> 106
			BEGIN

				EXEC [spPurchaseDocs_checkDocument]
					@comp_id,		@bra_id,
					@ct_kindOf,		@ct_pointOfSale,
					@ct_docNumber,	@sd_id,
					@supp_id,		-1,
					@return_value = @rv OUTPUT

				IF @rv = 0
				BEGIN
					Set @return_value			= -2
					Set @ret_ErrorCode			= -2
				END

			END

		END TRY
		BEGIN CATCH
			Set @return_value			= -1
			Set @ret_ErrorCode			= -1
			Set @ret_ErrorDescription	= 'spCommercialTransactions_InsertPurchaseData-' +
				(SELECT
					convert(varchar,ERROR_NUMBER	())	+ '-' +
					convert(varchar,ERROR_SEVERITY	())	+ '-' +
					convert(varchar,ERROR_STATE		())	+ '-' +
					convert(varchar,ERROR_LINE		())	+ '-' +
									ERROR_MESSAGE	())
		END CATCH





		--IF @return_value <> -2
		IF @ret_ErrorCode = 0
		-- =================================================================================================================

		BEGIN TRY



			-- X TRIGGER
			--DECLARE @fc_id AS INT
			--SET		@fc_id =   NULL
			--IF @supp_id IS NOT NULL
			--	BEGIN
			--		SELECT @fc_id = fc_id
			--			FROM tbSupplier ts			WITH (NOLOCK)
			--			WHERE	ts.comp_id = @comp_id AND
			--					ts.supp_id = @supp_id
			--	END

			--IF @fc_id IS NULL AND @cust_id IS NOT NULL
			--	BEGIN
			--		SELECT	@fc_id = fc_id
			--			FROM tbCustomer tc			WITH (NOLOCK)
			--			WHERE	tc.comp_id = @comp_id AND
			--					tc.cust_id = @cust_id
			--	END


			-- --------------------------------------------------------------------------------------------------
			-- Si es Comprobante de Diferencia de Cotizacion NO debe afectar a la Cuenta Corriente del Proveedor.
			-- NO CAMBIAR ESTE COMPORTAMIENTO POR MAS QUE ALGUN FORRO LO REQUIERA !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
			-- --------------------------------------------------------------------------------------------------
			IF @sd_id = 132 OR @sd_id = 133
				BEGIN
					SET @ct_ATotal		= 0
					SET @ct_ABalance	= 0
				END
			-- --------------------------------------------------------------------------------------------------



			-- MOS, 09-2012
			DECLARE @datProcessingDate AS DATETIME
			SET @datProcessingDate = GETDATE()
		--	SELECT @datProcessingDate = tb.bra_processingDate
		--		FROM tbBranch tb
		--	WHERE	tb.comp_id	= @comp_id
		--		AND tb.bra_id	= @bra_id

			insert into  dbo.tbCommercialTransactions
				(comp_id, bra_id, ct_pointOfSale, ct_kindOf, ct_docNumber, ct_date,
				ct_taxDate, ct_payDate, supp_id, cust_id, ba_id, cb_id, user_id,
				ct_cd, ct_subtotal, ct_total, ct_discount, ct_adjust, ct_taxes,
				curr_id_transaction, hacc_transaction, sm_id, disc_id, ct_ATotal,
				ct_ABalance, ct_ACurrency, ct_ACurrencyExchange, df_id, dl_id,
				st_id, sd_id, puco_id, ct_CompanyCurrency, ct_Branch2CompanyCurrencyExchange,
				ct_Pending, country_id, state_id, ct_isAvailableForImport,ct_CAI,ct_CAIDate,
				curr_id4Exchange,
				ct_curr_IdExchange) --, fc_id)

			Values
				(@comp_id, @bra_id, @ct_pointOfSale, @ct_kindOf, @ct_docNumber, @ct_date,
				@ct_taxDate, @ct_payDate, @supp_id, @cust_id, @ba_id, @cb_id, @user_id,
				@datProcessingDate, @ct_subtotal, @ct_total, @ct_discount, @ct_adjust, @ct_taxes,
				@curr_id_transaction, @hacc_transaction, @sm_id, @disc_id, @ct_ATotal,
				@ct_ABalance, @ct_ACurrency, @ct_ACurrencyExchange, @df_id, @dl_id,
				@st_id,	@sd_id, @puco_id, @ct_CompanyCurrency, @ct_Branch2CompanyCurrencyExchange,
				@ct_Pending, @country_id, @state_id, @ct_isAvailableForImport, @ct_CAI, @ct_CAIDate,
				@curr_id4Exchange,
				@ct_curr_IdExchange) --, @fc_id)


			Set @return_value = @@IDENTITY


			-- Graba Observaciones
			if not (@observation1 = '' and @observation2 = '' and @observation3 = '' and @observation4 = '')
			begin
				Insert Into dbo.tbCommercialTransactionNotes
						(	comp_id,
							bra_id,
							ct_transaction,
							ctn_note1,
							ctn_note2,
							ctn_note3,
							ctn_note4	)

						Values
						(	@comp_id,
							@bra_id,
							@return_value,
							@observation1,
							@observation2,
							@observation3,
							@observation4	)
			end





			-- --------------------------------------------------------------
			-- Verifica si hay estados para autorizar de esta factura
			-- --------------------------------------------------------------
			INSERT INTO tbPurchaseDocumentsStatus
			(
				comp_id,
				bra_id,
				ct_transaction,
				pdsc_id,
				pds_isOk,
				pds_date,
				pds_dateOfAuthorization,
				user_id_Request,
				user_id_Authorization
			)
			SELECT	@comp_id,
					@bra_id,
					@return_value,
					tpdsc.pdsc_id,
					0,
					tb.bra_processingDate,
					NULL,
					@user_id,
					NULL
				FROM tbCommercialTransactions tct
				INNER JOIN tbBranch tb									WITH (NOLOCK)
					ON	tb.comp_id	= tct.comp_id AND
						tb.bra_id	= tct.bra_id
				INNER JOIN tbSupplier ts								WITH (NOLOCK)
					ON	ts.comp_id = tct.comp_id			AND
						ts.supp_id = tct.supp_id
				INNER JOIN tbPurchaseDocumentsStatusConcept tpdsc		WITH (NOLOCK)
					on	tpdsc.comp_id	= tct.comp_id
			WHERE		tct.comp_id		= @comp_id			AND
					tct.ct_transaction	= @return_value		AND
					IsNull(tpdsc.pdsc_isDisabled,'False') = 'False'		AND
					(tpdsc.sd_id	IS NULL OR tct.sd_id = tpdsc.sd_id)	AND
					(tpdsc.sk_id	IS NULL OR ts.sk_id  = tpdsc.sk_id)	AND
					(tpdsc.brag_id	IS NULL OR EXISTS(	SELECT 1
			              									FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
			              	                  					WHERE	tbgd.comp_id	= tct.comp_id	AND
			              	                  							tbgd.bra_id		= tct.bra_id	AND
			              	                  							tbgd.brag_id	= tpdsc.brag_id ))


			-- --------------------------------------------------------------









		END TRY
		BEGIN CATCH
			Set @return_value			= -1
			Set @ret_ErrorCode			= -1
			Set @ret_ErrorDescription	= 'spCommercialTransactions_InsertPurchaseData-' +
				(SELECT
					convert(varchar,ERROR_NUMBER())		+ '-' +
					convert(varchar,ERROR_SEVERITY())	+ '-' +
					convert(varchar,ERROR_STATE())		+ '-' +
					convert(varchar,ERROR_LINE())		+ '-' +
					ERROR_MESSAGE())
		END CATCH



END
GO


CREATE PROCEDURE spCommercialTransactions_MicroSites_Liquidation_GetStatus
(
	@comp_id		INT,
	@ct_transaction	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------
		-- TESTING
		-- -------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT
			SELECT
				@comp_id		= 1,
				@ct_transaction	= 3386
		*/
		-- -------------------------------------

		SELECT
			ISNULL(tct.ws_isLiquidated,'False')				[ws_isLiquidated]
			FROM tbCommercialTransactions					tct
			WHERE	tct.comp_id			= @comp_id			AND
					tct.ct_transaction	= @ct_transaction
	END
GO



 CREATE PROCEDURE [dbo].[spCommercialTransactions_MicroSites_Liquidation_GetTotals]
(
	@comp_id	INT,
	@bra_id		INT,
	@guid		UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@guid		UNIQUEIDENTIFIER
		*/
		-- -------------------------------------------

		--Recuperamos Moneda y Símbolo de la Sucursal
		DECLARE
			@lBra_Curr_Id		INT,
			@lBra_Curr_Symbol	VARCHAR(10)
		SET @lBra_Curr_Id		= 0
		SELECT
			@lBra_Curr_Id = tb.curr_id
			FROM tbBranch					tb
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id
		SELECT
			@lBra_Curr_Symbol = tc.curr_symbol
			FROM tbsysCurrency tc
			WHERE	tc.curr_id	= @lBra_Curr_Id

		DECLARE @ldecTotals	DECIMAL(25,2)
		SET		@ldecTotals = 0


		SELECT
			@ldecTotals =
			SUM(
				dbo.fnGetExchange2(tct.comp_id, tct.ct_total, tct.curr_id_transaction, @lBra_Curr_Id, 0,0,0,0)
				)
			FROM tbCommercialTransactions			tct	WITH(NOLOCK)
			INNER JOIN tbTemporarySelection			tts	WITH(NOLOCK)
				ON	tts.tmpID	= tct.ct_transaction
			WHERE	tct.comp_id = @comp_id AND
					tts.tmpGUID = @guid


		SELECT
			ISNULL(@lBra_Curr_Symbol,'')	[Curr_Symbol],
			ISNULL(@ldecTotals,0)			[Totals]
	END


GO


CREATE PROCEDURE spCommercialTransactions_MicroSites_Liquidation_UpdateLiquidationStatus
(
	@comp_id		INT,
	@ct_transaction	INT,
	@isLiquidated	BIT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------
		-- TESTING
		-- ------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT,
				@IsLiquidated	BIT
		*/
		-- ------------------------------------------

		IF @IsLiquidated = 'True'
			BEGIN
				--PONEMOS ESTADO DE LIQUIDADO EN TRUE Y FECHA DE LIQUIDACION
				UPDATE tbCommercialTransactions
				SET
					ws_isLiquidated		= 'True',
					ws_isLiquidatedCD	= GETDATE()

				WHERE	comp_id			= @comp_id AND
						ct_transaction	= @ct_transaction
			END
		ELSE
			BEGIN
				--PONEMOS ESTADO DE LIQUIDADO EN FALSE Y FECHA DE LIQUIDACION EN NULL Y SETEAMOS EL NUMERO DE LIQUIDACION EN 0
				UPDATE tbCommercialTransactions
				SET
					ws_isLiquidated			= 'False',
					ws_isLiquidatedCD		= NULL,
					ws_LiquidationNumber	= 0

				WHERE	comp_id			= @comp_id AND
						ct_transaction	= @ct_transaction
			END
	END
GO


CREATE PROCEDURE [dbo].[spCommercialTransactions_MicroSites_LiquidationGetReport]
(
	@comp_id	INT,
	@lang_id	INT,
	@page_id	INT,
	@bra_id		INT,
	@guid		UNIQUEIDENTIFIER
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@page_id	INT,
				@bra_id		INT,
				@guid		UNIQUEIDENTIFIER
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@page_id	= 10003,
				@bra_id		= 1,
				@guid		= '25892e17-80f6-415f-9c65-7395632f0223'
		*/
		-- ----------------------------------------------------

		DECLARE
			@lBra_Curr_Id		INT,
			@lBra_Curr_Symbol	VARCHAR(10)
		SET @lBra_Curr_Id		= 0
		SELECT
			@lBra_Curr_Id		= tb.curr_id,
			@lBra_Curr_Symbol	= tc.curr_symbol
			FROM tbBranch					tb
			INNER JOIN tbsysCurrency		tc
				ON	tc.curr_id	= tb.curr_id
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

		SELECT
			tc.cust_name,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction)	[Document],
			tc2.curr_symbol,
			tct.ct_total,
			tct.ws_isLiquidatedCD
			FROM tbCommercialTransactions		tct
			INNER JOIN tbCustomer				tc
				ON	tc.comp_id	= tct.comp_id	AND
					tc.cust_id	= tct.cust_id
			INNER JOIN tbTemporarySelection		tts
				ON  tts.tmpID	= tct.ct_transaction
			INNER JOIN tbsysCurrency			tc2
				ON	tc2.curr_id	= tct.curr_id_transaction
			WHERE tct.comp_id	= @comp_id		AND
					tts.tmpGUID = @guid


		EXEC spReports_getData3  @comp_id, @bra_id, @lang_id, @page_id, 1


		SELECT
			SUM(
				dbo.fnGetExchange2(tct.comp_id, tct.ct_total, tct.curr_id_transaction, @lBra_Curr_Id, 0,0,0,0)
				)							[Total],
				@lBra_Curr_Symbol			[Curr_Symbol]
		FROM tbCommercialTransactions		tct
		INNER JOIN tbCustomer				tc
			ON	tc.comp_id	= tct.comp_id	AND
				tc.cust_id	= tct.cust_id
		INNER JOIN tbTemporarySelection		tts
			ON  tts.tmpID	= tct.ct_transaction
		INNER JOIN tbsysCurrency			tc2
			ON	tc2.curr_id	= tct.curr_id_transaction
		WHERE tct.comp_id	= @comp_id		AND
				tts.tmpGUID = @guid

	END
GO





CREATE PROCEDURE [dbo].[spCommercialTransactions_NotAvailableForImport]
(
	@comp_id			int,
	@lang_id			int,
	@import_id			int
)
as
set nocount on

/*
Declare
		@comp_id		int,
		@lang_id		int,
		@import_id		int

Select
		@comp_id		=1,
		@lang_id		=2,
		@import_id		=4
*/
Select
		CT.ct_transaction [Id],
		isnull(substring(S.supp_name,0,20),'') + ' - ' +  dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.ct_transaction) as [Desc]


From	dbo.tbCommercialTransactions							CT

		inner join dbo.tbSupplier								S
		on	CT.supp_id			=	S.supp_id

		inner join dbo.tbImportDetail							ID
		on	CT.comp_id			=	ID.comp_id
		and CT.ct_transaction	=	ID.ct_transaction
		AND id.import_id		=	@import_id
GO




-- =============================================
-- Author:		MOS
-- Create date: Miercoles 14-10-2015
-- Description:	Recuperamos Datos de
-- CommercialTransactions_PrintsRelations
-- =============================================


CREATE  PROCEDURE [dbo].[spCommercialTransactions_PrintsRelations_getData]
(
	@comp_id					INT,
	@ct_transaction				INT,
	@bitPrintOnlyAdditionals	BIT

)
AS

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	set nocount ON

	-- ---------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------
	/*
	DECLARE		@comp_id				int,
				@ct_transaction			int

	SELECT		@comp_id				= 1,
				@ct_transaction			= 11699
	*/
	-- ---------------------------------------------------------------------


	IF @bitPrintOnlyAdditionals = 'False'
		BEGIN
			SELECT
				tctpr.ct_transaction									[ct_transaction],
				tctpr.ctprint_QS										[ctprint_QS],
				tctpr.ctprint_id										[ID]
				FROM	tbCommercialTransactions_PrintsRelations		tctpr		WITH (NOLOCK)
				WHERE		tctpr.comp_id			= @comp_id					AND
							tctpr.ct_transaction	= @ct_transaction
				ORDER BY tctpr.ctprint_id
		END
	ELSE
		BEGIN	-- MOS 09-2023

			DECLARE @intRecordCount AS INT = 0
			SELECT  @intRecordCount = COUNT(*)
				FROM	tbCommercialTransactions_PrintsRelations		tctpr		WITH (NOLOCK)
				WHERE		tctpr.comp_id			= @comp_id					AND
							tctpr.ct_transaction	= @ct_transaction

			IF @intRecordCount > 1 SET @intRecordCount = @intRecordCount - 1

			SELECT TOP (@intRecordCount)
				tctpr.ct_transaction									[ct_transaction],
				tctpr.ctprint_QS										[ctprint_QS],
				tctpr.ctprint_id										[ID]
				FROM	tbCommercialTransactions_PrintsRelations		tctpr		WITH (NOLOCK)
				WHERE		tctpr.comp_id			= @comp_id					AND
							tctpr.ct_transaction	= @ct_transaction
				ORDER BY tctpr.ctprint_id DESC

		END




END
GO





-- =============================================
