CREATE PROCEDURE [dbo].[spCommercialTransactions_PrintsRelations_Insertdata]

		@comp_id				AS INT,
		@ct_transaction			AS INT,
		@ctprint_QS				AS NVARCHAR(2000),
		@return_value			AS INT	OUTPUT

AS
BEGIN

	SET NOCOUNT ON;

	Set @return_value			= 0


	INSERT INTO tbCommercialTransactions_PrintsRelations
	(
		comp_id,
		ct_transaction,
		ctprint_QS
	)
	VALUES
	(
		@comp_id,
		@ct_transaction,
		@ctprint_QS
	)

	SET @return_value = @@IDENTITY



END
GO

CREATE PROCEDURE [dbo].[spCommercialTransactions_Process_Auto]
(
	@comp_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@internalID		NVARCHAR(50),
	@cust_id		INT,
	@custf_id		INT,
	@ct_date		DATETIME,
	@ct_paydate		DATETIME,
	@df_id			INT,
	@ct_subtotal	DECIMAL(25,4),
	@ct_taxes		DECIMAL(25,4),
	@ct_atotal		DECIMAL(25,4),
	@ct_abalance	DECIMAL(25,4),
	@CustId4Import	NVARCHAR(50),
	@cb_id			INT,
	@ct_docnumber	NVARCHAR(50),



	@curr_id4Exchange		INT,
	@ct_curr_IdExchange     DECIMAL(35,15)


)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@user_id		INT,
				@internalID		NVARCHAR(50),
				@cust_id		INT,
				@custf_id		INT,
				@ct_date		DATETIME,
				@ct_paydate		DATETIME,
				@df_id			INT,
				@ct_subtotal	DECIMAL(25,4),
				@ct_taxes		DECIMAL(25,4),
				@ct_atotal		DECIMAL(25,4),
				@ct_abalance	DECIMAL(25,4),
				@CustId4Import	NVARCHAR(50),
				@cb_id			INT,
				@ct_docnumber	NVARCHAR(50)

			SELECT
				@comp_id		= 1,
				@bra_id			= 1,
				@user_id		= 10001,
				@internalID		= '1',
				@cust_id		= 46433,
				@custf_id		= 0,
				@ct_date		= '2017-08-18',
				@ct_paydate		= '2017-08-17',
				@df_id			= 58,
				@ct_subtotal	= 1244.47,
				@ct_taxes		= 0,
				@ct_atotal		= 1244.47,
				@ct_abalance	= 1244.47,
				@CustId4Import	= '46433',
				@cb_id			= 5914,
				@ct_docnumber	= 'FACT B 0001-00027327'
		*/
		-- -----------------------------------------------------

		DECLARE @strErrorMessage AS NVARCHAR(MAX) = ''
		DECLARE @return_value	INT


		-- Si se informa el ID de migracion que es el de la tabla ORIGINAL del sistema migrado se usa como Cust_id
		IF @CustId4Import <> ''
			BEGIN
				DECLARE @intGBPCustId AS INT
				SET		@intGBPCustId = NULL
				SELECT	@intGBPCustId = tc.cust_id
					FROM tbCustomer tc	WITH (NOLOCK)
					WHERE	tc.comp_id			= @comp_id AND
							tc.cust_migrationID = @CustId4Import
				IF @intGBPCustId IS NOT NULL
					BEGIN
						SET @cust_id = @intGBPCustId
					END
			END

		-- -----------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- -----------------------------------------------------
			--RECUPERO DE LA SUCURSAL
			DECLARE
				@bra_curr_id	INT

			--RECUPERO DEL CLIENTE
			DECLARE
				@sm_id			INT,
				@dl_id			INT,
				@st_id			INT,
				@fc_id			INT,
				@country_id		INT,
				@state_id		INT,
				@disc_id		INT,
				@cust_currency	INT

			--RECUPERO DEL DOCUMENTO
			DECLARE
				@sd_id			INT,
				@ct_pointofsale	INT,
				@ct_kindof		CHAR(10)
		-- -----------------------------------------------------


		-- -----------------------------------------------------
		-- DOCUMENTO
		-- -----------------------------------------------------
			SELECT
				@sd_id				= tdf.sd_id,
				@ct_pointofsale		= tdf.df_pointOfSale,
				@ct_kindof			= tdf.df_Kindof
				FROM tbDocumentsFile			tdf			WITH(NOLOCK)
				WHERE	tdf.comp_id = @comp_id	AND
						tdf.df_id	= @df_id
		-- -----------------------------------------------------


		-- -----------------------------------------------------
		-- CLIENTE
		-- -----------------------------------------------------
			SELECT
				@sm_id				= tc.sm_id,
				@dl_id				= tc.dl_id,
				@st_id				= tc.st_id,
				@fc_id				= tc.fc_id,
				@country_id			= tc.country_id,
				@state_id			= tc.state_id,
				@disc_id			= tc.disc_id,
				@cust_currency		= tc.curr_id
				FROM tbCustomer					tc			WITH(NOLOCK)
				WHERE	tc.comp_id = @comp_id	AND
						tc.cust_id = @cust_id

		-- -----------------------------------------------------
		-- SUCURSAL
		-- -----------------------------------------------------
			SELECT
				@bra_curr_id		= tb.curr_id
				FROM tbBranch					tb			WITH(NOLOCK)
				WHERE	tb.comp_id	= @comp_id	AND
						tb.bra_id	= @bra_id
		-- -----------------------------------------------------

		-- -----------------------------------------------------
		-- CONSTANTE SCTT_ID
		-- -----------------------------------------------------
			DECLARE
				@sctt_id	INT
			SET @sctt_id	= 100
		-- -----------------------------------------------------

		IF @custf_id = 0
			BEGIN
				SET @custf_id = -1
			END

		-- --------------------------------------------------
		-- NUEVOS CAMPOS PARA TICKET 15365
		-- --------------------------------------------------
		IF @curr_id4Exchange <> -1
			BEGIN
				IF NOT EXISTS(SELECT 1
								FROM tbsysCurrency AS tc
								WHERE tc.curr_id = @curr_id4Exchange)
					BEGIN
						SET @return_value = -33
						SET @strErrorMessage = 'ATENCIÓN: El ID de Moneda para Tipo de Cambio no es válido.-'
						SELECT
							@return_value		[Return_Value],
							@internalID			[InternalID],
							@strErrorMessage	[ErrorMSG]
						RETURN
					END
			END

		--TIPO DE CAMBIO, LO TENGO QUE VALIDAR?

		-- --------------------------------------------------


		IF (@ct_atotal < 0) OR (@ct_abalance < 0)
			BEGIN
				SET @return_value = -11
				SET @strErrorMessage = 'ATENCIÓN: Hay importes en NEGATIVO.-'
				SELECT
					@return_value		[Return_Value],
					@internalID			[InternalID],
					@strErrorMessage	[ErrorMSG]
				RETURN
			END

		-- ---------------------------------------------------------------------------------------------------------------
		-- STL 04-06-2018
		-- SI EL BRA_ID DEL SD_ID ES DISTINTO AL BRA_ID DEL CT_TRANSACTION, ENTONCES TIRAMOS ERROR
		-- EL DOCUMENTO QUE ESTA INGRESANDO TIENE UNA SUCURSAL DISTINTA A LA DEL MOVIMIENTO A IMPORTAR
		-- ---------------------------------------------------------------------------------------------------------------
		DECLARE	@lbra_id4DocumentFile AS INT
		SELECT
			@lbra_id4DocumentFile  = tdf.bra_id
			FROM tbDocumentsFile			tdf
			WHERE	tdf.comp_id = @comp_id	AND
					tdf.df_id	= @df_id

		IF @bra_id <> (@lbra_id4DocumentFile)
			BEGIN
				SET @return_value = -22
				SET @strErrorMessage = 'ATENCIÓN: El ID de Documento que ingresó tiene una sucursal distinta a la ingresada en ID de Sucursal'
				SELECT
					@return_value		[Return_Value],
					@internalID			[InternalID],
					@strErrorMessage	[ErrorMSG]
				RETURN
			END
		-- ---------------------------------------------------------------------------------------------------------------


		IF NOT EXISTS (SELECT tcb.cb_id
						   FROM tbCustomerBranch tcb		WITH (NOLOCK)
						   WHERE tcb.comp_id		= @comp_id and
		               			 tcb.cb_id			= @cb_id)
			BEGIN
				SET	@cb_id	= -1
			END

		IF @cb_id = 0 SET @cb_id = -1


		BEGIN TRY


			IF NOT EXISTS (SELECT
								1
								FROM tbCommercialTransactions_dataImportRelations	tctdir	WITH(NOLOCK)
								WHERE	tctdir.comp_id					= @comp_id			AND
										tctdir.dataimport_internal_id	= @internalID		AND
										tctdir.dataimport_type			= 1)
				BEGIN
					INSERT INTO tbCommercialTransactions
					(
						comp_id,
						bra_id,
						ct_pointOfSale,
						ct_kindOf,
						ct_docNumber,
						ct_date,
						ct_payDate,
						cust_id,
						[user_id],
						ct_total,
						ct_subtotal,
						ct_taxes,
						sm_id,
						disc_id,
						ct_ATotal,
						ct_ABalance,
						ct_ACurrency,
						df_id,
						dl_id,
						st_id,
						sd_id,
						ct_CompanyCurrency,
						country_id,
						state_id,
						curr_id4Exchange,
						curr_id4dfExchange,
						sctt_id,
						custf_id,
						fc_id,
						ct_discount,
						curr_id_transaction,
						ct_taxDate,
						ct_ACurrencyExchange,
						ct_Branch2CompanyCurrencyExchange,
						ct_Pending,
						ct_AAdjust,
						ct_isCancelled,
						ct_isMigrated,
						cb_id,
						ct_curr_IdExchange
					)
					SELECT
						@comp_id																			[comp_id],
						@bra_id																				[bra_id],
						@ct_pointofsale																		[Point_of_Sale],
						@ct_kindof																			[kindof],
						@ct_docnumber																		[docNumber],
						@ct_date																			[ct_Date],
						@ct_paydate																			[ct_paydate],
						CASE WHEN @cust_id = -1 THEN NULL ELSE @cust_id END									[cust_id],
						@user_id																			[user_id],
						@ct_atotal																			[ct_atotal],
						@ct_subtotal																		[ct_subtotal],
						@ct_taxes																			[ct_Taxes],
						@sm_id																				[sm_id],
						@disc_id																			[disc_id],
						@ct_atotal																			[ct_atotal],
						@ct_abalance																		[ct_abalance],
						@bra_curr_id																		[bra_curr_id],
						@df_id																				[df_id],
						@dl_id																				[dl_id],
						@st_id																				[st_id],
						@sd_id																				[sd_id],
						@bra_curr_id																		[ct_CompanyCurrency],
						@country_id																			[country_id],
						@state_id																			[state_id],
						--@bra_curr_id												[curr_id4Exchange],
						CASE WHEN @curr_id4Exchange = -1 THEN @bra_curr_id ELSE @curr_id4Exchange END		[curr_id4Exchange],
						@bra_curr_id																		[curr_id4dfExchange],
						@sctt_id																			[sctt_id],
						CASE WHEN @custf_id = -1 THEN NULL ELSE @custf_id END								[cusf_id],
						@fc_id																				[fc_id],
						0																					[ct_discount],
						@bra_curr_id																		[curr_id_transaction],
						@ct_date																			[ct_taxDate],
						1																					[ct_ACurrencyExchange],
						1																					[ct_Branch2CompanyCurrencyExchange],
						'False'																				[ct_Pending],
						0																					[ct_AAdjust],
						'False'																				[ct_isCancelled],
						'True'																				[ct_isMigrated],
						CASE WHEN @cb_id = -1 THEN NULL ELSE @cb_id END										[cb_id],
						CASE WHEN @ct_curr_IdExchange = 0 THEN NULL ELSE @ct_curr_IdExchange END			[ct_curr_IdExchange]



					SET	@return_value = IDENT_CURRENT('tbCommercialTransactions')   -- @@identity

					IF @return_value > 0
						BEGIN
							INSERT INTO tbCommercialTransactions_dataImportRelations
							(
								comp_id,
								dataimport_id ,
								ct_transaction,
								dataimport_type,
								dataimport_internal_id
							)
							VALUES
							(
								@comp_id,
								NULL,
								@return_value,
								1,
								@internalID
							)

						END

					END
				ELSE
					BEGIN
						SET @strErrorMessage = '<br/><br/><b>==>> tbCommercialTransactions_dataImportRelations ya tiene este InternalID de importación, borrar de esta tabla si se requiere re-importar</b><br/><br/><br/><br/><b>==>> tbCommercialTransactions_dataImportRelations has this InternalID import Data, Delete It Before Import</b><br/><br/>'
						SET @return_value = -2
					END
		END TRY
		BEGIN CATCH
			SET @strErrorMessage = '<b>ATENCIÓN, Error de Datos:</b> ' +  ERROR_MESSAGE() + '<br/><br/><b>Verificar que los datos sean correctos y que el documento informado pertenezca a la sucursal informada.</b><br/><br/>'
			SET @return_value = -1
		END CATCH

		SELECT
			@return_value		[Return_Value],
			@internalID			[InternalID],
			@strErrorMessage	[ErrorMsg]

	END
GO



CREATE PROCEDURE [dbo].[spCommercialTransactions_ProfitBalance]
(
	@comp_id			INT,
	@lang_id			INT,
	@page_id			INT,
	@brag_id			INT,
	@dateFrom			DATETIME,
	@dateTo				DATETIME,
	@coslis_id			INT,
	@stor_id			INT,
	@user_id			INT,
	@bra_id				INT,
	@intBranch4Lang		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- --------------------------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@lang_id			INT,
				@page_id			INT,
				@brag_id			INT,
				@dateFrom			DATETIME,
				@dateTo				DATETIME,
				@coslis_id			INT,
				@stor_id			INT,
				@user_id			INT,
				@bra_id				INT,
				@intBranch4Lang		INT
			SELECT
				@comp_id			= 1,
				@lang_id			= 2,
				@page_id			= 100959,
				@bra_id				= 1,
				@brag_id			= 4,
				@dateFrom			= '2016-01-01',
				@dateTo				= '2016-03-08',
				@coslis_id			= 1,
				@stor_id			= 1,
				@intBranch4Lang		= 1,
				@user_id			= 1
		*/
		-- --------------------------------------------------------------------------------







		SET @dateFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'False')
		SET @dateTo		= dbo.fnGetEnd_or_BeginOfDate(@dateTo,'True')




		-- --------------------------------------------------------------------------------
		-- SUCURSALES
		-- --------------------------------------------------------------------------------

		DECLARE
			@braCurr_Id		INT,
			@braCurr_Desc	VARCHAR(100),
			@braCurrSymbol	VARCHAR(10)

		SELECT
			@braCurr_Desc	= tc.curr_desc,
			@braCurrSymbol	= tc.curr_symbol,
			@braCurr_Id		= tb.curr_id
		FROM tbBranch					tb
			INNER JOIN tbsysCurrency	tc
				ON	tc.curr_id	= tb.curr_id
		WHERE	tb.comp_id		= @comp_id	AND
				tb.bra_id		= @bra_id



		DECLARE
			@tblBranch	TABLE(
								CompId			INT,
								BraId			INT,
								BraDesc			VARCHAR(200)
							 )
		INSERT INTO @tblBranch
		SELECT DISTINCT
			tbgd.comp_id,
			tbgd.bra_id,
			tb.bra_desc
			FROM tbBranchGroupDetail						tbgd
			INNER JOIN tbBranch							tb
				ON	tb.comp_id	= tbgd.comp_id			AND
					tb.bra_id	= tbgd.bra_id
			WHERE	tbgd.comp_id	= @comp_id				AND
					tbgd.brag_id	= @brag_id				AND
					tb.curr_id		= @braCurr_Id			AND
					ISNULL(tb.bra_disabled,'False') = 'False'


		--SELECT * FROM @tblBranch

		/*Mensaje de Error*/
		DECLARE @message VARCHAR(100)
		SELECT @message = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 150 AND tut.lang_id = @lang_id

		-- --------------------------------------------------------------------------------


		-- --------------------------------------------------------------------------------
		-- ESTO TIENE TODOS LOS CT_TRANSACTION QUE SON PARA """VENTAS""""
		-- --------------------------------------------------------------------------------
		DECLARE
			@tblCtTransaction4Sale	TABLE	(
												CompId				INT,
												BraId				INT,
												ct_transaction		INT PRIMARY KEY,
												ct_total			DECIMAL(19,5),
												ct_date				DATETIME,
												curr_id_transaction	INT,
												plusOrMinus			INT
											)

		INSERT INTO @tblCtTransaction4Sale
		(
			CompId,
			BraId,
			ct_transaction,
			ct_total,
			ct_date,
			curr_id_transaction,
			plusOrMinus
		)
		SELECT
			tct.comp_id,
			tct.bra_id,
			tct.ct_transaction,
			tct.ct_total,
			tct.ct_date,
			tct.curr_id_transaction,
			vctfs.PlusOrMinus
			FROM tbCommercialTransactions tct
				INNER JOIN vwCommercialTransactions_forSales		vctfs
					ON	vctfs.comp_id			= tct.comp_id		AND
						--vctfs.bra_id			= tct.bra_id		AND
						vctfs.ct_transaction	= tct.ct_transaction
				INNER JOIN tbUsers4BranchFilter						tubf
					ON	tubf.comp_id			= vctfs.comp_id		AND
						tubf.bra_id				= vctfs.bra_id		AND
						tubf.[user_id]			= @user_id
				INNER JOIN @tblBranch								tmp
					ON	tmp.CompId				= tct.comp_id		AND
						tmp.BraId				= tct.bra_id
			WHERE	tct.comp_id					= @comp_id AND
					tct.ct_date					BETWEEN @dateFrom AND @dateTo	AND
					vctfs.sd_isInBalance		= 'True'

		--SELECT * FROM @tblCtTransaction4Sale

		-- --------------------------------------------------------------------------------




		-- --------------------------------------------------------------------------------
		-- 1º
		-- TOTAL FACTURADO (VENTAS)
		-- --------------------------------------------------------------------------------
		SELECT
			tmp.BraDesc,
			tc.curr_symbol,
			SUM(tct.ct_total * vctfs.PlusOrMinus)					[Total]

			INTO #tmpTotalFacturado

			FROM @tblCtTransaction4Sale								tct
				INNER JOIN vwCommercialTransactions_forSales		vctfs
					ON	vctfs.comp_id			= tct.CompId		AND
						vctfs.bra_id			= tct.BraId		AND
						vctfs.ct_transaction	= tct.ct_transaction
				INNER JOIN @tblBranch								tmp
					ON	tmp.CompId				= tct.CompId		AND
						tmp.BraId				= tct.BraId
				INNER JOIN tbsysCurrency							tc
					ON	tc.curr_id				= tct.curr_id_transaction
			WHERE	tct.CompId					= @comp_id AND
					tct.ct_date					BETWEEN @dateFrom AND @dateTo	AND
					vctfs.sd_isInBalance		= 'True'	AND
					vctfs.sd_isReceipt			= 'False'	--NO RECIBOS

			GROUP BY tmp.braId,tmp.BraDesc, tc.curr_symbol

		 IF @@ROWCOUNT > 0
			BEGIN
				SELECT * FROM #tmpTotalFacturado
			END
		  ELSE
	  			BEGIN

			SELECT
  				@message	[BraDesc],
  				''			[curr_symbol],
  				0			[Total]

	  			END
		  DROP TABLE #tmpTotalFacturado


		-- --------------------------------------------------------------------------------
		-- TEXTOS DEL REPORTE
		-- --------------------------------------------------------------------------------

			EXEC spReports_getData3	@comp_id,@intBranch4Lang,@lang_id,@page_id

		-- --------------------------------------------------------------------------------


		-- --------------------------------------------------------------------------------
		-- 2º
		-- STOCK ACTUAL EN U$S
		-- WHERE
		-- --------------------------------------------------------------------------------
		SELECT
			tc.curr_symbol,
			SUM(dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id,ti.item_id) * ticl.coslis_price)	[Price],
			SUM(dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id,ti.item_id) * ticl.coslis_price_aw)	[Price_AW]

			INTO #tmpStockActual

			FROM tbItem ti
				INNER JOIN tbItemCostList										ticl
					ON	ticl.comp_id							= ti.comp_id	AND
						ticl.item_id							= ti.item_id
				INNER JOIN tbsysCurrency										tc
					ON	tc.curr_id								= ticl.curr_id
			WHERE	ti.comp_id									= @comp_id		AND
					ISNULL(ti.item_disabled,'False')			= 'False'		AND
					ISNULL(ti.item_disabledInBalance,'False')	= 'False'		AND
					ISNULL(ti.item_NoStockCheck,'False')		= 'False'
			GROUP BY ti.comp_id, tc.curr_symbol

		IF @@ROWCOUNT > 0
			BEGIN
				SELECT * FROM #tmpStockActual
			END
		  ELSE
	  			BEGIN

			SELECT
  				@message	[BraDesc],
  				0			[Price],
  				0			[Price_AW]

	  			END
		  DROP TABLE #tmpStockActual
		-- --------------------------------------------------------------------------------7


		-- --------------------------------------------------------------------------------
		-- 3º
		-- RENTABILIDAD BRUTA EN $ Y % SOBRE COSTO
		-- --------------------------------------------------------------------------------
		SELECT
			tmp.BraDesc,
			tc.curr_symbol,
			SUM((vctpam.SumOfSale - vctpam.SumOfCost) * tct.plusOrMinus)[Total]

			INTO #tmpRentabilidadBruta

			FROM @tblCtTransaction4Sale									tct
				INNER JOIN vwCommercialTransactionsProfitAndMarckup vctpam
					ON	vctpam.comp_id			= tct.CompId		AND
						vctpam.bra_id			= tct.BraId		AND
						vctpam.ct_transaction	= tct.ct_transaction
				INNER JOIN @tblBranch								tmp
					ON	tmp.CompId				= tct.CompId		AND
						tmp.BraId				= tct.BraId
				INNER JOIN tbsysCurrency							tc
					ON	tc.curr_id				= tct.curr_id_transaction
			WHERE	tct.CompId					= @comp_id AND
					tct.ct_date					BETWEEN @dateFrom AND @dateTo
			GROUP BY tmp.BraDesc, tc.curr_symbol

		IF @@ROWCOUNT > 0
			BEGIN
				SELECT * FROM #tmpRentabilidadBruta
			END
		  ELSE
	  			BEGIN

			SELECT
  				@message	[BraDesc],
  				0			[curr_symbol],
  				0			[Total]

	  			END
		  DROP TABLE #tmpRentabilidadBruta

		-- --------------------------------------------------------------------------------

		-- --------------------------------------------------------------------------------
		-- 4º
		-- GASTOS EN $
		-- VER TEMA COMPROBANTES (SABER QUE TIPOS ENTRAN)
		-- FILTROS WHERE
		-- USAR lA VISTA IS FOR PURCHASE SOLAMENTE
		-- --------------------------------------------------------------------------------
		SELECT
			tmp.BraDesc,
			tc.curr_symbol,
			SUM(tct.ct_total * vctfpa.PlusOrMinus)					[Total]

			INTO #tmpGastos

			FROM tbCommercialTransactions							tct
				INNER JOIN vwCommercialTransactions_forPurchase_All vctfpa
					ON	vctfpa.comp_id			= tct.comp_id		AND
						vctfpa.bra_id			= tct.bra_id		AND
						vctfpa.ct_transaction	= tct.ct_transaction
				INNER JOIN tbUsers4BranchFilter						tubf
					ON	tubf.comp_id			= tct.comp_id		AND
						tubf.bra_id				= tct.bra_id		AND
						tubf.[user_id]			= @user_id
				INNER JOIN @tblBranch								tmp
					ON	tmp.CompId				= tct.comp_id		AND
						tmp.BraId				= tct.bra_id
				INNER JOIN tbsysCurrency							tc
					ON	tc.curr_id				= tct.curr_id_transaction
			WHERE	tct.comp_id					= @comp_id AND
					tct.ct_date					BETWEEN @dateFrom AND @dateTo	AND
					vctfpa.sd_isInBalance		= 'True'
			GROUP BY tmp.BraDesc, tc.curr_symbol

		IF @@ROWCOUNT > 0
			BEGIN
				SELECT * FROM #tmpGastos
			END
		  ELSE
	  			BEGIN

			SELECT
  				@message	[BraDesc],
  				0			[curr_symbol],
  				0			[Total]

	  			END
		  DROP TABLE #tmpGastos
		-- --------------------------------------------------------------------------------

		-- --------------------------------------------------------------------------------
		-- 5º
		-- RENTABILIDAD NETA (BRUTO - GASTOS) EN $ Y EN U$S
		-- 3º - 4º
		-- --------------------------------------------------------------------------------
		DECLARE
			@NetoBruto	DECIMAL(19,5),
			@Gastos		DECIMAL(19,5)

		SELECT
			@NetoBruto = SUM(
								(
									vctpam.SumOfSale	-
									vctpam.SumOfCost
								)						*
									tct.plusOrMinus
							)
			FROM @tblCtTransaction4Sale									tct
				INNER JOIN vwCommercialTransactionsProfitAndMarckup		vctpam
					ON	vctpam.comp_id			= tct.CompId			AND
						vctpam.bra_id			= tct.BraId				AND
						vctpam.ct_transaction	= tct.ct_transaction
				INNER JOIN @tblBranch									tmp
					ON	tmp.CompId				= tct.CompId			AND
						tmp.BraId				= tct.BraId
				INNER JOIN tbsysCurrency							tc
					ON	tc.curr_id				= tct.curr_id_transaction
			WHERE	tct.CompId					= @comp_id AND
					tct.ct_date					BETWEEN @dateFrom AND @dateTo



		SELECT
			@Gastos =
			SUM(
					tct.ct_total * vctfpa.PlusOrMinus
				)
			FROM tbCommercialTransactions							tct
				INNER JOIN vwCommercialTransactions_forPurchase_All vctfpa
					ON	vctfpa.comp_id			= tct.comp_id		AND
						vctfpa.bra_id			= tct.bra_id		AND
						vctfpa.ct_transaction	= tct.ct_transaction
				INNER JOIN tbUsers4BranchFilter						tubf
					ON	tubf.comp_id			= tct.comp_id		AND
						tubf.bra_id				= tct.bra_id		AND
						tubf.[user_id]			= @user_id
				INNER JOIN @tblBranch								tmp
					ON	tmp.CompId				= tct.comp_id		AND
						tmp.BraId				= tct.bra_id
				INNER JOIN tbsysCurrency							tc
					ON	tc.curr_id				= tct.curr_id_transaction
			WHERE	tct.comp_id					= @comp_id AND
					tct.ct_date					BETWEEN @dateFrom AND @dateTo	AND
					vctfpa.sd_isInBalance		= 'True'


		SELECT
			@braCurr_Desc			[description],
			@braCurrSymbol			[curr_symbol],
			@NetoBruto - @Gastos	[Total]

			INTO #tmpRentabilidadNeta

		IF @@ROWCOUNT > 0
			BEGIN
				SELECT * FROM #tmpRentabilidadNeta
			END
		  ELSE
	  			BEGIN

			SELECT
  				@message	[BraDesc],
  				0			[curr_symbol],
  				0			[Total]

	  			END
		  DROP TABLE #tmpRentabilidadNeta
		-- --------------------------------------------------------------------------------



		-- --------------------------------------------------------------------------------
		-- 6º
		-- PORCENTAJE DE CADA MONEDA ( MENSUAL )
		-- 1.- $ + U$S + CHQ
		-- 2.- TARJETAS DE CREDITO
		-- 3.- CREDITOS COMPUMAR
		--SUMARIZAR PARA DESPUES SACAR PORCENTAJES
		-- --------------------------------------------------------------------------------

		/*
		CLASS
			1	= Efectivo
			2	= Cheque
			3	= Documento
			4	= Tarjeta de Crédito
			5	= Transferencia Bancaria
			7	= Cheques Emitidos
			10	= Cheque de Terceros
			100 = Retención

		*/





		-- ----------------------------------------------------
		-- Resumen x Cobranzas
		-- Si se toca alguno de los 2 query modificarlo en el otro !
		-- ----------------------------------------------------
		DECLARE @decTotalCobrado AS DECIMAL(19,2)
		SELECT

			@decTotalCobrado = SUM(vc.amount)
			FROM tbCommercialTransactions						tct
				INNER JOIN vwCollection							vc
					ON	vc.comp_id			= tct.comp_id		AND
						vc.bra_id			= tct.bra_id		AND
						vc.ct_transaction	= tct.ct_transaction
				INNER JOIN @tblCtTransaction4Sale				tmp
					ON	tmp.CompId			= tct.comp_id		AND
						tmp.BraId			= tct.bra_id		ANd
						tmp.ct_transaction	= tct.ct_transaction
				INNER JOIN tbUsers4BranchFilter					tubf
					ON	tubf.comp_id		= tct.comp_id		AND
						tubf.bra_id			= tct.bra_id		AND
						tubf.[user_id]		= @user_id
				INNER JOIN @tblBranch							tb
					ON	tb.CompId			= tct.comp_id		AND
						tb.BraId			= tct.bra_id
				INNER JOIN tbsysCurrency						tc
					ON	tc.curr_id			= tct.curr_id_transaction
			WHERE	tct.comp_id				= @comp_id			AND
					vc.lang_id				= @lang_id			AND
					tct.ct_date				BETWEEN @dateFrom AND @dateTo	AND
				   (
				   		tct.sd_id = 6
				   			OR
				   		tct.sd_id = 13
				   )

		-- ---

		SELECT
			vc.description,
			tc.curr_symbol,
			SUM(vc.amount)												[Total],
			SUM(vc.amount) / dbo.fnNoZDiv( @decTotalCobrado ) * 100		[Porcent]

			INTO #tmpCobranzas

			FROM tbCommercialTransactions						tct
				INNER JOIN vwCollection							vc
					ON	vc.comp_id			= tct.comp_id		AND
						vc.bra_id			= tct.bra_id		AND
						vc.ct_transaction	= tct.ct_transaction
				INNER JOIN @tblCtTransaction4Sale				tmp
					ON	tmp.CompId			= tct.comp_id		AND
						tmp.BraId			= tct.bra_id		ANd
						tmp.ct_transaction	= tct.ct_transaction
				INNER JOIN tbUsers4BranchFilter					tubf
					ON	tubf.comp_id		= tct.comp_id		AND
						tubf.bra_id			= tct.bra_id		AND
						tubf.[user_id]		= @user_id
				INNER JOIN @tblBranch							tb
					ON	tb.CompId			= tct.comp_id		AND
						tb.BraId			= tct.bra_id
				INNER JOIN tbsysCurrency						tc
					ON	tc.curr_id			= tct.curr_id_transaction
			WHERE	tct.comp_id				= @comp_id			AND
					vc.lang_id				= @lang_id			AND
					tct.ct_date				BETWEEN @dateFrom AND @dateTo	AND
				   (
				   		tct.sd_id = 6
				   			OR
				   		tct.sd_id = 13
				   )
			GROUP BY vc.description, tc.curr_symbol


		IF @@ROWCOUNT > 0
			BEGIN
				SELECT * FROM #tmpCobranzas
			END
		  ELSE
	  			BEGIN

			SELECT
  				@message	[description],
  				0			[curr_symbol],
  				0			[Total]

	  			END
		  DROP TABLE #tmpCobranzas

		-- --------------------------------------------------------------------------------







		-- --------------------------------------------------------------------------------
		-- TABLA CON LOS PARÁMETROS
		-- --------------------------------------------------------------------------------

			DECLARE @fun_id INT
			SET @fun_id = 1

			/* devolución de parámetros recibidos */
			DECLARE @related_page_id INT
			SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

			SELECT
				(SELECT
					tswn.word_desc
					 FROM [tbsysTextsNew]							t
						INNER JOIN tbSysWordsNew					tswn
							ON	tswn.lang_id	= @lang_id			AND
								tswn.wordsi_id	= t.wordsi_id
					WHERE	t.ctrl_id			= 639				AND
							t.[page_id]			= @related_page_id	AND
							t.[type_id]			= 1					AND
							t.fun_id			= @fun_id)						[params1],

				 CASE @brag_id WHEN -1 THEN
					(SELECT
						tut.utexts_desc
						FROM	 tbsysUniqueTexts				tut
						WHERE		tut.lang_id		= @lang_id	AND
									tut.utexts_id	= 1)
				ELSE
					(SELECT
						tbg.brag_desc
						FROM tbBranchGroup				tbg
						 WHERE	tbg.comp_id = @comp_id	AND
								tbg.brag_id	= @brag_id)
						END														[params2],


				(SELECT
					tswn.word_desc
					 FROM [tbsysTextsNew]							t
						INNER JOIN tbSysWordsNew					tswn
							ON	tswn.lang_id	= @lang_id			AND
								tswn.wordsi_id	= t.wordsi_id
					WHERE	t.ctrl_id			= 177				AND
							t.[page_id]			= @related_page_id	AND
							t.[type_id]			= 1					AND
							t.fun_id			= @fun_id)						[params3],
				@datefrom														[DateParams1],
				(SELECT
					tswn.word_desc
					 FROM [tbsysTextsNew]							t
						INNER JOIN tbSysWordsNew					tswn
							ON	tswn.lang_id	= @lang_id			AND
								tswn.wordsi_id	= t.wordsi_id
						WHERE	t.ctrl_id		= 384				AND
								t.[page_id]		= @related_page_id	AND
								t.[type_id]		= 1					AND
								t.fun_id		=	@fun_id)					[params4],
				@dateto															[DateParams2],

				(SELECT
					tswn.word_desc
					 FROM [tbsysTextsNew]							t
						INNER JOIN tbSysWordsNew					tswn
							ON	tswn.lang_id	= @lang_id			AND
								tswn.wordsi_id	= t.wordsi_id
					WHERE	t.ctrl_id			= 693				AND
							t.[page_id]			= @related_page_id	AND
							t.[type_id]			= 1					AND
							t.fun_id			= @fun_id)						[params5],

				 CASE @coslis_id WHEN -1 THEN
					(SELECT
						tut.utexts_desc
						FROM	 tbsysUniqueTexts				tut
						WHERE		tut.lang_id		= @lang_id	AND
									tut.utexts_id	= 1)
				ELSE
					(SELECT
						ticln.coslis_desc
						FROM tbItemCostListName				ticln
						 WHERE	ticln.comp_id	= @comp_id	AND
								ticln.coslis_id	= @coslis_id)
						END														[params6],

				(SELECT
					tswn.word_desc
					 FROM [tbsysTextsNew]							t
						INNER JOIN tbSysWordsNew					tswn
							ON	tswn.lang_id	= @lang_id			AND
								tswn.wordsi_id	= t.wordsi_id
					WHERE	t.ctrl_id			= 111				AND
							t.[page_id]			= @related_page_id	AND
							t.[type_id]			= 1					AND
							t.fun_id			= @fun_id)						[params7],

				 CASE @stor_id WHEN -1 THEN
					(SELECT
						tut.utexts_desc
						FROM	 tbsysUniqueTexts				tut
						WHERE		tut.lang_id		= @lang_id	AND
									tut.utexts_id	= 1)
				ELSE
					(SELECT
						ts.stor_desc
						FROM tbStorage					ts
						 WHERE	ts.comp_id	= @comp_id	AND
								ts.stor_id	= @stor_id)
						END														[params8]


		-- --------------------------------------------------------------------------------

		-- --------------------------------------------------------------------------------
		-- SUCURSALES DEL GRUPO DE SUCURSALES
		-- --------------------------------------------------------------------------------
--			SELECT
--				tmp.BraDesc
--			FROM @tblBranch	tmp
		-- --------------------------------------------------------------------------------


	END

GO






