create PROCEDURE [dbo].[spCommercialTransactions_PurchaseTermsUpdate]
(
	@comp_id		AS INT,
	@ct_transaction AS INT,
	@pt_id			AS INT

)
AS
SET NOCOUNT ON


-------------------------------------------------

/*
DECLARE
			@comp_id		AS INT,
			@ct_transaction AS INT,
			@pt_id		AS INT

SELECT
			@comp_id		=1,
			@ct_transaction	=5481,
			@pt_id		= 10
*/


-------------------------------------------------


UPDATE dbo.tbCommercialTransactions

	SET pt_id			 = @pt_id


WHERE comp_id			= @comp_id
AND	  ct_transaction	= @ct_transaction

GO

CREATE PROCEDURE [dbo].[spCommercialTransactions_QRImage_InsertData]
(
	@comp_id								INT,
	@ct_transaction							INT,
	@image									IMAGE,
	@type									INT
)
AS
BEGIN

	SET NOCOUNT ON


	IF @type = 1
		BEGIN
			IF EXISTS(
						SELECT TOP 1 1
							FROM tbCommercialTransactions_QRImage AS tctq	WITH (NOLOCK)
							WHERE	tctq.comp_id		= @comp_id AND
									tctq.ct_transaction = @ct_transaction
					)
				BEGIN
					UPDATE tbCommercialTransactions_QRImage
						SET ctQR_Image	= @image,
							ctQR_cd		= GETDATE()
						WHERE	comp_id			= @comp_id AND
								ct_transaction	= @ct_transaction
				END
			ELSE
				BEGIN
					INSERT INTO tbCommercialTransactions_QRImage(	comp_id,
																	ct_transaction,
																	ctQR_Image)
					VALUES(@comp_id,@ct_transaction,@image)
				END
		END
	IF @type = 2
		BEGIN
			IF EXISTS(
						SELECT TOP 1 1
							FROM tbCommercialTransactions_QRImage AS tctq	WITH (NOLOCK)
							WHERE	tctq.comp_id		= @comp_id AND
									tctq.ct_transaction = @ct_transaction
					)
				BEGIN
					UPDATE tbCommercialTransactions_QRImage
						SET ctQR_Image4Logistic = @image,
							ctQR_cd		= GETDATE()
						WHERE	comp_id			= @comp_id AND
								ct_transaction	= @ct_transaction
				END
			ELSE
				BEGIN
					INSERT INTO tbCommercialTransactions_QRImage(	comp_id,
																	ct_transaction,
																	ctQR_Image4Logistic)
					VALUES(@comp_id,@ct_transaction,@image)
				END

		END


END
GO




create PROCEDURE [dbo].[spCommercialTransactions_Relations_getDataById]
(

	@comp_id			as	INT,
	@ct_transaction_1	as	INT,
	@ct_transaction_2	as	INT

)
as


BEGIN

	set nocount on

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------------
	/*
	declare @comp_id				INT,
			@ct_Transaction			INT,
			@ct_transaction_2		INT

	select  @comp_id				= 1,
			@ct_Transaction			= 11082,
			@ct_transaction_2		= 11083
	*/
	-- -------------------------------------------------------------------------------------



	SELECT
		 tctr.comp_id,
		 tctr.ct_transaction_1,
		 tctr.ct_transaction_2,
		 tctr.class

	FROM tbCommercialTransactions_Relations tctr

	WHERE tctr.comp_id			= @comp_id				AND
		  tctr.ct_transaction_1 = @ct_transaction_1		AND
		  tctr.ct_transaction_2 = @ct_transaction_2
END
GO




CREATE PROCEDURE [dbo].[spCommercialTransactions_Relations_InsertData]
(
	@comp_id				AS	INT,
	@ct_transaction_1		AS	INT,
	@ct_transaction_2		AS	INT,
	@class					AS	INT,

	@return_value			AS	INT				OUTPUT,
	@ret_ErrorCode			AS	INT				OUTPUT,
	@ret_ErrorDescription	AS	VARCHAR(500)	OUTPUT
)
AS

	BEGIN
		SET NOCOUNT ON;
		-- ---------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@ct_transaction_1		INT,
				@ct_transaction_2		INT,
				@class					INT,

				@return_value			INT,
				@ret_ErrorCode			INT,
				@ret_ErrorDescription	VARCHAR(200)
			SELECT
				@comp_id				= 1,
				@ct_transaction_1		= 11704,
				@ct_transaction_2		= 11722,
				@class					= 1,
				@return_value			= 0,
				@ret_ErrorCode			= 0,
				@ret_ErrorDescription	= ''
		*/
		-- ---------------------------------------------------
			BEGIN TRY

				SET @return_value			= 0
				SET @ret_ErrorCode			= 0
				SET @ret_ErrorDescription	= ''

				INSERT INTO tbCommercialTransactions_Relations	WITH (ROWLOCK)
				(
					comp_id,
					ct_transaction_1,
					ct_transaction_2,
					class
				)
				VALUES
				(
					@comp_id,
					@ct_transaction_1,
					@ct_transaction_2,
					@class
				)
				SET @return_value = @@IDENTITY


			END TRY
		BEGIN CATCH
			SET @ret_ErrorCode			= -1
			SET @ret_ErrorDescription	= ERROR_MESSAGE()
		END CATCH
	END
GO





