CREATE PROCEDURE [dbo].[spCommercialTransactions_Relations_TransactionSelect4Collection_getData]
(

	@comp_id				INT,
	@ct_transaction			INT

)
AS

SET NOCOUNT ON


BEGIN

set nocount on
set dateformat 'ymd'


--------------------------------------------------------
-------------parametros de prueba-----------------------
-------------------------------------------------------
/*
DECLARE

		@comp_id				INT,
		@ct_transaction			INT


SELECT
		@comp_id				= 1,
		@ct_transaction			= 10222

*/
--------------------------------------------------------
--------------------------------------------------------
--------------------------------------------------------



	SELECT
		CASE tctr.ct_transaction_1  WHEN @ct_transaction THEN
			tctr.ct_transaction_2
		ELSE
			tctr.ct_transaction_1
		END											[ct_transaction_relation]

		FROM tbCommercialTransactions_Relations tctr

		WHERE	@ct_transaction = tctr.ct_transaction_1 OR
				@ct_transaction = tctr.ct_transaction_2




END





GO


