CREATE PROCEDURE [dbo].[spCommercialTransactions_Supplier_Process_Auto]
(
	@comp_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@internalID		NVARCHAR(50),
	@supp_id		INT,
	@ct_date		DATETIME,
	@ct_paydate		DATETIME,
	@sd_id			INT,
	@ct_subtotal	DECIMAL(25,4),
	@ct_taxes		DECIMAL(25,4),
	@ct_atotal		DECIMAL(25,4),
	@ct_abalance	DECIMAL(25,4),
	@suppId4Import	NVARCHAR(50),
	@PointOfSale	INT,
	@DocNumber		NVARCHAR(50),
	@kindOf			VARCHAR(10)
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
				/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@user_id		INT,
				@internalID		NVARCHAR(50),
				@supp_id		INT,
				@ct_date		DATETIME,
				@ct_paydate		DATETIME,
				@sd_id			INT,
				@ct_subtotal	DECIMAL(25,4),
				@ct_taxes		DECIMAL(25,4),
				@ct_atotal		DECIMAL(25,4),
				@ct_abalance	DECIMAL(25,4),
				@suppId4Import	NVARCHAR(50),
				@PointOfSale	INT,
				@DocNumber		NVARCHAR(50),
				@kindOf			VARCHAR(10)

			SELECT
				@comp_id		= 1,
				@bra_id			= 1,
				@user_id		= 119,
				@internalID		= 'FACT A 0056-00002921',
				@supp_id		= 8103,
				@ct_date		= '2016-07-08',
				@ct_paydate		= '2016-08-08',
				@sd_id			= 1,
				@ct_subtotal	= 4000,
				@ct_taxes		= 0,
				@ct_atotal		= 4000,
				@ct_abalance	= 4000,
				@suppId4Import	= '1',
				@PointOfSale	= 1,
				@DocNumber		= 'FACT A 0056-00002921',
				@kindOf			= 'A'
			*/
		-- -----------------------------------------------------


		DECLARE @return_value	INT
		SET		@return_value	= 0

		IF @suppId4Import <> ''
			BEGIN
				DECLARE @intGBPSuppId AS INT
				SET		@intGBPSuppId = NULL
				SELECT	@intGBPSuppId = tc.supp_id
					FROM tbSupplier								tc	WITH (NOLOCK)
					WHERE	tc.comp_id			= @comp_id		AND
							tc.supp_migrationID = @suppId4Import
				IF @intGBPSuppId IS NOT NULL
					BEGIN
						SET @supp_id = @intGBPSuppId
					END
				--ELSE
				--	BEGIN
				--		SET @return_value = -1
				--		SELECT @return_value	[Return_Value]
				--		RETURN
				--	END
			END



		-- -----------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- -----------------------------------------------------
			--RECUPERO DE LA SUCURSAL
			DECLARE
				@bra_curr_id	INT

			--RECUPERO DEL PROVEEDOR
			DECLARE
				@st_id			INT,
				@fc_id			INT,
				@country_id		INT,
				@state_id		INT,
				@supp_currency	INT,
				@pt_id			INT,
				@puco_id		INT

		-- -----------------------------------------------------

		-- -----------------------------------------------------
		-- PROVEEDOR
		-- -----------------------------------------------------
			SELECT
				@fc_id				= ts.fc_id,
				@pt_id				= ts.pt_id,
				@supp_currency		= ts.curr_id,
				@country_id			= ts.country_id,
				@state_id			= ts.state_id,
				@puco_id			= ts.puco_id

			FROM tbSupplier							ts	WITH(NOLOCK)
			WHERE	ts.comp_id		= ts.comp_id	AND
					ts.supp_id		= @supp_id

		-- -----------------------------------------------------
		-- SUCURSAL
		-- -----------------------------------------------------
			SELECT
				@bra_curr_id		= tb.curr_id
				FROM tbBranch					tb			WITH(NOLOCK)
				WHERE	tb.comp_id	= @comp_id	AND
						tb.bra_id	= @bra_id

		-- -----------------------------------------------------

		-- -----------------------------------------------------
		-- CONSTANTE SCTT_ID
		-- -----------------------------------------------------
			DECLARE
				@sctt_id	INT
			SET @sctt_id	= 100
		-- -----------------------------------------------------


		-- -----------------------------------------------------
		-- COMPAÑÍA
		-- -----------------------------------------------------
			DECLARE
				@comp_id_currency	INT
			SELECT
				@comp_id_currency = tc.curr_id
				FROM tbCompany					tc
				WHERE tc.comp_id = @comp_id
		-- -----------------------------------------------------



		BEGIN TRY

			IF NOT EXISTS (	SELECT 1
								FROM tbCommercialTransactions_dataImportRelations	tctdir	WITH(NOLOCK)
								WHERE	tctdir.comp_id					= @comp_id			AND
										tctdir.dataimport_internal_id	= @internalID		AND
										tctdir.dataimport_type			= 2)
				BEGIN
					INSERT INTO tbCommercialTransactions
					(
						comp_id,
						bra_id,
						ct_pointOfSale,
						ct_kindOf,
						ct_docNumber,
						ct_date,
						ct_payDate,
						supp_id,
						[user_id],
						ct_subtotal,
						ct_total,
						ct_taxes,
						ct_ATotal,
						ct_ABalance,
						ct_ACurrency,
						sd_id,
						puco_id,
						country_id,
						state_id,
						sctt_id,
						pt_id,
						fc_id,
						ct_discount,
						ct_taxDate,
						ct_ACurrencyExchange,
						ct_CompanyCurrency,
						ct_Branch2CompanyCurrencyExchange,
						ct_Pending,
						ct_isCancelled,
						ct_isMigrated,
						curr_id_transaction
					)
					SELECT
						@comp_id,
						@bra_id,
						@PointOfSale,
						@kindOf,
						@DocNumber,
						@ct_date,
						@ct_paydate,
						@supp_id,
						@user_id,
						@ct_subtotal + @ct_taxes,
						CASE
							WHEN @ct_subtotal = 0 THEN	@ct_atotal
							ELSE						@ct_subtotal
						END,
						@ct_taxes,
						@ct_atotal,
						@ct_abalance,
						@supp_currency,
						@sd_id,
						@puco_id,
						@country_id,
						@state_id,
						@sctt_id,
						@pt_id,
						@fc_id,
						0,
						@ct_date,
						1,
						@comp_id_currency,
						1,
						'False',
						'False',
						'True',
						@bra_curr_id

					SET	@return_value = IDENT_CURRENT('tbCommercialTransactions')   -- @@identity

					IF @return_value <> 0
						BEGIN

							INSERT INTO tbCommercialTransactions_dataImportRelations
							(
								comp_id,
								dataimport_id,
								ct_transaction,
								dataimport_type,
								dataimport_internal_id
							)
							VALUES
							(
								@comp_id,
								NULL,
								@return_value,
								2,
								@internalID
							)

						END
				END
		END TRY
		BEGIN CATCH
			SET @return_value = -1
		END CATCH

		SELECT @return_value	[Return_Value]

	END
GO






CREATE PROCEDURE [dbo].[spCommercialTransactions_SupplierKindFilterByProfile]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id						INT,
	@prof_id					INT,
	@user_id					INT,

	@sk_id						INT,
	@supp_id					INT


)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE	  		@comp_id					INT,
	@lang_id					INT,
	@bra_id						INT,
	@prof_id					INT,
	@user_id					INT,

SELECT		@comp_id				= 1,
			@poh_id					= 213
*/
-- ------------------------------------------------------

-- en wfmCommercialTransactions para PROVEEDORES UNICAMENTE verificar si
-- extiste una relacion en tbSupplierKindFilterByProfile para comp, bra y prof de sesion y
--  en caso de existir que el PROVEEDOR seleccionado en el eventtest tenga alguna clase asociada a ese perfil.
--SOLO VERIFICAR EN EL CASO DE EXISTIR LA RELACION COMP,BRA Y PROF, de lo contrario NO hacer NADA!

DECLARE		@BlockStatusCTSupp		INT

SET			@BlockStatusCTSupp = 1


	IF EXISTS ( SELECT tporc.sk_id
						FROM tbSupplierKindFilterByProfile 						tporc
						WHERE	tporc.comp_id		= @comp_id			AND
								tporc.bra_id		= @bra_id			AND
								tporc.prof_id		= @prof_id
					)

		BEGIN

				IF NOT EXISTS ( SELECT
							tporc.sk_id
				            FROM tbSupplier AS								ts

							INNER JOIN  tbSupplierKindFilterByProfile 		tporc
							ON	tporc.comp_id			= ts.comp_id	AND
								tporc.sk_id				= ts.sk_id

							WHERE	tporc.comp_id		= @comp_id		AND
									tporc.bra_id		= @bra_id		AND
									tporc.prof_id		= @prof_id		AND
									ts.supp_id			= @supp_id
					)

					BEGIN
					 --'La consulta al proveedor solicitado NO puede efectuarse ya que su perfil NO
					 -- posee relacionada la Clase de Proveeor correspondiente al proveedor seleccionado'

					 SET @BlockStatusCTSupp = 0
					END


		END

		SELECT @BlockStatusCTSupp [BlockStatusCTSupp]

END

GO





