CREATE PROCEDURE [dbo].[spCommercialTransactions_updateABalance]
(
	@comp_id							as int,
	@bra_id								as int,
	@ct_transaction						as int,
	@ct_abalance						as decimal(19,5),
	@CTL_Id								AS INT
)
AS
BEGIN

	set nocount ON
	-- =================================================================================================================
	-- Author		: HDP
	-- Update Date	: 2010-11-12
	-- Parte		: s/P referencia: #1
	-- Se quita una condición de inner join para que traiga comprobantes de diferentes sucursales
	-- =================================================================================================================

	-- -----------------------------------------------------
	-- -----------------------------------------------------
	/*
	declare 	@comp_id							as int,
		@bra_id								as int,
		@ct_transaction						as int,
		@ct_abalance						as decimal(19,5)
	select 	@comp_id						=1,
		@bra_id								=1,
		@ct_transaction						=64,
		@ct_abalance						=1000.00
	*/
	-- -----------------------------------------------------

	declare @d	int
	set		@d	= 2 -- HDP: Esto probablemente sea una MIERDA


	DECLARE @datProcessingDate AS DATETIME
	SELECT  @datProcessingDate = tb.bra_processingDate
		FROM tbBranch tb			WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id


	update	[tbCommercialTransactions]		WITH (ROWLOCK)

		set		[ct_ABalance]		= CASE
											--WHEN	sd_id IN (6,13) AND
											--		ct_ATotal > 0	AND
											--		ct_ABalance < 0						THEN	round([ct_ABalance],@d) + round(@ct_abalance,@d)	NO, rompe todo, NO hacerlo	-- MOS 02-2023 x FIESA y aplicar recibos con abalance negativo y atotal positiivo
											WHEN ct_ABalance > 0						THEN	round([ct_ABalance],@d) - round(@ct_abalance,@d)
											ELSE												round([ct_ABalance],@d) + round(@ct_abalance,@d)
   		             				  END,
   		         ct_lastPayDate		= @datProcessingDate,
   		         ct_DisableExchangeDifferenceInterest  =   -- MOS 02-2022: Para que NO vuelva a cobrar Dif de Cotización si es que desaplican el PUTO comprobante mil veces
   															CASE
																WHEN  CASE
																			WHEN ct_ABalance > 0	THEN	round([ct_ABalance],@d) - round(@ct_abalance,@d)
																			ELSE							round([ct_ABalance],@d) + round(@ct_abalance,@d)
   		             												  END = 0 THEN 1
   		             											ELSE ct_DisableExchangeDifferenceInterest
   															END

		where	[comp_id]			= @comp_id				AND
				[ct_transaction]	= @ct_transaction





	-- Actualiza el Saldo de las CUOTAS.-
	update	[tbCommercialTransactionsLoan]			WITH (ROWLOCK)
		set		ct_ABalance		= CASE
										WHEN ct_ABalance > 0		THEN	round([ct_ABalance],@d) - round(@ct_abalance,@d)
										ELSE								round([ct_ABalance],@d) + round(@ct_abalance,@d)
   		             				  END,
   		        ctl_lastPayDate = @datProcessingDate
		where	comp_id	= @comp_id				AND
				ctl_id	= @CTL_Id



END
GO






CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateAdditionalData]
(
	@comp_id					INT,
	@bra_id						INT,
	@ct_transaction				INT,
	@ba_id						INT,
	@return_value				INT 			OUTPUT,
	@ret_ErrorCode				INT 			OUTPUT,
	@ret_ErrorDescription		VARCHAR(200)	OUTPUT
)
AS
-- =================================================================================================================
-- Author		: MOS
-- Creation Date: 2011-01-13
-- Parte		: S/P
-- Description	: Sólo actualiza el ba_id (id de bankingaccount) ya que no lo tiene el insert general de
--				  commercialtransaction
-- =================================================================================================================
BEGIN

	SET NOCOUNT ON

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''


	UPDATE	tbCommercialTransactions	WITH (ROWLOCK)
		SET		ba_id			= @ba_id
		WHERE	comp_id			= @comp_id
		AND		bra_id			= @bra_id
		AND		ct_transaction	= @ct_transaction

END
GO







CREATE PROCEDURE [dbo].[spCommercialTransactions_updateBranchTransfer]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT, --destino
	@ct_transaction			INT,
	@supp_id				INT,
	@user_id				INT,
	@stor_id				INT,
	@return_value			INT OUTPUT,
	@ret_ErrorCode			INT OUTPUT,
	@ret_ErrorDescription	VARCHAR(200) OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------------------------------
	--
	--	ATENCION:!   Este SP SOLO puede ser modificado con autorizacion de MOS!!!!!!!
	--
	-- ------------------------------------------------------------------------------



	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-09-11
	-- Parte		: 550
	-- Description	: Se agregan los nuevos parámetros necesarios para ejecutar el sp spSecurityLog_insertData
	-- =================================================================================================================


	-- ------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------
	/*
		DECLARE
			@comp_id				INT,
			@lang_id				INT,
			@bra_id					INT,
			@ct_transaction			INT,
			@supp_id				INT,
			@user_id				INT,
			@return_value			INT,
			@ret_ErrorCode			INT,
			@ret_ErrorDescription	VARCHAR(200)


		SELECT
			@comp_id				= 1,
			@lang_id				= 2,
			@bra_id					= 35,
			@ct_transaction			= 6556,
			@supp_id				= 8113,
			@user_id				= 39



	*/
	-- ------------------------------------------------------------------------------


	set @return_value			= 0
	set	@ret_ErrorCode			= 0
	set	@ret_ErrorDescription	= ' '


    SAVE TRANSACTION traPROTECT_903
    BEGIN TRANSACTION
    BEGIN TRY

		DECLARE @lit_transaction INT
		DECLARE @lBra_Id AS INT


		-- Si ya se Proceso pero no se actualizo la grilla aun, sale sin volver a ingresar.-  MOS, 10-2011
		IF EXISTS (	SELECT TOP 1 1
						FROM tbCommercialTransactions tct		--WITH (NOLOCK)   NO PONER
	           			WHERE	tct.comp_id			= @comp_id
	           				AND tct.ct_transaction	= @ct_transaction
	           				AND ISNULL(tct.ct_Pending,'False') = 'False')
			BEGIN
				set @return_value			= -1
				set	@ret_ErrorCode			= 0
				set	@ret_ErrorDescription	= '*'
				Return
			END

		DECLARE @lct_transaction INT
		SET @lct_transaction = 0


		-- Deposito de Destino segun la sucursal de destino
	--	DECLARE @stor_id_destiny AS INT
	--	SELECT @stor_id_destiny = tb.stor_id
	--		FROM tbBranch tb
	--		WHERE	tb.comp_id	= @comp_id
	--			AND tb.bra_id	= @bra_id



		BEGIN TRY

			/*generación de nueva commercialtransaction de compras desde la original de ventas*/
			INSERT INTO tbCommercialTransactions	WITH (ROWLOCK)
			(
				comp_id,			bra_id,					ct_pointOfSale,			ct_kindOf,							ct_docNumber,
				ct_date,			ct_taxDate,				ct_payDate,				supp_id,							cust_id,
				ba_id,				cb_id,					[user_id],				ct_cd,								ct_subtotal,
				ct_total,			ct_discount,			ct_adjust,				ct_taxes,							curr_id_transaction,
				hacc_transaction,	sm_id,					disc_id,				ct_ATotal,							ct_ABalance,
				ct_ACurrency,		ct_ACurrencyExchange,	df_id,					dl_id,								st_id,
				sd_id,				puco_id,				ct_CompanyCurrency,		ct_Branch2CompanyCurrencyExchange,	ct_Pending,
				country_id,			state_id,				ct_isAvailableForImport,ct_soh_bra_id,						ct_soh_id,
				ct_CAI,				ct_CAIDate,				ct_CAIBarCodeImage,		ct_isAvailableForPayment,			ct_transaction_PackingList,
				ct_processingDate,	ct_AAdjust,				ct_dfExchange
			)

			SELECT
				tct.comp_id,		@bra_id,				tct.ct_pointOfSale,		tct.ct_kindOf,						tct.ct_docNumber,
				tct.ct_date,		tct.ct_taxDate,			tct.ct_payDate,			@supp_id,							NULL,
				tct.ba_id,			tct.cb_id,				@user_id,				GETDATE(),							tct.ct_subtotal,
				tct.ct_total,		tct.ct_discount,		tct.ct_adjust,			tct.ct_taxes,						tct.curr_id_transaction,
				tct.hacc_transaction,tct.sm_id,				tct.disc_id,			tct.ct_ATotal,						tct.ct_ABalance,
				tct.ct_ACurrency,	tct.ct_ACurrencyExchange,NULL,					tct.dl_id,							tct.st_id,
				tct.sd_id + 100,	tct.puco_id,			tct.ct_CompanyCurrency, tct.ct_Branch2CompanyCurrencyExchange, 'False',
				tct.country_id,		tct.state_id,			tct.ct_isAvailableForImport,tct.ct_soh_bra_id,				tct.ct_soh_id,
				tct.ct_CAI,			tct.ct_CAIDate,			tct.ct_CAIBarCodeImage, tct.ct_isAvailableForPayment,		tct.ct_transaction_PackingList,
				tct.ct_processingDate,tct.ct_AAdjust,		tct.ct_dfExchange

			FROM tbCommercialTransactions					tct	WITH (NOLOCK)
			WHERE tct.comp_id			= @comp_id
			AND   tct.ct_transaction	= @ct_transaction

			SET @lct_transaction = @@IDENTITY

		END TRY
		BEGIN CATCH
			Set @ret_ErrorCode			= -1
			Set	@ret_ErrorDescription	= '1 - ' + ERROR_MESSAGE()
			RETURN
		END CATCH




		BEGIN TRY
			/*Cargamos los items de la ItemTransaction Original en la ItemTransactionsTmp*/

			DECLARE @myid uniqueidentifier
			SET @myid = NEWID()

			INSERT INTO tbItemTransactionsTmp	WITH (ROWLOCK)
			(
				comp_id,			tis_guid,		tis_priority,		item_id,
				tis_itemDesc,		tis_detail,		curr_id,			tis_initQty,
				tis_qty,			tis_price,
				tax_id,
				stor_id,
				tis_CD,				bra_id,			tis_insertDate,		[user_id],
				tis_itemDiscount,	tis_IsEditing,	tis_IsEditingCd,	it_transaction, it_transaction4BranchTransfer,
				poh_id,				pod_id,			puco_id,			tis_IsBranchTransfer
			)

			SELECT
				tit2.comp_id,		@myid,			0,					ti.item_id,
				ti.item_desc,		NULL,			tit2.curr_id,		tit2.it_qty,
				tit2.it_qty,		tit2.it_price,
				(SELECT TOP 1 ttm.tax_id
					FROM tbTaxMovements ttm				WITH (NOLOCK)
						INNER JOIN tbTaxName ttn		WITH (NOLOCK)
							ON		ttn.comp_id	= ttm.comp_id
								and ttn.tax_id	= ttm.tax_id
					 WHERE  ttm.comp_id			= tit2.comp_id
						AND ttm.bra_id			= tit2.bra_id
						AND ttm.ct_transaction	= tit2.ct_transaction
						AND ttm.it_transaction	= tit2.it_transaction
						AND ttn.tax_class = 1

				),
				@stor_id,  --@stor_id_destiny ,
				GETDATE(),			@bra_id,		GETDATE(),			tct.[user_id],
				0,					0,				0,					NULL /*JAMAS INFORMARLO PLSSSSSSSSS  DEJA DE ANDAR TODO!!*/,tit2.it_transaction,  -- MOS 24-4-2015
				NULL,				NULL,			tct.puco_id,		'True'	--Es una TRANSFERENCIA entre Sucursales

			FROM tbItemTransactions							tit2		WITH (NOLOCK)

	--			LEFT JOIN tbTaxMovements					ttm
	--			ON ttm.comp_id			= tit2.comp_id
	--			AND ttm.bra_id			= tit2.bra_id
	--			AND ttm.ct_transaction	= tit2.ct_transaction
	--			AND ttm.it_transaction	= tit2.it_transaction

				INNER JOIN tbCommercialTransactions			tct			WITH (NOLOCK)
				ON tct.comp_id			= tit2.comp_id
				AND tct.bra_id			= tit2.bra_id
				AND tct.ct_transaction	= tit2.ct_transaction

				INNER JOIN tbItem							ti			WITH (NOLOCK)
				ON ti.comp_id			= tit2.comp_id
				AND ti.item_id			= tit2.item_id

			WHERE	tit2.comp_id		= @comp_id
			AND		tit2.ct_transaction = @ct_transaction
			AND		tit2.sitt_id		<> 150
			AND     tit2.sitt_id		<> 151			-- estaba con NOT IN (150,151)

		END TRY
		BEGIN CATCH
			Set @ret_ErrorCode			= -2
			Set	@ret_ErrorDescription	= '2 - ' + ERROR_MESSAGE()
			RETURN
		END CATCH



		--select @myid
		--delete tbItemTransactionsTmp
		--SELECT * FROM tbItemTransactionsTmp

		--DECLARE @myid uniqueidentifier
		--SET @myid = '190D0D0E-7DE9-4813-AECC-D59F60CA5A3C'

		BEGIN TRY

			DECLARE
				@currSupp	INT,
				@braCurr	INT,
				@exchange	DECIMAL(18,5)

		--	DECLARE	@lreturn_value INT,
		--			@lret_ErrorCode INT,
		--			@lret_ErrorDescription VARCHAR(200)

			SELECT @currSupp = ts.curr_id FROM tbSupplier ts WHERE ts.supp_id = @supp_id
			SELECT @braCurr = tb.curr_id  FROM tbBranch tb WHERE tb.bra_id = @bra_id

			SELECT @exchange = dbo.fnGetExchange2(@comp_id,1,@currSupp,@braCurr,@currSupp,@braCurr,0,0)

			--SELECT @currSupp [currSupp],@braCurr [braCurr], @exchange [exchange]

			EXEC spItemTransactions_insertData_ForBranchTransfer
				@comp_id,
				@bra_id,
				@lct_transaction,
				@myid,
				@currSupp,
				@braCurr,
				@exchange,
				'False',
				'FALSE',
				'FALSE',
				@return_value			OUTPUT,
				@ret_ErrorCode			OUTPUT,
				@ret_ErrorDescription	OUTPUT

			-- MOS 04-2014
			IF @return_value < 0 RETURN
				--SELECT @ret_ErrorCode,@ret_ErrorDescription



		END TRY
		BEGIN CATCH
			Set @ret_ErrorCode			= -3 + isnull(@ret_ErrorCode,0)
			Set	@ret_ErrorDescription	= '3 - ' + isnull(ERROR_MESSAGE(),'') + isnull(@ret_ErrorDescription,'')
			RETURN
		END CATCH



		/*Insertamos las TaxMovements correspondientes a la nueva CT_TRANSACTION*/

		BEGIN TRY

		DECLARE
			@comp_id1 INT,				@bra_id1 INT,					@pcm_id INT,					@tm_cd DATETIME,
			@tax_id INT,				@tm_subtotal DECIMAL(19,6),		@percentaje DECIMAL(19,6),		@tm_total DECIMAL(19,6),
			@curr_id INT,				@tm_exchangeToBranchCurrency DECIMAL(19,6),						@tm_docKindOf NVARCHAR(50),
			@tm_docPointOfSale INT,		@tm_docNumber NVARCHAR(50),		@tm_docDate DATETIME,			@tm_originalDocument NVARCHAR(200),
			@State_Id INT,				@Country_Id INT,				@tm_originalDocumentTypeOf NVARCHAR(50),
			@puco_id INT,				@litem_id INT

		DECLARE cursor1 CURSOR LOCAL  FAST_FORWARD FOR

			SELECT
				ttm.comp_id,			ttm.bra_id,						ttm.pcm_id,						ttm.tm_cd,
				ttm.tax_id,				ttm.tm_subtotal,				ttm.percentaje,					ttm.tm_total,
				ttm.curr_id,			ttm.tm_exchangeToBranchCurrency,ttm.tm_docKindOf,				ttm.tm_docPointOfSale,
				ttm.tm_docNumber,		ttm.tm_docDate,					ttm.tm_originalDocument,		ttm.State_Id,
				ttm.Country_Id,			ttm.tm_originalDocumentTypeOf,	ttm.puco_id,					tit.item_id

			FROM tbTaxMovements ttm							WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions tct		WITH (NOLOCK)
				ON	tct.comp_id			= ttm.comp_id
				AND tct.bra_id			= ttm.bra_id
				AND tct.ct_transaction	= ttm.ct_transaction

				INNER JOIN tbItemTransactions tit			WITH (NOLOCK)
				ON
					tit.comp_id			= tct.comp_id			AND
					tit.bra_id			= tct.bra_id			AND
					tit.ct_transaction	= tct.ct_transaction	AND
					tit.it_transaction	= ttm.it_transaction

			WHERE tct.comp_id			= @comp_id
			AND   ttm.ct_transaction	= @ct_transaction

		OPEN cursor1

		FETCH NEXT FROM cursor1
		INTO @comp_id1,				@bra_id1,					@pcm_id,					@tm_cd,
			 @tax_id,				@tm_subtotal,				@percentaje,				@tm_total,
			 @curr_id,				@tm_exchangeToBranchCurrency,							@tm_docKindOf,
			 @tm_docPointOfSale,	@tm_docNumber,				@tm_docDate,				@tm_originalDocument,
			 @State_Id,				@Country_Id,				@tm_originalDocumentTypeOf, @puco_id,
			 @litem_id





		WHILE @@FETCH_STATUS = 0
		BEGIN



			DECLARE cursor2 CURSOR LOCAL  FAST_FORWARD FOR

				SELECT
					tit2.it_transaction
					FROM   tbCommercialTransactions tct2		WITH (NOLOCK)
					INNER JOIN tbItemTransactions tit2			WITH (NOLOCK)
					ON	tit2.comp_id		= tct2.comp_id
					AND tit2.bra_id			= tct2.bra_id
					AND tit2.ct_transaction = tct2.ct_transaction
					and tit2.item_id		= @litem_id
					WHERE	TCT2.comp_id		= @comp_id		AND
							tct2.ct_transaction = @lct_transaction


			OPEN cursor2

			FETCH NEXT FROM cursor2
				INTO
					@lit_transaction
			WHILE @@FETCH_STATUS = 0
			BEGIN

				-- Se estaba pasando cualquier cosa como Bra en el alta, por lo que la recuperamos aqui.!!!!!!
				SELECT @lBra_Id = tct.bra_id
					FROM tbCommercialTransactions tct		WITH (NOLOCK)
					WHERE	tct.comp_id			= @comp_id	AND
							tct.ct_transaction  = @lct_transaction

				INSERT INTO tbTaxMovements		WITH (ROWLOCK)
				(
					comp_id,
					bra_id,
					ct_transaction,
					it_transaction,
					pcm_id,
					tm_cd,
					tax_id,
					tm_subtotal,
					percentaje,
					tm_total,
					curr_id,
					tm_exchangeToBranchCurrency,
					tm_docKindOf,
					tm_docPointOfSale,
					tm_docNumber,
					tm_docDate,
					tm_originalDocument,
					State_Id,
					Country_Id,
					tm_originalDocumentTypeOf,
					puco_id
				)
				VALUES
				(
					@comp_id1,
					@lBra_Id, -- @bra_id1,
					@lct_transaction,
					@lit_transaction,
					@pcm_id,
					GETDATE(),
					@tax_id,
					@tm_subtotal,
					@percentaje,
					@tm_total,
					@curr_id,
					@tm_exchangeToBranchCurrency,
					@tm_docKindOf,
					@tm_docpointOfSale,
					@tm_docNumber,
					@tm_docDate,
					@tm_originalDocument,
					@State_Id,
					@Country_Id,
					@tm_originalDocumentTypeOf,
					@puco_id
				)

				FETCH NEXT FROM cursor2
					INTO @lit_transaction
			end

			CLOSE cursor2
			DEALLOCATE cursor2

			FETCH NEXT FROM cursor1
				INTO
					 @comp_id1,				@bra_id1,					@pcm_id,					@tm_cd,
					 @tax_id,				@tm_subtotal,				@percentaje,				@tm_total,
					 @curr_id,				@tm_exchangeToBranchCurrency,							@tm_docKindOf,
					 @tm_docPointOfSale,	@tm_docNumber,				@tm_docDate,				@tm_originalDocument,
					 @State_Id,				@Country_Id,				@tm_originalDocumentTypeOf, @puco_id,
					 @litem_id

		END

		CLOSE CURSOR1
		DEALLOCATE cursor1

		END TRY
		BEGIN CATCH
			Set @ret_ErrorCode			= -4
			Set	@ret_ErrorDescription	= '4 - ' + ERROR_MESSAGE()
			RETURN
		END CATCH



		--==STL Hago un UPDATE de la tabla tbItemSerials
		UPDATE tbItemSerials		WITH (ROWLOCK)
		SET
			is_available	= 'True',
			stor_id			= @stor_id --@stor_id_destiny MOH
		FROM tbItemSerials its					--		WITH (NOLOCK)
		INNER JOIN tbItemTransactionSerials itts		WITH (NOLOCK)
			on		itts.comp_id	= its.comp_id
				AND itts.is_id		= its.is_id
		WHERE	itts.comp_id		= @comp_id
			AND itts.ct_transaction = @ct_transaction
		-- MOS: 08-2011
		--	WHERE is_id IN (SELECT tits.is_id
		--					FROM tbItemTransactionSerials		tits
		--					WHERE tbItemSerials.comp_id			= @comp_id
		--					AND tbItemSerials.ct_transaction	= @ct_transaction)




		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- MOS 11-2023:
		-- Los ENFERMOS de mierda de Electrom tocaron a proposito el puto boton al mismo tiempo.  Saqué arriba el nolock y volvi a poner esto abajo, x si pasa lo mismo, para que cancele la transaccion.
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
		IF EXISTS (	SELECT TOP 1 1
						FROM tbCommercialTransactions tct		--WITH (NOLOCK)   NO PONER
	           			WHERE	tct.comp_id			= @comp_id
	           				AND tct.ct_transaction	= @ct_transaction
	           				AND ISNULL(tct.ct_Pending,'False') = 'False')
			BEGIN
				set @return_value			= -1
				set	@ret_ErrorCode			= 0
				set	@ret_ErrorDescription	= '*'
				Return
			END
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------



		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- MOS 11-2023: puse arriba que vuelva a chequear ANTES de de hacer el update.
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
		BEGIN TRY

			/*Actualizamos la CommercialTransaction Original y le ponemos 'False' en el ct_Pending para que no se importe un remito duplicado*/

			UPDATE tbCommercialTransactions		WITH (ROWLOCK)
				SET
					ct_Pending = 'False'
				WHERE	comp_id			= @comp_id
				AND		ct_transaction	= @ct_transaction
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------

		END TRY
		BEGIN CATCH
			Set @ret_ErrorCode			= -5
			Set	@ret_ErrorDescription	= '5 - ' + ERROR_MESSAGE()
			RETURN
		END CATCH

		--SELECT @ret_ErrorCode,@ret_ErrorDescription

		--SELECT * FROM tbCommercialTransactions tct WHERE tct.ct_transaction = 3310




		BEGIN TRY

			DECLARE @lrv				INT,
					@lseclog_obs_2		VARCHAR(100),
					@lseclog_obs_3		VARCHAR(100)

			SET		@lseclog_obs_2		= 'original ct_transaction: '	+ convert(varchar,@ct_transaction)
			SET		@lseclog_obs_3		= 'new ct_transaction: '		+ convert(varchar,@lct_transaction)


			/*Generamos el movimiento en la SecurityLog*/
			EXEC spSecurityLog_insertData
				@comp_id			= @comp_id,
				@bra_id				= @bra_id,
				@user_id			= @user_id,
				@seclog_obs_1		= 'wfmBranchTransfers',
				@seclog_obs_2		= @lseclog_obs_2,
				@seclog_obs_3		= @lseclog_obs_3,
				@seclog_obs_4		= NULL,
				@aut_id				= NULL,
				@sysCode_id			= 500,
				@menu_id			= NULL,
				@request_ip			= NULL,
				@request_name		= NULL,
				@aure_isok			= NULL,
				@aure_user_id		= NULL,
				@prof_id			= NULL,
				@aure_id			= NULL,	-- Parte: 550
				@aure_cd			= NULL,	-- Parte: 550
				@seclog_id1			= NULL,
				@seclog_id2			= NULL,
				@seclog_id3			= NULL,
				@seclog_pageHTML	= NULL,
				@return_value		= @lrv OUTPUT


		END TRY
		BEGIN CATCH
			Set @ret_ErrorCode			= -6
			Set	@ret_ErrorDescription	= '6 - ' + ERROR_MESSAGE()
			RETURN
		END CATCH

		--SELECT @ret_ErrorCode,@ret_ErrorDescription


		SET @return_value = @lct_transaction


		-- ----------------------------------------------------------------
		-- Si es un remito de Transferencia , actualiza deposito totalizador de Articulos en transito
		-- ----------------------------------------------------------------
		DECLARE @intDfIdOfThisTrans AS INT
		SELECT	@intDfIdOfThisTrans = tct.df_id
			FROM tbCommercialTransactions tct		WITH (NOLOCK)
			WHERE	tct.comp_id			= @comp_id AND
					tct.ct_transaction	= @ct_transaction
		EXEC spStorage_updateInTransitStock @comp_id,@intDfIdOfThisTrans
		-- ----------------------------------------------------------------



		-- Pone que es una Recepcion de Transferencia entre Sucursales.!
		UPDATE tbItemTransactions	WITH (ROWLOCK)
			SET		sitt_id			= 120
			WHERE	comp_id			= @comp_id AND
					ct_transaction	= @lct_transaction



		-- MOS 08-2015
		-- Suma la cantidad disponible al despacho original de ese articulo
		UPDATE tbImportData		WITH (ROWLOCK)
			SET	impData_ActualQty		= impData_ActualQty + tit.itid_qty
			FROM  tbImportData						id	--WITH (NOLOCK)
			INNER JOIN tbItemTransactionImportData	tit	WITH (NOLOCK)
				ON	tit.comp_id			= id.comp_id		AND
					tit.impData_id		= id.impData_id
			INNER JOIN tbItemTransactions tit1			WITH (NOLOCK)
				ON	tit1.comp_id		= tit.comp_id		AND
					tit1.it_transaction = tit.it_transaction
			WHERE	tit.comp_id			= @comp_id			AND
					tit.ct_transaction	= @ct_transaction	AND
					tit1.item_id		= id.item_id



		/*insertamos la relacion entre el remito que se esta recibiendo y el recibido.*/

		EXEC spCommercialTransactions_Relations_InsertData_NoTransactional
				@comp_id				= @comp_id,
				@ct_transaction_1		= @ct_transaction,		-- ct ori
				@ct_transaction_2		= @lct_transaction,		-- ct new
				@class					= 4						-- branchtransfer



    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION traPROTECT_903
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_903










END
GO




-- =========================================================
-- Author:		GA
-- Create date: 27-09-2019
-- Description:	Modificar ARG:CAI/CAE/CAE, CH:Folio
-- =========================================================

CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateData_CAI]
(


	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,

	@ct_CAI					NVARCHAR(50),   -- ARG:CAI/CAE/CAE,CH:Folio
	@ct_CAIDate				DATETIME,		-- Fecha

	@ct_transaction			INT





)

AS




BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
					@comp_id				INT,
					@lang_id				INT,
					@bra_id					INT,
					@prof_id				INT,
					@user_id				INT,

					@ct_CAI					NVARCHAR(50),
					@ct_CAIDate				DATETIME


		SELECT
					@comp_id				= 1


*/

	-- -----------------------------------------------------------------------

	UPDATE tbCommercialTransactions			WITH (ROWLOCK)
		SET
			ct_CAI				= @ct_CAI,
			ct_CAIDate			= @ct_CAIDate
		WHERE	comp_id			= @comp_id			AND
				ct_transaction	= @ct_transaction


END

GO

