CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateData_Total]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,

	@ct_transaction			INT,
	@ct_total				DECIMAL(19,5)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------
		-- TESTING
		-- -----------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@ct_transaction	INT,
				@ct_CAI			NVARCHAR(50),
				@ct_CAIDate		DATETIME
		*/
		-- -----------------------------------

		-- Si lo encuentra, NO esta aplicado y el importe que se quiere poner no varía en mas de 1 de ABS,  lo hace.
		IF EXISTS(
					SELECT TOP 1 1
						FROM tbCommercialTransactions tt			WITH (NOLOCK)
						WHERE	tt.comp_id			= @comp_id				AND
								tt.ct_transaction	= @ct_transaction		AND
								tt.ct_ATotal        = tt.ct_ABalance		AND
								ABS(tt.ct_total - @ct_total) <= 1
					)
			BEGIN

				UPDATE tbCommercialTransactions		WITH (ROWLOCK)
					SET		ct_total		= @ct_total
					WHERE	comp_id			= @comp_id AND
							ct_transaction	= @ct_transaction


			END


	END
GO


