-- =============================================
-- MOS
-- Actualiza Commercial Transactions
-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateDataForSales]
	(
		@comp_id							as int,
		@bra_id								as int,
		@ct_docNumber						as varchar(40),
		@ct_date							as datetime,
		@supp_id							as int,
		@cust_id							as int,
		@cb_id								as int,
		@user_id							as int,
		@ct_subtotal						as decimal(19,5),
		@ct_total							as decimal(19,5),
		@ct_discount						as decimal(19,5),
		@ct_taxes							as decimal(19,5),
		@curr_id_transaction				as int,
		@sm_id								as int,
		@disc_id							as int,
		@ct_ATotal							as decimal(19,5),
		@ct_ABalance						as decimal(19,5),
		@ct_ACurrency						as int,
		@ct_ACurrencyExchange				as decimal(35,15),
		@df_id								as int,
		@dl_id								as int,
		@st_id								as int,
		@tis_guid			    			as uniqueidentifier,
		@ct_CompanyCurrency					as int,
		@ct_Branch2CompanyCurrencyExchange	as decimal(35,15),
		@sd_id_Alternative					as int,
		@note1								as nvarchar(200),
		@note2								as nvarchar(200),
		@note3								as nvarchar(200),
		@note4								as nvarchar(200),
		@ct_adjust							as int,
		@ct_transaction						as int,
		@ct_CAI								as varchar(50),
		@curr_Id_Other						AS INT,
		@curr_id_Exchange2Other				AS DECIMAL(35,15),
		@intCtTransaction_BarCode			AS INT,
		@dc_id								AS INT,
		@return_value						as int			output,
		@ret_ErrorCode						as int			output,
		@ret_ErrorDescription				as varchar(200) output
	)

AS
BEGIN

--SELECT 1 / 0

	SET NOCOUNT ON;

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''


	--DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	--IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT_904		-- MOS 06-2020
    --SAVE TRANSACTION traPROTECT_904
    --BEGIN TRANSACTION
    BEGIN TRY

		IF @dc_id = -1 SET @dc_id = NULL

		DECLARE @tis_CreditIntPercentage		AS DECIMAL(20,10)
		DECLARE @tis_CreditIntPlusPercentage	AS DECIMAL(20,10)
		DECLARE @ccp_id AS INT
		SET		@ccp_id = NULL
		SELECT TOP 1	@ccp_id							= ttis.ccp_id,
						@tis_CreditIntPercentage		= ttis.tis_CreditIntPercentage,
						@tis_CreditIntPlusPercentage	= ttis.tis_CreditIntPlusPercentage
			FROM tbTempItemStock ttis		WITH (NOLOCK)
			WHERE	ttis.comp_id	= @comp_id AND
					ttis.tis_guid	= @tis_guid




		-- OJO, Asignarlos
		Declare @ct_cd							as datetime
		Declare @ct_pointOfSale					as int
		Declare @ct_taxDate						as datetime
		Declare @ct_payDate						as datetime
		Declare @sd_id							as int
		Declare @sd_Kindof						as varchar(10)
		Declare @country_id						as int
		Declare @state_id						as INT
		DECLARE @intTransactionDecimalPlaces	AS integer
		DECLARE @strCAIFromDocumentsFile		AS VARCHAR(50)
		DECLARE @datCAIDateFromDocumentsFile	AS DATETIME
		DECLARE @bitIsFiscalDocument			AS BIT

		Set @country_id	 = Null
		Set @state_id	 = NULL
		SET @bitIsFiscalDocument		 = 'false'
		Set @strCAIFromDocumentsFile	 = @ct_CAI

		-- MOS 09-2021, lo puse abajo.
		--Set @datCAIDateFromDocumentsFile = (SELECT tb.bra_processingDate
		--										FROM tbBranch tb	WITH (NOLOCK)
		--										WHERE	tb.comp_id	= tb.comp_id
		--											AND tb.bra_id	= @bra_id)


		SELECT	@intTransactionDecimalPlaces	= bra_TransactionDecimalPlaces,
				@datCAIDateFromDocumentsFile	= bra_processingDate
			FROM tbBranch	WITH (NOLOCK)
			WHERE	comp_id = @comp_id
				AND bra_id  = @bra_id



		--If Not (@cust_id is Null)
		--	Begin
		--		Select @country_id = country_id,
		--			   @state_id   = state_id
		--			from dbo.tbCustomer		WITH (NOLOCK)
		--			Where	comp_id = @comp_id
		--				and cust_id = @cust_id
		--	End


		If @cust_id IS NOT Null
			Begin
				Select @country_id	= country_id,
					   @state_id	= state_id
					from dbo.tbCustomer				WITH (NOLOCK)
					Where	comp_id = @comp_id
						and cust_id = @cust_id
			END

		IF @cb_id IS NOT NULL	-- Si es la la Sucursal de un Cliente saca la provincia de la Sucursal del Cliente
			BEGIN
				Select @country_id	= country_id,
					   @state_id	= state_id
					from dbo.tbCustomerBranch				WITH (NOLOCK)
					Where	comp_id = @comp_id	AND
							cust_id = @cust_id	AND
							cb_id	= @cb_id
			END





		DECLARE @intdf_id4AdditionalIncrement AS INT

		DECLARE	@CAEA_isAvailable		 BIT	,
				@CAEA_fromDate			 datetime ,
				@CAEA_toDate				 DATEtime ,
				@CAEA_CAEANumber			 NVARCHAR(50)


			SET		@ct_pointOfSale = 0
		-- Recupera tbSysDocuments (Tipo de Documento del Sistema.-)
			Select	@sd_id							= A.sd_id,
					@intdf_id4AdditionalIncrement	= A.df_id4AdditionalIncrement,
					@CAEA_isAvailable				= ISNULL(A.df_CAEA_isAvailable,'False'),
					@CAEA_fromDate					= A.df_CAEA_fromDate,
					@CAEA_toDate					= A.df_CAEA_toDate,
					@CAEA_CAEANumber				= A.df_CAEA_CAEANumber,
					-- MOS 02-2022 se paso de abajo acá para no leer dos veces al pedo
					@ct_pointOfSale					= A.df_pointOfSale ,
					@sd_Kindof						= A.df_Kindof,
					@bitIsFiscalDocument			= A.df_Fiscal_IsFiscalPrinter
				From dbo.tbDocumentsFile A		WITH (NOLOCK)
	   			WHERE	A.comp_id	= @comp_id AND
	   					A.df_Id		= @df_id


		-- MOS 02-2022
		-- Si es NC o Nd x Diferencia de Cotizacion ( Clientes en USD )
		IF @sd_id IN (43,44)
			BEGIN
				SET @ct_ABalance = 0
			END

		-- Si viene un @sd_id_Alternative, lo hace igual
		If not @sd_id_Alternative is Null
			Begin
				Set @sd_id = @sd_id_Alternative
			End






		-- ------------------------------------------------------------
		-- Recupera Punto de Venta de la tabla de Documentos de Ventas
		-- ------------------------------------------------------------
		-- MOS 02-2022: Se paso arriba para no leer al pedo dos veces lo mismo
		--SET		@ct_pointOfSale = 0
		--Select	@ct_pointOfSale			= A.df_pointOfSale ,
		--		@sd_Kindof				= A.df_Kindof,
		--		@bitIsFiscalDocument	= A.df_Fiscal_IsFiscalPrinter
		--	From dbo.tbDocumentsFile A		WITH (NOLOCK)
		--	Where   A.comp_id = @comp_id	AND
		--			A.df_id   = @df_id



		-- MOS 09-2021, Refactoring
		--if EXISTS (	SELECT TOP 1  1
		--				from dbo.tbDocumentsFile A		WITH (NOLOCK)
		--				Where A.comp_id = @comp_id and A.df_id   = @df_id)
		--	BEGIN
		--		Select @ct_pointOfSale		= A.df_pointOfSale ,
		--			   @sd_Kindof			= A.df_Kindof,
		--			   @bitIsFiscalDocument = A.df_Fiscal_IsFiscalPrinter
		--			From dbo.tbDocumentsFile A		WITH (NOLOCK)
		--			Where   A.comp_id = @comp_id	AND
		--				    A.df_id   = @df_id
		--	END
		--ELSE
		--	BEGIN
		--		set @ct_pointOfSale = 0
		--	END
		-- ------------------------------------------------------------

		-- ------------------------------------------------------------
		-- Si no es un documento fiscal, saca el cai de documentsfile
		-- ------------------------------------------------------------
		IF @bitIsFiscalDocument = 'false'
			BEGIN
				Select @strCAIFromDocumentsFile		= dfl.df_cai ,
					   @datCAIDateFromDocumentsFile	= dfl.df_caiVto
					From dbo.tbDocumentsFile DFL		WITH (NOLOCK)
					Where   dfl.comp_id = @comp_id
						and dfl.df_id   = @df_id
			END
		-- ------------------------------------------------------------


		-- ------------------------------------------------------------
		-- Calcula la fecha de vencimiento segun la condicion de venta
		-- ------------------------------------------------------------
		Set @ct_cd = getdate()

		Set @ct_taxDate = @ct_date
		Set @ct_payDate = (@ct_date + IsNull((Select A.st_days2Pay
												From dbo.tbSalesTerms A		WITH (NOLOCK)
												Where   A.comp_id = @comp_id
													and A.st_id   = @st_id)
											,0)
						  )
		-- ------------------------------------------------------------


		-- ------------------------------------------------------------
		-- Calculos para grabar el campo : ct_dfExchange
		-- Se usa para poner el tipo de cambio en la impresion de
		-- los comprobantes.-
		-- ------------------------------------------------------------
		DECLARE @intcurr_id2Exchange	AS INT
		DECLARE @intBranchCurrency		AS integer

		SELECT @intBranchCurrency	= tb.curr_id
			FROM tbBranch tb				WITH (NOLOCK)
			WHERE	tb.comp_id		= @comp_id
				AND tb.bra_id		= @bra_id

		SELECT @intcurr_id2Exchange = tdf.df_curr_id2Exchange
			FROM tbDocumentsFile tdf		WITH (NOLOCK)
			WHERE	tdf.comp_id			= @comp_id
				AND tdf.df_id			= @df_id


		DECLARE @decdfExchange AS DECIMAL(35,15)
		set @decdfExchange = dbo.fnGetExchange2(@comp_id,
												1 ,
												@intcurr_id2Exchange,
												@intBranchCurrency,
												@curr_Id_Other,
												@intBranchCurrency,
												@curr_id_Exchange2Other,
												'false')

		DECLARE @decdfExchangeOriginal AS DECIMAL(35,15)		-- al tipo de cambio del momento
		set @decdfExchangeOriginal = dbo.fnGetExchange2(@comp_id,
														1 ,
														@intcurr_id2Exchange,
														@intBranchCurrency,
														0,
														0,
														0,
														'false')


		DECLARE @curr_id4Exchange	AS INT
		DECLARE @ct_curr_IdExchange AS DECIMAL(35,15)

		SELECT @curr_id4Exchange	= tb.curr_id4Exchange
			FROM tbBranch tb		WITH (NOLOCK)
			WHERE	tb.comp_id		= @comp_id
				AND tb.bra_id		= @bra_id
		set @ct_curr_IdExchange = dbo.fnGetExchange2(@comp_id,
												1 ,
												@curr_id4Exchange,
												@intBranchCurrency,
												@curr_Id_Other,
												@intBranchCurrency,
												@curr_id_Exchange2Other,
												'false')

		DECLARE @ct_curr_IdExchangeOriginal AS DECIMAL(35,15)		-- al tipo de cambio del momento
		set @ct_curr_IdExchangeOriginal = dbo.fnGetExchange2(@comp_id,
												1 ,
												@curr_id4Exchange,
												@intBranchCurrency,
												0,
												0,
												0,
												'false')
		-- ------------------------------------------------------------









		-- Si no hay Proveedor Poner Null
		--If @supp_id = 0
		--Begin
		--	Set @supp_id = Null
		--End
		--
		---- Si no hay Cliente Poner Null
		--If @cust_id = 0
		--Begin
		--	Set @cust_id = Null
		--End

		---- Si no hay Sucursal del Cliente Poner Null
		--If @cb_id = 0
		--Begin
		--	Set @cb_id = Null
		--End



		-- --------------------------------------------------------------
		-- Si debe actualizar la numeracion de algun otro documento
		-- como ser que actualice el numero de remito si se emite
		-- una factura sola.
		-- --------------------------------------------------------------
		-- DECLARE @intdf_id4AdditionalIncrement AS INT
		IF @intdf_id4AdditionalIncrement IS NOT NULL
			BEGIN
				UPDATE tbDocumentsFile WITH (ROWLOCK)
				SET
					df_number = df_number + 1
				WHERE	comp_id = @comp_id AND
						df_id	= @intdf_id4AdditionalIncrement
			END
		-- --------------------------------------------------------------


		IF @CAEA_isAvailable = 'True'
			BEGIN
				 SET @strCAIFromDocumentsFile		= @CAEA_CAEANumber
				 SET @datCAIDateFromDocumentsFile	= ISNULL(@CAEA_toDate,GETDATE())
			END








		Update dbo.tbCommercialTransactions	--  MOS 07-2024  WITH (ROWLOCK)
			Set comp_id							= @comp_id,
				bra_id							= @bra_id,
				ct_kindOf						= @sd_Kindof,
				ct_pointOfSale					= @ct_pointOfSale,
				ct_docNumber					= @ct_docNumber,
				ct_date							= @ct_date,
				ct_taxDate						= @ct_taxDate,
				ct_payDate						= @ct_payDate,
				supp_id							= @supp_id,
				cust_id							= @cust_id,
				cb_id							= @cb_id,
				user_id							= @user_id,
				ct_cd							= @ct_cd,
				ct_subtotal						= Round(@ct_subtotal,	@intTransactionDecimalPlaces),
				ct_total						= Round(@ct_total,		@intTransactionDecimalPlaces),
				ct_discount						= Round(@ct_discount,	@intTransactionDecimalPlaces),
				ct_taxes						= Round(@ct_taxes,		@intTransactionDecimalPlaces),
				curr_id_transaction				= @curr_id_transaction,
				sm_id							= @sm_id,
				disc_id							= @disc_id,
				ct_ATotal						= Round(@ct_ATotal,		@intTransactionDecimalPlaces),
				ct_ABalance						= Round(@ct_ABalance,	@intTransactionDecimalPlaces),
				ct_ACurrency					= @ct_ACurrency,
				ct_ACurrencyExchange			= @ct_ACurrencyExchange,
				df_id							= @df_id,
				dl_id							= @dl_id,
				st_id							= @st_id,
				sd_id							= @sd_id,
				ct_CompanyCurrency					= @ct_CompanyCurrency,
				ct_Branch2CompanyCurrencyExchange	= @ct_Branch2CompanyCurrencyExchange,
				country_id							= @country_id,
				state_id							= @state_id,
				ct_Pending							= 'True',
				ct_adjust							= @ct_adjust,
				ct_CAI								= @strCAIFromDocumentsFile, --@ct_CAI,
				ct_caiDate							= @datCAIDateFromDocumentsFile,
				ct_dfExchange	                    = @decdfExchange,
				curr_id4dfExchange					= @intcurr_id2Exchange,
				curr_id4Exchange					= @curr_id4Exchange,
				ct_curr_IdExchange					= @ct_curr_IdExchange,
				ct_TransactionBarCode				= @intCtTransaction_BarCode,
				ct_dfExchangeOriginal				= @decdfExchangeOriginal,
				ct_curr_IdExchangeOriginal			= @ct_curr_IdExchangeOriginal ,
				ccp_id								= @ccp_id,
				ct_CreditIntPercentage				= @tis_CreditIntPercentage,
				ct_CreditIntPlusPercentage			= @tis_CreditIntPlusPercentage,
				dc_id								= @dc_id
			Where	comp_id							= @comp_id
				and	ct_transaction					= @ct_transaction

		--@hacc_transaction,

		Set @return_value = @ct_transaction






	-- ----------------------------------------------------
	-- Actualiza el tis_id con el que se asigno a su sod_id
	-- *KJH09744TFRX
	-- ----------------------------------------------------
	DECLARE @intSOHBraId	AS INT
	DECLARE @intSHO_Id		AS INT
	SELECT	@intSOHBraId = tsocct.bra_id,
			@intSHO_Id	 = tsocct.soh_id
		FROM tbSaleOrderCreditCardsTMP tsocct	WITH (NOLOCK)
		WHERE tsocct.tis_guid = @tis_guid


	DELETE FROM tbSaleOrderCreditCards -- MOS 07-2024 WITH (ROWLOCK)
		WHERE	comp_id = @comp_id	AND
				bra_id	= @intSOHBraId	AND
				soh_id	= @intSHO_Id

	INSERT INTO tbSaleOrderCreditCards	WITH (ROWLOCK)
	(
		comp_id,
		tis_guid,
		bra_id,
		soh_id,
		cc_id,
		ccp_id,
		sohp_total,
		sohp_percentage,
		sohp_position,
		ct_transaction,
		ccm_cardNumber,
		ccm_cardEmissionDate,
		ccm_cardExpirationDate,
		ccm_customerDocumentNumber,
		ccm_customerName,
		ccm_AutorizationCode,
		ccm_receiptNumber,
		cmm_lote,
		ct_transaction_Rc
	)
	SELECT	comp_id,
			NULL,
			bra_id,
			soh_id,
			cc_id,
			ccp_id,
			sohp_total,
			sohp_percentage,
			sohp_position,
			@ct_transaction,
			ccm_cardNumber,
			ccm_cardEmissionDate,
			ccm_cardExpirationDate,
			ccm_customerDocumentNumber,
			ccm_customerName,
			ccm_AutorizationCode,
			ccm_receiptNumber,
			cmm_lote,
			ct_transaction_Rc
		FROM  tbSaleOrderCreditCardsTMP	WITH (NOLOCK)
		WHERE	tis_guid	= @tis_guid


	-- --------------------------------------------------------------
	-- Actualizo el Coeficiente de Plan de Descuentos MOS 10-2020
	-- --------------------------------------------------------------
	IF @@ROWCOUNT > 0
		BEGIN
			DECLARE @bitDiscountPlanEnabled AS BIT = 'False'
			DECLARE @decCashCoeficient		AS DECIMAL(19,4)
			SELECT	@decCashCoeficient		= tst.st_discountPlanCoeficient,
					@bitDiscountPlanEnabled = ISNULL(tst.st_collectionDiscountsAvailable,'False')
				FROM tbSalesTerms AS tst WITH (NOLOCK)
				WHERE	tst.comp_id = @comp_id	AND
						tst.st_id	= @st_id

			IF @bitDiscountPlanEnabled = 'true'
				BEGIN
					DECLARE @decTotalPayments				AS DECIMAL(19,4) = 0
					DECLARE @decTotalByCoeficientPayment	AS DECIMAL(19,4) = 0
					SELECT  @decTotalByCoeficientPayment = 	@decTotalByCoeficientPayment + 
															(
																CASE
																	WHEN tcmp.sohp_position = 8 THEN @decCashCoeficient
																	WHEN tcmp.sohp_position = 9 THEN ISNULL(tct.ct_discountPlanCoeficient,1)
																	ELSE							 ISNULL(tcclp.ccp_discountPlanCoeficient,1)
																END		* tcmp.sohp_total
															) ,
							@decTotalPayments			 =  @decTotalPayments + tcmp.sohp_total
						FROM  tbSaleOrderCreditCardsTMP AS tcmp		WITH (NOLOCK)
						LEFT JOIN tbCommercialTransactions AS tct	WITH (NOLOCK)
							ON	tct.comp_id			= tcmp.comp_id	AND
								tct.ct_transaction	= tcmp.ct_transaction_Rc
						INNER JOIN tbCreditCardLoanPlan AS tcclp	WITH (NOLOCK)
							ON	tcclp.comp_id = tcmp.comp_id		AND
								tcclp.cc_id   = tcmp.cc_id			AND
								tcclp.ccp_id  = tcmp.ccp_id
						WHERE tis_guid = @tis_guid

					UPDATE tbCommercialTransactions		-- MOS 07-2024 WITH (ROWLOCK)
						SET ct_discountPlanCoeficient = ISNULL(@decTotalByCoeficientPayment,0) / dbo.fnNoZDiv(@decTotalPayments)
					WHERE	comp_id			= @comp_id AND
							ct_transaction	= @ct_transaction
				END

		END
	-- --------------------------------------------------------------


	DELETE FROM tbSaleOrderCreditCardsTMP -- WITH (ROWLOCK)
		WHERE tis_guid = @tis_guid
	-- ----------------------------------------------------




	-- ----------------------------------------------------
	-- Si es una Nota de Debito por Financiacion de Terceros
	-- graba la relacion de ct_transactions con clase 1
	-- ----------------------------------------------------
	DECLARE @intCTTransactionOriginal AS INT
	-- Recupero el Nro de Pedido de esta tabla ahora . . .
	SELECT	@intSOHBraId = tsocct.bra_id,
			@intSHO_Id	 = tsocct.soh_id
		FROM tbTempItemStock tsocct		WITH (NOLOCK)
		WHERE	tsocct.tis_guid = @tis_guid AND
				tsocct.soh_id IS NOT NULL		-- por si tiene algun puto recargo x flete o algo q no pone el soh_id

	-- 1er paso, documento de Terceros !
	-- Si es el Debito Interno dejo guardado cual era el ct_transaction Original
	IF EXISTS(	SELECT top 1  1
					FROM tbDocumentsFile tdf	WITH (NOLOCK)
	          		WHERE	tdf.comp_id = @comp_id	AND
	          				tdf.df_id	= @df_id	AND
							tdf.df_3rdSales_isAvailable4RegisterSale = 'True'
		)
		BEGIN

			UPDATE tbSaleOrderHeader	-- MOS 07-2024 WITH (ROWLOCK)
			SET tbSaleOrderHeader.aux_3RDSales_lastCTTransaction = @ct_transaction
				FROM	tbSaleOrderHeader tsoh
				WHERE	tsoh.comp_id	= @comp_id		AND
						tsoh.bra_id		= @intSOHBraId	AND
						tsoh.soh_id		= @intSHO_Id



		END

	-- 2do paso, Nota de Debito !
	-- Si es la Nota de Debito grabo la relacion entre los dos comprobantes.
	IF EXISTS(	SELECT TOP 1  1
					FROM tbDocumentsFile tdf	WITH (NOLOCK)
	          		WHERE	tdf.comp_id = @comp_id	AND
	          				tdf.df_id	= @df_id	AND
							tdf.df_3rdSales_isDebitNoteDocument = 'True'
		)
		BEGIN
			SELECT	@intCTTransactionOriginal = tsoh.aux_3RDSales_lastCTTransaction
				FROM	tbSaleOrderHeader tsoh	WITH (NOLOCK)
				WHERE	tsoh.comp_id	= @comp_id		AND
						tsoh.bra_id		= @intSOHBraId	AND
						tsoh.soh_id		= @intSHO_Id

			IF @intCTTransactionOriginal IS NOT NULL
				BEGIN
					INSERT INTO tbCommercialTransactions_Relations	-- MOS 07-2024 WITH (ROWLOCK)
					(
						comp_id,
						ct_transaction_1,
						ct_transaction_2,
						class
					)
					VALUES
					(
						@comp_id,
						@intCTTransactionOriginal,
						@ct_transaction,
						2 -- OJO: Enumeracion de la clase clsCommercialTransactions_Relations: commercialTransactionsThirdSales
					)
				END

		END
	-- ----------------------------------------------------


	-- ----------------------------------------------------
	-- Graba la relacion si es una ND por Intereses de Cobranzas
	-- ----------------------------------------------------
	DECLARE @intCTR_ID4CollectionInterest AS INT
	SET		@intCTR_ID4CollectionInterest	= NULL
	IF EXISTS(	SELECT TOP 1  1
					FROM tbDocumentsFile tdf	WITH (NOLOCK)
	          		WHERE	tdf.comp_id = @comp_id	AND
	          				tdf.df_id	= @df_id	AND
							tdf.df_Collection_Interest_isDebitNoteDocument = 'True'
		)
		BEGIN

			SELECT	@intCTTransactionOriginal = tsoh.aux_collectionInterest_lastCTTransaction
				FROM	tbSaleOrderHeader tsoh	WITH (NOLOCK)
				WHERE	tsoh.comp_id	= @comp_id		AND
						tsoh.bra_id		= @intSOHBraId	AND
						tsoh.soh_id		= @intSHO_Id


			IF @intCTTransactionOriginal IS NOT NULL AND
				-- MOS 09-2022: En Fiesa si hacian un recibo a cuenta y lo aplicaban y se generaba el pedido de ND PENDIENTE de emitir, daba error de FK x este campo
			   EXISTS (	SELECT TOP 1 1
							FROM tbCommercialTransactions AS tct WITH (NOLOCK)
			           		WHERE	tct.comp_id			= @comp_id AND
			           				tct.ct_transaction	= @intCTTransactionOriginal
					  )
				BEGIN

					INSERT INTO tbCommercialTransactions_Relations	-- MOS 07-2024 WITH (ROWLOCK)
					(
						comp_id,
						ct_transaction_1,
						ct_transaction_2,
						class
					)
					VALUES
					(
						@comp_id,
						@intCTTransactionOriginal,
						@ct_transaction,
						5 -- OJO: Enumeracion de la clase clsCommercialTransactions_Relations: commercialTransactionsCollectionInterest
					)
					SET @intCTR_ID4CollectionInterest = @@IDENTITY
				END

		END
	-- ----------------------------------------------------


	-- ----------------------------------------------------
	-- Para el caso de Interes x cobranza, intenta aplicarlos
	-- ----------------------------------------------------
	IF @intCTR_ID4CollectionInterest IS NOT NULL
		BEGIN
			EXEC spCommercialTransactions_CustomerBalanceAutomaticAplication @comp_id, @bra_id, @cust_id, @intCTR_ID4CollectionInterest
		END
	-- ----------------------------------------------------



	-- ----------------------------------------------------
	-- Si es el Remito de Facturas
	-- incluye la relacion
	-- ----------------------------------------------------
	INSERT INTO tbCommercialTransactions_Relations
	(
		comp_id,
		ct_transaction_1,
		ct_transaction_2,
		class
	)
		SELECT	DISTINCT
				@comp_id,
				ttis.ct_transaction_SelectFromPacking,
				@ct_transaction,
				10
			FROM tbTempItemStock ttis		WITH (NOLOCK)
			WHERE	ttis.tis_guid							= @tis_guid  AND
					ttis.ct_transaction_SelectFromPacking	IS NOT NULL
	-- ----------------------------------------------------






	-- Guarda Historial de Autorizaciones !
	EXEC spAutorizationRequest_History_insertData	@comp_id,
													@tis_guid,
													@ct_transaction ,
													@intSOHBraId,
													@intSHO_Id



    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT_904
        --IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT_904		-- MOS 06-2020
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_904


END






GO




-- Modificacion de datos de items en la cta cte de clientes.


CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateDataItemTransactions]
(
	@comp_id							as INT,
	@sdlmt_id							as INT,
	@sreas_id							as INT,
	@stor_id							AS INT,
	@it_deliveryDate					AS DATETIME,
	@it_isBlocked4Delivery				AS BIT,
	@it_isCompensed						AS BIT,
	@it_disablePrintInEmmition			AS BIT,
	@it_priceOfCost						AS DECIMAL(19,6),
	@it_priceBOfCost					AS DECIMAL(19,6),
	@it_transaction						as INT
)

AS




BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
					@comp_id			as INT,
					@sdlmt_id			as INT,
					@sreas_id			as INT,
					@stor_id			AS INT,
					@it_transaction		as INT


		SELECT
					@comp_id				= 1,
					@sreas_id				= 1,
					@sreas_id				= 6165,
					@stor_id				= 10,
					@it_transaction			= 6222



*/

	-- -----------------------------------------------------------------------

	IF @sdlmt_id = -1
	BEGIN
		SET @sdlmt_id = NULL
	END

	IF @sreas_id = -1
	BEGIN
		SET @sreas_id = NULL
	END


	UPDATE tbItemTransactions
		SET
		sdlmt_id					= @sdlmt_id,
		sreas_id					= @sreas_id,
		it_deliveryDate				= @it_deliveryDate,
		it_isBlocked4Delivery		= @it_isBlocked4Delivery,
		it_isCompensed				= @it_isCompensed,
		it_disablePrintInEmmition	= @it_disablePrintInEmmition,
		it_priceOfCost				= @it_priceOfCost,
		it_priceBOfCost				= @it_priceBOfCost


		WHERE comp_id			= @comp_id			AND
			  it_transaction	= @it_transaction


	IF @it_isBlocked4Delivery = 'True'
		BEGIN
			UPDATE  tbAssembly_Turns4Assembly
				SET ta_isCancelled = 'True'
				WHERE	comp_id			= @comp_id AND
						it_transaction	= @it_transaction
		END



	IF NOT EXISTS ( SELECT titd.it_transaction
						FROM tbItemTransactionsDelivery titd		WITH (NOLOCK)
						WHERE titd.comp_id		  = @comp_id			AND
							  titd.it_transaction = @it_transaction
					)
		BEGIN

				INSERT INTO tbItemTransactionsDelivery
				(
					comp_id,
					bra_id,
					ct_transaction,
					it_transaction,
					itd_isPending,
					stor_id,
					itd_isByCode,
					[user_id],
					itd_deliveryDate,
					bra_id_delivery,
					IPNumber,
					itd_wasCancelled,
					user_id_Cancelled,
					itd_cancellDate,
					itd_guid,
					itd_isBlocked4Delivery
				)

				SELECT

					tit.comp_id,
					tit.bra_id,
					tit.ct_transaction,
					tit.it_transaction,
					1,
					@stor_id,
					NULL,
					tct.[user_id],
					tit.it_cd,
					NULL,
					NULL,
					NULL,
					NULL,
					NULL,
					NULL,
					tit.it_isBlocked4Delivery

				FROM tbItemTransactions											tit		WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions								tct		WITH (NOLOCK)
				ON  tct.comp_id				= tit.comp_id			AND
					tct.bra_id				= tit.bra_id			AND
					tct.ct_transaction		= tit.ct_transaction


				WHERE tit.comp_id			= @comp_id				AND
					  tit.it_transaction	= @it_transaction


		END

	ELSE

		BEGIN

			UPDATE tbItemTransactionsDelivery

			SET		itd_isBlocked4Delivery	= @it_isBlocked4Delivery


			WHERE	comp_id				= @comp_id			AND
					it_transaction		= @it_transaction   AND
					itd_isPending       = 'True'


		END




END

GO




CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateDataItemTransactions_Supp]
(
	@comp_id				as INT,
	@puco_id				AS INT,
	@it_transaction			as INT,
	@bra_id					AS INT

)

AS



BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
					@comp_id				as INT,
					@puco_id				AS INT,
					@it_transaction			as INT,
					@bra_id					AS INT

		SELECT
					@comp_id				= 1,
					@puco_id				= 185,
					@bra_id					= 1,
					@it_transaction			= 14276

*/
	-- -----------------------------------------------------------------------
		Declare @ct_CompanyCurrency as INT

		-- Variables para Tipo de Cambio Alternativo.-------
		Declare @intForcedExchangeCurrency1 AS INT
		Declare @intForcedExchangeCurrency2 AS INT
		DECLARE @intBranchCurrency AS INT
		Declare @decForcedExchange			AS DECIMAL(19,6)
		SELECT @intForcedExchangeCurrency1 = tct.curr_id4Exchange,
			   @intForcedExchangeCurrency2 = tct.curr_id_transaction,
			   @decForcedExchange		   = tct.ct_curr_IdExchange,
			   @intBranchCurrency		   = tct.curr_id_transaction
			FROM tbItemTransactions								tit WITH(NOLOCK)
			INNER JOIN tbCommercialTransactions					tct	WITH(NOLOCK)
			ON	tct.comp_id			= tit.comp_id			AND
				tct.ct_transaction	= tit.ct_transaction

			--FROM tbCommercialTransactions tct
			WHERE	tit.comp_id			= @comp_id AND
					tit.it_transaction	= @it_transaction
		-- -------------------------------------------------

		---- Fecha Impositiva de la Transaccion
		--	Select @intBranchCurrency		  = curr_id_transaction
		--		From dbo.tbCommercialTransactions		WITH (NOLOCK)
		--		Where	comp_id			= @comp_id
		--			and	ct_transaction  = @ct_transaction



		-- Moneda de la Compañia
		Select
			@ct_CompanyCurrency = curr_id
			From dbo.tbCompany						WITH (NOLOCK)
			Where comp_id = @comp_id



				Select 	 Sum(
  							 dbo.fnGetExchange2(@comp_id,
   												   A.it_price * A.it_qty * ISNULL(A.it_exchangeToBranchCurrency,1),
												   @intBranchCurrency,
												   @ct_CompanyCurrency,
												   @intForcedExchangeCurrency1 ,
												   @intForcedExchangeCurrency2 ,
												   @decForcedExchange,
												   0)
							)						[TotalByAcc],
						-- @cc_Code					[cc_Code],
						 CASE
							when B.acc_count_id4Purchase IS NULL THEN tpc.acc_count_id
							else B.acc_count_id4Purchase
						 END						[acc_count_id]
						 --CONVERT(NVARCHAR(100),'')   [Note1],
						 --CONVERT(NVARCHAR(100),'')   [Note2]
					Into #tbTempItemTransactions
					FROM tbItemTransactions			A		WITH (NOLOCK)
					Left Join	dbo.tbItem			B		WITH (NOLOCK)
						On		A.comp_id		= B.comp_id
							and A.Item_id		= B.Item_Id
					INNER JOIN tbPurchaseConcept tpc		WITH (NOLOCK)
						ON		tpc.comp_id = A.comp_id
							AND tpc.puco_id = A.puco_id

					Where	A.comp_id			= @comp_id
					and		A.it_transaction	= @it_Transaction

					Group By B.acc_count_id4Purchase,
							 tpc.acc_count_id


				-- Si no tiene definida ninguna cuenta, busca la 303 x estandard.-
				Update #tbTempItemTransactions
					Set acc_count_id =	(Select acc_count_id
											From dbo.tbAccountManagementRelations A
											Where   comp_id		= @comp_id
												and bra_id		= @bra_id
												and samr_id		= 303
										)
					Where IsNull(acc_count_id,-1) = -1


--==
/*
SELECT @comp_id,@it_transaction
SELECT * FROM #tbTempItemTransactions
*/


		-- ------------------------------------------------------------------
		-- Intenta generar una reversion a la cuenta corecta del asiento contable
		-- que se hara SOLO si no se modifico la cta contable en la que imputa
		-- el impuesto original.
		-- ------------------------------------------------------------------

		DECLARE @dacc_transactionOriginal	AS INT
		SET		@dacc_transactionOriginal = NULL
		DECLARE @ct_transaction				AS INT
		DECLARE @decTotal					AS DECIMAL(30,6)
		DECLARE @acc_count_id				AS INT
		DECLARE @acc_count_id_original		AS INT
		DECLARE @puco_id_Original			AS INT
		DECLARE @lbra_id					AS INT



		SELECT	@decTotal				= tmp.TotalByAcc,
				@acc_count_id_original	= tmp.acc_count_id
			FROM #tbTempItemTransactions tmp

		SELECT
			@ct_transaction		= tit.ct_transaction,
			@puco_id_Original	= tit.puco_id,
			@lbra_id			= tit.bra_id
			FROM tbItemTransactions								tit WITH(NOLOCK)
			WHERE	tit.comp_id			= @comp_id			AND
					tit.it_transaction	= @it_transaction



		---- Obtengo la cuenta contable original
		--SELECT
		--	@acc_count_id_original	= tpc.acc_count_id
		--	FROM tbPurchaseConcept						tpc		WITH(NOLOCK)
		--	WHERE	tpc.comp_id	= @comp_id			AND
		--			tpc.puco_id	= @puco_id_Original


		-- Obtengo la cuenta contable destino
		SELECT
			@acc_count_id		= tpc2.acc_count_id
			FROM tbPurchaseConcept						tpc2	WITH(NOLOCK)
			WHERE	tpc2.comp_id	= @comp_id		AND
					tpc2.puco_id	= @puco_id



		-- Obtengo la imputacion contable que se hizo
		SELECT @dacc_transactionOriginal = tatd.dacc_transaction
			FROM tbAccountTransactionDetail tatd	WITH(NOLOCK)
			WHERE	tatd.comp_id		= @comp_id					AND
					tatd.ct_transaction = @ct_transaction			AND
					tatd.acc_count_id	= @acc_count_id_original	AND
				   (
	   				tatd.dacc_debit		= @decTotal OR
					tatd.dacc_credit	= @decTotal
				   )												AND
				   @decTotal <> 0
			ORDER BY tatd.dacc_debit, tatd.dacc_credit

		-- Si logro enconrar la cuenta contable, la cambia
		IF	@acc_count_id				IS NOT NULL	AND
			@dacc_transactionOriginal	IS NOT NULL
			BEGIN

				UPDATE tbAccountTransactionDetail
					SET		acc_count_id		= @acc_count_id
					WHERE	comp_id				= @comp_id					AND
							dacc_transaction	= @dacc_transactionOriginal

			END
		-- ------------------------------------------------------------------


	--DROP TABLE #tbTempItemTransactions



	UPDATE tbItemTransactions
		SET		 puco_id			= @puco_id
		WHERE	 comp_id			= @comp_id			AND
				 it_transaction		= @it_transaction



END

GO






