CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateDataLoan_PayDate]
(
	@comp_id						as INT,
	@ctl_payDate_Days				as INT,
	@ctl_payDateUpdateUser			AS INT,
	@ct_transaction					as INT
)

AS




BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
					@comp_id						as INT,
					@ctl_payDate_Days				as INT,
					@ctl_payDateUpdateUser			AS INT,
					@ct_transaction					as INT


		SELECT
					@comp_id				= 1,
					@sreas_id				= 1,
					@sreas_id				= 6165,
					@stor_id				= 10,
					@it_transaction			= 6222



*/


	-- --------------------------------------------------------------


	UPDATE tbCommercialTransactionsLoan WITH (ROWLOCK)
		SET	ctl_payDate				= dateadd(DAY,@ctl_payDate_Days, ctl_payDate),
			ctl_payDateUpdateDate	= GETDATE(),
			ctl_payDateUpdateUser	= @ctl_payDateUpdateUser
			WHERE comp_id			= @comp_id				AND
				  ct_transaction	= @ct_transaction





END

GO





CREATE PROCEDURE [dbo].[spCommercialTransactions_updateDiscounts]
(
	@comp_id					INT,
	@bra_id						INT,
	@ct_transaction				INT,
	@discount1					DECIMAL(19,6),
	@discount2					DECIMAL(19,6),
	@discount3					DECIMAL(19,6),
	@discount4					DECIMAL(19,6),
	@ret_ErrorCode				as int			output,
	@ret_ErrorDescription		as varchar(200) output
)
AS SET NOCOUNT ON

-- ---------------------------------------------------
-- Testing
-- ---------------------------------------------------
/*
	DECLARE
		@comp_id		INT,
		@bra_id			INT,
		@ct_transaction	INT,
		@discount1		DECIMAL(19,6),
		@discount2		DECIMAL(19,6),
		@discount3		DECIMAL(19,6),
		@discount4		DECIMAL(19,6)

	SELECT
		@comp_id		= 1,
		@bra_id			= 1,
		@ct_transaction	= 3237,
		@discount1		= 1,
		@discount2		= 2,
		@discount3		= 3,
		@discount4		= 4
*/
-- ---------------------------------------------------

Set @ret_ErrorCode			= 0
Set @ret_ErrorDescription	= ''


BEGIN TRY

	UPDATE tbCommercialTransactions
	SET
		ct_Discount1 = @discount1,
		ct_Discount2 = @discount2,
		ct_Discount3 = @discount3,
		ct_Discount4 = @discount4

	WHERE	comp_id			= @comp_id
	AND		bra_id			= @bra_id
	AND		ct_transaction	= @ct_transaction

END TRY
BEGIN CATCH
	Set @ret_ErrorCode			= -1
	Set @ret_ErrorDescription	= 'spCommercialTransactions_updateDiscounts-' +
		(SELECT
			convert(varchar,ERROR_NUMBER	())	+ '-' +
			convert(varchar,ERROR_SEVERITY	())	+ '-' +
			convert(varchar,ERROR_STATE		())	+ '-' +
			convert(varchar,ERROR_LINE		())	+ '-' +
							ERROR_MESSAGE	())
END CATCH
GO







