CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateLiquidatedMicroSites]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@guid		UNIQUEIDENTIFIER
			SELECT
				@comp_id	= 1,
				@guid		= '25892e17-80f6-415f-9c65-7395632f0223'
		*/
		-- --------------------------------------------------------------

		DECLARE
			@lintWS_internalID	INT,
			@lIntWS_Counter		INT

		--RECUPERAMOS EL WS_INTERNALID
		SELECT
			TOP 1
			@lintWS_internalID  = tct.ws_internalID
		FROM tbCommercialTransactions tct				WITH(NOLOCK)
			INNER JOIN tbTemporarySelection				tts
				ON	tts.tmpID	= tct.ct_transaction
		WHERE	tct.comp_id		= @comp_id AND
				tts.tmpGUID		= @guid

		--ACTUALIZAMOS EL CONTADOR DE LIQUIDACIÓN
		UPDATE tbWebSiteII_Names
		SET
			ws_microSite_LiquidationNumber = ISNULL(ws_microSite_LiquidationNumber,0) + 1
		WHERE	comp_id			= @comp_id AND
				ws_internalID	= @lintWS_internalID

		--RECUPERAMOS EL VALOR DEL CONTADOR DE LIQUIDACIÓN PARA ACTUALIZAR LA CT_TRANS
		SELECT
			@lIntWS_Counter = twsin.ws_microSite_LiquidationNumber
		FROM tbWebSiteII_Names					twsin
		WHERE	twsin.comp_id		= @comp_id	AND
				twsin.ws_internalID = @lintWS_internalID




		UPDATE tbCommercialTransactions
		SET
			ws_isLiquidated			= 'True',
			ws_isLiquidatedCD		= GETDATE(),
			ws_LiquidationNumber	= @lIntWS_Counter
		FROM tbCommercialTransactions					tct
			INNER JOIN tbTemporarySelection				tts
				ON	tts.tmpID	= tct.ct_transaction	AND
					tts.tmpGUID = @guid
	END
GO

