-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateMercadoLibrePaymentButton]
	@comp_id					INT,
	@strTransactionsDetail		VARCHAR(MAX),
	@PaymentButton				NVARCHAR(500),
	@ccv_id						INT,
	@MPPreference_id			NVARCHAR(100),
	@datExpiresTo				DATETIME,
	@jsonMPBotonDePago			VARCHAR(4000),
	@strResponse				VARCHAR(4000),
	@user_id					INT,
	@MPBotonDePagoIsTotalButton BIT,
	@decTotal					DECIMAL(19,4),
	@decOriginalTotal			DECIMAL(19,4)
AS
BEGIN

	SET NOCOUNT ON;


		DECLARE @strTransaction AS VARCHAR(50)
		DECLARE @ct_transaction AS INT = 0
		DECLARE @ctl_id			AS INT = 0
		DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
			SELECT fst.items
				FROM dbo.fnSplitTable(@strTransactionsDetail,',') fst
		OPEN cursor_data
		FETCH cursor_data INTO @strTransaction
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SELECT @ct_transaction	=  CONVERT(INT,dbo.fnStrSplitString(@strTransaction,'-',0))
			SELECT @ctl_id			=  CONVERT(INT,dbo.fnStrSplitString(@strTransaction,'-',1))

			IF	   @ctl_id  <= 0 SET @ctl_id =NULL

			DECLARE @total AS DECIMAL(19,4) = 0
			SELECT  @total =	CASE
									WHEN tctl.comp_id IS NOT NULL THEN	tctl.ct_ABalance
									ELSE								tct.ct_ABalance
								END
				FROM tbCommercialTransactions				AS tct
				LEFT JOIN tbCommercialTransactionsLoan		AS tctl
					ON	tctl.comp_id			= tct.comp_id			AND
						tctl.ct_transaction		= tct.ct_transaction	AND
						tctl.ctl_id				= @ctl_id
				WHERE	tct.comp_id				= @comp_id AND
						tct.ct_transaction		= @ct_transaction


			IF @ctl_id IS NOT NULL
				BEGIN

					INSERT INTO tbCreditCard_VoucherRelations
					(
						comp_id,
						-- ctr_id -- this column value is auto-generated
						ccv_id,
						ct_transaction,
						ctl_id,
						[user_id],
						ctr_total
					)
					VALUES
					(
						@comp_id,
						@ccv_id,
						@ct_transaction,
						@ctl_id,
						@user_id,
					 	@total
					)

				END
			ELSE
				BEGIN

					INSERT INTO tbCreditCard_VoucherRelations
					(
						comp_id,
						-- ctr_id -- this column value is auto-generated
						ccv_id,
						ct_transaction,
						ctl_id,
						[user_id],
						ctr_total
					)
					VALUES
					(
						@comp_id,
						@ccv_id,
						@ct_transaction,
						NULL,
						@user_id,
					    @total
					)

				END

			FETCH cursor_data INTO @strTransaction
		END
		CLOSE cursor_data
		DEALLOCATE cursor_data




	UPDATE tbCreditCard_Voucher		WITH (ROWLOCK)
	SET ccv_MPPreference				= @MPPreference_id,
		ccv_MPexpiresOn					= @datExpiresTo,
		ccv_MPjsonMPBotonDePago			= @jsonMPBotonDePago,
		ccvMP_strResponse				= @strResponse,
		ccv_MPBotonDePagoIsTotalButton	= @MPBotonDePagoIsTotalButton,
		ccv_MPBotonDePagoLinkButton		= @PaymentButton,
		ccv_GrandTotalOriginal			=	CASE
												WHEN @decOriginalTotal > 0		THEN	@decOriginalTotal
												ELSE									ccv_GrandTotalOriginal
											END ,
		ccv_GrandTotal					=	CASE
												WHEN @decTotal > 0				THEN	@decTotal
												ELSE									ccv_GrandTotal
											END
		WHERE	comp_id  = @comp_id AND
				ccv_id	 = @ccv_id


	SELECT 'True'

END
GO



