-- Create date: Inserta las publicaciones de las que se debe actualizar la disponibilidad o pausarlas.
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateMercadoLibrePublications]
	@comp_id		INT,
	@ct_transaction	INT,
	@guid			UNIQUEIDENTIFIER
AS
BEGIN

	SET NOCOUNT ON;

	-- No hace trabajo al pedo . . .
	IF NOT EXISTS(
					SELECT TOP 1  1
						FROM tbMercadoLibre_ItemsPublicados		WITH (NOLOCK)
						WHERE	comp_id		= @comp_id AND
								mlp_Active	= 'True'
				)
		BEGIN
			SELECT 'False'
			RETURN
		END



	DECLARE @tmpPublications TABLE(	mlp_id		INT,
									[USER_ID]	INT,
									availableStock	DECIMAL(19,4))
	DECLARE @bitExecwfmMercadolibre_processQueue AS BIT
	SET		@bitExecwfmMercadolibre_processQueue = 'False'

	-- --------------------------------------------------------------------------
	-- DesActivar Publicaciones segun stock en tbMercadoLibre_ItemsPublicados
	-- --------------------------------------------------------------------------
	-- 1ro Pongo los ID de publicaciones en una temporal del mismo deposito del
	-- que se emitio la factura
	INSERT INTO @tmpPublications ( mlp_id, [USER_ID], availableStock)
	SELECT	tmlip.mlp_id,
			tct.[user_id],
			CASE
				WHEN tmlip.mlp_allowPublicationsWithNoStock = 'True' THEN	tmlip.mlp_initQty
				ELSE														dbo.fnGetAStock4MaxAssociation(@comp_id, tmls.stor_id4StockAvailability, tmlip.item_id, 999999999)
			END
		FROM tbItemTransactions							tit		WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_ItemsPublicados		tmlip	WITH (NOLOCK)
			ON	tmlip.comp_id		= tit.comp_id		AND
				tmlip.item_id		= tit.item_id
		INNER JOIN tbMercadoLibre_Stores				tmls	WITH (NOLOCK)
			ON	tmls.comp_id		= tmlip.comp_id		AND
				tmls.mls_id			= tmlip.mls_id
		INNER JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
			ON	tct.comp_id			= tit.comp_id		AND
				tct.ct_transaction	= tit.ct_transaction
		WHERE
				tit.comp_id			= @comp_id			AND
				tit.ct_transaction	= @ct_transaction	AND
				tmlip.mlp_Active	= 'True'			AND
				--tit.stor_id			= tmlip.stor_id		AND   MOS 06-2018, ver si se pone un join con una tabla q tenga los depositos de los cuales debe tomer los moviomientos ( grupo de depositos )  HOY NO ESTA ESE SETEO
				tmls.mls_disabled	= 'False'


	-- -----------------------------------------------------------------------------------------------------------
	-- MOS 03-2024: Fas con sus putos cientos de miles de reputos pedidos, y 10000 combos con el mismo articulo
	-- pongo el stock disponible con un distinct de articulos en una temporal para usarlo abajo
	DECLARE @tmpPublicationsSTKTMP TABLE(	item_id INT,	-- MOS 04-2024: Le saque el Primary Key ya que en TP3d daba error porque tenian articulos en diferentes depositos
											stor_id4StockAvailability INT,
											availableStock	DECIMAL(19,4))
	INSERT INTO @tmpPublicationsSTKTMP ( item_id, stor_id4StockAvailability,  availableStock)
	SELECT DISTINCT 	tmlip.item_id ,tmls.stor_id4StockAvailability,0
		FROM tbItemTransactions							tit		WITH (NOLOCK)
		INNER JOIN tbItemAssociation					tia		WITH (NOLOCK)
			ON	tia.comp_id			= tit.comp_id AND
				tia.item_id_1		= tit.item_id
		INNER JOIN tbMercadoLibre_ItemsPublicados		tmlip	WITH (NOLOCK)
			ON	tmlip.comp_id		= tia.comp_id		AND
				tmlip.item_id		= tia.item_id
		LEFT JOIN @tmpPublications						tmpp
			ON tmpp.mlp_id			= tmlip.mlp_id
		INNER JOIN tbMercadoLibre_Stores				tmls	WITH (NOLOCK)
			ON	tmls.comp_id		= tmlip.comp_id		AND
				tmls.mls_id			= tmlip.mls_id
		INNER JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
			ON	tct.comp_id			= tit.comp_id		AND
				tct.ct_transaction	= tit.ct_transaction
		WHERE
				tit.comp_id			= @comp_id			AND
				tit.ct_transaction	= @ct_transaction	AND
				tmpp.mlp_id IS NULL						AND
				tmlip.mlp_Active	= 'True'			AND
				tmls.mls_disabled	= 'False'

		UPDATE @tmpPublicationsSTKTMP SET availableStock = dbo.fnGetAStock(@comp_id, stor_id4StockAvailability, item_id, 999999999)   -- MOS 03-2024: Cambie a getAStock ya que este es el disponible de LAS PARTES

		-- Con el disponible de las PARTES precalculado, sigo.  Se huzo así x q en FAS esto daba unos 600 registros con algunos items.
	-- -----------------------------------------------------------------------------------------------------------



	-- Agregar a esa tabla los padres de items asociados que ya esten actualmente en esa tabla y que pertenezcan a una publicacion.
	-- Ver de hacer lo mismo con la carga de Pedidos.
	INSERT INTO @tmpPublications ( mlp_id, [USER_ID], availableStock)
	SELECT	tmlip.mlp_id,
			tct.[user_id],
			CASE
				WHEN tmlip.mlp_allowPublicationsWithNoStock = 'True' THEN	tmlip.mlp_initQty
				ELSE														ISNULL(tt2.availableStock,0)
				--ELSE														dbo.fnGetAStock4MaxAssociation(@comp_id, tmls.stor_id4StockAvailability, tmlip.item_id, 999999999)
			END
		FROM tbItemTransactions							tit		WITH (NOLOCK)
		INNER JOIN tbItemAssociation					tia		WITH (NOLOCK)
			ON	tia.comp_id			= tit.comp_id AND
				tia.item_id_1		= tit.item_id
		INNER JOIN tbMercadoLibre_ItemsPublicados		tmlip	WITH (NOLOCK)
			ON	tmlip.comp_id		= tia.comp_id		AND
				tmlip.item_id		= tia.item_id
		LEFT JOIN @tmpPublications						tmpp
			ON tmpp.mlp_id			= tmlip.mlp_id
		INNER JOIN tbMercadoLibre_Stores				tmls	WITH (NOLOCK)
			ON	tmls.comp_id		= tmlip.comp_id		AND
				tmls.mls_id			= tmlip.mls_id
		INNER JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
			ON	tct.comp_id			= tit.comp_id		AND
				tct.ct_transaction	= tit.ct_transaction

		LEFT JOIN @tmpPublicationsSTKTMP tt2			-- MOS 03-2024
				ON	tt2.item_id						= tmlip.item_id AND
					tt2.stor_id4StockAvailability	= tmls.stor_id4StockAvailability	-- MOS 04-2024: Para que tome en cuenta dl deposito arriba puesto de SU tienda
		WHERE
				tit.comp_id			= @comp_id			AND
				tit.ct_transaction	= @ct_transaction	AND
				tmpp.mlp_id IS NULL						AND
				tmlip.mlp_Active	= 'True'			AND
				--tit.stor_id			= tmlip.stor_id		AND   MOS 06-2018, ver si se pone un join con una tabla q tenga los depositos de los cuales debe tomer los moviomientos ( grupo de depositos )  HOY NO ESTA ESE SETEO
				tmls.mls_disabled	= 'False'








	-- MOS 08-2018, No mas, al pedo, que fuerce la de Stock
	---- 2do Desactivo las publicaciones que no cumplan con la pauta de stock definida
	--UPDATE tbMercadoLibre_ItemsPublicados							WITH (ROWLOCK)
	--	SET		mlp_Active										= 'False',
	--			tbMercadoLibre_ItemsPublicados.optval_statusId	= 3
	--	FROM	tbMercadoLibre_ItemsPublicados	 tmplip
	--	INNER JOIN @tmpPublications tmp
	--		ON	tmp.mlp_id			= tmplip.mlp_id
	--	WHERE	tmplip.comp_id		= @comp_id	AND
	--			tmp.availableStock	<= tmplip.mlp_minQty4Pause
	--IF @@ROWCOUNT > 0 SET @bitExecwfmMercadolibre_processQueue = 'True'



	-- Fuerzo a una restitucion de stock en el proximo chequeo, no hace falta que se ejecute YA
	UPDATE tbMercadoLibre_ItemsPublicados							WITH (ROWLOCK)
		SET mlp_force2CheckStock = 'True'
		FROM	tbMercadoLibre_ItemsPublicados	 tmplip
		INNER JOIN @tmpPublications tmp
			ON	tmp.mlp_id			= tmplip.mlp_id
		WHERE	tmplip.comp_id		= @comp_id
	IF @@ROWCOUNT > 0 SET @bitExecwfmMercadolibre_processQueue = 'True'


	-- MOS lo saque ya que no le encuentro sentido y rompe las pelotas, ya esta la de stock
	---- 3ro Inserto en tbMercadoLibre_updateQueue las publicaciones a Pausar
	--INSERT INTO tbMercadoLibre_updateQueue						WITH (ROWLOCK)
	--(
	--	comp_id,
	--	-- mlproc_id -- this column value is auto-generated,
	--	mlp_id,
	--	[user_id],
	--	mlproc_option,
	--	mlproc_integerValue,
	--	mlproc_isProcessed,
	--	mlproc_isCancelled,
	--	mlproc_priority,
	--	mlproc_guid
	--)
	--SELECT	DISTINCT
	--		@comp_id,
	--		tmlip.mlp_id,
	--		tmp.[user_id],
	--		7,  -- MLQO_Publication_Status
	--		3,	-- PAUSADA
	--		'False',
	--		'False',
	--		-1,
	--		@guid
	--	FROM @tmpPublications	tmp
	--	INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
	--		ON	tmlip.comp_id		= @comp_id				AND
	--			tmlip.mlp_id		= tmp.mlp_id
	--	WHERE	tmlip.mlp_Active	= 'False'
	--IF @@ROWCOUNT > 0 SET @bitExecwfmMercadolibre_processQueue = 'True'
	---- --------------------------------------------------------------------------


	-- MOS 03-2024: Al Pedo, ver de sacar, arriba ya pone una verificacion de stock y esto solo duplica cosas
	-- --------------------------------------------------------------------------
	-- Poner Stock de Publicaciones ACTIVAS Únicamente
	-- --------------------------------------------------------------------------
	INSERT INTO tbMercadoLibre_updateQueue						WITH (ROWLOCK)
	(
		comp_id,
		-- mlproc_id -- this column value is auto-generated,
		mlp_id,
		[user_id],
		mlproc_option,
		mlproc_integerValue,
		mlproc_isProcessed,
		mlproc_isCancelled,
		mlproc_priority,
		mlproc_guid,
		mlproc_internalID
	)
	SELECT	@comp_id,
			tmlip.mlp_id,
			tmp.[user_id],
			4,	-- MLQO_UpdateAvailableQTY
			CASE	-- Pone el minimo entre la cantidad a publicar y la cantidad disponible en ese deposito.
				WHEN tmp.availableStock < tmlip.mlp_initQty THEN tmp.availableStock
				ELSE tmlip.mlp_initQty
			END,
			'False',
			'False',
			-1,
			@guid,
			8101	-- MOS 03-2024
		FROM @tmpPublications	tmp
		INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
			ON	tmlip.comp_id		= @comp_id				AND
				tmlip.mlp_id		= tmp.mlp_id
		-- MOS 03-2024: Para que NO inserte AL PEDO 1000 veces esta mierda
		LEFT JOIN tbMercadoLibre_updateQueue AS tmluq	WITH (NOLOCK)
			ON	tmluq.comp_id				= @comp_id AND
				tmluq.mlp_id				= tmp.mlp_id	 AND
				tmluq.mlproc_option			= 4	AND
				tmluq.mlproc_isProcessed	= 0 AND
				tmluq.mlproc_isCancelled	= 0
		WHERE	tmlip.mlp_Active	= 'True'	AND
				tmluq.comp_id IS NULL	-- MOS 03-2024: para que NO inserte al pedo si ya esta ahora sin procesar.
	IF @@ROWCOUNT > 0 SET @bitExecwfmMercadolibre_processQueue = 'True'
	-- --------------------------------------------------------------------------



	-- MOS lo saque ya que no le encuentro sentido y rompe las pelotas, ya esta la de stock 08-2018
	---- --------------------------------------------------------------------------
	---- ACTIVA por las dudas las publicaciones que deban estar activas
	---- --------------------------------------------------------------------------
	--INSERT INTO tbMercadoLibre_updateQueue						WITH (ROWLOCK)
	--(
	--	comp_id,
	--	-- mlproc_id -- this column value is auto-generated,
	--	mlp_id,
	--	[user_id],
	--	mlproc_option,
	--	mlproc_integerValue,
	--	mlproc_isProcessed,
	--	mlproc_isCancelled,
	--	mlproc_priority,
	--	mlproc_guid
	--)
	--SELECT	@comp_id,
	--		tmlip.mlp_id,
	--		tmp.[user_id],
	--		7,  -- MLQO_Publication_Status
	--		2,	-- ACTIVA
	--		'False',
	--		'False',
	--		-1,
	--		@guid
	--	FROM @tmpPublications	tmp
	--	INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
	--		ON	tmlip.comp_id		= @comp_id				AND
	--			tmlip.mlp_id		= tmp.mlp_id
	--	WHERE	tmlip.mlp_Active	= 'True'
	--IF @@ROWCOUNT > 0 SET @bitExecwfmMercadolibre_processQueue = 'True'
	---- --------------------------------------------------------------------------


	SELECT @bitExecwfmMercadolibre_processQueue	-- Informa True para que ejecute la pagina: wfmMercadolibre_processQueue

END
GO


--BORRAR EL spCommercialTransactions_updateProject4Payments QUE ES EL VIEJO
-- =============================================
-- Author:		SL
-- Create date: 16-02-2016
-- =============================================

CREATE PROCEDURE [dbo].[spCommercialTransactions_updateProject]
(
	@comp_id		AS INT,
	@bra_id			AS INT,
	@ct_transaction	AS INT,
	@pro_id			AS INT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF @pro_id <> -1
		BEGIN
			UPDATE tbCommercialTransactions
				SET		pro_id			= @pro_id
				WHERE	comp_id			= @comp_id			AND
						bra_id			= @bra_id			AND
						ct_transaction	= @ct_transaction
		END
END

GO





