CREATE PROCEDURE [dbo].[spCommercialTransactions_UpdateSuppId4CCLiquidation]
(
	@comp_id				INT,
	@ct_transaction			INT,
	@supp_id				INT,
	@return_value			INT				OUTPUT,
	@ret_ErrorCode			INT				OUTPUT,
	@ret_ErrorDescription	VARCHAR(200)	OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------
		-- TESTING
		-- -----------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@ct_transaction			INT,
				@supp_id				INT,
				@return_value			INT,
				@ret_ErrorCode			INT,
				@ret_ErrorDescription	VARCHAR(200)

			SELECT
				@comp_id		= 1,
				@ct_transaction	= 1035,
				@supp_id		= -1
		*/
		-- -----------------------------------------------

		SET @return_value			= 0
		SET @ret_ErrorCode			= 0
		SET @ret_ErrorDescription	= ''


		IF @supp_id <= 0
			BEGIN
				SET @supp_id = NULL
			END


		UPDATE tbCommercialTransactions		WITH (ROWLOCK)
		SET
			supp_id4CreditCardLiquidation	= @supp_id
			WHERE	comp_id					= @comp_id	AND
					ct_transaction			= @ct_transaction

	END
GO





-- =============================================
-- Author:		MOS
-- Create date: 05-2013
-- =============================================
-- SOLO PARA IMPRESORAS FISCALES:!!!!!!!!!!!!!!!
CREATE PROCEDURE [dbo].[spCommercialTransactions_updateUpdateFiscalPrinterLastData]
	@comp_id			AS INT,
	@bra_id				AS INT,
	@ct_transaction		AS INT,
	@strDocumentNumber	AS NVARCHAR(MAX),
	@strCAI				AS NVARCHAR(MAX)
AS

BEGIN

	SET NOCOUNT ON;

	UPDATE tbcommercialtransactions WITH (ROWLOCK)
		SET	  ct_docNumber	= @strDocumentNumber,
			  ct_CAI		= @strCAI
		WHERE	comp_id			= @comp_id	AND
				ct_transaction	= @ct_transaction













	-- ---------------------------------------------------------------------------------
	-- Rellenado de numeros de comprobante SALTEADOS por la impresora fiscal.-
	-- MOS
	-- Busca el Numero Anterior ya que puede pasar que impriman una factura
	-- y la puta impresora fiscal y el enfermo mental que la diseño
	-- impriman en varias hojas salteando el numero de las hojas intermedias.
	-- No entiendo como pueden dar a IDIOTAS la responsabilidad de decidir
	-- cosas que no son capaces de ni siquiera pensar !!!!!!!
	-- ---------------------------------------------------------------------------------

	DECLARE @intFromFiscalNumber			AS INT
	DECLARE @intCTTransactionPreOriginal	AS INT
	DECLARE @strPreDocumentNumber			AS NVARCHAR(50)
	DECLARE @bitCheck4EmptyNumbers			AS BIT
	DECLARE @intSD_Id						AS INT
	DECLARE @intDF_Id						AS INT
	DECLARE @strKindOf						AS NVARCHAR(50)
	DECLARE @intPointOfSale					AS INT

	SET @bitCheck4EmptyNumbers = 'False'

	SELECT  @intDF_Id				= tct.df_id,
			@intSD_Id				= tct.sd_id,
			@bitCheck4EmptyNumbers	= tdf.df_Fiscal_Check4EmptyNumbers,
			@strKindOf				= tct.ct_kindOf,
			@intPointOfSale			= tct.ct_pointOfSale
		FROM tbCommercialTransactions	tct					WITH (NOLOCK)
		INNER JOIN tbDocumentsFile		tdf					WITH (NOLOCK)
			ON	tdf.comp_id = tct.comp_id		AND
				tdf.df_id	= tct.df_id
		WHERE	tct.comp_id			= @comp_id	AND
				tct.ct_transaction	= @ct_transaction


	IF @bitCheck4EmptyNumbers = 'True'
		BEGIN

			SET	@intCTTransactionPreOriginal	= NULL
			SET	@strPreDocumentNumber			= NULL

			-- Busca el Numero Anterior que se grabo
			SELECT	TOP 1
					@intCTTransactionPreOriginal	= tct.ct_transaction,
					@strPreDocumentNumber			= tct.ct_docNumber
				FROM tbCommercialTransactions	tct		WITH (NOLOCK)
				INNER JOIN tbDocumentsFile		tdf		WITH (NOLOCK)
					ON	tdf.comp_id = tct.comp_id		AND
						tdf.df_id	= tct.df_id
				WHERE
					tct.comp_id			= @comp_id			AND
					tct.ct_transaction	< @ct_transaction	AND
					tct.sd_id			= @intSD_Id			AND
					tct.ct_kindOf		= @strKindOf		AND
					tct.ct_pointOfSale	= @intPointOfSale	AND
					(
						tct.df_id			= @intDF_Id		OR
						tdf.df_id_getNumber = @intDF_Id
					)
			ORDER BY tct.ct_transaction	DESC


			-- Si encontro uno previo
			IF @intCTTransactionPreOriginal IS NOT NULL
				BEGIN
					IF ISNUMERIC(@strPreDocumentNumber) = 1 AND ISNUMERIC(@strDocumentNumber) = 1
						BEGIN
							DECLARE @intPreDocumentNumber			AS INT
							DECLARE @intDocumentNumber				AS INT
							SET @intPreDocumentNumber	= CONVERT(INT,@strPreDocumentNumber)
							SET @intDocumentNumber		= CONVERT(INT,@strDocumentNumber)

							-- Si hay menos de 100 numeros de diferencia
							IF (@intDocumentNumber - @intPreDocumentNumber) < 100
								BEGIN

									DECLARE @intCounter AS INT
									SET		@intCounter = 0
									DECLARE @intBeginNumber AS INT
									SET @intBeginNumber = @intPreDocumentNumber + 1
									WHILE @intBeginNumber < @intDocumentNumber
										BEGIN
											INSERT INTO tbCommercialTransactions WITH (ROWLOCK)
											(
												comp_id,
												bra_id,
												ct_pointOfSale,
												ct_kindOf,
												ct_docNumber,
												ct_date,
												ct_taxDate,
												ct_payDate,
												supp_id,
												cust_id,
												ba_id,
												cb_id,
												[user_id],
												ct_cd,
												ct_subtotal,
												ct_total,
												ct_discount,
												ct_adjust,
												ct_taxes,
												curr_id_transaction,
												hacc_transaction,
												sm_id,
												disc_id,
												ct_ATotal,
												ct_ABalance,
												ct_ACurrency,
												ct_ACurrencyExchange,
												df_id,
												dl_id,
												st_id,
												sd_id,
												puco_id,
												ct_CompanyCurrency,
												ct_Branch2CompanyCurrencyExchange,
												ct_Pending,
												country_id,
												state_id,
												ct_isAvailableForImport,
												ct_soh_bra_id,
												ct_soh_id,
												ct_CAI,
												ct_CAIDate,
												ct_CAIBarCodeImage,
												ct_isAvailableForPayment,
												ct_transaction_PackingList,
												ct_processingDate,
												ct_AAdjust,
												ct_dfExchange,
												curr_id4Exchange,
												ct_curr_IdExchange,
												curr_id4dfExchange,
												ct_AllUseTag1,
												ct_AllUseTag2,
												ct_AllUseTag3,
												ct_AllUseTag4,
												ct_FEIdNumber,
												ct_packagesQty,
												ct_isCancelled,
												sctt_id,
												ct_isSelected,
												ct_Discount1,
												ct_Discount2,
												ct_Discount3,
												ct_Discount4,
												ct_TransactionBarCode,
												suppa_id,
												pt_id,
												ct_optionalValue,
												ct_dfExchangeOriginal,
												ct_curr_IdExchangeOriginal,
												ct_Fiscal_Check4EmptyNumbers
											)

											SELECT
												comp_id,
												bra_id,
												ct_pointOfSale,
												ct_kindOf,
													convert(nvarchar(50),@intBeginNumber),
												ct_date,
												ct_taxDate,
												ct_payDate,
												supp_id,
												cust_id,
												ba_id,
												cb_id,
												[user_id],
												ct_cd,
												0,
												0,
												0,
												0,
												0,
												curr_id_transaction,
												hacc_transaction,
												sm_id,
												disc_id,
												0,
												0,
												ct_ACurrency,
												ct_ACurrencyExchange,
												df_id,
												dl_id,
												st_id,
												sd_id,
												puco_id,
												ct_CompanyCurrency,
												ct_Branch2CompanyCurrencyExchange,
												ct_Pending,
												country_id,
												state_id,
												ct_isAvailableForImport,
												ct_soh_bra_id,
												ct_soh_id,
												ct_CAI,
												ct_CAIDate,
												ct_CAIBarCodeImage,
												ct_isAvailableForPayment,
												ct_transaction_PackingList,
												ct_processingDate,
												0,
												ct_dfExchange,
												curr_id4Exchange,
												ct_curr_IdExchange,
												curr_id4dfExchange,
												ct_AllUseTag1,
												ct_AllUseTag2,
												ct_AllUseTag3,
												ct_AllUseTag4,
												ct_FEIdNumber,
												ct_packagesQty,
												ct_isCancelled,
												sctt_id,
												ct_isSelected,
												ct_Discount1,
												ct_Discount2,
												ct_Discount3,
												ct_Discount4,
												ct_TransactionBarCode,
												suppa_id,
												pt_id,
												ct_optionalValue,
												ct_dfExchangeOriginal,
												ct_curr_IdExchangeOriginal,
													'True'
											FROM tbCommercialTransactions tct				WITH (NOLOCK)
											WHERE	tct.comp_id			= @comp_id	AND
													tct.ct_transaction	= @ct_transaction

											SET @intBeginNumber = @intBeginNumber + 1
										END
								END
						END
				END


		END
		-- ---------------------------------------------------------------------------------

END

GO



CREATE PROCEDURE spCommercialTransactions4ThirdSales_GetDataByFilters
(
	@comp_id	INT,
	@lang_id	INT,
	@datefrom	DATETIME,
	@dateto		DATETIME
)
AS
	SET NOCOUNT ON

		BEGIN

			SELECT
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctts.ct_transaction)	[Document],
				tu.user_lastname + ',' + tu.user_firstname											[user_name],
				tctts.ct3_payDate,
				tctts.ct3_note,
				tctts.ct3_numberOfLiquidation,
				tctts.ct3_isLiquidated,
				tctts.ct_transaction																[ID]


			FROM tbCommercialTransactions4ThirdSales				tctts

				INNER JOIN tbUser									tu
					ON	tu.[user_id]			= tctts.[user_id]

			WHERE	tctts.comp_id				= @comp_id			AND
					tctts.ct3_payDate			BETWEEN @datefrom AND @dateto

		END



GO










