CREATE PROCEDURE spCommercialTransactionsDelivery_GetData4DeliverySheetConfirmation
(
	@comp_id		INT,
	@lang_id		INT,
	@ct_transaction	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------
		-- TESTING
		-- ------------------------------------------
		/*
		DECLARE
			@comp_id		INT,
			@lang_id		INT,
			@ct_transaction	INT

		SELECT
			@comp_id		= 1,
			@lang_id		= 2,
			@ct_transaction	= 3011
		*/
		-- ------------------------------------------

		SELECT
			tc.cust_name																			[CustName],
			dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[Document],
			tctd.ctd_isDelivered																	[IsDelivered],
			tctd.ctd_isDeliveryConfirmed,
			tctd.ctd_isDeliveryConfirmed_CD,
			tctd.ctd_isDeliveryRejected,
			tctd.ctd_isDeliveryRejected_CD,
			ISNULL(tctd.ctd_image,'')																[ctd_image],
			ISNULL(tctd.ctd_note1,'')																[ctd_note1],
			ISNULL(tctd.ctd_note2,'')																[ctd_note2],
			ISNULL(tctd.ctd_note3,'')																[ctd_note3],
			ISNULL(tctd.ctd_note4,'')																[ctd_note4]
			FROM tbCommercialTransactions					AS tct	WITH(NOLOCK)
				INNER JOIN tbCommercialTransactionsDelivery AS tctd	WITH(NOLOCK)
					ON	tctd.comp_id		= tct.comp_id	AND
						tctd.bra_id			= tct.bra_id	AND
						tctd.ct_transaction = tct.ct_transaction
				INNER JOIN tbCustomer						AS tc	WITH(NOLOCK)
					ON	tc.comp_id			= tct.comp_id	AND
						tc.cust_id			= tct.cust_id
			WHERE	tct.comp_id				= @comp_id		AND
					tct.ct_transaction		= @ct_transaction




	END
GO







CREATE PROCEDURE [dbo].[spCommercialTransactionsDelivery_getDataByFilters]
(
	@comp_id								INT,
	@lang_id								INT,
	@bra_id									INT,
	@opt						            INT,
	@ctd_isDelivered_CD_from                datetime,
	@ctd_isDelivered_CD_to                  datetime,
	@ctd_isDeliveryConfirmed_CD_from        datetime,
	@ctd_isDeliveryConfirmed_CD_to          datetime,
	@ctd_isDeliveryRejected_CD_from         datetime,
	@ctd_isDeliveryRejected_CD_to           datetime,
	@option                                 int,
	@document                               varchar(200),
	@ctd_Delivered_Nulls					bit,
	@ctd_DeliveryConfirmed_Nulls			bit,
	@ctd_DeliveryRejected_Nulls				BIT,
	@cust_id								INT,
	@item_id								INT,
	@dl_id									INT,
	@EmitionDateFrom						DATETIME,
	@EmitionDateTo							DATETIME
)
as

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	set nocount ON
	set dateformat 'ymd'


	---------------------------------------------------------------------------------------------------------
	-----------------------------parametros de prueba--------------------------------------------------------
	---------------------------------------------------------------------------------------------------------
	/*
	declare			@comp_id								INT,
					@lang_id								INT,
					@bra_id									INT,
					@opt						            INT,
					@ctd_isDelivered                        bit,
					@ctd_isDeliveryConfirmed                bit,
					@ctd_isDeliveryRejected                 bit,
					@ctd_isDelivered_CD_from                datetime,
					@ctd_isDelivered_CD_to                  datetime,
					@ctd_isDeliveryConfirmed_CD_from        datetime,
					@ctd_isDeliveryConfirmed_CD_to          datetime,
					@ctd_isDeliveryRejected_CD_from         datetime,
					@ctd_isDeliveryRejected_CD_to           datetime,
					@ctd_Delivered_Nulls					bit,
					@ctd_DeliveryConfirmed_Nulls			bit,
					@ctd_DeliveryRejected_Nulls				bit,
					@option                                 int,
					@document                               varchar(200),
					@cust_id								INT,
					@item_id								INT,
					@dl_id									INT,
					@EmitionDateFrom						DATETIME,
					@EmitionDateTo							DATETIME

	select			@comp_id							= 1,
					@lang_id							= 2,
					@bra_id								= 1,
					@opt					            = -1,
					@ctd_isDelivered					= 'false',
					@ctd_isDeliveryConfirmed			= 'false',
					@ctd_isDeliveryRejected				= 'false',
					@ctd_isDelivered_CD_from			= convert(datetime,'1900-01-01'),
					@ctd_isDelivered_CD_to				= convert(datetime,'9999-01-01'),
					@ctd_isDeliveryConfirmed_CD_from	= convert(datetime,'1900-01-01'),
					@ctd_isDeliveryConfirmed_CD_to      = convert(datetime,'9999-01-01'),
					@ctd_isDeliveryRejected_CD_from		= convert(datetime,'1900-01-01'),
					@ctd_isDeliveryRejected_CD_to       = convert(datetime,'9999-01-01'),
					@ctd_Delivered_Nulls				='True',
					@ctd_DeliveryConfirmed_Nulls		='True',
					@ctd_DeliveryRejected_Nulls			='True',
					@option								= -1,
					@document							= '',
					@cust_id							= -1,
					@item_id							= -1,
					@dl_id								= -1,
					@EmitionDateFrom					= convert(datetime,'1900-01-01'),
					@EmitionDateTo						= convert(datetime,'9999-01-01')

	*/
	---------------------------------------------------------------------------------------------------------
	-----------------------------parametros de prueba--------------------------------------------------------
	---------------------------------------------------------------------------------------------------------


	IF @item_id = -1
		BEGIN
			SELECT  ' ' [ ], ' ' [ ],
					tctd.comp_id,
					tctd.bra_id,
					tct.ct_cd,
					dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction])	[document] ,
					ISNULL(tc.cust_name,'')																	[cust_name],
					ISNULL(tc.cust_email,'')																[cust_email],
					tctd.ctd_isDelivered,
					tctd.ctd_isDelivered_CD,
					tctd.ctd_note1,
					tctd.ctd_isDeliveryConfirmed,
					tctd.ctd_isDeliveryConfirmed_CD,
					tctd.ctd_note2,
					tctd.ctd_isDeliveryRejected,
					tctd.ctd_isDeliveryRejected_CD,
					tctd.ctd_note3,
					tctd.ctd_note4,
					td.dl_name,
					isnull(tct.ct_packagesQty,0)	[ct_packagesQty],
					tctd.ct_transaction				[ID]

			FROM	tbCommercialTransactionsDelivery									tctd

					INNER JOIN tbCommercialTransactions									tct
					ON tct.comp_id							= tctd.comp_id
					AND tct.bra_id							= tctd.bra_id
					AND tct.ct_transaction					= tctd.ct_transaction

					INNER JOIN tbCustomer tc
						ON		tc.comp_id = tct.comp_id
							AND tc.cust_id = tct.cust_id

					INNER JOIN tbDelivery td
						ON		td.comp_id = tct.comp_id
							AND td.dl_id = tct.dl_id


			WHERE	tctd.comp_id		= @comp_id
			AND		tctd.bra_id			= @bra_id
			AND		(tct.cust_id		= @cust_id	OR	@cust_id	= -1)



			--AND    tctd.ct_transaction in ( select	tit.ct_transaction
			--								from	tbItemTransactions tit
			--								where	tit.comp_id			= tctd.comp_id
			--								and		tit.bra_id			= tctd.bra_id
			--								and		tit.ct_transaction	= tctd.ct_transaction
			--								and		(@item_id = -1 or tit.item_id = @item_id) )

			AND		(
						@opt = -1 OR
						(@opt = 1 AND		tctd.ctd_isDelivered			= 'true') or
						(@opt = 2 AND		tctd.ctd_isDeliveryConfirmed	= 'true') OR
						(@opt = 3 AND		tctd.ctd_isDeliveryRejected		= 'true') OR
						(@opt = 4 AND		tctd.ctd_isDelivered			= 'false' AND
											tctd.ctd_isDeliveryConfirmed	= 'false' AND
											tctd.ctd_isDeliveryRejected		= 'false')
					)

			AND		((@option    = -1 ) OR
					(@option    = 2 and dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction]) = @document) or
					(@option    = 0 and dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction]) like @document + '%') or
					(@option    = 1 and dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction]) like '%' + @document + '%') or
					(@option    = 3 and dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction]) <> @document) or
					(@option    = 4 and dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction]) not like '%' + @document + '%'))


			AND		(tctd.ctd_isDelivered_CD		 BETWEEN @ctd_isDelivered_CD_from		AND @ctd_isDelivered_CD_to OR
					(@ctd_Delivered_Nulls			='True' AND tctd.ctd_isDelivered_CD			IS null))

			AND		(tctd.ctd_isDeliveryConfirmed_CD BETWEEN @ctd_isDeliveryConfirmed_CD_from	AND @ctd_isDeliveryConfirmed_CD_to OR
					(@ctd_DeliveryConfirmed_Nulls	='True' AND tctd.ctd_isDeliveryConfirmed_CD IS null))

			AND		(tctd.ctd_isDeliveryRejected_CD	 BETWEEN @ctd_isDeliveryRejected_CD_from		AND @ctd_isDeliveryRejected_CD_to OR
					(@ctd_DeliveryRejected_Nulls	='True' AND tctd.ctd_isDeliveryRejected_CD	IS null))
			AND		(tct.dl_id		=	@dl_id	OR	@dl_id	= -1)

			AND		tct.ct_date	BETWEEN @EmitionDateFrom AND @EmitionDateTo


			ORDER BY  tctd.ct_transaction DESC
		END
	ELSE
		BEGIN
			SELECT  ' ' [ ], ' ' [ ],
					tctd.comp_id,
					tctd.bra_id,
					tct.ct_cd,
					dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction])	[document] ,
					tc.cust_name																			[cust_name],
					tctd.ctd_isDelivered,
					tctd.ctd_isDelivered_CD,
					tctd.ctd_note1,
					tctd.ctd_isDeliveryConfirmed,
					tctd.ctd_isDeliveryConfirmed_CD,
					tctd.ctd_note2,
					tctd.ctd_isDeliveryRejected,
					tctd.ctd_isDeliveryRejected_CD,
					tctd.ctd_note3,
					tctd.ctd_note4,
					td.dl_name,
					isnull(tct.ct_packagesQty,0)	[ct_packagesQty],
					tctd.ct_transaction				[ID]

			FROM	tbCommercialTransactionsDelivery									tctd

					INNER JOIN tbCommercialTransactions									tct
					ON tct.comp_id							= tctd.comp_id
					AND tct.bra_id							= tctd.bra_id
					AND tct.ct_transaction					= tctd.ct_transaction

					INNER JOIN tbCustomer tc
						ON		tc.comp_id = tct.comp_id
							AND tc.cust_id = tct.cust_id

					INNER JOIN tbDelivery td
						ON		td.comp_id	= tct.comp_id
							AND td.dl_id	= tct.dl_id


			WHERE	tctd.comp_id		= @comp_id
			AND		tctd.bra_id			= @bra_id
			AND		(tct.cust_id		= @cust_id	OR	@cust_id	= -1)


			AND EXISTS(
										select	1
											from	tbItemTransactions tit
											where	tit.comp_id			= tctd.comp_id
											and		tit.bra_id			= tctd.bra_id
											and		tit.ct_transaction	= tctd.ct_transaction
											and		tit.item_id			= @item_id
						)
			--AND    tctd.ct_transaction in ( select	tit.ct_transaction
			--								from	tbItemTransactions tit
			--								where	tit.comp_id			= tctd.comp_id
			--								and		tit.bra_id			= tctd.bra_id
			--								and		tit.ct_transaction	= tctd.ct_transaction
			--								and		(@item_id = -1 or tit.item_id = @item_id) )

			AND		(
						@opt  = -1 OR
						(@opt = 1 AND		tctd.ctd_isDelivered			= 'true') or
						(@opt = 2 AND		tctd.ctd_isDeliveryConfirmed	= 'true') OR
						(@opt = 3 AND		tctd.ctd_isDeliveryRejected		= 'true') OR
						(@opt = 4 AND		tctd.ctd_isDelivered			= 'false' AND
											tctd.ctd_isDeliveryConfirmed	= 'false' AND
											tctd.ctd_isDeliveryRejected		= 'false')
					)

			AND		((@option   = -1 ) OR
					(@option    = 2 and dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction]) = @document) or
					(@option    = 0 and dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction]) like @document + '%') or
					(@option    = 1 and dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction]) like '%' + @document + '%') or
					(@option    = 3 and dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction]) <> @document) or
					(@option    = 4 and dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.[ct_transaction]) not like '%' + @document + '%'))


			AND		(tctd.ctd_isDelivered_CD		 BETWEEN @ctd_isDelivered_CD_from		AND @ctd_isDelivered_CD_to OR
					(@ctd_Delivered_Nulls			='True' AND tctd.ctd_isDelivered_CD			IS null))

			AND		(tctd.ctd_isDeliveryConfirmed_CD BETWEEN @ctd_isDeliveryConfirmed_CD_from	AND @ctd_isDeliveryConfirmed_CD_to OR
					(@ctd_DeliveryConfirmed_Nulls	='True' AND tctd.ctd_isDeliveryConfirmed_CD IS null))

			AND		(tctd.ctd_isDeliveryRejected_CD	 BETWEEN @ctd_isDeliveryRejected_CD_from		AND @ctd_isDeliveryRejected_CD_to OR
					(@ctd_DeliveryRejected_Nulls	='True' AND tctd.ctd_isDeliveryRejected_CD	IS null))
			AND		(tct.dl_id		=	@dl_id	OR	@dl_id	= -1)

			AND		tct.ct_date	BETWEEN @EmitionDateFrom AND @EmitionDateTo


			ORDER BY  tctd.ct_transaction DESC
		END



END
GO






CREATE PROCEDURE [dbo].[spCommercialTransactionsDelivery_getDataById]
(
	@comp_id			INT,
	@lang_id			INT,
	@ct_transaction		INT
)
as
set nocount on

/*
declare		@rmadt_id		INT

select		@rmadt_id		= 81
*/

SELECT  ' ' [ ], ' ' [ ],
		tctd.comp_id,
		tctd.bra_id,
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctd.ct_transaction) [document] ,
		tctd.ctd_isDelivered,
		tctd.ctd_note1,
		tctd.ctd_isDelivered_CD,
		tctd.ctd_isDeliveryConfirmed,
		tctd.ctd_note2,
		tctd.ctd_isDeliveryConfirmed_CD,
		tctd.ctd_isDeliveryRejected,
		tctd.ctd_note3,
		tctd.ctd_isDeliveryRejected_CD,
		tctd.ctd_note4,
		tctd.ctd_image [ctd_image],
		tctd2.mloim_pdf,
		tc.cust_id,
		tc.cust_name,
		ISNULL(tctd.ctd_imageIsJPG,'False')													[ctd_imageIsJPG],
		tctd.ct_transaction																	[ID]

FROM tbCommercialTransactionsDelivery						tctd		WITH (NOLOCK)

LEFT JOIN tbCommercialTransactions_Digitalizations			tctd2		WITH (NOLOCK)
ON	tctd2.comp_id			= tctd.comp_id			AND
	tctd2.ct_transaction	= tctd.ct_transaction

INNER JOIN tbCommercialTransactions							tct			WITH (NOLOCK)
ON	tct.comp_id				= tctd.comp_id			AND
	tct.bra_id				= tctd.bra_id			AND
	tct.ct_transaction		= tctd.ct_transaction

LEFT JOIN tbCustomer										tc			WITH (NOLOCK)
ON	tc.comp_id				= tct.comp_id			AND
	tc.cust_id				= tct.cust_id

where	tctd.comp_id		= @comp_id		AND
		tctd.ct_transaction = @ct_transaction

order by tctd.ct_transaction






















GO








CREATE PROCEDURE [dbo].[spCommercialTransactionsDelivery_insertData]
(
	@comp_id						INT,
	@bra_id							INT,
	@ct_transaction					INT,
	@ctd_note1						VARCHAR(100),
	@ctd_note2						VARCHAR(100),
	@ctd_note3						VARCHAR(100),
	@ctd_note4						VARCHAR(100),
	@ctd_isDelivered				BIT,
	@ctd_isDeliveryConfirmed		BIT,
	@ctd_isDeliveryRejected			BIT,
	@ctd_isDelivered_CD				DATETIME,
	@ctd_isDeliveryConfirmed_CD		DATETIME,
	@ctd_isDeliveryRejected_CD		DATETIME,
	@dl_id							INT,
	@return_value					INT 			OUTPUT,
	@ret_ErrorCode					INT 			OUTPUT,
	@ret_ErrorDescription			VARCHAR(200)	OUTPUT
)
AS

BEGIN



	SET NOCOUNT ON



	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''


	BEGIN TRY

	/*si el dl_id es -1 se inserta normalmente sino se hace el control que necesita saleorder
	* esto es que se verifique que el transporte tenga la marca que requiere control de entregas*/

	IF @dl_id = -1 OR EXISTS (SELECT TOP 1 	1
							   FROM		tbDelivery td		WITH (NOLOCK)
							   WHERE	td.comp_id				= @comp_id
							   AND		td.dl_id				= @dl_id
							   AND		td.dl_deliveryControl	= 'True')
		BEGIN

				INSERT INTO tbCommercialTransactionsDelivery		WITH (ROWLOCK)
				(
					comp_id,
					bra_id,
					ct_transaction,
					ctd_note1,
					ctd_note2,
					ctd_note3,
					ctd_note4,
					ctd_isDelivered,
					ctd_isDeliveryConfirmed,
					ctd_isDeliveryRejected,
					ctd_isDelivered_CD,
					ctd_isDeliveryConfirmed_CD,
					ctd_isDeliveryRejected_CD
				)
				VALUES
				(
					@comp_id,
					@bra_id,
					@ct_transaction,
					@ctd_note1,
					@ctd_note2,
					@ctd_note3,
					@ctd_note4,
					@ctd_isDelivered,
					@ctd_isDeliveryConfirmed,
					@ctd_isDeliveryRejected,
					@ctd_isDelivered_CD,
					@ctd_isDeliveryConfirmed_CD,
					@ctd_isDeliveryRejected_CD
				)

		END


	END
	TRY BEGIN CATCH

		SET @ret_ErrorCode = -1

	END CATCH


END
GO








CREATE PROCEDURE [dbo].[spCommercialTransactionsDelivery_updateData]
(
		@comp_id						INT,
		@bra_id							INT,
		@ct_transaction					INT,
		@document						VARCHAR(200),
		@ctd_note1						VARCHAR(100),
		@ctd_note2						VARCHAR(100),
		@ctd_note3						VARCHAR(100),
		@ctd_note4						VARCHAR(100),
		@ctd_isDelivered				BIT,
		@ctd_isDeliveryConfirmed		BIT,
		@ctd_isDeliveryRejected			BIT,
		@ctd_isDelivered_CD				DATETIME,
		@ctd_isDeliveryConfirmed_CD		DATETIME,
		@ctd_isDeliveryRejected_CD		DATETIME,
		@user_id						INT

)
AS


BEGIN

	set nocount on

	DECLARE @bitIsDelivered		AS BIT
	DECLARE @datIsDelivered_CD	AS DATETIME
	SELECT @bitIsDelivered			= 'False'
	SET		@datIsDelivered_CD		= @ctd_isDelivered_CD
	SELECT @bitIsDelivered			= IsNull(tctd.ctd_isDelivered,'False'),
		   @datIsDelivered_CD		= tctd.ctd_isDelivered_CD
		FROM tbCommercialTransactionsDelivery tctd	WITH (NOLOCK)
		WHERE	tctd.comp_id		= @comp_id AND
				tctd.ct_transaction = @ct_transaction



	update	tbCommercialTransactionsDelivery	WITH (ROWLOCK)

		set		ctd_note1					= @ctd_note1,
				ctd_note2					= @ctd_note2,
				ctd_note3					= @ctd_note3,
				ctd_note4					= @ctd_note4,
				ctd_isDelivered				= @ctd_isDelivered,
				ctd_isDeliveryConfirmed		= @ctd_isDeliveryConfirmed,
				ctd_isDeliveryRejected		= @ctd_isDeliveryRejected,
				ctd_isDelivered_CD			= @ctd_isDelivered_CD,
				ctd_isDeliveryConfirmed_CD	= @ctd_isDeliveryConfirmed_CD,
				ctd_isDeliveryRejected_CD	= @ctd_isDeliveryRejected_CD,
				user_id4LastUpdate			= @user_id,
				ctd_lastUpdate				= GETDATE()

		WHERE	comp_id			= @comp_id
		AND		ct_transaction	= @ct_transaction


	-- ----------------------------------------------------------------------------------------------------------
	-- Si se puso como ENTREGADO o estaba entregado y se cambio la fecha de entrega, recalcula la fecha de PAGO.!
	-- ----------------------------------------------------------------------------------------------------------
	IF (@bitIsDelivered <> @ctd_isDelivered AND @ctd_isDelivered = 'True') OR
	   (@ctd_isDelivered = 'True' AND @datIsDelivered_CD <> @ctd_isDelivered_CD )
		BEGIN
			DECLARE @bitUpdatePayDateWhenDelyveryDateUpdated	AS BIT
			DECLARE @datPayDate									AS DATETIME
			SET		@datPayDate = @ctd_isDelivered_CD
			DECLARE @intDays2Pay								AS INT
			SET		@intDays2Pay = 0
			SELECT	@intDays2Pay = IsNull(tst.st_days2Pay,0),
					@bitUpdatePayDateWhenDelyveryDateUpdated = IsNull(tdf.df_UpdatePayDateWhenDelyveryDateUpdated,'False')
				FROM tbCommercialTransactions tct				WITH (NOLOCK)
				INNER JOIN tbDocumentsFile tdf					WITH (NOLOCK)
					ON	tdf.comp_id = tct.comp_id	AND
						tdf.df_id	= tct.df_id		AND
						tdf.bra_id	= tct.bra_id
				INNER JOIN tbSalesTerms tst						WITH (NOLOCK)
					ON	tst.comp_id = tct.comp_id AND
						tst.st_id	= tct.st_id
				WHERE	tct.comp_id			= @comp_id AND
						tct.ct_transaction	= @ct_transaction
			SET @datPayDate = dbo.fnGetEnd_or_BeginOfDate( DATEADD(DAY, @intDays2Pay, @datPayDate),'True')

			IF @bitUpdatePayDateWhenDelyveryDateUpdated = 'True'
				BEGIN
					UPDATE tbCommercialTransactions		WITH (ROWLOCK)
						SET ct_payDate			= @datPayDate
						WHERE	comp_id			= @comp_id AND
								ct_transaction	= @ct_transaction
				END
		END
	-- ----------------------------------------------------------------------------------------------------------





	UPDATE tbRMA_Detail	WITH (ROWLOCK)
		SET user_id_Delivery	= @user_id,
			rmad_Date_Delivery	= @ctd_isDelivered_CD,
			rmad_DelioveryNote	= @ctd_note1
		FROM tbRMA_Detail rmad
		INNER JOIN tbItemTransactions tit	WITH (NOLOCK)
			ON	tit.comp_id = rmad.comp_id AND
				tit.rmah_id = rmad.rmah_id AND
				tit.rmad_id = rmad.rmad_id
		WHERE tit.comp_id			= @comp_id AND
			  tit.ct_transaction	= @ct_transaction


END
GO








