GO




CREATE PROCEDURE [dbo].[spCommercialTransactionsGetDataForDocumentsMail]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@prof_id		INT,
	@ct_transaction	INT	,
	@df_IdAdditional INT
)
AS

BEGIN



	SET NOCOUNT ON

	-- ---------------------------------------------
	-- Testing
	-- ---------------------------------------------
	/*
		DECLARE
			@comp_id		INT,
			@lang_id		INT,
			@bra_id			INT,
			@user_id		INT,
			@prof_id		INT,
			@ct_transaction	INT	,
	@df_IdAdditional INT

		SELECT
			@comp_id		= 1,
			@lang_id		= 2,
			@bra_id			= 1,
			@user_id		= 1,
			@prof_id		= 1,
			@ct_transaction	= 13098,
@df_IdAdditional=-1
*/
	-- ---------------------------------------------

		SELECT
			isnull(tb.bra_MainDesc + ' - ' + dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,@ct_transaction), '')		[bra_desc],
			isnull(tdf.df_desc + ' - ' + dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,@ct_transaction), '')			[doc_description],
			isnull(tdf.df_eMail2Customer_emailFrom, '')																				[df_eMail2Customer_emailFrom],
			isnull(tdf.df_eMail2Customer_emailFromName, '')																			[df_eMail2Customer_emailFromName],
			isnull(tdf.df_eMail2Customer_emailTextBody, '')																			[df_eMail2Customer_emailTextBody],
			CASE
				WHEN tcb.comp_id IS NOT NULL AND ISNULL(tcb.custb_email,'') <> '' THEN  tcb.custb_email
				ELSE																	isnull(tc.cust_email, '')
			END																														[cust_email],
			isnull(tdf.df_eMail2Customer_emailToTest,'')																			[df_eMail2Customer_emailToTest],
			CASE
				WHEN tcb.comp_id IS NOT NULL AND ISNULL(tcb.custb_contact,'') <> '' THEN tcb.custb_contact
				ELSE															         ISNULL(tc.cust_contact,'')
			END																														[cust_contact],
			ISNULL(ts.sm_email,'')																									[sm_email],
			isnull(tdf.df_eMail2Customer_emailFromSalesman,'False')																	[df_eMail2Customer_emailFromSalesman],
			isnull(tdf.df_eMail2Customer_emailToTestCCO	,'')	+
			CASE
				WHEN ISNULL(tst.st_eMail2Customer_emailToTestCCO,'') <> '' THEN ';' + dbo.fnStrAllTrim(tst.st_eMail2Customer_emailToTestCCO)
				ELSE ''
			END																														[df_eMail2Customer_emailToTestCCO],
			isnull(tdf.df_eMail2Customer_emailInTEXTFormat	,'')																	[df_eMail2Customer_emailInTEXTFormat],

			dbo.fnStrAllTrim(
									ISNULL(
											(
											SELECT TOP 1 tccv.ccv_MPBotonDePagoLinkButton
												FROM tbCreditCard_VoucherRelations	AS tccvr	WITH (NOLOCK)
												INNER JOIN tbCreditCard_Voucher		AS tccv		WITH (NOLOCK)
													ON	tccv.comp_id			= tccvr.comp_id			AND
														tccv.ccv_id				= tccvr.ccv_id
												WHERE	tccvr.comp_id			= tct.comp_id			AND
														tccvr.ct_transaction	= tct.ct_transaction	AND
														tccv.ccv_MPBotonDePagoIsExpired = 0				AND
														tccv.ccv_isDECIDIRBP			= 'False'
												ORDER BY	CASE	-- Primero los de la FACTURA en particular ( que NO sean botones de TOTALES de varias facturas)
																WHEN tccv.ccv_MPBotonDePagoIsTotalButton = 'True' THEN 1
																ELSE 0
															END
															,
															CASE	-- Primero los de la CUOTA en particular
																WHEN tccvr.ctl_id IS NOT NULL THEN  0
																ELSE								1
															END

											)  ,'')
							)																	[MPct_MPButtonURL],

			dbo.fnStrAllTrim(
									ISNULL(
											(
											SELECT TOP 1 tccv.ccv_MPBotonDePagoLinkButton
												FROM tbCreditCard_VoucherRelations	AS tccvr	WITH (NOLOCK)
												INNER JOIN tbCreditCard_Voucher		AS tccv		WITH (NOLOCK)
													ON	tccv.comp_id			= tccvr.comp_id			AND
														tccv.ccv_id				= tccvr.ccv_id
												WHERE	tccvr.comp_id			= tct.comp_id			AND
														tccvr.ct_transaction	= tct.ct_transaction	AND
														tccv.ccv_MPBotonDePagoIsExpired = 0				AND
														tccv.ccv_isDECIDIRBP			= 'True'
												ORDER BY	CASE	-- Primero los de la FACTURA en particular ( que NO sean botones de TOTALES de varias facturas)
																WHEN tccv.ccv_MPBotonDePagoIsTotalButton = 'True' THEN 1
																ELSE 0
															END
															,
															CASE	-- Primero los de la CUOTA en particular
																WHEN tccvr.ctl_id IS NOT NULL THEN  0
																ELSE								1
															END

											)  ,'')
							)																	[DECIDIRBPct_ButtonURL]


			--ISNULL(tct.ct_MPButtonURL,'')																							[MPct_MPButtonURL]

		FROM tbCommercialTransactions			tct				WITH (NOLOCK)

		INNER JOIN tbDocumentsFile				tdf				WITH (NOLOCK)
		ON  tdf.comp_id	= tct.comp_id
		AND tdf.df_id	=	CASE
								WHEN @df_IdAdditional <> -1 THEN @df_IdAdditional
								ELSE tct.df_id
							END
		INNER JOIN tbBranch						tb				WITH (NOLOCK)
		ON  tb.comp_id	= tct.comp_id
		AND tb.bra_id	= tct.bra_id

		INNER JOIN tbCustomer					tc				WITH (NOLOCK)
		ON  tc.comp_id	= tct.comp_id
		AND tc.cust_id	= tct.cust_id

		INNER JOIN tbSalesman					ts				WITH (NOLOCK)
		ON	ts.comp_id	= tct.comp_id AND
			ts.sm_id	= tct.sm_id

		INNER JOIN tbSalesTerms				AS tst				WITH (NOLOCK)
			ON	tst.comp_id = tct.comp_id AND
				tst.st_id	= tct.st_id

		LEFT JOIN tbCustomerBranch				tcb				WITH (NOLOCK)
			ON	tcb.comp_id = tct.comp_id AND
				tcb.cust_id = tct.cust_id AND
				tcb.cb_id	= tct.cb_id

		WHERE	tct.comp_id		= @comp_id
		AND tct.ct_transaction	= @ct_transaction

END
GO





CREATE  PROCEDURE [dbo].[spCommercialTransactionsLoan_getData]
(
	@comp_id				INT,
	@ct_transaction			INT

)
AS

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	set nocount ON

	-- =================================================================================================================
	-- Author		: GA
	-- Update Date	: 2015-01-21
	-- Resumen de cuenta persoanl de cuotas.
	-- =================================================================================================================


	-- ---------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------
	/*
	declare		@comp_id				int,
				@ct_transaction			int

	select		@comp_id				= 1,
				@ct_transaction			= 10426

*/
	-- ---------------------------------------------------------------------


	SELECT  tctl.ctl_payNumber																	[ctl_payNumber],
			tctl.ctl_payDate																	[ctl_payDate],
			tctl.ctl_id																			[ID]




	FROM tbCommercialTransactionsLoan									tctl	WITH (NOLOCK)


	WHERE		tctl.comp_id		= @comp_id					AND
				tctl.ct_transaction = @ct_transaction


	ORDER BY tctl.ctl_payNumber







END
GO






CREATE  PROCEDURE [dbo].[spCommercialTransactionsLoan_getDataByFilters]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id  			INT,
	@cust_id  			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME

)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	set nocount ON

	-- =================================================================================================================
	-- Author		: GA
	-- Update Date	: 2015-01-21
	-- Resumen de cuenta persoanl de cuotas.
	-- =================================================================================================================


	-- ---------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------
/*
	declare		@comp_id			int,
				@lang_id			int,
				@bra_id  			INT,
				@cust_id  			INT,
				@dateto				DATETIME,
				@datefrom			DATETIME

	select		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@cust_id			= -1,
				@datefrom			= '1999-08-01',
				@dateto				= '2999-08-31'

	*/

	-- ---------------------------------------------------------------------


	SET @dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	SELECT  tct.ct_date																			[ct_date],
			tctl.ctl_payNumber																	[ctl_payNumber],
			tctl.ctl_lastPayDate																[ctl_lastPayDate],
			tctl.ctl_daysPastDue																[ctl_daysPastDue],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction)	[document],
			tctl.ct_ATotal																		[ct_ATotal],
			tctl.ct_ABalance																	[ct_ABalance]




	FROM tbCommercialTransactionsLoan									tctl	WITH (NOLOCK)

	INNER JOIN tbCommercialTransactions									tct		WITH (NOLOCK)
	ON	tct.comp_id				= tctl.comp_id			AND
		tct.ct_transaction		= tctl.ct_transaction






	WHERE	tctl.comp_id	= @comp_id									AND
			(@cust_id		= -1	OR tct.cust_id		= @cust_id)		AND
			(tct.ct_date		BETWEEN		@datefrom	AND	@dateto)










END
GO






CREATE  PROCEDURE [dbo].[spCommercialTransactionsLoan_getDataById]
(
	@comp_id			int,
	@lang_id			int,
	@ctl_id  			int
)
AS


BEGIN



	set nocount on
	-- =================================================================================================================
	-- Author		: MOS
	-- Update Date	: 2014-11-12
	-- Parte		: s/P referencia: #1
	-- Se quita una condición de inner join para que traiga comprobantes de diferentes sucursales
	-- =================================================================================================================


	-- ---------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------
/*
	declare	@comp_id	int,
			@lang_id	int,
			@ctl_id		int

	select	@comp_id	=1,
			@lang_id	=2,
			@ctl_id		= 15
*/
	-- ---------------------------------------------------------------------


	SELECT tctl.ct_ABalance,tctl.ctl_payNumber, tctl.ctl_payDate,tctl.ct_ATotal

		FROM tbCommercialTransactionsLoan tctl	WITH (NOLOCK)
		WHERE	tctl.comp_id	= @comp_id AND
				tctl.ctl_id		= @ctl_id


END
GO





CREATE  PROCEDURE [dbo].[spCommercialTransactionsLoan_getReport]
(
	@comp_id			INT,
	@lang_id			INT,
	@page_id			INT,
	@bra_id  			INT,
	@cust_id  			INT,
	@user_id			INT

)
AS




BEGIN

	set nocount ON


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ---------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------
	/*
	declare
			@comp_id			INT,
			@lang_id			INT,
			@page_id			INT,
			@bra_id  			INT,
			@cust_id  			INT,
			@user_id			INT


	select
			@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 100957,
			@bra_id				= 1,
			@cust_id			= 160851,
			@user_id			= 1
	*/
	-- ---------------------------------------------------------------------

	declare		@intcountdec INT
	set			@intcountdec = 2


	-- x velocidad
	DECLARE		@tbCommercialTransactionsLoan TABLE(comp_id INT ,  ct_transaction INT ,ct_ATotal DECIMAL(19,4),ctl_payNumber INT, ctl_payDate DATETIME,ct_ABalance DECIMAL(19,4)  PRIMARY KEY(comp_id,ct_transaction,ctl_payNumber, ctl_payDate  /*MOS AUTH 01-06-2021.  No se que hicieron pero pusieron 2 numeros de cuota iguales*/))
	INSERT INTO @tbCommercialTransactionsLoan(	comp_id,
												ct_transaction,
												ct_ATotal,
												ctl_payNumber,
												ctl_payDate,
												ct_ABalance)
		SELECT	DISTINCT	-- MOS 04-2022 x forros q ponen a mano cuotas duplicadas.
				tctl.comp_id,
				tctl.ct_transaction,
				tctl.ct_ATotal,
				tctl.ctl_payNumber,
				tctl.ctl_payDate,
				tctl.ct_ABalance
			FROM tbCommercialTransactionsLoan tctl	WITH (NOLOCK)
			WHERE tctl.comp_id = @comp_id AND tctl.ct_ABalance <> 0


	SELECT
	    tc.cust_name																		[cust_name],
	    dbo.fnGetCommercialTransactionDescription(tct.[comp_id],@lang_id,tct.[ct_transaction])	+
		CASE
			WHEN tctl.comp_id IS NULL THEN ''
			ELSE ' / ' + convert(nvarchar(3),tctl.ctl_payNumber)
		END
																							[doc],
		CASE
			WHEN tctl.comp_id IS NULL THEN	tct.[ct_payDate]
			ELSE							tctl.ctl_payDate
		END																					[ct_payDate],

--		convert(decimal(18,2),round(tctl.ct_ATotal,@intcountdec))							[ct_ATotal],
--
--		convert(decimal(18,2),round(tctl.ct_ABalance,@intcountdec))							[ct_ABalance],


		CASE
				WHEN tctl.comp_id IS NULL THEN	convert(decimal(18,2),round(		tct.[ct_ATotal],	@intcountdec))
				ELSE							convert(decimal(18,2),round(		tctl.ct_ATotal,		@intcountdec))
		END																					[ct_ATotal],
		CASE
				WHEN tctl.comp_id IS NULL THEN	convert(decimal(18,2),round(		tct.[ct_ABalance],	@intcountdec))
				ELSE							convert(decimal(18,2),round(		tctl.ct_ABalance,	@intcountdec))
		END																					[ct_ABalance],

		dbo.fnGetItemTransactionsOnlyItems(tct.comp_id,tct.ct_transaction)					[item_desc],
		tct.ct_transaction																	[ct_transaction]

		FROM tbCommercialTransactions										tct		WITH (NOLOCK)

		INNER join dbo.vwCommercialTransactions_forSales					vctfs	WITH (NOLOCK)
		On	vctfs.comp_id				=	tct.comp_id
		and vctfs.ct_transaction		=	tct.ct_transaction

		INNER JOIN tbUsers4BranchFilter								vubf		WITH (NOLOCK)
		ON	vubf.comp_id					=	tct.comp_id
		AND	vubf.bra_id						=	tct.bra_id
		AND	vubf.[user_id]					=	@user_id

		LEFT JOIN @tbCommercialTransactionsLoan								tctl	--WITH (NOLOCK)
		ON	tctl.comp_id			= tct.comp_id			AND
			tctl.ct_transaction		= tct.ct_transaction	--AND
			--tctl.ct_ABalance		<> 0

		INNER JOIN tbCustomer												tc		WITH (NOLOCK)
		ON	tc.comp_id				= tct.comp_id AND
			tc.cust_id				= tct.cust_id


		WHERE	tct.comp_id							= @comp_id		AND
				tct.cust_id							= @cust_id		AND
				vctfs.[sd_isInBalance]				=	'True'		AND
				vctfs.[sd_isCredit]					=	'False'		AND
				vctfs.[sd_isReceipt]				=	'False'		AND
				tct.ct_Abalance						<>	0			--AND
				--tct.ct_docNumber					<>	''


		ORDER BY tct.ct_transaction, tctl.ctl_payNumber asc



		---Datos para el reporte
		EXEC [spReports_getData3]@comp_id,@bra_id, @lang_id,@page_id,@bra_id
		---




END
GO


CREATE PROCEDURE [dbo].[spCommercialTransactionsLoan_Process_Auto]
(
	@comp_id				INT,
	@internalID				NVARCHAR(50),
	@ctl_PayNumber			INT,
	@ctl_PayDate			DATETIME,
	@ct_Atotal				DECIMAL(25,4),
	@ct_Abalance			DECIMAL(25,4),
	@ctl_payNumberTotalQty	INT,
	@NotValidateDuplicates	BIT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@internalID				NVARCHAR(50),
				@ctl_PayNumber			INT,
				@ctl_PayDate			DATETIME,
				@ct_Atotal				DECIMAL(25,4),
				@ct_Abalance			DECIMAL(25,4),
				@ctl_payNumberTotalQty	INT,
				@NotValidateDuplicates	BIT

			SELECT
				@comp_id				= 1,
				@internalID				= '445',
				@ctl_PayNumber			= 0,
				@ctl_PayDate			= '2016-10-11',
				@ct_Atotal				= -1500,
				@ct_Abalance			= -1500,
				@ctl_payNumberTotalQty	= 1,
				@NotValidateDuplicates	= 'False'
		*/
		-- -----------------------------------------------------

		DECLARE @return_value	INT
		SET		@return_value	= -1



		-- RECUPERAMOS EL CT_TRANSACTION
		DECLARE	@ct_transaction	INT
		SELECT
				@ct_transaction = tctdir.ct_transaction
			FROM tbCommercialTransactions_dataImportRelations	tctdir
			WHERE	tctdir.comp_id					= @comp_id			AND
					tctdir.dataimport_internal_id	= @internalID

		IF @ctl_PayNumber < 0
			BEGIN
				--SET @ctl_PayNumber = NULL
				SET @return_value = -1
				SELECT
					@return_value	[Return_Value],
					@internalID		[InternalID],
					@ctl_PayNumber	[PayNumber]
				RETURN
			END

		IF (@ct_Atotal < 0) OR (@ct_Atotal < 0)
			BEGIN
				SET @return_value = -1
				SELECT
					@return_value	[Return_Value],
					@internalID		[InternalID],
					@ctl_PayNumber	[PayNumber]
				RETURN
			END

		IF @NotValidateDuplicates = 'False'
			BEGIN
				IF EXISTS (SELECT
							1 FROM tbCommercialTransactionsLoan tctl
							WHERE tctl.comp_id = @comp_id AND tctl.ct_transaction = @ct_transaction AND tctl.ctl_payNumber = @ctl_PayNumber)
					BEGIN
						SET @return_value = -2
						SELECT
							@return_value	[Return_Value],
							@internalID		[InternalID],
							@ctl_PayNumber	[PayNumber]
						RETURN
					END
			END


		BEGIN TRY
			INSERT INTO tbCommercialTransactionsLoan
			(
				comp_id,
				ct_transaction,
				ctl_payNumber,
				ctl_payDate,
				ct_ATotal,
				ct_ABalance,
				curr_id,
				ctl_payNumberTotalQty,
				ctl_isMigrated
			)
			SELECT
				tct.comp_id,
				tct.ct_transaction,
				@ctl_PayNumber,
				@ctl_PayDate,
				@ct_Atotal,
				@ct_Abalance,
				tct.ct_ACurrency,
				@ctl_payNumberTotalQty,
				'True'
				FROM tbCommercialTransactions_dataImportRelations	tctdir	WITH(NOLOCK)
					INNER JOIN tbCommercialTransactions				tct		WITH(NOLOCK)
						ON  tct.comp_id			= tctdir.comp_id	AND
							tct.ct_transaction	= tctdir.ct_transaction
				WHERE	tctdir.comp_id					= @comp_id			AND
						tctdir.dataimport_internal_id	= @internalID		AND
						tctdir.dataimport_type			= 1

			IF @@ROWCOUNT > 0
				BEGIN
					SET	@return_value = IDENT_CURRENT('tbCommercialTransactionsLoan')
				END

		END TRY
		BEGIN CATCH
			SET @return_value = -1
		END CATCH

		SELECT
			ISNULL(@return_value,-1)	[Return_Value],
			@internalID					[InternalID],
			@ctl_PayNumber				[PayNumber]

	END
GO


