GO







CREATE PROCEDURE [dbo].[spCommercialTransactionsNotes_getDataById]
(
	@comp_id			INT,
	@bra_id				INT,
	@ct_transaction		INT,
	@user_id			INT
)
AS

SET NOCOUNT ON
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2011-05-27
-- TN			: 744
-- Description	: Se modifica todo el esquema de condiciones para el armado del query teniendo en cuenta que
--				  pueden estar informados o no todos los campos de tbCommercialTransactionsNotes
-- =================================================================================================================



/*
DECLARE	@comp_id			INT,
		@bra_id				INT,
		@ct_transaction		INT,
		@user_id			INT
SELECT	@comp_id			=1,
		@bra_id				=1,
		@ct_transaction		=7118,
		@user_id			=1
*/




DECLARE	@lctn_note1		VARCHAR(100),
		@lctn_note2		VARCHAR(100),
		@lctn_note3		VARCHAR(100),
		@lctn_note4		VARCHAR(100),
		@lctn_internal	VARCHAR(100)



SELECT	@lctn_note1	   =	ltrim(rtrim(ctn_note1)),
		@lctn_note2	   =	ltrim(rtrim(ctn_note2)),
		@lctn_note3	   =	ltrim(rtrim(ctn_note3)),
		@lctn_note4	   =	ltrim(rtrim(ctn_note4)),
		@lctn_internal =	LTRIM(RTRIM(ctn_internalAnnotation))

FROM 	tbCommercialTransactionNotes			ct

		INNER JOIN tbUsers4BranchFilter			vubf
		ON	vubf.comp_id	=  ct.comp_id
		AND	vubf.bra_id		=  ct.bra_id
		AND	vubf.[user_id]	=  @user_id

WHERE	ct.comp_id		=	@comp_id
AND		ct.bra_id		=	@bra_id
AND		ct_transaction	=	@ct_transaction



DECLARE @query	VARCHAR(8000)
SET @query = ''



IF  LEN(@lctn_note1) > 0
	SET @query = @query + 'select ''' + @lctn_note1 + ''' [desc]'



IF  LEN(@lctn_note2) > 0
BEGIN
	IF  LEN(@query) > 0
		SET @query = @query + ' union '

	SET @query = @query + 'select ''' + @lctn_note2 + ''''

	IF  CHARINDEX('[desc]',@query,0) = 0
		SET @query = @query + ' [desc]'
END



IF  LEN(@lctn_note3) > 0
BEGIN
	IF  LEN(@query) > 0
		SET @query = @query + ' union '

	SET @query = @query + 'select ''' + @lctn_note3 + ''''

	IF  CHARINDEX('[desc]',@query,0) = 0
		SET @query = @query + ' [desc]'
END




IF  LEN(@lctn_note4) > 0
BEGIN
	IF  LEN(@query) > 0
		SET @query = @query + ' union '

	SET @query = @query + 'select ''' + @lctn_note4 + ''''

	IF  CHARINDEX('[desc]',@query,0) = 0
		SET @query = @query + ' [desc]'
END




IF  LEN(@lctn_internal) > 0
BEGIN
	IF LEN(@query) > 0
		SET @query = @query + ' union '

	SET @query = @query + 'select ''' + @lctn_internal + ''''

	IF CHARINDEX('[desc]',@query,0) = 0
		SET @query = @query + ' [desc]'
END


--SELECT @query
IF  LEN(@query) > 0
	EXECUTE (@query)


GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2009
-- Description:	Alta de
-- CommercialTransactionsNotes
-- =============================================
CREATE PROCEDURE [dbo].[spCommercialTransactionsNotes_Insertdata]
	@comp_id AS INT,
	@bra_id AS INT,
	@ct_transaction AS INT,
	@Note1 AS VARCHAR(350),
	@Note2 AS VARCHAR(350),
	@Note3 AS VARCHAR(350),
	@Note4 AS VARCHAR(350),
	@internalAnnotation AS VARCHAR(100),
	@return_value			as int			output,
	@ret_ErrorCode			as int			output,
	@ret_ErrorDescription	as varchar(200) output

AS
BEGIN

	SET NOCOUNT ON;

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''


	IF not EXISTS(	SELECT TOP 1  1
					FROM tbCommercialTransactionNotes tctn		WITH (NOLOCK)
					WHERE	tctn.comp_id		= @comp_id	AND
							--tctn.bra_id			= @bra_id	AND
							tctn.ct_transaction = @ct_transaction)
		BEGIN

			INSERT INTO tbCommercialTransactionNotes
				(	comp_id,
					bra_id,
					ct_transaction,
					ctn_note1,
					ctn_note2,
					ctn_note3,
					ctn_note4,
					ctn_internalAnnotation)

				Values
				(	@comp_id,
					@bra_id,
					@ct_transaction,
					@Note1,
					@Note2,
					@Note3,
					@Note4,
					@internalAnnotation)


		END
	ELSE
		BEGIN
			UPDATE tbCommercialTransactionNotes WITH (ROWLOCK)
				SET
					ctn_note1 = @Note1,
					ctn_note2 = @Note2,
					ctn_note3 = @Note3,
					ctn_note4 = @Note4,
					ctn_internalAnnotation = @internalAnnotation
				WHERE	comp_id			= @comp_id	AND
						bra_id			= @bra_id	AND
						ct_transaction	= @ct_transaction

		END

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 09-2012
-- =============================================

CREATE PROCEDURE [dbo].[spCommercialTransactionsNotes_updateURL4Reprint]
	@comp_id		AS INT,
	@bra_id			AS INT,
	@ct_transaction	AS INT,
	@URL4Reprint	AS NVARCHAR(MAX),
	@deliveryAddressOfSaleOrder AS NVARCHAR(500),
	@pro_id			AS INT
AS

BEGIN

	SET NOCOUNT ON;

	if NOT EXISTS( SELECT 1
						FROM tbCommercialTransactionNotes tctn WITH (NOLOCK)
						WHERE	tctn.comp_id		= @comp_id
							AND tctn.bra_id			= @bra_id
							AND tctn.ct_transaction = @ct_transaction)
		BEGIN

			INSERT INTO tbCommercialTransactionNotes
			(
				comp_id,
				bra_id,
				ct_transaction,
				ctn_note1,
				ctn_note2,
				ctn_note3,
				ctn_note4,
				ctn_internalAnnotation,
				ctn_link4Reprint,
				ctn_deliveryAddressOfSaleOrder
			)
			VALUES
			(
				@comp_id,
				@bra_id,
				@ct_transaction,
				'',
				'',
				'',
				'',
				'',
				@URL4Reprint,
				@deliveryAddressOfSaleOrder
			)
		END

	ELSE

		BEGIN
			UPDATE tbCommercialTransactionNotes
			SET
				ctn_link4Reprint				= @URL4Reprint,
				ctn_deliveryAddressOfSaleOrder	= @deliveryAddressOfSaleOrder
			WHERE	comp_id			= @comp_id
				AND ct_transaction	= @ct_transaction

		END


	IF @pro_id <> -1
		BEGIN
			UPDATE tbCommercialTransactions
				SET		pro_id			= @pro_id
				WHERE	comp_id			= @comp_id AND
						ct_transaction	= @ct_transaction
		END



END

GO






CREATE  PROCEDURE [dbo].[spCommercialTransactionsOtherPayments_insertData]
(
	@comp_id				INT,
	@bra_id					INT,
	@ct_transaction			INT,
