CREATE PROCEDURE [dbo].[spCommercialTransactionsOtherPaymentsDetailTmp_getData]
(
	@comp_id				INT,
    @ctopdt_guid			UNIQUEIDENTIFIER
)
AS

BEGIN


	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOS
	-- Creation Date: 2010-08-26
	-- Parte		: 473
	-- Description	: Se agrega un nuevo tab de Conceptos a Pagar en Pagos, este sp es para alimentar la nueva funcionalidad
	-- =================================================================================================================

	SELECT	' ' [ ], ' ' [ ],
			tctopdt.ctopdt_desc,
			tctopdt.ctopdt_total,
			tctopdt.acc_count_id,
			ta.acc_code,
			ta.acc_desc,
      		tctopdt.puco_id,
      		tpc.puco_desc,
      		tctopdt.cc_code,
      		tcc.cc_desc,
      		tctopdt.ctopdt_id


	FROM	tbCommercialTransactionsOtherPaymentsDetailTmp	tctopdt		WITH (NOLOCK)

			LEFT JOIN tbAccountant							ta			WITH (NOLOCK)
			ON	ta.comp_id			= tctopdt.comp_id
			AND ta.acc_count_id		= tctopdt.acc_count_id

			LEFT JOIN tbPurchaseConcept						tpc			WITH (NOLOCK)
			ON	tpc.comp_id			= tctopdt.comp_id
			AND tpc.puco_id			= tctopdt.puco_id

			LEFT JOIN tbCostCenter							tcc			WITH (NOLOCK)
			ON	tcc.comp_id			= tctopdt.comp_id
			AND tcc.cc_code			= tctopdt.cc_code

	WHERE	tctopdt.comp_id			= @comp_id
	AND		tctopdt.ctopdt_guid		= @ctopdt_guid



END
GO







