-- -----------------------------------------------------------------------------
-- MOS: 08-2010
-- esta tabla se usa para posibles calculos de retenciones sobre pagos a cuenta
-- -----------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spCommercialTransactionsPaymentsAdditionals_InsertData]
(
	@comp_id							AS INT,
	@bra_id							AS INT,
	@ct_transaction					as int,
	@puco_id						as INT,
	@tax_id							AS INT,

	@ctr_note						NVARCHAR(4000),
	@tax_id4Discount				INT,
	@ctr_isOtherPayment				BIT,
	@ctr_onAccountAtGenerationTaxableBase	AS DECIMAL(19,4),

	@return_value					as int			output,
	@ret_ErrorCode					as int			output,
	@ret_ErrorDescription			as varchar(200)	output
)
AS
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-08-25
-- Parte		: 481
-- Description	: Se agregan los nuevos campos de la tabla, @ctr_note, @tax_id4Discount, @ctr_isOtherPayment
-- =================================================================================================================


BEGIN

	set nocount on

	SET @return_value			= 0
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''


	DECLARE @intOnAccount AS DECIMAL(19,6)

	SELECT @intOnAccount			= tct.ct_ABalance * tct.ct_ACurrencyExchange
		FROM tbCommercialTransactions tct
		WHERE	tct.comp_id			= @comp_id
			AND tct.bra_id			= @bra_id
			AND tct.ct_transaction	= @ct_transaction


	INSERT INTO tbCommercialTransactionsPaymentsAdditionals
	(
		comp_id,
		bra_id,
		ct_transaction,
		ctr_onAccountAtGeneration,
		puco_id,
		tax_id,

		ctr_note,					-- Parte		: 481
		tax_id4Discount,			-- Parte		: 481
		ctr_isOtherPayment,
		ctr_onAccountAtGenerationTaxableBase	--* HDP de CM
	)
	VALUES
	(
		@comp_id,
		@bra_id,
		@ct_transaction,
		@intOnAccount,
		@puco_id,
		@tax_id,

