------------------------------------------------------------------------------------------------------
--Date	: 13/04/15
--Author: GA
--Desc	: Carga de Asignacion de pagos.
-- Update 12/06/15 GA , se le agrego variable para saber si viene de ctacte y si recalcula o no
-- para mostrar el saldo .
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spCommercialTransactionsPurchaseLoan_getDatabyFilters]
(

		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,

		@guid				UNIQUEIDENTIFIER,
		@isrecalculate      BIT,
		@isFromCommSupp     BIT



)
as
SET NOCOUNT ON

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,

				@pt_id				INT,
				@total				DECIMAL(19,4),
				@guid				UNIQUEIDENTIFIER,
				@isrecalculate      BIT,
				@isFromCommSupp     BIT



	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@pt_id				= -1,
				@user_id			= 3,
				@prof_id			= 1,
				@total				= -1,
				@guid				= 'F7381D2C-25E4-402E-AE30-ED224F5BEF4B',
				@isrecalculate		= 'False',
				@isFromCommSupp		= 'True'
*/
-------------------------------------------------------------------------------------------

IF @isFromCommSupp = 'False'

	BEGIN
				SELECT	' '												[ ],
						tctpl.ctpl_payNumber							[#],
						tctpl.ctpl_payDate								[ctpl_date],
						convert(decimal(19,2),tctpl.ctpl_Total)			[ctpl_Total],
						convert(nvarchar(50),tctpl.ctpl_payDate)		[ctpl_date1],
						tctpl.ctpl_id									[ID]

						FROM tbCommercialTransactionsPurchaseLoan			tctpl	WITH (NOLOCK)



						Where	tctpl.comp_id	= @comp_id		AND
								tctpl.ctpl_guid = @guid



						ORDER BY tctpl.ctpl_id


	END
ELSE
	BEGIN
		IF @isrecalculate = 'True'
				BEGIN
						-- Si es recalculando no se muestra el saldo

						SELECT  ' ' [ ],
						tctpl.ctpl_payNumber							[#],
						tctpl.ctpl_payDate								[ctpl_date],
						convert(decimal(19,2),tctpl.ctpl_Total)			[ctpl_Total],
						convert(nvarchar(50),tctpl.ctpl_payDate)		[ctpl_date1],
						tctpl.ctpl_id									[ID]

						FROM tbCommercialTransactionsPurchaseLoan			tctpl	WITH (NOLOCK)



						Where	tctpl.comp_id	= @comp_id		AND
								tctpl.ctpl_guid = @guid



						ORDER BY tctpl.ctpl_id

				END

		ELSE

				BEGIN
					-- Si NO es recalculando Se muestra el saldo

					SELECT  ' ' [ ],
					tctpl.ctpl_payNumber							[#],
					tctpl.ctpl_payDate								[ctpl_date],
					convert(decimal(19,2),tctpl.ctpl_Total)			[ctpl_Total],
					convert(decimal(19,2),tctpl.ctpl_balance)		[ctpl_balance],
					convert(nvarchar(50),tctpl.ctpl_payDate)		[ctpl_date1],
					tctpl.ctpl_id									[ID]

					FROM tbCommercialTransactionsPurchaseLoan			tctpl	WITH (NOLOCK)



					Where	tctpl.comp_id	= @comp_id		AND
							tctpl.ctpl_guid = @guid



					ORDER BY tctpl.ctpl_id
			   END
	END


END
GO




