CREATE PROCEDURE [dbo].[spCommercialTransactionsPurchaseLoan_insertData]
(
	@comp_id				int,
	@ctpl_date				datetime,
	@ctpl_Total				DECIMAL(19,4),
	@ctpl_balance			DECIMAL(19,4),
	@ctpl_payDate			datetime,
	@user_id_creator		int,
	@user_id_payer			int,
	@ctpl_guid				uniqueidentifier,
	@ctpl_cd				datetime,
	@ct_transaction			int,
	@bra_id					int,
	@poh_id					int,
	@ctpl_paysQTY			int,
	@ctpl_paysFirstDate		datetime,
	@ctpl_payNumber			INT

)
as


set nocount on
set dateformat 'ymd'

BEGIN



	------------------------------------------------------------------------------------------------
	------------------------------------------------------------------------------------------------

	/*

	DECLARE @comp_id				int,
			@ctpl_date				datetime,
			@ctpl_Total				DECIMAL(19,4),
			@ctpl_balance			DECIMAL(19,4),
			@ctpl_payDate			datetime,
			@user_id_creator		int,
			@user_id_payer			int,
			@ctpl_guid				uniqueidentifier,
			@ctpl_cd				datetime,
			@ct_transaction			int,
			@bra_id					int,
			@poh_id					int,
			@ctpl_paysQTY			int,
			@ctpl_paysFirstDate		datetime,
			@ctpl_payNumber			INT


	SELECT  @comp_id				= 1 ,
			@ctpl_date				= getdate(),
			@ctpl_Total				= 333,
			@ctpl_balance			= 333,
			@ctpl_payDate			= getdate(),
			@user_id_creator		= 1,
			@user_id_payer			=-1,
			@ctpl_guid				='f77b5ec8-90ff-4fc8-9bb7-ee4324e31323',
			@ctpl_cd				= getdate(),
			@ct_transaction			=-1,
			@bra_id					=-1,
			@poh_id					=-1,
			@ctpl_paysQTY			= 3,
			@ctpl_paysFirstDate		= getdate(),
			@ctpl_payNumber			= 1

	*/
	------------------------------------------------------------------------------------------------
	------------------------------------------------------------------------------------------------



	IF @user_id_payer = -1
		BEGIN
			SET @user_id_payer = NULL
		END


	IF @ct_transaction = -1
		BEGIN
			SET @ct_transaction = NULL
		END


	IF @bra_id = -1
		BEGIN
			SET @bra_id = NULL
		END


	IF @poh_id = -1
		BEGIN
			SET @poh_id = NULL
		END

	DECLARE @lqty AS INT, @lpaynumber AS INT, @lpayDate AS DATETIME


	SELECT @lqty = @ctpl_paysQTY
	SELECT @lpaynumber = 1
	SELECT @lpayDate = @ctpl_payDate

	SELECT @ctpl_Total		=   @ctpl_Total / @ctpl_paysQTY
	SELECT @ctpl_balance	=   @ctpl_Total


	WHILE @lqty <> 0

		BEGIN


			INSERT INTO tbCommercialTransactionsPurchaseLoan
				(
					comp_id,
					ctpl_date,
					ctpl_Total,
					ctpl_balance,
					ctpl_payDate,
					user_id_creator,
					user_id_payer,
					ctpl_guid,
					ctpl_cd,
					ct_transaction,
					bra_id,
					poh_id,
					ctpl_paysQTY,
					ctpl_paysFirstDate,
					ctpl_payNumber
				)
				VALUES
				(
					@comp_id,
					@ctpl_date,
					@ctpl_Total,
					@ctpl_balance,
					@lpayDate,
					@user_id_creator,
					@user_id_payer,
					@ctpl_guid,
					@ctpl_cd,
					@ct_transaction	,
					@bra_id	,
					@poh_id	,
					@ctpl_paysQTY,
					@ctpl_paysFirstDate	,
					@lpaynumber
				)


			SET @lpayDate = DATEADD(MONTH,@lpaynumber,@ctpl_paysFirstDate)

			SET	@lqty = @lqty - 1
			SET	@lpaynumber = @lpaynumber + 1


		END



END























GO




