-- =============================================
-- Author:		MOS
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE  PROCEDURE [dbo].[spCommercialTransactionsPurchaseLoan_RecalculateBalance]
	@comp_id AS INT,
	@ct_transaction AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @decTotal	AS DECIMAL(19,4)
	DECLARE @decBalance AS DECIMAL(19,4)
	DECLARE @curr_id	AS INT
	DECLARE @bitIsLoan  AS BIT
	SET @decTotal	= 0
	SET @decBalance = 0
	SET @bitIsLoan  = 'False'

	SELECT	@decTotal	= tct.ct_ATotal,
			@decBalance = tct.ct_ABalance,
			@curr_id	= tct.ct_ACurrency,
			@bitIsLoan	= 'True'
		FROM tbCommercialTransactions tct						WITH (NOLOCK)
		INNER JOIN tbCommercialTransactionsPurchaseLoan tctpl	WITH (NOLOCK)
			ON	tctpl.comp_id			= tct.comp_id AND
				tctpl.ct_transaction	= tct.ct_transaction
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @ct_transaction

	-- Si es que tiene credito
	IF @bitIsLoan = 'True'
		BEGIN

			DECLARE @decPayed AS DECIMAL(19,4)
			SET		@decPayed = @decTotal - @decBalance


			-- 1ro pongo los saldos igual al total.
			-- Se pueden haber modificado las cuotas y por ende debo recalcular los saldos.!
			UPDATE tbCommercialTransactionsPurchaseLoan		WITH (ROWLOCK)
				SET		ctpl_balance	= ctpl_Total
				WHERE	comp_id			= @comp_id AND
						ct_transaction	= @ct_transaction


			DECLARE  curCommercialTransactionsPurchaseLoan CURSOR LOCAL FAST_FORWARD FOR
				SELECT	tctpl.comp_id,
						tctpl.ctpl_id,
						tctpl.ctpl_Total,
						tctpl.ctpl_balance
					FROM tbCommercialTransactionsPurchaseLoan tctpl		WITH (NOLOCK)
					WHERE	tctpl.comp_id			= @comp_id AND
							tctpl.ct_transaction	= @ct_transaction
					ORDER BY tctpl.ctpl_date

			OPEN		curCommercialTransactionsPurchaseLoan

			DECLARE @currCompId		AS INT
			DECLARE @currCtplId		AS INT
			DECLARE @currTotal		AS DECIMAL(19,4)
			DECLARE @currBalance	AS DECIMAL(19,4)
			FETCH NEXT FROM curCommercialTransactionsPurchaseLoan
				INTO	@currCompId,
						@currCtplId,
						@currTotal,
						@currBalance



			WHILE @@FETCH_STATUS = 0
				BEGIN



					IF @decPayed > 0
						BEGIN

							IF @decPayed >= @currBalance
								BEGIN
									UPDATE tbCommercialTransactionsPurchaseLoan	WITH (ROWLOCK)
										SET		ctpl_balance = 0
										WHERE	comp_id = @comp_id AND
												ctpl_id = @currCtplId
									SET @decPayed = @decPayed - @currBalance
								END
							ELSE
								BEGIN
									UPDATE tbCommercialTransactionsPurchaseLoan	WITH (ROWLOCK)
										SET		ctpl_balance = ctpl_balance - @decPayed
										WHERE	comp_id = @comp_id AND
												ctpl_id = @currCtplId
									SET @decPayed = 0
								END

						END


					FETCH NEXT FROM curCommercialTransactionsPurchaseLoan
						INTO	@currCompId,
								@currCtplId,
								@currTotal,
								@currBalance

				END



			CLOSE		curCommercialTransactionsPurchaseLoan
			DEALLOCATE	curCommercialTransactionsPurchaseLoan




		END

END
GO




