--Desc	:INSERT cta cte supp
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spCommercialTransactionsPurchaseLoan_Supp_getData]
(

		@comp_id			INT,
		@ct_transaction		INT,
		@guid				UNIQUEIDENTIFIER

)
as
SET NOCOUNT ON

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	-- SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


------------------------------------------------------------------------------------------
/*
	DECLARE 			@comp_id			INT,
					@ct_transaction		INT,
					@guid				UNIQUEIDENTIFIER



	SELECT		@comp_id			= 1,
				@ct_transaction			= 2,
				@guid				= '1592A229-6022-424A-9AEF-94E35D958992'
*/
-------------------------------------------------------------------------------------------


	-- INserta las cuotas como temporales

	INSERT INTO tbCommercialTransactionsPurchaseLoan
			(	comp_id,
				ctpl_date,
	            ctpl_Total,
	            ctpl_balance,
	            ctpl_payDate,
	            user_id_creator,
	            user_id_payer,
	            ctpl_guid,
	            ctpl_cd,
	            ctpl_paysQTY,
	            ctpl_paysFirstDate,
	            ctpl_payNumber)

		SELECT	tmp.comp_id,
				tmp.ctpl_date,
				tmp.ctpl_Total,
				tmp.ctpl_balance,
				tmp.ctpl_payDate,
				tmp.user_id_creator,
				tmp.user_id_payer,
				@guid,
				tmp.ctpl_cd,
				tmp.ctpl_paysQTY,
				tmp.ctpl_paysFirstDate,
				tmp.ctpl_payNumber

			FROM tbCommercialTransactionsPurchaseLoan tmp   WITH (NOLOCK)


			WHERE	tmp.comp_id			= @comp_id			AND
					tmp.ct_transaction	= @ct_transaction








END

GO





CREATE PROCEDURE [dbo].[spCommercialTransactionsPurchaseLoan_Supp_updateLoanData]
(


	@comp_id					INT,
	@ct_transaction				INT,
	@guid		     			UNIQUEIDENTIFIER


)
AS

BEGIN



	SET NOCOUNT ON

	-- Borro los originales
	DELETE FROM tbCommercialTransactionsPurchaseLoan
		WHERE	comp_id		    = @comp_id	AND
	    		ct_transaction	= @ct_transaction

	-- Le pongo a los temporales los datos del original
	UPDATE tbCommercialTransactionsPurchaseLoan
		SET
			ctpl_guid		= NULL,
			ct_transaction	= @ct_transaction,
			ctpl_balance	= ctpl_Total           -- OJO, si hacemos PAGOS de cuotas, esto hay que verlo !!!!  ya que no se pueden cambiar importes de cuotas YA PAGAS, solo FECHAS.

		WHERE ctpl_guid = @guid





END
