CREATE PROCEDURE [dbo].[spCommercialTransactionsSetFEIdNumber]
	@comp_id			AS INT,
	@ct_transaction		AS INT,
	@FEIdNumber			AS INT,
	@FEStrCAE			AS NVARCHAR(100),
	@FEDatCAE			AS DATETIME
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	UPDATE tbCommercialTransactions	WITH (ROWLOCK)
		SET
			ct_FEIdNumber		= @FEIdNumber,
			ct_CAI				= @FEStrCAE,
			ct_CAIDate			= @FEDatCAE
		WHERE	comp_id			= @comp_id
			AND ct_transaction	= @ct_transaction

END
GO








CREATE PROCEDURE [dbo].[spCommercialTransactionsTmp_deleteAllData]
(
	@comp_id			int,
	@guid				uniqueidentifier,
	@ctct_origin		char(1)
)
as

BEGIN



	set nocount on

	-- -------------------------------------------------------------------
	-- Test
	-- -------------------------------------------------------------------
	/*
	declare	@comp_id			int,
			@guid				UNIQUEIDENTIFIER,
			@ctct_origin		char(1)
	select	@comp_id			=1,
			@guid				='45b7f584-70ae-4d17-981d-392a3b8c75e9',
			@ctct_origin		= 'a'
	*/
	-- -------------------------------------------------------------------



	declare	@ID					int


	/* obtenemos todas las transacciones que tienen pagos a cuenta pendientes*/
	declare cursor_CTT_dAD_data CURSOR LOCAL FAST_FORWARD FOR
	select	ct.[ctct_transaction]
		from	dbo.[tbCommercialTransactionsTmp]		ct	WITH (NOLOCK)
		where	ct.[comp_id]		=	@comp_id
		and     ct.[ctct_guid]		=   @guid
		and	    ct.[ctct_origin]	=	@ctct_origin


	open cursor_CTT_dAD_data

	fetch cursor_CTT_dAD_data into @ID

	while @@FETCH_STATUS = 0
	begin

		exec dbo.[spCommercialTransactionsTmp_deleteData] @ID

		fetch cursor_CTT_dAD_data into @ID

	end

	close cursor_CTT_dAD_data
	deallocate cursor_CTT_dAD_data

END
GO






