CREATE  PROCEDURE [dbo].[spCommercialTransactionsTmp_deleteData]
(
		@ctct_transaction		int
)
AS

BEGIN

	set nocount on

	IF @ctct_transaction > 0
		BEGIN
			Delete	dbo.tbCommercialTransactionsTmp	WITH (ROWLOCK)
				where	ctct_transaction			= @ctct_transaction
		END
	ELSE
		BEGIN
			Delete	dbo.tbCommercialTransactionsTmp	WITH (ROWLOCK)
				WHERE ctl_id = ABS(@ctct_transaction)
		END

END





GO








