CREATE PROCEDURE [dbo].[spCommercialTransactionsTmp_getDataById]
(
	@comp_id			int,
	@bra_id				int,
	@guid				uniqueidentifier,
	@currExchange		decimal(19,6),
	@ct_transaction		int
)
as

BEGIN


	set nocount on

	-- -----------------------------------------------
	-- -----------------------------------------------
	/*
	declare @comp_id			int,
			@bra_id				int,
			@guid				uniqueidentifier,
			@currExchange		decimal(19,6),
			@ct_transaction		int

	select  @comp_id			=	1,
			@bra_id				=	1,
			@guid				=	'29f7dee9-0d1f-4dcc-84e2-b44bcde4a025',
			@currExchange		=	1,
			@ct_transaction		=	-103
	*/
	-- -----------------------------------------------


	IF @ct_transaction > 0
		BEGIN
			select	isnull(ctct.ctct_total,0)						[ctct_total],
					isnull(ct.ct_ABalance,0)						[ct_ABalance],
					dbo.[fnGetExchange](	@comp_id,
											ct.[ct_ABalance],
											ct.ct_ACurrency,
											ct.curr_id_transaction,
											ct.ct_ACurrency,
											@currExchange, 0)		[ct_Balance]
				from	dbo.tbCommercialTransactions							ct		WITH (NOLOCK)
				left join dbo.tbCommercialTransactionsTmp						ctct	WITH (NOLOCK)
				on	ctct.[comp_id]			= ct.[comp_id]
					--and	ctct.[bra_id]			= ct.[bra_id]
					and ctct.ctct_transaction	= ct.ct_transaction
					and	ctct.[ctct_guid]		= @guid
					--and ctct.ctct_transaction	= ct.ct_transaction		-- MOS 03-2022, estaba DUPLICADO arriba
				where	ct.[comp_id]				= @comp_id
				and		ct.ct_transaction			= @ct_transaction
		END
	ELSE	-- CUOTAS
		BEGIN


			SET @ct_transaction = ABS(@ct_transaction)

			select	isnull(ctct.ctct_total,0)						[ctct_total],
					isnull(tctl.ct_ABalance,0)						[ct_ABalance],
					dbo.[fnGetExchange](	@comp_id,
											tctl.[ct_ABalance],
											ct.ct_ACurrency,
											ct.curr_id_transaction,
											ct.ct_ACurrency,
											@currExchange, 0)		[ct_Balance]

				FROM tbCommercialTransactionsLoan tctl									WITH (NOLOCK)
				inner join dbo.tbCommercialTransactions							ct		WITH (NOLOCK)
					ON	ct.comp_id			= tctl.comp_id AND
						ct.ct_transaction	= tctl.ct_transaction
				left join dbo.tbCommercialTransactionsTmp				ctct			WITH (NOLOCK)
					on	ctct.[comp_id]			= ct.[comp_id]
					and ctct.ctct_transaction	= ct.ct_transaction
					and	ctct.[ctct_guid]		= @guid

			where	tctl.[comp_id]				= @comp_id	AND
					tctl.ctl_id					= @ct_transaction		-- abs(@ct_transaction)   MOS 03-2022

		END

END
GO



CREATE PROCEDURE [dbo].[spCommercialTransactionsTmp_insertAllData]
(
	@comp_id			int,
	@bra_id				int,
	@cust_id			int,
	@curr_id			int,
	@currExchange		decimal(19,6),
	@guid				uniqueidentifier,
	@ctct_origin		CHAR(1),
	@fun_id				CHAR(1)
)
as

BEGIN



	set nocount ON

	-- ---------------------------------------------------------------------
	-- ---------------------------------------------------------------------
	/*
	declare	@comp_id			int,
			@bra_id				int,
			@cust_id			int,
			@curr_id			int,
			@currExchange		decimal(19,6),
			@guid				uniqueidentifier,
			@ctct_origin		char(1),
			@fun_id				CHAR(1)

	select	@comp_id			=1,
			@bra_id				=1,
			@cust_id			=8103,
			@curr_id			=1,
			@currExchange		=1,
			@guid				='45b7f584-70ae-4d17-981d-392a3b8c75e8',
			@ctct_origin		='a',
			@fun_id				='8'
	*/
	-- ---------------------------------------------------------------------




	declare @d int
	set @d = 2


	declare	@ct_balance			decimal(19,2),
			@ID					int,
			@return_value		INT,
			@ct_ABalance		DECIMAL(19,4)


	--BEGIN TRY


	/* obtenemos todas las transacciones que tienen pagos a cuenta pendientes*/
	declare cursor_CTT_iAD_data CURSOR LOCAL  FAST_FORWARD for
	select	round(dbo.[fnGetExchange](@comp_id, ct.[ct_ABalance], ct.ct_ACurrency, ct.curr_id_transaction, 0, @currExchange, 0),@d)
									[ct_Balance],
			ct.[ct_transaction]		[ID],
			ct.ct_ABalance			[ct_ABalance]
		from	dbo.tbCommercialTransactions								ct
		inner join dbo.[vwCommercialTransactions_PaymentOnAccount]	VCTFS	WITH (NOLOCK)
			On	VCTFS.comp_id					=	ct.comp_id
			and VCTFS.ct_transaction			=	ct.ct_transaction
		inner join	[tbBranch]										b1	WITH (NOLOCK)
			on	b1.[comp_id]					=	ct.[comp_id]
			and b1.[bra_id]						=	@bra_id
		INNER JOIN tbbranch												b2				WITH (NOLOCK)
			ON	b2.comp_id				= ct.comp_id AND
				b2.bra_id				= ct.bra_id
		where	ct.[comp_id]						=	@comp_id
		and	    (
					(@fun_id=1 and ct.[cust_id]		=	@cust_id)
						OR
					(@fun_id = 8 and ct.supp_id		=	@cust_id)
				)
		and		ct.[curr_id_transaction]			=   b1.curr_id
		and     ct.[ct_Abalance]					<>	0
		and		ct.[ct_docNumber]					<>	''
		and
			(
				(	@fun_id = 1 AND
					((b1.bra_CollectionOfAllBranches	=	'True'
						-- QUe HDPPPP!!!!!!
					and ct.bra_id in (select bra_id from [tbBranch] WITH (NOLOCK) WHERE curr_id = @curr_id)) or
					(b1.bra_CollectionOfAllBranches		=	'False'
					and ct.bra_id						=	@bra_id))
				)
				OR
				(	@fun_id = 8 AND
					(
						(	b1.bra_PaymentsOfAllBranches	=	'True'		AND
							b2.curr_id						= @curr_id
						)
						OR
						(
								b1.bra_PaymentsOfAllBranches		=	'False'		AND
								ct.bra_id							=	@bra_id
						)
					)
				)


			)


	open cursor_CTT_iAD_data

	fetch cursor_CTT_iAD_data into @ct_balance, @ID,@ct_ABalance

	while @@FETCH_STATUS = 0
	begin

		if exists (	SELECT TOP 1	1
						from	dbo.tbCommercialTransactionsTmp		WITH (NOLOCK)
						where	comp_id				= @comp_id	AND
								ctct_transaction	= @ID		AND
								ctct_origin			= @ctct_origin)
		begin

			delete	dbo.tbCommercialTransactionsTmp
				where	comp_id				= @comp_id	AND
						ctct_transaction	= @ID		AND
						ctct_origin			= @ctct_origin

		end


		exec dbo.[spCommercialTransactionsTmp_insertData]
				@comp_id,			@bra_id,
				@guid,				@ID,
				/*@ct_balance*/
				@ct_ABalance			-- MOS: 02-2020
				,		@ctct_origin,
				@currExchange,		@return_value

		fetch cursor_CTT_iAD_data into @ct_balance, @ID,@ct_ABalance

	end

	close cursor_CTT_iAD_data
	deallocate cursor_CTT_iAD_data

END


GO


CREATE  PROCEDURE dbo.spCommercialTransactionsTmp_insertData
(
	@comp_id			int,
	@bra_id				int,
	@ctct_guid			uniqueidentifier,
	@ctct_transaction	int,
	@ctct_total			decimal(19,5),
	@ctct_origin		char(1),
	@ctct_exchange		decimal(19,5),
	@return_value		int output
)
AS

BEGIN



	set nocount on

	-- -----------------------------------------------------
	-- Test
	-- -----------------------------------------------------
	/*
		declare
			@comp_id			int = 1,
			@bra_id				int = 1,
			@ctct_guid			uniqueidentifier = '277BE2BE-FFD8-497F-B56F-3889EE7BA48F',
			@ctct_transaction	int = 1798933,
			@ctct_total			decimal(19,5) = 12,
			@ctct_origin		char(1) = 'h',
			@ctct_exchange		decimal(19,5) = 1,
			@return_value		int  = 0
	*/
	-- -----------------------------------------------------



	DECLARE @intCTTransaction4OriginalDocument AS INT
	SET		@intCTTransaction4OriginalDocument	= ABS(@ctct_transaction)
	DECLARE @intQuoteNumberRelated			  AS INT
	--SET		@intQuoteNumberRelated				= -1

	DECLARE @intCTTransaction	AS INT
	SET		@intCTTransaction = @ctct_transaction

	DECLARE @intCTL_Id			AS INT
	SET		@intCTL_Id		  = NULL

	IF @intCTTransaction < 0	-- Si viene informado un ctl_id ya que es negativo bucca la transaccion original
		BEGIN

			-- Una CUOTA
			SET		@intCTL_Id							= ABS( @intCTTransaction )

			SELECT	@intCTTransaction					= tctl.ct_transaction,
					@intCTTransaction4OriginalDocument	= tctl.ct_transaction,
					@intQuoteNumberRelated				= tctl.ctl_payNumber
				FROM tbCommercialTransactionsLoan tctl		WITH (NOLOCK)
				WHERE	tctl.comp_id		= @comp_id AND
						tctl.ctl_id			= @intCTL_Id

			DELETE FROM tbCommercialTransactionsTmp	--WITH (ROWLOCK)
				WHERE	comp_id = @comp_id AND
						ctl_id	= @intCTL_Id

		END
	ELSE
		BEGIN
			-- Un COMPROBANTE COMPLETO
			if exists (	SELECT TOP 1	1
							from	dbo.tbCommercialTransactionsTmp		WITH (NOLOCK)
							where	comp_id				= @comp_id			AND
									ctct_transaction	= @intCTTransaction	AND
									ctct_origin			= @ctct_origin)
				begin

					delete	dbo.tbCommercialTransactionsTmp	--WITH (ROWLOCK)
						where	comp_id				= @comp_id				AND
								ctct_transaction	= @intCTTransaction		AND
								ctct_origin			= @ctct_origin
				end
		END

	IF @ctct_total <> 0
		BEGIN

			insert into dbo.tbCommercialTransactionsTmp
			( comp_id,	bra_id,	 ctct_guid,  ctct_transaction,  ctct_total,  ctct_origin,	ctct_exchange,	ctl_id)

			values
			( @comp_id, @bra_id, @ctct_guid, @intCTTransaction, @ctct_total, @ctct_origin,	@ctct_exchange, @intCTL_Id)

		END

	set @return_value = 0



	-- ----------------------------------------
	-- Si tiene un articulo de ML intenta
	-- cargar el pago correspondiente
	-- ----------------------------------------
	DECLARE @mlo_id AS INT = -1
	SELECT  @mlo_id = MAX(ISNULL(tct.mlo_id,-1))
		FROM tbItemTransactions tct		WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @intCTTransaction

	IF ISNULL(@mlo_id,-1) > 0
		BEGIN
			EXEC spCreditCardMovementsTMP_InsertDataFromSaleOrderCreditCardsByCT_TRANSACTION @comp_id, @intCTTransaction, @ctct_guid
		END
	-- ----------------------------------------


	-- ----------------------------------------
	-- Verifica si esta relacionado o no
	-- ----------------------------------------

	DECLARE @intCTTransactionRelated AS INT
	SELECT	@intCTTransactionRelated =	CASE
											WHEN tr.ct_transaction_1 = @intCTTransaction4OriginalDocument THEN tr.ct_transaction_2
											WHEN tr.ct_transaction_2 = @intCTTransaction4OriginalDocument THEN tr.ct_transaction_1
											ELSE											  NULL
										END
		FROM tbCommercialTransactions_Relations tr	WITH (NOLOCK)
		WHERE tr.comp_id = @comp_id AND
			 (
			  tr.ct_transaction_1 = @intCTTransaction4OriginalDocument
				OR
			  tr.ct_transaction_2 = @intCTTransaction4OriginalDocument
			 )	AND
			 tr.class = 2 -- Financiacon de Terceros.



	-- Creo que no va, era para que marque el comprobane y el relacionado tipo fc y nd a la vez (vta 3ros)
	--IF @intCTTransactionRelated IS NOT NULL AND ISNULL(@intQuoteNumberRelated,0) > 0  -- AND 1 = 2 --  1 = 2   no se porque estaba esto, MOS 02-2017, lo saque...
	--	BEGIN

	--		insert into dbo.tbCommercialTransactionsTmp
	--		(	comp_id,
	--			bra_id,
	--			ctct_guid,
	--			ctct_transaction,
	--			ctct_total,
	--			ctct_origin,
	--			ctct_exchange,
	--			ctl_id)

	--		SELECT	tct.comp_id,
	--				@bra_id,
	--				@ctct_guid,
	--				@intCTTransactionRelated,
	--				CASE
	--					WHEN tctl.comp_id IS NULL THEN	tct.ct_ABalance
	--					ELSE							tctl.ct_ABalance
	--				END,
	--				@ctct_origin,
	--				@ctct_exchange,
	--				tctl.ctl_id
	--			FROM tbCommercialTransactions tct			WITH (NOLOCK)
	--			LEFT JOIN tbCommercialTransactionsLoan tctl
	--				ON	tctl.comp_id		= @comp_id AND
	--					tctl.ct_transaction = @intCTTransactionRelated AND
	--					tctl.ctl_payNumber	= @intQuoteNumberRelated
	--			WHERE	tct.comp_id			= @comp_id AND
	--					tct.ct_transaction	= @intCTTransactionRelated




	--	END
	-- ----------------------------------------


END
GO


