	@comp_id	INT,
	@commc_id	INT,
	@item_id	INT,
	@item_code	NVARCHAR(50)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@commc_id	INT,
				@item_id	INT,
				@item_code	NVARCHAR(50)
		*/
		-- --------------------------------------------

		IF NOT EXISTS (	SELECT 1
					FROM tbCommunity_ClientItemRelations AS tccir
	               	WHERE	tccir.comp_id	= @comp_id AND
	               			tccir.commc_id	= @commc_id AND
	               			tccir.item_id	= @item_id AND
	               			tccir.item_Code = @item_code)
		BEGIN
			INSERT INTO tbCommunity_ClientItemRelations
			(
				comp_id,
				commc_id,
				item_id,
				item_Code,
				commdr_disabled
			)
			VALUES
			(
				@comp_id,
				@commc_id,
				@item_id,
				@item_code,
				'False'
			)
		END
	END
GO

