CREATE PROCEDURE [dbo].[spCommunity_ClientItemsAvailable_GetDataByFilters]
(
	@comp_id	INT,
	@commc_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------
		-- TESTING
		-- -------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@commc_id	INT
		*/
		-- -------------------------------

		SELECT
			' '										[ ],
			tccia.item_code,
			ti.item_Code							[item_code_related],
			tccia.cat_desc,
			tccia.subcat_desc,
			tccia.item_desc,
			tccia.item_priceNoTaxIncluded,
			tccia.item_availableStock,
