			FROM tbCommunity_ClientItemsAvailable		AS tccia	WITH(NOLOCK)
			LEFT JOIN tbCommunity_ClientItemRelations	AS tccir	WITH(NOLOCK)
			ON	tccir.comp_id		= tccia.comp_id		AND
				tccir.item_code		= tccia.item_code
			LEFT JOIN tbItem							AS ti		WITH(NOLOCK)
			ON	ti.comp_id			= tccir.comp_id		AND
				ti.item_id			= tccir.item_id
			WHERE	tccia.comp_id	= @comp_id			AND
					tccia.commc_id	= @commc_id

	END



