CREATE PROCEDURE [dbo].[spCommunity_getItemDataAndPriceAndStorageData]
(
	@community_id	UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@community_id	UNIQUEIDENTIFIER
			SELECT
				@community_id	= '0F580582-2DB1-4322-B1D6-A897BE153CE8'
		*/
		-- ----------------------------------------------

		DECLARE
			@lstor_id			INT,
			@lprli_id			INT,
			@stockPercentaje	DECIMAL(19,2),
			@comm_id			INT,
			@comp_id			INT
		--Recupero los datos del server
		SELECT TOP 1												-- Si hay MAS de una compañia y tienen el MISMO CommunityID como servidor en las dos, SOLO va a retornar la primera.
			@lprli_id			= tcsc.prli_id,
			@lstor_id			= tcsc.stor_id,
			@stockPercentaje	= tcsc.comm_stockPercentage,
			@comm_id			= tcsc.comm_id,
			@comp_id			= tcsc.comp_id
		FROM tbCommunity_ServerConfiguration		AS tcsc		WITH (NOLOCK)
		WHERE	--tcsc.comp_id		= @comp_id		AND
				tcsc.community_id	= @community_id AND
				tcsc.comm_disabled	= 'False'



		-- ----------------------------------------------------
		-- Tiene el Modulo ?
		-- ----------------------------------------------------
		DECLARE @guidCOMPAM AS NVARCHAR(500)
		DECLARE @compGUID	AS UNIQUEIDENTIFIER
		SELECT
				@compGUID	= tc.comp_guid,
				@guidCOMPAM = tc.comp_am
			FROM tbCompany tc		WITH (NOLOCK)
			WHERE tc.comp_id = @comp_id

		DECLARE @bitAcquiredModule AS BIT = 'False'
		BEGIN TRY
			IF dbo.clrGetAM(@comp_id,100, @guidCOMPAM , CONVERT(NVARCHAR(50), @compGUID)) = 1    -- Requiere Exportacion Personalizada para poder ejecutarse.
				BEGIN
					SET @bitAcquiredModule = 'True'
				END
		END TRY
		BEGIN CATCH
		END CATCH
		-- ----------------------------------------------------






		SELECT
			CONVERT(VARCHAR(50), ti.item_code)		[item_code],
			CONVERT(VARCHAR(50),tc.cat_desc)		[cat_desc],
			CONVERT(VARCHAR(50),tsc.subcat_desc)	[subcat_desc],
			CONVERT(VARCHAR(100), ti.item_desc)		[item_desc],
			CASE
				WHEN	tis.comp_id IS NULL										THEN    0
				WHEN	tcb.comm_stockByLastCalculated			= 'True'	AND
						ts.stor_mustRecalculateAvailableStock	= 'True'	AND
						tis.itst_cant IS NOT NULL								THEN	tis.itst_LastAvailableInRelalculation
				ELSE																	dbo.fnGetAStock4MaxAssociation(ti.comp_id, @lstor_id, ti.item_id,9999999999) * (@stockPercentaje / 100)
			END																										[Stock],
			ISNULL(tpli.prli_price,0)																				[Price],
			ISNULL(tpli.curr_id,0)																					[curr_id],
			CASE
				WHEN tpli.comp_id IS NULL THEN 'False'
				ELSE 'True'
			END												[isPriceAvailable],
			CASE
				WHEN tis.comp_id  IS NULL THEN 'False'
				ELSE 'True'
			END												[isStorageAvailable]
		FROM tbItem									AS ti		WITH (NOLOCK)
		INNER JOIN tbCategory						AS tc		WITH(NOLOCK)
		ON	tc.comp_id		= ti.comp_id			AND
			tc.cat_id		= ti.cat_id
		INNER JOIN tbSubCategory					AS tsc		WITH(NOLOCK)
		ON	tsc.comp_id		= ti.comp_id			AND
			tsc.cat_id		= ti.cat_id				AND
			tsc.subcat_id	= ti.subcat_id
		INNER JOIN tbCommunity_ServerConfiguration	AS tcb		WITH (NOLOCK)
			ON	tcb.comp_id = @comp_id AND
				tcb.comm_id = @comm_id
		INNER JOIN vwCommunity_ItemsData			AS vcid		WITH (NOLOCK)
			ON	vcid.comp_id	= ti.comp_id		AND
				vcid.item_id	= ti.item_id
		LEFT JOIN tbStorage							AS ts		WITH (NOLOCK)
			ON	ts.comp_id	= @comp_id				AND
				ts.stor_id	= @lstor_id
		LEFT JOIN tbItemStorage						AS tis		WITH (NOLOCK)
			ON	tis.comp_id		= ti.comp_id		AND
				tis.item_id		= ti.item_id		AND
				tis.stor_id		= @lstor_id
		LEFT JOIN tbPriceListItems					AS tpli		WITH (NOLOCK)
			ON	tpli.comp_id	= ti.comp_id		AND
				tpli.item_id	= ti.item_id		AND
				tpli.prli_id	= @lprli_id
		WHERE	ti.comp_id			= @comp_id AND
				@bitAcquiredModule	= 'True'



	END


GO


CREATE PROCEDURE [dbo].[spCommunity_getPriceAndStorageData]
(
	@community_id	UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@community_id	UNIQUEIDENTIFIER
			SELECT
				@community_id	= '0F580582-2DB1-4322-B1D6-A897BE153CE8'
		*/
		-- ----------------------------------------------

		DECLARE
			@lstor_id			INT,
			@lprli_id			INT,
			@stockPercentaje	DECIMAL(19,2),
			@comm_id			INT,
			@comp_id			INT
		--Recupero los datos del server
		SELECT TOP 1												-- Si hay MAS de una compañia y tienen el MISMO CommunityID como servidor en las dos, SOLO va a retornar la primera.
			@lprli_id			= tcsc.prli_id,
			@lstor_id			= tcsc.stor_id,
			@stockPercentaje	= tcsc.comm_stockPercentage,
			@comm_id			= tcsc.comm_id,
			@comp_id			= tcsc.comp_id
		FROM tbCommunity_ServerConfiguration		AS tcsc		WITH (NOLOCK)
		WHERE	--tcsc.comp_id		= @comp_id		AND
				tcsc.community_id	= @community_id AND
				tcsc.comm_disabled	= 'False'



		-- ----------------------------------------------------
		-- Tiene el Modulo ?
		-- ----------------------------------------------------
		DECLARE @guidCOMPAM AS NVARCHAR(500)
		DECLARE @compGUID	AS UNIQUEIDENTIFIER
		SELECT
				@compGUID	= tc.comp_guid,
				@guidCOMPAM = tc.comp_am
			FROM tbCompany tc		WITH (NOLOCK)
			WHERE tc.comp_id = @comp_id

		DECLARE @bitAcquiredModule AS BIT = 'False'
		BEGIN TRY
			IF dbo.clrGetAM(@comp_id,100, @guidCOMPAM , CONVERT(NVARCHAR(50), @compGUID)) = 1    -- Requiere Exportacion Personalizada para poder ejecutarse.
				BEGIN
					SET @bitAcquiredModule = 'True'
				END
		END TRY
		BEGIN CATCH
		END CATCH
		-- ----------------------------------------------------






		SELECT
			ti.item_code																							[item_code],
			CASE
				WHEN	tis.comp_id IS NULL										THEN    0
				WHEN	tcb.comm_stockByLastCalculated			= 'True'	AND
						ts.stor_mustRecalculateAvailableStock	= 'True'	AND
						tis.itst_cant IS NOT NULL								THEN	tis.itst_LastAvailableInRelalculation
				ELSE																	dbo.fnGetAStock4MaxAssociation(ti.comp_id, @lstor_id, ti.item_id,9999999999) * (@stockPercentaje / 100)
			END																										[Stock],
			ISNULL(tpli.prli_price,0)																				[Price],
			ISNULL(tpli.curr_id,0)																					[curr_id],
			CASE
				WHEN tpli.comp_id IS NULL THEN 'False'
				ELSE 'True'
			END												[isPriceAvailable],
			CASE
				WHEN tis.comp_id  IS NULL THEN 'False'
				ELSE 'True'
			END												[isStorageAvailable]
		FROM tbItem							AS ti		WITH (NOLOCK)
		INNER JOIN tbCommunity_ServerConfiguration tcb  WITH (NOLOCK)
			ON	tcb.comp_id = @comp_id AND
				tcb.comm_id = @comm_id
		INNER JOIN vwCommunity_ItemsData	AS vcid		WITH (NOLOCK)
			ON	vcid.comp_id	= ti.comp_id	AND
				vcid.item_id	= ti.item_id
		LEFT JOIN tbStorage AS ts						WITH (NOLOCK)
			ON	ts.comp_id	= @comp_id AND
				ts.stor_id	= @lstor_id
		LEFT JOIN tbItemStorage				AS tis		WITH (NOLOCK)
			ON	tis.comp_id		= ti.comp_id	AND
				tis.item_id		= ti.item_id	AND
				tis.stor_id		= @lstor_id
		LEFT JOIN tbPriceListItems			AS tpli		WITH (NOLOCK)
			ON	tpli.comp_id	= ti.comp_id	AND
				tpli.item_id	= ti.item_id	AND
				tpli.prli_id	= @lprli_id
		WHERE	ti.comp_id			= @comp_id AND
				@bitAcquiredModule	= 'True'



	END


GO

CREATE PROCEDURE spCommunity_UpdatePriceAndStock
(
	@comp_id				INT,
	@community_id			UNIQUEIDENTIFIER,
	@commc_id				INT,
	@coslis_id				INT,
	@stor_id				INT,
	@stockPercentaje		DECIMAL(19,2),
	@item_code				NVARCHAR(50),
	@decprice				DECIMAL(19,5),
	@curr_id				INT,
	@intStorQty				INT,
	@bitIsPriceAvailable	BIT,
	@bitIsStorageAvailable	BIT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@community_id			UNIQUEIDENTIFIER,
				@commc_id				INT,
				@coslis_id				INT,
				@stor_id				INT,
				@stockPercentaje		INT,
				@item_code				NVARCHAR(50),
				@decprice				DECIMAL(19,5),
				@intStorQty				INT,
				@bitIsPriceAvailable	BIT,
				@bitIsStorageAvailable	BIT
		*/
		-- ---------------------------------------------------


		--RECUPERO EL ARTICULO ASOCIADO EN MI SISTEMA
		DECLARE
			@litem_id			INT

		SELECT
			@litem_id = tccir.item_id
		FROM tbCommunity_ClientItemRelations			AS tccir
		WHERE	tccir.item_Code			= @item_code	AND
				tccir.commc_id			= @commc_id		AND
				tccir.commdr_disabled	= 'False'

		IF @bitIsPriceAvailable = 'True'
			BEGIN
				-- SI ESTA EL PRECIO DISPONIBLE, CREO O ACTUALIZO EL ARTICULO
				IF NOT EXISTS (SELECT 1 FROM tbItemCostList AS ticl WHERE ticl.comp_id = @comp_id AND ticl.coslis_id = @coslis_id AND ticl.item_id = @litem_id)
					BEGIN
						INSERT INTO tbItemCostList
						(
							comp_id,
							coslis_id,
							item_id,
							coslis_price,
							curr_id
						)
						VALUES
						(
							@comp_id,
							@coslis_id,
							@litem_id,
							@decprice,
							@curr_id
						)
					END
				ELSE
					BEGIN
						UPDATE tbItemCostList
						SET
							coslis_price	= @decprice
						WHERE	comp_id		= @comp_id		AND
								coslis_id	= @coslis_id	AND
								item_id		= @litem_id

					END
			END


		IF @bitIsStorageAvailable = 'True'
			BEGIN
				--CON EL ARTICULO RECUPERADO CREO O ACTUALIZO EL DEPOSITO
				IF NOT EXISTS(SELECT 1 FROM tbItemStorage AS tis WHERE tis.comp_id = @comp_id AND tis.stor_id = @stor_id AND tis.item_id = @litem_id)
					BEGIN
						INSERT INTO tbItemStorage
						(
							comp_id,
							stor_id,
							item_id,
							itst_cant
						)
						VALUES
						(
							@comp_id,
							@stor_id,
							@litem_id,
							@intStorQty * (@stockPercentaje / 100)
						)
					END
				ELSE
					BEGIN
						UPDATE tbItemStorage
						SET
							itst_cant	= @intStorQty * (@stockPercentaje / 100)
						WHERE	comp_id = @comp_id AND
								stor_id = @stor_id AND
								item_id = @litem_id
					END
			END

	END

GO







