CREATE PROCEDURE [dbo].[spCompany_getDataById]
(
	@comp_id			int
)
AS

BEGIN

	set nocount on


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------

	/*
	declare	@comp_id		int
	select 	@comp_id		=1
	*/

	-- -----------------------------------------------------------------------------


	--DECLARE @bolHasMercadoLibreStores AS BIT = 'False'
	--SELECT  @bolHasMercadoLibreStores = 'True'
	--	FROM tbMercadoLibre_Stores tmls  WITH (NOLOCK)
	--	WHERE	tmls.comp_id		= @comp_id AND
	--			tmls.mls_disabled	='False'


	select	comp_id,
			comp_desc,
			comp_cd,
			org_id,
			dbo.tbCompany.curr_id,
			comp_MainDesc1,
			comp_MainDesc2,
			comp_Logo,
			tc.curr_desc,
			IsNull(comp_IISUserName,'')			[comp_IISUserName],
			IsNull(comp_IISPassword,'')			[comp_IISPassword],
			smtp_host,
			smtp_port,
			smtp_ssc,
			smtp_ValidationRequired,
			smtp_user,
			smtp_password,
			isnull(sevt_id,1)												[sevt_id], --1: es la versión default
            IsNull(comp_ServerFULLURL2Acces,'')								[comp_ServerFULLURL2Acces],
            ISNULL(comp_ServerFULLURL2RemoteAccess,'')						[comp_ServerFULLURL2RemoteAccess],
            IsNull(comp_hideDecimalsOnStock,'False')						[comp_hideDecimalsOnStock],
            ISNULL(comp_guid,NULL)											[comp_guid],
            ISNULL(comp_am,'')												[comp_am],
            ISNULL(lang_id,1)												[lang_id],
            ISNULL( comp_customer_disableStateForced2Select,'False')
																			[comp_customer_disableStateForced2Select],
			ISNULL(comp_disableImagePNGControl,'False')						[comp_disableImagePNGControl],
			ISNULL(comp_ServerFULLURL4wfmMercadolibre_processQueueExec,'')	[comp_ServerFULLURL4wfmMercadolibre_processQueueExec],
			ISNULL(comp_imageFormat,1)										[comp_imageFormat],
			ISNULL(comp_IE7Compatible,'False')							AS	comp_IE7Compatible,
			ISNULL(comp_DolarUpdate_integerValue,'False')					[comp_DolarUpdate_integerValue],
			ISNULL(comp_EuroUpdate_integerValue,'False')					[comp_EuroUpdate_integerValue]	,
			ISNULL(comp_chatGPT_APIKey,'')									[comp_chatGPT_APIKey]
			from	dbo.tbCompany							WITH (NOLOCK)
			INNER JOIN tbsysCurrency tc						WITH (NOLOCK)
				ON tc.curr_id = dbo.tbCompany.curr_id

		where	comp_id		=	@comp_id
		OPTION ( MAXDOP 1 )

END
GO









