CREATE PROCEDURE [dbo].[spCompany_getMailData]
(
	@comp_id		INT,
	@user_id		INT,
	@strReplyTo		NVARCHAR(2000)
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON

	-- -------------------------------------------
	-- Testing
	-- -------------------------------------------
	/*
	DECLARE	@comp_id		INT,
			@user_id		INT
	SELECT	@comp_id		=	1,
			@user_id		=	1
	*/
	-- -------------------------------------------


	SET @strReplyTo = dbo.fnStrAllTrim(@strReplyTo)

	IF @strReplyTo = ''
		BEGIN
			SELECT @strReplyTo		= dbo.fnStrAllTrim( IsNull(tu.user_email,'') )
				FROM tbUser tu		WITH (NOLOCK)
				WHERE tu.[user_id]	= @user_id
		END

	IF @strReplyTo = ''
		BEGIN
			SELECT @strReplyTo		= dbo.fnStrAllTrim( tc.smtp_defaultReply )
				FROM tbCompany tc	WITH (NOLOCK)
				WHERE tc.comp_id	= @comp_id
		END


	-- ------------------------------------------------------------------------------------------
	-- ATENCIÓN, si se modifica algo hacerlo en [spCompany_getMailData] y en [spSystem_sendEMail]
	-- Por si sale un mail de respuesta desde un dominio diferente y el server smtp lo bloquea
	-- ------------------------------------------------------------------------------------------
	-- Busca un EMAIL email@midominio.com
	IF EXISTS(
				SELECT 1
					FROM tbSMTPConfigurationByReplyTo tsbrt	WITH (NOLOCK)
					WHERE	tsbrt.comp_id		= @comp_id AND
							tsbrt.smtp_ReplyTo	= @strReplyTo
				)
		BEGIN

			SELECT	tc.comp_desc,
					tsbrt.smtp_host,
					tsbrt.smtp_port,
					tsbrt.smtp_ssc,
					tsbrt.smtp_user,
					tsbrt.smtp_password,
					tsbrt.smtp_ValidationRequired,
					tu.user_email								[from],
					tu.user_lastname + ',' + tu.user_firstname	[user_name],
					'True'										[IsFromReplyToConfig],
					ISNULL(tc.lang_id,1)						[lang_id],
					tsbrt.smtp_id								[smtp_id]
				FROM tbSMTPConfigurationByReplyTo	tsbrt	WITH (NOLOCK)
				INNER JOIN tbCompany				tc		WITH (NOLOCK)
					ON tc.comp_id = tsbrt.comp_id
				LEFT  JOIN tbUser					tu		WITH (NOLOCK)
					ON tu.[user_id] = @user_id
				WHERE	tsbrt.comp_id		= @comp_id AND
						tsbrt.smtp_ReplyTo	= @strReplyTo

		END
	-- ------------------------------------------------------------------------------------------

	-- Busca un Dominio @midominio.com
	ELSE 	IF EXISTS(
				SELECT TOP 1 1
					FROM tbSMTPConfigurationByReplyTo tsbrt	WITH (NOLOCK)
					WHERE	tsbrt.comp_id		= @comp_id AND
							@strReplyTo	LIKE '%' + REPLACE(tsbrt.smtp_ReplyTo,'*','') + '%'
				)
		BEGIN

			SELECT	tc.comp_desc,
					tsbrt.smtp_host,
					tsbrt.smtp_port,
					tsbrt.smtp_ssc,
					tsbrt.smtp_user,
					tsbrt.smtp_password,
					tsbrt.smtp_ValidationRequired,
					tu.user_email								[from],
					tu.user_lastname + ',' + tu.user_firstname	[user_name],
					'True'										[IsFromReplyToConfig],
					ISNULL(tc.lang_id,1)						[lang_id],
					tsbrt.smtp_id								[smtp_id]
				FROM tbSMTPConfigurationByReplyTo	tsbrt	WITH (NOLOCK)
				INNER JOIN tbCompany				tc		WITH (NOLOCK)
					ON tc.comp_id = tsbrt.comp_id
				LEFT  JOIN tbUser					tu		WITH (NOLOCK)
					ON tu.[user_id] = @user_id
				WHERE	tsbrt.comp_id		= @comp_id AND
						@strReplyTo	LIKE '%' + REPLACE(tsbrt.smtp_ReplyTo,'*','') + '%'

		END
	-- ------------------------------------------------------------------------------------------

	ELSE

		BEGIN

			SELECT	tc.comp_desc,
					tc.smtp_host,
					tc.smtp_port,
					tc.smtp_ssc,
					tc.smtp_user,
					tc.smtp_password,
					tc.smtp_ValidationRequired,
					tu.user_email								[from],
					tu.user_lastname + ',' + tu.user_firstname	[user_name],
					'False'										[IsFromReplyToConfig],
					ISNULL(tc.lang_id,1)						[lang_id],
					-1											[smtp_id]
				FROM	tbCompany									tc	WITH (NOLOCK)
						LEFT JOIN tbUser							tu	WITH (NOLOCK)
						ON		tu.[user_id]	=	@user_id
				WHERE	tc.comp_id				=	@comp_id

		END

END
GO


