CREATE PROCEDURE [dbo].[spCompany_UpdateAM]
(
	@comp_id	INT,
	@comp_am	NVARCHAR(4000)
)
AS
	BEGIN
		SET NOCOUNT ON
		UPDATE tbCompany
		SET
			comp_am		= @comp_am
		WHERE comp_id	= @comp_id
	END
GO



