-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spCompanyBranchProfileMenuEnabled]
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@menu_id	INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.

	SET NOCOUNT ON;

	DECLARE @bolIsMenuEnabled AS BIT
	SET		@bolIsMenuEnabled = 'False'

	SELECT @bolIsMenuEnabled = 'True'
		FROM tbUserCompanyProfile tucp		WITH (NOLOCK)
		INNER JOIN tbMenuGrants tmg			WITH (NOLOCK)
			ON	tmg.comp_id = tucp.comp_id	AND
				tmg.prof_id = tucp.prof_id	AND
				tmg.menu_id = @menu_Id
	WHERE	tucp.comp_id	= @comp_id		AND
			tucp.bra_id		= @bra_id		AND
			tucp.[user_id]	= @user_id		AND
			tucp.prof_id	= @prof_id

	SELECT @bolIsMenuEnabled [bolIsMenuEnabled]


END
GO






