-- Author:		GA
-- Create date: 15-08-2014
-- Description:	Filtro de Clientes por Clientes para el ComplexFilter
-- ======================================================================

CREATE PROCEDURE [dbo].[spComplexFilter_Cust_SelCustomer]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@cust_id			INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------

/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@cust_id			INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@cust_id			='3',
			@bitAddInTable		='True'
*/


-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbCustomer
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemSelCust TABLE(cust_id INT PRIMARY KEY)
	IF @cust_id = '-1'
		BEGIN
			INSERT INTO @tmpItemSelCust (cust_id)	SELECT tc.cust_id
			                                     		FROM tbCustomer tc		WITH (NOLOCK)
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemSelCust (cust_id)	SELECT @cust_id
		END
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					tc.cust_id,
					0,
					@SelectAll
			FROM tbCustomer tc		WITH (NOLOCK)

				INNER JOIN @tmpItemSelCust tmp
					ON tmp.cust_id	= tc.cust_id
				LEFT JOIN tbComplexFilter tcf		WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= tc.cust_id
				WHERE	tc.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf		WITH (NOLOCK)
				INNER JOIN tbCustomer tc
				ON	tc.comp_id = @comp_id AND
					tc.cust_id = tcf.sl_id

				INNER JOIN @tmpItemSelCust tmp
				ON tmp.cust_id = tc.cust_id

				WHERE tcf.sl_guid = @guid
		END






END
GO




-- =========================================================
