-- Create date: 23-05-2014
-- Description:	Filtro de Actividad para Cliente
-- =========================================================

CREATE PROCEDURE [dbo].[spComplexFilter_Customer_Activity]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@act_id				INT,
	@bitAddInTable		BIT,
	@SelectAll			BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@act_id				INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@act_id				=2,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



BEGIN

	SET NOCOUNT ON;


	-- -------------------------------------------------------------------------------------
	-- FILTRO por Actividad
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpCustomerActivity TABLE(CustId INT PRIMARY KEY)
	IF @act_id = '-1'
		BEGIN
			INSERT INTO @tmpCustomerActivity (CustId)	SELECT tc.cust_id
			                                        		FROM tbCustomer tc		WITH (NOLOCK)
		END
	ELSE
		BEGIN
			INSERT INTO @tmpCustomerActivity (CustId)	SELECT tc.cust_id
			                                        		FROM tbCustomer tc		WITH (NOLOCK)
			                                        		WHERE	tc.comp_id		= @comp_id AND
			                                        				tc.act_id		= @act_id
		END
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					tc.cust_id,
					0,
					@SelectAll
			FROM tbCustomer tc		WITH (NOLOCK)
				INNER JOIN @tmpCustomerActivity tmp
					ON tmp.CustId	= tc.cust_id
				LEFT JOIN tbComplexFilter tcf 		WITH (NOLOCK)-- ****** es join con tbcomplexfilter STL TRAGA CHELE ******
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= tc.cust_id  -- ****** es cliente por ende con tc.cust_id . GIL :P ******
				WHERE	tc.comp_id	= @comp_id AND  -- ****** TS NO , TC.COMP_ID ******
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf		WITH (NOLOCK)
				INNER JOIN tbCustomer tc		WITH (NOLOCK)
					ON	tc.comp_id = @comp_id AND
						tc.cust_id = tcf.sl_id
				INNER JOIN @tmpCustomerActivity tmp
					ON tmp.CustId = tc.cust_id
				WHERE tcf.sl_guid = @guid
		END

END
GO




-- =========================================================
-- Author:		STL
-- Create date: 23-05-2014
-- Description:	Filtro de Domicilio para Cliente
-- =========================================================

CREATE PROCEDURE [dbo].[spComplexFilter_Customer_Address]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@option				INT,
	@cust_address		VARCHAR(150),
	@bitAddInTable		BIT,
	@SelectAll			BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@option				INT,
			@cust_address		VARCHAR(150),
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@option				=1,
			@cust_address		= 'asdasd',
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por Dirección
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpCustomerAddress TABLE(CustId INT PRIMARY KEY)
	IF (@option = '-1') AND (@cust_address = '')
		BEGIN
			INSERT INTO @tmpCustomerAddress (CustId)	SELECT tc.cust_id
			                                        		FROM tbCustomer tc		WITH (NOLOCK)
		END
	ELSE
		BEGIN
			INSERT INTO @tmpCustomerAddress (CustId)	SELECT tc.cust_id
			                                        		FROM tbCustomer tc		WITH (NOLOCK)
			                                        		WHERE (
																	--(@option = -1 )														OR
																	(@option = 0 AND tc.cust_address LIKE			  @cust_address + '%') OR
																	(@option = 1 AND tc.cust_address LIKE		'%' + @cust_address + '%') OR
																	(@option = 2 AND tc.cust_address =			      @cust_address)		OR
																	(@option = 3 AND tc.cust_address <>			      @cust_address)		OR
																	(@option = 4 AND tc.cust_address NOT LIKE   '%' + @cust_address + '%')
																  )
		END
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					tc.cust_id,
					0,
					@SelectAll
			FROM tbCustomer tc		WITH (NOLOCK)
				INNER JOIN @tmpCustomerAddress tmp
					ON tmp.CustId	= tc.cust_id
				LEFT JOIN tbComplexFilter tcf		WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= tc.cust_id
				WHERE	tc.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf		WITH (NOLOCK)
				INNER JOIN tbCustomer tc		WITH (NOLOCK)
					ON	tc.comp_id = @comp_id AND
						tc.cust_id = tcf.sl_id
				INNER JOIN @tmpCustomerAddress tmp
					ON tmp.CustId = tc.cust_id
				WHERE tcf.sl_guid = @guid
		END

END
GO




