-- =========================================================
-- Author:		GA
-- Create date: 23-08-2016
-- Description:	Filtro de Grupo de Sucursales para Cliente
-- =========================================================

CREATE PROCEDURE [dbo].[spComplexFilter_Customer_CD]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@option_cust_cd		INT,
	@cust_cd_from		DATETIME,
	@cust_cd_to			DATETIME,
	@bitAddInTable		BIT,
	@SelectAll			BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@brag_id				INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@brag_id				=2,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	set DATEFORMAT 'ymd'

	SET @cust_cd_from	= dbo.fnGetEnd_or_BeginOfDate(@cust_cd_from	,'false')
	SET @cust_cd_to		= dbo.fnGetEnd_or_BeginOfDate(@cust_cd_to	,'true')

	-- -------------------------------------------------------------------------------------
	-- FILTRO por fecha de alta
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpCustomerCD TABLE(CustId INT PRIMARY KEY)
	IF @option_cust_cd = '-1'
		BEGIN
			INSERT INTO @tmpCustomerCD (CustId)	SELECT tc.cust_id
			                                        		FROM tbCustomer tc		WITH (NOLOCK)
		END
	ELSE
		BEGIN
			INSERT INTO @tmpCustomerCD (CustId)	SELECT tc.cust_id
			                                        		FROM tbCustomer tc		WITH (NOLOCK)
			                                        		WHERE (
																	(@option_cust_cd = 0 AND tc.cust_cd =	@cust_cd_from ) OR
																	(@option_cust_cd = 1 AND tc.cust_cd >	@cust_cd_from) OR
																	(@option_cust_cd = 2 AND tc.cust_cd <	@cust_cd_from)	OR
																	(@option_cust_cd = 3 AND tc.cust_cd BETWEEN  @cust_cd_from AND @cust_cd_to)
																  )
		END
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					tc.cust_id,
					0,
					@SelectAll
			FROM tbCustomer tc		WITH (NOLOCK)
				INNER JOIN @tmpCustomerCD tmp
					ON tmp.CustId	= tc.cust_id
				LEFT JOIN tbComplexFilter tcf		WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= tc.cust_id
				WHERE	tc.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf		WITH (NOLOCK)
				INNER JOIN tbCustomer tc		WITH (NOLOCK)
					ON	tc.comp_id = @comp_id AND
						tc.cust_id = tcf.sl_id
				INNER JOIN @tmpCustomerCD tmp
					ON tmp.CustId = tc.cust_id
				WHERE tcf.sl_guid = @guid
		END

END
GO




-- =========================================================
-- Author:		STL
-- Create date: 23-05-2014
-- Description:	Filtro de Localidad para Cliente
-- =========================================================

CREATE PROCEDURE [dbo].[spComplexFilter_Customer_City]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@option				INT,
	@cust_city			VARCHAR(60),
	@bitAddInTable		BIT,
	@SelectAll			BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@option				INT,
			@cust_city			VARCHAR(60),
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@option				=1,
			@cust_city			= 'asdasd',
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por Localidad
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpCustomerCity TABLE(CustId INT PRIMARY KEY)
	IF (@option = '-1') AND (@cust_city = '')
		BEGIN
			INSERT INTO @tmpCustomerCity (CustId)	SELECT tc.cust_id
			                                        		FROM tbCustomer tc
		END
	ELSE
		BEGIN
			INSERT INTO @tmpCustomerCity (CustId)	SELECT tc.cust_id
			                                        		FROM tbCustomer tc
			                                        		WHERE (
																	--(@option = -1 )														OR
																	(@option = 0 AND tc.cust_city LIKE		       @cust_city + '%') OR
																	(@option = 1 AND tc.cust_city LIKE		 '%' + @cust_city + '%') OR
																	(@option = 2 AND tc.cust_city =			       @cust_city)		 OR
																	(@option = 3 AND tc.cust_city <>		 	   @cust_city)		 OR
																	(@option = 4 AND tc.cust_city NOT LIKE   '%' + @cust_city + '%')
																  )
		END
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					tc.cust_id,
					0,
					@SelectAll
			FROM tbCustomer tc
				INNER JOIN @tmpCustomerCity tmp
					ON tmp.CustId	= tc.cust_id
				LEFT JOIN tbComplexFilter tcf
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= tc.cust_id
				WHERE	tc.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf
				INNER JOIN tbCustomer tc
					ON	tc.comp_id = @comp_id AND
						tc.cust_id = tcf.sl_id
				INNER JOIN @tmpCustomerCity tmp
					ON tmp.CustId = tc.cust_id
				WHERE tcf.sl_guid = @guid
		END

END
GO




