CREATE PROCEDURE [dbo].[spComplexFilter_Customer_getData]
(
	@guid				uniqueidentifier
)
as

	BEGIN

	set nocount on

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	-------------------------------------------------------------------------
	/*
	declare	@guid				UNIQUEIDENTIFIER


	select	@guid				='6F6AE531-CA81-4E36-8CC7-C8ECFB7D38B4'
*/
    -------------------------------------------------------------------------


	select	' '							[X0 ] ,
			tcf.sl_selected				[Selected],
			' '							[X1] ,
			' '							[X2] ,
			' '							[X3] ,
			tc.cust_name				[cust_name],
			tc.cust_taxNumber			[cust_taxNumber],
			tc.cust_address				[cust_address],
			tc.cust_city				[cust_city],
			tcf.sl_id					[ID]

	from	dbo.tbComplexFilter			tcf				WITH (NOLOCK)

	LEFT JOIN tbCustomer				tc				WITH (NOLOCK)
	ON tcf.sl_id = tc.cust_id

	WHERE tcf.sl_guid				=	@guid



END

GO




