				WHERE tcf.sl_guid = @guid
		END

END
GO





CREATE PROCEDURE [dbo].[spComplexFilter_Customer_MixedFilters]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,

	@cust_id			INT,
	@country_id			INT,
	@state_id			INT,
	@fc_id				INT,
	@tnt_id				INT,
	@optionTaxNumber	INT,
	@cust_taxNumber		VARCHAR(50),
	@optionName			INT,
	@Cust_Name			VARCHAR(100),
	@optionAddress		INT,
	@Cust_Address		VARCHAR(100),
	@optionCity			INT,
	@Cust_City			VARCHAR(100),
	@ss_id				INT,
	@dl_id				INT,
	@ck_id				INT,
	@act_id				INT,
	@sm_id				INT,
	@st_id				INT,
	@disc_id			INT,
	@prli_id			INT,
	@status				INT,
	@judman				INT,
	@rating_id			INT,
	@marst_id			INT,
	@corp_id			INT,
	@def_id				INT,
	@ageFrom			INT,
	@ageTo				INT,
	@brag_id			INT,
	@option_cust_cd		INT,
	@cust_cd_from		DATETIME,
	@cust_cd_to			DATETIME,
	@SelectAll			BIT,
	@bitAddInTable		BIT
)

AS









-----------------------------------------------------------------------------

/*

DECLARE @comp_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@guid				UNIQUEIDENTIFIER,

		@country_id			INT,
		@state_id			INT,
		@fc_id				INT,
		@tnt_id				INT,
		@optionTaxNumber	INT,
		@cust_taxNumber		VARCHAR(50),
		@optionName			INT,
		@Cust_Name			VARCHAR(100),
		@optionAddress		INT,
		@Cust_Address		VARCHAR(100),
		@optionCity			INT,
		@Cust_City			VARCHAR(100),
		@ss_id				INT,
		@dl_id				INT,
		@ck_id				INT,
		@act_id				INT,
		@sm_id				INT,
		@st_id				INT,
		@disc_id			INT,
		@prli_id			INT,
		@status				INT,
		@judman				INT,
		@SelectAll			BIT,
		@bitAddInTable		BIT



SELECT  @comp_id			= 1,
		@bra_id				= 1,
		@prof_id			= 1,
		@user_id			= 3,
		@guid				= 'f6fd463f-392d-4b40-b7ea-5e534c33675c',

		@country_id			= -1,
		@state_id			= -1,
		@fc_id				= -1,
		@tnt_id				= -1,
		@optionTaxNumber	= -1,
		@cust_taxNumber		= '',
		@optionName			= -1,
		@Cust_Name			= '',
		@optionAddress		= -1,
		@Cust_Address		= '',
		@optionCity			= -1,
		@Cust_City			= '',
		@ss_id				= -1,
		@dl_id				= -1,
		@ck_id				= -1,
		@act_id				= -1,
		@sm_id				= -1,
		@st_id				= -1,
		@disc_id			= -1,
		@prli_id			= -1,
		@status				= -1,
		@judman				= -1,
		@SelectAll			= 'False',
		@bitAddInTable		= 'True'

*/

-----------------------------------------------------------------------------

	SET NOCOUNT ON

		BEGIN
				-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
				-- -------------------------------------------------------------------------------------------------------------------------------------------------
				-- FILTRO por MixedFilters
				-- -------------------------------------------------------------------------------------------------------------------------------------------------
				DECLARE @tmpCustMixedFilters TABLE(cust_id INT PRIMARY KEY)

				INSERT INTO @tmpCustMixedFilters (cust_id)	SELECT tc.cust_id
				                                          	FROM tbCustomer tc

				                                          	WHERE	(@country_id		= -1 OR tc.country_id		= @country_id)		AND
				                                          			(@state_id			= -1 OR tc.state_id			= @state_id)		AND
				                                          			(@fc_id				= -1 OR tc.fc_id			= @fc_id)			AND
				                                          			(@tnt_id			= -1 OR tc.tnt_id			= @tnt_id)			AND
				                                          			(
																		(@optionTaxNumber = -1 )																OR
																		(@optionTaxNumber = 0	AND tc.cust_taxNumber LIKE			  @cust_taxNumber + '%')	OR
																		(@optionTaxNumber = 1	AND tc.cust_taxNumber LIKE		'%' + @cust_taxNumber + '%')	OR
																		(@optionTaxNumber = 2	AND tc.cust_taxNumber =				  @cust_taxNumber)			OR
																		(@optionTaxNumber = 3	AND tc.cust_taxNumber <>			  @cust_taxNumber)			OR
																		(@optionTaxNumber = 4	AND tc.cust_taxNumber NOT LIKE  '%' + @cust_taxNumber + '%')
				                                          			)																	AND
				                                          			(
																		(@optionName = -1 )																		OR
																		(@optionName = 0	AND tc.cust_name LIKE			  @Cust_Name + '%')					OR
																		(@optionName = 1	AND tc.cust_name LIKE		'%' + @Cust_Name + '%')					OR
																		(@optionName = 2	AND tc.cust_name =				  @Cust_Name)						OR
																		(@optionName = 3	AND tc.cust_name <>				  @Cust_Name)						OR
																		(@optionName = 4	AND tc.cust_name NOT LIKE   '%' + @Cust_Name + '%')
				                                          			)																	AND
				                                          			(
																		(@optionAddress = -1 )																	OR
																		(@optionAddress = 0	AND tc.cust_address LIKE			  @Cust_Address + '%')			OR
																		(@optionAddress = 1	AND tc.cust_address LIKE		'%' + @Cust_Address + '%')			OR
																		(@optionAddress = 2	AND tc.cust_address =				  @Cust_Address)				OR
																		(@optionAddress = 3	AND tc.cust_address <>				  @Cust_Address)				OR
																		(@optionAddress = 4	AND tc.cust_address NOT LIKE	'%' + @Cust_Address + '%')
				                                          			)																	AND
				                                          			(
																		(@optionCity = -1 )																	OR
																		(@optionCity = 0	AND tc.cust_city LIKE			  @Cust_City + '%')				OR
																		(@optionCity = 1	AND tc.cust_city LIKE		'%' + @Cust_City + '%')				OR
																		(@optionCity = 2	AND tc.cust_city =				  @Cust_City)					OR
																		(@optionCity = 3	AND tc.cust_city <>				  @Cust_City)					OR
																		(@optionCity = 4	AND tc.cust_city NOT LIKE	'%' + @Cust_City + '%')
				                                          			)																AND
				                                          			(
																		(@option_cust_cd = -1 )										OR
				                                          				(@option_cust_cd = 0 AND tc.cust_cd =	@cust_cd_from )		OR
																		(@option_cust_cd = 1 AND tc.cust_cd >	@cust_cd_from)		OR
																		(@option_cust_cd = 2 AND tc.cust_cd <	@cust_cd_from)		OR
																		(@option_cust_cd = 3 AND tc.cust_cd BETWEEN  @cust_cd_from AND @cust_cd_to)
																	)
																																	AND
				                                          			(@ss_id				= -1 OR tc.ss_id			= @ss_id)			AND
				                                          			(@dl_id				= -1 OR tc.dl_id			= @dl_id)			AND
				                                          			(@ck_id				= -1 OR tc.ck_id			= @ck_id)			AND
				                                          			(@act_id			= -1 OR tc.act_id			= @act_id)			AND
				                                          			(@sm_id				= -1 OR tc.sm_id			= @sm_id)			AND
				                                          			(@st_id				= -1 OR tc.st_id			= @st_id)			AND
				                                          			(@disc_id			= -1 OR tc.disc_id			= @disc_id)			AND
				                                          			(@prli_id			= -1 OR tc.prli_id			= @prli_id)			AND
				                                          			(@status			= -1 OR tc.cust_inactive	= @status)			AND
				                                          			(@judman			= -1 OR tc.cust_judMan		= @judman)			AND
																	(@rating_id			= -1 OR tc.rating_id		= @rating_id)		AND
																	(@marst_id			= -1 OR tc.marst_id			= @marst_id)		AND
																	(@corp_id			= -1 OR tc.corp_id			= @corp_id)			AND
																	(@def_id			= -1 OR tc.def_id			= @def_id)			AND
																	(@brag_id			= -1 OR tc.brag_id			= @brag_id)			AND
																	(isnull(tc.cust_age,0) BETWEEN @ageFrom AND @ageTo)



				-- -------------------------------------------------------------------------------------------------------------------------------------------------

				IF @bitAddInTable = 'True'
				BEGIN

					INSERT INTO tbComplexFilter
					(
						sl_guid,
						sl_id,
						sl_order,
						sl_selected
					)
					SELECT	@guid,
							tc.cust_id,
							0,
							@SelectAll
					FROM tbCustomer tc	WITH (NOLOCK)

						INNER JOIN @tmpCustMixedFilters tmp
							ON tmp.cust_id	= tc.cust_id

						LEFT JOIN tbComplexFilter tcf	WITH (NOLOCK)
							ON	tcf.sl_guid = @guid AND
								tcf.sl_id	= tc.cust_id

						WHERE	tc.comp_id	= @comp_id AND
								tcf.sl_guid IS NULL
				END
			ELSE
				BEGIN
					DELETE FROM tbComplexFilter
						FROM tbComplexFilter	tcf	WITH (NOLOCK)
						INNER JOIN tbCustomer	tc	WITH (NOLOCK)
							ON	tc.comp_id = @comp_id AND
								tc.cust_id = tcf.sl_id
						INNER JOIN @tmpCustMixedFilters tmp
							ON tmp.cust_id = tc.cust_id
						WHERE tcf.sl_guid = @guid
				END

				END
GO




