-- =========================================================

CREATE PROCEDURE [dbo].[spComplexFilter_Customer_Name]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@option				INT,
	@cust_name			VARCHAR(200),
	@bitAddInTable		BIT,
	@SelectAll			BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@option				INT,
			@cust_name			VARCHAR(200),
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@option				=1,
			@cust_name			= 'asdasd',
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	-- -------------------------------------------------------------------------------------
	-- FILTRO por Razón Social
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpCustomerName TABLE(CustId INT PRIMARY KEY)
	IF (@option = '-1') AND (@cust_name = '')
		BEGIN
			INSERT INTO @tmpCustomerName (CustId)	SELECT tc.cust_id
			                                        		FROM tbCustomer tc	WITH (NOLOCK)
		END
	ELSE
		BEGIN
			INSERT INTO @tmpCustomerName (CustId)	SELECT tc.cust_id
			                                        		FROM tbCustomer tc	WITH (NOLOCK)
			                                        		WHERE (
																	--(@option = -1 )														OR
																	(@option = 0 AND tc.cust_name LIKE			  @cust_name + '%') OR
																	(@option = 1 AND tc.cust_name LIKE		'%' + @cust_name + '%') OR
																	(@option = 2 AND tc.cust_name =			  @cust_name)		OR
																	(@option = 3 AND tc.cust_name <>			  @cust_name)		OR
																	(@option = 4 AND tc.cust_name NOT LIKE '%' + @cust_name + '%')
																  )
		END
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					tc.cust_id,
					0,
					@SelectAll
			FROM tbCustomer tc	WITH (NOLOCK)
				INNER JOIN @tmpCustomerName tmp
					ON tmp.CustId	= tc.cust_id
				LEFT JOIN tbComplexFilter tcf	WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= tc.cust_id
				WHERE	tc.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf	WITH (NOLOCK)
				INNER JOIN tbCustomer	tc	WITH (NOLOCK)
					ON	tc.comp_id = @comp_id AND
						tc.cust_id = tcf.sl_id
				INNER JOIN @tmpCustomerName tmp
					ON tmp.CustId = tc.cust_id
				WHERE tcf.sl_guid = @guid
		END

END
GO




