CREATE PROCEDURE [dbo].[spComplexFilter_ItemClass_getData]
(
	@guid				uniqueidentifier
)
as


BEGIN

	set nocount on

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-------------------------------------------------------------------------
	/*
	declare	@guid				UNIQUEIDENTIFIER


	select	@guid				='45b7f584-70ae-4d17-981d-392a3b8c75e9'

    -------------------------------------------------------------------------
    */

	select	' '							[X0],
			tcf.sl_selected				[Selected],
			' '							[X1] ,
			' '							[X2] ,
			' '							[X3] ,
			ti.item_code				[item_code],
			ti.item_desc				[item_desc],
			tcf.sl_id					[ID]

	from	dbo.tbComplexFilter		tcf		WITH (NOLOCK)

	LEFT JOIN tbitem				ti		WITH (NOLOCK)
	ON tcf.sl_id = ti.item_id

	WHERE tcf.sl_guid				=	@guid



END

GO




