-- Description:	Filtro de GRUPO DE SUCURSALES para el ComplexFilter
-- =========================================================


CREATE PROCEDURE [dbo].[spComplexFilter_Items_BranchGroup]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@brag_id				INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@cat_id				INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@cat_id				=3,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbBranchGroup
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemBranchGroup TABLE(brag_id INT PRIMARY KEY)
	IF @brag_id = '-1'
		BEGIN
			INSERT INTO @tmpItemBranchGroup (brag_id)	SELECT tc.brag_id
			                                         	FROM tbBranchGroup tc	WITH (NOLOCK)
			                                         	WHERE tc.comp_id = @comp_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemBranchGroup ( brag_id)	SELECT @brag_id
		END
--==
--SELECT * from @tmpItemCategory
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti	WITH (NOLOCK)
				INNER JOIN @tmpItemBranchGroup tmp
					ON tmp.brag_id	= ti.brag_id
				LEFT JOIN tbComplexFilter tcf	WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
 					    AND
         			    (
         			   		ti.bra_id IS NULL
         					OR
         					ti.bra_id = @bra_id
         			    )
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf	WITH (NOLOCK)
				INNER JOIN tbItem		ti	WITH (NOLOCK)
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItemBranchGroup tmp
					ON tmp.brag_id = ti.brag_id
				WHERE tcf.sl_guid = @guid
		END






END
GO





