	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@cat_id				INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@cat_id				INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@cat_id				=3,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbCategory
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemCategory TABLE(cat_id INT PRIMARY KEY)
	IF @cat_id = '-1'
		BEGIN
			INSERT INTO @tmpItemCategory (cat_id)	SELECT tc.cat_id
			                                    		FROM tbCategory tc	WITH (NOLOCK)
			                                     	WHERE tc.comp_id = @comp_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemCategory ( cat_id)	SELECT @cat_id
		END
--==
--SELECT * from @tmpItemCategory
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti	WITH (NOLOCK)
				INNER JOIN @tmpItemCategory tmp
					ON tmp.cat_id	= ti.cat_id
				LEFT JOIN tbComplexFilter tcf	WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
 					    AND
         			    (
         			   		ti.bra_id IS NULL
         					OR
         					ti.bra_id = @bra_id
         			    )
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf	WITH (NOLOCK)
				INNER JOIN tbItem		ti	WITH (NOLOCK)
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItemCategory tmp
					ON tmp.cat_id = ti.cat_id
				WHERE tcf.sl_guid = @guid
		END






END
GO




-- ================================================================
-- Author:		GA
-- Create date: 20-05-2014
-- Description:	Filtro de Grupo de Categoria para el ComplexFilter
-- ================================================================


CREATE PROCEDURE [dbo].[spComplexFilter_Items_CategoryGroup]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@catg_id			INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT

AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@catg_id			INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@catg_id				=3,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbCategoryGroup
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemCategoryGroup TABLE(catg_id INT PRIMARY KEY)
	IF @catg_id = '-1'
		BEGIN
			INSERT INTO @tmpItemCategoryGroup (catg_id)	SELECT tc.catg_id
			                                    			FROM tbCategoryGroup tc	WITH (NOLOCK)
			                                           		WHERE tc.comp_id = @comp_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemCategoryGroup ( catg_id)	SELECT @catg_id
		END
--==
--SELECT * from @tmpItemCategoryGroup
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
			FROM tbItem ti	WITH (NOLOCK)

			INNER JOIN tbCategory					tc	WITH (NOLOCK)
			ON  tc.comp_id	= ti.comp_id AND
				tc.cat_id	= ti.cat_id

			INNER JOIN @tmpItemCategoryGroup		tmp
			ON tmp.catg_id	= tc.catg_id

			LEFT JOIN tbComplexFilter				tcf	WITH (NOLOCK)
			ON	tcf.sl_guid = @guid AND
				tcf.sl_id	= ti.item_id

			WHERE	ti.comp_id	= @comp_id AND
					tcf.sl_guid IS NULL
				    AND
     			    (
     			   		ti.bra_id IS NULL
     					OR
     					ti.bra_id = @bra_id
     			    )
		END
	ELSE
		BEGIN

			DELETE FROM tbComplexFilter
				FROM tbComplexFilter					tcf	WITH (NOLOCK)

				INNER JOIN tbItem						ti	WITH (NOLOCK)
				ON	ti.comp_id	= @comp_id		AND
					ti.item_id	= tcf.sl_id

				INNER JOIN tbCategory					tc	WITH (NOLOCK)
				ON  tc.comp_id	= ti.comp_id	AND
					tc.cat_id	= ti.cat_id

				INNER JOIN @tmpItemCategoryGroup tmp
				ON tmp.catg_id	= tc.catg_id

				WHERE tcf.sl_guid = @guid
		END






END
GO




-- =========================================================
-- Author:		GA
-- Create date: 22-05-2014
-- Description:	Filtro de Codigo para Item
-- =========================================================

CREATE PROCEDURE [dbo].[spComplexFilter_Items_Code]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@option				INT,
	@Item_Code			VARCHAR(50),
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@Item_Code			VARCHAR(30),
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@Item_Code			='32507274',
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por codigo del Articulo
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItem_ItemCode TABLE(item_id INT PRIMARY KEY)
	IF @Item_code= ''
		BEGIN
			INSERT INTO @tmpItem_ItemCode (item_id)	SELECT	ts.item_id
			                                             	FROM tbItem ts	WITH (NOLOCK)
			                                       	WHERE ts.comp_id = @comp_id
			                                     					    AND
			                                             			    (
			                                             			   		ts.bra_id IS NULL
			                                             					OR
			                                             					ts.bra_id = @bra_id
			                                             			    )

		END
	ELSE
		BEGIN
			INSERT INTO @tmpItem_ItemCode (item_id)	SELECT ts.item_id
			                                            FROM tbItem ts	WITH (NOLOCK)
			                                       		WHERE ts.comp_id = @comp_id	 AND
			                                             		(
																	(@option = -1 )														OR
																	(@option = 0 AND ts.item_code LIKE			  @Item_code + '%') OR
																	(@option = 1 AND ts.item_code LIKE		'%' + @Item_code + '%') OR
																	(@option = 2 AND ts.item_code =				  @Item_code)		OR
																	(@option = 3 AND ts.item_code <>			  @Item_code)		OR
																	(@option = 4 AND ts.item_code NOT LIKE '%' + @Item_code + '%')
			                                             		)
			                                     					    AND
			                                             			    (
			                                             			   		ts.bra_id IS NULL
			                                             					OR
			                                             					ts.bra_id = @bra_id
			                                             			    )
		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti	WITH (NOLOCK)
				INNER JOIN @tmpItem_ItemCode tmp
					ON tmp.item_id	= ti.item_id
				LEFT JOIN tbComplexFilter tcf	WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf	WITH (NOLOCK)
				INNER JOIN tbItem		ti	WITH (NOLOCK)
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItem_ItemCode tmp
					ON tmp.item_id = ti.item_id
				WHERE tcf.sl_guid = @guid
		END






END
GO





-- =========================================================
