CREATE PROCEDURE [dbo].[spComplexFilter_Items_CostListCurrency]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@coslis_id			INT,					-- Lista de Costo
	@curr_id			INT,					-- Moneda
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-------------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@coslis_id			INT,					-- Lista de Costo
	@curr_id			INT,					-- Moneda
	@SelectAll			BIT,
	@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@curr_id			=1,
			@coslis_id			= 1,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por lista de costo y moneda
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemCostListCurrency TABLE(byor_id INT PRIMARY KEY)
	IF @coslis_id > 0 AND  @curr_id > 0
		BEGIN
			INSERT INTO @tmpItemCostListCurrency (byor_id)	SELECT ticl.item_id
			                                   					FROM  tbItemCostList AS ticl		WITH (NOLOCK)
			                                    				WHERE	ticl.comp_id	= @comp_id AND
			                                    						ticl.coslis_id	= @coslis_id AND
			                                    						ticl.curr_id	= @curr_id
		END
	--ELSE
	--	BEGIN
	--		INSERT INTO @tmpItemCostListCurrency ( byor_id)	SELECT @coslis_id
	--	END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti	WITH (NOLOCK)
				INNER JOIN @tmpItemCostListCurrency tmp
					ON tmp.byor_id	= ti.item_id
				LEFT JOIN tbComplexFilter tcf	WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
 					    AND
         			    (
         			   		ti.bra_id IS NULL
         					OR
         					ti.bra_id = @bra_id
         			    )
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf	WITH (NOLOCK)
				INNER JOIN tbItem		ti	WITH (NOLOCK)
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItemCostListCurrency tmp
					ON tmp.byor_id = ti.item_id
				WHERE tcf.sl_guid = @guid
		END






END
GO




