	@guid				UNIQUEIDENTIFIER,
	@Item_IDFrom		VARCHAR(50),
	@Item_IDTo			VARCHAR(50),
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
