	ELSE
		BEGIN
			INSERT INTO @tmpItem_ItemID (item_id)	SELECT ts.item_id
			                                            FROM tbItem ts	WITH (NOLOCK)
			                                       		WHERE ts.comp_id	= @comp_id	 AND
			                                       		(@item_IDTo			<> ''  and ts.item_id BETWEEN @item_IDFrom AND  @item_IDTo	OR
														 @item_IDTo			=  ''  and @item_IDFrom	= '' OR ts.item_id	= @item_IDFrom) and
			                                             	--	( ts.item_id = @Item_id
			                                             	--	)
			                                     					    --AND
			                                             			    (
			                                             			   		ts.bra_id IS NULL
			                                             					OR
			                                             					ts.bra_id = @bra_id
			                                             			    )
		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti	WITH (NOLOCK)
				INNER JOIN @tmpItem_ItemID tmp
					ON tmp.item_id	= ti.item_id
				LEFT JOIN tbComplexFilter tcf	WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf	WITH (NOLOCK)
				INNER JOIN tbItem ti	WITH (NOLOCK)
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItem_ItemID tmp
					ON tmp.item_id = ti.item_id
				WHERE tcf.sl_guid = @guid
		END






END
GO





