CREATE PROCEDURE [dbo].[spComplexFilter_Items_ItemClass]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@strItemClass		VARCHAR(MAX),
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS





-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@strItemClass		VARCHAR(MAX),
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@strItemClass		='25,7,6',
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbItemClass
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemClass TABLE(ic_id INT PRIMARY KEY CLUSTERED)
	IF @strItemClass = '-1' OR @strItemClass = ''
		BEGIN
			INSERT INTO @tmpItemClass (ic_id)	SELECT DISTINCT
													tic.ic_id
			                                 		FROM tbItemClass tic	WITH(NOLOCK)
			                                 		WHERE tic.comp_id =  @comp_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemClass ( ic_id)	SELECT	DISTINCT
														items
			                                  		FROM dbo.fnSplitTable(@strItemClass,',') fst
		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti	WITH (NOLOCK)
				INNER JOIN @tmpItemClass tmp
					ON tmp.ic_id	= ti.ic_id
				LEFT JOIN tbComplexFilter tcf	WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
 					    AND
         			    (
         			   		ti.bra_id IS NULL
         					OR
         					ti.bra_id = @bra_id
         			    )
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf	WITH (NOLOCK)
				INNER JOIN tbItem ti	WITH (NOLOCK)
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItemClass tmp
					ON tmp.ic_id = ti.ic_id
				WHERE tcf.sl_guid = @guid
		END






END
GO





CREATE PROCEDURE [dbo].[spComplexFilter_Items_liquidation]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@Option				INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@Option			INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@Option				=2,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbItem
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItem_liquidation TABLE(item_id INT PRIMARY KEY)
	IF @Option = '-1'
		BEGIN
			INSERT INTO @tmpItem_liquidation (item_id)	SELECT ti.item_id
			                                    				FROM tbitem ti	WITH (NOLOCK)
			                                          			WHERE ti.comp_id = @comp_id
			                                     					    AND
			                                             			    (
			                                             			   		ti.bra_id IS NULL
			                                             					OR
			                                             					ti.bra_id = @bra_id
			                                             			    )
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItem_liquidation (item_id)	SELECT ti.item_id
			                                     				FROM tbItem ti	WITH (NOLOCK)
			                                     				WHERE (
			                                     						  (@Option = 0 AND ti.item_liquidation = 'False') OR
			                                     						  (@Option = 1 AND ti.item_liquidation = 'True')
			                                     					  )
			                                     					    AND
			                                             			    (
			                                             			   		ti.bra_id IS NULL
			                                             					OR
			                                             					ti.bra_id = @bra_id
			                                             			    )

		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti	WITH (NOLOCK)
				INNER JOIN @tmpItem_liquidation tmp
					ON tmp.item_id	= ti.item_id
				LEFT JOIN tbComplexFilter tcf	WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf	WITH (NOLOCK)
				INNER JOIN tbItem ti	WITH (NOLOCK)
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItem_liquidation tmp
					ON tmp.item_id = ti.item_id
				WHERE tcf.sl_guid = @guid
		END






END
GO





