		BEGIN
			INSERT INTO @tmpItem_liquidationPlus (item_id)	SELECT ti.item_id
			                                     				FROM tbItem ti	WITH (NOLOCK)
			                                     				WHERE (
			                                     						  (@Option = 0 AND ti.item_liquidationPlus = 'False') OR
			                                     						  (@Option = 1 AND ti.item_liquidationPlus = 'True')
			                                     					  )
			                                     					    AND
			                                             			    (
			                                             			   		ti.bra_id IS NULL
			                                             					OR
			                                             					ti.bra_id = @bra_id
			                                             			    )

		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti	WITH (NOLOCK)
				INNER JOIN @tmpItem_liquidationPlus tmp
					ON tmp.item_id	= ti.item_id
				LEFT JOIN tbComplexFilter tcf	WITH (NOLOCK)
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf	WITH (NOLOCK)
				INNER JOIN tbItem ti	WITH (NOLOCK)
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItem_liquidationPlus tmp
					ON tmp.item_id = ti.item_id
				WHERE tcf.sl_guid = @guid
		END





END
GO





CREATE PROCEDURE [dbo].[spComplexFilter_Items_MixedFilters]
(
	@comp_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@guid					UNIQUEIDENTIFIER,

	@itemClass				VARCHAR(MAX),
	@cat_id					INT,
	@subcat_id				INT,
	@subcataux_id			INT,
	@brand_id				INT,
	@pres_id				INT,
	@status					INT,
	@optionDesc				INT,
	@itemDesc				VARCHAR(100),
	@optionCode				INT,
	@itemCode				VARCHAR(100),
	@optionVendorCode		INT,
	@itemVendorCode			VARCHAR(100),
	@itemDisabled			INT,
	@item_id				INT,	--selitem
	@supp_id				INT,
	@pubh_id				INT,
	@catg_id				INT,
	@brag_id				INT,
	@item_newness			INT,
	@item_liquidation		INT,
	@item_outlet			INT,

	@item_web				INT,--Disponible para MercadoLibre©
	@item_ML_isAvailable	INT,--Venta disponible x Web
	@byor_id				INT,--Por Cuenta y Orden de
	@item_liquidationPlus	INT,--Super oferta

	@itemIDFrom 			VARCHAR(50), -- filtro por ID de item Desde (textbox)txtitemid
	@itemIDTo 				VARCHAR(50), -- filtro por ID de item Hasta (textbox)txtitemid


	--poder seleccionar todos los items q en una lista determinada tienen la moneda x
	@coslis_id				INT,		 -- Lista de Costo
	@curr_id				INT,		 -- Moneda
	---
	@tipi_id				INT,		 -- Tipo de Item
	--
	@itemAtrb1_id			INT,		 -- Atributos de Articulo 1
	@itemAtrb2_id			INT,		 -- Atributos de Articulo 2
	@itemAtrb3_id			INT,		 -- Atributos de Articulo 3
	@itemAtrb4_id			INT,		 -- Atributos de Articulo 4
	--
	@SelectAll				BIT,
	@bitAddInTable			BIT
)

AS





BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	---- -----------------------------------------------------------------------------
	---- Sucursales para Filtrado
	---- -----------------------------------------------------------------------------
	--DECLARE @tblBranchs TABLE(bra_id INT PRIMARY KEY)
	--IF @brag_id = -1
	--	BEGIN
	--		INSERT INTO @tblBranchs(bra_id)
	--			SELECT tb.bra_id
	--				FROM tbBranch tb		WITH	(NOLOCK)
	--				WHERE tb.comp_id = @comp_id
	--	END
	--ELSE
	--	BEGIN
	--		INSERT INTO @tblBranchs(bra_id)
	--			SELECT tb.bra_id
	--			FROM tbBranchGroupDetail tb
	--				WHERE	tb.comp_id = @comp_id AND
	--						tb.brag_id = @brag_id
	--	END
	---- -----------------------------------------------------------------------------



	DECLARE @tmpItemClass	TABLE(ic_id		INT PRIMARY KEY)
	DECLARE @tmpItemByClass TABLE(item_id	INT PRIMARY KEY)
	IF @itemClass = '-1' OR @itemClass = ''
		BEGIN
			INSERT INTO @tmpItemByClass (item_id)	SELECT
														tm.item_id
														FROM	tbitem		tm WITH(NOLOCK)
			                                     		WHERE	tm.comp_id = @comp_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemClass ( ic_id)	SELECT items
	                                  				FROM dbo.fnSplitTable(@itemClass,',') fst

			INSERT INTO @tmpItemByClass (item_id)	SELECT		tm.item_id
														FROM	tbitem tm
														INNER JOIN @tmpItemClass tc
															ON tc.ic_id = tm.ic_id
			                                     		WHERE	tm.comp_id = @comp_id
		END
		-- -------------------------------------------------------------------------------------------------------------------------------------------------
		-- FILTRO por MixedFilters
		-- -------------------------------------------------------------------------------------------------------------------------------------------------
		DECLARE @tmpItemMixedFilters TABLE(item_id INT PRIMARY KEY)

		INSERT INTO @tmpItemMixedFilters (item_id)	SELECT
														ti.item_id
		              		FROM tbItem								ti		WITH (NOLOCK)

		                                          		INNER JOIN tbCategory					tc		WITH (NOLOCK)
														ON  tc.comp_id	= ti.comp_id AND
															tc.cat_id	= ti.cat_id
														--LEFT JOIN @tblBranchs					tmp
														--	ON tmp.bra_id = ti.bra_id


		                                          		WHERE
		                                          				(@catg_id			= -1 OR tc.catg_id			= @catg_id)					AND
		                                          				(@cat_id			= -1 OR ti.cat_id			= @cat_id)					AND
		                                          				(@subcat_id			= -1 OR ti.subcat_id		= @subcat_id)				AND
		                                          				(@subcataux_id		= -1 OR ti.subcataux_id		= @subcataux_id)			AND
		                                          				(@brand_id			= -1 OR ti.brand_id			= @brand_id)				AND
		                                          				(@pres_id			= -1 OR ti.pres_id			= @pres_id)					AND
		                                          				(@status			= -1 OR ti.item_disabled	= @status)					AND
		                                          				(@tipi_id			= -1 OR ti.tipi_id			= @tipi_id)					AND

		                                          				(@itemAtrb1_id		= -1 OR ti.itemAtrb1_id		= @itemAtrb1_id)			AND
		                                          				(@itemAtrb2_id		= -1 OR ti.itemAtrb2_id		= @itemAtrb2_id)			AND
		                                          				(@itemAtrb3_id		= -1 OR ti.itemAtrb3_id		= @itemAtrb3_id)			AND
		                                          				(@itemAtrb4_id		= -1 OR ti.itemAtrb4_id		= @itemAtrb4_id)			AND


		                                          				(
																	(@optionDesc = -1 )												   OR
																	(@optionDesc = 0 AND ti.item_desc LIKE			  @itemDesc + '%') OR
																	(@optionDesc = 1 AND ti.item_desc LIKE		'%' + @itemDesc + '%') OR
																	(@optionDesc = 2 AND ti.item_desc =				  @itemDesc)	   OR
																	(@optionDesc = 3 AND ti.item_desc <>			  @itemDesc)	   OR
																	(@optionDesc = 4 AND ti.item_desc NOT LIKE  '%' + @itemDesc + '%')
		                                          				)																			AND
		       				(
																	(@optionCode = -1 )												   OR
																	(@optionCode = 0 AND ti.item_code LIKE			  @itemCode + '%') OR
																	(@optionCode = 1 AND ti.item_code LIKE		'%' + @itemCode + '%') OR
																	(@optionCode = 2 AND ti.item_code =				  @itemCode)	   OR
																	(@optionCode = 3 AND ti.item_code <>			  @itemCode)	   OR
																	(@optionCode = 4 AND ti.item_code NOT LIKE  '%' + @itemCode + '%')
																)																			 AND
																(
																	(@optionVendorCode = -1 )															 OR
																	(@optionVendorCode = 0 AND ti.item_vendorCode LIKE			  @itemVendorCode + '%') OR
																	(@optionVendorCode = 1 AND ti.item_vendorCode LIKE		'%' + @itemVendorCode + '%') OR
																	(@optionVendorCode = 2 AND ti.item_vendorCode =				  @itemVendorCode)	     OR
																	(@optionVendorCode = 3 AND ti.item_vendorCode <>			  @itemVendorCode)	     OR
																	(@optionVendorCode = 4 AND ti.item_vendorCode NOT LIKE  '%' + @itemVendorCode + '%')
																)																			AND
																(@itemDisabled		= -1 OR ti.item_disabledInPriceList = @itemDisabled)	AND
																(@item_newness		= -1 OR ti.item_newness = @item_newness)	AND
																(@item_liquidation	= -1 OR ti.item_liquidation = @item_liquidation)	AND
																(@item_liquidationPlus	= -1 OR ti.item_liquidationPlus = @item_liquidationPlus)	AND
																(@item_outlet		= -1 OR ti.item_outlet = @item_outlet)	AND
																--(@item_web		= -1 OR ti.item_web = @item_web)					AND --Venta disponible x Web
																--(@item_ML_isAvailable		= -1 OR ti.item_ML_isAvailable = @item_ML_isAvailable)					AND --Disponible para MercadoLibre©
																(@item_id			= -1 OR ti.item_id					= @item_id)			AND --selitem
																(
																 @itemIDTo			<> ''  and ti.item_id BETWEEN @itemIDFrom AND  @itemIDTo	OR
																 @itemIDTo			=  ''  and @itemIDFrom	= '' OR ti.item_id	= @itemIDFrom
																) AND-- Item ID From y Item ID To



																--(IF  @itemIDTo			<> ''
																--	ELSE



																--	CASE
																--		WHEN @itemIDTo			<> ''  THEN ti.item_id BETWEEN @itemIDFrom AND  @itemIDTo
																--		WHEN @itemIDTo			=  ''  THEN @itemIDFrom	= -1 OR ti.item_id	= @itemIDFrom
																--		ELSE 0
																-- END)			AND --txtitemid
																(@supp_id			= -1 OR ti.supp_id					= @supp_id)			AND
																(@brag_id			= -1 OR ti.brag_id					= @brag_id)			AND
																(ti.bra_id IS NULL OR ti.bra_id = @bra_id)									AND
																 (
																	CASE
																		WHEN @pubh_id			= -1  THEN 1
																		WHEN
																			EXISTS(	SELECT TOP 1  1
																	       			FROM tbItemPublicationDetail tipd	WITH (NOLOCK)
         																				WHERE
         																					tipd.comp_id	= @comp_id		AND
         																					tipd.item_id	= ti.item_id	AND
         																					tipd.pubh_id    = @pubh_id

																				  ) THEN 1
																		ELSE	0
																	END	= 1
																 )																					AND
																 (@item_web				= -1 OR		ti.item_web				= @item_web)			AND
																 (@byor_id				= -1 OR		ti.byor_id				= @byor_id)				AND
																 (@item_ML_isAvailable	= -1 OR		ti.item_ML_isAvailable	= @item_ML_isAvailable) AND
																 CASE	-- MOS 10-2020
																	WHEN @coslis_id < 1 OR @curr_id < 1 THEN 1
																	ELSE	CASE
																				WHEN EXISTS(	SELECT TOP 1 1
																				            		FROM tbItemCostList AS ticl WITH (NOLOCK)
																				            		WHERE	ticl.comp_id	= @comp_id		AND
																				            				ticl.coslis_id	= @coslis_id	AND
																				            				ticl.item_id	= ti.item_id	AND
																				            				ticl.curr_id    = @curr_id
																							) THEN 1
																				ELSE 0
																			END
																 END = 1


		-- -------------------------------------------------------------------------------------------------------------------------------------------------

	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti

				INNER JOIN @tmpItemMixedFilters tmp
					ON tmp.item_id	= ti.item_id

				INNER JOIN @tmpItemByClass tmpI
					ON tmpI.item_id = ti.item_id

				LEFT JOIN tbComplexFilter tcf
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf
				INNER JOIN tbItem ti
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id

				INNER JOIN @tmpItemMixedFilters tmp
					ON tmp.item_id = ti.item_id

				INNER JOIN @tmpItemByClass tmpI
					ON tmpI.item_id = ti.item_id

				WHERE tcf.sl_guid = @guid
		END

END
GO




--Disponible para MercadoLibre©
CREATE PROCEDURE [dbo].[spComplexFilter_Items_ML_isAvailable]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@Option				INT,		--Disponible para MercadoLibre©
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@Option			INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@Option				=1,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbItem
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItem_ML_isAvailable TABLE(item_id INT PRIMARY KEY)
	IF @Option = '-1'
		BEGIN
			INSERT INTO @tmpItem_ML_isAvailable (item_id)	SELECT ti.item_id
			                                    				FROM tbitem ti		WITH (NOLOCK)
			                                             		WHERE	ti.comp_id = @comp_id AND
			                                             			   (
			                                             			   		ti.bra_id IS NULL
			                                             					OR
			                                             					ti.bra_id = @bra_id
			                                             			    )
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItem_ML_isAvailable (item_id)	SELECT ti.item_id
			                                     				FROM tbItem ti		WITH (NOLOCK)
			                                             		WHERE 	ti.comp_id = @comp_id AND
			                                     				    	(
			                                     						  (@Option = 0 AND ti.item_ML_isAvailable = 'False') OR
			                                     						  (@Option = 1 AND ti.item_ML_isAvailable = 'True')
			                                     					    )
			                                     					    AND
			                                             			    (
			                                             			   		ti.bra_id IS NULL
			                                             					OR
			                                             					ti.bra_id = @bra_id
			                                             			    )


		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti
				INNER JOIN @tmpItem_ML_isAvailable tmp
					ON tmp.item_id	= ti.item_id
				LEFT JOIN tbComplexFilter tcf
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf
				INNER JOIN tbItem ti
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItem_ML_isAvailable tmp
					ON tmp.item_id = ti.item_id
				WHERE tcf.sl_guid = @guid
		END





END
GO





