-- Description:	Filtro de Presentacion para el ComplexFilter
-- =========================================================

CREATE PROCEDURE [dbo].[spComplexFilter_Items_Presentation]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@pres_id			INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@pres_id			VARCHAR(MAX),
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@pres_id			='3',
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbBrand
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemPres TABLE(pres_id INT PRIMARY KEY)
	IF @pres_id = '-1'
		BEGIN
			INSERT INTO @tmpItemPres (pres_id)	SELECT tc.pres_id
			                                   		FROM tbPresentation tc
			                                  		WHERE tc.comp_id = @comp_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemPres ( pres_id)	SELECT @pres_id
		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti
				INNER JOIN @tmpItemPres tmp
					ON tmp.pres_id	= ti.pres_id
				LEFT JOIN tbComplexFilter tcf
					ON	tcf.sl_guid = @guid		AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id	AND
						tcf.sl_guid IS NULL		AND
         			   (
         			   		ti.bra_id IS NULL
         					OR
         					ti.bra_id = @bra_id
         			    )
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf
				INNER JOIN tbItem ti
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItemPres tmp
					ON tmp.pres_id = ti.pres_id
				WHERE tcf.sl_guid = @guid
		END






END
GO





-- =========================================================
-- Author:		GA
-- Create date: 29-09-2015
-- Description:	Filtro de precios actualizados entre fechas para el ComplexFilter
-- =========================================================


CREATE PROCEDURE [dbo].[spComplexFilter_Items_PriceRecentlyUpdate]


	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@dcDateFrom			DATETIME,
	@dcDateTo			DATETIME,
	@SelectAll			BIT,
	@bitAddInTable		BIT


AS

BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	--SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


		UPDATE tbComplexFilter
		SET	sl_selected		=	@bitAddInTable
		FROM tbComplexFilter	tmp

		INNER JOIN tbItem						ti			WITH (NOLOCK)
		ON	ti.comp_id		= @comp_id				AND
			ti.item_id		= tmp.sl_id

		LEFT JOIN tbBranch						tb2			WITH (NOLOCK)
		ON  tb2.comp_id		= ti.comp_id			AND
			tb2.bra_id		= @bra_id

		LEFT JOIN vwPriceListItems 				vwpli		WITH (NOLOCK)
		ON	vwpli.comp_id	= ti.comp_id			AND
			vwpli.item_id	= ti.item_id			AND
			vwpli.prli_id	= tb2.prli_id4Credit

		WHERE	tmp.sl_guid = @guid		AND
				(vwpli.lastUpdate	BETWEEN   @dcDateFrom	AND   @dcDateTo)


END
GO





-- =========================================================
-- Author:		STL
-- Create date: 21-05-2014
-- Description:	Filtro de Presentacion para el ComplexFilter
-- =========================================================


CREATE PROCEDURE [dbo].[spComplexFilter_Items_Publication]


	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@pubh_id			INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT


AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 		@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@guid				UNIQUEIDENTIFIER,
				@pubh_id			INT,
				@SelectAll			BIT,
				@bitAddInTable		BIT


SELECT			@comp_id			=1,
				@bra_id				=1,
				@prof_id			=1,
				@user_id			=1,
				@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
				@pubh_id			=1,
				@bitAddInTable		='True',
				@SelectAll			= 'False'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbItemPublicationHeader
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemPub TABLE(pubh_id INT PRIMARY KEY)
	IF @pubh_id = -1
		BEGIN
			INSERT INTO @tmpItemPub (pubh_id)	SELECT tiph.pubh_id
			                                 	FROM tbItemPublicationHeader tiph

		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemPub ( pubh_id)	SELECT @pubh_id
		END
--==
--SELECT * from @tmpItemPub
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll

				FROM tbItem ti

				--INNER JOIN @tmpItemPub tmp
				--ON tmp.pubh_id	= tipd.pubh_id

				LEFT JOIN tbComplexFilter tcf
				ON	tcf.sl_guid = @guid AND
					tcf.sl_id	= ti.item_id

				WHERE	ti.comp_id	= @comp_id	AND
						tcf.sl_guid IS NULL		AND
						 (
							CASE
								WHEN @pubh_id			= -1  THEN 1
								WHEN
									EXISTS(	SELECT 1
									       	FROM tbItemPublicationDetail tipd
												WHERE
													tipd.comp_id	= @comp_id		AND
													tipd.item_id	= ti.item_id	AND
													tipd.pubh_id    = @pubh_id

										  ) THEN 1
								ELSE	0
							END	= 1
								)
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf

				INNER JOIN tbItem ti
				ON	ti.comp_id = @comp_id AND
					ti.item_id = tcf.sl_id

				--INNER JOIN @tmpItemPub tmp
				--	ON tmp.pubh_id = tipd.pubh_id

				WHERE tcf.sl_guid = @guid	AND
				 (
					CASE
						WHEN @pubh_id			= -1  THEN 1
						WHEN
							EXISTS(	SELECT 1
							       	FROM tbItemPublicationDetail tipd
										WHERE
											tipd.comp_id	= @comp_id		AND
											tipd.item_id	= ti.item_id	AND
											tipd.pubh_id    = @pubh_id

								  ) THEN 1
						ELSE	0
					END	= 1
						)
		END






END
GO





-- =========================================================
-- Author:		MOS
-- Create date: 30-04-2015
-- Description:	Filtro de depositos para el ComplexFilter
-- =========================================================


CREATE PROCEDURE [dbo].[spComplexFilter_Items_RecentlyPurchased]


	@comp_id						INT,
	@bra_id							INT,
	@prof_id						INT,
	@user_id						INT,
	@guid							UNIQUEIDENTIFIER,
	@bitSelectRecentlyPurchased		bit

AS

BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	--SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	UPDATE tbComplexFilter
		SET	sl_selected		=	@bitSelectRecentlyPurchased
		FROM tbComplexFilter	tmp
		INNER JOIN tbItem ti
		ON	ti.comp_id = @comp_id		AND
			ti.item_id = tmp.sl_id
		WHERE	tmp.sl_guid = @guid		AND
				ti.item_recentlyPurchased = 'True'


END
GO





