-- =========================================================
-- Author:		GA
-- Create date: 21-05-2014
-- Description:	Filtro de Estado para el ComplexFilter
-- =========================================================

CREATE PROCEDURE [dbo].[spComplexFilter_Items_Status]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@Option				INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@Option			INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@Option			=2,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbItem
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemStatus TABLE(item_id INT PRIMARY KEY)
	IF @Option = '-1'
		BEGIN
			INSERT INTO @tmpItemStatus (item_id)	SELECT ti.item_id
			                                    	FROM tbitem ti
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemStatus (item_id)	SELECT ti.item_id
			                                     	  FROM tbItem ti

			                                     	WHERE (
			                                     			  (@Option = 0 AND ti.item_disabled = 'False') OR
			                                     			  (@Option = 1 AND ti.item_disabled = 'True')
			                                     		  )

		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti
				INNER JOIN @tmpItemStatus tmp
					ON tmp.item_id	= ti.item_id
				LEFT JOIN tbComplexFilter tcf
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf
				INNER JOIN tbItem ti
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItemStatus tmp
					ON tmp.item_id = ti.item_id
				WHERE tcf.sl_guid = @guid
		END






END
GO





-- =========================================================
-- Author:		MOS
-- Create date: 30-04-2015
-- Description:	Filtro de depositos para el ComplexFilter
-- =========================================================


CREATE PROCEDURE [dbo].[spComplexFilter_Items_Storage]


	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@stor_id			INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT


AS

BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	--SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	IF @stor_id <> -1

	BEGIN

		UPDATE tbComplexFilter
		SET	sl_selected		=	@bitAddInTable
		FROM tbComplexFilter	tmp
		WHERE	tmp.sl_guid = @guid AND
				dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id,tmp.sl_id) > 0




	END

END
GO





-- =========================================================
-- Author:		GA - MOS
-- Create date: 18/12/23
-- Description:	Filtro de Artículos con Stock Disponible en el Depósito Seleccionado ( Admite Sumarizadores )
-- =========================================================


CREATE PROCEDURE [dbo].[spComplexFilter_Items_StorageAvailableStock]


	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@stor_id			INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT


AS

BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	IF @stor_id <> -1

	BEGIN

		UPDATE tbComplexFilter
			SET	sl_selected		=	@bitAddInTable
			FROM tbComplexFilter	tmp
			WHERE	tmp.sl_guid = @guid AND
					dbo.fnGetAStock4MaxAssociation(@comp_id , @stor_id,tmp.sl_id,999999999) > 0

	END

END
GO





