-- =========================================================
-- Author:		GA
-- Create date: 20-05-2014
-- Description:	Filtro de SubCategoria para el ComplexFilter
-- =========================================================


CREATE PROCEDURE [dbo].[spComplexFilter_Items_SubCategory]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@subcat_id			INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@subcat_id			INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@subcat_id			=25,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbSubCategory
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemSubCategory TABLE(subcat_id INT PRIMARY KEY)
	IF @subcat_id = '-1'
		BEGIN
			INSERT INTO @tmpItemSubCategory (subcat_id)	SELECT tc.subcat_id
			                                    			FROM tbSubCategory tc
															WHERE tc.comp_id = @comp_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemSubCategory (subcat_id)	SELECT @subcat_id
		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti
				INNER JOIN @tmpItemSubCategory tmp
					ON tmp.Subcat_id	= ti.Subcat_id
				LEFT JOIN tbComplexFilter tcf
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
 					    AND
         			    (
         			   		ti.bra_id IS NULL
         					OR
         					ti.bra_id = @bra_id
         			    )
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf
				INNER JOIN tbItem ti
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItemSubCategory tmp
					ON tmp.Subcat_id = ti.Subcat_id
				WHERE tcf.sl_guid = @guid
		END






END
GO




