-- =============================================================================================
-- Author:		GA - MOS
-- Create date: 11-01-2023
-- Description:	Sección de Selección, utilizar UNICAMENTE para actuar sobre los Artículos ya filtrados.
-- Proveedor y Numero de documento seleccionado para el ComplexFilter
-- =============================================================================================


CREATE PROCEDURE [dbo].[spComplexFilter_Items_SuppDocNumber]


	@comp_id						INT,
	@bra_id							INT,
	@prof_id						INT,
	@user_id						INT,
	@guid							UNIQUEIDENTIFIER,
	@supp_id						INT,					-- Proveedor
	@ct_DocNumber					NVARCHAR(50)			-- Nro de Comprobante


AS

BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	--SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	UPDATE tbComplexFilter
		SET	sl_selected		=	CASE sl_selected
									WHEN 'True'  THEN 'False'
									WHEN 'False' THEN 'True'
								END
		FROM tbComplexFilter					tmp	WITH (NOLOCK)
		INNER JOIN tbItem						ti	WITH (NOLOCK)
		ON	ti.comp_id = @comp_id		AND
			ti.item_id = tmp.sl_id
		INNER JOIN tbCommercialTransactions AS tct	WITH (NOLOCK)
			ON	tct.comp_id			= @comp_id  AND
				tct.supp_id			= @supp_id  AND
				tct.ct_docNumber	= @ct_DocNumber
		INNER JOIN tbItemTransactions		AS tit	WITH (NOLOCK)
			ON	tit.comp_id			= tct.comp_id AND
				tit.ct_transaction	= tct.ct_transaction AND
				tit.item_id			= ti.item_id
		WHERE	tmp.sl_guid			= @guid



END
GO



-- =========================================================
-- Author:		STL
-- Create date: 16-06-2014
-- Description:	Filtro de Codigo de Vendedor para Item
-- =========================================================

CREATE PROCEDURE [dbo].[spComplexFilter_Items_VendorCode]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@option				INT,
	@Item_VendorCode	VARCHAR(50),
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@Item_Code			VARCHAR(30),
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@Item_Code			='32507274',
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por codigo del Articulo
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItem_ItemVendorCode TABLE(item_id INT PRIMARY KEY)
	IF @Item_VendorCode= ''
		BEGIN
			INSERT INTO @tmpItem_ItemVendorCode (item_id)	SELECT	ts.item_id
			                                             		FROM tbItem ts
			                                             		WHERE ts.comp_id = @comp_id

		END
	ELSE
		BEGIN
			INSERT INTO @tmpItem_ItemVendorCode (item_id)	SELECT ts.item_id
			                                             	FROM tbItem ts
			                                             	WHERE
			                                             		ts.comp_id = @comp_id AND
			                                             		(
																	(@option = -1 )														OR
																	(@option = 0 AND ts.item_vendorCode LIKE			  @Item_VendorCode + '%') OR
																	(@option = 1 AND ts.item_vendorCode LIKE		'%' + @Item_VendorCode + '%') OR
																	(@option = 2 AND ts.item_vendorCode =				  @Item_VendorCode)		OR
																	(@option = 3 AND ts.item_vendorCode <>				  @Item_VendorCode)		OR
																	(@option = 4 AND ts.item_vendorCode NOT LIKE  '%' + @Item_VendorCode + '%')
			                                             		)
			                                     					    AND
			                                             			    (
			                                             			   		ts.bra_id IS NULL
			                                             					OR
			                                             					ts.bra_id = @bra_id
			                                             			    )
		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti
				INNER JOIN @tmpItem_ItemVendorCode tmp
					ON tmp.item_id	= ti.item_id
				LEFT JOIN tbComplexFilter tcf
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
 					    AND
         			    (
         			   		ti.bra_id IS NULL
         					OR
         					ti.bra_id = @bra_id
         			    )
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf
				INNER JOIN tbItem ti
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItem_ItemVendorCode tmp
					ON tmp.item_id = ti.item_id
				WHERE tcf.sl_guid = @guid
		END






END
GO






CREATE PROCEDURE [dbo].[spComplexFilter_Items_VerificationData]
(

	@comp_id					INT,
	@guid						UNIQUEIDENTIFIER


)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE	  	@comp_id				INT,
			@guid					INT


SELECT		@comp_id				= 1,
			@guid					= ''
*/
-- ------------------------------------------------------




	IF NOT EXISTS ( SELECT
						tcf.sl_id
						FROM tbComplexFilter					tcf
						WHERE	tcf.sl_guid		= @guid AND
								tcf.sl_selected = 'True'
					)

		BEGIN
			 --SELECT 'NO TIENE DATOS'
			 SELECT 0 [IsValid4Process]

		END
	ELSE

		BEGIN
			--SELECT 'TIENE DATOS'
			SELECT 1 [IsValid4Process]

		END







END
GO




--Disponible para Sitio Web
CREATE PROCEDURE [dbo].[spComplexFilter_Items_Web]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@Option				INT,		--	Disponible para Sitio Web
	@SelectAll			BIT,
	@bitAddInTable		BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@Option			INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@Option				=1,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbItem
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItem_web TABLE(item_id INT PRIMARY KEY)
	IF @Option = '-1'
		BEGIN
			INSERT INTO @tmpItem_web (item_id)	SELECT ti.item_id
			                                    				FROM tbitem ti	WITH (NOLOCK)
			                                             		WHERE	ti.comp_id = @comp_id AND
			                                             			   (
			                                             			   		ti.bra_id IS NULL
			                                             					OR
			                                             					ti.bra_id = @bra_id
			                                             			   )
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItem_web (item_id)	SELECT ti.item_id
			                                     				FROM tbItem ti	WITH (NOLOCK)
			                                     				WHERE (
			                                     						  (@Option = 0 AND ti.item_web = 'False') OR
			                                     						  (@Option = 1 AND ti.item_web = 'True')
			                                     					  )
																		AND
			                                             			    (
			                                             			   		ti.bra_id IS NULL
			                                             					OR
			                                             					ti.bra_id = @bra_id
			                                             			    )

		END
--==
--SELECT * from @tmpItemClass
--==
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ti.item_id,
					0,
					@SelectAll
				FROM tbItem ti
				INNER JOIN @tmpItem_web tmp
					ON tmp.item_id	= ti.item_id
				LEFT JOIN tbComplexFilter tcf
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ti.item_id
				WHERE	ti.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf
				INNER JOIN tbItem ti
					ON	ti.comp_id = @comp_id AND
						ti.item_id = tcf.sl_id
				INNER JOIN @tmpItem_web tmp
					ON tmp.item_id = ti.item_id
				WHERE tcf.sl_guid = @guid
		END






END
GO





