CREATE PROCEDURE [dbo].[spComplexFilter_MarkOrUnmarkItem]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@prof_id		INT,
	@originalGuid	UNIQUEIDENTIFIER,
	@SelectionGuid	UNIQUEIDENTIFIER,
	@item_id		INT
)
AS

	SET NOCOUNT ON

		BEGIN

			-- --------------------------------------------------------------------------
			-- TESTING
			-- --------------------------------------------------------------------------
			/*
				DECLARE
					@comp_id		INT,
					@lang_id		INT,
					@bra_id			INT,
					@user_id		INT,
					@prof_id		INT,
					@originalGuid	UNIQUEIDENTIFIER,
					@SelectionGuid	UNIQUEIDENTIFIER,
					@item_id		INT

				SELECT
					@comp_id		= 1,
					@lang_id		= 2,
					@bra_id			= 1,
					@user_id		= 1,
					@prof_id		= 1,
					@originalGuid	= '673950da-debd-43cc-b851-10e4cdc9e6b4',
					@SelectionGuid	= '635a99bc-e423-48e5-838a-7ef45f236337',
					@item_id		= 229
			*/
			-- --------------------------------------------------------------------------


			--SI SELECCIONAMOS VAMOS A INSERTAR EL NUEVO REGISTRO Y VAMOS A BORRAR EL ORIGINAL
			IF EXISTS (SELECT 1 FROM tbComplexFilter tcf WHERE tcf.sl_guid = @originalGuid AND tcf.sl_id = @item_id)
				BEGIN

					--SELECT 1

					INSERT INTO tbComplexFilter
					(
						sl_guid,
						sl_id,
						sl_order,
						sl_cd,
						sl_selected,
						sl_tmpData
					)
					VALUES
					(
						@SelectionGuid,
						@item_id,
						0,
						GETDATE(),
						'True',
						0
					)

					DELETE FROM tbComplexFilter
					WHERE	sl_guid = @originalGuid AND
							sl_id	= @item_id

				END
			ELSE
				BEGIN
					--SI DES SELECCIONA VOLVEMOS A INSERTAR EL REGISTRO ORIGINAL Y A BORRAR EL QUE SE GENERO CON EL NUEVO GUID
					IF EXISTS(SELECT 1 FROM tbComplexFilter tcf WHERE tcf.sl_guid = @SelectionGuid AND tcf.sl_id = @item_id)
						BEGIN

							--SELECT 2

							INSERT INTO tbComplexFilter
							(
								sl_guid,
								sl_id,
								sl_order,
								sl_cd,
								sl_selected,
								sl_tmpData
							)
							VALUES
							(
								@originalGuid,
								@item_id,
								0,
								GETDATE(),
								'True',
								0
							)

							DELETE FROM tbComplexFilter
							WHERE	sl_guid = @SelectionGuid AND
									sl_id	= @item_id

						END
					ELSE
						BEGIN

							--SELECT 3
							--SI NO ELIGIO NINGÚN ITEM EN LA GRILLA, Y POR ENDE TOMA -1 COMO ITEMS
							--VAMOS A INSERTAR EL REGISTRO Y EN EL JOIN DEL GETDATABYFILTERS VAMOS A
							--CONTROLAR QEU EN LA SELECCIÓN DE ARTICULOS NO SELECCIONADOS, EL ITEM_ID
							--NO SE ENTUENTRE EN EL ITEM_ID DE LOS ARTÍCUOS SELECCIONADOS
							INSERT INTO tbComplexFilter
							(
								sl_guid,
								sl_id,
								sl_order,
								sl_cd,
								sl_selected,
								sl_tmpData
							)
							VALUES
							(
								@SelectionGuid,
								@item_id,
								0,
								GETDATE(),
								'True',
								0
							)


						END

	END

		END




GO




CREATE PROCEDURE [dbo].[spComplexFilter_MarkOrUnmarkItem_AllItems]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@prof_id		INT,
	@originalGuid	UNIQUEIDENTIFIER,
	@SelectionGuid	UNIQUEIDENTIFIER,
	@OptionSelection	INT -- 1 : Todos, 2:Ninguno, 3 : Invertir


)
AS

	SET NOCOUNT ON

		BEGIN

			-- --------------------------------------------------------------------------
			-- TESTING
			-- --------------------------------------------------------------------------
			/*
				DECLARE
					@comp_id		INT,
					@lang_id		INT,
					@bra_id			INT,
					@user_id		INT,
					@prof_id		INT,
					@originalGuid	UNIQUEIDENTIFIER,
					@SelectionGuid	UNIQUEIDENTIFIER,
					@item_id		INT,
					@OptionSelection			int

				SELECT
					@comp_id		= 1,
					@lang_id		= 2,
					@bra_id			= 1,
					@user_id		= 1,
