CREATE PROCEDURE spComplexFilter_PurchasePlanningUpdateQty
(
	@comp_id		INT,
	@SelectionGuid	UNIQUEIDENTIFIER,
	@item_id		INT,
	@qty			INT
)
AS
	SET NOCOUNT ON

		BEGIN

			UPDATE tbComplexFilter
			SET
				sl_tmpData	= @qty
			WHERE	sl_guid = @SelectionGuid AND
					sl_id	= @item_id

		END

GO



CREATE PROCEDURE [dbo].[spComplexFilter_PurchasePlanningUpdateQty_UPB]
(
	@comp_id		INT,
	@SelectionGuid	UNIQUEIDENTIFIER,
	@item_id		INT,
	@qty			INT
)
AS
	SET NOCOUNT ON

	BEGIN


		--------------------------------------------------------------------------------------------------------------
		-- test
		-- ejemplo de como se calcula la cantidad sugerida para que sea multiplo del upb
		-- test
		--------------------------------------------------------------------------------------------------------------
		/*
		DECLARE @Residuo decimal(8,2)
		DECLARE @ValASumar decimal(8,2)
		DECLARE @cantidadsugerida2 integer
		DECLARE	@UPB2 integer

		select 	@cantidadsugerida2 = -73386.967742,
				@UPB2 =20

		set @Residuo=@cantidadsugerida2 % dbo.fnNoZDiv(@UPB2)
		--SELECT @Residuo
		IF @Residuo=0
		select @cantidadsugerida2
		ELSE
		select @cantidadsugerida2+(@UPB2-@Residuo)
		*/
		--------------------------------------------------------------------------------------------------------------


		--------------------------------------------------------
		-- Guardamos el upb del item
		DECLARE @litem_upb DECIMAL(18,4)

		SET	@litem_upb  = (SELECT
			ti.item_upb
			FROM tbItem									ti WITH (NOLOCK)
			WHERE	ti.comp_id	= @comp_id		AND
					ti.item_id	= @item_id)
		--------------------------------------------------------

		--------------------------------------------------------
		-- Calculo final con upb
		DECLARE @lqtywithupb DECIMAL(18,4)
		SET	@lqtywithupb  =
		CASE @qty % dbo.fnNoZDiv(@litem_upb)
			WHEN 0	THEN	@qty
			ELSE			@qty + ( @litem_upb - (@qty % dbo.fnNoZDiv(@litem_upb)))
		END
		--------------------------------------------------------

		--------------------------------------------------------
		-- Actualizamos la cantidad sugerida
		UPDATE tbComplexFilter
		SET
			sl_tmpData	= @lqtywithupb
		WHERE	sl_guid = @SelectionGuid AND
				sl_id	= @item_id
		--------------------------------------------------------


	END

GO




