CREATE PROCEDURE [dbo].[spComplexFilter_Supplier_getData]
(
	@guid				uniqueidentifier
)
as


	BEGIN


	set nocount on
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-------------------------------------------------------------------------
	/*
	declare	@guid				UNIQUEIDENTIFIER


	select	@guid				='45b7f584-70ae-4d17-981d-392a3b8c75e9'

    -------------------------------------------------------------------------
    */

	select	' '							[X0 ] ,
			tcf.sl_selected				[Selected],
			' '							[X1] ,
			' '							[X2] ,
			' '							[X3] ,
			ts.supp_name,
			ts.supp_taxNumber,
			ts.supp_address,
			ts.supp_city,
			tcf.sl_id					[ID]

	from	dbo.tbComplexFilter		tcf		WITH (NOLOCK)

	LEFT JOIN tbSupplier			ts		WITH (NOLOCK)
	ON tcf.sl_id = ts.supp_id

	WHERE tcf.sl_guid				=	@guid



END

GO





CREATE PROCEDURE [dbo].[spComplexFilter_Supplier_MixedFilters]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,

	@supp_id			INT,
	@country_id			INT,
	@state_id			INT,
	@fc_id				INT,
	@tnt_id				INT,
	@optionTaxNumber	INT,
	@supp_taxNumber		VARCHAR(50),
	@optionName			INT,
	@supp_Name			VARCHAR(100),
	@optionAddress		INT,
	@supp_Address		VARCHAR(100),
	@optionCity			INT,
	@supp_City			VARCHAR(100),
	@pt_id				INT,
	@puco_id			INT,
	@sk_id				INT,
	@SelectAll			BIT,
	@bitAddInTable		BIT
)

AS


-----------------------------------------------------------------------------

/*

DECLARE @comp_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@guid				UNIQUEIDENTIFIER,

		@country_id			INT,
		@state_id			INT,
		@fc_id				INT,
		@tnt_id				INT,
		@optionTaxNumber	INT,
		@supp_taxNumber		VARCHAR(50),
		@optionName			INT,
		@supp_Name			VARCHAR(100),
		@optionAddress		INT,
		@supp_Address		VARCHAR(100),
		@optionCity			INT,
		@supp_City			VARCHAR(100),
		@pt_id				INT,
		@puco_id			INT,
		@sk_id				INT,
		@SelectAll			BIT,
		@bitAddInTable		BIT



SELECT  @comp_id			= 1,
		@bra_id				= 1,
		@prof_id			= 1,
		@user_id			= 3,
		@guid				= '5b97a114-471a-4004-b361-e29c1ad2d742',

		@country_id			= -1,
		@state_id			= -1,
		@fc_id				= -1,
		@tnt_id				= -1,
		@optionTaxNumber	= -1,
		@supp_taxNumber		= '',
		@optionName			= 1,
		@supp_Name			= '',
		@optionAddress		= 1,
		@supp_Address		= '',
		@optionCity			= -1,
		@supp_City			= '',
		@pt_id				= -1,
		@puco_id			= -1,
		@sk_id				= -1,
		@SelectAll			= 0,
		@bitAddInTable		= 1

*/

-----------------------------------------------------------------------------




	SET NOCOUNT ON
		-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
		BEGIN
				-- -------------------------------------------------------------------------------------------------------------------------------------------------
				-- FILTRO por MixedFilters
				-- -------------------------------------------------------------------------------------------------------------------------------------------------
				DECLARE @tmpSuppMixedFilters TABLE(supp_id INT PRIMARY KEY)

				INSERT INTO @tmpSuppMixedFilters (supp_id)	SELECT
																ts.supp_id
				                                          	FROM tbSupplier ts

				                                          	WHERE	(@country_id		= -1 OR ts.country_id		= @country_id)		AND
				                                          			(@state_id			= -1 OR ts.state_id			= @state_id)		AND
				                                          			(@fc_id				= -1 OR ts.fc_id			= @fc_id)			AND
				                                          			(@tnt_id			= -1 OR ts.tnt_id			= @tnt_id)			AND
				                                          			(
																		(@optionTaxNumber = -1 )																OR
																		(@optionTaxNumber = 0	AND ts.supp_taxNumber LIKE			  @supp_taxNumber + '%')	OR
																		(@optionTaxNumber = 1	AND ts.supp_taxNumber LIKE		'%' + @supp_taxNumber + '%')	OR
																		(@optionTaxNumber = 2	AND ts.supp_taxNumber =				  @supp_taxNumber)			OR
																		(@optionTaxNumber = 3	AND ts.supp_taxNumber <>			  @supp_taxNumber)			OR
																		(@optionTaxNumber = 4	AND ts.supp_taxNumber NOT LIKE  '%' + @supp_taxNumber + '%')
				                                          			)																	AND
				                                          			(
																		(@optionName = -1 )																		OR
																		(@optionName = 0	AND ts.supp_name LIKE			  @supp_Name + '%')					OR
																		(@optionName = 1	AND ts.supp_name LIKE		'%' + @supp_Name + '%')					OR
																		(@optionName = 2	AND ts.supp_name =				  @supp_Name)						OR
																		(@optionName = 3	AND ts.supp_name <>				  @supp_Name)						OR
																		(@optionName = 4	AND ts.supp_name NOT LIKE   '%' + @supp_Name + '%')
				                                          			)																	AND
				                                          			(
																		(@optionAddress = -1 )																	OR
																		(@optionAddress = 0	AND ts.supp_address LIKE			  @supp_Address + '%')			OR
																		(@optionAddress = 1	AND ts.supp_address LIKE		'%' + @supp_Address + '%')			OR
																		(@optionAddress = 2	AND ts.supp_address =				  @supp_Address)				OR
																		(@optionAddress = 3	AND ts.supp_address <>				  @supp_Address)				OR
																		(@optionAddress = 4	AND ts.supp_address NOT LIKE	'%' + @supp_Address + '%')
				                                          			)																	AND
				                                          			(
																		(@optionCity = -1 )																	OR
																		(@optionCity = 0	AND ts.supp_city LIKE			  @supp_City + '%')				OR
																		(@optionCity = 1	AND ts.supp_city LIKE		'%' + @supp_City + '%')				OR
																		(@optionCity = 2	AND ts.supp_city =				  @supp_City)					OR
																		(@optionCity = 3	AND ts.supp_city <>				  @supp_City)					OR
																		(@optionCity = 4	AND ts.supp_city NOT LIKE	'%' + @supp_City + '%')
				                                          			)																	AND
				                                          			(@pt_id				= -1 OR ts.pt_id			= @pt_id)			AND
				                                          			(@puco_id			= -1 OR ts.puco_id			= @puco_id)			AND
				                                          			(@sk_id				= -1 OR ts.sk_id			= @sk_id)			AND
				                                          			(@supp_id			= -1 OR ts.supp_id			= @supp_id)


				-- -------------------------------------------------------------------------------------------------------------------------------------------------

				--SELECT * FROM @tmpSuppMixedFilters


				IF @bitAddInTable = 'True'
				BEGIN

					INSERT INTO tbComplexFilter
					(
						sl_guid,
						sl_id,
						sl_order,
						sl_selected
					)
					SELECT	@guid,
							ts.supp_id,
							0,
							@SelectAll
					FROM tbSupplier ts

						INNER JOIN @tmpSuppMixedFilters tmp
							ON tmp.supp_id	= ts.supp_id

						LEFT JOIN tbComplexFilter tcf
							ON	tcf.sl_guid = @guid		AND
								tcf.sl_id	= ts.supp_id

						WHERE	ts.comp_id	= @comp_id AND
								tcf.sl_guid IS NULL
				END
			ELSE
				BEGIN
					DELETE FROM tbComplexFilter
						FROM tbComplexFilter	tcf
						INNER JOIN tbSupplier ts
							ON	ts.comp_id = @comp_id AND
								ts.supp_id = tcf.sl_id
						INNER JOIN @tmpSuppMixedFilters tmp
							ON tmp.supp_id = ts.supp_id
						WHERE tcf.sl_guid = @guid
				END

				END
GO




