CREATE PROCEDURE [dbo].[spComplexFilter_Supplier_SupplierKind]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@sk_id				INT,
	@bitAddInTable		BIT,
	@SelectAll			BIT
AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@guid				UNIQUEIDENTIFIER,
			@sk_id				INT,
			@bitAddInTable		BIT


SELECT		@comp_id			=1,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@guid				='0352be36-5ca2-4b30-be44-8a2020c78c14',
			@sk_id				=1,
			@bitAddInTable		='True'
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------------
	-- FILTRO por Clase de Proveedor
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpSupplierKind TABLE(SuppId INT PRIMARY KEY)
	IF (@sk_id = -1)
		BEGIN
			INSERT INTO @tmpSupplierKind (SuppId)	SELECT	ts.supp_id
			                                        FROM tbSupplier ts

		END
	ELSE
		BEGIN
			INSERT INTO @tmpSupplierKind (SuppId)	SELECT ts.supp_id
                             						FROM tbSupplier ts
                                              		WHERE ts.sk_id = @sk_id
		END
	-- -------------------------------------------------------------------------------------


	IF @bitAddInTable = 'True'
		BEGIN

			INSERT INTO tbComplexFilter
			(
				sl_guid,
				sl_id,
				sl_order,
				sl_selected
			)
			SELECT	@guid,
					ts.supp_id,
					0,
					@SelectAll
			FROM tbSupplier ts
				INNER JOIN @tmpSupplierKind tmp
					ON tmp.SuppId	= ts.supp_id
				LEFT JOIN tbComplexFilter tcf
					ON	tcf.sl_guid = @guid AND
						tcf.sl_id	= ts.supp_id
				WHERE	ts.comp_id	= @comp_id AND
						tcf.sl_guid IS NULL
		END
	ELSE
		BEGIN
			DELETE FROM tbComplexFilter
				FROM tbComplexFilter	tcf
				INNER JOIN tbSupplier ts
					ON	ts.comp_id = @comp_id AND
						ts.supp_id = tcf.sl_id
				INNER JOIN @tmpSupplierKind tmp
					ON tmp.SuppId = ts.supp_id
				WHERE tcf.sl_guid = @guid
		END






END
GO




