CREATE PROCEDURE [dbo].[spComplexFilters_GetItems4ItemPublication]
(
	@Guid	UNIQUEIDENTIFIER
)
AS

	SET NOCOUNT ON

		BEGIN
			-- ----------------------------------------
			-- TESTING
			-- ----------------------------------------
			/*
				DECLARE	@Guid	UNIQUEIDENTIFIER


				SELECT @Guid = '9a902676-27b1-4c87-852d-36bddfb0e00e'
			*/
			-- ----------------------------------------

			SELECT
				tcf.sl_id			--ITEM_ID

			FROM tbComplexFilter					tcf		WITH (NOLOCK)

			INNER JOIN tbItem					ti		WITH (NOLOCK)
			ON ti.item_id	= tcf.sl_id

			WHERE	tcf.sl_guid		= @Guid	AND
					tcf.sl_selected = 'True'
		END

GO



CREATE PROCEDURE [dbo].[spComplexFilters_GetItems4PurchaseOrder]
(
	@SelectionGuid	UNIQUEIDENTIFIER,
	@item_id		INT
)
AS
	SET NOCOUNT ON

		BEGIN
			-- ----------------------------------------
			-- TESTING
			-- ----------------------------------------
			/*
				DECLARE
					@SelectionGuid	UNIQUEIDENTIFIER,
					@item_id		INT
			*/
			-- ----------------------------------------

			SELECT
				tcf.sl_id,			--ITEM_ID
				tcf.sl_tmpData,		--ITEM_QTY
				ti.supp_id	,		--SUPP_ID
				ISNULL(ti.item_repositionTime,0)			[item_repositionTime],
				ISNULL(ti.item_repositionInternalDays,0)	[item_repositionInternalDays]

			FROM tbComplexFilter					tcf		WITH (NOLOCK)

			INNER JOIN tbItem						ti		WITH (NOLOCK)
				ON ti.item_id	= tcf.sl_id

			WHERE	tcf.sl_guid = @SelectionGuid	AND
					(@item_id	= -1 OR tcf.sl_id = @item_id)	AND
					ti.supp_id IS NOT NULL

			ORDER BY ti.supp_id


		END

GO





