(
	@SelectionGuid	UNIQUEIDENTIFIER,
	@item_id		INT
)
AS

	SET NOCOUNT ON

		BEGIN
			-- ----------------------------------------
			-- TESTING
			-- ----------------------------------------
			/*
				DECLARE
					@SelectionGuid	UNIQUEIDENTIFIER,
					@item_id		INT





			select
					@SelectionGuid  = '37eb3feb-5fa1-4f62-be04-1167f69a522f',
