		END

GO



CREATE PROCEDURE [dbo].[spComplexFilters_UpdateCheckStatus]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@sl_id		INT,
	@option		INT
)
AS

	SET NOCOUNT ON
		-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

		BEGIN
			--SI ES 1 CHECKEAMOS O DESCHECKEAMOS
			IF @option = 1
				UPDATE tbComplexFilter		WITH (ROWLOCK)
				SET
					sl_selected = ~ISNULL(sl_selected,'False')
				WHERE	sl_guid	= @guid	AND
						sl_id	= @sl_id
			ELSE
				--SI ES 2 CHECKEAMOS TODOS
				IF @option = 2
					UPDATE tbComplexFilter	WITH (ROWLOCK)
					SET
						sl_selected = 'True'
					WHERE sl_guid = @guid

				ELSE
					--DESCHECKEAMOS TODOS
					IF @option = 3
						UPDATE tbComplexFilter	WITH (ROWLOCK)
						SET
							sl_selected = 'False'
						WHERE sl_guid = @guid
					ELSE
						--INVERTIMOS SELECCIÓN
						IF @option = 4
							UPDATE tbComplexFilter	WITH (ROWLOCK)
							SET
								sl_selected = ~ISNULL(sl_selected,'False')
							WHERE sl_guid = @guid



		END
GO




