Create PROCEDURE [dbo].[spContact_getDataByText]
(
	@text		VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id	 AS int
)
AS

BEGIN

	SET NOCOUNT ON

	/*
	DECLARE
		@text		VARCHAR(300),
		@count		INT,
		@lang_id	INT
	SELECT
		@text		= 'R',
		@count		= 2,
		@lang_id	= 2

	*/

	SELECT		TOP (@count)
				dbo.fnStrPADR(	ta.contact_name,40,'.') + ' | ' + isnull(convert(varchar,ta.contact_id),'') [contact_desc],
				ta.contact_id

		FROM tbContact 		  ta		WITH (NOLOCK)

		WHERE		comp_id = @comp_id				AND
				   (	ta.contact_name LIKE '%' + @text + '%'
						OR
						ta.contact_desc LIKE @text+'%'
				   )

		ORDER BY	ta.contact_name

END
GO






create PROCEDURE [dbo].[spContact_getDataForMail]
(
	@comp_id		INT,
	@guid			UNIQUEIDENTIFIER
)
AS
SET NOCOUNT ON

/*
DECLARE
	@comp_id	INT,
	@country_id	INT,
	@state_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@pQuestion	BIT

SELECT
	@comp_id	= 1,
	@country_id	= -1,--54,
	@state_id	= -1,--54011,
	@guid		= '04af870b-a20b-41f6-a373-3949b02b640e',
	@pQuestion	= 'True'
*/

SELECT	tc.contact_email

FROM	tbContact 								tc

		INNER JOIN tbMail_Recipients			tmr
		ON	tc.comp_id			= tmr.comp_id
		AND tc.contact_id		= tmr.mr_recipientId
		AND tmr.guid			= @guid

WHERE	tc.comp_id		=	@comp_id
AND		NOT tc.contact_email IS NULL
AND		tc.contact_email	<>	''
AND		tmr.mr_checked	=	'True'
GO






create PROCEDURE [dbo].[spContact_getMailingList]
(
	@comp_id		INT,
	@where			VARCHAR(8000),
	@guid			UNIQUEIDENTIFIER,
	@pQuestion		BIT					-- TRUE = DESCHECKEA // FALSE = MANTIENE LOS QUE YA ESTABAN CHECKEADOS
)
AS

BEGIN

	SET NOCOUNT ON

	-- ----------------------------------------------------------
	-- testing
	-- ----------------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@where		VARCHAR(8000),
		@guid		UNIQUEIDENTIFIER,
		@pQuestion	BIT

	SELECT
		@comp_id	= 1,
		@where		= '((-1 = -1) or ([country_id] = ''-1''))  ',
		@guid		= 'a7a0b132-379d-4954-8106-75ae9680715b',
		@pQuestion	= 'True'
	*/
	-- ----------------------------------------------------------

	-- Verifica que la tabla tbMail_Recipients tenga algo
	IF NOT EXISTS(	SELECT 1
						FROM tbMail_Recipients tmr WITH (NOLOCK)
	              		WHERE	tmr.comp_id = @comp_id AND
	              				tmr.guid	= @guid)
		BEGIN
			INSERT INTO tbMail_Recipients
				(	comp_id,		[guid],		mr_checked,		mr_recipientId	)
					SELECT	tc.comp_id,
							@guid ,
							'False',
							tc.contact_id
					FROM tbContact  tc WITH (NOLOCK)
		END


	DECLARE @strWhere VARCHAR(8000)
	SET @strWhere = ' WHERE tmr.comp_id = ' + convert( varchar(10),@comp_id) + ' AND tmr.guid = ''' +  CAST(@guid AS VARCHAR(36))  + ''''


	If @pQuestion = 'True'
		BEGIN

			EXEC (	'UPDATE tbMail_Recipients
						SET	mr_checked = 0
						FROM tbMail_Recipients tmr
						 ' + @strWhere )
		END


	IF CHARINDEX('=', @where) > 0 SET @strWhere = @strWhere + ' and ' + @where


	CREATE TABLE #tmpContactFiltered (contact_id INT PRIMARY KEY)

	DECLARE @strAux AS VARCHAR(MAX)
	SET @strAux = CASE
			              WHEN	@where = '' THEN '1 = 1'
			              ELSE	@where
			          END
	EXEC ( '
	INSERT INTO #tmpContactFiltered
		SELECT contact_id
			FROM tbContact 	WITH (NOLOCK)
			WHERE ' + @strAux
		)



	SELECT	' ' [ ],
			tmr.mr_checked,
			tc.contact_name,
			tc.contact_email,
			tc2.country_desc,
			ts.state_desc,
			tmr.mr_id			[ID]
			FROM	tbMail_Recipients						tmr				WITH (NOLOCK)
					INNER JOIN tbContact  					tc				WITH (NOLOCK)
					ON	tmr.comp_id			= tc.comp_id	AND
						tmr.mr_recipientId	= tc.contact_id
					INNER JOIN tbsysCountry					tc2				WITH (NOLOCK)
					ON	tc2.country_id		= tc.country_id
					INNER JOIN tbsysState					ts				WITH (NOLOCK)
					ON  ts.country_id		= tc.country_id	AND
						ts.state_id			= tc.state_id
					INNER JOIN #tmpContactFiltered			tmp
						ON tmp.contact_id	= tmr.mr_recipientId
			WHERE	tmr.comp_id				= @comp_id		AND
					tmr.guid				= @guid

					--AND
					--ISNULL(tc.cust_excludeOfCustomerMailing,'False')	<> 'True'
			DROP TABLE #tmpContactFiltered

END
GO










