CREATE PROCEDURE [dbo].[spContacts_Process_Auto]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@bra_id						INT,
	@contact_name				NVARCHAR(200),
	@contact_desc				NVARCHAR(2000),
	@contact_address			NVARCHAR(200),
	@contact_city				NVARCHAR(60),
	@contact_zip				NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@contact_phone				NVARCHAR(100),
	@contact_email				NVARCHAR(200),
	@contact_BirthDate			DATETIME,
	@sm_Id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@contact_taxNumber			NVARCHAR(50),
	@conclass_id				INT,
	@cust_id					INT,
	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT


)
AS


---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@bra_id						INT,
	@contact_name				NVARCHAR(200),
	@contact_desc				NVARCHAR(2000),
	@contact_address			NVARCHAR(200),
	@contact_city				NVARCHAR(60),
	@contact_zip				NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@contact_phone				NVARCHAR(100),
	@contact_email				NVARCHAR(200),
	@contact_BirthDate			DATETIME,
	@sm_Id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@contact_taxNumber			NVARCHAR(50),
	@conclass_id				INT,
	@cust_id					INT,
	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT


SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id4session				= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,

	@bra_id						= -1 ,
	@contact_name				='dasasdasdasdasdasdasdasdasdl',
	@contact_desc				= '',
	@contact_address			= '',
	@contact_city				= '',
	@contact_zip				= '',
	@country_id					= 54 ,
	@state_id					= 54001,
	@contact_phone				='47685588',
	@contact_email				='asdasd@lflelfe.com.ar',
	@contact_BirthDate			='08/10/2016',
	@sm_Id						= 10 ,
	@fc_id						= -1 ,
	@tnt_id						= -1 ,
	@contact_taxNumber			= '',
	@conclass_id				= -1 ,
	@cust_id					= -1 ,

	@bolIsOK					='True',
	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 1000

---------------------------------------------------------------------------------
*/
SET NOCOUNT ON
SET DATEFORMAT 'YMD'


BEGIN
	declare @return_value	INT

	if	@bra_id			= -1  SET @bra_id		= NULL
	if	@conclass_id	= -1  SET @conclass_id	= NULL
	if	@cust_id		= -1  SET @cust_id		= NULL
	if	@fc_id			= -1  SET @fc_id		= NULL
	if	@tnt_id			= -1  SET @tnt_id		= NULL


				BEGIN TRY

					INSERT INTO tbContact
					(
						comp_id,
						bra_id,
						contact_name,
						contact_desc,
						contact_address,
						contact_city,
						contact_zip,
						country_id,
						state_id,
						contact_phone,
						contact_email,
						contact_BirthDate,
						sm_id,
						fc_id,
						tnt_id,
						contact_taxNumber,
						cust_id,
						conclass_id
					)
					VALUES
					(
						@comp_id,
						@bra_id,
						@contact_name,
						@contact_desc,
						@contact_address,
						@contact_city,
						@contact_zip,
						@country_id,
						@state_id,
						@contact_phone,
						@contact_email,
						@contact_BirthDate,
						@sm_id,
						@fc_id,
						@tnt_id,
						@contact_taxNumber,
						@cust_id,
						@conclass_id
					)

					set	@return_value = IDENT_CURRENT('tbContact')   -- @@identity

					END TRY
					BEGIN CATCH
						set	@return_value = 0
					END CATCH

					IF @return_value <> 0
						BEGIN
							--EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,@return_value,NULL

							EXEC [spSysScript_Contacts_Cities]


						END



END


















GO





