CREATE PROCEDURE [dbo].[spContacts_Process_Auto_Validate]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@bra_id						INT,
	@contact_name				NVARCHAR(200),
	@contact_desc				NVARCHAR(2000),
	@contact_address			NVARCHAR(200),
	@contact_city				NVARCHAR(60),
	@contact_zip				NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@contact_phone				NVARCHAR(100),
	@contact_email				NVARCHAR(200),
	@contact_BirthDate			DATETIME,
	@sm_Id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@contact_taxNumber			NVARCHAR(50),
	@conclass_id				INT,
	@cust_id					INT,
	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@curr_id					INT,
	@supp_name					NVARCHAR(200),
	@supp_name1					NVARCHAR(200),
	@supp_address				NVARCHAR(150),
	@supp_city					NVARCHAR(60),
	@supp_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@supp_phone1				NVARCHAR(200),
	@supp_phone2				NVARCHAR(200),
	@supp_fax					NVARCHAR(200),
	@supp_email					NVARCHAR(300),
	@pt_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@supp_taxNumber				NVARCHAR(50),
	@stcIB_Id					INT,
	@supp_taxIBNumber			NVARCHAR(50),
	@supp_web					NVARCHAR(500),
	@supp_partnerOf				NVARCHAR(100),
	@supp_contact				NVARCHAR(100),
	@supp_eMail_PurchaseSector	NVARCHAR(4000),
	@supp_annotation			NVARCHAR(100),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT



SELECT
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@curr_id					INT,
	@cust_name					NVARCHAR(200),
	@cust_name1					NVARCHAR(200),
	@cust_address				NVARCHAR(150),
	@cust_city					NVARCHAR(60),
	@cust_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@cust_phone1				NVARCHAR(200),
	@cust_phone2				NVARCHAR(200),
	@cust_fax					NVARCHAR(200),

	@st_id						INT,
	@disc_id					INT,
	@dl_id						INT,
	@ck_id						INT,
	@sm_id						INT,
	@act_id						INT,
	@ss_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@cust_taxNumber				NVARCHAR(50),
	@cust_inactive				BIT,
	@stcIB_Id					INT,
	@cust_taxIBNumber			NVARCHAR(50),
	@cust_web					NVARCHAR(500),
	@cust_partnerOf				NVARCHAR(100),
	@cust_contact				NVARCHAR(100),
	@cust_email					NVARCHAR(300),
	@cust_credit_max			NUMERIC(17,2),
	@cust_credit_own			NUMERIC(17,2),
	@cust_note1					NVARCHAR(100),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------


set nocount on

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''



	------Nombre de Contacto-----------------------------------------------------------------------------------------------------------
	if	@contact_name	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Nombre del Contacto'
		END
	-----------------------------------------------------------------------------------------------------------------------
	--------Localidad-----------------------------------------------------------------------------------------------------------
	--if	@contact_city	= ''
	--	BEGIN
	--		SET	@bolIsOK		= 'False'
	--		SET @errormessage	= @errormessage + '---' + 'No ingresó la Localidad'
	--	END
	-------------------------------------------------------------------------------------------------------------------------

	------Pais-----------------------------------------------------------------------------------------------------------
	if	@country_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID País'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.country_id
			               FROM tbsysCountry		tc		WITH (NOLOCK)
							WHERE	tc.country_id		= @country_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de País es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Provincia-----------------------------------------------------------------------------------------------------------
	if	@state_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Provincia'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.state_id
			               FROM tbsysState 	tc		WITH (NOLOCK)
			               WHERE tc.country_id = @country_id and
			               		 tc.state_id   = @state_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Provincia es incorrecto o no está relacionada al País'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------


	------Telefono-----------------------------------------------------------------------------------------------------------
	if	@contact_phone 	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Teléfono'
		END
	-----------------------------------------------------------------------------------------------------------------------


	------EMAIL-----------------------------------------------------------------------------------------------------------
	if	@contact_email	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Email'
		END
	-----------------------------------------------------------------------------------------------------------------------


	------Vendedor-----------------------------------------------------------------------------------------------------------
	if	@sm_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Vendedor'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT ts.sm_id
			               FROM tbSalesman ts		WITH (NOLOCK)
			               WHERE ts.comp_id = @comp_id and
			               		 ts.sm_id   = @sm_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Vendedor es incorrecto'
				END
		END

	-------------------------------------------------------------------------------------------------------------------------

	------Cliente-----------------------------------------------------------------------------------------------------------
	if	@cust_id <> -1
		BEGIN
			IF NOT EXISTS (SELECT ts.cust_id
						   FROM tbCustomer ts		WITH (NOLOCK)
							   WHERE ts.comp_id		= @comp_id and
		               				 ts.cust_id		= @cust_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Cliente es incorrecto'
					END
		END

	-------------------------------------------------------------------------------------------------------------------------


	--------Clase Fiscal -----------------------------------------------------------------------------------------------------------
	--if	@fc_id	= -1
	--	BEGIN
	--		SET	@bolIsOK		= 'False'
	--		SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Clase Fiscal'
	--	END
	--ELSE
	--	BEGIN
	--		IF NOT EXISTS (SELECT tfc.fc_id
	--		               FROM tbsysFiscalClass tfc		WITH (NOLOCK)
	--		               WHERE tfc.fc_id			= @fc_id AND
	--							 tfc.country_id		= @country_id)
	--			BEGIN
	--				SET	@bolIsOK		= 'False'
	--				SET @errormessage	= @errormessage + '---' + 'El ID de Clase Fiscal es incorrecto o no corresponde al País adecuado'
	--			END
	--	END

	-------------------------------------------------------------------------------------------------------------------------

	--------Tipo de Documento-----------------------------------------------------------------------------------------------------------
	--if	@tnt_id	= -1
	--	BEGIN
	--		SET	@bolIsOK		= 'False'
	--		SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Tipo de Documento'
	--	END
	--ELSE
	--	BEGIN
	--		IF NOT EXISTS (SELECT ttnt.tnt_id
	--		               FROM tbsysTaxNumberTypes								ttnt		WITH (NOLOCK)
	--		               INNER JOIN tbsysFiscalClassAvailableTaxNumberTypes	sfcatnt		WITH (NOLOCK)
	--					   ON sfcatnt.tnt_id	=	ttnt.tnt_id

	--		               WHERE ttnt.tnt_id	= @tnt_id AND
	--							 sfcatnt.fc_id	= @fc_id)
	--			BEGIN
	--				SET	@bolIsOK		= 'False'
	--				SET @errormessage	= @errormessage + '---' + 'El ID de Tipo de Documento es incorrecto o no corresponde a la Clase Fiscal adecuada'
	--			END
	--	END

	-------------------------------------------------------------------------------------------------------------------------


	--------Nro de Doc-----------------------------------------------------------------------------------------------------------
	--if	@supp_taxNumber	= ''
	--	BEGIN
	--		SET	@bolIsOK		= 'False'
	--		SET @errormessage	= @errormessage + '---' + 'No ingresó # Identificación tributaria'
	--	END
	--ELSE
	--	BEGIN
	--		IF EXISTS (SELECT tc.supp_id
	--		           FROM	 tbSupplier 			tc		WITH (NOLOCK)
	--		           WHERE tc.comp_id			= @comp_id			AND
	--		                 tc.supp_taxNumber	= @supp_taxNumber	AND
	--		                 tc.tnt_id			= @tnt_id)
	--				 BEGIN
 --                		SET	@bolIsOK		= 'False'
	--					SET @errormessage	= @errormessage + '---' + '# Identificación tributaria(Con mismo Tipo de Documento) ya existe ' + @supp_taxNumber
	--				 END

	--			--END
	--	END

	-------------------------------------------------------------------------------------------------------------------------


	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO



----------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Date   :04/08/16
-- Author : GA
-- Detail : Al finalizar el proceso de importacion se muestra en una grilla que registros fueron dados de alta y los que no.
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
create PROCEDURE [dbo].[spContacts_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN



	SELECT
			isnull(tc.contact_name,'')								[contact_name],
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbContact 								tc		WITH (NOLOCK)
		ON	tc.comp_id		= tpclil.comp_id	AND
			tc.contact_id	= tpclil.item_id

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO







CREATE PROCEDURE [dbo].[spContainer_getCombo]
(
	@comp_id			int,
	@bra_id				INT,
	@cont_id			int
)
AS

BEGIN

	set nocount on

	select		cont_id		[id],
				cont_desc	[desc]

		from		[tbContainer] cont

		where	(	comp_id		= @comp_id	AND
					bra_id		= @bra_id	AND
				   (
				   		( cont.cont_isAvailable4Selection = 'True' AND cont.cont_isClosed = 'False')
				   	)
				)
				OR
				( cont.cont_id = @cont_id )
		Order By	cont_desc


END




GO





CREATE PROCEDURE [dbo].[spControlPanel_CheckAndCalculate]
(
		@scpm_id	INT,
		@hour		BIT,
		@day		BIT,
		@week		BIT,
		@weekday	INT,
		@month		BIT,
		@monthday	INT
)
as set nocount on


-- --------------------------------------------
--
-- --------------------------------------------
/*
	DECLARE
		@scpm_id	INT,
		@hour		BIT,
		@day		BIT,
		@week		BIT,
		@weekday	INT,
		@month		BIT,
		@monthday	INT
	SELECT
		@scpm_id	= 1,
		@hour		= 'False',
		@day		= 'False',
		@week		= 'False',
		@weekday	= 3,
		@month		= 'True',
		@monthday	= 24
*/
-- --------------------------------------------

declare
	@getdate	DATETIME
set @getdate = getdate()

select
	datediff(hour,tcph.cph_cd,@getdate),
	datediff(month,tcph.cph_cd,@getdate),
	datepart(day,tcph.cph_cd)
from tbControlPanelHistory tcph


	if not exists	(
					select top 1 1 from tbControlPanelHistory tcph
					where	tcph.scpm_id = @scpm_id
					and	(
						(@hour	= 'True' and datediff(hour,tcph.cph_cd,@getdate)  < 0 )												or
						(@day	= 'True' and datediff(day,tcph.cph_cd,@getdate)   < 0 )												or
						(@week	= 'True' and datediff(week,tcph.cph_cd,@getdate)  > 0 and @weekday  = datepart(weekday,tcph.cph_cd))	or
						(@month = 'True' and datediff(month,tcph.cph_cd,@getdate) > 0 and @monthday = datepart(day,tcph.cph_cd))
						)

				)

				select 'Procesa'

else
				select 'No Procesa'
GO






CREATE PROCEDURE [dbo].[spControlPanel_getDataByFilters]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@brag_id		INT,
	@cpmc_id		INT,
	@dateFrom		DATETIME,
	@dateTo			DATETIME,
	@dateActual		DATETIME,
	@option			INT,
	@user_id		INT

)
AS

SET NOCOUNT ON

SET DATEFORMAT 'ymd'


/*
DECLARE
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@brag_id		INT,
	@prof_id		INT,
	@cpmc_id		INT,
	@dateFrom		DATETIME,
	@dateTo			DATETIME,
	@dateActual		DATETIME,
	@option			INT

SELECT
	@comp_id		= 1,
	@lang_id		= 2,
	@bra_id			= 1,
	@prof_id		= 1,
	@brag_id		= -1,
	@cpmc_id		= -1,
	@dateFrom		= '2000/01/01',
	@dateTo			= '2009/12/31',
	@dateActual		= '2009/04/09',
	@option			= 1

DROP TABLE #tmpControlPanelMeasures
*/



IF DATEPART(hh,@dateto) = 0
	set	@dateto	= @dateto + '23:59:59'


/*Creamos la tabla en donde se insertaran los resultados del cursor*/
CREATE TABLE #tmpControlPanelMeasures
	(	[Id]			int,
		[Id1]			int,
		[indicador]		varchar(200),
		[total]			decimal(19,5),
		[scpm_id]		int)


DECLARE @lscpm_id	INT
DECLARE @query		VARCHAR(8000)
DECLARE @case_id	INT
DECLARE @rank		INT

DECLARE cursor_CP_gDBF  CURSOR FOR
/*Select que recupera el Id y el Nombre del Stored Procedure a guardar en el cursor, para luego
* ejecutarlo y grabar el resultado en la tabla temporal*/
SELECT		tcpmp.scpm_id,
			tcpm.scpm_SPName4Total,
			tcpm.scpm_case,
			tcpm.scpm_rank

FROM		dbo.tbControlPanelMeasures4Profiles tcpmp

			INNER JOIN	dbo.tbsysControlPanelMeasures tcpm
			ON			tcpm.scpm_id	=	tcpmp.scpm_id

WHERE		(@cpmc_id = -1 or tcpmp.cpmc_id	= @cpmc_id)
AND			(@brag_id = -1 or tcpmp.brag_id	= @brag_id)
AND			tcpmp.prof_id	= @prof_id


open cursor_CP_gDBF


FETCH cursor_CP_gDBF INTO @lscpm_id, @query, @case_id, @rank


WHILE @@FETCH_STATUS = 0
BEGIN


	/*EXEC que ejecuta el nombre del stored procedure obtenido en el Select anterior, con el pasaje
	* de parametros necesario*/


--  	SET @time2 = GETDATE()
--  	SELECT @time2-@time, @query, @comp_id, @bra_id, @brag_id,@dateFrom, @dateTo, @dateActual, @lscpm_id, @case_id, @rank ,@user_id
--	SET @time = GETDATE()

	IF @case_id IN (4,8)
		EXEC @query @comp_id, @bra_id, @brag_id,@dateFrom, @dateTo, @dateActual, @lscpm_id, @case_id, @rank ,@user_id
	ELSE
		IF @case_id IN (1,2,3,5,6,7)
			EXEC  @query @comp_id, @bra_id, @brag_id,@dateFrom, @dateTo, @dateActual, @lscpm_id, @case_id ,@user_id


	FETCH NEXT	FROM cursor_CP_gDBF INTO @lscpm_id, @query, @case_id, @rank
END

close cursor_CP_gDBF
deallocate cursor_CP_gDBF
/*Fin del Cursor*/

--SELECT * FROM #tmpControlPanelMeasures
/*-------------------------------------------------------------------------------------------------------*/


/*Select que devuelve los valores necesarios para la carga de la grilla, se joinea con la tabla temporal
* utilizando los id's de la misma para poder identificar a que indicador pertenece cada resultado obtenido*/
SELECT 	' ' [ ],
		ISNULL(tov.optval_desc,'')		[cpm4p_desc], -- tcpmp.cpm4p_desc,

		CASE WHEN tmp.Id = -1	THEN	(SELECT tut.utexts_desc
		                     	    	   FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = tmp.indicador)
								ELSE	tmp.indicador
		END					[Indicator],


		tmp.total,
		tcpmp.cpm4p_max,
		tcpmp.cpm4p_med,
		tcpmp.cpm4p_min,
		tcpmc.cpmc_desc,
		tbg.brag_desc,
		tb.bra_desc,
		CONVERT(VARCHAR,tbg.brag_id)				+ '|' +
		CONVERT(VARCHAR,tcpm.scpm_id)				+ '|' +
		CONVERT(VARCHAR,tmp.id)						[ID]

FROM	dbo.tbControlPanelMeasures4Profiles				tcpmp

		INNER JOIN	dbo.tbsysControlPanelMeasures		tcpm
		ON			tcpm.scpm_id	=	tcpmp.scpm_id

		INNER JOIN	dbo.tbControlPanelMeasureCategories tcpmc
		ON			tcpmc.comp_id	=	tcpmp.comp_id
		AND			tcpmc.cpmc_id	=	tcpmp.cpmc_id

		INNER JOIN	dbo.tbBranchGroup					tbg
		ON			tbg.comp_id		=	tcpmp.comp_id
		AND			tbg.brag_id		=	tcpmp.brag_id

		INNER JOIN	dbo.tbBranchGroupDetail				tbgd
		ON			tbgd.comp_id	=	tbg.comp_id
		AND			tbgd.brag_id	=	tbg.brag_id

		INNER JOIN	dbo.tbBranch						tb
		ON			tb.comp_id		=	tbgd.comp_id
		AND			tb.bra_id		=	tbgd.bra_id

		INNER JOIN	dbo.tbProfile						tp
		ON			tp.comp_id		=	tcpmp.comp_id
		AND			tp.prof_id		=	tcpmp.prof_id

		INNER JOIN	#tmpControlPanelMeasures			tmp
		ON			tmp.scpm_id		=	tcpm.scpm_id
		AND			tmp.Id1			=	tb.bra_id

		LEFT JOIN	tbsysOptionsValues					tov
		ON			tov.lang_id		=	@lang_id
		AND			tov.optval_id	=	tcpm.scpm_id
		AND			tov.optval_class=	58

WHERE	tcpmp.comp_id	=	@comp_id
AND     tbgd.bra_id		= @bra_id
AND		(@brag_id		=	-1		or		 tcpmp.brag_id  = @brag_id)
AND		(@cpmc_id		=   -1		or		 tcpmp.cpmc_id	= @cpmc_id)
AND		((@option = 1  and tmp.total <		 tcpmp.cpm4p_min ) or
		 (@option = 2  and tmp.total >		 tcpmp.cpm4p_max ) or
		 (@option = 3  AND tmp.total BETWEEN tcpmp.cpm4p_min AND tcpmp.cpm4p_max) or
		 (@option = -1)
		)

ORDER BY 2

--Insert en tbControlPanelHistory...
exec [spControlPanelHistory_insertData] @comp_id,@lang_id,@bra_id,@brag_id,@cpmc_id,@dateFrom,@dateTo,@dateActual,@option,@user_id


GO

