CREATE PROCEDURE [dbo].[spControlPanelGraphics_getAverageTicketBySalesTerms]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@brag_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME
)
AS


	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME,
				@brag_id			INT,
				@lang_id			INT = 2
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@datefrom			= '2021-01-01',
				@dateto				= '2024-10-31',
				@brag_id			= 4

				--DROP TABLE #tmp
		*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto	= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


		--RECUPERO LA MONEDA DE LA SUCURSAL
		DECLARE
			@lbra_curr_id	INT
		SELECT
			@lbra_curr_id		= tb.curr_id
			FROM tbBranch					AS tb	WITH(NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

	SELECT
		tst.st_desc,
		SUM(dbo.fnGetExchange2(@comp_id, tct.ct_subtotal, tct.curr_id_transaction, @lbra_curr_id,  tct.curr_id4Exchange,tct.curr_id_transaction, tct.ct_curr_IdExchange,'False') *
		vctfs.PlusOrMinus)									[Facturado],
		COUNT(*)											[totalInvoices]
		INTO												#tmp
		FROM tbCommercialTransactions						tct		WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forSalesStats	vctfs	WITH(NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id		AND
				vctfs.bra_id			= tct.bra_id		AND
				vctfs.ct_transaction	= tct.ct_transaction
		INNER JOIN tbSalesTerms								AS tst	WITH(NOLOCK)
			ON	tst.comp_id				= tct.comp_id		AND
				tst.st_id				= tct.st_id
		INNER JOIN tbUsers4BranchFilter						vubf	WITH(NOLOCK)
			ON  vubf.comp_id			= tct.comp_id		AND
				vubf.bra_id				= tct.bra_id		AND
				vubf.[user_id]			= @user_id
		INNER JOIN tbBranchGroupDetail						AS tbgd	WITH(NOLOCK)
			ON	tbgd.comp_id			= tct.comp_id		AND
				tbgd.brag_id			= @brag_id			AND
				tbgd.bra_id				= tct.bra_id
		WHERE tct.[comp_id] = @comp_id						AND
			(
				vctfs.sd_id = 1 OR
				vctfs.sd_id = 3
			)												AND
			tct.ct_date  BETWEEN @datefrom AND @dateto
		GROUP BY tst.st_desc

		DECLARE
			@total DECIMAL(19,2)
		SET @total = (SELECT SUM(temp.[Facturado]) [Total] from #tmp temp)

		-- ==
			--SELECT @total
		-- ==

  --SELECT * FROM #tmp
  --
  --return



		SELECT
			temp.st_desc,
			SUM(temp.[Facturado] / totalInvoices)														[Facturado],  -- Ticket Promedio
			RANK() OVER (ORDER BY SUM(temp.[Facturado] / dbo.fnNoZDiv(temp.totalInvoices)) DESC)		[Puesto Nro],
			(SUM(temp.[Facturado]/dbo.fnNoZDiv(@total) / dbo.fnNoZDiv(temp.totalInvoices) * 100))      [Porcent]
			FROM	#tmp											temp
			WHERE [Facturado] >= 0
			GROUP BY temp.st_desc
			ORDER BY [Facturado] DESC

		DROP TABLE #tmp

	END
GO

CREATE PROCEDURE [dbo].[spControlPanelGraphics_getCustomerClaims]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@brag_id			INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@datefrom			= '2021-01-01',
				@dateto				= '2021-10-31'
		*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto	= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')



		SELECT
			COUNT(*)			[Cantidad],
			CASE tmlc.[type]
				WHEN	'cancel_purchase'	THEN	'Cancelación de Compra'
				WHEN	'mediations'		THEN	'Mediación'
				WHEN	'cancel_sale'		THEN	'Cancelación de Venta'
				WHEN	'returns'			THEN	'Devolución'
				WHEN	'fulfillment'		THEN	'Fulfillment'
			ELSE									tmlc.[type]
			END										[type],

			CASE tmlc.stage
				WHEN	'claim'				THEN	'Reclamo'
				WHEN	'dispute'			THEN	'Disputa'
				WHEN	'none'				THEN	'Ninguno'
				WHEN	'recontact'			THEN	'Contactar'
			ELSE									tmlc.stage
			END										[stage],

			CASE tmlc.[status]
				WHEN	'opened'			THEN	'Abierta'
				WHEN	'closed'			THEN	'Cerrada'
			ELSE									tmlc.[status]
			END										[status],

			CASE tmlc.[resource]
				WHEN	'order'			THEN	'Ordenes'
				WHEN	'shipment'		THEN	'Envío'
				WHEN	'payment'		THEN	'Pagos'
			ELSE								tmlc.[resource]
			END										[resource]

			FROM tbMercadoLibre_Claims				AS tmlc		WITH(NOLOCK)
			INNER JOIN tbMercadoLibre_ordersHeader	AS tmloh	WITH(NOLOCK)
				ON	tmloh.comp_id	= tmlc.comp_id	AND
					tmloh.mlo_id	= tmlc.mlo_id
			WHERE	tmlc.comp_id = @comp_id			AND
					tmloh.ML_date_created BETWEEN @datefrom AND @dateto
			GROUP BY	tmlc.[type],
						tmlc.stage,
						tmlc.[status],
						tmlc.[resource]
			ORDER BY [Cantidad] DESC, [type]

	END
GO

CREATE PROCEDURE [dbo].[spControlPanelGraphics_getCustomerRanking]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@brag_id			int
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@datefrom			= '2021-01-01',
				@dateto				= '2021-10-31'

				DROP TABLE #tmp
		*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto	= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


		--RECUPERO LA MONEDA DE LA SUCURSAL
		DECLARE
			@lbra_curr_id	INT
		SELECT
			@lbra_curr_id		= tb.curr_id
			FROM tbBranch					AS tb	WITH(NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

	SELECT
		tc.cust_id,
		tc.cust_name,

		dbo.fnGetExchange2(@comp_id, tct.ct_subtotal, tct.curr_id_transaction, @lbra_curr_id,  tct.curr_id4Exchange,tct.curr_id_transaction, tct.ct_curr_IdExchange,'False') *
		CASE
			WHEN vctfs.sd_id  =3    THEN -1
		ELSE           1
		END													[Facturado]
		INTO												#tmp
		FROM tbCommercialTransactions						tct		WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forSalesStats	vctfs	WITH(NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id		AND
				vctfs.bra_id			= tct.bra_id		AND
				vctfs.ct_transaction	= tct.ct_transaction
		INNER JOIN tbBranchGroupDetail						AS tbgd	WITH(NOLOCK)
			ON	tbgd.comp_id			= tct.comp_id		AND
				tbgd.brag_id			= @brag_id			AND
				tbgd.bra_id				= tct.bra_id
		INNER JOIN tbCustomer								tc		WITH(NOLOCK)
			ON  tc.comp_id				= tct.comp_id		AND
				tc.cust_id				= tct.cust_id
		LEFT JOIN tbSalesman								ts		WITH(NOLOCK)
			ON	ts.comp_id				= tc.comp_id		AND
				ts.sm_id				= tc.sm_id
		INNER JOIN tbUsers4BranchFilter						vubf	WITH(NOLOCK)
			ON  vubf.comp_id			= tct.comp_id		AND
				vubf.bra_id				= tct.bra_id		AND
				vubf.[user_id]			= @user_id
		WHERE tct.[comp_id] = @comp_id						AND
			(
				vctfs.sd_id = 1 OR
				vctfs.sd_id = 3
			)												AND
			tct.ct_date  BETWEEN @datefrom AND @dateto


		DECLARE
			@total DECIMAL(19,2)
		SET @total = (SELECT SUM(temp.[Facturado]) [Total] from #tmp temp)


		SELECT TOP 20
			CONVERT(VARCHAR,temp.cust_id) + ' - ' +
			CONVERT(VARCHAR,temp.cust_name)							[cust_name],
			CONVERT(DECIMAL(19,2),SUM(temp.[Facturado]))			[Facturado],
			RANK() OVER (ORDER BY SUM(temp.[Facturado]) DESC)		[Puesto Nro],
			(SUM(temp.[Facturado]/dbo.fnNoZDiv(@total) * 100))      [Porcent]
			FROM	#tmp											temp
			GROUP BY temp.cust_name,temp.cust_id
			ORDER BY [Facturado] DESC



	END
GO


CREATE PROCEDURE [dbo].[spControlPanelGraphics_getItemsAging]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@brag_id			INT,
	@user_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@storg_id			INT

)
AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	-- - ---------------------------------------------------------------------------------------
	-- - Testing
	-- - ---------------------------------------------------------------------------------------
	/*
	DECLARE
		@comp_id		INT,
		@storg_id		Int,

		@user_id		INT,
		@brag_id		INT



	SELECT
		@comp_id		= 1,
		@storg_id		= 2,

		@user_id		= 1,
		@brag_id		= 4

	DROP TABLE #tmpWorkingData
	*/
	-- - ---------------------------------------------------------------------------------------

	DECLARE @coslis_id		INT = -1
	SELECT @coslis_id		= tb.coslis_id
		FROM tbBranch AS tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id

	DECLARE @lGuid AS UNIQUEIDENTIFIER

	--SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	--INSERT INTO @tblComplexFilter_Items
	--	SELECT tcf.sl_id
	--		FROM tbComplexFilter tcf	WITH (NOLOCK)
	--		WHERE tcf.sl_guid = @lGuid     AND
	--					  tcf.sl_selected = 'True'
	--IF @@ROWCOUNT = 0
		--BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti		WITH (NOLOCK)
					WHERE	ti.comp_id			= @comp_id AND
							ti.item_disabled	= 'False'
		--END
	-- -------------------------------------------------------------



	DECLARE @tblSuppliers4Transfer AS TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblSuppliers4Transfer( supp_id)
		SELECT distinct tbcsi.supp_id
			FROM tbBranch2Customer4StockImport tbcsi	WITH (NOLOCK)
			WHERE	tbcsi.comp_id = @comp_id AND
					tbcsi.supp_id IS NOT NULL		-- MOS 06-2023 x marstech q explotaba

	DECLARE @tmpStorageGroup TABLE(stor_id INT PRIMARY KEY)
	INSERT INTO @tmpStorageGroup
	SELECT DISTINCT
		tb.stor_id
		FROM tbBranch							AS tb	WITH(NOLOCK)
			INNER JOIN tbBranchGroupDetail		AS tbgd	WITH(NOLOCK)
			ON	tbgd.comp_id	= tb.comp_id	AND
				tbgd.bra_id		= tb.bra_id
		WHERE	tb.comp_id		= @comp_id		AND
				tbgd.brag_id	= @brag_id

	--INSERT INTO @tmpStorageGroup
	--	SELECT DISTINCT	tsgd.stor_id
	--		FROM tbStorageGroupDetail tsgd	WITH (NOLOCK)
	--		WHERE	tsgd.comp_id	= @comp_id AND
	--				tsgd.storg_id	= @storg_id



	DECLARE @tmpTable TABLE (	stor_id					int,
								item_id					Int,
								periodo					Int,
								coslis_id				INT,
								[Value]					Decimal(19,6),
								[ValueOriginal]			Decimal(19,6),
								[Value_coslis_price]	Decimal(19,5),
								[Value_coslis_price_aw] Decimal(19,5),
								[Value_priceOfInvoice]	Decimal(19,5),INDEX IX3 NONCLUSTERED(stor_id,item_id,periodo,coslis_id)
							)

	--CREATE NONCLUSTERED INDEX ix_tmpTable ON @tmpTable (stor_id,item_id,periodo,coslis_id)

	Declare @date				Datetime,
			@intDayCounter		INT,
			@intDayCounterAdd	INT

	-- Pone en @Date la fecha de mañana
	Set @date = GETDATE() + 1 --convert(datetime, convert(char, getdate(), 1), 1) + 1

	--Select @date
	--:::::::::::::::::::::::::::::::::::::::::

	Declare @lstor_id				Int
	Declare @litem_id				Int
	declare @lstor_desc				Varchar(500)
	Declare @litem_code				Varchar(500)
	declare @litem_desc				Varchar(500)
	Declare @litst_cant				Decimal(18,5)
	Declare @lcant					Decimal(18,5)
	Declare @lcoslis_price			Decimal(19,5)
	Declare @lcoslis_price_aw		Decimal(19,5)
	Declare @lcoslis_id				Int
	DECLARE @datDateFrom			AS DATETIME
	DECLARE @datDateTo  			AS DATETIME


	-- Pone en un cursor los articulos con stock en el grupo de depositos a verificar.
	declare cursor_IS_gR CURSOR LOCAL FAST_FORWARD FOR
												Select	-1,
														'Grupo de Depositos XX',
														ti.item_id,
														ti.item_code,
														ti.item_desc,
														IsNull(SUM(tis.itst_cant),0),
														IsNull(ticl.coslis_price,0)					[coslis_price],
														IsNull(ticl.coslis_price_aw,0)				[coslis_price_aw],
														@coslis_id									[coslis_id]  --ticl.coslis_id

													From	tbItem									ti				WITH (NOLOCK)

													INNER JOIN @tblComplexFilter_Items tcf
														ON tcf.item_id = ti.item_id

													INNER JOIN tbItemStorage						tis				WITH (NOLOCK)
														ON	tis.comp_id = ti.comp_id	AND
															tis.item_id = ti.item_id

													INNER JOIN @tmpStorageGroup						tmp
													ON tmp.stor_id = tis.stor_id

													LEFT join tbItemCostList						ticl			WITH (NOLOCK)
													on  ticl.comp_id	= ti.comp_id	And
														ticl.item_id	= ti.item_id	AND
														ticl.coslis_id  = @coslis_id

													Where		ti.comp_id		=	@comp_id
														--And		(@item_id		=	-1			or ti.item_id     = @item_id)
														--And		(@cat_id		=	-1			or ti.cat_id      = @cat_id)
														--And		(@subcat_id		=	-1			or ti.subcat_id   = @subcat_id)
														--And		(@brand_id		=	-1			or ti.brand_id    = @brand_id)
														--And		(@pres_id		=	-1			or ti.pres_id	  = @pres_id)

													GROUP BY	ti.item_id,
																ti.item_code,
																ti.item_desc,
																ticl.coslis_price,
																ticl.coslis_price_aw
													HAVING SUM(tis.itst_cant) > 0


	open cursor_IS_gR


	FETCH NEXT FROM cursor_IS_gR
	Into	@lstor_id,
			@litem_desc,
			@litem_id,
			@litem_code,
			@litem_desc,
			@litst_cant,
			@lcoslis_price,
			@lcoslis_price_aw,
			@lcoslis_id




	WHILE @@FETCH_STATUS = 0
		Begin


			Set @lcant = @litst_cant



			Set @intDayCounter		= 0
			SET @intDayCounterAdd	= 14

			While @intDayCounter <> 9999
				begin

					IF @intDayCounter < 180
						BEGIN
							SET @datDateFrom = dbo.fnGetEnd_or_BeginOfDate( @date - @intDayCounter - @intDayCounterAdd,0)
							SET @datDateTo   = dbo.fnGetEnd_or_BeginOfDate( @date -   @intDayCounter,1)
						END
					ELSE
						BEGIN
							SET @datDateFrom = dbo.fnGetEnd_or_BeginOfDate( '1800-01-01' ,0)
							SET @datDateTo   = dbo.fnGetEnd_or_BeginOfDate( @date-@intDayCounter,1)
						END


					Insert into @tmpTable
						(	stor_id,
							item_id,
							[Value] ,
							[ValueOriginal] ,
							periodo,
							[Value_coslis_price],
							[Value_coslis_price_aw],
							[Value_priceOfInvoice],
							coslis_id)

					Select	@lstor_id	[stor_id],
							tit.item_id,
							Case
								When isnull(Sum(tit.it_qty),0) < @lcant Then isnull(Sum(tit.it_qty),0)
								Else @lcant
							End ,
							isnull(Sum(tit.it_qty),0),
							@intDayCounter,
							isnull(ticl.coslis_price,0),
							isnull(ticl.coslis_price_aw,0),
							isnull(Sum(tit.it_qty * tit.it_price * tit.it_exchangeToBranchCurrency),0)  / dbo.fnNoZDiv( isnull(Sum(tit.it_qty),0) ),
							@lcoslis_id --ticl.coslis_id

						From	tbItemTransactions										tit				WITH (NOLOCK)

								Inner Join tbUsers4BranchFilter							vubf			WITH (NOLOCK)
									ON	vubf.comp_id		= tit.comp_id	and
										vubf.bra_id			= tit.bra_id	and
										vubf.[user_id]		= @user_id

								INNER JOIN @tmpStorageGroup								tmp
									ON tmp.stor_id = tit.stor_id

								Inner Join tbCommercialTransactions						tct				WITH (NOLOCK)
									On	tct.comp_id			= tit.comp_id			and
										tct.ct_transaction	= tit.ct_transaction	--and
										--tct.sd_id			IN (101,102,104,121,124,130,145)



								Inner Join tbItem										ti				WITH (NOLOCK)
									On	ti.comp_id			= tit.comp_id	and
										ti.item_id			= tit.item_id

								LEFT join tbItemCostList								ticl			WITH (NOLOCK)
									on  ticl.comp_id		= ti.comp_id	and
										ticl.coslis_id		= @lcoslis_id	AND
										ticl.item_id		= ti.item_id



								LEFT JOIN @tblSuppliers4Transfer						 tr
									ON	tr.supp_id = tct.supp_id

						Where		tit.comp_id         = @comp_id
							AND		tit.item_id			= @litem_id
							and
									tct.sd_id			IN (101,102,104,121,124,130,145)
							AND		IsNull(tit.it_transaction_NoStockDiscount,0) = 0
							And		tct.ct_cd		Between @datDateFrom And @datDateTo
							And		@lcant			> 0
							AND		isnull(tit.it_IsInternalTransfer,0) = 0
							AND		tr.supp_id IS NULL
							AND CASE
							        WHEN tct.sd_id = 145 AND tit.it_qty >  0 THEN 1
							        WHEN tct.sd_id = 145 AND tit.it_qty <= 0 THEN 0
							        ELSE 1
							    END	= 1

						Group By
									tit.item_id,
									ticl.coslis_id,
									ticl.coslis_price,
									ticl.coslis_price_aw


					If Exists (	Select TOP 1 1
									From @tmpTable
				           			Where	stor_id		= @lstor_id			And
				           					item_id		= @litem_id			And
				           					coslis_id	= @lcoslis_id		And
				           					periodo		= @intDayCounter
							)
						BEGIN
							Set @lcant = @lcant - ISNULL((	Select [Value]
																From @tmpTable
						                       					Where	stor_id		= @lstor_id		And
						                       							item_id		= @litem_id		and
						                       							coslis_id	= @lcoslis_id	And
						                       							periodo		= @intDayCounter),0)
						END




					SET @intDayCounter =
											CASE
											    WHEN @intDayCounter = 00  THEN 15
											    WHEN @intDayCounter = 15  THEN 30
											    WHEN @intDayCounter = 30  THEN 45
											    WHEN @intDayCounter = 45  THEN 60
											    WHEN @intDayCounter = 60  THEN 90
											    WHEN @intDayCounter = 90  THEN 180
											    WHEN @intDayCounter = 180 THEN 9999
											    ELSE 9999
											END

					SET @intDayCounterAdd = CASE
											    WHEN @intDayCounter = 15  THEN 15
											    WHEN @intDayCounter = 30  THEN 15
											    WHEN @intDayCounter = 45  THEN 15
											    WHEN @intDayCounter = 60  THEN 30
											    WHEN @intDayCounter = 90  THEN 90
											    ELSE 9999
					                        END
					set @intDayCounterAdd = @intDayCounterAdd - 1



				End



			--------------------------------------------


			fetch cursor_IS_gR
				Into	@lstor_id,
						@litem_desc,
						@litem_id,
						@litem_code,
						@litem_desc,
						@litst_cant,
						@lcoslis_price,
						@lcoslis_price_aw,
						@lcoslis_id


		END


	close cursor_IS_gR
	deallocate cursor_IS_gR

--==
--select * from @tmpTable
--==



	;WITH pendingPIVOT AS (

-- Cantidad Pendiente de ingresos de este periodo
 	select				tsg.storg_desc,
						ti.item_code,
						--ti.item_desc,
						ti.item_desc,
						isnull(tb.brand_desc,'')								[brand_desc],
						isnull(tc2.cat_desc,'')									[cat_desc],
						isnull(tsc.subcat_desc,'')								[subcat_desc],
						isnull(tsca.subcataux_desc,'')							[subcataux_desc],
						isnull(tp.pres_desc,'')									[pres_desc],
						ticln.coslis_desc,
						tc.curr_symbol,
						--periodo 0 - 15
						Isnull(PT.[0],0)										Per1,
						Isnull(PT.[0] * IsNull(ticl.coslis_price,0),0)			Val1,
						Isnull(PT.[0] * IsNull(ticl.coslis_price_AW,0),0)		ValPP1,
						Isnull(PT.[0] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price,0),    ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AVal1,
						Isnull(PT.[0] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price_AW,0), ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AValPP1,

						--periodo 16 - 30
						Isnull(PT.[15],0)										Per2,
						Isnull(PT.[15] * IsNull(ticl.coslis_price,0),0)			Val2,
						Isnull(PT.[15] * IsNull(ticl.coslis_price_AW,0),0)		ValPP2,
						Isnull(PT.[15] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price,0),    ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AVal2,
						Isnull(PT.[15] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price_AW,0), ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AValPP2,

						--periodo 31 - 45
						Isnull(PT.[30],0)										Per3,
						Isnull(PT.[30] * IsNull(ticl.coslis_price,0),0)			Val3,
						Isnull(PT.[30] * IsNull(ticl.coslis_price_AW,0),0)		ValPP3,
						Isnull(PT.[30] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price,0),    ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AVal3,
						Isnull(PT.[30] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price_AW,0), ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AValPP3,

						--periodo 46 - 60
						Isnull(PT.[45],0)										Per4,
						Isnull(PT.[45] * IsNull(ticl.coslis_price,0),0)			Val4,
						Isnull(PT.[45] * IsNull(ticl.coslis_price_AW,0),0)		ValPP4,
						Isnull(PT.[45] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price,0),    ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AVal4,
						Isnull(PT.[45] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price_AW,0), ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AValPP4,

						--periodo 61 - 90
						Isnull(PT.[60],0)										Per5,
						Isnull(PT.[60] * IsNull(ticl.coslis_price,0),0)			Val5,
						Isnull(PT.[60] * IsNull(ticl.coslis_price_AW,0),0)		ValPP5,
						Isnull(PT.[60] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price,0),    ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AVal5,
						Isnull(PT.[60] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price_AW,0), ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AValPP5,

						--periodo 90 - 180
						Isnull(PT.[90],0)										Per6,
						Isnull(PT.[90] * IsNull(ticl.coslis_price,0),0)			Val6,
						Isnull(PT.[90] * IsNull(ticl.coslis_price_AW,0),0)		ValPP6,
						Isnull(PT.[90] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price,0),    ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AVal6,
						Isnull(PT.[90] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price_AW,0), ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AValPP6,

						--periodo +180
						Isnull(PT.[180],0)										Per7,
						Isnull(PT.[180] * IsNull(ticl.coslis_price,0),0)		Val7,
						Isnull(PT.[180] * IsNull(ticl.coslis_price_AW,0),0)		ValPP7,
						Isnull(PT.[180] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price,0),    ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AVal7,
						Isnull(PT.[180] * dbo.fnGetExchange2(ticl.comp_id,  IsNull(ticl.coslis_price_AW,0), ticl.curr_id, ticln.curr_id4AgeingReportAlternativeVal, 0, 0, 0, 'False') ,0)		AValPP7,

						--stock
						SUM(tis.itst_cant)										[itst_cant],
						ISNULL(tc.curr_symbol,'***')							[currency],
						ISNULL(tcA.curr_symbol,'***')							[currencyA],
						ti.item_id

		From (Select		t.stor_id [stor],
							t.item_id [item],
							t.periodo [Period],
							t.[Value],
							t.[Value_coslis_price] ,
							t.[Value_coslis_price_aw],
							t.coslis_id [coslis]

			from @tmpTable t) as V

			PIVOT (Sum( [Value] )			FOR [Period]			IN ([0], [15], [30], [45], [60], [90], [180]) )				as PT

			INNER JOIN tbStorageGroup						tsg		WITH (NOLOCK)
				ON	tsg.comp_id		= @comp_id AND
					tsg.storg_id	= @storg_id

			Inner Join tbItem								ti		WITH (NOLOCK)
			On	ti.comp_id			= @comp_id		And
				ti.item_id			= item

			LEFT JOIN tbBrand								tb		WITH (NOLOCK)
			ON  tb.comp_id			= ti.comp_id	AND
				tb.brand_id			= ti.brand_id

			LEFT JOIN tbCategory							tc2		WITH (NOLOCK)
			ON	tc2.comp_id			= ti.comp_id	AND
				tc2.cat_id			= ti.cat_id

			LEFT JOIN tbSubCategory							tsc		WITH (NOLOCK)
			ON	tsc.comp_id			= ti.comp_id	AND
				tsc.cat_id			= ti.cat_id		AND
				tsc.subcat_id		= ti.subcat_id

			LEFT JOIN tbSubCategoryAux						tsca	WITH (NOLOCK)
			ON	tsca.comp_id		= ti.comp_id	AND
				tsca.subcataux_id	= ti.subcataux_id

			LEFT JOIN tbPresentation						tp		WITH (NOLOCK)
			ON	tp.comp_id			= ti.comp_id	AND
				tp.pres_id			= ti.pres_id

			Inner Join tbItemStorage						tis		WITH (NOLOCK)
			On	tis.comp_id			= @comp_id		And
				tis.item_id			= item

			INNER JOIN @tmpStorageGroup tmp
				ON tmp.stor_id		= tis.stor_id

			LEFT join tbItemCostList						ticl	WITH (NOLOCK)
			on  ticl.comp_id		= @comp_id		AND
				ticl.item_id		= item			AND
				ticl.coslis_id		= @coslis_id

			LEFT join tbItemCostListName					ticln	WITH (NOLOCK)
			on  ticln.comp_id		= @comp_id		and
				ticln.coslis_id		= coslis

			LEFT join tbsysCurrency						tc		WITH (NOLOCK)
			on	tc.curr_id			= ticl.curr_id

			LEFT join tbsysCurrency						tcA		WITH (NOLOCK)
			on	tcA.curr_id			= ticln.curr_id4AgeingReportAlternativeVal


	GROUP BY	tsg.storg_desc,
				ti.item_code,
				ti.item_id,
				ti.item_desc,
				tb.brand_desc,
				tc2.cat_desc,
				tsc.subcat_desc,
				tsca.subcataux_desc,
				tp.pres_desc,
				ticln.coslis_desc,
				tc.curr_symbol,
				ticl.coslis_price,
				ticl.coslis_price_aw,
				PT.[0],
				PT.[15],
				PT.[30],
				PT.[45],
				PT.[60],
				PT.[90],
				PT.[180],
				ticln.curr_id4AgeingReportAlternativeVal,
				ticl.curr_id,
				ticl.comp_id,
				tcA.curr_symbol
	)
	,
	 totalPIVOT AS (
	-- Cantidad Pendiente de ingresos de este periodo
	select  			--tsg.storg_desc,

						--periodo 0 - 15
						Isnull(PT.[0],0)										OPer1,
						--periodo 16 - 30
						Isnull(PT.[15],0)										OPer2,
						--periodo 31 - 45
						Isnull(PT.[30],0)										OPer3,
						--periodo 46 - 60
						Isnull(PT.[45],0)										OPer4,
						--periodo 61 - 90
						Isnull(PT.[60],0)										OPer5,
						--periodo 90 - 180
						Isnull(PT.[90],0)										OPer6,
						--periodo +180
						Isnull(PT.[180],0)										OPer7,
						ti.item_id												[Oitem_id]
						--stock

		From (Select		t.stor_id [stor],
							t.item_id [item],
							t.periodo [Period],
							t.[ValueOriginal]

			from @tmpTable t) as OV

			PIVOT (Sum( [ValueOriginal] )			FOR [Period]			IN ([0], [15], [30], [45], [60], [90], [180]) )				as PT

			INNER JOIN tbStorageGroup						tsg		WITH (NOLOCK)
				ON	tsg.comp_id		= @comp_id AND
					tsg.storg_id	= @storg_id

			Inner Join tbItem								ti		WITH (NOLOCK)
			On	ti.comp_id			= @comp_id		And
				ti.item_id			= item


			Inner Join tbItemStorage						tis		WITH (NOLOCK)
			On	tis.comp_id			= @comp_id		And
				tis.item_id			= item

			INNER JOIN @tmpStorageGroup tmp
				ON tmp.stor_id		= tis.stor_id


	GROUP BY	ti.item_id,
				PT.[0],
				PT.[15],
				PT.[30],
				PT.[45],
				PT.[60],
				PT.[90],
				PT.[180]
	)

	,
	 valorizedAtPurchaseBranchCurrencyPIVOT AS (
						-- Cantidad Pendiente de ingresos de este periodo
						select  			--tsg.storg_desc,

											--periodo 0 - 15
											Isnull(PT.[0],0)										PurchaseCost1,
											--periodo 16 - 30
											Isnull(PT.[15],0)										PurchaseCost2,
											--periodo 31 - 45
											Isnull(PT.[30],0)										PurchaseCost3,
											--periodo 46 - 60
											Isnull(PT.[45],0)										PurchaseCost4,
											--periodo 61 - 90
											Isnull(PT.[60],0)										PurchaseCost5,
											--periodo 90 - 180
											Isnull(PT.[90],0)										PurchaseCost6,
											--periodo +180
											Isnull(PT.[180],0)										PurchaseCost7,
											item												[Oitem_id]
											--stock

							From (	Select
												t.item_id [item],
												t.periodo [Period],
												ISNULL(t.[Value_priceOfInvoice],0)	[Value_priceOfInvoice]
										from @tmpTable t) as OV

							PIVOT (  MAX( [Value_priceOfInvoice] )			FOR [Period]			IN ([0], [15], [30], [45], [60], [90], [180]) )				as PT

							GROUP BY	item,
										PT.[0],
										PT.[15],
										PT.[30],
										PT.[45],
										PT.[60],
										PT.[90],
										PT.[180]
				)





	SELECT
		A.*,
		--A.*,
		B.OPer1,
		--C.PurchaseCost1,
		B.OPer2,
		--C.PurchaseCost2,
		B.OPer3,
		--C.PurchaseCost3,
		B.OPer4,
		--C.PurchaseCost4,
		B.OPer5,
		--C.PurchaseCost5,
		B.OPer6,
		--C.PurchaseCost6,
		B.OPer7--,
		--C.PurchaseCost7
			INTO #tmpWorkingData
		FROM  pendingPIVOT									A
		INNER JOIN totalPIVOT								B
			ON A.item_id = B.Oitem_id
		INNER JOIN valorizedAtPurchaseBranchCurrencyPIVOT	C
			ON A.item_id = C.Oitem_id


		SELECT
			tmp.subcat_desc,
			-- ----------------------------------------------------------------------------
			-- La cantidad aquí informada es el pendiente de stock ingresado en el período.
			-- ----------------------------------------------------------------------------
				SUM(tmp.Per1)		[Per1],		-- 0 a 15
				SUM(tmp.Per2)		[Per2],		-- 16 a 30
				SUM(tmp.Per3)		[Per3],		-- 31 a 45
				SUM(tmp.Per4)		[Per4],		-- 46 a 60
				SUM(tmp.Per5)		[Per5],		-- 61 a 90
				SUM(tmp.Per6)		[Per6],		-- 91 a 180
				SUM(tmp.Per7)		[Per7],		-- 180+
			-- ----------------------------------------------------------------------------

			-- ----------------------------------------------------------------------------
			-- La cantidad aquí informada corresponde al total de los ingresos originales
			-- los cuales tienen cantidades pendientes en el período correspondiente.
			-- ----------------------------------------------------------------------------
				SUM(tmp.OPer1)		[OPer1],	-- 0 a 15
				SUM(tmp.OPer2)		[OPer2],	-- 16 a 30
				SUM(tmp.OPer3)		[OPer3],	-- 31 a 45
				SUM(tmp.OPer4)		[OPer4],	-- 46 a 60
				SUM(tmp.OPer5)		[OPer5],	-- 61 a 90
				SUM(tmp.OPer6)		[OPer6],	-- 91 a 180
				SUM(tmp.OPer7)		[OPer7]		-- 180+
			-- ----------------------------------------------------------------------------
		FROM #tmpWorkingData	tmp
		GROUP BY tmp.subcat_desc


END
GO

CREATE PROCEDURE [dbo].[spControlPanelGraphics_getItemSalesRanking]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@brag_id			INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@datefrom			= '2021-01-01',
				@dateto				= '2021-10-31'

				DROP TABLE #tmp
		*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto	= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


		--RECUPERO LA MONEDA DE LA SUCURSAL
		DECLARE
			@lbra_curr_id	INT
		SELECT
			@lbra_curr_id		= tb.curr_id
			FROM tbBranch					AS tb	WITH(NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

	SELECT
		ti.item_id,
		ti.item_code,
		ti.item_desc,
		tit.it_qty
		INTO												#tmp
		FROM tbCommercialTransactions						tct		WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forSalesStats	vctfs	WITH(NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id		AND
				vctfs.bra_id			= tct.bra_id		AND
				vctfs.ct_transaction	= tct.ct_transaction
		INNER JOIN tbBranchGroupDetail						AS tbgd	WITH(NOLOCK)
			ON	tbgd.comp_id			= tct.comp_id		AND
				tbgd.brag_id			= @brag_id			AND
				tbgd.bra_id				= tct.bra_id
		INNER JOIN tbItemTransactions						AS tit	WITH(NOLOCK)
			ON	tit.comp_id				= tct.comp_id		AND
				tit.ct_transaction		= tct.ct_transaction
		INNER JOIN tbItem									AS ti	WITH(NOLOCK)
			ON	ti.comp_id				= tit.comp_id		AND
				ti.item_id				= tit.item_id
		INNER JOIN tbUsers4BranchFilter						vubf	WITH(NOLOCK)
			ON  vubf.comp_id			= tct.comp_id		AND
				vubf.bra_id				= tct.bra_id		AND
				vubf.[user_id]			= @user_id
		WHERE tct.[comp_id] = @comp_id						AND
			(
				vctfs.sd_id = 1 OR
				vctfs.sd_id = 3
			)												AND
			tct.ct_date  BETWEEN @datefrom AND @dateto


		SELECT
			CONVERT(VARCHAR,temp.item_id) + ' - ' +
			CONVERT(VARCHAR,temp.item_code)							[item_desc],
			SUM(temp.it_qty)										[Cantidad]
			FROM	#tmp											temp
			GROUP BY temp.item_id, temp.item_code
			ORDER BY [Cantidad] DESC



	END
GO

CREATE PROCEDURE [dbo].[spControlPanelGraphics_getMonthlySales]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@brag_id			INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@datefrom			= '2021-01-01',
				@dateto				= '2021-10-31'

				DROP TABLE #tmp
		*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto	= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


		--RECUPERO LA MONEDA DE LA SUCURSAL
		DECLARE
			@lbra_curr_id	INT
		SELECT
			@lbra_curr_id		= tb.curr_id
			FROM tbBranch					AS tb	WITH(NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

	SELECT
		tct.ct_date,
		dbo.fnGetExchange2(@comp_id, tct.ct_subtotal, tct.curr_id_transaction, @lbra_curr_id,  tct.curr_id4Exchange,tct.curr_id_transaction, tct.ct_curr_IdExchange,'False') *
		vctfs.PlusOrMinus												[Facturado]
		INTO												#tmp
		FROM tbCommercialTransactions						tct		WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forSalesStats	vctfs	WITH(NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id		AND
				vctfs.bra_id			= tct.bra_id		AND
				vctfs.ct_transaction	= tct.ct_transaction
		INNER JOIN tbBranchGroupDetail						AS tbgd	WITH(NOLOCK)
			ON	tbgd.comp_id			= tct.comp_id		AND
				tbgd.brag_id			= @brag_id			AND
				tbgd.bra_id				= tct.bra_id
		--INNER JOIN tbCustomer								tc		WITH(NOLOCK)
		--	ON  tc.comp_id				= tct.comp_id		AND
		--		tc.cust_id				= tct.cust_id
		--LEFT JOIN tbsysCountry								AS tc2	WITH(NOLOCK)
		--	ON	tc2.country_id			= tct.country_id
		--LEFT JOIN tbsysState								AS ts	WITH(NOLOCK)
		--	ON	ts.country_id			= tct.country_id	AND
		--		ts.state_id				= tct.state_id
		INNER JOIN tbUsers4BranchFilter						vubf	WITH(NOLOCK)
			ON  vubf.comp_id			= tct.comp_id		AND
				vubf.bra_id				= tct.bra_id		AND
				vubf.[user_id]			= @user_id
		WHERE tct.[comp_id] = @comp_id						AND
			(
				vctfs.sd_id = 1 OR
				vctfs.sd_id = 3
			)												AND
			tct.ct_date  BETWEEN @datefrom AND @dateto


		DECLARE
			@total DECIMAL(19,2)
		SET @total = (SELECT SUM(temp.[Facturado]) [Total] from #tmp temp)

		-- ==
			--SELECT @total
		-- ==

		SELECT
			CONVERT(VARCHAR,temp.ct_date,103)						[Date],
			SUM(temp.[Facturado])									[Facturado],
			RANK() OVER (ORDER BY SUM(temp.[Facturado]) DESC)		[Puesto Nro],
			(SUM(temp.[Facturado]/dbo.fnNoZDiv(@total) * 100))      [Porcent]
			FROM	#tmp											temp
			GROUP BY temp.ct_date
			ORDER BY [Facturado] DESC



	END
GO

