CREATE PROCEDURE [dbo].[spControlPanelGraphics_getSalesBySuBCategory]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@brag_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@brag_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@brag_id			= 4,
				@datefrom			= '2022-01-01',
				@dateto				= '2022-12-31'

				DROP TABLE #tmp
		*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,	'True')


		--RECUPERO LA MONEDA DE LA SUCURSAL
		DECLARE
			@lbra_curr_id	INT
		SELECT
			@lbra_curr_id		= tb.curr_id
			FROM tbBranch					AS tb	WITH(NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

	SELECT
		tsc.subcat_desc,
		SUM(dbo.fnGetExchange2(@comp_id, tit.it_price, tit.curr_id, @lbra_curr_id,  tit.curr_id, @lbra_curr_id, 0,'False') *
		vctfs.PlusOrMinus)									[Facturado]
		INTO												#tmp
		FROM tbCommercialTransactions						tct		WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forSalesStats	vctfs	WITH(NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id		AND
				vctfs.bra_id			= tct.bra_id		AND
				vctfs.ct_transaction	= tct.ct_transaction
		INNER JOIN tbItemTransactions						AS tit	WITH(NOLOCK)
			ON	tit.comp_id				= tct.comp_id		AND
				tit.bra_id				= tct.bra_id		AND
				tit.ct_transaction		= tct.ct_transaction
		INNER JOIN tbItem									AS ti	WITH(NOLOCK)
			ON	ti.comp_id				= tit.comp_id		AND
				ti.item_id				= tit.item_id
		INNER JOIN tbSubCategory							AS tsc	WITH(NOLOCK)
			ON	tsc.comp_id				= tsc.comp_id		AND
				tsc.subcat_id			= ti.subcat_id
		INNER JOIN tbUsers4BranchFilter						vubf	WITH(NOLOCK)
			ON  vubf.comp_id			= tct.comp_id		AND
				vubf.bra_id				= tct.bra_id		AND
				vubf.[user_id]			= @user_id
		INNER JOIN tbBranchGroupDetail						AS tbgd	WITH(NOLOCK)
			ON	tbgd.comp_id			= tct.comp_id		AND
				tbgd.brag_id			= @brag_id			AND
				tbgd.bra_id				= tct.bra_id
		WHERE tct.[comp_id] = @comp_id						AND
			(
				vctfs.sd_id = 1 OR
				vctfs.sd_id = 3
			)												AND
			tct.ct_date  BETWEEN @datefrom AND @dateto
		GROUP BY tsc.subcat_desc

		DECLARE
			@total DECIMAL(19,2)
		SET @total = (SELECT SUM(temp.[Facturado]) [Total] from #tmp temp)

		-- ==
			--SELECT @total
		-- ==

		SELECT
			--temp.ct_date											[Date],
			temp.subcat_desc,
			SUM(temp.[Facturado])									[Facturado],
			RANK() OVER (ORDER BY SUM(temp.[Facturado]) DESC)		[Puesto Nro],
			(SUM(temp.[Facturado]/dbo.fnNoZDiv(@total) * 100))      [Porcent]
			FROM	#tmp											temp
			WHERE [Facturado] >= 0
			GROUP BY temp.subcat_desc
			ORDER BY [Facturado] DESC
	END
GO



CREATE PROCEDURE [dbo].[spControlPanelGraphics_getSalesBySuBCategoryByQty]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@brag_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@brag_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@brag_id			= 4,
				@datefrom			= '2022-01-01',
				@dateto				= '2022-12-31'

				DROP TABLE #tmp
		*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,	'True')


		--RECUPERO LA MONEDA DE LA SUCURSAL
		DECLARE
			@lbra_curr_id	INT
		SELECT
			@lbra_curr_id		= tb.curr_id
			FROM tbBranch					AS tb	WITH(NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

	SELECT
		tsc.subcat_desc,
		SUM(tit.it_qty *
		vctfs.PlusOrMinus)									[Qty]
		INTO												#tmp
		FROM tbCommercialTransactions						tct		WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forSalesStats	vctfs	WITH(NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id		AND
				vctfs.bra_id			= tct.bra_id		AND
				vctfs.ct_transaction	= tct.ct_transaction
		INNER JOIN tbItemTransactions						AS tit	WITH(NOLOCK)
			ON	tit.comp_id				= tct.comp_id		AND
				tit.bra_id				= tct.bra_id		AND
				tit.ct_transaction		= tct.ct_transaction
		INNER JOIN tbItem									AS ti	WITH(NOLOCK)
			ON	ti.comp_id				= tit.comp_id		AND
				ti.item_id				= tit.item_id
		INNER JOIN tbSubCategory							AS tsc	WITH(NOLOCK)
			ON	tsc.comp_id				= tsc.comp_id		AND
				tsc.subcat_id			= ti.subcat_id
		INNER JOIN tbUsers4BranchFilter						vubf	WITH(NOLOCK)
			ON  vubf.comp_id			= tct.comp_id		AND
				vubf.bra_id				= tct.bra_id		AND
				vubf.[user_id]			= @user_id
		INNER JOIN tbBranchGroupDetail						AS tbgd	WITH(NOLOCK)
			ON	tbgd.comp_id			= tct.comp_id		AND
				tbgd.brag_id			= @brag_id			AND
				tbgd.bra_id				= tct.bra_id
		WHERE tct.[comp_id] = @comp_id						AND
			(
				vctfs.sd_id = 1 OR
				vctfs.sd_id = 2 OR  -- Se agregan REMITOS
				vctfs.sd_id = 3
			)												AND
			tct.ct_date  BETWEEN @datefrom AND @dateto
		GROUP BY tsc.subcat_desc




		DECLARE
			@total DECIMAL(19,2)
		SET @total = (SELECT SUM(temp.[Qty]) [Total] from #tmp temp)

		-- ==
			--SELECT @total
		-- ==

		SELECT
			--temp.ct_date										[Date],
			temp.subcat_desc,
			SUM(temp.[Qty])										[Qty],
			RANK() OVER (ORDER BY SUM(temp.[Qty]) DESC)			[Puesto Nro],
			(SUM(temp.[Qty]/dbo.fnNoZDiv(@total) * 100))		[Porcent]
			FROM	#tmp										temp
			WHERE [Qty] >= 0
			GROUP BY temp.subcat_desc
			ORDER BY [Qty] DESC
	END
GO


CREATE PROCEDURE [dbo].[spControlPanelGraphics_getTotalPurchaseWithConditionalGroupBy4Columns]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@brag_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@brag_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@brag_id			= 4,
				@datefrom			= '2019-01-01',
				@dateto				= '2019-06-30'

				DROP TABLE #tmp
		*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

		DECLARE
			@intDateDiffGroupBy	INT

		-- ------------------------------------------
		-- SI EL DATEDIFF ES MENOR A 31 DIAS
		-- ENTONCES AGRUPO POR DIAS
		-- ------------------------------------------
		IF DATEDIFF(DAY,@datefrom,@dateto) < 32
			BEGIN
				SET @intDateDiffGroupBy = 1
			END
		-- ------------------------------------------

		-- ------------------------------------------
		-- SI EL DATEDIFF ES MENOR A 365 DIAS
		-- ENTONCES AGRUPO POR MES
		-- ------------------------------------------
		IF	DATEDIFF(DAY,@datefrom,@dateto) > 31	AND
			 DATEDIFF(DAY,@datefrom,@dateto) < 366
			BEGIN
				SET @intDateDiffGroupBy = 2
			END
		-- ------------------------------------------

		-- ------------------------------------------
		-- SI EL DATEDIFF ES MAYOR A 365 DIAS
		-- ENTONCES AGRUPO POR AÑO
		-- ------------------------------------------
		IF DATEDIFF(DAY,@datefrom,@dateto) > 365
			BEGIN
				SET @intDateDiffGroupBy = 3
			END
		-- ------------------------------------------

		-- ------------------------------------------
		-- RECUPERO LA MONEDA DE LA SUCURSAL
		-- ------------------------------------------
		DECLARE
			@lbra_curr_id	INT
		SELECT
			@lbra_curr_id		= tb.curr_id
			FROM tbBranch					AS tb	WITH(NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id
		-- ------------------------------------------

	SELECT
		tct.ct_date,
		-- -----------------------------------------------------------------------------------------------------------------
		-- SI EL A_BALANCE ES 0 SUME EN TOTAL_PAGADO
		-- -----------------------------------------------------------------------------------------------------------------
		SUM	(
			CASE
				WHEN tct.ct_ABalance = 0 THEN	dbo.fnGetExchange2(@comp_id,				tct.ct_ATotal,
																   tct.curr_id_transaction, @lbra_curr_id,
																   tct.curr_id4Exchange,	tct.curr_id_transaction,
																   tct.ct_curr_IdExchange,	'False') *
																   vctfp.PlusOrMinus
			ELSE	0
			END
			)														[Total_Pagado],
		-- -----------------------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------------------
		-- SI ES <> 0 Y TODAVIA NO SE VENCIÓ SUME EN PENDIENTE NO VENCIDO
		-- -----------------------------------------------------------------------------------------------------------------
		SUM	(
			CASE
				WHEN tct.ct_ABalance > 0 AND tct.ct_payDate >= GETDATE() THEN	dbo.fnGetExchange2(@comp_id,				tct.ct_ABalance,
																								   tct.curr_id_transaction, @lbra_curr_id,
																								   tct.curr_id4Exchange,	tct.curr_id_transaction,
																								   tct.ct_curr_IdExchange,	'False') *
																								   vctfp.PlusOrMinus
			ELSE	0
			END
			)														[Total_PendienteDePago_NoVencido],
		-- -----------------------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------------------------------
		-- SI ES <> 0 y SE VENCIO SUME EN PENDIENTE VENCIDO
		-- -----------------------------------------------------------------------------------------------------------------
		SUM	(
			CASE
				WHEN tct.ct_ABalance > 0 AND tct.ct_payDate < GETDATE() THEN	dbo.fnGetExchange2(@comp_id,				tct.ct_ABalance,
																								   tct.curr_id_transaction, @lbra_curr_id,
																								   tct.curr_id4Exchange,	tct.curr_id_transaction,
																								   tct.ct_curr_IdExchange,	'False') *
																								   vctfp.PlusOrMinus
			ELSE	0
			END
			)														[Total_PendienteDePago_Vencido],
		-- -----------------------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------------------
		-- TOTAL GENERAL
		-- -----------------------------------------------------------------------------------------------------------------
		SUM(dbo.fnGetExchange2(	@comp_id,				 tct.ct_ATotal,
								tct.curr_id_transaction, @lbra_curr_id,
								tct.curr_id4Exchange,	 tct.curr_id_transaction,
								tct.ct_curr_IdExchange,	 'False') *
								vctfp.PlusOrMinus)					[Facturado]
		-- -----------------------------------------------------------------------------------------------------------------


		INTO												#tmp
		FROM tbCommercialTransactions						tct		WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forPurchase		AS vctfp	WITH(NOLOCK)
			ON	vctfp.comp_id			= tct.comp_id		AND
				vctfp.bra_id			= tct.bra_id		AND
				vctfp.ct_transaction	= tct.ct_transaction
		INNER JOIN tbUsers4BranchFilter						vubf	WITH(NOLOCK)
			ON  vubf.comp_id			= tct.comp_id		AND
				vubf.bra_id				= tct.bra_id		AND
				vubf.[user_id]			= @user_id
		INNER JOIN tbBranchGroupDetail						AS tbgd	WITH(NOLOCK)
			ON	tbgd.comp_id			= tct.comp_id		AND
				tbgd.brag_id			= @brag_id			AND
				tbgd.bra_id				= tct.bra_id
		WHERE tct.[comp_id] = @comp_id						AND
			(
				vctfp.sd_id = 101 OR
				vctfp.sd_id = 103
			)												AND
			tct.ct_date  BETWEEN @datefrom AND @dateto
		GROUP BY tct.ct_date


		IF @intDateDiffGroupBy = 1
			BEGIN
				SELECT
					DAY(temp.ct_date)										[Date],
					SUM(temp.[Total_Pagado])								[Total_Pagado],
					SUM(temp.[Total_PendienteDePago_NoVencido])				[Total_PendienteDePago_NoVencido],
					SUM(temp.[Total_PendienteDePago_Vencido])				[Total_PendienteDePago_Vencido],
					SUM(temp.[Facturado])									[Facturado]
					FROM	#tmp											temp
					GROUP BY DAY(temp.ct_date)
					ORDER BY [Date] ASC
			END

		IF @intDateDiffGroupBy = 2
			BEGIN
				SELECT
					MONTH(temp.ct_date)										[Date],
					SUM(temp.[Total_Pagado])								[Total_Pagado],
					SUM(temp.[Total_PendienteDePago_NoVencido])				[Total_PendienteDePago_NoVencido],
					SUM(temp.[Total_PendienteDePago_Vencido])				[Total_PendienteDePago_Vencido],
					SUM(temp.[Facturado])									[Facturado]
					FROM	#tmp											temp
					GROUP BY MONTH(temp.ct_date)
					ORDER BY [Date] ASC
			END

		IF @intDateDiffGroupBy = 3
			BEGIN
				SELECT
					YEAR(temp.ct_date)										[Date],
					SUM(temp.[Total_Pagado])								[Total_Pagado],
					SUM(temp.[Total_PendienteDePago_NoVencido])				[Total_PendienteDePago_NoVencido],
					SUM(temp.[Total_PendienteDePago_Vencido])				[Total_PendienteDePago_Vencido],
					SUM(temp.[Facturado])									[Facturado]
					FROM	#tmp											temp
					GROUP BY YEAR(temp.ct_date)
					ORDER BY [Date] ASC
			END



		SELECT
			CASE
				WHEN @intDateDiffGroupBy = 1 THEN	'Día'
				WHEN @intDateDiffGroupBy = 2 THEN	'Mes'
				WHEN @intDateDiffGroupBy = 3 THEN	'Año'
			ELSE									''
			END										[GroupBy]

	END
GO


CREATE PROCEDURE [dbo].[spControlPanelGraphics_getTotalSalesWithConditionalGroupBy]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@brag_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@brag_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@brag_id			= 4,
				@datefrom			= '2021-01-01',
				@dateto				= '2021-02-27'

				DROP TABLE #tmp
		*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

		DECLARE
			@intDateDiffGroupBy	INT


		-- SI EL DATEDIFF ES MENOR A 31 DIAS
		-- ENTONCES AGRUPO POR DIAS
		IF DATEDIFF(DAY,@datefrom,@dateto) < 32
			BEGIN
				SET @intDateDiffGroupBy = 1
			END

		-- SI EL DATEDIFF ES MENOR A 365 DIAS
		-- ENTONCES AGRUPO POR MES
		IF	DATEDIFF(DAY,@datefrom,@dateto) > 31	AND
			 DATEDIFF(DAY,@datefrom,@dateto) < 366
			BEGIN
				SET @intDateDiffGroupBy = 2
			END

		-- SI EL DATEDIFF ES MAYOR A 365 DIAS
		-- ENTONCES AGRUPO POR AÑO
		IF DATEDIFF(DAY,@datefrom,@dateto) > 365
			BEGIN
				SET @intDateDiffGroupBy = 3
			END


		--RECUPERO LA MONEDA DE LA SUCURSAL
		DECLARE
			@lbra_curr_id	INT
		SELECT
			@lbra_curr_id		= tb.curr_id
			FROM tbBranch					AS tb	WITH(NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

	SELECT
		tct.ct_date,
		SUM(dbo.fnGetExchange2(@comp_id, tct.ct_subtotal, tct.curr_id_transaction, @lbra_curr_id,  tct.curr_id4Exchange,tct.curr_id_transaction, tct.ct_curr_IdExchange,'False') *
		vctfs.PlusOrMinus)									[Facturado]
		INTO												#tmp
		FROM tbCommercialTransactions						tct		WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forSalesStats	vctfs	WITH(NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id		AND
				vctfs.bra_id			= tct.bra_id		AND
				vctfs.ct_transaction	= tct.ct_transaction
		--INNER JOIN tbCustomer								tc		WITH(NOLOCK)
		--	ON  tc.comp_id				= tct.comp_id		AND
		--		tc.cust_id				= tct.cust_id
		--INNER JOIN tbsysCountry								AS tc2	WITH(NOLOCK)
		--	ON	tc2.country_id			= tct.country_id
		--INNER JOIN tbsysState								AS ts	WITH(NOLOCK)
		--	ON	ts.country_id			= tct.country_id	AND
		--		ts.state_id				= tct.state_id
		INNER JOIN tbUsers4BranchFilter						vubf	WITH(NOLOCK)
			ON  vubf.comp_id			= tct.comp_id		AND
				vubf.bra_id				= tct.bra_id		AND
				vubf.[user_id]			= @user_id
		INNER JOIN tbBranchGroupDetail						AS tbgd	WITH(NOLOCK)
			ON	tbgd.comp_id			= tct.comp_id		AND
				tbgd.brag_id			= @brag_id			AND
				tbgd.bra_id				= tct.bra_id
		WHERE tct.[comp_id] = @comp_id						AND
			(
				vctfs.sd_id = 1 OR
				vctfs.sd_id = 3
			)												AND
			tct.ct_date  BETWEEN @datefrom AND @dateto
		GROUP BY tct.ct_date

		DECLARE
			@total DECIMAL(19,2)
		SET @total = (SELECT SUM(temp.[Facturado]) [Total] from #tmp temp)

		-- ==
			--SELECT @total
		-- ==

		IF @intDateDiffGroupBy = 1
			BEGIN
				SELECT
					DAY(temp.ct_date)										[Date],
					SUM(temp.[Facturado])									[Facturado],
					(SUM(temp.[Facturado]/dbo.fnNoZDiv(@total) * 100))      [Porcent]
					FROM	#tmp											temp
					WHERE [Facturado] >= 0
					GROUP BY DAY(temp.ct_date)
					ORDER BY [Date] ASC
			END

		IF @intDateDiffGroupBy = 2
			BEGIN
				SELECT
					MONTH(temp.ct_date)										[Date],
					SUM(temp.[Facturado])									[Facturado],
					(SUM(temp.[Facturado]/dbo.fnNoZDiv(@total) * 100))      [Porcent]
					FROM	#tmp											temp
					WHERE [Facturado] >= 0
					GROUP BY MONTH(temp.ct_date)
					ORDER BY [Date] ASC
			END

		IF @intDateDiffGroupBy = 3
			BEGIN
				SELECT
					YEAR(temp.ct_date)										[Date],
					SUM(temp.[Facturado])									[Facturado],
					(SUM(temp.[Facturado]/dbo.fnNoZDiv(@total) * 100))      [Porcent]
					FROM	#tmp											temp
					WHERE [Facturado] >= 0
					GROUP BY YEAR(temp.ct_date)
					ORDER BY [Date] ASC
			END



		SELECT
			CASE
				WHEN @intDateDiffGroupBy = 1 THEN	'Día'
				WHEN @intDateDiffGroupBy = 2 THEN	'Mes'
				WHEN @intDateDiffGroupBy = 3 THEN	'Año'
			ELSE									''
			END										[GroupBy]

	END
GO


CREATE PROCEDURE [dbo].[spControlPanelGraphics_getTotalSalesWithConditionalGroupBy4Columns]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@brag_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
			/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@brag_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@brag_id			= 4,
				@datefrom			= '2024-01-01',
				@dateto				= '2024-08-31'
			*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

		DECLARE
			@intDateDiffGroupBy	INT

		-- ------------------------------------------
		-- SI EL DATEDIFF ES MENOR A 31 DIAS
		-- ENTONCES AGRUPO POR DIAS
		-- ------------------------------------------
		IF DATEDIFF(DAY,@datefrom,@dateto) < 32
			BEGIN
				SET @intDateDiffGroupBy = 1
			END
		-- ------------------------------------------

		-- ------------------------------------------
		-- SI EL DATEDIFF ES MENOR A 365 DIAS
		-- ENTONCES AGRUPO POR MES
		-- ------------------------------------------
		IF	DATEDIFF(DAY,@datefrom,@dateto) > 31	AND
			 DATEDIFF(DAY,@datefrom,@dateto) < 366
			BEGIN
				SET @intDateDiffGroupBy = 2
			END
		-- ------------------------------------------

		-- ------------------------------------------
		-- SI EL DATEDIFF ES MAYOR A 365 DIAS
		-- ENTONCES AGRUPO POR AÑO
		-- ------------------------------------------
		IF DATEDIFF(DAY,@datefrom,@dateto) > 365
			BEGIN
				SET @intDateDiffGroupBy = 3
			END
		-- ------------------------------------------

		-- ------------------------------------------
		-- RECUPERO LA MONEDA DE LA SUCURSAL
		-- ------------------------------------------
		DECLARE
			@lbra_curr_id	INT
		SELECT
			@lbra_curr_id		= tb.curr_id
			FROM tbBranch					AS tb	WITH(NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id
		-- ------------------------------------------

	SELECT
		tct.ct_date,
		-- -----------------------------------------------------------------------------------------------------------------
		-- SI EL A_BALANCE ES 0 SUME EN TOTAL_PAGADO
		-- -----------------------------------------------------------------------------------------------------------------
		SUM	(
			CASE
				WHEN tct.ct_ABalance <> tct.ct_ATotal THEN	dbo.fnGetExchange2(	@comp_id,
																				tct.ct_ATotal - tct.ct_ABalance,
																				tct.ct_ACurrency,
																				@lbra_curr_id,
																				tct.curr_id4Exchange,
																				tct.curr_id_transaction,
																					tct.ct_curr_IdExchange,	'False') *
																				vctfs.PlusOrMinus
				ELSE	0
			END
			)														[Total_Cobrado],
		-- -----------------------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------------------
		-- SI ES <> 0 Y TODAVIA NO SE VENCIÓ SUME EN PENDIENTE NO VENCIDO
		-- -----------------------------------------------------------------------------------------------------------------
		SUM	(
			CASE
				WHEN tct.ct_ABalance > 0 AND tct.ct_payDate >= GETDATE() THEN	dbo.fnGetExchange2(	@comp_id,
																									tct.ct_ABalance,
																									tct.ct_ACurrency,
																									@lbra_curr_id,
																									tct.curr_id4Exchange,
																									tct.curr_id_transaction,
																									tct.ct_curr_IdExchange,	'False') *
																									vctfs.PlusOrMinus
				ELSE	0
			END
			)														[Total_PendienteDeCobro_NoVencido],
		-- -----------------------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------------------------------
		-- SI ES <> 0 y SE VENCIO SUME EN PENDIENTE VENCIDO
		-- -----------------------------------------------------------------------------------------------------------------
		SUM	(
			CASE
				WHEN tct.ct_ABalance > 0 AND tct.ct_payDate < GETDATE() THEN	dbo.fnGetExchange2(	@comp_id,
																									tct.ct_ABalance,
																									tct.ct_ACurrency,
																									@lbra_curr_id,
																									tct.curr_id4Exchange,
																									tct.curr_id_transaction,
																									tct.ct_curr_IdExchange,	'False') *
																									vctfs.PlusOrMinus
				ELSE	0
			END
			)														[Total_PendienteDeCobro_Vencido],
		-- -----------------------------------------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------------------
		-- TOTAL GENERAL
		-- -----------------------------------------------------------------------------------------------------------------
		SUM(dbo.fnGetExchange2(	@comp_id,
								tct.ct_ATotal,
								tct.ct_ACurrency,
								@lbra_curr_id,
								tct.curr_id4Exchange,
								tct.curr_id_transaction,
								tct.ct_curr_IdExchange,	 'False') *
								vctfs.PlusOrMinus)					[Facturado]
		-- -----------------------------------------------------------------------------------------------------------------


		INTO												#tmp
		FROM tbCommercialTransactions						tct			WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forSalesStats	AS vctfs	WITH(NOLOCK)
		ON		vctfs.comp_id			= tct.comp_id		AND
				vctfs.bra_id			= tct.bra_id		AND
				vctfs.ct_transaction	= tct.ct_transaction
		INNER JOIN tbUsers4BranchFilter						vubf	WITH(NOLOCK)
			ON  vubf.comp_id			= tct.comp_id		AND
				vubf.bra_id				= tct.bra_id		AND
				vubf.[user_id]			= @user_id
		INNER JOIN tbBranchGroupDetail						AS tbgd	WITH(NOLOCK)
			ON	tbgd.comp_id			= tct.comp_id		AND
				tbgd.brag_id			= @brag_id			AND
				tbgd.bra_id				= tct.bra_id
		WHERE tct.[comp_id] = @comp_id						AND
			(
				vctfs.sd_id = 1 OR
				vctfs.sd_id = 3
			)												AND
			tct.ct_date  BETWEEN @datefrom AND @dateto
		GROUP BY tct.ct_date


		IF @intDateDiffGroupBy = 1
			BEGIN
				SELECT
					DAY(temp.ct_date)										[Date],
					SUM(temp.[Total_Cobrado])								[Total_Cobrado],
					SUM(temp.[Total_PendienteDeCobro_NoVencido])			[Total_PendienteDeCobro_NoVencido],
					SUM(temp.[Total_PendienteDeCobro_Vencido])				[Total_PendienteDeCobro_Vencido],
					SUM(temp.[Facturado])									[Facturado]
					FROM	#tmp											temp
					WHERE [Facturado] >= 0
					GROUP BY DAY(temp.ct_date)
					ORDER BY [Date] ASC
			END

		IF @intDateDiffGroupBy = 2
			BEGIN
				SELECT
					MONTH(temp.ct_date)										[Date],
					SUM(temp.[Total_Cobrado])								[Total_Cobrado],
					SUM(temp.[Total_PendienteDeCobro_NoVencido])			[Total_PendienteDeCobro_NoVencido],
					SUM(temp.[Total_PendienteDeCobro_Vencido])				[Total_PendienteDeCobro_Vencido],
					SUM(temp.[Facturado])									[Facturado]
					FROM	#tmp											temp
					WHERE [Facturado] >= 0
					GROUP BY MONTH(temp.ct_date)
					ORDER BY [Date] ASC
			END

		IF @intDateDiffGroupBy = 3
			BEGIN
				SELECT
					YEAR(temp.ct_date)										[Date],
					SUM(temp.[Total_Cobrado])								[Total_Cobrado],
					SUM(temp.[Total_PendienteDeCobro_NoVencido])			[Total_PendienteDeCobro_NoVencido],
					SUM(temp.[Total_PendienteDeCobro_Vencido])				[Total_PendienteDeCobro_Vencido],
					SUM(temp.[Facturado])									[Facturado]
					FROM	#tmp											temp
					WHERE [Facturado] >= 0
					GROUP BY YEAR(temp.ct_date)
					ORDER BY [Date] ASC
			END



		SELECT
			CASE
				WHEN @intDateDiffGroupBy = 1 THEN	'Día'
				WHEN @intDateDiffGroupBy = 2 THEN	'Mes'
				WHEN @intDateDiffGroupBy = 3 THEN	'Año'
			ELSE									''
			END										[GroupBy]


		DROP TABLE #tmp


	END
GO

