CREATE  PROCEDURE [dbo].[spControlPanelHistory_insertData]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@brag_id		INT,
	@cpmc_id		INT,
	@dateFrom		DATETIME,
	@dateTo			DATETIME,
	@dateActual		DATETIME,
	@option			INT,
	@user_id		INT

)

as

set nocount on;


--select
--	@comp_id		[comp_id],
--	@lang_id		[lang_id],
--	@bra_id			[bra_id],
--	@brag_id		[brag_id],
--	@cpmc_id		[cpmc_id],
--	@dateFrom		[dateFrom],
--	@dateTo			[dateTo],
--	@dateActual		[dateActual],
--	@option			[option]--,
--	@user_id		[user_id]

--select 'history'

Insert into tbControlPanelHistory
		(
		 comp_id,
		 brag_id,
		 scpm_id,
		 cpmc_id,
		 prof_id,
		 [user_id],
		 curr_id,
		 total,
		 cph_cd,
		 generic_id
		)

		(SELECT	tcpmp.comp_id,
				tcpmp.brag_id,
				tcpmp.scpm_id,
				tcpmp.cpmc_id,
				tcpmp.prof_id,
				@user_id,
				tb.curr_id,
				tmp.total,
				Getdate(),
				tmp.Id

		FROM	dbo.tbControlPanelMeasures4Profiles				tcpmp

		INNER JOIN	dbo.tbsysControlPanelMeasures		tcpm
		ON			tcpm.scpm_id	=	tcpmp.scpm_id

		INNER JOIN	dbo.tbControlPanelMeasureCategories tcpmc
		ON			tcpmc.comp_id	=	tcpmp.comp_id
		AND			tcpmc.cpmc_id	=	tcpmp.cpmc_id

		INNER JOIN	dbo.tbBranchGroup					tbg
		ON			tbg.comp_id		=	tcpmp.comp_id
		AND			tbg.brag_id		=	tcpmp.brag_id

		INNER JOIN	dbo.tbBranchGroupDetail				tbgd
		ON			tbgd.comp_id	=	tcpmp.comp_id
		AND			tbgd.brag_id	=	tcpmp.brag_id

		INNER JOIN	dbo.tbBranch						tb
		ON			tb.comp_id		=	tbgd.comp_id
		AND			tb.bra_id		=	tbgd.bra_id

		INNER JOIN	dbo.tbProfile						tp
		ON			tp.comp_id		=	tcpmp.comp_id
		AND			tp.prof_id		=	tcpmp.prof_id

		INNER JOIN	#tmpControlPanelMeasures			tmp
		ON			tmp.scpm_id		=	tcpm.scpm_id
		and			tmp.Id1			=	tb.bra_id


WHERE	tcpmp.comp_id	=	@comp_id
AND		(@brag_id		=	-1		or		 tcpmp.brag_id  = @brag_id)
AND		(@cpmc_id		=   -1		or		 tcpmp.cpmc_id	= @cpmc_id)
AND		((@option = 1  and tmp.total <		 tcpmp.cpm4p_min ) or
		 (@option = 2  and tmp.total >		 tcpmp.cpm4p_max ) or
		 (@option = 3  AND tmp.total BETWEEN tcpmp.cpm4p_min AND tcpmp.cpm4p_max))
)



--		LEFT JOIN	tbsysOptionsValues					tov
--		ON			tov.lang_id		=	@lang_id
--		AND			tov.optval_id	=	tcpm.scpm_id
--		AND			tov.optval_class=	58
GO






