(
		@comp_id	INT
)
AS

SET NOCOUNT ON

/*
DECLARE
		@comp_id	INT,
		@cpmc_id	INT

SELECT
		@comp_id	= 1,
		@cpmc_id	= 1
*/

SELECT
		tcpmc.cpmc_id [ID],
		tcpmc.cpmc_desc [Desc]

FROM dbo.tbControlPanelMeasureCategories tcpmc

WHERE	tcpmc.comp_id = @comp_id
AND		tcpmc.cpmc_id = tcpmc.cpmc_id
GO





