CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_BRANCH_SalesMonthDifference]
(

	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id    AS INT,
	@rank       AS INT,
	@user_id    AS INT


)
AS
SET NOCOUNT ON;
/*

	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE	@case_id	as INT
	DECLARE @rank       AS INT
	DECLARE @user_id	AS INT



	SET     @comp_id    = 1
	SET		@lang_id	= 2
	SET		@bra_id	    = 1
	SET     @brag_id    = -1
	SET		@dateFrom   = '2000/04/01'
	SET		@dateTo     = '9999/31/12'
	SET		@dateActual = '2009/20/11'
	SET		@id2Grid	= 1
	SET     @case_id    = 4
	SET     @rank       = 3
	SET     @user_id    = 1

*/

SELECT @rank = @rank * -1

SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date[Fecha],
		tc.cust_name[Cliente],


		CASE vctfss.sd_isCredit WHEN 'False' THEN
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		ELSE
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		END											[Total],

	  tst.st_desc[Condición de Venta],
	  tb.bra_desc[Sucursal]

FROM tbCommercialTransactions								tct

	INNER JOIN dbo.vwCommercialTransactions_forSales		vctfss
	ON		vctfss.comp_id			= tct.comp_id
	AND		vctfss.bra_id			= tct.bra_id
	AND		vctfss.ct_transaction	= tct.ct_transaction
	AND		vctfss.sd_isReceipt		=	'False'

	INNER JOIN tbBranchGroup								tbg
	ON tbg.comp_id					=	tct.comp_id

	INNER JOIN tbBranchGroupDetail							tbgd
	ON		tbgd.comp_id			= tct.comp_id
	AND		tbgd.brag_id			= tbg.brag_id
	AND		tbgd.bra_id				= tct.bra_id

	INNER JOIN tbItemTransactions							tit
	ON		tit.comp_id				=	tct.comp_id
	AND		tit.bra_id				=	tct.bra_id
	AND		tit.ct_transaction		=	tct.ct_transaction

	INNER JOIN vwItemTransactions							vit
	ON		vit.comp_id				=	tit.comp_id
	AND		vit.it_transaction		=	tit.it_transaction

	INNER JOIN  dbo.tbCustomer								tc
	ON		tc.comp_id				= tct.comp_id
	AND		tc.cust_id				= tct.cust_id

	INNER JOIN dbo.tbSalesTerms								tst
	ON		tst.comp_id				= tct.comp_id
	AND		tst.st_id				= tct.st_id

	INNER JOIN	tbBranch									tb
	ON		tb.comp_id				= tct.comp_id
	AND		tb.bra_id				= tct.bra_id

	INNER JOIN vwUsers4BranchFilter							vubf
	ON		vubf.comp_id			=  tct.comp_id
	AND		vubf.bra_id				=  tct.bra_id
	AND		vubf.[user_id]			=  @user_id


WHERE	tct.comp_id		= @comp_id
AND		tct.bra_id		= @id2Grid
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id = 4	AND	 tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual) AND @dateActual
OR 		tct.ct_date	 BETWEEN DATEADD(MONTH,@rank -12,@dateActual) AND DATEADD(MONTH,-12,@dateActual))


ORDER BY ct_date










GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Movimientos de Venta
--				del mes en curso de un Vendedor
--				para ser mostrados en la grilla
--				del panel de control.-
-- =============================================


CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_BRANCH_SalesOfThisMonth]
(

	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id    AS INT,
	@user_id    AS INT

)
AS
SET NOCOUNT ON;
/*

	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE @case_id    AS INT
	DECLARE @user_id    AS INT



	SET     @comp_id    = 1
	SET		@lang_id	= 2
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2009/01/01'
	SET		@dateTo     = '2009/31/12'
	SET		@dateActual = '2009/20/11'
	SET		@id2Grid	= 1
	SET     @case_id    = 5
	SET     @user_id    = 1
*/

SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date																		[Fecha],
		tc.cust_name																	[Cliente],

	CASE WHEN @case_id < 3
			THEN
			CASE vctfss.sd_isCredit WHEN 'False' THEN
				IsNull(dbo.fnGetExchange(tct.comp_id,
								 tct.ct_total,
								 tct.curr_id_transaction,
								 ct_CompanyCurrency,
								 ct_CompanyCurrency,
								 ct_Branch2CompanyCurrencyExchange,
								 'false'),0)
			ELSE
				IsNull(dbo.fnGetExchange(tct.comp_id,
								 tct.ct_total * -1,
								 tct.curr_id_transaction,
								 ct_CompanyCurrency,
								 ct_CompanyCurrency,
								 ct_Branch2CompanyCurrencyExchange,
								 'false'),0)
			END

     WHEN @case_id = 3
			Then
				 CASE vctfss.sd_isCredit WHEN 'False' THEN
					     IsNull(dbo.fnGetExchange(tct.comp_id,
										 tct.ct_total,
										 tct.curr_id_transaction,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				ELSE
					      IsNull(dbo.fnGetExchange(tct.comp_id,
										 tct.ct_total * -1,
										 tct.curr_id_transaction,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
		END --/ COUNT(DISTINCT MONTH(tct.ct_date))

		WHEN @case_id > 4 AND @case_id < 8
			THEN
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				ELSE
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance * -1,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				END



	END														[Total],
  tst.st_desc												[Condición de Venta],
  tb.bra_desc												[Sucursal]
FROM tbCommercialTransactions tct

		INNER JOIN dbo.vwCommercialTransactions_forSalesStats				vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN tbBranchGroupDetail										tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.brag_id			= @brag_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup											tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN  dbo.tbCustomer											tc
		ON		tc.comp_id				= tct.comp_id
		AND		tc.cust_id				= tct.cust_id

		INNER JOIN dbo.tbSalesTerms											tst
		ON		tst.comp_id				= tct.comp_id
		AND		tst.st_id				= tct.st_id

		INNER JOIN	tbBranch												tb
		ON		tb.comp_id				= tct.comp_id
		AND		tb.bra_id				= tct.bra_id

		INNER JOIN vwUsers4BranchFilter							vubf
		ON		vubf.comp_id			=  tct.comp_id
		AND		vubf.bra_id				=  tct.bra_id
		AND		vubf.[user_id]			=  @user_id


WHERE	tct.comp_id		= @comp_id
AND		tct.bra_id   	= @id2Grid
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		(
		(@case_id IN (1,5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2,6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3,7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		)


ORDER BY ct_date







GO







CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_BRAND_SalesMonthDifference]
(
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	as INT,
	@rank       AS INT,
	@user_id    AS INT

)
AS
SET NOCOUNT ON


/*
DECLARE @comp_id		INT,
		@lang_id		INT,
		@bra_id			INT,
		@brag_id		INT,
		@dateFrom		DATETIME,
		@dateTo			DATETIME,
		@dateActual		DATETIME,
		@id2Grid		INT,
		@id2Grid2		INT,
		@case_id		INT,
		@rank			INT,
		@user_id        INT


SELECT  @comp_id		= 1,
		@lang_id		= 2,
		@bra_id			= 1,
		@brag_id		= -1,
		@dateFrom		= '2000/01/01',
		@dateTo			= '9999/31/12',
		@dateActual		= '2009/20/11',
		@id2Grid		= 20,
		@case_id		= 4,
		@rank			= 3,
		@user_id        = 1


*/

SELECT @rank = @rank * -1


SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date																		[Fecha],

		CASE vctfss.sd_isCredit WHEN 'False' THEN
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		ELSE
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		END											[Total],
		tb.brand_desc								[Marca],
		tit.it_qty									[Cantidad]

FROM	tbCommercialTransactions								tct

		INNER JOIN dbo.vwCommercialTransactions_forSales	vctfss
		ON		vctfss.comp_id			=	tct.comp_id
		AND		vctfss.bra_id			=	tct.bra_id
		AND		vctfss.ct_transaction	=	tct.ct_transaction
		AND		vctfss.sd_isReceipt		=	'False'

		INNER JOIN tbBranchGroup								tbg
		ON tbg.comp_id					=	tct.comp_id

		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			=	tct.comp_id
		AND		tbgd.brag_id			=	tbg.brag_id
		AND		tbgd.bra_id				=	tct.bra_id

		INNER JOIN tbItemTransactions							tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction

		INNER JOIN vwItemTransactions							vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction

		INNER JOIN	tbItem										ti
		ON		ti.comp_id				=	tit.comp_id
		AND		ti.item_id				=	tit.item_id

		inner JOIN tbBrand                                      tb
		ON		tb.comp_id				=	ti.comp_id
		AND		tb.brand_id				=	ti.brand_id

		INNER JOIN vwUsers4BranchFilter							vubf
		ON		vubf.comp_id			=  tct.comp_id
		AND		vubf.bra_id				=  tct.bra_id
		AND		vubf.[user_id]			=  @user_id


WHERE	tct.comp_id		= @comp_id
AND		tct.bra_id		= @bra_id
AND		tb.brand_id		= @id2Grid
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8) AND
				(tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual)	AND @dateActual
			OR	tct.ct_date BETWEEN DATEADD(MONTH,@rank-12,@dateActual) AND DATEADD(MONTH,-12,@dateActual)))


ORDER BY ct_date










GO







CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_BRAND_SalesOfThisMonth]
(
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	as INT,
	@user_id    AS INT

)
AS
SET NOCOUNT ON

/*
	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE @case_id	AS INT
	DECLARE @user_id    AS INT


	SET     @comp_id    = 1
	SET		@lang_id	= 2
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '2009/31/12'
	SET		@dateActual = '2009/20/11'
	SET		@id2Grid	= 20
	SET		@case_id	= 1
	SET     @user_id     = 1
	*/


SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date																		[Fecha],
		CASE WHEN @case_id < 3
			THEN
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false'),0)
				ELSE
					IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false'),0)
				END
		WHEN @case_id = 3
			Then
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				ELSE
					IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				END --/ COUNT(DISTINCT MONTH(tct.ct_date))

		END														[Total],
		tb.brand_desc											[Marca],
		tit.it_qty												[Cantidad]

FROM	tbCommercialTransactions								tct

		INNER JOIN dbo.vwCommercialTransactions_forSalesStats	vctfss
		ON		vctfss.comp_id			=	tct.comp_id
		AND		vctfss.bra_id			=	tct.bra_id
		AND		vctfss.ct_transaction	=	tct.ct_transaction

		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			=	tct.comp_id
		AND		tbgd.brag_id			=	@brag_id
		AND		tbgd.bra_id				=	tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN tbItemTransactions							tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction

		INNER JOIN vwItemTransactions							vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction

		INNER JOIN	tbItem										ti
		ON		ti.comp_id				=	tit.comp_id
		AND		ti.item_id				=	tit.item_id

		INNER JOIN tbBrand                                      tb
		ON tb.comp_id					= ti.comp_id
		AND tb.brand_id					= ti.brand_id

		INNER JOIN vwUsers4BranchFilter							vubf
		ON		vubf.comp_id			=  tct.comp_id
		AND		vubf.bra_id				=  tct.bra_id
		AND		vubf.[user_id]			=  @user_id

WHERE	 tct.comp_id					= @comp_id
AND		 tb.brand_id  					= @id2Grid
AND		(@brag_id						= -1	or	tbgd.brag_id	= @brag_id)

AND		(
		(@case_id IN (1,5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2,6)	AND	year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3,7)   AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		)


ORDER BY ct_date









GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Movimientos de Venta
--				del mes en curso de un Vendedor
--				para ser mostrados en la grilla
--				del panel de control.-
-- =============================================


CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_COUNTRY_SalesMonthDifference]

	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	AS INT,
	@rank       AS INT,
	@user_id    AS INT



AS
SET NOCOUNT ON;
/*
	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE @case_id    AS INT
	DECLARE @rank       AS INT
	DECLARE @user_id	AS INT


	SET     @comp_id    = 1
	SET		@lang_id	= 2
	SET		@bra_id	    = 1
	SET     @brag_id    = -1
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '9999/31/12'
	SET		@dateActual = '2009/20/11'
	SET		@id2Grid	= 54
	SET     @case_id    = 4
	SET     @rank       = 3
	SET		@user_id    = 1

*/

SELECT @rank = @rank * -1

SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date																		[Fecha],
		tc2.country_desc																[País],

		CASE vctfss.sd_isCredit WHEN 'False' THEN
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		ELSE
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		END											[Total],

	    tst.st_desc									[Condición de Venta],
	    tck.ck_name									[Tipo de Cliente],
	    td.dl_name									[Transporte]

FROM tbCommercialTransactions											tct

	INNER JOIN dbo.vwCommercialTransactions_forSales					vctfss
	ON		vctfss.comp_id			= tct.comp_id
	AND		vctfss.bra_id			= tct.bra_id
	AND		vctfss.ct_transaction	= tct.ct_transaction
	AND		vctfss.sd_isReceipt		=	'False'

	INNER JOIN tbBranchGroup											tbg
	ON tbg.comp_id					= tct.comp_id

	INNER JOIN tbBranchGroupDetail										tbgd
	ON		tbgd.comp_id			= tct.comp_id
	AND		tbgd.brag_id			= tbg.brag_id
	AND		tbgd.bra_id				= tct.bra_id

	INNER JOIN tbItemTransactions										tit
	ON		tit.comp_id				=	tct.comp_id
	AND		tit.bra_id				=	tct.bra_id
	AND		tit.ct_transaction		=	tct.ct_transaction

	INNER JOIN vwItemTransactions										vit
	ON		vit.comp_id				=	tit.comp_id
	AND		vit.it_transaction		=	tit.it_transaction

	INNER JOIN  dbo.tbCustomer											tc
	ON		tc.comp_id				= tct.comp_id
	AND		tc.cust_id				= tct.cust_id

	INNER JOIN tbsysCountry												tc2
	ON		tc2.country_id			= tc.country_id

	INNER JOIN tbCustomerKind											tck
	ON		tck.comp_id				= tc.comp_id
	AND		tck.ck_id				= tc.ck_id

	INNER JOIN dbo.tbSalesTerms											tst
	ON		tst.comp_id				= tct.comp_id
	AND		tst.st_id				= tct.st_id

	INNER JOIN dbo.tbDelivery											td
	ON		td.comp_id				= tct.comp_id
	AND		td.dl_id				= tct.dl_id

	INNER JOIN vwUsers4BranchFilter										vubf
	ON		vubf.comp_id			=  tct.comp_id
	AND		vubf.bra_id				=  tct.bra_id
	AND		vubf.[user_id]			=  @user_id


WHERE	tct.comp_id		= @comp_id
AND		tc2.country_id	= @id2Grid
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id = 4	AND	 tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual) AND @dateActual
OR 		tct.ct_date	 BETWEEN DATEADD(MONTH,@rank-12,@dateActual) AND DATEADD(MONTH,-12,@dateActual))


ORDER BY ct_date





GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Movimientos de Venta
--				del mes en curso de un Vendedor
--				para ser mostrados en la grilla
--				del panel de control.-
-- =============================================



CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_COUNTRY_SalesOfThisMonth]
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	AS INT,
	@user_id   AS INT


AS
SET NOCOUNT ON;

/*
	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE @case_id	AS INT
	DECLARE @user_id   AS INT



	SET     @comp_id    = 1
	SET		@lang_id	= 2
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2009/01/01'
	SET		@dateTo     = '2009/31/12'
	SET		@dateActual = '2009/20/11'
	SET		@id2Grid	= 54
	SET		@case_id    = 5
	SET		@user_id    = 1

*/

SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
			tct.ct_date																	[Fecha],
			tc2.country_desc															[País],


	CASE WHEN @case_id < 3
			THEN
			CASE vctfss.sd_isCredit WHEN 'False' THEN
				IsNull(dbo.fnGetExchange(tct.comp_id,
								 tct.ct_total,
								 tct.curr_id_transaction,
								 ct_CompanyCurrency,
								 ct_CompanyCurrency,
								 ct_Branch2CompanyCurrencyExchange,
								 'false'),0)
			ELSE
				IsNull(dbo.fnGetExchange(tct.comp_id,
								 tct.ct_total * -1,
								 tct.curr_id_transaction,
								 ct_CompanyCurrency,
								 ct_CompanyCurrency,
								 ct_Branch2CompanyCurrencyExchange,
								 'false'),0)
			END



			WHEN @case_id = 3
			Then
				 CASE vctfss.sd_isCredit WHEN 'False' THEN
					     IsNull(dbo.fnGetExchange(tct.comp_id,
										 tct.ct_total,
										 tct.curr_id_transaction,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				ELSE
					      IsNull(dbo.fnGetExchange(tct.comp_id,
										 tct.ct_total * -1,
										 tct.curr_id_transaction,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
		END --/ COUNT(DISTINCT MONTH(tct.ct_date))
		WHEN @case_id > 4 AND @case_id < 8
			THEN
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				ELSE
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance * -1,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				END



	END														[Total],
	  tst.st_desc											[Condición de Venta],
	  tck.ck_name											[Tipo de Cliente],
	  td.dl_name											[Transporte]

FROM tbCommercialTransactions tct

		INNER JOIN dbo.vwCommercialTransactions_forSalesStats			vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN tbBranchGroupDetail									tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.brag_id			= @brag_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup										tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN  dbo.tbCustomer										tc
		ON		tc.comp_id				= tct.comp_id
		AND		tc.cust_id				= tct.cust_id

		INNER JOIN tbsysCountry											tc2
		ON		tc2.country_id			= tc.country_id

		INNER JOIN tbCustomerKind										tck
		ON		tck.comp_id				= tc.comp_id
		AND		tck.ck_id				= tc.ck_id

		INNER JOIN dbo.tbSalesTerms										tst
		ON		tst.comp_id				= tct.comp_id
		AND		tst.st_id				= tct.st_id

		INNER JOIN dbo.tbDelivery										td
		ON		td.comp_id				= tct.comp_id
		AND		td.dl_id				= tct.dl_id

		INNER JOIN vwUsers4BranchFilter										vubf
		ON		vubf.comp_id			=  tct.comp_id
		AND		vubf.bra_id				=  tct.bra_id
		AND		vubf.[user_id]			=  @user_id


WHERE	tct.comp_id				= @comp_id
AND		tct.country_id      	= @id2Grid
AND		(@brag_id		        = -1	or	tbgd.brag_id	= @brag_id)

AND		(
		(@case_id IN (1,5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2,6)	AND	year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3,7)   AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		)

ORDER BY ct_date






GO





