										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				ELSE
					IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal* -1,
									 vit.curr_id,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				END --/ COUNT(DISTINCT MONTH(tct.ct_date))

		END														[Total],
		ti.item_desc											[Articulo],
		tit.it_qty												[Cantidad]

FROM	tbCommercialTransactions								tct

	INNER JOIN dbo.vwCommercialTransactions_forSalesStats		vctfss
	ON		vctfss.comp_id			=	tct.comp_id
	AND		vctfss.bra_id			=	tct.bra_id
	AND		vctfss.ct_transaction	=	tct.ct_transaction

	INNER JOIN tbBranchGroupDetail								tbgd
	ON		tbgd.comp_id			=	tct.comp_id
	AND		tbgd.brag_id			=	@brag_id
	AND		tbgd.bra_id				=	tct.bra_id

	INNER JOIN tbBranchGroup									tbg
	ON		tbg.comp_id				= tct.comp_id
	AND		tbg.brag_id				= tbgd.brag_id

	INNER JOIN tbItemTransactions								tit
	ON		tit.comp_id				=	tct.comp_id
	AND		tit.bra_id				=	tct.bra_id
	AND		tit.ct_transaction		=	tct.ct_transaction

	INNER JOIN vwItemTransactions								vit
	ON		vit.comp_id				=	tit.comp_id
	AND		vit.it_transaction		=	tit.it_transaction

	INNER JOIN	tbItem											ti
	ON		ti.comp_id				=	tit.comp_id
	AND		ti.item_id				=	tit.item_id

	INNER JOIN vwUsers4BranchFilter							vubf
	ON  vubf.comp_id				= tct.comp_id
	AND vubf.bra_id					= tct.bra_id
	AND vubf.[user_id]				= @user_id



WHERE	 tct.comp_id		= @comp_id
AND		 ti.item_id  		= @id2Grid
AND		 (@brag_id		    = -1	or	tbgd.brag_id	= @brag_id)

AND	(
		(@case_id IN (1,5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2,6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3,7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
	)


ORDER BY ct_date









GO






CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_ITEMCATEGORY_SalesMonthDifference]
(
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	as INT,
	@rank       AS INT,
	@user_id	AS INT

)
AS
SET NOCOUNT ON

/*
DECLARE @comp_id	AS INT
DECLARE @lang_id	AS INT
DECLARE @bra_id		AS INT
DECLARE @brag_id	AS INT
DECLARE @dateFrom	AS DATETIME
DECLARE @dateTo		AS DATETIME
DECLARE @dateActual AS DATETIME
DECLARE @id2Grid	AS INT
DECLARE @id2Grid2	AS INT,
		@case_id	as INT,
		@rank       AS INT,
		@user_id	AS int



SELECT  @comp_id		= 1,
		@lang_id		= 2,
		@bra_id			= 1,
		@brag_id		= 2,
		@dateFrom		= '2000/01/01',
		@dateTo			= '2009/31/12',
		@dateActual		= '2009/26/10',
		@id2Grid		= 15,
		@case_id		= 8,
		@rank			= 6,
		@user_id		= 1

*/


SELECT @rank = @rank * -1

SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date,
		tc.cat_desc,
	CASE vctfss.sd_isCredit WHEN 'False' THEN
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		ELSE
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		END											[Total],

		tst.st_desc,
		tck.ck_name,
		tc.cat_id,
		td.dl_name

FROM	tbCommercialTransactions								tct

	INNER JOIN dbo.vwCommercialTransactions_forSales		vctfss
	ON		vctfss.comp_id				= tct.comp_id
	AND		vctfss.bra_id				= tct.bra_id
	AND		vctfss.ct_transaction		= tct.ct_transaction
	AND		vctfss.sd_isReceipt		=	'False'

	INNER JOIN tbBranchGroup								tbg
	ON tbg.comp_id					=	tct.comp_id

	INNER JOIN tbBranchGroupDetail								tbgd
	ON		tbgd.comp_id				=	tct.comp_id
	AND		tbgd.bra_id					=	tct.bra_id

	INNER JOIN tbItemTransactions								tit
	ON		tit.comp_id					=	tct.comp_id
	AND		tit.bra_id					=	tct.bra_id
	AND		tit.ct_transaction			=	tct.ct_transaction

	INNER JOIN vwItemTransactions								vit
	ON		vit.comp_id					=	tit.comp_id
	AND		vit.it_transaction			=	tit.it_transaction

	INNER JOIN tbItem											ti
	ON		ti.comp_id					=	tit.comp_id
	AND		ti.item_id					=	tit.item_id


	INNER JOIN tbCategory										tc
	ON		tc.comp_id					=	ti.comp_id
	AND		tc.cat_id					=	ti.cat_id

	INNER JOIN  dbo.tbCustomer									tctt
	ON		tctt.comp_id				= tct.comp_id
	AND		tctt.cust_id				= tct.cust_id

	INNER JOIN tbCustomerKind									tck
	ON		tck.comp_id					= tctt.comp_id
	AND		tck.ck_id					= tctt.ck_id

	INNER JOIN dbo.tbSalesTerms									tst
	ON		tst.comp_id					= tct.comp_id
	AND		tst.st_id					= tct.st_id

	INNER JOIN dbo.tbDelivery									td
	ON		td.comp_id					= tct.comp_id
	AND		td.dl_id					= tct.dl_id


	inner join vwUsers4BranchFilter								vubf
	ON  vubf.comp_id				= tct.comp_id
	AND vubf.bra_id					= tct.bra_id
	AND vubf.[user_id]				= @user_id


WHERE	tct.comp_id							= @comp_id
AND		tc.cat_id							= @id2Grid
AND		(@brag_id							= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8) AND
		(tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual)	AND @dateActual
		OR	tct.ct_date BETWEEN DATEADD(MONTH,@rank-12,@dateActual) AND DATEADD(MONTH,-12,@dateActual)))


ORDER BY ct_date






GO







CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_ITEMCATEGORY_SalesOfThisMonth]
(
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	as INT,
	@user_id	AS INT

)
AS
SET NOCOUNT ON


/*
	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE @case_id	AS INT
	DECLARE @user_id    AS int


	SET     @comp_id    = 1
	SET		@lang_id	= 2
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2009/01/01'
	SET		@dateTo     = '2009/31/12'
	SET		@dateActual = '2009/20/07'
	SET		@id2Grid	= 3
	SET		@case_id =    1
	SET     @user_id =    1


*/


SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date,
		tc.cat_desc,
		CASE WHEN @case_id < 3
			THEN
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false'),0)
				ELSE
					IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false'),0)
				END
		WHEN @case_id = 3
			Then
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				ELSE
					IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				END --/ COUNT(DISTINCT MONTH(tct.ct_date))

				/*
		WHEN @case_id > 4 AND @case_id < 8
			THEN
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				ELSE
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance * -1,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				END */

		END														[Total],

		ti.item_desc,
		tit.it_qty

FROM	tbCommercialTransactions								tct

		INNER JOIN dbo.vwCommercialTransactions_forSalesStats	vctfss
		ON		vctfss.comp_id			=	tct.comp_id
		AND		vctfss.bra_id			=	tct.bra_id
		AND		vctfss.ct_transaction	=	tct.ct_transaction

		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			=	tct.comp_id
		AND		tbgd.bra_id				=	tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				=	tct.comp_id
		AND		tbg.brag_id				=	tbgd.brag_id

		INNER JOIN tbItemTransactions							tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction

		INNER JOIN vwItemTransactions							vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction

		INNER JOIN	tbItem										ti
		ON		ti.comp_id				=	tit.comp_id
		AND		ti.item_id				=	tit.item_id

		INNER JOIN tbCategory									tc
		ON		tc.comp_id				=	tct.comp_id
		AND		tc.cat_id				=	ti.cat_id

		inner join vwUsers4BranchFilter							vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id					= tct.bra_id
		AND vubf.[user_id]				= @user_id


WHERE	tct.comp_id		= @comp_id
AND		ti.cat_id  		= @id2Grid
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		(
		(@case_id IN (1,5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2,6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3,7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		)


ORDER BY ct_date







GO






CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_ITEMSUBCATEGORY_SalesMonthDifference]
(
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	as INT,
	@rank       AS INT,
	@user_id	AS INT


)
AS
SET NOCOUNT ON


/*
DECLARE @comp_id	AS INT
DECLARE @lang_id	AS INT
DECLARE @bra_id		AS INT
DECLARE @brag_id	AS INT
DECLARE @dateFrom	AS DATETIME
DECLARE @dateTo		AS DATETIME
DECLARE @dateActual AS DATETIME
DECLARE @id2Grid	AS INT
DECLARE @id2Grid2	AS INT,
		@case_id	as INT,
		@rank       as INT,
		@user_id	as INT



SET     @comp_id    = 1
SET		@lang_id	= 2
SET		@bra_id	    = 1
SET     @brag_id    = 2
SET		@dateFrom   = '2009/04/04'
SET		@dateTo     = '2009/04/04'
SET		@dateActual = '2009/26/10'
SELECT 	@id2Grid	= 1,
		@case_id	= 4,
		@rank       = 6,
		@user_id    = 1
*/

SELECT @rank = @rank * -1


SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date[Fecha],
		tsc.subcat_desc[Subcategoria],
		CASE vctfss.sd_isCredit WHEN 'False' THEN
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		ELSE
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		END											[Total],
		tst.st_desc[Cond.Venta],
		tck.ck_name[Tipo Cliente],
		td.dl_name[Transporte]

FROM	tbCommercialTransactions tct

		INNER JOIN dbo.vwCommercialTransactions_forSales				vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction
		AND		vctfss.sd_isReceipt		=	'False'

		INNER JOIN tbSubCategory											tsc
		ON		tsc.comp_id					= tct.comp_id
		AND		tsc.bra_id					= tct.bra_id


		INNER JOIN tbBranchGroup											tbg
		ON tbg.comp_id					=	tct.comp_id



		INNER JOIN tbBranchGroupDetail										tbgd
		ON		tbgd.comp_id			=   tct.comp_id
		AND		tbgd.bra_id				=	tct.bra_id


		INNER JOIN tbItemTransactions										tit
		ON		tit.comp_id				=	  tct.comp_id
		AND		tit.bra_id				=	  tct.bra_id
		AND		tit.ct_transaction		=	  tct.ct_transaction


		INNER JOIN vwItemTransactions										vit
		ON		vit.comp_id				=	  tit.comp_id
		AND		vit.it_transaction		=	  tit.it_transaction


		INNER JOIN  dbo.tbCustomer											tc
		ON		tc.comp_id				=     tct.comp_id
		AND		tc.cust_id				=     tct.cust_id
		AND		tc.curr_id				=     vit.curr_id



		INNER JOIN tbCustomerKind											tck
		ON		tck.comp_id				= tc.comp_id
		AND		tck.ck_id				= tc.ck_id


		INNER JOIN dbo.tbSalesTerms											tst
		ON		tst.comp_id				= tct.comp_id
		AND		tst.st_id				= tct.st_id


		INNER JOIN dbo.tbDelivery											td
		ON		td.comp_id				= tct.comp_id
		AND		td.dl_id				= tct.dl_id



		INNER JOIN vwUsers4BranchFilter							vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id					= tct.bra_id
		AND vubf.[user_id]				= @user_id




WHERE	tct.comp_id		= @comp_id
AND		tsc.subcat_id	= @id2Grid
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)





AND		(@case_id IN (4,8)	AND	 tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual) AND @dateActual
OR 							tct.ct_date	 BETWEEN DATEADD(MONTH,@rank -12,@dateActual) AND DATEADD(MONTH,-12,@dateActual))





ORDER BY	ct_date








GO








CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_ITEMSUBCATEGORY_SalesOfThisMonth]
(
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	as INT,
	@user_id	AS INT

)
AS
SET NOCOUNT ON


/*
	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE @case_id	AS INT
	DECLARE @user_id	 as int


	SET     @comp_id    = 1
	SET		@lang_id	= 2
