AND		tsc.subcat_id  	= @id2Grid
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		(
		(@case_id IN (1,5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2,6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3,7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		)


ORDER BY ct_date








GO






CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_MaxChequeOwnExceeded]
(
		@comp_id	AS INT,
		@lang_id	AS INT,
		@bra_id		AS INT,
		@brag_id	AS INT,
		@dateFrom	AS DATETIME,
		@dateTo		AS DATETIME,
		@dateActual AS DATETIME,
		@id2Grid	AS INT,
		@id2Grid2	AS INT,
		@case_id	as INT,
		@user_id	AS INT

)
AS
SET NOCOUNT ON

/*
	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE @case_id	AS INT

	SET     @comp_id    = 1
	SET		@lang_id	= 2
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2009/01/01'
	SET		@dateTo     = '2009/31/12'
	SET		@dateActual = '2009/11/08'
	SET		@id2Grid	= 2
	SET		@case_id =    1
*/
SELECT	tbg.brag_id									[ID],
		tbgd.bra_id									[ID1],
		tbg.brag_desc								[Indicador],
		tc.cust_credit_own - fcgbs.cust_credit_cheque_own_used[Total]


FROM	tbBranchGroup									tbg

		INNER JOIN tbBranchGroupDetail					tbgd
		ON	tbgd.comp_id			=	tbg.comp_id
		AND tbgd.brag_id			=	tbg.brag_id

 		INNER JOIN tbCustomer							tc
		ON	tc.comp_id				=	tbg.comp_id
		AND	tc.bra_id				=	tbgd.bra_id

		CROSS APPLY dbo.fnCustomer_getBalanceStatus(1,1,tc.cust_id,@user_id,GETDATE(),-1,-1) fcgbs

where	tbg.comp_id		=	@comp_id
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)
AND		tbgd.bra_id		=   @bra_id
AND		fcgbs.cust_id	=	tc.cust_id
AND		NOT tc.cust_credit_own IS NULL
GO






CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_MaxCreditExceeded]
(
	@comp_id	 INT,
	@lang_id	 INT,
	@bra_id		 INT,
	@brag_id	 INT,
	@dateFrom	 DATETIME,
	@dateTo		 DATETIME,
	@dateActual  DATETIME,
	@id2Grid	 INT,
	@id2Grid2	 INT,
	@case_id     INT,
	@user_id	 INT

)
AS
SET NOCOUNT ON

/*
	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE @case_id    AS INT


	SET     @comp_id    = 1
	SET		@lang_id	= 2
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2009/01/01'
	SET		@dateTo     = '2009/31/12'
	SET		@dateActual = '2009/06/08'
	SET		@id2Grid	= 1
	SET     @case_id    = 5
*/
SELECT	tbg.brag_id									[ID],
		tbgd.bra_id									[ID1],
		tbg.brag_desc								[Indicador],
		(tc.cust_credit_max - fcgbs.cust_credit_cheque_own_used		+
		fcgbs.cust_credit_cheque_3rd_used		+
		fcgbs.cust_credit_balance)[Total]

FROM	tbBranchGroup									tbg

		INNER JOIN tbBranchGroupDetail					tbgd
		ON	tbgd.comp_id			=	tbg.comp_id
		AND tbgd.brag_id			=	tbg.brag_id

 		INNER JOIN tbCustomer							tc
		ON	tc.comp_id				=	tbg.comp_id
		AND	tc.bra_id				=	tbgd.bra_id

		CROSS APPLY dbo.fnCustomer_getBalanceStatus(1,1,tc.cust_id,@user_id,GETDATE(),-1,-1) fcgbs

where	tbg.comp_id		=	@comp_id
AND		(@brag_id		=	-1	or	tbgd.brag_id	= @brag_id)
AND		tbgd.bra_id		=	@bra_id
AND		not tc.cust_credit_max IS NULL



GO







CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_SALESMAN_SalesMonthDifference]
(
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	as INT,
	@rank       AS INT,
	@user_id	AS INT


)
AS
SET NOCOUNT ON

/*
DECLARE @comp_id	AS INT
DECLARE @lang_id	AS INT
DECLARE @bra_id		AS INT
DECLARE @brag_id	AS INT
DECLARE @dateFrom	AS DATETIME
DECLARE @dateTo		AS DATETIME
DECLARE @dateActual AS DATETIME
DECLARE @id2Grid	AS INT
DECLARE @id2Grid2	AS INT,
		@case_id	as INT,
		@rank       AS INT,
		@user_id	AS int


SET     @comp_id    = 1
SET		@lang_id	= 2
SET		@bra_id	    = 1
SET     @brag_id    = 2
SET		@dateFrom   = '2009/01/01'
SET		@dateTo     = '2009/31/12'
SET		@dateActual = '2009/19/11'
SET		@id2Grid	= 4
set		@case_id	= 8
SET		@rank       = 3
set		@user_id	= 1

 */


SELECT @rank = @rank * -1

SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date[Fecha],
		ts.sm_name[Vendedor],
		CASE vctfss.sd_isCredit WHEN 'False' THEN
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		ELSE
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		END											[Total],
tst.st_desc[Condicion Venta],
tck.ck_name[Tipo cliente],
td.dl_name[Transporte]

FROM	tbCommercialTransactions								tct

	INNER JOIN dbo.vwCommercialTransactions_forSales		  vctfss
	ON		vctfss.comp_id			 =  tct.comp_id
	AND		vctfss.bra_id			 =  tct.bra_id
	AND		vctfss.ct_transaction	 =  tct.ct_transaction
	AND		vctfss.sd_isReceipt		 =	'False'

	INNER JOIN tbBranchGroup								    tbg
	ON tbg.comp_id					=	tct.comp_id

	INNER JOIN tbBranchGroupDetail								tbgd
	ON		tbgd.comp_id			=   tct.comp_id
	AND		tbgd.bra_id				=   tct.bra_id

	INNER JOIN tbItemTransactions							    tit
	ON		tit.comp_id				=	 tct.comp_id
	AND		tit.bra_id				=	 tct.bra_id
	AND		tit.ct_transaction		=	 tct.ct_transaction

	INNER JOIN vwItemTransactions							     vit
	ON		vit.comp_id				=	 tit.comp_id
	AND		vit.it_transaction		=	 tit.it_transaction

	INNER JOIN  dbo.tbCustomer									 tc
	ON		tc.comp_id				=     tct.comp_id
	AND		tc.cust_id				=     tct.cust_id

    INNER JOIN tbCustomerKind									tck
	ON		tck.comp_id				= tc.comp_id
	AND		tck.ck_id				= tc.ck_id

	INNER JOIN dbo.tbSalesTerms									tst
	ON		tst.comp_id				= tct.comp_id
	AND		tst.st_id				= tct.st_id

	INNER JOIN dbo.tbDelivery									 td
	ON		td.comp_id				= tct.comp_id
	AND		td.dl_id				= tct.dl_id

	INNER JOIN tbSalesman										 ts
	ON		ts.comp_id				= tct.comp_id
	AND		ts.sm_id				= tct.sm_id

	INNER JOIN  vwUsers4BranchFilter							 vubf
	ON  vubf.comp_id				= tct.comp_id
	AND vubf.bra_id					= tct.bra_id
	AND vubf.[user_id]				= @user_id


WHERE	 tct.comp_id				= @comp_id
AND		 ts.sm_id					= @id2Grid
AND		(@brag_id					= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id = 4	AND	 tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual) AND @dateActual
OR 							tct.ct_date	 BETWEEN DATEADD(MONTH,@rank	-12,@dateActual) AND DATEADD(MONTH,-12,@dateActual))


ORDER BY	ct_date









GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Movimientos de Venta
--				del mes en curso de un Vendedor
--				para ser mostrados en la grilla
--				del panel de control.-
-- =============================================

CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_SALESMAN_SalesOfThisMonth]
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id    AS INT,
	@user_id    AS INT


AS
SET NOCOUNT ON;

/*
	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE @case_id	AS INT
	DECLARE @user_id	AS int



	SET     @comp_id    = 1
	SET		@lang_id	= 2
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2009/01/01'
	SET		@dateTo     = '2009/31/12'
	SET		@dateActual = '2009/18/08'
	SET		@id2Grid	= 4
	SET		@case_id    = 1
	SET		@user_id	= 1

	*/


SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date,
		tc.cust_name,
		CASE WHEN @case_id < 3
			THEN
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull(dbo.fnGetExchange(tct.comp_id,
									 tct.ct_total,
									 tct.curr_id_transaction,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false'),0)
				ELSE
					IsNull(dbo.fnGetExchange(tct.comp_id,
									 tct.ct_total * -1,
									 tct.curr_id_transaction,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false'),0)
				END
			WHEN @case_id = 3
			Then
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull(dbo.fnGetExchange(tct.comp_id,
										 tct.ct_total,
										 tct.curr_id_transaction,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				ELSE
					IsNull(dbo.fnGetExchange(tct.comp_id,
										 tct.ct_total * -1,
										 tct.curr_id_transaction,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				END --/ COUNT(DISTINCT MONTH(tct.ct_date))

	WHEN @case_id > 4 AND @case_id < 8
			THEN
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				ELSE
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance * -1,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				END
		END														[Total],
	    tst.st_desc,
		td.dl_name

FROM tbCommercialTransactions										tct


	INNER JOIN dbo.vwCommercialTransactions_forSalesStats			vctfss
	ON		vctfss.comp_id			= tct.comp_id
	AND		vctfss.bra_id			= tct.bra_id
	AND		vctfss.ct_transaction	= tct.ct_transaction

	INNER JOIN tbBranchGroupDetail									tbgd
	ON		tbgd.comp_id			= tct.comp_id
	AND		tbgd.bra_id				= tct.bra_id

	INNER JOIN tbBranchGroup										tbg
	ON		tbg.comp_id				= tct.comp_id
	AND		tbg.brag_id				= tbgd.brag_id

	INNER JOIN  dbo.tbCustomer										tc
	ON		tc.comp_id				= tct.comp_id
	AND		tc.cust_id				= tct.cust_id

	INNER JOIN dbo.tbSalesTerms										tst
	ON		tst.comp_id				= tct.comp_id
	AND		tst.st_id				= tct.st_id

	INNER JOIN dbo.tbDelivery										td
	ON		td.comp_id				= tct.comp_id
	AND		td.dl_id				= tct.dl_id

	INNER JOIN vwUsers4BranchFilter							vubf
	ON  vubf.comp_id				= tct.comp_id
	AND vubf.bra_id					= tct.bra_id
	AND vubf.[user_id]				= @user_id


WHERE	tct.comp_id		= @comp_id
AND		tct.sm_id		= @id2Grid
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		(
		(@case_id IN (1,5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2,6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3,7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		)

ORDER BY ct_date



GO






