										 'false')),0)
				ELSE
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance * -1,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				END
		END														[Total]



FROM tbCommercialTransactions tct

		INNER JOIN vwCommercialTransactions_forSalesStats			vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN tbBranchGroupDetail								tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup									tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN  dbo.tbCustomer									tc
		ON		tc.comp_id				= tct.comp_id
		AND		tc.cust_id				= tct.cust_id

		INNER JOIN dbo.tbSalesTerms									tst
		ON		tst.comp_id				= tct.comp_id
		AND		tst.st_id				= tct.st_id

		INNER JOIN vwUsers4BranchFilter							vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id					= tct.bra_id
		AND vubf.[user_id]				= @user_id


WHERE	tct.comp_id		= @comp_id
AND		tst.st_id	= @id2Grid
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		(
		(@case_id IN (1,5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2,6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3,7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		)


ORDER BY ct_date



GO






CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_STATE_SalesMonthDifference]
(
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	as INT,
	@rank		AS INT,
	@user_id	AS INT


)
AS
SET NOCOUNT ON

/*

DECLARE @comp_id	AS INT
DECLARE @lang_id	AS INT
DECLARE @bra_id		AS INT
DECLARE @brag_id	AS INT
DECLARE @dateFrom	AS DATETIME
DECLARE @dateTo		AS DATETIME
DECLARE @dateActual AS DATETIME
DECLARE @id2Grid	AS INT
DECLARE @id2Grid2	AS INT,
		@case_id	as INT,
		@rank       AS INT,
		@user_id	as int



SET     @comp_id    = 1
SET		@lang_id	= 2
SET		@bra_id	    = 1
SET     @brag_id    = 2
SET		@dateFrom   = '2009/04/04'
SET		@dateTo     = '2009/04/04'
SET		@dateActual = '2009/03/08'
SELECT 	@id2Grid	= 54013,
		@case_id	= 4 ,
		@rank       = 6,
		@user_id	= 1


*/

SELECT @rank = @rank * -1


SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date,
		ts.state_desc,
CASE vctfss.sd_isCredit WHEN 'False' THEN
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		ELSE
			IsNull(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 tbg.curr_id,
									 0, 0, 'false'),0)
		END											[Total],
		tst.st_desc,
		tck.ck_name,
		ts.state_id,
		td.dl_name

FROM	tbCommercialTransactions tct

	INNER JOIN dbo.vwCommercialTransactions_forSalesStats		vctfss
	ON		vctfss.comp_id			= tct.comp_id
	AND		vctfss.bra_id			= tct.bra_id
	AND		vctfss.ct_transaction	= tct.ct_transaction
	AND		vctfss.sd_isReceipt		=	'False'

	INNER JOIN tbBranchGroup								    tbg
	ON tbg.comp_id		            =	tct.comp_id


	INNER JOIN tbBranchGroupDetail								tbgd
	ON		tbgd.comp_id			= tct.comp_id
	AND		tbgd.bra_id				= tct.bra_id

	INNER JOIN tbItemTransactions							    tit
	ON		tit.comp_id				=	tct.comp_id
	AND		tit.bra_id				=	tct.bra_id
	AND		tit.ct_transaction		=	tct.ct_transaction

	INNER JOIN vwItemTransactions							     vit
	ON		vit.comp_id				=	tit.comp_id
	AND		vit.it_transaction		=	tit.it_transaction

	INNER JOIN  dbo.tbCustomer									tc
	ON		tc.comp_id				= tct.comp_id
	AND		tc.cust_id				= tct.cust_id

	INNER JOIN tbCustomerKind									tck
	ON		tck.comp_id				= tc.comp_id
	AND		tck.ck_id				= tc.ck_id

	INNER JOIN dbo.tbSalesTerms									tst
	ON		tst.comp_id				= tct.comp_id
	AND		tst.st_id				= tct.st_id

	INNER JOIN tbsysState										ts
	ON		ts.country_id			= tct.country_id
	AND		ts.state_id				= tct.state_id

	INNER JOIN dbo.tbDelivery									td
	ON		td.comp_id				= tct.comp_id
	AND		td.dl_id				= tct.dl_id

	INNER JOIN vwUsers4BranchFilter							vubf
	ON  vubf.comp_id				= tct.comp_id
	AND vubf.bra_id					= tct.bra_id
	AND vubf.[user_id]				= @user_id


WHERE	tct.comp_id		= @comp_id
AND		ts.state_id	= @id2Grid
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id = 4	AND	 tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual) AND @dateActual
OR 							tct.ct_date	 BETWEEN DATEADD(MONTH,@rank -12,@dateActual) AND DATEADD(MONTH,-12,@dateActual))


ORDER BY ct_date






GO






CREATE PROCEDURE [dbo].[spControlPanelMeasureGRID_STATE_SalesOfThisMonth]
(
	@comp_id	AS INT,
	@lang_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@id2Grid	AS INT,
	@id2Grid2	AS INT,
	@case_id	as INT,
	@user_id    AS INT

)
AS
SET NOCOUNT ON;
/*
	DECLARE @comp_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @id2Grid	AS INT
	DECLARE @id2Grid2	AS INT
	DECLARE @case_id	as INT
	DECLARE @user_id    AS INT



	SET     @comp_id    = 1
	SET		@lang_id	= 2
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2009/01/01'
	SET		@dateTo     = '2009/31/12'
	SET		@dateActual = '2009/06/08'
	SET		@id2Grid	= 54013
	SET		@case_id	= 5
	SET     @user_id    = 1


*/
SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
		tct.ct_date,
		ts.state_desc,
		CASE WHEN @case_id < 3
			THEN
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull(dbo.fnGetExchange(tct.comp_id,
									 tct.ct_total,
									 tct.curr_id_transaction,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false'),0)
				ELSE
					IsNull(dbo.fnGetExchange(tct.comp_id,
									 tct.ct_total * -1,
									 tct.curr_id_transaction,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false'),0)
				END
		WHEN @case_id = 3
			Then
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull(dbo.fnGetExchange(tct.comp_id,
										 tct.ct_total,
										 tct.curr_id_transaction,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				ELSE
					IsNull(dbo.fnGetExchange(tct.comp_id,
										 tct.ct_total * -1,
										 tct.curr_id_transaction,
										 ct_CompanyCurrency,
										 ct_CompanyCurrency,
										 ct_Branch2CompanyCurrencyExchange,
										 'false'),0)
				END --/ COUNT(DISTINCT MONTH(tct.ct_date))
					WHEN @case_id > 4 AND @case_id < 8
			THEN
				CASE vctfss.sd_isCredit WHEN 'False' THEN
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				ELSE
					IsNull((dbo.fnGetExchange(tct.comp_id,
										 tct.ct_ABalance * -1,
										 tct.ct_ACurrency,
										 tbg.curr_id,
										 0,
										 0,
										 'false')),0)
				END
		END														[Total],

		tst.st_desc,
		tck.ck_name,
		ts.state_id,
		td.dl_name

FROM	tbCommercialTransactions tct

		INNER JOIN dbo.vwCommercialTransactions_forSalesStats	vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN  dbo.tbCustomer								tc
		ON		tc.comp_id				= tct.comp_id
		AND		tc.cust_id				= tct.cust_id

		INNER JOIN tbCustomerKind								tck
		ON		tck.comp_id				= tc.comp_id
		AND		tck.ck_id				= tc.ck_id

		INNER JOIN dbo.tbSalesTerms								tst
		ON		tst.comp_id				= tct.comp_id
		AND		tst.st_id				= tct.st_id

		INNER JOIN tbsysState									ts
		ON		ts.country_id			= tct.country_id
		AND		ts.state_id				= tct.state_id

		INNER JOIN dbo.tbDelivery								td
		ON		td.comp_id				= tct.comp_id
		AND		td.dl_id				= tct.dl_id

		INNER JOIN vwUsers4BranchFilter							vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id					= tct.bra_id
		AND vubf.[user_id]				= @user_id


WHERE	tct.comp_id		= @comp_id
AND		tct.state_id	= @id2Grid
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		(
		(@case_id  IN (1,5)	AND		tct.ct_date		BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id  IN (2,6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id  IN (3,7) AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		)


ORDER BY ct_date







GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================



CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_BRANCH_SalesMonthDifference]

	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@rank       INT,
	@user_id    int

AS
SET NOCOUNT ON

/*

	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id	AS INT
	DECLARE @rank       AS INT
	DECLARE @user_id    AS INT



	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '9999/31/12'
	SET		@dateActual = '2009/26/10'
	SET		@scpm_id	= 1000000
	SET		@case_id    = 4
	SET     @rank       = 3
	SET     @user_id    = 1



DROP TABLE #tmp

*/

SELECT @rank = @rank * -1

SELECT	tct.bra_id												[Id],
		tct.bra_id												[Id1],
		tb.bra_desc												[Indicator],

		sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			ELSE
				0
			END	,0))											[TotalA],

		sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				0
			ELSE
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			END	,0))											[TotalB],

		@scpm_id												[scpm_id]

INTO	#tmp

FROM tbCommercialTransactions								tct

	INNER JOIN dbo.vwCommercialTransactions_forSales	    vctfss
	ON		vctfss.comp_id			= tct.comp_id
	AND		vctfss.bra_id			= tct.bra_id
	AND		vctfss.ct_transaction	= tct.ct_transaction
	AND		vctfss.sd_isReceipt		= 'False'

	INNER JOIN tbBranchGroup								tbg
	ON		tbg.comp_id				=	tct.comp_id
	--AND		tbg.brag_id				=	tbgd.brag_id

	INNER JOIN tbBranchGroupDetail							tbgd
	ON		tbgd.comp_id			=	tct.comp_id
	AND		tbgd.brag_id			=	tbg.brag_id
	AND		tbgd.bra_id				=	tct.bra_id

	INNER JOIN tbItemTransactions							tit
	ON		tit.comp_id				=	tct.comp_id
	AND		tit.bra_id				=	tct.bra_id
	AND		tit.ct_transaction		=	tct.ct_transaction

	INNER JOIN vwItemTransactions							vit
	ON		vit.comp_id				=	tit.comp_id
	AND		vit.it_transaction		=	tit.it_transaction

	INNER JOIN	tbBranch									tb
	ON		tb.comp_id				= tct.comp_id
	AND		tb.bra_id				= tct.bra_id

	INNER JOIN vwUsers4BranchFilter							vubf
	ON vubf.comp_id					= tct.comp_id
	AND vubf.bra_id					= tct.bra_id
	AND vubf.[user_id]				= @user_id



WHERE	tct.comp_id		= @comp_id
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8)	AND	 tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual) AND @dateActual
OR 		tct.ct_date	 BETWEEN DATEADD(MONTH,@rank-12,@dateActual) AND DATEADD(MONTH,-12,@dateActual))


GROUP BY 	tct.bra_id,
			tb.bra_desc

--SELECT * FROM #tmp


if @case_id = 4
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator], SUM([TotalA]) -  SUM([TotalB]) ,[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]


IF @case_id = 8
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator],
	CASE WHEN SUM([TotalB]) = 0 THEN 0
		ELSE ((SUM([TotalA])/dbo.fnNoZDiv(SUM([TotalB])))-1)*100
	END,
	[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]







GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================


CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_BRANCH_SalesOfThisMonth]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@user_id    int

AS
SET NOCOUNT ON

/*

	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id	AS INT
	DECLARE @user_id    AS INT



	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '2010/31/12'
	SET		@dateActual = '2009/20/11'
	SET		@scpm_id	= 1000000
	SET		@case_id    = 5
	SET     @user_id    = 1

*/

INSERT  #tmpControlPanelMeasures

	SELECT		isnull(tct.bra_id,-1)										[Id],
				tct.bra_id													[Id1],
				isnull(tb.bra_desc,125)										[Indicator],
	CASE

		--ventas totales entre fechas / último mes
		WHEN @case_id < 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

		--ventas totales últimos 6 meses
		WHEN @case_id = 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))
									--/ COUNT(DISTINCT MONTH(tct.ct_date))

		--saldos de ventas
		WHEN @case_id > 4 AND @case_id < 8	THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_ABalance,tct.ct_ACurrency,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

	END																		[Total],
	@scpm_id																[scpm_id]


FROM tbCommercialTransactions						tct

	INNER JOIN dbo.vwCommercialTransactions_forSales			vctfss
	ON		vctfss.comp_id			= tct.comp_id
	AND		vctfss.bra_id			= tct.bra_id
	AND		vctfss.ct_transaction	= tct.ct_transaction

	INNER JOIN tbBranchGroupDetail								tbgd
	ON		tbgd.comp_id			= tct.comp_id
	AND		tbgd.bra_id				= tct.bra_id

	INNER JOIN tbBranchGroup									tbg
	ON		tbg.comp_id				= tct.comp_id
	AND		tbg.brag_id				= tbgd.brag_id

	INNER JOIN	tbBranch										tb
	ON		tb.comp_id				= tct.comp_id
	AND		tb.bra_id				= tct.bra_id

	INNER JOIN vwUsers4BranchFilter vubf
	ON vubf.comp_id = tct.comp_id
	AND vubf.bra_id = tct.bra_id
	AND vubf.[user_id] = @user_id


WHERE	tct.comp_id = @comp_id
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		(((
		(@case_id IN (1)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual)))
		AND		vctfss.sd_isReceipt		= 'False'
		) OR (
		(@case_id IN (5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		))


GROUP BY 	tct.bra_id,
			tb.bra_desc
GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================




CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_BRAND_SalesMonthDifference]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	AS INT,
	@case_id	AS INT,
	@rank       AS INT,
	@user_id    as int
AS
SET NOCOUNT ON



/*
DECLARE @comp_id		INT,
		@bra_id			INT,
		@brag_id		INT,
		@dateFrom		DATETIME,
		@dateTo			DATETIME,
		@dateActual		DATETIME,
		@scpm_id		INT,
		@case_id		INT,
		@rank			INT,
		@user_id        INT


SELECT  @comp_id		= 1,
		@bra_id			= 1,
		@brag_id		= -1,
		@dateFrom		= '2000/01/01',
		@dateTo			= '9999/31/12',
		@dateActual		= '2009/26/10',
		@scpm_id		= 11004003,
		@case_id		= 4,
		@rank			= 3,
		@user_id        = 1

DROP TABLE #tmp
*/


SELECT @rank = @rank * -1

SELECT	tb.brand_id												[Id],
		tct.bra_id												[Id1],
		tb.brand_desc											[Indicator],

		sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			ELSE
				0
			END	,0))											[TotalA],

		sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				0
			ELSE
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			END	,0))											[TotalB],

		@scpm_id												[scpm_id]

INTO	#tmp

FROM	tbCommercialTransactions								tct

		INNER JOIN dbo.vwCommercialTransactions_forSales		vctfss
		ON		vctfss.comp_id			=	tct.comp_id
		AND		vctfss.bra_id			=	tct.bra_id
		AND		vctfss.ct_transaction	=	tct.ct_transaction
		AND		vctfss.sd_isReceipt		=	'False'

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				=	tct.comp_id
		--AND		tbg.brag_id				=	tbgd.brag_id

		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			=	tct.comp_id
		AND		tbgd.brag_id			=	tbg.brag_id
		AND		tbgd.bra_id				=	tct.bra_id

		INNER JOIN tbItemTransactions							tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction

		INNER JOIN vwItemTransactions							vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction

		INNER JOIN	tbItem										ti
		ON		ti.comp_id				=	tit.comp_id
		AND		ti.item_id				=	tit.item_id

		INNER JOIN  tbBrand										 tb
		ON		tb.comp_id				=	tct.comp_id
		AND		tb.brand_id				=	ti.brand_id

		INNER JOIN vwUsers4BranchFilter							vubf
		ON		vubf.comp_id			=	tct.comp_id
		AND		vubf.bra_id				=	tct.bra_id
		AND		vubf.[user_id]			=	@user_id


WHERE	tct.comp_id		= @comp_id
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8)	AND
			(tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual)		AND @dateActual	OR
			tct.ct_date	 BETWEEN DATEADD(MONTH,@rank-12,@dateActual)	AND DATEADD(MONTH,-12,@dateActual)))

GROUP BY 	tb.brand_id,
			tct.bra_id,
			tb.brand_desc

--SELECT * FROM #tmp

if @case_id = 4
	INSERT #tmpControlPanelMeasures
		SELECT	[Id],[Id1],[Indicator],
				SUM([TotalA])-SUM([TotalB]),
				[scpm_id]
		FROM	#tmp
		GROUP BY [Id],[Id1],[Indicator],[scpm_id]


IF @case_id = 8
	INSERT #tmpControlPanelMeasures
		SELECT	[Id],[Id1],[Indicator],
				CASE WHEN SUM([TotalB]) = 0 THEN 0
					ELSE ((SUM([TotalA])/dbo.fnNoZDiv(SUM([TotalB])))-1)*100
				END,
				[scpm_id]
		FROM	#tmp
		GROUP BY [Id],[Id1],[Indicator],[scpm_id]
GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================


CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_BRAND_SalesOfThisMonth]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@user_id    INT

AS
SET NOCOUNT ON

/*


	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id	AS INT
	DECLARE @user_id    AS INT


	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '2009/31/12'
	SET		@dateActual = '2009/04/09'
	SET		@scpm_id	= 1000000
	SET		@case_id    = 3
	SET     @user_id    = 1


*/

INSERT  #tmpControlPanelMeasures

SELECT	isnull(tb.brand_id	,-1)									[Id],
		tct.bra_id													[Id1],
		isnull(tb.brand_desc,125)									[Indicator],

		/*
		CASE WHEN @case_id < 3
		THEN
			CASE vctfss.sd_isCredit WHEN 'False' THEN
				IsNull(sum(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false')),0)
			ELSE
				IsNull(sum(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false')),0)

			END
		WHEN @case_id = 3
		Then
			CASE vctfss.sd_isCredit WHEN 'False' THEN
				IsNull(sum(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal,
									 vit.curr_id,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false')),0)
			ELSE
				IsNull(sum(dbo.fnGetExchange(vit.comp_id,
									 vit.vw_itemTotal * -1,
									 vit.curr_id,
									 ct_CompanyCurrency,
									 ct_CompanyCurrency,
									 ct_Branch2CompanyCurrencyExchange,
									 'false')),0)

			END / COUNT(DISTINCT MONTH(tct.ct_date)) */

		/*WHEN @case_id > 4 AND @case_id < 8
		THEN
			CASE vctfss.sd_isCredit WHEN 'False' THEN
				IsNull(sum(dbo.fnGetExchange(tct.comp_id,
									 tct.ct_ABalance,
									 tct.ct_ACurrency,
									 tbg.curr_id,
									 0,
									 0,
									 'false')),0)
			ELSE
				IsNull(sum(dbo.fnGetExchange(tct.comp_id,
									 tct.ct_ABalance * -1,
									 tct.ct_ACurrency,
									 tbg.curr_id,
									 0,
									 0,
									 'false')),0)
			END */



		CASE

		--ventas totales entre fechas / último mes
		WHEN @case_id < 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

		--ventas totales últimos 6 meses
		WHEN @case_id = 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))
									--/ COUNT(DISTINCT MONTH(tct.ct_date))

		END							    [Total],
		@scpm_id					    [scpm_id]

FROM	tbCommercialTransactions								tct

		INNER JOIN dbo.vwCommercialTransactions_forSalesStats	vctfss
		ON		vctfss.comp_id			=	tct.comp_id
		AND		vctfss.bra_id			=	tct.bra_id
		AND		vctfss.ct_transaction	=	tct.ct_transaction

		INNER JOIN tbItemTransactions							tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction


		INNER JOIN vwItemTransactions							vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction


		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			=	tct.comp_id
		AND		tbgd.bra_id				=	tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

	   	INNER JOIN tbItem										ti
		ON		ti.comp_id				=	tit.comp_id
		AND		ti.item_id				=	tit.item_id

		INNER JOIN tbBrand										tb
		ON	tb.comp_id					= tct.comp_id
		AND tb.brand_id					= ti.brand_id

		INNER JOIN vwUsers4BranchFilter							vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id					= tct.bra_id
		AND vubf.[user_id]				= @user_id





WHERE	tct.comp_id = @comp_id

AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		((
		(@case_id IN (1)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual)))
		AND		vctfss.sd_isReceipt		= 'False'
		)


GROUP BY 	tb.brand_id,
			tct.bra_id,
			tb.brand_desc





GO





