--				del mes en curso por Vendedor
-- =============================================


CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_COUNTRY_SalesMonthDifference]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@rank       INT,
	@user_id    int


AS
SET NOCOUNT ON

/*


	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id    AS INT
	DECLARE @rank       AS INT
	DECLARE @user_id    AS INT



	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '9999/31/12'
	SET		@dateActual = '2009/26/10'
	SET		@scpm_id	= 1000000
	SET     @case_id	= 4
	SET     @rank       = 3
	SET     @user_id    = 1




DROP TABLE #tmp

*/

SELECT @rank = @rank * -1

SELECT	tc.country_id											[Id],
		tct.bra_id												[Id1],
		tc2.country_desc										[Indicator],


		sum(isnull(
		CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
			dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
		ELSE
			0
		END	,0))											[TotalA],

		sum(isnull(
		CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
			0
		ELSE
			dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
		END	,0))											[TotalB],


		@scpm_id												[scpm_id]

INTO	#tmp

FROM	tbCommercialTransactions									tct

		INNER JOIN dbo.vwCommercialTransactions_forSales			vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction
		AND		vctfss.sd_isReceipt		= 'False'

		INNER JOIN tbBranchGroup									tbg
		ON		tbg.comp_id				=	tct.comp_id
		--AND	tbg.brag_id				=	tbgd.brag_id

		INNER JOIN tbBranchGroupDetail								tbgd
		ON		tbgd.comp_id			=	tct.comp_id
		AND		tbgd.brag_id			=	tbg.brag_id
		AND		tbgd.bra_id				=	tct.bra_id

		INNER JOIN tbItemTransactions								tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction

		INNER JOIN vwItemTransactions								vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction

		INNER JOIN tbCustomer										tc
		ON		tc.cust_id				= tct.cust_id
		AND		tc.comp_id				= tct.comp_id

		INNER JOIN tbsysCountry										tc2
		ON		tc2.country_id			= tc.country_id

		INNER JOIN vwUsers4BranchFilter								vubf
		ON		vubf.comp_id            = tct.comp_id
		AND		vubf.bra_id             = tct.bra_id
		AND		vubf.[user_id]          = @user_id



WHERE	tct.comp_id		= @comp_id
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8)	AND	 tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual) AND @dateActual
OR 		tct.ct_date	 BETWEEN DATEADD(MONTH,@rank-12,@dateActual) AND DATEADD(MONTH,-12,@dateActual))

GROUP BY	tc.country_id,
			tct.bra_id,
			tc2.country_desc

--SELECT * FROM #tmp

if @case_id = 4
    INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator], SUM([TotalA]) -  SUM([TotalB]) ,[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]


IF @case_id = 8
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator],
	CASE WHEN SUM([TotalB]) = 0 THEN 0
		ELSE ((SUM([TotalA])/dbo.fnNoZDiv(SUM([TotalB])))-1)*100
	END,
	[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]








GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================



CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_COUNTRY_SalesOfThisMonth]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@user_id    INT

AS
SET NOCOUNT ON
/*

	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id    AS INT
	DECLARE @user_id    AS INT



	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '2010/31/12'
	SET		@dateActual = '2009/04/09'
	SET		@scpm_id	= 1000000
	SET     @case_id	= 5
	SET     @user_id    = 1


*/

INSERT  #tmpControlPanelMeasures

SELECT	isnull(tc.country_id,-1)										[Id],
		tct.bra_id														[Id1],
		isnull(tc2.country_desc,125)									[Indicator],

		CASE
		--ventas totales entre fechas / último mes
		WHEN @case_id < 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

		--ventas totales últimos 6 meses
		WHEN @case_id = 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))
									--/ COUNT(DISTINCT MONTH(tct.ct_date))

		--saldos de ventas
		WHEN @case_id > 4 AND @case_id < 8	THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_ABalance,tct.ct_ACurrency,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

		END														[Total],
		@scpm_id												[scpm_id]



FROM	tbCommercialTransactions											tct

		INNER JOIN dbo.vwCommercialTransactions_forSales					vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN tbBranchGroupDetail										tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup											tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN tbCustomer												 tc
		ON	tc.cust_id					= tct.cust_id
		AND tc.comp_id					= tct.comp_id

		INNER JOIN tbsysCountry												tc2
		ON	tc2.country_id				= tc.country_id

		INNER JOIN vwUsers4BranchFilter										vubf
		ON vubf.comp_id                 = tct.comp_id
		AND vubf.bra_id                 = tct.bra_id
		AND vubf.[user_id]              = @user_id




WHERE	tct.comp_id = @comp_id
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		(((
		(@case_id IN (1)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual)))
		AND		vctfss.sd_isReceipt		= 'False'
		) OR (
		(@case_id IN (5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		))

GROUP BY	tc.country_id,
			tct.bra_id,
			tc2.country_desc






GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================


CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_CUSTOMERKIND_SalesMonthDifference]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@rank       INT,
	@user_id    INT


AS
SET NOCOUNT ON;


/*
	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id	AS INT
	DECLARE @rank       AS INT
	DECLARE @user_id    AS INT


	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '2010/31/01'
	SET		@dateActual = '2009/04/09'
	SET		@scpm_id	= 1000000
	SET		@case_id    = 8
	SET     @rank       = 4
	SET     @user_id    = 1




DROP TABLE #tmp

*/



SELECT @rank = @rank * -1

SELECT	tck.ck_id												[Id],
		tct.bra_id												[Id1],
		tck.ck_name											[Indicator],

		sum(isnull(
		CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
			dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
		ELSE
			0
		END	,0))											[TotalA],

		sum(isnull(
		CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
			0
		ELSE
			dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
		END	,0))											[TotalB],



		@scpm_id												[scpm_id]

INTO	#tmp

FROM tbCommercialTransactions						tct

	INNER JOIN dbo.vwCommercialTransactions_forSales			vctfss
	ON		vctfss.comp_id			= tct.comp_id
	AND		vctfss.bra_id			= tct.bra_id
	AND		vctfss.ct_transaction	= tct.ct_transaction
	AND		vctfss.sd_isReceipt		= 'False'

	INNER JOIN tbBranchGroup								tbg
	ON		tbg.comp_id				=	tct.comp_id
	--AND		tbg.brag_id			=	tbgd.brag_id

	INNER JOIN tbBranchGroupDetail							tbgd
	ON		tbgd.comp_id			=	tct.comp_id
	AND		tbgd.brag_id			=	tbg.brag_id
	AND		tbgd.bra_id				=	tct.bra_id

	INNER JOIN tbItemTransactions							tit
	ON		tit.comp_id				=	tct.comp_id
	AND		tit.bra_id				=	tct.bra_id
	AND		tit.ct_transaction		=	tct.ct_transaction

	INNER JOIN vwItemTransactions							vit
	ON		vit.comp_id				=	tit.comp_id
	AND		vit.it_transaction		=	tit.it_transaction

	INNER JOIN tbCustomer										tc
	ON tc.cust_id					= tct.cust_id
	AND tc.comp_id					= tct.comp_id

	INNER JOIN tbCustomerKind									tck
	ON tck.comp_id					= tc.comp_id
	AND tck.ck_id					= tc.ck_id

	INNER JOIN vwUsers4BranchFilter								vubf
	ON	vubf.comp_id				= tct.comp_id
	AND vubf.bra_id                 = tct.bra_id
	AND vubf.[user_id]              = @user_id



WHERE	tct.comp_id		= @comp_id
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8)	AND	 tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual) AND @dateActual
OR 		tct.ct_date	 BETWEEN DATEADD(MONTH,@rank -12,@dateActual) AND DATEADD(MONTH,-12,@dateActual))


GROUP BY     tck.ck_id,
			 tck.ck_name,
			 tct.bra_id

--SELECT * FROM #tmp

if @case_id = 4
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator], SUM([TotalA]) -  SUM([TotalB]) ,[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]


IF @case_id = 8
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator],
	CASE WHEN SUM([TotalB]) = 0 THEN 0
		ELSE ((SUM([TotalA])/dbo.fnNoZDiv(SUM([TotalB])))-1)*100
	END,
	[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]









GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================


CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_CUSTOMERKIND_SalesOfThisMonth]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@user_id    INT

AS
	SET NOCOUNT ON;

/*
	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id	AS INT
	DECLARE @user_id    AS INT



	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2009/01/01'
	SET		@dateTo     = '2009/31/01'
	SET		@dateActual = '2009/05/08'
	SET		@scpm_id	= 1000000
	SET		@case_id	= 7
	SET     @user_id    = 1



*/

INSERT  #tmpControlPanelMeasures

	SELECT	isnull(tck.ck_id,-1)									[Id],
			tct.bra_id												[Id1],
			isnull(tck.ck_name,125)									[Indicator],


	CASE
		--ventas totales entre fechas / último mes
		WHEN @case_id < 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

		--ventas totales últimos 6 meses
		WHEN @case_id = 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))
									--/ COUNT(DISTINCT MONTH(tct.ct_date))

		--saldos de ventas
		WHEN @case_id > 4 AND @case_id < 8	THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_ABalance,tct.ct_ACurrency,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

	END														  [Total],
	@scpm_id												  [scpm_id]

FROM tbCommercialTransactions										tct

	INNER JOIN dbo.vwCommercialTransactions_forSales				vctfss
	ON		vctfss.comp_id				= tct.comp_id
	AND		vctfss.bra_id				= tct.bra_id
	AND		vctfss.ct_transaction		= tct.ct_transaction

	INNER JOIN tbBranchGroupDetail									tbgd
	ON		tbgd.comp_id				= tct.comp_id
	AND		tbgd.bra_id					= tct.bra_id

	INNER JOIN tbBranchGroup										tbg
	ON		tbg.comp_id					= tct.comp_id
	AND		tbg.brag_id					= tbgd.brag_id

	INNER JOIN tbCustomer											tc
	ON tc.cust_id						= tct.cust_id
	AND tc.comp_id						= tct.comp_id

	INNER JOIN tbCustomerKind										tck
	ON tck.comp_id						= tc.comp_id
	AND tck.ck_id						= tc.ck_id

	INNER JOIN vwUsers4BranchFilter									vubf
	ON vubf.comp_id                     = tct.comp_id
	AND vubf.bra_id                     = tct.bra_id
	AND vubf.[user_id]                  = @user_id



WHERE	tct.comp_id						= @comp_id
AND		(@brag_id						= -1	or	tbgd.brag_id	= @brag_id)

AND		(((
		(@case_id IN (1)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual)))
		AND		vctfss.sd_isReceipt		= 'False'
		) OR (
		(@case_id IN (5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		))

GROUP BY     tck.ck_id,
			 tck.ck_name,
			 tct.bra_id






GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================


CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_CUSTOMERSALESECTOR_SalesMonthDifference]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@rank       INT,
	@user_id    INT



AS
SET NOCOUNT ON;

/*

	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id	AS INT
	DECLARE @rank       AS INT
	DECLARE @user_id    AS INT



	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '9999/31/01'
	SET		@dateActual = '2009/26/10'
	SET		@scpm_id	= 1000000
	SET		@case_id	= 4
	SET     @rank		= 3
	SET     @user_id    = 1



DROP TABLE #tmp

*/

SELECT @rank = @rank * -1

SELECT	tss.ss_id												[Id],
		tct.bra_id												[Id1],
		tss.ss_desc												[Indicator],


		sum(isnull(
		CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
			dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
		ELSE
			0
		END	,0))											[TotalA],

		sum(isnull(
		CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
			0
		ELSE
			dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
		END	,0))											[TotalB],



		@scpm_id												[scpm_id]

INTO	#tmp

FROM tbCommercialTransactions										tct

	INNER JOIN dbo.vwCommercialTransactions_forSales				vctfss
	ON		vctfss.comp_id			= tct.comp_id
	AND		vctfss.bra_id			= tct.bra_id
	AND		vctfss.ct_transaction	= tct.ct_transaction
	AND		vctfss.sd_isReceipt		= 'False'

	INNER JOIN tbBranchGroup										tbg
	ON		tbg.comp_id				=	tct.comp_id

	INNER JOIN tbBranchGroupDetail									tbgd
	ON		tbgd.comp_id			=	tct.comp_id
	AND		tbgd.brag_id			=	tbg.brag_id
	AND		tbgd.bra_id				=	tct.bra_id

	INNER JOIN tbItemTransactions									tit
	ON		tit.comp_id				=	tct.comp_id
	AND		tit.bra_id				=	tct.bra_id
	AND		tit.ct_transaction		=	tct.ct_transaction

	INNER JOIN vwItemTransactions									vit
	ON		vit.comp_id				=	tit.comp_id
	AND		vit.it_transaction		=	tit.it_transaction

	INNER JOIN tbCustomer											tc
	ON tc.cust_id					= tct.cust_id
	AND tc.comp_id					= tct.comp_id

	INNER JOIN tbSaleSector											tss
	ON  tss.comp_id					= tc.comp_id
	AND	tss.ss_id					= tc.ss_id

	INNER JOIN vwUsers4BranchFilter									vubf
	ON vubf.comp_id                =  tct.comp_id
	AND vubf.bra_id                =  tct.bra_id
	AND vubf.[user_id]             =  @user_id




WHERE	tct.comp_id		= @comp_id
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8)	AND	 tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual) AND @dateActual
OR 		tct.ct_date	 BETWEEN DATEADD(MONTH,@rank -12,@dateActual) AND DATEADD(MONTH,-12,@dateActual))


GROUP BY     tss.ss_id,
			 tss.ss_desc,
			 tct.bra_id

--SELECT * FROM #tmp

if @case_id = 4
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator], SUM([TotalA]) -  SUM([TotalB]) ,[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]


IF @case_id = 8
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator],
	CASE WHEN SUM([TotalB]) = 0 THEN 0
		ELSE ((SUM([TotalA])/dbo.fnNoZDiv(SUM([TotalB])))-1)*100
	END,
	[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]








GO





