CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_DELIVERY_SalesMonthDifference]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@rank       INT,
	@user_id    int


AS
SET NOCOUNT ON

/*

	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id	AS INT
	declare @rank       AS INT
	DECLARE @user_id    AS INT



	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '9999/31/12'
	SET		@dateActual = '2009/26/10'
	SET		@scpm_id	= 1000000
	SET		@case_id	= 4
	SET     @rank       = 3
	SET     @user_id	= 1



DROP TABLE #tmp

*/


SELECT @rank = @rank * -1

SELECT	td.dl_id												[Id],
		tct.bra_id												[Id1],
		td.dl_name												[Indicator],


		sum(isnull(
		CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
			dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
		ELSE
			0
		END	,0))											[TotalA],

		sum(isnull(
		CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
			0
		ELSE
			dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
		END	,0))											[TotalB],


		@scpm_id											[scpm_id]

INTO	#tmp

FROM	tbCommercialTransactions							tct

		INNER JOIN dbo.vwCommercialTransactions_forSales			vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction
		AND		vctfss.sd_isReceipt		= 'False'

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				=	tct.comp_id

		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			=	tct.comp_id
		AND		tbgd.brag_id			=	tbg.brag_id
		AND		tbgd.bra_id				=	tct.bra_id

		INNER JOIN tbItemTransactions							tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction

		INNER JOIN vwItemTransactions							vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction

		INNER JOIN  tbDelivery										td
		ON		td.dl_id				= tct.dl_id
		AND		td.comp_id				= tct.comp_id

		INNER JOIN vwUsers4BranchFilter									vubf
		ON		vubf.comp_id			=  tct.comp_id
		AND		vubf.bra_id				=  tct.bra_id
		AND		vubf.[user_id]			=  @user_id


WHERE	tct.comp_id		= @comp_id
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8)	AND	 tct.ct_date BETWEEN DATEADD(MONTH,@rank,@dateActual) AND @dateActual
OR 		tct.ct_date	 BETWEEN DATEADD(MONTH,@rank -12,@dateActual) AND DATEADD(MONTH,-12,@dateActual))


GROUP BY    td.dl_id,
			td.dl_name,
			tct.bra_id

--SELECT * FROM #tmp

if @case_id = 4
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator], SUM([TotalA]) -  SUM([TotalB]) ,[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]


IF @case_id = 8
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator],
	CASE WHEN SUM([TotalB]) = 0 THEN 0
		ELSE ((SUM([TotalA])/dbo.fnNoZDiv(SUM([TotalB])))-1)*100
	END,
	[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]





GO





