		(@case_id IN (5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		))

GROUP BY 	tc.cat_id,
			tct.bra_id,
			tc.cat_desc






GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================


CREATE	PROCEDURE [dbo].[spControlPanelMeasureTOTAL_ITEMSUBCATEGORY_SalesMonthDifference]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@rank       INT,
	@user_id	INT


AS
SET NOCOUNT ON


/*
DECLARE @comp_id	AS INT
DECLARE @bra_id		AS INT
DECLARE @brag_id	AS INT
DECLARE @dateFrom	AS DATETIME
DECLARE @dateTo		AS DATETIME
DECLARE @dateActual AS DATETIME
DECLARE @scpm_id	AS INT
DECLARE @case_id	AS INT
DECLARE @rank       AS INT
DECLARE @user_id	AS INT


SET     @comp_id    = 1
SET		@bra_id	    = 1
SET     @brag_id    = 2
SET		@dateFrom   = '2009/01/01'
SET		@dateTo     = '2009/31/12'
SET		@dateActual = '2009/26/10'
SET		@scpm_id	= 1000000
SET		@case_id	= 4
SET		@rank		= 6
SET     @user_id	= 1



DROP TABLE #tmp
*/

SELECT @rank = @rank * -1


SELECT	tsc.subcat_id											[Id],
		tct.bra_id												[Id1],
		tsc.subcat_desc											[Indicator],
	sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			ELSE
				0
			END	,0))											[TotalA],

		sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				0
			ELSE
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			END	,0))											[TotalB],

		@scpm_id												[scpm_id]

INTO	#tmp

FROM	tbCommercialTransactions 								tct

		INNER JOIN dbo.vwCommercialTransactions_forSalesStats	vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction
		AND		vctfss.sd_isReceipt		=	'False'

		INNER JOIN tbItemTransactions							tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction

		INNER JOIN vwItemTransactions							vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction

		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				= tct.comp_id
		--AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN tbItem										ti
		ON		ti.comp_id				= vctfss.comp_id
		AND		ti.bra_id				= vctfss.bra_id


		INNER JOIN tbSubCategory								tsc
		ON		tsc.comp_id				= vctfss.comp_id
		AND		tsc.bra_id				= vctfss.bra_id

		inner join vwUsers4BranchFilter							vubf
		ON  vubf.comp_id    =			tct.comp_id
		AND vubf.bra_id     =			tct.bra_id
		AND vubf.[user_id]  =			@user_id



WHERE	tct.comp_id		= @comp_id
AND		not tct.sm_id	is NULL
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8)	AND	tct.ct_date BETWEEN DATEADD(MONTH,@rank		,@dateActual)	AND @dateActual
						OR 	tct.ct_date	BETWEEN DATEADD(MONTH,@rank - 12	,@dateActual)	AND DATEADD(MONTH,-12,@dateActual))


GROUP BY	tsc.subcat_id,
			tct.bra_id,
			tsc.subcat_desc


--SELECT * FROM #tmp



if @case_id = 4
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator], SUM([TotalA]) -  SUM([TotalB]) ,[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]


IF @case_id = 8
	iNSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator],
	CASE WHEN SUM([TotalB]) = 0 THEN 0
		ELSE ((SUM([TotalA])/dbo.fnNoZDiv(SUM([TotalB])))-1)*100
	END,
	[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]


GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================


CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_ITEMSUBCATEGORY_SalesOfThisMonth]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@user_id	INT

AS
SET NOCOUNT ON

/*


	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id	AS INT
	DECLARE @user_id	AS INT


	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '2010/31/12'
	SET		@dateActual = '2009/04/09'
	SET		@scpm_id	= 1000000
	SET		@case_id =    1
	SET     @user_id =	  1

*/

INSERT  #tmpControlPanelMeasures

SELECT	isnull(tsc.subcat_id,-1)												[Id],
		tct.bra_id												[Id1],
		isnull(tsc.subcat_desc,125)											[Indicator],

CASE
		--ventas totales entre fechas / último mes
		WHEN @case_id < 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

		--ventas totales últimos 6 meses
		WHEN @case_id = 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))
									--/ COUNT(DISTINCT MONTH(tct.ct_date))



		END														[Total],
		@scpm_id												[scpm_id]


	FROM tbCommercialTransactions								tct

		INNER JOIN dbo.vwCommercialTransactions_forSales     	vctfss
		ON		vctfss.comp_id			=	tct.comp_id
		AND		vctfss.bra_id			=	tct.bra_id
		AND		vctfss.ct_transaction	=	tct.ct_transaction

		INNER JOIN tbItemTransactions							tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction

		INNER JOIN vwItemTransactions							vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction

		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			=	tct.comp_id
		AND		tbgd.bra_id				=	tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN	tbItem										ti
		ON		ti.comp_id				=	tit.comp_id
		AND		ti.item_id				=	tit.item_id

		INNER JOIN tbSubCategory								tsc
		ON	tsc.comp_id					=	tct.comp_id
		AND tsc.cat_id					=   ti.cat_id
		AND tsc.subcat_id				=	ti.subcat_id

		inner join vwUsers4BranchFilter vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id					= tct.bra_id
		AND vubf.[user_id]				= @user_id



WHERE	tct.comp_id = @comp_id

AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND	(((
		(@case_id IN (1)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual)))
		AND		vctfss.sd_isReceipt		= 'False'

		) OR (
		(@case_id IN (5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		))





GROUP BY 	tsc.subcat_id,
			tct.bra_id,
			tsc.subcat_desc









GO






CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_MaxChequeOwnExceeded]
(
		@comp_id		INT,
		@bra_id			INT,
		@brag_id		INT,
		@dateFrom		DATETIME,
		@dateTo			DATETIME,
		@dateActual		DATETIME,
		@scpm_id		INT,
		@case_id		INT,
		@user_id		INT

)
AS
SET NOCOUNT ON

set dateformat 'ymd'

/*
DECLARE @comp_id		INT,
		@bra_id			INT,
		@brag_id		INT,
		@dateFrom		DATETIME,
		@dateTo			DATETIME,
		@dateActual		DATETIME,
		@scpm_id		INT,
		@case_id		INT

	SET @comp_id        = 1
	SET @bra_id			= 1
	SET	@brag_id	    = -1
	SET	@dateFrom	    = '2000/01/01'
	SET	@dateTo			= '2009/31/12'
	SET	@dateActual		= '2009/10/08'
	SET	@scpm_id		= 14002000
	SET	@case_id		= 1
*/
INSERT  #tmpControlPanelMeasures

SELECT	tbg.brag_id									[ID],
		tbgd.bra_id									[ID1],
		tbg.brag_desc								[Indicador],
		sum(tc.cust_credit_own - fcgbs.cust_credit_cheque_own_used)[Total],
		@scpm_id									[scpm_id]

FROM	tbBranchGroup									tbg

		INNER JOIN tbBranchGroupDetail					tbgd
		ON	tbgd.comp_id			=	tbg.comp_id
		AND tbgd.brag_id			=	tbg.brag_id

 		INNER JOIN tbCustomer							tc
		ON	tc.comp_id				=	tbg.comp_id
		AND	tc.bra_id				=	tbgd.bra_id

		CROSS APPLY dbo.fnCustomer_getBalanceStatus(1,1,tc.cust_id,@user_id,GETDATE(),-1,-1) fcgbs

where	tbg.comp_id		=	@comp_id
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)
AND		tbgd.bra_id		=   @bra_id
AND		fcgbs.cust_id	=	tc.cust_id
AND		NOT tc.cust_credit_own IS NULL

GROUP BY tbg.brag_id,tbgd.bra_id, tbg.brag_desc
GO






CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_MaxCreditExceeded]
(
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	AS INT,
	@case_id	AS INT,
	@user_id	AS INT


)
AS
SET NOCOUNT ON

/*
DECLARE @comp_id		INT,
		@bra_id			INT,
		@brag_id		INT,
		@dateFrom		DATETIME,
		@dateTo			DATETIME,
		@dateActual		DATETIME,
		@scpm_id		INT,
		@case_id		INT

SET @comp_id        = 1
SET @bra_id			= 1
SET	@brag_id	    = -1
SET	@dateFrom	    = '2000/01/01'
SET	@dateTo			= '2009/31/12'
SET	@dateActual		= '2009/10/08'
SET	@scpm_id		= 14001000
SET	@case_id		= 1
*/

set dateformat 'ymd'

INSERT  #tmpControlPanelMeasures

SELECT	tbg.brag_id									[ID],
		--tbg.brag_id									[ID1],
		tbgd.bra_id									[ID1],
		tbg.brag_desc								[Indicador],
		sum(tc.cust_credit_max - fcgbs.cust_credit_cheque_own_used		+
		fcgbs.cust_credit_cheque_3rd_used		+
		fcgbs.cust_credit_balance)[Total],
		@scpm_id									[scpm_id]

FROM	tbBranchGroup									tbg

		INNER JOIN tbBranchGroupDetail					tbgd
		ON	tbgd.comp_id			=	tbg.comp_id
		AND tbgd.brag_id			=	tbg.brag_id
		AND tbgd.bra_id				=	@bra_id

 		INNER JOIN tbCustomer							tc
		ON	tc.comp_id				=	tbg.comp_id
		AND	tc.bra_id				=	tbgd.bra_id

		CROSS APPLY dbo.fnCustomer_getBalanceStatus(1,1,tc.cust_id,@user_id,GETDATE(),-1,-1) fcgbs

WHERE	tbg.comp_id		=	@comp_id
AND		(@brag_id		=	-1	or	tbgd.brag_id	= @brag_id)
AND		fcgbs.cust_id	=	tc.cust_id
AND		not tc.cust_credit_max IS NULL

GROUP BY tbg.brag_id,tbgd.bra_id, tbg.brag_desc


GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================

CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_SALESMAN_SalesMonthDifference]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id    INT,
	@rank		INT,
	@user_id	INT

AS
SET NOCOUNT ON

/*
	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id    AS INT
	DECLARE @user_id	AS INT


	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2009/01/01'
	SET		@dateTo     = '2009/31/12'
	SET		@dateActual = '2009/26/10'
	SET		@scpm_id	= 1000000
	SET     @case_id    = 8
	SET     @rank       = 6
	SET     @user_id	= 1


DROP TABLE #tmp

*/

SELECT @rank = @rank * -1

SELECT	tct.sm_id												[Id],
		tct.bra_id												[Id1],
		ts.sm_name												[Indicator],
	sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			ELSE
				0
			END	,0))											[TotalA],

		sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				0
			ELSE
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			END	,0))											[TotalB],

		@scpm_id												[scpm_id]


INTO	#tmp

FROM	tbCommercialTransactions									tct

		INNER JOIN dbo.vwCommercialTransactions_forSales			vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction
		AND		vctfss.sd_isReceipt		= 'False'

		INNER JOIN tbBranchGroupDetail								tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup								    tbg
		ON		tbg.comp_id				= tct.comp_id
		--AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN tbItemTransactions							    tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction

		INNER JOIN vwItemTransactions							   vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction

		INNER JOIN tbSalesman										ts
		ON		ts.comp_id				= tct.comp_id
		AND		ts.sm_id				= tct.sm_id

		inner join vwUsers4BranchFilter vubf
		ON  vubf.comp_id				 = tct.comp_id
		AND vubf.bra_id					 = tct.bra_id
		AND vubf.[user_id]				 = @user_id


WHERE	tct.comp_id		= @comp_id
AND		(@brag_id		= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8)	AND	tct.ct_date BETWEEN DATEADD(MONTH,@rank		,@dateActual)	AND @dateActual
						OR 	tct.ct_date	BETWEEN DATEADD(MONTH,@rank - 12	,@dateActual)	AND DATEADD(MONTH,-12,@dateActual))


GROUP BY	 tct.sm_id,
			 ts.sm_name,
			 tct.bra_id




--SELECT * FROM #tmp



if @case_id = 4
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator], SUM([TotalA]) -  SUM([TotalB]) ,[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]


IF @case_id = 8
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator],
	CASE WHEN SUM([TotalB]) = 0 THEN 0
		ELSE ((SUM([TotalA])/dbo.fnNoZDiv(SUM([TotalB])))-1)*100
	END,
	[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]



GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================

CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_SALESMAN_SalesOfThisMonth]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id    INT,
	@user_id	INT

AS
SET NOCOUNT ON


/*
	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id    AS INT
	DECLARE @user_id	as INT


	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '2010/31/12'
	SET		@dateActual = '2009/04/09'
	SET		@scpm_id	= 1000000
	SET     @case_id    = 5
	SET     @user_id	= 1

*/



INSERT  #tmpControlPanelMeasures

SELECT	isnull(tct.sm_id,-1)									[Id],
		tct.bra_id												[Id1],
		isnull(ts.sm_name,125)									[Indicator],
		CASE
		--ventas totales entre fechas / último mes
		WHEN @case_id < 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

		--ventas totales últimos 6 meses
		WHEN @case_id = 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))
									--/ COUNT(DISTINCT MONTH(tct.ct_date))

		--saldos de ventas
		WHEN @case_id > 4 AND @case_id < 8	THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_ABalance,tct.ct_ACurrency,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

		END														[Total],
		@scpm_id												[scpm_id]


FROM	tbCommercialTransactions								tct

		INNER JOIN dbo.vwCommercialTransactions_forSales		vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

		LEFT JOIN tbSalesman									ts
		ON		ts.comp_id				= tct.comp_id
		AND		ts.sm_id				= tct.sm_id

		inner join vwUsers4BranchFilter							vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id					= tct.bra_id
		AND vubf.[user_id]				= @user_id


WHERE	tct.comp_id		= @comp_id

AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		(((
		(@case_id IN (1)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual)))
		AND		vctfss.sd_isReceipt		= 'False'
		) OR (
		(@case_id IN (5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		))

GROUP BY	 tct.sm_id,
			 ts.sm_name,
			 tct.bra_id




GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================


CREATE	PROCEDURE [dbo].[spControlPanelMeasureTOTAL_SALESTERMS_SalesMonthDifference]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@rank		INT,
	@user_id	INT


AS
SET NOCOUNT ON


/*
DECLARE @comp_id	AS INT
DECLARE @bra_id		AS INT
DECLARE @brag_id	AS INT
DECLARE @dateFrom	AS DATETIME
DECLARE @dateTo		AS DATETIME
DECLARE @dateActual AS DATETIME
DECLARE @scpm_id	AS INT
DECLARE @case_id	INT
DECLARE @user_id	INT

SET     @comp_id    = 1
SET		@bra_id	    = 1
SET     @brag_id    = 2
SET		@dateFrom   = '2009/01/01'
SET		@dateTo     = '2009/31/12'
SET		@dateActual = '2009/03/08'
SET		@scpm_id	= 1000000
SET		@case_id	= 4
SET     @user_id	= 1


DROP TABLE #tmp
*/

SELECT @rank = @rank * -1


SELECT	tst.st_id												[Id],
		tct.bra_id												[Id1],
		tst.st_desc											[Indicator],
				sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			ELSE
				0
			END	,0))											[TotalA],

		sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				0
			ELSE
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			END	,0))											[TotalB],

		@scpm_id												[scpm_id]
INTO	#tmp

FROM	tbCommercialTransactions 								tct

		INNER JOIN dbo.vwCommercialTransactions_forSalesStats	vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction


		INNER JOIN	tbSalesTerms								tst
		ON tst.comp_id					= vctfss.comp_id
		AND tst.bra_id					= vctfss.bra_id


--		INNER JOIN tbSubCategory								tsc
--		ON tsc.comp_id					= vctfss.comp_id
--		AND tsc.bra_id					= vctfss.bra_id
--
--
--
--		INNER JOIN tbCategory									tc
--		ON  tc.comp_id					= vctfss.comp_id
--		AND tc.bra_id					= vctfss.bra_id
--




		INNER JOIN tbItem										ti
		ON ti.comp_id					= vctfss.comp_id
		AND ti.bra_id					= vctfss.bra_id
		AND ti.supp_id					= vctfss.supp_id



		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id



		INNER JOIN tbsysState									ts
		ON		ts.country_id			= tct.country_id
		AND		ts.state_id				= tct.state_id

		inner join vwUsers4BranchFilter vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id					= tct.bra_id
		AND vubf.[user_id]				= @user_id






WHERE	tct.comp_id		= @comp_id
AND		not tct.sm_id	is NULL
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

AND		(@case_id IN (4,8)	AND	tct.ct_date BETWEEN DATEADD(MONTH,@rank		,@dateActual)	AND @dateActual
						OR 	tct.ct_date	BETWEEN DATEADD(MONTH,@rank - 12	,@dateActual)	AND DATEADD(MONTH,-12,@dateActual))


GROUP BY	tst.st_id,
			tct.bra_id,
			tst.st_desc


    --SELECT * FROM #tmp



if @case_id = 4
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator], SUM([TotalA]) -  SUM([TotalB]) ,[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]


IF @case_id = 8
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator],
	CASE WHEN SUM([TotalB]) = 0 THEN 0
		ELSE ((SUM([TotalA])/dbo.fnNoZDiv(SUM([TotalB])))-1)*100
	END,
	[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]

GO





CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_SALESTERMS_SalesOfThisMonth]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id    INT,
	@user_id	INT

AS
SET NOCOUNT ON;

	-- Poner Aqui las variables para poder probar el SP

/*	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @brag_id	AS INT
	DECLARE @dateFrom	AS DATETIME
	DECLARE @dateTo		AS DATETIME
	DECLARE @dateActual AS DATETIME
	DECLARE @scpm_id	AS INT
	DECLARE @case_id    AS INT
	DECLARE @user_id	as int


	SET     @comp_id    = 1
	SET		@bra_id	    = 1
	SET     @brag_id    = 2
	SET		@dateFrom   = '2000/01/01'
	SET		@dateTo     = '2010/31/12'
	SET		@dateActual = '2009/04/09'
	SET 	@scpm_id	= 2000000
	SET     @case_id    = 1
	SET     @user_id	= 1



	*/


-- ACORDARSE de poner los Branch Groups en este SP

--BeginControlPanelSqlCode--

INSERT  #tmpControlPanelMeasures

SELECT	isnull(tst.st_id,-1)												[Id],
		tct.bra_id												                [Id1],
		isnull(tst.st_desc,125)											[Indicator],
	CASE
		--ventas totales entre fechas / último mes
		WHEN @case_id < 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

		--ventas totales últimos 6 meses
		WHEN @case_id = 3					THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))
									--/ COUNT(DISTINCT MONTH(tct.ct_date))

		--saldos de ventas
		WHEN @case_id > 4 AND @case_id < 8	THEN
			sum(isnull(dbo.fnGetExchange(@comp_id,tct.ct_ABalance,tct.ct_ACurrency,tbg.curr_id,0,0,'False')
									* Case When vctfss.sd_isCredit = 'False' Then 1 Else -1 End,0))

		END														[Total],
		@scpm_id												[scpm_id]


FROM	tbCommercialTransactions									tct

		INNER JOIN vwCommercialTransactions_forSales     			vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN tbBranchGroupDetail								tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN dbo.tbSalesTerms									tst
		ON		tst.comp_id				= tct.comp_id
		AND		tst.st_id				= tct.st_id

		inner join vwUsers4BranchFilter vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id					= tct.bra_id
		AND vubf.[user_id]				= @user_id



WHERE	tct.comp_id		= @comp_id

AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)


AND	(((
		(@case_id IN (1)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual)))
		AND		vctfss.sd_isReceipt		= 'False'

		) OR (
		(@case_id IN (5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		))



GROUP BY	 tst.st_id,
			 tct.bra_id,
			 tst.st_desc

GO





-- =============================================
-- Create date: 08-04-2009
-- Description:	Retorna los Totales de Venta
--				del mes en curso por Vendedor
-- =============================================


CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_STATE_SalesMonthDifference]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	INT,
	@case_id	INT,
	@rank		INT,
	@user_id	INT

AS
SET NOCOUNT ON


/*
DECLARE @comp_id	AS INT
DECLARE @bra_id		AS INT
DECLARE @brag_id	AS INT
DECLARE @dateFrom	AS DATETIME
DECLARE @dateTo		AS DATETIME
DECLARE @dateActual AS DATETIME
DECLARE @scpm_id	AS INT
DECLARE @case_id	INT
DECLARE @rank		INT
DECLARE @user_id	INT





SET     @comp_id    = 1
SET		@bra_id	    = 1
SET     @brag_id    = 2
SET		@dateFrom   = '2009/01/01'
SET		@dateTo     = '2009/31/12'
SET		@dateActual = '2009/26/10'
SET		@scpm_id	= 1000000
SET		@case_id	= 8
SET		@rank		= 6
SET     @user_id	= 1


DROP TABLE #tmp
*/



SELECT @rank = @rank * -1


SELECT	tct.state_id											[Id],
		tct.bra_id												[Id1],
		ts.state_desc											[Indicator],

		sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			ELSE
				0
			END	,0))											[TotalA],

		sum(isnull(
			CASE WHEN year(tct.ct_date) = year(@dateActual) THEN
				0
			ELSE
				dbo.fnGetExchange(@comp_id,tct.ct_total,tct.curr_id_transaction,tbg.curr_id,0,0,'False') * CASE WHEN vctfss.sd_isCredit = 'False' THEN 1 ELSE -1 END
			END	,0))											[TotalB],

		@scpm_id												[scpm_id]

INTO	#tmp

FROM	tbCommercialTransactions 								tct

		INNER JOIN dbo.vwCommercialTransactions_forSales		vctfss
		ON		vctfss.comp_id			= tct.comp_id
		AND		vctfss.bra_id			= tct.bra_id
		AND		vctfss.ct_transaction	= tct.ct_transaction
		AND		vctfss.sd_isReceipt		= 'False'


		INNER JOIN tbBranchGroupDetail							tbgd
		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				= tct.comp_id
		--AND		tbg.brag_id				= tbgd.brag_id

				INNER JOIN tbItemTransactions							tit
		ON		tit.comp_id				=	tct.comp_id
		AND		tit.bra_id				=	tct.bra_id
		AND		tit.ct_transaction		=	tct.ct_transaction

		INNER JOIN vwItemTransactions							vit
		ON		vit.comp_id				=	tit.comp_id
		AND		vit.it_transaction		=	tit.it_transaction


		INNER JOIN tbsysState									ts
		ON		ts.country_id			= tct.country_id
		AND		ts.state_id				= tct.state_id

		inner join vwUsers4BranchFilter							vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id				    = tct.bra_id
		AND vubf.[user_id]				= @user_id


WHERE	tct.comp_id						= @comp_id
AND		(@brag_id						= -1	or	tbg.brag_id	= @brag_id)

AND		(@case_id IN (4,8)	AND	tct.ct_date BETWEEN DATEADD(MONTH,@rank		,@dateActual)	AND @dateActual
						OR 	tct.ct_date	BETWEEN DATEADD(MONTH,@rank - 12	,@dateActual)	AND DATEADD(MONTH,-12,@dateActual))


GROUP BY            	tct.state_id,
						tct.bra_id,
						ts.state_desc

--SELECT * FROM #tmp





if @case_id = 4
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator], SUM([TotalA]) -  SUM([TotalB]) ,[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]


IF @case_id = 8
	INSERT  #tmpControlPanelMeasures
	SELECT	[Id],[Id1],[Indicator],
	CASE WHEN SUM([TotalB]) = 0 THEN 0
		ELSE ((SUM([TotalA])/dbo.fnNoZDiv(SUM([TotalB])))-1)*100
	END,
	[scpm_id]
	FROM	#tmp
	GROUP BY [Id],[Id1],[Indicator],[scpm_id]




GO





