		ON		tbgd.comp_id			= tct.comp_id
		AND		tbgd.bra_id				= tct.bra_id

		INNER JOIN tbBranchGroup								tbg
		ON		tbg.comp_id				= tct.comp_id
		AND		tbg.brag_id				= tbgd.brag_id

		INNER JOIN tbsysState									ts
		ON		ts.country_id			= tct.country_id
		AND		ts.state_id				= tct.state_id

		inner join vwUsers4BranchFilter							vubf
		ON  vubf.comp_id				= tct.comp_id
		AND vubf.bra_id					= tct.bra_id
		AND vubf.[user_id]				= @user_id


WHERE	tct.comp_id				= @comp_id

AND		(@brag_id				= -1	or	tbgd.brag_id	= @brag_id)


AND	(((
		(@case_id IN (1)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (2)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (3)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual)))
		AND		vctfss.sd_isReceipt		= 'False'

		) OR (
		(@case_id IN (5)	AND		tct.ct_date			BETWEEN	@dateFrom AND @dateTo) OR
		(@case_id IN (6)	AND		year(tct.ct_date) =	year(@dateActual) and month(tct.ct_date) = MONTH(@dateActual)) OR
		(@case_id IN (7)  AND		tct.ct_date > DATEADD(MONTH,-6,@dateActual))
		))


GROUP BY	tct.state_id,
			tct.bra_id,
			ts.state_desc
GO







CREATE PROCEDURE [dbo].[spControlPanelMeasureTOTAL_STOCK]
(
	@comp_id	AS INT,
	@bra_id		AS INT,
	@brag_id	AS INT,
	@dateFrom	AS DATETIME,
	@dateTo		AS DATETIME,
	@dateActual AS DATETIME,
	@scpm_id	AS INT,
	@case_id	AS INT,
	@user_id	AS INT



)
AS
SET NOCOUNT ON


/*
DECLARE @comp_id		INT,
		@bra_id			INT,
		@brag_id		INT,
		@dateFrom		DATETIME,
		@dateTo			DATETIME,
		@dateActual		DATETIME,
		@scpm_id		INT,
		@case_id		INT,



SET @comp_id        = 1
SET @bra_id			= 1
SET	@brag_id	    = -1
SET	@dateFrom	    = '2000/01/01'
SET	@dateTo			= '2009/31/12'
SET	@dateActual		= '2009/10/08'
SET	@scpm_id		= 13001000
SET	@case_id		= 1


*/



INSERT  #tmpControlPanelMeasures

SELECT DISTINCT
		tbg.brag_id									[ID],
		ts.stor_id									[ID1],
		ts.stor_desc + ' - ' + ti.item_desc			[Indicador],

		CASE @case_id
			WHEN 1 THEN
				CASE WHEN ti.item_cantMin = 0 THEN 0
					ELSE ((tis.itst_cant/dbo.fnNoZDiv(ti.item_cantMin))-1)*100
				END
			WHEN 2  THEN
				CASE WHEN ti.item_cantOpt = 0 THEN 0
					ELSE ((tis.itst_cant/dbo.fnNoZDiv(ti.item_cantOpt))-1)*100
				END

		END											[Total],
		@scpm_id									[scpm_id]


FROM tbBranchGroup								tbg

	INNER JOIN tbBranchGroupDetail				tbgd
	ON tbg.comp_id		= tbgd.comp_id
	AND tbg.brag_id		= tbgd.brag_id

	INNER JOIN tbBranch							tb
	ON  tb.comp_id		= tbgd.comp_id
	AND tb.bra_id		= tbgd.bra_id

	INNER JOIN tbStorage						ts
	ON  ts.comp_id		= tb.comp_id
	AND ts.stor_id		= tb.stor_id

	INNER JOIN tbItemStorage					tis
	ON tis.comp_id		= ts.comp_id
	AND tis.stor_id		= ts.stor_id

	INNER JOIN tbItem							ti
	ON	ti.comp_id		= tbgd.comp_id
	AND ti.item_id		= tis.item_id


WHERE	tbg.comp_id   = @comp_id
AND		(@brag_id		= -1	or	tbgd.brag_id	= @brag_id)

GO




CREATE PROCEDURE [dbo].[spControlProfiles_CloneProfile]
(
	@comp_id				INT,
	@bra_id_Origin			INT,
	@bra_id_Destiny			INT,
	@prof_id				INT,
	@deletePreviousCFG		BIT,
	@bitCloneAllProfiles	BIT
)
AS

	SET NOCOUNT ON
		BEGIN

			-- ---------------------------------------------
			-- TESTING
			-- ---------------------------------------------
			/*
				DECLARE
					@comp_id			INT,
					@bra_id_Origin		INT,
					@bra_id_Destiny		INT,
					@prof_id			INT,
					@deletePreviousCFG	BIT
				SELECT
					@comp_id			= 1,
					@bra_id_Origin		= 1,
					@bra_id_Destiny		= 50,
					@prof_id			= 1,
					@deletePreviousCFG	= 'False'
			*/
			-- ---------------------------------------------


			IF @deletePreviousCFG = 'True'
				BEGIN
					--COMO CHECKEÓ PARA QUE BORRARA TODA LA CONFIGURACIÓN DEL PERFIL
					--COMO PRIMER PASO BORRAMOS TODOS LOS DATOS DE LA SUCURSAL DE DESTINO

					DELETE FROM tbControlProfiles
					WHERE	comp_id = @comp_id			AND
							bra_id	= @bra_id_Destiny	AND
						   (prof_id = @prof_id OR @bitCloneAllProfiles = 'True')

				END

			--COMO YA NO HAY REGISTROS ASOCIADOS AL PERFIL EN LA SUCURSAL DE DESTINO
			--INSERTAMOS DIRECTAMENTE CON UN SELECT SOLO QUE EN LUGAR DE MANTENER LA
			--SUCURSAL ANTERIOR GRABAMOS CON LA SUCURSAL DE DESTINO.
			INSERT INTO tbControlProfiles
			(
				comp_id,
				bra_id,
				prof_id,
				page_id,
				ctrl_id,
				[type_id],
				prop_id,
				fun_id
			)
