									FROM tbControlProfiles tcp1
									WHERE	tcp1.comp_id	= tbcp.comp_id AND
											tcp1.bra_id		= @bra_id_Destiny AND
											tcp1.prof_id	= tbcp.prof_id AND
											tcp1.page_id	= tbcp.page_id AND
											tcp1.ctrl_id	= tbcp.ctrl_id AND
											tcp1.[type_id]	= tbcp.[type_id] AND
											tcp1.prop_id	= tbcp.prop_id AND
