			--				tbcp.page_id,
			--				tbcp.ctrl_id,
			--				tbcp.[type_id],
			--				tbcp.prop_id,
			--				tbcp.fun_id

			--			FROM tbControlProfiles						tbcp
			--			WHERE	tbcp.comp_id	= @comp_id			AND
			--					tbcp.bra_id		= @bra_id_Origin	AND
			--					tbcp.prof_id	= @prof_id

			--		OPEN	cursor_ControlProfiles
			--		FETCH cursor_ControlProfiles
			--		INTO
			--			@lcomp_id,
			--			@lbra_id,
			--			@lprof_id,
			--			@lpage_id,
			--			@lctrl_id,
			--			@ltype_id,
