			--				--EL PERFIL Y EL CONTROL EN LA SUCURSAL DE DESTINO, EN ESE CASO NO INSERTAREMOS NADA Y DEJAREMOS
			--				--EL REGISTRO TAL CUAL ESTÁ

			--				IF NOT EXISTS (SELECT 1
			--							   FROM tbControlProfiles					tbcp
			--							   WHERE tbcp.comp_id	= @lcomp_id			AND
			--									 tbcp.bra_id	= @bra_id_Destiny	AND
