CREATE PROCEDURE [dbo].[spControlProfiles_CloneProfiles_ByBranch]
(
	@comp_id				INT,
	@bra_id					INT,
	@prof_id_Origin			INT,
	@prof_id_Destiny		INT

)
AS

SET NOCOUNT ON
	BEGIN

		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id_Origin		INT,
				@bra_id_Destiny		INT,
				@prof_id			INT,
				@deletePreviousCFG	BIT
			SELECT
				@comp_id			= 1,
				@bra_id_Origin		= 1,
				@bra_id_Destiny		= 50,
				@prof_id			= 1,
				@deletePreviousCFG	= 'False'
		*/
		-- ---------------------------------------------

	INSERT INTO tbControlProfiles
		(
			comp_id,
			bra_id,
			prof_id,
			page_id,
			ctrl_id,
			[type_id],
			prop_id,
			fun_id
		)
		SELECT
			tbcp.comp_id,
			tbcp.bra_id,
			@prof_id_Destiny,
			tbcp.page_id,
			tbcp.ctrl_id,
			tbcp.[type_id],
			tbcp.prop_id,
			tbcp.fun_id

		FROM tbControlProfiles										tbcp
		WHERE	tbcp.comp_id	= @comp_id					AND
				tbcp.bra_id		= @bra_id					AND
			   	tbcp.prof_id	= @prof_id_Origin			AND
				NOT EXISTS (SELECT 1
								FROM tbControlProfiles tcp1
								WHERE	tcp1.comp_id	= tbcp.comp_id AND
										tcp1.bra_id		= @bra_id AND
										tcp1.prof_id	= @prof_id_Destiny AND
										tcp1.page_id	= tbcp.page_id AND
										tcp1.ctrl_id	= tbcp.ctrl_id AND
										tcp1.[type_id]	= tbcp.[type_id] AND
										tcp1.prop_id	= tbcp.prop_id AND
										tcp1.fun_id		= tbcp.fun_id
							)





	END






GO






