CREATE PROCEDURE [dbo].[spControlProfiles_getCombo]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@page_id		INT,
	@fun_id			INT
)
AS

BEGIN


	SET NOCOUNT ON

-- ---------------------------------------
-- Testing
-- ---------------------------------------
/*
	declare	@comp_id	int,
			@lang_id	INT,
			@bra_id		int,
			@prof_id	INT,
			@page_id	INT,
			@fun_id		INT
	select	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@prof_id	= 1,
			@page_id	= 6,
			@fun_id		= 1
*/
-- ---------------------------------------


	select	DISTINCT '(' +dbo.fnStrPADL( CONVERT(VARCHAR,cp.ctrl_id),5,'0') + ') '  + tw.word_desc					[desc],

			convert(varchar,cp.page_id) + '-' +
			convert(varchar,cp.ctrl_id) + '-' +
			convert(varchar,cp.type_id) + '-' +
			convert(varchar,cp.prop_id) + '-' +
			convert(varchar,cp.fun_id)				[id],
			tw.word_desc							[Order]
		INTO #tmpReturn
		from	dbo.tbControlProfiles			cp			WITH (NOLOCK)

				inner join [tbsysControls]		c			WITH (NOLOCK)
				on c.[ctrl_id]		= cp.ctrl_id

				INNER JOIN	tbsysTextsNew		t			WITH (NOLOCK)
				ON	--t.lang_id		=	@lang_id
				--AND
					t.page_id		=	cp.page_id
				AND	t.ctrl_id		=	cp.ctrl_id
				AND	t.[type_id]	=	c.[type_id]
				AND	t.prop_id		IN (1,20,2)
				AND	t.fun_id		=	cp.fun_id

				INNER JOIN tbsysWordsNew		tw			WITH (NOLOCK)
				ON	tw.lang_id		= @lang_id
				AND tw.wordsi_id	= t.wordsi_id


		where	cp.comp_id	=	@comp_id
		and		cp.bra_id	=	@bra_id
		and		cp.prof_id	=	@prof_id
		AND		cp.page_id	=	@page_id
		AND		cp.fun_id	=	@fun_id


		-- ----------------------------------------------------------------------------------------
		-- ATENCION: MOS
		-- Si se modifica algo aquí, copiar exactamente lo mismo al sp [spSysPageControls_getCombo]
		-- ----------------------------------------------------------------------------------------
		AND     ((t.type_id = 5		AND	t.prop_id = 2 )	or	--ImageButton + tooltip
				 (t.type_id = 3		AND	t.prop_id = 2 )	or	-- Textbox + tooltip
				 (t.type_id = 23	AND t.prop_id = 2 ) or	-- checkbox + tooltip
				 (t.type_id = 6  	AND t.prop_id = 2 ) or	-- DDL + tooltip
				 (t.type_id = 59	AND t.prop_id = 20) or	-- zdummy + Enabled
				 (t.type_id = 61					  ) or	-- wucExchange
				 (t.type_id = 62					  ) OR	-- wucPrice
				 (t.type_id <> 5	AND	t.prop_id = 1)	OR	-- diferente de ImageButton y que tenga la propiedad Text con algo
				 (t.type_id = 34  	AND t.prop_id = 2 ))    -- wucDateCalendar + tooltip
				 AND t.type_id <> 40
		-- ----------------------------------------------------------------------------------------


	UNION

	/**********************************************************************************************************/
	/* se agrega este union para recuperar los datos de los controles del toolbox relacionado a cada página   */



	SELECT 	--tov.optval_desc														[desc],
			--convert(varchar(9),pc.ctrl_id) + '-' + convert(varchar(9),2)			[id],
			--c.[type_id], 2 [prop_id]

	DISTINCT '(' +dbo.fnStrPADL( CONVERT(VARCHAR,cp.ctrl_id),5,'0') + ') ' +  tov.optval_desc							[desc],
			CONVERT(VARCHAR,cp.page_id) + '-' +
			CONVERT(VARCHAR,cp.ctrl_id) + '-' +
			CONVERT(VARCHAR,cp.type_id) + '-' +
			CONVERT(VARCHAR,cp.prop_id) + '-' +
			CONVERT(VARCHAR,cp.fun_id)					[id],
			tov.optval_desc


		FROM 	dbo.tbControlProfiles						cp			WITH (NOLOCK)

				INNER JOIN tbsysControls					c			WITH (NOLOCK)
				ON 	c.ctrl_id			=	cp.ctrl_id
				AND (
						c.ctrl_desc = 'imgExportToExcel'	OR
						c.ctrl_desc = 'imgPrint'			OR
						c.ctrl_desc = 'imgCopy'
					)

		--		inner join tbsysTypes						st
		--		on	st.[type_id]		=	c.[type_id]

				INNER JOIN tbsysOptionsValues				tov			WITH (NOLOCK)
				ON  tov.optval_class	= 5
				AND (
						(tov.optval_id	= 5 AND c.ctrl_desc = 'imgCopy')			OR
						(tov.optval_id	= 6 AND c.ctrl_desc = 'imgExportToExcel')	OR
						(tov.optval_id	= 7 AND c.ctrl_desc = 'imgPrint')
					)
				AND tov.lang_id			= @lang_id

		WHERE   cp.comp_id	=	@comp_id
		AND 	cp.bra_id	=	@bra_id
		AND 	cp.prof_id	=	@prof_id
		AND		cp.page_id	=	@page_id
		AND		cp.fun_id	=	@fun_id

		/**********************************************************************************************************/


	SELECT [Desc],[Id]
		FROM #tmpReturn
		ORDER BY [Order]

	DROP TABLE #tmpReturn

END
GO








CREATE PROCEDURE [dbo].[spControlProfiles_getData]
(
		@comp_id		int,
		@bra_id			int,
		@prof_id		int,
		@page_id		int,
		@fun_id			int,
		@user_id		int
)
AS


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


set nocount on


-- -----------------------------------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@bra_id			int,
		@prof_id		int,
		@page_id		int,
		@fun_id			INT,
		@user_id		INT
select	@comp_id		=1,
		@bra_id			=26,
		@prof_id		=1,
		@page_id		=173,
		@fun_id			=1,
		@user_id		=1
DROP TABLE #tmpProfiles
*/
-- -----------------------------------------------------------------------------------------


IF @user_id = -1

	BEGIN

		select	CP.page_id,
				P.page_desc,
				CP.ctrl_id,
				C.ctrl_desc			ctrl_desc,
				CP.type_id,
				Ty.type_desc,
				CP.prop_id,
				Pr.prop_desc		prop_desc,
				cp.prof_id,
				cp.fun_id

		from	dbo.tbControlProfiles				CP

				inner join dbo.tbSysPages			P
				on	P.page_id		=	CP.page_id

				inner join dbo.tbSysControls		C
				on	C.ctrl_id		=	CP.ctrl_id

				inner join dbo.tbSysTypes			Ty
				on	Ty.[type_id]	=	CP.[type_id]

				inner join dbo.tbSysProperties		Pr
				on	Pr.prop_id		=	CP.prop_id

		where	CP.comp_id			=	@comp_id
		and		CP.bra_id			=	@bra_id
		and		CP.prof_id			=	@prof_id
		and		CP.page_id			=	@page_id
		AND		cp.fun_id			=	@fun_id

		order by type_desc, ctrl_desc

	END

ELSE

	BEGIN

		SELECT	distinct tucp.prof_id
		INTO	#tmpProfiles
		FROM	tbUserCompanyProfile tucp
		WHERE	tucp.[user_id] = @user_id
		--SELECT * FROM #tmpProfiles

		select	distinct isnull(CP.page_id,-1) [page_id],
				P.page_desc,
				CP.ctrl_id,
				C.ctrl_desc			ctrl_desc,
				CP.type_id,
				Ty.type_desc,
				CP.prop_id,
				Pr.prop_desc		prop_desc,
				cp.prof_id,
				cp.fun_id--,
				--tp.*

		from	#tmpProfiles				tp

				inner JOIN dbo.tbControlProfiles				CP
				ON	tp.prof_id		=	cp.prof_id
				AND CP.comp_id		=	@comp_id
				and	CP.bra_id		=	@bra_id
				AND CP.page_id		=	@page_id
				AND	CP.fun_id		=	@fun_id
				AND cp.prof_id		=	@prof_id

				LEFT JOIN dbo.tbSysPages			P
				on	P.page_id		=	CP.page_id

				LEFT JOIN dbo.tbSysControls		C
				on	C.ctrl_id		=	CP.ctrl_id

				LEFT JOIN dbo.tbSysTypes			Ty
				on	Ty.[type_id]	=	CP.[type_id]

				LEFT JOIN dbo.tbSysProperties		Pr
				on	Pr.prop_id		=	CP.prop_id

--		where	CP.comp_id			=	@comp_id
--		--and		CP.bra_id			=	@bra_id
--		and		CP.page_id			=	@page_id
--		AND		cp.fun_id			=	@fun_id

		order BY page_id, type_desc, ctrl_desc



--		SELECT  cp.*, tp.*
--		from	#tmpProfiles tp
--
--				left join 	dbo.tbControlProfiles				CP
--				ON tp.prof_id		=	cp.prof_id
--
--		and	CP.comp_id			=	@comp_id
--		and		CP.page_id			=	@page_id
--		--AND		cp.fun_id			=	@fun_id


	END

GO








