					on	C.ctrl_id		=	CP.ctrl_id

					inner join dbo.tbSysTypes			Ty		WITH (NOLOCK)
					on	Ty.[type_id]	=	CP.[type_id]

					inner join dbo.tbSysProperties		Pr		WITH (NOLOCK)
					on	Pr.prop_id		=	CP.prop_id

			where	CP.comp_id			=	@comp_id
			and		CP.bra_id			=	@bra_id
			and		CP.prof_id			=	@prof_id
			and		CP.page_id			=	@page_id
			AND		cp.ctrl_id			=	@ctrl_id

			order by type_desc, ctrl_desc

END
GO











-- =================================================================
-- Author:		MOH
-- Modif:		MOS  29-2-08
-- Description:	Trae Valores por ID de conf. del sistema
-- Si no encuentra el dato por compañia y por sucursal
-- lo busca solo por compañia y sucursal 1
-- la cual estara cargada por script inicial del sistema
-- Como  lo pide por rango, tiene que respetar esto ultimo
-- =================================================================

CREATE  PROCEDURE [dbo].[spControlProfiles_insertData]
(
	@comp_id			int,
	@bra_id				int,
	@prof_id			int,
	@page_id			int,
	@ctrl_id			int,
	@prop_id			int,
	@fun_id				int
)

as

declare @type_id			int
set @type_id = (select type_id from tbsyscontrols where ctrl_id = @ctrl_id)

if not exists (select 1 from tbcontrolProfiles where
				comp_id =	@comp_id	and
				bra_id  =	@bra_id		and
				prof_id	=	@prof_id	and
				page_id	=	@page_id	and
				ctrl_id	=	@ctrl_id	and
				type_id	=	@type_id	and
				prop_id	=	@prop_id	and
				fun_id	=	@fun_id)



insert into dbo.tbControlProfiles
		    (	comp_id,
				bra_id,
				prof_id,
				page_id,
				ctrl_id,
				type_id,
				prop_id,
				fun_id
			)

values
			(
				@comp_id,
				@bra_id,
				@prof_id,
				@page_id,
				@ctrl_id,
				@type_id,
				@prop_id,
				@fun_id
			)



GO



CREATE PROCEDURE [dbo].[spConvert_DateTime]
(
		@datDateTime	 DATETIME,
		@intFirstOrEnd	 INT,				-- -1, Nada, 1.Comienzo, 2-Fin
		@intFormat		 int				-- -1 = Nada
)

AS

BEGIN

	IF @intFirstOrEnd = 1	SET @datDateTime = dbo.fnGetEnd_or_BeginOfDate(@datDateTime,'False')
	IF @intFirstOrEnd = 2	SET @datDateTime = dbo.fnGetEnd_or_BeginOfDate(@datDateTime,'True')
	IF @intFormat	 <= 0	SET @intFormat	 = 120


	SELECT  @datDateTime								[Date],
			convert(varchar,@datDateTime,@intFormat)	[DateAsString]

END
GO


CREATE PROCEDURE [dbo].[spCostCenter_getCombo]
(
	@comp_id				INT,
	@bra_id					INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------
		-- TESTING
		-- -------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1
		*/
		-- -------------------------------------

		SELECT
			cc_code		[Id],
			cc_desc		[desc]
			FROM	dbo.tbCostCenter
			WHERE	comp_id	= @comp_id
		ORDER BY	CASE WHEN bra_id IS NOT NULL AND bra_id = @bra_id THEN	0
					ELSE													1
					END
	END



















GO






