CREATE PROCEDURE [dbo].[spCostlistActualizationRules]
(
	@comp_id			AS INT,
	@intListNumber		AS INT,
	@item_id			AS INT,
	@bitIs4PriceList	AS BIT,
	@bitDisabled4Rules	AS BIT
)
AS



BEGIN



	SET NOCOUNT ON

	-- ------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------
	/*
	DECLARE		@comp_id		INT,
				@intListNumber		INT,
				@item_id		INT,
				@bitIs4PriceList	AS BIT = 'False',
				@bitDisabled4Rules	AS BIT = 'False'

	SELECT		@comp_id		= 1,
				@intListNumber		= 1,
				@item_id		= 348
	*/
	-- ------------------------------------------------------------------------------


	SET @bitDisabled4Rules = ISNULL(@bitDisabled4Rules,'False')

	DECLARE @coslis_price					DECIMAL(38,6)
	DECLARE @coslis_priceAW					DECIMAL(38,6)
	DECLARE	@coslis_curr_id					INT


	--declare para el cursor
	DECLARE	@lclr_id						INT,
			@lclr_coslis_id_Updated			INT,
			@lclr_prli_id_Updated			INT,
			@lclr_originListType			INT,
			@lclr_DestCurrIdIdemOrigin		BIT,
			@lclr_actMethod					INT,
			@lclr_origin_coslis_id			INT,
			@lclr_origin_prli_id			INT,
			@lclr_order						INT,
			@lclr_round2Decimals			INT,
			@lcat_id						INT,
			@lsubcat_id						INT,
			@lsubcataux_id					INT,
			@lsupp_id						INT,
			@lbrand_id						INT,
			@lclr_destinyListType			INT,
			@lclr_destiny_coslis_id			INT,
			@lclr_destiny_prli_id			INT,
			@lclr_coefficient					DECIMAL(38,4),
			@litem_markup_1						DECIMAL(19,5),
			@litem_markup_2						DECIMAL(19,5),
			@litem_markup_3						DECIMAL(19,5),
			@litem_markup_4						DECIMAL(19,5),
			@litem_markup_5						DECIMAL(19,5),
			@litem_markup_6						DECIMAL(19,5),
			@litem_markup_7						DECIMAL(19,5),
			@litem_markup_8						DECIMAL(19,5),
			@litem_markup_9						DECIMAL(19,5),
			@litem_markup_10					DECIMAL(19,5),
			@litem_markup_11					DECIMAL(19,5),
			@litem_markup_12					DECIMAL(19,5),
			@litem_markup_13					DECIMAL(19,5),
			@litem_markup_14					DECIMAL(19,5),
			@litem_markup_15					DECIMAL(19,5),
			@litem_markup_16					DECIMAL(19,5),
			@litem_currId						INT,
			@lOnlyIfPlusCost					BIT,
			@lclr_ApplyItemsCostDiscount		BIT,
			@lclr_noExecuteOnDisabledRecords	BIT,
			@clr_PurchaseDiscountApplyMethod	INT,
			@plm_id								INT,
			@pd_id								INT,
			@purOrd_surcharge1					DECIMAL(19,6),
			@purOrd_surcharge2					DECIMAL(19,6),
			@purOrd_surcharge3					DECIMAL(19,6),
			@purOrd_surcharge4					DECIMAL(19,6),
			@purOrd_Disc1						DECIMAL(19,6),
			@purOrd_Disc2						DECIMAL(19,6),
			@purOrd_Disc3						DECIMAL(19,6),
			@purOrd_Disc4						DECIMAL(19,6),
			@clr_sumTaxes2Destiny				BIT,
			@clr_disableDestinyCreation			BIT,
			@clr_roundFinalPrice				BIT,
			@clr_roundFinalPrice_Multiple		INT,
			@clr_roundFinalPrice_Option			INT,
			@clr_roundFinalPrice_From			INT





-- guardar el coeficiente de la tabla de descuentos
-- tomar los deccuentos que se deban aplicar segun el campo de accion a tomar
-- si va con incremento tomarlo de la tabla de incrementos y si no hay ninguno hacer loop  >> LISTO



	--cursor para recorrer las reglas de actualización
	--declare cursor_ClAR_items cursor for

	SELECT	ROW_NUMBER() OVER(ORDER BY ticlar.clr_order ) [RowNumber],
			ticlar.clr_id ,
			ticlar.clr_coslis_id_Updated ,
			ticlar.clr_prli_id_Updated ,
			ticlar.clr_originListType ,
			ticlar.clr_DestCurrIdIdemOrigin ,
			ticlar.clr_actMethod ,
			ticlar.clr_origin_coslis_id ,
			ticlar.clr_origin_prli_id ,
			ticlar.clr_order ,
			ticlar.clr_round2Decimals ,
			ticlar.cat_id ,
			ticlar.subcat_id ,
			ticlar.subcataux_id,
			ticlar.brand_id ,
			ticlar.clr_destinyListType ,
			ticlar.clr_destiny_coslis_id ,
			ticlar.clr_destiny_prli_id ,
			ticlar.clr_coefficient	,
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup1
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup1
				WHEN ti.item_markup_1	IS NOT NULL	THEN ISNULL(ti.item_markup_1,0)
				ELSE								0
			END									[item_markup_1],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup2
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup2
				WHEN ti.item_markup_2	IS NOT NULL	THEN ISNULL(ti.item_markup_2,0)
				ELSE								0
			END									[item_markup_2],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup3
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup3
				WHEN ti.item_markup_3	IS NOT NULL	THEN ISNULL(ti.item_markup_3,0)
				ELSE								0
			END									[item_markup_3],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup4
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup4
				WHEN ti.item_markup_4	IS NOT NULL	THEN ISNULL(ti.item_markup_4,0)
				ELSE								0
			END									[item_markup_4],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup5
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup5
				WHEN ti.item_markup_5	IS NOT NULL	THEN ISNULL(ti.item_markup_5,0)
				ELSE								0
			END									[item_markup_5],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup6
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup6
				WHEN ti.item_markup_6	IS NOT NULL	THEN ISNULL(ti.item_markup_6,0)
				ELSE								0
			END									[item_markup_6],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup7
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup7
				WHEN ti.item_markup_7	IS NOT NULL	THEN ISNULL(ti.item_markup_7,0)
				ELSE								0
			END									[item_markup_7],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup8
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup8
				WHEN ti.item_markup_8	IS NOT NULL	THEN ISNULL(ti.item_markup_8,0)
				ELSE								0
			END									[item_markup_8],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup9
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup9
				WHEN ti.item_markup_9	IS NOT NULL	THEN ISNULL(ti.item_markup_9,0)
				ELSE								0
			END									[item_markup_9],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup10
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup10
				WHEN ti.item_markup_10	IS NOT NULL	THEN ISNULL(ti.item_markup_10,0)
				ELSE								0
			END									[item_markup_10],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup11
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup11
				WHEN ti.item_markup_11	IS NOT NULL	THEN ISNULL(ti.item_markup_11,0)
				ELSE								0
			END									[item_markup_11],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup12
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup12
				WHEN ti.item_markup_12	IS NOT NULL	THEN ISNULL(ti.item_markup_12,0)
				ELSE								0
			END									[item_markup_12],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup13
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup13
				WHEN ti.item_markup_13	IS NOT NULL	THEN ISNULL(ti.item_markup_13,0)
				ELSE								0
			END									[item_markup_13],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup14
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup14
				WHEN ti.item_markup_14	IS NOT NULL	THEN ISNULL(ti.item_markup_14,0)
				ELSE								0
			END									[item_markup_14],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup15
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup15
				WHEN ti.item_markup_15	IS NOT NULL	THEN ISNULL(ti.item_markup_15,0)
				ELSE								0
			END									[item_markup_15],
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup16
				WHEN tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup16
				WHEN ti.item_markup_16	IS NOT NULL	THEN ISNULL(ti.item_markup_16,0)
				ELSE								0
			END									[item_markup_16],

			ti.curr_id,
			IsNull(TICLAR.clr_OnlyIfPlusCost,'False')			[clr_OnlyIfPlusCost],
			ISNULL(TICLAR.clr_ApplyItemsCostDiscount,'False')	[clr_ApplyItemsCostDiscount],
			ti.supp_id,
			ticlar.clr_noExecuteOnDisabledRecords,
			ticlar.plm_id,
			ISNULL(ticlar.clr_PurchaseDiscountApplyMethod,1)	[clr_PurchaseDiscountApplyMethod],
			CASE
				WHEN ti.pd_id IS NOT NULL THEN ti.pd_id
				WHEN ts.pd_id IS NOT NULL THEN ts.pd_id
				ELSE						   NULL
			END													[pd_id],
						-- -------------------------------------------------------------
			CASE		-- TODO LO RIGE EL DESCUENTO O RECARGO # 1, OJO !!!!!!!!!!!!!!!
						-- -------------------------------------------------------------
				WHEN ti.item_purOrd_surcharge1 <> 0 THEN ti.item_purOrd_surcharge1
				WHEN ts.supp_purOrd_surcharge1 <> 0 THEN ts.supp_purOrd_surcharge1
				ELSE									 0
			END													[purOrd_surcharge1],
			CASE
				WHEN ti.item_purOrd_surcharge1 <> 0 THEN ti.item_purOrd_surcharge2
				WHEN ts.supp_purOrd_surcharge1 <> 0 THEN ts.supp_purOrd_surcharge2
				ELSE									 0
			END													[purOrd_surcharge2],
			CASE
				WHEN ti.item_purOrd_surcharge1 <> 0 THEN ti.item_purOrd_surcharge3
				WHEN ts.supp_purOrd_surcharge1 <> 0 THEN ts.supp_purOrd_surcharge3
				ELSE									 0
			END													[purOrd_surcharge3],
			CASE
				WHEN ti.item_purOrd_surcharge1 <> 0 THEN ti.item_purOrd_surcharge4
				WHEN ts.supp_purOrd_surcharge1 <> 0 THEN ts.supp_purOrd_surcharge4
				ELSE									 0
			END													[purOrd_surcharge4],
			CASE
				WHEN ti.item_purOrd_Disc1 <> 0		THEN ti.item_purOrd_Disc1
				WHEN ts.supp_purOrd_Disc1 <> 0		THEN ts.supp_purOrd_Disc1
				ELSE									 0
			END													[purOrd_Disc1],
			CASE
				WHEN ti.item_purOrd_Disc1 <> 0		THEN ti.item_purOrd_Disc2
				WHEN ts.supp_purOrd_Disc1 <> 0		THEN ts.supp_purOrd_Disc2
				ELSE									 0
			END													[purOrd_Disc2],
			CASE
				WHEN ti.item_purOrd_Disc1 <> 0		THEN ti.item_purOrd_Disc3
				WHEN ts.supp_purOrd_Disc1 <> 0		THEN ts.supp_purOrd_Disc3
				ELSE									 0
			END													[purOrd_Disc3],
			CASE
				WHEN ti.item_purOrd_Disc1 <> 0		THEN ti.item_purOrd_Disc4
				WHEN ts.supp_purOrd_Disc1 <> 0		THEN ts.supp_purOrd_Disc4
				ELSE									 0
			END														[purOrd_Disc4],
			ISNULL(ticlar.clr_sumTaxes2Destiny,'False')				[clr_sumTaxes2Destiny],
			ISNULL(ticlar.clr_disableDestinyCreation,'False')		[clr_disableDestinyCreation],
			ISNULL(ticlar.clr_roundFinalPrice,'False')				[clr_roundFinalPrice],
			ISNULL(ticlar.clr_roundFinalPrice_Multiple,0)			[clr_roundFinalPrice_Multiple],
			ISNULL(ticlar.clr_roundFinalPrice_Option,1)				[clr_roundFinalPrice_Option],
			ISNULL(ticlar.clr_roundFinalPrice_From,0)				[clr_roundFinalPrice_From]

						-- -------------------------------------------------------------

			INTO #tmpCursor
			FROM	tbItemCostListActualizationRules ticlar						WITH (NOLOCK)	-- MOS 04-2022, no se x q se le habra sacado esto, no jode en nada
			INNER JOIN		tbItem ti											WITH (NOLOCK)	-- MOS 04-2022, no se x q se le habra sacado esto, no jode en nada
				ON	ti.comp_id		= ticlar.comp_id
				AND	ti.item_id		= @item_id
			LEFT JOIN tbPriceListMarkup tplm2									WITH (NOLOCK)
				ON	tplm2.comp_id	= ti.comp_id AND
					tplm2.plm_id	= ti.plm_id
			LEFT JOIN tbPriceListMarkup tplm									WITH (NOLOCK)
				ON	tplm.comp_id	= ticlar.comp_id AND
					tplm.plm_id		= ticlar.plm_id
			LEFT JOIN tbSupplier ts												WITH (NOLOCK)
				ON	ts.comp_id = ti.comp_id AND
					ts.supp_id = ti.supp_id

			WHERE	ticlar.comp_id					= @comp_id
			AND		CASE
	   					WHEN @bitIs4PriceList = 'False' AND ticlar.clr_coslis_id_Updated	= @intListNumber  THEN  'True'
	   					WHEN @bitIs4PriceList = 'True'  AND ticlar.clr_prli_id_Updated	    = @intListNumber  THEN  'True'
	   					ELSE																						'False'
	   				END					= 'True'

			AND     isnull(ticlar.clr_disabled,'false') = 'false'

			AND		(ticlar.cat_id			is null	or ticlar.cat_id		= ti.cat_id)
			AND		(ticlar.subcat_id		is null	or ticlar.subcat_id		= ti.subcat_id)
			AND		(ticlar.subcataux_id	is null	or (ticlar.subcataux_id = ti.subcataux_id AND ti.subcataux_id IS NOT NULL))
			AND		(ticlar.brand_id		is null	or ticlar.brand_id		= ti.brand_id)
			AND		(ticlar.supp_id			is null	or ticlar.supp_id		= ti.supp_id)
			AND		CASE
						WHEN ticlar.clr_ExecuteOnSumPriceCombo		= 'True'		THEN 1
						WHEN ticlar.clr_ExecuteOnSumPriceCombo		= 'False' AND
							 ti.item_isForAssociation				= 'True'  AND
							 ti.item_ifHasItemAssociationSumPrices	= 'True'		THEN 0 -- Si ES un COMBO que SUMA precios de las partes y la regla NO ejecuta eso, NO LO HACE!
						ELSE															 1
					END = 1


			ORDER BY ticlar.clr_order




	DECLARE @intCounter AS INT
	SET		@intCounter		= 1
	DECLARE @intTotalRows AS INT
	SELECT	@intTotalRows	= COUNT(*)
		FROM #tmpCursor


	WHILE   @intCounter <= @intTotalRows
		BEGIN

			SELECT
					@lclr_id					= clr_id,
					@lclr_coslis_id_Updated		= clr_coslis_id_Updated,
					@lclr_prli_id_Updated		= clr_prli_id_Updated,
					@lclr_originListType		= clr_originListType,
					@lclr_DestCurrIdIdemOrigin	= clr_DestCurrIdIdemOrigin,
					@lclr_actMethod				= clr_actMethod,
					@lclr_origin_coslis_id		= clr_origin_coslis_id,
					@lclr_origin_prli_id		= clr_origin_prli_id,
					@lclr_order					= clr_order,
					@lclr_round2Decimals		= clr_round2Decimals,
					@lcat_id					= cat_id,
					@lsubcat_id					= subcat_id,
					@lsubcataux_id				= subcataux_id,
					@lbrand_id					= brand_id,
					@lclr_destinyListType		= clr_destinyListType,
					@lclr_destiny_coslis_id		= clr_destiny_coslis_id,
					@lclr_destiny_prli_id		= clr_destiny_prli_id,
					@lclr_coefficient			= clr_coefficient,
					@litem_markup_1				= item_markup_1,
					@litem_markup_2				= item_markup_2,
					@litem_markup_3				= item_markup_3,
					@litem_markup_4				= item_markup_4,
					@litem_markup_5				= item_markup_5,
					@litem_markup_6				= item_markup_6,
					@litem_markup_7				= item_markup_7,
					@litem_markup_8				= item_markup_8,
					@litem_markup_9				= item_markup_9,
					@litem_markup_10			= item_markup_10,
					@litem_markup_11			= item_markup_11,
					@litem_markup_12			= item_markup_12,
					@litem_markup_13			= item_markup_13,
					@litem_markup_14			= item_markup_14,
					@litem_markup_15			= item_markup_15,
					@litem_markup_16			= item_markup_16,
					@litem_currId				= curr_id,
					@lOnlyIfPlusCost			= clr_OnlyIfPlusCost,
					@lclr_ApplyItemsCostDiscount		= clr_ApplyItemsCostDiscount,
					@lsupp_id							= supp_id	,
					@lclr_noExecuteOnDisabledRecords	= IsNull(clr_noExecuteOnDisabledRecords,'False'),
					@plm_id								= plm_id,
					@clr_PurchaseDiscountApplyMethod	= clr_PurchaseDiscountApplyMethod,
					@pd_id								= pd_id,
					@purOrd_surcharge1					= purOrd_surcharge1,
					@purOrd_surcharge2					= purOrd_surcharge2,
					@purOrd_surcharge3					= purOrd_surcharge3,
					@purOrd_surcharge4					= purOrd_surcharge4,
					@purOrd_Disc1						= purOrd_Disc1,
					@purOrd_Disc2						= purOrd_Disc2,
					@purOrd_Disc3						= purOrd_Disc3,
					@purOrd_Disc4						= purOrd_Disc4,
					@clr_sumTaxes2Destiny				= clr_sumTaxes2Destiny	,
					@clr_disableDestinyCreation			= clr_disableDestinyCreation,
					@clr_roundFinalPrice				= clr_roundFinalPrice,
					@clr_roundFinalPrice_Multiple		= clr_roundFinalPrice_Multiple,
					@clr_roundFinalPrice_Option			= clr_roundFinalPrice_Option,
					@clr_roundFinalPrice_From			= clr_roundFinalPrice_From
				FROM #tmpCursor tmp
				WHERE tmp.RowNumber = @intCounter


				-- ---------------------------------------------------------
				-- Comienzo del Proceso de Actualizacion
				-- ---------------------------------------------------------
				DECLARE @decOriginalPrice			AS DECIMAL(38,6)
				DECLARE @intOriginalCurrency		AS INT
				DECLARE @decDestinyPrice			AS DECIMAL(38,6)
				DECLARE @intDestinyCurrency			AS INT
				DECLARE @intDestinyActualCurrency	AS INT
				DECLARE @coslis_pricePreLast        AS DECIMAL(38,6)
				DECLARE @curr_id_PreLast			AS INT
				DECLARE @decCoeficient4Discount4Total		AS DECIMAL(38,6)
				DECLARE @decCoeficient4Bonification4Total	AS DECIMAL(38,6)
				DECLARE @decCoeficient4BonificationCN4Total	AS DECIMAL(38,6)


				SET @decCoeficient4Discount4Total		= 1
				SET @decCoeficient4Bonification4Total	= 1
				SET @decCoeficient4BonificationCN4Total	= 1


				IF @clr_PurchaseDiscountApplyMethod IN (2,3)
					BEGIN
						SELECT @decCoeficient4Discount4Total		= ISNULL(tmp.decCoeficient4Discount4Total,1),
						       @decCoeficient4Bonification4Total	= ISNULL(tmp.decCoeficient4Bonification4Total,1),
						       @decCoeficient4BonificationCN4Total	= ISNULL(tmp.decCoeficient4BonificationCN4Total,1)
							FROM dbo.fnGetPurchaseDiscount(@comp_id, @pd_id, 1) tmp
					END





				IF @lclr_noExecuteOnDisabledRecords = 'False'
					OR
				   (
						@lclr_noExecuteOnDisabledRecords = 'True'
							AND
						@bitDisabled4Rules = 'False'
				   )

				BEGIN






				-- se recorre el cursor de reglas de actualización hasta el fin del mismo


					-- -------------------------------------------------------------
					-- Precio de Costo Actualizado
					-- -------------------------------------------------------------
					IF @bitIs4PriceList = 'False'
						BEGIN
							SELECT	@coslis_price	= IsNull(ticl.coslis_price,0),
									@coslis_priceAW = IsNull(ticl.coslis_price_aw,0),
									@coslis_curr_id	= IsNull(ticl.curr_id,	(SELECT ti.curr_id
				               													FROM tbItem ti WITH (NOLOCK)
				               	                      							WHERE	ti.comp_id = @comp_id
				               	                      								AND ti.item_id = @item_id))	,
									@coslis_pricePreLast	= ISNULL(ticl.coslis_price_PreLastUpdate,0),
									@curr_id_PreLast		= ticl.curr_id_PreLastUpdate
								FROM	tbItemCostList	ticl			WITH (NOLOCK)
								WHERE	ticl.comp_id	= @comp_id
								AND		ticl.coslis_id	= @intListNumber
								AND		ticl.item_id	= @item_id
						END
					ELSE
						BEGIN
							SELECT	@coslis_price	= IsNull(ticl.prli_price,0),
									@coslis_priceAW = IsNull(ticl.prli_price,0),
									@coslis_curr_id	= IsNull(ticl.curr_id,	(SELECT ti.curr_id
				               													FROM tbItem ti WITH (NOLOCK)
				               	                      							WHERE	ti.comp_id = @comp_id
				               	                      								AND ti.item_id = @item_id))	,
									@coslis_pricePreLast	= ISNULL(ticl.prli_price_PreLastUpdate,0),
									@curr_id_PreLast		= ticl.curr_id_PreLastUpdate
								FROM tbPriceListItems 	ticl			WITH (NOLOCK)
								WHERE	ticl.comp_id	= @comp_id
								AND		ticl.prli_id	= @intListNumber
								AND		ticl.item_id	= @item_id
						END
					-- -------------------------------------------------------------


					-- -------------------------------------------------------------
					-- sI EL COSTO ACTUALIZADO ES MENOR AL ANTERIOR Y LA REGLA DICE
					-- QUE SOLO ACTUALIZA SI ES MAYOR, PASA DE LARGO.-
					-- -------------------------------------------------------------
					IF (@lOnlyIfPlusCost = 'True'				AND
						@coslis_price	<= @coslis_pricePreLast	AND
						@curr_id_PreLast = @coslis_curr_id)
						BEGIN
							GOTO lbl_LOOP
						END
					-- -------------------------------------------------------------



					-- -------------------------------------------------------------
					-- Calcula cuanto fue el incremento de la lista actualizada para
					-- ser usado en opcion de COMO 6
					-- -------------------------------------------------------------
					DECLARE @decIncrementPercentage AS DECIMAL(38,8)
					DECLARE @decStandardOldPrice	AS DECIMAL(38,6)
					DECLARE @decStandardNewPrice	AS DECIMAL(38,6)
					IF @coslis_pricePreLast <> 0
						BEGIN
							-- Llevo los dos precios a la moneda del viejo para poder sacar el 5 de incremento.
							SET		@decStandardOldPrice	= @coslis_pricePreLast
							SET		@decStandardNewPrice	= dbo.fngetExchange2(@comp_id, @coslis_price, @coslis_curr_id, @curr_id_PreLast, 0,0,0,'False')
							SET		@decIncrementPercentage = ((@decStandardNewPrice / dbo.fnNoZDiv(@decStandardOldPrice)) - 1) * 100
						END
					ELSE
						BEGIN
							SET		@decIncrementPercentage = 0
						END
					-- -------------------------------------------------------------






					-- -------------------------------------------------------------
					--  Precio de Origen
					-- -------------------------------------------------------------
					--1	60	Lista de Costos Actualizada
					--2	60	Lista de Costos Actualizada AW
					--3	60	Lista de Precios
					--4	60	Lista de Costos en Particular
					--5	60	Lista de Costos AW en Particular
					-- -------------------------------------------------------------
					If		@lclr_originListType = 1	-- Lista de Costos Actualizada
						BEGIN
							Set @decOriginalPrice			= @coslis_price
							SET @intOriginalCurrency		= @coslis_curr_id
						END
					ELSE IF @lclr_originListType = 2	-- Lista de Costos Actualizada AW
						BEGIN
							Set @decOriginalPrice			= @coslis_priceAW
							SET @intOriginalCurrency		= @coslis_curr_id
						END
					ELSE IF @lclr_originListType = 3	-- Lista de Precios
						BEGIN
							SELECT	@decOriginalPrice		= IsNull(tpli.prli_price,0),
									@intOriginalCurrency	= IsNull(tpli.curr_id,
																	(SELECT ti.curr_id
				               											FROM tbItem ti					WITH (NOLOCK)
				               	                      					WHERE	ti.comp_id = @comp_id
				               	                      						AND ti.item_id = @item_id)
																	)
								FROM tbPriceListItems tpli		WITH (NOLOCK)
								WHERE	tpli.comp_id = @comp_id
									AND	tpli.prli_id = @lclr_origin_prli_id
									AND tpli.item_id = @item_id
						END
					ELSE IF @lclr_originListType = 4	-- Lista de Costos
						BEGIN
							SELECT	@decOriginalPrice		= IsNull(tpli.coslis_price,0),
									@intOriginalCurrency	= IsNull(tpli.curr_id,
																	(SELECT ti.curr_id
				               											FROM tbItem ti
				               	                      					WHERE	ti.comp_id = @comp_id
				               	                      						AND ti.item_id = @item_id)
																	)
								FROM tbItemCostList  tpli												WITH (NOLOCK)
								WHERE	tpli.comp_id			= @comp_id
									AND	tpli.coslis_id			= @lclr_origin_coslis_id
									AND tpli.item_id			= @item_id
						END
					ELSE IF @lclr_originListType = 5	-- Lista de Costos AW
						BEGIN
							SELECT	@decOriginalPrice		= IsNull(tpli.coslis_price_aw,0),
									@intOriginalCurrency	= IsNull(tpli.curr_id,
																	(SELECT ti.curr_id
				               											FROM tbItem ti
				               	                      					WHERE	ti.comp_id = @comp_id
				               	                      						AND ti.item_id = @item_id)
																	)
								FROM tbItemCostList  tpli												WITH (NOLOCK)
								WHERE	tpli.comp_id			= @comp_id
									AND	tpli.coslis_id			= @lclr_origin_coslis_id
									AND tpli.item_id			= @item_id
						END
					-- -------------------------------------------------------------

					-- -------------------------------------------------------------
					-- Si aplica descuentos por compras definidos en el articulo
					-- al precio de origen (Sea cual sea).
					-- -------------------------------------------------------------
					IF @clr_PurchaseDiscountApplyMethod IN ( 1,3 )
						BEGIN
							-- descuentos
							set @decOriginalPrice = @decOriginalPrice - (@decOriginalPrice * @purOrd_Disc1 / 100)
							set @decOriginalPrice = @decOriginalPrice - (@decOriginalPrice * @purOrd_Disc2 / 100)
							set @decOriginalPrice = @decOriginalPrice - (@decOriginalPrice * @purOrd_Disc3 / 100)
							set @decOriginalPrice = @decOriginalPrice - (@decOriginalPrice * @purOrd_Disc4 / 100)
							-- Recargos
							set @decOriginalPrice = @decOriginalPrice + (@decOriginalPrice * @purOrd_surcharge1 / 100)
							set @decOriginalPrice = @decOriginalPrice + (@decOriginalPrice * @purOrd_surcharge2 / 100)
							set @decOriginalPrice = @decOriginalPrice + (@decOriginalPrice * @purOrd_surcharge3 / 100)
							set @decOriginalPrice = @decOriginalPrice + (@decOriginalPrice * @purOrd_surcharge4 / 100)
						END
					-- Descuentos por Tabla
					IF @clr_PurchaseDiscountApplyMethod IN ( 2,3 )
						BEGIN
							set @decOriginalPrice = @decOriginalPrice * @decCoeficient4Discount4Total
							set @decOriginalPrice = @decOriginalPrice * @decCoeficient4Bonification4Total
							set @decOriginalPrice = @decOriginalPrice * @decCoeficient4BonificationCN4Total
						END
					-- -------------------------------------------------------------





					-- -------------------------------------------------------------
					-- Modo de Actualizacion
					-- -------------------------------------------------------------
					--1	61	Sumar Monto Fijo
					--2	61	Multiplicar por Coeficiente
					--3	61	Dividir por Coeficiente
					--4	61	MARK UP de Articulo
					-- -------------------------------------------------------------
					IF		@lclr_actMethod = 1	-- Sumar Monto Fijo
						BEGIN
							SET @decDestinyPrice = @decOriginalPrice + @lclr_coefficient
						END
					ELSE IF @lclr_actMethod = 2	-- Multiplicar por Coeficiente
						BEGIN
							SET @decDestinyPrice = @decOriginalPrice * @lclr_coefficient
						END
					ELSE IF @lclr_actMethod = 3	-- Dividir por Coeficiente
						BEGIN
							SET @decDestinyPrice = @decOriginalPrice / dbo.fnNoZDiv( @lclr_coefficient )
						END
					ELSE IF @lclr_actMethod = 4	-- MARK UP de Articulo
						BEGIN
							Set @decDestinyPrice = ((@decOriginalPrice *
										CASE
											WHEN convert(int,@lclr_coefficient) = 1 THEN @litem_markup_1
											WHEN convert(int,@lclr_coefficient) = 2 THEN @litem_markup_2
											WHEN convert(int,@lclr_coefficient) = 3 THEN @litem_markup_3
											WHEN convert(int,@lclr_coefficient) = 4 THEN @litem_markup_4
											WHEN convert(int,@lclr_coefficient) = 5 THEN @litem_markup_5
											WHEN convert(int,@lclr_coefficient) = 6 THEN @litem_markup_6
											WHEN convert(int,@lclr_coefficient) = 7 THEN @litem_markup_7
											WHEN convert(int,@lclr_coefficient) = 8 THEN @litem_markup_8
											WHEN convert(int,@lclr_coefficient) = 9 THEN @litem_markup_9
											WHEN convert(int,@lclr_coefficient) = 10 THEN @litem_markup_10
											WHEN convert(int,@lclr_coefficient) = 11 THEN @litem_markup_11
											WHEN convert(int,@lclr_coefficient) = 12 THEN @litem_markup_12
											WHEN convert(int,@lclr_coefficient) = 13 THEN @litem_markup_13
											WHEN convert(int,@lclr_coefficient) = 14 THEN @litem_markup_14
											WHEN convert(int,@lclr_coefficient) = 15 THEN @litem_markup_15
											WHEN convert(int,@lclr_coefficient) = 16 THEN @litem_markup_16
										END /100 )) + @decOriginalPrice
						END
					ELSE IF @lclr_actMethod = 5	-- Aplicar un Descuento en %
						BEGIN
							SET @decDestinyPrice = @decOriginalPrice - (@decOriginalPrice * @lclr_coefficient / 100 )
						END
					ELSE IF @lclr_actMethod = 6 -- % de actualizacion de la lista ACTUALIZADA
						BEGIN
							SET @decDestinyPrice = @decOriginalPrice + (@decOriginalPrice * @decIncrementPercentage / 100 )
						END
					-- -------------------------------------------------------------

					-- -------------------------------------------------------------
					-- Lista de Precios de Destino, Chequear Existencia del precio
					-- de no existir crearlo en CERO con la moneda del Item.-
					-- -------------------------------------------------------------
					--1	62	Lista de Precios
					--2	62	Lista de Costos
					--3	62	Lista de Costos AW
					-- -------------------------------------------------------------
					IF		@lclr_destinyListType = 1 -- Lista de Precios
						BEGIN
							IF	@clr_disableDestinyCreation = 'False' AND
								NOT EXISTS (	SELECT TOP 1  1
												FROM tbPriceListItems tpli	WITH (NOLOCK)
				               					WHERE	tpli.comp_id = @comp_id
				               						AND tpli.prli_id = @lclr_destiny_prli_id
													AND tpli.item_id = @item_id)
								BEGIN
									INSERT INTO tbPriceListItems
									(
										comp_id,
										prli_id,
										item_id,
										prli_price,
										curr_id,
										bra_id,
										prli_cd,
										prli_lastModuleUpdate
									)
									VALUES
									(
										@comp_id,
										@lclr_destiny_prli_id,
										@item_id,
										0,
										@litem_currId,
										NULL,
										GETDATE(),
										20
									)
								END
						END
					ELSE IF		@lclr_destinyListType = 2 OR @lclr_destinyListType = 3 -- Costos o Costos AW
						BEGIN
							IF	@clr_disableDestinyCreation = 'False' AND
								NOT EXISTS (	SELECT TOP 1  1
				               				FROM tbItemCostList tpli	WITH (NOLOCK)
				               					WHERE	tpli.comp_id	= @comp_id
				               						AND tpli.coslis_id	= @lclr_destiny_coslis_id
													AND tpli.item_id	= @item_id)
								BEGIN

									INSERT INTO tbItemCostList
									(
										comp_id,
										coslis_id,
										item_id,
										coslis_price,
										coslis_price_aw,
										curr_id,
										coslis_cd
									)
									VALUES
									(
										@comp_id,
										@lclr_destiny_coslis_id,
										@item_id,
										0,
										0,
										@litem_currId,
										GETDATE()
									)

			--						INSERT INTO tbPriceListItems			MOS: 06-2011
			--						(
			--							comp_id,
			--							prli_id,
			--							item_id,
			--							prli_price,
			--							curr_id,
			--							bra_id,
			--							prli_cd
			--						)
			--						VALUES
			--						(
			--							@comp_id,
			--							@lclr_destiny_coslis_id,
			--							@item_id,
			--							0,
			--							@litem_currId,
			--							NULL,
			--							GETDATE()
			--						)
								END
						END
					-- -------------------------------------------------------------


					-- -------------------------------------------------------------
					-- Obtiene la Lista Actual de Costos
					--1	62	Lista de Precios
					--2	62	Lista de Costos
					--3	62	Lista de Costos AW
					-- -------------------------------------------------------------
					IF		@lclr_destinyListType = 1 -- Lista de Precios
						BEGIN

							SELECT @intDestinyActualCurrency = tpli.curr_id
								FROM tbPriceListItems tpli						WITH (NOLOCK)
									WHERE	tpli.comp_id	= @comp_id
										AND tpli.prli_id	= @lclr_destiny_prli_id
										AND tpli.item_id	= @item_id

						END
					ELSE IF		@lclr_destinyListType = 2 OR @lclr_destinyListType = 3 -- Costos o Costos AW
						BEGIN

							SELECT @intDestinyActualCurrency = tpli.curr_id
								FROM tbItemCostList tpli						WITH (NOLOCK)
									WHERE	tpli.comp_id	= @comp_id
										AND tpli.coslis_id	= @lclr_destiny_coslis_id
										AND tpli.item_id	= @item_id
						END
					-- -------------------------------------------------------------

					-- -------------------------------------------------------------
					-- Setea el tipo de moneda de destino
					-- -------------------------------------------------------------
					IF @lclr_DestCurrIdIdemOrigin = 'True'
						BEGIN
							SET @intDestinyCurrency = @intOriginalCurrency
						END
					ELSE
						BEGIN
							SET @intDestinyCurrency = @intDestinyActualCurrency
						END
					-- -------------------------------------------------------------


					-- -------------------------------------------------------------
					-- Si la moneda de origen es diferente a la de destino
					-- hace el tipo de cambio correspondiente
					-- -------------------------------------------------------------
						IF @intOriginalCurrency <> @intDestinyCurrency
							BEGIN
								set @decDestinyPrice = dbo.fnGetExchange2(@comp_id,
																		  @decDestinyPrice,
																		  @intOriginalCurrency,
																		  @intDestinyCurrency,
																		  0,
																		  0,
																		  0,
																		  'False')
							END
					-- -------------------------------------------------------------


					--		-- -------------------------------------------------------------
					--		-- Por si hay algun error con el precio
					--		-- -------------------------------------------------------------
					--		SET @decDestinyPrice	= ISNULL(@decDestinyPrice,0)
					--		SET @intDestinyCurrency = ISNULL(@intDestinyCurrency,
					--													(SELECT ti.curr_id
					--				               								FROM tbItem ti
					--				               	                      		WHERE	ti.comp_id = @comp_id
					--				               	                      			AND ti.item_id = @item_id)
					--										)
					--		-- -------------------------------------------------------------


					-- -------------------------------------------------------------
					-- Redondea el Precio
					-- -------------------------------------------------------------
					SET @decDestinyPrice = ROUND(@decDestinyPrice,@lclr_round2Decimals)
					-- -------------------------------------------------------------


					-- -------------------------------------------------------------
					-- Actualiza la lista de Destino
					--1	62	Lista de Precios
					--2	62	Lista de Costos
					--3	62	Lista de Costos AW
					-- -------------------------------------------------------------


					-- Se puso por los forros de Marstech que pusieron un precio GIGANTE y me hicieron perder toda la reputa tarde buscando esta mierda@!@@@@
					IF @decDestinyPrice > 99999999999999
						BEGIN
							SET @decDestinyPrice = 99999999999999
						END





					-- -------------------------------------------------------------
					-- MOS: 08-2023
					-- Si se redondea a importe FINAL, se puede poner a multiplo
					-- de que se debe redondear.
					-- Debo sumar el impuesto, redondear y luego restar el impuesto
					-- -------------------------------------------------------------
					IF	@clr_roundFinalPrice		= 'True' AND
						@clr_roundFinalPrice_Option > 0		 AND
						@decDestinyPrice		    > @clr_roundFinalPrice_From
						BEGIN

							-- Sumo Impuestos
							DECLARE @decDestinyPriceTMP DECIMAL(38,6) = @decDestinyPrice
							SELECT  @decDestinyPriceTMP = @decDestinyPriceTMP + (@decDestinyPriceTMP * ttn.tax_percentage / 100)
								FROM vwItemTaxesOnlyOneIvaTax	AS vitooit		WITH (NOLOCK)
								INNER JOIN tbTaxName			AS ttn			WITH (NOLOCK)
									ON	ttn.comp_id = vitooit.comp_id AND
										ttn.tax_id	= vitooit.tax_id
								WHERE	vitooit.comp_id = @comp_id AND
										vitooit.item_id = @item_id

							-- Redondeo el precio con los impuestos incluidos
							SET		@decDestinyPriceTMP = dbo.fnRoundByMultiple(@decDestinyPriceTMP,@clr_roundFinalPrice_Multiple,@clr_roundFinalPrice_Option)

							-- Resto los impuestos.
							SELECT  @decDestinyPriceTMP = @decDestinyPriceTMP / dbo.fnNoZDiv( 1+(ttn.tax_percentage / 100))
								FROM vwItemTaxesOnlyOneIvaTax	AS vitooit		WITH (NOLOCK)
								INNER JOIN tbTaxName			AS ttn			WITH (NOLOCK)
									ON	ttn.comp_id = vitooit.comp_id AND
										ttn.tax_id	= vitooit.tax_id
								WHERE	vitooit.comp_id = @comp_id AND
										vitooit.item_id = @item_id

							SET @decDestinyPrice = @decDestinyPriceTMP

						END
					-- -------------------------------------------------------------




					-- -------------------------------------------------------------
					-- MOS: 01-2020
					-- Esto se hizo para a&c para que si en la misma DB tienen inscriptos y monotributistas,
					-- la lista monotributo tenga el precio FINAL ya incluido
					-- -------------------------------------------------------------
					IF @clr_sumTaxes2Destiny = 'True'
						BEGIN
							SELECT  @decDestinyPrice = @decDestinyPrice + (@decDestinyPrice * ttn.tax_percentage / 100)
								FROM vwItemTaxesOnlyOneIvaTax	AS vitooit		WITH (NOLOCK)
								INNER JOIN tbTaxName			AS ttn			WITH (NOLOCK)
									ON	ttn.comp_id = vitooit.comp_id AND
										ttn.tax_id	= vitooit.tax_id
								WHERE	vitooit.comp_id = @comp_id AND
										vitooit.item_id = @item_id
						END
					-- -------------------------------------------------------------




					IF NOT @decDestinyPrice IS NULL
						BEGIN

							IF		@lclr_destinyListType = 1 -- Lista de Precios
								BEGIN

									UPDATE tbPriceListItems	WITH (ROWLOCK)
										SET
											prli_price				= @decDestinyPrice,
											curr_id					= @intDestinyCurrency,
											prli_cd					= GETDATE(),
											prli_lastModuleUpdate	= 20,
											prli_lastRuleUpdate		= GETDATE()
										WHERE	comp_id	= @comp_id
											AND prli_id	= @lclr_destiny_prli_id
											AND item_id	= @item_id


									-- Actualiza Precios de Padres de COMBOS
									EXEC spCostlistActualizationRules_SetComboPrices @comp_id,
																					 @lclr_destiny_prli_id,
																					 @item_id,
																					 NULL


								END
							ELSE IF		@lclr_destinyListType = 2 -- Costos
								BEGIN

									UPDATE tbItemCostList	WITH (ROWLOCK)
										SET
											coslis_price	= @decDestinyPrice,
											curr_id			= @intDestinyCurrency,
											coslis_cd		= GETDATE()

										WHERE	comp_id		= @comp_id
											AND coslis_id	= @lclr_destiny_coslis_id
											AND item_id		= @item_id

									EXEC spCostlistActualizationRules_SetComboCosts  @comp_id,
																					 @item_id,
																					 @lclr_destiny_coslis_id,
																					 NULL


								END
							ELSE IF		@lclr_destinyListType = 3 -- Costos AW
								BEGIN

									UPDATE tbItemCostList	WITH (ROWLOCK)
										SET
											coslis_price_AW	= @decDestinyPrice,
											curr_id			= @intDestinyCurrency,
											coslis_cd		= GETDATE()

										WHERE	comp_id		= @comp_id
											AND coslis_id	= @lclr_destiny_coslis_id
											AND item_id		= @item_id

									EXEC spCostlistActualizationRules_SetComboCosts  @comp_id,
																					 @item_id,
																					 @lclr_destiny_coslis_id,
																					 NULL

								END
						END
					-- -------------------------------------------------------------

				lbl_LOOP:

				-- ---------------------------------------------------------


			END
			SET @intCounter = @intCounter + 1
		END


		lbl_EXIT:





END
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spCostlistActualizationRules_SetComboCosts]   --spItemCostList_sumCOMBOCosts
	@comp_id AS INT,
	@item_id AS INT,
	@coslis_id  AS INT,
	@user_id	AS INT


AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;




	-- ----------------------------------------------------------------------------------------------
	-- Si tiene Articulos Asociados pone el costo del KIT como la suma de los costos de las partes.
	-- ----------------------------------------------------------------------------------------------
	IF EXISTS (	SELECT TOP 1 1
					FROM tbItemAssociation tia	WITH (NOLOCK)
	           			WHERE	tia.comp_id		= @comp_id
	           				AND tia.item_id_1	= @item_id)



		BEGIN

			DECLARE @curItemID	AS INT  -- estaba ANTES del Begin  MOS: 02-2020
			DECLARE @curr_id	AS INT



			DECLARE curItemAssociation CURSOR LOCAL  FAST_FORWARD FOR
												SELECT DISTINCT tia.item_id
													FROM	tbItemAssociation tia		WITH (NOLOCK)
													WHERE	tia.comp_id		= @comp_id
														AND tia.item_id_1	= @item_id

			OPEN curItemAssociation

			FETCH NEXT FROM curItemAssociation INTO @curItemID




			WHILE @@FETCH_STATUS = 0
				BEGIN
					-- Aca calcular el costo del @curItemID en base a los costos de las partes (tanto el costo como el PPP)
					-- para la @coslis_id informada



					-- recuperamos la moneda del artículo "padre"
					SELECT	@curr_id	= ti.curr_id
						FROM	tbItem						ti		WITH (NOLOCK)
						WHERE	ti.comp_id	= @comp_id
						AND		ti.item_id	= @curItemID




					-- si no existe el "padre" en la lista de costos destino, se lo incluye
					IF NOT EXISTS	(
									SELECT TOP 1 1
										FROM	tbItemCostList		ticl			WITH (NOLOCK)
										WHERE	ticl.comp_id	= @comp_id
										AND		ticl.coslis_id	= @coslis_id
										AND		ticl.item_id	= @curItemID
									)
						BEGIN



							-- insertamos el registro en la lista de costos del artículo "padre"
							INSERT INTO tbItemCostList		WITH (ROWLOCK)
							(
								comp_id,
								coslis_id,
								item_id,
								coslis_price,
								coslis_price_aw,
								curr_id,
								coslis_cd,
								coslis_price_Original,
								coslis_price_Disc1,
								coslis_price_Disc2,
								coslis_price_Disc3,
								coslis_price_Disc4,
								user_id_lastUpdate
							)
							VALUES
							(
								@comp_id,
								@coslis_id,
								@curItemID,
								0,
								0,
								@curr_id,
								GETDATE(),
								0,
								0,
								0,
								0,
								0,
								@user_id
							)

						END




					-- calculamos el precio de costo y costo AW del artículo "padre" en base a la suma de los costos/costos AW
					-- de los artículos que lo componen
					DECLARE @coslis_price		DECIMAL(19,5),
							@coslis_price_aw	DECIMAL(19,5)


					SELECT	@coslis_price		=	SUM(tic.iasso_qty * dbo.fnGetExchange2(	@comp_id,
																							ticl2.coslis_price,
																							ticl2.curr_id, ticl.curr_id,
																							ticl2.curr_id, ticl.curr_id,
																							0, 'false')),
							@coslis_price_aw	=	SUM(tic.iasso_qty * dbo.fnGetExchange2(	@comp_id,
																							ticl2.coslis_price_aw,
																							ticl2.curr_id, ticl.curr_id,
																							ticl2.curr_id, ticl.curr_id,
																							0, 'false'))

					FROM	tbItemCostList						ticl				WITH (NOLOCK)

							INNER JOIN tbItemAssociation	 	tic					WITH (NOLOCK)
							ON	tic.comp_id		= ticl.comp_id
							AND tic.item_id		= ticl.item_id

							INNER JOIN tbItemCostList			ticl2				WITH (NOLOCK)
							ON	ticl2.comp_id	= ticl.comp_id
							AND ticl2.coslis_id = @coslis_id
							AND ticl2.item_id	= tic.item_id_1

					WHERE	ticl.comp_id		= @comp_id
					AND		ticl.coslis_id		= @coslis_id
					AND		ticl.item_id		= @curItemID





					--actualizamos los costos/costos AW del artículo "padre" con los valores calculados en el paso anterior
					UPDATE	tbItemCostList		WITH (ROWLOCK)
						SET		coslis_price		= @coslis_price,
								coslis_price_aw		= @coslis_price_aw,
								coslis_cd			= GETDATE(),
								user_id_lastUpdate  = @user_id,
								coslis_lastUpdate	= GETDATE()

						WHERE	comp_id		= @comp_id
						AND		coslis_id	= @coslis_id
						AND		item_id		= @curItemID






					FETCH NEXT FROM curItemAssociation INTO @curItemID

				END


				CLOSE		curItemAssociation
				DEALLOCATE	curItemAssociation

		END
	-- ----------------------------------------------------------------------------------------------





END
GO



CREATE PROCEDURE [dbo].[spCostlistActualizationRules_SetComboPrices]
(
	@lComp_id			AS INT,
	@lPrli_id			AS	INT,
	@lItem_id			AS	INT,
	@lBra_id			AS BIT
)
AS


BEGIN

	SET NOCOUNT ON



	-- -----------------------------------------------------------------------------
	-- Si es un KIT y el principal SUMA el precio de las partes, se actualiza
	-- cuando se actualiza una parte
	-- -----------------------------------------------------------------------------
	IF EXISTS (	SELECT top 1 1
					FROM	tbItemAssociation tia	WITH (NOLOCK)
					INNER JOIN tbitem ti			WITH (NOLOCK)		-- KIT
						ON	ti.comp_id = tia.comp_id AND
							ti.item_id = tia.item_id
					WHERE	tia.comp_id		= @lComp_id		AND
							tia.item_id_1	= @lItem_id		AND
							ti.item_ifHasItemAssociationSumPrices = 1)
    BEGIN

    	DECLARE @intItemIdCombo											AS INT
		DECLARE @item_isForAssociation_discountPercentage4PriceListSUM	AS DECIMAL(15,4)
    	--declaración de cursor para recuperar los items hijos y los coeficientes
    	DECLARE cursor_childs4ItemAssociation CURSOR LOCAL FAST_FORWARD FOR
    		SELECT	DISTINCT  -- MOS 08-2021 x Bucle infinito zmotos x tener mas de un MISMO articulo relacionado a un combo con reglas de act de precios.
    				tia.item_id,
    				ti.item_isForAssociation_discountPercentage4PriceListSUM
				FROM	tbItemAssociation tia			WITH (NOLOCK)
				INNER JOIN tbitem ti					WITH (NOLOCK)	-- KIT
					ON	ti.comp_id		= tia.comp_id AND
						ti.item_id		= tia.item_id
				WHERE	tia.comp_id		= @lComp_id		AND
						tia.item_id_1	= @lItem_id		AND
						ti.item_ifHasItemAssociationSumPrices = 1

    	OPEN	cursor_childs4ItemAssociation

    	FETCH	cursor_childs4ItemAssociation
    		INTO	@intItemIdCombo,
    				@item_isForAssociation_discountPercentage4PriceListSUM

		DECLARE @intCurrID4KIT AS INT
		DECLARE @decPrice4KIT  AS DECIMAL(29,6)
		DECLARE @bitFoundKIT   AS BIT

    	WHILE @@FETCH_STATUS = 0
    	BEGIN


			SET @intCurrID4KIT	= NULL
			SET @decPrice4KIT	= 0
			SET @bitFoundKIT    = 'False'

			-- Obtiene la moneda de la lista de destino
			SELECT	@intCurrID4KIT = ISNULL(ISNULL(tpli.curr_id,ti.curr_id),1),
					@bitFoundKIT   = 'True'
			   FROM tbPriceListItems tpli					WITH (NOLOCK)
			   INNER JOIN tbItem ti							WITH (NOLOCK)
			   ON	ti.comp_id = tpli.comp_id and
					ti.item_id = tpli.item_id
			   WHERE tpli.comp_id  = @lComp_id	AND
					 tpli.prli_id  = @lPrli_id	AND
					 tpli.item_id  = @intItemIdCombo

			-- Si no encuentra la moneda pone la del articulo.
			IF @intCurrID4KIT IS NULL
				BEGIN
					SELECT @intCurrID4KIT = ISNULL(ti.curr_id,1)
					FROM tbItem ti							WITH (NOLOCK)
					WHERE	ti.comp_id = @lComp_id AND
							ti.item_id = @intItemIdCombo
				END

			-- calcula el precio del KIT en base a las partes
			SELECT @decPrice4KIT =
					SUM(
						dbo.fnGetExchange2(@lComp_id,ISNULL(tpli.prli_price,0) * ISNULL(tia.iasso_qty,1), tpli.curr_id, @intCurrID4KIT, 0, 0, 0, 'False')	*
						CASE	-- MOS 06-2020: Descuenta la SUMA de los descuentos de la PARTE y del COMBO
							WHEN (tia.itema_discountPercentage4PriceListSUM + @item_isForAssociation_discountPercentage4PriceListSUM) = 0 THEN		1
							ELSE														(1-((tia.itema_discountPercentage4PriceListSUM + @item_isForAssociation_discountPercentage4PriceListSUM) / 100))
						END
					   )
				FROM	tbItemAssociation tia				WITH (NOLOCK)
				INNER JOIN tbPriceListItems tpli			WITH (NOLOCK)
					ON	tpli.comp_id = tia.comp_id	AND
						tpli.prli_id = @lPrli_id	AND
						tpli.item_id = tia.item_id_1
				WHERE	tia.comp_id  = @lComp_id	AND
						tia.item_id  = @intItemIdCombo


			-- x si pusieron cualquier MIERDA en las cantidades
			IF @decPrice4KIT > 999999999999
				BEGIN
					SET @decPrice4KIT = 999999999999
				END


			IF	ISNULL(@decPrice4KIT,0)		<> 0	AND
				ISNULL(@intCurrID4KIT,0)	<> 0

				BEGIN


    				--verificación para saber si el registro a procesar ya existe en la lista de precios
    				IF @bitFoundKIT = 'True'
    					BEGIN




							--si ya existe se ejecuta un update del item hijo aplicando el coeficiente
							--multiplicado por la el precio de venta del padre
							UPDATE tbPriceListItems		WITH (ROWLOCK)
								SET		prli_price	= @decPrice4KIT,
										curr_id		= @intCurrID4KIT,
										bra_id		= @lBra_id,
										prli_lastModuleUpdate = 30 -- 20 MOS 2-05-2019 para que no entre en bucle infinito
								WHERE	comp_id		= @lComp_id
								AND		item_id		= @intItemIdCombo
								AND		prli_id		= @lPrli_id

    					END
    				ELSE
    					BEGIN

							--si no existe se ejecuta un insert del item hijo aplicando el coeficiente
							--multiplicado por la el precio de venta del padre
							INSERT INTO tbPriceListItems	WITH (ROWLOCK)
								(		comp_id,
										prli_id,
										item_id,
										prli_price,
										curr_id,
										bra_id,
										prli_cd,
										prli_lastModuleUpdate		)
							VALUES
    							(		@lComp_id,
    									@lPrli_id,
    									@intItemIdCombo,
    									@decPrice4KIT,
    									@intCurrID4KIT,
    									@lBra_id,
    									GETDATE(),
    									20)

    					END

				END


    		FETCH	cursor_childs4ItemAssociation
    			INTO	@intItemIdCombo,
    					@item_isForAssociation_discountPercentage4PriceListSUM

    	END

    	CLOSE		cursor_childs4ItemAssociation
    	DEALLOCATE	cursor_childs4ItemAssociation



    END
	-- -----------------------------------------------------------------------------





END

GO



-- NO SE PORQUE DICE NEW.!!!  NO USAR ESTO!!!!!!!!

CREATE PROCEDURE [dbo].[spCostlistActualizationRulesNew]
(
	@comp_id		INT,
	@coslis_id		INT,
	@item_id		INT
)
AS
SET NOCOUNT ON


/*
DECLARE		@comp_id		INT,
			@coslis_id		INT,
			@item_id		INT

SELECT		@comp_id		= 1,
			@coslis_id		= 1,
			@item_id		= 17
*/



DECLARE @origin_price					DECIMAL(18,6),
		@origin_curr_id					INT,
		@destiny_price					DECIMAL(18,6),
		@destiny_curr_id				INT


--declare para el cursor
DECLARE	@lclr_id						INT,
		@lclr_coslis_id_Updated			INT,
		@lclr_originListType			INT,
		@lclr_DestCurrIdIdemOrigin		BIT,
		@lclr_actMethod					INT,
		@lclr_origin_coslis_id			INT,
		@lclr_origin_prli_id			INT,
		@lclr_order						INT,
		@lclr_round2Decimals			INT,
		@lcat_id						INT,
		@lsubcat_id						INT,
		@lbrand_id						INT,
		@lclr_destinyListType			INT,
		@lclr_destiny_coslis_id			INT,
		@lclr_destiny_prli_id			INT,
		@lclr_coefficient				DECIMAL(19,4),
		@litem_markup_1					DECIMAL(19,5),
		@litem_markup_2					DECIMAL(19,5),
		@litem_markup_3					DECIMAL(19,5),
		@litem_markup_4					DECIMAL(19,5),
		@litem_markup_5					DECIMAL(19,5),
		@litem_markup_6					DECIMAL(19,5),
		@litem_markup_7					DECIMAL(19,5),
		@litem_markup_8					DECIMAL(19,5)




--cursor para recorrer las reglas de actualización
declare cursor_ClAR_items cursor for

SELECT	ticlar.clr_id,
		ticlar.clr_coslis_id_Updated,
		ticlar.clr_originListType,
		ticlar.clr_DestCurrIdIdemOrigin,
		ticlar.clr_actMethod,
		ticlar.clr_origin_coslis_id,
		ticlar.clr_origin_prli_id,
		ticlar.clr_order,
		ticlar.clr_round2Decimals,
		ticlar.cat_id,
		ticlar.subcat_id,
		ticlar.brand_id,
		ticlar.clr_destinyListType,
		ticlar.clr_destiny_coslis_id,
		ticlar.clr_destiny_prli_id,
		ticlar.clr_coefficient,
		ti.item_markup_1, ti.item_markup_2,
		ti.item_markup_3, ti.item_markup_4,
		ti.item_markup_5, ti.item_markup_6,
		ti.item_markup_7, ti.item_markup_8

FROM	tbItemCostListActualizationRules ticlar
		INNER JOIN		tbItem ti
		ON	ti.comp_id	= ticlar.comp_id
		AND	ti.item_id	= @item_id


WHERE	ticlar.comp_id					= @comp_id
AND		ticlar.clr_coslis_id_Updated	= @coslis_id

AND     isnull(ticlar.clr_disabled,'false') = 'false'

AND		(ticlar.cat_id		is null	or ticlar.cat_id	= ti.cat_id )
AND		(ticlar.subcat_id	is null	or ticlar.subcat_id = ti.subcat_id )
AND		(ticlar.brand_id	is null	or ticlar.brand_id	= ti.brand_id)

ORDER BY ticlar.clr_order




OPEN cursor_ClAR_items

-- lectura anticipada del cursor
FETCH 	cursor_ClAR_items
INTO	@lclr_id,
		@lclr_coslis_id_Updated,
		@lclr_originListType,
		@lclr_DestCurrIdIdemOrigin,
		@lclr_actMethod,
		@lclr_origin_coslis_id,
		@lclr_origin_prli_id,
		@lclr_order,
		@lclr_round2Decimals,
		@lcat_id,
		@lsubcat_id,
		@lbrand_id,
		@lclr_destinyListType,
		@lclr_destiny_coslis_id,
		@lclr_destiny_prli_id,
		@lclr_coefficient,
		@litem_markup_1,
		@litem_markup_2,
		@litem_markup_3,
		@litem_markup_4,
		@litem_markup_5,
		@litem_markup_6,
		@litem_markup_7,
		@litem_markup_8




-- se recorre el cursor de reglas de actualización hasta el fin del mismo
WHILE @@fetch_status = 0
BEGIN




	/************************************************************************************************/
	/* recuperamos datos de la lista de origen seleccionada en la regla								*/
	IF @lclr_originListType = '1'	-- Lista Origen		: Lista de Costos Actualizada
		SELECT	@origin_price		= ticl.coslis_price,
				@origin_curr_id		= ticl.curr_id
		FROM	tbItemCostList		ticl
		WHERE	ticl.comp_id		= @comp_id
		AND		ticl.coslis_id		= @coslis_id
		AND		ticl.item_id		= @item_id
	ELSE

	IF @lclr_originListType = '2'	-- Lista Origen		: Lista de Costos Actualizada AW
		SELECT	@origin_price		= ticl.coslis_price_aw,
				@origin_curr_id		= ticl.curr_id
		FROM	tbItemCostList		ticl
		WHERE	ticl.comp_id		= @comp_id
		AND		ticl.coslis_id		= @coslis_id
		AND		ticl.item_id		= @item_id
	ELSE

	IF @lclr_originListType = '3'	-- Lista Origen		: Lista de Ventas
		SELECT	@origin_price		= tpli.prli_price,
				@origin_curr_id		= tpli.curr_id
		FROM	tbPriceListItems	tpli
		WHERE	tpli.comp_id		= @comp_id
		AND		tpli.prli_id		= @lclr_origin_prli_id
		AND		tpli.item_id		= @item_id
	ELSE

	IF @lclr_originListType = '4'	-- Lista Origen		: Lista de Costos en Particular
		SELECT	@origin_price		= ticl.coslis_price,
				@origin_curr_id		= ticl.curr_id
		FROM	tbItemCostList		ticl
		WHERE	ticl.comp_id		= @comp_id
		AND		ticl.coslis_id		= @lclr_origin_coslis_id
		AND		ticl.item_id		= @item_id
	ELSE

	IF @lclr_originListType = '5'	-- Lista Origen		: Lista de Costos AW en Particular
		SELECT	@origin_price		= ticl.coslis_price_aw,
				@origin_curr_id		= ticl.curr_id
		FROM	tbItemCostList		ticl
		WHERE	ticl.comp_id		= @comp_id
		AND		ticl.coslis_id		= @lclr_origin_coslis_id
		AND		ticl.item_id		= @item_id
	/************************************************************************************************/




	/************************************************************************************************/
	/* calculamos el precio destino en base al método de actualización seleccionado en la regla		*/
	IF @lclr_actMethod = '1' 	-- Método de Actualización	: 1- Sumar Monto Fijo
		SELECT	@destiny_price	= 	@origin_price + @lclr_coefficient
	ELSE

	IF @lclr_actMethod = '2'	-- Método de Actualización	: 2- Multiplicar por Coeficiente
		SELECT 	@destiny_price	= 	@origin_price * @lclr_coefficient
	ELSE

	IF @lclr_actMethod = '3'	-- Método de Actualización	: 3- Dividir por Coeficiente
		SELECT 	@destiny_price	=	@origin_price / @lclr_coefficient
	ELSE

	IF @lclr_actMethod = '4'	-- Método de Actualización	: 4- Porcentaje del Archivo de Articulos
		SELECT 	@destiny_price	=	@origin_price + ( @origin_price *
											CASE
												WHEN convert(int,@lclr_coefficient) = 1 THEN @litem_markup_1
												WHEN convert(int,@lclr_coefficient) = 2 THEN @litem_markup_2
												WHEN convert(int,@lclr_coefficient) = 3 THEN @litem_markup_3
												WHEN convert(int,@lclr_coefficient) = 4 THEN @litem_markup_4
												WHEN convert(int,@lclr_coefficient) = 5 THEN @litem_markup_5
												WHEN convert(int,@lclr_coefficient) = 6 THEN @litem_markup_6
												WHEN convert(int,@lclr_coefficient) = 7 THEN @litem_markup_7
												WHEN convert(int,@lclr_coefficient) = 8 THEN @litem_markup_8
											END /100 )
	/************************************************************************************************/




	/************************************************************************************************/
	/* actualizamos la lista destino seleccionada en la regla en base a los datos de la lista origen*/
	/* y al método de actualización calculado en los pasos anteriores								*/
	IF @lclr_destinyListType = '1'	-- Lista Destino: 1- Lista de Ventas
	BEGIN
		UPDATE	tbpricelistitems
		SET		prli_price		= dbo.fnGetExchange2(
									@comp_id,
									@destiny_price,
									curr_id,
									CASE WHEN ISNULL(@lclr_DestCurrIdIdemOrigin,'false')='true' THEN @origin_curr_id ELSE curr_id END,
									curr_id, curr_id, 1, 'false'),
				curr_id			= CASE WHEN	ISNULL(@lclr_DestCurrIdIdemOrigin,'false')='true' THEN @origin_curr_id ELSE curr_id END
		WHERE	comp_id			= @comp_id
		AND		prli_id			= @lclr_destiny_prli_id
		AND		item_id			= @item_id

		IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO tbPriceListItems
			(		comp_id,
					prli_id,
					item_id,
					prli_price,
					curr_id,
					bra_id,
					prli_cd)
			VALUES (@comp_id,
					@lclr_destiny_prli_id,
					@item_id,
					@destiny_price,
					@origin_curr_id,
					NULL,
					GETDATE())
		END
	END
	ELSE

	IF @lclr_destinyListType = '2'	-- Lista Destino: 2- Lista de Costos
	BEGIN
		UPDATE	tbItemCostList
		SET		coslis_price	= dbo.fnGetExchange2(
									@comp_id,
									@destiny_price,
									curr_id,
									CASE WHEN ISNULL(@lclr_DestCurrIdIdemOrigin,'false')='true' THEN @origin_curr_id ELSE curr_id END,
									curr_id, curr_id, 1, 'false'),
				curr_id			= CASE WHEN	ISNULL(@lclr_DestCurrIdIdemOrigin,'false')='true' THEN @origin_curr_id ELSE curr_id END
		WHERE	comp_id			= @comp_id
		AND		coslis_id		= @lclr_destiny_coslis_id
		AND		item_id			= @item_id

		IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO tbItemCostList
			(		comp_id,
					coslis_id,
					item_id,
					coslis_price,
					coslis_price_aw,
					curr_id,
					coslis_cd)
			VALUES (@comp_id,
					@lclr_destiny_coslis_id,
					@item_id,
					@destiny_price,
					@destiny_price,
					@origin_curr_id,
					GETDATE())
		END
	END
	ELSE

	IF @lclr_destinyListType = '3'	-- Lista Destino: 3- Lista de Costos promedio ponderado
	BEGIN
		UPDATE	tbItemCostList
		SET		coslis_price_aw	= dbo.fnGetExchange2(
									@comp_id,
									@destiny_price,
									curr_id,
									CASE WHEN ISNULL(@lclr_DestCurrIdIdemOrigin,'false')='true' THEN @origin_curr_id ELSE curr_id END,
									curr_id, curr_id, 1, 'false'),
				curr_id			= CASE WHEN	ISNULL(@lclr_DestCurrIdIdemOrigin,'false')='true' THEN @origin_curr_id ELSE curr_id END
		WHERE	comp_id			= @comp_id
		AND		coslis_id		= @lclr_destiny_coslis_id
		AND		item_id			= @item_id

		IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO tbItemCostList
			(		comp_id,
					coslis_id,
					item_id,
					coslis_price,
					coslis_price_aw,
					curr_id,
					coslis_cd)
			VALUES (@comp_id,
					@lclr_destiny_coslis_id,
					@item_id,
					@destiny_price,
					@destiny_price,
					@origin_curr_id,
					GETDATE())
		END
	END
	/************************************************************************************************/




	-- próxima lectura del cursor
	FETCH 	cursor_ClAR_items
	INTO 	@lclr_id,
			@lclr_coslis_id_Updated,
			@lclr_originListType,
			@lclr_DestCurrIdIdemOrigin,
			@lclr_actMethod,
			@lclr_origin_coslis_id,
			@lclr_origin_prli_id,
			@lclr_order,
			@lclr_round2Decimals,
			@lcat_id,
			@lsubcat_id,
			@lbrand_id,
			@lclr_destinyListType,
			@lclr_destiny_coslis_id,
			@lclr_destiny_prli_id,
			@lclr_coefficient,
			@litem_markup_1,
			@litem_markup_2,
			@litem_markup_3,
			@litem_markup_4,
			@litem_markup_5,
			@litem_markup_6,
			@litem_markup_7,
			@litem_markup_8

END
--fin loop del cursor


CLOSE		cursor_ClAR_items
DEALLOCATE  cursor_ClAR_items
GO



CREATE procedure [dbo].[spCostLists_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@option				int,
		@item_desc			varchar(200),
		@coslis_id1			int,
		@coslis_id2			int,
		@coslis_id3			int,
		@pres_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@bra_id				int,
		@curr_id			int,
		@byor_id			INT,
		@item_disabled		INT,
		@supp_id			INT,
		@guid				VARCHAR(50), --CF DE ITEMS
		@intBranch4Lang		int
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		--------------------------------------------------------
		--testing--
		--------------------------------------------------------
		/*

		DECLARE @comp_id			int,
				@lang_id			int,
				@page_id			int,

				@option				int,
				@item_desc			varchar(200),
				@coslis_id1			int,
				@coslis_id2			int,
				@coslis_id3			int,
				@pres_id			int,
				@cat_id				int,
				@subcat_id			int,
				@brand_id			int,
				@bra_id				int,
				@curr_id			int,
				@byor_id			int,
				@item_disabled		INT,
				@supp_id			INT,
				@intBranch4Lang		INT



		SELECT	@comp_id			=1,
				@lang_id			=2,
				@page_id			=10019,

				@option				=1,
				@item_desc			='',
				@coslis_id1			=1,
				@coslis_id2			=2,
				@coslis_id3			=1,
				@pres_id			=-1,
				@cat_id				=-1,
				@subcat_id			=-1,
				@brand_id			=-1,
				@bra_id				=-1,
				@curr_id			=-1,
				@byor_id			=-1,
				@item_disabled		=0,
				@supp_id			=8103

		*/
		--------------------------------------------------------
		--------------------------------------------------------

		DECLARE @lGuid AS UNIQUEIDENTIFIER

		SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuid     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
		-- -------------------------------------------------------------


		DECLARE @fun_id INT
		SET @fun_id = 1


		SELECT	I.[cat_id],
				C.[cat_desc],
				I.[subcat_id],
				SC.[subcat_desc],
				I.[bra_id],
				B.brand_desc,
				I.item_code,
				I.item_desc,

				CLI1.coslis_price		[coslis_price1],
				CLI1.coslis_price_aw	[coslis_price_aw1],
				CC1.curr_symbol			[curr_desc1],

				CLI2.coslis_price		[coslis_price2],
				CLI2.coslis_price_aw	[coslis_price_aw2],
				CC2.curr_symbol			[curr_desc2],

				CLI3.coslis_price		[coslis_price3],
				CLI3.coslis_price_aw	[coslis_price_aw3],
				CC3.curr_symbol			[curr_desc3]

		FROM	dbo.tbItem						I	WITH(NOLOCK)

				INNER JOIN @tblComplexFilter_Items AS tcfi
				ON	tcfi.item_id				= I.item_id

				LEFT JOIN [tbPresentation]		P	WITH(NOLOCK)
				ON	P.[comp_id]					=	I.[comp_id]
				AND P.[pres_id]					=	I.[pres_id]

				LEFT JOIN tbCategory			C	WITH(NOLOCK)
				ON	C.[comp_id]					= I.[comp_id]
				AND C.[cat_id]					= I.[cat_id]

				LEFT JOIN tbSubCategory			SC	WITH(NOLOCK)
				ON	SC.[comp_id]				= I.[comp_id]
				AND SC.[cat_id]					= I.[cat_id]
				AND SC.[subcat_id]				= I.[subcat_id]

				LEFT JOIN tbBrand				B	WITH(NOLOCK)
				ON	B.[comp_id]					= I.[comp_id]
				AND B.[brand_id]				= I.[brand_id]
				--and B.[bra_id]					= I.[bra_id] 02/04/2020 verificando el tema de la hoja en blanco, probé filtrar por marca y no lo hacia.

				LEFT JOIN	tbBranch			BR	WITH(NOLOCK)
				ON BR.[comp_id]					=	I.[comp_id]
				AND BR.[bra_id]					=	I.[bra_id]

				LEFT JOIN dbo.tbByOrder			BO	WITH(NOLOCK)
				ON	BO.[comp_id]				=	I.[comp_id]
				AND BO.[byor_id]				=	I.[byor_id]

				left JOIN [tbsysOptionsValues] o	WITH(NOLOCK)
				ON	o.[optval_id]				= I.[item_liquidation]
				AND	o.[optval_class]			= 1
				and o.lang_id					= @lang_id

				Inner join tbItemCostList		CLI1	WITH(NOLOCK)
				on	CLI1.[comp_id]				= I.[comp_id]
				and CLI1.[coslis_id]			= @coslis_id1
				and CLI1.[item_id]				= I.[item_id]

				Inner JOIN tbsysCurrency		CC1	WITH(NOLOCK)
				ON	CC1.[curr_id]				= CLI1.[curr_id]

				left join tbItemCostList		CLI2	WITH(NOLOCK)
				on	CLI2.[comp_id]				= I.[comp_id]
				and CLI2.[coslis_id]		    = @coslis_id2
				and CLI2.[item_id]				= I.[item_id]

				left JOIN tbsysCurrency			CC2	WITH(NOLOCK)
				ON	CC2.[curr_id]				= CLI2.[curr_id]

				left join tbItemCostList		CLI3	WITH(NOLOCK)
				on	CLI3.[comp_id]				= I.[comp_id]
				and CLI3.[coslis_id]		    = @coslis_id3
				and CLI3.[item_id]				= I.[item_id]

				left JOIN tbsysCurrency			CC3	WITH(NOLOCK)
				ON	CC3.[curr_id]				= CLI3.[curr_id]

				LEFT JOIN tbSupplier			ts	WITH(NOLOCK)
				ON	ts.comp_id					= I.comp_id
				AND ts.supp_id					= I.supp_id

				WHERE		I.[comp_id]		=	@comp_id
				AND			(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
				AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
				AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
				AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
				AND			(@bra_id		= -1 or I.[bra_id]		=	@bra_id)
				AND			(@curr_id		= -1 or I.[curr_id]		=	@curr_id)
				AND			(@byor_id		= -1 or I.[byor_id]		=	@byor_id)
				AND			(@supp_id		= -1 OR ts.supp_id		=	@supp_id )
				AND			(
							 @item_disabled = 0 and I.item_disabled = 'False'  OR
							 @item_disabled = 1 AND I.item_disabled = 'True'
							 )
				and			(
							(@option	 = -1 ) or
							(@option	 = 0 and I.item_desc like @item_desc + '%') or
							(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
							(@option	 = 2 and I.item_desc = @item_desc ) or
							(@option	 = 3 and I.item_desc <> @item_desc ) or
							(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
							)


		order by C.cat_desc, SC.subcat_desc, brand_desc, item_desc




		exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id






		select
		(select	CLN.coslis_desc
		from	[tbItemCostListName]	CLN
		where	CLN.coslis_id = @coslis_id1) [Column1],

		(select	CLN.coslis_desc
		from	[tbItemCostListName]		CLN
		where	CLN.coslis_id = 	@coslis_id2) [Column2],

		(select	CLN.coslis_desc
		from	[tbItemCostListName]		CLN
		where	CLN.coslis_id = 	@coslis_id3) [Column3]

		/* devolución de parámetros recibidos */
		DECLARE @related_page_id INT
		SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id



		/*************************************************************************************************************/
		/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
		/*
				SELECT	t.ctrl_id,	t.[text_desc]
				FROM	[tbsysTexts]				t
						inner join [tbsysControls]	c
						on c.[ctrl_id] = t.[ctrl_id]
				where	t.[lang_id]	= @lang_id
				and		t.[page_id]	= @related_page_id
				and		t.[type_id]	= 1
		*/
		/*************************************************************************************************************/
		SELECT
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 43
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

				CASE @option WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tov.optval_desc + ISNULL(@item_desc,'')
						FROM	dbo.tbsysOptionsValues tov
						WHERE	tov.optval_class	= 2
						AND		tov.lang_id			= @lang_id
						AND		tov.optval_id		= @option)
				END		[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 470
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

      			 (SELECT ticln.coslis_desc
					FROM dbo.tbItemCostListName ticln
					WHERE ticln.coslis_id = @coslis_id1)						[params4],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 471
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],
      			 CASE @coslis_id2 WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
					ELSE
						(SELECT ticln.coslis_desc
							FROM dbo.tbItemCostListName ticln
							WHERE ticln.coslis_id = @coslis_id2)
					END				[params6],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 472
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],
      			 CASE @coslis_id3 WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
					ELSE
						(SELECT ticln.coslis_desc
							FROM dbo.tbItemCostListName ticln
							WHERE ticln.coslis_id = @coslis_id3)
					END															[params8],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 36
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],
      			 CASE @cat_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tc.cat_desc
							FROM	dbo.tbCategory tc
							WHERE	tc.cat_id = @cat_id)
					END			[params10]			,

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 38
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],
      			 CASE @subcat_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tsc.subcat_desc
							FROM	dbo.tbSubCategory tsc
							WHERE	tsc.subcat_id = @subcat_id)
					END			                               [params12],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 73
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],
      			 CASE @brand_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tb.brand_desc
							FROM	dbo.tbBrand tb
							WHERE	tb.brand_id = @brand_id)
					END  [params14]		,

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 371
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],
      			 CASE @pres_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tp.pres_desc
							FROM	dbo.tbPresentation tp
							WHERE	tp.pres_id = @pres_id)
					END																							[params16],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 28
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params17],

      			 CASE @bra_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tb.bra_desc
							FROM	dbo.tbBranch tb
							WHERE	tb.bra_id = @bra_id)
					END					[params18]	,

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 106
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params19],

      			 CASE @curr_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tc.curr_desc
							FROM	dbo.tbsysCurrency tc
							WHERE	tc.curr_id = @curr_id)
					END					[params20],


					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 375
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params21],

      			 CASE @curr_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tc.curr_desc
							FROM	dbo.tbsysCurrency tc
							WHERE	tc.curr_id = @curr_id)
					END				[params22],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 1392
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params23],

      			 CASE @item_disabled  WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT	TOP 1 tov.optval_desc
							FROM	  tbsysOptionsValues tov

							WHERE	  tov.optval_class = 111
							AND		  tov.optval_id = @item_disabled
							and			tov.lang_id = @lang_id)
					END		                                                    [params24],


				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 402
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params25],

      			 CASE @supp_id  WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT	 ts.supp_name
						 FROM		tbSupplier ts

							WHERE	  ts.comp_id = @comp_id
							AND		  ts.supp_id = @supp_id)
					END		                                                    [params26]

	END
GO









CREATE procedure [dbo].[spCostLists2_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@option				int,
		@item_desc			varchar(200),
		@coslis_id1			int,
		@coslis_id2			int,
		@coslis_id3			int,
		@pres_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@bra_id				int,
		@curr_id			int,
		@byor_id			INT,
		@item_disabled		INT,
		@intBranch4Lang		int
)
AS
	BEGIN
		SET NOCOUNT ON



		-----------------------------------------------------
		/*

		DECLARE @comp_id			int,
				@lang_id			int,
				@page_id			int,

				@option				int,
				@item_desc			varchar(200),
				@coslis_id1			int,
				@coslis_id2			int,
				@coslis_id3			int,
				@pres_id			int,
				@cat_id				int,
				@subcat_id			int,
				@brand_id			int,
				@bra_id				int,
				@curr_id			int,
				@byor_id			int,
				@item_disabled		INT

		SELECT	@comp_id			=1,
				@lang_id			=2,
				@page_id			=10019,

				@option				=-1,
				@item_desc			='chevro',
				@coslis_id1			=1,
				@coslis_id2			=2,
				@coslis_id3			=6,
				@pres_id			=-1,
				@cat_id				=-1,
				@subcat_id			=-1,
				@brand_id			=-1,
				@bra_id				=-1,
				@curr_id			=-1,
				@byor_id			=-1,
				@item_disabled		=0

		*/

		-----------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		DECLARE @fun_id INT
		SET @fun_id = 1




		SELECT	I.item_code						[item_code],
				I.item_desc						[item_desc],
				CLI1.coslis_price				[coslis_price],
				CLI1.coslis_price_aw			[coslis_price_aw],
				CC1.curr_symbol					[curr_desc]




		FROM	dbo.tbItem	I

				LEFT JOIN [tbPresentation]		P
				ON	P.[comp_id]					= I.[comp_id]
				AND P.[pres_id]					= I.[pres_id]

				LEFT JOIN tbCategory			C
				ON	C.[comp_id]					= I.[comp_id]
				AND C.[cat_id]					= I.[cat_id]

				LEFT JOIN tbSubCategory			SC
				ON	SC.[comp_id]				= I.[comp_id]
				AND SC.[cat_id]					= I.[cat_id]
				AND SC.[subcat_id]				= I.[subcat_id]

				LEFT JOIN tbBrand				B
				ON	B.[comp_id]					= I.[comp_id]
				AND B.[brand_id]				= I.[brand_id]
				and B.[bra_id]					= I.[bra_id]

				LEFT JOIN	tbBranch			BR
				ON  BR.[comp_id]				= I.[comp_id]
				AND BR.[bra_id]					= I.[bra_id]

				LEFT JOIN dbo.tbByOrder			BO
				ON	BO.[comp_id]				= I.[comp_id]
				AND BO.[byor_id]				= I.[byor_id]

				left JOIN [tbsysOptionsValues] o
				ON	o.[optval_id]				= I.[item_liquidation]
				AND	o.[optval_class]			= 1
				and o.lang_id					= @lang_id

				Inner join tbItemCostList		CLI1
				on	CLI1.[comp_id]				= I.[comp_id]
				and CLI1.[coslis_id]			= @coslis_id1
				and CLI1.[item_id]				= I.[item_id]

				Inner JOIN tbsysCurrency		CC1
				ON	CC1.[curr_id]				= CLI1.[curr_id]

				left join tbItemCostList		CLI2
				on	CLI2.[comp_id]				= I.[comp_id]
				and CLI2.[coslis_id]		    = @coslis_id2
				and CLI2.[item_id]				= I.[item_id]

				left JOIN tbsysCurrency			CC2
				ON	CC2.[curr_id]				= CLI2.[curr_id]

				left join tbItemCostList		CLI3
				on	CLI3.[comp_id]				= I.[comp_id]
				and CLI3.[coslis_id]		    = @coslis_id3
				and CLI3.[item_id]				= I.[item_id]

				left JOIN tbsysCurrency			CC3
				ON	CC3.[curr_id]				= CLI3.[curr_id]

				WHERE		I.[comp_id]		=	@comp_id
				AND			(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
				AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
				AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
				AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
				AND			(@bra_id		= -1 or I.[bra_id]		=	@bra_id)
				AND			(@curr_id		= -1 or I.[curr_id]		=	@curr_id)
				AND			(@byor_id		= -1 or I.[byor_id]		=	@byor_id)
				AND			(
							 @item_disabled = 0 and I.item_disabled = 'False'  OR
							 @item_disabled = 1 AND I.item_disabled = 'True'
							 )
				and			(
							(@option	 = -1 ) or
							(@option	 = 0 and I.item_desc like @item_desc + '%') or
							(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
							(@option	 = 2 and I.item_desc = @item_desc ) or
							(@option	 = 3 and I.item_desc <> @item_desc ) or
							(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
							)

		order by C.cat_desc, SC.subcat_desc, brand_desc, item_desc


		exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id



		/* devolución de parámetros recibidos */
		DECLARE @related_page_id INT
		SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id



		/*************************************************************************************************************/
		/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
		/*
				SELECT	t.ctrl_id,	t.[text_desc]
				FROM	[tbsysTexts]				t
						inner join [tbsysControls]	c
						on c.[ctrl_id] = t.[ctrl_id]
				where	t.[lang_id]	= @lang_id
				and		t.[page_id]	= @related_page_id
				and		t.[type_id]	= 1
		*/
		/*************************************************************************************************************/
		SELECT
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 43
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

				CASE @option WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tov.optval_desc + ISNULL(@item_desc,'')
						FROM	dbo.tbsysOptionsValues tov
						WHERE	tov.optval_class	= 2
						AND		tov.lang_id			= @lang_id
						AND		tov.optval_id		= @option)
				END		[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 470
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

      			 (SELECT ticln.coslis_desc
					FROM dbo.tbItemCostListName ticln
					WHERE ticln.coslis_id = @coslis_id1)						[params4],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 471
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],
      			 CASE @coslis_id2 WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
					ELSE
						(SELECT ticln.coslis_desc
							FROM dbo.tbItemCostListName ticln
							WHERE ticln.coslis_id = @coslis_id2)
					END				[params6],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 472
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],
      			 CASE @coslis_id3 WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
					ELSE
						(SELECT ticln.coslis_desc
							FROM dbo.tbItemCostListName ticln
							WHERE ticln.coslis_id = @coslis_id3)
					END															[params8],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 36
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],
      			 CASE @cat_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tc.cat_desc
							FROM	dbo.tbCategory tc
							WHERE	tc.cat_id = @cat_id)
					END			[params10]			,

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 38
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],
      			 CASE @subcat_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tsc.subcat_desc
							FROM	dbo.tbSubCategory tsc
							WHERE	tsc.subcat_id = @subcat_id)
					END			                               [params12],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 73
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],
      			 CASE @brand_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tb.brand_desc
							FROM	dbo.tbBrand tb
							WHERE	tb.brand_id = @brand_id)
					END  [params14]		,

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 371
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],
      			 CASE @pres_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tp.pres_desc
							FROM	dbo.tbPresentation tp
							WHERE	tp.pres_id = @pres_id)
					END																							[params16],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 28
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params17],

      			 CASE @bra_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tb.bra_desc
							FROM	dbo.tbBranch tb
							WHERE	tb.bra_id = @bra_id)
					END					[params18]	,

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 106
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params19],

      			 CASE @curr_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tc.curr_desc
							FROM	dbo.tbsysCurrency tc
							WHERE	tc.curr_id = @curr_id)
					END					[params20],


					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 375
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params21],

      			 CASE @curr_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tc.curr_desc
							FROM	dbo.tbsysCurrency tc
							WHERE	tc.curr_id = @curr_id)
					END				[params22],

						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 1392
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params23],

      			 CASE @item_disabled  WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT	TOP 1 tov.optval_desc
							FROM	  tbsysOptionsValues tov

							WHERE	  tov.optval_class = 111
							AND		  tov.optval_id = @item_disabled
							AND		  tov.lang_id	= @lang_id)
					END		                                                    [params24]

	END
GO








CREATE PROCEDURE [dbo].[spCostPriceEdition_getDataCostListHistory]
(

	@comp_id			INT,
	@lang_id			INT,
	@item_id			INT

)
AS



BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	set nocount on

	set dateformat 'ymd'

	--------------------------------------------------------------
	/*
	--------------------------------------------------------------
	declare		@comp_id			INT,
				@lang_id			INT,
				@item_id			INT


	select		@comp_id			= 1,
				@lang_id			= 2,
				@item_id			= 220

	--------------------------------------------------------------
	*/
	--------------------------------------------------------------


	select  ticln.coslis_desc,
			ti.item_desc,
			isnull(ticlh.iclh_price,0) [iclh_price],
			isnull(ticlh.iclh_price_aw,0)[iclh_price_aw],
			tc.curr_desc,
			ticlh.iclh_cd,
			ISNULL(tu.user_lastname,'') + ' ' + ISNULL(tu.user_firstname,'')	[User],
			ticlh.iclh_lote														[iclh_lote],
			ticlh.iclh_id														[Order]


	from tbItemCostListHistory					ticlh


	inner join tbItemCostListName				ticln
	on  ticln.comp_id	= ticlh.comp_id
	and ticln.coslis_id = ticlh.coslis_id

	inner join tbItem							ti
	on  ti.comp_id		= ticlh.comp_id
	and ti.item_id		= ticlh.item_id

	--inner join tbItemCostList					ticl
	--on  ticl.comp_id	= ticlh.comp_id
	--and ticl.coslis_id	= ticlh.coslis_id
	--and ticl.item_id	= ticlh.item_id

	inner join tbsysCurrency					tc
	on  tc.curr_id		= ticlh.curr_id

	LEFT JOIN tbUser tu
	ON tu.[user_id] = ticlh.user_id_lastUpdate

	where	ticlh.comp_id		=   @comp_id
	AND		ti.item_id			=	@item_id

	order by	ticlh.iclh_id DESC
				--ticln.coslis_desc asc,
				--ticlh.iclh_cd desc


	--UNION

	--select  '-->' + ticln.coslis_desc,
	--		ti.item_desc,
	--		0 [iclh_lote],
	--		isnull(ticlh.coslis_price,0) [iclh_price],
	--		isnull(ticlh.coslis_price_aw,0)[iclh_price_aw],
	--		tc.curr_desc,
	--		ticlh.coslis_cd,
	--		ISNULL(tu.user_lastname,'') + ' ' + ISNULL(tu.user_firstname,'')	[User],
	--		0					[Order]


	--from tbItemCostList							ticlh


	--inner join tbItemCostListName				ticln
	--on  ticln.comp_id	= ticlh.comp_id
	--and ticln.coslis_id = ticlh.coslis_id

	--inner join tbItem							ti
	--on  ti.comp_id		= ticlh.comp_id
	--and ti.item_id		= ticlh.item_id



	--inner join tbsysCurrency					tc
	--on  tc.curr_id		= ticlh.curr_id

	--LEFT JOIN tbUser tu
	--ON tu.[user_id] = ticlh.user_id_lastUpdate

	--where	ticlh.comp_id		=   @comp_id
	--AND		ti.item_id			=	@item_id





END
GO








CREATE PROCEDURE [dbo].[spCostPriceEdition_getDataPriceListHistory]
(

	@comp_id			INT,
	@lang_id			INT,
	@item_id			INT

)
AS


BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------
	set nocount on

	set dateformat 'ymd'

	--------------------------------------------------------------
	/*
	--------------------------------------------------------------
	declare		@comp_id			INT,
				@lang_id			INT,
				@item_id			INT


	select		@comp_id			= 1,
				@lang_id			= 2,
				@item_id			= 220

	--------------------------------------------------------------
	*/
	--------------------------------------------------------------


	select  tpl.prli_desc,
			ti.item_desc,
			isnull(tplh.plh_price,0) [plh_price],
			tc.curr_desc,
			tplh.plh_cd,
			ISNULL(tu.user_lastname,'') + ' ' + ISNULL(tu.user_firstname,'')	[User],
			isnull(tplh.plh_lote,0)		[plh_lote],
			CASE
				WHEN tplh.plh_ruleUpdate = 'True' THEN 'Rule'
				ELSE									''
			END											'UM',
			tplh.plh_id					[Order]


	from tbPriceListHistory					tplh


	inner join tbPriceList					tpl
	on  tpl.comp_id		= tplh.comp_id
	AND tpl.prli_id		= tplh.prli_id

	inner join tbItem						ti
	on  ti.comp_id		= tplh.comp_id
	and ti.item_id		= tplh.item_id

	inner join tbsysCurrency				tc
	on  tc.curr_id		= tplh.curr_id

	LEFT JOIN tbUser tu
	ON tu.[user_id] = tplh.user_id_lastUpdate

	where	tplh.comp_id		=   @comp_id
	AND		ti.item_id			=	@item_id
	ORDER BY tplh.plh_id DESC

--UNION


--	select  '-->' + tpl.prli_desc,
--			ti.item_desc,
--			0 [plh_lote],
--			isnull(tplh.prli_price,0) [plh_price],
--			tc.curr_desc,
--			tplh.prli_updatedAt,
--			ISNULL(tu.user_lastname,'') + ' ' + ISNULL(tu.user_firstname,'')	[User],
--			0					[Order]


--	from tbPriceListItems					tplh


--	inner join tbPriceList					tpl
--	on  tpl.comp_id		= tplh.comp_id
--	AND tpl.prli_id		= tplh.prli_id

--	inner join tbItem						ti
--	on  ti.comp_id		= tplh.comp_id
--	and ti.item_id		= tplh.item_id

--	inner join tbsysCurrency				tc
--	on  tc.curr_id		= tplh.curr_id

--	LEFT JOIN tbUser tu
--	ON tu.[user_id] = tplh.user_id_lastUpdate

--	where	tplh.comp_id		=   @comp_id
--	AND		ti.item_id			=	@item_id

--	order by	[Order],
--				tpl.prli_desc asc,
--				tplh.plh_cd desc



END
GO







