CREATE  PROCEDURE [dbo].[spCostPriceEditionDetail_UpdateData]

(
	@comp_id					INT,
	@item_id					INT,
	@item_disabledInBalance		BIT,
	@item_expser				BIT,
	@item_expean				BIT,
	@item_newness				BIT,
	@item_liquidation			BIT,
	@item_outlet				BIT,
	@itemAtrb1_id				INT,
	@itemAtrb2_id				INT,
	@itemAtrb3_id				INT,
	@itemAtrb4_id				INT,
	@item_ChkAtrb1				BIT,
	@item_ChkAtrb2				BIT,
	@item_ChkAtrb3				BIT,
	@item_ChkAtrb4				BIT,
	@item_Surcharge1			DECIMAL(19,4),
	@item_Surcharge2			DECIMAL(19,4),
	@item_Surcharge3			DECIMAL(19,4),
	@item_Surcharge4			DECIMAL(19,4),
	@item_detail				VARCHAR(100),
	@item_liquidationPlus		BIT



)
as

BEGIN


	set nocount on

		if	(@itemAtrb1_id			= -1)	set	@itemAtrb1_id				= NULL
		if	(@itemAtrb2_id			= -1)	set	@itemAtrb2_id				= NULL
		if	(@itemAtrb3_id			= -1)	set	@itemAtrb3_id				= NULL
		if	(@itemAtrb4_id			= -1)	set	@itemAtrb4_id				= NULL

		UPDATE tbItem
			SET

				item_expser				= @item_expser,
				item_newness			= @item_newness,
				item_liquidation		= @item_liquidation,
				item_disabledInBalance	= @item_disabledInBalance,
				item_expean				= @item_expean,
				item_outlet				= @item_outlet,
				itemAtrb1_id			= @itemAtrb1_id,
				itemAtrb2_id			= @itemAtrb2_id,
				itemAtrb3_id			= @itemAtrb3_id,
				itemAtrb4_id			= @itemAtrb4_id,
				item_ChkAtrb1			= @item_ChkAtrb1,
				item_ChkAtrb2			= @item_ChkAtrb2,
				item_ChkAtrb3			= @item_ChkAtrb3,
				item_ChkAtrb4			= @item_ChkAtrb4,
				item_purOrd_surcharge1	= @item_Surcharge1,
				item_purOrd_surcharge2	= @item_Surcharge2,
				item_purOrd_surcharge3	= @item_Surcharge3,
				item_purOrd_surcharge4	= @item_Surcharge4,
				item_detail				= @item_detail,
				item_liquidationPlus	= @item_liquidationPlus

			WHERE comp_id = @comp_id
			AND	  item_id = @item_id



END


GO





CREATE PROCEDURE [dbo].[spCostPricePercentRelatinInitialValues_getData]
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT
)

AS SET NOCOUNT ON

	BEGIN

	-- -------------------------------------
	-- TESTING
	-- -------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@bra_id		INT,
			@prof_id	INT,
			@user_id	INT

		SELECT
			@comp_id	= 1,
			@bra_id		= 1,
			@prof_id	= 1,
			@user_id	= 1
	*/
	-- -------------------------------------

		SELECT
			tcppriv.comp_id,
			tcppriv.bra_id,
			tcppriv.prof_id,
			tcppriv.user_id,
			isnull(tcppriv.cat_id,-1)			[cat_id],
			isnull(tcppriv.subcat_id,-1)		[subcat_id],
			isnull(tcppriv.brand_id,-1)			[brand_id],
			isnull(tcppriv.pres_id,-1)			[pres_id],
			isnull(tcppriv.item_id,-1)			[item_id],
			ti.item_code,
			ti.item_desc,
			IsNull(tcppriv.supp_id,-1)			[supp_id],
			ts.supp_name


		FROM tbCostPricePercentRelationInitialValues		tcppriv		WITH (NOLOCK)

			LEFT JOIN tbItem								ti			WITH (NOLOCK)
			ON	ti.comp_id			= tcppriv.comp_id AND
				ti.item_id			= tcppriv.item_id

			LEFT JOIN tbSupplier							ts			WITH (NOLOCK)
			ON	ts.comp_id			= tcppriv.comp_id AND
				ts.supp_id			= tcppriv.supp_id

		WHERE	tcppriv.comp_id		= @comp_id	AND
			    tcppriv.bra_id		= @bra_id	AND
				tcppriv.prof_id		= @prof_id	AND
				tcppriv.[user_id]	= @user_id

	END
GO




-- Log
-- MOS 04-2024: Se pone filtro de PM_Id, si llega informado se deben borrar todos los que NO tengan ese pm_id puesto



CREATE PROCEDURE [dbo].[spCostPricePercentRelation_getDataByFilters]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@guid							NVARCHAR(50),
	@item_recentlyPurchased			INT,
	@itemclass						INT,
	@page_size						INT,	-- #1
	@page_number					INT	,	-- #1
	@order							nvarchar(max),
	@bitViewTotals					BIT,
	@pm_id							INT
)
AS



BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	-- =================================================================================================================
	-- Testing
	-- =================================================================================================================
	/*
	DECLARE @comp_id					INT,
			@lang_id					INT,
			@bra_id						INT,
			@item_id					INT,
			@cat_id						INT,
			@subcat_id					INT,
			@pres_id					INT,
			@brand_id					INT,
			@item_disabled				INT,
			@item_disabledInPriceList	INT,
			@item_recentlyPurchased		INT,
			@page_size					INT,
			@page_number				INT,
			@itemclass					int,
			@supp_id					INT,
			@order					NVARCHAR(MAX),
			@guid							NVARCHAR(50),
			@bitViewTotals					BIT

	SELECT	@comp_id					= 1,
			@lang_id					= 2,
			@bra_id						= 1,
			@item_id					= -1,
			@cat_id						= -1,
			@subcat_id					= -1,
			@pres_id					= -1,
			@brand_id					= -1,
			@item_disabled				= -1,
			@item_disabledInPriceList	= -1,
			@item_recentlyPurchased		= -1,
			@page_size					= 15,
			@page_number				= 2,
			@itemclass					= -1,
			@supp_id					= -1,
			@order						= '',
			@guid						= '3F2504E0-4F89-11D3-9A0C-0305E82C3301',
			@bitViewTotals				= 1

	-- DROP TABLE #tmpPriceCostData
	-- drop TABLE #tblComplexFilter_Items
	*/
	-- =================================================================================================================


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros
	-- NOTA: Para buscar todas las incidencias
	-- de este método ejecutar el "BuscarTexto" en la base de datos
	-- con el valor de referencia "#8600"
	-- Página de EJEMPLO:App_Reports_App_WebForms_wfmRptFilters_PriceLists2_Testing
	-- -------------------------------------------------------------
	DECLARE @objGUID AS UNIQUEIDENTIFIER
	SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@guid)

	CREATE TABLE #tblComplexFilter_Items ([item_id] INT PRIMARY KEY)
	CREATE NONCLUSTERED INDEX #tblComplexFilter_Items ON #tblComplexFilter_Items
						(
						item_id
						)
	--DECLARE #tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO #tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf		WITH (NOLOCK)
			WHERE tcf.sl_guid = @objGUID     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO #tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti	WITH (NOLOCK)
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------


	-- MOS 04-2024: Se pone filtro de PM_Id, si llega informado se deben borrar todos los que NO tengan ese pm_id puesto
	IF @pm_id <> -1
		BEGIN
			DELETE  #tblComplexFilter_Items
				FROM #tblComplexFilter_Items tmp
				LEFT JOIN tbItem AS ti	WITH (NOLOCK)
				ON	ti.comp_id = @comp_id AND
					ti.item_id = tmp.item_id
				WHERE	ti.pm_id IS NULL	OR
						ti.pm_id <> @pm_id
		END




	DECLARE @bitTrue AS BIT
	DECLARE @bitFalse AS BIT
	SET @bitTrue = 1
	SET @bitFalse = 0


	-- Si solo trae los Ultimos Comprados entonces solo deja esos en la tabla temporal.
	IF @item_recentlyPurchased <> -1
		BEGIN
			DECLARE @bitRecPur AS BIT
			IF @item_recentlyPurchased = 0
				BEGIN
					SET @bitRecPur =  1
				END
			ELSE
				BEGIN
					SET @bitRecPur =  0
				END


			DELETE #tblComplexFilter_Items
				FROM #tblComplexFilter_Items tmp
				INNER JOIN tbItem ti		WITH (NOLOCK)
					ON	ti.comp_id	 = @comp_id		AND
						ti.item_id	 = tmp.item_id
			WHERE	ti.item_recentlyPurchased = @bitRecPur
		END


	-- Solo trae lo q corresponda segun talles y colores.
	IF @itemclass <> -1
		BEGIN
			DELETE #tblComplexFilter_Items
				FROM #tblComplexFilter_Items tmp
				INNER JOIN vwItems_ParentStatus vwr							WITH (NOLOCK)
					ON		vwr.comp_id = @comp_id		AND
							vwr.item_id = tmp.item_id
				WHERE
					CASE
   						WHEN @itemclass = 1 AND vwr.[Master]	= 1 THEN 1
   						WHEN @itemclass = 2 AND vwr.Slave		= 1 THEN 1
   						ELSE 0
   					END	= 0
		END



	IF	@order NOT LIKE '%item_id%' AND
		@order NOT LIKE '%item_code%' AND
		@order NOT LIKE '%item_desc%' AND
		@order NOT LIKE '%item_disabled%' AND
		@order NOT LIKE '%item_disabledInPriceList%' AND
		@order NOT LIKE '%item_purOrd_Disc1%' AND
		@order NOT LIKE '%item_purOrd_Disc2%' AND
		@order NOT LIKE '%item_purOrd_Disc3%' AND
		@order NOT LIKE '%item_purOrd_Disc4%'
		BEGIN
			SET @order = ''
		END


	IF @bitViewTotals = 'False'
		BEGIN


			IF @order = ''
				BEGIN
					SET @order = 'ti.cat_id,ti.subcat_id,ti.item_desc ASC'
				END



			DECLARE @strExecute2 AS NVARCHAR(MAX)

			SET @strExecute2 = '
			SELECT	'''' [ ], '''' [ ], '''' [ ],
					convert(bit,
					CASE
						WHEN tilu.comp_id IS NULL THEN 0
						ELSE						   1
					END	)[lastUpdated],
					ROW_NUMBER() OVER ( order BY ' + @order + '   ) AS RowNumber,
					ti.item_code,
					ti.item_desc,
					ti.item_disabled,				-- Parte: 677
						ti.item_disabledInPriceList,	-- Parte: 677
						CASE WHEN  ti.item_purOrd_Disc1 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_Disc1)	END  [item_purOrd_Disc1],
						CASE WHEN  ti.item_purOrd_Disc2 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_Disc2)	END	 [item_purOrd_Disc2],
						CASE WHEN  ti.item_purOrd_Disc3 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_Disc3)	END	 [item_purOrd_Disc3],
						CASE WHEN  ti.item_purOrd_Disc4 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_Disc4)	END	 [item_purOrd_Disc4],
						CASE WHEN  ti.item_purOrd_surcharge1 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_surcharge1) END	 [item_purOrd_surcharge1],
						CASE WHEN  ti.item_purOrd_surcharge2 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_surcharge2) END	 [item_purOrd_surcharge2],
						CASE WHEN  ti.item_purOrd_surcharge3 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_surcharge3) END	 [item_purOrd_surcharge3],
						CASE WHEN  ti.item_purOrd_surcharge4 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_surcharge4) END	 [item_purOrd_surcharge4],

			      	ti.item_id
			FROM tbItem ti							WITH (NOLOCK)
			INNER JOIN #tblComplexFilter_Items tmp
				ON tmp.item_id = ti.item_id
			LEFT JOIN tbItemLastUpdated tilu		WITH (NOLOCK)
				ON	tilu.comp_id = ti.comp_id AND
					tilu.item_id = ti.item_id

			ORDER BY ' + @order -- ti.cat_id,ti.subcat_id,ti.item_desc ASC

			EXEC (@strExecute2)


			SELECT	COUNT(*)
				FROM tbItem ti						WITH (NOLOCK)
				INNER JOIN #tblComplexFilter_Items tmp
					ON tmp.item_id = ti.item_id


			drop table #tblComplexFilter_Items
			return

		END





	IF	@order NOT LIKE '%item_id%' AND
		@order NOT LIKE '%item_code%' AND
		@order NOT LIKE '%item_desc%' AND
		@order NOT LIKE '%item_disabled%' AND
		@order NOT LIKE '%item_disabledInPriceList%' AND
		@order NOT LIKE '%item_purOrd_Disc1%' AND
		@order NOT LIKE '%item_purOrd_Disc2%' AND
		@order NOT LIKE '%item_purOrd_Disc3%' AND
		@order NOT LIKE '%item_purOrd_Disc4%'
		BEGIN
			SET @order = ''
		END



	-- si no se informa ningun ordenamiento, lo hace por descripcion.
	IF @order = '' SET @order = '[cat_id],[subcat_id],[item_desc] asc'



	-- =================================================================================================================
	-- variables de trabajo
	DECLARE	@prli_desc			VARCHAR(100),
			@costlist_desc		VARCHAR(100),
			@lcoslis_isAW		BIT,
			@tmp_id				INT,
			@value				VARCHAR(100),
			@value_price		VARCHAR(100),
			@value_aw			VARCHAR(100),
			@litem_id			INT,
			@lcostdesc_pp		NVARCHAR(100),
			@ItemPercentNumber	INT,
			@Markup				NVARCHAR(100),
			@columns			NVARCHAR(1000),
			@columnsCost		NVARCHAR(1000),
			@columnsCostCurr	NVARCHAR(1000),
			@columnsPerc		NVARCHAR(1000),
			@columnsPrice		NVARCHAR(1000),
			@columnsPriceCurr	NVARCHAR(1000),
			@values				NVARCHAR(1000),
			@qtyTotal			INT,
			@item_ifHasItemAssociationSumPrices	BIT





	-- =================================================================================================================
	-- recuperamos de la tabla de palabras la correspondiente a Costo AW
	SELECT	@lcostdesc_pp	= tswn.word_desc
		FROM	tbSysWordsNew	tswn	WITH (NOLOCK)
		WHERE	tswn.lang_id	= @lang_id
		AND		tswn.wordsi_id	= 393





	-- =================================================================================================================
	-- creación de la tabla temporal con los campos código y descripción de artículos
	CREATE TABLE #tmpPriceCostData
	(
		LastUpdated			BIT,
		RowNumber			INT,
		item_code			NVARCHAR(50),
		item_desc			NVARCHAR(500)
	)





	IF @bitViewTotals = 'True'
		BEGIN




			-- =================================================================================================================
			-- cursor para obtener las descripciones de los costos relacionados a los item de la tabla tbCostPricePercentRelation
			-- y agregar esos nombres como nuevos campos en la temporal #tmpPriceCostData
			DECLARE cursor_costlist CURSOR LOCAL FAST_FORWARD FOR

			SELECT	--DISTINCT
					ticln.coslis_desc,
					tcppr.coslis_isAW,
					tpl.prli_desc,
					tcppr.ItemPercentNumber,
					COUNT_BIG(*)						[qtyTotal]

			FROM	tbItem										ti				WITH (NOLOCK)

					INNER JOIN #tblComplexFilter_Items tmpi
						ON tmpi.item_id = ti.item_id

					INNER JOIN tbCostPricePercentRelation		tcppr			WITH (NOLOCK)  -- era von la vista, se paso a abla y argrego el oder
					ON  tcppr.comp_id	= ti.comp_id
					AND tcppr.bra_id	= @bra_id

					LEFT JOIN tbItemCostListName				ticln			WITH (NOLOCK)
					ON	ticln.comp_id	= ti.comp_id
					AND ticln.coslis_id = tcppr.coslis_id

					LEFT JOIN tbPriceList						tpl				WITH (NOLOCK)
					ON	tpl.comp_id = ti.comp_id
					AND tpl.prli_id = tcppr.prli_id

					--** IDEm EN ESTE TAG
					--INNER JOIN vwItems_ParentStatus vwr							WITH (NOLOCK)
					--	ON		vwr.comp_id = ti.comp_id
					--		AND vwr.item_id = ti.item_id

			WHERE	ti.comp_id						= @comp_id
			--AND		(@item_recentlyPurchased		= -1		or isnull(ti.item_recentlyPurchased,'false')	= @item_recentlyPurchased)
			--AND		CASE
			--			WHEN @itemclass = -1						THEN 1
	  -- 					WHEN @itemclass = 1 AND vwr.[Master]	= 1 THEN 1
	  -- 					WHEN @itemclass = 2 AND vwr.Slave		= 1 THEN 1
	  -- 					ELSE 0
	  -- 				END	= 1
			GROUP BY
					ticln.coslis_desc,
					tcppr.coslis_isAW,
					tpl.prli_desc,
					tcppr.ItemPercentNumber,
					tcppr.cppr_order
			ORDER BY tcppr.cppr_order

			OPEN cursor_costlist

			FETCH NEXT FROM cursor_costlist
			INTO	@costlist_desc,@lcoslis_isAW,@prli_desc,@ItemPercentNumber,@qtyTotal

			WHILE @@FETCH_STATUS = 0
				BEGIN

					-- =================================================================================================================
					-- se arma el nombre de cada campo que se va a crear en la temporal con las descripciones
					-- de lista de costo / markup / lista de precio
					--SET @columns = ''

					--IF @lcoslis_isAW = 'true'
					--	SET @columns = @costlist_desc + ' ' + @lcostdesc_pp
					--ELSE
					--	SET @columns = @costlist_desc

					--SELECT @columns = @columns	+ ' - ' + 'MarkUp ' + convert(varchar,@ItemPercentNumber) + ' - ' + @prli_desc
					--EXEC ('alter table #tmpPriceCostData add [' + @columns + '] NVARCHAR(200)')
					-- =================================================================================================================

					SET @columnsCost = ''
					IF @lcoslis_isAW = 'true'
						SET @columnsCost = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' '  + @costlist_desc + ' ' + @lcostdesc_pp
					ELSE
						SET @columnsCost = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' ' + @costlist_desc
					EXEC ('alter table #tmpPriceCostData add [' + @columnsCost + '] decimal(19,6)')

					SET @columnsCostCurr = ''
					SET @columnsCostCurr = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' ' + 'CostCu'
					EXEC ('alter table #tmpPriceCostData add [' + @columnsCostCurr + '] NVARCHAR(200)')

					SET @columnsPerc = ''
					SET @columnsPerc = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' ' + 'MarkUp'
					EXEC ('alter table #tmpPriceCostData add [' + @columnsPerc + '] decimal(19,8)')

					SET @columnsPrice = ''
					SET @columnsPrice  = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' ' + @prli_desc
					EXEC ('alter table #tmpPriceCostData add [' + @columnsPrice + '] decimal(19,6)')

					SET @columnsPriceCurr = ''
					SET @columnsPriceCurr = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' ' + 'PriceCu'
					EXEC ('alter table #tmpPriceCostData add [' + @columnsPriceCurr + '] NVARCHAR(200)')



					FETCH NEXT FROM cursor_costlist
					INTO	@costlist_desc,@lcoslis_isAW,@prli_desc,@ItemPercentNumber,@qtyTotal

				END

			CLOSE cursor_costlist
			DEALLOCATE cursor_costlist

		END




	-- =================================================================================================================
	-- se agregan los campos de id (identity) e item_id a la tabla temporal #tmpPriceCostData
	ALTER TABLE #tmpPriceCostData
		ADD item_disabled				BIT,	-- Parte: 677
			item_disabledInPriceList	BIT,	-- Parte: 677
			item_purOrd_Disc1			DECIMAL(18,4),
			item_purOrd_Disc2			DECIMAL(18,4),
			item_purOrd_Disc3			DECIMAL(18,4),
			item_purOrd_Disc4			DECIMAL(18,4),
			item_purOrd_surcharge1		DECIMAL(18,4),
			item_purOrd_surcharge2		DECIMAL(18,4),
			item_purOrd_surcharge3		DECIMAL(18,4),
			item_purOrd_surcharge4		DECIMAL(18,4),
			tmp_id						INT IDENTITY,
			item_id						INT


	-- =================================================================================================================
	-- aquí se terminó de crear la tabla temporal #tmpPriceCostData con todos los campos correspondientes
	-- =================================================================================================================



	-- ---------------------------------------------------------------------------------------------------------------
	-- Se insertan los items ORDENADOS en la tabla temporal MOS 12-2013
	-- ---------------------------------------------------------------------------------------------------------------
	DECLARE @strExecute AS VARCHAR(MAX)
	BEGIN TRY
		-- Si hay un problema de ordenamiento se pasa el orden por defecto!
		SET @strExecute =
		'
					SELECT	DISTINCT
						ti.item_id,
						ti.item_code,
						ti.item_desc,
						ti.item_disabled,				-- Parte: 677
						ti.item_disabledInPriceList,	-- Parte: 677
						ti.item_purOrd_Disc1,
						ti.item_purOrd_Disc2,
						ti.item_purOrd_Disc3,
						ti.item_purOrd_Disc4,
						ti.item_purOrd_surcharge1,
						ti.item_purOrd_surcharge2,
						ti.item_purOrd_surcharge3,
						ti.item_purOrd_surcharge4,
						ROW_NUMBER() OVER ( order by ' + @order + '   ) AS RowNumber

					FROM	tbItem									ti  WITH (NOLOCK)

						INNER JOIN #tblComplexFilter_Items tmpi
							ON tmpi.item_id = ti.item_id

						LEFT JOIN tbItemStorage						tis	WITH (NOLOCK)
							ON	tis.comp_id = ti.comp_id
							AND tis.item_id = ti.item_id
							AND tis.stor_id = (select bb.stor_id from tbBranch bb where bb.comp_id = ' + convert(nvarchar(10),@comp_id) + ' and bb.bra_id = ' + convert(nvarchar(10),@bra_id) + ')



					WHERE	ti.comp_id					= '				+ convert(nvarchar(10),@comp_id)




						----** IDEm EN ESTE TAG
						--INNER JOIN vwItems_ParentStatus vwr				WITH (NOLOCK)
						--	ON		vwr.comp_id = ti.comp_id
						--		AND vwr.item_id = ti.item_id
					--AND		(
					--			'  + convert(nvarchar(10),@itemclass) + ' = -1
					--		OR  (' + convert(nvarchar(10),@itemclass) + ' = 1 AND vwr.[Master]	= 1)
					--		OR	(' + convert(nvarchar(10),@itemclass) + ' = 2 AND vwr.Slave		= 1)
					--	)
--AND		(' + convert(nvarchar(10),@item_recentlyPurchased)   + '	= -1 OR isnull(ti.item_recentlyPurchased,''false'')	= ' + convert(nvarchar(10),@item_recentlyPurchased)   + ')

--					AND		(' + convert(nvarchar(10),@item_id)			+ '	= -1 OR ti.item_id									= '  + convert(nvarchar(10),@item_id)		+ ')
--					AND		(' + convert(nvarchar(10),@cat_id)			+ '	= -1 OR ti.cat_id									= '  + convert(nvarchar(10),@cat_id)		+ ')
--					AND		(' + convert(nvarchar(10),@supp_id)			+ '	= -1 OR ti.supp_id									= '  + convert(nvarchar(10),@supp_id)		+ ')
--					AND		(' + convert(nvarchar(10),@subcat_id)		+ '	= -1 OR ti.subcat_id								= '  + convert(nvarchar(10),@subcat_id)		+ ')
--					AND		(' + convert(nvarchar(10),@brand_id)		+ '	= -1 OR ti.brand_id									= '  + convert(nvarchar(10),@brand_id)		+ ')
--					AND		(' + convert(nvarchar(10),@pres_id)			+ '	= -1 OR ti.pres_id									= '  + convert(nvarchar(10),@pres_id)		+ ')
--					AND		(' + convert(nvarchar(10),@item_disabled)	+ '	= -1 OR ti.item_disabled							= '  + convert(nvarchar(10),@item_disabled) + ')
--					AND		(' + convert(nvarchar(10),@item_disabledInPriceList) + '	= -1 OR ti.item_disabledInPriceList					= ' + convert(nvarchar(10),@item_disabledInPriceList) + ')



		INSERT INTO	#tmpPriceCostData
			(
				item_id,
				item_code,
				item_desc,
				item_disabled,
				item_disabledInPriceList,
				item_purOrd_Disc1,
				item_purOrd_Disc2,
				item_purOrd_Disc3,
				item_purOrd_Disc4,
				item_purOrd_surcharge1,
				item_purOrd_surcharge2,
				item_purOrd_surcharge3,
				item_purOrd_surcharge4,
				RowNumber

			)
			EXEC (@strExecute)


	END TRY
	-- Idem pero con orden por defecto
	BEGIN CATCH
		SET @order = '[cat_id],[subcat_id],[item_desc] asc'
		SET @strExecute =
		'
					SELECT	DISTINCT
						ti.item_id,
						ti.item_code,
						ti.item_desc,
						ti.item_disabled,				-- Parte: 677
						ti.item_disabledInPriceList,	-- Parte: 677
						ti.item_purOrd_Disc1,
						ti.item_purOrd_Disc2,
						ti.item_purOrd_Disc3,
						ti.item_purOrd_Disc4,
						ti.item_purOrd_surcharge1,
						ti.item_purOrd_surcharge2,
						ti.item_purOrd_surcharge3,
						ti.item_purOrd_surcharge4,
						ROW_NUMBER() OVER ( order by ' + @order + '   ) AS RowNumber

					FROM	tbItem									ti  WITH (NOLOCK)

						INNER JOIN #tblComplexFilter_Items tmpi
							ON tmpi.item_id = ti.item_id

						LEFT JOIN tbItemStorage						tis	WITH (NOLOCK)
							ON	tis.comp_id = ti.comp_id
							AND tis.item_id = ti.item_id
							AND tis.stor_id = (select bb.stor_id from tbBranch bb where bb.comp_id = ' + convert(nvarchar(10),@comp_id) + ' and bb.bra_id = ' + convert(nvarchar(10),@bra_id) + ')
					WHERE	ti.comp_id					= '				+ convert(nvarchar(10),@comp_id)

					--AND		(
					--			'  + convert(nvarchar(10),@itemclass) + ' = -1
					--		OR  (' + convert(nvarchar(10),@itemclass) + ' = 1 AND vwr.[Master]	= 1)
					--		OR	(' + convert(nvarchar(10),@itemclass) + ' = 2 AND vwr.Slave		= 1)
					--	)
						----** IDEm EN ESTE TAG
						--INNER JOIN vwItems_ParentStatus vwr				WITH (NOLOCK)
						--	ON		vwr.comp_id = ti.comp_id
						--		AND vwr.item_id = ti.item_id

-- AND		(' + convert(nvarchar(10),@item_recentlyPurchased)   + '	= -1 OR isnull(ti.item_recentlyPurchased,''false'')	= ' + convert(nvarchar(10),@item_recentlyPurchased)   + ')
--					AND		(' + convert(nvarchar(10),@item_id)			+ '	= -1 OR ti.item_id									= '  + convert(nvarchar(10),@item_id)		+ ')
--					AND		(' + convert(nvarchar(10),@cat_id)			+ '	= -1 OR ti.cat_id									= '  + convert(nvarchar(10),@cat_id)		+ ')
--					AND		(' + convert(nvarchar(10),@supp_id)			+ '	= -1 OR ti.supp_id									= '  + convert(nvarchar(10),@supp_id)		+ ')
--					AND		(' + convert(nvarchar(10),@subcat_id)		+ '	= -1 OR ti.subcat_id								= '  + convert(nvarchar(10),@subcat_id)		+ ')
--					AND		(' + convert(nvarchar(10),@brand_id)		+ '	= -1 OR ti.brand_id									= '  + convert(nvarchar(10),@brand_id)		+ ')
--					AND		(' + convert(nvarchar(10),@pres_id)			+ '	= -1 OR ti.pres_id									= '  + convert(nvarchar(10),@pres_id)		+ ')
--					AND		(' + convert(nvarchar(10),@item_disabled)	+ '	= -1 OR ti.item_disabled							= '  + convert(nvarchar(10),@item_disabled) + ')
--					AND		(' + convert(nvarchar(10),@item_disabledInPriceList) + '	= -1 OR ti.item_disabledInPriceList					= ' + convert(nvarchar(10),@item_disabledInPriceList) + ')



		INSERT INTO	#tmpPriceCostData
			(
				item_id,
				item_code,
				item_desc,
				item_disabled,
				item_disabledInPriceList,
				item_purOrd_Disc1,
				item_purOrd_Disc2,
				item_purOrd_Disc3,
				item_purOrd_Disc4,
				item_purOrd_surcharge1,
				item_purOrd_surcharge2,
				item_purOrd_surcharge3,
				item_purOrd_surcharge4,
				RowNumber

			)
			EXEC (@strExecute)

	END CATCH






	DELETE FROM #tmpPriceCostData
		WHERE NOT (RowNumber BETWEEN (@page_size * @page_number + 1) AND (@page_size * (@page_number + 1)))
	-- ---------------------------------------------------------------------------------------------------------------


	-- =================================================================================================================
	-- Parte		: S/P Ref #1
	-- se insertan todos los registros que van a componer la tabla temporal con los datos de los artículos pero sólo de
	-- registros que componen la página consultada
/*
	;WITH resultado_total AS
	(
		SELECT	DISTINCT
				ti.item_id,
				ti.item_code,
				ti.item_desc,
				ti.item_disabled,				-- Parte: 677
				ti.item_disabledInPriceList,	-- Parte: 677
				ROW_NUMBER() OVER ( order by (@order) asc  ) AS RowNumber

		FROM	tbItem									ti

			LEFT JOIN tbItemStorage						tis
				ON	tis.comp_id = ti.comp_id
				AND tis.item_id = ti.item_id
				AND tis.stor_id = (select bb.stor_id from tbBranch bb where bb.comp_id = @comp_id and bb.bra_id = @bra_id)

			--** IDEm EN ESTE TAG
			INNER JOIN vwItems_ParentStatus vwr
				ON		vwr.comp_id = ti.comp_id
					AND vwr.item_id = ti.item_id

		WHERE	ti.comp_id					= @comp_id
		AND		(@item_id					= -1 OR ti.item_id									= @item_id)
		AND		(@cat_id					= -1 OR ti.cat_id									= @cat_id)
		AND		(@supp_id					= -1 OR ti.supp_id									= @supp_id)
		AND		(@subcat_id					= -1 OR ti.subcat_id								= @subcat_id)
		AND		(@brand_id					= -1 OR ti.brand_id									= @brand_id)
		AND		(@pres_id					= -1 OR ti.pres_id									= @pres_id)
		AND		(@item_disabled				= -1 OR ti.item_disabled							= @item_disabled)	-- Parte: 677
		AND		(@item_disabledInPriceList	= -1 OR ti.item_disabledInPriceList					= @item_disabledInPriceList) -- Parte: 677
		AND		(@item_recentlyPurchased	= -1 or isnull(ti.item_recentlyPurchased,'false')	= @item_recentlyPurchased)
		AND		(
					@itemclass = -1
				OR  (@itemclass = 1 AND vwr.[Master]	= 1)
				OR	(@itemclass = 2 AND vwr.Slave		= 1)
			)


		--ORDER BY ti.item_desc
	)
	INSERT INTO	#tmpPriceCostData
	(
		item_id,
		item_code,
		item_desc,
		item_disabled,
		item_disabledInPriceList,
		RowNumber

	)
	SELECT	item_id,item_code,item_desc,item_disabled,item_disabledInPriceList, RowNumber
			FROM resultado_total
		WHERE RowNumber BETWEEN (@page_size * @page_number + 1) AND (@page_size * (@page_number + 1))
	*/
	--***********************************************************************************************************************************



	IF @bitViewTotals = 'True'
		BEGIN


				-- =================================================================================================================
				-- se recuperan todos los datos necesarios para mostrar en la consulta
				DECLARE cursor_updatecostlist CURSOR LOCAL FAST_FORWARD FOR

				SELECT	tmp.tmp_id,
						tmp.item_id,
						LTRIM(RTRIM(ticln.coslis_desc))														[coslis_desc],
						LTRIM(RTRIM(ISNULL(sc4Cost.curr_symbol,''))) + ' ' +
								CONVERT(VARCHAR, convert(decimal(20,4),ISNULL(ticl.coslis_price,0)))		[coslis_price],
						LTRIM(RTRIM(ISNULL(sc4Cost.curr_symbol,''))) + ' ' +
								CONVERT(VARCHAR, convert(decimal(20,4),ISNULL(ticl.coslis_price_aw,0)))		[coslis_price_aw],
						tcppr.coslis_isAW,

						tcppr.ItemPercentNumber,


						CASE
							WHEN IsNull(tcppr.cppr_RecalculatePercent,'True') = 'True' OR ti.item_ifHasItemAssociationSumPrices = 'True' THEN
												convert(decimal(19,8),
														dbo.fngetMarkUp(
																		CASE WHEN tcppr.coslis_isAW = 'true' THEN
																				isnull(ticl.coslis_price_aw,0)
																			ELSE
																				isnull(ticl.coslis_price,0)
																		END,
																		CASE
																			when tpli.prli_price IS NULL THEN 0
																			ELSE

																					dbo.fnGetExchange2( @comp_id,
																										tpli.prli_price,
																										tpli.curr_id,
 																										CASE
 																											WHEN ticl.curr_id IS NULL THEN
																												ti.curr_id
																											ELSE
																												ticl.curr_id
																										END,
																										0,
																										0,
																										0,
																										'false')
																		END
																		)	)

							ELSE
								CASE
									WHEN tcppr.ItemPercentNumber = 1 THEN convert(decimal(19,8),ti.item_markup_1)
									WHEN tcppr.ItemPercentNumber = 2 THEN convert(decimal(19,8),ti.item_markup_2)
									WHEN tcppr.ItemPercentNumber = 3 THEN convert(decimal(19,8),ti.item_markup_3)
									WHEN tcppr.ItemPercentNumber = 4 THEN convert(decimal(19,8),ti.item_markup_4)
									WHEN tcppr.ItemPercentNumber = 5 THEN convert(decimal(19,8),ti.item_markup_5)
									WHEN tcppr.ItemPercentNumber = 6 THEN convert(decimal(19,8),ti.item_markup_6)
									WHEN tcppr.ItemPercentNumber = 7 THEN convert(decimal(19,8),ti.item_markup_7)
									WHEN tcppr.ItemPercentNumber = 8 THEN convert(decimal(19,8),ti.item_markup_8)
									WHEN tcppr.ItemPercentNumber = 9 THEN convert(decimal(19,8),ti.item_markup_9)
									WHEN tcppr.ItemPercentNumber = 10 THEN convert(decimal(19,8),ti.item_markup_10)
									WHEN tcppr.ItemPercentNumber = 11 THEN convert(decimal(19,8),ti.item_markup_11)
									WHEN tcppr.ItemPercentNumber = 12 THEN convert(decimal(19,8),ti.item_markup_12)
									WHEN tcppr.ItemPercentNumber = 13 THEN convert(decimal(19,8),ti.item_markup_13)
									WHEN tcppr.ItemPercentNumber = 14 THEN convert(decimal(19,8),ti.item_markup_14)
									WHEN tcppr.ItemPercentNumber = 15 THEN convert(decimal(19,8),ti.item_markup_15)
									WHEN tcppr.ItemPercentNumber = 16 THEN convert(decimal(19,8),ti.item_markup_16)
								END
						END
																											[MarkUp],

						LTRIM(RTRIM(tpl.prli_desc))															[prli_desc],
						LTRIM(RTRIM(ISNULL(tc1.curr_symbol,''))) + ' ' +
								CONVERT(VARCHAR,(ISNULL(tpli.prli_price,0)))			[prli_price],
								ISNULL(ti.item_ifHasItemAssociationSumPrices,'False')	[item_ifHasItemAssociationSumPrices],

						LTRIM(RTRIM(ISNULL(sc4Cost.curr_symbol,'')))					[strCostListCurrency],
						ISNULL(ticl.coslis_price,0)										[decCost],
						ISNULL(ticl.coslis_price_aw,0)									[decCostAW]	,
						LTRIM(RTRIM(ISNULL(tc1.curr_symbol,'')))						[strPriceCurrency],
						ISNULL(tpli.prli_price,0)										[decPrice]

					FROM	#tmpPriceCostData						tmp

							INNER JOIN tbItem						ti				WITH (NOLOCK)
							ON  ti.comp_id		= @comp_id
							AND ti.item_id		= tmp.item_id

							INNER JOIN tbCostPricePercentRelation	tcppr			WITH (NOLOCK)
							ON	tcppr.comp_id	= ti.comp_id
							AND tcppr.bra_id	= @bra_id

							LEFT JOIN tbItemCostListName			ticln			WITH (NOLOCK)
							ON	ticln.comp_id	= ti.comp_id
							AND ticln.coslis_id = tcppr.coslis_id

							LEFT JOIN tbItemCostList				ticl			WITH (NOLOCK)
							ON	ticl.comp_id	= ti.comp_id
							AND ticl.coslis_id	= tcppr.coslis_id
							AND ticl.item_id	= tmp.item_id

							LEFT JOIN tbsysCurrency					sc4Cost			WITH (NOLOCK) --tc
							ON	sc4Cost.curr_id		= ticl.curr_id

							LEFT JOIN tbPriceList					tpl				WITH (NOLOCK)
							ON	tpl.comp_id		= ti.comp_id
							AND tpl.prli_id		= tcppr.prli_id

							LEFT JOIN tbPriceListItems				tpli			WITH (NOLOCK)
							ON	tpli.comp_id	= ti.comp_id
							AND tpli.prli_id	= tcppr.prli_id
							AND tpli.item_id	= tmp.item_id

							LEFT JOIN tbsysCurrency					tc1				WITH (NOLOCK)
							ON	tc1.curr_id		= tpli.curr_id

							INNER JOIN tbsysCurrency					sc4Item			WITH (NOLOCK)
							ON	sc4Item.curr_id	= ti.curr_id

					ORDER BY	tmp.tmp_id,tcppr.cppr_order


				DECLARE @curCostCurrency	AS NVARCHAR(100) = ''
				DECLARE @curCost			AS DECIMAL(19,6) = 0
				DECLARE @curCostAW			AS DECIMAL(19,6) = 0
				DECLARE @curPriceCurrency	AS NVARCHAR(100) = ''
				DECLARE @curPrice			AS DECIMAL(19,8) = 0
				DECLARE @curMarkUp			AS DECIMAL(19,8) = 0



				OPEN cursor_updatecostlist




				FETCH NEXT FROM cursor_updatecostlist
				INTO	@tmp_id,
						@litem_id,
						@costlist_desc,
						@value,
						@value_aw,
						@lcoslis_isAW,
						@ItemPercentNumber,
						@curMarkUp,
						@prli_desc,
						@value_price,
						@item_ifHasItemAssociationSumPrices,
						@curCostCurrency,
						@curCost,
						@curCostAW,
						@curPriceCurrency,
						@curPrice



				WHILE @@FETCH_STATUS = 0
				BEGIN




					-- =================================================================================================================
					-- armado de nombre de columna a actualizar con descripciones de lista de costo / markup / lista de precios
					--SET @columns = ''

					--IF @lcoslis_isAW = 'true'
					--	SET @columns = @costlist_desc + ' ' + @lcostdesc_pp
					--ELSE
					--	SET @columns = @costlist_desc

					--SELECT @columns = @columns	+ ' - ' + 'MarkUp ' + convert(varchar,@ItemPercentNumber) + ' - ' + @prli_desc
					-- =================================================================================================================


					-- Columnas, armado de Nombres
					SET @columnsCost = ''
					IF @lcoslis_isAW = 'true'
						SET @columnsCost = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' '  + @costlist_desc + ' ' + @lcostdesc_pp
					ELSE
						SET @columnsCost = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' ' + @costlist_desc

					SET @columnsCostCurr = ''
					SET @columnsCostCurr = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' ' + 'CostCu'

					SET @columnsPerc = ''
					SET @columnsPerc = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' ' + 'MarkUp'

					SET @columnsPrice = ''
					SET @columnsPrice  = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' ' + @prli_desc

					SET @columnsPriceCurr = ''
					SET @columnsPriceCurr = '#' + CONVERT(VARCHAR,@ItemPercentNumber) + ' ' + 'PriceCu'






					-- =================================================================================================================
					-- armado de valores a actualizar con lista de costo / markup / lista de precios
					--SET @values = ''

					--IF @lcoslis_isAW = 'true'
					--	BEGIN
					--		SET @decCost = @value_aw
					--	END
					--ELSE
					--	BEGIN
					--		SET @decCost = @value
					--	END



				--	SELECT @values = @values + ' - ' + @MarkUp + ' - ' + @value_price
					-- =================================================================================================================



					DECLARE @tmpCostAW			AS NVARCHAR(100) = CONVERT(NVARCHAR(100),@curCostAW)
					DECLARE @tmpCost			AS NVARCHAR(100) = CONVERT(NVARCHAR(100),@curCost)
					DECLARE @tmpCostCurrency	AS NVARCHAR(100) = CONVERT(NVARCHAR(100),@curCostCurrency)
					DECLARE @tmpMarkUp			AS NVARCHAR(100) = CONVERT(NVARCHAR(100),@curMarkUp)
					DECLARE @tmpPrice			AS NVARCHAR(100) = CONVERT(NVARCHAR(100),@curPrice)
					DECLARE @tmpPriceCurrency	AS NVARCHAR(100) = CONVERT(NVARCHAR(100),@curPriceCurrency)






					--EXEC ('update #tmpPriceCostData set [' + @columns +	'] = ''' + @values	+ ''' WHERE tmp_id = ''' + @tmp_id + '''')

					IF @lcoslis_isAW = 'true'
						EXEC ('update #tmpPriceCostData set [' + @columnsCost  +	'] = '''	+ @tmpCostAW			+ ''' WHERE tmp_id = ''' + @tmp_id + '''')
					ELSE
						EXEC ('update #tmpPriceCostData set [' + @columnsCost  +	'] = '''	+ @tmpCost				+ ''' WHERE tmp_id = ''' + @tmp_id + '''')

					EXEC ('update #tmpPriceCostData set [' + @columnsCostCurr +	'] = '''		+ @tmpCostCurrency		+ ''' WHERE tmp_id = ''' + @tmp_id + '''')

					EXEC ('update #tmpPriceCostData set [' + @columnsPerc  +	'] = '''		+ @tmpMarkUp			+ ''' WHERE tmp_id = ''' + @tmp_id + '''')
					EXEC ('update #tmpPriceCostData set [' + @columnsPrice +	'] = '''		+ @tmpPrice				+ ''' WHERE tmp_id = ''' + @tmp_id + '''')
					EXEC ('update #tmpPriceCostData set [' + @columnsPriceCurr +	'] = '''	+ @tmpPriceCurrency		+ ''' WHERE tmp_id = ''' + @tmp_id + '''')



					FETCH NEXT FROM cursor_updatecostlist
					INTO	@tmp_id,
							@litem_id,
							@costlist_desc,
							@value,
							@value_aw,
							@lcoslis_isAW,
							@ItemPercentNumber,
							@curMarkUp ,
							@prli_desc,
							@value_price,
							@item_ifHasItemAssociationSumPrices,
							@curCostCurrency,
							@curCost,
							@curCostAW,
							@curPriceCurrency,
							@curPrice

				END

				CLOSE cursor_updatecostlist
				DEALLOCATE cursor_updatecostlist

	END



	-- =================================================================================================================
	-- se recuperan todos los datos que se cargaron en la tabla temporal ordenados por descripción de artículos
	UPDATE #tmpPriceCostData
		SET LastUpdated = 'True'
		FROM #tmpPriceCostData tmp
		INNER JOIN tbItem ti					WITH (NOLOCK)
			ON	ti.comp_id		= @comp_id AND
				ti.item_id		= tmp.item_id
		INNER JOIN tbItemLastUpdated tilu		WITH (NOLOCK)
			ON	tilu.comp_id = ti.comp_id AND
				tilu.item_id = ti.item_id



	SELECT	' ' [ ], ' ' [ ], ' ' [ ], *
	FROM	#tmpPriceCostData

	ORDER BY RowNumber



	-- =================================================================================================================
	-- se recupera la cantidad de registros de toda la consulta
	-- Ref #1
	SELECT	COUNT(1)
		FROM	tbItem									ti			WITH (NOLOCK)
		INNER JOIN #tblComplexFilter_Items tmpi
			ON tmpi.item_id = ti.item_id
				--** IDEm EN ESTE TAG
		--INNER JOIN vwItems_ParentStatus vwr					WITH (NOLOCK)
		--	ON		vwr.comp_id = ti.comp_id
		--		AND vwr.item_id = ti.item_id
		WHERE	ti.comp_id					= @comp_id
		--AND		(@item_recentlyPurchased	= -1 or isnull(ti.item_recentlyPurchased,'false')	= @item_recentlyPurchased)
		--AND		(
		--				@itemclass = -1
		--			OR  (@itemclass = 1 AND vwr.[Master]	= 1)
		--			OR	(@itemclass = 2 AND vwr.Slave		= 1)
		--		)


--		AND		(@item_id					= -1 OR ti.item_id									= @item_id	)
--		AND		(@cat_id					= -1 OR ti.cat_id									= @cat_id	)
--		AND		(@supp_id					= -1 OR ti.supp_id									= @supp_id )
--		AND		(@subcat_id					= -1 OR ti.subcat_id								= @subcat_id)
--		AND		(@brand_id					= -1 OR ti.brand_id									= @brand_id	)
--		AND		(@pres_id					= -1 OR ti.pres_id									= @pres_id	)
--		AND		(@item_disabled				= -1 OR ti.item_disabled							= @item_disabled)
--		AND		(@item_disabledInPriceList	= -1 OR ti.item_disabledInPriceList					= @item_disabledInPriceList)


	DROP TABLE #tblComplexFilter_Items
	DROP TABLE #tmpPriceCostData
END
GO








CREATE PROCEDURE [dbo].[spCostPricePercentRelation_getDataByFiltersOLD]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@guid							NVARCHAR(50),
	@item_recentlyPurchased			INT,
	@itemclass						INT,
	@page_size						INT,	-- #1
	@page_number					INT	,	-- #1
	@order							nvarchar(max),
	@bitViewTotals					BIT
)
AS



BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	-- =================================================================================================================
	-- Testing
	-- =================================================================================================================
	/*
	DECLARE @comp_id					INT,
			@lang_id					INT,
			@bra_id						INT,
			@item_id					INT,
			@cat_id						INT,
			@subcat_id					INT,
			@pres_id					INT,
			@brand_id					INT,
			@item_disabled				INT,
			@item_disabledInPriceList	INT,
			@item_recentlyPurchased		INT,
			@page_size					INT,
			@page_number				INT,
			@itemclass					int,
			@supp_id					INT,
			@order					NVARCHAR(MAX),
			@guid							NVARCHAR(50),
			@bitViewTotals					BIT

	SELECT	@comp_id					= 1,
			@lang_id					= 2,
			@bra_id						= 1,
			@item_id					= -1,
			@cat_id						= -1,
			@subcat_id					= -1,
			@pres_id					= -1,
			@brand_id					= -1,
			@item_disabled				= -1,
			@item_disabledInPriceList	= -1,
			@item_recentlyPurchased		= -1,
			@page_size					= 15,
			@page_number				= 2,
			@itemclass					= -1,
			@supp_id					= -1,
			@order						= '',
			@guid						= '3F2504E0-4F89-11D3-9A0C-0305E82C3301',
			@bitViewTotals				= 1

	DROP TABLE #tmpPriceCostData
	*/
	-- =================================================================================================================


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros
	-- NOTA: Para buscar todas las incidencias
	-- de este método ejecutar el "BuscarTexto" en la base de datos
	-- con el valor de referencia "#8600"
	-- Página de EJEMPLO:App_Reports_App_WebForms_wfmRptFilters_PriceLists2_Testing
	-- -------------------------------------------------------------
	DECLARE @objGUID AS UNIQUEIDENTIFIER
	SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@guid)

	CREATE TABLE #tblComplexFilter_Items ([item_id] INT PRIMARY KEY)
	CREATE NONCLUSTERED INDEX #tblComplexFilter_Items ON #tblComplexFilter_Items
						(
						item_id
						)
	--DECLARE #tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO #tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf		WITH (NOLOCK)
			WHERE tcf.sl_guid = @objGUID     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO #tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti	WITH (NOLOCK)
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

	DECLARE @bitTrue AS BIT
	DECLARE @bitFalse AS BIT
	SET @bitTrue = 1
	SET @bitFalse = 0


	-- Si solo trae los Ultimos Comprados entonces solo deja esos en la tabla temporal.
	IF @item_recentlyPurchased <> -1
		BEGIN
			DECLARE @bitRecPur AS BIT
			IF @item_recentlyPurchased = 0
				BEGIN
					SET @bitRecPur =  1
				END
			ELSE
				BEGIN
					SET @bitRecPur =  0
				END


			DELETE #tblComplexFilter_Items
				FROM #tblComplexFilter_Items tmp
				INNER JOIN tbItem ti		WITH (NOLOCK)
					ON	ti.comp_id	 = @comp_id		AND
						ti.item_id	 = tmp.item_id
			WHERE	ti.item_recentlyPurchased = @bitRecPur
		END


	-- Solo trae lo q corresponda segun talles y colores.
	IF @itemclass <> -1
		BEGIN
			DELETE #tblComplexFilter_Items
				FROM #tblComplexFilter_Items tmp
				INNER JOIN vwItems_ParentStatus vwr							WITH (NOLOCK)
					ON		vwr.comp_id = @comp_id		AND
							vwr.item_id = tmp.item_id
				WHERE
					CASE
   						WHEN @itemclass = 1 AND vwr.[Master]	= 1 THEN 1
   						WHEN @itemclass = 2 AND vwr.Slave		= 1 THEN 1
   						ELSE 0
   					END	= 0
		END



	IF	@order NOT LIKE '%item_id%' AND
		@order NOT LIKE '%item_code%' AND
		@order NOT LIKE '%item_desc%' AND
		@order NOT LIKE '%item_disabled%' AND
		@order NOT LIKE '%item_disabledInPriceList%' AND
		@order NOT LIKE '%item_purOrd_Disc1%' AND
		@order NOT LIKE '%item_purOrd_Disc2%' AND
		@order NOT LIKE '%item_purOrd_Disc3%' AND
		@order NOT LIKE '%item_purOrd_Disc4%'
		BEGIN
			SET @order = ''
		END


	IF @bitViewTotals = 'False'
		BEGIN


			IF @order = ''
				BEGIN
					SET @order = 'ti.cat_id,ti.subcat_id,ti.item_desc ASC'
				END



			DECLARE @strExecute2 AS NVARCHAR(MAX)

			SET @strExecute2 = '
			SELECT	'''' [ ], '''' [ ], '''' [ ],
					convert(bit,
					CASE
						WHEN tilu.comp_id IS NULL THEN 0
						ELSE						   1
					END	)[lastUpdated],
					ROW_NUMBER() OVER ( order BY ' + @order + '   ) AS RowNumber,
					ti.item_code,
					ti.item_desc,
					ti.item_disabled,				-- Parte: 677
						ti.item_disabledInPriceList,	-- Parte: 677
						CASE WHEN  ti.item_purOrd_Disc1 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_Disc1)	END  [item_purOrd_Disc1],
						CASE WHEN  ti.item_purOrd_Disc2 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_Disc2)	END	 [item_purOrd_Disc2],
						CASE WHEN  ti.item_purOrd_Disc3 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_Disc3)	END	 [item_purOrd_Disc3],
						CASE WHEN  ti.item_purOrd_Disc4 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_Disc4)	END	 [item_purOrd_Disc4],
						CASE WHEN  ti.item_purOrd_surcharge1 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_surcharge1) END	 [item_purOrd_surcharge1],
						CASE WHEN  ti.item_purOrd_surcharge2 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_surcharge2) END	 [item_purOrd_surcharge2],
						CASE WHEN  ti.item_purOrd_surcharge3 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_surcharge3) END	 [item_purOrd_surcharge3],
						CASE WHEN  ti.item_purOrd_surcharge4 > 999 THEN -1 ELSE  convert(decimal(6,2),ti.item_purOrd_surcharge4) END	 [item_purOrd_surcharge4],

			      	ti.item_id
			FROM tbItem ti							WITH (NOLOCK)
			INNER JOIN #tblComplexFilter_Items tmp
				ON tmp.item_id = ti.item_id
			LEFT JOIN tbItemLastUpdated tilu		WITH (NOLOCK)
				ON	tilu.comp_id = ti.comp_id AND
					tilu.item_id = ti.item_id

			ORDER BY ' + @order -- ti.cat_id,ti.subcat_id,ti.item_desc ASC

			EXEC (@strExecute2)


			SELECT	COUNT(*)
				FROM tbItem ti						WITH (NOLOCK)
				INNER JOIN #tblComplexFilter_Items tmp
					ON tmp.item_id = ti.item_id


			drop table #tblComplexFilter_Items
			return

		END





	IF	@order NOT LIKE '%item_id%' AND
		@order NOT LIKE '%item_code%' AND
		@order NOT LIKE '%item_desc%' AND
		@order NOT LIKE '%item_disabled%' AND
		@order NOT LIKE '%item_disabledInPriceList%' AND
		@order NOT LIKE '%item_purOrd_Disc1%' AND
		@order NOT LIKE '%item_purOrd_Disc2%' AND
		@order NOT LIKE '%item_purOrd_Disc3%' AND
		@order NOT LIKE '%item_purOrd_Disc4%'
		BEGIN
			SET @order = ''
		END



	-- si no se informa ningun ordenamiento, lo hace por descripcion.
	IF @order = '' SET @order = '[cat_id],[subcat_id],[item_desc] asc'



	-- =================================================================================================================
	-- variables de trabajo
	DECLARE	@prli_desc			VARCHAR(100),
			@costlist_desc		VARCHAR(100),
			@lcoslis_isAW		BIT,
			@tmp_id				INT,
			@value				VARCHAR(100),
			@value_price		VARCHAR(100),
			@value_aw			VARCHAR(100),
			@litem_id			INT,
			@lcostdesc_pp		NVARCHAR(100),
			@ItemPercentNumber	INT,
			@Markup				NVARCHAR(100),
			@columns			NVARCHAR(1000),
			@values				NVARCHAR(1000),
			@qtyTotal			INT,
			@item_ifHasItemAssociationSumPrices	BIT





	-- =================================================================================================================
	-- recuperamos de la tabla de palabras la correspondiente a Costo AW
	SELECT	@lcostdesc_pp	= tswn.word_desc
		FROM	tbSysWordsNew	tswn	WITH (NOLOCK)
		WHERE	tswn.lang_id	= @lang_id
		AND		tswn.wordsi_id	= 393





	-- =================================================================================================================
	-- creación de la tabla temporal con los campos código y descripción de artículos
	CREATE TABLE #tmpPriceCostData
	(
		LastUpdated			BIT,
		RowNumber			INT,
		item_code			NVARCHAR(50),
		item_desc			NVARCHAR(500)
	)





	IF @bitViewTotals = 'True'
		BEGIN




			-- =================================================================================================================
			-- cursor para obtener las descripciones de los costos relacionados a los item de la tabla tbCostPricePercentRelation
			-- y agregar esos nombres como nuevos campos en la temporal #tmpPriceCostData
			DECLARE cursor_costlist CURSOR LOCAL FAST_FORWARD FOR

			SELECT	--DISTINCT
					ticln.coslis_desc,
					tcppr.coslis_isAW,
					tpl.prli_desc,
					tcppr.ItemPercentNumber,
					COUNT_BIG(*)						[qtyTotal]

			FROM	tbItem										ti				WITH (NOLOCK)

					INNER JOIN #tblComplexFilter_Items tmpi
						ON tmpi.item_id = ti.item_id

					INNER JOIN tbCostPricePercentRelation		tcppr			WITH (NOLOCK)  -- era von la vista, se paso a abla y argrego el oder
					ON  tcppr.comp_id	= ti.comp_id
					AND tcppr.bra_id	= @bra_id

					LEFT JOIN tbItemCostListName				ticln			WITH (NOLOCK)
					ON	ticln.comp_id	= ti.comp_id
					AND ticln.coslis_id = tcppr.coslis_id

					LEFT JOIN tbPriceList						tpl				WITH (NOLOCK)
					ON	tpl.comp_id = ti.comp_id
					AND tpl.prli_id = tcppr.prli_id

					--** IDEm EN ESTE TAG
					--INNER JOIN vwItems_ParentStatus vwr							WITH (NOLOCK)
					--	ON		vwr.comp_id = ti.comp_id
					--		AND vwr.item_id = ti.item_id

			WHERE	ti.comp_id						= @comp_id
			--AND		(@item_recentlyPurchased		= -1		or isnull(ti.item_recentlyPurchased,'false')	= @item_recentlyPurchased)
			--AND		CASE
			--			WHEN @itemclass = -1						THEN 1
	  -- 					WHEN @itemclass = 1 AND vwr.[Master]	= 1 THEN 1
	  -- 					WHEN @itemclass = 2 AND vwr.Slave		= 1 THEN 1
	  -- 					ELSE 0
	  -- 				END	= 1
			GROUP BY
					ticln.coslis_desc,
					tcppr.coslis_isAW,
					tpl.prli_desc,
					tcppr.ItemPercentNumber,
					tcppr.cppr_order
			ORDER BY tcppr.cppr_order

			OPEN cursor_costlist

			FETCH NEXT FROM cursor_costlist
			INTO	@costlist_desc,@lcoslis_isAW,@prli_desc,@ItemPercentNumber,@qtyTotal

			WHILE @@FETCH_STATUS = 0
				BEGIN

					-- =================================================================================================================
					-- se arma el nombre de cada campo que se va a crear en la temporal con las descripciones
					-- de lista de costo / markup / lista de precio
					SET @columns = ''

					IF @lcoslis_isAW = 'true'
						SET @columns = @costlist_desc + ' ' + @lcostdesc_pp
					ELSE
						SET @columns = @costlist_desc

					SELECT @columns = @columns	+ ' - ' + 'MarkUp ' + convert(varchar,@ItemPercentNumber) + ' - ' + @prli_desc
					-- =================================================================================================================


					EXEC ('alter table #tmpPriceCostData add [' + @columns + '] NVARCHAR(200)')



					FETCH NEXT FROM cursor_costlist
					INTO	@costlist_desc,@lcoslis_isAW,@prli_desc,@ItemPercentNumber,@qtyTotal

				END

			CLOSE cursor_costlist
			DEALLOCATE cursor_costlist

		END




	-- =================================================================================================================
	-- se agregan los campos de id (identity) e item_id a la tabla temporal #tmpPriceCostData
	ALTER TABLE #tmpPriceCostData
		ADD item_disabled				BIT,	-- Parte: 677
			item_disabledInPriceList	BIT,	-- Parte: 677
			item_purOrd_Disc1			DECIMAL(18,4),
			item_purOrd_Disc2			DECIMAL(18,4),
			item_purOrd_Disc3			DECIMAL(18,4),
			item_purOrd_Disc4			DECIMAL(18,4),
			item_purOrd_surcharge1		DECIMAL(18,4),
			item_purOrd_surcharge2		DECIMAL(18,4),
			item_purOrd_surcharge3		DECIMAL(18,4),
			item_purOrd_surcharge4		DECIMAL(18,4),
			tmp_id						INT IDENTITY,
			item_id						INT


	-- =================================================================================================================
	-- aquí se terminó de crear la tabla temporal #tmpPriceCostData con todos los campos correspondientes
	-- =================================================================================================================



	-- ---------------------------------------------------------------------------------------------------------------
	-- Se insertan los items ORDENADOS en la tabla temporal MOS 12-2013
	-- ---------------------------------------------------------------------------------------------------------------
	DECLARE @strExecute AS VARCHAR(MAX)
	BEGIN TRY
		-- Si hay un problema de ordenamiento se pasa el orden por defecto!
		SET @strExecute =
		'
					SELECT	DISTINCT
						ti.item_id,
						ti.item_code,
						ti.item_desc,
						ti.item_disabled,				-- Parte: 677
						ti.item_disabledInPriceList,	-- Parte: 677
						ti.item_purOrd_Disc1,
						ti.item_purOrd_Disc2,
						ti.item_purOrd_Disc3,
						ti.item_purOrd_Disc4,
						ti.item_purOrd_surcharge1,
						ti.item_purOrd_surcharge2,
						ti.item_purOrd_surcharge3,
						ti.item_purOrd_surcharge4,
						ROW_NUMBER() OVER ( order by ' + @order + '   ) AS RowNumber

					FROM	tbItem									ti  WITH (NOLOCK)

						INNER JOIN #tblComplexFilter_Items tmpi
							ON tmpi.item_id = ti.item_id

						LEFT JOIN tbItemStorage						tis	WITH (NOLOCK)
							ON	tis.comp_id = ti.comp_id
							AND tis.item_id = ti.item_id
							AND tis.stor_id = (select bb.stor_id from tbBranch bb where bb.comp_id = ' + convert(nvarchar(10),@comp_id) + ' and bb.bra_id = ' + convert(nvarchar(10),@bra_id) + ')



					WHERE	ti.comp_id					= '				+ convert(nvarchar(10),@comp_id)




						----** IDEm EN ESTE TAG
						--INNER JOIN vwItems_ParentStatus vwr				WITH (NOLOCK)
						--	ON		vwr.comp_id = ti.comp_id
						--		AND vwr.item_id = ti.item_id
					--AND		(
					--			'  + convert(nvarchar(10),@itemclass) + ' = -1
					--		OR  (' + convert(nvarchar(10),@itemclass) + ' = 1 AND vwr.[Master]	= 1)
					--		OR	(' + convert(nvarchar(10),@itemclass) + ' = 2 AND vwr.Slave		= 1)
					--	)
--AND		(' + convert(nvarchar(10),@item_recentlyPurchased)   + '	= -1 OR isnull(ti.item_recentlyPurchased,''false'')	= ' + convert(nvarchar(10),@item_recentlyPurchased)   + ')

--					AND		(' + convert(nvarchar(10),@item_id)			+ '	= -1 OR ti.item_id									= '  + convert(nvarchar(10),@item_id)		+ ')
--					AND		(' + convert(nvarchar(10),@cat_id)			+ '	= -1 OR ti.cat_id									= '  + convert(nvarchar(10),@cat_id)		+ ')
--					AND		(' + convert(nvarchar(10),@supp_id)			+ '	= -1 OR ti.supp_id									= '  + convert(nvarchar(10),@supp_id)		+ ')
--					AND		(' + convert(nvarchar(10),@subcat_id)		+ '	= -1 OR ti.subcat_id								= '  + convert(nvarchar(10),@subcat_id)		+ ')
--					AND		(' + convert(nvarchar(10),@brand_id)		+ '	= -1 OR ti.brand_id									= '  + convert(nvarchar(10),@brand_id)		+ ')
--					AND		(' + convert(nvarchar(10),@pres_id)			+ '	= -1 OR ti.pres_id									= '  + convert(nvarchar(10),@pres_id)		+ ')
--					AND		(' + convert(nvarchar(10),@item_disabled)	+ '	= -1 OR ti.item_disabled							= '  + convert(nvarchar(10),@item_disabled) + ')
--					AND		(' + convert(nvarchar(10),@item_disabledInPriceList) + '	= -1 OR ti.item_disabledInPriceList					= ' + convert(nvarchar(10),@item_disabledInPriceList) + ')



		INSERT INTO	#tmpPriceCostData
			(
				item_id,
				item_code,
				item_desc,
				item_disabled,
				item_disabledInPriceList,
				item_purOrd_Disc1,
				item_purOrd_Disc2,
				item_purOrd_Disc3,
				item_purOrd_Disc4,
				item_purOrd_surcharge1,
				item_purOrd_surcharge2,
				item_purOrd_surcharge3,
				item_purOrd_surcharge4,
				RowNumber

			)
			EXEC (@strExecute)


	END TRY
	-- Idem pero con orden por defecto
	BEGIN CATCH
		SET @order = '[cat_id],[subcat_id],[item_desc] asc'
		SET @strExecute =
		'
					SELECT	DISTINCT
						ti.item_id,
						ti.item_code,
						ti.item_desc,
						ti.item_disabled,				-- Parte: 677
						ti.item_disabledInPriceList,	-- Parte: 677
						ti.item_purOrd_Disc1,
						ti.item_purOrd_Disc2,
						ti.item_purOrd_Disc3,
						ti.item_purOrd_Disc4,
						ti.item_purOrd_surcharge1,
						ti.item_purOrd_surcharge2,
						ti.item_purOrd_surcharge3,
						ti.item_purOrd_surcharge4,
						ROW_NUMBER() OVER ( order by ' + @order + '   ) AS RowNumber

					FROM	tbItem									ti  WITH (NOLOCK)

						INNER JOIN #tblComplexFilter_Items tmpi
							ON tmpi.item_id = ti.item_id

						LEFT JOIN tbItemStorage						tis	WITH (NOLOCK)
							ON	tis.comp_id = ti.comp_id
							AND tis.item_id = ti.item_id
							AND tis.stor_id = (select bb.stor_id from tbBranch bb where bb.comp_id = ' + convert(nvarchar(10),@comp_id) + ' and bb.bra_id = ' + convert(nvarchar(10),@bra_id) + ')
					WHERE	ti.comp_id					= '				+ convert(nvarchar(10),@comp_id)

					--AND		(
					--			'  + convert(nvarchar(10),@itemclass) + ' = -1
					--		OR  (' + convert(nvarchar(10),@itemclass) + ' = 1 AND vwr.[Master]	= 1)
					--		OR	(' + convert(nvarchar(10),@itemclass) + ' = 2 AND vwr.Slave		= 1)
					--	)
						----** IDEm EN ESTE TAG
						--INNER JOIN vwItems_ParentStatus vwr				WITH (NOLOCK)
						--	ON		vwr.comp_id = ti.comp_id
						--		AND vwr.item_id = ti.item_id

-- AND		(' + convert(nvarchar(10),@item_recentlyPurchased)   + '	= -1 OR isnull(ti.item_recentlyPurchased,''false'')	= ' + convert(nvarchar(10),@item_recentlyPurchased)   + ')
--					AND		(' + convert(nvarchar(10),@item_id)			+ '	= -1 OR ti.item_id									= '  + convert(nvarchar(10),@item_id)		+ ')
--					AND		(' + convert(nvarchar(10),@cat_id)			+ '	= -1 OR ti.cat_id									= '  + convert(nvarchar(10),@cat_id)		+ ')
--					AND		(' + convert(nvarchar(10),@supp_id)			+ '	= -1 OR ti.supp_id									= '  + convert(nvarchar(10),@supp_id)		+ ')
--					AND		(' + convert(nvarchar(10),@subcat_id)		+ '	= -1 OR ti.subcat_id								= '  + convert(nvarchar(10),@subcat_id)		+ ')
--					AND		(' + convert(nvarchar(10),@brand_id)		+ '	= -1 OR ti.brand_id									= '  + convert(nvarchar(10),@brand_id)		+ ')
--					AND		(' + convert(nvarchar(10),@pres_id)			+ '	= -1 OR ti.pres_id									= '  + convert(nvarchar(10),@pres_id)		+ ')
--					AND		(' + convert(nvarchar(10),@item_disabled)	+ '	= -1 OR ti.item_disabled							= '  + convert(nvarchar(10),@item_disabled) + ')
--					AND		(' + convert(nvarchar(10),@item_disabledInPriceList) + '	= -1 OR ti.item_disabledInPriceList					= ' + convert(nvarchar(10),@item_disabledInPriceList) + ')



		INSERT INTO	#tmpPriceCostData
			(
				item_id,
				item_code,
				item_desc,
				item_disabled,
				item_disabledInPriceList,
				item_purOrd_Disc1,
				item_purOrd_Disc2,
				item_purOrd_Disc3,
				item_purOrd_Disc4,
				item_purOrd_surcharge1,
				item_purOrd_surcharge2,
				item_purOrd_surcharge3,
				item_purOrd_surcharge4,
				RowNumber

			)
			EXEC (@strExecute)

	END CATCH






	DELETE FROM #tmpPriceCostData
		WHERE NOT (RowNumber BETWEEN (@page_size * @page_number + 1) AND (@page_size * (@page_number + 1)))
	-- ---------------------------------------------------------------------------------------------------------------


	-- =================================================================================================================
	-- Parte		: S/P Ref #1
	-- se insertan todos los registros que van a componer la tabla temporal con los datos de los artículos pero sólo de
	-- registros que componen la página consultada
/*
	;WITH resultado_total AS
	(
		SELECT	DISTINCT
				ti.item_id,
				ti.item_code,
				ti.item_desc,
				ti.item_disabled,				-- Parte: 677
				ti.item_disabledInPriceList,	-- Parte: 677
				ROW_NUMBER() OVER ( order by (@order) asc  ) AS RowNumber

		FROM	tbItem									ti

			LEFT JOIN tbItemStorage						tis
				ON	tis.comp_id = ti.comp_id
				AND tis.item_id = ti.item_id
				AND tis.stor_id = (select bb.stor_id from tbBranch bb where bb.comp_id = @comp_id and bb.bra_id = @bra_id)

			--** IDEm EN ESTE TAG
			INNER JOIN vwItems_ParentStatus vwr
				ON		vwr.comp_id = ti.comp_id
