		AND		(@item_disabled				= -1 OR ti.item_disabled							= @item_disabled)	-- Parte: 677
		AND		(@item_disabledInPriceList	= -1 OR ti.item_disabledInPriceList					= @item_disabledInPriceList) -- Parte: 677
		AND		(@item_recentlyPurchased	= -1 or isnull(ti.item_recentlyPurchased,'false')	= @item_recentlyPurchased)
		AND		(
					@itemclass = -1
				OR  (@itemclass = 1 AND vwr.[Master]	= 1)
				OR	(@itemclass = 2 AND vwr.Slave		= 1)
			)


		--ORDER BY ti.item_desc
	)
	INSERT INTO	#tmpPriceCostData
	(
		item_id,
		item_code,
		item_desc,
		item_disabled,
		item_disabledInPriceList,
		RowNumber

	)
	SELECT	item_id,item_code,item_desc,item_disabled,item_disabledInPriceList, RowNumber
			FROM resultado_total
		WHERE RowNumber BETWEEN (@page_size * @page_number + 1) AND (@page_size * (@page_number + 1))
	*/
	--***********************************************************************************************************************************



	IF @bitViewTotals = 'True'
		BEGIN


				-- =================================================================================================================
				-- se recuperan todos los datos necesarios para mostrar en la consulta
				DECLARE cursor_updatecostlist CURSOR LOCAL FAST_FORWARD FOR

				SELECT	tmp.tmp_id,
						tmp.item_id,
						LTRIM(RTRIM(ticln.coslis_desc))														[coslis_desc],
						LTRIM(RTRIM(ISNULL(sc4Cost.curr_symbol,''))) + ' ' +
								CONVERT(VARCHAR, convert(decimal(20,4),ISNULL(ticl.coslis_price,0)))		[coslis_price],
						LTRIM(RTRIM(ISNULL(sc4Cost.curr_symbol,''))) + ' ' +
								CONVERT(VARCHAR, convert(decimal(20,4),ISNULL(ticl.coslis_price_aw,0)))		[coslis_price_aw],
						tcppr.coslis_isAW,

						tcppr.ItemPercentNumber,

						'% ' +

						CASE
							WHEN IsNull(tcppr.cppr_RecalculatePercent,'True') = 'True' OR ti.item_ifHasItemAssociationSumPrices = 'True' THEN
												CONVERT(VARCHAR,convert(decimal(19,4),
														dbo.fngetMarkUp(
																		CASE WHEN tcppr.coslis_isAW = 'true' THEN
																				isnull(ticl.coslis_price_aw,0)
																			ELSE
																				isnull(ticl.coslis_price,0)
																		END,
																		CASE
																			when tpli.prli_price IS NULL THEN 0
																			ELSE

																					dbo.fnGetExchange2( @comp_id,
																										tpli.prli_price,
																										tpli.curr_id,
 																										CASE
 																											WHEN ticl.curr_id IS NULL THEN
																												ti.curr_id
																											ELSE
																												ticl.curr_id
																										END,
																										0,
																										0,
																										0,
																										'false')
																		END
																		)	))

							ELSE
								CASE
									WHEN tcppr.ItemPercentNumber = 1 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_1))
									WHEN tcppr.ItemPercentNumber = 2 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_2))
									WHEN tcppr.ItemPercentNumber = 3 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_3))
									WHEN tcppr.ItemPercentNumber = 4 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_4))
									WHEN tcppr.ItemPercentNumber = 5 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_5))
									WHEN tcppr.ItemPercentNumber = 6 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_6))
									WHEN tcppr.ItemPercentNumber = 7 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_7))
									WHEN tcppr.ItemPercentNumber = 8 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_8))
									WHEN tcppr.ItemPercentNumber = 9 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_9))
									WHEN tcppr.ItemPercentNumber = 10 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_10))
									WHEN tcppr.ItemPercentNumber = 11 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_11))
									WHEN tcppr.ItemPercentNumber = 12 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_12))
									WHEN tcppr.ItemPercentNumber = 13 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_13))
									WHEN tcppr.ItemPercentNumber = 14 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_14))
									WHEN tcppr.ItemPercentNumber = 15 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_15))
									WHEN tcppr.ItemPercentNumber = 16 THEN CONVERT(VARCHAR,convert(decimal(20,2),ti.item_markup_16))
								END
						END
																											[MarkUp],

						LTRIM(RTRIM(tpl.prli_desc))															[prli_desc],
						LTRIM(RTRIM(ISNULL(tc1.curr_symbol,''))) + ' ' +
								CONVERT(VARCHAR,(ISNULL(tpli.prli_price,0)))			[prli_price],
								ISNULL(ti.item_ifHasItemAssociationSumPrices,'False')	[item_ifHasItemAssociationSumPrices]

					FROM	#tmpPriceCostData						tmp

							INNER JOIN tbItem						ti				WITH (NOLOCK)
							ON  ti.comp_id		= @comp_id
							AND ti.item_id		= tmp.item_id

							INNER JOIN tbCostPricePercentRelation	tcppr			WITH (NOLOCK)
							ON	tcppr.comp_id	= ti.comp_id
							AND tcppr.bra_id	= @bra_id

							LEFT JOIN tbItemCostListName			ticln			WITH (NOLOCK)
							ON	ticln.comp_id	= ti.comp_id
							AND ticln.coslis_id = tcppr.coslis_id

							LEFT JOIN tbItemCostList				ticl			WITH (NOLOCK)
							ON	ticl.comp_id	= ti.comp_id
							AND ticl.coslis_id	= tcppr.coslis_id
							AND ticl.item_id	= tmp.item_id

							LEFT JOIN tbsysCurrency					sc4Cost			WITH (NOLOCK) --tc
							ON	sc4Cost.curr_id		= ticl.curr_id

							LEFT JOIN tbPriceList					tpl				WITH (NOLOCK)
							ON	tpl.comp_id		= ti.comp_id
							AND tpl.prli_id		= tcppr.prli_id

							LEFT JOIN tbPriceListItems				tpli			WITH (NOLOCK)
							ON	tpli.comp_id	= ti.comp_id
							AND tpli.prli_id	= tcppr.prli_id
							AND tpli.item_id	= tmp.item_id

							LEFT JOIN tbsysCurrency					tc1				WITH (NOLOCK)
							ON	tc1.curr_id		= tpli.curr_id

							INNER JOIN tbsysCurrency					sc4Item			WITH (NOLOCK)
							ON	sc4Item.curr_id	= ti.curr_id

					ORDER BY	tmp.tmp_id,tcppr.cppr_order






				OPEN cursor_updatecostlist

				FETCH NEXT FROM cursor_updatecostlist
				INTO	@tmp_id,
						@litem_id,
						@costlist_desc,
						@value,
						@value_aw,
						@lcoslis_isAW,
						@ItemPercentNumber,
						@MarkUp,
						@prli_desc,
						@value_price,
						@item_ifHasItemAssociationSumPrices



				WHILE @@FETCH_STATUS = 0
				BEGIN

					-- =================================================================================================================
					-- armado de nombre de columna a actualizar con descripciones de lista de costo / markup / lista de precios
					SET @columns = ''

					IF @lcoslis_isAW = 'true'
						SET @columns = @costlist_desc + ' ' + @lcostdesc_pp
					ELSE
						SET @columns = @costlist_desc

					SELECT @columns = @columns	+ ' - ' + 'MarkUp ' + convert(varchar,@ItemPercentNumber) + ' - ' + @prli_desc
					-- =================================================================================================================


					-- =================================================================================================================
					-- armado de valores a actualizar con lista de costo / markup / lista de precios
					SET @values = ''

					IF @lcoslis_isAW = 'true'
						BEGIN
							SET @values = @value_aw
						END
					ELSE
						BEGIN
							SET @values = @value
						END



					SELECT @values = @values + ' - ' + @MarkUp + ' - ' + @value_price
					-- =================================================================================================================



					EXEC ('update #tmpPriceCostData set [' + @columns +	'] = ''' + @values	+ ''' WHERE tmp_id = ''' + @tmp_id + '''')



					FETCH NEXT FROM cursor_updatecostlist
					INTO	@tmp_id,
							@litem_id,
							@costlist_desc,
							@value,
							@value_aw,
							@lcoslis_isAW,
							@ItemPercentNumber,
							@MarkUp,
							@prli_desc,
							@value_price,
							@item_ifHasItemAssociationSumPrices

				END

				CLOSE cursor_updatecostlist
				DEALLOCATE cursor_updatecostlist

	END



	-- =================================================================================================================
	-- se recuperan todos los datos que se cargaron en la tabla temporal ordenados por descripción de artículos
	UPDATE #tmpPriceCostData
		SET LastUpdated = 'True'
		FROM #tmpPriceCostData tmp
		INNER JOIN tbItem ti					WITH (NOLOCK)
			ON	ti.comp_id		= @comp_id AND
				ti.item_id		= tmp.item_id
		INNER JOIN tbItemLastUpdated tilu		WITH (NOLOCK)
			ON	tilu.comp_id = ti.comp_id AND
				tilu.item_id = ti.item_id



	SELECT	' ' [ ], ' ' [ ], ' ' [ ], *
	FROM	#tmpPriceCostData

	ORDER BY RowNumber



	-- =================================================================================================================
	-- se recupera la cantidad de registros de toda la consulta
	-- Ref #1
	SELECT	COUNT(1)
		FROM	tbItem									ti			WITH (NOLOCK)
		INNER JOIN #tblComplexFilter_Items tmpi
			ON tmpi.item_id = ti.item_id
				--** IDEm EN ESTE TAG
		--INNER JOIN vwItems_ParentStatus vwr					WITH (NOLOCK)
		--	ON		vwr.comp_id = ti.comp_id
		--		AND vwr.item_id = ti.item_id
		WHERE	ti.comp_id					= @comp_id
		--AND		(@item_recentlyPurchased	= -1 or isnull(ti.item_recentlyPurchased,'false')	= @item_recentlyPurchased)
		--AND		(
		--				@itemclass = -1
		--			OR  (@itemclass = 1 AND vwr.[Master]	= 1)
		--			OR	(@itemclass = 2 AND vwr.Slave		= 1)
		--		)


--		AND		(@item_id					= -1 OR ti.item_id									= @item_id	)
--		AND		(@cat_id					= -1 OR ti.cat_id									= @cat_id	)
--		AND		(@supp_id					= -1 OR ti.supp_id									= @supp_id )
--		AND		(@subcat_id					= -1 OR ti.subcat_id								= @subcat_id)
--		AND		(@brand_id					= -1 OR ti.brand_id									= @brand_id	)
--		AND		(@pres_id					= -1 OR ti.pres_id									= @pres_id	)
--		AND		(@item_disabled				= -1 OR ti.item_disabled							= @item_disabled)
--		AND		(@item_disabledInPriceList	= -1 OR ti.item_disabledInPriceList					= @item_disabledInPriceList)


	DROP TABLE #tblComplexFilter_Items
	--DROP TABLE #tmpPriceCostData
END
GO








CREATE PROCEDURE [dbo].[spCostPricePercentRelation_getDataByItem]
(
	@comp_id					INT,
	@lang_id					INT,
	@bra_id						INT,
	@item_id					INT
)
AS


BEGIN




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	SET NOCOUNT ON


	/*
	-- =================================================================================================================
	-- variables para pruebas
	DECLARE	@comp_id					INT,
			@lang_id					INT,
			@bra_id						INT,
			@item_id					INT
	SELECT 	@comp_id					=1,
			@lang_id					=2,
			@bra_id						=1,
			@item_id					=256
	-- =================================================================================================================
	*/






	-- =================================================================================================================
	-- recuperamos de la tabla de palabras la correspondiente a Costo AW
	DECLARE @lcostdesc_pp		NVARCHAR(100)
	SELECT	@lcostdesc_pp	= tswn.word_desc
	FROM	tbSysWordsNew	tswn
	WHERE	tswn.lang_id	= @lang_id
	AND		tswn.wordsi_id	= 393





	-- =================================================================================================================
	-- recuperamos de la tabla tbCostPricePercentRelation las relaciones de listas de costos, precios y markup,
	-- relacionados al artículo seleccionado
	SELECT	CASE WHEN tcppr.coslis_isAW = 'true' THEN
					ticln.coslis_desc + ' ' + @lcostdesc_pp
				ELSE
					ticln.coslis_desc
			END												[coslis_desc],
			CASE WHEN tc.curr_symbol IS NULL THEN
					tc3.curr_symbol
				ELSE
					tc.curr_symbol
			END 											[cost_curr_symbol],
			CASE WHEN tcppr.coslis_isAW = 'true' THEN
					isnull(ticl.coslis_price_aw,0)
				ELSE
					isnull(ticl.coslis_price,0)
			END												[coslis_price],
			tcppr.coslis_id,
			isnull(tcppr.coslis_isAW,'false')				[coslis_isAW],
			CASE WHEN tc.curr_id IS NULL THEN
					tc3.curr_id
				ELSE
					tc.curr_id
			END												[cost_curr_id],

				CASE
					WHEN	IsNull(tcppr.cppr_RecalculatePercent,'True') = 'True' OR
							(tcppr.cppr_disableComboCheck = 'False' AND ti.item_ifHasItemAssociationSumPrices = 'True')
																								 THEN
											-- MOS
											dbo.fngetMarkUp(
															CASE WHEN tcppr.coslis_isAW = 'true' THEN
																	isnull(ticl.coslis_price_aw,0)
																ELSE
																	isnull(ticl.coslis_price,0)
															END
															* dbo.fnGetFinalDiscountCoeficient(ti.item_purOrd_Disc1,ti.item_purOrd_Disc2,ti.item_purOrd_Disc3,ti.item_purOrd_Disc4)
															* dbo.fnGetFinalDiscountCoeficient(-ti.item_purOrd_surcharge1,-ti.item_purOrd_surcharge2,-ti.item_purOrd_surcharge3,-ti.item_purOrd_surcharge4)	,
															dbo.fnGetExchange2( @comp_id,
																				isnull(tpli.prli_price,0),
     																			CASE
     																				WHEN tc2.curr_symbol IS NULL THEN
																						tc3.curr_id
																					ELSE
																						tc2.curr_id
																				END,
																				ticl.curr_id,
																				0,
																				0,
																				0,
																				'false')
															)
					ELSE
						CASE


							WHEN tcppr.ItemPercentNumber = 1 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup1
							WHEN tcppr.ItemPercentNumber = 1 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup1
							WHEN tcppr.ItemPercentNumber = 1 AND ti.item_markup_1	IS NOT NULL	THEN ti.item_markup_1

							WHEN tcppr.ItemPercentNumber = 2 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup2
							WHEN tcppr.ItemPercentNumber = 2 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup2
							WHEN tcppr.ItemPercentNumber = 2 AND ti.item_markup_2	IS NOT NULL	THEN ti.item_markup_2

							WHEN tcppr.ItemPercentNumber = 3 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup3
							WHEN tcppr.ItemPercentNumber = 3 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup3
							WHEN tcppr.ItemPercentNumber = 3 AND ti.item_markup_3	IS NOT NULL	THEN ti.item_markup_3

							WHEN tcppr.ItemPercentNumber = 4 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup4
							WHEN tcppr.ItemPercentNumber = 4 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup4
							WHEN tcppr.ItemPercentNumber = 4 AND ti.item_markup_4	IS NOT NULL	THEN ti.item_markup_4

							WHEN tcppr.ItemPercentNumber = 5 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup5
							WHEN tcppr.ItemPercentNumber = 5 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup5
							WHEN tcppr.ItemPercentNumber = 5 AND ti.item_markup_5	IS NOT NULL	THEN ti.item_markup_5

							WHEN tcppr.ItemPercentNumber = 6 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup6
							WHEN tcppr.ItemPercentNumber = 6 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup6
							WHEN tcppr.ItemPercentNumber = 6 AND ti.item_markup_6	IS NOT NULL	THEN ti.item_markup_6

							WHEN tcppr.ItemPercentNumber = 7 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup7
							WHEN tcppr.ItemPercentNumber = 7 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup7
							WHEN tcppr.ItemPercentNumber = 7 AND ti.item_markup_7	IS NOT NULL	THEN ti.item_markup_7

							WHEN tcppr.ItemPercentNumber = 8 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup8
							WHEN tcppr.ItemPercentNumber = 8 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup8
							WHEN tcppr.ItemPercentNumber = 8 AND ti.item_markup_8	IS NOT NULL	THEN ti.item_markup_8

							WHEN tcppr.ItemPercentNumber = 9 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup9
							WHEN tcppr.ItemPercentNumber = 9 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup9
							WHEN tcppr.ItemPercentNumber = 9 AND ti.item_markup_9	IS NOT NULL	THEN ti.item_markup_9

							WHEN tcppr.ItemPercentNumber = 10 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup10
							WHEN tcppr.ItemPercentNumber = 10 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup10
							WHEN tcppr.ItemPercentNumber = 10 AND ti.item_markup_10	IS NOT NULL	THEN ti.item_markup_10

							WHEN tcppr.ItemPercentNumber = 11 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup11
							WHEN tcppr.ItemPercentNumber = 11 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup11
							WHEN tcppr.ItemPercentNumber = 11 AND ti.item_markup_11	IS NOT NULL	THEN ti.item_markup_11

							WHEN tcppr.ItemPercentNumber = 12 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup12
							WHEN tcppr.ItemPercentNumber = 12 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup12
							WHEN tcppr.ItemPercentNumber = 12 AND ti.item_markup_12	IS NOT NULL	THEN ti.item_markup_12

							WHEN tcppr.ItemPercentNumber = 13 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup13
							WHEN tcppr.ItemPercentNumber = 13 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup13
							WHEN tcppr.ItemPercentNumber = 13 AND ti.item_markup_13	IS NOT NULL	THEN ti.item_markup_13

							WHEN tcppr.ItemPercentNumber = 14 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup14
							WHEN tcppr.ItemPercentNumber = 14 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup14
							WHEN tcppr.ItemPercentNumber = 14 AND ti.item_markup_14	IS NOT NULL	THEN ti.item_markup_14

							WHEN tcppr.ItemPercentNumber = 15 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup15
							WHEN tcppr.ItemPercentNumber = 15 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup15
							WHEN tcppr.ItemPercentNumber = 15 AND ti.item_markup_15	IS NOT NULL	THEN ti.item_markup_15

							WHEN tcppr.ItemPercentNumber = 16 AND tplm2.comp_id		IS NOT NULL	THEN tplm2.plm_markup16
							WHEN tcppr.ItemPercentNumber = 16 AND tplm.comp_id		IS NOT NULL	THEN tplm.plm_markup16
							WHEN tcppr.ItemPercentNumber = 16 AND ti.item_markup_16	IS NOT NULL	THEN ti.item_markup_16

							ELSE																	 0


							--WHEN tcppr.ItemPercentNumber = 1 then ti.item_markup_1
							--WHEN tcppr.ItemPercentNumber = 2 then ti.item_markup_2
							--WHEN tcppr.ItemPercentNumber = 3 then ti.item_markup_3
							--WHEN tcppr.ItemPercentNumber = 4 then ti.item_markup_4
							--WHEN tcppr.ItemPercentNumber = 5 then ti.item_markup_5
							--WHEN tcppr.ItemPercentNumber = 6 then ti.item_markup_6
							--WHEN tcppr.ItemPercentNumber = 7 then ti.item_markup_7
							--WHEN tcppr.ItemPercentNumber = 8 then ti.item_markup_8
							--WHEN tcppr.ItemPercentNumber = 9 then ti.item_markup_9
							--WHEN tcppr.ItemPercentNumber = 10 then ti.item_markup_10
							--WHEN tcppr.ItemPercentNumber = 11 then ti.item_markup_11
							--WHEN tcppr.ItemPercentNumber = 12 then ti.item_markup_12
							--WHEN tcppr.ItemPercentNumber = 13 then ti.item_markup_13
							--WHEN tcppr.ItemPercentNumber = 14 then ti.item_markup_14
							--WHEN tcppr.ItemPercentNumber = 15 then ti.item_markup_15
							--WHEN tcppr.ItemPercentNumber = 16 then ti.item_markup_16
						END
				END															[item_markup],

			tcppr.ItemPercentNumber,



			tpl.prli_desc,
			CASE WHEN tc2.curr_symbol IS NULL THEN
					tc3.curr_symbol
				ELSE
					tc2.curr_symbol
			END												[price_curr_symbol],
			isnull(tpli.prli_price,0)						[prli_price],
			tcppr.prli_id,
			CASE WHEN tc2.curr_id IS NULL THEN
					tc3.curr_id
				ELSE
					tc2.curr_id
			END												[price_curr_id],

			CONVERT(BIT,
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN 'false'
				WHEN tplm.comp_id		IS NOT NULL	THEN 'false'
				ELSE									 ISNULL(tcppr.cppr_RecalculatePercent,'false')
			END)											[cppr_RecalculatePercent],  -- Si es con Incremento por TABLA NO se puede hacer el recálculo de markup ya que estan FIJOS en una tabla !!!!!

			IsNull(tcppr.cppr_wucPriceModeFinal,'True')		[cppr_wucPriceModeFinal],
			IsNull(tcppr.cppr_wucCostModeFinal,'True')		[cppr_wucCostModeFinal],
			ISNULL(tcppr.cppr_initialRecalculate,'False')	[cppr_initialRecalculate],
			ISNULL(tcppr.cppr_DiagonalOnENTER,'False')		[cppr_DiagonalOnENTER],
			CONVERT(BIT,
			CASE
				WHEN tplm2.comp_id		IS NOT NULL	THEN 'True'
				WHEN tplm.comp_id		IS NOT NULL	THEN 'True'
				ELSE 'False'
			END)												[DisableMarkUpField],
			ISNULL(
			(SELECT tpd.decCoeficient4Discount
				FROM dbo.fnGetPurchaseDiscount(@comp_id,	CASE
																WHEN ti.pd_id IS NOT NULL THEN ti.pd_id
																WHEN ts.pd_id IS NOT NULL THEN ts.pd_id
																ELSE -1
															END, 2) tpd ),0) * 100		[Percent4Discount],
			ISNULL(
			(SELECT tpd.decCoeficient4Bonification
				FROM dbo.fnGetPurchaseDiscount(@comp_id,	CASE
																WHEN ti.pd_id IS NOT NULL THEN ti.pd_id
																WHEN ts.pd_id IS NOT NULL THEN ts.pd_id
																ELSE -1
															END, 2) tpd ),0) * 100		[Percent4Bonification],
			ISNULL(
			(SELECT tpd.decCoeficient4BonificationCN
				FROM dbo.fnGetPurchaseDiscount(@comp_id,	CASE
																WHEN ti.pd_id IS NOT NULL THEN ti.pd_id
																WHEN ts.pd_id IS NOT NULL THEN ts.pd_id
																ELSE -1
															END, 2) tpd ),0) * 100		[Percent4BonificationCN]		,
			ISNULL(tcppr.cppr_disableComboCheck,'False')								[cppr_disableComboCheck]		,
			ISNULL(ti.item_ifHasItemAssociationSumPrices,'False')						[item_ifHasItemAssociationSumPrices],
			ISNULL(tcppr.cppr_disableDiscountAndSurcharge4Cost,'False')					[cppr_disableDiscountAndSurcharge4Cost]

	FROM	tbCostPricePercentRelation				tcppr						WITH (NOLOCK)

			LEFT JOIN tbItemCostList				ticl						WITH (NOLOCK)
				ON	ticl.comp_id	= tcppr.comp_id
				AND ticl.coslis_id	= tcppr.coslis_id
				AND ticl.item_id	= @item_id
			LEFT JOIN tbItemCostListName			ticln						WITH (NOLOCK)
				ON	ticln.comp_id	= tcppr.comp_id
				AND ticln.coslis_id = tcppr.coslis_id
			LEFT JOIN tbsysCurrency					tc							WITH (NOLOCK)
				ON	tc.curr_id		= ticl.curr_id

			LEFT JOIN tbPriceListItems				tpli						WITH (NOLOCK)
				ON	tpli.comp_id	= tcppr.comp_id
				AND tpli.prli_id	= tcppr.prli_id
				AND tpli.item_id	= @item_id
			LEFT JOIN tbPriceList					tpl							WITH (NOLOCK)
				ON	tpl.comp_id		= tcppr.comp_id
				AND tpl.prli_id		= tcppr.prli_id
			LEFT JOIN tbsysCurrency					tc2							WITH (NOLOCK)
				ON tc2.curr_id		= tpli.curr_id

			LEFT JOIN tbItem						ti							WITH (NOLOCK)
				ON	ti.comp_id		= tcppr.comp_id
				AND ti.item_id		= @item_id

			--recuperamos la moneda del artículo para aquellas listas que no estén creadas
			INNER JOIN tbsysCurrency				tc3							WITH (NOLOCK)
				ON tc3.curr_id		= ti.curr_id

			LEFT JOIN tbPriceListMarkup tplm2									WITH (NOLOCK)
				ON	tplm2.comp_id	= ti.comp_id AND
					tplm2.plm_id	= ti.plm_id
			LEFT JOIN tbPriceListMarkup tplm									WITH (NOLOCK)
				ON	tplm.comp_id	= tcppr.comp_id AND
					tplm.plm_id		= tcppr.plm_id

			LEFT JOIN tbSupplier ts												WITH (NOLOCK)
				ON	ts.comp_id = ti.comp_id AND
					ts.supp_id = ti.supp_id


	WHERE	tcppr.comp_id	= @comp_id
	AND		tcppr.bra_id	= @bra_id

	ORDER BY tcppr.cppr_order



END
GO







CREATE PROCEDURE [dbo].[spCostPricePercentRelation_updateDataByItem]
(
	@comp_id					INT,
	@lang_id					INT,
	@bra_id						INT,

	@item_id					INT,
	@markup_id					INT,
	@markup_value				DECIMAL(19,8),

	@coslis_id					INT,
	@coslist_price				DECIMAL(19,5),
	@coslist_aw					BIT,
	@coscurr_id					INT,

	@prli_id					INT,
	@prli_price					DECIMAL(19,5),
	@prlicurr_id				INT,

	@item_desc					NVARCHAR(100),
	@item_disabled				BIT,
	@item_disabledInPriceList	BIT,
	@item_web					BIT,
	@item_vendorcode			NVARCHAR(100),
	@item_purOrd_Disc1		AS  DECIMAL(19,6),
	@item_purOrd_Disc2		AS  DECIMAL(19,6),
	@item_purOrd_Disc3		AS  DECIMAL(19,6),
	@item_purOrd_Disc4		AS  DECIMAL(19,6),
	@user_id				AS  INT

)
AS


BEGIN

--SELECT 1 / 0


	SET NOCOUNT ON


	/*
	-- =================================================================================================================
	-- variables para pruebas
	DECLARE @comp_id					INT,
			@lang_id					INT,

			@item_id					INT,
			@markup_id					INT,
			@markup_value				INT,

			@coslis_id					INT,
			@coslist_price				DECIMAL(19,5),
			@coslist_aw					BIT,
			@coscurr_id					INT,

			@prli_id					INT,
			@prli_price					DECIMAL(19,5),
			@prlicurr_id				INT,
			@item_desc					NVARCHAR(100),
			@item_disabled				BIT,
			@item_disabledInPriceList	BIT

	SELECT	@comp_id					=1,
			@lang_id					=2,

			@item_id					=285,
			@markup_id					=8,
			@markup_value				=0,

			@coslis_id					=8,
			@coslist_price				=0,
			@coslist_aw					='false',
			@coscurr_id					=1,

			@prli_id					=8,
			@prli_price					=0,
			@prlicurr_id				=1,
			@item_desc					='nueva descripción para probar el sp',
			@item_disabled				='true',
			@item_disabledInPriceList	='true'
	-- =================================================================================================================
	*/




	-- =================================================================================================================
	-- Ref: #1
	-- obtención de marca para igualar costos
	DECLARE @lcppr_matchCosts		BIT

	SELECT	@lcppr_matchCosts	= ISNULL(tcppr.cppr_matchCosts,'false')
		FROM	tbCostPricePercentRelation		tcppr			WITH (NOLOCK)
		WHERE	tcppr.comp_id		= @comp_id
		AND		tcppr.bra_id		= @bra_id
		AND		tcppr.coslis_id		= @coslis_id
		AND		tcppr.prli_id		= @prli_id





	-- =================================================================================================================
	-- actualización del markup correspondiente en la tabla de artículos

	IF @markup_id		= 1
		BEGIN

			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_1	=	@markup_value
				WHERE	comp_id			=	@comp_id	AND
						item_id			=	@item_id	AND
						item_markup_1	<>	@markup_value

		END


	IF @markup_id		= 2
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_2	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_2	<>	@markup_value
		END





	IF @markup_id		= 3
		BEGIN

			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_3	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_3	<>	@markup_value

		END





	IF @markup_id		= 4
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_4	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_4	<>	@markup_value
		END




	IF @markup_id		= 5
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_5	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_5	<>	@markup_value
		END



	IF @markup_id		= 6
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_6	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_6	<>	@markup_value
		END



	IF @markup_id		= 7
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_7	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_7	<>	@markup_value
		END



	IF @markup_id		= 8
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_8	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_8	<>	@markup_value
		END



	IF @markup_id		= 9
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_9	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_9	<>	@markup_value
		END



	IF @markup_id		= 10
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_10	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_10	<>	@markup_value
		END


	IF @markup_id		= 11
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_11	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_11	<>	@markup_value
		END


	IF @markup_id		= 12
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_12	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_12	<>	@markup_value
		END


	IF @markup_id		= 13
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_13	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_13	<>	@markup_value
		END


	IF @markup_id		= 14
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_14	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_14	<>	@markup_value
		END


	IF @markup_id		= 15
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_15	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_15	<>	@markup_value
		END


	IF @markup_id		= 16
		BEGIN
			UPDATE	tbitem			WITH (ROWLOCK)
				SET		item_markup_16	= @markup_value
				WHERE	comp_id			= @comp_id	AND
						item_id			= @item_id	AND
						item_markup_16	<>	@markup_value
		END




	-- =================================================================================================================
	-- actualización de item_desc, item_disabled y item_disabledInPriceList en la tabla de artículos
	-- Parte 740 añadimos los campos a actualizar item_web , item_vendorcode

	UPDATE	tbitem	WITH (ROWLOCK)
		SET		item_desc					= @item_desc,
				item_disabled				= @item_disabled,
				item_disabledInPriceList	= @item_disabledInPriceList,
				item_web					= @item_web,
				item_vendorCode				= @item_vendorcode,
				item_purOrd_Disc1			= @item_purOrd_Disc1,
				item_purOrd_Disc2			= @item_purOrd_Disc2,
				item_purOrd_Disc3			= @item_purOrd_Disc3,
				item_purOrd_Disc4			= @item_purOrd_Disc4,
				item_recentlyPurchased		= 'false'
		WHERE	comp_id			= @comp_id
		AND		item_id			= @item_id




	-- =================================================================================================================
	-- actualización del de la lista de costo, si el registro correspondiente existe se actualiza, si no existe, se
	-- agrega el registro
	DECLARE @lcoslis_price			DECIMAL(19,5),
			@lcoslis_price_aw		DECIMAL(19,5)


	IF EXISTS (SELECT TOP 1	1   -- MOS 10-2023: Top 1
				   FROM tbItemCostList ticl		WITH (NOLOCK)
				   WHERE	ticl.comp_id	= @comp_id
				   AND		ticl.coslis_id	= @coslis_id
				   AND		ticl.item_id	= @item_id)

		BEGIN

			SELECT 	@lcoslis_price		= ticl.coslis_price,
					@lcoslis_price_aw	= ticl.coslis_price_aw
				FROM 	tbItemCostList ticl			WITH (NOLOCK)
				WHERE	ticl.comp_id		= @comp_id
				AND		ticl.coslis_id		= @coslis_id
				AND		ticl.item_id		= @item_id



			IF @lcppr_matchCosts = 'true' --Ref: #1
				BEGIN
					SET @lcoslis_price		= @coslist_price
					SET @lcoslis_price_aw	= @coslist_price
				END
			ELSE IF @coslist_aw	= 'true'
				BEGIN
					SET @lcoslis_price_aw	= @coslist_price
				END
			ELSE
				BEGIN
					SET @lcoslis_price		= @coslist_price
				END



			UPDATE	tbItemCostList		WITH (ROWLOCK)
				SET		coslis_price			= @lcoslis_price,
						coslis_price_aw			= @lcoslis_price_aw,
						coslis_cd				= GETDATE(),
						curr_id					= @coscurr_id,
						user_id_lastUpdate		= @user_id,
						coslis_disabled4Rules	= 'True'
				WHERE	comp_id			= @comp_id
				AND		coslis_id		= @coslis_id
				AND		item_id			= @item_id
				and (coslis_price			<> @lcoslis_price       --agrego dario 16/08/2017 para que no se grabe historial si no se modifica el costo
			    or coslis_price_aw			<> @lcoslis_price_aw
				or curr_id					<> @coscurr_id)

		END

	ELSE

		BEGIN

		--	DECLARE @lcoslis_price		DECIMAL(19,5),
		--			@lcoslis_price_aw	DECIMAL(19,5)

			SELECT  @lcoslis_price		= 0,
					@lcoslis_price_aw	= 0



			IF @lcppr_matchCosts = 'true' --Ref: #1
				BEGIN
					SET @lcoslis_price		= @coslist_price
					SET @lcoslis_price_aw	= @coslist_price
				END
			ELSE IF @coslist_aw	= 'true'
				BEGIN
					SET @lcoslis_price_aw	= @coslist_price
				END
			ELSE
				BEGIN
					SET @lcoslis_price		= @coslist_price
				END




			INSERT INTO tbItemCostList		WITH (ROWLOCK)
			(
				comp_id,
				coslis_id,
				item_id,
				coslis_price,
				coslis_price_aw,
				curr_id,
				coslis_cd,
				user_id_lastUpdate,
				coslis_disabled4Rules
			)
			VALUES
			(
				@comp_id,
				@coslis_id,
				@item_id,
				@lcoslis_price,
				@lcoslis_price_aw,
				@coscurr_id,
				GETDATE(),
				@user_id,
				'True'
			)

		END

	/*
	SELECT	*	FROM tbItemCostList ticl
	WHERE	ticl.comp_id	= @comp_id
	AND		ticl.coslis_id	= @coslis_id
	AND		ticl.item_id	= @item_id
	*/





	-- =================================================================================================================
	-- actualización del de la lista de precios, si el registro correspondiente existe se actualiza, si no existe, se
	-- agrega el registro

	IF EXISTS (	SELECT TOP 1	1 -- MOS 10-2023: Top 1
					FROM	tbPriceListItems tpli	WITH (NOLOCK)
					WHERE	tpli.comp_id = @comp_id
					AND		tpli.prli_id = @prli_id
					AND		tpli.item_id = @item_id)
		BEGIN

			UPDATE	tbPriceListItems				WITH (ROWLOCK)
				SET		prli_price				= @prli_price,
						prli_cd					= GETDATE(),
						curr_id					= @prlicurr_id,
						user_id_lastUpdate		= @user_id,
						prli_disabled4Rules		= 'True',
						prli_lastModuleUpdate	= 10
				WHERE	comp_id		= @comp_id
				AND		prli_id		= @prli_id
				AND		item_id		= @item_id
				and (prli_price				<> @prli_price      --agrego dario 16/08/2017 para que no se grabe historial si no se modifica el precio
				or curr_id					<> @prlicurr_id)
		END

	ELSE

		BEGIN

			INSERT INTO tbPriceListItems		WITH (ROWLOCK)
			(
				comp_id,
				prli_id,
				item_id,
				prli_price,
				curr_id,
				bra_id,
				prli_cd,
				user_id_lastUpdate,
				prli_disabled4Rules,
				prli_lastModuleUpdate
			)
			VALUES
			(
				@comp_id,
				@prli_id,
				@item_id,
				@prli_price,
				@prlicurr_id,
				NULL,
				GETDATE(),
				@user_id,
				'True',
				10
			)

		END

	/*
	SELECT	*
	FROM	tbPriceListItems tpli
	WHERE	tpli.comp_id = @comp_id
	AND		tpli.prli_id = @prli_id
	AND		tpli.item_id = @item_id
	*/





	-- =================================================================================================================
	-- actualización de la marca que indica que el artículo fue ingresado recientemente al valor Falso
	--UPDATE	tbItem
	--	SET		item_recentlyPurchased = 'false'
	--	WHERE	comp_id		= @comp_id
	--	AND		item_id		= @item_id



	DELETE FROM tbItemLastUpdated
	INSERT INTO tbItemLastUpdated	WITH (ROWLOCK)
	(
		comp_id,
		item_id
	)
	VALUES
	(
		@comp_id,
		@item_id
	)


	-- -------------------------------------------------------------------------------------------------
	-- Actualiza las Publicaciones de MercadoLibre Directamente para achicar los tiempos de publicacion.
	-- -------------------------------------------------------------------------------------------------
	--IF EXISTS(
	--			SELECT 1
	--				FROM tbMercadoLibre_Stores tmls WITH (ROWLOCK)
	--				WHERE	tmls.comp_id = @comp_id			AND
	--						tmls.mls_accessToken	<> ''	AND
	--						tmls.mls_disabled		= 'False'
	--		)
	--		BEGIN

	--			DECLARE @tabPublications TABLE(mlp_id INT PRIMARY KEY)
	--			INSERT INTO @tabPublications(mlp_id)
	--				SELECT tmlip.mlp_id
	--					FROM tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
	--					INNER JOIN tbMercadoLibre_Stores	tmls		WITH (NOLOCK)
	--						ON	tmls.comp_id			= tmlip.comp_id AND
	--							tmls.mls_id				= tmlip.mls_id
	--					WHERE	tmlip.comp_id			= @comp_id		AND
	--							tmlip.prli_id			= @prli_id		AND
	--							tmlip.item_id			= @item_id		AND
	--							tmls.mls_disabled		= 'False'		AND
	--							tmls.mls_accessToken	<> ''			AND
	--							tmlip.mlp_isFixedPrice	= 'False'		AND
	--							tmlip.optval_statusId IN (1,2,3,4,6)

	--			UPDATE 	tbMercadoLibre_ItemsPublicados WITH (ROWLOCK)
	--				SET mlp_price	= dbo.fnGetExchange2(@comp_id,@prli_price, @prlicurr_id, tmlip.curr_id, 0, 0, 0, 'False')
	--				FROM tbMercadoLibre_ItemsPublicados tmlip
	--				INNER JOIN @tabPublications tmp
	--					ON tmp.mlp_id = tmlip.mlp_id

	--		END
	-- -------------------------------------------------------------------------------------------------


	-- MOS 05-2022  Auth  **jhewvjqwhv12873612jqwhdqwjvdwqjhvdq
	-- Dispara el trigger de actualizacion de articulos para que se pasen los descuentos, etc de padres a hijos.
	UPDATE tbitem
		SET item_lastUpdate				= GETDATE(),
			user_id4LastUpdate			= @user_id,
			item_lastUpdate_byProcess	= GETDATE()
		WHERE	comp_id = @comp_id AND
				item_id = @item_id




END
GO






CREATE PROCEDURE [dbo].[spCostsAndPrices_ChangeCurrency_Update]
(

	@comp_id					INT,
	@bra_id						INT,
	@Item_Guid					UNIQUEIDENTIFIER,
	@typeFrom					INT, --1 : Lista de precios , 2 : Lista de Costos
	@list_id					INT, -- Id de la lista seleccionada
	@curr_id_From				INT, -- Moneda Desde
	@curr_id_To					INT  -- Moneda Hasta

)
AS

BEGIN

	---------------------------------------------------------------------------------
	-- PARAMETROS DE TESTING
	---------------------------------------------------------------------------------
	/*
	DECLARE
			@comp_id					INT,
			@bra_id						INT,
			@Item_Guid					UNIQUEIDENTIFIER,
			@typeFrom					INT, --1 : Lista de precios , 2 : Lista de Costos
			@list_id					INT, -- Id de la lista seleccionada
			@curr_id_From				INT, -- Moneda Desde
			@curr_id_To					INT  -- Moneda Hasta

	SELECT
			@comp_id					= 1,
			@typeFrom					= 1,
			@list_id					= 1,
			@bra_id						= 1,
			@Item_Guid					= '159d87d5-976c-4cd3-8f30-9b36a3788931',
			@curr_id_From				= 1,
			@curr_id_To					= 1

	*/
	---------------------------------------------------------------------------------
	---------------------------------------------------------------------------------
	---------------------------------------------------------------------------------



	set nocount ON


	------------------------------------------------------------------------------------
	DECLARE @objGUID AS UNIQUEIDENTIFIER
	SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@Item_Guid)

	DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)

	INSERT INTO @tblComplexFilter_Items

		SELECT
			tcf.sl_id
			FROM tbComplexFilter tcf      WITH (NOLOCK)
			WHERE tcf.sl_guid	  = @objGUID      AND
				  tcf.sl_selected = 'True'
	------------------------------------------------------------------------------------


		DECLARE @curCompID		AS INT
		DECLARE @curItemID		AS INT
		DECLARE @curPrLiID		AS INT
		DECLARE @curCosLisID	AS INT




		--@typeFrom 1 : Lista de precios , 2 : Lista de Costos
		IF @typeFrom = 1
			-- ----------------------------------
			-- Lista de Precios
			-- ----------------------------------

			BEGIN

				DECLARE curPrices CURSOR LOCAL FAST_FORWARD FOR
					SELECT	tpli.comp_id,
							tpli.prli_id,
							tpli.item_id
						FROM tbPriceListItems						tpli	WITH (NOLOCK)
						INNER JOIN tbItem							ti		WITH (NOLOCK)
							ON	ti.comp_id	= tpli.comp_id	AND
								ti.item_id	= tpli.item_id
						INNER JOIN @tblComplexFilter_Items			tmp
							ON	tmp.item_id	= ti.item_id
						WHERE  tpli.comp_id = @comp_id		AND
							   tpli.prli_id = @list_id		AND
							   tpli.curr_id = @curr_id_From

				OPEN curPrices

				FETCH NEXT FROM curPrices
					INTO	@curCompID,
							@curPrLiID,
							@curItemID

				WHILE @@FETCH_STATUS = 0
					BEGIN

						UPDATE tbPriceListItems
							SET prli_price		= dbo.fngetexchange2(@comp_id, prli_price,@curr_id_From,@curr_id_To, 0,0,0,'False'),
								curr_id			= @curr_id_To
							FROM tbPriceListItems						tpli
							WHERE  tpli.comp_id = @curCompID		AND
								   tpli.prli_id = @curPrLiID		AND
								   tpli.item_id = @curItemID

						FETCH NEXT FROM curPrices
							INTO	@curCompID,
									@curPrLiID,
									@curItemID
					END

				CLOSE		curPrices
				DEALLOCATE	curPrices





					--UPDATE tbPriceListItems

					--SET prli_price	= dbo.fngetexchange2(@comp_id, prli_price,@curr_id_From,@curr_id_To, 0,0,0,'False'),
					--	curr_id		= @curr_id_To

					--FROM tbPriceListItems						tpli

					--INNER JOIN tbItem							ti	WITH (NOLOCK)
					--ON	ti.comp_id	= tpli.comp_id	AND
					--	ti.item_id	= tpli.item_id

					--INNER JOIN @tblComplexFilter_Items			tmp
					--ON	tmp.item_id	= ti.item_id

					--WHERE  tpli.comp_id = @comp_id		AND
					--	   tpli.prli_id = @list_id		AND
					--	   tpli.curr_id = @curr_id_From
			END

		ELSE

			-- ----------------------------------
			-- Lista de Costos
			-- ----------------------------------

			BEGIN

				DECLARE curCosts CURSOR LOCAL FAST_FORWARD FOR
					SELECT	tpli.comp_id,
							tpli.coslis_id,
							tpli.item_id
						FROM tbItemCostList							tpli	WITH (NOLOCK)
						INNER JOIN tbItem							ti		WITH (NOLOCK)
							ON	ti.comp_id		= tpli.comp_id	AND
								ti.item_id		= tpli.item_id
						INNER JOIN @tblComplexFilter_Items			tmp
							ON	tmp.item_id		= ti.item_id
						WHERE  tpli.comp_id		= @comp_id		AND
							   tpli.coslis_id	= @list_id		AND
							   tpli.curr_id		= @curr_id_From

				OPEN curCosts

				FETCH NEXT FROM curCosts
					INTO	@curCompID,
							@curCosLisID,
							@curItemID

				WHILE @@FETCH_STATUS = 0
					BEGIN

						UPDATE tbItemCostList
							SET coslis_price		= dbo.fngetexchange2(@comp_id, coslis_price,   @curr_id_From,@curr_id_To, 0,0,0,'False'),
								coslis_price_aw		= dbo.fngetexchange2(@comp_id, coslis_price_aw,@curr_id_From,@curr_id_To, 0,0,0,'False'),
								curr_id				= @curr_id_To
							FROM tbItemCostList						tpli
							WHERE  tpli.comp_id		= @curCompID		AND
								   tpli.coslis_id	= @curCosLisID		AND
								   tpli.item_id		= @curItemID

						--FETCH NEXT FROM curPrices
						FETCH NEXT FROM curCosts --STL 16-05-2023 ESTABA MAL PEGADO EL NOMBRE DEL CURSOR
							INTO	@curCompID,
									@curCosLisID,
									@curItemID
					END

				CLOSE		curCosts
				DEALLOCATE	curCosts

				--UPDATE tbItemCostList

				--SET coslis_price	= dbo.fngetexchange2(@comp_id, coslis_price,@curr_id_From,@curr_id_To, 0,0,0,'False'),
				--    coslis_price_aw = dbo.fngetexchange2(@comp_id, coslis_price_aw,@curr_id_From,@curr_id_To, 0,0,0,'False'),
				--	curr_id			= @curr_id_To

				--FROM tbItemCostList							tpli

				--INNER JOIN tbItem							ti		WITH (NOLOCK)
				--ON	ti.comp_id	= tpli.comp_id	AND
				--	ti.item_id	= tpli.item_id

				--INNER JOIN @tblComplexFilter_Items			tmp
				--ON	tmp.item_id	= ti.item_id

				--WHERE  tpli.comp_id		= @comp_id		AND
				--	   tpli.coslis_id	= @list_id		AND
				--	   tpli.curr_id		= @curr_id_From


			END


END


















GO






