CREATE PROCEDURE [dbo].[spCounters_getNextValue]
(
	@comp_id				as int,
	@auxiliary_id			as int,
	@counter_id				as int,
	@counter_value			as int output
)
as

BEGIN

	set nocount on

	-- ----------------------------------------------------------
	-- ----------------------------------------------------------
	/*
	declare 	@comp_id				int,
				@bra_id					int,
				@counter_id				int
	declare @counter_value int
	select		@comp_id				=1,
				@bra_id					=1,
				@counter_id				=9999
	*/
	-- ----------------------------------------------------------



	IF @counter_id = 1  -- Prioridad
		BEGIN
				SET @auxiliary_id = -9999
		END


	if exists	(	SELECT TOP 1	1
	         	 		from	tbCounters	WITH (NOLOCK)
						where	comp_id			= @comp_id
						and		auxiliary_id	= @auxiliary_id
						and		counter_id		= @counter_id	)

		begin
			exec	dbo.spCounters_outputDataById	@comp_id, @auxiliary_id, @counter_id, @get_counter_value = @counter_value output
			set		@counter_value = @counter_value + 1
			exec	dbo.spCounters_updateData		@comp_id, @auxiliary_id, @counter_id, @counter_value
		end

	else

	BEGIN
			IF @auxiliary_id = -9999 AND @counter_id = 1
				BEGIN
					SET @counter_value = 21111111
				END
			ELSE
				BEGIN
					set	@counter_value = 1
				END

			exec	dbo.spCounters_insertData		@comp_id, @auxiliary_id, @counter_id, @counter_value
		end

	Return  @counter_value


END
GO












