CREATE PROCEDURE [dbo].[spCreditBehavior_Arg_ProtCom_DeleteData]
(
	@comp_id				INT,
	@ret_Identity			INT	OUTPUT,
	@ret_ErrorCode			INT	OUTPUT,
	@ret_ErrorDescription	VARCHAR(200) OUTPUT
)
AS
    -- -----------------------------------------------------------------------------
    -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
    -- -----------------------------------------------------------------------------
    --SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
    SET LOCK_TIMEOUT 500
    SET DEADLOCK_PRIORITY LOW
    -- -----------------------------------------------------------------------------


	SET NOCOUNT ON

		BEGIN

			Set @ret_Identity			= 0
			Set @ret_ErrorCode			= 0
			Set @ret_ErrorDescription	= ''

			--SAVE TRANSACTION traProtComDelete
			--BEGIN TRANSACTION
			BEGIN TRY
				TRUNCATE TABLE tbCreditBehavior_Arg_Protcom
			END TRY
			BEGIN CATCH
			END CATCH

			BEGIN TRY

				DELETE FROM tbCreditBehavior_Arg_Protcom

			END TRY
			BEGIN CATCH
				--ROLLBACK TRANSACTION traProtCom
				DECLARE @ErrorMessage   NVARCHAR(4000)
				DECLARE @ErrorSeverity  INT
				DECLARE @ErrorState     INT
				SELECT  @ErrorMessage    = ERROR_MESSAGE(),
						@ErrorSeverity   = ERROR_SEVERITY(),
						@ErrorState      = ERROR_STATE()
				IF      @ErrorState      = 0 SET @ErrorState = 1
				RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)
			END CATCH
			--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traProtCom

		END
GO



CREATE PROCEDURE [dbo].[spCreditBehavior_Arg_ProtCom_InsertData]
(
	@comp_id				INT,
	@protcom_infoID			INT,
	@protcom_infoName		NVARCHAR(350),
	@protcom_beginDate		DATETIME,
	@protcom_endDate		DATETIME,
	@protcom_status			NCHAR(10),
	@protcom_Name			NVARCHAR(350),
	@protcom_address		NVARCHAR(500),
	@protcom_doctype		NCHAR(10),
	@protcom_taxNumber		NVARCHAR(50),
	@isEndDateNull			BIT,
	@ret_Identity			INT	OUTPUT,
	@ret_ErrorCode			INT	OUTPUT,
	@ret_ErrorDescription	VARCHAR(200) OUTPUT
)
AS
	SET NOCOUNT ON

		BEGIN

			SET @protcom_taxNumber = dbo.fnStrAllTrim(@protcom_taxNumber)

			--SET DATEFORMAT 'YMD'

			Set @ret_Identity			= 0
			Set @ret_ErrorCode			= 0
			Set @ret_ErrorDescription	= ''

			--SAVE TRANSACTION traProtCom
			--BEGIN TRANSACTION
			BEGIN TRY

				DECLARE @tnt_id	INT
				--CUIT = tnt_id = 1
				--DNI  = tnt_id = 5
				--ACA PREGUNTAMOS POR EL TIPO QUE VIENE INFORMADO EN LA TABLA
				--EN EL CASO DE NO SER NI CUIT NI DNI, LE PONEMOS DNI.
				IF @protcom_doctype = 'CUIT'
					SET @tnt_id = 1
				ELSE
					IF @protcom_doctype = 'DNI'
						SET @tnt_id = 5
					ELSE
						SET @tnt_id = 5


				INSERT INTO tbCreditBehavior_Arg_Protcom
				(
					comp_id,
					-- protcom_id -- this column value is auto-generated,
					protcom_infoId,
					protcom_infoName,
					protcom_beginDate,
					protcom_endDate,
					protcom_status,
					protcom_Name,
					protcom_address,
					tnt_id,
					protcom_taxNumber
				)
				VALUES
				(
					@comp_id,
					CASE WHEN @protcom_infoID = -1 THEN NULL ELSE @protcom_infoID END,
					@protcom_infoName,
					@protcom_beginDate,
					CASE WHEN @isEndDateNull = 'False' THEN @protcom_endDate ELSE NULL END,
					@protcom_status,
					@protcom_Name,
					@protcom_address,
					@tnt_id,
					@protcom_taxNumber
				)

				SET @ret_Identity = @@IDENTITY


			END TRY
			BEGIN CATCH
				--ROLLBACK TRANSACTION traProtCom
				DECLARE @ErrorMessage   NVARCHAR(4000)
				DECLARE @ErrorSeverity  INT
				DECLARE @ErrorState     INT
				SELECT  @ErrorMessage    = ERROR_MESSAGE(),
						@ErrorSeverity   = ERROR_SEVERITY(),
						@ErrorState      = ERROR_STATE()
				IF      @ErrorState      = 0 SET @ErrorState = 1
				RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)
			END CATCH
			--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traProtCom

		END


GO



