CREATE PROCEDURE [dbo].[spCreditBehavior_GeneralInfo_GetDataByFilters]
(
	@comp_id		INT,
	@guid			UNIQUEIDENTIFIER,
	@cit_id			INT,
	@cis_id			INT,
	@Begin_dateFrom	DATETIME,
	@Begin_dateTo	DATETIME,
	@End_dateFrom	DATETIME,
	@End_dateTo		DATETIME
)
AS


	BEGIN


		SET NOCOUNT ON

		------------------------------------------------------------------------------------
		/*

		DECLARE
				@comp_id		INT,
				@guid			UNIQUEIDENTIFIER,
				@cit_id			INT,
				@cis_id			INT,
				@Begin_dateFrom	DATETIME,
				@Begin_dateTo	DATETIME,
				@End_dateFrom	DATETIME,
				@End_dateTo		DATETIME


		SELECT
				@comp_id		= 1,
				@guid			= '3fa3f1d3-68a4-4d4c-b75f-62516acd4597',
				@cit_id			= -1,
				@cis_id			= -1,
				@Begin_dateFrom	= '1900-01-01',
				@Begin_dateTo	= '9999-31-12',
				@End_dateFrom	= '1900-01-01',
				@End_dateTo		= '9999-31-12'
	*/
	------------------------------------------------------------------------------------



		SET @Begin_dateFrom = dbo.fnGetEnd_or_BeginOfDate(@Begin_dateFrom,'False')
		SET @Begin_dateTo	= dbo.fnGetEnd_or_BeginOfDate(@Begin_dateTo,'True')
		SET @End_dateFrom	= dbo.fnGetEnd_or_BeginOfDate(@End_dateFrom,'False')
		SET @End_dateTo		= dbo.fnGetEnd_or_BeginOfDate(@End_dateTo,'True')

		DECLARE @lGuid AS UNIQUEIDENTIFIER
		SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)
		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Customers TABLE (Cust_id INT PRIMARY KEY)

		IF EXISTS (SELECT 1 FROM tbComplexFilter tcf WHERE tcf.sl_guid = @guid)
			BEGIN
				INSERT INTO @tblComplexFilter_Customers
				(
					cust_id
				)
				SELECT
					tcf.sl_id
					FROM tbComplexFilter			tcf
					WHERE tcf.sl_guid = @lGuid		AND
						  tcf.sl_selected = 'True'
			END
		ELSE
			BEGIN
				INSERT INTO @tblComplexFilter_Customers
				(
					cust_id
				)
				SELECT
					tc.cust_id
					FROM tbCustomer tc
					WHERE tc.comp_id = @comp_id
			END



		SELECT
			' '												[ ],
			' '												[ ],
			tc.cust_name + ' | ' + convert(varchar,tc.cust_id) + ' | ' + tc.cust_taxNumber 								[cust_name],
			tcbs.cis_desc									[cis_desc],
			tcbt.cit_desc									[cit_desc],
			tcbgi.ci_dateBegin								[ci_dateBegin],
			tcbgi.ci_dateEnd								[ci_dateEnd],
			tcbgi.ci_desc									[ci_desc],
			tcbgi.ci_note									[ci_note],
			CONVERT(VARCHAR,tcbgi.ci_id) + '-' +
			CONVERT(VARCHAR,tcbgi.cust_id)					[ID]

			FROM tbCreditBehavior_GeneralInfo		tcbgi	WITH(NOLOCK)

			INNER JOIN @tblComplexFilter_Customers	tmp
			ON	tmp.cust_id		= tcbgi.cust_id

			left JOIN tbCustomer					tc		WITH(NOLOCK)
			ON	tc.comp_id		= tcbgi.comp_id AND
				tc.cust_id		= tcbgi.cust_id

			INNER JOIN tbCreditBehavior_Status		tcbs	WITH(NOLOCK)
			ON	tcbs.comp_id	= tcbgi.comp_id AND
				tcbs.cis_id		= tcbgi.cis_id

			INNER JOIN tbCreditBehavior_Types		tcbt	WITH(NOLOCK)
			ON	tcbt.comp_id	= tcbgi.comp_id	AND
				tcbt.cit_id		= tcbgi.cit_id

			WHERE	tcbgi.comp_id = @comp_id										AND
					(@cis_id = -1 OR tcbgi.cis_id = @cis_id )						AND
					(@cit_id = -1 OR tcbgi.cit_id = @cit_id )						AND
					tcbgi.ci_dateBegin	BETWEEN @Begin_dateFrom AND @Begin_dateTo	AND
					isnull(tcbgi.ci_dateEnd,'')	BETWEEN @End_dateFrom	AND @End_dateTo


	END


GO



CREATE PROCEDURE spCreditBehavior_GeneralInfo_GetDataById
(
	@comp_id	INT,
	@ci_id		INT,
	@cust_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SELECT
			tcbgi.comp_id,
			tcbgi.ci_id,
			tcbgi.cust_id,
			tcbgi.cis_id,
			tcbgi.cit_id,
			tcbgi.ci_dateBegin,
			tcbgi.ci_dateEnd,
			ISNULL(tcbgi.ci_desc,'')			[ci_desc],
			ISNULL(tcbgi.ci_note,'')			[ci_note],
			tcbgi.ci_pdf
		FROM tbCreditBehavior_GeneralInfo		tcbgi
		WHERE	tcbgi.comp_id	= @comp_id		AND
				tcbgi.ci_id		= @ci_id		AND
				tcbgi.cust_id	= @cust_id
	END

GO





CREATE PROCEDURE [dbo].[spCreditBehavior_GeneralInfo_InsertData]
(
	@comp_id				INT,
	@cust_id				INT,
	@cit_id					INT,
	@cis_id					INT,
	@ci_dateBegin			DATETIME,
	@ci_dateEnd				DATETIME,
	@ci_desc				NVARCHAR(250),
	@ci_note				NVARCHAR(4000),
	@chkHasDateEnd			BIT

)
AS

SET NOCOUNT ON

BEGIN

		--SET DATEFORMAT 'YMD'
		DECLARE	@endDate	DATETIME

		IF @chkHasDateEnd = 'True'
			BEGIN
				SET @endDate = @ci_dateEnd
			END
		ELSE
			BEGIN
				SET @endDate = NULL
			END


	IF @cust_id <> ''
		BEGIN

				INSERT INTO tbCreditBehavior_GeneralInfo
				(
					comp_id,
					-- ci_id -- this column value is auto-generated,
					cust_id,
					cis_id,
					cit_id,
					ci_dateBegin,
					ci_dateEnd,
					ci_desc,
					ci_note
				)
				VALUES
				(
					@comp_id,
					@cust_id,
					@cis_id,
					@cit_id,
					@ci_dateBegin,
					@endDate,
					@ci_desc,
					@ci_note
				)


		END



END


GO



