CREATE PROCEDURE [dbo].[spCreditBehavior_GeneralInfo_UpdateData]
(
	@comp_id		INT,
	@ci_id			INT,
	@cust_id		INT,
	@cis_id			INT,
	@cit_id			INT,
	@ci_dateBegin	DATETIME,
	@ci_dateEnd		DATETIME,
	@ci_desc		NVARCHAR(250),
	@ci_note		NVARCHAR(4000),
	@ci_pdf			IMAGE,
	@chkHasDateEnd	BIT
)
AS
	BEGIN
		SET NOCOUNT ON

		DECLARE
			@lcis_id	INT,
			@lcit_id	INT,
			@endDate	DATETIME

		IF @cis_id = -1
			BEGIN
				SET @lcis_id = NULL
			END
		ELSE
			BEGIN
				SET @lcis_id = @cis_id
			END

		IF @cit_id = -1
			BEGIN
				SET @lcit_id = NULL
			END
		ELSE
			BEGIN
				SET @lcit_id = @cit_id
			END

		IF @chkHasDateEnd = 'True'
			BEGIN
				SET @endDate = @ci_dateEnd
			END
		ELSE
			BEGIN
				SET @endDate = NULL
			END


		UPDATE tbCreditBehavior_GeneralInfo
		SET
			cis_id			= @lcis_id,
			cit_id			= @lcit_id,
			ci_dateBegin	= @ci_dateBegin,
			ci_dateEnd		= @endDate,
			ci_desc			= @ci_desc,
			ci_note			= @ci_note,
			ci_pdf			= @ci_pdf
		WHERE	comp_id		= @comp_id	AND
				ci_id		= @ci_id	AND
				cust_id		= @cust_id
	END

GO



