AS
	SET NOCOUNT ON

		BEGIN

			SELECT
				tcbt.cit_id				[Id],
				tcbt.cit_desc			[Desc]
			FROM tbCreditBehavior_Types tcbt

			WHERE	 tcbt.comp_id		= @comp_id

		END


GO















CREATE PROCEDURE [dbo].[spCreditCard_getCombo]
(
	@comp_id			int
)
AS

BEGIN

	/*
	declare @comp_id   int

	select @comp_id =1
	*/

	select
			cc.cc_id 	[id],
			cc.cc_desc  + ' , ' + sc.[curr_desc] [desc]
		from	dbo.tbCreditCard	cc			WITH (NOLOCK)
		left join dbo.tbsysCurrency	sc			WITH (NOLOCK)
			on  sc.curr_id	= cc.curr_id
		where	comp_id =	@comp_id AND
				cc.cc_disabled = 'False'
		Order BY	CASE
						WHEN cc.cc_MPIsEnabled = 'True' THEN 2
						ELSE								 1
					END
					,cc_desc

END









GO




CREATE PROCEDURE spCreditCard_getCombo4CCWithLoanPlans
(
	@comp_id	INT
)
AS

	BEGIN
