CREATE PROCEDURE spCreditCard_GetComboByProfile4CreditCardPaymentPlan
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@prof_id	INT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@prof_id	= 1
		*/
		-- ----------------------------------------------


		-- ACA GRABAMOS LOS CC_ID CORRESPONDIENTES A LOS ST_ID ASOCIADOS AL PERFIL
		-- SIEMPRE QUE TENGAN CARGADO UN CC_ID
		DECLARE @tblCC TABLE
							(
								comp_id	INT,
								cc_id	INT PRIMARY KEY
							)

		INSERT INTO @tblCC
		(
			comp_id,
			cc_id
		)
		SELECT	DISTINCT
			tst.comp_id,
			tst.cc_id
			FROM	dbo.tbSalesTerms												tst
			where	tst.comp_id							= @comp_id					AND
					ISNULL(tst.st_disabled,'False')		= 'False'					AND
					(tst.bra_id IS NULL OR tst.bra_id	= @bra_id OR @bra_id = -1) 	AND
					(tst.st_id IN	(SELECT
										tstp.st_id
   										FROM	tbSalesTerms4Profile		tstp
   										WHERE	tstp.comp_id	= @comp_id	AND
   												tstp.prof_id	= @prof_id)
   							OR
							NOT EXISTS	(SELECT
											1
   											FROM	tbSalesTerms4Profile		tstp
   											WHERE	tstp.comp_id	= @comp_id	AND
   													tstp.prof_id	= @prof_id))	AND
   					tst.cc_id IS NOT NULL

			ORDER BY	CC_ID


		-- SELECT FINAL CON LOS DATOS PARA EL COMBO
		SELECT
			tcc.cc_id							[ID],
			tcc.cc_desc							[DESC]
			FROM tbCreditCard					tcc
			INNER JOIN @tblCC					tbCC
			ON	tbCC.comp_id	= tcc.comp_id	AND
				tbCC.cc_id		= tcc.cc_id
		WHERE	tcc.comp_id		= @comp_id

	END




GO




------------------------
-- getDataById
------------------------

CREATE PROCEDURE [dbo].[spCreditCard_getDataById]
(

	@comp_id			INT,
	@cc_id				INT

)
as

BEGIN


	-- --------------------------------------
	-- Testing
	-- --------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@cc_id				INT,
					@ccp_id				INT

		SELECT
					@comp_id			= 1,
					@cc_id				= -1,
					@ccp_id				= 8

	*/
	-- --------------------------------------




	set nocount on


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SELECT
		cc.cc_id,
		cc.bra_id,
		cc.cc_percentage,
		cc.cc_plusPercentage,
		cc.acc_count_id,
		cc.acc_count_id_ExDif,
		cc.cc_desc,
		cc.curr_id,
		cc.acc_count_id_Payed,
		cc.acc_count_id_ExDif_Payed,
		cc.cc_PaymentsQty, ccg_id,
		cc.cc_NoLiquidationPending,
		cc.cc_disabled,
		cc.cc_mustVerifyAuthorizationCode,
		cc.cc_disableDataVerification,
		cc.cc_MPClientId,
		cc.cc_MPClientSecret,
		cc.cc_MPNotificationURL,
		isnull(cc.cc_MPType,0)								[cc_MPType],
		cc.cc_MPPointType,
		cc.cc_MPAdditionalParameter,
		cc.cc_MPPointDeviceName,
		isnull(cc_MPPointTitle,'')							[cc_MPPointTitle],
		isnull(cc.cc_MPIsEnabled,'False')					[cc_MPIsEnabled],
		isnull(cc.mls_id,-1)								[mls_id],
		ISNULL(tmls.MLUser_Id,-1)							[MLUser_Id],
		cc.cc_guid,
		ISNULL(cc.cc_MPQR_POSCreated,'False')				[cc_MPQR_POSCreated],
		ISNULL(cc.mlbra_id,-1)								[mlbra_id],
		ISNULL(tmlb.MLId,-1)								[mlbra_MLId],
		ISNULL(cc.cc_MPQR_POSId,-1)							[cc_MPQR_POSId],
		ISNULL(cc.cc_MPexpires,'False')						[cc_MPexpires],
		ISNULL(cc.cc_MPexpires_Days2Expire,0)				[cc_MPexpires_Days2Expire],
		ISNULL(cc.cc_MPexcluded_payment_methods,'')			[cc_MPexcluded_payment_methods],
		ISNULL(cc.cc_MPexcluded_payment_types,'')			[cc_MPexcluded_payment_types],
		ISNULL(cc.cc_MPdefault_payment_method_id,'')		[cc_MPdefault_payment_method_id],
		ISNULL(cc.cc_MPinstallments,0)						[cc_MPinstallments],
		ISNULL(cc.cc_MPdefault_installments,0)				[cc_MPdefault_installments],
		ISNULL(cc.cc_MPBotonDePago_back_urls_success,'')	[cc_MPBotonDePago_back_urls_success],
		ISNULL(cc.cc_MPBotonDePago_back_urls_pending,'')	[cc_MPBotonDePago_back_urls_pending],
		ISNULL(cc.cc_MPBotonDePago_back_urls_failure,'')	[cc_MPBotonDePago_back_urls_failure],
		CASE
			WHEN cc.mls_id IS NOT NULL AND cc.mls_id = tmps.mls_id THEN ISNULL(tmpl.external_id,'')
			ELSE														''
		END																					[MPpos_external_id],
		CASE
			WHEN cc.mls_id IS NOT NULL AND cc.mls_id = tmps.mls_id THEN ISNULL(tmpl.intID,-1)
			ELSE														-1
		END																					[MPpos_id],
		CASE
			WHEN cc.mls_id IS NOT NULL AND cc.mls_id = tmps.mls_id THEN ISNULL(tmps.external_id,'')
			ELSE														''
		END																					[MPsto_external_id],
		CASE
			WHEN cc.mls_id IS NOT NULL AND cc.mls_id = tmps.mls_id THEN ISNULL(tmps.intID,-1)
			ELSE														-1
		END																					[MPsto_id]


		FROM tbcreditcard				cc		WITH (NOLOCK)
		LEFT JOIN tbMercadoLibre_Stores tmls	WITH (NOLOCK)
			ON	tmls.comp_id	= cc.comp_id AND
				tmls.mls_id		= cc.mls_id
		LEFT JOIN tbMercadoLibre_Branchs tmlb	WITH (NOLOCK)
			ON	tmlb.comp_id	= cc.comp_id AND
				tmlb.mlbra_id	= cc.mlbra_id

		LEFT JOIN tbMercadoPago_POS AS tmpl		WITH (NOLOCK)
			ON	tmpl.comp_id	= cc.comp_id AND
				tmpl.mppos_id	= cc.mppos_id

		LEFT JOIN tbMercadoPago_Stores AS tmps	WITH (NOLOCK)
			ON	tmps.comp_id	= tmpl.comp_id AND
				tmps.mploc_id	= tmpl.mploc_id

		--LEFT JOIN tbMercadoLibre_Stores AS tmls2	WITH (NOLOCK)
		--	ON	tmls2.comp_id	= tmps.comp_id AND
		--		tmls2.mls_id	= tmps.mls_id





		WHERE	cc.comp_id		= @comp_id AND
				cc.cc_id		= @cc_id








END



















GO





