CREATE PROCEDURE [dbo].[spCreditCard_POSTerminalNumber_GetCombo]
(

	@comp_id			INT,
	@lang_id			INT,
	@cc_id				INT,
	@bra_id				INT


)
AS

	BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------------------------
	-- TESTING
	-- ------------------------------------------------------------------------
	/*
		DECLARE 	@comp_id			INT,
					@lang_id			INT,
					@cc_id				INT,
					@bra_id				INT


		SELECT 		@comp_id			= 1,
					@lang_id			= 2,
					@cc_id				= 14,
					@bra_id				= 1
*/
	-- ------------------------------------------------------------------------


	SELECT distinct
		clp.cct_id		[id],
		clp.cct_desc	[desc]

		FROM tbCreditCard_POSTerminalNumber	clp WITH (NOLOCK)

		WHERE	clp.comp_id			= @comp_id	AND
				(
					clp.brag_id IS NULL OR

					EXISTS(	SELECT 1
					       		FROM tbBranchGroupDetail				tbgd
					       		WHERE	tbgd.comp_id	= clp.comp_id	AND
					       				tbgd.brag_id	= clp.brag_id	AND
					       				tbgd.bra_id		= @bra_id)

				)								AND
				EXISTS(	SELECT 1
				       		FROM tbCreditCard			tcc
					       		WHERE	tcc.comp_id	= clp.comp_id	AND
					       				tcc.ccg_id	= clp.ccg_id    AND
										tcc.cc_id	= @cc_id) AND

				clp.cct_disabled	= 'False'

		ORDER BY clp.cct_desc


	END
GO




