create PROCEDURE [dbo].[spCreditCard_UpdateData_MPQR]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id						INT,
	@prof_id					INT,
	@user_id					INT,

	@cc_MPQR_POSCreated			BIT,
