AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@prof_id			INT,
