------------------------------------------------------------------------------------------------------
--Date	: 21/02/17
--Author: GA
--Desc	: getcombo para la pagina de gestionar vouchers,traemos las tarjetas habilitadas para mercadopago
------------------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spCreditCard_Voucher_getCombo]
(
	@comp_id			int
)
AS

BEGIN


	----------------------------------------------------------
	--testing
	/*
	declare @comp_id   int

	select @comp_id =1
	*/
	----------------------------------------------------------



	select
		cc.cc_id 								[id],
		cc.cc_desc  + ' , ' + sc.[curr_desc]	[desc]

		from	dbo.tbCreditCard	cc			WITH (NOLOCK)
		left join dbo.tbsysCurrency	sc			WITH (NOLOCK)
		on  sc.curr_id	= cc.curr_id
		where	comp_id				= @comp_id		AND
				cc.cc_disabled		= 'False'		AND --tarjeta no está deshabilitada
				(
					cc.cc_MPIsEnabled	= 'True'
					OR
					cc.DECIDIRBP_enabled = 'True'
				)			-- habilitado para mercadopago o Decidir, botones de pago

		Order By	cc_desc



END









GO




