CREATE procedure [dbo].[spCreditCard_Voucher_GetDataByFilters]
(

		@comp_id					INT,
		@lang_id					INT,
		@bra_id						INT,
		@prof_id					INT,
		@user_id					INT,

		@cc_id						INT,

		@ccv_cd_From				DATETIME,
		@ccv_cd_To					DATETIME,
		@ccv_MPPayDate_From			DATETIME,
		@ccv_MPPayDate_to			DATETIME,
		@ccv_MPApplyDate_From		DATETIME,
		@ccv_MPApplyDate_To			DATETIME,
		@ccv_MPDeleteDate_From		DATETIME,
		@ccv_MPDeleteDate_To		DATETIME,
		@ccv_MPRefundDate_From		DATETIME,
		@ccv_MPRefundDate_To		DATETIME,

		@ccv_status					INT,
		@cust_id					INT

)
as
SET NOCOUNT ON

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


------------------------------------------------------------------------------------------
/*
	DECLARE
		@comp_id				INT,
		@lang_id				INT,
		@bra_id					INT,
		@prof_id				INT,
		@user_id				INT,

		@cc_id					INT,

		@ccv_cd_From				DATETIME,
		@ccv_cd_To					DATETIME,
		@ccv_MPPayDate_From			DATETIME,
		@ccv_MPPayDate_to			DATETIME,
		@ccv_MPApplyDate_From		DATETIME,
		@ccv_MPApplyDate_To			DATETIME,
		@ccv_MPDeleteDate_From		DATETIME,
		@ccv_MPDeleteDate_To		DATETIME,
		@ccv_MPRefundDate_From		DATETIME,
		@ccv_MPRefundDate_To		DATETIME,

		@ccv_status				INT



	SELECT
			@comp_id			= 1,
			@lang_id			= 2,
			@bra_id				= 1,
			@cc_id				= -1,
			@user_id			= 1,
			@prof_id			= 1,

			@ccv_cd_From				= '2010-12-01',
			@ccv_cd_To				= '2018-12-31',
			@ccv_MPPayDate_From		= '2010-12-01',
			@ccv_MPPayDate_to		= '2018-12-31',
			@ccv_MPDeleteDate_From	= '2010-12-01',
			@ccv_MPDeleteDate_To		= '2018-12-31',

			@ccv_status				= -1
	*/
-------------------------------------------------------------------------------------------

	SET @ccv_cd_To				= dbo.fnGetEnd_or_BeginOfDate(@ccv_cd_To,'True')
	SET @ccv_MPPayDate_to		= dbo.fnGetEnd_or_BeginOfDate(@ccv_MPPayDate_to,'True')
	SET @ccv_MPApplyDate_To		= dbo.fnGetEnd_or_BeginOfDate(@ccv_MPApplyDate_To,'True')
	SET @ccv_MPDeleteDate_To	= dbo.fnGetEnd_or_BeginOfDate(@ccv_MPDeleteDate_To,'True')
	SET @ccv_MPRefundDate_To	= dbo.fnGetEnd_or_BeginOfDate(@ccv_MPRefundDate_To,'True')
	--SELECT 1 / 0

		SELECT  ' '																		[ ],
			ISNULL(tccv.ccv_MPId,'')													[ccv_MPId],


			tc.cust_id																	[CustID],
			tc.cust_name																[cust_name],
			CASE
				WHEN tct.comp_id IS NOT NULL THEN	dbo.fnGetCommercialTransactionDescription(tct.comp_id,2, tct.ct_transaction)
				ELSE ISNULL((	SELECT TOP 1		dbo.fnGetCommercialTransactionDescription(tct2.comp_id,2, tct2.ct_transaction) +
													' #' + CONVERT(NVARCHAR(10),tctl.ctl_payNumber)
				             		FROM tbCommercialTransactionsLoan	AS tctl WITH (NOLOCK)
				             		INNER JOIN tbCommercialTransactions AS tct2	WITH (NOLOCK)
				             			ON	tct2.comp_id		= tctl.comp_id				AND
				             				tct2.ct_transaction = tctl.ct_transaction
				             		WHERE	tctl.comp_id			= tccvR.comp_id			AND
				             				tctl.ct_transaction		= tccvR.ct_transaction
							),'')
			END																			[Invoice],
			tccv.ccv_total																[ccv_total],
			tovMPType.optval_desc														[ccv_MPType],
			tovstatus.optval_desc														[ccv_status],
			(tu4Create.user_lastname + ', ' + tu4Create.user_firstname)					[user_id_Creator],
			tccv.ccv_cd																	[ccv_cd],
			tccv.ccv_MPPayDate															[ccv_MPPayDate],
			(tu4Apply.user_lastname + ', ' + tu4Apply.user_firstname)					[user_id4Apply],
			tccv.ccv_MPApplyDate														[ccv_MPApplyDate],
			(tu4Delete.user_lastname + ', ' + tu4Delete.user_firstname)					[user_id4Delete],
			tccv.ccv_MPDeleteDate														[ccv_MPDeleteDate],
			(tu4Refund.user_lastname + ', ' + tu4Refund.user_firstname)					[user_id4Refund],
			tccv.ccv_MPRefundDate														[ccv_MPRefundDate],
			--0																			[accredited], --- Importe Liquidado (ya está cargado el texto.)

			tccv.ccv_id																	[ID]

			FROM tbCreditCard_Voucher								tccv			WITH(NOLOCK)

			LEFT JOIN tbCreditCard_VoucherRelations				 AS tccvr			WITH (NOLOCK)
				ON	tccvr.comp_id	= tccv.comp_id	AND
					tccvr.ccv_id	= tccv.ccv_id



			LEFT JOIN tbCommercialTransactions AS tct								WITH(NOLOCK)
				ON	tct.comp_id			= tccvr.comp_id AND
					tct.ct_transaction	= tccvr.ct_transaction

			INNER JOIN tbCreditCard									tcc				WITH(NOLOCK)
			ON	tcc.comp_id			= tccv.comp_id				AND
				tcc.cc_id			= tccv.cc_id

			INNER JOIN tbCustomer									tc				WITH(NOLOCK)
			ON	tc.comp_id			= tccv.comp_id				AND
				tc.cust_id			= tccv.cust_id

			LEFT JOIN tbUser										tu4Create		WITH(NOLOCK)
			ON tu4Create.user_id	= tccv.user_id4Create

			LEFT JOIN tbUser										tu4Apply		WITH(NOLOCK)
			ON tu4Apply.user_id		= tccv.user_id4Apply

			LEFT JOIN tbUser										tu4Delete		WITH(NOLOCK)
			ON tu4Delete.user_id	= tccv.user_id4Delete

			LEFT JOIN tbUser										tu4Refund		WITH(NOLOCK)
			ON tu4Refund.user_id	= tccv.user_id4Refund

			LEFT JOIN tbsysOptionsValues							tovMPType		WITH(NOLOCK)
			ON	tovMPType.lang_id			= @lang_id			AND
				tovMPType.optval_class		= 697				AND
				tovMPType.optval_id			= tccv.ccv_MPType

			LEFT JOIN tbsysOptionsValues							tovMPPointType	WITH(NOLOCK)
			ON	tovMPPointType.lang_id		= @lang_id			AND
				tovMPPointType.optval_class	= 698				AND
				tovMPPointType.optval_id	= tccv.ccv_MPPointType

			LEFT JOIN tbsysOptionsValues							tovstatus		WITH(NOLOCK)
			ON	tovstatus.lang_id			= @lang_id			AND
				(tovstatus.optval_class		= 699				OR tovstatus.optval_class		= 700)	AND
				tovstatus.optval_id			= tccv.ccv_status


			Where	 tccv.comp_id			=		@comp_id
			AND 	(@cc_id = -1			OR		tccv.cc_id			=	@cc_id)
			AND 	(@cust_id = -1			OR		tc.cust_id			=	@cust_id)
			AND		 tccv.ccv_cd								between @ccv_cd_From				and @ccv_cd_To
			AND		 isnull(tccv.ccv_MPPayDate,GETDATE())		between @ccv_MPPayDate_From			and @ccv_MPPayDate_To
			AND		 isnull(tccv.ccv_MPPayDate,GETDATE())		between @ccv_MPApplyDate_From		and @ccv_MPApplyDate_To
			AND		 isnull(tccv.ccv_MPDeleteDate,GETDATE())	between @ccv_MPDeleteDate_From		and @ccv_MPDeleteDate_To
			AND		 isnull(tccv.ccv_MPDeleteDate,GETDATE())		between @ccv_MPRefundDate_From	and @ccv_MPRefundDate_To
			AND 	(@ccv_status	 = -1			OR		tccv.ccv_status			=	@ccv_status)



END
GO






