-- =================================================================================================================

CREATE PROCEDURE [dbo].[spCreditCard_Voucher_getDataById]
(
	@comp_id	INT,
	@ccv_id		INT
)
AS

BEGIN

	SET NOCOUNT ON

	SELECT
		tccv.comp_id,
		tccv.ccv_id,
		tccv.cc_id,
		tccv.bra_id,
		tccv.cust_id,
		tccv.curr_id,
		tccv.ccv_cd,
		tccv.ccv_MPId,
		tccv.ccv_MPType,
		tccv.ccv_MPPointType,
		tccv.ccv_MPPayDate,
		tccv.ccv_MPApplyDate,
		tccv.ccv_MPDeleteDate,
		tccv.ccv_MPRefundDate,
		tccv.user_id4Create,
		tccv.user_id4Apply,
		tccv.user_id4Delete,
		tccv.user_id4Refund,
		tccv.ccv_status,
		tccv.ccv_MPCollectionID,
		tccv.ccv_MPResponse,
		tccv.ccv_total,
		tccv.ccv_JSON,
		tccv.ccv_JSONResponse,
		tccv.ccv_installments,
		tccv.ccv_installment_amount,
		tccv.cv_marketplace_fee,
		tccv.ccv_net_received_amount,
		tccv.ccv_status_detail,
		tccv.ccv_authorization_code,
		tccv.ccv_cardholderName,
		tccv.ccv_cardholderNameNumber,
		tmls.mls_clientID							[mls_clientID],
		tmls.mls_clientSecret						[mls_clientSecret],
		tmls.[user_id]								[user_id_MLStor],
		ISNULL(tccv.ct_transaction_Collection,-1)	[ct_transaction_Collection],
		tmls.bra_id									[bra_id_4collection],
		tmls.df_id4MPCollection						[df_id_4Collection],
		ISNULL(tccv.ccv_MPPreference,'')			[ccv_MPPreference]

		FROM tbCreditCard_Voucher		tccv		WITH (NOLOCK)
		INNER JOIN tbCreditCard			tcc			WITH (NOLOCK)
			ON	tcc.comp_id		= tccv.comp_id AND
				tcc.cc_id		= tccv.cc_id
		LEFT JOIN tbMercadoLibre_Stores tmls		WITH (NOLOCK)
			ON	tmls.comp_id	= tcc.comp_id AND
				tmls.mls_id		= tcc.mls_id
		WHERE	tccv.comp_id	= @comp_id		AND
				tccv.ccv_id		= @ccv_id


END
GO




CREATE PROCEDURE [dbo].[spCreditCard_Voucher_InsertData]
(

		@comp_id				INT,
		@bra_id					INT,
		@user_id				INT,
		@cc_id					INT,
		@cust_id				INT,
		@ccv_total				DECIMAL(19,2),
		@curr_id				INT,
		@return_value			INT	output

)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE
		@comp_id				INT,
		@bra_id					INT,
		@user_id				INT,
		@cc_id					INT,
		@cust_id				INT,
		@ccv_total				INT,
		@curr_id				INT,
		@return_value			INT

	SELECT
		 @comp_id						= 1,
		 @bra_id						= 1,
		 @user_id						= 1,
		 @cust_id						= 24431,
		 @ccv_total						= 2,
		 @curr_id						= 1,
		 @cc_id							= 2
 */
-- ------------------------------------------------------



	Set @return_value	= 0



	declare @lMPId				as NVARCHAR(50),
			@lMPType			as INT,
			@lMPPointType		as INT,
			@lccv_status		as INT,
			@bitIsDECIDIR		AS BIT






	-- MOS 07-2022: Se hizo como CORRESPONDE !!!!!!!
	SELECT
		@lMPType		= tcc.cc_MPType,
		@lMPPointType	= tcc.cc_MPPointType ,
		@bitIsDECIDIR	= ISNULL(tcc.DECIDIRBP_enabled,'False')
		FROM tbCreditCard tcc						WITH (NOLOCK)
		WHERE	tcc.comp_id = @comp_id		AND
				tcc.cc_id	= @cc_id



	-- MOPS 07-2022: BASURA
	--set @lMPType = (SELECT
	--					tcc.cc_MPType
	--					FROM tbCreditCard tcc						WITH (NOLOCK)
	--					WHERE	tcc.comp_id = @comp_id		AND
	--							tcc.cc_id	= @cc_id
	--				)

	--set @lMPPointType = (SELECT
	--						tcc.cc_MPPointType
	--						FROM tbCreditCard tcc				WITH (NOLOCK)
	--						WHERE	tcc.comp_id = @comp_id		AND
	--								tcc.cc_id	= @cc_id
	--						)


	IF @lMPType = 1
		BEGIN
			set @lccv_status = 1
		END
	ELSE
		BEGIN
			set @lccv_status = 101
		END




			INSERT INTO tbCreditCard_Voucher			WITH (ROWLOCK)
			(
				comp_id,
				cc_id,
				bra_id,
				cust_id,
				ccv_total,
				curr_id,
				ccv_cd,
				ccv_MPType,
				ccv_MPPointType,
				ccv_MPPayDate,
				ccv_MPApplyDate,
				ccv_MPDeleteDate,
				ccv_MPRefundDate,
				user_id4Create,
				user_id4Apply,
				user_id4Delete,
				user_id4Refund,
				ccv_status,
				ccv_MPCollectionID,
				ccv_MPResponse,
				ccv_isDECIDIRBP
			)
			VALUES
			(

				@comp_id,
				@cc_id,
				@bra_id,
				@cust_id,
				@ccv_total,
				@curr_id,
				GETDATE(),
				@lMPType,
				@lMPPointType ,
				NULL,
				NULL,
				NULL,
				NULL,
				@user_id,
				NULL,
				NULL,
				NULL,
				@lccv_status,
				NULL,
				NULL,
				@bitIsDECIDIR
			)


			Set @return_value = @@IDENTITY



END




GO





------------------------------------------------------------------------------------------------------
--Date	: 21/02/17
--Author: GA
--Desc	: Pagina de filtros de Vouchers de Tarjetas de Credito
------------------------------------------------------------------------------------------------------

CREATE  procedure [dbo].[spCreditCard_Voucher_IsBalanceOK4Transaction4CCV_Id]
(

		@comp_id					INT,
		@ccv_id						INT
)
as
SET NOCOUNT ON

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	DECLARE @bitIsOK4Collection AS BIT = 'True'
	DECLARE @cust_id			AS INT

	SELECT  @bitIsOK4Collection = 'False',
			@cust_id			= tct.cust_id
		FROM tbCreditCard_VoucherRelations			AS tccvr	WITH (NOLOCK)
		INNER JOIN tbCommercialTransactions			AS tct		WITH (NOLOCK)
			ON	tct.comp_id			= tccvr.comp_id AND
				tct.ct_transaction	= tccvr.ct_transaction
		LEFT JOIN tbCommercialTransactionsLoan		AS tctl		WITH (NOLOCK)
			ON	tctl.comp_id		= tccvr.comp_id AND
				tctl.ct_transaction = tccvr.ct_transaction	AND
				tctl.ctl_id			= tccvr.ctl_id
		WHERE	tccvr.comp_id	= @comp_id	AND
				tccvr.ccv_id	= @ccv_id	AND
				(
					tct.ct_ABalance = 0
					OR
					(
						tctl.ct_ABalance IS NOT NULL
							AND
						tctl.ct_ABalance < 0.1
					)
				)


	IF @bitIsOK4Collection = 'False'
		BEGIN
			INSERT INTO tbCreditCard_VoucherRelations_MPAlredyPaidLog
			(
				comp_id,
				cust_id,
				ccv_id
			)
			VALUES
			(
				@comp_id,
				@cust_id,
				@ccv_id
			)
		END

	SELECT @bitIsOK4Collection [isOK]


END
GO





------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: actualizamos estados de vouchers
--
------------------------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spCreditCard_Voucher_UpdateData]
(

	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@ccv_id				INT,
	@cv_status			INT



)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@ccv_id				INT,
			@cv_status			INT


	SELECT
			@comp_id					= 1,
			@bra_id						= 1,
			@por_cd						= ''

*/
-- ------------------------------------------------------

	declare
		@lMPType			as INT,
		@lccv_status		as INT,
		@lcc_id				AS INT


	set @lcc_id = (SELECT
					tccv.cc_id
	               FROM tbCreditCard_Voucher tccv			WITH (NOLOCK)
					WHERE	tccv.comp_id	= @comp_id		AND
							tccv.ccv_id		= @ccv_id
					)

	set @lMPType = (SELECT
					tcc.cc_MPType
	                FROM tbCreditCard tcc					WITH (NOLOCK)
					WHERE	tcc.comp_id		= @comp_id		AND
							tcc.cc_id		= @lcc_id
					)

		---------	PENDIENTE DE ENVIO
			IF @lMPType = 1
				BEGIN
					set @lccv_status = 1
				END
			ELSE
				BEGIN
					set @lccv_status = 101
				END

		---------	PENDIENTE DE ENVIO

		---------	ENVIADO
			IF @lMPType = 1
				BEGIN
					set @lccv_status = 2
				END
			ELSE
				BEGIN
					set @lccv_status = 102
				END


		---------	ENVIADO

		---------	BORRADO
			IF @lMPType = 1
				BEGIN
					set @lccv_status = 3
				END
			ELSE
				BEGIN
					set @lccv_status = 103
				END

				UPDATE tbCreditCard_Voucher
				SET
					user_id4Delete 		= @user_id,
					ccv_MPDeleteDate	= GETDATE(),
					ccv_status			= @lccv_status

				WHERE comp_id	= @comp_id AND
					  ccv_id	= @ccv_id


		---------	BORRADO


		---------	COBRADO
			IF @lMPType = 1
				BEGIN
					set @lccv_status = 4
				END
			ELSE
				BEGIN
					set @lccv_status = 104
				END

				UPDATE tbCreditCard_Voucher
				SET
					ccv_MPPayDate		= GETDATE(),
					ccv_status			= @lccv_status

				WHERE comp_id	= @comp_id AND
					  ccv_id	= @ccv_id



		---------	COBRADO

		---------	APLICADO

			IF @lMPType = 1
				BEGIN
					set @lccv_status = 5
				END
			ELSE
				BEGIN
					set @lccv_status = 105
				END

				UPDATE tbCreditCard_Voucher
				SET
					user_id4Apply 		= @user_id,
					ccv_MPApplyDate		= GETDATE(),
					ccv_status			= @lccv_status

				WHERE comp_id	= @comp_id AND
					  ccv_id	= @ccv_id

		-----------	APLICADO



		--------	REEMBOLSADO

		IF @lMPType = 1
			BEGIN
				set @lccv_status = 6
			END
		ELSE
			BEGIN
				set @lccv_status = 106
			END

		UPDATE tbCreditCard_Voucher
		SET
			user_id4Refund		= @user_id,
			ccv_MPRefundDate	= GETDATE(),
			ccv_status			= @lccv_status

		WHERE comp_id	= @comp_id AND
			  ccv_id	= @ccv_id


		--------	REEMBOLSADO





END
GO





