create PROCEDURE [dbo].[spCreditCard_Voucher_UpdateData_Cancel]
(

	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@ccv_id				INT,
	@ccv_status			INT,
	@MPResponse			NVARCHAR(500)




)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@ccv_id				INT,
			@cv_status			INT


	SELECT
			@comp_id					= 1,
			@bra_id						= 1,
			@por_cd						= ''

*/
-- ------------------------------------------------------

	declare
		@lMPType			as INT,
		@lccv_status		as INT,
		@lcc_id				AS INT


	set @lcc_id = (SELECT
					tccv.cc_id
	               FROM tbCreditCard_Voucher tccv		WITH (NOLOCK)
					WHERE	tccv.comp_id = @comp_id		AND
							tccv.ccv_id	 = @ccv_id
					)

	set @lMPType = (SELECT
					tcc.cc_MPType
	                FROM tbCreditCard		 tcc		WITH (NOLOCK)
					WHERE	tcc.comp_id = @comp_id		AND
							tcc.cc_id	= @lcc_id
					)

	--Borrado
	IF @lMPType = 1
		BEGIN
			set @lccv_status = 3
		END
	ELSE
		BEGIN
			set @lccv_status = 103
		END

		UPDATE tbCreditCard_Voucher
		SET

			ccv_status			= @lccv_status,
			ccv_MPResponse		= @MPResponse,
			ccv_JSON			= @MPResponse

		WHERE	comp_id			=  @comp_id AND
				cc_id			=  @lcc_id  AND
				ccv_id			=  @ccv_id





END
GO





