CREATE PROCEDURE [dbo].[spCreditCard_Voucher_UpdateData_CollectionPUT]
(

	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@ccv_id				INT,
	@ccv_status			INT,
	@MPCollectionID     INT,
	@MPResponse			NVARCHAR(500),
	@QRCollectionID AS  NVARCHAR(60)




)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@ccv_id				INT,
			@cv_status			INT


	SELECT
			@comp_id					= 1,
			@bra_id						= 1,
			@por_cd						= ''

*/
-- ------------------------------------------------------

	declare
		@lMPType			as INT,
		@lccv_status		as INT,
		@lcc_id				AS INT


	set @lcc_id = (SELECT tccv.cc_id
					   FROM tbCreditCard_Voucher tccv		WITH (NOLOCK)
					   WHERE	tccv.comp_id	= @comp_id		AND
								tccv.ccv_id		= @ccv_id
					)

	set @lMPType = (SELECT tcc.cc_MPType
						FROM tbCreditCard tcc				WITH (NOLOCK)
						WHERE	tcc.comp_id = @comp_id		AND
								tcc.cc_id	= @lcc_id
					)

	--ENVIADO
	IF @lMPType = 1  OR @lMPType = 3
		BEGIN
			set @lccv_status = 2
		END
	ELSE
		BEGIN
			set @lccv_status = 102
		END

		UPDATE tbCreditCard_Voucher
			SET

				ccv_status					= @lccv_status,
				ccv_MPCollectionID			= @MPCollectionID,
				ccv_MPResponse				= @MPResponse,
				ccv_JSON					= @MPResponse,
				ccv_MPQRCollectionID		= @QRCollectionID

			WHERE	comp_id					=  @comp_id AND
					ccv_id					=  @ccv_id





END
GO





