CREATE PROCEDURE [dbo].[spCreditCard_Voucher_UpdateDataFromMercadoLibre]
(

	@comp_id					INT,
	@user_id					INT,
	@ccv_id						INT,
	@ccv_status					INT,
	@ccv_JSonResponse			NTEXT,
	@ccv_installments			DECIMAL(19,4),
	@ccv_installment_amount		DECIMAL(19,4),
	@cv_marketplace_fee			DECIMAL(19,4),
	@ccv_net_received_amount	DECIMAL(19,4),
	@ccv_status_detail			NVARCHAR(80),
	@ccv_authorization_code		NVARCHAR(50),
	@ccv_cardholderName			NVARCHAR(200),
	@ccv_cardholderNameNumber	NVARCHAR(100),
	@ct_transaction_Collection	INT,
	@cvv_collectionError		NVARCHAR(500),
	@ccv_MPId					NVARCHAR(50)


)
AS

BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
		DECLARE
				@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@ccv_id				INT,
				@cv_status			INT


		SELECT
				@comp_id					= 1,
				@bra_id						= 1,
				@por_cd						= ''

	*/
	-- ------------------------------------------------------


	IF @ct_transaction_Collection <= 0 SET @ct_transaction_Collection = NULL


	UPDATE tbCreditCard_Voucher		WITH (ROWLOCK)
		SET ccv_status					=	CASE												--** wekfbwekfbwejkfbwekj 345634   SON 3
												WHEN ccv_status IN (5,105) THEN  ccv_status
												ELSE							 @ccv_status
											END,
			ccv_JSONResponse			= @ccv_JSonResponse,
			ccv_installments			= @ccv_installments,
			ccv_installment_amount		= @ccv_installment_amount,
			cv_marketplace_fee			= @cv_marketplace_fee,
			ccv_net_received_amount		= @ccv_net_received_amount,
			ccv_MPPayDate				= GETDATE(),
			ccv_status_detail			= @ccv_status_detail,
			ccv_authorization_code		= @ccv_authorization_code,
			ccv_cardholderName			= @ccv_cardholderName,
			ccv_cardholderNameNumber	= @ccv_cardholderNameNumber,
			ct_transaction_Collection	= @ct_transaction_Collection,
			cvv_collectionError			= @cvv_collectionError,
			ccv_MPId					= @ccv_MPId

		WHERE comp_id	= @comp_id AND
			  ccv_id	= @ccv_id

END
GO



