CREATE PROCEDURE [dbo].[spCreditCardLiquidationEdit_DeleteData]
(
	@comp_id		AS INT,
	@ct_transaction AS INT
)
AS

BEGIN

	------------------------------------------------------------------------------------
	/*
	DECLARE 	@comp_id		AS INT,
				@ct_transaction AS INT

	SELECT 	@comp_id		= 1,
			@ct_transaction = 13542
	*/
	------------------------------------------------------------------------------------

	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'

	DECLARE @bitOK AS BIT
	SET		@bitOK = 'False'

	DECLARE @intReturnValue			AS INT
	DECLARE @intErrorCode			AS INT
	DECLARE @strErrorDescription	AS NVARCHAR(200)


	DECLARE @intSDId AS INT
	SELECT	@intSDId = tct.sd_id
	FROM tbCommercialTransactions tct					WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @ct_transaction

	IF @intSDId <> 142
		BEGIN
			SELECT 'False' [isOK]
			RETURN
		END


	UPDATE tbCreditCardMovements						WITH (ROWLOCK)
		SET	ccm_isPayed = 'False'
		FROM tbCreditCardMovements						tmp
		INNER JOIN tbCreditCardLiquidationsMovements	tcclm
			ON	tcclm.comp_id			= tmp.comp_id	AND
				tcclm.ccm_id			= tmp.ccm_id
		WHERE	tcclm.comp_id			= @comp_id		AND
				tcclm.ct_transaction	= @ct_transaction


	DELETE FROM tbCreditCardLiquidationsMovements		WITH (ROWLOCK)
		WHERE	comp_id			= @comp_id				AND
				ct_transaction	= @ct_transaction


	EXEC [spCommercialTransactions_deleteAll]	@comp_id,
												@ct_transaction,
												2,
												'False' ,
												@intReturnValue			OUTPUT,
												@intErrorCode			OUTPUT,
												@strErrorDescription	OUTPUT

	IF @intErrorCode = 0
		BEGIN
			SET		@bitOK = 'True'
		END

	SELECT @bitOK		 [isOK]

END
GO




