--Date		31/05/2016
--Author	GA
---------------------------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spCreditCardLiquidationEdit_GetDataByFilters]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@prof_id				INT,
	@bra_id4Filter			INT,
	@optiontypemov			INT,-- 140:Imputaciones Bancarias - (Entrada),141:Imputaciones Bancarias - (Salida),142:Liquidación de T. de Crédito,143:Extracto Bancario (Resumen)
	@ba_id					INT,
	@ccg_id					INT,
	@cc_id					INT,
	@datefrom				DATETIME,
	@dateto					DATETIME

)
AS

BEGIN


	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	-- --------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------
	/*
	DECLARE
	@comp_id    INT,
	@lang_id    INT,
	@bra_id     INT,
	@user_id    INT,
	@prof_id    INT,
	@bra_id4Filter   INT,
	@optiontypemov   INT,-- 140:Imputaciones Bancarias - (Entrada),
					   -- 141:Imputaciones Bancarias - (Salida),
					   -- 142:Liquidación de T. de Crédito,
					   -- 143:Extracto Bancario (Resumen)
	@ba_id     INT,
	@ccg_id     INT,
	@cc_id     INT,
	@datefrom    DATETIME,
	@dateto     DATETIME



	SELECT
	@comp_id  =  1,
	@lang_id  =  2,
	@bra_id   =  1,
	@user_id  =  3,
	@prof_id  =  1,

	@bra_id4Filter =  -1,
	@optiontypemov  =  -1,
	@ba_id   =  -1,
	@ccg_id   =  -1,
	@cc_id   =  -1,


	@datefrom  = '2000-01-01',
	@dateto   = '2999-08-31'
*/
	-- --------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	SELECT distinct
		'' [1],
		'' [2],
		'' [3],
		tct.ct_date																			[ct_date],
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)	[Comprobante],
		tct.ct_total																		[ct_total], --task 89 authogar 12/12/16
		ba.ba_desc																			[ba_desc],
		isnull(ts.supp_name,'')																[supp_name],

		--td.sd_desc																		[sd_desc],
		--isnull(tccg.ccg_desc,'')															[ccg_desc],
		--isnull(tcc.cc_desc	,'')														[cc_desc],
		(SELECT
			top 1 tath.hacc_number
			FROM tbAccountTransactionDetail			tatd		WITH (NOLOCK)

			INNER JOIN tbAccountTransactionHead		tath		WITH (NOLOCK)
			ON	tath.comp_id			= tatd.comp_id		AND
				tath.bra_id				= tatd.bra_id		AND
				tath.hacc_transaction	= tatd.hacc_transaction
			WHERE	tatd.comp_id		= @comp_id AND				-- ts.comp_id
					tatd.ct_transaction = tct.ct_transaction)								[hacc_number],
		td.sd_desc,
		tct.ct_transaction																	[ID]

	FROM	tbCommercialTransactions						tct			WITH (NOLOCK)

	INNER JOIN tbsysDocuments								td			WITH (NOLOCK)
		ON	td.sd_id			= tct.sd_id

	INNER JOIN tbBankingAccounts							ba			WITH (NOLOCK)
		ON	ba.comp_id			= tct.comp_id			AND
			ba.ba_id			= tct.ba_id

	LEFT JOIN tbSupplier									ts			WITH (NOLOCK)
		ON	ts.comp_id			= tct.comp_id			AND
			ts.supp_id			= tct.supp_id4CreditCardLiquidation

	--LEFT JOIN tbCreditCardLiquidationsMovements				tcclm		WITH (NOLOCK)
	--	ON	tcclm.comp_id		 = tct.comp_id			AND
	--		tcclm.ct_transaction = tct.ct_transaction

	--LEFT JOIN tbCreditCardMovements							tccm		WITH (NOLOCK)
	--	ON	tccm.comp_id		= tcclm.comp_id			AND
	--		tccm.ccm_id			= tcclm.ccm_id

	--LEFT JOIN tbCreditCard									tcc			WITH (NOLOCK)
	--	ON	tcc.comp_id			= tccm.comp_id			AND
	--		tcc.cc_id			= tccm.cc_id

	--LEFT JOIN tbCreditCard_Group							tccg		WITH (NOLOCK)
	--	ON	tccg.comp_id		= tcc.comp_id			AND
	--		tccg.ccg_id			= tcc.ccg_id

	WHERE	(tct.comp_id		= @comp_id)
	AND		(tct.ct_date		BETWEEN @datefrom AND @dateto)
	AND		(@optiontypemov = -1	OR	td.sd_id	= @optiontypemov)	-- Tipo de Mov:
	   			                   	  	        	                		-- 140:Imputaciones Bancarias - (Entrada),
		              														-- 141:Imputaciones Bancarias - (Salida),
		              														-- 142:Liquidación de T. de Crédito,
		              														-- 143:Extracto Bancario (Resumen)
	AND		(@ba_id			= -1	OR	ba.ba_id	= @ba_id)
	AND		(@bra_id4Filter = -1	OR	tct.bra_id	= @bra_id4Filter)
	AND
		CASE
			WHEN @ccg_id = -1		THEN 1
			WHEN EXISTS(
							SELECT TOP 1 1
								FROM tbCreditCardLiquidationsMovements tcclm		WITH (NOLOCK)
								INNER JOIN tbCreditCardMovements tccm				WITH (NOLOCK)
									ON	tccm.comp_id	= tcclm.comp_id AND
										tccm.ccm_id		= tcclm.ccm_id
								INNER JOIN tbCreditCard tcc							WITH (NOLOCK)
									ON	tcc.comp_id		= tccm.comp_id AND
										tcc.cc_id		= tccm.cc_id
								WHERE	tct.comp_id			= @comp_id AND
										tct.ct_transaction	= tcclm.ct_transaction AND
										tcc.ccg_id			= @ccg_id
								)	THEN 1
			ELSE						 0
		END	= 1

	AND
		CASE
			WHEN @cc_id = -1		THEN 1
			WHEN EXISTS(
							SELECT TOP 1 1
								FROM tbCreditCardLiquidationsMovements tcclm		WITH (NOLOCK)
								INNER JOIN tbCreditCardMovements tccm				WITH (NOLOCK)
									ON	tccm.comp_id	= tcclm.comp_id AND
										tccm.ccm_id		= tcclm.ccm_id
								INNER JOIN tbCreditCard tcc							WITH (NOLOCK)
									ON	tcc.comp_id		= tccm.comp_id AND
										tcc.cc_id		= tccm.cc_id
								WHERE	tct.comp_id			= @comp_id AND
										tct.ct_transaction	= tcclm.ct_transaction AND
										tccm.cc_id			= @cc_id
								)	THEN 1
			ELSE						 0
		END	= 1


	--AND		(@ccg_id		= -1	OR	tcc.ccg_id	= @ccg_id)
	--AND		(@cc_id			= -1	OR	tcc.cc_id	= @cc_id)


	ORDER BY tct.ct_date desc
END
GO






CREATE PROCEDURE [dbo].[spCreditCardLiquidationEdit_UpdateData]
(
	@comp_id		AS INT,
	@ct_docNumber	AS NVARCHAR(50),
	@ct_date		AS DATETIME,
	@supp_id		AS INT,
	@ba_id			AS INT,
	@ct_transaction AS INT

)
AS

BEGIN

	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'


	-------------------------------------------------
	/*
	DECLARE

	SELECT
	*/
	-------------------------------------------------

		if	(@supp_id			= -1)	set	@supp_id	= NULL



		UPDATE dbo.tbCommercialTransactions
			SET ct_date							= @ct_date,
				ct_docNumber					= @ct_docNumber,
				ba_id							= @ba_id,
				supp_id4CreditCardLiquidation	= @supp_id
			WHERE comp_id			= @comp_id
			AND	  ct_transaction	= @ct_transaction




		UPDATE tbBankingTransactions
		SET
			ba_id = @ba_id
			WHERE comp_id			= @comp_id			AND
				  ct_transaction	= @ct_transaction

END
GO




