--- date : 08/04/15
--- getcombo mediante tarjeta de credito ( cc_id )
--------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spCreditCardLoanPlan_CreditCard_GetCombo]
(

	@comp_id			INT,
	@lang_id			INT,
	@cc_id				INT,
	@bra_id				INT

)
AS

	BEGIN



	set nocount on


	--------------------------------------------------------------------------

	/*
	DECLARE 	@comp_id			int,
				@lang_id			int,
				@cc_id				int,
				@bra_id				INT


	SELECT 		@comp_id			= 1,
				@lang_id			= 2,
				@cc_id				= 1,
				@bra_id				= 1
*/

	--------------------------------------------------------------------------



	SELECT
		clp.ccp_id							[id],
		clp.ccp_desc						[desc]

	from	tbCreditCardLoanPlan			clp	WITH (NOLOCK)

		where	comp_id			= @comp_id	AND
				cc_id			= @cc_id	AND
				(
					clp.brag_id IS NULL OR

					EXISTS(	SELECT TOP 1  1
					       		FROM tbBranchGroupDetail				tbgd
					       		WHERE	tbgd.comp_id	= clp.comp_id	AND
					       				tbgd.brag_id	= clp.brag_id	AND
					       				tbgd.bra_id		= @bra_id)

				)								AND
				ccp_disabled	= 'False'


		order by	ccp_desc



	END
GO




