-- MOS 11-2020
--------------------------------------------------------------------------


CREATE  PROCEDURE [dbo].[spCreditCardLoanPlan_CreditCard_GetComboByItem]
(

	@comp_id			INT,
	@lang_id			INT,
	@cc_id				INT,
	@bra_id				INT,
	@item_id			INT

)
AS

BEGIN



	set nocount on


	--------------------------------------------------------------------------

	/*
	DECLARE 	@comp_id			int,
				@lang_id			int,
				@cc_id				int,
				@bra_id				INT


	SELECT 		@comp_id			= 1,
				@lang_id			= 2,
				@cc_id				= 1,
				@bra_id				= 1
	*/

	--------------------------------------------------------------------------


	IF EXISTS(	SELECT TOP 1 1
	          		FROM tbCreditCardLoanPlanGroupItemRelations AS tcclpgir
	          		INNER JOIN tbCreditCardLoanPlanGroupRelations AS tcclpgr
	          			ON	tcclpgr.comp_id		= tcclpgir.comp_id AND
	          				tcclpgr.ccpg_id		= tcclpgir.ccpg_id
	          		WHERE	tcclpgir.comp_id	= @comp_id AND
	          				tcclpgir.item_id	= @item_id AND
	          				tcclpgr.cc_id		= @cc_id
			)
		BEGIN
			SELECT DISTINCT
				clp.ccp_id							[id],
				clp.ccp_desc						[desc]
				from		tbCreditCardLoanPlan				clp	WITH (NOLOCK)
				INNER JOIN	tbCreditCardLoanPlanGroupRelations	ccr WITH (NOLOCK)
					ON	ccr.ccp_id	= clp.ccp_id	AND
						ccr.cc_id	= clp.cc_id		AND
						ccr.comp_id = clp.comp_id
				INNER JOIN tbCreditCardLoanPlanGroupItemRelations ccri	WITH (NOLOCK)
					ON	ccri.comp_id		= ccr.comp_id AND
						ccri.ccpg_id		= ccr.ccpg_id AND
						ccri.item_id		= @item_id
				where	clp.comp_id			= @comp_id	AND
						clp.cc_id			= @cc_id	AND
						(
							clp.brag_id IS NULL OR

							EXISTS(	SELECT TOP 1  1
					       				FROM tbBranchGroupDetail				tbgd	WITH (NOLOCK)
					       				WHERE	tbgd.comp_id	= clp.comp_id	AND
					       						tbgd.brag_id	= clp.brag_id	AND
					       						tbgd.bra_id		= @bra_id)

						)								AND
						ccp_disabled	= 'False'
				order by	ccp_desc
		END
	ELSE
		BEGIN
			SELECT
				clp.ccp_id							[id],
				clp.ccp_desc						[desc]
				from	tbCreditCardLoanPlan			clp	WITH (NOLOCK)
				where	comp_id			= @comp_id	AND
						cc_id			= @cc_id	AND
						(
							clp.brag_id IS NULL OR

							EXISTS(	SELECT TOP 1  1
					       				FROM tbBranchGroupDetail				tbgd	WITH (NOLOCK)
					       				WHERE	tbgd.comp_id	= clp.comp_id	AND
					       						tbgd.brag_id	= clp.brag_id	AND
					       						tbgd.bra_id		= @bra_id)

						)								AND
						ccp_disabled	= 'False'
				order by	ccp_desc
		END






END
GO




