CREATE PROCEDURE [dbo].[spCreditCardLoanPlan_GetCombo]
(

	@comp_id			INT,
	@lang_id			INT,
	@st_id				INT,
	@bra_id				INT

)
AS

	BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------------------------
	-- TESTING
	-- ------------------------------------------------------------------------
	/*
		DECLARE 	@comp_id			INT,
					@lang_id			INT,
					--@ccp_id				INT,
					@bra_id				INT,
					@st_id				INT


		SELECT 		@comp_id			= 1,
					@lang_id			= 2,
					--@ccp_id				= 87,
					@st_id				= 17,
					@bra_id				= 1
	*/
	-- ------------------------------------------------------------------------


	DECLARE @cc_id AS INT
	SELECT	@cc_id = tst.cc_id
		FROM tbSalesTerms tst		WITH (NOLOCK)
		WHERE	tst.comp_id = @comp_id AND
				tst.st_id	= @st_id

	SELECT
		clp.ccp_id		[id],
		clp.ccp_desc	[desc],
		clp.brag_id

		FROM	tbCreditCardLoanPlan	clp WITH (NOLOCK)
		WHERE	clp.comp_id			= @comp_id	AND
				clp.cc_id			= @cc_id	AND
				(
					clp.brag_id IS NULL OR

					EXISTS(	SELECT 1
					       		FROM tbBranchGroupDetail				tbgd
					       		WHERE	tbgd.comp_id	= clp.comp_id	AND
					       				tbgd.brag_id	= clp.brag_id	AND
					       				tbgd.bra_id		= @bra_id)

				)								AND
				ccp_disabled	= 'False'
		ORDER BY	ccp_desc



	END
GO


CREATE PROCEDURE [dbo].[spCreditCardLoanPlan_GetComboAvailable4SaleOrderCreditCards]
(
	@comp_id	INT,
	@bra_id		INT,
	@cc_id		INT
)
AS

	BEGIN
		-- ------------------------------------------
		-- TESTING
		-- ------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@cc_id		INT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@cc_id		= 7
		*/
		-- ------------------------------------------

		SET NOCOUNT ON



		SELECT
			tcclp.ccp_id													[Id],
			tcclp.ccp_desc													[Desc]
			FROM tbCreditCardLoanPlan										tcclp
			WHERE	tcclp.comp_id								= @comp_id	AND
					tcclp.cc_id									= @cc_id	AND
					tcclp.ccp_isAvailable4saleOrderCreditCards	= 'True'	AND
					(
						EXISTS	(
								SELECT DISTINCT
									tbgd.brag_id
									FROM tbBranchGroupDetail					tbgd
									WHERE	tbgd.comp_id	= tcclp.comp_id		AND
											tbgd.brag_id	= tcclp.brag_id		AND
											tbgd.bra_id		= @bra_id
							)				OR
						tcclp.brag_id IS NULL
					)


	END


GO




