--- GA
--- Cargamos los planes dependiendo la tarjeta de credito seleccionada
--------------------------------------------------------------------------
create PROCEDURE [dbo].[spCreditCardLoanPlan_GetComboByCreditCard]
(

	@comp_id			INT,
	@lang_id			INT,
	@cc_id				INT

)
AS

	BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------------------------
	-- TESTING
	-- ------------------------------------------------------------------------
	/*
		DECLARE 	@comp_id			INT,
					@lang_id			INT,

	@cc_id				INT


		SELECT 		@comp_id			= 1,
					@lang_id			= 2,
					@cc_id			= 2
	*/
	-- ------------------------------------------------------------------------



	SELECT
		clp.ccp_id		[id],
		clp.ccp_desc	[desc]

		FROM	tbCreditCardLoanPlan	clp WITH (NOLOCK)
		WHERE	clp.comp_id			= @comp_id	AND
				ccp_disabled		= 'False'	AND
				clp.cc_id			= @cc_id

		ORDER BY	ccp_desc



	END
GO




------------------------
-- getDataById
------------------------

CREATE PROCEDURE [dbo].[spCreditCardLoanPlan_getDataById]
(

	@comp_id			INT,
	@cc_id				INT,
	@ccp_id				INT

)
as

BEGIN


	set nocount on


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- --------------------------------------
	-- Testing
	-- --------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@cc_id				INT,
					@ccp_id				INT

		SELECT
					@comp_id			= 1,
					@cc_id				= -1,
					@ccp_id				= 8

	*/
	-- --------------------------------------


	IF @cc_id > 0
		BEGIN

			SELECT
				ISNULL(tcclp.ccp_disabled,'False')					[ccp_disabled],
				ISNULL(tcclp.ccp_percentage,0)						[ccp_percentage],
				ISNULL(tcclp.ccp_plusPercentage,0)					[ccp_plusPercentage],
				ISNULL(tcclp.ccp_percentage4QuotePay,0)				[ccp_percentage4QuotePay],
				ISNULL(tcclp.ccp_PaymentsQty,-1)					[ccp_PaymentsQty],
				-1													[st_id],
				tcclp.cc_id,
				ISNULL(tcclp.disc_id,-1)							[disc_idRelated],
				ISNULL(tcclp.ccp_id,-1)								[ccp_id],
				ISNULL(tcclp.ccp_desc,'*')							[ccp_desc],
				''													[NPS_Plan],
				ISNULL(tcclp.VISATP_AvailableMethods,'')			[VISATP_AvailableMethods],
				ISNULL(tcclp.VISATP_MAXINSTALLMENTS,0)				[VISATP_MAXINSTALLMENTS],
				ISNULL(tcclp.VISATP_MININSTALLMENTS,0)				[VISATP_MININSTALLMENTS],
				ISNULL(tcclp.DECIDIR_enabled,'False')				[DECIDIR_enabled],
				ISNULL(tc.curr_symbol,'ARS')						[DECIDIR_curr_id],
				ISNULL(tcclp.DECIDIR_installments,1)				[DECIDIR_installments],
				ISNULL(tcclp.DECIDIR_payment_method_id,0)			[DECIDIR_payment_method_id],
				ISNULL(tcclp.DECIDIR_PrivateApiKey,'')				[DECIDIR_PrivateApiKey],
				ISNULL(tcclp.DECIDIR_PublicApiKey,'')				[DECIDIR_PublicApiKey],
				ISNULL(tcclp.DECIDIR_note4Buyer,'')					[DECIDIR_note4Buyer],
				ISNULL(tcclp.DECIDIR_hasFraud_Detection,'False')	[DECIDIR_hasFraud_Detection],
				ISNULL(tcclp.DECIDIR_days_to_delivery,0)			[DECIDIR_days_to_delivery],
				ISNULL(tcclp.DECIDIR_dispatch_method,'')			[DECIDIR_dispatch_method],
				ISNULL(tcclp.DECIDIR_developmentMode,'False')		[DECIDIR_developmentMode],
				ISNULL(tcclp.ccp_discountPlanCoeficient,0)		AS  ccp_discountPlanCoeficient,
				ISNULL(tcclp.MOBBEX_Installments,'')				[MOBBEX_Installments],
				ISNULL(tcclp.MOBBEX_Sources,'')						[MOBBEX_Sources],
				ISNULL(tcclp.DECIDIR_exclude_csmdds,'False')		[DECIDIR_exclude_csmdds]

				FROM tbCreditCardLoanPlan							tcclp		WITH (NOLOCK)
				LEFT JOIN tbsysCurrency								tc			WITH (NOLOCK)
					ON tc.curr_id = tcclp.DECIDIR_curr_id
				WHERE	tcclp.comp_id	=	@comp_id	AND
						tcclp.cc_id		=   @cc_id		AND
						tcclp.ccp_id	=	@ccp_id

		END

	ELSE
		BEGIN

			SELECT	TOP 1
				CASE
					WHEN ISNULL(tcclp.ccp_disabled,0) = 'False' AND ISNULL(tst.st_disabled,0) = 'False' THEN	'False'
					ELSE																						'True'
				END													[ccp_disabled],
				ISNULL(tcclp.ccp_percentage,0)						[ccp_percentage],
				ISNULL(tcclp.ccp_plusPercentage,0)					[ccp_plusPercentage],
				ISNULL(tcclp.ccp_percentage4QuotePay,0)				[ccp_percentage4QuotePay],
				ISNULL(tcclp.ccp_PaymentsQty,-1)					[ccp_PaymentsQty],
				ISNULL(tcclp.st_id,ISNULL(tst.st_id,-1))			[st_id],
				tcclp.cc_id,
				ISNULL(tcclp.disc_id,-1)							[disc_idRelated],
				ISNULL(tcclp.ccp_id,-1)								[ccp_id],
				ISNULL(tcclp.ccp_desc,'*')							[ccp_desc],
				ISNULL(tcclp.NPS_Plan,'')							[NPS_Plan],
				ISNULL(tcclp.VISATP_AvailableMethods,'')			[VISATP_AvailableMethods],
				ISNULL(tcclp.VISATP_MAXINSTALLMENTS,0)				[VISATP_MAXINSTALLMENTS],
				ISNULL(tcclp.VISATP_MININSTALLMENTS,0)				[VISATP_MININSTALLMENTS],
				ISNULL(tcclp.DECIDIR_enabled,'False')				[DECIDIR_enabled],
				ISNULL(tc.curr_symbol,'ARS')						[DECIDIR_curr_id],
				ISNULL(tcclp.DECIDIR_installments,1)				[DECIDIR_installments],
				ISNULL(tcclp.DECIDIR_payment_method_id,0)			[DECIDIR_payment_method_id],
				ISNULL(tcclp.DECIDIR_PrivateApiKey,'')				[DECIDIR_PrivateApiKey],
				ISNULL(tcclp.DECIDIR_PublicApiKey,'')				[DECIDIR_PublicApiKey],
				ISNULL(tcclp.DECIDIR_note4Buyer,'')					[DECIDIR_note4Buyer],
				ISNULL(tcclp.DECIDIR_hasFraud_Detection,'False')	[DECIDIR_hasFraud_Detection],
				ISNULL(tcclp.DECIDIR_days_to_delivery,0)			[DECIDIR_days_to_delivery],
				ISNULL(tcclp.DECIDIR_dispatch_method,'')			[DECIDIR_dispatch_method],
				ISNULL(tcclp.DECIDIR_developmentMode,'False')		[DECIDIR_developmentMode],
				ISNULL(tcclp.ccp_discountPlanCoeficient,0)		AS  ccp_discountPlanCoeficient,
				ISNULL(tcclp.MOBBEX_Installments,'')				[MOBBEX_Installments],
				ISNULL(tcclp.MOBBEX_Sources,'')						[MOBBEX_Sources],
				ISNULL(tcclp.DECIDIR_exclude_csmdds,'False')		[DECIDIR_exclude_csmdds]

				FROM tbCreditCardLoanPlan							tcclp		WITH (NOLOCK)
				LEFT JOIN tbSalesTerms								tst			WITH (NOLOCK)
					ON	tst.comp_id		= tcclp.comp_id		AND
						tst.cc_id		= tcclp.cc_id		AND
						tst.st_disabled = 'False'
				LEFT JOIN tbsysCurrency								tc			WITH (NOLOCK)
					ON tc.curr_id = tcclp.DECIDIR_curr_id
				WHERE	tcclp.comp_id	=	@comp_id	AND
						tcclp.ccp_id	=	@ccp_id		AND
						tcclp.cc_id     =	tst.cc_id


		END


END



















GO

CREATE PROCEDURE spCreditCardLoanPlan_ProcessAuto_Validate
(
	@comp_id			INT,
	@item_code			NVARCHAR(50),
	@ccpg_id_origin		INT,
	@ccpg_id_destiny	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@item_code			NVARCHAR(50),
				@ccpg_id_origin		INT,
				@ccpg_id_destiny	INT
		*/
		-- --------------------------------------------

		DECLARE
			@bolIsValid AS BIT
		SET @bolIsValid = 'True'

		-- ---------------------------------------------------------------------
		-- EXISTE ITEM_CODE?
		-- ---------------------------------------------------------------------
		IF NOT EXISTS (SELECT  1
						FROM tbItem AS						ti	WITH(NOLOCK)
						WHERE	ti.comp_id		= @comp_id	AND
								ti.item_code	= @item_code)
			BEGIN
				SET @bolIsValid = 'False'
			END
		-- ---------------------------------------------------------------------

		-- ---------------------------------------------------------------------
		-- EXISTE ORIGIN
		-- ---------------------------------------------------------------------
		IF NOT EXISTS (SELECT 1
						FROM tbCreditCardLoanPlanGroup		AS tcclpg	WITH(NOLOCK)
						WHERE	tcclpg.comp_id = @comp_id	AND
								tcclpg.ccpg_id = @ccpg_id_origin)
			BEGIN
				SET @bolIsValid = 'False'
			END
		-- ---------------------------------------------------------------------

		-- ---------------------------------------------------------------------
		-- EXISTE DESTINY?
		-- ---------------------------------------------------------------------
		IF NOT EXISTS (SELECT 1
						FROM tbCreditCardLoanPlanGroup		AS tcclpg	WITH(NOLOCK)
						WHERE	tcclpg.comp_id = @comp_id	AND
								tcclpg.ccpg_id = @ccpg_id_destiny)
			BEGIN
				SET @bolIsValid = 'False'
			END
		-- ---------------------------------------------------------------------

		SELECT @bolIsValid [IsValid]

	END




GO




