CREATE PROCEDURE [dbo].[spCreditCardLoanPlanGroup4Excel_ValidateData]
(
	@comp_id			INT,
	@item_code			NVARCHAR(50),
	@ccpg_id_origin		INT,
	@ccpg_id_destiny	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@item_code			NVARCHAR(50),
				@ccpg_id			INT,
				@ccpg_id_Destiny	INT
			SELECT
				@comp_id			= 1,
				@item_code			= '',
				@ccpg_id			= 1,
				@ccpg_id_Destiny	= 1
		*/
		-- -----------------------------------------------------

		DECLARE
			@strErrorSummary	AS NVARCHAR(400),
			@bolHasErrors		AS BIT
		SET @strErrorSummary	= ''
		SET @bolHasErrors		= 'False'

		IF NOT EXISTS(SELECT 1
						FROM tbCreditCardLoanPlanGroup		AS tcclpg	WITH(NOLOCK)
						WHERE	tcclpg.comp_id = @comp_id	AND
								tcclpg.ccpg_id = @ccpg_id_origin)
			BEGIN
				SET @bolHasErrors		= 'True'
				SET @strErrorSummary = 'El ID de Grupo de Plan de Tarjeta de Crédito de Origen no existe / '
			END

		IF NOT EXISTS(SELECT 1
						FROM tbItem							AS ti	WITH(NOLOCK)
						WHERE	ti.comp_id		= @comp_id	AND
								ti.item_code	= @item_code)
			BEGIN
				SET @bolHasErrors		= 'True'
				SET @strErrorSummary = @strErrorSummary + 'El Código de Artículo ingresado no existe / '
			END

		IF @ccpg_id_Destiny = -1
			BEGIN
				IF NOT EXISTS(SELECT 1
						FROM tbCreditCardLoanPlanGroup	AS tcclpg	WITH(NOLOCK)
						WHERE	tcclpg.comp_id = @comp_id AND
								tcclpg.ccpg_id = @ccpg_id_Destiny)
				BEGIN
					SET @bolHasErrors		= 'True'
					SET @strErrorSummary = @strErrorSummary + 'El ID de Grupo de Plan de Tarjeta de Crédito de Destino no existe / '
				END
			END


		SELECT
			@bolHasErrors		AS HasErrors,
			@strErrorSummary	AS ErrorSummary

	END







GO



CREATE PROCEDURE [dbo].[spCreditCardLoanPlanGroupItemRelations_DeleteData]
(
		@comp_id				INT,
		@ccprg_id				INT,
		@bra_id					INT,
		@user_id				INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'

	/*
	Declare @comp_id			Int,
			@Item_id			Int,
			@Item_id_1			Int,
			@iasso_qty			decimal (19,7)

	Select @comp_id				= 1,
		   @Item_id			    = 232,
		   @Item_id_1			= 238,
		   @iasso_qty			= '10,0'

	*/

	DECLARE
		@DeletedRecordParameters	NVARCHAR(1000),
		@ccpg_id					INT,
		@item_id					INT,
		@ccpg_hasLimit				BIT,
		@ccpg_fromDate				DATETIME,
		@ccpg_toDate				DATETIME

	SELECT
		@ccpg_id		= t.ccpg_id,
		@item_id		= t.item_id,
		@ccpg_hasLimit	= t.ccpg_hasLimit,
		@ccpg_fromDate	= t.ccpg_fromDate,
		@ccpg_toDate	= t.ccpg_toDate
		FROM tbCreditCardLoanPlanGroupItemRelations t	WITH(NOLOCK)
		WHERE	t.comp_id = @comp_id AND
				t.ccprg_id = @ccprg_id


	SET @DeletedRecordParameters = 'Datos ID Grupo de Tarjetas; ' + CONVERT(VARCHAR, @ccpg_id) + ' ID de Artículo: ' + CONVERT(VARCHAR,@item_id) + ' Tiene Límite: ' + CONVERT(VARCHAR,@ccpg_hasLimit) + ' Fecha de Vigencia desde: ' + CONVERT(VARCHAR, @ccpg_fromDate) + ' Fecha de Vigencia hasta: ' + CONVERT(VARCHAR,@ccpg_toDate)
	Delete FROM tbCreditCardLoanPlanGroupItemRelations
	Where	comp_id				= @comp_id
	and	    ccprg_id			= @ccprg_id

	DECLARE @rv INT
	EXEC spSecurityLog_insertData
		@comp_id,
		@bra_id,
		@user_id,
		'Eliminación de Asignación ',
		@DeletedRecordParameters,
		'',
		'',
		NULL,
		3000,
		NULL,
		NULL,
		NULL,
		NULL,
		NULL,
		NULL,
		NULL,	-- Parte: 550
		NULL,	-- Parte: 550
		NULL,
		NULL,
		NULL,
		'',
		@return_value = @rv OUTPUT



	END






GO





-- (00932) Asignar Artículos a Grupos de Planes de Tarjetas de Crédito
-- BTN Eliminar masivamente



CREATE PROCEDURE [dbo].[spCreditCardLoanPlanGroupItemRelations_DeleteDataMassive]
(
		@comp_id				Int,
		@Item_id				Int,
		@ccpg_id				Int,
		@ItemGuid				UNIQUEIDENTIFIER,
		@haslimit				INT,
		@BegindateFrom			DATETIME,
		@BegindateTo			DATETIME,
		@EnddateFrom			DATETIME,
		@EnddateTo				DATETIME,
		@user_id				INT,
		@bra_id					INT
)
AS
	BEGIN
		SET NOCOUNT ON
		/*
		Declare @comp_id			Int,
				@Item_id			Int,
				@Item_id_1			Int,
				@iasso_qty			decimal (19,7)

		Select @comp_id				= 1,
			   @Item_id			    = 232,
			   @Item_id_1			= 238,
			   @iasso_qty			= '10,0'

		*/


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT NULL UNIQUE CLUSTERED)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf	WITH (NOLOCK)
				WHERE	tcf.sl_guid		= @ItemGuid     AND
						tcf.sl_selected = 'True'

		DECLARE
			@bolHasItems2Delete		BIT = 'True'
		IF (SELECT COUNT(*) FROM @tblComplexFilter_Items) = 0
			BEGIN
				SET @bolHasItems2Delete = 'False'
			END
		-- -------------------------------------------------------------


		DELETE
			tbCreditCardLoanPlanGroupItemRelations
			FROM tbCreditCardLoanPlanGroupItemRelations							tcclpir	WITH(NOLOCK)
				INNER JOIN @tblComplexFilter_Items								tcfi
					ON tcfi.item_id = tcclpir.item_id
			Where comp_id		= @comp_id														AND
					(@ccpg_id  = -1		OR		ccpg_id							= @ccpg_id)		AND
					(@haslimit = -1		OR		ISNULL(ccpg_hasLimit,'False')	= @haslimit)	AND
					(ccpg_fromDate	BETWEEN @BegindateFrom	AND @BegindateTo)					AND
					(ccpg_toDate	BETWEEN @EnddateFrom	AND @EnddateTo)


		IF @bolHasItems2Delete = 'True'
			BEGIN

				DECLARE
					@DeletedRecordParameters	NVARCHAR(1000)
				SET @DeletedRecordParameters = 'Datos ID Grupo de Tarjetas; ' + CONVERT(VARCHAR, @ccpg_id) + ' Tiene Límite: ' + CONVERT(VARCHAR,@haslimit) + ' Entre Fechas de Vigencia Desde: ' + CONVERT(VARCHAR, @BegindateFrom) + '/' + CONVERT(VARCHAR, @BegindateTo) + ' Entre Fechas de Vigencia Hasta: ' + CONVERT(VARCHAR,@EnddateFrom) + '/' + CONVERT(VARCHAR,@EnddateTo)

				DECLARE @rv INT
				EXEC spSecurityLog_insertData
					@comp_id,
					@bra_id,
					@user_id,
					'Eliminación Masiva de Asignaciones',
					@DeletedRecordParameters,
					'',
					'',
					NULL,
					3000,
					NULL,
					NULL,
					NULL,
					NULL,
					NULL,
					NULL,
					NULL,	-- Parte: 550
					NULL,	-- Parte: 550
					NULL,
					NULL,
					NULL,
					'',
					@return_value = @rv OUTPUT
			END

	END



GO


CREATE PROCEDURE [dbo].[spCreditCardLoanPlanGroupItemRelations_GetDataByFilters]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@ItemGuid				UNIQUEIDENTIFIER,
	@item_id				INT,
	@ccpg_id				INT,
	@haslimit				INT,
	@BegindateFrom			DATETIME,
	@BegindateTo			DATETIME,
	@EnddateFrom			DATETIME,
	@EnddateTo				DATETIME

)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@bra_id			INT,
				@prof_id		INT,
				@user_id		INT,
				@ItemGuid		UNIQUEIDENTIFIER,
				@item_id		INT,
				@ccpg_id		INT,
				@haslimit		BIT,
				@dateFrom		DATETIME,
				@dateTo			DATETIME
			SELECT
				@comp_id		= 1,
				@lang_id		= 2,
				@custGuid		= '7B370139-75C6-425A-B9CB-7C900057E31E',
				@dateFrom		= '2017-01-01',
				@dateTo			= '2017-12-31',
				@dateVencFrom	= '2017-01-01',
				@dateVencTo		= '2017-12-31',
				@sd_id			= -1,
					@dateFrom		= '2017-01-01',
				@dateTo			= '2017-12-31',
				@haslimit		= 1
		*/
		-- -----------------------------------------------------




		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT NULL UNIQUE CLUSTERED)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf	WITH (NOLOCK)
				WHERE	tcf.sl_guid		= @ItemGuid     AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				IF @item_id > 0
					BEGIN
						INSERT INTO @tblComplexFilter_Items(item_id) VALUES (@item_id)
					END
				ELSE
					BEGIN
						INSERT INTO @tblComplexFilter_Items(item_id)
							SELECT item_id
								FROM tbItem ti	WITH (NOLOCK)
								WHERE ti.comp_id = @comp_id
						--INSERT INTO @tblComplexFilter_Items( item_id) VALUES (NULL)
					END
			END

		-- -------------------------------------------------------------




		SELECT
			' '																					[1],	--MODIFICAR
			' '																					[-],	--BORRAR
			ti.item_code																		[item_code],
			ti.item_desc																		[item_desc],
			tcclpg.ccpg_desc																	[ccpg_desc],
			tct.ccpg_hasLimit																	[ccpg_hasLimit],
			tct.ccpg_fromDate																	[ccpg_fromDate],
			tct.ccpg_toDate																		[ccpg_toDate],
			--ISNULL(tu.user_lastname + ',' + tu.user_firstname,'')								[user_id4Insert],
			--ISNULL(tu2.user_lastname + ',' + tu2.user_firstname,'')								[user_id4LastUpdate],
			--tct.cclpgir_LastUpdate																[cclpgir_LastUpdate],

			--CONVERT(VARCHAR,tct.ccpg_id) + '-' + CONVERT(VARCHAR,tct.item_id)					[ID]
			tct.ccprg_id																		[ID]

		FROM tbCreditCardLoanPlanGroupItemRelations												tct			WITH(NOLOCK)

			INNER JOIN tbItem																    ti			WITH(NOLOCK)
			ON		ti.comp_id			= tct.comp_id		AND
					ti.item_id			= tct.item_id

			INNER JOIN tbCreditCardLoanPlanGroup												tcclpg		WITH(NOLOCK)
			ON		tcclpg.comp_id		= tct.comp_id		AND
					tcclpg.ccpg_id		= tct.ccpg_id

			INNER JOIN @tblComplexFilter_Items													tmp
			ON		tmp.item_id			= tct.item_id

			--LEFT JOIN tbUser																	AS tu		WITH(NOLOCK)
			--ON tu.[user_id]				= tct.user_id4Insert

			--LEFT JOIN tbUser																	AS tu2		WITH(NOLOCK)
			--ON tu2.[user_id]			= tct.user_id4LastUpdate


			WHERE	tct.comp_id		= @comp_id																	AND
					(@haslimit = -1		OR		ISNULL(tct.ccpg_hasLimit,'False')			= @haslimit)		AND
					(tct.ccpg_fromDate	BETWEEN @BegindateFrom	AND @BegindateTo)								AND
					(tct.ccpg_toDate	BETWEEN @EnddateFrom	AND @EnddateTo)									AND
					(@ccpg_id = -1		OR		tcclpg.ccpg_id			= @ccpg_id)


	END
GO






CREATE PROCEDURE [dbo].[spCreditCardLoanPlanGroupItemRelations_getDataById]
(
		@comp_id				Int,
		@ccprg_id				Int
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'

		-- ------------------------------------------
		-- TESTING
		-- ------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@Item_id			INT,
				@Item_id_1			INT
			SELECT
				@comp_id			= 1,
				@Item_id			= 231,
				@Item_id_1			= 264
		*/
		-- ------------------------------------------



		SELECT
			tic.comp_id							[comp_id],
			tic.item_id							[item_id],
			tic.ccpg_id							[ccpg_id],
			ISNULL(tic.ccpg_hasLimit,'FALSE')	[ccpg_hasLimit],
			tic.ccpg_fromDate					[ccpg_fromDate],
			tic.ccpg_toDate						[ccpg_toDate],
			user_id4Insert,
			user_id4LastUpdate,
			cclpgir_LastUpdate
			FROM tbCreditCardLoanPlanGroupItemRelations tic	WITH(NOLOCK)
			Where	tic.comp_id				= @comp_id	AND
					tic.ccprg_id			= @ccprg_id


	END
GO





-- Asignar Artículos a Grupos de Planes de Tarjetas de Crédito
-- Insert masivo
-- 11/09/2020
-- GA


CREATE PROCEDURE [dbo].[spCreditCardLoanPlanGroupItemRelations_InsertData]
(
	@comp_id				Int,
	@Item_id				INT,
	@ccpg_id				INT,
	@ItemGuid				UNIQUEIDENTIFIER,
	@haslimit				INT,
	@dateFrom				DATETIME,
	@dateTo					DATETIME,
	@user_id4Insert			INT,
	@user_id4LastUpdate		INT,
	@cclpgir_LastUpdate		DATETIME,
	@bra_id					INT

)
as

set nocount ON

	set dateformat 'ymd'


/*
Declare
	@comp_id			Int,
	@Item_id			INT,
	@ccpg_id			Int

Select @comp_id				= 1,
	   @Item_id			    = 232

*/

BEGIN


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT NULL UNIQUE CLUSTERED)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf	WITH (NOLOCK)
			WHERE	tcf.sl_guid		= @ItemGuid     AND
					tcf.sl_selected = 'True'
	-- -------------------------------------------------------------


	--EXEC spCreditCardLoanPlanGroupItemRelations_DeleteDataMassive @comp_id, -1, @ccpg_id,@ItemGuid


	--INSERT INTO tbCreditCardLoanPlanGroupItemRelations
	--	(
	--		comp_id,
	--		ccpg_id,
	--		item_id,
	--		ccpg_hasLimit,
	--		ccpg_fromDate,
	--		ccpg_toDate
	--	)

	--SELECT
	--		@comp_id,
	--		@ccpg_id,
	--		item_id,
	--		@haslimit,
	--		@dateFrom,
	--		@dateTo

	--		FROM @tblComplexFilter_Items

			--WHERE NOT EXISTS (SELECT
			--					tccp2.item_id
			--					FROM tbCreditCardLoanPlanGroupItemRelations tccp2	WITH (NOLOCK)
			--					INNER JOIN @tblComplexFilter_Items tcci
			--					ON tcci.item_id		= tccp2.item_id
			--					WHERE	tccp2.comp_id = @comp_id AND
			--							tccp2.ccpg_id = @ccpg_id)









			 -- ------------------------------------------------------------------------
			 -- Curosr para poder preguntar si ya existe la relacion con esas fechas vigentes.
			 -- ------------------------------------------------------------------------

			 DECLARE @litem_id AS INT

			 DECLARE curCreditCardLoanPlanGroupItemRelations CURSOR LOCAL FAST_FORWARD FOR

			 SELECT item_id

			 FROM @tblComplexFilter_Items

			 OPEN curCreditCardLoanPlanGroupItemRelations
			 -- lectura anticipada del cursor
			 FETCH  curCreditCardLoanPlanGroupItemRelations INTO @litem_id

			 WHILE @@FETCH_STATUS = 0
			 BEGIN



			 IF NOT EXISTS (SELECT tccpgir.ccpg_id
			              FROM tbCreditCardLoanPlanGroupItemRelations tccpgir
			              WHERE tccpgir.comp_id			= @comp_id  AND
								tccpgir.ccpg_id			= @ccpg_id  AND
								tccpgir.item_id			= @litem_id AND
								tccpgir.ccpg_fromDate	= @dateFrom AND
			                    tccpgir.ccpg_toDate		= @dateTo)
			 BEGIN



					INSERT INTO tbCreditCardLoanPlanGroupItemRelations
						(
							comp_id,
							ccpg_id,
							item_id,
							ccpg_hasLimit,
							ccpg_fromDate,
							ccpg_toDate,
							user_id4Insert,
							user_id4LastUpdate,
							cclpgir_LastUpdate
						)

					SELECT
							@comp_id,
							@ccpg_id,
							@litem_id,
							@haslimit,
							@dateFrom,
							@dateTo,
							@user_id4Insert,
							@user_id4LastUpdate,
							@cclpgir_LastUpdate


					DECLARE @rv INT
					DECLARE
						@strDesc NVARCHAR(1000)
						SET @strDesc = 'Datos ID Grupo de Tarjetas: ' + CONVERT(VARCHAR, @ccpg_id) + ' ID de Artículo: ' + CONVERT(VARCHAR,@litem_id) + ' Tiene Límite: ' + CONVERT(VARCHAR,@haslimit) + ' Fecha de Vigencia desde: ' + CONVERT(VARCHAR, @dateFrom) + ' Fecha de Vigencia hasta: ' + CONVERT(VARCHAR,@dateTo)

					EXEC spSecurityLog_insertData
						@comp_id,
						@bra_id,
						@user_id4Insert,
						'Alta de Asignación ',
						@strDesc,
						'',
						'',
						NULL,
						3000,
						NULL,
						NULL,
						NULL,
						NULL,
						NULL,
						NULL,
						NULL,	-- Parte: 550
						NULL,	-- Parte: 550
						NULL,
						NULL,
						NULL,
						'',
						@return_value = @rv OUTPUT



			 END


			 FETCH  curCreditCardLoanPlanGroupItemRelations INTO @litem_id
			 END

			 CLOSE curCreditCardLoanPlanGroupItemRelations
			 DEALLOCATE curCreditCardLoanPlanGroupItemRelations

			 -- ------------------------------------------------





END
GO



CREATE PROCEDURE [dbo].[spCreditCardLoanPlanGroupItemsRelations_UpdateData4Excel]
(
	@comp_id				INT,
	@ccpg_id_origin			INT,
	@item_code				NVARCHAR(50),
	@ccpg_id_destiny		INT,
	@ccpg_hasLimit			BIT,
	@fromDate				DATETIME,
	@toDate					DATETIME,
	@user_id4LastUpdate		INT,
	@cclpgir_LastUpdate		DATETIME,
	@bra_id					INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@ccpg_id_origin		INT,
				@item_code			NVARCHAR(50),
				@ccpg_id_destiny	INT,
				@ccpg_hasLimit		BIT,
				@fromDate			DATETIME,
				@toDate				DATETIME,
				@user_id4LastUpdate	INT,
				@cclpgir_LastUpdate	DATETIME

			SELECT
				@comp_id			= 1,
				@ccpg_id_origin		= 2,
				@item_code			= 'ART-POS1',
				@ccpg_id_destiny	= 1,
				@ccpg_hasLimit		= 'True',
				@fromDate			= '2023-10-09',
				@toDate				= '2023-10-19',
				@user_id4LastUpdate	= 1,
				@cclpgir_LastUpdate	= GETDATE()
		*/
		-- -----------------------------------------------------

		DECLARE
			@litem_id		INT

		SELECT
			@litem_id				= ti.item_id
			FROM tbItem								AS ti	WITH(NOLOCK)
			WHERE	ti.comp_id		= @comp_id		AND
					ti.item_code	= @item_code

		IF EXISTS(SELECT 1
					FROM tbCreditCardLoanPlanGroupItemRelations AS tcclpgir	WITH(NOLOCK)
					WHERE	tcclpgir.comp_id = @comp_id			AND
							tcclpgir.ccpg_id = @ccpg_id_destiny AND
							tcclpgir.item_id = @litem_id)
			BEGIN
				SELECT
					'RelationAlreadyExists' [ErrorMessage]
			END
		ELSE
		BEGIN
				DECLARE
					@OrigDateFrom	DATETIME,
					@origDateTo		DATETIME,
					@origHasLimit	BIT,
					@OrigDesc		NVARCHAR(1000),
					@ModDesc		NVARCHAR(1000)
				SELECT
					@OrigDateFrom	= t.ccpg_fromDate,
					@origDateTo		= t.ccpg_toDate,
					@origHasLimit	= ISNULL(t.ccpg_hasLimit,'False')
				FROM tbCreditCardLoanPlanGroupItemRelations t
				WHERE	t.comp_id			= @comp_id			AND
						t.ccpg_id			= @ccpg_id_origin	AND
						t.item_id			= @litem_id

				SET @OrigDesc	= ' Datos Originales	ID Grupo de Tarjetas: ' + CONVERT(VARCHAR, @ccpg_id_origin)	+ ' ID de Artículo: ' + CONVERT(VARCHAR,@litem_id) + ' Tiene Límite: ' + CONVERT(VARCHAR,@origHasLimit) + ' Fecha de Vigencia desde: ' + CONVERT(VARCHAR, @OrigDateFrom)	+ ' Fecha de Vigencia hasta: ' + CONVERT(VARCHAR,@OrigDateTo)
				SET @ModDesc	= ' Datos Modificados	ID Grupo de Tarjetas: ' + CONVERT(VARCHAR, @ccpg_id_destiny)	+ ' ID de Artículo: ' + CONVERT(VARCHAR,@litem_id) + ' Tiene Límite: ' + CONVERT(VARCHAR,@ccpg_hasLimit)	+ ' Fecha de Vigencia desde: ' + CONVERT(VARCHAR, @fromDate)		+ ' Fecha de Vigencia hasta: ' + CONVERT(VARCHAR,@toDate)

				DECLARE @rv INT
				EXEC spSecurityLog_insertData
					@comp_id,
					@bra_id,
					@user_id4LastUpdate,
					'Modificación de Asignación ',
					@OrigDesc,
					@ModDesc,
					'',
					NULL,
					3000,
					NULL,
					NULL,
					NULL,
					NULL,
					NULL,
					NULL,
					NULL,	-- Parte: 550
					NULL,	-- Parte: 550
					NULL,
					NULL,
					NULL,
					'',
					@return_value = @rv OUTPUT

				UPDATE tbCreditCardLoanPlanGroupItemRelations
				SET
					ccpg_id				= @ccpg_id_destiny,
					ccpg_hasLimit		= @ccpg_hasLimit,
					ccpg_fromDate		= @fromDate,
					ccpg_toDate			= @toDate,
					user_id4LastUpdate	= @user_id4LastUpdate,
					cclpgir_LastUpdate	= @cclpgir_LastUpdate
				WHERE	comp_id			= @comp_id			AND
						ccpg_id			= @ccpg_id_origin	AND
						item_id			= @litem_id

				SELECT
					'OK' [ErrorMessage]
			END
	END

GO


CREATE PROCEDURE [dbo].[spCreditCardMovements_CheckMovementsByExcel]
(
	@comp_id		INT,
	@guid			UNIQUEIDENTIFIER,
	@ccm_Total		DECIMAL(19,2),
	@ccm_lote		NVARCHAR(50),
	@ccm_cardNumber	NVARCHAR(50)
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@guid			UNIQUEIDENTIFIER,
				@ccm_Total		DECIMAL(19,2),
				@ccm_lote		NVARCHAR(50),
				@ccm_cardNumber	NVARCHAR(50)
			SELECT
				@comp_id		= 1,
				@guid			= '24f72234-66b4-454a-bb78-adce756cc0d4',
				@ccm_Total		= 2,
				@ccm_lote		= '555',
				@ccm_cardNumber	= '32341411231231231'
		*/
		-- ----------------------------------------------------

		SET @ccm_cardNumber =  LTRIM(RTRIM(REPLACE(@ccm_cardNumber,' ','')))

		-- --------------------------------------------------------------------------------
		-- SI ENCUENTRA PARA UNA MISMA COMBINACION DE PARÁMETROS MÁS DE UN REGISTRO,
		-- QUE NO LOS MARQUE Y QUE DEVUELVA COMO QUE NO LOS ENCONTRÓ, CON ESTO SE BUSCA
		-- EVITAR LOS CASOS PARTICULARES QUE SE DAN EN 1 CADA 500 CUPONES
		-- HABLADO CON MARINA POR SKYPE FECHA 27-03-2019
		-- --------------------------------------------------------------------------------
			DECLARE @intMovementsFound AS INT
			SELECT
				@intMovementsFound		= COUNT(*)
				FROM tbCreditCardMovements tccm
				WHERE	comp_id			= @comp_id							AND
						ccm_Total		= @ccm_Total						AND
						ccm_lote		LIKE '%' + @ccm_lote	   + '%'	AND
						--ccm_cardNumber	=  @ccm_cardNumber				AND
						ccm_cardNumber	LIKE '%' + @ccm_cardNumber + '%'	AND
						ccm_isPayed		= 'False'			-- MOS 03-2019, NO SACARR!!!!!

			IF @intMovementsFound > 1
				BEGIN
					SELECT 'False'	[Exists]
					RETURN
				END
		-- --------------------------------------------------------------------------------


		UPDATE tbCreditCardMovements
		SET
			cmm_guid			=	Case
										When IsNull(cmm_isEditing,'false') = 'true'	Then	NULL
										Else												@guid
									End,
			cmm_isEditing		=	Case
										When IsNull(cmm_isEditing,'false') = 'true'	Then	'false'
										Else												'true'
									End,
			cmm_isEditingCD		=	Getdate()
			WHERE	comp_id			= @comp_id							AND
					ccm_Total		= @ccm_Total						AND
					ccm_lote		LIKE '%' + @ccm_lote	   + '%'	AND
					--ccm_cardNumber	=  @ccm_cardNumber					AND
					ccm_cardNumber	LIKE '%' + @ccm_cardNumber + '%'	AND
					ccm_isPayed		= 'False'			-- MOS 03-2019, NO SACARR!!!!!
		IF @@ROWCOUNT > 0
			BEGIN
				SELECT 'True'	[Exists]
			END
		ELSE
			BEGIN
				SELECT 'False'	[Exists]
			END
	END
GO


