CREATE PROCEDURE [dbo].[spCreditCardMovements_Edit_Detail_UpdateData]

		@comp_id						INT,
		@bra_id							INT,
		@ct_transaction					INT,
		@ccm_id							INT,
		@ccm_AutorizationCode			NVARCHAR(50),
		@ccm_receiptNumber				NVARCHAR(50),
		@ccm_customerName				NVARCHAR(100),
		@ccm_customerDocumentNumber	    NVARCHAR(50),
		@cardNumber						NVARCHAR(50),
		@ccm_total						DECIMAL(19,6),
		@ccm_lote						NVARCHAR(50),
		@cc_id							INT,
		@ccp_id							INT



AS

BEGIN

	SET NOCOUNT ON


	IF (@ccp_id = -1)  SET @ccp_id = NULL



	UPDATE tbCreditCardMovements

	SET
		ccm_cardNumber					= @cardNumber,
		ccm_customerDocumentNumber		= @ccm_customerDocumentNumber,
		ccm_customerName				= @ccm_customerName,
		ccm_receiptNumber				= @ccm_receiptNumber,
		ccm_AutorizationCode			= @ccm_AutorizationCode,
		ccm_lote						= @ccm_lote,
		ccm_Total						= @ccm_total,
		cc_id							= @cc_id,
		ccp_id							= @ccp_id


	WHERE  comp_id			= @comp_id			AND
		   bra_id			= @bra_id			AND
		   ct_transaction	= @ct_transaction	AND
		   ccm_id			= @ccm_id

END


GO







CREATE procedure [dbo].[spCreditCardMovements_Edit_getDataByFilters]
(
		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id            INT,

		@TotalOption		INT,
		@TotalFrom		    DECIMAL(19,6),
		@TotalTo			DECIMAL(19,6),
		@cc_id				INT,
		@ccp_id				INT,
		@cccm_id			INT,
		@bra_id4Filter		INT,
		@cardNumber			NVARCHAR(50),
		@ccm_lote			NVARCHAR(50),
		@datefrom			DATETIME,
		@dateto				DATETIME
)

AS

BEGIN

	SET NOCOUNT on


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	-- -------------------------------------------------------------
	-- TESTING
	-- -------------------------------------------------------------
	/*
		declare
					@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@prof_id			INT,
					@user_id            INT,

					@TotalOption		INT,
					@TotalFrom		    DECIMAL(19,6),
					@TotalTo			DECIMAL(19,6),
					@cc_id				INT,
					@ccp_id				INT,
					@cccm_id			INT,
					@bra_id4Filter		INT,
					@cardNumber			NVARCHAR(50),
					@ccm_lote			NVARCHAR(50)

		select
					@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@prof_id			= 1,
					@user_id            = 1,

					@TotalOption		= -1,
					@TotalFrom		    =0,
					@TotalTo			=0,
					@cc_id				= -1,
					@ccp_id				= -1,
					@cccm_id			= -1,
					@bra_id4Filter		= 1,
					@cardNumber			= '',
					@ccm_lote			= ''
	*/
	-- -------------------------------------------------------------



	SELECT
		' '																					[ ],
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ccm.ct_transaction)	[desc],
		ct.ct_date																			[ct_date],
		ccm.ccm_Total																		[ccm_Total],
		ccm.ccm_cardNumber																	[ccm_cardNumber],
		ccm.ccm_receiptNumber																[ccm_receiptNumber],
		ccm.ccm_AutorizationCode															[ccm_AutorizationCode],
		isnull(ccm.ccm_isPayed,'False')														[ccm_isPayed],
		isnull(ccm.ccm_isCancelled,'False')													[ccm_isCancelled],
		isnull(ccm.cmm_isEditing,'False')													[cmm_isEditing],
		ccm.cmm_isEditingCD																	[cmm_isEditingCD],
		IsNull(ccm.ccm_lote,'')																[ccm_lote],
		convert(VARCHAR,ccm.comp_id)		+ '-' +
		convert(VARCHAR,ccm.bra_id)			+ '-' +
		convert(VARCHAR,ccm.ct_transaction) + '-' +
		convert(VARCHAR,ccm.ccm_id)															[ID]

		FROM	dbo.tbCreditCardMovements							ccm			WITH(NOLOCK)

		INNER JOIN dbo.tbCommercialTransactions						ct			WITH(NOLOCK)
		ON  ct.comp_id			= ccm.comp_id			AND
			ct.bra_id			= ccm.bra_id			AND
			ct.ct_transaction	= ccm.ct_transaction


		WHERE   (ccm.comp_id				= @comp_id)
		AND 	(
				(@TotalOption = -1)														or
				(@TotalOption = 0 and ccm.ccm_Total = @TotalFrom)						or
				(@TotalOption = 1 and ccm.ccm_Total > @TotalFrom)						or
				(@TotalOption = 2 and ccm.ccm_Total < @TotalFrom)						or
				(@TotalOption = 3 and ccm.ccm_Total between @TotalFrom and @TotalTo)
				)
		AND     (@cc_id					= -1				OR      ccm.cc_id			= @cc_id)
		AND		(@ccp_id				= -1 	OR		ccm.ccp_id			= @ccp_id )
		AND		(@bra_id4Filter			= -1				OR		ccm.bra_id			= @bra_id4Filter)
		AND     (ccm.cccm_id			= @cccm_id)
		AND		(@ccm_lote				= ''				OR		ccm.ccm_lote		LIKE '%'+ @ccm_lote +'%')
		AND		(@cardNumber			= ''				OR		ccm.ccm_cardNumber	LIKE '%' + @cardNumber + '%')
		AND		(ct.ct_date				between  @datefrom and	@dateto)




END
GO





CREATE procedure [dbo].[spCreditCardMovements_Edit_getDataById]
(
		@comp_id				INT,
		@bra_id					INT,
		@ct_transaction			INT,
		@ccm_id					INT
)

AS

BEGIN

	SET NOCOUNT on


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	-- -------------------------------------------------------------
	-- TESTING
	-- -------------------------------------------------------------
	/*
		declare
				@comp_id				INT,
				@bra_id					INT,
				@ct_transaction			INT,
				@ccm_id					INT

		select
				@comp_id			= 1,
				@ct_transaction		= 8482,
				@bra_id				= 1,
				@ccm_id				= 59

*/
	-- -------------------------------------------------------------



	SELECT

		ccm.ccm_Total,
		ccm.ccm_cardNumber,
		ccm.ccm_cardEmissionDate,
		ccm.ccm_cardExpirationDate,
		isnull(ccm.ccm_customerDocumentNumber,'')		[ccm_customerDocumentNumber],
		isnull(ccm.ccm_customerName,'')					[ccm_customerName],
		isnull(ccm.ccm_receiptNumber,'')				[ccm_receiptNumber],
		isnull(ccm.ccm_AutorizationCode,'')				[ccm_AutorizationCode],
		isnull(ccm.ccm_lote,'')							[ccm_lote] ,
		isnull(ccm.ccp_id,-1)							[ccp_id],
		isnull(ccm.cc_id,-1)							[cc_id]

		FROM	dbo.tbCreditCardMovements							ccm			WITH(NOLOCK)


		WHERE   (ccm.comp_id			= @comp_id)
		AND 	(ccm.bra_id				= @bra_id)
		AND 	(ccm.ct_transaction		= @ct_transaction)
		AND 	(ccm.ccm_id				= @ccm_id)





END
GO


CREATE PROCEDURE [dbo].[spCreditCardMovements_existsAuthorizationCode]
(
	@comp_id					INT,
	@cc_id						INT ,
	@ccm_AutorizationCode		NVARCHAR(50)
)
AS

	BEGIN
		SET NOCOUNT ON


			SET @ccm_AutorizationCode =  dbo.fnStrAllTrim(@ccm_AutorizationCode)


			DECLARE @intMovementsFound AS INT = 0
			SELECT
				@intMovementsFound		= COUNT(*)
				FROM tbCreditCardMovements tccm		WITH (NOLOCK)
				WHERE	comp_id						= @comp_id							AND
						tccm.cc_id					= @cc_id							AND
						tccm.ccm_AutorizationCode	= @ccm_AutorizationCode
						--dbo.fnStrAllTrim(tccm.ccm_AutorizationCode) = @ccm_AutorizationCode  MOS x Speed 06-09-2021
			IF @intMovementsFound >= 1    -- @intMovementsFound > 1 MOS 03-2022, estaba MAL, con que sea 1 ya está.
				BEGIN
					SELECT 1	[Exists]
					RETURN
				END
			ELSE
				BEGIN
					SELECT 0	[Exists]
				END
		-- --------------------------------------------------------------------------------


	END
GO






CREATE PROCEDURE  [dbo].[spCreditCardMovements_freeData]
(
	@guid						UNIQUEIDENTIFIER
)
AS

BEGIN

	set nocount on

	/* libera los datos marcados en la grilla y se ejecuta cuando presiona el boton refresh */
	update dbo.tbCreditCardMovements		WITH (ROWLOCK)
		SET		cmm_isEditing	= 'false',
				--ccm_isPayed		= 'false',   MOS 03-2019, Por las dudas lo saco pero no se logró emular lo dicho por Marina SALVO que por algun error de su BD tome en el Where cupones que no debería.
				cmm_guid		= null
		where	cmm_guid		=	@guid

END


GO







CREATE procedure [dbo].[spCreditCardMovements_getDataByFilters]
(
		@comp_id			INT ,
		@lang_id			INT ,
		@bra_id				INT ,
		@curr_id			INT ,
		@ba_id				INT ,
		@guid				UNIQUEIDENTIFIER,
		@ccg_id				INT,
		@ccm_lote			NVARCHAR(50),
		@bra_id4Filter		INT,
		@cardNumber			NVARCHAR(50),
		@datCtDateFrom		DATETIME,
		@datCtDateTo		DATETIME,
		@TotalOption		INT,
		@TotalFrom		    DECIMAL(19,6),
		@TotalTo			DECIMAL(19,6),
		@cct_id				INT				--Terminales POS

)
AS


BEGIN

	SET NOCOUNT on


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	-- -------------------------------------------------------------
	-- TESTING
	-- -------------------------------------------------------------
	/*
		declare
					@comp_id			INT ,
					@lang_id			INT ,
					@bra_id				INT ,
					@curr_id			INT	,
					@ba_id				int ,
					@guid				UNIQUEIDENTIFIER,
					@ccg_id				INT,
					@ccm_lote			NVARCHAR(50)

		select
					@comp_id			= 1 ,
					@lang_id			= 2 ,
					@bra_id				= 1 ,
					@curr_id			= 1 ,
					@ba_id				= 31,
					@guid				= null,
					@ccg_id				= -1,
					@ccm_lote			= ''
	*/
	-- -------------------------------------------------------------



	select	' ' [ ],
			ccm.cmm_isEditing,
			ccm.ccm_cardNumber,
			ct.ct_date,
			ccm.ccm_receiptNumber,
			tc.curr_desc,
			ccm.ccm_Total,
			tcc.cc_desc,
			tcclp.ccp_code,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ccm.ct_transaction)	[doc],
			isnull(tb.bra_desc,'')																[bra_desc],
			IsNull(ccm.ccm_lote,'')																[ccm_lote],
			ISNULL(ccm.ccm_AutorizationCode,'')													[ccm_AutorizationCode],
			ccm.cmm_guid,
			convert(VARCHAR,ccm.comp_id)		+ '-' +
			convert(VARCHAR,ccm.bra_id)			+ '-' +
			convert(VARCHAR,ccm.ct_transaction) + '-' +
			convert(VARCHAR,ccm.ccm_id)															[ID]

	from	dbo.tbCreditCardMovements					ccm				WITH (NOLOCK)

			LEFT JOIN tbCreditCardLoanPlan tcclp						WITH (NOLOCK)
				ON	tcclp.comp_id	= ccm.comp_id		AND
					tcclp.cc_id		= ccm.cc_id			AND
					tcclp.ccp_id	= ccm.ccp_id

			inner join dbo.tbCommercialTransactions		ct				WITH (NOLOCK)
			ON  ct.comp_id			= ccm.comp_id
			AND ct.bra_id			= ccm.bra_id
			AND ct.ct_transaction	= ccm.ct_transaction

			INNER JOIN dbo.tbBankingAccounts			ba				WITH (NOLOCK)
			ON ba.comp_id			= ccm.comp_id
			AND ba.curr_id			= ccm.curr_id

			INNER JOIN tbsysCurrency					tc				WITH (NOLOCK)
			ON ba.curr_id			= tc.curr_id

			INNER JOIN tbCreditCard tcc									WITH (NOLOCK)
				ON		tcc.comp_id = ccm.comp_id
					AND tcc.cc_id	= ccm.cc_id
					AND tcc.cc_NoLiquidationPending = 'False'

			LEFT JOIN tbBranch tb										WITH (NOLOCK)
				ON		tb.comp_id	= ccm.comp_id
					AND tb.bra_id	= ccm.bra_id

	where   ccm.comp_id				= @comp_id
	--AND     ccm.bra_id				= @bra_id
	AND		ccm.curr_id				= @curr_id
	AND		ba.ba_id				= @ba_id
	AND		(ccm.ccm_isPayed		= 'False'	OR		ccm.ccm_ispayed		IS NULL)
	AND		(ccm.cmm_isEditing		= 'False'	OR		ccm.cmm_isEditing	IS NULL		OR
			(ccm.cmm_isEditing		= 'True'	AND		ccm.cmm_guid		= @guid))
	and		(@ccg_id				= -1		or		tcc.ccg_id			= @ccg_id)
	and		(@ccm_lote				= ''		or		ccm.ccm_lote		like '%'+ @ccm_lote +'%')
	AND		(@cardNumber = ''					OR		ccm.ccm_cardNumber	LIKE '%' + @cardNumber + '%')
	AND 	(
				(@TotalOption = -1)														or
				(@TotalOption = 0 and ccm.ccm_Total = @TotalFrom)						or
				(@TotalOption = 1 and ccm.ccm_Total > @TotalFrom)						or
				(@TotalOption = 2 and ccm.ccm_Total < @TotalFrom)						or
				(@TotalOption = 3 and ccm.ccm_Total between @TotalFrom and @TotalTo)
			)
	AND		ct.ct_date							BETWEEN @datCtDateFrom AND @datCtDateTo
	AND		(@bra_id4Filter = -1				OR		ccm.bra_id			= @bra_id4Filter)
	AND		(@cct_id = -1 OR ccm.cct_id = @cct_id)
	ORDER BY tcc.cc_id


END
GO


CREATE procedure [dbo].[spCreditCardMovements_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@cc_id				Int,
		@dateFrom			Datetime,
		@dateTo				Datetime,
		@bitOnlyLiquidated	BIT,
		@dateFromliq		Datetime,
		@dateToliq			Datetime,
		@cust_id			Int,
		@option				Int,
		@ba_id				Int,
		@brag_id			INT,
		@user_id            INT,
		@bra_id				INT,
		@intBranch4Lang		int



)
AS

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET DATEFORMAT 'ymd'



	-- -------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------
	/*
		DECLARE
			@comp_id			int,
			@lang_id			int,
			@page_id			int,

			@cc_id				Int,
			@dateFrom			Datetime,
			@dateTo				Datetime,
			@bitOnlyLiquidated	BIT,
			@dateFromliq		Datetime,
			@dateToliq			Datetime,
			@cust_id			Int,
			@option				Int,
			@ba_id				Int,
			@brag_id			INT,
			@user_id            INT,
			@bra_id				INT,
			@intBranch4Lang		int

		SELECT
			@comp_id			=1,
			@lang_id			=2,
			@page_id			=10034,

			@cc_id				=-1,
			@dateFrom			='01/01/2000',
			@dateTo				='01/01/9999',
			@bitOnlyLiquidated	= 'False',
			@dateFromliq		= '01/01/2000',
			@dateToliq			= '01/01/9999',
			@cust_id			=-1,
			@option				=0,
			@ba_id				=-1,
			@user_id            =1,
			@bra_id				=-1,
			@brag_id			= 4
	*/
	-- -------------------------------------------------------

	SET	@datefrom		= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET	@dateto			= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')
	SET	@dateFromliq	= dbo.fnGetEnd_or_BeginOfDate(@dateFromliq,'False')
	SET	@dateToliq		= dbo.fnGetEnd_or_BeginOfDate(@dateToliq,'True')


	--ticket 137
	DECLARE @tblCuponesAIncluir TABLE(ccm_id INT PRIMARY KEY)
	IF @bitOnlyLiquidated = 'True'
		BEGIN
			INSERT INTO @tblCuponesAIncluir(ccm_id)
				SELECT tccm.ccm_id
					FROM tbCreditCardMovements tccm						WITH (NOLOCK)
					INNER JOIN tbCreditCardLiquidationsMovements tcclm	WITH (NOLOCK)
						ON	tcclm.comp_id	= tccm.comp_id	AND
							tcclm.ccm_id	= tccm.ccm_id
					INNER JOIN tbCommercialTransactions tct				WITH (NOLOCK)
					ON	tct.comp_id			= tcclm.comp_id	AND
						tct.ct_transaction	= tcclm.ct_transaction
					WHERE	tccm.comp_id	= @comp_id		AND
							--tccm.cc_id		= @cc_id		AND
							(@cc_id			= -1 or tccm.cc_id		= @cc_id) AND
							tct.ct_taxDate BETWEEN @dateFromliq AND @dateToliq
			END
	ELSE
		BEGIN
			INSERT INTO @tblCuponesAIncluir(ccm_id)
				SELECT tccm.ccm_id
					FROM tbCreditCardMovements tccm				WITH (NOLOCK)
					WHERE	tccm.comp_id	= @comp_id		AND
							(@cc_id			= -1 or tccm.cc_id		= @cc_id)
		END





	DECLARE @fun_id INT
	SET @fun_id = 1

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
		FROM tbBranchGroupDetail tbgd
		WHERE	tbgd.comp_id = @comp_id		AND
				tbgd.brag_id = @brag_id


	SELECT	cc.cc_desc																		[cc_desc],
			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction)	[ct_transaction],
			tct.ct_date																		[ct_date],
			ccm.ccm_Total																	[ct_total],
			isnull(tc2.curr_symbol,'')														[curr_desc],
			isnull(tc.cust_name,'')															[cust_name],
			ccm.ccm_cardNumber																[ccm_cardNumber],
			ccm.ccm_receiptNumber															[ccm_receiptNumber],
			ccm.ccm_BranchCurrencyExchange													[ccm_BranchCurrencyExchange],
			o.optval_desc																	[ccm_isPayed],
			tb.bra_desc																		[bra_desc],
			ISNULL(ccm.ccm_lote,'')															[ccm_lote],
			tctliq.ct_taxDate																[ct_taxDate],	-- Fecha de Liquidacion ESTÁ OK???
			tctliq.ct_docNumber																[IDLiquidation],-- Id de Liquidacion que campo es ?
			tu.user_lastname + ',' + tu.user_firstname										[user_name]


	FROM	dbo.tbCreditCardMovements 						ccm		WITH (NOLOCK)

			INNER JOIN @tblCuponesAIncluir					tmpr
			ON tmpr.ccm_id = ccm.ccm_id

			Inner Join dbo.tbCreditCard						cc		WITH (NOLOCK)
			On	cc.comp_id			= ccm.comp_id
			And cc.cc_id			= ccm.cc_id

			left JOIN tbCreditCardLiquidationsMovements		tcclm	WITH (NOLOCK)
			ON	tcclm.comp_id		= ccm.comp_id	AND
				tcclm.ccm_id		= ccm.ccm_id

			left Join tbCommercialTransactions				tctliq		WITH (NOLOCK)
			On  tctliq.comp_id			=	tcclm.comp_id
			--And tct.bra_id			=   ccm.bra_id
			And tctliq.ct_transaction	=   tcclm.ct_transaction


			Inner Join tbCommercialTransactions				tct		WITH (NOLOCK)
			On  tct.comp_id			=	ccm.comp_id
			And tct.ct_transaction	=   ccm.ct_transaction

			LEFT JOIN tbBranch								tb		WITH (NOLOCK)
			ON	tb.comp_id			= ccm.comp_id
			AND tb.bra_id			= ccm.bra_id

			left Join tbCustomer							tc		WITH (NOLOCK)
			On  tc.comp_id			=	ccm.comp_id
			And tc.cust_id			=	tct.cust_id

			left Join tbsysCurrency							tc2		WITH (NOLOCK)
			On	tc2.curr_id			=	ccm.curr_id

			left join [tbsysOptionsValues]					o		WITH (NOLOCK)
			on	o.[optval_id]		= ccm.[ccm_isPayed]
			and	o.[optval_class]	= 1
			and	o.[lang_id]			= @lang_id

			INNER JOIN tbUsers4BranchFilter					vubf	WITH (NOLOCK)
			ON	vubf.comp_id		= tct.comp_id
			AND vubf.bra_id			= tct.bra_id
			AND vubf.[user_id]		= @user_id

			INNER JOIN tbUser								tu
			ON	tu.[user_id]		= tct.[user_id]

			LEFT JOIN @tblBranchs	tmpl
				ON tmpl.bra_id = tct.bra_id


	Where	ccm.[comp_id]	= @comp_id
	and		(@cc_id			= -1    or	cc.[cc_id]			= @cc_id)
	and		(tct.[ct_date]  Between		@dateFrom    And  	@dateTo)
	and		(@cust_id		= -1    or	tc.[cust_id]		= @cust_id)
	and		(@option		= -1    or	ccm.ccm_isPayed		= convert(bit,@option))
	And		(@option		= -1    or  @option  = 1 Or @option = 0 And @ba_id = -1 Or tct.ba_id = @ba_id)
	AND		(@brag_id		= -1	OR  tmpl.bra_id IS NOT NULL)
	--And		(
	--				(@brag_id = -1	AND		tct.bra_id	= @bra_id) OR
	--				(@brag_id <> -1 AND		EXISTS( SELECT 1
	--			                   						FROM	@tblBranchs tmpb
	--			                   						WHERE	tmpb.bra_id = tct.bra_id ))
	--			)


	Order By  tct.ct_date






	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	--/*************************************************************************************************************/
	--/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	--/*************************************************************************************************************/
	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 760
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1)	[params1],

				CASE @cc_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tcc.cc_desc
						FROM dbo.tbCreditCard tcc
						WHERE tcc.cc_id = @cc_id)
				END			[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 177
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)				[params3],

			@datefrom [DateParams1],
				--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))				[params4],



			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 384
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)				[params5],

				@dateto [DateParams2],
				--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))					[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 174
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id) [params7],

				CASE @cust_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tc.cust_name
					 FROM	dbo.tbCustomer tc
					 WHERE	tc.comp_id = @comp_id
					 and    tc.cust_id = @cust_id)
				END		[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 653
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id) [params9],

				CASE @option WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc
					 FROM	tbsysOptionsValues tov
					 WHERE	tov.lang_id = @lang_id
					 And tov.optval_order = @option
					 And tov.optval_class=50)
				END		[params10],



			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 406
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id) [params11],

				CASE @ba_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT TBA.ba_desc
					 FROM	tbBankingAccounts tba
					 WHERE	TBA.comp_id=@comp_id
					 And  TBA.ba_id=@ba_id)

				END		[params12],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 639
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id) [params13],

				CASE @brag_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 30)
				ELSE
					(SELECT tbg.brag_desc
					 FROM	tbBranchGroup tbg
					 WHERE	tbg.comp_id=@comp_id
					 And  tbg.brag_id=@brag_id)

				END		[params14],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 4806
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)				[params15],

				@datefromliq [DateParams3],
				--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))				[params4],



			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 4807
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)				[params16],

				@datetoliq [DateParams4]



END
GO






CREATE procedure [dbo].[spCreditCardMovements_getTotals]
(
		@comp_id			INT,
		@guid				UNIQUEIDENTIFIER
)
AS

BEGIN



	SET NOCOUNT ON

	/*
	declare		@guid		UNIQUEIDENTIFIER

	select 		@guid		= '3d434091-1694-441d-a6dd-24a500caaf72'
	*/


	select		SUM(ccm_Total)  [Totals]

