CREATE PROCEDURE  [dbo].[spCreditCardMovements_insertData]
(
		@comp_id							int,
		@bra_id								int,
		@ct_transaction						int,
		@ccm_id								int,
		@cc_id								int,
		@ccm_Total							decimal(19,6),
		@curr_id							int,
		@ccm_cardNumber						varchar(50),
		@ccm_cardEmissionDate				datetime,
		@ccm_cardExpirationDate				datetime,
		@ccm_customerDocumentNumber			VARCHAR(20),
		@ccm_customerName					VARCHAR(100),
		@ccm_receiptNumber					VARCHAR(50),
		@ccm_AutorizationCode				VARCHAR(50),
		@cccm_id							INT,
		@ccm_BranchCurrencyExchange			DECIMAL(19,5),
		@ccm_isPayed						bit,
		@ccm_isCancelled					bit,
		@cmm_isEditing						bit,
		@cmm_isEditingCD					datetime,
		@cmm_guid							uniqueidentifier,
		@return_value						int output
	)
as
set nocount on

INSERT INTO dbo.tbCreditCardMovements
(comp_id, bra_id, ct_transaction, ccm_id, cc_id, ccm_Total,
	curr_id, ccm_cardNumber, ccm_cardEmissionDate,
	ccm_cardExpirationDate, ccm_customerDocumentNumber,
	ccm_customerName, ccm_receiptNumber, ccm_AutorizationCode,
	cccm_id, ccm_BranchCurrencyExchange, ccm_isPayed,
	ccm_isCancelled, cmm_isEditing, cmm_isEditingCD,
	cmm_guid)

VALUES
(@comp_id , @bra_id , @ct_transaction, @ccm_id, @cc_id, @ccm_Total,
	@curr_id, @ccm_cardNumber, @ccm_cardEmissionDate,
	@ccm_cardExpirationDate, @ccm_customerDocumentNumber,
	@ccm_customerName, @ccm_receiptNumber, @ccm_AutorizationCode,
	@cccm_id, @ccm_BranchCurrencyExchange, @ccm_isPayed,
	@ccm_isCancelled, @cmm_isEditing, @cmm_isEditingCD, @cmm_guid)


set	@return_value = @@identity
GO






-- --------------------------------------------------------------
-- MOS  05-2009
-- Borra los temporales que no se estan usando y no se han
-- actualizado, pasados 2 minutos.-
-- --------------------------------------------------------------

CREATE pROCEDURE [dbo].[spCreditCardMovements_IsEditingPurgeStatus]
AS

BEGIN

	set nocount on


	declare @DeleteTime		as	datetime
	set		@DeleteTime		=	DATEADD(minute, -3, getdate())


	-- cabeceras sin actualizar
	Update dbo.tbCreditCardMovements		WITH(ROWLOCK)
		Set cmm_isEditing = 'False',
			cmm_guid = null
			Where   cmm_isEditing	= 'True'
				and	cmm_isEditingCD < @DeleteTime



END





GO






CREATE PROCEDURE  [dbo].[spCreditCardMovements_updateData]
(
	@guid						as UNIQUEIDENTIFIER			,
	@intCTTransaction			AS INT,
	@intUserID					AS INT,
	@return_value				as int				OUTPUT	,
	@ret_ErrorCode				as int				OUTPUT	,
	@ret_ErrorDescription		as varchar(200)		OUTPUT
)
As

BEGIN

	set nocount on

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''


	-- Obtiene una caja para el usuario actual
	DECLARE @intCompId	AS INT
	DECLARE @intBraId	AS INT
	DECLARE @intCnId	AS INT
	SELECT	@intCompId	= tct.comp_id,
			@intBraId	= tct.bra_id
		FROM tbCommercialTransactions tct	WITH (NOLOCK)
		WHERE tct.ct_transaction = @intCTTransaction

	SELECT TOP 1 @intCnId = tcnbu.cn_id
		FROM tbCashNumber4Branch4User tcnbu			WITH (NOLOCK)
		WHERE	tcnbu.comp_id	= @intCompId	AND
				tcnbu.bra_id	= @intBraId		AND
				tcnbu.[user_id] = @intUserID
		ORDER BY
					CASE
						WHEN tcnbu.re_CreditCardLiqFavorite = 1 THEN	0
						ELSE											1
					END,
					IsNull(tcnbu.re_order,0)

	IF @intCnId IS NULL
		BEGIN
			Set @return_value			= -1
			Set @ret_ErrorCode			= -1
			Set @ret_ErrorDescription	= 'El usuario NO posee cajas asignadas en la sucursal actual.!'
			RETURN
		END


	-- ----------------------------
	-- Saca los cupones de la Caja
	-- ----------------------------
	INSERT INTO tbCashMovements
	(
		comp_id,
		bra_id,
		cm_cd,
		ca_id,
		cm_debit,
		cm_credit,
		curr_id,
		cm_desc,
		cn_id,
		ct_transaction,
		svt_id,
		cm_BranchCurrencyExchange
	)
		SELECT		tct.comp_id,
					tct.bra_id,
					tb.bra_processingDate,
					tb.bra_CollectionCaId_CreditCard,
					0,
					ccm.ccm_Total,
					ccm.curr_id,
					'Liquidacion de Tarjetas de Crédito',
					@intCnId,
					@intCTTransaction,
					5,
					tct.ct_ACurrencyExchange

			FROM tbCreditCardMovements ccm			WITH (NOLOCK)
			INNER JOIN tbCommercialTransactions tct	WITH (NOLOCK)
				ON tct.ct_transaction = @intCTTransaction
			INNER JOIN tbBranch tb					WITH (NOLOCK)
				ON		tb.comp_id	= tct.comp_id
					AND tb.bra_id	= tct.bra_id

			where ccm.cmm_guid		=	@guid
	-- ----------------------------


	INSERT INTO tbCreditCardLiquidationsMovements (	comp_id,
													ct_transaction,
													ccm_id
												  )
		SELECT
				comp_id,
				@intCTTransaction,
				ccm_id
			FROM dbo.tbCreditCardMovements
			WHERE	cmm_guid		=	@guid




	update	dbo.tbCreditCardMovements
		SET		cmm_isEditing	=	'false'	,
				ccm_isPayed		=	'true'	,
				cmm_guid		=	null
		where	cmm_guid		=	@guid

END



GO






-- ----------------------------------------------------------------------
-- Selecciona el cupon para ser liquidado solo si no esta seleccionado
-- o lo des-selecciona solo si esta seleccionado y pertenece al guid
-- que se paso como parametro
-- esto se usa en wfmPurchaseDocs unicamente.-
-- ----------------------------------------------------------------------

CREATE PROCEDURE  [dbo].[spCreditCardMovements_updateDatatoGrid]
(
		@comp_id							int,
		@bra_id								int,
		@ct_transaction						int,
		@ccm_id								int,
		@cmm_guid							UNIQUEIDENTIFIER

)
As
set nocount on


/*declare		@comp_id							int,
		@bra_id								int,
		@ct_transaction						int,
		@ccm_id								int,
		@cmm_guid							UNIQUEIDENTIFIER

		SELECT 		@comp_id							=1,
		@bra_id								=1,
		@ct_transaction						=1376,
		@ccm_id								=18,
		@cmm_guid							='90169d85-587b-4c0b-8f1d-aac7b26bdd36'
*/



Update dbo.tbCreditCardMovements

Set		cmm_guid			=	Case When IsNull(cmm_isEditing,'false') = 'true'
									Then NULL
									Else @cmm_guid
								End,
		cmm_isEditing		=	Case When IsNull(cmm_isEditing,'false') = 'true'
									Then 'false'
									Else 'true'
								End,
		cmm_isEditingCD		=	Getdate()

Where	comp_id				=	@comp_id
And		bra_id				=	@bra_id
And	    ct_transaction		=	@ct_transaction
And		ccm_id				=	@ccm_id
And		(   cmm_guid		IS	null
	     or cmm_guid		=	@cmm_guid)





GO






CREATE PROCEDURE  [dbo].[spCreditCardMovements_updateDatatoGrid_All]
(
		@comp_id			INT ,
		@lang_id			INT ,
		@bra_id				INT ,
		@curr_id			INT ,
		@ba_id				INT ,
		@cmm_guid			UNIQUEIDENTIFIER,
		@ccg_id				INT,
		@ccm_lote			NVARCHAR(50),
		@bra_id4Filter		INT,
		@cardNumber			NVARCHAR(50),
		@datCtDateFrom		DATETIME,
		@datCtDateTo		DATETIME,
		@TotalOption		INT,
		@TotalFrom		    DECIMAL(19,6),
		@TotalTo			DECIMAL(19,6),
		@cct_id				INT	,
		@isselection		BIT


)
As
set nocount on


BEGIN


	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	/*
	declare
				@comp_id			INT ,
				@lang_id			INT ,
				@bra_id				INT ,
				@curr_id			INT ,
				@ba_id				INT ,
				@cmm_guid			UNIQUEIDENTIFIER,
				@ccg_id				INT,
				@ccm_lote			NVARCHAR(50),
				@bra_id4Filter		INT,
				@cardNumber			NVARCHAR(50),
				@datCtDateFrom		DATETIME,
				@datCtDateTo		DATETIME,
				@TotalOption		INT,
				@TotalFrom		    DECIMAL(19,6),
				@TotalTo			DECIMAL(19,6),
				@isselection		BIT

	select
				@comp_id			= 1 ,
				@lang_id			= 2 ,
				@bra_id				= 1 ,
				@curr_id			= 1 ,
				@ba_id				= 31,
				@cmm_guid			= '0aa5d271-6ffa-46c4-a0d0-e33f1856571c',
				@ccg_id				= -1,
				@ccm_lote			= '',
				@bra_id4Filter		= 1,
				@cardNumber			= '',
				@datCtDateFrom		='01/01/1900',
				@datCtDateTo		='04/30/2016',
				@TotalOption		=1,
				@TotalFrom		    =1000,
				@TotalTo			=0,
				@isselection		='True'

		*/

	----------------------------------------------------------------------------------------------------------------------------------------------------------------


	DECLARE @tbltmpCreditCardMovementsByFilters TABLE (comp_id int,bra_id int,ct_transaction int,ccm_id int)
		INSERT INTO @tbltmpCreditCardMovementsByFilters

	select
		ccm.comp_id, ccm.bra_id, ccm.ct_transaction, ccm.ccm_id


		from	dbo.tbCreditCardMovements					ccm

		LEFT JOIN tbCreditCardLoanPlan tcclp
			ON	tcclp.comp_id	= ccm.comp_id		AND
				tcclp.cc_id		= ccm.cc_id			AND
				tcclp.ccp_id	= ccm.ccp_id

		inner join dbo.tbCommercialTransactions		ct
		ON  ct.comp_id			= ccm.comp_id
		AND ct.bra_id			= ccm.bra_id
		AND ct.ct_transaction	= ccm.ct_transaction

		INNER JOIN dbo.tbBankingAccounts			ba
		ON ba.comp_id			= ccm.comp_id
		AND ba.curr_id			= ccm.curr_id

		INNER JOIN tbsysCurrency					tc
		ON ba.curr_id			= tc.curr_id

		INNER JOIN tbCreditCard tcc
			ON		tcc.comp_id = ccm.comp_id
				AND tcc.cc_id	= ccm.cc_id
				AND tcc.cc_NoLiquidationPending = 'False'

		LEFT JOIN tbBranch tb
			ON		tb.comp_id	= ccm.comp_id
				AND tb.bra_id	= ccm.bra_id

		where   ccm.comp_id				= @comp_id
		--AND     ccm.bra_id				= @bra_id
		AND		ccm.curr_id				= @curr_id
		AND		ba.ba_id				= @ba_id
		AND		(@cct_id = -1 OR ccm.cct_id = @cct_id)
		AND		(ccm.ccm_isPayed		= 'False'	OR		ccm.ccm_ispayed		IS NULL)
		AND		(ccm.cmm_isEditing		= 'False'	OR		ccm.cmm_isEditing	IS NULL		OR
				(ccm.cmm_isEditing		= 'True'	AND		ccm.cmm_guid		= @cmm_guid))
		and		(@ccg_id				= -1		or		tcc.ccg_id			= @ccg_id)
		and		(@ccm_lote				= ''		or		ccm.ccm_lote		like '%'+ @ccm_lote +'%')
		AND		(@cardNumber = ''					OR		ccm.ccm_cardNumber	LIKE '%' + @cardNumber + '%')
		AND 	(
					(@TotalOption = -1)														or
					(@TotalOption = 0 and ccm.ccm_Total = @TotalFrom)						or
					(@TotalOption = 1 and ccm.ccm_Total > @TotalFrom)						or
					(@TotalOption = 2 and ccm.ccm_Total < @TotalFrom)						or
					(@TotalOption = 3 and ccm.ccm_Total between @TotalFrom and @TotalTo)
				)
		AND		ct.ct_date							BETWEEN @datCtDateFrom AND @datCtDateTo
		AND		(@bra_id4Filter = -1				OR		ccm.bra_id			= @bra_id4Filter)




	--SELECT * FROM @tbltmpCreditCardMovementsByFilters

	Update dbo.tbCreditCardMovements

		Set		cmm_guid			=	Case when @isselection = 'false'
													Then NULL
													Else @cmm_guid
											End,
				cmm_isEditing		=	@isselection,
				cmm_isEditingCD		=	Getdate()

	from tbCreditCardMovements ccm

	INNER JOIN @tbltmpCreditCardMovementsByFilters				tempcc
	ON	tempcc.comp_id			= ccm.comp_id AND
		tempcc.bra_id			= ccm.bra_id AND
		tempcc.ct_transaction	= ccm.ct_transaction AND
		tempcc.ccm_id			= ccm.ccm_id

	Where	ccm.comp_id				=	@comp_id
	And		(   cmm_guid		IS	null
			or cmm_guid		=	@cmm_guid)




END
GO





