------------------------------------------------------------------------------------------------------
--Date   : 28/08/15
--Author :	GA
--Desc   :  validamos que no haya ingresado el codigo de aut
------------------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spCreditCardMovementsTmp_getData_ValidateData]
(

		@comp_id					INT,
		@bra_id						INT,
		@ccmt_guid					UNIQUEIDENTIFIER,
		@cc_id						INT,
		@ccmt_AutorizationCode		NVARCHAR(50),
		@bitIsInsert				BIT


)
AS

BEGIN

	SET NOCOUNT ON

	-- --------------------------------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------------------------------
	/*
		DECLARE			@comp_id					INT,
						@bra_id						INT,
						@ccmt_guid					UNIQUEIDENTIFIER,
						@cc_id						INT,
						@ccmt_AutorizationCode		NVARCHAR(50)

		SELECT			@comp_id					= 1,
						@bra_id						= 1,
						@ccmt_guid					= '19E16F3B-0890-4CB8-9DE2-BEAA1BE5E32F',
						@cc_id						= 14,
						@ccmt_AutorizationCode		= '123'
	*/
	-- --------------------------------------------------------------------------------------------------


	-- 0 : Ya esta ese codigo de aut
	-- 1 : Puede Agregar el codigo de aut


	DECLARE @lavailable AS INT

	SET		@lavailable = 1


	-- --------------------------------------------------------
	-- Verificacion de carga
	-- --------------------------------------------------------
	IF (SELECT tcc.cc_mustVerifyAuthorizationCode
			FROM tbCreditCard tcc
			WHERE	tcc.comp_id = @comp_id AND
					tcc.cc_id	= @cc_id
	) = 'False'
		BEGIN
			SELECT @lavailable [Available]
			RETURN
		END
	ELSE	-- Si debe verificar y no lo cargaron, da error.
		BEGIN
			IF @ccmt_AutorizationCode = ''
				BEGIN
					SELECT 0 [Available]
					RETURN
				END
		END
	-- --------------------------------------------------------


	IF EXISTS ( SELECT top 1 tccmt.ccmt_AutorizationCode
					FROM tbCreditCardMovementsTmp					tccmt
					Where	tccmt.ccmt_guid				= @ccmt_guid				AND
							tccmt.cc_id					= @cc_id					AND
							tccmt.ccmt_AutorizationCode = @ccmt_AutorizationCode
			  )


		BEGIN
			IF (
				SELECT COUNT(*)
					FROM tbCreditCardMovementsTmp					tccmt
					Where	tccmt.ccmt_guid				= @ccmt_guid				AND
							tccmt.cc_id					= @cc_id					AND
							tccmt.ccmt_AutorizationCode = @ccmt_AutorizationCode
				) > CASE
						WHEN @bitIsInsert = 'True' THEN 0
						ELSE							1
					END
				BEGIN
					SET		@lavailable = 0
				END

		END

	ELSE
		BEGIN

			IF EXISTS ( SELECT top 1 tccm.ccm_AutorizationCode
							FROM tbCreditCardMovements tccm
							Where	tccm.comp_id				= @comp_id		AND
									tccm.cc_id					= @cc_id		AND
									tccm.ccm_AutorizationCode	= @ccmt_AutorizationCode
						)


				BEGIN
						SET		@lavailable = 0

				END
			ELSE
				BEGIN
					SET		@lavailable = 1
				END

		END

	-- 0 : Ya esta ese codigo de aut
	-- 1 : Puede Agregar el codigo de aut


	SELECT @lavailable [Available]



END











GO






CREATE PROCEDURE [dbo].[spCreditCardMovementsTmp_getDataById]
(
		@ccmt_id		int
)
AS

BEGIN



	set nocount on

	select	' ' [ ], ' ' [ ],
			ccmt.bra_id,
			ccmt.ccmt_guid,
			ccmt.cc_id,
			cc.cc_desc,
			ccmt.ccmt_Total,
			ISNULL(ccmt.ccmt_cardNumber,'')					[ccmt_cardNumber],
			ISNULL(ccmt.ccmt_cardEmissionDate,GETDATE())	[ccmt_cardEmissionDate],
			ISNULL(ccmt.ccmt_cardExpirationDate,GETDATE())	[ccmt_cardExpirationDate],
			ISNULL(ccmt.ccmt_customerDocumentNumber,'')		[ccmt_customerDocumentNumber],
			ISNULL(ccmt.ccmt_customerName,'')				[ccmt_customerName],
			ISNULL(ccmt.ccmt_receiptNumber,'')				[ccmt_receiptNumber],
			ISNULL(ccmt.ccmt_AutorizationCode,'')			[ccmt_AutorizationCode],
			ISNULL(ccmt.cccm_id,-1)							[cccm_id],
			ISNULL(cccm.cccm_desc,'')						[cccm_desc],
			ISNULL(ccmt.ccmt_lote,'')						[ccmt_lote],
			ccmt.ccp_id,
			ISNULL(ccmt.ccmt_id,-1)							[ccmt_id],
			isnull(ccmt.cct_id,-1)							[cct_id],
			isnull(ccmt.ccv_id,-1)							[ccv_id]

	from	dbo.tbCreditCardMovementsTmp				ccmt			WITH (NOLOCK)

			left join dbo.tbCreditCard					cc				WITH (NOLOCK)
			on cc.comp_id		= ccmt.comp_id
			and cc.cc_id		= ccmt.cc_id

			left join dbo.tbsysCreditCardCuponMetod		cccm			WITH (NOLOCK)
			on cccm.cccm_id		= ccmt.cccm_id

	where	ccmt.ccmt_id		=	@ccmt_id




END













GO


CREATE PROCEDURE [dbo].[spCreditCardMovementsTMP_HasCreditCardsWithoutNumber]
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@page_id	INT,
	@ctrl_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@page_id	INT,
				@ctrl_id	INT,
				@guid		UNIQUEIDENTIFIER

			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@prof_id	= 1,
				@page_id	= 52,
				@ctrl_id	= 5459,
				@guid		= 'EE6FD1FE-015A-4761-BD17-7CB33EA730E9'
		*/
		-- -----------------------------------------------------

		--SI TIENE AL MENOS UN REGISTRO AL QUE LE FALTE EL NUMERO DE TARJETA DE CREDITO
		--NO PODEMOS PERMITIR QUE GRABE LA COBRANZA
		IF EXISTS(SELECT 1
					FROM tbControlProfiles	tcp1			WITH(NOLOCK)
					  WHERE	tcp1.comp_id	= @comp_id AND
							tcp1.bra_id		= @bra_id AND
							tcp1.prof_id	= @prof_id AND
							tcp1.ctrl_id	= @ctrl_id)
			BEGIN
				SELECT 0
			END
		ELSE
			BEGIN
				SELECT
					COUNT(*)
					FROM tbCreditCardMovementsTmp				tccmt	WITH(NOLOCK)
					WHERE	tccmt.comp_id			= @comp_id	AND
							tccmt.bra_id			= @bra_id	AND
							tccmt.ccmt_guid			= @guid		AND
							(tccmt.ccmt_cardNumber	IS NULL OR tccmt.ccmt_cardNumber = '')
			END
		END




GO







CREATE  PROCEDURE [dbo].[spCreditCardMovementsTmp_insertData]
(

		@comp_id						int,
		@bra_id							int,
		@ccmt_guid						uniqueidentifier,
		@cc_id							int,
		@ccmt_Total						decimal(19,6),
		@ccmt_cardNumber				varchar(50),
		@ccmt_cardEmissionDate			datetime,
		@ccmt_cardExpirationDate		datetime,
		@ccmt_customerDocumentNumber	varchar(20),
		@ccmt_customerName				varchar(100),
		@ccmt_receiptNumber				varchar(50),
		@ccmt_AutorizationCode			varchar(50),
		@cccm_id						int,
		@ccp_id							INT,
		@cct_id							INT,
		@return_value					int output

)
AS

BEGIN

	set nocount on

	SET @ccmt_AutorizationCode = dbo.fnStrAllTrim(@ccmt_AutorizationCode)

	IF @ccp_id = -1
	BEGIN
		SET @ccp_id = NULL
	END

	IF @cct_id = -1
	BEGIN
		SET @cct_id = NULL
	END

	insert into dbo.tbCreditCardMovementsTmp
	(comp_id, bra_id, ccmt_guid, cc_id, ccmt_Total, ccmt_cardNumber, ccmt_cardEmissionDate,
	ccmt_cardExpirationDate, ccmt_customerDocumentNumber, ccmt_customerName, ccmt_receiptNumber,
	ccmt_AutorizationCode, cccm_id,ccp_id,cct_id)

	values
	(@comp_id, @bra_id, @ccmt_guid, @cc_id,@ccmt_Total, @ccmt_cardNumber, @ccmt_cardEmissionDate,
	@ccmt_cardExpirationDate, @ccmt_customerDocumentNumber, @ccmt_customerName, @ccmt_receiptNumber,
	@ccmt_AutorizationCode, @cccm_id,@ccp_id,@cct_id)


	set	@return_value = @@identity


END

GO



-- Log
-- MOS 06-2024: mlo_OrdersWithDiscountCouponIncludeInPriceV2,  por el arreglo de que las ordenes si esta ese campo en true se carguen con el precio CON EL DESCUENTO INCLUIDO, debo RESTAR el descuento asi me da el total de la orden.
-- MOS 07-2024:999 x MCCars sino con el IF de la linea anterior si tiene envio PAGO por el cliente que HAY que facturar, salia en NEGATIVO y NO daba el total de plata para cobrar.



CREATE PROCEDURE [dbo].[spCreditCardMovementsTMP_InsertDataFromSaleOrderCreditCardsByCT_TRANSACTION]
(
	@comp_id		INT,
	@ct_transaction	INT,
	@guid			UNIQUEIDENTIFIER
)
AS
BEGIN

	SET NOCOUNT ON


	-- ----------------------------------------------------------------------
	-- Test
	-- ----------------------------------------------------------------------
	/*
	declare
			@comp_id		INT = 1,
			@ct_transaction	INT = 333,
			@guid			UNIQUEIDENTIFIER = ''
	*/
	-- ----------------------------------------------------------------------






	-- ----------------------------------------------------------------------
	-- Precarga valores de Plan de Pagos  MOS  05-10-2019
	-- ----------------------------------------------------------------------
	DECLARE @decTOTALPending AS DECIMAL(30,4)
	DECLARE @bra_id_original AS INT
	DECLARE @curr_id		 AS INT
	DECLARE @user_id		 AS INT
	DECLARE @cn_id			 AS INT
	DECLARE @ca_id			 AS INT
	SELECT	@decTOTALPending		= dbo.fnGetExchange2 (tct.comp_id ,tct.ct_ABalance,tct.ct_ACurrency,tb.curr_id,0,0,0,'False'),
			@bra_id_original		= tct.bra_id,
			@curr_id				= tb.curr_id,
			@user_id				= tct.[user_id],
			@ca_id					= tb.bra_CollectionCaId_Money
		FROM tbCommercialTransactions	tct	WITH (NOLOCK)
		INNER JOIN tbBranch				tb	WITH (NOLOCK)
			ON	tb.comp_id			= tct.comp_id AND
				tb.bra_id			= tct.bra_id
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @ct_transaction

	SELECT	 @cn_id = tcnbu.cn_id
		FROM tbCashNumber4Branch4User tcnbu		WITH (NOLOCK)
		WHERE	tcnbu.comp_id	= @comp_id			AND
				tcnbu.bra_id	= @bra_id_original	AND
				tcnbu.[user_id] = @user_id
		ORDER BY tcnbu.re_order


	INSERT INTO tbCreditCardMovementsTmp
	(
		comp_id,
		bra_id,
		-- ccmt_id -- this column value is auto-generated,
		ccmt_guid,
		cc_id,
		ccmt_Total,
		ccp_id,ccmt_cardNumber,
		ccmt_cardEmissionDate,
		ccmt_cardExpirationDate,
		ccmt_customerDocumentNumber,
		ccmt_customerName,
		ccmt_AutorizationCode,
		ccmt_receiptNumber,
		ccmt_lote

	)
	SELECT
		tsocc.comp_id,
		tsocc.bra_id,
		@guid,
		tsocc.cc_id,
		tsocc.sohp_total,
		tsocc.ccp_id,
		tsocc.ccm_cardNumber,
		tsocc.ccm_cardEmissionDate,
		tsocc.ccm_cardExpirationDate,
		tsocc.ccm_customerDocumentNumber,
		tsocc.ccm_customerName,
		dbo.fnStrAllTrim (tsocc.ccm_AutorizationCode),
		tsocc.ccm_receiptNumber,
		tsocc.cmm_lote
		FROM tbSaleOrderCreditCards						tsocc		WITH (NOLOCK)
		INNER JOIN tbCreditCard							tcc			WITH (NOLOCK)
			ON	tcc.comp_id				= tsocc.comp_id AND
				tcc.cc_id				= tsocc.cc_id
		WHERE	tsocc.comp_id			= @comp_id			AND
				tsocc.ct_transaction	= @ct_transaction	AND
				tsocc.sohp_position		< 6  /*<> 7  MOS 09-2020*/				AND
				tcc.curr_id				= @curr_id					-- SOLO si son t.cred en la moneda de sa sucursal.


	-- Pago de RESTO con Tarjeta de Crédito
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbSaleOrderCreditCards tsocc		WITH (NOLOCK)
					WHERE	tsocc.comp_id			= @comp_id			AND
							tsocc.ct_transaction	= @ct_transaction	AND
							tsocc.sohp_position		= 6		-- Resto en Tarjeta de Credito
				)
		BEGIN
			SELECT @decTOTALPending = @decTOTALPending - tsocc.sohp_total
				FROM tbSaleOrderCreditCards tsocc		WITH (NOLOCK)
				WHERE	tsocc.comp_id			= @comp_id			AND
						tsocc.ct_transaction	= @ct_transaction	AND
						tsocc.sohp_position		< 6
			IF @decTOTALPending > 0
				BEGIN
					UPDATE tbCreditCardMovementsTmp		WITH (ROWLOCK)
						SET		ccmt_Total				= @decTOTALPending
						WHERE	comp_id		= @comp_id	AND
								ccmt_guid	= @guid		AND
								ccmt_Total	= 0
				END
		END

	-- Pago de RESTO con Efectivo
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbSaleOrderCreditCards tsocc		WITH (NOLOCK)
					WHERE	tsocc.comp_id			= @comp_id			AND
							tsocc.ct_transaction	= @ct_transaction	AND
							tsocc.sohp_position		= 7		-- Resto en EFECTIVO
				)
		BEGIN
			SELECT @decTOTALPending = @decTOTALPending - tsocc.sohp_total
				FROM tbSaleOrderCreditCards tsocc		WITH (NOLOCK)
				WHERE	tsocc.comp_id			= @comp_id			AND
						tsocc.ct_transaction	= @ct_transaction	AND
						tsocc.sohp_position		< 6
			IF @decTOTALPending > 0
				BEGIN
					INSERT INTO tbCashMovementsTmp
					(
						comp_id,
						bra_id,
						cmt_guid,
						-- cmt_id -- this column value is auto-generated
						ca_id,
						cmt_amount,
						curr_id,
						cmt_desc,
						cn_id,
						cmt_branchCurrencyExchange
					)
					VALUES
					(
						@comp_id,
						@bra_id_original,
						@guid,
						@ca_id,
						@decTOTALPending,
						@curr_id,
						'CD',
						@cn_id ,
						1
					)

				END
		END



	-- Recibo a Cuenta
	DECLARE @decTotal_Rc		AS DECIMAL(19,8) = 0
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbSaleOrderCreditCards tsocc		WITH (NOLOCK)
					WHERE	tsocc.comp_id			= @comp_id			AND
							tsocc.ct_transaction	= @ct_transaction	AND
							tsocc.sohp_position		= 9		-- Recibo a Cuenta
				)
		BEGIN

			DECLARE @ct_transaction_Rc	AS INT
			DECLARE @bra_id_rc			AS INT
			SELECT	@decTotal_Rc		= tsocc.sohp_total,
					@curr_id			= tct.curr_id_transaction,
					@ct_transaction_Rc	= tsocc.ct_transaction_Rc,
					@bra_id_rc			= tct.bra_id
				FROM tbSaleOrderCreditCards tsocc				WITH (NOLOCK)
				INNER JOIN tbCommercialTransactions AS tct		WITH (NOLOCK)		-- del Recibo !
					ON	tct.comp_id				= tsocc.comp_id AND
						tct.ct_transaction		= tsocc.ct_transaction_Rc
				WHERE	tsocc.comp_id			= @comp_id			AND
						tsocc.ct_transaction	= @ct_transaction	AND
						tsocc.sohp_position		= 9
			IF @decTotal_Rc > 0
				BEGIN
					EXEC spCommercialTransactionsTmp_insertData
						@comp_id,
						@bra_id_rc ,
						@guid ,
						@ct_transaction_Rc ,
						@decTotal_Rc ,
						"a",
						1,
						null
					END
		END
		-- ----------------------------------------------------------------------




	-- Pago en Efectivo de Plan de Descuentos
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbSaleOrderCreditCards tsocc		WITH (NOLOCK)
					WHERE	tsocc.comp_id			= @comp_id			AND
							tsocc.ct_transaction	= @ct_transaction	AND
							tsocc.sohp_position		= 8		-- Resto en EFECTIVO
				)
		BEGIN

			DECLARE @decTotal	AS DECIMAL(19,8) = 0

			SELECT	@decTotal = tsocc.sohp_total,
					@curr_id  = tct.curr_id_transaction
				FROM tbSaleOrderCreditCards tsocc				WITH (NOLOCK)
				INNER JOIN tbCommercialTransactions AS tct		WITH (NOLOCK)
					ON	tct.comp_id				= tsocc.comp_id AND
						tct.ct_transaction		= tsocc.ct_transaction
				WHERE	tsocc.comp_id			= @comp_id			AND
						tsocc.ct_transaction	= @ct_transaction	AND
						tsocc.sohp_position		= 8

			-- NOOO  SET @decTotal = @decTotal - @decTotal_Rc  -- Le resto lo que tenga A Cuenta aplicado mas arriba

			IF @decTOTALPending > 0
				BEGIN
					INSERT INTO tbCashMovementsTmp
					(
						comp_id,
						bra_id,
						cmt_guid,
						ca_id,
						cmt_amount,
						curr_id,
						cmt_desc,
						cn_id,
						cmt_branchCurrencyExchange
					)
					VALUES
					(
						@comp_id,
						@bra_id_original,
						@guid,
						@ca_id,
						@decTotal,
						@curr_id,
						'CD',
						@cn_id ,
						1
					)

				END
		END
		-- ----------------------------------------------------------------------






	-- ----------------------------------------------------------------------
	-- Si viene de MercadoLibre
	-- ----------------------------------------------------------------------
	DECLARE @MLPaymentsID AS NVARCHAR(50)
	DECLARE @st_id		AS INT
	DECLARE @bra_id		AS INT
	DECLARE @cc_id		AS INT
	DECLARE @mlo_id		AS INT
	DECLARE @mlo_idCT	AS INT	= NULL
	SELECT	@mlo_id		= MAX(ISNULL( tit.mlo_id,0)),
			@mlo_idCT	= tct.mlo_id
		FROM tbItemTransactions				tit		WITH (NOLOCK)
		INNER JOIN tbCommercialTransactions tct		WITH (NOLOCK)
			ON	tct.comp_id			= tit.comp_id	AND
				--tct.bra_id = tit.bra_id		AND
				tct.ct_transaction	= tit.ct_transaction
		WHERE	tit.comp_id			= @comp_id			AND
				tit.ct_transaction	= @ct_transaction
		GROUP BY tct.mlo_id

	IF (@mlo_id IS NULL OR @mlo_id <= 0)	AND
		@mlo_idCT IS NOT NULL				AND
		@mlo_idCT > 0
		BEGIN
			SET @mlo_id = @mlo_idCT
		END

	IF @mlo_id > 0
		BEGIN


			-- ----------------------------------------------------------------------------
			-- Pongo en una Tabla Temporal TODAS las Ordenes que pertenecen a este pedido
			-- ----------------------------------------------------------------------------
			DECLARE		@MLShippingID BIGINT
			SELECT		@MLShippingID = WWW.MLshippingID
				FROM	tbMercadoLibre_ordersShipping WWW			WITH (NOLOCK)
				WHERE	comp_id = @comp_id AND
						mlo_id	= @mlo_id

			DECLARE		@tmpOrdersOfThisShippment TABLE(mlo_id INT PRIMARY KEY)
			INSERT INTO @tmpOrdersOfThisShippment(mlo_id)
				SELECT DISTINCT  TMLOS.mlo_id
					FROM tbMercadoLibre_ordersShipping tmlos		WITH (NOLOCK)
					WHERE	--tmlos.comp_id		= @comp_id  AND -- MOS 07-2021 x velocidad
							tmlos.MLshippingID	= @MLShippingID
			IF @@ROWCOUNT = 0
				BEGIN
					INSERT INTO @tmpOrdersOfThisShippment(mlo_id) VALUES (@mlo_id)
				END
			-- ----------------------------------------------------------------------------


			DECLARE @decShipmentPayedByCustomer AS DECIMAL(19,4) = 0
			DECLARE @cc_id4UserPayDelivery AS INT	= NULL
			SELECT  @cc_id4UserPayDelivery			= tmls.cc_id4UserPayDelivery
				FROM tbMercadoLibre_ordersDetail tmlod				WITH (NOLOCK)
				INNER JOIN @tmpOrdersOfThisShippment tmp
					ON tmp.mlo_id = tmlod.mlo_id
				INNER JOIN tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
					ON	tmlip.comp_id	= tmlod.comp_id		AND
						tmlip.mlp_id	= tmlod.mlp_id
				INNER JOIN tbMercadoLibre_Stores tmls				WITH (NOLOCK)
					ON	tmls.comp_id	= tmlip.comp_id AND
						tmls.mls_id		= tmlip.mls_id
				WHERE	tmlod.comp_id   = @comp_id      AND
						tmls.item_id4UserPayDelivery IS NOT NULL
			IF	@cc_id4UserPayDelivery IS NOT NULL
				BEGIN
					SELECT @decShipmentPayedByCustomer = tmlos.MLShippmentCost4Buyer
						FROM tbMercadoLibre_ordersShipping tmlos	WITH (NOLOCK)
						WHERE	tmlos.comp_id	= @comp_id AND
								tmlos.mlo_id	= @mlo_id
				END









			SELECT		@st_id	= tct.st_id,
						@bra_id	= tct.bra_id
				FROM	tbCommercialTransactions tct	WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id AND
						tct.ct_transaction	= @ct_transaction

			SELECT		@cc_id		=  tst.cc_id
				FROM	tbSalesTerms tst		WITH (NOLOCK)
				WHERE	tst.comp_id = @comp_id AND
						tst.st_id	= @st_id



			-- ***654654**KJNKJN   Ver aca tambien este calculo !!!!
			DECLARE @decPrice AS DECIMAL(19,4)
			SET		@decPrice	= 0

			SELECT @decPrice	= SUM(ISNULL(tmlod.mlo_unit_price,0) * ISNULL(tmlod.mlo_quantity,0))
				FROM tbMercadoLibre_ordersDetail tmlod		WITH (NOLOCK)
				INNER JOIN @tmpOrdersOfThisShippment tmp
					ON tmp.mlo_id = tmlod.mlo_id
				WHERE	tmlod.comp_id = @comp_id --AND
						--tmlod.mlo_id = @mlo_id


			-- Veo si hay alguna orden YA COBRADA
			DECLARE @mlo_isCollected AS BIT = 'False'
			SELECT	@mlo_isCollected		= ISNULL(tmloh.mlo_isCollected,'False')
				FROM tbMercadoLibre_ordersHeader tmloh	WITH (NOLOCK)
				INNER JOIN @tmpOrdersOfThisShippment tmp
					ON tmp.mlo_id = tmloh.mlo_id
				WHERE	tmloh.comp_id	= @comp_id AND
						tmloh.mlo_isCollected = 'True'
						--tmloh.mlo_id	= @mlo_id


			DECLARE @decPayments AS DECIMAL(19,4)		= 0
			DECLARE @decShippingCost AS DECIMAL(19,4)	= 0	-- MOS 07-2024


			-- MOS 07-2022: el nabo que hizo la clase le puso el total_paid_ammount en los dos campos por lo que no debo usar el transaction ammount y debo cambiarlo por el paid para que quede funcionando como estaba antes.
			-- SELECT	@decPayments				= SUM(tmlop.MLtransaction_amount - tmlop.MLshipping_cost)
			SELECT		@decPayments				= SUM(tmlop.MLtotal_paid_amount - tmlop.MLshipping_cost),
						@decShippingCost			= SUM(tmlop.MLshipping_cost)
				FROM tbMercadoLibre_ordersPayments tmlop WITH (NOLOCK)
				INNER JOIN @tmpOrdersOfThisShippment tmp
					ON tmp.mlo_id = tmlop.mlo_id
				WHERE	tmlop.comp_id			= @comp_id				AND
						--tmlop.mlo_id			= @mlo_id				AND
						tmlop.MLoperation_type	= 'regular_payment'		AND
						tmlop.MLstatus			= 'approved'			AND
						tmlop.MLstatus_detail   = 'accredited'			AND
						tmlop.MLpaymentsID		> 0

			DECLARE @decAdditionalPayments AS DECIMAL(19,4)
			SET		@decAdditionalPayments = 0



			-- MOS 07-2022: el nabo que hizo la clase le puso el total_paid_ammount en los dos campos por lo que no debo usar el transaction ammount y debo cambiarlo por el paid para que quede funcionando como estaba antes.
			-- SELECT	@decAdditionalPayments		= SUM(tmlop.MLtransaction_amount)
			SELECT		@decAdditionalPayments		= ISNULL(SUM(tmlop.MLtotal_paid_amount),0)
				FROM tbMercadoLibre_ordersPayments tmlop WITH (NOLOCK)
				INNER JOIN @tmpOrdersOfThisShippment tmp
					ON tmp.mlo_id = tmlop.mlo_id
				WHERE	tmlop.comp_id			= @comp_id				AND
						--tmlop.mlo_id			= @mlo_id				AND
						tmlop.MLoperation_type	= 'payment_addition'	AND
						tmlop.MLstatus			= 'approved'
			-- ***654654**KJNKJN   Ver aca tambien este calculo !!!!


		-- -----------------------------------------------------------------------------------------
		-- Se ejecuta una u otra, OJO!!!!!
		-- -----------------------------------------------------------------------------------------
			-- MOS 07-2022: SELECT * FROM tbMercadoLibre_ordersPayments AS tmlop WHERE tmlop.mlo_id = 4882774 de FAS, no se que mierda es pero hay q poner el importe total como PAGO Adicional
			SELECT		@decAdditionalPayments	= @decAdditionalPayments + ISNULL(SUM(tmlop.MLtransaction_amount - tmlop.MLtotal_paid_amount),0)
				FROM tbMercadoLibre_ordersPayments		  tmlop			WITH (NOLOCK)
				INNER JOIN tbMercadoLibre_ordersHeader AS tmloh			WITH (NOLOCK)
					ON	tmloh.comp_id			= tmlop.comp_id AND
						tmloh.mlo_id			= tmlop.mlo_id
				INNER JOIN tbMercadoLibre_Stores AS		  tmls			WITH (NOLOCK)
					ON	tmls.comp_id			= tmloh.comp_id AND
						tmls.mls_id				= tmloh.mls_id
				INNER JOIN @tmpOrdersOfThisShippment tmp
					ON tmp.mlo_id = tmlop.mlo_id
				WHERE	tmlop.comp_id			= @comp_id									AND
						tmls.mls_OrdersWithDiscountCouponIncludeInPrice		= 'False'		AND -- MOS 03-2023 x ADMA **wqlkn142231lklnk
						tmloh.mlo_OrdersWithDiscountCouponIncludeInPriceV2	= 'False'		AND -- MOS 06-2024: Para que ande SOLO si es al NUEVA orden con items con descuentos de cupones YA aplicados.
						tmlop.MLoperation_type	= 'regular_payment'							AND
						tmlop.MLstatus			= 'approved'								AND
						tmlop.MLstatus_detail   = 'accredited'								AND
						tmlop.MLcoupon_amount   = 0											AND
						ABS(tmlop.MLtransaction_amount - tmlop.MLtotal_paid_amount) > 10	AND	-- 10 es arbitrario, es para saber si hay algo significativo de diferencia...
						tmlop.MLinstallment_amount	= 0										AND	-- MOS 06-2024: HDC Puse q MLinstallment_amount =  cero sino como puse el ISNULL mas ARRIBA si tenia INTERESES x pagar en CUOTAS calculaba esto y daba cualquier cosa.
						tmlop.MLshipping_cost		= 0											-- MOS 07-2024:999 x MCCars sino con el IF de la linea anterior si tiene envio PAGO por el cliente que HAY que facturar, salia en NEGATIVO y NO daba el total de plata para cobrar.

			-- MOS 06-2024: mlo_OrdersWithDiscountCouponIncludeInPriceV2,  por el arreglo de que las ordenes si esta ese campo en true se carguen con el precio CON EL DESCUENTO INCLUIDO, debo RESTAR el descuento asi me da el total de la orden.
			-- La de arriba fue una MALA DESICION por info mala dada x los forros de adma.  para no romper nada lo ponemos ahora así.
			SELECT		@decAdditionalPayments	= @decAdditionalPayments - ISNULL(SUM(tmlop.MLtransaction_amount - tmlop.MLtotal_paid_amount),0)
				FROM tbMercadoLibre_ordersPayments		  tmlop			WITH (NOLOCK)
				INNER JOIN tbMercadoLibre_ordersHeader AS tmloh			WITH (NOLOCK)
					ON	tmloh.comp_id			= tmlop.comp_id AND
						tmloh.mlo_id			= tmlop.mlo_id
				INNER JOIN tbMercadoLibre_Stores AS		  tmls			WITH (NOLOCK)
					ON	tmls.comp_id			= tmloh.comp_id AND
						tmls.mls_id				= tmloh.mls_id
				INNER JOIN @tmpOrdersOfThisShippment tmp
					ON tmp.mlo_id = tmlop.mlo_id
				WHERE	tmlop.comp_id			= @comp_id							AND
						tmloh.mlo_OrdersWithDiscountCouponIncludeInPriceV2 = 'True'	AND -- MOS 06-2024: Para que ande SOLO si es al NUEVA orden con items con descuentos de cupones YA aplicados.
						tmlop.MLoperation_type	= 'regular_payment'					AND
						tmlop.MLstatus			= 'approved'						AND
						tmlop.MLstatus_detail   = 'accredited'						AND
						tmlop.MLcoupon_amount   <> 0					-- NOTA: si falla esto se deberia poner arriba este campo y no la resta !
						--ABS(tmlop.MLtransaction_amount - tmlop.MLtotal_paid_amount) > 10  -- 10 es arbitrario, es para saber si hay algo significativo de diferencia...
		-- -----------------------------------------------------------------------------------------





			SELECT	TOP 1 @MLPaymentsID			= convert(nvarchar(50),tmlop.MLpaymentsID)
				FROM tbMercadoLibre_ordersPayments tmlop WITH (NOLOCK)
				INNER JOIN @tmpOrdersOfThisShippment tmp
					ON tmp.mlo_id = tmlop.mlo_id
				WHERE	tmlop.comp_id			= @comp_id				AND
						--tmlop.mlo_id			= @mlo_id				AND
						tmlop.MLoperation_type	= 'regular_payment'		AND
						tmlop.MLstatus			= 'approved'			AND
						tmlop.MLpaymentsID		> 0


			IF @MLPaymentsID IS NULL OR @MLPaymentsID = ''
				BEGIN
					SET @MLPaymentsID = 'Error, Ingresar Manualmente'
				END



			-- Para evitar Chorreos solo la carga si la orden NO esta cobrada y
			-- NO existe esa orden en temporal actual de mi guid ni
			--  tampoco existe como movimiento de tarjetas de credito ya cobradas
			IF @mlo_isCollected = 'False'	AND
				NOT EXISTS (
							SELECT TOP 1  1
								FROM tbCreditCardMovementsTmp	WITH (NOLOCK)
								WHERE	comp_id		= @comp_id	AND
										mlo_id		= @mlo_id	AND
										ccmt_guid	= @guid
							)
											AND
				NOT EXISTS (
							SELECT TOP 1  1
								FROM tbCreditCardMovements		WITH (NOLOCK)
								WHERE	comp_id = @comp_id AND
										mlo_id	= @mlo_id
							)
				BEGIN

					INSERT INTO tbCreditCardMovementsTmp
					(
						comp_id,
						bra_id,
						-- ccmt_id -- this column value is auto-generated,
						ccmt_guid,
						cc_id,
						ccmt_Total,
						ccp_id,
						ccmt_customerName,
						ccmt_AutorizationCode,
						ccmt_receiptNumber,
						ccmt_lote,
						ccmt_cardNumber,
						ccmt_cardEmissionDate,
						ccmt_cardExpirationDate,
						ccmt_customerDocumentNumber,
						cccm_id,
						mlo_id

					)
					SELECT
						@comp_id,
						@bra_id,
						@guid,
						@cc_id,
						ISNULL(/*@decPayments*/@decPrice,0) + ISNULL(@decAdditionalPayments,0),
						NULL,
						'MercadoPago',
						@MLPaymentsID,
						@MLPaymentsID,
						@MLPaymentsID,
						'MercadoPago',
						GETDATE(),
						GETDATE(),
						'*' ,
						2,
						@mlo_id


					-- Si se le facturó Gastos de Envio pagados por el Comprador a Mercadolibre, los Recupera e ingresa como Valores
					IF ISNULL(@decShipmentPayedByCustomer,0) > 0
						BEGIN

							INSERT INTO tbCreditCardMovementsTmp
							(
								comp_id,
								bra_id,
								-- ccmt_id -- this column value is auto-generated,
								ccmt_guid,
								cc_id,
								ccmt_Total,
								ccp_id,
								ccmt_customerName,
								ccmt_AutorizationCode,
								ccmt_receiptNumber,
								ccmt_lote,
								ccmt_cardNumber,
								ccmt_cardEmissionDate,
								ccmt_cardExpirationDate,
								ccmt_customerDocumentNumber,
								cccm_id,
								mlo_id

							)
							SELECT
								@comp_id,
								@bra_id,
								@guid,
								@cc_id4UserPayDelivery,
								ISNULL(@decShipmentPayedByCustomer,0),
								NULL,
								'Gasto MercadoEnvios',
								@MLPaymentsID,
								@MLPaymentsID,
								@MLPaymentsID,
								@MLPaymentsID,
								GETDATE(),
								GETDATE(),
								'*' ,
								2,
								@mlo_id

						END




				END



			-- Marca la orden como COBRADA para que no se vuelva a procesar.
			-- Si cancelan la cobranza automatica van a tener que cargarla a mano por FORROS !!!
			UPDATE tbMercadoLibre_ordersHeader		WITH (ROWLOCK)
				SET mlo_isCollected = 1
			FROM tbMercadoLibre_ordersHeader tmlop
				INNER JOIN @tmpOrdersOfThisShippment tmp
					ON tmp.mlo_id = tmlop.mlo_id
				WHERE	comp_id = @comp_id --AND
						--mlo_id	= @mlo_id

		END
	-- ----------------------------------------------------------------------




END
GO








CREATE  PROCEDURE [dbo].[spCreditCardMovementsTmp_updateData]
(
		@ccmt_id						int,
		@ccmt_guid						uniqueidentifier,
		@cc_id							int,
		@ccmt_Total						decimal(19,6),
		@ccmt_cardNumber				varchar(50),
		@ccmt_cardEmissionDate			datetime,
		@ccmt_cardExpirationDate		datetime,
		@ccmt_customerDocumentNumber	varchar(20),
		@ccmt_customerName				varchar(100),
		@ccmt_receiptNumber				varchar(50),
		@ccmt_AutorizationCode			varchar(50),
		@cccm_id						INT,
		@ccp_id							INT,
		@cct_id							INT


)
AS

BEGIN

	set nocount on



	SET @ccmt_AutorizationCode = dbo.fnStrAllTrim(@ccmt_AutorizationCode)


	IF @ccp_id = -1
	BEGIN
		SET @ccp_id = NULL
	END

	IF @cct_id = -1
	BEGIN
		SET @cct_id = NULL
	END

	update	dbo.tbCreditCardMovementsTmp

	set
			cc_id						=		@cc_id,
			ccmt_Total					=		@ccmt_Total,
			ccmt_cardNumber				=		@ccmt_cardNumber,
			ccmt_cardEmissionDate		=		@ccmt_cardEmissionDate,
			ccmt_cardExpirationDate		=		@ccmt_cardExpirationDate,
			ccmt_customerDocumentNumber	=		@ccmt_customerDocumentNumber,
			ccmt_customerName			=		@ccmt_customerName,
			ccmt_receiptNumber			=		@ccmt_receiptNumber,
			ccmt_AutorizationCode		=		@ccmt_AutorizationCode,
			cccm_id						=		@cccm_id,
			ccp_id						=		@ccp_id,
			cct_id						=		@cct_id

	where	ccmt_guid		= @ccmt_guid
	and	    ccmt_id			= @ccmt_id

END
GO





CREATE procedure [dbo].[spCreditCardMovementsTmp_UpdateLoteData]
(
		@comp_id	int,
		@bra_id		int,
		@ccmt_id	int,
		@guid		UNIQUEIDENTIFIER,
		@ccmt_lote	nvarchar(50),
		@strJSON	NVARCHAR(MAX)
)
as set NOCOUNT on


-- --------------------------------------
-- TESTING
-- --------------------------------------
/*
	declare
		@comp_id	int,
		@bra_id		int,
		@ccmt_id	int,
		@guid		UNIQUEIDENTIFIER,
		@ccmt_lote	nvarchar(50)
*/
-- --------------------------------------

begin


	update tbCreditCardMovementsTmp	WITH (ROWLOCK)
	SET
		ccmt_lote		=	@ccmt_lote,
		JSonData		=	CASE
								WHEN dbo.fnStrAllTrim(@strJSON) <> '' THEN @strJSON
								ELSE null
							END
	where	comp_id		= @comp_id
	and		bra_id		= @bra_id
	and		ccmt_id		= @ccmt_id
	and		ccmt_guid	= @guid

end
GO





CREATE procedure [dbo].[spCreditCardMovementsTmp_UpdateVoucher]
(
		@comp_id	int,
		@bra_id		int,
		@ccmt_id	int,
		@guid		UNIQUEIDENTIFIER,
		@ccv_id		int
)
as set NOCOUNT on


-- --------------------------------------
-- TESTING
-- --------------------------------------
/*
	declare
		@comp_id	int,
		@bra_id		int,
		@ccmt_id	int,
		@guid		UNIQUEIDENTIFIER,
		@ccmt_lote	nvarchar(50)
*/
-- --------------------------------------

begin


	update tbCreditCardMovementsTmp
		SET
			ccv_id		=	@ccv_id

		where	comp_id		= @comp_id
		and		bra_id		= @bra_id
		and		ccmt_id		= @ccmt_id
		and		ccmt_guid	= @guid

end
GO





