-- =============================================
-- Author:		MOS
-- Create date: 08-2014
-- Description:	Pone fechas de advertencia en CRM
-- =============================================

CREATE PROCEDURE [dbo].[spCRM_AdvertisementsCalculation]
	@comp_id	AS INT,
	@bra_id		AS INT
AS


BEGIN

	-- --------------------------------------------
	-- Testing
	-- --------------------------------------------
	/*
	declare @comp_id	AS INT
	declare @bra_id		AS INT
	set @comp_id	= 1
	set @bra_id		= 1
	*/
	-- --------------------------------------------

	SET NOCOUNT ON;

	--BEGIN TRANSACTION


		-- ------------------------------------------------------------------------------------------------------------
		-- TAREAS
		-- ------------------------------------------------------------------------------------------------------------

		DECLARE @task_id		AS INT
		DECLARE @tast_id		AS INT
		DECLARE @lang_id		AS INT
		DECLARE @user_id		AS INT
		DECLARE @datProcessing	AS DATETIME
		SET @datProcessing = GETDATE()
		SELECT TOP 1  @datProcessing = dbo.fnGetEnd_or_BeginOfDate( tb.bra_processingDate,'True' )
			FROM tbBranch tb		WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id


		DECLARE curTaskAdvertisement CURSOR LOCAL FAST_FORWARD FOR
			SELECT	task.task_id,
					task.tast_id,
					ISNULL(tb.lang_id,2),
					task.[user_id]
    			FROM tbCRM_Task				task			WITH (NOLOCK)
    			INNER JOIN tbCRM_TaskStatus tcts			WITH (NOLOCK)
    				ON	tcts.comp_id = task.comp_id AND
    					tcts.tast_id = task.tast_id
    			INNER JOIN tbCRM_Task_AdvertiseConfig tctac	WITH (NOLOCK)
    				ON	tctac.comp_id	= task.comp_id	AND
    					tctac.bra_id	= task.bra_id	AND
    					tctac.tast_id	= task.tast_id	AND
    					tctac.taskt_id	= task.taskt_id
    			LEFT JOIN tbBranch			tb				WITH (NOLOCK)
    				ON	tb.comp_id		= task.comp_id AND
    					tb.bra_id		= task.bra_id
				WHERE	task.comp_id				= @comp_id		AND
						task.bra_id					= @bra_id		AND
						CASE
							WHEN	task.task_advertiseDate		IS NULL		THEN 1
							WHEN	task.task_advertiseLastDate < GETDATE() THEN 1
							ELSE 0
						END	= 1		AND
						tcts.tast_isFinalStatus		  = 'False'	AND
						tcts.tast_lastOrderInPriority = 'False' AND
						tctac.advertise_disabled	  = 'False'	AND
						DATEDIFF(	DAY,
									CASE
										WHEN task.task_advertiseLastDate IS NOT NULL THEN	task.task_advertiseLastDate
										WHEN tctac.advertise_checkBeforeEnd = 'true' THEN	task.task_nextReviewdate
										ELSE												task.task_date4End
									END,
									@datProcessing
								) > tctac.advertise_daysOverdue



		OPEN		curTaskAdvertisement

		FETCH NEXT FROM curTaskAdvertisement  INTO @task_id,@tast_id,@lang_id,@user_id

		WHILE @@FETCH_STATUS = 0
			BEGIN


				--SELECT *, task.task_id,
				UPDATE tbCRM_Task
					SET
    					task_advertiseDate	=
    											DATEADD(minute, tctac.advertise_minute,
    											DATEADD(hour, tctac.advertise_hour,
    											dbo.fnGetEnd_or_BeginOfDate(
    											DATEADD(DAY, tctac.advertise_daysStep,
    												CASE
    		                  							WHEN task.task_advertiseLastDate IS NULL   THEN
		                  																				CASE
																											WHEN tctac.advertise_checkBeforeEnd = 'true' THEN	task.task_nextReviewdate
																											ELSE												task.task_date4End
																										END
    		                  							ELSE task.task_advertiseLastDate
    		                  						END ),'False'))),
    					task_advertiseLastDate	=
    											DATEADD(minute, tctac.advertise_minute,
    											DATEADD(hour, tctac.advertise_hour,
    											dbo.fnGetEnd_or_BeginOfDate(@datProcessing,'False'))),
    					task_advertise_desc		= tctac.advertise_desc
    				FROM tbCRM_Task				task			WITH (NOLOCK)
    				INNER JOIN tbCRM_TaskStatus tcts			WITH (NOLOCK)
    					ON	tcts.comp_id = task.comp_id AND
    						tcts.tast_id = task.tast_id
    				INNER JOIN tbCRM_Task_AdvertiseConfig tctac	WITH (NOLOCK)
    					ON	tctac.comp_id	= task.comp_id	AND
    						tctac.bra_id	= task.bra_id	AND
    						tctac.tast_id	= task.tast_id	AND
    						tctac.taskt_id	= task.taskt_id
					WHERE	task.comp_id				= @comp_id		AND
							task.task_id				= @task_id


				-- -------------------------------------------------------
				-- Enviamos EMAils en caso de corresponder
				-- -------------------------------------------------------
				EXEC spCRM_Task_sendEmail @comp_id, @task_id, @lang_id
				-- -------------------------------------------------------

				-- -------------------------------------------------------
				-- Carga en workFlow
				-- -------------------------------------------------------

				-- Saca del WorkFlow lo que haya de esta tarea.
				UPDATE tbWorkflow
					SET		wf_isProcessed		= 'True',
							wf_dateOfProcessing = GETDATE()
					WHERE	comp_id			= @comp_id AND
							task_id			= @task_id AND
							wf_isProcessed	= 'False'



				DECLARE @strSubject AS NVARCHAR(200) = ''
				SELECT  @strSubject = tt.task_subject
					FROM  tbCRM_Task tt
					WHERE	comp_id = @comp_id AND
							task_id = @task_id

				DECLARE @strURL AS NVARCHAR(600)
				SET @strURL = 'wfmCRM_TaskDetail.aspx?&BraId='	+ CONVERT(VARCHAR,@bra_id)	+
													'&TaskId='	+ CONVERT(VARCHAR,@task_id) +
													'&Action='  + 'U'						+ '&'

				--GRABAMOS WORKFLOW
				INSERT INTO tbWorkflow
				(
					comp_id,
					bra_id,
					wf_type,
					wf_isProcessed,
					user_id_from,
					user_id_assigned,
					user_id_processed,
					prof_id_assigned,
					wf_dateOfAssigned,
					wf_dateOfProcessing,
					wf_link,
					wf_message1,
					wf_message2,
					wf_htmlTop,
					wf_htmlBody,
					wf_html_Bottom,
					task_id
				)
				VALUES
				(
					@comp_id,
					@bra_id,
					780,
					'False',
					NULL,
					@user_id, --@intUser4Notify,
					NULL,
					NULL,
					GETDATE(),
					NULL,
					@strURL,
					@strSubject,
					'',
					'', --@strRet_ErrorDescription,
					'',
					'',
					@task_id
				)


			-- -------------------------------------------------------


				FETCH NEXT FROM  curTaskAdvertisement  INTO @task_id,@tast_id,@lang_id,@user_id
			END

		CLOSE		curTaskAdvertisement
		DEALLOCATE	curTaskAdvertisement

		-- ------------------------------------------------------------------------------------------------------------





		-- --------------------------
		-- CASOS
		-- --------------------------
		;DISABLE TRIGGER ALL ON tbCRM_Case;


		UPDATE tbCRM_Case
			SET
    			Case_advertiseDate	=
    									DATEADD(minute, tctac.advertise_minute,
    									DATEADD(hour, tctac.advertise_hour,
    									dbo.fnGetEnd_or_BeginOfDate(
    									DATEADD(DAY, tctac.advertise_daysStep,
    										CASE
    		                  					WHEN crmCase.case_advertiseLastDate IS NULL   THEN
		                  																		CASE
																									WHEN tctac.advertise_checkBeforeEnd = 'true' THEN	crmCase.Case_date4Begin
																									ELSE												crmCase.Case_date4End
																								END
    		                  					ELSE crmCase.Case_advertiseLastDate
    		                  				END ),'False')))
    		FROM tbCRM_Case				crmCase
    		INNER JOIN tbCRM_CaseStatus tcts
    			ON	tcts.comp_id = crmCase.comp_id AND
    				tcts.cast_id = crmCase.cast_id
    		INNER JOIN tbCRM_Case_AdvertiseConfig tctac
    			ON	tctac.comp_id	= crmCase.comp_id	AND
    				tctac.bra_id	= crmCase.bra_id	AND
    				tctac.cast_id	= crmCase.cast_id	AND
    				tctac.caset_id	= crmCase.Caset_id
			WHERE	crmCase.comp_id				= @comp_id		AND
					crmCase.bra_id					= @bra_id		AND
					crmCase.Case_advertiseDate		IS NULL		AND
					tcts.cast_isFinalStatus		= 'False'	AND
					tctac.advertise_disabled	= 'False'	AND
				   ((tctac.advertise_checkBeforeEnd = 'False' AND @datProcessing > crmCase.Case_date4End)
						OR
					(tctac.advertise_checkBeforeEnd = 'True'  AND @datProcessing > crmCase.Case_date4Begin)
				   )
					AND
					DATEDIFF(	DAY,
								CASE
									WHEN tctac.advertise_checkBeforeEnd = 'true' THEN	crmCase.Case_date4Begin
									ELSE												crmCase.Case_date4End
								END ,
								@datProcessing
								) > tctac.advertise_daysOverdue

		;
		ENABLE TRIGGER ALL ON tbCRM_Case;












		-- --------------------------
		-- LLAMADAS
		-- --------------------------

		DISABLE TRIGGER ALL ON tbCRM_Call;


		UPDATE tbCRM_Call
			SET
    			call_advertiseDate	=
    									DATEADD(minute, tctac.advertise_minute,
    									DATEADD(hour, tctac.advertise_hour,
    									dbo.fnGetEnd_or_BeginOfDate(
    									DATEADD(DAY, tctac.advertise_daysStep,
    										CASE
    		                  					WHEN crmCall.call_advertiseLastDate IS NULL   THEN	crmCall.call_date4Begin
    		                  					ELSE crmCall.Call_advertiseLastDate
    		                  				END ),'False')))
    		FROM tbCRM_Call				crmCall
    		INNER JOIN tbCRM_CallStatus tcts
    			ON	tcts.comp_id	= crmCall.comp_id AND
    				tcts.callst_id  = crmCall.callst_id
    		INNER JOIN tbCRM_Call_AdvertiseConfig tctac
    			ON	tctac.comp_id	= crmCall.comp_id	AND
    				tctac.bra_id	= crmCall.bra_id	AND
    				tctac.callst_id	= crmCall.callst_id	AND
    				tctac.callt_id	= crmCall.callt_id
			WHERE	crmCall.comp_id				= @comp_id		AND
					crmCall.bra_id				= @bra_id		AND
					crmCall.call_advertiseDate		IS NULL		AND
					tcts.callst_isFinalStatus	= 'False'	AND
					tctac.advertise_disabled	= 'False'	AND
					(@datProcessing > crmCall.call_date4Begin)
					AND
					DATEDIFF(	DAY,
								crmCall.call_date4Begin ,
								@datProcessing
								) > tctac.advertise_daysOverdue

		;
		ENABLE TRIGGER ALL ON tbCRM_Call;











		-- --------------------------
		-- MEET
		-- --------------------------

		DISABLE TRIGGER ALL ON tbCRM_Meet;


		UPDATE tbCRM_Meet
			SET
    			meet_advertiseDate	=
    									DATEADD(minute, tctac.advertise_minute,
    									DATEADD(hour, tctac.advertise_hour,
    									dbo.fnGetEnd_or_BeginOfDate(
    									DATEADD(DAY, tctac.advertise_daysStep,
    										CASE
    		                  					WHEN crmMeet.Meet_advertiseLastDate IS NULL   THEN crmMeet.Meet_date4Begin
    		                  					ELSE crmMeet.Meet_advertiseLastDate
    		                  				END ),'False')))
    		FROM tbCRM_Meet				crmMeet
    		INNER JOIN tbCRM_MeetStatus tcts
    			ON	tcts.comp_id	= crmMeet.comp_id AND
    				tcts.meetst_id	= crmMeet.meetst_id
    		INNER JOIN tbCRM_Meet_AdvertiseConfig tctac
    			ON	tctac.comp_id	= crmMeet.comp_id	AND
    				tctac.bra_id	= crmMeet.bra_id	AND
    				tctac.meetst_id	= crmMeet.meetst_id	AND
    				tctac.meett_id	= crmMeet.meett_id
			WHERE	crmMeet.comp_id				= @comp_id		AND
					crmMeet.bra_id					= @bra_id		AND
					crmMeet.Meet_advertiseDate		IS NULL		AND
					tcts.meetst_isFinalStatus		= 'False'	AND
					tctac.advertise_disabled		= 'False'	AND
					( @datProcessing > crmMeet.Meet_date4Begin)
					AND
					DATEDIFF(	DAY,
								crmMeet.Meet_date4Begin  ,
								@datProcessing
								) > tctac.advertise_daysOverdue

		;
		ENABLE TRIGGER ALL ON tbCRM_Meet;




	--COMMIT TRANSACTION

END
GO







CREATE PROCEDURE [dbo].[spCRM_Call_deleteData]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@lang_id			INT,

	@call_id			INT
)
AS
SET NOCOUNT ON


BEGIN

	-- -----------------------------------------------------------------------------------------------------------
	--ACA BORRAMOS EL HISTORICO EN CASO DE PODER HACERLO EN BASE AL USUARIO QUE REALIZA LA ACCIÓN!
	-- -----------------------------------------------------------------------------------------------------------
	--VARIABLE PARA SABER SI PUEDE O NO BORRAR EL HISTORIAL
	DECLARE
		@lbitCanDeleteHistory	BIT

	IF EXISTS(SELECT 1
			  FROM tbControlProfiles			tcp1
			  WHERE	tcp1.comp_id	= @comp_id	AND
					tcp1.bra_id		= @bra_id	AND
					tcp1.prof_id	= @prof_id	AND
					tcp1.ctrl_id	= 2877		AND
					tcp1.page_id	= 9000)

		SET @lbitCanDeleteHistory = 'True'

	ELSE

		SET @lbitCanDeleteHistory = 'False'

	--SI EL CONTROL ESTA HABILITADO PARA BORRAR, BORRA TODOS LOS DETALLES ASOCIADOS AL @CALL_ID
	IF @lbitCanDeleteHistory = 'True'

		DELETE FROM tbCRM_CallHistory WHERE comp_id = @comp_id AND call_id = @call_id


	-- -----------------------------------------------------------------------------------------------------------

declare
	@callt_id	INT

select @callt_id = tcc.callt_id
  from tbCRM_Call tcc where tcc.comp_id = @comp_id and tcc.call_id = @call_id

	DELETE FROM tbCRM_Call

	WHERE	comp_id = @comp_id
	AND		call_id = @call_id

declare
	@msg	nvarchar(1000)

select @msg = (tut.utexts_desc + ' ' + convert(varchar,@call_id))
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 990


--STL
declare @description as nvarchar(500)

select
	@description = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 300066

set @description = @description + ' ' + convert(varchar,@call_id)


insert into tbSecurityLog
(
	comp_id,
	bra_id,
	user_id,
	seclog_obs_1,
	seclog_obs_2,
	seclog_image,
	seclog_obs_3,
	seclog_obs_4,
	seclog_cd,
	aut_id,
	sysCode_id,
	menu_id,
	menu_ts,
	request_ip,
	request_name,
	aure_isok,
	aure_user_id,
	seclog_pageHTML,
	prof_id,
	aure_cd,
	aure_id,
	seclog_id1,
	seclog_id2,
	seclog_id3
)
VALUES
(
	@comp_id,
	@bra_id,
	@user_id,
	@description,
	NULL,
	NULL,
	NULL,
	NULL,
	getdate(),
	NULL,
	1402,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	@prof_id,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL
)

-- -------------------------------------------------------
-- Obtenemos los mails a enviar a los grupos de usuarios
-- -------------------------------------------------------

declare
	@email_recipients	nvarchar(4000),
	@title				nvarchar(1000),
	@text				nvarchar(1000)

select @title = tut.utexts_desc
  from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 300074

select @text = tut.utexts_desc
  from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 300066

set @text = @text + ' ' + convert(varchar,@call_id)

set @email_recipients = ''

select
	@email_recipients = @email_recipients + '; ' + tu.user_email

	from tbCRM_UserGroups						tcug			WITH (NOLOCK)

	inner join tbCRM_UserGroupsDetail		tcugd				WITH (NOLOCK)
		on	tcugd.comp_id	= tcug.comp_id
		AND tcugd.crmug_id	= tcug.crmug_id

	inner join tbUser						tu					WITH (NOLOCK)
		on tu.[user_id] = tcugd.[user_id]

	where	tcug.comp_id						= @comp_id
	--and		tcugd.user_id						= @user_id
	and		tcugd.crmug_id						in (select crmug_id
														from tbCRM_UserGroupsDetail tcugd2		WITH (NOLOCK)
														where	tcugd2.comp_id	 = @comp_id
														and		tcugd2.[user_id] = @user_id)
	and		tcugd.crmugd_disabled				= 'False'
	and     tcugd.crmugd_reciveEmailofChanges	= 'True'
	-- ACA CAMBIAR PARA TAREAS, LLAMADAS y REUNIONES
	and		tcugd.crmugd_4Call					= 'True'
	and		(/*@callt_id = -1*/ tcugd.callt_id IS NULL or  tcugd.callt_id	= @callt_id)

if @email_recipients <> ''
	begin
		SET @email_recipients = SUBSTRING(@email_recipients,2,LEN(@email_recipients) - 1)

		exec spSystem_sendEMail
			@compId					= @comp_id,
			@precipients			= @email_recipients,
			@pcopy_recipients		= null,
			@psubject				= @title,
			@pbody_format			= 'TEXT',
			@pbody					= @text ,
			@pfile_attachments		= null,
			@pReplyTo				= NULL,
			@pblind_copy_recipients	='',
			@pUser_Id				= @user_id
	end


END
GO







CREATE PROCEDURE [dbo].[spCRM_Call_getCombo]
(
	@comp_id			int
)
as
set nocount ON

	select		tcc.call_id								[id],
				'(' + CONVERT(VARCHAR,tcc.call_id) + ') - ' +
				substring(tcc.call_description,1,100)	[desc]


	from		dbo.tbCRM_Call tcc

	where		comp_id		= @comp_id

	ORDER BY  tcc.call_description
GO






