CREATE PROCEDURE [dbo].[spCRM_Call_getDataByFilters]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,

	@selection_id		INT,	--- NO SE USA MAS ESTA MIERDA, QUIEN SABE QUE CARAJO ES Y ASI SE MANDAN LAS FORRADAS
	@tast_id			INT,
	@cast_id			INT,
	@callst_id			INT,
	@meetst_id			INT,
	@datefrom			datetime,
	@dateto				datetime,
	@option				INT,
	@text				nvarchar(500),
	@contact			int,
	@contact_text		nvarchar(500),
	@guid				UNIQUEIDENTIFIER,
	@session_user_id	int,
	@callt_id			int,
	@call_id			INT,
	@supp_id			INT,
	@cust_id			int,
	@datereviewfrom		datetime,
	@datereviewto		datetime,
	@pro_id				INT
)
AS


BEGIN





		SET NOCOUNT ON
		set DATEFORMAT 'ymd'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------

		--------------------------------------------------------
		-------------parametros de prueba-----------------------
		--------------------------------------------------------
		/*
		DECLARE		@comp_id		INT,
					@bra_id			INT,
					@prof_id		INT,
					@user_id		INT,

					@selection_id	INT,
					@tast_id		INT,
					@cast_id		INT,
					@callst_id		INT,
					@meetst_id		INT,
					@datefrom		datetime,
					@dateto			datetime,
					@option			INT,
					@text			nvarchar(500),
					@contact		int,
					@contact_text   nvarchar(500),
					@guid			uniqueidentifier,
					@session_user_id	int



		SELECT		@comp_id			= 1,
					@bra_id				= 1,
					@prof_id			= 1,

					@selection_id		= -1,
					@datefrom			= '2012-01-01',
					@dateto				= '2012-12-12',
					@tast_id			= -1,
					@cast_id			= -1,
					@meetst_id			= -1,
					@callst_id			= -1,
					@user_id			= 1,
					@option				= -1,
					@text				= '',
					@contact_id			= -1,
					@guid				= 'a87d4c32-3760-47f7-b09a-18d5978e1734',
					@session_user_id	= 1
	*/
		--------------------------------------------------------




	-- --------------------------------------------------------------------------
	-- Pone en una tabla temporal todos los usuarios de mi grupo y
	-- si no estoy en ningun grupo, todos los disponibles para crm
	-- --------------------------------------------------------------------------
	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom	,'false')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto	,'true')

	SET @datereviewfrom	= dbo.fnGetEnd_or_BeginOfDate(@datereviewfrom	,'false')
	SET @datereviewto   = dbo.fnGetEnd_or_BeginOfDate(@datereviewto	,'true')

	DECLARE @tmpUsersOfMyGroup TABLE(USER_ID INT PRIMARY KEY)

	INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
		SELECT DISTINCT tcugd.[USER_ID]
			FROM tbCRM_UserGroupsDetail tcugd							WITH (NOLOCK)
			INNER JOIN tbUser tuMyUser									WITH (NOLOCK)
				ON tuMyUser.[user_id]		= @session_user_id
			INNER JOIN tbUser tu										WITH (NOLOCK)
				ON	tu.[user_id]			= tcugd.[user_id]	AND
					tu.user_available4CRM	= 'True'
			INNER JOIN tbCRM_UserGroupsDetail mg						WITH (NOLOCK)
				ON	mg.[user_id] = @session_user_id				AND
					mg.crmugd_IsAvailable2ViewOtherUsers = 'True'
		WHERE	tcugd.comp_id	= mg.comp_id					AND
				tcugd.crmug_id	= mg.crmug_id					AND
			    tuMyUser.user_available4CRM_SeeAllCalls	= 'True'


	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tu.[USER_ID]
					FROM	tbUser tu									WITH (NOLOCK)
					INNER JOIN tbUser tuMyUser							WITH (NOLOCK)
						ON tuMyUser.[user_id]						= @session_user_id
					WHERE	tu.user_available4CRM					= 'True' AND
							tuMyUser.user_available4CRM_SeeAllCalls	= 'True'
		END


	IF NOT EXISTS(	SELECT 1
						FROM @tmpUsersOfMyGroup
						WHERE [USER_ID] = @session_user_id
				 )
	BEGIN
		INSERT INTO @tmpUsersOfMyGroup ([USER_ID])
			VALUES(@session_user_id)
	END
	-- --------------------------------------------------------------------------




		--guardar el campo de usuario "ver todas las tareas" para mostrar todas las tareas o
		--filtrar solo las del usuario
		declare @luser_available4CRM_SeeAllCalls	bit

		SELECT	@luser_available4CRM_SeeAllCalls	= isnull(tu.user_available4CRM_SeeAllCalls, 'false')
			FROM	tbUser tu
			WHERE	tu.[user_id] = @session_user_id
		--SELECT	@luser_available4CRM_SeeAllCalls


		SELECT  ' ' [ ], ' ' [ ],' ' [ ], ' ' [ ], ' ' [ ],
				convert(bit,case
								when tct2.comp_id is null then 'false'
								else 'true'
							end)													[filter],
				cc.call_id															[ID2],
				call_date4Begin,
				call_nextReviewdate												[nextReviewdate],
				call_howLong,
				call_description,
				tcct.callt_desc														[call_type],
				call_Note1,
				call_Note2,
				tcc.case_desc														[case_id],
				tct.task_subject													[task_id],
				cc.soh_Bra_id,
				cc.soh_Soh_id,
				tc2.contact_name													[contact_id],
				tc.cust_name														[cust_id],
				tu.user_lastname + ', ' + tu.user_firstname							[user_name],
				tccs.callst_desc,
				cc.[user_id],
				cc.call_price,
				tsc.curr_desc,
				cc.call_emailAdditional,
				cc.call_id															[ID]



		FROM 	dbo.tbCRM_Call								cc			WITH (NOLOCK)


				INNER JOIN @tmpUsersOfMyGroup tmpu
					ON tmpu.[USER_ID] = cc.[user_id]

				LEFT JOIN tbCRM_Call_Block4Filter tctbf					WITH (NOLOCK)
					ON	tctbf.comp_id			= cc.comp_id		AND
						tctbf.bra_id			= cc.bra_id			AND
						tctbf.callt_id			= cc.callt_id		AND
						tctbf.callst_id			= cc.callst_id		AND
						tctbf.user_id_call		= cc.[user_id]		AND
						tctbf.user_id_actual	= @session_user_id	AND
						cc.[user_id]			<>@session_user_id



				left join tbCRM_tmp							tct2		WITH (NOLOCK)
				on	tct2.comp_id			= cc.comp_id
				and tct2.crmt_function		= 3 -- Aquí es el unico caso en que se suma UNO, no se que MIERDA hizo el HDP que armo esta parte!!!  (0 Case;1 Task;2 Call;3 Meet)
				and tct2.crmt_function_id	= cc.call_id
				and tct2.crmt_guid			= @guid

				LEFT JOIN	tbCRM_CallStatus				tccs		WITH (NOLOCK)
				ON  tccs.comp_id	= cc.comp_id
				AND tccs.callst_id	= cc.callst_id

				inner join	tbCRM_TypesByProfile			tctbp		WITH (NOLOCK)
				on  tctbp.comp_id	= cc.comp_id
				and tctbp.bra_id	= cc.bra_id
				and tctbp.prof_id	= @prof_id
				and tctbp.crm_type	= 2		--call

				LEFT JOIN tbUsers4BranchFilter tubf								WITH (NOLOCK)
					ON	tubf.comp_id	= cc.comp_id		AND
						tubf.bra_id		= cc.bra_id		AND
						tubf.[user_id]	= @session_user_id

				left join	tbUser							tu			WITH (NOLOCK)
				on	tu.[user_id]	= cc.[user_id]

				left join	tbCustomer						tc			WITH (NOLOCK)
				on	tc.comp_id		= cc.comp_id
				AND tc.cust_id		= cc.cust_id

				left join	tbContact						tc2			WITH (NOLOCK)
				on  tc2.comp_id		= cc.comp_id
				AND tc2.contact_id	= cc.contact_id

				left join	tbCRM_Case						tcc			WITH (NOLOCK)
				on  tcc.comp_id		= cc.comp_id
				AND tcc.case_id		= cc.case_id

				left join tbCRM_CaseStatus					tccs2		WITH (NOLOCK)
				on  tccs2.comp_id	= tcc.comp_id
				and tccs2.cast_id	= tcc.cast_id

				left join	tbCRM_Task						tct			WITH (NOLOCK)
				on	tct.task_id		= cc.task_id
				AND tct.comp_id		= cc.comp_id

				left join tbCRM_TaskStatus					tcts		WITH (NOLOCK)
				on tcts.comp_id		= tct.comp_id
				ANd tcts.tast_id	= tct.tast_id

				inner join tbBranch							tb			WITH (NOLOCK)
				on tb.comp_id = cc.comp_id
				and tb.bra_id = cc.bra_id

				inner join tbsysCurrency					tsc			WITH (NOLOCK)
				on tsc.curr_id = tb.curr_id

				inner join tbCRM_CallType					tcct		WITH (NOLOCK)
				on  tcct.comp_id = cc.comp_id
				AND tcct.callt_id = cc.callt_id


		WHERE	cc.comp_id			= @comp_id
		AND			(@call_id		= 0			OR cc.call_id	= @call_id)
		AND			(cc.bra_id		= @bra_id	OR cc.[user_id]	= @session_user_id	 OR tubf.comp_id IS NOT NULL)
		AND		(@callt_id = -1 OR  cc.callt_id = @callt_id)
--		AND     (
--					(@luser_available4CRM_SeeAllCalls = 'false' and cc.[user_id]	= @user_id) OR
--					(@luser_available4CRM_SeeAllCalls = 'true')
--				)
		AND		(	 cc.task_id IS NULL																									OR
					(@tast_id		= -1)																								OR
     				(@tast_id		= -2 and  tcts.tast_isFinalStatus		= 'false')													OR
     				(@tast_id		= -3 and  tcts.tast_isFinalStatus		= 'True')													OR
     				(@tast_id		= -4 and  tcts.tast_isInitialStatus		= 'True')													OR
     				(@tast_id		= -5 and (tcts.tast_isInitialStatus		= 'False' AND tcts.tast_isFinalStatus = 'False'))			OR
					(@tast_id		= tcts.tast_id)
				)
		AND		(
					 cc.case_id IS NULL																									OR
					(@cast_id		= -1)																								or
     				(@cast_id		= -2 and  tccs2.cast_isFinalStatus		= 'false')													OR
     				(@cast_id		= -3 and  tccs2.cast_isFinalStatus		= 'True')													OR
     				(@cast_id		= -4 and  tccs2.cast_isInitialStatus	= 'True')													OR
     				(@cast_id		= -5 and (tccs2.cast_isInitialStatus	= 'False' AND tccs2.cast_isFinalStatus = 'False'))			OR
					(tcc.cast_id	= @cast_id)
				)

		AND		(
					(@callst_id		= -1)		or
     				(@callst_id		= -2 and  tccs.callst_isFinalStatus		= 'false')													OR
     				(@callst_id		= -3 and  tccs.callst_isFinalStatus		= 'True')													OR
     				(@callst_id		= -4 and  tccs.callst_isInitialStatus	= 'True')													OR
     				(@callst_id		= -5 and (tccs.callst_isInitialStatus	= 'False' AND tccs.callst_isFinalStatus = 'False'))			OR
					(tccs.callst_id	= @callst_id)
				)
		--and		(@selection_id		=	-1		or		 cc.cust_id		= @selection_id)

		--AND		(@contact_id		=	-1		or		 tc2.contact_id		= @contact_id)
		AND		(@contact			= -1			OR cc.contact_id = @contact)

--		and		(
--					(@contact	 = -1 ) or
--					(@contact	 = 0 and tc2.contact_name like @contact_text + '%') or
--					(@contact	 = 1 and tc2.contact_name like '%' + @contact_text + '%') or
--					(@contact	 = 2 and tc2.contact_name = @contact_text ) or
--					(@contact	 = 3 and tc2.contact_name <> @contact_text ) or
--					(@contact	 = 4 and tc2.contact_name not like '%' + @contact_text + '%')
--				)
		AND		cc.call_date4Begin	BETWEEN @datefrom and @dateto
		and		((
					(@option	 = -1 ) or
					(@option	 = 0 and cc.call_description like @text + '%') or
					(@option	 = 1 and cc.call_description like '%' + @text + '%') or
					(@option	 = 2 and cc.call_description = @text ) or
					(@option	 = 3 and cc.call_description <> @text ) or
					(@option	 = 4 and cc.call_description not like '%' + @text + '%')
				)
				or
				(
					(@option	 = -1 ) or
					(@option	 = 0 and cc.call_Note1 like @text + '%') or
					(@option	 = 1 and cc.call_Note1 like '%' + @text + '%') or
					(@option	 = 2 and cc.call_Note1 = @text ) or
					(@option	 = 3 and cc.call_Note1 <> @text ) or
					(@option	 = 4 and cc.call_Note1 not like '%' + @text + '%')
				)
				or
				(
					(@option	 = -1 ) or
					(@option	 = 0 and cc.call_Note2 like @text + '%') or
					(@option	 = 1 and cc.call_Note2 like '%' + @text + '%') or
					(@option	 = 2 and cc.call_Note2 = @text ) or
					(@option	 = 3 and cc.call_Note2 <> @text ) or
					(@option	 = 4 and cc.call_Note2 not like '%' + @text + '%')
				))
		AND		(
						(@user_id		= -1		AND tctbf.comp_id IS NULL)
					OR
						(cc.[user_id]	= @user_id	AND tctbf.comp_id IS NULL)
				)

		and		(
					( cc.comp_id not in (	select top 1 tct2.comp_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 1
												and tct2.crmt_guid = @guid))		or

					(cc.case_id in (		select tct2.crmt_function_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 1
												and tct2.crmt_guid = @guid))
				)

		and		(
					( cc.comp_id not in (	select top 1 tct2.comp_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 2
												and tct2.crmt_guid = @guid))		or

					(cc.task_id in (		select tct2.crmt_function_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 2
												and tct2.crmt_guid = @guid))
			    )

		AND		(@supp_id			= -1		OR		cc.supp_id		= @supp_id)
		AND		(@cust_id			= -1		or		cc.cust_id		= @cust_id)
		AND (isnull(cc.call_nextReviewdate,'')	BETWEEN @datereviewfrom and @datereviewto )--ga

		AND	(@pro_id			= -1		OR		cc.pro_id		= @pro_id)

	order by [filter],cc.call_date4Begin DESC



END
GO






