---Tareas
--------------------


CREATE PROCEDURE [dbo].[spCRM_Call_getDataById]
(
	@comp_id			INT,
	@call_id			INT
)
AS
SET NOCOUNT ON


BEGIN

	--------------------------------------------------------
	-------------parametros de prueba-----------------------
	--------------------------------------------------------
	/*
	declare		@comp_id			INT,
				@task_id			INT,
				@call_id			INT

	select		@comp_id			= 1,
				@task_id			= 1,
				@call_id			= 1
	*/
	--------------------------------------------------------
	--------------------------------------------------------
	--------------------------------------------------------


	SELECT	tcc.call_id,
			tcc.bra_id,
			tcc.call_date4Begin,
			CONVERT(VARCHAR(5) , call_date4Begin , 108)		[call_Hour4Begin],
			tcc.call_howLong,
			tcc.[user_id],
			isnull(tu.user_lastname,'') + ', ' + isnull(tu.user_firstname,'')
															[user_name],
			tcc.call_description,
			tcc.call_Note1,
			tcc.call_Note2,
			isnull(tcc.case_id,-1)							[case_id],
			isnull(tcc.task_id,-1)							[task_id],
			tcc.soh_Bra_id,
			tcc.soh_soh_id,
			isnull(tcc.contact_id,-1)						[contact_id],
			isnull(tcc.cust_id,-1)							[cust_id],
			tcc.callst_id,
			tc.curr_desc,
			tcc.call_price,
			tcc.curr_id,
			tcct.callt_id,
			tcc.call_emailAdditional,
			tcc.supp_id,
			tcc.call_nextReviewdate,
			tcc.pro_id

	FROM 	dbo.tbCRM_Call								tcc

			INNER JOIN tbUser							tu
			ON tu.[user_id]		= tcc.[user_id]

			inner join tbBranch							tb
			on tb.comp_id = tcc.comp_id
			and tb.bra_id = tcc.bra_id

			inner join tbsysCurrency					tc
			on tc.curr_id = tb.curr_id

			left join tbCRM_CallType					tcct
			on  tcct.comp_id = tcc.comp_id
			AND tcct.callt_id = tcc.callt_id

	WHERE	tcc.comp_id			= @comp_id
	AND		tcc.call_id			= @call_id

END



GO








CREATE PROCEDURE [dbo].[spCRM_Call_getDataByText]
(
	@text	VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id  AS INT
)
AS



BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*

		DECLARE
			@text		VARCHAR(300),
			@count		INT,
			@lang_id	INT,
			@comp_id AS INT,
			@bra_id  AS INT

		SELECT
			@text		='A',
			@count		= 2,
			@lang_id	= 2,
			@comp_id	= 1,
			@bra_id		= 1
	*/
	-- ----------------------------------------------------------------





	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')



	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)
	DECLARE @text6	varchar(300)
	DECLARE @text7	varchar(300)
	DECLARE @text8	varchar(300)
	DECLARE @text9	varchar(300)
	DECLARE @text10	varchar(300)

	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0 else
			IF @text2 IS NULL SET @text2 = @text0 else
			IF @text3 IS NULL SET @text3 = @text0 else
			IF @text4 IS NULL SET @text4 = @text0 else
			IF @text5 IS NULL SET @text5 = @text0 else
			IF @text6 IS NULL SET @text6 = @text0 else
			IF @text7 IS NULL SET @text7 = @text0 else
			IF @text8 IS NULL SET @text8 = @text0 else
			IF @text9 IS NULL SET @text9 = @text0 else
			IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------





	SELECT		TOP (@count)

				Upper(dbo.PadRightString( IsNull(tc.call_description,''),'.',50)) + ' | ' + isnull(convert(VARCHAR(10),tc.call_id),'')	[call_description],
				tc.call_id
		FROM tbCRM_Call tc
			WHERE		tc.comp_id = @comp_id
					AND (tc.bra_id IS NULL OR tc.bra_id = @bra_id)
		AND
			(

						CASE
							WHEN @selection_method = 0 AND tc.call_description LIKE @text + '%'	 THEN	'True'
							WHEN @selection_method = 1 AND tc.call_description LIKE '%' + @text1 + '%'	 THEN	'True'
							WHEN @selection_method = 2 AND tc.call_description LIKE '%' + @text1 + '%' AND tc.call_description LIKE '%' + @text2 + '%'		 THEN	'True'
							WHEN @selection_method = 3 AND tc.call_description LIKE '%' + @text1 + '%' AND tc.call_description LIKE '%' + @text2 + '%' AND tc.call_description LIKE '%' + @text3 + '%'	 THEN	'True'
							WHEN @selection_method = 4 AND tc.call_description LIKE '%' + @text1 + '%' AND tc.call_description LIKE '%' + @text2 + '%' AND tc.call_description LIKE '%' + @text3 + '%' AND tc.call_description LIKE '%' + @text4 + '%'		 THEN	'True'
							WHEN @selection_method = 5 AND tc.call_description LIKE '%' + @text1 + '%' AND tc.call_description LIKE '%' + @text2 + '%' AND tc.call_description LIKE '%' + @text3 + '%' AND tc.call_description LIKE '%' + @text4 + '%' AND tc.call_description LIKE '%' + @text5 + '%'		 THEN	'True'
							WHEN @selection_method = 6 AND tc.call_description LIKE '%' + @text1 + '%' AND tc.call_description LIKE '%' + @text2 + '%' AND tc.call_description LIKE '%' + @text3 + '%' AND tc.call_description LIKE '%' + @text4 + '%' AND tc.call_description LIKE '%' + @text5 + '%' AND tc.call_description LIKE '%' + @text6 + '%'	 THEN	'True'
							WHEN @selection_method = 7 AND tc.call_description LIKE '%' + @text1 + '%' AND tc.call_description LIKE '%' + @text2 + '%' AND tc.call_description LIKE '%' + @text3 + '%' AND tc.call_description LIKE '%' + @text4 + '%' AND tc.call_description LIKE '%' + @text5 + '%' AND tc.call_description LIKE '%' + @text6 + '%' AND tc.call_description LIKE '%' + @text7 + '%'	 THEN	'True'
							WHEN @selection_method = 8 AND tc.call_description LIKE '%' + @text1 + '%' AND tc.call_description LIKE '%' + @text2 + '%' AND tc.call_description LIKE '%' + @text3 + '%' AND tc.call_description LIKE '%' + @text4 + '%' AND tc.call_description LIKE '%' + @text5 + '%' AND tc.call_description LIKE '%' + @text6 + '%' AND tc.call_description LIKE '%' + @text7 + '%' AND tc.call_description LIKE '%' + @text8 + '%'		 THEN	'True'
							WHEN @selection_method = 9 AND tc.call_description LIKE '%' + @text1 + '%' AND tc.call_description LIKE '%' + @text2 + '%' AND tc.call_description LIKE '%' + @text3 + '%' AND tc.call_description LIKE '%' + @text4 + '%' AND tc.call_description LIKE '%' + @text5 + '%' AND tc.call_description LIKE '%' + @text6 + '%' AND tc.call_description LIKE '%' + @text7 + '%' AND tc.call_description LIKE '%' + @text8 + '%' AND tc.call_description LIKE '%' + @text9 + '%'		 THEN	'True'
							WHEN @selection_method =10 AND tc.call_description LIKE '%' + @text1 + '%' AND tc.call_description LIKE '%' + @text2 + '%' AND tc.call_description LIKE '%' + @text3 + '%' AND tc.call_description LIKE '%' + @text4 + '%' AND tc.call_description LIKE '%' + @text5 + '%' AND tc.call_description LIKE '%' + @text6 + '%' AND tc.call_description LIKE '%' + @text7 + '%' AND tc.call_description LIKE '%' + @text8 + '%' AND tc.call_description LIKE '%' + @text9 + '%' AND tc.call_description LIKE '%' + @text10 + '%'		 THEN 'True'
							ELSE	'False'
						END	= 'True'

			)



			ORDER BY	tc.call_description

END
GO








CREATE PROCEDURE [dbo].[spCRM_Call_GetHistoryData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@call_id	INT
)
as set nocount on


-- -----------------------------------------------
-- Testing
-- -----------------------------------------------
/*
	declare
		@comp_id	INT,
		@call_id	INT
	select
		@comp_id	= 1,
		@call_id	= 319
*/
-- -----------------------------------------------


select
	tcc2.case_subject													[case_subject],
	tcc2.case_desc														[case_desc],
	tcc2.case_resolution												[case_resolution],
	tct.task_subject													[task_subject],
	tct.task_desc														[task_desc],
	tcch.call_date4Begin												[call_date4Begin],
	tcch.call_howLong													[call_howLong],
	tcch.call_description												[call_description],
	tcch.call_Note1														[call_Note1],
	tcch.call_Note2														[call_Note2],
	tcch.callh_cd														[LastUpdate],
	tcct.callt_desc														[call_type],
	tu.user_lastname + ', ' + tu.user_firstname							[user_name]


from tbCRM_CallHistory							tcch	WITH (NOLOCK)

	inner join tbCRM_Call						tcc		WITH (NOLOCK)
	on	tcc.comp_id = tcch.comp_id
	AND tcc.call_id = tcch.call_id

	left join tbCRM_CallStatus					tccs	WITH (NOLOCK)
	on	tccs.comp_id	= tcch.comp_id
	AND tccs.callst_id	= tcch.callst_id

	left join tbCRM_Case						tcc2	WITH (NOLOCK)
	on	tcc2.comp_id = tcch.comp_id
	AND tcc2.case_id = tcch.case_id

	left join tbCRM_Task						tct		WITH (NOLOCK)
	on	tct.task_id = tcch.task_id
	AND tct.comp_id = tcch.comp_id

	left join tbCRM_CallType					tcct	WITH (NOLOCK)
	on tcct.comp_id = tcch.comp_id
	and tcct.callt_id = tcch.callt_id

	LEFT JOIN tbUser							tu		WITH (NOLOCK)
	ON tu.[user_id] = tcch.[user_id]


where	tcch.comp_id = @comp_id
and		tcch.call_id = @call_id
GO







