-- Reporte de Llamadas
------------------------


CREATE PROCEDURE [dbo].[spCRM_Call_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@call_id			INT,
		@intBranch4Lang		int


)
AS
SET NOCOUNT ON




BEGIN

set nocount on
set dateformat 'ymd'

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



--------------------------------------------------------
-------------parametros de prueba-----------------------
--------------------------------------------------------
/*
DECLARE		@comp_id			int,
			@lang_id			int,
			@page_id			int,

			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,

			@call_id			INT



SELECT		@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10090,

			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 1,

			@call_id			= 8


DROP TABLE #tmpcall, #tmpcase,#tmptask
*/
--------------------------------------------------------
--------------------------------------------------------
--------------------------------------------------------

DECLARE @fun_id INT, @ltotal decimal(19,4), @lcurr_desc nvarchar(50)

SET @fun_id = 1

  DECLARE   @message_task VARCHAR(100),
			@message_task_null VARCHAR(100),
			@message_call VARCHAR(100),
			@message_case VARCHAR(100),
			@message_case_null VARCHAR(100)

 SELECT @message_case = utexts_desc		 FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 156 AND tut.lang_id = @lang_id
 SELECT @message_task = utexts_desc		 FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 155 AND tut.lang_id = @lang_id
 SELECT @message_task_null = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 157 AND tut.lang_id = @lang_id
 SELECT @message_call = utexts_desc		 FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 152 AND tut.lang_id = @lang_id
 SELECT @message_case_null = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 158 AND tut.lang_id = @lang_id



-------------------------
-- sacar total final.
-------------------------
select @ltotal =

(SELECT isnull(SUM(ISNULL(TCC.call_price,0)),0)

FROM tbCRM_Call tcc

left join tbCRM_CallStatus			tccs
on  tccs.comp_id	= tcc.comp_id
and tccs.callst_id  = tcc.callst_id

where 	tcc.comp_id			= @comp_id
AND		tcc.call_id			= @call_id)

+
(SELECT isnull(SUM(ISNULL(tcc2.case_price,0)),0)

	FROM tbCRM_Call tcc

	left join tbCRM_CallStatus					tccs
	on  tccs.comp_id	= tcc.comp_id
	and tccs.callst_id  = tcc.callst_id

	inner join tbCRM_Case tcc2
	on tcc2.comp_id = tcc.comp_id
	AND tcc2.case_id = tcc.case_id

	where 	tcc.comp_id			= @comp_id
	AND		tcc.call_id			= @call_id )

+

(SELECT isnull(SUM(ISNULL(tct.task_price,0)),0)

FROM tbCRM_Call tcc

left join tbCRM_CallStatus					tccs
on  tccs.comp_id	= tcc.comp_id
and tccs.callst_id  = tcc.callst_id

inner join tbCRM_Task						tct
on  tct.comp_id	= tcc.comp_id
AND tct.task_id = tcc.task_id


where 	tcc.comp_id			= @comp_id
AND		tcc.call_id			= @call_id )



select @lcurr_desc = ( SELECT tc.curr_desc FROM tbBranch tb

						INNER JOIN tbsysCurrency tc
						ON TC.curr_id = TB.curr_id

						WHERE tb.bra_id = @bra_id )

--------------------
-- select principal
--------------------



	SELECT  tcc.call_description,
			tccs.callst_desc,
			tcc.call_date4Begin,
			tu.user_lastname + ', ' + tu.user_firstname			[User_name],
			tcc.call_Note1,
			tcc.call_Note2,
			isnull(tcc.call_price,0)							[call_price],
			isnull(@ltotal,0)									[total],
			@lcurr_desc											[curr_desc],
			isnull(tcct.callt_desc,'')							[call_type],
			CONVERT(VARCHAR,tcc.call_id)						[call_id]

	into #tmpcall
	FROM	tbCRM_Call										tcc


			left join tbCRM_CallStatus						tccs
			on  tccs.comp_id	= tcc.comp_id
			and tccs.callst_id  = tcc.callst_id

			LEFT JOIN	tbUser								tu
			ON  tu.[user_id]	= tcc.[user_id]

			INNER JOIN	tbCRM_TypesByProfile				tctbp
			on  tctbp.comp_id	= @comp_id
			and tctbp.bra_id	= @bra_id
			and tctbp.prof_id	= @prof_id
			and tctbp.crm_type	= 3	--call

			left join tbCRM_CallType						tcct
			on  tcct.comp_id	= tcc.comp_id
			and tcct.callt_id	= tcc.callt_id



	WHERE	tcc.comp_id			= @comp_id
	AND		tcc.call_id			= @call_id


 IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmpcall

		END
	  ELSE
			SELECT @message_call [call_description],
					' ' [callst_desc],
					' ' [call_date4Begin],
					' ' [User_name],
					' ' [call_Note1],
					' ' [call_Note2],
					' ' [call_price]

----------------------------------------------------
--params--
----------------------------------------------------


exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id
--exec [spReports_getData] 1, 2,	10005

/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/

SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1912
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

		CASE @call_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(select tcc.call_description
					 from tbCRM_Call tcc
				where   tcc.comp_id    = @comp_id
				And   tcc.call_id    = @call_id)
		End [params2]

----------------------------------------------------



------------------------------------------------------------
---Subreporte - Pertenece a tal tarea.
------------------------------------------------------------

select  @message_task [message],tct.task_desc [task_desc],isnull(tct.task_price,0) [task_price]

into #tmptask
from tbCRM_Call								tcc


left join tbCRM_CallStatus					tccs
on  tccs.comp_id	= tcc.comp_id
and tccs.callst_id  = tcc.callst_id

inner join tbCRM_Task						tct
on  tct.comp_id	= tcc.comp_id
AND tct.task_id = tcc.task_id


where 	tcc.comp_id			= @comp_id
AND		tcc.call_id			= @call_id



 IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmptask

		END
	  ELSE
			SELECT @message_task			[message],
				   @message_task_null		[task_desc],
					' ' [task_price]


------------------------------------------------------------------------------------------------------------------------


------------------------------------------------------------
---Subreporte - Pertenece a tal caso.
------------------------------------------------------------

select  @message_case [message],tcc2.case_desc [case_desc],isnull(tcc2.case_price,0) [case_price]

into #tmpcase
from tbCRM_Call								tcc


left join tbCRM_CallStatus					tccs
on  tccs.comp_id	= tcc.comp_id
and tccs.callst_id  = tcc.callst_id

inner join tbCRM_Case tcc2
on tcc2.comp_id = tcc.comp_id
AND tcc2.case_id = tcc.case_id

where 	tcc.comp_id			= @comp_id
AND		tcc.call_id			= @call_id



 IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmpcase

		END
	  ELSE
			SELECT @message_case			[message],
			       @message_case_null		[case_desc],
				   ''[case_price]











