CREATE PROCEDURE [dbo].[spCRM_Call_insertData]
(
	@comp_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@lang_id				INT,

	@call_date4Begin		DATETIME,
	@call_Hour4Begin		VARCHAR(2),
	@call_Minute4Begin		VARCHAR(2),
	@call_howLong			INT,
	@call_description		NVARCHAR(4000),
	@call_Note1				NVARCHAR(4000),
	@call_Note2				NVARCHAR(4000),
	@case_id				INT,
	@task_id				INT,
	@soh_Bra_id				INT,
	@soh_Soh_id				INT,
	@contact_id				INT,
	@cust_id				INT,
	@callst_id				INT,
	@call_price				DECIMAL(19,4),
	@curr_id				INT,
	@chkCA					BIT,
	@callt_id				INT,
	@call_emailAdditional	VARCHAR(250),
	@supp_id				INT,
	@call_nextReviewdate	DATETIME,
	@pro_id					INT,
	@return_value			INT OUTPUT
)
AS

BEGIN


	SET NOCOUNT ON

	IF @cust_id = -1
		BEGIN
			SET @cust_id = NULL
		END
	IF @contact_id = -1
		BEGIN
			SET @contact_id = NULL
		END
	IF @supp_id = -1
		BEGIN
			SET @supp_id = NULL
		END
	IF @pro_id = -1
		BEGIN
			SET @pro_id = NULL
		END

	insert into tbCRM_Call
	(
		comp_id,
		-- call_id -- this column value is auto-generated,
		bra_id,
		call_date4Begin,
		call_howLong,
		call_description,
		call_Note1,
		call_Note2,
		case_id,
		task_id,
		soh_Bra_id,
		soh_Soh_id,
		contact_id,
		cust_id,
		[user_id],
		callst_id,
		call_price,
		curr_id,
		callt_id,
		call_emailAdditional,
		supp_id,
		call_nextReviewdate,
		pro_id
	)
	VALUES
	(
		@comp_id,
		@bra_id,
		dateadd(mi,convert(int,@call_Minute4Begin),DATEADD(hh,convert(int,@call_Hour4Begin),@call_date4Begin)),
		@call_howLong,
		@call_description,
		@call_Note1,
		@call_Note2,
		@case_id,
		@task_id,
		@soh_Bra_id,
		@soh_Soh_id,
		@contact_id,
		@cust_id,
		@user_id,
		@callst_id,
		@call_price,
		@curr_id,
		@callt_id,
		@call_emailAdditional,
		@supp_id,
		@call_nextReviewdate,
		@pro_id
	)

	SET @return_value = @@IDENTITY


declare
	@message			 varchar(4000),
	@subject			 varchar(4000),
	@body				 varchar(4000),
	@mail				 varchar(8000),
	@user_origen_name	 varchar(400),
	@user_mail_origin	 varchar(400),
	@optionid			 int,
	@desc				 varchar(2000)



--Datos del Usuario de Origen
select
	@user_origen_name = (tu.user_lastname + ',' + tu.user_firstname),
	@user_mail_origin = tu.user_email
from tbUser tu where tu.[user_id] = @user_id
set @optionid = 4052



-- ---------------------------------------
-- Textos para armado del mail completo
DECLARE
	@lCallSubject	VARCHAR(100),
	@CallDesc		VARCHAR(100),
	@CallResolution	VARCHAR(100),
	@date4begin		VARCHAR(100),
	@date2end		VARCHAR(100),
	@callduration	VARCHAR(100),
	@notes			VARCHAR(100)


--ASUNTO
select @lCallSubject	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300626
--DESCRIPCION
select @CallDesc		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300627
--Fecha Inicio
select @date4begin		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300629
--Fecha Fin
select @date2end		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300630
--Duración de la llamada
select @callduration	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300633
--NOTAS
select @notes			= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300635
-- ---------------------------------------



--Armado de Subject y Body

select @desc = tswn.word_desc
  from tbSysWordsNew tswn where tswn.lang_id = @lang_id and tswn.wordsi_id = @optionid



/*************************************************************************************/
/*En caso de poseer un TEXTO EN LA HEADER/FOOTER propia, utilizamos ese, sino        */
/*utilizamos el valor genérico de CRM de la UniqueTexts          */
/*************************************************************************************/

	IF EXISTS (SELECT 1
	           FROM tbCRM_CallMailHeaderFooter					tccmhf		WITH (NOLOCK)
	           WHERE	tccmhf.comp_id					= @comp_id		AND
						tccmhf.callt_id					= @callt_id		AND
						tccmhf.callst_id				= @callst_id	AND
						ISNULL(tccmhf.crmhf_Subject,'')	<> '')
		BEGIN
			SELECT
				@subject = tccmhf.crmhf_Subject
			  FROM tbCRM_CallMailHeaderFooter	tccmhf
			WHERE tccmhf.comp_id	= @comp_id	AND
				  tccmhf.callt_id	= @callt_id AND
				  tccmhf.callst_id	= @callst_id
		END
	ELSE
		BEGIN
			SELECT
					@subject		= tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 984

			set @subject = @subject + @desc

		END


select @message = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 985

select @body = tut.utexts_desc + ' ' + CONVERT(VARCHAR,@return_value)
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 986



set @mail = @desc								+ ' ' +
			@message							+ ' ' +
			@user_origen_name					+ ' ' +
			@body								+ ' ' +
			@CallDesc							+ ' ' +
			@call_description					+ ' ' +
			@notes								+ ' ' +
			@call_Note1							+ ' ' +
			@call_Note2							+ ' ' +
			@date4begin							+ ' ' +
			CONVERT(VARCHAR,@call_date4Begin)	+ ' ' +
			@callduration						+ ' ' +
			CONVERT(VARCHAR,@call_howLong)



-- ---------------------------------------------------------------
-- ARMADO DEL HTML PARA EL MAIL
-- ---------------------------------------------------------------
--ARMAMOS HEADER Y FOOTER EN CASO DE QUE HAYA VALORES EN LAS TABLAS

DECLARE @MailTableHeader AS NVARCHAR(MAX),
		@HeaderText		 AS NVARCHAR(MAX),
		@FooterText		 AS NVARCHAR(MAX)

SET @HeaderText = ''
SET @FooterText = ''

SELECT
	@HeaderText = tccmhf.htmlHeader,
	@FooterText = tccmhf.htmlFooter
FROM tbCRM_CallMailHeaderFooter tccmhf
WHERE	tccmhf.comp_id	 = @comp_id  AND
		tccmhf.callt_id	 = @callt_id AND
		tccmhf.callst_id = @callst_id

IF NOT LEN(@HeaderText) > 0
	SET @HeaderText = ''
IF NOT LEN(@FooterText) > 0
	SET @FooterText = ''

-- ---------------------------------------------------------------
-- ESTADO
DECLARE @Status			AS VARCHAR(MAX)
DECLARE @Call_Status	AS VARCHAR(MAX)

	SELECT @Status = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30022

	SELECT @Call_Status = tccs.callst_desc FROM tbCRM_CallStatus tccs WHERE tccs.comp_id = @comp_id AND tccs.callst_id = @callst_id

--variables para el formateo del html email
	DECLARE	@MailTable							NVARCHAR(MAX),
			@MailEndTable						NVARCHAR(MAX),
			@Mailsubject						NVARCHAR(MAX),
			@MailbodyHeader						NVARCHAR(MAX),
			@Mailbody							NVARCHAR(MAX),
			@MailbodyFooter						NVARCHAR(MAX),
			@MailImageSRC						NVARCHAR(MAX)


SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
				 'cellpadding="1" cellspacing="1" border="1">'

SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
					  '<b>' + @subject + @desc + '</b><br /><br /><br />'


SET @Mailbody = ''
SET @MailBody =

	'<tr><td align="center">' +
		@desc + ' ' + @message + ' ' +  @user_origen_name  + ' ' +
	'</td><tr><td align="center">' +
		@body + ' ' +
	'</td></tr><td align="center">' + ' ' +
		@CallDesc + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@call_description) + ' ' +
	'</td></tr><td align="center">' +
		@Status + ' ' + @Call_Status + ' ' +
	'</td><tr><td align="center">' +
		@notes + ' ' + 	'<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@call_Note1) + ' <BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@call_Note2) + ' ' +
	'</td><tr><td align="center">' +
		@date4begin + ' ' + CONVERT(VARCHAR,@call_date4Begin) + ' ' +
	'</td><tr><td align="center">' +
		@callduration + ' ' + CONVERT(VARCHAR,@call_howLong) + ' ' +
	'</td></tr>'




SET @MailEndTable = + '</table>'

SET @MailbodyFooter = '</div>'






SET @Mailbody = @HeaderText + ' ' + @MailTable + ' ' + @Mailbody + @MailEndTable + ' ' + @FooterText + ' ' + @MailbodyFooter
--SELECT @MailTable
--SELECT @Mailbody
--SELECT @MailEndTable
--SELECT @MailImageSRC
-- ---------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Envio del Mail
-- -----------------------------------------------------------------------------
	DECLARE @strMailString	AS NVARCHAR(MAX)
	DECLARE @strMail		AS NVARCHAR(MAX)
	DECLARE @strMailCC		AS NVARCHAR(MAX)
	DECLARE @strMailCCO		AS NVARCHAR(MAX)
	DECLARE @strMailFrom    AS NVARCHAR(MAX)
	SELECT  @strMailString	= dbo.fnCRM_GetCustomerEmailByCallType(@comp_id, @cust_id, @callt_id, @callst_id, @return_value, @user_id)
	SELECT  @strMail		= dbo.fnSplitPosition(@strMailString, '|',1)
	SELECT  @strMailCC		= dbo.fnSplitPosition(@strMailString, '|',2)
	SELECT  @strMailCCO		= dbo.fnSplitPosition(@strMailString, '|',3)
	SELECT  @strMailFrom	= dbo.fnSplitPosition(@strMailString, '|',4)

	---- Mail al Usuario Asignado
	--exec spSystem_sendEMail
	--						@compId				= @comp_id,
	--						@precipients		= @user_mail_origin,
	--						@pcopy_recipients	= null,
	--						@psubject			= @subject,
	--						@pbody_format		= 'HTML',
	--						@pbody				= @MailBody,
	--						@pfile_attachments	= null,
	--						@pReplyTo			= @strMailFrom,
	--						@pblind_copy_recipients='',
	--						@pUser_Id			= @user_id

	-- Mail de Aviso a Clientes, Contactos, Adicionales, Etc.
	exec spSystem_sendEMail
							@compId					= @comp_id,
							@precipients			= @strMail,
							@pcopy_recipients		= @strMailCC,
							@psubject				= @subject,
							@pbody_format			= 'HTML',
							@pbody					= @Mailbody,
							@pfile_attachments		= null,
							@pReplyTo				= @strMailFrom,
							@pblind_copy_recipients	= @strMailCCO,
							@pUser_Id				= @user_id
	-- -----------------------------------------------------------------------------



insert into tbSecurityLog
(
	comp_id,
	bra_id,
	user_id,
	seclog_obs_1,
	seclog_obs_2,
	seclog_image,
	seclog_obs_3,
	seclog_obs_4,
	seclog_cd,
	aut_id,
	sysCode_id,
	menu_id,
	menu_ts,
	request_ip,
	request_name,
	aure_isok,
	aure_user_id,
	seclog_pageHTML,
	prof_id,
	aure_cd,
	aure_id,
	seclog_id1,
	seclog_id2,
	seclog_id3
)
VALUES
(
	@comp_id,
	@bra_id,
	@user_id,
	@mail,
	NULL,
	NULL,
	NULL,
	NULL,
	getdate(),
	NULL,
	1400,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	@prof_id,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL
)

-- ----------------------------------------------------------
-- ACTUALIZAMOS SALE ORDER
-- ----------------------------------------------------------
	if (@chkCA = 'False')
		begin
			declare
					@soss_id		INT
			select
					@soss_id		= ssos_id
			from tbSaleOrderHeader				tsoh
			where	tsoh.comp_id	= @comp_id
			and		tsoh.bra_id		= @bra_id
			and		tsoh.soh_id		= @soh_soh_id

			if (@soss_id = 10)
				begin
					update tbSaleOrderHeader
					SET
							ssos_id		= 20
					where	comp_id		= @comp_id
					and		bra_id		= @bra_id
					and		soh_id		= @soh_soh_id
				end
		end
-- ----------------------------------------------------------


END
GO



CREATE PROCEDURE [dbo].[spCRM_Call_SendNotifications]

AS
	SET NOCOUNT ON

	BEGIN
		/*
		DECLARE
			@lang_id	INT

		SELECT
			@lang_id	= 2

		*/


			-- declareción de variables para obtener los datos del cursor
			DECLARE
				@comp_id				INT,
				@call_id				INT,
				@bra_id					INT,
				@call_date4Begin		DATETIME,
				@call_howLong			INT,
				@call_description		VARCHAR(MAX),
				@call_Note1				VARCHAR(MAX),
				@call_Note2				VARCHAR(MAX),
				@cust_id				INT,
				@user_id				INT,
				@callst_id				INT,
				@callt_id				INT,
				@call_advertiseDate		DATETIME,
				@call_advertiseCount	INT,
				@call_advertiseLastDate	DATETIME,
				@bisIsAdvertiseLastDate BIT



			DECLARE cursor_Call CURSOR FOR

				SELECT
					tcc.comp_id,
					tcc.call_id,
					tcc.bra_id,
					tcc.call_date4Begin,
					tcc.call_howLong,
					tcc.call_description,
					tcc.call_Note1,
					tcc.call_Note2,
					tcc.cust_id,
					tcc.[user_id],
					tcc.callst_id,
					tcc.callt_id,
					tcc.call_advertiseDate,
					tcc.call_advertiseCount,
					tcc.call_advertiseLastDate,
					CASE
						WHEN tcc.call_advertiseDate IS NULL THEN	'False'
						ELSE										'True'
					END
				FROM tbCRM_Call tcc
				INNER JOIN tbBranch tb
					ON	tb.comp_id	= tcc.comp_id AND
						tb.bra_id	= tcc.bra_id
				INNER JOIN tbCRM_CallStatus tcts		WITH (NOLOCK)
					ON	tcts.comp_id				= tcc.comp_id	AND
						tcts.callst_id				= tcc.callst_id	AND
						tcts.callst_isFinalStatus	= 'False'
				WHERE	tcc.call_advertiseDate IS NOT NULL
							OR
						(	tb.bra_processingDate = tcc.call_nextReviewdate AND
						   (tcc.call_nextReviewdateLastMailDate IS NULL
								OR
							tcc.call_nextReviewdateLastMailDate < tcc.call_nextReviewdate
						   )
						)
				--where tcc.call_id = 319

			OPEN	cursor_Call



			-- lectura anticipada del cursor
			FETCH	cursor_Call
			INTO
				@comp_id,
				@call_id,
				@bra_id,
				@call_date4Begin,
				@call_howLong,
				@call_description,
				@call_Note1,
				@call_Note2,
				@cust_id,
				@user_id,
				@callst_id,
				@callt_id,
				@call_advertiseDate,
				@call_advertiseCount,
				@call_advertiseLastDate,
				@bisIsAdvertiseLastDate



			-- se recorre el cursor hasta el fin del mismo
			WHILE   @@FETCH_STATUS = 0
			BEGIN

				--ACA PROCESAMOS Y AVISAMOS

					--SI EL COUNT ES DISTINTO DE NULL, SUMAMOS 1 Y SETEAMOS EN NULL
					--LA FECHA DE AVISO SI ES MENOR O IGUAL A LA FECHA ACTUAL

					IF (@call_advertiseCount IS NOT NULL) AND (@call_advertiseDate <= GETDATE())

						BEGIN
							--select 1

							DECLARE @lang_id	INT
							SELECT  @lang_id = tb.lang_id FROM tbBranch tb WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id

							IF @bisIsAdvertiseLastDate = 'True'
								BEGIN

									UPDATE tbCRM_Call
									SET
										call_advertiseDate	= NULL,
										call_advertiseCount = call_advertiseCount + 1
									WHERE	comp_id			= @comp_id AND
											call_id			= @call_id

								END


							--COLOR DEL ENCABEZADO
							-- VERDE	= 1 Aviso			--> "Recordatorio"
							-- AMARILLO = 2 Avisos			--> "Recordatorio"
							-- ROJO		= 3 Avisos o más	--> "Advertencia"
							DECLARE
								@HeaderColor	VARCHAR(20),
								@HeaderMessage	VARCHAR(100)
								SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60000

								SET @HeaderColor = '#3ADF00'


								IF (@call_advertiseCount + 1) = 1
									BEGIN
										SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60000
										SET @HeaderColor = '#3ADF00'
									END

								IF (@call_advertiseCount + 1) = 2
									BEGIN
										SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60000
										SET @HeaderColor = '#F4FA58'
									END

								IF (@call_advertiseCount + 1) > 2
									BEGIN
										SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60001
										SET @HeaderColor = '#DF0101'
									END

							--ENVIAMOS MAILS
							-- --------------------------------------------------------------------------------------------------------------------------------
							-- Envio del Mail
							-- --------------------------------------------------------------------------------------------------------------------------------

								declare
									@message			 varchar(4000),
									@subject			 varchar(4000),
									@body				 varchar(4000),
									@mail				 varchar(8000),
									@user_origen_name	 varchar(400),
									@user_mail_origin	 varchar(400),
									@optionid			 int,
									@desc				 varchar(2000)



								--Datos del Usuario de Origen
								select
									@user_origen_name = (tu.user_lastname + ',' + tu.user_firstname),
									@user_mail_origin = tu.user_email
								from tbUser tu where tu.[user_id] = @user_id
								set @optionid = 4052



								-- ---------------------------------------
								-- Textos para armado del mail completo
								DECLARE
									@lCallSubject	VARCHAR(100),
									@CallDesc		VARCHAR(100),
									@CallResolution	VARCHAR(100),
									@date4begin		VARCHAR(100),
									@date2end		VARCHAR(100),
									@callduration	VARCHAR(100),
									@notes			VARCHAR(100)


								--ASUNTO
								select @lCallSubject	= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300626
								--DESCRIPCION
								select @CallDesc		= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300627
								--Fecha Inicio
								select @date4begin		= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300629
								--Fecha Fin
								select @date2end		= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300630
								--Duración de la llamada
								select @callduration	= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300633
								--NOTAS
								select @notes			= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300635
								-- ---------------------------------------



								--Armado de Subject y Body

								select @desc = tswn.word_desc
								  from tbSysWordsNew tswn where tswn.lang_id = @lang_id and tswn.wordsi_id = @optionid



								/*************************************************************************************/
								/*En caso de poseer un TEXTO EN LA HEADER/FOOTER propia, utilizamos ese, sino        */
								/*utilizamos el valor genérico de CRM de la UniqueTexts                              */
								/*************************************************************************************/

									IF EXISTS (SELECT 1
											   FROM tbCRM_CallMailHeaderFooter					tccmhf		WITH (NOLOCK)
											   WHERE	tccmhf.comp_id					= @comp_id		AND
														tccmhf.callt_id					= @callt_id		AND
														tccmhf.callst_id				= @callst_id	AND
														ISNULL(tccmhf.crmhf_Subject,'')	<> '')
										BEGIN
											SELECT
												@subject = tccmhf.crmhf_Subject
											  FROM tbCRM_CallMailHeaderFooter	tccmhf
											WHERE tccmhf.comp_id	= @comp_id	AND
												  tccmhf.callt_id	= @callt_id AND
												  tccmhf.callst_id	= @callst_id
										END
									ELSE
										BEGIN
											SELECT
													@subject		= tut.utexts_desc
											FROM tbsysUniqueTexts				tut
											WHERE	tut.lang_id		= @lang_id	AND
													tut.utexts_id	= 984

											set @subject = @subject + @desc

										END


								select @message = tut.utexts_desc
								from tbsysUniqueTexts tut
								where tut.lang_id = @lang_id
								and tut.utexts_id = 985

								select @body = tut.utexts_desc + ' ' + CONVERT(VARCHAR,@call_id)
								from tbsysUniqueTexts tut
								where tut.lang_id = @lang_id
								and tut.utexts_id = 986



								set @mail = @desc								+ ' ' +
											@message							+ ' ' +
											@user_origen_name					+ ' ' +
											@body								+ ' ' +
											@CallDesc							+ ' ' +
											@call_description					+ ' ' +
											@notes								+ ' ' +
											@call_Note1							+ ' ' +
											@call_Note2							+ ' ' +
											@date4begin							+ ' ' +
											CONVERT(VARCHAR,@call_date4Begin)	+ ' ' +
											@callduration						+ ' ' +
											CONVERT(VARCHAR,@call_howLong)



								-- ---------------------------------------------------------------
								-- ARMADO DEL HTML PARA EL MAIL
								-- ---------------------------------------------------------------
								--ARMAMOS HEADER Y FOOTER EN CASO DE QUE HAYA VALORES EN LAS TABLAS

								DECLARE @MailTableHeader AS NVARCHAR(MAX),
										@HeaderText		 AS NVARCHAR(MAX),
										@FooterText		 AS NVARCHAR(MAX)

								SET @HeaderText = ''
								SET @FooterText = ''

								SELECT
									@HeaderText = tccmhf.htmlHeader,
									@FooterText = tccmhf.htmlFooter
								FROM tbCRM_CallMailHeaderFooter tccmhf
								WHERE	tccmhf.comp_id	 = @comp_id  AND
										tccmhf.callt_id	 = @callt_id AND
										tccmhf.callst_id = @callst_id

								IF NOT LEN(@HeaderText) > 0
									SET @HeaderText = ''
								IF NOT LEN(@FooterText) > 0
									SET @FooterText = ''

								-- ---------------------------------------------------------------
								-- ESTADO
								DECLARE @Status			AS VARCHAR(MAX)
								DECLARE @Call_Status	AS VARCHAR(MAX)

									SELECT @Status = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30022

									SELECT @Call_Status = tccs.callst_desc FROM tbCRM_CallStatus tccs WHERE tccs.comp_id = @comp_id AND tccs.callst_id = @callst_id

								--variables para el formateo del html email
									DECLARE	@MailTable							NVARCHAR(MAX),
											@MailEndTable						NVARCHAR(MAX),
											@Mailsubject						NVARCHAR(MAX),
											@MailbodyHeader						NVARCHAR(MAX),
											@Mailbody							NVARCHAR(MAX),
											@MailbodyFooter						NVARCHAR(MAX),
											@MailImageSRC						NVARCHAR(MAX)


								SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

								SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
												 'cellpadding="1" cellspacing="1" border="3">'

								SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
													  '<b>' + @subject + @desc + '</b><br /><br /><br />'


								SET @Mailbody = ''
								SET @MailBody =

									'
									<tr>
										<td align="center" bgcolor="' + @HeaderColor +  '">' +
											@HeaderMessage + ' ' + CONVERT(VARCHAR,@call_advertiseCount + 1) + ' ' +
										'</td>
									</tr>
									<tr><td align="center">' +
										@desc + ' ' + @message + ' ' +  @user_origen_name  + ' ' +
									'</td><tr><td align="center">' +
										@body + ' ' +
									'</td></tr><td align="center">' + ' ' +
										@CallDesc + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@call_description) + ' ' +
									'</td></tr><td align="center">' +
										@Status + ' ' + @Call_Status + ' ' +
									'</td><tr><td align="center">' +
										@notes + ' ' + 	'<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@call_Note1) + ' <BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@call_Note2) + ' ' +
									'</td><tr><td align="center">' +
										@date4begin + ' ' + CONVERT(VARCHAR,@call_date4Begin) + ' ' +
									'</td><tr><td align="center">' +
										@callduration + ' ' + CONVERT(VARCHAR,@call_howLong) + ' ' +
									'</td></tr>'




								SET @MailEndTable = + '</table>'

								SET @MailbodyFooter = '</div>'






								SET @Mailbody = @HeaderText + ' ' + @MailTable + ' ' + @Mailbody + @MailEndTable + ' ' + @FooterText + ' ' + @MailbodyFooter
								--SELECT @MailTable
								--SELECT @Mailbody
								--SELECT @MailEndTable
								--SELECT @MailImageSRC
								-- ---------------------------------------------------------------

								-- -----------------------------------------------------------------------------
								-- Envio del Mail
								-- -----------------------------------------------------------------------------
									DECLARE @strMailString	AS NVARCHAR(MAX)
									DECLARE @strMail		AS NVARCHAR(MAX)
									DECLARE @strMailCC		AS NVARCHAR(MAX)
									DECLARE @strMailCCO		AS NVARCHAR(MAX)
									DECLARE @strMailFrom    AS NVARCHAR(MAX)
									SELECT  @strMailString	= dbo.fnCRM_GetCustomerEmailByCallType(@comp_id, @cust_id, @callt_id, @callst_id, @call_id, @user_id)
									SELECT  @strMail		= dbo.fnSplitPosition(@strMailString, '|',1)
									SELECT  @strMailCC		= dbo.fnSplitPosition(@strMailString, '|',2)
									SELECT  @strMailCCO		= dbo.fnSplitPosition(@strMailString, '|',3)
									SELECT  @strMailFrom	= dbo.fnSplitPosition(@strMailString, '|',4)

									-- Mail al Usuario Asignado

									exec spSystem_sendEMail
															@compId				= @comp_id,
															@precipients		= @user_mail_origin,
															@pcopy_recipients	= null,
															@psubject			= @subject,
															@pbody_format		= 'HTML',
															@pbody				= @MailBody,
															@pfile_attachments	= null,
															@pReplyTo			= @strMailFrom,
															@pblind_copy_recipients='',
															@pUser_Id			= @user_id

							-- --------------------------------------------------------------------------------------------------------------------------------
							-- --------------------------------------------------------------------------------------------------------------------------------


							--ACTUALIZAMOS LA FECHA DE AVISO
							UPDATE tbCRM_Call
							SET
								call_advertiseLastDate	= GETDATE(),
								call_nextReviewdateLastMailDate =		CASE
																			WHEN call_nextReviewdate IS NULL THEN NULL
																			WHEN call_nextReviewdate <= GETDATE() THEN GETDATE()
																			ELSE call_nextReviewdate
																		END
							WHERE	comp_id				= @comp_id AND
									call_id				= @call_id


							DECLARE @strURL AS NVARCHAR(600)
							SET @strURL = 'wfmCRM_CallDetail.aspx?&BraId='	+ CONVERT(VARCHAR,@bra_id)	+
																'&CallId='	+ CONVERT(VARCHAR,@call_id) +
																'&Action='  + 'U'						+ '&'

							--GRABAMOS WORKFLOW
							INSERT INTO tbWorkflow
							(
								comp_id,
								bra_id,
								wf_type,
								wf_isProcessed,
								user_id_from,
								user_id_assigned,
								user_id_processed,
								prof_id_assigned,
								wf_dateOfAssigned,
								wf_dateOfProcessing,
								wf_link,
								wf_message1,
								wf_message2,
								wf_htmlTop,
								wf_htmlBody,
								wf_html_Bottom,
								call_id
							)
							VALUES
							(
								@comp_id,
								@bra_id,
								777,
								'False',
								NULL,
								@user_id, --@intUser4Notify,
								NULL,
								NULL,
								GETDATE(),
								NULL,
								@strURL,
								@subject,
								'',
								@MailBody, --@strRet_ErrorDescription,
								'',
								'',
								@call_id
							)

						END


				-- próxima lectura del cursor
				FETCH	cursor_Call
				INTO
					@comp_id,
					@call_id,
					@bra_id,
					@call_date4Begin,
					@call_howLong,
					@call_description,
					@call_Note1,
					@call_Note2,
					@cust_id,
					@user_id,
					@callst_id,
					@callt_id,
					@call_advertiseDate,
					@call_advertiseCount,
					@call_advertiseLastDate,
					@bisIsAdvertiseLastDate


			END

			CLOSE cursor_Call
			DEALLOCATE cursor_Call

	END
GO






CREATE PROCEDURE [dbo].[spCRM_Call_updateData]
(
	@comp_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@lang_id				INT,

	@call_id				INT,
	@call_date4Begin		DATETIME,
	@call_Hour4Begin		VARCHAR(2),
	@call_Minute4Begin		VARCHAR(2),
	@call_howLong			INT,
	@call_description		NVARCHAR(4000),
	@call_Note1				NVARCHAR(4000),
	@call_Note2				NVARCHAR(4000),
	@case_id				INT,
	@task_id				INT,
	@soh_Bra_id				INT,
	@soh_Soh_id				INT,
	@contact_id				INT,
	@cust_id				INT,
	@callst_id				INT,
	@call_price				DECIMAL(19,4),
	@curr_id				INT,
	@chkCA					BIT,
	@callt_id				INT,
	@call_emailAdditional	VARCHAR(250),
	@supp_id				INT,
	@call_nextReviewdate	DATETIME,
	@pro_id					INT
)
AS


/*

DECLARE	@comp_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@lang_id			INT,

		@call_id			INT,
		@call_date4Begin	datetime,
		@call_Hour4Begin	varchar(2),
		@call_Minute4Begin	varchar(2),
		@call_howLong		int,
		@call_description	nvarchar(4000),
		@call_Note1			nvarchar(4000),
		@call_Note2			nvarchar(4000),
		@case_id			int,
		@task_id			int,
		@soh_Bra_id			int,
		@soh_Soh_id			int,
		@contact_id			int,
		@cust_id			int,
		@callst_id			int,
		@call_price			decimal(19,4),
		@curr_id			int,
		@chkCA				bit,
		@callt_id			INT,
		@call_emailAdditional	VARCHAR(250)


SELECT 	@comp_id			=1 ,
		@bra_id				=1,
		@prof_id			=1,
		@user_id			=1,
		@lang_id			=2,

		@call_id			=294,
		@call_date4Begin	='11/12/2013',
		@call_Hour4Begin	='14',
		@call_Minute4Begin	='25',
		@call_howLong		=1,
		@call_description	='aaaaaaaaaaaaa',
		@call_Note1			='asddsasad',
		@call_Note2			='adassdasadsd',
		@case_id			=NULL,
		@task_id			=NULL,
		@soh_Bra_id			=0,
		@soh_Soh_id			=0,
		@contact_id			=-1,
		@cust_id			=-1,
		@callst_id			=8,
		@call_price			=100,
		@curr_id			=1,
		@chkCA				=1,
		@callt_id			=5,
		@call_emailAdditional	=''


*/



SET NOCOUNT ON

	IF @cust_id = -1
		BEGIN
			SET @cust_id = NULL
		END
	IF @contact_id = -1
		BEGIN
			SET @contact_id = NULL
		END
	IF @supp_id = -1
		BEGIN
			SET @supp_id = NULL
		END
	IF @pro_id	= -1
		BEGIN
			SET @pro_id = NULL
		END

declare
	@hour	INT,
	@minute	INT

set @hour = substring(@call_Hour4Begin,0,2)

BEGIN

	update tbCRM_Call
	SET
		bra_id				= @bra_id,
		call_date4Begin		= dateadd(mi,convert(int,@call_Minute4Begin),DATEADD(hh,convert(int,@call_Hour4Begin),@call_date4Begin)),
		call_howLong		= @call_howLong,
		call_description	= @call_description,
		call_Note1			= @call_Note1,
		call_Note2			= @call_Note2,
		case_id				= @case_id,
		task_id				= @task_id,
		soh_Bra_id			= @soh_Bra_id,
		soh_Soh_id			= @soh_Soh_id,
		contact_id			= @contact_id,
		cust_id				= @cust_id,
		callst_id			= @callst_id,
		call_price			= @call_price,
		curr_id				= @curr_id,
		callt_id			= @callt_id,
		call_emailAdditional = @call_emailAdditional,
		supp_id				= @supp_id,
		call_nextReviewdate = @call_nextReviewdate,
		pro_id				= @pro_id

	WHERE	comp_id			= @comp_id
	AND		call_id			= @call_id

declare
	@msg	nvarchar(1000)

select @msg = (tut.utexts_desc + ' ' + convert(varchar,@call_id))
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 989

--STL
-- ---------------------------------------
-- Textos para armado del mail completo
DECLARE
	@lCallSubject	VARCHAR(100),
	@CallDesc		VARCHAR(100),
	@CallResolution	VARCHAR(100),
	@date4begin		VARCHAR(100),
	@date2end		VARCHAR(100),
	@callduration	VARCHAR(100),
	@notes			VARCHAR(100)

--ASUNTO
select @lCallSubject	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300626
--DESCRIPCION
select @CallDesc		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300627
--Fecha Inicio
select @date4begin		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300629
--Fecha Fin
select @date2end		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300630
--Duración de la llamada
select @callduration	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300633
--NOTAS
select @notes			= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300635
-- ---------------------------------------


declare @description as nvarchar(4000)

SELECT
	@description = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 300062

set @description = @description + ' ' + convert(varchar,@call_id)

insert into tbSecurityLog
(
	comp_id,
	bra_id,
	user_id,
	seclog_obs_1,
	seclog_obs_2,
	seclog_image,
	seclog_obs_3,
	seclog_obs_4,
	seclog_cd,
	aut_id,
	sysCode_id,
	menu_id,
	menu_ts,
	request_ip,
	request_name,
	aure_isok,
	aure_user_id,
	seclog_pageHTML,
	prof_id,
	aure_cd,
	aure_id,
	seclog_id1,
	seclog_id2,
	seclog_id3
)
VALUES
(
	@comp_id,
	@bra_id,
	@user_id,
	@description,
	NULL,
	NULL,
	NULL,
	NULL,
	getdate(),
	NULL,
	1401,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	@prof_id,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL
)

-- ----------------------------------------------------------
-- ACTUALIZAMOS SALE ORDER
-- ----------------------------------------------------------
	if (@chkCA = 'False')
		begin
			declare
					@soss_id		INT
			select
					@soss_id		= ssos_id
			from tbSaleOrderHeader				tsoh
			where	tsoh.comp_id	= @comp_id
			and		tsoh.bra_id		= @bra_id
			and		tsoh.soh_id		= @soh_soh_id

			if (@soss_id = 10)
				begin
					update tbSaleOrderHeader
					SET
							ssos_id		= 20
					where	comp_id		= @comp_id
					and		bra_id		= @bra_id
					and		soh_id		= @soh_soh_id
				end
		end
-- ----------------------------------------------------------


-- -------------------------------------------------------
-- Obtenemos los mails a enviar a los grupos de usuarios
-- -------------------------------------------------------

declare
	@email_recipients	nvarchar(4000),
	@title				nvarchar(1000),
	@text				nvarchar(4000)



/*************************************************************************************/
/*En caso de poseer un TEXTO EN LA HEADER/FOOTER propia, utilizamos ese, sino        */
/*utilizamos el valor genérico de CRM de la UniqueTexts                              */
/*************************************************************************************/

	IF EXISTS (SELECT 1
	           FROM tbCRM_CallMailHeaderFooter							tccmhf	WITH (NOLOCK)
	           WHERE	tccmhf.comp_id					= @comp_id		AND
						tccmhf.callt_id					= @callt_id		AND
						tccmhf.callst_id				= @callst_id	AND
						ISNULL(tccmhf.crmhf_Subject,'')	<> '')
		BEGIN
			SELECT
				@title = tccmhf.crmhf_Subject
			  FROM tbCRM_CallMailHeaderFooter	tccmhf
			WHERE tccmhf.comp_id	= @comp_id	AND
				  tccmhf.callt_id	= @callt_id AND
				  tccmhf.callst_id	= @callst_id
		END
	ELSE
		BEGIN
			SELECT
				@title = tut.utexts_desc
			FROM tbsysUniqueTexts tut
			WHERE	tut.lang_id		= @lang_id AND
					tut.utexts_id	= 300070
		END

select @text = tut.utexts_desc
  from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 300062

set @text = @text + ' ' + convert(varchar,@call_id) /*+ ' ' + @CallDesc + ' ' + @call_description + ' ' + @notes + ' ' +
			@call_Note1 + ' ' + @call_Note2 + ' ' + @date4begin + ' ' + CONVERT(VARCHAR,@call_date4Begin) + ' ' + @callduration + ' ' + CONVERT(VARCHAR,@call_howLong)*/


-- ---------------------------------------------------------------
-- ARMADO DEL HTML PARA EL MAIL
-- ---------------------------------------------------------------
--ARMAMOS HEADER Y FOOTER EN CASO DE QUE HAYA VALORES EN LAS TABLAS

DECLARE @MailTableHeader AS NVARCHAR(MAX),
		@HeaderText		 AS NVARCHAR(MAX),
		@FooterText		 AS NVARCHAR(MAX)

SET @HeaderText = ''
SET @FooterText = ''

SELECT
	@HeaderText = tccmhf.htmlHeader,
	@FooterText = tccmhf.htmlFooter
FROM tbCRM_CallMailHeaderFooter tccmhf
WHERE	tccmhf.comp_id	 = @comp_id  AND
		tccmhf.callt_id	 = @callt_id AND
		tccmhf.callst_id = @callst_id

IF NOT LEN(@HeaderText) > 0
	SET @HeaderText = ''
IF NOT LEN(@FooterText) > 0
	SET @FooterText = ''

-- ---------------------------------------------------------------
-- ESTADO
DECLARE @Status			AS VARCHAR(MAX)
DECLARE @Call_Status	AS VARCHAR(MAX)

	SELECT @Status = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30022

	SELECT @Call_Status = tccs.callst_desc FROM tbCRM_CallStatus tccs WHERE tccs.comp_id = @comp_id AND tccs.callst_id = @callst_id

--variables para el formateo del html email
	DECLARE	@MailTable							NVARCHAR(MAX),
			@MailEndTable						NVARCHAR(MAX),
			@Mailsubject						NVARCHAR(MAX),
			@MailbodyHeader						NVARCHAR(MAX),
			@Mailbody							NVARCHAR(MAX),
			@MailbodyFooter						NVARCHAR(MAX),
			@MailImageSRC						NVARCHAR(MAX)


SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
				 'cellpadding="1" cellspacing="1" border="1">'

SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
					  '<b>' + @title + '</b><br /><br /><br />'


SET @Mailbody = ''
SET @MailBody =

	'<tr><td align="center">' +
	@text + ' ' + convert(varchar,@call_id) + ' ' +
	'</td><tr><td align="center">' +
	@CallDesc + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@call_description) + ' ' +
	'</td></tr><td align="center">' +
		@Status + ' ' + @Call_Status + ' ' +
	'</td></tr><td align="center">' +
	@notes + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@call_Note1) + ' ' + dbo.fnSystem_sendEMail_SetBody2HTML(@call_Note2) + ' ' +
	'</td><tr><td align="center">' +
	@date4begin + ' ' + CONVERT(VARCHAR,@call_date4Begin) + ' ' +
	'</td></tr><td align="center">' +
	@callduration + ' ' + CONVERT(VARCHAR,@call_howLong) + ' ' +
	'</td></tr>'








SET @MailEndTable = + '</table>'

SET @MailbodyFooter = '</div>'






SET @Mailbody = @HeaderText + ' ' + @MailTable + ' ' + @Mailbody + @MailEndTable + ' ' + @FooterText + ' ' + @MailbodyFooter
--SELECT @MailTable
--SELECT @Mailbody
--SELECT @MailEndTable
--SELECT @MailImageSRC
-- ---------------------------------------------------------------



set @email_recipients = ''

select
	@email_recipients = @email_recipients + '; ' + tu.user_email

	from tbCRM_UserGroups						tcug			WITH (NOLOCK)

		inner join tbCRM_UserGroupsDetail		tcugd			WITH (NOLOCK)
		on	tcugd.comp_id	= tcug.comp_id
		AND tcugd.crmug_id	= tcug.crmug_id

		inner join tbUser						tu				WITH (NOLOCK)
		on tu.[user_id] = tcugd.[user_id]

	where	tcug.comp_id						= @comp_id
	--and		tcugd.user_id						= @user_id
	and		tcugd.crmug_id						in (select crmug_id
														from tbCRM_UserGroupsDetail tcugd2			WITH (NOLOCK)
														where	tcugd2.comp_id	 = @comp_id
														and		tcugd2.[user_id] = @user_id)
	and		tcugd.crmugd_disabled				= 'False'
	and     tcugd.crmugd_reciveEmailofChanges	= 'True'

	-- ACA CAMBIAR PARA TAREAS, LLAMADAS y REUNIONES

	and		tcugd.crmugd_4Call					= 'True'
	and		(/*@callt_id = -1*/ tcugd.callt_id IS NULL or  tcugd.callt_id	= @callt_id)

--SET @email_recipients = SUBSTRING(@email_recipients,2,LEN(@email_recipients) - 1)

SELECT @email_recipients

--if @email_recipients <> ''
--	BEGIN
--
--		SET @email_recipients = SUBSTRING(@email_recipients,2,LEN(@email_recipients) - 1)
--
--		exec spSystem_sendEMail
--			@compId = @comp_id,
--			@precipients = @email_recipients,
--			@pcopy_recipients = null,
--			@psubject = @title,
--			@pbody_format = 'HTML',
--			@pbody = @MailBody ,
--			@pfile_attachments = null,
--			@pReplyTo = NULL,
--			@pblind_copy_recipients='',
--			@pUser_Id				= @user_id
--	END


-- -----------------------------------------------------------------------------
-- Envio del Mail
-- -----------------------------------------------------------------------------
	DECLARE @user_mail_origin AS NVARCHAR(MAX)
	DECLARE @strMailString	AS NVARCHAR(MAX)
	DECLARE @strMail		AS NVARCHAR(MAX)
	DECLARE @strMailCC		AS NVARCHAR(MAX)
	DECLARE @strMailCCO		AS NVARCHAR(MAX)
	DECLARE @strMailFrom    AS NVARCHAR(MAX)
	SELECT  @strMailString	= dbo.fnCRM_GetCustomerEmailByCallType(@comp_id, @cust_id, @callt_id, @callst_id, @call_id, @user_id)
	SELECT  @strMail		= dbo.fnSplitPosition(@strMailString, '|',1)
	SELECT  @strMailCC		= dbo.fnSplitPosition(@strMailString, '|',2)
	SELECT  @strMailCCO		= dbo.fnSplitPosition(@strMailString, '|',3)
	SELECT  @strMailFrom	= dbo.fnSplitPosition(@strMailString, '|',4)
	SELECT  @user_mail_origin = tu.user_email from tbUser tu where tu.[user_id] = @user_id

	---- Mail al Usuario Asignado
	--exec spSystem_sendEMail
	--						@compId				= @comp_id,
	--						@precipients		= @user_mail_origin,
	--						@pcopy_recipients	= null,
	--						@psubject			= @title,
	--						@pbody_format		= 'HTML',
	--						@pbody				= @MailBody,
	--						@pfile_attachments	= null,
	--						@pReplyTo			= @strMailFrom,
	--						@pblind_copy_recipients='',
	--						@pUser_Id			= @user_id

	-- Mail de Aviso a Clientes, Contactos, Adicionales, Etc.
	exec spSystem_sendEMail
							@compId					= @comp_id,
							@precipients			= @strMail,
							@pcopy_recipients		= @strMailCC,
							@psubject				= @title,
							@pbody_format			= 'HTML',
							@pbody					= @Mailbody,
							@pfile_attachments		= null,
							@pReplyTo				= @strMailFrom,
							@pblind_copy_recipients	= @strMailCCO,
							@pUser_Id				= @user_id
	-- -----------------------------------------------------------------------------


END
GO




