CREATE PROCEDURE [dbo].[spCRM_CallStatus_getCombo]
(
	@comp_id			INT,
	@status				INT,	-- @status  -1 Update; -2 Insert; -3 Todos
	@prof_id			INT,
	@callst_id			INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo
	@user_id			INT,
	@bra_id				INT
)
AS


	-- --------------------------------------------
	-- Testing
	-- --------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@status		INT,
		@prof_id	INT,
		@callst_id	INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo
		@user_id	INT,
		@bra_id		INT

		SET @comp_id	= 1
		SET @status		= -1
		SET @prof_id	= 1
		SET @callst_id	= 4
		SET @user_id	= 41
		SET @bra_id		= 1
	*/
	-- --------------------------------------------

	SET NOCOUNT ON


	DECLARE @bitActualStatusIsInitial	AS BIT
	DECLARE @bitUserCanSetInitialStatus AS BIT
	SET		@bitActualStatusIsInitial	= 'False'
	SET		@bitUserCanSetInitialStatus = 'False'


	SELECT	@bitActualStatusIsInitial	= IsNull(tcts.callst_isInitialStatus,'False'),
			@bitUserCanSetInitialStatus = IsNull(tu.user_available4CRM_CanReAsignateTask,'False')
		FROM tbCRM_CallStatus tcts				WITH (NOLOCK)
		INNER JOIN tbUser tu					WITH (NOLOCK)
			ON	tu.[user_id] = @user_id
		WHERE	tcts.comp_id = @comp_id AND
				tcts.callst_id = @callst_id




	IF  EXISTS(
				SELECT 1
					FROM tbCRM_CallStatus2Profile tcttp							WITH (NOLOCK)
					INNER JOIN tbCRM_CallStatus tcts							WITH (NOLOCK)
						ON	tcts.comp_id		= tcttp.comp_id AND
							tcts.callst_id		= tcttp.callst_id
					WHERE	tcttp.comp_id		= @comp_id		AND
							tcttp.bra_id		= @bra_id		AND
							tcttp.prof_id		= @prof_id		AND
							tcttp.disabled		= 'False'		AND
							tcts.callst_disabled	= 'False'
				)
		BEGIN

			SELECT	tcts.callst_id		[Id],

					CASE
						WHEN tcts.callst_isInitialStatus	= 'True' THEN	'1'
						WHEN tcts.callst_isFinalStatus		= 'True' THEN	'3'
						ELSE												'2'
					END + ' | ' +
					tcts.callst_desc		[Desc]

				FROM	   tbCRM_CallStatus						tcts			WITH (NOLOCK)
				LEFT JOIN  tbCRM_CallStatus2Profile				tcttp			WITH (NOLOCK)
					ON	tcttp.comp_id		= tcts.comp_id	AND
						tcttp.bra_id		= @bra_id		AND
						tcttp.callst_id		= tcts.callst_id	AND
						tcttp.prof_id		= @prof_id
				WHERE		tcts.comp_id	= @comp_id 							AND
							(
								(
									(
										tcttp.comp_id		IS NOT NULL			AND
										tcttp.disabled		= 'False'			AND
										tcts.callst_disabled	= 'False'
									)

									AND

									CASE
										WHEN	@status	 = -1											AND
												ISNULL(tcts.callst_isInitialStatus,'False')	= 'True'	AND
												@bitActualStatusIsInitial					= 'False'	AND
												@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
										WHEN   (@status	 = -1	AND ISNULL(tcts.callst_isInitialStatus, 'False')	= 'False')	THEN	'True'
										WHEN   (@status	 = -2	AND ISNULL(tcts.callst_isInitialStatus, 'False')	= 'True')	THEN	'True'
										WHEN    @status	 = -3																THEN	'True'
										ELSE																						'False'
									END = 'True'
								)

								OR

								tcts.callst_id	=	@callst_id
							)
				ORDER BY	tcts.callst_desc

		END

	ELSE

		BEGIN

			SELECT		tcts.callst_id		[Id],
					CASE
						WHEN tcts.callst_isInitialStatus	= 'True' THEN	'1'
						WHEN tcts.callst_isFinalStatus		= 'True' THEN	'3'
						ELSE												'2'
					END + ' | ' +
					tcts.callst_desc		[Desc]

				FROM		tbCRM_CallStatus																tcts			WITH (NOLOCK)

				WHERE		tcts.comp_id	=	@comp_id 													AND
							(
								(
									(tcts.prof_id IS NULL OR tcts.prof_id = @prof_id AND tcts.callst_disabled = 'False')	AND
									CASE
										WHEN	@status	 = -1											AND
												ISNULL(tcts.callst_isInitialStatus,'False')	= 'True'	AND
												@bitActualStatusIsInitial					= 'False'	AND
												@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
										WHEN   (@status	 = -1	AND ISNULL(tcts.callst_isInitialStatus, 'False')	= 'False')	THEN	'True'
										WHEN   (@status	 = -2	AND ISNULL(tcts.callst_isInitialStatus, 'False')	= 'True')	THEN	'True'
										WHEN    @status	 = -3																THEN	'True'
										ELSE																						'False'
									END = 'True'
								)
								OR
								@callst_id = tcts.callst_id
							)
				ORDER BY	tcts.callst_desc

		END



GO




CREATE PROCEDURE spCRM_CallStatusGetDataById
(
	@comp_id	INT,
	@callst_id	INT
)
AS
	SET NOCOUNT ON

	BEGIN

		SELECT
			tccs.comp_id,
			tccs.callst_id,
			tccs.prof_id,
			tccs.callst_desc,
			tccs.callst_disabled,
			tccs.bra_id,
			tccs.callst_isFinalStatus,
			tccs.callst_mail2Customer,
			tccs.callst_mail2Contact,
			tccs.callst_mail2Additional,
			ISNULL(tccs.callst_isInitialStatus,'False') [callst_isInitialStatus]

		FROM tbCRM_CallStatus				tccs
		WHERE	tccs.comp_id	= @comp_id	AND
				tccs.callst_id	= @callst_id

	END
GO





