CREATE procedure [dbo].[spCRM_CallType_getCombo]
(
	@comp_id			INT,
	@prof_id			INT,
	@callt_id			INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo. -9 trae TODOS
	@user_id			INT,
	@bra_id				INT
)
as



BEGIN

	set NOCOUNT on


	-- ---------------------------------------------
	-- Testing
	-- ---------------------------------------------
	/*
	DECLARE
	@comp_id			INT,
	@prof_id			INT,
	@callt_id			INT,
	@user_id			INT,
	@bra_id				INT
	SET @comp_id	= 1
	SET @prof_id	= 1
	SET @callt_id	= -1
	SET @user_id	= 41
	SET @bra_id		= 1
	*/
	-- ---------------------------------------------


	IF EXISTS(
				SELECT 1
					FROM tbCRM_CallType2Profile tcttp
					INNER JOIN tbCRM_CallType tctt
						ON	tctt.comp_id		= tcttp.comp_id AND
							tctt.callt_id		= tcttp.callt_id
					WHERE	tcttp.comp_id		= @comp_id	AND
							tcttp.bra_id		= @bra_id	AND
							tcttp.prof_id		= @prof_id	AND
							tcttp.[disabled]	= 'False'	AND
							tctt.callt_disabled = 'False'
				)
		BEGIN

				SELECT		tctt.callt_id	[Id],
							tctt.callt_desc	[Desc]
					FROM		tbCRM_CallType			tctt
					LEFT JOIN	tbCRM_CallType2Profile	tcttp
						ON	tcttp.comp_id		= tctt.comp_id		AND
							tcttp.callt_id		= tctt.callt_id		AND
							tcttp.prof_id		= @prof_id			AND
							tcttp.bra_id		= @bra_id
				    WHERE
							(
								tctt.comp_id		= @comp_id			AND
				    			tctt.callt_disabled	= 'False'			AND
								tcttp.disabled		= 'False'			AND
								tcttp.comp_id		IS NOT NULL
							)
							OR
							tctt.callt_id	= @callt_id
					ORDER BY tctt.callt_desc

		END

	ELSE

		BEGIN

			select
				tctt.callt_id	[Id],
				tctt.callt_desc	[Desc]
				from tbCRM_CallType tctt			WITH (NOLOCK)
				where	tctt.comp_id		= @comp_id	AND
					   (
			   				tctt.callt_id	= @callt_id
			   				OR
							(
								(tctt.prof_id IS NULL OR tctt.prof_id = @prof_id)	AND
								 tctt.callt_disabled = 'False'
							)
					   )
				order by [Desc]

		END
END
GO



