CREATE PROCEDURE [dbo].[spCRM_CampaignDetail_InsertData]
(

 @comp_id					INT,
 @camp_id					INT,
 @cust_id					INT,
 @contact_id				INT,
 @wsc_id					INT,
 @supp_id					INT,
 @ws_ip						NCHAR(50),
 @ws_id						UNIQUEIDENTIFIER


)


AS



BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
	DECLARE

		 @comp_id					INT,
		 @camp_id					INT,
		 @cust_id					INT,
		 @contact_id				INT,
		 @wsc_id					INT,
		 @supp_id					INT,
		 @ws_id						NCHAR(50),
		 @ws_internalID				INT

	SELECT
		 @comp_id						= 1,
		 @guid							= '6e6f5998-9118-4c5c-bb58-723ada3ae6c6',
		 @user_id						= 1,
		 @stor_id						= 3,
		 @puco_id						= 1,
		 @por_id						= 88
	*/
	-- ------------------------------------------------------

	if	@cust_id			= -1 SET	@cust_id	= NULL
	if	@contact_id			= -1 SET	@contact_id	= NULL
	if	@supp_id			= -1 SET	@supp_id	= NULL
	if	@wsc_id				= -1 SET	@wsc_id		= NULL



	DECLARE @ws_InternalID AS INT
	SELECT  @ws_InternalID = twsin.ws_internalID
		FROM tbWebSiteII_Names twsin		WITH (NOLOCK)
		WHERE	twsin.comp_id	= @comp_id AND
				twsin.ws_id		= @ws_id


	INSERT INTO tbCRM_CampaignDetail
	(
			comp_id,
			camp_id,
			cust_id,
			contact_id,
			wsc_id,
			supp_id,
			ws_ip,
			ws_internalID,
			campd_cd
	)
	VALUES
	(
			 @comp_id,
			 @camp_id,
			 @cust_id,
			 @contact_id,
			 @wsc_id,
			 @supp_id,
			 @ws_ip	,
			 @ws_InternalID,
			 GETDATE()

	)






END
GO


