CREATE PROCEDURE [dbo].[spCRM_Case_getDataByFilters]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,

	@selection_id		INT,	--- NO SE USA MAS ESTA MIERDA, QUIEN SABE QUE CARAJO ES Y ASI SE MANDAN LAS FORRADAS
	@tast_id			INT,
	@cast_id			INT,
	@callst_id			INT,
	@meetst_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@option				INT,
	@text				NVARCHAR(500),
	@contact			INT,
	@contact_text		NVARCHAR(500),
	@guid				UNIQUEIDENTIFIER,
	@session_user_id	INT,
	@caset_id			INT,
	@item_id			INT,
	@subcat_id			INT,
	@brand_id			INT,
	@is_serial			NVARCHAR(100),
	@case_id			INT,
	@supp_id			INT,
	@cust_id			INT,
	@datereviewfrom		DATETIME,
	@datereviewto		DATETIME,
	@pro_id				INT
)
AS



BEGIN



	SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------


		--------------------------------------------------------
		-------------parametros de prueba-----------------------
		--------------------------------------------------------
		/*
		DECLARE		@comp_id			INT,
					@bra_id				INT,
					@prof_id			INT,
					@user_id			INT,

					@selection_id		INT,
					@tast_id			INT,
					@cast_id			INT,
					@callst_id			INT,
					@meetst_id			INT,
					@datefrom			datetime,
					@dateto				datetime,
					@option				INT,
					@text				nvarchar(500),
					@contact			int,
					@contact_text		nvarchar(500),
					@guid				uniqueidentifier,
					@session_user_id	int

		SELECT		@comp_id			= 1,
					@bra_id				= 1,
					@prof_id			= 1,

					@selection_id		= -1,
					@datefrom			= '1900-01-01',
					@dateto				= '2012-31-12',
					@tast_id			= -1,
					@cast_id			= -1,
					@meetst_id			= -1,
					@callst_id			= -1,
					@user_id			= 1,
					@option				= -1,
					@text				= '',
					@contact			= -1,
					@session_user_id	= 1
*/
		--------------------------------------------------------
		--------------------------------------------------------
		--------------------------------------------------------

	-- --------------------------------------------------------------------------
	-- Obtenemos el is_id correspondiente al Nº de Serie obtenido por parámetro
	-- --------------------------------------------------------------------------

		DECLARE	@lis_id	INT
		SET		@lis_id		= -1
		SET		@is_serial  = dbo.fnstrAllTrim(@is_serial)

		IF @is_serial <> ''
			BEGIN
				SET			@lis_id			= -2
				SELECT
							@lis_id			= tis.is_id
					FROM	tbItemSerials				tis				WITH (NOLOCK)
					WHERE	tis.comp_id		= @comp_id	AND
							tis.is_serial	= @is_serial
			END
	-- --------------------------------------------------------------------------

	-- --------------------------------------------------------------------------
	-- Pone en una tabla temporal todos los usuarios de mi grupo y
	-- si no estoy en ningun grupo, todos los disponibles para crm
	-- --------------------------------------------------------------------------
	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom	,'false')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto	,'true')

	SET @datereviewfrom	= dbo.fnGetEnd_or_BeginOfDate(@datereviewfrom	,'false')
	SET @datereviewto   = dbo.fnGetEnd_or_BeginOfDate(@datereviewto	,'true')


	DECLARE @tmpUsersOfMyGroup TABLE(USER_ID INT PRIMARY KEY)

	INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
		SELECT DISTINCT tcugd.[USER_ID]
			FROM tbCRM_UserGroupsDetail tcugd						WITH (NOLOCK)
			INNER JOIN tbUser tuMyUser								WITH (NOLOCK)
				ON tuMyUser.[user_id]		= @session_user_id
			INNER JOIN tbUser tu									WITH (NOLOCK)
				ON	tu.[user_id]			= tcugd.[user_id]	AND
					tu.user_available4CRM	= 'True'
			INNER JOIN tbCRM_UserGroupsDetail mg					WITH (NOLOCK)
				ON mg.[user_id] = @session_user_id				AND
				   mg.crmugd_IsAvailable2ViewOtherUsers = 'True'
		WHERE	tcugd.comp_id	= mg.comp_id					AND
				tcugd.crmug_id	= mg.crmug_id					AND
			    tuMyUser.user_available4CRM_SeeAllCases	= 'True'


	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tu.[USER_ID]
					FROM	tbUser tu								WITH (NOLOCK)
					INNER JOIN tbUser tuMyUser						WITH (NOLOCK)
						ON tuMyUser.[user_id]						= @session_user_id
					WHERE	tu.user_available4CRM					= 'True' AND
							tuMyUser.user_available4CRM_SeeAllCases	= 'True'
		END


	IF NOT EXISTS(	SELECT TOP 1  1
						FROM @tmpUsersOfMyGroup
						WHERE [USER_ID] = @session_user_id
				 )
	BEGIN
		INSERT INTO @tmpUsersOfMyGroup ([USER_ID])
			VALUES(@session_user_id)
	END
	-- --------------------------------------------------------------------------







		--guardar el campo de usuario "ver todas las tareas" para mostrar todas las tareas o
		--filtrar solo las del usuario
		declare @luser_available4CRM_SeeAllCases	bit

		SELECT	@luser_available4CRM_SeeAllCases	= isnull(tu.user_available4CRM_SeeAllCases, 'false')
			FROM	tbUser tu
			WHERE	tu.[user_id] = @session_user_id
		--SELECT	@luser_available4CRM_SeeAllCases





		SELECT 	' ' [ ], ' ' [ ],' ' [ ], ' ' [ ], ' ' [ ],
				convert(bit,case
								when tct2.comp_id is null then	'false'
								else							'true'
				            end)													[filter],
				cc.case_id															[ID2]	,
				cc.case_subject,
				cc.case_date4Begin,
				cc.case_nextReviewdate												[nextReviewdate],
				tccs.cast_desc,
				tu.user_lastname + ', ' + tu.user_firstname							[user_name],
				tc3.contact_name,
				tcct.caset_desc														[case_type],
				--cc.case_desc,
				cc.case_date4End,
				cc.case_resolution,
				cc.case_hours,

				cc.[user_id]														[user_id],
				cc.case_price,
				tc.curr_desc,
				tc2.cust_name,
				cc.case_emailAdditional,
				cc.case_id															[ID]



		FROM 	dbo.tbCRM_Case								cc			WITH (NOLOCK)

				INNER JOIN @tmpUsersOfMyGroup tmpu
					ON tmpu.[USER_ID] = cc.[user_id]

				LEFT JOIN tbCRM_Case_Block4Filter tctbf					WITH (NOLOCK)
					ON	tctbf.comp_id			= cc.comp_id		AND
						tctbf.bra_id			= cc.bra_id			AND
						tctbf.caset_id			= cc.caset_id		AND
						tctbf.cast_id			= cc.cast_id		AND
						tctbf.user_id_case		= cc.[user_id]		AND
						tctbf.user_id_actual	= @session_user_id	AND
						cc.[user_id]			<>@session_user_id

				left join tbCRM_tmp							tct2		WITH (NOLOCK)
				on	tct2.comp_id			= cc.comp_id
				and tct2.crmt_function		= 1 -- Aquí es el unico caso en que se suma UNO, no se que MIERDA hizo el HDP que armo esta parte!!!  (0 Case;1 Task;2 Call;3 Meet)
				and tct2.crmt_function_id	= cc.case_id
				and tct2.crmt_guid			= @guid

				LEFT JOIN	tbCRM_CaseStatus				tccs		WITH (NOLOCK)
				ON  tccs.comp_id	= cc.comp_id
				AND tccs.cast_id	= cc.cast_id

				LEFT JOIN	tbUser							tu			WITH (NOLOCK)
				ON  tu.[user_id]	= cc.[user_id]

				INNER JOIN	tbCRM_TypesByProfile			tctbp		WITH (NOLOCK)
				on  tctbp.comp_id	= @comp_id
				and tctbp.bra_id	= @bra_id
				and tctbp.prof_id	= @prof_id
				and tctbp.crm_type	= 0		--case

				LEFT JOIN tbUsers4BranchFilter tubf								WITH (NOLOCK)
					ON	tubf.comp_id	= cc.comp_id		AND
						tubf.bra_id		= cc.bra_id		AND
						tubf.[user_id]	= @session_user_id

				inner join tbBranch							tb			WITH (NOLOCK)
				on  tb.comp_id      = cc.comp_id
				and tb.bra_id	    = cc.bra_id

				inner join tbsysCurrency					tc			WITH (NOLOCK)
				on  tc.curr_id      = tb.curr_id

				inner join tbCRM_CaseType					tcct		WITH (NOLOCK)
				on  tcct.comp_id    = cc.comp_id
				AND tcct.caset_id   = cc.caset_id

				LEFT JOIN tbCustomer						tc2			WITH (NOLOCK)
				ON	tc2.comp_id		= cc.comp_id
				AND tc2.cust_id		= cc.cust_id

				LEFT JOIN tbContact							tc3			WITH (NOLOCK)
				ON	tc3.comp_id		= cc.comp_id
				AND tc3.contact_id	= cc.contact_id


		WHERE	cc.comp_id			= @comp_id
		AND		(@case_id		= 0			OR cc.case_id		= @case_id)

		AND		(cc.bra_id		= @bra_id	OR cc.[user_id]		= @session_user_id	 OR tubf.comp_id IS NOT NULL)
		AND		(@caset_id = -1 OR  cc.caset_id = @caset_id)
--		AND     (
--					(@luser_available4CRM_SeeAllCases = 'false' and cc.[user_id]	= @user_id) OR
--					(@luser_available4CRM_SeeAllCases = 'true')
--				)
		AND		(
					(@cast_id		= -1)		or
     				(@cast_id		= -2 and  tccs.cast_isFinalStatus		= 'false')													OR
     				(@cast_id		= -3 and  tccs.cast_isFinalStatus		= 'True')													OR
     				(@cast_id		= -4 and  tccs.cast_isInitialStatus		= 'True')													OR
     				(@cast_id		= -5 and (tccs.cast_isInitialStatus		= 'False' AND tccs.cast_isFinalStatus = 'False'))			OR
					(cc.cast_id	= @cast_id)
				)
		AND		cc.case_date4Begin	BETWEEN @datefrom and @dateto
		AND		cc.case_date4End	BETWEEN @datefrom and @dateto
		and		((
					(@option	 = -1 ) or
					(@option	 = 0 and cc.case_subject like @text + '%') or
					(@option	 = 1 and cc.case_subject like '%' + @text + '%') or
					(@option	 = 2 and cc.case_subject = @text ) or
					(@option	 = 3 and cc.case_subject <> @text ) or
					(@option	 = 4 and cc.case_subject not like '%' + @text + '%')
				)
				or
				(
					(@option	 = -1 ) or
					(@option	 = 0 and cc.case_desc like @text + '%') or
					(@option	 = 1 and cc.case_desc like '%' + @text + '%') or
					(@option	 = 2 and cc.case_desc = @text ) or
					(@option	 = 3 and cc.case_desc <> @text ) or
					(@option	 = 4 and cc.case_desc not like '%' + @text + '%')
				)
				or
				(
					(@option	 = -1 ) or
					(@option	 = 0 and cc.case_resolution like @text + '%') or
					(@option	 = 1 and cc.case_resolution like '%' + @text + '%') or
					(@option	 = 2 and cc.case_resolution = @text ) or
					(@option	 = 3 and cc.case_resolution <> @text ) or
					(@option	 = 4 and cc.case_resolution not like '%' + @text + '%')
				))
		AND		(
						(@user_id		= -1		AND tctbf.comp_id IS NULL)
					OR
						(cc.[user_id]	= @user_id	AND tctbf.comp_id IS NULL)
				)
		AND		(@item_id		= -1 OR  cc.item_id		= @item_id)
		AND		(@subcat_id		= -1 OR  cc.subcat_id	= @subcat_id)
		AND		(@brand_id		= -1 OR  cc.brand_id	= @brand_id )

		AND		(@lis_id		= -1  OR cc.is_id		= @lis_id)

		AND		(@contact		= -1  OR cc.contact_id	= @contact)

--		AND		(
--					(@contact	 = -1 )																or
--					(@contact	 = 0 and tc3.contact_name like				@contact_text + '%')	or
--					(@contact	 = 1 and tc3.contact_name like     '%' +	@contact_text + '%')	or
--					(@contact	 = 2 and tc3.contact_name =					@contact_text )			or
--					(@contact	 = 3 and tc3.contact_name <>				@contact_text )			or
--					(@contact	 = 4 and tc3.contact_name not like '%' +	@contact_text + '%')
--				)
		--==STL
		AND		(@supp_id			= -1		OR		cc.supp_id		= @supp_id)
		AND		(@cust_id			= -1		or		cc.cust_id		= @cust_id)
		AND (isnull(cc.case_nextReviewdate,'')	BETWEEN @datereviewfrom and @datereviewto )--ga
		AND		(@pro_id			= -1		OR		cc.pro_id		= @pro_id)
		ORDER BY cc.case_date4Begin DESC
		--ORDER BY [filter],cc.case_date4Begin



END
GO








CREATE PROCEDURE [dbo].[spCRM_Case_getDataById]
(
	@comp_id	INT,
	@case_id	INT
)
AS SET NOCOUNT ON


----------------------------------------------------------------------
/*
declare @comp_id	int,
		@case_id	int


select  @comp_id	=1,
		@case_id	=24

*/
----------------------------------------------------------------------

	SELECT	tcc.comp_id,
			tcc.case_id,
			tcc.bra_id,
			tcc.case_subject,
			tcc.case_desc,
			tcc.cast_id,
			tcc.case_resolution,
			tcc.case_hours,
			tcc.case_date4Begin,
			tcc.case_date4End,
			isnull(tu.user_lastname,'') + ', ' + isnull(tu.user_firstname,'')
															[user_name],
			tcc.[user_id],
			tc.curr_desc,
			tcc.case_price,
			tcc.curr_id,
			tcct.caset_id,
			tc2.cust_id,
			tc3.contact_id,
			tcc.case_emailAdditional,
			ISNULL(tcc.cat_id,-1)							[cat_id],
			ISNULL(tcc.subcat_id,-1)						[subcat_id],
			ISNULL(tcc.brand_id,-1)							[brand_id],
			ISNULL(tcc.item_id,-1)							[item_id],
			ISNULL(tcc.is_id,-1)							[is_id],
			ISNULL(tis.is_serial,'')						[is_serial],
			ISNULL(tcc.case_link1,'')						[case_link1],
			ISNULL(tcc.case_link2,'')						[case_link2],
			ISNULL(tcc.case_price2,0)						[case_price2],
			ISNULL(tcc.case_price3,0)						[case_price3],
			ISNULL(tcc.case_qty1,1)							[case_qty1],
			ISNULL(tcc.case_qty2,0)							[case_qty2],
			ISNULL(ti.item_code,'')							[item_code],
			ISNULL(tcc.case_isFromRMA,'False')				[case_isFromRMA],
			tcc.supp_id	,
			tcc.case_nextReviewdate							[case_nextReviewdate],
			tcc.pro_id


	from	tbCRM_Case									tcc

			INNER JOIN tbUser							tu
			ON	tu.[user_id]	= tcc.[user_id]

			inner join tbBranch							tb
			on  tb.comp_id		= tcc.comp_id
			and tb.bra_id		= tcc.bra_id

			inner join tbsysCurrency					tc
			on  tc.curr_id	    = tb.curr_id

			left join tbCRM_CaseType					tcct
			on  tcct.comp_id	= tcc.comp_id
			AND tcct.caset_id	= tcc.caset_id

			LEFT JOIN tbCustomer						tc2
			ON	tc2.comp_id = tcc.comp_id
			AND tc2.cust_id = tcc.cust_id

			LEFT JOIN tbContact							tc3
			ON	tc3.comp_id		= tcc.comp_id
			AND tc3.contact_id	= tcc.contact_id

			LEFT JOIN tbItemSerials						tis
			ON	tis.comp_id = tcc.comp_id AND
				tis.is_id	= tcc.is_id

			LEFT JOIN tbitem ti
				ON	ti.comp_id = tcc.comp_id AND
					ti.item_id = tcc.item_id


	where	tcc.comp_id = @comp_id
	and		tcc.case_id = @case_id


GO








CREATE PROCEDURE [dbo].[spCRM_Case_getDataByText]
(
	@text	VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id  AS INT
)
AS



BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*

		DECLARE
			@text		VARCHAR(300),
			@count		INT,
			@lang_id	INT,
			@comp_id AS INT,
			@bra_id  AS INT

		SELECT
			@text		='A',
			@count		= 2,
			@lang_id	= 2,
			@comp_id	= 1,
			@bra_id		= 1
	*/
	-- ----------------------------------------------------------------





	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')



	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)
	DECLARE @text6	varchar(300)
	DECLARE @text7	varchar(300)
	DECLARE @text8	varchar(300)
	DECLARE @text9	varchar(300)
	DECLARE @text10	varchar(300)

	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0 else
			IF @text2 IS NULL SET @text2 = @text0 else
			IF @text3 IS NULL SET @text3 = @text0 else
			IF @text4 IS NULL SET @text4 = @text0 else
			IF @text5 IS NULL SET @text5 = @text0 else
			IF @text6 IS NULL SET @text6 = @text0 else
			IF @text7 IS NULL SET @text7 = @text0 else
			IF @text8 IS NULL SET @text8 = @text0 else
			IF @text9 IS NULL SET @text9 = @text0 else
			IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------





	SELECT		TOP (@count)

				Upper(dbo.PadRightString( IsNull(tc.case_subject,''),'.',50)) + ' | ' + isnull(convert(VARCHAR(10),tc.case_id),'')	[case_subject],
				tc.case_id
		FROM tbCRM_Case tc
			WHERE		tc.comp_id = @comp_id
					AND (tc.bra_id IS NULL OR tc.bra_id = @bra_id)
		AND
			(

						CASE
							WHEN @selection_method = 0 AND tc.case_subject LIKE @text + '%'	 THEN	'True'
							WHEN @selection_method = 1 AND tc.case_subject LIKE '%' + @text1 + '%'	 THEN	'True'
							WHEN @selection_method = 2 AND tc.case_subject LIKE '%' + @text1 + '%' AND tc.case_subject LIKE '%' + @text2 + '%'		 THEN	'True'
							WHEN @selection_method = 3 AND tc.case_subject LIKE '%' + @text1 + '%' AND tc.case_subject LIKE '%' + @text2 + '%' AND tc.case_subject LIKE '%' + @text3 + '%'	 THEN	'True'
							WHEN @selection_method = 4 AND tc.case_subject LIKE '%' + @text1 + '%' AND tc.case_subject LIKE '%' + @text2 + '%' AND tc.case_subject LIKE '%' + @text3 + '%' AND tc.case_subject LIKE '%' + @text4 + '%'		 THEN	'True'
							WHEN @selection_method = 5 AND tc.case_subject LIKE '%' + @text1 + '%' AND tc.case_subject LIKE '%' + @text2 + '%' AND tc.case_subject LIKE '%' + @text3 + '%' AND tc.case_subject LIKE '%' + @text4 + '%' AND tc.case_subject LIKE '%' + @text5 + '%'		 THEN	'True'
							WHEN @selection_method = 6 AND tc.case_subject LIKE '%' + @text1 + '%' AND tc.case_subject LIKE '%' + @text2 + '%' AND tc.case_subject LIKE '%' + @text3 + '%' AND tc.case_subject LIKE '%' + @text4 + '%' AND tc.case_subject LIKE '%' + @text5 + '%' AND tc.case_subject LIKE '%' + @text6 + '%'	 THEN	'True'
							WHEN @selection_method = 7 AND tc.case_subject LIKE '%' + @text1 + '%' AND tc.case_subject LIKE '%' + @text2 + '%' AND tc.case_subject LIKE '%' + @text3 + '%' AND tc.case_subject LIKE '%' + @text4 + '%' AND tc.case_subject LIKE '%' + @text5 + '%' AND tc.case_subject LIKE '%' + @text6 + '%' AND tc.case_subject LIKE '%' + @text7 + '%'	 THEN	'True'
							WHEN @selection_method = 8 AND tc.case_subject LIKE '%' + @text1 + '%' AND tc.case_subject LIKE '%' + @text2 + '%' AND tc.case_subject LIKE '%' + @text3 + '%' AND tc.case_subject LIKE '%' + @text4 + '%' AND tc.case_subject LIKE '%' + @text5 + '%' AND tc.case_subject LIKE '%' + @text6 + '%' AND tc.case_subject LIKE '%' + @text7 + '%' AND tc.case_subject LIKE '%' + @text8 + '%'		 THEN	'True'
							WHEN @selection_method = 9 AND tc.case_subject LIKE '%' + @text1 + '%' AND tc.case_subject LIKE '%' + @text2 + '%' AND tc.case_subject LIKE '%' + @text3 + '%' AND tc.case_subject LIKE '%' + @text4 + '%' AND tc.case_subject LIKE '%' + @text5 + '%' AND tc.case_subject LIKE '%' + @text6 + '%' AND tc.case_subject LIKE '%' + @text7 + '%' AND tc.case_subject LIKE '%' + @text8 + '%' AND tc.case_subject LIKE '%' + @text9 + '%'		 THEN	'True'
							WHEN @selection_method =10 AND tc.case_subject LIKE '%' + @text1 + '%' AND tc.case_subject LIKE '%' + @text2 + '%' AND tc.case_subject LIKE '%' + @text3 + '%' AND tc.case_subject LIKE '%' + @text4 + '%' AND tc.case_subject LIKE '%' + @text5 + '%' AND tc.case_subject LIKE '%' + @text6 + '%' AND tc.case_subject LIKE '%' + @text7 + '%' AND tc.case_subject LIKE '%' + @text8 + '%' AND tc.case_subject LIKE '%' + @text9 + '%' AND tc.case_subject LIKE '%' + @text10 + '%'		 THEN 'True'
							ELSE	'False'
						END	= 'True'

			)



			ORDER BY	tc.case_subject

END
GO








CREATE PROCEDURE [dbo].[spCRM_Case_GetHistoryData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@case_id	INT
)
as set nocount on


-- -----------------------------------------------
-- Testing
-- -----------------------------------------------
/*
	declare
		@comp_id	INT,
		@case_id	INT
	select
		@comp_id	= 1,
		@case_id	= 2
*/
-- -----------------------------------------------

select

	tcch.case_subject													[case_subject],
	tcch.case_desc														[case_desc],
	tccs.cast_desc														[cast_desc],
	tcch.case_date4Begin												[case_date4Begin],
	tcch.case_date4End													[case_date4End],
	tcch.caseh_cd														[LastUpdate],--Fecha de Ultima actualizacion,
	tcct.caset_desc														[case_type],
	tu.user_lastname + ', ' + tu.user_firstname							[user_name],
	tu2.user_lastname + ', ' + tu2.user_firstname						[user_nameLastUpdate]

from tbCRM_CaseHistory							tcch	WITH (NOLOCK)

	inner join tbCRM_Case						tcc		WITH (NOLOCK)
	on	tcc.comp_id		= tcch.comp_id
	AND tcc.case_id		= tcch.case_id

	left join tbCRM_CaseStatus					tccs	WITH (NOLOCK)
	on	tccs.comp_id	= tcch.comp_id
	AND tccs.cast_id	= tcch.cast_id

	left join tbCRM_CaseType					tcct	WITH (NOLOCK)
	on  tcct.comp_id	= tcch.comp_id
	and tcct.caset_id	= tcch.caset_id

	LEFT JOIN tbUser							tu		WITH (NOLOCK)
	ON tu.[user_id] = tcch.[user_id]

	LEFT JOIN tbUser							tu2		WITH (NOLOCK)
	ON tu2.[user_id] = tcch.user_id_lastUpdate

where tcch.comp_id	= @comp_id
and   tcch.case_id	= @case_id
GO







