-- Reporte de Casos
------------------------


CREATE PROCEDURE [dbo].[spCRM_Case_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,

		@case_id			INT,
		@intBranch4Lang		int


)
AS

SET NOCOUNT ON


BEGIN

set nocount on
set dateformat 'ymd'


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



--------------------------------------------------------
-------------parametros de prueba-----------------------
--------------------------------------------------------
/*
DECLARE		@comp_id			int,
			@lang_id			int,
			@page_id			int,

			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,

			@case_id			INT,
			@intBranch4Lang		INT



SELECT		@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10088,

			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 1,

			@case_id			= 990,
			@intBranch4Lang		= 1


DROP TABLE #tmpcase,#tmptask,#tmpcall,#tmpmeet
*/
--------------------------------------------------------
--------------------------------------------------------
--------------------------------------------------------

DECLARE		@fun_id				INT,
			@ltotal				DECIMAL(19,4),
			@lcurr_desc			nvarchar(50),
			@message_task		VARCHAR(100),
			@message_call		VARCHAR(100),
			@message_meet		VARCHAR(100),
			@message_case		VARCHAR(100)



SET @fun_id = 1


 SELECT @message_case = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 154 AND tut.lang_id = @lang_id
 SELECT @message_task = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 151 AND tut.lang_id = @lang_id
 SELECT @message_call = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 152 AND tut.lang_id = @lang_id
 SELECT @message_meet = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 153 AND tut.lang_id = @lang_id




-------------------------
-- sacar importe total
-------------------------
select @ltotal =
	(SELECT isnull(SUM(ISNULL(CC.case_price,0) * ISNULL(cc.case_qty1, 1)),0)

	 FROM tbCRM_Case cc

		LEFT JOIN	tbCRM_CaseStatus		tccs
		ON  tccs.comp_id	= cc.comp_id
		AND tccs.cast_id	= cc.cast_id

		WHERE	cc.comp_id			= @comp_id
		AND		cc.case_id			= @case_id)

+

	(SELECT isnull(SUM(ISNULL(CC.case_price2,0) * ISNULL(cc.case_qty2, 0)),0)

	 FROM tbCRM_Case cc

		LEFT JOIN	tbCRM_CaseStatus		tccs
		ON  tccs.comp_id	= cc.comp_id
		AND tccs.cast_id	= cc.cast_id

		WHERE	cc.comp_id			= @comp_id
		AND		cc.case_id			= @case_id)

+

	(SELECT isnull(SUM(ISNULL(CC.case_price3,0)),0)

	 FROM tbCRM_Case cc

		LEFT JOIN	tbCRM_CaseStatus		tccs
		ON  tccs.comp_id	= cc.comp_id
		AND tccs.cast_id	= cc.cast_id

		WHERE	cc.comp_id			= @comp_id
		AND		cc.case_id			= @case_id)

+

(SELECT isnull(SUM(ISNULL(TCT.task_price,0)),0)

	FROM tbCRM_Task tct

	left join tbCRM_TaskStatus			tcts
	on  tcts.comp_id	= tct.comp_id
	and tcts.tast_id	= tct.tast_id

	where 	tct.comp_id			= @comp_id
	AND		tct.case_id			= @case_id)

+

(SELECT isnull(SUM(ISNULL(TCC.call_price,0)),0)

	FROM tbCRM_Call tcc

	left join tbCRM_CallStatus			tccs
	on  tccs.comp_id	= tcc.comp_id
	and tccs.callst_id  = tcc.callst_id

	where 	tcc.comp_id			= @comp_id
	AND		tcc.case_id			= @case_id)

+

(SELECT isnull(SUM(ISNULL(TCM.meet_price,0)),0)

	FROM tbCRM_Meet tcm

	left join tbCRM_MeetStatus			tcms
	on  tcms.comp_id    = tcm.comp_id
	and tcms.meetst_id  = tcm.meetst_id

	where 	tcm.comp_id			= @comp_id
	AND		tcm.case_id			= @case_id )

+
--PRECIO DE LAS NOTAS DE CASO DE CRM
(SELECT
	ISNULL(SUM(ISNULL(tccn.casenote_Price,0)),0)
 FROM tbCRM_CaseNote			tccn
 WHERE	tccn.comp_id = @comp_id AND
		tccn.case_id = @case_id)

+
--PRECIO DE LAS NOTAS DE TAREAS DE CRM
(
	SELECT
		ISNULL(SUM(ISNULL(tctn.tasknote_Price,0)),0)
	FROM tbCRM_Task tct
		INNER JOIN tbCRM_TaskNote			tctn
			ON	tctn.comp_id = tct.comp_id	AND
				tctn.task_id = tct.task_id
	WHERE	tct.comp_id = @comp_id AND
			tct.case_id = @case_id
)

-------------------------



---------------------------------------------
-- sacar moneda de la sucursal
---------------------------------------------


select @lcurr_desc = ( SELECT tc.curr_desc FROM tbBranch tb

						INNER JOIN tbsysCurrency tc
						ON TC.curr_id = TB.curr_id

						WHERE tb.bra_id = @bra_id )

-------------------------


---------------------------------------------
-- consulta principal
---------------------------------------------


	SELECT      tccs.cast_desc									[Estado],
				cc.case_date4Begin								[Fecha_Inicio],
				cc.case_date4End								[Fecha_Fin],
				tu.user_lastname + ', ' + tu.user_firstname		[User_Name],
				cc.case_desc									[Desc],
				cc.case_subject									[Subject],
				cc.case_resolution								[Resolucion],
				cc.case_hours									[Horas],
				isnull(cc.case_price,0)							[case_price],
				isnull(@ltotal,0)								[total],
				@lcurr_desc										[curr_desc],
				isnull(tcct.caset_desc,'')						[case_type],
				CONVERT(VARCHAR,cc.case_id)						[case_id],
				ISNULL(cc.case_price2,0)						[case_price2],
				ISNULL(cc.case_price3,0)						[case_price3],
				ISNULL(cc.case_qty1,1)							[case_qty1],
				ISNULL(cc.case_qty2,0)							[case_qty2],
				ISNULL(tc.cust_name,'')							[cust_name],
				ISNULL(tc2.contact_name,'')						[contact_name],
				ISNULL(ti.item_desc,'')							[item_desc]


	into #tmpcase
	FROM 	dbo.tbCRM_Case								cc


			LEFT JOIN	tbCRM_CaseStatus				tccs
			ON  tccs.comp_id	= cc.comp_id
			AND tccs.cast_id	= cc.cast_id

			LEFT JOIN	tbUser							tu
			ON  tu.[user_id]	= cc.[user_id]

			INNER JOIN	tbCRM_TypesByProfile			tctbp
			on  tctbp.comp_id	= @comp_id
			and tctbp.bra_id	= @bra_id
			and tctbp.prof_id	= @prof_id
			and tctbp.crm_type	= 0	--case

			inner join tbCRM_CaseType					tcct
			on  tcct.comp_id    = cc.comp_id
			AND tcct.caset_id   = cc.caset_id

			LEFT JOIN tbCustomer						tc
			ON	tc.comp_id		= cc.comp_id			AND
				tc.cust_id		= cc.cust_id

			LEFT JOIN tbItem							ti
			ON	ti.comp_id		= cc.comp_id			AND
				ti.item_id		= cc.item_id

			LEFT JOIN tbContact							tc2
			ON	tc2.comp_id		= cc.comp_id			AND
				tc2.contact_id	= cc.contact_id



	WHERE	cc.comp_id			= @comp_id
	AND		cc.case_id			= @case_id


 IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmpcase

		END
	  ELSE
			SELECT  ' '[cast_desc],
					' '[Fecha_Inicio],
					' '[Fecha_Fin],
					' '[User_name],
					@message_case [Desc],
					' '[Subject],
					' '[Resolucion],
					' '[Horas],
					' '[case_price],
					' ' [total],
					'' [curr_desc]



---------------------------------------------
---------------------------------------------




----------------------------------------------------
--params para filtros seleccionados --
----------------------------------------------------


exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id
--exec [spReports_getData] 1, 2,	10005

/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/

SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1912
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

		CASE @case_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(select tcc.case_desc
					 from tbCRM_Case tcc
				where   tcc.comp_id    = @comp_id
				And     tcc.case_id    = @case_id
				and     tcc.bra_id	   = @bra_id)
		End [params2]

----------------------------------------------------

----------------------------------------------------



--subreporte - Tareas relacionadas al caso
----------------------------------------------------

select  tct.task_desc,
		tcts.tast_desc,
		tct.task_date4Begin,
		tct.task_date4End,
		tu.user_lastname + ', ' + tu.user_firstname [User_name],
		tct.task_subject,
		isnull(tct.task_price,0) [task_price]

into #tmptask

from tbCRM_Task									tct

	left join tbCRM_TaskStatus					tcts
	on  tcts.comp_id	= tct.comp_id
	and tcts.tast_id	= tct.tast_id

	left join tbUser							tu
	on  tu.[user_id]	= tct.[user_id]

	left join tbCRM_Case						tcc
	on  tcc.comp_id		= tct.comp_id
	and tcc.case_id		= tct.case_id


where 	tct.comp_id			= @comp_id
AND		tct.case_id			= @case_id


 IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmptask
		END
	  ELSE
			SELECT @message_task [task_desc],
					' ' [tast_desc],
					' ' [task_date4Begin],
					' ' [task_date4End],
					' ' [User_name],
					' ' [task_subject],
					' ' [case_price]


----------------------------------------------------
----------------------------------------------------




--subreporte - Llamadas relacionadas al caso
----------------------------------------------------

select  tcc.call_description,
		tccs.callst_desc,
		tcc.call_date4Begin,
		tu.user_lastname + ', ' + tu.user_firstname [User_name],
		tcc.call_Note1,
		tcc.call_Note2,
		isnull(tcc.call_price,0) [call_price]

into #tmpcall
from tbCRM_Call										tcc

	left join tbCRM_CallStatus						tccs
	on  tccs.comp_id	= tcc.comp_id
	and tccs.callst_id  = tcc.callst_id

	left join tbCRM_Case							tcc2
	on  tcc2.comp_id	= tcc.comp_id
	and tcc2.case_id	= tcc.case_id

	left join tbUser								tu
	on  tu.[user_id]	= tcc.[user_id]


where 	tcc.comp_id			= @comp_id
AND		tcc.case_id			= @case_id



 IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmpcall

		END
	  ELSE
			SELECT @message_call [call_description],
					' ' [callst_desc],
					' ' [call_date4Begin],
					' ' [User_name],
					' ' [call_Note1],
					' ' [call_Note2],
					' ' [case_price]
----------------------------------------------------
----------------------------------------------------




--subreporte - Reuniones relacionadas al caso
----------------------------------------------------


select  tcms.meetst_desc,
		tcm.meet_date4Begin,
		tu.user_lastname + ', ' + tu.user_firstname [User_name] ,
		tcm.meet_description,
		tcm.meet_subject,
		tcm.meet_location,
		isnull(tcm.meet_price,0) [meet_price]

into #tmpmeet
from tbCRM_Meet									tcm

	left join tbCRM_MeetStatus					tcms
	on  tcms.comp_id    = tcm.comp_id
	and tcms.meetst_id  = tcm.meetst_id

	left join tbCRM_Case						tcc
	on  tcc.comp_id		= tcms.comp_id
	and tcc.case_id		= tcm.case_id

	left join tbUser							tu
	on  tu.[user_id]	= tcm.[user_id]



where 	tcm.comp_id			= @comp_id
AND		tcm.case_id			= @case_id


IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmpmeet

		END
	  ELSE
			SELECT  ' '[meetst_desc],
					@message_meet [meet_description],
					' ' [meet_date4Begin],
					' ' [User_name],
					' ' [meet_subject],
					' ' [meet_location],
					' ' [case_price]

----------------------------------------------------
----------------------------------------------------


END





GO








CREATE PROCEDURE [dbo].[spCRM_Case_insertData]
(
	@comp_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@lang_id				INT,

	@case_subject			NVARCHAR(2000),
	@case_desc				NVARCHAR(4000),
	@cast_id				INT,
	@case_resolution		NVARCHAR(4000),
	@case_hours				DECIMAL(19,2),
	@case_date4Begin		DATETIME,
	@case_date4End			DATETIME,
	@case_price				DECIMAL(19,4),
	@curr_id				INT,
	@caset_id				INT,
	@cust_id				INT,
	@contact_id				INT,
	@case_emailAdditional	VARCHAR(250),
	@supp_id				INT,
	@case_nextReviewdate    DATETIME,
	@return_value			INT OUTPUT
)
AS
SET NOCOUNT ON


-- ------------------------------------
-- TESTING
-- ------------------------------------
/*
	DECLARE
		@comp_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@lang_id			INT,

		@case_subject		nvarchar(2000),
		@case_desc			nvarchar(4000),
		@cast_id			int,
		@case_resolution	nvarchar(4000),
		@case_hours			decimal(19,2),
		@case_date4Begin	datetime,
		@case_date4End		datetime,
		@case_price			decimal(19,4),
		@curr_id			int,
		@caset_id			int,
		@return_value		INT
	SELECT
		@comp_id			= 1,
		@bra_id				= 1,
		@prof_id			= 1,
		@user_id			= 1,
		@lang_id			= 2,

		@case_subject		= 'PRUEBA SEBA',
		@case_desc			= 'PRUEBA SEBA',
		@cast_id			= 2,
		@case_resolution	= 'NO RESUELTO',
		@case_hours			= 10,
		@case_date4Begin	= '',
		@case_date4End		= '2013-08-26',
		@case_price			= 10,
		@curr_id			= 2,
		@caset_id			= 2
		SET @return_value	= 0
*/
-- ------------------------------------

BEGIN

	SET DATEFORMAT 'ymd'


	IF @cust_id = -1
		BEGIN
			SET @cust_id = NULL
		END
	IF @contact_id = -1
		BEGIN
			SET @contact_id = NULL
		END
	IF @supp_id = -1
		BEGIN
			SET @supp_id = NULL
		END


	insert into tbCRM_Case
	(
		comp_id,
		bra_id,
		case_subject,
		case_desc,
		cast_id,
		case_resolution,
		case_hours,
		case_date4Begin,
		case_date4End,
		[user_id],
		case_price,
		curr_id,
		caset_id,
		cust_id,
		contact_id,
		case_emailAdditional,
		case_secondUpdate,
		supp_id,
		case_nextReviewdate,
		user_id_Creator
	)
	VALUES
	(
		@comp_id,
		@bra_id,
		@case_subject,
		@case_desc,
		@cast_id,
		@case_resolution,
		@case_hours,
		@case_date4Begin,
		@case_date4End,
		@user_id,
		@case_price,
		@curr_id,
		@caset_id,
		@cust_id,
		@contact_id,
		@case_emailAdditional,
		'False',
		@supp_id,
		@case_nextReviewdate,
		@user_id
	)


	SET @return_value = @@IDENTITY



declare
	@message			 varchar(4000),
	@subject			 varchar(4000),
	@body				 varchar(4000),
	@mail				 varchar(8000),
	@user_origen_name	 varchar(400),
	@user_mail_origin	 varchar(400),
	@optionid			 int,
	@desc				 varchar(200)


--Datos del Usuario de Origen
select
	@user_origen_name = (tu.user_lastname + ',' + tu.user_firstname),
	@user_mail_origin = tu.user_email
from tbUser tu where tu.[user_id] = @user_id

set @optionid = 3512

-- ---------------------------------------
-- Textos para armado del mail completo
DECLARE
	@lCaseSubject	VARCHAR(100),
	@CaseDesc		VARCHAR(100),
	@CaseResolution	VARCHAR(100),
	@date4begin		VARCHAR(100),
	@date2end		VARCHAR(100)
--ASUNTO
select @lCaseSubject	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300626
--DESCRIPCION
select @CaseDesc		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300627
--RESOLUCION
select @CaseResolution	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300628
--Fecha Inicio
select @date4begin		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300629
--Fecha Fin
select @date2end		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300630
-- ---------------------------------------


--Armado de Subject y Body

select @desc = tswn.word_desc
  from tbSysWordsNew tswn where tswn.lang_id = @lang_id and tswn.wordsi_id = @optionid

/*************************************************************************************/
/*En caso de poseer un TEXTO EN LA HEADER/FOOTER propia, utilizamos ese, sino        */
/*utilizamos el valor genérico de CRM de la UniqueTexts                              */
/*************************************************************************************/

	IF EXISTS (SELECT 1
	           FROM tbCRM_CaseMailHeaderFooter tccmhf WITH (NOLOCK)
	           WHERE	tccmhf.comp_id					= @comp_id AND
						tccmhf.cast_id					= @cast_id AND
						tccmhf.caset_id					= @caset_id AND
						ISNULL(tccmhf.crmhf_Subject,'') <> '')
		BEGIN
			SELECT
				@subject = tccmhf.crmhf_Subject
			  FROM tbCRM_CaseMailHeaderFooter		tccmhf WITH (NOLOCK)
			WHERE	tccmhf.comp_id		= @comp_id	AND
						tccmhf.cast_id	= @cast_id	AND
						tccmhf.caset_id	= @caset_id

		END
	ELSE
		BEGIN
			SELECT
				@subject = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id  AND
					tut.utexts_id	= 984

			set @subject = @subject + @desc

		END




select @message = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 985

select @body = tut.utexts_desc + ' ' + CONVERT(VARCHAR,@return_value)
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 986




set @mail = @desc								+ ' ' +
			@message							+ ' ' +
			@user_origen_name					+ ' ' +
			@body								+ ' ' +
			@lCaseSubject						+ ' ' +
			@case_subject						+ ' ' +
			@CaseDesc							+ ' ' +
			@case_desc							+ ' ' +
			@CaseResolution						+ ' ' +
			@case_resolution					+ ' ' +
			@date4begin							+ ' ' +
			CONVERT(VARCHAR,@case_date4Begin)	+ ' ' +
			@date2end							+ ' ' +
			CONVERT(VARCHAR,@case_date4End)




-- ---------------------------------------------------------------
-- ARMADO DEL HTML PARA EL MAIL
-- ---------------------------------------------------------------
--ARMAMOS HEADER Y FOOTER EN CASO DE QUE HAYA VALORES EN LAS TABLAS

DECLARE @MailTableHeader AS NVARCHAR(MAX),
		@HeaderText		 AS NVARCHAR(MAX),
		@FooterText		 AS NVARCHAR(MAX)

SET @HeaderText = ''
SET @FooterText = ''

SELECT
	@HeaderText = tccmhf.htmlHeader,
	@FooterText = tccmhf.htmlFooter
FROM tbCRM_CaseMailHeaderFooter tccmhf
WHERE	tccmhf.comp_id	= @comp_id AND
		tccmhf.cast_id	= @cast_id AND
		tccmhf.caset_id = @caset_id

IF NOT LEN(@HeaderText) > 0
	SET @HeaderText = ''
IF NOT LEN(@FooterText) > 0
	SET @FooterText = ''


-- ---------------------------------------------------------------
-- ESTADO
DECLARE @Status			AS VARCHAR(MAX)
DECLARE @Case_Status	AS VARCHAR(MAX)

	SELECT @Status = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30022

	SELECT @Case_Status = tccs.cast_desc FROM tbCRM_CaseStatus tccs WHERE tccs.comp_id = @comp_id AND tccs.cast_id = @cast_id

-- ---------------------------------------------------------------
--variables para el formateo del html email
	DECLARE	@MailTable							NVARCHAR(MAX),
			@MailEndTable						NVARCHAR(MAX),
			@Mailsubject						NVARCHAR(MAX),
			@MailbodyHeader						NVARCHAR(MAX),
			@Mailbody							NVARCHAR(MAX),
			@MailbodyFooter						NVARCHAR(MAX),
			@MailImageSRC						NVARCHAR(MAX)


SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
				 'cellpadding="1" cellspacing="1" border="1">'

SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
					  '<b>' + @subject + @desc + '</b><br /><br /><br />'


SET @Mailbody = ''
SET @MailBody =

	'<tr><td align="center">' +
		@desc + ' ' + @message + ' ' +  @user_origen_name  + ' ' +
	'</td><tr><td align="center">' +
		@body + ' ' +
	'</td></tr><td align="center">' +
		@lCaseSubject + ' ' + @case_subject + ' ' +
	'</td></tr><td align="center">' +
		@Status + ' ' + @Case_Status + ' ' +
	'</td><tr><td align="center">' +
		@CaseDesc + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@case_desc) + ' ' +
	'</td></tr><td align="center">' +
		@CaseResolution + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@case_resolution) + ' ' +
	'</td><tr><td align="center">' +
		@date4begin + ' ' + CONVERT(VARCHAR,@case_date4Begin) + ' ' +
	'</td><tr><td align="center">' +
		@date2end + ' ' + CONVERT(VARCHAR,@case_date4End)	  + ' ' +
	'</td></tr>'




SET @MailEndTable = + '</table>'

SET @MailbodyFooter = '</div>'






SET @Mailbody = @HeaderText + ' ' +  @MailTable + ' ' + @Mailbody + @MailEndTable + ' ' + @FooterText + ' ' + @MailbodyFooter
--SELECT @MailTable
--SELECT @Mailbody
--SELECT @MailEndTable
--SELECT @MailImageSRC
-- ---------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Envio del Mail
-- -----------------------------------------------------------------------------
	DECLARE @strMailString	AS NVARCHAR(MAX)
	DECLARE @strMail		AS NVARCHAR(MAX)
	DECLARE @strMailCC		AS NVARCHAR(MAX)
	DECLARE @strMailCCO		AS NVARCHAR(MAX)
	DECLARE @strMailFrom    AS NVARCHAR(MAX)
	SELECT  @strMailString	= dbo.fnCRM_GetCustomerEmailByCaseType(@comp_id, @cust_id, @caset_id, @cast_id, @return_value, @user_id)
	SELECT  @strMail		= dbo.fnSplitPosition(@strMailString, '|',1)
	SELECT  @strMailCC		= dbo.fnSplitPosition(@strMailString, '|',2)
	SELECT  @strMailCCO		= dbo.fnSplitPosition(@strMailString, '|',3)
	SELECT  @strMailFrom	= dbo.fnSplitPosition(@strMailString, '|',4)

	---- Mail al Usuario Asignado
	--exec spSystem_sendEMail
	--						@compId				= @comp_id,
	--						@precipients		= @user_mail_origin,
	--						@pcopy_recipients	= null,
	--						@psubject			= @subject,
	--						@pbody_format		= 'HTML',
	--						@pbody				= @MailBody,
	--						@pfile_attachments	= null,
	--						@pReplyTo			= @strMailFrom,
	--						@pblind_copy_recipients='',
	--						@pUser_Id			= @user_id

	-- Mail de Aviso a Clientes, Contactos, Adicionales, Etc.
	exec spSystem_sendEMail
							@compId					= @comp_id,
							@precipients			= @strMail,
							@pcopy_recipients		= @strMailCC,
							@psubject				= @subject,
							@pbody_format			= 'HTML',
							@pbody					= @Mailbody,
							@pfile_attachments		= null,
							@pReplyTo				= @strMailFrom,
							@pblind_copy_recipients	= @strMailCCO,
							@pUser_Id				= @user_id
	-- -----------------------------------------------------------------------------


insert into tbSecurityLog
(
	comp_id,
	bra_id,
	user_id,
	seclog_obs_1,
	seclog_obs_2,
	seclog_image,
	seclog_obs_3,
	seclog_obs_4,
	seclog_cd,
	aut_id,
	sysCode_id,
	menu_id,
	menu_ts,
	request_ip,
	request_name,
	aure_isok,
	aure_user_id,
	seclog_pageHTML,
	prof_id,
	aure_cd,
	aure_id,
	seclog_id1,
	seclog_id2,
	seclog_id3
)
VALUES
(
	@comp_id,
	@bra_id,
	@user_id,
	@mail,
	NULL,
	NULL,
	NULL,
	NULL,
	getdate(),
	NULL,
	1200,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	@prof_id,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL
)

END
GO








CREATE PROCEDURE [dbo].[spCRM_Case_Relations]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@case_id	INT
)
as set nocount on


-- -----------------------------------------------
-- Testing
-- -----------------------------------------------
/*
	declare
		@comp_id	INT,
		@case_id	INT
	select
		@comp_id	= 1,
		@case_id	= 2
*/

-- -----------------------------------------------


select distinct tcc.case_id, tcc.case_desc

from tbCRM_Case tcc

inner join tbCRM_Task tct
on tct.comp_id = tcc.comp_id
and tct.case_id = tcc.case_id

where tcc.comp_id= @comp_id
and tcc.case_id = @case_id

UNION
select distinct tcc.case_id, tcc.case_desc

from tbCRM_Case tcc

inner join tbCRM_Call tcc2
on tcc2.comp_id = tcc.comp_id
AND tcc2.case_id = tcc.case_id

where tcc.comp_id= @comp_id
and tcc.case_id = @case_id

UNION
select distinct tcc.case_id, tcc.case_desc

from tbCRM_Case tcc

inner join tbCRM_Meet tcm
on tcm.comp_id = tcc.comp_id
and tcm.case_id = tcc.case_id

where tcc.comp_id= @comp_id
and tcc.case_id = @case_id
GO



CREATE PROCEDURE [dbo].[spCRM_Case_SendNotifications]

AS
	SET NOCOUNT ON

	BEGIN
		/*
		DECLARE
			@lang_id	INT

		SELECT
			@lang_id	= 2
		*/



			-- declareción de variables para obtener los datos del cursor
			DECLARE
				@comp_id				INT,
				@case_id				INT,
				@bra_id					INT,
				@case_subject			VARCHAR(MAX),
				@case_desc				VARCHAR(MAX),
				@cast_id				INT,
				@case_resolution		VARCHAR(MAX),
				@user_id				INT,
				@caset_id				INT,
				@cust_id				INT,
				@case_link1				VARCHAR(500),
				@case_link2				VARCHAR(500),
				@case_date4Begin		DATETIME,
				@case_date4End			DATETIME,
				@case_advertiseDate		DATETIME,
				@case_advertiseCount	INT,
				@case_advertiseLastDate	DATETIME,
				@bisIsAdvertiseLastDate BIT



			DECLARE cursor_Case CURSOR LOCAL FAST_FORWARD FOR

				SELECT
					tcc.comp_id,
					tcc.case_id,
					tcc.bra_id,
					tcc.case_subject,
					tcc.case_desc,
					tcc.cast_id,
					tcc.case_resolution,
					tcc.[user_id],
					tcc.caset_id,
					tcc.cust_id,
					tcc.case_link1,
					tcc.case_link2,
					TCC.case_date4Begin,
					TCC.case_date4End,
					tcc.case_advertiseDate,
					tcc.case_advertiseCount,
					tcc.case_advertiseLastDate,
					CASE
						WHEN tcc.case_advertiseDate IS NULL THEN	'False'
						ELSE										'True'
					END
				FROM tbCRM_Case tcc
				INNER JOIN tbBranch tb
					ON	tb.comp_id	= tcc.comp_id AND
						tb.bra_id	= tcc.bra_id
				INNER JOIN tbCRM_CaseStatus tcts		WITH (NOLOCK)
					ON	tcts.comp_id			= tcc.comp_id	AND
						tcts.cast_id			= tcc.cast_id	AND
						tcts.cast_isFinalStatus = 'False'

				WHERE	tcc.case_advertiseDate IS NOT NULL
														OR
						(	tb.bra_processingDate = tcc.case_nextReviewdate AND
						   (tcc.case_nextReviewdateLastMailDate IS NULL
								OR
							tcc.case_nextReviewdateLastMailDate < tcc.case_nextReviewdate
						   )
						)
				--WHERE tcc.case_id = 995

			OPEN	cursor_Case


			-- lectura anticipada del cursor
			FETCH	cursor_Case
			INTO
				@comp_id,
				@case_id,
				@bra_id,
				@case_subject,
				@case_desc,
				@cast_id,
				@case_resolution,
				@user_id,
				@caset_id,
				@cust_id,
				@case_link1,
				@case_link2,
				@case_date4Begin,
				@case_date4End,
				@case_advertiseDate,
				@case_advertiseCount,
				@case_advertiseLastDate,
				@bisIsAdvertiseLastDate



			-- se recorre el cursor hasta el fin del mismo
			WHILE   @@FETCH_STATUS = 0
			BEGIN

				--ACA PROCESAMOS Y AVISAMOS

					--SI EL COUNT ES DISTINTO DE NULL, SUMAMOS 1 Y SETEAMOS EN NULL
					--LA FECHA DE AVISO SI ES MENOR O IGUAL A LA FECHA ACTUAL

					IF (@case_advertiseCount IS NOT NULL) AND (@case_advertiseDate <= GETDATE())

						BEGIN
							--select 1
							DECLARE @lang_id	INT
							SELECT  @lang_id = tb.lang_id FROM tbBranch tb WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id


							IF @bisIsAdvertiseLastDate = 'True'
								BEGIN
									UPDATE tbCRM_Case
									SET
										case_advertiseDate	= NULL,
										case_advertiseCount = case_advertiseCount + 1
									WHERE	comp_id			= @comp_id AND
											case_id			= @case_id
								END


							--COLOR DEL ENCABEZADO
							-- VERDE	= 1 Aviso			--> "Recordatorio"
							-- AMARILLO = 2 Avisos			--> "Recordatorio"
							-- ROJO		= 3 Avisos o más	--> "Advertencia"
							DECLARE
								@HeaderColor	VARCHAR(20),
								@HeaderMessage	VARCHAR(100)
								SET @HeaderColor = '#3ADF00'
								SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60000

								IF (@case_advertiseCount + 1) = 1
									BEGIN
										SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60000
										SET @HeaderColor = '#3ADF00'
									END

								IF (@case_advertiseCount + 1) = 2
									BEGIN
										SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60000
										SET @HeaderColor = '#F4FA58'
									END

								IF (@case_advertiseCount + 1) > 2
									BEGIN
										SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60001
										SET @HeaderColor = '#DF0101'
									END

							--ENVIAMOS MAILS
							-- --------------------------------------------------------------------------------------------------------------------------------
							-- Envio del Mail
							-- --------------------------------------------------------------------------------------------------------------------------------

								DECLARE
									@message			 VARCHAR(4000),
									@subject			 VARCHAR(4000),
									@body				 VARCHAR(4000),
									@mail				 VARCHAR(8000),
									@user_origen_name	 VARCHAR(400),
									@user_mail_origin	 VARCHAR(400),
									@optionid			 INT,
									@desc				 VARCHAR(200)


								--Datos del Usuario de Origen
								SELECT
									@user_origen_name = (tu.user_lastname + ',' + tu.user_firstname),
									@user_mail_origin = tu.user_email
								FROM tbUser tu
								WHERE tu.[user_id] = @user_id

								SET @optionid = 3512

								-- ---------------------------------------
								-- Textos para armado del mail completo
								DECLARE
									@lCaseSubject	VARCHAR(100),
									@CaseDesc		VARCHAR(100),
									@CaseResolution	VARCHAR(100),
									@date4begin		VARCHAR(100),
									@date2end		VARCHAR(100)
								--ASUNTO
								SELECT @lCaseSubject	= tut.utexts_desc
								FROM tbsysUniqueTexts	tut
								WHERE tut.lang_id		= @lang_id
								AND tut.utexts_id		= 300626
								--DESCRIPCION
								SELECT @CaseDesc		= tut.utexts_desc
								FROM tbsysUniqueTexts	tut
								WHERE tut.lang_id		= @lang_id
								AND tut.utexts_id		= 300627
								--RESOLUCION
								SELECT @CaseResolution	= tut.utexts_desc
								FROM tbsysUniqueTexts	tut
								WHERE tut.lang_id		= @lang_id
								AND tut.utexts_id		= 300628
								--Fecha Inicio
								SELECT @date4begin		= tut.utexts_desc
								FROM tbsysUniqueTexts	tut
								WHERE tut.lang_id		= @lang_id
								AND tut.utexts_id		= 300629
								--Fecha Fin
								SELECT @date2end		= tut.utexts_desc
								FROM tbsysUniqueTexts	tut
								WHERE tut.lang_id		= @lang_id
								AND tut.utexts_id		= 300630
								-- ---------------------------------------


								--Armado de Subject y Body

								SELECT @desc = tswn.word_desc
								  FROM tbSysWordsNew tswn
								WHERE	tswn.lang_id	= @lang_id AND
										tswn.wordsi_id	= @optionid

								/*************************************************************************************/
								/*En caso de poseer un TEXTO EN LA HEADER/FOOTER propia, utilizamos ese, sino        */
								/*utilizamos el valor genérico de CRM de la UniqueTexts                              */
								/*************************************************************************************/

									IF EXISTS (SELECT 1
											   FROM tbCRM_CaseMailHeaderFooter tccmhf WITH (NOLOCK)
											   WHERE	tccmhf.comp_id					= @comp_id AND
														tccmhf.cast_id					= @cast_id AND
														tccmhf.caset_id					= @caset_id AND
														ISNULL(tccmhf.crmhf_Subject,'') <> '')
										BEGIN
											SELECT
												@subject = tccmhf.crmhf_Subject
											  FROM tbCRM_CaseMailHeaderFooter		tccmhf WITH (NOLOCK)
											WHERE	tccmhf.comp_id		= @comp_id	AND
														tccmhf.cast_id	= @cast_id	AND
														tccmhf.caset_id	= @caset_id

										END
									ELSE
										BEGIN
											SELECT
												@subject = tut.utexts_desc
											FROM tbsysUniqueTexts				tut
											WHERE	tut.lang_id		= @lang_id  AND
													tut.utexts_id	= 984

											set @subject = @subject + @desc

										END




								select @message = tut.utexts_desc
								from tbsysUniqueTexts tut
								where tut.lang_id = @lang_id
								and tut.utexts_id = 985

								select @body = tut.utexts_desc + ' ' + CONVERT(VARCHAR,@case_id)
								from tbsysUniqueTexts tut
								where tut.lang_id = @lang_id
								and tut.utexts_id = 986




								set @mail = @desc								+ ' ' +
											@message							+ ' ' +
											@user_origen_name					+ ' ' +
											@body								+ ' ' +
											@lCaseSubject						+ ' ' +
											@case_subject						+ ' ' +
											@CaseDesc							+ ' ' +
											@case_desc							+ ' ' +
											@CaseResolution						+ ' ' +
											@case_resolution					+ ' ' +
											@date4begin							+ ' ' +
											CONVERT(VARCHAR,@case_date4Begin)	+ ' ' +
											@date2end							+ ' ' +
											CONVERT(VARCHAR,@case_date4End)




								-- ---------------------------------------------------------------
								-- ARMADO DEL HTML PARA EL MAIL
								-- ---------------------------------------------------------------
								--ARMAMOS HEADER Y FOOTER EN CASO DE QUE HAYA VALORES EN LAS TABLAS

								DECLARE @MailTableHeader AS NVARCHAR(MAX),
										@HeaderText		 AS NVARCHAR(MAX),
										@FooterText		 AS NVARCHAR(MAX)

								SET @HeaderText = ''
								SET @FooterText = ''

								SELECT
									@HeaderText = tccmhf.htmlHeader,
									@FooterText = tccmhf.htmlFooter
								FROM tbCRM_CaseMailHeaderFooter tccmhf
								WHERE	tccmhf.comp_id	= @comp_id AND
										tccmhf.cast_id	= @cast_id AND
										tccmhf.caset_id = @caset_id

								IF NOT LEN(@HeaderText) > 0
									SET @HeaderText = ''
								IF NOT LEN(@FooterText) > 0
									SET @FooterText = ''


								-- ---------------------------------------------------------------
								-- ESTADO
								DECLARE @Status			AS VARCHAR(MAX)
								DECLARE @Case_Status	AS VARCHAR(MAX)

									SELECT @Status = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30022

									SELECT @Case_Status = tccs.cast_desc FROM tbCRM_CaseStatus tccs WHERE tccs.comp_id = @comp_id AND tccs.cast_id = @cast_id

								-- ---------------------------------------------------------------
								--variables para el formateo del html email
									DECLARE	@MailTable							NVARCHAR(MAX),
											@MailEndTable						NVARCHAR(MAX),
											@Mailsubject						NVARCHAR(MAX),
											@MailbodyHeader						NVARCHAR(MAX),
											@Mailbody							NVARCHAR(MAX),
											@MailbodyFooter						NVARCHAR(MAX),
											@MailImageSRC						NVARCHAR(MAX)


								SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

								SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
												 'cellpadding="1" cellspacing="1" border="3">'

								SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
													  '<b>' + @subject + @desc + '</b><br /><br /><br />'


								SET @Mailbody = ''
								SET @MailBody =

									'
									<tr>
										<td align="center" bgcolor="' + @HeaderColor +  '">' +
											@HeaderMessage + ' ' + CONVERT(VARCHAR,@case_advertiseCount + 1) + ' ' +
										'</td>
									</tr>
									<tr><td align="center">' +
										@desc + ' ' + @message + ' ' +  @user_origen_name  + ' ' +
									'</td><tr><td align="center">' +
										@body + ' ' +
									'</td></tr><td align="center">' +
										@lCaseSubject + ' ' + @case_subject + ' ' +
									'</td></tr><td align="center">' +
										@Status + ' ' + @Case_Status + ' ' +
									'</td><tr><td align="center">' +
										@CaseDesc + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@case_desc) + ' ' +
									'</td></tr><td align="center">' +
										@CaseResolution + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@case_resolution) + ' ' +
									'</td><tr><td align="center">' +
										@date4begin + ' ' + CONVERT(VARCHAR,@case_date4Begin) + ' ' +
									'</td><tr><td align="center">' +
										@date2end + ' ' + CONVERT(VARCHAR,@case_date4End)	  + ' ' +
									'</td></tr>'




								SET @MailEndTable = + '</table>'

								SET @MailbodyFooter = '</div>'

								SET @Mailbody = @HeaderText + ' ' +  @MailTable + ' ' + @Mailbody + @MailEndTable + ' ' + @FooterText + ' ' + @MailbodyFooter
								-- ---------------------------------------------------------------

								-- -----------------------------------------------------------------------------
								-- Envio del Mail
								-- -----------------------------------------------------------------------------
									DECLARE @strMailString	AS NVARCHAR(MAX)
									DECLARE @strMail		AS NVARCHAR(MAX)
									DECLARE @strMailCC		AS NVARCHAR(MAX)
									DECLARE @strMailCCO		AS NVARCHAR(MAX)
									DECLARE @strMailFrom    AS NVARCHAR(MAX)
									SELECT  @strMailString	= dbo.fnCRM_GetCustomerEmailByCaseType(@comp_id, @cust_id, @caset_id, @cast_id, @case_id, @user_id)
									SELECT  @strMail		= dbo.fnSplitPosition(@strMailString, '|',1)
									SELECT  @strMailCC		= dbo.fnSplitPosition(@strMailString, '|',2)
									SELECT  @strMailCCO		= dbo.fnSplitPosition(@strMailString, '|',3)
									SELECT  @strMailFrom	= dbo.fnSplitPosition(@strMailString, '|',4)

									-- Mail al Usuario Asignado
									--select @user_mail_origin

									exec spSystem_sendEMail
															@compId				= @comp_id,
															@precipients		= @user_mail_origin,
															@pcopy_recipients	= null,
															@psubject			= @subject,
															@pbody_format		= 'HTML',
															@pbody				= @MailBody,
															@pfile_attachments	= null,
															@pReplyTo			= @strMailFrom,
															@pblind_copy_recipients='',
															@pUser_Id			= @user_id

							-- --------------------------------------------------------------------------------------------------------------------------------
							-- --------------------------------------------------------------------------------------------------------------------------------


							--ACTUALIZAMOS LA FECHA DE AVISO
							UPDATE tbCRM_Case
							SET
								case_advertiseLastDate = GETDATE(),
								case_nextReviewdateLastMailDate =	CASE
																		WHEN case_nextReviewdate IS NULL THEN NULL
																		WHEN case_nextReviewdate <= GETDATE() THEN GETDATE()
																		ELSE case_nextReviewdate
																	END
							WHERE	comp_id = @comp_id AND
									case_id = @case_id

							DECLARE @strURL AS NVARCHAR(600)
							SET @strURL = 'wfmCRM_CaseDetail.aspx?&BraId='	+ CONVERT(VARCHAR,@bra_id)	+
																'&CaseId='	+ CONVERT(VARCHAR,@case_id) +
																'&Action='  + 'U'						+ '&'


							--GRABAMOS WORKFLOW
							INSERT INTO tbWorkflow
							(
								comp_id,
								bra_id,
								wf_type,
								wf_isProcessed,
								user_id_from,
								user_id_assigned,
								user_id_processed,
								prof_id_assigned,
								wf_dateOfAssigned,
								wf_dateOfProcessing,
								wf_link,
								wf_message1,
								wf_message2,
								wf_htmlTop,
								wf_htmlBody,
								wf_html_Bottom,
								case_id
							)
							VALUES
							(
								@comp_id,
								@bra_id,
								777,
								'False',
								NULL,
								@user_id, --@intUser4Notify,
								NULL,
								NULL,
								GETDATE(),
								NULL,
								@strURL,
								@subject,
								'',
								@MailBody, --@strRet_ErrorDescription,
								'',
								'',
								@case_id
							)

						END


				-- próxima lectura del cursor
				FETCH	cursor_Case
				INTO
					@comp_id,
					@case_id,
					@bra_id,
					@case_subject,
					@case_desc,
					@cast_id,
					@case_resolution,
					@user_id,
					@caset_id,
					@cust_id,
					@case_link1,
					@case_link2,
					@case_date4Begin,
					@case_date4End,
					@case_advertiseDate,
					@case_advertiseCount,
					@case_advertiseLastDate,
					@bisIsAdvertiseLastDate


			END

			CLOSE cursor_Case
			DEALLOCATE cursor_Case

	END
GO








CREATE PROCEDURE [dbo].[spCRM_Case_updateData]
(
	@comp_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@lang_id				INT,

	@case_id				INT,
	@case_subject			NVARCHAR(2000),
	@case_desc				NVARCHAR(4000),
	@cast_id				INT,
	@case_resolution		NVARCHAR(4000),
	@case_hours				DECIMAL(19,2),
	@case_date4Begin		DATETIME,
	@case_date4End			DATETIME,
	@case_price				DECIMAL(19,4),
	@curr_id				INT,
	@caset_id				INT,
	@cust_id				INT,
	@contact_id				INT,
	@case_emailAdditional	VARCHAR(250),
	@supp_id				INT,
	@case_nextReviewdate    DATETIME
)
AS



BEGIN


	SET NOCOUNT ON

	IF @cust_id = -1
		BEGIN
			SET @cust_id = NULL
		END
	IF @contact_id = -1
		BEGIN
			SET @contact_id = NULL
		END
	IF @supp_id = -1
		BEGIN
			SET @supp_id = NULL
		END


	update tbCRM_Case
	SET
		bra_id					= @bra_id,
		case_subject			= @case_subject,
		case_desc				= @case_desc,
		cast_id					= @cast_id,
		case_resolution			= @case_resolution,
		case_hours				= @case_hours,
		case_date4Begin			= @case_date4Begin,
		case_date4End			= @case_date4End,
		case_price				= @case_price,
		curr_id					= @curr_id,
		caset_id				= @caset_id,
		cust_id					= @cust_id,
		contact_id				= @contact_id,
		case_emailAdditional	= @case_emailAdditional,
		case_secondUpdate		= 'False',
		supp_id					= @supp_id,
		case_nextReviewdate		= @case_nextReviewdate

	WHERE	comp_id				= @comp_id
	AND		case_id				= @case_id




declare
	@user_origen		 int,
	@message			 varchar(4000),
	@subject			 varchar(4000),
	@body				 varchar(4000),
	@mail				 varchar(8000),
	@user_origen_name	 varchar(400),
	@user_mail_origin	 varchar(400),
	@user_origen_destiny varchar(400),
	@user_mail_destiny	 varchar(400),
	@optionid			 int,
	@desc				 varchar(2000)




--Datos del Usuario de Origen
select
	@user_origen_name = (tu.user_lastname + ',' + tu.user_firstname),
	@user_mail_origin = tu.user_email
from tbUser tu where tu.[user_id] = @user_id

set @optionid = 3512

--Datos del Usuario de Destino
select
	@user_origen_destiny = (tu.user_lastname + ',' + tu.user_firstname),
	@user_mail_destiny	 = tu.user_email
from tbUser tu where tu.[user_id] = @user_id

-- ---------------------------------------
-- Textos para armado del mail completo
DECLARE
	@lCaseSubject	VARCHAR(100),
	@CaseDesc		VARCHAR(100),
	@CaseResolution	VARCHAR(100),
	@date4begin		VARCHAR(100),
	@date2end		VARCHAR(100)

--ASUNTO
select @lCaseSubject	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300626
--DESCRIPCION
select @CaseDesc		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300627
--RESOLUCION
select @CaseResolution	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300628
--Fecha Inicio
select @date4begin		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300629
--Fecha Fin
select @date2end		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300630
-- ---------------------------------------


--Armado de Subject y Body

select @desc = tswn.word_desc
  from tbSysWordsNew tswn where tswn.lang_id = @lang_id and tswn.wordsi_id = @optionid

/*************************************************************************************/
/*En caso de poseer un TEXTO EN LA HEADER/FOOTER propia, utilizamos ese, sino        */
/*utilizamos el valor genérico de CRM de la UniqueTexts                              */
/*************************************************************************************/

	IF EXISTS (SELECT 1
	           FROM tbCRM_CaseMailHeaderFooter tccmhf WITH (NOLOCK)
	           WHERE	tccmhf.comp_id					= @comp_id AND
						tccmhf.cast_id					= @cast_id AND
						tccmhf.caset_id					= @caset_id AND
						ISNULL(tccmhf.crmhf_Subject,'') <> '')
		BEGIN
			SELECT
				@subject = tccmhf.crmhf_Subject
			  FROM tbCRM_CaseMailHeaderFooter		tccmhf WITH (NOLOCK)
			WHERE	tccmhf.comp_id		= @comp_id	AND
						tccmhf.cast_id	= @cast_id	AND
						tccmhf.caset_id	= @caset_id

		END
	ELSE
		BEGIN
			SELECT
				@subject = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30025

			set @subject = @subject + @desc

		END




select @message = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 985

select @body = tut.utexts_desc + ' ' + CONVERT(VARCHAR,@case_id)
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 986



set @mail = @desc								+ ' ' +
			@message							+ ' ' +
			@user_origen_name					+ ' ' +
			@body								+ ' ' +
			convert(varchar,@case_id) + ' ' + @lCaseSubject + ' ' + @case_subject + ' ' +
			@lCaseSubject + ' ' + @case_desc + ' ' + @CaseResolution + ' ' + @case_resolution + ' ' + @date4begin + ' ' + CONVERT(VARCHAR,@case_date4Begin) + ' ' +
			@date2end + ' ' + CONVERT(VARCHAR,@case_date4End)


-- ---------------------------------------------------------------
-- ARMADO DEL HTML PARA EL MAIL
-- ---------------------------------------------------------------
--ARMAMOS HEADER Y FOOTER EN CASO DE QUE HAYA VALORES EN LAS TABLAS

DECLARE @MailTableHeader AS NVARCHAR(MAX),
		@HeaderText		 AS NVARCHAR(MAX),
		@FooterText		 AS NVARCHAR(MAX)

SET @HeaderText = ''
SET @FooterText = ''

SELECT
	@HeaderText = tccmhf.htmlHeader,
	@FooterText = tccmhf.htmlFooter
FROM tbCRM_CaseMailHeaderFooter tccmhf
WHERE	tccmhf.comp_id	= @comp_id AND
		tccmhf.cast_id	= @cast_id AND
		tccmhf.caset_id = @caset_id

IF NOT LEN(@HeaderText) > 0
	SET @HeaderText = ''
IF NOT LEN(@FooterText) > 0
	SET @FooterText = ''

-- ---------------------------------------------------------------
-- ESTADO
DECLARE @Status			AS VARCHAR(MAX)
DECLARE @Case_Status	AS VARCHAR(MAX)

	SELECT @Status = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30022

	SELECT @Case_Status = tccs.cast_desc FROM tbCRM_CaseStatus tccs WHERE tccs.comp_id = @comp_id AND tccs.cast_id = @cast_id

--variables para el formateo del html email
	DECLARE	@MailTable							NVARCHAR(MAX),
			@MailEndTable						NVARCHAR(MAX),
			@Mailsubject						NVARCHAR(MAX),
			@MailbodyHeader						NVARCHAR(MAX),
			@Mailbody							NVARCHAR(MAX),
			@MailbodyFooter						NVARCHAR(MAX),
			@MailImageSRC						NVARCHAR(MAX),
			@MailCaseNotes						NVARCHAR(MAX)


SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
				 'cellpadding="1" cellspacing="1" border="1">'

SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
					  '<b>' + @subject + @desc + '</b><br /><br /><br />'


SET @Mailbody = ''
SET @MailBody =

	'<tr><td align="center">' +
		@desc + ' ' + @message + ' ' +  @user_origen_name  + ' ' +
	'</td><tr><td align="center">' +
	@body + ' ' +
	'</td></tr><td align="center">' +
	@lCaseSubject + ' ' + @case_subject + ' ' +
	'</td></tr><td align="center">' +
		@Status + ' ' + @Case_Status + ' ' +
	'</td><tr><td align="center">' +
	@CaseDesc + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@case_desc) + ' ' +
	'</td></tr><td align="center">' +
	@CaseResolution + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@case_resolution) + ' ' +
	'</td><tr><td align="center">' +
	@date4begin + ' ' + CONVERT(VARCHAR,@case_date4Begin) + ' ' +
	'</td><tr><td align="center">' +
	@date2end + ' ' + CONVERT(VARCHAR,@case_date4End)	  + ' ' +
	'</td></tr>'



-- ---------------------------------------------------------------------------------
-- ULTIMA CELDA CON LA ULTIMA NOTA DE LA TABLA CRM_TASKNOTES
-- ---------------------------------------------------------------------------------
	DECLARE
		@CaseNoteDesc	NVARCHAR(100),
		@CaseTitle		NVARCHAR(100),
		@CaseNote		NVARCHAR(MAX),
		@CaseDateTitle	NVARCHAR(100),
		@CaseCD			VARCHAR(100)

	SELECT @CaseTitle = tut.utexts_desc
	FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 240003

	SELECT @CaseDateTitle = tut.utexts_desc
	FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 240001

	SELECT @CaseNoteDesc = tut.utexts_desc
	FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 240002



	SELECT TOP 1
		@CaseCD		= ISNULL(tccn.casenote_cd, ''),
		@CaseNote	= ISNULL(tccn.casenote_Note,'')
	FROM tbCRM_CaseNote				tccn
	WHERE	tccn.comp_id = @comp_id AND
			tccn.case_id = @case_id
	ORDER BY tccn.casenote_cd DESC


	IF (@CaseCD <> '') AND (@CaseNote <> '')

		BEGIN

			SET @MailCaseNotes =
								'<tr><td align="center" bgcolor="#E6E6E6">'				+
									@CaseTitle											+ ' ' +
								'<tr><td align="center" bgcolor="#E6E6E6">'				+
									@CaseDateTitle	+ ' ' + @CaseCD						+ ' ' +
								'</td><tr><td align="center" bgcolor="#E6E6E6">'		+
									@CaseNoteDesc	+ ' ' +  @CaseNote					+ ' ' +
								'</td></tr>'

		END
	ELSE

		SET @MailCaseNotes = ''


-- ---------------------------------------------------------------------------------




SET @MailEndTable = + '</table>'

SET @MailbodyFooter = '</div>'






SET @Mailbody = @HeaderText + ' ' + @MailTable + ' ' + @Mailbody + @MailCaseNotes +  @MailEndTable + ' ' + @FooterText + ' ' + @MailbodyFooter
--SELECT @MailTable
--SELECT @Mailbody
--SELECT @MailEndTable
--SELECT @MailImageSRC


--STL
declare @description as nvarchar(500)

select
	@description = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 300060

set @description = @description + ' ' + convert(varchar,@case_id)

insert into tbSecurityLog
(
	comp_id,
	bra_id,
	user_id,
	seclog_obs_1,
	seclog_obs_2,
	seclog_image,
	seclog_obs_3,
	seclog_obs_4,
	seclog_cd,
	aut_id,
	sysCode_id,
	menu_id,
	menu_ts,
	request_ip,
	request_name,
	aure_isok,
	aure_user_id,
	seclog_pageHTML,
	prof_id,
	aure_cd,
	aure_id,
	seclog_id1,
	seclog_id2,
	seclog_id3
)
VALUES
(
	@comp_id,
	@bra_id,
	@user_id,
	@description,
	NULL,
	NULL,
	NULL,
	NULL,
	getdate(),
	NULL,
	1201,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	@prof_id,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL
)




-- -------------------------------------------------------
-- Obtenemos los mails a enviar a los grupos de usuarios
-- -------------------------------------------------------

declare
	@email_recipients	nvarchar(4000),
	@title				nvarchar(1000),
	@text				nvarchar(4000)

set @email_recipients = ''

--Obtengo el SUBJECT DEL MAIL
select @title = tut.utexts_desc
  from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 300068

--Obtengo el Cuerpo del Mail
select @text = tut.utexts_desc
  from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 300060

set @text = @text + ' ' + convert(varchar,@case_id) + ' ' + @mail


--Obtengo el listado de mails de las personas del grupo a enviar el mailing
select
	@email_recipients = @email_recipients + '; ' + tu.user_email

from tbCRM_UserGroups						tcug			WITH (NOLOCK)

	inner join tbCRM_UserGroupsDetail		tcugd			WITH (NOLOCK)
	on	tcugd.comp_id	= tcug.comp_id
	AND tcugd.crmug_id	= tcug.crmug_id

	inner join tbUser						tu				WITH (NOLOCK)
	on tu.[user_id] = tcugd.[user_id]

where	tcug.comp_id						= @comp_id
--and		tcugd.[user_id]						= @user_id --ESTA LINEA ES MI PROBLEMA
and		tcugd.crmug_id						in (select crmug_id
													from tbCRM_UserGroupsDetail tcugd2		WITH (NOLOCK)
													where	tcugd2.comp_id	 = @comp_id
													and		tcugd2.[user_id] = @user_id)
and		tcugd.crmugd_disabled				= 'False'
and     tcugd.crmugd_reciveEmailofChanges	= 'True'
-- ACA CAMBIAR PARA TAREAS, LLAMADAS y REUNIONES
and		tcugd.crmugd_4Case					= 'True'
and		(/*@caset_id = -1*/ tcugd.caset_id IS NULL or tcugd.caset_id	= @caset_id)

--
--if @email_recipients <> ''
--	begin
--		SET @email_recipients = SUBSTRING(@email_recipients,2,LEN(@email_recipients) - 1)
--
--		exec spSystem_sendEMail
--			@compId = @comp_id,
--			@precipients = @email_recipients,
--			@pcopy_recipients = null,
--			@psubject = @title,
--			@pbody_format = 'HTML',
--			@pbody = @MailBody ,
--			@pfile_attachments = null,
--			@pReplyTo = NULL,
--			@pblind_copy_recipients='',
--			@pUser_Id				= @user_id
--	END




-- -----------------------------------------------------------------------------
-- Envio del Mail
-- -----------------------------------------------------------------------------
	DECLARE @strMailString	AS NVARCHAR(MAX)
	DECLARE @strMail		AS NVARCHAR(MAX)
	DECLARE @strMailCC		AS NVARCHAR(MAX)
	DECLARE @strMailCCO		AS NVARCHAR(MAX)
	DECLARE @strMailFrom    AS NVARCHAR(MAX)
	SELECT  @strMailString	= dbo.fnCRM_GetCustomerEmailByCaseType(@comp_id, @cust_id, @caset_id, @cast_id, @case_id, @user_id)
	SELECT  @strMail		= dbo.fnSplitPosition(@strMailString, '|',1)
	SELECT  @strMailCC		= dbo.fnSplitPosition(@strMailString, '|',2)
	SELECT  @strMailCCO		= dbo.fnSplitPosition(@strMailString, '|',3)
	SELECT  @strMailFrom	= dbo.fnSplitPosition(@strMailString, '|',4)

	---- Mail al Usuario Asignado
	--exec spSystem_sendEMail
	--						@compId				= @comp_id,
	--						@precipients		= @user_mail_origin,
	--						@pcopy_recipients	= null,
	--						@psubject			= @subject,
	--						@pbody_format		= 'HTML',
	--						@pbody				= @MailBody,
	--						@pfile_attachments	= null,
	--						@pReplyTo			= @strMailFrom,
	--						@pblind_copy_recipients='',
	--						@pUser_Id			= @user_id

	-- Mail de Aviso a Clientes, Contactos, Adicionales, Etc.
	exec spSystem_sendEMail
							@compId					= @comp_id,
							@precipients			= @strMail,
							@pcopy_recipients		= @strMailCC,
							@psubject				= @subject,
							@pbody_format			= 'HTML',
							@pbody					= @Mailbody,
							@pfile_attachments		= null,
							@pReplyTo				= @strMailFrom,
							@pblind_copy_recipients	= @strMailCCO,
							@pUser_Id				= @user_id
	-- -----------------------------------------------------------------------------

-- ---------------------------------------------------------------

END
GO






CREATE PROCEDURE [dbo].[spCRM_CaseNotes_DeleteData]
(
	@comp_id			INT,
	@casenote_id			INT
)
AS SET NOCOUNT ON

	BEGIN

		DELETE FROM tbCRM_caseNote
		WHERE	comp_id		 = @comp_id		AND
				casenote_id  = @casenote_id




	END

GO







CREATE PROCEDURE [dbo].[spCRM_CaseNotes_GetDataByFilters]
(
	@comp_id										INT,
	@lang_id										INT,
	@bra_id											INT,
	@prof_id										INT,
	@user_id										INT,
	@case_id										INT
)

AS SET NOCOUNT ON


BEGIN


-- --------------------------------------
-- Testing
-- --------------------------------------
/*
	DECLARE
				@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@prof_id				INT,
				@user_id				INT,
				@case_id				INT

	SELECT
				@comp_id				= 1,
				@lang_id				= 2,
				@bra_id					= 1,
				@prof_id				= 1,
				@user_id				= 3,
				@case_id				= 989
*/
-- --------------------------------------



	SELECT	' '															[ ],
			' '															[ ],
			tctn.casenote_cd											[casenote_cd],
			tu.user_lastname + ', ' + tu.user_firstname					[User_Name],
			ISNULL(tctn.casenote_Note,'')								[note1],
			ISNULL(tctn.casenote_Price,0)								[casenote_Price],
			tctn.casenote_id											[ID]

	FROM tbCRM_caseNote									tctn

		INNER JOIN tbCRM_case							tct
		ON  tct.comp_id		= tctn.comp_id AND
			tct.case_id		= tctn.case_id

		INNER JOIN tbUser								tu
		ON  tu.[user_id]	= tctn.[user_id]

		LEFT JOIN tbProfile								tp
		ON  tp.comp_id		= tctn.comp_id AND
			tp.prof_id		= tctn.prof_id


	WHERE	tctn.comp_id			= @comp_id					AND
			tctn.case_id			= @case_id					--AND
			--tctn.prof_id			= @prof_id


	ORDER BY tctn.casenote_cd desc



END


GO


