CREATE PROCEDURE [dbo].[spCRM_CaseStatus_getCombo]
(
	@comp_id			INT,
	@status				INT,	-- @status  -1 Update; -2 Insert; -3 Todos
	@prof_id			INT,
	@cast_id			INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo
	@user_id			INT,
	@bra_id				INT
)
AS


	-- --------------------------------------------
	-- Testing
	-- --------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@status		INT,
		@prof_id	INT,
		@cast_id	INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo
		@user_id	INT,
		@bra_id		INT

		SET @comp_id	= 1
		SET @status		= -1
		SET @prof_id	= 1
		SET @cast_id	= 4
		SET @user_id	= 41
		SET @bra_id		= 1
	*/
	-- --------------------------------------------

	SET NOCOUNT ON


	DECLARE @bitActualStatusIsInitial	AS BIT
	DECLARE @bitUserCanSetInitialStatus AS BIT
	SET		@bitActualStatusIsInitial	= 'False'
	SET		@bitUserCanSetInitialStatus = 'False'


	SELECT	@bitActualStatusIsInitial	= IsNull(tcts.cast_isInitialStatus,'False'),
			@bitUserCanSetInitialStatus = IsNull(tu.user_available4CRM_CanReAsignateTask,'False')
		FROM tbCRM_CaseStatus tcts				WITH (NOLOCK)
		INNER JOIN tbUser tu					WITH (NOLOCK)
			ON	tu.[user_id] = @user_id
		WHERE	tcts.comp_id = @comp_id AND
				tcts.cast_id = @cast_id




	IF  EXISTS(
				SELECT 1
					FROM tbCRM_CaseStatus2Profile tcttp							WITH (NOLOCK)
					INNER JOIN tbCRM_CaseStatus tcts							WITH (NOLOCK)
						ON	tcts.comp_id		= tcttp.comp_id AND
							tcts.cast_id		= tcttp.cast_id
					WHERE	tcttp.comp_id		= @comp_id		AND
							tcttp.bra_id		= @bra_id		AND
							tcttp.prof_id		= @prof_id		AND
							tcttp.disabled		= 'False'		AND
							tcts.cast_disabled	= 'False'
				)
		BEGIN

			SELECT	tcts.cast_id		[Id],
					CASE
						WHEN tcts.cast_isInitialStatus		= 'True' THEN	'1'
						WHEN tcts.cast_isFinalStatus		= 'True' THEN	'3'
						ELSE												'2'
					END + ' | ' +
					tcts.cast_desc		[Desc]

				FROM	   tbCRM_CaseStatus						tcts			WITH (NOLOCK)
				LEFT JOIN  tbCRM_CaseStatus2Profile				tcttp			WITH (NOLOCK)
					ON	tcttp.comp_id		= tcts.comp_id	AND
						tcttp.bra_id		= @bra_id		AND
						tcttp.cast_id		= tcts.cast_id	AND
						tcttp.prof_id		= @prof_id
				WHERE		tcts.comp_id	= @comp_id 							AND
							(
								(
									(
										tcttp.comp_id		IS NOT NULL			AND
										tcttp.disabled		= 'False'			AND
										tcts.cast_disabled	= 'False'
									)

									AND

									CASE
										WHEN	@status	 = -1											AND
												ISNULL(tcts.cast_isInitialStatus,'False')	= 'True'	AND
												@bitActualStatusIsInitial					= 'False'	AND
												@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
										WHEN   (@status	 = -1	AND ISNULL(tcts.cast_isInitialStatus, 'False')	= 'False')	THEN	'True'
										WHEN   (@status	 = -2	AND ISNULL(tcts.cast_isInitialStatus, 'False')	= 'True')	THEN	'True'
										WHEN    @status	 = -3																THEN	'True'
										ELSE																						'False'
									END = 'True'
								)

								OR

								tcts.cast_id	=	@cast_id
							)
				ORDER BY	tcts.cast_desc

		END

	ELSE

		BEGIN

			SELECT		tcts.cast_id		[Id],
						CASE
							WHEN tcts.cast_isInitialStatus		= 'True' THEN	'1'
							WHEN tcts.cast_isFinalStatus		= 'True' THEN	'3'
							ELSE												'2'
						END + ' | ' +
						tcts.cast_desc		[Desc]

				FROM		tbCRM_CaseStatus																tcts			WITH (NOLOCK)

				WHERE		tcts.comp_id	=	@comp_id 													AND
							(
								(
									(tcts.prof_id IS NULL OR tcts.prof_id = @prof_id AND tcts.cast_disabled = 'False')	AND
									CASE
										WHEN	@status	 = -1											AND
												ISNULL(tcts.cast_isInitialStatus,'False')	= 'True'	AND
												@bitActualStatusIsInitial					= 'False'	AND
												@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
										WHEN   (@status	 = -1	AND ISNULL(tcts.cast_isInitialStatus, 'False')	= 'False')	THEN	'True'
										WHEN   (@status	 = -2	AND ISNULL(tcts.cast_isInitialStatus, 'False')	= 'True')	THEN	'True'
										WHEN    @status	 = -3																THEN	'True'
										ELSE																						'False'
									END = 'True'
								)
								OR
								@cast_id = tcts.cast_id
							)
				ORDER BY	tcts.cast_desc

		END



GO







