CREATE procedure [dbo].[spCRM_CaseType_getCombo]
(
	@comp_id			INT,
	@prof_id			INT,
	@caset_id			INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo. -9 trae TODOS
	@user_id			INT,
	@bra_id				INT
)
as



BEGIN

	set NOCOUNT on


	-- ---------------------------------------------
	-- Testing
	-- ---------------------------------------------
	/*
	DECLARE
	@comp_id			INT,
	@prof_id			INT,
	@caset_id			INT,
	@user_id			INT,
	@bra_id				INT
	SET @comp_id	= 1
	SET @prof_id	= 1
	SET @caset_id	= -1
	SET @user_id	= 41
	SET @bra_id		= 1
	*/
	-- ---------------------------------------------


	IF EXISTS(
				SELECT 1
					FROM tbCRM_CaseType2Profile tcttp
					INNER JOIN tbCRM_CaseType tctt
						ON	tctt.comp_id		= tcttp.comp_id AND
							tctt.caset_id		= tcttp.caset_id
					WHERE	tcttp.comp_id		= @comp_id	AND
							tcttp.bra_id		= @bra_id	AND
							tcttp.prof_id		= @prof_id	AND
							tcttp.[disabled]	= 'False'	AND
							tctt.caset_disabled = 'False'
				)
		BEGIN

				SELECT		tctt.caset_id	[Id],
							tctt.caset_desc	[Desc]
					FROM		tbCRM_CaseType			tctt
					LEFT JOIN	tbCRM_CaseType2Profile	tcttp
						ON	tcttp.comp_id		= tctt.comp_id		AND
							tcttp.caset_id		= tctt.caset_id		AND
							tcttp.prof_id		= @prof_id			AND
							tcttp.bra_id		= @bra_id
				    WHERE
							(
								tctt.comp_id		= @comp_id			AND
				    			tctt.caset_disabled	= 'False'			AND
								tcttp.disabled		= 'False'			AND
								tcttp.comp_id		IS NOT NULL
							)
							OR
							tctt.caset_id	= @caset_id
					ORDER BY tctt.caset_desc

		END

	ELSE

		BEGIN

			select
				tctt.caset_id	[Id],
				tctt.caset_desc	[Desc]
				from tbCRM_CaseType tctt			WITH (NOLOCK)
				where	tctt.comp_id		= @comp_id	AND
					   (
			   				tctt.caset_id	= @caset_id
			   				OR
							(
								(tctt.prof_id IS NULL OR tctt.prof_id = @prof_id)	AND
								 tctt.caset_disabled = 'False'
							)
					   )
				order by [Desc]

		END
END
GO







