CREATE PROCEDURE [dbo].[spCRM_Document_getDataById]
(

	@comp_id								INT,
	@lang_id								INT,
	@bra_id									INT,
	@prof_id								INT,
	@user_id								INT,
	@doc_id									INT

)

AS
SET NOCOUNT ON

BEGIN

	--------------------------------------------------------
	-------------parametros de prueba-----------------------
	--------------------------------------------------------
	/*
	declare		@comp_id			INT,
				@doc_id				INT

	select		@comp_id			= 1,
				@doc_id				= 1
*/
	--------------------------------------------------------
	--------------------------------------------------------
	--------------------------------------------------------


	SELECT	isnull(tcd.dt_id,-1)						[dt_id],
			tcd.doc_versionCounter						[doc_versionCounter],
			tcd.doc_profilesRelatedMustCheck			[doc_profilesRelatedMustCheck],
			isnull(tcd.prof_id2Check,-1)				[prof_id2Check],
			tcd.case_id,
			tcd.task_id

	FROM	tbCRM_Document						tcd

	left JOIN tbCRM_DocumentType				tcdt
	ON	tcdt.comp_id	= tcd.comp_id AND
		tcdt.dt_id		= tcd.dt_id

	WHERE	tcd.comp_id			= @comp_id
	AND		tcd.doc_id			= @doc_id

END



GO








CREATE PROCEDURE [dbo].[spCRM_Document_insertData]
(
	@comp_id								INT,
	@lang_id								INT,
	@bra_id									INT,
	@prof_id								INT,
	@user_id								INT,


	@dt_id									INT,
	@doc_versionCounter						INT,
	@doc_profilesRelatedMustCheck			BIT,
	@prof_id2Check							INT,
	@doc_desc								NVARCHAR(500),
	@case_id								INT,
	@task_id								INT,

	@return_value							INT OUTPUT
)
AS
SET NOCOUNT ON


BEGIN

	DECLARE @lcase_id AS INT
	DECLARE @ltask_id AS INT

	SET @lcase_id = @case_id
	SET @ltask_id = @task_id

	IF @case_id = -1
		SET @lcase_id = NULL
	IF @task_id = -1
		SET @ltask_id = NULL


	INSERT INTO tbCRM_Document
	(
		comp_id,
		dt_id,
		doc_versionCounter,
		doc_profilesRelatedMustCheck,
		prof_id2Check,
		doc_desc,
		case_id,
		task_id
	)
	VALUES
	(
		@comp_id,
		@dt_id,
		@doc_versionCounter,
		@doc_profilesRelatedMustCheck,
		@prof_id2Check,
		@doc_desc,
		@lcase_id,
		@ltask_id
	)


	SET @return_value = @@IDENTITY


END
GO








CREATE PROCEDURE [dbo].[spCRM_Document_updateData]
(
	@comp_id								INT,
	@lang_id								INT,
