	@user_id								INT,


	@dt_id									INT,
	@doc_versionCounter						INT,
	@doc_profilesRelatedMustCheck			BIT,
	@prof_id2Check							INT,
	@doc_id									INT


)
AS
SET NOCOUNT ON


-- --------------------------------------
-- TESTING
-- --------------------------------------
/*


declare	@comp_id								INT,
		@lang_id								INT,
		@bra_id									INT,
		@prof_id								INT,
		@user_id								INT,

		@dt_id									INT,
