		prof_id2Check					= @prof_id2Check


	WHERE	comp_id						= @comp_id
	AND		doc_id						= @doc_id






END
GO





CREATE PROCEDURE [dbo].[spCRM_DocumentsGetDataByFilters]
(
	@comp_id	INT,
	@prof_id	INT,
	@dt_id		INT,
	@user_id	INT,
	@bra_id		INT,
	@lang_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS SET NOCOUNT ON

BEGIN

	SET DATEFORMAT 'ymd'

-- ---------------------------------
-- Testing
-- ---------------------------------
/*
	DECLARE
		@comp_id	INT,
		@doc_id		INT,
		@prof_id	INT,
		@dt_id		INT
	SELECT
		@comp_id	= 1,
		@doc_id		= 1,
		@prof_id	= 1,
		@dt_id		= -1
*/
-- ---------------------------------

	SELECT
		' '																				[+],
		' '																				[ ],
		convert(bit,case
								when tct2.comp_id is null then 'false'
								else 'true'
							end)														[filter],
		ISNULL(tcdv.doc_filename,'')													[doc_filename],
		tcdt.dt_desc,
		tcdv.doc_cd,
		tcdv.doc_version,
		tcd.doc_versionCounter,
		ISNULL(tcdvir.docvu_isReaded,'False')											[docvu_isReaded],
		ISNULL(tcdvir.docvu_isreadedDate,GETDATE())										[docvu_isreadedDate],
		tu.user_lastname + ',' + tu.user_firstname										[docvu_userOfThisVersion],
		IsNull(tud.user_lastname,'') + ',' + IsNull(tud.user_firstname,'')				[docvu_userDeleteThisVersion],
		ISNULL(tcdv.doc_disabled,'False')												[doc_disabled],
		ISNULL(tcd.doc_desc,'')															[doc_desc],
		ISNULL(tcc.case_subject,'')														[case_id],
		ISNULL(tct.task_subject,'')														[task_id],
		CONVERT(VARCHAR,tcd.doc_id) + '-' + CONVERT(VARCHAR,tcdv.doc_version)			[ID]

	FROM tbCRM_Document								tcd				WITH (NOLOCK)

		LEFT JOIN tbCRM_tmp							tct2			WITH (NOLOCK)
			ON	tct2.comp_id			= tcd.comp_id	AND
				tct2.crmt_function		= 5				AND -- Aquí es el unico caso en que se suma UNO, no se que MIERDA hizo el HDP que armo esta parte!!!  (0 Case;1 Task;2 Call;3 Meet; 4 Correos; 5 Document)
				tct2.crmt_function_id	= tcd.doc_id	AND
				tct2.crmt_guid			= @guid

		INNER JOIN tbCRM_DocumentType					tcdt		WITH (NOLOCK)
			ON	tcdt.comp_id		= tcd.comp_id	AND
				tcdt.dt_id			= tcd.dt_id


		INNER JOIN tbCRM_DocumentTypeRelation2Profile	tcdtrp		WITH (NOLOCK)
			ON	tcdtrp.comp_id		= tcdt.comp_id	AND
				tcdtrp.dt_id		= tcdt.dt_id

		INNER JOIN tbCRM_DocumentVersion				tcdv		WITH (NOLOCK)
			ON	tcdv.comp_id		= tcd.comp_id	AND
				tcdv.doc_id			= tcd.doc_id

		LEFT JOIN tbCRM_DocumentVersionIsReaded			tcdvir		WITH (NOLOCK)
			ON	tcdvir.comp_id		= tcdv.comp_id		AND
				tcdvir.doc_id		= tcdv.doc_id		AND
				tcdvir.doc_version	= tcdv.doc_version	AND
				tcdvir.[user_id]	= @user_id

		INNER JOIN tbUser								tu			WITH (NOLOCK)
			ON tu.[user_id] = 	tcdv.[user_id]

		LEFT JOIN tbUser								tud			WITH (NOLOCK)
			ON tud.[user_id] = 	tcdv.user_id_disabled

		INNER JOIN tbBranch								tb			WITH (NOLOCK)
			ON	tb.comp_id	= tcdv.comp_id AND
				tb.bra_id	= tcdv.bra_id

		INNER JOIN vwCRM_DocumentVersion				vwv			WITH (NOLOCK)
			ON	vwv.comp_id = tcdv.comp_id	AND
				vwv.doc_id  = tcdv.doc_id	AND
			  (	vwv.Version = tcdv.doc_version OR tcdtrp.dtr_viewAllVersionDocuments = 'True')

		LEFT JOIN tbCRM_Case							tcc			WITH (NOLOCK)
			ON	tcc.comp_id = tcd.comp_id	AND
				tcc.case_id = tcd.case_id

		LEFT JOIN tbCRM_Task							tct			WITH (NOLOCK)
			ON	tct.comp_id	= tcd.comp_id	AND
				tct.task_id	= tcd.task_id

	WHERE	tcd.comp_id			= @comp_id									AND
			tcdtrp.prof_id		= @prof_id									AND
			(@dt_id				= -1	   OR tcdtrp.dt_id		= @dt_id)   AND
			tcdt.dt_disabled	= 'False'									AND
			(tcdtrp.dtr_viewDisabledDocuments = 'True' OR (tcdtrp.dtr_viewDisabledDocuments='False' AND tcdv.doc_disabled='False' ) )

			and		(
						(tcd.comp_id not in (	select top 1 tct2.comp_id
													from tbCRM_tmp tct2
													where tct2.comp_id = @comp_id
													and tct2.crmt_function = 1
													and tct2.crmt_guid = @guid))		or

						(tcd.case_id in (		select tct2.crmt_function_id
													from tbCRM_tmp tct2
													where tct2.comp_id = @comp_id
													and tct2.crmt_function = 1
													and tct2.crmt_guid = @guid))
					)

			and		(
						(tcd.comp_id not in (	select top 1 tct2.comp_id
													from tbCRM_tmp tct2
													where tct2.comp_id = @comp_id
													and tct2.crmt_function = 2
													and tct2.crmt_guid = @guid))		or

						(tcd.task_id in (		select tct2.crmt_function_id
													from tbCRM_tmp tct2
													where tct2.comp_id = @comp_id
													and tct2.crmt_function = 2
													and tct2.crmt_guid = @guid))
					)


END
GO





