CREATE PROCEDURE spCRM_DocumentVersion_DisableDocument
(
	@comp_id		INT,
	@doc_id			INT,
	@doc_version	INT,
	@user_id		INT
)
AS

	SET NOCOUNT ON

		BEGIN
			--Obtenemos el Estado Previo del Documento
			-- -----------------------------------------------
			DECLARE @PreviousState AS BIT

			SELECT @PreviousState		= tcdv.doc_disabled
			FROM tbCRM_DocumentVersion tcdv
			WHERE	tcdv.comp_id		= @comp_id AND
					tcdv.doc_id			= @doc_id AND
					tcdv.doc_version	= @doc_version
			-- -----------------------------------------------

			IF @PreviousState = 'True'

				BEGIN

					UPDATE tbCRM_DocumentVersion
					SET
						doc_disabled			= ~ doc_disabled,
						user_id_disabled	= NULL


					WHERE	comp_id		= @comp_id			AND
							doc_id		= @doc_id			AND
							doc_version = @doc_version

				END
			ELSE
				BEGIN

					UPDATE tbCRM_DocumentVersion
					SET
						doc_disabled			= ~ doc_disabled,
						user_id_disabled	= @user_id


					WHERE	comp_id		= @comp_id			AND
							doc_id		= @doc_id			AND
							doc_version = @doc_version

				END






		END

GO





CREATE PROCEDURE [dbo].[spCRM_DocumentVersion_getDataById]
(
	@comp_id		INT,
	@doc_id			INT,
	@doc_version	INT,
	@user_id		INT
)
AS SET NOCOUNT ON

	BEGIN

		-- --------------------------------------
		-- TESTING
		-- --------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@doc_id			INT,
				@doc_version	INT,
				@user_id		INT

			SELECT
				@comp_id		= 1,
				@doc_id			= 10,
				@doc_version	= 1,
				@user_id		= 1
		*/
		-- --------------------------------------

		SELECT
			tcdv.comp_id,
			tcdv.doc_id,
			tcdv.doc_version,
			tcdv.[user_id],
			tcdv.doc_cd,
			tcdv.bra_id,
			tcdv.doc_filename,
			tcdv.doc_file

		FROM tbCRM_DocumentVersion						tcdv

			LEFT JOIN tbCRM_DocumentVersionIsReaded		tcdvir
			ON	tcdvir.comp_id			= tcdv.comp_id		AND
				tcdvir.doc_id			= tcdv.doc_id		AND
				tcdvir.doc_version		= tcdv.doc_version	AND
				tcdvir.[user_id]		= @user_id			AND
				tcdvir.docvu_isReaded	= 'False'

		WHERE	tcdv.comp_id			= @comp_id			AND
				tcdv.doc_id				= @doc_id			AND
				tcdv.doc_version		= @doc_Version		--AND
				--tcdvir.[user_id]		= @user_id			AND
				--tcdvir.docvu_isReaded	= 'False'

	END
GO




CREATE PROCEDURE [dbo].[spCRM_DocumentVersion_GetLatestVersion]
(
	@comp_id	INT,
	@doc_id		INT
)
AS SET NOCOUNT ON

BEGIN
	-- -------------------------------
	-- Testing
	-- -------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@doc_id		INT
		SELECT
			@comp_id	= 1,
			@doc_id		= 1
	*/
	-- -------------------------------

	SELECT
		TOP 1 tcdv.doc_version
	FROM tbCRM_DocumentVersion			tcdv
		INNER JOIN tbCRM_Document		tcd
		ON	tcd.comp_id = tcdv.comp_id	AND
			tcd.doc_id	= tcdv.doc_id

	WHERE	tcd.comp_id = @comp_id		AND
			tcd.doc_id	= @doc_id

	ORDER BY tcdv.doc_version DESC
END
GO




CREATE PROCEDURE [dbo].[spCRM_DocumentVersion_InsertData]
(
	@comp_id		INT,
	@doc_id			INT,
	@doc_version	INT,
	@user_id		INT,
	@bra_id			INT,
	@doc_filename	NVARCHAR(250),
	@doc_file		IMAGE
)

AS SET NOCOUNT ON

	BEGIN

		SET DATEFORMAT 'ymd'

		-- ----------------------------------------
		-- TESTING
		-- ----------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@doc_id			INT,
				@doc_version	INT,
				@user_id		INT,
				@doc_cd			DATETIME,
				@bra_id			INT,
				@doc_filename	NVARCHAR(250),
				@doc_file		IMAGE

			SELECT
				@comp_id		= 1,
				@doc_id			= 1,
				@doc_version	= 1,
				@user_id		= 1,
				@doc_cd			= '2013-12-31',
				@bra_id			= 1,
				@doc_filename	= 'ArchivoLoco',
				@doc_file		= NULL
		*/
		-- ----------------------------------------

		--OBTENEMOS LA ULTIMA VERSION DEL ARCHIVO
		DECLARE @Doclastversion AS INT

		IF EXISTS (SELECT 1 FROM tbCRM_DocumentVersion tcdv WHERE tcdv.comp_id = @comp_id AND tcdv.doc_filename = @doc_filename)
			BEGIN
				SELECT TOP 1 @Doclastversion = CONVERT(INT,tcdv.doc_version) + 1
				  FROM tbCRM_DocumentVersion tcdv WHERE tcdv.comp_id = @comp_id AND tcdv.doc_filename = @doc_filename
				ORDER BY tcdv.doc_version DESC
			END
		ELSE
			BEGIN
				SET @Doclastversion = 1
			END


			INSERT INTO tbCRM_DocumentVersion
			(
				comp_id,
				doc_id,
				doc_version,
				[user_id],
				doc_cd,
				bra_id,
				doc_filename,
				doc_file
			)
			VALUES
			(
				@comp_id,
				@doc_id,
				@Doclastversion,
				@user_id,
				GETDATE(),
				@bra_id,
				@doc_filename,
				@doc_file
			)
	END
GO




CREATE PROCEDURE [dbo].[spCRM_DocumentVersionIsReaded_InsertData]
(
	@comp_id				INT,
	@doc_id					INT,
	@doc_version			INT,
	@user_id				INT,
	@docvu_isReaded			BIT
)
AS SET NOCOUNT ON

	SET DATEFORMAT 'ymd'

	BEGIN

		-- --------------------------------------
		-- TESTING
		-- --------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@doc_id					INT,
				@doc_version			INT,
				@user_id				INT,
				@docvu_isReaded			BIT,
				@docvu_isreadedDate		DATETIME

			SELECT
				@comp_id				= 1,
				@doc_id					= 1,
				@doc_version			= 1,
				@user_id				= 1,
				@docvu_isReaded			= 'False',
				@docvu_isreadedDate		= '2013-12-31'
		*/
		-- --------------------------------------

		IF NOT EXISTS (SELECT 1 FROM tbCRM_DocumentVersionIsReaded tcdvir
					   WHERE	tcdvir.comp_id		= @comp_id		AND
								tcdvir.doc_id		= @doc_id		AND
								tcdvir.doc_version	= @doc_version	AND
								tcdvir.[user_id]	= @user_id)

			BEGIN
				INSERT INTO tbCRM_DocumentVersionIsReaded
				(
					comp_id,
					doc_id,
					doc_version,
					[user_id],
					docvu_isReaded,
					docvu_isreadedDate
				)
				VALUES
				(
					@comp_id,
					@doc_id,
					@doc_version,
					@user_id,
					@docvu_isReaded,
					GETDATE()
				)

			END
		END
GO




