CREATE PROCEDURE [dbo].[spCRM_GetDesc]
(
	@comp_id			INT,
	@lang_id			INT,
	@option				int,
	@id					int
)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	------------------------------------------------------------------------------
	--PARAMETROS PARA PRUEBAS ----------------------------------------------------
	------------------------------------------------------------------------------

/*

	DECLARE

			@comp_id			INT,
			@lang_id			INT,
			@option				int,
			@id					int

	SELECT

			@comp_id			= 1,
			@lang_id			= 2,
			@option				= 1,
			@id					= 2


*/
	-----------------------------------------------------------------------------
	------------------------------------------------------------------------------
	------------------------------------------------------------------------------


	if @option = 0

		BEGIN

				select	isnull(case_desc,'')	[description],
						user_id					[user_id],
						case_subject			[Subject]
					from tbCRM_Case  WITH (NOLOCK)
					WHERE	comp_id = @comp_id AND
							case_id = @id

		END

	else if @option = 1

		BEGIN

			select	isnull(task_desc,'')		[description],
					user_id						[user_id],
					task_subject				[Subject]
				from tbCRM_Task			WITH (NOLOCK)
				WHERE	comp_id = @comp_id AND
						task_id = @id

		END

	ELSE if @option = 2

		BEGIN

		    select	isnull(tcc.call_description,'')	[description],
					user_id							[user_id],
					tcc.call_description			[Subject]
				from tbCRM_Call tcc		WITH (NOLOCK)
				WHERE	comp_id = @comp_id AND
						call_id = @id
		END

	else if @option = 3

		BEGIN

			select	isnull(tcm.meet_description,'')	[description],
					user_id							[user_id],
					tcm.meet_subject				[Subject]
				from tbCRM_Meet tcm		WITH (NOLOCK)
				WHERE	comp_id = @comp_id AND
						meet_id = @id

		END

	else if @option = 4

		BEGIN

			select	isnull(tcm.crmm_subject,'')	[description],
					user_id							[user_id],
					tcm.crmm_subject				[Subject]
			FROM tbCRM_Mails  tcm		WITH (NOLOCK)
				WHERE	tcm.comp_id = @comp_id AND
						tcm.crmm_id = @id

		END

END
GO





CREATE PROCEDURE [dbo].[spCRM_ItemSerialExistsData]
(
	@comp_id	INT,
	@item_id	INT,
	@is_serial	NVARCHAR(100)
)
AS

	-- -----------------------------
	-- TESTING
	-- -----------------------------
	/*
		DECLARE
			@comp_id	INT,
			@item_id	INT,
			@is_serial	NVARCHAR(50)
		SELECT
			@comp_id	= 1,
			@item_id	= 256,
			@is_serial	= 'V09300G10400533'
	*/
	-- -----------------------------

	SET NOCOUNT ON

		BEGIN
			--VARIABLE DE TRABAJO
			DECLARE
				@lis_id	INT

			--PREGUNTAMOS SI EXISTE EL # DE SERIE EN LA TBITEMSERIALS
			IF EXISTS (SELECT TOP 1  1
						   FROM		tbItemSerials				tis	WITH (NOLOCK)
						   WHERE	tis.comp_id		= @comp_id	AND
									tis.is_serial	= @is_serial)

				BEGIN

					--SI EXISTE LO GRABAMOS EN LA VARIABLE LOCAL
					SELECT
							@lis_id			= tis.is_id
					FROM	tbItemSerials				tis	WITH (NOLOCK)
					WHERE	tis.comp_id		= @comp_id	AND
							tis.is_serial	= @is_serial

					--SELECT @lis_id

					--PREGUNTAMOS SI EXISTE ALGÚN CASO O TAREA CON
					--ESE # DE SERIE ASIGNADO PARA QUE NO PUEDA VOLVER
					--A ASIGNARSE

						DECLARE
							@lHasCase	BIT,
							@lHasTask	BIT

						--LOS SETEAMOS EN FALSO
						SET @lHasCase = 'False'
						SET @lHasTask = 'False'

						--TIENE UN CASO ASIGNADO?
						IF EXISTS (SELECT TOP 1  1
									   FROM tbCRM_Case				tcc	WITH (NOLOCK)
									   WHERE tcc.comp_id = @comp_id	AND
											 tcc.is_id	 = @lis_id)

							SET @lHasCase = 'True'


						--TIENE UNA TAREA ASIGNADA?
						IF EXISTS (SELECT TOP 1  1
									   FROM tbCRM_Task				tct	WITH (NOLOCK)
									   WHERE tct.comp_id = @comp_id AND
											 tct.is_id	 = @lis_id)

							SET @lHasTask = 'True'



						--SI NO POSEE NI CASOS NI TAREAS DEVUELVE 0 (CERO)
						--PERO SI LLEGASE A POSEER ALGUNA DE LAS DOS
						-- DEVOLVERA EL IS_ID OBTENIDO DE LA tbItemSerials
						IF (@lHasCase = 'False') AND (@lHasTask = 'False')
							SELECT @lis_id
						ELSE
							BEGIN
								SET @lis_id = 0
								SELECT @lis_id
							END
				END
			ELSE
				BEGIN
					SET @lis_id = 0
					SELECT @lis_id
				END

		END
GO

