CREATE PROCEDURE [dbo].[spCRM_Mails_getMails2Process]
	@comp_id AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SELECT	tumar.comp_id,
			tumar.ue_id,
			tumar.ue_pop3ServerName,
			tumar.ue_UserName,
			tumar.ue_UserPassword,
			tumar.[user_id],
			tumar.ue_desc,
			tumar.ue_SSL,
			tumar.ue_PortNumber
		FROM tbUserMailsAccountsRelation tumar				WITH (NOLOCK)
			inner JOIN tbCompany tc							WITH (NOLOCK)
				ON tc.comp_id	= tumar.comp_id
			INNER JOIN tbuser	tu							WITH (NOLOCK)
				ON tu.[user_id] = tumar.[user_id]
		WHERE
				tumar.ue_disabled				= 'False'	AND
				IsNull(tu.user_Blocked,'False') = 'False'	AND
				tumar.comp_id					= @comp_id



END
GO







CREATE PROCEDURE [dbo].[spCRM_Meet_deleteData]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@lang_id			INT,

	@meet_id			INT
)
AS
SET NOCOUNT ON


BEGIN

	-- -----------------------------------------------------------------------------------------------------------
	--ACA BORRAMOS EL HISTORICO EN CASO DE PODER HACERLO EN BASE AL USUARIO QUE REALIZA LA ACCIÓN!
	-- -----------------------------------------------------------------------------------------------------------
	--VARIABLE PARA SABER SI PUEDE O NO BORRAR EL HISTORIAL
	DECLARE
		@lbitCanDeleteHistory	BIT

	IF EXISTS(SELECT 1
			  FROM tbControlProfiles			tcp1
			  WHERE	tcp1.comp_id	= @comp_id	AND
					tcp1.bra_id		= @bra_id	AND
					tcp1.prof_id	= @prof_id	AND
					tcp1.ctrl_id	= 2878		AND
					tcp1.page_id	= 9000)

		SET @lbitCanDeleteHistory = 'True'

	ELSE

		SET @lbitCanDeleteHistory = 'False'

	--SI EL CONTROL ESTA HABILITADO PARA BORRAR, BORRA TODOS LOS DETALLES ASOCIADOS AL @MEET_ID
	IF @lbitCanDeleteHistory = 'True'

		DELETE FROM tbCRM_MeetHistory WHERE comp_id = @comp_id AND meet_id = @meet_id


	-- -----------------------------------------------------------------------------------------------------------

declare
	@meett_id	INT

select @meett_id = tcm.meett_id
  from tbCRM_Meet tcm where tcm.comp_id = @comp_id and tcm.meet_id = @meet_id


	DELETE FROM tbCRM_Meet

	WHERE	comp_id = @comp_id
	AND		meet_id = @meet_id


declare
	@msg	nvarchar(1000)

select @msg = (tut.utexts_desc + ' ' + convert(varchar,@meet_id)) from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 988


--STL
declare @description as nvarchar(500)

select
	@description = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 300067

set @description = @description + ' ' + convert(varchar,@meet_id)

insert into tbSecurityLog
(
	comp_id,
	bra_id,
	user_id,
	seclog_obs_1,
	seclog_obs_2,
	seclog_image,
	seclog_obs_3,
	seclog_obs_4,
	seclog_cd,
	aut_id,
	sysCode_id,
	menu_id,
	menu_ts,
	request_ip,
	request_name,
	aure_isok,
	aure_user_id,
	seclog_pageHTML,
	prof_id,
	aure_cd,
	aure_id,
	seclog_id1,
	seclog_id2,
	seclog_id3
)
VALUES
(
	@comp_id,
	@bra_id,
	@user_id,
	@description,
	NULL,
	NULL,
	NULL,
	NULL,
	getdate(),
	NULL,
	1302,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	@prof_id,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL
)


-- -------------------------------------------------------
-- Obtenemos los mails a enviar a los grupos de usuarios
-- -------------------------------------------------------

declare
	@email_recipients	nvarchar(4000),
	@title				nvarchar(1000),
	@text				nvarchar(1000)

select @title = tut.utexts_desc
  from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 300075

select @text = tut.utexts_desc
  from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 300067

set @text = @text + ' ' + convert(varchar,@meet_id)

set @email_recipients = ''

select
	@email_recipients = @email_recipients + '; ' + tu.user_email

	from tbCRM_UserGroups						tcug

		inner join tbCRM_UserGroupsDetail		tcugd
		on	tcugd.comp_id	= tcug.comp_id
		AND tcugd.crmug_id	= tcug.crmug_id

		inner join tbUser						tu
		on tu.[user_id] = tcugd.[user_id]

	where	tcug.comp_id						= @comp_id
	--and		tcugd.user_id						= @user_id
	and		tcugd.crmug_id						in (select crmug_id
														from tbCRM_UserGroupsDetail tcugd2
														where	tcugd2.comp_id	 = @comp_id
														and		tcugd2.[user_id] = @user_id)
	and		tcugd.crmugd_disabled				= 'False'
	and     tcugd.crmugd_reciveEmailofChanges	= 'True'
	and		tcugd.crmugd_4Meet					= 'True'
	and		(/*@meett_id = -1*/ tcugd.meett_id  is null	or tcugd.meett_id   = @meett_id)

if @email_recipients <> ''
	begin
		SET @email_recipients = SUBSTRING(@email_recipients,2,LEN(@email_recipients) - 1)

		exec spSystem_sendEMail
			@compId = @comp_id,
			@precipients = @email_recipients,
			@pcopy_recipients = null,
			@psubject = @title,
			@pbody_format = 'TEXT',
			@pbody = @text ,
			@pfile_attachments = null,
			@pReplyTo = NULL,
			@pblind_copy_recipients='',
			@pUser_Id				= @user_id
	end


END
GO















CREATE PROCEDURE [dbo].[spCRM_Meet_getCombo]
(
	@comp_id			int
)
as
set nocount on

	select		tcm.meet_id								[id],
				'(' + CONVERT(VARCHAR,tcm.meet_id) + ') - ' +
				substring(tcm.meet_description,1,100)	[desc]

	from		dbo.tbCRM_Meet tcm

