------------------------


CREATE PROCEDURE [dbo].[spCRM_Meet_getDataByFilters]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,

	@selection_id		INT,  --- NO SE USA MAS ESTA MIERDA, QUIEN SABE QUE CARAJO ES Y ASI SE MANDAN LAS FORRADAS
	@tast_id			INT,
	@cast_id			INT,
	@callst_id			INT,
	@meetst_id			INT,
	@datefrom			datetime,
	@dateto				datetime,
	@option				int,
	@text				nvarchar(500),
	@contact			int,
	@contact_text		nvarchar(500),
	@guid				UNIQUEIDENTIFIER,
	@session_user_id	int,
	@meett_id			int,
	@meet_id			INT,
	@supp_id			INT,
	@cust_id			int,
	@datereviewfrom		datetime,
	@datereviewto		datetime,
	@pro_id				INT

)
AS




BEGIN



	SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------



	set DATEFORMAT 'ymd'

		--------------------------------------------------------
		-------------parametros de prueba-----------------------
		--------------------------------------------------------
/*
		DECLARE			@comp_id			INT,
						@bra_id				INT,
						@prof_id			INT,
						@user_id			INT,

						@selection_id		INT,
						@tast_id			INT,
						@cast_id			INT,
						@callst_id			INT,
						@meetst_id			INT,
						@datefrom			datetime,
						@dateto				datetime,
						@option				int,
						@text				nvarchar(500),
						@contact_id			int,
						@guid				uniqueidentifier,
						@session_user_id	int,
						@meett_id			int

		SELECT			@comp_id			= 1,
						@bra_id				= 1,
						@prof_id			= 1,

						@selection_id		= -1,
						@datefrom			= '2012-01-01',
						@dateto				= '2012-12-31',
						@tast_id			= -1,
						@cast_id			= -1,
						@meetst_id			= -1,
						@callst_id			= -1,
						@user_id			= 1,
						@option				= -1,
						@text				= '',
						@contact_id			= -1,
						@guid				= 'a87d4c32-3760-47f7-b09a-18d5978e1734',
						@session_user_id	= 1,
						@meett_id			= -1
*/
		--------------------------------------------------------







	-- --------------------------------------------------------------------------
	-- Pone en una tabla temporal todos los usuarios de mi grupo y
	-- si no estoy en ningun grupo, todos los disponibles para crm
	-- --------------------------------------------------------------------------
	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom	,'false')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto	,'true')

	SET @datereviewfrom	= dbo.fnGetEnd_or_BeginOfDate(@datereviewfrom	,'false')
	SET @datereviewto   = dbo.fnGetEnd_or_BeginOfDate(@datereviewto	,'true')


	DECLARE @tmpUsersOfMyGroup TABLE(USER_ID INT PRIMARY KEY)

	INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
		SELECT DISTINCT tcugd.[USER_ID]
			FROM tbCRM_UserGroupsDetail tcugd							WITH (NOLOCK)
			INNER JOIN tbUser tuMyUser									WITH (NOLOCK)
				ON tuMyUser.[user_id]		= @session_user_id
			INNER JOIN tbUser tu										WITH (NOLOCK)
				ON	tu.[user_id]			= tcugd.[user_id]	AND
					tu.user_available4CRM	= 'True'
			INNER JOIN tbCRM_UserGroupsDetail mg						WITH (NOLOCK)
				ON mg.[user_id] = @session_user_id				AND
				   mg.crmugd_IsAvailable2ViewOtherUsers = 'True'
		WHERE	tcugd.comp_id	= mg.comp_id					AND
				tcugd.crmug_id	= mg.crmug_id					AND
			    tuMyUser.user_available4CRM_SeeAllMeets	= 'True'


	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tu.[USER_ID]
					FROM	tbUser tu									WITH (NOLOCK)
					INNER JOIN tbUser tuMyUser							WITH (NOLOCK)
						ON tuMyUser.[user_id]						= @session_user_id
					WHERE	tu.user_available4CRM					= 'True' AND
							tuMyUser.user_available4CRM_SeeAllMeets	= 'True'
		END


	IF NOT EXISTS(	SELECT 1
						FROM @tmpUsersOfMyGroup
						WHERE [USER_ID] = @session_user_id
				 )
	BEGIN
		INSERT INTO @tmpUsersOfMyGroup ([USER_ID])
			VALUES(@session_user_id)
	END
	-- --------------------------------------------------------------------------






		--guardar el campo de usuario "ver todas las reuniones" para mostrar todas las reuniones o
		--filtrar solo las del usuario
		declare @luser_available4CRM_SeeAllMeets bit

		SELECT	@luser_available4CRM_SeeAllMeets	= isnull(tu.user_available4CRM_SeeAllMeets, 'false')
			FROM	tbUser tu
			WHERE	tu.[user_id] = @session_user_id
		--SELECT	@luser_available4CRM_SeeAllMeets







		select	' ' [ ], ' ' [ ],' ' [ ], ' ' [ ], ' ' [ ],
				convert(bit,case
								when tct2.comp_id is null then	'false'
								else							'true'
							end)													[filter],
				cc.meet_id															[ID2],
				cc.meet_subject,
				cc.meet_date4Begin,
				cc.meet_nextReviewdate												[nextReviewdate],
				tcmt.meett_desc														[meet_type],
				ms.meetst_desc														[meetst_id],
				cc.meet_location,
				cc.meet_howLong,
				cc.meet_howLong_minutes,
				cc.meet_remind,
				cc.meet_description,
				tc2.cust_name														[cust_name],
				isnull(tc.contact_name,'')											[contact_id],
				tu.user_lastname + ', ' + tu.user_firstname							[user_name],
				cc.soh_Bra_id,
				cc.soh_Soh_id,
				tcc.case_desc														[case_id],
				tct.task_subject													[task_id],
				cc.[user_id],
				cc.meet_price,
				tsc.curr_desc,

				cc.meet_emailAdditional,
				cc.meet_id															[ID]



		FROM 	dbo.tbCRM_Meet								cc			WITH (NOLOCK)

				INNER JOIN @tmpUsersOfMyGroup tmpu
					ON tmpu.[USER_ID] = cc.[user_id]

				LEFT JOIN tbCRM_Meet_Block4Filter tctbf					WITH (NOLOCK)
					ON	tctbf.comp_id			= cc.comp_id		AND
						tctbf.bra_id			= cc.bra_id			AND
						tctbf.meett_id			= cc.meett_id		AND
						tctbf.meetst_id			= cc.meetst_id		AND
						tctbf.user_id_meet		= cc.[user_id]		AND
						tctbf.user_id_actual	= @session_user_id	AND
						cc.[user_id]			<>@session_user_id

				left join tbCRM_tmp							tct2		WITH (NOLOCK)
				on	tct2.comp_id			= cc.comp_id
				and tct2.crmt_function		= 4  -- Aquí es el unico caso en que se suma UNO, no se que MIERDA hizo el HDP que armo esta parte!!!  (0 Case;1 Task;2 Call;3 Meet)
				and tct2.crmt_function_id	= cc.meet_id
				and tct2.crmt_guid			= @guid

				LEFT JOIN	tbCRM_MeetStatus				ms			WITH (NOLOCK)
				ON	cc.comp_id		= ms.comp_id
				AND cc.meetst_id	= ms.meetst_id

				left join	tbCustomer						tc2			WITH (NOLOCK)
				on	tc2.comp_id		= cc.comp_id
				AND tc2.cust_id		= cc.cust_id

				LEFT JOIN	tbUser							tu			WITH (NOLOCK)
				on  tu.[user_id]	= cc.[user_id]

				LEFT JOIN	tbCRM_Case						tcc			WITH (NOLOCK)
				ON	tcc.comp_id		= cc.comp_id
				AND	tcc.case_id		= cc.case_id

				left join tbCRM_CaseStatus					tccs		WITH (NOLOCK)
				on tccs.comp_id		= tcc.comp_id
				and tccs.cast_id	= tcc.cast_id

				LEFT JOIN	tbCRM_Task						tct			WITH (NOLOCK)
				ON  tct.task_id		= cc.task_id
				AND tct.comp_id		= cc.comp_id

				left join tbCRM_TaskStatus					tcts		WITH (NOLOCK)
				on tcts.comp_id		= tct.comp_id
				ANd tcts.tast_id	= tct.tast_id

				LEFT JOIN	tbContact						tc			WITH (NOLOCK)
				ON  tc.comp_id		= cc.comp_id
				AND tc.contact_id	= cc.contact_id

				INNER JOIN  tbCRM_TypesByProfile			tctbp		WITH (NOLOCK)
				on  tctbp.comp_id	= @comp_id
				and tctbp.bra_id	= @bra_id
				and tctbp.prof_id	= @prof_id
				and tctbp.crm_type	= 3		--meet

				LEFT JOIN tbUsers4BranchFilter tubf								WITH (NOLOCK)
					ON	tubf.comp_id	= cc.comp_id		AND
						tubf.bra_id		= cc.bra_id		AND
						tubf.[user_id]	= @session_user_id

				inner join tbBranch							tb			WITH (NOLOCK)
				on tb.comp_id = cc.comp_id
				and tb.bra_id = cc.bra_id

				inner join tbsysCurrency					tsc			WITH (NOLOCK)
				on tsc.curr_id = tb.curr_id

				inner join tbCRM_MeetType					tcmt		WITH (NOLOCK)
				on  tcmt.comp_id = cc.comp_id
				AND tcmt.meett_id = cc.meett_id


		WHERE	cc.comp_id		= @comp_id
		AND		(@meet_id		= 0			OR cc.meet_id	= @meet_id)
		AND		(cc.bra_id		= @bra_id	OR cc.[user_id]	= @session_user_id  OR tubf.comp_id IS NOT NULL)
		AND		(@meett_id = -1 OR  cc.meett_id	 = @meett_id)
		AND     (
					(@luser_available4CRM_SeeAllMeets = 'false' and cc.[user_id]	= @session_user_id) OR
					(@luser_available4CRM_SeeAllMeets = 'true')
				)
		AND		(
					(@tast_id		= -1)														OR
     				(@tast_id		= -2 and  tcts.tast_isFinalStatus		= 'false')													OR
     				(@tast_id		= -3 and  tcts.tast_isFinalStatus		= 'True')													OR
     				(@tast_id		= -4 and  tcts.tast_isInitialStatus		= 'True')													OR
     				(@tast_id		= -5 and (tcts.tast_isInitialStatus		= 'False' AND tcts.tast_isFinalStatus = 'False'))			OR
					(@tast_id		= tct.tast_id)																						OR
					cc.task_id IS NULL
				)
		AND		(
					(@cast_id		= -1)		or
     				(@cast_id		= -2 and  tccs.cast_isFinalStatus		= 'false')													OR
     				(@cast_id		= -3 and  tccs.cast_isFinalStatus		= 'True')													OR
     				(@cast_id		= -4 and  tccs.cast_isInitialStatus		= 'True')													OR
     				(@cast_id		= -5 and (tccs.cast_isInitialStatus		= 'False' AND tccs.cast_isFinalStatus = 'False'))			OR
					(tcc.cast_id	= @cast_id)																							OR
					cc.case_id IS NULL
				)

		AND		(
					(@meetst_id		= -1)		or
     				(@meetst_id		= -2 and  ms.meetst_isFinalStatus		= 'false')													OR
     				(@meetst_id		= -3 and  ms.meetst_isFinalStatus		= 'True')													OR
     				(@meetst_id		= -4 and  ms.meetst_isInitialStatus	= 'True')														OR
     				(@meetst_id		= -5 and (ms.meetst_isInitialStatus	= 'False'		AND ms.meetst_isFinalStatus = 'False'))			OR
					(ms.meetst_id	= @meetst_id)
				)

		AND		cc.meet_date4Begin	BETWEEN @datefrom and @dateto
		--and		(@selection_id		=	-1		or		 tct.cust_id	= @selection_id)
		and		((
					(@option	 = -1 ) or
					(@option	 = 0 and cc.meet_subject like @text + '%') or
					(@option	 = 1 and cc.meet_subject like '%' + @text + '%') or
					(@option	 = 2 and cc.meet_subject = @text ) or
					(@option	 = 3 and cc.meet_subject <> @text ) or
					(@option	 = 4 and cc.meet_subject not like '%' + @text + '%')
				)
				or
				(
					(@option	 = -1 ) or
					(@option	 = 0 and cc.meet_location like @text + '%') or
					(@option	 = 1 and cc.meet_location like '%' + @text + '%') or
					(@option	 = 2 and cc.meet_location = @text ) or
					(@option	 = 3 and cc.meet_location <> @text ) or
					(@option	 = 4 and cc.meet_location not like '%' + @text + '%')
				)
				or
				(
					(@option	 = -1 ) or
					(@option	 = 0 and cc.meet_description like @text + '%') or
					(@option	 = 1 and cc.meet_description like '%' + @text + '%') or
					(@option	 = 2 and cc.meet_description = @text ) or
					(@option	 = 3 and cc.meet_description <> @text ) or
					(@option	 = 4 and cc.meet_description not like '%' + @text + '%')
				))

		AND		(
						(@user_id		= -1		AND tctbf.comp_id IS NULL)
					OR
						(cc.[user_id]	= @user_id	AND tctbf.comp_id IS NULL)
				)

		AND		(@contact		 = -1	OR	cc.contact_id = @contact)

--		and		(
--					(@contact	 = -1 ) or
--					(@contact	 = 0 and tc.contact_name like @contact_text + '%') or
--					(@contact	 = 1 and tc.contact_name like '%' + @contact_text + '%') or
--					(@contact	 = 2 and tc.contact_name = @contact_text ) or
--					(@contact	 = 3 and tc.contact_name <> @contact_text ) or
--					(@contact	 = 4 and tc.contact_name not like '%' + @contact_text + '%')
--				)

		and		(
					( cc.comp_id not in (	select top 1 tct2.comp_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 1
												and tct2.crmt_guid = @guid))		or

					(cc.case_id in (		select tct2.crmt_function_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 1
												and tct2.crmt_guid = @guid))
				)

		and		(
					( cc.comp_id not in (	select top 1 tct2.comp_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 2
												and tct2.crmt_guid = @guid))		or

					(cc.task_id in (		select tct2.crmt_function_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 2
												and tct2.crmt_guid = @guid))
				)

		AND		(@supp_id			= -1		OR		cc.supp_id		= @supp_id)
		AND		(@cust_id			= -1		or		cc.cust_id		= @cust_id)
		AND (isnull(cc.meet_nextReviewdate,'')	BETWEEN @datereviewfrom and @datereviewto )--ga

		AND	(@pro_id			= -1		OR		cc.pro_id		= @pro_id)

	order by [filter],cc.meet_date4Begin DESC




END
GO







CREATE procedure [dbo].[spCRM_Meet_getDataById]
(
	@comp_id	int,
	@meet_id	int
)
as set NOCOUNT on


select
	tcm.comp_id,
	tcm.meet_id,
	tcm.bra_id,
	tcm.meetst_id,
	tcm.meet_subject,
	tcm.meet_date4Begin,
	tcm.meet_location,
	tcm.meet_howLong,
	tcm.meet_howLong_minutes,
	tcm.meet_remind,
	tcm.meet_description,
	tcm.[user_id],
	isnull(tu.user_lastname,'') + ', ' + isnull(tu.user_firstname,'') [user_name],
	tcm.soh_Bra_id,
	tcm.soh_Soh_id,
	isnull(tcm.case_id,-1)							[case_id],
	isnull(tcm.task_id,-1)							[task_id],
	isnull(tcm.contact_id,-1)						[contact_id],
	tc.curr_desc,
	tcm.meet_price,
	tcm.curr_id,
	isnull(tcm.cust_id,-1)							[cust_id],
	tcmt.meett_id,
	tcm.meet_emailAdditional,
	tcm.supp_id,
	tcm.meet_nextReviewdate							[meet_nextReviewdate],
	tcm.pro_id

from tbCRM_Meet tcm

inner join tbUser tu
on tu.[user_id] = tcm.[user_id]

inner join tbBranch tb
on tb.comp_id = tcm.comp_id
and tb.bra_id = tcm.bra_id

inner join tbsysCurrency tc
on tc.curr_id = tb.curr_id

left join tbCRM_MeetType tcmt
on  tcmt.comp_id = tcm.comp_id
AND tcmt.meett_id = tcm.meett_id


where tcm.comp_id = @comp_id
and tcm.meet_id = @meet_id

GO








CREATE PROCEDURE [dbo].[spCRM_Meet_getDataByText]
(
	@text	VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id  AS INT
)
AS



BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*

		DECLARE
			@text		VARCHAR(300),
			@count		INT,
			@lang_id	INT,
			@comp_id AS INT,
			@bra_id  AS INT

		SELECT
			@text		='A',
			@count		= 2,
			@lang_id	= 2,
			@comp_id	= 1,
			@bra_id		= 1
	*/
	-- ----------------------------------------------------------------





	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')



	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)
	DECLARE @text6	varchar(300)
	DECLARE @text7	varchar(300)
	DECLARE @text8	varchar(300)
	DECLARE @text9	varchar(300)
	DECLARE @text10	varchar(300)

	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0 else
			IF @text2 IS NULL SET @text2 = @text0 else
			IF @text3 IS NULL SET @text3 = @text0 else
			IF @text4 IS NULL SET @text4 = @text0 else
			IF @text5 IS NULL SET @text5 = @text0 else
			IF @text6 IS NULL SET @text6 = @text0 else
			IF @text7 IS NULL SET @text7 = @text0 else
			IF @text8 IS NULL SET @text8 = @text0 else
			IF @text9 IS NULL SET @text9 = @text0 else
			IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------





	SELECT		TOP (@count)

				Upper(dbo.PadRightString( IsNull(tc.meet_subject,''),'.',50)) + ' | ' + isnull(convert(VARCHAR(10),tc.Meet_id),'')	[meet_subject],
				tc.Meet_id
		FROM tbCRM_Meet tc
			WHERE		tc.comp_id = @comp_id
					AND (tc.bra_id IS NULL OR tc.bra_id = @bra_id)
		AND
			(

						CASE
							WHEN @selection_method = 0 AND tc.meet_subject LIKE @text + '%'	 THEN	'True'
							WHEN @selection_method = 1 AND tc.meet_subject LIKE '%' + @text1 + '%'	 THEN	'True'
							WHEN @selection_method = 2 AND tc.meet_subject LIKE '%' + @text1 + '%' AND tc.meet_subject LIKE '%' + @text2 + '%'		 THEN	'True'
							WHEN @selection_method = 3 AND tc.meet_subject LIKE '%' + @text1 + '%' AND tc.meet_subject LIKE '%' + @text2 + '%' AND tc.meet_subject LIKE '%' + @text3 + '%'	 THEN	'True'
							WHEN @selection_method = 4 AND tc.meet_subject LIKE '%' + @text1 + '%' AND tc.meet_subject LIKE '%' + @text2 + '%' AND tc.meet_subject LIKE '%' + @text3 + '%' AND tc.meet_subject LIKE '%' + @text4 + '%'		 THEN	'True'
							WHEN @selection_method = 5 AND tc.meet_subject LIKE '%' + @text1 + '%' AND tc.meet_subject LIKE '%' + @text2 + '%' AND tc.meet_subject LIKE '%' + @text3 + '%' AND tc.meet_subject LIKE '%' + @text4 + '%' AND tc.meet_subject LIKE '%' + @text5 + '%'		 THEN	'True'
							WHEN @selection_method = 6 AND tc.meet_subject LIKE '%' + @text1 + '%' AND tc.meet_subject LIKE '%' + @text2 + '%' AND tc.meet_subject LIKE '%' + @text3 + '%' AND tc.meet_subject LIKE '%' + @text4 + '%' AND tc.meet_subject LIKE '%' + @text5 + '%' AND tc.meet_subject LIKE '%' + @text6 + '%'	 THEN	'True'
							WHEN @selection_method = 7 AND tc.meet_subject LIKE '%' + @text1 + '%' AND tc.meet_subject LIKE '%' + @text2 + '%' AND tc.meet_subject LIKE '%' + @text3 + '%' AND tc.meet_subject LIKE '%' + @text4 + '%' AND tc.meet_subject LIKE '%' + @text5 + '%' AND tc.meet_subject LIKE '%' + @text6 + '%' AND tc.meet_subject LIKE '%' + @text7 + '%'	 THEN	'True'
							WHEN @selection_method = 8 AND tc.meet_subject LIKE '%' + @text1 + '%' AND tc.meet_subject LIKE '%' + @text2 + '%' AND tc.meet_subject LIKE '%' + @text3 + '%' AND tc.meet_subject LIKE '%' + @text4 + '%' AND tc.meet_subject LIKE '%' + @text5 + '%' AND tc.meet_subject LIKE '%' + @text6 + '%' AND tc.meet_subject LIKE '%' + @text7 + '%' AND tc.meet_subject LIKE '%' + @text8 + '%'		 THEN	'True'
							WHEN @selection_method = 9 AND tc.meet_subject LIKE '%' + @text1 + '%' AND tc.meet_subject LIKE '%' + @text2 + '%' AND tc.meet_subject LIKE '%' + @text3 + '%' AND tc.meet_subject LIKE '%' + @text4 + '%' AND tc.meet_subject LIKE '%' + @text5 + '%' AND tc.meet_subject LIKE '%' + @text6 + '%' AND tc.meet_subject LIKE '%' + @text7 + '%' AND tc.meet_subject LIKE '%' + @text8 + '%' AND tc.meet_subject LIKE '%' + @text9 + '%'		 THEN	'True'
							WHEN @selection_method =10 AND tc.meet_subject LIKE '%' + @text1 + '%' AND tc.meet_subject LIKE '%' + @text2 + '%' AND tc.meet_subject LIKE '%' + @text3 + '%' AND tc.meet_subject LIKE '%' + @text4 + '%' AND tc.meet_subject LIKE '%' + @text5 + '%' AND tc.meet_subject LIKE '%' + @text6 + '%' AND tc.meet_subject LIKE '%' + @text7 + '%' AND tc.meet_subject LIKE '%' + @text8 + '%' AND tc.meet_subject LIKE '%' + @text9 + '%' AND tc.meet_subject LIKE '%' + @text10 + '%'		 THEN 'True'
							ELSE	'False'
						END	= 'True'

			)



			ORDER BY	tc.meet_subject

END
GO








CREATE PROCEDURE [dbo].[spCRM_Meet_GetHistoryData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@meet_id	INT
)
as set nocount on


-- -----------------------------------------------
-- Testing
-- -----------------------------------------------
/*
	declare
		@comp_id	INT,
		@meet_id	INT
	select
		@comp_id	= 1,
		@meet_id	= 23
*/
-- -----------------------------------------------


select		tcc.case_desc													[case_desc],
			tct.task_desc													[task_desc],
			tcmh.meet_subject												[meet_subject],
			tcmh.meet_location												[meet_location],
			tcmh.meet_description											[meet_description],
			tcmh.meet_howLong												[meet_howLong],
			tcmh.meet_date4Begin											[meet_date4Begin],
			tcmh.meeth_cd													[LastUpdate],--Fecha de ultima actualización
			tcmt.meett_desc													[meet_type],
			tu.user_lastname + ', ' + tu.user_firstname						[user_name]

from tbCRM_MeetHistory						tcmh	WITH (NOLOCK)


	inner join tbCRM_Meet					tcm		WITH (NOLOCK)
	on	tcm.comp_id = tcmh.comp_id
	AND tcm.meet_id = tcmh.meet_id

	left join tbCRM_MeetStatus			    tcms	WITH (NOLOCK)
	on	tcms.comp_id	= tcm.comp_id
	AND tcms.meetst_id	= tcm.meetst_id

	left join tbCRM_Case					tcc		WITH (NOLOCK)
	on	tcc.comp_id = tcmh.comp_id
	AND tcc.case_id = tcmh.case_id

	left join tbCRM_Task					tct		WITH (NOLOCK)
	on	tct.comp_id = tcmh.comp_id
	AND tct.task_id = tcmh.task_id

	left join tbCRM_MeetType				tcmt	WITH (NOLOCK)
	on tcmt.comp_id = tcmh.comp_id
	and tcmt.meett_id = tcmh.meett_id

	LEFT JOIN tbUser						tu		WITH (NOLOCK)
	ON tu.[user_id] = tcmh.[user_id]

where	tcmh.comp_id = @comp_id
and		tcmh.meet_id = @meet_id


GO







------------------------
-- Reporte de Reuniones
------------------------


CREATE PROCEDURE [dbo].[spCRM_Meet_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,

		@meet_id			INT,
		@intBranch4Lang		int


)
AS
SET NOCOUNT ON


BEGIN

set nocount on
set dateformat 'ymd'

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



--------------------------------------------------------
-------------parametros de prueba-----------------------
--------------------------------------------------------
/*
DECLARE		@comp_id			int,
			@lang_id			int,
			@page_id			int,

			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,

			@meet_id			INT,
			@intBranch4Lang		INT



SELECT		@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10091,

			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 1,

			@meet_id			= 228,
			@intBranch4Lang		= 1




DROP TABLE #tmpmeet,#tmptask,#tmpcase
*/
--------------------------------------------------------
--------------------------------------------------------
--------------------------------------------------------

DECLARE @fun_id					INT,
		@ltotal					decimal(19,4),
		@lcurr_desc				nvarchar(50),
		@message_task			VARCHAR(100),
		@message_task_null		VARCHAR(100),
		@message_meet			VARCHAR(100),
		@message_case			VARCHAR(100),
		@message_case_null		VARCHAR(100)


SET @fun_id = 1



 SELECT @message_case = utexts_desc		 FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 156 AND tut.lang_id = @lang_id
 SELECT @message_task = utexts_desc		 FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 155 AND tut.lang_id = @lang_id
 SELECT @message_task_null = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 157 AND tut.lang_id = @lang_id
 SELECT @message_meet = utexts_desc		 FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 153 AND tut.lang_id = @lang_id
 SELECT @message_case_null = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 158 AND tut.lang_id = @lang_id


-------------------------
-- sacar total final.
-------------------------
select @ltotal =

(SELECT isnull(SUM(ISNULL(tcm.meet_price,0)),0)

FROM tbCRM_Meet tcm

left join tbCRM_MeetStatus tcms
on  tcms.comp_id	= tcm.comp_id
and tcms.meetst_id  = tcm.meetst_id

where 	tcm.comp_id			= @comp_id
AND		tcm.meet_id			= @meet_id)

+
(SELECT isnull(SUM(ISNULL(tcc2.case_price,0)),0)

	FROM tbCRM_Meet tcm

	left join tbCRM_MeetStatus tcms
	on  tcms.comp_id	= tcm.comp_id
	and tcms.meetst_id  = tcm.meetst_id

	inner join tbCRM_Case tcc2
	on  tcc2.comp_id = tcm.comp_id
	AND tcc2.case_id = tcm.case_id

	where 	tcm.comp_id			= @comp_id
	AND		tcm.meet_id		= @meet_id )

+

(SELECT isnull(SUM(ISNULL(tct.task_price,0)),0)

FROM tbCRM_Meet tcm

left join tbCRM_MeetStatus tcms
on  tcms.comp_id	= tcm.comp_id
and tcms.meetst_id  = tcm.meetst_id

inner join tbCRM_Task						tct
on  tct.comp_id	= tcm.comp_id
AND tct.task_id = tcm.task_id


where 	tcm.comp_id			= @comp_id
AND		tcm.meet_id			= @meet_id )


----------------------------------
--Recuperar moneda de la sucursal
----------------------------------

select @lcurr_desc = ( SELECT tc.curr_desc FROM tbBranch tb

						INNER JOIN tbsysCurrency tc
						ON TC.curr_id = TB.curr_id

						WHERE tb.bra_id = @bra_id )








--------------------
-- select principal
--------------------


select  tcms.meetst_desc,
		tcm.meet_date4Begin,
		tu.user_lastname + ', ' + tu.user_firstname [User_name] ,
		tcm.meet_description,
		tcm.meet_subject,
		tcm.meet_location,
		isnull(tcm.meet_price,0)					[meet_price],
		@ltotal										[total],
		@lcurr_desc									[curr_desc],
		isnull(tcmt.meett_desc, '')					[meet_type],
		CONVERT(VARCHAR,tcm.meet_id)				[meet_id]


into #tmpmeet
from tbCRM_Meet									tcm

	left join tbCRM_MeetStatus					tcms
	on  tcms.comp_id    = tcm.comp_id
	and tcms.meetst_id  = tcm.meetst_id

	left join tbUser							tu
	on  tu.[user_id]	= tcm.[user_id]


	INNER JOIN	tbCRM_TypesByProfile			tctbp
	on tctbp.comp_id	= @comp_id
	and tctbp.bra_id	= @bra_id
	and tctbp.prof_id	= @prof_id
	and tctbp.crm_type	= 2	-- reunion

	left join tbCRM_MeetType tcmt
	on tcmt.comp_id = tcm.comp_id
	AND tcmt.meett_id = tcm.meett_id



where 	tcm.comp_id			= @comp_id
AND		tcm.meet_id			= @meet_id


IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmpmeet

		END
	  ELSE
			SELECT  ''[meetst_desc],
					@message_meet [meet_description],
					' ' [meet_date4Begin],
					' ' [User_name],
					' ' [meet_subject],
					' ' [meet_location],
					' ' [meet_price]

----------------------------------------------------
--params para el reporte--
----------------------------------------------------


exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id
--exec [spReports_getData] 1, 2,	10005

/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/

SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1912
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

		CASE @meet_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(select tcm.meet_description
					 from tbCRM_Meet tcm
				where   tcm.comp_id    = @comp_id
				And   tcm.meet_id     = @meet_id)
		End [params2]

----------------------------------------------------




------------------------------------------------------------
---Subreporte - Pertenece a tal tarea.
------------------------------------------------------------

select  @message_task [message],tct.task_desc [task_desc],isnull(tct.task_price,0) [task_price]

into #tmptask
from  tbCRM_Meet tcm

left join tbCRM_MeetStatus					tcms
on  tcms.comp_id    = tcm.comp_id
and tcms.meetst_id  = tcm.meetst_id

inner join tbCRM_Task tct
on tct.comp_id = tcm.comp_id
AND tct.task_id = tcm.task_id

where 	tcm.comp_id			= @comp_id
AND		tcm.meet_id			= @meet_id



 IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmptask

		END
	  ELSE
			SELECT @message_task [message], @message_task_null[task_desc],' ' [task_price]


------------------------------------------------------------------------------------------------------------------------


------------------------------------------------------------
---Subreporte - Pertenece a tal caso.
------------------------------------------------------------

select  @message_case [message],tcc.case_desc [case_desc],isnull(tcc.case_price,0) [case_price]

into #tmpcase
from  tbCRM_Meet tcm

left join tbCRM_MeetStatus					tcms
on  tcms.comp_id    = tcm.comp_id
and tcms.meetst_id  = tcm.meetst_id

inner join tbCRM_Case tcc
on tcc.comp_id = tcm.comp_id
AND tcc.case_id = tcm.case_id

where 	tcm.comp_id			= @comp_id
AND		tcm.meet_id			= @meet_id



 IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmpcase

		END
	  ELSE
			SELECT @message_case			[message],
			       @message_case_null		[case_desc],' ' [case_price]





END





GO








CREATE PROCEDURE [dbo].[spCRM_Meet_insertData]
(
	@comp_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@lang_id				INT,

	@meetst_id				INT,
	@meet_subject			NVARCHAR(200),
	@meet_date4Begin		DATETIME,
	@meet_location			NVARCHAR(1000),
	@meet_howLong			INT,
	@meet_howLong_minutes	INT,
	@meet_remind			BIT,
	@meet_description		NVARCHAR(4000),
	@soh_Bra_id				INT,
	@soh_Soh_id				INT,
	@case_id				INT,
	@task_id				INT,
	@contact_id				INT,
	@meet_price				decimal(19,4),
	@curr_id				INT,
	@cust_id				INT,
	@chkCA					BIT,
	@meett_id				INT,
	@meet_emailAdditional	VARCHAR(250),
	@supp_id				INT,
	@meet_nextReviewdate    DATETIME,
	@pro_id					INT,
	@return_value			INT OUTPUT
)
AS



BEGIN

	SET NOCOUNT ON

	IF @cust_id = -1
		BEGIN
			SET @cust_id = NULL
		END
	IF @contact_id = -1
		BEGIN
			SET @contact_id = NULL
		END
	IF @supp_id = -1
		BEGIN
			SET @supp_id = NULL
		END
	IF @pro_id = -1
		BEGIN
			SET @pro_id = NULL
		END


	INSERT INTO tbCRM_Meet
	(
		comp_id,
		bra_id,
		meetst_id,
		meet_subject,
		meet_date4Begin,
		meet_location,
		meet_howLong,
		meet_howLong_minutes,
		meet_remind,
		meet_description,
		[user_id],
		soh_Bra_id,
		soh_Soh_id,
		case_id,
		task_id,
		contact_id,
		meet_price,
		curr_id,
		cust_id,
		meett_id,
		meet_emailAdditional,
		supp_id,
		meet_nextReviewdate,
		pro_id
	)
	VALUES
	(
		@comp_id,
		@bra_id,
		@meetst_id,
		@meet_subject,
		@meet_date4Begin,
		@meet_location,
		@meet_howLong,
		@meet_howLong_minutes,
		@meet_remind,
		@meet_description,
		@user_id,
		@soh_Bra_id,
		@soh_Soh_id,
		@case_id,
		@task_id,
		@contact_id,
		@meet_price,
		@curr_id,
		@cust_id,
		@meett_id,
		@meet_emailAdditional,
		@supp_id,
		@meet_nextReviewdate,
		@pro_id
	)


	SET @return_value = @@IDENTITY


declare
	@message			 varchar(400),
	@subject			 varchar(400),
	@body				 varchar(400),
	@mail				 varchar(2000),
	@user_origen_name	 varchar(400),
	@user_mail_origin	 varchar(400),
	@optionid			 int,
	@desc				 varchar(200)



--Datos del Usuario de Origen
select
	@user_origen_name = (tu.user_lastname + ',' + tu.user_firstname),
	@user_mail_origin = tu.user_email
from tbUser tu where tu.[user_id] = @user_id

set @optionid = 3795

-- ---------------------------------------
-- Textos para armado del mail completo
DECLARE
	@lMeetSubject		VARCHAR(100),
	@MeetDesc			VARCHAR(100),
	@date4begin			VARCHAR(100),
	@date2end			VARCHAR(100),
	@callduration		VARCHAR(100),
	@meetduration		VARCHAR(100)

--ASUNTO
select @lMeetSubject	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300626
--DESCRIPCION
select @MeetDesc		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300627
--Fecha Inicio
select @date4begin		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300629
--Fecha Fin
select @date2end		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300630
--Duración de la llamada
select @callduration	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300633
--Duración de la reunion
select @meetduration	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300634
-- ---------------------------------------


--Armado de Subject y Body

select @desc = tswn.word_desc
  from tbSysWordsNew tswn where tswn.lang_id = @lang_id and tswn.wordsi_id = @optionid

/*************************************************************************************/
/*En caso de poseer un TEXTO EN LA HEADER/FOOTER propia, utilizamos ese, sino        */
/*utilizamos el valor genérico de CRM de la UniqueTexts                              */
/*************************************************************************************/

	IF EXISTS (SELECT 1
	           FROM tbCRM_MeetMailHeaderFooter			tcmmhf WITH (NOLOCK)
	           WHERE	tcmmhf.comp_id					= @comp_id AND
						tcmmhf.meett_id					= @meett_id AND
						tcmmhf.meetst_id				= @meetst_id AND
						ISNULL(tcmmhf.crmhf_Subject,'') <> '')
		BEGIN
			SELECT
				@subject = tcmmhf.crmhf_Subject
			  FROM tbCRM_MeetMailHeaderFooter			tcmmhf WITH (NOLOCK)
	           WHERE	tcmmhf.comp_id		= @comp_id AND
						tcmmhf.meett_id		= @meett_id AND
						tcmmhf.meetst_id	= @meetst_id

		END
	ELSE
		BEGIN
			SELECT
				@subject = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 984

			set @subject = @subject + @desc

		END



select @message = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 985

select @body = tut.utexts_desc + ' ' + CONVERT(VARCHAR,@return_value)
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 986



set @mail = @desc								+ ' ' +
			@message							+ ' ' +
			@user_origen_name					+ ' ' +
			@body								+ ' ' +
			@lMeetSubject + ' ' +
			@meet_subject + ' ' + @MeetDesc + ' ' + @meet_description + ' ' + @meetduration + ' ' + CONVERT(VARCHAR,@meet_howLong)


-- ---------------------------------------------------------------
-- ARMADO DEL HTML PARA EL MAIL
-- ---------------------------------------------------------------
--ARMAMOS HEADER Y FOOTER EN CASO DE QUE HAYA VALORES EN LAS TABLAS

DECLARE @MailTableHeader AS NVARCHAR(MAX),
		@HeaderText		 AS NVARCHAR(MAX),
		@FooterText		 AS NVARCHAR(MAX)

SET @HeaderText = ''
SET @FooterText = ''

SELECT
	@HeaderText = tcmmhf.htmlHeader,
	@FooterText = tcmmhf.htmlFooter
FROM tbCRM_MeetMailHeaderFooter tcmmhf
WHERE	tcmmhf.comp_id	 = @comp_id  AND
		tcmmhf.meett_id	 = @meett_id AND
		tcmmhf.meetst_id = @meetst_id

IF NOT LEN(@HeaderText) > 0
	SET @HeaderText = ''
IF NOT LEN(@FooterText) > 0
	SET @FooterText = ''

-- ---------------------------------------------------------------
-- ESTADO
DECLARE @Status			AS VARCHAR(MAX)
DECLARE @Meet_Status	AS VARCHAR(MAX)

	SELECT @Status = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30022

	SELECT @Meet_Status = tcms.meetst_desc FROM tbCRM_MeetStatus tcms WHERE tcms.comp_id = @comp_id AND tcms.meetst_id = @meetst_id

--variables para el formateo del html email
	DECLARE	@MailTable							NVARCHAR(MAX),
			@MailEndTable						NVARCHAR(MAX),
			@Mailsubject						NVARCHAR(MAX),
			@MailbodyHeader						NVARCHAR(MAX),
			@Mailbody							NVARCHAR(MAX),
			@MailbodyFooter						NVARCHAR(MAX),
			@MailImageSRC						NVARCHAR(MAX)


SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
				 'cellpadding="1" cellspacing="1" border="1">'

SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
					  '<b>' + @subject + @desc + '</b><br /><br /><br />'


SET @Mailbody = ''
SET @MailBody =

	'<tr><td align="center">' +
		@desc + ' ' + @message + ' ' +  @user_origen_name  + ' ' +
	'</td><tr><td align="center">' +
		@body + ' ' +
	'</td></tr><td align="center">' +
		@lMeetSubject + ' ' + @meet_subject + ' ' +
	'</td></tr><td align="center">' +
		@Status + ' ' + @Meet_Status + ' ' +
	'</td><tr><td align="center">' +
		@MeetDesc + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@meet_description) + ' ' +
	'</td><tr><td align="center">' +
		@meetduration + ' ' + CONVERT(VARCHAR,@meet_howLong) + ' ' +
	'</td></tr>'

SET @MailEndTable = + '</table>'

SET @MailbodyFooter = '</div>'






SET @Mailbody = @HeaderText + ' ' +  @MailTable + ' ' + @Mailbody + @MailEndTable + ' ' + @FooterText + ' ' + @MailbodyFooter
--SELECT @MailTable
--SELECT @Mailbody
--SELECT @MailEndTable
--SELECT @MailImageSRC
-- ---------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Envio del Mail
-- -----------------------------------------------------------------------------
	DECLARE @strMailString	AS NVARCHAR(MAX)
	DECLARE @strMail		AS NVARCHAR(MAX)
	DECLARE @strMailCC		AS NVARCHAR(MAX)
	DECLARE @strMailCCO		AS NVARCHAR(MAX)
	DECLARE @strMailFrom    AS NVARCHAR(MAX)
	SELECT  @strMailString	= dbo.fnCRM_GetCustomerEmailByMeetType(@comp_id, @cust_id, @meett_id, @meetst_id, @return_value, @user_id)
	SELECT  @strMail		= dbo.fnSplitPosition(@strMailString, '|',1)
	SELECT  @strMailCC		= dbo.fnSplitPosition(@strMailString, '|',2)
	SELECT  @strMailCCO		= dbo.fnSplitPosition(@strMailString, '|',3)
	SELECT  @strMailFrom	= dbo.fnSplitPosition(@strMailString, '|',4)

	---- Mail al Usuario Asignado
	--exec spSystem_sendEMail
	--						@compId				= @comp_id,
	--						@precipients		= @user_mail_origin,
	--						@pcopy_recipients	= null,
	--						@psubject			= @subject,
	--						@pbody_format		= 'HTML',
	--						@pbody				= @MailBody,
	--						@pfile_attachments	= null,
	--						@pReplyTo			= @strMailFrom,
	--						@pblind_copy_recipients='',
	--						@pUser_Id			= @user_id

	-- Mail de Aviso a Clientes, Contactos, Adicionales, Etc.
	exec spSystem_sendEMail
							@compId					= @comp_id,
							@precipients			= @strMail,
							@pcopy_recipients		= @strMailCC,
							@psubject				= @subject,
							@pbody_format			= 'HTML',
							@pbody					= @Mailbody,
							@pfile_attachments		= null,
							@pReplyTo				= @strMailFrom,
							@pblind_copy_recipients	= @strMailCCO,
							@pUser_Id				= @user_id
	-- -----------------------------------------------------------------------------









insert into tbSecurityLog
(
	comp_id,
	bra_id,
	user_id,
	seclog_obs_1,
	seclog_obs_2,
