	if (@chkCA = 'False')
		begin
			declare
					@soss_id		INT
			select
					@soss_id		= ssos_id
			from tbSaleOrderHeader				tsoh
			where	tsoh.comp_id	= @comp_id
			and		tsoh.bra_id		= @bra_id
			and		tsoh.soh_id		= @soh_soh_id

			if (@soss_id = 10)
