CREATE PROCEDURE [dbo].[spCRM_Meet_SendNotifications]

AS
	SET NOCOUNT ON

	BEGIN
		/*
		DECLARE
			@lang_id	INT

		SELECT
			@lang_id	= 2
		*/


			-- declareción de variables para obtener los datos del cursor
			DECLARE
					@comp_id				INT,
					@meet_id				INT,
					@bra_id					INT,
					@meetst_id				INT,
					@meet_subject			VARCHAR(MAX),
					@meet_date4Begin		DATETIME,
					@meet_location			VARCHAR(MAX),
					@meet_howLong			INT,
					@meet_howLong_minutes	INT,
					@meet_remind			BIT,
					@meet_description		VARCHAR(MAX),
					@user_id				INT,
					@cust_id				INT,
					@meett_id				INT,
					@meet_advertiseDate		DATETIME,
					@meet_advertiseCount	INT,
					@meet_advertiseLastDate	DATETIME,
				@bisIsAdvertiseLastDate BIT



			DECLARE cursor_Meet CURSOR FOR

				SELECT
					tcm.comp_id,
					tcm.meet_id,
					tcm.bra_id,
					tcm.meetst_id,
					tcm.meet_subject,
					tcm.meet_date4Begin,
					tcm.meet_location,
					tcm.meet_howLong,
					tcm.meet_howLong_minutes,
					tcm.meet_remind,
					tcm.meet_description,
					tcm.[user_id],
					tcm.cust_id,
					tcm.meett_id,
					tcm.meet_advertiseDate,
					tcm.meet_advertiseCount,
					tcm.meet_advertiseLastDate,
					CASE
						WHEN tcm.meet_advertiseDate IS NULL THEN	'False'
						ELSE										'True'
					END

				FROM tbCRM_Meet tcm
				INNER JOIN tbBranch tb
					ON	tb.comp_id	= tcm.comp_id AND
						tb.bra_id	= tcm.bra_id

				INNER JOIN tbCRM_MeetStatus tcts		WITH (NOLOCK)
					ON	tcts.comp_id				= tcm.comp_id	AND
						tcts.meetst_id				= tcm.meetst_id	AND
						tcts.meetst_isFinalStatus	= 'False'

				WHERE	tcm.meet_advertiseDate IS NOT NULL
							OR
						(	tb.bra_processingDate = tcm.meet_nextReviewdate AND
						   (tcm.meet_nextReviewdateLastMailDate IS NULL
								OR
							tcm.meet_nextReviewdateLastMailDate < tcm.meet_nextReviewdate
						   )
						)

				--where tcm.meet_id = 237

			OPEN	cursor_Meet

			-- lectura anticipada del cursor
			FETCH	cursor_Meet
			INTO
				@comp_id,
				@meet_id,
				@bra_id,
				@meetst_id,
				@meet_subject,
				@meet_date4Begin,
				@meet_location,
				@meet_howLong,
				@meet_howLong_minutes,
				@meet_remind,
				@meet_description,
				@user_id,
				@cust_id,
				@meett_id,
				@meet_advertiseDate,
				@meet_advertiseCount,
				@meet_advertiseLastDate,
				@bisIsAdvertiseLastDate



			-- se recorre el cursor hasta el fin del mismo
			WHILE   @@FETCH_STATUS = 0
			BEGIN

				--ACA PROCESAMOS Y AVISAMOS

					--SI EL COUNT ES DISTINTO DE NULL, SUMAMOS 1 Y SETEAMOS EN NULL
					--LA FECHA DE AVISO SI ES MENOR O IGUAL A LA FECHA ACTUAL

					IF (@meet_advertiseCount IS NOT NULL) AND (@meet_advertiseDate <= GETDATE())

						BEGIN
							--select 1
							DECLARE @lang_id	INT
							SELECT  @lang_id = tb.lang_id FROM tbBranch tb WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id

							IF @bisIsAdvertiseLastDate = 'True'
								BEGIN
									UPDATE tbCRM_Meet
									SET
										meet_advertiseDate	= NULL,
										meet_advertiseCount = meet_advertiseCount + 1
									WHERE	comp_id			= @comp_id AND
											meet_id			= @meet_id
								END


							--COLOR DEL ENCABEZADO
							-- VERDE	= 1 Aviso			--> "Recordatorio"
							-- AMARILLO = 2 Avisos			--> "Recordatorio"
							-- ROJO		= 3 Avisos o más	--> "Advertencia"
							DECLARE
								@HeaderColor	VARCHAR(20),
								@HeaderMessage	VARCHAR(100)
								SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60000


								SET @HeaderColor = '#3ADF00'

								IF (@meet_advertiseCount + 1) = 1
									BEGIN
										SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60000
										SET @HeaderColor = '#3ADF00'
									END

								IF (@meet_advertiseCount + 1) = 2
									BEGIN
										SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60000
										SET @HeaderColor = '#F4FA58'
									END

								IF (@meet_advertiseCount + 1) > 2
									BEGIN
										SELECT @HeaderMessage = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 60001
										SET @HeaderColor = '#DF0101'
									END

							--ENVIAMOS MAILS
							-- --------------------------------------------------------------------------------------------------------------------------------
							-- Envio del Mail
							-- --------------------------------------------------------------------------------------------------------------------------------

								declare
									@message			 varchar(400),
									@subject			 varchar(400),
									@body				 varchar(400),
									@mail				 varchar(2000),
									@user_origen_name	 varchar(400),
									@user_mail_origin	 varchar(400),
									@optionid			 int,
									@desc				 varchar(200)



								--Datos del Usuario de Origen
								select
									@user_origen_name = (tu.user_lastname + ',' + tu.user_firstname),
									@user_mail_origin = tu.user_email
								from tbUser tu where tu.[user_id] = @user_id

								set @optionid = 3795

								-- ---------------------------------------
								-- Textos para armado del mail completo
								DECLARE
									@lMeetSubject		VARCHAR(100),
									@MeetDesc			VARCHAR(100),
									@date4begin			VARCHAR(100),
									@date2end			VARCHAR(100),
									@callduration		VARCHAR(100),
									@meetduration		VARCHAR(100)

								--ASUNTO
								select @lMeetSubject	= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300626
								--DESCRIPCION
								select @MeetDesc		= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300627
								--Fecha Inicio
								select @date4begin		= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300629
								--Fecha Fin
								select @date2end		= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300630
								--Duración de la llamada
								select @callduration	= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300633
								--Duración de la reunion
								select @meetduration	= tut.utexts_desc
								from tbsysUniqueTexts	tut
								where tut.lang_id		= @lang_id
								and tut.utexts_id		= 300634
								-- ---------------------------------------


								--Armado de Subject y Body

								select @desc = tswn.word_desc
								  from tbSysWordsNew tswn where tswn.lang_id = @lang_id and tswn.wordsi_id = @optionid

								/*************************************************************************************/
								/*En caso de poseer un TEXTO EN LA HEADER/FOOTER propia, utilizamos ese, sino        */
								/*utilizamos el valor genérico de CRM de la UniqueTexts                              */
								/*************************************************************************************/

									IF EXISTS (SELECT 1
											   FROM tbCRM_MeetMailHeaderFooter			tcmmhf WITH (NOLOCK)
											   WHERE	tcmmhf.comp_id					= @comp_id AND
														tcmmhf.meett_id					= @meett_id AND
														tcmmhf.meetst_id				= @meetst_id AND
														ISNULL(tcmmhf.crmhf_Subject,'') <> '')
										BEGIN
											SELECT
												@subject = tcmmhf.crmhf_Subject
											  FROM tbCRM_MeetMailHeaderFooter			tcmmhf WITH (NOLOCK)
											   WHERE	tcmmhf.comp_id		= @comp_id AND
														tcmmhf.meett_id		= @meett_id AND
														tcmmhf.meetst_id	= @meetst_id

										END
									ELSE
										BEGIN
											SELECT
												@subject = tut.utexts_desc
											FROM tbsysUniqueTexts				tut
											WHERE	tut.lang_id		= @lang_id	AND
													tut.utexts_id	= 984

											set @subject = @subject + @desc

										END



								select @message = tut.utexts_desc
								from tbsysUniqueTexts tut
								where tut.lang_id = @lang_id
								and tut.utexts_id = 985

								select @body = tut.utexts_desc + ' ' + CONVERT(VARCHAR,@meet_id)
								from tbsysUniqueTexts tut
								where tut.lang_id = @lang_id
								and tut.utexts_id = 986



								set @mail = @desc								+ ' ' +
											@message							+ ' ' +
											@user_origen_name					+ ' ' +
											@body								+ ' ' +
											@lMeetSubject + ' ' +
											@meet_subject + ' ' + @MeetDesc + ' ' + @meet_description + ' ' + @meetduration + ' ' + CONVERT(VARCHAR,@meet_howLong)


								-- ---------------------------------------------------------------
								-- ARMADO DEL HTML PARA EL MAIL
								-- ---------------------------------------------------------------
								--ARMAMOS HEADER Y FOOTER EN CASO DE QUE HAYA VALORES EN LAS TABLAS

								DECLARE @MailTableHeader AS NVARCHAR(MAX),
										@HeaderText		 AS NVARCHAR(MAX),
										@FooterText		 AS NVARCHAR(MAX)

								SET @HeaderText = ''
								SET @FooterText = ''

								SELECT
									@HeaderText = tcmmhf.htmlHeader,
									@FooterText = tcmmhf.htmlFooter
								FROM tbCRM_MeetMailHeaderFooter tcmmhf
								WHERE	tcmmhf.comp_id	 = @comp_id  AND
										tcmmhf.meett_id	 = @meett_id AND
										tcmmhf.meetst_id = @meetst_id

								IF NOT LEN(@HeaderText) > 0
									SET @HeaderText = ''
								IF NOT LEN(@FooterText) > 0
									SET @FooterText = ''

								-- ---------------------------------------------------------------
								-- ESTADO
								DECLARE @Status			AS VARCHAR(MAX)
								DECLARE @Meet_Status	AS VARCHAR(MAX)

									SELECT @Status = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30022

									SELECT @Meet_Status = tcms.meetst_desc FROM tbCRM_MeetStatus tcms WHERE tcms.comp_id = @comp_id AND tcms.meetst_id = @meetst_id

								--variables para el formateo del html email
									DECLARE	@MailTable							NVARCHAR(MAX),
											@MailEndTable						NVARCHAR(MAX),
											@Mailsubject						NVARCHAR(MAX),
											@MailbodyHeader						NVARCHAR(MAX),
											@Mailbody							NVARCHAR(MAX),
											@MailbodyFooter						NVARCHAR(MAX),
											@MailImageSRC						NVARCHAR(MAX)


								SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

								SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
												 'cellpadding="1" cellspacing="1" border="3">'

								SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
													  '<b>' + @subject + @desc + '</b><br /><br /><br />'


								SET @Mailbody = ''
								SET @MailBody =

									'
									<tr>
										<td align="center" bgcolor="' + @HeaderColor +  '">' +
											@HeaderMessage + ' ' + CONVERT(VARCHAR,@meet_advertiseCount + 1) + ' ' +
										'</td>
									</tr>
									<tr><td align="center">' +
										@desc + ' ' + @message + ' ' +  @user_origen_name  + ' ' +
									'</td><tr><td align="center">' +
										@body + ' ' +
									'</td></tr><td align="center">' +
										@lMeetSubject + ' ' + @meet_subject + ' ' +
									'</td></tr><td align="center">' +
										@Status + ' ' + @Meet_Status + ' ' +
									'</td><tr><td align="center">' +
										@MeetDesc + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@meet_description) + ' ' +
									'</td><tr><td align="center">' +
										@meetduration + ' ' + CONVERT(VARCHAR,@meet_howLong) + ' ' +
									'</td></tr>'

								SET @MailEndTable = + '</table>'

								SET @MailbodyFooter = '</div>'






								SET @Mailbody = @HeaderText + ' ' +  @MailTable + ' ' + @Mailbody + @MailEndTable + ' ' + @FooterText + ' ' + @MailbodyFooter
								--SELECT @MailTable
								--SELECT @Mailbody
								--SELECT @MailEndTable
								--SELECT @MailImageSRC
								-- ---------------------------------------------------------------

								-- -----------------------------------------------------------------------------
								-- Envio del Mail
								-- -----------------------------------------------------------------------------
									DECLARE @strMailString	AS NVARCHAR(MAX)
									DECLARE @strMail		AS NVARCHAR(MAX)
									DECLARE @strMailCC		AS NVARCHAR(MAX)
									DECLARE @strMailCCO		AS NVARCHAR(MAX)
									DECLARE @strMailFrom    AS NVARCHAR(MAX)
									SELECT  @strMailString	= dbo.fnCRM_GetCustomerEmailByMeetType(@comp_id, @cust_id, @meett_id, @meetst_id, @meet_id, @user_id)
									SELECT  @strMail		= dbo.fnSplitPosition(@strMailString, '|',1)
									SELECT  @strMailCC		= dbo.fnSplitPosition(@strMailString, '|',2)
									SELECT  @strMailCCO		= dbo.fnSplitPosition(@strMailString, '|',3)
									SELECT  @strMailFrom	= dbo.fnSplitPosition(@strMailString, '|',4)

									-- Mail al Usuario Asignado
									--select @user_mail_origin
									exec spSystem_sendEMail
															@compId				= @comp_id,
															@precipients		= @user_mail_origin,
															@pcopy_recipients	= null,
															@psubject			= @subject,
															@pbody_format		= 'HTML',
															@pbody				= @MailBody,
															@pfile_attachments	= null,
															@pReplyTo			= @strMailFrom,
															@pblind_copy_recipients='',
															@pUser_Id			= @user_id

							-- --------------------------------------------------------------------------------------------------------------------------------
							-- --------------------------------------------------------------------------------------------------------------------------------


							--ACTUALIZAMOS LA FECHA DE AVISO
							UPDATE tbCRM_Meet
							SET
								meet_advertiseLastDate	= GETDATE(),
								meet_nextReviewdateLastMailDate =		CASE
																			WHEN meet_nextReviewdate IS NULL THEN NULL
																			WHEN meet_nextReviewdate <= GETDATE() THEN GETDATE()
																			ELSE meet_nextReviewdate
																		END
							WHERE	comp_id				= @comp_id AND
									meet_id				= @meet_id


							DECLARE @strURL AS NVARCHAR(600)
							SET @strURL = 'wfmCRM_MeetDetail.aspx?&BraId='	+ CONVERT(VARCHAR,@bra_id)	+
																'&MeetId='	+ CONVERT(VARCHAR,@meet_id) +
																'&Action='  + 'U'						+ '&'

							--GRABAMOS WORKFLOW
							INSERT INTO tbWorkflow
							(
								comp_id,
								bra_id,
								wf_type,
								wf_isProcessed,
								user_id_from,
								user_id_assigned,
								user_id_processed,
								prof_id_assigned,
								wf_dateOfAssigned,
								wf_dateOfProcessing,
								wf_link,
								wf_message1,
								wf_message2,
								wf_htmlTop,
								wf_htmlBody,
								wf_html_Bottom,
								meet_id
							)
							VALUES
							(
								@comp_id,
								@bra_id,
								777,
								'False',
								NULL,
								@user_id, --@intUser4Notify,
								NULL,
								NULL,
								GETDATE(),
								NULL,
								@strURL,
								@subject,
								'',
								@MailBody, --@strRet_ErrorDescription,
								'',
								'',
								@meet_id
							)

						END


				-- próxima lectura del cursor
				FETCH	cursor_Meet
				INTO
					@comp_id,
					@meet_id,
					@bra_id,
					@meetst_id,
					@meet_subject,
					@meet_date4Begin,
					@meet_location,
					@meet_howLong,
					@meet_howLong_minutes,
					@meet_remind,
					@meet_description,
					@user_id,
					@cust_id,
					@meett_id,
					@meet_advertiseDate,
					@meet_advertiseCount,
					@meet_advertiseLastDate,
					@bisIsAdvertiseLastDate


			END

			CLOSE cursor_Meet
			DEALLOCATE cursor_Meet

	END
GO








CREATE PROCEDURE [dbo].[spCRM_Meet_updateData]
(
	@comp_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@lang_id				INT,

	@meet_id				INT,
	@meetst_id				INT,
	@meet_subject			NVARCHAR(200),
	@meet_date4Begin		DATETIME,
	@meet_location			NVARCHAR(1000),
	@meet_howLong			INT,
	@meet_howLong_minutes	INT,
	@meet_remind			BIT,
	@meet_description		NVARCHAR(4000),
	@soh_Bra_id				INT,
	@soh_Soh_id				INT,
	@case_id				INT,
	@task_id				INT,
	@contact_id				INT,
	@meet_price				DECIMAL(19,4),
	@curr_id				INT,
	@cust_id				INT,
	@chkCA					BIT,
	@meett_id				INT,
	@meet_emailAdditional	VARCHAR(250),
	@supp_id				INT,
	@meet_nextReviewdate    DATETIME,
	@pro_id					INT
)
AS
SET NOCOUNT ON


BEGIN


	SET NOCOUNT ON

		IF @cust_id = -1
			BEGIN
				SET @cust_id = NULL
			END
		IF @contact_id = -1
			BEGIN
				SET @contact_id = NULL
			END
		IF @supp_id = -1
			BEGIN
				SET @supp_id = NULL
			END
		IF @pro_id	= -1
			BEGIN
				SET @pro_id = NULL
			END


	UPDATE	tbCRM_Meet
	SET
		bra_id					= @bra_id,
		meetst_id				= @meetst_id,
		meet_subject			= @meet_subject,
		meet_date4Begin			= @meet_date4Begin,
		meet_location			= @meet_location,
		meet_howLong			= @meet_howLong,
		meet_howLong_minutes	= @meet_howLong_minutes,
		meet_remind				= @meet_remind,
		meet_description		= @meet_description,
		soh_Bra_id				= @soh_Bra_id,
		soh_Soh_id				= @soh_Soh_id,
		case_id					= @case_id,
		task_id					= @task_id,
		contact_id				= @contact_id,
		meet_price				= @meet_price,
		curr_id					= @curr_id,
		cust_id					= @cust_id,
		meett_id				= @meett_id,
		meet_emailAdditional	= @meet_emailAdditional,
		supp_id					= @supp_id,
		meet_nextReviewdate		= @meet_nextReviewdate,
		pro_id					= @pro_id

	WHERE	comp_id			= @comp_id
	AND		meet_id			= @meet_id



-- ---------------------------------------
-- Textos para armado del mail completo
DECLARE
	@lMeetSubject		VARCHAR(100),
	@MeetDesc			VARCHAR(100),
	@date4begin			VARCHAR(100),
	@date2end			VARCHAR(100),
	@callduration		VARCHAR(100),
	@meetduration		VARCHAR(100)

--ASUNTO
select @lMeetSubject	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300626
--DESCRIPCION
select @MeetDesc		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300627
--Fecha Inicio
select @date4begin		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300629
--Fecha Fin
select @date2end		= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300630
--Duración de la llamada
select @callduration	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 300633
--Duración de la reunion
select @meetduration	= tut.utexts_desc
from tbsysUniqueTexts	tut
where tut.lang_id		= @lang_id
and tut.utexts_id		= 30064
-- ---------------------------------------

declare
	@msg	nvarchar(4000)

select @msg = (tut.utexts_desc + ' ' + convert(varchar,@meet_id)) from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 987


--STL
declare @description as nvarchar(500)

select
	@description = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 300063

set @description = @description + ' ' + convert(varchar,@meet_id)


insert into tbSecurityLog
(
	comp_id,
	bra_id,
	user_id,
	seclog_obs_1,
	seclog_obs_2,
	seclog_image,
	seclog_obs_3,
	seclog_obs_4,
	seclog_cd,
	aut_id,
	sysCode_id,
	menu_id,
	menu_ts,
	request_ip,
	request_name,
	aure_isok,
	aure_user_id,
	seclog_pageHTML,
	prof_id,
	aure_cd,
	aure_id,
	seclog_id1,
	seclog_id2,
	seclog_id3
)
VALUES
(
	@comp_id,
	@bra_id,
	@user_id,
	@description,
	NULL,
	NULL,
	NULL,
	NULL,
	getdate(),
	NULL,
	1301,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	@prof_id,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL
)

-- ----------------------------------------------------------
-- ACTUALIZAMOS SALE ORDER
-- ----------------------------------------------------------
	if (@chkCA = 'False')
		begin
			declare
					@soss_id		INT
			select
					@soss_id		= ssos_id
			from tbSaleOrderHeader				tsoh
			where	tsoh.comp_id	= @comp_id
			and		tsoh.bra_id		= @bra_id
			and		tsoh.soh_id		= @soh_soh_id

			if (@soss_id = 10)
				begin
					update tbSaleOrderHeader
					SET
							ssos_id		= 20
					where	comp_id		= @comp_id
					and		bra_id		= @bra_id
					and		soh_id		= @soh_soh_id
				end
		end
-- ----------------------------------------------------------

-- -------------------------------------------------------
-- Obtenemos los mails a enviar a los grupos de usuarios
-- -------------------------------------------------------

declare
	@email_recipients	nvarchar(4000),
	@title				nvarchar(1000),
	@text				nvarchar(4000)



/*************************************************************************************/
/*En caso de poseer un TEXTO EN LA HEADER/FOOTER propia, utilizamos ese, sino        */
/*utilizamos el valor genérico de CRM de la UniqueTexts                              */
/*************************************************************************************/

	IF EXISTS (SELECT 1
	           FROM tbCRM_MeetMailHeaderFooter			tcmmhf WITH (NOLOCK)
	           WHERE	tcmmhf.comp_id					= @comp_id AND
						tcmmhf.meett_id					= @meett_id AND
						tcmmhf.meetst_id				= @meetst_id AND
						ISNULL(tcmmhf.crmhf_Subject,'') <> '')
		BEGIN
			SELECT
				@title = tcmmhf.crmhf_Subject
			  FROM tbCRM_MeetMailHeaderFooter			tcmmhf WITH (NOLOCK)
	           WHERE	tcmmhf.comp_id		= @comp_id AND
						tcmmhf.meett_id		= @meett_id AND
						tcmmhf.meetst_id	= @meetst_id

		END
	ELSE
		BEGIN
			SELECT
				@title = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 300071
		END



select @text = tut.utexts_desc
  from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 300063

set @text = @text + ' ' + convert(varchar,@meet_id) /*+ ' ' + @lMeetSubject + ' ' +
			@meet_subject + ' ' + @MeetDesc + ' ' + @meet_description + ' ' + @meetduration + ' ' + CONVERT(VARCHAR,@meet_howLong)*/



-- ---------------------------------------------------------------
-- ARMADO DEL HTML PARA EL MAIL
-- ---------------------------------------------------------------
--ARMAMOS HEADER Y FOOTER EN CASO DE QUE HAYA VALORES EN LAS TABLAS

DECLARE @MailTableHeader AS NVARCHAR(MAX),
		@HeaderText		 AS NVARCHAR(MAX),
		@FooterText		 AS NVARCHAR(MAX)

SET @HeaderText = ''
SET @FooterText = ''

SELECT
	@HeaderText = tcmmhf.htmlHeader,
	@FooterText = tcmmhf.htmlFooter
FROM tbCRM_MeetMailHeaderFooter tcmmhf
WHERE	tcmmhf.comp_id	 = @comp_id  AND
		tcmmhf.meett_id	 = @meett_id AND
		tcmmhf.meetst_id = @meetst_id

IF NOT LEN(@HeaderText) > 0
	SET @HeaderText = ''
IF NOT LEN(@FooterText) > 0
	SET @FooterText = ''

-- ---------------------------------------------------------------
-- ESTADO
DECLARE @Status			AS VARCHAR(MAX)
DECLARE @Meet_Status	AS VARCHAR(MAX)

	SELECT @Status = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30022

	SELECT @Meet_Status = tcms.meetst_desc FROM tbCRM_MeetStatus tcms WHERE tcms.comp_id = @comp_id AND tcms.meetst_id = @meetst_id

--variables para el formateo del html email
	DECLARE	@MailTable							NVARCHAR(MAX),
			@MailEndTable						NVARCHAR(MAX),
			@Mailsubject						NVARCHAR(MAX),
			@MailbodyHeader						NVARCHAR(MAX),
			@Mailbody							NVARCHAR(MAX),
			@MailbodyFooter						NVARCHAR(MAX),
			@MailImageSRC						NVARCHAR(MAX)


SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
				 'cellpadding="1" cellspacing="1" border="1">'

SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
					  '<b>' + @title + '</b><br /><br /><br />'


SET @Mailbody = ''
SET @MailBody =

	'<tr><td align="center">' +
	@text + ' ' + convert(varchar,@meet_id) + ' ' +
	'</td><tr><td align="center">' +
	@lMeetSubject + ' ' + @meet_subject + ' ' +
	'</td></tr><td align="center">' +
		@Status + ' ' + @Meet_Status + ' ' +
	'</td></tr><td align="center">' +
	@MeetDesc + ' ' + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@meet_description) + ' ' +
	'</td><tr><td align="center">' +
	@meetduration + ' ' + CONVERT(VARCHAR,@meet_howLong) + ' ' +
	'</td></tr>'

SET @MailEndTable = + '</table>'

SET @MailbodyFooter = '</div>'






SET @Mailbody = @HeaderText + ' ' +  @MailTable + ' ' + @Mailbody + @MailEndTable + ' ' + @FooterText + ' ' + @MailbodyFooter
--SELECT @MailTable
--SELECT @Mailbody
--SELECT @MailEndTable
--SELECT @MailImageSRC
-- ---------------------------------------------------------------






set @email_recipients = ''

select
	@email_recipients = @email_recipients + '; ' + tu.user_email

from tbCRM_UserGroups						tcug									WITH (NOLOCK)

	inner join tbCRM_UserGroupsDetail		tcugd									WITH (NOLOCK)
	on	tcugd.comp_id	= tcug.comp_id
	AND tcugd.crmug_id	= tcug.crmug_id

	inner join tbUser						tu										WITH (NOLOCK)
	on tu.[user_id] = tcugd.[user_id]

where	tcug.comp_id						= @comp_id
--and		tcugd.user_id						= @user_id
and		tcugd.crmug_id						in (select crmug_id
													from tbCRM_UserGroupsDetail tcugd2				WITH (NOLOCK)
													where	tcugd2.comp_id	 = @comp_id
													and		tcugd2.[user_id] = @user_id)
and		tcugd.crmugd_disabled				= 'False'
and     tcugd.crmugd_reciveEmailofChanges	= 'True'
and		tcugd.crmugd_4Meet					= 'True'
and		(/*@meett_id = -1*/ tcugd.meett_id  IS NULL or tcugd.meett_id   = @meett_id)

--if @email_recipients <> ''
--	begin
--		SET @email_recipients = SUBSTRING(@email_recipients,2,LEN(@email_recipients) - 1)
--
--		exec spSystem_sendEMail
--			@compId = @comp_id,
--			@precipients = @email_recipients,
--			@pcopy_recipients = null,
--			@psubject = @title,
--			@pbody_format = 'HTML',
--			@pbody = @Mailbody ,
--			@pfile_attachments = null,
--			@pReplyTo = NULL,
--			@pblind_copy_recipients='',
--			@pUser_Id				= @user_id
--	END


-- -----------------------------------------------------------------------------
-- Envio del Mail
-- -----------------------------------------------------------------------------
	DECLARE @user_mail_origin AS NVARCHAR(MAX)
	DECLARE @strMailString	AS NVARCHAR(MAX)
	DECLARE @strMail		AS NVARCHAR(MAX)
	DECLARE @strMailCC		AS NVARCHAR(MAX)
	DECLARE @strMailCCO		AS NVARCHAR(MAX)
	DECLARE @strMailFrom    AS NVARCHAR(MAX)
	SELECT  @strMailString	= dbo.fnCRM_GetCustomerEmailByMeetType(@comp_id, @cust_id, @meett_id, @meetst_id, @meet_id, @user_id)
	SELECT  @strMail		= dbo.fnSplitPosition(@strMailString, '|',1)
	SELECT  @strMailCC		= dbo.fnSplitPosition(@strMailString, '|',2)
	SELECT  @strMailCCO		= dbo.fnSplitPosition(@strMailString, '|',3)
	SELECT  @strMailFrom	= dbo.fnSplitPosition(@strMailString, '|',4)
	--Datos del Usuario de Origen
		select @user_mail_origin = tu.user_email
			from	tbUser tu
			where	tu.[user_id] = @user_id

	---- Mail al Usuario Asignado
	--exec spSystem_sendEMail
	--						@compId				= @comp_id,
	--						@precipients		= @user_mail_origin,
	--						@pcopy_recipients	= null,
	--						@psubject			= @title,
	--						@pbody_format		= 'HTML',
	--						@pbody				= @MailBody,
	--						@pfile_attachments	= null,
	--						@pReplyTo			= @strMailFrom,
	--						@pblind_copy_recipients='',
	--						@pUser_Id			= @user_id

	-- Mail de Aviso a Clientes, Contactos, Adicionales, Etc.
	exec spSystem_sendEMail
							@compId					= @comp_id,
							@precipients			= @strMail,
							@pcopy_recipients		= @strMailCC,
							@psubject				= @title,
							@pbody_format			= 'HTML',
							@pbody					= @Mailbody,
							@pfile_attachments		= null,
							@pReplyTo				= @strMailFrom,
							@pblind_copy_recipients	= @strMailCCO,
							@pUser_Id				= @user_id
	-- -----------------------------------------------------------------------------


END
GO




