			FROM tbCRM_MeetStatus tcms	WITH (NOLOCK)
			WHERE tcms.comp_id = @comp_id

		END
GO







CREATE PROCEDURE [dbo].[spCRM_MeetStatus_getCombo]
(
	@comp_id			INT,
	@status				INT,	-- @status  -1 Update; -2 Insert; -3 Todos
	@prof_id			INT,
	@meetst_id			INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo
	@user_id			INT,
	@bra_id				INT
)
AS


	-- --------------------------------------------
	-- Testing
	-- --------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@status		INT,
		@prof_id	INT,
		@meetst_id	INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo
		@user_id	INT,
		@bra_id		INT

		SET @comp_id	= 1
		SET @status		= -1
		SET @prof_id	= 1
		SET @meetst_id	= 4
		SET @user_id	= 41
		SET @bra_id		= 1
	*/
	-- --------------------------------------------

	SET NOCOUNT ON


	DECLARE @bitActualStatusIsInitial	AS BIT
	DECLARE @bitUserCanSetInitialStatus AS BIT
	SET		@bitActualStatusIsInitial	= 'False'
	SET		@bitUserCanSetInitialStatus = 'False'


	SELECT	@bitActualStatusIsInitial	= IsNull(tcts.meetst_isInitialStatus,'False'),
			@bitUserCanSetInitialStatus = IsNull(tu.user_available4CRM_CanReAsignateTask,'False')
		FROM tbCRM_MeetStatus tcts				WITH (NOLOCK)
		INNER JOIN tbUser tu					WITH (NOLOCK)
			ON	tu.[user_id] = @user_id
		WHERE	tcts.comp_id = @comp_id AND
				tcts.meetst_id = @meetst_id




	IF  EXISTS(
				SELECT 1
					FROM tbCRM_MeetStatus2Profile tcttp							WITH (NOLOCK)
					INNER JOIN tbCRM_MeetStatus tcts							WITH (NOLOCK)
						ON	tcts.comp_id		= tcttp.comp_id AND
							tcts.meetst_id		= tcttp.meetst_id
					WHERE	tcttp.comp_id		= @comp_id		AND
							tcttp.bra_id		= @bra_id		AND
							tcttp.prof_id		= @prof_id		AND
							tcttp.disabled		= 'False'		AND
							tcts.meetst_disabled	= 'False'
				)
		BEGIN

			SELECT	tcts.meetst_id		[Id],
					CASE
						WHEN tcts.meetst_isInitialStatus	= 'True' THEN	'1'
						WHEN tcts.meetst_isFinalStatus		= 'True' THEN	'3'
						ELSE												'2'
					END + ' | ' +
					tcts.meetst_desc		[Desc]

				FROM	   tbCRM_MeetStatus						tcts			WITH (NOLOCK)
				LEFT JOIN  tbCRM_MeetStatus2Profile				tcttp			WITH (NOLOCK)
					ON	tcttp.comp_id		= tcts.comp_id	AND
						tcttp.bra_id		= @bra_id		AND
						tcttp.meetst_id		= tcts.meetst_id	AND
						tcttp.prof_id		= @prof_id
				WHERE		tcts.comp_id	= @comp_id 							AND
							(
								(
									(
										tcttp.comp_id		IS NOT NULL			AND
										tcttp.disabled		= 'False'			AND
										tcts.meetst_disabled	= 'False'
									)

									AND

									CASE
										WHEN	@status	 = -1											AND
												ISNULL(tcts.meetst_isInitialStatus,'False')	= 'True'	AND
												@bitActualStatusIsInitial					= 'False'	AND
												@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
										WHEN   (@status	 = -1	AND ISNULL(tcts.meetst_isInitialStatus, 'False')	= 'False')	THEN	'True'
										WHEN   (@status	 = -2	AND ISNULL(tcts.meetst_isInitialStatus, 'False')	= 'True')	THEN	'True'
										WHEN    @status	 = -3																THEN	'True'
										ELSE																						'False'
									END = 'True'
								)

								OR

								tcts.meetst_id	=	@meetst_id
							)
				ORDER BY	tcts.meetst_desc

		END

	ELSE

		BEGIN

			SELECT	tcts.meetst_id			[Id],
					CASE
						WHEN tcts.meetst_isInitialStatus	= 'True' THEN	'1'
						WHEN tcts.meetst_isFinalStatus		= 'True' THEN	'3'
						ELSE												'2'
					END + ' | ' +
					tcts.meetst_desc		[Desc]

				FROM		tbCRM_MeetStatus																tcts			WITH (NOLOCK)

				WHERE		tcts.comp_id	=	@comp_id 													AND
							(
								(
									(tcts.prof_id IS NULL OR tcts.prof_id = @prof_id AND tcts.meetst_disabled = 'False')	AND
									CASE
										WHEN	@status	 = -1											AND
												ISNULL(tcts.meetst_isInitialStatus,'False')	= 'True'	AND
												@bitActualStatusIsInitial					= 'False'	AND
												@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
										WHEN   (@status	 = -1	AND ISNULL(tcts.meetst_isInitialStatus, 'False')	= 'False')	THEN	'True'
										WHEN   (@status	 = -2	AND ISNULL(tcts.meetst_isInitialStatus, 'False')	= 'True')	THEN	'True'
										WHEN    @status	 = -3																THEN	'True'
										ELSE																						'False'
									END = 'True'
								)
								OR
								@meetst_id = tcts.meetst_id
							)
				ORDER BY	tcts.meetst_desc

		END



GO




CREATE PROCEDURE spCRM_MeetStatusGetDataById
(
	@comp_id	INT,
	@meetst_id	INT
)
AS
	SET NOCOUNT ON

	BEGIN

		SELECT
			tcms.comp_id,
			tcms.meetst_id,
			tcms.prof_id,
			tcms.meetst_desc,
			tcms.meetst_disabled,
			tcms.bra_id,
			tcms.meetst_isFinalStatus,
			tcms.meetst_mail2Customer,
			tcms.meetst_mail2Contact,
			tcms.meetst_mail2Additional,
			ISNULL(tcms.meetst_isInitialStatus,'False') [meetst_isInitialStatus]

		FROM tbCRM_MeetStatus				tcms
		WHERE	tcms.comp_id	= @comp_id	AND
				tcms.meetst_id	= @meetst_id
	END
GO




CREATE PROCEDURE spCRM_MeetStatusNotInitialStatus
(
	@comp_id	INT
)

AS

	SET NOCOUNT ON

	BEGIN

		SELECT
			tcms.meetst_id									[Id],
			tcms.meetst_desc								[Desc]
		FROM tbCRM_MeetStatus								tcms
		WHERE	tcms.comp_id								= @comp_id	AND
				ISNULL(tcms.meetst_isInitialStatus,'False')	= 'False'

	END


GO




