CREATE procedure [dbo].[spCRM_MeetType_getCombo]
(
	@comp_id			INT,
	@prof_id			INT,
	@meett_id			INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo. -9 trae TODOS
	@user_id			INT,
	@bra_id				INT
)
as



BEGIN

	set NOCOUNT on


	-- ---------------------------------------------
	-- Testing
	-- ---------------------------------------------
	/*
	DECLARE
	@comp_id			INT,
	@prof_id			INT,
	@meett_id			INT,
	@user_id			INT,
	@bra_id				INT
	SET @comp_id	= 1
	SET @prof_id	= 1
	SET @meett_id	= -1
	SET @user_id	= 41
	SET @bra_id		= 1
	*/
	-- ---------------------------------------------


	IF EXISTS(
				SELECT 1
					FROM tbCRM_MeetType2Profile tcttp
					INNER JOIN tbCRM_MeetType tctt
						ON	tctt.comp_id		= tcttp.comp_id AND
							tctt.meett_id		= tcttp.meett_id
					WHERE	tcttp.comp_id		= @comp_id	AND
							tcttp.bra_id		= @bra_id	AND
							tcttp.prof_id		= @prof_id	AND
							tcttp.[disabled]	= 'False'	AND
							tctt.meett_disabled = 'False'
				)
		BEGIN

				SELECT		tctt.meett_id	[Id],
							tctt.meett_desc	[Desc]
					FROM		tbCRM_MeetType			tctt
					LEFT JOIN	tbCRM_MeetType2Profile	tcttp
						ON	tcttp.comp_id		= tctt.comp_id		AND
							tcttp.meett_id		= tctt.meett_id		AND
							tcttp.prof_id		= @prof_id			AND
							tcttp.bra_id		= @bra_id
				    WHERE
							(
								tctt.comp_id		= @comp_id			AND
				    			tctt.meett_disabled	= 'False'			AND
								tcttp.disabled		= 'False'			AND
								tcttp.comp_id		IS NOT NULL
							)
							OR
							tctt.meett_id	= @meett_id
					ORDER BY tctt.meett_desc

		END

	ELSE

		BEGIN

			select
				tctt.meett_id	[Id],
				tctt.meett_desc	[Desc]
				from tbCRM_MeetType tctt			WITH (NOLOCK)
				where	tctt.comp_id		= @comp_id	AND
					   (
			   				tctt.meett_id	= @meett_id
			   				OR
							(
								(tctt.prof_id IS NULL OR tctt.prof_id = @prof_id)	AND
								 tctt.meett_disabled = 'False'
							)
					   )
				order by [Desc]

		END
END
GO




CREATE PROCEDURE [dbo].[spCRM_Notes_DeleteData]
(
	@comp_id			INT,
	@crmn_id			INT
)
AS SET NOCOUNT ON

	BEGIN

		DELETE FROM tbCRM_Notes
			FROM tbCRM_Notes crmn
			LEFT JOIN tbCollectionManagementDetail AS tcmd	WITH (NOLOCK)
				ON	tcmd.comp_id = crmn.comp_id AND
					tcmd.crmn_id = crmn.crmn_id
			WHERE	crmn.comp_id = @comp_id AND
					crmn.crmn_id = @crmn_id	AND
					tcmd.comp_id IS NULL

	END

GO





CREATE PROCEDURE [dbo].[spCRM_Notes_GetDataByCustomer]
(
	@comp_id	INT,
	@cust_id	INT,
	@prof_id	INT
)

AS

	SET NOCOUNT ON

	-- ------------------------------------
	-- TESTING
	-- ------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@cust_id	INT,
		@prof_id	INT

	SELECT
		@comp_id	= 1,
		@cust_id	= 24288,
		@prof_id	= 1
	*/
	-- ------------------------------------

	BEGIN

		SET DATEFORMAT 'YMD'

		SELECT
			tcn.crmn_cd,
			ISNULL(tu.user_nick,'')				[user_nick_Creator],
			ISNULL(tu2.user_nick,'')			[user_nick_LastUpdate],
			ISNULL(tc.cust_name,'')				[cust_name],
			ISNULL(tc2.contact_name,'')			[contact_name],
			ISNULL(tb.bra_desc,'')				[bra_desc],
			tcn.so_soh_id,
			ISNULL(tcn.crmn_note1,'')			[crmn_note1],
			ISNULL(tcn.crmn_note2,'')			[crmn_note2],
			tcn.crmn_id							[ID]


		FROM tbCRM_Notes						tcn

			LEFT JOIN tbUser					tu
			ON	tu.[user_id]	= tcn.user_id_Creator

			LEFT JOIN tbUser					tu2
			ON	tu2.[user_id]	= tcn.user_id_lastUpdate

			LEFT JOIN tbCustomer				tc
			ON	tc.comp_id		= tcn.comp_id	AND
				tc.cust_id		= tcn.cust_id

			LEFT JOIN tbContact					tc2
			ON	tc2.comp_id		= tcn.comp_id	AND
				tc2.contact_id	= tcn.contact_id

			LEFT JOIN tbBranch					tb
			ON	tb.comp_id		= tcn.comp_id	AND
				tb.bra_id		= tcn.so_bra_id

			INNER JOIN tbCRM_NoteType			tcnt
			ON	tcnt.comp_id	= tcn.comp_id	AND
				tcnt.crmnt_id	= tcn.crmnt_id

			INNER JOIN tbCRM_NoteType2Profile	tcntp
			ON  tcntp.comp_id	= tcnt.comp_id	AND
				tcntp.crmnt_id	= tcnt.crmnt_id
--
		WHERE	tcn.comp_id		= @comp_id		AND
				tcn.cust_id		= @cust_id		AND
				tcntp.prof_id	= @prof_id		AND
				tcnt.crmnt_alertOnSaleOrder		= 'True'

	END

GO




CREATE PROCEDURE [dbo].[spCRM_Notes_GetDataByFilters]
(
	@comp_id			INT,
	@bra_id				INT,
	@user_creator_id	INT,
	@user_update_id		INT,
	@cust_id			INT,
	@contact_id			INT,
	@soh_bra_id			INT,
	@soh_id				INT,
	@prof_id			INT,
	@pro_id				INT,
	@crmnt_id			INT

)
AS


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON
	BEGIN
		-- --------------------------------------
		-- Testing
		-- --------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@user_creator_id	INT,
				@user_update_id		INT,
				@cust_id			INT,
				@contact_id			INT,
				@soh_bra_id			INT,
				@soh_id				INT,
				@prof_id			INT

			SELECT
				@comp_id			= 1,
				@bra_id				= -1,
				@user_creator_id	= -1,
				@user_update_id		= -1,
				@cust_id			= -1,
				@contact_id			= -1,
				@soh_bra_id			= 0,
				@soh_id				= 0,
				@prof_id			= 1
		*/
		-- --------------------------------------



		SELECT TOP 10000
			' '														[ ],
			CONVERT(VARCHAR,tcn.user_id_Creator)					[ ],
			ISNULL(tc.cust_name,'')									[cust_name],
			ISNULL(tc2.contact_name,'')								[contact_name],
			ISNULL(tcn.crmn_note1,'')								[crmn_note1],
			ISNULL(tcn.crmn_note2,'')								[crmn_note2],
			tcn.crmn_cd												[crmn_cd],
			isnull(tcnt.crmnt_desc,'')								[crmnt_desc],
			tu.user_nick,
			ISNULL(tu2.user_nick,'')								[user_nick_Updt],
			tb.bra_desc,
			tb2.bra_desc											[so_bra_id],
			tcn.so_soh_id,
			ISNULL(tcme.cme_desc,'')								[cme_desc],
			tcn.cme_validUpToDate									[cme_validUpToDate],

			tcn.crmn_id												[ID]

		FROM tbCRM_Notes						tcn			WITH(NOLOCK)

			INNER JOIN tbCRM_NoteType			tcnt		WITH(NOLOCK)
			ON	tcnt.comp_id	= tcn.comp_id	AND
				tcnt.crmnt_id	= tcn.crmnt_id

			--INNER JOIN tbCRM_NoteType2Profile	tcntp		WITH(NOLOCK)
			--ON	tcntp.comp_id	= tcnt.comp_id	AND
			--	tcntp.crmnt_id	= tcnt.crmnt_id AND
			--	tcntp.prof_id   = @prof_id

			INNER JOIN tbUser					tu			WITH(NOLOCK)
			ON tu.[user_id]		= tcn.user_id_Creator

			LEFT JOIN tbUser					tu2			WITH(NOLOCK)
			ON tu2.[user_id]	= tcn.user_id_lastUpdate

			LEFT JOIN tbCustomer				tc			WITH(NOLOCK)
			ON  tc.comp_id		= tcn.comp_id	AND
				tc.cust_id		= tcn.cust_id

			LEFT JOIN tbContact					tc2			WITH(NOLOCK)
			ON	tc2.comp_id		= tcn.comp_id	AND
				tc2.contact_id	= tcn.contact_id

			LEFT JOIN tbBranch					tb			WITH(NOLOCK)
			ON	tb.comp_id		= tcn.comp_id	AND
				tb.bra_id		= tcn.bra_id

			LEFT JOIN tbBranch					tb2			WITH(NOLOCK)
			ON	tb2.comp_id		= tcn.comp_id	AND
				tb2.bra_id		= tcn.so_bra_id

			LEFT JOIN tbCollectionManagementException tcme	WITH(NOLOCK)
			ON	tcme.comp_id		= tcn.comp_id	AND
				tcme.cme_id			= tcn.cme_id


		WHERE	tcn.comp_id				= @comp_id											AND
				(@bra_id				= -1 OR tcn.bra_id				= @bra_id)			AND
				(@user_creator_id		= -1 OR tcn.user_id_Creator		= @user_creator_id)	AND
				(@user_update_id		= -1 OR tcn.user_id_lastUpdate	= @user_update_id)	AND
				(@cust_id				= -1 OR tcn.cust_id				= @cust_id)			AND
				(@contact_id			= -1 OR tcn.contact_id			= @contact_id)		AND
				(@soh_bra_id			= 0  OR tcn.so_bra_id			= @soh_bra_id)		AND
				(@soh_id				= 0  OR tcn.so_soh_id			= @soh_id)			AND
				--tcntp.prof_id			= @prof_id
				(@pro_id			= -1		OR		tcn.pro_id		= @pro_id)			AND
				(@crmnt_id			= -1		OR		tcnt.crmnt_id	= @crmnt_id)
		ORDER BY tcn.crmn_id DESC
	END


GO




CREATE PROCEDURE [dbo].[spCRM_Notes_GetDataById]
(
	@comp_id	INT,
	@crmn_id	INT
)

AS SET NOCOUNT ON

	BEGIN

		SELECT
			tcn.comp_id,
			tcn.crmn_id,
			tcn.bra_id,
			tcn.user_id_Creator,
			tcn.user_id_lastUpdate,
			tcn.crmn_cd,
			tcn.cust_id,
			tcn.contact_id,
			tcn.so_bra_id,
			tcn.so_soh_id,
			ISNULL(tcn.crmn_note1,'')	[crmn_note1],
			ISNULL(tcn.crmn_note2,'')	[crmn_note2],
			tcn.crmn_PDF,
			tcn.cme_id,
			tcn.cme_validUpToDate,
			ISNULL(tcn.crmnt_id,0)		[crmnt_id],
			tcn.pro_id

		FROM tbCRM_Notes				tcn

		WHERE	tcn.comp_id = @comp_id AND
				tcn.crmn_id = @crmn_id

	END
GO




CREATE PROCEDURE [dbo].[spCRM_Notes_HasAlerts]
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@cust_id	INT
)
AS

BEGIN

	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	SELECT
		tcn.crmn_id
	FROM tbCRM_Notes						tcn
		INNER JOIN tbCRM_NoteType			tcnt
		ON	tcnt.comp_id	= tcn.comp_id	AND
			tcnt.crmnt_id	= tcn.crmnt_id
		INNER JOIN tbCRM_NoteType2Profile	tcntp
		ON	tcntp.comp_id	= tcnt.comp_id	AND
			tcntp.crmnt_id	= tcnt.crmnt_id

	WHERE	tcn.comp_id					= @comp_id		AND
			tcntp.bra_id				= @bra_id		AND
			tcntp.prof_id				= @prof_id		AND
			tcnt.crmnt_alertOnSaleOrder	= 'True'		AND
			tcn.cust_id					= @cust_id

END



GO




CREATE PROCEDURE [dbo].[spCRM_Notes_InsertData]
(
	@comp_id			INT,
	@bra_id				INT,
	@user_id_Creator	INT,
	@user_id_lastUpdate	INT,
	@cust_id			INT,
	@contact_id			INT,
	@so_bra_id			INT,
	@so_soh_id			INT,
	@crmn_note1			NVARCHAR(4000),
	@crmn_note2			NVARCHAR(4000),
	@crmnt_id			INT,
	@crmn_PDF			IMAGE,
	@cme_id				INT,
	@cme_validUpToDate	DATETIME,
	@pro_id				INT,
	@return_value		INT	OUTPUT
)
AS SET NOCOUNT ON

	BEGIN

SET NOCOUNT ON

	IF @cust_id = -1
		BEGIN
			SET @cust_id = NULL
		END
	IF @contact_id = -1
		BEGIN
			SET @contact_id = NULL
		END

		IF @cme_id = -1
		BEGIN
			SET @cme_id = NULL
		END

		IF @pro_id = -1
			BEGIN
				SET @pro_id = NULL
			END

		INSERT INTO tbCRM_Notes
		(
			comp_id,
			-- crmn_id -- this column value is auto-generated,
			bra_id,
			user_id_Creator,
			user_id_lastUpdate,
			crmn_cd,
			cust_id,
			contact_id,
			so_bra_id,
			so_soh_id,
			crmn_note1,
			crmn_note2,
			crmnt_id,
			crmn_PDF,
			cme_id,
			cme_validUpToDate,
			pro_id
		)
		VALUES
		(
			@comp_id,
			@bra_id,
			@user_id_Creator,
			@user_id_lastUpdate,
			GETDATE(),
			@cust_id,
			@contact_id,
			@so_bra_id,
			@so_soh_id,
			@crmn_note1,
			@crmn_note2,
			@crmnt_id,
			@crmn_PDF,
			@cme_id,
			@cme_validUpToDate,
			@pro_id
		)

		SET @return_value = @@IDENTITY
	END
GO




CREATE PROCEDURE [dbo].[spCRM_Notes_UpdateData]
(
	@comp_id			INT,
	@bra_id				INT,
	@crmn_id			INT,
	@user_id_lastUpdate	INT,
	@cust_id			INT,
	@contact_id			INT,
	@so_bra_id			INT,
	@so_soh_id			INT,
	@crmn_note1			NVARCHAR(4000),
	@crmn_note2			NVARCHAR(4000),
	@crmnt_id			INT,
	@crmn_PDF			IMAGE,
	@cme_id				INT,
	@cme_validUpToDate	DATETIME,
	@pro_id				INT

)
AS SET NOCOUNT ON

	BEGIN


SET NOCOUNT ON

	IF @cme_id = -1
		BEGIN
			SET @cme_id = NULL
		END

	IF @cust_id = -1
		BEGIN
			SET @cust_id = NULL
		END
	IF @contact_id = -1
		BEGIN
			SET @contact_id = NULL
		END
	IF @pro_id	= -1
		BEGIN
			SET @pro_id = NULL
		END

		UPDATE tbCRM_Notes
		SET
			--bra_id				= @bra_id,
			user_id_lastUpdate	= @user_id_lastUpdate,
			cust_id				= @cust_id,
			contact_id			= @contact_id,
			so_bra_id			= @so_bra_id,
			so_soh_id			= @so_soh_id,
			crmn_note1			= @crmn_note1,
			crmn_note2			= @crmn_note2,
			crmnt_id			= @crmnt_id,
			crmn_PDF			= @crmn_PDF,
			cme_id				= @cme_id,
			cme_validUpToDate	= @cme_validUpToDate,
			pro_id				= @pro_id

		WHERE	comp_id			= @comp_id AND
				crmn_id			= @crmn_id

	END
GO




