CREATE PROCEDURE [dbo].[spCRM_Task_deleteData]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@lang_id			INT,

	@task_id			INT
)
AS
SET NOCOUNT ON


BEGIN


	-- -----------------------------------------------------------------------------------------------------------
	--ACA BORRAMOS EL HISTORICO EN CASO DE PODER HACERLO EN BASE AL USUARIO QUE REALIZA LA ACCIÓN!
	-- -----------------------------------------------------------------------------------------------------------
	--VARIABLE PARA SABER SI PUEDE O NO BORRAR EL HISTORIAL
	DECLARE
		@lbitCanDeleteHistory	BIT

	IF EXISTS(SELECT 1
			  FROM tbControlProfiles			tcp1
			  WHERE	tcp1.comp_id	= @comp_id	AND
					tcp1.bra_id		= @bra_id	AND
					tcp1.prof_id	= @prof_id	AND
					tcp1.ctrl_id	= 2876		AND
					tcp1.page_id	= 9000)

		SET @lbitCanDeleteHistory = 'True'

	ELSE

		SET @lbitCanDeleteHistory = 'False'

	--SI EL CONTROL ESTA HABILITADO PARA BORRAR, BORRA TODOS LOS DETALLES ASOCIADOS AL @TASK_ID
	IF @lbitCanDeleteHistory = 'True'

		DELETE FROM tbCRM_TaskHistory WHERE comp_id = @comp_id AND task_id = @task_id


	-- -----------------------------------------------------------------------------------------------------------



declare
	@user_origen		 int,
	@message			 varchar(400),
	@subject			 varchar(400),
	@body				 varchar(400),
	@mail				 varchar(2000),
	@user_origen_name	 varchar(400),
	@user_mail_origin	 varchar(400),
	@user_origen_destiny varchar(400),
	@user_mail_destiny	 varchar(400),
	@optionid			 int,
	@desc				 varchar(200)



declare
	@taskt_id	INT

select @taskt_id = tct.taskt_id
  from tbCRM_Task tct where tct.comp_id = @comp_id and tct.task_id = @task_id


	DELETE FROM tbCRM_Task

	WHERE	comp_id = @comp_id
	AND		task_id = @task_id





--Datos del Usuario de Origen
select
	@user_origen_name = (tu.user_lastname + ',' + tu.user_firstname),
	@user_mail_origin = tu.user_email
from tbUser tu where tu.[user_id] = @user_id

set @optionid = 3583


--Datos del Usuario de Destino
select
	@user_origen_destiny = (tu.user_lastname + ',' + tu.user_firstname),
	@user_mail_destiny	 = tu.user_email
from tbUser tu where tu.[user_id] = @user_id


--Armado de Subject y Body
select @subject = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 984

select @message = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 985

select @body = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 986

select @desc = tswn.word_desc
  from tbSysWordsNew tswn where tswn.lang_id = @lang_id and tswn.wordsi_id = @optionid

set @subject = @subject + @desc

set @mail = @user_origen_name  + ' ' + @message + ' ' + @desc + ' ' + @body + ' ' + convert(varchar,@task_id)

--STL
declare @description as nvarchar(500)

select
	@description = tut.utexts_desc
from tbsysUniqueTexts tut
where tut.lang_id = @lang_id
and tut.utexts_id = 300065

set @description = @description + ' ' + convert(varchar,@task_id)

insert into tbSecurityLog
(
	comp_id,
	bra_id,
	user_id,
	seclog_obs_1,
	seclog_obs_2,
	seclog_image,
	seclog_obs_3,
	seclog_obs_4,
	seclog_cd,
	aut_id,
	sysCode_id,
	menu_id,
	menu_ts,
	request_ip,
	request_name,
	aure_isok,
	aure_user_id,
	seclog_pageHTML,
	prof_id,
	aure_cd,
	aure_id,
	seclog_id1,
	seclog_id2,
	seclog_id3
)
VALUES
(
	@comp_id,
	@bra_id,
	@user_id,
	@description,
	NULL,
	NULL,
	NULL,
	NULL,
	getdate(),
	NULL,
	1102,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL,
	@prof_id,
	NULL,
	NULL,
	NULL,
	NULL,
	NULL
)



-- -------------------------------------------------------
-- Obtenemos los mails a enviar a los grupos de usuarios
-- -------------------------------------------------------

declare
	@email_recipients	nvarchar(4000),
	@title				nvarchar(1000),
	@text				nvarchar(1000)

select @title = tut.utexts_desc
  from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 300073

select @text = tut.utexts_desc
  from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 300065

set @text = @text + ' ' + convert(varchar,@task_id)

set @email_recipients = ''

select
	@email_recipients = @email_recipients + '; ' + tu.user_email

	from tbCRM_UserGroups						tcug		WITH (NOLOCK)

		inner join tbCRM_UserGroupsDetail		tcugd		WITH (NOLOCK)
		on	tcugd.comp_id	= tcug.comp_id
		AND tcugd.crmug_id	= tcug.crmug_id

		inner join tbUser						tu			WITH (NOLOCK)
		on tu.[user_id] = tcugd.[user_id]

	where	tcug.comp_id						= @comp_id
	--and		tcugd.user_id						= @user_id
	and		tcugd.crmug_id						in (select crmug_id
														from tbCRM_UserGroupsDetail tcugd2		WITH (NOLOCK)
														where	tcugd2.comp_id	 = @comp_id
														and		tcugd2.[user_id] = @user_id)
	and		tcugd.crmugd_disabled				= 'False'
	and     tcugd.crmugd_reciveEmailofChanges	= 'True'
	-- ACA CAMBIAR PARA TAREAS, LLAMADAS y REUNIONES
	and		tcugd.crmugd_4Task					= 'True'
	and		(/*@taskt_id = -1*/tcugd.taskt_id	 IS NULL  or  tcugd.taskt_id	= @taskt_id)


if @email_recipients <> ''
	begin
		SET @email_recipients = SUBSTRING(@email_recipients,2,LEN(@email_recipients) - 1)

		exec spSystem_sendEMail
			@compId = @comp_id,
			@precipients = @email_recipients,
			@pcopy_recipients = null,
			@psubject = @title,
			@pbody_format = 'TEXT',
			@pbody = @text ,
			@pfile_attachments = null,
			@pReplyTo = NULL,
			@pblind_copy_recipients='',
			@pUser_Id				= @user_id
	end




END
GO






CREATE PROCEDURE [dbo].[spCRM_Task_getCombo]
(
	@comp_id			INT,
	@task_id			INT
)
AS

BEGIN

	set nocount on

	select		task_id										[id],
				'(' + CONVERT(VARCHAR,task_id) + ') - ' +
				dbo.fnStrAllTrim( task.task_subject	)		[desc]

		from		dbo.tbCRM_Task task							WITH (NOLOCK)
		INNER JOIN tbCRM_TaskStatus tcts						WITH (NOLOCK)
			ON	tcts.tast_id = task.tast_id AND
				tcts.comp_id = task.comp_id
		where	task.comp_id = @comp_id		AND
				(
					tcts.tast_isFinalStatus = 'False'
						OR
					task.task_id = @task_id
				)
		Order By	task.task_subject


END
GO



