CREATE PROCEDURE [dbo].[spCRM_Task_getDataByFilters]
(
	@comp_id				INT,
	@bra_id					INT,
	@prof_id				INT,

	@cust_id				int,
	@datefrom				datetime,
	@dateto					datetime,
	@tast_id				INT,
	@cast_id				INT,
	@meetst_id				int,
	@callst_id				int,
	@user_id				INT,
	@option					INT,
	@text					nvarchar(500),
	@contact				INT,
	@contact_text			nvarchar(500),
	@guid					UNIQUEIDENTIFIER,
	@session_user_id		INT,
	@taskt_id				INT,
	@item_id				INT,
	@subcat_id				INT,
	@brand_id				INT,
	@is_serial				NVARCHAR(100),
	@task_id				INT,
	@supp_id				INT,
	@datereviewfrom			datetime,
	@datereviewto			datetime,
	@dateEndFrom			datetime,
	@dateEndTo				datetime,
	@pro_id					INT,

	@dateResolutionFrom		datetime,
	@dateResolutionTo		datetime,
	@user_id4Resolution		INT,
	@user_id4StateProcessed	INT,
	@task_priority			INT,
	@taskOrder				INT		-- 1: Ordenar por Prioridad  2: Ordenar por Mis Tickets, Luego Otros + Prioridad  3: Ordenar por Otros Tickets, Luego Mis Tickets + Prioridad

)
AS


BEGIN


	set DATEFORMAT 'ymd'
	SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------


		--------------------------------------------------------
		-------------parametros de prueba-----------------------
		--------------------------------------------------------
		/*


					DECLARE	@comp_id	INT,
					@bra_id				INT,
					@prof_id			INT,
					@cust_id			int,
					@datefrom			datetime,
					@dateto				datetime,
					@tast_id			INT,
					@cast_id			INT,
					@meetst_id			int,
					@callst_id			int,
					@user_id			INT,
					@option				INT,
					@text				nvarchar(500),
					@contact			int,
					@contact_text		nvarchar(500),
					@guid				UNIQUEIDENTIFIER,
					@session_user_id	int,
					@taskt_id			int,
					@item_id			INT,
					@subcat_id			INT,
					@brand_id			INT,
					@is_serial			NVARCHAR(100),
					@task_id			INT,
					@supp_id			INT,
					@guidRandom			UNIQUEIDENTIFIER,
					@datereviewfrom		datetime,
					@datereviewto		datetime,
					@dateEndFrom		datetime,
					@dateEndTo			datetime,
					@pro_id				INT	,
					@dateResolutionFrom		datetime,
					@dateResolutionTo		datetime,
					@user_id4Resolution		INT,
					@user_id4StateProcessed	INT,
					@task_priority			INT



		SELECT		@comp_id			= 1,
					@bra_id				= 1,
					@prof_id			= 1,

					@cust_id			= -1,
					@datefrom			= '2000-01-01',
					@dateto				= '2099-12-31',
					@tast_id			= -2,
					@cast_id			= -2,
					@meetst_id			= -2,
					@callst_id			= -2,
					@user_id			=  45,
					@option				= -1,
					@text				= '',
					@contact			= -1,
					@contact_text		= '',
					@guid				= '548A7A6E-7BDB-42A4-920C-AEBA91149526',
					@session_user_id	=45,
					@taskt_id			=-1,
					@item_id			=-1,
					@subcat_id			=-1,
					@brand_id			=-1,
					@is_serial			='',
					@task_id			= 0,
					@supp_id			= -1,
					@datereviewfrom		= '1900-01-01',
					@datereviewto		= '2999-01-29',
					@dateEndFrom		= '1900-01-01',
					@dateEndTo			= '2900-01-01',
					@pro_id				= -1,
					@dateResolutionFrom	= '1900-01-01',
					@dateResolutionTo	= '2999-01-29',
					@user_id4Resolution		 = -1,
					@user_id4StateProcessed	 = -1,
					@task_priority		= -1


	*/

		--------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Obtenemos el is_id correspondiente al Nº de Serie obtenido por parámetro
	-- --------------------------------------------------------------------------

		DECLARE	@lis_id	INT
		SET		@lis_id		= -1
		SET		@is_serial  = dbo.fnstrAllTrim(@is_serial)

		IF @is_serial <> ''
			BEGIN
				SET			@lis_id			= -2
				SELECT
							@lis_id			= tis.is_id
					FROM	tbItemSerials				tis				WITH (NOLOCK)
					WHERE	tis.comp_id		= @comp_id	AND
							tis.is_serial	= @is_serial
			END


	-- --------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Pone en una tabla temporal todos los usuarios de mi grupo y
	-- si no estoy en ningun grupo, todos los disponibles para crm
	-- --------------------------------------------------------------------------
	SET @datefrom		= dbo.fnGetEnd_or_BeginOfDate(@datefrom			,'false')
	SET @dateto			= dbo.fnGetEnd_or_BeginOfDate(@dateto			,'true')

	SET @datereviewfrom	= dbo.fnGetEnd_or_BeginOfDate(@datereviewfrom	,'false')
	SET @datereviewto	= dbo.fnGetEnd_or_BeginOfDate(@datereviewto		,'true')

	SET @dateEndFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateEndFrom		,'false')
	SET @dateEndTo		= dbo.fnGetEnd_or_BeginOfDate(@dateEndTo		,'true')

	SET @dateResolutionFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateResolutionFrom	,'false')
	SET @dateResolutionTo	= dbo.fnGetEnd_or_BeginOfDate(@dateResolutionTo		,'true')




	DECLARE @tmpUsersOfMyGroup TABLE([USER_ID] INT , taskt_id INT ,[user_id_assigned] INT,crmugd_blockUserCantSeeMe BIT,crmugd_userMustViewHisCRM BIT)

	INSERT INTO @tmpUsersOfMyGroup( [USER_ID], taskt_id,user_id_assigned,crmugd_blockUserCantSeeMe,crmugd_userMustViewHisCRM)
		SELECT DISTINCT tcugd.[USER_ID],
						tcugd.taskt_id,
						mg.[user_id],
						ISNULL(mg.crmugd_blockUserCantSeeMe,'False'),
						ISNULL(tcugd.crmugd_userMustViewHisCRM,'False')
			FROM tbCRM_UserGroupsDetail			tcugd			WITH (NOLOCK)
			INNER JOIN tbCRM_UserGroups			tcug			WITH (NOLOCK)
				ON tcug.comp_id				= tcugd.comp_id						AND
				   tcug.crmug_id			= tcugd.crmug_id
			INNER JOIN tbUser					tuMyUser		WITH (NOLOCK)
				ON tuMyUser.[user_id]		= @session_user_id
			INNER JOIN tbUser					tu				WITH (NOLOCK)
				ON	tu.[user_id]			= tcugd.[user_id]					AND
					tu.user_available4CRM	= 'True'
			LEFT JOIN tbCRM_UserGroupsDetail	mg				WITH (NOLOCK)
				ON
					mg.comp_id								= tcugd.comp_id			AND
					mg.crmug_id								= tcugd.crmug_id		AND
					--mg.crmugd_IsAvailable2ViewOtherUsers	= 'True'				AND
					(
						mg.crmugd_blockUserCantSeeMe			= 'False'
							OR
						tcugd.crmugd_userMustViewHisCRM			= 'True'
					)
																					AND
					mg.crmugd_disabled						= 'False'
			LEFT JOIN tbCRM_UserGroups			tcug2			WITH (NOLOCK)
				ON tcug2.comp_id			= mg.comp_id						AND
				   tcug2.crmug_id			= mg.crmug_id
		WHERE	tcugd.comp_id							= @comp_id				AND
				tcugd.[user_id]							= @session_user_id		AND		-- Todos los grupos a los q pertenezca mi usuario de sesion
			    tuMyUser.user_available4CRM_SeeAllTasks	= 'True'				AND
				(
					tcugd.crmugd_IsAvailable2ViewOtherUsers	= 'True'
							OR
					tcugd.crmugd_userMustViewHisCRM			= 'True'
				)																AND
			    tcug.crmug_disabled						= 'False'				AND
			    ISNULL(tcug2.crmug_disabled,'False')	= 'False'				AND
			    mg.comp_id IS NOT NULL
			  --  CASE
					--WHEN tcugd.[user_id] <> mg.[user_id] AND  tcugd.crmugd_blockUserCantSeeMe = 'False'	THEN 1
					--WHEN tcugd.[user_id] =  mg.[user_id]												THEN 1
					----WHEN mg.comp_id IS NULL																THEN 1
					--ELSE																					 0
			  --  END = 1


	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tu.[USER_ID]
					FROM	tbUser tu							WITH (NOLOCK)
					INNER JOIN tbUser tuMyUser					WITH (NOLOCK)
						ON tuMyUser.[user_id]						= @session_user_id
					WHERE	tu.user_available4CRM					= 'True' AND
							tuMyUser.user_available4CRM_SeeAllTasks	= 'True'
		END


	-- borrar todos los que tengan un tipo X y un null y que los dos usuarios sean los mismos
	DELETE   tmp1
		FROM @tmpUsersOfMyGroup			tmp1
		INNER JOIN @tmpUsersOfMyGroup	tmp2
			ON	tmp2.[USER_ID]			= tmp1.[USER_ID]			AND
				tmp2.user_id_assigned	= tmp1.user_id_assigned		AND
				tmp2.taskt_id IS NULL								AND
				tmp1.taskt_id IS NOT NULL



	IF NOT EXISTS(	SELECT TOP 1 1
						FROM @tmpUsersOfMyGroup
						WHERE [USER_ID] = @session_user_id
				 )
		BEGIN
			INSERT INTO @tmpUsersOfMyGroup ([USER_ID])
				VALUES(@session_user_id)
		END


	-- Actualizo en los Tipos de Tareas


	-- --------------------------------------------------------------------------



		--guardar el campo de usuario "ver todas las tareas" para mostrar todas las tareas o
		--filtrar solo las del usuario
		declare @luser_available4CRM_SeeAllTasks	bit

		SELECT	@luser_available4CRM_SeeAllTasks = isnull(tu.user_available4CRM_SeeAllTasks, 'false')
			FROM	tbUser tu	WITH (NOLOCK)
			WHERE	tu.[user_id] = @session_user_id
		--SELECT	@luser_available4CRM_SeeAllTasks


	-- Para que no DUPLIQUE abajo y x Velocidad
	DECLARE		@tmpTask TABLE(task_id INT PRIMARY KEY)
	INSERT INTO @tmpTask(task_id)

		SELECT distinct tct.task_id
			FROM 	dbo.tbCRM_Task								tct					WITH (NOLOCK)
			LEFT JOIN @tmpUsersOfMyGroup tmpu
				ON
					(
					    (
					    	tmpu.user_id_assigned			= tct.[user_id]
					    		AND
					    	tmpu.crmugd_blockUserCantSeeMe	= 'False'
					    )
					    	OR
					    (
					    	tmpu.crmugd_userMustViewHisCRM = 'True'  /*tmpu.crmugd_blockUserCantSeeMe NO IMPORTARÍA...*/
					    		AND
					    	tmpu.[USER_ID] = tct.user_id_Creator
					    )
					)
					    															AND
					(
						tmpu.taskt_id IS NULL
						OR
						tmpu.taskt_id	= tct.taskt_id
					)


























		select	CASE
					WHEN tct.user_id_4SupportCreator IS NOT NULL THEN '*'
					ELSE ' '
				END											[ ],	-- 1	>5
				ISNULL(typeColor.color_value,'')			[ ],	-- 2	>6
				ISNULL(statusColor.color_value,'')			[ ],	-- 3	>7
				CASE
					WHEN	ISNULL(tcts.tast_isFinalStatus,'False') = 'False' THEN  '-'
					ELSE															'*'
				END											[ ],	-- 4	>8
				tct.task_advertise_desc						[ ],	-- 5	>9



				-- NO PONER NADA A PARTIR DE ACA.
				convert(bit,case
								when tct2.comp_id is null then	0
								else							1
							end)													[filter], --10
				tct.task_id															[ID2],    --11
				tct.task_subject,   --12
				tct.task_date4Begin, --13
				TCT.task_nextReviewdate												[nextReviewdate],  --14
				tcts.tast_desc,  --15
				isnull(tc.cust_name,'')												[cust_id],	--16
				isnull(tu.user_lastname,'') + ', ' + isnull(tu.user_firstname,'')	[user_name],	--17
				tctt.taskt_desc														[task_type],	--18		**wsefnwkenwkejnwe  OJO CON CAMBIAR ESTE ORDEN, LES CORTO LAS MANOS !!!!!
				isnull(tc2.contact_name,'')											[contact_id],  --19
				tct.task_advertiseDate,																-- 20
				tct.task_date4End,																	-- 21
				isnull(tcc.case_desc,'')											[case_id],
				ISNULL(tccs.cast_desc,'')											[cast_desc],
				tct.task_priority,

				tct.soh_Bra_id,
				tct.soh_soh_id,

				tct.[user_id],
				tct.task_price,
				tsc.curr_desc,
			--	tct.task_emailAdditional,

				ISNULL(tct.task_resolution, '')											[task_resolution],
				tct.task_date4Resolution												[task_date4Resolution],
				CASE
					WHEN tures.user_lastname IS NOT NULL THEN
						isnull(tures.user_lastname,'') + ', ' + isnull(tures.user_firstname,'')
					ELSE
						' '
				END																		[user4Resolution],
				tct.task_advertise_desc													[advertise_desc],
				tct.task_advertiseCount													[advertiseCount],
				tct.task_advertiseLastDate												[advertiseLastDate],
				tct.task_id																[ID]



		FROM 	dbo.tbCRM_Task								tct					WITH (NOLOCK)

		LEFT JOIN @tmpTask AS tt
			ON tt.task_id = tct.task_id
				--LEFT JOIN @tmpUsersOfMyGroup tmpu
				--	ON
				--	    (
				--	    	(
				--	    		tmpu.user_id_assigned			= tct.[user_id]
				--	    			AND
				--	    		tmpu.crmugd_blockUserCantSeeMe	= 'False'
				--	    	)
				--	    		OR
				--	    	(
				--	    		tmpu.crmugd_userMustViewHisCRM = 'True'  /*tmpu.crmugd_blockUserCantSeeMe NO IMPORTARÍA...*/
				--	    			AND
				--	    		tmpu.[USER_ID] = tct.user_id_Creator
				--	    	)
				--	    )
				--	    																AND
				--		(
				--			tmpu.taskt_id IS NULL
				--			OR
				--			tmpu.taskt_id	= tct.taskt_id
				--		)

				LEFT JOIN tbCRM_Task_Block4Filter tctbf							WITH (NOLOCK)
					ON	tctbf.comp_id			= tct.comp_id		AND
						tctbf.bra_id			= tct.bra_id		AND
						tctbf.taskt_id			= tct.taskt_id		AND
						tctbf.tast_id			= tct.tast_id		AND
						tctbf.user_id_task		= tct.[user_id]		AND
						tctbf.user_id_actual	= @session_user_id	AND
						tct.[user_id]			<>@session_user_id


				left join tbCRM_tmp							tct2				WITH (NOLOCK)
					on	tct2.comp_id			= tct.comp_id
					and tct2.crmt_function		= 2 -- Aquí es el unico caso en que se suma UNO, no se que MIERDA hizo el HDP que armo esta parte!!!  (0 Case;1 Task;2 Call;3 Meet)
					and tct2.crmt_function_id	= tct.task_id
					and tct2.crmt_guid			= @guid

				INNER JOIN	tbCRM_TaskStatus				tcts				WITH (NOLOCK)
					ON  tcts.comp_id	= tct.comp_id
					AND tcts.tast_id	= tct.tast_id


				LEFT JOIN   tbsysfontdef_Colors				statusColor			WITH (NOLOCK)
					ON	statusColor.color_id = tcts.tast_color

				--LEFT JOIN tbsysOptionsValues statusColor
				--	ON	statusColor.lang_id			= 1 AND
				--		statusColor.optval_id		= tcts.tast_color	AND
				--		statusColor.optval_class	= 21

				INNER JOIN	tbCRM_TypesByProfile			tctbp				WITH (NOLOCK)
					ON  tctbp.comp_id	= tct.comp_id
					AND tctbp.bra_id	= tct.bra_id
					AND tctbp.prof_id	= @prof_id
					AND tctbp.crm_type	= 1		--task


				LEFT JOIN tbUsers4BranchFilter tubf								WITH (NOLOCK)
					ON	tubf.comp_id	= tct.comp_id		AND
						tubf.bra_id		= tct.bra_id		AND
						tubf.[user_id]	= @session_user_id


				LEFT JOIN	tbCRM_Case						tcc					WITH (NOLOCK)
					ON  tcc.comp_id		= tct.comp_id
					AND tcc.case_id		= tct.case_id

				LEFT JOIN	tbCRM_CaseStatus				tccs				WITH (NOLOCK)
					ON	tccs.comp_id	= tcc.comp_id
					AND tccs.cast_id	= tcc.cast_id

				INNER JOIN	tbUser							tu					WITH (NOLOCK)		-- 09-2021, MOS, era LEFT
					ON  tu.[user_id]	= tct.[user_id]

				LEFT JOIN	tbCustomer						tc					WITH (NOLOCK)
					ON  tc.comp_id		= tct.comp_id
					AND tc.cust_id		= tct.cust_id

				LEFT JOIN	tbContact						tc2					WITH (NOLOCK)
					on  tc2.comp_id		= tct.comp_id
					and tc2.contact_id	= tct.contact_id

				inner join tbBranch							tb					WITH (NOLOCK)
					on  tb.comp_id = tct.comp_id
					and tb.bra_id  = tct.bra_id

				inner join tbsysCurrency					tsc					WITH (NOLOCK)
					on tsc.curr_id = tb.curr_id

				inner join tbCRM_TaskType					tctt				WITH (NOLOCK)
				on tctt.comp_id = tct.comp_id
				and tctt.taskt_id = tct.taskt_id


				LEFT JOIN   tbsysfontdef_Colors				typeColor			WITH (NOLOCK)
				ON	typeColor.color_id = tctt.taskt_color

				LEFT JOIN	tbUser							tures				WITH (NOLOCK)
				ON  tures.[user_id]	= tct.user_id4Resolution

				--LEFT JOIN tbsysOptionsValues typeColor
				--	ON	typeColor.lang_id		= 1					AND
				--		typeColor.optval_id		= tctt.taskt_color	AND
				--		typeColor.optval_class	= 21


		WHERE	tct.comp_id			= @comp_id

		AND		(tct.[user_id]			= @session_user_id OR 	tt.task_id IS NOT NULL)
		--AND		(tct.[user_id]			= @session_user_id OR 	tmpu.user_id_assigned IS NOT NULL)

		AND		(@task_id			= 0			OR  tct.task_id			= @task_id OR tct.task_id_related = @task_id OR tct.task_id_related2 = @task_id)
		AND		(tct.bra_id			= @bra_id	OR  tct.[user_id]		= @session_user_id OR tubf.comp_id IS NOT NULL)
		AND		(@taskt_id			= -1		OR  tct.taskt_id		= @taskt_id)
		AND		(@task_priority		= -1		OR  tct.task_priority	= @task_priority) -- 18/06/19 GA filtro de prioridad

		AND		(
					(@tast_id		= -1)														OR
     				(@tast_id		= -2 and  tcts.tast_isFinalStatus		= 'false')													OR
     				(@tast_id		= -3 and  tcts.tast_isFinalStatus		= 'True')													OR
     				(@tast_id		= -4 and  tcts.tast_isInitialStatus		= 'True')													OR
     				(@tast_id		= -5 and (tcts.tast_isInitialStatus		= 'False' AND tcts.tast_isFinalStatus = 'False'))			OR
					(@tast_id		= tcts.tast_id)
				)

		AND		(
					 tct.case_id IS NULL																								OR
					(@cast_id		= -1)																								or
     				(@cast_id		= -2 and  tccs.cast_isFinalStatus		= 'false')													OR
     				(@cast_id		= -3 and  tccs.cast_isFinalStatus		= 'True')													OR
     				(@cast_id		= -4 and  tccs.cast_isInitialStatus		= 'True')													OR
     				(@cast_id		= -5 and (tccs.cast_isInitialStatus		= 'False' AND tccs.cast_isFinalStatus = 'False'))			OR
					(tccs.cast_id	= @cast_id)
				)

		AND		(@cust_id			=	-1		or		 tc.cust_id		= @cust_id)
		AND		(@contact			=   -1		OR		 tct.contact_id	= @contact)
--		and		(
--					(@contact	 = -1 ) or
--					(@contact	 = 0 and tc2.contact_name like @contact_text + '%')			or
--					(@contact	 = 1 and tc2.contact_name like '%' + @contact_text + '%')	or
--					(@contact	 = 2 and tc2.contact_name = @contact_text )					or
--					(@contact	 = 3 and tc2.contact_name <> @contact_text )				or
--					(@contact	 = 4 and tc2.contact_name not like '%' + @contact_text + '%')
--				)




		AND
		CASE
			WHEN @user_id4StateProcessed	= -1 THEN	1
			WHEN EXISTS(
							SELECT TOP 1 1
								FROM tbCRM_TaskHistory tcth		WITH (NOLOCK)
								WHERE	tcth.comp_id = tct.comp_id AND
										tcth.task_id = tct.task_id AND
										tcth.[user_id] = @user_id4StateProcessed
					   ) THEN							1
			ELSE										0
		END  = 1

		AND		ISNULL(tct.task_date4Resolution,@dateResolutionFrom)	BETWEEN @dateResolutionFrom AND @dateResolutionTo
		AND		tct.task_date4Begin			BETWEEN @datefrom			and @dateto
		AND		tct.task_date4End			BETWEEN @dateEndFrom		and @dateEndTo
		and		((
					(@option	 = -1 ) or
					(@option	 = 0 and tct.task_subject like @text + '%')			or
					(@option	 = 1 and tct.task_subject like '%' + @text + '%')	or
					(@option	 = 2 and tct.task_subject = @text )					or
					(@option	 = 3 and tct.task_subject <> @text )				or
					(@option	 = 4 and tct.task_subject not like '%' + @text + '%')
				)
				or
				(
					(@option	 = -1 ) or
					(@option	 = 0 and tct.task_desc like @text + '%')		or
					(@option	 = 1 and tct.task_desc like '%' + @text + '%')	or
					(@option	 = 2 and convert(NVARCHAR(4000),tct.task_desc) = @text )				or
					(@option	 = 3 and convert(NVARCHAR(4000),tct.task_desc) <> @text )				or
					(@option	 = 4 and tct.task_desc not like '%' + @text + '%')
				))

		AND		(
						(@user_id		= -1		AND tctbf.comp_id IS NULL)
					OR
						(tct.[user_id]	= @user_id	AND tctbf.comp_id IS NULL)
				)

		AND		(@user_id4Resolution = -1 OR  tct.user_id4Resolution = @user_id4Resolution)

		-- ---------------------------------------------------------------------------
		-- Esto pone todo LENTO TODO !!!
		-- Arreglarlo MOS en cuanto puedas  05-2018
		-- Se puede arreglar con un Lesft join preguntando x null o no ya que son los marcadores de
		-- relaciones entre tareas y casos
		and		(
					( NOT EXISTS(			select top 1 tct2.comp_id
												from tbCRM_tmp tct2				WITH (NOLOCK)
												where	tct2.comp_id		= @comp_id	AND
														tct2.crmt_function	= 1			AND
														tct2.crmt_guid		= @guid))		or

					(	EXISTS  (			SELECT TOP 1 tct2.crmt_function_id
												from tbCRM_tmp tct2				WITH (NOLOCK)
												where	tct2.comp_id			= @comp_id	AND
														tct2.crmt_function		= 1			AND
														tct2.crmt_guid			= @guid		AND
														tct2.crmt_function_id	= tct.case_id
							    )
					)
				)
		-- ---------------------------------------------------------------------------

		AND		(@item_id		= -1 OR  tct.item_id	= @item_id)
		AND		(@subcat_id		= -1 OR  tct.subcat_id	= @subcat_id)
		AND		(@brand_id		= -1 OR  tct.brand_id	= @brand_id )

		AND		(@lis_id		= -1  OR tct.is_id		= @lis_id)
		--==STL
		AND		(@supp_id		= -1  OR @supp_id		= tct.supp_id)

		AND (isnull(tct.task_nextReviewdate,'')	BETWEEN @datereviewfrom and @datereviewto )--ga

		AND	(@pro_id			= -1		OR		tct.pro_id		= @pro_id)



	order by
			CASE	-- 1: Ordenar por Prioridad  2: Ordenar por Mis Tickets, Luego Otros + Prioridad  3: Ordenar por Otros Tickets, Luego Mis Tickets + Prioridad
				WHEN @taskOrder = 1											THEN  1
				WHEN @taskOrder = 2 AND  tct.[user_id] = @session_user_id	THEN  2
				WHEN @taskOrder = 3 AND  tct.[user_id] <> @session_user_id	THEN  3
				ELSE															  5
			END,
			CASE	-- Indica si el estado dice que va al FONDO o no
				WHEN tcts.tast_lastOrderInPriority = 'False' THEN 1
				WHEN tcts.tast_lastOrderInPriority = 'True'  THEN 2
				ELSE										      1
			END,
			CASE	-- Prioridad a los de fecha de revision o advertencia, para que queden arriba
				WHEN tct.task_priority  < 0															THEN tct.task_priority
				WHEN CONVERT(date, tct.task_advertiseDate) = convert(date,tb.bra_processingDate)	THEN 0
				WHEN CONVERT(date,tct.task_nextReviewdate) = convert(date,tb.bra_processingDate)	THEN 0
				WHEN ABS(DATEDIFF(DAY,tb.bra_processingDate,tct.task_advertiseDate))  <= 3			THEN 10
				WHEN ABS(DATEDIFF(DAY,tb.bra_processingDate,tct.task_nextReviewdate)) <= 3			THEN 20
				WHEN DATEDIFF(DAY,tb.bra_processingDate,tct.task_date4End)		 BETWEEN -15 AND 2	THEN 30  -- Los que esten por vencerse en 2 dias o ya esten vencidos
				ELSE																				     tct.task_priority + 1000
				--ELSE 10
			END,
			--tct.task_priority		ASC,
			--CASE	-- orden dentro de las fechas de revision o advertencia   11-08-2019
			--	WHEN CONVERT(date, tct.task_advertiseDate) = convert(date,tb.bra_processingDate)	THEN tct.task_advertiseDate
			--	WHEN CONVERT(date,tct.task_nextReviewdate) = convert(date,tb.bra_processingDate)	THEN tct.task_nextReviewdate
			--	WHEN ABS(DATEDIFF(DAY,tb.bra_processingDate,tct.task_advertiseDate))  <= 5			THEN tct.task_advertiseDate
			--	WHEN ABS(DATEDIFF(DAY,tb.bra_processingDate,tct.task_nextReviewdate)) <= 10			THEN task_nextReviewdate
			--	ELSE tct.task_date4Begin
			--END						DESC,
			--	tct.task_priority		ASC,	11-08-2019
			tct.task_date4Begin		DESC,
			tct.task_id DESC

			--tct.task_date4Begin DESC




END
GO






