CREATE PROCEDURE [dbo].[spCRM_Task_getDataById]
(
	@comp_id			INT,
	@task_id			INT
)
AS
SET NOCOUNT ON

BEGIN

	--------------------------------------------------------
	-------------parametros de prueba-----------------------
	--------------------------------------------------------
	/*
	declare		@comp_id			INT,
				@task_id			INT

	select		@comp_id				= 1,
				@task_id			= 1290

*/
	--------------------------------------------------------
	--------------------------------------------------------
	--------------------------------------------------------


	SELECT	tct.bra_id,
			isnull(tct.task_subject,'')						[task_subject],
			tct.task_date4Begin,
			tct.task_date4End,
			tct.task_priority,
			isnull(tct.user_id_Creator,-1)								[user_id_Creator],
			tct.[user_id],
			isnull(tu.user_lastname,'') + ', ' + isnull(tu.user_firstname,'')
															[user_name],
			tct.task_desc,
			isnull(tct.case_id,-1)							[case_id],
			tct.soh_Bra_id,
			tct.soh_soh_id,
			isnull(tct.cust_id,-1)							[cust_id],
			isnull(tct.contact_id,-1)						[contact_id],
			tct.tast_id,
			tc.curr_desc,
			tct.task_price,
			tct.curr_id,
			tct.task_emailAdditional,
			tctt.taskt_id,
			ISNULL(tct.task_resolution, '')					[task_resolution],
			ISNULL(tct.cat_id,-1)							[cat_id],
			ISNULL(tct.subcat_id,-1)						[subcat_id],
			ISNULL(tct.brand_id,-1)							[brand_id],
			ISNULL(tct.item_id,-1)							[item_id],
			ISNULL(tct.is_id,-1)							[is_id],
			ISNULL(tis.is_serial,'')						[is_serial],
			ISNULL(tct.task_link1,'')						[task_link1],
			ISNULL(tct.task_link2,'')						[task_link2],
			ISNULL(tct.Task_price2,0)						[Task_price2],
			ISNULL(tct.Task_price3,0)						[Task_price3],
			ISNULL(tct.Task_qty1,1)							[Task_qty1],
			ISNULL(tct.Task_qty2,0)							[Task_qty2],
			tct.task_id,
			ISNULL(ti.item_code,'')							[item_code],
			tct.supp_id,
			tct.task_nextReviewdate,
			tct.pro_id,
			tct.crmm_id,
			tct.task_image,
			ISNULL(tct.task_resolutionCustomerCompliance_Calification,-1)		[task_resolutionCustomerCompliance_Calification],
			ISNULL(tct.task_resolutionCustomerCompliance_Note,'')				[task_resolutionCustomerCompliance_Note],
			ISNULL(tct.user_id_Creator,-1)										[user_id_Creator],
			ISNULL(tct.user_id_4SupportCreator,-1)								[user_id_4SupportCreator],
			isnull(tov.optval_desc,'')											[Calificacion],
			ISNULL(tct.task_customerCompliance_note,'')							[task_customerCompliance_note],
			tct.camp_id,
			tct.task_image,
			tct.tasch_id,
			ISNULL(tct.task_qtyHour,0)											[task_qtyHour],
			ISNULL(tct.task_qtyMinutes,0)										[task_qtyMinutes],
			ISNULL(tct.task_qtyEstimatedHours,0)								[task_qtyEstimatedHours],
			ISNULL(tct.task_qtyEstimatedMinutes,0)								[task_qtyEstimatedMinutes],
			ISNULL(tct.user_id_lastUpdate,-1)									[user_id_lastUpdate],
			ISNULL(tct.task_IFAvailableInVersion,0)								[task_IFAvailableInVersion],
			tct.task_id_related													[task_id_related],
			tct.task_id_related2												[task_id_related2],
			tct.task_date4Resolution											[task_date4Resolution],
			ISNULL(tct.user_id4Resolution,-1)									[user_id4Resolution],
			tct.task_advertiseLastDate											[task_advertiseDate],
			ISNULL(tct.taskta_id_1,-1)											[taskta_id_1],
			ISNULL(tct.taskta_id_2,-1)											[taskta_id_2],
			ISNULL(tct.taskta_id_3,-1)											[taskta_id_3],
			ISNULL(tct.taskta_id_4,-1)											[taskta_id_4],
			ISNULL(tct.taskta_id_5,-1)											[taskta_id_5],
			ISNULL(tct.taskta_id_6,-1)											[taskta_id_6],
			ISNULL(tct.taskta_id_7,-1)											[taskta_id_7],
			ISNULL(tct.taskta_id_8,-1)											[taskta_id_8],
			ISNULL(tct.taskta_id_9,-1)											[taskta_id_9] ,
			ISNULL(tct.taskta_text_1,'')										[taskta_text_1],
			ISNULL(tct.taskta_text_2,'')										[taskta_text_2],
			ISNULL(tct.taskta_text_3,'')										[taskta_text_3],
			ISNULL(tct.taskta_text_4,'')										[taskta_text_4],
			ISNULL(tct.taskta_text_5,'')										[taskta_text_5],
			ISNULL(tct.taskta_text_6,'')										[taskta_text_6],
			ISNULL(tct.taskta_text_7,'')										[taskta_text_7],
			ISNULL(tct.taskta_text_8,'')										[taskta_text_8],
			ISNULL(tct.taskta_text_9,'')										[taskta_text_9],
			ISNULL(tct.task_advertise_desc,'')									[task_advertise_desc],
			tct.task_lastUpdate,
			tct.user_id4lastUpdate,
			ISNULL(tct.wact_id,-1)												[wact_id],
			ISNULL(tct.taskatr1_id,-1)											[taskatr1_id],
			ISNULL(tct.taskatr2_id,-1)											[taskatr2_id],
			ISNULL(tct.taskatr3_id,-1) 											[taskatr3_id],
			ISNULL(tct.taskatr4_id,-1)											[taskatr4_id],
			ISNULL(tct.taskatr5_id,-1) 											[taskatr5_id],
			ISNULL(tct.taskatr6_id,-1)											[taskatr6_id],
			ISNULL(tct.task_qtyBudgetHours,0)									[task_qtyBudgetHours]

	FROM 	dbo.tbCRM_Task		tct																WITH(NOLOCK)

			INNER JOIN tbUser	tu																WITH(NOLOCK)
			ON tu.[user_id]		= tct.[user_id]

			--LEFT JOIN tbUser	tulastupdate													WITH(NOLOCK)
			--ON tulastupdate.[user_id]		= tct.user_id_lastUpdate

			--LEFT JOIN tbuser	tucreator
			--ON  tucreator.[user_id]		= tct.[user_id]

			inner join tbBranch tb																WITH(NOLOCK)
			on tb.comp_id = tct.comp_id
			and tb.bra_id = tct.bra_id

			inner join tbsysCurrency tc															WITH(NOLOCK)
			on tc.curr_id = tb.curr_id

			left join tbCRM_TaskType					tctt									WITH(NOLOCK)
			on tctt.comp_id = tct.comp_id
			and tctt.taskt_id = tct.taskt_id

			LEFT JOIN tbItemSerials						tis										WITH(NOLOCK)
			ON	tis.comp_id = tct.comp_id AND
				tis.is_id	= tct.is_id

			LEFT JOIN tbitem ti																	WITH(NOLOCK)
				ON	ti.comp_id = tct.comp_id AND
					ti.item_id = tct.item_id

			LEFT JOIN tbsysOptionsValues							tov							WITH(NOLOCK)
				ON	tov.lang_id			= 2							AND
					tov.optval_class	= 696						AND
					tov.optval_id		= tct.task_resolutionCustomerCompliance_Calification


	WHERE	tct.comp_id			= @comp_id
	AND		tct.task_id			= @task_id

END



GO








CREATE PROCEDURE [dbo].[spCRM_Task_getDataByText]
(
	@text	VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id  AS INT
)
AS



BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*

		DECLARE
			@text		VARCHAR(300),
			@count		INT,
			@lang_id	INT,
			@comp_id AS INT,
			@bra_id  AS INT

		SELECT
			@text		='A',
			@count		= 2,
			@lang_id	= 2,
			@comp_id	= 1,
			@bra_id		= 1
	*/
	-- ----------------------------------------------------------------





	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')



	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)
	DECLARE @text6	varchar(300)
	DECLARE @text7	varchar(300)
	DECLARE @text8	varchar(300)
	DECLARE @text9	varchar(300)
	DECLARE @text10	varchar(300)

	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0 else
			IF @text2 IS NULL SET @text2 = @text0 else
			IF @text3 IS NULL SET @text3 = @text0 else
			IF @text4 IS NULL SET @text4 = @text0 else
			IF @text5 IS NULL SET @text5 = @text0 else
			IF @text6 IS NULL SET @text6 = @text0 else
			IF @text7 IS NULL SET @text7 = @text0 else
			IF @text8 IS NULL SET @text8 = @text0 else
			IF @text9 IS NULL SET @text9 = @text0 else
			IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------





	SELECT		TOP (@count)

				Upper(dbo.PadRightString( IsNull(tc.task_subject,''),'.',50)) + ' | ' + isnull(convert(VARCHAR(10),tc.task_id),'')	[task_subject],
				tc.task_id
		FROM tbCRM_Task tc
			WHERE		tc.comp_id = @comp_id
					AND (tc.bra_id IS NULL OR tc.bra_id = @bra_id)
		AND
			(

						CASE
							WHEN @selection_method = 0 AND tc.task_subject LIKE @text + '%'	 THEN	'True'
							WHEN @selection_method = 1 AND tc.task_subject LIKE '%' + @text1 + '%'	 THEN	'True'
							WHEN @selection_method = 2 AND tc.task_subject LIKE '%' + @text1 + '%' AND tc.task_subject LIKE '%' + @text2 + '%'		 THEN	'True'
							WHEN @selection_method = 3 AND tc.task_subject LIKE '%' + @text1 + '%' AND tc.task_subject LIKE '%' + @text2 + '%' AND tc.task_subject LIKE '%' + @text3 + '%'	 THEN	'True'
							WHEN @selection_method = 4 AND tc.task_subject LIKE '%' + @text1 + '%' AND tc.task_subject LIKE '%' + @text2 + '%' AND tc.task_subject LIKE '%' + @text3 + '%' AND tc.task_subject LIKE '%' + @text4 + '%'		 THEN	'True'
							WHEN @selection_method = 5 AND tc.task_subject LIKE '%' + @text1 + '%' AND tc.task_subject LIKE '%' + @text2 + '%' AND tc.task_subject LIKE '%' + @text3 + '%' AND tc.task_subject LIKE '%' + @text4 + '%' AND tc.task_subject LIKE '%' + @text5 + '%'		 THEN	'True'
							WHEN @selection_method = 6 AND tc.task_subject LIKE '%' + @text1 + '%' AND tc.task_subject LIKE '%' + @text2 + '%' AND tc.task_subject LIKE '%' + @text3 + '%' AND tc.task_subject LIKE '%' + @text4 + '%' AND tc.task_subject LIKE '%' + @text5 + '%' AND tc.task_subject LIKE '%' + @text6 + '%'	 THEN	'True'
							WHEN @selection_method = 7 AND tc.task_subject LIKE '%' + @text1 + '%' AND tc.task_subject LIKE '%' + @text2 + '%' AND tc.task_subject LIKE '%' + @text3 + '%' AND tc.task_subject LIKE '%' + @text4 + '%' AND tc.task_subject LIKE '%' + @text5 + '%' AND tc.task_subject LIKE '%' + @text6 + '%' AND tc.task_subject LIKE '%' + @text7 + '%'	 THEN	'True'
							WHEN @selection_method = 8 AND tc.task_subject LIKE '%' + @text1 + '%' AND tc.task_subject LIKE '%' + @text2 + '%' AND tc.task_subject LIKE '%' + @text3 + '%' AND tc.task_subject LIKE '%' + @text4 + '%' AND tc.task_subject LIKE '%' + @text5 + '%' AND tc.task_subject LIKE '%' + @text6 + '%' AND tc.task_subject LIKE '%' + @text7 + '%' AND tc.task_subject LIKE '%' + @text8 + '%'		 THEN	'True'
							WHEN @selection_method = 9 AND tc.task_subject LIKE '%' + @text1 + '%' AND tc.task_subject LIKE '%' + @text2 + '%' AND tc.task_subject LIKE '%' + @text3 + '%' AND tc.task_subject LIKE '%' + @text4 + '%' AND tc.task_subject LIKE '%' + @text5 + '%' AND tc.task_subject LIKE '%' + @text6 + '%' AND tc.task_subject LIKE '%' + @text7 + '%' AND tc.task_subject LIKE '%' + @text8 + '%' AND tc.task_subject LIKE '%' + @text9 + '%'		 THEN	'True'
							WHEN @selection_method =10 AND tc.task_subject LIKE '%' + @text1 + '%' AND tc.task_subject LIKE '%' + @text2 + '%' AND tc.task_subject LIKE '%' + @text3 + '%' AND tc.task_subject LIKE '%' + @text4 + '%' AND tc.task_subject LIKE '%' + @text5 + '%' AND tc.task_subject LIKE '%' + @text6 + '%' AND tc.task_subject LIKE '%' + @text7 + '%' AND tc.task_subject LIKE '%' + @text8 + '%' AND tc.task_subject LIKE '%' + @text9 + '%' AND tc.task_subject LIKE '%' + @text10 + '%'		 THEN 'True'
							ELSE	'False'
						END	= 'True'

			)



			ORDER BY	tc.task_subject

END
GO






CREATE PROCEDURE [dbo].[spCRM_Task_GetHistoryData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@task_id	INT
)
as

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on


	-- -----------------------------------------------
	-- Testing
	-- -----------------------------------------------
	/*
		declare
			@comp_id	INT,
			@task_id	INT
		select
			@comp_id	= 1,
			@task_id	= 191
	*/
	-- -----------------------------------------------

	select		tcth.task_subject											[task_subject],
				tcth.task_desc												[task_desc],
				tcc.case_subject											[case_subject],
				tcc.case_desc												[case_desc],
				tcts.tast_desc												[tast_desc],
				tcc.case_resolution											[case_resolution],
				tcth.task_date4Begin										[task_date4Begin],
				tcth.task_date4End											[task_date4End],
				tcth.taskh_cd												[LastUpdate],--Fecha de Última actualización
				tctt.taskt_desc												[task_type],
				tu.user_lastname + ', ' + tu.user_firstname					[user_name],
				tu2.user_lastname + ', ' + tu2.user_firstname				[user_nameLastUpdate],
				tcth.task_date4Resolution									[task_date4Resolution],
				tu4res.user_lastname + ', ' + tu4res.user_firstname			[user_name4Resolution]





	from tbCRM_TaskHistory							tcth		WITH (NOLOCK)

		inner join tbCRM_Task						tct			WITH (NOLOCK)
		on	tct.comp_id = tcth.comp_id
		AND tct.task_id = tcth.task_id

		left join tbCustomer						tc			WITH (NOLOCK)
		on	tc.comp_id = tcth.comp_id
		AND tc.cust_id = tcth.cust_id

		left join tbCRM_Case						tcc			WITH (NOLOCK)
		on tcc.comp_id  = tct.comp_id
		and tcc.case_id = tct.case_id

		left join tbCRM_TaskType					tctt		WITH (NOLOCK)
		on tctt.comp_id	  = tcth.comp_id
		and tctt.taskt_id = tcth.taskt_id

		LEFT JOIN tbCRM_TaskStatus					tcts		WITH (NOLOCK)
		ON	tcts.comp_id = tcth.comp_id AND
			tcts.tast_id = tcth.tast_id

		LEFT JOIN tbUser							tu			WITH (NOLOCK)
		ON tu.[user_id] = tcth.[user_id]

		LEFT JOIN tbUser							tu2			WITH (NOLOCK)
		ON tu2.[user_id] = tcth.user_id_lastUpdate

		LEFT JOIN tbUser							tu4res		WITH (NOLOCK)
		ON tu4res.[user_id] = tcth.user_id4Resolution

	where	tcth.comp_id = @comp_id
	and		tcth.task_id = @task_id



END
GO


------------------------
-- Reporte de Tareas
------------------------

CREATE PROCEDURE [dbo].[spCRM_Task_getReport]
(
		@comp_id			INT,
		@lang_id			INT,
		@page_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@task_id			INT,
		@intBranch4Lang		INT


)
AS
SET NOCOUNT ON

BEGIN
	SET DATEFORMAT 'ymd'

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


--------------------------------------------------------
-------------parametros de prueba-----------------------
--------------------------------------------------------
/*
DECLARE		@comp_id			int,
			@lang_id			int,
			@page_id			int,

			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,

			@task_id			INT,
			@intBranch4Lang		INT



SELECT		@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 100965,

			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 1,

			@task_id			= 1148,
			@intBranch4Lang		= 1

DROP TABLE #tmptasks,#tmpcalls,#tmpmeets,#tmpnotes
*/
-------------------------------------------------------
--------------------------------------------------------
--------------------------------------------------------

DECLARE @fun_id INT, @ltotal decimal(19,4), @lcurr_desc nvarchar(50)
SET @fun_id = 1

  DECLARE   @message_task VARCHAR(100),
			@message_call VARCHAR(100),
			@message_meet VARCHAR(100),
			@message_note VARCHAR(100)


 SELECT @message_task = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 151 AND tut.lang_id = @lang_id
 SELECT @message_call = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 152 AND tut.lang_id = @lang_id
 SELECT @message_meet = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 153 AND tut.lang_id = @lang_id
 SELECT @message_note = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 40256 AND tut.lang_id = @lang_id


-------------------------
-- sacar total final.
-------------------------
SELECT @ltotal =

(SELECT ISNULL(SUM(ISNULL(TCT.task_price,0) * ISNULL(tct.Task_qty1,1)),0)

FROM tbCRM_Task tct

	LEFT JOIN tbCRM_TaskStatus			tcts
	ON  tcts.comp_id	= tct.comp_id	AND
		tcts.tast_id	= tct.tast_id

	WHERE 	tct.comp_id	= @comp_id		AND
			tct.task_id	= @task_id)

+

(SELECT ISNULL(SUM(ISNULL(TCT.Task_price2,0) * ISNULL(tct.Task_qty2,0)),0)

FROM tbCRM_Task tct

	LEFT JOIN tbCRM_TaskStatus			tcts
	ON  tcts.comp_id	= tct.comp_id	AND
		tcts.tast_id	= tct.tast_id

	WHERE 	tct.comp_id	= @comp_id		AND
			tct.task_id	= @task_id)

+

(SELECT ISNULL(SUM(ISNULL(tct.Task_price3,0)),0)

FROM tbCRM_Task tct

	LEFT JOIN tbCRM_TaskStatus			tcts
	ON  tcts.comp_id	= tct.comp_id	AND
		tcts.tast_id	= tct.tast_id

	WHERE 	tct.comp_id	= @comp_id		AND
			tct.task_id	= @task_id)

+

(SELECT ISNULL(SUM(ISNULL(TCC.call_price,0)),0)

FROM tbCRM_Call tcc

left join tbCRM_CallStatus			tccs
on  tccs.comp_id	= tcc.comp_id
and tccs.callst_id  = tcc.callst_id

where 	tcc.comp_id			= @comp_id
AND		tcc.task_id			= @task_id)

+

(SELECT ISNULL(SUM(ISNULL(TCM.meet_price,0)),0)

FROM tbCRM_Meet tcm

left join tbCRM_MeetStatus			tcms
on  tcms.comp_id    = tcm.comp_id
and tcms.meetst_id  = tcm.meetst_id

where 	tcm.comp_id			= @comp_id
AND		tcm.task_id			= @task_id )

+

(
	SELECT
		ISNULL(SUM(ISNULL(tctn.tasknote_Price,0)),0)
	FROM tbCRM_TaskNote				tctn
	WHERE	tctn.comp_id = @comp_id AND
			tctn.task_id = @task_id
)




select @lcurr_desc = (	SELECT tc.curr_desc
							FROM tbBranch tb
							INNER JOIN tbsysCurrency tc
								ON TC.curr_id = TB.curr_id
							WHERE tb.bra_id = @bra_id )

--------------------
-- select principal
--------------------


	SELECT
				CASE
					WHEN tct.task_Desc LIKE '%img src="data:image%' then
						dbo.fnStrStripHTML(tct.task_Desc)
					ELSE
						tct.task_Desc
				END																						[task_desc],
				tcts.tast_desc																			[tast_desc],
				tct.task_date4Begin																		[task_date4Begin],
				tct.task_date4End																		[task_date4End],
				tu.user_lastname + ', ' + tu.user_firstname												[User_name],
				tct.task_subject																		[task_subject],
				ISNULL(tct.task_price,0)																[task_price],
				ISNULL(@ltotal,0)																		[total],
				@lcurr_desc																				[curr_desc],
				ISNULL(tctt.taskt_desc,'')																[task_type],
				CONVERT(VARCHAR,tct.task_id)															[task_id],
				ISNULL(tct.Task_price2,0)																[Task_price2],
				ISNULL(tct.Task_price3,0)																[Task_price3],
				ISNULL(tct.Task_qty1,0)																	[Task_qty1],
				ISNULL(tct.Task_qty2,0)																	[Task_qty2],
				ISNULL(tct.task_resolutionCustomerCompliance_Note,'')									[task_resolutionCustomerCompliance_Note],
				ISNULL(tct.task_resolution,'')															[task_resolution],
				tov.optval_desc																			[task_resolutionCustomerCompliance_Calification],
				ISNULL(tc.cust_name,'')																	[cust_name],
				ISNULL(tc2.contact_name,'')																[contact_name],
				ISNULL(ts.supp_name,'')																	[supp_name],
				ISNULL(tcts.tast_reportFooter,'')														[tast_reportFooter],
				ISNULL(tctt.taskt_reportFooter,'')														[taskt_reportFooter],
				isnull(tulastupdate.user_lastname,'') + ', ' + isnull(tulastupdate.user_firstname,'')	[user_id_lastUpdate],
				(ISNULL(tct.task_qtyHour,0) * 60)			+ ISNULL(tct.task_qtyMinutes,0)				[task_qtyMinutes],
				(ISNULL(tct.task_qtyEstimatedHours,0) * 60) + ISNULL(tct.task_qtyEstimatedMinutes,0)	[task_qtyEstimatedMinutes],
				tct.task_date4Resolution																[task_date4Resolution],
				isnull(tu4Resolution.user_lastname,'') + ', ' + isnull(tu4Resolution.user_firstname,'')	[user_id4Resolution],
				ISNULL(tct.task_Desc,'')																[fullTaskDesc],
				ISNULL(tct.task_IFAvailableInVersion,0)													[task_IFAvailableInVersion]

	into #tmptasks
	FROM	tbCRM_Task									tct


			left join tbCRM_TaskStatus					tcts
			on  tcts.comp_id	= tct.comp_id
			and tcts.tast_id	= tct.tast_id

			LEFT JOIN	tbUser							tu
			ON  tu.[user_id]	= tct.[user_id]

			LEFT JOIN tbUser							tulastupdate	WITH(NOLOCK)
			ON tulastupdate.[user_id]		= tct.user_id_lastUpdate

			LEFT JOIN tbUser							tu4Resolution	WITH(NOLOCK)
			ON tu4Resolution.[user_id]		= tct.user_id4Resolution

			INNER JOIN	tbCRM_TypesByProfile			tctbp
			on  tctbp.comp_id	= @comp_id
			and tctbp.bra_id	= @bra_id
			and tctbp.prof_id	= @prof_id
			and tctbp.crm_type	= 1	--tarea

			left join tbCRM_TaskType					tctt
			on  tctt.taskt_id   = tct.taskt_id
			AND tctt.comp_id    = tct.comp_id

			INNER JOIN tbsysOptionsValues				tov
			ON	tov.lang_id			= @lang_id			AND
				tov.optval_class	= 696 AND
				tov.optval_id		= tct.task_resolutionCustomerCompliance_Calification

			LEFT JOIN tbCustomer						tc
			ON	tc.comp_id			= tct.comp_id		AND
				tc.cust_id			= tct.cust_id

			LEFT JOIN tbContact							tc2
			ON	tc2.comp_id			= tct.comp_id		AND
				tc2.contact_id		= tct.contact_id

			LEFT JOIN tbSupplier						ts
			ON	ts.comp_id			= tct.comp_id		AND
				ts.supp_id			= tct.supp_id

	WHERE	tct.comp_id			= @comp_id
	AND		tct.task_id			= @task_id




 IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmptasks

		END
	  ELSE
			SELECT @message_task [task_desc],
					' ' [tast_desc],
					' ' [task_date4Begin],
					' ' [task_date4End],
					' ' [User_name],
					' ' [task_subject],
					' ' [task_price]


----------------------------------------------------
--params--
----------------------------------------------------


exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/

SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1912
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

		CASE @task_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(select task_desc from tbCRM_Task tct
				where   tct.comp_id    = @comp_id
				And   tct.task_id   = @task_id)
		End [params2]

----------------------------------------------------

----------------------------------------------------

--
----subreporte - Casos relacionadas a la tarea.
------------------------------------------------------
--
--	SELECT      tccs.cast_desc									[Estado],
--				cc.case_date4Begin								[Fecha_Inicio],
--				cc.case_date4End								[Fecha_Fin],
--				tu.user_lastname + ', ' + tu.user_firstname		[User_Name],
--				cc.case_desc									[Desc],
--				cc.case_subject									[Subject],
--				cc.case_resolution								[Resolucion],
--				cc.case_hours									[Horas]
--
--
--	FROM 	dbo.tbCRM_Case								cc
--
--			LEFT JOIN	tbCRM_CaseStatus				tccs
--			ON  tccs.comp_id	= cc.comp_id
--			AND tccs.cast_id	= cc.cast_id
--
--			LEFT JOIN	tbUser							tu
--			ON  tu.[user_id]	= cc.[user_id]
--
--
--where 	cc.comp_id			= @comp_id
--AND		cc.bra_id			= @bra_id
--AND		tccs.prof_id		= @prof_id
--AND		cc.[user_id]		= @user_id
----AND					= @task_id
--
------------------------------------------------------
------------------------------------------------------




--subreporte - Llamadas relacionadas a la tarea.
----------------------------------------------------

select  tcc.call_description,
		tccs.callst_desc,
		tcc.call_date4Begin,
		tu.user_lastname + ', ' + tu.user_firstname [User_name],
		tcc.call_Note1,
		tcc.call_Note2,
		isnull(tcc.call_price,0) [call_price]

into #tmpcalls
from tbCRM_Call										tcc

	left join tbCRM_CallStatus						tccs
	on  tccs.comp_id	= tcc.comp_id
	and tccs.callst_id  = tcc.callst_id

	left join tbCRM_Task							tct
	on  tct.comp_id		= tcc.comp_id
	and tct.task_id		= tcc.task_id

	left join tbUser								tu
	on  tu.[user_id]	= tcc.[user_id]


where 	tcc.comp_id			= @comp_id
AND		tcc.task_id			= @task_id


 IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmpcalls

		END
 ELSE
			SELECT  @message_call [call_description],
					' ' [callst_desc],
					' ' [call_date4Begin],
					' ' [User_name],
					' ' [call_Note1],
					' ' [call_Note2],
					' ' [call_price]

----------------------------------------------------
----------------------------------------------------



--subreporte - Reuniones relacionadas a la tarea.
----------------------------------------------------


select  tcms.meetst_desc,
		tcm.meet_date4Begin,
		tu.user_lastname + ', ' + tu.user_firstname [User_name] ,
		tcm.meet_description,
		tcm.meet_subject,
		tcm.meet_location,
		isnull(tcm.meet_price,0) [meet_price]

into #tmpmeets
from tbCRM_Meet									tcm

	left join tbCRM_MeetStatus					tcms
	on  tcms.comp_id    = tcm.comp_id
	and tcms.meetst_id  = tcm.meetst_id

	left join tbCRM_Task						tct
	on  tct.comp_id		= tcm.comp_id
	and tct.task_id		= tcm.task_id

	left join tbUser							tu
	on  tu.[user_id]	= tcm.[user_id]



where 	tcm.comp_id			= @comp_id
AND		tcm.task_id			= @task_id

IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmpmeets

		END
ELSE
			SELECT  ' ' [meetst_desc],
					@message_meet [meet_description],
					' ' [meet_date4Begin],
					' ' [User_name],
					' ' [meet_subject],
					' ' [meet_location],
					' ' [meet_price]


----------------------------------------------------
----------------------------------------------------


--subreporte - Notas relacionadas a la tarea.
----------------------------------------------------


select
		CASE
			WHEN tcm.tasknote_Note LIKE '%<img src=%' THEN	(	SELECT tut.utexts_desc
			                                              			FROM tbsysUniqueTexts tut
			                                              	 		WHERE	tut.lang_id		= 2 AND
			                                              	 				tut.utexts_id	= 777
															)
			ELSE											tcm.tasknote_Note
		END											[tasknote_Note],
		tcm.tasknote_cd								[tasknote_cd],
		tu.user_lastname + ', ' + tu.user_firstname [User_name] ,
		tcm.tasknote_Subject						[tasknote_Subject],
		isnull(tcm.tasknote_Price,0)				[tasknote_Pricee],
		tcm.tasknote_Note							[fullTaskNote]

into #tmpnotes
FROM tbCRM_TaskNote 							tcm

	left join tbCRM_Task						tct
	on  tct.comp_id		= tcm.comp_id
	and tct.task_id		= tcm.task_id

	left join tbUser							tu
	on  tu.[user_id]	= tcm.[user_id]

where 	tcm.comp_id			= @comp_id
AND		tcm.task_id			= @task_id

--ORDER BY tcm.tasknote_id desc

IF @@ROWCOUNT>0
		BEGIN
			  SELECT * FROM #tmpnotes
			  ORDER BY [tasknote_cd] DESC

		END
ELSE
			SELECT  @message_note					[tasknote_Note],
					' '								[tasknote_cd],
					' '								[User_name],
					' '								[tasknote_Subject],
					' '								[tasknote_Price],
					@message_note					[fullTaskNote]


----------------------------------------------------
----------------------------------------------------






END
GO


CREATE PROCEDURE [dbo].[spCRM_Task_insertData]
(
	@comp_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@lang_id				INT,

	@task_subject			NVARCHAR(200),
	@task_date4Begin		DATETIME,
	@task_date4End			DATETIME,
	@task_priority			INT,
	@task_desc				NTEXT,
	@case_id				INT,
	@soh_Bra_id				INT,
	@soh_soh_id				INT,
	@cust_id				INT,
	@contact_id				INT,
	@tast_id				INT,
	@task_price				decimal(19,4),
	@curr_id				int,
	@chkCA					bit,
	@taskt_id				int,
	@task_emailAdditional	VARCHAR(250),
	@task_resolution		NVARCHAR(4000),
	@supp_id				INT,
	@task_nextReviewdate	DATETIME,
	@user_idCreator			INT,
	@return_value			INT OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON


	-- -----------------------------------------------
	-- TESTING
	-- -----------------------------------------------
	/*
	declare
		@comp_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@lang_id			INT,

		@task_subject		NVARCHAR(200),
		@task_date4Begin	DATETIME,
		@task_date4End		DATETIME,
		@task_priority		INT,
		@task_desc			NVARCHAR(4000),
		@case_id			INT,
		@soh_Bra_id			INT,
		@soh_soh_id			INT,
		@cust_id			INT,
		@contact_id			INT,
		@tast_id			INT,
		@task_price			decimal(19,4),
		@curr_id			int,
		@chkCA				bit--,
		--@return_value		INT OUTPUT
	*/
	-- -----------------------------------------------


	IF @case_id = -1
		BEGIN
			SET @case_id = NULL
		END

	IF @cust_id = -1
		BEGIN
			SET @cust_id = NULL
		END
	IF @contact_id = -1
		BEGIN
			SET @contact_id = NULL
		END
	IF @supp_id = -1
		BEGIN
			SET @supp_id = NULL
		END


	IF @user_idCreator = -1
		BEGIN
			SET @user_idCreator = @user_id
		END

	-- -----------------------------------------------------------------------
	-- MOS 08-2023: para que el BOT pueda dejar grabado el CONTACTO
	-- -----------------------------------------------------------------------
	DECLARE @wact_id AS integer = NULL
	IF 	@soh_Bra_id < 0 AND
		@soh_soh_id < 0
		BEGIN
			IF @soh_Bra_id = -98765
				BEGIN
					SET @wact_id = @soh_soh_id * -1
					SET @soh_Bra_id = 0
					SET @soh_soh_id = 0
				END
		END
	-- MOS 08-2023:si viene del BOT mira si no hay algun ticket ya ingresado en los mismos estados.  si esta, agrega notas y no vuelve a cargar el ticket
	IF @wact_id > 0
		BEGIN
			DECLARE @intTaskID AS INT = NULL
			SELECT	@intTaskID = tct.task_id
				FROM tbCRM_Task AS tct	WITH (NOLOCK)
				WHERE	tct.comp_id		= @comp_id AND
						tct.wact_id		= @wact_id AND
						tct.[user_id]	= @user_id AND
						tct.bra_id		= @bra_id  AND
						tct.tast_id		= @tast_id AND
						tct.taskt_id	= @taskt_id

			IF @intTaskID IS NOT NULL
				BEGIN
					INSERT INTO tbCRM_TaskNote
					(
						comp_id,
						-- tasknote_id -- this column value is auto-generated
						task_id,
						[user_id],
						prof_id,
						tasknote_cd,
						tasknote_Subject,
						tasknote_Note
					)
					VALUES
					(
						@comp_id,
						@intTaskID,
						@user_id,
						@prof_id,
						GETDATE(),
						@task_subject,
						@task_desc
					)
					RETURN
				END

		END
	-- -----------------------------------------------------------------------




	BEGIN

		INSERT INTO tbCRM_Task		WITH (ROWLOCK)
		(
			comp_id,
			bra_id,
			task_subject,
			task_date4Begin,
			task_date4End,
			task_priority,
			[user_id],
			task_desc,
			case_id,
			soh_Bra_id,
			soh_soh_id,
			cust_id,
			contact_id,
			tast_id,
			task_price,
			curr_id,
			taskt_id,
			task_emailAdditional,
			task_resolution,
			task_secondUpdate,
			supp_id,
			task_nextReviewdate,
			user_id_Creator,
			task_lastUpdate,
			user_id4lastUpdate,
			wact_id
		)
		VALUES
		(
			@comp_id,
			@bra_id,
			@task_subject,
			@task_date4Begin,
			@task_date4End,
			@task_priority,
			@user_id,
			@task_desc,
			@case_id,
			@soh_Bra_id,
			@soh_soh_id,
			@cust_id,
			@contact_id,
			@tast_id,
			@task_price,
			@curr_id,
			@taskt_id,
			@task_emailAdditional,
			@task_resolution,
			'False',
			@supp_id,
			@task_nextReviewdate,
			@user_idCreator,
			GETDATE(),
			@user_idCreator,
			@wact_id
		)


		SET @return_value = IDENT_CURRENT('tbCRM_Task')  -- @@IDENTITY

		-- -----------------------------------------------------------------------------
		-- ACA SE GRABA TODAS LAS NOTAS DE LA MASCARA DE TIPO DE NOTA PARA ISO
		-- STL 29-06-2018
		-- #STL29062018
		-- -----------------------------------------------------------------------------
			INSERT INTO tbCRM_TaskNote
			(
				comp_id,
				task_id,
				[user_id],
				prof_id,
				tasknote_cd,
				tasknote_PDF,
				tasknote_Price,
				tasknote_Subject,
				tast_id,
				tasknote_Note,
				tasknote_qtyHour,
				tasknote_qtyMinutes,
				tasknotet_id,
				tasknote_isChecked,
				tasknote_isCheckedLimitDate
			)
			SELECT
				tctnm.comp_id,
				@return_value,
				NULL/*@user_id*/,
				@prof_id,
				NULL,
				NULL,
				0,
				tctnm.tasknote_Subject,
				NULL,
				tctnm.tasknote_Note,
				0,
				0,
				tctnm.tasknotet_id,
				CASE
					WHEN tctnt.tasknotet_mustCheck = 'True' THEN	'False'
					ELSE											NULL
				END,
				CASE
					WHEN tctnt.tasknotet_mustCheck = 'True' THEN dbo.fnGetEnd_or_BeginOfDate(DATEADD(DAY,ISNULL(tctnm.tnm_days4Limit,0) + ISNULL(tctnt.tasknotet_days4Limit,0),ISNULL(@task_date4Begin,GETDATE())),'True')
					ELSE											NULL
				END

				FROM tbCRM_TaskNoteMask				tctnm
				INNER JOIN tbCRM_TaskNoteType		tctnt
					ON	tctnt.comp_id		= tctnm.comp_id		AND
						tctnt.taskt_id		= tctnm.taskt_id	AND
						tctnt.tasknotet_id	= tctnm.tasknotet_id
				WHERE	tctnm.comp_id	= @comp_id	AND
						tctnm.bra_id	= @bra_id	AND
						tctnm.taskt_id	= @taskt_id
				ORDER BY tctnm.tnm_order ASC
		-- -----------------------------------------------------------------------------




	-- -------------------------------------------------------
	-- Enviamos EMAils en caso de corresponder
	-- -------------------------------------------------------
	EXEC spCRM_Task_sendEmail @comp_id, @return_value, @lang_id
	-- -------------------------------------------------------

	-- ----------------------------------------------------------
	-- ACTUALIZAMOS SALE ORDER
	-- ----------------------------------------------------------
		if (@chkCA = 'False')
			begin
				declare
						@soss_id		INT
				select
						@soss_id		= ssos_id
					from tbSaleOrderHeader				tsoh			WITH (NOLOCK)
					where	tsoh.comp_id	= @comp_id
					and		tsoh.bra_id		= @bra_id
					and		tsoh.soh_id		= @soh_soh_id

				if (@soss_id = 10)
					begin
						update tbSaleOrderHeader		WITH (ROWLOCK)
							SET
									ssos_id		= 20
							where	comp_id		= @comp_id
							and		bra_id		= @bra_id
							and		soh_id		= @soh_soh_id
					end
			end
	-- ----------------------------------------------------------

	END



END
GO


CREATE  PROCEDURE [dbo].[spCRM_Task_InsertSupportRequestTaskNote]
(
	@comp_id				INT,
	@user_id				INT,
	@task_id				INT,
	@task_image				IMAGE ,
	@strTaskSubject			NVARCHAR(200),
	@strTaskNote			NVARCHAR(4000)
)
AS
BEGIN
	SET NOCOUNT ON

	IF DATALENGTH(@task_image) = 339 SET @task_image = NULL   -- POr si llega MIERDA mal generada por configurar cualquier MIERDA en SupportRequest, que no la guarde.

	INSERT INTO tbCRM_TaskNote
	(
		comp_id,
		-- tasknote_id -- this column value is auto-generated,
		task_id,
		[user_id],
		prof_id,
		tasknote_cd,
		tasknote_Note,
		tasknote_PDF,
		tasknote_Price,
		tasknote_Subject
	)
	VALUES
	(
		@comp_id,
		@task_id,
		@user_id,
		NULL,
		GETDATE(),
		@strTaskNote,
		@task_image,
		0,
		@strTaskSubject
	)



	-- POne la tarea en Advertencia ya que se agregó una nota de CRM
	UPDATE tbcrm_task
		SET task_advertiseDate		= dbo.fnGetEnd_or_BeginOfDate(  DATEADD(DAY,1,GETDATE()),'False'),
			task_advertise_desc		= 'Support Request: Se insertó una Nota de Tarea',
			task_advertiseLastDate	= GETDATE()
		WHERE	comp_id = @comp_id AND
				task_id = @task_id


	-- -------------------------------------------------------
	-- Enviamos EMAils en caso de corresponder
	-- -------------------------------------------------------
	DECLARE @lang_id AS INT
	SELECT @lang_id = isnull(TC.lang_id,2)
		FROM tbCompany tc	WITH (NOLOCK)
		WHERE tc.comp_id = @comp_id
	EXEC spCRM_Task_sendEmail @comp_id, @task_id, @lang_id
	-- -------------------------------------------------------


END
GO








CREATE PROCEDURE [dbo].[spCRM_Task_Relations]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@task_id	INT
)
as

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on


	-- -----------------------------------------------
	-- Testing
	-- -----------------------------------------------
	/*
		declare
			@comp_id	INT,
			@task_id	INT
		select
			@comp_id	= 1,
			@task_id	= 4
	*/
	-- -----------------------------------------------


	select distinct tct.task_id,tct.task_subject   -- Era Task_Desc

	from tbCRM_Task tct

	inner join tbCRM_Call tcc
	on tcc.comp_id = tct.comp_id
	and tcc.task_id = tct.task_id

	WHERE tct.comp_id = @comp_id
	and   tct.task_id = @task_id

	UNION

	select distinct tct.task_id,tct.task_subject

	from tbCRM_Task tct

	inner join tbCRM_Meet tcm
	on tcm.comp_id = tct.comp_id
	and tcm.task_id = tct.task_id

	WHERE tct.comp_id = @comp_id
	and   tct.task_id = @task_id




END
GO


CREATE PROCEDURE [dbo].[spCRM_Task_sendEmail]
(
	@comp_id			INT,
	@task_id			INT,
	@lang_id			int
)
AS



-- --------------------------------------
-- TESTING
-- --------------------------------------
/*
declare
	@comp_id			INT = 1,
	@lang_id			INT = 2,
	@task_id			INT = 3403
*/
-- --------------------------------------

BEGIN


	SET NOCOUNT ON

	-- MOS 06-2024: Si viene de una advertencia ( uso asi para no romper nada ) me doy cuenta y pongo q si o si mande el email.
	DECLARE @bolForce2EnvieEMail AS BIT = 'False'
	IF @lang_id < 0
		BEGIN
			SET @lang_id = @lang_id * -1
			SET @bolForce2EnvieEMail = 'True'
		END




	declare
		@user_origen					int,
		@message						varchar(4000),
		@subject						varchar(4000),
		@body							varchar(4000),
		@mail							varchar(8000),
		@user_origen_name				varchar(400),
		@user_mail_origin				varchar(400),
		@user_origen_destiny			varchar(400),
		@user_mail_destiny				varchar(400),
		@optionid						int,
		@desc							varchar(2000),
		@cust_id						INT,
		@tast_id						INT,
		@taskt_id						INT,
		@task_subject					NVARCHAR(MAX),
		@task_desc						NVARCHAR(MAX),
		@task_date4Begin				DATETIME ,
		@task_date4End					DATETIME	,
		@task_resolution				NVARCHAR(MAX),
		@task_customerCompliance_note	NVARCHAR(MAX),
		@user_id4lastUpdate				INT

	DECLARE @user_id		 INT

	SELECT	@user_id						= tct.[user_id],
			@cust_id						= tct.cust_id,
			@tast_id						= tct.tast_id,
			@taskt_id						= tct.taskt_id,
			@task_subject					= tct.task_subject,
			@task_desc						= convert(NVARCHAR(MAX),tct.task_desc),
			@task_date4Begin				= tct.task_date4Begin,
			@task_date4End					= tct.task_date4End,
			@task_resolution				= tct.task_resolution,
			@task_customerCompliance_note	= ISNULL(tct.task_customerCompliance_note,''),
			@user_id4lastUpdate				= ISNULL(tct.user_id4lastUpdate,tct.[user_id])
		FROM tbCRM_Task tct		WITH (NOLOCK)
		WHERE	tct.comp_id = @comp_id AND
				tct.task_id = @task_id


	-- MOS 06-2024: Si el que modifica esd el mismo, es AL PEDO que mande mail avisando...
	IF	@bolForce2EnvieEMail	= 'False'	AND
		@user_id4lastUpdate		= @user_id
		BEGIN
			RETURN
		END



	-- Si hay una imagen la corta para que no explote el mail
	IF @task_desc LIKE '%img src="data:image%'
		BEGIN
			SET @task_desc = dbo.fnStrStripHTML(@task_desc)
			SET @task_desc = SUBSTRING(@task_desc,1,3000) + '<br/><br/> <b> El texto no está completo, visualizar en el sistema. <br/> The text is not complete, visualize in the system. </b>'
		END

	-- Si es muy larga la corta para que no explote el mail
	IF LEN(@task_desc) > 3000
		BEGIN
			SET @task_desc = SUBSTRING(@task_desc,1,3000) + '<br/><br/> <b> El texto no está completo, visualizar en el sistema. <br/> The text is not complete, visualize in the system. </b>'
		END


	--Datos del Usuario de Origen
	select
		@user_origen_name	= (tu.user_lastname + ',' + tu.user_firstname),
		@user_mail_origin	= tu.user_email
		from tbUser tu		WITH (NOLOCK)
		where tu.[user_id]	= @user_id4lastUpdate --MOS 06-2024: para que mande del que MANDA y no del mismo asignado  @user_id

	-- Que MIERDA es esto ?
	set @optionid = 3583


	--Datos del Usuario de Destino
	select
		@user_origen_destiny	= (tu.user_lastname + ',' + tu.user_firstname),
		@user_mail_destiny		= tu.user_email
		from tbUser tu		WITH (NOLOCK)
		where tu.[user_id]		= @user_id

	-- ---------------------------------------
	-- Textos para armado del mail completo
	DECLARE
		@lTaskSubject			VARCHAR(100),
		@TaskDesc				VARCHAR(100),
		@TaskResolution			VARCHAR(100),
		@date4begin				VARCHAR(100),
		@date2end				VARCHAR(100),
		@Task_Resolution_Text	VARCHAR(100),
		@Task_Crm_NotesHeader	VARCHAR(100)




	--ASUNTO
	select @lTaskSubject	= '<b>' + tut.utexts_desc	+ '</b>'
	from tbsysUniqueTexts	tut		WITH (NOLOCK)
	where tut.lang_id		= @lang_id
	and tut.utexts_id		= 300626
	--DESCRIPCION
	select @TaskDesc		= '<b>' + tut.utexts_desc	+ '</b>'
	from tbsysUniqueTexts	tut		WITH (NOLOCK)
	where tut.lang_id		= @lang_id
	and tut.utexts_id		= 300627
	--RESOLUCION
	select @TaskResolution	= '<b>' + tut.utexts_desc	+ '</b>'
	from tbsysUniqueTexts	tut		WITH (NOLOCK)
	where tut.lang_id		= @lang_id
	and tut.utexts_id		= 300628
	--Fecha Inicio
	select @date4begin		= tut.utexts_desc
	from tbsysUniqueTexts	tut		WITH (NOLOCK)
	where tut.lang_id		= @lang_id
	and tut.utexts_id		= 300629
	--Fecha Fin
	select @date2end		= tut.utexts_desc
	from tbsysUniqueTexts	tut		WITH (NOLOCK)
	where tut.lang_id		= @lang_id
	and tut.utexts_id		= 300630
	--Resolución
	select @Task_Resolution_Text = '<b>' + tut.utexts_desc + '</b>'
	from tbsysUniqueTexts	tut		WITH (NOLOCK)
	where tut.lang_id		= @lang_id
	and tut.utexts_id		= 30878

	--Notas de Tarea
	SELECT
		@Task_Crm_NotesHeader = tut.utexts_desc
	FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
	WHERE	tut.lang_id		= @lang_id	AND
			tut.utexts_id	= 30886

	-- Datos del Cliente
	DECLARE @strCustomer AS NVARCHAR(200)
	SET @strCustomer = ''
	SELECT
		@strCustomer = tc.cust_name
		FROM tbCustomer					tc			WITH (NOLOCK)
		WHERE	tc.comp_id = @comp_id	AND
				tc.cust_id = @cust_id

	DECLARE @strCustDesc NVARCHAR(100)
	SET @strCustDesc = ''
	SELECT
		@strCustDesc = '<b>' + tut.utexts_desc + '</b>'
	FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
	WHERE	tut.lang_id		= @lang_id	AND
			tut.utexts_id	= 400025

	-- Solicitado por
	DECLARE @strSolicitadoPor	AS NVARCHAR(200)
	SET		@strSolicitadoPor = ''
	SELECT
		@strSolicitadoPor = '<b>' + tut.utexts_desc + '</b>'
	FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
	WHERE	tut.lang_id		= @lang_id	AND
			tut.utexts_id	= 40307

	IF @task_customerCompliance_note = ''
		BEGIN
			SET @strSolicitadoPor = ''
		END
	ELSE
		BEGIN
			SET @strSolicitadoPor = @strSolicitadoPor + ' ' + @task_customerCompliance_note
		END
	-- ---------------------------------------


	--Armado de Subject y Body
	select @desc = tswn.word_desc
		from tbSysWordsNew tswn						WITH (NOLOCK)
		where	tswn.lang_id	= @lang_id and
				tswn.wordsi_id	= @optionid

	/*************************************************************************************/
	/*En caso de poseer un TEXTO EN LA HEADER/FOOTER propia, utilizamos ese, sino        */
	/*utilizamos el valor genérico de CRM de la UniqueTexts                              */
	/*************************************************************************************/
	IF EXISTS (SELECT 1
				   FROM tbCRM_TaskMailHeaderFooter			tctmhf WITH (NOLOCK)
				   WHERE	tctmhf.comp_id					= @comp_id AND
							tctmhf.tast_id					= @tast_id AND
							tctmhf.taskt_id					= @taskt_id AND
							ISNULL(tctmhf.crmhf_Subject,'') <> '')
		BEGIN
			SELECT
				@subject = tctmhf.crmhf_Subject
				FROM tbCRM_TaskMailHeaderFooter			tctmhf WITH (NOLOCK)
				WHERE	tctmhf.comp_id		= @comp_id	AND
						tctmhf.tast_id		= @tast_id	AND
						tctmhf.taskt_id		= @taskt_id
		END
	ELSE
		BEGIN
			SELECT
				@subject = tut.utexts_desc
				FROM tbsysUniqueTexts				tut	WITH (NOLOCK)
				WHERE	tut.lang_id		= @lang_id	AND
						tut.utexts_id	= 30025

			set @subject = @subject + @desc
		END




	select @message = tut.utexts_desc
		from tbsysUniqueTexts tut		WITH (NOLOCK)
		where tut.lang_id = @lang_id
		and tut.utexts_id = 985

	select @body = tut.utexts_desc
		from tbsysUniqueTexts tut		WITH (NOLOCK)
		where tut.lang_id = @lang_id
		and tut.utexts_id = 986



	set @mail = @desc								+ ' ' +
				@message							+ ' ' +
				@user_origen_name					+ ' ' +
				@body								+ ' ' +
				convert(varchar,@task_id)			+ ' ' +
				@lTaskSubject						+ ' ' +
				@task_subject						+ ' ' +
				@TaskDesc							+ ' ' +
				@task_desc							+ ' ' +
				@date4begin							+ ' ' +
				CONVERT(VARCHAR,@task_date4Begin)	+ ' ' +
				@date2end							+ ' ' +
				CONVERT(VARCHAR,@task_date4End)

	-- ---------------------------------------------------------------
	-- ARMADO DEL HTML PARA EL MAIL
	-- ---------------------------------------------------------------
	--ARMAMOS HEADER Y FOOTER EN CASO DE QUE HAYA VALORES EN LAS TABLAS

	DECLARE @MailTableHeader AS NVARCHAR(MAX),
			@HeaderText		 AS NVARCHAR(MAX),
			@FooterText		 AS NVARCHAR(MAX)

	SET @HeaderText = ''
	SET @FooterText = ''

	SELECT
		@HeaderText = tctmhf.htmlHeader,
		@FooterText = tctmhf.htmlFooter
	FROM tbCRM_TaskMailHeaderFooter tctmhf		WITH (NOLOCK)
	WHERE	tctmhf.comp_id	= @comp_id AND
			tctmhf.tast_id	= @tast_id AND
			tctmhf.taskt_id	= @taskt_id

	IF NOT LEN(@HeaderText) > 0
		SET @HeaderText = ''
	IF NOT LEN(@FooterText) > 0
		SET @FooterText = ''

	-- ESTADO
	DECLARE @Status				AS VARCHAR(MAX)
	DECLARE @Task_Status		AS VARCHAR(MAX)

		SELECT @Status =  '<b>' + tut.utexts_desc + '</b>'
			FROM tbsysUniqueTexts tut
			WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30022

		SELECT @Task_Status = tcts.tast_desc
			FROM tbCRM_TaskStatus tcts
			WHERE tcts.comp_id = @comp_id AND tcts.tast_id = @tast_id

	--variables para el formateo del html email
		DECLARE	@MailTable							NVARCHAR(MAX),
				@MailEndTable						NVARCHAR(MAX),
				@Mailsubject						NVARCHAR(MAX),
				@MailbodyHeader						NVARCHAR(MAX),
				@Mailbody							NVARCHAR(MAX),
				@MailbodyFooter						NVARCHAR(MAX),
				@MailImageSRC						NVARCHAR(MAX),
				@MailTaskNotes						NVARCHAR(MAX)


	SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

	SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black;border-radius:8px;" ' +
					 'cellpadding="3" cellspacing="5" border="6"  BORDERCOLOR="#666666" BORDERCOLORLIGHT="#8c8c8c" BORDERCOLORDARK="#404040">'

	SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
						  '<b>' + @subject + @desc + '</b><br /><br /><br />'


	SET @Mailbody = ''
	SET @MailBody =

		'<tr>
			<td style="border-radius:4px;" align="Left">' +
				@strCustDesc + ' : ' + @strCustomer  + ' ' +
			'</td>
		<tr>
		<tr><td style="border-radius:4px;" align="Left">' +
			@desc + ' ' + @message + ' ' +  @user_origen_name  + ' ' +
		'</td><tr><td style="border-radius:4px;" align="Left">' +
			@body + ' ' + convert(varchar,@task_id)+ ' ' +
		'</td></tr><td style="border-radius:4px;" align="Left">' +
			@lTaskSubject + ' ' + @task_subject + ' ' +
		'</td></tr><td style="border-radius:4px;" align="Left">' +
			@Status + ' ' + @Task_Status + ' ' +
		'</td><tr><td style="border-radius:4px;" align="Left">' +
			@TaskDesc + '<BR> ' + dbo.fnSystem_sendEMail_SetBody2HTML(@task_desc) + ' ' +
		'</td><tr><td style="border-radius:4px;" align="Left">' +
			@date4begin + ' ' + CONVERT(VARCHAR,@task_date4Begin) + ' ' +
		'</td><tr><td style="border-radius:4px;" align="Left">' +
			@date2end + ' ' + CONVERT(VARCHAR,@task_date4End) + ' ' +
		'</td></tr>' +
		'</td><tr><td style="border-radius:4px;" align="Left">' +
			ISNULL(@Task_Resolution_Text,'Resolución') + ' :' + ISNULL(@task_resolution,'') + ' ' +
		'</td></tr> ' +
		'</td><tr><td style="border-radius:4px;" align="Left">' +
			@strSolicitadoPor + ' ' +
		'</td></tr> '
	-- ---------------------------------------------------------------------------------
	-- ULTIMA CELDA CON LA ULTIMA NOTA DE LA TABLA CRM_TASKNOTES
	-- ---------------------------------------------------------------------------------
		DECLARE
			@TaskNoteDesc	NVARCHAR(100),
			@TaskTitle		NVARCHAR(100),
			@TaskNote		NVARCHAR(MAX),
			@TaskDateTitle	NVARCHAR(100),
			@TaskCD			VARCHAR(100)

		SELECT @TaskTitle = '<b>' + tut.utexts_desc + '</b>'
			FROM tbsysUniqueTexts tut	WITH (NOLOCK)
			WHERE tut.lang_id = @lang_id AND tut.utexts_id = 240000

		SELECT @TaskDateTitle = tut.utexts_desc
			FROM tbsysUniqueTexts tut	WITH (NOLOCK)
			WHERE tut.lang_id = @lang_id AND tut.utexts_id = 240001

		SELECT @TaskNoteDesc = tut.utexts_desc
			FROM tbsysUniqueTexts tut	WITH (NOLOCK)
			WHERE tut.lang_id = @lang_id AND tut.utexts_id = 240002



	SET @TaskNote = ''

	SELECT TOP 1
		@TaskCD		= convert(varchar(50),tctn.tasknote_cd),
		@TaskNote	= ISNULL(tctn.tasknote_Subject,'')
		FROM tbCRM_TaskNote				tctn		WITH (NOLOCK)
		WHERE	tctn.comp_id = @comp_id AND
				tctn.task_id = @task_id
		ORDER BY tctn.tasknote_cd DESC

	IF @TaskNote <> ''
		BEGIN
			SET @MailTaskNotes =
								'<tr><td style="border-radius:4px;" align="Left" bgcolor="#E6E6E6">'				+
									@TaskTitle											+ ' ' +
								'</tr><tr><td style="border-radius:4px;" align="Left" bgcolor="#E6E6E6">'				+
									@TaskDateTitle	+ ' ' + @TaskCD						+ ' ' +
								'</td></tr><tr><td style="border-radius:4px;" align="Left" bgcolor="#E6E6E6">'			+
									@TaskNoteDesc	+ ' ' +  @TaskNote					+ ' ' +
								'</td></tr>'

		END
	ELSE
		BEGIN
			SET @MailTaskNotes = @MailTaskNotes
		END

	-- ---------------------------------------------------------------------------------

	SET @MailEndTable = + '</table>'

	SET @MailbodyFooter =

				'</div>'


--==
--SELECT '@Mailbody' , @Mailbody
--SELECT '@@HeaderText' , @HeaderText
--SELECT '@@MailTable' , @MailTable
--SELECT '@@MailTaskNotes' , @MailTaskNotes
--SELECT '@@MailEndTable' , @MailEndTable
--SELECT '@@FooterText' , @FooterText
--SELECT '@MailbodyFooter' , @MailbodyFooter


	SET @Mailbody = ISNULL(@HeaderText,'')			+ ' ' +
					ISNULL(@MailTable,'')			+ ' ' +
					ISNULL(@Mailbody,'')			+ ' ' +
					ISNULL(@MailTaskNotes,'')		+ ' ' +
					ISNULL(@MailEndTable,'')		+ ' ' +
					ISNULL(@FooterText,'')			+ ' ' +
					ISNULL(@MailbodyFooter,'')
	-- ---------------------------------------------------------------


--==
--select @Mailbody

	-- -----------------------------------------------------------------------------
	-- Envio del Mail
	-- -----------------------------------------------------------------------------
	DECLARE @strMailString	AS NVARCHAR(MAX)
	DECLARE @strMail		AS NVARCHAR(MAX)
	DECLARE @strMailCC		AS NVARCHAR(MAX)
	DECLARE @strMailCCO		AS NVARCHAR(MAX)
	DECLARE @strMailFrom    AS NVARCHAR(MAX)
	SELECT  @strMailString	= dbo.fnCRM_GetCustomerEmailByTaskType(@comp_id, @cust_id, @taskt_id, @tast_id, @task_id, @user_id)
	SELECT  @strMail		= dbo.fnSplitPosition(@strMailString, '|',1)
	SELECT  @strMailCC		= dbo.fnSplitPosition(@strMailString, '|',2)
	SELECT  @strMailCCO		= dbo.fnSplitPosition(@strMailString, '|',3)
	SELECT  @strMailFrom	= dbo.fnSplitPosition(@strMailString, '|',4)


	exec spSystem_sendEMail
							@compId					= @comp_id,
							@precipients			= @strMail,
							@pcopy_recipients		= @strMailCC,
							@psubject				= @subject,
							@pbody_format			= 'HTML',
							@pbody					= @Mailbody,
							@pfile_attachments		= null,
							@pReplyTo				= @strMailFrom,
							@pblind_copy_recipients	= @strMailCCO,
							@pUser_Id				= @user_id
	-- -----------------------------------------------------------------------------


END
GO



CREATE PROCEDURE [dbo].[spCRM_Task_SendNotifications]

AS
	SET NOCOUNT ON

	BEGIN
		/*
		DECLARE
			@lang_id	INT

		SELECT
			@lang_id	= 2
		*/



			-- declareción de variables para obtener los datos del cursor
			DECLARE
				@comp_id				INT,
				@task_id				INT,
				@bra_id					INT,
				@task_subject			NVARCHAR(MAX),
				@task_date4Begin		DATETIME,
				@task_date4End			DATETIME,
				@task_priority			INT,
				@task_desc				NVARCHAR(MAX),
				@cust_id				INT,
				@taskt_id				INT,
				@tast_id				INT,
				@user_id				INT,
				@task_advertiseDate		DATETIME,
				@task_advertiseCount	INT,
				@task_advertiseLastDate	DATETIME,
				@bisIsAdvertiseLastDate BIT,
				@cust_name				NVARCHAR(200),
				@contact_name			NVARCHAR(200),
				@task_advertise_desc	NVARCHAR(200),
				@user_id4lastUpdate		INT



			-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
			DECLARE cursor_Task CURSOR LOCAL FAST_FORWARD FOR

				SELECT
					tct.comp_id,
					tct.task_id,
					tct.bra_id,
					tct.task_subject,
					tct.task_date4Begin,
					tct.task_date4End,
					tct.task_priority,
					CONVERT(NVARCHAR(MAX),tct.task_desc),
					tct.cust_id,
					tct.taskt_id,
					tct.tast_id,
					tct.[user_id],
					ISNULL(tct.task_advertiseDate, GETDATE()),
					tct.task_advertiseCount,
					tct.task_advertiseLastDate,
					CASE
						WHEN tct.task_advertiseDate IS NULL THEN	'False'
						ELSE										'True'
					END,
					ISNULL(tc.cust_name,''),
					ISNULL(tc2.contact_name,'')	,
					ISNULL(tct.task_advertise_desc,'')
				FROM tbCRM_Task tct						WITH (NOLOCK)
				INNER JOIN tbBranch tb					WITH (NOLOCK)
					ON	tb.comp_id	= tct.comp_id AND
						tb.bra_id	= tct.bra_id
				INNER JOIN tbCRM_TaskStatus tcts		WITH (NOLOCK)
					ON	tcts.comp_id			= tct.comp_id	AND
						tcts.tast_id			= tct.tast_id	AND
						tcts.tast_isFinalStatus = 'False'
				LEFT JOIN tbCustomer				tc	WITH (NOLOCK)
					ON	tc.comp_id	= tct.comp_id	AND
						tc.cust_id	= tct.cust_id
				LEFT JOIN tbContact						tc2	WITH (NOLOCK)
					ON	tc2.comp_id		= tct.contact_id	AND
						tc2.contact_id	= tct.contact_id
				WHERE	tct.task_advertiseDate IS NOT NULL
							OR
						(	tb.bra_processingDate = tct.task_nextReviewdate AND
						   (tct.task_nextReviewdateLastMailDate IS NULL
								OR
							tct.task_nextReviewdateLastMailDate < tct.task_nextReviewdate
						   )
						)

				--where tct.task_id = 412

			OPEN	cursor_Task


			-- lectura anticipada del cursor
			FETCH	cursor_Task
			INTO
				@comp_id				,
				@task_id				,
				@bra_id					,
				@task_subject			,
				@task_date4Begin		,
				@task_date4End			,
				@task_priority			,
				@task_desc				,
				@cust_id				,
				@taskt_id				,
				@tast_id				,
				@user_id				,
				@task_advertiseDate		,
				@task_advertiseCount	,
				@task_advertiseLastDate ,
				@bisIsAdvertiseLastDate,
				@cust_name,
				@contact_name,
				@task_advertise_desc


			-- se recorre el cursor hasta el fin del mismo
			WHILE   @@FETCH_STATUS = 0
			BEGIN

				--ACA PROCESAMOS Y AVISAMOS


				-- Si hay una imagen la corta para que no explote el mail
				IF @task_desc LIKE '%img src="data:image%'
					BEGIN
						SET @task_desc = dbo.fnStrStripHTML(@task_desc)
						SET @task_desc = SUBSTRING(@task_desc,1,3000) + '<br/><br/> <b> El texto no está completo, visualizar en el sistema. <br/> The text is not complete, visualize in the system. </b>'
					END

				-- Si es muy larga la corta para que no explote el mail
				IF LEN(@task_desc) > 3000
					BEGIN
						SET @task_desc = SUBSTRING(@task_desc,1,3000) + '<br/><br/> <b> El texto no está completo, visualizar en el sistema. <br/> The text is not complete, visualize in the system. </b>'
					END



					--SI EL COUNT ES DISTINTO DE NULL, SUMAMOS 1 Y SETEAMOS EN NULL
					--LA FECHA DE AVISO SI ES MENOR O IGUAL A LA FECHA ACTUAL
					IF (@task_advertiseCount IS NOT NULL) AND (@task_advertiseDate <= GETDATE())

						BEGIN

							DECLARE @lang_id	INT
							SELECT  @lang_id = tb.lang_id
								FROM tbBranch tb		WITH (NOLOCK)
								WHERE	tb.comp_id	= @comp_id AND
										tb.bra_id	= @bra_id


							-- Si tiene Fecha de Advertencia la borro e incremento en UNO las advertencias informadas.
							IF @bisIsAdvertiseLastDate = 'True'
								BEGIN
									UPDATE tbCRM_Task	WITH (ROWLOCK)
									SET
										task_advertiseDate		= NULL,
										task_advertiseCount		= task_advertiseCount + 1
									WHERE	comp_id = @comp_id AND
											task_id = @task_id
								END



							-- -------------------------------------------------------
							-- Enviamos EMAils en caso de corresponder
							-- -------------------------------------------------------
							DECLARE @return_value NVARCHAR(MAX)
							DECLARE @auxParameter AS INT = @lang_id * -1
							EXEC	spCRM_Task_sendEmail @comp_id, @return_value, @auxParameter
							-- -------------------------------------------------------

							DECLARE @strSubject AS NVARCHAR(200) = ''
							SELECT  @strSubject = tt.task_subject
								FROM  tbCRM_Task tt
								WHERE	comp_id = @comp_id AND
										task_id = @task_id





							--ACTUALIZAMOS LA FECHA DE AVISO
							UPDATE tbCRM_Task
								SET

									task_advertiseLastDate = GETDATE(),
									task_nextReviewdateLastMailDate =	CASE
																			WHEN task_nextReviewdate IS NULL THEN NULL
																			WHEN task_nextReviewdate <= GETDATE() THEN GETDATE()
																			ELSE task_nextReviewdate
																		END
								WHERE	comp_id = @comp_id AND
										task_id = @task_id

							DECLARE @strURL AS NVARCHAR(600)
							SET @strURL = 'wfmCRM_TaskDetail.aspx?&BraId='	+ CONVERT(VARCHAR,@bra_id)	+
																'&TaskId='	+ CONVERT(VARCHAR,@task_id) +
																'&Action='  + 'U'						+ '&'



							DELETE FROM tbWorkflow	WITH (ROWLOCK)
								WHERE	comp_id = @comp_id	AND
										bra_id	= @bra_id	AND
										wf_type = 777		AND
										task_id = @task_id	AND
										wf_isProcessed = 'False'


							--GRABAMOS WORKFLOW
							INSERT INTO tbWorkflow
							(
								comp_id,
								bra_id,
								wf_type,
								wf_isProcessed,
								user_id_from,
								user_id_assigned,
								user_id_processed,
								prof_id_assigned,
								wf_dateOfAssigned,
								wf_dateOfProcessing,
								wf_link,
								wf_message1,
								wf_message2,
								wf_htmlTop,
								wf_htmlBody,
								wf_html_Bottom,
								task_id
							)
							VALUES
							(
								@comp_id,
								@bra_id,
								777,
								'False',
								NULL,
								@user_id, --@intUser4Notify,
								NULL,
								NULL,
								GETDATE(),
								NULL,
								@strURL,
								@strSubject,
								@task_advertise_desc,
								'', --@strRet_ErrorDescription,
								'',
								'',
								@task_id
							)

						END


				-- próxima lectura del cursor
				FETCH	cursor_Task
				INTO
					@comp_id				,
					@task_id				,
					@bra_id					,
					@task_subject			,
					@task_date4Begin		,
					@task_date4End			,
					@task_priority			,
					@task_desc				,
					@cust_id				,
					@taskt_id				,
					@tast_id				,
					@user_id				,
					@task_advertiseDate		,
					@task_advertiseCount	,
					@task_advertiseLastDate ,
					@bisIsAdvertiseLastDate	,
					@cust_name				,
					@contact_name,
					@task_advertise_desc

			END

			CLOSE cursor_Task
			DEALLOCATE cursor_Task

	END
GO




CREATE  PROCEDURE spCRM_Task_SetCompliance
(
	@comp_id							INT,
	@task_id							INT,
	@task_customerCompliance_note		NVARCHAR(4000),
	@cust_id							INT
)
AS

BEGIN

	SET NOCOUNT ON

	-- Solo pone la conformidad del cliente si la tarea esta asignada al cliente logeado actualmente.!!!
	IF @cust_id <> (
						SELECT tct.cust_id
							FROM tbCRM_Task tct		WITH (NOLOCK)
							WHERE	tct.comp_id = @comp_id AND
									tct.task_id = @task_id
					)
		BEGIN
			RETURN 'False'
		END



	UPDATE tbcrm_Task
		SET task_customerCompliance_isOK	= 'True',
			task_customerCompliance_cust_Id = @cust_id,
			task_customerCompliance_cd		= GETDATE(),
			task_customerCompliance_note	= @task_customerCompliance_note
		WHERE	comp_id = @comp_id AND
				task_id = @task_id

	RETURN 'True'


END
GO

CREATE PROCEDURE [dbo].[spCRM_Task_SupportRequest_GetData4Grid]
(
	@comp_id	INT,
	@cust_id	INT,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@taskt_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'



		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@cust_id	INT,
				@datefrom	DATETIME,
				@dateto		DATETIME,
				@taskt_id	INT

			SELECT
				@comp_id	= 1,
				@cust_id	= 24288,
				@datefrom	= '2017-01-01',
				@dateto		= '2017-01-31',
				@taskt_id	= -1
		*/
		-- ----------------------------------------------

		SELECT
			' ' [ ],	--REPORTE
			' ' [ ],	--AGREGAR NOTAS
			--' ' [ ],	--CALIFICACION
			' ' [ ],	--VER DETALLES DEL TICKET
			tct.task_id													[ticketID],
			tov.optval_desc												[task_resolutionCustomerCompliance_Calification],
			tct.task_subject,
			tcts.tast_desc												[Estado],
			ISNULL(tct.task_IFAvailableInVersion,0)						[AvailableInVersion],
			tct.task_date4Begin,
			tctt.taskt_desc,
			tct.task_customerCompliance_note,
			tct.task_emailAdditional,
			ISNULL(tuAssigned.user_lastname,'*')   + ', ' + ISNULL(tuAssigned.user_firstname,'*')		[tuAssigned],
			ISNULL(tuLastUpdate.user_lastname,'*') + ', ' + ISNULL(tuLastUpdate.user_firstname,'*')		[tuLastUpdate],
			tct.task_lastUpdate																			[lastUpdateDate],
			ISNULL(tuResolution.user_lastname,'*') + ', ' + ISNULL(tuResolution.user_firstname,'*')		[tuResolution],
			tct.task_date4Resolution																	[resolutionDate],
			tct.task_id													[ID]
			FROM tbCRM_Task												tct		WITH(NOLOCK)
				INNER JOIN tbCRM_TaskType								tctt	WITH(NOLOCK)
					ON	tctt.taskt_id	= tct.taskt_id					AND
						tctt.comp_id	= tct.comp_id
				LEFT JOIN tbsysOptionsValues							tov		WITH(NOLOCK)
					ON	tov.lang_id			= 2							AND
						tov.optval_class	= 696						AND
						tov.optval_id		= tct.task_resolutionCustomerCompliance_Calification
				INNER JOIN tbCRM_TaskStatus tcts								WITH(NOLOCK)
					ON	tcts.comp_id = tct.comp_id AND
						tcts.tast_id = tct.tast_id
				LEFT JOIN tbUser tuAssigned										WITH(NOLOCK)
					ON	tuAssigned.[user_id] = tct.[user_id]
				LEFT JOIN tbUser tuLastUpdate									WITH(NOLOCK)
					ON	tuLastUpdate.[user_id] = tct.user_id_lastUpdate
				LEFT JOIN tbUser tuResolution									WITH(NOLOCK)
					ON	tuResolution.[user_id] = tct.user_id4Resolution

			WHERE	tct.comp_id			= @comp_id						AND
					tct.cust_id			= @cust_id						AND
					tct.task_date4Begin BETWEEN @datefrom AND @dateto	AND
					tct.taskt_id IN (7,8,9,12)
					--(	@taskt_id			= -1 /*AND tct.taskt_id IN (7,8,9)*/ OR
					--	tct.taskt_id		= @taskt_id
					--)

			ORDER BY tct.task_id DESC

	END
GO

CREATE PROCEDURE [dbo].[spCRM_Task_SupportRequest_InsertData]
(
	@comp_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@cust_id				INT,
	@taskt_id				INT,
	@user_name				NVARCHAR(500),
	@task_date4Begin		DATETIME,
	@task_image				IMAGE,
	@lang_id				INT,
	@task_subject			NVARCHAR(200),
	@task_desc				NTEXT,
	@task_emailAdditional	NVARCHAR(250),
	@user_id_4SupportCreator	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@bra_id					INT,
				@task_subject			VARCHAR(500),
				@task_date4Begin		DATETIME,
				@user_id				INT,
				@task_desc				VARCHAR(1000),
				@cust_id				INT,
				@taskt_id				INT,
				@task_emailAdditional	VARCHAR(1000),
				@task_image				IMAGE
		*/
		-- ---------------------------------------------

		--MARTIN, EL BRA_ID lo pase en el código VB con 1 en duro, donde iría la descripción del nombre y apellido del usuario????

		DECLARE @return_value	INT
		SET		@return_value	= -1

		INSERT INTO tbCRM_Task	  WITH (ROWLOCK)
		(
			comp_id,
			bra_id,
			task_subject,
			task_date4Begin,
			task_date4End,
			[user_id],
			task_desc,
			cust_id,
			taskt_id,
			tast_id,
			task_emailAdditional,
			task_image,
			task_advertiseDate,
			task_customerCompliance_note,
			task_resolution,
			task_nextReviewdate,
			soh_Bra_id,
			soh_soh_id,
			task_price,
			Task_price2,
			Task_price3,
			curr_id,
			task_priority,
			user_id_4SupportCreator,
			task_customerCompliance_cd,
			user_id_Creator
		)
		VALUES
		(
			@comp_id,
			@bra_id,
			@task_subject,
			GETDATE()/*@task_date4Begin*/,
			DATEADD(DAY,
						CASE
							WHEN @taskt_id = 7 THEN 5			--200
							WHEN @taskt_id = 8 THEN	60			--205
							WHEN @taskt_id = 9 THEN	15			--210
							ELSE 3
						END
						, @task_date4Begin),
			@user_id,
			@task_desc,
			@cust_id,
			@taskt_id,
			21/*  En duro, es el estado inicial en nuestro sistema*/,
			@task_emailAdditional,
			@task_image,
			DATEADD(DAY, 2, @task_date4Begin),
			@user_name,
			'',
			DATEADD(DAY, 2, @task_date4Begin),
			0,
			0,
			0,
			0,
			0,
			1,
			5,
			@user_id_4SupportCreator,
			GETDATE(),
			@user_id
		)

		SET	   @return_value = IDENT_CURRENT('tbCRM_Task') --' @@IDENTITY

		SELECT @return_value






	-- -------------------------------------------------------
	-- Enviamos EMAils en caso de corresponder
	-- -------------------------------------------------------
	EXEC spCRM_Task_sendEmail @comp_id, @return_value, @lang_id
	-- -------------------------------------------------------




	---- -----------------------------------------------------------------------------------------
	---- Envio de Mail
	---- -----------------------------------------------------------------------------------------
	--declare
	--	@message			 varchar(4000),
	--	@subject			 varchar(4000),
	--	@body				 varchar(4000),
	--	@mail				 varchar(8000),
	--	@user_origen_name	 varchar(400),
	--	@user_mail_origin	 varchar(400),
	--	@optionid			 int,
	--	@desc				 varchar(2000),
	--	@tast_id			 INT,
	--	@task_date4End		 DATE



	--SET @task_date4End = DATEADD(DAY, 2, @task_date4Begin)


	----Datos del Usuario de Origen
	--select
	--	@user_origen_name		= (tu.user_lastname + ',' + tu.user_firstname),
	--	@user_mail_origin		= tu.user_email
	--	from	tbUser tu
	--	where	tu.[user_id]	= @user_id

	--set @optionid = 3583
	--SET @tast_id  = 21

	---- ---------------------------------------
	---- Datos del Cliente
	--DECLARE @strCustomer AS NVARCHAR(200)
	--SET @strCustomer = ''
	--SELECT
	--	@strCustomer = tc.cust_name
	--	FROM tbCustomer					tc
	--	WHERE	tc.comp_id = @comp_id	AND
	--			tc.cust_id = @cust_id

