CREATE PROCEDURE spCRM_Task_SupportRequestGetDataByIDWithNotes
(
	@comp_id	INT,
	@task_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------
		-- TESTING
		-- --------------------------
		/*
			DECLARE
				@comp_id	INT,
				@task_id	INT
		*/
		-- --------------------------

		--DEVUELVO SUBJECT Y RESOLUCION
		SELECT
			tct.task_id,
			tct.task_subject,
			tct.task_resolution,
			tct.task_date4Begin,
			tct.task_date4End,
			tct.task_desc,
			ISNULL(tu.user_lastname,'') + ',' + ISNULL(tu.user_firstname,'') [UserCreator]
		FROM tbCRM_Task AS tct
		LEFT JOIN tbUser AS tu
		ON tu.[user_id] = tct.[user_id]
		WHERE tct.comp_id = @comp_id AND tct.task_id = @task_id

		--DEVUELVO LAS NOTAS
		SELECT
			tctn.comp_id,
			tctn.tasknote_id,
			tctn.tasknote_Subject,
			tctn.tasknote_Note
			FROM tbCRM_TaskNote AS			tctn
			WHERE	tctn.comp_id = @comp_id	AND
					tctn.task_id = @task_id

	END



GO

CREATE PROCEDURE [dbo].[spCRM_Task_UpdateAvailableInVersion]
(
	@comp_id	INT,
	@Version	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------
		-- TESTING
		-- -------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@Version	INT
			SELECT
				@comp_id	= 1,
				@Version	= 121321321
		*/
		-- -------------------------------------






		UPDATE tbCRM_Task
		SET
			task_IFAvailableInVersion = @Version
			FROM tbCRM_Task															tct		WITH(NOLOCK)
			INNER JOIN tbCRM_TaskStatus												tcts	WITH(NOLOCK)
			ON	tcts.comp_id								= tct.comp_id			AND
				tcts.tast_id								= tct.tast_id
			WHERE	tct.comp_id								= @comp_id 				AND
					tct.taskt_id							IN (1,2,8,9)		AND		-- (1,2,205,210)
					(tcts.tast_isFinalStatus					= 'True' OR tcts.tast_id = 58)				AND
					ISNULL(tct.task_IFAvailableInVersion,0) = 0

	END


GO


CREATE PROCEDURE [dbo].[spCRM_Task_updateData]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@lang_id			INT,
	@task_id			INT,
	@task_subject		NVARCHAR(200),
	@task_date4Begin	DATETIME,
	@task_date4End		DATETIME,
	@task_priority		INT,
	@task_desc			ntext,
	@case_id			INT,
	@soh_Bra_id			INT,
	@soh_soh_id			INT,
	@cust_id			INT,
	@contact_id			INT,
	@tast_id			INT,
	@task_price			decimal(19,4),
	@curr_id			int,
	@chkCA				bit,
	@taskt_id			INT,
	@task_emailAdditional VARCHAR(250),
	@task_resolution	NVARCHAR(4000),
	@supp_id			INT,
	@task_nextReviewdate DATETIME,
	@lastUserID			INT

)
AS

--return
--SELECT 1 / 0

-- --------------------------------------
-- TESTING
-- --------------------------------------
/*
declare
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@lang_id			INT,

	@task_id			INT,
	@task_subject		NVARCHAR(200),
	@task_date4Begin	DATETIME,
	@task_date4End		DATETIME,
	@task_priority		INT,
	@task_desc			NVARCHAR(4000),
	@case_id			INT,
	@soh_Bra_id			INT,
	@soh_soh_id			INT,
	@cust_id			INT,
	@contact_id			INT,
	@tast_id			INT,
	@task_price			decimal(19,4),
	@curr_id			int,
	@chkCA				bit
*/
-- --------------------------------------

BEGIN


	SET NOCOUNT ON





			-- INserta HIstorial
			INSERT INTO tbCRM_TaskHistory
			(
				comp_id,
				task_id,
				bra_id,
				task_subject,
				task_date4Begin,
				task_date4End,
				task_priority,
				[user_id],
				task_desc,
				case_id,
				soh_Bra_id,
				soh_soh_id,
				cust_id,
				contact_id,
				tast_id,
				taskh_cd,
				taskt_id,
				task_price,
				curr_id,
				task_resolution,
				user_id_lastUpdate,
				task_lastUpdate,
				user_id4lastUpdate
			)
			SELECT
				tct.comp_id,
				tct.task_id,
				tct.bra_id,
				tct.task_subject,
				tct.task_date4Begin,
				tct.task_date4End,
				tct.task_priority,
				tct.[user_id],
				tct.task_desc,
				tct.case_id,
				tct.soh_Bra_id,
				tct.soh_soh_id,
				tct.cust_id,
				tct.contact_id,
				tct.tast_id,
				GETDATE(),
				taskt_id,
				task_price,
				curr_id,
				task_resolution,
				@user_id,
				GETDATE(),
				@lastUserID

			FROM tbCRM_Task tct
			WHERE	tct.comp_id = @comp_id AND
					tct.task_id = @task_id



	DECLARE @intLastUserAssigned AS INT = NULL
	SELECT	@intLastUserAssigned =  tct.[user_id]
	    FROM tbCRM_Task tct		WITH (NOLOCK)
	    WHERE	tct.comp_id = @comp_id AND
	            tct.task_id = @task_id




	--IF @user_id <> @intLastUserAssigned
	--	BEGIN
	--		SET @task_nextReviewdate = GETDATE()
	--	END


	IF @cust_id = -1
		BEGIN
			SET @cust_id = NULL
		END
	IF @contact_id = -1
		BEGIN
			SET @contact_id = NULL
		END
	IF @supp_id = -1
		BEGIN
			SET @supp_id = NULL
		END


	-- Si NO tiene nada ingresado y un pedido lo modificó mientras lko estaban modificando, deja el ultimo pedido asociado.
	SELECT
			@soh_Bra_id =	CASE
								WHEN @soh_Bra_id = 0 AND tct.soh_Bra_id > 0 THEN tct.soh_Bra_id
								ELSE @soh_Bra_id
							END	,
			@soh_soh_id = CASE
								WHEN @soh_soh_id = 0 AND tct.soh_soh_id > 0 THEN tct.soh_soh_id
								ELSE @soh_soh_id
							END
		FROM tbCRM_Task tct		WITH (NOLOCK)
		WHERE	tct.comp_id = @comp_id AND
				tct.task_id = @task_id




	UPDATE	tbCRM_Task		WITH (ROWLOCK)
	SET		bra_id					= @bra_id,
			task_subject			= @task_subject,
			task_date4Begin			= @task_date4Begin,
			task_date4End			= @task_date4End,
			task_priority			= @task_priority,
			[user_id]				= @user_id,
			task_desc				= @task_desc,
			case_id					= @case_id,
			soh_Bra_id				= @soh_Bra_id,
			soh_soh_id				= @soh_soh_id,
			cust_id					= @cust_id,
			contact_id				= @contact_id,
			tast_id					= @tast_id,
			task_price				= @task_price,
			curr_id					= @curr_id,
			taskt_id				= @taskt_id,
			task_emailAdditional	= @task_emailAdditional,
			task_resolution			= @task_resolution,
			task_secondUpdate		= 'False',
			supp_id					= @supp_id,
			task_nextReviewdate		= @task_nextReviewdate,
			user_id_Last			= @intLastUserAssigned,
			user_id_Creator			=	CASE
											WHEN user_id_Creator IS NOT NULL THEN user_id_Creator
											ELSE							      @user_id
										END,
			task_lastUpdate			= GETDATE() ,
			user_id4lastUpdate		= @lastUserID


			--user_id_lastUpdate		= @user_id




	WHERE	comp_id			= @comp_id
	AND		task_id			= @task_id




	-- ----------------------------------------------------------
	-- ACTUALIZAMOS SALE ORDER
	-- ----------------------------------------------------------
	if (@chkCA = 'False')
		begin
			declare
					@soss_id		INT
			select
					@soss_id		= ssos_id
			from tbSaleOrderHeader				tsoh
			where	tsoh.comp_id	= @comp_id
			and		tsoh.bra_id		= @bra_id
			and		tsoh.soh_id		= @soh_soh_id

			if (@soss_id = 10)
				begin
					update tbSaleOrderHeader	WITH (ROWLOCK)
					SET
							ssos_id		= 20
					where	comp_id		= @comp_id
					and		bra_id		= @bra_id
					and		soh_id		= @soh_soh_id
				end
		end
	-- ----------------------------------------------------------





	-- -------------------------------------------------------
	-- Enviamos EMAils en caso de corresponder
	-- -------------------------------------------------------
	EXEC spCRM_Task_sendEmail @comp_id, @task_id, @lang_id
	-- -------------------------------------------------------



	-- Saca del WorkFlow lo que haya de esta tarea.
	UPDATE tbWorkflow
		SET		wf_isProcessed		= 'True',
				wf_dateOfProcessing = GETDATE()
		WHERE	comp_id			= @comp_id AND
				task_id			= @task_id AND
				wf_isProcessed	= 'False'



	-- -------------------------------------------------------
	-- Carga en workFlow
	-- -------------------------------------------------------
	IF EXISTS(
				SELECT 1
					FROM tbCRM_TaskStatus tcts
					WHERE	tcts.comp_id				= @comp_id AND
							tcts.tast_id				= @tast_id AND
							tcts.tast_assign2workFlow	= 1
			)
		AND
		@user_id <> @intLastUserAssigned
		BEGIN



			DECLARE @strSubject AS NVARCHAR(200) = ''
			SELECT  @strSubject = tt.task_subject
				FROM  tbCRM_Task tt
				WHERE	comp_id = @comp_id AND
						task_id = @task_id

			DECLARE @strURL AS NVARCHAR(600)
			SET @strURL = 'wfmCRM_TaskDetail.aspx?&BraId='	+ CONVERT(VARCHAR,@bra_id)	+
												'&TaskId='	+ CONVERT(VARCHAR,@task_id) +
												'&Action='  + 'U'						+ '&'

			--GRABAMOS WORKFLOW
			INSERT INTO tbWorkflow
			(
				comp_id,
				bra_id,
				wf_type,
				wf_isProcessed,
				user_id_from,
				user_id_assigned,
				user_id_processed,
				prof_id_assigned,
				wf_dateOfAssigned,
				wf_dateOfProcessing,
				wf_link,
				wf_message1,
				wf_message2,
				wf_htmlTop,
				wf_htmlBody,
				wf_html_Bottom,
				task_id
			)
			VALUES
			(
				@comp_id,
				@bra_id,
				778,
				'False',
				NULL,
				@user_id, --@intUser4Notify,
				NULL,
				NULL,
				GETDATE(),
				NULL,
				@strURL,
				@strSubject,
				'',
				'', --@strRet_ErrorDescription,
				'',
				'',
				@task_id
			)

		END
		-- -------------------------------------------------------













END
GO


CREATE PROCEDURE spCRM_Task_UpdateSupportRequestCalification
(
	@comp_id				INT,
	@bra_id					INT,
	@task_id				INT,
	@SupportCalification	INT,
	@SupportCalifNote		NVARCHAR(4000)
)
AS
	BEGIN
		SET NOCOUNT ON

		UPDATE tbCRM_Task
		SET
			task_resolutionCustomerCompliance_Calification	= @SupportCalification,
			task_resolutionCustomerCompliance_Note			= @SupportCalifNote

		WHERE	comp_id = @comp_id	AND
				task_id = @task_id
	END
GO


CREATE PROCEDURE [dbo].[spCRM_Task_userByType_GetDataById]
(
	@comp_id	INT,
	@ws_id		UNIQUEIDENTIFIER,
	@bra_id		INT,
	@taskt_id	INT,
	@cust_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@ws_id		UNIQUEIDENTIFIER,
				@bra_id		INT,
				@taskt_id	INT,
				@cust_id	INT

			DECLARE
				@comp_id	= 1,
				@ws_id		= '',
				@bra_id		= 1,
				@taskt_id	= 1,
				@cust_id	= 1
		*/
		-- ------------------------------------------------


		SELECT
			tctubt.comp_id,
			tctubt.tbwst_id,
			tctubt.bra_id,
			tctubt.taskt_id,
			tctubt.user_id,
			tctubt.cust_id,
			tctubt.isDisabled,
			tctubt.days4Review,
			CASE tctubt.cust_id
				WHEN NULL THEN	0
				ELSE			1
			END									[Order]
			FROM tbCRM_Task_userByType			tctubt		WITH (NOLOCK)
			WHERE	tctubt.comp_id	= @comp_id	AND
					tctubt.ws_id	= @ws_id	AND
					tctubt.bra_id	= @bra_id	AND
					tctubt.taskt_id	= @taskt_id	AND
					(
						tctubt.cust_id	= @cust_id OR
						tctubt.cust_id  IS NULL
					)

			ORDER BY [Order] DESC


	END

GO

