CREATE PROCEDURE [dbo].[spCRM_TaskNote_HasMustCheckNotesPending]
(
	@comp_id	INT,
	@task_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------
		-- TESTING
		-- ----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@task_id	INT
			SELECT
				@comp_id	= 1,
				@task_id	= 1213
		*/
		-- ----------------------------------------

		-- ----------------------------------------
		-- VARIABLE DE TRABAJO
		-- ----------------------------------------
		DECLARE
			@bitHasMustCheckNotesPending	BIT
		SET @bitHasMustCheckNotesPending	= 'False'
		-- ----------------------------------------

		IF (
			SELECT
				COUNT(*)
			FROM tbCRM_TaskNote										tctn
				INNER JOIN tbCRM_TaskNoteType						tctnt
				ON	tctnt.comp_id				= tctn.comp_id		AND
					tctnt.tasknotet_id			= tctn.tasknotet_id
			WHERE	tctnt.comp_id				= @comp_id			AND
					tctn.task_id				= @task_id			AND
					tctn.tasknote_isChecked		= 'False'			AND
					tctnt.tasknotet_mustCheck	= 'True')	> 0
			BEGIN
				SET @bitHasMustCheckNotesPending = 'True'
			END
		ELSE
			BEGIN
				SET @bitHasMustCheckNotesPending = 'False'
			END

		SELECT @bitHasMustCheckNotesPending	[HasMustCheckNotesPending]

	END

GO

CREATE PROCEDURE [dbo].[spCRM_TaskNote_UpdateAdditionalData]
(
	@comp_id								INT,
	@tasknote_id							INT,
	@tasknotet_id							INT,
	@tasknote_isChecked						BIT,
	@tasknotet_iso_origen					NVARCHAR(4000),
	@tasknotet_iso_analisisCausa			NVARCHAR(4000),
	@tasknotet_iso_accionInmediata			NVARCHAR(4000),
	@tasknotet_iso_accionCorrectiva			NVARCHAR(4000),
	@tasknotet_iso_user_id_resp				INT,
	@tasknotet_iso_plazoResolucion			DATETIME,
	@tasknotet_iso_verificaEficacia			NVARCHAR(4000),
	@tasknotet_iso_verificaEficaciaDate		DATETIME,
	@user_id								INT
)
AS
	BEGIN
		SET NOCOUNT ON

		IF @tasknotet_id = -1
			BEGIN
				SET @tasknotet_id = NULL
			END

		IF @tasknotet_iso_user_id_resp = -1
			BEGIN
				SET @tasknotet_iso_user_id_resp = NULL
			END


		UPDATE tbCRM_TaskNote
		SET
			tasknotet_id						= @tasknotet_id,
			tasknotet_iso_origen				= @tasknotet_iso_origen,
			tasknotet_iso_analisisCausa			= @tasknotet_iso_analisisCausa,
			tasknotet_iso_accionInmediata		= @tasknotet_iso_accionInmediata,
			tasknotet_iso_accionCorrectiva		= @tasknotet_iso_accionCorrectiva,
			tasknotet_iso_user_id_resp			= @tasknotet_iso_user_id_resp,
			tasknotet_iso_plazoResolucion		= @tasknotet_iso_plazoResolucion,
			tasknotet_iso_verificaEficacia		= @tasknotet_iso_verificaEficacia,
			tasknotet_iso_verificaEficaciaDate	= @tasknotet_iso_verificaEficaciaDate,
			tasknote_isChecked_user_id			=
												CASE
													WHEN	(tasknote_isChecked_user_id IS NULL OR tasknote_isChecked = 'False') AND @tasknote_isChecked = 'True'  THEN  @user_id
													ELSE																												 tasknote_isChecked_user_id
												END,
			tasknote_isCheckedDate				=
												CASE
													WHEN	(tasknote_isChecked_user_id IS NULL OR tasknote_isChecked = 'False') AND @tasknote_isChecked = 'True'  THEN  GETDATE()
													ELSE																												 tasknote_isCheckedDate
												END,
			tasknote_isChecked					= @tasknote_isChecked
			WHERE	comp_id		= @comp_id AND
					tasknote_id = @tasknote_id
	END
GO


create PROCEDURE [dbo].[spCRM_TaskNote_UpdateTaskRelated]
(
	@comp_id								INT,
	@tasknote_id							INT,
	@task_id_related						INT

)
AS
	BEGIN
		SET NOCOUNT ON

		IF @task_id_related = -1
