	END
GO

CREATE PROCEDURE spCRM_TaskNoteMask_InsertAllNotes
(
	@comp_id	INT,
	@bra_id		INT,
	@user_id	INT,
	@prof_id	INT,
	@task_id	INT,
	@taskt_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@user_id	INT,
				@prof_id	INT,
				@task_id	INT,
				@taskt_id	INT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@user_id	= 132,
				@prof_id	= 1,
				@task_id	= 1,
				@taskt_id	= 3
		*/
		-- -----------------------------------------
		INSERT INTO tbCRM_TaskNote
		(
			comp_id,
			task_id,
			[user_id],
			prof_id,
			tasknote_cd,
			tasknote_PDF,
			tasknote_Price,
			tasknote_Subject,
			tast_id,
			tasknote_Note,
			tasknote_qtyHour,
			tasknote_qtyMinutes,
			tasknotet_id,
			tasknote_isChecked
		)
		SELECT
			tctnm.comp_id,
			@task_id,
			@user_id,
			@prof_id,
			GETDATE(),
			NULL,
			0,
			tctnm.tasknote_Subject,
			NULL,
			tctnm.tasknote_Note,
			0,
			0,
			tctnm.tasknotet_id,
			'False'
			FROM tbCRM_TaskNoteMask				tctnm
			WHERE	tctnm.comp_id	= @comp_id	AND
					tctnm.bra_id	= @bra_id	AND
					tctnm.taskt_id	= @taskt_id
			ORDER BY tctnm.tnm_order ASC
	END
GO






