CREATE PROCEDURE [dbo].[spCRM_TaskNotes_GetDataByFilters]
(
	@comp_id										INT,
	@lang_id										INT,
	@bra_id											INT,
	@prof_id										INT,
	@user_id										INT,
	@task_id										INT
)

AS



BEGIN


-- --------------------------------------
-- Testing
-- --------------------------------------
/*
	DECLARE
				@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@prof_id				INT,
				@user_id				INT,
				@task_id				INT

	SELECT
				@comp_id				= 1,
				@lang_id				= 2,
				@bra_id					= 1,
				@prof_id				= 1,
				@user_id				= 3,
				@task_id				= 1697
*/
-- --------------------------------------


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	SELECT	' '															[ ],
			' '															[ ],
			CASE
				WHEN tctnt.tasknotet_mustCheck = 'True' AND tctn.tasknote_isChecked = 'True'  THEN 'OK'
				WHEN tctnt.tasknotet_mustCheck = 'True' AND (tctn.tasknote_isChecked = 'False' OR tctn.tasknote_isChecked IS NULL) THEN 'Pend'
				ELSE																			   ''  --'N/A'
			END															[tasknote_isChecked] ,
			CASE
				WHEN tu2.[user_id] IS NULL THEN	''
				ELSE							tu2.user_lastname + ', ' + tu2.user_firstname
			END															[UserName_Check],
			tctn.tasknote_isCheckedDate									[tasknote_isCheckedDate],
			tctn.tasknote_isCheckedLimitDate							[tasknote_isCheckedLimitDate],



			ISNULL(tcts.tast_desc,'-')									[tast_desc],
			ISNULL(tctn.tasknote_Subject,'')							[tasknote_Subject],

			CASE
				WHEN tu.[user_id] IS NULL THEN	''
				ELSE							tu.user_lastname + ', ' + tu.user_firstname
			END															[User_Name],
			tctn.tasknote_cd											[tasknote_cd],
			--ISNULL(tctn.tasknote_Note,'')								[note1],

			ISNULL(tctn.tasknote_Price,0)								[tasknote_Price],
			ISNULL(tctn.tasknote_qtyHour,0)								[tasknote_qtyHour],
			tctn.task_id_related,

			tctn.tasknote_id											[ID]

	FROM tbCRM_TaskNote									tctn						WITH (NOLOCK)

		INNER JOIN tbCRM_Task							tct							WITH (NOLOCK)
		ON  tct.comp_id		= tctn.comp_id AND
			tct.task_id		= tctn.task_id

		LEFT JOIN tbUser								tu							WITH (NOLOCK)
		ON  tu.[user_id]	= tctn.[user_id]

		LEFT JOIN tbUser								tu2							WITH (NOLOCK)
			ON tu2.[user_id]
							= tctn.tasknote_isChecked_user_id

		LEFT JOIN tbProfile								tp							WITH (NOLOCK)
		ON  tp.comp_id		= tctn.comp_id AND
			tp.prof_id		= tctn.prof_id

		LEFT JOIN tbCRM_TaskStatus						tcts						WITH (NOLOCK)
			ON	tcts.comp_id = tctn.comp_id AND
				tcts.tast_id = tctn.tast_id

		LEFT JOIN tbCRM_TaskNoteType					tctnt						WITH (NOLOCK)
			ON	tctnt.comp_id		= tctn.comp_id			AND
				tctnt.tasknotet_id	= tctn.tasknotet_id

		--LEFT JOIN tbCRM_TaskNoteMask					tctnm						WITH (NOLOCK)
		--	ON	tctnm.comp_id		= tctnt.comp_id AND
		--		tctnm.tasknotet_id	= tctnt.tasknotet_id

	WHERE	tctn.comp_id			= @comp_id					AND
			tctn.task_id			= @task_id					--AND
			--tctn.prof_id			= @prof_id


	ORDER BY tctn.tasknote_isCheckedLimitDate, tctn.tasknote_id -- tctn.tasknote_cd desc



END


GO



CREATE PROCEDURE [dbo].[spCRM_TaskNotes_GetDataById]
(
	@comp_id										INT,
	@tasknote_id									INT
)

AS
	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------
		-- Testing
		-- --------------------------------------
		/*
			DECLARE
						@comp_id		INT,
						@tasknote_id	INT
			SELECT
						@comp_id		= 1,
						@tasknote_id	= 2
		*/
		-- --------------------------------------

		SELECT
			tctn.tasknote_id,
			tctn.task_id,
			tctn.[user_id],
			tctn.prof_id,
			tctn.tasknote_cd,
			isnull(tctn.tasknote_Note,'')[tasknote_Note],
			tct.task_subject,
			tct.task_desc,
			ISNULL(tu.user_nick,'')															[user_nick],
			ISNULL(tu.user_firstname,'')													[user_firstname],
			ISNULL(tu.user_lastname,'')														[user_lastname],
			tp.prof_desc,
			ISNULL(tu.user_lastname,'') + ', ' + ISNULL(tu.user_firstname,'')				[UserName],
			tctn.tasknote_PDF,
			ISNULL(tctn.tasknote_Price,0)													[tasknote_Price],
			ISNULL(tctn.tasknote_Subject,'')												[tasknote_Subject],
			ISNULL(tctn.tasknote_qtyHour,0)													[tasknote_qtyHour],
			ISNULL(tctn.tasknote_qtyMinutes,0)												[tasknote_qtyMinutes],
			tctn.tasknotet_id,
			ISNULL(tctn.tasknote_isChecked,'False')											[tasknote_isChecked],
			ISNULL(tctn.tasknotet_iso_origen,'')											[tasknotet_iso_origen],
			ISNULL(tctn.tasknotet_iso_analisisCausa,'')										[tasknotet_iso_analisisCausa],
			ISNULL(tctn.tasknotet_iso_accionInmediata,'')									[tasknotet_iso_accionInmediata],
			ISNULL(tctn.tasknotet_iso_accionCorrectiva,'')									[tasknotet_iso_accionCorrectiva],
			tctn.tasknotet_iso_user_id_resp,
			tctn.tasknotet_iso_plazoResolucion,
			ISNULL(tctn.tasknotet_iso_verificaEficacia,'')									[tasknotet_iso_verificaEficacia],
			tctn.tasknotet_iso_verificaEficaciaDate,
			ISNULL(tctn.task_id_related,-1)													[task_id_related],
			ISNULL(tctrelated.task_subject,'')												[task_related_note_Subject]



			FROM tbCRM_TaskNote						tctn		WITH (NOLOCK)

			left JOIN tbCRM_Task					tct			WITH (NOLOCK)
				ON  tct.comp_id		= tctn.comp_id	AND
					tct.task_id		= tctn.task_id

			left JOIN tbUser						tu			WITH (NOLOCK)
				ON  tu.[user_id]	= tctn.[user_id]

			LEFT JOIN tbProfile						tp			WITH (NOLOCK)
				ON  tp.comp_id		= tctn.comp_id	AND
					tp.prof_id		= tctn.prof_id

			LEFT JOIN tbCRM_Task					tctrelated	WITH (NOLOCK)
			ON	tctrelated.comp_id	= tctn.comp_id
			AND tctrelated.task_id	= tctn.task_id_related

			WHERE	tctn.comp_id		= @comp_id	AND
					tctn.tasknote_id	= @tasknote_id

	END


GO

CREATE PROCEDURE [dbo].[spCRM_TaskNotes_InsertData]
(
	@comp_id								INT,
	@task_id								INT,
	@user_id								INT,
	@prof_id								INT,
	@tasknote_cd							DATETIME,
