	@TaskNote_Subject						NVARCHAR(200),
	@tasknote_qtyHour						INT,
	@tasknote_qtyMinutes					INT,
	@tasknotet_id							INT,
	@tasknote_isChecked						BIT,
	@tasknotet_iso_origen					NVARCHAR(4000),
	@tasknotet_iso_analisisCausa			NVARCHAR(4000),
	@tasknotet_iso_accionInmediata			NVARCHAR(4000),
	@tasknotet_iso_accionCorrectiva			NVARCHAR(4000),
	@tasknotet_iso_user_id_resp				INT,
	@tasknotet_iso_plazoResolucion			DATETIME,
	@tasknotet_iso_verificaEficacia			NVARCHAR(4000),
	@tasknotet_iso_verificaEficaciaDate		DATETIME,
	@return_value							INT	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON


	IF DATALENGTH(@tasknote_Image) = 339 SET @tasknote_Image = NULL   -- POr si llega MIERDA mal generada por configurar cualquier MIERDA en SupportRequest, que no la guarde.

	--#STL29062018
	--Agregué los parámetros @tasknotet_id y @tasknote_isChecked (en la clase son OPCIONALES)
	IF @tasknotet_id = -1
		BEGIN
			SET @tasknotet_id = NULL
		END

	IF @tasknotet_iso_user_id_resp = -1
		BEGIN
			SET @tasknotet_iso_user_id_resp = NULL
		END

	INSERT INTO tbCRM_TaskNote
	(
		comp_id,
		-- tasknote_id -- this column value is auto-generated,
		task_id,
		[user_id],
		prof_id,
		tasknote_cd,
		tasknote_Note,
		tasknote_PDF,
		tasknote_Price,
		tasknote_Subject,
		tasknote_qtyHour,
		tasknote_qtyMinutes,
		tast_id,
		tasknotet_id,
		tasknote_isChecked,
		tasknotet_iso_origen,
		tasknotet_iso_analisisCausa,
		tasknotet_iso_accionInmediata,
		tasknotet_iso_accionCorrectiva,
		tasknotet_iso_user_id_resp,
		tasknotet_iso_plazoResolucion,
		tasknotet_iso_verificaEficacia,
		tasknotet_iso_verificaEficaciaDate
	)
	VALUES
	(
		@comp_id,
		@task_id,
		@user_id,
		@prof_id,
		@tasknote_cd,
		@tasknote_Note,
		@tasknote_Image,
		@TaskNote_Price,
		@TaskNote_Subject,
		@tasknote_qtyHour,
		@tasknote_qtyMinutes,
		(SELECT ttt.tast_id
			FROM tbcrm_task ttt
			WHERE	ttt.comp_id = @comp_id AND
					ttt.task_id = @task_id),
		@tasknotet_id,
		@tasknote_isChecked,
		@tasknotet_iso_origen,
		@tasknotet_iso_analisisCausa,
		@tasknotet_iso_accionInmediata,
		@tasknotet_iso_accionCorrectiva,
		@tasknotet_iso_user_id_resp,
		@tasknotet_iso_plazoResolucion,
		@tasknotet_iso_verificaEficacia,
		@tasknotet_iso_verificaEficaciaDate
	)
	SET @return_value = @@IDENTITY





	-- -------------------------------------------------------
	-- Enviamos EMAils en caso de corresponder
	-- -------------------------------------------------------
	DECLARE @lang_id AS INT
	SELECT @lang_id = isnull(TC.lang_id,2)
		FROM tbCompany tc	WITH (NOLOCK)
		WHERE tc.comp_id = @comp_id
	EXEC spCRM_Task_sendEmail @comp_id, @task_id, @lang_id
	-- -------------------------------------------------------



END
GO


