CREATE PROCEDURE [dbo].[spCRM_TaskNotes_UpdateData]
(
	@comp_id				INT,
	@task_id				INT,
	@user_id				INT,
	@prof_id				INT,
	@tasknote_cd			DATETIME,
	@tasknote_Note			NTEXT,
	@tasknote_id			INT,
	@tasknote_Image			IMAGE,
	@TaskNote_Price			DECIMAL(25,2),
	@TaskNote_Subject		NVARCHAR(200),
	@tasknote_qtyHour		INT,
	@tasknote_qtyMinutes	INT
)
AS
BEGIN

	SET NOCOUNT ON

	UPDATE tbCRM_TaskNote
	SET
		comp_id				= @comp_id,
		task_id				= @task_id,
		[user_id]			= @user_id,
		prof_id				= @prof_id,
		tasknote_cd			= @tasknote_cd,
		tasknote_Note		= @tasknote_Note,
		tasknote_PDF		= @tasknote_Image,
		tasknote_Price		= @TaskNote_Price,
		tasknote_Subject	= @TaskNote_Subject,
		tasknote_qtyHour	= @tasknote_qtyHour,
		tasknote_qtyMinutes = @tasknote_qtyMinutes
	WHERE	comp_id			= @comp_id		AND
			tasknote_id		= @tasknote_id


	-- -------------------------------------------------------
	-- Enviamos EMAils en caso de corresponder
	-- -------------------------------------------------------
	DECLARE @lang_id AS INT
	SELECT @lang_id = isnull(TC.lang_id,2)
		FROM tbCompany tc	WITH (NOLOCK)
		WHERE tc.comp_id = @comp_id
	EXEC spCRM_Task_sendEmail @comp_id, @task_id, @lang_id
	-- -------------------------------------------------------

END
GO

