CREATE PROCEDURE [dbo].[spCRM_TaskStatus_getCombo]
(
	@comp_id			INT,
	@status				INT,	-- @status  -1 Update; -2 Insert; -3 Todos
	@prof_id			INT,
	@tast_id			INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo
	@user_id			INT,
	@bra_id				INT,
	@taskt_id			INT
)
AS

	BEGIN




	-- --------------------------------------------
	-- Testing
	-- --------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@status		INT,
		@prof_id	INT,
		@tast_id	INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo
		@user_id	INT,
		@bra_id		INT,
		@taskt_id	INT

		SET @comp_id	= 1
		SET @status		= -3
		SET @prof_id	= 1
		SET @tast_id	= -1
		SET @user_id	= 1
		SET @bra_id		= 1
		SET @taskt_id   = 13
	*/
	-- --------------------------------------------

	SET NOCOUNT ON


	DECLARE @bitActualStatusIsInitial	AS BIT
	DECLARE @bitUserCanSetInitialStatus AS BIT
	SET		@bitActualStatusIsInitial	= 'False'
	SET		@bitUserCanSetInitialStatus = 'False'


	SELECT	@bitActualStatusIsInitial	= IsNull(tcts.tast_isInitialStatus,'False'),
			@bitUserCanSetInitialStatus = IsNull(tu.user_available4CRM_CanReAsignateTask,'False')
		FROM tbCRM_TaskStatus tcts				WITH (NOLOCK)
		INNER JOIN tbUser tu					WITH (NOLOCK)
			ON	tu.[user_id] = @user_id
		WHERE	tcts.comp_id = @comp_id AND
				tcts.tast_id = @tast_id




	-- Busca los Relacionados al Tipo de Tarea
	IF @taskt_id > 0 AND EXISTS(	SELECT TOP 1 1
	                            				FROM tbCRM_TaskTypeStatusRelation tcttsr WITH (NOLOCK)
	                            				WHERE	tcttsr.comp_id		= @comp_id	AND
	                            						tcttsr.taskt_id		= @taskt_id AND
	                            						tcttsr.tts_disabled = 'False'
								)
		BEGIN

			SELECT
					tcts.tast_id		[Id],
					CASE
						WHEN tcts.tast_isInitialStatus		= 'True' THEN	'1'
						WHEN tcts.tast_isFinalStatus		= 'True' THEN	'3'
						ELSE												'2'
					END + ' | ' +
					tcts.tast_desc		[Desc]

				FROM	   tbCRM_TaskStatus						tcts			WITH (NOLOCK)
				LEFT JOIN tbCRM_TaskTypeStatusRelation			tcttsr			WITH (NOLOCK)
					ON	tcttsr.comp_id		= tcts.comp_id AND
						tcttsr.tast_id		= tcts.tast_id
				LEFT JOIN  tbCRM_TaskStatus2Profile				tcttp			WITH (NOLOCK)
					ON	tcttp.comp_id		= tcts.comp_id	AND
						tcttp.bra_id		= @bra_id		AND
						tcttp.tast_id		= tcts.tast_id	AND
						tcttp.prof_id		= @prof_id
				WHERE		tcts.comp_id	= @comp_id 							AND
							(
								(
									(
										tcttp.comp_id		IS NOT NULL
											AND
										tcttp.disabled		= 'False'
									)

									AND

									tcttsr.taskt_id = @taskt_id

									AND

									tcts.tast_disabled	= 'False'

									AND

									CASE
										WHEN	@status	 = -1											AND
												ISNULL(tcts.tast_isInitialStatus,'False')	= 'True'	AND
												@bitActualStatusIsInitial					= 'False'	AND
												@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
										WHEN   (@status	 = -1	AND ISNULL(tcts.tast_isInitialStatus, 'False')	= 'False')	THEN	'True'
										WHEN   (@status	 = -2	AND ISNULL(tcts.tast_isInitialStatus, 'False')	= 'True')	THEN	'True'
										WHEN    @status	 = -3																THEN	'True'
										ELSE																						'False'
									END = 'True'

									AND

									(
										tcttsr.comp_id IS NOT NULL
											AND
										tcttsr.tts_disabled = 'False'
									)
								)

								OR

								tcts.tast_id	=	@tast_id
							)
				ORDER BY	[Desc]

			--SELECT 111
			RETURN
		END




	-- Busca los relacionados a Perfiles
	IF  EXISTS(
				SELECT 1
					FROM tbCRM_TaskStatus2Profile tcttp							WITH (NOLOCK)
					INNER JOIN tbCRM_TaskStatus tcts							WITH (NOLOCK)
						ON	tcts.comp_id		= tcttp.comp_id AND
							tcts.tast_id		= tcttp.tast_id
					WHERE	tcttp.comp_id		= @comp_id		AND
							tcttp.bra_id		= @bra_id		AND
							tcttp.prof_id		= @prof_id		AND
							tcttp.disabled		= 'False'		AND
							tcts.tast_disabled	= 'False'
				)
		BEGIN

			SELECT	tcts.tast_id		[Id],
					CASE
						WHEN tcts.tast_isInitialStatus		= 'True' THEN	'1'
						WHEN tcts.tast_isFinalStatus		= 'True' THEN	'3'
						ELSE												'2'
					END + ' | ' +
					tcts.tast_desc		[Desc]

				FROM	   tbCRM_TaskStatus						tcts			WITH (NOLOCK)
				LEFT JOIN  tbCRM_TaskStatus2Profile				tcttp			WITH (NOLOCK)
					ON	tcttp.comp_id		= tcts.comp_id	AND
						tcttp.bra_id		= @bra_id		AND
						tcttp.tast_id		= tcts.tast_id	AND
						tcttp.prof_id		= @prof_id
				WHERE		tcts.comp_id	= @comp_id 							AND
							(
								(
									(
										tcttp.comp_id		IS NOT NULL			AND
										tcttp.disabled		= 'False'			AND
										tcts.tast_disabled	= 'False'
									)

									AND

									CASE
										WHEN	@status	 = -1											AND
												ISNULL(tcts.tast_isInitialStatus,'False')	= 'True'	AND
												@bitActualStatusIsInitial					= 'False'	AND
												@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
										WHEN   (@status	 = -1	AND ISNULL(tcts.tast_isInitialStatus, 'False')	= 'False')	THEN	'True'
										WHEN   (@status	 = -2	AND ISNULL(tcts.tast_isInitialStatus, 'False')	= 'True')	THEN	'True'
										WHEN    @status	 = -3																THEN	'True'
										ELSE																						'False'
									END = 'True'
								)

								OR

								tcts.tast_id	=	@tast_id
							)
				ORDER BY	tcts.tast_desc

				RETURN

		END





		SELECT	tcts.tast_id		[Id],
				CASE
					WHEN tcts.tast_isInitialStatus		= 'True' THEN	'1'
					WHEN tcts.tast_isFinalStatus		= 'True' THEN	'3'
					ELSE												'2'
				END + ' | ' +
				tcts.tast_desc		[Desc]

			FROM		tbCRM_TaskStatus																tcts			WITH (NOLOCK)

			WHERE		tcts.comp_id	=	@comp_id 													AND
						(
							(
								(tcts.prof_id IS NULL OR tcts.prof_id = @prof_id AND tcts.tast_disabled = 'False')	AND
								CASE
									WHEN	@status	 = -1											AND
											ISNULL(tcts.tast_isInitialStatus,'False')	= 'True'	AND
											@bitActualStatusIsInitial					= 'False'	AND
											@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
									WHEN   (@status	 = -1	AND ISNULL(tcts.tast_isInitialStatus, 'False')	= 'False')	THEN	'True'
									WHEN   (@status	 = -2	AND ISNULL(tcts.tast_isInitialStatus, 'False')	= 'True')	THEN	'True'
									WHEN    @status	 = -3																THEN	'True'
									ELSE																						'False'
								END = 'True'
							)
							OR
							@tast_id = tcts.tast_id
						)
			ORDER BY	tcts.tast_desc

		RETURN


	END


GO







CREATE PROCEDURE [dbo].[spCRM_TaskStatusByType_getCombo]
(
	@comp_id			INT,
	@status				INT,	-- @status  -1 Update; -2 Insert; -3 Todos
	@prof_id			INT,
	@tast_id			INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo
	@user_id			INT,
	@bra_id				INT,
	@taskt_id			int
)
AS

BEGIN

	-- --------------------------------------------
	-- Testing
	-- --------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@status		INT,
		@prof_id	INT,
		@tast_id	INT,	-- Si viene informado es porque si o si necesita que se incluya en el combo
		@user_id	INT,
		@bra_id		INT

		SET @comp_id	= 1
		SET @status		= -1
		SET @prof_id	= 1
		SET @tast_id	= 4
		SET @user_id	= 41
		SET @bra_id		= 1
	*/
	-- --------------------------------------------

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE @bitActualStatusIsInitial	AS BIT
	DECLARE @bitUserCanSetInitialStatus AS BIT
	SET		@bitActualStatusIsInitial	= 'False'
	SET		@bitUserCanSetInitialStatus = 'False'


	SELECT	@bitActualStatusIsInitial	= IsNull(tcts.tast_isInitialStatus,'False'),
			@bitUserCanSetInitialStatus = IsNull(tu.user_available4CRM_CanReAsignateTask,'False')
		FROM tbCRM_TaskStatus tcts				WITH (NOLOCK)
		INNER JOIN tbUser tu					WITH (NOLOCK)
			ON	tu.[user_id] = @user_id
		WHERE	tcts.comp_id = @comp_id AND
				tcts.tast_id = @tast_id


	DECLARE @tmpTable TABLE([id] INT PRIMARY KEY, [Desc] NVARCHAR(200))


	IF  EXISTS(
				SELECT 1
					FROM tbCRM_TaskStatus2Profile tcttp							WITH (NOLOCK)
					INNER JOIN tbCRM_TaskStatus tcts							WITH (NOLOCK)
						ON	tcts.comp_id		= tcttp.comp_id AND
							tcts.tast_id		= tcttp.tast_id
					WHERE	tcttp.comp_id		= @comp_id		AND
							tcttp.bra_id		= @bra_id		AND
							tcttp.prof_id		= @prof_id		AND
							tcttp.disabled		= 'False'		AND
							tcts.tast_disabled	= 'False'
				)
		BEGIN
			INSERT INTO @tmpTable(id, [Desc])
				SELECT	tcts.tast_id		[Id],
						CASE
							WHEN tcts.tast_isInitialStatus		= 'True' THEN	'1'
							WHEN tcts.tast_isFinalStatus		= 'True' THEN	'3'
							ELSE												'2'
						END + ' | ' +
						tcts.tast_desc		[Desc]

					FROM	   tbCRM_TaskStatus						tcts			WITH (NOLOCK)

					LEFT JOIN  tbCRM_TaskStatus2Profile				tcttp			WITH (NOLOCK)
						ON	tcttp.comp_id		= tcts.comp_id	AND
							tcttp.bra_id		= @bra_id		AND
							tcttp.tast_id		= tcts.tast_id	AND
							tcttp.prof_id		= @prof_id
					WHERE		tcts.comp_id	= @comp_id 							AND
								(
									(
										(
											tcttp.comp_id		IS NOT NULL			AND
											tcttp.disabled		= 'False'			AND
											tcts.tast_disabled	= 'False'
										)

										AND

										CASE
											WHEN	@status	 = -1											AND
													ISNULL(tcts.tast_isInitialStatus,'False')	= 'True'	AND
													@bitActualStatusIsInitial					= 'False'	AND
													@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
											WHEN   (@status	 = -1	AND ISNULL(tcts.tast_isInitialStatus, 'False')	= 'False')	THEN	'True'
											WHEN   (@status	 = -2	AND ISNULL(tcts.tast_isInitialStatus, 'False')	= 'True')	THEN	'True'
											WHEN    @status	 = -3																THEN	'True'
											ELSE																						'False'
										END = 'True'
									)

									OR

									tcts.tast_id	=	@tast_id
								)
					ORDER BY	tcts.tast_desc

		END

	ELSE

		BEGIN

			INSERT INTO @tmpTable(id, [Desc])

				SELECT	tcts.tast_id		[Id],
						CASE
							WHEN tcts.tast_isInitialStatus		= 'True' THEN	'1'
							WHEN tcts.tast_isFinalStatus		= 'True' THEN	'3'
							ELSE												'2'
						END + ' | ' +
						tcts.tast_desc		[Desc]

					FROM		tbCRM_TaskStatus																tcts			WITH (NOLOCK)

					WHERE		tcts.comp_id	=	@comp_id 													AND
								(
									(
										(tcts.prof_id IS NULL OR tcts.prof_id = @prof_id AND tcts.tast_disabled = 'False')	AND
										CASE
											WHEN	@status	 = -1											AND
													ISNULL(tcts.tast_isInitialStatus,'False')	= 'True'	AND
													@bitActualStatusIsInitial					= 'False'	AND
													@bitUserCanSetInitialStatus					= 'True'						THEN	'True'
											WHEN   (@status	 = -1	AND ISNULL(tcts.tast_isInitialStatus, 'False')	= 'False')	THEN	'True'
											WHEN   (@status	 = -2	AND ISNULL(tcts.tast_isInitialStatus, 'False')	= 'True')	THEN	'True'
											WHEN    @status	 = -3																THEN	'True'
											ELSE																						'False'
										END = 'True'
									)
									OR
									@tast_id = tcts.tast_id
								)
					ORDER BY	tcts.tast_desc

		END

		-- ---------------------------------------------------------------------------------------
		-- Borra los estados que NO esten en la relacion de permisos en cado de haber alguna . . .
		-- ---------------------------------------------------------------------------------------
		IF EXISTS(	SELECT 1
						FROM tbCRM_TaskTypeStatusRelation
		          		WHERE	comp_id			= @comp_id AND
		          				taskt_id		= @taskt_id AND
		          				tts_disabled	= 'False'
				 )
			BEGIN
				DELETE  @tmpTable
					FROM @tmpTable tmp
					LEFT JOIN tbCRM_TaskTypeStatusRelation rel
						ON	rel.comp_id			= @comp_id AND
							rel.tast_id			= tmp.id AND
							rel.taskt_id		= @taskt_id AND
							rel.tts_disabled	= 'False'
					WHERE	rel.comp_id IS NULL AND
							(tmp.id <> @tast_id or @status = -2)  -- Si es un ALTA que solo me traiga los que corresponden
			END
		-- ---------------------------------------------------------------------------------------



		SELECT * FROM @tmpTable ORDER BY [Desc]

END
GO




CREATE PROCEDURE [dbo].[spCRM_TaskStatusGetDataById]
(
	@comp_id	INT,
	@tast_id	INT
)
AS
	SET NOCOUNT ON

	BEGIN

