			tcts.comp_id,
			tcts.tast_id,
			tcts.prof_id,
			tcts.tast_desc,
			tcts.tast_disabled,
			tcts.bra_id,
			tcts.tast_isFinalStatus,
			tcts.tast_mail2Customer,
			tcts.tast_mail2Contact,
			tcts.tast_mail2Additional,
			ISNULL(tcts.tast_isInitialStatus,'False')				[tast_isInitialStatus],
			ISNULL(tcts.tast_setENDDate,'False')					[tast_setENDDate],
			tcts.tast_id_previous,
			tcts.tast_id_hasInHistory,
			ISNULL(tcts.tast_EndDateBlock,'False')					[tast_EndDateBlock],
			ISNULL(tcts.tast_disableNoteChecked,'False')			[tast_disableNoteChecked],
			ISNULL(tcts.tast_mustChargeEstimatedMinutes,'False')	[tast_mustChargeEstimatedMinutes],
			ISNULL(tcts.tast_mustChargeRealMinutes,'False')			[tast_mustChargeRealMinutes]

		FROM tbCRM_TaskStatus			tcts			WITH (NOLOCK)
		WHERE	tcts.comp_id = @comp_id AND
