CREATE procedure [dbo].[spCRM_TaskType_getCombo]
(
	@comp_id			INT,
	@prof_id			INT,
	@taskt_id			INT, 	-- Si viene informado es porque si o si necesita que se incluya en el combo. -9 trae TODOS
	@user_id			INT,
	@bra_id				INT
)
as



BEGIN

	set NOCOUNT on


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- ---------------------------------------------
	-- Testing
	-- ---------------------------------------------
	/*
	DECLARE
	@comp_id			INT,
	@prof_id			INT,
	@taskt_id			INT,
	@user_id			INT,
	@bra_id				INT
	SET @comp_id	= 1
	SET @prof_id	= 1
	SET @taskt_id	= 3
	SET @user_id	= 1
	SET @bra_id		= 1
	*/
	-- ---------------------------------------------


	IF EXISTS(
				SELECT 1
					FROM tbCRM_TaskType2Profile tcttp
					INNER JOIN tbCRM_TaskType tctt
						ON	tctt.comp_id		= tcttp.comp_id AND
							tctt.taskt_id		= tcttp.taskt_id
					WHERE	tcttp.comp_id		= @comp_id	AND
							tcttp.bra_id		= @bra_id	AND
							tcttp.prof_id		= @prof_id	AND
							tcttp.[disabled]	= 'False'	AND
							tctt.taskt_disabled = 'False'
				)
		BEGIN

				SELECT		tctt.taskt_id	[Id],
							tctt.taskt_desc	[Desc]
					FROM		tbCRM_TaskType			tctt
					LEFT JOIN	tbCRM_TaskType2Profile	tcttp
						ON	tcttp.comp_id		= tctt.comp_id		AND
							tcttp.prof_id		= @prof_id			AND
							tcttp.bra_id		= @bra_id			AND
							tcttp.taskt_id		= tctt.taskt_id

				    WHERE
							(
								tctt.comp_id		= @comp_id			AND
				    			tctt.taskt_disabled	= 'False'			AND
								tcttp.disabled		= 'False'			AND
								tcttp.comp_id		IS NOT NULL
							)
							OR
							tctt.taskt_id	= @taskt_id
					ORDER BY tctt.taskt_desc

		END

	ELSE

		BEGIN

			select
				tctt.taskt_id	[Id],
				tctt.taskt_desc	[Desc]
				from tbCRM_TaskType tctt			WITH (NOLOCK)
				where	tctt.comp_id		= @comp_id	AND
					   (
			   				tctt.taskt_id	= @taskt_id
			   				OR
							(
								(tctt.prof_id IS NULL OR tctt.prof_id = @prof_id)	AND
								 tctt.taskt_disabled = 'False'
							)
					   )
				order by [Desc]

		END
END
GO

