--
-- Descr	: Recuperar datos de atributos de tipos de tareas tbCRM_TaskTypeAttributes
-- Date		: 31/01/19
-- Author	: GA
--

create PROCEDURE [dbo].[spCRM_TaskTypeAttributes_GetDataById]
(
	@comp_id										INT,
	@lang_id										INT,
	@taskta_id										INT
)

AS
	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------
		-- Testing
		-- --------------------------------------
		/*
			DECLARE
						@comp_id		INT,
						@taskta_id		INT
			SELECT
						@comp_id		= 1,
						@taskta_id		= 2
		*/
		-- --------------------------------------

		SELECT
			tctta.taskt_id,
			tctta.optval_attributeNumber,
			tctta.taskta_id,
			tctta.taskta_desc,
			isnull(tctta.taskta_disabled,'false')		[taskta_disabled],
			tctt.taskt_desc,
			tov.optval_desc								[optval_attributeNumber]

			FROM tbCRM_TaskTypeAttributes						tctta

			INNER JOIN tbCRM_TaskType							tctt
			ON	tctt.comp_id	= tctta.comp_id		AND
				tctt.taskt_id	= tctta.taskt_id

			INNER JOIN tbsysOptionsValues						tov
			ON  tov.lang_id		 = @lang_id			AND
				tov.optval_id	 = tctta.optval_attributeNumber AND
				tov.optval_class = 1031

			WHERE	tctta.comp_id		= @comp_id	AND
					tctta.taskta_id		= @taskta_id

	END


GO







CREATE PROCEDURE [dbo].[spCRM_User_checkBasicData]
(
	@comp_id			INT,
	@lang_id			INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



	SET NOCOUNT ON


	/*
	DECLARE @comp_id		INT
	DECLARE @lang_id		INT
	SELECT	@comp_id		=1,
			@lang_id		=2
	DROP TABLE #tmpData
	*/


	CREATE TABLE #tmpData ( [check] INT )

	/*
	por cada control que se realice al comienzo de las páginas y no esté correcto,
	hay que hacer un insert en la temporal creada arriba
	con el valor correspondiente al table_id de la tabla tbSysTables (siempre deberá ser un valor negativo)
	y este valor está relacionado con la tabla tbSysHelpPages que si tendrá el mensaje de error
	a mostrar al usuario
	*/

	IF NOT EXISTS (SELECT TOP 1 1 FROM tbUser tu WHERE tu.user_available4CRM = 'true')
																					INSERT INTO #tmpData ([check]) VALUES (0)


	SELECT	tut.utexts_desc, tut.utexts_id
	FROM	tbsysUniqueTexts tut
	WHERE	tut.lang_id			= @lang_id
	AND		tut.utexts_id		IN(4, 5, 6)
	AND		EXISTS(SELECT 1 FROM #tmpData)

	UNION

	SELECT	cast(thp.hp_desc AS NVARCHAR(MAX)), thp.page_id
	FROM	tbsysHelpPages			thp
			INNER JOIN #tmpData		td
			ON	td.[check]		= thp.table_id
	WHERE	thp.page_id			= -100100 --este valor está en duro e indica la funcionalidad que se está chequeando
	AND		thp.lang_id			= @lang_id

	ORDER BY 2 DESC


END
GO







CREATE PROCEDURE [dbo].[spCRM_User_getCombo]

(
		@comp_id		int,
		@bra_id			int,
		@prof_id		int,
		@crm_type		INT,
		@user_id		INT,
		@action			CHAR(1)		-- Insert  Update Delete Filter Change_user_assigned Todos

)


as


-- 0 Casos;1 Tareas; 2 Llamadas; 3 Reuniones;


-- Todos, debe traer:



BEGIN

	set nocount on

	--  --------------------------------------------------------------------------
	-- Testing
	--  --------------------------------------------------------------------------
	/*
	declare @comp_id		int,
			@bra_id			int,
			@prof_id		int,
			@crm_type		int,
			@user_id		INT,
			@action			CHAR(1)

	select  @comp_id		=1,
			@bra_id			=1,
			@prof_id		=1,
			@crm_type       = 4,
			@user_id		= 1
			@action			'I'

	*/
	-- --------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Llena la cantidad de casos, etc. que tenga YA asignado cada usuario.
	-- --------------------------------------------------------------------------
	DECLARE @tmpUserCRMAssigned AS TABLE([user_id] INT PRIMARY KEY, CRMCountAssigned INT)

	IF		@crm_type = 0	-- Casos
		BEGIN
			INSERT INTO @tmpUserCRMAssigned
				SELECT tcc.[user_id], COUNT(*)
					FROM tbCRM_Case tcc						WITH (NOLOCK)
					INNER JOIN tbCRM_CaseStatus tccs		WITH (NOLOCK)
						ON	tccs.comp_id = tcc.comp_id AND
							tccs.cast_id = tcc.cast_id
					WHERE tccs.cast_isFinalStatus = 'False'		AND tcc.[user_id] IS NOT NULL
					GROUP BY tcc.[user_id]
		END
	ELSE IF @crm_type = 1	-- Tareas
		BEGIN
			INSERT INTO @tmpUserCRMAssigned
				SELECT tcc.[user_id], COUNT(*)
					FROM tbCRM_Task tcc						WITH (NOLOCK)
					INNER JOIN tbCRM_TaskStatus tccs		WITH (NOLOCK)
						ON	tccs.comp_id = tcc.comp_id AND
							tccs.tast_id = tcc.tast_id
					WHERE tccs.tast_isFinalStatus = 'False'		AND tcc.[user_id] IS NOT NULL
					GROUP BY tcc.[user_id]
		END
 	ELSE IF @crm_type = 2	-- Llamadas
		BEGIN
			INSERT INTO @tmpUserCRMAssigned
				SELECT tcc.[user_id], COUNT(*)
					FROM tbCRM_Call tcc						WITH (NOLOCK)
					INNER JOIN tbCRM_CallStatus tccs		WITH (NOLOCK)
						ON	tccs.comp_id = tcc.comp_id AND
							tccs.callst_id = tcc.callst_id
					WHERE tccs.callst_isFinalStatus = 'False'	AND tcc.[user_id] IS NOT NULL
					GROUP BY tcc.[user_id]
		END
 	ELSE IF @crm_type = 3	-- Reuniones
		BEGIN
			INSERT INTO @tmpUserCRMAssigned
				SELECT tcc.[user_id], COUNT(*)
					FROM tbCRM_Meet tcc						WITH (NOLOCK)
					INNER JOIN tbCRM_MeetStatus tccs		WITH (NOLOCK)
						ON	tccs.comp_id = tcc.comp_id AND
							tccs.meetst_id = tcc.meetst_id
					WHERE tccs.meetst_isFinalStatus = 'False'	AND tcc.[user_id] IS NOT NULL
					GROUP BY tcc.[user_id]
		END
 	ELSE IF @crm_type = 4	-- eMails
		BEGIN
			INSERT INTO @tmpUserCRMAssigned
				SELECT tcc.[user_id], COUNT(*)
				FROM tbCRM_Mails tcc						WITH (NOLOCK)
					--INNER JOIN tbcrm_ma tbCRM_MeetStatus tccs		WITH (NOLOCK)
					--	ON	tccs.comp_id = tcc.comp_id AND
					--		tccs.meetst_id = tcc.meetst_id
					WHERE  tcc.[user_id] IS NOT NULL
					GROUP BY tcc.[user_id]

		END
	-- --------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Pone en una tabla temporal todos los usuarios de mi grupo y
	-- si no estoy en ningun grupo, todos los disponibles para crm
	-- --------------------------------------------------------------------------
	DECLARE @tmpUsersOfMyGroup TABLE(USER_ID INT PRIMARY KEY)

	IF @crm_type  = 0		-- Casos
		BEGIN

			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tcugd.[USER_ID]
					FROM tbCRM_UserGroupsDetail tcugd			WITH (NOLOCK)
					INNER JOIN tbUser tu						WITH (NOLOCK)
						ON	tu.[user_id]			= tcugd.[user_id]	AND
							tu.user_available4CRM	= 'True'			AND
							tu.user_Blocked			= 'False'
					INNER JOIN tbCRM_UserGroupsDetail mg		WITH (NOLOCK)	-- Los grupos a donde YO pertenezco.!
						ON	mg.[user_id] = @user_id	AND
						   (
				   				mg.caset_id		IS NULL OR
				   				tcugd.caset_id	IS NULL OR
				   				mg.caset_id		=  tcugd.caset_id
				   			)

				WHERE	tcugd.comp_id	= mg.comp_id					AND
						tcugd.crmug_id	= mg.crmug_id

		END
	ELSE IF @crm_type = 1	-- Tareas
		BEGIN

			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tcugd.[USER_ID]
					FROM tbCRM_UserGroupsDetail tcugd			WITH (NOLOCK)
					INNER JOIN tbUser tu						WITH (NOLOCK)
						ON	tu.[user_id]			= tcugd.[user_id]	AND
							tu.user_available4CRM	= 'True'			AND
							tu.user_Blocked			= 'False'
					INNER JOIN tbCRM_UserGroupsDetail mg		WITH (NOLOCK)	-- Los grupos a donde YO pertenezco.!
						ON	mg.[user_id] = @user_id	AND
						   (
				   				mg.taskt_id		IS NULL OR
				   				tcugd.taskt_id	IS NULL OR
				   				mg.taskt_id		=  tcugd.taskt_id
				   			)

				WHERE	tcugd.comp_id	= mg.comp_id					AND
						tcugd.crmug_id	= mg.crmug_id

		END
 	ELSE IF @crm_type = 2	-- Llamadas
		BEGIN

			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tcugd.[USER_ID]
					FROM tbCRM_UserGroupsDetail tcugd			WITH (NOLOCK)
					INNER JOIN tbUser tu						WITH (NOLOCK)
						ON	tu.[user_id]			= tcugd.[user_id]	AND
							tu.user_available4CRM	= 'True'			AND
							tu.user_Blocked			= 'False'
					INNER JOIN tbCRM_UserGroupsDetail mg		WITH (NOLOCK)	-- Los grupos a donde YO pertenezco.!
						ON	mg.[user_id] = @user_id	AND
						   (
				   				mg.callt_id		IS NULL OR
				   				tcugd.callt_id	IS NULL OR
				   				mg.callt_id		=  tcugd.callt_id
				   			)

				WHERE	tcugd.comp_id	= mg.comp_id					AND
						tcugd.crmug_id	= mg.crmug_id

		END
 	ELSE IF @crm_type = 3	-- Reuniones
		BEGIN

			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tcugd.[USER_ID]
					FROM tbCRM_UserGroupsDetail tcugd			WITH (NOLOCK)
					INNER JOIN tbUser tu						WITH (NOLOCK)
						ON	tu.[user_id]			= tcugd.[user_id]	AND
							tu.user_available4CRM	= 'True'			AND
							tu.user_Blocked			= 'False'
					INNER JOIN tbCRM_UserGroupsDetail mg		WITH (NOLOCK)	-- Los grupos a donde YO pertenezco.!
						ON	mg.[user_id] = @user_id	AND
						   (
				   				mg.meett_id		IS NULL OR
				   				tcugd.meett_id	IS NULL OR
				   				mg.meett_id		=  tcugd.meett_id
				   			)

				WHERE	tcugd.comp_id	= mg.comp_id					AND
						tcugd.crmug_id	= mg.crmug_id

		END



 	ELSE IF @crm_type = 4	-- eMails
		BEGIN

			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tcugd.[USER_ID]
					FROM tbCRM_UserGroupsDetail tcugd			WITH (NOLOCK)
					INNER JOIN tbUser tu						WITH (NOLOCK)
						ON	tu.[user_id]			= tcugd.[user_id]	AND
							tu.user_available4CRM	= 'True'			AND
							tu.user_Blocked			= 'False'
					INNER JOIN tbCRM_UserGroupsDetail mg		WITH (NOLOCK)	-- Los grupos a donde YO pertenezco.!
						ON	mg.[user_id] = @user_id	--AND
						   --(
				   		--		mg.meett_id		IS NULL OR
				   		--		tcugd.meett_id	IS NULL OR
				   		--		mg.meett_id		=  tcugd.meett_id
				   		--	)

				WHERE	tcugd.comp_id	= mg.comp_id					AND
						tcugd.crmug_id	= mg.crmug_id

		END



	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tu.[USER_ID]
					FROM	tbUser tu					WITH (NOLOCK)
					WHERE	tu.user_available4CRM	= 'True' AND
							tu.user_Blocked			= 'False'
		END
	-- Verifica que YO al menos este insertado
	IF NOT EXISTS(SELECT 1 FROM @tmpUsersOfMyGroup WHERE [USER_ID] = @user_id)
		BEGIN
			INSERT INTO @tmpUsersOfMyGroup ([USER_ID]) VALUES (@user_id)
		END
	-- --------------------------------------------------------------------------



	-- -------------------------------------------
	-- Casos
	-- -------------------------------------------
	if @crm_type  = 0		AND (@action = 'I' OR @action = 'C')	-- Alta de un nuevo caso

		BEGIN

			select  tu.user_id								[id],
					dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) + '  (' + dbo.fnStrPADL( CONVERT(VARCHAR(10),ISNULL(tmpacn.CRMCountAssigned,0)),5,'0') + ')'		[desc]
				from tbUser									tu				WITH (NOLOCK)
				inner join tbCRM_TypesByProfile				tctbp			WITH (NOLOCK)
					on  tctbp.comp_id  = @comp_id
					and tctbp.bra_id   = @bra_id
					and tctbp.prof_id  = @prof_id
					and tctbp.crm_type = 0
				INNER JOIN @tmpUsersOfMyGroup tmp
					ON tmp.[USER_ID] = tu.[user_id]
				LEFT JOIN @tmpUserCRMAssigned tmpacn
					ON tmpacn.[user_id] = tu.[user_id]
				where	tu.user_available4CRM	= 'True'	AND
						tu.user_Blocked			= 'False'
				GROUP BY tu.[user_id],tu.user_firstname,tu.user_lastname,tmpacn.CRMCountAssigned
				ORDER BY tmpacn.CRMCountAssigned , tu.user_lastname, tu.user_firstname

		END


	else if @crm_type  = 0

		BEGIN

					select  tu.user_id								[id],
							dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) + '  (' + dbo.fnStrPADL( CONVERT(VARCHAR(10),ISNULL(tmpacn.CRMCountAssigned,0)),5,'0') + ')'		[desc]
						from tbUser									tu				WITH (NOLOCK)
						inner join tbCRM_TypesByProfile				tctbp			WITH (NOLOCK)
							on  tctbp.comp_id  = @comp_id
							and tctbp.bra_id   = @bra_id
							and tctbp.prof_id  = @prof_id
							and tctbp.crm_type = 0
						LEFT JOIN @tmpUserCRMAssigned tmpacn
							ON tmpacn.[user_id] = tu.[user_id]
						where tu.user_available4CRM = 'True'	AND
							  tu.user_Blocked		= 'False'
						GROUP BY tu.[user_id],tu.user_firstname,tu.user_lastname,tmpacn.CRMCountAssigned
						ORDER BY tmpacn.CRMCountAssigned ,  tu.user_lastname, tu.user_firstname


		END

	-- -------------------------------------------
	-- Tareas
	-- -------------------------------------------
	else if @crm_type = 1	AND	(@action = 'I' OR @action = 'C')

		BEGIN

			select  tu.user_id								[id],
					dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) + '  (' + dbo.fnStrPADL( CONVERT(VARCHAR(10),ISNULL(tmpacn.CRMCountAssigned,0)),5,'0') + ')'		[desc]
				from tbUser									tu						WITH (NOLOCK)
				inner join tbCRM_TypesByProfile				tctbp					WITH (NOLOCK)
					on tctbp.comp_id   = @comp_id
					and tctbp.bra_id   = @bra_id
					and tctbp.prof_id  = @prof_id
					and tctbp.crm_type = 1
				INNER JOIN @tmpUsersOfMyGroup tmp
					ON tmp.[USER_ID] = tu.[user_id]
				LEFT JOIN @tmpUserCRMAssigned tmpacn
					ON tmpacn.[user_id] = tu.[user_id]
				where tu.user_available4CRM = 'True'	AND
					  tu.user_Blocked		= 'False'
				GROUP BY tu.[user_id],tu.user_firstname,tu.user_lastname,tmpacn.CRMCountAssigned
				ORDER BY tmpacn.CRMCountAssigned , tu.user_lastname, tu.user_firstname

		END

	else if @crm_type = 1

		BEGIN

			select  tu.user_id								[id],
					dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) + '  (' + dbo.fnStrPADL( CONVERT(VARCHAR(10),ISNULL(tmpacn.CRMCountAssigned,0)),5,'0') + ')'		[desc]
				from tbUser									tu						WITH (NOLOCK)
				inner join tbCRM_TypesByProfile				tctbp					WITH (NOLOCK)
					on tctbp.comp_id   = @comp_id
					and tctbp.bra_id   = @bra_id
					and tctbp.prof_id  = @prof_id
					and tctbp.crm_type = 1
				LEFT JOIN @tmpUserCRMAssigned tmpacn
					ON tmpacn.[user_id] = tu.[user_id]
				where tu.user_available4CRM = 'True'	AND
					  tu.user_Blocked	    = 'False'
				GROUP BY tu.[user_id],tu.user_firstname,tu.user_lastname,tmpacn.CRMCountAssigned
				ORDER BY tmpacn.CRMCountAssigned , tu.user_lastname, tu.user_firstname

		END


	-- -------------------------------------------
	-- Llamadas
	-- -------------------------------------------
	ELSE if @crm_type  = 2	AND	(@action = 'I' OR @action = 'C')

		BEGIN

	   		select  tu.user_id								[id],
					dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) + '  (' + dbo.fnStrPADL( CONVERT(VARCHAR(10),ISNULL(tmpacn.CRMCountAssigned,0)),5,'0') + ')'		[desc]
				from tbUser									tu						WITH (NOLOCK)
				inner join tbCRM_TypesByProfile				tctbp					WITH (NOLOCK)
					on tctbp.comp_id   = @comp_id
					and tctbp.bra_id   = @bra_id
					and tctbp.prof_id  = @prof_id
					and tctbp.crm_type = 2
				INNER JOIN @tmpUsersOfMyGroup tmp
					ON tmp.[USER_ID] = tu.[user_id]
				LEFT JOIN @tmpUserCRMAssigned tmpacn
					ON tmpacn.[user_id] = tu.[user_id]
				where tu.user_available4CRM = 'True'	AND
					  tu.user_Blocked		= 'False'
				GROUP BY tu.[user_id],tu.user_firstname,tu.user_lastname,tmpacn.CRMCountAssigned
				ORDER BY tmpacn.CRMCountAssigned , tu.user_lastname, tu.user_firstname

		END

	ELSE if @crm_type  = 2

		BEGIN

	   		select  tu.user_id								[id],
					dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) + '  (' + dbo.fnStrPADL( CONVERT(VARCHAR(10),ISNULL(tmpacn.CRMCountAssigned,0)),5,'0') + ')'		[desc]
				from tbUser									tu						WITH (NOLOCK)
				inner join tbCRM_TypesByProfile				tctbp					WITH (NOLOCK)
					on tctbp.comp_id   = @comp_id
					and tctbp.bra_id   = @bra_id
					and tctbp.prof_id  = @prof_id
					and tctbp.crm_type = 2
				LEFT JOIN @tmpUserCRMAssigned tmpacn
					ON tmpacn.[user_id] = tu.[user_id]
				where tu.user_available4CRM = 'True'	AND
					  tu.user_Blocked		= 'False'
				GROUP BY tu.[user_id],tu.user_firstname,tu.user_lastname,tmpacn.CRMCountAssigned
				ORDER BY tmpacn.CRMCountAssigned , tu.user_lastname, tu.user_firstname

		END


	-- -------------------------------------------
	-- Reuniones
	-- -------------------------------------------
	else if @crm_type = 3	AND	(@action = 'I' OR @action = 'C')

		BEGIN

			select   tu.user_id										[id],
					 dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) + '  (' + dbo.fnStrPADL( CONVERT(VARCHAR(10),ISNULL(tmpacn.CRMCountAssigned,0)),5,'0') + ')'		[desc]
				from tbUser									tu						WITH (NOLOCK)
				inner join tbCRM_TypesByProfile				tctbp					WITH (NOLOCK)
					on tctbp.comp_id   = @comp_id
					and tctbp.bra_id   = @bra_id
					and tctbp.prof_id  = @prof_id
					and tctbp.crm_type = 3
				INNER JOIN @tmpUsersOfMyGroup tmp
					ON tmp.[USER_ID] = tu.[user_id]
				LEFT JOIN @tmpUserCRMAssigned tmpacn
					ON tmpacn.[user_id] = tu.[user_id]
				where tu.user_available4CRM = 'True'	AND
					  tu.user_Blocked		= 'False'
				GROUP BY tu.[user_id],tu.user_firstname,tu.user_lastname,tmpacn.CRMCountAssigned
				ORDER BY tmpacn.CRMCountAssigned , tu.user_lastname, tu.user_firstname

		END

	else if @crm_type = 3

		BEGIN

			select  tu.user_id										[id],
					dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) + '  (' + dbo.fnStrPADL( CONVERT(VARCHAR(10),ISNULL(tmpacn.CRMCountAssigned,0)),5,'0') + ')'		[desc]
				from tbUser									tu						WITH (NOLOCK)
				inner join tbCRM_TypesByProfile				tctbp					WITH (NOLOCK)
					on tctbp.comp_id   = @comp_id
					and tctbp.bra_id   = @bra_id
					and tctbp.prof_id  = @prof_id
					and tctbp.crm_type = 3
				LEFT JOIN @tmpUserCRMAssigned tmpacn
					ON tmpacn.[user_id] = tu.[user_id]
				where tu.user_available4CRM = 'True'	AND
					  tu.user_Blocked		= 'False'
				GROUP BY tu.[user_id],tu.user_firstname,tu.user_lastname,tmpacn.CRMCountAssigned
				ORDER BY tmpacn.CRMCountAssigned , tu.user_lastname, tu.user_firstname

		END


	-- -------------------------------------------
	-- Trae los usaurios que estan habilitados
	-- para CRM ( se usa para llenar el combo de
	-- la pagina principal de crm )
	-- -------------------------------------------
	else if @crm_type  = 4	 AND @action = 'F'

			BEGIN
					select  tu.user_id										[id],
							dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) 		[desc]
						from tbUser				tu								WITH (NOLOCK)
						INNER JOIN @tmpUsersOfMyGroup tmp
							ON tmp.[USER_ID] = tu.[user_id]
						LEFT JOIN @tmpUserCRMAssigned tmpacn
							ON tmpacn.[user_id] = tu.[user_id]
						where tu.user_available4CRM = 'True'	AND
							  tu.user_Blocked		= 'False'

			END
	else if @crm_type  = 4

		BEGIN
				select  tu.user_id										[id],
						dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) 		[desc]
					from tbUser				tu									WITH (NOLOCK)
					LEFT JOIN @tmpUserCRMAssigned tmpacn
						ON tmpacn.[user_id] = tu.[user_id]
					where tu.user_available4CRM = 'True'	AND
						  tu.user_Blocked		= 'False'

		END
	-- -------------------------------------------




	-- -------------------------------------------
	-- Trae los usaurios que estan habilitados
	-- para CRM ( se usa para llenar el combo de
	-- la pagina principal de crm )
	-- -------------------------------------------
	else if @crm_type  = 5	 AND @action = 'F'

			BEGIN
					select  tu.user_id										[id],
							dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) 		[desc]
						from tbUser				tu								WITH (NOLOCK)
						INNER JOIN @tmpUsersOfMyGroup tmp
							ON tmp.[USER_ID] = tu.[user_id]
						LEFT JOIN @tmpUserCRMAssigned tmpacn
							ON tmpacn.[user_id] = tu.[user_id]
						where tu.user_available4CRM = 'True'	AND
							  tu.user_Blocked		= 'False'

			END
	else if @crm_type  = 5

		BEGIN
				select  tu.user_id										[id],
						dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname) 		[desc]
					from tbUser				tu									WITH (NOLOCK)
					LEFT JOIN @tmpUserCRMAssigned tmpacn
						ON tmpacn.[user_id] = tu.[user_id]
					where tu.user_available4CRM = 'True'	AND
						  tu.user_Blocked		= 'False'

		END
	-- -------------------------------------------




END














GO



CREATE PROCEDURE [dbo].[spCRM_User_Task_getCombo]

(
		@comp_id		int,
		@bra_id			int,
		@prof_id		int,
		@user_id		INT,
		@action			CHAR(1),		-- Insert  Update Delete Filter Change_user_assigned Todos
		@taskt_id		INT,
		@tast_id		INT

)
AS


BEGIN

	set nocount on

	--  --------------------------------------------------------------------------
	-- Testing
	--  --------------------------------------------------------------------------
	/*
	declare @comp_id		int,
			@bra_id			int,
			@prof_id		int,
			@crm_type		int,
			@user_id		INT,
			@action			CHAR(1),
			@taskt_id		INT,
			@tast_id		INT


	select  @comp_id		=1,
			@bra_id			=1,
			@prof_id		=1,
			@crm_type       = 4,
			@user_id		= 3,
			@action			= 'C',
			@taskt_id		= 5,
			@tast_id		= 4
	*/
	-- --------------------------------------------------------------------------


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- --------------------------------------------------------------------------
	-- Llena la cantidad de casos, etc. que tenga YA asignado cada usuario.
	-- --------------------------------------------------------------------------
	DECLARE @tmpUserCRMAssigned AS TABLE([user_id] INT PRIMARY KEY, CRMCountAssigned INT)
	INSERT INTO @tmpUserCRMAssigned
		SELECT tcc.[user_id], COUNT(*)
			FROM tbCRM_Task tcc						WITH (NOLOCK)
			INNER JOIN tbCRM_TaskStatus tccs		WITH (NOLOCK)
				ON	tccs.comp_id = tcc.comp_id AND
					tccs.tast_id = tcc.tast_id
			WHERE tccs.tast_isFinalStatus = 'False'		AND tcc.[user_id] IS NOT NULL
			GROUP BY tcc.[user_id]


	-- --------------------------------------------------------------------------
	-- Pone en una tabla temporal todos los usuarios de mi grupo y
	-- si no estoy en ningun grupo, todos los disponibles para crm
	-- --------------------------------------------------------------------------
	DECLARE @tmpUsersOfMyGroup TABLE(USER_ID INT PRIMARY KEY)


	INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
		SELECT DISTINCT tcugd.[USER_ID]
			FROM tbCRM_UserGroupsDetail			tcugd	WITH (NOLOCK)
			INNER JOIN tbUser					tu		WITH (NOLOCK)
				ON	tu.[user_id]			= tcugd.[user_id]	AND
					tu.user_available4CRM	= 'True'			AND
					tu.user_Blocked			= 'False'
			INNER JOIN tbCRM_UserGroupsDetail	mg		WITH (NOLOCK)	-- Los grupos a donde YO pertenezco.!
				ON	mg.[user_id] = @user_id	AND
				   (
		   				mg.taskt_id		IS NULL OR
		   				tcugd.taskt_id	IS NULL OR
		   				mg.taskt_id		=  tcugd.taskt_id
		   			)
			WHERE	tcugd.comp_id	= mg.comp_id					AND
					tcugd.crmug_id	= mg.crmug_id




	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpUsersOfMyGroup( [USER_ID])
				SELECT DISTINCT tu.[USER_ID]
					FROM	tbUser tu					WITH (NOLOCK)
					WHERE	tu.user_available4CRM	= 'True' AND
							tu.user_Blocked			= 'False'
		END

	-- Verifica que YO al menos este insertado
	IF NOT EXISTS(	SELECT 1
						FROM @tmpUsersOfMyGroup
	              		WHERE [USER_ID] = @user_id)
		BEGIN
			INSERT INTO @tmpUsersOfMyGroup ([USER_ID]) VALUES (@user_id)
		END



	-- Anade Adicionales segun este tipo y estado de tareas
	INSERT INTO @tmpUsersOfMyGroup([USER_ID])
		SELECT DISTINCT tctuaa.user_id4Assign
			FROM tbCRM_TaskUsers4AddAssign tctuaa
			LEFT JOIN @tmpUsersOfMyGroup tmp
				ON  tmp.[USER_ID]	= tctuaa.user_id4Assign
			WHERE	tmp.[USER_ID]			IS NULL			AND
					tctuaa.bra_id	= @bra_id				AND
					tctuaa.taskt_id = @taskt_id				AND
					tctuaa.tast_id	= @tast_id				AND
					tctuaa.user_id4Assign	IS NOT NULL		AND
					tctuaa.taskau_disabled  = 'False'


	-- Borra Usuarios disponibles segun este tipo y estado de tareas
	DELETE   @tmpUsersOfMyGroup
		FROM @tmpUsersOfMyGroup				tmp
		LEFT JOIN tbCRM_TaskUsers4AddAssign tc
			ON  tc.user_id4Block	= tmp.[USER_ID]
		WHERE	tc.user_id4Block IS NOT NULL		AND
				tc.taskau_disabled	= 'False'		AND
				tc.bra_id	= @bra_id				AND
				tc.taskt_id = @taskt_id				AND
				tc.tast_id	= @tast_id



	-- --------------------------------------------------------------------------



	-- -------------------------------------------
	-- Tareas
	-- -------------------------------------------
	IF 	(@action = 'I' OR @action = 'U')

		BEGIN

			SELECT  tu.user_id																									[id],
					dbo.fnStrPADR(	dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname),60,'-')  + ' #' + dbo.fnStrPADL( CONVERT(VARCHAR(10),ISNULL(tmpacn.CRMCountAssigned,0)),5,'0')					[desc]
				FROM tbUser									tu						WITH (NOLOCK)
				INNER JOIN tbCRM_TypesByProfile				tctbp					WITH (NOLOCK)
					ON  tctbp.comp_id   = @comp_id	AND
						tctbp.bra_id	= @bra_id	AND
						tctbp.prof_id	= @prof_id	AND
						tctbp.crm_type	= 1		-- Tareas
				INNER JOIN @tmpUsersOfMyGroup tmp
					ON tmp.[USER_ID] = tu.[user_id]
				LEFT JOIN @tmpUserCRMAssigned tmpacn
					ON tmpacn.[user_id] = tu.[user_id]
				where tu.user_available4CRM = 'True'	AND
					  tu.user_Blocked		= 'False'
				GROUP BY tu.[user_id],tu.user_firstname,tu.user_lastname,tmpacn.CRMCountAssigned
				ORDER BY tmpacn.CRMCountAssigned , tu.user_lastname, tu.user_firstname

		END

	else

		BEGIN

			SELECT  tu.user_id																									[id],
					dbo.fnStrPADR(	dbo.fnStrAllTrim(tu.user_lastname) + ', ' + dbo.fnStrAllTrim(user_firstname),60,'-')  + ' #' + dbo.fnStrPADL( CONVERT(VARCHAR(10),ISNULL(tmpacn.CRMCountAssigned,0)),5,'0')					[desc]
				from tbUser									tu						WITH (NOLOCK)
				inner join tbCRM_TypesByProfile				tctbp					WITH (NOLOCK)
					on tctbp.comp_id   = @comp_id
					and tctbp.bra_id   = @bra_id
					and tctbp.prof_id  = @prof_id
					and tctbp.crm_type = 1
				LEFT JOIN @tmpUserCRMAssigned tmpacn
					ON tmpacn.[user_id] = tu.[user_id]
				where tu.user_available4CRM = 'True'	AND
					  tu.user_Blocked	    = 'False'
				GROUP BY tu.[user_id],tu.user_firstname,tu.user_lastname,tmpacn.CRMCountAssigned
				ORDER BY tmpacn.CRMCountAssigned , tu.user_lastname, tu.user_firstname

		END





END














GO






CREATE  PROCEDURE [dbo].[spCRM_User_UpdateData]
(

	@comp_id					int,
	@lang_id					int,
	@user_id					int,
	@option						int,
	@id							INT,
	@user_id_Proc				INT
)

as

set nocount on;


BEGIN

	-----------------------------------------------------------------
	-- Testing
	-----------------------------------------------------------------
	/*
		declare		@comp_id					int,
					@lang_id					int,
					@user_id					int,
					@option						int,
					@id							int

		select 		@comp_id			= 1,
					@lang_id			= 2,
					@user_id			= 4,
					@option				= 0,
					@id					= 2
	*/
	----------------------------------------------------------------
	-----------------------------------------------------------------

	declare
		@user_origen						int,
		@user_AssignedBy					INT,
		@message							varchar(400),
		@subject							varchar(400),
		@strIDNumber						varchar(400),
		@mail								varchar(2000),
		@user_origen_name					varchar(400),
		@user_assignedBy_name				varchar(400),
		@user_assignedBy_replyTo			AS NVARCHAR(2000),
		@user_mail_origin					varchar(400),
		@user_origen_destiny				varchar(400),
		@user_mail_destiny					varchar(400),
		@optionid							int,
		@desc								varchar(200),
		@strCRMDescription					AS NVARCHAR(4000),
		@strCRMDetail1						AS NVARCHAR(4000),
		@strCRMDetail2						AS NVARCHAR(4000)



		if @option = 0

			BEGIN

				UPDATE tbCRM_Case
					SET [user_id]			= @user_id,
						case_nextReviewdate = GETDATE()
				WHERE	comp_id = @comp_id AND
						case_id = @id

				select	@user_origen		= tct.[user_id],
						@user_AssignedBy	= tct.user_id_Last,
						@strCRMDescription	= IsNull(tct.case_subject,''),
						@strCRMDetail1		= isNull(tct.case_desc,''),
						@strCRMDetail2		= IsNull(tct.case_resolution,'')
					from tbCRM_Case tct		WITH (NOLOCK)
					where	tct.comp_id = @comp_id and
							tct.case_id = @id

				set @optionid = 3512

			END

		else if @option = 1

			BEGIN


				DECLARE @task_id AS INT = @id
				DECLARE @tast_id AS INT
				DECLARE @bra_id  AS INT

				UPDATE tbCRM_Task
					SET [user_id]			= @user_id,
						task_nextReviewdate = GETDATE(),
						user_id_lastUpdate	= @user_id_Proc
					WHERE comp_id = @comp_id AND
						  task_id = @id


				select	@user_origen		= tct.[user_id],
						@user_AssignedBy	= tct.user_id_Last,
						@strCRMDescription	= IsNull(tct.task_subject,''),
						@strCRMDetail1		= '',  --isNull(tct.task_desc,''),   NO PONER, es NTEXT y va a hacer explotar todo.  si lo piden mandar con el sp SendMail de Tareas
						@strCRMDetail2		= '',
						@tast_id			= tct.tast_id,
						@bra_id				= tct.bra_id
					from tbCRM_Task tct		WITH (NOLOCK)
					where	tct.comp_id		= @comp_id and
							tct.task_id		= @id

				set @optionid = 3583

				-- -------------------------------------------------------
				-- Enviamos EMAils en caso de corresponder
				-- -------------------------------------------------------
				EXEC spCRM_Task_sendEmail @comp_id, @id, @lang_id
				-- -------------------------------------------------------


				-- -------------------------------------------------------
				-- Carga en workFlow
				-- -------------------------------------------------------



				IF EXISTS(
							SELECT 1
								FROM tbCRM_TaskStatus tcts	WITH (NOLOCK)
								WHERE	tcts.comp_id				= @comp_id AND
										tcts.tast_id				= @tast_id AND
										tcts.tast_assign2workFlow	= 1
						)
					BEGIN


						DECLARE @strSubject AS NVARCHAR(200) = ''
						SELECT  @strSubject = tt.task_subject
							FROM  tbCRM_Task tt
							WHERE	comp_id = @comp_id AND
									task_id = @task_id

						DECLARE @strURL AS NVARCHAR(600)
						SET @strURL = 'wfmCRM_TaskDetail.aspx?&BraId='	+ CONVERT(VARCHAR,@bra_id)	+
															'&TaskId='	+ CONVERT(VARCHAR,@task_id) +
															'&Action='  + 'U'						+ '&'


						-- Saca del WorkFlow lo que haya de esta tarea.
						UPDATE tbWorkflow
							SET		wf_isProcessed		= 'True',
									wf_dateOfProcessing = GETDATE()
							WHERE	comp_id			= @comp_id AND
									task_id			= @task_id AND
									wf_isProcessed	= 'False'


						--GRABAMOS WORKFLOW
						INSERT INTO tbWorkflow
						(
							comp_id,
							bra_id,
							wf_type,
							wf_isProcessed,
							user_id_from,
							user_id_assigned,
							user_id_processed,
							prof_id_assigned,
							wf_dateOfAssigned,
							wf_dateOfProcessing,
							wf_link,
							wf_message1,
							wf_message2,
							wf_htmlTop,
							wf_htmlBody,
							wf_html_Bottom,
							task_id
						)
						VALUES
						(
							@comp_id,
							@bra_id,
							779,
							'False',
							NULL,
							@user_id, --@intUser4Notify,
							NULL,
							NULL,
							GETDATE(),
							NULL,
							@strURL,
							@strSubject,
							'',
							'', --@strRet_ErrorDescription,
							'',
							'',
							@task_id
						)

					END
					-- -------------------------------------------------------










			END

		ELSE if @option = 2

			BEGIN

				UPDATE tbCRM_Call
					SET [user_id]			= @user_id,
						call_nextReviewdate = GETDATE()
					WHERE comp_id = @comp_id AND
						  call_id = @id

				select	@user_origen		= tct.[user_id],
						@user_AssignedBy	= tct.user_id_Last,
						@strCRMDescription	= IsNull(tct.call_description,''),
						@strCRMDetail1		= isNull(tct.call_Note1,''),
						@strCRMDetail2		= IsNull(tct.call_Note2,'')
					from	tbCRM_Call tct	WITH (NOLOCK)
					where	tct.comp_id = @comp_id and
							tct.call_id = @id

					set @optionid = 4052

			END

		ELSE if @option = 3

			BEGIN


				UPDATE tbCRM_Meet
					SET [user_id]			= @user_id,
						meet_nextReviewdate = GETDATE()
					WHERE comp_id = @comp_id AND
						  meet_id = @id

				select	@user_origen		= tct.[user_id],
						@user_AssignedBy	= tct.user_id_Last,
						@strCRMDescription	= IsNull(tct.meet_subject,''),
						@strCRMDetail1		= isNull(tct.meet_location,''),
						@strCRMDetail2		= IsNull(tct.meet_description,'')
					from tbCRM_Meet tct		WITH (NOLOCK)
					where	tct.comp_id = @comp_id and
							tct.meet_id = @id

					set @optionid = 3795

			END

	--SI NO ES TAREA
	IF @option <> 1
		BEGIN
			--Datos del Usuario de Origen
			select
				@user_origen_name = (tu.user_lastname + ',' + tu.user_firstname),
				@user_mail_origin = tu.user_email
				from tbUser tu		WITH (NOLOCK)
				where tu.[user_id] = @user_origen


			select
				@user_assignedBy_name		= (tu.user_lastname + ',' + tu.user_firstname),
				@user_assignedBy_replyTo	= ISNULL(tu.user_email,'')
				from tbUser tu		WITH (NOLOCK)
				where tu.[user_id] = @user_AssignedBy


			--Datos del Usuario de Destino
			select
				@user_origen_destiny = (tu.user_lastname + ',' + tu.user_firstname),
				@user_mail_destiny	 = tu.user_email
				from tbUser tu	WITH (NOLOCK) where tu.[user_id] = @user_id


			--Armado de Subject y Body
			select @subject = tut.utexts_desc
				from tbsysUniqueTexts tut	WITH (NOLOCK)
				where tut.lang_id = @lang_id
				and tut.utexts_id = 984

			select @message = tut.utexts_desc
				from tbsysUniqueTexts tut	WITH (NOLOCK)
				where tut.lang_id = @lang_id
				and tut.utexts_id = 985

			select @strIDNumber = tut.utexts_desc
				from tbsysUniqueTexts tut	WITH (NOLOCK)
				where tut.lang_id = @lang_id
				and tut.utexts_id = 986


			DECLARE @strAssignedByText AS NVARCHAR(20)
			select @strAssignedByText = tut.utexts_desc
				from tbsysUniqueTexts tut	WITH (NOLOCK)
				where tut.lang_id = @lang_id
				and tut.utexts_id = 991


			select @desc = tswn.word_desc
				from tbSysWordsNew tswn	WITH (NOLOCK)
				where	tswn.lang_id	= @lang_id and
						tswn.wordsi_id	= @optionid

			set @subject = @subject + @desc

			set @mail =		@desc					+ ' ' +	-- Tarea
							@message				+ ' ' + -- Asignada a
							@user_origen_name		+ ' <BR>' + -- Usuario
							@strAssignedByText		+ ' ' + -- Por
							@user_assignedBy_name	+ ' <BR>' +	-- Usuario que se lo asigna
							@strIDNumber + ' ' + convert(varchar,@id) + '<BR> <BR>'


			set @mail = IsNull(@mail,'') +
				'<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
							 'cellpadding="1" cellspacing="1" border="1">' +
				'<tr>
					<td align="Left">' +
						dbo.fnSystem_sendEMail_SetBody2HTML(@strCRMDescription)  +
					'</td>
				<tr>
					<td align="Left">' +
						dbo.fnSystem_sendEMail_SetBody2HTML(@strCRMDetail1)		+
					'</td>
				</tr>
					<td align="Left">' +
						dbo.fnSystem_sendEMail_SetBody2HTML(@strCRMDetail2)		+
					'</td>
				<tr>
					' +
				'</table>'


			exec spSystem_sendEMail
				@compId					= @comp_id,
				@precipients			= @user_mail_destiny,
				@pcopy_recipients		= null,
				@psubject				= @subject,
				@pbody_format			= 'HTML',
				@pbody					= @mail,
				@pfile_attachments		= null,
				@pReplyTo				= @user_assignedBy_replyTo,
				@pblind_copy_recipients	='',
				@pUser_Id				= @user_id
		END


	--declare @bra_id int,
	--		@prof_id int

	--	if @option = 0

	--		BEGIN

	--			set @bra_id = (	select tcc.bra_id
	--								from tbCRM_Case tcc	WITH (NOLOCK)
