CREATE procedure [dbo].[spCRM_UserGroups_getCombo]
(
	@comp_id	int
)
as set NOCOUNT on

select
	crmug_id	[Id],
	crmug_desc [Desc]

from tbCRM_UserGroups

where comp_id = @comp_id

order by [Desc]
GO




CREATE PROCEDURE [dbo].[spCRMCase_UpdateItemSerialData]
(
	@comp_id			INT,
	@case_id			INT,
	@item_id			INT,
	@subcat_id			INT,
	@brand_id			INT,
	@is_id				INT,
	@case_link1			NVARCHAR(500),
	@case_link2			NVARCHAR(500),
	@case_price2		DECIMAL(19,4),
	@case_price3		DECIMAL(19,4),
	@case_qty1			INT,
	@case_qty2			INT,
	@user_id_lastUpdate	INT,
	@IsFromRMA			BIT,
	@pro_id				INT
)
AS

	SET NOCOUNT ON

		BEGIN

			IF @item_id = -1
				SET @item_id = NULL
			IF @subcat_id = -1
				SET @subcat_id = NULL
			IF @brand_id = -1
				SET @brand_id = NULL
			IF @is_id = 0
				SET @is_id = NULL
			IF @is_id = -1
				SET @is_id = NULL
			IF @pro_id = -1
				SET @pro_id = NULL

			--OBTENEMOS LA CATEGORÍA DE LA SUBCATEGORÍA SELECCIONADA
			DECLARE @lCat_Id INT
			SELECT @lCat_Id = tsc.cat_id
				FROM tbSubCategory tsc WITH (NOLOCK)
				WHERE	tsc.comp_id		= @comp_id AND
						tsc.subcat_id	= @subcat_id

			UPDATE tbCRM_Case
			SET
					cat_id				= @lCat_Id,
					subcat_id			= @subcat_id,
					brand_id			= @brand_id,
					item_id				= @item_id,
					is_id				= @is_id,
					case_link1			= @case_link1,
					case_link2			= @case_link2,
					case_price2			= @case_price2,
					case_price3			= @case_price3,
					case_qty1			= @case_qty1,
					case_qty2			= @case_qty2,
					case_secondUpdate	= 'True',
					user_id_lastUpdate	= @user_id_lastUpdate,
					case_isFromRMA		= @IsFromRMA,
					pro_id				= @pro_id

			WHERE	comp_id				= @comp_id AND
					case_id				= @case_id

		END
GO





CREATE procedure [dbo].[spCRMMails_DeleteData]
(
	@comp_id			int,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@lang_id			INT,
	@crmm_id			int
)
as set NOCOUNT on

begin

	delete from tbCRM_Mails
	where	comp_id = @comp_id
	and		crmm_id = @crmm_id

end
GO






CREATE procedure [dbo].[spCRMMails_GetDataByFilters]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,

	@selection_id		INT,
	@tast_id			INT,
	@cast_id			INT,
	@callst_id			INT,
	@meetst_id			INT,
	@datefrom			datetime,
	@dateto				datetime,
	@option				int,
	@text				nvarchar(500),
	@contact			int,
	@contact_text		nvarchar(500),
	@guid				UNIQUEIDENTIFIER,
	@session_user_id	INT

)
as

BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
-- -----------------------------------------------------------------------------


	set NOCOUNT on


	set DATEFORMAT 'ymd'

	-- ---------------------------------------------
	-- Testing
	-- ---------------------------------------------
	/*
		declare
			@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,


			@task_id			INT,
			@case_id			INT,
			@call_id			INT,
			@meet_id			INT,
			@datefrom			datetime,
			@dateto				datetime,
			@option				int,
			@text				nvarchar(500),
			@scrmst_id			int,
			@guid				UNIQUEIDENTIFIER,
			@session_user_id	INT

		select
			@comp_id			= 1,
			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 1,


			@task_id			= -1,
			@case_id			= -1,
			@call_id			= -1,
			@meet_id			= -1,
			@datefrom			= '2012-01-01',
			@dateto				= '2013-12-31',
			@option				= -1,
			@text				= '',
			@scrmst_id			= -1,
			@guid				= '33920467-1e86-4aff-a56e-e33cab7ebd7b',
			@session_user_id	= 1
	*/
	-- ---------------------------------------------

	BEGIN


		select
			' ' [ ], ' ' [ ],' ' [ ],
			tcm.crmm_from,
			tcm.crmm_to,
			tcm.crmm_subject,
			--tcm.crmm_body,
			tcm.crmm_date,
			tcms.scrmst_desc,
			tu.user_lastname + ', ' + tu.user_firstname	[userName],
			tcc.case_desc,
			tct.task_desc,
			tcc2.call_description,
			tcm2.meet_description,
			tcm.crmm_id							[ID]

		from tbCRM_Mails						tcm

			left join tbCRM_tmp					tct2
			on	tct2.comp_id			= tcm.comp_id
			and tct2.crmt_function		= 5
			and tct2.crmt_function_id	= tcm.crmm_id
			and tct2.crmt_guid			= @guid

			INNER JOIN tbuser  tu
				ON tu.[user_id] = tcm.[user_id]

			inner join tbsysCRM_MailStatus		tcms
			on	tcms.scrmst_id	= tcm.scrmst_id

			LEFT join tbCRM_Case				tcc
			on	tcc.comp_id		= tcm.comp_id
			AND tcc.case_id		= tcm.case_id

			LEFT join tbCRM_Task				tct
			on	tct.comp_id		= tcm.comp_id
			AND tct.task_id		= tcm.task_id

			LEFT join tbCRM_Call				tcc2
			on	tcc2.comp_id	= tcm.comp_id
			AND tcc2.call_id	= tcm.call_id

			LEFT join tbCRM_Meet				tcm2
			on	tcm2.comp_id	= tcm.comp_id
			AND tcm2.meet_id	= tcm.meet_id

		where	tcm.comp_id		= @comp_id
		and		tcm.[user_id]	= @session_user_id

		and		tcm.crmm_date between @datefrom and @dateto

		and		(
					(
						(@option	 = -1 ) or
						(@option	 = 0 and tcm.crmm_from like @text + '%') or
						(@option	 = 1 and tcm.crmm_from like '%' + @text + '%') or
						(@option	 = 2 and tcm.crmm_from = @text ) or
						(@option	 = 3 and tcm.crmm_from <> @text ) or
						(@option	 = 4 and tcm.crmm_from not like '%' + @text + '%')
					)
					or
					(
						(@option	 = -1 ) or
						(@option	 = 0 and tcm.crmm_to like @text + '%') or
						(@option	 = 1 and tcm.crmm_to like '%' + @text + '%') or
						(@option	 = 2 and tcm.crmm_to = @text ) or
						(@option	 = 3 and tcm.crmm_to <> @text ) or
						(@option	 = 4 and tcm.crmm_to not like '%' + @text + '%')
					)
					or
					(
						(@option	 = -1 ) or
						(@option	 = 0 and tcm.crmm_subject like @text + '%') or
						(@option	 = 1 and tcm.crmm_subject like '%' + @text + '%') or
						(@option	 = 2 and tcm.crmm_subject = @text ) or
						(@option	 = 3 and tcm.crmm_subject <> @text ) or
						(@option	 = 4 and tcm.crmm_subject not like '%' + @text + '%')
					)
					or
					(
						(@option	 = -1 ) or
						(@option	 = 0 and convert( VARCHAR, tcm.crmm_body) like @text + '%') or
						(@option	 = 1 and convert( VARCHAR, tcm.crmm_body) like '%' + @text + '%') or
						(@option	 = 2 and convert( VARCHAR, tcm.crmm_body) = @text ) or
						(@option	 = 3 and convert( VARCHAR, tcm.crmm_body) <> @text ) or
						(@option	 = 4 and convert( VARCHAR, tcm.crmm_body) not like '%' + @text + '%')
					)

				)




		and		(
					( tcm.comp_id not in (	select top 1 tct2.comp_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 1
												and tct2.crmt_guid = @guid))		or

					(tcm.case_id in (		select tct2.crmt_function_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 1
												and tct2.crmt_guid = @guid))
				)

		and		(
					( tcm.comp_id not in (	select top 1 tct2.comp_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 2
												and tct2.crmt_guid = @guid))		or

					(tcm.task_id in (		select tct2.crmt_function_id
												from tbCRM_tmp tct2					WITH (NOLOCK)
												where tct2.comp_id = @comp_id
												and tct2.crmt_function = 2
												and tct2.crmt_guid = @guid))
				)
		ORDER BY tcm.crmm_id DESC


		--and		(
		--				( tcm.comp_id not in (select top 1 tct2.comp_id
		--							from tbCRM_tmp tct2
		--							where tct2.comp_id = @comp_id
		--							and tct2.crmt_function = 3
		--							and tct2.crmt_guid = @guid))		or

		--				(tcm.case_id in (select tct2.crmt_function_id
		--									from tbCRM_tmp tct2
		--									where tct2.comp_id = @comp_id
		--									and tct2.crmt_function = 1
		--									and tct2.crmt_guid = @guid))
		--		)

		--and		(
		--				( tcm.comp_id not in (select top 1 tct2.comp_id
		--							from tbCRM_tmp tct2
		--							where tct2.comp_id = @comp_id
		--							and tct2.crmt_function = 4
		--							and tct2.crmt_guid = @guid))		or

		--				(tcm.task_id in (select tct2.crmt_function_id
		--									from tbCRM_tmp tct2
		--									where tct2.comp_id = @comp_id
		--									and tct2.crmt_function = 2
		--									and tct2.crmt_guid = @guid))
		--		)

	end

END
GO





CREATE procedure spCRMMails_GetDataById
(
	@comp_id	int,
	@crmm_id	int
)
as set nocount on

begin

	select
		tcm.comp_id,
		tcm.crmm_id,
		tcm.crmm_from,
		tcm.crmm_to,
		tcm.crmm_subject,
		tcm.crmm_body,
		tcm.crmm_date,
		tcm.scrmst_id,
		tcm.case_id,
		tcm.task_id,
		tcm.call_id,
		tcm.meet_id

	from tbCRM_Mails tcm

	where	tcm.comp_id = @comp_id
	and		tcm.crmm_id = @crmm_id

end
GO





CREATE procedure [dbo].[spCRMMails_InsertData]
(
	@comp_id		int,
	@prof_id		int,
	@user_id		int,
	@lang_id		INT,
	@crmm_from		nvarchar(4000),
	@crmm_to		nvarchar(4000),
	@crmm_subject	nvarchar(4000),
	@crmm_body		ntext,
	@scrmst_id		int,
	@case_id		int,
	@task_id		int,
	@call_id		int,
	@meet_id		int,
	@return_value	INT OUTPUT
)

as set nocount on
BEGIN

	DECLARE
		@lcase_id	INT,
		@ltask_id	INT,
		@lcall_id	INT,
		@lmeet_id	INT

	IF @case_id = -1
		SET @lcase_id = NULL
	ELSE
		SET @lcase_id = @case_id

	IF @task_id = -1
		SET @ltask_id = NULL
	ELSE
		SET @ltask_id = @task_id

	IF @call_id = -1
		SET @lcall_id = NULL
	ELSE
		SET @lcall_id = @call_id

	IF @meet_id = -1
		SET @lmeet_id = NULL
	ELSE
		SET @lmeet_id = @meet_id








	insert into tbCRM_Mails
	(
		comp_id,
		[user_id],
		crmm_from,
		crmm_to,
		crmm_subject,
		crmm_body,
		crmm_date,
		scrmst_id,
		case_id,
		task_id,
		call_id,
		meet_id
	)
	VALUES
	(
		@comp_id,
		@user_id,
		@crmm_from,
		@crmm_to,
		@crmm_subject,
		@crmm_body,
		getdate(),
		@scrmst_id,
		@lcase_id,
		@ltask_id,
		@lcall_id,
		@lmeet_id
	)

	SET @return_value = @@IDENTITY




end
GO





CREATE PROCEDURE [dbo].[spCRMMails_InsertDataFromDLL]
(
	@comp_id		int,
	@user_id		int,
	@crmm_from		nvarchar(4000),
	@crmm_to		nvarchar(4000),
	@crmm_subject	nvarchar(4000),
	@crmm_body		nvarchar(MAX),
	@scrmst_id		INT,
	@crmm_id_related int
)

as
begin


	set nocount on

	DECLARE @crmm_id AS INT

	IF @crmm_id_related = -1 SET @crmm_id_related = NULL



	insert into tbCRM_Mails
	(
		comp_id,
		crmm_from,
		crmm_to,
		crmm_subject,
		crmm_body,
		crmm_date,
		scrmst_id,
		USER_ID,
		crmm_id_related
	)
	VALUES
	(
		@comp_id,
		@crmm_from,
		@crmm_to,
		@crmm_subject,
		@crmm_body,
		getdate(),
		@scrmst_id,
		@user_id,
		@crmm_id_related
	)
	SET @crmm_id = @@IDENTITY


	-- -------------------------------------------------------------------------------
	-- MOS 12-2022:  Pone un enganche para que si se responde este email
	-- al recibir las respuestas se agregue este ID al campo crmm_id_related del nuevo email
	-- -------------------------------------------------------------------------------
	IF @crmm_id_related IS NULL
		BEGIN
			IF @crmm_body NOT LIKE '%<crmm_id>%'
				BEGIN

					SET @crmm_body = @crmm_body + '<crmm_id>' + CONVERT(VARCHAR(20),@crmm_id) + '</crmm_id>'

					UPDATE tbCRM_Mails
						SET		crmm_body	= @crmm_body
						WHERE	comp_id		= @comp_id AND
								crmm_id		= @crmm_id

				END
		END
	-- -------------------------------------------------------------------------------





	DECLARE @intTaskID	AS INT
	SET		@intTaskID = NULL
	DECLARE @intID		AS INT

	-- -------------------------------------------------------------------------------
	-- Intenta sacar el TAG de Campa#a insertado por el Mailing del sistema para disparar la carga automatica de una tarea al recibir el mail
	-- -------------------------------------------------------------------------------
	DECLARE @datDate AS DATETIME
	SET		@datDate = GETDATE()

	DECLARE @strTask_desc AS NVARCHAR(4000)
	SET		@strTask_desc = dbo.fnStrStripHTML(@crmm_body)

	DECLARE @camp_id AS INT
	SET		@camp_id = NULL

	DECLARE @xml AS XML
	DECLARE @strFounded AS NVARCHAR(MAX)
	BEGIN TRY
		set @xml		= CONVERT(XML,@crmm_body)
		set @strFounded = @xml.value ('(camp_id)[1]', 'varchar(550)')
	END TRY
	BEGIN CATCH
	END CATCH
	IF  @strFounded IS NOT NULL
		BEGIN
			SET @strFounded = dbo.fnStrAllTrim( dbo.fnGetOnlyNumbers(@strFounded) )
			IF @strFounded <> ''
				BEGIN
					SET @camp_id	= CONVERT(INT,@strFounded)
				END
		END



	IF @camp_id IS NOT NULL
		BEGIN

			DECLARE @taskt_id		AS INT
			DECLARE @tast_id		AS INT
			DECLARE @taskuser_id	AS INT
			DECLARE @taskSubject    AS NVARCHAR(MAX)
			DECLARE @intBraID		AS INT
			DECLARE @intProfID		AS INT

			SELECT TOP 1
					@taskt_id		= tcc.taskt_id,
					@tast_id		= tcc.tast_id,
					@taskuser_id	= tcc.[user_id],
					@taskSubject	= tcc.[Subject] + ': ' + @crmm_subject,
					@intBraID		= tcc.bra_id,
					@intProfID		= tcc.prof_id
				FROM tbCRM_Campaign tcc
				WHERE	tcc.comp_id			= @comp_id	AND
						tcc.camp_disabled	= 'False'	AND
						tcc.taskt_id		IS NOT NULL AND
						tcc.camp_id			= @camp_id

			IF @taskt_id IS NOT NULL

				BEGIN
					EXEC spCRM_Task_insertData
						@comp_id				= @comp_id,
						@bra_id					= @intBraID ,
						@prof_id				= @intProfID,
						@user_id				= @taskuser_id,
						@lang_id				= 2,
						@task_subject			= @taskSubject,
						@task_date4Begin		= @datDate,
						@task_date4End			= @datDate,
						@task_priority			= 0,
						@task_desc				= @strTask_desc,
						@case_id				= null,
						@soh_Bra_id				= null,
						@soh_soh_id				= null,
						@cust_id				= null,
						@contact_id				= null,
						@tast_id				= @tast_id,
						@task_price				= 0,
						@curr_id				= 1,
						@chkCA					= null,
						@taskt_id				= @taskt_id,
						@task_emailAdditional	= @crmm_from,
						@task_resolution		= '',
						@supp_id				= -1,
						@task_nextReviewdate	= @datDate,
						@user_idCreator			= @taskuser_id,
						@return_value			= @intID OUTPUT

					UPDATE tbCRM_Task
						SET		crmm_id		= @crmm_id,
								task_desc	= @strTask_desc
						WHERE	comp_id		= @comp_id AND
								task_id		= @intID

					IF @intTaskID IS NULL
						BEGIN
							SET @intTaskID = @intID
						END


				END

		END
	-- -------------------------------------------------------------------------------















	DECLARE curTASKFromMailSubject CURSOR LOCAL FAST_FORWARD FOR

		SELECT	tk.uer_subject,
				tk.tast_id,
				tk.taskt_id,
				tk.[user_id],
				tk.prof_id,
				tk.bra_id
			FROM tbCRM_Mails_TaskFromMails tk
			INNER JOIN tbUserMailsAccountsRelation tumar
				ON	tumar.comp_id	= tk.comp_id	AND
					tumar.ue_id		= tk.ue_id
			WHERE	tk.comp_id			= @comp_id		AND
					tumar.[user_id]		= @user_id		AND
					tumar.ue_disabled	= 'False'		AND
					tk.uer_disabled		= 'False'		AND
					(
						@crmm_subject		LIKE '%' + tk.uer_subjectContains + '%'
						OR
						tk.uer_subjectContains = '*'
					)									AND
					(
						@crmm_body			LIKE '%' + tk.uer_bodyContains + '%'
						OR
						tk.uer_bodyContains = '*'
					)
			ORDER BY tk.uer_order


		OPEN		curTASKFromMailSubject

		FETCH NEXT FROM curTASKFromMailSubject INTO
						@taskSubject,
						@tast_id,
						@taskt_id,
						@taskuser_id,
						@intProfID,
						@intBraID




		WHILE @@FETCH_STATUS = 0
			BEGIN


					EXEC spCRM_Task_insertData
						@comp_id				= @comp_id,
						@bra_id					= @intBraID ,
						@prof_id				= @intProfID,
						@user_id				= @taskuser_id,
						@lang_id				= 2,
						@task_subject			= @taskSubject,
						@task_date4Begin		= @datDate,
						@task_date4End			= @datDate,
						@task_priority			= 0,
						@task_desc				= @strTask_desc,
						@case_id				= null,
						@soh_Bra_id				= null,
						@soh_soh_id				= null,
						@cust_id				= null,
						@contact_id				= null,
						@tast_id				= @tast_id,
						@task_price				= 0,
						@curr_id				= 1,
						@chkCA					= null,
						@taskt_id				= @taskt_id,
						@task_emailAdditional	= @crmm_from,
						@task_resolution		= '',
						@supp_id				= -1,
						@task_nextReviewdate	= @datDate,
						@user_idCreator			= @taskuser_id,
						@return_value			= @intID OUTPUT


					UPDATE tbCRM_Task
						SET		crmm_id = @crmm_id
						WHERE	comp_id = @comp_id AND
								task_id = @intID

					IF @intTaskID IS NULL
						BEGIN
							SET @intTaskID = @intID
						END

				FETCH NEXT FROM curTASKFromMailSubject INTO
								@taskSubject,
								@tast_id,
								@taskt_id,
								@taskuser_id,
								@intProfID,
								@intBraID
			END



		CLOSE		curTASKFromMailSubject
		DEALLOCATE	curTASKFromMailSubject


    IF	@crmm_id	IS NOT NULL AND
		@intTaskID	IS NOT NULL
		BEGIN
			UPDATE tbCRM_Mails
				SET		task_id = @intTaskID
				WHERE	comp_id = @comp_id AND
						crmm_id = @crmm_id
		END


END
GO





CREATE procedure [dbo].[spCRMMails_UpdateData]
(
	@comp_id		int,
	@prof_id		int,
	@user_id		int,
	@lang_id		INT,
	@crmm_id		int,
	@crmm_from		nvarchar(4000),
	@crmm_to		nvarchar(4000),
	@crmm_subject	nvarchar(4000),
	@crmm_body		NTEXT,
	@scrmst_id		int,
	@case_id		int,
	@task_id		int,
	@call_id		int,
	@meet_id		int
)
as set nocount on

BEGIN


	DECLARE
		@lcase_id	INT,
		@ltask_id	INT,
		@lcall_id	INT,
		@lmeet_id	INT

	IF @case_id = -1
		SET @lcase_id = NULL
	ELSE
		SET @lcase_id = @case_id

	IF @task_id = -1
		SET @ltask_id = NULL
	ELSE
		SET @ltask_id = @task_id

	IF @call_id = -1
		SET @lcall_id = NULL
	ELSE
		SET @lcall_id = @call_id

	IF @meet_id = -1
		SET @lmeet_id = NULL
	ELSE
		SET @lmeet_id = @meet_id



	update	tbCRM_Mails
	SET
		crmm_from		= @crmm_from,
		crmm_to			= @crmm_to,
		crmm_subject	= @crmm_subject,
		crmm_body		= @crmm_body,
		scrmst_id		= @scrmst_id,
		case_id			= @lcase_id,
		task_id			= @ltask_id,
		call_id			= @lcall_id,
		meet_id			= @lmeet_id
	where comp_id		= @comp_id
	and   crmm_id		= @crmm_id

end

GO





