		END

		IF @taskta_text_6 = ''
		BEGIN
			SET @taskta_text_6 = NULL
		END

		IF @taskta_text_7 = ''
		BEGIN
			SET @taskta_text_7 = NULL
		END

		IF @taskta_text_8 = ''
		BEGIN
			SET @taskta_text_8 = NULL
		END

		IF @taskta_text_9 = ''
		BEGIN
			SET @taskta_text_9 = NULL
		END


-------------------------



	IF @item_id					= -1
		SET @item_id			= NULL

	IF @subcat_id				= -1
		SET @subcat_id			= NULL

	IF @brand_id				= -1
		SET @brand_id			= NULL

	IF @is_id					= 0
		SET @is_id				= NULL

	IF @is_id					= -1
		SET @is_id				= NULL

	IF @pro_id					= -1
		SET @pro_id				= NULL

	IF @task_idRelated1			= -1
		SET @task_idRelated1	= NULL

	IF @task_idRelated2			= -1
		SET @task_idRelated2	= NULL


	IF @taskatr1_id = -1
		SET @taskatr1_id = NULL
	IF @taskatr2_id = -1
		SET @taskatr2_id = NULL
	IF @taskatr3_id = -1
		SET @taskatr3_id = NULL
	IF @taskatr4_id = -1
		SET @taskatr4_id = NULL
	IF @taskatr5_id = -1
		SET @taskatr5_id = NULL
	IF @taskatr6_id = -1
		SET @taskatr6_id = NULL



	--OBTENEMOS LA CATEGORÍA DE LA SUBCATEGORÍA SELECCIONADA
	DECLARE @lCat_Id INT
	SELECT @lCat_Id = tsc.cat_id
		FROM tbSubCategory tsc							WITH (NOLOCK)
		WHERE	tsc.comp_id		= @comp_id		AND
				tsc.subcat_id	= @subcat_id

	UPDATE tbCRM_Task		WITH (ROWLOCK)
	SET
			cat_id						= @lCat_Id,
			subcat_id					= @subcat_id,
			brand_id					= @brand_id,
			item_id						= @item_id,
			is_id						= @is_id,
			task_link1					= @task_link1,
			task_link2					= @task_link2,
			task_price2					= @task_price2,
			task_price3					= @task_price3,
			task_qty1					= @task_qty1,
			task_qty2					= @task_qty2,
			task_secondUpdate			= 'True',
			user_id_lastUpdate			= @user_id_lastUpdate,
			pro_id						= @pro_id,
			task_image					= @task_image,
			--  user_id_Creator				= @user_id_lastUpdate,    NO IDIOTA, NO !!!!!!!!!!!!!!!!!!!!!!!!!!
			task_qtyHour				= @task_qtyHour,
			task_qtyMinutes				= @task_qtyMinutes,
			task_qtyEstimatedHours		= @task_qtyEstimatedHours,
			task_qtyEstimatedMinutes	= @task_qtyEstimatedMinutes,
			task_id_related				= @task_idRelated1,
			task_id_related2			= @task_idRelated2,

			taskta_id_1				= @taskta_id_1,
			taskta_id_2				= @taskta_id_2,
			taskta_id_3				= @taskta_id_3,
			taskta_id_4				= @taskta_id_4,
			taskta_id_5				= @taskta_id_5,
			taskta_id_6				= @taskta_id_6,
			taskta_id_7				= @taskta_id_7,
			taskta_id_8				= @taskta_id_8,
			taskta_id_9				= @taskta_id_9,
			taskta_text_1			= @taskta_text_1,
			taskta_text_2			= @taskta_text_2,
			taskta_text_3			= @taskta_text_3,
			taskta_text_4			= @taskta_text_4,
			taskta_text_5			= @taskta_text_5,
			taskta_text_6			= @taskta_text_6,
			taskta_text_7			= @taskta_text_7,
			taskta_text_8			= @taskta_text_8,
			taskta_text_9			= @taskta_text_9,
			task_advertise_desc		= @task_advertise_desc,
			taskatr1_id				= @taskatr1_id,
			taskatr2_id				= @taskatr2_id,
			taskatr3_id				= @taskatr3_id,
			taskatr4_id				= @taskatr4_id,
			taskatr5_id				= @taskatr5_id,
			taskatr6_id				= @taskatr6_id,
			task_qtyBudgetHours		= @task_qtyBudgetHours


	WHERE	comp_id						= @comp_id AND
			task_id						= @task_id


	DECLARE @user_id4Resolution AS INT = NULL
	DECLARE @tast_id			AS INT = NULL
	DECLARE @bitisFinalStatus	AS BIT = 'False'
	SELECT  @tast_id		    = tcts.tast_id,
			@user_id4Resolution = tcts.user_id4Resolution
		FROM tbCRM_Task tcts		WITH (NOLOCK)
		WHERE	tcts.comp_id = @comp_id AND
				tcts.task_id = @task_id

	SELECT @bitisFinalStatus = tcts.tast_isFinalStatus
		FROM tbCRM_TaskStatus tcts		WITH (NOLOCK)
		WHERE	tcts.comp_id = @comp_id AND
				tcts.tast_id = @tast_id


	IF @bitisFinalStatus = 'True' AND  @user_id4Resolution IS NULL
		BEGIN
			UPDATE tbCRM_Task	WITH (ROWLOCK)
				SET user_id4Resolution		= @user_id_lastUpdate,
					task_date4Resolution	= GETDATE()
				WHERE	comp_id			= @comp_id AND
						task_id			= @task_id
		END


	IF @bitisFinalStatus = 'False'
		BEGIN
			UPDATE tbCRM_Task	WITH (ROWLOCK)
				SET user_id4Resolution		= NULL,
					task_date4Resolution	= NULL
				WHERE	comp_id			= @comp_id AND
						task_id			= @task_id
		END



END
GO




create PROCEDURE [dbo].[spCRMTask_UpdateSaleOrderDataData]
(
	@comp_id					INT,
	@task_id					INT,
	@soh_Bra_id					INT,
	@soh_Soh_id					INT
)
AS

SET NOCOUNT ON

BEGIN


	UPDATE tbCRM_Task		WITH (ROWLOCK)
	SET soh_Bra_id =	CASE
							WHEN ISNULL(soh_Bra_id,0) <= 0 THEN @soh_Bra_id
							ELSE								soh_Bra_id
						END,
		soh_soh_id =	CASE
							WHEN ISNULL(soh_soh_id,0) <= 0 THEN @soh_Soh_id
							ELSE								soh_soh_id
						END
		WHERE	comp_id = @comp_id AND
				task_id = @task_id





END
GO





