CREATE PROCEDURE [dbo].[spCRMTmp_UpdateData]
(
	@comp_id			INT,
	@crmt_function		INT,
	@crmt_function_id	INT,
	@guid				UNIQUEIDENTIFIER
)
as set NOCOUNT on

declare @rv	INT

if exists (	select 1
				from tbCRM_tmp tct			WITH (NOLOCK)
				where	tct.comp_id				= @comp_id
				and		tct.crmt_function		= @crmt_function
				and		tct.crmt_function_id	= @crmt_function_id
				and		tct.crmt_guid			= @guid)

	begin

		exec spCRMTmp_DeleteData
			@comp_id			= @comp_id,
			@crmt_function		= @crmt_function,
			@crmt_function_id	= @crmt_function_id,
			@guid				= @guid

	end
else
	begin

		exec spCRMTmp_InsertData
			@comp_id			= @comp_id,
			@crmt_function		= @crmt_function,
			@crmt_function_id	= @crmt_function_id,
			@guid				= @guid,
			@return_value		= @rv

	end
GO





