-- =============================================
CREATE PROCEDURE [dbo].[spCube_Facts_SalesTable]
--	@comp_id	AS INT,
--	@bra_id		AS INT,
--	@user_id	AS INT,
--	@prof_id    AS INT
AS
BEGIN



	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SELECT 	tct.comp_id,
			tct.ct_transaction,
			tct.cust_id,
			tct.sm_id,
			tct.ct_subtotal *	CASE
									WHEN tct.sd_id = 3 THEN -1
									ELSE					 1
								END				[ct_subtotal],
			tct.ct_total    *	CASE
									WHEN tct.sd_id = 3 THEN -1
									ELSE					 1
								END				[ct_total],
			tct.ct_date
		FROM tbCommercialTransactions tct
		INNER JOIN tbCustomer tc
			ON		tc.comp_id	= tct.comp_id
				AND tc.cust_id	= tct.cust_id
		INNER JOIN tbSalesman ts
			ON		ts.comp_id	= tct.comp_id
				AND ts.sm_id	= tct.sm_id

	WHERE tct.sd_id IN (1,3,4)


END
GO


