-- =============================================
CREATE PROCEDURE [dbo].[spCube_SalesByTotals]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@user_id	AS INT,
	@prof_id    AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SELECT	tct.ct_transaction,
			tct.cust_id,
			tct.sm_id,
			tct.ct_subtotal,
			tct.ct_total
		FROM tbCommercialTransactions tct
		INNER JOIN tbCustomer tc
			ON		tc.comp_id	= tct.comp_id
				AND tc.cust_id	= tct.cust_id
		INNER JOIN tbSalesman ts
			ON		ts.comp_id	= tct.comp_id
				AND ts.sm_id	= tct.sm_id
		WHERE	tct.comp_id		= @comp_id
			AND tct.bra_id		= @bra_id

	SELECT  tct.ct_transaction,
			tct.ct_date						[Date],
			YEAR(tct.ct_date)				[Year],
			MONTH(tct.ct_date)				[Month],
			DATEPART(quarter,tct.ct_date)	[Quarter]
		FROM tbCommercialTransactions tct
		WHERE	tct.comp_id		= @comp_id
			AND tct.bra_id		= @bra_id

	SELECT	tc.cust_id,
			tc.cust_name
		FROM tbCustomer tc
		WHERE tc.comp_id = @comp_id

	SELECT	ts.sm_id,
			ts.sm_name
		FROM tbSalesman ts
		WHERE ts.comp_id = @comp_id



END
GO







CREATE PROCEDURE [dbo].[spCubes_MyAnalysis_getCombo]
(
	@comp_id			int,
	@lang_id			int,
	@cubetype			int,
	@user_id			int,
	@prof_id			INT,
	@bra_id				INT
)
as



BEGIN

	set nocount on

------------------------------------------------
------------------------------------------------
/*
	declare 	@comp_id			int,
				@lang_id			int,
				@cubetype			int,
				@user_id			int,
				@prof_id			INT,
				@bra_id				int

	select 		@comp_id			=1,
				@lang_id			=2,
				@cubetype			=400,
				@user_id			=1,
				@prof_id			=1,
				@bra_id				=1

*/
------------------------------------------------




	select	   dbo.fnStrPADR( dbo.fnStrAllTrim(tbc.ma_desc),30 ,'.' ) + ':' + tu.user_lastname + ',' + tu.user_firstname  		[desc],
	           tbc.ma_id		[id]


	from		tbCubes_QueriesSaved					tbc

	inner join tbsysOptionsValues						tov
		on  tov.lang_id			= @lang_id
		and tov.optval_id		= tbc.cubetype
		and	tov.optval_class	= 66

	INNER JOIN tbUser tu
		ON tu.[user_id] = tbc.[user_id]

	where		tbc.comp_id			=	@comp_id
	and			tbc.cubetype		=   @cubetype
	and			(
					tbc.[user_id]		=   @user_id
					OR
				    tbc.prof_id4Share   =	@prof_id
				)
	ORDER BY tbc.ma_desc


END
GO








CREATE PROCEDURE [dbo].[spCubes_Prof4Share_getCombo]
(
	@comp_id		int,
	@lang_id		int,
	@user_id		int
)
as
set nocount on


BEGIN


------------------------------------------------
------------------------------------------------
/*
	declare	@comp_id		int,
			@user_id		int

	select 	@comp_id		=1,
			@user_id		=1
*/
------------------------------------------------
------------------------------------------------

	select		distinct tp.prof_desc		[desc],
						 tp.prof_id			[id]


	from		dbo.tbProfile						tp

	inner join dbo.tbUserCompanyProfile				tucp
	on	tucp.comp_id	= tp.comp_id
	and	tucp.[user_id]	= @user_id
	and tucp.prof_id	= tp.prof_id


	where		tp.comp_id	=	@comp_id






END
GO







