CREATE PROCEDURE [dbo].[spCuotaApplication_ApplyDocument]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@prof_id				INT,
	@cust_id				INT,
	@ct_transaction_Source	INT,
	@ct_transaction_Destiny	INT,
	@payNumber				INT,
	@Value2Apply			DECIMAL(19,4),
	@ctl_id_Destiny			INT,
	@ret_Identity			INT	OUTPUT,
	@ret_ErrorCode			INT	OUTPUT,
	@ret_ErrorDescription	VARCHAR(200) OUTPUT
)
AS

	SET NOCOUNT ON

		BEGIN

			-- -----------------------------------------------------------------------------
			-- TESTING
			-- -----------------------------------------------------------------------------
			/*
				DECLARE
					@comp_id				INT,
					@lang_id				INT,
					@bra_id					INT,
					@user_id				INT,
					@prof_id				INT,
					@cust_id				INT,
					@ct_transaction_Source	INT,
					@ct_transaction_Destiny	INT,
					@payNumber				INT,
					@ret_Identity			INT,
					@ret_ErrorCode			INT,
					@ret_ErrorDescription	VARCHAR(200),
					@Value2Apply			DECIMAL(19,2),
					@ctl_id_Destiny			INT

				SELECT
					@comp_id				= 1,
					@lang_id				= 2,
					@bra_id					= 1,
					@user_id				= 119,
					@prof_id				= 1,
					@cust_id				= 24483,

					--@ct_transaction_Source	= 10464,
					--@ct_transaction_Destiny	= 10512,

					@ct_transaction_Source	= 10976,
					@ct_transaction_Destiny	= 10965,

					@payNumber				= 1,
					@Value2Apply			= 0.87,
					@ctl_id_Destiny			= 141
			*/
			-- -----------------------------------------------------------------------------


			--@ct_transaction_Source	<-- Documento a pagar por el Cliente
			--@ct_transaction_Destiny	<-- Documento a favor del cliente



			Set @ret_Identity			= 0
			Set @ret_ErrorCode			= 0
			Set @ret_ErrorDescription	= ''

-- Esto no se usa mas, se aplica desde cobfranzas!!!
return
			--SAVE TRANSACTION traCuotaApplication
			BEGIN TRANSACTION
			BEGIN TRY

				-- ******************************************************************************************************************
				-- PASO 1
				-- CHEQUEO SI ES UN CT_TRANSACTION CORRESPONDIENTE A UNA CUOTA, SINO, ES UN DOCUMENTO Y ME GUARDO LOS VALORES
				-- CORRESPONDIENTES AL A_TOTAL y AL A_BALANCE
				-- ******************************************************************************************************************
				DECLARE
					@total_Destiny		DECIMAL(19,6),
					@a_balance_Destiny	DECIMAL(19,6),
					@ctl_id				INT,
					@IsCuota			BIT,
					@curr_id			INT,
					@appl_coef			DECIMAL(38,18),
					@appl_coef_			DECIMAL(38,18),
					@appl_total			DECIMAL(19,6),
					@ct_Atotal			DECIMAL(19,6),
					@IsCuota_Destiny	BIT


				SET @ctl_id			= -1
				--SET @ctl_id_Destiny = -1



				IF EXISTS (SELECT 1
						   FROM tbCommercialTransactionsLoan						tctl		WITH (NOLOCK)
						   WHERE	tctl.comp_id		= @comp_id					AND
									tctl.ct_transaction = @ct_transaction_Source	AND
									tctl.ctl_payNumber	= @payNumber				AND
									tctl.ct_ABalance	<> 0)

					BEGIN

						SELECT
							@total_Destiny		= tctl.ct_ATotal,
							@a_balance_Destiny	= tctl.ct_ABalance,
							@ctl_id				= tctl.ctl_id,
							@ct_Atotal			= tct.ct_ATotal

						FROM tbCommercialTransactionsLoan						tctl			WITH (NOLOCK)
							INNER JOIN tbCommercialTransactions					tct
							ON	tct.comp_id			= tctl.comp_id AND
								tct.ct_transaction	= tctl.ct_transaction
						WHERE	tctl.comp_id		= @comp_id					AND
								tctl.ct_transaction = @ct_transaction_Source	AND
								tctl.ctl_payNumber	= @payNumber

						SET @IsCuota = 'True'

						--==
--						SELECT
--							1,
--							'ES UNA CUOTA',
--							@IsCuota				[IsCuota],
--							@total_Destiny			[total_Destiny],
--							@a_balance_Destiny		[a_balance_Destiny],
--							@ctl_id					[ctl_id],
--							@ct_Atotal				[ct_Atotal]
						--==

					END


				ELSE
					IF EXISTS(SELECT 1
							  FROM tbCommercialTransactions							tct			WITH (NOLOCK)
							  WHERE tct.comp_id			= @comp_id					AND
									tct.ct_transaction	= @ct_transaction_Source	AND
									tct.ct_ABalance		<> 0)

					BEGIN

						SELECT
							@total_Destiny		= tct.ct_ATotal,
							@a_balance_Destiny	= tct.ct_ABalance,
							@ct_Atotal			= tct.ct_ATotal

							FROM tbCommercialTransactions								tct		WITH (NOLOCK)
							WHERE	tct.comp_id			= @comp_id						AND
									tct.ct_transaction	= @ct_transaction_Source

						SET @IsCuota = 'False'

						--==
--						SELECT
--							2,
--							'ES UN DOCUMENTO',
--							@IsCuota				[IsCuota],
--							@total_Destiny			[total_Destiny],
--							@a_balance_Destiny		[a_balance_Destiny],
--							@ct_Atotal				[ct_Atotal]
						--==

					END
				-- ******************************************************************************************************************





				-- ******************************************************************************************************************
				-- PASO 2
				-- OBTENEMOS LA INFORMACIÓN DEL DOCUMENTO A FAVOR QUE VAMOS A APLICAR A LA CUOTA O DOCUMENTO PENDIENTE DEL CLIENTE
				-- ******************************************************************************************************************
				DECLARE
					@total_Source		DECIMAL(19,6),
					@a_balance_Source	DECIMAL(19,6)


				IF EXISTS (SELECT 1
				           FROM tbCommercialTransactionsLoan tctl			WITH (NOLOCK)
						   WHERE	tctl.comp_id		= @comp_id					AND
									tctl.ct_transaction = @ct_transaction_Destiny	AND
									tctl.ctl_id			= @ctl_id_Destiny			AND
									tctl.ct_ABalance	<> 0)

					BEGIN

						SELECT
							@total_Source		= tctl.ct_ATotal,
							--==
							@a_balance_Source	= @Value2Apply,
							--==
							--@a_balance_Source	= tct.ct_ABalance,
							@curr_id			= tctl.curr_id
						FROM tbCommercialTransactionsLoan		tctl	--		WITH (NOLOCK)
						WHERE	tctl.comp_id		= @comp_id								AND
								tctl.ct_transaction = @ct_transaction_Destiny

						SET @IsCuota_Destiny = 'True'

					END
				ELSE
					BEGIN
						IF EXISTS (SELECT 1
								   FROM tbCommercialTransactions							tct		WITH (NOLOCK)
								   WHERE	tct.comp_id			= @comp_id					AND
											tct.ct_transaction	= @ct_transaction_Destiny	AND
											tct.ct_ABalance		<> 0)

							BEGIN

								SELECT
									@total_Source		= tct.ct_ATotal,
									--==
									@a_balance_Source	= @Value2Apply,
									--==
									--@a_balance_Source	= tct.ct_ABalance,
									@curr_id			= tct.curr_id_transaction
									FROM tbCommercialTransactions						tct
									WHERE	tct.comp_id			= @comp_id				AND
											tct.ct_transaction	= @ct_transaction_Destiny

								SET @IsCuota_Destiny = 'False'

							END
					END

				--SELECT @curr_id [CURR_ID]
			    --SELECT @a_balance_Source
				-- ******************************************************************************************************************


				-- ******************************************************************************************************************
				-- PASO 3
				-- ACTUALIZAMOS LOS A_BALANCE DE LAS CUOTAS, COMPROBANTES Y DEL CT_TRANSACTION ORIGINAL EN CASO DE SER UNA CUOTA
				-- ******************************************************************************************************************

					DECLARE
						@decAux	DECIMAL(19,6)
					--==
--					SELECT
--						@a_balance_Destiny		[a_balance_Destiny],
--						@a_balance_Source		[a_balance_Source]
					--==

					IF @a_balance_Destiny < @a_balance_Source

						BEGIN


							SET @appl_coef		= (@a_balance_Destiny * 100) / dbo.fnNoZDiv(@ct_Atotal)
							SET @appl_coef_		= (@a_balance_Destiny * 100) / dbo.fnNoZDiv(@total_Source)

							SET @appl_total = @a_balance_Source
							SET @decAux		= @a_balance_Source - @a_balance_Destiny

							/*
							select
									1					[A],
									@a_balance_Source	[a_balance_Source],
									@a_balance_Destiny	[a_balance_Destiny],
									@total_Source		[total_source],
									--@ct_Atotal			[ct_Atotal],
									@appl_coef			[appl_coef],
									@appl_coef_			[appl_coef_]--,
									--@decAux				[decAux]
							*/

							IF @IsCuota = 'True'
								BEGIN
									--SELECT 'CUANDO TERMINES DESCOMENTA ESTO 1'
									--ACTUALIZAMOS LA CUOTA EN CERO YA QUE AL SER MAYOR EL VALOR APLICADO, LA MISMA QUEDARIA SALDADA

									--==
										--SELECT 1
									--==
									UPDATE tbCommercialTransactionsLoan		WITH (ROWLOCK)
									SET
										ct_ABalance			= 0
									WHERE	comp_id			= @comp_id					AND
											ct_transaction	= @ct_transaction_Source	AND
											ctl_payNumber	= @payNumber


									--ACTUALIZAMOS EL A_BALANCE DEL CT_TRANSACTION QUE ENGLOBA TODAS LAS CUOTAS
									--==
										--SELECT 1
									--==
									UPDATE tbCommercialTransactions		WITH (ROWLOCK)
									SET
											ct_ABalance		=  ct_ABalance - @a_balance_Destiny
									WHERE	comp_id			= @comp_id AND
											ct_transaction	= @ct_transaction_Source


									--ACTUALIZAMOS EL A_BALANCE DEL DOCUMENTO A FAVOR DEL CLIENTE YA QUE NO SE APLICO DE MANERA TOTAL SINO PARCIAL
									--Y ACTUALIZAMOS EL A_BALANCE DEL CT_TRANSACTION QUE ENGLOBA EL VALOR DEL COMPROBANTE
									--==
										--SELECT 1
									--==

									IF @IsCuota_Destiny = 'True'
										BEGIN
											--ACTUALIZAMOS A_BALANCE DE LA CUOTA DEL DOCUMENTO A FAVOR

											UPDATE tbCommercialTransactionsLoan		WITH (ROWLOCK)
											SET
												ct_ABalance = @decAux
											WHERE	comp_id			= @comp_id					AND
													ct_transaction	= @ct_transaction_Destiny	AND
													ctl_id			= @ctl_id_Destiny

											--ACTUALIZAMOS LA COMMERCIALTRANSACTIONS Y EL A_BALANCE PARA EL COMPROBANTE A FAVOR QUE POSEE CUOTAS
											UPDATE tbCommercialTransactions			WITH (ROWLOCK)
											SET
												ct_ABalance			= ct_ABalance - @decAux
											WHERE	comp_id			= @comp_id AND
													ct_transaction	= @ct_transaction_Destiny

										END
									ELSE
										BEGIN
											--SELECT 1
											UPDATE tbCommercialTransactions			WITH (ROWLOCK)
											SET
												ct_ABalance			= @decAux
											WHERE	comp_id			= @comp_id AND
													ct_transaction	= @ct_transaction_Destiny
										END

								END
							ELSE
								--NO ES CUOTA, ES UN DOCUMENTO A PAGAR DEL CLIENTE
								BEGIN
									--SELECT 'CUANDO TERMINES DESCOMENTA ESTO 2'
									--ACTUALIZAMOS EL A_BALANCE EN CERO YA QUE AL SER MAYOR EL VALOR APLICADO, EL MISMA QUEDARIA SALDADO
									--==
										SELECT 2
									--==
									UPDATE tbCommercialTransactions		WITH (ROWLOCK)
									SET
										ct_ABalance			= 0
									WHERE	comp_id			= @comp_id AND
											ct_transaction	= @ct_transaction_Source

									--ACTUALIZAMOS EL A_BALANCE DEL DOCUMENTO A FAVOR DEL CLIENTE YA QUE NO SE APLICO DE MANERA TOTAL SINO PARCIAL
									--==
										--SELECT 2
									--==

									IF @IsCuota_Destiny = 'True'
										BEGIN
											--ACTUALIZAMOS A_BALANCE DE LA CUOTA DEL DOCUMENTO A FAVOR
											--SELECT 2
											UPDATE tbCommercialTransactionsLoan		WITH (ROWLOCK)
											SET
												ct_ABalance = @decAux
											WHERE	comp_id			= @comp_id					AND
													ct_transaction	= @ct_transaction_Destiny	AND
													ctl_id			= @ctl_id_Destiny

											--ACTUALIZAMOS LA COMMERCIALTRANSACTIONS Y EL A_BALANCE PARA EL COMPROBANTE A FAVOR QUE POSEE CUOTAS
											UPDATE tbCommercialTransactions			WITH (ROWLOCK)
											SET
												ct_ABalance			= ct_ABalance - @decAux
											WHERE	comp_id			= @comp_id AND
													ct_transaction	= @ct_transaction_Destiny

										END
									ELSE
										BEGIN
											--SELECT 2
											UPDATE tbCommercialTransactions			WITH (ROWLOCK)
											SET
												ct_ABalance			= @decAux
											WHERE	comp_id			= @comp_id AND
													ct_transaction	= @ct_transaction_Destiny

										END

								END


						END
					ELSE
						IF @a_balance_Destiny >= @a_balance_Source
							BEGIN

								SET @appl_coef		= (@a_balance_Source * 100) / dbo.fnNoZDiv(@ct_Atotal)

								SET @appl_coef_		= (@a_balance_Source * 100) / dbo.fnNoZDiv(@total_Source)

--								select
--									2					[B],
--									@a_balance_Source	[a_balance_Source],
--									@ct_Atotal			[ct_Atotal],
--									@appl_coef			[appl_coef],
--									@appl_coef_			[appl_coef_]


								SET @appl_total = @a_balance_Source
								SET @decAux		= @a_balance_Destiny - @a_balance_Source


								IF @IsCuota = 'True'
									BEGIN

										BEGIN
											--SELECT 'CUANDO TERMINES DESCOMENTA ESTO 3'
											--ACTUALIZAMOS LA CUOTA EN CERO YA QUE AL SER MAYOR EL VALOR APLICADO, LA MISMA QUEDARIA SALDADA
											--==
--												SELECT
--													3,
--													@a_balance_Destiny				[a_balance_Destiny],
--													@a_balance_Source				[a_balance_Source],
--													@decAux							[decAux]
											--==
											UPDATE tbCommercialTransactionsLoan			WITH (ROWLOCK)
											SET
												ct_ABalance			= @decAux
											WHERE	comp_id			= @comp_id					AND
													ct_transaction	= @ct_transaction_Source	AND
													ctl_id			= @ctl_id


											--ACTUALIZAMOS EL A_BALANCE DEL CT_TRANSACTION QUE ENGLOBA TODAS LAS CUOTAS
											--==
												--ALERT
											--==
											--==
												--SELECT 3
											--==
											UPDATE tbCommercialTransactions				WITH (ROWLOCK)
											SET
													ct_ABalance		=  ct_ABalance - @a_balance_Source
											WHERE	comp_id			= @comp_id AND
													ct_transaction	= @ct_transaction_Source


											--ACTUALIZAMOS EL A_BALANCE DEL DOCUMENTO A FAVOR DEL CLIENTE YA QUE NO SE APLICO DE MANERA TOTAL SINO PARCIAL
											--==
												--SELECT 3
											--==

											IF @IsCuota_Destiny = 'True'
												BEGIN
													--== ALERT REVISTAR ESTO CUANDO ACTUALIZA LA CUOTA
													--ACTUALIZAMOS A_BALANCE DE LA CUOTA DEL DOCUMENTO A FAVOR
													--SELECT 3, @decAux, @Value2Apply, @ctl_id_Destiny
													UPDATE tbCommercialTransactionsLoan		WITH (ROWLOCK)
													SET
														ct_ABalance			= @decAux
													WHERE	comp_id			= @comp_id					AND
															ct_transaction	= @ct_transaction_Destiny	AND
															ctl_id			= @ctl_id_Destiny

													--ACTUALIZAMOS LA COMMERCIALTRANSACTIONS Y EL A_BALANCE PARA EL COMPROBANTE A FAVOR QUE POSEE CUOTAS
													UPDATE tbCommercialTransactions			WITH (ROWLOCK)
													SET
														ct_ABalance			= ct_ABalance - @Value2Apply
													WHERE	comp_id			= @comp_id AND
															ct_transaction	= @ct_transaction_Destiny

												END
											ELSE
												BEGIN
													--SELECT 3
													UPDATE tbCommercialTransactions			WITH (ROWLOCK)
													SET
														--==
														ct_ABalance			= ct_ABalance - @Value2Apply
														--==
														--ct_ABalance			= 0
													WHERE	comp_id			= @comp_id AND
															ct_transaction	= @ct_transaction_Destiny

												END

										END
									END

								ELSE
									--NO ES CUOTA, ES UN DOCUMENTO A PAGAR DEL CLIENTE
									BEGIN
										--select @a_balance_Source [a_balance_Source], @ct_Atotal [ct_Atotal]
										--ACTUALIZAMOS EL A_BALANCE EN CERO YA QUE AL SER MAYOR EL VALOR APLICADO, EL MISMA QUEDARIA SALDADOç
										--==
											--SELECT 4, @decAux, @Value2Apply, @ctl_id_Destiny, @ctl_id
										--==
										UPDATE tbCommercialTransactions			WITH (ROWLOCK)
										SET
											ct_ABalance			= @decAux
										WHERE	comp_id			= @comp_id AND
												ct_transaction	= @ct_transaction_Source

										--ACTUALIZAMOS EL A_BALANCE DEL DOCUMENTO A FAVOR DEL CLIENTE YA QUE NO SE APLICO DE MANERA TOTAL SINO PARCIAL
										--==
											--SELECT 4
										--==
										IF @IsCuota_Destiny = 'True'
											BEGIN
												--== ALERT REVISTAR ESTO CUANDO ACTUALIZA LA CUOTA
												--ACTUALIZAMOS A_BALANCE DE LA CUOTA DEL DOCUMENTO A FAVOR
												--SELECT 4
												UPDATE tbCommercialTransactionsLoan		WITH (ROWLOCK)
												SET
													ct_ABalance			= ct_ABalance - @Value2Apply --@decAux
												WHERE	comp_id			= @comp_id					AND
														ct_transaction	= @ct_transaction_Destiny	AND
														ctl_id			= @ctl_id_Destiny

												--ACTUALIZAMOS LA COMMERCIALTRANSACTIONS Y EL A_BALANCE PARA EL COMPROBANTE A FAVOR QUE POSEE CUOTAS
												UPDATE tbCommercialTransactions			WITH (ROWLOCK)
												SET
													ct_ABalance			= ct_ABalance - @Value2Apply
												WHERE	comp_id			= @comp_id AND
														ct_transaction	= @ct_transaction_Destiny

											END
										ELSE
											BEGIN
												--SELECT 4
												UPDATE tbCommercialTransactions			WITH (ROWLOCK)
												SET
													--==
													ct_ABalance			= ct_ABalance - @Value2Apply
													--==
													--ct_ABalance			= 0
												WHERE	comp_id			= @comp_id AND
														ct_transaction	= @ct_transaction_Destiny
											END


									END

							END
--						SELECT
--							@appl_coef	[appl_coef],
--							@appl_coef_	[appl_coef_],
--							@appl_total	[appl_total]


				-- ******************************************************************************************************************

				-- ******************************************************************************************************************
				-- PASO 4 INSERTAMOS EN LA TBAPPLICATION
				-- ******************************************************************************************************************

					INSERT INTO tbApplication		WITH (ROWLOCK)
					(
						comp_id,
						bra_id,
						-- appl_id -- this column value is auto-generated,
						ct_transaction_Source,
						ct_transaction_destiny,
						appl_currency,
						appl_total,
						appl_coef,
						appl_coef_,
						appl_excdifchecked,
						ct_transaction,
						ctl_id_Source,
						ctl_id_Destiny
					)
					VALUES
					(
						@comp_id,
						@bra_id,
						@ct_transaction_Source,
						@ct_transaction_Destiny,
						@curr_id,
						@appl_total,
						@appl_coef,
						@appl_coef_,
						'False',
						@ct_transaction_Source,
						CASE @ctl_id WHEN -1 THEN NULL ELSE @ctl_id END,
						CASE @ctl_id_Destiny WHEN -1 THEN NULL ELSE @ctl_id_Destiny END
					)
--
--					/*
--						NULL,
--						CASE @ctl_id WHEN -1 THEN NULL ELSE @ctl_id END
--					*/
--					SET @ret_Identity = @@IDENTITY


				-- ******************************************************************************************************************

				COMMIT TRANSACTION

			END TRY
			BEGIN CATCH
				ROLLBACK TRANSACTION --traCuotaApplication
				DECLARE @ErrorMessage   NVARCHAR(4000)
				DECLARE @ErrorSeverity  INT
				DECLARE @ErrorState     INT
				SELECT  @ErrorMessage    = ERROR_MESSAGE(),
						@ErrorSeverity   = ERROR_SEVERITY(),
						@ErrorState      = ERROR_STATE()
				IF      @ErrorState      = 0 SET @ErrorState = 1
				RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)
			END CATCH
			--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traCuotaApplication

		END






GO




CREATE PROCEDURE [dbo].[spCuotaApplication_DesApplyDocument]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@user_id						INT,
	@prof_id						INT,

	@ct_transaction_Document		INT,	--CT_TRANSACTION DEL DOCUMENTO QUE TIENE VALORES APLICADOS
	@payNumber						INT,	--SI ES UNA CUOTA ME DA EL NUMERO DE CUOTA
	@ctl_id							INT,	--EN CASO DE SER UNA CUOTA, ESTO ME VA A PERMITIR BORRAR UNIVOCAMENTE
	@appl_id						INT,	--EL REGISTRO DE LA TBAPPLICATION

	@ct_transaction_AppliedDocument	INT,	--CT_TRANSACTION DEL DOCUMENTO APLICADO AL DOCUMENTO O CUOTA
	@ctl_id_AppliedDocument			INT,	--CTL_ID CORRESPONDIENTE AL DOCUMENTO A FAVOR DEL CLIENTE

	@ret_Identity					INT	OUTPUT,
	@ret_ErrorCode					INT	OUTPUT,
	@ret_ErrorDescription			VARCHAR(200) OUTPUT
)
AS

SET NOCOUNT ON

BEGIN

	-- -----------------------------------------------------
	-- TESTING
	-- -----------------------------------------------------
	/*
		DECLARE
			@comp_id						INT,
			@lang_id						INT,
			@bra_id							INT,
			@user_id						INT,
			@prof_id						INT,

			@ct_transaction_Document		INT,	--CT_TRANSACTION DEL DOCUMENTO QUE TIENE VALORES APLICADOS
			@payNumber						INT,	--SI ES UNA CUOTA ME DA EL NUMERO DE CUOTA
			@ctl_id							INT,	--EN CASO DE SER UNA CUOTA, ESTO ME VA A PERMITIR BORRAR UNIVOCAMENTE
													--EL REGISTRO DE LA TBAPPLICATION

			@ct_transaction_AppliedDocument	INT,	--CT_TRANSACTION DEL DOCUMENTO APLICADO AL DOCUMENTO O CUOTA
			@ctl_id_AppliedDocument			INT,

			@ret_Identity					INT	,
			@ret_ErrorCode					INT	,
			@ret_ErrorDescription			VARCHAR(200)

		SELECT
			@comp_id						= 1,
			@lang_id						= 2,
			@bra_id							= 1,
			@user_id						= 119,
			@prof_id						= 1,

			@ct_transaction_Document		= 10964,--CT_TRANSACTION DEL DOCUMENTO QUE TIENE VALORES APLICADOS
			@payNumber						= 1,	--SI ES UNA CUOTA ME DA EL NUMERO DE CUOTA
			@ctl_id							= 104,	--EN CASO DE SER UNA CUOTA, ESTO ME VA A PERMITIR BORRAR UNIVOCAMENTE
													--EL REGISTRO DE LA TBAPPLICATION
			@ctl_id_AppliedDocument			= -1,

			@ct_transaction_AppliedDocument	= 10965,--CT_TRANSACTION DEL DOCUMENTO APLICADO AL DOCUMENTO O CUOTA


			@ret_Identity					= 0,
			@ret_ErrorCode					= 0,
			@ret_ErrorDescription			= ''
	*/
	-- -----------------------------------------------------

	Set @ret_Identity			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''

	--SAVE TRANSACTION traCuotaDesApplication
	BEGIN TRANSACTION
	BEGIN TRY

		-- --------------------------
		-- VARIABLES DE TRABAJO
		-- --------------------------

			DECLARE
				@Total		DECIMAL(19,6),
				@lappl_id	INT

			SET	@Total		= 0

		-- --------------------------

		--**************************************************************************************************************************
		--RECUPERAMOS LOS DATOS DE LA TBAPPLICATION
		--RECUPERAMOS EL TOTAL APLICADO AL COMPROBANTE Y EL APPL_ID PARA SU POSTERIOR BORRADO

		SELECT
			@lappl_id	= ta.appl_id,
			@Total		= ta.appl_total
			FROM tbApplication														ta
			WHERE	ta.comp_id					= @comp_id							AND
					ta.ct_transaction_destiny	= @ct_transaction_AppliedDocument	AND
					ta.ct_transaction_Source	= @ct_transaction_Document			AND
				   (	@ctl_id						= -1
							OR
						ta.ctl_id_Source = @ctl_id
				   )																AND
				   ta.appl_id = @appl_id  -- MOS 05-2017, no se porque MIERDA no se hacia como corresponde !!!!!!!!!!!


		--SELECT @lappl_id [APPL_ID]

		--**************************************************************************************************************************

		--ES UNA CUOTA
		IF @ctl_id <> -1  -- En realidad no te calienta esto, si le haces el puto update a un ctl con -1 ho va a hacer nada !!!!

			BEGIN



				----------------------------------------------------------------------------------
				-- ACTUALIZAMOS LA COMMERCIALTRANSACTIONSLOAN CON EL VALOR APLICADO
				-- SE LO SUMAMOS AL A_BALANCE
				----------------------------------------------------------------------------------
				UPDATE tbCommercialTransactionsLoan		WITH (ROWLOCK)
					SET
						ct_ABalance			= ct_ABalance + @Total
					WHERE	comp_id			= @comp_id					AND
							ct_transaction	= @ct_transaction_Document	AND
							ctl_payNumber	= @payNumber				AND
							ctl_id			= @ctl_id
				----------------------------------------------------------------------------------

				----------------------------------------------------------------------------------
				-- ACTUALIZAMOS LA COMMERCIAL TRANSACTIONS CORRESPONDIENTE A LAS CUOTAS
				----------------------------------------------------------------------------------
				UPDATE tbCommercialTransactions			WITH (ROWLOCK)
					SET
						ct_ABalance			= ct_ABalance + @Total
					WHERE	comp_id			= @comp_id AND
							ct_transaction	= @ct_transaction_Document
				----------------------------------------------------------------------------------




				----------------------------------------------------------------------------------
				-- ACTUALIZAMOS LA CUOTA DEL COMPROBANTE A FAVOR DEL CLIENTE
				----------------------------------------------------------------------------------
				UPDATE tbCommercialTransactionsLoan		WITH (ROWLOCK)
					SET
						ct_ABalance			= ct_ABalance + @Total
					WHERE	comp_id			= @comp_id							AND
							ct_transaction	= @ct_transaction_AppliedDocument	AND
							ctl_id			= @ctl_id_AppliedDocument
							-- ctl_id			= @ct_transaction_AppliedDocument NOOOOOOOOOOOOOOOOOOOOOOOO, deja el puto whatsapp !!!!!!
				----------------------------------------------------------------------------------

				----------------------------------------------------------------------------------
				-- ACTUALIZAMOS LA COMMERCIALTRANSACTIONS DEL DOCUMENTO QUE FUE APLICADO
				----------------------------------------------------------------------------------
				UPDATE tbCommercialTransactions			WITH (ROWLOCK)
					SET
						ct_ABalance			= ct_ABalance + @Total
					WHERE	comp_id			= @comp_id AND
							ct_transaction	= @ct_transaction_AppliedDocument
				----------------------------------------------------------------------------------





				--POR ULTIMO BORRAMOS LA TBAPPLICATION PARA LA CUOTA A PAGAR POR EL CLIENTE
				DELETE FROM tbApplication				WITH (ROWLOCK)
					WHERE	comp_id		= @comp_id		AND
							appl_id		= @lappl_id

			END

		ELSE
		--**************************************************************************************************************************
		--	ES UN DOCUMENTO
			BEGIN

				--------------------------------------------------------------------------------------------
				-- ACTUALIZO LA COMMERCIALTRANSACTIONS DEVOLVIENDOLE EL VALOR QUE SE APLICO DEL DOCUMENTO
				--------------------------------------------------------------------------------------------
				UPDATE tbCommercialTransactions			WITH (ROWLOCK)
					SET
						ct_ABalance			= ct_Abalance + @Total
					WHERE	comp_id			= @comp_id					AND
							ct_transaction	= @ct_transaction_Document
				--------------------------------------------------------------------------------------------

				--------------------------------------------------------------------------------------------
				-- ACTUALIZAMOS LA CUOTA DEL DOCUMENTO A FAVOR DEL CLIENTE DEVOLVIENDO EL VALOR QUE SE APLICO
				--------------------------------------------------------------------------------------------
				UPDATE tbCommercialTransactionsLoan		WITH (ROWLOCK)
					SET
						ct_ABalance = ct_ABalance + @Total
					WHERE	comp_id = @comp_id AND
							ctl_id	= @ctl_id_AppliedDocument

				--------------------------------------------------------------------------------------------

				--------------------------------------------------------------------------------------------
				-- ACTUALIZAMOS LA COMMERCIALTRANSACTIONS CON EL VALOR APLICADO EN LA TBAPPLICATION
				--------------------------------------------------------------------------------------------
				UPDATE tbCommercialTransactions			WITH (ROWLOCK)
					SET
						ct_ABalance			= ct_Abalance + @Total
					WHERE	comp_id			= @comp_id					AND
							ct_transaction	= @ct_transaction_AppliedDocument
				--------------------------------------------------------------------------------------------



				--------------------------------------------------------------------------------------------
				-- POR ULTIMO BORRAMOS LA TBAPPLICATION
				--------------------------------------------------------------------------------------------
				DELETE FROM tbApplication				WITH (ROWLOCK)
					WHERE	comp_id		= @comp_id		AND
							appl_id		= @lappl_id
				--------------------------------------------------------------------------------------------

			END

		COMMIT TRANSACTION

	END TRY
	BEGIN CATCH
		ROLLBACK TRANSACTION --traCuotaDesApplication
		DECLARE @ErrorMessage   NVARCHAR(4000)
		DECLARE @ErrorSeverity  INT
		DECLARE @ErrorState     INT
		SELECT  @ErrorMessage    = ERROR_MESSAGE(),
				@ErrorSeverity   = ERROR_SEVERITY(),
				@ErrorState      = ERROR_STATE()
		IF      @ErrorState      = 0 SET @ErrorState = 1
		RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)
	END CATCH
	--IF @@TRANCOUNT > 0 COMMIT --TRANSACTION traCuotaDesApplication

END
GO



CREATE PROCEDURE [dbo].[spCuotaApplication_GetDataByCtTransactionAndPayNumber]
(
	@comp_id		INT,
	@ct_transaction	INT,
	@ctl_id			INT
)
AS


BEGIN


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ----------------------------------
	-- TESTING
	-- ----------------------------------
	/*
		DECLARE
			@comp_id		INT,
			@ct_transaction	INT,
			@payNumber		INT
		SELECT
			@comp_id		= 1,
			@ct_transaction	= 10014,
			@payNumber		= -1
	*/
	-- ----------------------------------



	--SI CUOTA = -1 ES UN COMPROBANTE QUE NO TIENE CUOTAS,
	--SINO ES EL CT_TRANSACTION y CUOTA ES EL NUMERO DE CUOTA
	--PARA PODER IDENTIFICARLO UNIVOCAMENTE EN LA COMMERCIALTRANSACIONSLOAN
	IF @ctl_id = -1

		SELECT
			tct.ct_ATotal,
			tct.ct_ABalance
		FROM	tbCommercialTransactions				tct
		WHERE	tct.comp_id			= @comp_id			AND
				tct.ct_transaction	= @ct_transaction
	ELSE
		SELECT
			tctl.ct_ATotal,
			tctl.ct_ABalance
		FROM tbCommercialTransactionsLoan				tctl
		WHERE	tctl.comp_id		= @comp_id			AND
				tctl.ct_transaction = @ct_transaction	AND
				tctl.ctl_id			= @ctl_id

END







GO





CREATE PROCEDURE [dbo].[spCuotaApplication_GetDocumentsApplied2SelectedDocument]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@cust_id				INT,
	@ct_transaction_Source	INT,
	@ctl_id					INT
)
AS

	SET NOCOUNT ON

			BEGIN

				-- ------------------------------
				-- TESTING
				-- ------------------------------
				/*
					DECLARE
						@comp_id				INT,
						@lang_id				INT,
						@bra_id					INT,
						@user_id				INT,
						@cust_id				INT,
						@ct_transaction_Source	INT,
						@ctl_id					INT
					SELECT
						@comp_id				= 1,
						@lang_id				= 2,
						@bra_id					= 1,
						@user_id				= 1,
						@cust_id				= 24484,
						@ct_transaction_Source	= 10973,
						@ctl_id					= -1
				*/
				-- ------------------------------

					declare @d int
					set		@d = 2



				--OBTENGO LOS COMPROBANTES APLICADOS

--				SELECT
--					--ta.ct_transaction_Source,
--					--dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,ta.ct_transaction_Source),
--
--					dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,ta.ct_transaction_destiny) + ' | ' +
--					CONVERT(VARCHAR,tct.ct_ATotal)															+ ' | ' +
--					CONVERT(VARCHAR,tct.ct_ABalance)														[Desc],
--					ta.ct_transaction_destiny																[Id]
--					--ta.ctl_id_Source,
--					--ta.ctl_id_Destiny
--				FROM tbApplication										ta
--
--					INNER JOIN tbCommercialTransactions					tct
--						ON	tct.comp_id			= ta.comp_id			AND
--							tct.ct_transaction	= ta.ct_transaction_destiny
--
--					INNER JOIN tbUsers4BranchFilter						tubf
--						ON	tubf.comp_id		= ta.comp_id			AND
--							tubf.bra_id			= ta.bra_id				AND
--							tubf.[user_id]		= @user_id
--
--				WHERE	ta.comp_id					= @comp_id AND
--						(ta.ct_transaction_Source	= @ct_transaction_Source) AND
--						(@ctl_id  = -1 OR			ta.ctl_id_Destiny = @ctl_id)





				SELECT
					dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,ta.ct_transaction_destiny) + ' -> $' + dbo.fnStrFromDecimal(ta.appl_total, 10, 2, 12) + ' | ' +
					CASE
						WHEN tctl.comp_id IS NULL THEN
							'#---'
					ELSE
							'# ' + dbo.fnStrPADL(CONVERT(VARCHAR(2),tctl.ctl_payNumber),2,'0')
					END																						+ ' | ' +
					CASE
						WHEN tctl.comp_id IS NULL THEN
							CONVERT(VARCHAR,tct.ct_ATotal)	+ ' | ' +
							CONVERT(VARCHAR,tct.ct_ABalance)
					ELSE
							CONVERT(VARCHAR,tctl.ct_ATotal)	+ ' | ' +
							CONVERT(VARCHAR,tctl.ct_ABalance)
					END																						[Desc],
					CONVERT(VARCHAR,ta.ct_transaction_destiny) + ' | ' +
					CASE
						WHEN tctl.comp_id IS NULL THEN
								CONVERT(VARCHAR,'-1')
					ELSE
								CONVERT(VARCHAR,tctl.ctl_id)
					END				 + ' | ' +
					CONVERT(VARCHAR,ta.appl_id)																	[Id]

				FROM tbApplication										ta

					INNER JOIN tbCommercialTransactions					tct
						ON	tct.comp_id			= ta.comp_id			AND
							tct.ct_transaction	= ta.ct_transaction_destiny

					LEFT JOIN tbCommercialTransactionsLoan				tctl
						ON	tctl.comp_id		= tct.comp_id			AND
							tctl.ct_transaction = tct.ct_transaction	and
							tctl.ctl_id			= ta.ctl_id_Destiny

					INNER JOIN tbUsers4BranchFilter						tubf
						ON	tubf.comp_id		= tct.comp_id			AND
							tubf.bra_id			= tct.bra_id			AND
							tubf.[user_id]		= @user_id

				WHERE	ta.comp_id					= @comp_id			AND
						ta.ct_transaction_Source	= @ct_transaction_Source AND
						(@ctl_id  = -1 OR			ta.ctl_id_Source = @ctl_id)
						--(@ctl_id  = -1 OR			ta.ctl_id_Destiny = @ctl_id)


			END







GO




CREATE PROCEDURE [dbo].[spCuotaApplication_getDocumentsToApply]
(
	@comp_id	INT,
	@lang_id	INT,
	@user_id	INT,
	@cust_id	INT
)
AS


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SET NOCOUNT ON

		BEGIN

			-- ----------------------------
			-- TESTING
			-- ----------------------------
			/*
				DECLARE
					@comp_id	INT,
					@lang_id	INT,
					@user_id	INT,
					@cust_id	INT

				SELECT
					@comp_id	= 1,
					@lang_id	= 2,
					@user_id	= 1,
					@cust_id	= 24484
			*/
			-- ----------------------------

			--ACA OBTENEMOS LAS CUOTAS Y LOS NOMBRES DE LOS COMPROBANTES QUE CORRESPONDEN AL CLIENTE

			SELECT
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tctl.ct_transaction)	+ ' | ' +
				'#' + ' ' + CONVERT(VARCHAR,tctl.ctl_payNumber)										+ ' | ' +
				dbo.fnStrFromDecimal(tctl.ct_ATotal, 13, 2, 12)														+ ' | ' +
				dbo.fnStrFromDecimal(tctl.ct_ABalance, 13, 2, 12)													[Desc],
				CONVERT(VARCHAR,tctl.ct_transaction)												+ ' | ' +
				CONVERT(VARCHAR,tctl.ctl_id)														[Id]


			FROM tbCommercialTransactionsLoan						tctl

				INNER JOIN vwCommercialTransactions_forSales		vctfs
					ON	vctfs.comp_id = tctl.comp_id				AND
						vctfs.ct_transaction = tctl.ct_transaction	AND
						vctfs.sd_isInBalance = 'True'				AND
						vctfs.sd_isQuotation = 'False'

				INNER JOIN tbCommercialTransactions					tct
					ON	tct.comp_id			= tctl.comp_id			AND
						tct.ct_transaction	= tctl.ct_transaction

				INNER JOIN tbCustomer								tc
					ON	tc.comp_id			= tct.comp_id			AND
						tc.cust_id			= tct.cust_id

				INNER JOIN tbUsers4BranchFilter						tubf
					ON	tubf.comp_id		= tct.comp_id			AND
						tubf.bra_id			= tct.bra_id			AND
						tubf.[user_id]		= @user_id



			WHERE		tctl.comp_id		= @comp_id				AND
						tct.cust_id			= @cust_id				AND
						tctl.ct_ABalance	<> 0					AND
						tctl.ct_transaction NOT IN (SELECT vctpoa.ct_transaction
														FROM vwCommercialTransactions_PaymentOnAccount vctpoa
														WHERE	vctpoa.comp_id			= @comp_id AND
																vctpoa.ct_transaction	= tctl.ct_transaction )
													-- esto es hacer las cosas como se te re cantan las pelotas ya que sabes que no se puede hacer !!!!!
													-- Ya no se si nos tomas de forros o que. . .

			UNION


			SELECT
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction)	+ ' | ' +
				'#--'																				+ ' | ' +
				dbo.fnStrFromDecimal(tct.ct_ATotal, 13, 2, 12)														+ ' | ' +
				dbo.fnStrFromDecimal(tct.ct_ABalance, 13, 2, 12)													[Desc],
				CONVERT(VARCHAR,tct.ct_transaction) + ' | ' +  '-1'									[Id]
			FROM tbCommercialTransactions							tct

				INNER JOIN vwCommercialTransactions_forSales		vctfs
					ON	vctfs.comp_id		 = tct.comp_id				AND
						vctfs.ct_transaction = tct.ct_transaction	AND
						vctfs.sd_isInBalance = 'True'				AND
						vctfs.sd_isQuotation = 'False'

				INNER JOIN tbCustomer								tc
					ON	tc.comp_id			= tct.comp_id			AND
						tc.cust_id			= tct.cust_id

				INNER JOIN tbUsers4BranchFilter						tubf
					ON	tubf.comp_id		= tct.comp_id			AND
						tubf.bra_id			= tct.bra_id			AND
						tubf.[user_id]		= @user_id



			WHERE		tct.comp_id			= @comp_id				AND
						tct.cust_id			= @cust_id				AND
						tct.ct_ABalance		<> 0					AND
						tct.ct_transaction	NOT IN (
													SELECT tctl.ct_transaction
						                  				FROM tbCommercialTransactionsLoan tctl
						                  				WHERE	tctl.comp_id		= tct.comp_id	AND
						                  						tctl.ct_transaction = tct.ct_transaction
													)
						                  							AND
						tct.ct_transaction NOT IN (
													SELECT vctpoa.ct_transaction
														FROM vwCommercialTransactions_PaymentOnAccount vctpoa
														WHERE 	vctpoa.comp_id			= tct.comp_id AND
																vctpoa.ct_transaction	= tct.ct_transaction
												  ) -- IDEM ARRIBA !!!



		END








GO





CREATE PROCEDURE [dbo].[spCuotaApplication_GetDocumentsWithApplications]
(
	@comp_id	INT,
	@lang_id	INT,
	@user_id	INT,
	@cust_id	INT,
	@datefrom	DATETIME,
	@dateto		DATETIME
)
AS


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SET NOCOUNT ON

		BEGIN

			set	@dateFrom	=  dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'False')
			set	@dateto		=  dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


			-- ----------------------------
			-- TESTING
			-- ----------------------------
			/*
				DECLARE
					@comp_id	INT,
					@lang_id	INT,
					@user_id	INT,
					@cust_id	INT

				SELECT
					@comp_id	= 1,
					@lang_id	= 2,
					@user_id	= 1,
					@cust_id	= 24454
			*/
			-- ----------------------------

			--ACA OBTENEMOS LAS CUOTAS Y LOS NOMBRES DE LOS COMPROBANTES QUE CORRESPONDEN AL CLIENTE

			SELECT
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tctl.ct_transaction)	+ ' | ' +
				'# ' +  dbo.fnStrPADL( CONVERT(NVARCHAR(3),tctl.ctl_payNumber),2,'0')										+ ' | ' +
				dbo.fnStrFromDecimal(tctl.ct_ATotal, 13, 2, 12)														+ ' | ' +
				dbo.fnStrFromDecimal(tctl.ct_ABalance, 13, 2, 12)																							[Desc],
				CONVERT(VARCHAR,tctl.ct_transaction) + ' | ' +  CONVERT(VARCHAR,tctl.ctl_payNumber) + ' | ' + CONVERT(VARCHAR,tctl.ctl_id) 	[Id]


			FROM tbCommercialTransactionsLoan						tctl		WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions					tct			WITH (NOLOCK)
					ON	tct.comp_id			= tctl.comp_id			AND
						tct.ct_transaction	= tctl.ct_transaction

--				INNER JOIN tbCustomer								tc
--					ON	tc.comp_id			= tct.comp_id			AND
--						tc.cust_id			= tct.cust_id

				INNER JOIN tbUsers4BranchFilter						tubf		WITH (NOLOCK)
					ON	tubf.comp_id		= tct.comp_id			AND
						tubf.bra_id			= tct.bra_id			AND
						tubf.[user_id]		= @user_id

				INNER JOIN tbApplication							ta			WITH (NOLOCK)
					ON	ta.comp_id					= tctl.comp_id	AND
						ta.ct_transaction_Source	= tctl.ct_transaction



			WHERE		tctl.comp_id		= @comp_id				AND
						tct.cust_id			= @cust_id				AND
						tct.ct_date	between @datefrom and @dateto	AND
						--tctl.ctl_id			= ta.ctl_id_Destiny		AND
						tctl.ctl_id			= ta.ctl_id_Source		AND
						tct.ct_transaction	NOT IN (	SELECT vctpoa.ct_transaction
															FROM vwCommercialTransactions_PaymentOnAccount vctpoa  WITH (NOLOCK) )  -- Otra vez ???????????????
						--tctl.ct_ABalance	<> 0

		UNION


			SELECT
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction)	+ ' | ' +
				'#--'																				+ ' | ' +
				dbo.fnStrFromDecimal(tct.ct_ATotal, 13, 2, 12)														+ ' | ' +
				dbo.fnStrFromDecimal(tct.ct_ABalance, 13, 2, 12)													[Desc],
				CONVERT(VARCHAR,tct.ct_transaction) + ' | ' +  '-1'	+ ' | ' + '-1'					[Id]
			FROM tbCommercialTransactions							tct		WITH (NOLOCK)

				INNER JOIN tbCustomer								tc		WITH (NOLOCK)
					ON	tc.comp_id			= tct.comp_id			AND
						tc.cust_id			= tct.cust_id

				INNER JOIN tbUsers4BranchFilter						tubf	WITH (NOLOCK)
					ON	tubf.comp_id		= tct.comp_id			AND
						tubf.bra_id			= tct.bra_id			AND
						tubf.[user_id]		= @user_id

				--HICE ESTA NEGRADA HIPER NEGRA STL STL STL PROBAR PRIMERO, PUTEARME DESPUÉS
				--MOH HABIA GRABADO DE UNA FORMA LOS CT_TRANSACTIONS EN LA APPLICATION, PERO RESULTA QUE ERA AL REVES
				--YO LO GRABE DE LA FORMA QUE LOGICAMENTE ES LA CORRECTA. POR ESO PUSE EL OR PARA ABARCAR
				--LO DEL DERECHO Y LO DEL REVES
				INNER JOIN tbApplication							ta		WITH (NOLOCK)
					ON	ta.comp_id					= tct.comp_id	AND
						--(ta.ct_transaction_destiny	= tct.ct_transaction OR
						 ta.ct_transaction_Source	= tct.ct_transaction


			WHERE		tct.comp_id			= @comp_id				AND
						tct.cust_id			= @cust_id				AND
						tct.ct_date	between @datefrom and @dateto	AND
						--tct.ct_ABalance		<> 0					AND
						--LO DE ABAJO ESTABA COMENTADO
						---------------------------------------------------------------------
						tct.ct_transaction	NOT IN (SELECT tctl.ct_transaction
						                  				FROM tbCommercialTransactionsLoan tctl		WITH (NOLOCK)
						                  				WHERE	tct.comp_id = tct.comp_id AND
						                  						tct.cust_id = tct.cust_id)
						                  								AND
						---------------------------------------------------------------------
						tct.ct_transaction	NOT IN (SELECT vctpoa.ct_transaction
														FROM vwCommercialTransactions_PaymentOnAccount vctpoa	WITH (NOLOCK))  -- Segui asi, van 4 en 5 minutos . . .
		END



GO




CREATE PROCEDURE [dbo].[spCuotaApplication_GetOnAccountDocuments]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@user_id	INT,
	@cust_id	INT
)
AS

	SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------




		BEGIN

			-- ------------------------------
			-- TESTING
			-- ------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@lang_id	INT,
					@bra_id		INT,
					@user_id	INT,
					@cust_id	INT
				SELECT
					@comp_id	= 1,
					@lang_id	= 2,
					@bra_id		= 1,
					@user_id	= 119,
					@cust_id	= 24484
			*/
			-- ------------------------------

				declare @d int
				set		@d = 2



			-- ACA OBTENGO LOS COMPROBANTES A FAVOR DEL CLIENTE PARA APLICAR A LAS CUOTAS

--			SELECT
--				dbo.fnGetCommercialTransactionDescription(ct.comp_id,@lang_id,ct.ct_transaction)	+ ' | ' +
--				CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),ROUND(ct.[ct_ATotal],@d)))					+ ' | ' +
--				CONVERT(VARCHAR,CONVERT(DECIMAL(18,2),ROUND(ct.ct_ABalance,@d)))					[Desc],
--				CONVERT(VARCHAR,ct.ct_transaction) + ' | ' + '-1'									[Id]
--
--				FROM	dbo.tbCommercialTransactions									ct
--
--						INNER JOIN dbo.[vwCommercialTransactions_PaymentOnAccount]		VCTFS
--						On	VCTFS.comp_id				=	ct.comp_id
--						and VCTFS.bra_id				=	ct.bra_id
--						and VCTFS.ct_transaction		=	ct.ct_transaction
--
--						INNER JOIN [tbsysCurrency]										sct
--						on  sct.[curr_id]				=	ct.[curr_id_transaction]
--
--						INNER JOIN tbUsers4BranchFilter									vubf
--						ON	vubf.comp_id				=	ct.comp_id
--						AND	vubf.bra_id					=	ct.bra_id
--						AND	vubf.[user_id]				=	@user_id
--
--
--			WHERE		ct.comp_id						= @comp_id					AND
--						ct.bra_id						= @bra_id					AND
--						ct.ct_ABalance					<> 0						AND
--						--PREGUNTAR A MOS
--						NOT ct.sd_id					IN (56,66,156,166)			AND
--						ct.cust_id						= @cust_id
--
--			ORDER BY [Desc] ASC

			SELECT
				dbo.fnGetCommercialTransactionDescription(ct.comp_id,@lang_id,ct.ct_transaction)	+ ' | ' +
				CASE
					WHEN tctl.comp_id IS NULL THEN
						 dbo.fnStrFromDecimal(CONVERT(DECIMAL(18,2),ct.[ct_ATotal]), 13, 2, 12)			+ ' | ' +
						 dbo.fnStrFromDecimal(CONVERT(DECIMAL(18,2),ct.ct_ABalance), 13, 2, 12)
				ELSE
						dbo.fnStrFromDecimal(CONVERT(DECIMAL(18,2),tctl.ct_ATotal), 13, 2, 12)			+ ' | ' +
						dbo.fnStrFromDecimal(CONVERT(DECIMAL(18,2),tctl.ct_ABalance), 13, 2, 12)
				END																					[Desc],
				CONVERT(VARCHAR,ct.ct_transaction)													+ ' | ' +
				CASE
					WHEN tctl.comp_id IS NULL THEN
							CONVERT(VARCHAR,'-1')
				ELSE
							CONVERT(VARCHAR,tctl.ctl_id)
				END																					[Id]

				FROM	dbo.tbCommercialTransactions									ct

						LEFT JOIN tbCommercialTransactionsLoan							tctl
							ON	tctl.comp_id		= ct.comp_id						AND
								tctl.ct_transaction = ct.ct_transaction

						INNER JOIN dbo.[vwCommercialTransactions_PaymentOnAccount]		VCTFS WITH (NOLOCK)
							ON	VCTFS.comp_id				=	ct.comp_id				AND
								--VCTFS.bra_id				=	ct.bra_id				AND
								VCTFS.ct_transaction		=	ct.ct_transaction

						INNER JOIN [tbsysCurrency]										sct
							ON  sct.[curr_id]				=	ct.[curr_id_transaction]

						INNER JOIN tbUsers4BranchFilter									vubf
							ON	vubf.comp_id				=	ct.comp_id				AND
								vubf.bra_id					=	ct.bra_id				AND
								vubf.[user_id]				=	@user_id


			WHERE		ct.comp_id						= @comp_id					AND
						ct.bra_id						= @bra_id					AND
						(
							0 <>
							CASE
								WHEN tctl.comp_id IS NULL THEN
									ct.ct_ABalance
							ELSE
									tctl.ct_ABalance
							END
						)															AND
						--ct.ct_ABalance					<> 0						AND
						--PREGUNTAR A MOS
						NOT ct.sd_id					IN (56,66,156,166)			AND
						ct.cust_id						= @cust_id

			ORDER BY [Desc] ASC


		END

GO
















