CREATE PROCEDURE [dbo].[spCurrencyExchange_getCurrentExchange]
(
	@comp_id			int	,
	@curr_id_1			int ,
	@curr_id_2			int
)
AS

BEGIN

	SET NOCOUNT ON

	/*
	DECLARE @comp_id			int	,
		@curr_id_1			int ,
		@curr_id_2			INT
		SELECT @comp_id			=1	,
		@curr_id_1			=5 ,
		@curr_id_2			=1
	*/



	select		ltrim(rtrim(tc.curr_symbol)) + ' 1 : ' + ltrim(rtrim(tc2.curr_symbol)) + ' ' +
				convert(varchar,convert(decimal(19,4),round(dbo.fnGetExchange2(@comp_id, 1, @curr_id_1, @curr_id_2, @curr_id_1,@curr_id_1,1,'false'),4))) [exchange]

	from		tbsysCurrency		tc						WITH (NOLOCK)

				INNER JOIN tbsysCurrency		tc2			WITH (NOLOCK)
				ON tc2.curr_id = @curr_id_2

	WHERE		tc.curr_id = @curr_id_1

END






GO







