-- ------------------------------------------------------------------------
-- MOS
-- 01-2009
-- Actualiza automaticamente la cotizacion del dolar o euro cada 30 minutos
-- según lo diga la compañia.-
-- ------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spCurrencyExchange_updateExchange4Argentina]
as

BEGIN

	SET NOCOUNT ON;



    BEGIN TRANSACTION
    BEGIN TRY

		-- ------------------------------------
		-- Bloquear la base antes de hacer nada
		-- ------------------------------------
		DECLARE @intLock AS INT
		SELECT @intLock = tce.sb_id
			FROM tbsysBlockPage4IsoTran  tce
		-- ------------------------------------



		-- ---------------------------------------------------------------------------------------------------------
		-- Esto se usa para que cree la tabla de historial ya que se actualizo en 001 antes de generar version
		-- ---------------------------------------------------------------------------------------------------------
		IF NOT EXISTS (	SELECT TOP 1 1
							FROM sysobjects
		               		WHERE xtype = 'U' AND NAME ='tbCurrencyExchangeUpdateHistory')
			BEGIN

				DECLARE @strExecute AS NVARCHAR(MAX)
				SET @strExecute = '

				CREATE TABLE [dbo].[tbCurrencyExchangeUpdateHistory](
					[comp_id] [int] NOT NULL,
					[ceu_id] [int] IDENTITY(1,1) NOT NULL,
					[ceu_cd] [datetime] NULL CONSTRAINT [DF_tbCurrencyExchangeUpdateHistory_ceu_cd]  DEFAULT (getdate()),
					[ceu_USD] [decimal](19, 4) NULL,
					[ceu_EUR] [decimal](19, 4) NULL,
				 CONSTRAINT [PK_tbCurrencyExchangeUpdateHistory_1] PRIMARY KEY CLUSTERED
				(
					[comp_id] ASC,
					[ceu_id] ASC
				)WITH (PAD_INDEX  = OFF, STATISTICS_NORECOMPUTE  = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS  = ON, ALLOW_PAGE_LOCKS  = ON) ON [PRIMARY]
				) ON [PRIMARY]

											'
				EXEC (@strExecute)

			END
		-- ---------------------------------------------------------------------------------------------------------


		DECLARE @bitComp_DolarUpdate		AS BIT
		DECLARE @bitComp_EuroUpdate			AS BIT
		DECLARE @bitComp_DolarUpdate_offSet	AS DECIMAL(19,6)
		DECLARE @bitComp_EuroUpdate_offSet	AS DECIMAL(19,6)
		DECLARE @bitIsUpdated AS BIT
		DECLARE @decExchange				AS DECIMAL(19,6) = 0
		DECLARE @decExchange2USD			AS DECIMAL(19,6) = 0
		DECLARE @decExchange2EUR			AS DECIMAL(19,6) = 0

		SET @decExchange     = -1
		SET @decExchange2USD = -1
		SET @decExchange2EUR = -1
		SET @bitIsUpdated = 'False'


		DECLARE @compId AS integer


		DECLARE curCompany CURSOR LOCAL FAST_FORWARD FOR
												SELECT comp_id
													FROM tbCompany tc		WITH (NOLOCK)
													WHERE	(tc.comp_DolarUpdate = 'True' OR
															tc.comp_EuroUpdate	= 'True' )
		OPEN curCompany
		FETCH NEXT FROM curCompany INTO @compId



		WHILE @@FETCH_STATUS = 0
			BEGIN




						-- Chequea si ya se actualizo en los ultimos 480 minutos.-
						IF (
										SELECT TOP 1 DATEDIFF(minute, tceuh.ceu_cd,GETDATE())
											FROM tbCurrencyExchangeUpdateHistory tceuh		WITH (NOLOCK)
											WHERE tceuh.comp_id = @compId
											ORDER BY tceuh.ceu_id DESC
							) > 480  -- cada 8 horas.  NO BAJAR este tiempo.  si hay corridas q lo cambien a mano.
							OR
							-- o SI AUN NO HAY NINGUN TIPO DE CMBIO EFECTUADO
							NOT EXISTS(
										SELECT TOP 1  1
											FROM tbCurrencyExchangeUpdateHistory tceuh		WITH (NOLOCK)
											WHERE tceuh.comp_id = @compId
											ORDER BY tceuh.ceu_id DESC
										)
							BEGIN



								DECLARE @comp_currencyUpdateMethod AS INT
								SET		@comp_currencyUpdateMethod = 0
								SET @bitIsUpdated = 'False'
								SELECT	@bitComp_DolarUpdate		= isnull(comp_DolarUpdate,'false'),
										@bitComp_EuroUpdate			= isnull(comp_EuroUpdate,'false'),
										@bitComp_DolarUpdate_offSet = ISNULL(Comp_DolarUpdate_offSet,0),
										@bitComp_EuroUpdate_offSet	= ISNULL(Comp_EuroUpdate_offSet,0),
										@comp_currencyUpdateMethod  = ISNULL(tc.comp_currencyUpdateMethod,0)
									FROM tbCompany tc		WITH (NOLOCK)
									WHERE tc.comp_id = @compId



								-- Dolar
								IF @bitComp_DolarUpdate	= 'True'
									BEGIN

										--SELECT @compId,'Dolar'

										IF @comp_currencyUpdateMethod = 0
											BEGIN
												SET @decExchange = dbo.clrGetExchange4Argentina(2)
											END
										ELSE
											BEGIN
												SET @decExchange = dbo.clrGetBNAExchange4Argentina(2)
											END

										IF @decExchange <> -1 AND @decExchange <> 0 AND @decExchange BETWEEN 900 AND 40000 -- esto ultimo porque a veces hacen cualquier mierda con el promedio
											BEGIN																		-- El día que haya que correr los 500, mejor VAYAMOSNOS TODOS A LA MIERDA !!!

												SET @decExchange = (@decExchange + @bitComp_DolarUpdate_offSet)
												UPDATE tbCurrencyExchange	WITH (ROWLOCK)
													SET
														ce_exchange				= @decExchange,
														ce_exchange_purchase	= @decExchange
													WHERE
															comp_id		= @compId
														and curr_id_1	= 1
														and curr_id_2	= 2
												SET @decExchange2USD = @decExchange

												SET @decExchange = 1 / dbo.fnNoZDiv( @decExchange )
												UPDATE tbCurrencyExchange	WITH (ROWLOCK)
													SET
														ce_exchange				= @decExchange,
														ce_exchange_purchase	= @decExchange
													WHERE
															comp_id		= @compId
														and curr_id_1	= 2
														and curr_id_2	= 1


												SET @bitIsUpdated = 'True'
											END
									END

								-- Euro
								IF @bitComp_EuroUpdate = 'True'
									BEGIN

										--SELECT @compId,'Euro'

										IF @comp_currencyUpdateMethod = 0
											BEGIN
												SET @decExchange = dbo.clrGetExchange4Argentina(4)
											END
										ELSE
											BEGIN
												SET @decExchange = dbo.clrGetBNAExchange4Argentina(4)
											END


										IF @decExchange <> -1 AND @decExchange <> 0 AND @decExchange BETWEEN 900 AND 40000  -- esto ultimo porque a veces hacen cualquier mierda con el promedio
											BEGIN																		    -- Si baja de 40, ALABADO SEA ALBERTO (%$#&%"&%##&##%#%)

												SET @decExchange = (@decExchange + @bitComp_EuroUpdate_offSet)
												UPDATE tbCurrencyExchange	WITH (ROWLOCK)
													SET
														ce_exchange				= @decExchange,
														ce_exchange_purchase	= @decExchange
													WHERE
															comp_id		= @compId
														and curr_id_1	= 1
														and curr_id_2	= 4

												SET @decExchange2EUR = @decExchange
												SET @decExchange = 1 / dbo.fnNoZDiv( @decExchange )
												UPDATE tbCurrencyExchange	WITH (ROWLOCK)
													SET
														ce_exchange				= @decExchange,
														ce_exchange_purchase	= @decExchange
													WHERE
															comp_id		= @compId
														and curr_id_1	= 4
														and curr_id_2	= 1

												SET @bitIsUpdated = 'True'

											END
									END




								IF @bitIsUpdated = 'True'
									BEGIN
										--POr compatibilidad anterior.

										INSERT INTO tbCurrencyExchangeUpdateHistory	WITH (ROWLOCK)
										(
											comp_id,
											ceu_USD,
											ceu_EUR
										)
										VALUES
										(
											@compId,
											@decExchange2USD,
											@decExchange2EUR
										)
									END

							END

						FETCH NEXT FROM curCompany INTO @compId

			END
		CLOSE		curCompany
		DEALLOCATE	curCompany

		COMMIT TRANSACTION
    END TRY
    BEGIN CATCH
		ROLLBACK TRANSACTION
    END CATCH



END










GO


-- =============================================
-- Author:		MOS  02-2012
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spCustomer_FreeITTransactionSelected]
	@comp_id AS INT,
	@cust_id AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- ----------------------------------------------------------------------------
	-- Des-Selecciona items que habian sido seleccionados antes y no estan en False
	-- ----------------------------------------------------------------------------
	UPDATE tbItemTransactions	--WITH (ROWLOCK)
		SET it_packingInvoiceSelected		= 'False'
		FROM tbItemTransactions tmp						--	WITH (NOLOCK)
		INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
			ON		tct.comp_id				= tmp.comp_id
				AND tct.bra_id				= tmp.bra_id
				AND tct.ct_transaction		= tmp.ct_transaction
		WHERE	tmp.comp_id						= @comp_id
			AND tmp.it_packingInvoiceSelected	= 'true'
			AND tct.cust_id						= @cust_id
	-- ----------------------------------------------------------------------------


	IF EXISTS(
				SELECT TOP 1 1
					from tbCommercialTransactions tct			WITH (NOLOCK)
					WHERE	tct.comp_id					    = @comp_id
						AND tct.cust_id						= @cust_id
						AND tct.ct_isSelected				= 'True'
				)
		BEGIN
			UPDATE tbCommercialTransactions		--WITH (ROWLOCK)
			SET
				ct_isSelected = 'False'
				from tbCommercialTransactions tct			--WITH (NOLOCK)
				WHERE	tct.comp_id					    = @comp_id
					AND tct.cust_id						= @cust_id
					AND tct.ct_isSelected				= 'True'
		END

END
GO






-- =============================================
-- Author:		MOS
-- Create date: 10-2008
-- Description:	Retorna el Estado de Credito del
---				Cliente
-- =============================================

CREATE PROCEDURE [dbo].[spCustomer_getBalanceStatus]
(
	@comp_id					as	int,
	@curr_id					as	int,
	@cust_id					as	int,
	@user_id				    AS  INT,
	@branchProcessingDate		as DATETIME,
	@bra_id						AS INT,
	@soh_id						AS INT
)
AS

BEGIN

	SET NOCOUNT ON;

-- -----------------------------------------------------------------
-- TEsting
-- -----------------------------------------------------------------
/*
	DECLARE	@comp_id					as	int,
			@curr_id					as	int,
			@cust_id					as	int,
			@user_id					INT,
			@branchProcessingDate		as DATETIME,
			@bra_id						INT,
			@soh_id						INT
	SELECT 	@comp_id					=1,
			@curr_id					=2,
			@cust_id					=807,
			@user_id					=1,
			@branchProcessingDate		='2011/11/08',
			@bra_id						=-1,
			@soh_id						=500
*/
-- -----------------------------------------------------------------

	set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	/******************************************************************************************************/
	--copia del query de spCollectionTmp_getDataToAccount que retorna los comprobantes a cuenta en la
	--página de cobranzas
	--es sólo para retonar una marca que indica si hay datos a cuenta e informarlo al usuario
	--este sp sólo se utiliza en wfmCollection, wfmCommercialTransactions y wfmSaleOrder
	--probado y chequeado en los 3 lugares 08/11/2011 MOH
	DECLARE @OnAccount	BIT

	SET @OnAccount = 'false'

	IF EXISTS (	SELECT TOP 1 1

				FROM	dbo.tbCommercialTransactions								ct

						INNER JOIN dbo.[vwCommercialTransactions_PaymentOnAccount]	VCTFS	WITH (NOLOCK)
						On	VCTFS.comp_id					=	ct.comp_id
						--and VCTFS.bra_id					=	ct.bra_id
						and VCTFS.ct_transaction			=	ct.ct_transaction

						INNER JOIN [tbsysCurrency]									sct
						on  sct.[curr_id]					=	ct.[curr_id_transaction]

						INNER JOIN	[tbBranch]										b1
						on	b1.[comp_id]					=	ct.[comp_id]
						and b1.[bra_id]						=	@bra_id

						INNER JOIN tbUsers4BranchFilter								vubf
						ON	vubf.comp_id					=	ct.comp_id
						AND	vubf.bra_id						=	ct.bra_id
						AND	vubf.[user_id]					=	@user_id

						INNER JOIN tbBranch tbj
							ON tbj.comp_id = CT.comp_id AND
								tbj.bra_id = CT.bra_id

				WHERE	ct.[comp_id]						=	@comp_id
				AND		ct.[cust_id]						=	@cust_id
				AND 	ct.[curr_id_transaction]			=   b1.curr_id
				AND     ct.[ct_Abalance]					<>	0
				AND 	ct.[ct_docNumber]					<>	''

				AND 	((b1.bra_CollectionOfAllBranches	=	'True'
						AND tbj.curr_id = @curr_id
							/*ct.bra_id in (SELECT bra_id FROM [tbBranch] WHERE curr_id = @curr_id)*/) OR

						(b1.bra_CollectionOfAllBranches		=	'False'
						AND ct.bra_id						=	@bra_id))
				)
		BEGIN
			SET @OnAccount = 'true'
		END
	/*************************************************************************************************************/


	DECLARE @bra_Credit_AssumeValuesAcreditDays AS INT
	SET	   @bra_Credit_AssumeValuesAcreditDays = 4
	SELECT @bra_Credit_AssumeValuesAcreditDays = tb.bra_Credit_AssumeValuesAcreditDays
		FROM tbBranch tb
		WHERE	tb.comp_id									= @comp_id	AND
				tb.bra_id									= @bra_id

			--AND
			--	tb.bra_Credit_AssumeAcredit2DaysPostDate	= 'True'






	Select	cust_credit_max					,
			cust_credit_own					,
			cust_credit_cheque_own_used		,
			cust_credit_cheque_3rd_used		,
			cust_credit_SaleOrder			,
			cust_credit_balance				,
			cust_credit_balance_OverCome	,
			cust_credit_balance_NotOverCome	,
			cust_credit_balance_OverComeWithTolerance,
			cust_id,
			(SELECT curr_symbol
				FROM tbsysCurrency tc
				WHERE tc.curr_id = @curr_id)	[curr_symbol],

			ISNULL(@OnAccount,'false')												[onAccount],
			@bra_Credit_AssumeValuesAcreditDays										[bra_Credit_AssumeValuesAcreditDays]

	From	dbo.fnCustomer_getBalanceStatus(@comp_id,@curr_id,@cust_id,@user_id,@branchProcessingDate,@bra_id,@soh_id)


END
GO




CREATE PROCEDURE [dbo].[spCustomer_getBalanceStatusGrid]
(
	@comp_id					AS	INT,
	@lang_id					AS  INT,
	@page_id					AS	INT,
	@curr_id					AS	INT,
	@cust_id					AS  INT,
	@user_id				    AS  INT,
	@strBranchProcessingDate	AS  VARCHAR(10)
)
AS


BEGIN

	SET DATEFORMAT 'YMD'
	SET NOCOUNT ON;


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- --------------------------------------------------------
	-- TESTING
	-- --------------------------------------------------------
	/*
		DECLARE
			@comp_id					AS	INT,
			@lang_id					AS  INT,
			@page_id					AS	INT,
			@curr_id					AS	INT,
			@cust_id					AS  INT,
			@user_id				    AS  INT,
			@strBranchProcessingDate	AS  VARCHAR(10)
		SELECT
			@comp_id					= 1,
			@lang_id					= 2,
			@page_id					= 15,
			@curr_id					= 1,
			@cust_id					= 24454,
			@user_id				    = 119,
			@strBranchProcessingDate	= '2015-9-25'

			DROP TABLE #tmp
	*/
	-- --------------------------------------------------------


	DECLARE @BranchProcessingDate AS DATETIME
	SET @BranchProcessingDate = CONVERT(DATETIME,@strBranchProcessingDate)

	/*
	drop table #tmp
	*/


	SELECT
		*
	INTO	#tmp
	FROM  fnCustomer_getBalanceStatus(
										@comp_id,
										@curr_id,
										@cust_id,
										@user_id,
										@branchProcessingDate,
										-1,
										-1
									 )



--SELECT * FROM #tmp

	--------------------------------
	SELECT * FROM
	(






			(--1
			 SELECT
				'1) ' + tswn.word_desc								[Desc],
				CONVERT(DECIMAL(19,2),t.cust_credit_own)	[Total]
				FROM  #tmp t,tbsysTextsNew					ttn
					INNER JOIN tbSysWordsNew				tswn
						ON	   tswn.wordsi_id	= ttn.wordsi_id
				 WHERE tswn.lang_id				= 2
				  AND  ttn.page_id				= 15
				  AND  ttn.[type_id]			= 1
				  AND  ttn.ctrl_id				= 1138
			)

		UNION
			(--2
			 SELECT
				'2) ' + tswn.word_desc,
				CONVERT(DECIMAL(19,2),t.cust_credit_max)
				FROM	#tmp t,tbsysTextsNew			ttn
					INNER JOIN tbSysWordsNew			tswn
						ON	    tswn.wordsi_id	= ttn.wordsi_id
				 WHERE  tswn.lang_id			= 2		AND
						ttn.page_id				= 15	AND
						ttn.[type_id]			= 1		AND
						ttn.ctrl_id				= 205
			)
		UNION
			(--3
			 SELECT
				'3) ' + tswn.word_desc,
				CONVERT(DECIMAL(19,2),t.cust_credit_cheque_own_used)
				FROM  #tmp t,tbsysTextsNew							ttn
					INNER JOIN tbSysWordsNew						tswn
						ON	   tswn.wordsi_id	= ttn.wordsi_id
				 WHERE	tswn.lang_id			= 2					AND
						ttn.page_id				= 15				AND
						ttn.[type_id]			= 1					AND
						ttn.ctrl_id				= 1139
			)
		UNION
			(--4
			 SELECT
				'4) ' + tswn.word_desc,
				CONVERT(DECIMAL(19,2),cust_credit_cheque_3rd_used)
				FROM   #tmp,tbsysTextsNew							ttn
					INNER JOIN tbSysWordsNew						tswn
					ON	   tswn.wordsi_id	= ttn.wordsi_id
				WHERE	tswn.lang_id		= 2						AND
						ttn.page_id			= 15					AND
						ttn.[type_id]		= 1						AND
						ttn.ctrl_id			= 1140
			)
		UNION
			(--5
			 SELECT
				'5) ' + tswn.word_desc,
				CONVERT(DECIMAL(19,2),cust_credit_SaleOrder)
				FROM #tmp,tbsysTextsNew								ttn
				INNER JOIN tbSysWordsNew							tswn
					ON	   tswn.wordsi_id	= ttn.wordsi_id
				WHERE	tswn.lang_id		= 2						AND
						ttn.page_id			= 15					AND
						ttn.[type_id]		= 1						AND
						ttn.ctrl_id			= 1141
			)
		UNION
			(--6
			 SELECT
				'6) ' + tswn.word_desc,
				CONVERT(DECIMAL(19,2),cust_credit_balance)
				FROM #tmp,tbsysTextsNew								ttn
					INNER JOIN tbSysWordsNew						tswn
						ON	   tswn.wordsi_id	= ttn.wordsi_id
				WHERE	tswn.lang_id			= 2					AND
						ttn.page_id				= 15				AND
						ttn.[type_id]			= 1					AND
						ttn.ctrl_id				= 207
			)
		UNION
			(--7
			 SELECT
				'7) ' + tswn.word_desc,
				CONVERT(DECIMAL(19,2),cust_credit_balance_OverCome)
				FROM #tmp,tbsysTextsNew								ttn
					INNER JOIN tbSysWordsNew						tswn
					ON	   tswn.wordsi_id	= ttn.wordsi_id
				WHERE	tswn.lang_id		= 2						AND
						ttn.page_id			= 15					AND
						ttn.[type_id]		= 1						AND
						ttn.ctrl_id			= 1142
			)
		UNION
			(--8
			 SELECT
				'8) ' + tswn.word_desc,
				CONVERT(DECIMAL(19,2),cust_credit_balance_NotOverCome)
				FROM #tmp,tbsysTextsNew								ttn
					INNER JOIN tbSysWordsNew						tswn
						ON	   tswn.wordsi_id	= ttn.wordsi_id
				WHERE	tswn.lang_id			= 2					AND
						ttn.page_id				= 15				AND
						ttn.[type_id]			= 1					AND
						ttn.ctrl_id				= 1143
			)

		UNION


			(--Disponible
			 SELECT
				'9) ' + tut.utexts_desc				[Desc],
				CONVERT(DECIMAL(19,2),t.cust_credit_max - (cust_credit_balance + cust_credit_cheque_own_used + cust_credit_cheque_3rd_used + cust_credit_SaleOrder))
											[Total]
				FROM  #tmp t
				INNER JOIN tbsysUniqueTexts tut
					ON	tut.lang_id = @lang_id AND
						tut.utexts_id = 442
			)




	)AS R



END
GO




















