CREATE PROCEDURE [dbo].[spCustomer_GetCustomerCommunityURL]
	@cust_GBPComunityID AS UNIQUEIDENTIFIER
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SELECT ISNULL(tc.cust_GBPCommunityURL,'')			[cust_GBPCommunityURL]
