-- Clon de GetDataByID pero con cross apply
CREATE PROCEDURE spCustomer_GetCustomerInAlert
(
	@comp_id			INT,
	@bra_id				INT,
	@cust_id			INT,
	@user_id			INT
)
AS



BEGIN



	-- ----------------------------------------------------
	-- Testing
	-- ----------------------------------------------------
/*
	DECLARE @comp_id			INT,
			@cust_id			INT,
			@user_id			INT,
			@bra_id				INT

	SELECT 	@comp_id			=1,
			@cust_id			=24294,
			@user_id			=124,
			@bra_id				=1
*/
	-- ----------------------------------------------------




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE @bitCustomerInAlert AS BIT
	SET @bitCustomerInAlert = 'False'
	IF @cust_id < 0
		BEGIN
			SET @cust_id = @cust_id * -1

		END



	SET NOCOUNT ON


	DECLARE @bitIsInCretitInfoEntity	AS BIT
	DECLARE @bitIsInProtcom				AS BIT
	DECLARE @bitHasCRMNotes				AS BIT

	SET		@bitIsInCretitInfoEntity	= 'False'
	SET		@bitIsInProtcom				= 'False'
	SET		@bitHasCRMNotes				= 'False'

	SELECT @bitHasCRMNotes = 'True'
		FROM tbCRM_Notes			tcn		WITH (NOLOCK)
		INNER JOIN tbCRM_NoteType	tcnt	WITH (NOLOCK)
			ON	tcnt.comp_id				= tcn.comp_id AND
				tcnt.crmnt_id				= tcn.crmnt_id
		WHERE	tcn.comp_id					= @comp_id AND
				tcn.cust_id					= @cust_id AND
				tcnt.crmnt_alertOnSaleOrder = 'True' AND
				tcnt.crmnt_disabled			= 'False'


	SELECT TOP 1 @bitIsInProtcom = 'True'
		FROM tbCustomer				tc		WITH (NOLOCK)
		INNER JOIN tbCreditBehavior_Arg_Protcom tcbap
		ON	tcbap.comp_id			= @comp_id			AND
			tcbap.protcom_taxNumber = tc.cust_taxNumber
		WHERE	tc.comp_id = @comp_id AND
				tc.cust_id = @cust_id


	SELECT TOP 1 @bitIsInCretitInfoEntity = 'True'
		FROM tbCreditBehavior_GeneralInfo tcbgi	WITH (NOLOCK)
		INNER JOIN tbCreditBehavior_Status tcbs
			ON	tcbs.comp_id	= tcbgi.comp_id AND
				tcbs.cis_id		= tcbgi.cis_id
		WHERE	tcbgi.comp_id	= @comp_id		AND
				tcbgi.cust_id	= @cust_id		AND
				tcbs.cis_isAlert= 'True'




	SELECT	c.comp_id,
			c.cust_id,
			c.bra_id,
			IsNull(c.cust_name,'No Name !') + CASE
										WHEN c.cust_SaleOrderBranchTransfer = 'True' THEN ' (*)'
										ELSE										''
									 END													[cust_name],
			c.cust_name1,
			c.fc_id,
			c.cust_taxNumber,
			isnull(c.cust_web,'') cust_web,
			c.cust_inactive,
			isnull(c.cust_partnerOf,'') cust_partnerOf,
			isnull(c.cust_contact,'') cust_contact,
			c.cust_address,
			c.cust_city,
			c.cust_zip,
			c.country_id,
			c.state_id,
			isnull(c.cust_phone1,'')									[cust_phone1],
			isnull(c.cust_phone2,'')					                [cust_phone2],
			isnull(c.cust_cellPhone,'')									[cust_cellPhone_last],
			ISNULL(c.cust_email,'')										[cust_email],
			c.cust_fax,
			c.cust_picture,
			ISNULL(c.sm_id,-1)											[sm_id],
			isnull(s.sm_name,'') sm_name,
			c.ck_id,
			ISNULL(c.st_id,-1)											[st_id],
			ISNULL(c.disc_id,-1)										[disc_id],
			ISNULL(c.dl_id,-1)											[dl_id],
			c.cust_credit_max,
			c.cust_credit_own,
			c.curr_id,
			c.acc_count_id,
			c.user_id,
			ISNULL(c.prli_id,-1)										[prli_id],
			ISNULL(c.stor_id,-1)										[stor_id],
			dbo.fnGetFiscalCustomer_KindOf(c.cust_id) Fiscal_kindOf,
			dbo.fnGetFiscalCustomer_Fiscal_fc_id(c.cust_id) Fiscal_fc_id,
			dbo.fnGetFiscalCustomer_FiscalTaxNumberType(c.cust_id) FiscalTaxNumberType,
			dbo.fnGetFiscalCustomer_Fiscal_fc_id_EpsonAR(c.cust_id) Fiscal_fc_id_EpsonAr,
			cust_isEditing,
			cust_isEditingUserId,
			tc.country_desc,
			c.stcIB_Id,
			ts.state_desc,
			c.cust_note1,
			c.cust_note2,
			c.cust_note3,
			c.cust_note4,
			isnull(c.cust_4InitialValues,'false') cust_4InitialValues,
			c.cust_address4Delivery										[DeliveryAddress],
			IsNull(c.cust_address4Payments,'')							[PaymentAddress],
			ISNULL(c.cust_SaleOrderMaxValue,0)							[cust_SaleOrderMaxValue],
			c.cust_webNickName,
			TTNT.tnt_FiscalPrinterType4EpsonAR,
			IsNull(c.cust_SaleOrderDisableConcurrentProc,'False')		[cust_SaleOrderDisableConcurrentProc],
			IsNull(c.cust_SaleOrderBranchTransfer,'False')				[cust_SaleOrderBranchTransfer],
			ttnt.tnt_OCXHASAR											[tnt_OCXHASAR],
			tfc.FiscalClass4OXCFiscal									[FiscalClass4OXCFiscal],
			c.tnt_id,
			isnull(c.cust_email4RMA,'')									[cust_email4RMA],
			isnull(c.cust_isAvailable4InternalRMA,'False')				[cust_isAvailable4InternalRMA],
			ISNULL(c.cust_contact4RMA,'')								[cust_contact4RMA],
			ISNULL(c.cust_address4RMA,'')								[cust_address4RMA],
			ISNULL(c.rmap_id,0)											[rmap_id],
			ISNULL(tb.bra_SaleOrder_DisableCustomerConcurrentCheck,'False')
																		[bra_SaleOrder_DisableCustomerConcurrentCheck],
			Isnull(c.cust_disabled4PersonalLoan,'False')				[cust_disabled4PersonalLoan],
			ISNULL(c.cust_annotation,'')								[cust_annotation],
			CASE
				WHEN c.cust_checked IS NULL THEN	'True'
				ELSE								'False'
			END															[cust_Pend2VerifyInsert],

			CASE
				WHEN tcf.cust_credit_balance_OverCome > 0		THEN 'True'
				WHEN tccr.rating_AlertOnInfo	= 'True'		THEN 'True'
				WHEN @bitIsInCretitInfoEntity	= 'True'		THEN 'True'
				WHEN @bitIsInProtcom			= 'True'		THEN 'True'
				WHEN @bitHasCRMNotes			= 'True'		THEN 'True'
				WHEN tcdl.def_isAlert			= 'True'		THEN 'True'
				ELSE												 'False'
			END															[customerInAlert]







	FROM 	dbo.tbCustomer							c			WITH (NOLOCK)

			LEFT JOIN dbo.tbSalesman				s			WITH (NOLOCK)
			ON 	s.comp_id			= c.comp_id
			AND s.sm_id				= c.sm_id

			LEFT JOIN dbo.tbsysCountry				tc			WITH (NOLOCK)
			ON	tc.country_id		= c.country_id

			LEFT JOIN tbsysState					ts			WITH (NOLOCK)
			ON	ts.state_id			= c.state_id

			LEFT JOIN tbsysTaxNumberTypes ttnt					WITH (NOLOCK)
				ON ttnt.tnt_id	= C.tnt_id

			LEFT JOIN tbsysFiscalClass tfc						WITH (NOLOCK)
				ON tfc.fc_id	= c.fc_id

			LEFT JOIN tbBranch tb								WITH (NOLOCK)
				ON	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id


			LEFT JOIN tbCustomerDefaultLevel tcdl				WITH (NOLOCK)
				ON	tcdl.comp_id	= c.comp_id		AND
					tcdl.def_id		= c.def_id

			LEFT JOIN tbCustomerCreditRating tccr				WITH (NOLOCK)
				ON	tccr.comp_id	= c.comp_id AND
					tccr.rating_id	= c.rating_id


			CROSS APPLY dbo.fnCustomer_getBalanceStatus(@comp_id,
														CASE
															WHEN tb.bra_id IS NOT NULL	THEN tb.curr_id
															ELSE						     c.curr_id
														END, @cust_id, @user_id,
														CASE
															WHEN tb.bra_id IS NOT NULL	THEN tb.bra_processingDate
															ELSE						     GETDATE()
														END,
														@bra_id,
														-4)	tcf




	WHERE	c.comp_id				= @comp_id
	AND		c.cust_id				= @cust_id



END
GO







CREATE PROCEDURE [dbo].[spCustomer_getData]
(
	@comp_id			INT
)
AS
SET NOCOUNT ON



SELECT 	c.comp_id,					c.cust_id,						c.bra_id,
		c.cust_name + CASE
		                  WHEN c.cust_SaleOrderBranchTransfer = 'True' THEN ' (*)'
		                  ELSE												''
		              END			[cust_name],
		c.cust_name1,					c.fc_id,
		c.cust_taxNumber,			c.stcIB_Id,						c.cust_taxIBNumber,
		c.cust_web,					c.cust_inactive,				c.cust_partnerOf,
		c.cust_contact,				c.cust_address,					c.cust_city,
		c.cust_zip,					c.country_id,					c.state_id,
		c.cust_phone1,				c.cust_phone2,					c.cust_email,
		c.cust_fax,					c.cust_picture,					c.sm_id,
		c.ck_id,					c.st_id,						c.disc_id,
		c.dl_id,					c.cust_credit_max,				c.cust_credit_own,
		c.curr_id,					c.acc_count_id,					c.[user_id],
		c.prli_id,					c.stor_id,						c.tnt_id,
		c.ss_id,					c.cust_isEditing,				c.cust_isEditingCd,
		c.cust_isEditingUserId,		c.cust_annotation,				c.cust_judMan,
		c.cust_note1,				c.cust_note2,					c.cust_note3,
		c.cust_note4,				c.cust_address4Delivery,		c.cust_address4Payments,
		c.cust_webNickName,			c.cust_webPassword,				c.bra_id4Emmition,
		c.city_id,					c.cust_4InitialValues,			c.sm_id_2,
		c.cust_showstock,			c.cust_showpricelist,			c.cust_showzerostockitems,
		c.cust_login,				c.cust_login_cd,				c.cust_login_ip,
		c.cust_login_name,			c.cust_SaleOrderMaxValue

FROM 	tbCustomer				c

WHERE 	c.comp_id	= @comp_id
GO






CREATE PROCEDURE [dbo].[spCustomer_GetData4AM]
(
	@strCG AS NVARCHAR(100)
)
AS

BEGIN


	SET NOCOUNT ON

	--DECLARE @guiCG AS UNIQUEIDENTIFIER
	--SET @guiCG = CONVERT(UNIQUEIDENTIFIER,@strCG)

	SELECT	tc.cust_GBPUrl,
			tc.cust_GBPModules,
			tc.cust_GBPDbName,
			tc.cust_GBPUserQty,
			tc.cust_GBPBranchQty,
			tc.cust_GBPCompanyQty,
			tc.cust_GBPLastURLUpdate,
			tc.cust_GBPCG ,
			tc.cust_GBPSN								[cust_GBPSerial],
			convert(nvarchar(4),YEAR(ISNULL(tc.cust_GBPLPD,GETDATE() + 9999))) + '-' +
			convert(nvarchar(2),MONTH(ISNULL(tc.cust_GBPLPD,GETDATE() + 9999))) + '-' +
			convert(nvarchar(2),DAY(ISNULL(tc.cust_GBPLPD,GETDATE() + 9999)))						[cust_GBPMaxProsessingDate],
			ISNULL(tc.cust_GBPComunityID,NEWID())													[cust_GBPComunityID],
			ISNULL(tc.cust_GBPInProduction,'True')													[cust_GBPInProduction]
		FROM tbCustomer tc	WITH (NOLOCK)
		WHERE	tc.cust_GBPCG		= @strCG AND
				-- --------------------------------------------------------
				-- OJO !!!  si hay varios clientes que usan el mismo GUID para que se informe en la deuda arriba, solo UNO debe tener los datos completos, el resto debe tener los usuarios en CERO !!!
				-- --------------------------------------------------------
				tc.cust_GBPUserQty	> 0
				-- --------------------------------------------------------

END


GO


CREATE PROCEDURE [dbo].[spCustomer_GetData4CreditApplication]
(
	@comp_id	INT,
	@lang_id	INT,
	@page_id	INT,
	@bra_id		INT,
	@cust_id	INT,
	@ReportType	INT	--1 = Solicitud de Crédito / 2 Reactualización de Crédito
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@page_id	INT,
				@bra_id		INT,
				@cust_id	INT,
				@ReportType	INT	--1 = Solicitud de Crédito / 2 Reactualización de Crédito
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@page_id	= 100093,
				@bra_id		= 1,
				@cust_id	= 24294,
				@ReportType	= 1
		*/
		-- -------------------------------------------


		SELECT
			tc.cust_picture,
			tc.cust_name,				--1
			tc.cust_firstname,			--2
			tsc.city_desc,				--3
			tc.cust_zip,				--3
			tcs.street_desc,			--3
			tc.cust_addressNumber,		--3
			tc.cust_addressFloor,		--3
			tc.cust_addressAdditional,	--3
			tc.cust_phone1,				--4
			tc.cust_cellPhone,			--5
			tc.cust_email,				--6
			ttnt.tnt_desc,				--7
			tc.cust_taxNumber,			--8
			tc.cust_birthDay,			--9
			tcms.marst_desc,			--10
										--11
			tc.cust_remuneration,		--12
			ISNULL(tc.cust_jobPayIntervalIs15,'False') [cust_jobPayIntervalIs15],	--13
			tc.cust_ramification,		--14
			tc.cust_jobTitle,			--15
			tc.cust_jobAddress,			--16
			tc.cust_jobPhone,			--17
			tc.cust_jobAdmissionDate,	--18
			tc.cust_jobName,			--19
			CASE WHEN tc.cust_isOwner = 'TRUE' THEN 'Si' ELSE 'No' END [cust_isOwner],			--20
			tc.cust_ownerOf,			--21
			GETDATE()									[CreditAppDate],
			tc.cust_id,
			ISNULL(tcjd.cram_desc,'')					[cram_desc],
			ISNULL(tc.cust_credit_max,0)				[cust_Credit_max],
			tc.cust_4OnlySign

			FROM tbCustomer								tc
				LEFT JOIN tbCities_Streets				tcs
				ON	tcs.comp_id		= tc.comp_id		AND
					tcs.street_id	= tc.street_id
				LEFT JOIN tbSysCities					tsc
				ON	tsc.country_id	= tcs.country_id	AND
					tsc.state_id	= tcs.state_id		AND
					tsc.city_id		= tcs.city_id
				INNER JOIN tbsysTaxNumberTypes			ttnt
				ON	ttnt.tnt_id		= tc.tnt_id
				LEFT JOIN tbCustomerMaritalStatus		tcms
				ON	tcms.comp_id	= tc.comp_id		AND
					tcms.marst_id	= tc.marst_id
				LEFT JOIN tbCustomerJobDepartament		tcjd
				ON	tcjd.comp_id	= tc.comp_id		AND
					tcjd.cram_id	= tc.cram_id
			WHERE	tc.comp_id		= @comp_id			AND
					tc.cust_id		= @cust_id


			DECLARE @func_id	INT
			SET		@func_id	= 1

			EXEC spReports_getData3	@comp_id, @bra_id, @lang_id, @page_id, @func_id

		IF @ReportType = 1
			BEGIN
				SELECT TOP 2
					tcf.custf_name,					--21
					tcs.street_desc,				--23
					tcf.cust_addressNumber,			--23
					tsc.city_desc,					--23
					tcf.custf_addressFloor,			--23
					tcf.custf_addressAdditional,	--23
					tcms.marst_desc,				--22
					tcf.custf_birthDay,				--24
					ttnt.tnt_desc,					--25
					tcf.custf_taxNumber,			--26
					tcf.custf_cellPhone,			--27
					tcf.custf_picture
				FROM tbCustomerFamily						tcf
					LEFT JOIN tbCities_Streets				tcs
					ON	tcs.comp_id		= tcf.comp_id		AND
						tcs.street_id	= tcf.street_id
					LEFT JOIN tbSysCities					tsc
					ON	tsc.country_id	= tcs.country_id	AND
						tsc.state_id	= tcs.state_id		AND
						tsc.city_id		= tcs.city_id
					INNER JOIN tbsysTaxNumberTypes			ttnt
					ON	ttnt.tnt_id		= tcf.tnt_id
					LEFT JOIN tbCustomerMaritalStatus		tcms
					ON	tcms.comp_id	= tcf.comp_id		AND
						tcms.marst_id	= tcf.marst_id
				WHERE	tcf.comp_id		= @comp_id			AND
						tcf.cust_id		= @cust_id
				ORDER BY tcf.custf_id ASC
			END
		ELSE
			BEGIN
				SELECT TOP 1
					tcf.custf_name,					--21
					tcs.street_desc,				--23
					tcf.cust_addressNumber,			--23
					tsc.city_desc,					--23
					tcf.custf_addressFloor,			--23
					tcf.custf_addressAdditional,	--23
					tcms.marst_desc,				--22
					tcf.custf_birthDay,				--24
					ttnt.tnt_desc,					--25
					tcf.custf_taxNumber,			--26
					tcf.custf_cellPhone,			--27
					tcf.custf_picture
				FROM tbCustomerFamily						tcf
					LEFT JOIN tbCities_Streets				tcs
					ON	tcs.comp_id		= tcf.comp_id		AND
						tcs.street_id	= tcf.street_id
					LEFT JOIN tbSysCities					tsc
					ON	tsc.country_id	= tcs.country_id	AND
						tsc.state_id	= tcs.state_id		AND
						tsc.city_id		= tcs.city_id
					INNER JOIN tbsysTaxNumberTypes			ttnt
					ON	ttnt.tnt_id		= tcf.tnt_id
					LEFT JOIN tbCustomerMaritalStatus		tcms
					ON	tcms.comp_id	= tcf.comp_id		AND
						tcms.marst_id	= tcf.marst_id
				WHERE	tcf.comp_id		= @comp_id			AND
						tcf.cust_id		= @cust_id
				ORDER BY tcf.custf_id ASC
			END



			SELECT
				tb.bra_address,
				tb.bra_address1,
				tb.bra_MainDesc,
				UPPER(tb.bra_MainDesc2) [bra_MainDesc2]

				FROM tbBranch							 tb
				WHERE	tb.comp_id		= @comp_id			AND
				tb.bra_id				= @bra_id
	END
GO







CREATE PROCEDURE [dbo].[spCustomer_getDataByEmail]
(
	@comp_id					int,
	@email						NVARCHAR(250),
	@password					NVARCHAR(250),
	@ws_id						UNIQUEIDENTIFIER

)
AS

BEGIN

	SET NOCOUNT ON

	SELECT
				CASE
					WHEN tw.wsu_webPassword = @password		THEN 0
					WHEN tw.wsu_webPassword LIKE '%FB_ID:%'	THEN 1
					ELSE											 2	-- Ya estaba registrado con un email y password
				END															[customer_foundOption],
				tc.comp_id,
				tc.cust_id,
				tc.cust_name,
				tc.cust_name1,
				tc.fc_id,
				tc.cust_taxNumber,
				tw.wsu_webNickName,
				tw.wsu_webPassword
		FROM		tbWebSiteII_Users				AS tw	WITH (NOLOCK)
		INNER JOIN	tbCustomer						AS tc	WITH (NOLOCK)
			ON	tc.comp_id	= tw.comp_id AND
				tc.cust_id	= tw.cust_id
		WHERE	tw.comp_id	= @comp_id	AND
				tw.wsu_webNickName	= @email	AND
				tw.ws_id			= @ws_id
		ORDER BY
				[customer_foundOption]



	SELECT * FROM tbWebSiteII_Users AS twsiu

END




GO






CREATE PROCEDURE [dbo].[spCustomer_getDataByFilters]
(
	@comp_id			INT,
	@cust_name			VARCHAR(100),
	@cust_name1			VARCHAR(100),
	@cust_address		VARCHAR(100),
	@cust_taxNumber		VARCHAR(100),
	@cust_city			VARCHAR(100),
    @cust_zip			VARCHAR(20),
	@cust_Phone1        VARCHAR(100),
	@cust_Phone2		VARCHAR(100),
	@country_id			INT,
	@state_id			INT,
	@user_id			INT,
	@bra_id				INT
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------------------
	/*
	declare @comp_id			INT,
			@cust_name			VARCHAR (100),
			@cust_name1			VARCHAR (100),
			@cust_address		VARCHAR (100),
			@cust_city			VARCHAR (100),
			@cust_zip			VARCHAR (20),
			@cust_taxNumber		VARCHAR (100),
			@cust_Phone1        VARCHAR (100),
			@cust_Phone2		VARCHAR (100),
			@country_id			INT,
			@state_id			INT,
			@user_id			INT,
			@bra_id				INT
	select	@comp_id			=1,
			@cust_name			='',
			@cust_name1			='',
			@cust_address		='',
			@cust_city			='',
			@cust_zip			='',
			@cust_taxNumber		='',
			@cust_Phone1        ='',
			@cust_Phone2		='',
			@country_id			=-1,
			@state_id			=-1,
			@user_id			=60,
			@bra_id				=26
	DROP TABLE #tmpCustomerFilterByUser
	*/
	-- -----------------------------------------------------------------------------------------



	-- Tomo los Grupos de Sucursales a los que pertenece esta sucursal
	DECLARE @tmpBranchsOfBranchGroup TABLE(brag_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchsOfBranchGroup(brag_id)
		SELECT brag_id
			FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
			WHERE	tbgd.comp_id	= @comp_id AND
					tbgd.bra_id		= @bra_id






	DECLARE @tblCustomerFilterByUser TABLE (cust_id INT PRIMARY KEY )

	INSERT INTO @tblCustomerFilterByUser
		SELECT  DISTINCT  c.cust_id
		FROM 	tbCustomer										c
		INNER JOIN tbBranch								tb
			ON  tb.comp_id				= c.comp_id
			AND tb.bra_id				= @bra_id
		INNER JOIN vwCustomerFilterByUser				vcfbu
			ON	vcfbu.comp_id			= c.comp_id
			AND vcfbu.cust_id			= c.cust_id
			AND (vcfbu.sm_id			= c.sm_id	OR c.sm_id IS NULL)
			AND	(tb.bra_CustomerSelectionByUserId = 'true' AND	vcfbu.[user_id] = @user_id)
		WHERE   c.comp_id				 =  @comp_id

	if @@ROWCOUNT = 0
	BEGIN

		INSERT	INTO @tblCustomerFilterByUser
		SELECT  distinct c.cust_id
		FROM 	tbCustomer						c
		WHERE   c.comp_id		= @comp_id

	END
	/*********************************************************************************************************************************/


	SELECT	TOP 10000
		    ' ' [+],
			c.cust_name + CASE
			                  WHEN c.cust_SaleOrderBranchTransfer = 'True' THEN ' (*)'
			                  ELSE												''
			              END	[cust_name],
			c.cust_name1,
			ts.sm_name,
			c.cust_address,
			c.cust_taxNumber,
			c.cust_city,
			c.cust_zip,
			c.cust_Phone1,
			c.cust_Phone2,
			sc.country_desc,
			ss.state_desc,
			c.cust_id [ID]

	from	tbCustomer										c				WITH (NOLOCK)
			LEFT JOIN @tmpBranchsOfBranchGroup tmp
				ON tmp.brag_id = c.brag_id
			inner join tbsysCountry							sc				WITH (NOLOCK)
				on	sc.country_id	= c.country_id

			inner join tbsysState							ss				WITH (NOLOCK)
				on  ss.state_id     = c.state_id
				and ss.country_id	= c.country_id

			INNER JOIN @tblCustomerFilterByUser				tt
				ON tt.cust_id	= c.cust_id

			INNER JOIN tbSalesman ts										WITH (NOLOCK)
				ON		ts.comp_id	= c.comp_id
					AND	ts.sm_id	= c.sm_id


	Where		c.comp_id				 =  @comp_id
		AND		isnull(c.cust_name		,'')	like '%' +  @cust_name      + '%'
		AND		isnull(c.cust_name1		,'')	like '%' +  @cust_name1     + '%'
		AND		isnull(c.cust_address	,'')	like '%' +  @cust_address   + '%'
		AND		isnull(c.cust_taxNumber	,'')	like '%' +  @cust_taxNumber + '%'
		AND		isnull(c.cust_city		,'')	like '%' +  @cust_city      + '%'
		AND		isnull(c.cust_zip		,'')	like '%' +  @cust_zip       + '%'
		AND		isnull(c.cust_Phone1	,'')    like '%' +  @cust_Phone1    + '%'
		AND		isnull(c.cust_Phone2	,'')    like '%' +  @cust_Phone2    + '%'
		AND		(sc.country_id			 =  @country_id OR  @country_id		= -1)
		AND		(ss.state_id			 =  @state_id   OR  @state_id		= -1)
		--AND     (c.bra_id IS NULL		OR  c.bra_id = @bra_id)
		AND
		CASE
			WHEN c.brag_id IS NOT NULL AND tmp.brag_id IS NULL THEN 0
			WHEN c.bra_id  IS NULL								THEN 1
			WHEN c.bra_id  = @bra_id							THEN 1
			ELSE 0
		END = 1

END


GO


CREATE  PROCEDURE [dbo].[spCustomer_GetDataByGBP_MeliID]
(
	@intMeLiID AS BIGINT
)
AS

BEGIN

	SET NOCOUNT ON

	SELECT ISNULL(tb.cust_GBPMeLi_serverURL,'')	[cust_GBPMeLi_serverURL]
		FROM tbMercadoLibre_GBPMeLiID4url	ml	WITH (NOLOCK,INDEX(IX_tbMercadoLibre_GBPMeLiID4url_cust_GBPMeLi_ID))
		INNER JOIN tbcustomer				tb	WITH (NOLOCK)
			ON	tb.comp_id = ml.comp_id AND
				tb.cust_id = ml.cust_id
		WHERE ml.cust_GBPMeLi_ID = @intMeLiID

END


GO






