CREATE PROCEDURE [dbo].[spCustomer_getDataById]
(
	@comp_id			INT,
	@cust_id			INT,
	@user_id			INT,
	@bra_id				INT
)
AS



BEGIN



	-- ----------------------------------------------------
	-- Testing
	-- ----------------------------------------------------
/*
	DECLARE @comp_id			INT,
			@cust_id			INT,
			@user_id			INT,
			@bra_id				INT

	SELECT 	@comp_id			=1,
			@cust_id			=24499,
			@user_id			=1,
			@bra_id				=1
*/
	-- ----------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	SELECT	c.comp_id,
			c.cust_id,
			c.bra_id,
			IsNull(c.cust_name,'No Name !') + CASE
										WHEN c.cust_SaleOrderBranchTransfer = 'True' THEN ' (*)'
										ELSE										''
									 END													[cust_name],
			c.cust_name1,
			c.fc_id,
			c.cust_taxNumber,
			isnull(c.cust_web,'') cust_web,
			c.cust_inactive,
			isnull(c.cust_partnerOf,'') cust_partnerOf,
			isnull(c.cust_contact,'') cust_contact,
			c.cust_address,
			ISNULL(c.cust_city,'')										[cust_city],
			ISNULL(c.cust_zip,'')										[cust_zip],
			c.country_id,
			c.state_id,
			isnull(c.cust_phone1,'')									[cust_phone1],
			isnull(c.cust_phone2,'')					                [cust_phone2],
			isnull(c.cust_cellPhone,'')									[cust_cellPhone_last],

			ISNULL(c.cust_cellPhone2,'')								[cust_cellPhone2],			-- Telefono Celular
			ISNULL(c.cust_cellPhone2_notes,'')							[cust_cellPhone2_notes],	-- Notas Telefono Celular
			ISNULL(c.cust_cellPhone1_notes,'')							[cust_cellPhone1_notes],	-- Notas Telefonos Ad
			ISNULL(c.cust_email,'')										[cust_email],
			c.cust_fax,
			c.cust_picture,
			ISNULL(c.sm_id,-1)											[sm_id],
			isnull(s.sm_name,'') sm_name,
			c.ck_id,
			ISNULL(c.st_id,-1)											[st_id],
			ISNULL(c.disc_id,-1)										[disc_id],
			ISNULL(c.dl_id,-1)											[dl_id],
			c.cust_credit_max,
			c.cust_credit_own,
			c.curr_id,
			c.acc_count_id,
			c.user_id,
			ISNULL(c.prli_id,-1)										[prli_id],
			ISNULL(c.stor_id,-1)										[stor_id],
			dbo.fnGetFiscalCustomer_KindOf(c.cust_id) Fiscal_kindOf,
			dbo.fnGetFiscalCustomer_Fiscal_fc_id(c.cust_id) Fiscal_fc_id,
			dbo.fnGetFiscalCustomer_FiscalTaxNumberType(c.cust_id) FiscalTaxNumberType,
			dbo.fnGetFiscalCustomer_Fiscal_fc_id_EpsonAR(c.cust_id) Fiscal_fc_id_EpsonAr,
			cust_isEditing,
			cust_isEditingUserId,
			tc.country_desc,
			c.stcIB_Id,
			ts.state_desc,
			c.cust_note1,
			c.cust_note2,
			c.cust_note3,
			c.cust_note4,
			isnull(c.cust_4InitialValues,'false') cust_4InitialValues,
			c.cust_address4Delivery										[DeliveryAddress],
			IsNull(c.cust_address4Payments,'')							[PaymentAddress],
			ISNULL(c.cust_SaleOrderMaxValue,0)							[cust_SaleOrderMaxValue],
			c.cust_webNickName,
			TTNT.tnt_FiscalPrinterType4EpsonAR,
			IsNull(c.cust_SaleOrderDisableConcurrentProc,'False')		[cust_SaleOrderDisableConcurrentProc],
			IsNull(c.cust_SaleOrderBranchTransfer,'False')				[cust_SaleOrderBranchTransfer],
			ttnt.tnt_OCXHASAR											[tnt_OCXHASAR],
			tfc.FiscalClass4OXCFiscal									[FiscalClass4OXCFiscal],
			c.tnt_id,
			isnull(c.cust_email4RMA,'')									[cust_email4RMA],
			isnull(c.cust_isAvailable4InternalRMA,'False')				[cust_isAvailable4InternalRMA],
			ISNULL(c.cust_contact4RMA,'')								[cust_contact4RMA],
			ISNULL(c.cust_address4RMA,'')								[cust_address4RMA],
			ISNULL(c.rmap_id,0)											[rmap_id],
			ISNULL(tb.bra_SaleOrder_DisableCustomerConcurrentCheck,'False')
																		[bra_SaleOrder_DisableCustomerConcurrentCheck],
			Isnull(c.cust_disabled4PersonalLoan,'False')				[cust_disabled4PersonalLoan],
			ISNULL(c.cust_annotation,'')								[cust_annotation],
			CASE
				WHEN c.cust_checked IS NULL THEN	'True'
				ELSE								'False'
			END																					[cust_Pend2VerifyInsert],

			CASE
				WHEN ISNULL(c.cust_address4Delivery,'') = '' THEN
					c.cust_address + ' ' + c.cust_city + ' ' + c.cust_zip + ' ' + tc.country_desc
				ELSE
					c.cust_address4Delivery
			END																					[cust_address4Deliverycomplet],
			ISNULL(c.cust_GBPUrl,'')															[cust_GBPUrl],
			ISNULL(c.cust_GBPModules,'')														[cust_GBPModules],
			ISNULL(c.cust_GBPDbName,'')															[cust_GBPDbName],
			c.cust_GBPUserQty,
			c.cust_GBPBranchQty,
			c.cust_GBPCompanyQty,
			c.cust_GBPLastURLUpdate,
			ts.state_VISATodoPago,
			ts.country_VISATodopago,
			ISNULL(tov.optval_desc,'')															[cust_isOwner],
			ISNULL(c.cust_ownerOf,'')															[cust_ownerOf],
			ISNULL(tcjd.cram_desc,'')															[cram_desc],
			ISNULL(c.cust_ramification,'')														[cust_ramification],
			ISNULL(c.cust_jobTitle,'')															[cust_jobTitle],
			ISNULL(c.cust_jobAddress,'')														[cust_jobAddress],
			ISNULL(c.cust_jobCity,'')															[cust_jobCity],
			ISNULL(c.cust_jobPhone,'')															[cust_jobPhone],
			ISNULL(c.cust_jobName,'')															[cust_jobName],
			c.cust_jobPayDate																	[cust_jobPayDate],
			c.cust_jobAdmissionDate																[cust_jobAdmissionDate],
			ISNULL(tcca.corp_desc,'')															[corp_desc],
			isnull(c.cust_judManBlockCollection,'False')										[cust_judManBlockCollection],
			ISNULL(c.prli_id_alternative,-1)													[prli_id_alternative],
			ISNULL(c.prli_id_alternative_upTo,dbo.fnGetEnd_or_BeginOfDate(GETDATE(),'False') )	[prli_id_alternative_upTo],
			ISNULL(c.cust_CRMComment,'')														[cust_CRMComment],
			ISNULL(TS.state_EnvioPackID,'')														[state_EnvioPackID]

	FROM 	dbo.tbCustomer							c			WITH (NOLOCK)

			LEFT JOIN dbo.tbSalesman				s			WITH (NOLOCK)
			ON 	s.comp_id			= c.comp_id
			AND s.sm_id				= c.sm_id

			LEFT JOIN dbo.tbsysCountry				tc			WITH (NOLOCK)
			ON	tc.country_id		= c.country_id

			LEFT JOIN tbsysState					ts			WITH (NOLOCK)
			ON	ts.state_id			= c.state_id

			LEFT JOIN tbsysTaxNumberTypes ttnt					WITH (NOLOCK)
				ON ttnt.tnt_id	= C.tnt_id

			LEFT JOIN tbsysFiscalClass tfc						WITH (NOLOCK)
				ON tfc.fc_id	= c.fc_id

			LEFT JOIN tbBranch tb								WITH (NOLOCK)
				ON	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id

			LEFT JOIN tbCustomerDefaultLevel tcdl				WITH (NOLOCK)
				ON	tcdl.comp_id	= c.comp_id		AND
					tcdl.def_id		= c.def_id

			LEFT JOIN tbCustomerCreditRating tccr				WITH (NOLOCK)
				ON	tccr.comp_id	= c.comp_id AND
					tccr.rating_id	= c.rating_id

			LEFT JOIN tbCustomerJobDepartament tcjd 			WITH (NOLOCK)
				ON	tcjd.comp_id	= c.comp_id AND
					tcjd.cram_id	= c.cram_id

			LEFT JOIN tbCustomerCorporativeAccounts tcca 		WITH (NOLOCK)
				ON	tcca.comp_id	= c.comp_id AND
					tcca.corp_id	= c.corp_id

			LEFT JOIN tbsysOptionsValues			tov			WITH (NOLOCK)
				ON tov.lang_id			= tb.lang_id AND
					tov.optval_id		= isnull(c.cust_isOwner,'False') AND
					tov.optval_class	= 17 --si or no





	WHERE	c.comp_id				= @comp_id
	AND		c.cust_id				= @cust_id


END
GO







CREATE PROCEDURE [dbo].[spCustomer_getdatabyIdtext]
(
	@comp_id					int,
	@option						int,
	@cust_id					VARCHAR(100)
    --@cust_name					VARCHAR(500)

)
AS
SET NOCOUNT ON


/*
DECLARE   @comp_id			INT,
		  @cust_name		INT

SELECT @comp_id = 1,
	@cust_name=''
*/




--//ITEM//
IF @option = 0
BEGIN
	SELECT	ti.item_code
	FROM	tbItem ti

	WHERE  ti.comp_id    = @comp_id
	AND    ti.item_code  = LTRIM(@cust_id)
END



--//CUSTOMER//
IF @option = 1
BEGIN
	SELECT	tc.cust_id
	FROM	tbCustomer tc

	WHERE  tc.comp_id   = @comp_id
	AND    tc.cust_id =   convert(int,@cust_id)
END


--//SUPPLIER//
IF @option = 2
BEGIN
	SELECT	ts.supp_id
	FROM	tbSupplier ts

	WHERE  ts.comp_id   = @comp_id
	AND    ts.supp_id   = convert(int,@cust_id)
END



--//ACCOUNTANT//
IF @option = 3
BEGIN
	SELECT	ta.acc_count_id
	FROM	tbAccountant ta

	WHERE  ta.comp_id		= @comp_id
	AND    ta.acc_count_id  = convert(int,@cust_id)
END


GO



CREATE PROCEDURE [dbo].[spCustomer_getDataByText]
(
	@text	VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id  AS INT
)
AS


BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*
	DECLARE
		@text		VARCHAR(300),
		@count		INT,
		@lang_id	INT,
		@comp_id AS INT,
		@bra_id  AS INT

	SELECT
		@text		='+test+cuit',
		@count		= 10,
		@lang_id	= 2,
	    @comp_id	= 1,
	    @bra_id		= 1
	*/
	-- ----------------------------------------------------------------


	-- Tomo los Grupos de Sucursales a los que pertenece esta sucursal
	DECLARE		@tmpBranchsOfBranchGroup TABLE(brag_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchsOfBranchGroup(brag_id)
		SELECT DISTINCT  brag_id
			FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
			WHERE	tbgd.comp_id	= @comp_id AND
					tbgd.bra_id		= @bra_id

	DECLARE @bra_enableCustomerByBranchSearch AS BIT = 'False'
	SELECT	@bra_enableCustomerByBranchSearch = ISNULL(tb.bra_enableCustomerByBranchSearch,'False')
		FROM tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id

	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple: si es con / Busca a lo Viejo, con + busca acotado y rapido
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'//','/')
	SET @text = REPLACE(@text,'//','/')
	SET @text = REPLACE(@text,'//','/')

	DECLARE @bitUltraFast AS BIT = 'True'
	IF @text LIKE '%/%'
		BEGIN
			SET @bitUltraFast = 'False'
			SET @text = REPLACE(@text,'/','+')
		END


	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	DECLARE		@tblSearch   TABLE(strSearch NVARCHAR(50))
	INSERT INTO @tblSearch(strSearch)
		SELECT TOP 3 aa.items
			FROM  dbo.fnSplitTable(@text,'+') aa
	IF @selection_method > 0	SELECT @selection_method = COUNT(*) FROM @tblSearch --COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)


	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR LOCAL  FAST_FORWARD FOR
		SELECT fst.strSearch FROM @tblSearch fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0
			ELSE IF @text2 IS NULL SET @text2 = @text0
			ELSE IF @text3 IS NULL SET @text3 = @text0 --else
			--IF @text4 IS NULL SET @text4 = @text0 else
			--IF @text5 IS NULL SET @text5 = @text0 else
			--IF @text6 IS NULL SET @text6 = @text0 else
			--IF @text7 IS NULL SET @text7 = @text0 else
			--IF @text8 IS NULL SET @text8 = @text0 else
			--IF @text9 IS NULL SET @text9 = @text0 else
			--IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------

	SET @text = REPLACE(@text,'+','')


--SELECT * FROM @tblSearch
--SELECT @selection_method,@bra_enableCustomerByBranchSearch,@text1,@text2,@text3

	IF @bra_enableCustomerByBranchSearch = 'False'
		BEGIN	-- Sin filtro x Sucursal


			IF @bitUltraFast = 'False'
				BEGIN		-- Busqueda NORMAL SIN limitar por Sucursales

					SELECT		TOP (@count)
								Upper(dbo.fnStrPADR( dbo.fnStrAllTrim( IsNull(tc.cust_name,'') )
																			+
																			CASE
																				WHEN tcf.comp_id IS NOT NULL THEN '->' + dbo.fnStrAllTrim(IsNull(tcf.custf_name,''))
																				ELSE ''
																			END
																			+
																			CASE
																				WHEN tc.cust_SaleOrderBranchTransfer='TRUE'  THEN ' (*)'
																				ELSE											   ''
																			END
														 ,50,'-')) + ' |' + dbo.fnStrPADL(isnull(convert(varchar,tc.cust_id),''),8,'0') + '|' + isnull(convert(varchar,tc.cust_taxNumber),'') [cust_name],
								tc.cust_id
						INTO #tmpTable1
						FROM		tbCustomer tc				WITH (NOLOCK)
						--LEFT JOIN @tmpBranchsOfBranchGroup tmp
						--	ON tmp.brag_id = tc.brag_id
						LEFT JOIN tbCustomerFamily tcf			WITH (NOLOCK)
							ON	tcf.comp_id = tc.comp_id AND
								tcf.cust_id = tc.cust_id
						WHERE	tc.comp_id  = @comp_id
								-- NO, MOS.-AND tc.cust_inactive = 'False'
							AND
								(

											CASE
												WHEN @selection_method = 0 AND tc.cust_name LIKE @text + '%'	 THEN	'True'
												WHEN @selection_method = 1 AND tc.cust_name LIKE '%' + @text1 + '%'	 THEN	'True'
												WHEN @selection_method = 2 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%'		 THEN	'True'
												WHEN @selection_method = 3 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%'	 THEN	'True'
												--WHEN @selection_method = 4 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%'		 THEN	'True'
												--WHEN @selection_method = 5 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%'		 THEN	'True'
												--WHEN @selection_method = 6 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%'	 THEN	'True'
												--WHEN @selection_method = 7 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%'	 THEN	'True'
												--WHEN @selection_method = 8 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%' AND tc.cust_name LIKE '%' + @text8 + '%'		 THEN	'True'
												--WHEN @selection_method = 9 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%' AND tc.cust_name LIKE '%' + @text8 + '%' AND tc.cust_name LIKE '%' + @text9 + '%'		 THEN	'True'
												--WHEN @selection_method =10 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%' AND tc.cust_name LIKE '%' + @text8 + '%' AND tc.cust_name LIKE '%' + @text9 + '%' AND tc.cust_name LIKE '%' + @text10 + '%'		 THEN 'True'
												ELSE	'False'
											END	= 'True'
										OR  tc.cust_name1					LIKE '%' + @text + '%'
										OR	tc.cust_email					LIKE '%' + @text + '%'
										OR	tc.cust_taxNumber				LIKE '%' + @text + '%'
										OR	tc.cust_MercadoLibreNickName	LIKE '%' + @text + '%'
										OR  tc.cust_webNickName				LIKE '%' + @text + '%'
										OR	tcf.custf_taxNumber				LIKE '%' + @text + '%'
										OR	tcf.custf_name					LIKE '%' + @text + '%'
										OR	tc.cust_phone1					LIKE '%' + @text + '%'
										OR	tc.cust_cellPhone				LIKE '%' + @text + '%'
										OR	tc.cust_cellPhone2				LIKE '%' + @text + '%'
										OR	tcf.custf_cellPhone				LIKE '%' + @text + '%'


								)

					SELECT *
						FROM #tmpTable1
						ORDER BY cust_name
					DROP TABLE #tmpTable1

				END
			ELSE
				BEGIN		-- Busqueda RAPIDA Sin limitar por sucursales
					--SELECT 1 / 0
					SELECT		TOP (@count)

								Upper(dbo.fnStrPADR( dbo.fnStrAllTrim( IsNull(tc.cust_name,'') )
																			+
																			--CASE
																			--	WHEN tcf.comp_id IS NOT NULL THEN '->' + dbo.fnStrAllTrim(IsNull(tcf.custf_name,''))
																			--	ELSE ''
																			--END
																			--+
																			CASE
																				WHEN tc.cust_SaleOrderBranchTransfer='TRUE'  THEN ' (*)'
																				ELSE											   ''
																			END
														 ,50,'-')) + ' |' + dbo.fnStrPADL(isnull(convert(varchar,tc.cust_id),''),8,'0') + '|' + isnull(convert(varchar,tc.cust_taxNumber),'') [cust_name],
								tc.cust_id
						INTO #tmpTable2
						FROM		tbCustomer tc				WITH (NOLOCK)

						WHERE	tc.comp_id  = @comp_id
								-- NO, MOS.-AND tc.cust_inactive = 'False'
							AND
								(

											CASE
												WHEN @selection_method = 0 AND tc.cust_name LIKE @text + '%'			THEN	'True'
												WHEN @selection_method = 1 AND tc.cust_name LIKE '%' + @text1 + '%'		THEN	'True'
												WHEN @selection_method = 2 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%'		 THEN	'True'
												WHEN @selection_method = 3 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%'	 THEN	'True'
												--WHEN @selection_method = 4 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%'		 THEN	'True'
												--WHEN @selection_method = 5 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%'		 THEN	'True'
												--WHEN @selection_method = 6 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%'	 THEN	'True'
												--WHEN @selection_method = 7 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%'	 THEN	'True'
												--WHEN @selection_method = 8 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%' AND tc.cust_name LIKE '%' + @text8 + '%'		 THEN	'True'
												--WHEN @selection_method = 9 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%' AND tc.cust_name LIKE '%' + @text8 + '%' AND tc.cust_name LIKE '%' + @text9 + '%'		 THEN	'True'
												--WHEN @selection_method =10 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%' AND tc.cust_name LIKE '%' + @text8 + '%' AND tc.cust_name LIKE '%' + @text9 + '%' AND tc.cust_name LIKE '%' + @text10 + '%'		 THEN 'True'
												ELSE	'False'
											END	= 'True'
										--OR  tc.cust_name1					LIKE '%' + @text + '%'
										--OR	tc.cust_email					LIKE '%' + @text + '%'
										OR	tc.cust_taxNumber				LIKE '%' + @text + '%'
										--OR	tc.cust_MercadoLibreNickName	LIKE '%' + @text + '%'
										--OR  tc.cust_webNickName				LIKE '%' + @text + '%'
										--OR	tcf.custf_taxNumber				LIKE '%' + @text + '%'
								)

					SELECT *
						FROM #tmpTable2
						ORDER BY cust_name
					DROP TABLE #tmpTable2

				END






			-- x Velocidad se volco a una temp y luego se ordena la temporal


		END



	ELSE



		BEGIN  -- Con filtro por Sucursal, busqueda NORMAL.


			SELECT		TOP (@count)
						Upper(dbo.fnStrPADR( dbo.fnStrAllTrim( IsNull(tc.cust_name,'') )
																	+
																	CASE
																		WHEN tcf.comp_id IS NOT NULL THEN '->' + dbo.fnStrAllTrim(IsNull(tcf.custf_name,''))
																		ELSE ''
																	END
																	+
																	CASE
																		WHEN tc.cust_SaleOrderBranchTransfer='TRUE'  THEN ' (*)'
																		ELSE											   ''
																	END
												 ,50,'-')) + ' |' + dbo.fnStrPADL(isnull(convert(varchar,tc.cust_id),''),8,'0') + '|' + isnull(convert(varchar,tc.cust_taxNumber),'') [cust_name],
						tc.cust_id
				INTO #tmpTable3
				FROM		tbCustomer tc				WITH (NOLOCK)
				LEFT JOIN @tmpBranchsOfBranchGroup tmp
					ON tmp.brag_id = tc.brag_id
				LEFT JOIN tbCustomerFamily tcf			WITH (NOLOCK)
					ON	tcf.comp_id = tc.comp_id AND
						tcf.cust_id = tc.cust_id
				WHERE	tc.comp_id  = @comp_id
						-- NO, MOS.-AND tc.cust_inactive = 'False'
					AND
						(

									CASE
										WHEN @selection_method = 0 AND tc.cust_name LIKE @text + '%'	 THEN	'True'
										WHEN @selection_method = 1 AND tc.cust_name LIKE '%' + @text1 + '%'	 THEN	'True'
										WHEN @selection_method = 2 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%'		 THEN	'True'
										WHEN @selection_method = 3 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%'	 THEN	'True'
										--WHEN @selection_method = 4 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%'		 THEN	'True'
										--WHEN @selection_method = 5 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%'		 THEN	'True'
										--WHEN @selection_method = 6 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%'	 THEN	'True'
										--WHEN @selection_method = 7 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%'	 THEN	'True'
										--WHEN @selection_method = 8 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%' AND tc.cust_name LIKE '%' + @text8 + '%'		 THEN	'True'
										--WHEN @selection_method = 9 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%' AND tc.cust_name LIKE '%' + @text8 + '%' AND tc.cust_name LIKE '%' + @text9 + '%'		 THEN	'True'
										--WHEN @selection_method =10 AND tc.cust_name LIKE '%' + @text1 + '%' AND tc.cust_name LIKE '%' + @text2 + '%' AND tc.cust_name LIKE '%' + @text3 + '%' AND tc.cust_name LIKE '%' + @text4 + '%' AND tc.cust_name LIKE '%' + @text5 + '%' AND tc.cust_name LIKE '%' + @text6 + '%' AND tc.cust_name LIKE '%' + @text7 + '%' AND tc.cust_name LIKE '%' + @text8 + '%' AND tc.cust_name LIKE '%' + @text9 + '%' AND tc.cust_name LIKE '%' + @text10 + '%'		 THEN 'True'
										ELSE	'False'
									END	= 'True'
								OR  tc.cust_name1					LIKE '%' + @text + '%'
								OR	tc.cust_email					LIKE '%' + @text + '%'
								OR	tc.cust_taxNumber				LIKE '%' + @text + '%'
								OR	tc.cust_MercadoLibreNickName	LIKE '%' + @text + '%'
								OR  tc.cust_webNickName				LIKE '%' + @text + '%'
								OR	tcf.custf_taxNumber				LIKE '%' + @text + '%'
								OR	tcf.custf_name					LIKE '%' + @text + '%'
								OR	tc.cust_phone1					LIKE '%' + @text + '%'
								OR	tc.cust_cellPhone				LIKE '%' + @text + '%'
								OR	tc.cust_cellPhone2				LIKE '%' + @text + '%'
								OR	tcf.custf_cellPhone				LIKE '%' + @text + '%'


						)
					AND

					-- Filtro x pertenencia a una sucursal o Grupo de Sucursales
					(
						(tc.bra_id  IS NULL AND tc.brag_id IS NULL)
							OR
						tc.bra_id  = @bra_id
							OR
						tmp.brag_id IS NOT NULL
					)
									--CASE
									--	WHEN tc.brag_id IS NOT NULL AND tmp.brag_id IS NULL THEN 0
									--	WHEN tc.bra_id  IS NULL								THEN 1
									--	WHEN tc.bra_id  = @bra_id							THEN 1
									--	ELSE 0
									--END = 1

			-- x Velocidad se volco a una temp y luego se ordena la temporal
			SELECT *
				FROM #tmpTable3
				ORDER BY cust_name
			DROP TABLE #tmpTable3

		END








END


