--ALTER PROCEDURE [dbo].[spCustomer_getDataByText]
--(
--	@text	VARCHAR(300),
--	@count		INT,
--	@lang_id	INT	,
--	@comp_id AS INT,
--	@bra_id  AS INT
--)
--AS




--BEGIN

--	SET NOCOUNT ON
--	-- -----------------------------------------------------------------------------
--	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
--	-- -----------------------------------------------------------------------------
--	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
--	SET LOCK_TIMEOUT 500
--	SET DEADLOCK_PRIORITY LOW
--	-- -----------------------------------------------------------------------------


--	-- ----------------------------------------------------------------
--	-- Testing
--	-- ----------------------------------------------------------------
--	/*
--	DECLARE
--		@text		VARCHAR(300),
--		@count		INT,
--		@lang_id	INT,
--		@comp_id AS INT,
--		@bra_id  AS INT

--	SELECT
--		@text		='marina toyos',
--		@count		= 10,
--		@lang_id	= 2,
--	    @comp_id	= 1,
--	    @bra_id		= 1
--	*/
--	-- ----------------------------------------------------------------





--	-- Tomo los Grupos de Sucursales a los que pertenece esta sucursal
--	DECLARE @tmpBranchsOfBranchGroup TABLE(brag_id INT PRIMARY KEY)
--	INSERT INTO @tmpBranchsOfBranchGroup(brag_id)
--		SELECT DISTINCT  brag_id
--			FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
--			WHERE	tbgd.comp_id	= @comp_id AND
--					tbgd.bra_id		= @bra_id



--	DECLARE @bra_enableCustomerByBranchSearch AS BIT = 'False'
--	SELECT	@bra_enableCustomerByBranchSearch = ISNULL(tb.bra_enableCustomerByBranchSearch,'False')
--		FROM tbBranch tb	WITH (NOLOCK)
--		WHERE	tb.comp_id	= @comp_id AND
--				tb.bra_id	= @bra_id



--	-- --------------------------------------------------------------------------------------------
--	-- Seleccion Multiple
--	-- --------------------------------------------------------------------------------------------
