CREATE PROCEDURE [dbo].[spCustomer_getDataForMail]
(
	@comp_id		INT,
	@guid			UNIQUEIDENTIFIER
)
AS
SET NOCOUNT ON

/*
DECLARE
	@comp_id	INT,
	@country_id	INT,
	@state_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@pQuestion	BIT

SELECT
	@comp_id	= 1,
	@country_id	= -1,--54,
	@state_id	= -1,--54011,
	@guid		= '04af870b-a20b-41f6-a373-3949b02b640e',
	@pQuestion	= 'True'
*/

SELECT	tc.cust_email

	FROM	tbCustomer								tc				WITH (NOLOCK)

			INNER JOIN tbMail_Recipients			tmr				WITH (NOLOCK)
			ON	tc.comp_id			= tmr.comp_id
			AND tc.cust_id			= tmr.mr_recipientId
			AND tmr.guid			= @guid

	WHERE	tc.comp_id		=	@comp_id
	AND		NOT tc.cust_email IS NULL
	AND		tc.cust_email	<>	''
	AND		tmr.mr_checked	=	'True' AND
			ISNULL(tc.cust_excludeOfCustomerMailing,'False')	= 'False'
GO








CREATE PROCEDURE [dbo].[spCustomer_getDataForWeb]
(
	@comp_id			INT,
	@cust_id			INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------------------
	/*
	DECLARE @comp_id			INT,
			@cust_id			INT,
			@user_id			INT,
			@bra_id				INT
	SELECT 	@comp_id			=1,
			@cust_id			=24289,
			@user_id			=1,
			@bra_id				=1
	*/
-- -----------------------------------------------------------------------------



	SELECT	c.cust_name,
			c.cust_name1,
			c.prli_id,
			c.stor_id,
			c.cust_webNickName

	FROM 	dbo.tbCustomer	c	WITH (NOLOCK)

	WHERE	c.comp_id				= @comp_id
	AND		c.cust_id				= @cust_id










END


GO







CREATE PROCEDURE [dbo].[spCustomer_getDataForWS]
(
	@comp_id			INT,
	@bra_id				INT,
	@cust_id			INT,
	@page_number		INT
)
AS

BEGIN



	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- -----------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------
	/*
	DECLARE 	@comp_id			INT,
				@bra_id				INT,
				@cust_id			INT,
				@page_number		INT
	SELECT 		@comp_id			=1,
				@bra_id				=1,
				@cust_id			=24288,
				@page_number		=-1
	*/
	-- -----------------------------------------------------------------------------


	DECLARE	@bra_proccesingdate		DATETIME,
			@user_id				INT



	SELECT	@bra_proccesingdate = tb.bra_processingDate
	FROM	tbBranch				tb
	WHERE	tb.comp_id	= @comp_id
	AND		tb.bra_id	= @bra_id



	SELECT  @user_id	= ISNULL(tc.user_id_4WebService,-1)
	FROM	tbCompany				tc
	WHERE	tc.comp_id	= @comp_id




	;WITH resultado_total AS
	(
		SELECT 	c.cust_id,					c.bra_id,
				c.cust_name,				c.cust_taxNumber,
				c.cust_web,
				c.cust_address,				c.cust_city,
				c.cust_zip,					c.country_id,					c.state_id,
				c.cust_phone1,				c.cust_phone2,					c.cust_email,
				c.sm_id,
				c.ck_id,					c.disc_id,
				c.cust_credit_max,			c.cust_credit_own,
				c.curr_id,
				c.prli_id,
				c.cust_note1,
				c.cust_address4Delivery,
				c.cust_webPassword,
				c.city_id,
				--fcgbs.cust_credit_balance,
				'true' [cust_showstock],
				'true' [cust_usestock],
				td.disc_coef,
				ROW_NUMBER() OVER ( order by c.cust_name asc ) AS RN

		FROM 	tbCustomer					c

				INNER JOIN tbDiscount		td
				ON	td.comp_id = c.comp_id
				AND td.disc_id = c.disc_id

				--CROSS APPLY dbo.fnCustomer_getBalanceStatus(@comp_id,c.curr_id,c.cust_id,@user_id,@bra_proccesingdate,-1,-1) fcgbs

		WHERE 	c.comp_id = @comp_id
		AND		(@cust_id = -1 OR c.cust_id = @cust_id)
	)





	SELECT		a.cust_id,
				a.bra_id,
				a.cust_name,
				a.cust_taxNumber,
				a.cust_web,
				a.cust_address,
				a.cust_city,
				a.cust_zip,
				a.country_id,
				a.state_id,
				a.cust_phone1,
				a.cust_phone2,
				a.cust_email,
				a.sm_id,
				a.ck_id,
				a.disc_id,
				a.cust_credit_max,
				a.cust_credit_own,
				a.curr_id,
				a.prli_id,
				a.cust_note1,
				a.cust_address4Delivery,
				a.cust_webPassword,
				a.city_id,
				b.cust_credit_balance,
				a.[cust_showstock],
				a.[cust_usestock],
				a.disc_coef

	FROM		resultado_total	a

				CROSS APPLY dbo.fnCustomer_getBalanceStatus(@comp_id,a.curr_id,a.cust_id,@user_id,@bra_proccesingdate,-1,-1) b

	WHERE		(@cust_id = -1 AND RN BETWEEN (500 * @page_number + 1) AND (500 * (@page_number + 1)))
	OR			@cust_id <> -1



END
GO




CREATE PROCEDURE [dbo].[spCustomer_GetDataPictures]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1
		*/
		-- -------------------------------------------


		SELECT
			tc.cust_picture,
			tc.cust_id


			FROM tbCustomer								tc

			WHERE	tc.comp_id		= @comp_id	AND
					tc.cust_picture IS NOT NULL






END
GO





-- =============================================
-- Author:		GA
-- Create date: 12/09/18
-- Description:	Obtener el descuento por item
-- =============================================


CREATE PROCEDURE [dbo].[spCustomer_getDiscountByItem]
	@comp_id	AS INT,
	@cust_id	AS INT,
	@item_id	AS INT,
	@bra_id		AS INT

AS


BEGIN


	SET NOCOUNT ON;

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
	DECLARE			@comp_id	AS INT,
					@cust_id	AS INT,
					@item_id	AS INT,
					@bra_id		AS INT


	SELECT			@comp_id	= 1,
					@item_id	= 606,
					@cust_id	= 24518,
					@bra_id		= 1
*/
	-- ------------------------------------------------------



	DECLARE @ldiscount AS DECIMAL(19,4)
	SET		@ldiscount = 0


	SELECT
		TOP 1 @ldiscount = tbi.dxi_discount
		FROM tbCustomerDiscountByItem			tbi		WITH (NOLOCK)
		INNER JOIN tbItem						ti		WITH (NOLOCK)
			ON  ti.comp_id = @comp_id				AND
				ti.item_id = @item_id

		WHERE	tbi.comp_id			= @comp_id		AND
				tbi.cust_id			= @cust_id		AND
				tbi.dxi_disabled	= 'False'		AND
				(
					tbi.bra_id			= @bra_id
						OR
					tbi.bra_id			IS NULL
				)									AND
				(
					tbi.item_id			= @item_id		 OR
					(
						tbi.item_id IS NULL
							AND
						(
							tbi.subcat_id IS NULL
								AND
							tbi.cat_id			= ti.cat_id
						)									 OR
						tbi.subcat_id		= ti.subcat_id	 OR
						tbi.brand_id		= ti.brand_id	 OR
						tbi.supp_id			= ti.supp_id
					)
				)

		ORDER BY tbi.item_id DESC,tbi.cat_id DESC, tbi.subcat_id DESC, tbi.brand_id DESC,tbi.supp_id DESC

