CREATE PROCEDURE [dbo].[spCustomer_GetGetData4WebByWebNickName]
(
	@comp_id			 as INT,
	@strNickName		 AS NVARCHAR(MAX),
	@intBraId			 AS INT,
	@guidWSID			 AS UNIQUEIDENTIFIER
)
AS

BEGIN

	set nocount ON



	DECLARE @cust_id			AS INT = NULL
	DECLARE @cust_webNickName	AS NVARCHAR(300)
	DECLARE @cust_webPassword	AS NVARCHAR(50)
	DECLARE @wsu_id				AS INT = -1
	SELECT	@cust_id			= twsiu.cust_id,
			@cust_webNickName	= twsiu.wsu_webNickName,
			@cust_webPassword	= twsiu.wsu_webPassword,
			@wsu_id				= twsiu.wsu_id
		FROM tbWebSiteII_Users twsiu		WITH (NOLOCK)
		WHERE	twsiu.comp_id			= @comp_id	AND
				twsiu.ws_id				= @guidWSID AND
				twsiu.wsu_webNickName	LIKE '%'+ @strNickName +'%'

	-- MOS 04-2023
	IF	@cust_id IS NOT NULL	AND
		@cust_id > 0			AND
		dbo.fnStrAllTrim(@cust_webPassword) = ''
		BEGIN
			UPDATE tbWebSiteII_Users
				SET wsu_webPassword = NEWID()
				WHERE	comp_id = @comp_id		AND
						wsu_id	= @wsu_id
		END



	IF @cust_id IS NOT NULL
		BEGIN					-- Si encontro el cliente de la nueva manera de logearse...
			SELECT TOP 1
				tc.comp_id,
				tc.cust_id,
				tc.cust_name,
				@cust_webNickName							[cust_webNickName],
				@cust_webPassword							[cust_webPassword],
				tc.cust_email,
				tb.bra_desc,
				tb.bra_MainDesc,
				twsin.ws_desc,
				ts.sm_email,
				twsin.ws_newCustomerEmailContactName,
				CASE
					WHEN dbo.fnStrAllTrim( ISNULL(twsin.ws_newCustomerEmailContactEMail,'')) = '' THEN	twsin.ws_MailReplyTO
					ELSE																				twsin.ws_newCustomerEmailContactEMail
				END														[ws_newCustomerEmailContactEMail],
				IsNull(twsin.ws_recoverPasswordText,'')					[ws_recoverPasswordText],
				IsNull(twsin.ws_recoverPasswordSubject,'')				[ws_recoverPasswordSubject],
				IsNull(twsin.ws_recoverPasswordDisplayName,'')			[ws_recoverPasswordDisplayName]
				FROM tbcustomer tc							WITH (NOLOCK)
				INNER JOIN tbSalesman ts					WITH (NOLOCK)
					ON	ts.comp_id		= tc.comp_id AND
						ts.sm_id		= tc.sm_id
				INNER JOIN tbBranch tb						WITH (NOLOCK)
					ON	tb.comp_id		= @comp_id AND
						tb.bra_id		= @intBraId
				INNER JOIN tbWebSiteII_Names twsin			WITH (NOLOCK)
					ON	twsin.comp_id	= @comp_id AND
						twsin.ws_id		= @guidWSID
				WHERE	tc.comp_id		= @comp_id AND
						tc.cust_id		= @cust_id

		END
	ELSE	-- sino lo retorna directo del cliente, si es que está
		BEGIN

			SET @cust_id				= -1
			SET @cust_webPassword		= ''
			SELECT	@cust_id			= tc.cust_id,
					@cust_webPassword	= tc.cust_webPassword
				FROM tbCustomer AS tc	WITH (NOLOCK)
				WHERE	tc.comp_id			= @comp_id AND
						tc.cust_webNickName LIKE '%'+ @strNickName +'%'

			IF @cust_id > 0 AND dbo.fnStrAllTrim(@cust_webPassword) = ''		-- MOS 04-2023: Dario x Recuperacion Pass
				BEGIN
					UPDATE tbCustomer
						SET cust_webPassword = NEWID()
						WHERE	comp_id = @comp_id		AND
								cust_id	= @cust_id
				END

			SELECT TOP 1
				tc.comp_id,
				tc.cust_id,
				tc.cust_name,
				IsNull(tc.cust_webNickName,'')				[cust_webNickName],
				IsNull(tc.cust_webPassword,'')				[cust_webPassword],
				tc.cust_email,
				tb.bra_desc,
				tb.bra_MainDesc,
				twsin.ws_desc,
				ts.sm_email,
				twsin.ws_newCustomerEmailContactName,
				twsin.ws_newCustomerEmailContactEMail,
				IsNull(twsin.ws_recoverPasswordText,'')					[ws_recoverPasswordText],
				IsNull(twsin.ws_recoverPasswordSubject,'')				[ws_recoverPasswordSubject],
				IsNull(twsin.ws_recoverPasswordDisplayName,'')			[ws_recoverPasswordDisplayName]
				FROM tbcustomer tc							WITH (NOLOCK)
				INNER JOIN tbSalesman ts					WITH (NOLOCK)
					ON	ts.comp_id		= tc.comp_id AND
						ts.sm_id		= tc.sm_id
				INNER JOIN tbBranch tb						WITH (NOLOCK)
					ON	tb.comp_id		= @comp_id AND
						tb.bra_id		= @intBraId
				INNER JOIN tbWebSiteII_Names twsin			WITH (NOLOCK)
					ON	twsin.comp_id	= @comp_id AND
						twsin.ws_id		= @guidWSID
				WHERE	tc.comp_id		= @comp_id AND
						tc.cust_webNickName LIKE '%'+ @strNickName +'%'

		END






END





GO







CREATE PROCEDURE [dbo].[spCustomer_GetGetData4WebService4MercadoLibre]
(
	@comp_id			 as INT,
	@cust_id			 AS INT
)
AS

BEGIN

	set nocount ON


	SELECT tc.comp_id, tc.cust_id, tc.cust_name, tc.fc_id, tc.cust_taxNumber,
	       tc.stcIB_Id, tc.cust_taxIBNumber, tc.cust_inactive, tc.cust_contact,
	       tc.cust_address, tc.cust_city, tc.cust_zip, tc.country_id, tc.state_id,
	       tc.cust_phone1, tc.cust_phone2, tc.cust_email, tc.sm_id, tc.ck_id,
	       tc.st_id, tc.disc_id, tc.dl_id, tc.cust_credit_max, tc.cust_credit_own,
	       tc.curr_id, tc.prli_id, tc.stor_id, tc.tnt_id, tc.ss_id, tc.cust_judMan,
	       tc.cust_address4Delivery, tc.cust_address4Payments, tc.cust_webNickName,
	       tc.cust_webPassword, tc.city_id, tc.cust_contact4Payments,
	       tc.cust_email4Payments, tc.cust_contact4Management,
	       tc.cust_email4Management, tc.cust_contact4Administration,
	       tc.cust_email4Administration, tc.cust_contact4Logistics,
	       tc.cust_email4Logistics, tc.act_id, tc.cust_contact4Alternative,
	       tc.cust_email4Alternative, tc.cust_contact4RMA, tc.cust_email4RMA,
	       tc.cust_address4RMA, tc.cust_isAvailable4InternalRMA, tc.cust_phone4RMA,
	       tc.cust_contact4AlternativeII, tc.cust_email4AlternativeII
		FROM tbcustomer tc
		WHERE	tc.comp_id			= @comp_id		AND
			   (
			   	@cust_id			= -1 OR
			    tc.cust_id			= @cust_id
			   )									AND
			    tc.cust_inactive	=	'False'


END





GO





