CREATE PROCEDURE [dbo].[spCustomer_getIBStatus]
	@comp_id	AS INT,
	@cust_id	AS INT,
	@guid	AS UNIQUEIDENTIFIER
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	-- ------------------------------------------------------------------------------------------------
	-- MOS: 08-2011
	-- Verifica que si tiene alguna percepcion de Ingresos Brutos, solo se pueda emitir si el cliente
	-- tiene cargado algo en numero de inscripcion.
	-- ------------------------------------------------------------------------------------------------
	IF EXISTS
			(
				SELECT  TOP 1 1
					FROM tbtmpTax tt								WITH (NOLOCK)
					INNER JOIN tbTaxName ttn						WITH (NOLOCK)
						ON		ttn.comp_id = tt.comp_id
							AND ttn.tax_id	= tt.tax_id
					INNER JOIN vwsysTaxClassIB_Perceptions vtcip	WITH (NOLOCK)
						ON vtcip.tax_class = ttn.tax_class
				WHERE tt.tis_guid = @guid
			)
		AND
		EXISTS
			(
				SELECT TOP 1 1
					FROM tbCustomer tc								WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id
					AND tc.cust_id = @cust_id
					AND len( IsNull(tc.cust_taxIBNumber,'') ) < 4
			)
		BEGIN
			SELECT -1
			RETURN
--			Set @return_value			= -1
--			Set @ret_ErrorCode			= -1
--			Set @ret_ErrorDescription	= 'Falta Cargar el Numero de Inscripción de Ingresos Brutos en el Cliente.!'
		END
		SELECT 1
END
GO







