CREATE PROCEDURE [dbo].[spCustomer_getLogin]
(
	@comp_id				INT,
	@ws_id					UNIQUEIDENTIFIER,
	@cust_webNickName		varchar(50),
	@cust_webPassword		varchar(1000),
	@cust_boolean			BIT,
	@cust_login_ip			VARCHAR(20),
	@cust_login_name		VARCHAR(50),

	@return_value			INTEGER OUTPUT
)
AS


BEGIN


	SET NOCOUNT ON

	DECLARE @wsu_id AS INT =  NULL  -- Usuario de este sitio web

	DECLARE @lcust_id			INT,
			@lcust_login		BIT,
			@lcust_login_ip		VARCHAR(20),
			@lcust_login_name	VARCHAR(50),
			@prli_id			INT,
			@stor_id			INT,
			@cust_webPassword_original	NVARCHAR(50)


	-- NUEVO 01-2019
	SET @cust_webNickName = LOWER(dbo.fnStrAllTrim(@cust_webNickName))
	SET @cust_webPassword = LOWER(dbo.fnStrAllTrim(@cust_webPassword))

	-- Veo si puedo encontrar al cliente de la nueva manera
	SET		@lcust_id = NULL
	SELECT	@lcust_id = twsiu.cust_id,
			@wsu_id   = twsiu.wsu_id
		FROM tbWebSiteII_Users twsiu	WITH (NOLOCK)
		WHERE	twsiu.comp_id					= @comp_id			AND
				twsiu.ws_id						= @ws_id			AND
				LOWER(twsiu.wsu_webNickName)	= @cust_webNickName AND
				LOWER(twsiu.wsu_webPassword)	= @cust_webPassword	AND
				@cust_webNickName				<> ''				AND
				@cust_webPassword				<> ''




	IF @lcust_id IS NOT NULL	--Si lo encuentro de la nueva manera, si lo encuentro tomo el ID
		BEGIN
			SELECT	@lcust_id					= [cust_id],
					@lcust_login				= cust_login,
					@lcust_login_ip				= cust_login_ip,
					@lcust_login_name			= cust_login_name,
					@prli_id					= prli_id,
					@stor_id					= stor_id,
					@cust_webPassword_original	= cust_webPassword
				FROM	[tbCustomer]
				WHERE	comp_id = @comp_id AND
						cust_id = @lcust_id
		END
	ELSE
		BEGIN
			SELECT	@lcust_id					= [cust_id],
					@lcust_login				= cust_login,
					@lcust_login_ip				= cust_login_ip,
					@lcust_login_name			= cust_login_name,
					@prli_id					= prli_id,
					@stor_id					= stor_id,
					@cust_webPassword_original	= cust_webPassword
				FROM	[tbCustomer]
				WHERE	cust_webNickName	= @cust_webNickName
				AND		cust_webPassword	= @cust_webPassword
				AND		@cust_webNickName	<> ''
				AND		@cust_webPassword	<> ''

		END




	------------------------------------------------------------------------------------------------------
	--transformamos la clave original y la ingresada al valores ascii para verificar 'case sensitive'
	------------------------------------------------------------------------------------------------------
	--DECLARE @cust_webPassword_original_ascii	NVARCHAR(100)
	--DECLARE @cust_webPassword_ascii				NVARCHAR(100)

	--DECLARE	@position							INT

	--SET		@cust_webPassword_original_ascii	=''
	--SET		@cust_webPassword_ascii				=''
	------------------------------------------------------------------------------------------------------
	-- Se puede ser TAN PERO TAN HDP !!!!!
	----convertimos la clave original
	--SET		@position		= 1

	--WHILE @position <= len(@cust_webPassword_original)
	--	BEGIN
	--		SET @cust_webPassword_original_ascii = @cust_webPassword_original_ascii + convert(nvarchar,ASCII(SUBSTRING(@cust_webPassword_original, @position, 1)))
	--		SET @position = @position + 1
	--	END

	----convertimos la clave ingresada
	--SET		@position		= 1
	--WHILE @position <= len(@cust_webPassword)
	--BEGIN
	--	SET @cust_webPassword_ascii = @cust_webPassword_ascii + convert(nvarchar,ASCII(SUBSTRING(@cust_webPassword, @position, 1)))
	--	SET @position = @position + 1
	--END

	--si difieren los ascii de la claves ingresada y la de la base ponemos el cust_id a null
	--para que siga el proceso como si no la hubiera encontrado
	--IF @cust_webPassword_ascii <> @cust_webPassword_original_ascii	SET @lcust_id = NULL
	------------------------------------------------------------------------------------------------------


	IF @lcust_id IS NULL		--usuario o password incorrectos

		BEGIN

			SET		@return_value	= -1
			SELECT	-1

		END

	ELSE

		BEGIN

			IF isnull(@lcust_login,'false') = 'false'	--usuario y password correctos y usuario no conectado
				BEGIN

					SET		@return_value	= 0

					SELECT 	@lcust_id	[cust_id],
							@prli_id	[prli_id],
							@stor_id	[stor_id]

					--actualizacion para indicar que el usuario se logueo
					IF (LTRIM(RTRIM(UPPER(@cust_webNickName))) <> UPPER('ERPAdmin'))
						BEGIN

							UPDATE	tbCustomer
								SET		cust_login			= 'True',
										cust_login_CD		= GETDATE(),
										cust_login_ip		= @cust_login_ip,
										cust_login_name		= @cust_login_name
								WHERE	cust_webNickName	= @cust_webNickName
								AND 	cust_webPassword	= @cust_webPassword
								AND		@cust_boolean		= 'False'
								AND		cust_SaleOrderDisableConcurrentProc = 'False'


							-- Pone la fecha y hora de el último Logeo
							UPDATE tbWebSiteII_Users
								SET	wsu_lastLogin = GETDATE()
								WHERE	comp_id = @comp_id AND
										wsu_id	= @wsu_id

						END

				END


			ELSE

				IF @lcust_login = 'true'	--usuario y password correctos y usuario ya conectado
					BEGIN


						--si está logueado se verifica si es de la misma ip/name
						IF @lcust_login_ip = @cust_login_ip OR @lcust_login_name = @cust_login_name
							BEGIN

								SET		@return_value	= 1

								SELECT 	@lcust_id	[cust_id]

							END

						ELSE

							BEGIN

								SET		@return_value	= 2

								SELECT 	@lcust_id	[cust_id]

							END

					END

		END


END
GO





CREATE PROCEDURE [dbo].spCustomer_getLogin4WebSite
(
	@cust_webNickName		varchar(50),
	@cust_webPassword		varchar(1000),
	@cust_boolean			BIT,
	@cust_login_ip			VARCHAR(20),
	@cust_login_name		VARCHAR(50),
	@ws_id					UNIQUEIDENTIFIER,
	@return_value			INTEGER OUTPUT
)
AS


BEGIN



	SET NOCOUNT ON




	DECLARE @lcust_id			INT,
			@lcust_login		BIT,
			@lcust_login_ip		VARCHAR(20),
			@lcust_login_name	VARCHAR(50),
			@prli_id			INT,
			@stor_id			INT,
			@cust_webPassword_original	NVARCHAR(50),
			@comp_id			INT



	SELECT	@lcust_id			= [cust_id],
			@lcust_login		= cust_login,
			@lcust_login_ip		= cust_login_ip,
			@lcust_login_name	= cust_login_name,
			@prli_id			= prli_id,
			@stor_id			= stor_id,
			@cust_webPassword_original = cust_webPassword,
			@comp_id			= comp_id
		FROM	[tbCustomer]		WITH (NOLOCK)
		WHERE	cust_webNickName	= @cust_webNickName
		AND		cust_webPassword	= @cust_webPassword
		AND		@cust_webNickName	<> ''
		AND		@cust_webPassword	<> ''




	IF NOT EXISTS (
						SELECT 1
							FROM tbWebSiteII_Customer4WebSiteRelation twsicwsr		WITH (NOLOCK)
							WHERE	twsicwsr.comp_id	= @comp_id AND
									twsicwsr.ws_id		= @ws_id
					)
		BEGIN
			SET		@return_value	= -5
			SELECT	-5
		END



	------------------------------------------------------------------------------------------------------
	--transformamos la clave original y la ingresada al valores ascii para verificar 'case sensitive'
	------------------------------------------------------------------------------------------------------
	DECLARE @cust_webPassword_original_ascii	NVARCHAR(100)
	DECLARE @cust_webPassword_ascii				NVARCHAR(100)

	DECLARE	@position							INT

	SET		@cust_webPassword_original_ascii	=''
	SET		@cust_webPassword_ascii				=''



	--convertimos la clave original
	SET		@position		= 1

	WHILE @position <= len(@cust_webPassword_original)
		BEGIN

			SET @cust_webPassword_original_ascii = @cust_webPassword_original_ascii + convert(nvarchar,ASCII(SUBSTRING(@cust_webPassword_original, @position, 1)))

			SET @position = @position + 1

		END




	--convertimos la clave ingresada
	SET		@position		= 1

	WHILE @position <= len(@cust_webPassword)
	BEGIN

		SET @cust_webPassword_ascii = @cust_webPassword_ascii + convert(nvarchar,ASCII(SUBSTRING(@cust_webPassword, @position, 1)))

		SET @position = @position + 1

	END




	--si difieren los ascii de la claves ingresada y la de la base ponemos el cust_id a null
	--para que siga el proceso como si no la hubiera encontrado
	IF @cust_webPassword_ascii <> @cust_webPassword_original_ascii

		SET @lcust_id = NULL

	------------------------------------------------------------------------------------------------------


	IF @lcust_id IS NULL		--usuario o password incorrectos

		BEGIN

			SET		@return_value	= -1
			SELECT	-1

		END

	ELSE

		BEGIN

			IF isnull(@lcust_login,'false') = 'false'	--usuario y password correctos y usuario no conectado
				BEGIN

					SET		@return_value	= 0

					SELECT 	@lcust_id	[cust_id],
							@prli_id	[prli_id],
							@stor_id	[stor_id]

					--actualizacion para indicar que el usuario se logueo
					IF (LTRIM(RTRIM(UPPER(@cust_webNickName))) <> UPPER('ERPAdmin'))
						BEGIN

							UPDATE	tbCustomer		WITH (ROWLOCK)
								SET		cust_login			= 'True',
										cust_login_CD		= GETDATE(),
										cust_login_ip		= @cust_login_ip,
										cust_login_name		= @cust_login_name
								WHERE	cust_webNickName	= @cust_webNickName
								AND 	cust_webPassword	= @cust_webPassword
								AND		@cust_boolean		= 'False'
								AND		cust_SaleOrderDisableConcurrentProc = 'False'

						END

				END


			ELSE

				IF @lcust_login = 'true'	--usuario y password correctos y usuario ya conectado
					BEGIN


						--si está logueado se verifica si es de la misma ip/name
						IF @lcust_login_ip = @cust_login_ip OR @lcust_login_name = @cust_login_name
							BEGIN

								SET		@return_value	= 1

								SELECT 	@lcust_id	[cust_id]

							END

						ELSE

							BEGIN

								SET		@return_value	= 2

								SELECT 	@lcust_id	[cust_id]

							END

					END

		END


END
GO






CREATE PROCEDURE [dbo].[spCustomer_getMailingList]
(
	@comp_id		INT,
	@where			VARCHAR(8000),
	@guid			UNIQUEIDENTIFIER,
	@pQuestion		BIT					-- TRUE = DESCHECKEA // FALSE = MANTIENE LOS QUE YA ESTABAN CHECKEADOS
)
AS

BEGIN

	SET NOCOUNT ON

	-- ----------------------------------------------------------
	-- testing
	-- ----------------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@where		VARCHAR(8000),
		@guid		UNIQUEIDENTIFIER,
		@pQuestion	BIT

	SELECT
		@comp_id	= 1,
		@where		= '((-1 = -1) or ([country_id] = ''-1''))  ',
		@guid		= 'a7a0b132-379d-4954-8106-75ae9680715b',
		@pQuestion	= 'True'
	*/
	-- ----------------------------------------------------------

	-- Verifica que la tabla tbMail_Recipients tenga algo
	IF NOT EXISTS(	SELECT 1
						FROM tbMail_Recipients tmr WITH (NOLOCK)
	              		WHERE	tmr.comp_id = @comp_id AND
	              				tmr.guid	= @guid)
		BEGIN
			INSERT INTO tbMail_Recipients
				(	comp_id,		[guid],		mr_checked,		mr_recipientId	)
					SELECT	tc.comp_id,
							@guid ,
							'False',
							tc.cust_id
						FROM	tbCustomer tc WITH (NOLOCK)
		END


	DECLARE @strWhere VARCHAR(8000)
	SET @strWhere = ' WHERE tmr.comp_id = ' + convert( varchar(10),@comp_id) + ' AND tmr.guid = ''' +  CAST(@guid AS VARCHAR(36))  + ''''


	If @pQuestion = 'True'
		BEGIN

			EXEC (	'UPDATE tbMail_Recipients
						SET	mr_checked = 0
						FROM tbMail_Recipients tmr
						 ' + @strWhere )
		END


	IF CHARINDEX('=', @where) > 0 SET @strWhere = @strWhere + ' and ' + @where


	CREATE TABLE #tmpCustomerFiltered (cust_id INT PRIMARY KEY)

	DECLARE @strAux AS VARCHAR(MAX)
	SET @strAux = CASE
			              WHEN	@where = '' THEN '1 = 1'
			              ELSE	@where
			          END
	EXEC ( '
	INSERT INTO #tmpCustomerFiltered
		SELECT cust_id
			FROM tbCustomer 	WITH (NOLOCK)
			WHERE ' + @strAux
		)



	SELECT	' ' [ ],
			tmr.mr_checked,
			tc.cust_name,
			tc.cust_email,
			tc2.country_desc,
			ts.state_desc,
			tmr.mr_id			[Id]
			FROM	tbMail_Recipients						tmr				WITH (NOLOCK)
					INNER JOIN tbCustomer					tc				WITH (NOLOCK)
					ON	tmr.comp_id			= tc.comp_id	AND
						tmr.mr_recipientId	= tc.cust_id
					INNER JOIN tbsysCountry					tc2				WITH (NOLOCK)
					ON	tc2.country_id		= tc.country_id
					INNER JOIN tbsysState					ts				WITH (NOLOCK)
					ON  ts.country_id		= tc.country_id	AND
						ts.state_id			= tc.state_id
					INNER JOIN #tmpCustomerFiltered			tmp
						ON tmp.cust_id		= tmr.mr_recipientId
			WHERE	tmr.comp_id				= @comp_id		AND
					tmr.guid				= @guid			AND
					ISNULL(tc.cust_excludeOfCustomerMailing,'False')	= 'False'
			DROP TABLE #tmpCustomerFiltered

END
GO



CREATE procedure [dbo].[spCustomer_getReport]
(
  @comp_id			INT,
  @lang_id			INT,
  @page_id			INT,

  @option			INT,
  @cust_name		VARCHAR(200),
  @fc_id			INT,
  @ck_id			INT,
  @prli_id			INT,
  @country_id		INT,
  @tnt_id			INT,
  @stor_id			INT,
  @curr_id			INT,
  @disc_id			INT,
  @st_id			INT,
  @bra_id			INT,
  @dl_id			INT,
  @sm_id			INT,
  @state_id			INT,
  @CustomerGuid		VARCHAR(50),
  @intBranch4Lang	INT
)
AS
	BEGIN

		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		/*
		DECLARE   @comp_id  int,
			@lang_id  int,
			@page_id  int,
			@fc_id   int,
			@ck_id   int,
			@prli_id  int,
			@country_id  int,
			@tnt_id   int,
			@stor_id  int,
			@curr_id  int,
			@disc_id  int,
			@st_id   int,
			@bra_id   int,
			@dl_id   int,
			@sm_id   int,
			@state_id  int,
			@option   int,
			@cust_name  varchar(200)

		SELECT   @comp_id  = 1,
			@lang_id  = 2,
			@page_id  = 10005,
			@fc_id   = -1,
			@ck_id   = -1,
			@prli_id  = -1,
			@country_id  = -1,
			@tnt_id   = -1,
			@stor_id  = -1,
			@curr_id  = -1,
			@disc_id  = -1,
			@st_id   = -1,
			@bra_id   = -1,
			@dl_id   = -1,
			@sm_id   = -1,
			@state_id  = -1,
			@option   = -1,
			@cust_name  = 'ya'

		*/


		DECLARE @lGuid AS UNIQUEIDENTIFIER

		 SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@CustomerGuid)

		 -- -------------------------------------------------------------
		 -- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		 -- -------------------------------------------------------------
		 DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		 INSERT INTO @tblComplexFilter_Customer
		  SELECT tcf.sl_id
		   FROM tbComplexFilter tcf
		   WHERE tcf.sl_guid = @lGuid     AND
				tcf.sl_selected = 'True'
		 IF @@ROWCOUNT = 0
		  BEGIN
		   INSERT INTO @tblComplexFilter_Customer
			SELECT tc.cust_id
			FROM tbCustomer tc
			WHERE tc.comp_id = @comp_id
		  END
		 -- -------------------------------------------------------------





		DECLARE @fun_id INT
		SET @fun_id = 1



		SELECT
			BR.bra_desc,
			convert(varchar,c.cust_id) + '-' + convert(varchar,c.cust_name)  [cust_name],
			C.cust_name1,
			FC.fc_desc,
			C.cust_taxNumber,
			C.cust_web,
			o.optval_desc [cust_inactive],
			C.cust_partnerOf,
			C.cust_contact,
			C.cust_address,
			C.cust_city,
			C.cust_zip,
			CNT.country_desc,
			STT.state_desc,
			C.cust_phone1,
			C.cust_phone2,
			C.cust_email,
			C.cust_fax,
			C.cust_picture,
			SM.sm_name,
			CK.ck_name,
			ST.st_desc,
			DC.disc_desc,
			DLV.dl_name,
			C.cust_credit_max,
			C.cust_credit_own,
			CR.curr_desc,
			US.user_nick,
			PL.prli_desc,
			STG.stor_desc,
			TNT.tnt_desc,
			AC.acc_code
			FROM tbCustomer									C
				INNER JOIN @tblComplexFilter_Customer		tmpC
					ON	tmpC.cust_id	= C.cust_id
				LEFT JOIN tbsysFiscalClass					FC
					ON	C.[fc_id]		= FC.[fc_id]
				LEFT JOIN tbCustomerKind					CK
					ON	C.[ck_id]		= CK.[ck_id]
				LEFT JOIN [tbPriceList]						PL
					ON	C.[prli_id]		= PL.[prli_id]
				LEFT JOIN tbsysCountry						CNT
					ON	C.[country_id]	= CNT.[country_id]
				LEFT JOIN tbsysTaxNumberTypes				TNT
					ON	TNT.[tnt_id]	= C.[tnt_id]
				LEFT JOIN tbStorage							STG
					ON	C.[stor_id]		= STG.[stor_id]
				LEFT JOIN tbsysCurrency						CR
					ON	C.[curr_id]		= CR.[curr_id]
				LEFT JOIN [tbDiscount]						DC
					ON	C.[disc_id]		= DC.[disc_id]
				LEFT JOIN [tbSalesTerms]					ST
					ON	C.[st_id]		= ST.[st_id]
				LEFT JOIN [tbBranch]						BR
					ON	C.[bra_id]		= BR.[bra_id]
				LEFT JOIN [tbDelivery]						DLV
					ON	C.[dl_id]		= DLV.[dl_id]
				LEFT JOIN [tbSalesman]						SM
					ON	C.[sm_id]		= SM.[sm_id]
				LEFT JOIN [tbsysState]						STT
					ON	C.[state_id]	= STT.[state_id]
				LEFT JOIN [tbUser]							US
					ON	C.[user_id]		= US.[user_id]
				LEFT JOIN [tbAccountant]					AC
					ON	C.[acc_count_id]= AC.[acc_count_id]
				LEFT JOIN [tbsysOptionsValues]				O
					ON  O.[optval_id]	= C.[cust_inactive]	AND
						O.[optval_class]= 1					AND
						O.[lang_id]		= @lang_id

			WHERE	C.[comp_id]			= @comp_id										AND
					(@fc_id				= -1  OR  C.[fc_id]			= @fc_id)			AND
					(@ck_id				= -1  OR  C.[ck_id]			= @ck_id)			AND
					(@prli_id			= -1  OR  C.[prli_id]		= @prli_id)			AND
					(@country_id		= -1  OR  C.[country_id]	= @country_id)		AND
					(@tnt_id			= -1  OR  C.[tnt_id]		= @tnt_id)			AND
					(@stor_id			= -1  OR  C.[stor_id]		= @stor_id)			AND
					(@curr_id			= -1  OR  C.[curr_id]		= @curr_id)			AND
					(@disc_id			= -1  OR  C.[disc_id]		= @disc_id)			AND
					(@st_id				= -1  OR  C.[st_id]			= @st_id)			AND
					(@bra_id			= -1  OR  C.[bra_id]		= @bra_id)			AND
					(@dl_id				= -1  OR  C.[dl_id]			= @dl_id)			AND
					(@sm_id				= -1  OR  C.[sm_id]			= @sm_id)			AND
					(@state_id			= -1  OR  C.[state_id]		= @state_id)		AND
					(
					  (@option = -1 )												OR
					  (@option = 0 AND C.cust_name LIKE @cust_name + '%')			OR
					  (@option = 1 AND C.cust_name LIKE '%' + @cust_name + '%')		OR
					  (@option = 2 AND C.cust_name = @cust_name)					OR
					  (@option = 3 AND C.cust_name <> @cust_name)					OR
					  (@option = 4 AND C.cust_name NOT LIKE '%' + @cust_name + '%')
					  )

			--and  (C.acc_count_id  = -1  or  C.acc_count_id = @acc_count_id)
			--and     (C.[user_id]  = -1  or  C.[user_id]  = @user_id)

			ORDER BY c.cust_name


		EXEC [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id
		--exec [spReports_getData] 1, 2, 10005

		/* devolución de parámetros recibidos */
		DECLARE @related_page_id INT
		SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
		/*************************************************************************************************************/ /* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros   */ /*   SELECT t.ctrl_id, t.[text_desc]
		  FROM [tbsysTexts]    t
			inner join [tbsysControls] c
			on c.[ctrl_id] = t.[ctrl_id]
		  where t.[lang_id] = @lang_id
		  and  t.[page_id] = @related_page_id
		  and  t.[type_id] = 1
		*/
		/*************************************************************************************************************/

		SELECT
		  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 43
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params1],

		  CASE @option WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			(select tov.optval_desc
			from  dbo.tbsysOptionsValues tov
			where tov.optval_class =  2
			and   tov.lang_id      = @lang_id
			And   tov.optval_id    = @option)
		  End [params2],

		   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 370
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params3],

		  CASE @fc_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			(SELECT  tfc.fc_desc
			 FROM tbsysFiscalClass tfc
			 WHERE  tfc.fc_id = @fc_id)
		  END  [params4],

		   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 372
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params5],

		  CASE @ck_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
		   (SELECT  tck.ck_name
			 FROM tbCustomerKind tck
			 WHERE Tck.comp_id = @comp_id AND Tck.ck_id = @ck_id)
		  END  [params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 109
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params7],

		  CASE @prli_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
		  (SELECT  tpl.prli_desc
			 FROM tbPriceList tpl
			 WHERE tpl.prli_id= @prli_id)
		  END  [params8],

			  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 373
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params9],

		  CASE @tnt_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
		  (SELECT  ttnt.tnt_desc
			 FROM tbsysTaxNumberTypes ttnt
			 WHERE ttnt.tnt_id= @tnt_id)
		  END  [params10],

		  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 57
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params11],

		  CASE @country_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			 (SELECT  Tc.country_desc
			 FROM tbsysCountry tc
			 WHERE tc.country_id= @country_id)
		  END  [params12],


		  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 59
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params13],

		  CASE @state_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			 (SELECT  ts.state_desc
			 FROM tbsysState ts
			 WHERE Ts.state_id= @state_id)
		  END  [params14],

		   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 175
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params15],

		  CASE @st_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			 (SELECT  tst.st_desc
			 FROM tbSalesTerms tst
			  Where  tst.comp_id =@comp_id
			 And     tst.st_id = @st_id)
		  END  [params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 173
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params17],

		  CASE @disc_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			(SELECT  td.disc_desc
			 FROM tbDiscount td
			 WHERE td.disc_id = @disc_id)
		  END  [params18],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 106
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params19],

		  CASE @disc_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			 (SELECT  tc.curr_desc
			 FROM tbsysCurrency tc
			 WHERE  tc.curr_id= @curr_id)
		  END  [params20],


			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 111
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params21],

		  CASE @stor_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			(SELECT  ts.stor_desc
			 FROM tbStorage ts
			 WHERE  ts.stor_id= @stor_id)
		  END  [params22],

			   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 28
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params23],

		  CASE @bra_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			(SELECT  tb2.bra_desc
			 FROM tbBranch tb2
			 WHERE  tb2.bra_id= @bra_id)
		  END  [params24],

		  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 170
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params25],

		  CASE @dl_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			 (SELECT  td.dl_name
			 FROM tbDelivery td
			 WHERE td.comp_id = @comp_id AND td.dl_id = @dl_id)
		  END  [params26],

		   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				WHERE t.ctrl_id = 172
				--AND t.[lang_id] = @lang_id
				and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params27],

		  CASE @sm_id WHEN -1 THEN
			(SELECT  tut.utexts_desc
			 FROM tbsysUniqueTexts tut
			 WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
		   ELSE
			  (SELECT  ts.sm_name
			 FROM tbSalesman ts
			 WHERE ts.comp_id = @comp_id AND Ts.sm_id = @sm_id)
		  END  [params28],

		  (Select @cust_name) [params29]






















	END

GO








CREATE PROCEDURE [dbo].[spCustomer_getTransactionData]
(
	@comp_id			INT,
	@cust_id			INT,
	@bra_id				INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------------------
	/*
	DECLARE @comp_id			INT,
			@cust_id			INT,
			@user_id			INT,
			@bra_id				INT
	SELECT 	@comp_id			=1,
			@cust_id			=24289,
			@user_id			=1,
			@bra_id				=1
	*/
-- -----------------------------------------------------------------------------

	DECLARE @days_in_site			AS INT = 0
	DECLARE @num_of_transactions	AS INT = 0

	SELECT @days_in_site = 	ABS(DATEDIFF(DAY,c.cust_cd,GETDATE()))
		FROM 	dbo.tbCustomer	c	WITH (NOLOCK)
		WHERE	c.comp_id				= @comp_id
		AND		c.cust_id				= @cust_id


	SELECT @num_of_transactions =  COUNT(*)
		FROM tbCommercialTransactions AS tct WITH (NOLOCK)
		WHERE	tct.comp_id = @comp_id	AND
				tct.cust_id = @cust_id	AND
				tct.sd_id	= 1			AND
				tct.bra_id  = @bra_id


	SELECT	@days_in_site			[days_in_site],
			@num_of_transactions	[num_of_transactions]




END


GO









CREATE PROCEDURE [dbo].[spCustomer_getWebSiteImages]
(
	@comp_id				INT,
	@bolGetNullImages		BIT
)
AS

BEGIN


	SET NOCOUNT ON


	SELECT
		tsc.cust_id					[Id],
		tsc.cust_picture			[Image]
		FROM tbCustomer tsc		WITH (NOLOCK)
		WHERE	tsc.comp_id = @comp_id			AND
				( @bolGetNullImages = 'True' OR
				tsc.cust_picture IS NOT NULL)	AND ISNULL(tsc.cust_web,'') <> ''


END
GO







CREATE PROCEDURE [dbo].[spCustomer_insertDataFromMercadoLibre]
(
	@comp_id				INT,
	@cust_id				INT,

	@cust_name				NVARCHAR(200),
	@country_id				INT,
	@state_id				INT,
	@cust_address			NVARCHAR(150),
	@cust_City				NVARCHAR(200),
	@cust_zip				NVARCHAR(20),
	@fc_id					INT,
	@tnt_id					INT,
	@cust_taxNumber			NVARCHAR(50),
	@cust_email				NVARCHAR(300),
	@cust_Phone1			NVARCHAR(200),
	@cust_webNickName		NVARCHAR(50),
	@cust_webPassword		NVARCHAR(50),
	@MLContactID			NVARCHAR(30),
	@return_value			INT	OUTPUT
)
AS


BEGIN




	SET NOCOUNT ON

	-- ---------------------------------------------------------
	-- Test
	-- ---------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@cust_id			INT,

			@name				NVARCHAR(200),
			@country			INT,
			@state				INT,
			@address			NVARCHAR(150),
			@city				NVARCHAR(200),
			@fiscalclass		INT,
			@taxnumbertype		INT,
			@taxnumber			NVARCHAR(50),
			@email				NVARCHAR(300),
			@phone				NVARCHAR(200),
			@nickname			NVARCHAR(50),
			@pass1				NVARCHAR(50),

			@returnvalue		INT

	SELECT 	@comp_id			=1,
			@cust_id			=24300,

			@name				='PRUEBA WEB',
			@country			=54,
			@state				=54019,
			@address			='DOMICILIO PRUEBA WEB',
			@city				='Capital Federal',
			@fiscalclass		=1,
			@taxnumbertype		=1,
			@taxnumber			='30-65856224-6',
			@email				='prueba@prueba.com',
			@phone				='3220-7172',
			@nickname			='nuevo',
			@pass1				='nuveo'

	*/
	-- ---------------------------------------------------------




	DECLARE @cust_id_new	INT

	SET @return_value = 0




	-- Primero busca por ID de MeercadoLibre
	IF @MLContactID <> ''
		BEGIN
			IF EXISTS(
						SELECT 1
							FROM tbcustomer tc	WITH (NOLOCK)
							WHERE	tc.comp_id				= @comp_id AND
									tc.cust_MercadoLibreID	= @MLContactID
					)
				BEGIN
					SELECT @return_value = tc.cust_id
						FROM tbcustomer tc		WITH (NOLOCK)
						WHERE	tc.comp_id				= @comp_id AND
								tc.cust_MercadoLibreID	= @MLContactID

					UPDATE tbcustomer WITH (ROWLOCK)	-- para que no pise los mails que no son de mercadolibre y ya estan cargados
						SET		cust_email	=
												CASE
													WHEN cust_email = ''								THEN @cust_email
													WHEN UPPER(@cust_email) LIKE '%MAIL.MERCADOLIBRE%'  THEN cust_email
													ELSE												  	 @cust_email
												END
						WHERE	comp_id		= @comp_id		AND
								cust_id		= @return_value AND
								cust_email <> @cust_email
					RETURN
				END
		END




	--controlamos que el nickname ya no exista para otro cliente
	IF EXISTS (	SELECT 1
	           		FROM tbCustomer tc			WITH (NOLOCK)
					WHERE	tc.comp_id						= @comp_id
					AND		tc.cust_MercadoLibreNickName	= @cust_webNickName)
		BEGIN

			SELECT @return_value = tc.cust_id
				FROM tbCustomer tc			WITH (NOLOCK)
				WHERE	tc.comp_id							= @comp_id
				AND		tc.cust_MercadoLibreNickName		= @cust_webNickName

			UPDATE tbcustomer WITH (ROWLOCK)
				SET		cust_email	=
										CASE
											WHEN cust_email = ''								THEN @cust_email
											WHEN UPPER(@cust_email) LIKE '%MAIL.MERCADOLIBRE%'  THEN cust_email
											ELSE													 @cust_email
										END
				--@cust_email
				WHERE	comp_id		= @comp_id		AND
						cust_id		= @return_value AND
						cust_email <> @cust_email
			--SET @return_value = -1
			RETURN
		END



	-- Adecuamos el Numero de Documento Informado
	SET @cust_taxNumber = dbo.fnGetOnlyNumbers(@cust_taxNumber)
	--IF	@tnt_id = 80				AND
	--	LEN(@cust_taxNumber) = 11
	--	BEGIN
	--		SET @cust_taxNumber = SUBSTRING(@cust_taxNumber, 1,2) + '-' + SUBSTRING(@cust_taxNumber, 3,8) + '-' + SUBSTRING(@cust_taxNumber, 11,1)
	--	END




	--controlamos que ya no exista un cliente con el mismo tipo y nro de documento
	IF @return_value = 0 and EXISTS (SELECT 1
										FROM tbCustomer tc	WITH (NOLOCK)
										WHERE	tc.comp_id			= @comp_id
										AND		tc.tnt_id			= @tnt_id
										AND		dbo.fnGetOnlyNumbers(tc.cust_taxNumber)	= @cust_taxNumber)
		BEGIN
			SELECT @return_value = tc.cust_id
				FROM tbCustomer tc	WITH (NOLOCK)
				WHERE	tc.comp_id			= @comp_id
				AND		tc.tnt_id			= @tnt_id
				AND		dbo.fnGetOnlyNumbers(tc.cust_taxNumber)	= @cust_taxNumber

			UPDATE tbcustomer WITH (ROWLOCK)
				SET		cust_email	=
										CASE
											WHEN cust_email = ''								THEN @cust_email
											WHEN UPPER(@cust_email) LIKE '%MAIL.MERCADOLIBRE%'  THEN cust_email
											ELSE													 @cust_email
										END
				--@cust_email
				WHERE	comp_id		= @comp_id		AND
						cust_id		= @return_value AND
						cust_email <> @cust_email
			RETURN
		END


	-- Si es CUIT trata de poner la descripcion de AFIP
	IF @tnt_id = 80
		BEGIN
			SELECT @cust_name = tta.afip_nombre
				FROM tbsysTaxAFIP tta
				WHERE tta.afip_cuit = replace(@cust_taxNumber,'-','')
		END



	IF @return_value = 0
		BEGIN


			DECLARE @city_id INT

			DECLARE @table_city AS TABLE (city_id INT)

			INSERT INTO @table_city(city_id)
			EXEC spCities_getIdByDesc @comp_id, -10, @country_id, @state_id, @cust_City

			SELECT TOP 1 @city_id = city_id FROM @table_city




			INSERT INTO tbCustomer
			(
				comp_id,					bra_id,
				cust_name,
				cust_lastName,
				cust_name1,					fc_id,					cust_taxNumber,
				stcIB_Id,					cust_taxIBNumber,		cust_web,
				cust_inactive,				cust_partnerOf,			cust_contact,
				cust_address,				cust_city,				cust_zip,
				country_id,					state_id,				cust_phone1,
				cust_phone2,				cust_email,				cust_fax,
				cust_picture,				sm_id,					ck_id,
				st_id,						disc_id,				dl_id,
				cust_credit_max,			cust_credit_own,		curr_id,
				acc_count_id,				[user_id],				prli_id,
				stor_id,					tnt_id,					ss_id,
				cust_isEditing,				cust_isEditingCd,		cust_isEditingUserId,
				cust_annotation,			cust_judMan,			cust_note1,
				cust_note2,					cust_note3,				cust_note4,
				cust_address4Delivery,		cust_address4Payments,
				cust_webNickName,
				cust_webPassword,			bra_id4Emmition,		city_id,
				cust_4InitialValues,		sm_id_2,				cust_showstock,
				cust_showpricelist,			cust_showzerostockitems,
				cust_login,
				cust_login_cd,
				cust_login_ip,			cust_login_name,
				cust_SaleOrderMaxValue,		cust_cd,				fecountry_id,
				fex_cuitID,					cust_contact4Payments,	cust_email4Payments,
				cust_contact4Management,	cust_email4Management,	cust_contact4Administration,
				cust_email4Administration,	cust_contact4Logistics,	cust_email4Logistics,
				act_id,		cust_SaleOrderDisableConcurrentProc,	cust_SaleOrderBranchTransfer,
				coslis_id,					coslis_idB,				cust_webPending2Verify ,
				cust_excludeInCITI,
				stca_id, cust_Mailing4CustOverdueDebt_Excluded,
				cust_contact4Alternative, cust_email4Alternative, cust_contact4RMA,
				cust_email4RMA, cust_address4RMA, cust_isAvailable4InternalRMA,
				cust_phone4RMA, cust_contact4AlternativeII, cust_email4AlternativeII,
				rmap_id, street_id, cust_addressNumber, cust_addressAdditional,
				rating_id, marst_id, cust_isOwner, cust_ownerOf, cust_remuneration,
				cram_id, cust_ramification, cust_jobTitle, cust_jobAddress,
				cust_jobCity, cust_jobCity_Id, cust_jobPhone, cust_jobName,
				cust_jobPayDate, cust_jobAdmissionDate, corp_id, cust_addressFloor,
				stg_id, cust_imageChecksum, cust_ratingProcessCheck,
				rating_id_previous, rating_id_cd, cust_firstname,
				def_id, cmde_noAction, cust_updatedFromABM,
				cust_jobPayIntervalIs15, cust_disabled4PersonalLoan, cust_birthDay,
				cust_maleOrFemale,  cust_cellPhone	,
				cust_MercadoLibreNickName	,
				cust_checked,
				cust_MercadoLibreID
			)
			SELECT	tc.comp_id,
					tc.bra_id,
					@cust_name,
					@cust_name,
					tc.cust_name1,
					@fc_id,
					@cust_taxNumber,
					tc.stcIB_Id, tc.cust_taxIBNumber, tc.cust_web,
					tc.cust_inactive, tc.cust_partnerOf, tc.cust_contact,
					@cust_address,
					convert(nvarchar(60),@cust_City),
					@cust_zip,
					@country_id,
					@state_id,
					@cust_Phone1,
					tc.cust_phone2,
					@cust_email,
					tc.cust_fax, tc.cust_picture, tc.sm_id,
					tc.ck_id, tc.st_id, tc.disc_id, tc.dl_id, tc.cust_credit_max,
					tc.cust_credit_own, tc.curr_id, tc.acc_count_id,
					tc.[user_id], tc.prli_id, tc.stor_id,
					@tnt_id,
					tc.ss_id,tc.cust_isEditing,	tc.cust_isEditingCd,
					tc.cust_isEditingUserId, tc.cust_annotation, tc.cust_judMan, tc.cust_note1,
					tc.cust_note2, tc.cust_note3, tc.cust_note4,
					tc.cust_address4Delivery, tc.cust_address4Payments,
					'',
					'',
					tc.bra_id4Emmition,
					@city_id,
					tc.cust_4InitialValues, tc.sm_id_2,
					tc.cust_showstock, tc.cust_showpricelist, tc.cust_showzerostockitems,
					'False',
					GETDATE(),
					tc.cust_login_ip, tc.cust_login_name,
					tc.cust_SaleOrderMaxValue, tc.cust_cd, tc.fecountry_id, tc.fex_cuitID,
					tc.cust_contact4Payments, tc.cust_email4Payments,
					tc.cust_contact4Management, tc.cust_email4Management,
					tc.cust_contact4Administration, tc.cust_email4Administration,
					tc.cust_contact4Logistics, tc.cust_email4Logistics, tc.act_id,
					tc.cust_SaleOrderDisableConcurrentProc, tc.cust_SaleOrderBranchTransfer,
					tc.coslis_id, tc.coslis_idB, tc.cust_webPending2Verify,
					tc.cust_excludeInCITI,
					tc.stca_id, tc.cust_Mailing4CustOverdueDebt_Excluded,
					tc.cust_contact4Alternative, tc.cust_email4Alternative, tc.cust_contact4RMA,
					tc.cust_email4RMA, tc.cust_address4RMA, tc.cust_isAvailable4InternalRMA,
					tc.cust_phone4RMA, tc.cust_contact4AlternativeII, tc.cust_email4AlternativeII,
					tc.rmap_id, tc.street_id, tc.cust_addressNumber, tc.cust_addressAdditional,
					tc.rating_id, tc.marst_id, tc.cust_isOwner, tc.cust_ownerOf, tc.cust_remuneration,
					tc.cram_id, tc.cust_ramification, tc.cust_jobTitle, tc.cust_jobAddress,
					tc.cust_jobCity, tc.cust_jobCity_Id, tc.cust_jobPhone, tc.cust_jobName,
					tc.cust_jobPayDate, tc.cust_jobAdmissionDate, tc.corp_id,tc. cust_addressFloor,
					tc.stg_id, tc.cust_imageChecksum, tc.cust_ratingProcessCheck,
					tc.rating_id_previous, tc.rating_id_cd, tc.cust_firstname,
					tc.def_id, tc.cmde_noAction, tc.cust_updatedFromABM,
					tc.cust_jobPayIntervalIs15, tc.cust_disabled4PersonalLoan, tc.cust_birthDay,
					tc.cust_maleOrFemale,
					tc.cust_cellPhone,
					@cust_webNickName,
					NULL,
					@MLContactID

			FROM	tbCustomer tc WITH (NOLOCK)

			WHERE	tc.comp_id = @comp_id
			AND		tc.cust_id = @cust_id



			SET @return_value = @@IDENTITY



		END


END
GO


CREATE PROCEDURE [dbo].[spCustomer_insertDataFromWebService]
(
	@comp_id				INT,
	@cust_id				INT,
	@ws_id					UNIQUEIDENTIFIER,
	@cust_name				NVARCHAR(200),
	@country_id				INT,
	@state_id				INT,
	@cust_address			NVARCHAR(150),
	@cust_City				NVARCHAR(200),
	@cust_zip				NVARCHAR(20),
	@fc_id					INT,
	@tnt_id					INT,
	@cust_taxNumber			NVARCHAR(50),
	@cust_email				NVARCHAR(300),
	@cust_Phone1			NVARCHAR(200),
	@cust_webNickName		NVARCHAR(50),
	@cust_webPassword		NVARCHAR(50),
	@cust_login				BIT,

	@return_value			INT	OUTPUT
)
AS

BEGIN
	SET NOCOUNT ON

	--------------------------------------------------------------------------------------------------------
	-- ATENCIÓN! SI SE TOCA ALGO ACÁ, TAMBIÉN TOCARLO EN spCustomer_insertDataFromWebSite
	--------------------------------------------------------------------------------------------------------

	-- ------------------------------------------------------------------
	-- Test
	-- ------------------------------------------------------------------
	/*
	DECLARE	@comp_id				INT,
			@cust_id				INT,
			@ws_id					UNIQUEIDENTIFIER,
			@cust_name				NVARCHAR(200),
			@country_id				INT,
			@state_id				INT,
			@cust_address			NVARCHAR(150),
			@cust_City				NVARCHAR(200),
			@cust_zip				NVARCHAR(20),
			@fc_id					INT,
			@tnt_id					INT,
			@cust_taxNumber			NVARCHAR(50),
			@cust_email				NVARCHAR(300),
			@cust_Phone1			NVARCHAR(200),
			@cust_webNickName		NVARCHAR(50),
			@cust_webPassword		NVARCHAR(50),
			@cust_login				BIT,

			@return_value			INT

	SELECT 	@comp_id				= 1,
			@cust_id				= 101498,
			@ws_id					= '02d9a54c-a6e9-47d4-9857-89f9eaea103f',
			@cust_name				= 'CUSTOMER TEST',
			@country_id				= 54,
			@state_id				= 54019,
			@cust_address			= 'CALLE FALSA 123',
			@cust_City				= 'Capital Federal',
			@cust_zip				= '1036',
			@fc_id					= 2,
			@tnt_id					= 5,
			@cust_taxNumber			= '32507274',
			@cust_email				= 'Mail@mail.com',
			@cust_Phone1			= '030345611',
			@cust_webNickName		= 'WebUserTest',
			@cust_webPassword		= 'PassWord',
			@cust_login				= 'True'
	*/
	-- ------------------------------------------------------------------


	SET @cust_webNickName = LOWER(dbo.fnStrAllTrim(@cust_webNickName))
	SET @cust_webPassword = LOWER(dbo.fnStrAllTrim(@cust_webPassword))


	DECLARE @cust_id_new	INT

	SET		@return_value = 0

	DECLARE @intCustIdYetExists AS INT = -1
	--controlamos que ya no exista un cliente con el mismo tipo y nro de documento
	SELECT @intCustIdYetExists = tc.cust_id
		FROM tbCustomer tc	WITH (NOLOCK)
		WHERE	tc.comp_id			= @comp_id
		AND		tc.tnt_id			= @tnt_id
		AND		tc.cust_taxNumber	= @cust_taxNumber
	IF	@return_value = 0			AND
		@intCustIdYetExists <> -1
		BEGIN
			SET @return_value = -2
		END


	IF @return_value = 0	-- SI NO lo encontro lod a de alta
		BEGIN

			DECLARE @city_id INT

			DECLARE @table_city AS TABLE (city_id INT)

			INSERT INTO @table_city(city_id)
				EXEC spCities_getIdByDesc @comp_id, -10,@country_id, @state_id, @cust_City

			SELECT TOP 1 @city_id = city_id
				FROM @table_city


			INSERT INTO tbCustomer	WITH (ROWLOCK)
			(
				comp_id,					bra_id,
				cust_name,
				cust_lastName,
				cust_name1,					fc_id,					cust_taxNumber,
				stcIB_Id,					cust_taxIBNumber,		cust_web,
				cust_inactive,				cust_partnerOf,			cust_contact,
				cust_address,				cust_city,				cust_zip,
				country_id,					state_id,				cust_phone1,
				cust_phone2,				cust_email,				cust_fax,
				cust_picture,				sm_id,					ck_id,
				st_id,						disc_id,				dl_id,
				cust_credit_max,			cust_credit_own,		curr_id,
				acc_count_id,				[user_id],				prli_id,
				stor_id,					tnt_id,					ss_id,
				cust_isEditing,				cust_isEditingCd,		cust_isEditingUserId,
				cust_annotation,			cust_judMan,			cust_note1,
				cust_note2,					cust_note3,				cust_note4,
				cust_address4Delivery,		cust_address4Payments,	cust_webNickName,
				cust_webPassword,			bra_id4Emmition,		city_id,
				cust_4InitialValues,		sm_id_2,				cust_showstock,
				cust_showpricelist,			cust_showzerostockitems,
				cust_login,
				cust_login_cd,
				cust_login_ip,			cust_login_name,
				cust_SaleOrderMaxValue,		cust_cd,				fecountry_id,
				fex_cuitID,					cust_contact4Payments,	cust_email4Payments,
				cust_contact4Management,	cust_email4Management,	cust_contact4Administration,
				cust_email4Administration,	cust_contact4Logistics,	cust_email4Logistics,
				act_id,		cust_SaleOrderDisableConcurrentProc,	cust_SaleOrderBranchTransfer,
				coslis_id,					coslis_idB,				cust_webPending2Verify,
				cust_excludeInCITI,
				stca_id, cust_Mailing4CustOverdueDebt_Excluded,
				cust_contact4Alternative, cust_email4Alternative, cust_contact4RMA,
				cust_email4RMA, cust_address4RMA, cust_isAvailable4InternalRMA,
				cust_phone4RMA, cust_contact4AlternativeII, cust_email4AlternativeII,
				rmap_id, street_id, cust_addressNumber, cust_addressAdditional,
				rating_id, marst_id, cust_isOwner, cust_ownerOf, cust_remuneration,
				cram_id, cust_ramification, cust_jobTitle, cust_jobAddress,
				cust_jobCity, cust_jobCity_Id, cust_jobPhone, cust_jobName,
				cust_jobPayDate, cust_jobAdmissionDate, corp_id, cust_addressFloor,
				stg_id, cust_imageChecksum, cust_ratingProcessCheck,
				rating_id_previous, rating_id_cd, cust_firstname,
				def_id, cmde_noAction, cust_updatedFromABM,
				cust_jobPayIntervalIs15, cust_disabled4PersonalLoan, cust_birthDay,
				cust_maleOrFemale,  cust_cellPhone,
				cust_excludeOfCustomerMailing, ws_internalID
			)
			SELECT	tc.comp_id, tc.bra_id,
					@cust_name,
					@cust_name,
					tc.cust_name1,
					@fc_id,
					@cust_taxNumber,
					tc.stcIB_Id, tc.cust_taxIBNumber, tc.cust_web,
					tc.cust_inactive, tc.cust_partnerOf, tc.cust_contact,
					@cust_address,
					convert(nvarchar(60),@cust_City),
					@cust_zip,
					@country_id,
					@state_id,
					@cust_Phone1,
					tc.cust_phone2,
					@cust_email,
					tc.cust_fax, tc.cust_picture, tc.sm_id,
					tc.ck_id, tc.st_id, tc.disc_id, tc.dl_id, tc.cust_credit_max,
					tc.cust_credit_own, tc.curr_id, tc.acc_count_id,
					tc.[user_id], tc.prli_id, tc.stor_id,
					@tnt_id,
					tc.ss_id,tc.cust_isEditing,	tc.cust_isEditingCd,
					tc.cust_isEditingUserId, tc.cust_annotation, tc.cust_judMan, tc.cust_note1,
					tc.cust_note2, tc.cust_note3, tc.cust_note4,
					tc.cust_address4Delivery, tc.cust_address4Payments,
					@cust_webNickName,
					/*@cust_webPassword*/'',
					tc.bra_id4Emmition,
					@city_id,
					tc.cust_4InitialValues, tc.sm_id_2,
					tc.cust_showstock, tc.cust_showpricelist, tc.cust_showzerostockitems,
					~@cust_login,
					GETDATE(),
					tc.cust_login_ip, tc.cust_login_name,
					tc.cust_SaleOrderMaxValue, tc.cust_cd, tc.fecountry_id, tc.fex_cuitID,
					tc.cust_contact4Payments, tc.cust_email4Payments,
					tc.cust_contact4Management, tc.cust_email4Management,
					tc.cust_contact4Administration, tc.cust_email4Administration,
					tc.cust_contact4Logistics, tc.cust_email4Logistics, tc.act_id,
					tc.cust_SaleOrderDisableConcurrentProc, tc.cust_SaleOrderBranchTransfer,
					tc.coslis_id, tc.coslis_idB, tc.cust_webPending2Verify,
					tc.cust_excludeInCITI,
					tc.stca_id, tc.cust_Mailing4CustOverdueDebt_Excluded,
					tc.cust_contact4Alternative, tc.cust_email4Alternative, tc.cust_contact4RMA,
					tc.cust_email4RMA, tc.cust_address4RMA, tc.cust_isAvailable4InternalRMA,
					tc.cust_phone4RMA, tc.cust_contact4AlternativeII, tc.cust_email4AlternativeII,
					tc.rmap_id, tc.street_id, tc.cust_addressNumber, tc.cust_addressAdditional,
					tc.rating_id, tc.marst_id, tc.cust_isOwner, tc.cust_ownerOf, tc.cust_remuneration,
					tc.cram_id, tc.cust_ramification, tc.cust_jobTitle, tc.cust_jobAddress,
					tc.cust_jobCity, tc.cust_jobCity_Id, tc.cust_jobPhone, tc.cust_jobName,
					tc.cust_jobPayDate, tc.cust_jobAdmissionDate, tc.corp_id,tc. cust_addressFloor,
					tc.stg_id, tc.cust_imageChecksum, tc.cust_ratingProcessCheck,
					tc.rating_id_previous, tc.rating_id_cd, tc.cust_firstname,
					tc.def_id, tc.cmde_noAction, tc.cust_updatedFromABM,
					tc.cust_jobPayIntervalIs15, tc.cust_disabled4PersonalLoan, tc.cust_birthDay,
					tc.cust_maleOrFemale,  tc.cust_cellPhone,
					tc.cust_excludeOfCustomerMailing,
					NULL
			FROM	tbCustomer tc		WITH (NOLOCK)
			WHERE	tc.comp_id = @comp_id
			AND		tc.cust_id = @cust_id

			SET @return_value = @@IDENTITY

			SELECT
					ISNULL((	SELECT	tc.country_desc
		      	 				FROM	tbsysCountry			tc
		      	 				WHERE	tc.country_id	= @country_id	),'')		[country_desc],

		      		ISNULL((	SELECT	ts.state_desc
		      	 				FROM	tbsysState				ts
		      	 				WHERE	ts.country_id	= @country_id
		      	 				AND		ts.state_id		= @state_id		),'')		[state_desc],

					ISNULL((	SELECT	tsc.city_desc
								FROM	vwCities				tsc
								WHERE	tsc.country_id	= @country_id
								AND		tsc.state_id	= @state_id
								AND		tsc.city_id		= @city_id		),'')		[city_desc],

					ISNULL((	SELECT	tfc.fc_desc
				 				FROM	tbsysFiscalClass		tfc
				 				WHERE	tfc.fc_id		= @fc_id		),'')		[fc_desc],

					ISNULL((	SELECT	ttnt.tnt_desc
				 				FROM	tbsysTaxNumberTypes		ttnt
				 				WHERE	ttnt.tnt_id		= @tnt_id		),'')		[tnt_desc]


		END


	-- ----------------------
	-- ----------------------

	-- Si hay un cliente con ese tipo de documento pero no lo encontro, lo da de alta en la relacion al sitio web.
	IF @return_value = -2
		BEGIN
			SET @return_value = 0

			SELECT
					ISNULL((	SELECT	tc.country_desc
		      	 				FROM	tbsysCountry			tc
		      	 				WHERE	tc.country_id	= @country_id	),'')		[country_desc],

		      		ISNULL((	SELECT	ts.state_desc
		      	 				FROM	tbsysState				ts
		      	 				WHERE	ts.country_id	= @country_id
		      	 				AND		ts.state_id		= @state_id		),'')		[state_desc],

					ISNULL((	SELECT	tsc.city_desc
								FROM	vwCities				tsc
								WHERE	tsc.country_id	= @country_id
								AND		tsc.state_id	= @state_id
								AND		tsc.city_id		= @city_id		),'')		[city_desc],

					ISNULL((	SELECT	tfc.fc_desc
				 				FROM	tbsysFiscalClass		tfc
				 				WHERE	tfc.fc_id		= @fc_id		),'')		[fc_desc],

					ISNULL((	SELECT	ttnt.tnt_desc
				 				FROM	tbsysTaxNumberTypes		ttnt
				 				WHERE	ttnt.tnt_id		= @tnt_id		),'')		[tnt_desc]


		END

END
GO

CREATE PROCEDURE [dbo].[spCustomer_insertDataFromWebService4FullJaus]
(
	@comp_id				INT,
	@cust_id				INT,
	@wst_id					INT,
	@cust_name				NVARCHAR(200),
	@country_id				INT,
	@state_id				INT,
	@cust_address			NVARCHAR(150),
	@cust_City				NVARCHAR(200),
	@cust_zip				NVARCHAR(20),
	@fc_id					INT,
	@tnt_id					INT,
	@cust_taxNumber			NVARCHAR(50),
	@cust_email				NVARCHAR(300),
	@cust_Phone1			NVARCHAR(200),
	@cust_webNickName		NVARCHAR(50),
	@cust_webPassword		NVARCHAR(50),
	@cust_login				BIT,

	@return_value			INT	OUTPUT
)
AS

BEGIN
	SET NOCOUNT ON

	--------------------------------------------------------------------------------------------------------
	-- ATENCIÓN! SI SE TOCA ALGO ACÁ, TAMBIÉN TOCARLO EN spCustomer_insertDataFromWebSite
	--------------------------------------------------------------------------------------------------------

	-- ------------------------------------------------------------------
	-- Test
	-- ------------------------------------------------------------------
	/*
	DECLARE	@comp_id				INT,
			@cust_id				INT,
			@ws_id					UNIQUEIDENTIFIER,
			@cust_name				NVARCHAR(200),
			@country_id				INT,
			@state_id				INT,
			@cust_address			NVARCHAR(150),
			@cust_City				NVARCHAR(200),
			@cust_zip				NVARCHAR(20),
			@fc_id					INT,
			@tnt_id					INT,
			@cust_taxNumber			NVARCHAR(50),
			@cust_email				NVARCHAR(300),
			@cust_Phone1			NVARCHAR(200),
			@cust_webNickName		NVARCHAR(50),
			@cust_webPassword		NVARCHAR(50),
			@cust_login				BIT,

			@return_value			INT

	SELECT 	@comp_id				= 1,
			@cust_id				= 101498,
			@ws_id					= '02d9a54c-a6e9-47d4-9857-89f9eaea103f',
			@cust_name				= 'CUSTOMER TEST',
			@country_id				= 54,
			@state_id				= 54019,
			@cust_address			= 'CALLE FALSA 123',
			@cust_City				= 'Capital Federal',
			@cust_zip				= '1036',
			@fc_id					= 2,
			@tnt_id					= 5,
			@cust_taxNumber			= '32507274',
			@cust_email				= 'Mail@mail.com',
			@cust_Phone1			= '030345611',
			@cust_webNickName		= 'WebUserTest',
			@cust_webPassword		= 'PassWord',
			@cust_login				= 'True'
	*/
	-- ------------------------------------------------------------------


	SET @cust_webNickName = LOWER(dbo.fnStrAllTrim(@cust_webNickName))
	SET @cust_webPassword = LOWER(dbo.fnStrAllTrim(@cust_webPassword))


	DECLARE @cust_id_new	INT

	SET		@return_value = 0

	DECLARE @intCustIdYetExists AS INT = -1
	--controlamos que ya no exista un cliente con el mismo tipo y nro de documento
	SELECT @intCustIdYetExists = tc.cust_id
		FROM tbCustomer tc	WITH (NOLOCK)
		WHERE	tc.comp_id			= @comp_id
		AND		tc.tnt_id			= @tnt_id
		AND		tc.cust_taxNumber	= @cust_taxNumber
	IF	@return_value = 0			AND
		@intCustIdYetExists <> -1
		BEGIN
			SET @return_value = -2
		END


	IF @return_value = 0	-- SI NO lo encontro lod a de alta
		BEGIN

			DECLARE @city_id INT

			DECLARE @table_city AS TABLE (city_id INT)

			INSERT INTO @table_city(city_id)
				EXEC spCities_getIdByDesc @comp_id, -10,@country_id, @state_id, @cust_City

			SELECT TOP 1 @city_id = city_id
				FROM @table_city


			DECLARE @sm_id AS INT	= -1
			SELECT  @sm_id			= ISNULL(tws.sm_id4FullJaus,-1)
				FROM tbWebServices AS tws	WITH (NOLOCK)
				WHERE	tws.comp_id = @comp_id AND
						tws.wst_id	= @wst_id



			INSERT INTO tbCustomer	WITH (ROWLOCK)
			(
				comp_id,					bra_id,
				cust_name,
				cust_lastName,
				cust_name1,					fc_id,					cust_taxNumber,
				stcIB_Id,					cust_taxIBNumber,		cust_web,
				cust_inactive,				cust_partnerOf,			cust_contact,
				cust_address,				cust_city,				cust_zip,
				country_id,					state_id,				cust_phone1,
				cust_phone2,				cust_email,				cust_fax,
				cust_picture,				sm_id,					ck_id,
				st_id,						disc_id,				dl_id,
				cust_credit_max,			cust_credit_own,		curr_id,
				acc_count_id,				[user_id],				prli_id,
				stor_id,					tnt_id,					ss_id,
				cust_isEditing,				cust_isEditingCd,		cust_isEditingUserId,
				cust_annotation,			cust_judMan,			cust_note1,
				cust_note2,					cust_note3,				cust_note4,
				cust_address4Delivery,		cust_address4Payments,	cust_webNickName,
				cust_webPassword,			bra_id4Emmition,		city_id,
				cust_4InitialValues,		sm_id_2,				cust_showstock,
				cust_showpricelist,			cust_showzerostockitems,
				cust_login,
				cust_login_cd,
				cust_login_ip,			cust_login_name,
				cust_SaleOrderMaxValue,		cust_cd,				fecountry_id,
				fex_cuitID,					cust_contact4Payments,	cust_email4Payments,
				cust_contact4Management,	cust_email4Management,	cust_contact4Administration,
				cust_email4Administration,	cust_contact4Logistics,	cust_email4Logistics,
				act_id,		cust_SaleOrderDisableConcurrentProc,	cust_SaleOrderBranchTransfer,
				coslis_id,					coslis_idB,				cust_webPending2Verify,
				cust_excludeInCITI,
				stca_id, cust_Mailing4CustOverdueDebt_Excluded,
				cust_contact4Alternative, cust_email4Alternative, cust_contact4RMA,
				cust_email4RMA, cust_address4RMA, cust_isAvailable4InternalRMA,
				cust_phone4RMA, cust_contact4AlternativeII, cust_email4AlternativeII,
				rmap_id, street_id, cust_addressNumber, cust_addressAdditional,
				rating_id, marst_id, cust_isOwner, cust_ownerOf, cust_remuneration,
				cram_id, cust_ramification, cust_jobTitle, cust_jobAddress,
				cust_jobCity, cust_jobCity_Id, cust_jobPhone, cust_jobName,
				cust_jobPayDate, cust_jobAdmissionDate, corp_id, cust_addressFloor,
				stg_id, cust_imageChecksum, cust_ratingProcessCheck,
				rating_id_previous, rating_id_cd, cust_firstname,
				def_id, cmde_noAction, cust_updatedFromABM,
				cust_jobPayIntervalIs15, cust_disabled4PersonalLoan, cust_birthDay,
				cust_maleOrFemale,  cust_cellPhone,
				cust_excludeOfCustomerMailing, ws_internalID
			)
			SELECT	tc.comp_id, tc.bra_id,
					@cust_name,
					@cust_name,
					tc.cust_name1,
					@fc_id,
					@cust_taxNumber,
					tc.stcIB_Id, tc.cust_taxIBNumber, tc.cust_web,
					tc.cust_inactive, tc.cust_partnerOf, tc.cust_contact,
					@cust_address,
					convert(nvarchar(60),@cust_City),
					@cust_zip,
					@country_id,
					@state_id,
					@cust_Phone1,
					tc.cust_phone2,
					@cust_email,
					tc.cust_fax, tc.cust_picture,
					CASE
						WHEN @sm_id > 0 THEN	@sm_id
						ELSE					tc.sm_id
					END,
					tc.ck_id, tc.st_id, tc.disc_id, tc.dl_id, tc.cust_credit_max,
					tc.cust_credit_own, tc.curr_id, tc.acc_count_id,
					tc.[user_id], tc.prli_id, tc.stor_id,
					@tnt_id,
					tc.ss_id,tc.cust_isEditing,	tc.cust_isEditingCd,
					tc.cust_isEditingUserId, tc.cust_annotation, tc.cust_judMan, tc.cust_note1,
					tc.cust_note2, tc.cust_note3, tc.cust_note4,
					tc.cust_address4Delivery, tc.cust_address4Payments,
					@cust_webNickName,
					/*@cust_webPassword*/'',
					tc.bra_id4Emmition,
					@city_id,
					tc.cust_4InitialValues, tc.sm_id_2,
					tc.cust_showstock, tc.cust_showpricelist, tc.cust_showzerostockitems,
					~@cust_login,
					GETDATE(),
					tc.cust_login_ip, tc.cust_login_name,
					tc.cust_SaleOrderMaxValue, tc.cust_cd, tc.fecountry_id, tc.fex_cuitID,
					tc.cust_contact4Payments, tc.cust_email4Payments,
					tc.cust_contact4Management, tc.cust_email4Management,
					tc.cust_contact4Administration, tc.cust_email4Administration,
					tc.cust_contact4Logistics, tc.cust_email4Logistics, tc.act_id,
					tc.cust_SaleOrderDisableConcurrentProc, tc.cust_SaleOrderBranchTransfer,
					tc.coslis_id, tc.coslis_idB, tc.cust_webPending2Verify,
					tc.cust_excludeInCITI,
					tc.stca_id, tc.cust_Mailing4CustOverdueDebt_Excluded,
					tc.cust_contact4Alternative, tc.cust_email4Alternative, tc.cust_contact4RMA,
					tc.cust_email4RMA, tc.cust_address4RMA, tc.cust_isAvailable4InternalRMA,
					tc.cust_phone4RMA, tc.cust_contact4AlternativeII, tc.cust_email4AlternativeII,
					tc.rmap_id, tc.street_id, tc.cust_addressNumber, tc.cust_addressAdditional,
					tc.rating_id, tc.marst_id, tc.cust_isOwner, tc.cust_ownerOf, tc.cust_remuneration,
					tc.cram_id, tc.cust_ramification, tc.cust_jobTitle, tc.cust_jobAddress,
					tc.cust_jobCity, tc.cust_jobCity_Id, tc.cust_jobPhone, tc.cust_jobName,
					tc.cust_jobPayDate, tc.cust_jobAdmissionDate, tc.corp_id,tc. cust_addressFloor,
					tc.stg_id, tc.cust_imageChecksum, tc.cust_ratingProcessCheck,
					tc.rating_id_previous, tc.rating_id_cd, tc.cust_firstname,
					tc.def_id, tc.cmde_noAction, tc.cust_updatedFromABM,
					tc.cust_jobPayIntervalIs15, tc.cust_disabled4PersonalLoan, tc.cust_birthDay,
					tc.cust_maleOrFemale,  tc.cust_cellPhone,
					tc.cust_excludeOfCustomerMailing,
					NULL
			FROM	tbCustomer tc		WITH (NOLOCK)
			WHERE	tc.comp_id = @comp_id
			AND		tc.cust_id = @cust_id

			SET @return_value = @@IDENTITY

			SELECT
					ISNULL((	SELECT	tc.country_desc
		      	 				FROM	tbsysCountry			tc
		      	 				WHERE	tc.country_id	= @country_id	),'')		[country_desc],

		      		ISNULL((	SELECT	ts.state_desc
		      	 				FROM	tbsysState				ts
		      	 				WHERE	ts.country_id	= @country_id
		      	 				AND		ts.state_id		= @state_id		),'')		[state_desc],

					ISNULL((	SELECT	tsc.city_desc
								FROM	vwCities				tsc
								WHERE	tsc.country_id	= @country_id
								AND		tsc.state_id	= @state_id
								AND		tsc.city_id		= @city_id		),'')		[city_desc],

					ISNULL((	SELECT	tfc.fc_desc
				 				FROM	tbsysFiscalClass		tfc
				 				WHERE	tfc.fc_id		= @fc_id		),'')		[fc_desc],

					ISNULL((	SELECT	ttnt.tnt_desc
				 				FROM	tbsysTaxNumberTypes		ttnt
				 				WHERE	ttnt.tnt_id		= @tnt_id		),'')		[tnt_desc]


		END


	-- ----------------------
	-- ----------------------

	-- Si hay un cliente con ese tipo de documento pero no lo encontro, lo da de alta en la relacion al sitio web.
	IF @return_value = -2
		BEGIN
			SET @return_value = 0

			SELECT
					ISNULL((	SELECT	tc.country_desc
		      	 				FROM	tbsysCountry			tc
		      	 				WHERE	tc.country_id	= @country_id	),'')		[country_desc],

		      		ISNULL((	SELECT	ts.state_desc
		      	 				FROM	tbsysState				ts
		      	 				WHERE	ts.country_id	= @country_id
		      	 				AND		ts.state_id		= @state_id		),'')		[state_desc],

					ISNULL((	SELECT	tsc.city_desc
								FROM	vwCities				tsc
								WHERE	tsc.country_id	= @country_id
								AND		tsc.state_id	= @state_id
								AND		tsc.city_id		= @city_id		),'')		[city_desc],

					ISNULL((	SELECT	tfc.fc_desc
				 				FROM	tbsysFiscalClass		tfc
				 				WHERE	tfc.fc_id		= @fc_id		),'')		[fc_desc],

					ISNULL((	SELECT	ttnt.tnt_desc
				 				FROM	tbsysTaxNumberTypes		ttnt
				 				WHERE	ttnt.tnt_id		= @tnt_id		),'')		[tnt_desc]


		END

END
GO



--Si  wsNRW_SetNewCustomer está:


--- Relacionado a tbWebSiteII_Users Sale con -1
--- Si encuentra por Tipo de Documento retorna -2
--- Si el CLIENTE EXISTE y NO esta relacionado al sitio web pero lo encontró x nro de dcto, lo da de alta en la relacion.




CREATE PROCEDURE [dbo].[spCustomer_insertDataFromWebSite]
(
	@comp_id				INT,
	@cust_id				INT,
	@ws_id					UNIQUEIDENTIFIER,
	@cust_name				NVARCHAR(200),
	@country_id				INT,
	@state_id				INT,
	@cust_address			NVARCHAR(150),
	@cust_City				NVARCHAR(200),
	@cust_zip				NVARCHAR(20),
	@fc_id					INT,
	@tnt_id					INT,
	@cust_taxNumber			NVARCHAR(50),
	@cust_email				NVARCHAR(300),
	@cust_Phone1			NVARCHAR(200),
	@cust_webNickName		NVARCHAR(50),
	@cust_webPassword		NVARCHAR(50),
	@cust_login				BIT,

	@return_value			INT	OUTPUT
)
AS

BEGIN

	--------------------------------------------------------------------------------------------------------
	-- ATENCIÓN! SI SE TOCA ALGO ACÁ, TAMBIÉN TOCARLO EN spCustomer_insertDataFromWebService
	--------------------------------------------------------------------------------------------------------


	SET NOCOUNT ON

	-- ------------------------------------------------------------------
	-- Test
	-- ------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@cust_id			INT,

			@name				NVARCHAR(200),
			@country			INT,
			@state				INT,
			@address			NVARCHAR(150),
			@city				NVARCHAR(200),
			@fiscalclass		INT,
			@taxnumbertype		INT,
			@taxnumber			NVARCHAR(50),
			@email				NVARCHAR(300),
			@phone				NVARCHAR(200),
			@nickname			NVARCHAR(50),
			@pass1				NVARCHAR(50),

			@returnvalue		INT

	SELECT 	@comp_id			=1,
			@cust_id			=24300,

			@name				='PRUEBA WEB',
			@country			=54,
			@state				=54019,
			@address			='DOMICILIO PRUEBA WEB',
			@city				='Capital Federal',
			@fiscalclass		=1,
			@taxnumbertype		=1,
			@taxnumber			='30-65856224-6',
			@email				='prueba@prueba.com',
			@phone				='3220-7172',
			@nickname			='nuevo',
			@pass1				='nuveo'

	*/
	-- ------------------------------------------------------------------


	SET @cust_webNickName = LOWER(dbo.fnStrAllTrim(@cust_webNickName))
	SET @cust_webPassword = LOWER(dbo.fnStrAllTrim(@cust_webPassword))
	SET	@return_value	  = 0


	DECLARE @ws_newCustomer_allowIfExistsByCUITDocument		AS BIT = 'False'
	DECLARE @ws_newCustomer_allowIfExistsByOTHERDocument	AS BIT = 'False'

	-- Busca el Sitio WEB del ALta
	DECLARE @ws_internalID AS INT
	SELECT  @ws_internalID = twsin.ws_internalID,
			@ws_newCustomer_allowIfExistsByCUITDocument		= ws_newCustomer_allowIfExistsByCUITDocument,
			@ws_newCustomer_allowIfExistsByOTHERDocument	= ws_newCustomer_allowIfExistsByOTHERDocument
		FROM tbWebSiteII_Names twsin		WITH (NOLOCK)
		WHERE	twsin.comp_id	= @comp_id AND
				twsin.ws_id		= @ws_id



	-- -----------------------------------------------------------------------
	-- Si esta relacionado a este sitio web ya sabe que NO lo debe dar de alta
	-- -----------------------------------------------------------------------
	DECLARE @intCustID					AS INT = -1
	DECLARE @strWebSiteActualPassword	AS NVARCHAR(50) = ''
	SELECT  @intCustID					= twsiu.cust_id ,
			@strWebSiteActualPassword	= twsiu.wsu_webPassword
		FROM	tbWebSiteII_Users twsiu	WITH (NOLOCK)
		WHERE	twsiu.comp_id			= @comp_id	AND
				twsiu.ws_id				= @ws_id	AND
				twsiu.wsu_webNickName	= @cust_webNickName

	IF @intCustID > 0
		BEGIN
			SET @return_value = -1
		END
	-- -----------------------------------------------------------------------



	-- -----------------------------------------------------------------------
	--controlamos que ya no exista un cliente con el mismo tipo y nro de documento
	-- -----------------------------------------------------------------------
	SET		@cust_taxNumber = REPLACE(@cust_taxNumber,'-','')
	DECLARE @intCustIdYetExists AS INT = -1

	SELECT	@intCustIdYetExists		= tc.cust_id,
			@intCustID				= tc.cust_id
		FROM tbCustomer tc	WITH (NOLOCK)
		WHERE	tc.comp_id			= @comp_id
		AND		tc.tnt_id			= @tnt_id
		AND		REPLACE(tc.cust_taxNumber,'-','')	= @cust_taxNumber

	IF	@return_value = 0			AND  -- Dejarlo asi y no incluir este bloque en el = 0
		@intCustIdYetExists <> -1
		BEGIN
			SET @return_value = -2
		END
	-- -----------------------------------------------------------------------




	IF @return_value = 0	-- SI NO lo encontro lo da de alta
		BEGIN


			DECLARE @city_id INT

			DECLARE @table_city AS TABLE (city_id INT)

			INSERT INTO @table_city(city_id)
				EXEC spCities_getIdByDesc @comp_id, -10,@country_id, @state_id, @cust_City

			SELECT TOP 1 @city_id = city_id
				FROM @table_city



			IF @tnt_id = 1	-- C.U.I.T.
				BEGIN
					BEGIN TRY
						EXEC spGeneric_validateTaxNumber	@country_id,
															@tnt_id,
															@cust_taxNumber OUTPUT,
															0
					END TRY
					BEGIN CATCH
					END CATCH
				END


			INSERT INTO tbCustomer	WITH (ROWLOCK)
			(
				comp_id,					bra_id,
				cust_name,
				cust_lastName,
				cust_name1,					fc_id,					cust_taxNumber,
				stcIB_Id,					cust_taxIBNumber,		cust_web,
				cust_inactive,				cust_partnerOf,			cust_contact,
				cust_address,				cust_city,				cust_zip,
				country_id,					state_id,				cust_phone1,
				cust_phone2,				cust_email,				cust_fax,
				cust_picture,				sm_id,					ck_id,
				st_id,						disc_id,				dl_id,
				cust_credit_max,			cust_credit_own,		curr_id,
				acc_count_id,				[user_id],				prli_id,
				stor_id,					tnt_id,					ss_id,
				cust_isEditing,				cust_isEditingCd,		cust_isEditingUserId,
				cust_annotation,			cust_judMan,			cust_note1,
				cust_note2,					cust_note3,				cust_note4,
				cust_address4Delivery,		cust_address4Payments,	cust_webNickName,
				cust_webPassword,			bra_id4Emmition,		city_id,
				cust_4InitialValues,		sm_id_2,				cust_showstock,
				cust_showpricelist,			cust_showzerostockitems,
				cust_login,
				cust_login_cd,
				cust_login_ip,			cust_login_name,
				cust_SaleOrderMaxValue,		cust_cd,				fecountry_id,
				fex_cuitID,					cust_contact4Payments,	cust_email4Payments,
				cust_contact4Management,	cust_email4Management,	cust_contact4Administration,
				cust_email4Administration,	cust_contact4Logistics,	cust_email4Logistics,
				act_id,		cust_SaleOrderDisableConcurrentProc,	cust_SaleOrderBranchTransfer,
				coslis_id,					coslis_idB,				cust_webPending2Verify,
				cust_excludeInCITI,
				stca_id, cust_Mailing4CustOverdueDebt_Excluded,
				cust_contact4Alternative, cust_email4Alternative, cust_contact4RMA,
				cust_email4RMA, cust_address4RMA, cust_isAvailable4InternalRMA,
				cust_phone4RMA, cust_contact4AlternativeII, cust_email4AlternativeII,
				rmap_id, street_id, cust_addressNumber, cust_addressAdditional,
				rating_id, marst_id, cust_isOwner, cust_ownerOf, cust_remuneration,
				cram_id, cust_ramification, cust_jobTitle, cust_jobAddress,
				cust_jobCity, cust_jobCity_Id, cust_jobPhone, cust_jobName,
				cust_jobPayDate, cust_jobAdmissionDate, corp_id, cust_addressFloor,
				stg_id, cust_imageChecksum, cust_ratingProcessCheck,
				rating_id_previous, rating_id_cd, cust_firstname,
				def_id, cmde_noAction, cust_updatedFromABM,
				cust_jobPayIntervalIs15, cust_disabled4PersonalLoan, cust_birthDay,
				cust_maleOrFemale,  cust_cellPhone,
				cust_excludeOfCustomerMailing, ws_internalID
			)
			SELECT	tc.comp_id, tc.bra_id,
					@cust_name,
					@cust_name,
					tc.cust_name1,
					@fc_id,
					@cust_taxNumber,
					tc.stcIB_Id, tc.cust_taxIBNumber, tc.cust_web,
					tc.cust_inactive, tc.cust_partnerOf, tc.cust_contact,
					@cust_address,
					convert(nvarchar(60),@cust_City),
					@cust_zip,
					CASE
						WHEN @country_id > 0 THEN @country_id
						ELSE					  tc.country_id
					END,
					CASE
						WHEN @state_id > 0 THEN @state_id
						ELSE					tc.state_id
					END,
					@cust_Phone1,
					tc.cust_phone2,
					@cust_email,
					tc.cust_fax, tc.cust_picture, tc.sm_id,
					tc.ck_id, tc.st_id, tc.disc_id, tc.dl_id, tc.cust_credit_max,
					tc.cust_credit_own, tc.curr_id, tc.acc_count_id,
					tc.[user_id], tc.prli_id, tc.stor_id,
					@tnt_id,
					tc.ss_id,tc.cust_isEditing,	tc.cust_isEditingCd,
					tc.cust_isEditingUserId, tc.cust_annotation, tc.cust_judMan, tc.cust_note1,
					tc.cust_note2, tc.cust_note3, tc.cust_note4,
					tc.cust_address4Delivery, tc.cust_address4Payments,
					@cust_webNickName,
					/*@cust_webPassword*/'',
					tc.bra_id4Emmition,
					@city_id,
					tc.cust_4InitialValues, tc.sm_id_2,
					tc.cust_showstock, tc.cust_showpricelist, tc.cust_showzerostockitems,
					~@cust_login,
					GETDATE(),
					tc.cust_login_ip, tc.cust_login_name,
					tc.cust_SaleOrderMaxValue, tc.cust_cd, tc.fecountry_id, tc.fex_cuitID,
					tc.cust_contact4Payments, tc.cust_email4Payments,
					tc.cust_contact4Management, tc.cust_email4Management,
					tc.cust_contact4Administration, tc.cust_email4Administration,
					tc.cust_contact4Logistics, tc.cust_email4Logistics, tc.act_id,
					tc.cust_SaleOrderDisableConcurrentProc, tc.cust_SaleOrderBranchTransfer,
					tc.coslis_id, tc.coslis_idB, tc.cust_webPending2Verify,
					tc.cust_excludeInCITI,
					tc.stca_id, tc.cust_Mailing4CustOverdueDebt_Excluded,
					tc.cust_contact4Alternative, tc.cust_email4Alternative, tc.cust_contact4RMA,
					tc.cust_email4RMA, tc.cust_address4RMA, tc.cust_isAvailable4InternalRMA,
					tc.cust_phone4RMA, tc.cust_contact4AlternativeII, tc.cust_email4AlternativeII,
					tc.rmap_id, tc.street_id, tc.cust_addressNumber, tc.cust_addressAdditional,
					tc.rating_id, tc.marst_id, tc.cust_isOwner, tc.cust_ownerOf, tc.cust_remuneration,
					tc.cram_id, tc.cust_ramification, tc.cust_jobTitle, tc.cust_jobAddress,
					tc.cust_jobCity, tc.cust_jobCity_Id, tc.cust_jobPhone, tc.cust_jobName,
					tc.cust_jobPayDate, tc.cust_jobAdmissionDate, tc.corp_id,tc. cust_addressFloor,
					tc.stg_id, tc.cust_imageChecksum, tc.cust_ratingProcessCheck,
					tc.rating_id_previous, tc.rating_id_cd, tc.cust_firstname,
					tc.def_id, tc.cmde_noAction, tc.cust_updatedFromABM,
					tc.cust_jobPayIntervalIs15, tc.cust_disabled4PersonalLoan, tc.cust_birthDay,
					tc.cust_maleOrFemale,  tc.cust_cellPhone,
					tc.cust_excludeOfCustomerMailing,
					@ws_internalID
			FROM	tbCustomer tc		WITH (NOLOCK)
			WHERE	tc.comp_id = @comp_id
			AND		tc.cust_id = @cust_id

			SET @return_value = @@IDENTITY



			-- Lo doy de alta como usuario de ESTE sitio web
			INSERT INTO tbWebSiteII_Users
			(
				comp_id,
				ws_id,
				cust_id,
				wsu_webNickName,
				wsu_webPassword,
				wsu_block2Login,
				wsu_cd,
				wsu_lastLogin
			)
			VALUES
			(
				@comp_id,
				@ws_id,
				@return_value,
				@cust_webNickName,
				@cust_webPassword,
				'False',
				GETDATE(),
				GETDATE()
			)




			SELECT
					ISNULL((	SELECT	tc.country_desc
		      	 				FROM	tbsysCountry			tc
		      	 				WHERE	tc.country_id	= @country_id	),'')		[country_desc],

		      		ISNULL((	SELECT	ts.state_desc
		      	 				FROM	tbsysState				ts
		      	 				WHERE	ts.country_id	= @country_id
		      	 				AND		ts.state_id		= @state_id		),'')		[state_desc],

					ISNULL((	SELECT	tsc.city_desc
								FROM	vwCities				tsc
								WHERE	tsc.country_id	= @country_id
								AND		tsc.state_id	= @state_id
								AND		tsc.city_id		= @city_id		),'')		[city_desc],

					ISNULL((	SELECT	tfc.fc_desc
				 				FROM	tbsysFiscalClass		tfc
				 				WHERE	tfc.fc_id		= @fc_id		),'')		[fc_desc],

					ISNULL((	SELECT	ttnt.tnt_desc
				 				FROM	tbsysTaxNumberTypes		ttnt
				 				WHERE	ttnt.tnt_id		= @tnt_id		),'')		[tnt_desc]


		END


	-- -----------------------------------------------------------------------------------------------------------
	-- SI NO ESTA EN EL SITIO WEB PERO SI ESTA COMO CLIENTE. . .
	-- Si hay un cliente con ese tipo de documento pero no lo encontro, lo da de alta en la relacion al sitio web.
	-- -----------------------------------------------------------------------------------------------------------
	IF	@return_value								= -2 AND
		CASE	-- MOS 08-2020 x seguridad deben permitirlo.
			WHEN @tnt_id     IN (1,2,21,31,41,51,61)  AND @ws_newCustomer_allowIfExistsByCUITDocument	= 'True'	THEN 1
			WHEN @tnt_id NOT IN (1,2,21,31,41,51,61)  AND @ws_newCustomer_allowIfExistsByOTHERDocument	= 'True'	THEN 1
			ELSE 0
		END = 1
		BEGIN
			--CUSTOM_GN_001
			SET @return_value = 0

			-- Lo doy de alta como usuario de ESTE sitio web
			INSERT INTO tbWebSiteII_Users
			(
				comp_id,
				ws_id,
				cust_id,
				wsu_webNickName,
				wsu_webPassword,
				wsu_block2Login,
				wsu_cd,
				wsu_lastLogin
			)
			VALUES
			(
				@comp_id,
				@ws_id,
				@intCustIdYetExists,
				@cust_webNickName,
				@cust_webPassword,
				'False',
				GETDATE(),
				GETDATE()
			)


			SELECT
					ISNULL((	SELECT	tc.country_desc
		      	 				FROM	tbsysCountry			tc			WITH (NOLOCK)
		      	 				WHERE	tc.country_id	= @country_id	),'')		[country_desc],

		      		ISNULL((	SELECT	ts.state_desc
		      	 				FROM	tbsysState				ts			WITH (NOLOCK)
		      	 				WHERE	ts.country_id	= @country_id
		      	 				AND		ts.state_id		= @state_id		),'')		[state_desc],

					ISNULL((	SELECT	tsc.city_desc
								FROM	vwCities				tsc			WITH (NOLOCK)
								WHERE	tsc.country_id	= @country_id
								AND		tsc.state_id	= @state_id
								AND		tsc.city_id		= @city_id		),'')		[city_desc],

					ISNULL((	SELECT	tfc.fc_desc
				 				FROM	tbsysFiscalClass		tfc			WITH (NOLOCK)
				 				WHERE	tfc.fc_id		= @fc_id		),'')		[fc_desc],

					ISNULL((	SELECT	ttnt.tnt_desc
				 				FROM	tbsysTaxNumberTypes		ttnt		WITH (NOLOCK)
				 				WHERE	ttnt.tnt_id		= @tnt_id		),'')		[tnt_desc]

		--CUSTOM_GN_002
		END
	-- -----------------------------------------------------------------------------------------------------------

	-- -----------------------------------------------------------------------------------------------------------
	-- MOS 06-2020: Actualiza los datos del cliente si es que NO estaban cargados.
	-- -----------------------------------------------------------------------------------------------------------
	IF @intCustID > 0
		BEGIN
			UPDATE tbcustomer	WITH (ROWLOCK)
				SET cust_email	=	CASE
										WHEN ISNULL(cust_email,'') = ''			THEN @cust_email
										WHEN cust_email LIKE '%mercadolibre%'	THEN @cust_email
										ELSE cust_email
									END,
					cust_phone1 =	CASE
										WHEN ISNULL(cust_phone1,'') = ''		THEN @cust_Phone1
										ELSE cust_phone1
					             	END
				WHERE	comp_id = @comp_id		AND
						cust_id = @intCustID
		END
	-- -----------------------------------------------------------------------------------------------------------



END
GO






-- --------------------------------------------------------------
-- MOS  10-2008
-- Borra los temporales que no se estan usando y no se han
-- actualizado, pasados 3 minutos.-
-- --------------------------------------------------------------

CREATE pROCEDURE [dbo].[spCustomer_IsEditingPurgeStatus]
AS

BEGIN


	set nocount on


	declare @DeleteTime		as	datetime
	set		@DeleteTime		=	DATEADD(minute, -3, getdate())




		-- cabeceras sin actualizar
		Update dbo.tbCustomer	WITH(ROWLOCK)
			Set cust_isEditing			= 'False'
			from tbcustomer tc	WITH (INDEX(IX_tbCustomer_cust_isEditingCd))
				Where   tc.cust_isEditing	= 'True'
					and	tc.cust_isEditingCd < @DeleteTime



		-- MOS 11-2021: MIerda del FORRO que JAMAS se usó !
		---- /////////////////////////////////////////////////////////////////////////////////////
		---- 08-11-2010 - MOH --
		---- Se actualiza el cust_login que es la marca que está logueado al sitio web
		--Update dbo.tbCustomer	WITH(ROWLOCK)
		--	Set cust_login				= 'False'
		--		Where   cust_login		= 'True'
		--			and	cust_login_cd	< @DeleteTime
		---- /////////////////////////////////////////////////////////////////////////////////////


END
GO





-- =============================================
-- Author:		MOS  06-2012
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[spCustomer_IsValidDocument4CustomerTax]
	@comp_id	AS INT,
	@cust_id	AS INT,
	@df_id		AS INT
AS




BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- --------------------------------------------
	-- Testing
	-- --------------------------------------------
	/*
		DECLARE
		@comp_id	AS INT,
		@cust_id	AS INT,
		@df_id		AS INT

		set @comp_id	= 1
		set @cust_id	= 24510
		set @df_id		= 84
	*/
	-- --------------------------------------------

	SET NOCOUNT ON;

	DECLARE @intReturnValue AS int
	DECLARE @strKindOf	AS NVARCHAR(100)
	DECLARE @sd_id		AS INT
	DECLARE @boldf_isInterBranchDocument	AS BIT
	DECLARE @bolCheckCUITInAFIPPadron		AS BIT
	DECLARE @country_id						AS INT	= 54
	SET		@bolCheckCUITInAFIPPadron		= 'False'



	SELECT  @strKindOf						= IsNull(tdf.df_Kindof ,' '),
			@boldf_isInterBranchDocument	= IsNull(tdf.df_isInterBranchDocument,'False'),
			@sd_id							= tdf.sd_id,
			@bolCheckCUITInAFIPPadron		= ISNULL(tdf.df_saleOrder_CheckCUITInAFIPPadron,'False'),
			@country_id						= tb.country_id
		FROM tbDocumentsFile tdf		WITH (NOLOCK)
		INNER JOIN tbBranch AS tb		WITH (NOLOCK)
			ON	tb.comp_id	= tdf.comp_id AND
				tb.bra_id	= tdf.bra_id
		WHERE	tdf.comp_id = @comp_id
			AND tdf.df_id	= @df_id


	-- Como estas FORRADAS son solo para Argentina, que NO las haga en otros paises.   MOS 10-2021
	IF @country_id <> 54
		BEGIN
			SET		@intReturnValue = 1
			select	@intReturnValue
			RETURN
		END


	-- No MOlesta si es Transf entre sucursales, presupuesto o saldos iniciales.
	IF @boldf_isInterBranchDocument = 'True' OR @sd_id IN (5,21,23)
		BEGIN
			SET		@intReturnValue = 1
			select	@intReturnValue
			RETURN
		END



	IF (dbo.fnStrAllTrim( dbo.fnGetFiscalCustomer_KindOf(@cust_id)) LIKE '%' + @strKindOf  + '%'
			OR @strKindOf = 'R'
			OR @strKindOf = 'X'
			OR @strKindOf = ''
			OR @strKindOf = ' '
			OR @strKindOf IS NULL
			OR @strKindOf = 'E'
			)

		BEGIN
			SET @intReturnValue = 1
		END
	ELSE
		BEGIN
			SET @intReturnValue = -1
		END


	-- -------------------------------------------------------------------------------------------------------------------------------------
	-- Verificar aqui si es que en Sucursal no esta deshabilitado que la condicion del cliente corresponda a la que dice el padron de AFIP.-
	-- Por defecto se VERIFICA SIEMPRE que tenga algo cargado la tabla tbsysTaxAFIP
	-- Si no corresponde se debe pasar @intReturnValue = -1
	-- -------------------------------------------------------------------------------------------------------------------------------------
	DECLARE @intFiscalClassFromCustomer AS int
	DECLARE @intFiscalClassFromAFIP     AS INT
	DECLARE @strTaxNumber				AS CHAR(11)
	DECLARE @intTNTId					AS INT
	SET		@intTNTId	= -1
	SELECT	@intFiscalClassFromCustomer = tc.fc_id,
			@strTaxNumber				= REPLACE(tc.cust_taxNumber,'-',''),
			@intTNTId					= ISNULL(tc.tnt_id,-1)
		FROM tbCustomer tc		WITH (NOLOCK)
		WHERE	tc.comp_id = @comp_id
			AND tc.cust_id = @cust_id
			AND tc.country_id = 54

	SELECT @intFiscalClassFromAFIP  = tta.afip_fiscalClass
		FROM tbsysTaxAFIP tta	WITH (NOLOCK)
		WHERE tta.afip_cuit = @strTaxNumber


	IF	@strTaxNumber IS not	NULL		AND
		@intFiscalClassFromAFIP IS NOT NULL AND
		@intFiscalClassFromAFIP <> @intFiscalClassFromCustomer AND
		@intTNTId <> 61		-- MOS 11-2021 x ticket 14211 GN
		BEGIN
			SET @intReturnValue = -2
		END


	-- Verifica si es q en el doc lo dice q este si o si en el padron salvo q use CUIT VI
	IF	@bolCheckCUITInAFIPPadron = 'True'	AND
		@intFiscalClassFromAFIP IS NULL		AND
		@intTNTId <> 61
		BEGIN
			SET @intReturnValue = -3
		END


	-- -------------------------------------------------------------------------------------------------------------------------------------


	select @intReturnValue

END
GO






/******************************************************************************************************************
Programador: Martin Bloise;
Report:		 Customers Reduced;
******************************************************************************************************************/


CREATE PROCEDURE [dbo].[spCustomer_Reduced_getReport]
(
		@comp_id		int,
		@lang_id		int,
		@page_id		int,

		@option			int,
		@cust_name		varchar(200),
		@ck_id			int,
		@disc_id		int,
		@st_id			int,
		@dl_id			int,
		@sm_id			INT,
		@bra_id			int,
		@intBranch4Lang int
)

AS
SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



/*
DECLARE			@comp_id		int,
				@lang_id		int,
				@page_id		int,

				@option			int,
				@cust_name		varchar(200),
				@ck_id			int,
				@disc_id		int,
				@st_id			int,
				@dl_id			int,
				@sm_id			INT,
				@bra_id			INT


SELECT			@comp_id		= 1,
				@lang_id		= 2,
				@page_id		= 10079,


				@ck_id			= -1,
				@disc_id		= -1,
				@st_id			= -1,
				@dl_id			= -1,
				@sm_id			= -1,
				@option			= -1,
				@cust_name		= 'prueba clase A'

*/



DECLARE @fun_id INT
SET @fun_id = 1



SELECT

			C.cust_name,
			C.cust_address,
			C.cust_city,
			C.cust_phone1,
			SM.sm_name,
			CK.ck_name,
			ST.st_desc,
			DC.disc_desc,
			DLV.dl_name



FROM	tbCustomer							C


		left join tbCustomerKind			CK
		ON C.[ck_id]	= CK.[ck_id]

		left join	[tbDiscount]			DC
		ON C.[disc_id] = DC.[disc_id]

		left join [tbSalesTerms]			ST
		ON C.[st_id] = ST.[st_id]

		left join [tbBranch]				BR
		ON C.[bra_id] = BR.[bra_id]

		left join [tbDelivery]				DLV
		ON C.[dl_id] = DLV.[dl_id]

		left join [tbSalesman]				SM
		ON C.[sm_id]	= SM.[sm_id]


		left join [tbUser]					US
		ON	C.[user_id]			= US.[user_id]

		left join [tbAccountant]			AC
		ON	C.[acc_count_id]	= AC.[acc_count_id]

		left join [tbsysOptionsValues]		o
		on	o.[optval_id]		= C.[cust_inactive]
		and	o.[optval_class]	= 1
		and	o.[lang_id]			= @lang_id


WHERE	C.[comp_id]		= @comp_id

and	    (@ck_id			= -1		or		C.[ck_id]		= @ck_id)
and		(@disc_id		= -1		or		C.[disc_id]		= @disc_id)
and		(@st_id			= -1		or		C.[st_id]		= @st_id)
--and		(@bra_id		= -1		or		C.[bra_id]		= @bra_id)
and		(@dl_id			= -1		or		C.[dl_id]		= @dl_id)
and		(@sm_id			= -1		or		C.[sm_id]		= @sm_id)
and		(
		(@option = -1 ) or
		(@option = 0 and C.cust_name like @cust_name + '%') or
		(@option = 1 and C.cust_name like '%' + @cust_name + '%') or
		(@option = 2 and C.cust_name = @cust_name) or
		(@option = 3 and C.cust_name <> @cust_name) or
		(@option = 4 and C.cust_name not like '%' + @cust_name + '%')
		)



order by c.cust_name


exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


/* devolución de parámetros recibidos */

DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/


SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 43
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

		CASE @option WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(select tov.optval_desc
				from  dbo.tbsysOptionsValues tov
				where tov.optval_class =  2
				and   tov.lang_id      = @lang_id
				And   tov.optval_id    = @option)
		End [params2],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 372
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

		CASE @ck_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
			(SELECT		tck.ck_name
					FROM	tbCustomerKind tck
					WHERE	Tck.comp_id = @comp_id AND Tck.ck_id = @ck_id)
		END		[params4],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 175
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

		CASE @st_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(SELECT		tst.st_desc
					FROM	tbSalesTerms tst
					 Where    tst.comp_id =@comp_id
					And    	tst.st_id = @st_id)
		END		[params6],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 173
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

		CASE @disc_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		td.disc_desc
					FROM	tbDiscount td
					WHERE	td.disc_id = @disc_id)
		END		[params8],


(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 170
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

		CASE @dl_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(SELECT		td.dl_name
					FROM	tbDelivery td
					WHERE	td.comp_id = @comp_id AND td.dl_id = @dl_id)
		END		[params10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 172
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],

		CASE @sm_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
						(SELECT		ts.sm_name
					FROM	tbSalesman ts
					WHERE	ts.comp_id = @comp_id AND Ts.sm_id = @sm_id)
		END		[params12],

		(Select @cust_name) [params13]
GO







-- ------------------------------------------
-- Calificación de Crédito
-- 02-2015
-- ------------------------------------------

CREATE PROCEDURE  [dbo].[spCustomer_SetCreditRating]
(
	@comp_id			INT,
	@bra_id				INT,
	@DateUpdate			DATETIME,
	@user_id			INT,
	@prof_id			INT,
	@bitIsAutoClose		BIT
	--@return_value		INT OUTPUT
)
AS

BEGIN


	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	--BEGIN TRANSACTION


	BEGIN TRY



		DECLARE @tmpRatings			AS TABLE(rating_id INT PRIMARY KEY)
		DECLARE @intBranchGroup		AS INT
		DECLARE @datProcessingDate	AS DATETIME
		SET @intBranchGroup = NULL
		SELECT	@intBranchGroup		= tb.brag_id4CreditRating,
				@datProcessingDate	= tb.bra_processingDate
			FROM tbBranch tb
			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id


		IF @intBranchGroup IS NULL
			BEGIN
				RETURN
			END

		-- Pone las sucursales del grupo de sucursales.-
		DECLARE @tmpBranchs AS TABLE(bra_id INT PRIMARY KEY)
		INSERT INTO @tmpBranchs(bra_id)
			SELECT tbg.bra_id
			FROM tbBranchGroupDetail tbg
				WHERE	tbg.comp_id = @comp_id AND
						tbg.brag_id = @intBranchGroup


		-- Pone a todos en CERO asi al final puede saber a quienes NO se marco como Procesados
		UPDATE tbcustomer
			SET cust_ratingProcessCheck = 0,
				rating_id_previous		=  rating_id

		-- ----------------------------------------------
		-- PASO 1
		-- Verifica primero a los que no tengan fecha
		-- de alta o la fecha de alta sea menor a la
		-- indicada en el rating_id
		-- rating_isAvailable4Initial = TRUE
		-- ----------------------------------------------
		DECLARE @intRatingID4Initial AS INT
		SET		@intRatingID4Initial = NULL
		DECLARE @intDaysFrom		AS INT
		DECLARE @intDaysTO			AS INT

		SELECT  TOP 1
					@intRatingID4Initial	= tccr.rating_id,
					@intDaysFrom			= tccr.rating_isInitial_days
			FROM	tbCustomerCreditRating tccr			WITH (NOLOCK)
			WHERE	tccr.comp_id					= @comp_id	AND
					tccr.rating_disabled			= 'False'	AND
					tccr.rating_isAvailable4Initial	= 'True'	AND
					( tccr.brag_id IS NULL OR tccr.brag_id = @intBranchGroup)


		IF @intRatingID4Initial IS NOT NULL
			BEGIN
				UPDATE tbcustomer
					SET		rating_id				= @intRatingID4Initial,
							cust_ratingProcessCheck	= 1,
							tbcustomer.rating_id_cd = @datProcessingDate

					FROM	tbCustomer	tc		WITH (NOLOCK)
					WHERE	tc.cust_cd IS NULL OR
							datediff( day, isnull(tc.cust_cd,@datProcessingDate),@datProcessingDate) <= @intDaysFrom
			END
		-- ----------------------------------------------


		-- ----------------------------------------------
		-- Pone en una tabla temporal los clientes
		-- Su mora y su deuda total para PASO 2
		-- ----------------------------------------------
		DECLARE @tmpCustomerInDefault AS TABLE(	cust_id						INT PRIMARY KEY,
												intDaysInDefault			INT,
												decTotal2Pay				DECIMAL(19,2))

		INSERT INTO @tmpCustomerInDefault(	cust_id,
											intDaysInDefault,
											decTotal2Pay )
		SELECT DISTINCT tct.cust_id ,
						MAX(tctl.ctl_daysPastDue)	OVER (PARTITION BY tct.cust_id) AS MaxDefaultDays,
						SUM(tctl.ct_ABalance * vctfs.PlusOrMinus)
													OVER (PARTITION BY tct.cust_id) AS TotalBalance
			FROM		tbCommercialTransactions		tct		WITH (NOLOCK)
			INNER JOIN tbCustomer tc		WITH (NOLOCK)
				ON	tc.comp_id = tct.comp_id AND
					tc.cust_id = tct.cust_id
			INNER JOIN @tmpBranchs	tmpb
				ON	tmpb.bra_id				= tct.bra_id
			INNER JOIN vwCommercialTransactions_forSales vctfs		WITH (NOLOCK)
				ON	vctfs.comp_id			= tct.comp_id		AND
					vctfs.ct_transaction	= tct.ct_transaction
			INNER JOIN	tbCommercialTransactionsLoan	tctl		WITH (NOLOCK)
				ON	tctl.comp_id		= tct.comp_id			AND
					tctl.ct_transaction = tct.ct_transaction
		WHERE	tct.comp_id					=  @comp_id			AND
				tc.cust_ratingProcessCheck	= 0

		-- ----------------------------------------------




 		-- ----------------------------------------------
		-- Pone en una tabla temporal los clientes
		-- Su mora y su deuda total, etc. para PASO 3
		-- ----------------------------------------------
		DECLARE @tmpCustomer4OK AS TABLE(		cust_id						INT PRIMARY KEY,
												intDaysInDefault			INT,
												decTotal2Pay				DECIMAL(19,2),
												decAVGPaymentsOfLastYear	DECIMAL(19,4),
												decAVGDefaultDaysLastYear	DECIMAL(19,2))

		INSERT INTO @tmpCustomer4OK(	cust_id,
										intDaysInDefault,
										decTotal2Pay,
										decAVGPaymentsOfLastYear,
										decAVGDefaultDaysLastYear )
		SELECT DISTINCT tct.cust_id ,
						MAX(tctl.ctl_daysPastDue)	OVER (PARTITION BY tct.cust_id) AS MaxDefaultDays,
						SUM(tctl.ct_ABalance * vctfs.PlusOrMinus)
													OVER (PARTITION BY tct.cust_id) AS TotalBalance,
						AVG(tctl.ctl_daysPastDue * vctfs.PlusOrMinus)
													OVER (PARTITION BY tct.cust_id) AS AVGPaymentsOfLastYear,
						AVG(tctl.ct_ATotal * vctfs.PlusOrMinus)
													OVER (PARTITION BY tct.cust_id) AS AVGDefaultDaysLastYear
			FROM		tbCommercialTransactions		tct			WITH (NOLOCK)
			INNER JOIN tbCustomer tc	WITH (NOLOCK)
				ON	tc.comp_id = tct.comp_id AND
					tc.cust_id = tct.cust_id
			INNER JOIN @tmpBranchs	tmpb
				ON	tmpb.bra_id				= tct.bra_id
			INNER JOIN vwCommercialTransactions_forSales vctfs		WITH (NOLOCK)
				ON	vctfs.comp_id			= tct.comp_id		AND
					vctfs.ct_transaction	= tct.ct_transaction
			INNER JOIN	tbCommercialTransactionsLoan	tctl	WITH (NOLOCK)
				ON	tctl.comp_id		= tct.comp_id			AND
					tctl.ct_transaction = tct.ct_transaction
		WHERE	tct.comp_id					=  @comp_id			AND
				tc.cust_ratingProcessCheck	= 0					AND
				datediff(day,tctl.ctl_payDate,@datProcessingDate) <= 365

		-- ----------------------------------------------




		-- ----------------------------------------------
		-- PASO 2
		-- Para los clientes con deuda superior a X
		-- rating_isAvailable4Default = TRUE
		-- ----------------------------------------------
		-- Pone las condiciones de MOROSO para trabajar solo con ellas
		DELETE FROM @tmpRatings
		INSERT INTO @tmpRatings(rating_id)
		SELECT rating_id
		FROM tbCustomerCreditRating tccr
		WHERE	tccr.comp_id					= @comp_id	AND
				tccr.rating_disabled			= 'false'	AND
				tccr.rating_isAvailable4Default = 'True'	AND
				(tccr.brag_id IS NULL OR tccr.brag_id = @intBranchGroup)

		UPDATE tbcustomer
			SET rating_id				= tccr.rating_id ,
				cust_ratingProcessCheck = 1,
				tbcustomer.rating_id_cd = @datProcessingDate
			FROM tbCustomer tc	WITH (NOLOCK)
			inner join @tmpCustomerInDefault cid
				ON cid.cust_id = tc.cust_id
			INNER JOIN @tmpRatings tmpr
				ON tmpr.rating_id	= tc.rating_id
			INNER JOIN tbCustomerCreditRating tccr	WITH (NOLOCK)
				ON	tccr.comp_id	= tc.comp_id AND
					tccr.rating_id	= tc.rating_id
			WHERE	tc.comp_id = @comp_id AND
					cid.intDaysInDefault > 0 AND
					cid.decTotal2Pay		BETWEEN		tccr.rating_defaultTotalFrom AND tccr.rating_defaultTotalTo	AND
					cid.intDaysInDefault	BETWEEN		tccr.rating_defaultDaysFrom  AND tccr.rating_defaultDaysTo

		-- ----------------------------------------------






		-- ----------------------------------------------
		-- PASO 3
		-- rating_isAvailable4okCredit
		-- Para los que no son morosos
		-- ----------------------------------------------
		-- Pone las condiciones de MOROSO para trabajar solo con ellas
		DELETE FROM @tmpRatings
		INSERT INTO @tmpRatings(rating_id)
		SELECT rating_id
		FROM tbCustomerCreditRating tccr
		WHERE	tccr.comp_id					 = @comp_id	AND
				tccr.rating_disabled			 = 'false'	AND
				tccr.rating_isAvailable4okCredit = 'True'	AND
				(tccr.brag_id IS NULL OR tccr.brag_id = @intBranchGroup)
		UPDATE tbcustomer
			SET rating_id				= tccr.rating_id ,
				cust_ratingProcessCheck = 1,
				tbcustomer.rating_id_cd = @datProcessingDate
			FROM tbCustomer tc	WITH (NOLOCK)
			inner join @tmpCustomer4OK cid
				ON cid.cust_id = tc.cust_id
			INNER JOIN @tmpRatings tmpr
				ON tmpr.rating_id	= tc.rating_id
			INNER JOIN tbCustomerCreditRating tccr	WITH (NOLOCK)
				ON	tccr.comp_id	= tc.comp_id AND
					tccr.rating_id	= tc.rating_id
			WHERE	tc.comp_id  = @comp_id AND
					cid.intDaysInDefault > 0 AND
					cid.decAVGPaymentsOfLastYear	BETWEEN		tccr.rating_okCreditAvgSaleFrom			AND tccr.rating_okCreditAvgSaleTo	AND
					cid.decAVGDefaultDaysLastYear	BETWEEN		tccr.rating_okCreditAvgDefaultDaysFrom  AND tccr.rating_okCreditAvgDefaultDaysTo

		-- ----------------------------------------------


		-- ----------------------------------------------
		-- PASO 4
		-- Pone como NO PROCESADOS a todos los que
		-- NO entraron en los procesos anteriores
		-- ----------------------------------------------
		SET @intRatingID4Initial = NULL
		SELECT TOP 1 @intRatingID4Initial = rating_id
			FROM tbCustomerCreditRating tccr
			WHERE	tccr.comp_id					  = @comp_id	AND
					tccr.rating_disabled			  = 'false'	AND
					tccr.rating_isAvailable4NoProcess = 'True'	AND
					(tccr.brag_id IS NULL OR tccr.brag_id = @intBranchGroup)
		IF @intRatingID4Initial IS NOT NULL
			BEGIN
				UPDATE tbcustomer
					SET rating_id					= @intRatingID4Initial,
						tbcustomer.rating_id_cd		= @datProcessingDate,
						cust_ratingProcessCheck     = 1
					WHERE cust_ratingProcessCheck	= 0 AND comp_id = @comp_id
			END
		-- ----------------------------------------------



		-- ----------------------------------------------
		-- PASO 5
		-- Guarda Historial
		-- ----------------------------------------------
		INSERT INTO tbCustomerCreditRating_History
		(
			comp_id,
			cust_id,
			rating_id,
			rating_idOLD,
			rating_cd,
			[user_id]
		)
		SELECT	tc.comp_id,
				tc.cust_id,
				tc.rating_id,
				tc.rating_id_previous,
				@datProcessingDate,
				@user_id
			FROM tbcustomer tc	WITH (NOLOCK)
			WHERE tc.cust_ratingProcessCheck = 1 and tc.comp_id = @comp_id
		-- ----------------------------------------------


		-- Saca todas las marcas de procesamiento
		UPDATE tbcustomer
			SET cust_ratingProcessCheck = 0

		COMMIT TRANSACTION

	 END TRY
	 BEGIN CATCH
		--ROLLBACK TRANSACTION
	 END CATCH


END
GO







