CREATE PROCEDURE [dbo].[spCustomer_updateDataFromWebSite]
(
	@comp_id				INT,
	@ws_id					UNIQUEIDENTIFIER,
	@cust_id				INT,
	@cust_name				NVARCHAR(200),
	@country_id				INT,
	@state_id				INT,
	@cust_address			NVARCHAR(150),
	@cust_City				NVARCHAR(60),
	@cust_zip				NVARCHAR(20),
	@fc_id					INT,
	@tnt_id					INT,
	@cust_taxNumber			NVARCHAR(50),
	@cust_email				NVARCHAR(250),
	@cust_Phone1			NVARCHAR(200),
	@cust_webNickName		NVARCHAR(250),
	@return_value			INT	OUTPUT
)
AS

BEGIN

	--------------------------------------------------------------------------------------------------------
	-- ATENCIÓN! SI SE TOCA ALGO ACÁ, TAMBIÉN TOCARLO EN spCustomer_insertDataFromWebService pNickName
	--------------------------------------------------------------------------------------------------------


	SET NOCOUNT ON

	-- ------------------------------------------------------------------
	-- Test
	-- ------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@cust_id			INT,

			@name				NVARCHAR(200),
			@country			INT,
			@state				INT,
			@address			NVARCHAR(150),
			@city				NVARCHAR(200),
			@fiscalclass		INT,
			@taxnumbertype		INT,
			@taxnumber			NVARCHAR(50),
			@email				NVARCHAR(300),
			@phone				NVARCHAR(200),
			@nickname			NVARCHAR(50),
			@pass1				NVARCHAR(50),

			@returnvalue		INT

	SELECT 	@comp_id			=1,
			@cust_id			=24300,

			@name				='PRUEBA WEB',
			@country			=54,
			@state				=54019,
			@address			='DOMICILIO PRUEBA WEB',
			@city				='Capital Federal',
			@fiscalclass		=1,
			@taxnumbertype		=1,
			@taxnumber			='30-65856224-6',
			@email				='prueba@prueba.com',
			@phone				='3220-7172',
			@nickname			='nuevo',
			@pass1				='nuveo'

	*/
	-- ------------------------------------------------------------------

	SET @return_value = 0

	UPDATE tbcustomer
		SET
			cust_name =			CASE
									WHEN	dbo.fnStrAllTrim( @cust_name ) <> ''	THEN @cust_name
									ELSE												 cust_name
								END,
			country_id =		CASE
									WHEN	@country_id > 0							THEN @country_id
									ELSE												 country_id
								END,
			state_id =			CASE
									WHEN	@state_id > 0							THEN @state_id
									ELSE											     state_id
								END,
			cust_address =		CASE
									WHEN	dbo.fnStrAllTrim( @cust_address ) <> '' THEN @cust_address
									ELSE												 cust_address
								END,
			cust_City =			CASE
									WHEN	dbo.fnStrAllTrim( @cust_City ) <> ''		THEN @cust_City
									ELSE													 cust_City
								END,
			cust_zip =			CASE
									WHEN	dbo.fnStrAllTrim( @cust_zip ) <> ''			THEN @cust_zip
									ELSE													 cust_zip
								END,
			fc_id =				CASE
									WHEN	@fc_id > 0 THEN @fc_id
									ELSE	fc_id
								END,
			tnt_id =			CASE
									WHEN	@tnt_id > 0 THEN @tnt_id
									ELSE	tnt_id
								END,
			cust_taxNumber =	CASE
									WHEN	dbo.fnStrAllTrim( @cust_taxNumber ) <> '' THEN @cust_taxNumber
									ELSE	cust_taxNumber
								END,
			cust_email =		CASE
									WHEN	dbo.fnStrAllTrim( @cust_email ) <> '' THEN @cust_email
									ELSE	cust_email
								END,
			cust_Phone1 =		CASE
									WHEN	dbo.fnStrAllTrim( @cust_Phone1 ) <> '' THEN @cust_Phone1
									ELSE	cust_Phone1
			             		END,
			cust_webNickName  =	CASE
									WHEN	dbo.fnStrAllTrim( @cust_webNickName ) <> '' THEN @cust_webNickName
									ELSE	cust_webNickName
								END



		WHERE	comp_id = @comp_id AND
				cust_id = @cust_id


		IF @@ROWCOUNT = 0
			BEGIN
				SET @return_value = -1
			END
		ELSE
			BEGIN
				SET @return_value = @cust_id
			END




END

GO





-- =============================================
-- Author:		MOS
-- Create date: 10-2008
-- Description:	Actualiza isEditing en Clientes
-- =============================================

CREATE PROCEDURE [dbo].[spCustomer_updateIsEditing]
	@comp_id			as int,
	@cust_id			as int,
	@user_id			as int,
	@cust_isediting		as BIT,
	@ForceActualization AS bit
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	/*
	declare 	@comp_id			as int,
		@cust_id			as int,
		@user_id			as int,
		@cust_isediting		as bit
	select 	@comp_id			=1,
		@cust_id			=19976,
		@user_id			=2,
		@cust_isediting		='False'
	*/

	Update	dbo.tbCustomer WITH (ROWLOCK)
		Set		cust_isediting			= @cust_isediting,
				cust_iseditingCd		= getdate(),
				cust_isEditingUserId	= @user_id
		FROM tbCustomer cu
		Where	cu.comp_id					= @comp_id
			and	cu.cust_id					= @cust_id
			AND (@ForceActualization = 'True' OR cu.cust_isediting = 'true')

END

GO







