CREATE PROCEDURE [dbo].[spCustomer_updatePassword]
(
	@comp_id				INT,
	@ws_id					UNIQUEIDENTIFIER,
	@cust_id				int,
	@cust_webPassword		nvarchar(50),
	@return_value			INT OUTPUT
)
as

BEGIN
	SET NOCOUNT ON


	SET @cust_webPassword = dbo.fnStrAllTrim(@cust_webPassword)

	-- Si se dio de alta de la nueva manera...
	IF EXISTS(
					SELECT TOP 1  1
						FROM tbWebSiteII_Users twsiu WITH (NOLOCK)
						WHERE	twsiu.comp_id	= @comp_id	AND
								twsiu.ws_id		= @ws_id	AND
								twsiu.cust_id	= @cust_id
				)
		BEGIN

			UPDATE tbWebSiteII_Users
				SET wsu_webPassword = @cust_webPassword
			FROM tbWebSiteII_Users twsiu WITH (NOLOCK)
			WHERE	twsiu.comp_id	= @comp_id	AND
					twsiu.ws_id		= @ws_id	AND
					twsiu.cust_id	= @cust_id
			SET @return_value = 1
			RETURN
		END


	-- Vieja Manera.
	UPDATE	tbCustomer
		SET		cust_webPassword	= @cust_webPassword--,
				--cust_login			= 'false'
		WHERE 	comp_id				= @comp_id	AND
				cust_id				= @cust_id



	-- Ya que no esta de la nueva manera, lo da de alta
	DECLARE @wsu_webNickName AS NVARCHAR(200) = ''
	SELECT  @wsu_webNickName = tc.cust_webNickName
		FROM tbCustomer tc					WITH (NOLOCK)
		WHERE	tc.comp_id = @comp_id AND
				tc.cust_id = @cust_id

	INSERT INTO tbWebSiteII_Users
	(
		comp_id,
		ws_id,
		cust_id,
		wsu_webNickName,
		wsu_webPassword,
		wsu_block2Login,
		wsu_cd,
		wsu_lastLogin
	)
	VALUES
	(
		@comp_id,
		@ws_id,
		@cust_id,
		@wsu_webNickName,
		@cust_webPassword,
		'False',
		GETDATE(),
		GETDATE()
	)




	SET @return_value = 1
	RETURN

END







GO



