-- =============================================
CREATE PROCEDURE [dbo].[spCustomer_WSGetDataByPhone]
	@comp_id AS INT,
	@strCustomerName AS NVARCHAR(200),
	@strPhone AS NVARCHAR(200)

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	IF @strPhone <> ''	SET @strPhone = '%' + @strPhone + '%'
	IF @strCustomerName <> ''	SET @strCustomerName = '%' + @strCustomerName + '%'


	SELECT @strPhone,@strCustomerName

	SELECT tc.cust_id, tc.cust_name, tc.cust_name1, tc.cust_taxNumber,
	       tc.cust_taxIBNumber, tc.cust_address, tc.cust_city, tc.cust_zip,
	       tc.country_id, tc.state_id, tc.cust_phone1, tc.cust_phone2,
	       tc.cust_email, tc.cust_fax, tc.cust_picture, tc.sm_id, tc.ck_id,
	       tc.st_id, tc.disc_id, tc.dl_id, tc.cust_credit_max, tc.cust_credit_own,
	       tc.curr_id, tc.prli_id, tc.tnt_id, tc.cust_note1, tc.cust_note2,
	       tc.cust_note3, tc.cust_note4, tc.cust_address4Delivery,
	       tc.cust_address4Payments, tc.cust_webNickName, tc.cust_webPassword,
	       tc.cust_cd, tc.cust_contact4Payments, tc.cust_email4Payments,
	       tc.cust_contact4Management, tc.cust_contact4Administration,
	       tc.cust_email4Management, tc.cust_email4Administration,
	       tc.cust_contact4Logistics, tc.cust_email4Logistics, tc.act_id
		FROM tbCustomer tc
		WHERE	(dbo.fnGetOnlyNumbers(tc.cust_phone1) LIKE @strPhone AND @strPhone <> '' )or
				(dbo.fnGetOnlyNumbers(tc.cust_phone2) LIKE @strPhone AND @strPhone <> '' ) or
				(dbo.fnGetOnlyNumbers(tc.cust_fax)    LIKE @strPhone AND @strPhone <> '' ) or
				(tc.cust_name   LIKE @strCustomerName AND @strCustomerName <> '' ) OR
				(tc.cust_name1  LIKE @strCustomerName AND @strCustomerName <> '' )


END
GO





