CREATE PROCEDURE [dbo].[spCustomerAssociation_GetDataByFilters]
(
		@comp_id			INT,
		@cust_id			INT,
		@cust_id_associated	INT,
		@cb_id				INT
)
AS SET NOCOUNT ON

	BEGIN

		-- --------------------------------
		-- TESTING
		-- --------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@cust_id			INT,
				@cust_id_associated	INT,
				@cb_id				INT

			SELECT
				@comp_id			= 1,
				@cust_id			= 1,
				@cust_id_associated	= 1,
				@cb_id				= 1
		*/
		-- --------------------------------



		SELECT
			' ' [ ], ' ' [ ],
			tc.cust_name,
			tc2.cust_name,
			tcb.custb_name,

			CONVERT(VARCHAR,tca.comp_id)			+ '-' +
			CONVERT(VARCHAR,tca.cust_id)			+ '-' +
			CONVERT(VARCHAR,tca.cust_id_associated) + '-' +
			CONVERT(VARCHAR,tca.cb_id_associated)				[ID]

		FROM tbCustomerAssociation						tca

			INNER JOIN tbCustomer						tc
			ON	tc.comp_id = tca.comp_id AND
				tc.cust_id = tca.cust_id

			INNER JOIN tbCustomer						tc2
			ON	tc2.comp_id = tca.comp_id AND
				tc2.cust_id = tca.cust_id_associated

			INNER JOIN tbCustomerBranch					tcb
			ON  tcb.comp_id = tc2.comp_id AND
				tcb.cb_id	= tca.cb_id_associated

		WHERE	tca.comp_id				= @comp_id													AND
				(@cust_id				= -1	OR tca.cust_id				= @cust_id)				AND
				(@cust_id_associated	= -1	OR tca.cust_id_associated	= @cust_id_associated)	AND
				(@cb_id					= -1	OR tca.cb_id_associated		= @cb_id)

	END
GO




CREATE PROCEDURE [dbo].[spCustomerAssociation_GetDataByID]
(
		@comp_id			INT,
		@cust_id			INT,
		@cust_id_associated	INT,
		@cb_id				INT
)
AS SET NOCOUNT ON

	BEGIN
		-- --------------------------------
		-- TESTING
		-- --------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@cust_id			INT,
				@cust_id_associated	INT,
				@cb_id				INT

			SELECT
				@comp_id			= 1,
				@cust_id			= 1,
				@cust_id_associated	= 1,
				@cb_id				= 1
		*/
		-- --------------------------------


		SELECT
			tca.comp_id,
			tca.cust_id,
			tc.cust_name,
			tca.cust_id_associated,
			tc2.cust_name				[cust_name2],
			tca.cb_id_associated

		FROM tbCustomerAssociation			tca

			INNER JOIN tbCustomer			tc
			ON	tc.comp_id = tca.comp_id AND
				tc.cust_id = tca.cust_id

			INNER JOIN tbCustomer			tc2
			ON	tc2.comp_id = tca.comp_id AND
				tc2.cust_id	= tca.cust_id_associated

		WHERE	tca.comp_id				= @comp_id				AND
				tca.cust_id				= @cust_id				AND
				tca.cust_id_associated	= @cust_id_associated	AND
				tca.cb_id_associated	= @cb_id

	END
GO




CREATE PROCEDURE [dbo].[spCustomerAssociation_InsertData]
(
		@comp_id				INT,
		@cust_id				INT,
		@cust_id_associated		INT,
		@cb_id					INT
		--@return_value			INT OUTPUT
)
AS SET NOCOUNT ON

	BEGIN

		-- --------------------------------
		-- TESTING
		-- --------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@cust_id			INT,
				@cust_id_associated	INT,
				@cb_id				INT

			SELECT
				@comp_id			= 1,
				@cust_id			= 1,
				@cust_id_associated	= 1,
				@cb_id				= 1
		*/
		-- --------------------------------

		DECLARE
			@lcb_id	INT
		IF @cb_id = -1
			BEGIN
				SET @lcb_id = NULL
			END
		ELSE
			BEGIN
				SET @lcb_id	= @cb_id
			END


		INSERT INTO tbCustomerAssociation
		(
			comp_id,
			cust_id,
			cust_id_associated,
			cb_id_associated
		)
		VALUES
		(
			@comp_id,
			@cust_id,
			@cust_id_associated,
			@lcb_id
		)

		--SET @return_value = @@IDENTITY

	END
GO



