CREATE Procedure [dbo].[spCustomerBalanceAging4Past_getReport]
(
		@comp_id		int,
		@lang_id		int,
		@page_id		int,

		@custsupp		int,
		@sm_id			int,
		@ck_id			int,
		@country_id		int,
		@state_id		int,
		@ss_id			int,
		@dl_id			int,
		@balancefrom	BIGINT,
		@balanceto		BIGINT,
		@act_id			INT,
		@credit_option  INT,
		@custsm_id		INT,
		@guid			VARCHAR(50),
		@bra_id			INT,
		@user_id		INT,
		@intBranch4Lang INT,
		@intOrder		int

)
AS

BEGIN

	set nocount on
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set dateformat 'ymd'


-- -------------------------------------------------
-- Testing
-- -------------------------------------------------
/*
	DECLARE

			@comp_id		INT,
			@lang_id		INT,
			@page_id		INT,

			@custsupp		INT,
			@sm_id			INT,
			@ck_id			INT,
			@country_id		INT,
			@state_id		INT,
			@ss_id			INT,
			@dl_id			INT,
			@balancefrom	INT,
			@balanceto		INT,
			@act_id			INT,
			@bra_id			INT,
			@user_id		INT,
			@intBranch4Lang INT,
			@credit_option  INT,
			@intOrder		INT,
			@custsm_id		INT,
			@guid			VARCHAR(50)


	SELECT
			@comp_id		=1,
			@lang_id		=2,
			@page_id		=10086,

			@custsupp		=-1,
			@sm_id			=-1,
			@ck_id			=-1,
			@country_id		=-1,
			@state_id		=-1,
			@ss_id			=-1,
			@dl_id			=-1,
			@balancefrom	='-99999999',
			@balanceto		='99999999',
			@bra_id			= 1 ,
			@user_id		= 39,
			@act_id			=-1,
			@credit_option  = 0,
			@intOrder		= 1,
			@custsm_id		= -1,
			@guid			= 'e488791d-b010-467a-976c-62dea8da1236'

	drop table #tmp
	drop table #tmp2
*/
-- -------------------------------------------------


	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)


	DECLARE @bra_Credit_AssumeValuesAcreditDays AS INT
	SET @bra_Credit_AssumeValuesAcreditDays = 4
	SELECT @bra_Credit_AssumeValuesAcreditDays = tb.bra_Credit_AssumeValuesAcreditDays
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Customer
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Customer
				SELECT tc.cust_id
				FROM tbCustomer tc
					WHERE tc.comp_id = @comp_id
		END
	-- -------------------------------------------------------------


	-- ------------------------------------------------------------------
	-- Asceleracion del reporte
	-- Pone en una tabla temporal a los clientes que tengan saldo
	-- o valores.  Esto sirve para lugares con MUUUCha cantidad de datos.
	-- ------------------------------------------------------------------
	DECLARE @tblCustomerIncludedTmp TABLE(	cust_id	INT 	)
	DECLARE @tblCustomerIncludedTmp1 TABLE(	cust_id	INT 	)
	DECLARE @tblCustomerIncluded	TABLE(	cust_id	INT PRIMARY KEY,
											cust_credit_cheque_own_used decimal(19,4),
											cust_credit_cheque_3rd_used decimal(19,4),
											cust_credit_max				decimal(19,4),
											cust_credit_balance			decimal(19,4))

	INSERT INTO @tblCustomerIncludedTmp (cust_id)
		SELECT DISTINCT tc.cust_id
			FROM tbCommercialTransactions tct		WITH (NOLOCK)
			INNER JOIN tbCustomer tc				WITH (NOLOCK)
				ON	tc.comp_id = tct.comp_id AND
					tc.cust_id = tct.cust_id
		WHERE	tct.comp_id = @comp_id		AND
				(tct.cust_id IS NOT NULL)	AND
				tct.ct_ABalance <> 0		AND
				(@custsupp	= -1 or tc.cust_id	= @custsupp)	AND
				(@sm_id		= -1 or tc.sm_id	= @sm_id)		AND
				(@act_id	= -1 or tc.act_id	= @act_id)


	-- ATENCION !!
	-- Si se toca algo aqui tocar tembien en **BalanceStatus	(Buscarlo en la DB)
	INSERT INTO @tblCustomerIncludedTmp (cust_id)
		SELECT DISTINCT  ct.cust_id
			From dbo.tbCheckPortfolio					CP					WITH (NOLOCK)
				INNER JOIN tbBranch tb										WITH (NOLOCK)
					ON	tb.comp_id				= cp.comp_id AND
						tb.bra_id				= cp.bra_id_PortFolio
				inner Join dbo.tbCommercialTransactions		CT				WITH (NOLOCK)
					On		CT.comp_id			= CP.comp_id
						and CT.ct_transaction	= CP.ct_transaction

				Inner Join dbo.vwCheckPortfolio_AllPayPending CPOP			WITH (NOLOCK)
					On		(CPOP.comp_id		= CP.comp_id
						and CPOP.chp_id			= CP.chp_id)
				INNER JOIN tbUsers4BranchFilter				vubf			WITH (NOLOCK)
					ON vubf.comp_id				= cp.comp_id
					AND vubf.bra_id				= cp.bra_id
					AND vubf.[user_id]			= @user_id
				Where  CP.comp_id				= @comp_id
					AND (	(cpop.isSold='false' AND cpop.isPayed2Supplier = 'False')
						  OR
							(
								(cpop.isSold='True' OR cpop.isPayed2Supplier = 'True') AND cp.chp_PayDate > (tb.bra_processingDate - @bra_Credit_AssumeValuesAcreditDays)  -- Si fueron vendidos toma en cuenta una semana mas de plazo para liberar el credito
							)
						)
					--AND CASE
					--		WHEN tb.bra_Credit_AssumeAcredit2DaysPostDate = 'True' AND DATEDIFF(DAY,cp.chp_PayDate,tb.bra_processingDate) > 2  THEN 'False'
					--		ELSE 'True'
					--	END	= 'True'
					AND NOT EXISTS (SELECT 1 FROM @tblCustomerIncludedTmp tt WHERE tt.cust_id = ct.cust_id)
					AND ct.cust_id IS NOT NULL



	INSERT INTO @tblCustomerIncludedTmp1 (	cust_id)
		SELECT 	DISTINCT			tmp.cust_id
			FROM  @tblCustomerIncludedTmp tmp

	INSERT INTO @tblCustomerIncluded (	cust_id,
										cust_credit_cheque_own_used,
										cust_credit_cheque_3rd_used,
										cust_credit_max,
										cust_credit_balance)
		SELECT 				tmp.cust_id ,
							fcgbs.cust_credit_cheque_own_used,
							fcgbs.cust_credit_cheque_3rd_used,
							fcgbs.cust_credit_max,
							fcgbs.cust_credit_balance
			FROM  @tblCustomerIncludedTmp1 tmp
			INNER JOIN tbBranch tb
				ON	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id
			CROSS APPLY dbo.fnCustomer_getBalanceStatus(tb.comp_id ,
														    tb.curr_id,
															tmp.cust_id,
															@user_id,
															tb.bra_processingDate,
															-1,
															CASE
																when @balancefrom = -9999999999 and @balanceto = 9999999999  then 0
																else 0
															END) fcgbs
															--CASE    MOS 03-2017
															--	when (@balancefrom = -99999999 and @balanceto = 99999999) AND @credit_option = 0 then -2
															--	else -3
															--END) fcgbs
		WHERE
			CASE
				when (@balancefrom = -9999999999 and @balanceto = 9999999999)		THEN	1
				WHEN fcgbs.cust_credit_balance BETWEEN @balancefrom AND @balanceto	THEN	1
				else 0
			END		= 1


		--WHERE tmp.cust_id IS NOT NULL
	-- ------------------------------------------------------------------



	DECLARE @datProcessingDate AS DATETIME
	SELECT  @datProcessingDate = tb.bra_processingDate
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id

	SET @datProcessingDate = DATEADD(DAY,-91, @datProcessingDate)

	DECLARE @fun_id INT
	SET @fun_id = 1


	DECLARE @bra_curr_id INT
	SELECT @bra_curr_id = curr_id FROM tbBranch tb WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id

	Select	convert(varchar,CT.cust_id) [cust_id],
			C.cust_name,
			sum(isnull(Case
				When CT.ct_PayDate <= @datProcessingDate THEN (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,ct.ct_ACurrency,ct.curr_id_transaction, ct.ct_ACurrencyExchange,'false' ) * vwct.PlusOrMinus )
			end,0))  [+ 90 Dias],		--[A Futuro]
			sum(isnull(Case
				When CT.ct_PayDate > @datProcessingDate and CT.ct_PayDate <= @datProcessingDate+30 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,ct.ct_ACurrency,ct.curr_id_transaction, ct.ct_ACurrencyExchange,'False') * vwct.PlusOrMinus )
			end,0)) [90 Dias],		--[30 Dias]
			sum(isnull(Case
				When CT.ct_PayDate > @datProcessingDate+30 and CT.ct_PayDate <= @datProcessingDate+60 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,ct.ct_ACurrency,ct.curr_id_transaction, ct.ct_ACurrencyExchange,'false')*  vwct.PlusOrMinus )
			end,0)) [60 Dias],		--[60 Dias]
			sum(isnull(Case
				When CT.ct_PayDate > @datProcessingDate+60 and CT.ct_PayDate < @datProcessingDate+90 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,ct.ct_ACurrency,ct.curr_id_transaction, ct.ct_ACurrencyExchange,'false') * vwct.PlusOrMinus )
			end,0)) [30 Dias],		--[90 Dias]
			sum(isnull(Case
				When CT.ct_PayDate >= @datProcessingDate+90 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,ct.ct_ACurrency,ct.curr_id_transaction, ct.ct_ACurrencyExchange,'false') * vwct.PlusOrMinus )
			end,0)) [A Futuro],	--[+ 90 Dias]
			ts.sm_name [sm_name],
			tmp.cust_credit_cheque_own_used [cust_credit_cheque_own_used],
			tmp.cust_credit_cheque_3rd_used [cust_credit_cheque_3rd_used],
			tmp.cust_credit_max				[cust_credit_max],
			ta.act_desc						[act_desc],
			tck.ck_name						[ck_name]

	into   #tmp

	From	dbo.vwCommercialTransactions_forSales									VWCT		WITH (NOLOCK)



			INNER JOIN tbBranch														tb			WITH (NOLOCK)
			ON	tb.comp_id	= vwct.comp_id					AND
				tb.bra_id	= VWCT.bra_id

			INNER JOIN @tblCustomerIncluded tmp
				ON tmp.cust_id = vwct.cust_id

			INNER JOIN dbo.tbCommercialTransactions									CT			WITH (NOLOCK)
			ON  VWCT.comp_id		=	CT.comp_id
			AND VWCT.bra_id			=	CT.bra_id
			AND VWCT.ct_transaction	=	CT.ct_transaction


			INNER JOIN @tblComplexFilter_Customer		tempCustomer
			ON tempCustomer.cust_id						= CT.cust_id

			INNER JOIN dbo.tbCustomer												C			WITH (NOLOCK)
			ON  CT.comp_id			=	C.comp_id
			AND CT.cust_id			=	C.cust_id
			AND (@ck_id				=	-1 OR C.ck_id		= @ck_id		)
			AND (@country_id		=	-1 OR C.country_id	= @country_id	)
			AND (@state_id			=	-1 OR C.state_id	= @state_id		)
			AND (@ss_id				=	-1 OR C.ss_id		= @ss_id		)
			AND (@dl_id			    =	-1 OR C.dl_id		= @dl_id		)
			AND isnull(c.cust_judMan,'False')			    = 'False'
			AND IsNull(c.cust_4InitialValues,'False')		= 'False'




			LEFT JOIN tbActivity													ta			WITH (NOLOCK)
			ON  ta.comp_id			= C.comp_id AND
				ta.act_id			= C.act_id

			LEFT JOIN tbCustomerKind												tck			WITH (NOLOCK)
			ON	tck.comp_id			= C.comp_id AND
				tck.ck_id			= C.ck_id

			left JOIN tbSalesman													ts			WITH (NOLOCK)
			ON  ts.comp_id			= C.comp_id
			AND ts.sm_id			= C.sm_id

			inner join tbUsers4BranchFilter											vubf		WITH (NOLOCK)
			ON  vubf.comp_id		= CT.comp_id
			AND vubf.bra_id			= CT.bra_id
			AND vubf.[user_id]		= @user_id

--			CROSS APPLY dbo.fnCustomer_getBalanceStatus(ct.comp_id ,
--														    tb.curr_id,
--															c.cust_id,
--															@user_id,
--															tb.bra_processingDate,
--															-1,
--															CASE
--																when (@balancefrom = -99999999 and @balanceto = 99999999) AND @credit_option = 0 then -2
--																else -3
--															END) fcgbs

	WHERE CT.comp_id	= @comp_id
	AND   (@custsupp	= -1 or CT.cust_id	= @custsupp)
	AND   (@sm_id		= -1 or CT.sm_id	= @sm_id)
	AND   (@custsm_id	= -1 or C.sm_id		= @custsm_id)
	and	   tmp.cust_credit_balance BETWEEN @balancefrom AND @balanceto
	AND	   vwct.sd_isInBalance = 'True'
	AND   (@act_id		= -1 or C.act_id	= @act_id)

	GROUP BY	CT.cust_id, C.cust_name,ts.sm_name,tmp.cust_credit_cheque_own_used ,tmp.cust_credit_cheque_3rd_used ,tmp.cust_credit_max,ta.act_desc,tck.ck_name
	ORDER BY	C.cust_name


	select  temp.cust_id,
			temp.cust_name,
			temp.[A Futuro],temp.[30 Dias],
			temp.[60 Dias],temp.[90 Dias],temp.[+ 90 DIas],
			sum(temp.[A Futuro]+temp.[30 Dias]+temp.[60 Dias]+temp.[90 Dias]+temp.[+ 90 DIas]) [Total],
			temp.[sm_name],
			temp.[cust_credit_cheque_own_used],
			temp.[cust_credit_cheque_3rd_used],
			temp.[cust_credit_max],
			temp.[act_desc],
			temp.[ck_name]

	into	#tmp2

	from	#tmp temp

	GROUP BY	temp.cust_id,
				temp.cust_name,
				temp.[A Futuro],temp.[30 Dias],
				temp.[60 Dias],
				temp.[90 Dias],
				temp.[+ 90 DIas],
				temp.[sm_name],
				temp.[cust_credit_cheque_own_used],
				temp.[cust_credit_cheque_3rd_used],
				temp.[cust_credit_max],
				temp.[act_desc],
				temp.[ck_name]






	IF @intOrder = 1
		BEGIN
			select	    temp2.cust_id,
						temp2.cust_name,
						temp2.[A Futuro],
						temp2.[30 Dias],
						temp2.[60 Dias],
						temp2.[90 Dias],
						temp2.[+ 90 DIas],
						temp2.[sm_name],
						temp2.[cust_credit_cheque_own_used],
						temp2.[cust_credit_cheque_3rd_used],
						temp2.[cust_credit_max],
						temp2.[act_desc],
						temp2.[ck_name]
				from        #tmp2		temp2
				where		temp2.[Total]<> 0
			ORDER BY temp2.cust_name ASC

		END
	ELSE IF @intOrder = 2
		BEGIN
			select	    temp2.cust_id,
						temp2.cust_name,
						temp2.[A Futuro],
						temp2.[30 Dias],
						temp2.[60 Dias],
						temp2.[90 Dias],
						temp2.[+ 90 DIas],
						temp2.[sm_name],
						temp2.[cust_credit_cheque_own_used],
						temp2.[cust_credit_cheque_3rd_used],
						temp2.[cust_credit_max],
						temp2.[act_desc],
						temp2.[ck_name]
				from        #tmp2		temp2
				where		temp2.[Total]<> 0
				ORDER BY temp2.Total ASC
		END
	ELSE
		BEGIN
			select	    temp2.cust_id,
						temp2.cust_name,
						temp2.[A Futuro],
						temp2.[30 Dias],
						temp2.[60 Dias],
						temp2.[90 Dias],
						temp2.[+ 90 DIas],
						temp2.[sm_name],
						temp2.[cust_credit_cheque_own_used],
						temp2.[cust_credit_cheque_3rd_used],
						temp2.[cust_credit_max],
						temp2.[act_desc],
						temp2.[ck_name]
				from        #tmp2		temp2
				where		temp2.[Total]<> 0
				ORDER BY temp2.Total DESC
		END




	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 402
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params1],

			CASE @custsupp WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
	     		ELSE
										(Select Tc.cust_name
						FROM	tbCustomer tc
						WHERE	Tc.comp_id = @comp_id
						AND		Tc.cust_id = @custsupp)

			END		[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 172
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params3],
			CASE @sm_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.sm_name
						FROM	tbSalesman ts
						WHERE	ts.comp_id = @comp_id AND ts.sm_id = @sm_id)
			END		[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 372
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],
			CASE @ck_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tck.ck_name
						FROM	tbCustomerKind tck
						WHERE	Tck.comp_id = @comp_id AND Tck.ck_id = @ck_id)
			END		[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 57
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params7],
			CASE @country_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		Tc.country_desc
						FROM	tbsysCountry tc
						WHERE	tc.country_id= @country_id)
			END		[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 59
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params9],
		CASE @state_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.state_desc
						FROM	tbsysState ts
						WHERE	Ts.state_id= @state_id)
			END		[params10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 488
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params11],
		CASE @ss_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tss.ss_desc
						FROM	tbSaleSector tss
						WHERE	tss.ss_id= @ss_id)
			END		[params12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 170
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params13],
			CASE @dl_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		td.dl_name
						FROM	tbDelivery td
						WHERE	td.comp_id = @comp_id AND td.dl_id = @dl_id)
			END		[params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 401
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id)		[params15],

		CONVERT(NVARCHAR,@balancefrom) + ' - ' + CONVERT(NVARCHAR,@balanceto)				[params16],

		(SELECT tswn.word_desc FROM tbSysWordsNew tswn WHERE tswn.lang_id = @lang_id and tswn.wordsi_id = 3632)	[params17],


	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 2379
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params18],
		CASE @act_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ta.act_desc
					 FROM	tbActivity ta
						WHERE	ta.act_id= @act_id)
			END		[params19],


	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 2380
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params20],

		(

		SELECT tov.optval_desc  FROM tbsysOptionsValues tov

		WHERE	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 1			AND
				tov.optval_id		= @credit_option

		) [params21],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 2465
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id = @fun_id)		[params22],

		(

		SELECT tov.optval_desc  FROM tbsysOptionsValues tov

		WHERE	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 322		AND
				tov.optval_id		= @intOrder

		) [params23],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2966
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id = @fun_id)		[params24],
			CASE @custsm_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.sm_name
						FROM	tbSalesman ts
						WHERE	ts.comp_id = @comp_id AND ts.sm_id = @custsm_id)
			END		[params25]






END
GO




CREATE PROCEDURE [dbo].[spCustomerBranch_GetCombo]
(
	@comp_id			int	,
	@cust_id			INT,
	@prof_id			INT,
	@bra_id				INT
)

AS

BEGIN


	SET NOCOUNT ON

	--select		cb_id		[id],
	--			custb_name	[desc]

	--	from		tbCustomerBranch  cb
	--	where		cb.comp_id =	@comp_id										AND
	--				cb.cust_id =   @cust_id											AND
	--			   (cb.prof_id			IS NULL OR cb.prof_id		  =  @prof_id)	AND
	--			   (cb.bra_id_Disabled	IS NULL OR cb.bra_id_Disabled <> @bra_id)
	--	Order By	custb_name


	-- 01-2019 sugerido por GN, DE
	select
		cb.cb_id	[id],
		custb_name	[desc]
		from		tbCustomerBranch  cb		with(nolock)
		inner join tbCustomer cust	with(nolock)
			on	cust.comp_id = cb.comp_id	AND
				cust.cust_id = cb.cust_id
		where
				cb.comp_id = @comp_id												AND
				cb.cust_id = @cust_id												AND
				(cb.prof_id	IS NULL OR cb.prof_id =  @prof_id)						AND
				(cb.bra_id_Disabled	IS NULL OR cb.bra_id_Disabled <> @bra_id)		AND
			    (	isnull(cust.cust_SaleOrderBranchTransfer,'False') = 'False'
					OR
					((cust.cust_SaleOrderBranchTransfer = 'True' AND cb.cb_id in (
																				select bcs.cb_id
																					from	tbBranch2Customer4StockImport bcs with(nolock)
																					where	bcs.comp_id			= @comp_id	AND
																							bcs.bra_id_original = @bra_id
																			)))
				)

		Order By
			custb_name



END
GO







CREATE PROCEDURE [dbo].[spCustomerBranch_getComboAll]
(
	@comp_id			INT
)
AS
SET NOCOUNT ON


SELECT 		tcb.cb_id						[id],
			CASE WHEN LEN(tc.cust_name) > 30 THEN SUBSTRING(tc.cust_name,0,30) + '...' ELSE tc.cust_name END
			+ ' - ' + tcb.custb_name		[desc]

FROM 		tbCustomerBranch				tcb    WITH (NOLOCK)
			INNER JOIN tbCustomer			tc      WITH (NOLOCK)
			ON	tc.comp_id = tcb.comp_id
			AND tc.cust_id = tcb.cust_id

WHERE 		tcb.comp_id =	@comp_id

ORDER BY	tc.cust_name, tcb.custb_name
GO




