CREATE PROCEDURE [dbo].[spCustomerBranch_GetDataById]
(
	@comp_id			int	,
	@cust_id			int	,
	@cb_id				int
)

AS

BEGIN



	set nocount on

	select		cb_id		[id],
				custb_name	[name],
				cb.*,
				ISNULL(ts.state_desc,'')				[state_desc],
				ISNULL(ts.state_EnvioPackID,'')			[state_EnvioPackID]

		from		dbo.tbCustomerBranch cb	WITH (NOLOCK)
		LEFT JOIN	tbsysState ts			WITH (NOLOCK)
			ON	ts.country_id	= cb.country_id AND
				ts.state_id		= cb.state_id

		where		cb.comp_id =	@comp_id
				and	cb.cust_id =   @cust_id
				AND cb.cb_id   =	@cb_id



END












GO









