CREATE PROCEDURE [dbo].[spCustomerBranch_Process_Auto]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cust_id					INT,
	@custb_name					NVARCHAR(100),
	@custb_address				NVARCHAR(150),
	@custb_city					NVARCHAR(60),
	@custb_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@custb_phone1				NVARCHAR(200),
	@custb_phone2				NVARCHAR(200),
	@custb_email				NVARCHAR(300),
	@custb_fax					NVARCHAR(200),
	@ss_id						INT,
	@custb_contact				NVARCHAR(200),
	@custb_shortname			NVARCHAR(50),
	@sm_id						INT,
	@dl_id						INT,
	@bra_id_disabled			INT,
	@prof_id_filter				INT,

	@custb_migrationID			NVARCHAR(30),
	@st_id						INT,
	@prli_id					INT,
	@disc_id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT




)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cust_id					INT,
	@custb_name					NVARCHAR(100),
	@custb_address				NVARCHAR(150),
	@custb_city					NVARCHAR(60),
	@custb_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@custb_phone1				NVARCHAR(200),
	@custb_phone2				NVARCHAR(200),
	@custb_email				NVARCHAR(300),
	@custb_fax					NVARCHAR(200),
	@ss_id						INT,
	@custb_contact				NVARCHAR(200),
	@custb_shortname			NVARCHAR(50),
	@sm_id						INT,
	@dl_id						INT,
	@bra_id_disabled			INT,
	@prof_id_filter				INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT

SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,

	@item_code					='1637 hs999',
	@cat_id						= 40 ,
	@subcat_id					= 3823 ,
	@subcataux_id				= -1 ,
	@ic_id						= 2  ,
	@item_desc					='desc',
	@item_detail				='detail',
	@item_vendorCode			='vendor code',
	@brand_id					= 75 ,
	@pres_id					= 69,
	@item_codeAlternative		='alternative code',
	@curr_id					= 1,
	@supp_id					= 8110 ,
	@item_trigger_tax_id		= 1,
	@item_upb					= 1,
	@item_upp					= 1,
	@item_mult					= 1,
	@item_commission			= 1,
	@item_commission_byReceive  = 1,
	@item_liquidation			= 1,
	@item_newness				= 0,
	@item_outlet				= 0,
	@item_expser				= 0,
	@item_expean				= 1,
	@item_disabled				= 0,
	@item_comboDisc_Cant1		= 1,
	@item_comboDisc_Cant2		= 1,
	@item_comboDisc_Disc1		= 1,
	@item_comboDisc_Disc2		= 1,
	@item_purOrd_Disc1			= 1,
	@item_purOrd_Disc2			= 1,
	@item_purOrd_Disc3			= 1,
	@item_markup_1				= 0,
	@item_markup_2				= 0,
	@item_markup_3				= 0,
	@item_markup_4				= 0,
	@item_markup_5				= 0,
	@item_markup_6				= 0,
	@item_markup_7				= 0,
	@item_markup_8				= 0,
	@item_annotation1			='anotation1',
	@item_annotation2			='',
	@item_WebSite_desc			='',
	@item_WebSite_vendorPage	='',
	@item_WebSite_vendorDrivers	='@item_WebSite_vendorDrivers',
	@item_WebSite_url4Image1	='@item_WebSite_url4Image1',
	@item_WebSite_url4Image2	='@item_WebSite_url4Image2',
	@item_WebSite_url4Image3	='@item_WebSite_url4Image3',
	@item_WebSite_url4Image4	='@item_WebSite_url4Image4',
	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 10

*/
---------------------------------------------------------------------------------

SET NOCOUNT ON
SET DATEFORMAT 'YMD'


BEGIN
	declare @return_value	INT


	IF NOT EXISTS (SELECT tb.bra_id
	               FROM tbBranch tb		WITH (NOLOCK)
		               WHERE tb.comp_id		= @comp_id and
		               		 tb.bra_id		= @bra_id_disabled)
			BEGIN
				SET	@bra_id_disabled	= -1
			END

	IF NOT EXISTS (SELECT tb.prof_id
	               FROM tbProfile tb	WITH (NOLOCK)
		               WHERE tb.comp_id		= @comp_id and
		               		 tb.prof_id		= @prof_id_filter)
			BEGIN
				SET	@prof_id_filter	= -1
			END

	IF NOT EXISTS (SELECT tb.st_id
	               FROM tbSalesTerms tb	WITH (NOLOCK)
		               WHERE tb.comp_id		= @comp_id and
		               		 tb.st_id		= @st_id)
			BEGIN
				SET	@st_id	= -1
			END

	IF NOT EXISTS (SELECT tb.prli_id
	               FROM tbPriceList  tb	WITH (NOLOCK)
		               WHERE tb.comp_id		= @comp_id and
		               		 tb.prli_id		= @prli_id)
			BEGIN
				SET	@prli_id	= -1
			END

	IF NOT EXISTS (SELECT tb.dl_id
	               FROM tbDelivery tb WITH (NOLOCK)
		               WHERE tb.comp_id		= @comp_id and
		               		 tb.dl_id		= @dl_id)
			BEGIN
				SET	@dl_id	= -1
			END

	IF NOT EXISTS (SELECT tb.disc_id
	               FROM tbDiscount tb WITH (NOLOCK)
		               WHERE tb.comp_id		= @comp_id and
		               		 tb.disc_id		= @disc_id)
			BEGIN
				SET	@disc_id	= -1
			END


	if	@bra_id_disabled		= -1  SET @bra_id_disabled	= NULL
	if	@prof_id_filter			= -1  SET @prof_id_filter	= NULL
	if	@st_id					= -1  SET @st_id			= NULL
	if	@prli_id				= -1  SET @prli_id			= NULL
	if	@dl_id					= -1  SET @dl_id			= NULL
	if	@disc_id				= -1  SET @disc_id			= NULL

				BEGIN TRY

					INSERT INTO tbCustomerBranch
					(
						comp_id,
						cust_id,
						custb_name,
						custb_address,
						custb_city,
						custb_zip,
						custb_Phone1,
						custb_Phone2,
						custb_email,
						custb_fax,
						custb_contact,
						ss_id,
						custb_shortname,
						country_id,
						state_id,
						sm_id,
						bra_id_Disabled,
						prof_id,
						dl_id,
						custb_migrationID,
						st_id,
						prli_id,
						disc_id
					)
					VALUES
					(
						@comp_id,
						@cust_id,
						@custb_name,
						@custb_address,
						@custb_city,
						@custb_zip,
						@custb_Phone1,
						@custb_Phone2,
						@custb_email,
						@custb_fax,
						@custb_contact,
						@ss_id,
						@custb_shortname,
						@country_id,
						@state_id,
						@sm_id,
						@bra_id_Disabled,
						@prof_id_filter,
						@dl_id,
						@custb_migrationID,
						@st_id,
						@prli_id,
						@disc_id
					)



						set	@return_value = IDENT_CURRENT('tbCustomerBranch')   -- @@identity

					END TRY
					BEGIN CATCH
						set	@return_value = 0
					END CATCH

					IF @return_value <> 0
						BEGIN
							--EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,@return_value,NULL

							EXEC [spSysScript_CustomerBranch_Cities]


						END



END


















GO





