--------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spCustomerBranch_Process_Auto_Validate]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cust_id					INT,
	@custb_name					NVARCHAR(100),
	@custb_address				NVARCHAR(150),
	@custb_city					NVARCHAR(60),
	@custb_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@ss_id						INT,
	@sm_id						INT,
	@dl_id						INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT




)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cust_id					INT,
	@custb_name					NVARCHAR(100),
	@custb_address				NVARCHAR(150),
	@custb_city					NVARCHAR(60),
	@custb_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@ss_id						INT,
	@sm_id						INT,
	@dl_id						INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------

SET NOCOUNT ON
SET DATEFORMAT 'YMD'

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''



	------CLIENTE-----------------------------------------------------------------------------------------------------------
	if	@cust_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Cliente'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT	tc.cust_id
			               FROM		tbCustomer		tc		WITH (NOLOCK)
			               WHERE	tc.comp_id		= @comp_id AND
									tc.cust_id		= @cust_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Cliente es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Nombre de la sucursal del cliente-----------------------------------------------------------------------------------------------------------
	if	@custb_name	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Nombre de la Sucursal del Cliente'
		END
	-----------------------------------------------------------------------------------------------------------------------


	------Domicilio-----------------------------------------------------------------------------------------------------------
	if	@custb_address	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Domicilio'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Localidad-----------------------------------------------------------------------------------------------------------
	if	@custb_city	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó la Localidad'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Pais-----------------------------------------------------------------------------------------------------------
	if	@country_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID País'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.country_id
			   FROM tbsysCountry		tc		WITH (NOLOCK)
							WHERE	tc.country_id		= @country_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de País es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Provincia-----------------------------------------------------------------------------------------------------------
	if	@state_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Provincia'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.state_id
			               FROM tbsysState 	tc		WITH (NOLOCK)
			               WHERE tc.country_id = @country_id and
			               		 tc.state_id   = @state_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Provincia es incorrecto o no está relacionada al País'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Sector de Ventas -----------------------------------------------------------------------------------------------------------
	if	@ss_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Sector de Venta'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tck.ss_id
			               FROM tbSaleSector   tck		WITH (NOLOCK)
			               WHERE tck.comp_id		= @comp_id and
			               		 tck.ss_id			= @ss_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Sector de Venta es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Vendedor-----------------------------------------------------------------------------------------------------------
	if	@sm_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Vendedor'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tck.sm_id
			               FROM tbSalesman  tck		WITH (NOLOCK)
			               WHERE tck.comp_id		= @comp_id and
			               		 tck.sm_id			= @sm_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Vendedor es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------


	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO



----------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Date   : 27/04/17
-- Author : GA
-- Detail : Al finalizar el proceso de importacion se muestra en una grilla que registros fueron dados de alta y los que no.
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
create PROCEDURE [dbo].[spCustomerBranch_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN



	SELECT
			isnull(tc.custb_name,'')								[cust_name],
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbCustomerBranch 							tc		WITH (NOLOCK)
		ON	tc.comp_id		= tpclil.comp_id	AND
			tc.cb_id		= tpclil.item_id

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO







