create PROCEDURE [dbo].[spCustomerFamily_getDataById]
(
	@comp_id			INT,
	@custf_id			INT
)
AS



BEGIN



	-- ----------------------------------------------------
	-- Testing
	-- ----------------------------------------------------
/*
	DECLARE @comp_id			INT,
			@custf_id			INT

	SELECT 	@comp_id			=1,
			@custf_id			=20
*/
	-- ----------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	SELECT	*,
			c.custf_address + ' ' + c.custf_city + ' ' + c.custf_zip + ' ' + tc.country_desc	[custf_address4Deliverycomplet]


	FROM 	dbo.tbCustomerFamily					c			WITH (NOLOCK)

