CREATE PROCEDURE [dbo].[spCustomerFamily_getFamilyByCustomer]
(
	@comp_id	INT,
	@cust_id	INT
)
AS

	SET NOCOUNT ON

		BEGIN

			-- ----------------------------------
			-- TESTING
			-- ----------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@cust_id	INT
				SELECT
					@comp_id	= 1,
					@cust_id	= 24294
			*/
			-- ----------------------------------

			SELECT
				tcf.custf_id,
				tc2.cust_name,
				isnull(tcf.custf_name,'') [custf_name],											-- 1
				ttnt.tnt_desc,																	-- 2
				isnull(tcf.custf_taxNumber,'') [custf_taxNumber],								-- 3
				isnull(tcf.custf_address,'') [custf_address],									-- 4
				tc.country_desc,
				ts.state_desc,
				tsc.city_desc,																	-- 5
				isnull(tcf.custf_city,'')							[custf_city],				-- 6
				isnull(tcf.custf_zip,'')							[custf_zip],				-- 7
				isnull(tcf.custf_birthDay,'')						[custf_birthDay],			-- 8
				isnull(tcs.street_desc,'')							[street_desc],				-- 9
				isnull(tcf.cust_addressNumber,'')					[cust_addressNumber],		--10
				isnull(tcf.custf_addressFloor,'')					[custf_addressFloor],		--11
				isnull(tcf.custf_addressAdditional,'')				[custf_addressAdditional],	--12
				isnull(tcms.marst_desc,'')							[marst_desc],				--13
				isnull(tccr.rating_desc,'')							[rating_desc],				--14
				tcf.custf_picture,																--15
				ISNULL(tcf.custf_cellPhone,'')						[custf_cellPhone],
				tcf.cust_id
			FROM tbCustomerFamily						tcf			WITH (NOLOCK)
				INNER JOIN tbsysCountry					tc			WITH (NOLOCK)
				ON tc.country_id	= tcf.country_id
				INNER JOIN tbsysState					ts			WITH (NOLOCK)
				ON	ts.country_id	= tcf.country_id	AND
					ts.state_id		= tcf.state_id
				INNER JOIN vwCities						tsc				WITH (NOLOCK)
				ON	tsc.country_id	= ts.country_id		AND
					tsc.state_id	= ts.state_id		AND
					tsc.city_id		= tcf.city_id
				INNER JOIN tbCustomerMaritalStatus		tcms			WITH (NOLOCK)
				ON	tcms.comp_id	= tcf.comp_id		AND
					tcms.marst_id	= tcf.marst_id
				INNER JOIN tbCustomerCreditRating		tccr			WITH (NOLOCK)
				ON	tccr.comp_id	= tcf.comp_id		AND
					tccr.rating_id	= tcf.rating_id
				INNER JOIN tbCustomer					tc2				WITH (NOLOCK)
				ON	tc2.comp_id		= tcf.comp_id		AND
					tc2.cust_id		= tcf.cust_id
				INNER JOIN tbsysTaxNumberTypes			ttnt			WITH (NOLOCK)
				ON	ttnt.tnt_id		= tcf.tnt_id
				LEFT JOIN tbCities_Streets				tcs				WITH (NOLOCK)
				ON	tcs.comp_id		= tcf.comp_id		AND
					tcs.country_id	= tcf.country_id	AND
					tcs.state_id	= tcf.state_id		AND
					tcs.street_id	= tcf.street_id
			WHERE	tcf.comp_id			= @comp_id		AND
					tcf.cust_id			= @cust_id		AND
					tcf.custf_inactive	= 'False'

		END


GO

