-- MOS: 09-2010

CREATE PROCEDURE [dbo].[spCustomerFilterByUser_existsData]
(
	@comp_id		INT,
	@user_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@return_value	INT OUTPUT
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON


	IF (
			SELECT IsNull(tb.bra_SaleOrderFilterByUserId,'False')
				FROM tbBranch tb
				WHERE	tb.comp_id	= @comp_id
					AND tb.bra_id	= @bra_id
		) = 'True'
		and EXISTS (
					SELECT  TOP 1 1
						FROM	tbCustomerFilterByUser tcfbu
						WHERE	tcfbu.comp_id	= @comp_id
						AND		tcfbu.[user_id] = @user_id
				   )
		BEGIN
			SET @return_value = 1
			RETURN
		END

	ELSE IF EXISTS(	SELECT TOP 1 1
	               		FROM tbSaleOrderFilterByUser tt
	               		WHERE	tt.comp_id		= @comp_id	AND
	               				tt.bra_id		= @bra_id	AND
	               				tt.[user_id]	= @user_id	AND
	               				tt.prof_id		= @prof_id
					)
		BEGIN
			SET @return_value = 1
			RETURN
		END
	ELSE
		BEGIN
			SET @return_value = 0
			RETURN
		END


END
GO






-- --------------------------------------------------
-- MOS   Parte 460
-- --------------------------------------------------
-- Este SP decide que vendedor asignara al pedido
-- 05-2012: Se cambio de la tabla spCustomerFilterByUser a la tabla tbUserSalesmanRelation
--          para que funcione tambien con los Gerentes, que no tienen filtro asignado de clientes x usuario
--			pero si tienen relacion de Usuario-Vendedor.

CREATE PROCEDURE [dbo].[spCustomerFilterByUser_getDataByUser]
(
	@comp_id			INT,
	@bra_id				INT,
	@user_id			INT,
	@cust_id			INT
)

AS



BEGIN

	SET NOCOUNT ON


-- ---------------------------------------------------------------
-- Testing
-- ---------------------------------------------------------------
/*
	DECLARE @comp_id				INT,
			@bra_id					INT,
			@user_id				INT,
			@cust_id				INT


	SELECT	@comp_id				= 1,
			@bra_id					= 86,
			@user_id				= 67,
			@cust_id				=24288
*/
-- ---------------------------------------------------------------

	DECLARE @intSm_Id_Original	INT

	-- variable @intSm_Id_Original = el vendedor del cliente
	SELECT @intSm_Id_Original =	tc.sm_id
		FROM tbCustomer tc
		WHERE	tc.comp_id = @comp_id
			AND tc.cust_id = @cust_id


	-- Si en sucursal dice que debe forzar al vendedor que tiene cargado el cliente
	IF (SELECT ISNULL(tb.bra_SaleOrderForceCustomerSalesman,'False' )
			FROM tbBranch tb
	  		WHERE	tb.comp_id	= @comp_id
	  			AND tb.bra_id	= @bra_id
		) = 'True'
		BEGIN
			SELECT @intSm_Id_Original
			RETURN
		END


	-- Saco en una temporal los Vendedores ACTIVOS relacionados al usuario actual
	DECLARE @tblMySalesman AS TABLE(comp_id	INT,sm_id INT)
	INSERT INTO @tblMySalesman(comp_id, sm_id)
	SELECT	ts.comp_id,
			ts.sm_id
		FROM tbUserSalesmanRelation tusr
		INNER JOIN vwSalesmanEnabled ts
			ON		ts.comp_id	= @comp_id
				AND	ts.sm_id	= tusr.sm_id
	WHERE	tusr.comp_id					= @comp_id
		and tusr.bra_id						= @bra_id
		AND tusr.[user_id]					= @user_id
		AND IsNull(ts.sm_disabled,'False')	= 'False'


	--SELECT * FROM @tblMySalesman


	-- Si el vendedor PERTENECE a un vendedor asignado a mi usuario no hago nada, sino, ...
	IF  NOT EXISTS (select 1
						FROM  @tblMySalesman ms
						WHERE ms.sm_id = @intSm_Id_Original )

		BEGIN

			-- Verifico si el usuario tienen algun vendedor en su mismo grupo,
			-- de ser asi se mantiene el vendedor asignado al cliente.-
			-->>
			IF  NOT EXISTS (

							-- Para que se entienda lo hacemos paso a paso
							-- 1 obtengo los grupos de vendedores a los que yo pertenezco
							select	sg.comp_id,
									sg.sg_id
								FROM	tbSalesmanGroup4Salesman sg
								CROSS JOIN @tblMySalesman tcfbu
								where	sg.comp_id		= @comp_id
									AND	sg.sm_id		= tcfbu.sm_id
									AND EXISTS(
												-- 2 obtengo  los grupos de vendedores a los que pertenece el vendedor original.
												select	sg.comp_id,
														sg.sg_id
													FROM	tbSalesmanGroup4Salesman sg1
													where	sg1.comp_id		= @comp_id
														and	sg1.sm_id		= @intSm_Id_Original
														AND sg1.sg_id       = sg.sg_id
											)



							)
				-- 3 si coincidimos en alguno, el vendedor queda como esta originalmente
				-- 4 si NO coincidimos en ninguno entonces se pasa al primer vendedor asignado a mi usuario en la sucursal actual.


				BEGIN
					-- De NO ser asi, se asigna como vendedor a algun vendedor asignado al usuario Actual.
					SELECT TOP 1 @intSm_Id_Original = cfbu.sm_id
						FROM @tblMySalesman cfbu

				END

		END

	SELECT @intSm_Id_Original

END
GO





