CREATE PROCEDURE [dbo].[spCustomerGuarrantor_getComboByCustomer]
(
	@comp_id	INT,
	@cust_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN

			SELECT
				tcf.cust_id					[ID],
				CASE
					WHEN tcf.custg_isOccasional = 'True' THEN	'(O) '
					ELSE										'(P) '
				END	 +
				tc.cust_name				[Desc]
				FROM tbCustomerGuarantorOf 	tcf				WITH (NOLOCK)
				INNER JOIN tbcustomer	tc					WITH (NOLOCK)
					ON	tc.comp_id = tcf.comp_id AND
						tc.cust_id = tcf.cust_id
				WHERE	tcf.comp_id				= @comp_id	AND
						tcf.cust_id_guaranteed	= @cust_id	AND
						tcf.ciw_disabled		= 'False'

		END

GO



