------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: Informe de Credito
------------------------------------------------------------------------------------------------------


CREATE procedure [dbo].[spCustomerInfo_CreditBehavior_GeneralInfo_GetdataByFilters]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

)
as
SET NOCOUNT ON

----------------------------------------------------------
--PARAMETROS DE PRUEBA
----------------------------------------------------------
/*
  DECLARE @comp_id		AS INT,
		  @lang_id		AS INT,
		  @cust_id		AS INT


  SELECT  @comp_id		= 1,
		  @lang_id		= 2,
		  @cust_id		= 24294
*/
----------------------------------------------------------
----------------------------------------------------------



  BEGIN


			SELECT  tov.optval_desc													[cis_isAlert],
					tcbgi.ci_dateBegin												[ci_dateBegin],
					tcbgi.ci_dateEnd												[ci_dateEnd],
					tcbgi.ci_desc													[ci_desc],
					tcbgi.ci_note													[ci_note],
					tcbs.cis_desc													[cis_desc],
					tcbt.cit_desc													[cit_desc],
					tcbgi.ci_id														[ID]


			FROM tbCreditBehavior_GeneralInfo							tcbgi		WITH (NOLOCK)

			INNER JOIN tbCreditBehavior_Status							tcbs		WITH (NOLOCK)
			ON	tcbs.comp_id		= tcbgi.comp_id		AND
				tcbs.cis_id			= tcbgi.cis_id

			INNER JOIN tbCreditBehavior_Types							tcbt		WITH (NOLOCK)
			ON  tcbt.comp_id		= tcbgi.comp_id		AND
				tcbt.cit_id			= tcbgi.cit_id

			INNER JOIN tbCustomer										tc			WITH (NOLOCK)
			ON	tc.comp_id			= tcbgi.comp_id		AND
				tc.cust_id			= tcbgi.cust_id

			INNER JOIN tbsysOptionsValues								tov			WITH (NOLOCK)
			on  tov.optval_class	= 137
			and tov.lang_id			= @lang_id
			and tov.optval_id		= tcbs.cis_isAlert


		   WHERE tcbgi.comp_id				 = @comp_id		AND
				 tc.cust_id					 = @cust_id



		   ORDER BY tcbs.cis_isAlert desc,
					tcbgi.ci_dateBegin desc








END
GO



