--Author:GA
--Desc:  Credit Rating
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spCustomerInfo_CreditRating_GetdataByFilters]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

)
as
SET NOCOUNT ON

----------------------------------------------------------
--PARAMETROS DE PRUEBA
----------------------------------------------------------
/*
  DECLARE @comp_id		AS INT,
		  @lang_id		AS INT,
		  @cust_id		AS INT


  SELECT  @comp_id		= 1,
		  @lang_id		= 2,
		  @cust_id		= 24294
*/
----------------------------------------------------------
----------------------------------------------------------



  BEGIN

			SELECT	ISNULL(tccr.rating_desc,'')								[rating_desc],
					ISNULL(tc.rating_id_cd,GETDATE())						[rating_id_cd],
					ISNULL(tccrPre.rating_desc,'')							[rating_previous_desc],
					ISNULL(tccr.rating_AlertOnInfo,'False')					[rating_AlertOnInfo]

			FROM	tbCustomer												tc			WITH (NOLOCK)

			INNER JOIN tbCustomerCreditRating								tccr		WITH (NOLOCK)
				ON tc.comp_id					= tccr.comp_id			AND
				   tc.rating_id					= tccr.rating_id

			LEFT JOIN tbCustomerCreditRating								tccrPre		WITH (NOLOCK)
				ON tc.comp_id					= tccrPre.comp_id		AND
				   tc.rating_id_previous		= tccrPre.rating_id


			 WHERE	tc.comp_id				 = @comp_id		AND
					tc.cust_id				 = @cust_id

			ORDER BY tccr.rating_desc desc,tc.rating_id_cd desc








END
GO



------------------------------------------------------------------------------------------------------
--Date:
--Author:MOS
--Desc: customer info - Mora Maxima
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spCustomerInfo_CreditRating_LoanMora]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

)
AS

  BEGIN

/*
	DECLARE @comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

	SELECT @comp_id	= 1,
	@lang_id	= 2 ,
	@cust_id	=24294
*/
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON


	SELECT MAX(
				CASE
					WHEN tctl.comp_id IS NULL THEN	tct.ctl_daysPastDue
					ELSE							tctl.ctl_daysPastDue
				END
			  ) [MoraDays]
		FROM tbCommercialTransactions tct
		INNER JOIN vwCommercialTransactions_forSales vctfs		WITH (NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id AND
				--vctfs.bra_id			= tct.bra_id AND
				vctfs.ct_transaction	= tct.ct_transaction
		LEFT JOIN tbCommercialTransactionsLoan tctl			WITH (NOLOCK)
			ON	tctl.comp_id		= tct.comp_id			AND
				tctl.ct_transaction = tct.ct_transaction

		WHERE	tct.comp_id = @comp_id	AND
				tct.cust_id = @cust_id	AND
				--tct.sd_id = 1			AND
				--tct.sd_id	<> 5		AND		-- Excluye Presupuestos 13/12/16 GA
				vctfs.sd_isInBalance	= 'True'	AND
				vctfs.sd_isCredit		= 'False'	AND
				vctfs.sd_isReceipt		= 'False'	AND
				CASE
					WHEN tctl.comp_id IS NULL THEN	tct.ct_ABalance
					ELSE							tctl.ct_ABalance
				END	<> 0
		GROUP BY tct.cust_id


END
GO





