CREATE procedure [dbo].[spCustomerInfo_DefaultLevel]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

)
AS

  BEGIN

	----------------------------------------------------------
	--PARAMETROS DE PRUEBA
	----------------------------------------------------------
	/*
	  DECLARE	@comp_id	INT,
				@lang_id	INT,
				@cust_id	INT


	  SELECT	@comp_id		= 1,
				@lang_id		= 2,
				@cust_id		= 24294
*/
	----------------------------------------------------------
	----------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON


	SELECT
		tcdl.def_desc							[def_desc],
		tovdisabled.optval_desc					[def_disabled],
		isnull(tcdl.def_isAlert,'False')		[def_isAlert]

		FROM tbCustomer												tc				WITH (NOLOCK)

		inner join tbCustomerDefaultLevel							tcdl			WITH (NOLOCK)
		ON	tcdl.comp_id					= tc.comp_id
		AND tcdl.def_id						= tc.def_id

		inner join tbsysOptionsValues								tovdisabled		WITH (NOLOCK)
		on  tovdisabled.optval_class		= 137 -- Si o No
		and tovdisabled.lang_id				= @lang_id
		and tovdisabled.optval_id			= isnull(tcdl.def_disabled,'False')

--		inner join tbsysOptionsValues								tovisAlert		WITH (NOLOCK)
--		on  tovisAlert.optval_class			= 137 -- Si o No
--		and tovisAlert.lang_id				= @lang_id
--		and tovisAlert.optval_id			= isnull(tcdl.def_isAlert,'False')
--

		WHERE	tc.comp_id = @comp_id	AND
				tc.cust_id = @cust_id


END
GO



