CREATE procedure [dbo].[spCustomerInfo_getData_InvoicesPending]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT,
	@prof_id	INT,
	@user_id	INT

)
as
SET NOCOUNT ON


----------------------------------------------------------
--PARAMETROS DE PRUEBA
----------------------------------------------------------

/*

  DECLARE @comp_id		AS INT,
		  @lang_id		AS INT,
		  @cust_id		AS INT,
		  @prof_id		AS INT



  SELECT  @comp_id		= 1,
		  @lang_id		= 2,
		  @cust_id		= 24294,
		  @prof_id		= 1


*/


----------------------------------------------------------
----------------------------------------------------------



  BEGIN


			SELECT  tct.ct_date																				[ct_date],
					tct.ct_payDate																			[ct_payDate],
					dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)		[ct_transaction],
					convert(decimal(19,2),tct.ct_ATotal)	* vwct.PlusOrMinus												[ct_ATotal],
					tc.curr_desc																			[curr_desc],
					convert(decimal(19,2),tct.ct_ABalance)	* vwct.PlusOrMinus								[ct_ABalance]

			FROM tbCommercialTransactions								tct			WITH (NOLOCK)


			INNER join vwCommercialTransactions_forSales				vwct		WITH (NOLOCK)
			on  vwct.comp_id					=	tct.comp_id
			and vwct.bra_id						=	tct.bra_id
			and vwct.ct_transaction				=	tct.ct_transaction


			inner JOIN tbUsers4BranchFilter 							tucp		WITH (NOLOCK)
			ON	tucp.comp_id					=	tct.comp_id
			AND tucp.bra_id						=	tct.bra_id
			AND	tucp.[user_id]					=	@user_id


			LEFT JOIN tbsysCurrency										tc			WITH (NOLOCK)
			ON	 tc.curr_id						= tct.ct_ACurrency


			WHERE	tct.comp_id			= @comp_id				AND
					tct.cust_id			= @cust_id				AND
					tct.ct_ABalance		<> 0
			--		tct.sd_id			<> 5					-- Excluye Presupuestos 13/12/16 GA



			ORDER BY tct.ct_payDate



END
GO



