--Author:GA
--Desc: customer info - cuotas pendientes que el cliente esta GARANTIZANDO Actualmente.
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spCustomerInfo_getData_LoanByGuarantorOf]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

)
as
SET NOCOUNT ON

----------------------------------------------------------
--PARAMETROS DE PRUEBA
----------------------------------------------------------
/*
  DECLARE @comp_id		AS INT,
		  @lang_id		AS INT,
		  @cust_id		AS INT


  SELECT  @comp_id		= 1,
		  @lang_id		= 2,
		  @cust_id		= 24294
*/
----------------------------------------------------------
----------------------------------------------------------



  BEGIN


			SELECT  tctl.ctl_payNumber									[ctl_payNumber],
					tctl.ctl_payDate									[ctl_payDate],
					tctl.ct_ATotal										[ct_ATotal],
					tctl.ct_ABalance									[ct_ABalance],
					tc.curr_desc										[curr_desc],
					tc2.cust_name										[cust_name],
					tcf.custf_name										[custf_name],
					tctl.ctl_payDateUpdateDate							[ctl_payDateUpdateDate],
					isnull(tctl.ctl_daysPastDue,0)						[ctl_daysPastDue]

			FROM tbCommercialTransactions								tct			WITH (NOLOCK)

			INNER JOIN tbCommercialTransactionsLoan						tctl		WITH (NOLOCK)
			ON  tctl.comp_id			= tct.comp_id			AND
				tctl.ct_transaction		= tct.ct_transaction

			INNER JOIN tbcustomer										tc2			WITH (NOLOCK)
			ON   tct.comp_id			= tc2.comp_id			AND
				 tct.cust_id			= tc2.cust_id

			LEFT JOIN tbCustomerFamily tcf											WITH (NOLOCK)
				ON	tcf.comp_id			= tct.comp_id AND
					tcf.cust_id			= tct.cust_id AND
					tcf.custf_id		= tct.custf_id

			INNER JOIN tbsysCurrency									tc			WITH (NOLOCK)
			ON	 tc.curr_id				= tctl.curr_id



		   WHERE tct.comp_id			= @comp_id				AND
				tct.cust_id_guarantor	= @cust_id





END
GO



------------------------------------------------------------------------------------------------------
--Date: 31/12/14
--Author:GA
--Desc: customer info - cuotas pendientes agrupadas por fecha de pago
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spCustomerInfo_getData_LoanByPaymentDate]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

)
AS

  BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON

----------------------------------------------------------
--PARAMETROS DE PRUEBA
----------------------------------------------------------
/*
  DECLARE @comp_id		AS INT,
		  @lang_id		AS INT,
		  @cust_id		AS INT


  SELECT  @comp_id		= 1,
		  @lang_id		= 2,
		  @cust_id		= 24454
*/
----------------------------------------------------------
----------------------------------------------------------






			SELECT  --' '													[ ],
					convert(varchar(4),Isnull(tctl.ctl_payNumber,0)) + ' / '	+ convert(varchar(4),IsNull(tctl.ctl_payNumberTotalQty,0) )	[ctl_payNumber],
					tctl.ctl_payDate																					[ctl_payDate],
					dbo.fnGetCommercialTransactionDescription(tct.comp_id,2,tct.ct_transaction)							[DFDesc],
					tctl.ct_ATotal	+
					CASE
						WHEN tctr.comp_id IS NOT NULL						THEN (	SELECT tctl2.ct_ATotal
																						FROM	tbCommercialTransactionsLoan tctl2
																						WHERE	tctl2.comp_id			= tctr.comp_id AND
						                                                           				tctl2.ct_transaction	= tctr.ct_transaction_2  AND
						                                                           				tctl2.ctl_payNumber		= tctl.ctl_payNumber
																				 )
						ELSE														0
					END													[ct_ATotal],
					tctl.ct_ABalance 	+
					CASE
						WHEN tctr.comp_id IS NOT NULL						THEN (	SELECT tctl2.ct_ABalance
																						FROM	tbCommercialTransactionsLoan tctl2
																						WHERE	tctl2.comp_id			= tctr.comp_id AND
						                                                           				tctl2.ct_transaction	= tctr.ct_transaction_2  AND
						                                                           				tctl2.ctl_payNumber		= tctl.ctl_payNumber
																				 )
						ELSE														0
					END													[ct_ABalance],
					CASE
						WHEN tctl.ctl_payDate > dbo.fnGetEnd_or_BeginOfDate(GETDATE(),'True') THEN 0
						WHEN tctl.ct_ATotal = tctl.ct_ABalance	THEN	isnull(tctl.ctl_daysPastDue,0)
						WHEN tctl.ct_ATotal = 0					THEN	isnull(tctl.ctl_daysPastDue,0)
						ELSE isnull(tctl.ctl_daysPastDue,0)
					END													[ctl_daysPastDue],
					tcf.custf_name,
					custg.cust_name										[Guarrantor],
					tu.user_lastname + ',' + tu.user_firstname			[ctl_payDateUpdateUser],
					tctl.ctl_payDateUpdateDate							[ctl_payDateUpdateDate],
					tctl.ctl_lastPayDate,
					tct.ct_transaction									[ID]



			FROM tbCommercialTransactions								tct			WITH (NOLOCK)

			INNER join vwCommercialTransactions_forSales				vwct		WITH (NOLOCK)
				on  vwct.comp_id					=	tct.comp_id
				and vwct.bra_id						=	tct.bra_id
				and vwct.ct_transaction				=	tct.ct_transaction

			INNER JOIN tbCommercialTransactionsLoan						tctl		WITH (NOLOCK)
			ON  tctl.comp_id			= tct.comp_id			AND
				tctl.ct_transaction		= tct.ct_transaction

			INNER JOIN tbcustomer										tc2			WITH (NOLOCK)
			ON   tct.comp_id			= tc2.comp_id			AND
				 tct.cust_id			= tc2.cust_id

			left JOIN tbCustomerFamily tcf											WITH (NOLOCK)
			ON	tcf.comp_id		= tct.comp_id AND
				tcf.cust_id		= tct.cust_id AND
				tcf.custf_id	= tct.custf_id

			LEFT JOIN tbcustomer custg												WITH (NOLOCK)
				ON	custg.comp_id = tct.comp_id AND
					custg.cust_id = tct.cust_id_guarantor


			INNER JOIN tbsysCurrency									tc			WITH (NOLOCK)
			ON	 tc.curr_id				= tctl.curr_id


			INNER JOIN tbDocumentsFile tdf											WITH (NOLOCK)
			ON	tdf.comp_id = tct.comp_id	AND
				tdf.bra_id	= tct.bra_id	AND
				tdf.df_id	= tct.df_id

			LEFT JOIN tbCommercialTransactions_Relations tctr						WITH (NOLOCK)
				ON	tctr.comp_id			= tct.comp_id			AND
					tctr.ct_transaction_1	= tct.ct_transaction	AND
					tctr.class				= 2   -- Financiacion de Terceros

			LEFT JOIN tbUser											tu			WITH(NOLOCK)
			ON	tu.[user_id]				= tctl.ctl_payDateUpdateUser


		   WHERE tct.comp_id							= @comp_id	AND
				 tct.cust_id							= @cust_id	AND
				 tdf.df_3rdSales_isDebitNoteDocument	= 'False'


			--GROUP BY tct.ct_payDate,
			--		ctl_payNumber,
