------------------------------------------------------------------------------------------------------
--Date: 19/01/15
--Author:GA/MOS
--Desc: customer info - Historial de Cuotas
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spCustomerInfo_getData_LoanHistory]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

)
as



	----------------------------------------------------------
	--PARAMETROS DE PRUEBA
	----------------------------------------------------------
	/*
	  DECLARE @comp_id		AS INT,
			  @lang_id		AS INT,
			  @cust_id		AS INT


	  SELECT  @comp_id		= 1,
			  @lang_id		= 2,
			  @cust_id		= 24454

	*/
	----------------------------------------------------------



  BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SET NOCOUNT ON

	DECLARE @tmpTable TABLE([Month] NVARCHAR(10),
							[ct_ATotal_his] DECIMAL(19,2),
							[AcumTotal] DECIMAL(19,2),
							[ct_ABalance_his] DECIMAL(19,2),
							[AcumBalance] DECIMAL(19,2),
							--[AVGPastDue] DECIMAL(19,2),
							[Id] INT IDENTITY (1,1))


	 INSERT INTO @tmpTable ([Month],
							ct_ATotal_his,
							AcumTotal,
							ct_ABalance_his,
							AcumBalance)
							--AVGPastDue)

		SELECT
			CONVERT(varchar, MONTH(tctl.ctl_payDate))+ ' - ' + CONVERT(varchar, YEAR(tctl.ctl_payDate)) [Month],
			SUM(tctl.ct_ATotal * vctfs.PlusOrMinus)															[ct_ATotal_his],
			CONVERT(decimal(19,2),0)																		[AcumTotal],
			SUM(tctl.ct_ABalance * vctfs.PlusOrMinus)														[ct_ABalance_his],
			CONVERT(decimal(19,2),0)																		[AcumBalance]
			--CASE
			--	WHEN avg(tctl.ctl_daysPastDue) > 0 THEN avg(tctl.ctl_daysPastDue)
			--	ELSE									0
			--END																							[AVGPastDue]



			FROM tbCommercialTransactions								tct			WITH (NOLOCK)
			INNER JOIN vwCommercialTransactions_forSales vctfs						WITH (NOLOCK)
				ON	vctfs.comp_id		= tct.comp_id AND
					vctfs.ct_transaction= tct.ct_transaction
			INNER JOIN tbCommercialTransactionsLoan						tctl		WITH (NOLOCK)
			ON  tctl.comp_id			= tct.comp_id			AND
				tctl.ct_transaction		= tct.ct_transaction
			INNER JOIN tbcustomer										tc2			WITH (NOLOCK)
			ON   tct.comp_id			= tc2.comp_id			AND
				 tct.cust_id			= tc2.cust_id
			INNER JOIN tbsysCurrency									tc			WITH (NOLOCK)
			ON	 tc.curr_id				= tctl.curr_id

			WHERE	tct.comp_id			= @comp_id				AND
					tct.cust_id			= @cust_id
			GROUP BY Month(tctl.ctl_payDate),
					 Year(tctl.ctl_payDate)
			ORDER BY Year(tctl.ctl_payDate),Month(tctl.ctl_payDate) asc



		UPDATE @tmpTable
			SET AcumTotal	= (	select sum(ct_ATotal_his)
			             			FROM @tmpTable tmp1
			             	   		WHERE tmp1.Id <= tmp.id	),
				AcumBalance = (	select sum(ct_ABalance_his)
			             			FROM @tmpTable tmp1
			             	   		WHERE tmp1.Id <= tmp.id	)
			FROM @tmpTable tmp


		SELECT * FROM	@tmpTable


END
GO



------------------------------------------------------------------------------------------------------
--Date		: 12/07/2017
--Author	: GA
--Desc		: Cantidad de pedidos en la sucursal
------------------------------------------------------------------------------------------------------



CREATE procedure [dbo].[spCustomerInfo_GetData_QtySaleOrder]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@cust_id	INT
)
AS


BEGIN

------------------------------------------------------------------------
/*

	DECLARE
		@comp_id	INT,
		@lang_id	INT,
		@bra_id		INT,
		@prof_id	INT,
		@user_id	INT,
		@cust_id	INT

	SELECT
		@comp_id	= 1,
		@lang_id	= 2,
		@bra_id		= 1,
		@prof_id	= 1,
		@user_id	= 1,
		@cust_id	= 24454

*/
------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
-- -----------------------------------------------------------------------------
SET NOCOUNT ON


	-- En esta Sucursal
	DECLARE @lqtyBranch AS INT
	SET		@lqtyBranch = ( SELECT COUNT(*)
							FROM	tbSaleOrderHeader						tsoh		WITH (NOLOCK)

							INNER JOIN tbDocumentsFile						tdf			WITH (NOLOCK)
							ON	tdf.comp_id			= tsoh.comp_id		AND
								tdf.bra_id			= tsoh.bra_id		AND
								tdf.df_id			= tsoh.df_id

							INNER JOIN tbUsers4BranchFilter					 vubf		WITH (NOLOCK)
							 ON  vubf.comp_id		= tsoh.comp_id		AND
								 vubf.bra_id		= tsoh.bra_id		AND
								 vubf.[user_id]		= @user_id

							WHERE	tsoh.comp_id	= @comp_id			AND
									tsoh.bra_id		= @bra_id			AND
									tsoh.cust_id	= @cust_id			AND
									(tdf.sd_id = 1 OR tdf.sd_id = 2)	-- Solo Facturas o Remitos

					)


	-- En todas las sucursales
	DECLARE @ltotalqtyALLBranch AS INT
	SET		@ltotalqtyALLBranch = ( SELECT COUNT(*)
									FROM	tbSaleOrderHeader						tsoh		WITH (NOLOCK)

									INNER JOIN tbDocumentsFile						tdf			WITH (NOLOCK)
									ON	tdf.comp_id			= tsoh.comp_id		AND
										tdf.bra_id			= tsoh.bra_id		AND
										tdf.df_id			= tsoh.df_id

									INNER JOIN tbUsers4BranchFilter					 vubf		WITH (NOLOCK)
									 ON  vubf.comp_id		= tsoh.comp_id		AND
										 vubf.bra_id		= tsoh.bra_id		AND
										 vubf.[user_id]		= @user_id

									WHERE	tsoh.comp_id	= @comp_id			AND
											tsoh.bra_id		<> @bra_id			AND
											tsoh.cust_id	= @cust_id			AND
											(tdf.sd_id = 1 OR tdf.sd_id = 2)	-- Solo Facturas o Remitos
						)


SELECT
	@lqtyBranch								[qty],		-- En esta Sucursal
	@ltotalqtyALLBranch	+ @lqtyBranch		[totalqty]	-- En todas las sucursales

END
GO



