--Date:
--Author:GA
--Desc: customer info garante de y garantizado por
------------------------------------------------------------------------------------------------------


CREATE procedure [dbo].[spCustomerInfo_Guarantors_GetdataByFilters]
(

	@comp_id  INT,
	@cust_id  INT

)
as
SET NOCOUNT ON


----------------------------------------------------------
--PARAMETROS DE PRUEBA
----------------------------------------------------------
 /*

  DECLARE @comp_id		AS INT,
		  @cust_id		AS INT


  SELECT  @comp_id		= 1,
		  @cust_id		= 24294
*/
----------------------------------------------------------
----------------------------------------------------------



  BEGIN


	  -----------------------------------------------------------------------------------------
	  -- BEGIN Cliente Garante de
	  -----------------------------------------------------------------------------------------

		  SELECT  ' ' [ ],
				  tc2.cust_name					[cust_name],
				  tc2.cust_id					[ID]


			  FROM tbCustomerGuarantorOf							tcg		WITH (NOLOCK)

			  left JOIN tbCustomer									tc		WITH (NOLOCK)
			  ON  tcg.comp_id				= tc.comp_id	AND
				  tcg.cust_id				= tc.cust_id

			  left JOIN tbcustomer									tc2		WITH (NOLOCK)
			  ON  tcg.comp_id				= tc2.comp_id	AND
				  tcg.cust_id_guaranteed	= tc2.cust_id

		   WHERE tcg.comp_id = @comp_id		AND
				 tc.cust_id  = @cust_id

		  ORDER BY tc.cust_name

	   -----------------------------------------------------------------------------------------
	   -- END Cliente Garante de
	   -----------------------------------------------------------------------------------------


	   -----------------------------------------------------------------------------------------
	   --Cliente Garantizado por
	   -----------------------------------------------------------------------------------------
		  SELECT  ' ' [ ],
				  tc.cust_name					[cust_name],
				  tc.cust_id					[ID]


			  FROM tbCustomerGuarantorOf							tcg		WITH (NOLOCK)

			  left JOIN tbCustomer									tc		WITH (NOLOCK)
			  ON  tcg.comp_id				= tc.comp_id	AND
				  tcg.cust_id				= tc.cust_id

			  left JOIN tbcustomer									tc2		WITH (NOLOCK)
			  ON  tcg.comp_id				= tc2.comp_id	AND
				  tcg.cust_id_guaranteed	= tc2.cust_id



		  WHERE tcg.comp_id  = @comp_id		AND
				tc2.cust_id  = @cust_id

		  ORDER BY tc2.cust_name


		-----------------------------------------------------------------------------------------
		-- END Cliente Garantizado por
		-----------------------------------------------------------------------------------------



END
GO



