--Desc: customer info NOTES
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spCustomerInfo_Notes_GetdataByFilters]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

)
as



  BEGIN


	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	----------------------------------------------------------
	--PARAMETROS DE PRUEBA
	----------------------------------------------------------
	/*
	  DECLARE @comp_id		AS INT,
			  @lang_id		AS INT,
			  @cust_id		AS INT


	  SELECT  @comp_id		= 1,
			  @lang_id		= 2,
			  @cust_id		= 24294
	*/
	----------------------------------------------------------
	----------------------------------------------------------



	SELECT  tov.optval_desc													[crmnt_alertOnSaleOrder],
			tcn.crmn_note1													[crmn_note1],
			tcn.crmn_cd														[crmn_cd],
			tcnt.crmnt_desc													[crmnt_desc],
			tu.user_lastname + ', ' + tu.user_firstname						[user_id_Creator],
			tu2.user_lastname + ', ' + tu2.user_firstname					[user_id_lastUpdate],
			tcn.crmn_id														[ID]


	FROM tbCRM_Notes											tcn			WITH (NOLOCK)


	INNER JOIN tbCRM_NoteType									tcnt		WITH (NOLOCK)
	ON  tcnt.comp_id			= tcn.comp_id	AND
		tcnt.crmnt_id			= tcn.crmnt_id


	-- NO FORRO, NO
	--INNER JOIN tbCRM_NoteType2Profile							tcntp		WITH (NOLOCK)
	--ON  tcntp.comp_id			= tcnt.comp_id	AND
	--	tcntp.crmnt_id			= tcnt.crmnt_id

	INNER JOIN tbUser											tu			WITH (NOLOCK)
	ON tu.[user_id]				= tcn.user_id_Creator

	INNER JOIN tbUser											tu2			WITH (NOLOCK)
	ON tu2.[user_id]			= tcn.user_id_lastUpdate

	inner join tbsysOptionsValues								tov			WITH (NOLOCK)
	on  tov.optval_class		= 137
	and tov.lang_id				= @lang_id
	and tov.optval_id			= tcnt.crmnt_alertOnSaleOrder

	inner join tbsysOptionsValues								tov2		WITH (NOLOCK)
	on  tov2.optval_class		= 137
	and tov2.lang_id			= @lang_id
	and tov2.optval_id			= tcnt.crmnt_disabled



   WHERE tcn.comp_id				 = @comp_id		AND
		 tcn.cust_id				 = @cust_id		AND
		 tcnt.crmnt_disabled		 = 'False'		AND
		 tcnt.crmnt_alertOnSaleOrder = 'False'


	ORDER BY tcnt.crmnt_alertOnSaleOrder desc,tcn.crmn_cd desc








END
GO



