			--ON  tcntp.comp_id			= tcnt.comp_id	AND
			--	tcntp.crmnt_id			= tcnt.crmnt_id

			INNER JOIN tbUser											tu			WITH (NOLOCK)
			ON tu.[user_id]				= tcn.user_id_Creator

			INNER JOIN tbUser											tu2			WITH (NOLOCK)
			ON tu2.[user_id]			= tcn.user_id_lastUpdate

			inner join tbsysOptionsValues								tov			WITH (NOLOCK)
			on  tov.optval_class		= 137
			and tov.lang_id				= @lang_id
			and tov.optval_id			= tcnt.crmnt_alertOnSaleOrder

			inner join tbsysOptionsValues								tov2		WITH (NOLOCK)
			on  tov2.optval_class		= 137
			and tov2.lang_id			= @lang_id
			and tov2.optval_id			= tcnt.crmnt_disabled



		   WHERE tcn.comp_id				 = @comp_id		AND
				 tcn.cust_id				 = @cust_id		AND
				 tcnt.crmnt_disabled		 = 'False'		AND
				 tcnt.crmnt_alertOnSaleOrder = 'True'


			ORDER BY tcnt.crmnt_alertOnSaleOrder desc,tcn.crmn_cd desc








END
GO



