--Date:
--Author:GA
--Desc: customer info Prot-com
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spCustomerInfo_ProtCom_GetdataByFilters]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

)
as
SET NOCOUNT ON

----------------------------------------------------------
--PARAMETROS DE PRUEBA
----------------------------------------------------------
/*
  DECLARE @comp_id		AS INT,
		  @lang_id		AS INT,
		  @cust_id		AS INT


  SELECT  @comp_id		= 1,
		  @lang_id		= 2,
		  @cust_id		= 24294

drop table #tmpProtCom
*/
----------------------------------------------------------
----------------------------------------------------------
BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON

	--Guardamos en una tabla temporal el cliente y sus familiares
	DECLARE @tmpCustomers TABLE(cust_id int PRIMARY	 KEY,taxnumber NVARCHAR(50))
	INSERT INTO @tmpCustomers (cust_id,taxnumber)

		SELECT
			tc.cust_id					[ID],
			tc.cust_taxNumber			[TaxNumber]

			FROM	tbCustomer										tc		WITH (NOLOCK)

			WHERE	tc.comp_id		= @comp_id		AND
					tc.cust_id		= @cust_id

			UNION

			SELECT	tcf.custf_id				[ID],
					tcf.custf_taxNumber		[TaxNumber]

			FROM		tbCustomerFamily							tcf		WITH (NOLOCK)

			WHERE	tcf.comp_id  = @comp_id		AND
					tcf.cust_id  = @cust_id


		--SELECT * FROM @tmpCustomers



		SELECT  tcbap.protcom_infoName,
				tcbap.protcom_Name,
				tcbap.protcom_status,
		        tcbap.protcom_address,
				tcbap.protcom_beginDate,
		        tcbap.protcom_endDate,
		        tcbap.protcom_taxNumber,
		        ttnt.tnt_desc

	    into	#tmpProtCom

		FROM tbCreditBehavior_Arg_Protcom					tcbap			WITH (NOLOCK)

		INNER JOIN tbsysTaxNumberTypes						ttnt			WITH (NOLOCK)
		ON ttnt.tnt_id = tcbap.tnt_id

		INNER JOIN @tmpCustomers							tc
		ON tc.taxNumber = tcbap.protcom_taxNumber

		WHERE tcbap.comp_id = @comp_id

		--tabla que muestra los datos
		SELECT * FROM #tmpProtCom WHERE protcom_Name <> ''


		DECLARE @count AS INT
		SET @count = ( SELECT COUNT(*)FROM #tmpProtCom)
		--SELECT @count


		--estado segun los datos
		IF NOT EXISTS ( SELECT 1 FROM #tmpProtCom )
			BEGIN
		 		SELECT 4 [Status]
			END

			ELSE
				BEGIN

					IF (SELECT COUNT(*)FROM #tmpProtCom tmppc WHERE tmppc.protcom_endDate  IS NULL) = 0
					BEGIN
							--VERDE Fecha de Baja TODAS DISTINTO DE NULL
		 					SELECT 3  [Status]
					END

					ELSE
						IF (SELECT COUNT(*)FROM #tmpProtCom tmppc WHERE tmppc.protcom_endDate IS NULL) = @count
							BEGIN
							--ROJO Fecha de Baja todas en NULL
		 					SELECT 1 [Status]
							END
					ELSE
						IF (SELECT COUNT(*)FROM #tmpProtCom tmppc WHERE tmppc.protcom_endDate IS NULL) <> @count
							BEGIN
							--AMARILLO Fecha de Baja NULL y NO NULL
		 					SELECT 2 [Status]
							END

		 		END


END
GO



