CREATE procedure [dbo].[spCustomerInfo_SaleOrderHeader_MercadoLibreHistory_InAlerts_Getdata]
(

	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT

)
as
SET NOCOUNT ON

----------------------------------------------------------
--PARAMETROS DE PRUEBA
----------------------------------------------------------
/*
  DECLARE @comp_id		AS INT,
		  @lang_id		AS INT,
		  @cust_id		AS INT


  SELECT  @comp_id		= 1,
		  @lang_id		= 2,
