		ON tsoh.comp_id = tsohml.comp_id	AND
		   tsoh.bra_id	= tsohml.bra_id		AND
		   tsoh.soh_id	= tsohml.soh_id

		INNER JOIN tbCustomer										tc				WITH (NOLOCK)
		ON	tc.comp_id	= tsoh.comp_id		AND
			tc.cust_id	= tsoh.cust_id


	   WHERE tsohml.comp_id				 = @comp_id		AND
			 tc.cust_id					 = @cust_id		AND
			 tsohml.mls_isAlert			 = 'True'


		ORDER BY tsohml.mls_cd desc



END
GO



