--------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spCustomerPriceListBySOItemType_Process_Auto_Validate]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cust_id					INT,
	@prli_id					INT,
	@tipi_id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT




)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cust_id					INT,
	@custb_name					NVARCHAR(100),
	@custb_address				NVARCHAR(150),
	@custb_city					NVARCHAR(60),
	@custb_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@ss_id						INT,
	@sm_id						INT,
	@dl_id						INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------

SET NOCOUNT ON
SET DATEFORMAT 'YMD'

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''



	------CLIENTE-----------------------------------------------------------------------------------------------------------
	if	@cust_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Cliente'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT	tc.cust_id
			               FROM		tbCustomer		tc		WITH (NOLOCK)
			               WHERE	tc.comp_id		= @comp_id AND
									tc.cust_id		= @cust_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Cliente es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------



		------Tipo de articulo  -----------------------------------------------------------------------------------------------------------
	if	@tipi_id	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Tipo de Artículo'
		END
	ELSE
		BEGIN

			IF not EXISTS (SELECT top 1 ti.tipi_id
    								FROM tbItemType AS  ti								WITH (NOLOCK)
    								WHERE	ti.comp_id				= @comp_id AND
											ti.tipi_id			= @tipi_id
							)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Tipo de Artículo es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------





	------Lista de Precio-----------------------------------------------------------------------------------------------------------
	if	@prli_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Lista de Precio'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT	tc.prli_id
			               FROM		tbPriceList AS  		tc		WITH (NOLOCK)
			               WHERE	tc.comp_id		= @comp_id AND
									tc.prli_id		= @prli_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Lista de Precio es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------






	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO





create PROCEDURE [dbo].[spCustomerPriceListBySOItemType_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN



	SELECT
			CONVERT(VARCHAR,TC.cust_id) + '-' + CONVERT(VARCHAR,tc.prli_id)	 + '-' + CONVERT(VARCHAR,tc.tipi_id)		[cust_name],
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbCustomerPriceListBySOItemType			tc		WITH (NOLOCK)
		ON	tc.comp_id		= tpclil.comp_id	AND
			tc.cust_id		= tpclil.item_id

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO





