CREATE PROCEDURE [dbo].[spCustomers_Process_Auto_MassiveUpdate]
(

	@comp_id									INT,
	@lang_id									INT,
	@bra_id4session								INT,
	@user_id									INT,
	@prof_id									INT,

	@cust_id									INT,
	@cust_lastName								NVARCHAR(200),			-- RAZÓN SOCIAL / APELLIDO
	@cust_name1									NVARCHAR(200),			-- Nombre de Fantasía / Otros
	@city_id									INT,					-- ID de Ciudad
	@cust_address								NVARCHAR(150),			-- Domicilio
	@cust_zip									NVARCHAR(50),			-- Código Postal, - (menos) si no lo conoce
	@cust_phone1								NVARCHAR(200),			-- Teléfono
	@act_id										INT,					-- ID Actividad
	@sm_id										INT,					-- ID Vendedor
	@ss_id										INT,					-- ID Area de Ventas
	@ck_id										INT,					-- ID Clase de Cliente
	@dl_id										INT,					-- ID Transporte
	@cust_contact								NVARCHAR(100),			-- 1) Contacto Compras
	@cust_email									NVARCHAR(300),			-- 1) e-mail Compras (Principal)
	@cust_address4Delivery						NVARCHAR(200),			-- Domicilio de Envío
    @cust_address4Payments						NVARCHAR(200),			-- Domicilio de Pago
	@st_id										INT,					-- ID Condición de Venta
	@disc_id									INT,					-- ID Descuento
	@prli_id									INT, 					-- ID Lista de Precio
	@cust_credit_max							NUMERIC(17,2),			-- Crédito Máximo
	@cust_credit_own							NUMERIC(17,2),			-- Crédito Máximo en Valores Propios
	@cust_Mailing4CustOverdueDebt_Excluded		INT,					-- Excluir de Mailing de DEUDA
	@cust_excludeOfCustomerMailing				INT,					-- Excluir de Mailing a Clientes
	@cust_inactive								INT,					-- Inactivo - CUENTA BLOQUEADA
	@stor_id									INT,					-- ID Depósito
	@bra_id										INT,					-- ID Sucursal
	@stcIB_Id									INT,					-- ID Ingresos Brutos
	@cust_taxIBNumber							NVARCHAR(50),			-- Número Ingresos Brutos
	@cust_contact4Payments						NVARCHAR(2000),			-- 2) Contacto Pagos
    @cust_email4Payments						NVARCHAR(2000),			-- 2) e-mail Pagos
    @cust_contact4Administration				NVARCHAR(2000),			-- 4) Contacto Administración / Impuestos
    @cust_email4Administration					NVARCHAR(2000),			-- 4) e-mail Administración / Impuestos
    @cust_contact4RMA							NVARCHAR(2000),			-- 8) Contacto R.M.A.
    @cust_email4RMA								NVARCHAR(2000),			-- 8) e-mail R.M.A.
    @cust_webPending2Verify						INT,					-- Pendiente de Habilitar para Ventas WEB
    @cust_webNickName							NVARCHAR(250),			-- Nombre de Usuario para Sitio Web (Se aconseja que sea un eMail)
    @cust_webPassword							NVARCHAR(50),			-- Clave para Sitio Web
	@cust_note1									NVARCHAR(100),			-- Nota 1
	@cust_note2									NVARCHAR(100),			-- Nota 2
    @cust_note3									NVARCHAR(100),			-- Nota 3
    @cust_note4									NVARCHAR(100),			-- Nota 4

	@guid										UNIQUEIDENTIFIER,		-- Guid
	@intROW										INT						-- N° Fila




)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,



	@cust_id									INT,
	@cust_lastName								NVARCHAR(200),
	@cust_name1									NVARCHAR(200),
	@city_id									INT,
	@cust_address								NVARCHAR(150),
	@cust_zip									NVARCHAR(50),
	@cust_phone1								NVARCHAR(200),
	@act_id										INT,
	@sm_id										INT,
	@ss_id										INT,
	@ck_id										INT,
	@dl_id										INT,
	@cust_contact								NVARCHAR(100),
	@cust_email									NVARCHAR(300),
	@cust_address4Delivery						NVARCHAR(200),
    @cust_address4Payments						NVARCHAR(200),
	@st_id										INT,
	@disc_id									INT,
	@prli_id									INT,
	@cust_credit_max							NUMERIC(17,2),
	@cust_Mailing4CustOverdueDebt_Excluded		BIT,
	@cust_excludeOfCustomerMailing				BIT,
	@cust_inactive								BIT,
	@stor_id									INT,
	@bra_id										INT,
	@stcIB_Id									INT,
	@cust_taxIBNumber							NVARCHAR(50),
	@cust_contact4Payments						NVARCHAR(2000),
    @cust_email4Payments						NVARCHAR(2000),
    @cust_cust_contact4Administration			NVARCHAR(2000),
    @cust_cust_email4Administration				NVARCHAR(2000),
    @cust_contact4RMA							NVARCHAR(2000),
    @cust_email4RMA								NVARCHAR(2000),
    @cust_webPending2Verify						BIT,
    @cust_webNickName							NVARCHAR(250),
    @cust_webPassword							NVARCHAR(50),
	@cust_note1									NVARCHAR(100),
	@cust_note2									NVARCHAR(100),
    @cust_note3									NVARCHAR(100),
    @cust_note4									NVARCHAR(100),

	@guid										UNIQUEIDENTIFIER,
	@intROW										INT,

	@bolIsOK									BIT





SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,

	@item_code					='1637 hs999',
	@cat_id						= 40 ,
	@subcat_id					= 3823 ,
	@subcataux_id				= -1 ,
	@ic_id						= 2  ,
	@item_desc					='desc',
	@item_detail				='detail',
	@item_vendorCode			='vendor code',
	@brand_id					= 75 ,
	@pres_id					= 69,
	@item_codeAlternative		='alternative code',
	@curr_id					= 1,
	@supp_id					= 8110 ,
	@item_trigger_tax_id		= 1,
	@item_upb					= 1,
	@item_upp					= 1,
	@item_mult					= 1,
	@item_commission			= 1,
	@item_commission_byReceive  = 1,
	@item_liquidation			= 1,
	@item_newness				= 0,
	@item_outlet				= 0,
	@item_expser				= 0,
	@item_expean				= 1,
	@item_disabled				= 0,
	@item_comboDisc_Cant1		= 1,
	@item_comboDisc_Cant2		= 1,
	@item_comboDisc_Disc1		= 1,
	@item_comboDisc_Disc2		= 1,
	@item_purOrd_Disc1			= 1,
	@item_purOrd_Disc2			= 1,
	@item_purOrd_Disc3			= 1,
	@item_markup_1				= 0,
	@item_markup_2				= 0,
	@item_markup_3				= 0,
	@item_markup_4				= 0,
	@item_markup_5				= 0,
	@item_markup_6				= 0,
	@item_markup_7				= 0,
	@item_markup_8				= 0,
	@item_annotation1			='anotation1',
	@item_annotation2			='',
	@item_WebSite_desc			='',
	@item_WebSite_vendorPage	='',
	@item_WebSite_vendorDrivers	='@item_WebSite_vendorDrivers',
	@item_WebSite_url4Image1	='@item_WebSite_url4Image1',
	@item_WebSite_url4Image2	='@item_WebSite_url4Image2',
	@item_WebSite_url4Image3	='@item_WebSite_url4Image3',
	@item_WebSite_url4Image4	='@item_WebSite_url4Image4',
	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 10

*/
---------------------------------------------------------------------------------

SET NOCOUNT ON
SET DATEFORMAT 'YMD'


BEGIN
	declare @return_value	INT = 1


	--if	@bra_id		= -1  SET @bra_id = NULL
	--if	@ss_id		= -1  SET @ss_id = NULL
	--if	@stcIB_Id	= -1  SET @stcIB_Id = 1
	--if	@stor_id	= -1  SET @stor_id = NULL


	-- ------------------------------------------------
	-- VARIABLES BOOLEAN LOCALES
	-- ------------------------------------------------

	DECLARE
		@Local_cust_Mailing4CustOverdueDebt_Excluded		BIT,		-- Excluir de Mailing de DEUDA
		@Local_cust_excludeOfCustomerMailing				BIT,		-- Excluir de Mailing a Clientes
		@Local_cust_inactive								BIT,		-- Inactivo Cuenta bloqueada
		@Local_cust_webPending2Verify						BIT			-- Pendiente de Habilitar para Ventas WEB

		IF @cust_Mailing4CustOverdueDebt_Excluded	<> -1
				BEGIN
					SET @Local_cust_Mailing4CustOverdueDebt_Excluded = CONVERT(BIT, @cust_Mailing4CustOverdueDebt_Excluded)
				END

		IF @cust_excludeOfCustomerMailing	<> -1
				BEGIN
					SET @Local_cust_excludeOfCustomerMailing = CONVERT(BIT, @cust_excludeOfCustomerMailing)
				END

		IF @cust_inactive	<> -1
				BEGIN
					SET @Local_cust_inactive = CONVERT(BIT, @cust_inactive)
				END

		IF @cust_webPending2Verify	<> -1
				BEGIN
					SET @Local_cust_webPending2Verify = CONVERT(BIT, @cust_webPending2Verify)
				END

	-- ------------------------------------------------
	-- VARIABLES BOOLEAN LOCALES
	-- ------------------------------------------------

			BEGIN TRY

					UPDATE tbCustomer
					SET

					cust_lastName				=	CASE
													WHEN @cust_lastName				= ''	THEN	-- Si viene informado "nada", deja lo que está
															cust_lastName
													ELSE @cust_lastName
				         							END,

				    cust_name1					=	CASE
													WHEN @cust_name1				= ''	THEN
															cust_name1
													ELSE @cust_name1
				         							END,

				   city_id						=	CASE
													WHEN @city_id					<= 0	THEN
															city_id
													ELSE @city_id
				         							END,
				   cust_address					=	CASE
													WHEN @cust_address				= ''	THEN
															cust_address
													ELSE @cust_address
				         							END,
				   cust_zip						=	CASE
													WHEN @cust_zip					= ''	THEN
															cust_zip
													ELSE @cust_zip
				         							END,
				   cust_phone1					=	CASE
													WHEN @cust_phone1				= ''	THEN
															cust_phone1
													ELSE @cust_phone1
				         							END,
				    act_id						=	CASE
													WHEN @act_id					<= 0	THEN
															act_id
													ELSE @act_id
				         							END,
				    sm_id						=	CASE
													WHEN @sm_id						<= 0	THEN
															sm_id
													ELSE @sm_id
				         							END,
				    ss_id						=	CASE
													WHEN @ss_id						<= 0	THEN
															ss_id
													ELSE @ss_id
				         							END,
				    ck_id						=	CASE
													WHEN @ck_id						<= 0	THEN
															ck_id
													ELSE @ck_id
				         							END,

				    dl_id						=	CASE
													WHEN @dl_id						<= 0	THEN
															dl_id
													ELSE @dl_id
				         							END,
					cust_contact				=	CASE
													WHEN @cust_contact				= ''	THEN
															cust_contact
													ELSE @cust_contact
				         							END,
				    cust_email					=	CASE
													WHEN @cust_email				= ''	THEN
															cust_email
													ELSE @cust_email
				         							END,
				    cust_address4Delivery		=	CASE
													WHEN @cust_address4Delivery		= ''	THEN
															cust_address4Delivery
													ELSE @cust_address4Delivery
				         							END,
				    cust_address4Payments		=	CASE
													WHEN @cust_address4Payments		= ''	THEN
															cust_address4Payments
													ELSE @cust_address4Payments
				         								END,
					st_id						=	CASE
													WHEN @st_id						<= 0	THEN
															st_id
													ELSE @st_id
				         							END,
				    disc_id						=	CASE
													WHEN @disc_id					<= 0	THEN
															disc_id
													ELSE @disc_id
				         							END,
					prli_id						=	CASE
													WHEN @prli_id					<= 0	THEN
															prli_id
													ELSE @prli_id
				         							END,
				    cust_credit_max				=	CASE
													WHEN @cust_credit_max			= -1	THEN
															cust_credit_max
													ELSE @cust_credit_max
				         							END,
				    cust_credit_own				=	CASE
													WHEN @cust_credit_own			= -1	THEN
															cust_credit_own
													ELSE @cust_credit_own
				         							END,

				    cust_Mailing4CustOverdueDebt_Excluded			=	CASE
																		WHEN @cust_Mailing4CustOverdueDebt_Excluded	= -1	THEN
																			cust_Mailing4CustOverdueDebt_Excluded
																			ELSE @Local_cust_Mailing4CustOverdueDebt_Excluded
				                                           				END,
				    cust_excludeOfCustomerMailing					=	CASE
																		WHEN @cust_excludeOfCustomerMailing			= -1	THEN
																				cust_excludeOfCustomerMailing
																		ELSE @Local_cust_excludeOfCustomerMailing
				         												END,
				     cust_inactive									=	CASE
																		WHEN @cust_inactive							= -1	THEN
																				cust_inactive
																		ELSE @Local_cust_inactive
				         												END,

				     stor_id				=	CASE
												WHEN @stor_id			<= 0	THEN
														stor_id
												ELSE @stor_id
				         						END,

				    bra_id					=	CASE
												WHEN @bra_id			<= 0	THEN
														bra_id
												ELSE @bra_id
				         						END,
				     stcIB_Id				=	CASE
												WHEN @stcIB_Id			<= 0	THEN
														stcIB_Id
												ELSE @stcIB_Id
				         						END,
				    cust_taxIBNumber		=	CASE
												WHEN @cust_taxIBNumber				= ''	THEN
														cust_taxIBNumber
												ELSE @cust_taxIBNumber
				         						END,
				    cust_contact4Payments		=	CASE
												WHEN @cust_contact4Payments			= ''	THEN
														cust_contact4Payments
												ELSE @cust_contact4Payments
				         						END,
				    cust_email4Payments		=	CASE
												WHEN @cust_email4Payments			= ''	THEN
														cust_email4Payments
												ELSE @cust_email4Payments
				         						END,
				    cust_contact4Administration		=	CASE
												WHEN @cust_contact4Administration	= ''	THEN
														cust_contact4Administration
												ELSE @cust_contact4Administration
				         						END,
				    cust_email4Administration		=	CASE
												WHEN @cust_email4Administration		= ''	THEN
														cust_email4Administration
												ELSE @cust_email4Administration
				         						END,
				   cust_contact4RMA			=	CASE
												WHEN @cust_contact4RMA				= ''	THEN
														cust_contact4RMA
												ELSE @cust_contact4RMA
				         						END,
				    cust_email4RMA			=	CASE
												WHEN @cust_email4RMA				= ''	THEN
														cust_email4RMA
												ELSE @cust_email4RMA
				         						END,

				    cust_webPending2Verify	=	CASE
												WHEN @cust_webPending2Verify	= -1	THEN
														cust_webPending2Verify
												ELSE @Local_cust_webPending2Verify
				         						END,
				     cust_webNickName		=	CASE
												WHEN @cust_webNickName		= ''	THEN
														cust_webNickName
												ELSE @cust_webNickName
				         						END,
				      cust_webPassword		=	CASE
												WHEN @cust_webPassword		= ''	THEN
														cust_webPassword
												ELSE @cust_webPassword
				         						END,
				       cust_note1			=	CASE
												WHEN @cust_note1			= ''	THEN
														cust_note1
												ELSE @cust_note1
				         						END,
				      cust_note2			=	CASE
												WHEN @cust_note2			= ''	THEN
														cust_note2
												ELSE @cust_note2
				         						END,
				      cust_note3			=	CASE
												WHEN @cust_note3			= ''	THEN
														cust_note3
												ELSE @cust_note3
				         						END,
				      cust_note4			=	CASE
												WHEN @cust_note4			= ''	THEN
														cust_note4
												ELSE @cust_note4
				         						END
					WHERE	comp_id				= @comp_id AND
							cust_id				= @cust_id

					EXEC [spSysScript_Customers_Cities]

				END TRY
				BEGIN CATCH
					set	@return_value = 0
				END CATCH

				IF @return_value <> 0
					BEGIN
						--EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,@return_value,NULL
						EXEC [spSysScript_Customers_Cities]

					END



END


















GO





