CREATE PROCEDURE [dbo].[spCustomers_Process_Auto_MassiveUpdate_Validate]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cust_id					INT,
	@city_id					INT,
	@act_id						INT,
	@sm_id						INT,
	@ss_id						INT,
	@ck_id						INT,
	@dl_id						INT,
	@st_id						INT,
	@disc_id					INT,
	@prli_id					INT,
	@stor_id					INT,
	@stcIB_Id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT




)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cust_id					INT,
	@city_id					INT,
	@act_id						INT,
	@sm_id						INT,
	@ss_id						INT,
	@ck_id						INT,
	@dl_id						INT,
	@st_id						INT,
	@disc_id					INT,
	@prli_id					INT,
	@stor_id					INT,
	@stcIB_Id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT



SELECT
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@curr_id					INT,

	@st_id						INT,
	@disc_id					INT,
	@dl_id						INT,
	@ck_id						INT,
	@sm_id						INT,
	@act_id						INT,
	@ss_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@cust_taxNumber				NVARCHAR(50),
	@cust_inactive				BIT,
	@stcIB_Id					INT,


	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------

SET NOCOUNT ON
SET DATEFORMAT 'YMD'

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''





			-- ------------------------------------------------------------------------------------------------------------
			-- CLIENTE
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@cust_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT
									1
					               FROM tbCustomer AS tc	WITH (NOLOCK)
									WHERE	tc.comp_id	= @comp_id AND
											tc.cust_id	= @cust_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Cliente ingresado NO existe'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- CIUDAD
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@city_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT
									1
					               FROM tbCities  AS tc		WITH (NOLOCK)
									WHERE	tc.comp_id	= @comp_id AND
											tc.city_id	= @city_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Ciudad ingresado NO existe'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- Actividad
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@act_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT tck.act_id
								   FROM tbActivity   tck		WITH (NOLOCK)
								   WHERE tck.comp_id		= @comp_id and
			               				 tck.act_id			= @act_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Actividad es incorrecto'
						END
				END

			----------------------------------------------------------------------------------------------------------------


			-- ------------------------------------------------------------------------------------------------------------
			-- Vendedor
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@sm_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT tck.sm_id
								   FROM tbSalesman  tck		WITH (NOLOCK)
								   WHERE tck.comp_id		= @comp_id and
			               				 tck.sm_id			= @sm_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Vendedor es incorrecto'
						END
				END

			------------------------------------------------------------------------------------------------------------------


			-- ------------------------------------------------------------------------------------------------------------
			-- Area de Ventas
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@ss_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT tck.ss_id
								   FROM tbSaleSector   tck		WITH (NOLOCK)
								   WHERE tck.comp_id		= @comp_id and
			               				 tck.ss_id			= @ss_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Sector de Venta es incorrecto'
						END
				END

			-----------------------------------------------------------------------------------------------------------------------


			-- ------------------------------------------------------------------------------------------------------------
			-- Tipo de Cliente
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@ck_id	> 0)
				BEGIN

					IF NOT EXISTS (SELECT tck.ck_id
								   FROM tbCustomerKind tck		WITH (NOLOCK)
								   WHERE tck.comp_id		= @comp_id and
			               				 tck.ck_id			= @ck_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Clase de Cliente es incorrecto'
						END
				END

			-----------------------------------------------------------------------------------------------------------------------



			-- ------------------------------------------------------------------------------------------------------------
			-- Transporte
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@dl_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT td2.dl_id
								   FROM tbDelivery td2		WITH (NOLOCK)
								   WHERE td2.comp_id		= @comp_id and
			               				 td2.dl_id			= @dl_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Transporte es incorrecto'
						END
				END

			-----------------------------------------------------------------------------------------------------------------------




			-- ------------------------------------------------------------------------------------------------------------
			-- condicion de venta
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@st_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT tst.st_id
								   FROM tbSalesTerms tst		WITH (NOLOCK)
								   WHERE tst.comp_id = @comp_id and
			               				 tst.st_id   = @st_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Condición de Venta es incorrecto'
						END
				END

			-----------------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- Descuento
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@disc_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT td.disc_id
								   FROM tbDiscount		td		WITH (NOLOCK)
								   WHERE td.comp_id		= @comp_id and
			               				 td.disc_id		= @disc_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Descuento es incorrecto'
						END
				END

			-----------------------------------------------------------------------------------------------------------------------



			-- ------------------------------------------------------------------------------------------------------------
			-- Lista de precio
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@prli_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT tpl.prli_id
								   FROM tbPriceList tpl		WITH (NOLOCK)
								WHERE	tpl.comp_id		= @comp_id AND
										tpl.prli_id		= @prli_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Lista de Precios es incorrecto'
					END
				END

			-----------------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- Deposito
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@stor_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT tpl.stor_id
					               FROM tbStorage AS tpl	WITH (NOLOCK)
								WHERE	tpl.comp_id		= @comp_id AND
										tpl.stor_id		= @stor_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Depósito es incorrecto'
					END
				END

			-----------------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- Ingresos Brutos
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@stcIB_Id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT ttci.stcIB_Id
					               FROM tbsysTaxClass_IB AS ttci WITH (NOLOCK)
								WHERE	ttci.stcIB_Id		= @stcIB_Id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Ingresos Brutos es incorrecto'
					END
				END

			-----------------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- SUCURSAL
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@bra_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT
									1
									FROM tbBranch tb	WITH (NOLOCK)
									WHERE	tb.comp_id	= @comp_id AND
											tb.bra_id	= @bra_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Sucursal ingresado NO existe'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------




			-- 1 True  : Todo ok para actualizar.
			-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la actualizacion masiva.
			IF @bolIsOK = 'True'
				BEGIN
					SELECT
						1				[bolIsOK],
						@intROW			[Nº Fila],
						@errormessage	[Error]
				END
			ELSE
				BEGIN

					EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW, NULL,@errormessage

					SELECT
						0				[bolIsOK],
						@intROW			[Nº Fila],
						@errormessage	[Error]
				END


END


















GO





