--------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spCustomers_Process_Auto_Validate]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,



	@curr_id					INT,
	@cust_name					NVARCHAR(200),
	@cust_name1					NVARCHAR(200),
	@cust_address				NVARCHAR(150),
	@cust_city					NVARCHAR(60),
	@cust_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@cust_phone1				NVARCHAR(200),
	@cust_phone2				NVARCHAR(200),
	@cust_fax					NVARCHAR(200),

	@st_id						INT,
	@disc_id					INT,
	@dl_id						INT,
	@ck_id						INT,
	@sm_id						INT,
	@act_id						INT,
	@ss_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@cust_taxNumber				NVARCHAR(50),
	@cust_inactive				BIT,
	@stcIB_Id					INT,
	@cust_taxIBNumber			NVARCHAR(50),
	@cust_web					NVARCHAR(500),
	@cust_partnerOf				NVARCHAR(100),
	@cust_contact				NVARCHAR(100),
	@cust_email					NVARCHAR(300),
	@cust_credit_max			NUMERIC(17,2),
	@cust_credit_own			NUMERIC(17,2),
	@cust_note1					NVARCHAR(100),
	@brag_id					INT,
	@prli_id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT




)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@curr_id					INT,
	@cust_name					NVARCHAR(200),
	@cust_name1					NVARCHAR(200),
	@cust_address				NVARCHAR(150),
	@cust_city					NVARCHAR(60),
	@cust_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@cust_phone1				NVARCHAR(200),
	@cust_phone2				NVARCHAR(200),
	@cust_fax					NVARCHAR(200),

	@st_id						INT,
	@disc_id					INT,
	@dl_id						INT,
	@ck_id						INT,
	@sm_id						INT,
	@act_id						INT,
	@ss_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@cust_taxNumber				NVARCHAR(50),
	@cust_inactive				BIT,
	@stcIB_Id					INT,
	@cust_taxIBNumber			NVARCHAR(50),
	@cust_web					NVARCHAR(500),
	@cust_partnerOf				NVARCHAR(100),
	@cust_contact				NVARCHAR(100),
	@cust_email					NVARCHAR(300),
	@cust_credit_max			NUMERIC(17,2),
	@cust_credit_own			NUMERIC(17,2),
	@cust_note1					NVARCHAR(100),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT



SELECT
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@curr_id					INT,
	@cust_name					NVARCHAR(200),
	@cust_name1					NVARCHAR(200),
	@cust_address				NVARCHAR(150),
	@cust_city					NVARCHAR(60),
	@cust_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@cust_phone1				NVARCHAR(200),
	@cust_phone2				NVARCHAR(200),
	@cust_fax					NVARCHAR(200),

	@st_id						INT,
	@disc_id					INT,
	@dl_id						INT,
	@ck_id						INT,
	@sm_id						INT,
	@act_id						INT,
	@ss_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@cust_taxNumber				NVARCHAR(50),
	@cust_inactive				BIT,
	@stcIB_Id					INT,
	@cust_taxIBNumber			NVARCHAR(50),
	@cust_web					NVARCHAR(500),
	@cust_partnerOf				NVARCHAR(100),
	@cust_contact				NVARCHAR(100),
	@cust_email					NVARCHAR(300),
	@cust_credit_max			NUMERIC(17,2),
	@cust_credit_own			NUMERIC(17,2),
	@cust_note1					NVARCHAR(100),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------

SET NOCOUNT ON
SET DATEFORMAT 'YMD'

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''

	------Sucursal-----------------------------------------------------------------------------------------------------------
	if	@bra_id	= 0
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Sucursal'
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Moneda-----------------------------------------------------------------------------------------------------------
	if	@curr_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Moneda'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.curr_id
			               FROM		tbsysCurrency tc		WITH (NOLOCK)
							WHERE	tc.curr_id		= @curr_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Moneda es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Nombre de Cliente-----------------------------------------------------------------------------------------------------------
	if	@cust_name	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Nombre del Cliente'
		END
	-----------------------------------------------------------------------------------------------------------------------


	------Domicilio-----------------------------------------------------------------------------------------------------------
	if	@cust_address	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Domicilio'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Localidad-----------------------------------------------------------------------------------------------------------
	if	@cust_city	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó la Localidad'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Pais-----------------------------------------------------------------------------------------------------------
	if	@country_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID País'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.country_id
			               FROM tbsysCountry		tc		WITH (NOLOCK)
							WHERE	tc.country_id		= @country_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de País es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Provincia-----------------------------------------------------------------------------------------------------------
	if	@state_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Provincia'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.state_id
			               FROM tbsysState 	tc		WITH (NOLOCK)
			               WHERE tc.country_id = @country_id and
			               		 tc.state_id   = @state_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Provincia es incorrecto o no está relacionada al País'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	--------Telefono-----------------------------------------------------------------------------------------------------------
	--if	@cust_phone1	= ''
	--	BEGIN
	--		SET	@bolIsOK		= 'False'
	--		SET @errormessage	= @errormessage + '---' + 'No ingresó el Teléfono'
	--	END
	-------------------------------------------------------------------------------------------------------------------------

	------Condicion de Venta-----------------------------------------------------------------------------------------------------------
	if	@st_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Condición de Venta'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tst.st_id
			               FROM tbSalesTerms tst		WITH (NOLOCK)
			               WHERE tst.comp_id = @comp_id and
			               		 tst.st_id   = @st_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Condición de Venta es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Descuento-----------------------------------------------------------------------------------------------------------
	if	@disc_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Descuento'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT td.disc_id
			               FROM tbDiscount		td		WITH (NOLOCK)
			               WHERE td.comp_id		= @comp_id and
			               		 td.disc_id		= @disc_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Descuento es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Transporte-----------------------------------------------------------------------------------------------------------
	if	@dl_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Transporte'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT td2.dl_id
			               FROM tbDelivery td2		WITH (NOLOCK)
			               WHERE td2.comp_id		= @comp_id and
			               		 td2.dl_id			= @dl_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Transporte es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Tipo de Cliente-----------------------------------------------------------------------------------------------------------
	if	@ck_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Clase de Cliente'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tck.ck_id
			               FROM tbCustomerKind tck		WITH (NOLOCK)
			               WHERE tck.comp_id		= @comp_id and
			               		 tck.ck_id			= @ck_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Clase de Cliente es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Vendedor-----------------------------------------------------------------------------------------------------------
	if	@sm_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Vendedor'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tck.sm_id
			               FROM tbSalesman  tck		WITH (NOLOCK)
			               WHERE tck.comp_id		= @comp_id and
			               		 tck.sm_id			= @sm_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Vendedor es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------
	--

	------Actividad -----------------------------------------------------------------------------------------------------------
	if	@act_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Actividad'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tck.act_id
			               FROM tbActivity   tck		WITH (NOLOCK)
			               WHERE tck.comp_id		= @comp_id and
			               		 tck.act_id			= @act_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Actividad es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Sector de Ventas -----------------------------------------------------------------------------------------------------------
	if	@ss_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Sector de Venta'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tck.ss_id
			               FROM tbSaleSector   tck		WITH (NOLOCK)
			               WHERE tck.comp_id		= @comp_id and
			               		 tck.ss_id			= @ss_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Sector de Venta es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Clase Fiscal -----------------------------------------------------------------------------------------------------------
	if	@fc_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Clase Fiscal'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tfc.fc_id
			               FROM tbsysFiscalClass tfc		WITH (NOLOCK)
			               WHERE tfc.fc_id			= @fc_id AND
								 tfc.country_id		= @country_id)
				BEGIN

					IF NOT EXISTS (SELECT tfc.fc_id
			               FROM tbsysFiscalClass tfc		WITH (NOLOCK)
			               WHERE tfc.fc_id			= @fc_id AND
								 tfc.country_id		IS NULL)
								 BEGIN
								 	SET	@bolIsOK		= 'False'
									SET @errormessage	= @errormessage + '---' + 'El ID de Clase Fiscal es incorrecto o no corresponde al País adecuado'

								 END

				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Tipo de Documento-----------------------------------------------------------------------------------------------------------
	if	@tnt_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Tipo de Documento'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT ttnt.tnt_id
			               FROM tbsysTaxNumberTypes								ttnt		WITH (NOLOCK)
			               INNER JOIN tbsysFiscalClassAvailableTaxNumberTypes	sfcatnt		WITH (NOLOCK)
						   ON sfcatnt.tnt_id	=	ttnt.tnt_id

			               WHERE ttnt.tnt_id	= @tnt_id AND
								 sfcatnt.fc_id	= @fc_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Tipo de Documento es incorrecto o no corresponde a la Clase Fiscal adecuada'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------


	------Nro de Doc-----------------------------------------------------------------------------------------------------------
	if	@fc_id <> 99999999 and @tnt_id <> 8 and @cust_taxNumber	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el CUIT/DNI/RUC/RUT'
		END
	ELSE
		BEGIN
			IF EXISTS (SELECT tc.cust_id
			           FROM tbCustomer			tc		WITH (NOLOCK)
			           WHERE tc.comp_id			= @comp_id			AND
			                 tc.cust_taxNumber	= @cust_taxNumber	AND
			                 tc.tnt_id			= @tnt_id)
				--BEGIN

				--	DECLARE @ltnt_idalternative INT
				--	IF @tnt_id = 1
				--		SET @ltnt_idalternative = 21
				--	ELSE
				--		IF @tnt_id = 5
				--			SET @ltnt_idalternative = 25
				--		ELSE
				--			SET @ltnt_idalternative = 8


				--		IF EXISTS (SELECT tc.cust_id
				--				   FROM tbCustomer			tc
				--				   WHERE tc.comp_id			= @comp_id			AND
				--						 tc.cust_taxNumber	= @cust_taxNumber	AND
				--						 tc.tnt_id			= @ltnt_idalternative)
					 BEGIN
                 		SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El CUIT/DNI/RUC/RUT(Con mismo Tipo de Documento) ya existe ' + @cust_taxNumber
					 END

				--END
		END

	-----------------------------------------------------------------------------------------------------------------------


	------Grupo de Suc-----------------------------------------------------------------------------------------------------------
	IF	@brag_id	<> -1
		BEGIN
			IF NOT EXISTS (SELECT tbg.brag_id
			               FROM tbBranchGroup tbg		WITH (NOLOCK)
						WHERE	tbg.comp_id		= @comp_id AND
								tbg.brag_id		= @brag_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Grupo de Sucursales es incorrecto'
			END
		END

	-----------------------------------------------------------------------------------------------------------------------


	------Lista de Precios-----------------------------------------------------------------------------------------------------------
	IF	@prli_id	<> -1
		BEGIN
			IF NOT EXISTS (SELECT tpl.prli_id
			               FROM tbPriceList tpl		WITH (NOLOCK)
						WHERE	tpl.comp_id		= @comp_id AND
								tpl.prli_id		= @prli_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Lista de Precios es incorrecto'
			END
		END

	-----------------------------------------------------------------------------------------------------------------------




	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO



----------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Date   : 21/07/16
-- Author : GA
-- Detail : Al finalizar el proceso de importacion se muestra en una grilla que registros fueron dados de alta y los que no.
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[spCustomers_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN



	SELECT
			isnull(tc.cust_name,'')									[cust_name],
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbCustomer								tc		WITH (NOLOCK)
		ON	tc.comp_id		= tpclil.comp_id	AND
			tc.cust_id		= tpclil.item_id

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO




CREATE PROCEDURE [dbo].[spCustomerTmp_getDataByFilters]
(
		@comp_id		INT,
		--@cust_id			INT,
		--@ck_id			INT,
		--@sm_id			INT,
		--@country_id		INT,
		--@state_id			INT,
		--@fc_id			INT,
		--@cust_inactive	INT,
		@CF_Guid		UNIQUEIDENTIFIER,
		@showtable		BIT,
		@guid			UNIQUEIDENTIFIER
)
AS
	SET NOCOUNT ON
		BEGIN
			-- ----------------------------------------------------------------------------
			-- TESTING
			-- ----------------------------------------------------------------------------
			/*
				DECLARE 	@comp_id	INT,
							@cust_id	INT,
							@bra_id		INT,
							@ck_id		INT,
							@sm_id		INT,
							@country_id	INT,
							@state_id	INT,
							@showtable	BIT,
							@withTaxes	INT,
							@guid		UNIQUEIDENTIFIER


				SELECT      @comp_id	= 1,
							@cust_id	=-1,
							@bra_id		=1,
							@ck_id		=-1,
							@sm_id		=-1,
							@country_id	=-1,
							@state_id	=-1,
							@showtable	='true',
							@withTaxes	= 0,
							@guid		= '524F82C9-E3DA-41A7-8913-0E7EA3C76604'
			*/
			-- ----------------------------------------------------------------------------

			DECLARE @lCF_Guid AS UNIQUEIDENTIFIER
			SET @lCF_Guid = CONVERT(UNIQUEIDENTIFIER,@CF_Guid)

			-- ------------------------------------------------------------------
			-- Tabla Temporal para hacer JOIN de Articulos para Filtros
			-- ------------------------------------------------------------------
				DECLARE @tblComplexFilter_Customers TABLE (cust_id INT PRIMARY KEY)
				INSERT INTO @tblComplexFilter_Customers
					SELECT tcf.sl_id
						FROM tbComplexFilter tcf
						WHERE tcf.sl_guid = @lCF_Guid     AND
									  tcf.sl_selected = 'True'
				IF @@ROWCOUNT = 0
					BEGIN
						INSERT INTO @tblComplexFilter_Customers
							SELECT
								tc.cust_id
								FROM tbCustomer tc
								WHERE tc.comp_id = @comp_id
					END
			-- ------------------------------------------------------------------

			SELECT DISTINCT
				' '											[ ],
				CASE WHEN tct.guid IS NULL THEN
					CONVERT(BIT,'False')
				ELSE
					CONVERT(BIT,'True')
				END											[Checked],
				tc.cust_name,
				tc.cust_name1,
				tc.cust_address,
				tc.cust_city,
				tc.cust_zip,
				tck.ck_name,
				tc2.country_desc,
				ts.state_desc,
				tc.cust_phone1,
				tc.cust_phone2,
				tc.cust_taxNumber,
				tc.cust_id

				FROM tbCustomer								tc
					--JOIN CON LA TABLA DE COMPLEX FILTERS
					INNER JOIN @tblComplexFilter_Customers	tmp
						ON tmp.cust_id	= tc.cust_id
					LEFT JOIN dbo.tbCustomerTmp				tct
						ON  tct.comp_id		= tc.comp_id	AND
							tct.cust_id		= tc.cust_id	AND
							tct.guid		= @guid
					INNER JOIN tbsysCountry					tc2
						ON	tc2.country_id	= tc.country_id
					INNER JOIN tbsysState					ts
						ON  ts.state_id		= tc.state_id	AND
							ts.country_id	= tc.country_id
					INNER JOIN tbCustomerKind				tck
						ON  tck.comp_id		= tc.comp_id	AND
							tck.ck_id		= tc.ck_id
				WHERE	 tc.comp_id		= @comp_id
				--AND		(@cust_id		= -1 OR tc.cust_id		 = @cust_id)
				--AND     (@ck_id			= -1 OR tc.ck_id		 = @ck_id)
				--AND     (@sm_id			= -1 OR tc.sm_id		 = @sm_id)
				--AND     (@country_id	= -1 OR tc.country_id	 = @country_id)
				--AND     (@state_id		= -1 OR tc.state_id		 = @state_id)
				--AND     (@fc_id			= -1 OR tc.fc_id		 = @fc_id)
				--AND     (@cust_inactive = -1 OR tc.cust_inactive = @cust_inactive)
				ORDER BY tc.cust_id

			IF @showtable = 'True'
				BEGIN
					SELECT
						tct.comp_id,
						tct.cust_id,
						tct.guid,
						tc.cust_name,
						tc.cust_name1,
						tc.cust_address,
						tc.cust_city,
						tc.cust_zip,
						tck.ck_name,
						tc2.country_desc,
						ts.state_desc,
						tc.cust_phone1,
						tc.cust_phone2,
						tc.cust_taxNumber

						FROM tbCustomerTmp							tct
							--JOIN CON LA TABLA DE COMPLEX FILTERS
							INNER JOIN @tblComplexFilter_Customers	tmp
								ON	tmp.cust_id		= tct.cust_id
							INNER JOIN tbCustomer					tc
								ON	tc.comp_id		= tct.comp_id	AND
									tc.cust_id		= tct.cust_id
							INNER JOIN tbsysCountry					tc2
								ON	tc2.country_id	= tc.country_id
							INNER JOIN tbsysState					ts
								ON  ts.state_id		= tc.state_id	AND
									ts.country_id	= tc.country_id
							INNER JOIN tbCustomerKind				tck
								ON  tck.comp_id		= tc.comp_id	AND
									tck.ck_id		= tc.ck_id
						WHERE		tct.comp_id		= @comp_id		AND
									tct.guid		= @guid

				END
		END






GO




CREATE PROCEDURE [dbo].[spCustomerTmp_Insertdata]
(
	@comp_id			INT,
	@cust_id			INT,
	@CF_Guid			UNIQUEIDENTIFIER,
	@guid				UNIQUEIDENTIFIER,
	--@ck_id			INT,
	--@sm_id			INT,
	--	@dl_id			INT,
	--@country_id		INT,
	--@state_id			INT,
	--@fc_id			INT,
	--@cust_inactive	INT,

	@option				BIT,	--TRUE = MARCAR TODOS // FALSE = DESMARCAR TODOS
	@showtable          BIT

)
AS
	SET NOCOUNT ON
		BEGIN

			-- ----------------------------------------------------------
			-- TESTING
			-- ----------------------------------------------------------
			/*
				DECLARE 	@comp_id			INT,
							@item_id			INT,
							@prli_id			INT,
							@brand_id			INT,
							@bra_id				INT,
							@cat_id				INT,
							@subcat_id			INT,
							@pres_id			INT,
							@guid				UNIQUEIDENTIFIER,
							@option BIT,
							@showtable bit

				SELECT      @comp_id  =  1,
							@item_id  = -1,
							@guid	  = '5CD6FD5B-165E-4496-9CAE-9B9217F7B5C7',
							@bra_id   = -1,
							@prli_id  = -1,
							@brand_id = -1,
							@cat_id   = -1,
							@subcat_id= -1,
							@pres_id  = -1,
							@showtable='false',
							@option =  'false'

				--DROP TABLE #tmp
			*/
			-- ----------------------------------------------------------

			IF @cust_id = -1
				BEGIN
  					IF @option = 'true'
						BEGIN
							DELETE FROM tbCustomerTmp
							WHERE	comp_id = @comp_id	AND
									guid    = @guid
							--DROP TABLE #tmp
								CREATE TABLE #tmp (	[a] [VARCHAR](1),		[checked]      [bit],
													[cust_name]				[varchar](200)	NULL,
													[cust_name1]			[varchar](200)	NULL,
													[cust_address]			[varchar](200)	NULL,
													[cust_city]				[varchar](200)	NULL,
													[cust_zip]				[varchar](200)	NULL,
													[ck_name]				[varchar](200)	NULL,
													[country_desc]			[varchar](200)	NULL,
													[state_desc]			[varchar](200)	NULL,
													[cust_phone1]			[varchar](200)	NULL,
													[cust_phone2]			[varchar](200)	NULL,
													[cust_taxNumber]		[varchar](50)	NULL,
													[cust_id]				[int])

								INSERT #tmp
									  ([a],[checked], [cust_name],   [cust_name1],[cust_address],
													  [cust_city],   [cust_zip],  [ck_name],
													  [country_desc],[state_desc],[cust_phone1],
													  [cust_phone2],[cust_taxNumber], [cust_id])

								EXEC  [spCustomerTmp_getDataByFilters]	@comp_id,	@CF_Guid,
																		@showtable ,@guid


					--			EXEC  [spCustomerTmp_getDataByFilters] @comp_id, @cust_id,       @ck_id,
					--												   @sm_id,   @country_id,    @state_id,
					--												   @fc_id,   @cust_inactive, @showtable,
					--												   @guid

							INSERT INTO tbCustomerTmp
							(comp_id, cust_id , guid)

							 SELECT @comp_id,
									tc.cust_id,
									@guid
							 FROM #tmp tc
						END

					ELSE
					  BEGIN
							DELETE FROM tbCustomerTmp
							WHERE	comp_id = @comp_id	AND
									guid    = @guid
						END
				END
			ELSE
				BEGIN
					IF NOT EXISTS (SELECT 1 FROM tbCustomerTmp		tct
									WHERE	tct.comp_id = @comp_id	AND
											tct.cust_id = @cust_id	AND
											tct.guid	= @guid)
						BEGIN
									INSERT INTO tbCustomerTmp
									(
										comp_id,
										cust_id,
										guid
									)
									VALUES
									(
										@comp_id,
										@cust_id,
 										@guid
									)
						END
					ELSE
						BEGIN
						   DELETE FROM tbCustomerTmp
						   WHERE	comp_id = @comp_id		AND
									cust_id = @cust_id		AND
									guid    = @guid
						END
				END

			SELECT
				tmp.comp_id,
				tmp.cust_id,
				tmp.guid
				FROM tbCustomerTmp	tmp
		END
GO



CREATE PROCEDURE [dbo].[spCustomQuery_ExistsQueryesByPage]
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id AS INT,
	@lang_id	INT,
	@page_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@prorh_id	INT
			SELECT
				@comp_id	= 1,
				@prorh_id	= 1
		*/
		-- ---------------------------------------------

		SELECT
			 TOP 1 tpmpr.expgr_id
			FROM  tbCustomQuery2Grid_byPage  AS tpmpr			WITH(NOLOCK)
				WHERE	tpmpr.comp_id			= @comp_id	AND
						tpmpr.bra_id			= @bra_id	AND
						tpmpr.prof_id			= @prof_id	AND
						tpmpr.page_id			= @page_id	AND
						tpmpr.expgrr_disabled	= 'False'

	END
GO



create PROCEDURE [dbo].[spCustomQuery_GetDataByPage]
(
	@comp_id	INT,
	@lang_id	INT,
	@page_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@prorh_id	INT
			SELECT
				@comp_id	= 1,
				@prorh_id	= 1
		*/
		-- ---------------------------------------------

		DECLARE @intProc_Id AS UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000' --'6538AB79-77B4-4011-970A-AF9343D3C0E7'
		SELECT
			@intProc_Id = tpmpr.proc_id
			FROM tbProcedureManual_PageRelations tpmpr			WITH(NOLOCK)
				WHERE	tpmpr.comp_id			= @comp_id	AND
						tpmpr.page_id			= @page_id	AND
						tpmpr.proccpr_disabled	= 'False'

		SELECT @intProc_Id [proc_id]

	END
GO

