	--set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@datToDateAditional',ISNULL('''' + convert(varchar,@datToDateAditional,111) + '''','')))


	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@strguidItem',@guidItem))
	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@strguidCustomer',@guidcustomer))
	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@strguidSupplier',@guidsupplier))

	--taxi---
	if @txch_Name	  = ''	set @txch_Name	   = ''''''	else set @txch_Name		= '''' + @txch_Name + ''''
	if @txch_LastName = ''  set @txch_LastName = ''''''	else set @txch_LastName = '''' + @txch_LastName + ''''
	if @txem_Name	  = ''	set @txem_Name	   = ''''''	else set @txem_Name		= '''' + @txem_Name + ''''

	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@strTxch_Name',ISNULL(convert(varchar,@txch_Name),'')))
	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@strTxch_LastName',ISNULL(convert(varchar,@txch_LastName),'')))
