	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@datExpirationDateFrom',ISNULL('''' + convert(varchar,@ExpirationDateFrom,111) + '''','')))
	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@datExpirationDateTo',ISNULL('''' + convert(varchar,@ExpirationDateTo,111) + '''','')))
	--taxi---

	IF dbo.fnStrAT('sysSelectSP',@strQuery2Execute,1) > 0
		BEGIN

			IF	@strQuery2Execute LIKE '%DROP %'		OR
				@strQuery2Execute LIKE '%sysobjects %'	OR
				@strQuery2Execute LIKE '%databases %'	OR
				@strQuery2Execute LIKE '%master. %'		OR
				@strQuery2Execute LIKE '%TRUNCATE %'	OR
				@strQuery2Execute LIKE '%ALTER %'		OR
