					SET @strQuery2Execute = ''
				END

			SELECT
				@strQuery2Execute	[Query2Execute]
		END
	ELSE
		BEGIN

			---------------------------------------------------------------------------------
			--Se saca del query toda instruccion que pueda dañar la base de datos asi como ;, etc.
			---------------------------------------------------------------------------------
			IF	@strQuery2Execute LIKE '%DROP %'		OR
				@strQuery2Execute LIKE '%DELETE %'		OR
				@strQuery2Execute LIKE '%sysobjects %'	OR
				@strQuery2Execute LIKE '%databases %'	OR
