CREATE PROCEDURE [dbo].[spCustomQuery2Grid_GetCombo]
(
	@comp_id			int
)
AS

BEGIN

	set nocount on

/*
	DECLARE 	@comp_id			int,
				@bra_id				INT

	SELECT 		@comp_id			=1,
				@bra_id				=-1
*/

	select		tcqg.expgr_id	[id],
				tcqg.expgr_desc [desc]

		from		dbo.vwCustomQuery2Grid tcqg

		where	  ( tcqg.comp_id		= @comp_id OR tcqg.comp_id		= -1)

		and		  (tcqg.expgr_desc NOT LIKE '%Taxi%')

		order BY	tcqg.[Type],tcqg.expgr_desc




END












GO






-- MOS 08-2013
CREATE PROCEDURE [dbo].[spCustomQuery2Grid_GetCombo4ExportData]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT
)
AS

BEGIN

	set nocount on


	-- -------------------------------------------------
	-- -------------------------------------------------
/*
		DECLARE 	@comp_id			int,
					@bra_id				INT,
					@prof_id			INT,
					@user_id			INT

		SELECT 		@comp_id			=1,
					@bra_id				=1,
					@prof_id			= 1,
					@user_id			= 41
*/
	-- -------------------------------------------------



	-- Si hay definido alguna regla las filtra... sino muestra todas
	IF EXISTS(
				SELECT 1
					FROM tbCustomQuery2GridByProfile tcqgbp
					WHERE	tcqgbp.comp_id	= @comp_id	--AND
							--tcqgbp.bra_id	= @bra_id	AND
							--tcqgbp.prof_id	= @prof_id
			  )
		BEGIN

			select		tcqg.expgr_id	[id],
						tcqg.expgr_desc [desc]
				from	dbo.vwCustomQuery2Grid tcqg
				INNER JOIN tbCustomQuery2GridByProfile tcqgbp
					ON	(tcqgbp.comp_id	= tcqg.comp_id OR  tcqg.comp_id = -1)	AND
						tcqgbp.bra_id	= @bra_id		AND
						tcqgbp.prof_id	= @prof_id		AND
						tcqgbp.expgr_id = tcqg.expgr_id
				WHERE	tcqg.comp_id = @comp_id	OR tcqg.comp_id = -1
				order BY tcqg.[Type],tcqg.expgr_desc


		END

	ELSE
		BEGIN


			select		tcqg.expgr_id	[id],
						tcqg.expgr_desc [desc]
				from	dbo.vwCustomQuery2Grid tcqg
				WHERE tcqg.comp_id = @comp_id OR tcqg.comp_id = -1
				order by	tcqg.[Type],tcqg.expgr_desc


		END






END












GO


-- MOS 08-2013
CREATE PROCEDURE [dbo].[spCustomQuery2Grid_GetCombo4ExportDataByPage]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@page_id			INT
)
AS

BEGIN

	set nocount on


	-- -------------------------------------------------
	-- -------------------------------------------------
/*
		DECLARE 	@comp_id			int,
					@bra_id				INT,
					@prof_id			INT,
					@user_id			INT

		SELECT 		@comp_id			=1,
					@bra_id				=1,
					@prof_id			= 1,
					@user_id			= 41
*/
	-- -------------------------------------------------


	select		tcqg.expgr_id	[id],
				tcqg.expgr_desc [desc]
		from	dbo.vwCustomQuery2Grid			tcqg			WITH (NOLOCK)
		INNER JOIN tbCustomQuery2Grid_byPage AS tcqgbp			WITH (NOLOCK)
			ON	tcqg.comp_id	= @comp_id			AND
				tcqgbp.expgr_id = tcqg.expgr_id
		WHERE (tcqg.comp_id = @comp_id OR tcqg.comp_id = -1)	AND
				tcqgbp.comp_id	= @comp_id	AND
				tcqgbp.page_id	= @page_id	AND
				tcqgbp.bra_id	= @bra_id	AND
				tcqgbp.prof_id	= @prof_id

		order by	tcqg.[Type],tcqg.expgr_desc


		--- falta esto y probar




END












GO


