    set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@intCurr_ID',convert(varchar,@curr_id)))
	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@intUser_ID',convert(varchar,@UserID)))
