	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@intSessionBranchID',convert(varchar,@SessionBranchID)))
	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@intSessionLangID',convert(varchar,@SessionLangID)))



	if @desc1	  = ''	set @desc1	   = ''''''	else set @desc1		= '''' + @desc1 + ''''
	if @desc2	  = ''	set @desc2	   = ''''''	else set @desc2		= '''' + @desc2 + ''''
