	set @strQuery2Execute = (REPLACE (@strQuery2Execute,'@datExpirationDateTo',ISNULL('''' + convert(varchar,@ExpirationDateTo,120) + '''','')))
	--taxi---





	DECLARE @strSettings AS NVARCHAR(MAX)
	SET		@strSettings =	'SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ' + CHAR(13) +
							'SET LOCK_TIMEOUT 500 '								+ CHAR(13) +
							'SET DEADLOCK_PRIORITY LOW '						+ CHAR(13)


	IF LEN(@strQuery2Execute) > 7990
		BEGIN
			SELECT 'La consulta no se puede realizar, ya que el query que forma parte de la misma es superior a 8000 caracteres, siento este el máximo soportado por una variable.'
			RETURN
		END

	IF dbo.fnStrAT('sysSelectSP',@strQuery2Execute,1) > 0
		BEGIN

			IF	@strQuery2Execute LIKE '%DROP %'		OR
				@strQuery2Execute LIKE '%TRUNCATE %'	OR
