				@strQuery2Execute LIKE '%FUNCTION %'
				BEGIN
					SET @strQuery2Execute = 'Select ''Se intenta utilizar una instrucción SQL Prohibida!'' [GenerationError] '
				END

				IF @bitIs4Report = 'True'
