		END
	ELSE
		BEGIN

			---------------------------------------------------------------------------------
			--Se saca del query toda instruccion que pueda dañar la base de datos asi como ;, etc.
			---------------------------------------------------------------------------------
			IF	@strQuery2Execute LIKE '%DROP %'		OR
				@strQuery2Execute LIKE '%DELETE %'		OR
				@strQuery2Execute LIKE '% UPDATE %'		OR
				@strQuery2Execute LIKE '%sysobjects %'	OR
				@strQuery2Execute LIKE '%databases %'	OR
				@strQuery2Execute LIKE '%master. %'		OR
				@strQuery2Execute LIKE '%TRUNCATE %'	OR
				@strQuery2Execute LIKE '%ALTER %'		OR
				@strQuery2Execute LIKE '%PROCEDURE %'	OR
				@strQuery2Execute LIKE '%DBCC%'			OR
				@strQuery2Execute LIKE '%FUNCTION %'
				BEGIN
					SET @strQuery2Execute = ' ''Se intenta utilizar una instrucción SQL Prohibida!'' [GenerationError] '
				END
			---------------------------------------------------------------------------------


				IF @bitIs4Report = 'True'
					BEGIN
						SELECT
							'SELECT ' + @strQuery2Execute	[Query2Execute]
							RETURN
					END
				ELSE
					BEGIN
						EXEC( @strSettings +  'SELECT ' + @strQuery2Execute)
					END


		END

	-- --------------------------------------------------------------------

END
GO

CREATE PROCEDURE [dbo].[spCustomQuery2Grid_GetDataById]
(
