			ISNULL(tcqg.expgr_help,'')				[expgr_help],
			ISNULL(tcqg.expgr_rptFileName,'')		[expgr_rptFileName]
			FROM	vwCustomQuery2Grid				tcqg WITH (NOLOCK)
