CREATE procedure [dbo].[spCustomQuery2Grid_logData_InsertData]
(

	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@expgr_id			INT,
	@expgrd_query		NTEXT,
	@intSeconds			INT

)
AS

/*
DECLARE
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@expgr_id			INT,
	@expgrd_query		NVARCHAR(4000)



	SELECT
	@comp_id			=1,
	@lang_id			=2,
	@bra_id				=1,
	@prof_id			=1,
	@user_id			=3,
	@expgr_id			=9999,
	@expgrd_query		='SET NOCOUNT ON
SET DATEFORMAT ''ymd''
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET LOCK_TIMEOUT 500
SELECT * FROM tbCommercialTransactions tct

INNER JOIN tbItemTransactions tit
ON tit.bra_id = tct.bra_id AND tit.comp_id = tct.comp_id AND tit.ct_transaction = tct.ct_transaction

INNER JOIN tbItemStorage tis
ON tis.item_id = tit.item_id AND tis.stor_id = tit.stor_id AND tis.comp_id = tit.comp_id

INNER JOIN tbItem ti
ON ti.item_id = tit.it_item_id_origin AND ti.item_id = tit.item_id AND ti.comp_id = tit.comp_id
 AND ti.comp_id = tit.comp_id'
	*/


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	INSERT INTO tbCustomQuery2Grid_logData
	(
		comp_id,
		expgr_id,
		expgrd_cd,
		expgrd_query,
		expgrd_execSeconds,
		[user_id],
		bra_id,
		prof_id
	)
	VALUES
	(
		@comp_id,
		@expgr_id,
		GETDATE(),
		@expgrd_query,
		convert(decimal(19,4),@intSeconds),
		@user_id,
		@bra_id,
		@prof_id
	)

	SELECT @@IDENTITY [Id]


END











GO

