create PROCEDURE [dbo].[spCustoms_DJAI_Notes_GetDataByFilters]
(
	@comp_id			INT,
	@lang_id			INT,
	@djai_id			INT
)
AS

SET NOCOUNT ON


	BEGIN
		-- --------------------------------------
		-- Testing
		-- --------------------------------------
		/*
			DECLARE	@comp_id			INT,
					@lang_id			INT,
					@djai_id			INT

			SELECT	@comp_id			= 1,
					@lang_id			= 2,
