create procedure [dbo].[spDATABASE_LockBegin] (@SyncObject nvarchar(255))
as

begin

    declare @ret int

    exec @ret = sp_getapplock @Resource = @SyncObject, @LockMode = 'Exclusive', @LockOwner = 'Session'

    select  @ret

end

GO


create procedure [dbo].[spDATABASE_LockEnd](@SyncObject nvarchar(255))

as

begin

    begin try

        exec sp_releaseapplock @Resource = @SyncObject, @LockOwner = 'Session'

    end try

    begin catch

        -- I don't care exceptions here

    end catch

end

GO

