CREATE PROCEDURE [dbo].[spDelivery_getComboavailable4WebSite]
(
	@comp_id				INT,
	@prof_id				int
)
AS

BEGIN

	DECLARE @intDeliveriByProfile AS int
	SELECT @intDeliveriByProfile = COUNT(1)
		FROM tbDelivery4Profile tdp	WITH (NOLOCK)
		WHERE	tdp.comp_id = @comp_id AND
				tdp.prof_id = @prof_id


	-- Si tiene cargado algun transporte en este perfil, solo trae los del perfil, siono trae todos los disponibles para website
	IF @intDeliveriByProfile > 0
		BEGIN

			select		dl.dl_id		[id],
						dl.dl_name		[desc]
				from		dbo.tbDelivery dl	WITH (NOLOCK)
				INNER JOIN tbDelivery4Profile tdp	WITH (NOLOCK)
					ON	tdp.comp_id = dl.comp_id	AND
						tdp.prof_id = @prof_id		AND
						tdp.dl_id	= dl.dl_id
				where		dl.comp_id				= @comp_id
				AND			dl_available4WebSite	= 'True'

			Order By	dl_name

		END
	ELSE
		BEGIN
			select		dl_id		[id],
						dl_name		[desc]
				from		dbo.tbDelivery	WITH (NOLOCK)
				where		comp_id					= @comp_id
				AND			dl_available4WebSite	= 'True'
				Order By	dl_name
		END

END
GO






