CREATE PROCEDURE [dbo].[spDelivery_getComboByProfile]
(
	@comp_id			INT,
	@prof_id			INT,
	@dl_id				INT
)
as

	BEGIN

	DECLARE @intDeliveriByProfile AS int
	SELECT  @intDeliveriByProfile = COUNT(*)
		FROM tbDelivery4Profile tdp	WITH (NOLOCK)
		WHERE	tdp.comp_id = @comp_id AND
				tdp.prof_id = @prof_id AND
				tdp.isAvailable4SaleOrder = 'True'

	IF @intDeliveriByProfile > 0
		BEGIN
			DECLARE @tmpDelivery TABLE(id INT PRIMARY KEY, [DESC] NVARCHAR(200))

			INSERT INTO @tmpDelivery
			(
				id,
				[DESC]
			)
				SELECT 	DISTINCT
							dl.dl_id		[id],
							dl.dl_name		[desc]
					FROM 	dbo.tbDelivery dl			WITH (NOLOCK)
					INNER JOIN tbDelivery4Profile tdp	WITH (NOLOCK)
						ON	tdp.comp_id = dl.comp_id	AND
							tdp.prof_id = @prof_id		AND
							tdp.dl_id	= dl.dl_id
					where		dl.comp_id				  = @comp_id
					AND			tdp.isAvailable4SaleOrder = 'True'
					Order By	dl_name

				IF NOT EXISTS (	SELECT TOP 1 1
									FROM @tmpDelivery AS td
				               		WHERE td.id = @dl_id)
					BEGIN
						INSERT INTO @tmpDelivery
						(
							id,
							[DESC]
						)
						SELECT 		td.dl_id		[id],
									td.dl_name		[desc]
							FROM tbDelivery AS td	WITH (NOLOCK)
							WHERE	td.comp_id	= @comp_id AND
									td.dl_id	= @dl_id
					END


				SELECT *
					FROM @tmpDelivery AS td
					ORDER BY td.[DESC]



		END
	ELSE
		BEGIN
			select		dl_id		[id],
						dl_name		[desc]
				from		dbo.tbDelivery	WITH (NOLOCK)
				where		comp_id =	@comp_id
				Order By	dl_name
		END



	END








GO

