SELECT
		@comp_id			= 1	,
		@dl_id				= 1
*/
BEGIN

	select
			comp_id, dl_id, dl_name, dl_address, dl_city, dl_zip, country_id,
	      	state_id, [user_id], bra_id, dl_taxNumber, dl_deliveryControl, dl_Web,
	      	dl_phone, fc_id, dl_Note, incoid, dl_available4WebSite, de_email,
	      	arba_cot_Planta, arba_cot_Puerta, arba_cot_SUJETO_GENERADOR_IsDestiny,
	      	arba_cot_ORIGEN_DOMICILIO_CALLE, arba_cot_ORIGEN_DOMICILIO_NUMERO,
	      	arba_cot_ORIGEN_DOMICILIO_COMPLE, arba_cot_ORIGEN_DOMICILIO_PISO,
	      	arba_cot_ORIGEN_DOMICILIO_DTO, arba_cot_ORIGEN_DOMICILIO_BARRIO,
	      	arba_cot_ORIGEN_DOMILILIO_CODIGOP, arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
	      	arba_cot_EMISOR_TENEDOR, arba_cot_ORIGEN_CUIT,
	      	arba_cot_ORIGEN_RAZON_SOCIAL, arba_cot_PATENTE_VEHICULO,
	      	arba_cot_PATENTE_ACOPLADO, arba_cot_Counter, arba_cot_isAvailable,
	      	dl_deliveryType_pickUpNow, dl_deliveryType_warns4PickUp,
	      	dl_deliveryType_deliver, dl_deliveryType_warns4Deliver,
	      	dl_deliveryType_wait4GuarantorSignature,
	      	dl_deliveryType_wait4OwnerSignature,
	      	dl_deliveryType_wait4PurchaseOrderArrival, dl_deliveryType_other,
	      	sdlmt_id, dl_webSiteDecription, dl_webSiteNote, dl_eMailWhenDelivered,
	      	dl_eMailWhenDeliveredHead, dl_eMailWhenDeliveredFooter,
	      	dl_eMailWhenDeliveredFromEmail, dl_eMailWhenDeliveredSubject, dl_image,
	      	sds_id4picking, sds_id4delivery,
	      	arba_cot_cust_id_alternativeDestiny,
	      	ISNULL(ENVIOPACK_enabled,'False')			[ENVIOPACK_enabled],
	      	ENVIOPACK_APIKEY,
	      	ENVIOPACK_SECRETKEY,
	      	ENVIOPACK_direccion_envio,
	      	ENVIOPACK_confirmado,
	      	ISNULL(ENVIOPACK_item_id,-1)				[ENVIOPACK_item_id]	,
	      	dl_driverName,
	      	dl_driverDocument ,

			CASE isnull(ENVIOPACK_despacho,-1)
				WHEN -1 THEN
					NULL
				WHEN 1 THEN
					'D'
				ELSE
					'S'
			END				[ENVIOPACK_despacho],

			CASE isnull(ENVIOPACK_modalidad,-1)
				WHEN -1 THEN
					NULL
				WHEN 1 THEN
					'D'
				ELSE
					'S'
			END				[ENVIOPACK_modalidad],

			CASE isnull(ENVIOPACK_servicio,-1)

				WHEN -1 THEN
					NULL
				WHEN 1 THEN
					'N'
				WHEN 2 THEN
					'P'
				WHEN 3 THEN
					'X'
				ELSE
					'R'
			END												[ENVIOPACK_servicio],
			ISNULL(ENVIOPACK_fromTotal1,0)					[ENVIOPACK_fromTotal1],
			ISNULL(ENVIOPACK_toTotal1,0)					[ENVIOPACK_toTotal1],
			ISNULL(ENVIOPACK_discountPercent1,0)			[ENVIOPACK_discountPercent1],
			ISNULL(ENVIOPACK_fromTotal2,0)					[ENVIOPACK_fromTotal2],
			ISNULL(ENVIOPACK_toTotal2,0)					[ENVIOPACK_toTotal2],
			ISNULL(ENVIOPACK_discountPercent2,0)			[ENVIOPACK_discountPercent2],
			ISNULL(ENVIOPACK_OneBoxPackage,'False')			[ENVIOPACK_OneBoxPackage],
			ISNULL(ZIPPIN_enabled,'True')					[ZIPPIN_enabled],
			ISNULL(ZIPPIN_userEMail,'')						[ZIPPIN_userEMail],
			ISNULL(ZIPPIN_userPassword,'')					[ZIPPIN_userPassword],
			ISNULL(ZIPPIN_Clasification,-1)					[ZIPPIN_Clasification],
			ISNULL(ZIPPIN_account_id,-1)					[ZIPPIN_account_id],
			ISNULL(ZIPPIN_origin_id,-1)						[ZIPPIN_origin_id],
			ISNULL(ZIPPIN_item_id,-1)						[ZIPPIN_item_id],
			ISNULL(ZIPPIN_withOutDeclaredValue,'False')		[ZIPPIN_withOutDeclaredValue],
			ISNULL(deliverySheet_StartAddress,'')			[deliverySheet_StartAddress],
			ISNULL(deliverySheet_EndAddress,'')				[deliverySheet_EndAddress],
			ISNULL(de_email,'')								[deliverySheet_Email]


			from		dbo.tbDelivery						WITH (NOLOCK)
			where		comp_id =	@comp_id	AND
						dl_id	=   @dl_id

END

GO

