CREATE procedure [dbo].[spDelivery_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@bra_id				int,
		@country_id			int,
		@state_id			int,
		@intBranch4Lang		int

)
as


SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


/*

DECLARE @comp_id			int,
		@lang_id			int,
		@page_id			int,

		@bra_id				int,
		@country_id			int,
		@state_id			int,
		@intBranch4Lang		int



SELECT	@comp_id			=1,
		@lang_id			=2,
		@page_id			=10054,

		@bra_id				=-1,
		@country_id			=-1,
		@state_id			=-1

*/

DECLARE @fun_id INT
SET @fun_id = 1


SELECT	td.dl_id,
		td.dl_name,
		td.dl_address,
		tc.country_desc,
		ts2.state_desc,
		isnull(tb.bra_desc,'') [bra_desc],
		isnull(td.dl_phone,'') [dl_phone],
		isnull(td.dl_Note,'')  [dl_Note]



FROM tbDelivery td


left JOIN tbBranch tb
ON  tb.comp_id = td.comp_id
AND tb.bra_id  = td.bra_id

INNER  JOIN tbsysCountry tc
ON tc.country_id = td.country_id

inner JOIN tbsysState ts2
ON  ts2.state_id= td.state_id

WHERE	td.[comp_id]		=	@comp_id
AND     (@bra_id			= -1	OR		tb.bra_id =	@bra_id)
AND     (@country_id		= -1    OR      tc.country_id = @country_id)
AND     (@state_id          = -1    OR      ts2.state_id  = @state_id)


order by 1



exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

----/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id


SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 57
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

		CASE @country_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(
	     	   SELECT tc.country_desc
	     		FROM tbsysCountry tc
	     		 WHERE tc.country_id = @country_id
	     	   )
	     End [params2],

	     (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 59
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

		CASE @state_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
			(SELECT ts.state_desc
				 FROM tbsysCountry tc
				 INNER JOIN tbsysState ts
				 ON ts.country_id = tc.country_id

				 WHERE ts.state_id=@state_id
				)
		END		[params4],

		    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 28
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

		CASE @bra_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tb.bra_desc
				 FROM tbBranch tb
				 WHERE tb.comp_id=@comp_id
				 and tb.bra_id=@bra_id

				)

		END		[params6]

GO






