CREATE PROCEDURE [dbo].[spDeliverySheetDetail_GetComboRMA]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@user_id			INT,
	@cust_id			INT,
	@intisRMA4picking	INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@dl_id				INT

)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@user_id			INT,
				@cust_id			INT,
				@intSelectionOption	INT --        1 = Retiro / 0 = Envío
			SELECT
				@comp_id			= 1,
				@user_id			= 119,
				@cust_id			= 24498,
				@intSelectionOption	= 1
	*/
		-- ------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom, 'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto, 'True')

		IF @intisRMA4picking = 1
		--PICKING - RETIRO
			BEGIN
				SELECT
					trd.rmad_id																	[ID],
					tc.cust_name	+ ' * ' +
					ti.item_code	+ ' * ' +
					CONVERT(VARCHAR,trh.rmah_id)+ '-' + CONVERT(VARCHAR,trd.rmad_id)			[Desc]

					FROM tbRMA_Detail						trd		WITH (NOLOCK)
						INNER JOIN tbRMA_Header				trh		WITH (NOLOCK)
						ON	trh.comp_id		= trd.comp_id	AND
							trh.rmah_id		= trd.rmah_id
						LEFT JOIN tbCustomer				tc		WITH (NOLOCK)
						ON	tc.comp_id = trh.comp_id        AND
							tc.cust_id = trh.cust_id
						INNER JOIN tbItem					ti		WITH (NOLOCK)
						ON	ti.comp_id		= trd.comp_id	AND
							ti.item_id		= trd.item_id
						INNER JOIN tbUsers4BranchFilter		tubf	WITH (NOLOCK)
						ON	tubf.comp_id	= trh.comp_id	AND
							tubf.bra_id		= trh.bra_id	AND
							tubf.[user_id]	= @user_id
					WHERE	trd.comp_id							= @comp_id			AND
							(@cust_id	= -1	OR trh.cust_id	= @cust_id)			AND
							(@dl_id		= -1	OR trd.dl_id4Picking	= @dl_id)	AND
							trd.rmad_isAvailable4DeliverySheet	= 'True'			AND
							trd.srpt_id							= 1					AND
							trd.dsd_id4Picking					IS NULL				AND
							trd.rmad_deliveryDate4Picking BETWEEN @datefrom AND @dateto
			END

		IF @intisRMA4picking = 0
		--DELIVERY - ENVIO
			BEGIN
				SELECT
					trd.rmad_id																		[ID],
					tc.cust_name	+ ' * ' +
					ti.item_code	+ ' * ' +
					CONVERT(VARCHAR,trh.rmah_id)+ '-' + CONVERT(VARCHAR,trd.rmad_id)				[Desc]

					FROM tbRMA_Detail						trd		WITH (NOLOCK)
						INNER JOIN tbRMA_Header				trh		WITH (NOLOCK)
						ON	trh.comp_id		= trd.comp_id	AND
							trh.rmah_id		= trd.rmah_id
						LEFT JOIN tbCustomer				tc		WITH (NOLOCK)
						ON	tc.comp_id = trh.comp_id        AND
							tc.cust_id = trh.cust_id
						INNER JOIN tbItem					ti		WITH (NOLOCK)
						ON	ti.comp_id		= trd.comp_id	AND
							ti.item_id		= trd.item_id
						INNER JOIN tbUsers4BranchFilter		tubf	WITH (NOLOCK)
						ON	tubf.comp_id	= trh.comp_id	AND
							tubf.bra_id		= trh.bra_id	AND
							tubf.[user_id]	= @user_id
					WHERE	trd.comp_id							= @comp_id			AND
							(@cust_id	= -1	OR trh.cust_id	= @cust_id)			AND
							(@dl_id		= -1	OR trd.dl_id4delivery	= @dl_id)	AND
							trd.rmad_isAvailable4DeliverySheet	= 'True'			AND
							trd.srpt_id							<> 1				AND
							trd.dsd_id4Delivery					IS NULL				AND
							trd.rmad_deliveryDate4Delivery BETWEEN @datefrom AND @dateto

			END


	END
GO








CREATE PROCEDURE [dbo].[spDeliverySheetDetail_GetDataByFilters]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@ds_id				INT
)

AS




BEGIN


----------------------------------------
/*
DECLARE		@comp_id		INT,
			@lang_id		INT,
			@bra_id			INT,
			@ds_id			INT

SELECT
			@comp_id		= 1,
		    @lang_id		= 2,
		    @bra_id			= 1,
		    @ds_id			= 34
*/
------------------------------------------


	SET NOCOUNT ON

	SELECT
			''																						[ ],
			''																						[ ],
			''																						[ ],
			isnull(tdsd.dsd_order,0)																[dsd_order],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tdsd.ds_ct_transaction)	[ct_transaction],
			isnull(tdsd.ds_note,'')																	[ds_note],
			isnull(tc.cust_name,'') + ' ' + isnull(tcrma.cust_name,'')								[cust_name],
			/*isnull(tc.cust_address,'')*/

				CASE
					WHEN ctn.ctn_deliveryAddressOfSaleOrder IS NOT NULL AND
						 ctn.ctn_deliveryAddressOfSaleOrder <> ''		THEN ctn.ctn_deliveryAddressOfSaleOrder
					WHEN tcf.comp_id IS NOT NULL						THEN tcf.custf_address
					WHEN tcb.comp_id IS NOT NULL						THEN tcb.custb_address
					WHEN ISNULL(tc.cust_address4Delivery,'') <> ''		THEN tc.cust_address4Delivery
					ELSE													 tc.cust_address
				END

			[cust_address],
			-- ATENCION!!!!!!
			-- No poner nada detras de este campo(RMA) ya que se hacen controles de Count en la pagina 	wfmDeliverySheetDetail
			convert(varchar, tdsd.rmah_id) + '-' + 	convert(varchar, tdsd.rmad_id)				[RMA],
			-- ATENCION!!!!!!
			-- No poner nada detras de este campo(ds_ct_transaction) ya que se hacen controles de Count en la pagina 	wfmDeliverySheetDetail
			CONVERT(VARCHAR,tdsd.ds_ct_transaction) + '-' + CONVERT(VARCHAR,tct.bra_id)			[ct_transaction], --- Count -2
			tdsd.dsd_id																			[ID]

			FROM tbDeliverySheetDetail										tdsd	WITH (NOLOCK)

			LEFT JOIN tbCommercialTransactions								tct		WITH (NOLOCK)
			ON	tct.comp_id				= tdsd.comp_id				AND
				--tct.bra_id				= tdsd.bra_id				AND
				tct.ct_transaction		= tdsd.ds_ct_transaction

			left join dbo.tbCommercialTransactionNotes						CTN		WITH (NOLOCK)
				on	CTN.comp_id				= tct.comp_id
				and	CTN.bra_id				= tct.bra_id
				and CTN.ct_transaction		= tct.ct_transaction

			LEFT JOIN tbCustomerFamily										tcf		WITH (NOLOCK)
				ON	tcf.comp_id		= tct.comp_id AND
					tcf.cust_id		= tct.cust_id AND
					tcf.custf_id	= tct.custf_id

			LEFT JOIN tbCustomerBranch										tcb		WITH (NOLOCK)
				ON		tcb.comp_id = tct.comp_id
					AND tcb.cust_id = tct.cust_id
					AND tcb.cb_id	= tct.cb_id

			LEFT JOIN tbCustomer											tc		WITH (NOLOCK)
			ON	tc.comp_id				= tct.comp_id				AND
				tc.cust_id				= tct.cust_id


			LEFT JOIN tbRMA_Header											trh		WITH (NOLOCK)
			ON	trh.comp_id				= tdsd.comp_id				AND
				trh.rmah_id				= tdsd.rmah_id

			LEFT JOIN tbCustomer											tcrma	WITH (NOLOCK)
			ON	tcrma.comp_id			= trh.comp_id				AND
				tcrma.cust_id			= trh.cust_id


			WHERE tdsd.comp_id	= @comp_id
			AND   tdsd.bra_id	= @bra_id
			AND   tdsd.ds_id	= @ds_id


			ORDER BY tdsd.dsd_order


END
GO





