CREATE PROCEDURE [dbo].[spDeliverySheetDetail_getReport]
(
		@comp_id		INT,
		@lang_id		INT,
		@page_id		int,
		@bra_id			INT,
		@ds_id			INT,
		@intBranch4Lang int
)
as

	SET NOCOUNT ON

	BEGIN
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------



	-- -------------------------------
	-- Testing
	-- -------------------------------
	/*
		DECLARE @comp_id INT,
				@lang_id INT,
				@page_id INT,
				@bra_id	 INT,
				@ds_id	 INT,
				@intBranch4Lang int


		SELECT  @comp_id = 1,
				@lang_id = 2,
				@page_id = 10071,
				@bra_id	 = 1,
				@ds_id	 = 7802,
				@intBranch4Lang = 1
	*/
	-- -------------------------------





			-- ---------------------------------------------------------------
			-- MENSAJE PARA EL BLOQUEO DE DESPACHO
			-- ---------------------------------------------------------------
				DECLARE
					@strSI	VARCHAR(10),
					@strNO	VARCHAR(10)

				SELECT
					@strSI					= tov.optval_desc
				FROM tbsysOptionsValues						tov 	WITH (NOLOCK)
				WHERE	tov.lang_id			=	@lang_id	AND
						tov.optval_class	=	175			AND
						tov.optval_id		=	0

				SELECT
					@strNO					= tov.optval_desc
				FROM tbsysOptionsValues						tov		WITH (NOLOCK)
				WHERE	tov.lang_id			=	@lang_id	AND
						tov.optval_class	=	175			AND
						tov.optval_id		=	1
			-- ---------------------------------------------------------------

			-- MENSAJE DE QUE EL ARTÍCULO YA HA SIDO DESPACHADO
			DECLARE
				@ArtículoDespachado	NVARCHAR(50)
			SELECT
				@ArtículoDespachado = tut.utexts_desc
			FROM tbsysUniqueTexts		tut	WITH (NOLOCK)
			WHERE	tut.lang_id		= 2 AND
					tut.utexts_id	= 40280



			DECLARE
				@Multiplicador	INT
			IF EXISTS (SELECT
						TOP 1 	1
					   FROM tbControlProfiles tcp1	WITH (NOLOCK)
					   WHERE tcp1.page_id = 218 AND
							 tcp1.ctrl_id = 3151)
				BEGIN
					SET @Multiplicador = 0
				END
			ELSE
				BEGIN
					SET @Multiplicador = 1
				END


			DECLARE @prli_id4RMA	INT,
					@lcurr_id		INT


			SELECT
				@prli_id4RMA		= tb2.bra_RMA_prli_id4AdditionalItems,
				@lcurr_id			= tb2.curr_id
				FROM tbBranch		tb2	WITH (NOLOCK)
				WHERE	tb2.comp_id	= @comp_id	AND
						tb2.bra_id	= @bra_id




			SELECT
				 	tb.bra_desc,
					tdsh.ds_top,
					tdsh.ds_bottom,
					tdsh.ds_date,
					td.dl_name,
				   convert(varchar,tdsh.ds_id) [ds_id],

				   CASE
						WHEN tdsd.ds_ct_transaction IS NULL THEN
							convert(varchar,row_number() over(order by tdsd.ds_id ) * -1)
					ELSE
							dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tdsd.ds_ct_transaction)
					END			[ds_ct_transaction]										,

				   tdsd.ds_note ,
				   isnull(tdsd.dsd_order,0) [dsd_order],

					@Multiplicador * (
										CASE tc.curr_id WHEN tc2.curr_id THEN
 										ISNULL(tct.ct_total,0)
										ELSE
										ISNULL(tct.ct_ATotal,0)
										END)						 [ct_total],

					CASE tct.ct_total WHEN tct.ct_ATotal THEN
 					tc.curr_desc
					ELSE
					tc2.curr_desc
					END						 [curr_desc],
					tc3.cust_name,
					isnull(tc3.cust_phone1,tc3.cust_phone2) [cust_phone],


					CASE
						-- Domicilio de entrega especificado en el pedido
						WHEN tcdd.comp_id IS NOT NULL AND dbo.fnStrAllTrim(ISNULL(tcdd.ctd_note1,'')) <> ''	THEN	tcdd.ctd_note1
						-- Domicilio de la Sucursal del Cliente
						WHEN tcb.comp_id IS NOT NULL														THEN	isnull(tcb.custb_address,'') + ' ' + isnull(tcb.custb_city,'') + ' ' + isnull(tsb.state_desc,'')
						-- Domicilio del Cliente
						WHEN dbo.fnStrAllTrim(ISNULL(tc3.cust_address4Delivery,'')) = ''					THEN	isnull(tc3.cust_address,'')  + ' ' + isnull(tc3.cust_city,'')  + ' ' + isnull(ts.state_desc,'')
					ELSE
						-- Domicilio de Entrega del archivo de Clientes
						isnull(tc3.cust_address4Delivery,isnull(tc3.cust_address,'')  + ' ' + isnull(tc3.cust_city,'') + ' ' + isnull(ts.state_desc,'') )
					END						 [cust_address],




					ISNULL(tc3.cust_taxNumber,'')					[cust_taxNumber],
					tc3.cust_id										[cust_id],
					isnull(ti.item_desc,'')							[item_desc],
					tit.it_qty										[it_qty],
					tstr.stor_desc									[stor_desc],
					ISNULL(tov.optval_desc,'')						[it_isBlocked4Delivery], -- descrpcion "NO ENTREGAR" si esta bloqueado para entrega
					tit.it_deliveryDate								[it_deliveryDate],
					isnull(tctn.ctn_deliveryAddressOfSaleOrder,'')	[ctn_deliveryAddressOfSaleOrder],
					CONVERT(VARCHAR,tdsd.rmah_id)+ '-' + CONVERT(VARCHAR,tdsd.rmad_id) [rmah_id],
					--tdsd.rmah_id,
					tdsd.rmad_id,
					tcrma.cust_name									[cust_name_rma],
					trd.rmad_qty,
					trd.rmad_deliveryDate4Picking,
					trd.rmad_deliveryDate4Delivery,
					CASE WHEN tdsd.rmad_id IS NOT NULL THEN
						case when tdsd.dsd_isRMA4Picking = 0 then
							(SELECT tut.utexts_desc
								FROM tbsysUniqueTexts tut	WITH (NOLOCK)  WHERE tut.lang_id = @lang_id AND tut.utexts_id = 40213)--entregar
						ELSE
							(SELECT tut.utexts_desc
									FROM tbsysUniqueTexts tut	WITH (NOLOCK)  WHERE tut.lang_id = @lang_id AND tut.utexts_id = 40212)--retirar
						end

						ELSE
									convert(varchar,'')

						END										[dsd_isRMA4Picking],
					--ISNULL(tcrma.cust_address4RMA,tcrma.cust_address)		    [cust_address4RMA],
					CASE WHEN tcrma.cust_address4RMA <> '' THEN
						isnull(tcrma.cust_address4RMA,'')+ ' ' + isnull(tcrma.cust_city,'') + ' ' + isnull(tcrma.cust_zip,'')  + ' ' + isnull(tsrma.state_desc,'') + ' ' + isnull(tcrma.cust_phone1,'')
						ELSE
							tcrma.cust_address + ' ' + isnull(tcrma.cust_city,'') + ' ' + isnull(tcrma.cust_zip,'')  + ' ' + isnull(tsrma.state_desc,'') + ' ' + isnull(tcrma.cust_phone1,'')
							END								[cust_address4RMA],

					isnull(tirma.item_desc,'')					[item_desc_rma],
					isnull(tctn.ctn_note1,'')					[ctn_note1],
					isnull(tctn.ctn_note2,'')					[ctn_note2],
					isnull(tctn.ctn_note3,'')					[ctn_note3],
					isnull(tctn.ctn_note4,'')					[ctn_note4],

					CONVERT(VARCHAR,convert(decimal(19,2),trd.rmad_originalPrice)) + ' ' + CONVERT(VARCHAR,tscrma.curr_symbol) [AddItemsImportIVA],

					(SELECT
						CONVERT(VARCHAR,SUM(convert(decimal(19,2),trdai.rmaa_qty *
						dbo.fnGetExchange2(@comp_id, tpli.prli_price * dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,ti.item_id)), tc.curr_id, @lcurr_id, 0,0,0,0)))) + ' ' + CONVERT(VARCHAR,tc2.curr_symbol)

						FROM tbRMA_Detail_AddItems			trdai		WITH (NOLOCK)
						INNER JOIN tbItem					ti			WITH (NOLOCK)
							ON	ti.comp_id		= trdai.comp_id	AND
								ti.item_id		= trdai.item_id
						LEFT JOIN tbPriceListItems			tpli		WITH (NOLOCK)
							ON	tpli.comp_id	= trdai.comp_id	AND
								tpli.prli_id	= @prli_id4RMA	AND
								tpli.item_id	= trdai.item_id
						LEFT JOIN tbsysCurrency				tc			WITH (NOLOCK)
							ON	tc.curr_id		= tpli.curr_id
						LEFT JOIN tbsysCurrency				tc2			WITH (NOLOCK)
							ON	tc2.curr_id		= @lcurr_id

						WHERE	trdai.comp_id	= @comp_id		AND
								trdai.rmah_id	= trh.rmah_id
						GROUP BY tc2.curr_symbol
					)																				[AddItemsTotals], --Total con IVA de Art. Adicionales

					--198d7f098a90sd8a098fds908da0f98
					'Artículos despachados : ' + CONVERT(VARCHAR,(SELECT
																	COUNT(*)
																	FROM tbItemTransactionsDelivery						titd	WITH(NOLOCK)
																	WHERE	titd.comp_id						= tit.comp_id			AND
																			titd.ct_transaction					= tit.ct_transaction	AND
																			titd.it_transaction					= tit.it_transaction	AND
																			ISNULL(titd.itd_isPending,'False')	= 'False')) + ' de ' + CONVERT(VARCHAR, CONVERT(INT,tit.it_qty)) [itd_isPending],



					ISNULL(ti.item_code,'') [item_code],
					--dbo.fnGetEAN_Encode4EAN13(dbo.fnStrPADL(dbo.fnGetOnlyNumbers(isnull(tdsd.ds_ct_transaction,'')),13, '0'),'False')  [ct_transactino4BarCode]
					--dbo.fnStrPADL(dbo.fnGetOnlyNumbers(isnull(tdsd.ds_ct_transaction,'')),7, '0')  [ct_transactino4BarCode]
					--isnull(tdsd.ds_ct_transaction,'')  [ct_transactino4BarCode]
					--'*' + ' ' + dbo.fnStrPADL(isnull(tdsd.ds_ct_transaction,''),10, '0') + ' ' + '*'				[ct_transactino4BarCode]
					dbo.fnGetEAN_Encode4EAN13(dbo.fnStrPADL(dbo.fnGetOnlyNumbers(isnull(tdsd.ds_ct_transaction,'')),13, '0'),'False')	 [ct_transactino4BarCode],




					-- ---------------------------------------------------------
					-- MOS 01-2022
					-- ---------------------------------------------------------
						CASE	-- MOS: 01-2022 para poder ver en la cta cte los relacionados de fc anticipada.
							-- Si es una Fc Anticipada:
							WHEN	tct.sd_id = 1 AND
									tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL	THEN	(
																										SELECT TOP 1 dbo.fnGetCommercialTransactionDescription(tmpPR.comp_id,2,tmpPR.ct_transaction_packingList)	+
																												' / ' + dbo.fnStrPADL(  CONVERT(VARCHAR(15),ISNULL(tmpPR.bra_id,0)), 5, '0') 		+ '-'	+
																													  + dbo.fnStrPADL(  CONVERT(VARCHAR(15),ISNULL(tmpPR.soh_id,0)),8,'0')
																											FROM	dbo.vwCommercialTransactions_preInvoice_PackingListRelation tmpPR		WITH (NOLOCK)
																											WHERE	tmpPR.comp_id					= tct.comp_id			AND
																													tmpPR.bra_id					= tct.bra_id			AND
																													tmpPR.ct_transaction_preInvoice = tct.ct_transaction
																									)
							-- Si es un Remito de Fc Anticipada
							WHEN	tct.sd_id = 2 AND
									tdf.df_SaleOrder_IsInvoiceFirstPacking = 'True'		THEN	(
																									SELECT  TOP 1 dbo.fnGetCommercialTransactionDescription(tmpPR.comp_id,2,tmpPR.ct_transaction_preInvoice)	+
																												' / ' + dbo.fnStrPADL(  CONVERT(VARCHAR(15),ISNULL(tmpPR.bra_id,0)), 5, '0') 	+ '-'	+
																													  + dbo.fnStrPADL(  CONVERT(VARCHAR(15),ISNULL(tmpPR.soh_id,0)),8,'0')
																										FROM	dbo.vwCommercialTransactions_preInvoice_PackingListRelation tmpPR			WITH (NOLOCK)
																										WHERE	tmpPR.comp_id					= tct.comp_id			AND
																												tmpPR.bra_id					= tct.bra_id			AND
																												tmpPR.ct_transaction_packingList = tct.ct_transaction
																								)
							ELSE																''
						END		[preInvoiceStatus],

						CASE	-- MOS: 01-2022 para poder ver el SALDO ya sea una Fc o un Remito de Fc Anticipada.
							-- Si es una Fc Anticipada:
							WHEN	tct.sd_id = 1 AND
									tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL	THEN	ISNULL(tc2.curr_symbol,'') + ' ' +
																									CONVERT(NVARCHAR(50),CONVERT(DECIMAL(19,2),ISNULL(tct.ct_ABalance,0)))

							-- Si es un Remito de Fc Anticipada
							WHEN	tct.sd_id = 2 AND
									tdf.df_SaleOrder_IsInvoiceFirstPacking = 'True'		THEN	(
																									SELECT  TOP 1	ISNULL(tc2X.curr_symbol,'') + ' ' +
																													CONVERT(NVARCHAR(50),CONVERT(DECIMAL(19,2),ISNULL(tct2.ct_ABalance,0)))

																										FROM	dbo.vwCommercialTransactions_preInvoice_PackingListRelation tmpPR			WITH (NOLOCK)
																										INNER JOIN tbCommercialTransactions								 AS tct2			WITH (NOLOCK)
																											ON	tct2.comp_id		= tmpPR.comp_id						AND
																												tct2.ct_transaction = tmpPR.ct_transaction_preInvoice
																										INNER JOIN tbsysCurrency										 AS tc2X			WITH (NOLOCK)
																											ON tc2X.curr_id = tct2.ct_ACurrency
																										WHERE	tmpPR.comp_id					= tct.comp_id			AND
																												tmpPR.bra_id					= tct.bra_id			AND
																												tmpPR.ct_transaction_packingList = tct.ct_transaction
																								)
							ELSE																	ISNULL(tc2.curr_symbol,'') + ' ' +
																									CONVERT(NVARCHAR(50),CONVERT(DECIMAL(19,2),ISNULL(tct.ct_ABalance,0)))
						END		[aBalance],
					-- ---------------------------------------------------------


					tctq.ctQR_Image4Logistic

					--STL 28-12-2018 CAMBIE ESTO POR LO DE ARRIBA YA QUE SI JOINNEABA ABAJO ME TRAIA UN REGISTRO POR CADA ITEM DE LA FC
					--CASE
					--	WHEN ISNULL(titd.itd_isPending,'False') = 'False' THEN	@ArtículoDespachado
					--	ELSE													''
					--END																				[itd_isPending]


					--STL 23-03-2017
					--SE QUITO ESTE CAMPO, PORQUE SE LLAMABA EXACTAMENTE IGUAL A UNO ANTERIOR, AL ESTAR UNO VACÍO
					--SE VE QUE TOMA ALGUNO POR DEFECTO COMO EL VÁLIDO Y PISA AL OTRO, O NO MUESTRA NINGUNO
					--CASE
					--	WHEN ISNULL(tit.it_isBlocked4Delivery,'False') = 'False' THEN	@strNO
					--ELSE																@strSI
					--END												[it_isBlocked4Delivery]

			FROM tbDeliverySheetHeader							tdsh			WITH (NOLOCK)

			INNER JOIN tbDeliverySheetDetail					tdsd			WITH (NOLOCK)
			ON  tdsd.comp_id			= tdsh.comp_id			AND
			--AND tdsd.bra_id			= tdsh.bra_id
				tdsd.ds_id				= tdsh.ds_id

			LEFT JOIN tbRMA_Header								trh				WITH (NOLOCK)
			ON trh.comp_id				= tdsd.comp_id			AND
			   trh.rmah_id				= tdsd.rmah_id

			LEFT JOIN tbRMA_Detail								trd				WITH (NOLOCK)
			ON	trd.comp_id				= trh.comp_id			AND
				trd.rmah_id				= tdsd.rmah_id			AND
				trd.rmad_id				= tdsd.rmad_id

			LEFT JOIN tbsysCurrency								tscrma			WITH (NOLOCK)
			ON	tscrma.curr_id			= trd.curr_id

			LEFT JOIN tbCustomer								tcrma			WITH (NOLOCK)
			ON	tcrma.comp_id			= trh.comp_id			AND
				tcrma.cust_id			= trh.cust_id

			LEFT JOIN tbsysCountry								tc4rma			WITH (NOLOCK)
			ON    tc4rma.country_id		= tcrma.country_id

			LEFT JOIN tbsysState								tsrma			WITH (NOLOCK)
			ON  tsrma.country_id		= tc4rma.country_id		AND
				tsrma.state_id			= tcrma.state_id

			LEFT JOIN tbItem									tirma			WITH (NOLOCK)
			ON	tirma.comp_id			= trd.comp_id			AND
				tirma.item_id			= trd.item_id

			LEFT JOIN tbCommercialTransactions					tct				WITH (NOLOCK)
			on  tct.comp_id				= tdsd.comp_id			AND
			--AND tct.bra_id			= tdsd.bra_id
				tct.ct_transaction		= tdsd.ds_ct_transaction

			LEFT JOIN tbDocumentsFile						AS tdf				WITH (NOLOCK)
				ON	tdf.comp_id			= tct.comp_id AND
					tdf.df_id			= tct.df_id

			LEFT JOIN tbCommercialTransactionsDelivery			tcdd			WITH (NOLOCK)
				ON	tcdd.comp_id		= tct.comp_id	AND
					tcdd.bra_id			= tct.bra_id	AND
					tcdd.ct_transaction = tct.ct_transaction

			LEFT JOIN tbCommercialTransactionNotes				tctn			WITH (NOLOCK)
			ON	tctn.comp_id			= tct.comp_id			AND
				tctn.bra_id				= tct.bra_id			AND
				tctn.ct_transaction		= tct.ct_transaction

			LEFT JOIN tbItemTransactions						tit				WITH (NOLOCK)
			ON	tit.comp_id				= tct.comp_id			AND
				tit.bra_id				= tct.bra_id			AND
				tit.ct_transaction		= tct.ct_transaction	AND
				tit.sdlmt_id			= 2

			-- -------------------------------------------------------------------
			-- 21-05-2018  STL Ticket de Authogar 127 --VER 198d7f098a90sd8a098fds908da0f98
			-- -------------------------------------------------------------------
			--LEFT JOIN tbItemTransactionsDelivery			titd
			--ON	titd.comp_id		= tit.comp_id			AND
			--	titd.ct_transaction	= tit.ct_transaction	AND
			--	titd.it_transaction	= tit.it_transaction
			-- -------------------------------------------------------------------

			LEFT JOIN tbStorage									tstr			WITH (NOLOCK)
			ON 	tstr.comp_id		= tit.comp_id			AND
				tstr.stor_id		= tit.stor_id

			LEFT JOIN tbItem									ti				WITH (NOLOCK)
			ON	ti.comp_id			= tit.comp_id			AND
				ti.item_id			= tit.item_id

			LEFT join tbsysCurrency								tc				WITH (NOLOCK)
			on tc.curr_id			= tct.curr_id_transaction

			LEFT join tbsysCurrency								tc2				WITH (NOLOCK)
			on tc2.curr_id			= tct.ct_ACurrency

			INNER JOIN tbBranch									tb				WITH (NOLOCK)
			ON  tb.comp_id			= tdsh.comp_id				AND
				tb.bra_id			= tdsh.bra_id

			LEFT JOIN tbDelivery								td				WITH (NOLOCK)
			ON  td.comp_id			= tdsh.comp_id				AND
				td.dl_id			= tdsh.dl_id

			LEFT JOIN tbCustomer								tc3				WITH (NOLOCK)
			ON	tc3.comp_id			= tct.comp_id				AND
				tc3.cust_id			= tct.cust_id

			LEFT JOIN tbsysCountry								tc4				WITH (NOLOCK)
			on    tc4.country_id	= tc3.country_id

			LEFT JOIN tbsysState								ts				WITH (NOLOCK)
			ON  ts.country_id		= tc4.country_id			AND
				ts.state_id			= tc3.state_id




			LEFT JOIN tbCustomerBranch					     AS tcb				WITH (NOLOCK)
				ON	tcb.comp_id = tct.comp_id AND
					tcb.cust_id = tct.cust_id AND
					tcb.cb_id	= tct.cb_id

			LEFT JOIN tbsysCountry								tc4B				WITH (NOLOCK)
			on    tc4B.country_id	= tcb.country_id

			LEFT JOIN tbsysState								tsB				WITH (NOLOCK)
			ON  tsB.country_id		= tcb.country_id			AND
				tsB.state_id		= tcb.state_id


			LEFT JOIN tbsysOptionsValues						tov				WITH (NOLOCK)
			ON	tov.lang_id			= @lang_id										AND
				tov.optval_id		= isnull(tit.it_isBlocked4Delivery,'FALSE')		AND -- descrpcion "NO ENTREGAR" si esta bloqueado para entrega
				tov.optval_class	= 542

			LEFT JOIN tbCommercialTransactions_QRImage AS tctq	WITH (NOLOCK)
				ON	tctq.comp_id		= tct.comp_id					AND
					tctq.ct_transaction = tct.ct_transaction



			WHERE tdsd.comp_id		= @comp_id
			--AND   tdsd.bra_id		= @bra_id
			AND   tdsd.ds_id		= @ds_id





			order by tdsd.dsd_order,tdsd.ds_ct_transaction,tdsd.ds_note

			exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


			-----------------------------
			-- SUBREPORTES
			-----------------------------


--			SELECT ti.item_desc,tct.ct_transaction
--
--
--				FROM tbDeliverySheetHeader										tdsh
--
--				INNER JOIN tbDeliverySheetDetail								tdsd
--				ON  tdsd.comp_id		= tdsh.comp_id
--				AND tdsd.bra_id			= tdsh.bra_id
--				AND tdsd.ds_id			= tdsh.ds_id
--
--				inner join tbCommercialTransactions								tct
--				on  tct.comp_id			= tdsd.comp_id
--				AND tct.bra_id			= tdsd.bra_id
--				AND tct.ct_transaction  = tdsd.ds_ct_transaction
--
--				INNER JOIN tbItemTransactions									tit
--				ON  tit.comp_id				= tct.comp_id			AND
--					tit.bra_id				= tct.bra_id			AND
--					tit.ct_transaction		= tct.ct_transaction
--
--				left JOIN tbItem												ti
--				ON	ti.comp_id				= tit.comp_id			AND
--					ti.item_id				= tit.item_id
--
--				WHERE		 tdsd.comp_id		= @comp_id
--				AND			 tdsd.bra_id		= @bra_id
--				AND			 tdsd.ds_id			= @ds_id


END

GO



--Si se toca este SP, también corroborar spDeliverySheetDetail_InsertData4Excel

CREATE PROCEDURE [dbo].[spDeliverySheetDetail_InsertData]
(
	@comp_id		   INT,
	@bra_id			   INT,
	@ds_id			   INT,
	@ds_bra_id		   INT,
	@ds_ct_transaction INT,
	@ds_note		   VARCHAR(4000),
	@dsd_order		   INT
)

AS
SET NOCOUNT ON

-------------------------------------------------------------
/*

DECLARE @comp_id		   INT,
		@bra_id			   INT,
		@ds_id			   INT,
		@ds_bra_id		   INT,
		@ds_ct_transaction INT,
		@ds_note		   VARCHAR(4000),
		@dsd_order		   INT



SELECT	@comp_id		   = 1,
		@bra_id			   = 1,
		@ds_id			   = 1,
		@ds_bra_id		   = 1,
		@ds_ct_transaction = 3004,
		@ds_note		   = '',
		@dsd_order		   = 9999

*/
-------------------------------------------------------------



BEGIN


		if	(@ds_ct_transaction			= -1)	set	@ds_ct_transaction			= NULL


		IF NOT EXISTS (
					   SELECT 1
		               FROM tbDeliverySheetDetail tdsd
		               WHERE tdsd.comp_id				= @comp_id				AND
							 tdsd.bra_id				= @bra_id				AND
							 tdsd.ds_ct_transaction		= @ds_ct_transaction
						)


		BEGIN

			INSERT INTO tbDeliverySheetDetail
				(
					comp_id,
					bra_id,
					ds_id,
					ds_bra_id,
					ds_ct_transaction,
					ds_note,
					dsd_order
				)
				VALUES
				(
					@comp_id,
					@bra_id	,
					@ds_id	,
					@ds_bra_id,
					@ds_ct_transaction,
					@ds_note,
					@dsd_order
				)


		END



END
GO



