CREATE PROCEDURE spDeliverySheetDetail_InsertDataBySOHID
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT,
	@ds_id		INT,
	@ds_bra_id	INT,
	@ds_note	VARCHAR(4000),
	@dsd_order	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@soh_id		INT
				@ds_id		INT,
				@ds_bra_id	INT,
				@ds_note	VARCHAR(4000),
				@dsd_order	INT

			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@soh_id		= 1
		*/
		-- ----------------------------------------------

		-- -------------------------------------------------------
		-- VARIABLES DE TRABAJO
			DECLARE
				@lct_transaction	INT
		-- -------------------------------------------------------


		IF (@lct_transaction	= -1)
			BEGIN
				SET	@lct_transaction	= NULL
			END

		-- Recupero el ct_transaction en base al soh_id y al soh_bra_id
		SELECT
			@lct_transaction = tct.ct_transaction
		FROM tbCommercialTransactions			AS tct	WITH(NOLOCK)
		WHERE	tct.comp_id			= @comp_id	AND
				tct.ct_soh_bra_id	= @bra_id	AND
				tct.ct_soh_id		= @soh_id

		IF @lct_transaction IS NOT NULL
			BEGIN
				--Pregunto si ya existe ese ct_transaction cargado
				IF NOT EXISTS (
							   SELECT 1
							   FROM tbDeliverySheetDetail tdsd
							   WHERE tdsd.comp_id				= @comp_id				AND
									 tdsd.bra_id				= @bra_id				AND
									 tdsd.ds_ct_transaction		= @lct_transaction
							  )
					BEGIN
						INSERT INTO tbDeliverySheetDetail
						(
							comp_id,
							bra_id,
							ds_id,
							ds_bra_id,
							ds_ct_transaction,
							ds_note,
							dsd_order
						)
						VALUES
						(
							@comp_id,
							@bra_id,
							@ds_id,
							@ds_bra_id,
							@lct_transaction,
							@ds_note,
							@dsd_order
						)
						SELECT 'True' [Inserted]
					END
				ELSE
					BEGIN
						SELECT 'False' [Inserted]
					END


			END
		ELSE
			BEGIN
				--ACA TENGO QUE INFORMAR QUE ESE NUMERO DE PEDIDO NO EXISTE DE ALGUNA FORMA
				SELECT 'False' [Inserted]
			END

	END


GO

