CREATE PROCEDURE [dbo].[spDeliverySheetDetail4RMA_InsertData]
(
	@comp_id		   INT,
	@bra_id			   INT,
	@ds_id			   INT,
	@ds_bra_id		   INT,
	@rmad_id		   INT,
	@ds_note		   VARCHAR(4000),
	@dsd_order		   INT,
	@dsd_isRMA4Picking INT,
	@user_id		   INT,
	@return_value		as int	output

)

AS
SET NOCOUNT ON

-------------------------------------------------------------
/*

DECLARE @comp_id		   INT,
		@bra_id			   INT,
		@ds_id			   INT,
		@ds_bra_id		   INT,
		@ds_ct_transaction INT,
		@ds_note		   VARCHAR(4000),
		@dsd_order		   INT



SELECT	@comp_id		   = 1,
		@bra_id			   = 1,
		@ds_id			   = 1,
		@ds_bra_id		   = 1,
		@ds_ct_transaction = 3004,
		@ds_note		   = '',
		@dsd_order		   = 9999

*/
-------------------------------------------------------------



BEGIN

		DECLARE @LSDS_ID AS INT

		SET @LSDS_ID = 1

		if @dsd_isRMA4Picking = 1
			BEGIN
				SET @LSDS_ID = 11
			END
		ELSE
			BEGIN
				SET @LSDS_ID = 1
			END



		Set @return_value	= 0

		DECLARE @lrmah_id INT

				SET @lrmah_id = (SELECT trd.rmah_id FROM tbRMA_Detail trd
									WHERE	trd.comp_id   = @comp_id
									AND		trd.rmad_id   = @rmad_id
				)


		IF NOT EXISTS (
					   SELECT 1
		               FROM tbDeliverySheetDetail tdsd
		               WHERE tdsd.comp_id				= @comp_id				AND
							 tdsd.bra_id				= @bra_id				AND
							 tdsd.rmah_id				= @lrmah_id				AND
							 tdsd.rmad_id				= @rmad_id				AND
							 tdsd.dsd_isRMA4Picking		= @dsd_isRMA4Picking
						)


		BEGIN

			INSERT INTO tbDeliverySheetDetail
				(
					comp_id,
					bra_id,
					ds_id,
					ds_bra_id,
					ds_ct_transaction,
					ds_note,
					dsd_order,
					rmah_id,
					rmad_id,
					dsd_isRMA4Picking,
					dsd_status0_cd,
					dsd_status0_user_id,
					sds_id
				)
				VALUES
				(
					@comp_id,
					@bra_id	,
					@ds_id	,
					@ds_bra_id,
					NULL,
					@ds_note,
					@dsd_order,
					@lrmah_id,
					@rmad_id,
					@dsd_isRMA4Picking,
					GETDATE(),
					@user_id,
					@LSDS_ID
				)



		IF @@ERROR = 0 and @@ROWCOUNT = 1
		BEGIN
				Set @return_value = @@IDENTITY
		END

		END



END
GO




CREATE PROCEDURE [dbo].[spDeliverySheetDetail4RMA_UpdateStatus]
(
	@comp_id		   INT,
	@bra_id			   INT,
	@dsd_id			   INT,
	@ds_status		   INT,
	@user_id		   INT



)
AS
SET NOCOUNT ON


BEGIN
					-----------------
					--Update Detail tbDeliverySheetDetail
					UPDATE tbDeliverySheetDetail
						SET		sds_id	= @ds_status
						WHERE	comp_id = @comp_id
						AND		bra_id  = @bra_id
						AND		dsd_id   = @dsd_id



					-- ---------------------------------------------------------------
					-- Reemplaza este estado en rma detail si es que corresponde
					-- ---------------------------------------------------------------
					DECLARE @rmah_id	AS INT
					DECLARE @rmad_id	AS INT
					DECLARE @is4Picking AS BIT
					SELECT  @rmah_id	= tdsd.rmah_id,
							@rmad_id	= tdsd.rmad_id,
							@is4Picking =  isnull(tdsd.dsd_isRMA4Picking,'False')
					FROM tbDeliverySheetDetail tdsd
						WHERE	comp_id = @comp_id
								AND		bra_id  = @bra_id
								AND		dsd_id  = @dsd_id


					IF @rmad_id IS NOT NULL
						BEGIN

							--SELECT 1 / 0

							UPDATE tbRMA_Detail
							SET	sds_id4Delivery =	CASE
														WHEN @is4Picking = 'True' THEN	sds_id4Delivery
														ELSE							@ds_status
													END,
								dsd_id4Delivery =   CASE
														WHEN @is4Picking = 'True' THEN	dsd_id4Delivery
														ELSE							@dsd_id
													END,
							 	sds_id4Picking =	CASE
														WHEN @is4Picking = 'False' THEN	sds_id4Picking
														ELSE							@ds_status
													END,
								dsd_id4Picking  =	CASE
														WHEN @is4Picking = 'False' THEN	dsd_id4Picking
														ELSE							@dsd_id
													END

								WHERE	comp_id = @comp_id AND
										rmah_id = @rmah_id AND
										rmad_id = @rmad_id
						END
					-- ---------------------------------------------------------------

					-------------------
					----Update Detail tbRMA_Detail
					--EXEC [spRMA_Detail_Update_DeliverySheetDetail] @comp_id,@bra_id,@dsd_id,@user_id



					IF @ds_status = 0
						BEGIN
							--No Asignado
							UPDATE tbDeliverySheetDetail
								SET
									dsd_status0_cd = GETDATE(),
									dsd_status0_user_id = @user_id
								WHERE	comp_id = @comp_id
								AND		bra_id  = @bra_id
								AND		dsd_id   = @dsd_id
						END

					IF @ds_status = 1 or @ds_status = 11
						-- Espera Envío / Espera Retiro
						BEGIN
							UPDATE tbDeliverySheetDetail
								SET
									dsd_status1_cd = GETDATE(),
									dsd_status1_user_id = @user_id
								WHERE	comp_id = @comp_id
								AND		bra_id  = @bra_id
								AND		dsd_id   = @dsd_id
						END

					IF @ds_status = 2 or @ds_status = 12
						-- Enviando / Retirando
						BEGIN
							UPDATE tbDeliverySheetDetail
								SET
									dsd_status2_cd = GETDATE(),
									dsd_status2_user_id = @user_id
								WHERE	comp_id = @comp_id
								AND		bra_id  = @bra_id
								AND		dsd_id   = @dsd_id
						END

					IF @ds_status = 3 or @ds_status = 13
						-- Enviado / Retirado
						BEGIN
							UPDATE tbDeliverySheetDetail
								SET
									dsd_status3_cd = GETDATE(),
									dsd_status3_user_id = @user_id
								WHERE	comp_id = @comp_id
								AND		bra_id  = @bra_id
								AND		dsd_id   = @dsd_id
						END

					IF @ds_status = 4 or @ds_status = 14
						--Envío Cancelado/Retiro Cancelado
						BEGIN
							UPDATE tbDeliverySheetDetail
								SET
									dsd_status4_cd = GETDATE(),
									dsd_status4_user_id = @user_id
								WHERE	comp_id = @comp_id
								AND		bra_id  = @bra_id
								AND		dsd_id   = @dsd_id
						END




END


GO






CREATE PROCEDURE [dbo].[spDeliverySheetHeader_DeleteData]
(
	@comp_id		   INT,
	@bra_id			   INT,
	@ds_id			   INT
)
AS
SET NOCOUNT ON

IF EXISTS(SELECT 1 FROM tbDeliverySheetDetail tdsd
          WHERE tdsd.comp_id = @comp_id
          AND   tdsd.bra_id  = @bra_id
          AND   tdsd.ds_id   = @ds_id)
  BEGIN
	DELETE tbDeliverySheetDetail
	WHERE  comp_id = @comp_id
    AND    bra_id  = @bra_id
    AND    ds_id   = @ds_id
  END


DELETE tbDeliverySheetHeader
WHERE comp_id = @comp_id
AND   bra_id  = @bra_id
AND   ds_id   = @ds_id




GO






