--tkt 20352
--11/03/24
--fecha de entrega desde y hasta



CREATE PROCEDURE [dbo].[spDeliverySheetHeader_GetComboComprobante]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@IsDeliveryDocument	BIT,			-- Solo Documentos del Transporte
	@ds_id				INT,
	@cust_id			INT,
	@brag_id			INT,
	@deliverydatefrom		DATETIME,		--	 fecha de entrega desde tkt 20352
	@deliverydateto			DATETIME		--	 fecha de entrega hasta tkt 20352
)

AS


BEGIN


	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'

	-- ----------------------------------------------
	-- TESTING
	-- ----------------------------------------------
	/*
		DECLARE 	@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@datefrom			DATETIME,
					@dateto				DATETIME,
					@IsDeliveryDocument	BIT,
					@ds_id				INT,
					@cust_id			INT,
					@brag_id			INT,
					@deliverydatefrom		DATETIME,		--	 fecha de entrega desde tkt 20352
					@deliverydateto			DATETIME		--	 fecha de entrega hasta tkt 20352

		SELECT		@comp_id			=1,
					@lang_id			=2,
					@bra_id				=34,
					@datefrom			='2024-01-21 00:00:00AM',
					@dateto				='2024-12-31 23:59:00PM',
					@IsDeliveryDocument	='False',
					@ds_id				= 2500,
					@cust_id			= -1,
					@brag_id			= -1,
					@deliverydatefrom			='2024-01-01 00:00:00AM',
					@deliverydateto				='2024-12-31 23:59:00PM'
*/
	-- ----------------------------------------------


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE @tblBranch TABLE(bra_id INT PRIMARY KEY CLUSTERED)
	IF @brag_id = -1
		BEGIN
			INSERT INTO @tblBranch(bra_id)
				SELECT bra_id
				FROM tbBranch tb		WITH (NOLOCK)
				WHERE	tb.comp_id		= @comp_id AND
						tb.bra_disabled = 'False'
		END
	ELSE
		BEGIN
			INSERT INTO @tblBranch(bra_id)
				SELECT DISTINCT  tb.bra_id
					FROM tbBranch tb						WITH (NOLOCK)
					INNER JOIN tbBranchGroupDetail tbgd		WITH (NOLOCK)
					ON	tbgd.comp_id	= tb.comp_id	AND
						tbgd.bra_id		= tb.bra_id
					WHERE	tbgd.comp_id = @comp_id		AND
							tbgd.brag_id = @brag_id		AND
							tb.bra_disabled = 'False'

		END










	-- NO PONES ESTO ya que viene con Fecha y HOra informada !!!!
	--SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	--SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	-- Modo de Obtener Comprobantes Disponibles
	-- 0: Normal
	-- 1: Todas Las Sucursales
	-- 2: Todas Las Sucursales con sdlme=Enviar
	DECLARE @intMode AS INT
	SET		@intMode = 0
	SELECT  @intMode =  IsNull(tb.bra_deliverySheetMode,0)
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id



	DECLARE @tmpCT TABLE(ct_transaction INT PRIMARY KEY CLUSTERED)


	INSERT INTO @tmpCT(ct_transaction)
			SELECT DISTINCT TOP 5000
				tct.ct_transaction
				FROM tbCommercialTransactions					tct		WITH (NOLOCK)

				INNER JOIN @tblBranch ooo
					ON ooo.bra_id = tct.bra_id


				LEFT JOIN tbDeliverySheetDetail					r		WITH (NOLOCK)
					ON  r.comp_id			= tct.comp_id		AND
						r.ds_ct_transaction	= tct.ct_transaction

				INNER JOIN tbDeliverySheetHeader				tdsh	WITH (NOLOCK)
					ON	tdsh.comp_id		= @comp_id			AND
						tdsh.ds_id			= @ds_id			AND
						CASE
							WHEN	@IsDeliveryDocument = 'False'		THEN 1
							WHEN	@IsDeliveryDocument = 'True' AND
									tdsh.dl_id			= tct.dl_id		THEN 1
							ELSE											 0
						END = 1

				INNER JOIN tbDelivery							td		WITH (NOLOCK)
					ON	td.comp_id			= tdsh.comp_id		AND
						td.dl_id			= tdsh.dl_id

				INNER JOIN tbDocumentsFile						tdf		WITH (NOLOCK)
					ON	tdf.comp_id			= tct.comp_id		AND
						--tdf.bra_id			= tct.bra_id		AND
						tdf.df_id			= tct.df_id

				LEFT JOIN tbItemTransactions					tit		WITH (NOLOCK)
					ON	tit.comp_id			= tct.comp_id		AND
						tit.ct_transaction	= tct.ct_transaction

				WHERE	tct.comp_id = @comp_id	AND
						CASE
							WHEN @intMode = 2  AND tit.it_deliveryDate BETWEEN @datefrom AND @dateto THEN 1
							WHEN @intMode <> 2 AND tct.ct_cd BETWEEN @datefrom AND @dateto			 THEN 1
							ELSE																		 0
						END	= 1		AND

						CASE
							WHEN @intMode = 2  AND  tct.sd_id = 1																THEN 1
							WHEN @intMode <> 2 AND (tct.sd_id = 1 OR tct.sd_id = 2 OR tct.sd_id = 3 OR tct.sd_id = 4)			THEN 1
							ELSE																									 0
						END = 1				AND
						r.comp_id IS NULL	AND
						IsNull(tdf.df_deliverySheetExcluded,'False') = 'False'		AND
						CASE
							WHEN @intMode <> 2											THEN 1
							WHEN td.sdlmt_id IS NOT NULL AND tit.sdlmt_id = td.sdlmt_id THEN 1
							WHEN td.sdlmt_id IS NULL									THEN 1
							ELSE															 0
						END	= 1																AND
					   (@cust_id = -1 OR tct.cust_id = @cust_id)
					   AND		((tct.ct_deliveryDate		BETWEEN      @deliverydatefrom		AND @deliverydateto) OR tct.ct_deliveryDate IS NULL)



			SELECT DISTINCT
				tct.ct_transaction								[ID],
				dbo.fnStrPADR( dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction),23,' ') + ' * ' +
				convert(varchar, tct.ct_cd, 103) + ' ' + dbo.fnStrPADL( convert(varchar,DATEPART(hour,tct.ct_cd)),2,'0') + ':' + dbo.fnStrPADL(convert(varchar,DATEPART(minute,tct.ct_cd)),2,'0') + ' * ' +
				dbo.fnStrPADR( tc.cust_name,30,'-') +
				' * ' + /*tc.cust_address*/
				CASE
					WHEN ctn.ctn_deliveryAddressOfSaleOrder IS NOT NULL AND
						 ctn.ctn_deliveryAddressOfSaleOrder <> ''		THEN ctn.ctn_deliveryAddressOfSaleOrder
					WHEN tcf.comp_id IS NOT NULL						THEN tcf.custf_address
					WHEN tcb.comp_id IS NOT NULL						THEN tcb.custb_address
					WHEN ISNULL(tc.cust_address4Delivery,'') <> ''		THEN tc.cust_address4Delivery
					ELSE													 tc.cust_address
				END
														[DESC]

				FROM tbCommercialTransactions					tct		WITH (NOLOCK)
				INNER JOIN @tmpCT tmp
					ON tmp.ct_transaction	= tct.ct_transaction

				INNER JOIN tbCustomer							tc		WITH (NOLOCK)
					ON	tc.comp_id			= tct.comp_id		AND
						tc.cust_id			= tct.cust_id

				LEFT JOIN tbCustomerFamily tcf							WITH (NOLOCK)
					ON	tcf.comp_id		= tct.comp_id AND
						tcf.cust_id		= tct.cust_id AND
						tcf.custf_id	= tct.custf_id

				LEFT JOIN tbCustomerBranch tcb							WITH (NOLOCK)
					ON		tcb.comp_id = tct.comp_id
						AND tcb.cust_id = tct.cust_id
						AND tcb.cb_id	= tct.cb_id

				left join dbo.tbCommercialTransactionNotes		CTN		WITH (NOLOCK)
					on	CTN.comp_id				= tct.comp_id
					and	CTN.bra_id				= tct.bra_id
					and CTN.ct_transaction		= tct.ct_transaction

				order by tct.ct_transaction desc ,[DESC]



END
GO





CREATE PROCEDURE [dbo].[spDeliverySheetHeader_GetDataByFilters]
(
	@comp_id					INT,
	@bra_id						INT,
	@datefrom					DATETIME,
	@dateto						DATETIME,
	@dl_id					    INT,
	@ct_docNumber_optionid  	INT,
	@ct_docnumber			    NVARCHAR(50),
	@cust_id				    INT

)
AS


BEGIN


	SET DATEFORMAT 'YMD'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- ---------------------------------------------
	-- tEST
	-- ---------------------------------------------
	/*
	declare @comp_id					INT,
			@bra_id						INT,
			@datefrom					DATETIME,
			@dateto						DATETIME,
			@dl_id					    INT,
			@ct_docNumber_optionid  	INT,
			@ct_docnumber			    NVARCHAR(50),
			@cust_id				    INT

	SElect	@comp_id				= 1,
			@bra_id					= 34,
			@datefrom				= '1900/01/01',
			@dateto					= '2999/12/31',
			@dl_id					= -1,
			@ct_docNumber_optionid	= 1,
			@ct_docnumber			= '302555',
			@cust_id				= -1
	*/
	-- ---------------------------------------------



	SET NOCOUNT ON


	IF @ct_docnumber = '' AND @cust_id = -1	-- porque es LENTO
		BEGIN


			SELECT distinct  '' [ ], ''[ ],''[ ],'' [ ],'' [ ],
					iSnULL(tdsh.ds_top,'')			[ds_top],
					isnull(tdsh.ds_bottom,'')		[ds_bottom],
					isnull(td.dl_name,'')			[dl_name],
					isnull(tdsh.ds_date,GETDATE())	[ds_date],
					tdsh.ds_id						[ID]
					--convert(varchar,tdsh.bra_id) + ' - ' + convert(varchar,tdsh.ds_id) [ID]

			FROM tbDeliverySheetHeader tdsh			WITH (NOLOCK)
			INNER JOIN tbDelivery		td			WITH (NOLOCK)	-- MOS 5-2017 Antes era LEFT, Ahora si o si debe tener un trabsporte asignado.  si alguien se queja poner un id de transporte a todas las que tengan NULL
			ON  td.comp_id = tdsh.comp_id	AND
				td.dl_id   = tdsh.dl_id
			WHERE	tdsh.comp_id = @comp_id		AND
					tdsh.bra_id  = @bra_id		AND
					tdsh.ds_date BETWEEN @datefrom AND @dateto	AND
				   (@dl_id  = -1 OR tdsh.dl_id   = @dl_id)
			ORDER BY tdsh.ds_id DESC

		END
	ELSE
		BEGIN

			SELECT distinct  '' [ ], ''[ ],''[ ],'' [ ],
					iSnULL(tdsh.ds_top,'')			[ds_top],
					isnull(tdsh.ds_bottom,'')		[ds_bottom],
					isnull(td.dl_name,'')			[dl_name],
					isnull(tdsh.ds_date,GETDATE())	[ds_date],
					tdsh.ds_id						[ID]
					--convert(varchar,tdsh.bra_id) + ' - ' + convert(varchar,tdsh.ds_id) [ID]

			FROM tbDeliverySheetHeader tdsh			WITH (NOLOCK)
			INNER JOIN tbDelivery		td			WITH (NOLOCK)	-- MOS 5-2017 Antes era LEFT, Ahora si o si debe tener un trabsporte asignado.  si alguien se queja poner un id de transporte a todas las que tengan NULL
			ON  td.comp_id = tdsh.comp_id
			AND td.dl_id   = tdsh.dl_id

			INNER JOIN tbDeliverySheetDetail tdsd	WITH (NOLOCK)
			ON	tdsd.comp_id	= tdsh.comp_id	AND
				tdsd.bra_id		= tdsh.bra_id	AND
				tdsd.ds_id		= tdsh.ds_id

			LEFT JOIN tbCommercialTransactions tct	WITH (NOLOCK)
			ON	tct.comp_id			= tdsd.comp_id		AND
				--tct.bra_id			= tdsd.bra_id		AND    NOOOOOO, como mierda va a encotrar facturas de cualquier lado si esta con la sucursal de centro de distribucion ???????????
				tct.ct_transaction	= tdsd.ds_ct_transaction


			WHERE tdsh.comp_id = @comp_id
			AND   tdsh.bra_id  = @bra_id
			AND   tdsh.ds_date BETWEEN @datefrom AND @dateto
			AND   (@dl_id  = -1 OR tdsh.dl_id   = @dl_id)
			AND	  (
						(@ct_docNumber_optionid	 = -1 ) or
						(@ct_docNumber_optionid	 = 0 and tct.ct_docNumber like @ct_docnumber + '%') or
						(@ct_docNumber_optionid	 = 1 and tct.ct_docNumber like '%' + @ct_docnumber + '%') or
						(@ct_docNumber_optionid	 = 2 and tct.ct_docNumber = @ct_docnumber ) or
						(@ct_docNumber_optionid	 = 3 and tct.ct_docNumber <> @ct_docnumber ) or
						(@ct_docNumber_optionid	 = 4 and tct.ct_docNumber not like '%' + @ct_docnumber + '%')
					)
			AND   (@cust_id  = -1 OR tct.cust_id   = @cust_id)

			ORDER BY tdsh.ds_id DESC

		END

END

GO






CREATE PROCEDURE [dbo].[spDeliverySheetHeader_GetDataById]
(
	@comp_id		   INT,
	@bra_id			   INT,
	@ds_id			   INT
)

AS
SET NOCOUNT ON

SELECT  tdsh.comp_id,
		tdsh.bra_id,
		tb.bra_desc,
		tdsh.ds_id,
		tdsh.ds_top,
		tdsh.ds_bottom,
        isnull(tdsh.dl_id,-1) [dl_id],
        td.dl_name,
        convert(varchar,tdsh.ds_date,103) [ds_date],
        ISNULL(tdsh.sds_id,0)   		  [ds_status]

FROM tbDeliverySheetHeader tdsh

INNER JOIN tbBranch tb			WITH (NOLOCK)
ON  tb.comp_id = tdsh.comp_id
AND tb.bra_id  = tdsh.bra_id

LEFT JOIN tbDelivery td			WITH (NOLOCK)
ON  td.comp_id = tdsh.comp_id
AND td.dl_id   = tdsh.dl_id


WHERE tdsh.comp_id = @comp_id
AND   tdsh.bra_id  = @bra_id
AND   tdsh.ds_id   = @ds_id

GO






