CREATE PROCEDURE [dbo].[spDeliverySheetHeader4RMA_UpdateStatus]
(
	@comp_id		   INT,
	@bra_id			   INT,
	@ds_id			   INT,
	@ds_status		   INT,
	@ApplyToDetails	   BIT,
	@user_id		   INT



)
AS
SET NOCOUNT ON


BEGIN

	--Aplica a todos los detalles de la hoja de ruta
	IF @ApplyToDetails = 'True'
		BEGIN
			--------------------------------------------------------------------
			--Update header ACTUALIZAMOS EL ESTADO DE LA HEADER
			UPDATE tbDeliverySheetHeader
				SET		sds_id	= @ds_status

				WHERE	comp_id = @comp_id
				AND		bra_id  = @bra_id
				AND		ds_id   = @ds_id
			--------------------------------------------------------------------

			--------------------------------------------------------------------
			-- GUARDAMOS EN UNA TABLA TEMPORAL LOS DETALLES CON SU dsd_isRMA4Picking PARA
			-- SABER SI ES ENVIO O RETIRO
			DECLARE @tmpUpdateStatus TABLE(dsd_isRMA4Picking INT,dsd_id int)

			INSERT INTO @tmpUpdateStatus (dsd_isRMA4Picking,dsd_id)
				SELECT
					tdsd.dsd_isRMA4Picking,tdsd.dsd_id

                FROM tbDeliverySheetDetail					tdsd
    			WHERE	tdsd.comp_id = @comp_id
				AND		tdsd.bra_id  = @bra_id
				AND		tdsd.ds_id   = @ds_id

			--------------------------------------------------------------------
			--4delivery - envio
			UPDATE  tbDeliverySheetDetail
				SET	sds_id = @ds_status

				FROM tbDeliverySheetDetail TDST
				INNER JOIN @tmpUpdateStatus tmp
				ON tmp.dsd_id				= TDST.dsd_id AND
				   tmp.dsd_isRMA4Picking	= 0

				WHERE TDST.comp_id = @comp_id


			--4pick - retiro
			UPDATE  tbDeliverySheetDetail
				SET	sds_id = 10+@ds_status

				FROM tbDeliverySheetDetail TDST
				INNER JOIN @tmpUpdateStatus tmp
				ON  tmp.dsd_id				= TDST.dsd_id AND
					tmp.dsd_isRMA4Picking	= 1

				WHERE TDST.comp_id = @comp_id


			------------------------------------------------------------------------------
			--RMA DETAIL
			--Actualizamos estado si es que esta relacionado en rma detail

			--Guardamos los dsd relacionados a los rma
			DECLARE @tmpRMA4UpdateStatus TABLE(rmah_id INT ,rmad_id INT, dsd_isRMA4Picking INT,dsd_id int)

			INSERT INTO @tmpRMA4UpdateStatus (rmah_id,rmad_id,dsd_isRMA4Picking,dsd_id)
				SELECT
					tdsd.rmah_id,
					tdsd.rmad_id,
					tdsd.dsd_isRMA4Picking,
					tdsd.dsd_id

                FROM tbDeliverySheetDetail					tdsd
    			WHERE	tdsd.comp_id = @comp_id
				AND		tdsd.bra_id  = @bra_id
				AND		tdsd.ds_id   = @ds_id
				AND     tdsd.rmah_id IS NOT NULL
				AND		tdsd.rmad_id IS NOT NULL

				--4delivery - envio
				UPDATE  tbRMA_Detail
				SET	sds_id4Delivery = @ds_status,
					dsd_id4Delivery = tmp.dsd_id
				FROM tbRMA_Detail trd
				INNER JOIN @tmpRMA4UpdateStatus tmp
				ON  tmp.rmah_id				= trd.rmah_id	AND
					tmp.rmad_id				= trd.rmad_id	AND
					tmp.dsd_isRMA4Picking	= 0

				WHERE trd.comp_id = @comp_id



				--4pick - retiro
				UPDATE  tbRMA_Detail
				SET sds_id4Picking  = 10+@ds_status,
					dsd_id4Picking  = tmp.dsd_id
				FROM tbRMA_Detail trd
				INNER JOIN @tmpRMA4UpdateStatus tmp
				ON  tmp.rmah_id				= trd.rmah_id	AND
					tmp.rmad_id				= trd.rmad_id	AND
					tmp.dsd_isRMA4Picking	= 1

				WHERE trd.comp_id = @comp_id


			------------------------------------------------------------------------------

			------------------------------------------------------------------------------
			-- ACTUALIZACION DE LA FECHA Y EL USUARIO
			------------------------------------------------------------------------------

			IF @ds_status = 1
				-- Espera Envío / Espera Retiro
				BEGIN
					UPDATE tbDeliverySheetDetail
						SET
							dsd_status1_cd = GETDATE(),
							dsd_status1_user_id = @user_id
						WHERE	comp_id = @comp_id
						AND		bra_id  = @bra_id
						AND		ds_id   = @ds_id

				END

			IF @ds_status = 2
				-- Enviando / Retirando
				BEGIN
					UPDATE tbDeliverySheetDetail
						SET
							dsd_status2_cd = GETDATE(),
							dsd_status2_user_id = @user_id
						WHERE	comp_id = @comp_id
						AND		bra_id  = @bra_id
						AND		ds_id   = @ds_id
				END

			IF @ds_status = 3
				-- Enviado / Retirado
				BEGIN
					UPDATE tbDeliverySheetDetail
						SET
							dsd_status3_cd = GETDATE(),
							dsd_status3_user_id = @user_id
						WHERE	comp_id = @comp_id
						AND		bra_id  = @bra_id
						AND		ds_id   = @ds_id
				END

		END
	ELSE
		-- Solo actualizamos la header
		BEGIN

			--------------------------------------------------------------------
			--Update header ACTUALIZAMOS EL ESTADO DE LA HEADER

			UPDATE tbDeliverySheetHeader
				SET		sds_id	= @ds_status
				WHERE	comp_id = @comp_id
				AND		bra_id  = @bra_id
				AND		ds_id   = @ds_id

			--------------------------------------------------------------------

		END

END
GO




-- Asignar Accesos Personalizados
-- 15/07/2020

CREATE PROCEDURE [dbo].[spDesktopShortcuts_getDataById]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id						INT,
	@prof_id					INT,
	@user_id					INT


)
AS

BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
	DECLARE	  	@comp_id					INT,
				@bra_id						INT,
				@prof_id					INT,
				@user_id					INT


	SELECT		@comp_id						= 1,
				@bra_id							= 1
	*/
	-- ------------------------------------------------------




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 100
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	set nocount ON



	-- Copiado de [spSysMenu_getDataGranted]
	DECLARE @tmpParameters AS TABLE (menu_id INT PRIMARY KEY,parameters	NVARCHAR(MAX))
	INSERT  @tmpParameters
	(
		menu_id,parameters
	)
	select	distinct mp.menu_id,
	--tooltip3
	isnull((select	t.ptype_desc +'='+ v.[desc] +','
			from	tbsysmenuparameters m											WITH (NOLOCK)
					inner join tbsysparameterstype t								WITH (NOLOCK)
					on	m.ptype_id		= t.ptype_id
					inner join [tbSysParametersTypeLangValuesClearFromView]	v		WITH (NOLOCK)
					on	v.[type_id]		= m.[ptype_id]
					and	v.id			= m.ptypevalue_id
					AND v.lang_id		= @lang_id
			where	m.menu_id = mp.menu_id		and		m.ptype_id = 21),'') +
	--tooltip4
	isnull((select	t.ptype_desc +'='+ v.[desc] +','
			from	tbsysmenuparameters m											WITH (NOLOCK)
					inner join tbsysparameterstype t								WITH (NOLOCK)
					on	m.ptype_id		= t.ptype_id
					inner join [tbSysParametersTypeLangValuesClearFromView]	v		WITH (NOLOCK)
					on	v.[type_id]		= m.[ptype_id]
					and	v.id			= m.ptypevalue_id
					AND v.lang_id		= @lang_id
			where	m.menu_id = mp.menu_id		and
					m.ptype_id = 22),'') +
	--tooltip4
	isnull((select	t.ptype_desc +'='+ v.[desc] +','
			from	tbsysmenuparameters m											WITH (NOLOCK)
					inner join tbsysparameterstype t								WITH (NOLOCK)
					on	m.ptype_id		= t.ptype_id
					inner join [tbSysParametersTypeLangValuesClearFromView]	v		WITH (NOLOCK)
					on	v.[type_id]		= m.[ptype_id]
					and	v.id			= m.ptypevalue_id
					AND v.lang_id		= @lang_id
			where	m.menu_id = mp.menu_id		and
					m.ptype_id = 57),'') +
	--tooltip5
	isnull((select	t.ptype_desc +'='+ v.[desc] +','
			from	tbsysmenuparameters m											WITH (NOLOCK)
					inner join tbsysparameterstype t								WITH (NOLOCK)
					on	m.ptype_id		= t.ptype_id
					inner join [tbSysParametersTypeLangValuesClearFromView]	v		WITH (NOLOCK)
					on	v.[type_id]		= m.[ptype_id]
					and	v.id			= m.ptypevalue_id
					AND v.lang_id		= @lang_id
			where	m.menu_id = mp.menu_id		and		m.ptype_id = 32),'') [parameters]
	FROM 	tbsysmenuparameters		mp												WITH (NOLOCK)
	WHERE	mp.ptype_id  = 21 OR
			mp.ptype_id  = 22 OR
			mp.ptype_id  = 32 OR
			mp.ptype_id  = 57









	SELECT
		tds.comp_id							[comp_id],
		tds.du_id							[du_id],
		tds.du_hideDefaultDesktop,
		CASE
			WHEN ISNULL(tds.du_desc,'') = '' THEN ISNULL(isnull(L.mid_desc,M.menu_desc),tds.du_reference)
			ELSE tds.du_desc
		END									[du_desc],
		CASE
			WHEN ISNULL(tds.du_desc,'') = '' THEN ISNULL(IsNull(L.mid_tooltip,''),'')
			ELSE tds.du_tooltip
		END									[du_tooltip],

		ISNULL(tds.menu_id,-1)				[menu_id],
		ISNULL(tds.du_url,'')				[du_url],

		ISNULL(M.menu_destiny,tds.du_openInNewWindow)		[du_openInNewWindow],

		M.menu_type,
		--isnull(L.mid_desc,M.menu_desc)					[menu_desc],
		CASE SUBSTRING(P.page_desc,1,3)
			WHEN 'wfm' then	isnull(P.page_desc + '.aspx', '')
			WHEN 'htm' THEN ISNULL(P.page_desc + '.htm', '')
			WHEN 'hel' THEN ISNULL(P.page_desc + '.htm', '')
			ELSE isnull(P.page_desc + '.aspx', '')
		end												[menu_page],
		case
			when MP.parameters is null					then ''
			when len(ltrim(rtrim(MP.parameters))) = 0	then ''
			else substring(MP.parameters,1,len(MP.parameters)-1)
		end	 +
		case
			when ttsmp.parameters is null					then ''
			when len(ltrim(rtrim(ttsmp.parameters))) = 0	then ''
			else ',' + substring(ttsmp.parameters,1,len(ttsmp.parameters)-1)
		end	 +
		case
			when M.menu_parameters is null					then ''
			when len(ltrim(rtrim(M.menu_parameters)))	= 0	then ''
			ELSE
				CASE WHEN LEN(MP.parameters) > 0 OR LEN(ttsmp.parameters) > 0 THEN ',' ELSE '' END
					+ M.menu_parameters
		end												[menu_parameters]--,
		--M.menu_destiny,
		--M.menu_imageurl_path

		FROM tbDesktopShortcuts tds														WITH (NOLOCK)

		LEFT JOIN tbsysMenu				M												WITH (NOLOCK)
			ON  m.menu_id = tds.menu_id
		LEFT join tbsysMenuLanguage		L												WITH (NOLOCK)
			on	L.menu_id		= M.menu_id
			and	L.lang_id		= @lang_id

		left JOIN tbMenuGrants tmg														WITH (NOLOCK)
			ON  tmg.comp_id		= @comp_id
			AND tmg.prof_id		= @prof_id
			AND tmg.menu_id		= m.menu_id

		left join tbsysMenuParametersFromView MP										WITH (NOLOCK)
			on MP.menu_id		= M.menu_id
		LEFT JOIN @tmpParameters ttsmp
			ON MP.menu_id		= ttsmp.menu_id
		left join tbsysPages P															WITH (NOLOCK)
			on P.page_id		= M.page_id


		WHERE	 tds.comp_id	= @comp_id									AND
				(tds.bra_id		= @bra_id	OR tds.bra_id		IS NULL)	AND
				(tds.prof_id	= @prof_id	OR tds.prof_id		IS NULL)	AND
				(tds.user_id	= @user_id  OR tds.[user_id]	IS NULL)	AND
				(tds.menu_id    IS NULL		OR  m.menu_disabled = 0    )	AND
				CASE
					WHEN	tds.du_url		= ''	AND
							tds.menu_id	is NOT NULL			THEN 1
					WHEN	tds.du_url		like '%http%'	THEN 1
					WHEN	tds.menu_id	is NOT NULL			THEN 1
					ELSE										 0
				END = 1

		ORDER BY tds.du_order



END
GO




