-- =============================================
-- Author:		MOS
-- Create date: 04-2014
-- =============================================
CREATE PROCEDURE spDigitalization_InsertUpdateData
	@comp_id			AS INT,
	@img_id				AS INT,
	@ct_transaction		AS INT,
	@it_transaction		AS INT,
	@it_id				AS INT,
	@img_DATA			AS IMAGE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	IF @ct_transaction = -1 SET @ct_transaction = NULL
	IF @it_transaction = -1 SET @it_transaction = NULL
	IF @img_id		   = -1 SET @img_id			= NULL


	IF NOT EXISTS(
					SELECT 1
						FROM tbDigitalization td
						WHERE	td.comp_id	= @comp_id AND
								td.img_id	= @img_id
				)
		BEGIN
			-- INSERT
			INSERT INTO tbDigitalization
			(
				comp_id,
				it_id,
				ct_transaction,
				it_transaction,
				img_DATA
			)
			VALUES
			(
				@comp_id,
				@it_id,
				@ct_transaction,
				@it_transaction,
				@img_DATA
			)
		END
	ELSE
		BEGIN
			-- UPDATE
			UPDATE tbDigitalization
			SET
				img_DATA    = @img_DATA
			WHERE	comp_id = @comp_id AND
					img_id	= @img_id
		END



END
GO















