CREATE PROCEDURE [dbo].[spDiscount_getComboByProfile]
(
	@comp_id			INT,
	@prof_id			INT
)
AS

BEGIN

	SET NOCOUNT ON

	/*
	DECLARE 	@comp_id			INT, @prof_id			INT
	SELECT		@comp_id=1, @prof_id=2
	*/


		select		td.disc_id		[id],
					td.disc_desc	[desc]

		from		dbo.tbDiscount td

		where		td.comp_id =	@comp_id
		AND			IsNull(td.disc_Disabled,'false') = 'false'
		AND			(td.disc_id IN (SELECT	tdp.disc_id
	   							  FROM		tbDiscount4Profile tdp
	   							  WHERE		tdp.comp_id	= @comp_id
								  AND		tdp.prof_id	= @prof_id) OR
					 NOT EXISTS (SELECT	1
	   							  FROM		tbDiscount4Profile tdp
	   							  WHERE		tdp.comp_id	= @comp_id
								  AND		tdp.prof_id	= @prof_id))

		Order By	disc_desc


END







GO






