CREATE PROCEDURE spDocumentsFile_GetAvailableCAEADocumentsByFilters
(
	@comp_id	INT,
	@bra_id		INT,
	@dateFrom	DATETIME,
	@dateTo		DATETIME,
	@Caea		NVARCHAR(50)
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- ---------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@dateFrom	DATETIME,
				@dateTo		DATETIME,
				@Caea		NVARCHAR(50)

			SELECT
				@comp_id	= 1,
				@bra_id		= -1,
				@dateFrom	= '2018-12-01',
				@dateTo		= '2018-12-31',
				@Caea		= '01TEST'
		*/
		-- ---------------------------------------------------

		SET @dateFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'False')
		SET @dateTo		= dbo.fnGetEnd_or_BeginOfDate(@dateTo,	'True')

		SELECT
			' '																[1],
			tdf.df_desc,
			tdf.df_CAEA_isAvailable,
			tdf.df_CAEA_fromDate,
			tdf.df_CAEA_toDate,
			tdf.df_CAEA_CAEANumber,
			CONVERT(VARCHAR,tdf.bra_id) + '-' + CONVERT(VARCHAR,tdf.df_id)	[ID]
			FROM tbDocumentsFile											tdf	WITH(NOLOCK)
			WHERE	tdf.comp_id				= @comp_id						AND
					(
						@bra_id				= -1		OR
						tdf.bra_id			= @bra_id
					)														AND
					tdf.df_CAEA_fromDate	BETWEEN @dateFrom AND @dateTo	AND
					tdf.df_CAEA_toDate		BETWEEN @dateFrom AND @dateTo	AND
					ISNULL(tdf.df_CAEA_isAvailable,'False')	  = 'True'		AND
					tdf.df_CAEA_CAEANumber					  = @Caea
	END


GO








