-- Author:		MOS
-- Modif:		MOS  07-2014
-- Description:	Trae Valores por ID de conf. del sistema
-- =================================================================

CREATE PROCEDURE [dbo].[spDocumentsFile_getComboByBranchAndProfile]
(
	@comp_id			int ,
	@bra_id				INT,
	@prof_id			int
)
AS

BEGIN



	set nocount on

	/*
	declare	@comp_id		int,
			@bra_id			int
	select 	@comp_id		=1,
			@bra_id			=4
	*/

	select	--DISTINCT
			tdf.df_id		[id],
			tdf.df_desc		[desc],
			tdf.bra_id,
			tdf.df_order,
			tdf.df_desc
		INTO #tmpDocFile
		from	dbo.tbDocumentsFile tdf					WITH (NOLOCK)
		INNER JOIN tbDocumentsFileByProfile tdfbp		WITH (NOLOCK)
			ON	tdfbp.comp_id	= tdf.comp_id	AND
				tdfbp.bra_id	= tdf.bra_id	AND
				tdfbp.df_id		= tdf.df_id
		where	tdf.comp_id		=	@comp_id	AND
				tdf.bra_id		=	@bra_id



	-- hidSOIncludeDocuments4Replace  Si Incluye este tipo de documentos para el filtro, los muestra.
	IF EXISTS(	SELECT TOP 1 1
	          		FROM tbControlProfiles AS tcp1	WITH (NOLOCK)
	          		WHERE	tcp1.comp_id	= @comp_id	AND
	          				tcp1.bra_id		= @bra_id	AND
	          				tcp1.prof_id	= @prof_id	AND
	          				tcp1.page_id	= 14		AND
	          				tcp1.ctrl_id	= 5941
			)
		BEGIN
			INSERT INTO #tmpDocFile ([id],
									 [desc],
									 bra_id,
									 df_order,
									 df_desc)
					SELECT
							tdf.df_id		[id],
							tdf.df_desc		[desc],
							tdf.bra_id,
							tdf.df_order,
							tdf.df_desc
						from	dbo.tbDocumentsFile tdf								WITH (NOLOCK)
						INNER JOIN tbDocumentsFile_Replacement4Branch AS tdfrb		WITH (NOLOCK)
							ON	tdfrb.comp_id		= tdf.comp_id AND
								tdfrb.df_id_from	= tdf.df_id
						where	tdfrb.comp_id				=	@comp_id	AND
								tdfrb.bra_idofProcessing	=	@bra_id		AND
								tdfrb.dfr_Replace4Emmition	= 1
		END


	SELECT DISTINCT *
		INTO #tmpDocFile2
		FROM #tmpDocFile


	SELECT tdf.[id],tdf.[desc]
		FROM #tmpDocFile2 tdf
		order BY tdf.bra_id,tdf.df_order,tdf.df_desc

	DROP TABLE #tmpDocFile2
	DROP TABLE #tmpDocFile



END












GO









