CREATE PROCEDURE [dbo].[spDocumentsFile_getComboBySysDocument]
(
	@comp_id			INT,
	@bra_id				INT,
	@sd_id				INT
)
AS
SET NOCOUNT ON

-- -----------------------------------------
-- Testing
-- -----------------------------------------
	/*
	declare @comp_id		int,
			@bra_id			INT,
			@sd_id			INT
	select 	@comp_id		=1,
			@bra_id			=1,
