CREATE PROCEDURE [dbo].[spDocumentsFile_getComboForElectronicInvoice]
(
	@comp_id			int
)
AS

BEGIN
	set nocount on
	/*

	declare	@comp_id	INT

	select 	@comp_id	=1
	*/

	select	df_id		[id],
			CASE
				WHEN df_CAEA_isAvailable = 'True' THEN 'CAEA:'
				ELSE ''
			END +
			df_desc		[desc]
		from	dbo.tbDocumentsFile	WITH (NOLOCK)
		where	comp_id					=	@comp_id	AND
				(df_isElectronicInvoice	= 'true' OR df_CAEA_isAvailable = 'True')  -- CAEA MOS 07-2021
		order by
			CASE
				WHEN df_CAEA_isAvailable = 'True' THEN 1
				ELSE 0
			END,
			df_desc
END


















GO









