CREATE PROCEDURE [dbo].[spDocumentsFile_getComboOfBranchDocuments]
(
	@comp_id			INT,
	@bra_id				int
)
as
set nocount on

/*
declare 	@comp_id			int,
			@df_id				int,
			@bra_id				int

select 	@comp_id		=1,
		@df_id			=2,
		@bra_id			=1
*/

	select
				df_id [id],
				df_desc [desc]


		from		dbo.tbDocumentsFile  WITH (NOLOCK)

		where		comp_id		=	@comp_id	AND
					bra_id      =	@bra_id

		ORDER BY bra_id,df_desc
















GO



CREATE PROCEDURE [dbo].[spDocumentsFile_GetComboOfCollectionDocuments]
(
	@comp_id			int ,
	@bra_id				INT,
	@user_id			INT,
	@prof_id			INT
)
AS

BEGIN

	set nocount on

	-- --------------------------------------------------
	-- Testing
	-- Si NO tiene ninguno asignado trae todos los recibos que encuentre
	-- de lo contrario solo los q tiene ese perfil.
	-- --------------------------------------------------
	/*
	declare	@comp_id		int,
			@bra_id			int
	select 	@comp_id		=1,
			@bra_id			=1
	*/
	-- --------------------------------------------------

	SELECT 	convert(varchar,df.df_id) + '-' + convert(varchar,df.[sd_id])		[id],
			df.df_desc															[desc]
		INTO #tmpReceipts
		FROM  	dbo.tbDocumentsFile					df	WITH (NOLOCK)
		INNER JOIN  dbo.[tbsysDocuments]		sd		WITH (NOLOCK)
			ON 	sd.[sd_id]		= df.[sd_id]
		INNER JOIN tbDocumentsFileByProfile		tdfbp	WITH (NOLOCK)
			ON
				tdfbp.comp_id		= df.comp_id	AND
				tdfbp.bra_id		= df.bra_id		AND
				tdfbp.df_id			= df.df_id		AND
				tdfbp.prof_id		= @prof_id
		WHERE 	df.comp_id			= @comp_id	AND
				df.bra_id			= @bra_id	AND
				sd.[sd_isReceipt]	= 'True'	AND
				sd.[sd_isPurchase]	= 'False'	AND
				df.df_Disabled		= 'False'
		ORDER BY df.df_order,df.df_desc


	IF @@ROWCOUNT = 0
		BEGIN

			SELECT 	convert(varchar,df.df_id) + '-' + convert(varchar,df.[sd_id])		[id],
					df.df_desc															[desc]
				FROM  	dbo.tbDocumentsFile					df	WITH (NOLOCK)
				INNER JOIN  dbo.[tbsysDocuments]		sd	WITH (NOLOCK)
					ON 	sd.[sd_id]		= df.[sd_id]
				WHERE 	df.comp_id			= @comp_id	AND
						df.bra_id			= @bra_id	AND
						sd.[sd_isReceipt]	= 'True'	AND
						sd.[sd_isPurchase]	= 'False'	AND
						df.df_Disabled		= 'False'
				ORDER BY df.df_order,df.df_desc

		END
	ELSE
		BEGIN
			SELECT *
				FROM #tmpReceipts
		END

END












GO









create PROCEDURE [dbo].[spDocumentsFile_GetComboOfCollectionDocumentsAllBranchs]
(
	@comp_id			int
)
as

set nocount on

-----------------------------------------
/*
declare	@comp_id		INT

select 	@comp_id		=1
*/

-----------------------------------------



	select	convert(varchar,df.df_id)		[id],
			df.df_desc						[desc]

	from 	dbo.tbDocumentsFile					df	WITH (NOLOCK)

			inner join dbo.[tbsysDocuments]		sd	WITH (NOLOCK)
			on	sd.[sd_id]		= df.[sd_id]

	where 	df.comp_id			= @comp_id
	and		sd.[sd_isReceipt]	= 'True'
	and		sd.[sd_isPurchase]	= 'False'
	AND		df.df_Disabled		= 'False'


	Order BY df.df_order,
			 df.df_desc















GO






-- =================================================================
-- Author:		MOS
-- Modif:		MOS  20-03-2008
-- Description:	Trae solo  los documentos de la clase permitida x el
--				cliente de  la suc correspondiente.-
-- GRUPO: CalculosFiscales
-- =================================================================

CREATE PROCEDURE [dbo].[spDocumentsFile_GetComboOfCustomerDocuments]
(
	@comp_id			INT,
	@bra_id				INT,
	@cust_id			INT,
	@prof_id			INT,
	@sd_id				INT
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	SET NOCOUNT ON


	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*
	declare	@comp_id		INT,
			@bra_id			INT,
			@cust_id		INT,
			@prof_id		INT,
			@sd_id			INT
	select 	@comp_id		=1,
			@bra_id			=1,
			@cust_id		=24288,
			@prof_id        =1,
			@sd_id			=-1
	*/
	-- ----------------------------------------------------------------


	DECLARE @fc_id AS INT
	SET		@fc_id = NULL

	SELECT	tdf.df_id				[id],
			tdf.df_desc				[desc],
			-- tdf.df_order + 1000000	[df_order]  MOS 10-2021 x HDC   Si hay alguien mas q lo usa que ponga los ORDERS como CORRESPONDE, VER:  **wefklnw9874lknlknl si se modifica algo acá
			tdf.df_order			[df_order]
		INTO #tmpDocuments
		FROM tbDocumentsFileAdditionalByFiscalClass tmp		WITH (NOLOCK)
		INNER JOIN tbCustomer tc							WITH (NOLOCK)
			ON	tc.comp_id = @comp_id AND
				tc.cust_id = @cust_id
		INNER JOIN tbDocumentsFile tdf						WITH (NOLOCK)
			ON	tdf.comp_id = tmp.comp_id	AND
				tdf.df_id	= tmp.df_id		AND
				tdf.bra_id  = tmp.bra_id
		WHERE	tmp.fc_id	= tc.fc_id	AND
				tmp.comp_id = @comp_id	AND
				tmp.bra_id	= @bra_id	AND
				tmp.prof_id = @prof_id






	-- Verifica si hace falta por alguna opcion poner factura tipo E
	DECLARE @bitCustomerBranchInOtherCountryOrTierraDelFuego AS BIT
	SET @bitCustomerBranchInOtherCountryOrTierraDelFuego    = 'False'
	SELECT @bitCustomerBranchInOtherCountryOrTierraDelFuego = 'True'
		FROM tbCustomer tc			WITH (NOLOCK)
		WHERE	tc.comp_id = @comp_id
			AND tc.cust_id = @cust_id
			AND (
				IsNull(tc.country_id,54)	<> 54
			OR	IsNull(tc.state_id,0)		= 54018
			)
	IF @bitCustomerBranchInOtherCountryOrTierraDelFuego = 'False'
		BEGIN
			SELECT @bitCustomerBranchInOtherCountryOrTierraDelFuego = 'True'
				FROM tbCustomerBranch tc			WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id
					AND tc.cust_id = @cust_id
					AND (
						IsNull(tc.country_id,54)	<> 54
					OR	IsNull(tc.state_id,0)		= 54018
						)
		END







	INSERT INTO #tmpDocuments (id,[DESC],df_order)

	SELECT 	df.df_id		[id],
			df_desc			[desc],
			ISNULL(df_order,0)		+	CASE	-- Asi no salen nunca primeras las NC ya que bloquean el DDL y borran todo lo que no sea NC
											WHEN df.sd_id = 3 THEN	999999
											ELSE					0
										END


	FROM 	dbo.tbDocumentsFile						DF				WITH (NOLOCK)

			-- -------------------------------------------------------------------
			-- Para ver si se excluye el documento para esa provincia de destino
			-- -------------------------------------------------------------------
			INNER JOIN tbCustomer tc								WITH (NOLOCK)
				ON		tc.comp_id = @comp_id
					AND tc.cust_id = @cust_id
			LEFT JOIN tbDocumentsFileDisabledByCustomerState tdfes	WITH (NOLOCK)
				ON		tdfes.comp_id		= tc.comp_id
					AND tdfes.df_id			= df.df_id
					AND tdfes.state_id		= tc.state_id
					AND tdfes.country_id	= tc.country_id
					AND tdfes.[disabled]	= 'True'
			LEFT JOIN tbDocumentsFileExclusions4SO tdfes2			WITH (NOLOCK)
				ON		tdfes2.comp_id		= tc.comp_id
					AND tdfes2.df_id		= df.df_id
					AND tdfes2.state_id		= tc.state_id
					AND tdfes2.country_id	= tc.country_id
					AND tdfes2.prof_id		= @prof_id
			-- -------------------------------------------------------------------


			Inner Join vwsysDocuments_forSaleOrder	VDF				WITH (NOLOCK)
			ON 	VDF.sd_id		= DF.sd_id

			INNER JOIN tbDocumentsFileByProfile		tdfbp			WITH (NOLOCK)
			ON	tdfbp.comp_id	= df.comp_id
			AND tdfbp.bra_id	= df.bra_id
			AND tdfbp.prof_id	= @prof_id
			AND tdfbp.df_id		= df.df_id

	WHERE 	DF.comp_id			= @comp_id
	AND		DF.bra_id			= @bra_id
	AND		DF.df_Disabled		= 'False'
	AND		(dbo.fnStrAllTrim( dbo.fnGetFiscalCustomer_KindOf(@cust_id)) LIKE '%' + DF.df_kindOf  + '%'
			OR DF.df_kindof = 'R'
			OR DF.df_kindof = 'X'
			OR DF.df_kindof = 'C'  -- MOS 07-2015
			OR DF.df_kindof = ''
			OR DF.df_kindof = ' '
			OR DF.df_kindof IS NULL
			OR (df.df_Kindof = 'E' AND @bitCustomerBranchInOtherCountryOrTierraDelFuego = 'True')
			)
	AND		(@sd_id = -1 OR DF.sd_id = @sd_id)
	AND tdfes.comp_id IS NULL		-- Si no esta excluido en tbDocumentsFileDisabledByCustomerState, lo trae
	AND tdfes2.comp_id IS NULL		-- Si no esta excluido en tbDocumentsFileExclusions4SO, lo trae
	AND (df.df_SaleOrder_only4CustomersWithCountry_id IS NULL OR df.df_SaleOrder_only4CustomersWithCountry_id = tc.country_id)


	SELECT tmp.id,tmp.[desc]
		FROM #tmpDocuments tmp
		ORDER BY tmp.df_order

	DROP TABLE #tmpDocuments

END









GO








create PROCEDURE [dbo].[spDocumentsFile_GetComboOfFiscalPrinterDocuments]
(
	@comp_id			int,
	@bra_id				int
)
as
set nocount on


SELECT	df_id		[id],
		df_desc		[desc]

FROM	tbDocumentsFile tdf

		INNER JOIN tbsysDocuments tsd
		ON	tsd.sd_id				=	tdf.sd_id
		and (tsd.sd_isQuotation		=	'false')
		AND (tsd.sd_isPurchase		=	'false')
		AND (tsd.sd_isReceipt		=	'false')
		AND (tsd.sd_isCredit		=	'false')

WHERE	tdf.comp_id						=	@comp_id
AND		tdf.bra_id						=	@bra_id
AND		tdf.df_Fiscal_IsFiscalPrinter	=	'true'
GO









CREATE PROCEDURE [dbo].[spDocumentsFile_GetComboOfPaymentsDocuments]
(
	@comp_id			int ,
	@bra_id				int
)
as

set nocount on

/*
declare	@comp_id		int,
		@bra_id			int
select 	@comp_id		=1,
		@bra_id			=1
*/


select	convert(varchar,df.df_id) + '-' + convert(varchar,df.[sd_id])		[id],
		df.df_desc		[desc]


from 	dbo.tbDocumentsFile					df		WITH (NOLOCK)

		inner join dbo.[tbsysDocuments]		sd	WITH (NOLOCK)
		on	sd.[sd_id]		= df.[sd_id]

where 	df.comp_id			= @comp_id
and		df.bra_id			= @bra_id
and		sd.[sd_isReceipt]	= 'True'
and		sd.[sd_isPurchase]	= 'True'

Order By df.df_desc















GO






CREATE PROCEDURE [dbo].[spDocumentsFile_GetComboWithDesign]
(
	@comp_id			int,
	@bra_id				int
)

as
set nocount on

/*
declare
@comp_id			int,
@bra_id				int

select
@comp_id			=1,
@bra_id				=4
*/




select		df_id		[id],
			df_desc		[desc]

from		dbo.tbDocumentsFile

where		comp_id		=	@comp_id
and			bra_id		=	@bra_id
and			df_id in (select distinct df_id
					  from dbo.tbDocumentsFileDesign
					  						)

Order By	df_desc















GO






CREATE PROCEDURE [dbo].[spDocumentsFile_GetComboWithDesignList]
(
	@comp_id			int,
	@bra_id				int,
	@df_id				int
)

as
set nocount on


/*
declare
@comp_id			int,
@bra_id				int,
@df_id				int

select
@comp_id			=1,
@bra_id				=1,
@df_id				=11
*/




select		df_id		[id],
			df_desc		[desc]

from		dbo.tbDocumentsFile

where		comp_id =	@comp_id
and			df_id in (select distinct df_id
					  from dbo.tbDocumentsFileDesign
					  where			bra_id	=	@bra_id
					  and 			df_id	=	@df_id
						)

Order By	df_desc















GO






CREATE PROCEDURE [dbo].[spDocumentsFile_GetComboWithoutDesign]
(
	@comp_id			int,
	@bra_id				int,
	@df_id				int
)

as
set nocount on

/*
declare
@comp_id			int,
@bra_id				int,
@df_id				int

select
@comp_id			=1,
@bra_id				=1,
@df_id				=2
*/
select		df_id		[id],
			df_desc		[desc]

from		dbo.tbDocumentsFile

where		comp_id =	@comp_id
and bra_id	=	@bra_id
and	df_id	=	@df_id
and			df_id  not in (select distinct df_id
					  from dbo.tbDocumentsFileDesign
						)



Order By	df_desc















GO







-- =================================================================
-- Author	: MOS
-- Data		: Impresion de Doc formato Crystal.
-- Date		: 28/10/15
-- =================================================================


CREATE PROCEDURE [dbo].[spDocumentsFile_Getdata4CrystalReports]
(
	@comp_id					INT,
	@lang_id					INT,
	@page_id					INT,
	@ct_transaction				INT,
	@bra_id						INT,
	@user_id					INT,
	@CopyNumber					NVARCHAR(50)

)

As



BEGIN

Set NoCount ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


-- =================================================================
-- *********************Datos de Prueba*****************************
-- =================================================================
/*
	DECLARE
		@comp_id					INT,
		@lang_id					INT,
		@page_id					INT,
		@bra_id						INT,
		@user_id					INT,
		@ct_transaction				INT,
		@CopyNumber					NVARCHAR(50)


	SELECT
		@comp_id					= 1,
		@lang_id					= 2,
		@page_id					= 100954,
		@bra_id						= 1,
		@user_id					= 1,
		@ct_transaction				= 10811,
		@CopyNumber					= 'LACONCHADETUMADRE'
*/
-- =================================================================


	---Datos del comprobante
	EXEC spCommercialTransactions_getDataById @comp_id, @ct_transaction, @user_id



	-- ------------------------------------------------------------------------------
	-- Si es un REMITO que se EMITIO JUNTO a una FACTURA, debe traer los ITEMS del REMITO
	-- ------------------------------------------------------------------------------
	DECLARE @ct_transaction4ItemTransactions AS INT = @ct_transaction
	SELECT  @ct_transaction4ItemTransactions =	CASE
													WHEN tct.sd_id = 2 AND 	tct.ct_transaction_PackingList IS NOT NULL THEN tct.ct_transaction_PackingList
													ELSE																	@ct_transaction4ItemTransactions
												END
		FROM tbcommercialtransactions  tct WITH (NOLOCK)
		WHERE	comp_id			= @comp_id AND
				ct_transaction	= @ct_transaction
	-- ------------------------------------------------------------------------------




	---Datos de los articulos
	EXEC spItemTransactions_getData @comp_id, @bra_id,@ct_transaction4ItemTransactions /*@ct_transaction*/,0, 0

	---Datos para el reporte
	EXEC [spReports_getData3]@comp_id,@bra_id, @lang_id,	@page_id,@bra_id
	---



	SELECT @CopyNumber						[CopyNumber]


END
GO






-- =================================================================
-- Author:		MOS
-- Modif:		MOS  29-2-08
-- Description:	Trae Valores por ID de conf. del sistema
-- =================================================================


CREATE PROCEDURE [dbo].[spDocumentsFile_getDataById]
(
	@comp_id			int,
	@bra_id				int,
	@df_id				int
)
AS

BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 200
SET DEADLOCK_PRIORITY NORMAL
-- -----------------------------------------------------------------------------


	set nocount on

-- ------------------------------------------------------------
-- Testing
-- ------------------------------------------------------------
	/*
	declare 	@comp_id			int,
				@df_id				int,
				@bra_id				int

	select 	@comp_id		=1,
			@df_id			=2,
			@bra_id			=1

	*/

-- ------------------------------------------------------------
--

	-- ----------------------------------------------------
	-- Verifica si debo reemplazar este documento por otro
	-- ----------------------------------------------------
	DECLARE @intDf_id4Replacement	AS INT
	DECLARE @intSD_Id				AS INT
	DECLARE @strKind				AS NVARCHAR(100)
	DECLARE @intSD_IdR				AS INT
	DECLARE @strKindR				AS NVARCHAR(100)
	DECLARE @intBraID				AS INT
	DECLARE @intBraIDR				AS INT

	SELECT	@intDf_id4Replacement	= tdf.df_id4Replacement ,
			@intSD_Id				= tdf.sd_id,
			@strKind				= tdf.df_Kindof,
			@intBraID				= tdf.bra_id
		FROM tbDocumentsFile tdf								WITH (NOLOCK)
		WHERE	tdf.comp_id = @comp_id
			AND tdf.df_id	= @df_id

	IF @intDf_id4Replacement IS NOT NULL
		BEGIN
			SELECT	@intSD_IdR				= tdf.sd_id,
					@strKindR				= tdf.df_Kindof,
					@intBraIDR				= tdf.bra_id
				FROM tbDocumentsFile tdf						WITH (NOLOCK)
				WHERE	tdf.comp_id				= @comp_id
					AND tdf.df_id				= @intDf_id4Replacement

			IF		@intSD_Id	= @intSD_IdR
				AND @strKind	= @strKindR
				AND @intBraID	= @intBraIDR
				BEGIN
					SET @df_id = @intDf_id4Replacement
				END

		END
	-- ----------------------------------------------------


		select	A.comp_id,
				A.bra_id,
				A.df_id,
				A.df_desc,
				A.df_fromDate,
				A.df_toDate,
				A.df_number,
				A.df_toNumber,
				A.df_isClientSide,
				A.df_computerName,
				A.df_printerName,
				A.df_cai,
				A.df_caiVto,
				IsNull(A.df_copies,0)			[df_copies],
				A.df_pointOfSale,
				A.df_Kindof,
				A.df_Fiscal_ComOrName,
				A.df_Fiscal_BaudOrPort,
				A.df_Fiscal_IsFiscalPrinter,
				D.sfp_Available_sd_id,
				D.sfp_driver					[df_Fiscal_Model_COM],
				D.sfp_driver_tcp				[df_Fiscal_Model_TCP],
				CASE
					WHEN  CharIndex('COM',upper(A.df_Fiscal_ComOrName)) > 0 THEN D.sfp_driver
					ELSE														 D.sfp_driver_tcp
				END								[df_Fiscal_Model],
				CASE
					WHEN  CharIndex('COM',upper(A.df_Fiscal_ComOrName)) > 0 THEN 'false'
					ELSE														 'true'
				END								[df_Fiscal_Model_IsTCP],
				D.spf_id						,
				A.df_Fiscal_Frame,
				A.fprt_id,
				A.df_Fiscal_FantasyName1,
				A.df_Fiscal_FantasyName2,
				A.df_Fiscal_Address1,
				A.df_Fiscal_Address2,
				A.sd_id,
				A.sdfpt_id,
				G.sdfpt_width,
				G.sdfpt_height,
				--E.sd_isQuotation				[df_IsQuotation],		MOS 08-01-2021
				C.sd_isQuotation				[df_IsQuotation],
				B.fprt_Receipt_Type,
				b.fprt_Receipt_Type4EpsonAR,
				B.fprt_Desc,
				B.fprt_FiscalDocumentType,
				B.fprt_MustEnvieNumber,
				C.sd_isCredit,
				C.sd_isQuotation,
				C.sd_isInBalance,
				C.sd_isReceipt,
				IsNull(A.df_confirm2Print,'False')		 [df_confirm2Print],
				IsNull(A.df_portraitPrint,'True')		 [df_portraitPrint],
				IsNull(A.df_curr_id2Print,tb.curr_id)	 [df_curr_id2Print],
				IsNull(A.df_curr_id2Exchange,tb.curr_id) [df_curr_id2Exchange],
				tb.curr_id								 [df_branchCurrency],
				IsNull(A.df_maxItems,0)					 [df_maxItems],
				ISNULL(A.df_isManualEmitting,'False')	 [df_isManualEmitting],
				wsta.eis_url							 [wsURL_TA],
				ws.eis_serviceName						 [wsServiceName],
				ws.eis_is4Homologation				     [ws4Homologation],
				ISNULL(teip.p12_id,-1)					 [p12ID],
				ISNULL(teip.p12_disabled,'True')		 [p12Disabled],
				teip.p12_desc							 [p12FileName], -- Archivo .12 FE
				teip.p12_password						 [p12password], -- Password Archivo .p12 FE
				teip.p12_cuit							 [p12CUIT],
				a.df_isServicesProvider,
				isnull(A.fedt_id,-1)					 [fedt_id],
				IsNull(a.df_SaleOrderIsMade4AllItem,'False')		[df_SaleOrderIsMade4AllItem],
				A.df_Fiscal_Delay		,
				IsNull(A.df_isInterBranchDocument,'false')			[df_isInterBranchDocument]		,
				IsNull(A.df_eMail2Customer,'False')					[df_eMail2Customer],
				A.df_eMail2Customer_emailFrom,
				A.df_eMail2Customer_emailFromName,
				A.df_eMail2Customer_emailTextBody ,
				IsNull(ws.eis_ClassType,0)							[eis_ClassType],
				IsNull(A.df_isElectronicInvoice,'False')			[df_isElectronicInvoice],
				ISNULL(a.df_SODisableEmmition,'False')				[df_SODisableEmmition],
