				ISNULL(a.wssql_id4preCloseCollection,-1)								[wssql_id4preCloseCollection],
				ISNULL(tdfS.bra_id,-1)													[intBraid4SOInsert],
				ISNULL(A.df_id_4SOInsert,-1)											[intDF_id4SOInsert],
				ISNULL(A.wssql_id4SOInsertItem,-1)										[wssql_id4SOInsertItem],
				ISNULL(A.wssql_id4SOInsertItemPOS,-1)									[wssql_id4SOInsertItemPOS],
				ISNULL(A.wssql_id4SOupdateItem,-1)										[wssql_id4SOupdateItem],
				ISNULL(A.wssql_id4SODeleteItem,-1)										[wssql_id4SODeleteItem],
				ISNULL(A.df_printInCR_rptName,'')										[df_printInCR_rptName],
				ISNULL(A.df_enableSaveAndProcessNow,'False')							[df_enableSaveAndProcessNow],
				ISNULL(A.df_SaleOrderTransfer2Branch_KeepOriginalStorage,'False')		[df_SaleOrderTransfer2Branch_KeepOriginalStorage],
				ISNULL(A.df_SaleOrderSelectStorageOfStorg_id,'False')					[df_SaleOrderSelectStorageOfStorg_id],
				ISNULL(A.df_Fiscal_monotributoLikeRI,'False')							[df_Fiscal_monotributoLikeRI],
				tb.bra_processingDate,
				ISNULL(A.df_SaleOrderZeroEnabled,'False')								[df_SaleOrderZeroEnabled],
				ISNULL(A.df_SaleOrderDetailBlockPrLiChangeByStorChange,'False')			[df_SaleOrderDetailBlockPrLiChangeByStorChange],
				ISNULL(A.df_printQueue_Enabled,'False')									[df_printQueue_Enabled],
				ISNULL(A.printQueue_id,'')												[printQueue_id],
				ISNULL(A.printQueue_printerName,'')										[printQueue_printerName],
				CASE
					WHEN ISNULL(A.df_documentsPrint_HtmlViewerWidth,0) > 0 THEN ISNULL(A.df_documentsPrint_HtmlViewerWidth,0)
					ELSE 300
				END																		[documentsPrint_HtmlViewerWidth],
				ISNULL(tb.country_id,-1)												[country_id],
				ISNULL(A.df_force2SavePDF,'False')										[df_force2SavePDF],
				ISNULL(A.df_force2SavePDF_BlockThreading,'False')						[df_force2SavePDF_BlockThreading],
				ISNULL(A.df_obs1Tooltip,'')												[df_obs1Tooltip],
				ISNULL(A.df_obs2Tooltip,'')												[df_obs2Tooltip],
				ISNULL(A.df_obs3Tooltip,'')												[df_obs3Tooltip],
				ISNULL(A.df_obs4Tooltip,'')												[df_obs4Tooltip]

		from		dbo.tbDocumentsFile A						WITH (NOLOCK)

		INNER JOIN tbBranch tb									WITH (NOLOCK)
			ON		tb.comp_id	= A.comp_id
				AND tb.bra_id	= A.bra_id

		inner JOIN dbo.tbsysDocumentsFilePageType G				WITH (NOLOCK)
			ON  G.sdfpt_id		= A.sdfpt_id

		INNER JOIN dbo.tbsysDocuments C							WITH (NOLOCK)   -- MOS 01-2021, era LEFT
			ON	C.sd_id			= A.Sd_Id


		left JOIN tbsysFiscalPrinterReceiptTypes B				WITH (NOLOCK)
			ON	A.fprt_id = B.fprt_id

		left JOIN dbo.tbsysFiscalPrinters D						WITH (NOLOCK)
			ON	A.spf_id = D.spf_id

		--left JOIN dbo.tbsysDocuments E							WITH (NOLOCK)
		--	ON	A.sd_id = E.sd_id




		LEFT JOIN tbElectronicInvoice_P12Files teip				WITH (NOLOCK)
			ON		teip.comp_id		= a.comp_id
				AND teip.p12_id			= a.p12_id
				AND teip.p12_disabled	= 'False'

		LEFT JOIN tbsysFEWS_Url ws								WITH (NOLOCK)
		 ON ws.eis_id = a.eis_id

		LEFT JOIN tbsysFEWS_Url wsta							WITH (NOLOCK)
		 ON wsta.eis_id = a.eis_id_ta

		LEFT JOIN tbDocumentsFile AS tdfS						WITH (NOLOCK)
			ON	tdfs.comp_id	= A.comp_id AND
				tdfs.df_id		= A.df_id_4SOInsert


		where		A.comp_id		=	@comp_id
			and		A.df_id			=	@df_id
			--and	    A.bra_id		=	@bra_id		NOOOOOOOOOOOOOOOOOO






END




GO



 CREATE PROCEDURE [dbo].[spDocumentsFile_GetDataByIdTransferBranch]

(
			@comp_id			INT,
			@bra_id				INT,
			@df_id				INT,
			@lbra_id_new		INT
)
AS


BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE @comp_id			INT,
			@bra_id				INT,
			@df_id				INT,
			@lbra_id_new		INT

    SELECT  @comp_id			= 1,
			@bra_id				= 1,
			@df_id				= 2,
			@lbra_id_new		= 4

*/
-- ------------------------------------------------------



	SELECT Top 1	tdf2.df_id   [df_if_New],
					tdf2.df_id	 [df_id],
					tdf2.df_desc,
					tdf2.bra_id,
					ISNULL(tdf2.df_SaleOrderTransfer2Branch_KeepOriginalStorage	,'False')		[df_SaleOrderTransfer2Branch_KeepOriginalStorage]
		FROM tbDocumentsFile tdf					WITH (NOLOCK)
		INNER JOIN tbDocumentsFile tdf2				WITH (NOLOCK)
		ON		tdf2.comp_id	= tdf.comp_id
			AND tdf2.sd_id		= tdf.sd_id
			AND tdf2.df_Kindof	= tdf.df_Kindof
		WHERE	tdf.comp_id		= @comp_id
			AND tdf.df_id		= @df_id
			and tdf2.df_id	   <> tdf.df_id
			AND tdf2.bra_id		= @lbra_id_new	AND
				tdf2.df_Disabled = 'False'		AND
				-- MOS 10-11-2021 para que NO seleccione una Fc Anticipada si es q esta en otro orden
				(
					(tdf2.df_SaleOrder_InvoiceFirstPacking_df_id IS NULL		AND tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NULL)
						OR
					(tdf2.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL	AND tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL)
				)
		ORDER BY	tdf2.df_order,
					tdf2.df_desc





END
GO






-- =================================================================
-- Author:		MOS
-- Modif:		MOS  07-2008
-- Retorna si es un documento fiscal
-- =================================================================

CREATE PROCEDURE [dbo].[spDocumentsFile_GetDocumentsForCustomers]
(
	@comp_id			int,
	@bra_id				INT,
	@cust_id			INT,
	@sd_id				INT,
	@IsFavorite4WebSite	BIT,
	@prof_id			INT
)

AS



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

Set NoCount On

BEGIN


	IF @IsFavorite4WebSite = 'True'
		BEGIN
			DECLARE @df_id AS INT = NULL

			IF @prof_id > 0		-- **wefklnw9874lknlknl  MOS 10-2021 x USA
				BEGIN

					SELECT TOP 1 @df_id = tdf.df_id
						FROM tbDocumentsFileAdditionalByFiscalClass AS dfc	WITH (NOLOCK)
						INNER JOIN tbCustomer						AS tc	WITH (NOLOCK)
							ON	tc.comp_id		= @comp_id		AND
								tc.cust_id		= @cust_id
						INNER JOIN tbDocumentsFile					AS tdf	WITH (NOLOCK)
							ON	tdf.comp_id		= dfc.comp_id	AND
								tdf.df_id		= dfc.df_id
						WHERE	dfc.comp_id		= @comp_id		AND
								dfc.fc_id		= tc.fc_id		AND
								dfc.bra_id		= @bra_id		AND
								dfc.prof_id		= @prof_id		AND
								tdf.sd_id		= @sd_id
						ORDER BY
								CASE
									WHEN tdf.df_favorite4WebSite = 1 THEN 0
									ELSE								  1
								END,
								df_order

				END


			IF @df_id IS NOT NULL
				BEGIN
					SELECT @df_id
					RETURN
				END

			SELECT	TOP 1 df_id
				FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
				WHERE	sd_id			= @sd_id
				ORDER BY
					CASE
						WHEN is4WS = 1 THEN 0
						ELSE				1
					END,
					df_order
			RETURN

		END
	ELSE
		BEGIN
			SELECT	TOP 1 df_id
				FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
				WHERE	sd_id			= @sd_id
				ORDER BY df_order
			RETURN
		END


END
GO






-- =================================================================
-- Desc: Verificar si existe el numero de documento
-- Date: 13/09/13
-- Author: GA
-- =================================================================


CREATE PROCEDURE [dbo].[spDocumentsFile_GetExistsDocNumber]
(
	@comp_id			INT ,
	@df_id				INT ,
	@ct_docNumber		NVARCHAR(50)
)

AS



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

Set NoCount On


BEGIN


	------------------------------------------------------

	/*

	DECLARE @comp_id			int ,
			@df_id				INT ,
			@ct_docNumber		NVARCHAR(50)

	SELECT  @comp_id			= 1,
			@df_id				= 2,
			@ct_docNumber		= '22222222222222222222'

	*/

	------------------------------------------------------

	-- Si existe el numero de doc devuelve un 1 , si no existe devuelve un 0 .

		IF EXISTS	(	 SELECT tct.ct_docNumber,
							tct.df_id

						 FROM tbCommercialTransactions				tct

						 INNER JOIN tbDocumentsFile					tdf
						 ON tdf.comp_id		= tct.comp_id AND
							tdf.df_id		= tct.df_id

						 WHERE	tct.comp_id			= @comp_id		AND
								tct.df_id			= @df_id		AND
								tct.ct_docNumber	= @ct_docNumber

					)
						-- Ya existe el numero de documento
						SELECT 1	[ExistsDocNumber]

		ELSE
						-- NO existe el numero de documento
						SELECT 0	[ExistsDocNumber]









END


GO






