CREATE PROCEDURE [dbo].[spDocumentsFile_GetIsElectronicInvoice]
(
	@comp_id			int ,
	@df_id				int
)

AS


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

Set NoCount On

	Select		IsNull(A.df_isElectronicInvoice,'False')			[df_Fiscal_IsElectronicInvoice],
				IsNull(A.df_Fiscal_AlsoPrintDocument,'False')		[df_Fiscal_AlsoPrintDocument],
				ISNULL(a.df_Fiscal_SpoolerGBP,'False')				[df_Fiscal_IsWSSpooler]
		From	dbo.tbDocumentsFile A
		where	A.comp_id		=	@comp_id
		and	    A.df_id 		=	@df_id

GO






