-- =================================================================
-- Author:		MOS
-- Modif:		MOS  07-2008
--				MOS  10-2009
-- Incrementa y devuelve el nuevo numero de comprobante
-- =================================================================

CREATE PROCEDURE [dbo].[spDocumentsFile_GetNewDocumentNumber]
(
	@comp_id	as		int ,
	@df_id		as		int
)

AS

BEGIN


---- -----------------------------------------------------------------------------
---- Para prevenir que alguien haga un query que mate la base para todo el resto.!
---- -----------------------------------------------------------------------------
--SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
--SET LOCK_TIMEOUT 500
--SET DEADLOCK_PRIORITY LOW
---- -----------------------------------------------------------------------------


	Set NoCount On

	DECLARE @intDFIDOriginal as INT
	SET		@intDFIDOriginal = @df_id
	-- ---------------------------------------------------------
	-- Si se debe obtener la numeración de otro documento
	-- se hace en ésta sección
	-- ---------------------------------------------------------
	DECLARE @df_id_getNumber AS INT
	SELECT  @df_id_getNumber = isnull(tdf.df_id_getNumber,@df_id)
		FROM tbDocumentsFile tdf			WITH (NOLOCK)
		WHERE tdf.comp_id = @comp_id
			AND tdf.df_id = @df_id

	SET @df_id = @df_id_getNumber
	-- ---------------------------------------------------------

	Declare @df_number as int

	Update		dbo.tbDocumentsFile		WITH (ROWLOCK)
		Set		df_number   =	df_number + 1
		where	comp_id		=	@comp_id
			and	df_id 		=	@df_id


	SELECT @df_number		=   df_number
		FROM tbDocumentsFile tdf
		where	comp_id		=	@comp_id
			and	df_id 		=	@df_id

	Set @df_number = isnull(@df_number,0)

	-- MOS 10-2017
	IF @df_id <> @intDFIDOriginal
		BEGIN
			Update		dbo.tbDocumentsFile		WITH (ROWLOCK)
				Set		df_number   =	@df_number
				where	comp_id		=	@comp_id
					and	df_id 		=	@intDFIDOriginal
		END


	Select @df_number

END

GO








-- =================================================================
