-- Modif:		MOS  30-8-08
-- Description:	Trae Valores por ID de conf. del sistema
-- =================================================================


CREATE PROCEDURE [dbo].[spDocumentsFile_getPackingListCombo]
(
	@comp_id			int,
	@bra_id				int
)
as
set nocount on


/*
declare @comp_id		int
select 	@comp_id		=1
*/

select		tdf.df_id		[id],
			tdf.df_desc		[desc]

from		dbo.tbDocumentsFile				tdf		WITH (NOLOCK)

			INNER JOIN tbsysDocuments		td		WITH (NOLOCK)
			ON td.sd_id		= tdf.sd_id

where		tdf.comp_id		=	@comp_id
AND			tdf.bra_id		=	@bra_id
AND			td.sd_id		=	2
AND			tdf.df_Disabled = 'False'
ORDER BY tdf.df_desc

















GO








