CREATE PROCEDURE [dbo].[spDocumentsFile_getPackingListCombo2]
(
	@comp_id			int,
	@bra_id				INT,
	@prof_id			INT
)
AS

BEGIN


	set nocount on


	/*
	declare @comp_id		int
	select 	@comp_id		=1
	*/


	IF EXISTS(	SELECT TOP 1 1
	          		FROM tbDocumentsFileByProfile	AS tdfbp		WITH (NOLOCK)
	          		INNER JOIN tbDocumentsFile		AS tdf			WITH (NOLOCK)
	          			ON	tdf.comp_id		= tdfbp.comp_id AND
	          				tdf.bra_id		= tdfbp.bra_id	AND
	          				tdf.df_id		= tdfbp.df_id
	          		WHERE	tdfbp.comp_id	= @comp_id	AND
	          				tdfbp.bra_id	= @bra_id	AND
	          				tdfbp.prof_id	= @prof_id  AND
	          				tdf.sd_id       = 2			AND
	          				tdf.df_Disabled = 'False'
			)
		BEGIN

			select	--DISTINCT
					tdf.df_id		[id],
					tdf.df_desc		[desc]
				from	dbo.tbDocumentsFile tdf					WITH (NOLOCK)
				INNER JOIN tbDocumentsFileByProfile tdfbp		WITH (NOLOCK)
					ON	tdfbp.comp_id	= tdf.comp_id	AND
						tdfbp.bra_id	= tdf.bra_id	AND
						tdfbp.df_id		= tdf.df_id
				where	tdf.comp_id		=	@comp_id	AND
						tdf.bra_id		=	@bra_id		AND
						tdf.sd_id		=	2			AND
						tdf.df_Disabled = 'False'		AND
						tdfbp.prof_id   = @prof_id
				ORDER BY tdf.df_desc

		END
	ELSE
		BEGIN

			select		tdf.df_id		[id],
						tdf.df_desc		[desc]
				from		dbo.tbDocumentsFile				tdf		WITH (NOLOCK)
				INNER JOIN tbsysDocuments					td		WITH (NOLOCK)
					ON td.sd_id		= tdf.sd_id

				where		tdf.comp_id		=	@comp_id
				AND			tdf.bra_id		=	@bra_id
				AND			td.sd_id		=	2
				AND			tdf.df_Disabled = 'False'
				ORDER BY tdf.df_desc

		END



	--select		tdf.df_id		[id],
	--			tdf.df_desc		[desc],
	--			tdf.bra_id,
	--			tdf.df_order,
	--			tdf.df_desc
	--	from		dbo.tbDocumentsFile				tdf		WITH (NOLOCK)

	--	INNER JOIN tbsysDocuments					td		WITH (NOLOCK)
	--		ON td.sd_id		= tdf.sd_id

	--	where		tdf.comp_id		=	@comp_id
	--	AND			tdf.bra_id		=	@bra_id
	--	AND			td.sd_id		=	2
	--	AND			tdf.df_Disabled = 'False'
	--	ORDER BY tdf.df_desc


END














GO







CREATE PROCEDURE [dbo].[spDocumentsFile_getTopOneByCustomerSysDocuments]
(
	@comp_id			INT,
	@bra_id				INT,
	@cust_id			INT,
	@sd_id				INT
)
AS

BEGIN

	SET NOCOUNT ON


	/*********************************
	sd_id	sd_desc
	-----   ---------------
	1		Factura
	2		Remito
	3		Nota de Credito
	4		Nota de Debito
	*********************************/



	/*
	declare	@comp_id		INT,
			@bra_id			INT,
			@cust_id		INT,
			@sd_id			INT
	select 	@comp_id		=1,
			@bra_id			=1,
			@cust_id		=24300,
			@sd_id			=4
	*/


	-- Verifica si hace falta por alguna opcion poner factura tipo E
	DECLARE @bitCustomerBranchInOtherCountryOrTierraDelFuego AS BIT
	SET @bitCustomerBranchInOtherCountryOrTierraDelFuego    = 'False'
	SELECT @bitCustomerBranchInOtherCountryOrTierraDelFuego = 'True'
		FROM tbCustomer tc
		WHERE	tc.comp_id = @comp_id
			AND tc.cust_id = @cust_id
			AND (
				IsNull(tc.country_id,54)	<> 54
			OR	IsNull(tc.state_id,0)		= 54018
			)
	IF @bitCustomerBranchInOtherCountryOrTierraDelFuego = 'False'
		BEGIN
			SELECT @bitCustomerBranchInOtherCountryOrTierraDelFuego = 'True'
				FROM tbCustomerBranch tc
				WHERE	tc.comp_id = @comp_id
					AND tc.cust_id = @cust_id
					AND (
						IsNull(tc.country_id,54)	<> 54
					OR	IsNull(tc.state_id,0)		= 54018
						)
		END








	SELECT TOP 1

	 		DF.df_id		,
			DF.df_desc

	FROM 	dbo.tbDocumentsFile						DF

			-- -------------------------------------------------------------------
			-- Para ver si se excluye el documento para esa provincia de destino
			-- -------------------------------------------------------------------
			INNER JOIN tbCustomer tc
				ON		tc.comp_id = @comp_id
					AND tc.cust_id = @cust_id
			LEFT JOIN tbDocumentsFileDisabledByCustomerState tdfes
				ON		tdfes.comp_id		= tc.comp_id
					AND tdfes.df_id			= df.df_id
					AND tdfes.state_id		= tc.state_id
					AND tdfes.country_id	= tc.country_id
					AND tdfes.[disabled]	= 'True'
			-- -------------------------------------------------------------------


			Inner Join vwsysDocuments_forSaleOrder	VDF
			ON 	VDF.sd_id		= DF.sd_id


	WHERE 	DF.comp_id			= @comp_id
	AND		DF.bra_id			= @bra_id
	AND		DF.df_Disabled		= 'False'
	AND		(dbo.fnStrAllTrim( dbo.fnGetFiscalCustomer_KindOf(@cust_id)) LIKE '%' + DF.df_kindOf  + '%'
			OR DF.df_kindof = 'R'
			OR DF.df_kindof = 'X'
			OR DF.df_kindof = ''
			OR DF.df_kindof = ' '
			OR DF.df_kindof IS NULL
			OR (df.df_Kindof = 'E' AND @bitCustomerBranchInOtherCountryOrTierraDelFuego = 'True')
			)
	AND		(@sd_id = -1 OR DF.sd_id = @sd_id)
	AND tdfes.comp_id IS NULL		-- Si no esta excluido en tbDocumentsFileDisabledByCustomerState, lo trae

	ORDER BY df_Order



END









GO






