CREATE PROCEDURE spDocumentsFile_UpdateCAEADataByFilters
(
	@comp_id		INT,
	@bra_id			INT,
	@dateFrom		DATETIME,
	@dateTo			DATETIME,
	@Caea			NVARCHAR(50),

	@dateFromUPDT	DATETIME,
	@dateToUPDT		DATETIME,
	@CaeaUPDT		NVARCHAR(50)
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@dateFrom		DATETIME,
				@dateTo			DATETIME,
				@Caea			NVARCHAR(50),

				@dateFromUPDT	DATETIME,
				@dateToUPDT		DATETIME,
				@CaeaUPDT		NVARCHAR(50)
		*/
		-- --------------------------------------------

		SET @dateFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'False')
		SET @dateTo		= dbo.fnGetEnd_or_BeginOfDate(@dateTo,	'True')

		UPDATE tbDocumentsFile
		SET
			df_CAEA_fromDate	= @dateFromUPDT,
			df_CAEA_toDate		= @dateToUPDT,
			df_CAEA_CAEANumber	= @CaeaUPDT
		WHERE	comp_id				= @comp_id						AND
				(
					@bra_id				= -1		OR
					bra_id			= @bra_id
				)													AND
				df_CAEA_fromDate	BETWEEN @dateFrom AND @dateTo	AND
				df_CAEA_toDate		BETWEEN @dateFrom AND @dateTo	AND
				ISNULL(df_CAEA_isAvailable,'False')	  = 'True'		AND
				df_CAEA_CAEANumber					  = @Caea

	END
GO

