-- -------------------------------------------------
-- Exportación e Importación de formatos de impresión.
-- -------------------------------------------------
CREATE PROCEDURE [dbo].[spDocumentsFileDesign_Export]
(
	@comp_id	AS INT,
	@df_id		AS INT
)
as

BEGIN

	SET NOCOUNT ON

	DELETE FROM tbDocumentsFileDesign_ExpImp

	INSERT INTO tbDocumentsFileDesign_ExpImp
	(
		comp_id,
		df_id,
		dfd_id,
		bra_id,
		dfdf_order,
		dfdc_id,
		_top,
		_left,
		_width,
		_height,
		_Font_Size,
		_image,
		_text,
		_length,
		isDetail,
		dfdct_id,
		_Color_id,
		_foreColor_id,
		_backColor_id,
		_borderColor_id,
		_fontWeight_id,
		_fontStyle_id,
		_fontTextDecoration_id,
		_borderRight_id,
		_borderTop_id,
		_borderLeft_id,
		_borderBottom_id,
		_font_Family_id,
		_skipPixels,
		_text_align,
		_maxChar
	)

			SELECT
				comp_id,
				df_id,
				dfd_id,
				bra_id,
				dfdf_order,
				dfdc_id,
				_top,
				_left,
				_width,
				_height,
				_Font_Size,
				_image,
				_text,
				_length,
				isDetail,
				dfdct_id,
				_Color_id,
				_foreColor_id,
				_backColor_id,
				_borderColor_id,
				_fontWeight_id,
				_fontStyle_id,
				_fontTextDecoration_id,
				_borderRight_id,
				_borderTop_id,
				_borderLeft_id,
				_borderBottom_id,
				_font_Family_id,
				_skipPixels,
				_text_align,
				_maxChar
			FROM tbDocumentsFileDesign dfd
			WHERE	dfd.comp_id = @comp_id
				AND dfd.df_id	= @df_id
				AND IsNull(dfd.dfd_isDisabled,'False') = 'False'


	select 'DELETE FROM tbDocumentsFileDesign_ExpImp'
	EXEC dbo.sp_generate_inserts 'tbDocumentsFileDesign_ExpImp',@include_column_list=1,@ommit_images=1,@disable_constraints=0,@ommit_computed_cols=1,@deleteData=1

END

GO





CREATE procedure [dbo].[spDocumentsFileDesign_GetAllData]
(
	@df_id		INT
)

as set nocount on



select
	tdfd.comp_id,
	tdfd.df_id,
	tdfd.dfd_id,
	IsNull(tdfd.bra_id,-1)					[bra_id],
	ISNull(tdfd.dfdf_order,0)				[dfdf_order],
	IsNull(tdfd.dfdc_id,-1)					[dfdc_id],
	IsNull(tdfd._top,'')					[_top],
	IsNull(tdfd._left,'')					[_left],
	IsNull(tdfd._width,'')					[_width],
	IsNull(tdfd._height,'')					[_height],
	IsNull(tdfd._Font_Size,'')				[_Font_Size],
	tdfd._image								[_image],
	IsNull(tdfd._text,'')					[_text],
	IsNull(tdfd._length,1)					[_length],
	IsNull(tdfd.isDetail,'False')			[isDetail],
	IsNull(tdfd.dfdct_id,-1)				[dfdct_id],
	IsNull(tdfd._Color_id,-1)				[_Color_id],
	IsNull(tdfd._foreColor_id,-1)			[_foreColor_id],
	IsNull(tdfd._backColor_id,-1)			[_backColor_id],
	IsNull(tdfd._borderColor_id,-1)			[_borderColor_id],
	IsNull(tdfd._fontWeight_id,-1)			[_fontWeight_id],
	IsNull(tdfd._fontStyle_id,-1)			[_fontStyle_id],
	IsNull(tdfd._fontTextDecoration_id,-1)	[_fontTextDecoration_id],
	IsNull(tdfd._borderRight_id,-1)			[_borderRight_id],
	IsNull(tdfd._borderTop_id,-1)			[_borderTop_id],
	IsNull(tdfd._borderLeft_id,-1)			[_borderLeft_id],
	IsNull(tdfd._borderBottom_id,-1)		[_borderBottom_id],
	IsNull(tdfd._font_Family_id,-1)			[_font_Family_id],
	IsNull(tdfd._skipPixels,'')				[_skipPixels],
	IsNull(tdfd._text_align,-1)				[_text_align],
	IsNull(tdfd._maxChar,-1)				[_maxChar],
	IsNull(tdfd.dfd_isDisabled,'False')		[dfd_isDisabled],
	IsNull(tdfd.dfd_Dummy4MaxLen,'')		[dfd_Dummy4MaxLen],
	IsNull(tdfd._border_widthInPX,0)		[_border_widthInPX],
	ISNULL(tdfd.dfd_hideDetailsOfROW,'')	[dfd_hideDetailsOfROW],
	ISNULL(tdfd.dfd_top_AllwaysJoin2Detail,'False')				[dfd_top_AllwaysJoin2Detail],
	ISNULL(tdfd.dfd_top_AdjustY2Detail,'False')					[dfd_top_AdjustY2Detail],
	ISNULL(tdfd.dfd_top_Offset2Detail,0)						[dfd_top_Offset2Detail]

from tbDocumentsFileDesign tdfd		WITH (NOLOCK)

where	tdfd.df_id							= @df_id	AND
		ISNULL(tdfd.dfd_isDisabled,'False') = 'False'
GO






-- ====================================================================================
-- Author:		GA.
-- Create date: 27/06/2011.
-- Parte:		-
-- Description:	Recuperar ct_transaction con el df_id & ct_docNumber
-- ====================================================================================


CREATE PROCEDURE [dbo].[spDocumentsFileDesign_getCt_transaction]

(

		@comp_id			INT,
		@lang_id			INT,

		@df_id				INT,
		@ct_docNumber		nvarchar(50)


)

AS


BEGIN



	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	--------------------------------------------------------------------------------
	-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
	--------------------------------------------------------------------------------
/*
	DECLARE

		@comp_id			INT,
		@lang_id			INT,

		@df_id				INT,
		@ct_docNumber		nvarchar(50)


	SELECT

		@comp_id		= 1,
		@lang_id		= 2,

		@df_id			= 56,
		@ct_docNumber	= 139

*/
	--------------------------------------------------------------------------------
	--------------------------------------------------------------------------------
	--------------------------------------------------------------------------------


	SELECT TOP 1 tct.ct_transaction																	[ct_transaction],
		   dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction)		[description]
		from tbCommercialTransactions																tct WITH (NOLOCK)
		WHERE	tct.comp_id				= @comp_id
		and		tct.df_id				= @df_id
		and		tct.ct_docNumber        = @ct_docNumber
		ORDER BY tct.ct_transaction DESC




END
GO






-- -------------------------------------------------
-- MOS 26-4-08  Please no sacar el Select *
-- -------------------------------------------------

CREATE PROCEDURE [dbo].[spDocumentsFileDesign_getData]
(
	@comp_id			INT,
	@df_id				int
)
AS



BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	set nocount on

	-- -------------------------------------------------
	-- Test
	-- -------------------------------------------------
	/*
	declare @df_id as int
	set @df_id = 2
	*/
	-- -------------------------------------------------

	select		IsNull(C.fb_Desc,'')	    [_border_right],
				IsNull(D.fb_Desc,'')		[_border_top],
				IsNull(E.fb_Desc,'')		[_border_left],
				IsNull(F.fb_Desc,'')		[_border_bottom],
				IsNull(G.color_Value,'')	[_color],
				IsNull(H.color_Value,'')	[_foreColor],
				IsNull(I.color_Value,'')	[_backColor],
				IsNull(J.color_Value,'')    [_borderColor],
				IsNull(K.fw_Desc,'')		[_Font_weight],
				IsNull(L.fs_Desc,'')		[_Font_Style],
				IsNull(M.td_Desc,'')		[_Font_text-decoration],
				IsNull(O.ff_Desc,'')		[_Font_Family],
				A.comp_id,
				tdf.bra_id,
				A.df_id,
				CASE
					WHEN	A.isDetail = 'True'		THEN				  convert(nvarchar(19),A.dfd_id)
													ELSE	'IDNUMBER_' + convert(nvarchar(19),A.dfd_id)
				END							[dfd_id],
				A.dfdf_order,
				A.dfdc_id,
				A._top,
				A._left,
				A._width,
				A._height,
				A._Font_Size,
				A._image,
				IsNull(A._text,'')			[_text],
				A._length,
				isNull(A._maxChar,0)		[_maxChar],
				A.isDetail,
				A.dfdct_id,
				B.dfdc_isDetail,
				B.dfdc_Description,
				B.dfdc_isImage,
				B.dfdc_isFixedText,
				B.dfdc_isHRHorizontal,
				B.dfdc_isHRVertical,
				B.dfdc_isBox,
				P.dfdct_Desc						[_Control_Name],
				IsNull(A._skipPixels,0)				[_skipPixels],
				Isnull(A._text_align,0)				[_text_align],
				IsNull(A._border_widthInPX,0)		[_border_widthInPX],
				IsNull(A.dfd_hideDetailsOfROW,'')	[dfd_hideDetailsOfROW],
				ISNULL(A.dfd_disableIncrementalROW,'False')					[dfd_disableIncrementalROW],
				A.dfd_id                                                    [__dfdID],
				ROW_NUMBER() OVER (ORDER BY A.dfdf_order DESC) AS 			[Reference],  -- MOS 11-2019, no toque nada pero no se PORQUE MIERDA HACE 13 años puse esto así ( NO TOCAR )  **weflkqwe-%#%&# de codigo VB
				ISNULL(A.dfd_top_AllwaysJoin2Detail,'False')				[dfd_top_AllwaysJoin2Detail],
				ISNULL(A.dfd_top_AdjustY2Detail,'False')					[dfd_top_AdjustY2Detail],
				ISNULL(A.dfd_top_Offset2Detail,0)							[dfd_top_Offset2Detail],
				ISNULL(A._detail_addRowBeforePrint,'False')					[_detail_addRowBeforePrint],
				ISNULL(cmp.comp_CAEByQR,'False')							[comp_CAEByQR],
				ISNULL(A._detail_addRow4maxChar,'False')					[_detail_addRow4maxChar]




	--INTO #tmpTable
		from		dbo.tbDocumentsFileDesign A				WITH (NOLOCK)
		INNER JOIN tbCompany					cmp			WITH (NOLOCK)
			ON cmp.comp_id      = A.comp_id
		INNER JOIN tbdocumentsfile tdf						WITH (NOLOCK)
			ON	tdf.comp_id		= A.comp_id AND
				tdf.df_id		= A.df_id

		INNER JOIN	dbo.tbsysDocumentsFileDesignControls B	WITH (NOLOCK)
			ON		A.dfdc_id = B.dfdc_id

		Left  Join  dbo.tbsysfontdef_Borders C				WITH (NOLOCK)
			On		C.fb_id = A._BorderRight_id

		Left  Join  dbo.tbsysfontdef_Borders D				WITH (NOLOCK)
			On		D.fb_id = A._BorderTop_id

		Left  Join  dbo.tbsysfontdef_Borders E				WITH (NOLOCK)
			On		E.fb_id = A._BorderLeft_id

		Left  Join  dbo.tbsysfontdef_Borders F				WITH (NOLOCK)
			On		F.fb_id = A._BorderBottom_id

		Left  Join  dbo.tbsysfontdef_Colors		 G			WITH (NOLOCK)
			On		G.color_id = A._color_id

		Left  Join  dbo.tbsysfontdef_Colors		 H			WITH (NOLOCK)
			On		H.color_id = A._foreColor_id

		Left  Join  dbo.tbsysfontdef_Colors		 I			WITH (NOLOCK)
			On		I.color_id = A._backColor_id

		Left  Join  dbo.tbsysfontdef_Colors		 J			WITH (NOLOCK)
			On		J.color_id = A._borderColor_id

		Left  Join  dbo.tbsysfontdef_Weight		 K			WITH (NOLOCK)
				On	K.fw_id = A._fontWeight_id

		Left  Join  dbo.tbsysfontdef_Style		 L			WITH (NOLOCK)
				On	L.fs_id = A._fontStyle_id

		Left  Join  dbo.tbsysfontdef_TextDecoration		 M	WITH (NOLOCK)
				On	M.td_id = A._fontTextDecoration_id

		Left  Join  dbo.tbsysfontdef_Family		 O			WITH (NOLOCK)
				On	O.ff_id = A._font_Family_id

		Left JOIN	dbo.tbsysDocumentsFileDesignControlsTypes P	WITH (NOLOCK)
			ON		P.dfdct_id = A.dfdct_id

		Where	A.comp_id			= @comp_id	AND
				A.df_id				= @df_id	AND
				A.dfd_isDisabled	= 'False'

	ORDER BY	[Reference]	 --A.dfdf_order



END
GO






