CREATE PROCEDURE [dbo].[spDocumentsFileDesign_InsertData]
(
	@comp_id			int,
	@bra_id				Int,
	@df_From			Int,
	@df_To				Int
)
As
set nocount ON

BEGIN

/*
DECLARE @comp_id			int,
	@bra_id				Int,
	@df_From			Int,
	@df_To				INT
SELECT @comp_id			=1,
	@bra_id				=1,
	@df_From			=1,
	@df_To				=72
*/


	Insert into tbDocumentsFileDesign
	(
		comp_id,
		bra_id,
		df_id,
		dfdf_order,
		dfdc_id,
		_top,
		_left,
		_width,
		_height,
		_Font_Size,
		_image,
		_text,
		_length,
		isDetail,
		dfdct_id,
		_Color_id,
		_foreColor_id,
		_backColor_id,
		_borderColor_id,
		_fontWeight_id,
		_fontStyle_id,
		_fontTextDecoration_id,
		_borderRight_id,
		_borderTop_id,
		_borderLeft_id,
		_borderBottom_id,
		_font_Family_id,
		_skipPixels,
		_text_align
	)

	(
		Select	tdfd.comp_id,
			   (select	df.bra_id
			    from	tbDocumentsFile df
			    where	df.comp_id	= @comp_id
			    and		df.df_id	= @df_to)									/*tdfd.bra_id*/,
				@df_To,
				tdfd.dfdf_order, tdfd.dfdc_id, tdfd._top, tdfd._left,
				tdfd._width, tdfd._height, tdfd._Font_Size, tdfd._image,
				tdfd._text, tdfd._length, tdfd.isDetail, tdfd.dfdct_id,
				tdfd._Color_id, tdfd._foreColor_id, tdfd._backColor_id,
				tdfd._borderColor_id, tdfd._fontWeight_id, tdfd._fontStyle_id,
				tdfd._fontTextDecoration_id, tdfd._borderRight_id,
				tdfd._borderTop_id, tdfd._borderLeft_id, tdfd._borderBottom_id,
				tdfd._font_Family_id, tdfd._skipPixels, tdfd._text_align
		From	tbDocumentsFileDesign tdfd
		Where	tdfd.comp_id			= @comp_id
			--AND tdfd.bra_id				= @bra_id    -- 2010-07-0-17 - MOH - Sin parte
			AND	tdfd.df_id			    = @df_From
			AND ISNULL(tdfd.dfd_isDisabled,'False')='False'
	)


END







GO





CREATE  procedure [dbo].[spDocumentsFileDesign_InsertDataForImport]
(
	@comp_id				INT,
	@df_id					INT,
	@bra_id					int,
	@dfdf_order				INT,
	@dfdc_id				INT,
	@top					VARCHAR(100),
	@left					varchar(100),
	@width					varchar(100),
	@height					varchar(100),
	@Font_Size				varchar(100),
	@image					image,
	@text					nvarchar(4000),
	@length					int,
	@isDetail				bit,
	@dfdct_id				int,
	@Color_id				int,
	@foreColor_id			int,
	@backColor_id			int,
	@borderColor_id			int,
	@fontWeight_id			int,
	@fontStyle_id			int,
	@fontTextDecoration_id	int,
	@borderRight_id			int,
	@borderTop_id			int,
	@borderLeft_id			int,
	@borderBottom_id		int,
	@font_Family_id			int,
	@skipPixels				int,
	@text_align				int,
	@maxChar				int,
	@dfd_isDisabled			bit,
	@dfd_Dummy4MaxLen		nvarchar(200),
	@delete					bit,
	@_border_widthInPX		INT,
	@pdfd_hideDetailsOfROW	NVARCHAR(500),
	@dfd_top_AllwaysJoin2Detail	bit,
	@dfd_top_AdjustY2Detail		bit,
	@dfd_top_Offset2Detail		int

)

AS

BEGIN




	 set nocount on


	-- --------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------
	/*
		declare
			@comp_id				INT,
			@df_id					INT,
			@bra_id					int,
			@dfdf_order				INT,
			@dfdc_id				INT,
			@top					VARCHAR(100),
			@left					varchar(100),
			@width					varchar(100),
			@height					varchar(100),
			@Font_Size				varchar(100),
			@image					image,
			@text					varchar(1000),
			@length					int,
			@isDetail				bit,
			@dfdct_id				int,
			@Color_id				int,
			@foreColor_id			int,
			@backColor_id			int,
			@borderColor_id			int,
			@fontWeight_id			int,
			@fontStyle_id			int,
			@fontTextDecoration_id	int,
			@borderRight_id			int,
			@borderTop_id			int,
			@borderLeft_id			int,
			@borderBottom_id		int,
			@font_Family_id			int,
			@skipPixels				int,
			@text_align				int,
			@maxChar				int,
			@dfd_isDisabled			bit,
			@dfd_Dummy4MaxLen		nvarchar(200),
			@delete					bit
	*/



	if @delete = 'True'
		begin

			delete from tbDocumentsFileDesign
			where comp_id	= @comp_id
			and df_id		= @df_id

		end


	--ACA OBTENGO EL COMP_ID PROPIO DEL DOCUMENT FILE LOCAL QUE QUIERO REEMPLAZAR, ESTA BIEN ASI? LO DEJO ACA ESCRITO POR SI LAS DUDAS CUANDO LO VEAS

	Declare @lcomp_id	int,
			@lbra_id	int
	select
		@lcomp_id	= tdf.comp_id,
		@lbra_id	= tdf.bra_id

	from tbDocumentsFile tdf
	where tdf.df_id = @df_id

	-- ----------------------------------------------------------------------
	-- Seteamos los -1 como NULOS
	-- ----------------------------------------------------------------------


	if	(@bra_id				= -1)	set	@bra_id					= NULL
	if	(@dfdf_order			=  0)	set	@dfdf_order				= NULL
	if	(@dfdc_id				= -1)	set	@dfdc_id				= NULL
	--	@top					VARCHAR(100),
	--	@left					varchar(100),
	--	@width					varchar(100),
	--	@height					varchar(100),
	--	@Font_Size				varchar(100),
	--	@image					image,
	--	@text					varchar(1000),
	if	(@length				= -1)	set @length					= NULL
	--	@isDetail				bit,
	if	(@dfdct_id				= -1)	set	@dfdct_id				= NULL
	if	(@Color_id				= -1)	set @Color_id				= NULL
	if	(@foreColor_id			= -1)	set	@foreColor_id			= NULL
	if	(@backColor_id			= -1)	set @backColor_id			= NULL
	if	(@borderColor_id		= -1)	set	@borderColor_id			= NULL
	if	(@fontWeight_id			= -1)	set @fontWeight_id			= NULL
	if	(@fontStyle_id			= -1)	set @fontStyle_id			= NULL
	if	(@fontTextDecoration_id	= -1)	set	@fontTextDecoration_id	= NULL
	if	(@borderRight_id		= -1)	set @borderRight_id			= NULL
	if	(@borderTop_id			= -1)	set @borderTop_id			= NULL
	if	(@borderLeft_id			= -1)	set @borderLeft_id			= NULL
	if	(@borderBottom_id		= -1)	set @borderBottom_id		= NULL
	if	(@font_Family_id		= -1)	set @font_Family_id			= NULL
	if	(@skipPixels			= -1)	set @skipPixels				= NULL
	if	(@text_align			= -1)	set @text_align				= NULL
	if	(@maxChar				= -1)	set @maxChar				= NULL
	--	@dfd_isDisabled			bit,
	--	@dfd_Dummy4MaxLen		nvarchar(200),
	--	@delete					bit,


	-- ----------------------------------------------------------------------



	insert into tbDocumentsFileDesign
	(
		comp_id,
		df_id,
		bra_id,
		dfdf_order,
		dfdc_id,
		_top,
		_left,
		_width,
		_height,
		_Font_Size,
		_image,
		_text,
		_length,
		isDetail,
		dfdct_id,
		_Color_id,
		_foreColor_id,
		_backColor_id,
		_borderColor_id,
		_fontWeight_id,
		_fontStyle_id,
		_fontTextDecoration_id,
		_borderRight_id,
		_borderTop_id,
		_borderLeft_id,
		_borderBottom_id,
		_font_Family_id,
		_skipPixels,
		_text_align,
		_maxChar,
		dfd_isDisabled,
		dfd_Dummy4MaxLen,
		_border_widthInPX,
		dfd_hideDetailsOfROW,
		dfd_top_AllwaysJoin2Detail,
		dfd_top_AdjustY2Detail,
		dfd_top_Offset2Detail
	)
	VALUES
	(
		@lcomp_id,
		@df_id,
		@lbra_id,
		@dfdf_order,
		@dfdc_id,
		@top,
		@left,
		@width,
		@height,
		@Font_Size,
		@image,
		@text,
		@length,
		@isDetail,
		@dfdct_id,
		@Color_id,
		@foreColor_id,
		@backColor_id,
		@borderColor_id,
		@fontWeight_id,
		@fontStyle_id,
		@fontTextDecoration_id,
		@borderRight_id,
		@borderTop_id,
		@borderLeft_id,
		@borderBottom_id,
		@font_Family_id,
		@skipPixels,
		@text_align,
		@maxChar,
		@dfd_isDisabled,
		@dfd_Dummy4MaxLen,
		@_border_widthInPX,
		@pdfd_hideDetailsOfROW,
		@dfd_top_AllwaysJoin2Detail,
		@dfd_top_AdjustY2Detail,
		@dfd_top_Offset2Detail
	)




END
GO







CREATE PROCEDURE [dbo].[spDocumentsFileDesign_updateDataForImport]
(
	@comp_id	INT,
	@df_id		INT
)
AS
SET NOCOUNT ON



/*
DECLARE	@comp_id	INT,
		@df_id		INT
SELECT	@comp_id	= 1,
		@df_id		= 64
*/





/*Actualizo la tabla tbDocumentsFileDesign_ExpImp con la Compañía y el DF_ID de la compañía en la que estoy importando el diseño
* también hay que actualizar la sucursal*/
UPDATE tbDocumentsFileDesign_ExpImp
SET		comp_id = @comp_id,
		df_id	= @df_id,
		bra_id	= (SELECT bra_id FROM tbDocumentsFile tdf WHERE tdf.comp_id = @comp_id AND tdf.df_id = @df_id) -- 2010-08-17 - MOH - Sin Parte






/*Elimino los registros anteriores con ese DF_ID de la tabla para poder insertar los registros importados*/
DELETE tbDocumentsFileDesign WHERE comp_id = @comp_id AND df_id = @df_id






/*Inserto el nuevo diseño, con la compañía y el df_id actualizado*/
INSERT INTO tbDocumentsFileDesign
(
	comp_id,						df_id,
	bra_id,							dfdf_order,
	dfdc_id,						_top,
	_left,							_width,
	_height,						_Font_Size,
	_image,							_text,
	_length,						isDetail,
	dfdct_id,						_Color_id,
	_foreColor_id,					_backColor_id,
	_borderColor_id,				_fontWeight_id,
	_fontStyle_id,					_fontTextDecoration_id,
	_borderRight_id,				_borderTop_id,
	_borderLeft_id,					_borderBottom_id,
	_font_Family_id,				_skipPixels,
	_text_align,					_maxChar
)
SELECT
	tdfdei.comp_id,					tdfdei.df_id,
	tdfdei.bra_id,					tdfdei.dfdf_order,
	tdfdei.dfdc_id,					tdfdei._top,
	tdfdei._left,					tdfdei._width,
	tdfdei._height,					tdfdei._Font_Size,
	tdfdei._image,					tdfdei._text,
	tdfdei._length,					tdfdei.isDetail,
	tdfdei.dfdct_id,				tdfdei._Color_id,
	tdfdei._foreColor_id,			tdfdei._backColor_id,
	tdfdei._borderColor_id,			tdfdei._fontWeight_id,
	tdfdei._fontStyle_id,			tdfdei._fontTextDecoration_id,
	tdfdei._borderRight_id,			tdfdei._borderTop_id,
	tdfdei._borderLeft_id,			tdfdei._borderBottom_id,
	tdfdei._font_Family_id,			tdfdei._skipPixels,
	tdfdei._text_align,				tdfdei._maxChar

FROM tbDocumentsFileDesign_ExpImp tdfdei






/*Borramos la tabla que guardaba el documento Exportado6*/
DELETE FROM tbDocumentsFileDesign_ExpImp


GO








