------------------------------------------------------------

CREATE PROCEDURE [dbo].[spDocumentsFileDesign_UpdatePixels]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@user_id		INT,
	@df_id			INT,
	@axis			BIT,
	@value			INT


)

AS SET NOCOUNT ON



-----------------------------------------------------------------------------------
-----------------------------------------------------------------------------------
-----------------------------------------------------------------------------------
/*


DECLARE		@comp_id		INT,
			@lang_id		INT,
			@bra_id			INT,
			@prof_id		INT,
			@user_id		INT,
			@df_id			INT,
			@axis			BIT,
			@value			INT



SELECT		@comp_id		=1,
			@lang_id		=2,
			@bra_id			=1,
			@prof_id		=1,
			@user_id		=1,
			@df_id			=2,
			@axis			='false',
			@value			=1

*/
-----------------------------------------------------------------------------------
-----------------------------------------------------------------------------------
-----------------------------------------------------------------------------------
--@axis 0- Vertical , 1 - Horizontal



BEGIN

	if @axis = 'true' --Horizontal

			BEGIN
				update tbDocumentsFileDesign
				SET _left = convert(nvarchar(100),(convert(int,replace(_left,'px','')) + @value )) + 'px'
				where df_id = @df_id


			END

	else
			--Vertical
			BEGIN
				update tbDocumentsFileDesign
				SET _top = convert(nvarchar(100),(convert(int,replace(_top,'px','')) + @value )) + 'px'
				where df_id = @df_id
			END


END
GO




CREATE PROCEDURE spDocumentVersionIsReaded_getDataById
(
	@comp_id		INT,
	@doc_id			INT,
	@doc_version	INT,
	@user_id		INT
)
AS SET NOCOUNT ON

	BEGIN
		-- ----------------------------------
		-- TESTING
		-- ----------------------------------
		/*
		DECLARE
			@comp_id		INT,
			@doc_id			INT,
			@doc_version	INT,
			@user_id		INT
		SELECT
			@comp_id		= 1,
			@doc_id			= 1,
			@doc_version	= 1,
			@user_id		= 1
		*/
		-- ----------------------------------


		SELECT
			tcdvir.comp_id,
			tcdvir.doc_id,
			tcdvir.doc_version,
			tcdvir.[user_id],
			tcdvir.docvu_isReaded,
			tcdvir.docvu_isreadedDate

		FROM tbCRM_DocumentVersionIsReaded tcdvir

		WHERE	tcdvir.comp_id		= @comp_id		AND
				tcdvir.doc_id		= @doc_id		AND
				tcdvir.doc_version	= @doc_version	AND
				tcdvir.[user_id]	= @user_id

	END
GO

CREATE PROCEDURE spDocumetsFile_UpdateCAEAData
(
	@comp_id		INT,
	@bra_id			INT,
	@df_id			INT,
	@dateFrom		DATETIME,
	@dateTo			DATETIME,
	@Caea			NVARCHAR(50)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@df_id			INT,
				@dateFrom		DATETIME,
				@dateTo			DATETIME,
				@Caea			NVARCHAR(50)
		*/
		-- ------------------------------------

		UPDATE tbDocumentsFile
		SET
			df_CAEA_fromDate	= @dateFrom,
			df_CAEA_toDate		= @dateTo,
			df_CAEA_CAEANumber	= @Caea
			WHERE	comp_id		= @comp_id AND
					bra_id		= @bra_id AND
					df_id		= @df_id

	END
GO



