CREATE PROCEDURE [dbo].[spEffectivenessAnalysisBudgets_getReport]

	(
		@comp_id					INT,
		@lang_id					INT,
		@page_id					INT,

		@guid_Item					VARCHAR(50),
		@guid_Cust					VARCHAR(50),

		@datefrom					DATETIME,
		@dateto						DATETIME,

		@sm_id						INT,
		@st_id						INT,
		@dl_id						INT,
		@stor_id					INT,
		@option						INT,

		@bra_id						INT,
		@prof_id					INT,
		@user_id					INT,
		@intBranch4Lang				INT

   )
AS



	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -------------------------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id					INT,
				@lang_id					INT,
				@page_id					INT,

				@guid_Item					VARCHAR(50),
				@guid_Cust					VARCHAR(50),

				@datefrom					DATETIME,
				@dateto						DATETIME,

				@sm_id						INT,
				@st_id						INT,
				@dl_id						INT,
				@stor_id					INT,

				@bra_id						INT,
				@prof_id					INT,
				@user_id					INT,
				@intBranch4Lang				INT,
				@option						INT	-- 1 Facturado / 2 Presupuestos / -1 Todos



			SELECT
				@comp_id			=1,
				@lang_id			=2,
				@page_id			=100963,

				@guid_Item			= '3F2504E0-4F89-11D3-9A0C-0305E82C3301',
				@guid_Cust			= '30B7E39A-67D7-4F3D-921D-34C3ACE34C59',
				@sm_id				= -1,
				@st_id				= -1,
				@dl_id				= -1,
				@stor_id			= -1,
				@prof_id			=  1,
				@user_id			= 41,
				@bra_id				= 26,
				@datefrom			= '2017-09-01',
				@dateto				= '2017-10-10',
				@option				= -1

			 DROP TABLE #tmpPresupuestos
	*/
		-- -------------------------------------------------------------------------

		DECLARE @fun_id INT
		SET     @fun_id = 1
		SET	@datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')
		DECLARE @lGuid_Item AS UNIQUEIDENTIFIER
		SET @lGuid_Item = CONVERT(UNIQUEIDENTIFIER,@guid_Item)

		DECLARE @strPedidoVigente AS NVARCHAR(100)
		SELECT
		 @strPedidoVigente		= tut.utexts_desc
		FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
		WHERE	tut.lang_id		= @lang_id	AND
				tut.utexts_id	= 30876

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf		WITH (NOLOCK)
				WHERE tcf.sl_guid = @lGuid_Item     AND
					  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti		WITH (NOLOCK)
						WHERE ti.comp_id = @comp_id
			END
		-- -------------------------------------------------------------

		DECLARE @lGuid_Cust AS UNIQUEIDENTIFIER

		SET @lGuid_Cust = CONVERT(UNIQUEIDENTIFIER,@guid_Cust)


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf		WITH (NOLOCK)
				WHERE tcf.sl_guid = @lGuid_Cust     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT tc.cust_id
					FROM tbCustomer tc		WITH (NOLOCK)
						WHERE tc.comp_id = @comp_id
			END

		--==
			--SELECT * FROM @tblComplexFilter_Customer
		--==
		-- -------------------------------------------------------------


		-- ---------------------------------------------------------------------------------------------
		-- PRESUPUESTOS NO FACTURADOS VIGENTES
		-- FILTRO POR LOS CLIENTES QUE PUSO EN LOS FILTROS
		-- ---------------------------------------------------------------------------------------------
		DECLARE @tblPresupuestos TABLE (comp_id INT,bra_id INT,soh_id	INT)
		IF @option = 2 OR @option = -1
			BEGIN

				INSERT INTO @tblPresupuestos
				(
					comp_id,
					bra_id,
					soh_id
				)
				SELECT DISTINCT
					tsoh.comp_id,
					tsoh.bra_id,
					tsoh.soh_id
					FROM tbSaleOrderHeader					tsoh		WITH (NOLOCK)
						INNER JOIN tbSaleOrderDetail		tsod		WITH (NOLOCK)
						ON	tsod.comp_id	= tsoh.comp_id	AND
							tsod.bra_id		= tsoh.bra_id	AND
							tsod.soh_id		= tsoh.soh_id
						INNER JOIN tbDocumentsFile			tdf		WITH (NOLOCK)
						ON	tdf.comp_id		= tsoh.comp_id	AND
							tdf.df_id		= tsoh.df_id	AND
							tdf.sd_id		= 5
						INNER JOIN @tblComplexFilter_Customer	tmpCust
						ON	tmpCust.cust_id = tsoh.cust_id
						-- 26/05/2017 STL
						INNER JOIN @tblComplexFilter_Items		tmpITEM
						ON	tmpITEM.item_id	= tsod.item_id
						--
					WHERE	tsoh.comp_id	= @comp_id	AND
							tsoh.bra_id		= @bra_id	AND
							(	@sm_id		= -1 OR
								tsoh.sm_id	= @sm_id
							)							AND
							(	@st_id		= -1 OR
								tsoh.st_id	= @st_id
							)							AND
							(
								@dl_id		= -1 OR
								tsoh.st_id	= @dl_id
							)							AND
							(
								@stor_id		= -1 OR
								tsod.stor_id	= @stor_id
							)							AND
							tsoh.soh_cd		BETWEEN @datefrom AND @dateto

				--==
					--SELECT * FROM @tblPresupuestos
				--==
				--
			END
		-- ---------------------------------------------------------------------------------------------

		-- ---------------------------------------------------------------------------------------------
		-- PRESUPUESTOS FACTURADOS / PRESUPUESTOS ELIMINADOS / DEPURADOS
		-- FILTRO POR LOS CLIENTES QUE PUSO EN LOS FILTROS
		-- ---------------------------------------------------------------------------------------------
		DECLARE @tblMaxupdSaleorderHistory TABLE (comp_id INT,bra_id INT,soh_id	INT,sohh_id	INT)
		IF @option = 1 OR @option = -1
			BEGIN
				INSERT INTO @tblMaxupdSaleorderHistory
				(
					comp_id,
					bra_id,
					soh_id,
					sohh_id
				)
				SELECT DISTINCT
					tsohh.comp_id											[comp_id],
					tsohh.bra_id											[bra_id],
					tsohh.soh_id											[soh_id],
					MAX(tsohh.sohh_id)										[sohh_id]
					FROM tbSaleOrderHeaderHistory							tsohh		WITH (NOLOCK)
						INNER JOIN tbSaleOrderDetailHistory					tsodh		WITH (NOLOCK)
						ON	tsodh.comp_id	= tsohh.comp_id					AND
							tsodh.bra_id	= tsohh.bra_id					AND
							tsodh.soh_id	= tsohh.soh_id					AND
							tsodh.sohh_id	= tsohh.sohh_id
						INNER JOIN @tblComplexFilter_Customer				tmpCust
						ON	tmpCust.cust_id = tsohh.cust_id
						-- 26/05/2017 STL
						INNER JOIN @tblComplexFilter_Items					tmpITEM
						ON	tmpITEM.item_id	= tsodh.item_id
						--
						INNER JOIN tbDocumentsFile							tdf		WITH (NOLOCK)
						ON	tdf.comp_id		= tsohh.comp_id					AND
							tdf.df_id		= tsohh.df_id					AND
							tdf.sd_id		= 1
					WHERE	tsohh.comp_id	= @comp_id						AND
							tsohh.bra_id	= @bra_id						AND
							tsohh.soh_cd	BETWEEN @datefrom AND @dateto	AND
							(	@sm_id		= -1 OR
								tsohh.sm_id	= @sm_id
							)												AND
							(	@st_id		= -1 OR
								tsohh.st_id	= @st_id
							)												AND
							(
								@dl_id		= -1 OR
								tsohh.st_id	= @dl_id
							)												AND
							(
								@stor_id		= -1 OR
								tsodh.stor_id	= @stor_id
							)												AND
							(
								tsohh.sohh_TypeOfHistory = 10	OR
								tsohh.sohh_TypeOfHistory = 20	OR
								tsohh.sohh_TypeOfHistory = 30
							)
					GROUP BY tsohh.comp_id,tsohh.bra_id,tsohh.soh_id,tsohh.sohh_TypeOfHistory
			END
		--==
			--SELECT * FROM @tblMaxupdSaleorderHistory
		--==
		-- ---------------------------------------------------------------------------------------------

		-- ---------------------------------------------------------------------------------------------
		-- PRESUPUESTOS - PRIMER REGISTRO CON EL TOTAL ORIGINAL DEL PEDIDO
		-- EN CASO DE QUE HAYA SUFRIDO ALGUNA MODIFICACIÓN, POR ESO SOLO UTILIZO LOS QUE TIENEN
		-- el SOHH_TYPEOFHISTORY = 1
		-- ---------------------------------------------------------------------------------------------
		DECLARE @tblSaleorderHistory_TotalOriginal TABLE (comp_id INT,bra_id INT,soh_id	INT,sohh_id	INT)
		INSERT INTO @tblSaleorderHistory_TotalOriginal
		(
			comp_id,
			bra_id,
			soh_id,
			sohh_id
		)
		SELECT DISTINCT
			tsohh.comp_id											[comp_id],
			tsohh.bra_id											[bra_id],
			tsohh.soh_id											[soh_id],
			MIN(tsohh.sohh_id)										[sohh_id]
			FROM tbSaleOrderHeaderHistory							tsohh		WITH (NOLOCK)
				INNER JOIN tbSaleOrderDetailHistory					tsodh		WITH (NOLOCK)
				ON	tsodh.comp_id	= tsohh.comp_id					AND
					tsodh.bra_id	= tsohh.bra_id					AND
					tsodh.soh_id	= tsohh.soh_id					AND
					tsodh.sohh_id	= tsohh.sohh_id
				INNER JOIN @tblComplexFilter_Customer				tmpCust
				ON	tmpCust.cust_id = tsohh.cust_id
				-- 26/05/2017 STL
				INNER JOIN @tblComplexFilter_Items					tmpITEM
				ON	tmpITEM.item_id	= tsodh.item_id
				--
				INNER JOIN tbDocumentsFile							tdf		WITH (NOLOCK)
				ON	tdf.comp_id		= tsohh.comp_id					AND
					tdf.df_id		= tsohh.df_id					AND
					tdf.sd_id		= 5
			WHERE	tsohh.comp_id	= @comp_id						AND
					tsohh.bra_id	= @bra_id						AND
					tsohh.soh_cd	BETWEEN @datefrom AND @dateto	AND
					(	@sm_id		= -1 OR
						tsohh.sm_id	= @sm_id
					)												AND
					(	@st_id		= -1 OR
						tsohh.st_id	= @st_id
					)												AND
					(
						@dl_id		= -1 OR
						tsohh.st_id	= @st_id
					)												AND
					(
						@stor_id		= -1 OR
						tsodh.stor_id	= @stor_id
					)												AND
					(
						tsohh.sohh_TypeOfHistory = 1	--OR
						--tsohh.sohh_TypeOfHistory = 10	OR
						--tsohh.sohh_TypeOfHistory = 20	OR
						--tsohh.sohh_TypeOfHistory = 30
					)
			GROUP BY tsohh.comp_id,tsohh.bra_id,tsohh.soh_id,tsohh.sohh_TypeOfHistory


		--==
			--SELECT * FROM @tblSaleorderHistory_TotalOriginal
		--==
		-- ---------------------------------------------------------------------------------------------




		-- -----------------------------------------------------------------------------------------
		-- OBTENGO MONEDA DE LA SUCURSAL
		-- -----------------------------------------------------------------------------------------

			DECLARE
				@bra_curr_id		INT,
				@bra_curr_symbol	VARCHAR(10)

			SELECT
				@bra_curr_id		= tb.curr_id,
				@bra_curr_symbol	= tc.curr_symbol
				FROM tbBranch					tb		WITH (NOLOCK)
					INNER JOIN tbsysCurrency	tc		WITH (NOLOCK)
					ON	tc.curr_id	= tb.curr_id
				WHERE	tb.comp_id	= @comp_id	AND
						tb.bra_id	= @bra_id


			--==
				--SELECT @bra_curr_id [Bra_Curr_Id], @bra_curr_symbol [Bra_Curr_Symbol]
			--==
		-- -----------------------------------------------------------------------------------------



		-- --------------------------------------------------------------------------------------------------------------------------
		-- Trae los articulos FACTURADOS
		-- --------------------------------------------------------------------------------------------------------------------------
			SELECT
				dbo.fnStrPADL(CONVERT(VARCHAR,tsohh.bra_id),4,'0') + '-' + dbo.fnStrPADL(CONVERT(VARCHAR, tsohh.soh_id),10,'0') /*+ ' / ' + dbo.fnStrAllTrim(CONVERT(NVARCHAR,tsohh.soh_id))*/  [SaleOrderNumber],
				tsohh.sohh_cd												[soh_cd],
				tov.optval_desc												[Action],
				ti.item_code												[item_code],
				ti.item_desc												[item_desc],
				tdf.df_desc,
				tov.optval_id,
				tsohh.comp_id,
				tsohh.bra_id,
				tsohh.soh_id,
				temptsohh.sohh_id,
				tsod.item_id,
				tsod.sod_qty,
				tsod.sod_price,
				tc.cat_desc,
				tsc.subcat_desc,
				ts.sm_name,
				dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction) [Document],
				tc2.cust_name,
				tc2.cust_id
				INTO #tmpPresupuestos
				FROM tbSaleOrderHeaderHistory					tsohh			WITH (NOLOCK)
					INNER JOIN @tblMaxupdSaleorderHistory		temptsohh
					ON  temptsohh.comp_id	= tsohh.comp_id		AND
						temptsohh.bra_id	= tsohh.bra_id		AND
						temptsohh.soh_id	= tsohh.soh_id		AND
						temptsohh.sohh_id	= tsohh.sohh_id
					INNER JOIN tbSaleOrderDetailHistory			tsod			WITH (NOLOCK)
					ON  tsod.comp_id		= temptsohh.comp_id	AND
						tsod.bra_id			= temptsohh.bra_id	AND
						tsod.soh_id			= temptsohh.soh_id	AND
						tsod.sohh_id		= temptsohh.sohh_id
					INNER JOIN tbCommercialTransactions			tct				WITH (NOLOCK)	-- MOS 10-2017
					ON	tct.comp_id			= tsohh.comp_id		AND
						tct.ct_soh_bra_id	= tsohh.bra_id		AND
						tct.ct_soh_id		= tsohh.soh_id
					INNER JOIN tbItemTransactions					tit			WITH(NOLOCK) --LO AGREGUE PARA QUE SOLO MUESTRE LOS ARTICULOS QUE SE FACTURARON
					ON	tit.comp_id			= tct.comp_id			AND
						tit.ct_transaction	= tct.ct_transaction	AND
						ISNULL(tit.item_id,tit.item_idfromPreInvoice)	= tsod.item_id -- MOS 08-2024
					INNER JOIN tbItem							ti				WITH (NOLOCK)
					ON	ti.comp_id			= tsod.comp_id		AND
						ti.item_id			= tsod.item_id
					INNER JOIN tbCategory						tc				WITH (NOLOCK)
					ON	tc.comp_id			= ti.comp_id		AND
						tc.cat_id			= ti.cat_id
					INNER JOIN tbSubCategory					tsc				WITH (NOLOCK)
					ON	tsc.comp_id			= ti.comp_id		AND
						tsc.cat_id			= ti.cat_id			AND
						tsc.subcat_id		= ti.subcat_id
					INNER JOIN @tblComplexFilter_Items			tempITEM
					ON	tempitem.item_id	= ti.item_id
					INNER JOIN tbDocumentsFile					tdf				WITH (NOLOCK)
					ON  tdf.comp_id			= tsohh.comp_id		AND
						tdf.df_id			= tsohh.df_id		--AND
						--tdf.sd_id			= 5
					LEFT JOIN tbsysOptionsValues				tov				WITH (NOLOCK)
					ON	tov.lang_id			= @lang_id			AND
						tov.optval_class	= 999				AND
						tov.optval_id		= tsohh.sohh_TypeOfHistory
					INNER JOIN tbSalesman						ts		WITH (NOLOCK)
					ON	ts.comp_id			= tsohh.comp_id		AND
						ts.sm_id			= tsohh.sm_id
					INNER JOIN tbCustomer						tc2		WITH (NOLOCK)
					ON	tc2.comp_id			= tsohh.comp_id		AND
						tc2.cust_id			= tsohh.cust_id
				WHERE	tct.comp_id = @comp_id AND
						tct.sd_id	= 1		-- Solo FACTURADOS por FACTURA		-- MOS 10-2017


		UNION
			-- PRESUPUESTOS
			-- --------------------------------------------------------------------------------------------------------------------------
			-- NOTAS
			-- SAQUE EL tdf.sd_id			= 5 PORQUE YA LOS FILTRE CUANDO LOS CARGUÉ EN LA TABLA
			-- --------------------------------------------------------------------------------------------------------------------------
			SELECT
				dbo.fnStrPADL(CONVERT(VARCHAR,tsoh.bra_id),4,'0') + '-' + dbo.fnStrPADL(CONVERT(VARCHAR, tsoh.soh_id),10,'0') /*+ ' / ' + dbo.fnStrAllTrim(CONVERT(NVARCHAR,tsoh.soh_id))*/  [SaleOrderNumber],
				tsoh.soh_cd													[soh_cd],
				@strPedidoVigente											[Action],
				ti.item_code												[item_code],
				ti.item_desc												[item_desc],
				tdf.df_desc,
				''															[optval_id],
				tsoh.comp_id,
				tsoh.bra_id,
				tsoh.soh_id,
				'' [sohh_id],
				tsod.item_id,
				tsod.sod_qty,
				tsod.sod_price,
				tc.cat_desc,
				tsc.subcat_desc	,
				ts.sm_name,
				/*dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)*/ '' [Document],
				tc2.cust_name,
				tc2.cust_id
				FROM tbSaleOrderHeader							tsoh		WITH (NOLOCK)
					INNER JOIN @tblPresupuestos					temptsoh
					ON  temptsoh.comp_id		= tsoh.comp_id	AND
						temptsoh.bra_id			= tsoh.bra_id	AND
						temptsoh.soh_id			= tsoh.soh_id
					INNER JOIN tbSaleOrderDetail				tsod		WITH (NOLOCK)
					ON  tsod.comp_id			= tsoh.comp_id	AND
						tsod.bra_id				= tsoh.bra_id	AND
						tsod.soh_id				= tsoh.soh_id
					--LEFT JOIN tbCommercialTransactions			tct			WITH (NOLOCK)	-- MOS 10-2017
					--ON	tct.comp_id				= tsoh.comp_id	AND
					--	tct.ct_soh_bra_id		= tsoh.bra_id	AND
					--	tct.ct_soh_id			= tsoh.soh_id
					INNER JOIN tbItem							ti			WITH (NOLOCK)
					ON	ti.comp_id				= tsod.comp_id	AND
						ti.item_id				= tsod.item_id
					INNER JOIN tbCategory						tc			WITH (NOLOCK)
					ON	tc.comp_id				= ti.comp_id	AND
						tc.cat_id				= ti.cat_id
					INNER JOIN tbSubCategory					tsc			WITH (NOLOCK)
					ON	tsc.comp_id				= ti.comp_id	AND
						tsc.cat_id				= ti.cat_id		AND
						tsc.subcat_id			= ti.subcat_id
					INNER JOIN @tblComplexFilter_Items			tempITEM
					ON	tempitem.item_id		= ti.item_id
					INNER JOIN tbDocumentsFile					tdf			WITH (NOLOCK)
					ON  tdf.comp_id				= tsoh.comp_id	AND
						tdf.df_id				= tsoh.df_id
					INNER JOIN tbSalesman						ts		WITH (NOLOCK)
					ON	ts.comp_id				= tsoh.comp_id	AND
						ts.sm_id				= tsoh.sm_id

					INNER JOIN tbCustomer						tc2		WITH (NOLOCK)
					ON	tc2.comp_id				= tsoh.comp_id	AND
						tc2.cust_id				= tsoh.cust_id


				--WHERE	tsoh.comp_id			= @comp_id									AND
				--		(tsoh.soh_cd			BETWEEN		@datefrom	AND	@dateto)		--AND
						--(@sm_id					= -1    OR tsoh.sm_id		= @sm_id)		AND
						--(@st_id					= -1    OR tsoh.st_id		= @st_id)		AND
						--(@dl_id					= -1    OR tsoh.dl_id		= @dl_id)		AND
						--(@stor_id				= -1    OR tsod.stor_id		= @stor_id)


		UNION

			-- Trae los presupuestos de los que se modifico el precio con respecto al original o las cantidades
			SELECT
				dbo.fnStrPADL(CONVERT(VARCHAR,tsohh.bra_id),4,'0') + '-' + dbo.fnStrPADL(CONVERT(VARCHAR, tsohh.soh_id),10,'0') /*+ ' / ' + dbo.fnStrAllTrim(CONVERT(NVARCHAR,tsohh.soh_id))*/  [SaleOrderNumber],
				tsohh.sohh_cd												[soh_cd],
				tov.optval_desc												[Action],
				ti.item_code												[item_code],
				ti.item_desc												[item_desc],
				tdf.df_desc,
				tov.optval_id,
				tsohh.comp_id,
				tsohh.bra_id,
				tsohh.soh_id,
				temptsohh.sohh_id,
				tsod.item_id,
				tsod.sod_qty,
				tsod.sod_price,
				tc.cat_desc,
				tsc.subcat_desc,
				ts.sm_name,
				dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction) [Document],
				tc2.cust_name,
				tc2.cust_id
				FROM tbSaleOrderHeaderHistory						tsohh			WITH (NOLOCK)
					INNER JOIN @tblSaleorderHistory_TotalOriginal	temptsohh
					ON  temptsohh.comp_id	= tsohh.comp_id		AND
						temptsohh.bra_id	= tsohh.bra_id		AND
						temptsohh.soh_id	= tsohh.soh_id		AND
						temptsohh.sohh_id	= tsohh.sohh_id
					INNER JOIN tbSaleOrderDetailHistory			tsod			WITH (NOLOCK)
					ON  tsod.comp_id		= tsohh.comp_id		AND
						tsod.bra_id			= tsohh.bra_id		AND
						tsod.soh_id			= tsohh.soh_id		AND
						tsod.sohh_id		= tsohh.sohh_id
					INNER JOIN tbCommercialTransactions			tct				WITH (NOLOCK)		-- MOS 10-2017
					ON	tct.comp_id			= tsohh.comp_id		AND
						tct.ct_soh_bra_id	= tsohh.bra_id		AND
						tct.ct_soh_id		= tsohh.soh_id
					INNER JOIN tbItem							ti				WITH (NOLOCK)
					ON	ti.comp_id			= tsod.comp_id		AND
						ti.item_id			= tsod.item_id
					INNER JOIN tbCategory						tc				WITH (NOLOCK)
					ON	tc.comp_id			= ti.comp_id		AND
						tc.cat_id			= ti.cat_id
					INNER JOIN tbSubCategory					tsc				WITH (NOLOCK)
					ON	tsc.comp_id			= ti.comp_id		AND
						tsc.cat_id			= ti.cat_id			AND
						tsc.subcat_id		= ti.subcat_id
					INNER JOIN @tblComplexFilter_Items			tempITEM
					ON	tempitem.item_id	= ti.item_id
					INNER JOIN tbDocumentsFile					tdf				WITH (NOLOCK)
					ON  tdf.comp_id			= tsohh.comp_id		AND
						tdf.df_id			= tsohh.df_id		--AND
						--tdf.sd_id			= 5
					LEFT JOIN tbsysOptionsValues				tov				WITH (NOLOCK)
					ON	tov.lang_id			= @lang_id			AND
						tov.optval_class	= 999				AND
						tov.optval_id		= tsohh.sohh_TypeOfHistory
					INNER JOIN tbSalesman						ts		WITH (NOLOCK)
					ON	ts.comp_id			= tsohh.comp_id		AND
						ts.sm_id			= tsohh.sm_id

					INNER JOIN tbCustomer						tc2		WITH (NOLOCK)
					ON	tc2.comp_id			= tsohh.comp_id		AND
						tc2.cust_id			= tsohh.cust_id

				WHERE	tct.comp_id = @comp_id	AND
						tct.sd_id	= 1			AND	-- Solo FACTURADOS por FACTURA		-- MOS 10-2017
					tsod.item_id NOT IN (SELECT
											tsodh.item_id
											FROM @tblMaxupdSaleorderHistory		tmp
											INNER JOIN tbSaleOrderDetailHistory tsodh
											ON	tsodh.comp_id = tmp.comp_id		AND
												tsodh.sohh_id = tmp.sohh_id)

			ORDER BY [SaleOrderNumber],tc.cat_desc,tsc.subcat_desc, ti.item_desc





			SELECT
				*
				FROM #tmpPresupuestos
				ORDER BY	soh_id ASC

				--ORDER BY	[SaleOrderNumber],
				--			cat_desc,
				--			subcat_desc,
				--			item_desc

		EXEC spReports_getData3  @comp_id, @bra_id, @lang_id, @page_id, 1

		DROP TABLE #tmpPresupuestos

		-- --------------------------------------------
		-- CANTIDAD TOTAL DE PRESUPUESTOS
		-- --------------------------------------------

			DECLARE
				@lCantTotalPresupuestos			INT,
				@lCantPresupuestosVigentes		INT,
				@lCantPresupuestosFC_DEL_DEP	INT

			SET	@lCantTotalPresupuestos			= 0
			SET	@lCantPresupuestosVigentes		= 0
			SET @lCantPresupuestosFC_DEL_DEP	= 0

			--PRESUPUESTOS VIGENTES
			SELECT
				@lCantPresupuestosVigentes = COUNT(*)
				FROM @tblPresupuestos

			--PRESUPUESTOS QUE SE FACTURARON / BORRARON / DEPURARON
			SELECT
				@lCantPresupuestosFC_DEL_DEP = COUNT(*)
				FROM @tblMaxupdSaleorderHistory

			SET @lCantTotalPresupuestos = @lCantPresupuestosVigentes + @lCantPresupuestosFC_DEL_DEP

			--==
			--SELECT
			--	@lCantPresupuestosVigentes		[CantPresupuestosVigentes],
			--	@lCantPresupuestosFC_DEL_DEP	[CantPresupuestosFC_DEL_DEP],
			--	@lCantTotalPresupuestos			[CantTotalPresupuestos]
			--==

		-- --------------------------------------------

		-- --------------------------------------------
		-- CANT PRESUPUESTOS QUE SE FACTURARON
		-- --------------------------------------------
			DECLARE @lCantPresupuestosFacturados	INT
			SET		@lCantPresupuestosFacturados	= 0


			SELECT
				@lCantPresupuestosFacturados = COUNT(*)
			FROM @tblMaxupdSaleorderHistory					tmpID
				INNER JOIN tbSaleOrderHeaderHistory			tsohh		WITH (NOLOCK)
				ON	tsohh.comp_id		= tmpID.comp_id		AND
					tsohh.bra_id		= tmpID.bra_id		AND
					tsohh.soh_id		= tmpID.soh_id		AND
					tsohh.sohh_id		= tmpID.sohh_id
			WHERE	tmpID.comp_id		= @comp_id			AND
					tmpid.bra_id		= @bra_id			AND
					tsohh.sohh_TypeOfHistory	= 10

			--==
			--SELECT
			--	@lCantPresupuestosFacturados [CantPresupuestosFacturados]
			--==
		-- --------------------------------------------

		-- --------------------------------------------
		-- CANT PRESUPUESTOS QUE NO SE FACTURARON
		-- --------------------------------------------
			DECLARE
				@lCantPresupuestosNoFacturados	INT,
				@lCantPresupuestosVigentesNoFC	INT,
				@lCantPresupuestos_DEL_DEP		INT

			SET	@lCantPresupuestosNoFacturados	= 0
			SET	@lCantPresupuestosVigentesNoFC	= 0
			SET @lCantPresupuestos_DEL_DEP		= 0

			--PRESUPUESTOS VIGENTES EN SOH
			SELECT
				@lCantPresupuestosVigentesNoFC = COUNT(*)
				FROM @tblPresupuestos			tmpID
			WHERE	tmpID.comp_id	= @comp_id

			-- PRESUPUESTOS BORRADOS O DEPURADOS QUE NO SE LLEGARON A FACTURAR
			SELECT
				@lCantPresupuestos_DEL_DEP = COUNT(*)
			FROM @tblMaxupdSaleorderHistory			tmpID
				INNER JOIN tbSaleOrderHeaderHistory tsohh		WITH (NOLOCK)
				ON	tsohh.comp_id	= tmpID.comp_id AND
					tsohh.bra_id	= tmpID.bra_id	AND
					tsohh.soh_id	= tmpID.soh_id	AND
					tsohh.sohh_id	= tmpID.sohh_id
			WHERE tmpID.comp_id = @comp_id AND
					(
						tsohh.sohh_TypeOfHistory = 20 OR
						tsohh.sohh_TypeOfHistory = 30
					)


			SET @lCantPresupuestosNoFacturados = @lCantPresupuestosVigentesNoFC + @lCantPresupuestos_DEL_DEP
--==
--SELECT
--	@lCantPresupuestosVigentesNoFC	[CantPresupuestosVigentesNoFC],
--	@lCantPresupuestos_DEL_DEP		[CantPresupuestos_DEL_DEP]
--==
		-- --------------------------------------------


		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- HAGO LA SUMA GENERAL DE TODOS LOS TOTALES POR CADA PRESUPUESTO PARA PODER INFORMAR CUANTO DINERO SE GENERÓ A PARTIR DE LA FACTURACIÓN Y CUANTO DINERO NO INGRESÓ

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------
			DECLARE
				@lTotalPresupuestos						DECIMAL(25,2),
				@lTotalPresupuestosFC_DEL_DEP			DECIMAL(25,2),
				@lTotalPresupuestosVigentes				DECIMAL(25,2),
				@lTotalPresupuestosFacturados			DECIMAL(25,2),
				@lTotalPresupuestosNoFacturados			DECIMAL(25,2),
				@lTOtalPresupuestosNoFacturados_DEL_DEP	DECIMAL(25,2),
				@lTotalPresupuestosNoFacturadosVigentes	DECIMAL(25,2),
				@lTotalPresupuestosPreciosOriginales	DECIMAL(25,2)
			SET	@lTotalPresupuestos						= 0
			SET @lTotalPresupuestosVigentes				= 0
			SET	@lTotalPresupuestosFacturados			= 0
			SET	@lTotalPresupuestosNoFacturados			= 0

			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- SUMA TOTAL DE PRESUPUESTOS (Fact y No Fact)
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------

				--PRESUPUESTOS QUE ESTAN FACTURADOS / BORRADOS / DEPURADOS
				SELECT
					@lTotalPresupuestosFC_DEL_DEP	= ISNULL(SUM(ISNULL(dbo.fnGetExchange(tsodh.comp_id,
																						  tsodh.sod_price,
																						  tsodh.curr_id,
																						  @bra_curr_id,
																						  0,
																						  0,
																						  0),0) * tsodh.sod_qty),0)
					--(tsodh.sod_price - (tsodh.sod_price * td.disc_coef)) / dbo.fnNoZDiv(1 + (tsodh.sod_itemDiscount / 100))
					FROM @tblMaxupdSaleorderHistory			tmp
						INNER JOIN tbSaleOrderHeaderHistory tsohh		WITH (NOLOCK)
						ON	tsohh.comp_id	= tmp.comp_id	AND
							tsohh.bra_id	= tmp.bra_id	AND
							tsohh.soh_id	= tmp.soh_id	AND
							tsohh.sohh_id	= tmp.sohh_id
						INNER JOIN tbSaleOrderDetailHistory tsodh				WITH (NOLOCK)
						ON	tsodh.comp_id	= tsohh.comp_id	AND
							tsodh.bra_id	= tsohh.bra_id	AND
							tsodh.soh_id	= tsohh.soh_id	AND
							tsodh.sohh_id	= tsohh.sohh_id
						-- AGREGADO PARA QUE SOLO SUME LOS ARTICULOS FACTURADOS
						INNER JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
						ON	tct.comp_id			= tsohh.comp_id			AND
							tct.ct_transaction	= tsohh.ct_transaction
						INNER JOIN tbItemTransactions					tit		WITH (NOLOCK)
						ON	tit.comp_id			= tct.comp_id			AND
							tit.ct_transaction	= tct.ct_transaction	AND
							ISNULL(tit.item_id,tit.item_idfromPreInvoice)	= tsodh.item_id	-- MOS 08-2024

						-- STL 22/05/2017
						INNER JOIN @tblComplexFilter_Items				TMPItems
						ON	TMPItems.item_id	= tsodh.item_id
						--

						--
						--INNER JOIN tbDiscount				td
						--ON	td.comp_id		= tsohh.comp_id AND
						--	td.disc_id		= tsohh.disc_id
					WHERE	tmp.comp_id		= @comp_id		AND
							tsodh.item_id	IS NOT NULL		AND
							tsodh.sod_qty	IS NOT NULL		AND
							tsodh.sod_price IS NOT NULL		AND
							tsodh.curr_id	IS NOT NULL		AND
							tsodh.comp_id	IS NOT NULL




--==
--SELECT 'dfweqfweq'
--SELECT * FROM @tblMaxupdSaleorderHistory

--SELECT
--*
--	FROM @tblMaxupdSaleorderHistory			tmp
--		INNER JOIN tbSaleOrderHeaderHistory tsohh
--		ON	tsohh.comp_id	= tmp.comp_id	AND
--			tsohh.bra_id	= tmp.bra_id	AND
--			tsohh.soh_id	= tmp.soh_id	AND
--			tsohh.sohh_id	= tmp.sohh_id
--		INNER JOIN tbSaleOrderDetailHistory tsodh
--		ON	tsodh.comp_id	= tsohh.comp_id	AND
--			tsodh.bra_id	= tsohh.bra_id	AND
--			tsodh.soh_id	= tsohh.soh_id	AND
--			tsodh.sohh_id	= tsohh.sohh_id
--		-- AGREGADO PARA QUE SOLO SUME LOS ARTICULOS FACTURADOS
--		INNER JOIN tbCommercialTransactions				tct
--		ON	tct.comp_id			= tsohh.comp_id			AND
--			tct.ct_transaction	= tsohh.ct_transaction
--		INNER JOIN tbItemTransactions					tit
--		ON	tit.comp_id			= tct.comp_id			AND
--			tit.ct_transaction	= tct.ct_transaction	AND
--			tit.item_id			= tsodh.item_id

--		-- STL 22/05/2017
--		INNER JOIN @tblComplexFilter_Items				TMPItems
--		ON	TMPItems.item_id	= tsodh.item_id
--		--

--		--
--		--INNER JOIN tbDiscount				td
--		--ON	td.comp_id		= tsohh.comp_id AND
--		--	td.disc_id		= tsohh.disc_id
--	WHERE	tmp.comp_id		= @comp_id		AND
--			tsodh.item_id	IS NOT NULL		AND
--			tsodh.sod_qty	IS NOT NULL		AND
--			tsodh.sod_price IS NOT NULL		AND
--			tsodh.curr_id	IS NOT NULL		AND
--			tsodh.comp_id	IS NOT NULL
--==


				--PRESUPUESTOS VIGENTES
				SELECT
					@lTotalPresupuestosVigentes = ISNULL(SUM(ISNULL(dbo.fnGetExchange(tsod.comp_id,
																					  tsod.sod_price,
																					  tsod.curr_id,
																					  @bra_curr_id,
																					  0,
																					  0,
																					  0),0) * tsod.sod_qty),0)
					--(tsod.sod_price - (tsod.sod_price * td.disc_coef)) / dbo.fnNoZDiv(1 + (tsod.sod_itemDiscount / 100))
					FROM @tblPresupuestos					tmpID
						INNER JOIN tbSaleOrderHeader		tsoh		WITH (NOLOCK)
						ON	tsoh.comp_id	= tmpID.comp_id	AND
							tsoh.bra_id		= tmpID.bra_id	AND
							tsoh.soh_id		= tmpID.soh_id
						INNER JOIN tbSaleOrderDetail		tsod		WITH (NOLOCK)
						ON	tsod.comp_id	= tsoh.comp_id	AND
							tsod.bra_id		= tsoh.bra_id	AND
							tsod.soh_id		= tsoh.soh_id
						--STL 22/05/2017
						INNER JOIN @tblComplexFilter_Items	tmpITEMS
						ON tmpITEMS.item_id	= tsod.item_id
						--
						--INNER JOIN tbDiscount				td
						--ON	td.comp_id		= tsoh.comp_id	AND
						--	td.disc_id		= tsoh.disc_id
					WHERE	tmpID.comp_id	= @comp_id		AND
							tsod.item_id	IS NOT NULL


				SET @lTotalPresupuestos = @lTotalPresupuestosFC_DEL_DEP + @lTotalPresupuestosVigentes

--==
	--SELECT
	--	@lTotalPresupuestosFC_DEL_DEP	[TotalPresupuestosFC_DEL_DEP],
	--	@lTotalPresupuestosVigentes		[TotalPresupuestosVigentes],
	--	@lTotalPresupuestos				[Total Presupuestos]
--==
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------

			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- SUMA PRESUPUESTOS FACT Y NO FACT ( CON PRECIOS ORIGINALES )
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------

				--TODOS LOS QUE SUFRIERON UNA MODIFICACIÓN, UTILIZAMOS EL PRIMER REGISTRO QUE GRABÓ EL TOTAL ORIGINAL DEL PRESUPUESTO
				SELECT
					@lTotalPresupuestosPreciosOriginales  = ISNULL(SUM(ISNULL(dbo.fnGetExchange(tsodh.comp_id,
																								tsodh.sod_price,
																								tsodh.curr_id,
																								@bra_curr_id,
																								0,
																								0,
																								0),0) * tsodh.sod_qty),0)
					--(tsodh.sod_price - (tsodh.sod_price * td.disc_coef)) / dbo.fnNoZDiv(1 + (tsodh.sod_itemDiscount / 100))
					FROM @tblSaleorderHistory_TotalOriginal	tmpID
					INNER JOIN tbSaleOrderHeaderHistory		tsohh		WITH (NOLOCK)
					ON	tsohh.comp_id	= tmpID.comp_id		AND
						tsohh.bra_id	= tmpID.bra_id		AND
						tsohh.soh_id	= tmpID.soh_id		AND
						tsohh.sohh_id	= tmpID.sohh_id
					INNER JOIN tbSaleOrderDetailHistory		tsodh		WITH (NOLOCK)
					ON	tsodh.comp_id	= tsohh.comp_id		AND
						tsodh.bra_id	= tsohh.bra_id		AND
						tsodh.soh_id	= tsohh.soh_id		AND
						tsodh.sohh_id	= tsohh.sohh_id
					--STL 22/05/2017
					INNER JOIN @tblComplexFilter_Items		tmpITEMS
					ON	tmpITEMS.item_id= tsodh.item_id
					--
					--INNER JOIN tbDiscount					td
					--ON	td.comp_id		= tsohh.comp_id		AND
					--	td.disc_id		= tsohh.disc_id
					WHERE tmpid.comp_id = @comp_id			AND
						  tsodh.item_id IS NOT NULL


				--ACA DEBERIA SUMAR TODOS LOS QUE SE FACTURARON, QUE SE BORRARON Y QUE SE DEPURARON PERO QUE YA NO ESTEN SUMADOS ANTES ARRIBA
				SELECT
					@lTotalPresupuestosPreciosOriginales =	@lTotalPresupuestosPreciosOriginales +
															ISNULL(SUM(ISNULL(dbo.fnGetExchange(tsodh.comp_id,
																								tsodh.sod_price,
																								tsodh.curr_id,
																								@bra_curr_id,
																								0,
																								0,
																								0),0) * tsodh.sod_qty),0)
					--(tsodh.sod_price - (tsodh.sod_price * td.disc_coef)) / dbo.fnNoZDiv(1 + (tsodh.sod_itemDiscount / 100))
					FROM @tblMaxupdSaleorderHistory				tmp
						INNER JOIN tbSaleOrderHeaderHistory		tsohh		WITH (NOLOCK)
						ON	tsohh.comp_id	= tmp.comp_id		AND
							tsohh.bra_id	= tmp.bra_id		AND
							tsohh.soh_id	= tmp.soh_id		AND
							tsohh.sohh_id	= tmp.sohh_id
						INNER JOIN tbSaleOrderDetailHistory		tsodh		WITH (NOLOCK)
						ON	tsodh.comp_id	= tsohh.comp_id		AND
							tsodh.bra_id	= tsohh.bra_id		AND
							tsodh.soh_id	= tsohh.soh_id		AND
							tsodh.sohh_id	= tsohh.sohh_id
						--STL 22/05/2017
						INNER JOIN @tblComplexFilter_Items		tmpITEMS
						ON	tmpITEMS.item_id= tsodh.item_id
						--
						-- SOLO LOS FACTURADOS
						INNER JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
						ON	tct.comp_id			= tsohh.comp_id			AND
							tct.ct_transaction	= tsohh.ct_transaction
						INNER JOIN tbItemTransactions					tit		WITH (NOLOCK)
						ON	tit.comp_id			= tct.comp_id			AND
							tit.ct_transaction	= tct.ct_transaction	AND
							ISNULL(tit.item_id,tit.item_idfromPreInvoice)			= tsodh.item_id	-- MOS 08-2024
						--
						--INNER JOIN tbDiscount					td
						--ON	td.comp_id		= tsohh.comp_id		AND
						--	td.disc_id		= tsohh.disc_id
					WHERE	tmp.comp_id		= @comp_id		AND--CONVIENE HACER NOT IN????
							tmp.soh_id NOT IN (SELECT
													tmp.soh_id
													FROM @tblSaleorderHistory_TotalOriginal	tmp
													WHERE tmp.comp_id = @comp_id)


				--ACA DEBERIA SUMAR LOS PRESUPUESTOS VIGENTES QUE NO SE FACTURARON Y QUE NO SUFRIERON NINGUNA MODIFICACIÓN
				SELECT
					@lTotalPresupuestosPreciosOriginales = @lTotalPresupuestosPreciosOriginales + ISNULL(SUM(ISNULL(dbo.fnGetExchange(tsod.comp_id,
																																	  tsod.sod_price,
																																	  tsod.curr_id,
																																	  @bra_curr_id,
																																	  0,
																																	  0,
																																	  0),0) * tsod.sod_qty),0)
					--(tsod.sod_price - (tsod.sod_price * td.disc_coef)) / dbo.fnNoZDiv(1 + (tsod.sod_itemDiscount / 100))
					FROM @tblPresupuestos					tmpID
						INNER JOIN tbSaleOrderHeader		tsoh		WITH (NOLOCK)
						ON	tsoh.comp_id	= tmpID.comp_id	AND
							tsoh.bra_id		= tmpID.bra_id	AND
							tsoh.soh_id		= tmpID.soh_id
						INNER JOIN tbSaleOrderDetail		tsod		WITH (NOLOCK)
						ON	tsod.comp_id	= tsoh.comp_id	AND
							tsod.bra_id		= tsoh.bra_id	AND
							tsod.soh_id		= tsoh.soh_id
						--STL 22/05/2017
						INNER JOIN @tblComplexFilter_Items	tmpITEMS
						ON	tmpITEMS.item_id= tsod.item_id
						--
						--INNER JOIN tbDiscount				td
						--ON	td.comp_id		= tsoh.comp_id	AND
						--	td.disc_id		= tsoh.disc_id

					WHERE	tmpID.comp_id	= @comp_id		AND --CONVIENE HACER NOT IN????
							tmpID.soh_id	NOT IN (SELECT
														tmp.soh_id
														FROM @tblSaleorderHistory_TotalOriginal	tmp
														WHERE tmp.comp_id = @comp_id)



			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------


			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- SUMA TOTAL PRESUPUESTOS FACTURADOS
			-- LOS QUE TIENEN TYPEOFHISTORY = 10
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
				SELECT
					@lTotalPresupuestosFacturados = ISNULL(SUM(ISNULL(dbo.fnGetExchange(tsodh.comp_id,
																					    tsodh.sod_price,
																					    tsodh.curr_id,
																					    @bra_curr_id,
																					    0,
																					    0,
																					    0),0) * tsodh.sod_qty),0)
					--(tsodh.sod_price - (tsodh.sod_price * td.disc_coef)) / dbo.fnNoZDiv(1 + (tsodh.sod_itemDiscount / 100))
					FROM @tblMaxupdSaleorderHistory			tmp
						INNER JOIN tbSaleOrderHeaderHistory tsohh		WITH (NOLOCK)
						ON	tsohh.comp_id	= tmp.comp_id	AND
							tsohh.bra_id	= tmp.bra_id	AND
							tsohh.soh_id	= tmp.soh_id	AND
							tsohh.sohh_id	= tmp.sohh_id
						INNER JOIN tbSaleOrderDetailHistory tsodh				WITH (NOLOCK)
						ON	tsodh.comp_id	= tsohh.comp_id	AND
							tsodh.bra_id	= tsohh.bra_id	AND
							tsodh.soh_id	= tsohh.soh_id	AND
							tsodh.sohh_id	= tsohh.sohh_id
						--STL 22/05/2017
						INNER JOIN @tblComplexFilter_Items	tmpITEMS
						ON	tmpITEMS.item_id= tsodh.item_id
						--
						-- AGREGUE ESTO PARA QUE SOLO SUME LOS ARTICULOS QUE HAN SIDO FACTURADOS STL 08/05/2017
						INNER JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
						ON	tct.comp_id			= tsohh.comp_id			AND
							tct.ct_transaction	= tsohh.ct_transaction
						INNER JOIN tbItemTransactions					tit		WITH (NOLOCK)
						ON	tit.comp_id			= tct.comp_id			AND
							tit.ct_transaction	= tct.ct_transaction	AND
							ISNULL(tit.item_id,tit.item_idfromPreInvoice)		= tsodh.item_id -- MOS 08-2024
						--
						--INNER JOIN tbDiscount				td
						--ON	td.comp_id		= tsohh.comp_id AND
						--	td.disc_id		= tsohh.disc_id
					WHERE	tmp.comp_id		= @comp_id		AND
							tsodh.item_id	IS NOT NULL		AND
							tsohh.sohh_TypeOfHistory	= 10

				--SELECT @lTotalPresupuestosFacturados [Presupuestos Facturados]
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------

			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- SUMA TOTAL PRESUPUESTOS NO FACTURADOS
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
				-- PRESUPUESTOS NO FACTURADOS PORQUE HAN SIDO BORRADOS O DEPURADOS
				SELECT
					@lTOtalPresupuestosNoFacturados_DEL_DEP = ISNULL(SUM(ISNULL(dbo.fnGetExchange(tsodh.comp_id,
																								  tsodh.sod_price,
																								  tsodh.curr_id,
																								  @bra_curr_id,
																								  0,
																								  0,
																								  0),0) * tsodh.sod_qty),0)
					--(tsodh.sod_price - (tsodh.sod_price * td.disc_coef)) / dbo.fnNoZDiv(1 + (tsodh.sod_itemDiscount / 100))
					FROM @tblMaxupdSaleorderHistory				tmp
						INNER JOIN tbSaleOrderHeaderHistory		tsohh		WITH (NOLOCK)
						ON	tsohh.comp_id	= tmp.comp_id		AND
							tsohh.bra_id	= tmp.bra_id		AND
							tsohh.soh_id	= tmp.soh_id		AND
							tsohh.sohh_id	= tmp.sohh_id
						INNER JOIN tbSaleOrderDetailHistory		tsodh				WITH (NOLOCK)
						ON	tsodh.comp_id	= tsohh.comp_id		AND
							tsodh.bra_id	= tsohh.bra_id		AND
							tsodh.soh_id	= tsohh.soh_id		AND
							tsodh.sohh_id	= tsohh.sohh_id
						--STL 22/05/2017
						INNER JOIN @tblComplexFilter_Items		tmpITEMS
						ON	tmpITEMS.item_id= tsodh.item_id
						--
						--INNER JOIN tbDiscount					td
						--ON	td.comp_id		= tsohh.comp_id		AND
						--	td.disc_id		= tsohh.disc_id
						WHERE	tmp.comp_id		= @comp_id		AND
								tsodh.item_id	IS NOT NULL		AND
								tsohh.sohh_TypeOfHistory	<> 10

				-- PRESUPUESTOS VIGENTES
				SELECT
					@lTotalPresupuestosNoFacturadosVigentes = ISNULL(SUM(ISNULL(dbo.fnGetExchange(tsod.comp_id,
																								  tsod.sod_price,
																								  tsod.curr_id,
																								  @bra_curr_id,
																								  0,
																								  0,
																								  0),0) * tsod.sod_qty),0)
					--(tsod.sod_price - (tsod.sod_price * td.disc_coef)) / dbo.fnNoZDiv(1 + (tsod.sod_itemDiscount / 100))
					FROM @tblPresupuestos						tmp
						INNER JOIN tbSaleOrderHeader			tsoh	WITH(NOLOCK)
						ON	tsoh.comp_id	= tmp.comp_id		AND
							tsoh.bra_id		= tmp.bra_id		AND
							tsoh.soh_id		= tmp.soh_id
						INNER JOIN tbSaleOrderDetail			tsod	WITH(NOLOCK)
						ON	tsod.comp_id	= tsoh.comp_id		AND
							tsod.bra_id		= tsoh.bra_id		AND
							tsod.soh_id		= tsoh.soh_id
						--STL 22/05/2017
						INNER JOIN @tblComplexFilter_Items		tmpITEMS
						ON	tmpITEMS.item_id= tsod.item_id
						--
						--INNER JOIN tbDiscount					td
						--ON	td.disc_id		= tsoh.disc_id		AND
						--	td.comp_id		= tsoh.comp_id
						WHERE	tmp.comp_id		= @comp_id		--AND
								--tsod.item_id	IS NOT NULL

					--SELECT @lTOtalPresupuestosNoFacturados_DEL_DEP [TOtalPresupuestosNoFacturados_DEL_DEP], @lTotalPresupuestosNoFacturadosVigentes [TotalPresupuestosNoFacturadosVigentes]

					SET @lTotalPresupuestosNoFacturados = @lTOtalPresupuestosNoFacturados_DEL_DEP +  @lTotalPresupuestosNoFacturadosVigentes
					--SELECT @lTotalPresupuestosNoFacturados [Presupuestos NO Facturados]
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------


		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------
		-- PORCENTAJES Y TOTALES EN MONEDA DE LA SUCURSAL
		-- -----------------------------------------------------------------------------------------

			SELECT
				CONVERT(DECIMAL(25,2),@lCantPresupuestosFacturados	* 100 / dbo.fnNoZDiv(@lCantTotalPresupuestos))		[PresupuestosFactPorcentaje],
				CONVERT(DECIMAL(25,2),@lCantPresupuestosNoFacturados	* 100 / dbo.fnNoZDiv(@lCantTotalPresupuestos))	[PresupuestosNoFactPorcentaje],
				@lCantTotalPresupuestos																					[CantTotalPresupuestos],
				@lCantPresupuestosNoFacturados																			[PresupuestosNoFacturados],
				@lCantPresupuestosFacturados																			[PresupuestosFacturados],
				@lTotalPresupuestos																						[TotalPresupuestos],
				@lTotalPresupuestosFacturados																			[TotalPresupuestosFacturados],
				@lTotalPresupuestosNoFacturados																			[TotalPresupuestosNoFacturados],
				@bra_curr_symbol																						[BraCurrencySymbol],
				@lTotalPresupuestosPreciosOriginales																	[TotalPresupuestosPreciosOriginales]


		-- -----------------------------------------------------------------------------------------




		DECLARE @related_page_id INT
			SELECT
				@related_page_id = related_page_id
				FROM tbsysPages tp
				WHERE tp.page_id = @page_id
				SELECT
					(SELECT tswn.word_desc FROM [tbsysTextsNew] t 		WITH (NOLOCK) INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
							 WHERE t.ctrl_id = 177
							 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params1],

								@datefrom [DateParams1],


					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
							 WHERE t.ctrl_id = 384
							 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params2],

								@dateto		[DateParams2],

					(SELECT
						tswn.word_desc
						FROM [tbsysTextsNew] t
						INNER JOIN tbSysWordsNew tswn
						ON	 tswn.lang_id	= @lang_id			AND
							 tswn.wordsi_id = t.wordsi_id

						 WHERE	t.ctrl_id	= 172				AND
								t.[page_id] = @related_page_id	AND
								t.[type_id]	= 1					AND
								t.fun_id	= @fun_id)										[params4],

						CASE @sm_id WHEN -1 THEN
							(SELECT
								 tut.utexts_desc
								 FROM	tbsysUniqueTexts tut

								 WHERE	tut.lang_id		= @lang_id AND
										tut.utexts_id	= 1)
						ELSE
							(SELECT
								tba.sm_name
	 							FROM	tbSalesman					tba
								 WHERE tba.comp_id	=	@comp_id AND
									   tba.sm_id	=	@sm_id)
						END																	[params5],


						(SELECT
							tswn.word_desc
							FROM [tbsysTextsNew] t
							INNER JOIN tbSysWordsNew tswn
							ON	 tswn.lang_id	= @lang_id			AND
								 tswn.wordsi_id = t.wordsi_id

							 WHERE	t.ctrl_id	= 175				AND
									t.[page_id] = @related_page_id	AND
									t.[type_id]	= 1					AND
									t.fun_id	= @fun_id)									[params6],

						CASE @st_id WHEN -1 THEN
							(SELECT
								 tut.utexts_desc
								 FROM	tbsysUniqueTexts tut

								 WHERE	tut.lang_id		= @lang_id AND
										tut.utexts_id	= 1)
						ELSE
							(SELECT
								tst.st_desc
							 FROM tbSalesTerms 					tst
								 WHERE tst.comp_id	=	@comp_id AND
									   tst.st_id	=	@st_id)
						END																	[params7],


						(SELECT
							tswn.word_desc
							FROM [tbsysTextsNew] t
							INNER JOIN tbSysWordsNew tswn
							ON	 tswn.lang_id	= @lang_id			AND
								 tswn.wordsi_id = t.wordsi_id

							 WHERE	t.ctrl_id	= 170				AND
									t.[page_id] = @related_page_id	AND
									t.[type_id]	= 1					AND
									t.fun_id	= @fun_id)									[params8],

						CASE @dl_id WHEN -1 THEN
							(SELECT
								 tut.utexts_desc
								 FROM	tbsysUniqueTexts tut

								 WHERE	tut.lang_id		= @lang_id AND
										tut.utexts_id	= 1)
						ELSE
							(SELECT
								tba.dl_name
							 FROM tbDelivery 					tba
								 WHERE tba.comp_id	=	@comp_id AND
									   tba.dl_id	=	@dl_id)
						END																	[params9],


						(SELECT
							tswn.word_desc
							FROM [tbsysTextsNew] t
							INNER JOIN tbSysWordsNew tswn
							ON	 tswn.lang_id	= @lang_id			AND
								 tswn.wordsi_id = t.wordsi_id

							 WHERE	t.ctrl_id	= 172				AND
									t.[page_id] = @related_page_id	AND
									t.[type_id]	= 1					AND
									t.fun_id	= @fun_id)									[params10],

						CASE @stor_id WHEN -1 THEN
							(SELECT
								 tut.utexts_desc
								 FROM	tbsysUniqueTexts tut

								 WHERE	tut.lang_id		= @lang_id AND
										tut.utexts_id	= 1)
						ELSE
							(SELECT
								tba.stor_desc
							 FROM tbStorage 				tba
								 WHERE tba.comp_id	=	@comp_id AND
									   tba.stor_id	=	@stor_id)
						END																[params11],

						(SELECT
							tswn.word_desc
							FROM [tbsysTextsNew] t
							INNER JOIN tbSysWordsNew tswn
							ON	 tswn.lang_id	= @lang_id			AND
								 tswn.wordsi_id = t.wordsi_id

							 WHERE	t.ctrl_id	= 4790				AND
									t.[page_id] = @related_page_id	AND
									t.[type_id]	= 1					AND
									t.fun_id	= @fun_id)									[params12],

						CASE @option WHEN -1 THEN
							(SELECT
								 tut.utexts_desc
								 FROM	tbsysUniqueTexts tut

								 WHERE	tut.lang_id		= @lang_id AND
										tut.utexts_id	= 1)
						ELSE
							(SELECT
								tov.optval_desc
							 FROM tbsysOptionsValues				tov
							 WHERE	tov.lang_id			= @lang_id	AND
									tov.optval_class	= 703		AND
									tov.optval_id		= @option)
						END																[params13]
			/**************************************************************************************************************/

	DELETE FROM  @tblMaxupdSaleorderHistory
	DELETE FROM  @tblComplexFilter_Items
	DELETE FROM  @tblComplexFilter_Customer
	DELETE FROM  @tblPresupuestos
	DELETE FROM  @tblMaxupdSaleorderHistory
	DELETE FROM  @tblSaleorderHistory_TotalOriginal

END
GO






