--------------------------------------------------------------------------------------------


CREATE  PROCEDURE [dbo].[spElectronicInvoice_Query_getDataByFilters]
(
	@comp_id		AS INT,
	@lang_id		AS INT,
	@df_id			AS INT,
	@FromNumber		AS INT,
	@ToNumber		AS INT

)
AS

--------------------------------------------------------------------------------------------
-- Parametros de Test.
--------------------------------------------------------------------------------------------
/*
DECLARE @comp_id		AS INT,
		@lang_id		AS INT,
		@df_id			AS INT,
		@FromNumber		AS INT,
		@ToNumber		AS INT


SELECT 	@comp_id		= 1 ,
		@lang_id		= 2,
		@df_id			= 106,
		@FromNumber		= 1,
		@ToNumber		= 4


DROP TABLE #tmpElectronicInvoiceQuery
*/
--------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------

set nocount on

BEGIN

	DECLARE @int_count_DocNumber	AS INT

	SET		@int_count_DocNumber = @FromNumber


	CREATE TABLE #tmpElectronicInvoiceQuery
		(

			cust_id				INT,
			cust_name			NVARCHAR(200),
			cust_taxNumber		NVARCHAR(50),
			ct_date				DATETIME,
			ct_transaction		NVARCHAR(200),
			ct_subtotal			DECIMAL(19,5),
			ct_total			DECIMAL(19,5),
			ct_taxes			DECIMAL(19,5),
			ct_docnumber		INT
		)




	WHILE @int_count_DocNumber <= @ToNumber

			BEGIN

				-- Verificamos si existe el documento.
				IF EXISTS	(	 SELECT tct.ct_docNumber,
										tct.df_id

									 FROM tbCommercialTransactions				tct

									 INNER JOIN tbDocumentsFile					tdf
									 ON tdf.comp_id		= tct.comp_id AND
										tdf.df_id		= tct.df_id

									 WHERE	tct.comp_id			= @comp_id		AND
											tct.df_id			= @df_id		AND
											tct.ct_docNumber	= @int_count_DocNumber

								)

									--Si existe grabamos con los datos correspondiente a ese comprobante.
									INSERT INTO #tmpElectronicInvoiceQuery

									(
										cust_id,
										cust_name,
										cust_taxNumber,
										ct_date,
										ct_transaction,
										ct_subtotal,
										ct_total,
										ct_taxes,
										ct_docnumber
									)


								SELECT	tc.cust_id,
										tc.cust_name,
										tc.cust_taxNumber,
										tct.ct_date,
										dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction),
										tct.ct_subtotal,
										tct.ct_total,
										tct.ct_taxes,
										tct.ct_docNumber

									FROM	tbCommercialTransactions				tct

									INNER JOIN tbCustomer							tc
									ON		tc.comp_id		= tct.comp_id	AND
											tc.cust_id		= tct.cust_id

									INNER JOIN 	tbDocumentsFile						df
									on		df.comp_id		= tct.comp_id	AND
											df.bra_id		= tct.bra_id	AND
											df.df_id		= tct.df_id

									LEFT JOIN tbsysDocuments						sd
									on		sd.sd_id		= tct.sd_id



									WHERE	df.df_id = @df_id
									AND		tct.ct_docNumber	= @int_count_DocNumber

					ELSE
						-- Si no existe grabamos en la temporal con datos vacios.
								INSERT INTO #tmpElectronicInvoiceQuery
									(
										cust_id,
										cust_name,
										cust_taxNumber,
										ct_date,
										ct_transaction,
										ct_subtotal,
										ct_total,
										ct_taxes,
										ct_docnumber
									)
								VALUES
									(
										'',
										'*',
										'*',
										'',
										'*',
										'0',
										'0',
										'0',
										@int_count_DocNumber

									)


				SET @int_count_DocNumber = @int_count_DocNumber + 1


			END

			SELECT  * ,
					'' [FECUIT],
					'' [FETOTAL],
					'' [FESUBTOTAL],
					'' [FETAX],
					'' [FEDATE],
					'' [FECAE],
					'' [FECAEDATE],
					'' [FEDOCNUMBER],
					'' [FERESULTADO]
		     FROM #tmpElectronicInvoiceQuery



END















GO






-- MOS: Retorna un Ticket Fiscal Activo para poder reusarlo sin tener que sacar uno nuevo.-
CREATE  PROCEDURE [dbo].[spElectronicInvoice_TicketTransactions_getDataByFilters]
(
	@comp_id		As Int,
	@lang_id		AS INT,
	@df_id			As Int,
	@ActualDateTime	as DATETIME,
	@servicename    AS NVARCHAR(200)
)
AS

BEGIN

	set nocount on


	-- ------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------
	/*
	DECLARE 	@comp_id		As Int,
				@lang_id		AS INT,
				@df_id			As Int,
				@ActualDateTime	as DATETIME

	SET			@comp_id			= 1
	SET 		@lang_id			= 2
	SET 		@df_id				=72
	SET 		@ActualDateTime		=GETDATE()
	*/
	-- ------------------------------------------------------------------------








	-- ------------------------------------------------------------------------
	-- Por seguridad se añade 15 minutos a la hora actual, para verificar
	-- que no se exeda por una diferencia horaria del ticket de acceso actual.-
	-- ------------------------------------------------------------------------
	SET @ActualDateTime = GETDATE()
	SET @ActualDateTime = DATEADD(minute,20,@ActualDateTime)
	-- ------------------------------------------------------------------------

	DECLARE @intP12_ID  AS INT
	DECLARE @fedt_id	AS INT = -1
	SELECT  @intP12_ID		= tdf.p12_id,
			@fedt_id		= tdf.fedt_id
		FROM tbDocumentsFile tdf			WITH (NOLOCK)
		WHERE	tdf.comp_id = @comp_id
			AND tdf.df_id	= @df_id

	SELECT TOP 1 teitt.comp_id,
				 teitt.df_id,
				 teitt.ta_id,
				 teitt.ta_text,
				 teitt.ta_fromDateTime,
				 teitt.ta_toDateTime,
				 teitt.user_id,
				 teitt.ta_ipFrom,
				 teitt.p12_id,
				 teitt.ta_sign,
				 teitt.ta_token,
				 teitt.ta_service,
				 teitt.ta_uniqueId

	FROM tbElectronicInvoice_TicketTransactions teitt	WITH (NOLOCK)
	INNER JOIN tbDocumentsFile tdf						WITH (NOLOCK)
		ON		tdf.comp_id = teitt.comp_id
			AND tdf.df_id	= teitt.df_id
	LEFT JOIN tbsysFEWS_Url ws							WITH (NOLOCK)
		ON ws.eis_id = tdf.eis_id

	WHERE 	teitt.comp_id		=	@comp_id
		--AND teitt.df_id			=	@df_id			-- MOS 11-2013
		AND tdf.p12_id			=   @intP12_ID
		and	(@ActualDateTime between teitt.ta_fromDateTime AND teitt.ta_toDateTime)
		AND	(
				(@fedt_id IN (19,20,21) AND tdf.fedt_id IN (19,20,21))
				OR
				(@fedt_id NOT IN (19,20,21) AND tdf.fedt_id NOT IN (19,20,21) )
				OR
				(tdf.df_id = @df_id AND tdf.eis_id_ta = 101)	-- Documento para Constatacion de comprobantes  MOS 08-2020
			)
		AND
		CASE
			WHEN @servicename <> '' AND teitt.ta_service	= @servicename		THEN 1
			WHEN @servicename =  '' AND	ws.eis_serviceName	= teitt.ta_service	THEN 1
			ELSE																	 0
		END	= 1




END


GO







CREATE  PROCEDURE [dbo].[spElectronicInvoice_TicketTransactions_getDataById]
(
	@comp_id		As Int,
	@df_id			As Int,
	@ta_id			as int

)
as
set nocount on


-------------------------------------------------------
-------------------------------------------------------
/*
DECLARE 	@comp_id		As Int,
			@df_id			As Int,
			@ta_id			as int


select		@comp_id		=1,
			@df_id			=1,
			@ta_id			=1
*/
------------------------------------------------------
------------------------------------------------------


SELECT		teitt.comp_id,
			teitt.df_id,
			teitt.ta_id,
			teitt.ta_text,
			teitt.ta_fromDateTime,
			teitt.ta_toDateTime,
			teitt.user_id,
			teitt.ta_ipFrom,
			teitt.p12_id


FROM tbElectronicInvoice_TicketTransactions teitt	WITH (NOLOCK)


WHERE 	teitt.comp_id		=	@comp_id
AND 	teitt.df_id			=	@df_id
and		teitt.ta_id			=   @ta_id






GO








CREATE PROCEDURE [dbo].[spElectronicInvoice_TicketTransactions_insertData]
(

	@comp_id						INT,
	@df_id							INT,
	@ta_text					    ntext,
	@ta_fromDateTime				DATETIME,
	@ta_toDateTime					DATETIME,
	@user_id						INT,
	@ta_ipFrom						NVARCHAR(20),
	@sign						AS  NVARCHAR(4000),
	@token						AS  NVARCHAR(4000),
	@service					AS  NVARCHAR(4000),
	@uniqueId					AS  BIGINT,
	@return_value					int output

)
AS

BEGIN

	set nocount on

	DECLARE @p12_id AS INT
	SELECT @p12_id = tdf.p12_id
		FROM tbDocumentsFile tdf	WITH (NOLOCK)
		WHERE	tdf.comp_id = @comp_id
			AND tdf.df_id	= @df_id


	INSERT INTO tbElectronicInvoice_TicketTransactions
	(
		comp_id,
		df_id,
		ta_text,
		ta_fromDateTime,
		ta_toDateTime,
		user_id,
		ta_ipFrom,
		p12_id,
		ta_sign,
		ta_token,
		ta_service,
		ta_uniqueId
	)
	VALUES
	(
		@comp_id,
		@df_id,
		@ta_text,
		@ta_fromDateTime,
		@ta_toDateTime,
		@user_id,
		@ta_ipFrom,
		@p12_id,
		@sign,
		@token,
		@service,
		@uniqueId
	)

	set	@return_value = @@IDENTITY

END
GO




CREATE PROCEDURE [dbo].[spElectronicInvoice_Transactions_insertData]
(

	@comp_id						INT,
	@bra_id							INT,
	@ct_transaction					INT,
	@df_id							INT,
	@eim_sentxml					ntext,
	@eim_receivedxml				ntext,
	@eim_cd							DATETIME,
	@return_value					int output

)
AS

BEGIN



	set nocount on



	INSERT INTO tbElectronicInvoice_Transactions	WITH (ROWLOCK)
	(
		comp_id,
		bra_id,
		ct_transaction,
		df_id,
		eim_sentxml,
		eim_receivedxml,
		eim_cd

	)

	VALUES
	(

		@comp_id,
		@bra_id,
		@ct_transaction,
		@df_id,
		@eim_sentxml,
		@eim_receivedxml,
		GETDATE()

	)


	set	@return_value = @@IDENTITY



END
GO






CREATE PROCEDURE [dbo].[spElectronicInvoiceCheck_getData]
(

	@comp_id								INT,
	@lang_id								INT

)


AS
SET NOCOUNT ON


BEGIN



	-----------------------------------------
	--Test
	-----------------------------------------
	/*

	DECLARE @comp_id				INT,
			@lang_id				INT

	SELECT 	@comp_id				= 1,
			@lang_id				= 2

	*/
	-----------------------------------------
	-----------------------------------------


		SELECT  '' [ ],
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)	[ct_transaction],
				df.df_desc																			[desc],
				tc.cust_name																		[cust_name],
				tct.ct_date																			[ct_date],
				tct.ct_total																		[ct_total],
				tct.ct_transaction																	[ID]



		FROM	tbCommercialTransactions				tct		WITH (NOLOCK)

		INNER JOIN tbCustomer							tc	WITH (NOLOCK)
		ON		tc.comp_id		= tct.comp_id	AND
				tc.cust_id		= tct.cust_id

		INNER JOIN 	tbDocumentsFile						df	WITH (NOLOCK)
		on		df.comp_id		= tct.comp_id	AND
				df.bra_id		= tct.bra_id	AND
				df.df_id		= tct.df_id

		LEFT JOIN tbsysDocuments						sd	WITH (NOLOCK)
		on		sd.sd_id		= tct.sd_id



		WHERE	sd.sd_id IN (1,3,4)
		AND		df.df_isElectronicInvoice = 'True'
		AND     (tct.ct_CAI = '' or tct.ct_CAI IS NULL )


		ORDER BY tct.ct_transaction















END

GO



CREATE PROCEDURE [dbo].[spEmittedChecks_4PrintChecks_getDataById]
(
	@comp_id			INT,
	@lang_id			INT,
	@ec_id				INT

)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@ec_id		INT

			Select
				@comp_id	= 1,
				@lang_id	= 2,
				@ec_id		= 173
		*/
		-- ------------------------------------------------------------------


		--SET DATEFORMAT 'ymd'



		------------------------------------------------------------------------------------------------------------
		-- Recuperamos el ct para saber el proveedor y la sucursal y con la sucursal saber si es otros pagos .
		------------------------------------------------------------------------------------------------------------

		DECLARE @lct_transaction	INT
		DECLARE @lbra_id			INT
		DECLARE @Supp_id			INT
		DECLARE @PaymentSupp_I		INT

		SET @lct_transaction = (
								SELECT ec.ct_transaction
									FROM	dbo.tbEmmitedChecks			ec			WITH (NOLOCK)
									WHERE	ec.comp_id		= @comp_id		AND
											ec.ec_id		= @ec_id
								)

		SET @Supp_id = (
						SELECT tct.supp_id
               				FROM tbCommercialTransactions				tct			WITH (NOLOCK)
							WHERE tct.comp_id			= @comp_id			AND
								  tct.ct_transaction	= @lct_transaction
						)

		SET @lbra_id = (
						SELECT tct.bra_id
               				FROM tbCommercialTransactions				tct			WITH (NOLOCK)
							WHERE tct.comp_id			= @comp_id			AND
								  tct.ct_transaction	= @lct_transaction
						)


		SET @PaymentSupp_I = (
								SELECT tb.bra_PaymentSupp_Id
									FROM tbBranch						tb			WITH (NOLOCK)
									WHERE tb.comp_id	= @comp_id AND
										  tb.bra_id		= @lbra_id
							  )
		--------------------------------------------------------------------


		--SELECT @lct_transaction,@lbra_id,@PaymentSupp_I [proveedor de otros pagos de la sucursal],@Supp_id [Proveedor del cttransaction]

			SELECT		ec.ec_Number												[ec_Number],
						CONVERT(char(10),ec.ec_EmissionDate,103)					[ec_EmissionDate],
						day(ec.ec_EmissionDate)										[ec_EmissionDateDay],
						month(ec.ec_EmissionDate)									[ec_EmissionDateMonth],
						tovED.optval_desc											[ec_EmissionDateMonthInLetters],
						year(ec.ec_EmissionDate)									[ec_EmissionDateYear],
						CONVERT(char(10),ec.ec_PayDate,103)							[ec_PayDate],
						day(ec.ec_PayDate)											[ec_PayDateDay],
						month(ec.ec_PayDate)										[ec_PayDateMonth],
						tovPD.optval_desc											[ec_PayDateMonthInLetters],
						year(ec.ec_PayDate)											[ec_PayDateYear],
						--CASE @PaymentSupp_I WHEN @Supp_id THEN
						--	CASE ISNULL(ec.ec_payto,'') WHEN '' THEN
						--		ts.supp_name
						--	ELSE
						--		ec.ec_payto
						--	END
						--ELSE
						--		ts.supp_name
						--END															[ec_payto],
						CASE
							WHEN isnull(ec.ec_payto,'') <> '' THEN
								ec.ec_payto
							WHEN  @PaymentSupp_I = @Supp_id   THEN
								''
							ELSE
								ts.supp_name
						END															[ec_payto],

						convert(DECIMAL(19,2),ec.ec_Total)							[ec_Total],
						convert(DECIMAL(19,2),ec.ec_Total)							[ec_TotalInLetters],
						convert(DECIMAL(19,2),ec.ec_Total)							[ec_TotalInLettersRow1],
						convert(DECIMAL(19,2),ec.ec_Total)							[ec_TotalInLettersRow2],
						convert(DECIMAL(19,2),ec.ec_Total)							[ec_TotalInLettersRow3],
						CASE
							WHEN ec.ec_not_to_order = 'False' THEN ''
							ELSE 'NO A LA ORDEN	'
						END															[print_NOT2ORDER]



			from	dbo.tbEmmitedChecks										ec

			LEFT JOIN tbsysOptionsValues									tovED		WITH (NOLOCK)
			ON tovED.lang_id			= @lang_id						AND
			   tovED.optval_id			= month(ec.ec_EmissionDate)		AND
			   tovED.optval_class		= 37

			LEFT JOIN tbsysOptionsValues									tovPD		WITH (NOLOCK)
			ON tovPD.lang_id			= @lang_id						AND
			   tovPD.optval_id			= month(ec.ec_PayDate)			AND
			   tovPD.optval_class		= 37

			 INNER JOIN tbSupplier											ts			WITH (NOLOCK)
			 ON ts.comp_id				= ec.comp_id AND
				ts.supp_id				= @Supp_id

			where	ec.comp_id			= @comp_id		AND
					ec.ec_id			= @ec_id


	END
















GO



--para orden de pago, al ingresar cheques emitidos controlamos que no existan.


CREATE PROCEDURE [dbo].[spEmittedChecks_CheckNumber_getData]
(
	@comp_id		INT,
	@lang_id		INT,
	@ba_id			INT,
	@ec_Number		NVARCHAR(50),
	@ecct_id		INT
)

as set nocount on

BEGIN


	-- Si es una chequera que auto imprime cheques no debe verificar esa numeracion.
	IF EXISTS	(
					SELECT 1
						FROM tbEmmitedChecks_CheckBook				WITH (NOLOCK)
						WHERE	comp_id = @comp_id	AND
								ecct_id = @ecct_id	AND
								ecct_isAvailable4Print = 1

				)
		BEGIN
			SELECT 1	[IsOk]
			return
		END




	DECLARE @lisOk AS INT

	SET @lisOk = 1



	IF EXISTS (	SELECT
					tec.ec_id

	           		FROM tbEmmitedChecks tec	WITH (NOLOCK)

		          	WHERE	tec.comp_id			= @comp_id		AND
							tec.ba_id			= @ba_id		AND
							tec.ec_Number		= @ec_Number	AND
							tec.ecct_id			= @ecct_id
				)

			BEGIN
				--No se puede,ya existe
				SET @lisOk = 0
			END




	-- 1 : Ok para dar de alta
	-- 0 : No se puede,ya existe

	SELECT @lisOk [IsOk]



END
GO






CREATE PROCEDURE [dbo].[spEmittedChecks_get4Print]
(
	@comp_id			INT,
	@bra_id				INT,
	@ct_transaction		INT
)

AS

BEGIN

SET DATEFORMAT 'ymd'

set nocount on

-----------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------
/*
	declare 	@comp_id				INT,
				@bra_id					INT,
				@ct_transaction			INT

	select		@comp_id				= 1,
				@bra_id					= 1,
				@ct_transaction			= 10786

*/
-----------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------

	SELECT  tec.comp_id										[comp_id],
			tec.bra_id										[bra_id],
			isnull(tec.ec_isPrinted,'FALSE')				[ec_isPrinted],
			tec.ecct_id										[ecct_id],
			isnull(teccb.ecct_isAvailable4Print,'FALSE')	[ecct_isAvailable4Print],
			tec.ec_id										[ec_id]


	from	dbo.tbEmmitedChecks				tec

	LEFT JOIN tbEmmitedChecks_CheckBook		teccb
	ON	teccb.comp_id = tec.comp_id		AND
		teccb.ecct_id = tec.ecct_id


	Where	tec.comp_id				= @comp_id
	And		tec.ct_transaction		= @ct_transaction





END
GO






