CREATE PROCEDURE [dbo].[spEmittedChecks_getDataById]
(
		@comp_id			Int,
		@bra_id				Int,
		@ba_id				Int,
		@DateDepositFrom	datetime,
		@DateDepositTo		datetime,
		@DateProcesing		datetime
)
as
set nocount on
--Declare	@comp_id			Int,
--			@bra_id				Int,
--			@ba_id				Int,
--			@DateDepositFrom	Int,
--			@DateDepositTo		Int,
--			@DateProcesing		Int
--
--Select	@ba_id				=
--			@DateDepositFrom	=
--			@DateDepositTo		=

select	ec.ec_isPaid

from	dbo.tbEmmitedChecks		ec

where	ec.ba_id	=	@ba_id
And		ec.ec_PayDate	between @DateDepositFrom And @DateDepositTo

--Actualizar el campo ec_PaymentFinalDate con la fecha de proceso.
Update tbEmmitedChecks
SET		ec_PaymentFinalDate = @DateProcesing
Where	comp_id		= @comp_id
And		bra_id		= @bra_id
And		ba_id		= @ba_id


















GO


-- ----------------------------------------------------------------------------------------------------------------------------------------------------
-- NOTAS Y VERSIONADO
-- ----------------------------------------------------------------------------------------------------------------------------------------------------
-- STL - 09-03-2018 - DurkWorks - Se agregó filtro por GRUPO DE SUCURSALES REFERENCIA : #3773  #Parte = 3191
-- ----------------------------------------------------------------------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spEmittedChecks_getEmitted]
(
	@comp_id			INT,
	@bra_id				INT,
	@ba_id				INT,
	@DateDepositFrom	DATETIME,
	@DateDepositTo		DATETIME,
	@dummy				Bit,
	@optionNumber		INT,
	@numberFrom			VARCHAR(40),
	@optionTotal		INT,
	@totalFrom			DECIMAL(19,5),
	@totalTo			DECIMAL(19,5),
	@brag_id			INT
)
AS


BEGIN

	SET DATEFORMAT 'ymd'
	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------------
	-- CARGO EN UNA VARIABLE DE TABLA LAS SUCURSALES DEL BRAG_ID O EN CASO DE SER -1
	-- CARGO SOLO LA QUE VIENE EN EL BRA_ID #3773
	-- -----------------------------------------------------------------------------------
		DECLARE @tblBranchs TABLE (comp_id	INT, bra_id INT PRIMARY KEY)
		INSERT INTO @tblBranchs
			SELECT
				tbgd.comp_id,
				tbgd.bra_id
				FROM tbBranchGroupDetail			tbgd	WITH(NOLOCK)
				INNER JOIN tbBranch					tb		WITH(NOLOCK)
				ON	tb.comp_id		= tbgd.comp_id	AND
					tb.bra_id		= tbgd.bra_id
			WHERE	tbgd.comp_id	= @comp_id		AND
					tbgd.brag_id	= @brag_id		AND
					tb.bra_disabled = 'False'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblBranchs
				(
					comp_id,
					bra_id
				)
				SELECT
					@comp_id,
					@bra_id

			END
	-- -----------------------------------------------------------------------------------

	-- -----------------------------------------------------------------------------------
	-- TESTING
	-- -----------------------------------------------------------------------------------
	/*
		declare @comp_id			int,
				@bra_id				Int,
				--@ec_id				Int,
				@ba_id				int,
				@DateDepositFrom	datetime,
				@DateDepositTo		datetime,
				@dummy				BIT,
				@optionNumber		int,
				@numberFrom			varchar(40),
				@optionTotal		int,
				@totalFrom			decimal(19,5),
				@totalTo			decimal(19,5),
				@ec_ispaid			BIT,
				@brag_id			INT

		select	@comp_id			= 1,
				@bra_id				= 1,
				--@ec_id				= 6,
				@ba_id				= 16,
				@DateDepositFrom	= '01/01/2008',
				@DateDepositTo		= '18/12/2009',
				@dummy				= 'false',
				@optionNumber		=	-1,
				@numberFrom			=	'',
				@optionTotal		=	-1,
				@totalFrom			=	0.0,
				@totalTo			=	0.0,
				@ec_ispaid			='false',
				@brag_id			= -1
	*/
	-- -----------------------------------------------------------------------------------



	select	tec.ec_id																[id],
			convert(varchar, tec.ec_PayDate, 103) +
			' #' + dbo.PadString(tec.ec_Number,'0',12) +
			' - ' + ltrim(rtrim(tc.[curr_symbol])) +
			' - ' + convert(varchar,Convert(Decimal(18,2), round(tec.ec_Total,2)))	[desc]

	from	dbo.tbEmmitedChecks				tec

			Inner Join tbsysCurrency		tc
			On tc.curr_id	= tec.curr_id

			INNER JOIN @tblBranchs			tbb		--#3773
			ON	tbb.comp_id = tec.comp_id	AND
				tbb.bra_id	= tec.bra_id

	Where	tec.comp_id		= @comp_id
	--And		tec.bra_id		= @bra_id	#3773
	And		tec.ba_id		= @ba_id
	And		tec.ec_PayDate	between @DateDepositFrom And @DateDepositTo
	--And		@ec_id			= -1 or tec.[ec_id]		=	@ec_id
	And		tec.ec_isPaid	= @dummy
	and		(
			(@optionNumber = -1)													or
			(@optionNumber = 0 and tec.ec_Number like @numberFrom + '%')			or
			(@optionNumber = 1 and tec.ec_Number like '%' +  @numberFrom + '%')		or
			(@optionNumber = 2 and tec.ec_Number = @numberFrom)						or
			(@optionNumber = 3 and tec.ec_Number <> @numberFrom)					or
			(@optionNumber = 4 and tec.ec_Number not like '%' +  @numberFrom + '%')
			)
	and		(
			(@optionTotal = -1)														or
			(@optionTotal = 0 and tec.ec_Total = @totalFrom)						or
			(@optionTotal = 1 and tec.ec_Total > @totalFrom)						or
			(@optionTotal = 2 and tec.ec_Total < @totalFrom)						or
			(@optionTotal = 3 and tec.ec_Total between @totalFrom and @totalTo)
			)

	--and		tec.ec_isPaid   = @ec_ispaid

END
GO









CREATE PROCEDURE [dbo].[spEmittedChecks_getList]
(
	@comp_id			int,
	@date_from			datetime,
	@date_to			datetime,
	@ba_id				integer
)
as

set nocount on
/*
declare 	@comp_id			int,
			@date_from			datetime,
			@date_to			datetime,
			@ba_id				integer

select		@comp_id			= 1,
			@date_from			= '01/01/2008',
			@date_to			= '26/08/2008',
			@ba_id				= 1
*/

select	ec_id			[id],
		ec_Number		[desc]


from 	tbEmmitedChecks

where	comp_id		=	@comp_id
and ec_isPaid = 'false'
and ec_id not in (select	distinct
							b.ec_id
					from	[tbEmmitedChecksMovements] a

					inner join [tbEmmitedChecks]		b
					on	b.ec_id		= a.ec_id

					where	b.ba_id				= -1 or	b.ba_id	= @ba_id
					and		a.comp_id			= @comp_id
					and		b.ec_EmissionDate	= @date_from
					and		b.ec_EmissionDate	= @date_to)




GO






