-- ----------------------------------------------------------------------------------------------------------------------------------------------------
-- NOTAS Y VERSIONADO
-- ----------------------------------------------------------------------------------------------------------------------------------------------------
-- OJO !!!! SI SE TOCA ALGO EN ESTE SP DE MIERDAAAAAAAAAAAA TAMBIEN
--	HAY QUE TOCAR EXACTAMENTE LO MISMO EN EL OTRO SP DE MIERDA LLAMADO [spEmittedChecks_getReport4Grid](PARA REPORTE A GRILLA ) OK ? GRACIAS !
-- STL - 09-03-2018 - DurkWorks - Se agregó filtro por GRUPO DE SUCURSALES REFERENCIA : #3773 #Parte = 3191
-- ----------------------------------------------------------------------------------------------------------------------------------------------------


CREATE Procedure [dbo].[spEmittedChecks_getReport]
(
		@comp_id				int,
		@lang_id				int,
		@page_id				int,

		@datefrompaydate		datetime,
		@datetopaydate			datetime,
		@ordervalues			int,
		@datefromemdate			datetime,
		@datetoemdate			datetime,
		@curr_id				int,
		@selection				int,
		@custsupp				int,
		@bankacc				int,
		@debval					int,
		@datefromcon			datetime,
		@datetocon				datetime,
		@ecct_id				INT,
		@bra_id					INT,
		@user_id				INT,
		@intBranch4Lang			INT,
		@brag_id				INT
)

AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- ---------------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------------
	/*
		Declare
				@comp_id				int,
				@lang_id				int,
				@page_id				int,

				@datefrompaydate		datetime,
				@datetopaydate			datetime,
				@ordervalues			int,
				@datefromemdate			datetime,
				@datetoemdate			datetime,
				@curr_id				int,
				@selection				bit,
				@custsupp				int,
				@bankacc				int,
				@debval					int,
				@datefromcon			datetime,
				@datetocon				datetime,
				@bra_id					int,
				@user_id				INT,
				@intBranch4Lang			INT,
				@ecct_id				INT,
				@brag_id				INT



		Select
				@comp_id				= 1,
				@lang_id				= 2,
				@page_id				= 10016,

				@datefrompaydate		= '1900-01-01',
				@datetopaydate			= '9999-12-31',
				@ordervalues			= -1,
				@datefromemdate			= '1900-01-01',
				@datetoemdate			= '9999-12-31',
				@curr_id				= 1,
				@selection				= -1,
				@custsupp				= -1,
				@bankacc				= -1,
				@debval					= 0,
				@datefromcon			= '1900-01-01',
				@datetocon				= '9999-12-31',
				@bra_id					= 1,
				@user_id				= 1,
				@ecct_id				= 152,
				@brag_id				= -1
	*/
	-- ---------------------------------------------------------------------------

	set nocount on
	set dateformat 'ymd'

	set	@datefrompaydate = dbo.fnGetEnd_or_BeginOfDate(@datefrompaydate,'False')
	set	@datetopaydate = dbo.fnGetEnd_or_BeginOfDate(@datetopaydate,'True')

	set	@datefromemdate = dbo.fnGetEnd_or_BeginOfDate(@datefromemdate,'False')
	set	@datetoemdate = dbo.fnGetEnd_or_BeginOfDate(@datetoemdate,'True')

	set	@datefromcon = dbo.fnGetEnd_or_BeginOfDate(@datefromcon,'False')
	set	@datetocon = dbo.fnGetEnd_or_BeginOfDate(@datetocon,'True')


	-- -----------------------------------------------------------------------------------
	-- CARGO EN UNA VARIABLE DE TABLA LAS SUCURSALES DEL BRAG_ID O EN CASO DE SER -1
	-- CARGO SOLO LA QUE VIENE EN EL BRA_ID #3773
	-- -----------------------------------------------------------------------------------
		DECLARE @tblBranchs TABLE (comp_id	INT, bra_id INT PRIMARY KEY)
		INSERT INTO @tblBranchs
			SELECT
				tbgd.comp_id,
				tbgd.bra_id
				FROM tbBranchGroupDetail			tbgd	WITH(NOLOCK)
				INNER JOIN tbBranch					tb		WITH(NOLOCK)
				ON	tb.comp_id		= tbgd.comp_id	AND
					tb.bra_id		= tbgd.bra_id
			WHERE	tbgd.comp_id	= @comp_id		AND
					tbgd.brag_id	= @brag_id		AND
					tb.bra_disabled = 'False'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblBranchs
				(
					comp_id,
					bra_id
				)
				SELECT
					@comp_id,
					@bra_id

			END
	-- -----------------------------------------------------------------------------------





	DECLARE @fun_id INT
	SET @fun_id = 1


	Select
			case convert(bit,@selection) when 'True' then ct.supp_id
				else ct.cust_id
			end [ID],
			case convert(bit,@selection) when 'True' then s.supp_name
				else c.cust_name
			end [Name],
			ba.ba_desc,
			ec.ec_paydate,
			br.bra_desc,
			ec.ec_number,
			ec.ec_note,
			ct.ct_date,
			ec.ec_total,
			cu.curr_desc,
			ec.ec_exchangeToBranchCurrency,
			ec.ec_id

	From	dbo.tbEmmitedChecks								ec			WITH ( NOLOCK )

			INNER JOIN dbo.tbBankingAccounts				ba			WITH ( NOLOCK )
			ON  ec.comp_id			= ba.comp_id	AND
				ec.ba_id			= ba.ba_id

			LEFT JOIN tbEmmitedChecks_CheckBook				teccb		WITH ( NOLOCK )
			ON  teccb.comp_id		= ec.comp_id	AND
				teccb.ecct_id		= ec.ecct_id

			INNER JOIN dbo.tbCommercialTransactions			ct			WITH ( NOLOCK )
			ON  ct.comp_id			= ec.comp_id	AND
				ct.ct_transaction	= ec.ct_transaction


			LEFT JOIN dbo.tbBankingTransactions				bt			WITH ( NOLOCK )
			ON  bt.comp_id			= ec.comp_id	AND
				ec.bra_id			= bt.bra_id		AND
				ec.ec_id			= bt.ec_id		AND
				bt.bt_isCancelled	= 'False'

			INNER JOIN dbo.tbsysCurrency					cu			WITH ( NOLOCK )
			ON	ec.curr_id			= cu.curr_id

			INNER JOIN dbo.tbBranch							br			WITH ( NOLOCK )
			ON	br.bra_id			= ec.bra_id

			LEFT JOIN dbo.tbCustomer						c			WITH ( NOLOCK )
			ON	c.comp_id			= ct.comp_id	AND
				c.cust_id			= ct.cust_id	AND
				@selection			= convert(bit,@selection)

			LEFT JOIN dbo.tbSupplier						s			WITH ( NOLOCK )
			ON	s.comp_id			= ct.comp_id	AND
				s.supp_id			= ct.supp_id	AND
				@selection			= convert(bit,@selection)

			INNER JOIN @tblBranchs							tbb			--#3773
			ON	tbb.comp_id			= ec.comp_id			AND
				tbb.bra_id			= ec.bra_id

			INNER JOIN tbUsers4BranchFilter					vubf		WITH ( NOLOCK )
			ON  vubf.comp_id		= CT.comp_id	AND
				vubf.bra_id			= CT.bra_id		AND
				vubf.[user_id]		= @user_id

	Where	 ec.comp_id				= @comp_id
	--AND		 ec.bra_id				= @bra_id	#3773
	AND		 ec.ec_paydate			between  @datefrompaydate and  @datetopaydate
	AND		 ec.ec_EmissionDate		between  @datefromemdate  and  @datetoemdate
	AND		 ec.curr_id				= @curr_id
	AND		 (@bankacc				= -1 or		ba.ba_id			  = @bankacc)
	AND		 (@ordervalues			= -1 or		ec.ec_not_to_order    = convert(bit,@ordervalues))
	AND		 (	@debval				= -1 or		(@debval = 0 AND ec.ec_isPaid = 'TRUE') OR (@debval = 1 AND ec.ec_isPaid = 'False') )
	AND		 (
				(convert(bit,@selection) = 'True'   and (@custsupp = -1 or ct.supp_id = @custsupp)and (ct.supp_id is not null)) or
				(convert(bit,@selection) = 'False'  and (@custsupp = -1 or ct.cust_id = @custsupp)and (ct.cust_id is not null))
			 )
	AND ec.ec_isCancelled	= 'False'
	AND (@bankacc			= -1 OR	ba.ba_id = @bankacc)
	AND (@ecct_id			= -1 OR teccb.ecct_id = @ecct_id)





	ORDER BY ec.ec_paydate,id

	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/*************************************************************************************************************/
	select
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 416
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params1],
		@datefrompaydate [DateParams1],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 417
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params3],
		@datetopaydate [DateParams2],
			--convert(varchar,day(@datetopaydate)) + '/' + convert(varchar,month(@datetopaydate)) + '/' + convert(varchar,year(@datetopaydate))		[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 423
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params5],

				CASE @ordervalues WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id  =  @lang_id
						AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
						FROM	dbo.tbsysOptionsValues tov
						WHERE	tov.optval_class	= 1
						AND		tov.lang_id			= @lang_id
						AND		tov.optval_id		=   @ordervalues )

				END																																	[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 418
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params7],

		@datefromemdate [DateParams3],
			--convert(varchar,day(@datefromemdate)) + '/' + convert(varchar,month(@datefromemdate)) + '/' + convert(varchar,year(@datefromemdate))	[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 419
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params9],

			@datetoemdate [DateParams4],
			--convert(varchar,day(@datetoemdate)) + '/' + convert(varchar,month(@datetoemdate)) + '/' + convert(varchar,year(@datetoemdate))			[params10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 106
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params11],

			(SELECT		tc.curr_desc
						FROM	dbo.tbsysCurrency tc
						WHERE	tc.curr_id	= @curr_id)																								[params12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 529
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params13],

			CASE @selection WHEN 0 THEN
				CASE @custsupp WHEN -1 THEN
					(SELECT		tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tc.cust_name
					 FROM	dbo.tbCustomer tc
					 WHERE	tc.cust_id  = @custsupp)
				END
			ELSE
				CASE @custsupp WHEN -1 THEN
					(SELECT		tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT ts.supp_name
					 FROM	dbo.tbSupplier ts
					 WHERE	ts.supp_id  = @custsupp)
				END
			END																																		[params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 406
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params15],

				CASE @bankacc WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tba.ba_desc
			 		 FROM	dbo.tbBankingAccounts tba
					 WHERE tba.ba_id	=	@bankacc)
				END																																	[params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 422
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params17],

				CASE @debval WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tov.optval_desc
			 		 FROM	dbo.tbsysOptionsValues tov
					 WHERE tov.lang_id = @lang_id
					 AND	tov.optval_class = 16
					 AND	tov.optval_id = @debval)
				END																																	[params18],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 420
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params19],

			@datefromcon [DateParams5],
			--convert(varchar,day(@datefromcon)) + '/' + convert(varchar,month(@datefromcon)) + '/' + convert(varchar,year(@datefromcon))				[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 421
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params21],

		@datetocon [DateParams6],
			--convert(varchar,day(@datetocon)) + '/' + convert(varchar,month(@datetocon)) + '/' + convert(varchar,year(@datetocon))					[params22]


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 2914
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params22],


				CASE @ecct_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT teccb.ecct_desc
					 FROM dbo.tbEmmitedChecks_CheckBook teccb
					 WHERE teccb.comp_id = @comp_id and	teccb.ecct_id = @ecct_id)
				END																									[params23],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 639
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params24],


				CASE @brag_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT
						tbg.brag_desc
					 FROM tbBranchGroup tbg
					 WHERE tbg.comp_id = @comp_id AND tbg.brag_id = @brag_id)
				END																									[params25]





END
GO

-- ----------------------------------------------------------------------------------------------------------------------------------------------------
-- NOTAS Y VERSIONADO
-- ----------------------------------------------------------------------------------------------------------------------------------------------------
-- OJO !!!! SI SE TOCA ALGO EN ESTE SP DE MIERDAAAAAAAAAAAA TAMBIEN
--	HAY QUE TOCAR EXACTAMENTE LO MISMO EN EL OTRO SP DE MIERDA LLAMADO [spEmittedChecks_getReport](IMPRIMIR REPORTE ) OK ? GRACIAS !
-- STL - 09-03-2018 - DurkWorks - Se agregó filtro por GRUPO DE SUCURSALES REFERENCIA : #3773 #Parte = 3191
-- ----------------------------------------------------------------------------------------------------------------------------------------------------

CREATE Procedure [dbo].[spEmittedChecks_getReport4Grid]
(
		@comp_id				int,
		@lang_id				int,
		@page_id				int,

		@datefrompaydate		NVARCHAR(30),
		@datetopaydate			NVARCHAR(30),
		@ordervalues			int,
		@datefromemdate			NVARCHAR(30),
		@datetoemdate			NVARCHAR(30),
		@curr_id				int,
		@selection				int,
		@custsupp				int,
		@bankacc				int,
		@debval					int,
		@datefromcon			NVARCHAR(30),
		@datetocon				NVARCHAR(30),
		@ecct_id				INT,
		@bra_id					INT,
		@user_id				INT,
		@intBranch4Lang			INT,
		@brag_id				INT
)

AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	set nocount on
	set dateformat 'ymd'

	-- ---------------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------------
	/*
		Declare
				@comp_id				int,
				@lang_id				int,
				@page_id				int,

				@datefrompaydate		datetime,
				@datetopaydate			datetime,
				@ordervalues			int,
				@datefromemdate			datetime,
				@datetoemdate			datetime,
				@curr_id				int,
				@selection				bit,
				@custsupp				int,
				@bankacc				int,
				@debval					int,
				@datefromcon			datetime,
				@datetocon				datetime,
				@bra_id					int,
				@user_id				INT,
				@intBranch4Lang			INT,
				@ecct_id				INT,
				@brag_id				INT



		Select
				@comp_id				= 1,
				@lang_id				= 2,
				@page_id				= 10016,

				@datefrompaydate		= '1900-01-01',
				@datetopaydate			= '9999-12-31',
				@ordervalues			= -1,
				@datefromemdate			= '1900-01-01',
				@datetoemdate			= '9999-12-31',
				@curr_id				= 1,
				@selection				= -1,
				@custsupp				= -1,
				@bankacc				= -1,
				@debval					= 0,
				@datefromcon			= '1900-01-01',
				@datetocon				= '9999-12-31',
				@bra_id					= 1,
				@user_id				= 1,
				@ecct_id				= 152,
				@brag_id				= -1
	*/
	-- ---------------------------------------------------------------------------



	-- ---------------------------------------------------------
	-- Esto se tuvo que hacer para ejecutar desde la grilla
	-- generica que recibe un String SQL a ejecutar y los formatos
	-- de fecha pueden variar segun el SQL que este instalado
	-- Por lo que se pasan siempre en YMD y se convierten a fecha
	-- ---------------------------------------------------------
	DECLARE

		@ldatefrompaydate			 DATETIME,
		@ldatetopaydate				 DATETIME,
		@ldatefromemdate			 DATETIME,
		@ldatetoemdate				 DATETIME,
		@ldatefromcon				 DATETIME,
		@ldatetocon					 DATETIME



	set	@ldatefrompaydate = dbo.fnGetEnd_or_BeginOfDate(@datefrompaydate,'False')
	set	@ldatetopaydate = dbo.fnGetEnd_or_BeginOfDate(@datetopaydate,'True')

	set	@ldatefromemdate = dbo.fnGetEnd_or_BeginOfDate(@datefromemdate,'False')
	set	@ldatetoemdate = dbo.fnGetEnd_or_BeginOfDate(@datetoemdate,'True')

	set	@ldatefromcon = dbo.fnGetEnd_or_BeginOfDate(@datefromcon,'False')
	set	@ldatetocon = dbo.fnGetEnd_or_BeginOfDate(@datetocon,'True')



	-- -----------------------------------------------------------------------------------
	-- CARGO EN UNA VARIABLE DE TABLA LAS SUCURSALES DEL BRAG_ID O EN CASO DE SER -1
	-- CARGO SOLO LA QUE VIENE EN EL BRA_ID #3773
	-- -----------------------------------------------------------------------------------
		DECLARE @tblBranchs TABLE (comp_id	INT, bra_id INT PRIMARY KEY)
		INSERT INTO @tblBranchs
			SELECT
				tbgd.comp_id,
				tbgd.bra_id
				FROM tbBranchGroupDetail			tbgd	WITH(NOLOCK)
				INNER JOIN tbBranch					tb		WITH(NOLOCK)
				ON	tb.comp_id		= tbgd.comp_id	AND
					tb.bra_id		= tbgd.bra_id
			WHERE	tbgd.comp_id	= @comp_id		AND
					tbgd.brag_id	= @brag_id		AND
					tb.bra_disabled = 'False'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblBranchs
				(
					comp_id,
					bra_id
				)
				SELECT
					@comp_id,
					@bra_id

			END
	-- -----------------------------------------------------------------------------------



	DECLARE @fun_id INT
	SET @fun_id = 1


	Select
			case convert(bit,@selection) when 'True' then ct.supp_id
				else ct.cust_id
			end [ID],
			case convert(bit,@selection) when 'True' then s.supp_name
				else c.cust_name
			end [Name],
			ba.ba_desc,
			ec.ec_paydate,
			br.bra_desc,
			ec.ec_number,
			ec.ec_note,
			ct.ct_date,
			ec.ec_total,
			cu.curr_desc,
			ec.ec_exchangeToBranchCurrency,
			ec.ec_id

	From	dbo.tbEmmitedChecks								ec			WITH ( NOLOCK )

			INNER JOIN dbo.tbBankingAccounts				ba			WITH ( NOLOCK )
			ON  ec.comp_id			= ba.comp_id	AND
				ec.ba_id			= ba.ba_id

			LEFT JOIN tbEmmitedChecks_CheckBook				teccb		WITH ( NOLOCK )
			ON  teccb.comp_id		= ec.comp_id	AND
				teccb.ecct_id		= ec.ecct_id

			INNER JOIN dbo.tbCommercialTransactions			ct			WITH ( NOLOCK )
			ON  ct.comp_id			= ec.comp_id	AND
				ct.ct_transaction	= ec.ct_transaction


			LEFT JOIN dbo.tbBankingTransactions				bt			WITH ( NOLOCK )
			ON  bt.comp_id			= ec.comp_id	AND
				ec.bra_id			= bt.bra_id		AND
				ec.ec_id			= bt.ec_id		AND
				bt.bt_isCancelled	= 'False'

			INNER JOIN dbo.tbsysCurrency					cu			WITH ( NOLOCK )
			ON	ec.curr_id			= cu.curr_id

			INNER JOIN dbo.tbBranch							br			WITH ( NOLOCK )
			ON	br.bra_id			= ec.bra_id

			LEFT JOIN dbo.tbCustomer						c			WITH ( NOLOCK )
			ON	c.comp_id			= ct.comp_id	AND
				c.cust_id			= ct.cust_id	AND
				@selection			= convert(bit,@selection)

			LEFT JOIN dbo.tbSupplier						s			WITH ( NOLOCK )
			ON	s.comp_id			= ct.comp_id	AND
				s.supp_id			= ct.supp_id	AND
				@selection			= convert(bit,@selection)

			INNER JOIN @tblBranchs							tbb			--#3773
			ON	tbb.comp_id			= ec.comp_id			AND
				tbb.bra_id			= ec.bra_id

			INNER JOIN tbUsers4BranchFilter					vubf		WITH ( NOLOCK )
			ON  vubf.comp_id		= CT.comp_id	AND
				vubf.bra_id			= CT.bra_id		AND
				vubf.[user_id]		= @user_id


	Where	 ec.comp_id				= @comp_id
	--AND		 ec.bra_id				= @bra_id		#3773
	AND		 ec.ec_paydate			between  @ldatefrompaydate and  @ldatetopaydate
	AND		 ec.ec_EmissionDate		between  @ldatefromemdate  and  @ldatetoemdate
	AND		 ec.curr_id				= @curr_id
	AND		 (@bankacc				= -1 or		ba.ba_id			  = @bankacc)
	AND		 (@ordervalues			= -1 or		ec.ec_not_to_order    = convert(bit,@ordervalues))
	AND		 (	@debval				= -1 or		(@debval = 0 AND ec.ec_isPaid = 'TRUE') OR (@debval = 1 AND ec.ec_isPaid = 'False') )
	AND		 (
				(convert(bit,@selection) = 'True'   and (@custsupp = -1 or ct.supp_id = @custsupp)and (ct.supp_id is not null)) or
				(convert(bit,@selection) = 'False'  and (@custsupp = -1 or ct.cust_id = @custsupp)and (ct.cust_id is not null))
			 )
	AND ec.ec_isCancelled	= 'False'
	AND (@bankacc			= -1 OR	ba.ba_id = @bankacc)
	AND (@ecct_id			= -1 OR teccb.ecct_id = @ecct_id)




	ORDER BY ec.ec_paydate,id

	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/*************************************************************************************************************/
	select
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 416
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params1],
		@datefrompaydate [DateParams1],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 417
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params3],
		@datetopaydate [DateParams2],
			--convert(varchar,day(@datetopaydate)) + '/' + convert(varchar,month(@datetopaydate)) + '/' + convert(varchar,year(@datetopaydate))		[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 423
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params5],

				CASE @ordervalues WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id  =  @lang_id
						AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
						FROM	dbo.tbsysOptionsValues tov
						WHERE	tov.optval_class	= 1
						AND		tov.lang_id			= @lang_id
						AND		tov.optval_id		=   @ordervalues )

				END																																	[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 418
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params7],

		@datefromemdate [DateParams3],
			--convert(varchar,day(@datefromemdate)) + '/' + convert(varchar,month(@datefromemdate)) + '/' + convert(varchar,year(@datefromemdate))	[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 419
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params9],

			@datetoemdate [DateParams4],
			--convert(varchar,day(@datetoemdate)) + '/' + convert(varchar,month(@datetoemdate)) + '/' + convert(varchar,year(@datetoemdate))			[params10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 106
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params11],

			(SELECT		tc.curr_desc
						FROM	dbo.tbsysCurrency tc
						WHERE	tc.curr_id	= @curr_id)																								[params12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 529
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params13],

			CASE @selection WHEN 0 THEN
				CASE @custsupp WHEN -1 THEN
					(SELECT		tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tc.cust_name
					 FROM	dbo.tbCustomer tc
					 WHERE	tc.cust_id  = @custsupp)
				END
			ELSE
				CASE @custsupp WHEN -1 THEN
					(SELECT		tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT ts.supp_name
					 FROM	dbo.tbSupplier ts
					 WHERE	ts.supp_id  = @custsupp)
				END
			END																																		[params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 406
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params15],

				CASE @bankacc WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tba.ba_desc
			 		 FROM	dbo.tbBankingAccounts tba
					 WHERE tba.ba_id	=	@bankacc)
				END																																	[params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 422
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params17],

				CASE @debval WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tov.optval_desc
			 		 FROM	dbo.tbsysOptionsValues tov
					 WHERE tov.lang_id = @lang_id
					 AND	tov.optval_class = 16
					 AND	tov.optval_id = @debval)
				END																																	[params18],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 420
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params19],

			@datefromcon [DateParams5],
			--convert(varchar,day(@datefromcon)) + '/' + convert(varchar,month(@datefromcon)) + '/' + convert(varchar,year(@datefromcon))				[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 421
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params21],

		@datetocon [DateParams6],
			--convert(varchar,day(@datetocon)) + '/' + convert(varchar,month(@datetocon)) + '/' + convert(varchar,year(@datetocon))					[params22]


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 2914
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params22],


				CASE @ecct_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT teccb.ecct_desc
					 FROM dbo.tbEmmitedChecks_CheckBook teccb
					 WHERE teccb.comp_id = @comp_id and	teccb.ecct_id = @ecct_id)
				END																									[params23],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 639
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)						[params24],


				CASE @brag_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT
						tbg.brag_desc
					 FROM tbBranchGroup tbg
					 WHERE tbg.comp_id = @comp_id AND tbg.brag_id = @brag_id)
				END																									[params25]







END
GO








