CREATE PROCEDURE [dbo].[spEmittedChecks_UpdateData]
(
	@comp_id			int,
	@ec_id				int,
	@bra_id				Int,
	@ba_id				Int,
	@ec_ispaid			Bit,
	@processing_date		datetime
)
as

BEGIN

	set nocount on

	/*
	declare 	@comp_id			int,
	--			@lang_id			int,
				@bra_id				Int,
				@ec_id				Int,
				@ba_id				int,
				@DateDepositFrom	datetime,
				@DateDepositTo		datetime,
				@dummy				bit


	select		@comp_id			= 1,
	--			@lang_id			= 2,
				@bra_id				= 1,
				@ec_id				= 8,
				@ba_id				= 16,
				@DateDepositFrom	= '09/01/2009',
				@DateDepositTo		= '18/06/2009',
				@dummy				= 'true'

	*/


	Update	dbo.tbEmmitedChecks
	Set		ec_isPaid = @ec_ispaid,
			ec_PaymentFinalDate = @processing_date
	Where comp_id = @comp_id
	And	    ec_id = @ec_id
	And    bra_id = @bra_id
	And     ba_id = @ba_id

END
GO







CREATE PROCEDURE [dbo].[spEmittedChecks_updateIsPayedData]

(
	@comp_id				int,
	--@ba_id					int,
	@ec_id					int,
	@value					bit,
	@ProcessingDate			datetime
)
as

/*
DECLARE @comp_id			int,
		@ba_id				int,
		@ec_id				int,
		@value				bit,
		@ProcessingDate		datetime

SELECT 	@comp_id			= 1,
		@ba_id				= 31,
		@ec_id				= 1,
