GO







CREATE PROCEDURE [dbo].[spEmittedChecks_UpdateIsPrinted]

(
	@comp_id				int,
	@ec_id					int

)

as
	---------------------------------------------------------------------------------------------
	---------------------------------------------------------------------------------------------
	/*


	DECLARE @comp_id			int,
			@ec_id				int

	SELECT 	@comp_id			= 1,
			@ec_id				= 1


	*/

	---------------------------------------------------------------------------------------------
	---------------------------------------------------------------------------------------------

BEGIN


	IF EXISTS(	SELECT 1
	          		FROM tbEmmitedChecks tec WITH (NOLOCK)
	          		WHERE	tec.comp_id = @comp_id	AND
	          				tec.ec_id	= @ec_id	AND
	          				ISNULL(tec.ec_isPrinted,'False') = 'False')
		BEGIN

			-- Pone el cheque como impreso y asigna el numero.
			UPDATE  dbo.tbEmmitedChecks
				SET		ec_isPrinted	= 'True',
						ec_Number		= teccb.ecct_fromNumber + 1
				FROM tbEmmitedChecks ec
				INNER JOIN tbEmmitedChecks_CheckBook teccb
					ON	teccb.comp_id = ec.comp_id AND
						teccb.ecct_id = ec.ecct_id
				WHERE	ec.comp_id		= @comp_id	AND
						ec.ec_id		= @ec_id


			DECLARE @ecct_id			AS INT
			DECLARE @ecct_fromNumber	AS DECIMAL(20,0)
			-- Recupera el nro asignado
			SELECT	@ecct_fromNumber	= ec.ec_Number,
					@ecct_id			= ec.ecct_id
				FROM tbEmmitedChecks ec						WITH (NOLOCK)
				WHERE	ec.comp_id		= @comp_id	AND
						ec.ec_id		= @ec_id

			-- actualiza la chequera con el ultimo numero asignado.
			UPDATE tbEmmitedChecks_CheckBook
				SET	ecct_fromNumber = @ecct_fromNumber
				WHERE	comp_id		= @comp_id AND
						ecct_id		= @ecct_id

		END




END

GO







