CREATE PROCEDURE [dbo].[spEmmitedChecks_CheckBook_getDataById]
(
	@comp_id						INT,
	@ecct_id						INT
)
as
set nocount on


/*

---------------------------------------------------------

DECLARE 	@comp_id				INT,
			@ecct_id				INT

SELECT		@comp_id = 1,
			@ecct_id = 152
---------------------------------------------------------
*/

SELECT comp_id,
		ecct_desc,
		ba_id,
		brag_id,
		ecct_fromNumber,
		ecct_toNumber,
		ecct_nextNumber,
		ecct_disabled,
		--ecct_isAvailable4Print,
		ecct_printerName,
		ecct_printText,
		ecct_printerComputerName,
		ecct_id,
		isnull(ecct_isAvailable4Print,'False') [ecct_isAvailable4Print]

FROM	tbEmmitedChecks_CheckBook	WITH (NOLOCK)

WHERE	comp_id		=	@comp_id
AND		ecct_id		=	@ecct_id
AND isnull(ecct_disabled,'False')   = 'False'













GO






CREATE procedure spEmmitedChecks_getDataByFilters
(
	@comp_id			INT,
	@bra_id				INT,
	@ba_id				INT,
	@ec_number			nVARCHAR(50),
	--EmissionDate
	@datefrom			datetime,
	@dateto				datetime,
	--PayDate
	@paydatefrom		datetime,
	@paydateto			datetime
)
as set NOCOUNT on

set dateformat 'ymd'



-- --------------------------------------------
-- Testing
-- --------------------------------------------
/*
	declare
		@comp_id			INT,
		@bra_id				INT,
		@ba_id				INT,
		@ec_number			VARCHAR(100),
		--EmissionDate
		@datefrom			datetime,
		@dateto				datetime,
		--PayDate
		@paydatefrom		datetime,
		@paydateto			datetime

	select
		@comp_id			= 1,
		@bra_id				= 1,
		@ba_id				= 31,
		@ec_number			= '5',
		--EmissionDate
		@datefrom			= '2012-01-01',
		@dateto				= '2013-12-31',
		--PayDate
		@paydatefrom		= '2012-01-01',
		@paydateto			= '2013-12-31'
*/
-- --------------------------------------------


set	@dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,1)
set	@paydateto	= dbo.fnGetEnd_or_BeginOfDate(@paydateto,1)

	select
		' '						[ ],
		tec.ec_Number,
		tec.ec_Total,
		tec.ec_EmissionDate,
		tec.ec_PayDate,
		isnull(tec.ec_memo,'')	[ec_memo],
		isnull(tec.ec_payto,'')	[ec_payto],
		tec.ec_id				[ID]


from tbEmmitedChecks tec

where	tec.comp_id			= @comp_id
and		tec.bra_id			= @bra_id
and		tec.ec_Number like	'%'+@ec_number+'%'
and		tec.ec_EmissionDate between @datefrom		and @dateto
and		tec.ec_PayDate		between @paydatefrom	and @paydateto
and     (@ba_id				= -1	or tec.ba_id	= @ba_id)

GO





