CREATE PROCEDURE [dbo].[spExportDefaultersCustomers_getDataByFilters]
(
	@comp_id					INT,
	@lang_id					INT,
	@bra_id						INT,
	@prof_id					INT,
	@user_id					INT,
	@orderby					INT,						-- Ordenar por 1:codigo 2-Nombre 3- ZONA o AREA
	@PastDueLoans				DECIMAL(19,2),				-- Saldos morosos sup a
	@LastPaymentBefore			INT,						-- ultimo pago anterior a
	@DaysPastDueGreaterThan		DECIMAL(19,2),				-- dias de mora sup a
	@guid						UNIQUEIDENTIFIER,			-- clientes
	@option						INT,						-- 1:incluir/0:excluir , no se usa
	@strdefaultsLevels			NVARCHAR(500),				-- Aca llegan los que se debe incluir SIEMPRE
	@cit_id						INT
)
AS



BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on
	set dateformat 'ymd'


	-- -----------------------------------------------------------------------------------------------
	-- -----------parametros de prueba----------------------------------------------------------------
	-- -----------------------------------------------------------------------------------------------
/*
		DECLARE		@comp_id					INT,
					@lang_id					INT,
					@bra_id						INT,
					@prof_id					INT,
					@user_id					INT,
					@orderby					INT,
					@PastDueLoans				DECIMAL(19,2),
					@LastPaymentBefore			INT,
					@DaysPastDueGreaterThan		DECIMAL(19,2),
					@guid						UNIQUEIDENTIFIER,
					@option						INT,
					@strdefaultsLevels			NVARCHAR(500)

		SELECT		@comp_id					= 1,
					@lang_id					= 2,
					@bra_id						= 1,
					@prof_id					= 1,
					@user_id					= 39,
					@orderby					= 1,
					@PastDueLoans				= 8000,
					@LastPaymentBefore			= 30,
					@DaysPastDueGreaterThan		= 50,
					@guid						= '64cc46d4-209d-4a9a-b3d8-c22121718500',
					@option						= 1,
					@strdefaultsLevels			= '1;'

		drop table #tmpCommercialTransactionsLoan
  */
	-------------------------------------------------------------------------------------------------


	-- -------------------------------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de CLIENTES para Filtros
	-- -------------------------------------------------------------------------------------

	DECLARE @lGuidCust AS UNIQUEIDENTIFIER

	SET @lGuidCust = CONVERT(UNIQUEIDENTIFIER,@guid)

	DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Customer
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuidCust     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Customer
				SELECT tc.cust_id
				FROM tbCustomer tc
					WHERE tc.comp_id = @comp_id
		END
	-- -------------------------------------------------------------------------------------


	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbDefaultLevels
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpDefaultLevels TABLE(def_id INT PRIMARY KEY)
	IF @strdefaultsLevels <>  ''
		BEGIN
			INSERT INTO @tmpDefaultLevels (def_id)	SELECT items
			                                  			FROM dbo.fnSplitTable(@strdefaultsLevels,';') fst
		END
	-- -------------------------------------------------------------------------------------




	SELECT
		tc2.cust_id												[cust_id],
		tc2.cust_name											[cust_name],
		tc.country_desc,
		--''								[registro],
		--''								[comercio],
		tc2.cust_cd												[cust_cd],
		tc2.cust_taxNumber										[cust_taxNumber],
		ISNULL(tcs.street_desc, tc2.cust_address)				[cust_address],
		ISNULL(tc2.cust_addressNumber,'')						[cust_addressNumber],
		--''								[situacion],
		--''								[fechabaja],
		tov.optval_desc											[cust_maleOrFemale],
		SUM(
			CASE
				WHEN tctl.comp_id IS NULL THEN tct.ct_ABalance
				ELSE			   			   tctl.ct_ABalance
			END *  vwc.PlusOrMinus
			)													[ct_ABalance],
		MAX(
			CASE
				WHEN tct.sd_id <> 1 AND tct.sd_id <> 4 AND tct.sd_id <> 21 AND tct.sd_id <> 31 AND  tct.sd_id <> 44 THEN 0
				WHEN tctl.comp_id IS NULL  AND tct.ct_ABalance > 0 THEN tct.ctl_daysPastDue
				WHEN tctl.comp_id IS NOT NULL  AND tctl.ct_ABalance > 0 THEN tctl.ctl_daysPastDue
				ELSE			   			   0
			END *  vwc.PlusOrMinus
			)													[defaultDays],
		tc2.cust_birthDay										[cust_birthDay],
		tc2.cust_phone1											[cust_phone1],
		tc2.cust_cellPhone										[cust_cellPhone],
		CONVERT(DATETIME,NULL)									[lastPayDate],
		CONVERT(DATETIME,NULL) /*ISNULL(tctl.ctl_payDate,tct.ct_payDate)*/
																[ctl_paydate],

		--tmp2.ctl_PayDate,
		--MAX(
		--		CASE
		--			WHEN NOT (tct.sd_id = 6 OR tct.sd_id = 13)																		THEN NULL
		--			WHEN tc2.cust_lastPaymentDatefromOtherERP IS NULL																THEN	tct.ct_date
		--			WHEN tc2.cust_lastPaymentDatefromOtherERP IS NOT NULL AND   tct.ct_date >= tc2.cust_lastPaymentDatefromOtherERP THEN	tct.ct_date
		--			WHEN tc2.cust_lastPaymentDatefromOtherERP IS NOT NULL AND   tct.ct_date < tc2.cust_lastPaymentDatefromOtherERP	THEN	tc2.cust_lastPaymentDatefromOtherERP
		--			ELSE	NULL
		--		END
		--	)														[lastPayDate],
		' '															[ci_desc],
		' '															[ci_Note]

		INTO #tmpCommercialTransactionsLoan


		-- OJO CON LOS INNER JOINS CON COSAS QUER MULTIPLIQUEN ROWS !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
		FROM tbCommercialTransactions								tct			WITH (NOLOCK)
			INNER JOIN vwCommercialTransactions_forSales			vwc			WITH (NOLOCK)
				ON	vwc.comp_id			= tct.comp_id	AND
					vwc.bra_id			= tct.bra_id	AND
					vwc.ct_transaction	= tct.ct_transaction
			INNER JOIN tbUsers4BranchFilter tubf
				ON	tubf.comp_id	= tct.comp_id	AND
					tubf.bra_id		= tct.bra_id	AND
					tubf.[user_id]	= @user_id
			INNER JOIN @tblComplexFilter_Customer					tmp
				ON		tmp.cust_id				= tct.cust_id
			INNER JOIN tbCustomer									tc2			WITH (NOLOCK)
				ON		tct.comp_id				= tc2.comp_id		AND
						tct.cust_id				= tc2.cust_id

			INNER JOIN @tmpDefaultLevels							tmpdl
				ON		tmpdl.def_id			= tc2.def_id

			LEFT JOIN tbCommercialTransactionsLoan					tctl		WITH (NOLOCK)
			ON		tctl.comp_id			= tct.comp_id			AND
					tctl.ct_transaction		= tct.ct_transaction

			LEFT JOIN tbsysOptionsValues							tov			WITH (NOLOCK)
			ON tov.lang_id					= @lang_id				AND
			   tov.optval_id				= tc2.cust_maleOrFemale	AND
			   tov.optval_class				= 377

			INNER JOIN tbsysCountry									tc			WITH(NOLOCK)
			ON		tc.country_id			= tc2.country_id

			LEFT JOIN tbCities_Streets								tcs			WITH(NOLOCK)
			ON		tcs.comp_id				= tc2.comp_id			AND
					tcs.street_id			= tc2.street_id

		WHERE	tct.comp_id					= @comp_id				AND
				vwc.sd_isInBalance			= 'True'				AND
				CASE
					WHEN tctl.comp_id IS NULL THEN	tct.ctl_daysPastDue
					ELSE							tctl.ctl_daysPastDue
				END		> @DaysPastDueGreaterThan				--	AND

		GROUP BY	tc2.cust_id,
					[cust_name],
					tc.country_desc,
					[cust_cd],
					[cust_taxNumber],
					tcs.street_desc,
					[cust_address],
					tc2.cust_addressNumber,
					tov.optval_desc,
					[cust_birthDay],
					[cust_phone1],
					[cust_cellPhone]--,
					--ctl_PayDate, tct.ct_payDate

		HAVING 		SUM(
						CASE
							WHEN tctl.comp_id IS NULL THEN tct.ct_ABalance
							ELSE			   			   tctl.ct_ABalance
						END *  vwc.PlusOrMinus
						)	> @PastDueLoans



	IF @cit_id > 0
		BEGIN
			-- Borra los que YA estan informados en el padron seleccionado y NO tienen aun la baja registrada.
			DELETE FROM #tmpCommercialTransactionsLoan
				FROM	#tmpCommercialTransactionsLoan tmp
				INNER JOIN tbCreditBehavior_GeneralInfo tcbgi	WITH (NOLOCK)
					ON	tcbgi.comp_id = @comp_id		AND
						tcbgi.cust_id = tmp.cust_id
				WHERE   tcbgi.cit_id  = @cit_id			AND
						tcbgi.ci_dateBegin IS NOT NULL	AND
						tcbgi.ci_dateEnd   IS     NULL
		END



	-- Actualiza la fecha del ultimo VENCIMIENTO DE CUOTA
	UPDATE #tmpCommercialTransactionsLoan
		SET ctl_paydate = (
								SELECT TOP 1
												CASE
													WHEN tctl.comp_id IS NULL THEN tct.ct_payDate
													ELSE tctl.ctl_payDate
												END
									FROM	tbCommercialTransactions tct
									INNER JOIN tbUsers4BranchFilter tubf
										ON	tubf.comp_id	= tct.comp_id	AND
											tubf.bra_id		= tct.bra_id	AND
											tubf.[user_id]	= @user_id
									LEFT JOIN tbCommercialTransactionsLoan tctl
										ON	tctl.comp_id		= tct.comp_id			AND
											tctl.ct_transaction = tct.ct_transaction
									WHERE tct.comp_id	= @comp_id AND
										  tct.cust_id   = #tmpCommercialTransactionsLoan.cust_id	AND
 										  CASE
										      WHEN tctl.comp_id IS NULL AND tct.ct_ABalance <> 0		THEN 1
										      WHEN tctl.comp_id IS NOT NULL AND tctl.ct_ABalance <> 0	THEN 1
											  ELSE 0
										  END	 = 1												AND
										  (
										  tct.sd_id	= 1
											OR
										  tct.sd_id = 4
											OR
									      tct.sd_id = 21
											OR
									      tct.sd_id = 31
											OR
									      tct.sd_id = 44
									      )
									ORDER BY
												CASE
													WHEN tctl.comp_id IS NULL THEN tct.ct_payDate
													ELSE tctl.ctl_payDate
												END



						)


	-- Actualiza la fecha del ultimo pago
	UPDATE #tmpCommercialTransactionsLoan
		SET lastPayDate = (
			SELECT  MAX(tct.ct_date)
				FROM	tbCommercialTransactions tct
						INNER JOIN tbUsers4BranchFilter tubf
							ON	tubf.comp_id	= tct.comp_id	AND
								tubf.bra_id		= tct.bra_id	AND
								tubf.[user_id]	= @user_id
						WHERE tct.comp_id	= @comp_id AND
							  tct.cust_id   = #tmpCommercialTransactionsLoan.cust_id AND
							 (
							  tct.sd_id	= 6
								OR
							  tct.sd_id = 13
							 )
						)

	-- borra los que el ultimo pago queda fuera de rango
	DELETE FROM #tmpCommercialTransactionsLoan WHERE lastPayDate IS NOT NULL AND lastpaydate  >  DATEADD(DAY,  -@LastPaymentBefore, GETDATE())


	IF @orderby = 1 -- Còdigo
		BEGIN
			SELECT tmp.*
				FROM #tmpCommercialTransactionsLoan tmp
				INNER JOIN tbcustomer tc
					ON	tc.comp_id = @comp_id AND
						tc.cust_id = tmp.cust_id
				ORDER BY	tc.cust_id
		END
	ELSE IF @orderby = 2 -- Nombre
		BEGIN
			SELECT tmp.*
				FROM #tmpCommercialTransactionsLoan tmp
				INNER JOIN tbcustomer tc
					ON	tc.comp_id = @comp_id AND
						tc.cust_id = tmp.cust_id
				ORDER BY	tc.cust_name
		END
	ELSE IF @orderby = 3 -- Zona
		BEGIN
			SELECT tmp.*
				FROM #tmpCommercialTransactionsLoan tmp
				INNER JOIN tbcustomer tc
					ON	tc.comp_id = @comp_id AND
						tc.cust_id = tmp.cust_id
				ORDER BY	tc.ss_id
		END

END





GO







