--desc: Verificar que esten cerrados todos los trabajos anteriores
--date: 19/03/14
--author: GA
-------------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spFactory_SaleOrder4Factoring_ExistsJobsPending]
(
	@comp_id			INT,
	@soh_id				INT
)


AS

SET NOCOUNT ON

BEGIN


---------------------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@soh_id				INT



SELECT 		@comp_id			= 1,
			@soh_id				= 33083

*/
---------------------------------------------------------------




		IF EXISTS	(	 SELECT tfsof.ff_orderOfFactoring

		         	 	 FROM tbFactory_SaleOrder4Factoring tfsof

		         	 	 WHERE tfsof.ff_isFactored			= 'FALSE'
		         	 	 AND   tfsof.soh_id					= @soh_id



					)
						-- Hay trabajos pendientes de procesar. NO FINALIZADO
						SELECT 1	[ExistJobPending]

		ELSE
						-- No hay trabajos pendientes de procesar. FINALIZADO
						SELECT 0	[ExistJobPending]




END



GO






create PROCEDURE [dbo].[spFactory_SaleOrder4Factoring_getDataByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@soh_id		INT
)


as




---------------------------------------------------------------
/*
DECLARE 	@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@prof_id	INT,
			@user_id	INT,
			@soh_id		INT


SELECT		@comp_id	=1,
			@lang_id	=1,
			@bra_id		=1,
			@prof_id	=1,
			@user_id	=1,
			@soh_id		=32942
*/
---------------------------------------------------------------
	SET NOCOUNT ON

		BEGIN

			SELECT
				' '													[ ],
				' '													[ ],
				ti.item_code											,
				ti.item_desc											,
				ISNULL(tfsof.ff_dateOfFactoringAssigned	,'')		[ff_dateOfFactoringAssigned],
				ISNULL(tfsof.ff_orderOfFactoring		,0 )		[ff_orderOfFactoring],
				ISNULL(tfsof.ff_isInFactoring			,'False')	[ff_isInFactoring],
				ISNULL(tfsof.user_id_4BeginFactoring	,'')		[user_id_4BeginFactoring],
				ISNULL(tfsof.ff_dateOfBeginFactoring	,'')		[ff_dateOfBeginFactoring],
				ISNULL(tfsof.user_id_4EndFactoring		,'')		[user_id_4EndFactoring],
				ISNULL(tfsof.ff_dateOfEndFactoring		,'')		[ff_dateOfEndFactoring],
				ISNULL(tfsof.ff_isFactored				,'False')	[ff_isFactored]



			FROM tbFactory_SaleOrder4Factoring		tfsof

				INNER JOIN tbSaleOrderHeader		tsoh
				ON	tsoh.comp_id	= tfsof.comp_id AND
					tsoh.bra_id		= tfsof.bra_id	AND
					tsoh.soh_id		= tfsof.soh_id

				INNER JOIN tbSaleOrderDetail		tsod
				ON	tsod.bra_id		= tsoh.bra_id	AND
					tsod.comp_id	= tsoh.comp_id	AND
					tsod.soh_id		= tsoh.soh_id

				INNER JOIN tbItem					ti
				ON	ti.comp_id		= tsod.comp_id	AND
					ti.item_id		= tsod.sod_item_id_origin

			WHERE	tfsof.comp_id	= @comp_id		AND
					tfsof.bra_id	= @bra_id		AND
					tfsof.soh_id	= @soh_id



		END




GO







CREATE PROCEDURE [dbo].[spFactory_SaleOrder4Factoring_getDataById]
(
	@comp_id	INT,
	@lang_id	INT,
	@sod_id		INT
)


as

-------------------------------------------------------------
/*
DECLARE 		@comp_id	INT,
				@lang_id	INT,
				@sod_id		INT


SELECT			@comp_id	= 1,
				@lang_id	= 2,
				@sod_id		= 22459
*/
-------------------------------------------------------------



	SET NOCOUNT ON

		BEGIN

			SELECT
					tfsof.fs_id,
					tfsof.bra_id,
					tfsof.fs_id,
					tfsof.soh_id,
					tfsof.sod_id,
					ISNULL(tfsof.ff_dateOfFactoringAssigned	,'')		[ff_dateOfFactoringAssigned],
					ISNULL(tfsof.ff_orderOfFactoring		,0 )		[ff_orderOfFactoring],
					ISNULL(tfsof.ff_isInFactoring			,'False')	[ff_isInFactoring],
					ISNULL(tfsof.user_id_4BeginFactoring	,'')		[user_id_4BeginFactoring],
					ISNULL(tfsof.ff_dateOfBeginFactoring	,'')		[ff_dateOfBeginFactoring],
					ISNULL(tfsof.user_id_4EndFactoring		,'')		[user_id_4EndFactoring],
					ISNULL(tfsof.ff_dateOfEndFactoring		,'')		[ff_dateOfEndFactoring],
					ISNULL(tfsof.ff_isFactored				,'False')	[ff_isFactored]	,
					ti.item_id,
					tc.cust_id



			FROM tbFactory_SaleOrder4Factoring				tfsof

				INNER JOIN tbSaleOrderHeader				tsoh
				ON  tsoh.comp_id	= tfsof.comp_id	AND
					tsoh.bra_id		= tfsof.bra_id	AND
					tsoh.soh_id		= tfsof.soh_id


				INNER JOIN tbSaleOrderDetail				tsod
				ON  tsod.comp_id	= tfsof.comp_id AND
					tsod.bra_id		= tfsof.bra_id	AND
					tsod.soh_id		= tfsof.soh_id	AND
					tsod.sod_id		= tfsof.sod_id


				INNER JOIN tbItem							ti
				ON  ti.comp_id = tsod.comp_id		AND
					ti.item_id = tsod.item_id

				INNER JOIN tbCustomer						tc
				ON  tc.comp_id = tsoh.comp_id		AND
					tc.cust_id = tsoh.cust_id


			WHERE	tfsof.comp_id		= @comp_id		AND
					tfsof.sod_id		= @sod_id



		END




GO





CREATE PROCEDURE [dbo].[spFactory_SaleOrder4Factoring_getPendingData]
(
	@comp_id	INT,
	@soh_id		INT
)
AS

	SET NOCOUNT ON

	BEGIN

		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@soh_id		INT
			SELECT
				@comp_id	= 1,
				@soh_id		= 33080
		*/
		-- ------------------------------------

		DECLARE
			@lsoh_id	INT

		IF @soh_id = 0
			SET @lsoh_id = -1
		ELSE
			SET @lsoh_id = @soh_id


		SELECT

			CASE
				WHEN tfsof.ff_dateOfFactoringAssigned < ISNULL(tfsof.ff_dateOfBeginFactoring, GETDATE()) THEN 'RED'
				WHEN tfsof.ff_dateOfFactoringAssigned = ISNULL(tfsof.ff_dateOfBeginFactoring, GETDATE()) THEN 'BLUE'
				WHEN tfsof.ff_dateOfFactoringAssigned > ISNULL(tfsof.ff_dateOfBeginFactoring, GETDATE()) THEN 'GREEN'
			END																								  [ ],
			--tfsof.bra_id,
			tfsof.soh_id,
			ISNULL(tfs.fs_desc, '')				[fs_id],
			ti.item_desc,
			tfsof.ff_dateOfFactoringAssigned,
			ISNULL(tu.user_nick,'')				[user_id_4BeginFactoring],
			tfsof.ff_dateOfBeginFactoring,
			ISNULL(tu2.user_nick,'')			[user_id_4EndFactoring],
			tfsof.ff_dateOfEndFactoring,
			tfsof.ff_isFactored

		FROM tbFactory_SaleOrder4Factoring		tfsof

			INNER JOIN tbSaleOrderDetail		tsod	WITH(NOLOCK)
			ON	tsod.comp_id	= tfsof.comp_id AND
				tsod.bra_id		= tfsof.bra_id	AND
				tsod.soh_id		= tfsof.soh_id	AND
				tsod.sod_id		= tfsof.sod_id

			INNER JOIN tbItem					ti		WITH(NOLOCK)
			ON	ti.comp_id		= tsod.comp_id	AND
				ti.item_id		= tsod.item_id

			LEFT JOIN tbFactory_Sectors			tfs		WITH(NOLOCK)
			ON	tfs.comp_id		= tfsof.comp_id	AND
				tfs.fs_id		= tfsof.fs_id

			LEFT JOIN tbUser					tu		WITH(NOLOCK)
			ON	tu.[user_id]	= tfsof.user_id_4BeginFactoring

			LEFT JOIN tbUser					tu2		WITH(NOLOCK)
			ON	tu2.[user_id]	= tfsof.user_id_4EndFactoring

--			LEFT JOIN tbBranch					tb		WITH(NOLOCK)
--			ON	tb.comp_id		= tfsof.comp_id	AND
--				tb.bra_id		= tfsof.bra_id

		WHERE	tfsof.comp_id		= @comp_id	AND
				tfsof.ff_isFactored = 'False'	AND
				(@lsoh_id			= -1 OR tfsof.soh_id = @lsoh_id)


		ORDER BY tfsof.soh_id, tfsof.ff_orderOfFactoring

	END
GO





CREATE PROCEDURE [dbo].[spFactory_SaleOrder4Factoring_InsertData]
(
	@comp_id			INT,
	@bra_id				INT,
	@soh_id				INT,
	@sod_id				INT,
	@order				INT,
	@return_value		INT OUTPUT
)
AS


	SET NOCOUNT ON

		BEGIN


			SET DATEFORMAT 'ymd'
			/*
			DECLARE
				@comp_id						INT,
				@bra_id							INT,
				@soh_id							INT,
				@sod_id							INT,
				@order							INT,
				@return_value					INT

			SELECT
				@comp_id						= 1,
				@bra_id							= 1,
				@soh_id							= 33094,
				@sod_id							= 22459,
				@order							= 1
			*/

			-- -------------------------------------------------------
			-- VARIABLES DE TRABAJO
			-- 1º.- Cantidad de Trabajos por Día
			-- 2º.- Cantidad de Unidades de Tiempo a utilizar por día
			-- 3º.- Fecha de Proceso para el Insert en Factory
			-- 4º.- Loop de Control para el Bucle
			-- -------------------------------------------------------

				DECLARE
					--@MaxJobsByDay		INT,
					--@MaxTimeUnitsByDay	INT,
					@lDate4Process		DATETIME,
					@lLoopControl		BIT--,
					--@lfs_id				INT

				--Obtenemos el FS_ID del artículo a cargar


				-- Si la PUTA tabla se llama tbFactory_SectorsSSSSSSSSByItem y como lo hablamos... son MUCHOS sectores x cada item !!!!!!!!!!!!!!!!!!!!
				-- POR FAVORRRRRRRRRRRRRRRRRR
--				SELECT
--					@lfs_id = tfsbi.fs_id
--				FROM tbSaleOrderDetail					tsod
--					INNER JOIN tbFactory_SectorsByItem	tfsbi
--					ON	tfsbi.comp_id	= tsod.comp_id	AND
--						tfsbi.item_id	= tsod.item_id
--				WHERE	tsod.comp_id	= @comp_id		AND
--						tsod.soh_id		= @soh_id		AND
--						tsod.sod_id		= @sod_id
--
				--SELECT @lfs_id



				-- SETEAMOS LA FECHA DE TRABAJO CON LA ACTUAL PARA CARGAR LOS TRABAJOS
				SET @lDate4Process = dbo.fnGetEnd_or_BeginOfDate(GETDATE(),'False')

				--SELECT @lDate4Process

				--OBTENEMOS LOS VALORES DE LAS UNIDADES DE TIEMPO Y DE TRABAJOS POR DIA
--				SELECT
--					@MaxJobsByDay			= tfs.fs_maxJobsByDay,
--					@MaxTimeUnitsByDay		= tfs.fs_factoryIndexByday
--				FROM tbFactory_Sectors					tfs
--				WHERE	tfs.comp_id			= @comp_id	AND
--						tfs.fs_id			= @lfs_id

				--SELECT @MaxJobsByDay, @MaxTimeUnitsByDay
				-- *************************************************************************************************************************************
				-- PROCESAMIENTO
				-- *************************************************************************************************************************************
				--IF @lfs_id IS NULL SET @lLoopControl = 'True'  -- Si el articulo NO tiene sectores definidos NO debe entrar aca sino se cuelga y no sale mas !!!
				--STL CURSOR
					DECLARE
						@FactorySector		INT,
						@Item_Id			INT,
						@FactoryOrder		INT,
						@FactoryDays		INT,
						@lSOD_ID			INT,
						@MaxJobsByDay		INT,
						@MaxTimeUnitsByDay	INT

					DECLARE Cursor_AssingTurnByFactorySector CURSOR LOCAL FAST_FORWARD  FOR

						SELECT
							tsod.item_id,
							tfsbi.fs_id,
							tfsbi.fs_order,
							tfsbi.fs_factoryDays,
							tfs.fs_maxJobsByDay,
							tfs.fs_factoryIndexByday

						FROM tbSaleOrderDetail					tsod	WITH(NOLOCK)
							INNER JOIN tbFactory_SectorsByItem	tfsbi	WITH(NOLOCK)
							ON	tfsbi.comp_id	= tsod.comp_id	AND
								tfsbi.item_id	= tsod.item_id
							INNER JOIN tbFactory_Sectors		tfs		WITH(NOLOCK)
							ON	tfs.comp_id		= tfsbi.comp_id AND
								tfs.fs_id		= tfsbi.fs_id

						WHERE	tsod.comp_id	= @comp_id		AND
								tsod.soh_id		= @soh_id		AND
								tsod.sod_id		= @sod_id

						ORDER BY tsod.item_id, tfsbi.fs_order ASC

						OPEN	Cursor_AssingTurnByFactorySector

						-- lectura anticipada del cursor
						FETCH	Cursor_AssingTurnByFactorySector
						INTO	@Item_Id,
								@FactorySector,
								@FactoryOrder,
								@FactoryDays,
								@MaxJobsByDay,
								@MaxTimeUnitsByDay

						-- se recorre el cursor hasta el fin del mismo
						WHILE   @@FETCH_STATUS = 0
						BEGIN
							--POR CADA ARTICULO Y POR CADA SECTOR DE FABRICACION ASOCIADO
							--CREA EL NUEVO TURNO DE FABRICACIÓN.

							--SETEAMOS EL CONTROLADOR DEL LOOP EN FALSO PARA QUE INICIE LAS ITERACIONES
							SET @lLoopControl = 'False'
							--***************************************************************************************************************************************************************************
								--SELECT 1


								WHILE @lLoopControl = 'False'
									BEGIN
										--CHECKEAMOS QUE LA FECHA NO ESTÉ EN LA TABLA DE DIAS NO DISPONIBLES
										IF dbo.fnGetEnd_or_BeginOfDate(@lDate4Process,'False') NOT IN (SELECT dbo.fnGetEnd_or_BeginOfDate(tfnwd.fs_noWorkingDay,'False')
																								  FROM tbFactory_NoWorkingDays tfnwd WHERE tfnwd.fs_id = @FactorySector)
											BEGIN
												--SELECT 'ENTRE ACA 1'
												--SET @lLoopControl = 'True'

												--CHECKEAMOS QUE NO SEA NI SABADO NI DOMINGO
												IF (DATEPART(weekday, GETDATE()) <> 6) AND (DATEPART(weekday,GETDATE()) <> 7)

													BEGIN
														--SELECT 'ENTRE ACA 2'
														--SET @lLoopControl = 'True'

														--CHECKEAMOS SI ES POSIBLE ASIGNAR UN TRABAJO MÁS AL DÍA ACTUAL
														IF (SELECT COUNT(*)
															FROM tbFactory_SaleOrder4Factoring			tfsof
															WHERE	tfsof.comp_id	= @comp_id	AND
															tfsof.fs_id				= @FactorySector	AND
															tfsof.ff_isInFactoring	= 'True'	AND
															tfsof.ff_isFactored		= 'False'	AND
															dbo.fnGetEnd_or_BeginOfDate(tfsof.ff_dateOfFactoringAssigned ,'False') =  dbo.fnGetEnd_or_BeginOfDate(GETDATE(),'False')) < @MaxJobsByDay

															BEGIN
																--SELECT 'ENTRE ACA 3'
																--SET @lLoopControl = 'True'

																/*******************************************************************************************************
																CHECKEAMOS SI NO ESTAN SUPERADAS LAS UNIDADES DE TIEMPO DISPONIBLES PARA ASIGNAR TRABAJOS A ESTE DÍA
																SE REALIZA UNA RESTA PARA SABER SI LA CANTIDAD DE UNIDADES HORARIAS RESULTANTES ES POSITIVA, EN ESE
																CASO SE REALIZA EL INSERT FINAL (HABIENDO SUPERADO TODAS LAS INSTANCIAS ANTERIORES)
																********************************************************************************************************/
																IF (@MaxTimeUnitsByDay - (SELECT ISNULL(SUM(ISNULL(tfsbi.fs_factoryIndex,0)),0)
																						  FROM tbFactory_SaleOrder4Factoring			tfsof
																							INNER JOIN tbSaleOrderDetail				tsod	WITH(NOLOCK)
																								ON	tsod.comp_id	= tfsof.comp_id		AND
																									tsod.soh_id		= tfsof.soh_id		AND
																									tsod.sod_id		= tfsof.sod_id
																							INNER JOIN tbFactory_SectorsByItem			tfsbi	WITH(NOLOCK)
																								ON	tfsbi.comp_id	= tsod.comp_id		AND
																									tfsbi.item_id	= tsod.item_id

																						   WHERE	tfsof.comp_id			= @comp_id	AND
																									tfsof.fs_id				= @FactorySector	AND
																									tfsof.ff_isInFactoring	= 'True'	AND
																									tfsof.ff_isFactored		= 'False')) > 0


																	BEGIN
																		--SELECT 'ENTRE ACA 4'
																		--SET @lLoopControl = 'True'

																		/*******************************************************
																		ACA REALIZAMOS EL INSERT FINAL EN EL AREA DE PRODUCCIÓN
																		LOS CAMPOS CORRESPONDIENTES BEGIN Y END FACTORING SE
																		GRABAN EN NULL YA QUE LAS FECHAS DE INICIO Y FIN SE
																		CARGAN CUANDO EL USUARIO ACEPTA EL TRABAJO
																		*******************************************************/
																		--AHORA VEMOS COMO PREGUNTAR POR SI EXISTE EL REGISTRO CON ANTELACION
																		--TENER EN CUANTA SOH_ID SOD_ID FS_ID ITEM_ID con esos 4 preguntar.

																		INSERT INTO tbFactory_SaleOrder4Factoring
																		(
																			comp_id,
																			-- ff_id -- this column value is auto-generated,
																			fs_id,
																			bra_id,
																			soh_id,
																			sod_id,
																			ff_dateOfFactoringAssigned,
																			ff_orderOfFactoring,
																			ff_isInFactoring,
																			user_id_4BeginFactoring,
																			ff_dateOfBeginFactoring,
																			user_id_4EndFactoring,
																			ff_dateOfEndFactoring,
																			ff_isFactored
																		)
																		VALUES
																		(
																			@comp_id,
																			@FactorySector,
																			@bra_id,
																			@soh_id,
																			@sod_id,
																			@lDate4Process,
																			@FactoryOrder,
																			'False',
																			NULL,
																			NULL,
																			NULL,
																			NULL,
																			'False'
																		)

																		SET @return_value = @@IDENTITY

																		--UNA VES REALIZADO EL INSERT, PROCEDEMOS A SALIR DEL BUCLE.
																		SET @lLoopControl = 'True'


																	END
																	--END DEL CUARTO IF

																ELSE
																	--SUMAMOS UN DÍA A LA FECHA Y LE SACAMOS LAS HORAS, MINUTOS Y SEGUNDOS
																	BEGIN
																		SET @lDate4Process = @lDate4Process + 1
																		SET @lDate4Process = dbo.fnGetEnd_or_BeginOfDate(@lDate4Process,'False')
																	END



															END
															--END DEL TERCER IF

														ELSE
															--SUMAMOS UN DÍA A LA FECHA Y LE SACAMOS LAS HORAS, MINUTOS Y SEGUNDOS
															BEGIN
																SET @lDate4Process = @lDate4Process + 1
																SET @lDate4Process = dbo.fnGetEnd_or_BeginOfDate(@lDate4Process,'False')
															END


													END
													--END DEL SEGUNDO IF

												ELSE
													--SUMAMOS UN DÍA A LA FECHA Y LE SACAMOS LAS HORAS, MINUTOS Y SEGUNDOS
													BEGIN
														SET @lDate4Process = @lDate4Process + 1
														SET @lDate4Process = dbo.fnGetEnd_or_BeginOfDate(@lDate4Process,'False')
													END


											END

											--END DEL PRIMER IF
											--
										ELSE
											--SUMAMOS UN DÍA A LA FECHA Y LE SACAMOS LAS HORAS, MINUTOS Y SEGUNDOS
											BEGIN
												SET @lDate4Process = @lDate4Process + 1
												SET @lDate4Process = dbo.fnGetEnd_or_BeginOfDate(@lDate4Process,'False')
											END



									END
									--END DEL WHILE
									--***************************************************************************************************************************************************************************


							-- próxima lectura del cursor
							FETCH	Cursor_AssingTurnByFactorySector
							INTO	@Item_Id,
									@FactorySector,
									@FactoryOrder,
									@FactoryDays,
									@MaxJobsByDay,
									@MaxTimeUnitsByDay
						END

						CLOSE Cursor_AssingTurnByFactorySector
						DEALLOCATE Cursor_AssingTurnByFactorySector


		END



GO







-------------------------------------------------------------------------------------------
--desc: Verificar que esten cerrados todos los trabajos anteriores
--date: 19/03/14
--author: GA
-------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spFactory_SaleOrder4Factoring_Pending]
(
	@comp_id			INT,
	@sod_id				INT,
	@fs_id				INT
)


AS

SET NOCOUNT ON

BEGIN


---------------------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@sod_id				INT,
			@fs_id				INT



SELECT 		@comp_id			= 1,
			@sod_id				= 22459,
			@fs_id				= 1
*/
---------------------------------------------------------------



DECLARE @lfs_id_Exist AS INT

SET @lfs_id_Exist = ( SELECT tfsof.fs_id
							  FROM tbFactory_SaleOrder4Factoring tfsof
							  WHERE   tfsof.comp_id  = @comp_id
								  AND tfsof.sod_id	 = @sod_id
								  AND tfsof.fs_id	 = @fs_id )

--SELECT @lfs_id_Exist

if @lfs_id_Exist IS NULL

BEGIN
		-- No existe ese sector para los turnos de ese pedido.
		SELECT 2	[PendingIsFactored]

END

ELSE
	BEGIN



	DECLARE @factory_Orden_Actual AS INT

	SET @factory_Orden_Actual = ( SELECT tfsof.ff_orderOfFactoring
								  FROM tbFactory_SaleOrder4Factoring tfsof
								  WHERE   tfsof.comp_id  = @comp_id
									  AND tfsof.sod_id	 = @sod_id
									  AND tfsof.fs_id	 = @fs_id )



			IF EXISTS	(	 SELECT tfsof.ff_orderOfFactoring

		         	 		 FROM tbFactory_SaleOrder4Factoring tfsof

		         	 		 WHERE tfsof.comp_id				= @comp_id
		         	 		 AND   tfsof.ff_orderOfFactoring	< @factory_Orden_Actual
		         	 		 AND   tfsof.ff_isFactored			= 'FALSE'


						)
							-- Hay trabajos pendientes de procesar.
							SELECT 1	[PendingIsFactored]

			ELSE
							-- No hay trabajos pendientes de procesar.
							SELECT 0	[PendingIsFactored]


	END

END



GO







create PROCEDURE [dbo].[spFactory_SaleOrder4Factoring_Process_getDataById]
(
	@comp_id	INT,
	@lang_id	INT,
	@sod_id		INT,
	@fs_id		INT
)


as

-------------------------------------------------------------
/*
DECLARE 		@comp_id	INT,
				@lang_id	INT,
				@sod_id		INT,
				@fs_id		INT


SELECT			@comp_id	= 1,
				@lang_id	= 2,
				@sod_id		= 22459,
				@fs_id		= 12
*/
-------------------------------------------------------------



	SET NOCOUNT ON

		BEGIN

			SELECT
					tfsof.fs_id,
					tfsof.bra_id,
					tfsof.fs_id,
					tfsof.soh_id,
					tfsof.sod_id,
					ISNULL(tfsof.ff_dateOfFactoringAssigned	,'')		[ff_dateOfFactoringAssigned],
					ISNULL(tfsof.ff_orderOfFactoring		,0 )		[ff_orderOfFactoring],
					ISNULL(tfsof.ff_isInFactoring			,'False')	[ff_isInFactoring],
					ISNULL(tfsof.user_id_4BeginFactoring	,'')		[user_id_4BeginFactoring],
					ISNULL(tfsof.ff_dateOfBeginFactoring	,'')		[ff_dateOfBeginFactoring],
					ISNULL(tfsof.user_id_4EndFactoring		,'')		[user_id_4EndFactoring],
					ISNULL(tfsof.ff_dateOfEndFactoring		,'')		[ff_dateOfEndFactoring],
					ISNULL(tfsof.ff_isFactored				,'False')	[ff_isFactored]	,
					ti.item_id,
					tc.cust_id



			FROM tbFactory_SaleOrder4Factoring				tfsof

				INNER JOIN tbSaleOrderHeader				tsoh
				ON  tsoh.comp_id	= tfsof.comp_id	AND
					tsoh.bra_id		= tfsof.bra_id	AND
					tsoh.soh_id		= tfsof.soh_id


				INNER JOIN tbSaleOrderDetail				tsod
				ON  tsod.comp_id	= tfsof.comp_id AND
					tsod.bra_id		= tfsof.bra_id	AND
					tsod.soh_id		= tfsof.soh_id	AND
					tsod.sod_id		= tfsof.sod_id


				INNER JOIN tbItem							ti
				ON  ti.comp_id = tsod.comp_id		AND
					ti.item_id = tsod.item_id

				INNER JOIN tbCustomer						tc
				ON  tc.comp_id = tsoh.comp_id		AND
					tc.cust_id = tsoh.cust_id


			WHERE	tfsof.comp_id		= @comp_id		AND
					tfsof.sod_id		= @sod_id		AND
					tfsof.fs_id			= @fs_id



		END




GO







-------------------------------------------------------------------------------------------
--desc: grabar fecha y hora que se cierra o abre .
--date: 19/03/14
--author: GA
-------------------------------------------------------------------------------------------



CREATE PROCEDURE [dbo].[spFactory_SaleOrder4Factoring_Processing]
(
	@comp_id			INT,
	@sod_id				INT,
	@IsBeginProcess		BIT,
	@IsEndProcess		BIT,
	@user_id			INT,
	@fs_id				INT


)

AS


SET NOCOUNT ON


BEGIN


---------------------------------------------------------------
/*
DECLARE 	@comp_id			INT,
			@sod_id				INT,
			@IsBeginProcess		BIT,
			@IsEndProcess		BIT,
			@user_id			INT,
			@fs_id				INT



SELECT 		@comp_id			=1 ,
			@sod_id				=22044,
			@IsBeginProcess		='False',
			@IsEndProcess		='True',
			@user_id			= 119 ,
			@fs_id				= 7

*/
---------------------------------------------------------------

DECLARE @status AS INT

SET @status = 0


DECLARE @lfs_id_Exist AS INT

SET @lfs_id_Exist = ( SELECT tfsof.fs_id
					  FROM tbFactory_SaleOrder4Factoring tfsof
					  WHERE   tfsof.comp_id  = @comp_id
						  AND tfsof.sod_id	 = @sod_id
						  AND tfsof.fs_id	 = @fs_id )

if @lfs_id_Exist IS NULL

BEGIN
		-- No existe ese sector para los turnos de ese pedido.
		SET @status = 3

END

ELSE

BEGIN

			DECLARE		@LisinFactoring AS BIT
			DECLARE		@LisFactored	AS BIT

			SET @LisinFactoring = ( SELECT  tfsof.ff_isInFactoring
									from tbFactory_SaleOrder4Factoring	tfsof
									WHERE	tfsof.comp_id	= @comp_id
									AND		tfsof.sod_id	= @sod_id
									AND		tfsof.fs_id		= @fs_id)


			SET @LisFactored = ( SELECT tfsof.ff_isFactored
								 from tbFactory_SaleOrder4Factoring		tfsof
								 WHERE tfsof.comp_id	= @comp_id
								 AND   tfsof.sod_id		= @sod_id
								 AND   tfsof.fs_id		= @fs_id )




			IF @IsBeginProcess = 'True'AND  @LisinFactoring = 'False'
			--Se selecciono la opcion Ingreso de proceso por ende se abre verificando que no este abierto
					begin
						 SET @status = 1
						 UPDATE tbFactory_SaleOrder4Factoring

						 SET	user_id_4BeginFactoring = @user_id,
 								ff_dateOfBeginFactoring = GETDATE(),
 								ff_isInFactoring		= 'True'

						 WHERE	comp_id = @comp_id	AND
								sod_id  = @sod_id	AND
								fs_id   = @fs_id



					end
			ELSE



				IF @IsBeginProcess = 'False' AND @LisinFactoring = 'True' AND  @LisFactored = 'False'
					--Se selecciono la opcion final de proceso por ende se cierra verificando que este abierto y no cerrado
							BEGIN

							 SET @status = 2

							 UPDATE		tbFactory_SaleOrder4Factoring

							 SET		user_id_4EndFactoring = @user_id,
 										ff_dateOfEndFactoring = GETDATE(),
 										ff_isFactored		  = 'True'

							 WHERE  comp_id = @comp_id	AND
									sod_id  = @sod_id	AND
									fs_id   = @fs_id

							END


END



-- @status = 0 -- No se grabo nada , ni abrio ni cerro proceso.
-- @status = 1 -- Grabo abriendo el proceso.
-- @status = 2 -- Grabo cerrando el proceso.
-- @status = 3 -- No existe tunro para ese sector de fabricacion

SELECT @status [Status]


END



GO




