(
	@comp_id	INT
)
AS

	SET NOCOUNT ON

		BEGIN

			SELECT
				tfs.fs_id			[Id],
				tfs.fs_desc			[Desc]
			FROM tbFactory_Sectors	tfs

			WHERE tfs.comp_id		= @comp_id

		END





GO





-- =============================================
-- Author:		MOS
-- Create date: 12-2010
-- Description:	Genera un ID x Compañia para
--				la Factura Electronica de
--				ARGENTINA.-
-- =============================================

CREATE PROCEDURE spFEIdNumber_GetNext
	@comp_id AS INT
AS

BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

-- --------------------------------------------------------
-- Testing
-- --------------------------------------------------------
/*
	DECLARE @comp_id AS INT
	SET @comp_id = 1
*/
-- --------------------------------------------------------

	DECLARE @return_Value AS INT

	EXEC spCounters_getNextValue
		@comp_id		= @comp_id,
		@auxiliary_id	= 0,
		@counter_id		= 150,
		@counter_value	= @return_Value output

	SELECT @return_Value

END
GO





