-- =============================================
-- Author:		GA
-- Create date: 10/08/2010
-- Description:	Versiones de Interfaz - FTP Sites
-- =============================================




CREATE PROCEDURE [dbo].[spFtpSites_getData]
(
		@comp_id		int,
		@bra_id			int
)
as
set nocount on


-- -----------------------------------------------------------------------------------------
-- datos de prueba
-- -----------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@bra_id			int


select	@comp_id		=1,
		@bra_id			=26
*/
-- -----------------------------------------------------------------------------------------
-- -----------------------------------------------------------------------------------------

BEGIN

select  ti.item_id														[cArtCod],
		ti.item_desc													[cArtDes],
		tc.cat_id														[cArtRub],
		tsc.subcat_id													[cArtSub],
		tsc.subcat_desc													[cArtSDe],
		tc2.curr_id														[cArtMo1],
		tpli.prli_price													[nArtPr1],
		''																[cArtMo2],
		''																[nArtPr2],
		''																[cArtMo3],
		''																[nArtPr3],
		''																[cArtMo4],
		''																[nArtPr4],
		''																[cArtMo5],
		''																[nArtPr5],
		''																[cArtMo6],
		''																[nArtPr6],
		''																[cArtMo7],
		''																[nArtPr7],
		''																[cArtMo8],
		''																[nArtPr8],
		''																[cArtMo9],
		''																[nArtPr9],
		''																[cArtMo0],
		''																[nArtPr0],
		dbo.fnGetAStock(ti.comp_id,ts.stor_id,ti.item_id,99999999)		[nArtStk],
		ti.item_annotation												[cArtNot],
		''																[cArtImg],
		ti.item_liquidation												[cArtOfe],
		ti.item_newness													[cArtNov],
		''																[nArtOrd],
		''																[dArtOrd],
		ti.item_annotation1												[cArtDLL],
		ti.item_weight													[nArtPes],
		''																[nArtPeU],
		''																[nArtDis],
		tb.brand_id														[nArtMar]

from tbItem ti

left join	tbBranch							br
on		br.comp_id			=	ti.comp_id
AND		br.bra_id			=	ti.bra_id

left join tbCategory							tc
on		tc.comp_id			=	ti.comp_id
AND		tc.cat_id			=	ti.cat_id

left join tbSubCategory							tsc
on		tsc.comp_id			=	ti.comp_id
AND		tsc.cat_id			=	ti.cat_id
AND		tsc.subcat_id		=	ti.subcat_id

left join tbBrand								tb
on		tb.comp_id			=	ti.comp_id
AND		tb.bra_id			=	ti.bra_id

inner join tbPriceListItems						tpli
on		tpli.comp_id		=   ti.comp_id
AND		tpli.item_id		=   ti.item_id

inner join tbsysCurrency						tc2
on		tc2.curr_id			=   tpli.curr_id

inner join tbStorage							ts
on		ts.comp_id			=   ti.comp_id



END


--marcas

select  tb.brand_id			[nMarCod],
		tb.brand_desc		[cMarDes],
		''					[fMarIma],
		''					[cMarLin],
		''					[cMarMue]

from tbBrand tb

--rubros
select  tc.cat_id			[cRubCod],
		tc.cat_desc			[cRubDes],
		''					[cRubIma],
		''					[cRubTex],
		''					[cRubVis]

from tbCategory tc


--subrubros
select  tsc.subcat_id		[cSubCod],
		tsc.subcat_desc		[cSubDes],
		''					[cSubCor],
		''					[cSubIma],
		''					[cSubTex]

from tbSubCategory tsc
GO

