CREATE PROCEDURE [dbo].[spGenericGrid_getDataCheckPortfolio2]
(
	@comp_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@user_id		INT,
	@lang_id		INT,
	@coption		INT,
	@custsupp		INT
)
AS



BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- --------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------
	/*
		DECLARE
			@comp_id		INT,
			@bra_id			INT,
			@prof_id		INT,
			@user_id		INT,
			@lang_id		INT,
			@coption		INT,
			@custsupp		INT

		SELECT
			@comp_id		= 1,
			@bra_id			= 1,
			@prof_id		= 1,
			@user_id		= 1,
			@lang_id		= 2,
			@coption		= 1,
			@custsupp		= 24454
	*/
	-- --------------------------------------------------------------










	DECLARE @bra_Credit_AssumeValuesAcreditDays AS INT
	SET @bra_Credit_AssumeValuesAcreditDays = 4
	SELECT @bra_Credit_AssumeValuesAcreditDays = tb.bra_Credit_AssumeValuesAcreditDays
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id
	SET @bra_Credit_AssumeValuesAcreditDays = @bra_Credit_AssumeValuesAcreditDays * -1


	SELECT
			tcp1.chp_number,
			tc.curr_symbol,
			tcp1.chp_total,		--**kHGF7789537 de VB
			tcp1.chp_PayDate,
			tbn.bn_name,
			CONVERT(BIT,
			CASE
				WHEN tcpm.svtt_id	= 40 AND IsNull(tcp1.chp_isNegociated,'False') = 'False'  THEN	'True'
				ELSE							'False'
			END		)									[IsDeposited],
			CONVERT(BIT,
			CASE
				WHEN tcp1.chp_isNegociated = 'True'  THEN	'True'
				ELSE							'False'
			END		)									[IsNegociated],
			CONVERT(BIT,
			CASE
				WHEN tcpm.svtt_id	= 30 THEN	'True'
				ELSE							'False'
			END		)									[IsPayed2Supplier],
			--tcpm.chpm_id,
			tcp1.chp_id									[ID]
		INTO #tmp
		FROM tbCheckPortfolio									tcp1


		INNER JOIN tbBranch										tb
		ON	tb.comp_id		= tcp1.comp_id					AND
			tb.bra_id		= tcp1.bra_id_PortFolio

		INNER JOIN tbsysCurrency								tc
		ON	tc.curr_id		= tcp1.curr_id

		INNER JOIN tbBanksName									tbn
		ON	tbn.comp_id		= tcp1.comp_id					AND
			tbn.country_id	= tcp1.country_id				AND
			tbn.bn_id		= tcp1.bn_id

		INNER JOIN tbCommercialTransactions						tct
		ON	tct.comp_id			= tcp1.comp_id				AND
			tct.ct_transaction	= tcp1.ct_transaction

		INNER JOIN tbUsers4BranchFilter							vubf
		ON	vubf.comp_id	= tcp1.comp_id					AND
			vubf.bra_id		= tcp1.bra_id					AND
			vubf.[user_id]	= @user_id

		LEFT JOIN tbCheckPortfolioMovements						tcpm    -- Para ver si es un cheque salido en una orden de pago a un proveedor.-
		ON	tcpm.comp_id		= tcp1.comp_id				AND
			tcpm.chp_id			= tcp1.chp_id				AND
			(tcpm.svtt_id		= 30 OR tcpm.svtt_id = 40)	AND -- Pago a Proveedores / DEPOSITADO
			tcpm.mm_isCancelled = 'False'


		WHERE tcp1.comp_id	= @comp_id		AND
			  tct.cust_id	= @custsupp		AND
			 (DATEDIFF(DAY,tb.bra_processingDate,tcp1.chp_PayDate) >= @bra_Credit_AssumeValuesAcreditDays)	AND
			  tcp1.chp_isRejected = 'false'	AND
			  tcp1.chp_isCancelled= 'False'

	ORDER BY tcp1.chp_PayDate DESC, tcpm.chpm_id DESC




	-- Borra Registros Duplicados
	;
	WITH CTE AS
	(
	   SELECT ID,
			  ROW_NUMBER() OVER(PARTITION BY ID ORDER BY ID) AS R
	   FROM #tmp
	)
	DELETE CTE WHERE R > 1;






	SELECT DISTINCT tmp.*
		FROM #tmp tmp
		ORDER BY tmp.chp_PayDate DESC


	DROP TABLE #tmp

END
GO



