CREATE PROCEDURE [dbo].[spGenericGrid_getDataCommercialTransactionsLoan]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,

	@ct_transaction		INT

)
AS

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- --------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------
	/*
	DECLARE
			@comp_id				INT,
			@lang_id				INT,
			@bra_id					INT,
			@prof_id				INT,
			@user_id				INT,

			@ct_transaction			INT

	SELECT
			@comp_id			= 1,
			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 1,
			@lang_id			= 2,
			@ct_transaction		= 26516
*/
	-- --------------------------------------------------------------




	SELECT
		tc.cust_name																						[cust_name],
		dbo.fnGetCommercialTransactionDescription(tct.comp_id,2,tct.ct_transaction)							[ct_docNumber],
		CASE
			WHEN tctl.comp_id IS NOT NULL THEN CONVERT(NVARCHAR(10),tctl.ctl_payNumber) + '/' + CONVERT(NVARCHAR(10),tctl.ctl_payNumberTotalQty)
			ELSE ''
		END																									[ctl_payNumberTotalQty],
		CASE
			WHEN tctl.comp_id IS NOT NULL THEN	tctl.ctl_payDate
			ELSE								tct.ct_payDate
		END																									[ct_payDate],

		-- Botones de la Transaccion
		ISNULL(tccvC.ccv_MPBotonDePagoLinkButton,'')														[ct_MPButtonURL],				-- Botón de Pago del Comprobante
		tccvC.ccv_MPexpiresOn																				[tct_ccv_MPPayDate],			-- Fecha de Vencimiento del Cupón (Comprobante)
		tccvC.ccv_MPPreference																				[tct_ccv_MPPreference],			-- Id de Preferencia (Comprobante)
		tccvC.ccv_id																						[tct_ccv_id],					-- Id de Cupón (Comprobante)
		tccvC.ccv_MPBotonDePagoIsTotalButton																[tct_ccv_isTotalButton],

		-- Botones de las Cuotas
		ISNULL(tccvL.ccv_MPBotonDePagoLinkButton,'')														[ctl_MPButtonURL],				-- Botón de Pago de la Cuota
		tccvL.ccv_MPexpiresOn																				[ccv_MPPayDate],				-- Fecha de Vencimiento del Cupón (Cuota)
		tccvL.ccv_MPPreference																				[ccv_MPPreference],				-- Id de Preferencia  (Cuota)
		tccvL.ccv_id																						[ccv_id],						-- Id de Cupón (Cuota)
		tccvL.ccv_MPBotonDePagoIsTotalButton																[ccv_isTotalButton]
		FROM tbCommercialTransactions						 AS	tct		WITH (NOLOCK)

		INNER JOIN tbCustomer								 AS tc		WITH (NOLOCK)
			ON	tc.comp_id = tct.comp_id						AND
				tc.cust_id = tct.cust_Id

		-- Vouchers de tbCommercialTransactions
		LEFT JOIN tbCreditCard_VoucherRelations 			 AS tccvrC	WITH (NOLOCK)
			ON	tccvrC.comp_id			= tct.comp_id			AND
				tccvrC.ct_transaction	= tct.ct_transaction	AND
				tccvrC.ctl_id			IS NULL
		LEFT JOIN tbCreditCard_Voucher						 AS tccvC   WITH (NOLOCK)
			ON	tccvC.comp_id	= tccvrC.comp_id				AND
				tccvC.ccv_id	= tccvrC.ccv_id

		LEFT JOIN tbCommercialTransactionsLoan AS				tctl	WITH (NOLOCK)
		ON	tctl.comp_id			= tct.comp_id				AND
			tctl.ct_transaction		= tct.ct_transaction

		-- Vouchers de tbCommercialTransactions
		LEFT JOIN tbCreditCard_VoucherRelations 			 AS tccvrL	WITH (NOLOCK)
			ON	tccvrL.comp_id			= tctl.comp_id			AND
				tccvrL.ct_transaction	= tctl.ct_transaction	AND
				tccvrL.ctl_id			= tctl.ctl_id
		LEFT JOIN tbCreditCard_Voucher						 AS tccvL   WITH (NOLOCK)
			ON	tccvL.comp_id	= tccvrL.comp_id				AND
				tccvL.ccv_id	= tccvrL.ccv_id
	WHERE	tct.comp_id				= @comp_id					AND
			tct.ct_transaction		= @ct_transaction			AND
			(
				(
					tccvC.ccv_MPBotonDePagoLinkButton <> ''		AND
					tccvC.ccv_MPBotonDePagoIsExpired = 0
				)
				OR
				(
					tccvL.ccv_MPBotonDePagoLinkButton <> ''		AND
					tccvL.ccv_MPBotonDePagoIsExpired = 0
				)
			)

END
GO






CREATE PROCEDURE [dbo].[spGenericGrid_getDataForRmaAndCheckPortfolio]
(
	@comp_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@user_id		INT,
	@lang_id		INT,
	@coption		INT,		-- @coption = 1 : Clientes @coption = 2 : Proveedores
	@custsupp		INT,
	@option			INT			-- @option = 1 : Rma Pendientes @option = 2 : Rma Resueltos
)
AS

BEGIN



	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	DECLARE @bra_Credit_AssumeValuesAcreditDays AS INT
	SET @bra_Credit_AssumeValuesAcreditDays = 4
	SELECT @bra_Credit_AssumeValuesAcreditDays = tb.bra_Credit_AssumeValuesAcreditDays
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id



	-- --------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------
	/*
		DECLARE
			@comp_id		INT,
			@bra_id			INT,
			@prof_id		INT,
			@user_id		INT,
			@lang_id		INT,
			@coption		INT,
			@custsupp		INT,
			@option			INT

		SELECT
			@comp_id		= 1,
			@bra_id			= 1,
			@prof_id		= 1,
			@user_id		= 1,
			@lang_id		= 2,
			@coption		= 1,
			@custsupp		= 24288,
			@option			= 3
	*/
	-- --------------------------------------------------------------

	--Dependiendo el boton que apreta, pasar 1 parametro que elija que Query ejecutar.

	IF @option = 1
		BEGIN

			--Rma Pendientes
			SELECT
				trt.srpt_desc,
				ti.item_cd,
				ti.item_desc,
				trd.rmad_qty,
				trd.rmad_Date_Reception													[reception_dateTime],
				ISNULL(tu.user_lastname,'') + ', ' + ISNULL(tu.user_firstname,'')		[reception_userName],
				ISNULL(tis.is_serial,'') [is_serial],
				convert(varchar,trh.rmah_id) + '-' + convert(varchar,trd.rmad_id) [ID]

			FROM tbRMA_Header								trh	WITH (NOLOCK)
				INNER JOIN tbRMA_Detail						trd	WITH (NOLOCK)
				ON trd.comp_id = trh.comp_id
				AND trd.rmah_id = trh.rmah_id
				INNER JOIN tbsysRMAProcType					trt	WITH (NOLOCK)
				ON trt.srpt_id = trd.srpt_id
				LEFT JOIN tbItem							ti	WITH (NOLOCK)
				ON ti.comp_id = trd.comp_id
				AND ti.item_id = trd.item_id
				LEFT JOIN tbItemSerials						tis	WITH (NOLOCK)
				ON tis.comp_id = trd.comp_id
				AND tis.is_id = trd.is_id
				INNER JOIN tbUsers4BranchFilter				vubf	WITH (NOLOCK)
					ON	vubf.comp_id	= trh.comp_id	AND
						vubf.bra_id		= trh.bra_id	AND
						vubf.[user_id]	= @user_id
				LEFT JOIN tbUser AS							tu	WITH (NOLOCK)
					ON tu.[user_id] = trd.user_id_Reception
			WHERE	trh.comp_id = @comp_id
			--AND		trh.bra_id	= @bra_id
			AND		trd.srpt_id = 1
			AND		(
						(@coption = 1 AND trh.cust_id = @custsupp) OR
						(@coption = 2 AND trh.supp_id = @custsupp)
					)

			ORDER BY ID, trt.srpt_desc

		END

	ELSE
		BEGIN
			IF @option = 2
				BEGIN
					--Rma Resueltos
							SELECT
								trt.srpt_desc,
								ti.item_cd,
								ti.item_desc,
								trd.rmad_qty,
								trd.rmad_Date_Proc														[process_dateTime],
								ISNULL(tu.user_lastname,'') + ', ' + ISNULL(tu.user_firstname,'')		[process_userName],
								ISNULL(tis.is_serial,'') [is_serial],
								convert(varchar,trh.rmah_id) + '-' + convert(varchar,trd.rmad_id) [ID]

							FROM tbRMA_Header						trh	WITH (NOLOCK)
								INNER JOIN tbRMA_Detail				trd	WITH (NOLOCK)
								ON trd.comp_id = trh.comp_id
								AND trd.rmah_id = trh.rmah_id
								INNER JOIN tbsysRMAProcType			trt	WITH (NOLOCK)
								ON trt.srpt_id = trd.srpt_id
								LEFT JOIN tbItem					ti	WITH (NOLOCK)
								ON ti.comp_id = trd.comp_id
								AND ti.item_id = trd.item_id
								LEFT JOIN tbItemSerials				tis	WITH (NOLOCK)
								ON	tis.comp_id		= trd.comp_id		AND
									tis.is_id		= trd.is_id
								LEFT JOIN tbUser AS					tu	WITH (NOLOCK)
									ON	tu.[user_id]	= trd.user_id_Proc
    							INNER JOIN tbUsers4BranchFilter		vubf WITH (NOLOCK)
									ON	vubf.comp_id	= trh.comp_id	AND
										vubf.bra_id		= trh.bra_id	AND
										vubf.[user_id]	= @user_id

							WHERE	trh.comp_id = @comp_id
							--AND		trh.bra_id	= @bra_id
							AND		trd.srpt_id <> 1
							AND		(
										(@coption = 1 AND trh.cust_id = @custsupp) OR
										(@coption = 2 AND trh.supp_id = @custsupp)
									)

							ORDER BY ID, trt.srpt_desc

				END
			ELSE
				BEGIN
					--Valores en Cartera NO pagos
					SELECT
						tcp1.chp_number,
						tc.curr_symbol,
						tcp1.chp_total,   -- NO CAMBIAR EL ORDEN, SINO TOCAR EN: **kHGF7789536 del VB
						tcp1.chp_PayDate,
						tbn.bn_name,
						CONVERT(BIT,
						CASE
						    WHEN tcpm.svtt_id	= 40 AND IsNull(tcp1.chp_isNegociated,'False') = 'False'  THEN	'True'
						    ELSE							'False'
						END		)									[IsDeposited],
						CONVERT(BIT,
						CASE
						    WHEN tcp1.chp_isNegociated = 'True'  THEN	'True'
						    ELSE							'False'
						END		)									[IsNegociated],
						CONVERT(BIT,
						CASE
						    WHEN tcpm.svtt_id	= 30 THEN	'True'
						    ELSE							'False'
						END		)									[IsPayed2Supplier],
						ISNULL(tcp1.chp_isElectronic,'False')		[chp_isElectronic],
						tcp1.chp_id	[ID]
						into #tmp
						FROM tbCheckPortfolio					tcp1	WITH (NOLOCK)

						INNER JOIN tbBranch						tb	WITH (NOLOCK)
							ON	tb.comp_id	= tcp1.comp_id AND
								tb.bra_id	= tcp1.bra_id_PortFolio

						INNER JOIN tbsysCurrency				tc	WITH (NOLOCK)
						ON	tc.curr_id		= tcp1.curr_id

						INNER JOIN tbBanksName					tbn	WITH (NOLOCK)
						ON	tbn.comp_id		= tcp1.comp_id
						AND tbn.country_id	= tcp1.country_id
						AND tbn.bn_id		= tcp1.bn_id

						INNER JOIN tbCommercialTransactions		tct	WITH (NOLOCK)
						ON	tct.comp_id			= tcp1.comp_id			AND
							tct.ct_transaction	= tcp1.ct_transaction

						INNER JOIN tbUsers4BranchFilter vubf	WITH (NOLOCK)
							ON	vubf.comp_id	= tcp1.comp_id	AND
								vubf.bra_id		= tcp1.bra_id	AND
								vubf.[user_id]	= @user_id

						LEFT JOIN tbCheckPortfolioMovements tcpm  	WITH (NOLOCK)  -- Para ver si es un cheque salido en una orden de pago a un proveedor.-
									ON		tcpm.comp_id		= tcp1.comp_id
										AND tcpm.chp_id			= tcp1.chp_id
										AND (tcpm.svtt_id		= 30 OR tcpm.svtt_id = 40)  -- Pago a Proveedores / DEPOSITADO
										AND tcpm.mm_isCancelled = 'False'
										AND DATEDIFF(DAY,tb.bra_processingDate,tcp1.chp_PayDate) > @bra_Credit_AssumeValuesAcreditDays --7


						WHERE tcp1.comp_id					= @comp_id													AND
							((@coption = 1 AND tct.cust_id	= @custsupp) OR (@coption = 2 AND tct.supp_id = @custsupp))	AND
							(
								(
								 (tcp1.chp_isAvailable= 'True'	OR (tcp1.chp_isAvailable= 'False' AND tcp1.chp_IsPayed		= 'True' AND tcp1.chp_isNegociated = 'True' ))							AND
								 (tcp1.chp_IsPayed	  = 'False'	OR (tcp1.chp_IsPayed	= 'True'  AND tcp1.chp_isNegociated	= 'True' AND DATEDIFF(DAY,tb.bra_processingDate,tcp1.chp_PayDate) > @bra_Credit_AssumeValuesAcreditDays /*2*/))	AND
								  tcp1.chp_isRejected = 'false'																AND
								  tcp1.chp_isCancelled= 'False'
								)
								OR
								(NOT tcpm.chp_id IS NULL)	-- MOS: 01-2011   esto puede hacer que demoreeeeee
							)
					ORDER BY tcp1.chp_PayDate DESC


					-- Borra Registros Duplicados
					;
					WITH CTE AS
					(
					   SELECT ID,
							  ROW_NUMBER() OVER(PARTITION BY ID ORDER BY ID) AS R
					   FROM #tmp
					)
					DELETE CTE WHERE R > 1;


					SELECT DISTINCT *
						FROM #tmp
					ORDER BY chp_PayDate DESC

				END
		END


END
GO





