CREATE PROCEDURE [dbo].[spGenericGrid_getDataItemPartsChecking]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@user_id		INT,

	@guid			UNIQUEIDENTIFIER

)
AS

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- --------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------
	/*
		DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@bra_id			INT,
				@prof_id		INT,
				@user_id		INT,

				@guid			UNIQUEIDENTIFIER

		SELECT
				@comp_id		= 1,
				@bra_id			= 1,
				@prof_id		= 1,
				@user_id		= 1,
				@lang_id		= 2,
				@guid			= 'DA4961C6-25DD-46FF-BBA1-F8C0086BFE62'

		*/
	-- --------------------------------------------------------------




	SELECT  ' '										[ ],
			' '										[ ],
			tipct.itp_EAN							[itp_EAN],
			(SELECT top 1 isnull(tip.itp_desc,'')
	        FROM tbItemParts	tip
	        where tip.itp_EAN = tipct.itp_EAN)		[itp_desc],
			tipct.ipc_qtyChequed					[ipc_qtyChequed],
			tipct.ipc_qtyConfirmed					[ipc_qtyConfirmed],
			tipct.ipc_cd							[ipc_cd],
			tipct.ipc_id							[ID]


	FROM tbItemPartsCheckingTable				tipct	WITH (NOLOCK)

	WHERE tipct.ipc_guid	= @guid



END
GO







CREATE procedure [dbo].[spGenerics_exec]
(
	@query				ntext
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE @dateOfBegin AS DATETIME
	DECLARE @dateOfEnd   AS DATETIME
	DECLARE @intSeconds  AS INT
	SET		@intSeconds	 = 0
	SET		@dateOfBegin = GETDATE()

	exec (@query)

	SET		@dateOfEnd   = GETDATE()
	SET		@intSeconds  = DATEDIFF(second , @dateOfBegin, @dateOfEnd)



	IF @intSeconds > 8
		BEGIN
			INSERT INTO tbGenerics_ExecLog([query], dateBegin, dateEnd, secondsOfExec)
				VALUES(@query, @dateOfBegin, @dateOfEnd, @intSeconds)
		END

END

--SET NOCOUNT ON










GO







CREATE  procedure [dbo].[spGenerics_execQuery]
(
	@query				varchar(8000),
	@action				char(1),
	@table				varchar(100),
	@where				varchar(8000),
	@errormessage		varchar(200)
)
as

declare @return_value	int

/*
declare		@query			varchar(8000),
			@action			char(1),
			@table			varchar(100),
			@where			varchar(8000)
select		@query			= 'delete tMonedas cc',
			@action			= 'D',
			@table			= 'tMonedas',
			@where			= '[comp_id] = ''' + '1' + ''' and [mone_id] = ''' + '294934' + ''''
select		@query,
			@action,
			@table,
			@where
*/

if (upper(@action) = 'U' or upper(@action) = 'D') and @where <> ''

--este begin se ejecuta por update y delete por lo tanto debe venir informado el @where
begin
--	declare		@select varchar(100)
--	set			@select = 'select 1 from ' + @table + ' where ' + @where
--	--select		@select
--
--	-- validación de existencia del registro a mpdificar o eliminar
--	exec		(@select)
--	if @@ROWCOUNT = 1
--	begin
		--si existe el registro se ejecuta el update o delete
		exec (@query + ' where ' + @where)
--		SET NOCOUNT off
--		--set @errormessage = 'Successfully operation'
--		return 0
--	end
--	else
--	begin
--		SET NOCOUNT off
--		--set @errormessage = '9999'
--		return 99
--	end
end


else

--este begin se ejecuta por insert
begin
	exec (@query)
end



SET @return_value = @@Error

-- Error validation
IF (@return_value = 0)
	BEGIN
		SET @errormessage = 'Execution Successfully'
		if (upper(@action) = 'I')
			begin
				SET @return_value = @@identity
			end
		else
			begin
				SET @return_value = 0
			end
	END
ELSE
	BEGIN
		SET @errormessage = 'Execution Failed'
		--SET @return_value = 0
	END

-- ****************************************************************************
-- RETURN
-- ****************************************************************************
SET NOCOUNT OFF
RETURN (@return_value)










GO








