CREATE  procedure [dbo].[spGenerics_getFilters]
(
	@lang_id		int,
	@table_desc		varchar(100),		-- Evidentemente sos un ENFERMO HIJO DE RE MIL PUTAS !!!!!!!!!!!!!!!!!!
	@country_id		INT,
	@ERPVersion		INT,
	@ERPModules			VARCHAR(500)
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on
	--Obtiene los datos necesarios para armar los filtros de la tabla recibida como parámeto
	--en el lunguaje solicitado
	------------------------------------------------------------------------
	---  ACTUALIZADO CON tbSysNamesNew 26/02/2010---------------------------
	------------------------------------------------------------------------

	/*
	declare	@lang_id			int,
			@table_desc			varchar(100),
			@country_id			int
	select	@lang_id			= 2,
			@table_desc			= '40',	 --'tbSysPrueba'
			@country_id			= 1
	*/



	-- pOR el FORRO
	-- Hacer de nuevo esto pls!
	DECLARE @tmpERPModules				TABLE (smod_id INT NULL UNIQUE CLUSTERED)




	if convert(bit,isnumeric(@table_desc)) = 'True'   -- SOS UN HIJO DE RECONTRRA RE MIL PUTAS, ENFERMO DE MIERDA, FORRO, ME CAGASTE AL DECIR QUE SABIAS ALGO FORRRRRRROOOOOOOOOOOOOOOO

		BEGIN

			-- ATENCION, tambien mas ABAJO!!!!
			-- -------------------------------------------
			-- Pone en la temporal los modulos que fueron
			-- adquiridos para poder sacar de
			-- tbSysNamesNew solo los campos que necesita
			-- -------------------------------------------
			--DECLARE @tmpERPModules				TABLE (smod_id INT NULL UNIQUE CLUSTERED)
			INSERT INTO @tmpERPModules(	smod_id)
				SELECT fst.items
					FROM dbo.fnSplitTable(@ERPModules, ',') fst
			INSERT INTO @tmpERPModules VALUES (-2)

			SELECT tnn.table_id, tnn.name_id, tnn.tab_id, tnn.field_id, tnn.[type_id],
				   tnn.name_desc_id, tnn.name_join, tnn.name_combo, tnn.name_comboact,
				   tnn.name_errormessage_id, tnn.name_errormessage2_id, tnn.ctrl_id,
				   tnn.prop_id, tnn.country_id, tnn.RegExp,
				   tnn.sevt_id_Enabled4ThisVersion, tnn.sevt_id_Disabled4ThisVersion,
				   tnn.name_boxed, tnn.name_lineUp, tnn.name_lineDown, tnn.name_tabHeader,
				   tnn.name_tabFooter, tnn.name_tabHeaderColor, tnn.name_tabFooterColor,
				   tnn.name_disableValidator,
				   tnn.smod_id4DisableIfNotPurchased,
				   tnn.smod_id4NotVisibleIfNotPurchased,
				   tnn.smod_id4VisibleIfNotPurchased
				INTO #tbsysNamesNew
				FROM tbsysNamesNew tnn
				INNER JOIN @tmpERPModules tmpMV
					ON tmpMV.smod_id = tnn.smod_id4NotVisibleIfNotPurchased
				WHERE tnn.table_id = @table_desc																	AND
			 ( tnn.sevt_id_Enabled4ThisVersion	   IS NULL OR tnn.sevt_id_Enabled4ThisVersion	=  @ERPVersion )	AND
			 ( tnn.sevt_id_Disabled4ThisVersion    IS NULL OR tnn.sevt_id_Disabled4ThisVersion	<> @ERPVersion )


			DELETE FROM #tbsysnamesnew
				FROM #tbsysnamesnew tsnn
				LEFT JOIN @tmpERPModules tmp
					ON	tmp.smod_id = tsnn.smod_id4VisibleIfNotPurchased
				WHERE	tmp.smod_id <> -2 AND
						tmp.smod_id IS NOT NULL
			-- -------------------------------------------


				--select 1
			select 	f.field_name			, --[Name],		--nombre físico del campo en tabla
					f.field_order			, --[Order],	--número de orden de filtro a mostrar
					f.field_type			, --[Type],		--tipo de campos a filtrar
					f.field_lenght			, --[Lenght],	--longitud del campo a filtrar (char y varchar)
					--n.name_desc,
					n.name_combo			, --[Query],	--query para obtener las opciones para el campo
					--n.name_column			, --[Label],	--descripción a mostrar en label de filtro
					isnull(tswn.word_desc,'')	[name_column],
					f.field_function		, --[Function]
					n.name_comboact			,
					isnull(f.field_nullenable,'false')		[field_nullenable],
					n.tab_id,
					ISNULL(
						(
							SELECT TOP 1 tswn.word_desc
								FROM tbsysNamesNew tnn				WITH (NOLOCK)
								INNER JOIN tbSysWordsNew tswn		WITH (NOLOCK)
									ON	tswn.lang_id	= @lang_id AND
										tswn.wordsi_id	= tnn.name_desc_id
								WHERE	tnn.table_id	= t.table_id	AND
										tnn.tab_id		= n.tab_id		AND
										tnn.[type_id]	= 8
						)
					,'*')										[tabName]


				from 	tbSysTables							t		WITH (NOLOCK)

						inner join tbSysFields				f		WITH (NOLOCK)
						on 		f.table_id	= t.table_id

						inner join #tbSysNamesNew  			n		WITH (NOLOCK)
						on 		n.field_id	= f.field_id

						--INNER JOIN @tmpERPModules tmpM
						--	ON tmpM.smod_id = n.smod_id4NotVisibleIfNotPurchased


						LEFT JOIN tbSysWordsNew				tswn	WITH (NOLOCK)
						ON tswn.lang_id		= @lang_id
						AND tswn.wordsi_id	= n.name_desc_id

						LEFT JOIN tbsysTabs tt
							ON tt.tab_id = n.tab_id



				where 	t.table_id			= @table_desc
				--and		n.lang_id 			= @lang_id
				and		f.field_mrc_filter	= 'true'
				and     ( n.country_id is null or n.country_id = @country_id)										--	AND
					 --   ( n.sevt_id_Enabled4ThisVersion	IS NULL OR n.sevt_id_Enabled4ThisVersion	=  @ERPVersion )	AND
						--( n.sevt_id_Disabled4ThisVersion IS NULL OR n.sevt_id_Disabled4ThisVersion	<> @ERPVersion )
				order by	CASE
								WHEN f.field_type = 'ID'		THEN -1
								ELSE tt.tab_order --n.tab_id
							END	,f.field_order ASC


		end

	ELSE	-- HIJO DE PUTAAAAAAAAAAAAAAA

		begin
			--select 2

			-- ATENCION, tambien mas ARRIBA!!!!
			-- -------------------------------------------
			-- Pone en la temporal los modulos que fueron
			-- adquiridos para poder sacar de
			-- tbSysNamesNew solo los campos que necesita
			-- -------------------------------------------

			INSERT INTO @tmpERPModules(	smod_id)
				SELECT fst.items
					FROM dbo.fnSplitTable(@ERPModules, ',') fst
			INSERT INTO @tmpERPModules VALUES (-2)

			SELECT tnn.table_id, tnn.name_id, tnn.tab_id, tnn.field_id, tnn.[type_id],
				   tnn.name_desc_id, tnn.name_join, tnn.name_combo, tnn.name_comboact,
				   tnn.name_errormessage_id, tnn.name_errormessage2_id, tnn.ctrl_id,
				   tnn.prop_id, tnn.country_id, tnn.RegExp,
				   tnn.sevt_id_Enabled4ThisVersion, tnn.sevt_id_Disabled4ThisVersion,
				   tnn.name_boxed, tnn.name_lineUp, tnn.name_lineDown, tnn.name_tabHeader,
				   tnn.name_tabFooter, tnn.name_tabHeaderColor, tnn.name_tabFooterColor,
				   tnn.name_disableValidator,
				   tnn.smod_id4DisableIfNotPurchased,
				   tnn.smod_id4NotVisibleIfNotPurchased,
				   tnn.smod_id4VisibleIfNotPurchased
				INTO #tbsysNamesNew2
				FROM tbsysNamesNew tnn
				INNER JOIN tbsysTables tt
					ON tt.table_id = tnn.table_id
				INNER JOIN @tmpERPModules tmpMV
					ON tmpMV.smod_id = tnn.smod_id4NotVisibleIfNotPurchased
				WHERE tt.table_desc  = @table_desc

			DELETE FROM #tbsysnamesnew2
				FROM #tbsysnamesnew2 tsnn
				LEFT JOIN @tmpERPModules tmp
					ON	tmp.smod_id = tsnn.smod_id4VisibleIfNotPurchased
				WHERE	tmp.smod_id <> -2 AND
						tmp.smod_id IS NOT NULL
			-- -------------------------------------------

			select 	f.field_name			, --[Name],		--nombre físico del campo en tabla
					f.field_order			, --[Order],	--número de orden de filtro a mostrar
					f.field_type			, --[Type],		--tipo de campos a filtrar
					f.field_lenght			, --[Lenght],	--longitud del campo a filtrar (char y varchar)
					--n.name_desc,
					n.name_combo			, --[Query],	--query para obtener las opciones para el campo
					--n.name_column			, --[Label],	--descripción a mostrar en label de filtro
					isnull(tswn.word_desc,'')	[name_column],
					f.field_function		, --[Function]
					n.name_comboact			,
					isnull(f.field_nullenable,'false')		[field_nullenable],
					n.tab_id,
					ISNULL(
						(
							SELECT TOP 1 tswn.word_desc
								FROM tbsysNamesNew tnn				WITH (NOLOCK)
								INNER JOIN tbSysWordsNew tswn		WITH (NOLOCK)
									ON	tswn.lang_id	= @lang_id AND
										tswn.wordsi_id	= tnn.name_desc_id
								WHERE	tnn.table_id	= t.table_id	AND
										tnn.tab_id		= n.tab_id		AND
										tnn.[type_id]	= 8
						)
					,'*')										[tabName]


			from 	tbSysTables							t		WITH (NOLOCK)

					inner join tbSysFields				f		WITH (NOLOCK)
					on 		f.table_id	= t.table_id

					inner join #tbSysNamesNew2			n		WITH (NOLOCK)
					on 		n.field_id	= f.field_id

					LEFT JOIN tbSysWordsNew				tswn		WITH (NOLOCK)
					ON tswn.lang_id		= @lang_id
					AND tswn.wordsi_id	= n.name_desc_id

			where 	t.table_desc		= @table_desc
			--and		n.lang_id 			= @lang_id
			and		f.field_mrc_filter	= 'true'
			and     ( n.country_id is null or n.country_id = @country_id)	AND
					( n.sevt_id_Enabled4ThisVersion	IS NULL OR n.sevt_id_Enabled4ThisVersion	=  @ERPVersion )	AND
					( n.sevt_id_Disabled4ThisVersion IS NULL OR n.sevt_id_Disabled4ThisVersion	<> @ERPVersion )
			order by
					CASE
						WHEN f.field_type = 'ID'		THEN -1
						ELSE n.tab_id
					END	,f.field_order ASC


		end



END
GO



CREATE  procedure [dbo].[spGenerics_getImage]
(
	@comp_id			int,
	@lang_id			int,
	@table_id			int,
	@fields_filter		varchar(1000)
)
as



BEGIN




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	set nocount ON
	------------------------------------------------------------------------
	-- MOS
	------------------------------------------------------------------------



	-- --------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------
	/*
	declare	@comp_id		int,
			@lang_id		int,
			@table_id		int,
			--@fields_order	varchar(1000),
			@fields_filter	varchar(1000)--,
			--@top_filter		int
	select	@comp_id		= 1,
			@lang_id		= 2,
			@table_id		= 538,
			@fields_filter	= '[mls_id]=13'
	*/
	-- --------------------------------------------------------------------

--SELECT @fields_filter


	/*************************************************************************************************
	Generic procedure to get needed data for managed table
	Table 0 - get data from managed table to show on gridviews
	Table 1 - get properties and names for managed table fields
	Table 2 - get user name from manged table to show on pages
	*************************************************************************************************/




	/*************************************************************************************************
	Table 0 - get data from managed table to show on gridviews with language translate
	*************************************************************************************************/
	declare	@query				varchar(8000),
			@name_desc			varchar(1000),
			@name_join			varchar(5000),
			@field_function		char(1),
			@field_type			char(2),
			@name_field			varchar(200)



	-- generate dynamic query to get data from managed table


	declare @table_desc		varchar(100)
	select	@table_desc = table_desc from tbSysTables where table_id = @table_id


	select @query = 'select '

	-- cursor with properties and names from managed table fields
	-- NO USAR FAST FORWARD !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
	declare cursor_G_gI_names CURSOR    for
	select 	@table_desc + '.' + f.field_name	[name_field],
			--' [' + n.name_desc + ']'
			' [' + tswn.word_desc + ']'			[name_desc],
			n.name_join,
			f.field_function,
			f.field_type

	from 	tbSysTables					t				WITH (NOLOCK)
			inner join tbSysFields		f				WITH (NOLOCK)
				on 		f.table_id		= t.table_id
			inner join tbSysNamesNew	n				WITH (NOLOCK)
				on 		n.table_id		= t.table_id
				and		n.field_id		= f.field_id
			LEFT JOIN tbSysWordsNew tswn				WITH (NOLOCK)
				ON tswn.lang_id			= @lang_id
				AND tswn.wordsi_id		= n.name_desc_id
	where 	t.table_id				= @table_id
	--and		n.lang_id 				= @lang_id
	--and		f.field_visible			= 'True'
	and		f.[field_type]			= 'IM'

	order by f.field_order


	-- drive cursor
	open cursor_G_gI_names

	IF @@CURSOR_ROWS > 0
		begin



			-- get first record from cursor
			FETCH	NEXT  FROM cursor_G_gI_names
				INTO	@name_field, @name_desc, @name_join, @field_function, @field_type

			-- control end cursor
			WHILE @@FETCH_STATUS = 0
			BEGIN

				-- evaluate managed table field function, 'C'=Constraint, 'F'=Foreign Key
				if @field_function = 'D'
					BEGIN
						-- set fisical field names
						select @query =	@query + @name_field + @name_desc + ', '
					END

				-- get next record from cursor
				FETCH NEXT FROM cursor_G_gI_names
	  				INTO 	@name_field, @name_desc, @name_join, @field_function, @field_type

			END
			close		cursor_G_gI_names
			deallocate	cursor_G_gI_names

			-- delete last ',' and add 'from' and fisical managed table name to dynamic query
			set @query = substring(@query,1,len(@query)-1) + ' from ' + @table_desc


			-- if there is filter fields add it
			if len(@fields_filter) > 0 set @query = @query + ' where ' + @fields_filter

			-- replace '@comp_id' parameter with value informed
			select @query = replace(@query, '@comp_id', convert(varchar,(select @comp_id)))

			-- execute dynamic query to get real data from managed table

			exec (@query)

		END
	ELSE
		BEGIN
			close		cursor_G_gI_names
			deallocate	cursor_G_gI_names
		END



	/*************************************************************************************************
	end Table 0 -
	*************************************************************************************************/


END



GO










