CREATE PROCEDURE [dbo].[spGenerics_getTabs]
(
	@lang_id			int,
	@table_desc			varchar(100)
)
as


set nocount on

/*
declare	@lang_id		int,
		@table_desc		varchar(100)
select	@lang_id		= 2,
		@table_desc		= 'tbCostCenter'
*/


declare @type_id			int
select	@type_id			= 8		--tipo Tabs
declare @typeFields_id		int
