select	t.tab_id                    [tab],
		t.tab_order					[order],
		isnull(n.name_desc,'')		[desc]

from	tbSysTables					tb			WITH (NOLOCK)

		inner join tbSysTabs		t			WITH (NOLOCK)
		on	t.table_id	= tb.table_id

		inner join	tbSysNames		n			WITH (NOLOCK)
		on	n.table_id	= tb.table_id
		and	n.tab_id	= t.tab_id

where	tb.table_desc	= @table_desc
and		n.lang_id		= @lang_id
and		n.type_id		= @type_id

and		t.tab_id		in (select	distinct n.tab_id
							from	tbSysNames	n
							where	n.table_id	=	tb.table_id
							and		n.type_id	=	@typeFields_id)


order by t.tab_order


/*
