select	t.tab_id
from	tbSysTables				tb
		inner join tbSysTabs	t
		on	t.table_id	= tb.table_id
where	tb.table_desc	= @table_desc
and		t.tab_id		in (select	distinct n.tab_id
							from	tbSysNames	n
							where	n.table_id	=	tb.table_id
							and		n.type_id	=	@type_id)

*/




GO







CREATE PROCEDURE [dbo].[spGenerics_ValidateData]
(
	@comp_id		INT,
	@table_id		INT,
	@prof_id		INT,
	@id				INT,
	@where			VARCHAR(8000),
	@return_value	INT OUTPUT
)
AS

SET NOCOUNT ON
/*
DECLARE @comp_id		INT,
		@table_id		INT,
		@prof_id		INT,
		@id				INT,
		@where			VARCHAR(8000),
		@return_value	int

SELECT  @comp_id		=1,
		@table_id		=60,
		@prof_id		=1,
		@id				=4--,
		--@return_value int

DROP TABLE #tmp
*/


DECLARE @query VARCHAR(8000)
SET @query = 'select 1'

SELECT	@query = ttpv.validationText
FROM	tbTableProfileValidations ttpv
WHERE	ttpv.comp_id	= @comp_id
AND		ttpv.table_id	= @table_id
AND		ttpv.prof_id	= @prof_id

--SELECT	@query


CREATE TABLE #tmp ( _value INT )

SET @query = REPLACE(@query,'@comp_id',CONVERT(VARCHAR,@comp_id))
SET @query = REPLACE(@query,'@id',CONVERT(VARCHAR,@id))

IF @where <> ''
BEGIN
	SET @query = SUBSTRING(@query,0,CHARINDEX('where',@query,0)+6) + @where
END

--SELECT @query


BEGIN TRANSACTION T2
BEGIN TRY

	INSERT INTO #tmp (_value)
	EXEC ('IF EXISTS ( ' + @query + ' ) select 1 else select 0 ')
	SELECT @return_value = _value FROM #tmp
	COMMIT TRANSACTION T2

END TRY
BEGIN CATCH
	SET @return_value = -1
	ROLLBACK TRANSACTION T2
END CATCH


--SELECT @return_value





GO





-- NO SE USA MAS EN NINGUN LADO!!


CREATE PROCEDURE [dbo].[spGenerics2_getData]
(
	@comp_id			int,
	@lang_id			int,
	@table_id			int,
	@fields_order		varchar(1000),
	@fields_filter		varchar(1000),
	@country_id			int,
	@top_filter			int
)
as

set nocount on

/*
declare	@comp_id		int,
		@lang_id		int,
		@table_id		int,
		@fields_order	varchar(1000),
		@fields_filter	varchar(1000),
		@top_filter		INT

select	@comp_id		= 1,
		@lang_id		= 2,
		@table_id		= 17,
		@fields_order	= '', --[Dato Varchar] asc, [Dato DateTime] asc', --'[Dato DateTime] desc',
		@fields_filter	= '',
		@top_filter		= -1
*/


/*************************************************************************************************
Generic procedure to get needed data for managed table
Table 0 - get data from managed table to show on gridviews
Table 1 - get properties and names for managed table fields
Table 2 - get user name from manged table to show on pages
*************************************************************************************************/




/*************************************************************************************************
Table 0 - get data from managed table to show on gridviews with language translate
*************************************************************************************************/

declare	@query				varchar(8000),
		@query1				varchar(8000),
		@query2				varchar(8000),
		@name_desc			varchar(1000),
		@name_join			varchar(5000),
		@field_function		char(1),
		@field_type			char(2),
		@name_field			varchar(200),
		@field_name			varchar(200),
		@position			int,
		@length				int,
		@ids				varchar(8000)

select @ids = ' , ''Id=''+'

-- generate dynamic query to get data from managed table


declare @table_desc		varchar(100)
select @table_desc = table_desc from tbSysTables where table_id = @table_id
--select @table_desc




-- two empty columns to add update and delete buttons on page code
if @top_filter = -1
	select @query = 'select  '' '' [ ], '' '' [ ], '
else
	select @query = 'select top ' + convert(varchar(6),@top_filter) + ' '' '' [ ], '' '' [ ], '



-- cursor with properties and names from managed table fields
declare cursor_G2_gD_names CURSOR LOCAL FAST_FORWARD FOR
select 	@table_desc + '.' + f.field_name	name_field,
		' [' + n.name_desc + ']'			name_desc,
		n.name_join,
		f.field_function,
		f.field_type,
		f.field_name

from 	tbSysTables				t				WITH (NOLOCK)

		inner join tbSysFields	f				WITH (NOLOCK)
		on 		f.table_id		= t.table_id

		inner join tbSysNames 	n				WITH (NOLOCK)
		on 		n.table_id		= t.table_id
		and		n.field_id		= f.field_id

where 	t.table_id				= @table_id
and		n.lang_id 				= @lang_id
and		f.field_visible			= 'True'

order by f.field_order





-- drive cursor
open cursor_G2_gD_names

IF @@CURSOR_ROWS > 0
begin

	-- get first record from cursor
	FETCH	NEXT FROM cursor_G2_gD_names
	INTO	@name_field, @name_desc, @name_join, @field_function, @field_type, @field_name


	-- control end cursor
	WHILE @@FETCH_STATUS = 0
	BEGIN

		-- evaluate managed table field function, 'C'=Constraint, 'F'=Foreign Key
		if @field_function <> 'C' and @field_function <> 'F' and @field_function <> 'P'
		begin

			-- set fisical field names
			select @query =
				@query +
					case
						when @field_type = 'DA' then ' convert(varchar,' + @name_field + ', 103)'
						when @field_type = 'TI' then ' convert(varchar,' + @name_field + ', 108)'
						when @field_type = 'DT' then ' convert(varchar,' + @name_field + ', 103) +'' ''+'+' convert(varchar,' + @name_field + ', 108)'
						when @field_type = 'IM' then '''  '''
						else @name_field
					end
						+ @name_desc + ', '

		end


		-- evaluate if name join is informed
		if not @name_join is null and len(rtrim(ltrim(@name_join))) > 0
		begin
			select @query = @query + @name_join + ', '
			if @field_function = 'P'
			begin
				--select @ids = @ids + '''' + @field_name + '=''+cast(' + @field_name + ' as varchar(9)) + '' and '' +'
				select @ids = @ids + 'cast(' + @field_name + ' as varchar(9)) + '','' +'
			end
		end


		-- get next record from cursor
		FETCH NEXT FROM cursor_G2_gD_names
  		INTO 	@name_field, @name_desc, @name_join, @field_function, @field_type, @field_name

	END


	-- delete last ',' and add 'from' and fisical managed table name to dynamic query
	set @query = substring(@query,1,len(@query)-1) + substring(@ids,1,len(@ids)-7) + ' [ID]' + ' from ' + @table_desc


	-- if there is filter fields add it
	if len(@fields_filter)		> 0 set @query = @query + ' where '		+ @fields_filter


	-- if there is order fields add it
	if len(@fields_order)		> 0 set @query = @query + ' order by '	+ @fields_order


	-- replace '@comp_id' parameter with value informed
	select @query1 = replace(@query, '@comp_id', convert(varchar,(select @comp_id)))


	-- replace '@lang_id' parameter with value informed
	select @query2 = replace(@query1, '@lang_id', convert(varchar,(select @lang_id)))


	-- execute dynamic query to get real data from managed table
	--select @query2
	exec (@query2)

end

close		cursor_G2_gD_names
deallocate	cursor_G2_gD_names
/*************************************************************************************************
end Table 0 -
