CREATE PROCEDURE [dbo].[spGetCodeFromObject]
AS
BEGIN
	SET NOCOUNT ON

	select
	(Select	TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spUser_checkLogin'))				[spUser_checkLogin],
	(Select	TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spUser_getLogin'))					[spUser_getLogin],
	(Select	TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spUser_getLoginMobile'))			[spUser_getLoginMobile],
	(Select	TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spUser_getLoginFailCheck'))			[spUser_getLoginFailCheck],
	(Select	TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spUser_getLoggedCount'))			[spUser_getLoggedCount],
	(Select	TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spGetCodeFromObject'))				[spGetCodeFromObject],
	(Select	TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('fnGetEMailPoweredBy'))				[fnGetEMailPoweredBy],
	(SELECT TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spSystem_sendEMail'))				[spSystem_sendEMail],
	(Select	TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spIsEditingPurgeStatus'))			[spIsEditingPurgeStatus],
	(Select	TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spUSER_IsEditingPurgeStatus'))		[spUSER_IsEditingPurgeStatus],
	(Select	TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spBlockPage_IsEditingPurgeStatus'))	[spBlockPage_IsEditingPurgeStatus],
	(SELECT TOP 1 dbo.fnStrAllTrim(TEXT) from syscomments where id = object_id('spSysMenu_getDataGranted'))			[spSysMenu_getDataGranted],	
	GETDATE()																										[datetime]
END




GO


























CREATE PROCEDURE [dbo].[spGetCustomerById]
(
	@comp_id			int,
	@cust_id			int

)
as

	Select  tbC.comp_id,
			tbC.cust_id,
			tbC.bra_id,
			tbC.cust_name,
			tbC.cust_name1,
			tbC.fc_id,
			tbC.cust_taxNumber,
			tbC.cust_web,
			tbC.cust_inactive,
			tbC.cust_partnerOf,
			tbC.cust_contact,
			tbC.cust_address,
			tbC.cust_city,
			tbC.cust_zip,
			tbC.country_id,
			tbC.state_id,
			tbC.cust_phone1,
			tbC.cust_phone2,
			tbC.cust_email,
			tbC.cust_fax,
			tbC.cust_picture,
			tbC.sm_id,
			tbC.ck_id,
			tbC.st_id,
			tbC.disc_id,
			tbC.dl_id,
			tbC.cust_credit_max,
			tbC.cust_credit_own,
			tbC.curr_id,
			tbC.acc_count_id,
			tbC.prli_id,
			tbC.stor_id,
			tbC.user_id,
			tbS.state_desc

/*
	select	tbC.cust_name,
			tbC.cust_address,
			tbC.cust_city,
			tbC.cust_phone1,
			tbS.state_desc,
			tbc.curr_id,
			tbc.sm_id,
			tbc.ck_id,
			tbc.st_id,
			tbc.disc_id,
			tbc.dl_id,
			tbc.acc_count_id,
			tbc.cust_picture,
*/

	from	dbo.tbCustomer					tbC

			inner join dbo.tbsysState		tbS
			on  tbC.state_id   			= tbS.state_id




	where	tbC.comp_id =				    @comp_id
	AND		tbC.cust_id =					@cust_id




















GO








CREATE PROCEDURE [dbo].[spGetHeaderTexts]
(
	@lang_id			int,
	@page_id			int
)
as
SET NOCOUNT on



/*
declare	@lang_id		int,
		@page_id		int
select	@lang_id		=2,
		@page_id		=23
*/



select	T.page_id,
		P.page_desc,
		T.ctrl_id,
		upper(C.ctrl_desc) ctrl_desc,
		T.type_id,
		Ty.type_desc,
		T.prop_id,
		upper(Pr.prop_desc) prop_desc,
		--T.text_desc
		tswn.word_desc


from	dbo.tbSysTextsNew					T		WITH (NOLOCK)
		inner join dbo.tbSysPages			P		WITH (NOLOCK)
			on	P.page_id		= T.page_id
		inner join dbo.tbSysControls		C		WITH (NOLOCK)
			on	C.ctrl_id		= T.ctrl_id
		inner join dbo.tbSysTypes			Ty		WITH (NOLOCK)
			on	Ty.type_id		= T.type_id
		inner join dbo.tbSysProperties		Pr		WITH (NOLOCK)
			on	Pr.prop_id		= T.prop_id
		INNER JOIN tbSysWordsNew tswn				WITH (NOLOCK)
		ON	tswn.lang_id		= @lang_id
		AND tswn.wordsi_id		= T.wordsi_id

where	--T.lang_id				= @lang_id
--and
		T.page_id				= @page_id
and		T.type_id				= 12



GO

