CREATE PROCEDURE [dbo].[spGetTexts]
(
	@lang_id			int,
	@page_id			int,
	@fun_id				INT,
	@country_id			INT
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON


	-- ----------------------------------------
	-- Test
	-- ----------------------------------------
	/*
	declare	@lang_id		int,
			@page_id		int,
			@fun_id			INT,
			@country_id     int
	select	@lang_id		= 2,
			@page_id		= 14,
			@fun_id			= 1,
			@country_id		= 54
	*/
	-- ----------------------------------------


	SELECT 	T.page_id		,
			P.page_desc		,
			T.ctrl_id		,
			C.ctrl_desc		,
			T.[type_id]		,
			Ty.type_desc	,
			T.prop_id		,
			Pr.prop_desc	,
			CASE
			    WHEN c.ctrl_id = 29 OR c.ctrl_id = 726 THEN '(' + dbo.fnStrPADL( CONVERT(NVARCHAR(10),@page_id), 5, '0') + ') '
			    ELSE	''
			END +
			dbo.fnSysWordsNew_GetText(@lang_id,@country_id,t.wordsi_id)	[text_desc]
			--T.text_desc

	FROM 	dbo.tbSysTextsNew					T				WITH (NOLOCK)
			INNER JOIN dbo.tbSysPages			P				WITH (NOLOCK)
			ON 	P.page_id		= T.page_id
			INNER JOIN dbo.tbSysControls		C				WITH (NOLOCK)
			ON 	C.ctrl_id		= T.ctrl_id
			INNER JOIN dbo.tbSysTypes			Ty				WITH (NOLOCK)
			ON 	Ty.[type_id]	= T.[type_id]
			INNER JOIN dbo.tbSysProperties		Pr				WITH (NOLOCK)
			ON	Pr.prop_id		= T.prop_id
--			INNER JOIN tbsysWordsNew			tw
--			ON	t.wordsi_id		= tw.wordsi_id
--			AND tw.lang_id		= @lang_id


	WHERE	--T.lang_id			= 2
	--AND
			T.page_id			= @page_id
	AND 	T.[type_id]			NOT IN (12,18,59)	--omite textos de header, pager de grillas
    	           			      					--y de tipo dummy (textos para controles a inhabilitar)
	AND 	T.fun_id			= @fun_id

	ORDER BY type_desc, ctrl_desc



END
GO




CREATE PROCEDURE [dbo].[spGetTexts_byControl]
(
	@lang_id			int,
	@page_id			int,
	@ctrl_id			int,
	@fun_id				int
)
AS

BEGIN

	SET NOCOUNT ON

	-- -----------------------------------
	--
	-- -----------------------------------
	/*
	declare	@lang_id	int,
			@page_id	int,
			@ctrl_id	int,
			@fun_id		int
	select	@lang_id	=2,
			@page_id	=72,
			@ctrl_id	=46,
			@fun_id		=1
	*/
	-- -----------------------------------

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SELECT 	T.page_id		,
			P.page_desc		,
			T.ctrl_id		,
			C.ctrl_desc		,
			T.[type_id]		,
			Ty.type_desc	,
			T.prop_id		,
			Pr.prop_desc	,
			tw.word_desc	[text_desc]

		FROM 	dbo.tbSysTextsNew				   T	WITH (NOLOCK)
		INNER JOIN dbo.tbSysPages				AS P	WITH (NOLOCK)
			ON 	P.page_id			= T.page_id
		INNER JOIN dbo.tbSysControls			AS C	WITH (NOLOCK)
			ON 	C.ctrl_id			= T.ctrl_id
		INNER JOIN dbo.tbSysTypes				AS Ty	WITH (NOLOCK)
			ON	Ty.[type_id]		= T.[type_id]
		INNER JOIN dbo.tbSysProperties			AS Pr	WITH (NOLOCK)
			ON	Pr.prop_id			= T.prop_id
		INNER JOIN tbsysWordsNew				AS tw	WITH (NOLOCK)
			ON	tw.lang_id			= @lang_id	AND
				tw.wordsi_id		= T.wordsi_id
		WHERE 	T.page_id			= @page_id	AND
			 	T.[type_id]			= @ctrl_id	AND
		 		T.fun_id			= @fun_id
		ORDER BY type_desc, ctrl_desc ,T.prop_id desc



END
GO



CREATE PROCEDURE [dbo].[spGlobalChanges_GetPriceFromCost]
(
	@comp_id		INT,
	@bra_id			INT,
	@item_id		INT,
	@decCost		DECIMAL(19,4),
	@curr_id4Cost	INT,
    @decDiscount1	DECIMAL(19,4),
    @decDiscount2	DECIMAL(19,4),
    @decDiscount3	DECIMAL(19,4),
    @decDiscount4	DECIMAL(19,4),
    @decSurcharge1	DECIMAL(19,4),
    @decSurcharge2	DECIMAL(19,4),
    @decSurcharge3	DECIMAL(19,4),
    @decSurcharge4	DECIMAL(19,4),
    @decMarkup1		DECIMAL(25,8),
    @decMarkup2		DECIMAL(25,9),
    @curr_id4Spot	INT,
    @curr_id4Price	INT
)
AS
	SET NOCOUNT	ON

		BEGIN

			SELECT
				TBL.comp_id,
				TBL.item_id,
				TBL.CostWithAppliences,
				TBL.CostWithAppliencesNoTaxes,
				TBL.Price4Spot,
				TBL.Price4List,
				TBL.Price4SpotNoTaxes,
				TBL.Price4ListNoTaxes

			FROM dbo.fnGetPriceFromCost(@comp_id,
									    @bra_id,
									    @item_id,
									    @decCost,
									    @curr_id4Cost,
									    @decDiscount1,
									    @decDiscount2,
									    @decDiscount3,
									    @decDiscount4,
									    @decSurcharge1,
									    @decSurcharge2,
									    @decSurcharge3,
									    @decSurcharge4,
									    @decMarkup1,
									    @decMarkup2,
									    @curr_id4Spot,
									    @curr_id4Price) TBL

		END
GO



