CREATE PROCEDURE [dbo].[spIAData_CustomerCurrentPurchase_GetData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------
		-- TESTING
		-- ---------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT
		*/
		-- ---------------------------------------




		SELECT DISTINCT
							CASE
								WHEN tic.ic_desc LIKE '%root%'		THEN tsc.subcat_desc
								WHEN tic.ic_desc LIKE '%raiz%'		THEN tsc.subcat_desc
								WHEN tic.ic_desc LIKE '%01.gen%'	THEN tsc.subcat_desc
								ELSE tic.ic_desc
							END		[subCategory]
			FROM tbTempItemStock		AS ttis		WITH (NOLOCK)
			INNER JOIN tbItem			AS ti		WITH (NOLOCK)
				ON	ti.comp_id		= ttis.comp_id AND
					ti.item_id		= ttis.item_id
			INNER JOIN tbSubCategory	AS tsc		WITH (NOLOCK)
				ON	tsc.comp_id		= ti.comp_id	AND
					tsc.cat_id		= ti.cat_id		AND
					tsc.subcat_id	= ti.subcat_id
			INNER JOIN tbItemClass		AS tic		WITH (NOLOCK)
				ON	tic.comp_id		= ti.comp_id	AND
					tic.ic_id		= ti.ic_id
			WHERE ttis.tis_guid		= @guid



	END
GO

CREATE PROCEDURE [dbo].[spIAData_getBranchData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			ISNULL(tb.bra_IAData_companySector,'')	[bra_IAData_companySector],
			ISNULL(tb.bra_IAData_enabled,'False')	[bra_IAData_enabled],
			ISNULL(tb.bra_IAData_storg_id,-1)		[bra_IAData_storg_id],
			ISNULL(tb.bra_IAData_expertAt,'')		[bra_IAData_expertAt]
			FROM tbBranch							AS tb WITH(NOLOCK)
			WHERE	tb.comp_id	= @comp_id			AND
					tb.bra_id	= @bra_id
	END
GO

CREATE PROCEDURE spIAData_getCustomerData
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@cust_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			tc2.country_desc,
			ts.state_desc,
			ISNULL(tsc.city_desc,'')	[city_desc]
			FROM tbCustomer					AS tc	WITH(NOLOCK)
			INNER JOIN tbsysCountry			AS tc2	WITH(NOLOCK)
				ON tc2.country_id	= tc.country_id
			INNER JOIN tbsysState			AS ts	WITH(NOLOCK)
				ON	ts.country_id	= tc.country_id AND
					ts.state_id		= tc.state_id
			LEFT JOIN tbSysCities			AS tsc	WITH(NOLOCK)
				ON	tsc.country_id	= tc.country_id AND
					tsc.state_id	= tc.state_id
			WHERE	tc.comp_id = @comp_id AND
					tc.cust_id = @cust_id

	END
GO

CREATE PROCEDURE [dbo].[spIAData_ItemsOnSale_GetData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------
		-- TESTING
		-- ---------------------------------------
		/*
			DECLARE
				@comp_id	INT = 1,
				@lang_id	INT = 2,
				@bra_id		INT = 1,
				@prof_id	INT = 1,
				@user_id	INT = 1
		*/
		-- ---------------------------------------

		DECLARE @storg_id AS INT = -1
		DECLARE @stor_id  AS INT = -1
		SELECT  @storg_id		 = tb.bra_IAData_storg_id,
				@stor_id		 = tb.stor_id
			FROM tbBranch AS tb	WITH (NOLOCK)
			WHERE	tb.comp_id	 = @comp_id AND
					tb.bra_id	 = @bra_id


		SELECT DISTINCT
							CASE
								WHEN tic.ic_desc LIKE '%root%'		THEN tsc.subcat_desc
								WHEN tic.ic_desc LIKE '%raiz%'		THEN tsc.subcat_desc
								WHEN tic.ic_desc LIKE '%01.gen%'	THEN tsc.subcat_desc
								ELSE tic.ic_desc
							END																[subcat_desc],
							ti.item_desc
			FROM tbIAData_SalesBySubcategoryAndStorageGroup AS tisbsasg	WITH(NOLOCK)
			INNER JOIN tbSubCategory	AS tsc		WITH (NOLOCK)
				ON	tsc.comp_id		= tisbsasg.comp_id	AND
					tsc.subcat_id	= tisbsasg.subcat_id
			INNER JOIN tbItemClass		AS tic		WITH (NOLOCK)
				ON	tic.comp_id		= tisbsasg.comp_id	AND
					tic.ic_id		= tisbsasg.ic_id
			INNER JOIN tbItem			AS ti		WITH (NOLOCK)
				ON	ti.comp_id		= tisbsasg.comp_id AND
					ti.subcat_id	= tisbsasg.subcat_id AND
					ti.ic_id		= tisbsasg.ic_id
			WHERE tisbsasg.comp_id	= @comp_id			AND
				  tisbsasg.storg_id = @storg_id			AND
				  tisbsasg.inLiquidationCount > 0		AND
				  ti.item_liquidation = 'True'			AND
				  ti.item_disabled	  = 'False'			AND
				  ti.item_disabledInPriceList = 'False' AND
				  dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999) > 0


	END
GO

CREATE PROCEDURE [dbo].[spIAData_SalesByCustomerAndSubcategory_GetData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@cust_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------
		-- TESTING
		-- ---------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT
		*/
		-- ---------------------------------------


		SELECT DISTINCT
							CASE
								WHEN tic.ic_desc LIKE '%root%'		THEN tsc.subcat_desc
								WHEN tic.ic_desc LIKE '%raiz%'		THEN tsc.subcat_desc
								WHEN tic.ic_desc LIKE '%01.gen%'	THEN tsc.subcat_desc
								ELSE									 tic.ic_desc
							END					[subCategory]
			FROM tbitemtransactions							AS ttis		WITH (NOLOCK)
			INNER JOIN vwCommercialTransactions_forSales	AS vctfs	WITH (NOLOCK)
				ON	vctfs.comp_id			= ttis.comp_id	AND
					vctfs.bra_id			= ttis.bra_id	AND
					vctfs.ct_transaction	= ttis.ct_transaction
			INNER JOIN tbCommercialTransactions				AS tct		WITH (NOLOCK)
				ON	tct.comp_id				= ttis.comp_id	AND
					tct.bra_id				= ttis.bra_id	AND
					tct.ct_transaction		= ttis.ct_transaction
			INNER JOIN tbItem								AS ti		WITH (NOLOCK)
				ON	ti.comp_id				= ttis.comp_id	AND
					ti.item_id				= ttis.item_id
			INNER JOIN tbSubCategory						AS tsc		WITH (NOLOCK)
				ON	tsc.comp_id				= ti.comp_id	AND
					tsc.cat_id				= ti.cat_id		AND
					tsc.subcat_id			= ti.subcat_id
			INNER JOIN tbItemClass							AS tic		WITH (NOLOCK)
				ON	tic.comp_id				= ti.comp_id	AND
					tic.ic_id				= ti.ic_id
			WHERE	tct.comp_id				= @comp_id		AND
					tct.cust_id				= @cust_id

	END
GO

CREATE PROCEDURE [dbo].[spIAData_SalesBySubcategoryAndStorageGroup_GetData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------
		-- TESTING
		-- ---------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT
		*/
		-- ---------------------------------------

		DECLARE @storg_id AS INT = -1
		SELECT  @storg_id		= tb.bra_IAData_storg_id
			FROM tbBranch AS tb	WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id

		;WITH cte AS (
		SELECT DISTINCT
							CASE
								WHEN tic.ic_desc LIKE '%root%'		THEN tsc.subcat_desc
								WHEN tic.ic_desc LIKE '%raiz%'		THEN tsc.subcat_desc
								WHEN tic.ic_desc LIKE '%01.gen%'	THEN tsc.subcat_desc
								ELSE tic.ic_desc
							END		[subCategory],
							tisbsasg.QTY
			FROM tbIAData_SalesBySubcategoryAndStorageGroup AS tisbsasg	WITH(NOLOCK)
			INNER JOIN tbSubCategory AS tsc
				ON	tsc.comp_id		= tisbsasg.comp_id	AND
					tsc.subcat_id	= tisbsasg.subcat_id
			INNER JOIN tbItemClass		AS tic		WITH (NOLOCK)
				ON	tic.comp_id		= tisbsasg.comp_id	AND
					tic.ic_id		= tisbsasg.ic_id
			WHERE tisbsasg.comp_id	= @comp_id			AND
				  tisbsasg.storg_id = @storg_id
					)

		SELECT TOP 30 *
			FROM cte
			ORDER BY CHECKSUM(NEWID())



	END




GO

CREATE PROCEDURE [dbo].[spIAData_SubcategoriesOnSale_GetData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------
		-- TESTING
		-- ---------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT
		*/
		-- ---------------------------------------


		DECLARE @storg_id AS INT = -1
		SELECT  @storg_id = tb.bra_IAData_storg_id
			FROM tbBranch AS tb	WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id

		;WITH cte AS (
		SELECT DISTINCT
							CASE
								WHEN tic.ic_desc LIKE '%root%'		THEN tsc.subcat_desc
								WHEN tic.ic_desc LIKE '%raiz%'		THEN tsc.subcat_desc
								WHEN tic.ic_desc LIKE '%01.gen%'	THEN tsc.subcat_desc
								ELSE tic.ic_desc
							END										[subCategory]
			FROM tbIAData_SalesBySubcategoryAndStorageGroup AS tisbsasg	WITH(NOLOCK)
			INNER JOIN tbSubCategory AS tsc			WITH (NOLOCK)
				ON	tsc.comp_id		= tisbsasg.comp_id	AND
					tsc.subcat_id	= tisbsasg.subcat_id
			INNER JOIN tbItemClass		AS tic		WITH (NOLOCK)
				ON	tic.comp_id		= tisbsasg.comp_id	AND
					tic.ic_id		= tisbsasg.ic_id
			WHERE tisbsasg.comp_id	= @comp_id			AND
				  tisbsasg.storg_id = @storg_id			AND
				  tisbsasg.inLiquidationCount > 0
				)

		SELECT TOP 20 *
			FROM cte
			ORDER BY CHECKSUM(NEWID())


	END
GO

