CREATE PROCEDURE [dbo].[spImport_CalculateCostV2_GetDataByImport]
(
	@comp_id	INT,
	@import_id	INT
)
AS
	BEGIN

		--STL Con este SP obtenemos que tipo de Prorateo se utilizó y si fue calculado con Impuestos o sin Impuestos
		--para que al momento de seleccionar una importación en la página, si ya presenta datos, los precargue
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@import_id	INT
			SELECT
				@comp_id	= 1,
				@import_id	= 480
		*/
		-- ---------------------------------------------

		SELECT
			TOP 1
				ticc.comp_id,
				ticc.ica_id,
				ticc.import_id,
				ticc.ica_ProrrationType,
				CASE WHEN ticc.ica_finalCostWithTaxes = 0 THEN 0 ELSE 1 END [WithTaxes]
		FROM tbImport_costCalculate			ticc		WITH (NOLOCK)
		WHERE	ticc.comp_id	= @comp_id	AND
				ticc.import_id	= @import_id

	END
GO

