CREATE PROCEDURE [dbo].[spImport_CostCalculateHistory_GetDataByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@import_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------
		-- TESTING
		-- ------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@import_id	INT
			SELECT
				@comp_id	= 1,
				@import_id	= 1
		*/
		-- ------------------------------------------

		SELECT
			' '													[ ],
			ticch.comp_id,
			ticch.ica_id,
			ticch.icah_id,
			ticch.import_id,
			ticch.it_transaction,
			ti.item_code,
			ti.item_desc,
			titp.posara_desc,
			ticch.ica_coef,
			ticch.ica_percentage,
			ticch.ica_cost,
			ticch.ica_qty,
			ticch.ica_freightByItem,
			ticch.ica_insuranceByItem,
			ticch.ica_spendingInOriginByItem,
			ticch.ica_staticticsByItem,
			ticch.ica_dutiesByItem,
			ticch.ica_dumpingByItem,
			ticch.ica_internalTaxesByItem,
			ticch.ica_otherSpendingsTotalByItem,
			ticch.ica_localExpensesByItem,
			ticch.ica_costBeforeExtrasByItem,
			ticch.ica_finalCostWithOutTaxes,
			ticch.ica_incidencepercentage,
			ticch.ica_ExpensesCoeficientByItem,
			ticch.ica_finalCostWithTaxes,
			ttn.tax_desc,
			tu.user_lastname + ' , ' + tu.user_firstname		[User_Name],
			tov.optval_desc,
			ticch.ica_calcDate
			FROM tbImport_costCalculateHistory					ticch	WITH(NOLOCK)
				INNER JOIN tbItem								ti		WITH(NOLOCK)
					ON	ti.comp_id			= ticch.comp_id		AND
						ti.item_id			= ticch.item_id
				INNER JOIN tbImport_tariffPosition				titp	WITH(NOLOCK)
					ON	titp.comp_id		= ticch.comp_id		AND
						titp.posara_id		= ticch.posara_id
				INNER JOIN tbTaxName							ttn		WITH(NOLOCK)
					ON	ttn.comp_id			= ticch.comp_id		AND
						ttn.tax_id			= ticch.tax_id
				INNER JOIN tbUser								tu		WITH(NOLOCK)
					ON	tu.[user_id]		= ticch.[user_id]
				INNER JOIN tbsysOptionsValues					tov
					ON	tov.lang_id			=  @lang_id			AND
						tov.optval_class	= 47				AND
						tov.optval_id		= ticch.ica_ProrrationType
 				WHERE	ticch.comp_id	= @comp_id			AND
						ticch.import_id = @import_id

			ORDER BY ticch.icah_id DESC

	END
GO


