--Log:
-- MOS 02-2024, referencias abajo



CREATE PROCEDURE [dbo].[spImport_getComboForAdjustment]
(
	@comp_id AS INT,
	@lang_id AS INT,
	@item_id AS INT,
	@option  AS INT
)
AS

BEGIN

	SET NOCOUNT ON


	-- ------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------
	/*
	DECLARE @comp_id     AS INT,
			@lang_id     AS INT,
			@item_id     AS INT,
			@option      AS INT
	SELECT	@comp_id	=1,
			@lang_id	=2,
			@item_id	=353,
			@option		=3
	*/
	-- ------------------------------------------------------------------------------


	/**************************************************************************************************
	@option = 1 : Entrada
	@option = 2 : Salida
	@option = 3 : Transferencia
	@option = 4 : Componer
	@option = 5 : Descomponer
	**************************************************************************************************/

	SELECT	DISTINCT TOP 500		-- MOS 02-2024: Pase de 50 a 500
			tid.it_transaction,
			convert(varchar,tid.impData_id) + '-' + convert(varchar,tid.it_transaction)					[ID],
			DBO.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tid.ct_transaction) + ' # ' +
			isnull(tid.impData_Custom_local,'')												+ ' # ' +
			isnull(tid.impData_Number_local,'')												+ ' # ' +
			isnull(CONVERT(varchar,convert(decimal(18,2),tid.impData_InitialQty)),'')		+ ' # ' +
			isnull(CONVERT(varchar,convert(decimal(18,2),tid.impData_ActualQty)),'')		+ ' # ' +
			isnull(CONVERT(varchar,tct.ct_date,103),'')													[desc]

	FROM	tbImportData							tid		WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions		tct		WITH (NOLOCK)
			ON	tct.comp_id        = tid.comp_id
			AND tct.ct_transaction = tid.ct_transaction

			INNER JOIN tbItemTransactions			tit		WITH (NOLOCK)
			ON  tit.comp_id			= tid.comp_id
			--AND tit.ct_transaction	= tid.ct_transaction		--	MOS: 05-2024 Saque esto ya quer no tenia indices y colgaba TODO x q hacia un full scan
			AND tit.it_transaction	= tid.it_transaction
			--AND tit.item_id			= tid.item_id				--	MOS: 05-2024 Saque esto ya quer no tenia indices y colgaba TODO x q hacia un full scan

			INNER JOIN tbItem						ti		WITH (NOLOCK)
			ON	ti.comp_id			= tid.comp_id
			AND ti.item_id			= tid.item_id

			LEFT JOIN tbItemSerials					tis		WITH (NOLOCK)
			ON	tis.comp_id			= tid.comp_id
			AND tis.it_transaction	= tid.it_transaction

	WHERE	tid.comp_id = @comp_id
	AND		tid.item_id = @item_id

	/**********************************************************************************************************************/
	/*Cambiado por MOH  el  28/10/2011*/
	AND		(
				(@option IN (2,3) AND (ISNULL(tis.is_serial,'') = '' OR ISNULL(tis.is_available,'false') = 'true')) 	OR
				(@option IN (1,4,5))
			)
--	AND		(
--				(
--					(ti.item_expser = 'true') AND
--					(
--						(tis.is_available = 'true' OR tis.is_available = 'false') AND
--						ISNULL(tis.is_serial,'') = ''
--					)
--				) OR
--				(ti.item_expser = 'false')
--			)
	/**********************************************************************************************************************/

	AND		(
				(@option = 1 AND tid.impData_InitialQty > tid.impData_ActualQty) OR
				(@option = 2 AND tid.impData_ActualQty	> 0) OR
				(@option = 3 AND (tid.impData_ActualQty	> 0 OR tis.comp_id IS NOT NULL)) OR	-- MOS 02-2024 x tixcket 20546 para que puedan transferir. me parece una FORRADA esto, ver si no hay q revertirlo. NO deberian poder transferir algo que YA NO ESTá disponible en el despacho.
				--(@option = 3 AND tid.impData_ActualQty	> 0 ) OR
				(@option = 4 AND tid.impData_ActualQty	> 0) OR
				(@option = 5 AND tid.impData_ActualQty	> 0)
			)

	AND		tct.sd_id IN (
							101, -- factura proveedor
							102, -- remito proveedor
							124, -- carga inicial de stock
							130, -- despacho de importación
							145  -- producción de equipos
						)
	ORDER BY tid.it_transaction DESC


END
GO





