CREATE PROCEDURE [dbo].[spImport_getDataByText]
(
	@text	VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id	AS INT,
	@bra_id		AS INT,
	@status		AS INT
)
AS



BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*

		DECLARE
			@text		VARCHAR(300),
			@count		INT,
			@lang_id	INT,
			@comp_id AS INT,
			@bra_id  AS INT

		DECLARE @status		AS INT = 2

		SELECT
			@text		='+A',
			@count		= 2,
			@lang_id	= 2,
			@comp_id	= 1,
			@bra_id		= 1
	*/
	-- ----------------------------------------------------------------





	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')



	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)
	DECLARE @text6	varchar(300)
	DECLARE @text7	varchar(300)
	DECLARE @text8	varchar(300)
	DECLARE @text9	varchar(300)
	DECLARE @text10	varchar(300)

	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0 else
			IF @text2 IS NULL SET @text2 = @text0 else
			IF @text3 IS NULL SET @text3 = @text0 else
			IF @text4 IS NULL SET @text4 = @text0 else
			IF @text5 IS NULL SET @text5 = @text0 else
			IF @text6 IS NULL SET @text6 = @text0 else
			IF @text7 IS NULL SET @text7 = @text0 else
			IF @text8 IS NULL SET @text8 = @text0 else
			IF @text9 IS NULL SET @text9 = @text0 else
			IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------





	SELECT		TOP (@count)

				Upper(dbo.PadRightString( IsNull(tc.import_desc,''),'.',50)) + ' | ' + isnull(convert(VARCHAR(10),tc.import_id),'')	[import_desc],
				tc.import_id
		FROM tbImport tc			WITH (NOLOCK)
		WHERE		tc.comp_id = @comp_id	AND
					CASE
						WHEN @status = 2								THEN 1
						WHEN @status = 0 AND tc.import_closed = 'True'	THEN 1
						WHEN @status = 1 AND tc.import_closed = 'False'	THEN 1
						ELSE											     0
					END	= 1					AND
			(

						CASE
							WHEN @selection_method = 0 AND tc.import_desc LIKE @text + '%'	 THEN	'True'
							WHEN @selection_method = 1 AND tc.import_desc LIKE '%' + @text1 + '%'	 THEN	'True'
							WHEN @selection_method = 2 AND tc.import_desc LIKE '%' + @text1 + '%' AND tc.import_desc LIKE '%' + @text2 + '%'		 THEN	'True'
							WHEN @selection_method = 3 AND tc.import_desc LIKE '%' + @text1 + '%' AND tc.import_desc LIKE '%' + @text2 + '%' AND tc.import_desc LIKE '%' + @text3 + '%'	 THEN	'True'
							WHEN @selection_method = 4 AND tc.import_desc LIKE '%' + @text1 + '%' AND tc.import_desc LIKE '%' + @text2 + '%' AND tc.import_desc LIKE '%' + @text3 + '%' AND tc.import_desc LIKE '%' + @text4 + '%'		 THEN	'True'
							WHEN @selection_method = 5 AND tc.import_desc LIKE '%' + @text1 + '%' AND tc.import_desc LIKE '%' + @text2 + '%' AND tc.import_desc LIKE '%' + @text3 + '%' AND tc.import_desc LIKE '%' + @text4 + '%' AND tc.import_desc LIKE '%' + @text5 + '%'		 THEN	'True'
							WHEN @selection_method = 6 AND tc.import_desc LIKE '%' + @text1 + '%' AND tc.import_desc LIKE '%' + @text2 + '%' AND tc.import_desc LIKE '%' + @text3 + '%' AND tc.import_desc LIKE '%' + @text4 + '%' AND tc.import_desc LIKE '%' + @text5 + '%' AND tc.import_desc LIKE '%' + @text6 + '%'	 THEN	'True'
							WHEN @selection_method = 7 AND tc.import_desc LIKE '%' + @text1 + '%' AND tc.import_desc LIKE '%' + @text2 + '%' AND tc.import_desc LIKE '%' + @text3 + '%' AND tc.import_desc LIKE '%' + @text4 + '%' AND tc.import_desc LIKE '%' + @text5 + '%' AND tc.import_desc LIKE '%' + @text6 + '%' AND tc.import_desc LIKE '%' + @text7 + '%'	 THEN	'True'
							WHEN @selection_method = 8 AND tc.import_desc LIKE '%' + @text1 + '%' AND tc.import_desc LIKE '%' + @text2 + '%' AND tc.import_desc LIKE '%' + @text3 + '%' AND tc.import_desc LIKE '%' + @text4 + '%' AND tc.import_desc LIKE '%' + @text5 + '%' AND tc.import_desc LIKE '%' + @text6 + '%' AND tc.import_desc LIKE '%' + @text7 + '%' AND tc.import_desc LIKE '%' + @text8 + '%'		 THEN	'True'
							WHEN @selection_method = 9 AND tc.import_desc LIKE '%' + @text1 + '%' AND tc.import_desc LIKE '%' + @text2 + '%' AND tc.import_desc LIKE '%' + @text3 + '%' AND tc.import_desc LIKE '%' + @text4 + '%' AND tc.import_desc LIKE '%' + @text5 + '%' AND tc.import_desc LIKE '%' + @text6 + '%' AND tc.import_desc LIKE '%' + @text7 + '%' AND tc.import_desc LIKE '%' + @text8 + '%' AND tc.import_desc LIKE '%' + @text9 + '%'		 THEN	'True'
							WHEN @selection_method =10 AND tc.import_desc LIKE '%' + @text1 + '%' AND tc.import_desc LIKE '%' + @text2 + '%' AND tc.import_desc LIKE '%' + @text3 + '%' AND tc.import_desc LIKE '%' + @text4 + '%' AND tc.import_desc LIKE '%' + @text5 + '%' AND tc.import_desc LIKE '%' + @text6 + '%' AND tc.import_desc LIKE '%' + @text7 + '%' AND tc.import_desc LIKE '%' + @text8 + '%' AND tc.import_desc LIKE '%' + @text9 + '%' AND tc.import_desc LIKE '%' + @text10 + '%'		 THEN 'True'
							ELSE	'False'
						END	= 'True'

			)

			ORDER BY	tc.import_desc

END
GO


CREATE PROCEDURE [dbo].[spImport_SIMI_ValidateItemQty4PurchaseOrderItem]
(
	@comp_id			INT,
	@simi_id			INT,
	@simid_id			INT,
	@itemQty2Purchase	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@simi_id			INT,
				@simid_id			INT,
				@itemQty2Purchase	INT
			SELECT
				@comp_id			= 1,
				@simi_id			= 15,
				@simid_id			= 28,
				@itemQty2Purchase	= 4
		*/
		-- ----------------------------------------------


		-- ------------------------------------------------------
		-- CONSTANTES
		-- ------------------------------------------------------
			DECLARE
				@lErrorMargenPercentaje4ItemsQty	INT
			SET @lErrorMargenPercentaje4ItemsQty	= 4
		-- ------------------------------------------------------


		--TOTAL DE ARTICULOS COMPRADOS PARA ESE SIMID_ID
		DECLARE
			@ItemQtyPurchased	INT
		SET @ItemQtyPurchased	= 0
		SELECT
			@ItemQtyPurchased  = ISNULL(SUM(tpod.pod_qty),0)
		FROM tbPurchaseOrderDetail			tpod
		WHERE	tpod.comp_id	= @comp_id	AND
				tpod.simi_id	= @simi_id	AND
				tpod.simid_id	= @simid_id

		--TOTAL DE ARTICULOS DISPONIBLES DE ESE SIMID_ID (TOTAL DE ARTICULOS - TOTAL DE ARTÍCULOS COMPRADOS)
		DECLARE
			@ItemQtyAvailable		INT,
			@TotalItemQty2Purchase	INT
		SET @ItemQtyAvailable		= 0
		SET @TotalItemQty2Purchase	= 0

		SELECT
			@TotalItemQty2Purchase	= tis.simid_qty,
			@ItemQtyAvailable		= tis.simid_qty - @ItemQtyPurchased
		FROM tbImport_SIMIDetail			tis
		WHERE	tis.comp_id		= @comp_id	AND
				tis.simi_id		= @simi_id	AND
				tis.simid_id	= @simid_id

		--SETEO LA CANTIDAD POR DEBAJO Y POR ENCIMA EN UN 4%
		DECLARE
			@ItemQty4PercentajeAbove	DECIMAL(25,2),
			@ItemQty4PercentajeBelow	DECIMAL(25,2)

		SET @ItemQty4PercentajeAbove	= @TotalItemQty2Purchase  + (@lErrorMargenPercentaje4ItemsQty * @TotalItemQty2Purchase / 100)
		SET @ItemQty4PercentajeBelow	= @TotalItemQty2Purchase  - (@lErrorMargenPercentaje4ItemsQty * @TotalItemQty2Purchase / 100)




		--SI LA CANTIDAD COMPRADA + LA CANTIDAD A COMPRAR ES MAYOR
		--AL MARGEN SUPERIOR, ERROR
		IF (@ItemQtyPurchased + @itemQty2Purchase) > @ItemQty4PercentajeAbove
			BEGIN
				SELECT
					'QTY_EXCEED'	[Message]
			END
		--SI CANTIDAD COMPRADA + LA CANTIDAD A COMPRAR ES MENOR
		--AL MARGEN INFERIOR, LO DEJAMOS GRABAR; PERO LE TIRAMOS CARTEL
		--CON ADVERTENCIA
		IF (@ItemQtyPurchased + @itemQty2Purchase) < @ItemQty4PercentajeBelow
			BEGIN
				SELECT
					'QTY_BELOW'	[Message]
			END

		--SI CANTIDAD COMPRADA + LA CANTIDAD A COMPRAR SE MANTIENE
		--ENTRE LOS MARGENES, NO HAY MENSAJE DE ADVERTENCIA NI DE ERROR.
		IF (@ItemQtyPurchased + @itemQty2Purchase) BETWEEN @ItemQty4PercentajeBelow AND @ItemQty4PercentajeAbove
			BEGIN
				SELECT
					'QTY_OK'		[Message]
			END

	END







GO


CREATE PROCEDURE [dbo].[spImport_SIMI_ValidatePrice4PurchaseOrderItem]
(
	@comp_id	INT,
	@simi_id	INT,
	@simid_id	INT,
	@Price		DECIMAL(25,2)
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@simi_id	INT,
				@simid_id	INT,
				@Price		DECIMAL(25,2)
			SELECT
				@comp_id	= 1,
				@simi_id	= 15,
				@simid_id	= 28,
				@Price		= 2800
		*/
		-- ------------------------------------------------

		-- ------------------------------------------------------
		-- CONSTANTES
		-- ------------------------------------------------------
			DECLARE
				@lErrorMargenPercentaje4Price	INT
			SET @lErrorMargenPercentaje4Price	= 4
		-- ------------------------------------------------------


		DECLARE
			@PriceAbove		DECIMAL(25,2),
			@PriceBelow		DECIMAL(25,2),
			@OriginalPrice	DECIMAL(25,2)

		SET @PriceAbove = 0
		SET @PriceBelow = 0

		SELECT
			@OriginalPrice		= tis.simid_price
		FROM tbImport_SIMIDetail			tis
		WHERE	tis.comp_id		= @comp_id	AND
				tis.simi_id		= @simi_id	AND
				tis.simid_id	= @simid_id

		SET @PriceAbove = @OriginalPrice + (@lErrorMargenPercentaje4Price * @OriginalPrice / 100)
		SET @PriceBelow = @OriginalPrice - (@lErrorMargenPercentaje4Price * @OriginalPrice / 100)


		IF @Price BETWEEN @PriceBelow AND @PriceAbove
			BEGIN
				SELECT
					'Price_Ok'				[Message]
			END
		ELSE
			BEGIN
				SELECT
					'Price_Error'			[Message],
					@Price					[Price],
					@PriceBelow				[PriceBelow],
					@PriceAbove				[PriceAbove]
			END

	END

GO


