CREATE PROCEDURE [dbo].[spImport_SIMIDetail_GetCombo]
(
	@comp_id	INT,
	@simi_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------
		-- TESTING
		-- ----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@simi_id	INT

			SELECT
				@comp_id	= 1,
				@simi_id	= 13
		*/
		-- ----------------------------------------

		SELECT
			CONVERT(VARCHAR,tis.simid_item)							+ ' | ' +
			CONVERT(VARCHAR,tis.simid_subItem)						+ ' | ' +
			CONVERT(VARCHAR,ISNULL(ti.item_code,''))				+ ' | ' +
			CONVERT(VARCHAR,ISNULL(ti.item_desc,''))				+ ' | ' +
			ISNULL(SUBSTRING(tis.simid_itemDescription,0,30),'')	+ ' | ' +
			CONVERT(VARCHAR,tis.simid_price)						+ ' | ' +
			CONVERT(VARCHAR,tis.simid_qty)						[Desc],
			tis.simid_id										[Id]
			FROM tbImport_SIMIDetail							tis
				LEFT JOIN tbItem								ti
					ON	ti.comp_id	= tis.comp_id				AND
						ti.item_id	= tis.item_id
			WHERE	tis.comp_id		= @comp_id					AND
					tis.simi_id		= @simi_id

	END
GO


CREATE PROCEDURE [dbo].[spImport_SIMIDetail_GetDataByFilters]
(
	@comp_id		INT,
	@simid_item		INT,
	@simid_subItem	INT,
	@country_id		INT,
	@posara_id		INT,
	@brand_id		INT,
	@item_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------
		-- TESTING
		-- --------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@simid_item		INT,
				@simid_subItem	INT,
				@country_id		INT,
				@posara_id		INT,
				@brand_id		INT,
				@item_id		INT
		*/
		-- --------------------------------------------------
		SELECT
			' '												[ ],	--UPDATE
			' '												[ ],	--DELETE
			' '												[ ],	--A DEFINIR
			tis.simid_item,
			tis.simid_subItem,
			tc.country_desc,
			titp.posara_code,
			tis.simid_itemDescription,
			tb.brand_desc,
			ISNULL(ti.item_desc,'')							[item_Desc],
			tis.simid_qty,
			tis.simid_price,
			ISNULL(tis.simid_qty,0) *
			ISNULL(tis.simid_price,0)						[SubTotal],
			CONVERT(VARCHAR,tis.simi_id) + '-' +
			CONVERT(VARCHAR,tis.simid_id)					[ID]
			FROM tbImport_SIMIDetail						tis
				INNER JOIN tbsysCountry						tc
					ON tc.country_id	= tis.country_id4Origin
				INNER JOIN tbBrand							tb
					ON	tb.comp_id		= tis.comp_id		AND
						tb.brand_id		= tis.brand_id
				INNER JOIN tbImport_tariffPosition			titp
					ON	titp.comp_id	= tis.comp_id		AND
						titp.posara_id	= tis.posara_id
				LEFT JOIN tbItem							ti
					ON	ti.comp_id		= tb.comp_id		AND
						ti.item_id		= tis.item_id
			WHERE	tis.comp_id			= @comp_id												AND
					(@simid_item		= 0		OR tis.simid_item			= @simid_item)		AND
					(@simid_subItem		= 0		OR tis.simid_subItem		= @simid_subItem)	AND
					(@item_id			= -1	OR tis.item_id				= @item_id)			AND
					(@country_id		= -1	OR tis.country_id4Origin	= @country_id)		AND
					(@posara_id			= -1	OR tis.posara_id			= @posara_id)		AND
					(@brand_id			= -1	OR tis.brand_id				= @brand_id)

	END



GO


