CREATE PROCEDURE spImport_SIMIDetail_InsertData
(
	@comp_id				INT,
	@simi_id				INT,
	@simid_item				INT,
	@simid_subItem			INT,
	@country_id				INT,
	@posara_id				INT,
	@simid_ItemDescription	NVARCHAR(500),
	@brand_id				INT,
	@item_id				INT,
	@simid_qty				DECIMAL(19,4),
	@simid_price			DECIMAL(19,4),
	@return_value			INT	OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@simi_id				INT,
				@simid_item				INT,
				@simid_subItem			INT,
				@country_id				INT,
				@posara_id				INT,
				@simid_ItemDescription	NVARCHAR(500),
				@brand_id				INT,
				@item_id				INT,
				@simid_qty				DECIMAL(19,4),
				@simid_price			DECIMAL(19,4),
				@return_value			INT
		*/
		-- -------------------------------------------------

		INSERT INTO tbImport_SIMIDetail
		(
			comp_id,
			simi_id,
			simid_item,
			simid_subItem,
			country_id4Origin,
			posara_id,
			simid_itemDescription,
			brand_id,
			item_id,
			simid_qty,
			simid_price
		)
		VALUES
		(
			@comp_id,
			@simi_id,
			@simid_item,
			@simid_subItem,
			@country_id,
			@posara_id,
			@simid_ItemDescription,
			@brand_id,
			@item_id,
			@simid_qty,
			@simid_price
		)

		SET @return_value = @@IDENTITY
	END


GO


CREATE PROCEDURE spImport_SIMIDetail_UpdateData
(
	@comp_id				INT,
	@simi_id				INT,
	@simid_id				INT,
