			ISNULL(ti.item_desc,'')									[item_desc],
			tist.simid_qty,
			tist.simid_price,
			ISNULL(tist.simid_total,0)								[simid_total],
			tov.optval_desc,
			tist.simidt_id											ID
			FROM tbImport_SIMIDetailTmp								tist
				INNER JOIN tbsysCountry								tc
					ON	tc.country_id	= tist.country_id4Origin
				INNER JOIN tbBrand									tb
					ON	tb.comp_id		= tist.comp_id				AND
						tb.brand_id		= tist.brand_id
				INNER JOIN tbImport_tariffPosition					titp
					ON	titp.comp_id	= tist.comp_id				AND
						titp.posara_id	= tist.posara_id
				LEFT JOIN tbItem									ti
					ON	ti.comp_id		= tist.comp_id				AND
						ti.item_id		= tist.item_id
				LEFT JOIN tbsysOptionsValues						tov
					ON	tov.lang_id		= @lang_id					AND
						tov.optval_class= 550						AND
						tov.optval_id	= tist.simid_status
			WHERE	tist.comp_id		= @comp_id					AND
					tist.simidt_id		= @simidt_id				AND
					tist.simid_guid		= @guid

	END

GO



CREATE PROCEDURE [dbo].[spImport_SIMIDetailTmp_GetDataBySimiId]
(
