CREATE PROCEDURE [dbo].[spImport_SIMIDetailTmp_InsertData]
(
	@comp_id				INT,
	@simi_id				INT,
	--@simid_id				INT,
	@guid					UNIQUEIDENTIFIER,
	@simid_item				INT,
	@simid_subItem			INT,
	@country_id				INT,
	@posara_id				INT,
	@simid_itemDescription	NVARCHAR(500),
	@brand_id				INT,
	@item_id				INT,
	@simid_qty				DECIMAL(19,4),
	@simid_price			DECIMAL(19,4),
	@simidt_status			INT,
	@simidt_total			DECIMAL(25,4),
	@return_value			INT OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@simi_id				INT,
				@guid					UNIQUEIDENTIFIER,
				@simid_item				INT,
				@simid_subItem			INT,
				@country_id				INT,
				@posara_id				INT,
				@simid_itemDescription	NVARCHAR(500),
				@brand_id				INT,
				@item_id				INT,
				@simid_qty				DECIMAL(19,4),
				@simid_price			DECIMAL(19,4)



			SELECT
				@comp_id				= 1,
				@simi_id				= 2,
				@guid					= '',
				@simid_item				= 1,
				@simid_subItem			= 1,
				@country_id				= 1,
				@posara_id				= 1,
				@simid_itemDescription	= '',
				@brand_id				= 1,
				@item_id				= 1,
				@simid_qty				= 10,
				@simid_price			= 11
		*/
		-- -----------------------------------------------------------

		IF @simi_id = -1
			BEGIN
				SET @simi_id = NULL
			END
--		IF @simid_id = -1
--			BEGIN
--				SET @simid_id = NULL
--			END

		IF @item_id = -1
			BEGIN
				SET @item_id = NULL
			END



		INSERT INTO tbImport_SIMIDetailTmp
		(
			comp_id,
			-- simidt_id -- this column value is auto-generated,
			simi_id,
			--simid_id,
			simid_guid,
			simid_item,
			simid_subItem,
			country_id4Origin,
			posara_id,
			simid_itemDescription,
			brand_id,
			item_id,
			simid_qty,
			simid_price,
			simid_status,
			simid_total
		)
		VALUES
		(
			@comp_id,
			@simi_id,
			--@simid_id,
			@guid,
			@simid_item,
			@simid_subItem,
			@country_id,
			@posara_id,
			@simid_itemDescription,
			@brand_id,
			@item_id,
			@simid_qty,
			@simid_price,
			@simidt_status,
			@simidt_total
		)

		SET @return_value = @@IDENTITY
	END
GO


CREATE PROCEDURE [dbo].[spImport_SIMIDetailTmp_InsertDataFromTMP]
(
	@comp_id	INT,
	@simi_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@simi_id	INT,
				@guid		UNIQUEIDENTIFIER
		*/
		-- ----------------------------------------------------------


		-- Borro los que NO están mas en la Temp pero SI estan en la detail  (Esto puede explorar si YA esta asignado a una OC.  1ro deberían des-asignarla.)
		DELETE   tbImport_SIMIDetail
			FROM tbImport_SIMIDetail simiD
			LEFT JOIN tbImport_SIMIDetailTmp tmp					WITH (NOLOCK)
				ON	tmp.comp_id		= simiD.comp_id AND
					tmp.simi_id		= simiD.simi_id AND
					tmp.simid_id	= simiD.simid_id
			WHERE	simiD.comp_id = @comp_id		AND
					simiD.simi_id = @simi_id		AND
					tmp.comp_id IS NULL



		-- Actualizo la Detail con SOLO los que YA estaban como simid_id y pueden YA estar asignados a una OC ( para q no explorte )
		UPDATE tbImport_SIMIDetail SET simid_item				= tist.simid_item,
										simid_subItem			= tist.simid_subItem,
										country_id4Origin		= tist.country_id4Origin,
										posara_id				= tist.posara_id,
										simid_itemDescription	= tist.simid_itemDescription,
										brand_id				= tist.brand_id,
										item_id					= tist.item_id,
										simid_qty				= tist.simid_qty,
										simid_price				= tist.simid_price,
										simid_status			= tist.simid_status,
										simid_total				= tist.simid_total
			FROM		tbImport_SIMIDetail				tmp		WITH(NOLOCK)
			INNER JOIN	tbImport_SIMIDetailTmp			tist	WITH(NOLOCK)
				ON	tmp.comp_id		= tist.comp_id AND
					tmp.simi_id		= tist.simi_id AND
					tmp.simid_id	= tist.simid_id
			WHERE	tist.comp_id	= @comp_id	AND
					tist.simid_guid = @guid



		-- INserta los NUEVOS que NO estan en la detail definitiva
		INSERT INTO tbImport_SIMIDetail
		(
			comp_id,
			simi_id,
			-- simid_id -- this column value is auto-generated,
			simid_item,
			simid_subItem,
			country_id4Origin,
			posara_id,
			simid_itemDescription,
			brand_id,
			item_id,
			simid_qty,
			simid_price,
			simid_status,
			simid_total
		)
		SELECT
			tist.comp_id,
			@simi_id,
			tist.simid_item,
			tist.simid_subItem,
			tist.country_id4Origin,
			tist.posara_id,
			tist.simid_itemDescription,
			tist.brand_id,
			tist.item_id,
			tist.simid_qty,
			tist.simid_price,
			tist.simid_status,
			tist.simid_total
			FROM tbImport_SIMIDetailTmp			tist	WITH(NOLOCK)
			LEFT JOIN tbImport_SIMIDetail		simiD	WITH(NOLOCK)
				ON	simiD.comp_id	= tist.comp_id AND
					simiD.simi_id	= tist.simi_id AND
					simiD.simid_id	= tist.simid_id
			WHERE	tist.comp_id	= @comp_id	AND
					tist.simid_guid = @guid		AND
					simiD.comp_id IS NULL








	END
GO


CREATE PROCEDURE [dbo].[spImport_SIMIDetailTmp_UpdateData]
(
	@comp_id				INT,
	@simidt_id				INT,
	@simid_item				INT,
	@simid_subItem			INT,
	@country_id				INT,
	@posara_id				INT,
	@simid_itemDescription	NVARCHAR(500),
	@brand_id				INT,
	@item_id				INT,
	@simid_qty				DECIMAL(19,4),
	@simid_price			DECIMAL(19,4),
	@simidt_status			INT,
	@simidt_total			DECIMAL(25,4)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@simidt_id				INT,
				@simid_item				INT,
				@simid_subItem			INT,
				@country_id				INT,
				@posara_id				INT,
				@simid_itemDescription	NVARCHAR(500),
				@brand_id				INT,
				@item_id				INT,
				@simid_qty				DECIMAL(19,4),
				@simid_price			DECIMAL(19,4)
		*/
		-- ---------------------------------------------------


			IF @item_id = -1
				BEGIN
					SET @item_id = NULL
				END


		UPDATE tbImport_SIMIDetailTmp
		SET
			simid_item				= @simid_item,
			simid_subItem			= @simid_subItem,
			country_id4Origin		= @country_id,
			posara_id				= @posara_id,
			simid_itemDescription	= @simid_itemDescription,
			brand_id				= @brand_id,
			item_id					= @item_id,
			simid_qty				= @simid_qty,
			simid_price				= @simid_price,
			simid_status			= @simidt_status,
			simid_total				= @simidt_total
			WHERE	comp_id			= @comp_id	AND
					simidt_id		= @simidt_id
	END
GO


