CREATE PROCEDURE spImport_SIMIHeader_ExistsCode
(
	@comp_id	INT,
	@simi_code	NVARCHAR(30)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@simi_code	NVARCHAR(30)
		*/
		-- -------------------------------------------------

		IF EXISTS (SELECT
						1
						FROM tbImport_SIMIHeader			tis
						WHERE	tis.comp_id		= @comp_id	AND
								tis.simi_code	= @simi_code)
			BEGIN
				SELECT 'True'
			END
		ELSE
			BEGIN
				SELECT 'False'
			END
	END
GO


