CREATE PROCEDURE [dbo].[spImport_SIMIHeader_GetDataByFilters]
(
 @comp_id							INT,
 @lang_id							INT,
 @simi_code							NVARCHAR(30),
 @simi_Type							INT,
 @simi_Status						INT,
 @simi_presentationDateFrom			DATETIME,
 @simi_presentationDateTo			DATETIME,
 @simi_approvalDateFrom				DATETIME,
 @simi_approvalDateTo				DATETIME,
 @simi_presentationAtLNADateFrom	DATETIME,
 @simi_presentationAtLNADateTo		DATETIME,
 @simi_via							INT,
 @country_id						INT,
 @cagent_id							INT,
 @simi_dueDateFrom					DATETIME,
 @simi_dueDateTo					DATETIME
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -------------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------------
		/*
			DECLARE
			@comp_id						INT,
			@lang_id						INT,
			@simi_code						NVARCHAR(30),
			@simi_Type						INT,
			@simi_Status					INT,
			@simi_presentationDateFrom		DATETIME,
			@simi_presentationDateTo		DATETIME,
			@simi_approvalDateFrom			DATETIME,
			@simi_approvalDateTo			DATETIME,
			@simi_presentationAtLNADateFrom DATETIME,
			@simi_presentationAtLNADateTo	DATETIME,
			@simi_via						INT,
			@country_id						INT,
			@cagent_id						INT

			SELECT
			@comp_id						= 1,
			@lang_id						= 2,
			@simi_code						= '',
			@simi_Type						= -1,
			@simi_Status					= -1,
			@simi_presentationDateFrom		= '1900-01-01',
			@simi_presentationDateTo		= '9999-01-01',
			@simi_approvalDateFrom			= '1900-01-01',
			@simi_approvalDateTo			= '9999-01-01',
			@simi_presentationAtLNADateFrom = '1900-01-01',
			@simi_presentationAtLNADateTo	= '9999-01-01',
			@simi_via						= -1,
			@country_id						= -1,
			@cagent_id						= -1
		*/
		-- -------------------------------------------------------------

		SET @simi_presentationDateFrom = dbo.fnGetEnd_or_BeginOfDate(@simi_presentationDateFrom, 'False')
		SET @simi_presentationDateTo = dbo.fnGetEnd_or_BeginOfDate(@simi_presentationDateTo, 'True')

		SET @simi_approvalDateFrom = dbo.fnGetEnd_or_BeginOfDate(@simi_approvalDateFrom, 'False')
		SET @simi_approvalDateTo = dbo.fnGetEnd_or_BeginOfDate(@simi_approvalDateTo, 'True')

		SET @simi_presentationAtLNADateFrom = dbo.fnGetEnd_or_BeginOfDate(@simi_presentationAtLNADateFrom, 'False')
		SET @simi_presentationAtLNADateTo = dbo.fnGetEnd_or_BeginOfDate(@simi_presentationAtLNADateTo, 'True')

		SELECT
			' '										[ ], --UPDATE
			' '										[ ], --DELETE
			' '										[ ], --A DEFINIR
			--tis.comp_id,
			--tis.simi_id,
			tis.simi_code,
			tis2.simi_desc,
			tov.optval_desc							[simi_Status],
			tis.simi_presentationDate,
			tis.simi_approvalDate,
			tis.simi_presentationAtLNADate,
			tov2.optval_desc						[simi_via],
			tc.country_desc,
			tis.simi_total,
			tc2.curr_desc,
			tca.cagent_name,
			tis.simi_dueDate,
			tis.simi_id								[ID]
			FROM tbImport_SIMIHeader				tis
			INNER JOIN tbsysOptionsValues			tov  --ESTADO
				ON tov.lang_id		= @lang_id		AND
				tov.optval_class	= 550			AND
				tov.optval_id		= tis.simi_status
			INNER JOIN tbsysOptionsValues			tov2 --VIA
				ON tov2.lang_id		= @lang_id		AND
				tov2.optval_class	= 551			AND
				tov2.optval_id		= tis.simi_via
			INNER JOIN tbsysCountry					tc
				ON tc.country_id	= tis.country_id4Origin
			INNER JOIN tbsysCurrency				tc2
				ON tc2.curr_id		= tis.curr_id
			INNER JOIN tbCustoms_Agent				tca
				ON tca.comp_id		= tis.comp_id	AND
				tca.cagent_id		= tis.cagent_id
			INNER JOIN tbImport_SIMITypes			tis2
				ON tis2.comp_id		= tis.comp_id	AND
				tis2.simi_type		= tis.simi_type
			WHERE tis.comp_id		= @comp_id																						AND
			(@simi_code				= '' OR tis.simi_code = @simi_code)																AND
			(@simi_Type				= -1 OR tis.simi_type = @simi_Type)																AND
			(@simi_via				= -1 OR tis.simi_via  = @simi_via)																AND
			(@country_id			= -1 OR tis.country_id4Origin = @country_id)													AND
			(@cagent_id				= -1 OR tis.cagent_id = @cagent_id)																AND
			tis.simi_presentationDate					BETWEEN  @simi_presentationDateFrom AND @simi_presentationDateTo			AND
			tis.simi_approvalDate						BETWEEN @simi_approvalDateFrom AND @simi_approvalDateTo						AND
			ISNULL(tis.simi_presentationAtLNADate,'')	BETWEEN @simi_presentationAtLNADateFrom AND @simi_presentationAtLNADateTo	AND
			ISNULL(tis.simi_dueDate,'')					BETWEEN @simi_dueDateFrom AND @simi_dueDateTo

	END
GO


