CREATE PROCEDURE [dbo].[spImport_SIMIHeader_InsertData]
(
 @comp_id						INT,
 @simi_code						NVARCHAR(30),
 @simi_Type						INT,
 @simi_Status					INT,
 @simi_presentationDate			DATETIME,
 @simi_approvalDate				DATETIME,
 @simi_presentationAtLNADate	DATETIME,
 @PresentationLNADate_Null		BIT,
 @simi_via						INT,
 @country_id					INT,
 @simi_total					DECIMAL(19,4),
 @curr_id						INT,
 @cagent_id						INT,
 @simi_dueDate					DATETIME,
 @return_value					INT OUTPUT
)
AS
 BEGIN
  SET NOCOUNT ON
  SET DATEFORMAT 'YMD'

  -- -----------------------------------------------------
  -- TESTING
  -- -----------------------------------------------------
  /*
   DECLARE
   @comp_id      INT,
   @simi_code      NVARCHAR(30),
   @simi_Type      INT,
   @simi_Status     INT,
   @simi_presentationDate   DATETIME,
   @simi_approvalDate    DATETIME,
   @simi_presentationAtLNADate  DATETIME,
   @simi_via      INT,
   @country_id      INT,
   @simi_total      DECIMAL(19,4),
   @curr_id      INT,
   @cagent_id      INT,
   @return_value     INT
  */
  -- -----------------------------------------------------

  IF @PresentationLNADate_Null = 'True'
	BEGIN
		SET @simi_presentationAtLNADate = NULL
	END


  INSERT INTO tbImport_SIMIHeader
  (
   comp_id,
   simi_code,
   simi_type,
   simi_status,
   simi_presentationDate,
   simi_approvalDate,
   simi_presentationAtLNADate,
   simi_via,
   country_id4Origin,
   simi_total,
   curr_id,
   cagent_id,
   simi_dueDate
  )
  VALUES
  (
   @comp_id,
   @simi_code,
   @simi_Type,
   @simi_Status,
   @simi_presentationDate,
   @simi_approvalDate,
   @simi_presentationAtLNADate,
   @simi_via,
   @country_id,
   @simi_total,
   @curr_id,
   @cagent_id,
   @simi_dueDate
  )

  SET @return_value = @@IDENTITY

 END

GO


CREATE PROCEDURE [dbo].[spImport_SIMIHeader_UpdateData]
(
	@comp_id					INT,
	@simi_id					INT,
	@simi_code					NVARCHAR(30),
	@simi_Type					INT,
	@simi_Status				INT,
	@simi_presentationDate		DATETIME,
	@simi_approvalDate			DATETIME,
	@simi_presentationAtLNADate	DATETIME,
	@simi_via					INT,
	@country_id					INT,
	@simi_Total					DECIMAL(19,4),
	@curr_id					INT,
	@cagent_id					INT,
	@simi_dueDate				DATETIME
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		UPDATE tbImport_SIMIHeader
		SET
			simi_code					= @simi_code,
			simi_type					= @simi_Type,
			simi_status					= @simi_Status,
			simi_presentationDate		= @simi_presentationDate,
			simi_approvalDate			= @simi_approvalDate,
			simi_presentationAtLNADate	= @simi_presentationAtLNADate,
			simi_via					= @simi_via,
			country_id4Origin			= @country_id,
			simi_total					= @simi_Total,
			curr_id						= @curr_id,
			cagent_id					= @cagent_id,
			simi_dueDate				= @simi_dueDate
			WHERE	comp_id				= @comp_id	AND
					simi_id				= @simi_id
	END


GO


