CREATE PROCEDURE [dbo].[spImport_updateData]
(
	@comp_id						INT,
	@bra_id							INT,
	@import_id						INT,
	@AlternativeExchangeCurency		INT,			-- Moneda del Tipo de Cambio Alternativo
	@AlternativeExchange			DECIMAL(19,4),	-- Tipo de Cambio Alternativo
	@guid							UNIQUEIDENTIFIER,
	@user_id						INT
)
AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------------
	/*
	DECLARE
		@comp_id						INT,
		@bra_id							INT,
		@import_id						INT,
		@AlternativeExchangeCurency		INT,			-- Moneda del Tipo de Cambio Alternativo
		@AlternativeExchange			DECIMAL(19,4),	-- Tipo de Cambio Alternativo
		@guid							UNIQUEIDENTIFIER

	SELECT
		@comp_id						=1,
		@bra_id							=1,
		@import_id						=4,
		@AlternativeExchangeCurency		=1,
		@AlternativeExchange			=3.6,
		@guid							='45b7f584-70ae-4d17-981d-392a3b8c75e9'
	*/

		/*El price deberia de sacarse de la tabla temporal en la cual se cargara mediante el SP
		* que recupera los datos para mostrar en la grilla	*/
	-- -----------------------------------------------------------------------------------



	UPDATE	dbo.tbImport
	SET		import_closed		=	'True'
	WHERE		comp_id			=	@comp_id		AND
				import_id		=	@import_id


	/*********************************************************************************************************************/

	/*********************************************************************************************************************/





	/*********************************************************************************************************************/
	/*Stored Procedure que actualiza la tabla ItemCostList con el Costo y el Costo AW en base a los parametros que recibe*/

	DECLARE @litem_id			INT,
			@litvt_qty			INT,
			@litvt_price		INT,
			@lcurr_id			INT,
			@lit_storePrevious	INT,
			@stor_id			INT,
			@it_transaction		INT,
			@supp_id		    int

	DECLARE cursor_I_uD_items CURSOR LOCAL FAST_FORWARD  FOR
	SELECT	tit.item_id,
			titvt.itvt_qty,
			titvt.itvt_price,
			tit.curr_id,
			tit.it_storePrevious,
			titvt.it_transaction,
			tct.supp_id
		FROM	tbItemTransactionsValuesTmp titvt
			INNER JOIN tbItemTransactions tit
				ON	tit.comp_id			=	titvt.comp_id
				AND tit.bra_id			=	titvt.bra_id
				AND tit.ct_transaction	=	titvt.ct_transaction
				AND tit.it_transaction	=	titvt.it_transaction
			INNER JOIN tbCommercialTransactions tct
				ON		tct.comp_id			= tit.comp_id
					AND tct.ct_transaction	= tit.ct_transaction
		WHERE	titvt.itvt_guid		=	@guid

	OPEN cursor_I_uD_items

	FETCH cursor_I_uD_items
	INTO
			@litem_id,
			@litvt_qty,
			@litvt_price,
			@lcurr_id,
			@lit_storePrevious	,
			@it_transaction,
			@supp_id

	WHILE @@FETCH_STATUS = 0
	BEGIN

		-- Saca el deposito de la Transaccion Original.-
		SELECT @stor_id = tit.stor_id
			FROM tbItemTransactions tit
			WHERE	tit.comp_id			= @comp_id
				AND tit.it_transaction	= @it_transaction


		DECLARE @decStockrevious AS DECIMAL(29,6)	-- Se resta el stoock a ingresar ya que YA INGRESO y si lo dejo va a ponderar mal !!!  MOS 03-2016
		SET		@decStockrevious = ISNULL(@lit_storePrevious,0)
		SET		@decStockrevious = @decStockrevious - @litvt_qty

		EXEC spItemCostList_UpdateFromPurchase
			@comp_id,
			@bra_id,
			@litem_id,
			@litvt_qty,
			@litvt_price,
			@lcurr_id,
			@decStockrevious,
			@AlternativeExchangeCurency,
			-1,  --==MOS     Corregir tambien en la pagina que lo llama para que mande bien el tipo de cambio alternativo.!!!
			@AlternativeExchange,
			1	,		-- Actualiza CosLis_Id  (Principal, no la B)
			@stor_id,
			@supp_id,
			@user_id

		FETCH cursor_I_uD_items
		INTO
			@litem_id,
			@litvt_qty,
			@litvt_price,
			@lcurr_id,
			@lit_storePrevious	,
			@it_transaction,
			@supp_id

	END

	CLOSE cursor_I_uD_items

	DEALLOCATE cursor_I_uD_items



END














GO


CREATE PROCEDURE [dbo].[spImportCalculateCost_CloseImport]
(
	@comp_id						INT,
	@bra_id							INT,
	@import_id						INT,
	@user_id						int
)
AS
	SET NOCOUNT ON
		BEGIN
			-- ---------------------------------------------------------------------------------
			-- TESTING
			-- ---------------------------------------------------------------------------------
			/*
				DECLARE
					@comp_id						INT,
					@bra_id							INT,
					@import_id						INT
				SELECT
					@comp_id						= 1,
					@bra_id							= 1,
					@import_id						= 336
			*/
			-- ---------------------------------------------------------------------------------



			--*******************************************************
			-- PRIMERO SE CIERRA LA IMPORTACIÓN
			--*******************************************************
				UPDATE tbImport
				SET
					import_closed	= 'True'
				WHERE	comp_id		= @comp_id AND
						import_id	= @import_id
			--*******************************************************


			--*******************************************************
			-- VARIABLES DE TRABAJO PARA EL CURSOR
			--*******************************************************
				DECLARE
					@litem_id			INT,
					@litem_qty			INT,
					@litem_price		DECIMAL(30,9),
					@lcurr_id			INT,
					@lStore_Previous	INT,
					@it_transaction		INT,
					@stor_id			INT,
					@supp_id			INT
			--*******************************************************


			--************************************************************************************************************
			-- CURSOR PARA ACTUALIZAR COSTOS
			--************************************************************************************************************
				-- -----------------------------------------------------------------------------------
				-- RECUPERAMOS LA LISTA DE COSTOS ASOCIADA A LA IMPORTACIÓN, LA MONEDA DE LA MISMA
				-- Y EL TIPO DE CAMBIO
				-- -----------------------------------------------------------------------------------
					DECLARE
						@coslis_id						INT,
						@AlternativeExchangeCurrency	INT,
						@AlternativeExchange			DECIMAL(19,4)

					SELECT
						@coslis_id						= ti.coslis_id,
						@AlternativeExchangeCurrency	= ti.curr_id,
						@AlternativeExchange			= ti.import_Exchange2BranchCurrency
						FROM tbImport							ti	WITH(NOLOCK)
						WHERE	ti.comp_id		= ti.comp_id	AND
								ti.import_id	= @import_id
				-- -----------------------------------------------------------------------------------






				/*
					ANTES EN LUGAR DEL TICC.ICA_FINALCOSTWITHOUTTAXES USABA ESTO

					(
						ticc.ica_cost +
						ticc.ica_freightByItem +
						ticc.ica_insuranceByItem +
						ticc.ica_spendingInOriginByItem +
						ticc.ica_staticticsByItem +
						ticc.ica_dutiesByItem +
						ticc.ica_dumpingByItem +
						ticc.ica_internalTaxesByItem +
						ticc.ica_otherSpendingsTotalByItem
					),

				*/

				DECLARE cursor_ItemCostCalculate CURSOR LOCAL FAST_FORWARD FOR
					SELECT
						ticc.item_id,
						ticc.ica_qty,
						ticc.ica_finalCostWithOutTaxes,
						tit.curr_id,
						tit.it_storePrevious,
						tit.it_transaction,
						tit.stor_id,
						tit.supp_id
					FROM tbImport_costCalculate							ticc		WITH(NOLOCK)
					INNER JOIN tbItemTransactions						tit			WITH(NOLOCK)
						ON	tit.comp_id			= ticc.comp_id			AND
							tit.it_transaction	= ticc.it_transaction
					WHERE	ticc.comp_id		= @comp_id				AND
							ticc.import_id		= @import_id

				OPEN cursor_ItemCostCalculate
				FETCH cursor_ItemCostCalculate
				INTO
					@litem_id,
					@litem_qty,
					@litem_price,
					@lcurr_id,
					@lStore_Previous,
					@it_transaction,
					@stor_id,
					@supp_id

					WHILE @@FETCH_STATUS = 0
						BEGIN
							DECLARE @decStockrevious AS DECIMAL(29,6)	-- Se resta el stock a ingresar ya que YA INGRESO y si lo dejo va a ponderar mal !!!  MOS 03-2016
							SET		@decStockrevious = ISNULL(@lStore_Previous,0)
							--SET		@decStockrevious = @decStockrevious - @litem_qty  -- MOS 08-2022:  No se x q se puso esto ya que en tbItemTransactions en previous está el stock PREVIO al INGRESO y NO hay que restar la cantidad

							EXEC spItemCostList_UpdateFromPurchase
								@comp_id,
								@bra_id,
								@litem_id,
								@litem_qty,
								@litem_price,
								@lcurr_id,
								@decStockrevious,
								@AlternativeExchangeCurrency,	-- @AlternativeExchangeCurrency
								-1, --
								@AlternativeExchange, --@AlternativeExchange,
								@coslis_id,	--Actualizar CosLis_ID (PRINCIPAL)
								@stor_id,
								@supp_id,
								@user_id

							FETCH cursor_ItemCostCalculate
							INTO
								@litem_id,
								@litem_qty,
								@litem_price,
								@lcurr_id,
								@lStore_Previous,
								@it_transaction,
								@stor_id,
								@supp_id
						END
				CLOSE cursor_ItemCostCalculate
				DEALLOCATE cursor_ItemCostCalculate
			--************************************************************************************************************

		END
GO





CREATE procedure [dbo].[spImportCalculateCost_getHeaderData]
(
		@comp_id	INT,
		@bra_id		INT,
		@curr_id_1	INT,
		@curr_id_2	INT
)
as

set nocount on
/*
declare
		@comp_id	INT,
		@bra_id		INT,
		@curr_id_1	INT,
		@curr_id_2	INT

select
		@comp_id	= 1,
		@bra_id		= 1,
		@curr_id_1	= 1,
		@curr_id_2	= 2
*/


select
		@curr_id_1	= b.curr_id
		from dbo.tbBranch b
		where	b.bra_id = @bra_id



select
		@curr_id_2 = b.curr_id
		from	[tbsyscurrency] b
		where	b.[curr_id] = @curr_id_2



select
		--@curr_id_2															[CurrIdSel],
		(select	c.[curr_symbol]
		 from [tbsysCurrency] c
		 where c.[curr_id] = @curr_id_2)									[Currency Sel],
		1																	[Value Sel],
		--@curr_id_1															[CurrIdBranch],
		(select c.[curr_symbol]
		 from [tbBranch] b
		 inner join [tbsysCurrency] c
		 on c.[curr_id] = b.[curr_id]
		 where b.bra_id = @bra_id)											[Currency Branch],
		(dbo.[fnGetExchange](@comp_id, 1, @curr_id_2, @curr_id_1, 0, 0, 0)) [Value Branch]


GO

CREATE PROCEDURE [dbo].[spImportCalculateCostV2_CheckSum]
(
	@comp_id	INT,
	@import_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		IF ROUND((SELECT
					SUM (ticc.ica_percentage)
					FROM tbImport_costCalculate			ticc
					WHERE	ticc.comp_id	= @comp_id	AND
							ticc.import_id	= @import_id),1) = 100
			BEGIN
				SELECT 'True'
			END
		ELSE
			BEGIN
				SELECT 'False'
			END

	END
GO

CREATE PROCEDURE spImportCalculateCostV2_ExistsData
(
	@comp_id	INT,
	@import_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		IF EXISTS (	SELECT TOP 1
						1
						FROM tbImport_costCalculate			ticc
						WHERE	ticc.comp_id	= @comp_id	AND
								ticc.import_id	= @import_id)
			BEGIN
				SELECT 'True'
			END
		ELSE
			BEGIN
				SELECT 'False'
			END
	END
GO

CREATE PROCEDURE [dbo].[spImportCalculateCostV2_GetDataByFilters]
(
	@comp_id	INT,
	@import_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------
		-- TESTING
		-- -----------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@import_id	INT
			SELECT
				@comp_id	= 1,
				@import_id	= 336
		*/
		-- -----------------------------------


		SELECT
			' '											[ ],
			ti.item_code,
			ti.item_desc,
			dbo.fnGetCommercialTransactionDescription(tct.comp_id, 2, tct.ct_transaction)	[ctDesc],
			titp.posara_desc,
			ticc.ica_coef,
			ticc.ica_percentage,
			ticc.ica_cost,
			ticc.ica_qty,
			--ticc.ica_freight,
			ticc.ica_freightByItem,
			--ticc.ica_insurance,
			ticc.ica_insuranceByItem,
			--ticc.ica_spendingInOrigin,
			ticc.ica_spendingInOriginByItem,
			--ticc.ica_statictics,
			ticc.ica_staticticsByItem,
			--ticc.ica_duties,
			ticc.ica_dutiesByItem,
			--ticc.ica_dumping,
			ticc.ica_dumpingByItem,
			--ticc.ica_internalTaxes,
			ticc.ica_internalTaxesByItem,
			--ticc.ica_otherSpendingsTotal,
			ticc.ica_otherSpendingsTotalByItem,
			ticc.ica_costBeforeExtrasByItem,
			ticc.ica_localExpensesByItem,

			ticc.ica_finalCostWithOutTaxes				[Item_Cost],
			ticc.ica_finalCostWithTaxes					[Item_Cost_WithTaxes],

			ticc.ica_id									[ID]
		FROM tbImport_costCalculate						ticc	WITH(NOLOCK)
			INNER JOIN tbItem							ti		WITH(NOLOCK)
				ON	ti.comp_id = ticc.comp_id			AND
					ti.item_id = ticc.item_id
			LEFT JOIN tbImport_tariffPosition			titp	WITH(NOLOCK)
				ON	titp.comp_id	= ticc.comp_id		AND
					titp.posara_id	= ticc.posara_id
			INNER JOIN tbImport							ti2		WITH(NOLOCK)
				ON	ti2.comp_id		= ticc.comp_id		AND
					ti2.import_id	= ticc.import_id

			LEFT JOIN tbItemTransactions				tit		WITH (NOLOCK)
				ON	tit.comp_id			= ticc.comp_id AND
					tit.it_transaction	= ticc.it_transaction

			LEFT JOIN tbCommercialTransactions			tct		WITH (NOLOCK)
				ON	tct.comp_id			= tit.comp_id	AND
					tct.ct_transaction	= tit.ct_transaction


			WHERE	ticc.comp_id		= @comp_id		AND
					ticc.import_id	= @import_id

	END
GO

CREATE PROCEDURE [dbo].[spImportCalculateCostV2_PreCalculate]
(
	@comp_id	INT,
	@bra_id		INT,
	@import_id	INT,
	@UseTaxes	BIT
)
AS


	BEGIN
		SET NOCOUNT ON


		--EL IMPORTE CONVERTIDO A LA MONEDA DE LA TRANSACCION ES MAYOR QUE EL DE ITEM TRANSACTION TIENE QUE TOMAR ESE Y SINO TOMAR EL DE LA ITEM TRANSACTIONS SOLO PARA CALCULO
		--EN DERECHOS Y ESTADISTICAS HACER INNER CON  TBITEM Y ELEGIR QUE VALOR CORRESPONDE SEGUN CRITERIO ARRIBA MENCIONADO

		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@import_id	INT,
				@UseTaxes	BIT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@import_id	= 2,
				@UseTaxes	= 'True'
		*/
		-- --------------------------------------------

		-- ****************************************************************************************************************
		-- GRABAMOS EL ÚLTIMO MOVIMIENTO EN EL HISTÓRICO PARA MANTENER UN REGISTRO DE LAS MODIFICACIONES
		-- ****************************************************************************************************************
			IF EXISTS (SELECT 1 FROM tbImport_costCalculate ticc WHERE ticc.comp_id = @comp_id AND ticc.import_id = @import_id)
				BEGIN
					EXEC spImport_CostCalculateHistory_InsertDataFromImportCalculateCost @comp_id, @import_id
				END

		-- ****************************************************************************************************************

		-- ************************************************************************************************
		-- VARIABLES DE TRABAJO
		-- ************************************************************************************************
			DECLARE
				@ImportCurrency			INT,
				@ImportCurrencyExchange	DECIMAL(19,4),
				@bra_curr_id			INT

			SET @ImportCurrency			= 0
			SET @ImportCurrencyExchange	= 0
			SET @bra_curr_id			= 0
		-- ************************************************************************************************

		-- **********************************************************************
		-- GRABAMOS LA MONEDA DE LA IMPORTACIÓN Y LA COTIZACIÓN
		-- **********************************************************************
			SELECT
				@ImportCurrency			= ti.curr_id,
				@ImportCurrencyExchange	= ti.import_Exchange2BranchCurrency
			FROM tbImport							ti	WITH(NOLOCK)
			WHERE	ti.comp_id		= @comp_id		AND
					ti.import_id	= @import_id
		-- **********************************************************************

		-- ******************************************
		-- GRABAMOS LA MONEDA DE LA SUCURSAL
		-- ******************************************
			SELECT
				@bra_curr_id		= tb.curr_id
				FROM tbBranch					tb		WITH(NOLOCK)
				WHERE	tb.comp_id	= @comp_id	AND
						tb.bra_id	= @bra_id
		-- ******************************************


		-- ************************************************************************************************
		-- FLETE / FLETE POR ARTÍCULO
		-- Solo se le calcula el flete a aquellos artículos que no esten excentos de cálculo de costo
		-- ************************************************************************************************
			UPDATE tbImport_costCalculate
			SET
				ica_freight			= (ti.import_freightTotal * tmp.ica_coef),
				ica_freightByItem	= (ti.import_freightTotal * tmp.ica_coef) / dbo.fnNoZDiv(tmp.ica_qty)
				FROM tbImport_costCalculate					tmp	WITH(NOLOCK)
				INNER JOIN tbImport							ti	WITH(NOLOCK)
					ON	ti.comp_id		= tmp.comp_id		AND
						ti.import_id	= tmp.import_id
				INNER JOIN tbItem							ti2	WITH(NOLOCK)
					ON	ti2.comp_id		= tmp.comp_id		AND
						ti2.item_id		= tmp.item_id
				WHERE	tmp.comp_id		= @comp_id			AND
						tmp.import_id	= @import_id		AND
						ISNULL(ti2.item_importCost_isExent4CostCalculation,'False') = 'False'

		-- ------------------------------------------------------------------------------------------------


		-- ************************************************************************************************
		-- SEGURO / SEGURO POR ARTÍCULO
		-- ************************************************************************************************
			--SI EL PORCENTAJE DEL SEGURO ES CERO, ENTONCES TIENE QUE CALCULARLO COMO...
			--TOMAR EL VALOR CARGADO EN LA IMPORTACION
			UPDATE tbImport_costCalculate
			SET
				ica_insurance		=	CASE WHEN ((tmp.ica_cost * tmp.ica_qty) + tmp.ica_freight) * ti.import_insurancePercent = 0 THEN	ti.import_insuranceTotal
										ELSE																								((tmp.ica_cost * tmp.ica_qty) + tmp.ica_freight) * ti.import_insurancePercent
				             		 	END,
				ica_insuranceByItem =	CASE WHEN ((tmp.ica_cost * tmp.ica_qty) + tmp.ica_freight) * ti.import_insurancePercent = 0 THEN	ti.import_insuranceTotal / dbo.fnNoZDiv(tmp.ica_qty)
										ELSE																								(((tmp.ica_cost * tmp.ica_qty) + tmp.ica_freight) * ti.import_insurancePercent) / dbo.fnNoZDiv(tmp.ica_qty)
				             		 	END
				--ica_insurance		= (ti.import_insuranceTotal * tmp.ica_coef),
				--ica_insuranceByItem = (ti.import_insuranceTotal * tmp.ica_coef) / tmp.ica_qty
				FROM tbImport_costCalculate				tmp		WITH(NOLOCK)
				INNER JOIN tbImport						ti		WITH(NOLOCK)
					ON	ti.comp_id		= tmp.comp_id	AND
						ti.import_id	= tmp.import_id
				WHERE	tmp.comp_id		= @comp_id		AND
						tmp.import_id	= @import_id
		-- ************************************************************************************************

		-- ************************************************************************************************
		-- GASTOS EN ORIGEN
		-- Solo se le calcula el gasto en origen a aquellos artículos que no esten excentos de cálculo de costo
		-- ************************************************************************************************
			UPDATE tbImport_costCalculate
			SET
				ica_spendingInOrigin		= (ti.import_originExpensesTotal * tmp.ica_coef),
				ica_spendingInOriginByItem	= (ti.import_originExpensesTotal * tmp.ica_coef) / dbo.fnNoZDiv(tmp.ica_qty)
				FROM tbImport_costCalculate				tmp		WITH(NOLOCK)
				INNER JOIN tbImport						ti		WITH(NOLOCK)
					ON	ti.comp_id		= tmp.comp_id	AND
						ti.import_id	= tmp.import_id
				INNER JOIN tbItem						ti2		WITH(NOLOCK)
					ON	ti2.comp_id		= tmp.comp_id	AND
						ti2.item_id		= tmp.item_id
				WHERE	tmp.comp_id		= @comp_id		AND
						tmp.import_id	= @import_id	AND
						ISNULL(ti2.item_importCost_isExent4CostCalculation,'False') = 'False'

		-- ************************************************************************************************

		-- ************************************************************************************************
		-- ESTADISTICA
		-- ************************************************************************************************
			UPDATE tbImport_costCalculate
			SET
				--ica_statictics			= (tmp.ica_cost + tmp.ica_freightByItem + tmp.ica_insuranceByItem + tmp.ica_spendingInOriginByItem) * titp.posara_statisticsPercentage



				ica_statictics			=	CASE
												WHEN		dbo.[fnGetExchange](ti.comp_id, ISNULL(ti.item_import_CriteriaValue,0),ISNULL(ti.curr_id_import_CriteriaValue,1), @ImportCurrency, 0, 0, 0) > tmp.ica_cost
													THEN		(dbo.[fnGetExchange](ti.comp_id, ISNULL(ti.item_import_CriteriaValue,0),ISNULL(ti.curr_id_import_CriteriaValue,1), @ImportCurrency, 0, 0, 0) + tmp.ica_freightByItem + tmp.ica_insuranceByItem + tmp.ica_spendingInOriginByItem) * titp.posara_statisticsPercentage
												ELSE 			(tmp.ica_cost + tmp.ica_freightByItem + tmp.ica_insuranceByItem + tmp.ica_spendingInOriginByItem) * titp.posara_statisticsPercentage
											END

				FROM tbImport_costCalculate				tmp		WITH(NOLOCK)
				INNER JOIN tbImport_tariffPosition		titp	WITH(NOLOCK)
					ON	titp.comp_id	= tmp.comp_id	AND
						titp.posara_id	= tmp.posara_id

				INNER JOIN tbItem						AS ti	WITH(NOLOCK)
				ON	ti.comp_id			= tmp.comp_id	AND
					ti.item_id			= tmp.item_id

				WHERE	tmp.comp_id		= @comp_id		AND
						tmp.import_id	= @import_id


			--SI EXCEDE EL VALOR MAXIMO PARA ESTADISTICAS, HACEMOS QUE TOME EL VALOR MAXIMO PARA ESTADISTICAS
			UPDATE tbImport_costCalculate
			SET
				ica_statictics =	CASE WHEN ica_statictics > titp.posara_statisticsMaxValue
									THEN titp.posara_statisticsMaxValue
									ELSE ica_statictics END
				FROM tbImport_costCalculate				tmp		WITH(NOLOCK)
				INNER JOIN tbImport_tariffPosition		titp	WITH(NOLOCK)
					ON	titp.comp_id	= tmp.comp_id	AND
						titp.posara_id	= tmp.posara_id
				WHERE	tmp.comp_id		= @comp_id		AND
						tmp.import_id	= @import_id

			UPDATE tbImport_costCalculate
			SET
				ica_staticticsByItem	= tmp.ica_statictics / dbo.fnNoZDiv(tmp.ica_qty)
				FROM tbImport_costCalculate				tmp		WITH(NOLOCK)
				INNER JOIN tbImport_tariffPosition		titp	WITH(NOLOCK)
					ON	titp.comp_id	= tmp.comp_id	AND
						titp.posara_id	= tmp.posara_id
				WHERE	tmp.comp_id		= @comp_id		AND
						tmp.import_id	= @import_id


		-- ************************************************************************************************


		-- ************************************************************************************************
		-- DERECHOS
		-- ************************************************************************************************
			UPDATE tbImport_costCalculate
			SET
				--ica_duties		= (((tmp.ica_cost * tmp.ica_qty) + tmp.ica_freight + tmp.ica_insurance + tmp.ica_spendingInOrigin) * titp.posara_dutiesPercentage) / 100,
				--ica_dutiesByItem	= ((((tmp.ica_cost * tmp.ica_qty) + tmp.ica_freight + tmp.ica_insurance + tmp.ica_spendingInOrigin) * titp.posara_dutiesPercentage) / 100) / tmp.ica_qty


				ica_duties			=	CASE
											WHEN	dbo.[fnGetExchange](ti.comp_id, ISNULL(ti.item_import_CriteriaValue,0), ISNULL(ti.curr_id_import_CriteriaValue,1), @ImportCurrency, 0, 0, 0) > tmp.ica_cost
												THEN	(((dbo.[fnGetExchange](ti.comp_id, ISNULL(ti.item_import_CriteriaValue,0), ISNULL(ti.curr_id_import_CriteriaValue,0), @ImportCurrency, 0, 0, 0) * tmp.ica_qty) + tmp.ica_freight + tmp.ica_insurance + tmp.ica_spendingInOrigin) * titp.posara_dutiesPercentage) / 100
											ELSE		(((tmp.ica_cost * tmp.ica_qty) + tmp.ica_freight + tmp.ica_insurance + tmp.ica_spendingInOrigin) * titp.posara_dutiesPercentage) / 100
										END,
				ica_dutiesByItem	=	CASE
											WHEN	dbo.[fnGetExchange](ti.comp_id, ISNULL(ti.item_import_CriteriaValue,0), ISNULL(ti.curr_id_import_CriteriaValue,1), @ImportCurrency, 0, 0, 0) > tmp.ica_cost
												THEN	(((( dbo.[fnGetExchange](ti.comp_id, ISNULL(ti.item_import_CriteriaValue,0), ISNULL(ti.curr_id_import_CriteriaValue,0), @ImportCurrency, 0, 0, 0) * tmp.ica_qty) + tmp.ica_freight + tmp.ica_insurance + tmp.ica_spendingInOrigin) * titp.posara_dutiesPercentage) / 100) / tmp.ica_qty
										ELSE 			((((tmp.ica_cost * tmp.ica_qty) + tmp.ica_freight + tmp.ica_insurance + tmp.ica_spendingInOrigin) * titp.posara_dutiesPercentage) / 100) / tmp.ica_qty
										END

				FROM	tbImport_costCalculate			tmp		WITH(NOLOCK)
				INNER JOIN tbImport_tariffPosition		titp	WITH(NOLOCK)
					ON	titp.comp_id	= tmp.comp_id	AND
						titp.posara_id	= tmp.posara_id

				INNER JOIN tbItem						AS ti	WITH(NOLOCK)
				ON	ti.comp_id			= tmp.comp_id	AND
					ti.item_id			= tmp.item_id


				WHERE	tmp.comp_id		= @comp_id		AND
						tmp.import_id	= @import_id
		-- ************************************************************************************************

		-- ************************************************************************************************
		-- DUMPING
		-- ************************************************************************************************
			UPDATE tbImport_costCalculate
			SET
				ica_dumping			= ISNULL(tmp.ica_dumping,0) * ISNULL(tmp.ica_coef,0),
				ica_dumpingByItem	= (ISNULL(tmp.ica_dumping,0) * ISNULL(tmp.ica_coef,0)) / dbo.fnNoZDiv(tmp.ica_qty)
				FROM tbImport_costCalculate					tmp		WITH(NOLOCK)
					INNER JOIN tbImport						ti		WITH(NOLOCK)
						ON	ti.comp_id		= tmp.comp_id	AND
							ti.import_id	= tmp.import_id
				WHERE	tmp.comp_id			= @comp_id		AND
						tmp.import_id		= @import_id

		-- ************************************************************************************************
		-- OTROS GASTOS
		-- ************************************************************************************************
			UPDATE tbImport_costCalculate
			SET
				ica_otherSpendingsTotal			= ISNULL(tmp.ica_otherSpendingsTotal,0) * ISNULL(tmp.ica_coef,0),
				ica_otherSpendingsTotalByItem	= (ISNULL(tmp.ica_otherSpendingsTotal,0) * ISNULL(tmp.ica_coef,0)) / dbo.fnNoZDiv(tmp.ica_qty)
				FROM tbImport_costCalculate					tmp	WITH(NOLOCK)
				INNER JOIN tbImport							ti	WITH(NOLOCK)
					ON	ti.comp_id			= tmp.comp_id	AND
						ti.import_id		= tmp.import_id
				WHERE	tmp.comp_id			= @comp_id		AND
						tmp.import_id		= @import_id
		-- ************************************************************************************************



		-- ************************************************************************************************
		-- ACA CALCULAMOS LOS GASTOS LOCALES (SON LOS DOCUMENTOS QUE SE ASOCIAN A LA IMPORTACIÓN
		-- QUE NO TIENEN RELACIONADO UN SIMI_ID Y UN SIMID_ID
		-- ************************************************************************************************

			--CALCULO EL COSTO DE CADA ARTÍCULO ANTES DE SUMARLE LOS EXTRAS
			UPDATE tbImport_costCalculate
			SET
				ica_costBeforeExtrasByItem		= (
													ISNULL(ticc.ica_cost,0)						+
													ISNULL(ticc.ica_freightByItem,0)			+
													ISNULL(ticc.ica_insuranceByItem,0)			+
													ISNULL(ticc.ica_spendingInOriginByItem,0)	+
													ISNULL(ticc.ica_staticticsByItem,0)			+
													ISNULL(ticc.ica_dutiesByItem,0)				+
													ISNULL(ticc.ica_dumpingByItem,0)			+
													ISNULL(ticc.ica_internalTaxesByItem,0)		+
													ISNULL(ticc.ica_otherSpendingsTotalByItem,0)
												  )
				FROM tbImport_costCalculate			ticc	WITH(NOLOCK)
				WHERE	ticc.comp_id	= @comp_id	AND
						ticc.import_id	= @import_id


			--UNA VEZ CALCULADO EL COSTO SIN EXTRAS POR ARTÍCULO PROCEDEMOS A SUMARLE LOS EXTRAS
			DECLARE
				@decInternalExpenses	DECIMAL(24,2)
			SET @decInternalExpenses	= 0

		-- ************************************************************************************************


		-- ************************************************************************************************
		-- SUMAMOS TODOS LOS GASTOS DE IMPORTACIONES
		-- ************************************************************************************************
			SELECT
				@decInternalExpenses =	ISNULL(SUM(
												ISNULL(dbo.fnGetExchange2(tie.comp_id, tie.importex_Total, tie.curr_id , @ImportCurrency, @ImportCurrency, @bra_curr_id, @ImportCurrencyExchange,'False'),0)
											),0)
				FROM tbImportExpenses						tie	WITH(NOLOCK)
				WHERE	tie.comp_id			= @comp_id		AND
						tie.import_id		= @import_id	AND
						tie.importex_Total	> 0

		-- ************************************************************************************************

		-- ************************************************************************************************
		-- SUMAMOS TODOS LOS GASTOS DE CONCEPTOS QUE NO ESTEN EXCLUIDOS PARA CALCULO DE COSTOS
		-- ************************************************************************************************
			SELECT
				@decInternalExpenses = @decInternalExpenses +
				ISNULL(
						SUM(
							dbo.fnGetExchange2(ti.comp_id, tpcm.pcm_total, tpcm.curr_id ,@ImportCurrency, @ImportCurrency, @bra_curr_id, @ImportCurrencyExchange,'False')
						   ),0)
				FROM tbImportDetail								tid		WITH(NOLOCK)
				INNER JOIN tbImport								ti		WITH(NOLOCK)
					ON	ti.comp_id			= tid.comp_id		AND
						ti.import_id		= tid.import_id
				INNER JOIN tbCommercialTransactions				tct		WITH(NOLOCK)
					ON	tct.comp_id			= tid.comp_id		AND
						tct.ct_transaction	= tid.ct_transaction
				INNER JOIN tbPurchaseConceptMovements			tpcm	WITH(NOLOCK)
					ON	tpcm.comp_id		= tct.comp_id		AND
						tpcm.ct_transaction = tct.ct_transaction
				INNER JOIN tbPurchaseConcept					tpc		WITH(NOLOCK)
					ON	tpc.comp_id			= tpcm.comp_id		AND
						tpc.puco_id			= tpcm.puco_id

				WHERE	tid.comp_id			= @comp_id			AND
						tid.import_id		= @import_id		AND
						ISNULL(tpc.puco_importCost_isExentConcept,'False') = 'False'

		-- ************************************************************************************************

		-- ******************************************************************************************
		-- COEFICIENTE DE GASTOS
		-- ******************************************************************************************
			DECLARE
				@DocumentTotal	DECIMAL(30,4),
				@ExpensesCoef	DECIMAL(30,4)
			SET @DocumentTotal	= 0
			SET @ExpensesCoef	= 0

			SELECT
				@DocumentTotal			= SUM(ticc.ica_cost * ticc.ica_qty)
				FROM tbImport_costCalculate			ticc
				WHERE	ticc.comp_id	= @comp_id	AND
						ticc.import_id	= @import_id

			SET @ExpensesCoef = @decInternalExpenses / dbo.fnNoZDiv(@DocumentTotal)

			--==TESTING
			--SELECT
			--	@ExpensesCoef			[ExpensesCoef],
			--	@decInternalExpenses	[InternalExpenses],
			--	@DocumentTotal			[DocumentTotal]
			--==

		-- ******************************************************************************************

		-- ************************************************************************************************
		-- SI LA DIFERENCIA DEL FLETE LA CARGAN EN LOS GASTOS DE IMPORTACIÓN NO ES NECESARIO RESTARLE EL FLETE
		-- ************************************************************************************************
			UPDATE tbImport_costCalculate
			SET
				ica_localExpenses		= (tmp.ica_cost * tmp.ica_qty) * @ExpensesCoef,
				ica_localExpensesByItem = ((tmp.ica_cost * tmp.ica_qty) * @ExpensesCoef) / dbo.fnNoZDiv(tmp.ica_qty)
				FROM tbImport_costCalculate					tmp		WITH(NOLOCK)
				INNER JOIN tbImport							ti		WITH(NOLOCK)
					ON	ti.comp_id		= tmp.comp_id		AND
						ti.import_id	= tmp.import_id
				WHERE	tmp.comp_id		= @comp_id			AND
						tmp.import_id	= @import_id

		-- ******************************************************************************************

		-- ******************************************************************************************
		-- UNA VEZ CALCULADOS TODOS LOS EXTRAS ACTUALIZAMOS EL COSTO FINAL DEL ARTÍCULO SIN IVA
		-- COSTO ANTES DE EXTRAS + GASTOS INTERNOS
		-- ******************************************************************************************

			UPDATE tbImport_costCalculate
			SET
				ica_finalCostWithOutTaxes			= ticc.ica_costBeforeExtrasByItem + ticc.ica_localExpensesByItem-- + @TotalsByPercentajeAditionals
				FROM tbImport_costCalculate			ticc		WITH(NOLOCK)
				WHERE	ticc.comp_id	= @comp_id	AND
						ticc.import_id	= @import_id

		-- ******************************************************************************************

		--*******************************************************************************************
		--ACTUALIZAMOS EL COSTO FINAL Y LE SUMAMOS LOS PORCENTAJES ADICIONALES QUE ESTEN MARCADOS
		--PARA SUMARSE ANTES DE IMPUESTOS
		--*******************************************************************************************
		UPDATE tbImport_costCalculate
			SET
				ica_finalCostWithOutTaxes			= ica_finalCostWithOutTaxes + (ticc.ica_cost) * tie.importex_Percentage / ticc.ica_qty
				FROM tbImport_costCalculate			ticc		WITH(NOLOCK)
				INNER JOIN tbImportExpenses						tie
						ON	tie.comp_id			= ticc.comp_id		AND
							tie.import_id		= ticc.import_id
				WHERE	ticc.comp_id			= @comp_id			AND
						ticc.import_id			= @import_id		AND
						tie.importex_Percentage > 0					AND
						ISNULL(tie.importex_PercentageBeforeTaxes,'False')	= 'True'
		--*******************************************************************************************

		--*******************************************************************************************
		--ACTUALIZAMOS EL COSTO FINAL Y LE SUMAMOS EL IVA EN CASO DE QUE ESTE TILDADA LA OPCIÓN
		--*******************************************************************************************

			IF @UseTaxes = 'True'
				BEGIN
					--ACTUALIZAMOS EL COSTO FINAL
					UPDATE tbImport_costCalculate
					SET
						ica_finalCostWithTaxes  				= ticc.ica_finalCostWithOutTaxes + (ticc.ica_finalCostWithOutTaxes * ttn.tax_percentage) / 100
						FROM tbImport_costCalculate				ticc		WITH(NOLOCK)
							LEFT JOIN tbTaxName					ttn
							ON	ttn.comp_id		= ticc.comp_id	AND
								ttn.tax_id		= ticc.tax_id
						WHERE	ticc.comp_id	= @comp_id		AND
								ticc.import_id	= @import_id

				END

		--*******************************************************************************************


		--*******************************************************************************************
		--SUMO LOS PORCENTAJES ADICIONALES
		-- NOTA SE CAMBIO LO ANTERIOR POR EL CÁLCULO DE LOS PORCENTAJES SOBRE EL FOB Y NO SOBRE EL DDP
		--*******************************************************************************************

			UPDATE tbImport_costCalculate
			SET
				ica_finalCostWithOutTaxes			= ica_finalCostWithOutTaxes + (ticc.ica_cost) * tie.importex_Percentage / ticc.ica_qty
				FROM tbImport_costCalculate			ticc		WITH(NOLOCK)
				INNER JOIN tbImportExpenses						tie
						ON	tie.comp_id			= ticc.comp_id		AND
							tie.import_id		= ticc.import_id
				WHERE	ticc.comp_id			= @comp_id			AND
						ticc.import_id			= @import_id		AND
						tie.importex_Percentage > 0					AND
						ISNULL(tie.importex_PercentageBeforeTaxes,'False')	= 'False'

			IF @UseTaxes = 'True'
				BEGIN
					UPDATE tbImport_costCalculate
					SET
						ica_finalCostWithTaxes				= ica_finalCostWithTaxes	+ (ticc.ica_qty * ticc.ica_cost) * tie.importex_Percentage / ticc.ica_qty
						FROM tbImport_costCalculate			ticc		WITH(NOLOCK)
						INNER JOIN tbImportExpenses						tie
								ON	tie.comp_id			= ticc.comp_id		AND
									tie.import_id		= ticc.import_id
						WHERE	ticc.comp_id			= @comp_id			AND
								ticc.import_id			= @import_id		AND
								tie.importex_Percentage > 0					AND
								ISNULL(tie.importex_PercentageBeforeTaxes,'False')	= 'False'

				END
		--*******************************************************************************************






	END
GO


CREATE PROCEDURE [dbo].[spImportCalculateCostV2_Proration]
(
	@comp_id		INT,
	@bra_id			INT,
	@import_id		INT,
	@ProrrationType	INT,			-- 1 = PESO / 2 = CANTIDAD / 3 = VOLUMEN / 4 = PORCENTAJE DE COMPRA
	@Exists			BIT,
	@user_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		--***************************************************************************************************
		-- VERSIONADO DEL SP
		--***************************************************************************************************
		/*
			25-08-2016 STL - CAMBIE LOS INNER JOIN CONTRA LA POD, SIMI_DETAIL y TARIFFPOSITION por LEFT JOIN
			25-08-2016 STL - QUITÉ LOS JOINS AL INSERTAR EN LA TABLA DE CALCULO DE COSTOS YA QUE NO UTILIZABA
							 NINGÚN CAMPO



		*/
		--***************************************************************************************************

		-- --------------------------------------------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@import_id		INT,
				@ProrrationType	INT,		-- 1 = PESO / 2 = CANTIDAD / 3 = VOLUMEN / 4 = PORCENTAJE DE COMPRA
				@Exists			BIT
			SELECT
				@comp_id		= 1,
				@bra_id			= 1,
				@import_id		= 369,
				@ProrrationType	= 2,
				@Exists			= 'False'
		*/
		-- --------------------------------------------------------------------------------------------------

		-- ****************************************************************************************************************
		-- GRABAMOS EL ÚLTIMO MOVIMIENTO EN EL HISTÓRICO PARA MANTENER UN REGISTRO DE LAS MODIFICACIONES
		-- ****************************************************************************************************************
			IF EXISTS (SELECT 1 FROM tbImport_costCalculate ticc WHERE ticc.comp_id = @comp_id AND ticc.import_id = @import_id)
				BEGIN
					EXEC spImport_CostCalculateHistory_InsertDataFromImportCalculateCost @comp_id, @import_id
				END

		-- ****************************************************************************************************************

		-- ************************************************************************************************
		-- SI YA EXISTE LA IMPORTACIÓN CARGADA
		-- ************************************************************************************************

			IF EXISTS(SELECT 1
							FROM tbImport_costCalculate			ticc	WITH(NOLOCK)
							WHERE	ticc.comp_id	= @comp_id	AND
									ticc.import_id	= @import_id)
				BEGIN
					SET @Exists = 'True'
				END
			ELSE
				BEGIN
					SET @Exists = 'False'
				END

		-- ************************************************************************************************

		-- ************************************************************************************************
		-- VARIABLES DE TRABAJO
		-- ************************************************************************************************
			DECLARE
				@CoeficienteProrrateo	DECIMAL(25,6),
				@ImportCurrency			INT,
				@ImportCurrencyExchange	DECIMAL(19,4),
				@bra_curr_id			INT

			SET @CoeficienteProrrateo	= 0
			SET @ImportCurrency			= 0
			SET @ImportCurrencyExchange	= 0
			SET @bra_curr_id			= 0
		-- ************************************************************************************************

		-- **********************************************************************
		-- GRABAMOS LA MONEDA DE LA IMPORTACIÓN Y LA COTIZACIÓN
		-- **********************************************************************
			SELECT
				@ImportCurrency			= ti.curr_id,
				@ImportCurrencyExchange	= ti.import_Exchange2BranchCurrency
			FROM tbImport							ti
			WHERE	ti.comp_id		= @comp_id		AND
					ti.import_id	= @import_id
		-- **********************************************************************

		-- ******************************************
		-- GRABAMOS LA MONEDA DE LA SUCURSAL
		-- ******************************************
			SELECT
				@bra_curr_id		= tb.curr_id
				FROM tbBranch tb
				WHERE	tb.comp_id	= @comp_id AND
						tb.bra_id	= @bra_id
		-- ******************************************

		-- ********************************************************************************************************************************************************************************
		-- GRABAMOS LA SUMA TOTAL QUE VAMOS A UTILIZAR PARA EL COEFICIENTE DE PRORRATEO
		-- ********************************************************************************************************************************************************************************
			-- 1 POR PESO
			-- 2 POR PRECIO
			-- 3 POR VOLUMEN
			-- 4 POR PORCENTAJE DE COMPRA

			SELECT
				@CoeficienteProrrateo  =	CASE @ProrrationType
												WHEN 1 THEN SUM(tit.it_qty * ISNULL(ti2.item_weight,0))
												WHEN 2 THEN SUM(tit.it_qty * dbo.fnGetExchange2(ti.comp_id, tit.it_price, tit.curr_id ,@ImportCurrency,  @bra_curr_id, @ImportCurrency, @ImportCurrencyExchange,'False'))
												WHEN 3 THEN SUM(tit.it_qty * ISNULL(ti2.item_volume,0))
												WHEN 4 THEN SUM(tit.it_qty)
												ELSE ''
											END


				FROM tbImportDetail								tid		WITH(NOLOCK)
				INNER JOIN tbImport								ti		WITH(NOLOCK)
					ON	ti.comp_id			= tid.comp_id		AND
						ti.import_id		= tid.import_id
				INNER JOIN tbCommercialTransactions				tct		WITH(NOLOCK)
					ON	tct.comp_id			= tid.comp_id		AND
						tct.ct_transaction	= tid.ct_transaction
				INNER JOIN tbItemTransactions					tit		WITH(NOLOCK)
					ON	tit.comp_id			= tct.comp_id		AND
						tit.ct_transaction	= tct.ct_transaction
				INNER JOIN tbItem								ti2
					ON	ti2.comp_id			= tid.comp_id		AND
						ti2.item_id			= tit.item_id
				WHERE	tid.comp_id			= @comp_id			AND
						tid.import_id		= @import_id

		-- ********************************************************************************************************************************************************************************



		-- ************************************************************************************************
		-- TABLA DE TRABAJO
		-- ************************************************************************************************
			DECLARE @tblImport_CostCalculate  TABLE(
														comp_id							INT,
														import_id						INT,
														it_transaction					INT,
														item_id							INT,
														posara_id						INT,
														ica_coef						DECIMAL(30,10),
														ica_percentage					DECIMAL(30,10),
														ica_cost						DECIMAL(25,6),
														ica_qty							DECIMAL(19,4),
														tax_id							INT,
														prorration_type					INT,
														[user_id]						INT
													)
		-- ************************************************************************************************

		--******************************************************************************************
		-- GRABAMOS LOS REGISTROS PARA PRORATEAR EN LA TABLA TEMPORAL
		--******************************************************************************************
			INSERT INTO @tblImport_CostCalculate
			(
				comp_id,
				import_id,
				it_transaction,
				item_id,
				posara_id,
				ica_coef,
				ica_percentage,
				ica_cost,
				ica_qty,
				tax_id,
				prorration_type,
				[user_id]
			)
			SELECT
				tid.comp_id,
				tid.import_id,
				tit.it_transaction,
				tit.item_id,
				ISNULL(titp.posara_id, ti2.posara_id),
				(
					CASE @ProrrationType
						WHEN 1 THEN ((tit.it_qty * ISNULL(ti2.item_weight,0)) / dbo.fnNoZDiv(@CoeficienteProrrateo))
						WHEN 2 THEN ((tit.it_qty * dbo.fnGetExchange2(tit.comp_id, tit.it_price, tit.curr_id, ti.curr_id, @bra_curr_id, ti.curr_id, ti.import_Exchange2BranchCurrency, 'False')) / dbo.fnNoZDiv(@CoeficienteProrrateo))
						WHEN 3 THEN ((tit.it_qty * ISNULL(ti2.item_volume,0)) / dbo.fnNoZDiv(@CoeficienteProrrateo))
						WHEN 4 THEN ((tit.it_qty) /dbo.fnNoZDiv(@CoeficienteProrrateo))
						ELSE ''
					END
				),
				(
					CASE @ProrrationType
						WHEN 1 THEN ((tit.it_qty * ISNULL(ti2.item_weight,0)) / dbo.fnNoZDiv(@CoeficienteProrrateo))
						WHEN 2 THEN ((tit.it_qty * dbo.fnGetExchange2(tit.comp_id, tit.it_price, tit.curr_id, ti.curr_id, @bra_curr_id, ti.curr_id, ti.import_Exchange2BranchCurrency, 'False')) / dbo.fnNoZDiv(@CoeficienteProrrateo))
						WHEN 3 THEN ((tit.it_qty * ISNULL(ti2.item_volume,0)) / dbo.fnNoZDiv(@CoeficienteProrrateo))
						WHEN 4 THEN ((tit.it_qty) /dbo.fnNoZDiv(@CoeficienteProrrateo))
						ELSE ''
					END
				) * 100,
				tit.it_price,
				tit.it_qty,
				tpod.tax_id,
				@ProrrationType,
				@user_id
				FROM tbImportDetail									tid		WITH(NOLOCK)
					INNER JOIN tbImport								ti		WITH(NOLOCK)
						ON	ti.comp_id			= tid.comp_id		AND
							ti.import_id		= tid.import_id
					INNER JOIN tbCommercialTransactions				tct		WITH(NOLOCK)
						ON	tct.comp_id			= tid.comp_id		AND
							tct.ct_transaction	= tid.ct_transaction
					INNER JOIN tbItemTransactions					tit		WITH(NOLOCK)
						ON	tit.comp_id			= tct.comp_id		AND
							tit.ct_transaction	= tct.ct_transaction
					INNER JOIN tbItem								ti2		WITH(NOLOCK)
						ON	ti2.comp_id			= tit.comp_id		AND
							ti2.item_id			= tit.item_id
					LEFT JOIN tbPurchaseOrderDetail					tpod	WITH(NOLOCK)
						ON	tpod.comp_id		= tit.comp_id		AND
							tpod.poh_id			= tit.it_poh_id		AND
							tpod.pod_id			= tit.it_pod_id
					LEFT JOIN tbImport_SIMIDetail					tis		WITH(NOLOCK)
						ON	tis.comp_id			= tpod.comp_id		AND
							tis.simi_id			= tpod.simi_id		AND
							tis.simid_id		= tpod.simid_id
					LEFT JOIN tbImport_tariffPosition				titp	WITH(NOLOCK)
						ON	titp.comp_id		= tis.comp_id		AND
							titp.posara_id		= tis.posara_id
					WHERE	tid.comp_id			= @comp_id			AND
							tid.import_id		= @import_id

		--******************************************************************************************



		--******************************************************************************************
		--SI LA IMPORTACION QUE VIENE COMO PARAMETRO YA EXISTE, PRORATEAMOS Y SOLO ACTUALIZAMOS
		--SI LA IMPORTACION NO EXISTE, PRORATEAMOS E INSERTAMOS LOS REGISTROS EN LA TABLA FINAL
		--******************************************************************************************

			IF @Exists = 'False'
				BEGIN

					--INSERTAMOS LOS REGISTROS CORRESPONDIENTES A LA IMPORTACIÓN
					INSERT INTO tbImport_costCalculate
					(
						comp_id,
						import_id,
						it_transaction,
						item_id,
						posara_id,
						ica_coef,
						ica_percentage,
						ica_cost,
						ica_qty,
						ica_incidencepercentage,
						tax_id,
						ica_ProrrationType,
						[user_id]
					)
					SELECT
						tmp.comp_id,
						tmp.import_id,
						tmp.it_transaction,
						tmp.item_id,
						tmp.posara_id,
						tmp.ica_coef,
						tmp.ica_percentage,
						tmp.ica_cost,
						tmp.ica_qty,
						(tmp.ica_cost * tmp.ica_qty) / dbo.fnNoZDiv(@CoeficienteProrrateo),
						tmp.tax_id,
						tmp.prorration_type,
						tmp.[user_id]
						FROM @tblImport_CostCalculate				tmp
						--INNER JOIN tbItem							ti		WITH(NOLOCK)
						--	ON	ti.comp_id = tmp.comp_id			AND
						--		ti.item_id = tmp.item_id
						--INNER JOIN tbImport_tariffPosition			titp	WITH(NOLOCK)
						--	ON	titp.comp_id	= tmp.comp_id		AND
						--		titp.posara_id	= tmp.posara_id
						--INNER JOIN tbImport							ti2		WITH(NOLOCK)
						--	ON	ti2.comp_id		= tmp.comp_id		AND
						--		ti2.import_id	= tmp.import_id
						WHERE	tmp.comp_id		= @comp_id			AND
								tmp.import_id	= @import_id

				END
			ELSE
				BEGIN

					UPDATE tbImport_costCalculate
					SET
						ica_coef			= tmp.ica_coef,
						ica_percentage		= tmp.ica_percentage,
						ica_ProrrationType	= tmp.prorration_type,
						[user_id]			= @user_id
					FROM tbImport_costCalculate					ticc			WITH(NOLOCK)
					INNER JOIN @tblImport_CostCalculate			tmp
						ON	tmp.comp_id		= ticc.comp_id		AND
							tmp.import_id	= ticc.import_id	AND
							tmp.item_id		= ticc.item_id
					WHERE	ticc.comp_id	= @comp_id			AND
							ticc.import_id	= @import_id

				END


			--ACA DEBERIAMOS BORRAR EL RESTO DE LOS VALORES POR CADA VEZ QUE SE PRORRATEA PARA EVITAR QUE
			--UN PRORRATEO NUEVO QUEDE CON VALORES DE PRECALCULO VIEJOS

			UPDATE tbImport_costCalculate
			SET
				ica_freight						= 0,
				ica_freightByItem				= 0,
				ica_insurance					= 0,
				ica_insuranceByItem				= 0,
				ica_spendingInOrigin			= 0,
				ica_spendingInOriginByItem		= 0,
				ica_statictics					= 0,
				ica_staticticsByItem			= 0,
				ica_duties						= 0,
				ica_dutiesByItem				= 0,
				ica_dumping						= 0,
				ica_dumpingByItem				= 0,
				ica_internalTaxes				= 0,
				ica_internalTaxesByItem			= 0,
				ica_otherSpendingsTotal			= 0,
				ica_otherSpendingsTotalByItem	= 0,
				ica_localExpenses				= 0,
				ica_localExpensesByItem			= 0,
				ica_costBeforeExtrasByItem		= 0,
				ica_finalCostWithOutTaxes		= 0,
				ica_ExpensesCoeficient			= 0,
				ica_ExpensesCoeficientByItem	= 0,
				ica_finalCostWithTaxes			= 0

			WHERE	comp_id		= @comp_id		AND
					import_id	= @import_id

		--******************************************************************************************

	END
GO






