(
	@comp_id					AS INT,
	@impData_id					AS INT,
	@blocked4SOPreparation		AS BIT
)

AS




BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
						@comp_id				 as INT


*/

	-- -----------------------------------------------------------------------



	UPDATE tbImportData
	SET
