CREATE procedure [dbo].[spImportData_GetData4GenericGrid]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@user_id						INT,
	@prof_id						INT,
	@impData_id						INT
)
as

BEGIN


SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



---------------------------------------------------------------------------------------------
-- TEST
---------------------------------------------------------------------------------------------
/*
	DECLARE

		@comp_id						INT = 1,
		@lang_id						INT = 2,
		@bra_id							INT = 1,
		@user_id						INT = 1,
		@prof_id						INT = 1,
		@impData_id						INT

	SELECT
		@comp_id						= 1,
		@lang_id						= 2,
		@impData_id						= 1333

	*/

	---------------------------------------------------------------------------------------------
	---------------------------------------------------------------------------------------------


		SELECT
			tct.ct_date																						[ct_date],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)				[ct_transaction],
			tc.cust_id																						[cust_id],
			tc.cust_name																					[cust_name],
			tit.it_qty																						[QTY],

			tid.impData_Custom_local																		[impData_Custom_local],
			tid.impData_Number_local																		[impData_Number_local],

			tid.impData_Origin																				[impData_Origin],
			tid.impData_From																				[impData_From],
			tid.impdata_Stamp																				[impdata_Stamp],
			tid.impdata_LotNumber																			[impdata_LotNumber],
			tid.impData_ExpirationDate																		[impData_ExpirationDate],
			ti.item_code																					[item_code],
			ti.item_desc																					[item_desc],
			tctp.ct_taxDate																					[purchaseDate],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tctP.ct_transaction)				[purchaseTransaction],
			ts.supp_id																						[supp_id],
			ts.supp_name																					[supp_name],
			tid.impData_InitialQty																			[purchaseQTY],
			tid.impData_ActualQty																			[purchaseAvailable]

			FROM		dbo.tbImportData					    tid				WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions				AS tctP				WITH (NOLOCK)
				ON	tctp.comp_id			= tid.comp_id AND
					tctp.ct_transaction		= tid.ct_transaction

			INNER JOIN tbSupplier							AS ts				WITH (NOLOCK)
				ON	ts.comp_id				= tctp.comp_id AND
					ts.supp_id				= tctp.supp_id

			INNER JOIN tbItemTransactionImportData			AS titid			WITH (NOLOCK)
				ON	titid.comp_id			= tid.comp_id AND
					titid.impData_id		= tid.impData_id

			INNER JOIN tbItemTransactions						tit				WITH (NOLOCK)
			ON  tit.comp_id					= titid.comp_id			AND
				tit.bra_id					= titid.bra_id			and
				tit.it_transaction			= titid.it_transaction


			INNER JOIN tbCommercialTransactions					tct				WITH (NOLOCK)
			ON	tct.comp_id					= tit.comp_id			AND
				tct.bra_id					= tit.bra_id			AND
				tct.ct_transaction			= tit.ct_transaction

			INNER JOIN vwCommercialTransactions_forSalesStatsPlusPackingList /* mos 09-2022 vwCommercialTransactions_forSales*/			vctfs			WITH (NOLOCK)
			ON	vctfs.comp_id				= tct.comp_id			AND
				vctfs.bra_id				= tct.bra_id			AND
				vctfs.ct_transaction		= tct.ct_transaction


			INNER JOIN tbItem									ti				WITH (NOLOCK)
			ON	ti.comp_id					= tit.comp_id			AND
				ti.item_id					= tit.item_id


			INNER JOIN tbCustomer								tc				WITH (NOLOCK)
			ON	tc.comp_id					= tct.comp_id			AND
				tc.cust_id					= tct.cust_id

		WHERE	tid.comp_id					= @comp_id
		AND		tid.impData_id				= @impData_id
		ORDER BY tct.ct_transaction ASC


END





GO



