CREATE PROCEDURE [dbo].[spImportData_getDataByFilters]
(
	@comp_id						INT,
	@datefrom						DATETIME,
	@dateto							DATETIME,

	@item_id						INT,
	@supp_id						INT,

	@optionNumber					INT,			-- Opciones para DOcumento
	@numberFrom						VARCHAR(40),	-- Documento
	@optionCustom_local				INT,			-- Opciones para Aduana
	@impData_Custom_local			VARCHAR(200),	-- Aduana
	@optionNumber_local				INT,			-- Opciones para Despacho
	@impData_Number_local			VARCHAR(200),	-- Despacho
	@optionOrigin					INT,			-- Opciones para Origen
	@impData_Origin					VARCHAR(200),	-- Origen
	@optionFrom						INT,			-- Opciones para Destino
	@impData_from					VARCHAR(200),	-- Destino
	@optionLotNumber				INT,			-- Opciones para Numero de Lote
	@impdata_LotNumber				VARCHAR(200),	-- Numero de Lote

	@impdata_Priority				INT,			-- Prioridad
	@impData_ActualQty				DECIMAL(19,5),	-- Cantidad Disponible
	@ExpirationDatefrom				DATETIME,		-- Fecha de Vencimiento
	@ExpirationDateto				DATETIME,
	@impdata_blocked4SOPreparation	INT	 			-- Bloqueado para Preparación de Pedidos?


)
AS

------------------------------------------------------------
/*
DECLARE

	@comp_id				INT,
	@datefrom				DATETIME,
	@dateto					DATETIME,

	@item_id				INT,
	@supp_id				INT,

	@optionNumber			INT,			-- Opciones para DOcumento
	@numberFrom				VARCHAR(40),	-- Documento
	@optionCustom_local		INT,			-- Opciones para Aduana
	@impData_Custom_local	VARCHAR(200),	-- Aduana
	@optionNumber_local		INT,			-- Opciones para Despacho
	@impData_Number_local	VARCHAR(200),	-- Despacho
	@optionOrigin			INT,			-- Opciones para Origen
	@impData_Origin			VARCHAR(200),	-- Origen
	@optionFrom				INT,			-- Opciones para Destino
	@impData_from			VARCHAR(200),	-- Destino
	@optionLotNumber		INT,			-- Opciones para Numero de Lote
	@impdata_LotNumber		VARCHAR(200),	-- Numero de Lote

	@impdata_Priority		INT,			-- Prioridad
	@impData_ActualQty		DECIMAL(19,5),	-- Cantidad Disponible,
	@ExpirationDatefrom				DATETIME,		-- Fecha de Vencimiento
	@ExpirationDateto				DATETIME,
	@impdata_blocked4SOPreparation	INT		 = -1


SELECT
	@comp_id				=1,
	@datefrom				='01-01-1900',
	@dateto					='12-31-9999',
	@ExpirationDatefrom		='01-01-1900',
	@ExpirationDateto		='12-31-9999',
	@optionNumber			=-1,
	@numberFrom				='',
	@item_id				=-1,
	@supp_id				=-1,

	@optionCustom_local		=-1,
	@impData_Custom_local	='',
	@optionNumber_local		=-1,
	@impData_Number_local	='',
	@optionOrigin			=-1,
	@impData_Origin			='',
	@optionFrom				=-1,
	@impData_from			='',
	@optionLotNumber		=-1,
	@impdata_LotNumber		='',

	@impdata_Priority		= 0,
	@impData_ActualQty		= 0

	*/


------------------------------------------------------------



BEGIN


	set nocount on

	SET @datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateTo   = dbo.fnGetEnd_or_BeginOfDate(@dateTo,'True')

	DECLARE @intTOP		AS INT
	SET		@intTOP		= 30000

	IF @item_id    <> -1	SET @intTOP=99999999
	IF @numberFrom <> ''	SET @intTOP=99999999




	SELECT TOP (@intTOP)
				''																				[1], -- Modificar
				''																				[2], -- Grilla generica Detalle de Número de Lote
				ti.item_desc																	[item_desc],
				ti.item_code																	[item_code],
				ts.supp_name																	[supp_name],
				tct.ct_date																		[ct_date],				--e.Row.Cells(5).Text
				dbo.fnGetCommercialTransactionDescription(tct.comp_id, 2, tct.ct_transaction)	[ct_docNumber],
				isnull(id.impData_Custom_local,'')												[impData_Custom_local],
				isnull(id.impData_Number_local,'')												[impData_Number_local],
				isnull(id.impData_Origin,'')													[impData_Origin],
				isnull(id.impData_from,'')														[impData_from],
				isnull(id.impdata_LotNumber,'')													[impdata_LotNumber],
				isnull(id.impdata_Priority,0)													[impdata_Priority],
				isnull(convert(decimal(18,2),id.impData_InitialQty),0)							[impData_InitialQty],
				isnull(convert(decimal(18,2),id.impData_ActualQty),0)							[impData_ActualQty],
				id.impData_ExpirationDate														[impData_ExpirationDate], -- e.Row.Cells(15).Text
				---------------------------------------------------------------------------------
				-- DE AQUI PARA ARRIBA NOOOOOOOOOOO SE PUEDE AGREGAR COLUMNAS
				--DE AQUI PARA ABAJO SE PUEDEN AGREGAR
				isnull(id.impdata_blocked4SOPreparation	,'False')								[is_blocked],
				id.impData_id																	[ID]

	from		dbo.tbImportData   id								WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions tct				WITH (NOLOCK)
					ON	tct.comp_id			= id.comp_id	AND
						tct.ct_transaction	= id.ct_transaction

				INNER JOIN tbItem ti								WITH (NOLOCK)
					ON	ti.comp_id = id.comp_id				AND
						ti.item_id = id.item_id

				-- MOS 02-2020
				INNER JOIN tbSupplier ts								WITH (NOLOCK)
					ON	ts.comp_id = tct.comp_id AND
						ts.supp_id = tct.supp_id


				--LEFT JOIN tbSupplier ts								WITH (NOLOCK)
				--	ON	ts.comp_id = tct.comp_id AND
				--		ts.supp_id = tct.supp_id


	where	id.comp_id	=	@comp_id
	AND		tct.[ct_date] between @datefrom		and @dateto
	AND		(impData_ExpirationDate IS NULL OR id.impData_ExpirationDate between	@ExpirationDatefrom		and @ExpirationDateto)
	AND		(@impdata_blocked4SOPreparation	= -1 OR	 isnull(id.impdata_blocked4SOPreparation,'false')	= @impdata_blocked4SOPreparation)
	AND		(@item_id	= -1 OR	 id.item_id	= @item_id	)
	AND		(@supp_id	= -1 OR	 ts.supp_id	= @supp_id	)
	AND 	(
				(@optionNumber = -1)														or
				(@optionNumber = 0 and tct.ct_docNumber like			@numberFrom + '%')	or
				(@optionNumber = 1 and tct.ct_docNumber like '%' +		@numberFrom + '%')	or
				(@optionNumber = 2 and tct.ct_docNumber =				@numberFrom)		or
				(@optionNumber = 3 and tct.ct_docNumber <>				@numberFrom)		or
				(@optionNumber = 4 and tct.ct_docNumber not like '%' +	@numberFrom + '%')
	)

	AND 	(
				(@optionCustom_local = -1)																			or
				(@optionCustom_local = 0 and id.impData_Custom_local like			@impData_Custom_local + '%')	or
				(@optionCustom_local = 1 and id.impData_Custom_local like '%' +		@impData_Custom_local + '%')	or
				(@optionCustom_local = 2 and id.impData_Custom_local =				@impData_Custom_local)			or
				(@optionCustom_local = 3 and id.impData_Custom_local <>				@impData_Custom_local)			or
				(@optionCustom_local = 4 and id.impData_Custom_local not like '%' +	@impData_Custom_local + '%')
	)

	AND 	(
				(@optionNumber_local = -1)																			or
				(@optionNumber_local = 0 and id.impData_Number_local like			@impData_Number_local + '%')	or
				(@optionNumber_local = 1 and id.impData_Number_local like '%' +		@impData_Number_local + '%')	or
				(@optionNumber_local = 2 and id.impData_Number_local =				@impData_Number_local)			or
				(@optionNumber_local = 3 and id.impData_Number_local <>				@impData_Number_local)			or
				(@optionNumber_local = 4 and id.impData_Number_local not like '%' +	@impData_Number_local + '%')
	)

	AND 	(
				(@optionOrigin = -1)															or
				(@optionOrigin = 0 and id.impData_Origin like			@impData_Origin + '%')	or
				(@optionOrigin = 1 and id.impData_Origin like '%' +		@impData_Origin + '%')	or
				(@optionOrigin = 2 and id.impData_Origin =				@impData_Origin)		or
				(@optionOrigin = 3 and id.impData_Origin <>				@impData_Origin)		or
				(@optionOrigin = 4 and id.impData_Origin not like '%' +	@impData_Origin + '%')
	)

	AND 	(
				(@optionFrom = -1)															or
				(@optionFrom = 0 and id.impData_From like			@impData_from + '%')	or
				(@optionFrom = 1 and id.impData_From like '%' +		@impData_from + '%')	or
				(@optionFrom = 2 and id.impData_From =				@impData_from)			or
				(@optionFrom = 3 and id.impData_From <>				@impData_from)			or
				(@optionFrom = 4 and id.impData_From not like '%' +	@impData_from + '%')
	)

	AND 	(
				(@optionLotNumber = -1)																		or
				(@optionLotNumber = 0 and id.impdata_LotNumber like			@impdata_LotNumber + '%')		or
				(@optionLotNumber = 1 and id.impdata_LotNumber like '%' +		@impdata_LotNumber + '%')	or
				(@optionLotNumber = 2 and id.impdata_LotNumber =				@impdata_LotNumber)			or
				(@optionLotNumber = 3 and id.impdata_LotNumber <>				@impdata_LotNumber)			or
				(@optionLotNumber = 4 and id.impdata_LotNumber not like '%' +	@impdata_LotNumber + '%')
	)

	AND		(@impdata_Priority	= 0 OR	 id.impdata_Priority	= @impdata_Priority	)
	AND		(@impData_ActualQty	= 0 OR	 id.impData_ActualQty	= @impData_ActualQty	)

	AND		CASE
	   		    WHEN @intTOP = 30000 AND id.impData_ActualQty >  0 THEN  1
 	   		    WHEN @intTOP = 30000 AND id.impData_ActualQty <= 0 THEN  0
	   		    ELSE												     1
	   		END	= 1


	ORDER BY
		id.impData_ActualQty DESC,tct.ct_transaction ASC

END
GO


