CREATE PROCEDURE [dbo].[spImportData_GetDataByFilters4Block]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,

	@GuidItem						VARCHAR(50),
	@GuidSupp						VARCHAR(50),
	@import_id						INT,
	@brag_id						INT,
	@impData_Number_local			VARCHAR(200),
    @impData_id						INT,
    @impdata_blocked4SOPreparation	INT,
	@datefrom						DATETIME,
	@dateto							DATETIME

)
AS


BEGIN



	-----------------------------------------------------------------------------------
	--Test
	----------------------------------------------------------------------------------
	/*
	declare
		@comp_id				INT,
		@lang_id				INT,
		@bra_id					INT,
		@prof_id				INT,
		@user_id				INT,

		@GuidItem				VARCHAR(50),
		@GuidSupp				VARCHAR(50),
		@import_id				INT,
		@brag_id				INT,
		@datefrom				DATETIME,
		@dateto					DATETIME

	SELECT

		@comp_id				 = 1,
		@lang_id				= 2,
		@bra_id					= 1,
		@prof_id				= 1,
		@user_id				= 1,

		@GuidItem				='b65d24ab-f319-48d1-8d97-a169136a1c7b',
		@GuidSupp				='f5b83bf5-b48c-4d6f-b3ad-c429405dc7d4',
		@import_id				= -1,
		@brag_id				=-1,
		@datefrom				='1900-01-01',
		@dateto					='2099-04-06'

	*/
	-----------------------------------------------------------------------------------
	--Test
	---------------------------------------------------------------------









		SET NOCOUNT ON
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------

		DECLARE @lGuid_Item AS UNIQUEIDENTIFIER
		SET @lGuid_Item = CONVERT(UNIQUEIDENTIFIER,@GuidItem)

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuid_Item     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
		-- -------------------------------------------------------------

		DECLARE @lGuid_Supp AS UNIQUEIDENTIFIER
		SET @lGuid_Supp = CONVERT(UNIQUEIDENTIFIER,@GuidSupp)

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Supp TABLE (supp_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Supp
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuid_Supp     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Supp
					SELECT ts.supp_id
					FROM tbSupplier ts
						WHERE ts.comp_id = @comp_id
			END
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------------
		-- Grupo de Sucursales
		-- -------------------------------------------------------------------
		DECLARE @tmpBranchGroupDetail TABLE(bra_id int PRIMARY	 KEY)
		INSERT INTO @tmpBranchGroupDetail (bra_id)
			SELECT tbgd.bra_id
				FROM tbBranchGroupDetail tbgd				WITH (NOLOCK)
				WHERE	tbgd.comp_id = @comp_id AND
						tbgd.brag_id = @brag_id

		IF @brag_id = -1
			BEGIN
				INSERT INTO @tmpBranchGroupDetail (bra_id)
					VALUES(
							@bra_id )
			END
		-- -------------------------------------------------------------------


		SET @datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto  = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


		SELECT
			''																						[1],
			tid.impdata_blocked4SOPreparation														[is_blocked],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)		[ct_transaction],
			tct.ct_date																				[ct_date],
			ti.item_desc																			[item_desc],
			ts.supp_name																			[supp_name],
			isnull(tid.impData_Custom_local,'')														[impData_Custom_local],
			isnull(tid.impData_Number_local,'')														[impData_Number_local],
			tid.impData_ExpirationDate																[impData_ExpirationDate],
			tid.impData_id																			[ID]

			FROM tbImportData										tid				WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions						tct				WITH (NOLOCK)
			ON	tct.comp_id			= tid.comp_id			AND
				tct.bra_id			= tid.bra_id			AND
				tct.ct_transaction	= tid.ct_transaction

			LEFT JOIN tbImportDetail								tidet			WITH (NOLOCK)
			ON	tidet.comp_id			= tct.comp_id		AND
				tidet.bra_id			= tct.bra_id		AND
				tidet.ct_transaction	= tct.ct_transaction

			LEFT JOIN tbImport										timprt			WITH (NOLOCK)
			ON  timprt.comp_id			= tidet.comp_id AND
				timprt.import_id		= tidet.import_id

			INNER JOIN @tmpBranchGroupDetail						tmpbg
			ON	tmpbg.bra_id		= tct.bra_id

			INNER JOIN @tblComplexFilter_Items						tempITEM
			ON	tempITEM.item_id	= tid.item_id

			INNER JOIN tbItem										ti				WITH (NOLOCK)
			ON	ti.comp_id			= tid.comp_id			AND
				ti.item_id			= tid.item_id

			INNER JOIN @tblComplexFilter_Supp						tempSUPP
			ON	tempSUPP.supp_id	= tct.supp_id

			INNER JOIN tbSupplier									ts				WITH (NOLOCK)
			ON	ts.comp_id			= tct.comp_id			AND
				ts.supp_id			= tct.supp_id

			WHERE	tid.comp_id			= @comp_id										AND
					tct.ct_date BETWEEN @datefrom AND @dateto							AND
					tid.impData_ActualQty > 0											AND
					(@import_id = -1 OR		timprt.import_id		=	@import_id)		AND
					(@impData_id = 0 OR		tid.impData_id			=	@impData_id)	AND
					(@impdata_blocked4SOPreparation = -1 OR		ISNULL(tid.impdata_blocked4SOPreparation,'False')	=	@impdata_blocked4SOPreparation)	AND
					(@impData_Number_local = '' OR		tid.impData_Number_local			=	@impData_Number_local)


		ORDER BY tid.impData_id desc



END
GO












CREATE PROCEDURE [dbo].[spImportData_getDataById]
(
	@impData_id		INT
)
AS
SET NOCOUNT ON

BEGIN


	SELECT  comp_id,
			item_id,
			impData_id,
			IsNull(impData_InitialQty,0)								[impData_InitialQty],
			isnull(impData_ActualQty,0)									[impData_ActualQty],
			ct_transaction,
			it_transaction,
			bra_id,
			isnull(impData_Custom_local,'')								[impData_Custom_local],
			isnull(impData_Number_local,'')								[impData_Number_local],
			isnull(impData_Origin, '')									[impData_Origin],
			isnull(impData_From,'')										[impData_From],
			isnull(impData_ExpirationDate,GETDATE()), 					[impData_ExpirationDate],
			isnull(impdata_Priority,0)									[impdata_Priority],
			isnull(impdata_LotNumber,'')								[impdata_LotNumber],
			isnull(impdata_blocked4SOPreparation,'False')				[impdata_blocked4SOPreparation]

	FROM 	dbo.tbImportData id

	WHERE 	id.impData_id = @impData_id


END


















GO










CREATE PROCEDURE [dbo].[spImportData_getDataById_blocked4SOPreparation]
(
	@comp_id		INT,
	@lang_id		INT,
	@impData_id		INT
)
AS
SET NOCOUNT ON

BEGIN


	SELECT
		comp_id,
		item_id,
		impData_id,
		IsNull(impData_InitialQty,0)															[impData_InitialQty],
		isnull(impData_ActualQty,0)																[impData_ActualQty],
		ct_transaction,
		it_transaction,
		bra_id,
		isnull(impData_Custom_local,'')															[impData_Custom_local],
		isnull(impData_Number_local,'')															[impData_Number_local],
		isnull(impData_Origin, '')																[impData_Origin],
		isnull(impData_From,'')																	[impData_From],
		isnull(impData_ExpirationDate,GETDATE()), 												[impData_ExpirationDate],
		isnull(impdata_Priority,0)																[impdata_Priority],
		isnull(impdata_LotNumber,'')															[impdata_LotNumber],
		isnull(impdata_blocked4SOPreparation,'False')											[impdata_blocked4SOPreparation],
		dbo.fnGetCommercialTransactionDescription(1, 2, id.ct_transaction)						[comprobante]

		FROM 	dbo.tbImportData id

		WHERE 	id.impData_id = @impData_id


END


















GO




CREATE procedure [dbo].[spImportData_getReport]
(
	@comp_id						INT,
	@lang_id						INT,
	@page_id						INT,

	@date_from						DATETIME,
	@date_to						DATETIME,
	@impdata_LotNumber_Option		INT,
	@impdata_LotNumber				VARCHAR(50),
	@item_id						INT,
	@cust_id						INT,
	@supp_id						INT,

	@intBranch4Lang					INT

)
as


SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



---------------------------------------------------------------------------------------------
-- TEST
---------------------------------------------------------------------------------------------
	/*

	DECLARE

	@comp_id						INT,
	@lang_id						INT,
	@page_id						INT,

	@bra_id							INT,
	@date_from						DATETIME,
	@date_to						DATETIME,
	@impdata_LotNumber_Option		INT,
	@impdata_LotNumber				VARCHAR(50),
	@item_id						INT,
	@cust_id						INT,
	@supp_id						INT,

	@intBranch4Lang					INT


	SELECT
		@comp_id					= 1,
		@lang_id					= 2,
		@page_id					= 100969,

		@bra_id						=-1,
		@cust_id					=-1,
		@supp_id					=-1,
		@item_id					=-1,
		@date_from					='06/01/2010',
		@date_to					='12/31/2020',
		@impdata_LotNumber_Option	= -1,
		@impdata_LotNumber			= ''


*/
	---------------------------------------------------------------------------------------------
	---------------------------------------------------------------------------------------------


 SELECT  @date_from = dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
 SELECT  @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')



	DECLARE @fun_id INT
	SET		@fun_id = 1


		SELECT
			 tid.impdata_LotNumber																		[impdata_LotNumber],
			 tct.ct_date																				[ct_date],
			 ts.supp_name																				[supp_name],
			 tc.cust_name																				[cust_name],
			 ti.item_desc																				[item_desc],
			 dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)			[ct_transaction]

			FROM		dbo.tbImportData					    tid		WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions					tct		WITH (NOLOCK)
			ON	tct.comp_id			= tid.comp_id			AND
				tct.bra_id			= tid.bra_id			AND
				tct.ct_transaction	= tid.ct_transaction

			INNER JOIN tbItemTransactions						tit		WITH (NOLOCK)
			ON  tit.comp_id			= tct.comp_id			AND
				tit.bra_id			= tct.bra_id			AND
				tit.ct_transaction	= tct.ct_transaction

			LEFT JOIN tbItem									ti		WITH (NOLOCK)
			ON	ti.comp_id			= tit.comp_id			AND
				ti.item_id			= tit.item_id

			LEFT JOIN tbSupplier								ts		WITH (NOLOCK)
			ON	ts.comp_id			= tct.comp_id			AND
				ts.supp_id			= tct.supp_id

			LEFT JOIN tbCustomer								tc		WITH (NOLOCK)
			ON	tc.comp_id			= tc.comp_id			AND
				tc.cust_id			= tct.cust_id

	WHERE	tid.comp_id						=	@comp_id
	AND		tct.ct_date BETWEEN @date_from AND @date_to
	AND		(@cust_id  = -1  or tc.cust_id    = @cust_id)
	AND		(@supp_id  = -1  or ts.supp_id    = @supp_id)
	AND		(@item_id  = -1  or ti.item_id    = @item_id)
	AND 	(
				(@impdata_LotNumber_Option = -1)													or
				(@impdata_LotNumber_Option = 0 and tid.impdata_LotNumber like			@impdata_LotNumber + '%')	or
				(@impdata_LotNumber_Option = 1 and tid.impdata_LotNumber like '%' +		@impdata_LotNumber + '%')	or
				(@impdata_LotNumber_Option = 2 and tid.impdata_LotNumber =				@impdata_LotNumber)		or
				(@impdata_LotNumber_Option = 3 and tid.impdata_LotNumber <>				@impdata_LotNumber)		or
				(@impdata_LotNumber_Option = 4 and tid.impdata_LotNumber not like '%' +	@impdata_LotNumber + '%')
			)


order by 1

exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

