CREATE PROCEDURE [dbo].[spImportData_insertData]
(
    @comp_id					int,
	@item_id					int,
	@impData_InitialQty			decimal(19,5),
	@impData_ActualQty			decimal(19,5),
	@ct_transaction				int,
	@it_transaction				int,
	@bra_id						INT,
	@impData_Custom_local		VARCHAR(20),
	@impData_Number_local		VARCHAR(20),
	@impData_Origin				VARCHAR(100),		-- Parte : 709
    @impData_From				VARCHAR(100),		-- Parte : 709
    @impData_ExpirationDate     DATETIME,
    @impdata_LotNumber			NVARCHAR(50)
)
AS



BEGIN




	set nocount ON
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-12-04
	-- Parte		: 709
	-- Description	: Se agrega la actualización de los nuevos campos impData_Origin y impData_From
	-- =================================================================================================================



	insert into	dbo.tbImportData	WITH (ROWLOCK)
					(	comp_id,
						item_id,
						impData_InitialQty,
						impData_ActualQty,
						ct_transaction,
						it_transaction,
						bra_id,
						impData_Custom_local,
						impData_Number_local,
						impData_Origin,
						impData_From,
						impData_ExpirationDate,
						impdata_LotNumber)
	values
			   		(   @comp_id,
			   			@item_id,
			   			@impData_InitialQty,
			   			@impData_ActualQty,
						@ct_transaction,
						@it_transaction,
						@bra_id,
			   			@impData_Custom_local,
			   			@impData_Number_local,
			   			@impData_Origin,			-- Parte : 709
			   			@impData_From,				-- Parte : 709
						@impData_ExpirationDate,
						@impdata_LotNumber
					 )



END
GO








CREATE PROCEDURE [dbo].[spImportData_StateIsChecked]
(
	@comp_id			   AS INT,
	@qty				   AS INT,
	@is_checked			   AS BIT,
	--@item_id			   AS INT,
	@stor_id			   AS INT,
    @it_transaction		   AS INT,
	@guid			UNIQUEIDENTIFIER


)
AS

BEGIN


	set nocount ON


	/*
	declare @comp_id			   AS INT,
			@qty				   AS INT,
			@is_checked			   AS BIT,
			@guid			UNIQUEIDENTIFIER

	SELECT @comp_id			   =1,
			@qty			   =10,
			@is_checked		   ='false'
	*/


	IF @is_checked = 'False'

		UPDATE tbItemSerials
		SET   is_checked = 'false',
			  is_guid    = NULL

	ELSE

		UPDATE TOP(@qty) tbItemSerials
		SET		is_checked	= 'true',
				is_guid		= @guid

		WHERE	comp_id			= @comp_id
		--AND   item_id			= @item_id
		AND		stor_id			= @stor_id
		AND		it_transaction	= @it_transaction
		AND		is_available	= 'true'




END








GO






CREATE PROCEDURE [dbo].[spImportData_UpdateData]
(
	@comp_id					INT,
	@impData_id					INT,
	@impData_Custom_local		nVARCHAR(200),
	@impData_Number_local		nVARCHAR(200),
	@dateExpiration				DATETIME,
	@impData_Origin				nVARCHAR(200),
	@impData_From				nVARCHAR(200),
	@impdata_Priority			INT,
	@impData_ActualQty			DECIMAL(19,5),
	@impData_LotNumber			nVARCHAR(50)


)
AS


BEGIN



	UPDATE dbo.tbImportData

	SET impData_Custom_local	= @impData_Custom_local,
		impData_Number_local	= @impData_Number_local,
		impData_ExpirationDate  = @dateExpiration,
		impData_Origin			= @impData_Origin,
		impData_From			= @impData_From,
		impdata_Priority		= @impdata_Priority,
		impData_ActualQty		= @impData_ActualQty,
		impdata_LotNumber	    = @impData_LotNumber


	WHERE comp_id				= @comp_id
	AND   impData_id			= @impData_id



END
GO



