CREATE PROCEDURE [dbo].[spImportData_ValidateProcess]
(
	@comp_id			   AS INT,
	@lang_id			   AS INT,
	@option				   AS INT,
	@item_id			   AS INT,
	@stor_id			   AS INT,
	@stor_id_destiny       AS INT,
	@Qty				   AS DECIMAL(19,7),
	@impData_id            AS INT,
	@it_transaction		   AS INT,
	@guid                  AS UNIQUEIDENTIFIER,
	@color_id			   AS INT,
	@intCTTransaction	   AS INT,

	@return_value		   AS INT		    output,
	@ret_ErrorCode		   AS INT			output,
	@ret_ErrorDescription  AS VARCHAR(200)  output
)
AS



BEGIN



	set nocount ON


	-- -------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------
	/*
		DECLARE
			@comp_id				AS INT,
			@lang_id				AS INT,
			@option					AS INT,
			@item_id				AS INT,
			@stor_id				AS INT,
			@stor_id_destiny		AS INT,
			@Qty					AS DECIMAL(19,7),
			@impData_id				AS INT,
			@it_transaction			AS INT,
			@guid					AS UNIQUEIDENTIFIER,
			@color_id			    AS INT,
			@intCTTransaction		AS INT,

			@return_value			AS INT,
			@ret_ErrorCode			AS INT,
			@ret_ErrorDescription	AS VARCHAR(200)

		SELECT
			@comp_id				= 1,
			@lang_id				= 2,
			@item_id				= 628,
			@option					= 4002,
			@stor_id				= 3,
			@stor_id_destiny		= 3,
			@Qty					= 1,
			@impData_id				= 2342,
			@it_transaction			= 14078,
			@guid					='7a24ddf2-54bf-470f-8fa1-455dc919ed92',
			@color_id			    = 4,
			@intCTTransaction		=29117
			-- DROP TABLE #tmp_ItemCompositionStatus
			-- DROP TABLE #tmp_ItemCompositionStatus2

	*/
	-- -------------------------------------------------------------


	DECLARE @bitDisableSerialControl AS BIT
	SET		@bitDisableSerialControl = 'False'
	IF @option = 3002			-- Si es Transferencia entre depositos y tiene el control x perfil que dice que no moleste con nros de serie, lo hace igual.-
		BEGIN
			SET @option						= 3
			SET	@bitDisableSerialControl	= 'True'
		END
	IF @option = 4002			-- Si es Transferencia entre depositos y tiene el control x perfil que dice que no moleste con nros de serie, lo hace igual.-
		BEGIN
			SET @option						= 4
			SET	@bitDisableSerialControl	= 'True'
		END
	IF @option = 5002			-- Si es Transferencia entre depositos y tiene el control x perfil que dice que no moleste con nros de serie, lo hace igual.-
		BEGIN
			SET @option						= 5
			SET	@bitDisableSerialControl	= 'True'
		END




	DECLARE @intBraIdOfCtTransaction	AS INT
	DECLARE @intCurrIdOfBrand			AS INT

	DECLARE @bra_id			AS INT
	DECLARE @ct_transaction AS INT
	DECLARE @lStorePreviuos	AS DECIMAL(19,6)
	DECLARE @lStorePreviuos_destiny AS DECIMAL(19,6)
	DECLARE @lcurr_id		AS INT


	set	@return_value = 0
	set	@ret_ErrorDescription = ' '
	SET @ret_ErrorCode = 0

	SELECT	@intBraIdOfCtTransaction = tct.bra_id,
			@intCurrIdOfBrand		 = tb.curr_id
		FROM tbCommercialTransactions tct					WITH (NOLOCK)
		INNER JOIN tbBranch tb								WITH (NOLOCK)
			ON	tb.comp_id			= tct.comp_id AND
				tb.bra_id			= tct.bra_id
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @intCTTransaction


	BEGIN TRY


		------------------------------------------------------------------------------------------------------
		-- == 1:ENTRADA ======================================================================================
		-- OK
		------------------------------------------------------------------------------------------------------
		IF @option = 1
			BEGIN

				-- ::Valido que la cantidad q viene + la cantidad actual sea menor o igual a la cantidad inicial.
				IF EXISTS (	SELECT		1
				           		FROM tbImportData tid			WITH (NOLOCK)
								WHERE	tid.comp_id		= @comp_id
								AND		tid.item_id		= @item_id
								AND		tid.impData_id	= @impData_id
								AND		((@Qty + tid.impData_ActualQty) > tid.impData_InitialQty))
					BEGIN

						SET @return_value = 1

						SET @ret_ErrorCode =-1

						SET @ret_ErrorDescription = (SELECT tut.utexts_desc
													 FROM tbsysUniqueTexts tut			WITH (NOLOCK)
													 WHERE tut.lang_id  = @lang_id
   													 AND tut.utexts_id	= 224014)
   						RETURN
					END
				ELSE
					BEGIN

						-- ::Crear tantas row como qty

						SELECT	@bra_id			 = tit.bra_id,
								@ct_transaction  = tit.ct_transaction
							FROM tbItemTransactions tit			WITH (NOLOCK)
							WHERE tit.comp_id		 = @comp_id
							AND   tit.it_transaction = @it_transaction


						EXEC spItemSerials_insertQtyData
														@comp_id		= @comp_id,
														@bra_id			= @bra_id,
														@ct_transaction = @ct_transaction,
														@it_transaction = @it_transaction,
														@item_id		= @item_id,
														@stor_id		= @stor_id,
														@qty			= @Qty


						-- ::Sumar cantidad actual + qty
						UPDATE	tbImportData
							SET		impData_ActualQty	= impData_ActualQty + @Qty
							WHERE	comp_id				= @comp_id
							AND		item_id				= @item_id
							AND		impData_id			= @impData_id


						-- ::cambiar el estado de los checkeados.
						UPDATE	tbItemSerials
							SET is_checked = 'False',
								is_guid = NULL
							WHERE comp_id	   = @comp_id	AND
								  is_checked   = 'True'		AND
								  is_guid	   = @guid

						-- -----------------------------------------------
						-- Actualizacion del Stock
						-- -----------------------------------------------

						--** Genera un ItemTrans con el storprevius del deposito origen y poenle una entrada  sd_id: 350 y it_IsStockAdjustment = True y
						-- ct_transaction = @intCTTransaction y luego SUMA del stock del deposito @stor_id


						set @lStorePreviuos = 0
						SET @lStorePreviuos = ( SELECT tis.itst_cant
													FROM tbItemStorage				tis	--WITH (NOLOCK)
													WHERE tis.comp_id = @comp_id AND
														  tis.stor_id = @stor_id AND
														  tis.item_id = @item_id
												)


--==
--SELECT @intBraIdOfCtTransaction,@intCurrIdOfBrand,@item_id,@lStorePreviuos,@intCTTransaction
--==

						INSERT INTO tbItemTransactions
							(
								comp_id,				bra_id,						ct_transaction,
								item_id,				it_qty,						it_priceWithOutOthers,
								it_price,				curr_id,					it_exchangeToBranchCurrency,
								it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
								it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
								it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
								stor_id,				it_storePrevious,			prli_id,
								byor_id,				it_isProduction,			it_isAssociation,
								it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
								it_order,				so_id,						it_guarantee,
								it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
								it_CreditIntPlus,		puco_id,					it_poh_bra_id,
								it_poh_id,				it_soh_id,					it_sod_id,
								rmah_id,				rmad_id,					it_qty_rma,
								it_tis_id_aux,			it_IsStockAdjustment,		sitt_id
							)
							VALUES
							(
								@comp_id,				@intBraIdOfCtTransaction,	@intCTTransaction,
								@item_id,				@Qty,						0,
								0,						@intCurrIdOfBrand,			NULL,
								0,						0,							0,
								0,						0,							0,
								0,						NULL,						1,
								@stor_id,				isnull(@lStorePreviuos,0),	NULL,
								NULL,					'False',					'False',
								NULL,					GETDATE(),					NULL,
								0,						NULL,						0,
								0,						0,							0,
								0,						NULL,						NULL,
								NULL,					NULL,						NULL,
								NULL,					NULL,						NULL,
								NULL,					'True',						40
							)



						--SUMAMOS del stock del deposito @stor_id
						UPDATE	tbItemStorage
								SET		itst_cant = itst_cant + @Qty
								WHERE	comp_id = @comp_id	AND
										stor_id	= @stor_id	AND
										item_id	= @item_id

						-- -----------------------------------------------


					END
			END
		---Fin opcion 1 ---------------------------------------------------------------------------







	------------------------------------------------------------------------------------------------------
	-- == 2:SALIDA  ======================================================================================
	-- OK
	------------------------------------------------------------------------------------------------------

	IF @option = 2
		BEGIN


			-- ::Valido que la cantidad actual menos la cantidad q viene debe ser mayor o igual a 0.
			IF EXISTS (	SELECT TOP 1 1
			           		FROM tbImportData tid		WITH (NOLOCK)
							WHERE	tid.comp_id		= @comp_id
							 AND	tid.item_id		= @item_id
							 AND	tid.impData_id	= @impData_id
							 AND	((tid.impData_ActualQty - @Qty) < 0))
				BEGIN

					SET @return_value = 2
					--SELECT @return_value
					SET @ret_ErrorCode =-2
					SET @ret_ErrorDescription = (SELECT isnull(tut.utexts_desc, '')
													 FROM tbsysUniqueTexts tut			WITH (NOLOCK)
													 WHERE tut.lang_id   = @lang_id
													 and   tut.utexts_id = 224015)
					RETURN
				END
			ELSE
				BEGIN
					-- ::Verificar que estén marcados tantos número de serie como dice la cantidad y que el artículo
					-- ::sea serializable
					IF	((	SELECT COUNT(*)
								FROM	tbItemSerials tis		WITH (NOLOCK)
								WHERE tis.comp_id		= @comp_id
								  AND	tis.is_guid		= @guid
								  AND	tis.is_checked	= 'True') <> @Qty)
							AND
							(EXISTS (	SELECT TOP 1  1
   											FROM tbItem ti	WITH (NOLOCK)
											WHERE	ti.comp_id		= @comp_id AND
													ti.item_id		= @item_id AND
													ti.item_expser	= 'true'))

					   BEGIN
						 SET @return_value = 3
						 -- SELECT @return_value
						 SET @ret_ErrorCode =-12    --  -3
		 				 SET @ret_ErrorDescription = (SELECT tut.utexts_desc
													  FROM tbsysUniqueTexts tut
													  WHERE tut.lang_id    = @lang_id
													  AND   tut.utexts_id  = 224016)
					   END

					ELSE

					   BEGIN
						-- ::Marcar IsAvailable = False para los registros marcados.

							UPDATE	tbItemSerials
								SET is_available   = 'False'
									WHERE comp_id	   = @comp_id
									AND	 is_guid	   = @guid
									AND	 is_checked    = 'True'



							-- ::Restar actual_qty - qty

							UPDATE tbImportData
								SET	impData_ActualQty	= (impData_ActualQty - @Qty)
								WHERE comp_id			= @comp_id
								AND   item_id			= @item_id
								AND   impData_id		= @impData_id

							-- ::cambiar el estado de los checkeados.
							UPDATE	tbItemSerials
 								SET is_checked = 'False',
 									is_guid = NULL
								WHERE comp_id	   = @comp_id	AND
									  is_checked   = 'True'		AND
									  is_guid	   = @guid


						-- -----------------------------------------------
						-- Actualizacion del Stock
						-- -----------------------------------------------

						--** Genera un ItemTrans con el storprevius del deposito origen y poenle una SALIDA (Qty * -1)  sd_id: 350 y it_IsStockAdjustment = True y
						--ct_transaction = @intCTTransaction y luego RESTA del stock del deposito @stor_id

						SELECT	@bra_id			 = tit.bra_id

								FROM tbItemTransactions tit			WITH (NOLOCK)
								WHERE tit.comp_id		 = @comp_id
								AND   tit.it_transaction = @it_transaction

						SET @lStorePreviuos = ( SELECT tis.itst_cant
													FROM tbItemStorage				tis
													WHERE tis.comp_id = @comp_id AND
														  tis.stor_id = @stor_id AND
														  tis.item_id = @item_id
												)


						INSERT INTO tbItemTransactions
							(
								comp_id,				bra_id,						ct_transaction,
								item_id,				it_qty,						it_priceWithOutOthers,
								it_price,				curr_id,					it_exchangeToBranchCurrency,
								it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
								it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
								it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
								stor_id,				it_storePrevious,			prli_id,
								byor_id,				it_isProduction,			it_isAssociation,
								it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
								it_order,				so_id,						it_guarantee,
								it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
								it_CreditIntPlus,		puco_id,					it_poh_bra_id,
								it_poh_id,				it_soh_id,					it_sod_id,
								rmah_id,				rmad_id,					it_qty_rma,
								it_tis_id_aux,			it_IsStockAdjustment,		sitt_id
							)
							VALUES
							(
								@comp_id,				@intBraIdOfCtTransaction,					@intCTTransaction,
								@item_id,				@Qty * -1,					0,
								NULL,					@intCurrIdOfBrand,			NULL,
								0,						0,							0,
								0,						0,							0,
								0,						NULL,						1,
								@stor_id,				isnull(@lStorePreviuos,0),	NULL,
								NULL,					'False',					'False',
								NULL,					GETDATE(),					NULL,
								0,						NULL,						0,
								0,						0,							0,
								0,						NULL,						NULL,
								NULL,					NULL,						NULL,
								NULL,					NULL,						NULL,
								NULL,					'True',						40
							)



						--RESTAMOS del stock del deposito @stor_id
						UPDATE	tbItemStorage
								SET		itst_cant = itst_cant - @Qty
								WHERE	comp_id = @comp_id	AND
										stor_id	= @stor_id	AND
										item_id	= @item_id

						-- -----------------------------------------------


	  				  END
				END
		END
	 ---Fin opcion 2 ---------------------------------------------------------------------------















	-----------------------------------------------------------------------------------------------
	-- == 3:TRANSFERENCIA =========================================================================
	-----------------------------------------------------------------------------------------------

	IF @option = 3
		BEGIN

 			-- ::Verificar que estén marcados tantos número de serie como dice la cantidad.
 			IF	@bitDisableSerialControl = 'False'					AND
 				((SELECT COUNT(*)
 					  FROM	tbItemSerials tis		WITH (NOLOCK)
					  WHERE tis.comp_id		= @comp_id
					  AND	tis.is_guid		= @guid
					  AND	tis.is_checked	= 'True') <> @Qty)
																	AND
				 (EXISTS (	SELECT TOP 1  1
								FROM tbItem ti	WITH (NOLOCK)
								WHERE	ti.comp_id		= @comp_id AND
										ti.item_id		= @item_id AND
										ti.item_expser	= 'true'))
				BEGIN
				  -- SELECT 1
					SET @return_value = 3
  	  			   -- SELECT @return_value
  	  				SET @ret_ErrorCode =-13   -- -3
  	  				SET @ret_ErrorDescription = (SELECT tut.utexts_desc
													 FROM tbsysUniqueTexts tut		WITH (NOLOCK)
													 WHERE tut.lang_id    = @lang_id
   													 and   tut.utexts_id  = 224016)
   					RETURN
				END

			ELSE

				BEGIN

					DECLARE @resultValue AS BIT
					DECLARE @QtyOrigin AS INT


					SELECT
						@QtyOrigin = tis.itst_cant
						FROM tbItemStorage tis			WITH (NOLOCK)
						WHERE tis.comp_id = @comp_id
						AND tis.stor_id = @stor_id
						AND tis.item_id = @item_id


					IF @QtyOrigin >= @Qty

						BEGIN

							--:: Si no existe el registro de DESTINO, lo crea para la transferencia y luego lo actualiza! Parte:1006 STL


							EXEC spItemStorage_insertData @comp_id,@item_id,@stor_id_destiny,0



							-- ::Actualizar el stor_id con el depósito destino.
							UPDATE	tbItemSerials
								SET stor_id		   = @stor_id_destiny,
								  is_checked	   = 'False',
								  is_guid		   = NULL
								WHERE	comp_id	   = @comp_id			AND
										item_id	   = @item_id			AND
										is_checked = 'True'				AND
										is_guid	   = @guid



							-- -----------------------------------------------
							-- Actualizacion del Stock
							-- -----------------------------------------------

							--** Genera un ItemTrans con el storprevius del deposito origen y poenle una salida  sd_id: 350 y it_IsStockAdjustment = True (Qty  * -1) y
							--ct_transaction = @intCTTransaction y luego RESTA del stock del deposito @stor_id

							SELECT	@bra_id			 = tit.bra_id

									FROM tbItemTransactions tit			WITH (NOLOCK)
									WHERE tit.comp_id		 = @comp_id
									AND   tit.it_transaction = @it_transaction

							SET @lStorePreviuos = ( SELECT tis.itst_cant
														FROM tbItemStorage				tis
														WHERE tis.comp_id = @comp_id AND
															  tis.stor_id = @stor_id AND
															  tis.item_id = @item_id
													)


							INSERT INTO tbItemTransactions
								(
									comp_id,				bra_id,						ct_transaction,
									item_id,				it_qty,						it_priceWithOutOthers,
									it_price,				curr_id,					it_exchangeToBranchCurrency,
									it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
									it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
									it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
									stor_id,				it_storePrevious,			prli_id,
									byor_id,				it_isProduction,			it_isAssociation,
									it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
									it_order,				so_id,						it_guarantee,
									it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
									it_CreditIntPlus,		puco_id,					it_poh_bra_id,
									it_poh_id,				it_soh_id,					it_sod_id,
									rmah_id,				rmad_id,					it_qty_rma,
									it_tis_id_aux,			it_IsStockAdjustment,		sitt_id
								)
								VALUES
								(
									@comp_id,				@intBraIdOfCtTransaction,					@intCTTransaction,
									@item_id,				@Qty * -1,					0,
									NULL,					@intCurrIdOfBrand,			NULL,
									0,						0,							0,
									0,						0,							0,
									0,						NULL,						1,
									@stor_id,				isnull(@lStorePreviuos,0),	NULL,
									NULL,					'False',					'False',
									NULL,					GETDATE(),					NULL,
									0,						NULL,						0,
									0,						0,							0,
									0,						NULL,						NULL,
									NULL,					NULL,						NULL,
									NULL,					NULL,						NULL,
									NULL,					'True',						40
								)



							--RESTAMOS del stock del deposito @stor_id
							UPDATE	tbItemStorage
								SET		itst_cant = itst_cant - @Qty
								WHERE	comp_id = @comp_id	AND
										stor_id	= @stor_id	AND
										item_id	= @item_id



							--** Genera un ItemTrans con el storprevius del deposito origen y poenle una entrada sd_id: 350 y
							--it_IsStockAdjustment = True y ct_transaction = @intCTTransaction y luego SUMA del stock del deposito @stor_id_destiny

							SET @lStorePreviuos_destiny = ( SELECT tis.itst_cant
																FROM tbItemStorage				tis
																WHERE tis.comp_id = @comp_id		 AND
																	  tis.stor_id = @stor_id_destiny AND
																	  tis.item_id = @item_id
															)

							INSERT INTO tbItemTransactions
								(
									comp_id,				bra_id,						ct_transaction,
									item_id,				it_qty,						it_priceWithOutOthers,
									it_price,				curr_id,					it_exchangeToBranchCurrency,
									it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
									it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
									it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
									stor_id,				it_storePrevious,			prli_id,
									byor_id,				it_isProduction,			it_isAssociation,
									it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
									it_order,				so_id,						it_guarantee,
									it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
									it_CreditIntPlus,		puco_id,					it_poh_bra_id,
									it_poh_id,				it_soh_id,					it_sod_id,
									rmah_id,				rmad_id,					it_qty_rma,
									it_tis_id_aux,			it_IsStockAdjustment,		sitt_id
								)
								VALUES
								(
									@comp_id,				@intBraIdOfCtTransaction,					@intCTTransaction,
									@item_id,				@Qty,						0,
									0,						@intCurrIdOfBrand,			NULL,
									0,						0,							0,
									0,						0,							0,
									0,						NULL,						1,
									@stor_id_destiny,		isnull(@lStorePreviuos_destiny,0),	NULL,
									NULL,					'False',					'False',
									NULL,					GETDATE(),					NULL,
									0,						NULL,						0,
									0,						0,							0,
									0,						NULL,						NULL,
									NULL,					NULL,						NULL,
									NULL,					NULL,						NULL,
									NULL,					'True',						40
								)



							--SUMAMOS del stock del deposito @stor_id_destiny
							UPDATE	tbItemStorage
									SET		itst_cant = itst_cant + @Qty
									WHERE	comp_id = @comp_id			AND
											stor_id	= @stor_id_destiny	AND
											item_id	= @item_id


							-- -----------------------------------------------



						END

					ELSE

						BEGIN

							SET @return_value = 6
						   -- SELECT @return_value
							SET @ret_ErrorCode =-6
							SET @ret_ErrorDescription = (SELECT tut.utexts_desc
															 FROM tbsysUniqueTexts tut		WITH (NOLOCK)
															 WHERE tut.lang_id    = @lang_id
															 and   tut.utexts_id  = 224031)
						END


    			END
   		END
	--  END
	---Fin opcion 3 ---------------------------------------------------------------------------














	-----------------------------------------------------------------------------------------------
	-- == 4:COMPOSICION   =========================================================================
	-----------------------------------------------------------------------------------------------

	IF @option = 4

		BEGIN
			IF	@bitDisableSerialControl = 'False'					AND
 				((SELECT COUNT(*)
 					  FROM	tbItemSerials tis			WITH (NOLOCK)
							  WHERE tis.comp_id		= @comp_id
							  AND	tis.is_guid		= @guid
							  AND	tis.is_checked	= 'True') <> @Qty)
					AND
				 (EXISTS (	SELECT TOP 1  1
				          		FROM tbItem ti			WITH (NOLOCK)
								WHERE	ti.comp_id		= @comp_id AND
										ti.item_id		= @item_id AND
										ti.item_expser	= 'true'))
				BEGIN
				  -- SELECT 1
					SET @return_value = 3
				   -- SELECT @return_value
					SET @ret_ErrorCode =-14		--- -13
					SET @ret_ErrorDescription = (SELECT tut.utexts_desc
													 FROM tbsysUniqueTexts tut		WITH (NOLOCK)
													 WHERE tut.lang_id    = @lang_id
													 and   tut.utexts_id  = '224016')
					RETURN
				END
			ELSE

			-- ::Obtenemos las cantidades necesarias para componer el artículo y comparamos con las existentes en
			-- ::el Depósito de destino
   				BEGIN
--SELECT 14
						SELECT
							tic.item_id_1,
							tic.icomp_qty * @Qty										[icomp_qty],
							@item_id /*tis.item_id*/									[item_id],
							ISNULL(tis.itst_cant,0)										[itst_cant],
							CASE
								WHEN ISNULL(tis.itst_cant,0) >= (icomp_qty * @Qty) THEN	'True'
								ELSE													'False'
							END															[item_Status]

							INTO #tmp_ItemCompositionStatus

							FROM tbItemComposition tic			WITH (NOLOCK)

							LEFT JOIN tbItemStorage tis				WITH (NOLOCK)
								ON	tis.comp_id = tic.comp_id		AND
									tis.item_id = tic.item_id_1		AND
									tis.stor_id	= @stor_id
							WHERE	tic.comp_id	= @comp_id			AND
									tic.item_id	= @item_id

--SELECT 15
--SELECT * FROM #tmp_itemcompositionstatus
					-- :: Variable que controla si esta OK o NO para la composición, si el valor es 0
					-- :: procede a componer, en caso contrario arroja error

					DECLARE
						@control AS INT


					SELECT @control  = COUNT(*) FROM #tmp_itemcompositionstatus WHERE  item_Status = 'False'
--SELECT '@control',@control

					IF ISNULL(@control,0) = 0  -- Si dice que tiene stock de las partes sigue el proceso.

						--:: Actualizamos la tabla TbItemStorage restando el stock de los articulos que compondran el nuevo articulo
						--:: PRESTAR ATENCION ACA!!!!!!!!!
						BEGIN

--SELECT 16
							--:: Si no existe el registro de DESTINO, lo crea para la transferencia y luego lo actualiza! Parte:1006 STL

							  EXEC spItemStorage_insertData @comp_id,@item_id,@stor_id_destiny,0
							  EXEC spItemStorage_insertData @comp_id,@item_id,@stor_id,0

							  -- ::Actualizar el stor_id con el depósito destino.
							  UPDATE	tbItemSerials
								  SET  stor_id		= @stor_id_destiny,
									   is_checked	= 'False',
									   is_guid		= NULL
								  WHERE comp_id	   = @comp_id	AND
								  		item_id	   = @item_id	AND
								  		is_checked = 'True'		AND
								  		is_guid    = @guid

--SELECT 19
--							  NO ENFERMO HIJO DE RE MIL PUTAS::: NOOOOO
--							  -- ::Actualizo ItemTransactions y dejo el STORE PREVIOUS
--							  UPDATE tbItemTransactions
--								SET
--									it_storePrevious = @QtyOrigin
--							  WHERE comp_id = @comp_id
--							  AND it_transaction = @it_transaction




							-- -----------------------------------------------
							-- Actualizacion del Stock
							-- -----------------------------------------------

							--** Genera un ItemTrans con el storprevius del deposito @stor_id y poenle una SALIDA: (tmp.icomp_qty)  sd_id: 350 y it_IsStockAdjustment = True (Qty  * -1) y ct_transaction = @intCTTransaction
							--   podes hacerlo con un insert select como esta abajo el update del stock asi lo hacees todo en una sola instruccion.
							--   OJO, consultame si no entendes

							INSERT INTO tbItemTransactions
								(
									comp_id,				bra_id,						ct_transaction,
									item_id,				it_qty,						it_priceWithOutOthers,
									it_price,				curr_id,					it_exchangeToBranchCurrency,
									it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
									it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
									it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
									stor_id,				it_storePrevious,			prli_id,
									byor_id,				it_isProduction,			it_isAssociation,
									it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
									it_order,				so_id,						it_guarantee,
									it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
									it_CreditIntPlus,		puco_id,					it_poh_bra_id,
									it_poh_id,				it_soh_id,					it_sod_id,
									rmah_id,				rmad_id,					it_qty_rma,
									it_tis_id_aux,			it_IsStockAdjustment,		sitt_id
								)

								SELECT
										@comp_id,				@intBraIdOfCtTransaction,					@intCTTransaction,
										tmp.item_id_1,			tmp.icomp_qty * -1,			0,
										NULL,					@intCurrIdOfBrand,			NULL,
										0,						0,							0,
										0,						0,							0,
										0,						NULL,						1,
										@stor_id,				ISNULL((
																		SELECT IsNull(tis.itst_cant,0)
																			FROM tbItemStorage				tis
																			WHERE tis.comp_id = @comp_id AND
																				  tis.stor_id = @stor_id AND
																				  tis.item_id = tmp.item_id_1

																)	,0)	,					NULL,
										NULL,					'False',					'False',
										NULL,					GETDATE(),					NULL,
										0,						NULL,						0,
										0,						0,							0,
										0,						NULL,						NULL,
										NULL,					NULL,						NULL,
										NULL,					NULL,						NULL,
										NULL,					'True',						40
									FROM #tmp_itemcompositionstatus tmp

--SELECT 22

							-- :: Actualizamos la tabla ItemStorage restando las cantidades necesarias para la composición del artículo
							UPDATE	tbItemStorage
								SET		itst_cant = tis.itst_cant - tmp.icomp_qty
								FROM	tbItemStorage						tis
									INNER JOIN #tmp_itemcompositionstatus	tmp
									ON 	tmp.item_id_1	= tis.item_id
								WHERE	tis.comp_id		= @comp_id AND
										tis.stor_id		= @stor_id
							-- -----------------------------------------------



							-- -----------------------------------------------
							-- Actualizacion del Stock
							-- -----------------------------------------------

							--** Genera un ItemTrans con el storprevius del deposito @stor_id_destiny y poenle una ENTRADA: @Qty  sd_id: 350 y it_IsStockAdjustment = True  y ct_transaction = @intCTTransaction
							--   del item @item_id

							---***GA

--SELECT 25

							SET @lStorePreviuos_destiny = ( SELECT tis.itst_cant
															FROM tbItemStorage						tis
															WHERE tis.comp_id = @comp_id		 AND
																  tis.stor_id = @stor_id_destiny AND
																  tis.item_id = @item_id
															)

							INSERT INTO tbItemTransactions
								(
									comp_id,				bra_id,						ct_transaction,
									item_id,				it_qty,						it_priceWithOutOthers,
									it_price,				curr_id,					it_exchangeToBranchCurrency,
									it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
									it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
									it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
									stor_id,				it_storePrevious,			prli_id,
									byor_id,				it_isProduction,			it_isAssociation,
									it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
									it_order,				so_id,						it_guarantee,
									it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
									it_CreditIntPlus,		puco_id,					it_poh_bra_id,
									it_poh_id,				it_soh_id,					it_sod_id,
									rmah_id,				rmad_id,					it_qty_rma,
									it_tis_id_aux,			it_IsStockAdjustment,		sitt_id
								)


								VALUES
								(
									@comp_id,				@intBraIdOfCtTransaction,					@intCTTransaction,
									@item_id,				@Qty,						0,
									0,						@intCurrIdOfBrand,			NULL,
									0,						0,							0,
									0,						0,							0,
									0,						NULL,						1,
									@stor_id_destiny,		isnull(@lStorePreviuos_destiny,0),	NULL,
									NULL,					'False',					'False',
									NULL,					GETDATE(),					NULL,
									0,						NULL,						0,
									0,						0,							0,
									0,						NULL,						NULL,
									NULL,					NULL,						NULL,
									NULL,					NULL,						NULL,
									NULL,					'True',						40
								)


							-- :: Actualizamos la tabla ItemStorage sumando las cantidades de la composicion
							UPDATE tbItemStorage
								SET
									itst_cant = itst_cant + @Qty
								WHERE comp_id = @comp_id
								AND   stor_id = @stor_id_destiny
								AND   item_id = @item_id
							-- -----------------------------------------------
--SELECT 26

							DROP TABLE #tmp_ItemCompositionStatus

						END
					ELSE
						BEGIN
--SELECT 555
							 SET @return_value = 7
							 -- SELECT @return_value
							 SET @ret_ErrorCode =-14			--	-3
	 						 SET @ret_ErrorDescription = (SELECT tut.utexts_desc
														  FROM tbsysUniqueTexts tut			WITH (NOLOCK)
														  WHERE tut.lang_id    = @lang_id
														  AND   tut.utexts_id  = '224042')
							DROP TABLE #tmp_ItemCompositionStatus
							RETURN
						END
				END
	END

	---Fin opcion 4 ---------------------------------------------------------------------------

















	-----------------------------------------------------------------------------------------------
	-- == 5:DESCOMPOSICION=========================================================================
	-----------------------------------------------------------------------------------------------

	IF @option = 5

		 BEGIN
			DECLARE
				@control2		 INT,
				@store_previous	 INT,
				@bitHasComposition AS BIT

			SET @bitHasComposition = 'False'


			SELECT	@control2 = tis.itst_cant
				FROM tbItemStorage tis			WITH (NOLOCK)
				WHERE	tis.comp_id = @comp_id	AND
						tis.stor_id = @stor_id	AND
						tis.item_id = @item_id


			IF @control2 >= @Qty	-- Si hay stock como para descomponerlo...

				BEGIN
					--:: Actualizamos la tabla TbItemStorage restando el stock de los articulos que compondran el nuevo articulo
						DECLARE
							@litem_id		INT,
							@litem_qty		INT,
							@lqty_origin	INT

						DECLARE cursor_InsertItems CURSOR LOCAL FAST_FORWARD FOR
							SELECT
								tic.item_id_1,
								tic.icomp_qty 			[icomp_qty],
								tis.itst_cant
								FROM tbItemComposition tic					WITH (NOLOCK)
								LEFT JOIN tbItemStorage tis					WITH (NOLOCK)
									ON	tis.comp_id = tic.comp_id	AND
										tis.item_id = tic.item_id_1
								WHERE	tic.comp_id	= @comp_id		AND
										tic.item_id	= @item_id		AND
										tis.stor_id = @stor_id_destiny

						OPEN	cursor_InsertItems

						-- lectura anticipada del cursor
						FETCH NEXT FROM	cursor_InsertItems
							INTO
								@litem_id,
								@litem_qty,
								@lqty_origin

						WHILE @@FETCH_STATUS = 0
							BEGIN

								EXEC spItemStorage_insertData @comp_id,@item_id,@stor_id,0
								EXEC spItemStorage_insertData @comp_id,@item_id,@stor_id_destiny,0

								EXEC spItemStorage_insertData @comp_id,@litem_id,@stor_id,0
								EXEC spItemStorage_insertData @comp_id,@litem_id,@stor_id_destiny,0

								-- -----------------------------------------------
								-- Actualizacion del Stock
								-- -----------------------------------------------

								--** Genera un ItemTrans con el storprevius del deposito @stor_id_destiny y poenle una ENTRADA: (@litem_qty * @Qty) sd_id: 350 y it_IsStockAdjustment = True  y ct_transaction = @intCTTransaction
								--   del item @litem_id



								SET @lStorePreviuos_destiny = ( SELECT tis.itst_cant
																	FROM tbItemStorage						tis		--WITH (NOLOCK)
																	WHERE tis.comp_id = @comp_id		 AND
																		  tis.stor_id = @stor_id_destiny AND
																		  tis.item_id = @litem_id --@item_id
																)

								SET @lcurr_id = ( SELECT tb.curr_id
													  FROM tbBranch tb				WITH (NOLOCK)
													  WHERE  tb.comp_id = @comp_id AND
															 tb.bra_id  = @bra_id
															   )


								INSERT INTO tbItemTransactions
									(
										comp_id,				bra_id,						ct_transaction,
										item_id,				it_qty,						it_priceWithOutOthers,
										it_price,				curr_id,					it_exchangeToBranchCurrency,
										it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
										it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
										it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
										stor_id,				it_storePrevious,			prli_id,
										byor_id,				it_isProduction,			it_isAssociation,
										it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
										it_order,				so_id,						it_guarantee,
										it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
										it_CreditIntPlus,		puco_id,					it_poh_bra_id,
										it_poh_id,				it_soh_id,					it_sod_id,
										rmah_id,				rmad_id,					it_qty_rma,
										it_tis_id_aux,			it_IsStockAdjustment,		sitt_id
									)
									VALUES
									(
										@comp_id,				@intBraIdOfCtTransaction,					@intCTTransaction,
										@litem_id,				@litem_qty * @Qty,			0,
										0,						@lcurr_id,					NULL,
										0,						0,							0,
										0,						0,							0,
										0,						NULL,						1,
										@stor_id_destiny,		isnull(@lStorePreviuos_destiny,0),	NULL,
										NULL,					'False',					'False',
										NULL,					GETDATE(),					NULL,
										0,						NULL,						0,
										0,						0,							0,
										0,						NULL,						NULL,
										NULL,					NULL,						NULL,
										NULL,					NULL,						NULL,
										NULL,					'True',						40
									)

			---***GA





								UPDATE tbItemStorage
									SET
										itst_cant = itst_cant + (@litem_qty * @Qty)
									WHERE comp_id = @comp_id
									AND   item_id = @litem_id
									AND   stor_id = @stor_id_destiny

								-- -----------------------------------------------


								 -- ::Actualizar el stor_id con el depósito destino.
								  UPDATE	tbItemSerials
									  SET  stor_id		= @stor_id_destiny,
										   is_checked	= 'False',
										   is_guid		= NULL
									  WHERE comp_id		= @comp_id			AND
								  			item_id		= @litem_id			AND
											stor_id		= @stor_id_destiny	AND
								  			is_checked	= 'True'			AND
								  			is_guid		= @guid




							SET @bitHasComposition = 'True'



							-- NO ; NOOOOOOOOOOOOO
														-- ::Actualizo ItemTransactions y dejo el STORE PREVIOUS
														-- :: Aca buscar por cada entrada LA CANTIDAD QUE TIENE EN EL STOREPREVIOUS
							--							SET @store_previous = 0
							--							SELECT
							--								@store_previous = it_storePrevious
							--								FROM tbitemtransactions
							--								WHERE comp_id = @comp_id
							--								AND it_transaction = @it_transaction
							--
							--							UPDATE tbItemTransactions
							--								SET
							--									it_storePrevious = @lqty_origin
							--								WHERE comp_id = @comp_id
							--								AND it_transaction = @it_transaction

							--							-- :: Actualizamos la tabla ItemStorage restando las cantidades necesarias para la composición del artículo
							--								UPDATE	tbItemStorage
							--								SET		itst_cant = itst_cant - @Qty
							--								WHERE	stor_id	= @stor_id
							--								AND		item_id	= @item_id

							FETCH NEXT FROM	cursor_InsertItems
								INTO
									@litem_id,
									@litem_qty,
									@lqty_origin

						END

						CLOSE cursor_InsertItems
						DEALLOCATE cursor_InsertItems




						-- -----------------------------------------------
						-- Actualizacion del Stock
						-- -----------------------------------------------

						--** Genera un ItemTrans con el storprevius del deposito @stor_id y poenle una SALIDA  (@Qty * -1) sd_id: 350 y it_IsStockAdjustment = True  y ct_transaction = @intCTTransaction
						--   del item @item_id


						---***GA

						-- Solo guarda descomposicion si tenia alguna PUTA parte !!!!!!
						IF @bitHasComposition = 'True'
							BEGIN




								SET @lStorePreviuos = ( SELECT tis.itst_cant
															FROM tbItemStorage				tis	WITH (NOLOCK)
															WHERE tis.comp_id = @comp_id AND
																  tis.stor_id = @stor_id AND
																  tis.item_id = @item_id
																	)

								SET @lcurr_id = ( SELECT tb.curr_id
													  FROM tbBranch tb	WITH (NOLOCK)
													  WHERE  tb.comp_id = @comp_id AND
															 tb.bra_id  = @bra_id
													   )



								INSERT INTO tbItemTransactions
									(
										comp_id,				bra_id,						ct_transaction,
										item_id,				it_qty,						it_priceWithOutOthers,
										it_price,				curr_id,					it_exchangeToBranchCurrency,
										it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
										it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
										it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
										stor_id,				it_storePrevious,			prli_id,
										byor_id,				it_isProduction,			it_isAssociation,
										it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
										it_order,				so_id,						it_guarantee,
										it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
										it_CreditIntPlus,		puco_id,					it_poh_bra_id,
										it_poh_id,				it_soh_id,					it_sod_id,
										rmah_id,				rmad_id,					it_qty_rma,
										it_tis_id_aux,			it_IsStockAdjustment,		sitt_id
									)
									VALUES
									(
										@comp_id,				@intBraIdOfCtTransaction,					@intCTTransaction,
										@item_id,				@Qty * -1,					0,
										0,						@lcurr_id,					NULL,
										0,						0,							0,
										0,						0,							0,
										0,					NULL,						1,
										@stor_id,				isnull(@lStorePreviuos,0),	NULL,
										NULL,					'False',					'False',
										NULL,					GETDATE(),					NULL,
										0,						NULL,						0,
										0,						0,							0,
										0,						NULL,						NULL,
										NULL,					NULL,						NULL,
										NULL,					NULL,						NULL,
										NULL,					'True',						40
									)

								---***GA

								-- :: Actualizamos la tabla ItemStorage restando las cantidades necesarias para la composición del artículo
								UPDATE	tbItemStorage
									SET		itst_cant = itst_cant - @Qty
									WHERE	comp_id = @comp_id	AND
											stor_id	= @stor_id	AND
											item_id	= @item_id

								-- -----------------------------------------------

							END
						ELSE
							BEGIN
								SET @return_value = 8
								 -- SELECT @return_value
								 SET @ret_ErrorCode =-15     -- -3
 								 SET @ret_ErrorDescription = 'Articulo SIN Composicion  / Item without Parts! ! !'
 														--(SELECT tut.utexts_desc
															--  FROM tbsysUniqueTexts tut
															--  WHERE tut.lang_id    = @lang_id
															--  AND   tut.utexts_id  = '224016')
							END

				END

			ELSE

				BEGIN
					SET @return_value = 8
					 -- SELECT @return_value
					 SET @ret_ErrorCode =-16     -- -3
 					 SET @ret_ErrorDescription = (SELECT tut.utexts_desc
												  FROM tbsysUniqueTexts tut
												  WHERE tut.lang_id    = @lang_id
												  AND   tut.utexts_id  = '224016')
				END

		 END

	---Fin opcion 5 ---------------------------------------------------------------------------



	END TRY
	BEGIN CATCH
	  SET @return_value		= 5
	  SET @ret_ErrorCode	=-5
	  SELECT @ret_ErrorDescription = isnull(tut.utexts_desc,'') + '*' + ERROR_MESSAGE()
		  FROM tbsysUniqueTexts tut
		  WHERE tut.lang_id   = @lang_id
			AND tut.utexts_id = 22409
--SELECT 777,ERROR_MESSAGE()
	END CATCH


-- ==

	--SELECT @ret_ErrorCode
	--SELECT @return_value
	--SELECT @ret_ErrorDescription

--==



END
GO





