CREATE PROCEDURE [dbo].[spIndicators4BackGround]
	@comp_id		AS INT,
	@bra_id			AS INT,
	@prof_id		AS INT,
	@user_id		AS INT,
	@lang_id		AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	SET DATEFIRST	7  -- Domingo



	-- OPciones en tbsysOptionsValues ClassID: 1900


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	DECLARE @datProcessingDate AS DATETIME = GETDATE()
	SELECT	@datProcessingDate = tb.bra_processingDate
		FROM tbBranch tb			WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id


	-- Desde - Hasta Día de Hoy
	DECLARE @datFromDate AS DATETIME = dbo.fnGetEnd_or_BeginOfDate(@datProcessingDate,'False')
	DECLARE @datToDate   AS DATETIME = dbo.fnGetEnd_or_BeginOfDate(@datProcessingDate,'True')

	-- Desde Semana en Curso
	DECLARE @datFromDateOfThisWeek AS DATETIME = dbo.fnGetEnd_or_BeginOfDate(DATEADD(DAY, 1 - DATEPART(WEEKDAY, @datFromDate), @datFromDate),'False')
	DECLARE @datToDateOfThisWeek   AS DATETIME = dbo.fnGetEnd_or_BeginOfDate(DATEADD(wk, DATEDIFF(wk, 6, GETDATE()), 5 + 7),'True')


	-- Desde - Hasta Semana Anterior
	DECLARE @datFromDateOfLastWeek AS DATETIME = dbo.fnGetEnd_or_BeginOfDate(dateadd(DAY,-1, dateadd(wk, datediff(wk, 0, getdate()) - 1, 0)),'False')
	DECLARE @datToDateOfLastWeek   AS DATETIME = dbo.fnGetEnd_or_BeginOfDate(DATEADD(DAY,-2, dateadd(wk, datediff(wk, 0, getdate()), 0)),'True')



	-- Desde  Mes en Curso
	DECLARE @datFromDateOfThisMonth AS DATETIME = dbo.fnGetEnd_or_BeginOfDate(DATEADD(dd, -DAY(GETDATE()) + 1, GETDATE()),'False')
	DECLARE @datToDateOfThisMonth   AS DATETIME = dbo.fnGetEnd_or_BeginOfDate(DATEADD(dd,-(DAY(DATEADD(mm,1,GETDATE()))),DATEADD(mm,1,GETDATE())),'True')



	-- ----------------------------------------------------------------------
	-- Retornar esta tabla si NO debe estar habilitado el indicador
	-- evitando calcularlo para no hacer perder el tiempo a al BD
	-- si NO CORRESPONDE calcularlo.
	-- ----------------------------------------------------------------------
	DECLARE @emptyIndicator TABLE(	indicatorValue			DECIMAL(19,2),
									indicatorDescription	NVARCHAR(100),
									indicatorImage			NVARCHAR(100),
									indicatorSubTitle		NVARCHAR(100),
									indicatorEnabled		BIT,
									indicatorLink			NVARCHAR(200) DEFAULT '',
									indicatorSubTitle2		NVARCHAR(100) DEFAULT '',
									indicatorSubTitle3		NVARCHAR(100) DEFAULT '',
									indicatorSubTitle4		NVARCHAR(100) DEFAULT '',
									indicatorSubTitle5		NVARCHAR(100) DEFAULT '',
									indicatorTooltip		NVARCHAR(100) DEFAULT ''
								 )
	INSERT INTO @emptyIndicator(indicatorValue,
								indicatorDescription,
								indicatorImage,
								indicatorSubTitle,
								indicatorEnabled,
								indicatorLink,
								indicatorSubTitle2,
								indicatorSubTitle3,
								indicatorSubTitle4,
								indicatorSubTitle5,
								indicatorTooltip
								)
			VALUES(0,'','','','False','','','','','','')


	SELECT	@datFromDate				AS fromDate,
			@datToDate					AS toDate,
			@datFromDateOfThisWeek		AS fromDateOfThisWeek,
			@datFromDateOfLastWeek		AS fromDateOfLastWeek,
			@datToDateOfLastWeek		AS toDateOfLastWeek,
			@datFromDateOfThisMonth		AS fromDateOfThisMonth

	DECLARE @strQueryName AS NVARCHAR(200) = ''
	DECLARE @bitEnabled   AS BIT		   = 'False'




	-- ---------------------------------------------------------------------------------------------
	-- Comienzo del Cálculo de Indicadores
	-- ---------------------------------------------------------------------------------------------
	DECLARE @bitMustIncludeHR AS BIT = 'False'



	-- -------------------------------------------
	-- 10: Pedidos Pendientes
	-- -------------------------------------------
	SELECT @bitEnabled = 'False'
	SELECT @bitEnabled = 'True'
		FROM tbIndicators_Internal_ByProfile tiibp		WITH (NOLOCK)
	    WHERE	tiibp.comp_id				= @comp_id AND
	            tiibp.prof_id				= @prof_id AND
	            tiibp.optval_indicatorID	= 10
	SELECT @strQueryName = tov.optval_desc
		FROM tbsysOptionsValues	tov						WITH (NOLOCK)
		where	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 1900		AND
				tov.optval_id		= 10

	IF @bitEnabled = 'True'
		BEGIN
			SET @bitMustIncludeHR = 'True'
			SELECT	COUNT(*)			AS indicatorValue,
					@strQueryName		AS indicatorDescription,
					''					AS indicatorImage,
					''					AS indicatorSubTitle,
					@bitEnabled			AS indicatorEnabled,
					''					AS indicatorImage,
					''					AS indicatorLink,
					''					AS indicatorLink,
					''				    AS indicatorTooltip,
					''					AS indicatorSubTitle2,
					''					AS indicatorSubTitle3,
					''					AS indicatorSubTitle4,
					''					AS indicatorSubTitle5
				FROM tbSaleOrderHeader			tsoh			WITH (NOLOCK)
				INNER JOIN tbDocumentsFile		tdf				WITH (NOLOCK)
					ON	tdf.comp_id = tsoh.comp_id	AND
						tdf.bra_id	= tsoh.bra_id	AND
						tdf.df_id	= tsoh.df_id

				WHERE	tsoh.comp_id	= @comp_id		AND
						tsoh.bra_id		= @bra_id		AND
						(
							tdf.sd_id = 1
								OR
							tdf.sd_id = 2
						)
		END
	ELSE
		BEGIN
			SELECT * FROM @emptyIndicator
		END
	-- -------------------------------------------



	-- -------------------------------------------
	-- 20: Pedidos Pendientes del día de HOY
	-- -------------------------------------------
	SELECT @bitEnabled = 'False'
	SELECT @bitEnabled = 'True'
		FROM tbIndicators_Internal_ByProfile tiibp		WITH (NOLOCK)
	    WHERE	tiibp.comp_id				= @comp_id AND
	            tiibp.prof_id				= @prof_id AND
	            tiibp.optval_indicatorID	= 20

	SELECT @strQueryName = tov.optval_desc
		FROM tbsysOptionsValues	tov						WITH (NOLOCK)
		where	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 1900		AND
				tov.optval_id		= 20
	IF @bitEnabled = 'True'
		BEGIN
			SET @bitMustIncludeHR = 'True'
			SELECT  COUNT(*)			AS indicatorValue,
					@strQueryName		AS indicatorDescription,
					''					AS indicatorImage,
					''					AS indicatorSubTitle,
					@bitEnabled			AS indicatorEnabled,
					''					AS indicatorImage,
					''					AS indicatorLink,
					''				    AS indicatorTooltip,
					''					AS indicatorSubTitle2,
					''					AS indicatorSubTitle3,
					''					AS indicatorSubTitle4,
					''					AS indicatorSubTitle5
				FROM tbSaleOrderHeader			tsoh				WITH (NOLOCK)
				INNER JOIN tbDocumentsFile		tdf					WITH (NOLOCK)
					ON	tdf.comp_id = tsoh.comp_id	AND
						tdf.bra_id	= tsoh.bra_id	AND
						tdf.df_id	= tsoh.df_id
				WHERE	tsoh.comp_id	= @comp_id		AND
						tsoh.bra_id		= @bra_id		AND
						(
							tdf.sd_id = 1
								OR
							tdf.sd_id = 2
						)								AND
						tsoh.soh_cd BETWEEN @datFromDate AND @datToDate
		END
	ELSE
		BEGIN
			SELECT * FROM @emptyIndicator
		END
	-- -------------------------------------------



	-- -------------------------------------------
	-- 30: Pedidos Pendientes de esta Semana
	-- -------------------------------------------
	SELECT @bitEnabled = 'False'
	SELECT @bitEnabled = 'True'
		FROM tbIndicators_Internal_ByProfile tiibp		WITH (NOLOCK)
	    WHERE	tiibp.comp_id				= @comp_id AND
	            tiibp.prof_id				= @prof_id AND
	            tiibp.optval_indicatorID	= 30
	SELECT @strQueryName = tov.optval_desc
		FROM tbsysOptionsValues	tov						WITH (NOLOCK)
		where	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 1900		AND
				tov.optval_id		= 30
	IF @bitEnabled = 'True'
		BEGIN
			SET @bitMustIncludeHR = 'True'
			SELECT  COUNT(*)			AS indicatorValue,
					@strQueryName		AS indicatorDescription,
					''					AS indicatorImage,
					''					AS indicatorSubTitle,
					@bitEnabled			AS indicatorEnabled,
					''					AS indicatorImage,
					''					AS indicatorLink,
					''				    AS indicatorTooltip,
					''					AS indicatorSubTitle2,
					''					AS indicatorSubTitle3,
					''					AS indicatorSubTitle4,
					''					AS indicatorSubTitle5
				FROM tbSaleOrderHeader			tsoh				WITH (NOLOCK)
				INNER JOIN tbDocumentsFile		tdf					WITH (NOLOCK)
					ON	tdf.comp_id = tsoh.comp_id	AND
						tdf.bra_id	= tsoh.bra_id	AND
						tdf.df_id	= tsoh.df_id
				WHERE	tsoh.comp_id	= @comp_id		AND
						tsoh.bra_id		= @bra_id		AND
						(
							tdf.sd_id = 1
								OR
							tdf.sd_id = 2
						)								AND
						tsoh.soh_cd BETWEEN @datFromDateOfThisWeek AND @datToDate
		END
	ELSE
		BEGIN
			SELECT * FROM @emptyIndicator
		END
	-- -------------------------------------------



	-- -------------------------------------------
	-- 40: Pedidos Pendientes de la Semana Anterior
	-- -------------------------------------------
	SELECT @bitEnabled = 'False'
	SELECT @bitEnabled = 'True'
		FROM tbIndicators_Internal_ByProfile tiibp		WITH (NOLOCK)
	    WHERE	tiibp.comp_id				= @comp_id AND
	            tiibp.prof_id				= @prof_id AND
	            tiibp.optval_indicatorID	= 40
	SELECT @strQueryName = tov.optval_desc
		FROM tbsysOptionsValues	tov						WITH (NOLOCK)
		where	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 1900		AND
				tov.optval_id		= 40
	IF @bitEnabled = 'True'
		BEGIN
			SET @bitMustIncludeHR = 'True'
			SELECT  COUNT(*)			AS indicatorValue,
					@strQueryName		AS indicatorDescription,
					''					AS indicatorImage,
					''					AS indicatorSubTitle,
					@bitEnabled			AS indicatorEnabled,
					''					AS indicatorImage,
					''					AS indicatorLink,
					''				    AS indicatorTooltip,
					''					AS indicatorSubTitle2,
					''					AS indicatorSubTitle3,
					''					AS indicatorSubTitle4,
					''					AS indicatorSubTitle5
				FROM tbSaleOrderHeader			tsoh				WITH (NOLOCK)
				INNER JOIN tbDocumentsFile		tdf					WITH (NOLOCK)
					ON	tdf.comp_id = tsoh.comp_id	AND
						tdf.bra_id	= tsoh.bra_id	AND
						tdf.df_id	= tsoh.df_id
				WHERE	tsoh.comp_id	= @comp_id		AND
						tsoh.bra_id		= @bra_id		AND
						(
							tdf.sd_id = 1
								OR
							tdf.sd_id = 2
						)								AND
						tsoh.soh_cd BETWEEN @datFromDateOfLastWeek AND @datToDateOfLastWeek
		END
	ELSE
		BEGIN
			SELECT * FROM @emptyIndicator
		END
	-- -------------------------------------------



	-- -------------------------------------------
	-- 50: Pedidos Pendientes de este mes
	-- -------------------------------------------
	SELECT @bitEnabled = 'False'
	SELECT @bitEnabled = 'True'
		FROM tbIndicators_Internal_ByProfile tiibp		WITH (NOLOCK)
	    WHERE	tiibp.comp_id				= @comp_id AND
	            tiibp.prof_id				= @prof_id AND
	            tiibp.optval_indicatorID	= 50
	SELECT @strQueryName = tov.optval_desc
		FROM tbsysOptionsValues	tov						WITH (NOLOCK)
		where	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 1900		AND
				tov.optval_id		= 50
	IF @bitEnabled = 'True'
		BEGIN
			SET @bitMustIncludeHR = 'True'
			SELECT  COUNT(*)			AS indicatorValue,
					@strQueryName		AS indicatorDescription,
					''					AS indicatorImage,
					''					AS indicatorSubTitle,
					@bitEnabled			AS indicatorEnabled,
					''					AS indicatorImage,
					''					AS indicatorLink,
					''				    AS indicatorTooltip,
					''					AS indicatorSubTitle2,
					''					AS indicatorSubTitle3,
					''					AS indicatorSubTitle4,
					''					AS indicatorSubTitle5
				FROM tbSaleOrderHeader			tsoh				WITH (NOLOCK)
				INNER JOIN tbDocumentsFile		tdf					WITH (NOLOCK)
					ON	tdf.comp_id = tsoh.comp_id	AND
						tdf.bra_id	= tsoh.bra_id	AND
						tdf.df_id	= tsoh.df_id
				WHERE	tsoh.comp_id	= @comp_id		AND
						tsoh.bra_id		= @bra_id		AND
						(
							tdf.sd_id = 1
								OR
							tdf.sd_id = 2
						)								AND
						tsoh.soh_cd BETWEEN @datFromDateOfThisMonth AND @datToDate
		END
	ELSE
		BEGIN
			SELECT * FROM @emptyIndicator
		END
	-- -------------------------------------------






	-- -------------------------------------------
	-- 75: En Fecha de Deposito
	-- -------------------------------------------
	SELECT @bitEnabled = 'False'
	SELECT @bitEnabled = 'True'
		FROM tbIndicators_Internal_ByProfile tiibp		WITH (NOLOCK)
	    WHERE	tiibp.comp_id				= @comp_id AND
	            tiibp.prof_id				= @prof_id AND
	            tiibp.optval_indicatorID	= 75
	SELECT @strQueryName = tov.optval_desc
		FROM tbsysOptionsValues	tov						WITH (NOLOCK)
		where	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 1900		AND
				tov.optval_id		= 75
	IF @bitEnabled = 'True'
		BEGIN
			SET @bitMustIncludeHR = 'True'
			SELECT  COUNT(*)			AS indicatorValue,
					@strQueryName		AS indicatorDescription,
					''					AS indicatorImage,
					'$ ' + convert(nvarchar(20),convert(decimal(19,2),ISNULL(SUM(tcp1.chp_total),0)))	AS indicatorSubTitle,
					@bitEnabled			AS indicatorEnabled,
					''					AS indicatorImage,
					''					AS indicatorLink,
					''				    AS indicatorTooltip,
					''					AS indicatorSubTitle2,
					''					AS indicatorSubTitle3,
					''					AS indicatorSubTitle4,
					''					AS indicatorSubTitle5
			FROM tbCheckPortfolio	tcp1		WITH (NOLOCK)
			INNER JOIN tbBranch		tb			WITH (NOLOCK)
				ON	tb.comp_id		= @comp_id AND
					tb.bra_id		= @bra_id
			WHERE	tcp1.comp_id	= @comp_id	AND
					tcp1.bra_id		= @bra_id	AND
					tcp1.chp_isAvailable = 1	AND tcp1.chp_PayDate <= @datProcessingDate
		END
	ELSE
		BEGIN
			SELECT * FROM @emptyIndicator
		END
	-- -------------------------------------------





	-- -------------------------------------------
	-- 65: Valores en Cartera para Esta Semana
	-- -------------------------------------------
	SELECT @bitEnabled = 'False'
	SELECT @bitEnabled = 'True'
		FROM tbIndicators_Internal_ByProfile tiibp		WITH (NOLOCK)
	    WHERE	tiibp.comp_id				= @comp_id AND
	            tiibp.prof_id				= @prof_id AND
	            tiibp.optval_indicatorID	= 65
	SELECT @strQueryName = tov.optval_desc
		FROM tbsysOptionsValues	tov						WITH (NOLOCK)
		where	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 1900		AND
				tov.optval_id		= 65
	IF @bitEnabled = 'True'
		BEGIN
			SET @bitMustIncludeHR = 'True'
			SELECT  COUNT(*)			AS indicatorValue,
					@strQueryName		AS indicatorDescription,
					''					AS indicatorImage,
					'$ ' + convert(nvarchar(20),convert(decimal(19,2),ISNULL(SUM(tcp1.chp_total),0)))	AS indicatorSubTitle,
					@bitEnabled			AS indicatorEnabled,
					''					AS indicatorImage,
					''					AS indicatorLink,
					''				    AS indicatorTooltip,
					''					AS indicatorSubTitle2,
					''					AS indicatorSubTitle3,
					''					AS indicatorSubTitle4,
					''					AS indicatorSubTitle5
			FROM tbCheckPortfolio	tcp1		WITH (NOLOCK)
			INNER JOIN tbBranch		tb			WITH (NOLOCK)
				ON	tb.comp_id		= @comp_id AND
					tb.bra_id		= @bra_id
			WHERE	tcp1.comp_id	= @comp_id	AND
					tcp1.bra_id		= @bra_id	AND
					tcp1.chp_isAvailable = 1	AND tcp1.chp_PayDate < @datToDateOfThisWeek
		END
	ELSE
		BEGIN
			SELECT * FROM @emptyIndicator
		END
	-- -------------------------------------------



	-- -------------------------------------------
	-- 70: Valores en Cartera para Este Mes
	-- -------------------------------------------
	SELECT @bitEnabled = 'False'
	SELECT @bitEnabled = 'True'
		FROM tbIndicators_Internal_ByProfile tiibp		WITH (NOLOCK)
	    WHERE	tiibp.comp_id				= @comp_id AND
	            tiibp.prof_id				= @prof_id AND
	            tiibp.optval_indicatorID	= 70
	SELECT @strQueryName = tov.optval_desc
		FROM tbsysOptionsValues	tov						WITH (NOLOCK)
		where	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 1900		AND
				tov.optval_id		= 70
	IF @bitEnabled = 'True'
		BEGIN
			SET @bitMustIncludeHR = 'True'
			SELECT  COUNT(*)			AS indicatorValue,
					@strQueryName		AS indicatorDescription,
					''					AS indicatorImage,
					'$ ' + convert(nvarchar(20),convert(decimal(19,2),ISNULL(SUM(tcp1.chp_total),0)))	AS indicatorSubTitle,
					@bitEnabled			AS indicatorEnabled,
					''					AS indicatorImage,
					''					AS indicatorLink,
					''				    AS indicatorTooltip,
					''					AS indicatorSubTitle2,
					''					AS indicatorSubTitle3,
					''					AS indicatorSubTitle4,
					''					AS indicatorSubTitle5
			FROM tbCheckPortfolio	tcp1		WITH (NOLOCK)
			INNER JOIN tbBranch		tb			WITH (NOLOCK)
				ON	tb.comp_id		= @comp_id AND
					tb.bra_id		= @bra_id
			WHERE	tcp1.comp_id	= @comp_id	AND
					tcp1.bra_id		= @bra_id	AND
					tcp1.chp_isAvailable = 1	AND tcp1.chp_PayDate < @datToDateOfThisMonth
		END
	ELSE
		BEGIN
			SELECT * FROM @emptyIndicator
		END
	-- -------------------------------------------



	-- -------------------------------------------
	-- 60: TOTAL Valores en Cartera
	-- -------------------------------------------
	SELECT @bitEnabled = 'False'
	SELECT @bitEnabled = 'True'
		FROM tbIndicators_Internal_ByProfile tiibp		WITH (NOLOCK)
	    WHERE	tiibp.comp_id				= @comp_id AND
	            tiibp.prof_id				= @prof_id AND
	            tiibp.optval_indicatorID	= 60
	SELECT @strQueryName = tov.optval_desc
		FROM tbsysOptionsValues	tov						WITH (NOLOCK)
		where	tov.lang_id			= @lang_id	AND
				tov.optval_class	= 1900		AND
				tov.optval_id		= 60
	IF @bitEnabled = 'True'
		BEGIN
			SET @bitMustIncludeHR = 'True'
			SELECT  COUNT(*)			AS indicatorValue,
					@strQueryName		AS indicatorDescription,
					''					AS indicatorImage,
					'$ ' + convert(nvarchar(20),convert(decimal(19,2),ISNULL(SUM(tcp1.chp_total),0)))	AS indicatorSubTitle,
					@bitEnabled			AS indicatorEnabled,
					''					AS indicatorImage,
					''					AS indicatorLink,
					''				    AS indicatorTooltip,
					''					AS indicatorSubTitle2,
					''					AS indicatorSubTitle3,
					''					AS indicatorSubTitle4,
					''					AS indicatorSubTitle5
			FROM tbCheckPortfolio	tcp1		WITH (NOLOCK)
			INNER JOIN tbBranch		tb			WITH (NOLOCK)
				ON	tb.comp_id		= @comp_id AND
					tb.bra_id		= @bra_id
			WHERE	tcp1.comp_id	= @comp_id	AND
					tcp1.bra_id		= @bra_id	AND
					tcp1.chp_isAvailable = 1
		END
	ELSE
		BEGIN
			SELECT * FROM @emptyIndicator
		END
	-- -------------------------------------------




	-- Incluye una Raya de Separacion
	IF @bitMustIncludeHR = 'True'
		BEGIN
			SET @bitMustIncludeHR = 'False'
			SELECT  -999998									AS indicatorValue,
					'<hr/>'									AS indicatorDescription,
					''										AS indicatorImage,
					''		AS indicatorSubTitle,
					CONVERT(BIT,'True')						AS indicatorEnabled,
					''
							   								AS indicatorLink
		END





	-- VIEJO: https://app.powerbi.com/view?r=eyJrIjoiYjRlOGI2ZDUtZGUwNi00ZDgyLWI2NTAtNTlkZTNiNDI5OGQ3IiwidCI6ImRiODBiNTQzLTU3MDctNDBjMS04NWY2LTFkZDI4OGQ4MzIyOSIsImMiOjR9
	-- https://app.powerbi.com/view?r=eyJrIjoiYWI0ODdjN2QtNTlmNi00YjU5LTgwZWItOGJjNWEyNmQ2ZTc5IiwidCI6ImRiODBiNTQzLTU3MDctNDBjMS04NWY2LTFkZDI4OGQ4MzIyOSIsImMiOjR9&pageName=ReportSection2581f918a68805000975

	-- -------------------------------------------
	-- DEMO PowerBoard
	-- -------------------------------------------

		SELECT  -999997									AS indicatorValue,
				'Demo Tablero PowerBI©'							AS indicatorDescription,
				'evolutionUp.png'						AS indicatorImage,
				'Haga Click en la imágen para ver la Demostración, NO disponible desde Internet Explorer. CONSULTE CON SU IMPLEMENTADOR.'		AS indicatorSubTitle,
				CONVERT(BIT,'True')						AS indicatorEnabled,
				'https://app.powerbi.com/view?r=eyJrIjoiYWI0ODdjN2QtNTlmNi00YjU5LTgwZWItOGJjNWEyNmQ2ZTc5IiwidCI6ImRiODBiNTQzLTU3MDctNDBjMS04NWY2LTFkZDI4OGQ4MzIyOSIsImMiOjR9&pageName=ReportSection2581f918a68805000975'
							   							AS indicatorLink,
				'Demo de acceso a un tablero PowerBI©. Este tablero es externo a GlobalBluePoint© ERP. Los datos son meramente demostrativos. Se activa mediante la puerta de enlace PowerBI© y puede usarse bajo la licencia gratuita de su desarrollador.'
														AS indicatorTooltip,
				''										AS indicatorSubTitle2,
				''										AS indicatorSubTitle3,
				''										AS indicatorSubTitle4,
				''										AS indicatorSubTitle5
	-- -------------------------------------------














END
GO















create PROCEDURE [dbo].[spInsuranceAgent_getCombo]
(
	@comp_id			int
)
AS

BEGIN

	/*
	declare @comp_id   int

	select @comp_id =1
	*/

	select
			tbia.insu_id 				[id],
			tbia.insu_desc				[desc]
		from	dbo.tbInsuranceAgent	tbia		WITH (NOLOCK)

		where	tbia.comp_id =	@comp_id
		Order By	tbia.insu_desc

END









GO






