CREATE PROCEDURE [dbo].[spInvoiceDocumentItemTmp_getDataById]
(
		@idit_id		int
)
as
set nocount on

select	' ' [ ], ' ' [ ],
		idit.idit_guid,
		idit.item_id,
		i.item_desc,
		idit.idit_itemDesc,
		idit.idit_qty,
		idit.idit_price,
		idit.tax_id,
		tn.tax_desc,
		idit.stor_id,
		stor.stor_desc,
		idit.idit_CD,
		idit.bra_id,
		idit.idit_id


from	dbo.tbInvoiceDocumentItemTmp	idit

		left join dbo.tbItem		i
		on i.comp_id		= idit.comp_id
		and i.item_id		= idit.item_id

		left join dbo.tbTaxName		tn
		on tn.comp_id		= idit.comp_id
		and tn.tax_id		= idit.tax_id

		left join dbo.tbStorage		stor
		on stor.comp_id		= idit.comp_id
		and stor.stor_id	= idit.stor_id


where	idit.idit_id	=	@idit_id

order by idit.idit_id






















GO







