CREATE PROCEDURE [dbo].[spItem_ApplyItemsForPurchaseOrders_Selection]
(
		@comp_id			Int,
		--@selection          Bit,
		@guid				Uniqueidentifier,
		@return_value		Int Output
	)
as

set nocount on


-----------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------

/*


Declare @comp_id			Int,
		--@selection          Bit,
		@guid				Uniqueidentifier

Select  @comp_id			= 1,
--		@selection          = 'True',
		@guid				= 'b73850d7-7253-4c83-abcc-47987c3d747a'

*/

-----------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------



If Exists (Select
				1 From tbPurchaseOrderDetailTmp tpodt

				Where	comp_id			= @comp_id
				And		podt_guid		= @guid
				And     podt_qty		<> '-999'
				And		podt_Selection  = 'TRUE'
			)
BEGIN

	Delete tbPurchaseOrderDetailTmp
	Where podt_guid = @guid
	And podt_Selection = 'False'



	Update	tbPurchaseOrderDetailTmp
	SET		podt_Selection = Null

	Where	comp_id			= @comp_id
	And		podt_guid		= @guid
	And     podt_qty		<> '-999'
	And		podt_Selection  = 'TRUE'

	Set @return_value = 0
END
ELSE
	BEGIN
		Delete tbPurchaseOrderDetailTmp
		Where podt_guid = @guid
		And podt_Selection = 'False'

		Set @return_value = 1



	END

GO


CREATE PROCEDURE [dbo].[spItem_CodeAlternative_Process_Auto]
(
	@comp_id					INT,
	@user_id					INT,
	@prof_id					INT,
	@item_id					INT,		-- ahora no se pasandolo desde la pagina - 30/04/19
	@item_Code					NVARCHAR(MAX),
	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT,
	@processOption				INT,	--1.-AGREGAR AL CÓDIGO YA EXISTENTE // 2.-REEMPLAZAR CÓDIGO YA EXISTENTE // 3.-NO EFECTUAR ACCIÓN SI YA EXISTE UN CÓDIGO
	@item_code_main				NVARCHAR(50)
)
AS


---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
	DECLARE
		@comp_id					INT,
		@user_id					INT,
		@prof_id					INT,
		@item_id					INT,
		@item_Code					NVARCHAR(MAX),
		@guid						UNIQUEIDENTIFIER,
		@intROW						INT,
		@bolIsOK					BIT,
		@processOption				INT

	SELECT
		@comp_id					= 1,
		@user_id					= 119,
		@prof_id					= 1,
		@item_id					= 493,
		@item_Code					= 'TEST',
		@guid						= 'E011017D-8C70-400D-A241-C5B0E9B921FA',
		@intROW						= 7,
		@bolIsOK					= 'True',
		@processOption				= 1
*/
---------------------------------------------------------------------------------


SET NOCOUNT ON
	BEGIN
		DECLARE @return_value	INT

		SET	@return_value = 1
		BEGIN TRY


			--Recuperamos el item_id mediante el codigo
			SELECT
				@item_id = ti.item_id

				FROM tbitem  ti	WITH (NOLOCK)

				WHERE	ti.comp_id		= @comp_id		AND
						ti.item_code	= @item_code_main



			IF EXISTS (SELECT 1 FROM tbItem_codeAlternative tica WHERE tica.comp_id = @comp_id AND tica.item_id = @item_id)
				BEGIN
					--1.-AGREGAR AL CÓDIGO YA EXISTENTE
					IF @processOption = 1
						BEGIN
							UPDATE tbItem_codeAlternative
							SET
								item_codeAlternative = item_codeAlternative + ' ' + @item_Code
							WHERE	comp_id = @comp_id AND
									item_id = @item_id
						END

					--2.-REEMPLAZAR CÓDIGO YA EXISTENTE
					IF @processOption = 2
						BEGIN
							UPDATE tbItem_codeAlternative
							SET
								item_codeAlternative = @item_Code
							WHERE	comp_id = @comp_id AND
									item_id = @item_id
						END
				END
			ELSE
				BEGIN
					INSERT INTO tbItem_codeAlternative
					(
						comp_id,
						item_id,
						item_codeAlternative
					)
					VALUES
					(
						@comp_id,
						@item_id,
						@item_Code
					)
				END



			--set	@return_value = IDENT_CURRENT('tbItemAssociation')   -- @@identity

			END TRY
			BEGIN CATCH
				SET	@return_value = 0
			END CATCH

			SELECT	@return_value
			IF		@return_value <> 0
				BEGIN
					EXEC [spItems_Process_ImportLog_InsertData] @comp_id, @guid, @user_id, @intROW, NULL, NULL
				END

	END


















GO



CREATE PROCEDURE [dbo].[spItem_CodeAlternative_Process_AutoValidate]
(
	@comp_id					INT,
	@user_id					INT,
	@item_id					INT,
	@guid						UNIQUEIDENTIFIER,
	@intRow						INT,
	@item_code_main				NVARCHAR(50)
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@user_id	INT,
				@item_id	INT,
				@guid		UNIQUEIDENTIFIER,
				@intRow		INT
		*/
		-- -----------------------------------------------------------------------------

		DECLARE @errormessage   NVARCHAR(4000)
		DECLARE @return_value	INT
		DECLARE @bolIsOK		BIT

		SET     @bolIsOK		= 'True'
		SET		@errormessage	= ''

		---- -----------------------------------------------------------------------------------------------------
		----
		---- -----------------------------------------------------------------------------------------------------
		--	IF	@item_id	= -1
		--		BEGIN
		--			SET	@bolIsOK		= 'False'
		--			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Artículo'
		--		END
		--	ELSE
		--		BEGIN
		--			IF NOT EXISTS (SELECT ti.item_id
		--						   FROM		tbItem ti		WITH (NOLOCK)
		--							WHERE	ti.comp_id		= @comp_id		AND
		--									ti.item_id		= @item_id)
		--				BEGIN
		--					SET	@bolIsOK		= 'False'
		--					SET @errormessage	= @errormessage + '---' + 'El ID de Artículo es incorrecto'
		--				END
		--		END
		-------------------------------------------------------------------------------------------------------------------------ss



		------Codigo del articulo combo -----------------------------------------------------------------------------------------------------------
		if	@item_code_main	= ''
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'No ingresó el Código del Artículo '
			END
		ELSE
			BEGIN

				IF not EXISTS (SELECT top 1 ti.item_id
    									FROM tbitem ti								WITH (NOLOCK)
    									WHERE	ti.comp_id				= @comp_id AND
												ti.item_code			= @item_code_main
								)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'No existe un Artículo para el Código del Artículo ingresado'
					END
			END

		-----------------------------------------------------------------------------------------------------------------------



		-- -----------------------------------------------------------------------------------------------------
		-- si no viene nada del excel para estos campos le pondra 0 : @qty
		-- 1 True  : Todo ok para insertar.
		-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
		-- -----------------------------------------------------------------------------------------------------
			IF @bolIsOK = 'True'
				BEGIN
					SELECT
						1				[bolIsOK],
						@intROW			[Nº Fila],
						@errormessage	[Error]
				END
			ELSE
				BEGIN

					EXEC [spItems_Process_ImportLog_InsertData] @comp_id, @guid, @user_id, @intROW, NULL, @errormessage

					SELECT
						0				[bolIsOK],
						@intROW			[Nº Fila],
						@errormessage	[Error]
				END
		-- -----------------------------------------------------------------------------------------------------
	END
GO




CREATE PROCEDURE spItem_CommercialCampaign_getCombo
(
	@comp_id	INT,
	@bra_id		INT,
	@prli_id	INT,
	@item_id	INT
)

AS SET NOCOUNT ON

-- ----------------------------------------
-- TESTING
-- ----------------------------------------
/*
	DECLARE
		@comp_id	INT,
		@bra_id		INT,
		@prli_id	INT,
		@item_id	INT

	SELECT
		@comp_id	= 1,
		@bra_id		= 1,
		@prli_id	= 1,
		@item_id	= 256
*/
-- ----------------------------------------


	BEGIN

		SELECT
			ticc.camp_id	[Id],
			ticc.camp_desc	[Desc]

		FROM tbItem_CommercialCampaign ticc

		WHERE	ticc.comp_id	= @comp_id							AND
				(@bra_id		= -1 OR ticc.bra_id		= @bra_id)	AND
				(@prli_id		= -1 OR ticc.prli_id	= @prli_id)	AND
				(@item_id		= -1 OR ticc.item_id	= @item_id)

	END
GO




CREATE PROCEDURE spItem_CommercialCampaign_getGenericGridData
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@supp_id	INT
)
AS SET NOCOUNT ON

	-- ------------------------------
	-- TESTING
	-- ------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@supp_id	INT
		SELECT
			@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@supp_id	= 8110
	*/
	-- ------------------------------


	BEGIN

		SELECT
			ticc.camp_desc,
			ticc.camp_active,
			tov.optval_desc
		FROM tbItem_CommercialCampaign						ticc

			INNER JOIN tbsysOptionsValues					tov
			ON	tov.optval_id	 = ticc.camp_status	AND
				tov.optval_class = 311				AND
				tov.lang_id		 = @lang_id

		WHERE	ticc.comp_id	 = @comp_id AND
				ticc.bra_id		 = @bra_id	AND
				ticc.supp_id	 = @supp_id	AND
				ticc.camp_active = 'False'	AND
				tov.optval_id	 = 1

	END
GO





