	@user_id					INT,
	@prof_id					INT,

	@camp_desc					NVARCHAR(200),
	@camp_validFrom				DATETIME,
	@camp_validTo				DATETIME,
	@camp_disabled				BIT,
	@camp_active				BIT,
	@camp_qtyCheck				BIT,
	@camp_qtyAvailable			INT,
	@camp_qtyTotal				INT,
	@camp_costMinus				DECIMAL(19,4),
	@camp_priceMinus			DECIMAL(19,4),
	@camp_pricePercentMinus		DECIMAL(19,4),

	@bra_id						INT,
	@supp_id					INT,
	@prli_id					INT,
	@item_id					INT,
	@cat_id						INT,
	@subcat_id					INT,
