	@st_id						INT,
	@camp_status				INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT


)
AS


---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT


SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id4session				= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,


	@bolIsOK					='True',
	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 1000

---------------------------------------------------------------------------------
*/
SET NOCOUNT ON
SET DATEFORMAT 'YMD'


BEGIN

	declare @return_value	INT


	if	@bra_id				= -1  SET @bra_id		= NULL
	if	@supp_id			= -1  SET @supp_id		= NULL
	if	@prli_id			= -1  SET @prli_id		= NULL
	if	@item_id			= -1  SET @item_id		= NULL
	if	@cat_id				= -1  SET @cat_id		= NULL
	if	@subcat_id			= -1  SET @subcat_id	= NULL
	if	@brand_id			= -1  SET @brand_id		= NULL
	if	@st_id				= -1  SET @st_id		= NULL
	if	@camp_status		= -1  SET @camp_status	= 0


				BEGIN TRY


				INSERT INTO tbItem_CommercialCampaign
				(
					comp_id,
					bra_id,
					camp_desc,
					camp_validFrom,
					camp_validTo,
					camp_disabled,
					camp_active,
					camp_status,
					prli_id,
					item_id,
					cat_id,
					subcat_id,
					brand_id,
					supp_id,
					camp_qtyCheck,
					camp_qtyAvailable,
					camp_qtyTotal,
					camp_costMinus,
					camp_priceMinus,
					st_id,
					camp_pricePercentMinus
				)
				VALUES
				(
					@comp_id,
					@bra_id,
					@camp_desc,
					@camp_validFrom,
					@camp_validTo,
					@camp_disabled,
					@camp_active,
					@camp_status,
					@prli_id,
					@item_id,
					@cat_id,
					@subcat_id,
					@brand_id,
					@supp_id,
					@camp_qtyCheck,
					@camp_qtyAvailable,
					@camp_qtyTotal,
					@camp_costMinus,
					@camp_priceMinus,
					@st_id,
					@camp_pricePercentMinus
				)


			set	@return_value = IDENT_CURRENT('tbItem_CommercialCampaign')   -- @@identity

			END TRY
			BEGIN CATCH
				set	@return_value = 0
			END CATCH


					--IF @return_value <> 0
					--	BEGIN
					--		EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,@return_value,NULL
					--	END




END


















GO





