	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@curr_id					INT,


	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------


set nocount on

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''


	-----------------------------------------------------------------------------------------------------------------
	-- Sucursal
	-----------------------------------------------------------------------------------------------------------------
	if	@bra_id	<> -1
	BEGIN

	IF NOT EXISTS (SELECT
					tb.bra_id
					FROM tbBranch tb		WITH (NOLOCK)
					WHERE   tb.comp_id			= @comp_id and
		               		tb.bra_id			= @bra_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Sucursal es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------
	-- Proveedor
	-----------------------------------------------------------------------------------------------------------------
	if	@supp_id	<> -1
	BEGIN

	IF NOT EXISTS (SELECT
					ts.supp_id
					FROM	tbSupplier AS ts		WITH (NOLOCK)
					WHERE   ts.comp_id			= @comp_id and
		               		ts.supp_id			= @supp_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Proveedor es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------
	-- Lista de Precios
	-----------------------------------------------------------------------------------------------------------------
	if	@prli_id	<> -1
	BEGIN

	IF NOT EXISTS (SELECT
					tpli.prli_id
	                FROM tbPriceListItems	 tpli 		WITH (NOLOCK)
					WHERE   tpli.comp_id			= @comp_id and
		               		tpli.prli_id			= @prli_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de la Lista de Precio es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------


	-----------------------------------------------------------------------------------------------------------------
	-- Artículo
	-----------------------------------------------------------------------------------------------------------------
	if	@item_id	<> -1
	BEGIN

	IF NOT EXISTS (SELECT
					ti.item_id
	                FROM tbItem AS ti		WITH (NOLOCK)
					WHERE   ti.comp_id			= @comp_id and
		               		ti.item_id			= @item_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Artículo es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------


	-----------------------------------------------------------------------------------------------------------------
	-- Categoría
	-----------------------------------------------------------------------------------------------------------------
	if	@cat_id	<> -1
	BEGIN

	IF NOT EXISTS (SELECT
					tc.cat_id
	                FROM tbCategory AS tc		WITH (NOLOCK)
					WHERE   tc.comp_id			= @comp_id and
		               		tc.cat_id			= @cat_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Categoría es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------
	-- SubCategoría
	-----------------------------------------------------------------------------------------------------------------
	if	@subcat_id	<> -1
	BEGIN

	IF NOT EXISTS (SELECT
					tc.subcat_id
					FROM tbSubCategory  AS tc		WITH (NOLOCK)
					WHERE   tc.comp_id			= @comp_id and
		               		tc.subcat_id		= @subcat_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de SubCategoría es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------
	-- Marca
	-----------------------------------------------------------------------------------------------------------------
	if	@brand_id	<> -1
	BEGIN

	IF NOT EXISTS (SELECT
					tb.brand_id
					FROM tbBrand tb		WITH (NOLOCK)
					WHERE   tb.comp_id			= @comp_id and
		               		tb.brand_id			= @brand_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Marca es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------
	-- Condicion de Venta
	-----------------------------------------------------------------------------------------------------------------
	if	@st_id	<> -1
	BEGIN

	IF NOT EXISTS (SELECT
					tst.st_id
	               FROM tbSalesTerms AS tst		WITH (NOLOCK)
					WHERE   tst.comp_id			= @comp_id and
		               		tst.st_id			= @st_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de la Condición de Venta es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------
	-- Estado
	-----------------------------------------------------------------------------------------------------------------
	if	@camp_status	<> -1
	BEGIN

	IF NOT EXISTS (SELECT
					tov.optval_id
	                FROM tbsysOptionsValues AS tov		WITH (NOLOCK)
					WHERE   tov.lang_id				= @lang_id	 AND
							tov.optval_class		= 311		 AND
		               		tov.optval_id			= @camp_status)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Estado es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------





	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Fila],
				@errormessage	[Error],
				'True'			[Exists]
		END
	ELSE
		BEGIN

			--EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Fila],
				@errormessage	[Error],
				'False'			[Exists]
		END


END


















GO



----------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Date   : 06/10/2024
-- Author : GA
-- Detail : Al finalizar el proceso de importacion se muestra en una grilla que registros fueron dados de alta y los que no.
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
create PROCEDURE [dbo].[spItem_CommercialCampaign_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN



	SELECT
			isnull(tc.camp_desc,'')									[contact_name],
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbItem_CommercialCampaign					tc		WITH (NOLOCK)
		ON	tc.comp_id		= tpclil.comp_id	AND
			tc.camp_id		= tpclil.item_id

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO








