-- MOS
-- Fuerza a que se ejecuten las reglas de actualizacion de ptrecios para los rangos seleccionados.-

CREATE PROCEDURE [dbo].[spItem_ForceCostRecalculation]
(
	@comp_id	INT,
	@bra_id		INT,
	@cat_id		INT,
	@subcat_id	INT,
	@brand_id	INT,
	@pres_id	INT,
	@supp_id	INT,
	@item_id	INT,
	@coslis_id	INT,
	@Item_Guid	UNIQUEIDENTIFIER
)

AS

BEGIN



	-- ------------------------------------------------------------------------------
	-- Test
	-- ------------------------------------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@bra_id		INT,
		@cat_id		INT,
		@subcat_id	INT,
		@brand_id	INT,
		@pres_id	INT,
		@supp_id	INT,
		@item_id	INT,
		@coslis_id	INT,
		@Item_Guid	UNIQUEIDENTIFIER


	SELECT
		@comp_id	= 1,
		@bra_id		= -1,
		@cat_id		= -1,
		@subcat_id	= -1,
		@brand_id	= -1,
		@pres_id	= -1,
		@supp_id	= -1,
		@item_id	= -1,
		@coslis_id	= 1,
		@Item_Guid	= NEWID()
	*/
	-- ------------------------------------------------------------------------------





	SET NOCOUNT ON


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros
		-- NOTA: Para buscar todas las incidencias
		-- de este método ejecutar el "BuscarTexto" en la base de datos
		-- con el valor de referencia "#8600"
		-- Página de EJEMPLO:App_Reports_App_WebForms_wfmRptFilters_PriceLists2_Testing
		-- -------------------------------------------------------------
		DECLARE @objGUID AS UNIQUEIDENTIFIER
		SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@Item_Guid)
		DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf      WITH (NOLOCK)
				WHERE tcf.sl_guid	  = @objGUID      AND
					  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti	WITH (NOLOCK)
					WHERE ti.comp_id = @comp_id
			END



	DECLARE @intCompId		AS int
	DECLARE @intItemId		AS INT
	DECLARE @intCoslis_Id	AS INT
	DECLARE curItemCostList CURSOR LOCAL  FAST_FORWARD FOR

	--			UPDATE tbItemCostList
	--			SET coslis_price = ticl.coslis_price
			SELECT	ticl.comp_id,
					ticl.coslis_id,
					ticl.item_id
				FROM tbItemCostList ticl		WITH (NOLOCK)
				INNER JOIN tbitem TI			WITH (NOLOCK)
					ON		ti.comp_id = ticl.comp_id
						AND ti.item_id = ticl.item_id

				INNER JOIN @tblComplexFilter_Items	TEMP
				ON TEMP.item_id = TI.item_id

			WHERE
					 ti.comp_id = @comp_id
				--AND (@bra_id    = -1	OR ti.bra_id	= @bra_id	OR ti.bra_id IS NULL)
				AND (@cat_id    = -1	OR ti.cat_id	= @cat_id)
				AND (@subcat_id = -1	OR ti.subcat_id = @subcat_id)
				AND (@pres_id   = -1	OR ti.pres_id	= @pres_id)
				AND (@brand_id  = -1	OR ti.brand_id	= @brand_id)
				AND (@item_id   = -1	OR ti.item_id	= @item_id)
				AND (@supp_id   = -1	OR ti.supp_id	= @supp_id)
				AND (@coslis_id = -1    or ticl.coslis_id = @coslis_id)
				-- --------------------------------------------------------------------------------------------------------------
				-- MOS 06-2020 Solo ejecute sobre los items que NO son combos que suman el precio de sus partes, sino puede pasar
				-- que la regra calcule el precio de venta y no la suma del combo.
				-- **wergfklnwek8920347654**ewqrfqw2
				-- --------------------------------------------------------------------------------------------------------------
				AND		(
							(
								ti.item_isForAssociation				= 'True' AND
								ti.item_ifHasItemAssociationSumPrices	= 'False'
							)
						OR
							ti.item_isForAssociation					= 'False'
						)
				-- --------------------------------------------------------------------------------------------------------------



			OPEN curItemCostList
			FETCH NEXT FROM curItemCostList INTO @intCompId,@intCoslis_Id,@intItemId
			WHILE @@FETCH_STATUS = 0
				BEGIN
					BEGIN TRY
						UPDATE tbItemCostList	WITH (ROWLOCK)
							SET
								coslis_price		= coslis_price,
								coslis_lastUpdate	= GETDATE()
							WHERE	comp_id		= @intCompId
								AND coslis_id	= @intCoslis_Id
								AND item_id		= @intItemId

						-- MOS 06-2022 x Sib para q x las dudas recalcule precios de combos, etc.
						UPDATE tbitem
							SET item_lastUpdate_byProcess = GETDATE()
							WHERE	comp_id = @intCompId AND
									item_id = @intItemId

					END TRY
					BEGIN CATCH
						DECLARE @ErrorMessage NVARCHAR(4000);
						DECLARE @ErrorSeverity INT;
						DECLARE @ErrorState INT;
						SELECT
							@ErrorMessage	= ERROR_MESSAGE(),
							@ErrorSeverity	= ERROR_SEVERITY(),
							@ErrorState		= ERROR_STATE();
							DECLARE @strError AS NVARCHAR(MAX)
							SELECT  @ErrorMessage =  @ErrorMessage + '<br/> <br/> Error on Item ID:' + CONVERT( NVARCHAR(20), @intItemId)
						    RAISERROR (@ErrorMessage, -- Message text.
									   @ErrorSeverity, -- Severity.
									   @ErrorState -- State.
									   );
							RETURN
					END CATCH
					FETCH NEXT FROM curItemCostList INTO @intCompId,@intCoslis_Id,@intItemId
				END
			CLOSE		curItemCostList
			DEALLOCATE	curItemCostList


END
GO







CREATE PROCEDURE [dbo].[spItem_funValidateParenthood]
(
	@comp_id		INT,
	@item_id		INT,
	@return_value	INT OUTPUT
)
AS

begin

	SET NOCOUNT ON

-- -----------------------------------------------
-- Testing
-- -----------------------------------------------
/*
	DECLARE
		@comp_id		INT,
		@item_id		INT,
		@return_value	INT
	SELECT
		@comp_id	= 1,
		@item_id	= 4736
*/
-- -----------------------------------------------


	IF EXISTS (SELECT 1
			   FROM  tbItemSizeColorRelation tiscr		WITH (NOLOCK)
			   where tiscr.comp_id = @comp_id
			   and tiscr.item_id = @item_id)
		or

		not exists (SELECT 1
					FROM  tbItemSizeColorRelation tiscr	WITH (NOLOCK)
					where tiscr.comp_id = @comp_id
					and tiscr.item_id_child = @item_id)

		SET @return_value = 1

	ELSE

		SET @return_value = 0
end
GO



CREATE PROCEDURE [dbo].[spItem_GenericGetCombo4PCConfig]
(
	@comp_id								INT,
	@pcConfigType							INT,
	@stor_id								INT
)
AS

	SET NOCOUNT ON
		BEGIN

			--RECIBE STOR_ID QUE SOLO TRAIGA ARTICULOS QUE TENGAN
			--STOCK PARA EL DEPOSITO QUE MANDAN
			-- ----------------------------------------------------
			-- TESTING
			-- ----------------------------------------------------
			/*
				DECLARE
					@comp_id								INT,
					@pcConfigType							INT,
					@stor_id								INT

				SELECT
					@comp_id								= 1,
					@pcConfigType							= 3,
					@stor_id								= 113
			*/
			-- ----------------------------------------------------

			SELECT
				ti.item_id								[ID],
				ti.item_desc							[Desc]

			FROM tbItem									ti		WITH(NOLOCK)

				INNER JOIN tbSubCategory				tsc		WITH(NOLOCK)
					ON	tsc.comp_id		= ti.comp_id	AND
						tsc.cat_id		= ti.cat_id		AND
						tsc.subcat_id	= ti.subcat_id

			WHERE	ti.comp_id			= @comp_id		AND
					(
						@pcConfigType			= -1	OR
						tsc.subcat_pcConfigType = @pcConfigType
					)									AND
					dbo.fnGetAStock(@comp_id, @stor_id, ti.item_id,9999999999) > 0

		END
GO



CREATE PROCEDURE spItem_getAStock4ItemReplacement
(
	@comp_id	INT,
	@item_id	INT,
	@stor_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------
		-- TESTING
		-- ----------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT,
				@stor_id	INT
			SELECT
				@comp_id	= 1,
				@item_id	= 492,
