-- Solo lo usa wsBasicQuery, NO USARLO PARA NADA MAS!!!!!
CREATE PROCEDURE [dbo].[spItem_getData]
(
	@comp_id			INT
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	SET NOCOUNT ON

	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*
	DECLARE @comp_id			INT
	SELECT 	@comp_id			=1
	*/
	-- ----------------------------------------------------------------



	SELECT	ti.item_id,
			ti.bra_id,
			ti.item_code,
			ti.item_desc,
			ti.item_detail,
      		ti.item_vendorCode,
      		ti.cat_id,
      		ti.subcat_id,
      		ti.brand_id,
      		ti.pres_id,
      		ti.curr_id,
      		ti.item_upb,
      		ti.item_upp,
      		ti.item_cantMin,
      		ti.item_cantOpt,
      		ti.item_mult,
      		ti.item_commission,
      		ti.item_picture,
      		ti.item_guarantee,
      		ti.item_expser,
      		ti.item_made,
      		isnull(ti.item_web,'false')										[item_web],
      		ti.item_annotation,
      		ti.item_annotation1,
      		ti.item_annotation2,
      		ti.acc_count_id,
      		isnull(ti.item_newness,'false')									[item_newness],
      		isnull(ti.item_liquidation,'false')								[item_liquidation],
      		ti.item_withDecimal,
      		ti.byor_id,
      		ti.supp_id,
      		ti.item_qtyMin1,
      		ti.item_qtyMin2,
      		ti.item_qtyMin3,
      		ti.item_markup_1,
      		ti.item_markup_2,
      		ti.item_markup_3,
      		ti.item_markup_4,
      		ti.item_markup_5,
      		ti.item_markup_6,
      		ti.item_markup_7,
      		ti.item_markup_8,
      		ti.item_isForAssociation,
      		ti.item_isForAssociation_canEditGroup,
      		ti.item_trigger_tax_id,
      		ti.item_weight,
      		ti.item_volume,
      		ti.item_not4Sale,
      		ti.item_cd,
      		ti.pf_id,
      		ti.item_disabled,
      		ti.item_commission_byReceive,
      		ti.item_disabledInPriceList,
      		ti.item_recentlyPurchased,
      		ti.item_disabledInBalance,
      		ti.mu_id,
      		dbo.fnGetAStock(ti.comp_id,-1,ti.item_id, 9999999999)			[stock],
      		isnull(convert(varchar,vitooit.tax_id), '')						[tax_id],
      		CASE
      			WHEN dbo.fnGetAStock(ti.comp_id,-1,ti.item_id, 9999999999)	> 0 THEN 2
      			WHEN dbo.fnGetStock4AllStorages(ti.comp_id,-1,ti.item_id)	> 0 THEN 1
      			ELSE 0
      		END																[option_id],
      		ttn.tax_percentage,
      		isnull(convert(varchar,vitooit2.tax_id), '')					[tax_id_II],
      		IsNull(ttn2.tax_percentage,0)									[tax_percentage_II],

      		convert(bit,CASE WHEN ti.item_picture IS NULL THEN 'false'
      				ELSE 'true' END) 										[imageExisting],
      		ti.subcataux_id,
      		ti.item_markup_9,
      		ti.item_markup_10,
      		ti.item_markup_11,
      		ti.item_markup_12,
      		ti.item_markup_13,
      		ti.item_markup_14,
      		ti.item_markup_15,
      		ti.item_markup_16   ,
      		ti.item_WebSite_desc,
      		ti.item_higth,
      		ti.item_wide,
      		ti.item_large


	FROM	tbItem									ti						WITH (NOLOCK)

			INNER JOIN tbCategory tc
				ON	tc.comp_id	= ti.comp_id AND
					tc.cat_id	= ti.cat_id
			INNER JOIN tbSubCategory tsc									WITH (NOLOCK)
				ON  tsc.comp_id		= ti.comp_id AND
					tsc.cat_id		= ti.cat_id  AND
					tsc.subcat_id   = ti.subcat_id

			LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit					WITH (NOLOCK)
			ON	vitooit.comp_id		= ti.comp_id
			AND vitooit.item_id		= ti.item_id

			LEFT JOIN tbTaxName						ttn						WITH (NOLOCK)
			ON	ttn.comp_id			= ti.comp_id
			AND ttn.tax_id			= vitooit.tax_id

			LEFT JOIN vwItemTaxesOnlyOneInternalTax vitooit2				WITH (NOLOCK)
			ON	vitooit2.comp_id	= ti.comp_id
			AND vitooit2.item_id	= ti.item_id

			LEFT JOIN tbTaxName						ttn2					WITH (NOLOCK)
			ON	ttn2.comp_id		= ti.comp_id
			AND ttn2.tax_id			= vitooit2.tax_id

	WHERE	ti.comp_id		= @comp_id						AND
			tc.cat_web		= 'True'						AND
			tsc.subcat_web	= 'True'						AND
			ti.item_web		= 'true'						AND
			isnull(ti.item_disabled,'false')	= 'false'

END

GO

CREATE PROCEDURE [dbo].[spItem_getData_ShortVersion]
(
	@comp_id	INT
)
AS
	BEGIN

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------

		SET NOCOUNT ON

		SELECT
			ti.item_id,
			ti.item_code,
			ti.item_desc,
			ti.cat_id,
			ti.subcat_id,
			ti.subcataux_id,
			ti.brand_id,
			ti.item_annotation,
			ti.item_annotation1,
			ti.item_weight,
			ti.item_volume,
			ti.item_wide,
			ti.item_large,
			ti.item_higth,
			ti.item_higth,
			ti.item_large,
			ti.item_web
			FROM tbItem AS ti
			INNER JOIN tbCategory									tc			WITH (NOLOCK)
					ON	tc.comp_id	= ti.comp_id					AND
						tc.cat_id	= ti.cat_id
			INNER JOIN tbSubCategory								tsc			WITH (NOLOCK)
				ON  tsc.comp_id		= ti.comp_id					AND
					tsc.cat_id		= ti.cat_id						AND
					tsc.subcat_id   = ti.subcat_id
			WHERE	ti.comp_id		= @comp_id						AND
					tc.cat_web		= 'True'						AND
					tsc.subcat_web	= 'True'						AND
					ti.item_web		= 'true'						AND
					isnull(ti.item_disabled,'false')	= 'false'
	END
GO

