					LEFT JOIN tbTaxName						ttn2		WITH(NOLOCK)
						ON	ttn2.comp_id		= ti.comp_id	AND
							ttn2.tax_id			= vitooit2.tax_id
					INNER JOIN tbBrand						tb			WITH(NOLOCK)
						ON	tb.comp_id			= ti.comp_id	AND
							tb.brand_id			= ti.brand_id
					WHERE	ti.comp_id							= @comp_id	AND
							ISNULL(ti.item_disabled,'False')	= 'False'

					RETURN
			END


		--SINO PAGINO Y DEVUELVO LOS DATOS
		BEGIN
			WITH tbPagedItems
				AS (
					SELECT
						ti.item_id,
						ti.bra_id,
						ti.item_code,
						ti.item_desc,
						ti.item_detail,
      					ti.item_vendorCode,
      					ti.cat_id,
      					ti.subcat_id,
      					ti.brand_id,
      					ti.pres_id,
      					ti.curr_id,
      					ti.item_upb,
      					ti.item_upp,
      					ti.item_cantMin,
      					ti.item_cantOpt,
      					ti.item_mult,
      					ti.item_commission,
      					ti.item_picture,
      					ti.item_guarantee,
      					ti.item_expser,
      					ti.item_made,
      					ISNULL(ti.item_web,'False')										[item_web],
      					ti.item_annotation,
      					ISNULL(ti.item_annotation1,'')									[WebSite_Copete],
      					ISNULL(ti.item_annotation2,'')									[WebSite_ShortDescription],
      					ti.acc_count_id,
      					ISNULL(ti.item_newness,'False')									[item_newness],
      					ISNULL(ti.item_liquidation,'False')								[item_liquidation],
      					ti.item_withDecimal,
      					ti.byor_id,
      					ti.supp_id,
      					ti.item_qtyMin1,
      					ti.item_qtyMin2,
      					ti.item_qtyMin3,
      					ti.item_markup_1,
      					ti.item_markup_2,
      					ti.item_markup_3,
      					ti.item_markup_4,
      					ti.item_markup_5,
      					ti.item_markup_6,
      					ti.item_markup_7,
      					ti.item_markup_8,
      					ti.item_isForAssociation,
      					ti.item_isForAssociation_canEditGroup,
      					ti.item_trigger_tax_id,
      					ti.item_weight,
      					ti.item_volume,
      					ti.item_not4Sale,
      					ti.item_cd,
      					ti.pf_id,
      					ti.item_disabled,
      					ti.item_commission_byReceive,
      					ti.item_disabledInPriceList,
      					ti.item_recentlyPurchased,
      					ti.item_disabledInBalance,
      					ti.mu_id,
      					dbo.fnGetAStock4MaxAssociation(ti.comp_id, @intStor_ID, ti.item_id,9999999999)	[stock],
      					--dbo.fnGetAStock(ti.comp_id,-1,ti.item_id, 9999999999)			[stock],
      					ISNULL(CONVERT(VARCHAR,vitooit.tax_id), '')						[tax_id],
      					--CASE
      					--	WHEN dbo.fnGetAStock(ti.comp_id,-1,ti.item_id, 9999999999)	> 0 THEN 2
      					--	WHEN dbo.fnGetStock4AllStorages(ti.comp_id,-1,ti.item_id)	> 0 THEN 1
      					--	ELSE 0
      					--END																[option_id],
      					ttn.tax_percentage,
      					ISNULL(CONVERT(VARCHAR,vitooit2.tax_id), '')					[tax_id_II],
      					ISNULL(ttn2.tax_percentage,0)									[tax_percentage_II],

      					CONVERT(BIT,CASE WHEN ti.item_picture IS NULL THEN 'False'
      							ELSE 'True' END) 										[imageExisting],
      					ti.subcataux_id,
      					ti.item_markup_9,
      					ti.item_markup_10,
      					ti.item_markup_11,
      					ti.item_markup_12,
      					ti.item_markup_13,
      					ti.item_markup_14,
      					ti.item_markup_15,
      					ti.item_markup_16   ,
      					ISNULL(ti.item_WebSite_desc,'')									[WebSite_Description],
      					ti.item_higth,
      					ti.item_wide,
      					ti.item_large,
      					tc.cat_desc,
      					tsc.subcat_desc,
      					tb.brand_desc,
      					Row_number() OVER(ORDER BY ti.item_id)							[rownum]
						FROM	tbItem								ti			WITH(NOLOCK)
							INNER JOIN tbCategory					tc			WITH(NOLOCK)
							ON	tc.comp_id			= ti.comp_id	AND
								tc.cat_id			= ti.cat_id
							INNER JOIN tbSubCategory				tsc			WITH(NOLOCK)
							ON  tsc.comp_id			= ti.comp_id	AND
								tsc.cat_id			= ti.cat_id		AND
								tsc.subcat_id		= ti.subcat_id
							LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit		WITH(NOLOCK)
							ON	vitooit.comp_id		= ti.comp_id	AND
								vitooit.item_id		= ti.item_id
							LEFT JOIN tbTaxName						ttn			WITH(NOLOCK)
							ON	ttn.comp_id			= ti.comp_id	AND
								ttn.tax_id			= vitooit.tax_id
							LEFT JOIN vwItemTaxesOnlyOneInternalTax vitooit2	WITH(NOLOCK)
							ON	vitooit2.comp_id	= ti.comp_id	AND
								vitooit2.item_id	= ti.item_id
							LEFT JOIN tbTaxName						ttn2		WITH(NOLOCK)
							ON	ttn2.comp_id		= ti.comp_id	AND
								ttn2.tax_id			= vitooit2.tax_id
							INNER JOIN tbBrand						tb			WITH(NOLOCK)
							ON	tb.comp_id			= ti.comp_id	AND
								tb.brand_id			= ti.brand_id
						WHERE	ti.comp_id							= @comp_id	AND
								tc.cat_web							= 'True'	AND
								tsc.subcat_web						= 'True'	AND
								ti.item_web							= 'True'	AND
								--tc.cat_isAvailable4FullJaus			= 'True'	AND
								--tsc.subcat_isAvailable4FullJaus		= 'True'	AND
								--ti.item_isAvailable4FullJaus		= 'True'	AND
								ISNULL(ti.item_disabled,'False')	= 'False')

					SELECT
						*
						FROM   tbPagedItems
						WHERE  rownum BETWEEN ( @PageNumber - 1 ) * @PageSize + 1 AND
						@PageNumber * @PageSize
		END
	END
GO







CREATE PROCEDURE [dbo].[spItem_getData4SEO]
(
	@comp_id		INT,
	@ws_id			INT,
	@item_id		INT
)
AS

SET NOCOUNT ON

BEGIN


	-- ----------------------------------------------------------------
	-- parámetros
	-- ----------------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@ws_id		INT,
			@item_id	INT
	SELECT	@comp_id	=1,
			@ws_id		=22,
			@item_id	= 220
	*/
	-- ----------------------------------------------------------------


	DECLARE @ws_seo_title			nvarchar(500),
			@ws_seo_keywords		nvarchar(4000),
			@ws_seo_description		nvarchar(4000),
			@ws_seo_footer			nvarchar(500),
			@ws_seo_comp_desc		nvarchar(500),
			@item_desc				nvarchar(100),
			@item_annotation		nvarchar(4000),
			@item_WebSite_desc		nvarchar(100),
			@item_SEO4PAGE			varchar(200),
			@cat_desc				nvarchar(50),
			@cat_WebSite_desc		nvarchar(50),
			@subcat_desc			varchar(100),
			@subcat_WebSite_desc	nvarchar(50),
			@brand_desc				nvarchar(200)



	SELECT	@ws_seo_title		= isnull(twsn.ws_seo_title,'') ,
			@ws_seo_keywords	= isnull(twsn.ws_seo_keywords,'') ,
			@ws_seo_description = isnull(twsn.ws_seo_description,'') ,
			@ws_seo_footer		= isnull(twsn.ws_seo_footer,'') ,
			@ws_seo_comp_desc	= isnull(twsn.ws_seo_comp_desc,'')
	FROM	tbWebSite_Names twsn		WITH (NOLOCK)
	WHERE	twsn.comp_id	= @comp_id
	AND		twsn.ws_id		= @ws_id



	SELECT	@item_desc				= isnull(ti.item_desc,''),
			@item_annotation		= isnull(ti.item_annotation,''),
			@item_WebSite_desc		= isnull(ti.item_WebSite_desc,''),
			@item_SEO4PAGE			= isnull(ti.item_SEO4PAGE,''),
			@cat_desc				= isnull(tc.cat_desc,''),
			@cat_WebSite_desc		= isnull(tc.cat_WebSite_desc,''),
			@subcat_desc			= isnull(tsc.subcat_desc,''),
			@subcat_WebSite_desc	= isnull(tsc.subcat_WebSite_desc,''),
			@brand_desc				= isnull(tb.brand_desc,'')
	FROM	tbItem ti						WITH (NOLOCK)
			LEFT JOIN tbCategory tc			WITH (NOLOCK)
			ON tc.comp_id = ti.comp_id AND tc.cat_id = ti.cat_id
			LEFT JOIN tbSubCategory tsc		WITH (NOLOCK)
			ON tsc.comp_id = ti.comp_id AND tsc.cat_id = ti.cat_id AND tsc.subcat_id = ti.subcat_id
			LEFT JOIN tbBrand tb			WITH (NOLOCK)
			ON tb.brand_id = ti.brand_id AND tb.comp_id = ti.comp_id

	WHERE	ti.comp_id = @comp_id
	AND		ti.item_id = @item_id


	--SELECT  @ws_seo_title,
	--        @ws_seo_keywords,
	--        @ws_seo_description,
	--        @ws_seo_footer,
	--        @ws_seo_comp_desc,
	--		@item_desc,
	--		@item_annotation,
	--		@item_WebSite_desc,
	--		@cat_desc,
	--		@cat_WebSite_desc,
	--		@subcat_desc,
	--		@subcat_WebSite_desc,
	--		@brand_desc


	SELECT	CASE	WHEN LEN(@item_WebSite_desc) > 0 THEN @item_WebSite_desc
					ELSE  @item_desc
			END 				+ ' - ' +
			@brand_desc															[item_title],

			CASE	WHEN LEN(@item_WebSite_desc) > 0 THEN @item_WebSite_desc
					ELSE  @item_desc
			END 				+ ' - ' +
			@item_annotation	+ ' - ' +
			@ws_seo_comp_desc													[item_description],

			CASE	WHEN LEN(@item_SEO4PAGE) > 0 THEN @item_SEO4PAGE
					ELSE	CASE	WHEN LEN(@item_WebSite_desc) > 0 THEN @item_WebSite_desc
									ELSE  @item_desc
							END 				+ ' - ' +
							@item_annotation	+ ' - ' +
							@ws_seo_comp_desc	+ ' - ' +
							CASE	WHEN LEN(@cat_WebSite_desc) > 0 THEN @cat_WebSite_desc
									ELSE @cat_desc
							END	+ ' - ' +
							CASE	WHEN LEN(@subcat_WebSite_desc) > 0 THEN @subcat_WebSite_desc
									ELSE @subcat_desc
							END	+ ' - ' +
							@brand_desc
			END																	[item_keywords]



END
GO






-- Solo lo usa wsBasicQuery, NO USARLO PARA NADA MAS!!!!!
CREATE PROCEDURE [dbo].[spItem_getData4StorageGroup]
(
	@comp_id			INT,
	@stor_id			INT
)
AS

BEGIN

	SET NOCOUNT ON

	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*
	DECLARE @comp_id			INT
	SELECT 	@comp_id			=1
	*/
	-- ----------------------------------------------------------------
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SELECT	ti.item_id,
			ti.bra_id,
			ti.item_code,
			ti.item_desc,
			ti.item_detail,
      		ti.item_vendorCode,
      		ti.cat_id,
      		ti.subcat_id,
      		ti.brand_id,
      		ti.pres_id,
      		ti.curr_id,
      		ti.item_upb,
      		ti.item_upp,
      		ti.item_cantMin,
      		ti.item_cantOpt,
      		ti.item_mult,
      		ti.item_commission,
      		ti.item_picture,
      		ti.item_guarantee,
      		ti.item_expser,
      		ti.item_made,
      		isnull(ti.item_web,'false')										[item_web],
      		ti.item_annotation,
      		ti.item_annotation1,
      		ti.item_annotation2,
      		ti.acc_count_id,
      		isnull(ti.item_newness,'false')									[item_newness],
      		isnull(ti.item_liquidation,'false')								[item_liquidation],
      		ti.item_withDecimal,
      		ti.byor_id,
      		ti.supp_id,
      		ti.item_qtyMin1,
      		ti.item_qtyMin2,
      		ti.item_qtyMin3,
      		ti.item_markup_1,
      		ti.item_markup_2,
      		ti.item_markup_3,
      		ti.item_markup_4,
      		ti.item_markup_5,
      		ti.item_markup_6,
      		ti.item_markup_7,
      		ti.item_markup_8,
      		ti.item_markup_9,
      		ti.item_markup_10,
      		ti.item_markup_11,
      		ti.item_markup_12,
      		ti.item_markup_13,
      		ti.item_markup_14,
      		ti.item_markup_15,
      		ti.item_markup_16,
      		ti.item_isForAssociation,
      		ti.item_isForAssociation_canEditGroup,
      		ti.item_trigger_tax_id,
      		ti.item_weight,
      		ti.item_volume,
      		ti.item_not4Sale,
      		ti.item_cd,
      		ti.pf_id,
      		ti.item_disabled,
      		ti.item_commission_byReceive,
      		ti.item_disabledInPriceList,
      		ti.item_recentlyPurchased,
      		ti.item_disabledInBalance,
      		ti.mu_id,
      		dbo.fnGetAStock(ti.comp_id,@stor_id,ti.item_id, 9999999999)			[stock],
      		dbo.fnGetStockOfStorageGroup(ti.comp_id,@stor_id,ti.item_id) 		[PhisicalStock],
      		isnull(convert(varchar,vitooit.tax_id), '')						[tax_id],
      		CASE
      			WHEN dbo.fnGetAStock(ti.comp_id,-1,ti.item_id, 9999999999)	> 0 THEN 2
      			WHEN dbo.fnGetStock4AllStorages(ti.comp_id,-1,ti.item_id)	> 0 THEN 1
      			ELSE 0
      		END																[option_id],
      		ttn.tax_percentage,
      		isnull(convert(varchar,vitooit2.tax_id), '')					[tax_id_II],
      		IsNull(ttn2.tax_percentage,0)									[tax_percentage_II],

      		convert(bit,CASE WHEN ti.item_picture IS NULL THEN 'false'
      				ELSE 'true' END) 										[imageExisting],
      		ti.subcataux_id,
      		ISNULL(ti.item_WebSite_desc,'')									[item_WebSite_desc],
      		ti.item_wide,
      		ti.item_large,
      		ti.item_higth


	FROM	tbItem									ti		WITH (NOLOCK)

			INNER JOIN tbCategory tc						WITH (NOLOCK)
				ON	tc.comp_id	= ti.comp_id AND
					tc.cat_id	= ti.cat_id
			INNER JOIN tbSubCategory tsc					WITH (NOLOCK)
				ON  tsc.comp_id		= ti.comp_id AND
					tsc.cat_id		= ti.cat_id  AND
					tsc.subcat_id   = ti.subcat_id

			LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit	WITH (NOLOCK)
			ON	vitooit.comp_id		= ti.comp_id
			AND vitooit.item_id		= ti.item_id

			LEFT JOIN tbTaxName						ttn		WITH (NOLOCK)
			ON	ttn.comp_id			= ti.comp_id
			AND ttn.tax_id			= vitooit.tax_id

			LEFT JOIN vwItemTaxesOnlyOneInternalTax vitooit2	WITH (NOLOCK)
			ON	vitooit2.comp_id	= ti.comp_id
			AND vitooit2.item_id	= ti.item_id

			LEFT JOIN tbTaxName						ttn2		WITH (NOLOCK)
			ON	ttn2.comp_id		= ti.comp_id
			AND ttn2.tax_id			= vitooit2.tax_id

	WHERE	ti.comp_id		= @comp_id						AND
			tc.cat_web		= 'True'						AND
			tsc.subcat_web	= 'True'						AND
			ti.item_web		= 'true'						AND
			isnull(ti.item_disabled,'false')	= 'false'

END

GO





-- ---------
-- ATENCIÓN: Si se agrega un campo para ser usado en el control de Seleccion tambien agregarlo en el SP:spItem_getDataByCode
-- ---------


CREATE PROCEDURE [dbo].[spItem_getData4WUCSelection]
(
	@comp_id		INT,
	@Item_id		INT
)
AS

SET NOCOUNT ON

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- ----------------------------------------------------------------
	-- parámetros
	-- ----------------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@item_id	INT
	SELECT	@comp_id	=1,
			@item_id	= 220
	*/
	-- ----------------------------------------------------------------


	SELECT * ,
			''			[code_in],
			0			[case_select],
			1			[foundType]
		FROM tbitem		WITH (NOLOCK)
		WHERE	comp_id = @comp_id AND
				item_id = @item_id



END
GO



-- foundType
-- 1: Busqueda normal
-- 2: # Serie de Sistema Anterior
-- 3: Busqueda por Descripcion, no se pone aca. va en la clase
-- 5: Busqueda por Codigo
-- 7: Busqueda por EAN Adicional
-- intDUNQty: Si es por EAN es la cantidad a multiplicar por si es DUN

-- ---------
-- ATENCIÓN: Si se agrega un campo para ser usado en el control de Seleccion tambien agregarlo en el SP:spItem_getData4WUCSelection
-- ---------



CREATE  PROCEDURE [dbo].[spItem_getDataByCode]
(
	@comp_id		INT,
	@bra_id			INT,
	@item_code		VARCHAR(50),
	@option			INT
)
AS



BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------
	/*
		--el parámetro @option indica si se deben recuperar o no, artículos	relacionados a size/color
		--@option = 0 - sólo artículos POSIBLES PADRES E HIJOS	- item_id not in tbItemSizeColor.item_id -wfmItemSizeColor
		--@option = 1 - sólo artículos PADRES Y POSIBLES PADRES - item_id not in tbItemSizeColor.item_id_child -wfmSaleOrderDetailSizeColor
		--@option = 2 - sólo artículos PADRES					- item_id     in tbItemSizeColor.item_id -las demás páginas
		--@option = 3 - todos los artículos
		DECLARE @comp_id		INT,
				@item_code		NVARCHAR(50),
				@option			INT,
				@bra_id			INT
		SELECT 	@comp_id		=1,
				@item_code		='D1 DESHAB',
				@option			= 10,
				@bra_id			= 1
	*/
	-- ------------------------------------------------------------



	-- Tomo los Grupos de Sucursales a los que pertenece esta sucursal
	DECLARE @tmpBranchsOfBranchGroup TABLE(brag_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchsOfBranchGroup(brag_id)
		SELECT brag_id
			FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
			WHERE	tbgd.comp_id	= @comp_id AND
					tbgd.bra_id		= @bra_id



	DECLARE @comp_enableItemSearchByID				AS BIT
	DECLARE @comp_quitLeftCerofromCode2SearchItem	AS BIT
	SET		@comp_enableItemSearchByID				= 'True'
	SELECT  @comp_enableItemSearchByID				= ISNULL(tb.comp_enableItemSearchByID,'True'),
			@comp_quitLeftCerofromCode2SearchItem	= ISNULL(tb.comp_quitLeftCerofromCode2SearchItem,'False')
		FROM tbCompany tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.comp_id	= @comp_id


	DECLARE @intItemId AS INT
	DECLARE @strItemId AS NVARCHAR(50)
	SET		@intItemId = -1
	DECLARE @bitHASGBPFSI AS BIT
	SET		@bitHASGBPFSI = 'False'
	IF @item_code LIKE '%*GBPSI*%'
		BEGIN
			SET @strItemId = REPLACE(@item_code, '*GBPSI*','')
			SET @item_code = REPLACE(@item_code, '*GBPSI*','')
			SET @intItemId = CONVERT(INT,@strItemId)
			SET		@bitHASGBPFSI = 'True'
		END

	-- Intenta obtener el id como un numero
	DECLARE @item_CodeNoZero AS INT
	SET @item_CodeNoZero = -1
	IF ISNUMERIC(@item_code) = '1'
	BEGIN

		BEGIN TRY
			SET @item_CodeNoZero = CONVERT(INT,@item_Code)
		END TRY
		BEGIN CATCH
			SET @item_CodeNoZero = -1
		END CATCH

	END




	-- -------------------------------------------------------------------------
	-- 1ro se fija si lo puede encontrar rapidamente y no forrear por toda la BD
	-- -------------------------------------------------------------------------
	DECLARE @bitFoundByFastMode AS BIT
	SET		@bitFoundByFastMode = 'False'
	DECLARE @tmpItemByCODEOrEAN TABLE(item_id INT PRIMARY KEY, foundType INT,intDUNQty INT)
	IF @bitHASGBPFSI = 'False'
		BEGIN
			DECLARE @strCode2Search AS NVARCHAR(50)
			SET		@strCode2Search = @item_code
			IF @comp_quitLeftCerofromCode2SearchItem = 'True'
				BEGIN
					IF ISNUMERIC(@strCode2Search) = 1
						BEGIN
							SET @strCode2Search = dbo.fnStrAllTrim( CONVERT(nvarchar(50),CONVERT(DECIMAL(20,0),@strCode2Search)) )
						END
				END

			INSERT INTO @tmpItemByCODEOrEAN(item_id, foundType, intDUNQty)
				SELECT TOP 1
					ti.item_id,
					CASE
						WHEN tie.comp_id IS NULL THEN 5  -- Encontrado por Codigo
						ELSE						  7  -- Encontrado por EAN
					END,
					CASE
						WHEN tie.comp_id IS NULL								THEN 1
						WHEN ti.item_code = @strCode2Search						THEN 1
						WHEN tie.comp_id IS NOT NULL AND tie.ie_isDUC = 'True'	THEN ISNULL(tie.ie_DUNQty,1)
						ELSE 1
					END									-- DUN QTY
					FROM tbItem ti					WITH (NOLOCK)
					LEFT JOIN tbItemEAN tie			WITH (NOLOCK)
					ON	tie.comp_id = ti.comp_id AND
						tie.item_id = ti.item_id
					WHERE ti.comp_id = @comp_id AND
						( ti.item_code = @strCode2Search /*@item_code*/ OR tie.ie_ean = @strCode2Search/*@item_code*/)	AND
						  ti.item_disabled = 'False'

			IF @@ROWCOUNT > 0 SET @bitFoundByFastMode = 'True'
		END
	-- -------------------------------------------------------------------------




	-- -----------------------------------------------------------------------------------------
	-- ATENCION
	-- Si se modifica algo de este select hay que clonarlo SIEMPRE en la marca **1 mas abajo!!!
	-- -----------------------------------------------------------------------------------------
	-- POne en una tabla si encuentra el serial ya que lo buscaba 300 veces
	DECLARE		@tblItemSerials AS TABLE(is_id  INT,is_serial NVARCHAR(50),item_id INT,is_available BIT		)
	INSERT INTO @tblItemSerials SELECT tis.is_id  ,tis.is_serial,tis.item_id,tis.is_available
									FROM	tbItemSerials tis	WITH (NOLOCK)
									WHERE	tis.comp_id		= @comp_id AND
											tis.is_serial	= @item_code



--==
--SELECT @bitFoundByFastMode,'@tblItemSerials',* FROM @tblItemSerials

	-- Busqueda Rapida
	-- ATENCION: Si se toca algo aca tambien hacerlo mas abajo !!!
	IF @bitFoundByFastMode = 'True'
		BEGIN



			SELECT 	TOP 1

					ti.comp_id,
					ti.bra_id,
					ti.item_code,
					ti.item_id,
					ti.item_desc,
					ti.item_detail,
					ti.item_vendorCode,
					ti.cat_id,
					ti.subcat_id,
					ti.brand_id,
					ti.pres_id,
					ti.curr_id,
					ti.item_upb,
					ti.item_upp,
					ti.item_cantMin,
					ti.item_cantOpt,
					ti.item_mult,
					ti.item_commission,
					ti.item_picture,
					ti.item_guarantee,
					ISNULL(ti.item_expser,'False')				[item_expser],
					ISNULL(ti.item_expean,'False')				[item_expean],
					ti.item_made,
					ti.item_web,
					ti.item_annotation,
					ti.acc_count_id,
					ti.item_newness,
					ti.item_liquidation,

					@item_code														[code_in],
					CASE
						WHEN ti.item_code =  @item_code																							THEN 1
						WHEN ti.item_id IN (SELECT tie.item_id
												FROM tbItemEAN tie
												WHERE	tie.comp_id = ti.comp_id AND
														tie.item_id = ti.item_id AND
														tie.ie_ean	= @item_code)																THEN 5
						WHEN ti.item_code <> @item_code AND ti.item_vendorCode =  @item_code													THEN 4
						WHEN ti.item_code <> @item_code AND ti.item_vendorCode <> @item_code AND ti.item_codeAlternative =  @item_code			THEN 2
						WHEN /*ti.item_code <> @item_code AND ti.item_vendorCode <> @item_code AND ti.item_codeAlternative <> @item_code AND  */
							 ti.item_id IN (SELECT tis.item_id FROM @tblItemSerials tis WHERE tis.is_serial = @item_code)
																																				THEN 3
					END		[case_select],

					CASE
						WHEN ti.item_code =  @item_code														THEN 0
						WHEN ti.item_code <> @item_code AND ti.item_vendorCode		=  @item_code			THEN 0
						WHEN ti.item_code <> @item_code AND ti.item_vendorCode		<> @item_code	AND ti.item_codeAlternative =  @item_code
																											THEN 0
						WHEN --ti.item_code <> @item_code AND ti.item_vendorCode		<> @item_code	AND ti.item_codeAlternative <> @item_code AND
							 ti.item_id IN (SELECT tis.item_id FROM @tblItemSerials tis WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code)
				 																							THEN
							(SELECT tis.is_id  FROM @tblItemSerials tis WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code)
						ELSE NULL
					END		[is_id],
					CASE
						WHEN ti.item_code				= @item_code THEN 1
						WHEN ti.item_vendorCode			= @item_code THEN 2
						WHEN ti.item_codeAlternative	= @item_code THEN 4
						WHEN  ti.item_id IN (SELECT tis.item_id
												FROM @tblItemSerials tis
												WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code /*AND tis.is_available = 'true' MOS, 12-2011*/ )  THEN 3
						ELSE 5
					END		[xOrder],

					CASE
						WHEN exists(	SELECT TOP 1  1
											FROM @tblItemSerials tis
											WHERE	/*tis.comp_id			= @comp_id */
													tis.is_serial		= @item_code
												AND tis.item_id			= ti.item_id
												AND tis.is_available	= 'true' )   THEN 'True'
						ELSE 'False'
					END		[bitSerialAvailable],

					CASE
						WHEN exists(	SELECT TOP  1 1
											FROM @tblItemSerials tis
											INNER JOIN tbTempItemStock ttis WITH (NOLOCK)
												ON ttis.is_id = tis.is_id
											WHERE	/*tis.comp_id			= @comp_id */
													tis.is_serial		= @item_code
												AND tis.item_id			= ti.item_id
												AND tis.is_id			= ttis.is_id)
									OR
							 EXISTS(			SELECT TOP 1  1
													FROM tbSaleOrderSerials tsos WITH (NOLOCK)
													INNER JOIN @tblItemSerials tis
														ON		/*tis.comp_id		= @comp_id */
																tis.is_serial	= @item_code
															AND tis.item_id		= ti.item_id
													WHERE		tsos.comp_id = @comp_id
															AND tsos.is_id = tis.is_id
								   )
												 THEN 'True'
						ELSE 'False'
					END		[bitSerialInTempItemStock],
					tmp.foundType,
					tmp.intDUNQty,
					ti.item_disabled


				FROM 	dbo.tbItem ti WITH (NOLOCK)

				INNER JOIN @tmpItemByCODEOrEAN  tmp
					ON tmp.item_id = ti.item_id

			RETURN

		END



	-- Comienza a buscar por lo que encuentre . . .



	DECLARE @bolIsCodeAlternative AS BIT
	SET		@bolIsCodeAlternative = 'False'
	IF EXISTS(	SELECT TOP 1 1
					FROM tbItem_codeAlternative	WITH (NOLOCK)
	          		WHERE comp_id = @comp_id)
		BEGIN
			SET @bolIsCodeAlternative = 'True'
		END









	-- Busqueda Lenta
	-- ATENCION: Si se toca algo aca tambien hacerlo mas arriba !!!
	SELECT 	TOP 1

			ti.comp_id,
			ti.bra_id,
			ti.item_code,
			ti.item_id,
			ti.item_desc,
			ti.item_detail,
			ti.item_vendorCode,
			ti.cat_id,
			ti.subcat_id,
			ti.brand_id,
			ti.pres_id,
			ti.curr_id,
			ti.item_upb,
			ti.item_upp,
			ti.item_cantMin,
			ti.item_cantOpt,
			ti.item_mult,
			ti.item_commission,
			ti.item_picture,
			ti.item_guarantee,
			ISNULL(ti.item_expser,'False')				[item_expser],
			ISNULL(ti.item_expean,'False')				[item_expean],
			ti.item_made,
			ti.item_web,
			ti.item_annotation,
			ti.acc_count_id,
			ti.item_newness,
			ti.item_liquidation,

			@item_code														[code_in],
			CASE
				WHEN ti.item_code =  @item_code																							THEN 1
				WHEN ti.item_id IN (SELECT tie.item_id
										FROM tbItemEAN tie	WITH (NOLOCK)
										WHERE	tie.comp_id = ti.comp_id AND
												tie.item_id = ti.item_id AND
												tie.ie_ean	= @item_code)																THEN 5
				WHEN ti.item_code <> @item_code AND ti.item_vendorCode =  @item_code													THEN 4
				WHEN ti.item_code <> @item_code AND ti.item_vendorCode <> @item_code AND ti.item_codeAlternative =  @item_code			THEN 2
				WHEN /*ti.item_code <> @item_code AND ti.item_vendorCode <> @item_code AND ti.item_codeAlternative <> @item_code AND  */
					 ti.item_id IN (SELECT tis.item_id FROM @tblItemSerials tis WHERE tis.is_serial = @item_code)
																																		THEN 3
			END		[case_select],

			CASE
				WHEN ti.item_code =  @item_code														THEN 0
				WHEN ti.item_code <> @item_code AND ti.item_vendorCode		=  @item_code			THEN 0
				WHEN ti.item_code <> @item_code AND ti.item_vendorCode		<> @item_code	AND ti.item_codeAlternative =  @item_code
																									THEN 0
				WHEN --ti.item_code <> @item_code AND ti.item_vendorCode		<> @item_code	AND ti.item_codeAlternative <> @item_code AND
					 ti.item_id IN (SELECT tis.item_id FROM @tblItemSerials tis WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code)
				 																					THEN
					(SELECT TOP 1 tis.is_id  FROM @tblItemSerials tis WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code)
				ELSE NULL
			END		[is_id],
			CASE
				WHEN ti.item_code				= @item_code THEN 1
				WHEN ti.item_vendorCode			= @item_code THEN 2
				WHEN ti.item_codeAlternative	= @item_code THEN 4
				WHEN  ti.item_id IN (SELECT tis.item_id
										FROM @tblItemSerials tis
										WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code /*AND tis.is_available = 'true' MOS, 12-2011*/ )  THEN 3
				ELSE 5
			END		[xOrder],

			CASE
				WHEN exists(	SELECT TOP 1 1
									FROM @tblItemSerials tis
									WHERE	/*tis.comp_id			= @comp_id */
										    tis.is_serial		= @item_code
										AND tis.item_id			= ti.item_id
										AND tis.is_available	= 'true' )   THEN 'True'
				ELSE 'False'
			END		[bitSerialAvailable],

			CASE
				WHEN exists(	SELECT TOP 1 1
									FROM @tblItemSerials tis
									INNER JOIN tbTempItemStock ttis
										ON ttis.is_id = tis.is_id
									WHERE	/*tis.comp_id			= @comp_id */
										    tis.is_serial		= @item_code
										AND tis.item_id			= ti.item_id
										AND tis.is_id			= ttis.is_id)
							OR
					 EXISTS(			SELECT TOP 1 1
											FROM tbSaleOrderSerials tsos WITH (NOLOCK)
											INNER JOIN @tblItemSerials tis
												ON		/*tis.comp_id		= @comp_id */
														tis.is_serial	= @item_code
													AND tis.item_id		= ti.item_id
											WHERE		tsos.comp_id = @comp_id
													AND tsos.is_id = tis.is_id
						   )
										 THEN 'True'
				ELSE 'False'
			END		[bitSerialInTempItemStock],
			1											[foundType],
			1											[intDUNQty]	,
			ti.item_disabled

		INTO #tmpItems
		FROM 	dbo.tbItem ti			WITH (NOLOCK)

		LEFT JOIN @tmpBranchsOfBranchGroup tmp
			ON tmp.brag_id = ti.brag_id

		LEFT JOIN tbItem_codeAlternative				tica	WITH (NOLOCK)
				ON tica.comp_id = ti.comp_id and
				   tica.item_id = ti.item_id

		WHERE 	 ti.comp_id = @comp_id
		AND     (@intItemId = -1 OR (@comp_enableItemSearchByID = 'True' AND ti.item_id = @intItemId  ))	AND

		CASE
			WHEN ti.brag_id IS NOT NULL AND tmp.brag_id IS NULL THEN 0
			WHEN ti.bra_id  IS NULL								THEN 1
			WHEN ti.bra_id  = @bra_id							THEN 1
			ELSE 0
		END = 1
		--AND		(ti.bra_id  = @bra_id OR ti.bra_id IS NULL)
		AND 	(

					--selecciona artículo por código
					(ti.item_code		= @item_code)

					OR

					(ltrim(ti.item_code)= @item_code)

					OR	-- Por si hay espacios en blanco delante del codigo. Ver si no pone lento.!


					-- Busca si tiene algun EAN Asociado
					(
						NOT EXISTS (SELECT TOP 1 1
										FROM tbItem ti2		WITH (NOLOCK)
										WHERE	ti2.comp_id			= @comp_id		AND
												ti2.item_code		= @item_code
									)	AND
							EXISTS (
									SELECT TOP 1 1
										FROM tbItemEAN tie	WITH (NOLOCK)
										WHERE	tie.comp_id	= ti.comp_id AND
												tie.item_id = ti.item_id AND
												tie.ie_ean  = @item_code
									)
					)

					OR


					--si no encuentra artículo por código, lo selecciona por código de vendedor
					(NOT EXISTS (SELECT TOP 1 1
									FROM tbItem ti2	WITH (NOLOCK)
									WHERE	ti2.comp_id			= @comp_id		AND
											ti2.item_code		= @item_code
								)	AND
											ti.item_vendorCode	= @item_code
					)

					OR

					--si no encuentra artículo por código, lo selecciona por código Alternativo
					(NOT EXISTS (SELECT TOP 1 1
									FROM tbItem ti2	WITH (NOLOCK)
									WHERE	ti2.comp_id				= @comp_id AND
										   (ti2.item_code			= @item_code OR
										    ti2.item_vendorCode		= @item_code)
								) AND
											ti.item_codeAlternative = @item_code
					)

					OR


					--si no encuentra artículo por código ni por código de vendedor, lo selecciona por nro. de serie
					(NOT EXISTS (SELECT TOP 1 1
									FROM tbItem ti2 WITH (NOLOCK)
									WHERE ti2.comp_id = @comp_id AND ti2.item_code       = @item_code) AND
					 NOT EXISTS (SELECT TOP 1 1
									FROM tbItem ti3 WITH (NOLOCK)
									WHERE ti3.comp_id = @comp_id AND ti3.item_vendorCode = @item_code) AND
					 ti.item_id IN (SELECT tis.item_id
										FROM @tblItemSerials tis
										WHERE /*tis.comp_id = @comp_id AND */ tis.is_serial = @item_code /*AND tis.is_available = 'true' MOS, 12-2011*/)
					)

					OR

					(
						CASE
							WHEN @bolIsCodeAlternative = 'False'													THEN 0
							WHEN @bolIsCodeAlternative = 'True' THEN
								(CASE
								    WHEN tica.item_id IS NOT NULL and tica.item_codeAlternative	LIKE '%' + @item_code + '%' THEN 1
								    ELSE 0
								END)
							ELSE																						 0
						END = 1
					)

					OR

					-- Si no lo encuentra de ninguna de las otras maneras lo busca por item_id
					(@comp_enableItemSearchByID = 'True' AND ti.item_id = @item_CodeNoZero )

				)

		AND

				-- --------------------------------------------------------------------------------------------------------------------
				--  ATENCION, prestar atencion a lo siguiente.
				-- --------------------------------------------------------------------------------------------------------------------
				--cada vez que se actualicen alguna de estas opciones también hay que actualizarlas en [spItem_getDataByCode]
				--el parámetro @option indica si se deben recuperar o no, artículos	relacionados a size/color
				--@option = 0 - Solo Articulos sin Talle o HIJOS		->> wfmItemSizeColor
				--@option = 1 - sólo artículos sin Talle o PADRES -		->> wfmSaleOrderDetailSizeColor
				--@option = 2 - sólo artículos PADRES					- item_id     in tbItemSizeColor.item_id -las demás páginas
				--@option = -1 - todos los artículos

				CASE
					WHEN @option = 0 OR @option = 10	THEN
						(
							CASE
								WHEN NOT EXISTS(
												SELECT TOP 1 1
													FROM tbItemSizeColorRelation tiscr		WITH (NOLOCK)
													WHERE	tiscr.comp_id = ti.comp_id AND
															tiscr.item_id = ti.item_id) THEN 1
								ELSE 0
							END
						)
					WHEN @option = 1	THEN
						(
							CASE
								WHEN NOT EXISTS(
												SELECT DISTINCT isnull(tiscr.item_id_child,-1)
													FROM tbItemSizeColorRelation tiscr		WITH (NOLOCK)
													WHERE tiscr.comp_id			= ti.comp_id AND
														  tiscr.item_id_child	= ti.item_id

												) THEN 1
								ELSE 0
							END
						)
					WHEN @option = 2	THEN
						(
							CASE
								WHEN	EXISTS(
												SELECT TOP 1 1
													FROM tbItemSizeColorRelation tiscr	WITH (NOLOCK)
													WHERE	tiscr.comp_id = ti.comp_id AND
															tiscr.item_id = ti.item_id) THEN 1
								ELSE 0
							END
						)
				    WHEN @option = -1	THEN  1
				    WHEN @option = -3	THEN  1
				    WHEN @option =  3	THEN  1
					ELSE 0
				END	 = 1

				AND ti.item_disabled = 'False'


		ORDER BY [xOrder]
	-- -----------------------------------------------------------------------------------------


	-- Si encontro lo devuelve
	IF @@ROWCOUNT > 0
		BEGIN
			SELECT * FROM	#tmpItems
			DROP TABLE		#tmpItems
		END
	ELSE -- Sino se fija si es un numero de serie que vino de otro sistema anterior.
		BEGIN
			DROP TABLE		#tmpItems		-- MOS 01-2023
			DECLARE @intIsId	AS INT
			DECLARE @intStorId	AS INT
			SET @intIsId = NULL
			SELECT TOP 1	@intIsId	= tis.is_id,
							@intStorId	= ts.stor_id
				FROM tbItemSerialsFromOtherERP tisfoe		WITH (NOLOCK)

				INNER JOIN tbItemSerials tis				WITH (NOLOCK)
					ON	tis.comp_id = tisfoe.comp_id AND
						tis.item_id = tisfoe.item_id
				INNER JOIN tbItemStorage ts					WITH (NOLOCK)
					ON	ts.comp_id	= tis.comp_id AND
						ts.item_id	= tis.item_id
				WHERE	tisfoe.isfo_serial = @item_code AND
						tis.is_available = 'False'		AND
					   (tis.is_serial IS NULL  OR tis.is_serial = '') AND
					    ts.itst_cant > 0

				-- Si encontro algun N'umero de serie lo actualiza y vuelve a hacer la busqueda inicial.
				IF @intIsId IS NOT NULL AND @intStorId IS NOT NULL
					BEGIN
						UPDATE tbItemSerials
							SET
								is_serial		= @item_code,
								is_available	= 'True',
								stor_id			= @intStorId
							WHERE	comp_id = @comp_id AND
									is_id = @intIsId

					END


--==
--SELECT '@tblItemSerials',* FROM @tblItemSerials

				-- -----------------------------------------------------------------------------------------
				-- **1   Viene del clonado de el select de arriba !!!
				-- Recordar sacar aqui abajo el into #tmpItems
				-- -----------------------------------------------------------------------------------------
				INSERT INTO @tblItemSerials SELECT tis.is_id  ,tis.is_serial,tis.item_id,tis.is_available
												FROM	tbItemSerials tis	WITH (NOLOCK)
												WHERE	tis.comp_id		= @comp_id AND
														tis.is_serial	= @item_code


--==
--SELECT '@tblItemSerials2',* FROM @tblItemSerials

				-- Si se toca algo aca hacerlo tambien mas arrtiba
				SELECT 	TOP 1

						ti.comp_id,
						ti.bra_id,
						ti.item_code,
						ti.item_id,
						ti.item_desc,
						ti.item_detail,
						ti.item_vendorCode,
						ti.cat_id,
						ti.subcat_id,
						ti.brand_id,
						ti.pres_id,
						ti.curr_id,
						ti.item_upb,
