						ti.item_guarantee,
						ISNULL(ti.item_expser,'False')				[item_expser],
						ISNULL(ti.item_expean,'False')				[item_expean],
						ti.item_made,
						ti.item_web,
						ti.item_annotation,
						ti.acc_count_id,
						ti.item_newness,
						ti.item_liquidation,

						@item_code														[code_in],
						CASE
							WHEN ti.item_code =  @item_code																							THEN 1
							WHEN ti.item_code <> @item_code AND ti.item_vendorCode =  @item_code													THEN 4
							WHEN ti.item_code <> @item_code AND ti.item_vendorCode <> @item_code AND ti.item_codeAlternative =  @item_code			THEN 2
							WHEN /*ti.item_code <> @item_code AND ti.item_vendorCode <> @item_code AND ti.item_codeAlternative <> @item_code AND  */
								 ti.item_id IN (SELECT tis.item_id FROM @tblItemSerials tis WHERE tis.is_serial = @item_code)
																																					THEN 3
						END		[case_select],

						CASE
							WHEN ti.item_code =  @item_code														THEN 0
							WHEN ti.item_code <> @item_code AND ti.item_vendorCode		=  @item_code			THEN 0
							WHEN ti.item_code <> @item_code AND ti.item_vendorCode		<> @item_code	AND ti.item_codeAlternative =  @item_code
																												THEN 0
							WHEN --ti.item_code <> @item_code AND ti.item_vendorCode		<> @item_code	AND ti.item_codeAlternative <> @item_code AND
								 ti.item_id IN (SELECT tis.item_id FROM @tblItemSerials tis WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code)
	 																											THEN
								(SELECT TOP 1 tis.is_id  FROM @tblItemSerials tis WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code)
							ELSE NULL
						END		[is_id],
						CASE
							WHEN ti.item_code				= @item_code THEN 1
							WHEN ti.item_vendorCode			= @item_code THEN 2
							WHEN ti.item_codeAlternative	= @item_code THEN 4
							WHEN  ti.item_id IN (SELECT tis.item_id
													FROM @tblItemSerials tis
													WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code /*AND tis.is_available = 'true' MOS, 12-2011*/ )  THEN 3
							ELSE 5
						END		[xOrder],

						CASE
							WHEN exists(	SELECT TOP 1 1
												FROM @tblItemSerials tis
												WHERE	/*tis.comp_id			= @comp_id */
														tis.is_serial		= @item_code
													AND tis.item_id			= ti.item_id
													AND tis.is_available	= 'true' )   THEN 'True'
							ELSE 'False'
						END		[bitSerialAvailable],

						CASE
							WHEN exists(	SELECT TOP 1 1
												FROM @tblItemSerials tis
												INNER JOIN tbTempItemStock ttis	WITH (NOLOCK)
													ON ttis.is_id = tis.is_id
												WHERE	/*tis.comp_id			= @comp_id */
														tis.is_serial		= @item_code
													AND tis.item_id			= ti.item_id
													AND tis.is_id			= ttis.is_id)
										OR
								 EXISTS(			SELECT TOP 1 1
														FROM tbSaleOrderSerials tsos	WITH (NOLOCK)
														INNER JOIN @tblItemSerials tis
															ON		/*tis.comp_id		= @comp_id */
																	tis.is_serial	= @item_code
																AND tis.item_id		= ti.item_id
														WHERE		tsos.comp_id = @comp_id
																AND tsos.is_id = tis.is_id
									   )
													 THEN 'True'
							ELSE 'False'
						END		[bitSerialInTempItemStock],
						2											[foundType],
						1											[intDUNQty]	,
						ti.item_disabled

					INTO #tmpItems2
					FROM 	dbo.tbItem ti	WITH (NOLOCK)
					LEFT JOIN @tmpBranchsOfBranchGroup tmp
						ON tmp.brag_id = ti.brag_id
					LEFT JOIN tbItem_codeAlternative				tica	WITH (NOLOCK)
						ON tica.comp_id = ti.comp_id and
						   tica.item_id = ti.item_id

					WHERE 	 ti.comp_id = @comp_id
					--AND		(ti.bra_id  = @bra_id OR ti.bra_id IS NULL)
					AND		CASE
								WHEN ti.brag_id IS NOT NULL AND tmp.brag_id IS NULL THEN 0
								WHEN ti.bra_id  IS NULL								THEN 1
								WHEN ti.bra_id  = @bra_id							THEN 1
								ELSE 0
							END = 1
					AND 	(

								--selecciona artículo por código
								(ti.item_code		= @item_code) OR
								(ltrim(ti.item_code)= @item_code) OR	-- Por si hay espacios en blanco delante del codigo. Ver si no pone lento.!

								--si no encuentra artículo por código, lo selecciona por código de vendedor
								(
									NOT EXISTS (SELECT TOP 1 1
													FROM tbItem ti2	WITH (NOLOCK)
													WHERE ti2.comp_id = @comp_id AND ti2.item_code = @item_code) AND
									ti.item_vendorCode = @item_code
								) OR

								--si no encuentra artículo por código, lo selecciona por código Alternativo
								(
									NOT EXISTS (
													SELECT TOP 1 1
													FROM tbItem ti2	WITH (NOLOCK)
													WHERE ti2.comp_id = @comp_id AND (ti2.item_code = @item_code OR ti2.item_vendorCode = @item_code)
												)
										AND
									ti.item_codeAlternative = @item_code
								) OR


								--si no encuentra artículo por código ni por código de vendedor, lo selecciona por nro. de serie
								(
									NOT EXISTS (SELECT TOP 1  1 FROM tbItem ti2 WITH (NOLOCK)	WHERE ti2.comp_id = @comp_id AND ti2.item_code       = @item_code) AND
									NOT EXISTS (SELECT TOP 1  1 FROM tbItem ti3 WITH (NOLOCK)	WHERE ti3.comp_id = @comp_id AND ti3.item_vendorCode = @item_code) AND
									ti.item_id IN (SELECT tis.item_id FROM @tblItemSerials tis
												WHERE /*tis.comp_id = @comp_id AND */ tis.is_serial = @item_code /*AND tis.is_available = 'true' MOS, 12-2011*/)
								) OR
								(
									tica.item_id IS NOT NULL and tica.item_codeAlternative	LIKE '%' + @item_code + '%'
								) OR
								-- Si no lo encuentra de ninguna de las otras maneras lo busca por item_id
								(@comp_enableItemSearchByID = 'True' AND  ti.item_id = @item_CodeNoZero )


							)


				AND

		-- --------------------------------------------------------------------------------------------------------------------
		--  ATENCION, prestar atencion a lo siguiente.
		-- --------------------------------------------------------------------------------------------------------------------
		--cada vez que se actualicen alguna de estas opciones también hay que actualizarlas en [spItem_getDataByCode]
		--el parámetro @option indica si se deben recuperar o no, artículos	relacionados a size/color
		--@option = 0 - Solo Articulos sin Talle o HIJOS		->> wfmItemSizeColor
		--@option = 1 - sólo artículos sin Talle o PADRES -		->> wfmSaleOrderDetailSizeColor
		--@option = 2 - sólo artículos PADRES					- item_id     in tbItemSizeColor.item_id -las demás páginas
		--@option = -1 - todos los artículos

				CASE
					WHEN @option = 0 OR @option = 10	THEN
						(
							CASE
								WHEN NOT EXISTS(
												SELECT TOP 1 1
													FROM tbItemSizeColorRelation tiscr	WITH (NOLOCK)
													WHERE	tiscr.comp_id = ti.comp_id AND
															tiscr.item_id = ti.item_id) THEN 1
								ELSE 0
							END
						)
					WHEN @option = 1	THEN
						(
							CASE
								WHEN NOT EXISTS(
												SELECT DISTINCT isnull(tiscr.item_id_child,-1)
													FROM tbItemSizeColorRelation tiscr		WITH (NOLOCK)
													WHERE tiscr.comp_id			= ti.comp_id AND
														  tiscr.item_id_child	= ti.item_id

												) THEN 1
								ELSE 0
							END
						)
					WHEN @option = 2	THEN
						(
							CASE
								WHEN	EXISTS(
												SELECT TOP 1 1
													FROM tbItemSizeColorRelation tiscr	WITH (NOLOCK)
													WHERE	tiscr.comp_id = ti.comp_id AND
															tiscr.item_id = ti.item_id) THEN 1
								ELSE 0
							END
						)
				    WHEN @option = -1	THEN  1
				    WHEN @option = -3	THEN  1
					ELSE 0
				END	 = 1
				AND ti.item_disabled = 'False'	-- MOS 01-2023 x Latamly para que NO se pueda buscar x CODIGO

				ORDER BY [xOrder]
				-- --------------------------------------------------------------------------------------------------------------------

					----cada vez que se actualicen alguna de estas opciones también hay que actualizarlas en [spItem_getDataByCode]
					----el parámetro @option indica si se deben recuperar o no, artículos	relacionados a size/color
					----@option = 0 - sólo artículos POSIBLES PADRES E HIJOS	- item_id not in tbItemSizeColor.item_id -wfmItemSizeColor
					----@option = 1 - sólo artículos PADRES Y POSIBLES PADRES - item_id not in tbItemSizeColor.item_id_child -wfmSaleOrderDetailSizeColor
					----@option = 2 - sólo artículos PADRES					- item_id     in tbItemSizeColor.item_id -las demás páginas
					----@option = -1 - todos los artículos
					--AND		(
					--		 (@option = 0 AND ti.item_id NOT IN (SELECT DISTINCT isnull(tiscr.item_id,-1)       FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = ti.comp_id)) OR
					--		 (@option = 1 AND ti.item_id NOT IN (SELECT DISTINCT isnull(tiscr.item_id_child,-1) FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = ti.comp_id)) OR
					--		 (@option = 2 AND ti.item_id     IN (SELECT DISTINCT isnull(tiscr.item_id,-1)       FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = ti.comp_id)) OR
					--		 (@option = -1 OR @option = 3)
					--		)


				-- -----------------------------------------------------------------------------------------

			IF @@ROWCOUNT > 0
				BEGIN
					SELECT * FROM	#tmpItems2
					DROP TABLE		#tmpItems2
				END
			ELSE	-- Busca x ID en la tabla de OtherERP Directamente
				BEGIN
					DROP TABLE		#tmpItems2
					DECLARE @intItemIDPUTA AS INT
					SELECT  @intItemIDPUTA = tisfoe.item_id
						FROM tbItemSerialsFromOtherERP tisfoe			WITH (NOLOCK)
						INNER JOIN tbCompany tc							WITH (NOLOCK)
							ON tc.comp_id = @comp_id
						WHERE	tisfoe.comp_id		= @comp_id		AND
								tisfoe.isfo_serial	= @item_code	AND
								tc.comp_admitSearchDirectSerialOtherERP = 'True'	-- PUTA BUTESI

					SELECT 	TOP 1

							ti.comp_id,
							ti.bra_id,
							ti.item_code,
							ti.item_id,
							ti.item_desc,
							ti.item_detail,
							ti.item_vendorCode,
							ti.cat_id,
							ti.subcat_id,
							ti.brand_id,
							ti.pres_id,
							ti.curr_id,
							ti.item_upb,
							ti.item_upp,
							ti.item_cantMin,
							ti.item_cantOpt,
							ti.item_mult,
							ti.item_commission,
							ti.item_picture,
							ti.item_guarantee,
							ISNULL(ti.item_expser,'False')				[item_expser],
							ISNULL(ti.item_expean,'False')				[item_expean],
							ti.item_made,
							ti.item_web,
							ti.item_annotation,
							ti.acc_count_id,
							ti.item_newness,
							ti.item_liquidation,

							@item_code														[code_in],
							CASE
								WHEN ti.item_code =  @item_code																							THEN 1
								WHEN ti.item_id IN (SELECT tie.item_id
														FROM tbItemEAN tie	WITH (NOLOCK)
														WHERE	tie.comp_id = ti.comp_id AND
																tie.item_id = ti.item_id AND
																tie.ie_ean	= @item_code)																THEN 5
								WHEN ti.item_code <> @item_code AND ti.item_vendorCode =  @item_code													THEN 4
								WHEN ti.item_code <> @item_code AND ti.item_vendorCode <> @item_code AND ti.item_codeAlternative =  @item_code			THEN 2
								WHEN /*ti.item_code <> @item_code AND ti.item_vendorCode <> @item_code AND ti.item_codeAlternative <> @item_code AND  */
									 ti.item_id IN (SELECT tis.item_id FROM @tblItemSerials tis WHERE tis.is_serial = @item_code)
																																						THEN 3
								ELSE 1
							END		[case_select],

							CASE
								WHEN ti.item_code =  @item_code														THEN 0
								WHEN ti.item_code <> @item_code AND ti.item_vendorCode		=  @item_code			THEN 0
								WHEN ti.item_code <> @item_code AND ti.item_vendorCode		<> @item_code	AND ti.item_codeAlternative =  @item_code
																													THEN 0
								WHEN --ti.item_code <> @item_code AND ti.item_vendorCode		<> @item_code	AND ti.item_codeAlternative <> @item_code AND
									 ti.item_id IN (SELECT tis.item_id FROM @tblItemSerials tis WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code)
				 																									THEN
									(SELECT  TOP 1  tis.is_id  FROM @tblItemSerials tis WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code)
								ELSE NULL
							END		[is_id],
							CASE
								WHEN ti.item_code				= @item_code THEN 1
								WHEN ti.item_vendorCode			= @item_code THEN 2
								WHEN ti.item_codeAlternative	= @item_code THEN 4
								WHEN  ti.item_id IN (SELECT tis.item_id
														FROM @tblItemSerials tis
														WHERE /*tis.comp_id = @comp_id AND*/ tis.is_serial = @item_code /*AND tis.is_available = 'true' MOS, 12-2011*/ )  THEN 3
								ELSE 5
							END		[xOrder],

							CASE
								WHEN exists(	SELECT  TOP 1 1
													FROM @tblItemSerials tis
													WHERE	/*tis.comp_id			= @comp_id */
															tis.is_serial		= @item_code
														AND tis.item_id			= ti.item_id
														AND tis.is_available	= 'true' )   THEN 'True'
								ELSE 'False'
							END		[bitSerialAvailable],

							CASE
								WHEN exists(	SELECT  TOP 1 1
													FROM @tblItemSerials tis
													INNER JOIN tbTempItemStock ttis	WITH (NOLOCK)
														ON ttis.is_id = tis.is_id
													WHERE	/*tis.comp_id			= @comp_id */
															tis.is_serial		= @item_code
														AND tis.item_id			= ti.item_id
														AND tis.is_id			= ttis.is_id)
											OR
									 EXISTS(			SELECT  TOP 1 1
															FROM tbSaleOrderSerials tsos WITH (NOLOCK)
															INNER JOIN @tblItemSerials tis
																ON		/*tis.comp_id		= @comp_id */
																		tis.is_serial	= @item_code
																	AND tis.item_id		= ti.item_id
															WHERE		tsos.comp_id = @comp_id
																	AND tsos.is_id = tis.is_id
										   )
														 THEN 'True'
								ELSE 'False'
							END		[bitSerialInTempItemStock],
							0					[foundType],
							1					[intDUNQty],
							ti.item_disabled


						FROM 	dbo.tbItem ti WITH (NOLOCK)
					WHERE	ti.comp_id = @comp_id AND
							ti.item_id = @intItemIDPUTA AND
							ti.item_disabled = 'False'	-- MOS 01-2023



				END


		END

	--DROP TABLE #tmpItems
	--DROP TABLE #tmpItems2


END


--0000021424
GO










CREATE  PROCEDURE [dbo].[spItem_GetDataByExactlyCode]
(
	@comp_id		INT,
	@item_code		VARCHAR(100)
)
AS

BEGIN

	SET NOCOUNT ON
	SELECT ti.item_id
		FROM tbitem  ti		WITH (NOLOCK)
		WHERE	ti.comp_id	 = @comp_id		AND
				ti.item_code = @item_code

END
GO





-- MOS 05-2018: cambie fnGetAStock x fnGetAStock4MaxAssociation  (x si se pone muy lenta esta busqueda !!!)


-- ------------------------------------------------------------------------------------
--
-- ATENCION !!!!!!!!!!!!!!!!!!!!!!!
--
-- Si se modifica este SP, y cambia el orden de los campos, verificar la página
-- wfmSelItem, ya que busca los campos 11 y 12 (10 y 11 en la página) para encontrar
-- el stock físico y potencial.-

-- Tambien MOdificar spItem_getDataByFilters_vendorCode

-- ------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spItem_getDataByFilters]
(
	@comp_id										INT,
	@lang_id										INT,
	@bra_id											INT,
	@prof_id										INT,
	@Item_code										VARCHAR(100),
	@Item_desc1										VARCHAR(100),
	@Item_desc2										VARCHAR(100),
	@cat_id											INT,
	@subcat_id										INT,
	@not4Sale										INT,
	@option2										INT,
	@item_vendorCode								VARCHAR(50),
	@checkstock										BIT,
	@checkAvailable									BIT,
	@stor_id										INT,
	@option											INT,	-- Talles y Colores

	@page_size										INT,
	@page_number									INT,
	@order_by										VARCHAR(MAX),
	@brand_id										INT,
	@supp_id										INT,
	@ItemClass										VARCHAR(MAX),
	@intPCConfigClass								INT,
	@intPCConfigDisRel4ItemID						BIT,
	@intPCConfigItemID								INT,
	@bitShowDisabled								BIT,	-- Articulo DESHABILITADO, x defecto NO los muestra

	@item_newness									BIT,
	@item_liquidation								BIT,
	@item_outlet									BIT,
	@item_codeAlternative							VARCHAR(400),
	@item_id										INT,
	@mlp_publicationID								BIGINT,
	@item_IsCreatedBySaleOrderProductionComposition	BIT,
	@subcataux_id									INT
	-- ---------------------------------------------------------------------------------
	-- OJOOOOOOOOOOOOOOOOOO
	-- Si agregan un campo tocar tambien  '**kjbgfwekjb38756jkkjba en Visual !!!!!!!!!
	-- ---------------------------------------------------------------------------------
)
AS



BEGIN


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- --------------------------------------------------------------------------------------------------------
	-- Evitar Bloqueo de Interprocesos - CONSULTAR a Aquitecto
	-- --------------------------------------------------------------------------------------------------------
	SET LOCK_TIMEOUT 25000			-- 25 segundos
	SET DEADLOCK_PRIORITY LOW		-- Tomar en cuenta para ULTIMA Opcion de Eliminación
	-- --------------------------------------------------------------------------------------------------------


	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
	/*
	DECLARE @comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@Item_code			VARCHAR(100),
			@Item_desc1			VARCHAR(100),
			@Item_desc2			VARCHAR(100),
			@cat_id				INT,
			@subcat_id			INT,
			@not4Sale			INT,
			@option2            INT,
			@item_vendorCode	VARCHAR(50),
			@checkstock			BIT,
			@checkAvailable		BIT,
			@stor_id			INT,
			@option				INT,
			@page_size			INT,
			@page_number		INT,
			@order_by			VARCHAR(MAX),
			@brand_id			INT,
			@supp_id			INT,
			@ItemClass			VARCHAR(MAX),
			@intPCConfigItemID	INT,
			@intPCConfigClass	INT,
			@intPCConfigDisRel4ItemID BIT,
			@item_id					INT = 0,
			@mlp_publicationID			BIGINT = 0,
			@bitShowDisabled			BIT = 0,
			@item_newness				BIT = 0,
			@item_liquidation			BIT = 0,
			@item_outlet				BIT = 0,
			@item_codeAlternative		VARCHAR(400) = '',
			@item_IsCreatedBySaleOrderProductionComposition	BIT	 = 0
	select 	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@prof_id			=1,
			@Item_code			='',
			@Item_desc1			='',
			@Item_desc2			='',
			@cat_id				=-1,
			@subcat_id			=-1,
			@not4Sale			=-1,
			@option2            =1,
			@item_vendorCode	='',
			@checkstock			='false',
			@checkAvailable		='False',
			@stor_id			=10,
			@option				=0,
			@page_size			=10,
			@page_number		=0,
			@order_by			='', --'order by item_desc asc  [Stk] asc' --Lista de Precios 1 Final
			@brand_id			=-1,
			@supp_id			=-1,
			@ItemClass			= '',
			@intPCConfigItemID	= -1,
			@intPCConfigClass	= -1,
			@intPCConfigDisRel4ItemID = 0
	--@option = 0 - sólo artículos que no estén incluidos en size/color
	--@option = 1 - sólo artículos de size/color
	--@option = 2 - ambos
	IF NOT OBJECT_ID('tempdb.dbo.#tmpTaxes')		IS NULL DROP TABLE #tmpTaxes

	*/
	-- -----------------------------------------------------------------------





	-- Tomo los Grupos de Sucursales a los que pertenece esta sucursal
	DECLARE @tmpBranchsOfBranchGroup TABLE(brag_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchsOfBranchGroup(brag_id)
		SELECT brag_id
			FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
			WHERE	tbgd.comp_id	= @comp_id AND
					tbgd.bra_id		= @bra_id




	-- Si llega un ItemID NO se va a tomar en cuenta el código
	IF @item_id <> 0
		BEGIN
			SELECT TOP 1 @Item_code		= ISNULL(ti.item_code,'')
				FROM tbItem ti			WITH (NOLOCK)
				WHERE	ti.comp_id	= @comp_id AND
						ti.item_id	= @item_id
		END


	-- Si llega un ItemID NO se va a tomar en cuenta el código
	IF @mlp_publicationID <> 0
		BEGIN
			SELECT TOP 1 @Item_code		= ISNULL(ti.item_code,'')
				FROM		tbItem							ti			WITH (NOLOCK)
				INNER JOIN	tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
					ON	tmlip.comp_id = ti.comp_id AND
						tmlip.item_id = ti.item_id
				WHERE	tmlip.comp_id = @comp_id AND
						tmlip.mlp_publicationID LIKE '%' + CONVERT(NVARCHAR(30),@mlp_publicationID)  + '%'
		END




	-- Si el codigo contiene │*│ significa que se busco por el control de seleccion y no debe buscar por contenido sino un codigo exactamente igual.
	DECLARE @bitIsDirectSearchFromItem AS BIT
	SET		@bitIsDirectSearchFromItem = 'False'
	IF @Item_code LIKE '%│*│'
		BEGIN
			SET @bitIsDirectSearchFromItem = 'True'
			SET @Item_code = REPLACE(@Item_code,'│*│','')
		END






	-- Talles y Colores, si opcion = 2 (seleccion de talles y colores en PEDIDOS, q n busque x stock)
	IF @option = 2 OR @option = 1
		BEGIN
			SET @checkstock     = 'False'
			SET @checkAvailable = 'False'
		END

	--IF @checkAvailable = 'True'    -- SPEED, MOS, 05-2017
	--	BEGIN
	--		SET @checkstock = 'False'
	--	END



	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbItemClass
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemClass TABLE (ic_id INT PRIMARY KEY)
	IF @ItemClass = '-1' OR @ItemClass = ''
		BEGIN
			INSERT INTO @tmpItemClass (ic_id)	SELECT tic.ic_id
			                                 		FROM tbItemClass tic	WITH (NOLOCK)
			               		WHERE tic.comp_id = @comp_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemClass ( ic_id)	SELECT items
			                                  		FROM dbo.fnSplitTable(@ItemClass,',') fst
		END
	-- -------------------------------------------------------------------------------------		`

	-- -------------------------------------------------------------------------------------
	-- Se fija si es un EAN Adicional
	-- -------------------------------------------------------------------------------------
	DECLARE @itemID4EAN		AS INT
	SET		@itemID4EAN = NULL
	SELECT	@itemID4EAN = tie.item_id
		FROM tbItemEAN tie			WITH (NOLOCK)
		INNER JOIN tbitem ti		WITH (NOLOCK)
			ON	ti.comp_id = tie.comp_id	AND
				ti.item_id = tie.item_id
		WHERE	tie.comp_id		= @comp_id		AND
				tie.ie_ean		= @Item_code	AND
				ti.item_expean	= 'True'

	-- -------------------------------------------------------------------------------------


	-- ---------------------------------------------------------
	-- Creamos una Tabla Temporal para uego hacer Inner Join y
	-- acelerar la busqueda
	-- ---------------------------------------------------------

	DECLARE @bitItem_desc1 AS BIT
	DECLARE @bitItem_desc2 AS BIT
	IF @Item_desc1 = ''
		BEGIN
			SET @bitItem_desc1 = 'False'
		END
	ELSE
		BEGIN
			SET @bitItem_desc1 = 'True'
		END
	IF @Item_desc2 = ''
		BEGIN
			SET @bitItem_desc2 = 'False'
		END
	ELSE
		BEGIN
			SET @bitItem_desc2 = 'True'
		END



	-- ========================================================================================================
	--si la variable @stor_id ni viene informada, se recupera el valor del stor_id de la sucursal, sino se
	--deja el valor que viene informado
	-- MOS 08-2024: Referencia **wenfk2398572390451235 de esta MIERDAAAAAA
	DECLARE @storage INT
	SELECT  @stor_id =	CASE  -- MOS 05-2020 x Marstech
							WHEN tb.stor_id4OverwriteSelItem IS NOT NULL THEN tb.stor_id4OverwriteSelItem
							ELSE @stor_id
						END	,
			@storage =	CASE
							WHEN @stor_id <= 0 then tb.stor_id
							ELSE @stor_id
	                 	END
   		FROM tbBranch tb		WITH (NOLOCK)
	   	WHERE	tb.comp_id	= @comp_id AND
	   			tb.bra_id	= @bra_id
	-- ========================================================================================================



	DECLARE @bitFastIsAvailable AS BIT = 'False'
	SELECT  @bitFastIsAvailable = ISNULL(ts.stor_mustRecalculateAvailableStock ,'False')
		FROM tbStorage AS ts	WITH (NOLOCK)
		WHERE	ts.comp_id = @comp_id AND
				ts.stor_id = @stor_id



	DECLARE @tmpItemSearch		TABLE(item_id INT PRIMARY KEY , intROW INT IDENTITY(1,1))
	DECLARE @tmpItemSearch2		TABLE(item_id INT PRIMARY KEY , intROW INT IDENTITY(1,1))
	CREATE TABLE #tmpItemFinalSearch (item_id INT PRIMARY KEY , intROW INT)
	DECLARE @strOrderBy AS NVARCHAR(MAX)
	--SET @strOrderBy = @order_by
	--SET @strOrderBy = dbo.fnstrAllTrim( REPLACE(@strOrderBy,'ORDER BY',''))
	--SET @strOrderBy = dbo.fnstrAllTrim( REPLACE(@strOrderBy,'order by',''))
	--IF  @strOrderBy = '' SET @strOrderBy = 'ii.item_desc ASC'
	SET @strOrderBy = 'ii.item_desc ASC'



	IF @item_codeAlternative <> ''
		BEGIN
			INSERT INTO @tmpItemSearch(item_id)
				SELECT	tica.item_id
					FROM tbItem_codeAlternative tica		WITH (NOLOCK)
					INNER JOIN tbitem			ii			WITH (NOLOCK)
					ON	ii.comp_id = tica.comp_id								AND
						ii.item_id = tica.item_id
					LEFT JOIN @tmpBranchsOfBranchGroup tmp
						ON tmp.brag_id = ii.brag_id
					WHERE	tica.comp_id = @comp_id								AND
							tica.item_codeAlternative LIKE '%' + @item_codeAlternative + '%'				AND
							CASE
								WHEN @checkstock = 'False'												THEN 1
								WHEN dbo.fnGetStockOfStorageGroup(@comp_id,@stor_id,tica.item_id) > 0	THEN 1
								ELSE																	     0
							END = 1												AND
							CASE
								WHEN @checkAvailable = 'False'											THEN 1
								WHEN @bitFastIsAvailable = 'true'  AND  dbo.fnGetStockAvailable(@comp_id,@stor_id,tica.item_id) > 0					THEN 1
								WHEN @bitFastIsAvailable = 'False' AND  dbo.fnGetAStock4MaxAssociation(@comp_id,@stor_id,tica.item_id,999999999) > 0 THEN 1
								ELSE																		 0
							END = 1														AND
							(@cat_id		= -1 OR ii.cat_id		= @cat_id)			AND
							(@subcat_id		= -1 OR ii.subcat_id	= @subcat_id)		AND
							(@subcataux_id	= -1 OR ii.subcataux_id	= @subcataux_id)	AND
							(@brand_id	= -1 OR ii.brand_id		= @brand_id)	AND
							ii.item_disabled	= @bitShowDisabled				AND

							-- NOO, estos FORROS vuelven loco a todos !!!!
							----ii.item_not4Sale	= @bitShowDisabled				AND	-- MOS 01-2023: En selItem dice DESHABILITADO PARA LA VENTA y no DESHABILITADO !!!!!!!!!!!!!!!!!!!!!!!!
							--CASE	-- MOS 01-2023 x FIESA
							--	WHEN @bitShowDisabled = -1					THEN 1
							--	WHEN @bitShowDisabled = ii.item_not4Sale	THEN 1
							--	ELSE											 0
							--END = 1	AND
							--ii.item_disabled	= 'False'						AND -- MOS 01-2023

							CASE
								WHEN ii.brag_id IS NOT NULL AND tmp.brag_id IS NULL THEN 0
								WHEN ii.bra_id  IS NULL								THEN 1
								WHEN ii.bra_id  = @bra_id							THEN 1
								ELSE 0
							END = 1


							--(
							--	ii.bra_id IS NULL
							--		OR
							--	ii.bra_id = @bra_id
							--)
		END
	ELSE
		BEGIN

			INSERT INTO @tmpItemSearch(item_id)
			SELECT	ii.item_id--,
				--	ROW_NUMBER() OVER ( ORDER BY @order_by ) AS intROW
				--INTO #tmpItemSearch
				FROM tbItem ii		WITH (NOLOCK)
				LEFT JOIN @tmpBranchsOfBranchGroup tmp
					ON tmp.brag_id = ii.brag_id
				INNER JOIN	@tmpItemClass tic
					ON	tic.ic_id = ii.ic_id
				WHERE
						ii.comp_id			= @comp_id AND
						ii.item_disabled	= @bitShowDisabled AND

						-- NOOOOO, FORROS de F
						--ii.item_not4Sale	= @bitShowDisabled				AND	-- MOS 01-2023: En selItem dice DESHABILITADO PARA LA VENTA y no DESHABILITADO !!!!!!!!!!!!!!!!!!!!!!!!
						--CASE	-- MOS 01-2023 x FIESA
						--	WHEN @bitShowDisabled = -1					THEN 1
						--	WHEN @bitShowDisabled = ii.item_not4Sale	THEN 1
						--	ELSE											 0
						--END = 1	AND
						--ii.item_disabled	= 'False'						AND -- MOS 01-2023



						CASE
							WHEN ii.brag_id IS NOT NULL AND tmp.brag_id IS NULL THEN 0
							WHEN ii.bra_id  IS NULL								THEN 1
							WHEN ii.bra_id  = @bra_id							THEN 1
							ELSE 0
						END = 1	AND
						--(ii.bra_id IS NULL  OR ii.bra_id = @bra_id) AND
						CASE
							WHEN @bitItem_desc1 = 'False'					THEN 1
							WHEN ii.item_desc LIKE '%' + @Item_desc1 + '%'  THEN 1
							ELSE											     0
						END = 1	AND
						CASE
							WHEN @bitItem_desc2 = 'False'					THEN 1
							WHEN ii.item_desc LIKE '%' + @Item_desc2 + '%'  THEN 1
							ELSE 0
						END = 1	AND

						CASE
							WHEN @Item_code = ''																		THEN 1
							WHEN @bitIsDirectSearchFromItem = 'True'  AND  ii.item_code =  @Item_code 					THEN 1
							WHEN @bitIsDirectSearchFromItem = 'False' AND  ii.item_code LIKE '%' +  @Item_code + '%'	THEN 1
							ELSE																							 0
						END = 1 AND

						(@cat_id	= -1 OR ii.cat_id		= @cat_id) AND
						(@subcat_id = -1 OR ii.subcat_id	= @subcat_id) AND
						(@subcataux_id	= -1 OR ii.subcataux_id	= @subcataux_id)	AND
						(@brand_id	= -1 OR ii.brand_id		= @brand_id) AND
						CASE
							WHEN @option2 = -1 THEN 1
							WHEN @option2 = 2 AND ii.item_vendorCode =			@item_vendorCode		THEN 1
							WHEN @option2 = 0 AND ii.item_vendorCode like		@item_vendorCode + '%'	THEN 1
							WHEN @option2 = 1 AND ii.item_vendorCode like '%' + @item_vendorCode + '%'	THEN 1
							WHEN @option2 = 3 AND ii.item_vendorCode <>			@item_vendorCode		THEN 1
							WHEN @option2 = 4 AND ii.item_vendorCode not like	@item_vendorCode		THEN 1
							ELSE																			 0
						END = 1	AND
						(@supp_id	= -1		OR ii.supp_id = @supp_id) AND
						(@itemID4EAN IS NULL	OR ii.item_id = @itemID4EAN) AND
						--CASE
						--	WHEN @not4Sale = -1									THEN 1
						--	WHEN @not4Sale = 0 AND ii.item_not4Sale = 'False'	THEN 1
						--	WHEN @not4Sale = 1 AND ii.item_not4Sale = 'True'	THEN 1
						--	ELSE													 0
						--END = 1 AND

						CASE
							WHEN @checkstock = 'False'											THEN 1
							WHEN dbo.fnGetStockOfStorageGroup(@comp_id,@stor_id,ii.item_id) > 0 THEN 1
							ELSE																	 0
						END = 1 AND
						CASE
							WHEN @checkAvailable = 'False'									THEN 1
							WHEN @bitFastIsAvailable = 'True'  AND  dbo.fnGetStockAvailable(@comp_id,@stor_id,ii.item_id) > 0	THEN 1
							WHEN @bitFastIsAvailable = 'False' AND  dbo.fnGetAStock4MaxAssociation(@comp_id,@stor_id,ii.item_id,999999999) > 0 THEN 1
							ELSE																 0
						END = 1


					ORDER BY  ii.item_desc
		END

	-- Saco todo lo que no sea OUTLET, se hace asi por un tema de velocidad de la busaueda en sistemas con muchos articulos.
	IF @item_outlet = 1
		BEGIN
			DELETE @tmpItemSearch
				FROM   @tmpItemSearch tmp
				INNER JOIN tbitem	ti		WITH (NOLOCK)
					ON	ti.comp_id		= @comp_id		AND
						ti.item_id		= tmp.item_id
				WHERE ti.item_outlet	= 0

		END



	-- Saco todo lo que no haya sido creado x armado de pc y produccion.
	IF @item_IsCreatedBySaleOrderProductionComposition = 1
		BEGIN
			DELETE @tmpItemSearch
				FROM   @tmpItemSearch tmp
				INNER JOIN tbitem	ti		WITH (NOLOCK)
					ON	ti.comp_id		= @comp_id		AND
						ti.item_id		= tmp.item_id
				WHERE ISNULL(ti.item_IsCreatedBySaleOrderProductionComposition,'False') = 'False'
		END


	-- Saco todo lo que no sea Oferta, se hace asi por un tema de velocidad de la busaueda en sistemas con muchos articulos.
	IF @item_liquidation = 1
		BEGIN
			DELETE @tmpItemSearch
				FROM   @tmpItemSearch tmp
				INNER JOIN tbitem	ti		WITH (NOLOCK)
					ON	ti.comp_id		= @comp_id		AND
						ti.item_id		= tmp.item_id
				WHERE ti.item_liquidation	= 0

		END

	-- Saco todo lo que no sea Novedad, se hace asi por un tema de velocidad de la busaueda en sistemas con muchos articulos.
	IF @item_newness = 1
		BEGIN
			DELETE @tmpItemSearch
				FROM   @tmpItemSearch tmp
				INNER JOIN tbitem	ti		WITH (NOLOCK)
					ON	ti.comp_id		= @comp_id		AND
						ti.item_id		= tmp.item_id
				WHERE ti.item_newness	= 0

		END

	-- Si pide los Disponibles para venta, borro los NO disponibles
	IF @not4Sale = 0
		BEGIN
			DELETE @tmpItemSearch
				FROM   @tmpItemSearch tmp
				INNER JOIN tbitem	ti		WITH (NOLOCK)
					ON	ti.comp_id		= @comp_id		AND
						ti.item_id		= tmp.item_id
				WHERE ti.item_not4Sale	= 'True'

		END


	-- Si pide los Disponibles para venta, borro los NO disponibles
	IF @not4Sale = 1
		BEGIN
			DELETE @tmpItemSearch
				FROM   @tmpItemSearch tmp
				INNER JOIN tbitem	ti		WITH (NOLOCK)
					ON	ti.comp_id		= @comp_id		AND
						ti.item_id		= tmp.item_id
				WHERE ti.item_not4Sale	= 'False'

		END


	-- -----------------------------------------------------------------------------
	--  Elimina articulos que NO son del tipo de parte que se necesita.-
	-- -----------------------------------------------------------------------------
	IF @intPCConfigClass <> -1
		BEGIN


			IF @intPCConfigClass = 2 AND @intPCConfigDisRel4ItemID = 'False' -- MotherBoard
				BEGIN

					DELETE @tmpItemSearch
						FROM @tmpItemSearch tmp
					WHERE tmp.item_id NOT IN
						(
						SELECT tipr.item_id
							FROM   tbItem_PCConfig_Relations				tipr			WITH(NOLOCK)
							INNER JOIN tbItem									ti			WITH(NOLOCK)
								ON	ti.comp_id = tipr.comp_id					AND
									ti.item_id = tipr.item_id
							INNER JOIN tbSubCategory							tsc			WITH(NOLOCK)
								ON	tsc.comp_id				= ti.comp_id		AND
									tsc.cat_id				= ti.cat_id			AND
									tsc.subcat_id			= ti.subcat_id		--AND
									--tsc.subcat_pcConfigType	= 2					--TIPO MOTHERBOARD
							LEFT JOIN tbSubCategoryAux							tsca		WITH (NOLOCK)
								ON	tsca.comp_id		= ti.comp_id					AND
									tsca.subcataux_id	= ti.subcataux_id
							WHERE	tipr.comp_id		= @comp_id					AND
									tipr.pcctr_disabled = 'False'					AND
									(
										tsc.subcat_pcConfigType		= 2	 OR
										tsca.subcat_pcConfigType	= 2					--TIPO MOTHERBOARD
									)												AND
									tipr.pcct_id  IN (SELECT tipr2.pcct_id
															 FROM tbItem_PCConfig_Relations				tipr2	WITH (NOLOCK)
															 WHERE	tipr2.comp_id			= @comp_id				AND
																	tipr2.item_id			= @intPCConfigItemID	AND
																	tipr2.pcctr_disabled	= 'False')
						)
				END

			ELSE IF @intPCConfigClass = 4 AND @intPCConfigDisRel4ItemID = 'False'	-- Memorias
				BEGIN

					DELETE @tmpItemSearch
						FROM @tmpItemSearch tmp
					WHERE tmp.item_id NOT IN
						(
							SELECT tipr.item_id
								FROM   tbItem_PCConfig_Relations				tipr			WITH(NOLOCK)
								INNER JOIN tbItem									ti			WITH(NOLOCK)
									ON	ti.comp_id = tipr.comp_id					AND
										ti.item_id = tipr.item_id
								INNER JOIN tbSubCategory							tsc			WITH(NOLOCK)
									ON	tsc.comp_id				= ti.comp_id		AND
										tsc.cat_id				= ti.cat_id			AND
										tsc.subcat_id			= ti.subcat_id		--AND
										-- tsc.subcat_pcConfigType	= 4					--Memorias
								LEFT JOIN tbSubCategoryAux							tsca		WITH (NOLOCK)
									ON	tsca.comp_id		= ti.comp_id					AND
										tsca.subcataux_id	= ti.subcataux_id
								WHERE	tipr.comp_id		= @comp_id					AND
										tipr.pcctr_disabled = 'False'					AND
										(
											tsc.subcat_pcConfigType		= 4			OR		--Memorias
											tsca.subcat_pcConfigType	= 4					--Memorias
										)												AND
										tipr.pcct_id  IN (SELECT tipr2.pcct_id
																 FROM tbItem_PCConfig_Relations				tipr2		WITH (NOLOCK)
																 WHERE	tipr2.comp_id			= @comp_id				AND
																		tipr2.item_id			= @intPCConfigItemID	AND
																		tipr2.pcctr_disabled	= 'False')
						)
				END

			ELSE IF @intPCConfigClass = 5 AND @intPCConfigDisRel4ItemID = 'False' -- Gabinetes
				BEGIN

					DELETE @tmpItemSearch
						FROM @tmpItemSearch tmp
					WHERE tmp.item_id NOT IN
						(
							SELECT tipr.item_id
								FROM   tbItem_PCConfig_Relations				tipr			WITH(NOLOCK)
								INNER JOIN tbItem									ti			WITH(NOLOCK)
									ON	ti.comp_id = tipr.comp_id					AND
										ti.item_id = tipr.item_id
								INNER JOIN tbSubCategory							tsc			WITH(NOLOCK)
									ON	tsc.comp_id				= ti.comp_id		AND
										tsc.cat_id				= ti.cat_id			AND
										tsc.subcat_id			= ti.subcat_id		--AND
										--tsc.subcat_pcConfigType	= 5					--TIPO Gabinetes
								LEFT JOIN tbSubCategoryAux							tsca		WITH (NOLOCK)
									ON	tsca.comp_id		= ti.comp_id					AND
										tsca.subcataux_id	= ti.subcataux_id
								WHERE	tipr.comp_id		= @comp_id					AND
										tipr.pcctr_disabled = 'False'					AND
										(
											tsc.subcat_pcConfigType		= 5				OR	--TIPO Gabinetes STL Cambié el AND por un OR, por eso no traía los gabinetes
											tsca.subcat_pcConfigType	= 5					--TIPO Gabinetes
										)												AND
										tipr.pcct_id  IN (SELECT tipr2.pcct_id
																 FROM tbItem_PCConfig_Relations				tipr2	WITH (NOLOCK)
																 WHERE	tipr2.comp_id			= @comp_id				AND
																		tipr2.item_id			= @intPCConfigItemID	AND
																		tipr2.pcctr_disabled	= 'False')
						)
				END

			ELSE
				BEGIN
					-- Resto Sin Relaciones
					DELETE @tmpItemSearch
						FROM @tmpItemSearch tmp
						INNER JOIN tbItem	ti										WITH(NOLOCK)
							ON	ti.comp_id = @comp_id			AND
								ti.item_id = tmp.item_id
						INNER JOIN tbSubCategory				tsc					WITH(NOLOCK)
							ON	tsc.comp_id		= ti.comp_id	AND
								tsc.cat_id		= ti.cat_id		AND
								tsc.subcat_id	= ti.subcat_id
						LEFT JOIN tbSubCategoryAux							tsca	WITH (NOLOCK)
							ON	tsca.comp_id		= ti.comp_id							AND
								tsca.subcataux_id	= ti.subcataux_id
						WHERE	ti.comp_id = @comp_id										AND
								ISNULL(tsc.subcat_pcConfigType,-1)  <> @intPCConfigClass	AND
								ISNULL(tsca.subcat_pcConfigType,-1) <> @intPCConfigClass
				END

		END
	-- -----------------------------------------------------------------------------





	-- -----------------------------------------------------------------------------
	-- Elimina registros de talles y colores segun lo que se necesiter
    --NoFathers		= 0  'para toda la aplicación
    --NoChilds		= 1  'para wfmItemSizeColor
    --Fathers		= 2  'para wfmSaleOrderDetailSizeColor
    --All			= -1 '?
	-- -----------------------------------------------------------------------------
	IF @option = 0 OR @option = 10	-- Saco TODOS los que son Padres
		BEGIN
			DELETE @tmpItemSearch
				FROM @tmpItemSearch tmp
				INNER JOIN tbItemSizeColorRelation tiscr	WITH(NOLOCK)

					ON  tiscr.comp_id = @comp_id    AND
						tiscr.item_id = tmp.item_id
		END
	IF @option = 1  -- Saco todos los HIJOS y quedan solo Padres o Sin Talle y Color
		BEGIN
			DELETE @tmpItemSearch
				FROM @tmpItemSearch tmp
				INNER JOIN tbItemSizeColorRelation tiscr	WITH(NOLOCK)

					ON  tiscr.comp_id = @comp_id    AND
						tiscr.item_id_child = tmp.item_id
		END
	IF @option = 2	-- Solo los que SI o Si son padres
		BEGIN
			DELETE @tmpItemSearch
				FROM @tmpItemSearch tmp
				INNER JOIN tbItemSizeColorRelation tiscr	WITH(NOLOCK)
					ON  tiscr.comp_id = @comp_id    AND
						tiscr.item_id_child = tmp.item_id
			DELETE @tmpItemSearch
				FROM @tmpItemSearch tmp
				LEFT JOIN tbItemSizeColorRelation tiscr		WITH(NOLOCK)
					ON  tiscr.comp_id = @comp_id    AND
					    tiscr.item_id = tmp.item_id
				WHERE tiscr.comp_id IS NULL
		END
	-- -----------------------------------------------------------------------------


	-- Genera la Tabla que se muestra mas abajo con JOIN
	DECLARE @intFirstRecord AS INT
	DECLARE @intLastRecord  AS INT
	SET @intFirstRecord = @page_size * @page_number
	SET @intLastRecord  = @intFirstRecord + @page_size


	-- pOR SI SE BORRAN id HAY QUE RENUMERAR EN order
	INSERT INTO @tmpItemSearch2(item_id)
		SELECT tmp.item_id
			FROM @tmpItemSearch TMP
			ORDER BY intROW


--==
--SELECT *
--	FROM @tmpItemSearch2 tmp
--	INNER JOIN tbitem ti
--		ON ti.item_id = tmp.item_id
--	ORDER BY intROW
--==


	-- Tabla FINAL LIsta para hacer Inner Join y no poner lenta la puta busqueda abajo hecha por el HDP
	INSERT INTO #tmpItemFinalSearch(item_id, intROW)
		SELECT tmp.item_id, tmp.intROW
			FROM @tmpItemSearch2 tmp
			WHERE tmp.intROW BETWEEN @intFirstRecord AND @intLastRecord
			ORDER BY tmp.intROW



--==
--SELECT *
--	FROM #tmpItemFinalSearch tmp
--	INNER JOIN tbitem ti
--		ON ti.item_id = tmp.item_id
--	ORDER BY intROW
--==

	-- ---------------------------------------------------------



BEGIN TRY



	-- ========================================================================================================
	--si la variable @order_by no viene informada, se le pone un valor por defecto, para que no cancele
	--la numeración de registros para la paginación
	IF LEN(@order_by) < 1	SET @order_by = 'ORDER BY intROW ASC'
	-- ========================================================================================================





	---- ========================================================================================================
	----si la variable @stor_id ni viene informada, se recupera el valor del stor_id de la sucursal, sino se
	----deja el valor que viene informado
	--DECLARE @storage INT
	--SELECT  @storage =	CASE
	--						WHEN @stor_id <= 0 then tb.stor_id
	--						ELSE @stor_id
	--                 	END
 --  		FROM tbBranch tb		WITH (NOLOCK)
	--   	WHERE	tb.comp_id	= @comp_id AND
	--   			tb.bra_id	= @bra_id
	---- ========================================================================================================





	DECLARE	@lprli_id					INT,
			@lstor_id					INT,
			@lis_prli_plusIVATax		BIT,
			@strColumnName				NVARCHAR(200),
			@bitPhisicalStock			BIT,
			@curr_id4PriceOrCost		INT,
			@curr_Symbol4PriceOrCost	NVARCHAR(10),
			@bitNoShowStorageGroup      BIT,

			--variable donde se generará el select/from de la página solicitada
			@lSelectPaging				VARCHAR(MAX),

			--variable donde se generará el where de la página solicitada
			@lWhereFixedPaging			VARCHAR(MAX),

			--variable donde se generará el select con todos los registros numerados en el orden solicitado
			@lSelectDynamic				VARCHAR(MAX),

			--variable donde se generará el from/join/where con todos los registros numerados en el orden solicitado
			@lFromFixedJoinWhereDynamic	VARCHAR(MAX),

			--variable donde se generarán los campos dinámicos según la configuración de la consulta
			@lFieldsDynamictmp			VARCHAR(MAX),
			@lFieldsDynamic1			VARCHAR(MAX),
			@lFieldsDynamic2			VARCHAR(MAX),
			@lFieldsDynamic3			VARCHAR(MAX),
			@lFieldsDynamic4			VARCHAR(MAX),

			--variable donde se generarán los Inner Joins relacionados a los campos dinámicos según la configuración de la consulta
			@lInnerJoinDynamic			VARCHAR(MAX),

			--variable donde se generará el From tbItem Inner Joins de tbCategoty/tbSubCategory
			@lFromFixed					VARCHAR(MAX),

			--variable donde se generará el Where con todas las condiciones de los parámetros recibidos
			@lWhereFixed				VARCHAR(MAX),

			--variable donde se generará el ROW_NUMBER para numerar los registros de la consulta total y el orden solicitado por @order_by
			@lRowNumberOrderDynamic		VARCHAR(MAX),


			@lsourcealias				CHAR(27),
			@lalias						CHAR(1),
			@lAliasIndex				INT,
			@lname						VARCHAR(200),
			@lcoslis_id					INT,
			@lcoslis_name				VARCHAR(200),
			@lcoslis_aw					BIT,
			@lis_id						INT,
			@lplusIVATax				VARCHAR(10),
			@lis_decimalPlaces			INT,
			@ltoClipboard				VARCHAR(4)	-- TN:218






	-- ========================================================================================================
	--inicialización de variables
	--la variable @lsourcealias se carga la cadena de donde se obtendrán los alias para los joins dinámicos
	SELECT	@lsourcealias			= 'ABCDEFGHIJKLMNÑOPQRSTUVWXYZ',
			@lSelectDynamic			= '',
			@lFieldsDynamictmp		= '',
			@lFieldsDynamic1		= '',
			@lFieldsDynamic2		= '',
			@lFieldsDynamic3		= '',
			@lFieldsDynamic4		= '',
			@lInnerJoinDynamic		= '',
			@lAliasIndex			= 0
	-- ========================================================================================================





	-- ========================================================================================================
	--generación de temporal con la sumatoria de impuestos por cada artículo
	CREATE TABLE	#tmpTaxes ( comp_id  INT ,item_id  INT PRIMARY KEY,tax_percentage  decimal(19, 6) NULL,tax_percentageII  decimal(19, 6) NULL)
	CREATE INDEX	#tmpTaxesIndex ON #tmpTaxes (comp_id,item_id);

	INSERT INTO		#tmpTaxes
	(		comp_id,		item_id,		tax_percentage,	tax_percentageII)
	(
		SELECT	tit.comp_id,	tit.item_id,	sum(ttn.tax_percentage) [tax_percentage], SUM(CASE
																									WHEN ttn.tax_class = 20 THEN ttn.tax_percentage
																									ELSE 0
																							  END	)	[tax_percentageII]
			FROM	tbItemTaxes				tit		WITH (NOLOCK)
			INNER JOIN #tmpItemFinalSearch it	-- MOS: 12-2019 x Speed
				ON it.item_id = tit.item_id
			INNER JOIN tbTaxName	ttn		WITH (NOLOCK)
			ON	ttn.tax_id				= tit.tax_id	AND
				ttn.comp_id				= tit.comp_id	AND
				tit.tax_itemComposed	= 'false'
			WHERE	tit.comp_id		= @comp_id
			GROUP BY tit.comp_id, tit.item_id
	)
	-- ========================================================================================================





	-- ========================================================================================================
	--se convierten las variables INT en VARCHAR para poder ser utilizadas en las concatenaciones de cadenas y
	--evitar la conversión de la misma variable muchas de veces
	DECLARE	@str_comp_id	VARCHAR(4)	SET @str_comp_id = CONVERT(VARCHAR,@comp_id)
	DECLARE @str_lang_id	VARCHAR(4)	SET @str_lang_id = CONVERT(VARCHAR,@lang_id)
	DECLARE @str_bra_id		VARCHAR(4)	SET @str_bra_id  = CONVERT(VARCHAR,@bra_id)
	DECLARE @str_prof_id	VARCHAR(4)	SET @str_prof_id = CONVERT(VARCHAR,@prof_id)
	DECLARE @str_stor_id	VARCHAR(4)	SET @str_stor_id = CONVERT(VARCHAR,@storage)
	-- ========================================================================================================


	-- Si hay que pner mas columnas poner un @lFieldsDynamicX mas del ultimo que hay y subir el top
	-- son 13 aprox por cada variable
	SELECT TOP 50 *
		INTO #tmpItemSelection
		FROM vwItemSelection tis	WITH (NOLOCK)
		WHERE	tis.comp_id		= @comp_id
		AND		(tis.bra_id		= @bra_id
					OR tis.bra_id IS NULL
				)
		AND		tis.prof_id		= @prof_id

	UPDATE #tmpItemSelection
		SET bra_id = @bra_id


	-- ==========================================================================================================================
	-- comienzo de la generación de todas la variables que formarán los querys dinámicos que se ejecutarán al final del sp
	-- ==========================================================================================================================



	--campos fijos del select final
	SET @lSelectPaging = 'SELECT '' '' [+], '' '' [-], '' '' [*], '' '' [.], '' '' [:],'' '' [=],'' '' [;],[item_code],[item_desc],[Stk],[AStk], '



	----si en la variable @order_by se solicita el ordenamiento de [AStk] y/o [Stk], deben reemplazar estos valores por la función
	----que generan esos campos, ya que el order by del ROW_NUMBER no acepta los alias de los campos
	--IF  CHARINDEX('[AStk]', @order_by) > 0
	--	SET @order_by = REPLACE(@order_by,'[AStk]','dbo.fnGetAStock4MaxAssociation('+@str_comp_id+','+@str_stor_id+',ii.item_id,9999999999)')

	--IF  CHARINDEX('[Stk]', @order_by) > 0
	--	SET @order_by = REPLACE(@order_by,'[Stk]','dbo.fnGetStockOfStorageGroup('+@str_comp_id+','+@str_stor_id+',ii.item_id)')



	--campos fijos del select para numeración  DISTINCT
	SELECT @lSelectDynamic =';WITH resultado_total AS (' +
							'SELECT			tfs.intROW, ii.item_code,ii.item_desc,' +
							'Convert(decimal(15,0),dbo.fnGetStockOfStorageGroup('+@str_comp_id+','+@str_stor_id+',ii.item_id)) [Stk],' +
							'Convert(decimal(15,0),dbo.fnGetAStock4MaxAssociation('+@str_comp_id+','+@str_stor_id+',ii.item_id,9999999999)) [AStk],'


	DECLARE @order	INT
	DECLARE @is_id	INT

	--primer select para obtener el is_id que se deberá mostrar en el resultado de la consulta
--	SELECT	@is_id = min(tis.is_id)
--	FROM	#tmpItemSelection tis
--	WHERE	tis.comp_id	= @comp_id
--	AND		tis.bra_id	= @bra_id
--	AND		tis.prof_id	= @prof_id

	SELECT	@order = MIN(((isnull(tis.is_order,0)+1) * 1000000) + tis.is_id)
		FROM	#tmpItemSelection tis
		WHERE	tis.comp_id	= @comp_id
		AND		tis.bra_id	= @bra_id
		AND		tis.prof_id	= @prof_id


	SELECT @is_id = @order%1000000

--==
--SELECT @order_by
--==

	--comienzo del ciclo hasta el fin
	WHILE @is_id IS NOT NULL
	BEGIN


		--recuperamos los valores en base al @is_id
		SELECT	@lprli_id				= tis.prli_id,
				@lstor_id				= tis.stor_id,
				@lis_prli_plusIVATax	= tis.is_prli_plusIVATax,
				@lcoslis_id				= tis.coslis_id,
				@lcoslis_aw				= coslis_id_aw,
				@lis_id					= tis.is_id,
				@lis_decimalPlaces		= CASE WHEN ISNULL(tis.is_decimalPlaces,2) < 0 THEN 2 ELSE ISNULL(tis.is_decimalPlaces,2) END,
				@ltoClipboard			= CASE WHEN tis.is_toClipboard = 'true' THEN ' (C)' ELSE '' END, --TN:218,
				@strColumnName			= tis.ise_Desc,
				@bitPhisicalStock		= ISNULL(tis.stor_showPhisicalStock,'False'),
				@curr_id4PriceOrCost    = tis.curr_id4PriceOrCost,
				@bitNoShowStorageGroup  = IsNull(tis.is_NoShowStorageGroup,'False')

		FROM	#tmpItemSelection tis
		WHERE	tis.comp_id		= @comp_id
		AND		tis.bra_id		= @bra_id
		AND		tis.prof_id		= @prof_id
		AND		tis.is_id		= @is_id


		SET @curr_Symbol4PriceOrCost = ''
		IF  @curr_id4PriceOrCost IS NOT NULL
			BEGIN
				SELECT @curr_Symbol4PriceOrCost = tc.curr_symbol
					FROM tbsysCurrency tc		WITH (NOLOCK)
					WHERE tc.curr_id = @curr_id4PriceOrCost
			END


		--obtención del próximo alias que se utilizará en el join que generará el ciclo de los caracteres cargados en @lsourcealias,
		--esto es,tomar un caracter (letra) por vez para utilizarlos como alias ya que para diferentes campos se pueden estar utlizando
		--joins a las mismas tablas
		SET @lAliasIndex= @lAliasIndex+ 1
		SET @lalias = SUBSTRING(@lsourcealias,@lAliasIndex,1)
		IF @lis_prli_plusIVATax = 'true'
			SELECT @lplusIVATax = ' ' + tut.utexts_desc
				FROM tbsysUniqueTexts tut		WITH (NOLOCK)
				WHERE	tut.lang_id		= @lang_id AND
						tut.utexts_id	= 10
		ELSE
			SET @lplusIVATax = ''

		-- ------------------------------------------
		-- No se usa mas, se deja por compatibilidad
		-- ------------------------------------------
		SET @lplusIVATax = ''
		SET @lname = @strColumnName
		-- ------------------------------------------


		IF NOT @lprli_id IS NULL AND @curr_id4PriceOrCost IS NULL
			BEGIN

				/* GENERACIÓN DEL CÓDIGO PARA OBTENER LAS FILAS RELACIONADAS A LISTAS DE PRECIOS */


				/* OBTENCIÓN DEL NOMBRE DE LA LISTA DE PRECIOS */
				--SELECT @lname = tpl.prli_desc FROM tbPriceList tpl WHERE tpl.comp_id = @comp_id	AND tpl.prli_id = @lprli_id


				/* GENERACIÓN DE CAMPO DE LA LISTA DE PRECIOS */
				SET @lFieldsDynamictmp = @lFieldsDynamictmp +
								',  CONVERT(VARCHAR,CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+'), ISNULL('+@lalias+'1.prli_price *
										CASE
											WHEN '+@lalias+'2.is_prli_plusIVATaxCombo = ''true'' THEN (1+(   dbo.fnGetPriceListItemTaxesPercentage4Combo( ' + @lalias+'1.comp_id,' + @str_bra_id + ',' + @lalias+'1.item_id,' + @lalias+'1.prli_id)                                                    /100.00))
											WHEN '+@lalias+'2.is_prli_plusIVATax	  = ''true'' THEN (1+('+@lalias+'3.tax_percentage/100.00))
											WHEN '+@lalias+'2.is_prli_plusIITax4Neto  = ''true'' THEN (1+('+@lalias+'3.tax_percentageII/100.00))
											ELSE 1
										END,0))) + '' '' + LTRIM(RTRIM('+@lalias+'4.curr_symbol))   ['+@lname+@lplusIVATax+@ltoClipboard+']'


				--el campo también se carga en la variable del select final
				SET @lSelectPaging = @lSelectPaging + ' ['+@lname+@lplusIVATax+@ltoClipboard+'] ,'


--==
--SELECT @order_by,1
--==


				----si el campo está solicitado para ordenamiento se reemplaza por el valor correspondiente ya que el ordenamiento dentro del ROW_NUMBER no acepta los alias externos
				--IF  CHARINDEX('['+@lname+@lplusIVATax+@ltoClipboard+']', @order_by) > 0
				--	--SET @order_by = REPLACE(@order_by,'['+@lname+@lplusIVATax+@ltoClipboard+']','LTRIM(RTRIM('+@lalias+'4.curr_symbol)) + '' '' +  CONVERT(VARCHAR,CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+'), ISNULL('+@lalias+'1.prli_price *	CASE WHEN '+@lalias+'2.is_prli_plusIVATax = ''true'' THEN (1+('+@lalias+'3.tax_percentage/100.00)) ELSE 1 END,0)))')
				--	SET @order_by = REPLACE(@order_by,	--MOS
				--							'['+@lname+@lplusIVATax+@ltoClipboard+']',
				--							'LTRIM(RTRIM('+@lalias+'4.curr_symbol)) + '' '' + dbo.fnStrPADL(dbo.fnStrAllTrim(CONVERT(VARCHAR,CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+'), ISNULL('+@lalias+'1.prli_price *	CASE WHEN '+@lalias+'2.is_prli_plusIVATax = ''true'' THEN (1+('+@lalias+'3.tax_percentage/100.00)) ELSE 1 END,0)))), 25,''0'')')
--==
--SELECT @order_by,1
--==

				/* GENERACIÓN DE LOS INNER JOIN QUE ATIENDEN AL CAMPO RECIÉN GENERADO */
				SET @lInnerJoinDynamic = @lInnerJoinDynamic +
					'	LEFT JOIN #tmpItemSelection								AS '+@lalias+'2
							WITH (NOLOCK)	ON	'+@lalias+'2.comp_id	= '+@str_comp_id+'
								AND '+@lalias+'2.bra_id		= '+@str_bra_id+'
								AND '+@lalias+'2.prof_id	= '+@str_prof_id+'
								AND '+@lalias+'2.prli_id	= '+CONVERT(VARCHAR,@lprli_id)+'
								AND '+@lalias+'2.is_id		= '+CONVERT(VARCHAR,@lis_id)+'
						LEFT JOIN vwPriceListItems								AS '+@lalias+'1
							WITH (NOLOCK)	ON	'+@lalias+'1.comp_id	= '+@str_comp_id+'
								AND '+@lalias+'1.item_id	= ii.item_id
								AND '+@lalias+'1.prli_id	= '+@lalias+'2.prli_id
						LEFT JOIN #tmpTaxes										AS '+@lalias+'3
							WITH (NOLOCK)	ON	'+@lalias+'3.comp_id	= '+@str_comp_id+'
								AND '+@lalias+'3.item_id	= ii.item_id
						LEFT JOIN tbSysCurrency									AS '+@lalias+'4
						ON  '+@lalias+'4.curr_id	= '+@lalias+'1.curr_id '


--								AND ('+@lalias+'1.bra_id is NULL OR '+@lalias+'1.bra_id = ' + CONVERT(NVARCHAR(10),@bra_id) + ')


			END

		ELSE IF NOT @lprli_id IS NULL AND @curr_id4PriceOrCost IS NOT NULL
			-- Si lo muestro en una moneda DIFERENTE a la de la lista de precios.
			BEGIN

				/* GENERACIÓN DEL CÓDIGO PARA OBTENER LAS FILAS RELACIONADAS A LISTAS DE PRECIOS */


				/* OBTENCIÓN DEL NOMBRE DE LA LISTA DE PRECIOS */
				--SELECT @lname = tpl.prli_desc FROM tbPriceList tpl WHERE tpl.comp_id = @comp_id	AND tpl.prli_id = @lprli_id


				/* GENERACIÓN DE CAMPO DE LA LISTA DE PRECIOS */
				SET @lFieldsDynamictmp = @lFieldsDynamictmp +
								',  CONVERT(VARCHAR,CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+'),
								ISNULL(
										dbo.fnGetExchange2(' + @str_comp_id  + ','+@lalias+'1.prli_price,'+@lalias+'1.curr_id,'+ CONVERT(NVARCHAR(10),@curr_id4PriceOrCost) + ',0,0,0,0)
										' + ' *
										CASE
											WHEN '+@lalias+'2.is_prli_plusIVATaxCombo   = ''true'' THEN (1+(   dbo.fnGetPriceListItemTaxesPercentage4Combo( ' + @lalias+'1.comp_id,' + @str_bra_id + ',' + @lalias+'1.item_id,' + @lalias+'1.prli_id)                                                    /100.00))
											WHEN '+@lalias+'2.is_prli_plusIVATax		= ''true'' THEN (1+('+@lalias+'3.tax_percentage/100.00))
											WHEN '+@lalias+'2.is_prli_plusIITax4Neto	= ''true'' THEN (1+('+@lalias+'3.tax_percentageII/100.00))
											ELSE 1
										END,0))) + '' '' + LTRIM(RTRIM('''+ @curr_Symbol4PriceOrCost +'''))   ['+@lname+@lplusIVATax+@ltoClipboard+']'

--==
--SELECT @lFieldsDynamic
--==
				--el campo también se carga en la variable del select final
				SET @lSelectPaging = @lSelectPaging + ' ['+@lname+@lplusIVATax+@ltoClipboard+'] ,'


				----si el campo está solicitado para ordenamiento se reemplaza por el valor correspondiente ya que el ordenamiento dentro del ROW_NUMBER no acepta los alias externos
				--IF  CHARINDEX('['+@lname+@lplusIVATax+@ltoClipboard+']', @order_by) > 0
				--	SET @order_by = REPLACE(@order_by,
				--							'['+@lname+@lplusIVATax+@ltoClipboard+']',
				--							'LTRIM(RTRIM('+@lalias+'4.curr_symbol)) + '' '' + dbo.fnStrPADL(dbo.fnStrAllTrim(CONVERT(VARCHAR,CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+'), ISNULL('+@lalias+'1.prli_price *	CASE WHEN '+@lalias+'2.is_prli_plusIVATax = ''true'' THEN (1+('+@lalias+'3.tax_percentage/100.00)) ELSE 1 END,0))) ), 25,''0'')')


				/* GENERACIÓN DE LOS INNER JOIN QUE ATIENDEN AL CAMPO RECIÉN GENERADO */
				SET @lInnerJoinDynamic = @lInnerJoinDynamic +
					'	LEFT JOIN #tmpItemSelection								AS '+@lalias+'2
					WITH (NOLOCK)	ON	'+@lalias+'2.comp_id	= '+@str_comp_id+'
						AND '+@lalias+'2.bra_id		= '+@str_bra_id+'
						AND '+@lalias+'2.prof_id	= '+@str_prof_id+'
						AND '+@lalias+'2.prli_id	= '+CONVERT(VARCHAR,@lprli_id)+'
						AND '+@lalias+'2.is_id		= '+CONVERT(VARCHAR,@lis_id)+'
						LEFT JOIN vwPriceListItems								AS '+@lalias+'1
					WITH (NOLOCK)	ON	'+@lalias+'1.comp_id	= '+@str_comp_id+'
						AND '+@lalias+'1.item_id	= ii.item_id
						AND '+@lalias+'1.prli_id	= '+@lalias+'2.prli_id
						LEFT JOIN #tmpTaxes										AS '+@lalias+'3
					WITH (NOLOCK)	ON	'+@lalias+'3.comp_id	= '+@str_comp_id+'
						AND '+@lalias+'3.item_id	= ii.item_id
						LEFT JOIN tbSysCurrency									AS '+@lalias+'4
						ON  '+@lalias+'4.curr_id	= '+@lalias+'1.curr_id '


			END

		ELSE
			IF NOT @lstor_id IS NULL
				BEGIN

					/* GENERACIÓN DEL CÓDIGO PARA OBTENER LAS FILAS RELACIONADAS A DEPÓSITOS */


					/* OBTENCIÓN DEL NOMBRE DEL DEPÓSITO */
					-- x MOS SELECT @lname = ts.stor_desc FROM tbStorage ts WHERE ts.comp_id = @comp_id AND ts.stor_id = @lstor_id


					IF @bitNoShowStorageGroup = 'False'
						BEGIN

							if @bitPhisicalStock = 'True'
								BEGIN

									/* GENERACIÓN DE CAMPO DEL DEPÓSITO */
									SET @lFieldsDynamictmp = @lFieldsDynamictmp +
															', CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+
																		'), dbo.fnGetStockOfStorageGroup('+@str_comp_id+','+@lalias+'.stor_id'+','+'ii.item_id)) ['+@lname+@ltoClipboard+'] ' -- Ref: #1


									--el campo también se carga en la variable del select final
									SET @lSelectPaging = @lSelectPaging + ' ['+@lname+@ltoClipboard+'] ,'


									----si el campo está solicitado para ordenamiento se reemplaza por el valor correspondiente ya que el ordenamiento dentro del ROW_NUMBER no acepta los alias externos
									--IF  CHARINDEX('['+@lname+@ltoClipboard+']', @order_by) > 0
									--	SET @order_by = REPLACE(@order_by,'['+@lname+@ltoClipboard+']',
									--						'CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+
									--									'), dbo.fnGetStockOfStorageGroup('+@str_comp_id+','+@lalias+'.stor_id'+','+'ii.item_id))') -- Ref: #1


								END
							ELSE
								BEGIN

									/* GENERACIÓN DE CAMPO DEL DEPÓSITO */
									SET @lFieldsDynamictmp = @lFieldsDynamictmp +
															', CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+
																		'), dbo.fnGetAStock4MaxAssociation('+@str_comp_id+','+@lalias+'.stor_id'+','+'ii.item_id,9999999999)) ['+@lname+@ltoClipboard+'] ' -- Ref: #1


									--el campo también se carga en la variable del select final
									SET @lSelectPaging = @lSelectPaging + ' ['+@lname+@ltoClipboard+'] ,'


									----si el campo está solicitado para ordenamiento se reemplaza por el valor correspondiente ya que el ordenamiento dentro del ROW_NUMBER no acepta los alias externos
									--IF  CHARINDEX('['+@lname+@ltoClipboard+']', @order_by) > 0
									--	SET @order_by = REPLACE(@order_by,'['+@lname+@ltoClipboard+']',
									--						'CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+
									--									'), dbo.fnGetAStock4MaxAssociation('+@str_comp_id+','+@lalias+'.stor_id'+','+'ii.item_id,9999999999))') -- Ref: #1

								END

						END
					ELSE	-- Si SOLO muerstra el stock de su deposito y no del grupo . . .
						BEGIN


							if @bitPhisicalStock = 'True'
								BEGIN

									/* GENERACIÓN DE CAMPO DEL DEPÓSITO */
									SET @lFieldsDynamictmp = @lFieldsDynamictmp +
															', CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+
																		'), dbo.fnGetStockOfStorageGroup('+@str_comp_id+','+@lalias+'.stor_id'+','+'-ii.item_id)) ['+@lname+@ltoClipboard+'] ' -- Ref: #1


									--el campo también se carga en la variable del select final
									SET @lSelectPaging = @lSelectPaging + ' ['+@lname+@ltoClipboard+'] ,'


									--si el campo está solicitado para ordenamiento se reemplaza por el valor correspondiente ya que el ordenamiento dentro del ROW_NUMBER no acepta los alias externos
									--IF  CHARINDEX('['+@lname+@ltoClipboard+']', @order_by) > 0
									--	SET @order_by = REPLACE(@order_by,'['+@lname+@ltoClipboard+']',
									--						'CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+
									--									'), dbo.fnGetStockOfStorageGroup('+@str_comp_id+','+@lalias+'.stor_id'+','+'-ii.item_id))') -- Ref: #1


								END
							ELSE
								BEGIN

									/* GENERACIÓN DE CAMPO DEL DEPÓSITO */
									SET @lFieldsDynamictmp = @lFieldsDynamictmp +
															', CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+
																		'), dbo.fnGetAStock4MaxAssociation('+@str_comp_id+','+@lalias+'.stor_id'+','+'-ii.item_id,9999999999)) ['+@lname+@ltoClipboard+'] ' -- Ref: #1


									--el campo también se carga en la variable del select final
									SET @lSelectPaging = @lSelectPaging + ' ['+@lname+@ltoClipboard+'] ,'


									--si el campo está solicitado para ordenamiento se reemplaza por el valor correspondiente ya que el ordenamiento dentro del ROW_NUMBER no acepta los alias externos
									--IF  CHARINDEX('['+@lname+@ltoClipboard+']', @order_by) > 0
									--	SET @order_by = REPLACE(@order_by,'['+@lname+@ltoClipboard+']',
									--						'CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+
									--									'), dbo.fnGetAStock4MaxAssociation('+@str_comp_id+','+@lalias+'.stor_id'+','+'-ii.item_id,9999999999))') -- Ref: #1

								END

						END





					/* GENERACIÓN DE LOS INNER JOIN QUE ATIENDEN AL CAMPO RECIÉN GENERADO */
					SET @lInnerJoinDynamic = @lInnerJoinDynamic +
						'	LEFT JOIN #tmpItemSelection								as '+@lalias+'
						WITH (NOLOCK)	ON	'+@lalias+'.comp_id	= '+@str_comp_id+'
							AND	'+@lalias+'.bra_id	= '+@str_bra_id+'
							AND '+@lalias+'.prof_id = '+@str_prof_id+'
							AND '+@lalias+'.stor_id = '+CONVERT(VARCHAR,@lstor_id)+'
							AND '+@lalias+'.is_id	= '+CONVERT(VARCHAR,@lis_id)

				END
			ELSE

				IF NOT @lcoslis_id IS NULL
				BEGIN

					/* GENERACIÓN DEL CÓDIGO PARA OBTENER LAS FILAS RELACIONADAS A LISTAS DE COSTOS */


					/* OBTENCIÓN DEL NOMBRE DE LA LISTA DE COSTOS */
					-- x MOS SELECT @lname = ticln.coslis_desc FROM tbItemCostListName ticln	WHERE ticln.comp_id = @comp_id	AND ticln.coslis_id = @lcoslis_id


					/* GENERACIÓN DE CAMPO DE LA LISTA DE COSTOS */
					IF @lcoslis_aw='True'
						BEGIN

							SET @lFieldsDynamictmp = @lFieldsDynamictmp +
								',  CONVERT(VARCHAR,CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+'), ISNULL('+@lalias+'1.coslis_price_aw *
														CASE
															WHEN '+@lalias+'2.is_prli_plusIVATaxCombo   = ''true'' THEN (1+(   dbo.fnGetCostListItemTaxesPercentage4Combo( ' + @lalias+'1.comp_id,' + @str_bra_id + ',' + @lalias+'1.item_id,' + @lalias+'1.coslis_id)                                                    /100.00))
															WHEN '+@lalias+'2.is_prli_plusIVATax		= ''true''	THEN (1+('+@lalias+'3.tax_percentage/100.00))
															WHEN '+@lalias+'2.is_prli_plusIITax4Neto	= ''true''  THEN (1+('+@lalias+'3.tax_percentageII/100.00))
															ELSE 1
														END,0))) + '' '' +  LTRIM(RTRIM('+@lalias+'4.curr_symbol)) ['+@lname+@lplusIVATax+@ltoClipboard+']'


							--si el campo está solicitado para ordenamiento se reemplaza por el valor correspondiente ya que el ordenamiento dentro del ROW_NUMBER no acepta los alias externos
							--IF  CHARINDEX('['+@lname+@lplusIVATax+@ltoClipboard+']', @order_by) > 0
							--	SET @order_by = REPLACE(@order_by,  --MOS
							--						    '['+@lname+@lplusIVATax+@ltoClipboard+']',
							--							'LTRIM(RTRIM('+@lalias+'4.curr_symbol)) + '' '' + dbo.fnStrPADL(dbo.fnStrAllTrim(CONVERT(VARCHAR,CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+'), ISNULL('+@lalias+'1.coslis_price_aw *
							--								CASE WHEN '+@lalias+'2.is_prli_plusIVATax = ''true''
							--								THEN (1+('+@lalias+'3.tax_percentage/100.00))
							--								ELSE 1 END,0)))), 25,''0'')')

						END
					ELSE
						BEGIN

							SET @lFieldsDynamictmp = @lFieldsDynamictmp +
								',  CONVERT(VARCHAR,CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+'), ISNULL('+@lalias+'1.coslis_price *
														CASE
															WHEN '+@lalias+'2.is_prli_plusIVATaxCombo   = ''true'' THEN (1+(   dbo.fnGetCostListItemTaxesPercentage4Combo( ' + @lalias+'1.comp_id,' + @str_bra_id + ',' + @lalias+'1.item_id,' + @lalias+'1.coslis_id)                                                    /100.00))
															WHEN '+@lalias+'2.is_prli_plusIVATax		= ''true''	THEN (1+('+@lalias+'3.tax_percentage/100.00))
															WHEN '+@lalias+'2.is_prli_plusIITax4Neto	= ''true''	THEN (1+('+@lalias+'3.tax_percentageII/100.00))
															ELSE 1
														END,0))) + '' '' + LTRIM(RTRIM('+@lalias+'4.curr_symbol))  ['+@lname+@lplusIVATax+@ltoClipboard+']'


							--si el campo está solicitado para ordenamiento se reemplaza por el valor correspondiente ya que el ordenamiento dentro del ROW_NUMBER no acepta los alias externos
							--IF  CHARINDEX('['+@lname+@lplusIVATax+@ltoClipboard+']', @order_by) > 0
							--	SET @order_by = REPLACE(@order_by,	-- MOS
							--							'['+@lname+@lplusIVATax+@ltoClipboard+']',
							--							'LTRIM(RTRIM('+@lalias+'4.curr_symbol)) + '' '' + dbo.fnStrPADL(dbo.fnStrAllTrim(CONVERT(VARCHAR,CONVERT(DECIMAL(18,'+convert(varchar,@lis_decimalPlaces)+'), ISNULL('+@lalias+'1.coslis_price *
							--								CASE WHEN '+@lalias+'2.is_prli_plusIVATax = ''true''
							--											THEN (1+('+@lalias+'3.tax_percentage/100.00))
							--									ELSE 1 END,0)))), 25,''0'')')


						END


					--el campo también se carga en la variable del select final
					SET @lSelectPaging = @lSelectPaging + ' ['+@lname+@lplusIVATax+@ltoClipboard+'] ,'


					/* GENERACIÓN DE LOS INNER JOIN QUE ATIENDEN AL CAMPO RECIÉN GENERADO */
					SET @lInnerJoinDynamic = @lInnerJoinDynamic +
						'	LEFT JOIN #tmpItemSelection										AS '+@lalias+'2
						WITH (NOLOCK)	ON	'+@lalias+'2.comp_id	= '+@str_comp_id+'
							AND '+@lalias+'2.bra_id		= '+@str_bra_id+'
							AND '+@lalias+'2.prof_id	= '+@str_prof_id+'
							AND '+@lalias+'2.coslis_id  = '+CONVERT(VARCHAR,@lcoslis_id)+'
							AND '+@lalias+'2.is_id		= '+CONVERT(VARCHAR,@lis_id)+'
							LEFT JOIN vwItemCostList										AS '+@lalias+'1
						WITH (NOLOCK)	ON	'+@lalias+'1.comp_id	= '+@str_comp_id+'
							AND '+@lalias+'1.item_id	= ii.item_id
							AND '+@lalias+'1.coslis_id	= '+@lalias+'2.coslis_id
							LEFT JOIN #tmpTaxes												AS '+@lalias+'3
						WITH (NOLOCK)	ON	'+@lalias+'3.comp_id	= '+@str_comp_id+'
							AND '+@lalias+'3.item_id	= ii.item_id
							LEFT JOIN tbSysCurrency											AS '+@lalias+'4
							ON  '+@lalias+'4.curr_id	= '+@lalias+'1.curr_id '

				END



		--select para obtener el próximo is_id que se deberá mostrar en el resultado de la consulta
--		SELECT	@is_id = min(tis.is_id)
--		FROM	#tmpItemSelection tis
--		WHERE	tis.comp_id	= @comp_id
--		AND		tis.bra_id	= @bra_id
--		AND		tis.prof_id	= @prof_id
--		AND		tis.is_id	> @is_id

		SELECT	@order = MIN(((isnull(tis.is_order,0)+1) * 1000000) + tis.is_id)
			FROM	#tmpItemSelection tis
			WHERE	tis.comp_id	= @comp_id
			AND		tis.bra_id	= @bra_id
			AND		tis.prof_id	= @prof_id
			AND		(((tis.is_order+1) * 1000000) + tis.is_id) > @order

		SELECT @is_id = @order%1000000



		IF  LEN(@lFieldsDynamic1) < 7000
			BEGIN
				SET @lFieldsDynamic1	= @lFieldsDynamic1 + @lFieldsDynamictmp
			END
		ELSE IF  LEN(@lFieldsDynamic2) < 7000
			BEGIN
				SET @lFieldsDynamic2	= @lFieldsDynamic2 + @lFieldsDynamictmp
			END
		ELSE IF  LEN(@lFieldsDynamic3) < 7000
			BEGIN
				SET @lFieldsDynamic3	= @lFieldsDynamic3 + @lFieldsDynamictmp
			END
		ELSE IF  LEN(@lFieldsDynamic4) < 7000
			BEGIN
				SET @lFieldsDynamic4	= @lFieldsDynamic4 + @lFieldsDynamictmp
			END


		SET @lFieldsDynamictmp	= ''

	END




	SELECT @lFromFixed =	' FROM tbItem ii WITH (NOLOCK)' +
							--' LEFT  JOIN #tbItemEAN tie			    	            ON tie.item_id	= ii.item_id  ' +
							' INNER JOIN #tmpItemFinalSearch tfs ON tfs.item_id = ii.item_id ' +
							' INNER JOIN tbBrand        tbr			WITH (NOLOCK) ON tbr.comp_id = ii.comp_id   AND tbr.brand_id = ii.brand_id' +
							' INNER JOIN tbCategory	    cc			WITH (NOLOCK) ON cc.comp_id	 = ii.comp_id	AND cc.cat_id	 = ii.cat_id ' +
							' INNER JOIN tbSubCategory	sc			WITH (NOLOCK) ON sc.comp_id	 = ii.comp_id	AND sc.cat_id	 = ii.cat_id	  AND sc.subcat_id = ii.subcat_id ' +
							--' INNER JOIN #tmpItemClass  tic							ON tic.ic_id    = ii.ic_id OR ii.ic_id IS NULL ' +

							/*Deberia ser con la VISTA*/
							--' LEFT  JOIN tbItemTaxes ttax			WITH (NOLOCK)	ON ttax.comp_id = ii.comp_id	and ttax.item_id	= ii.item_id  and ttax.tax_itemComposed = 0 ' +
							' LEFT  JOIN vwItemTaxesOnlyOneIvaTax ttax			WITH (NOLOCK)	ON ttax.comp_id = ii.comp_id	and ttax.item_id	= ii.item_id   ' +
							' LEFT  JOIN tbTaxName ttn				WITH (NOLOCK)	ON ttn.tax_id	= ttax.tax_id	and ttn.tax_class	= 1  '


	SELECT @lWhereFixed	=	' WHERE ii.comp_id='+@str_comp_id+
						--	' AND (ii.bra_id='+@str_bra_id+' or ii.bra_id is Null)' +
							--' AND (ii.item_code like ''%'+ @Item_code + '%'' or ii.item_vendorCode like ''%'+ @Item_code + '%'' or ii.item_codeAlternative like ''%'+ @Item_code + '%''		)  ' +
						--	' AND ( tie.item_id is not NULL or ii.item_code like ''%'+ @Item_code + '%'' or ii.item_vendorCode like ''%'+ @Item_code + '%'' or ii.item_codeAlternative like ''%'+ @Item_code + '%''		)  ' +
						--	' AND ii.item_desc like ''%'+ @Item_desc1 + '%''' +
						--	' AND ii.item_desc like ''%'+ @Item_desc2 + '%''' +
						--	' AND (cc.cat_id ='+CONVERT(VARCHAR,@cat_id)+' OR '+CONVERT(VARCHAR,@cat_id)+'= -1)' +
						--	' AND (sc.subcat_id	='+CONVERT(VARCHAR,@subcat_id)+' OR '+CONVERT(VARCHAR,@subcat_id)+'= -1)' +
						--	' AND (ii.brand_id ='+CONVERT(VARCHAR,@brand_id)+' OR '+CONVERT(VARCHAR,@brand_id)+'= -1)' +
						--	' AND (ii.supp_id ='+CONVERT(VARCHAR,@supp_id)+' OR '+CONVERT(VARCHAR,@supp_id)+'= -1)' +
						--	' AND ('+convert(varchar,@not4Sale)+'= -1 OR ii.item_not4Sale <> '+CONVERT(VARCHAR,convert(bit,@not4Sale))+')' +

							--' AND (('+convert(varchar,@option2)+'= -1 ) OR ' +
							--	  '('+convert(varchar,@option2)+'= 0 and ii.item_vendorCode = ''' +@item_vendorCode+''') OR ' +
							--	  '('+convert(varchar,@option2)+'= 1 and ii.item_vendorCode like ''' +@item_vendorCode+'%'') OR ' +
							--	  '('+convert(varchar,@option2)+'= 2 and ii.item_vendorCode like ''%'+@item_vendorCode+'%'') OR ' +
							--	  '('+convert(varchar,@option2)+'= 3 and ii.item_vendorCode <> ''' +@item_vendorCode+''') OR ' +
							--	  '('+convert(varchar,@option2)+'= 4 and ii.item_vendorCode not like ''%'+@item_vendorCode+'%''))' +


							--' AND (('+CONVERT(VARCHAR,@checkstock)+' = 1 and dbo.fnGetStockOfStorageGroup('+@str_comp_id+','+@str_stor_id+',ii.item_id) > 0) or '+CONVERT(VARCHAR,@checkstock)+' = 0)' +


							--' AND (('+CONVERT(VARCHAR,@checkAvailable)+' = 1 and dbo.fnGetStockAvailable('+@str_comp_id+','+@str_stor_id+',ii.item_id) > 0) or '+CONVERT(VARCHAR,@checkAvailable)+' = 0)' +


							--' AND ii.item_disabled = ''false'' ' +





							-- OJO, si se vuelve a poner hacer arriba una temporal e incluir 1ro los que correspondan en la temporal...
							--' AND ( ' +
							--		'('+convert(varchar,@option)+' = 0  AND ii.item_id NOT IN (SELECT DISTINCT isnull(tiscr.item_id,-1)       FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = ii.comp_id)) OR ' +
							--		'('+convert(varchar,@option)+' = 1  AND ii.item_id NOT IN (SELECT DISTINCT isnull(tiscr.item_id_child,-1) FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = ii.comp_id)) OR ' +
							--		'('+convert(varchar,@option)+' = 2  AND ii.item_id     IN (SELECT DISTINCT isnull(tiscr.item_id,-1)       FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = ii.comp_id)) OR ' +
							--		'('+convert(varchar,@option)+' = -1)' +
							--	 ')' +

								--cada vez que se actualicen alguna de estas últimas opciones también hay que actualizarlas en
								--[spItem_getDataByCode], [spItem_getDataByFilters] y [spItem_getDataByText]
								--el parámetro @option indica si se deben recuperar o no, artículos	relacionados a size/color
								--@option = 0 - sólo artículos POSIBLES PADRES E HIJOS	- item_id not in tbItemSizeColor.item_id -wfmItemSizeColor
								--@option = 1 - sólo artículos PADRES Y POSIBLES PADRES - item_id not in tbItemSizeColor.item_id_child -wfmSaleOrderDetailSizeColor
								--@option = 2 - sólo artículos PADRES					- item_id     in tbItemSizeColor.item_id -las demás páginas
								--@option = 3 - todos los artículos




							')'





	-- ==============================================================================================================================
	--se realizan las últimac concatenaciones para armar todos los querys necesarios
	SET @lSelectPaging				= @lSelectPaging + '[cat_desc],[subcat_desc],[brand_desc],[tax_percentage],[ID] FROM resultado_total '

	SET @lRowNumberOrderDynamic		= ',ROW_NUMBER() OVER ( '+@order_by+' ) AS RowNumber '

	SET @lSelectDynamic				= substring(@lSelectDynamic,1,len(@lSelectDynamic)-1) --+ @lFieldsDynamic

	SET @lFromFixedJoinWhereDynamic = ',cc.cat_desc [cat_desc],sc.subcat_desc [subcat_desc],tbr.brand_desc [brand_desc],convert(decimal(5,2),ttn.tax_percentage) [tax_percentage],ii.item_id [ID] ' +
										/*@lRowNumberOrderDynamic +*/ @lFromFixed + @lInnerJoinDynamic + @lWhereFixed

	SET @lWhereFixedPaging			= ''
	                                  --' WHERE RowNumber BETWEEN '+ CONVERT(VARCHAR,(@page_size * @page_number + 1)) +
									  --					' AND '	 + CONVERT(VARCHAR,(@page_size * (@page_number + 1))) + ' Order By RowNumber'
	-- ==============================================================================================================================


	/*
	SELECT	@lSelectDynamic
	SELECT	@lFromFixedJoinWhereDynamic
	SELECT	@lSelectPaging
	SELECT	@lWhereFixedPaging
	*/
	-- SELECT (@lSelectDynamic + @lFromFixedJoinWhereDynamic + @lSelectPaging + @lWhereFixedPaging)






--SELECT @order_by
--SET @order_by = 'order by item_desc asc,  [Stk] ASC'

	-- ==============================================================================================================================
	--recuperación de los registros de la página solicitada
	EXEC   (@lSelectDynamic +
			@lFieldsDynamic1 +
			@lFieldsDynamic2 +
			@lFieldsDynamic3 +
			@lFieldsDynamic4 +
			@lFromFixedJoinWhereDynamic  +
			@lSelectPaging + ' ' + @order_by ) --  ' /*+ @lWhereFixedPaging*/)
	-- ==============================================================================================================================


	-- ==============================================================================================================================
	--recuperación de la cantidad total de registros de toda la consulta
	SELECT COUNT(*) FROM @tmpItemSearch2
	--EXEC   ('(select count(1) ' + @lFromFixed + @lWhereFixed)
	-- ==============================================================================================================================

	DROP TABLE #tmpItemSelection
	DROP TABLE #tmpItemFinalSearch
	DROP TABLE #tmpTaxes
	--drop table #tmpItemSearch

END TRY
BEGIN CATCH
	SELECT '0' [+], '0' [-], '0' [*], '0' [.], '0' [:], 'ERROR DE CONFIGURACION:' + CONVERT(NVARCHAR(10),ERROR_LINE()) + ' ' +  ERROR_MESSAGE()  [ERROR],
			'COMUNIQUESE CON EL ADMINISTRADOR DEL SISTEMA' [Mensaje], '0' [ ],'0' [ ]
	SELECT 1
	DROP TABLE #tmpItemSelection
	DROP TABLE #tmpItemFinalSearch
END CATCH

END
GO


CREATE  PROCEDURE [dbo].[spItem_getDataById]
(
	@comp_id		As Int,
	@item_id		As Int
)
AS

BEGIN

	set nocount ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-11-09
	-- Parte		: 677
	-- Description	: Por el agregado de nuevos campos item_disabled y item_dsabledInPriceList en la consulta de
	-- wfmCostPriceEdition.aspx se agrega el campo item_dsabledInPriceList en el select
	-- =================================================================================================================



-- --------------------------------------------------------
-- Testing
-- --------------------------------------------------------
	/*
	DECLARE @comp_id		INT,
			@item_id		int
	select	@comp_id		=1,
			@item_id		=229
	*/
-- --------------------------------------------------------

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	SELECT TOP 1
			i.comp_id,
			i.bra_id,
			isnull(b.bra_desc,'')								[bra_desc],
			i.item_code,
			i.item_id,
			isnull(i.item_desc,'')								[item_desc],
			isnull(i.item_detail,'')							[item_detail],
			ISNULL(i.item_vendorCode,'')						[item_vendorCode],
			i.cat_id,
			i.subcat_id,
			i.brand_id,
			i.pres_id,
			isnull(p.pres_desc,'')			pres_desc,
			i.curr_id,
			isnull(c.curr_desc,'')			curr_desc,
			ISNULL(i.item_upb,1)			item_upb,
			ISNULL(i.item_upp,1)			item_upp,
			i.item_cantMin,
			i.item_cantOpt,
			i.item_mult,
			i.item_commission,
			i.item_picture,
			ISNULL(i.item_guarantee,'')							[item_guarantee],
			ISNULL(i.item_expser,'false')						[item_expser],
			IsNull(i.item_made,'False')							[item_made],
			CONVERT(BIT,ISNULL(i.item_web,'false'))				[item_web],
			isnull(i.item_annotation,'')						[item_annotation],
			i.acc_count_id,
			isnull(i.item_newness,'false')						[item_newness],
			isnull(i.item_liquidation,'false')					[item_liquidation],
			isnull(i.item_withDecimal,'false')					[item_withDecimal],
			cli.coslis_price,
			cli.coslis_price_aw,
			i.item_qtyMin1,
			i.item_qtyMin2,
			i.item_qtyMin3,
			ttn.tax_id											ivaTax_Id,
			isnull(i.item_annotation1,'')						[item_annotation1],
			isnull(i.item_annotation2,'')						[item_annotation2],
			ISNULL(i.item_disabled,'false')						item_disabled,
			ISNULL(tc.cat_desc,'')								cat_desc,
			ISNULL(tsc.subcat_desc,'')							subcat_desc,
			ISNULL(tb.brand_desc,'')							brand_desc,
			ISNULL(i.item_disabledInPriceList,'false')			item_disabledInPriceList, -- Parte		: 677
			ISNULL(dbo.fnGetStock(@comp_id,-1,i.item_id),0)				    [item_Stock],			  -- Parte		: 740
			ISNULL(dbo.fnGetAStock(@comp_id,-1,i.item_id,NULL),999999999)	[item_PotStock],           -- Parte		: 740
			CASE
				WHEN ISNULL(i.item_purOrd_Disc1,0) = 0 AND ISNULL(ts.supp_purOrd_Disc1,0) <> 0	THEN	ts.supp_purOrd_Disc1
				WHEN ISNULL(i.item_purOrd_Disc1,0) <> 0											THEN	i.item_purOrd_Disc1
				ELSE																					0
			END																[item_purOrd_Disc1],
			CASE
				WHEN ISNULL(i.item_purOrd_Disc2,0) = 0 AND ISNULL(ts.supp_purOrd_Disc2,0) <> 0	THEN	ts.supp_purOrd_Disc2
				WHEN ISNULL(i.item_purOrd_Disc2,0) <> 0											THEN	i.item_purOrd_Disc2
				ELSE																					0
			END																[item_purOrd_Disc2],
			CASE
				WHEN ISNULL(i.item_purOrd_Disc3,0) = 0 AND ISNULL(ts.supp_purOrd_Disc3,0) <> 0	THEN	ts.supp_purOrd_Disc3
				WHEN ISNULL(i.item_purOrd_Disc3,0) <> 0											THEN	i.item_purOrd_Disc3
				ELSE																					0
			END																[item_purOrd_Disc3],
			CASE
				WHEN ISNULL(i.item_purOrd_Disc4,0) = 0 AND ISNULL(ts.supp_purOrd_Disc4,0) <> 0	THEN	ts.supp_purOrd_Disc4
				WHEN ISNULL(i.item_purOrd_Disc4,0) <> 0											THEN	i.item_purOrd_Disc4
				ELSE																					0
			END																[item_purOrd_Disc4],

			CASE
				WHEN ISNULL(i.item_purOrd_surcharge1,0) = 0 AND ISNULL(ts.supp_purOrd_surcharge1,0) <> 0	THEN	ts.supp_purOrd_surcharge1
				WHEN ISNULL(i.item_purOrd_surcharge1,0) <> 0												THEN	i.item_purOrd_surcharge1
				ELSE																					0
			END																[item_purOrd_surcharge1],
			CASE
				WHEN ISNULL(i.item_purOrd_surcharge2,0) = 0 AND ISNULL(ts.supp_purOrd_surcharge2,0) <> 0	THEN	ts.supp_purOrd_surcharge2
				WHEN ISNULL(i.item_purOrd_surcharge2,0) <> 0												THEN	i.item_purOrd_surcharge2
				ELSE																					0
			END																[item_purOrd_surcharge2],
			CASE
				WHEN ISNULL(i.item_purOrd_surcharge3,0) = 0 AND ISNULL(ts.supp_purOrd_surcharge3,0) <> 0	THEN	ts.supp_purOrd_surcharge3
				WHEN ISNULL(i.item_purOrd_surcharge3,0) <> 0												THEN	i.item_purOrd_surcharge3
				ELSE																					0
			END																[item_purOrd_surcharge3],
			CASE
				WHEN ISNULL(i.item_purOrd_surcharge4,0) = 0 AND ISNULL(ts.supp_purOrd_surcharge4,0) <> 0	THEN	ts.supp_purOrd_surcharge4
				WHEN ISNULL(i.item_purOrd_surcharge4,0) <> 0												THEN	i.item_purOrd_surcharge4
				ELSE																					0
			END																[item_purOrd_surcharge4],


			ISNULL(i.item_WebSite_vendorPage,'')							[item_WebSite_vendorPage],
			ISNULL(i.item_WebSite_vendorDrivers,'')							[item_WebSite_vendorDrivers],
			ISNULL(i.item_WebSite_desc,'')									[item_WebSite_desc],
			isnull(i.item_disabledInBalance,'false')						[item_disabledInBalance],
			ISNULL(i.item_expean,'false')									[item_expean],
			ISNULL(i.item_outlet,'false')									[item_outlet],
			ISNULL(i.item_WebSite_url4Image1,'')							[item_WebSite_url4Image1],
			ISNULL(i.item_WebSite_url4Image2,'')							[item_WebSite_url4Image2],
			ISNULL(i.item_WebSite_url4Image3,'')							[item_WebSite_url4Image3],
			ISNULL(i.item_WebSite_url4Image4,'')							[item_WebSite_url4Image4],
			ISNULL(i.item_WebSite_url4Image5,'')							[item_WebSite_url4Image5],
			isnull(i.itemAtrb1_id,'-1')										[itemAtrb1_id],
			isnull(i.itemAtrb2_id,'-1')										[itemAtrb2_id],
			isnull(i.itemAtrb3_id,'-1')										[itemAtrb3_id],
			isnull(i.itemAtrb4_id,'-1')										[itemAtrb4_id],
			isnull(i.item_ChkAtrb1,'False')									[item_ChkAtrb1],
			isnull(i.item_ChkAtrb2,'False')									[item_ChkAtrb2],
			isnull(i.item_ChkAtrb3,'False')									[item_ChkAtrb3],
			isnull(i.item_ChkAtrb4,'False')									[item_ChkAtrb4],
			ISNULL(i.item_assemblyType,2)									[item_assemblyType]	,	-- 0 = Se ensambla en el Domicilio // 1 = Se ensambla en Taller // 2 = No requiere ensamblado
			isnull(i.creditReplaceInterest,'False')							[creditReplaceInterest],
			isnull(i.creditI_up2Pays,0)										[creditI_up2Pays],
			isnull(i.creditI_creditInterest,0)								[creditI_creditInterest],
			isnull(i.creditII_up2Pays,0)									[creditII_up2Pays],
			isnull(i.creditII_creditInterest,0)								[creditII_creditInterest],
			isnull(i.creditIII_up2Pays,0)									[creditIII_up2Pays],
			isnull(i.creditIII_creditInterest,0)							[creditIII_creditInterest],
			isnull(i.creditIV_up2Pays, 0)									[creditIV_up2Pays],
			isnull(i.creditIV_creditInterest,0)								[creditIV_creditInterest],
			isnull(i.creditOther_creditInterest,0)							[creditOther_creditInterest],
			IsNull(i.sdlmt_id,0)											[sdlmt_id],
			i.stor_id,
			Isnull(i.CreditQuotaQtyMaximum,0)								[CreditQuotaQtyMaximum],
			isnull(i.item_isEW,'False')										[item_isEW],
			ISNULL(i.item_discountByItem,0)									[item_discountByItem],
			ISNULL(tsca.subcataux_desc,'')									[subcataux_desc],
			ISNULL(i.item_RMACloneItemInAdditionalPartsOnInsert,'False')	[item_RMACloneItemInAdditionalPartsOnInsert],
			ISNULL(i.item_ML_isAvailable,'False')							[item_ML_isAvailable],
			ISNULL(i.item_ML_desc,'')										[item_ML_desc],
			ISNULL(i.item_ML_html4Publication,'')							[item_ML_html4Publication],
			ISNULL(i.item_ML_url4video,'')									[item_ML_url4video],
			ISNULL(i.item_ML_title,'')										[item_ML_title],
			item_imageChecksum,
			ISNULL(i.item_pcConfigMode_AllowMainItemUpdate,'False')			[item_pcConfigMode_AllowMainItemUpdate],
			i.posara_id,
			ISNULL(i.item_isForAssociation,'False')							[item_isForAssociation],
			ISNULL(i.item_ifHasItemAssociationSumPrices,'False')			[item_ifHasItemAssociationSumPrices],
			ISNULL(I.item_discountByItem2,0)								[item_discountByItem2]

	FROM 	dbo.tbItem										i			WITH (NOLOCK)

			left join dbo.tbPresentation					p			WITH (NOLOCK)
			on		p.comp_id			=	i.comp_id
			and		p.pres_id			=	i.pres_id

			left join dbo.tbBranch							b			WITH (NOLOCK)
			on		b.comp_id			=	i.comp_id
			and		b.bra_id			=	i.bra_id

			left join dbo.tbsysCurrency						c			WITH (NOLOCK)
			on		c.curr_id			=	i.curr_id

			left join dbo.tbItemCostList					cli			WITH (NOLOCK)
			on		cli.comp_id			=	i.comp_id
			and		cli.item_id			=	i.item_id

			left Join tbItemTaxes							tit			WITH (NOLOCK)
			On		tit.comp_id			=	i.comp_id
			And		tit.item_id			=	i.item_id

			left Join tbTaxName								ttn			WITH (NOLOCK)
			On		ttn.comp_id			=	i.comp_id
			And		ttn.tax_id			=	tit.tax_id

			left Join dbo.vwsysTaxClassIVA_Taxes			stit		WITH (NOLOCK)
			On		stit.tax_class		=	ttn.tax_class

			LEFT JOIN tbCategory							tc			WITH (NOLOCK)
			ON		tc.comp_id			=	i.comp_id
			AND		tc.cat_id			=	i.cat_id

			LEFT JOIN tbSubCategory							tsc			WITH (NOLOCK)
			ON		tsc.comp_id			=	i.comp_id
			AND		tsc.cat_id			=	i.cat_id
			AND		tsc.subcat_id		=	i.subcat_id

			LEFT JOIN tbSubCategoryAux						tsca		WITH (NOLOCK)
			ON		tsca.comp_id		= i.comp_id
			AND		tsca.subcataux_id	= i.subcataux_id

			LEFT JOIN tbBrand								tb			WITH (NOLOCK)
			ON		tb.comp_id			=	i.comp_id
			AND		tb.bra_id			=	i.bra_id

			LEFT JOIN tbSupplier ts										WITH (NOLOCK)
				ON	ts.comp_id = i.comp_id AND
					ts.supp_id = i.supp_id


	WHERE 	i.comp_id		=	@comp_id
	AND 	i.item_id		=	@item_id



END
GO



CREATE  PROCEDURE [dbo].[spItem_getDataById2]
(
