	DECLARE @intStorId				AS INT
	DECLARE @intStorId4LastPurchase AS INT
	set		@intStorId				= -1
	set		@intStorId4LastPurchase	= -1


	IF @item_id < 0
		BEGIN
			SET @bitInformLastPurchase = 'True'
			SET @item_id = @item_id * -1
		END

	--IF @bitInformLastPurchase = 'True'
	--	BEGIN
	--		SELECT  @intStorId				= tc.stor_id,
	--				@intStorId4LastPurchase = tc.stor_id4LastPurchase
