	-- WHERE tit.comp_id = @comp_id AND
	-- tit.item_id = @item_id AND
	-- tit.bra_id = @bra_id  AND
	-- --tit.stor_id = @intStorId4LastPurchase AND
	-- (tct.sd_id = 101 OR tct.sd_id = 102)
	-- ORDER BY tit.it_transaction DESC
	-- END
	-- END








	--==
	--select @intStorId4LastPurchase
	--==






	SELECT TOP 1
	i.comp_id,
	i.bra_id,
	isnull(b.bra_desc,'') [bra_desc],
	i.item_code,
	i.item_id,
	isnull(i.item_desc,'') [item_desc],
	isnull(i.item_detail,'') [item_detail],
	ISNULL(i.item_vendorCode,'') [item_vendorCode],
	i.cat_id,
	i.subcat_id,
	i.brand_id,
	i.pres_id,
	isnull(p.pres_desc,'') pres_desc,
	i.curr_id,
	isnull(c.curr_desc,'') curr_desc,
	i.item_upb,
	i.item_upp,
	i.item_cantMin,
	i.item_cantOpt,
	i.item_mult,
	i.item_commission,
	i.item_picture,
	ISNULL(i.item_guarantee,'') [item_guarantee],
	ISNULL(i.item_expser,'false') [item_expser],
	IsNull(i.item_made,'False') [item_made],
	CONVERT(BIT,ISNULL(i.item_web,'false')) [item_web],
	isnull(i.item_annotation,'') [item_annotation],
	i.acc_count_id,
	isnull(i.item_newness,'false') [item_newness],
	isnull(i.item_liquidation,'false') [item_liquidation],
	isnull(i.item_withDecimal,'false') [item_withDecimal],
	cli.coslis_price,
	cli.coslis_price_aw,
	i.item_qtyMin1,
	i.item_qtyMin2,
	i.item_qtyMin3,
	ttn.tax_id ivaTax_Id,
	isnull(i.item_annotation1,'') [item_annotation1],
	isnull(i.item_annotation2,'') [item_annotation2],
	ISNULL(i.item_disabled,'false') item_disabled,
	ISNULL(tc.cat_desc,'') cat_desc,
	ISNULL(tsc.subcat_desc,'') subcat_desc,
	ISNULL(tb.brand_desc,'') brand_desc,
	ISNULL(i.item_disabledInPriceList,'false') item_disabledInPriceList, -- Parte : 677
	ISNULL(dbo.fnGetStockOfStorageGroup(@comp_id,@intStorId,i.item_id),0)     [item_Stock],   -- Parte : 740
	ISNULL(dbo.fnGetAStock(@comp_id,@intStorId,i.item_id, 999999999),99999999) [item_PotStock],           -- Parte : 740

	CASE
		WHEN ISNULL(i.item_purOrd_Disc1,0) = 0 AND ISNULL(ts.supp_purOrd_Disc1,0) <> 0 THEN ts.supp_purOrd_Disc1
		WHEN ISNULL(i.item_purOrd_Disc1,0) <> 0 THEN i.item_purOrd_Disc1
		ELSE 0
	END [item_purOrd_Disc1],
	CASE
		WHEN ISNULL(i.item_purOrd_Disc2,0) = 0 AND ISNULL(ts.supp_purOrd_Disc2,0) <> 0 THEN ts.supp_purOrd_Disc2
		WHEN ISNULL(i.item_purOrd_Disc2,0) <> 0 THEN i.item_purOrd_Disc2
		ELSE 0
	END [item_purOrd_Disc2],
	CASE
		WHEN ISNULL(i.item_purOrd_Disc3,0) = 0 AND ISNULL(ts.supp_purOrd_Disc3,0) <> 0 THEN ts.supp_purOrd_Disc3
		WHEN ISNULL(i.item_purOrd_Disc3,0) <> 0 THEN i.item_purOrd_Disc3
		ELSE 0
	END [item_purOrd_Disc3],
	CASE
		WHEN ISNULL(i.item_purOrd_Disc4,0) = 0 AND ISNULL(ts.supp_purOrd_Disc4,0) <> 0 THEN ts.supp_purOrd_Disc4
		WHEN ISNULL(i.item_purOrd_Disc4,0) <> 0 THEN i.item_purOrd_Disc4
		ELSE 0
	END [item_purOrd_Disc4],

	CASE
		WHEN ISNULL(i.item_purOrd_surcharge1,0) = 0 AND ISNULL(ts.supp_purOrd_surcharge1,0) <> 0 THEN ts.supp_purOrd_surcharge1
		WHEN ISNULL(i.item_purOrd_surcharge1,0) <> 0 THEN i.item_purOrd_surcharge1
		ELSE 0
	END [item_purOrd_surcharge1],
	CASE
		WHEN ISNULL(i.item_purOrd_surcharge2,0) = 0 AND ISNULL(ts.supp_purOrd_surcharge2,0) <> 0 THEN ts.supp_purOrd_surcharge2
		WHEN ISNULL(i.item_purOrd_surcharge2,0) <> 0 THEN i.item_purOrd_surcharge2
		ELSE 0
	END [item_purOrd_surcharge2],
	CASE
		WHEN ISNULL(i.item_purOrd_surcharge3,0) = 0 AND ISNULL(ts.supp_purOrd_surcharge3,0) <> 0 THEN ts.supp_purOrd_surcharge3
		WHEN ISNULL(i.item_purOrd_surcharge3,0) <> 0 THEN i.item_purOrd_surcharge3
		ELSE 0
	END [item_purOrd_surcharge3],
	CASE
		WHEN ISNULL(i.item_purOrd_surcharge4,0) = 0 AND ISNULL(ts.supp_purOrd_surcharge4,0) <> 0 THEN ts.supp_purOrd_surcharge4
		WHEN ISNULL(i.item_purOrd_surcharge4,0) <> 0 THEN i.item_purOrd_surcharge4
		ELSE 0
	END [item_purOrd_surcharge4],

	ISNULL(i.item_WebSite_vendorPage,'') [item_WebSite_vendorPage],
	ISNULL(i.item_WebSite_vendorDrivers,'') [item_WebSite_vendorDrivers],
	ISNULL(i.item_WebSite_desc,'') [item_WebSite_desc],
	isnull(i.item_disabledInBalance,'false') [item_disabledInBalance],
	ISNULL(i.item_expean,'false') [item_expean],
	ISNULL(i.item_outlet,'false') [item_outlet],
	ISNULL(i.item_WebSite_url4Image1,'') [item_WebSite_url4Image1],
	ISNULL(i.item_WebSite_url4Image2,'') [item_WebSite_url4Image2],
	ISNULL(i.item_WebSite_url4Image3,'') [item_WebSite_url4Image3],
	ISNULL(i.item_WebSite_url4Image4,'') [item_WebSite_url4Image4],
	ISNULL(i.item_WebSite_url4Image5,'') [item_WebSite_url4Image5],
	isnull(i.itemAtrb1_id,'-1') [itemAtrb1_id],
	isnull(i.itemAtrb2_id,'-1') [itemAtrb2_id],
	isnull(i.itemAtrb3_id,'-1') [itemAtrb3_id],
	isnull(i.itemAtrb4_id,'-1') [itemAtrb4_id],
	isnull(i.item_ChkAtrb1,'False') [item_ChkAtrb1],
	isnull(i.item_ChkAtrb2,'False') [item_ChkAtrb2],
	isnull(i.item_ChkAtrb3,'False') [item_ChkAtrb3],
	isnull(i.item_ChkAtrb4,'False') [item_ChkAtrb4],
	ISNULL(i.item_assemblyType,2) [item_assemblyType] , -- 0 = Se ensambla en el Domicilio // 1 = Se ensambla en Taller // 2 = No requiere ensamblado
	isnull(i.creditReplaceInterest,'False') [creditReplaceInterest],
	isnull(i.creditI_up2Pays,0) [creditI_up2Pays],
	isnull(i.creditI_creditInterest,0) [creditI_creditInterest],
	isnull(i.creditII_up2Pays,0) [creditII_up2Pays],
	isnull(i.creditII_creditInterest,0) [creditII_creditInterest],
	isnull(i.creditIII_up2Pays,0) [creditIII_up2Pays],
	isnull(i.creditIII_creditInterest,0) [creditIII_creditInterest],
	isnull(i.creditIV_up2Pays, 0) [creditIV_up2Pays],
	isnull(i.creditIV_creditInterest,0) [creditIV_creditInterest],
	isnull(i.creditOther_creditInterest,0) [creditOther_creditInterest],
	IsNull(i.sdlmt_id,0) [sdlmt_id],
	i.stor_id,
	Isnull(i.CreditQuotaQtyMaximum,0) [CreditQuotaQtyMaximum],
	ISNULL(@strLastPurchase ,'') [lastPurchase],
	isnull(i.item_isEW,'False') [item_isEW],
	ISNULL(i.item_discountByItem,0) [item_discountByItem],
	ISNULL(tsca.subcataux_desc,'') [subcataux_desc],
	@intStorId4LastPurchase [intStorId4LastPurchase],
	ISNULL(i.item_ML_isAvailable,'False') [item_ML_isAvailable],
	ISNULL(i.item_ML_desc,'') [item_ML_desc],
	ISNULL(i.item_ML_html4Publication,'') [item_ML_html4Publication],
	ISNULL(i.item_ML_url4video,'') [item_ML_url4video],
	ISNULL(i.item_ML_title,'') [item_ML_title],
	item_imageChecksum,
	isnull(i.item_liquidationPlus,'false') [item_liquidationPlus],
	ISNULL(i.item_pcConfigMode_AllowMainItemUpdate,'False') [item_pcConfigMode_AllowMainItemUpdate],
	ISNULL(i.item_weight,0) [item_weight], --Peso
	ISNULL(i.item_large,0) [item_large], --Largo (Medida)
	ISNULL(i.item_higth,0) [item_higth], --Alto (Medida)
	ISNULL(i.item_wide,0) [item_wide], --Ancho (Medida)
	ISNULL(i.item_volume,0) [item_volume],
	dbo.fnStrAllTrim(ISNULL(i.MLPictureId1,'')) [MLPictureId1],
	dbo.fnStrAllTrim(ISNULL(i.MLPictureId2,'')) [MLPictureId2],
	dbo.fnStrAllTrim(ISNULL(i.MLPictureId3,'')) [MLPictureId3],
	dbo.fnStrAllTrim(ISNULL(i.MLPictureId4,'')) [MLPictureId4],
	dbo.fnStrAllTrim(ISNULL(i.MLPictureId5,'')) [MLPictureId5],
	dbo.fnStrAllTrim(ISNULL(i.MLPictureId6,'')) [MLPictureId6],
	dbo.fnStrAllTrim(ISNULL(i.MLPictureId7,'')) [MLPictureId7],
	dbo.fnStrAllTrim(ISNULL(i.MLPictureId8,'')) [MLPictureId8],
	dbo.fnStrAllTrim(ISNULL(i.MLPictureId9,'')) [MLPictureId9],
	dbo.fnStrAllTrim(ISNULL(i.MLPictureId10,'')) [MLPictureId10] ,
	ISNULL(i.item_WebSite_url4Image6,'') [item_WebSite_url4Image6],
	ISNULL(i.item_WebSite_url4Image7,'') [item_WebSite_url4Image7],
	ISNULL(i.item_WebSite_url4Image8,'') [item_WebSite_url4Image8],
	ISNULL(i.item_WebSite_url4Image9,'') [item_WebSite_url4Image9],
	ISNULL(i.item_WebSite_url4Image10,'') [item_WebSite_url4Image10] ,
	ISNULL(I.item_discountByItem2,0)								[item_discountByItem2]

		FROM  dbo.tbItem i WITH (NOLOCK)

		left join dbo.tbPresentation p WITH (NOLOCK)
		on p.comp_id = i.comp_id
		and p.pres_id = i.pres_id

		left join dbo.tbBranch b WITH (NOLOCK)
		on b.comp_id = i.comp_id
		and b.bra_id = i.bra_id

		left join dbo.tbsysCurrency c WITH (NOLOCK)
		on c.curr_id = i.curr_id

		left join dbo.tbItemCostList cli WITH (NOLOCK)
		on cli.comp_id = i.comp_id
		and cli.item_id = i.item_id

		left Join tbItemTaxes tit WITH (NOLOCK)
		On tit.comp_id = i.comp_id
		And tit.item_id = i.item_id

		left Join tbTaxName ttn WITH (NOLOCK)
		On ttn.comp_id = i.comp_id
		And ttn.tax_id = tit.tax_id

		left Join dbo.vwsysTaxClassIVA_Taxes stit WITH (NOLOCK)
		On stit.tax_class = ttn.tax_class

		LEFT JOIN tbCategory tc WITH (NOLOCK)
		ON tc.comp_id = i.comp_id
		AND tc.cat_id = i.cat_id

		LEFT JOIN tbSubCategory tsc WITH (NOLOCK)
		ON tsc.comp_id = i.comp_id
		AND tsc.cat_id = i.cat_id
		AND tsc.subcat_id = i.subcat_id

		LEFT JOIN tbSubCategoryAux tsca WITH (NOLOCK)
		ON tsca.comp_id = i.comp_id
		AND tsca.subcataux_id = i.subcataux_id

		LEFT JOIN tbBrand tb WITH (NOLOCK)
		ON tb.comp_id = i.comp_id
		AND tb.brand_id = i.brand_id

		LEFT JOIN tbSupplier ts WITH (NOLOCK)
		ON ts.comp_id = i.comp_id AND
		ts.supp_id = i.supp_id

		WHERE  i.comp_id = @comp_id
		AND  i.item_id = @item_id



END
GO

CREATE PROCEDURE [dbo].[spItem_getDataByID4FullJaus]
(
	@comp_id	INT,
	@wst_id		INT,
	@item_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@wst_id		INT,
				@item_id	INT
			SELECT
				@comp_id	= 1,
				@wst_id		= 10,
				@item_id	= 222
		*/
		-- -----------------------------------------------------

		DECLARE
			@intStor_ID		INT

		SELECT
			@intStor_ID			= tws.stor_id4FullJaus
		FROM tbWebServices					AS tws
		WHERE	tws.comp_id		= @comp_id	AND
				tws.wst_id		= @wst_id

		SELECT
			ti.item_id,
			ti.bra_id,
			ti.item_code,
			ti.item_desc,
			ti.item_detail,
			ti.item_vendorCode,
			ti.cat_id,
			ti.subcat_id,
			ti.brand_id,
			ti.pres_id,
			--ti.curr_id,
			ti.item_upb,
			ti.item_upp,
			ti.item_cantMin,
			ti.item_cantOpt,
			ti.item_mult,
			ti.item_commission,
			--ti.item_picture,
			ti.item_guarantee,
			ti.item_expser,
			ti.item_made,
			ISNULL(ti.item_web,'False')										[item_web],
			ti.item_annotation,
			ISNULL(ti.item_annotation1,'')									[WebSite_Copete],
			ISNULL(ti.item_annotation2,'')									[WebSite_ShortDescription],
			--ti.acc_count_id,
			ISNULL(ti.item_newness,'False')									[item_newness],
			ISNULL(ti.item_liquidation,'False')								[item_liquidation],
			ti.item_withDecimal,
			ti.byor_id,
			ti.supp_id,
			ti.item_qtyMin1,
			ti.item_qtyMin2,
			ti.item_qtyMin3,
			ti.item_markup_1,
			ti.item_markup_2,
			ti.item_markup_3,
			ti.item_markup_4,
			ti.item_markup_5,
			ti.item_markup_6,
			ti.item_markup_7,
			ti.item_markup_8,
			--ti.item_isForAssociation,
			--ti.item_isForAssociation_canEditGroup,
			--ti.item_trigger_tax_id,
			ti.item_weight,
			ti.item_volume,
			ti.item_not4Sale,
			--ti.item_cd,
			--ti.pf_id,
			ti.item_disabled,
			--ti.item_commission_byReceive,
			--ti.item_disabledInPriceList,
			--ti.item_recentlyPurchased,
			ti.item_disabledInBalance,
			ti.mu_id,
			dbo.fnGetAStock4MaxAssociation(ti.comp_id, @intStor_ID, ti.item_id,9999999999)	[stock],
			ISNULL(CONVERT(VARCHAR,vitooit.tax_id), '')						[tax_id],
			ttn.tax_percentage,
			ISNULL(CONVERT(VARCHAR,vitooit2.tax_id), '')					[tax_id_II],
			ISNULL(ttn2.tax_percentage,0)									[tax_percentage_II],

			CONVERT(BIT,CASE WHEN ti.item_picture IS NULL THEN 'False'
      				ELSE 'True' END) 										[imageExisting],
			ti.subcataux_id,
			ti.item_markup_9,
			ti.item_markup_10,
			ti.item_markup_11,
			ti.item_markup_12,
			ti.item_markup_13,
			ti.item_markup_14,
			ti.item_markup_15,
			ti.item_markup_16   ,
			ISNULL(ti.item_WebSite_desc,'')									[WebSite_Description],
			ti.item_higth,
			ti.item_wide,
			ti.item_large,
			tc.cat_desc,
			tsc.subcat_desc,
			tb.brand_desc
			FROM	tbItem								ti			WITH(NOLOCK)
				INNER JOIN tbCategory					tc			WITH(NOLOCK)
				ON	tc.comp_id			= ti.comp_id	AND
					tc.cat_id			= ti.cat_id
				INNER JOIN tbSubCategory				tsc			WITH(NOLOCK)
				ON  tsc.comp_id			= ti.comp_id	AND
					tsc.cat_id			= ti.cat_id		AND
					tsc.subcat_id		= ti.subcat_id
				LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit		WITH(NOLOCK)
				ON	vitooit.comp_id		= ti.comp_id	AND
					vitooit.item_id		= ti.item_id
				LEFT JOIN tbTaxName						ttn			WITH(NOLOCK)
				ON	ttn.comp_id			= ti.comp_id	AND
					ttn.tax_id			= vitooit.tax_id
				LEFT JOIN vwItemTaxesOnlyOneInternalTax vitooit2	WITH(NOLOCK)
				ON	vitooit2.comp_id	= ti.comp_id	AND
					vitooit2.item_id	= ti.item_id
				LEFT JOIN tbTaxName						ttn2		WITH(NOLOCK)
				ON	ttn2.comp_id		= ti.comp_id	AND
					ttn2.tax_id			= vitooit2.tax_id
				INNER JOIN tbBrand						tb			WITH(NOLOCK)
				ON	tb.comp_id			= ti.comp_id	AND
					tb.brand_id			= ti.brand_id
			WHERE	ti.comp_id							= @comp_id	AND
					tc.cat_isAvailable4FullJaus			= 'True'	AND
					tsc.subcat_isAvailable4FullJaus		= 'True'	AND
					ti.item_isAvailable4FullJaus		= 'True'	AND
					ISNULL(ti.item_disabled,'False')	= 'False'	AND
					ti.item_id							= @item_id

	END
GO





    --NoFathers		= 0  'para toda la aplicación
    --NoChilds		= 1  'para wfmItemSizeColor
    --Fathers		= 2  'para wfmSaleOrderDetailSizeColor
    --All			= -1 '?

	--cada vez que se actualicen alguna de estas opciones también hay que actualizarlas en
	--[spItem_getDataByCode], [spItem_getDataByFilters] y [spItem_getDataByText]
	--el parámetro @option indica si se deben recuperar o no, artículos	relacionados a size/color
	--@option = 0  - sólo artículos POSIBLES PADRES E HIJOS	- item_id not in tbItemSizeColor.item_id -wfmItemSizeColor
	--@option = 10 - sólo artículos POSIBLES PADRES E HIJOS	- item_id not in tbItemSizeColor.item_id -wfmItemSizeColor (NO Deshabilitados para la VENTA)
	--@option = 1 - sólo artículos PADRES Y POSIBLES PADRES - item_id not in tbItemSizeColor.item_id_child -wfmSaleOrderDetailSizeColor
	--@option = 2 - sólo artículos PADRES					- item_id     in tbItemSizeColor.item_id -las demás páginas
	--@option = -1 - todos los artículos
	--ATENCION LO QUE EN LOS OTROS SP ES @option EN ESTE ES @option Seguramente obra del REVERENDO HIJO DE MIL PITAS ENFERMO MENTALLLLLLLLLLL



-- Log:
-- MOS 04-2024: Si la busqueda con - está habilitada ( x defecto lo está salvo que un FORRO HIJO DE RE MIL PUTAS como NG no lo quiera. Nestor y la reconcha de tu reputa madre, enfermo hjijo de puta !!!



CREATE  PROCEDURE [dbo].[spItem_getDataByText]
(
	@text			NVARCHAR(300),
	@count			INT,
	@option			INT ,		-- No es Lang_id.... cambiar... asi nose hace.!!!!
	@comp_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@prof_id		INT,
	@intStorageId	INT,
	@intPriceListId INT


	--ATENCION: en este caso se aprovechó este parámetro (@option) que no se estaba
	--utilizando para seleccionar artículos relacionados a talles/colores
)
AS



BEGIN


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-12-08
	-- Parte		: 715
	-- Description	: Se agrega la funcionalidad que si en la cadena de búsqueda se separan palabras con la cadena '++'
	--				  estas palabras se buscan con coordinante 'and' y dentro de todo el texto y no sólo desde el principio
	-- =================================================================================================================


	-- ---------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------
	/*
		DECLARE	@text			VARCHAR(300),
				@count			INT,
				@option		INT,
				@comp_id		INT,
				@bra_id			INT,
				@user_id		INT,
				@prof_id		INT,
				@intStorageId	INT,
				@intPriceListId INT
		SELECT 	@text			= '+257+Auto',-- - CAJA 4',
				@count			= 20,
				@option		= 0,
				@comp_id		= 1,
				@bra_id			= 1,
				@user_id		=42,
				@prof_id		=1,
				@intStorageId	=-1,
				@intPriceListId =-1
	*/
	-- ---------------------------------------------------------------------



	-- Filtra los Deshabilitados para la Venta ?
	DECLARE @bitFilterNot4SaleInFalse AS BIT = 'False'
	IF @option = 10
		BEGIN
			SET @option = 0
			SET @bitFilterNot4SaleInFalse = 'True'
		END



	SET @text = REPLACE(@text,'%','[%]')


	-- Tomo los Grupos de Sucursales a los que pertenece esta sucursal
	DECLARE @tmpBranchsOfBranchGroup TABLE(brag_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchsOfBranchGroup(brag_id)
		SELECT brag_id
			FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
			WHERE	tbgd.comp_id	= @comp_id AND
					tbgd.bra_id		= @bra_id



	-- Si se requiere SOLO Padres para la pagina de Seleccion de Talles y Colores....
	IF @option = 2
		BEGIN
			EXEC spItem_getDataByText_onlyFathers
										@text,
										@count,
										@option ,
										@comp_id,
										@bra_id,
										@user_id,
										@prof_id,
										@intStorageId,
										@intPriceListId
			RETURN
		END


	-- Padres o Posibles Padres
	IF @option = 1
		BEGIN
			EXEC spItem_getDataByText_noChilds
										@text,
										@count,
										@option ,
										@comp_id,
										@bra_id,
										@user_id,
										@prof_id,
										@intStorageId,
										@intPriceListId
			RETURN
		END






	-- -------------------------------------------------------------------------
	-- Verificaciones de Colores
	-- -------------------------------------------------------------------------
	--DECLARE @option			AS INT
	--SET		@option = @option			-- Cosa de HDPPPPPPPPP  !!!!!
	DECLARE @bitHasItemSizeColorRelation	AS BIT
	IF EXISTS(	SELECT TOP 1  1
	          		FROM tbItemSizeColorRelation tiscr
	          		WHERE tiscr.comp_id = @comp_id   )
		BEGIN
			SET @bitHasItemSizeColorRelation = 'True'
		END
	ELSE
		BEGIN
			SET @bitHasItemSizeColorRelation = 'False'
		END
	-- -------------------------------------------------------------------------





	-- Se agrega que ademas del + se pueda tipear un PUNTO
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'.','+')






	-- Si se tiene que buscar solo en el CODIGO del articulo ** en la busqueda.
	DECLARE @strSearchBiCode AS NVARCHAR(50)
	DECLARE @bitSearchBiCode AS BIT
	IF substring(@text,1,2) = '**' AND LEN(@text) > 2
		BEGIN
			SET @bitSearchBiCode = 'True'
			SET @strSearchBiCode = dbo.fnStrAllTrim( SUBSTRING(@text,3,45))
		END
	ELSE
		BEGIN
			SET @bitSearchBiCode = 'False'
			SET @strSearchBiCode = ''
		END



	-- ---------------------------------------------------------------
	-- MOS 01-2024: textos a eliminar en la busqueda
	-- ---------------------------------------------------------------
	DECLARE @text0_Minus	varchar(300)
	DECLARE @text1_Minus	varchar(300)
	DECLARE @text2_Minus	varchar(300)
	DECLARE @text3_Minus	varchar(300)
	DECLARE @text4_Minus	varchar(300)
	DECLARE @text5_Minus	varchar(300)
	DECLARE @selection_method_Minus	INT  --0:búsqueda normal  >0:búsqueda múltiple   MOS 01-2024: Se agregala Exclusión de articulos que tengan lo puesto en -

	DECLARE @bitDisableMinusSearch AS BIT = 'False'	-- MOS 04-2024: Si la busqueda con - está habilitada ( x defecto lo está salvo que un FORRO HIJO DE RE MIL PUTAS como NG no lo quiera. Nestor y la reconcha de tu reputa madre, enfermo hjijo de puta !!!
	SELECT  @bitDisableMinusSearch = tcfc.comp_disableMinusSearch
		FROM	tbCompanyFastConfigs AS tcfc	WITH (NOLOCK)
		WHERE	tcfc.comp_id = @comp_id


--==
--SELECT '@bitDisableMinusSearch',@bitDisableMinusSearch


	IF		@bitDisableMinusSearch = 'False' 		-- MOS 04-2024: Si la busqueda con - está habilitada ( x defecto lo está salvo que un FORRO HIJO DE RE MIL PUTAS como NG no lo quiera. Nestor y la reconcha de tu reputa madre, enfermo hjijo de puta !!!
		BEGIN
			SELECT	@selection_method_Minus = CHARINDEX('-',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')
			IF @selection_method_Minus > 0
				BEGIN
					SELECT @selection_method_Minus	= COUNT(*) from dbo.fnSplitTable(@text,'-')
				END

			IF @selection_method_Minus > 0
				BEGIN
					--SET @textFTS = ''
					DECLARE cursor_data_Minus CURSOR LOCAL FAST_FORWARD FOR
					SELECT fst.items FROM dbo.fnSplitTable(@text,'-') fst
					OPEN cursor_data_Minus
					FETCH cursor_data_Minus INTO @text0_Minus
					WHILE @@FETCH_STATUS = 0
						BEGIN

							IF @text1_Minus IS NULL SET @text1_Minus = @text0_Minus else
							IF @text2_Minus IS NULL SET @text2_Minus = @text0_Minus else
							IF @text3_Minus IS NULL SET @text3_Minus = @text0_Minus else
							IF @text4_Minus IS NULL SET @text4_Minus = @text0_Minus else
							IF @text5_Minus IS NULL SET @text5_Minus = @text0_Minus --else

							FETCH cursor_data_Minus INTO @text0_Minus
						END

					CLOSE cursor_data_Minus
					DEALLOCATE cursor_data_Minus
				end

			IF @text2_Minus IS NOT NULL	SET @text = REPLACE(@text,'-' + @text2_Minus,'')
			IF @text3_Minus IS NOT NULL	SET @text = REPLACE(@text,'-' + @text3_Minus,'')
			IF @text4_Minus IS NOT NULL	SET @text = REPLACE(@text,'-' + @text4_Minus,'')
			IF @text5_Minus IS NOT NULL	SET @text = REPLACE(@text,'-' + @text5_Minus,'')

		END
	ELSE
		BEGIN
			SET @selection_method_Minus = 0
		END
	-- ---------------------------------------------------------------


--==
--SELECT '@text',@text
--SELECT '@selection_method_Minus',@selection_method_Minus



	DECLARE @selection_method		INT  --0:búsqueda normal  >0:búsqueda múltiple
	--se verifica si hay cadena '++'
	SELECT	@selection_method		= CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method		= COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)		-- MOS 01-2024, eran nvarchar y los pase a varchar
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)




	IF @selection_method > 0
		BEGIN
			--SET @textFTS = ''
			DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
			SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
			OPEN cursor_data
			FETCH cursor_data INTO @text0
			WHILE @@FETCH_STATUS = 0
				BEGIN

					IF @text1 IS NULL SET @text1 = @text0 else
					IF @text2 IS NULL SET @text2 = @text0 else
					IF @text3 IS NULL SET @text3 = @text0 else
					IF @text4 IS NULL SET @text4 = @text0 else
					IF @text5 IS NULL SET @text5 = @text0 --else
					--IF @text6 IS NULL SET @text6 = @text0 else
					--IF @text7 IS NULL SET @text7 = @text0 else
					--IF @text8 IS NULL SET @text8 = @text0 else
					--IF @text9 IS NULL SET @text9 = @text0 else
					--IF @text10 IS NULL SET @text10 = @text0
					--IF @text0 <> '' AND @textFTS = ''
					--	BEGIN
					--		SET @textFTS = @text0
					--	END
					--ELSE IF @text0 <> '' AND @textFTS <> ''
					--	BEGIN
					--		SET @textFTS = @textFTS + ' AND '+ @text0
					--	END
					FETCH cursor_data INTO @text0
				END

			CLOSE cursor_data
			DEALLOCATE cursor_data
		end






	-- =================================================================================================================


--==
--SELECT @text0,
--	   @text1,
--	   @text2,
--	   @text3,
--	   @text4,
--	   @text5
--SELECT @text0_Minus,
--	   @text1_Minus,
--	   @text2_Minus,
--	   @text3_Minus,
--	   @text4_Minus,
--	   @text5_Minus
--==




	-- --------------------------------------------
	-- Busca el Deposito de la sucursal actual
	-- --------------------------------------------
	DECLARE @Stor_Id AS INT
	DECLARE @bra_ItemSearhOnlyWithStock AS BIT
	DECLARE @bra_ItemSearhOrderByDesc   AS BIT
	SELECT	@Stor_Id					= stor_id ,
			@bra_ItemSearhOnlyWithStock = IsNull(tb.bra_ItemSearhOnlyWithStock,'False'),
			@bra_ItemSearhOrderByDesc	= tb.bra_ItemSearhOrderByDesc
		FROM	tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id
	IF @intStorageId <> -1	-- Si llega un deposito en particcular, pone ese.!
		BEGIN
			SET @Stor_Id = @intStorageId
		END
	-- --------------------------------------------


	-- --------------------------------------------
	-- Busca el Deposito de la sucursal actual
	-- --------------------------------------------
	DECLARE @intStoreIdAdditional AS INT
	SET		@intStoreIdAdditional = NULL
	SELECT  @intStoreIdAdditional = tisfqa.stor_id
		FROM tbItemStorageFastQueryAdditional tisfqa
		WHERE	tisfqa.comp_id	= @comp_id	AND
				tisfqa.bra_id	= @bra_id	AND
				tisfqa.prof_id	= @prof_id
	-- --------------------------------------------



	-- --------------------------------------------
	-- Busca la Lista de Precios a mostrar
	-- --------------------------------------------
	DECLARE @intPrLiId		AS INT
	DECLARE @bitPlusIVATAx	AS BIT
	DECLARE @intCurrId		AS INT
	SET		@intPrLiId		= -1
	SET		@bitPlusIVATAx  = 'False'
	SET		@intCurrId		= -1

	-- 1ro, si esta la lista que se pasa por parametro, que muestre esa.!!
	SELECT top 1	@intPrLiId		= prli_id ,
					@bitPlusIVATAx	= IsNull(is_prli_plusIVATax,'False'),
					@intCurrId		= curr_id4PriceOrCost
		FROM	tbitemselection				WITH (NOLOCK)
		WHERE	comp_id = @comp_id
			AND (bra_id	= @bra_id OR bra_id IS NULL)
			AND prof_id = @prof_id
			AND prli_id = @intPriceListId
			AND prli_id IS NOT NULL
			AND is_disabled = 'False'
		ORDER BY is_order
	-- 2do: Si no la encuentra que muestre la primera que este definida para seleccion de articulos
	IF @intPrLiId = -1
		BEGIN

			SELECT top 1	@intPrLiId		=	prli_id ,
							@bitPlusIVATAx	=	IsNull(is_prli_plusIVATax,'False'),
							@intCurrId		=	curr_id4PriceOrCost
				FROM	tbitemselection		WITH (NOLOCK)
				WHERE	 comp_id = @comp_id
					AND (bra_id	 = @bra_id OR bra_id IS NULL)
					AND  prof_id = @prof_id
					AND  prli_id IS NOT NULL
					AND is_disabled = 'False'
				ORDER BY is_order

		END
	-- --------------------------------------------


	DECLARE @tmpItemTable TABLE(	item_desc	NVARCHAR(500),
									item_id		INT,
									tmpOrder  int NOT NULL IDENTITY (1, 1 ))


	-- --------------------------------------------------------------------------------------------------------
	-- ATENCION!!!
	-- Si se modifica algo en la busqueda ver de hacerlo tanto en la por CODIGO como el la por DESCROPCION!!!!!
	-- --------------------------------------------------------------------------------------------------------
	DECLARE @tmpItemFilter TABLE(	item_id INT PRIMARY KEY,
									itst_LastAvailableInRelalculation DECIMAL(19,4),
									itst_cant DECIMAL(19,4),
									tmpOrder  int NOT NULL IDENTITY (1, 1 ))


	-- Si busca por cualquier metodo
	IF @bitSearchBiCode = 'False'
		BEGIN

			INSERT INTO @tmpItemFilter(item_id, itst_LastAvailableInRelalculation,		itst_cant)
			SELECT	TOP (@count)	ti.item_id,tis.itst_LastAvailableInRelalculation,	tis.itst_cant

				FROM		tbItem ti										WITH (NOLOCK)
				INNER JOIN tbItem_FastestSearch				AS tifs			WITH (NOLOCK)
					ON	tifs.comp_id = ti.comp_id AND
						tifs.item_id = ti.item_id
				LEFT JOIN @tmpBranchsOfBranchGroup tmp
					ON tmp.brag_id = ti.brag_id
				LEFT JOIN tbItemStorage							tis			WITH (NOLOCK)
					ON	tis.comp_id = ti.comp_id	AND
						tis.stor_id = @Stor_Id		AND
						tis.item_id = ti.item_id
				WHERE		ti.comp_id = @comp_id	AND
							CASE
								WHEN ti.brag_id IS NOT NULL AND tmp.brag_id IS NULL THEN 0
								WHEN ti.bra_id  IS NULL								THEN 1
								WHEN ti.bra_id  = @bra_id							THEN 1
								ELSE 0
							END = 1
				--AND			(ti.bra_id = @bra_id OR ti.bra_id IS NULL)
				AND			(
								(

									CASE
										-- --------------------------------------
										-- MOS 10-2021, para que busque con y sin acentos
										-- --------------------------------------
										WHEN (@selection_method = 0 AND tifs.item_desc LIKE @text + '%' )				THEN 1
										WHEN (@selection_method = 1 AND tifs.item_desc LIKE '%' + @text1 + '%')			THEN 1
										WHEN (@selection_method = 2 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%') THEN 1
										WHEN (@selection_method = 3 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%' AND tifs.item_desc LIKE '%' + @text3 + '%') THEN 1
										WHEN (@selection_method = 4 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%' AND tifs.item_desc LIKE '%' + @text3 + '%' AND tifs.item_desc LIKE '%' + @text4 + '%') THEN 1
										WHEN (@selection_method = 5 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%' AND tifs.item_desc LIKE '%' + @text3 + '%' AND tifs.item_desc LIKE '%' + @text4 + '%' AND tifs.item_desc LIKE '%' + @text5 + '%') THEN 1
										ELSE 0
									END	= 1
									AND
									CASE
										-- --------------------------------------
										-- MOS 01-2024: para poder excluir de una busqueda lo que está precedido x un -
										-- --------------------------------------
										WHEN @selection_method_Minus = 0 															THEN 1
										WHEN (@selection_method_Minus = 2 AND  tifs.item_desc NOT LIKE '%' + @text2_Minus + '%') THEN 1
										WHEN (@selection_method_Minus = 3 AND  tifs.item_desc NOT LIKE '%' + @text2_Minus + '%' AND tifs.item_desc NOT LIKE '%' + @text3_Minus + '%') THEN 1
										WHEN (@selection_method_Minus = 4 AND  tifs.item_desc NOT LIKE '%' + @text2_Minus + '%' AND tifs.item_desc NOT LIKE '%' + @text3_Minus + '%' AND tifs.item_desc NOT LIKE '%' + @text4_Minus + '%') THEN 1
										WHEN (@selection_method_Minus = 5 AND  tifs.item_desc NOT LIKE '%' + @text2_Minus + '%' AND tifs.item_desc NOT LIKE '%' + @text3_Minus + '%' AND tifs.item_desc NOT LIKE '%' + @text4_Minus + '%' AND tifs.item_desc NOT LIKE '%' + @text5_Minus + '%') THEN 1
										ELSE 0
									END	= 1
								)
							)

				-- MOS 12-2021 x Sonnos
				AND		( @bitFilterNot4SaleInFalse = 'False' OR (@bitFilterNot4SaleInFalse = 'True' AND ti.item_not4Sale = 'False'))





				-- MOS 12-2014
				-- Hace MUUYY lento todo, si hay que agregarlo nuevamente hacer un select separado.!
				--AND		(
				--			CASE
				--				WHEN @bitHasItemSizeColorRelation	= 'False'																																	THEN 'True'
				--				WHEN @option		= -1																																		THEN 'True'
				--				WHEN (@option = 0 AND NOT EXISTS (	SELECT 1
				--																		FROM tbItemSizeColorRelation tiscr
				--				                                                  		WHERE	tiscr.comp_id = ti.comp_id AND
				--				                                                  				tiscr.item_id = ti.item_id)) 			THEN 'True'
				--				WHEN (@option = 1 AND NOT EXISTS (	SELECT  1
				--				                                                  		FROM tbItemSizeColorRelation tiscr
				--				                                                  		WHERE	tiscr.comp_id		= ti.comp_id AND
				--				                                                  				tiscr.item_id_child = ti.item_id)) 		THEN 'True'
				--				WHEN (@option = 2 AND     EXISTS (	SELECT  1
				--				                                                  		FROM tbItemSizeColorRelation tiscr
				--				                                                  		WHERE	tiscr.comp_id = ti.comp_id AND
				--																				tiscr.item_id = ti.item_id)) 			THEN 'True'
				--				ELSE 'False'
				--			END		= 'True'
				--		)


				AND	 ti.item_disabled = 'false'
				AND (
						CASE
							WHEN @bra_ItemSearhOnlyWithStock = 'False'										THEN 'True'
							WHEN ti.item_NoStockCheck		 = 'True'										THEN 'True'
							WHEN tis.itst_cant > 0															THEN 'True'
							ELSE																				 'False'
						END	= 'True'
					)
				--AND ti.comp_id IS NOT NULL   al pedo. MOS 12-2016
				ORDER BY	CASE
        						WHEN tis.itst_LastAvailableInRelalculation > 0		THEN	0   /*tis.itst_LastAvailableInRelalculation*/
        						WHEN tis.itst_LastAvailableInRelalculation IS NULL  THEN	2
        						ELSE														1
        					END ASC,
        					CASE	@bra_ItemSearhOrderByDesc
        						WHEN 1 THEN ti.item_desc
        						ELSE ''
        					END ASC,
        					tis.itst_LastAvailableInRelalculation DESC


		END

			-- ----------------------------------------------
	ELSE	-- Si busca solo en el CODIGO del Articulo . . .
			-- ----------------------------------------------

		BEGIN


			-- Verifica si hay que subclasificar por SubCategorias y selecciona la PRIMERA que coincida
			DECLARE @strSUBCAT AS NVARCHAR(4000)
			SET		@strSUBCAT = ''

			IF @strSearchBiCode LIKE '%##%'
				BEGIN
					SET	@strSUBCAT = ISNULL(dbo.fnSplitPosition(@strSearchBiCode, '##',2) ,'')
					IF @strSUBCAT <> ''
						BEGIN
							SET @strSUBCAT			= '%'+ @strSUBCAT + '%'
							SET @strSearchBiCode	=  ISNULL(dbo.fnSplitPosition(@strSearchBiCode, '##',1) ,'')
						END
				END
--==
--SELECT '@intSubCatID',@intSubCatID
--==


			SELECT 	TOP (@count)		ti.item_id,
										tis.itst_LastAvailableInRelalculation,
										tis.itst_cant
				INTO #tmpITEM		-- Se p[one en una temporal ya que puede haber mas de un resultado en esta busqueda y debe hacerse un DISTINCT x el indice de la tabla temporal
				FROM		tbItem ti										WITH (NOLOCK)
				LEFT JOIN @tmpBranchsOfBranchGroup tmp
					ON tmp.brag_id = ti.brag_id
				INNER JOIN tbSubCategory						tsc			WITH (NOLOCK)
					ON	tsc.comp_id		= ti.comp_id AND
						tsc.cat_id		= ti.cat_id AND
						tsc.subcat_id	= ti.subcat_id
				LEFT JOIN tbItemStorage							tis			WITH (NOLOCK)
					ON	tis.comp_id = ti.comp_id	AND
						tis.stor_id = @Stor_Id		AND
						tis.item_id = ti.item_id
				LEFT JOIN tbItemEAN tie										WITH (NOLOCK)
					ON	tie.comp_id = ti.comp_id AND
						tie.item_id = ti.item_id
				LEFT JOIN tbItem_codeAlternative				tica		WITH (NOLOCK)
					ON tica.comp_id = ti.comp_id and
					   tica.item_id = ti.item_id
				WHERE		ti.comp_id = @comp_id
				--AND			(ti.bra_id = @bra_id OR ti.bra_id IS NULL)
				AND		CASE
							WHEN ti.brag_id IS NOT NULL AND tmp.brag_id IS NULL THEN 0
							WHEN ti.bra_id  IS NULL								THEN 1
							WHEN ti.bra_id  = @bra_id							THEN 1
							ELSE 0
						END = 1
				AND			(

								(
									CASE
										WHEN ti.item_code				LIKE '%' + @strSearchBiCode + '%'			THEN 'True'
										WHEN ti.item_expean = 'True'	AND		   @strSearchBiCode = tie.ie_ean	THEN 'True'

										-- MOS 03-2022 x ticket 15519 se puso que busque por contenido.
										-- WHEN ti.item_vendorCode			LIKE       @strSearchBiCode + '%'			THEN 'True'
										WHEN ti.item_vendorCode			LIKE '%' + @strSearchBiCode + '%'			THEN 'True'

										WHEN ti.item_codeAlternative	LIKE       @strSearchBiCode + '%'			THEN 'True'
										WHEN tica.item_codeAlternative	LIKE '%' + @strSearchBiCode + '%'			THEN 'True'
										ELSE	'False'
									END	= 'True'
								)
							)
				AND	 ti.item_disabled = 'false'

				-- MOS 12-2021 x Sonnos
				AND		( @bitFilterNot4SaleInFalse = 'False' OR (@bitFilterNot4SaleInFalse = 'True' AND ti.item_not4Sale = 'False'))

				AND			(@strSUBCAT = '' OR tsc.subcat_desc LIKE @strSUBCAT)
				AND (
						CASE
							WHEN @bra_ItemSearhOnlyWithStock = 'False'										THEN 'True'
							WHEN ti.item_NoStockCheck		 = 'True'										THEN 'True'
							WHEN tis.itst_cant > 0															THEN 'True'
							ELSE																				 'False'
						END	= 'True'
					)
				--AND ti.comp_id IS NOT NULL  Al pedo, mos, 12-2016
				ORDER BY	CASE
        						WHEN tis.itst_LastAvailableInRelalculation > 0		THEN	0   /*tis.itst_LastAvailableInRelalculation*/
        						WHEN tis.itst_LastAvailableInRelalculation IS NULL  THEN	2
        						ELSE														1
        					END ASC,
        					CASE	@bra_ItemSearhOrderByDesc
        						WHEN 1 THEN ti.item_desc
        						ELSE ''
        					END,
        					tis.itst_LastAvailableInRelalculation



			INSERT INTO @tmpItemFilter(	item_id,	itst_LastAvailableInRelalculation,		itst_cant)
				SELECT DISTINCT *
					FROM  #tmpITEM

			DROP TABLE #tmpITEM


		END
	-- --------------------------------------------------------------------------------------------------------

	-- --------------------------------------------------------------------------------------------------------
	-- Busca x Patente, ver si no pone lento a todo...
	-- --------------------------------------------------------------------------------------------------------
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpItemFilter(	item_id,	itst_LastAvailableInRelalculation,		itst_cant)
			SELECT	TOP (@count)		ti.item_id,	tis.itst_LastAvailableInRelalculation,  tis.itst_cant
				FROM		tbItem ti										WITH (NOLOCK)
				LEFT JOIN @tmpBranchsOfBranchGroup tmp
					ON tmp.brag_id = ti.brag_id
				LEFT JOIN tbItemStorage							tis			WITH (NOLOCK)
					ON	tis.comp_id = ti.comp_id	AND
						tis.stor_id = @Stor_Id		AND
						tis.item_id = ti.item_id
				LEFT JOIN tbItemEAN tie										WITH (NOLOCK)
					ON	tie.comp_id = ti.comp_id AND
						tie.item_id = ti.item_id
				LEFT JOIN tbItem_codeAlternative				tica		WITH (NOLOCK)
					ON tica.comp_id = ti.comp_id and
					   tica.item_id = ti.item_id
				WHERE		ti.comp_id				= @comp_id	AND
							ti.itemCAR_PatentNumber = @text		AND
				     	   --(ti.bra_id = @bra_id OR ti.bra_id IS NULL)
				CASE
					WHEN ti.brag_id IS NOT NULL AND tmp.brag_id IS NULL THEN 0
					WHEN ti.bra_id  IS NULL								THEN 1
					WHEN ti.bra_id  = @bra_id							THEN 1
					ELSE 0
				END = 1

				AND	 ti.item_disabled = 'false'
				AND (
						CASE
							WHEN @bra_ItemSearhOnlyWithStock = 'False'										THEN 'True'
							WHEN ti.item_NoStockCheck		 = 'True'										THEN 'True'
							WHEN tis.itst_cant > 0															THEN 'True'
							ELSE																				 'False'
						END	= 'True'
					)
				--AND ti.comp_id IS NOT NULL  Al pedo, mos, 12-2016
				ORDER BY	CASE
        						WHEN tis.itst_LastAvailableInRelalculation > 0		THEN	0   /*tis.itst_LastAvailableInRelalculation*/
        						WHEN tis.itst_LastAvailableInRelalculation IS NULL  THEN	2
        						ELSE														1
        					END ASC,
        					CASE	@bra_ItemSearhOrderByDesc
        						WHEN 1 THEN ti.item_desc
        						ELSE ''
        					END,
        					tis.itst_LastAvailableInRelalculation


		END
	-- --------------------------------------------------------------------------------------------------------






	-- --------------------------------------------------------------------------------------------------------
	-- Insert Final
	-- --------------------------------------------------------------------------------------------------------
	INSERT INTO @tmpItemTable(item_desc, item_id)
		SELECT
					(	-- MOS, 30-08-2021
						dbo.fnStrPADR	(   -- Dejar estos REPLACE para que se mantenga todo ENCOLUMNADO con los caracteres monoespaciados del buscador !!!
											REPLACE(REPLACE(dbo.fnStrAllTrim (SUBSTRING(ISNULL(ti.item_desc,''),1,55)),'  ',' '),'  ',' ')
											,55,'.'
										)

					)									+ '|' +
					'D/F:' + dbo.fnStrPADL(convert( VARCHAR ,CONVERT(DECIMAL(10,0), ROUND (ISNULL(dbo.fnGetAStock4MaxAssociation(@comp_id,@stor_id,ti.item_id, 9999999999 ),0),0))),07,'0') + '/' +
					dbo.fnItem_getDataByText_getStock(tmp.itst_cant,4) +
					/*
					Stock Rapido de tbItemStorageFastQueryAdditional
					*/
						   + '/'  + CASE
										WHEN @intStoreIdAdditional IS NULL THEN '--'
										ELSE dbo.fnItem_getDataByText_getStock(dbo.fnGetAStock4MaxAssociation(@comp_id,@intStoreIdAdditional,ti.item_id,999999999),2)
									END  +
						   + '|' +
					CASE

						-- Moneda de la Consulta
						WHEN @intCurrId IS NOT NULL AND tpli.item_id IS NOT NULL AND @bitPlusIVATAx = 'False' THEN dbo.fnStrAllTrim( IsNull(tc2.curr_symbol,'***') ) + ':' + dbo.fnStrPADL(convert(varchar,convert(decimal(12,2),IsNull(
																																																											dbo.fnGetExchange2( tpli.comp_id,tpli.prli_price, tpli.curr_id, @intCurrId, 0,0,0,'False')
																																																										,0))) ,10,'0') + ''

						WHEN @intCurrId IS NOT NULL AND tpli.item_id IS NOT NULL AND @bitPlusIVATAx = 'True'  THEN dbo.fnStrAllTrim( IsNull(tc2.curr_symbol,'***') ) + ':' + dbo.fnStrPADL(convert(varchar,convert(decimal(12,2),IsNull(
																																																											dbo.fnGetExchange2( tpli.comp_id,tpli.prli_price, tpli.curr_id, @intCurrId, 0,0,0,'False')
																																																										,0) + (IsNull(
																																																														dbo.fnGetExchange2( tpli.comp_id,tpli.prli_price, tpli.curr_id, @intCurrId, 0,0,0,'False')
																																																													  ,0) * dbo.fnItem_getDataByText_getTaxPercentage(ti.comp_id,ti.item_id) / 100))) ,10,'0') + ''
						-- Moneda de Origen
						WHEN tpli.item_id IS NOT NULL AND @bitPlusIVATAx = 'False' THEN dbo.fnStrAllTrim( IsNull(tc.curr_symbol,'***') ) + ':' + dbo.fnStrPADL(convert(varchar,convert(decimal(12,2),IsNull(tpli.prli_price,0))) ,10,'0') + ''
						WHEN tpli.item_id IS NOT NULL AND @bitPlusIVATAx = 'True'  THEN dbo.fnStrAllTrim( IsNull(tc.curr_symbol,'***') ) + ':' + dbo.fnStrPADL(convert(varchar,convert(decimal(12,2),IsNull(tpli.prli_price,0) + (IsNull(tpli.prli_price,0) * dbo.fnItem_getDataByText_getTaxPercentage(ti.comp_id,ti.item_id) / 100))) ,10,'0') + ''
						ELSE '***:' + dbo.fnStrPADL(convert(varchar,convert(decimal(12,2),0 )) ,08,'0') + ''

					END

					-- MOS 06-2022 x alguien de MR, como siempre con cosas raras...   Si jode, SACARLO!
					+ 			CASE
									WHEN DATALENGTH(ti.item_desc) > 55 THEN '->' + ISNULL(ti.item_code,'') + '-->' + dbo.fnStrAllTrim (ISNULL(ti.item_desc,''))
									ELSE ''
								END


					+ '|' +
					convert(VARCHAR(50),ISNULL(ti.item_code,''))   -- OJOOOOOOO, Debe ser el ULTIMO Parametro y debe estar SOLO el CODIGOOO!!!!!
																																												[item_desc],
					ti.item_id																																					[item_id]
		FROM		tbItem ti										WITH (NOLOCK)

		INNER JOIN @tmpItemFilter tmp
			ON tmp.item_id = ti.item_id

		LEFT JOIN vwPriceListItems						tpli		WITH (NOLOCK)
			ON		tpli.comp_id = ti.comp_id
				AND tpli.item_id = ti.item_id
				AND tpli.prli_id = @intPrLiId
				--AND ( tpli.bra_id IS NULL OR tpli.bra_id = @bra_id ) nooooooooooo

		LEFT JOIN tbsysCurrency							tc			WITH (NOLOCK)
			ON  tc.curr_id = tpli.curr_id

		LEFT JOIN tbsysCurrency							tc2			WITH (NOLOCK)
			ON tc2.curr_id = @intCurrId
		WHERE  ti.comp_id  = @comp_id

		ORDER BY	tmp.tmpOrder

	-- --------------------------------------------------------------------------------------------------------




	IF @bra_ItemSearhOrderByDesc = 'True'
		BEGIN
			SELECT DISTINCT *
				FROM @tmpItemTable tmp
				ORDER BY tmp.item_desc
		END
	ELSE
		BEGIN
			SELECT DISTINCT *
				FROM @tmpItemTable tmp
				ORDER BY tmp.tmpOrder
		END


END
GO






--@option = 1 - sólo artículos PADRES Y POSIBLES PADRES - item_id not in tbItemSizeColor.item_id_child -wfmSaleOrderDetailSizeColor

CREATE  PROCEDURE [dbo].[spItem_getDataByText_noChilds]
(
	@text			NVARCHAR(300),
	@count			INT,
	@option			INT,
	@comp_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@prof_id		INT,
	@intStorageId	INT,
	@intPriceListId INT
)
AS



BEGIN


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



-- ---------------------------------------------------------------------
-- Testing
-- ---------------------------------------------------------------------
	/*
	DECLARE	@text			VARCHAR(300),
			@count			INT,
			@option		INT,
			@comp_id		INT,
			@bra_id			INT,
			@user_id		INT,
			@prof_id		INT,
			@intStorageId	INT,
			@intPriceListId INT
	SELECT 	@text			= '+a',
			@count			= 20,
			@option		= 0,
			@comp_id		= 1,
			@bra_id			= 1,
			@user_id		=42,
			@prof_id		=1,
			@intStorageId	=3,
			@intPriceListId =1
	*/
-- ---------------------------------------------------------------------

	SET @text = REPLACE(@text,'%','[%]')


	-- Tomo los Grupos de Sucursales a los que pertenece esta sucursal
	DECLARE @tmpBranchsOfBranchGroup TABLE(brag_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchsOfBranchGroup(brag_id)
		SELECT brag_id
			FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
			WHERE	tbgd.comp_id	= @comp_id AND
					tbgd.bra_id		= @bra_id



	-- Se agrega que ademas del + se pueda tipear un PUNTO
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'.','+')





	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	nvarchar(300)
	DECLARE @text1	nvarchar(300)
	DECLARE @text2	nvarchar(300)
	DECLARE @text3	nvarchar(300)
	DECLARE @text4	nvarchar(300)
	DECLARE @text5	nvarchar(300)
	--DECLARE @text6	nvarchar(300)
	--DECLARE @text7	nvarchar(300)
	--DECLARE @text8	nvarchar(300)
	--DECLARE @text9	nvarchar(300)
	--DECLARE @text10	nvarchar(300)
	--DECLARE @textFTS NVARCHAR(500)

	IF @selection_method > 0
	BEGIN
		--SET @textFTS = ''
		DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
			BEGIN

				IF @text1 IS NULL SET @text1 = @text0 else
				IF @text2 IS NULL SET @text2 = @text0 else
				IF @text3 IS NULL SET @text3 = @text0 else
				IF @text4 IS NULL SET @text4 = @text0 else
				IF @text5 IS NULL SET @text5 = @text0 --else
				--IF @text6 IS NULL SET @text6 = @text0 else
				--IF @text7 IS NULL SET @text7 = @text0 else
				--IF @text8 IS NULL SET @text8 = @text0 else
				--IF @text9 IS NULL SET @text9 = @text0 else
				--IF @text10 IS NULL SET @text10 = @text0
				--IF @text0 <> '' AND @textFTS = ''
				--	BEGIN
				--		SET @textFTS = @text0
				--	END
				--ELSE IF @text0 <> '' AND @textFTS <> ''
				--	BEGIN
				--		SET @textFTS = @textFTS + ' AND '+ @text0
				--	END
				FETCH cursor_data INTO @text0
			END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- =================================================================================================================


--SELECT 1 / 0

	-- --------------------------------------------
	-- Busca el Deposito de la sucursal actual
	-- --------------------------------------------
	DECLARE @Stor_Id AS INT
	DECLARE @bra_ItemSearhOnlyWithStock AS BIT
	SELECT	@Stor_Id					= stor_id ,
			@bra_ItemSearhOnlyWithStock = IsNull(tb.bra_ItemSearhOnlyWithStock,'False')
		FROM	tbBranch tb
		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id
	IF @intStorageId <> -1	-- Si llega un deposito en particcular, pone ese.!
		BEGIN
			SET @Stor_Id = @intStorageId
		END
	-- --------------------------------------------


	-- --------------------------------------------
	-- Busca el Deposito de la sucursal actual
	-- --------------------------------------------
	DECLARE @intStoreIdAdditional AS INT
	SET		@intStoreIdAdditional = NULL
	SELECT  @intStoreIdAdditional = tisfqa.stor_id
		FROM tbItemStorageFastQueryAdditional tisfqa
		WHERE	tisfqa.comp_id	= @comp_id	AND
				tisfqa.bra_id	= @bra_id	AND
				tisfqa.prof_id	= @prof_id
	-- --------------------------------------------



	-- --------------------------------------------
	-- Busca la Lista de Precios a mostrar
	-- --------------------------------------------
	DECLARE @intPrLiId		AS INT
	DECLARE @bitPlusIVATAx	AS BIT
	SET		@intPrLiId		= -1
	SET		@bitPlusIVATAx  = 'False'
	-- 1ro, si esta la lista que se pasa por parametro, que muestre esa.!!
	SELECT top 1	@intPrLiId = prli_id ,
					@bitPlusIVATAx=IsNull(is_prli_plusIVATax,'False')
		FROM	tbitemselection				WITH (NOLOCK)
		WHERE	comp_id = @comp_id
			AND (bra_id	= @bra_id OR bra_id IS NULL)
			AND prof_id = @prof_id
			AND prli_id = @intPriceListId
			AND prli_id IS NOT NULL
		ORDER BY is_order
	-- 2do: Si no la encuentra que muestre la primera que este definida para seleccion de articulos
	IF @intPrLiId = -1
		BEGIN
			SELECT top 1	@intPrLiId = prli_id ,
							@bitPlusIVATAx=IsNull(is_prli_plusIVATax,'False')
				FROM	tbitemselection
				WITH (NOLOCK)
				WHERE	 comp_id = @comp_id
					AND (bra_id	 = @bra_id OR bra_id IS NULL)
					AND  prof_id = @prof_id
					AND  prli_id IS NOT NULL
				ORDER BY is_order
		END
	-- --------------------------------------------


	DECLARE @tmpOnlyFathers AS TABLE(item_id INT PRIMARY KEY)
	INSERT INTO @tmpOnlyFathers(item_id)
		SELECT DISTINCT crl.item_id
			FROM tbItem ti
			LEFT JOIN  tbItemSizeColorRelation crl
			ON	crl.comp_id			= ti.comp_id  AND
				crl.item_id_child	= ti.item_id
			WHERE	crl.comp_id			= @comp_id  AND
					ti.item_disabled	= 'False'	--AND
					--crl.comp_id IS NULL




	DECLARE @tmpItemTable TABLE(	item_desc	NVARCHAR(500),
									item_id		INT,
									tmpOrder  int NOT NULL IDENTITY (1, 1 ))


	-- --------------------------------------------------------------------------------------------------------
	-- ATENCION!!!
	-- Si se modifica algo en la busqueda ver de hacerlo tanto en la por CODIGO como el la por DESCROPCION!!!!!
	-- --------------------------------------------------------------------------------------------------------
	DECLARE @tmpItemFilter TABLE(	item_id INT PRIMARY KEY,
									tmpOrder  int NOT NULL IDENTITY (1, 1 ))




	INSERT INTO @tmpItemFilter(item_id)
	SELECT	TOP (@count)	ti.item_id

		FROM		tbItem ti										WITH (NOLOCK)
		INNER JOIN tbItem_FastestSearch				AS tifs			WITH (NOLOCK)
			ON	tifs.comp_id = ti.comp_id AND
				tifs.item_id = ti.item_id
		LEFT JOIN @tmpBranchsOfBranchGroup tmp2
			ON tmp2.brag_id = ti.brag_id
		INNER JOIN @tmpOnlyFathers tmp
			ON tmp.item_id = ti.item_id

		WHERE		ti.comp_id = @comp_id	AND
					CASE
						WHEN ti.brag_id IS NOT NULL AND tmp2.brag_id IS NULL THEN 0
						WHEN ti.bra_id  IS NULL								THEN 1
						WHEN ti.bra_id  = @bra_id							THEN 1
						ELSE 0
					END = 1
		--AND			(ti.bra_id = @bra_id OR ti.bra_id IS NULL)
		AND			(
						(

							CASE
								-- --------------------------------------
								-- MOS 10-2021, para que busque con y sin acentos
								-- --------------------------------------
								WHEN (@selection_method = 0 AND tifs.item_desc LIKE @text + '%' )				THEN 'True'
								WHEN (@selection_method = 1 AND tifs.item_desc LIKE '%' + @text1 + '%')			THEN 'True'
								WHEN (@selection_method = 2 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%') THEN 'True'
								WHEN (@selection_method = 3 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%' AND tifs.item_desc LIKE '%' + @text3 + '%') THEN 'True'
								WHEN (@selection_method = 4 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%' AND tifs.item_desc LIKE '%' + @text3 + '%' AND tifs.item_desc LIKE '%' + @text4 + '%') THEN 'True'
								WHEN (@selection_method = 5 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%' AND tifs.item_desc LIKE '%' + @text3 + '%' AND tifs.item_desc LIKE '%' + @text4 + '%' AND tifs.item_desc LIKE '%' + @text5 + '%') THEN 'True'



								--WHEN (@selection_method = 0 AND ti.item_desc LIKE @text + '%' )				THEN 'True'
								--WHEN (@selection_method = 1 AND ti.item_desc LIKE '%' + @text1 + '%')		THEN 'True'
								--WHEN (@selection_method = 2 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%') THEN 'True'
								--WHEN (@selection_method = 3 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%') THEN 'True'
								--WHEN (@selection_method = 4 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%') THEN 'True'
								--WHEN (@selection_method = 5 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%') THEN 'True'
								-- --------------------------------------


								--WHEN (@selection_method = 6 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%' AND ti.item_desc LIKE '%' + @text6 + '%') THEN 'True'
								--WHEN (@selection_method = 7 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%' AND ti.item_desc LIKE '%' + @text6 + '%' AND ti.item_desc LIKE '%' + @text7 + '%') THEN 'True'
								--WHEN (@selection_method = 8 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%' AND ti.item_desc LIKE '%' + @text6 + '%' AND ti.item_desc LIKE '%' + @text7 + '%' AND ti.item_desc LIKE '%' + @text8 + '%') THEN 'True'
								--WHEN (@selection_method = 9 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%' AND ti.item_desc LIKE '%' + @text6 + '%' AND ti.item_desc LIKE '%' + @text7 + '%' AND ti.item_desc LIKE '%' + @text8 + '%' AND ti.item_desc LIKE '%' + @text9 + '%') THEN 'True'
								--WHEN (@selection_method =10 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%' AND ti.item_desc LIKE '%' + @text6 + '%' AND ti.item_desc LIKE '%' + @text7 + '%' AND ti.item_desc LIKE '%' + @text8 + '%' AND ti.item_desc LIKE '%' + @text9 + '%' AND ti.item_desc LIKE '%' + @text10 + '%') THEN 'True'
								ELSE 'False'
							END	= 'True'
						)
					)

		--AND	 ti.item_disabled = 'false'

		AND ti.comp_id IS NOT NULL
		ORDER BY ti.item_desc



	-- --------------------------------------------------------------------------------------------------------


	-- --------------------------------------------------------------------------------------------------------
	-- Insert Final
	-- --------------------------------------------------------------------------------------------------------
	INSERT INTO @tmpItemTable(item_desc, item_id)
		SELECT
					(dbo.fnStrPADR ( ISNULL(ti.item_desc,'') ,55,'.'))									+ '|' +
						   + '|' +
					CASE
						WHEN tpli.item_id IS NOT NULL AND @bitPlusIVATAx = 'False' THEN dbo.fnStrAllTrim( IsNull(tc.curr_symbol,'***') ) + ':' + dbo.fnStrPADL(convert(varchar,convert(decimal(10,2),IsNull(tpli.prli_price,0))) ,08,'0') + ''
						WHEN tpli.item_id IS NOT NULL AND @bitPlusIVATAx = 'True'  THEN dbo.fnStrAllTrim( IsNull(tc.curr_symbol,'***') ) + ':' + dbo.fnStrPADL(convert(varchar,convert(decimal(10,2),IsNull(tpli.prli_price,0) + (IsNull(tpli.prli_price,0) * dbo.fnItem_getDataByText_getTaxPercentage(ti.comp_id,ti.item_id) / 100))) ,08,'0') + ''
						ELSE '***:' + dbo.fnStrPADL(convert(varchar,convert(decimal(10,2),0 )) ,08,'0') + ''
					END		+ '|' +
					convert(varchar,ISNULL(ti.item_code,''))   -- OJOOOOOOO, Debe ser el ULTIMO Parametro y debe estar SOLO el CODIGOOO!!!!!
																																												[item_desc],
					ti.item_id																																					[item_id]
		FROM		tbItem ti										WITH (NOLOCK)

		INNER JOIN @tmpItemFilter tmp
			ON tmp.item_id = ti.item_id



		LEFT JOIN vwPriceListItems						tpli		WITH (NOLOCK)
			ON		tpli.comp_id = ti.comp_id
				AND tpli.item_id = ti.item_id
				AND tpli.prli_id = @intPrLiId

		LEFT JOIN tbsysCurrency							tc			WITH (NOLOCK)
			ON  tc.curr_id = tpli.curr_id

		ORDER BY	tmp.tmpOrder

	-- --------------------------------------------------------------------------------------------------------





	SELECT DISTINCT *
		FROM @tmpItemTable tmp
		ORDER BY tmp.tmpOrder


END
GO






--Fathers		= 2  'para wfmSaleOrderDetailSizeColor

CREATE  PROCEDURE [dbo].[spItem_getDataByText_onlyFathers]
(
	@text			NVARCHAR(300),
	@count			INT,
	@option			INT ,		-- No es Lang_id.... cambiar... asi nose hace.!!!!
	@comp_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@prof_id		INT,
	@intStorageId	INT,
	@intPriceListId INT


	--ATENCION: en este caso se aprovechó este parámetro (@option) que no se estaba
	--utilizando para seleccionar artículos relacionados a talles/colores
)
AS



BEGIN


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-12-08
	-- Parte		: 715
	-- Description	: Se agrega la funcionalidad que si en la cadena de búsqueda se separan palabras con la cadena '++'
	--				  estas palabras se buscan con coordinante 'and' y dentro de todo el texto y no sólo desde el principio
	-- =================================================================================================================


-- ---------------------------------------------------------------------
-- Testing
-- ---------------------------------------------------------------------
	/*
	DECLARE	@text			VARCHAR(300),
			@count			INT,
			@option		INT,
			@comp_id		INT,
			@bra_id			INT,
			@user_id		INT,
			@prof_id		INT,
			@intStorageId	INT,
			@intPriceListId INT
	SELECT 	@text			= '+a',
			@count			= 20,
			@option		= 0,
			@comp_id		= 1,
			@bra_id			= 1,
			@user_id		=42,
			@prof_id		=1,
			@intStorageId	=3,
			@intPriceListId =1
	*/
-- ---------------------------------------------------------------------

	SET @text = REPLACE(@text,'%','[%]')

	-- Tomo los Grupos de Sucursales a los que pertenece esta sucursal
	DECLARE @tmpBranchsOfBranchGroup TABLE(brag_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchsOfBranchGroup(brag_id)
		SELECT brag_id
			FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
			WHERE	tbgd.comp_id	= @comp_id AND
					tbgd.bra_id		= @bra_id



	-- Se agrega que ademas del + se pueda tipear un PUNTO
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'.','+')





	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	nvarchar(300)
	DECLARE @text1	nvarchar(300)
	DECLARE @text2	nvarchar(300)
	DECLARE @text3	nvarchar(300)
	DECLARE @text4	nvarchar(300)
	DECLARE @text5	nvarchar(300)
	--DECLARE @text6	nvarchar(300)
	--DECLARE @text7	nvarchar(300)
	--DECLARE @text8	nvarchar(300)
	--DECLARE @text9	nvarchar(300)
	--DECLARE @text10	nvarchar(300)
	--DECLARE @textFTS NVARCHAR(500)

	IF @selection_method > 0
	BEGIN
		--SET @textFTS = ''
		DECLARE cursor_data CURSOR LOCAL  FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
			BEGIN

				IF @text1 IS NULL SET @text1 = @text0 else
				IF @text2 IS NULL SET @text2 = @text0 else
				IF @text3 IS NULL SET @text3 = @text0 else
				IF @text4 IS NULL SET @text4 = @text0 else
				IF @text5 IS NULL SET @text5 = @text0 --else
				--IF @text6 IS NULL SET @text6 = @text0 else
				--IF @text7 IS NULL SET @text7 = @text0 else
				--IF @text8 IS NULL SET @text8 = @text0 else
				--IF @text9 IS NULL SET @text9 = @text0 else
				--IF @text10 IS NULL SET @text10 = @text0
				--IF @text0 <> '' AND @textFTS = ''
				--	BEGIN
				--		SET @textFTS = @text0
				--	END
				--ELSE IF @text0 <> '' AND @textFTS <> ''
				--	BEGIN
				--		SET @textFTS = @textFTS + ' AND '+ @text0
				--	END
				FETCH cursor_data INTO @text0
			END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- =================================================================================================================


	-- --------------------------------------------
	-- Busca el Deposito de la sucursal actual
	-- --------------------------------------------
	DECLARE @Stor_Id AS INT
	DECLARE @bra_ItemSearhOnlyWithStock AS BIT
	SELECT	@Stor_Id					= stor_id ,
			@bra_ItemSearhOnlyWithStock = IsNull(tb.bra_ItemSearhOnlyWithStock,'False')
		FROM	tbBranch tb
		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id
	IF @intStorageId <> -1	-- Si llega un deposito en particcular, pone ese.!
		BEGIN
			SET @Stor_Id = @intStorageId
		END
	-- --------------------------------------------


	-- --------------------------------------------
	-- Busca el Deposito de la sucursal actual
	-- --------------------------------------------
	DECLARE @intStoreIdAdditional AS INT
	SET		@intStoreIdAdditional = NULL
	SELECT  @intStoreIdAdditional = tisfqa.stor_id
		FROM tbItemStorageFastQueryAdditional tisfqa
		WHERE	tisfqa.comp_id	= @comp_id	AND
				tisfqa.bra_id	= @bra_id	AND
				tisfqa.prof_id	= @prof_id
	-- --------------------------------------------



	-- --------------------------------------------
	-- Busca la Lista de Precios a mostrar
	-- --------------------------------------------
	DECLARE @intPrLiId		AS INT
	DECLARE @bitPlusIVATAx	AS BIT
	SET		@intPrLiId		= -1
	SET		@bitPlusIVATAx  = 'False'
	-- 1ro, si esta la lista que se pasa por parametro, que muestre esa.!!
	SELECT top 1	@intPrLiId = prli_id ,
					@bitPlusIVATAx=IsNull(is_prli_plusIVATax,'False')
		FROM	tbitemselection				WITH (NOLOCK)
		WHERE	comp_id = @comp_id
			AND (bra_id	= @bra_id OR bra_id IS NULL)
			AND prof_id = @prof_id
			AND prli_id = @intPriceListId
			AND prli_id IS NOT NULL
		ORDER BY is_order
	-- 2do: Si no la encuentra que muestre la primera que este definida para seleccion de articulos
	IF @intPrLiId = -1
		BEGIN
			SELECT top 1	@intPrLiId = prli_id ,
							@bitPlusIVATAx=IsNull(is_prli_plusIVATax,'False')
				FROM	tbitemselection
				WITH (NOLOCK)
				WHERE	 comp_id = @comp_id
					AND (bra_id	 = @bra_id OR bra_id IS NULL)
					AND  prof_id = @prof_id
					AND  prli_id IS NOT NULL
				ORDER BY is_order
		END
	-- --------------------------------------------


	DECLARE @tmpOnlyFathers AS TABLE(item_id INT PRIMARY KEY)
	INSERT INTO @tmpOnlyFathers(item_id)
		SELECT DISTINCT crl.item_id
			FROM tbItemSizeColorRelation crl
			WHERE crl.comp_id = @comp_id



	DECLARE @tmpItemTable TABLE(	item_desc	NVARCHAR(500),
									item_id		INT,
									tmpOrder  int NOT NULL IDENTITY (1, 1 ))


	-- --------------------------------------------------------------------------------------------------------
	-- ATENCION!!!
	-- Si se modifica algo en la busqueda ver de hacerlo tanto en la por CODIGO como el la por DESCROPCION!!!!!
	-- --------------------------------------------------------------------------------------------------------
	DECLARE @tmpItemFilter TABLE(	item_id INT PRIMARY KEY,
									tmpOrder  int NOT NULL IDENTITY (1, 1 ))




	INSERT INTO @tmpItemFilter(item_id)
	SELECT	TOP (@count)	ti.item_id

		FROM		tbItem ti										WITH (NOLOCK)
		INNER JOIN tbItem_FastestSearch				AS tifs			WITH (NOLOCK)
			ON	tifs.comp_id = ti.comp_id AND
				tifs.item_id = ti.item_id
		LEFT JOIN @tmpBranchsOfBranchGroup tmp2
			ON tmp2.brag_id = ti.brag_id
		INNER JOIN @tmpOnlyFathers tmp
			ON tmp.item_id = ti.item_id

		WHERE		ti.comp_id = @comp_id	AND
					CASE
						WHEN ti.brag_id IS NOT NULL AND tmp2.brag_id IS NULL THEN 0
						WHEN ti.bra_id  IS NULL								THEN 1
						WHEN ti.bra_id  = @bra_id							THEN 1
						ELSE 0
					END = 1
		--AND			(ti.bra_id = @bra_id OR ti.bra_id IS NULL)
		AND			(
						(

							CASE

								-- --------------------------------------
								-- MOS 10-2021, para que busque con y sin acentos
								-- --------------------------------------
								WHEN (@selection_method = 0 AND tifs.item_desc LIKE @text + '%' )				THEN 'True'
								WHEN (@selection_method = 1 AND tifs.item_desc LIKE '%' + @text1 + '%')			THEN 'True'
								WHEN (@selection_method = 2 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%') THEN 'True'
								WHEN (@selection_method = 3 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%' AND tifs.item_desc LIKE '%' + @text3 + '%') THEN 'True'
								WHEN (@selection_method = 4 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%' AND tifs.item_desc LIKE '%' + @text3 + '%' AND tifs.item_desc LIKE '%' + @text4 + '%') THEN 'True'
								WHEN (@selection_method = 5 AND tifs.item_desc LIKE '%' + @text1 + '%' AND tifs.item_desc LIKE '%' + @text2 + '%' AND tifs.item_desc LIKE '%' + @text3 + '%' AND tifs.item_desc LIKE '%' + @text4 + '%' AND tifs.item_desc LIKE '%' + @text5 + '%') THEN 'True'



								--WHEN (@selection_method = 0 AND ti.item_desc LIKE @text + '%' )				THEN 'True'
								--WHEN (@selection_method = 1 AND ti.item_desc LIKE '%' + @text1 + '%')		THEN 'True'
								--WHEN (@selection_method = 2 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%') THEN 'True'
								--WHEN (@selection_method = 3 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%') THEN 'True'
								--WHEN (@selection_method = 4 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%') THEN 'True'
								--WHEN (@selection_method = 5 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%') THEN 'True'
								-- --------------------------------------



								--WHEN (@selection_method = 6 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%' AND ti.item_desc LIKE '%' + @text6 + '%') THEN 'True'
								--WHEN (@selection_method = 7 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%' AND ti.item_desc LIKE '%' + @text6 + '%' AND ti.item_desc LIKE '%' + @text7 + '%') THEN 'True'
								--WHEN (@selection_method = 8 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%' AND ti.item_desc LIKE '%' + @text6 + '%' AND ti.item_desc LIKE '%' + @text7 + '%' AND ti.item_desc LIKE '%' + @text8 + '%') THEN 'True'
								--WHEN (@selection_method = 9 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%' AND ti.item_desc LIKE '%' + @text6 + '%' AND ti.item_desc LIKE '%' + @text7 + '%' AND ti.item_desc LIKE '%' + @text8 + '%' AND ti.item_desc LIKE '%' + @text9 + '%') THEN 'True'
								--WHEN (@selection_method =10 AND ti.item_desc LIKE '%' + @text1 + '%' AND ti.item_desc LIKE '%' + @text2 + '%' AND ti.item_desc LIKE '%' + @text3 + '%' AND ti.item_desc LIKE '%' + @text4 + '%' AND ti.item_desc LIKE '%' + @text5 + '%' AND ti.item_desc LIKE '%' + @text6 + '%' AND ti.item_desc LIKE '%' + @text7 + '%' AND ti.item_desc LIKE '%' + @text8 + '%' AND ti.item_desc LIKE '%' + @text9 + '%' AND ti.item_desc LIKE '%' + @text10 + '%') THEN 'True'
								ELSE 'False'
							END	= 'True'
						)
					)

		AND	 ti.item_disabled = 'false'

		AND ti.comp_id IS NOT NULL
		ORDER BY ti.item_desc



	-- --------------------------------------------------------------------------------------------------------


	-- --------------------------------------------------------------------------------------------------------
	-- Insert Final
	-- --------------------------------------------------------------------------------------------------------
	INSERT INTO @tmpItemTable(item_desc, item_id)
		SELECT
					(dbo.fnStrPADR ( ISNULL(ti.item_desc,'') ,55,'.'))									+ '|' +
						   + '|' +
					CASE
						WHEN tpli.item_id IS NOT NULL AND @bitPlusIVATAx = 'False' THEN dbo.fnStrAllTrim( IsNull(tc.curr_symbol,'***') ) + ':' + dbo.fnStrPADL(convert(varchar,convert(decimal(10,2),IsNull(tpli.prli_price,0))) ,08,'0') + ''
						WHEN tpli.item_id IS NOT NULL AND @bitPlusIVATAx = 'True'  THEN dbo.fnStrAllTrim( IsNull(tc.curr_symbol,'***') ) + ':' + dbo.fnStrPADL(convert(varchar,convert(decimal(10,2),IsNull(tpli.prli_price,0) + (IsNull(tpli.prli_price,0) * dbo.fnItem_getDataByText_getTaxPercentage(ti.comp_id,ti.item_id) / 100))) ,08,'0') + ''
						ELSE '***:' + dbo.fnStrPADL(convert(varchar,convert(decimal(10,2),0 )) ,08,'0') + ''
					END		+ '|' +
					convert(varchar,ISNULL(ti.item_code,''))   -- OJOOOOOOO, Debe ser el ULTIMO Parametro y debe estar SOLO el CODIGOOO!!!!!
																																												[item_desc],
					ti.item_id																																					[item_id]
		FROM		tbItem ti										WITH (NOLOCK)

		INNER JOIN @tmpItemFilter tmp
			ON tmp.item_id = ti.item_id



		LEFT JOIN vwPriceListItems						tpli		WITH (NOLOCK)
			ON		tpli.comp_id = ti.comp_id
				AND tpli.item_id = ti.item_id
				AND tpli.prli_id = @intPrLiId

		LEFT JOIN tbsysCurrency							tc			WITH (NOLOCK)
			ON  tc.curr_id = tpli.curr_id

		ORDER BY	tmp.tmpOrder

	-- --------------------------------------------------------------------------------------------------------





	SELECT DISTINCT *
		FROM @tmpItemTable tmp
		ORDER BY tmp.tmpOrder


END
GO



--NO SE USA MAS ESTE SP, SE REEMPLAZO EN GENERACION AUTOMATICA EN PURCHASEORDER POR EL SP [spPurchaseOrder_getItems4GenerationAutomatic]


CREATE PROCEDURE [dbo].[spItem_getDataForPurchaseOrders]
(
		@comp_id			Int,
		@bra_id				INT,
		@guid				UNIQUEIDENTIFIER,
		--@Item_id			Int,
		--@brand_id         Int,
		--@cat_id				Int,
		--@subcat_id			Int,
		--@supp_id			Int,
		@pf_id				int,
		@stor_id			Int,
		@pQuestion          BIT,
		@guidItem			UNIQUEIDENTIFIER
)
as
set nocount on

/*
declare	@comp_id			Int,
		@bra_id				INT,
		@guid				UNIQUEIDENTIFIER,
		@Item_id			Int,
		@brand_id           Int,
		@cat_id				Int,
		@subcat_id			Int,
		@supp_id			Int,
		@pf_id				INT,
		@stor_id			Int,
		@pQuestion          bit
select 	@comp_id			= 1,
		@bra_id				= 1,
		@guid				='ccdd876d-7c07-4cfe-9a64-ffd00422ed21',
		@Item_id			=-1,
		@brand_id			=-1,
		@cat_id				=-1,
		@subcat_id			=-1,
		@supp_id			=-1,
		@pf_id				=-1,
		@stor_id			=-1,
		@pQuestion          ='true'

DROP TABLE #tmp_items


*/





	DECLARE @lGuidItem AS UNIQUEIDENTIFIER

	SET @lGuidItem = CONVERT(UNIQUEIDENTIFIER,@guidItem)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuidItem     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------


If @pQuestion = 'True'
Begin
   DELETE FROM tbPurchaseOrderDetailTmp
   WHERE	comp_id		= @comp_id
   AND		podt_guid	= @guid
   AND		NOT podt_Selection IS NULL

--else
 --	begin
declare @data			VARCHAR(4000)
declare @operation		VARCHAR(4000)
declare @query			VARCHAR(4000)

CREATE TABLE #tmp_items ( item_id INT, qty DECIMAL(18,5) )

IF @pf_id = -1
BEGIN

	DECLARE @litem_id INT, @lpf_id INT
	DECLARE crsr_items CURSOR LOCAL FAST_FORWARD  FOR
	SELECT item_id, pf_id
	FROM tbItem ti
	WHERE ti.comp_id = @comp_id
	OPEN crsr_items
	FETCH crsr_items INTO @litem_id, @lpf_id
	WHILE @@FETCH_STATUS = 0
	BEGIN


		SELECT	@data		= ''
		FROM	dbo.tbPurchaseFormula
		WHERE	comp_id		= @comp_id
		AND		pf_id		= @lpf_id


		SELECT	@operation	= ''
		FROM	dbo.tbPurchaseFormula
		WHERE	comp_id		= @comp_id
		AND		pf_id		= @lpf_id


		SELECT	@data		= REPLACE(@data,'@comp_id', @comp_id)
		SELECT	@data		= REPLACE(@data,'@stor_id', @stor_id)


		SELECT	@query = 'insert into #tmp_items ( item_id, qty )
							select item_id, (' + @operation + ') [qty]
							from tbitem
							where ' + @data + '
							and comp_id = ' + convert(varchar,@comp_id) + '
							and item_id = ' + convert(varchar,@litem_id)


		BEGIN TRY

			EXEC	(@query)

		END TRY
		BEGIN CATCH

			SELECT	@query = 'insert into #tmp_items ( item_id, qty )
							select item_id, -999 [qty]
							from tbitem
							where comp_id = ' + convert(varchar,@comp_id) + '
							and   item_id = ' + convert(varchar,@litem_id)
			--SELECT @query
			EXEC	(@query)

		END CATCH


		FETCH crsr_items INTO @litem_id, @lpf_id
	END
	CLOSE crsr_items
	DEALLOCATE crsr_items

END
ELSE
BEGIN

	SELECT	@data		= ''
	FROM	dbo.tbPurchaseFormula
	WHERE	comp_id		= @comp_id
	AND		pf_id		= @pf_id


	SELECT	@operation	= ''
	FROM	dbo.tbPurchaseFormula
	WHERE	comp_id		= @comp_id
	AND		pf_id		= @pf_id


	SELECT	@data		= REPLACE(@data,'@comp_id', @comp_id)
	SELECT	@data		= REPLACE(@data,'@stor_id', @stor_id)


	SELECT	@query = 'insert into #tmp_items ( item_id, qty ) select item_id, (' + @operation + ') [qty] from tbitem where ' + @data + ' and comp_id = ' + convert(varchar,@comp_id)

	BEGIN TRY

		EXEC	(@query)

	END TRY
	BEGIN CATCH

		SELECT	@query = 'insert into #tmp_items ( item_id, qty )
						select item_id, -999 [qty]
						from tbitem
						where comp_id = ' + convert(varchar,@comp_id) + '
						and   item_id = ' + convert(varchar,@litem_id)
		--SELECT @query
		EXEC	(@query)

	END CATCH

END

--SELECT * FROM #tmp_items






		INSERT INTO tbPurchaseOrderDetailTmp
		(
			comp_id,
			podt_guid,
			item_id,
			curr_id,
			bra_id,
			cont_id,
			tax_id,
			podt_qty,
			podt_price,
			podt_cd,
			podt_isProcessed,
			podt_Selection
		)

				SELECT	@comp_id,
						@guid,
						ti.item_id,
						1, --averiguar
						1, --averiguar
						NULL, --averiguar
						NULL, --averiguar
						sum(tmp.qty),
						CASE CONVERT(BIT, tb2.bra_costlist_type)
							WHEN 'TRUE' THEN ticl.coslis_price
							ELSE ticl.coslis_price_aw
						END,
						GETDATE(),
						NULL,
						'False'


				From	tbItem									ti

						INNER JOIN #tmp_items					tmp
						ON	tmp.item_id		=	ti.item_id
						AND tmp.qty			>= 0

						INNER JOIN @tblComplexFilter_Items		tempITEM
						ON tempitem.item_id	= ti.item_id

						left join tbBrand						tb
						On  tb.comp_id		=   ti.comp_id
						And tb.brand_id		=   ti.brand_id

						left Join tbCategory					tc
						On  tc.comp_id		=   ti.comp_id
						And tc.cat_id		=   ti.cat_id

						left Join tbSubCategory					tsc
						On  tsc.comp_id		=   ti.comp_id
						And tsc.cat_id		=   ti.cat_id
						And tsc.subcat_id	=   ti.subcat_id

						left Join tbSupplier					ts
						On  ts.comp_id		=   ti.comp_id
						And ts.supp_id		=   ti.supp_id

						Inner JOIN tbItemStorage				tis
						On	tis.comp_id		=	ti.comp_id
						AND tis.item_id		=	ti.item_id


						INNER JOIN tbBranch tb2
						ON tb2.comp_id = ti.comp_id
						AND tb2.bra_id = @bra_id

						left JOIN tbItemCostList ticl
						ON	ticl.comp_id   = ti.comp_id
						And	ticl.coslis_id = tb2.bra_id
						And	ticl.item_id	= ti.item_id



				where	ti.comp_id	= @comp_id
			--	And    (@Item_id	= -1  Or	ti.item_id		= @Item_id	)
			--	And    (@brand_id	= -1  Or	tb.brand_id		= @brand_id	)
			--	And    (@cat_id		= -1  Or	tc.cat_id		= @cat_id	)
			--	And    (@subcat_id	= -1  Or	tsc.subcat_id	= @subcat_id)
			--	And    (@supp_id	= -1  Or	ts.supp_id		= @supp_id	)
				And    (@stor_id    = -1  Or	tis.stor_id		= @stor_id	)

				GROUP BY ti.item_id,
						 tb2.bra_costlist_type,
						 ticl.coslis_price,
						 ticl.coslis_price_aw

				/*ORDER BY ti.item_code,
						ti.item_desc,
						tb.brand_desc,
						tc.cat_desc,
						tsc.subcat_desc,
						ts.supp_name*/

				UNION ALL

				Select	distinct @comp_id,
						@guid,
						ti.item_id,
						1, --averiguar
						1, --averiguar
						NULL, --averiguar
						NULL, --averiguar
						tmp.qty,
						CASE CONVERT(BIT, tb2.bra_costlist_type)
							WHEN 'TRUE' THEN ticl.coslis_price
							ELSE ticl.coslis_price_aw
						END,
						GETDATE(),
						NULL,
						'False'

				--		distinct ti.item_code,
				--		ti.item_desc,
				--		tb.brand_desc,
				--		tc.cat_desc,
				--		tsc.subcat_desc,
				--		ts.supp_name,
				--		ti.item_cantMin,
				--		ti.item_cantOpt,
				--		tmp.qty		[qty],
				--		ti.item_id


				From	tbItem									ti

						INNER JOIN #tmp_items					tmp
						ON	tmp.item_id		=	ti.item_id
						AND tmp.qty			<  0

						INNER JOIN @tblComplexFilter_Items		tempITEM
						ON tempitem.item_id	= ti.item_id

						left join tbBrand						tb
						On  tb.comp_id		=   ti.comp_id
						And tb.brand_id		=   ti.brand_id

						left Join tbCategory					tc
						On  tc.comp_id		=   ti.comp_id
						And tc.cat_id		=   ti.cat_id

						left Join tbSubCategory					tsc
						On  tsc.comp_id		=   ti.comp_id
						And tsc.cat_id		=   ti.cat_id
						And tsc.subcat_id	=   ti.subcat_id

						left Join tbSupplier					ts
						On  ts.comp_id		=   ti.comp_id
						And ts.supp_id		=   ti.supp_id

						Inner JOIN tbItemStorage				tis
						On	tis.comp_id		=	ti.comp_id
						AND tis.item_id		=	ti.item_id

						INNER JOIN tbBranch tb2
						ON tb2.comp_id = ti.comp_id
						AND tb2.bra_id = @bra_id

						left JOIN tbItemCostList ticl
						ON	ticl.comp_id   = ti.comp_id
						And	ticl.coslis_id = tb2.bra_id
						And	ticl.item_id	= ti.item_id

				where	ti.comp_id	= @comp_id
			--	And    (@Item_id	= -1  Or	ti.item_id		= @Item_id	)
			--	And    (@brand_id	= -1  Or	tb.brand_id		= @brand_id	)
			--	And    (@cat_id		= -1  Or	tc.cat_id		= @cat_id	)
			--	And    (@subcat_id	= -1  Or	tsc.subcat_id	= @subcat_id)
			--	And    (@supp_id	= -1  Or	ts.supp_id		= @supp_id	)
				And    (@stor_id    = -1  Or	tis.stor_id		= @stor_id	)


END



SELECT	' ' [ ],
		tpodt.podt_Selection,
		ti.item_code,
		ti.item_desc,
		tb.brand_desc,
		tc.cat_desc,
		tsc.subcat_desc,
		ts.supp_name,
		--deposito
		ISNULL(ts2.stor_desc,'') [stor_desc],
		ti.item_cantMin,
		ti.item_cantOpt,
		tpodt.podt_qty		[qty],
		tpodt.item_id

FROM	tbPurchaseOrderDetailTmp				tpodt

		INNER JOIN tbItem						ti
		ON	ti.comp_id		=	tpodt.comp_id
		AND ti.item_id		=	tpodt.item_id

		left join tbBrand						tb
		On  tb.comp_id		=   ti.comp_id
		And tb.brand_id		=   ti.brand_id

		left Join tbCategory					tc
		On  tc.comp_id		=   ti.comp_id
		And tc.cat_id		=   ti.cat_id

		left Join tbSubCategory					tsc
		On  tsc.comp_id		=   ti.comp_id
		And tsc.cat_id		=   ti.cat_id
		And tsc.subcat_id	=   ti.subcat_id

		left Join tbSupplier					ts
		On  ts.comp_id		=   ti.comp_id
		And ts.supp_id		=   ti.supp_id

		Left Join tbBranch tb2
		On tb2.comp_id		= tpodt.comp_id
		And TB2.bra_id		= tpodt.bra_id

		Left Join tbStorage ts2
		On  ts2.comp_id		= tb2.comp_id
		And ts2.stor_id		= tb2.stor_id



WHERE	tpodt.comp_id	=	@comp_id
AND 	tpodt.podt_guid =	@guid
And		Not tpodt.podt_Selection Is Null

--Group By ts2.stor_desc,
--		tpodt.podt_Selection,
--		ti.item_code,
--		ti.item_desc,
--		tb.brand_desc,
--		tc.cat_desc,
--		tsc.subcat_desc,
--		ts.supp_name,ti.item_cantMin,
--		ti.item_cantOpt,
--		tpodt.podt_qty	,
--		tpodt.item_id

--Order By ts2.stor_desc
GO





CREATE PROCEDURE [dbo].[spItem_getDataForWeb]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@cat_id				INT,
	@subcat_id			INT,
	@brand_id			INT,
	@pres_id			INT,
	@prli_id			INT,
	@stor_id			INT,
	@showzerostock		BIT,
	@option				INT,
	@ws_id				INT,
	@searchtext			NVARCHAR(4000)
)
AS

BEGIN



	SET NOCOUNT ON



	/*
	DECLARE @comp_id		INT,
			@lang_id		INT,
			@bra_id			INT,
			@cat_id			INT,
			@subcat_id		INT,
			@brand_id		INT,
			@pres_id		INT,
			@prli_id		INT,
			@stor_id		INT,
			@showzerostock	BIT,
			@option			INT,
			@ws_id			INT,
			@searchtext		NVARCHAR(4000)
	SELECT  @comp_id		=1,
			@lang_id		=2,
			@bra_id			=1,
			@cat_id			=-1,
			@subcat_id		=-1,
			@brand_id		=-1,
			@pres_id		=-1,
			@prli_id		=1,
			@stor_id		=1,
			@showzerostock	='true',
			@option			=1,
			@ws_id			=9,
			@searchtext		='fundada'
	DROP TABLE #tmpWords
	--DROP TABLE #tmpAStock
	--DROP TABLE #tmpSearchText
	DROP TABLE #tmpItems
	DROP TABLE #tmpSearchText_Spaces --, #tmpSearchText_OR--, #tmpSearchText_AND
	*/



	--99
	-- -----------------------------------------------------------
	-- Trae de que manera debe mostrarse el precio (Moneda)
	-- -----------------------------------------------------------
	DECLARE @intCurrId2PriceConvert AS INT
	SET		@intCurrId2PriceConvert = -1
	SELECT  @intCurrId2PriceConvert	= twsn.ws_curr_id4Prices
		FROM tbWebSite_Names twsn
		WHERE	twsn.comp_id	= @comp_id AND
				twsn.ws_id		= @ws_id
	-- -----------------------------------------------------------



	SELECT	isnull(twspccd.swscc_id,0)		[swscc_id],
			isnull(twswn.wswn_desc,'')		[wswn_desc]
	INTO	#tmpWords
	FROM	tbWebSite_ParagraphComponentsControlsData	twspccd		WITH (NOLOCK)
			LEFT JOIN tbWebSite_WordsNew				twswn		WITH (NOLOCK)
			ON	twswn.lang_id	= @lang_id
			AND twswn.wswi_id	= twspccd.wspcc_wswi_id
	WHERE	twspccd.comp_id		= @comp_id
	AND		twspccd.ws_id		= @ws_id
	AND		twspccd.swsc_id		= @option
	AND		twspccd.swscc_id	IN (102,75)










	-- ===========================================================================================================
	-- cargamos en una tabla temporal sólo los artículos que componen el criterio de búsqueda del control buscador
	-- ===========================================================================================================

	-- creamos la temporal de artículos que componen el criterio de búsqueda
	CREATE TABLE #tmpItems (item_id INT)


	IF len(@searchtext) > 0
	BEGIN

		-- primero separamos por espacios las palabras a buscar en una tabla
		SELECT	fst.items
		INTO	#tmpSearchText_Spaces
		FROM	dbo.fnSplitTableWithSpaces (@searchtext,' ') fst
		--SELECT  items  FROM #tmpSearchText_Spaces



		-- variable donde se generará el query correspondiente a la búsqueda
		DECLARE @query NVARCHAR(4000)


		SET @query =			'INSERT INTO #tmpItems SELECT DISTINCT ti.item_id '
		SET @query = @query +	'FROM tbItem ti			WITH (NOLOCK)'
		SET @query = @query +	'LEFT JOIN tbBrand tb2	WITH (NOLOCK)
									ON tb2.brand_id = ti.brand_id AND tb2.comp_id = ti.comp_id '
		SET @query = @query +	'WHERE ti.comp_id = ' + convert(VARCHAR,@comp_id) + ' and '

		DECLARE @items  NVARCHAR(4000)

		-- cursor para recorrer las palabras
		DECLARE cursor_palabras CURSOR LOCAL FAST_FORWARD FOR
		SELECT items FROM #tmpSearchText_Spaces

		OPEN cursor_palabras

		FETCH cursor_palabras INTO @items

		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @query = @query + '( ti.item_desc LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'ti.item_code LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'ti.item_detail LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'ti.item_vendorCode LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'tb2.brand_desc LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'ti.item_annotation LIKE ''%' + @items + '%'') and '

			FETCH cursor_palabras INTO @items
		END

		CLOSE cursor_palabras
		DEALLOCATE cursor_palabras

		-- se elimina el último texto ' and' generado en el loop del cursor
		SELECT @query = SUBSTRING(@query, 1, LEN(@query) - 4)
		--SELECT @query


		-- se ejecuta el query y se carga la temporal antes definida
		EXEC (@query)

	END

	ELSE

	BEGIN

		INSERT	INTO #tmpItems
		SELECT	ti.item_id
		FROM	tbItem ti
		WHERE	ti.comp_id = @comp_id

	END

	--SELECT * FROM #tmpItems
	-- ===========================================================================================================


	DECLARE @tmpAStock  as TABLE(	item_id INT PRIMARY KEY,
									AStock DECIMAL(19,2))



	-- ==========================================================================================================
	--como en el query principal se necesita recuperar el stock potencial en 5 lugares diferentes,
	--lo que hacía necesario utilizar la función fnGetAStock que obtiene el stock potencial en
	--5 lugares, se decide cargar una tabla temporal utilizando la función mencionada sólo una vez,
	--y luego en el query principal se joinea con esta tabla temporal
	INSERT INTO @tmpAStock (item_id,AStock)
	SELECT	ti.item_id,
			dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99)		[AStock]

	--INTO	#tmpAStock

		FROM	tbItem ti														WITH (NOLOCK)
		INNER JOIN #tmpItems tmpI
			ON tmpI.item_id = ti.item_id

		LEFT JOIN tbWebSite_OnSaleAndNewness wsOferta			WITH (NOLOCK)
			ON wsOferta.comp_id			= @comp_id		AND
				wsOferta.ws_id			= @ws_id		AND
				wsOferta.item_id		= ti.item_id	AND
				wsOferta.wso_type		= 1				AND
				wsOferta.wso_Disabled	= 'False'

		LEFT JOIN tbWebSite_OnSaleAndNewness wsNovedad			WITH (NOLOCK)
			ON  wsNovedad.comp_id		= @comp_id		AND
				wsNovedad.ws_id			= @ws_id		AND
				wsNovedad.item_id		= ti.item_id	AND
				wsNovedad.wso_type		= 2				AND
				wsNovedad.wso_Disabled	= 'False'
		WHERE	ti.comp_id = @comp_id
		AND		ISNULL(ti.item_web,'false')			= 'true'
		AND		ISNULL(ti.item_disabled,'false')	= 'false'
		AND		ISNULL(ti.item_not4Sale,'false')	= 'false'
		AND		(
					(@option = 1)													-- items (todos)
					OR
							(@option = 2 AND wsOferta.item_id  IS NOT NULL /*ISNULL(ti.item_liquidation,'false') = 'true'*/)	-- ofertas
							OR
							(@option = 3 AND wsNovedad.item_id IS NOT NULL /*ISNULL(ti.item_newness,'false')	 = 'true'*/)	-- novedades
				)

		AND		(@cat_id	= -1	OR ti.cat_id	= @cat_id	)
		AND		(@subcat_id = -1	OR ti.subcat_id = @subcat_id)
		AND		(@brand_id	= -1	OR ti.brand_id	= @brand_id	)
		AND		(@pres_id	= -1	OR ti.pres_id	= @pres_id	)

	--SELECT * FROM #tmpAStock
	-- ==========================================================================================================





	-- ==========================================================================================================
	-- recuperamos el límite de stock potencial y la marca indicadora de como mostrar los precios del web_site seleccionado
	-- ==========================================================================================================
	DECLARE @ws_PotentialStockLimit		INT,
			@ws_showpricewithtax		BIT,
			@ws_griddesign_maxlength_desc	INT

	SELECT	@ws_PotentialStockLimit			= twsn.ws_PotentialStockLimit,
			@ws_showpricewithtax			= isnull(twsn.ws_showpricewithtax,'false'),
			@ws_griddesign_maxlength_desc	= ISNULL(twsn.ws_griddesign_maxlength_desc,100)

		FROM	tbWebSite_Names				twsn		WITH (NOLOCK)

		WHERE	twsn.comp_id	= @comp_id
		AND		twsn.ws_id		= @ws_id
	--SELECT @ws_PotentialStockLimit, @ws_showpricewithtax
	-- ==========================================================================================================





	-- ==========================================================================================================
	SELECT	--ti.item_code, ti.item_vendorCode,
			--isnull(tc.cat_web_order,999999) [c], isnull(tsc.subcat_web_order,99999) [sc],
			tc.cat_desc,
			tsc.subcat_desc,
			--' ' [ ],

			ti.item_id,

			SUBSTRING
				(
					CASE	WHEN ti.item_WebSite_desc					 IS NULL THEN ti.item_desc
							WHEN LEN(ltrim(rtrim(ti.item_WebSite_desc))) = 0	 THEN ti.item_desc
							ELSE ti.item_WebSite_desc
					END
				,1,@ws_griddesign_maxlength_desc)				[item_desc],

			ti.curr_id,
			isnull(tb.stor_id,-1)								[stor_id],
			isnull(ti.cat_id,-1)								[cat_id],

			isnull(ti.subcat_id,-1)								[subcat_id],
			isnull(ti.subcataux_id,-1)							[subcataux_id],

			ti.item_picture,


			CASE --99
				WHEN @intCurrId2PriceConvert <> -1 AND @ws_showpricewithtax = 'true' THEN
										LTRIM(RTRIM(ISNULL(tsc33.curr_symbol,''))) + ' ' +
										CONVERT(NVARCHAR,
											dbo.fnGetExchange2(	@comp_id,
																isnull(tpli.prli_price,0) + (isnull(tpli.prli_price,0) * ttn.tax_percentage / 100),
																tpli.curr_id,
																@intCurrId2PriceConvert,
																0,
																0,
																0,
																'False')
												)
				--99
				WHEN @intCurrId2PriceConvert <> -1 AND @ws_showpricewithtax = 'False' THEN
										LTRIM(RTRIM(ISNULL(tsc33.curr_symbol,''))) + ' ' +
										CONVERT(NVARCHAR,
											dbo.fnGetExchange2(	@comp_id,
																isnull(tpli.prli_price,0),
																tpli.curr_id,
																@intCurrId2PriceConvert,
																0,
																0,
																0,
																'False')
												)

				WHEN @ws_showpricewithtax = 'true' THEN
										LTRIM(RTRIM(ISNULL(tscy.curr_symbol,''))) + ' ' +
										CONVERT(NVARCHAR,
												isnull(tpli.prli_price,0) + (isnull(tpli.prli_price,0) * ttn.tax_percentage / 100)
												)
				ELSE
										LTRIM(RTRIM(ISNULL(tscy.curr_symbol,''))) + ' ' +
										CONVERT(NVARCHAR,
												isnull(tpli.prli_price,0)
												)
				END		[item_price],
			--ISNULL(tpli.prli_price,0),
			--ttn.tax_percentage,

			--isnull(ts.itst_cant,0)								[itst_cant],
			--dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99)		[itst_cant],
			CONVERT(integer,(tmpAStock.AStock * @ws_PotentialStockLimit / 100))	[itst_cant],


			tut2.utexts_desc									[buy],
			tut1.utexts_desc									[info],
			isnull(ti.item_annotation,'')						[item_annotation],
			--ti.item_id,
			tc.cat_desc + ' - ' + tsc.subcat_desc				[desc],
			isnull(ti.item_detail,'')							[item_detail],
			isnull(ti.item_annotation1,'')						[item_annotation1],
			isnull(ti.item_annotation2,'')						[item_annotation2],
			ti.item_web,

												[signal],
			CASE
				WHEN NOT ISNULL(tmpAStock.AStock,0) < ti.item_cantOpt							THEN 'g'
				WHEN	 ISNULL(tmpAStock.AStock,0) BETWEEN ti.item_cantMin AND ti.item_cantOpt	THEN 'y'
				WHEN	 ISNULL(tmpAStock.AStock,0) < ti.item_cantMin							THEN 'r'
			END													[signal],


			LTRIM(RTRIM(ISNULL(tscy.curr_symbol,'')))			[curr_symbol],

			CASE WHEN @ws_showpricewithtax = 'true' THEN
						CONVERT(NVARCHAR,ISNULL(tpli.prli_price,0) + (ISNULL(tpli.prli_price,0) * ttn.tax_percentage / 100))
				ELSE
						CONVERT(NVARCHAR,ISNULL(tpli.prli_price,0))
				END		[prli_price],

			--ISNULL(tpli.prli_price,0)							[prli_price],


			CASE WHEN LEN(ti.item_desc) > 50 THEN SUBSTRING(ti.item_desc,1,47) + '...' ELSE ti.item_desc END +
			'|'+
			isnull(tmpPrice.wswn_desc,'') +
			'|'+
			LTRIM(RTRIM(ISNULL(tscy.curr_symbol,''))) + ' ' +
				CASE WHEN @ws_showpricewithtax = 'true' THEN
						CONVERT(NVARCHAR,ISNULL(tpli.prli_price,0) + (ISNULL(tpli.prli_price,0) * ttn.tax_percentage / 100))
				ELSE
						CONVERT(NVARCHAR,ISNULL(tpli.prli_price,0))
				END	 +
			'|'+
			isnull(tmpStock.wswn_desc,'') +
			'|'+
			CONVERT(VARCHAR,ISNULL(tmpAStock.AStock,0))			[grid_desc],

			ISNULL(tb2.brand_desc,'')							[brand_desc],
			ISNULL(tp.pres_desc,'')								[pres_desc],

			ti.item_id											[ID]


	FROM	tbItem									ti				WITH (NOLOCK)

			INNER JOIN #tmpItems					tmpI
			ON	tmpI.item_id	= ti.item_id

			LEFT JOIN tbBranch						tb				WITH (NOLOCK)
			ON	tb.comp_id		= ti.comp_id
			AND tb.bra_id		= ti.bra_id

			INNER JOIN tbCategory					tc				WITH (NOLOCK)
			ON	tc.comp_id		= ti.comp_id
			AND tc.cat_id		= ti.cat_id


			INNER JOIN tbSubCategory					tsc				WITH (NOLOCK)
			ON	tsc.cat_id		= ti.cat_id
			AND tsc.subcat_id	= ti.subcat_id
			AND tsc.comp_id		= ti.comp_id


			LEFT JOIN tbPriceListItems				tpli			WITH (NOLOCK)
			ON	tpli.comp_id		= ti.comp_id
			AND tpli.item_id		= ti.item_id
			AND tpli.prli_id		= @prli_id



			LEFT JOIN tbsysCurrency					tscy			WITH (NOLOCK)
			ON	tscy.curr_id			= tpli.curr_id

--99
			LEFT JOIN tbsyscurrency					tsc33
				ON tsc33.curr_id		= @intCurrId2PriceConvert


			INNER JOIN tbsysUniqueTexts				tut1			WITH (NOLOCK)
				ON	tut1.lang_id		= @lang_id
				AND tut1.utexts_id		= 224012
			INNER JOIN tbsysUniqueTexts				tut2			WITH (NOLOCK)
				ON	tut2.lang_id		= @lang_id
				AND tut2.utexts_id		= 224013

			LEFT JOIN #tmpWords		tmpStock
			ON tmpStock.swscc_id	= 102
			LEFT JOIN #tmpWords		tmpPrice
			ON tmpPrice.swscc_id	= 75

			INNER JOIN @tmpAStock		tmpAStock
			ON	ti.item_id			= tmpAStock.item_id

			LEFT JOIN tbBrand			tb2							WITH (NOLOCK)
				ON	tb2.brand_id		= ti.brand_id
				AND tb2.comp_id			= ti.comp_id

			INNER JOIN tbPresentation	tp							WITH (NOLOCK)
				ON	tp.comp_id			= ti.comp_id
				AND tp.pres_id			= ti.pres_id


			LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit			WITH (NOLOCK)
				ON vitooit.comp_id		= ti.comp_id
				AND vitooit.item_id		= ti.item_id

			LEFT JOIN tbTaxName						ttn				WITH (NOLOCK)
				ON	ttn.comp_id			= ti.comp_id
				AND ttn.tax_id			= vitooit.tax_id

			LEFT JOIN tbWebSite_OnSaleAndNewness wsOferta	WITH (NOLOCK)
				ON wsOferta.comp_id			= @comp_id		AND
					wsOferta.ws_id			= @ws_id		AND
					wsOferta.item_id		= ti.item_id	AND
					wsOferta.wso_type		= 1				AND
					wsOferta.wso_Disabled	= 'False'

			LEFT JOIN tbWebSite_OnSaleAndNewness wsNovedad	WITH (NOLOCK)
				ON  wsNovedad.comp_id		= @comp_id		AND
					wsNovedad.ws_id			= @ws_id		AND
					wsNovedad.item_id		= ti.item_id	AND
					wsNovedad.wso_type		= 2				AND
					wsNovedad.wso_Disabled	= 'False'

	WHERE	ti.comp_id						= @comp_id
	AND		ti.item_web						= 'true'
	AND		ti.item_disabled				= 'false'
	AND		ti.item_not4Sale				= 'false'
	AND		tc.cat_web						= 'true'
	AND		tsc.subcat_web					= 'true'

	AND		(
				(@showzerostock = 'true') OR
				--esto es para que recupere items si no está definido el depósito
				(@showzerostock = 'false' AND
				(CONVERT(integer,(tmpAStock.AStock * @ws_PotentialStockLimit / 100)) > 0 OR @stor_id = -1))
			)


	AND		(
				(@option = 1)													-- items (todos)
				OR
						(@option = 2 AND wsOferta.item_id  IS NOT NULL /*ISNULL(ti.item_liquidation,'false') = 'true'*/)	-- ofertas
						OR
						(@option = 3 AND wsNovedad.item_id IS NOT NULL /*ISNULL(ti.item_newness,'false')	 = 'true'*/)	-- novedades
			)

	AND		(@cat_id	= -1	OR ti.cat_id	= @cat_id	)
	AND		(@subcat_id = -1	OR ti.subcat_id = @subcat_id)
	AND		(@brand_id	= -1	OR ti.brand_id	= @brand_id	)
	AND		(@pres_id	= -1	OR ti.pres_id	= @pres_id	)
	/*AND		ti.item_id NOT IN (SELECT DISTINCT isnull(tiscr.item_id,-1)
   							   FROM		tbItemSizeColorRelation tiscr
   							   WHERE	tiscr.comp_id = ti.comp_id)*/

	AND		ti.item_id NOT IN (SELECT tia.item_id FROM tbItemAssociation tia
   							   WHERE tia.comp_id = @comp_id )

	AND		isnull(tpli.prli_price,0) > 0

	ORDER BY	isnull(tc.cat_web_order,	9999999),
				isnull(tsc.subcat_web_order,9999999),
				SUBSTRING
				(
					CASE	WHEN ti.item_WebSite_desc					 IS NULL THEN ti.item_desc
							WHEN LEN(ltrim(rtrim(ti.item_WebSite_desc))) = 0	 THEN ti.item_desc
							ELSE ti.item_WebSite_desc
					END
				,1,@ws_griddesign_maxlength_desc)
	-- ==========================================================================================================


END
GO






CREATE PROCEDURE [dbo].[spItem_getDataForWeb2]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@cat_id					INT,
	@subcat_id				INT,
	@brand_id				INT,
	@pres_id				INT,
	@prli_id				INT,
	@stor_id				INT,
	@showzerostock			BIT,
	@option					INT,
	@ws_id					INT,
	@searchtext				NVARCHAR(4000),
	@curr_id				INT,
	@pricefrom				INT,
	@priceto				INT,
	@item_id				INT
)
AS



BEGIN



	SET NOCOUNT ON



	-- -----------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------
	/*
	DECLARE @comp_id		INT,
			@lang_id		INT,
			@bra_id			INT,
			@cat_id			INT,
			@subcat_id		INT,
			@brand_id		INT,
			@pres_id		INT,
			@prli_id		INT,
			@stor_id		INT,
			@showzerostock	BIT,
			@option			INT,
			@ws_id			INT,
			@searchtext		NVARCHAR(4000),
			@curr_id				INT,
			@pricefrom				INT,
			@priceto				INT,
			@item_id				INT
	SELECT  @comp_id		=1,
			@lang_id		=2,
			@bra_id			=1,
			@cat_id			=-1,
			@subcat_id		=-1,--14,
			@brand_id		=-1,--68,
			@pres_id		=-1,
			@prli_id		=1,
			@stor_id		=1,
			@showzerostock	='false',
			@option			=2, --1:menú, 2:ofertas, 3:novedades
			@ws_id			=12,
			@searchtext		='item_annotation --- amarillo',
			@curr_id		=1,
			@pricefrom		=0,
			@priceto		=99999999,
			@item_id		=228

	IF NOT OBJECT_ID('tempdb.dbo.#tmpWords')				IS NULL DROP TABLE #tmpWords
	IF NOT OBJECT_ID('tempdb.dbo.#tmpAStock')				IS NULL DROP TABLE #tmpAStock
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItems')				IS NULL DROP TABLE #tmpItems
	IF NOT OBJECT_ID('tempdb.dbo.#tmpSearchText_Spaces')	IS NULL DROP TABLE #tmpSearchText_Spaces
	*/
	-- -----------------------------------------------------------------



	--99
	-- -----------------------------------------------------------
	-- Trae de que manera debe mostrarse el precio (Moneda)
	-- -----------------------------------------------------------
	DECLARE @intCurrId2PriceConvert AS INT
	SET		@intCurrId2PriceConvert = -1
	SELECT  @intCurrId2PriceConvert	= twsn.ws_curr_id4Prices
		FROM tbWebSite_Names twsn
		WHERE	twsn.comp_id	= @comp_id AND
				twsn.ws_id		= @ws_id
	-- -----------------------------------------------------------




	-- creamos la temporal de artículos que componen el criterio de búsqueda
	create table #tmpItems (item_id INT)



	-- ==========================================================================================================================================
	-- si la moneda viene informada con -1, significa que no se seleccionó ninguna moneda en las opciones a avanzadas de filtros, en ese
	-- caso se recupera la moneda de la compañía
	-- ==========================================================================================================================================
	IF @curr_id = -1
		SELECT @curr_id = tc.curr_id
			FROM tbCompany tc			WITH (NOLOCK)
			WHERE tc.comp_id = @comp_id





	-- ==========================================================================================================================================
	-- se verifica que en el rango de importes infomados desde las opciones avanzadas sea el importe desde sea manor o igual al importe hasta,
	-- en caso contrario se invierten los valores, es se hace para que siempre funcione correctamente la instrucción BEETWEN
	-- ==========================================================================================================================================
	IF @priceto < @pricefrom
	BEGIN
		DECLARE @price		INT

		SET		@price		= @pricefrom
		SET		@pricefrom	= @priceto
		SET		@priceto	= @price
	END





	-- ==========================================================================================================================================
	-- recuperan textos para se agregados en la descripción utilizada en la vista en grilla de los datos
	-- ==========================================================================================================================================
	DECLARE @tmpWords AS TABLE (swscc_id INT,wswn_desc NVARCHAR(MAX))
	INSERT INTO @tmpWords(swscc_id, wswn_desc)
	SELECT	isnull(twspccd.swscc_id,0)		[swscc_id],
			isnull(twswn.wswn_desc,'')		[wswn_desc]
	--INTO	#tmpWords
		FROM	tbWebSite_ParagraphComponentsControlsData	twspccd		WITH (NOLOCK)
				LEFT JOIN tbWebSite_WordsNew				twswn		WITH (NOLOCK)
				ON	twswn.lang_id	= @lang_id
				AND twswn.wswi_id	= twspccd.wspcc_wswi_id
		WHERE	twspccd.comp_id		= @comp_id
		AND		twspccd.ws_id		= @ws_id
		--AND		twspccd.swsc_id		= @option
		AND		twspccd.swscc_id	IN (102,75)
	DELETE FROM @tmpWords WHERE [wswn_desc] = ''
	--SELECT * FROM #tmpWords









	-- ===========================================================================================================
	-- cargamos en una tabla temporal sólo los artículos que componen el criterio de búsqueda del control buscador
	-- ===========================================================================================================

	IF len(@searchtext) > 0
	BEGIN

		-- primero separamos por espacios las palabras a buscar en una tabla
		SELECT	fst.items
		INTO	#tmpSearchText_Spaces
		FROM	dbo.fnSplitTableWithSpaces (@searchtext,' ') fst
--SELECT  items  FROM #tmpSearchText_Spaces



		-- variable donde se generará el query correspondiente a la búsqueda
		DECLARE @query NVARCHAR(4000)


		SET @query =			'INSERT INTO #tmpItems SELECT DISTINCT ti.item_id '
		SET @query = @query +	'FROM tbItem ti WITH (NOLOCK)'
		SET @query = @query +	'LEFT JOIN tbBrand tb2 WITH (NOLOCK)
									ON tb2.brand_id = ti.brand_id AND tb2.comp_id = ti.comp_id '
		SET @query = @query +	'LEFT JOIN tbPresentation tb3 WITH (NOLOCK)
									ON tb3.pres_id = ti.pres_id AND tb3.comp_id = ti.comp_id '
		SET @query = @query +	'WHERE ti.comp_id = ' + convert(VARCHAR,@comp_id) + ' and '

		SET @query = @query +	'      ( ' + convert(VARCHAR,@brand_id) + ' = -1 or ti.brand_id = ' + convert(VARCHAR,@brand_id) + ' ) and '
		SET @query = @query +	'      ( ' + convert(VARCHAR,@pres_id)  + ' = -1 or ti.pres_id = ' + convert(VARCHAR,@pres_id)  + ' ) and '


		DECLARE @items  NVARCHAR(4000)

		-- cursor para recorrer las palabras
		DECLARE cursor_palabras CURSOR LOCAL FAST_FORWARD FOR
		SELECT items FROM #tmpSearchText_Spaces

		OPEN cursor_palabras

		FETCH cursor_palabras INTO @items

		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @query = @query + '( ti.item_desc LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'ti.item_WebSite_desc LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'ti.item_code LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'ti.item_detail LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'ti.item_vendorCode LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'tb2.brand_desc LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'tb3.pres_desc LIKE ''%' + @items + '%'' or '
			SET @query = @query + 'ti.item_annotation LIKE ''%' + @items + '%'') and '

			FETCH cursor_palabras INTO @items
		END

		CLOSE cursor_palabras
		DEALLOCATE cursor_palabras

		-- se elimina el último texto ' and' generado en el loop del cursor
		SELECT @query = SUBSTRING(@query, 1, LEN(@query) - 4)
		--SELECT @query


		-- se ejecuta el query y se carga la temporal antes definida
		EXEC (@query)

	END

	ELSE

	BEGIN

		IF @item_id <> -1

			INSERT	INTO #tmpItems

			SELECT	ti2.item_id

			FROM	tbItem				ti		WITH (NOLOCK)

					INNER JOIN tbItem	ti2		WITH (NOLOCK)
					ON	ti2.comp_id		= ti.comp_id
					AND ti2.cat_id		= ti.cat_id
					AND ti2.subcat_id	= ti.subcat_id
					AND ti2.brand_id	= ti.brand_id
					--AND ti2.item_id		<> ti.item_id

			WHERE	ti.comp_id = @comp_id
			AND		ti.item_id = @item_id

		ELSE

			INSERT	INTO #tmpItems
			SELECT	ti.item_id
			FROM	tbItem ti		WITH (NOLOCK)
			WHERE	ti.comp_id = @comp_id

			AND		(@brand_id = -1 OR ti.brand_id = @brand_id)
			AND		(@pres_id = -1  OR ti.pres_id = @pres_id)


	END

	--SELECT * FROM #tmpItems
	-- ===========================================================================================================






	-- ==========================================================================================================
	--como en el query principal se necesita recuperar el stock potencial en 5 lugares diferentes,
	--lo que hacía necesario utilizar la función fnGetAStock que obtiene el stock potencial en
	--5 lugares, se decide cargar una tabla temporal utilizando la función mencionada sólo una vez,
	--y luego en el query principal se joinea con esta tabla temporal

	DECLARE @tmpAStock AS TABLE(item_id INT PRIMARY KEY,AStock DECIMAL(19,4))
	INSERT INTO @tmpAStock	(item_id,AStock)
		SELECT 	ti.item_id,
				dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99)		[AStock]
		--INTO	#tmpAStock
			FROM	tbItem ti											WITH (NOLOCK)
				INNER JOIN #tmpItems tmpI
					ON tmpI.item_id = ti.item_id

				LEFT JOIN tbWebSite_OnSaleAndNewness wsOferta			WITH (NOLOCK)
					ON wsOferta.comp_id			= @comp_id		AND
						wsOferta.ws_id			= @ws_id		AND
						wsOferta.item_id		= ti.item_id	AND
						wsOferta.wso_type		= 1				AND
						wsOferta.wso_Disabled	= 'False'

				LEFT JOIN tbWebSite_OnSaleAndNewness wsNovedad			WITH (NOLOCK)
					ON  wsNovedad.comp_id		= @comp_id		AND
						wsNovedad.ws_id			= @ws_id		AND
						wsNovedad.item_id		= ti.item_id	AND
						wsNovedad.wso_type		= 2				AND
						wsNovedad.wso_Disabled	= 'False'

			WHERE	ti.comp_id = @comp_id
			AND		ISNULL(ti.item_web,'false')			= 'true'
			AND		ISNULL(ti.item_disabled,'false')	= 'false'
			AND		ISNULL(ti.item_not4Sale,'false')	= 'false'
			AND		(
						(@option = 1)													-- items (todos)
						OR
					(@option = 2 AND wsOferta.item_id  IS NOT NULL /*ISNULL(ti.item_liquidation,'false') = 'true'*/)	-- ofertas
					OR
					(@option = 3 AND wsNovedad.item_id IS NOT NULL /*ISNULL(ti.item_newness,'false')	 = 'true'*/)	-- novedades
					)

			AND		(@cat_id	= -1	OR ti.cat_id	= @cat_id	)
			AND		(@subcat_id = -1	OR ti.subcat_id = @subcat_id)
			AND		(@brand_id	= -1	OR ti.brand_id	= @brand_id	)
			AND		(@pres_id	= -1	OR ti.pres_id	= @pres_id	)

	--SELECT * FROM #tmpAStock
	-- ==========================================================================================================





	-- ==========================================================================================================
	-- recuperamos el límite de stock potencial y la marca indicadora de como mostrar los precios del web_site seleccionado
	-- ==========================================================================================================
	DECLARE @ws_PotentialStockLimit			INT,
			@ws_showpricewithtax			BIT,
			@ws_showpricelist				INT,
			@ws_griddesign_maxlength_desc	INT

	SELECT	@ws_PotentialStockLimit			= isnull(twsn.ws_PotentialStockLimit,0),
			@ws_showpricewithtax			= isnull(twsn.ws_showpricewithtax,'false'),
			@ws_showpricelist				= ISNULL(twsn.ws_showpricelist,0),
			@ws_griddesign_maxlength_desc	= ISNULL(twsn.ws_griddesign_maxlength_desc,100)
		FROM	tbWebSite_Names				twsn	WITH (NOLOCK)
		WHERE	twsn.comp_id	= @comp_id
		AND		twsn.ws_id		= @ws_id
	--SELECT @ws_PotentialStockLimit, @ws_showpricewithtax
	-- ==========================================================================================================


	IF @ws_PotentialStockLimit = 0
		SET @ws_PotentialStockLimit = 100



	-- ==========================================================================================================
	SELECT	--ti.item_code, ti.item_vendorCode,
			--isnull(tc.cat_web_order,999999) [c], isnull(tsc.subcat_web_order,99999) [sc],
			tc.cat_desc,
			tsc.subcat_desc,
			--' ' [ ],

			ti.item_id,

			SUBSTRING
				(
					CASE	WHEN ti.item_WebSite_desc					 IS NULL THEN ti.item_desc
							WHEN LEN(ltrim(rtrim(ti.item_WebSite_desc))) = 0	 THEN ti.item_desc
							ELSE ti.item_WebSite_desc
					END
				,1,@ws_griddesign_maxlength_desc)				[item_desc],

			ti.curr_id,
			isnull(tb.stor_id,-1)								[stor_id],
			isnull(ti.cat_id,-1)								[cat_id],

			isnull(ti.subcat_id,-1)								[subcat_id],

			--ti.item_picture,


			CASE
				WHEN @intCurrId2PriceConvert <> -1 AND @ws_showpricewithtax = 'true' THEN
										LTRIM(RTRIM(ISNULL(tsc33.curr_symbol,''))) + ' ' +
										CONVERT(NVARCHAR,
											dbo.fnGetExchange2(	@comp_id,
																isnull(tpli.prli_price,0) + (isnull(tpli.prli_price,0) * ttn.tax_percentage / 100),
																tpli.curr_id,
																@intCurrId2PriceConvert,
																0,
																0,
																0,
																'False')
												)
				--99
				WHEN @intCurrId2PriceConvert <> -1 AND @ws_showpricewithtax = 'False' THEN
										LTRIM(RTRIM(ISNULL(tsc33.curr_symbol,''))) + ' ' +
										CONVERT(NVARCHAR,
											dbo.fnGetExchange2(	@comp_id,
																isnull(tpli.prli_price,0),
																tpli.curr_id,
																@intCurrId2PriceConvert,
																0,
																0,
																0,
																'False')
												)


				WHEN @ws_showpricewithtax = 'true' THEN
										LTRIM(RTRIM(ISNULL(tscy.curr_symbol,''))) + ' ' +
											CONVERT(NVARCHAR,isnull(tpli.prli_price,0) + (isnull(tpli.prli_price,0) * ttn.tax_percentage / 100))
				ELSE
										LTRIM(RTRIM(ISNULL(tscy.curr_symbol,''))) + ' ' +
											CONVERT(NVARCHAR,isnull(tpli.prli_price,0))
				END		[item_price],
			--ISNULL(tpli.prli_price,0),
			--ttn.tax_percentage,

			--isnull(ts.itst_cant,0)								[itst_cant],
			--dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99)		[itst_cant],
			CONVERT(integer,(tmpAStock.AStock * @ws_PotentialStockLimit / 100))	[itst_cant],


			tut2.utexts_desc									[buy],
			tut1.utexts_desc									[info],
			isnull(ti.item_annotation,'')						[item_annotation],
			--ti.item_id,
			tc.cat_desc + ' - ' + tsc.subcat_desc				[desc],
			isnull(ti.item_detail,'')							[item_detail],
			isnull(ti.item_annotation1,'')						[item_annotation1],
			isnull(ti.item_annotation2,'')						[item_annotation2],
			ti.item_web,

	--		CASE
	--			WHEN NOT ISNULL(ts.itst_cant,0) < ti.item_cantOpt						THEN 'green'
	--			WHEN	 ISNULL(ts.itst_cant,0) BETWEEN ti.item_cantMin AND ti.item_cantOpt THEN 'yellow'
	--			WHEN	 ISNULL(ts.itst_cant,0) < ti.item_cantMin							THEN 'red'
	--		END													[signal],
	--		CASE
	--			WHEN NOT ISNULL(dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99),0) < ti.item_cantOpt							THEN 'green'
	--			WHEN	 ISNULL(dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99),0) BETWEEN ti.item_cantMin AND ti.item_cantOpt	THEN 'yellow'
	--			WHEN	 ISNULL(dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99),0) < ti.item_cantMin							THEN 'red'
	--		END													[signal],
			CASE
				WHEN NOT ISNULL(tmpAStock.AStock,0) < ti.item_cantOpt							THEN 'g'
				WHEN	 ISNULL(tmpAStock.AStock,0) BETWEEN ti.item_cantMin AND ti.item_cantOpt	THEN 'y'
				WHEN	 ISNULL(tmpAStock.AStock,0) < ti.item_cantMin							THEN 'r'
			END													[signal],


			LTRIM(RTRIM(ISNULL(tscy.curr_symbol,'')))			[curr_symbol],

			CASE WHEN @ws_showpricewithtax = 'true' THEN
						CONVERT(NVARCHAR,ISNULL(tpli.prli_price,0) + (ISNULL(tpli.prli_price,0) * ttn.tax_percentage / 100))
				ELSE
						CONVERT(NVARCHAR,ISNULL(tpli.prli_price,0))
				END		[prli_price],

			--ISNULL(tpli.prli_price,0)							[prli_price],


			CASE
				WHEN LEN(ISNULL(ti.item_WebSite_desc, ti.item_desc)) > 50
					THEN SUBSTRING(ISNULL(ti.item_WebSite_desc, ti.item_desc),1,47) + '...'
					ELSE ISNULL(ti.item_WebSite_desc, ti.item_desc)
			END +
			'|'+
			isnull(tmpPrice.wswn_desc,'') +
			'|'+
			LTRIM(RTRIM(ISNULL(tscy.curr_symbol,''))) + ' ' +
				CASE WHEN @ws_showpricewithtax = 'true' THEN
						CONVERT(NVARCHAR,ISNULL(tpli.prli_price,0) + (ISNULL(tpli.prli_price,0) * ttn.tax_percentage / 100))
				ELSE
						CONVERT(NVARCHAR,ISNULL(tpli.prli_price,0))
				END	 +
			'|'+
			isnull(tmpStock.wswn_desc,'') +
			'|'+
			CONVERT(VARCHAR,ISNULL(tmpAStock.AStock,0))			[grid_desc],

			ISNULL(tb2.brand_desc,'')							[brand_desc],
			ISNULL(tp.pres_desc,'')								[pres_desc],

			ti.item_id											[ID]


	FROM	tbItem									ti			WITH (NOLOCK)

			INNER JOIN #tmpItems					tmpI
				ON	tmpI.item_id	= ti.item_id

			LEFT JOIN tbBranch						tb			WITH (NOLOCK)
				ON	tb.comp_id		= ti.comp_id
				AND tb.bra_id		= ti.bra_id

			INNER JOIN tbCategory					tc			WITH (NOLOCK)
				ON	tc.comp_id		= ti.comp_id
					AND tc.cat_id		= ti.cat_id


			INNER JOIN tbSubCategory					tsc			WITH (NOLOCK)
				ON	tsc.cat_id		= ti.cat_id
				AND tsc.subcat_id	= ti.subcat_id
				AND tsc.comp_id		= ti.comp_id


			LEFT JOIN tbPriceListItems				tpli		WITH (NOLOCK)
			ON	tpli.comp_id		= ti.comp_id
			AND tpli.item_id		= ti.item_id
			AND tpli.prli_id		= @prli_id

	--		LEFT JOIN tbPriceList					tpl
	--		ON	tpl.comp_id			= ti.comp_id
	--		AND tpl.prli_id			= tpli.prli_id

	--		LEFT JOIN tbItemStorage					ts
	--		ON	ts.comp_id			= ti.comp_id
	--		AND ts.stor_id			= @stor_id
	--		AND ts.item_id			= ti.item_id

			LEFT JOIN tbsysCurrency					tscy		WITH (NOLOCK)
			ON	tscy.curr_id			= tpli.curr_id


			--99
			LEFT JOIN tbsyscurrency					tsc33
				ON tsc33.curr_id		= @intCurrId2PriceConvert

			INNER JOIN tbsysUniqueTexts				tut1		WITH (NOLOCK)
				ON	tut1.lang_id		= @lang_id
				AND tut1.utexts_id		= 224012

			INNER JOIN tbsysUniqueTexts				tut2		WITH (NOLOCK)
				ON	tut2.lang_id		= @lang_id
				AND tut2.utexts_id		= 224013

			LEFT JOIN @tmpWords					tmpStock
				ON tmpStock.swscc_id	= 102

			LEFT JOIN @tmpWords					tmpPrice
				ON tmpPrice.swscc_id	= 75


			INNER JOIN @tmpAStock		tmpAStock
				ON	ti.item_id			= tmpAStock.item_id

			INNER JOIN tbBrand			tb2						WITH (NOLOCK)
				ON	tb2.brand_id		= ti.brand_id
				AND tb2.comp_id			= ti.comp_id

			INNER JOIN tbPresentation	tp						WITH (NOLOCK)
				ON	tp.comp_id			= ti.comp_id
				AND tp.pres_id			= ti.pres_id


			LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit		WITH (NOLOCK)
				ON vitooit.comp_id		= ti.comp_id
				AND vitooit.item_id		= ti.item_id

			LEFT JOIN tbTaxName						ttn			WITH (NOLOCK)
				ON	ttn.comp_id			= ti.comp_id
				AND ttn.tax_id			= vitooit.tax_id

			LEFT JOIN tbWebSite_OnSaleAndNewness wsOferta	WITH (NOLOCK)
				ON wsOferta.comp_id			= @comp_id		AND
					wsOferta.ws_id			= @ws_id		AND
					wsOferta.item_id		= ti.item_id	AND
					wsOferta.wso_type		= 1				AND
					wsOferta.wso_Disabled	= 'False'

			LEFT JOIN tbWebSite_OnSaleAndNewness wsNovedad	WITH (NOLOCK)
				ON  wsNovedad.comp_id		= @comp_id		AND
					wsNovedad.ws_id			= @ws_id		AND
					wsNovedad.item_id		= ti.item_id	AND
					wsNovedad.wso_type		= 2				AND
					wsNovedad.wso_Disabled	= 'False'


	WHERE	ti.comp_id							= @comp_id
	AND		ISNULL(ti.item_web,'false')			= 'true'
	AND		ISNULL(ti.item_disabled,'false')	= 'false'
	AND		ISNULL(ti.item_not4Sale,'false')	= 'false'
	AND		isnull(tc.cat_web,'true')			= 'true'
	AND		isnull(tsc.subcat_web,'true')		= 'true'

	AND		(
				(@showzerostock = 'true') OR
				--esto es para que recupere items si no está definido el depósito
				(@showzerostock = 'false' AND
				(CONVERT(integer,(tmpAStock.AStock * @ws_PotentialStockLimit / 100)) > 0 OR @stor_id = -1))
			)


	AND		(
				(@option = 1)													-- items (todos)
				OR
					(@option = 2 AND wsOferta.item_id  IS NOT NULL /*ISNULL(ti.item_liquidation,'false') = 'true'*/)	-- ofertas
					OR
					(@option = 3 AND wsNovedad.item_id IS NOT NULL /*ISNULL(ti.item_newness,'false')	 = 'true'*/)	-- novedades
	)

	AND		(@cat_id	= -1	OR ti.cat_id	= @cat_id	)
	AND		(@subcat_id = -1	OR ti.subcat_id = @subcat_id)
	AND		(@brand_id	= -1	OR ti.brand_id	= @brand_id	)
	AND		(@pres_id	= -1	OR ti.pres_id	= @pres_id	)

	AND		ti.item_id NOT IN (SELECT tia.item_id FROM tbItemAssociation tia
   							   WHERE tia.comp_id = @comp_id )

	AND		isnull(tpli.prli_price,0) > 0

	AND		dbo.fnGetExchange2(@comp_id,tpli.prli_price,tpli.curr_id,@curr_id,0,0,0,'false') BETWEEN @pricefrom AND @priceto



	AND		ti.cat_id		NOT IN (SELECT	DISTINCT isnull(twscsd.cat_id, -1)
	   									FROM	tbWebSite_Cat_Subcat_Disabled twscsd		WITH (NOLOCK)
	   									WHERE	twscsd.comp_id		= ti.comp_id
										AND		twscsd.ws_id		= @ws_id
										AND		twscsd.subcat_id	IS NULL)


	AND		ti.subcat_id	NOT IN (SELECT	DISTINCT isnull(twscsd.subcat_id, -1)
	   									FROM	tbWebSite_Cat_Subcat_Disabled twscsd		WITH (NOLOCK)
	   									WHERE	twscsd.comp_id		= ti.comp_id
										AND		twscsd.ws_id		= @ws_id)



	ORDER BY	isnull(tc.cat_web_order		,9999999)	,
				isnull(tc.cat_desc			,'')		,
				isnull(tsc.subcat_web_order	,9999999)	,
				isnull(tsc.subcat_desc		,'')		,
				isnull(tb2.brand_desc		,'')		,
				isnull(tp.pres_desc			,'')		,
				SUBSTRING
				(
					CASE	WHEN ti.item_WebSite_desc					 IS NULL THEN ti.item_desc
							WHEN LEN(ltrim(rtrim(ti.item_WebSite_desc))) = 0	 THEN ti.item_desc
							ELSE ti.item_WebSite_desc
					END
				,1,@ws_griddesign_maxlength_desc)
	-- ==========================================================================================================



END
GO








CREATE PROCEDURE [dbo].[spItem_getDataForWeb3]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@cat_id					INT,
	@subcat_id				INT,
	@brand_id				INT,
	@pres_id				INT,
	@prli_id				INT,
	@stor_id				INT,
	@showzerostock			BIT,
	@option					INT,
	@ws_id					INT,
	@searchtext				NVARCHAR(4000),
	@curr_id				INT,
	@pricefrom				INT,
	@priceto				INT,
	@item_id				INT
)
AS




BEGIN

	SET NOCOUNT ON

	-- -------------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------------
	/*
	DECLARE @comp_id		INT,
			@lang_id		INT,
			@bra_id			INT,
			@cat_id			INT,
			@subcat_id		INT,
			@brand_id		INT,
			@pres_id		INT,
			@prli_id		INT,
			@stor_id		INT,
			@showzerostock	BIT,
			@option			INT,
			@ws_id			INT,
			@searchtext		NVARCHAR(4000),
			@curr_id		INT,
			@pricefrom		INT,
			@priceto		INT,
			@item_id		INT
	SELECT  @comp_id		=1,
			@lang_id		=2,
			@bra_id			=1,
			@cat_id			=-1,
			@subcat_id		=-1,--14,
			@brand_id		=-1,--68,
			@pres_id		=-1,
			@prli_id		=1,
			@stor_id		=1,
			@showzerostock	='false',
			@option			=1,
			@ws_id			=12,
			@searchtext		='',
			@curr_id		=1,
			@pricefrom		=0,
			@priceto		=99999999,
			@item_id		=-1

	--IF NOT OBJECT_ID('tempdb.dbo.#tmpWords')				IS NULL DROP TABLE @tmpWords
	--IF NOT OBJECT_ID('tempdb.dbo.#tmpAStock')				IS NULL DROP TABLE @tmpAStock
	--IF NOT OBJECT_ID('tempdb.dbo.#tmpItems')				IS NULL DROP TABLE @tmpItems
	--IF NOT OBJECT_ID('tempdb.dbo.#tmpSearchText_Spaces')	IS NULL DROP TABLE @tmpSearchText_Spaces
	*/
	-- -------------------------------------------------------------------------------------



	--99
	-- -----------------------------------------------------------
	-- Trae de que manera debe mostrarse el precio (Moneda)
	-- -----------------------------------------------------------
	DECLARE @intCurrId2PriceConvert AS INT
	SET		@intCurrId2PriceConvert = -1
	SELECT  @intCurrId2PriceConvert	= twsn.ws_curr_id4Prices
		FROM tbWebSite_Names twsn
		WHERE	twsn.comp_id	= @comp_id AND
				twsn.ws_id		= @ws_id
	-- -----------------------------------------------------------





	-- ==========================================================================================================================================
	-- si la moneda viene informada con -1, significa que no se seleccionó ninguna moneda en las opciones a avanzadas de filtros, en ese
	-- caso se recupera la moneda de la compañía
	-- ==========================================================================================================================================
	IF @curr_id = -1
		SELECT @curr_id = tc.curr_id
			FROM tbCompany tc	WITH (NOLOCK)
			WHERE tc.comp_id = @comp_id


	-- ==========================================================================================================================================
	-- se verifica que en el rango de importes infomados desde las opciones avanzadas sea el importe desde sea manor o igual al importe hasta,
	-- en caso contrario se invierten los valores, es se hace para que siempre funcione correctamente la instrucción BEETWEN
	-- ==========================================================================================================================================
	IF @priceto < @pricefrom
	BEGIN
		DECLARE @price		INT

		SET		@price		= @pricefrom
		SET		@pricefrom	= @priceto
		SET		@priceto	= @price
	END





	-- ==========================================================================================================================================
	-- recuperan textos para se agregados en la descripción utilizada en la vista en grilla de los datos
	-- ==========================================================================================================================================
	DECLARE @tmpWords	AS TABLE(swscc_id INT,wswn_desc NVARCHAR(4000))
	INSERT INTO @tmpWords (	swscc_id,
							wswn_desc)
		SELECT	isnull(twspccd.swscc_id,0)		[swscc_id],
				isnull(twswn.wswn_desc,'')		[wswn_desc]
			--INTO	@tmpWords
			FROM	tbWebSite_ParagraphComponentsControlsData	twspccd		WITH (NOLOCK)
					LEFT JOIN tbWebSite_WordsNew				twswn		WITH (NOLOCK)
					ON	twswn.lang_id	= @lang_id
					AND twswn.wswi_id	= twspccd.wspcc_wswi_id
			WHERE	twspccd.comp_id		= @comp_id
			AND		twspccd.ws_id		= @ws_id
			--AND		twspccd.swsc_id		= @option
			AND		twspccd.swscc_id	IN (102,75)
	DELETE FROM @tmpWords WHERE [wswn_desc] = ''
	--SELECT * FROM @tmpWords
	-- ==========================================================================================================================================








	-- ===========================================================================================================
	-- cargamos en una tabla temporal sólo los artículos que componen el criterio de búsqueda del control buscador
	-- ===========================================================================================================

	-- creamos la temporal de artículos que componen el criterio de búsqueda
	--DECLARE @tmpItems AS TABLE(item_id INT)
	CREATE TABLE #tmpItems (item_id INT)
	DECLARE @tmpSearchText_Spaces AS TABLE(items NVARCHAR(1000))

	IF len(@searchtext) > 0
		BEGIN	-- Si hay texto a buscar

			-- primero separamos por espacios las palabras a buscar en una tabla
			INSERT INTO @tmpSearchText_Spaces(items)
			SELECT	fst.items
			--INTO	#tmpSearchText_Spaces
			FROM	dbo.fnSplitTableWithSpaces (@searchtext,' ') fst
			--SELECT  items  FROM @tmpSearchText_Spaces



			-- variable donde se generará el query correspondiente a la búsqueda
			DECLARE @query NVARCHAR(4000)


			SET @query =			'INSERT INTO #tmpItems SELECT DISTINCT ti.item_id '
			SET @query = @query +	'FROM tbItem ti			WITH (NOLOCK) '
			SET @query = @query +	'LEFT JOIN tbBrand tb2	WITH (NOLOCK)
										ON tb2.brand_id = ti.brand_id AND tb2.comp_id = ti.comp_id '
			SET @query = @query +	'LEFT JOIN tbPresentation tb3 WITH (NOLOCK)
										ON tb3.pres_id = ti.pres_id AND tb3.comp_id = ti.comp_id '
			SET @query = @query +	'WHERE ti.comp_id = ' + convert(VARCHAR,@comp_id) + ' and '

			SET @query = @query +	'      ( ' + convert(VARCHAR,@brand_id) + ' = -1 or ti.brand_id = ' + convert(VARCHAR,@brand_id) + /*' or tb2.brand_WebSite_id = ' + convert(VARCHAR,@brand_id)*/ + ') and '
			SET @query = @query +	'      ( ' + convert(VARCHAR,@pres_id)  + ' = -1 or ti.pres_id = ' + convert(VARCHAR,@pres_id)  + ' ) and '


			DECLARE @items  NVARCHAR(4000)

			-- cursor para recorrer las palabras
			DECLARE cursor_palabras CURSOR LOCAL FAST_FORWARD FOR
			SELECT items FROM @tmpSearchText_Spaces
			OPEN cursor_palabras

			FETCH cursor_palabras INTO @items

			WHILE @@FETCH_STATUS = 0
			BEGIN

				SET @query = @query + '( ti.item_desc LIKE ''%' + @items + '%'' or '
				SET @query = @query + 'ti.item_WebSite_desc LIKE ''%' + @items + '%'' or '
				SET @query = @query + 'ti.item_code LIKE ''%' + @items + '%'' or '
				SET @query = @query + 'ti.item_detail LIKE ''%' + @items + '%'' or '
				SET @query = @query + 'ti.item_vendorCode LIKE ''%' + @items + '%'' or '
				SET @query = @query + 'tb2.brand_desc LIKE ''%' + @items + '%'' or '
				SET @query = @query + 'tb3.pres_desc LIKE ''%' + @items + '%'' or '
				SET @query = @query + 'ti.item_annotation LIKE ''%' + @items + '%'') and '

				FETCH cursor_palabras INTO @items
			END

			CLOSE cursor_palabras
			DEALLOCATE cursor_palabras



			-- se elimina el último texto ' and' generado en el loop del cursor
			SELECT @query = SUBSTRING(@query, 1, LEN(@query) - 4)
			--SELECT @query


			-- se ejecuta el query y se carga la temporal antes definida
			EXEC (@query)

		END

	ELSE	-- si NO hay texto a buscar

		BEGIN

			IF @item_id <> -1
				INSERT	INTO #tmpItems
				SELECT	ti.item_id
						FROM	tbItem				ti	WITH (NOLOCK)
						WHERE	ti.comp_id = @comp_id
						AND		ti.item_id = @item_id
					-- MOS: 04-2013
					--SELECT	ti2.item_id
					--	FROM	tbItem				ti
					--			INNER JOIN tbItem	ti2
					--			ON	ti2.comp_id		= ti.comp_id
					--			AND ti2.cat_id		= ti.cat_id
					--			AND ti2.subcat_id	= ti.subcat_id
					--			AND ti2.brand_id	= ti.brand_id
					--			--AND ti2.item_id		<> ti.item_id
					--	WHERE	ti.comp_id = @comp_id
					--	AND		ti.item_id = @item_id

			ELSE

				INSERT	INTO #tmpItems
					SELECT	ti.item_id
						FROM	tbItem ti	WITH (NOLOCK)
								-- MOS: 04-2013
								--INNER JOIN tbBrand tb
								--ON tb.brand_id = ti.brand_id AND tb.comp_id = ti.comp_id
						WHERE	ti.comp_id = @comp_id
						AND		(@brand_id = -1 OR ti.brand_id = @brand_id /*OR tb.brand_WebSite_id = @brand_id*/)
						AND		(@pres_id = -1  OR ti.pres_id = @pres_id)
		END

	--SELECT * FROM @tmpItems
	-- ===========================================================================================================





	-- ==========================================================================================================
	--como en el query principal se necesita recuperar el stock potencial en 5 lugares diferentes,
	--lo que hacía necesario utilizar la función fnGetAStock que obtiene el stock potencial en
	--5 lugares, se decide cargar una tabla temporal utilizando la función mencionada sólo una vez,
	--y luego en el query principal se joinea con esta tabla temporal
	DECLARE @tmpAStock  as TABLE(	item_id INT PRIMARY KEY,
									AStock DECIMAL(19,2))

	INSERT INTO @tmpAStock (item_id,AStock)
	SELECT	ti.item_id,
			dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99)		[AStock]
		--INTO	@tmpAStock
		FROM	tbItem ti													WITH (NOLOCK)
				INNER JOIN #tmpItems tmpI
				ON tmpI.item_id = ti.item_id

				INNER JOIN tbCategory tc									WITH (NOLOCK)
					ON		tc.comp_id	= ti.comp_id AND
							tc.cat_id	= ti.cat_id
				INNER JOIN tbBrand tb										WITH (NOLOCK)
					ON		tb.brand_id = ti.brand_id AND
							tb.comp_id	= ti.comp_id
				INNER JOIN tbItemStorage tis								WITH (NOLOCK)
					ON	tis.comp_id = ti.comp_id	AND
						tis.stor_id = @stor_id		AND
						tis.item_id = ti.item_id

				LEFT JOIN tbPriceListItems				tpli				WITH (NOLOCK)
					ON	tpli.comp_id		= ti.comp_id
					AND tpli.item_id		= ti.item_id
					AND tpli.prli_id		= @prli_id

				LEFT JOIN tbsysCurrency					tscy				WITH (NOLOCK)
					ON	tscy.curr_id			= tpli.curr_id

				--99
				LEFT JOIN tbsyscurrency					tsc33
					ON tsc33.curr_id		= @intCurrId2PriceConvert

				LEFT JOIN tbWebSite_OnSaleAndNewness wsOferta				WITH (NOLOCK)
					ON wsOferta.comp_id			= @comp_id		AND
						wsOferta.ws_id			= @ws_id		AND
						wsOferta.item_id		= ti.item_id	AND
						wsOferta.wso_type		= 1				AND
						wsOferta.wso_Disabled	= 'False'

				LEFT JOIN tbWebSite_OnSaleAndNewness wsNovedad				WITH (NOLOCK)
					ON  wsNovedad.comp_id		= @comp_id		AND
						wsNovedad.ws_id			= @ws_id		AND
						wsNovedad.item_id		= ti.item_id	AND
						wsNovedad.wso_type		= 2				AND
						wsNovedad.wso_Disabled	= 'False'

		WHERE	-- Poner aqui TODOS los filtros posibles ya que esto es lo MAS LENTO de este SP.!
				ti.comp_id = @comp_id
		AND		ISNULL(ti.item_web,'false')			= 'true'
		AND		ISNULL(ti.item_disabled,'false')	= 'false'
		AND		ISNULL(ti.item_not4Sale,'false')	= 'false'
		AND		(
					(@option = 1)													-- items (todos)
					OR
					(@option = 2 AND wsOferta.item_id  IS NOT NULL /*ISNULL(ti.item_liquidation,'false') = 'true'*/)	-- ofertas
					OR
					(@option = 3 AND wsNovedad.item_id IS NOT NULL /*ISNULL(ti.item_newness,'false')	 = 'true'*/)	-- novedades
				)

		AND		(@cat_id	= -1	OR ti.cat_id	= @cat_id	/*OR tc.cat_WebSite_id = @cat_id*/)
		AND		(@subcat_id = -1	OR ti.subcat_id = @subcat_id)
		AND		(@brand_id	= -1	OR ti.brand_id	= @brand_id	/*OR tb.brand_WebSite_id = @brand_id*/)
		AND		(@pres_id	= -1	OR ti.pres_id	= @pres_id	)



		AND				NOT EXISTS (	SELECT	1
											FROM	tbWebSite_Cat_Subcat_Disabled twscsd		WITH (NOLOCK)
											WHERE	twscsd.comp_id		= ti.comp_id	AND
													twscsd.cat_id		= ti.cat_id		AND
													twscsd.ws_id		= @ws_id		AND
													twscsd.subcat_id	IS NULL)

		AND				NOT EXISTS (	SELECT	1
   												FROM	tbWebSite_Cat_Subcat_Disabled twscsd	WITH (NOLOCK)
   												WHERE	twscsd.comp_id		= ti.comp_id	AND
														twscsd.subcat_id	= ti.subcat_id	AND
														twscsd.ws_id		= @ws_id)
		and (
				@showzerostock = 'true'  OR
			   (@showzerostock = 'False' AND tis.itst_cant > 0 )
			)
		AND	isnull(tpli.prli_price,0) > 0
		AND	dbo.fnGetExchange2(@comp_id,tpli.prli_price,tpli.curr_id,@curr_id,0,0,0,'false') BETWEEN @pricefrom AND @priceto
	--SELECT @showzerostock
	--SELECT * FROM @tmpAStock
	-- ==========================================================================================================





	-- ==========================================================================================================
	-- recuperamos el límite de stock potencial y la marca indicadora de como mostrar los precios del web_site seleccionado
	-- ==========================================================================================================
	DECLARE @ws_PotentialStockLimit			INT,
			@ws_showpricewithtax			BIT,
			@ws_showpricelist				INT,
			@ws_cols						INT,
			@ws_rows						INT,
			@ws_decimals4Price				INT,
			@ws_griddesign_maxlength_desc	INT


	SELECT	@ws_PotentialStockLimit			= twsn.ws_PotentialStockLimit,
			@ws_showpricewithtax			= ISNULL(twsn.ws_showpricewithtax,'false'),
			@ws_showpricelist				= ISNULL(twsn.ws_showpricelist,0),

			@ws_cols						= ISNULL(twsn.ws_griddesign_cells,1),
			@ws_rows						= ISNULL(twsn.ws_griddesign_rows,1),
			@ws_decimals4Price				= twsn.ws_decimals4Price,
			@ws_griddesign_maxlength_desc	= ISNULL(twsn.ws_griddesign_maxlength_desc,100)

	FROM	tbWebSite_Names				twsn		WITH (NOLOCK)

	WHERE	twsn.comp_id	= @comp_id
	AND		twsn.ws_id		= @ws_id



	IF @ws_cols > 5
	BEGIN
		SET @ws_cols = 5
	END



	--SELECT @ws_PotentialStockLimit, @ws_showpricewithtax
	-- ==========================================================================================================









	-- ==========================================================================================================
	IF NOT OBJECT_ID('tempdb.dbo.#tmpFinal')	IS NULL DROP TABLE #tmpFinal

		CREATE TABLE #tmpFinal (item_desc		NVARCHAR(100),
								item_price		NVARCHAR(50),
								item_id			INT,
								new_id [int]	IDENTITY(0,1))


	INSERT INTO #tmpFinal (	item_desc,
							item_price,
							item_id)

		SELECT	/*SUBSTRING
					(ISNULL
						(ti.item_WebSite_desc, ti.item_desc),
							1,@ws_griddesign_maxlength_desc)					[item_desc],*/

				SUBSTRING
					(
						CASE	WHEN ti.item_WebSite_desc					 IS NULL THEN ti.item_desc
								WHEN LEN(ltrim(rtrim(ti.item_WebSite_desc))) = 0	 THEN ti.item_desc
								ELSE ti.item_WebSite_desc
						END
					,1,@ws_griddesign_maxlength_desc)								[item_desc],

				CASE
					WHEN @ws_showpricelist = 1 THEN --muestra precio
						CASE
							WHEN @intCurrId2PriceConvert <> -1 AND @ws_showpricewithtax = 'true' THEN
													LTRIM(RTRIM(ISNULL(tsc33.curr_symbol,''))) + ' ' +
													CONVERT(NVARCHAR,
														dbo.fnGetExchange2(	@comp_id,
																			isnull(tpli.prli_price,0) + (isnull(tpli.prli_price,0) * ttn.tax_percentage / 100),
																			tpli.curr_id,
																			@intCurrId2PriceConvert,
																			0,
																			0,
																			0,
																			'False')
															)
							--99
							WHEN @intCurrId2PriceConvert <> -1 AND @ws_showpricewithtax = 'False' THEN
													LTRIM(RTRIM(ISNULL(tsc33.curr_symbol,''))) + ' ' +
													CONVERT(NVARCHAR,
														dbo.fnGetExchange2(	@comp_id,
																			isnull(tpli.prli_price,0),
																			tpli.curr_id,
																			@intCurrId2PriceConvert,
																			0,
																			0,
																			0,
																			'False')
															)


							WHEN @ws_showpricewithtax = 'true' THEN
													LTRIM(RTRIM(ISNULL(tscy.curr_symbol,''))) + ' ' +
														CONVERT(NVARCHAR,isnull(tpli.prli_price,0) +
																		(isnull(tpli.prli_price,0) * IsNull(ttn.tax_percentage,0) / 100) +
																		(isnull(tpli.prli_price,0) * IsNull(ttnit.tax_percentage,0) / 100)
																)


							ELSE
													LTRIM(RTRIM(ISNULL(tscy.curr_symbol,''))) + ' ' +
														CONVERT(NVARCHAR,isnull(tpli.prli_price,0))
						END

					WHEN @ws_showpricelist = 0 THEN --no muestra precio
						''
					WHEN @ws_showpricelist = 2 THEN --muestra mensaje de llamar/consultar debería sacarlo de tbWebSite_ParagraphComponentsControlsData
						'Consultar'
				END 																[item_price],

				ti.item_id															[ID]


		FROM	tbItem									ti		WITH (NOLOCK)


				inner JOIN tbCategory					tc		WITH (NOLOCK)
				ON	tc.comp_id		= ti.comp_id
				AND tc.cat_id		= ti.cat_id


				INNER JOIN tbSubCategory					tsc		WITH (NOLOCK)
				ON	tsc.cat_id		= ti.cat_id
				AND tsc.subcat_id	= ti.subcat_id
				AND tsc.comp_id		= ti.comp_id


				LEFT JOIN tbPriceListItems				tpli	WITH (NOLOCK)
				ON	tpli.comp_id		= ti.comp_id
				AND tpli.item_id		= ti.item_id
				AND tpli.prli_id		= @prli_id



				LEFT JOIN tbsysCurrency					tscy	WITH (NOLOCK)
				ON	tscy.curr_id			= tpli.curr_id

				--99
				LEFT JOIN tbsyscurrency					tsc33
					ON tsc33.curr_id		= @intCurrId2PriceConvert

				INNER JOIN tbsysUniqueTexts				tut1	WITH (NOLOCK)
					ON	tut1.lang_id		= @lang_id
					AND tut1.utexts_id		= 224012

				INNER JOIN tbsysUniqueTexts				tut2	WITH (NOLOCK)
					ON	tut2.lang_id		= @lang_id
					AND tut2.utexts_id		= 224013

				LEFT JOIN @tmpWords					tmpStock
					ON tmpStock.swscc_id	= 102

				LEFT JOIN @tmpWords					tmpPrice
					ON tmpPrice.swscc_id	= 75


				INNER JOIN @tmpAStock		tmpAStock
				ON	ti.item_id			= tmpAStock.item_id

				INNER JOIN tbBrand			tb2					WITH (NOLOCK)
					ON	tb2.brand_id		= ti.brand_id
					AND tb2.comp_id			= ti.comp_id


				LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit	WITH (NOLOCK)
					ON	vitooit.comp_id		= ti.comp_id and
						vitooit.item_id		= ti.item_id

				LEFT JOIN tbTaxName						ttn		WITH (NOLOCK)
				ON	ttn.comp_id			= ti.comp_id
				AND ttn.tax_id			= vitooit.tax_id


				left join vwItemTaxesOnlyOneInternalTax vooit	WITH (NOLOCK)
					ON	vooit.comp_id = ti.comp_id AND
						vooit.item_id = ti.item_id

				LEFT JOIN tbTaxName						ttnit	WITH (NOLOCK)
					ON	ttnit.comp_id			= ti.comp_id
					AND ttnit.tax_id			= vooit.tax_id

				LEFT JOIN tbWebSite_OnSaleAndNewness wsOferta	WITH (NOLOCK)
					ON wsOferta.comp_id			= @comp_id		AND
						wsOferta.ws_id			= @ws_id		AND
						wsOferta.item_id		= ti.item_id	AND
						wsOferta.wso_type		= 1				AND
						wsOferta.wso_Disabled	= 'False'

				LEFT JOIN tbWebSite_OnSaleAndNewness wsNovedad	WITH (NOLOCK)
					ON  wsNovedad.comp_id		= @comp_id		AND
						wsNovedad.ws_id			= @ws_id		AND
						wsNovedad.item_id		= ti.item_id	AND
						wsNovedad.wso_type		= 2				AND
						wsNovedad.wso_Disabled	= 'False'


		WHERE	ti.comp_id							= @comp_id
		AND		ISNULL(ti.item_web,'false')			= 'true'
		AND		ISNULL(ti.item_disabled,'false')	= 'false'
		AND		ISNULL(ti.item_not4Sale,'false')	= 'false'
		AND		isnull(tc.cat_web,'true')			= 'true'
		AND		isnull(tsc.subcat_web,'true')		= 'true'

		AND		(
					(@showzerostock = 'true')		OR
					--esto es para que recupere items si no está definido el depósito
					(	 @showzerostock = 'false'	AND
						(	@stor_id = -1			OR
							(CONVERT(integer,(tmpAStock.AStock * @ws_PotentialStockLimit / 100)) > 0)
					    )
					)
				)


		AND		(
					(@option = 1)													-- items (todos)
					OR
					(@option = 2 AND wsOferta.item_id  IS NOT NULL /*ISNULL(ti.item_liquidation,'false') = 'true'*/)	-- ofertas
					OR
					(@option = 3 AND wsNovedad.item_id IS NOT NULL /*ISNULL(ti.item_newness,'false')	 = 'true'*/)	-- novedades
				)



		ORDER BY	SUBSTRING
						(
							CASE	WHEN ti.item_WebSite_desc					 IS NULL THEN ti.item_desc
									WHEN LEN(ltrim(rtrim(ti.item_WebSite_desc))) = 0	 THEN ti.item_desc
									ELSE ti.item_WebSite_desc
							END
						,1,@ws_griddesign_maxlength_desc)

	-- ==========================================================================================================







	DECLARE @queryfinal		NVARCHAR(4000)

	SELECT	@queryfinal =
	'SELECT	s.[val], ' +

			's.[col1]														[item_id1]		,
			dbo.fnGetWordsCutByChar(ti1.item_desc,'' '',13)					[item_desc1]	,
			ti1.item_price													[item_price1]		' +

			CASE WHEN @ws_cols > 1 then
			',s.[col2]														[item_id2],
			dbo.fnGetWordsCutByChar(ti2.item_desc,'' '',13)					[item_desc2]	,
			ti2.item_price													[item_price2]		'
			ELSE ''
			END		+


			CASE WHEN @ws_cols > 2 then
			',s.[col3]														[item_id3],
			dbo.fnGetWordsCutByChar(ti3.item_desc,'' '',13)					[item_desc3]	,
			ti3.item_price													[item_price3]		'
			ELSE ''
			END		+


			CASE WHEN @ws_cols > 3 then
			',s.[col4]														[item_id4],
			dbo.fnGetWordsCutByChar(ti4.item_desc,'' '',13)					[item_desc4]	,
			ti4.item_price													[item_price4]		'
			ELSE ''
			END		+


			CASE WHEN @ws_cols > 4 then
			',s.[col5]														[item_id5],
			dbo.fnGetWordsCutByChar(ti5.item_desc,'' '',13)					[item_desc5]	,
			ti5.item_price													[item_price5]		'
			ELSE ''
			END		+

	'FROM	(
			SELECT	convert(int,new_id/' + CONVERT(VARCHAR,@ws_cols) + ')									[val] ' +


			',sum(CASE new_id % ' + CONVERT(VARCHAR,@ws_cols) + ' WHEN 0 THEN ISNULL(item_id, null) END)	[col1] ' +


			CASE WHEN @ws_cols > 1 then
			',sum(CASE new_id % ' + CONVERT(VARCHAR,@ws_cols) + ' WHEN 1 THEN ISNULL(item_id, null) END)	[col2] '
			ELSE ''
			END		+

			CASE WHEN @ws_cols > 2 then
			',sum(CASE new_id % ' + CONVERT(VARCHAR,@ws_cols) + ' WHEN 2 THEN ISNULL(item_id, null) END)	[col3] '
			ELSE ''
			END		+

			CASE WHEN @ws_cols > 3 then
			',sum(CASE new_id % ' + CONVERT(VARCHAR,@ws_cols) + ' WHEN 3 THEN ISNULL(item_id, null) END)	[col4] '
			ELSE ''
			END		+

			CASE WHEN @ws_cols > 4 then
			',sum(CASE new_id % ' + CONVERT(VARCHAR,@ws_cols) + ' WHEN 3 THEN ISNULL(item_id, null) END)	[col5] '
			ELSE ''
			END		+

			'FROM	#tmpFinal


			GROUP BY convert(int,new_id/' + CONVERT(VARCHAR,@ws_cols) + ')
			) s '  +

										'left join #tmpFinal ti1 on ti1.item_id = s.col1 ' +
			CASE WHEN @ws_cols > 1 then	'left join #tmpFinal ti2 on ti2.item_id = s.col2 ' ELSE '' END +
			CASE WHEN @ws_cols > 2 then	'left join #tmpFinal ti3 on ti3.item_id = s.col3 ' ELSE '' END +
			CASE WHEN @ws_cols > 3 then	'left join #tmpFinal ti4 on ti4.item_id = s.col4 ' ELSE '' END +
			CASE WHEN @ws_cols > 4 then	'left join #tmpFinal ti5 on ti5.item_id = s.col5 ' ELSE '' END





	--SELECT @queryfinal
	EXEC (@queryfinal)

END
GO




