CREATE PROCEDURE [dbo].[spItem_getDetailForWeb]
(
	@comp_id			INT,
	@lang_id			INT,
	@item_id			INT,
	@prli_id			INT,
	@stor_id			INT,
	@ws_id				INT
)
AS

BEGIN

	SET NOCOUNT ON


	-- ----------------------------------------------------
	-- Testing
	-- ----------------------------------------------------
	/*
	DECLARE @comp_id		INT,
			@item_id		INT,
			@prli_id		INT,
			@stor_id		INT
	select	@comp_id		=1,
			@item_id		=821,
			@prli_id		=1,
			@stor_id		=1
	*/
	-- ----------------------------------------------------



	--99
	-- -----------------------------------------------------------
	-- Trae de que manera debe mostrarse el precio (Moneda)
	-- -----------------------------------------------------------
	DECLARE @intCurrId2PriceConvert AS INT
	SET		@intCurrId2PriceConvert = -1
	SELECT  @intCurrId2PriceConvert	= IsNull(twsn.ws_curr_id4Prices,-1)
		FROM tbWebSite_Names twsn
		WHERE	twsn.comp_id	= @comp_id AND
				twsn.ws_id		= @ws_id
	-- -----------------------------------------------------------




	SELECT	ti.item_id,
			dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99)		[AStock]
		INTO	#tmpAStock
		FROM	tbItem ti					WITH (NOLOCK)
		WHERE	ti.comp_id	= @comp_id
		AND		ti.item_id	= @item_id







	-- ==========================================================================================================
	-- recuperamos el límite de stock potencial y la marca indicadora de como mostrar los precios del web_site seleccionado
	-- ==========================================================================================================
	DECLARE @ws_PotentialStockLimit		INT,
			@ws_showpricewithtax		BIT

	SELECT	@ws_PotentialStockLimit		= isnull(twsn.ws_PotentialStockLimit,0),
			@ws_showpricewithtax		= isnull(twsn.ws_showpricewithtax,'false')

		FROM	tbWebSite_Names				twsn		WITH (NOLOCK)

		WHERE	twsn.comp_id	= @comp_id
		AND		twsn.ws_id		= @ws_id
	--SELECT @ws_PotentialStockLimit, @ws_showpricewithtax
	-- ==========================================================================================================


	IF @ws_PotentialStockLimit = 0
		SET @ws_PotentialStockLimit = 100



	SELECT	ti.item_code,
			ti.item_desc,
			ISNULL(ti.item_detail,'')																[item_detail],
			ti.item_picture,
			ti.item_guarantee,
			ISNULL(ti.item_annotation,'')															[item_annotation],
			ISNULL(p.pres_desc,'')																	[pres_desc],
			ISNULL(tc.cat_desc,'')																	[cat_desc],
			ISNULL(tsc.subcat_desc,'')																[subcat_desc],
			ISNULL(tb.brand_desc,'')																[brand_desc],

			ISNULL(tscy.curr_symbol,'') + ' ' + CONVERT(VARCHAR,dbo.fnGetExchange2(@comp_id,ISNULL(tpli.prli_price, 0),
																					tpli.curr_id,
																					CASE
																					    WHEN @intCurrId2PriceConvert <> -1  THEN @intCurrId2PriceConvert
																					    ELSE									 tpli.curr_id
																					END ,
																					0,
																					0,
																					0,
																					'False'))		[item_price],

			CASE
				WHEN NOT ISNULL(tmpAStock.AStock,0) < ti.item_cantOpt							THEN 'g'
				WHEN	 ISNULL(tmpAStock.AStock,0) BETWEEN ti.item_cantMin AND ti.item_cantOpt	THEN 'y'
				WHEN	 ISNULL(tmpAStock.AStock,0) < ti.item_cantMin							THEN 'r'
			END																						[signal],

			LTRIM(RTRIM(ISNULL(tscy.curr_symbol,'')))												[curr_symbol],
			CASE
				WHEN @intCurrId2PriceConvert <> -1 AND @ws_showpricewithtax = 'true' THEN
										CONVERT(NVARCHAR,
											dbo.fnGetExchange2(	@comp_id,
																isnull(tpli.prli_price,0) + (isnull(tpli.prli_price,0) * ttn.tax_percentage / 100),
																tpli.curr_id,
																@intCurrId2PriceConvert,
																0,
																0,
																0,
																'False')
												)
				WHEN @intCurrId2PriceConvert <> -1 AND @ws_showpricewithtax = 'False' THEN
										CONVERT(NVARCHAR,
											dbo.fnGetExchange2(	@comp_id,
																isnull(tpli.prli_price,0),
																tpli.curr_id,
																@intCurrId2PriceConvert,
																0,
																0,
																0,
																'False')
												)


				WHEN @ws_showpricewithtax = 'true' THEN
										CONVERT(NVARCHAR,ISNULL(tpli.prli_price,0) +
															(ISNULL(tpli.prli_price,0) * ttn.tax_percentage / 100))
				ELSE
										CONVERT(NVARCHAR,ISNULL(tpli.prli_price,0))
				END																					[prli_price],

			CONVERT(VARCHAR,ISNULL(ti.item_cantOpt, 0))												[item_cantOpt],

			--CONVERT(VARCHAR,ISNULL(dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,9999999999.99), 0))	[itst_cant],

			CONVERT(integer,(ISNULL(tmpAStock.AStock, 0) * @ws_PotentialStockLimit / 100))			[itst_cant],



			ISNULL(ti.item_annotation1,'')															[item_annotation1],
			ISNULL(ti.item_annotation2,'')															[item_annotation2],

			ti.brand_id,
			CASE WHEN tb.brand_image	IS NULL THEN 'false' ELSE 'true' END 						[brand_image],
			ti.cat_id,
			CASE WHEN tc.cat_image		IS NULL THEN 'false' ELSE 'true' END 						[cat_image],
			ti.subcat_id,
			CASE WHEN tsc.subcat_image	IS NULL THEN 'false' ELSE 'true' END 						[subcat_image],

			ISNULL(ti.item_WebSite_vendorPage,'')													[item_WebSite_vendorPage],
			ISNULL(ti.item_WebSite_vendorDrivers,'')												[item_WebSite_vendorDrivers],


			CASE	WHEN ti.item_WebSite_desc					 IS NULL THEN	ti.item_desc
					WHEN LEN(ltrim(rtrim(ti.item_WebSite_desc))) = 0	 THEN	ti.item_desc
					ELSE														ti.item_WebSite_desc
			END
			--ISNULL(ti.item_WebSite_desc,'')
																									[item_WebSite_desc]


	FROM 	dbo.tbItem										ti		WITH (NOLOCK)

			left join dbo.tbPresentation					p		WITH (NOLOCK)
			on		p.comp_id			=	ti.comp_id
			and		p.pres_id			=	ti.pres_id

			LEFT JOIN tbCategory							tc		WITH (NOLOCK)
			ON		tc.comp_id			=	ti.comp_id
			AND		tc.cat_id			=	ti.cat_id

			LEFT JOIN tbSubCategory							tsc		WITH (NOLOCK)
			ON		tsc.comp_id			=	ti.comp_id
			AND		tsc.cat_id			=	ti.cat_id
			AND		tsc.subcat_id		=	ti.subcat_id

			LEFT JOIN tbBrand								tb		WITH (NOLOCK)
			ON		tb.comp_id			=	ti.comp_id
			AND		tb.brand_id			=	ti.brand_id

			LEFT JOIN tbPriceListItems						tpli	WITH (NOLOCK)
			ON		tpli.comp_id		=	ti.comp_id
			AND		tpli.item_id		=	ti.item_id
			AND		tpli.prli_id		=	@prli_id

			LEFT JOIN tbsysCurrency							tscy	WITH (NOLOCK)
			ON		tscy.curr_id		=	CASE
			  		            		 	    WHEN @intCurrId2PriceConvert <> -1 THEN @intCurrId2PriceConvert
			  		            		 	    ELSE									tpli.curr_id
			  		            		 	END


			--99
			LEFT JOIN tbsyscurrency					tsc33
				ON tsc33.curr_id		= @intCurrId2PriceConvert

	--		LEFT JOIN tbItemStorage							tis
	--		ON		tis.comp_id			=	i.comp_id
	--		AND		tis.item_id			=	i.item_id
	--		AND		tis.stor_id			=	@stor_id

			LEFT JOIN vwItemTaxesOnlyOneIvaTax				vitooit	WITH (NOLOCK)
			ON vitooit.comp_id		= ti.comp_id
			AND vitooit.item_id		= ti.item_id

			LEFT JOIN tbTaxName								ttn		WITH (NOLOCK)
			ON	ttn.comp_id			= ti.comp_id
			AND ttn.tax_id			= vitooit.tax_id

			INNER JOIN #tmpAStock							tmpAStock
			ON	ti.item_id			= tmpAStock.item_id


	WHERE 	ti.comp_id		=	@comp_id
	AND 	ti.item_id		=	@item_id


END
GO



CREATE PROCEDURE [dbo].[spItem_GetDiscounts4ItemSelectionGrid]
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@item_id	INT
)
AS



	BEGIN
		SET NOCOUNT ON

		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@item_id	INT

			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@prof_id	= 1,
				@item_id	= 492

				DROP TABLE #tmpTaxes
		*/
		-- ----------------------------------------------



		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- *********************************************************************************************************
		-- Generación de temporal con la sumatoria de impuestos por cada artículo
		-- *********************************************************************************************************
			CREATE TABLE #tmpTaxes ( comp_id  INT ,item_id  INT PRIMARY KEY,tax_percentage  decimal(19, 6) NULL)
			INSERT INTO #tmpTaxes
			(
				comp_id,
				item_id,
				tax_percentage
			)

			SELECT
				tit.comp_id,
				tit.item_id,
				SUM(ttn.tax_percentage)
			FROM	tbItemTaxes								tit
			INNER JOIN tbTaxName							ttn
				ON	ttn.tax_id				= tit.tax_id	AND
					ttn.comp_id				= tit.comp_id	AND
					tit.tax_itemComposed	= 'False'
			WHERE	tit.comp_id				= @comp_id		AND
					tit.item_id				= @item_id
			GROUP BY tit.comp_id, tit.item_id
		-- *********************************************************************************************************


		-- *********************************************************************************************
		-- RECUPERAMOS LOS DESCUENTOS POR VENTAS DEL ARTÍCULO
		-- *********************************************************************************************
			DECLARE @tblItemDiscounts TABLE
											(
												comp_id					INT,
												item_id					INT,
												item_comboDisc_Desc	NVARCHAR(200),
												item_comboDisc_Cant	DECIMAL(18,2),
												item_comboDisc_Disc	DECIMAL(18,4),
												orderByQty			INT IDENTITY(1,1)
											)


			INSERT INTO @tblItemDiscounts
			(
				comp_id,
				item_id,
				item_comboDisc_Desc,
				item_comboDisc_Cant,
				item_comboDisc_Disc
			)
			SELECT
				ti.comp_id,
				ti.item_id,
				ISNULL(ti.item_comboDisc_Desc1,''),
				ISNULL(ti.item_comboDisc_Cant1,0),
				ISNULL(ti.item_comboDisc_Disc1,0)
				FROM tbItem							ti	WITH(NOLOCK)
				WHERE	ti.comp_id					= @comp_id	AND
						ti.item_id					= @item_id	AND
						ti.item_comboDisc_Disc1    <> 0

			INSERT INTO @tblItemDiscounts
			(
				comp_id,
				item_id,
				item_comboDisc_Desc,
				item_comboDisc_Cant,
				item_comboDisc_Disc
			)
			SELECT
				ti.comp_id,
				ti.item_id,
				ISNULL(ti.item_comboDisc_Desc2,''),
				ISNULL(ti.item_comboDisc_Cant2,0),
				ISNULL(ti.item_comboDisc_Disc2,0)
				FROM tbItem							ti	WITH(NOLOCK)
				WHERE	ti.comp_id					= @comp_id	AND
						ti.item_id					= @item_id	AND
						ti.item_comboDisc_Disc2    <> 0

			INSERT INTO @tblItemDiscounts
			(
				comp_id,
				item_id,
				item_comboDisc_Desc,
				item_comboDisc_Cant,
				item_comboDisc_Disc
			)
			SELECT
				ti.comp_id,
				ti.item_id,
				ISNULL(ti.item_comboDisc_Desc3,''),
				ISNULL(ti.item_comboDisc_Cant3,0),
				ISNULL(ti.item_comboDisc_Disc3,0)
				FROM tbItem							ti	WITH(NOLOCK)
				WHERE	ti.comp_id					= @comp_id	AND
						ti.item_id					= @item_id	AND
						ti.item_comboDisc_Disc3    <> 0


			INSERT INTO @tblItemDiscounts
			(
				comp_id,
				item_id,
				item_comboDisc_Desc,
				item_comboDisc_Cant,
				item_comboDisc_Disc
			)
			SELECT
				ti.comp_id,
				ti.item_id,
				ISNULL(ti.item_comboDisc_Desc4,''),
				ISNULL(ti.item_comboDisc_Cant4,0),
				ISNULL(ti.item_comboDisc_Disc4,0)
				FROM tbItem							ti	WITH(NOLOCK)
				WHERE	ti.comp_id					= @comp_id	AND
						ti.item_id					= @item_id	AND
						ti.item_comboDisc_Disc4    <> 0

		-- *********************************************************************************************

			-- * ( (1-(temp.item_comboDisc_Disc / 100) ))

		SELECT
			tis.ise_Desc,
			CONVERT(DECIMAL(20,4),
			tpli.prli_price +
			CASE
				WHEN tis.is_prli_plusIVATax = 'True'	THEN	((tpli.prli_price * tmp.tax_percentage) / 100)
				ELSE											0
			END		)								[originalPrice],
			tc.curr_symbol,
			temp.item_comboDisc_Cant,


			-- Precio con Descuento
			CONVERT(DECIMAL(20,4),
			(tpli.prli_price +
			CASE
				WHEN tis.is_prli_plusIVATax = 'True'	THEN	((tpli.prli_price * tmp.tax_percentage) / 100)
				ELSE											0
			END	)	* ( (1-(temp.item_comboDisc_Disc / 100) ))
					)								[Item_Price],
			-- Precio con Descuento


			temp.item_comboDisc_Disc				[item_comboDisc_Disc1],





			-- Precio por Cantidad
			CONVERT(DECIMAL(20,2),
			(
			(tpli.prli_price +
			CASE
				WHEN tis.is_prli_plusIVATax = 'True'	THEN	((tpli.prli_price * tmp.tax_percentage) / 100)
				ELSE											0
			END	)	* ( (1-(temp.item_comboDisc_Disc / 100) ))
			) * temp.item_comboDisc_Cant)			[Item_PriceByQTY],
			-- Precio por Cantidad
			temp.item_comboDisc_Desc

		FROM tbItem								ti
			LEFT JOIN @tblItemDiscounts		temp
				ON	temp.comp_id = ti.comp_id	AND
					temp.item_id = ti.item_id
			INNER JOIN tbPriceListItems			tpli
				ON	tpli.comp_id = ti.comp_id	AND
					tpli.item_id = ti.item_id
			INNER JOIN tbItemSelection			tis
				ON	tis.comp_id = tpli.comp_id	AND
					tis.prli_id = tpli.prli_id
			INNER JOIN tbPriceList				tpl
				ON	tpl.comp_id	= tis.comp_id	AND
					tpl.prli_id	= tis.prli_id	AND
					tpl.prli_isAvailable4DiscountByQTY = 'True'
			INNER JOIN tbsysCurrency			tc
				ON	tc.curr_id	= tpli.curr_id
			INNER JOIN #tmpTaxes				tmp
				ON	tmp.comp_id	= ti.comp_id	AND
					tmp.item_id	= ti.item_id
		WHERE	ti.comp_id	= @comp_id			AND
				ti.item_id	= @item_id			AND
			   (
			   		tis.bra_id	= @bra_id
						OR
					tis.bra_id IS NULL
			    )								AND
				tis.prof_id = @prof_id			AND
				tis.prli_id	IS NOT NULL			AND
				tis.is_disabled = 'False'

		ORDER BY tis.is_order ASC, temp.orderByQty ASC

	END

GO





