CREATE PROCEDURE spItem_GetItemID_ByItemEan
(
	@comp_id	INT,
	@item_ean	NVARCHAR(50)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_ean	NVARCHAR(50)
			SELECT
				@comp_id	= 1,
				@item_ean	= '2050340000008'
		*/
		-- --------------------------------------------------------

		DECLARE @item_id	INT
		SET		@item_id	= -1

		SELECT
			@item_id				= ti.item_id
			FROM tbItem							ti	WITH(NOLOCK)
			WHERE	ti.comp_id		= @comp_id	AND
					ti.item_code	= @item_ean


		IF @item_id = -1
			BEGIN
				SELECT
					@item_id			= tie.item_id
					FROM tbItemEAN					tie	WITH(NOLOCK)
					WHERE	tie.comp_id = @comp_id	AND
							tie.ie_ean	= @item_ean
			END


		SELECT @item_id [item_id]

	END
GO



