CREATE procedure [dbo].[spItem_getLayout1]
(
		@comp_id			INT,
		@lang_id			INT,
		@ws_id              INT,
		@swsc_id            INT,

		@option				INT,

		@item_id			INT,
		@curr_id			INT,
		@prli_id			INT,
		@stor_id			INT,
		@cat_id             INT,
		@subcat_id			INT


)
as
SET NOCOUNT ON


/*
DECLARE @comp_id			int,
		@lang_id			int,
		@ws_id				INT,
		@swsc_id			INT,
		@option				INT,
		@item_id            int,
		@curr_id			int,
		@prli_id			INT,
		@stor_id			INT,
		@cat_id             INT,
		@subcat_id			INT
SELECT	@comp_id			=1,
		@lang_id			=2,
		@ws_id				=3,
		@swsc_id			=1,
		@option				=1,
		@item_id			=-1,
		@curr_id			=1,
		@prli_id			=1,
		@stor_id			=1,
		@cat_id             =26,
		@subcat_id			=3819
*/

IF @option = 1 --artículos

	SELECT  ti.item_desc,
			ti.item_picture,
			ltrim(rtrim(isnull(tc.curr_symbol,''))) + ' ' + CONVERT(nVARCHAR,tpli.prli_price) [item_price],
			tut2.utexts_desc	[buy],
			tut1.utexts_desc	[info],
			ti.item_annotation,
			tc2.cat_id,
			tsc.subcat_id,
			ti.item_id,
			tc2.cat_desc + ' - ' + tsc.subcat_desc [desc],
			ti.item_detail,
			ti.item_annotation1,
			ti.item_annotation2,
			ti.item_web

	FROM	dbo.tbItem								ti

			LEFT JOIN tbPriceListItems				tpli
			ON	tpli.comp_id		= ti.comp_id
			AND tpli.item_id		= ti.item_id
			AND tpli.prli_id		= @prli_id

			LEFT JOIN tbPriceList					tpl
			ON	tpl.comp_id			= ti.comp_id
			AND tpl.prli_id			= tpli.prli_id

			LEFT JOIN tbBranch						tb
			ON	tb.comp_id			= ti.comp_id
			AND tb.bra_id			= ti.bra_id

			LEFT JOIN tbStorage						ts
			ON  ts.comp_id			= ti.comp_id
			AND ts.stor_id			= tb.stor_id

			LEFT JOIN tbsysCurrency					tc
			ON	tc.curr_id			= tpli.curr_id
			AND tc.curr_id			= tpli.curr_id

			INNER JOIN tbCategory					tc2
			ON tc2.comp_id			= ti.comp_id
			AND tc2.cat_id			= ti.cat_id

			INNER JOIN tbSubCategory				tsc
			ON  tsc.comp_id			= ti.comp_id
			AND tsc.cat_id			= ti.cat_id
			AND tsc.subcat_id		= ti.subcat_id

			LEFT JOIN tbsysUniqueTexts				tut1
			ON	tut1.lang_id		= @lang_id
			AND tut1.utexts_id		= 224012

			LEFT JOIN tbsysUniqueTexts				tut2
			ON	tut2.lang_id		= @lang_id
			AND tut2.utexts_id		= 224013


	WHERE	ti.comp_id		= @comp_id
	AND     (ti.item_id		= @item_id		OR @item_id		= -1)
	AND     (tc2.cat_id		= @cat_id		OR @cat_id		= -1)
	AND     (tsc.subcat_id	= @subcat_id	OR @subcat_id	= -1)


	order by tc2.cat_desc,tsc.subcat_desc,item_desc

ELSE

	IF @option = 2 --login

		SELECT 'Ingresar usuario' [tbwe], 'Ingresar' [btnOk], 'Salir' [btnClose]

	ELSE

		IF @option = 3 --flash

		SELECT '~/App_ThumbImages/Bubbles.swf' [purl]

		ELSE

		SELECT 1 --todos los otros



EXEC spWebSite_Styles_getDataById @comp_id,	@ws_id,	@swsc_id
GO








CREATE PROCEDURE [dbo].[spItem_getNextCode]
(
	@comp_id				INT,
	@errormessage			VARCHAR(200) OUTPUT
)
AS
SET NOCOUNT ON
-- ==============================================================================================================
-- Author		: MOH
-- Creation Date: 2010-10-12
-- Parte		: Se generó a partir del Parte 615 ver detalle en wfmGenericEditNew.aspx.vb
-- Description	: Se obtiene el próximo valor no utilizado en item_code a partir del número de contador 10
-- ==============================================================================================================



/*
DECLARE	@comp_id		INT,
		@errormessage	VARCHAR(200)
SELECT	@comp_id		= 1
*/





DECLARE		@ok				BIT,
			@next_value		INT,
			@return_value	INT
SET			@ok				= 'false'
SET 		@return_value	= 0
SET			@errormessage	= ''





-- Ciclo hasta que se encuentre un valor no utilizado en item_code
WHILE @ok = 'false'
BEGIN


	-- Obtener el próximo valor del contador 10
	EXEC spCounters_getNextValue
			@comp_id,
			0,
			10,
			@counter_value = @next_value OUTPUT
	--SELECT @next_value



	-- Verificación de existencia del próximo valor obtenido del contador en el campo item_code de tbItem
	IF NOT EXISTS (SELECT TOP 1 	1
					FROM	tbItem						ti with (NOLOCK)
					WHERE	ti.comp_id					= @comp_id
					AND		LTRIM(RTRIM(ti.item_code))	= CONVERT(VARCHAR,@next_value))
	BEGIN

		-- si el valor no existe se cambia el valor de la marca para que salga del ciclo
		SET	@ok	= 'true'

	END
	--SELECT @ok

END


-- se setea el valor de retorno
SET @return_value = @next_value
--SELECT 'final', @next_value

RETURN @return_value









GO



CREATE PROCEDURE spItem_GetParent
(
	@comp_id	INT,
	@item_child	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------
		-- TESTING
		-- ------------------------------
		/*
			DECLARE
				@comp_id	INT,
