CREATE procedure [dbo].[spItem_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@option				int,
		@item_desc			varchar(200),
		@pres_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@bra_id				int,
		@curr_id			int,
		@byor_id			int,
		@guid				VARCHAR(50), --CF DE ITEMS
		@intBranch4Lang		int
)
as
SET NOCOUNT ON



---------------------------------------------------
---------------------------------------------------
/*
DECLARE @comp_id			int,
		@lang_id			int,
		@page_id			int,

		@option				int,
		@item_desc			varchar(200),
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@pres_id			int,
		@bra_id				int,
		@curr_id			int,
		@byor_id			INT,
		@intBranch4Lang		int

SELECT	@comp_id			=1,
		@lang_id			=2,
		@page_id			=10006,

		@option				=-1,
		@item_desc			='',
		@cat_id				=-1,
		@subcat_id			=-1,
		@brand_id			=-1,
		@pres_id			=-1,
		@bra_id				=1,
		@curr_id			=1,
		@byor_id			=8

DROP TABLE #tmp_Item
*/
---------------------------------------------------
---------------------------------------------------

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------



DECLARE @fun_id INT
SET @fun_id = 1

SELECT	I.item_code,
		I.item_desc,
		I.item_detail,
		I.item_vendorCode,
		C.cat_desc,
		SC.subcat_desc,
		B.brand_desc,
		P.pres_desc,
		CC.curr_desc,
		I.item_upb,
		I.item_upp,
		I.item_cantMin,
		I.item_cantOpt,
		I.item_mult,
		I.item_commission,
		I.item_picture,
		I.item_guarantee,
		I.item_expser,
		o2.[optval_desc]	[item_made],
		o3.[optval_desc]	[item_web],
		I.item_annotation,
		BR.bra_desc,
		o1.[optval_desc]	[item_newness],
		o.[optval_desc]		[item_liquidation],
		I.item_withDecimal,
		BO.byor_desc

INTO #tmp_Item


FROM	dbo.tbItem						I	WITH(NOLOCK)

		INNER JOIN @tblComplexFilter_Items		tempITEM
		ON tempitem.item_id				= I.item_id

		LEFT JOIN [tbPresentation]		P	WITH(NOLOCK)
		ON	P.[comp_id]					=	I.[comp_id]
		AND P.[pres_id]					=	I.[pres_id]

		LEFT JOIN tbCategory			C	WITH(NOLOCK)
		ON	I.[comp_id]					=	C.[comp_id]
		AND I.[cat_id]					=	C.[cat_id]

		LEFT JOIN tbSubCategory			SC	WITH(NOLOCK)
		ON	I.[comp_id]					=	SC.[comp_id]
		AND I.[cat_id]					=	SC.[cat_id]
		AND I.[subcat_id]				=	SC.[subcat_id]

		LEFT JOIN tbBrand				B	WITH(NOLOCK)
		ON	B.[comp_id]					=	I.[comp_id]
		AND B.[brand_id]				=	I.[brand_id]

		LEFT JOIN	tbBranch			BR	WITH(NOLOCK)
		ON BR.[comp_id]					=	I.[comp_id]
		AND BR.[bra_id]					=	I.[bra_id]

		LEFT JOIN tbsysCurrency			CC	WITH(NOLOCK)
		ON	CC.[curr_id]				=	I.[curr_id]

		LEFT JOIN dbo.tbByOrder			BO
		ON	BO.[comp_id]				=	I.[comp_id]
		AND BO.[byor_id]				=	I.[byor_id]

		left JOIN [tbsysOptionsValues]	o	WITH(NOLOCK)
		ON	o.[optval_id]				= I.[item_liquidation]
		AND	o.[optval_class]			= 1
		and o.lang_id					= @lang_id

		left JOIN [tbsysOptionsValues]	o1	WITH(NOLOCK)
		on	o1.[optval_id]				= I.[item_newness]
		AND	o1.[optval_class]			= 1
		and o1.lang_id					= @lang_id

		left JOIN [tbsysOptionsValues]	o2	WITH(NOLOCK)
		on	o2.[optval_id]				= I.[item_made]
		AND	o2.[optval_class]			= 1
		and o2.lang_id					= @lang_id

		left JOIN [tbsysOptionsValues]	o3	WITH(NOLOCK)
		on	o3.[optval_id]				= I.[item_web]
		AND	o3.[optval_class]			= 1
		and o3.lang_id					= @lang_id

		/*left join [tbsysOptionsValues]		o4
		on	o.[optval_id]		= @optval_id
		and	o.[optval_class]	= 1
		and	o.[lang_id]			= @lang_id*/



		WHERE		I.[comp_id]		=	@comp_id
		AND			(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
		AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
		AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
		AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
		AND			(@bra_id		= -1 or I.[bra_id]		=	@bra_id)
		AND			(@curr_id		= -1 or I.[curr_id]		=	@curr_id)
		--AND			(@byor_id		= -1 or I.[byor_id]		=	@byor_id)
		and			(
					(@option	 = -1 ) or
					(@option	 = 0 and I.item_desc like @item_desc + '%') or
					(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
					(@option	 = 2 and I.item_desc = @item_desc ) or
					(@option	 = 3 and I.item_desc <> @item_desc ) or
					(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
		)


--order by item_desc


	IF @byor_id = 1 -- Descripcion
		BEGIN
			SELECT * FROM #tmp_Item tmp
			ORDER BY	tmp.item_desc
		END
	ELSE
		IF @byor_id = 2 -- Categoría, SubCategoría, Descripción
			BEGIN
				SELECT * FROM #tmp_Item tmp
				ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.item_desc
			END
		ELSE
			IF @byor_id = 3 -- Categoría, SubCategoría, Código
				BEGIN
					SELECT * FROM #tmp_Item tmp
					ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.item_code
				END
			ELSE
				IF @byor_id = 4 -- Còdigo
					BEGIN
						SELECT * FROM #tmp_Item tmp
						ORDER BY tmp.item_code ASC
					END
						IF @byor_id = 5 -- Marca, Descripción
							BEGIN
								SELECT * FROM #tmp_Item tmp
								ORDER BY tmp.brand_desc, tmp.item_desc
							END

						ELSE
							IF @byor_id = 6 -- Marca, Código
								BEGIN
									SELECT * FROM #tmp_Item tmp
									ORDER BY tmp.brand_desc,tmp.item_code
								END
							ELSE
								IF @byor_id = 7 -- Categoría, SubCategoría, Marca, Descripción
									BEGIN
										SELECT * FROM #tmp_Item tmp
										ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.brand_desc,tmp.item_desc
									END
										IF @byor_id = 8 -- Categoría, SubCategoría, Marca, Código
											BEGIN
												SELECT * FROM #tmp_Item tmp
												ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.brand_desc,tmp.item_code
											END






exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/

SELECT	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id   = 43
      	 and   t.[page_id] = @related_page_id
      	 and   t.[type_id] = 1					) [params1],

		CASE @option WHEN -1 THEN
				(SELECT	tut.utexts_desc
				  FROM	tbsysUniqueTexts tut
				  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
			ELSE
				@item_desc
		END		[params2],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id   = 36
      	 and   t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

		CASE @cat_id WHEN -1 THEN
				(SELECT	tut.utexts_desc
				 FROM	tbsysUniqueTexts tut
				 WHERE	tut.lang_id   = @lang_id
				 AND	tut.utexts_id = 1)
			ELSE
				(SELECT	tc.cat_desc
				 FROM	tbCategory tc
				 WHERE	tc.comp_id = @comp_id
				 AND	tc.cat_id  = @cat_id)
		END		[params4],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 38
         and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],
		CASE @subcat_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tsc.subcat_desc
					FROM	tbSubCategory tsc
					WHERE	tsc.comp_id = @comp_id AND tsc.subcat_id= @subcat_id)
		END		[params6],

       (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 73
         and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],
		CASE @brand_id WHEN -1 THEN
				(SELECT	 tut.utexts_desc
				 FROM	 tbsysUniqueTexts tut
				 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT	tb.brand_desc
				 FROM	tbBrand tb
				 WHERE	tb.comp_id  = @comp_id
				 AND	tb.brand_id = @brand_id)
		END		[params8],

		 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 371
         and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],
		CASE @pres_id WHEN -1 THEN
				(SELECT	 tut.utexts_desc
				 FROM	 tbsysUniqueTexts tut
				 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tp.pres_desc
					FROM	tbPresentation tp
					WHERE	tp.comp_id = @comp_id AND tp.pres_id= @pres_id)
		END		[params10],

		 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 28
         and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],
		CASE @bra_id WHEN -1 THEN
				(SELECT	 tut.utexts_desc
				 FROM	 tbsysUniqueTexts tut
				 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tb2.bra_desc
					FROM	tbBranch tb2
					WHERE	tb2.comp_id = @comp_id AND tb2.bra_id= @bra_id)
		END		[params12],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 106
         and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],
		 CASE @curr_id WHEN -1 THEN
				(SELECT	 tut.utexts_desc
				 FROM	 tbsysUniqueTexts tut
				 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT	tc.curr_desc
				 FROM	tbsysCurrency tc
				 WHERE	tc.curr_id= @curr_id)
		END		[params14],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 375
         and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],
		 CASE @byor_id WHEN -1 THEN
				(SELECT	 tut.utexts_desc
				 FROM	 tbsysUniqueTexts tut
				 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tbo.optval_desc
					FROM	tbsysOptionsValues tbo
					WHERE	tbo.lang_id = @lang_id
					AND tbo.optval_id= @byor_id AND
				   tbo.optval_class = 327)
		END		[params16]



GO








CREATE procedure [dbo].[spItem_getReportCodeBar]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int

--		@option				int,
--		@item_desc			varchar(200)
--		@pres_id			int,
--		@cat_id				int,
--		@subcat_id			int
--		@brand_id			int,
--		@bra_id				int,
--		@curr_id			int,
--		@byor_id			int
)
as


SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



/*DECLARE @comp_id			int,
		@lang_id			int,
		@page_id			int
--		@option				int,
--		@item_desc			varchar(200),
--		@pres_id			int,
--		@cat_id				int,
--		@subcat_id			int,
--		@brand_id			int,
--		@bra_id				int,
--		@curr_id			int,
--		@byor_id			int

SELECT	@comp_id			=1,
		@lang_id			=2,
		@page_id			=10006
--		@option				=-1,
--		@item_desc			='ptas',
--		@pres_id			=-1,
--		@cat_id				=-1,
--		@subcat_id			=-1,
--		@brand_id			=-1,
--		@bra_id				=-1,
--		@curr_id			=-1,
--		@byor_id			=-1
*/

SELECT	I.item_code,
		I.item_desc,
		I.item_id
--		I.item_detail,
--		I.item_vendorCode,
--		C.cat_desc,
--		SC.subcat_desc,
--		B.brand_desc,
--		P.pres_desc,
--		CC.curr_desc,
--		I.item_upb,
--		I.item_upp,
--		I.item_cantMin,
--		I.item_cantOpt,
--		I.item_mult,
--		I.item_commission,
--		I.item_picture,
--		I.item_guarantee,
--		I.item_expser,
--		o2.[optval_desc]	[item_made],
--		o3.[optval_desc]	[item_web],
--		I.item_annotation,
--		BR.bra_desc,
--		o1.[optval_desc]	[item_newness],
--		o.[optval_desc]		[item_liquidation],
--		I.item_withDecimal,
--		BO.byor_desc


FROM	dbo.tbItem	I

		LEFT JOIN [tbPresentation]		P
		ON	P.[comp_id]					=	I.[comp_id]
		AND P.[pres_id]					=	I.[pres_id]

		LEFT JOIN tbCategory			C
		ON	I.[comp_id]					=	C.[comp_id]
		AND I.[cat_id]					=	C.[cat_id]

		LEFT JOIN tbSubCategory			SC
		ON	I.[comp_id]					=	SC.[comp_id]
		AND I.[cat_id]					=	SC.[cat_id]
		AND I.[subcat_id]				=	SC.[subcat_id]

		LEFT JOIN tbBrand				B
		ON	B.[comp_id]					=	I.[comp_id]
		AND B.[brand_id]				=	I.[brand_id]

		LEFT JOIN	tbBranch			BR
		ON BR.[comp_id]					=	I.[comp_id]
		AND BR.[bra_id]					=	I.[bra_id]

--		LEFT JOIN tbsysCurrency			CC
--		ON	CC.[curr_id]				=	I.[curr_id]
--
--		LEFT JOIN dbo.tbByOrder			BO
--		ON	BO.[comp_id]				=	I.[comp_id]
--		AND BO.[byor_id]				=	I.[byor_id]
--
--		left JOIN [tbsysOptionsValues] o
--		ON	o.[optval_id]				= I.[item_liquidation]
--		AND	o.[optval_class]			= 1
--		and o.lang_id					= @lang_id
--
--		left JOIN [tbsysOptionsValues] o1
--		on	o1.[optval_id]				= I.[item_newness]
--		AND	o1.[optval_class]			= 1
--		and o1.lang_id					= @lang_id
--
--		left JOIN [tbsysOptionsValues] o2
--		on	o2.[optval_id]				= I.[item_made]
--		AND	o2.[optval_class]			= 1
--		and o2.lang_id					= @lang_id
--
--		left JOIN [tbsysOptionsValues] o3
--		on	o3.[optval_id]				= I.[item_web]
--		AND	o3.[optval_class]			= 1
--		and o3.lang_id					= @lang_id

		/*left join [tbsysOptionsValues]		o4
		on	o.[optval_id]		= @optval_id
		and	o.[optval_class]	= 1
		and	o.[lang_id]			= @lang_id*/



--		WHERE		I.[comp_id]		=	@comp_id
--		AND			(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
--		AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
--		AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
--		AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
--		AND			(@bra_id		= -1 or I.[bra_id]		=	@bra_id)
--		AND			(@curr_id		= -1 or I.[curr_id]		=	@curr_id)
--		AND			(@byor_id		= -1 or I.[byor_id]		=	@byor_id)
--		and			(
--					(@option	 = -1 ) or
--					(@option	 = 0 and I.item_desc like @item_desc + '%') or
--					(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
--					(@option	 = 2 and I.item_desc = @item_desc ) or
--					(@option	 = 3 and I.item_desc <> @item_desc ) or
--					(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
--		)
--

order by item_desc



exec [spReports_getData]@comp_id, @lang_id,	@page_id
GO








CREATE procedure [dbo].[spItem_getReportComisionLiquidation]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@option				int,
		@item_desc			varchar(200),
		@sm_id				int,
		@dl_id				int,
		@cust_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int
)
as


BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON


	/*DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			int,

			@option				int,
			@item_desc			varchar(200),
			@sm_id				int,
			@dl_id				int,
			@cust_id			int,
			@cat_id				int,
			@subcat_id			int,
			@brand_id			int

	SELECT	@comp_id			=1,
			@lang_id			=2,
			@page_id			=10006,
			@option				=-1,
			@item_desc			='ptas',
			@sm_id				=-1,
			@dl_id				=-1,
			@cust_id			=-1,
			@cat_id				=-1,
			@subcat_id			=-1,
			@brand_id			=-1
	*/

	SELECT	CT.[ct_date],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, CT.ct_transaction) [Comprobante],
			isnull(B.[brand_commission],0)[brand_commission],
			isnull(ck_commission, 0) [ck_commission],
			isnull(sm_commission_bySale, 0)[sm_commission_bySale],
			isnull(cat_commission, 0) [cat_commission],
			isnull(subcat_commission, 0) [subcat_commission]


	FROM	tbCommercialTransactions			CT

			inner join tbCustomer				CU
			ON	CU.[comp_id]					=	CT.[comp_id]
			and CU.[cust_id]					=	CT.[cust_id]

			left join tbItemTransactions		IT
			on IT.[comp_id]						=   CT.[comp_id]
			and IT.[bra_id]						=	CT.[bra_id]
			and IT.[ct_transaction]				=	CT.[ct_transaction]

			left join tbItem					I
			on  I.[comp_id]						=	IT.[comp_id]
			and I.[item_id]						=	IT.[item_id]

			LEFT JOIN tbBrand					B
			ON	B.[comp_id]						=	I.[comp_id]
			AND B.[brand_id]					=	I.[brand_id]

			inner join vwCommercialTransactions_forSales   vwct
			on  ct.comp_id						= vwct.comp_id
			--and ct.bra_id						= vwct.bra_id
			and ct.ct_transaction				= vwct.ct_transaction

			left join tbCustomerKind			CK
			on CK.[comp_id]						=	CT.[comp_id]
			and CK.[user_id]					=	CT.[user_id]

			left join tbSalesman				SM
			ON	SM.[comp_id]					=	CT.[comp_id]
			and SM.[sm_id]						=	CT.[sm_id]
			and SM.[user_id]					=   CT.[user_id]
			and SM.[bra_id]						=   CT.[bra_id]

			LEFT JOIN tbCategory				C
			ON	C.[comp_id]						=	I.[comp_id]
			AND C.[cat_id]						=	I.[cat_id]

			LEFT JOIN tbSubCategory				SC
			ON	SC.[comp_id]					=	I.[comp_id]
			AND SC.[cat_id]						=	I.[cat_id]
			AND SC.[subcat_id]					=	I.[subcat_id]

			left join tbDelivery				DL
			on DL.[comp_id]						=	CT.[comp_id]
			and DL.[dl_id]						=	CT.[dl_id]


			WHERE		I.[comp_id]		=	@comp_id
			AND			(@sm_id			= -1 or CT.[sm_id]		=	@sm_id)
			AND			(@dl_id			= -1 or CT.[dl_id]		=	@dl_id)
			AND			(@cust_id		= -1 or CT.[cust_id]	=	@cust_id)
			AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
			AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
			AND			(@brand_id		= -1 or B.[brand_id]	=	@brand_id)
			and			(
						(@option	 = -1 ) or
						(@option	 = 0 and I.item_desc like @item_desc + '%') or
						(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
						(@option	 = 2 and I.item_desc = @item_desc ) or
						(@option	 = 3 and I.item_desc <> @item_desc ) or
						(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
			)


	order by 1



	exec [spReports_getData]@comp_id, @lang_id,	@page_id


END
GO








CREATE procedure [dbo].[spItem_getReportImage]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@option				int,
		@item_desc			varchar(200),
		@pres_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@bra_id				int,
		@curr_id			int,
		@byor_id			int,
		@intBranch4Lang		int
)
as


SET NOCOUNT ON


/*DECLARE @comp_id			int,
		@lang_id			int,
		@page_id			int,
		@option				int,
		@item_desc			varchar(200),
		@pres_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@bra_id				int,
		@curr_id			int,
		@byor_id			int

SELECT	@comp_id			=1,
		@lang_id			=2,
		@page_id			=10006,
		@option				=3,
		@item_desc			='ptas',
		@pres_id			=-1,
		@cat_id				=-1,
		@subcat_id			=-1,
		@brand_id			=-1,
		@bra_id				=-1,
		@curr_id			=-1,
		@byor_id			=-1
*/

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



SELECT	I.item_code,
		I.item_desc,
		I.item_picture--,
		--convert(binary,I.item_picture)as binary

FROM	dbo.tbItem	I

		LEFT JOIN [tbPresentation]		P
		ON	P.[comp_id]					=	I.[comp_id]
		AND P.[pres_id]					=	I.[pres_id]

		LEFT JOIN tbCategory			C
		ON	I.[comp_id]					=	C.[comp_id]
		AND I.[cat_id]					=	C.[cat_id]

		LEFT JOIN tbSubCategory			SC
		ON	I.[comp_id]					=	SC.[comp_id]
		AND I.[cat_id]					=	SC.[cat_id]
		AND I.[subcat_id]				=	SC.[subcat_id]

		LEFT JOIN tbBrand				B
		ON	B.[comp_id]					=	I.[comp_id]
		AND B.[brand_id]				=	I.[brand_id]

		LEFT JOIN	tbBranch			BR
		ON BR.[comp_id]					=	I.[comp_id]
		AND BR.[bra_id]					=	I.[bra_id]

		LEFT JOIN tbsysCurrency			CC
		ON	CC.[curr_id]				=	I.[curr_id]

		LEFT JOIN dbo.tbByOrder			BO
		ON	BO.[comp_id]				=	I.[comp_id]
		AND BO.[byor_id]				=	I.[byor_id]

		left JOIN [tbsysOptionsValues] o
		ON	o.[optval_id]				= I.[item_liquidation]
		AND	o.[optval_class]			= 1
		and o.lang_id					= @lang_id

		left JOIN [tbsysOptionsValues] o1
		on	o1.[optval_id]				= I.[item_newness]
		AND	o1.[optval_class]			= 1
		and o1.lang_id					= @lang_id

		left JOIN [tbsysOptionsValues] o2
		on	o2.[optval_id]				= I.[item_made]
		AND	o2.[optval_class]			= 1
		and o2.lang_id					= @lang_id

		left JOIN [tbsysOptionsValues] o3
		on	o3.[optval_id]				= I.[item_web]
		AND	o3.[optval_class]			= 1
		and o3.lang_id					= @lang_id

		/*left join [tbsysOptionsValues]		o4
		on	o.[optval_id]		= @optval_id
		and	o.[optval_class]	= 1
		and	o.[lang_id]			= @lang_id*/



		WHERE		I.[comp_id]		=	@comp_id
		AND			(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
		AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
		AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
		AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
		AND			(@bra_id		= -1 or I.[bra_id]		=	@bra_id)
		AND			(@curr_id		= -1 or I.[curr_id]		=	@curr_id)
		AND			(@byor_id		= -1 or I.[byor_id]		=	@byor_id)
		and			(
					(@option	 = 0 and I.item_desc like @item_desc + '%') or
					(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
					(@option	 = 2 and I.item_desc = @item_desc ) or
					(@option	 = 3 and I.item_desc <> @item_desc ) or
					(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
		)


order by item_desc



exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id
GO






CREATE procedure [dbo].[spItem_getReportPotentialStock]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

--		@option				int,
--		@item_desc			varchar(200),
		@item_id			int,
		@supp_id			int,

		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@pres_id			int,
		@stor_id			INT,
		@stor2_id			int,
		@bra_id				INT,
		@stock				int,
		@orders				int,
		@activity			INT,		-- Disabled
		@guid				VARCHAR(50),--CF DE ITEMS
		@intBranch4Lang		int


)
AS



BEGIN


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------






------------------------------------------------------------
------------------------------------------------------------
/*
	DECLARE 	@comp_id			int,
				@lang_id			int,
				@page_id			int,

				@item_id			int,
				@supp_id			int,

				@cat_id				int,
				@subcat_id			int,
				@brand_id			int,
				@pres_id			int,
				@stor_id			INT,
				@stor2_id			int,
				@bra_id				INT,
				@stock				int,
				@orders				int,
				@activity			INT,
				@intBranch4Lang		int



	SELECT		@comp_id			=1,
				@lang_id			=2,
				@page_id			=10023,
				@stor_id			= -1,

				@cat_id				=-1,
				@subcat_id			=-1,
				@pres_id			= -1,
				@brand_id			=-1,
				@bra_id				= 1,
				@supp_id			=-1,
				@stor2_id			= 1,
				@stock				= 1,
				@orders				= 1,
				@item_id			= -1,
				@activity			= 0


	drop table #tmpItemStorage
	drop table #tmpSaleOrderDetail
	drop table #tmpPurchaseOrderDetail

*/
------------------------------------------------------------
------------------------------------------------------------



	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf	WITH (NOLOCK)
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti	WITH (NOLOCK)
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------


	/*************************************************************/
	select	st.comp_id, st.item_id, sum(st.itst_cant) [itst_cant], st.stor_id
		into	#tmpItemStorage
		from	[tbItemStorage] st	WITH (NOLOCK)
		Inner JOIN tbStorage ts	WITH (NOLOCK)
			ON		ts.comp_id = st.comp_id
				AND ts.stor_id = st.stor_id

		where (	(	@stor_id			= -1 AND ts.stor_web4ALL = 'True')
				 or st.[stor_id]		=	@stor_id
			  )
		group by st.comp_id, st.item_id, st.stor_id
	/*************************************************************/




	/***********************************************************/
	select comp_id, item_id, sum(sod_qty) [sod_qty]
	into	#tmpSaleOrderDetail
	from
		(select  sod.comp_id, sod.item_id,
				case sd.sd_isCredit
					when 'true' then sod.sod_qty * -1
					else sod.sod_qty
				end	[sod_qty]

		from	tbSaleOrderDetail	sod	WITH (NOLOCK)

				inner join tbSaleOrderHeader 	soh	WITH (NOLOCK)
				on	soh.comp_id  = sod.comp_id
				and soh.[bra_id] = sod.[bra_id]
				and soh.[soh_id] = sod.[soh_id]

				inner join dbo.tbDocumentsFile	df	WITH (NOLOCK)
				on	df.comp_id  = soh.comp_id
				and df.[bra_id] = soh.[bra_id]
				and df.[df_id]	= soh.[df_id]

				inner join dbo.tbsysDocuments	sd	WITH (NOLOCK)
				on	sd.[sd_id]	= df.[sd_id]

		where   sod.comp_id = @comp_id
			and (@stor_id	= -1 or sod.[stor_id] =	@stor_id)
			AND sd.sd_id IN (1,2,3,4)
		) [tempquery]

	group by comp_id, item_id
	/***********************************************************/




	/*******************************************************************/
	select	pod.comp_id,
			pod.item_id,
			sum([pod_qty])										[pod_qty]
		into	#tmpPurchaseOrderDetail
		from	tbpurchaseorderdetail							pod	WITH (NOLOCK)
		INNER JOIN tbPurchaseOrderHeader						tpoh	WITH (NOLOCK)
			ON		tpoh.comp_id = pod.comp_id
				AND tpoh.poh_id = pod.poh_id
		where   pod.comp_id = @comp_id AND isnull(tpoh.poh_quotation,0) = 0 AND IsNull(pod.pod_isProcessed,0) = 0
		group by pod.comp_id, pod.item_id
	/*****************************************************************/


	DECLARE @fun_id INT
	SET @fun_id = 1



	declare @data  table(item_id int, getStock DECIMAL(18,2), getAStock decimal(18,2))

	insert into @data
	(		item_id,		getStock,		getAStock	)
	select	item_id,
			dbo.fnGetStock(@comp_id,  @stor_id, ti.item_id),
			dbo.fnGetAStock(@comp_id, @stor_id, ti.item_id, 999999999)
	FROM	tbItem ti	WITH (NOLOCK)
	where	ti.comp_id = @comp_id

	--select * from @data d




	SELECT	I.item_code,
			C.cat_desc,

			SC.subcat_desc,
			isnull(B.brand_desc,'')										[brand_desc],

			I.item_desc,
			isnull(tis.itst_cant,0)										[quantity],
			isnull(tsod.sod_qty,0)										[saleorder],
			dbo.fnGetAStock(@comp_id, @stor_id, i.item_id,999999999)	[potential],
			--isnull(tis.itst_cant,0) - isnull(tsod.sod_qty,0)			[potential],
			isnull(tpod.pod_qty,0)										[purchaseorder],
			isnull(ts3.stor_desc,'')									[stor_desc],
			ISNULL(tp.pres_desc,0)										[pres_desc],
			dbo.fnGetAStock(@comp_id, @stor2_id, i.item_id,999999999)	[potentialAd]
	--		SU.[supp_id]



	FROM	dbo.tbItem	I	WITH (NOLOCK)

			INNER JOIN @tblComplexFilter_Items		tempITEM
			ON tempitem.item_id				= I.item_id

			INNER JOIN tbPresentation tp	WITH (NOLOCK)
			ON tp.comp_id = I.comp_id
			--AND tp.bra_id = I.bra_id
			AND tp.pres_id = I.pres_id

			LEFT JOIN tbCategory			C	WITH (NOLOCK)
			ON	C.[comp_id]					= I.[comp_id]
			AND C.[cat_id]					= I.[cat_id]

			LEFT JOIN tbSubCategory			SC	WITH (NOLOCK)
			ON	SC.[comp_id]				= I.[comp_id]
			AND SC.[cat_id]					= I.[cat_id]
			AND SC.[subcat_id]				= I.[subcat_id]

			LEFT JOIN tbBrand				B	WITH (NOLOCK)
			ON	B.[comp_id]					= I.[comp_id]
			AND B.[brand_id]				= I.[brand_id]
			--and B.[bra_id]				= I.[bra_id]

			LEFT join tbSupplier			SU	WITH (NOLOCK)
			on  SU.[comp_id]				= I.[comp_id]
			AND SU.[supp_id]				= I.[supp_id]


			LEFT join #tmpItemStorage			tis
			on	tis.comp_id					= i.comp_id
			and tis.item_id					= i.item_id


			LEFT join #tmpSaleOrderDetail		tsod
			on	tsod.comp_id				= i.comp_id
			and tsod.item_id				= i.item_id


			LEFT join #tmpPurchaseOrderDetail	tpod
			on	tpod.comp_id				= i.comp_id
			and tpod.item_id				= i.item_id


----		LEFT JOIN	tbItemStorage			tis2
----		ON tis2.comp_id = i.comp_id
----		AND tis2.item_id = i.item_id


			LEFT JOIN tbStorage					ts3	WITH (NOLOCK)
			ON  ts3.comp_id = i.comp_id
			AND ts3.stor_id = tis.stor_id

			INNER JOIN vwItemEnabledInBalance vieib	WITH (NOLOCK)
				ON	vieib.comp_id = i.comp_id AND
					vieib.item_id = i.item_id


	WHERE	I.[comp_id]		=	@comp_id
	AND		(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
	AND		(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
	AND		(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
	AND		(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
	AND		(@supp_id		= -1 or I.[Supp_id]		=	@supp_id)
	AND		(@stor_id		= -1 or tis.[stor_id]	=	@stor_id)
	and		(@item_id		= -1 or I.item_id		=	@item_id)
	AND ISNULL(i.item_not4Sale,'False')			= 'False'
	--AND ISNULL(i.item_disabledInBalance,'False')= 'False'
	AND ISNULL(i.item_disabled,'False')			= 'False'
	and		(
				(@stock = -1)														or
				(@stock = 2 and i.item_id  in (	select da.item_id
													from @data da
													where da.getStock > 0))				or
				(@stock = 1 and i.item_id  in (	select da.item_id
													from @data da
													where da.getAStock > 0))
			)

	and		(
				(@orders = -1)																				or
				(@orders = 1 and i.item_id in		(	select tsod2.item_id
				                             				from tbSaleOrderDetail tsod2	WITH (NOLOCK)
															where tsod2.comp_id = @comp_id AND (@stor_id = -1 OR @stor_id = tsod2.stor_id)))					or
				(@orders = 2 and i.item_id not in	(	select tsod3.item_id
				                                 	 		from tbSaleOrderDetail tsod3	WITH (NOLOCK)
															where tsod3.comp_id = @comp_id AND (@stor_id = -1 OR @stor_id = tsod3.stor_id)))
			)

	AND		(@activity		= -1 or I.item_disabled		=	@activity)



	order by C.cat_desc, SC.subcat_desc, brand_desc, item_desc

	declare	@item_desc	VARCHAR(300)
	if (@item_id <> -1)
		select @item_desc = ti.item_desc
		  from tbItem ti where ti.comp_id = @comp_id and ti.item_id = @item_id



	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 43
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

			CASE @item_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(@item_desc)
			END
			[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 392
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			CASE @supp_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	ts.supp_name
					FROM	dbo.tbSupplier ts
					WHERE	ts.comp_id = @comp_id
					AND     ts.supp_id = @supp_id
					)
			END
			[params4],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 36
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

			CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(Select tc.cat_desc
					 FROM	tbCategory tc
					 WHERE	tc.comp_id = @comp_id
					 AND		tc.cat_id = @cat_id)
			END		[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

			CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
						(Select tsc.subcat_desc
						FROM	tbSubCategory tsc
						WHERE	tsc.comp_id = @comp_id
						AND		tsc.subcat_id = @subcat_id)

			END		[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 73
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

			CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select tb2.brand_desc
						FROM	tbBrand tb2
						WHERE	tb2.comp_id = @comp_id
						AND		tb2.brand_id= @brand_id)

			END		[params10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 371
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],

			CASE @pres_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE		(Select tp.pres_desc
						FROM	tbPresentation tp
						WHERE	tp.comp_id = @comp_id
						AND		tp.pres_id = @pres_id)

			END		[params12],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 111
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],

			CASE @stor_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(SELECT		ts.stor_desc
						FROM	tbStorage ts
						WHERE	ts.comp_id = @comp_id
						AND		ts.stor_id	   = @stor_id)
			END		[params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 1694
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],

			CASE @stor2_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(SELECT		ts.stor_desc
						FROM	tbStorage ts
						WHERE	ts.comp_id = @comp_id
						AND		ts.stor_id	   = @stor2_id)
			END		[params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 1505
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params17],

			CASE @stock WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 143
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @stock)
			END
			[params18],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 2022
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params19],

				CASE @orders WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 144
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @orders)
			END
			[params20],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 529
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params21],

				CASE @activity WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 320
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @activity)
			END
			[params22]








END
GO






CREATE procedure [dbo].[spItem_getReportPotentialStockOfStorageGroup]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

--		@option				int,
--		@item_desc			varchar(200),
		@item_id			int,
		@supp_id			int,

		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@pres_id			int,
		@stor_id			INT,
		@stor2_id			int,
		@bra_id				INT,
		@stock				int,
		@orders				int,
		@activity			INT,
		@guid				VARCHAR(50),--CF DE ITEMS
		@intBranch4Lang		int


)
as



BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	------------------------------------------------------------
	------------------------------------------------------------
	/*
		DECLARE 	@comp_id			int,
					@lang_id			int,
					@page_id			int,

					@item_id			int,
					@supp_id			int,

					@cat_id				int,
					@subcat_id			int,
					@brand_id			int,
					@pres_id			int,
					@stor_id			INT,
					@stor2_id			int,
					@bra_id				INT,
					@stock				int,
					@orders				int,
					@activity			INT,
					@intBranch4Lang		int



		SELECT		@comp_id			=1,
					@lang_id			=2,
					@page_id			=10023,
					@stor_id			= 4,

					@cat_id				=-1,
					@subcat_id			=-1,
					@pres_id			= -1,
					@brand_id			=-1,
					@bra_id				= 1,
					@supp_id			=-1,
					@stor2_id			= -1,
					@stock				= 1,
					@orders				= 1,
					@item_id			= -1,
					@activity			= -1


		drop table #tmpItemStorage
		drop table #tmpSaleOrderDetail
		drop table #tmpPurchaseOrderDetail
	*/
	------------------------------------------------------------
	------------------------------------------------------------

	--	/*************************************************************/
	--	select	st.comp_id,
	--			st.item_id,
	--			sum(st.itst_cant) [itst_cant],
	--			st.stor_id
	--
	--		into	#tmpItemStorage
	--		from	[tbItemStorage] st			WITH (NOLOCK)
	--		LEFT JOIN tbItem ti					WITH (NOLOCK)
	--			ON	ti.comp_id = st.comp_id AND
	--				ti.item_id = st.item_id
	--		LEFT JOIN tbStorage ts				WITH (NOLOCK)
	--			ON		ts.comp_id = st.comp_id	AND
	--					ts.stor_id = st.stor_id
	--
	--		where ( ts.comp_id		= @comp_id and
	--				ts.[stor_id]	= @stor_id  )
	--
	--		group by st.comp_id, st.item_id, st.stor_id
	--	/*************************************************************/

	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------



		if @stor_id	= @stor2_id	SET @stor2_id = -1



		/***********************************************************/
		select  comp_id,
				item_id,
				sum(sod_qty) [sod_qty]

		into	#tmpSaleOrderDetail
		from
			(select  sod.comp_id, sod.item_id,
					case sd.sd_isCredit
						when 'true' then sod.sod_qty * -1
						else sod.sod_qty
					end	[sod_qty]

			from	tbSaleOrderDetail	sod					WITH (NOLOCK)

					inner join tbSaleOrderHeader 	soh		WITH (NOLOCK)
					on	soh.comp_id  = sod.comp_id
					and soh.[bra_id] = sod.[bra_id]
					and soh.[soh_id] = sod.[soh_id]

					inner join dbo.tbDocumentsFile	df		WITH (NOLOCK)
					on	df.comp_id  = soh.comp_id
					and df.[bra_id] = soh.[bra_id]
					and df.[df_id]	= soh.[df_id]

					inner join dbo.tbsysDocuments	sd		WITH (NOLOCK)
					on	sd.[sd_id]	= df.[sd_id]

			where   sod.comp_id = @comp_id
				and sod.[stor_id] =	@stor_id
				AND sd.sd_id IN (1,2,3,4)
			) [tempquery]

		group by comp_id, item_id
		/***********************************************************/




		/*******************************************************************/
		select	pod.comp_id,
				pod.item_id,
				sum([pod_qty])										[pod_qty]
			into	#tmpPurchaseOrderDetail
			from	tbpurchaseorderdetail							pod			WITH (NOLOCK)
			INNER JOIN tbPurchaseOrderHeader						tpoh		WITH (NOLOCK)
				ON		tpoh.comp_id = pod.comp_id
					AND tpoh.poh_id = pod.poh_id
			where   pod.comp_id = @comp_id AND isnull(tpoh.poh_quotation,0) = 0 AND IsNull(pod.pod_isProcessed,0) = 0
			group by pod.comp_id, pod.item_id
		/*****************************************************************/


		DECLARE @fun_id INT
		SET @fun_id = 1



		declare @data  table(item_id INT PRIMARY KEY, getStock DECIMAL(18,2), getAStock decimal(18,2))

		insert into @data
		(		item_id,		getStock,		getAStock	)
		select	item_id,
				dbo.fnGetStock(@comp_id, @stor_id, ti.item_id),
				dbo.fnGetAStock(@comp_id, @stor_id, ti.item_id, 999999999)
		FROM	tbItem ti
		where	ti.comp_id = @comp_id

		--select * from @data d




		SELECT	I.item_code														[item_code],
				C.cat_desc														[cat_desc],
				SC.subcat_desc													[subcat_desc],
				isnull(B.brand_desc,'')											[brand_desc],
				I.item_desc														[item_desc],
				dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id, i.item_id)		[quantity],
				dbo.fnGetStockOfStorageGroup(@comp_id, @stor2_id, i.item_id)	[saleorder], --unidades2 fisico se le deja nombre de columna saleorder para no modificar dataset
				dbo.fnGetAStock(@comp_id, @stor_id, i.item_id,999999999)		[potential],
				isnull(tpod.pod_qty,0)											[purchaseorder],
				isnull(ts3.stor_desc,'')										[stor_desc],
				ISNULL(tp.pres_desc,0)											[pres_desc],
				dbo.fnGetAStock(@comp_id, @stor2_id, i.item_id,999999999)		[potentialAd]
		--		SU.[supp_id]



		FROM	dbo.tbItem						I

				INNER JOIN @tblComplexFilter_Items		tempITEM
				ON tempitem.item_id				= I.item_id

				INNER JOIN tbPresentation		tp
				ON tp.comp_id = I.comp_id
				--AND tp.bra_id = I.bra_id
				AND tp.pres_id = I.pres_id

				LEFT JOIN tbCategory			C
				ON	C.[comp_id]					= I.[comp_id]
				AND C.[cat_id]					= I.[cat_id]

				LEFT JOIN tbSubCategory			SC
				ON	SC.[comp_id]				= I.[comp_id]
				AND SC.[cat_id]					= I.[cat_id]
				AND SC.[subcat_id]				= I.[subcat_id]

				LEFT JOIN tbBrand				B
				ON	B.[comp_id]					= I.[comp_id]
				AND B.[brand_id]				= I.[brand_id]
				--and B.[bra_id]				= I.[bra_id]

				LEFT join tbSupplier			SU
				on  SU.[comp_id]				= I.[comp_id]
				AND SU.[supp_id]				= I.[supp_id]





				LEFT join #tmpSaleOrderDetail		tsod
				on	tsod.comp_id				= i.comp_id
				and tsod.item_id				= i.item_id


				LEFT join #tmpPurchaseOrderDetail	tpod
				on	tpod.comp_id				= i.comp_id
				and tpod.item_id				= i.item_id


	----		LEFT JOIN	tbItemStorage			tis2
	----		ON tis2.comp_id = i.comp_id
	----		AND tis2.item_id = i.item_id


				LEFT JOIN tbStorage					ts3
				ON  ts3.comp_id = i.comp_id
				AND ts3.stor_id = @stor_id   --tis.stor_id

				INNER JOIN vwItemEnabledInBalance vieib
						ON	vieib.comp_id = i.comp_id AND
							vieib.item_id = i.item_id




		WHERE	I.[comp_id]		=	@comp_id
		AND		(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
		AND		(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
		AND		(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
		AND		(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
		AND		(@supp_id		= -1 or I.[Supp_id]		=	@supp_id)
		--AND		tis.[stor_id]	=	@stor_id
		and		(@item_id		= -1 or I.item_id		=	@item_id)
		AND		(@activity		= -1 or I.item_disabled	=	@activity)
		AND		ISNULL(i.item_not4Sale,'False')			= 'False'
		--AND		ISNULL(i.item_disabledInBalance,'False')= 'False'
		AND		ISNULL(i.item_disabled,'False')			= 'False'
		and		(
					(@stock = -1)														or
					(@stock = 2 and i.item_id  in (	select da.item_id
														from @data da
														where da.getStock > 0))				or
					(@stock = 1 and i.item_id  in (	select da.item_id
														from @data da
														where da.getAStock > 0))
				)

		and		(
					(@orders = -1)																				or
					(@orders = 1 and i.item_id in		(	select tsod2.item_id
				                             					from tbSaleOrderDetail tsod2
																where tsod2.comp_id = @comp_id AND @stor_id = tsod2.stor_id))					or
					(@orders = 2 and i.item_id not in	(	select tsod3.item_id
				                                 	 			from tbSaleOrderDetail tsod3
																where tsod3.comp_id = @comp_id AND @stor_id = tsod3.stor_id))
				)



		order by C.cat_desc, SC.subcat_desc, brand_desc, item_desc

		declare	@item_desc	VARCHAR(300)
		if (@item_id <> -1)
			select @item_desc = ti.item_desc
			  from tbItem ti where ti.comp_id = @comp_id and ti.item_id = @item_id



		exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


		/* devolución de parámetros recibidos */
		DECLARE @related_page_id INT
		SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
		/*************************************************************************************************************/
		/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
		/*
				SELECT	t.ctrl_id,	t.[text_desc]
				FROM	[tbsysTexts]				t
						inner join [tbsysControls]	c
						on c.[ctrl_id] = t.[ctrl_id]
				where	t.[lang_id]	= @lang_id
				and		t.[page_id]	= @related_page_id
				and		t.[type_id]	= 1
		*/
		/*************************************************************************************************************/
		SELECT
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 43
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

				CASE @item_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(@item_desc)
				END
				[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 392
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

				CASE @supp_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT	ts.supp_name
						FROM	dbo.tbSupplier ts
						WHERE	ts.comp_id = @comp_id
						AND     ts.supp_id = @supp_id
						)
				END
				[params4],

						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 36
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

				CASE @cat_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(Select tc.cat_desc
						 FROM	tbCategory tc
						 WHERE	tc.comp_id = @comp_id
						 AND		tc.cat_id = @cat_id)
				END		[params6],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 38
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

				CASE @subcat_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
							(Select tsc.subcat_desc
							FROM	tbSubCategory tsc
							WHERE	tsc.comp_id = @comp_id
							AND		tsc.subcat_id = @subcat_id)

				END		[params8],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 73
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

				CASE @brand_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE	(Select tb2.brand_desc
							FROM	tbBrand tb2
							WHERE	tb2.comp_id = @comp_id
							AND		tb2.brand_id= @brand_id)

				END		[params10],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 371
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],

				CASE @pres_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE		(Select tp.pres_desc
							FROM	tbPresentation tp
							WHERE	tp.comp_id = @comp_id
							AND		tp.pres_id = @pres_id)

				END		[params12],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 111
      			 --AND t.[lang_id] = @lang_id
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],

				CASE @stor_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE	(SELECT		ts.stor_desc
							FROM	tbStorage ts
							WHERE	ts.comp_id = @comp_id
							AND		ts.stor_id	   = @stor_id)
				END		[params14],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      					 WHERE t.ctrl_id = 1694
      					 --AND t.[lang_id] = @lang_id
      					 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],

				CASE @stor2_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
					ELSE	(SELECT		ts.stor_desc
							FROM	tbStorage ts
							WHERE	ts.comp_id = @comp_id
							AND		ts.stor_id	   = @stor2_id)
				END		[params16],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      					 WHERE t.ctrl_id = 1505
      					 --AND t.[lang_id] = @lang_id
      					 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params17],

				CASE @stock WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tov.optval_desc
						FROM	dbo.tbsysOptionsValues tov
						WHERE	tov.optval_class	= 143
						AND		tov.lang_id			= @lang_id
						AND		tov.optval_id		= @stock)
				END
				[params18],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      					 WHERE t.ctrl_id = 2022
      					 --AND t.[lang_id] = @lang_id
      					 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params19],

					CASE @orders WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tov.optval_desc
						FROM	dbo.tbsysOptionsValues tov
						WHERE	tov.optval_class	= 144
						AND		tov.lang_id			= @lang_id
						AND		tov.optval_id		= @orders)
				END
				[params20],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      					 WHERE t.ctrl_id = 529
      					 --AND t.[lang_id] = @lang_id
      					 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params21],

					CASE @activity WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tov.optval_desc
						FROM	dbo.tbsysOptionsValues tov
						WHERE	tov.optval_class	= 320
						AND		tov.lang_id			= @lang_id
						AND		tov.optval_id		= @activity)
				END
				[params22]







END
GO







CREATE procedure [dbo].[spItem_getReportUpToDateItemsStock]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,
	@item_id			INT,
	@pres_id			int,
	@cat_id				int,
	@subcat_id			int,
	@brand_id			int,
	@stor_id			int,
	@bra_id				int,
	--@supp_id			int,
	@date_to			DATETIME,
	@user_id            INT,
	@prli_id			int,
	@coli_id			int,
	@curr_id			INT,
	@bitIsByProcessingDate INT,
	@guid				VARCHAR(50),--CF DE ITEMS
	@intBranch4Lang		int
)
AS


BEGIN



	SET NOCOUNT ON
	SET dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



-- -------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------
/*
	  DECLARE	@comp_id			int,
				@lang_id			int,
				@page_id			int,
				--@option				int,
				@item_id			INT,
				@pres_id			int,
				@cat_id				int,
				@subcat_id			int,
				@brand_id			int,
				@stor_id			int,
				@bra_id				INT,
				--@supp_id			INT,
				@date_to			DATETIME,
				@user_id            INT,
				@prli_id			int,
				@coli_id			int,
				@curr_id			int,
				@bitIsByProcessingDate BIT,
				@intBranch4Lang		int

	  SELECT	@comp_id			=1,
				@lang_id			=2,
				@page_id			=10025,

				--@option				=-1,
				@item_id			=301,
				@pres_id			=-1,
				@cat_id				=-1,
				@subcat_id			=-1,
				@brand_id			=-1,
				@stor_id			= 1,
				@bra_id				=-1,
				--@supp_id			=-1,
				@date_to			='2015-05-02',
				@user_id            = 1,
				@prli_id			= 1,
				@coli_id			= 1,
				@curr_id			= 1,
				@bitIsByProcessingDate = 1,
				@intBranch4Lang		= 1
*/
-- -------------------------------------------------------------------

	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	DECLARE	@curr_desc	VARCHAR(20)
	SELECT	@curr_desc	= tc.curr_desc FROM tbsysCurrency tc WHERE tc.curr_id = @curr_id

	SET 	@date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to,'True');


	WITH Stock_CTE  (item_code,item_desc,cat_desc,subcat_desc,brand_desc,stor_desc,itst_cant,prli_priceTMP,prli_curr_desc,coslis_priceTMP,coslis_curr_desc)
	AS
	(
		SELECT	I.item_code,
				I.item_desc,
				C.cat_desc,
				SC.subcat_desc,
				B.brand_desc,
				ts.stor_desc,
				convert(decimal(18,2),
									IsNull(IST.itst_cant,0) + Sum(IsNull(
																			case
																				when (
																					CASE
																						WHEN @bitIsByProcessingDate = 2 THEN IsNull(ct.ct_cd,ct.ct_date)					-- Por fecha de Carga ( Idem Consulta de Movimientos )
																						WHEN @bitIsByProcessingDate = 1 THEN IsNull(ct.ct_processingDate,ct.ct_date)		-- Por fecha de Procesamiento
																						ELSE IsNull(ct.ct_taxDate, ct.ct_date)												-- Por fecha de Imputacion.-
																					END
																							>	@date_to ) then IT.it_qty
																				else 0
																			end
																		 ,0) * IsNull(vitfsmc.vwToBack,0))
					   )																						as		itst_cant,

				isnull(convert(decimal(18,2),

						dbo.fnGetExchange2(@comp_id,pl.prli_price,pl.curr_id,@curr_id,pl.curr_id,@curr_id,0,'false')),0)		[prli_priceTMP],

				@curr_desc																										[prli_curr_desc],

				isnull(convert(decimal(18,2),

						dbo.fnGetExchange2(@comp_id,cl.coslis_price,cl.curr_id,@curr_id,cl.curr_id,@curr_id,0,'false')),0)		[coslis_priceTMP],

				@curr_desc																										[coslis_curr_desc]


			FROM	[tbItemStorage]										IST


				inner JOIN tbItem									I
  				ON		I.[comp_id]		=	IST.[comp_id]
  					AND	I.item_id		=	IST.item_id

				INNER JOIN @tblComplexFilter_Items		tempITEM
				ON tempitem.item_id				= I.item_id

				INNER JOIN tbStorage									ts
  				ON	ts.comp_id			=	IST.comp_id
  				AND ts.stor_id			=	IST.stor_id


  				INNER JOIN tbCategory								C
  				ON	C.[comp_id]			=	I.[comp_id]
  				AND C.[cat_id]			=	I.[cat_id]

  				INNER JOIN tbSubCategory								SC
  				ON	SC.[comp_id]		=	I.[comp_id]
  				AND SC.[subcat_id]		=	I.[subcat_id]

  				INNER JOIN tbBrand									B
  				ON	B.[comp_id]			=	I.[comp_id]
  				AND B.[brand_id]		=	I.[brand_id]



  				LEFT join tbItemTransactions						IT
  				on  IT.[comp_id]		=	IsT.[comp_id]
  				and IT.[stor_id]		=	IsT.[stor_id]
  				and IT.[item_id]		=   IsT.[item_id]

  				left join tbCommercialTransactions					CT
  				On  CT.[comp_id]		=	IT.[comp_id]
  				And CT.[bra_id]			=	IT.[bra_id]
  				AND	CT.ct_transaction	=	IT.ct_transaction


	-- No Usar PLS:
	--			left JOIN tbUsers4BranchFilter						vubf
	--  			ON	--ct.comp_id IS NULL OR
	--  				(		vubf.comp_id		=	ct.comp_id
	--  				 AND	vubf.bra_id			=	ct.bra_id
	--  				 AND	vubf.[user_id]		=	@user_id)


				left join dbo.tbPriceListItems						PL
				on 	i.[comp_id]			=	PL.[comp_id]
				and i.ITEM_id			=   PL.[item_id]
				and PL.[prli_id]		=   @prli_id

				left join dbo.tbItemCostList						CL
				on 	i.comp_id			=	CL.comp_id
				and i.item_id			=   CL.item_id
				and CL.coslis_id		=	@coli_id

				LEFT join dbo.tbsysCurrency							CU
				on	PL.[curr_id]		=	CU.[curr_id]

				LEFT join dbo.tbsysCurrency							CU1
				on	CL.[curr_id]		=	CU1.[curr_id]

  				left JOIN vwItemTransactions_forStockMovementsCalculations		vitfsmc
  				ON		vitfsmc.comp_id			= it.comp_id
  					AND vitfsmc.bra_id			= it.bra_id
  					AND	vitfsmc.ct_transaction	= it.ct_transaction
  					AND	vitfsmc.it_transaction	= it.it_transaction

				INNER JOIN vwItemEnabledInBalance vieib
						ON	vieib.comp_id = i.comp_id AND
							vieib.item_id = i.item_id



		WHERE	IST.[comp_id]	= @comp_id AND
				IST.stor_id		= @stor_id
				AND	(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
				AND	(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
				AND	(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
				AND	(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
				AND	(@bra_id		= -1 or I.[bra_id]		=	@bra_id)
				AND	(@item_id		= -1 or Ist.item_id		=	@item_id)
				AND ISNULL(i.item_not4Sale,'False')			= 'False'
				--AND ISNULL(i.item_disabledInBalance,'False')= 'False'
				AND ISNULL(i.item_disabled,'False')			= 'False'

		GROUP BY	I.item_code,
					I.item_desc,
					C.cat_desc,
					SC.subcat_desc,
					B.brand_desc,
					ts.stor_desc,
					IST.itst_cant,
					cu.curr_symbol,
					pl.[prli_price],cl.curr_id,cl.[coslis_price],CU1.curr_symbol,pl.curr_id


	)

	SELECT	-- poner el resto.!!!
			item_code,
			item_desc,
			cat_desc,
			subcat_desc,
			brand_desc,
			stor_desc,
			itst_cant,
			stk.prli_priceTMP * stk.itst_cant AS prli_price,
			prli_curr_desc,
			stk.coslis_priceTMP * stk.itst_cant AS coslis_price,
			coslis_curr_desc

		FROM Stock_CTE stk
		WHERE itst_cant <> 0
		ORDER BY	stk.cat_desc,
					stk.subcat_desc,
					stk.brand_desc,
					stk.item_code







	  exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id
	  /* devolución de parámetros recibidos */
	  DECLARE @related_page_id INT
	  SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	  /*************************************************************************************************************/
	 /* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	 /*
 			SELECT	t.ctrl_id,	t.[text_desc]
  			FROM	[tbsysTexts]				t
  					inner join [tbsysControls]	c
  					on c.[ctrl_id] = t.[ctrl_id]
  			where	t.[lang_id]	= @lang_id
  			and		t.[page_id]	= @related_page_id
  			and		t.[type_id]	= 1
	  */
	  /*************************************************************************************************************/

	   SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 43
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

			CASE @item_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)

		     	Else
		     		(Select ti.item_desc From tbItem ti
		     		 Where ti.comp_id = @comp_id
		     		And ti.item_id = @item_id)
	     End [params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 36
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cat_desc
  						FROM	tbCategory tc
  						WHERE	tc.comp_id = @comp_id
  						AND		tc.cat_id= @cat_id)
  			END		[params4],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

			CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
  						FROM	tbSubCategory tsc
  						WHERE	tsc.comp_id = @comp_id AND tsc.subcat_id= @subcat_id)
  			END		[params6],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 73
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

			CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.brand_desc
  						FROM	tbBrand tb
  						WHERE	tb.comp_id = @comp_id AND tb.brand_id= @brand_id)
  			END		[params8],

  				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 371
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

			CASE @pres_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tp.pres_desc
  						FROM	tbPresentation tp
  						WHERE	tp.comp_id = @comp_id AND tp.pres_id= @pres_id)
  			END		[params10],

  				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 28
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],

			CASE @bra_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb2.bra_desc
  						FROM	tbBranch tb2
  						WHERE	tb2.comp_id = @comp_id AND tb2.bra_id= @bra_id)
  			END		[params12],

  		  				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 111
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],

			CASE @stor_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.stor_desc
  						FROM	tbStorage ts
  						WHERE	 ts.stor_id= @stor_id)
  			END		[params14],

	--  		 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
	--      	 WHERE t.ctrl_id = 384
	--      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],
	--
	--		CASE @stor_id WHEN -1 THEN
	--				(SELECT		tut.utexts_desc
	--					FROM	tbsysUniqueTexts tut
	--					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
	--			ELSE
	--				(SELECT		ts.stor_desc
	--  					FROM	tbStorage ts
	--  					WHERE	 ts.stor_id= @stor_id)
	--  		END		[params16],


  			(SELECT t.[text_desc] FROM [tbsysTexts]	t
        		WHERE t.ctrl_id = 384 AND t.[lang_id] = @lang_id and t.[page_id] = @related_page_id and t.[type_id]	= 1)	[params15],
        		@date_to [DateParams1],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 390
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params16],

				CASE @prli_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tpl.prli_desc
							FROM	tbPriceList tpl
							WHERE	tpl.comp_id = @comp_id And tpl.prli_id=@prli_id)
				END		[params17],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 391
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params18],

				CASE @coli_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
							(SELECT		ticln.coslis_desc
							FROM	tbItemCostListName ticln
							WHERE	ticln.comp_id = @comp_id And ticln.coslis_id=@coli_id)
				END		[params19],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 106
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params20],

				CASE @curr_id WHEN -1 THEN
						(SELECT		tut.utexts_desc
							FROM	tbsysUniqueTexts tut
							WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
					ELSE
						(SELECT		tc.curr_desc
							FROM	tbsysCurrency tc
							WHERE	Tc.curr_id= @curr_id)
				END		[params21],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 2097
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params22],


				(SELECT		tov.optval_desc
							FROM tbsysOptionsValues tov
							WHERE	tov.lang_id=@lang_id AND tov.optval_class=305 and tov.optval_id = @bitIsByProcessingDate) [params23]


  			--convert(varchar,day(@date_to)) + '/' + convert(varchar,month(@date_to)) + '/' + convert(varchar,year(@date_to))[params16]


END
GO




CREATE procedure [dbo].[spItem_getReportVal]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@stor_id			int,
		@curr_id			int,

		@prli_id			int,
		@coli_id			int,

		@cat_id				int,
		@subcat_id			int,

		@brand_id			int,
		@pres_id			int,

		@item_id			INT,
		@supp_id			INT,
		@onlyStock_id		INT,
		@guid				VARCHAR(50), --CF DE ITEMS

		@bra_id				INT,
		@intBranch4Lang		int
)

AS



BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-09-11
	-- Parte		: 545
	-- Description	: Se eliminó el doble join con tbitemstorage
	-- =================================================================================================================


	-- ---------------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------------
	/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			int,

			@stor_id			int,
			@curr_id			int,

			@prli_id			int,
			@coli_id			int,

			@cat_id				int,
			@subcat_id			int,

			@brand_id			int,
			@pres_id			int,

			@item_id			int,
			@supp_id			int,
			@onlyStock_id		INT,
			@guid				VARCHAR(50), --CF DE ITEMS

			@bra_id				INT,
			@intBranch4Lang		int


	SELECT	@comp_id			=1,
			@lang_id			=2,
			@page_id			=10008,

			@cat_id				= -1,
			@subcat_id			= -1,
			@prli_id			= 8,
			@coli_id			= 10,
			@curr_id			= 1,
			@item_id			= -1,
			@stor_id			= -1,
			@pres_id			= -1,
			@supp_id			= -1,
			@brand_id			= -1,
			@onlyStock_id		=  1,

			@bra_id				= 1,
			@guid				= NEWID(),
			@intBranch4Lang		= 1

			*/
	-- ---------------------------------------------------------------------------




	DECLARE @fun_id INT
	SET @fun_id = 1



	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------



	DECLARE			@tmpStorage TABLE(stor_id INT  PRIMARY KEY)
	INSERT INTO		@tmpStorage(stor_id)
		SELECT ts.stor_id
		FROM tbStorage ts		WITH (NOLOCK)
		WHERE ts.comp_id = @comp_id AND
			    (
					(ts.stor_web4ALL	= 'true' and @stor_id = -1) 	or
					 ts.stor_id			= @stor_id
				)



	;WITH A (item_id,cat_desc,subcat_desc,item_code,item_desc,itst_cantm,prli_price,curr_desc,curr_id,coslis_price,coslis_price_aw,coslis_curr_desc,coslis_curr_id,item_withDecimal)
		AS
			(
				SELECT

						I.item_id,
						C.cat_desc,
						SC.subcat_desc,
						I.item_code,
						I.item_desc,
						dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id, I.item_id)		[itst_cantm],
						isnull(PL.prli_price,0)											[prli_price],
						isnull(CU.curr_symbol,'')										[curr_desc],
						PL.curr_id,

						isnull(CL.coslis_price,0)			[coslis_price],
						isnull(CL.coslis_price_aw,0)		[coslis_price_aw],
						isnull(CU1.curr_symbol,'')			[coslis_curr_desc],
						CL.curr_id							[coslis_curr_id],
						isnull(i.item_withDecimal,'false')  [item_withDecimal]

						FROM	dbo.tbItem						I										WITH (NOLOCK)

							INNER JOIN vwItemEnabledInBalance vieib									WITH (NOLOCK)
									ON	vieib.comp_id = i.comp_id AND
										vieib.item_id = i.item_id

							INNER JOIN @tblComplexFilter_Items		tempITEM
								ON tempitem.item_id				= I.item_id

							INNER join tbCategory			C										WITH (NOLOCK)
								on	I.[comp_id]					=	C.[comp_id]
								and I.[cat_id]					=	C.[cat_id]

							INNER join tbSubCategory			SC									WITH (NOLOCK)
								on	I.[comp_id]					=	SC.[comp_id]
								and I.[cat_id]					=	SC.[cat_id]
								and I.[subcat_id]				=	SC.[subcat_id]


							left join dbo.tbPriceListItems  PL										WITH (NOLOCK)
								on 	pl.comp_id					= @comp_id		AND
									pl.prli_id					= @prli_id		AND
									pl.ITEM_id					= I.item_id
							--and (@prli_id = -1 or PL.[prli_id] = @prli_id)

							left join dbo.tbsysCurrency		CU										WITH (NOLOCK)
								on PL.[curr_id]				=	CU.[curr_id]

							left join dbo.tbItemCostList    CL										WITH (NOLOCK)
								on 	CL.comp_id					=	@comp_id	AND
									cl.coslis_id				=   @coli_id	AND
									CL.item_id					=   I.item_id
							--and (@coli_id = -1 or CL.coslis_id = @coli_id)

							left join dbo.tbsysCurrency		CU1										WITH (NOLOCK)
								on CL.[curr_id]				=	CU1.[curr_id]

					WHERE		I.comp_id	= @comp_id
					and			(@item_id	= -1 or I.item_id   = @item_id)
					and			(@cat_id	= -1 or I.cat_id    = @cat_id)
					and			(@subcat_id = -1 or I.subcat_id	= @subcat_id)
					and			(@pres_id	= -1 or I.pres_id	= @pres_id)
					and			(@supp_id   = -1 or I.supp_id	= @supp_id)		AND
					CASE
						WHEN @onlyStock_id = -1													THEN 1
						WHEN dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id, I.item_id) > 0	THEN 1
						ELSE 0
					END	 = 1
					--AND			(@onlyStock_id = -1 OR (@onlyStock_id <> -1 and	dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id, I.item_id) > 0))
					and			(@brand_id  = -1 or I.brand_id	= @brand_id)
					AND			ISNULL(i.item_not4Sale,'False')				= 'False'
					AND			ISNULL(i.item_disabled,'False')				= 'False'

			)


	SELECT

			a.cat_desc,
			a.subcat_desc,
			a.item_code,
			a.item_desc,
			a.itst_cantm,
			a.prli_price,
			a.curr_desc,
			isnull(convert(decimal(18,2),a.itst_cantm * dbo.fnGetExchange2(@comp_id, a.prli_price ,  a.curr_id,        @curr_id, a.curr_id, @curr_id,0, 'false')),0) [stock_val_price],
			a.coslis_price,
			a.coslis_curr_desc,
			isnull(convert(decimal(18,2),a.itst_cantm * dbo.fnGetExchange2(@comp_id, a.coslis_price, a.coslis_curr_id, @curr_id, a.coslis_curr_id, @curr_id,0, 'false')),0) [stock_val_cost],
			isnull(convert(decimal(18,2),a.itst_cantm * dbo.fnGetExchange2(@comp_id, a.coslis_price_aw, a.coslis_curr_id, @curr_id, a.coslis_curr_id, @curr_id,0, 'false')),0) [stock_val_cost_aw],
			ISNULL(ttn.tax_percentage,0)						[Item_Tax],
			a.coslis_price_aw,
			a.item_withDecimal

		FROM A	-- cte
		LEFT JOIN vwItemTaxesOnlyOneIvaTax vitooit			WITH (NOLOCK)
			ON	vitooit.comp_id = @comp_id AND
				vitooit.item_id = a.item_id
		LEFT JOIN tbTaxName ttn								WITH (NOLOCK)
			ON	ttn.comp_id = vitooit.comp_id AND
				ttn.tax_id	= vitooit.tax_id

		order by a.cat_desc, a.subcat_desc, a.item_desc

	--
	--
	--
	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/************************************************************************************************************ */

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 111
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

			CASE @stor_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.stor_desc
						FROM	tbStorage ts
						WHERE	Ts.comp_id= @comp_id AND ts.stor_id = @stor_id)
			END		[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 106
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			CASE @curr_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.curr_desc
						FROM	tbsysCurrency tc
						WHERE	Tc.curr_id= @curr_id)
			END		[params4],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 390
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

			CASE @prli_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tpl.prli_desc
						FROM	tbPriceList tpl
						WHERE	tpl.comp_id = @comp_id And tpl.prli_id=@prli_id)
			END		[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 391
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

			CASE @coli_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
						(SELECT		ticln.coslis_desc
						FROM	tbItemCostListName ticln
						WHERE	ticln.comp_id = @comp_id And ticln.coslis_id=@coli_id)
			END		[params8],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 36
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

			CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
						(SELECT		tc.cat_desc
						FROM	tbCategory tc
						WHERE	tc.comp_id = @comp_id And tc.cat_id=@cat_id)
			END		[params10],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],

			CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
						(SELECT		tsc.subcat_desc
						FROM	tbSubCategory tsc
						WHERE	tsc.comp_id = @comp_id And tsc.subcat_id=@subcat_id)
			END		[params12],

						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 73
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],

			CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.brand_desc
						FROM	tbBrand tb
						WHERE	tb.comp_id = @comp_id And tb.brand_id=@brand_id)
			END		[params14],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 371
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],

			CASE @pres_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
						(SELECT		tp.pres_desc
						FROM	tbPresentation tp
						WHERE	tp.comp_id = @comp_id And tp.pres_id=@pres_id)
			END		[params16],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 103
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params17],

			CASE @item_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ti.item_desc
						FROM	tbItem ti
						WHERE	ti.comp_id = @comp_id And ti.item_id=@item_id)
			END		[params18],

							(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 392
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params19],

			CASE @supp_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.supp_name
						FROM	tbSupplier ts
						WHERE	ts.comp_id = @comp_id And ts.supp_id=@supp_id)
			END		[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1742
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params21],


			CASE @onlyStock_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
						FROM	tbsysOptionsValues tov
						WHERE	tov.lang_id = @lang_id AND tov.optval_class = 128)
			END		[params22]


END







GO



CREATE PROCEDURE [dbo].[spItem_GetSerialsAvailable_Grid]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@item_id	INT
)
AS



	BEGIN
		SET NOCOUNT ON

		-- ----------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@item_id	INT

			SELECT
				@comp_id	= 1,
				@lang_id	=2,
				@bra_id		= 1,
				@prof_id	= 1,
				@item_id	= 492

*/
		-- ----------------------------------------------



		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		SELECT TOP 350
			tis2.is_serial																			[is_serial],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)		[Comprobante],
			tct.ct_date																				[ct_date],
			ISNULL(ts.stor_desc,'')																	[stor_desc],
			tis2.is_id																				[ID]

			FROM tbItem												ti			WITH (NOLOCK)

			INNER JOIN tbItemSerials								tis2		WITH (NOLOCK)
			ON	tis2.comp_id		= ti.comp_id			AND
				tis2.item_id		= ti.item_id

			INNER JOIN tbCommercialTransactions						tct			WITH (NOLOCK)
			ON	tct.comp_id			= tis2.comp_id			AND
				tct.bra_id			= tis2.bra_id			AND
				tct.ct_transaction	= tis2.ct_transaction

			LEFT JOIN tbStorage										ts			WITH (NOLOCK)
			ON	ts.comp_id			= tis2.comp_id			AND
				ts.stor_id			= tis2.stor_id

			WHERE	ti.comp_id					= @comp_id			AND
					ti.item_id					= @item_id			AND
				   (ti.bra_id IS NULL OR ti.bra_id = @bra_id)		AND
					tis2.is_available			= 'True'			AND
					isnull(tis2.is_serial,'') <> ''

			ORDER BY tct.ct_transaction	, tis2.is_serial--, tis2.is_id

	END

GO



create PROCEDURE [dbo].[spItem_getStock4ItemReplacement]
(
	@comp_id	INT,
	@item_id	INT,
	@stor_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------
		-- TESTING
		-- ----------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT,
				@stor_id	INT
			SELECT
				@comp_id	= 1,
				@item_id	= 492,
				@stor_id	= 3
		*/
		-- ----------------------------

		SELECT
			dbo.fnGetStock(@comp_id,  @stor_id, ti.item_id)	[AStock] -- Stock fisico fnGetStock
			FROM tbItem													ti
			WHERE	ti.comp_id = @comp_id								AND
					ti.item_id = @item_id
	END
GO







CREATE PROCEDURE [dbo].[spItem_getStockById]
(
	@comp_id		int,
	@stor_id		int,
	@item_id		int,
	@priority		decimal(16,4)
)
AS

BEGIN

	-- Avisa si es cun COMBO asi no pide clave de stock.-
	DECLARE @bitIsCombo AS BIT
	SET @bitIsCombo = 'False'
	SELECT TOP 1 @bitIsCombo =	CASE
									WHEN tia.item_id_1 IS NULL THEN 'False'
									ELSE							'True'
								END
		FROM tbItemAssociation tia
	WHERE	tia.comp_id = @comp_id AND
			tia.item_id = @item_id


	set nocount on

	/*
	declare 	@comp_id		int,
				@stor_id		int,
				@item_id		INT,
				@priority		INT

	select 		@comp_id		=1,
				@stor_id		=1,
				@item_id		=352,
				@priority		=999999999

	*/

	select dbo.fnGetAStock			   (@comp_id, @stor_id, @item_id, @priority)	[Stock],
		   dbo.fnGetStockOfStorageGroup(@comp_id,@stor_id,@item_id) 				[PhisicalStock],
		   @bitIsCombo					 											[IsCombo]


END
GO



CREATE PROCEDURE [dbo].[spItem_getWebSiteImages]
(
	@comp_id				INT,
	@bolGetNullImages		BIT,
	@bolOnlyUpdatedImages	BIT,
	@item_id				AS INT
)
AS

BEGIN

	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 50
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE  @tblItem TABLE ( item_id INT PRIMARY KEY )

	INSERT INTO @tblItem (item_id)
		SELECT	distinct
			tsc.item_id				[Id]
			FROM tbItem tsc								WITH (NOLOCK)
			INNER JOIN tbWebSiteII_ItemsData twsiid		WITH (NOLOCK)
				ON	twsiid.comp_id = tsc.comp_id  AND
					twsiid.item_id = tsc.item_id
			WHERE	tsc.comp_id = @comp_id											AND
					CASE
						WHEN @item_id > 0 AND twsiid.item_id =  @item_id							THEN 1
						WHEN @item_id > 0 AND twsiid.item_id <> @item_id							THEN 0
						WHEN tsc.item_web_forceImageGeneration						  = 'True'		THEN 1
						WHEN @bolOnlyUpdatedImages = 'True' AND tsc.item_imageUpdated = 'True'		THEN 1
						WHEN @bolOnlyUpdatedImages = 'False'										THEN 1
						ELSE																			 0
					END	 = 1														AND
					( tsc.item_picture IS NOT NULL OR @bolGetNullImages = 'True' )


	-- Agrega las imagenes de los articulos que estan FORZADOS a crearlas.
	--IF @item_id <= 0
		BEGIN
			INSERT INTO @tblItem(item_id)
				SELECT ti.item_id
					FROM tbItem			ti	WITH (NOLOCK)
					LEFT JOIN @tblItem	tmp
						ON tmp.item_id = ti.item_id
				WHERE	ti.comp_id							= @comp_id	AND
						ti.item_web_forceImageGeneration	= 'True'	AND
						tmp.item_id IS NULL								AND
						(@item_id <= 0 OR ti.item_id = @item_id)
		END

	IF @item_id <= 0
		BEGIN
			UPDATE tbitem		WITH (ROWLOCK)
				SET item_imageUpdated = 0
				FROM tbitem ti
				INNER JOIN @tblItem tmp
					ON tmp.item_id = ti.item_id
				WHERE ti.item_imageUpdated = 1
		END


	SELECT
		tsc.item_code4web				[Id],
		CASE
			WHEN @item_id = -2 THEN NULL
			ELSE					tsc.item_picture
		END								[Image],
		tsc.item_id
		FROM tbItem tsc		WITH (NOLOCK)
		INNER JOIN @tblItem twsiid
			ON twsiid.item_id	= tsc.item_id
		WHERE	tsc.comp_id = @comp_id											--AND
				--( tsc.item_picture IS NOT NULL OR @bolGetNullImages = 'True' )	AND
				--((tsc.item_web		= 'True'									AND
				--  tsc.item_disabled	= 'False') OR @bolGetNullImages = 'True')





END
GO



