	@item_weight					DECIMAL(21,9),
	@bititem_weight					BIT,
	@mu_id							INT,
	@bitmu_id						BIT,
	@item_liquidationPlus			INT,
	@item_newness					INT,
	@item_isAvailable4FullJaus		INT,
	@item_outlet					INT,					-- tkt 10528 MT
	@item_PriceLabel_Desc9			NVARCHAR(50),
	@bititem_PriceLabel_Desc9		BIT,

	@item_WebSite_desc				NVARCHAR(4000),
	@bititem_WebSite_desc			BIT,
	@item_annotation1				NVARCHAR(4000),
	@bititem_annotation1			BIT,
	@item_descHTML					NVARCHAR(max),
	@bititem_descHTML				BIT



)

AS




---------------------------------------------------
---------------------------------------------------
/*

DECLARE
		@comp_id			INT,
		@bra_id				INT,
		@Item_Guid			UNIQUEIDENTIFIER,
		@brand_id			INT,
		@pres_id			INT,
		@cat_id				INT,
		@subcat_id			INT,
		@subcataux_id		INT,
		@bitsubcataux		BIT -- Solo actualiza si es true(es xq al poder grabar ninguno solo lo hara si se activo el control en la pagina)

SELECT
		@comp_id			=1,
		@bra_id				=1,
		@Item_Guid			='1242A2A1-D106-4865-A6AB-70C2567B5004',
		@brand_id			=2,
		@pres_id			=-1,
		@cat_id				=3,
		@subcat_id			=2,
		@subcataux_id		=2,
		@bitsubcataux		='False'

*/

---------------------------------------------------
---------------------------------------------------

BEGIN

SET NOCOUNT ON


		DECLARE @objGUID AS UNIQUEIDENTIFIER
		SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@Item_Guid)

		DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)

		INSERT INTO @tblComplexFilter_Items

			SELECT
				tcf.sl_id
				FROM tbComplexFilter tcf      WITH (NOLOCK)
				WHERE tcf.sl_guid	  = @objGUID      AND
					  tcf.sl_selected = 'True'

			--------------------------------------
			--ACTUALIZAMOS LA MARCA
			IF @brand_id <> -1
				BEGIN
					UPDATE tbitem
					SET brand_id		= @brand_id

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END

			--------------------------------------

			--------------------------------------
			--ACTUALIZAMOS LA PRESENTACION
			IF @pres_id <> -1
				BEGIN
					UPDATE tbitem
					SET pres_id			= @pres_id

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id
				END

			--------------------------------------

			--------------------------------------
			--ACTUALIZAMOS LA CATEGORIA Y SUBCATEGORIA
			IF @cat_id <> -1
				BEGIN
					UPDATE tbitem
					SET cat_id			= @cat_id,
						subcat_id		= @subcat_id

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END

			--------------------------------------


			--------------------------------------
			--ACTUALIZAMOS LA SUBCATEGORIA AUX
			IF @bitsubcataux = 'True'
				BEGIN

					if	(@subcataux_id			= -1)	set	@subcataux_id			= NULL

					UPDATE tbitem
					SET subcataux_id	= @subcataux_id

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END

			--------------------------------------

			--------------------------------------
			--ACTUALIZAMOS LA MAX CANTIDAD DE CUOTAS
			IF @bitcreditquotaqtymax = 'True'
				BEGIN

					--if	(@creditquotaqtymax			= 0)	set	@creditquotaqtymax			= NULL

					UPDATE tbitem
