			--	----------------------------------------------------
			--ACTUALIZAMOS EL CAMPO SOLICITA SERIE
			IF @item_expser <> -1
				BEGIN
					UPDATE tbitem
					SET tbitem.item_expser  = @item_expser

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END
			----------------------------------------------------


			--	----------------------------------------------------
			--ACTUALIZAMOS EL CAMPO SOLICITA SERIE
			-- cursor por si son muchos articulos
			--	----------------------------------------------------
			IF @item_expser <> -1
				BEGIN
					DECLARE @litem_id		AS INT
					DECLARE cursor_items CURSOR LOCAL FAST_FORWARD FOR

						SELECT	ti.item_id
						FROM tbItem										ti
						INNER JOIN @tblComplexFilter_Items				tmp
						ON	tmp.item_id		= ti.item_id
						WHERE ti.comp_id	= @comp_id

					OPEN cursor_items

					-- lectura anticipada del cursor
					FETCH  cursor_items INTO	@litem_id

					WHILE @@FETCH_STATUS = 0
						BEGIN
							UPDATE tbitem
							SET tbitem.item_expser  = @item_expser

							FROM tbItem										ti

							WHERE ti.comp_id	= @comp_id AND
								  ti.item_id    = @litem_id


								FETCH  cursor_items INTO	@litem_id

						END

							CLOSE cursor_items
							DEALLOCATE cursor_items
				END

			-- ------------------------------------------------


			--	----------------------------------------------------
			--ACTUALIZAMOS EL CAMPO SOLICITA EAN
			-- cursor por si son muchos articulos
