			--------------------------------------


			--------------------------------------
			--ACTUALIZAMOS Purchase Discount
			IF @bitpd_id = 'True'
				BEGIN

					if	(@pd_id			= -1)	set	@pd_id			= NULL

					UPDATE tbitem
					SET tbitem.pd_id    	= @pd_id

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END

			--------------------------------------
			--


			--------------------------------------
			--ACTUALIZAMOS arbaCOT_Nomenclador
			IF @bitarbaCOT = 'True'
				BEGIN

					UPDATE tbitem
					SET tbitem.arbaCOT_Nomenclador =  @arbaCOT_Nomenclador

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END

			--------------------------------------


			----------------------------------------------------
			--ACTUALIZAMOS EL CAMPO Deshabilitado en Lista de Precios
			IF @item_disabledInPriceList <> -1
				BEGIN
					UPDATE tbitem
					SET item_disabledInPriceList = @item_disabledInPriceList

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END
			----------------------------------------------------

			----------------------------------------------------
			--Peso y Volumen

			IF @bititem_weight = 'True'
					BEGIN

						UPDATE tbitem
						SET tbitem.item_weight  = @item_weight

						FROM tbItem										ti

						INNER JOIN @tblComplexFilter_Items				tmp
						ON	tmp.item_id		= ti.item_id

						WHERE ti.comp_id	= @comp_id


					END


			IF @bititem_volume = 'True'
					BEGIN

						UPDATE tbitem
						SET tbitem.item_volume  = @item_volume

						FROM tbItem										ti

						INNER JOIN @tblComplexFilter_Items				tmp
						ON	tmp.item_id		= ti.item_id

						WHERE ti.comp_id	= @comp_id


					END
			----------------------------------------------------
			--

			--------------------------------------
			--ACTUALIZAMOS metricsunit
			IF @bitmu_id = 'True'
				BEGIN

					if	(@mu_id		= -1)	set	@mu_id			= NULL

					UPDATE tbitem
					SET tbitem.mu_id    	= @mu_id

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END

			--------------------------------------

			--------------------------------------
			--ACTUALIZAMOS "Cartel de Precio : Descripción 9"
			IF @bititem_PriceLabel_Desc9 = 'True'
				BEGIN

					UPDATE tbitem
					SET tbitem.item_PriceLabel_Desc9   	= @item_PriceLabel_Desc9

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END

			--------------------------------------


			--------------------------------------
			--ACTUALIZAMOS WebSite / FullJaus©
			IF @bititem_WebSite_desc = 'True'
				BEGIN

					UPDATE tbitem
					SET tbitem.item_WebSite_desc   	= @item_WebSite_desc

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END

			--------------------------------------

			--------------------------------------
			--ACTUALIZAMOS WebSite / FullJaus© Texto Adicional WEB 1 (Copete)
			IF @bititem_annotation1 = 'True'
				BEGIN

					UPDATE tbitem
					SET tbitem.item_annotation1   	= @item_annotation1

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END

			--------------------------------------

			--------------------------------------
			--ACTUALIZAMOS HTML Asociado
			IF @bititem_descHTML = 'True'
				BEGIN

					UPDATE tbitem
					SET tbitem.item_descHTML   	= @item_descHTML

					FROM tbItem										ti

					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id

					WHERE ti.comp_id	= @comp_id

				END

			--------------------------------------







END
GO








