CREATE procedure spItem_IsExPser
(
	@comp_id	INT,
	@item_id	INT
)

as set NOCOUNT ON

	-- -------------------------------
	-- TESTING
	-- -------------------------------
	/*
		declare
			@comp_id	INT,
			@item_id	INT

		select
			@comp_id	= 1,
			@item_id	= 256
	*/
	-- -------------------------------

	begin

		select
			isnull(ti.item_expser,'False')	[item_expser]
		from tbItem ti

		where	ti.comp_id	= @comp_id	and
				ti.item_id	= @item_id
	end
GO

CREATE PROCEDURE spItem_MassiveUpdate_ExecutePriceUpdateRules
(
	@comp_id	INT,
	@coslis_id	INT,
	@item_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------------------------
		-- Disparo de Reglas de actualizacion de precios segun lista de costos recibida
		-- y articulo actualizado
		-- -----------------------------------------------------------------------------
		IF @coslis_id > 0
 			BEGIN
				UPDATE tbItemCostList
 				SET	coslis_lastUpdate	= GETDATE(),
 					coslis_price		= coslis_price
 				WHERE	comp_id		= @comp_id		AND
 						coslis_id	= @coslis_id	AND
 						item_id		= @item_id
			END
		-- ---------------------------------------------------------------------------
	END

GO

CREATE PROCEDURE spItem_PcConfig_GetAllSubCatPCConfigTypes
(
