CREATE PROCEDURE spItem_PCConfig_Relations_GetData4WebService
(
	@comp_id	INT,
	@item_id	INT,
	@pcct_id	INT
)
AS
	BEGIN
		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT,
				@pcct_id	INT
			SELECT
				@comp_id	= 1,
				@item_id	= 698,
				@pcct_id	= -1
		*/
		-- -------------------------------------------------

		SELECT
			*
			FROM tbItem_PCConfig_Relations				ti	WITH (NOLOCK)
			WHERE	ti.comp_id			= @comp_id	AND
					(	@item_id		= -1 OR
						ti.item_id		= @item_id
					)								AND
					(
						@pcct_id		= -1 OR
						ti.pcct_id		= @pcct_id
					)								AND
					ISNULL(ti.pcctr_disabled,'False') = 'False'
	END
GO

