CREATE PROCEDURE [dbo].[spItem_UpdateImagesURL4MercadoLibreAttributesImport]
(
	@comp_id					INT,
	@item_id					INT,
	@item_WebSite_url4Image1	NVARCHAR(150),
	@item_WebSite_url4Image2	NVARCHAR(150),
	@item_WebSite_url4Image3	NVARCHAR(150),
	@item_WebSite_url4Image4	NVARCHAR(150),
	@item_WebSite_url4Image5	NVARCHAR(150),
	@item_WebSite_url4Image6	NVARCHAR(150),
	@item_WebSite_url4Image7	NVARCHAR(150),
	@item_WebSite_url4Image8	NVARCHAR(150),
	@item_WebSite_url4Image9	NVARCHAR(150),
	@item_WebSite_url4Image10	NVARCHAR(150)
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------
		/*
			DECLARE
				@comp_id					INT,
				@item_id					INT,
