					MLPictureId2 = CASE WHEN @MLPictureId2   <> '' THEN @MLPictureId2 ELSE '' END,
					MLPictureId3 = CASE WHEN @MLPictureId3   <> '' THEN @MLPictureId3 ELSE '' END,
