CREATE PROCEDURE [dbo].[spItem_UpdatePicture4ImageImportation]
(
	@comp_id			INT,
	@item_code			VARCHAR(50),
	@item_Image			IMAGE,
	@bitReplaceImage	BIT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------
		-- TESTING
		-- --------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@item_code			VARCHAR(50),
				@item_Image			IMAGE,
				@bitReplaceImage	BIT
		*/
		-- --------------------------------------------------



		-- --------------------------------------------------------------------------------------------------------
		-- Evitar Bloqueo de Interprocesos - CONSULTAR a Aquitecto
		-- --------------------------------------------------------------------------------------------------------
		SET LOCK_TIMEOUT 5000			-- 10 segundos
		SET DEADLOCK_PRIORITY LOW		-- Tomar en cuenta para ULTIMA Opcion de Eliminación
		-- --------------------------------------------------------------------------------------------------------



		DECLARE @lUpdateOK		AS INT
		SET		@lUpdateOK		= 0


		--SI ESTÁ CHECKEADO REEMPLAZO LA IMAGEN DIRECTAMENTE
		IF @bitReplaceImage = 'True'
			BEGIN
				IF EXISTS (SELECT TOP 1  1
								FROM tbItem								ti		WITH (NOLOCK)
								WHERE	ti.comp_id		= @comp_id		AND
										ti.item_code	= @item_code)
					BEGIN
						UPDATE tbItem	WITH (ROWLOCK)
						SET
							item_picture	= @item_Image
						WHERE	comp_id		= @comp_id		AND
								item_code	= @item_code

						SET @lUpdateOK = 1

					END
			END
		ELSE
			BEGIN
				--SI NO ESTÁ CHECKEADO PRIMERO ME FIJO QUE SOLO ACTUALIZO EL ARTÍCULO SI NO TIENE IMAGEN, SINO LO DEJO COMO ESTÁ
				IF EXISTS (SELECT TOP 1  1
							FROM tbItem								ti		WITH (NOLOCK)
							WHERE	ti.comp_id		= @comp_id		AND
									ti.item_code	= @item_code	AND
									ti.item_picture IS NULL)

						UPDATE tbItem	WITH (ROWLOCK)
						SET
							item_picture	= @item_Image
						WHERE	comp_id		= @comp_id		AND
								item_code	= @item_code

						SET @lUpdateOK = 1

			END





		-- 0 : No actualizó
		-- 1 : Sí Actualizó

		SELECT @lUpdateOK [UpdateOK]



	END
GO



