		-- de este método ejecutar el "BuscarTexto" en la base de datos
		-- con el valor de referencia "#8600"
		-- Página de EJEMPLO:App_Reports_App_WebForms_wfmRptFilters_PriceLists2_Testing
		-- -------------------------------------------------------------
		DECLARE @objGUID AS UNIQUEIDENTIFIER
		SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@Item_Guid)
		DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf      WITH (NOLOCK)
				WHERE tcf.sl_guid	  = @objGUID      AND
					  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
				FROM tbItem ti	WITH (NOLOCK)
				WHERE ti.comp_id = @comp_id
			END

	IF @replaceOption = 1
		BEGIN
			UPDATE tbitem
				SET
--				item_cantMin		= @minqty,
--				item_cantOpt		= @optqty,
				item_purOrd_Disc1	= isnull(item_purOrd_Disc1,0)  + @item_purOrd_Disc1,
				item_purOrd_Disc2	= isnull(item_purOrd_Disc2,0)  + @item_purOrd_Disc2,
				item_purOrd_Disc3	= isnull(item_purOrd_Disc3,0)  + @item_purOrd_Disc3,
				item_purOrd_Disc4	= isnull(item_purOrd_Disc4,0)  + @item_purOrd_Disc4
			FROM tbItem ti	WITH (NOLOCK)
				INNER JOIN @tblComplexFilter_Items TEMP
				ON TEMP.item_id = ti.item_id

			WHERE
					 ti.comp_id = @comp_id
				AND (@bra_id    = -1	OR ti.bra_id	= @bra_id	OR ti.bra_id IS NULL)
				AND (@cat_id    = -1	OR ti.cat_id	= @cat_id)
				AND (@subcat_id = -1	OR ti.subcat_id = @subcat_id)
				AND (@pres_id   = -1	OR ti.pres_id	= @pres_id)
				AND (@brand_id  = -1	OR ti.brand_id	= @brand_id)
				AND (@item_id   = -1	OR ti.item_id	= @item_id)
				AND (@supp_id   = -1	OR ti.supp_id	= @supp_id)
		END
	ELSE
		BEGIN
			UPDATE tbitem
				SET
				item_purOrd_Disc1 = @item_purOrd_Disc1, --case when @item_purOrd_Disc1 <> 0 THEN @item_purOrd_Disc1 ELSE item_purOrd_Disc1 END ,
				item_purOrd_Disc2 = @item_purOrd_Disc2, --case when @item_purOrd_Disc2 <> 0 THEN @item_purOrd_Disc2 ELSE item_purOrd_Disc2 END,
				item_purOrd_Disc3 = @item_purOrd_Disc3, --case when @item_purOrd_Disc3 <> 0 THEN @item_purOrd_Disc3 ELSE item_purOrd_Disc3 END,
				item_purOrd_Disc4 = @item_purOrd_Disc4 --case when @item_purOrd_Disc4 <> 0 THEN @item_purOrd_Disc4 ELSE item_purOrd_Disc4 END
			FROM tbItem ti	WITH (NOLOCK)
				INNER JOIN @tblComplexFilter_Items	TEMP
				ON TEMP.item_id = ti.item_id

			WHERE
					 ti.comp_id = @comp_id
				AND (@bra_id    = -1	OR ti.bra_id	= @bra_id	OR ti.bra_id IS NULL)
				AND (@cat_id    = -1	OR ti.cat_id	= @cat_id)
				AND (@subcat_id = -1	OR ti.subcat_id = @subcat_id)
				AND (@pres_id   = -1	OR ti.pres_id	= @pres_id)
				AND (@brand_id  = -1	OR ti.brand_id	= @brand_id)
				AND (@item_id   = -1	OR ti.item_id	= @item_id)
				AND (@supp_id   = -1	OR ti.supp_id	= @supp_id)
		END

END
GO








