CREATE PROCEDURE [dbo].[spItemAdditional_getDataByFilters]
(

		@comp_id								INT,
		@item_id								INT,
		@item_id_1								INT
)
as
set nocount ON
--set dateformat 'ymd'

/*
declare	@comp_id								INT,
		@item_id								INT,
		@item_id_1								INT


select		@comp_id		= 1,
			@item_id		=239,
			@item_id_1		=264
*/


SELECT  ' ' [ ], ' ' [ ],' ' [ ],
		ti.item_code															[item_codeMain],
		ti.item_desc									[item_descMain],
		ti2.item_code															[item_codeChild],
		ti2.item_desc									[item_descChild],
		tia.ir_qty																[iasso_qty],
		CONVERT(VARCHAR,tia.item_id) + ' - ' + Convert(Varchar, tia.item_id_1)	[ID]


FROM	tbItemAdditional tia					WITH (NOLOCK)

		Inner Join tbItem ti					WITH (NOLOCK)
		On	ti.comp_id	= tia.comp_id
		And ti.item_id	= tia.item_id

		Inner Join tbitem ti2					WITH (NOLOCK)
		On  ti2.comp_id = tia.comp_id
		And ti2.item_id = tia.item_id_1

WHERE	tia.comp_id			= @comp_id			AND
(
	(
		(@item_id   = -1 or tia.item_id		= @item_id)		AND
		(@item_id_1 = -1 or tia.item_id_1	= @item_id_1)
	)
	OR
	(
		(@item_id   = -1 or tia.item_id_1   = @item_id)		AND
		(@item_id_1 = -1 or tia.item_id		= @item_id_1)
	)
)


--AND		(
--			@item_id		= -1			OR
--			tia.item_id		= @item_id
--		)
--AND		(
--			@item_id_1		= -1			OR
--			tia.item_id_1	= @item_id_1
--		)
GO








