From tbItemAdditional tia

Inner Join tbItem ti1
On  ti1.comp_id = tia.comp_id
And ti1.item_id = tia.item_id


Inner Join tbItem ti2
On  ti2.comp_id = tia.comp_id
And ti2.item_id = tia.item_id_1


Where tia.comp_id    = @comp_id
And   tia.item_id    = @Item_id
And   tia.item_id_1  = @Item_id_1
GO








