CREATE PROCEDURE [dbo].[spItemAdditional_validateData]
(
	@comp_id		int,
	@origen			Int,
	@destino		Int,
	@level			Int,
	@return_value	Int Output
)
as
set nocount on


/*
Declare		@comp_id	int,
			@origen Int,
			@destino Int,
			@level	Int,
			@return_value Int
select		@comp_id	=1,
			@origen		=277,
			@destino	=229,
			@level		=0,
			@return_value = 0
*/


Set @level = @level + 1

-- -----------------------
-- Para Evitar StackFault
If @level > 30
Begin
    Return
End
-- -----------------------

--select		@level ,@origen,	@destino


If Exists (Select 1 From tbItemAdditional tia
           Where tia.comp_id	= @comp_id
           And tia.item_id		= @origen
           And tia.item_id_1	= @destino
           And @level			= 1 )

	Begin

		-- esta condición es para evitar duplicados
		Set @return_value = 2
		--Select 33

	End

Else

	Begin

		If Exists (Select 1 From tbItemAdditional tia
				   Where tia.comp_id	= @comp_id
				   And tia.item_id		= @destino
				   And tia.item_id_1	= @origen )

			begin
				--esta condición es cuando se encuentra que algún origen es parte del destino
				Set @return_value = 1
				--Select 1

			End

		Else

			Begin

				Declare @lorigen Int,
						@lret_val Int
				Select @lret_val =0

				Declare @varCursor Cursor
				Set @varCursor = Cursor for
					Select	tia.item_id_1
					From	tbItemAdditional tia
					Where	tia.comp_id = @comp_id
					And		tia.item_id = @destino

				Open @varCursor
				--Select 2

				Fetch  @varCursor Into @lorigen

				While @@FETCH_STATUS = 0 And @lret_val = 0
				Begin

					--Select @lorigen
					Exec spItemAdditional_validateData
						@comp_id,
						@origen,
						@lorigen,
						@level,
						@return_value = @lret_val Output

					Fetch  @varCursor Into @lorigen

				End

				Close @varCursor
				Deallocate @varCursor

				Set @return_value = @lret_val

			End

	End








GO

