CREATE PROCEDURE [dbo].[spItemAdditionalCost_GetDataByItem]
(
	@comp_id	INT,
	@item_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT
			SELECT
				@comp_id	= 1,
				@item_id	= 493
		*/
		-- ------------------------------------------------



		SELECT
			' '										[ ],	--UPDATE
			' '										[ ],	--DELETE
			tiac.itemca_desc,
			tiac.itemca_note,
			tiac.itemca_image,
			tiac.itemca_cd,
			tiac.itemca_qty,
			tiac.itemca_price,
			tc.curr_symbol,
			ISNULL(ts.supp_name,'')					[supp_name],
			tiac.itemca_id	[ID]
			FROM tbItemAdditionalCost				tiac	WITH(NOLOCK)
				INNER JOIN tbsysCurrency			tc		WITH(NOLOCK)
				ON	tc.curr_id		= tiac.curr_id
				LEFT JOIN tbSupplier				ts		WITH(NOLOCK)
				ON	ts.comp_id		= tiac.comp_id	AND
					ts.supp_id		= tiac.supp_id
			WHERE	tiac.comp_id	= @comp_id AND
					tiac.item_id	= @item_id

	END
GO

CREATE PROCEDURE [dbo].[spItemAdditionalCost_InsertData]
(
	@comp_id		INT,
	@item_id		INT,
	@itemca_desc	NVARCHAR(100),
	@itemca_note	NTEXT,
	@itemca_image	IMAGE,
	@itemca_qty		INT,
	@itemca_price	DECIMAL(19,2),
	@curr_id		INT,
	@supp_id		INT,
	@itemca_cd		DATETIME,
	@return_value	INT OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@item_id		INT,
				@itemca_desc	NVARCHAR(100),
				@itemca_note	NTEXT,
				@itemca_image	IMAGE,
				@itemca_qty		INT,
				@itemca_price	DECIMAL(19,2),
				@curr_id		INT,
				@return_value	INT
		*/
		-- --------------------------------------------

		IF @supp_id = -1
			BEGIN
				SET @supp_id = NULL
			END

		INSERT INTO tbItemAdditionalCost
		(
			comp_id,
			-- itemca_id -- this column value is auto-generated,
			item_id,
			itemca_desc,
			itemca_note,
			itemca_image,
			itemca_cd,
			itemca_qty,
			itemca_price,
			curr_id,
			supp_id
		)
		VALUES
		(
			@comp_id,
			@item_id,
			@itemca_desc,
			@itemca_note,
			@itemca_image,
			@itemca_cd,
			@itemca_qty,
			@itemca_price,
			@curr_id,
			@supp_id
		)

		SET @return_value = @@IDENTITY

	END
GO

