	@itemca_cd		DATETIME
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@itemca_id		INT,
				@itemca_desc	VARCHAR(100),
				@itemca_note	NTEXT,
				@itemca_image	IMAGE,
				@itemca_qty		INT,
