CREATE Procedure [dbo].[spItemAssociation_getReport]

		@comp_id		INT,
		@lang_id		INT,
		@page_id		INT,

		@option         INT,
		@list_id        INT,



		@cat_id			INT,
		@subcat_id		INT,
		@brand_id		INT,
		@item_id		INT,
		@pres_id		INT,
		@guid			VARCHAR(50), --CF DE ITEMS
		@bra_id			INT,
		@intBranch4Lang int

	AS

SET NOCOUNT ON

SET dateformat 'ymd'

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

/*
DECLARE @comp_id		INT,
		@lang_id		INT,
		@page_id		INT,

		@option			INT, /*-1:Ninguna, 1:Ventas, 2:Costos*/
		@list_id		INT ,
		@cat_id			INT,
		@subcat_id		INT,
		@brand_id		INT,
		@item_id		int,
		@pres_id		INT,
		@bra_id			INT



SELECT
		@comp_id		=1,
		@lang_id		=2,
		@page_id		=10048,



        @option		    =  1,
		@list_id	    =  1,

		@cat_id			= -1,
		@subcat_id		= -1,
		@brand_id		= -1,
		@item_id		= -1,
		@pres_id		= -1,
		@bra_id			=-1

*/



DECLARE @lGuid AS UNIQUEIDENTIFIER

SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

-- -------------------------------------------------------------
-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
-- -------------------------------------------------------------
DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
INSERT INTO @tblComplexFilter_Items
	SELECT tcf.sl_id
		FROM tbComplexFilter tcf
		WHERE tcf.sl_guid = @lGuid     AND
					  tcf.sl_selected = 'True'
IF @@ROWCOUNT = 0
	BEGIN
		INSERT INTO @tblComplexFilter_Items
			SELECT ti.item_id
				FROM tbItem ti
				WHERE ti.comp_id = @comp_id
	END
-- -------------------------------------------------------------

DECLARE @fun_id INT
SET @fun_id = 1

SELECT  ti.item_code [item_code1],
		ti.item_desc [item_desc1],
		ti.item_upb,

		CASE @option WHEN 1 THEN dbo.fnGetExchange2(@comp_id ,isnull(tpli.prli_price * tia.iasso_qty,0),tpli.curr_id,ti.curr_id, tpli.curr_id,ti.curr_id,0,'False')
					ELSE dbo.fnGetExchange2(@comp_id,isnull(ticl.coslis_price * tia.iasso_qty,0), ticl.curr_id,ti.curr_id,ticl.curr_id,ti.curr_id,0,'False')
		END [value1],

		ti2.item_code [item_code2],
		ti2.item_desc [item_desc2],

		tia.iasso_qty,

		CASE @option WHEN 1 THEN dbo.fnGetExchange2(@comp_id,isnull(tpli2.prli_price * tia.iasso_qty, 0),tpli2.curr_id,ti.curr_id,tpli2.curr_id,ti.curr_id,0,'False')
					ELSE dbo.fnGetExchange2(@comp_id,isnull(ticl2.coslis_price * tia.iasso_qty,0),ticl2.curr_id,ti.curr_id,ticl2.curr_id,ti.curr_id,0,'False')
		END [value2]




FROM	tbItemAssociation tia		WITH (NOLOCK)

		INNER JOIN tbItem ti		WITH (NOLOCK)
		ON ti.comp_id = tia.comp_id
		AND ti.item_id = tia.item_id

		INNER JOIN @tblComplexFilter_Items				tempITEM
		ON tempitem.item_id			= ti.item_id

		LEFT JOIN tbPriceListItems tpli	WITH (NOLOCK)
		ON tpli.comp_id	 = tia.comp_id
		AND tpli.prli_id = @list_id
		AND tpli.item_id = ti.item_id
		AND @option = 1

		LEFT JOIN tbItemCostList ticl	WITH (NOLOCK)
		ON ticl.comp_id	   = tia.comp_id
		AND ticl.coslis_id = @list_id
		AND ticl.item_id	= ti.item_id
		AND @option = 2


		INNER JOIN tbitem ti2	WITH (NOLOCK)
		ON ti2.comp_id = tia.comp_id
		AND ti2.item_id = tia.item_id_1

		LEFT JOIN tbPriceListItems tpli2	WITH (NOLOCK)
		ON tpli2.comp_id	 = tia.comp_id
		AND tpli2.prli_id = @list_id
		AND tpli2.item_id = ti2.item_id
		AND @option = 1

		LEFT JOIN tbItemCostList ticl2	WITH (NOLOCK)
		ON ticl2.comp_id	   = tia.comp_id
		AND ticl2.coslis_id = @list_id
		AND ticl2.item_id	= ti2.item_id
		AND @option = 2

		INNER JOIN tbCategory tc	WITH (NOLOCK)
		ON tc.comp_id = ti.comp_id
		AND tc.cat_id = ti.cat_id

		INNER JOIN tbSubCategory tsc	WITH (NOLOCK)
		ON tsc.comp_id = ti.comp_id
		AND tsc.subcat_id = ti.subcat_id

		INNER JOIN tbBrand tb	WITH (NOLOCK)
		ON tb.comp_id = ti.comp_id
		AND tb.brand_id = ti.brand_id

		INNER JOIN tbPresentation tp	WITH (NOLOCK)
		ON tp.comp_id = ti.comp_id
		AND tp.pres_id = ti.pres_id


WHERE ti.comp_id = @comp_id
AND  (@cat_id = -1 or tc.cat_id    = @cat_id)
AND  (@subcat_id = -1 or tsc.subcat_id    = @subcat_id)
AND  (@brand_id = -1 or tb.brand_id	  = @brand_id)
AND  (@item_id= -1  or ti.item_id   = @item_id)
AND  (@pres_id= -1  or tp.pres_id   = @pres_id)


ORDER BY 1

exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id



/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/

	/*	SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/

SELECT

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 991
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params1],
		CASE @option WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tov.optval_desc
					FROM	tbsysOptionsValues tov
					WHERE	tov.lang_id = @lang_id --tC.comp_id = @comp_id AND tc.cust_id= @cust_id)
					AND     tov.optval_class = 19
					AND     tov.optval_order = @option)
		END		[params2],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1024
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params3],

		CASE @option WHEN 1 THEN
				(SELECT tpli.prli_desc FROM tbPriceList tpli	WITH (NOLOCK)
				WHERE tpli.comp_id = @comp_id
				AND 	   tpli.prli_id = @list_id)

		ELSE (SELECT ticln.coslis_desc FROM tbItemCostListName ticln	WITH (NOLOCK)
					      WHERE ticln.comp_id = @comp_id
							AND ticln.coslis_id =@list_id )
		END [params4],





		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 103
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],
		CASE @item_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut	WITH (NOLOCK)
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				( SELECT

						ti.item_desc


				  FROM tbItem ti	WITH (NOLOCK)


		WHERE  ti.comp_id = @comp_id
		AND ti.item_id = @item_id)
		END		[params6],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 36
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params7],
		CASE @cat_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut	WITH (NOLOCK)
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tc.cat_desc
				 FROM tbCategory tc	WITH (NOLOCK)
				WHERE tc.comp_id = @comp_id
				AND	  tc.cat_id = @cat_id)

		END		[params8],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 38
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params9],
		CASE @subcat_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tsc.subcat_desc
				 FROM tbSubCategory tsc	WITH (NOLOCK)

				 INNER JOIN tbCategory tc	WITH (NOLOCK)
				 ON tc.comp_id = tsc.comp_id
				 AND tc.cat_id = tsc.cat_id


				 WHERE tc.comp_id = @comp_id
				 AND tc.cat_id = @cat_id
				 AND tsc.subcat_id =@subcat_id)

		END		[params10],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 73
      	 --AND t.[lang_id] = @lang_id
     	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params11],
		CASE @brand_id  WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut	WITH (NOLOCK)
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tb.brand_desc
				 FROM tbBrand tb	WITH (NOLOCK)
					WHERE tb.comp_id = @comp_id
					AND  tb.brand_id = @brand_id )
		END		[params12],




		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 371
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params13],
		CASE @pres_id  WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tp.pres_desc
				 FROM tbPresentation tp
					WHERE tp.comp_id = @comp_id
					AND  tp.pres_id = @pres_id )
		END		[params14],

		(SELECT tswn.word_desc FROM tbSysWordsNew tswn WHERE tswn.lang_id = @lang_id and tswn.wordsi_id = 3633)	[params15]

GO

CREATE PROCEDURE spItemAssociation_HasAssociatedItems
(
	@comp_id	INT,
	@item_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		IF EXISTS (SELECT
					1
					FROM tbItemAssociation			tia
					WHERE	tia.comp_id = @comp_id	AND
							tia.item_id = @item_id)

			BEGIN
				SELECT 'True'
			END
		ELSE
			BEGIN
				SELECT 'False'
			END
	END

GO








CREATE PROCEDURE [dbo].[spItemAssociation_InsertData]
(
		@comp_id								Int,
		@Item_id								Int,
		@Item_id_1								Int,
		@iasso_qty								decimal (19,7),
		@itema_canDeleteInSO					bit,
		@itema_discountPercentage4PriceListSUM	decimal (15,4)
)
AS

BEGIN


	set nocount on

	/*
	Declare @comp_id			Int,
			@Item_id			Int,
			@Item_id_1			Int,
			@iasso_qty			decimal (19,7)

	Select @comp_id				= 1,
		   @Item_id			    = 232,
		   @Item_id_1			= 238,
		   @iasso_qty			= '10,0'

	*/

	Insert into tbItemAssociation
	(
		comp_id,
		item_id,
		item_id_1,
		iasso_qty,
		itema_canDeleteInSO,
		itema_discountPercentage4PriceListSUM
	)
	VALUES
	(
		@comp_id,
		@Item_id,
		@Item_id_1,
		@iasso_qty,
		@itema_canDeleteInSO,
		@itema_discountPercentage4PriceListSUM
	)


	-- Pone que el item principal es un Combo
	UPDATE tbitem	WITH (ROWLOCK)
		SET item_isForAssociation = 'True'
		WHERE	comp_id = @comp_id AND
				item_id = @Item_id



END
GO








CREATE PROCEDURE [dbo].[spItemAssociation_UpdateData]
(
		@comp_id								Int,
		@Item_id								Int,
		@Item_id_1								Int,
		@iasso_qty								decimal (19,7),
		@itema_canDeleteInSO					bit,
		@itema_discountPercentage4PriceListSUM	decimal (15,4),
		@Itema_id								Int
)
as

BEGIN


	set nocount on


	-- ----------------------------------------------
	-- ----------------------------------------------
	/*
	Declare @comp_id			Int,
			@Item_id			Int,
			@Item_id_1			Int,
			@iasso_qty			decimal (19,7)

	Select @comp_id				= 1,
		   @Item_id			    = 232,
		   @Item_id_1			= 238,
		   @iasso_qty			= '10,0'

	*/
	-- ----------------------------------------------

	Update tbItemAssociation
		Set
		 iasso_qty								= @iasso_qty,
		 itema_canDeleteInSO					= @itema_canDeleteInSO,
		 itema_discountPercentage4PriceListSUM	= @itema_discountPercentage4PriceListSUM
		--Where comp_id   = @comp_id
		--and   item_id   = @Item_id
		--and   item_id_1 = @Item_id_1
		WHERE comp_id		=	@comp_id AND
			  itema_id		=	@Itema_id

	-- Pone que el item principal es un Combo
	UPDATE tbitem	WITH (ROWLOCK)
		SET item_isForAssociation = 'True'
		WHERE	comp_id = @comp_id AND
				item_id = @Item_id


END
GO







CREATE PROCEDURE [dbo].[spItemAssociation_validateData]
(
	@comp_id		int,
	@origen			Int,
	@destino		Int,
	@level			Int,
	@return_value	Int Output
)
as
set nocount on


/*
Declare		@comp_id	int,
			@origen Int,
			@destino Int,
			@level	Int,
			@return_value Int
select		@comp_id	=1,
			@origen		=277,
			@destino	=229,
			@level		=0,
			@return_value = 0
*/


Set @level = @level + 1

-- -----------------------
-- Para Evitar StackFault
If @level > 30
Begin
    Return
End
-- -----------------------

--select		@level ,@origen,	@destino


If Exists (Select 1 From tbItemAssociation tia		WITH (NOLOCK)
			   Where tia.comp_id	= @comp_id
			   And tia.item_id		= @origen
			   And tia.item_id_1	= @destino
			   And @level			= 1
			   AND 1 = 2 ) -- MOS 06-2020, ahora puede haber duplicados x Ofertas 2 + 1 free, etc. )

	Begin

		-- esta condición es para evitar duplicados
		Set @return_value = 2
		--Select 33

	End

Else

	Begin

		If Exists (Select 1 From tbItemAssociation tia	WITH (NOLOCK)
					   Where tia.comp_id	= @comp_id
					   And tia.item_id		= @destino
					   And tia.item_id_1	= @origen )

			begin
				--esta condición es cuando se encuentra que algún origen es parte del destino
				Set @return_value = 1
				--Select 1

			End

		Else

			Begin

				Declare @lorigen Int,
						@lret_val Int
				Select @lret_val =0

				Declare @varCursor Cursor
				Set @varCursor = CURSOR LOCAL FAST_FORWARD for
					Select	tia.item_id_1
					From	tbItemAssociation tia	WITH (NOLOCK)
					Where	tia.comp_id = @comp_id
					And		tia.item_id = @destino

				Open @varCursor
				--Select 2

				Fetch  @varCursor Into @lorigen

				While @@FETCH_STATUS = 0 And @lret_val = 0
				Begin

					--Select @lorigen
					Exec spItemAssociation_validateData
						@comp_id,
						@origen,
						@lorigen,
						@level,
						@return_value = @lret_val Output

					Fetch  @varCursor Into @lorigen

				End

				Close @varCursor
				Deallocate @varCursor

				Set @return_value = @lret_val

			End

	End








GO




