create PROCEDURE [dbo].[spItemClass_getDataById]
(


		@comp_id			INT,
		@lang_id			INT,
		@ic_id				INT


)
as

set nocount on

--------------------------------------------------------
-------------parametros de prueba-----------------------
--------------------------------------------------------
/*


Declare @comp_id			INT,
		@ic_id				INT


Select @comp_id				= 1,
	   @ic_id			    = 2


*/
--------------------------------------------------------
BEGIN

		SELECT
			tic.comp_id,
			tic.ic_id,
			tic.ic_desc,
			tic.ic_id_sup,
			tic.ic_isRoot,
			tic.ic_isSelectable,
			tic.ic_order,
			tic.ic_ownLevel,
			tic.ic_levelRoot,
			tic.ic_levelI,
			tic.ic_levelII,
			tic.ic_levelIII,
			tic.ic_levelIV,
			tic.ic_levelV,
			tic.ic_levelVI,
			tic.ic_levelVII,
			tic.ic_levelVIII

			FROM tbItemClass					tic

			Where tic.comp_id    = @comp_id
			And   tic.ic_id		 = @ic_id



END
GO






CREATE PROCEDURE [dbo].[spItemClass_getDataByText]
(
	@text		VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id	 AS INT

)
AS



BEGIN

	SET NOCOUNT ON


	-- -----------------------------------------------
	-- Testing
	-- -----------------------------------------------
	/*
	DECLARE
		@text		VARCHAR(300),
		@count		INT,
		@lang_id	INT,
		@comp_id AS INT,
		@bra_id	 AS INT
	SELECT
		@text		= 'a',
		@count		= 20,
		@lang_id	= 2,
		@comp_id    = 1,
		@bra_id	    = 1
	*/
	-- -----------------------------------------------


	SELECT			TOP (@count)
					REPLACE(
					dbo.fnStrPADR(dbo.fnItemClass4tbItem_getCombo(tic.comp_id,tic.ic_id_sup),55,'.') + ' >> ' +
					dbo.fnStrPADR(tic.ic_desc,50,'.')
					,'|',' ') + ' | ' + CONVERT(VARCHAR(10),tic.ic_id) 								[Desc],
					tic.ic_id																		[Id]
			FROM	tbItemClass tic						WITH (NOLOCK)
			WHERE	tic.comp_id = @comp_id AND
					tic.ic_isSelectable = 'true' AND
					tic.ic_desc LIKE '%' + @text + '%'
		ORDER BY tic.ic_isRoot DESC ,
				(	SELECT TOP	1 tmp.ic_order
						FROM	tbitemClass tmp			WITH (NOLOCK)
                   		WHERE	tic.comp_id = tic.comp_id AND
                   				tmp.ic_id	= tic.ic_id_sup	) ,
								tic.ic_order


END
GO




