CREATE PROCEDURE spItemClassLevelContructor
	@comp_id		AS INT,
	@ic_id			AS INT,
	@intMyLevel		AS INT				OUTPUT,
	@strIcIdString	AS VARCHAR(4000)	OUTPUT,
	@intICIdRoot	AS INT				OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @ErrorMessage   NVARCHAR(4000)
	DECLARE @ErrorSeverity  INT
	DECLARE @ErrorState     INT


	SET @intMyLevel		= ISNULL(@intMyLevel,0) + 1
	IF @intMyLevel > 30
		BEGIN

			SELECT  @ErrorMessage    = ERROR_MESSAGE(),
					@ErrorSeverity   = ERROR_SEVERITY(),
					@ErrorState      = ERROR_STATE()
			SELECT  @ErrorMessage	 = 'Error Recursivo intentando encontrar la Clase RAIZ, Mas de 100 Niveles en Clase:'  + CONVERT(NVARCHAR(10),@ic_id)
			IF      @ErrorState      = 0 SET @ErrorState = 1
			RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

			RETURN

		END



	SET @strIcIdString	= ISNULL(@strIcIdString,'')  + CONVERT(NVARCHAR(10), @ic_id) + ';'

	DECLARE @ic_id_UP AS INT

	SELECT	@ic_id_UP	 =	tic.ic_id_sup,
			@intICIdRoot =	CASE
								WHEN tic.ic_isRoot = 'True' THEN tic.ic_id
								ELSE NULL
							END
		FROM tbItemClass tic WITH (NOLOCK)
		WHERE	tic.comp_id = @comp_id AND
				tic.ic_id	= @ic_id



	IF @ic_id_UP IS NULL AND @intICIdRoot IS NULL
		BEGIN


			SELECT  @ErrorMessage    = ERROR_MESSAGE(),
					@ErrorSeverity   = ERROR_SEVERITY(),
					@ErrorState      = ERROR_STATE()
			SELECT  @ErrorMessage	 = 'Error Recursivo intentando encontrar la Clase RAIZ, Sin Clase Superior Asignada en Clase:' + CONVERT(NVARCHAR(10),@ic_id)
			IF      @ErrorState      = 0 SET @ErrorState = 1
			RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

			RETURN

		END


	IF @intICIdRoot IS NULL
		BEGIN
			EXEC spItemClassLevelContructor @comp_id,
											@ic_id_UP,
											@intMyLevel		OUTPUT,
											@strIcIdString	OUTPUT,
											@intICIdRoot	OUTPUT
		END




END
GO

CREATE PROCEDURE [dbo].[spItemCodeAlternative_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
AS
	BEGIN
		SET NOCOUNT ON

		--------------------------------------------------------------------------------------------------
		--PARAMETROS DE TESTING
		--------------------------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@guid			UNIQUEIDENTIFIER,
				@lang_id		INT

			SELECT
				@comp_id		= 1,
				@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
				@lang_id		= 2

		*/
		--------------------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

			SELECT
				tpclil.code4Import,
				tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
				tpclil.pli_cd											[pli_cd],
				ISNULL(tpclil.info,tut.utexts_desc)						[Error],
				tpclil.pli_idn											[ID]
				FROM	tbPriceCostListImportLog						tpclil	WITH (NOLOCK)
				LEFT JOIN tbUser										tu		WITH (NOLOCK)
					ON	tu.[user_id]	= tpclil.[user_id]
				LEFT JOIN tbsysUniqueTexts								tut		WITH (NOLOCK)
					ON	tut.lang_id		= @lang_id						AND
						tut.utexts_id	= 40151
				WHERE	tpclil.comp_id	= @comp_id						AND
						tpclil.pli_id	= @guid
			ORDER BY tpclil.pli_id ASC

	END
GO




