	@item_id_Destiny	INT
)
AS


	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------
		-- Testing
		-- ------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@item_id_Origin		INT,
				@wco_id				INT,
				@item_id_Destiny	INT

			SELECT
				@comp_id			= 1,
