CREATE PROCEDURE [dbo].[spItemComparatives_getDataByFilters]
(
	@comp_id	INT,
	@wco_id		INT,
	@item_id	INT,
	@cat_id		INT,
	@subcat_id	INT,
	@brand_id	INT
)

AS SET NOCOUNT ON

BEGIN

	-- ---------------------------
	-- TESTING
	-- ---------------------------
	/*
		DECLARE
			@comp_id	INT,
			@wco_id		INT,
			@item_id	INT,
			@cat_id		INT,
			@subcat_id	INT,
			@brand_id	INT

		SELECT
			@comp_id	= 1,
			@wco_id		= 2,
			@item_id	= -1,
			@cat_id		= -1,
			@subcat_id	= -1,
			@brand_id	= -1
	*/
	-- ---------------------------

	SELECT

		' '	[ ],
		' ' [ ],
		' ' [ ],
		' ' [ ],
		ticg.wcog_desc,
		ti.item_code,
		ti.item_desc,
		tic.wco_desc							[wco_desc],
		tc.cat_desc,
		tsc.subcat_desc,
		tb.brand_desc,
		ticr.wco_Text1,
		ticr.wco_Text2,
		ISNULL(ticr.wco_IntValue,0)				[wco_IntValue],
		ISNULL(ticr.wco_DecValue,0)				[wco_DecValue],
		ISNULL(ticr.wco_VarcharValue,'')		[wco_VarcharValue],
		ISNULL(ticr.wco_BitValue,'False')		[wco_BitValue],
		CONVERT(VARCHAR,ticr.comp_id) + '-' +
		CONVERT(VARCHAR,ticr.item_id) + '-' +
		CONVERT(VARCHAR,ticr.wco_id)			[ID]


	FROM tbItemComparatives						tic

		INNER JOIN tbItemComparativesRelations	ticr
		ON	ticr.comp_id	= tic.comp_id		AND
			ticr.wco_id		= tic.wco_id

		LEFT JOIN tbCategory					tc
		ON	tc.comp_id		= tic.comp_id		AND
			tc.cat_id		= tic.cat_id

		LEFT JOIN tbSubCategory					tsc
		ON	tsc.comp_id		= tic.comp_id		AND
			tsc.cat_id		= tic.cat_id		AND
			tsc.subcat_id	= tic.subcat_id

		INNER JOIN tbItem						ti
		ON	ti.comp_id		= ticr.comp_id		AND
			ti.item_id		= ticr.item_id

		LEFT JOIN tbItemComparativesGroup		ticg
		ON	ticg.comp_id	= tic.comp_id		AND
			ticg.wcog_id	= tic.wcog_id

		INNER JOIN tbBrand						tb
		ON	tb.comp_id		= ti.comp_id		AND
			tb.brand_id		= ti.brand_id

	WHERE	tic.comp_id	= @comp_id								AND
			(@wco_id	= -1 OR  ticr.wco_id	= @wco_id)		AND
			(@item_id	= -1 OR	 ticr.item_id	= @item_id)		AND
			(@cat_id	= -1 OR  tic.cat_id		= @cat_id)		AND
			(@subcat_id = -1 OR  tic.subcat_id	= @subcat_id)	AND
			(@brand_id	= -1 OR	 ti.brand_id	= @brand_id)

END
GO



