CREATE PROCEDURE spItemComparatives_InsertData
(
	@comp_id					INT,
	@cat_id						INT,
	@subcat_id					INT,
	@ws_id						INT,
	@wco_desc					NVARCHAR(500),
	@wcog_id					INT,
	@wco_Type					INT,
	@wco_isAvailable4Compare	BIT,
	@wco_isAvailable4Filters	BIT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id					INT,
				@cat_id						INT,
				@subcat_id					INT,
				@ws_id						INT,
				@wco_desc					NVARCHAR(500),
				@wcog_id					INT,
				@wco_Type					INT,
				@wco_isAvailable4Compare	BIT,
				@wco_isAvailable4Filters	BIT
		*/
		-- ---------------------------------------------

		IF @cat_id = -1
			BEGIN
				SET @cat_id = NULL
			END

		IF @subcat_id = -1
			BEGIN
				SET @subcat_id = NULL
			END

		IF @ws_id = -1
			BEGIN
				SET @ws_id = NULL
			END


		INSERT INTO tbItemComparatives
		(
			comp_id,
			cat_id,
			subcat_id,
			ws_id,
			wco_desc,
			wcog_id,
			wco_Type,
			wco_isAvailable4Compare,
			wco_isAvailable4Filters
		)
		VALUES
		(
			@comp_id,
			@cat_id,
			@subcat_id,
			@ws_id,
			@wco_desc,
			@wcog_id,
			@wco_Type,
			@wco_isAvailable4Compare,
			@wco_isAvailable4Filters
		)

	END

GO


CREATE PROCEDURE spItemComparatives_ProcessAuto_ValidateData
(
	@comp_id					INT,
	@lang_id					INT,
	@user_id					INT,
	@prof_id					INT,

	@cat_id						INT,
	@subcat_id					INT,
	@wco_desc					NVARCHAR(500),
	@wcog_id					INT,
	@wco_Type					INT,
	@intROW						INT,
	@guid						UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON
		--  ----------------------------------------------------------------------------------------
		-- TESTING
		--  ----------------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id					INT,
				@lang_id					INT,
				@user_id					INT,
				@prof_id					INT,

				@cat_id						INT,
				@subcat_id					INT,
				@wco_desc					NVARCHAR(500),
				@wcog_id					INT,
				@wco_Type					INT,
				@intROW						INT,
				@guid						UNIQUEIDENTIFIER
			SELECT
				@comp_id					= 1,
				@lang_id					= 2,
				@user_id					= 119,
				@prof_id					= 1,

				@cat_id						= -1,
				@subcat_id					= -1,
				@wco_desc					= '',
				@wcog_id					= -1,
				@wco_Type					= -1,
				@intROW						= 9,
				@guid						= 'C513E213-71EB-478C-B3B2-8BEAA8182968'
		*/
		--  ----------------------------------------------------------------------------------------


		DECLARE @errormessage   NVARCHAR(4000)
			DECLARE @return_value	INT
			DECLARE @bolIsOK		BIT

			SET     @bolIsOK		= 'True'
			SET		@errormessage	= ''

		--  ----------------------------------------------------------------------------------------
		-- CATEGORIA
		--  ----------------------------------------------------------------------------------------
		IF (@cat_id <> -1)
			BEGIN
				IF NOT EXISTS (SELECT tc.cat_id
							   FROM		tbCategory		tc		WITH (NOLOCK)
								WHERE	tc.comp_id		= @comp_id		AND
										tc.cat_id		= @cat_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + ' --- ' + 'El ID de Categoría es incorrecto'
					END
			END
		--  ----------------------------------------------------------------------------------------

		--  ----------------------------------------------------------------------------------------
		-- SUBCATEGORIA
		--  ----------------------------------------------------------------------------------------
		IF	(@subcat_id	<> -1)
			BEGIN
				IF NOT EXISTS (SELECT tsc.subcat_id
							   FROM		tbSubCategory	tsc		WITH (NOLOCK)
								WHERE	tsc.comp_id		= @comp_id		AND
										tsc.cat_id		= @cat_id		AND
										tsc.subcat_id	= @subcat_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + ' --- ' + 'El ID de SubCategoría es incorrecto o no está relacionada a la Categoría'
					END
			END
		--  ----------------------------------------------------------------------------------------

		--  ----------------------------------------------------------------------------------------
		-- DESCRIPCIÓN
		--  ----------------------------------------------------------------------------------------
		IF	(@wco_desc	= '')
			BEGIN

				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + ' --- ' + 'No se ha cargado una descripción para la Comparativa'

			END
		--  ----------------------------------------------------------------------------------------

		--  ----------------------------------------------------------------------------------------
		-- GRUPO DE COMPARATIVAS
		--  ----------------------------------------------------------------------------------------
		IF	(@wcog_id	<> -1)
			BEGIN
				IF NOT EXISTS (SELECT ticg.wcog_id
							   FROM tbItemComparativesGroup ticg
							   WHERE	ticg.comp_id = @comp_id AND
										ticg.wcog_id = @wcog_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + ' --- ' + 'El ID de Grupo de Comparativas es incorrecto o no existe'
					END
			END

		IF	(@wcog_id	= -1)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + ' --- ' + 'No se ha cargado un ID de Grupo de Comparativas'
			END
		--  ----------------------------------------------------------------------------------------

		--  ----------------------------------------------------------------------------------------
		-- TIPO DE DATO
		--  ----------------------------------------------------------------------------------------
		IF	(@wco_Type	<> -1)
			BEGIN
				IF NOT EXISTS (SELECT 1
				               FROM tbsysOptionsValues			tov
							WHERE	tov.optval_class	= 250	AND
									tov.optval_id		= @wco_Type)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + ' --- ' + 'El ID de Tipo de Dato es incorrecto o no existe'
					END
			END
		--  ----------------------------------------------------------------------------------------
		-- 1 True  : Todo ok para ACTUALIZAR.
		-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la ACTUALIZACIÓN.
		IF (@bolIsOK = 'True')
			BEGIN
				SELECT
					1				[bolIsOK],
					@intROW			[Nº Fila],
					@errormessage	[Error]
			END
		ELSE
			BEGIN

				EXEC [spItems_Process_ImportLog_InsertData] @comp_id, @guid, @user_id, @intROW, NULL, @errormessage

				SELECT
					0				[bolIsOK],
					@intROW			[Nº Fila],
					@errormessage	[Error]
			END


	END
GO




