CREATE PROCEDURE spItemComparativesRelations_getAllDataByItem
(
	@comp_id	INT,
	@item_id	INT
)
AS

	SET NOCOUNT ON

	BEGIN

		-- ----------------------
		-- Testing
		-- ----------------------
		/*
		DECLARE
			@comp_id	INT,
			@item_id	INT
		SELECT
			@comp_id	= 1,
			@item_id	= 256
		*/
		-- ---------------------

		SELECT
			tic.wco_desc,
			ISNULL(ticr.wco_Text1,'')			[wco_Text1],
			ISNULL(ticr.wco_Text2,'')			[wco_Text2],
			ISNULL(ticr.wco_IntValue,0)			[wco_IntValue],
			ISNULL(ticr.wco_DecValue,0)			[wco_DecValue],
			ISNULL(ticr.wco_VarcharValue,'')	[wco_VarcharValue],
			ISNULL(ticr.wco_BitValue,'False')	[wco_BitValue],
			CONVERT(VARCHAR,ticr.comp_id) + '-' +
			CONVERT(VARCHAR,ticr.item_id) + '-' +
			CONVERT(VARCHAR,ticr.wco_id)			[ID]

		FROM tbItemComparativesRelations	ticr
			INNER JOIN tbItemComparatives	tic
			ON	tic.comp_id = ticr.comp_id  AND
				tic.wco_id	= ticr.wco_id


		WHERE	ticr.comp_id = @comp_id AND
				ticr.item_id = @item_id

	END
GO




