CREATE PROCEDURE [dbo].[spItemComparativesRelations_InsertData_FromImporter]
(
	@comp_id			INT,
	@item_id			INT,
	@wco_id				INT,
	@wco_Text1			NVARCHAR(200),
	@wco_Text2			NVARCHAR(2000),
	@wco_IntValue		INT,
	@wco_DecValue		DECIMAL(19,4),
	@wco_VarcharValue	NVARCHAR(4000),
	@wco_BitValue		BIT,
	@bit_DeleteRecord	BIT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@item_id			INT,
				@wco_id				INT,
				@wco_Text1			NVARCHAR(200),
				@wco_Text2			NVARCHAR(2000),
				@wco_IntValue		INT,
				@wco_DecValue		DECIMAL(19,4),
				@wco_VarcharValue	NVARCHAR(4000),
				@wco_BitValue		BIT


			SELECT
				@comp_id			= 1 ,
				@item_id			= 495,
				@wco_id				= 2,
				@wco_Text1			= '',
				@wco_Text2			= '',
				@wco_IntValue		= 2,
				@wco_DecValue		= 2,
				@wco_VarcharValue	= '',
				@wco_BitValue		= 'false'
		*/
		-- -----------------------------------------------------------------------------------------------
		IF @bit_DeleteRecord = 'False'
			BEGIN
				IF NOT EXISTS (SELECT 1
								FROM tbItemComparativesRelations	tir
							   WHERE	tir.comp_id	= @comp_id		AND
										tir.item_id = @item_id		AND
										tir.wco_id	= @wco_id)
					BEGIN
						INSERT INTO tbItemComparativesRelations
						(
							comp_id,
							item_id,
							wco_id,
							wco_Text1,
							wco_Text2,
							wco_IntValue,
							wco_DecValue,
							wco_VarcharValue,
							wco_BitValue
						)
						VALUES
						(
							@comp_id,
							@item_id,
							@wco_id	,
							@wco_Text1,
							@wco_Text2,
							@wco_IntValue,
							@wco_DecValue,
							@wco_VarcharValue,
							@wco_BitValue
						)
					END
				ELSE
					BEGIN
						UPDATE tbItemComparativesRelations
						SET
							wco_Text1			= @wco_Text1,
							wco_Text2			= @wco_Text2,
							wco_IntValue		= @wco_IntValue,
							wco_DecValue		= @wco_DecValue,
							wco_VarcharValue	= @wco_VarcharValue,
							wco_BitValue		= @wco_BitValue
						WHERE	comp_id = @comp_id AND
								item_id = @item_id AND
								wco_id	= @wco_id
					END
			END
		ELSE
			BEGIN
				DELETE FROM tbItemComparativesRelations
				WHERE	comp_id = @comp_id AND
						item_id = @item_id AND
						wco_id	= @wco_id
			END
	END

GO


CREATE PROCEDURE [dbo].[spItemComparativesRelations_ProcessAuto_ValidateData]
(
	@comp_id	INT,
	@lang_id	INT,
	@user_id	INT,
	@prof_id	INT,

	@item_id	INT,
	@wco_id		INT,
	@intROW		INT,
	@guid		UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON
		--  ----------------------------------------------------------------------------------------
		-- TESTING
		--  ----------------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id					INT,
				@lang_id					INT,
				@user_id					INT,
				@prof_id					INT,

				@item_id					INT,
				@wco_id						INT,
				@intROW						INT,
				@guid						UNIQUEIDENTIFIER
			SELECT
				@comp_id					= 1,
				@lang_id					= 2,
				@user_id					= 119,
				@prof_id					= 1,

				@item_id					= -1,
				@wco_id						= -1,
				@intROW						= 9,
				@guid						= 'C513E213-71EB-478C-B3B2-8BEAA8182968'
		*/
		--  ----------------------------------------------------------------------------------------


		DECLARE @errormessage   NVARCHAR(4000)
			DECLARE @return_value	INT
			DECLARE @bolIsOK		BIT

			SET     @bolIsOK		= 'True'
			SET		@errormessage	= ''

		-- ----------------------------------------------------------------------------------------
		-- ARTÍCULO
		-- ----------------------------------------------------------------------------------------
		IF (@item_id <> -1)
			BEGIN
				IF NOT EXISTS (SELECT	1
				               FROM tbItem						ti
				               WHERE	ti.comp_id = @comp_id	AND
										ti.item_id = @item_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + ' --- ' + 'El ID de Artículo es Incorrecto o no existe'
					END
			END
		-- ----------------------------------------------------------------------------------------

		-- ----------------------------------------------------------------------------------------
		-- ID De Comparativa
		-- ----------------------------------------------------------------------------------------
		IF (@wco_id <> -1)
			BEGIN
				IF NOT EXISTS (SELECT	1
				               FROM tbItemComparatives			tic
				               WHERE	tic.comp_id = @comp_id	AND
										tic.wco_id	= @wco_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + ' --- ' + 'El ID de Comparativa es Incorrecto o no existe'
					END
			END
		-- ----------------------------------------------------------------------------------------


		-- ----------------------------------------------------------------------------------------
		-- YA EXISTE EL REGISTRO
		-- ----------------------------------------------------------------------------------------
		--IF EXISTS(SELECT 1
		--          FROM tbItemComparativesRelations	ticr
		--          WHERE ticr.comp_id	= @comp_id	AND
		--				ticr.item_id	= @item_id	AND
		--				ticr.wco_id		= @wco_id)
		--	BEGIN
		--		SET	@bolIsOK		= 'False'
		--		SET @errormessage	= @errormessage + ' --- ' + 'La relación que intenta insertar ya existe'
		--	END
		-- ----------------------------------------------------------------------------------------


		-- 1 True  : Todo ok para ACTUALIZAR.
		-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la ACTUALIZACIÓN.
		IF (@bolIsOK = 'True')
			BEGIN
				SELECT
					1				[bolIsOK],
					@intROW			[Nº Fila],
					@errormessage	[Error]
			END
		ELSE
			BEGIN

				EXEC [spItems_Process_ImportLog_InsertData] @comp_id, @guid, @user_id, @intROW, NULL, @errormessage

				SELECT
					0				[bolIsOK],
					@intROW			[Nº Fila],
					@errormessage	[Error]
			END


	END
GO




