CREATE PROCEDURE [dbo].[spItemComposition_getDataByFilters]
(

		@comp_id								Int,
		@item_id								Int,
		@item_id_1								Int,
		@color_id								Int
)
AS



BEGIN

	set nocount ON



	-- -----------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------
	/*
	declare	@comp_id								INT,
			@item_id								INT,
			@item_id_1								Int,
			@color_id								Int


	select		@comp_id		=1,
				@item_id		=15970,
				@item_id_1		=-1,
				@color_id       = -1
	*/
	-- -----------------------------------------------------------------

	SELECT  ' ' [ ], ' ' [ ],' ' [ ],
			ti.item_code															[item_codeMain],
   			ti.item_desc		[item_descMain],
   			ti2.item_code															[item_codeChild],
			ti2.item_desc		[item_descChild],
			tc.color_desc,
			--tic.item_id,
			--tic.item_id_1,
			--tic.color_id,
			tic.icomp_qty,
			CONVERT(VARCHAR,tic.item_id) + ' - ' + Convert(Varchar, tic.item_id_1) + ' - ' + Convert(Varchar,tic.color_id)  [ID]


	From	tbItemComposition tic					WITH (NOLOCK)

			Inner Join tbItem ti					WITH (NOLOCK)
			On ti.comp_id = tic.comp_id
			And ti.item_id = tic.item_id
			--
			--
			Inner Join tbitem ti2					WITH (NOLOCK)
			On  ti2.comp_id = tic.comp_id
			And ti2.item_id = tic.item_id_1
			--
			--
			LEFT Join tbColor tc					WITH (NOLOCK)
			On  tc.comp_id   = tic.comp_id
			And tc.color_id =  tic.color_id


	WHERE	tic.comp_id					      = @comp_id
	And     (@color_id  = -1 Or tic.color_id   = @color_id)
	AND		(@item_id   = -1 or tic.item_id    = @item_id)
	AND		(@item_id_1 = -1 or tic.item_id_1  = @item_id_1)




END

GO








CREATE PROCEDURE [dbo].[spItemComposition_getDataById]
(
		@comp_id			Int,
		@Item_id			Int,
		@Item_id_1			Int,
		@color_id			Int
)
as

set nocount on

/*
Declare @comp_id			Int,
		@Item_id			Int,
		@Item_id_1			Int


Select @comp_id				= 1,
	   @Item_id			    = 231,
	   @Item_id_1			= 264

		*/


Select tic.comp_id,
	   tic.item_id,
	   ti1.item_code,
	   ti1.item_desc,
	   tic.item_id_1,
	   ti2.item_code [item_code1] ,
	   ti2.item_desc [item_desc1],
	   tic.icomp_qty,
	   tic.color_id,
	   tc.color_desc

From tbItemComposition tic

Inner Join tbItem ti1
On  ti1.comp_id = tic.comp_id
And ti1.item_id = tic.item_id


Inner Join tbItem ti2
On  ti2.comp_id = tic.comp_id
And ti2.item_id = tic.item_id_1

Inner Join tbColor tc
On  tc.comp_id  = tic.comp_id
And tc.color_id = tic.color_id


Where tic.comp_id    = @comp_id
And   tic.item_id    = @Item_id
And   tic.item_id_1  = @Item_id_1
And   tic.color_id   = @color_id
GO





create procedure spItemComposition_GetDataForGenericGrid
(
	@comp_id	INT,
	@item_id	INT
)
as set NOCOUNT on


select
	ti.item_code,
	ti.item_desc,
	tic.icomp_qty,
	isnull(tc.color_desc, '')	[color_desc]

from tbItemComposition				tic
	inner join tbItem				ti
	on	ti.comp_id = tic.comp_id
	AND ti.item_id = tic.item_id_1
	left join tbColor				tc
	on	tc.comp_id	= tic.comp_id
	AND tc.color_id = tic.color_id

where	tic.comp_id = @comp_id
and		tic.item_id = @item_id
GO






CREATE Procedure [dbo].[spItemComposition_getReport]

		@comp_id		INT,
		@lang_id		INT,
		@page_id		INT,

		@option         INT,
		@list_id        INT,



		@cat_id			INT,
		@subcat_id		INT,
		@brand_id		INT,
		@item_id		INT,
		@pres_id		INT,
		@color_id		INT,

		@bra_id			INT,
		@intBranch4Lang int




	AS

SET nocount on
SET dateformat 'ymd'
/*
DECLARE @comp_id		INT,
		@lang_id		INT,
		@page_id		INT,

		@option			INT, /*-1:Ninguna, 1:Ventas, 2:Costos*/
		@list_id		INT ,
		@cat_id			INT,
		@subcat_id		INT,
		@brand_id		INT,
		@item_id		int,
		@pres_id		INT,
		@color_id		INT,
		@bra_id			INT



SELECT
		@comp_id		=1,
		@lang_id		=2,
		@page_id		=10050,



        @option		    =  1,
		@list_id	    =  1,

		@cat_id			= -1,
		@subcat_id		= -1,
		@brand_id		= -1,
		@item_id		= -1,
		@pres_id		= -1,
		@color_id		= -1,
		@bra_id			= -1


*/

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


DECLARE @fun_id INT
SET @fun_id = 1

SELECT  ti.item_code [item_code1],
		ti.item_desc [item_desc1],
		ti.item_upb,
		tc2.color_desc,

		CASE @option WHEN 1 THEN isnull(tpli.prli_price * tia.iasso_qty,0)
					ELSE isnull(ticl.coslis_price * tia.iasso_qty,0)
		END [value1],

		ti2.item_code [item_code2],
		ti2.item_desc [item_desc2],

		tia.iasso_qty,

		CASE @option WHEN 1 THEN isnull(tpli2.prli_price * tia.iasso_qty, 0)
					ELSE isnull(ticl2.coslis_price * tia.iasso_qty,0)
		END [value2]




FROM	tbItemComposition			tic


		INNER JOIN tbColor tc2
		ON tc2.comp_id = tic.comp_id
		AND tc2.color_id = tic.color_id


		INNER JOIN tbItemAssociation tia
		ON  tia.comp_id = tic.comp_id
		AND tia.item_id = tic.item_id


		INNER JOIN tbItem ti
		ON  ti.comp_id = tia.comp_id
		AND ti.item_id = tia.item_id


		LEFT JOIN tbPriceListItems tpli
		ON  tpli.comp_id	 = tia.comp_id
		AND tpli.prli_id = @list_id
		AND tpli.item_id = ti.item_id
		AND @option = 1

		LEFT JOIN tbItemCostList ticl
		ON ticl.comp_id	   = tia.comp_id
		AND ticl.coslis_id = @list_id
		AND ticl.item_id	= ti.item_id
		AND @option = 2


		INNER JOIN tbitem ti2
		ON ti2.comp_id = tia.comp_id
		AND ti2.item_id = tia.item_id_1

		LEFT JOIN tbPriceListItems tpli2
		ON tpli2.comp_id	 = tia.comp_id
		AND tpli2.prli_id = @list_id
		AND tpli2.item_id = ti2.item_id
		AND @option = 1

		LEFT JOIN tbItemCostList ticl2
		ON ticl2.comp_id	   = tia.comp_id
		AND ticl2.coslis_id = @list_id
		AND ticl2.item_id	= ti2.item_id
		AND @option = 2

		INNER JOIN tbCategory tc
		ON tc.comp_id = ti.comp_id
		AND tc.cat_id = ti.cat_id

		INNER JOIN tbSubCategory tsc
		ON tsc.comp_id = ti.comp_id
		AND tsc.subcat_id = ti.subcat_id

		INNER JOIN tbBrand tb
		ON tb.comp_id = ti.comp_id
		AND tb.brand_id = ti.brand_id

		INNER JOIN tbPresentation tp
		ON tp.comp_id = ti.comp_id
		AND tp.pres_id = ti.pres_id


WHERE ti.comp_id = @comp_id
AND  (@cat_id = -1 or tc.cat_id    = @cat_id)
AND  (@subcat_id = -1 or tsc.subcat_id    = @subcat_id)
AND  (@brand_id = -1 or tb.brand_id	  = @brand_id)
AND  (@item_id= -1  or ti.item_id   = @item_id)
AND  (@pres_id= -1  or tp.pres_id   = @pres_id)
AND  (@color_id = -1  or tic.color_id   = @color_id)


ORDER BY 1

exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id



/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/

SELECT

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 991
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params1],
		CASE @option WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tov.optval_desc
					FROM	tbsysOptionsValues tov
					WHERE	tov.lang_id = @lang_id --tC.comp_id = @comp_id AND tc.cust_id= @cust_id)
					AND     tov.optval_class = 19
					AND     tov.optval_order = @option)
		END		[params2],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1024
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params3],

		CASE @option WHEN 1 THEN
				(SELECT tpli.prli_desc FROM tbPriceList tpli
				WHERE tpli.comp_id = @comp_id
				AND 	   tpli.prli_id = @list_id)

		ELSE (SELECT ticln.coslis_desc FROM tbItemCostListName ticln
					      WHERE ticln.comp_id = @comp_id
							AND ticln.coslis_id =@list_id )
		END [params4],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 103
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],
		CASE @item_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				( SELECT

						ti.item_desc


				  FROM tbItem ti


		WHERE  ti.comp_id = @comp_id
		AND ti.item_id = @item_id)
		END		[params6],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 36
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params7],
		CASE @cat_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tc.cat_desc
				 FROM tbCategory tc
				WHERE tc.comp_id = @comp_id
				AND	  tc.cat_id = @cat_id)

		END		[params8],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 38
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params9],
		CASE @subcat_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tsc.subcat_desc
				 FROM tbSubCategory tsc

				 INNER JOIN tbCategory tc
				 ON tc.comp_id = tsc.comp_id
				 AND tc.cat_id = tsc.cat_id


				 WHERE tc.comp_id = @comp_id
				 AND tc.cat_id = @cat_id
				 AND tsc.subcat_id =@subcat_id)

		END		[params10],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 73
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params11],
		CASE @brand_id  WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tb.brand_desc
				 FROM tbBrand tb
					WHERE tb.comp_id = @comp_id
					AND  tb.brand_id = @brand_id )
		END		[params12],




		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 371
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params13],
		CASE @pres_id  WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tp.pres_desc
				 FROM tbPresentation tp
					WHERE tp.comp_id = @comp_id
					AND  tp.pres_id = @pres_id )
		END		[params14],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1028
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params15],
		CASE @pres_id  WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tc2.color_desc
				 FROM tbcolor tc2
				WHERE tc2.comp_id = @comp_id
				AND  tc2.color_id = @color_id )


		END		[params16]






GO








