CREATE PROCEDURE [dbo].[spItemComposition_New_getReport]

	(
		@comp_id		INT,
		@lang_id		INT,
		@page_id		INT,

		@item_id        INT,
		@color_id		INT,
		@guid			VARCHAR(50), --CF DE ITEMS
		@bra_id			INT,
		@intBranch4Lang int
   )


AS
SET NOCOUNT ON

/*
DECLARE @comp_id		INT,
		@lang_id		INT,
		@page_id		INT,

		@item_id        INT,
		@color_id		INT,

		@bra_id			INT


SELECT  @comp_id		=1,
		@lang_id		=2,
		@page_id		=10065,

		@item_id		= -1,
		@color_id		= -1,

		@bra_id			=-1

*/

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------


DECLARE @fun_id INT
SET     @fun_id = 1


SELECT	ti.item_desc			[item_desc],
		ti2.item_desc			[item_desc2],
		tic.icomp_qty			[item_qty],

		tc.color_desc			[color_desc]



FROM tbItemComposition tic

INNER JOIN         tbItem ti
ON  ti.comp_id = tic.comp_id
AND ti.item_id = tic.item_id


		INNER JOIN @tblComplexFilter_Items		tempITEM
		ON tempitem.item_id				= ti.item_id

INNER JOIN		   tbItem ti2
ON  ti2.comp_id = tic.comp_id
AND ti2.item_id = tic.item_id_1

INNER JOIN		    tbColor tc
ON  tc.comp_id   = tic.comp_id
AND tc.color_id  = tic.color_id

WHERE ti.comp_id = @comp_id
AND  (@item_id = -1     or ti.item_id      = @item_id)
AND  (@color_id = -1    or tic.color_id    = @color_id)

ORDER BY ti.item_desc


/************************************************************************************************************/
/* devolución de parámetros recibidos */

exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

SELECT	(SELECT top 1 tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id   = 103
      	 and   t.[page_id] = @related_page_id
      	 and   t.[type_id] = 1					) [params1],

      		CASE @item_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				( SELECT

						ti.item_desc
						FROM tbItem ti

			WHERE  ti.comp_id = @comp_id
			AND ti.item_id = @item_id)
		END									[Params2],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1028
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[Params3],

		CASE @color_id  WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tc2.color_desc
				 FROM tbcolor tc2
				WHERE tc2.comp_id = @comp_id
				AND  tc2.color_id = @color_id )
		END		[Params4]

/**************************************************************************************************************/
GO








create PROCEDURE [dbo].[spItemComposition_UpdateData]
(
		@comp_id			Int,
		@Item_id			Int,
		@Item_id_1			Int,
		@icomp_qty			decimal (19,7),
		@color_id			Int
)
as

set nocount on

/*
Declare @comp_id			Int,
		@Item_id			Int,
		@Item_id_1			Int,
		@icomp_qty			decimal (19,7),
		@color_id			Int

Select @comp_id				= 1,
	   @Item_id			    = 232,
	   @Item_id_1			= 238,
	   @iasso_qty			= '10,0'

*/

Update tbItemComposition
Set  icomp_qty =  @icomp_qty

Where comp_id   = @comp_id
