and   item_id_1 = @Item_id_1
And   color_id  = @color_id


GO







CREATE PROCEDURE [dbo].[spItemComposition_validateData]
(
	@comp_id		int,
	@origen			Int,
	@destino		Int,
	@level			Int,
	@return_value	Int Output
)
as
set nocount on


/*
Declare		@comp_id	int,
			@origen Int,
			@destino Int,
			@level	Int,
			@return_value Int
select		@comp_id	=1,
			@origen		=277,
			@destino	=229,
			@level		=0,
			@return_value = 0
*/


Set @level = @level + 1

-- -----------------------
-- Para Evitar StackFault
If @level > 30
Begin
    Return
End
-- -----------------------

--select		@level ,@origen,	@destino


If Exists (Select 1 From tbItemComposition tic
           Where tic.comp_id	= @comp_id
           And	 tic.item_id	= @origen
           And   tic.item_id_1	= @destino
           And    @level		= 1			 )

	Begin

		-- esta condición es para evitar duplicados
		Set @return_value = 2
		--Select 33

	End

Else

	Begin

		If Exists (Select 1 From tbItemComposition tic
				   Where tic.comp_id	= @comp_id
				   And	 tic.item_id	= @destino
				   And   tic.item_id_1	= @origen )

			begin
				--esta condición es cuando se encuentra que algún origen es parte del destino
				Set @return_value = 1
				--Select 1

			End

		Else

			Begin

				Declare @lorigen  Int,
						@lret_val Int
				Select  @lret_val = 0

				Declare @varCursor Cursor
				Set @varCursor = Cursor for
					Select	tic.item_id_1
					From	tbItemComposition tic
					Where	tic.comp_id = @comp_id
					And		tic.item_id = @destino

				Open @varCursor
				--Select 2

				Fetch  @varCursor Into @lorigen

				While @@FETCH_STATUS = 0 And @lret_val = 0
				Begin

					--Select @lorigen
					Exec spItemComposition_validateData
						@comp_id,
						@origen,
						@lorigen,
						@level,
						@return_value = @lret_val Output

					Fetch  @varCursor Into @lorigen

				End

				Close @varCursor
				Deallocate @varCursor

				Set @return_value = @lret_val

			End

	End








GO




CREATE PROCEDURE [dbo].[spItemComposition2_getReport]

	(
		@comp_id				INT,
		@lang_id				INT,
		@page_id				INT,

		@guid					VARCHAR(50),
		@color_id				INT,
		@list_id				INT,

		@GastosFijos			decimal(19,4),
		@ImpGanancias			decimal(19,4),
		@ImpIBrutos				decimal(19,4),
		@ImpSegeHigiene			decimal(19,4),
		@ComisionxVtas			decimal(19,4),
		@ComisionIndirecta		decimal(19,4),
		@Varios					decimal(19,4),
		@CoeficientePrecioVC	decimal(19,4),
		@UtilidadAcumulada		decimal(19,4),
		@item_id_labor			INT,
		@prli_id				INT,
		@DescuentoGral			decimal(19,4),
		@DescuentoFijo			decimal(19,4),
		@bra_id					INT,
		@intBranch4Lang			int
   )


AS
SET NOCOUNT ON



BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


---------------------------------------------------------------------------
---- Parametros de Prueba
---------------------------------------------------------------------------
/*
DECLARE @comp_id				INT,
		@lang_id				INT,
		@page_id				INT,

		@guid					VARCHAR(50),
		@color_id				INT,
		@list_id				INT,

		@GastosFijos			decimal(19,4),
		@ImpGanancias			decimal(19,4),
		@ImpIBrutos				decimal(19,4),
		@ImpSegeHigiene			decimal(19,4),
		@ComisionxVtas			decimal(19,4),
		@ComisionIndirecta		decimal(19,4),
		@Varios					decimal(19,4),
		@CoeficientePrecioVC	decimal(19,4),
		@UtilidadAcumulada		decimal(19,4),
		@item_id_labor			INT,
		@prli_id				INT,
		@DescuentoGral			decimal(19,4),
		@DescuentoFijo			decimal(19,4),
		@bra_id					INT,
		@intBranch4Lang			int


SELECT  @comp_id		=1,
		@lang_id		=2,
		@page_id		=10083,

		@guid			= '3F2504E0-4F89-11D3-9A0C-0305E82C3301',
		@color_id		= -1,

		@list_id		= 1,
		@prli_id		= 1,

		@GastosFijos			= 117,
		@ImpGanancias			= 5.25,
		@ImpIBrutos				= 0,
		@ImpSegeHigiene			= 1,
		@ComisionxVtas			= 4.70,
		@ComisionIndirecta		= 0.68,
		@Varios					= 0.71,
		@CoeficientePrecioVC	= 0.7766,
		@UtilidadAcumulada		= 10,
		@DescuentoGral			= 47,
		@DescuentoFijo			= 5,

		@item_id_labor	= 489,
		@bra_id			= 1


drop table #tmp
drop table #tmp2

*/
---------------------------------------------------------------------------
----
---------------------------------------------------------------------------


	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
				  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------




DECLARE @fun_id INT
SET     @fun_id = 1


	SELECT	ti.item_desc										[item_desc],
			ti2.item_desc										[item_desc2],
			tc.color_desc										[color_desc],
			isnull(tic.icomp_qty,0)								[item_qty],
			isnull(ticl.coslis_price,0)							[coslis_price],
			isnull(ticl.coslis_price * tic.icomp_qty,0)			[item_labor],
			ti.item_id											[item_id],
			isnull(ti.item_code,'')								[item_code],
			isnull(ticl.coslis_price,0)							[prli_price]


	into #tmp

	FROM tbItemComposition										tic		WITH (NOLOCK)

	INNER JOIN tbItem											ti		WITH (NOLOCK)
	ON  ti.comp_id   = tic.comp_id
	AND ti.item_id   = tic.item_id

	INNER JOIN tbItem											ti2		WITH (NOLOCK)
	ON  ti2.comp_id	 = tic.comp_id
	AND ti2.item_id	 = tic.item_id_1

	INNER JOIN tbColor											tc		WITH (NOLOCK)
	ON  tc.comp_id   = tic.comp_id
	AND tc.color_id  = tic.color_id

	LEFT JOIN tbItemCostList									ticl	WITH (NOLOCK)
	ON  ticl.comp_id	= tic.comp_id
	And ticl.coslis_id	= @list_id
	AND ticl.item_id	= ti2.item_id

	LEFT JOIN tbPriceListItems									tpli	WITH (NOLOCK)
	ON  tpli.comp_id	= ti2.comp_id
	AND tpli.prli_id	= @prli_id
	AND tpli.item_id	= ti2.item_id

	LEFT JOIN tbCategory										tcc		WITH (NOLOCK)
	ON  tcc.comp_id		= ti.comp_id
	AND tcc.cat_id		= ti.cat_id

	LEFT JOIN tbSubCategory										tsc		WITH (NOLOCK)
	ON  tsc.comp_id		= ti.comp_id
	AND tsc.subcat_id	= ti.subcat_id

	INNER JOIN @tblComplexFilter_Items							tempITEM
	ON	tempitem.item_id = ti.item_id


	WHERE ti.comp_id = @comp_id
	--AND  (@item_id  = -1    or ti.item_id   = @item_id)
	AND  (@color_id = -1    or tic.color_id = @color_id)
	AND  (ti.bra_id = @bra_id or ( ti.bra_id is null))
	--AND   tic.item_id_1 = @item_id_labor
	AND	  ti2.item_id <> @item_id_labor

	order by tcc.cat_desc,tsc.subcat_desc, ti2.item_desc



select * from #tmp



/************************************************************************************************************/
/* devolución de parámetros recibidos */

exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

--SELECT	(SELECT top 1 tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
--      	 WHERE t.ctrl_id   = 103
--      	 and   t.[page_id] = @related_page_id
--      	 and   t.[type_id] = 1					) [params1],
--
--    		CASE @item_id WHEN -1 THEN
--				(SELECT		tut.utexts_desc
--					FROM	tbsysUniqueTexts tut
--					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
--			ELSE
--				( SELECT
--
--						ti.item_desc
--						FROM tbItem ti
--
--			WHERE  ti.comp_id = @comp_id
--			AND ti.item_id = @item_id)
--		END									[Params2],

SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1028
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[Params3],

		CASE @color_id  WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tc2.color_desc
				 FROM tbcolor tc2
				WHERE tc2.comp_id = @comp_id
				AND  tc2.color_id = @color_id )
		END		[Params4],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1024
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],

		(SELECT ticln.coslis_desc FROM tbItemCostListName ticln

		 WHERE ticln.comp_id = @comp_id
		  AND  ticln.coslis_id= @list_id)	                      [params6],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1994
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

		 @GastosFijos [params8],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1995
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

		 @ImpGanancias [params10],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1996
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],

		 @ImpIBrutos [params12],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1997
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],

		 @ImpSegeHigiene [params14],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1998
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],

		 @ComisionxVtas [params16],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1999
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params17],

		 @ComisionIndirecta [params18],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 2000
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params19],

		 @Varios [params20],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 2001
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params21],

		 @CoeficientePrecioVC [params22],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 2002
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params23],

		 @UtilidadAcumulada [params24],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 2004
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params25],

		  	CASE @item_id_labor  WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
			ELSE(SELECT 	ti.item_desc FROM tbItem ti
				  WHERE  ti.comp_id = @comp_id
				  AND ti.item_id = @item_id_labor)end [params26],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 109
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params27],

		(SELECT tpl.prli_desc FROM tbPriceList tpl

		 WHERE tpl.comp_id = @comp_id
		  AND  tpl.prli_id= @prli_id)	                      [params28],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 3190
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params29],

		 @DescuentoGral [params30],

		 	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 3191
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params31],

		 @DescuentoFijo [params32]






/**************************************************************************************************************/



-- " Costos Totales"


-- se calcula el costo,cantidad y precio de la mano de obra del item_id
-- para mostrar en el subreporte


SELECT	temp.item_id,
	    temp.item_desc																															[item_desc],

		sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id) * dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id)		[SubTotal],

		dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)				[GastosFijos],

		ISNULL(sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos),0)																			[CostoDeProd],

		ISNULL((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC),0)									[PreciodeVtaContado],

		ISNULL((((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC)) * @ImpGanancias) /100	,0)			[ImpuestoGanancias],

		ISNULL((((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC)) * @ImpIBrutos) /100	,0)			[ImpuestoIngrBrutos],

		ISNULL((((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC)) * @ImpSegeHigiene) /100	,0)		[SeguridadeHigiene],

		ISNULL((((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC)) * @ComisionxVtas) /100	,0)		[ComisionVtas],

		ISNULL((((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC)) * @ComisionIndirecta) /100,0)		[ComisionIndirecta],

		ISNULL((((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC)) * @Varios) /100	,0)				[Varios],

		ISNULL(((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC)) * @UtilidadAcumulada/100	,0)		[UtilidadAcumulada],

		ISNULL(((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC)) - (((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC)) * @UtilidadAcumulada /100 ),0)	 [PrecioVtaSinUtilidad],


		(select ti.item_desc FROM tbItem ti
							 WHERE  ti.comp_id  = @comp_id
							 AND ti.item_id		= @item_id_labor)																																		[ManodeObra_desc],

		dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)																									[ManodeObra_Cantidad],
		dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id)																									[ManodeObra_Precio],
		dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id)	[ManodeObra_Costo],
		dbo.fnItemComposition2_ManodeObra_color(@comp_id,@bra_id,temp.item_id,@item_id_labor)																											[ManodeObra_Color],

		dbo.fnItemComposition2_ManodeObra_PriceList_Price_Parcial(@comp_id,@bra_id,temp.item_id,@item_id_labor,@prli_id,@DescuentoGral) - (dbo.fnItemComposition2_ManodeObra_PriceList_Price_Parcial(@comp_id,@bra_id,temp.item_id,@item_id_labor,@prli_id,@DescuentoGral)	* @DescuentoFijo / 100) [PreciodeLista],

		((dbo.fnItemComposition2_ManodeObra_PriceList_Price_Parcial(@comp_id,@bra_id,temp.item_id,@item_id_labor,@prli_id,@DescuentoGral) - (dbo.fnItemComposition2_ManodeObra_PriceList_Price_Parcial(@comp_id,@bra_id,temp.item_id,@item_id_labor,@prli_id,@DescuentoGral)	* @DescuentoFijo / 100) - ISNULL((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC),0) ) / dbo.fnNoZDiv(ISNULL((sum(temp.[item_labor])+ dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, temp.item_id,@item_id_labor,@list_id) + dbo.fnItemComposition2_ManodeObra_GastosFijos(@comp_id,@bra_id,temp.item_id,@item_id_labor,@list_id,@GastosFijos)) / dbo.fnNoZDiv(@CoeficientePrecioVC),0)) ) * 100  [DifPrecioListayContado],



		dbo.fnItemComposition2_ManodeObra_PriceList_Price(@comp_id,@bra_id,temp.item_id,@item_id_labor,@prli_id) [PL_Original]


	into #tmp2

	from #tmp temp

	INNER JOIN @tblComplexFilter_Items				tempITEM
	ON	tempitem.item_id = temp.item_id

group by temp.item_id,temp.item_desc


select * from #tmp2


declare @lSubTotalImpuestos decimal(19,4)

set @lSubTotalImpuestos = (select @ImpGanancias + @ImpIBrutos + @ImpSegeHigiene + @ComisionxVtas + @ComisionIndirecta + @Varios)


select  @lSubTotalImpuestos		[SubTotalImpuestos],
		@GastosFijos			[Params_GastosFijos],
		@ImpGanancias			[Params_ImpGanancias],
		@ImpIBrutos				[Params_ImpIBrutos],
		@ImpSegeHigiene			[Params_ImpSegeHigiene],
		@ComisionxVtas			[Params_ComisionxVtas],
		@ComisionIndirecta		[Params_ComisionIndirecta],
		@Varios					[Params_Varios],
		@CoeficientePrecioVC	[Params_CoeficientePrecioVC],
		@UtilidadAcumulada		[Params_UtilidadAcumulada],
		@DescuentoGral			[Params_DescuentoGral],
		@DescuentoFijo			[Params_DescuentoFijo]



END
GO






