CREATE  PROCEDURE [dbo].[spItemCostList_deleteData]
(
		@comp_id			INT,
		@coslis_id			INT
)
as


Delete	dbo.tbItemCostList	WITH (ROWLOCK)

where	comp_id	=	@comp_id
AND		coslis_id =	@coslis_id




GO






CREATE PROCEDURE [dbo].[spItemCostList_GetCombo]
(
	@comp_id			int
)

as
set nocount on

select		coslis_id		,
			coslis_price,
			coslis_price_aw

from		dbo.tbItemCostList

where		comp_id =	@comp_id

Order By	coslis_id















GO






CREATE PROCEDURE [dbo].[spItemCostList_getCount]
(
	@comp_id			int,
	@coslis_id			int
)
AS
set nocount on

SELECT (
		SELECT	COUNT(*)

		FROM	tbItemCostList tpli

		WHERE	tpli.comp_id	= @comp_id
		AND		tpli.coslis_id	= @coslis_id
		),
		(SELECT	tpl.coslis_desc

		FROM	tbItemCostListName tpl

		WHERE	tpl.comp_id		= @comp_id
		AND		tpl.coslis_id	= @coslis_id
		) [coslis_desc]

/*
SELECT	COUNT(*),
		tpl.coslis_desc

	FROM dbo.tbItemCostList tpli

		INNER JOIN tbItemCostListName tpl
		ON  tpl.coslis_id = tpli.coslis_id
		AND tpl.comp_id = tpli.comp_id


		WHERE	tpli.comp_id	= @comp_id
		AND		tpli.coslis_id	= @coslis_id

		GROUP BY tpl.coslis_desc
*/
GO






-- Mod. x MOS 09-2008

CREATE pROCEDURE [dbo].[spItemCostList_getDataById]
(
	@comp_id		as	int,
	@bra_id			as	int,
	@coslis_id		as	int,
	@item_id		as	INT,
	@stor_id		AS  INT
)
as

BEGIN



	Set Nocount On

	-- Si no se pone @coslis_id, trae la lista de costos x defecto de la sucursal.-
	If @coslis_id = -1
		Begin
			Select @coslis_id = coslis_id
				From	dbo.tbBranch
				Where	comp_id = @comp_id and
						bra_id  = @bra_id
		End

	-- Si hay definido un deposito y tiene asignada una lista de costos, sobreescribe a la de la sucursal.-
	IF @stor_id <> -1
		BEGIN
			Select @coslis_id = IsNull(coslis_id,@coslis_id)
				From	tbStorage ts
				Where	comp_id = @comp_id and
						stor_id = @stor_id
		END


	Select		ICL.coslis_price,
				ICL.coslis_price_aw,
				ICL.curr_id,
				CUR.curr_desc,
				ICL.coslis_lastUpdate

		From		dbo.tbItemCostList				ICL

					left join dbo.[tbsysCurrency]	CUR
					on CUR.[curr_id]	= ICL.[curr_id]

		Where		ICL.[comp_id]		= @comp_id
			and		ICL.[coslis_id]		= @coslis_id
			and     ICL.[item_id]		= @item_id


END














GO






-- Mod. x MOS 09-2008

CREATE pROCEDURE [dbo].[spItemCostList_getDataById4Association]
(
	@comp_id		as	int,
	@bra_id			as	int,
	@coslis_id		as	int,
	@item_id		as	INT,
	@stor_id		AS  INT
)
as

BEGIN



	Set Nocount On

	-- Truchada, me quiero ir

	IF EXISTS(	SELECT 1
					FROM tbItemAssociation tia
	          		WHERE	tia.comp_id = @comp_id AND
	          				tia.item_id = @item_id)
		BEGIN
			SELECT 'True' [Status]
		END
	ELSE
		BEGIN
			SELECT 'False' [Status]
		END



END














GO






-- Mod. x MOS 09-2008

CREATE pROCEDURE [dbo].[spItemCostList_getDataByIdfromVIEW]
(
	@comp_id		as	int,
	@bra_id			as	int,
	@coslis_id		as	int,
	@item_id		as	INT,
	@stor_id		AS  INT
)
as

BEGIN



	Set Nocount On






	-- Si no se pone @coslis_id, trae la lista de costos x defecto de la sucursal.-
	If @coslis_id = -1
		Begin
			Select @coslis_id = coslis_id
				From	dbo.tbBranch				WITH (NOLOCK)
				Where	comp_id = @comp_id and
						bra_id  = @bra_id
		End

	-- Si hay definido un deposito y tiene asignada una lista de costos, sobreescribe a la de la sucursal.-
	IF @stor_id <> -1
		BEGIN
			Select @coslis_id = IsNull(coslis_id,@coslis_id)
				From	tbStorage ts				WITH (NOLOCK)
				Where	comp_id = @comp_id and
						stor_id = @stor_id
		END





	Select		ICL.coslis_price,
				ICL.coslis_price_aw,
				ICL.curr_id,
				CUR.curr_desc


		From		dbo.vwItemCostList				ICL		WITH (NOLOCK)

					left join dbo.[tbsysCurrency]	CUR		WITH (NOLOCK)
					on CUR.[curr_id]	= ICL.[curr_id]


		Where		ICL.[comp_id]		= @comp_id
			and		ICL.[coslis_id]		= @coslis_id
			and     ICL.[item_id]		= @item_id


END














GO





