-- Create date: 03-2009
-- Description:	Actualiza CPP
-- =============================================

CREATE PROCEDURE [dbo].[spItemCostList_UpdateFromPurchase]
(
	@comp_id						As Int,
	@bra_id							As Int,
	@litem_id						As Int,				-- item_id
	@lit_qty						As Decimal(19,4),	-- qty Ingresada
	@lPrice							As Decimal(19,4),	-- Precio Ingresado
	@lcurr_id						As Int,				-- Moneda del Precio Ingresado
	@lstorePrevious					As Decimal(19,4),	-- Stock Anterior
	@AlternativeExchangeCurency		As Int,				-- Moneda del Tipo de Cambio Alternativo
	@AlternativeExchangeCurency2	As Int,				-- Moneda del Tipo de Cambio Alternativo
	@AlternativeExchange			As Decimal(38,15),    -- Tipo de Cambio Alternativo		-- MOS 03-2023: Decimal(19,4) a 38,15 x tema de cliente de german y sus putos costos en usd
	@fieldtype						as INT, --1:actualiza la lista bra_PurDoc_coslis_id de tbBranch		-- Si actualiza Primer Costo		**
											--2:actualiza la lista coslis_id_B			de tbBranch		-- Si actualiza Costo Alternativo	**
	@stor_id						AS INT		,
	@supp_id						AS INT,
	@user_id						AS INT
)
AS

BEGIN



	SET NOCOUNT ON


-- --------------------------------------------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------------------------------------------
	/*
	DECLARE 	@comp_id						As Int,
				@bra_id							As Int,
				@litem_id						As Int,				-- item_id
				@lit_qty						As Decimal(19,4),	-- qty Ingresada
				@lPrice							As Decimal(19,4),	-- Precio Ingresado
				@lcurr_id						As Int,				-- Moneda del Precio Ingresado
				@lstorePrevious					As Decimal(19,4),	-- Stock Anterior
				@AlternativeExchangeCurency		As Int,				-- Moneda del Tipo de Cambio Alternativo
				@AlternativeExchangeCurency2	As Int,				-- Moneda del Tipo de Cambio Alternativo
				@AlternativeExchange			As Decimal(19,4),    -- Tipo de Cambio Alternativo
				@fieldtype						INT --1:actualiza la lista bra_PurDoc_coslis_id de tbBranch
	SELECT		@fieldtype						= 2
	*/



-- --------------------------------------------------------------------------------------------------------


	-- --------------------------------------------------------------------------------------------------------
	-- Suma al stock previo todos los depositos que dice que se deben tener en cuenta para el calculo del costo ppp ademas del actual.
	-- --------------------------------------------------------------------------------------------------------
	DECLARE @decOtherStock4PPP AS DECIMAL(19,4)
	SET		@decOtherStock4PPP = 0
	SELECT  @decOtherStock4PPP = IsNull(SUM(ISNULL(tis.itst_cant,0)),0)
		FROM		tbItemStorage	tis		WITH (NOLOCK)
		INNER JOIN	tbStorage		ts		WITH (NOLOCK)
			ON		ts.comp_id = tis.comp_id
				AND ts.stor_id = tis.stor_id
		WHERE	tis.comp_id = @comp_id
			AND tis.stor_id <> @stor_id
			AND tis.item_id = @litem_id
			and IsNull(ts.stor_ever4AWCost,'false') = 'True'

	SET @lstorePrevious = ISNULL(@lstorePrevious,0) + ISNULL(@decOtherStock4PPP,0)
	-- --------------------------------------------------------------------------------------------------------

	-- ----------------------------------------------------------------------------------------------
	-- Obtiene la lista de costos a actualizar definidas en la SUCURSAL
	-- ----------------------------------------------------------------------------------------------
	Declare @coslis_id						As INT
	DECLARE @bitPPPOnlyCostIsMinor			AS BIT
	DECLARE @coslis_blockLastUpdate4Rules	AS BIT


	Select  @coslis_id = CASE
							WHEN @fieldtype  = 1 THEN bra_PurDoc_coslis_id
							ELSE					  tb.coslis_id_B
						 END,
			@coslis_blockLastUpdate4Rules	 =
						 CASE
						     WHEN @fieldtype = 1 THEN ISNULL(tb.bra_PurDoc_coslis_id_blockRules  ,'False')
						     ELSE					  ISNULL(tb.bra_PurDoc_coslis_id_B_blockRules,'False')
						 END
		From	tbBranch tb			WITH (NOLOCK)
		Where	tb.comp_id = @comp_id
		And		tb.bra_id  = @bra_id


	-- ------------------------------------------------------------------------------------------------------------
	-- ATENCION->!
	-- Si esta definida la lista de precios en el DEPOSITO de la transaccion, usa esa, sino usa la de la sucursal.!
	-- ------------------------------------------------------------------------------------------------------------
	SELECT @coslis_id =	ISNULL(
							CASE
								WHEN @fieldtype = 1 THEN ts.coslis_id_4Purchase
								ELSE ts.coslis_idB4Purchase
							END   ,@coslis_id)
		FROM tbStorage ts			WITH (NOLOCK)
		WHERE	ts.comp_id = @comp_id
			AND ts.stor_id = @stor_id
	-- ----------------------------------------------------------------------------------------------


	-- ------------------------------------------------------------------------------------------------------------
	-- ATENCION->!  MOS  2011-05
	-- Si esta definida la lista de precios en el Proveedor de la transaccion, usa esa, sino usa la Definida antes
	-- ------------------------------------------------------------------------------------------------------------
	IF NOT @supp_id IS NULL
	BEGIN

		SELECT @coslis_id =	ISNULL(
								CASE
									WHEN @fieldtype = 1 THEN ts.coslis_id_4Purchase
									ELSE ts.coslis_idB4Purchase
								END   ,@coslis_id)
			FROM tbSupplier ts			WITH (NOLOCK)
		WHERE	ts.comp_id = @comp_id
			AND ts.supp_id = @supp_id
	END
	-- ----------------------------------------------------------------------------------------------




	IF NOT (@coslis_id IS NULL)
		BEGIN

			-- ------------------------------------------------
			-- Si no esta dado de alta el Item, lo da de alta.-
			-- ------------------------------------------------
			If  not Exists (SELECT TOP 1  1
								From tbItemCostList	WITH (NOLOCK)
								Where	comp_id		= @comp_id		And
										coslis_id	= @coslis_id	And
										item_id		= @litem_id)
				Begin
					Declare @itemCurrency As Int
					Select @itemCurrency = ti.curr_id
						From	tbItem ti			WITH (NOLOCK)
						Where	ti.comp_id = @comp_id
							And ti.item_id = @litem_id

					Insert into tbItemCostList	WITH (ROWLOCK)
					(
						comp_id,
						coslis_id,
						item_id,
						coslis_price,
						coslis_price_aw,
						curr_id,
						coslis_blockLastUpdate4Rules
					)
					VALUES
					(
						@comp_id,
						@coslis_id,
						@litem_id,
						0,
						0,
						@itemCurrency,
						@coslis_blockLastUpdate4Rules
					)
				END



			-- ------------------------------------------------
			-- Obtiene la Moneda de la Lista de Costos a Actualizar
			-- ------------------------------------------------
			Declare @CostListCurrency As Int
			Declare @price_aw_Actual	 As Decimal(19,5)
			Select  @CostListCurrency = curr_id ,
					@price_aw_Actual  = coslis_price_aw
				From tbItemCostList ticl	WITH (NOLOCK)
				Where	ticl.comp_id	= @comp_id
					And ticl.coslis_id	= @coslis_id
					AND ticl.item_id	= @litem_id


			-- -----------------------------------------------------------------------------
			-- Si esta en TRUE solo debe ponderar si el nuevo costo es MENOR al PPP Actual.-
			-- -----------------------------------------------------------------------------
			select @bitPPPOnlyCostIsMinor = IsNull(ticln.coslis_PPPOnlyIfMinor,'False')
				FROM tbItemCostListName ticln			WITH (NOLOCK)
				WHERE	ticln.comp_id	= @comp_id
					AND ticln.coslis_id = @coslis_id
			-- -----------------------------------------------------------------------------


			-- ------------------------------------------------
			-- Calcula el Precio Nuevo de Costo en la moneda que posee la lista de costos.
			-- ------------------------------------------------
			Declare @PriceInCostListCurrency As Decimal(19,5)

			Set	   @PriceInCostListCurrency = dbo.fnGetExchange2(	@comp_id,
																	@lPrice,
																	@lcurr_id,
																	@CostListCurrency,
																	@AlternativeExchangeCurency,
																	@AlternativeExchangeCurency2,
																	@AlternativeExchange,
																	'false'
																)




			-- ------------------------------------------------
			-- Calcula el Costo Promedio Ponderado.
			-- ------------------------------------------------
			Declare @price_aw As Decimal(19,5)
			Set @price_aw = ( (@lstorePrevious * @price_aw_Actual) + (@lit_qty * @PriceInCostListCurrency) )
							/ dbo.fnNoZDiv( @lstorePrevious + @lit_qty)


			-- ------------------------------------------------
			-- MOS 06-2012
			-- Si @bitPPPOnlyCostIsMinor = 'TRUE y el costo actual es MAYOR al de la ultima compra
			-- NO PONDERO sino que pongo el PPP igual al de ultima compra.!!!!!
			-- ------------------------------------------------
			IF @bitPPPOnlyCostIsMinor = 'True'
				BEGIN
					IF	(SELECT TOP 1 IsNull(ticl.coslis_price,0)
							FROM tbItemCostList ticl
								WHERE	ticl.comp_id		= @comp_id
									AND ticl.coslis_id		= @coslis_id
									AND ticl.item_id		= @litem_id
						) < @PriceInCostListCurrency
						BEGIN
							SET @price_aw = @PriceInCostListCurrency
						END
				END
			-- ------------------------------------------------


			-- ------------------------------------------------
			-- Graba el nuevo costo y cost Promedio Ponderado.-
			-- ------------------------------------------------
			Update tbItemCostList	WITH (ROWLOCK)
			   SET
				coslis_price					= @PriceInCostListCurrency,
				coslis_price_aw					= @price_aw,
				coslis_blockLastUpdate4Rules	= @coslis_blockLastUpdate4Rules,
				user_id_lastUpdate				= @user_id
			WHERE	comp_id		= @comp_id
				AND coslis_id	= @coslis_id
				AND item_id		= @litem_id

		END

END
GO






CREATE PROCEDURE [dbo].[spItemCostListName_GetCombo]
(
	@comp_id			int
)

as
set nocount on

select		coslis_id		[Id],
			coslis_desc		[desc]

from		dbo.tbItemCostListName

where		comp_id =	@comp_id

Order By	coslis_desc















GO






create PROCEDURE [dbo].[spItemCostListName_GetCombo4Import]
(
	@comp_id			int
)

as
set nocount on

select		coslis_id		[Id],
			coslis_desc		[desc]

from		dbo.tbItemCostListName

where		comp_id						=	@comp_id	AND
			coslis_isAvailable4Import	= 'True'

