CREATE PROCEDURE [dbo].[spItemCustomerDiscountRelation_Process_Auto]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@cust_id					INT,
	@disc_id					INT,

	@rdc_discountPercentage		DECIMAL(19,2),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT,
	@item_code   				NVARCHAR(50)





)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@cust_id					INT,
	@disc_id					INT,

	@rdc_discountPercentage		DECIMAL(19,2),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT,
	@item_code   				NVARCHAR(50)

SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id4session						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,

	@item_code					='D1',
	@cust_id						= 24294 ,
	@disc_id					= 1 ,

	@rdc_discountPercentage	= 99,

	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 10

	*/
---------------------------------------------------------------------------------

SET NOCOUNT ON
SET DATEFORMAT 'YMD'


BEGIN


	--Recuperamos el item_id mediante el codigo
	DECLARE @litem_id AS INT

	SELECT
		@litem_id = ti.item_id

		FROM tbitem  ti	WITH (NOLOCK)

		WHERE	ti.comp_id		= @comp_id		AND
				ti.item_code	= @item_code


		declare @return_value	INT
		set	@return_value		= 1

				BEGIN TRY


					INSERT INTO tbItemCustomerDiscountRelation
					(
						comp_id,
						item_id,
						cust_id,
						disc_id,
						rdc_discountPercentage,
						rdc_disabled
					)
					VALUES
					(
						@comp_id,
						@litem_id,
						@cust_id,
						@disc_id,
						@rdc_discountPercentage,
						0
					)

					--set	@return_value = IDENT_CURRENT('tbItemCustomerDiscountRelation')   -- @@identity

					END TRY
					BEGIN CATCH
						set	@return_value = 0
					END CATCH



END


















GO





--------------------------------------------------------------------------
-- Date  : 16/01/2020
-- Author: GA
-- Data  :Importacion de Descuentos de Artículos para Clientes - VALIDATE data
--------------------------------------------------------------------------

create PROCEDURE [dbo].[spItemCustomerDiscountRelation_Process_Auto_Validate]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@cust_id					INT,
	@disc_id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@item_code					NVARCHAR(50)




)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cust_id					INT,
	@custb_name					NVARCHAR(100),
	@custb_address				NVARCHAR(150),
	@custb_city					NVARCHAR(60),
	@custb_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@ss_id						INT,
	@sm_id						INT,
	@dl_id						INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------

SET NOCOUNT ON
SET DATEFORMAT 'YMD'

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''



	------CLIENTE-----------------------------------------------------------------------------------------------------------
	if	@cust_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Cliente'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT	tc.cust_id
			               FROM		tbCustomer		tc		WITH (NOLOCK)
			               WHERE	tc.comp_id		= @comp_id AND
									tc.cust_id		= @cust_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Cliente es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------


	--------ITEM-----------------------------------------------------------------------------------------------------------
	--if	@item_id	= -1
	--	BEGIN
	--		SET	@bolIsOK		= 'False'
	--		SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Artículo'
	--	END
	--ELSE
	--	BEGIN
	--		IF NOT EXISTS (SELECT	tc.item_id
	--		               FROM		tbitem		tc		WITH (NOLOCK)
	--		               WHERE	tc.comp_id		= @comp_id AND
	--								tc.item_id		= @item_id)
	--			BEGIN
	--				SET	@bolIsOK		= 'False'
	--				SET @errormessage	= @errormessage + '---' + 'El ID de Artículo es incorrecto'
	--			END
	--	END

	-------------------------------------------------------------------------------------------------------------------------



		------Codigo del articulo  -----------------------------------------------------------------------------------------------------------
	if	@item_code	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Código del Artículo'
		END
	ELSE
		BEGIN

			IF not EXISTS (SELECT top 1 ti.item_id
    								FROM tbitem ti								WITH (NOLOCK)
    								WHERE	ti.comp_id				= @comp_id AND
											ti.item_code			= @item_code
							)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'No existe un Artículo para el Código del Artículo ingresado'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------





	------DESCUENTO-----------------------------------------------------------------------------------------------------------
	if	@disc_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Descuento'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT	tc.disc_id
			               FROM		tbDiscount 		tc		WITH (NOLOCK)
			               WHERE	tc.comp_id		= @comp_id AND
									tc.disc_id		= @disc_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Descuento es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------






	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO




--------------------------------------------------------------------------
-- Date  : 16/01/2020
-- Author: GA
-- Detail : Al finalizar el proceso de importacion se muestra en una grilla que registros fueron dados de alta y los que no.
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
create PROCEDURE [dbo].[spItemCustomerDiscountRelation_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN



	SELECT
			--isnull(tc.custb_name,'')								[cust_name],
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO







