)
as
set nocount ON

/*

declare	 @comp_id			Int,
		 @item_id			Int,
		 @cust_id			Int


select	 @comp_id		= 1,
		 @item_id		=239,
		 @cust_id		=264
*/
Delete FROM tbItemDescription4Customer

Where comp_id   = @comp_id
And   cust_id   = @cust_id
And   item_id   = @Item_id



GO







CREATE PROCEDURE [dbo].[spItemDescription4Customer_getDataByFilters]
(

		@comp_id								Int,
		@cust_id								Int,
		@item_id								Int
)
as
set nocount ON

/*

declare	 @comp_id			Int,
		 @item_id			Int,
		 @cust_id			Int


select	 @comp_id		= 1,
		 @item_id		=239,
		 @cust_id		=264
*/


SELECT  ' ' [ ], ' ' [ ],
		tc.cust_name,
		ti.item_desc,
		tidc.id4c_code,
		tidc.id4c_desc,
		tidc.id4c_price,
		tc2.curr_desc,
		Convert(Varchar,tidc.cust_id) + ' - ' + Convert(Varchar,tidc.item_id) [ID]

FROM	tbItemDescription4Customer tidc

		Inner Join tbItem ti
		On	ti.comp_id	= tidc.comp_id
		And ti.item_id	= tidc.item_id

		Inner Join tbCustomer tc
		On  tc.comp_id = tidc.comp_id
		And tc.cust_id = tidc.cust_id

		LEFT JOIN tbsysCurrency tc2
		ON tc2.curr_id = tidc.curr_id

WHERE	tidc.comp_id							= @comp_id
AND		(@cust_id   = -1 or tidc.cust_id		= @cust_id)
AND		(@item_id   = -1 or tidc.item_id		= @item_id)
GO








CREATE PROCEDURE [dbo].[spItemDescription4Customer_getDataById]
(
		@comp_id			Int,
		@cust_id			Int,
		@Item_id			Int
)
as

set nocount on

/*
Declare @comp_id			Int,
		@Item_id			Int,
		@Item_id_1			Int


Select @comp_id				= 1,
	   @Item_id			    = 231,
	   @Item_id_1			= 264

		*/


Select  tidc.comp_id,
		tidc.cust_id,
		tidc.item_id,
		tidc.id4c_code,
		tidc.id4c_desc,
		tidc.id4c_price,
		ti.item_code,
		ti.item_desc,
		tc.cust_name,
		tidc.curr_id

From dbo.tbItemDescription4Customer tidc

Inner Join tbItem ti
On  ti.comp_id = tidc.comp_id
And ti.item_id = tidc.item_id

Inner Join tbCustomer tc
On tc.comp_id  = tidc.comp_id
And tc.cust_id = tidc.cust_id

Where tidc.comp_id    = @comp_id
And   tidc.cust_id    = @cust_id
And   tidc.item_id    = @Item_id



GO







CREATE PROCEDURE [dbo].[spItemDescription4Customer_InsertData]
(

		@comp_id								Int,
		@cust_id								Int,
		@item_id								Int,
		@id4c_code								Varchar(50),
		@id4c_desc								Varchar(200),
		@id4c_price								Decimal(19,6),
		@curr_id								INT
)
as
set nocount ON

/*

declare	 @comp_id			Int,
		 @item_id			Int,
		 @cust_id			Int


select	 @comp_id		= 1,
		 @item_id		=239,
		 @cust_id		=264
*/


Insert into tbItemDescription4Customer
(
  comp_id,
