--- Date : 28/10/2014
--- Desc : Item EAN - Getdatabyfilters
------------------------------------------------------------

CREATE PROCEDURE [dbo].[spItemEAN_getDataByFilters]
(

		@comp_id								Int,
		@lang_id								INT,
		@item_id								Int,
		@option									INT,
		@ie_ean									nvarchar(50)

)
as
set nocount ON

--------------------------------------------------------
-------------parametros de prueba-----------------------
--------------------------------------------------------
/*
declare		@comp_id								Int,
			@lang_id								INT,
			@item_id								Int,
			@option									INT,
			@ie_ean									nvarchar(50)


select		@comp_id								= 1,
			@lang_id								= 2,
			@item_id								= 229,
			@option									= -1,
			@ie_ean									= ''

*/
--------------------------------------------------------
BEGIN



	SELECT
		' '											[ ],
		' '											[ ],
		ti.item_code  + ' - ' +  ti.item_desc		[item_desc],
		tie.ie_ean									[ie_ean],
		tov.optval_desc								[ie_isDUC],
		tie.ie_DUNQty								[ie_DUNQty],
		tovForce2InternalNewEAN.optval_desc			[ie_Force2InternalNewEAN],
		tovisInternalEAN.optval_desc				[ie_isInternalEAN],
		tie.ie_id									[ID]


		FROM	tbItemEAN											tie					WITH (NOLOCK)

		Inner Join tbItem											ti					WITH (NOLOCK)
		On  ti.comp_id = tie.comp_id
		And ti.item_id = tie.item_id

		inner join tbsysOptionsValues								tov					WITH (NOLOCK)
		on  tov.optval_class		= 137
		and tov.lang_id				= @lang_id
		and tov.optval_id			= isnull(tie.ie_isDUC,0)

		inner join tbsysOptionsValues								tovForce2InternalNewEAN				WITH (NOLOCK)
		on  tovForce2InternalNewEAN.optval_class	= 137
		and tovForce2InternalNewEAN.lang_id			= @lang_id
		and tovForce2InternalNewEAN.optval_id		= isnull(tie.ie_Force2InternalNewEAN,0)

		inner join tbsysOptionsValues								tovisInternalEAN					WITH (NOLOCK)
		on  tovisInternalEAN.optval_class		= 137
		and tovisInternalEAN.lang_id			= @lang_id
		and tovisInternalEAN.optval_id			= isnull(tie.ie_isInternalEAN,0)



		WHERE	(tie.comp_id = @comp_id)
		AND		(@item_id   = -1 or tie.item_id    = @item_id)
		AND		(@option = -1 )												 OR
				(@option = 0 AND tie.ie_ean LIKE			  @ie_ean + '%') OR
				(@option = 1 AND tie.ie_ean LIKE		'%' + @ie_ean + '%') OR
				(@option = 2 AND tie.ie_ean =				  @ie_ean)		 OR
				(@option = 3 AND tie.ie_ean <>				  @ie_ean)		 OR
				(@option = 4 AND tie.ie_ean NOT LIKE	'%' + @ie_ean + '%')




END

GO





-----------------------------------------------------------
--- Date : 28/10/2014
--- Desc : Item EAN - Getdataby
------------------------------------------------------------



CREATE PROCEDURE [dbo].[spItemEAN_getDataById]
(


		@comp_id			Int,
		@ie_id				INT


)
as

set nocount on

--------------------------------------------------------
-------------parametros de prueba-----------------------
--------------------------------------------------------
/*


Declare @comp_id			Int,
		@ie_id				Int


Select @comp_id				= 1,
	   @ie_id			    = 2


*/
--------------------------------------------------------
BEGIN

		Select tie.comp_id,
			   tie.item_id,
			   ti1.item_code,
			   ti1.item_desc,
			   tie.ie_ean,
			   isnull(tie.ie_isDUC,'FALSE')					[ie_isDUC],
			   isnull(tie.ie_DUNQty,0)						[ie_DUNQty],
			   isnull(tie.ie_Force2InternalNewEAN,'false')  [ie_Force2InternalNewEAN],
			   isnull(tie.ie_isInternalEAN,'false')			[ie_isInternalEAN]


		FROM tbItemEAN								tie

		Inner Join tbItem ti1
		On  ti1.comp_id = tie.comp_id
		And ti1.item_id = tie.item_id



		Where tie.comp_id    = @comp_id
		And   tie.ie_id		 = @ie_id







END
GO




-- NO SE USA , SE USA [spItemEAN_InsertData_ItemChild]
CREATE PROCEDURE [dbo].[spItemEAN_InsertChildEanData]
(
	@comp_id	INT,
	@item_id	INT,
	@size_id	INT,
	@color_id	INT,
	@item_ean	VARCHAR(50)
)
AS
	SET NOCOUNT ON

		BEGIN

			-- --------------------------------------
			-- TESTING
			-- --------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@item_id	INT,
					@size_id	INT,
					@color_id	INT,
					@item_ean	VARCHAR(50)
			*/
			-- --------------------------------------

			DECLARE	@lItem_ID	INT

			--RECUPERAMOS EL ID DEL HIJO PARA PODER CARGAR EL ITEM_EAN CORRESPONDIENTE
			SELECT @lItem_ID = tiscr.item_id_child

			FROM tbItemSizeColorRelation		tiscr

			WHERE	tiscr.comp_id	= @comp_id	AND
					tiscr.item_id	= @item_id	AND
					tiscr.color_id	= @color_id AND
					tiscr.size_id	= @size_id

			--SI NO EXISTE EL ARTICULO CON ESE EAN YA CARGADO, LO CARGAMOS
			IF NOT EXISTS (SELECT 1
						   FROM tbItemEAN					tie
						   WHERE	tie.comp_id = @comp_id	AND
									tie.item_id = @lItem_ID AND
									tie.ie_ean	= @item_ean)
				BEGIN

					INSERT INTO tbItemEAN
					(
						comp_id,
						-- ie_id -- this column value is auto-generated,
						item_id,
						ie_ean,
						ie_isDUC,
						ie_DUNQty,
						ie_Force2InternalNewEAN,
						ie_isInternalEAN
					)
					VALUES
					(
						@comp_id,
						@lItem_ID,
						@item_ean,
						'False',
						NULL,
						'False',
						'False'
					)

				END


		END

GO





