CREATE PROCEDURE [dbo].[spItemEAN_InsertData_ItemChild]
(
	@comp_id	INT,
	@item_code	NVARCHAR(50),
	@size_code	NVARCHAR(50),
	@color_code	NVARCHAR(50),
	@Ean		VARCHAR(50)
)
AS


SET NOCOUNT ON

BEGIN

	-- --------------------------------------
	-- TESTING
	-- --------------------------------------
/*
		DECLARE
					@comp_id	INT,
					@item_code	NVARCHAR(50),
					@size_code	NVARCHAR(50),
					@color_code	NVARCHAR(50),
					@Ean		VARCHAR(50)

		select		@comp_id	=1,
					@item_code	='F1',
					@size_code	='S',
					@color_code	='4AZ',
					@Ean		='lalalalala'
	*/
	-- --------------------------------------


			DECLARE		@litem_id		INT,
						@lsize_id		INT,
						@lcolor_id		INT,
						@litem_id_child	INT

			SELECT		@litem_id  = -1,
						@lsize_id  = -1,
						@lcolor_id = -1


			SELECT @litem_id = ti.item_id
				FROM tbItem ti									WITH (NOLOCK)
				WHERE	ti.comp_id		= @comp_id		AND
						ti.item_code	= @item_code

			SELECT @lsize_id = ts.size_id
			    FROM tbSize ts									WITH (NOLOCK)
				WHERE	ts.comp_id	    = @comp_id			AND
						ts.size_code    = @size_code



			SELECT @lcolor_id = tc.color_id
			    FROM tbColor tc									WITH (NOLOCK)
				WHERE	tc.comp_id		= @comp_id			AND
						tc.color_code	= @color_code


			SELECT @litem_id_child = tiscr.item_id_child
				FROM tbItemSizeColorRelation		tiscr		WITH (NOLOCK)
				WHERE	tiscr.comp_id	= @comp_id	 AND
						tiscr.item_id	= @litem_id	 AND
						tiscr.color_id	= @lcolor_id AND
						tiscr.size_id	= @lsize_id



			IF @litem_id_child IS NOT NULL

			BEGIN

				IF NOT EXISTS (SELECT TOP 1 1
								   FROM tbItemEAN					tie		WITH (NOLOCK)
								   WHERE	tie.comp_id = @comp_id			AND
											--tie.item_id = @litem_id_child	AND		tbItemEAN Tiene un indice UNIQUE de EAN !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
											tie.ie_ean	= @Ean)
				BEGIN

					INSERT INTO tbItemEAN
					(
						comp_id,
						item_id,
						ie_ean,
						ie_isDUC,
						ie_DUNQty,
						ie_Force2InternalNewEAN,
						ie_isInternalEAN
					)
					VALUES
					(
						@comp_id,
						@litem_id_child,
						@Ean,
						'False',
						NULL,
						'False',
						'False'
					)

				END


			END





END

GO





