--------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spItemEAN_Process_Auto]
(
	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_code					NVARCHAR(50),
	@ie_ean						NVARCHAR(50),
	@ie_isDUC					BIT,
	@ie_DUNQty					INT,
	@ie_Force2InternalNewEAN	BIT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT



)
AS


---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

		@item_code					NVARCHAR(50),
	@ie_ean						NVARCHAR(50),
	@ie_isDUC					BIT,
	@ie_DUNQty					INT,
	@ie_Force2InternalNewEAN	BIT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT,
	@bolIsOK					BIT




SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,
	@item_code					= '305werewrew',
	@ie_ean						='66669911caca99ho62625',
	@ie_isDUC					= 1,
	@ie_DUNQty					= 1,
	@ie_Force2InternalNewEAN	= 0,

	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 666

*/
---------------------------------------------------------------------------------


set nocount on


BEGIN

	--Recuperamos el item_id mediante el codigo
	DECLARE @litem_id AS INT

	SELECT
		@litem_id = ti.item_id

		FROM tbitem  ti	WITH (NOLOCK)

		WHERE	ti.comp_id		= @comp_id		AND
				ti.item_code	= @item_code

	declare @return_value	INT
		BEGIN TRY


			INSERT INTO tbItemEAN
			(
				comp_id,
				-- ie_id -- this column value is auto-generated,
				item_id,
				ie_ean,
				ie_isDUC,
				ie_DUNQty,
				ie_Force2InternalNewEAN,
				ie_isInternalEAN
			)
			VALUES
			(
				@comp_id,
				-- ie_id -- this column value is auto-generated,
				@litem_id,
				@ie_ean,
				@ie_isDUC,
				@ie_DUNQty,
				@ie_Force2InternalNewEAN,
				1
			)


			set	@return_value = IDENT_CURRENT('tbItemEAN')   -- @@identity

			END TRY
			BEGIN CATCH
				set	@return_value = 0
			END CATCH

			SELECT @return_value
			IF @return_value <> 0
				BEGIN
					EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,NULL
				END



END


















GO





