-- Date  : 05/01/17
-- Author: GA
-- Data  :Importacion de ean adic de Articulos - Insert data
--------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spItemEAN_Process_Auto_Validate]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_code					NVARCHAR(50),
	@ie_ean						NVARCHAR(50),
	@ie_Force2InternalNewEAN	BIT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT


)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@item_id_1					INT,
	@qty						DECIMAL(19,5),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT




SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,

	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 10,
	@bra_id4session				= 1

*/
---------------------------------------------------------------------------------


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


set nocount on

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''



	------Codigo-----------------------------------------------------------------------------------------------------------

	IF not EXISTS (SELECT top 1 ti.item_id
    						FROM tbitem ti								WITH (NOLOCK)
    						WHERE	ti.comp_id				= @comp_id AND
									ti.item_code			= @item_code
					)
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No existe un Artículo para el Código ingresado'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Ean Adicional-----------------------------------------------------------------------------------------------------------

	--Recuperamos el item_id mediante el codigo
	DECLARE @litem_id AS INT

	SELECT
		@litem_id = ti.item_id

		FROM tbitem  ti	WITH (NOLOCK)

		WHERE	ti.comp_id		= @comp_id		AND
				ti.item_code	= @item_code

	if	@ie_ean	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el EAN Adicional del Artículo'
		END
	ELSE
		BEGIN
			IF EXISTS (SELECT top 1 ti.item_id
    						FROM tbitem ti								WITH (NOLOCK)
    						WHERE	ti.comp_id				= @comp_id	AND
    								@ie_Force2InternalNewEAN = 0		AND
    							(	ti.item_code			= @ie_ean	OR
    								ti.item_vendorCode		= @ie_ean	OR
    								ti.item_codeAlternative = @ie_ean)
								)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El EAN Adicional ya existe en un Item(Código/Código Alternativo/Código de Fabricante)'
			END
		END



		IF EXISTS (SELECT top 1 tie.item_id
								FROM tbItemEAN tie								WITH (NOLOCK)
    									WHERE	tie.comp_id				 = @comp_id		AND
    											tie.item_id				 <> @litem_id	AND
    											tie.ie_ean				 = @ie_ean		AND
    											@ie_Force2InternalNewEAN = 0
					)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El EAN Adicional ya existe para otro Item'
			END

	-----------------------------------------------------------------------------------------------------------------------


	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO



----------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Date   : 05/01/17
-- Author : GA
-- Detail : Al finalizar el proceso de importacion se muestra en una grilla que registros fueron dados de alta y los que no.
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[spItemEAN_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SELECT
			tpclil.code4Import										[code4Import],
			--isnull(ti.item_code,'')									[detail],
			--tie.ie_ean												[desc],--eaan adicional
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	--LEFT JOIN tbItemEAN									tie		WITH (NOLOCK)
	--	ON	tie.comp_id		= tpclil.comp_id	AND
	--		tie.ie_id		= tpclil.item_id --tpclil.item_id = ie_id de tbPriceCostListImportLog

	--LEFT JOIN tbItem									ti		WITH (NOLOCK)
	--	ON	ti.comp_id		= tie.comp_id	AND
	--		ti.item_id		= tie.item_id

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40177 --El EAN Adicional del Artículo fue agregado con éxito



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO





