------------------------------------------------------------



CREATE PROCEDURE [dbo].[spItemEAN_UpdateData]
(

	@comp_id				 INT,
	@item_id				 INT,
	@ie_ean					 NVARCHAR(50),
	@ie_isDUC				 BIT,
	@ie_DUNQty				 INT,
	@ie_Force2InternalNewEAN BIT,
	@ie_id					 INT



)
as

set nocount on

--------------------------------------------------------
-------------parametros de prueba-----------------------
--------------------------------------------------------
/*


Declare @comp_id				INT,
		@item_id				INT,
		@ie_ean					NVARCHAR(50),
		@ie_isDUC				BIT,
		@ie_DUNQty				int


Select @comp_id				= 1,
	   @ie_id			    = 2


*/
--------------------------------------------------------
BEGIN

UPDATE tbItemEAN

SET
	comp_id						= @comp_id,
	item_id						= @item_id,
	ie_ean						= @ie_ean,
	ie_isDUC					= @ie_isDUC,
	ie_DUNQty					= @ie_DUNQty,
	ie_Force2InternalNewEAN		= @ie_Force2InternalNewEAN


WHERE comp_id		= @comp_id AND
	  ie_id			= @ie_id






END
GO






------------------------------------------------------------
--- Date : 29/10/2014
--- Desc : Item EAN - ValidateData
------------------------------------------------------------


CREATE PROCEDURE [dbo].[spItemEAN_ValidateData]
(

		@comp_id								Int,
		@item_id								Int,
		@ie_ean									nvarchar(50)



)
as
set nocount ON


--------------------------------------------------------
-------------parametros de prueba-----------------------
--------------------------------------------------------
/*
declare	@comp_id							Int,
		@item_id							Int,
		@ie_ean								nvarchar(50)



select		@comp_id						= 1,
			@item_id						= 223,
			@ie_ean							= 'F2'

*/
--------------------------------------------------------
BEGIN


    IF EXISTS(
    			SELECT TOP 1  1
    				FROM tbitem ti								WITH (NOLOCK)
    			WHERE	 ti.comp_id = @comp_id AND
    					(	ti.item_code			= @ie_ean	OR
    						ti.item_vendorCode		= @ie_ean	OR
    						ti.item_codeAlternative = @ie_ean)

			)
		OR
	   EXISTS(
	   			SELECT TOP 1  1
	   				FROM tbItemSerials tis			WITH (NOLOCK)
	   				WHERE	tis.comp_id		= @comp_id AND
	   						tis.is_serial	= @ie_ean
	   )



		BEGIN

			-- el codigo ean ya existe, NO se puede agregar
			SELECT 0 [isValid]
			--RAISERROR (15600,-1,-1, '<br> <br> <br> * El código  EAN ya existe como: Código de Artículo, Código del Proveedor, Código Alternativo o Número de Serie <br> <br> * The EAN code already exists as Item Code, Supplier Code, Alternate Code or Serial Number');

		END

		ELSE


	  IF EXISTS(
	   			SELECT TOP 1  1
	   				FROM tbItemEAN								tie			WITH (NOLOCK)
	   				WHERE	tie.comp_id		= @comp_id AND
	   						tie.ie_ean		= @ie_ean
	  )

	  BEGIN

			-- el codigo ean ya existe EN LA TABLA
			SELECT -1 [isValid]


		END

		ELSE


			BEGIN
				-- el codigo ean no existe, se puede agregar
				SELECT 1 [isValid]

			END


END


GO




CREATE PROCEDURE [dbo].[spItemExtendedWarranty_CloneData]
(
	@comp_id			INT,
	@item_id			INT,
	@subcat_id			INT,	-- no se usa mas xq se agregó CF
	@Item_Guid			UNIQUEIDENTIFIER

)
AS

	SET NOCOUNT ON

	BEGIN

		-- ----------------------
		-- TESTING
		-- ----------------------
		/*
		DECLARE
			@item_id	INT,
			@subcat_id	INT

		SELECT
			@item_id	= 1,
			@subcat_id	= 5
		*/
		-- ----------------------

		DECLARE @objGUID AS UNIQUEIDENTIFIER
		SET		@objGUID = CONVERT(UNIQUEIDENTIFIER,@Item_Guid)

		DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)

		INSERT INTO @tblComplexFilter_Items

		SELECT
			tcf.sl_id
			FROM tbComplexFilter tcf      WITH (NOLOCK)

			WHERE tcf.sl_guid	  = @objGUID      AND
				  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0
				BEGIN
					INSERT INTO @tblComplexFilter_Items
						SELECT ti.item_id
							FROM tbItem ti
							WHERE ti.comp_id	= @comp_id
				END

		-- --------------------------------------
		-- VARIABLES DE TRABAJO PARA EL CURSOR
		-- --------------------------------------
		DECLARE
			@lIntcomp_id				INT,
			@lIntitem_id				INT,
			@lIntitem_idWarranty		INT,
			@lIntQty					INT,
			@lBitIsByPercentage			BIT,
			@lDecimalPercentage			DECIMAL(19,6),
			@lDecimalPercentage4Cost	DECIMAL(19,6)



		-- Declaración del cursor para obtener los datos de tbItemExtendedWarranty en base al artículo seleccionado
		DECLARE cursor_ItemExtendedWarranty CURSOR FOR

			SELECT
				tiew.comp_id,
				tiew.item_id,
				tiew.item_id_1,
				tiew.ir_qty,
				tiew.ieg_IsByPercentage,
				tiew.ieg_Percentage,
				tiew.ieg_Percentage4Cost

			FROM tbItemExtendedWarranty		tiew
			WHERE	tiew.comp_id = @comp_id AND
					tiew.item_id = @item_id


		OPEN cursor_ItemExtendedWarranty

		-- lectura anticipada del cursor
		FETCH 	cursor_ItemExtendedWarranty
		INTO
			@lIntcomp_id				,
			@lIntitem_id				,
			@lIntitem_idWarranty		,
			@lIntQty					,
			@lBitIsByPercentage			,
			@lDecimalPercentage			,
			@lDecimalPercentage4Cost

		WHILE @@FETCH_STATUS = 0
			BEGIN
				-------------------------------------------------------------------------------------------------------------------------
				--DECLARAMOS UN NUEVO CURSOR PARA OBTENER TODOS LOS ARTÍCULOS CORRESPONDIENTES
				--A UNA SUBCATEGORÍA SELECCIONADA.

				DECLARE
					@lIntItem_Id4Clone	INT --ID DEL ARTÍCULO DEL QUE SE CREARA LA NUEVA GARANTÍA


				DECLARE cursor_ItemExtendedWarrantyCLONE CURSOR FOR
					SELECT
						ti.item_id
						FROM tbItem ti

						inner JOIN @tblComplexFilter_Items				tmp
						ON	tmp.item_id		= ti.item_id

						--WHERE ti.subcat_id = @subcat_id


				OPEN cursor_ItemExtendedWarrantyCLONE

				-- lectura anticipada del cursor
				FETCH 	cursor_ItemExtendedWarrantyCLONE
				INTO
					@lIntItem_Id4Clone


				WHILE @@FETCH_STATUS = 0
				BEGIN

					IF NOT EXISTS (SELECT 1
									FROM tbItemExtendedWarranty							tiew
								   WHERE	tiew.comp_id	= @comp_id					AND
											tiew.item_id	= @lIntItem_Id4Clone		AND
											tiew.item_id_1	= @lIntitem_idWarranty)

					BEGIN

						INSERT INTO tbItemExtendedWarranty
						(
							comp_id,
							item_id,
							item_id_1,
							ir_qty,
							ieg_IsByPercentage,
							ieg_Percentage,
							ieg_Percentage4Cost
						)
						VALUES
						(
							@comp_id,
							@lIntItem_Id4Clone,
							@lIntitem_idWarranty,
							@lIntQty,
							@lBitIsByPercentage,
							@lDecimalPercentage,
							@lDecimalPercentage4Cost
						)

					END


					-- próxima lectura del cursor
					FETCH cursor_ItemExtendedWarrantyCLONE
					INTO
						@lIntItem_Id4Clone
				END

				CLOSE cursor_ItemExtendedWarrantyCLONE
				DEALLOCATE cursor_ItemExtendedWarrantyCLONE



				-------------------------------------------------------------------------------------------------------------------------

			-- próxima lectura del cursor
			FETCH cursor_ItemExtendedWarranty
			INTO
				@lIntcomp_id				,
				@lIntitem_id				,
				@lIntitem_idWarranty		,
				@lIntQty					,
				@lBitIsByPercentage			,
				@lDecimalPercentage			,
				@lDecimalPercentage4Cost

			END
		CLOSE cursor_ItemExtendedWarranty
		DEALLOCATE cursor_ItemExtendedWarranty
	END


































GO




