CREATE PROCEDURE [dbo].[spItemExtendedWarranty_GetDataById]
(
	@comp_id	INT,
	@item_id	INT,
	@item_id_1	INT
)

AS SET NOCOUNT ON

-- ----------------------------------
-- TESTING
-- ----------------------------------
/*
	declare
			@comp_id	INT,
			@item_id	INT,
			@item_id_1	INT

	select
		@comp_id	= 1,
		@item_id	= -1,
		@item_id_1	= -1
*/
-- ----------------------------------



BEGIN

	SELECT
		tiew.comp_id,
		tiew.item_id,
		ti.item_code,
		ti.item_desc,
		tiew.item_id_1,
		ti2.item_code,
		ti2.item_desc,
		tiew.ir_qty,
		isnull(tiew.ieg_IsByPercentage,'False')		[ieg_IsByPercentage],
		isnull(tiew.ieg_Percentage,0)				[ieg_Percentage],
		isnull(tiew.ieg_Percentage4Cost,0)		    [ieg_Percentage4Cost]



	FROM tbItemExtendedWarranty tiew

		INNER JOIN tbItem					ti
		ON	ti.comp_id = tiew.comp_id
		AND ti.item_id = tiew.item_id

		INNER JOIN tbItem					ti2
		ON	ti2.comp_id	= tiew.comp_id
		AND ti2.item_id	= tiew.item_id_1

	WHERE	tiew.comp_id	= @comp_id	AND
			tiew.item_id	= @item_id	AND
			tiew.item_id_1	= @item_id_1

END
GO




