	@item_id_1	INT
)

AS SET NOCOUNT ON

BEGIN

	-- ---------------------------------------
	-- TESTING
	-- ---------------------------------------
	/*
		declare
			@comp_id	INT,
			@item_id	INT,
			@item_id_1	INT

		select
			@comp_id	= 1,
			@item_id	= -1,
