CREATE PROCEDURE [dbo].[spItemFathers_getCombo]
	@comp_id AS INT
as
set nocount on

select	ti.item_id																[Id],
		CASE
			WHEN len(ti.item_desc) > 50 THEN substring(ti.item_desc,1,50) + '...'
		ELSE ti.item_desc
		END																	    [desc]

FROM	dbo.tbItem		ti

WHERE	ti.comp_id = @comp_id
AND		ti.item_id IN (SELECT tiscr.item_id
						FROM tbItemSizeColorRelation tiscr
   		                WHERE tiscr.comp_id = ti.comp_id)


order by ti.item_desc





















GO





