CREATE PROCEDURE spItemImages_GetImageByRow4WebService
(
	@comp_id	INT,
	@item_id	INT,
	@ImgID		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT,
				@ImgID		INT
			SELECT
				@comp_id	= 1,
				@item_id	= 15549,
				@ImgID		= 1
		*/
		-- ------------------------------------

		SELECT
			ti.itimg_image
		FROM
		(
			SELECT
				ROW_NUMBER() OVER (ORDER BY tii.itimg_id) [RowNum],
				tii.itimg_image
			FROM tbItemImages AS tii
			WHERE	tii.comp_id = @comp_id AND
					tii.item_id = @item_id
		) ti
		WHERE RowNum = @ImgID
	END





GO









