CREATE PROCEDURE [dbo].[spItemImages_getWebSiteImages]
(
	@comp_id				INT,
	@bolGetNullImages		BIT,
	@bolOnlyUpdatedImages	BIT ,
	@itimg_id				INT
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 50
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	DECLARE			@tblItem TABLE ( item_id INT PRIMARY KEY )
	INSERT INTO		@tblItem( item_id)
		SELECT	distinct
			tsc.item_id			[Id]
			FROM tbItemImages tsc									WITH (NOLOCK)
			INNER JOIN tbItem ti									WITH (NOLOCK)
				ON	ti.comp_id	= tsc.comp_id AND
					ti.item_id	= tsc.item_id
			INNER JOIN tbWebSiteII_ItemsData twsiid					WITH (NOLOCK)
				ON	twsiid.comp_id = ti.comp_id AND
					twsiid.item_id = ti.item_id
			WHERE	tsc.comp_id = @comp_id			AND
					( tsc.itimg_image IS NOT NULL OR @bolGetNullImages='True')		AND
					tsc.itimg_disabled = 'False'	AND
					CASE
						WHEN @itimg_id > 0 AND tsc.itimg_id =  @itimg_id							THEN 1
						WHEN @itimg_id > 0 AND tsc.itimg_id <> @itimg_id							THEN 0
						WHEN @bolOnlyUpdatedImages = 'True' AND tsc.itimg_imageUpdated = 'True'		THEN 1
						WHEN @bolOnlyUpdatedImages = 'False'										THEN 1
						ELSE																			 0
					END	 = 1




	SELECT
		tsc.itimg_id			[Id],
		CASE
			WHEN @itimg_id = -2 THEN	NULL
			ELSE						tsc.itimg_image
		END						[Image]
		FROM tbItemImages tsc							WITH (NOLOCK)
		INNER JOIN @tblItem tmp
			ON tmp.item_id = tsc.item_id
		WHERE (@itimg_id <= 0 OR @itimg_id = tsc.itimg_id)



	IF @itimg_id <= 0
		BEGIN
			UPDATE tbItemImages		WITH (ROWLOCK)
				SET itimg_imageUpdated = 0
				FROM tbItemImages ti
				INNER JOIN @tblItem tmp
					ON tmp.item_id = ti.item_id
				WHERE ti.itimg_imageUpdated = 1
		END



END
GO




CREATE PROCEDURE [dbo].[spItemImages_getWebSitePDF]
(
	@comp_id				INT
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	DECLARE  @tblItem TABLE ( item_id INT PRIMARY KEY )
	INSERT INTO @tblItem( item_id)

	SELECT	distinct
		tsc.item_id			[Id]
		FROM tbItemPDF tsc						WITH (NOLOCK)
		INNER JOIN tbItem ti					WITH (NOLOCK)
			ON	ti.comp_id	= tsc.comp_id AND
				ti.item_id	= tsc.item_id
		INNER JOIN tbWebSiteII_ItemsData twsiid	WITH (NOLOCK)
			ON	twsiid.comp_id = ti.comp_id AND
				twsiid.item_id = ti.item_id
		WHERE	tsc.comp_id = @comp_id			AND
				( tsc.itpdf_pdf IS NOT NULL )	AND
				(
					(	tsc.itpdf_disabled	 = 'False'	AND
						ti.item_disabled	= 'False'	AND
						ti.item_web			= 'True'
					)
				)




	SELECT
		tsc.itpdf_id			[Id],
		tsc.itpdf_pdf			[Image]
		FROM tbItemPDF tsc		WITH (NOLOCK)
		INNER JOIN @tblItem tmp
			ON tmp.item_id = tsc.item_id
		WHERE tsc.itpdf_disabled = 0
		ORDER BY tsc.itpdf_order


END
GO


CREATE PROCEDURE [dbo].[spItemImages_UpdatePicture4ImageImportation]
(
	@comp_id			INT,
	@item_code			VARCHAR(50),
	@item_Image			IMAGE,
	@bitReplaceImage	BIT,
	@img_order			INT,
	@user_id			INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------
		-- TESTING
		-- --------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@item_code			VARCHAR(50),
				@item_Image			IMAGE,
				@bitReplaceImage	BIT
		*/
		-- --------------------------------------------------



		-- --------------------------------------------------------------------------------------------------------
		-- Evitar Bloqueo de Interprocesos - CONSULTAR a Aquitecto
		-- --------------------------------------------------------------------------------------------------------
		SET LOCK_TIMEOUT 5000			-- 10 segundos
		SET DEADLOCK_PRIORITY LOW		-- Tomar en cuenta para ULTIMA Opcion de Eliminación
		-- --------------------------------------------------------------------------------------------------------



		DECLARE @lUpdateOK		AS INT
		SET		@lUpdateOK		= 0

		DECLARE @lItemID		AS INT
		SET		@lItemID		= 0


		--SI ESTÁ CHECKEADO REEMPLAZO LA IMAGEN DIRECTAMENTE
		--IF @bitReplaceImage = 'True'
		--	BEGIN
				IF EXISTS (SELECT TOP 1  1
								FROM tbItem								ti		WITH (NOLOCK)
								LEFT JOIN tbItemEAN						tie		WITH (NOLOCK)
								ON	tie.comp_id = ti.comp_id AND
									tie.item_id = ti.item_id

								WHERE	ti.comp_id				= @comp_id		AND
										ti.item_code			= @item_code	OR
										tie.ie_ean				= @item_code	OR
										ti.item_vendorCode		= @item_code	OR
										ti.item_codeAlternative = @item_code
							)
					BEGIN

						SET @lItemID = (SELECT
											TOP 1 ti.item_id

											FROM tbItem									ti		WITH (NOLOCK)

											LEFT JOIN tbItemEAN							tie		WITH (NOLOCK)
											ON	tie.comp_id = ti.comp_id AND
												tie.item_id = ti.item_id

											WHERE	ti.comp_id				= @comp_id		AND
													ti.item_code			= @item_code	OR
													tie.ie_ean				= @item_code	OR
													ti.item_vendorCode		= @item_code	OR
													ti.item_codeAlternative = @item_code

											ORDER BY ti.item_id
						)



							IF EXISTS (SELECT TOP 1  1
										FROM tbItem								ti		WITH (NOLOCK)
										INNER JOIN tbItemImages					tii		WITH (NOLOCK)
										ON tii.comp_id = ti.comp_id  AND
											tii.item_id = ti.item_id
										WHERE	ti.comp_id		= @comp_id		AND
												ti.item_id		= @lItemID		AND
												tii.itimg_order = @img_order)

									BEGIN

										IF @bitReplaceImage = 'True'
													BEGIN

																				UPDATE tbItemImages
																				SET

																					itimg_image = @item_Image

																				WHERE
																					comp_id				= @comp_id		AND
																					item_id				= @lItemID		AND
																					itimg_order			= @img_order

																						SET @lUpdateOK = 1

													END

													ELSE
														BEGIN
																	IF EXISTS (SELECT TOP 1  1
																			FROM tbItem								ti		WITH (NOLOCK)
																			INNER JOIN tbItemImages					tii		WITH (NOLOCK)
																			ON tii.comp_id = ti.comp_id  AND
																				tii.item_id = ti.item_id
																			WHERE	ti.comp_id		= @comp_id		AND
																					ti.item_id		= @lItemID		AND
																					ti.item_picture IS NULL			AND
																					tii.itimg_order = @img_order)

																		BEGIN

																			UPDATE tbItemImages
																			SET

																				itimg_image = @item_Image

																			WHERE
																				comp_id				= @comp_id		AND
																				item_id				= @lItemID		AND
																				itimg_order			= @img_order

																					SET @lUpdateOK = 1

																		END
														END


									END
								ELSE
									BEGIN
										INSERT INTO tbItemImages
											(
												comp_id,
												item_id,
												itimg_image,
												itimg_disabled,
												itimg_order,
												itimg_imageChecksum,
												itimg_disabled4MercadoLibre,
												user_id4Insert,
												user_id4LastUpdate,
												user_LastUpdate,
												itimg_imageUpdated,
												MLPictureId,
												MLPictureIdWithError
											)
											VALUES
											(
												@comp_id,
												@lItemID,
												@item_Image,
												0,
												@img_order,
												0,
												0,
												@user_id,
												@user_id,
												GETDATE(),
												NULL,
												NULL,
												NULL
											)
									END


						SET @lUpdateOK = 1

					END







		--	END
		--ELSE
		--	BEGIN
		--		--SI NO ESTÁ CHECKEADO PRIMERO ME FIJO QUE SOLO ACTUALIZO EL ARTÍCULO SI NO TIENE IMAGEN Y PARA ESA ADICIONAL POR EL ORDEN
		--		--PQ PUEDE SER QUE ESTE LA ADICIONAL 3 Y 5 , Y ESTÉ QUERIENDO AGREGAR LA 4, SINO LO DEJO COMO ESTÁ
		--		IF EXISTS (SELECT TOP 1  1
		--						FROM tbItem								ti		WITH (NOLOCK)
		--						LEFT JOIN tbItemEAN						tie		WITH (NOLOCK)
		--						ON	tie.comp_id = ti.comp_id AND
		--							tie.item_id = ti.item_id

		--						WHERE	ti.comp_id				= @comp_id		AND
		--								ti.item_code			= @item_code	OR
		--								tie.ie_ean				= @item_code	OR
		--								ti.item_vendorCode		= @item_code	OR
		--								ti.item_codeAlternative = @item_code
		--		)
		--		BEGIN

		--			SET @lItemID = (SELECT
		--								TOP 1 ti.item_id

		--								FROM tbItem									ti		WITH (NOLOCK)

		--								LEFT JOIN tbItemEAN							tie		WITH (NOLOCK)
		--								ON	tie.comp_id = ti.comp_id AND
		--									tie.item_id = ti.item_id

		--								WHERE	ti.comp_id				= @comp_id		AND
