		--										ti.item_vendorCode		= @item_code	OR
		--										ti.item_codeAlternative = @item_code

		--								ORDER BY ti.item_id )


		--			IF EXISTS (SELECT TOP 1  1
		--								FROM tbItem								ti		WITH (NOLOCK)
		--								INNER JOIN tbItemImages					tii		WITH (NOLOCK)
		--								ON tii.comp_id = ti.comp_id  AND
		--									tii.item_id = ti.item_id
		--								WHERE	ti.comp_id		= @comp_id		AND
		--										ti.item_id		= @lItemID		AND
		--										ti.item_picture IS NULL			AND
		--										tii.itimg_order = @img_order)

		--							BEGIN

		--								UPDATE tbItemImages
		--								SET

		--									itimg_image = @item_Image

		--								WHERE
		--									comp_id				= @comp_id		AND
		--									item_id				= @lItemID	OR
		--									itimg_order			= @img_order

		--							END

		--							SET @lUpdateOK = 1


		--		END

				--IF EXISTS (SELECT TOP 1  1
				--			FROM tbItem								ti		WITH (NOLOCK)
				--			WHERE	ti.comp_id		= @comp_id		AND
				--					ti.item_code	= @item_code	AND
				--					ti.item_picture IS NULL)

				--		UPDATE tbItem	WITH (ROWLOCK)
				--		SET
				--			item_picture	= @item_Image
				--		WHERE	comp_id		= @comp_id		AND
