CREATE PROCEDURE [dbo].[spItemPartsChecking_Check_qtyConfirmed]
(
	@comp_id				int,
	@guid					uniqueidentifier
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*
		  DECLARE
  			@comp_id				int,
  			@guid					uniqueidentifier

		  SELECT
  			@comp_id				= 1,
  			@guid					= '6ec6b7de-4f83-40a7-bcc3-f55748c3140d'
*/
		-- --------------------------------------------------------------------------


	-- 0 : ERROR - Hay una parte que tiene una parte suelta.
	-- 1 : OK - No hay ninguna parte con parte sueltas.


	DECLARE @lavailable AS INT

	DECLARE @lean AS NVARCHAR(50)

	SET		@lavailable = 1
	set		@lean= ''


			IF EXISTS ( SELECT top 1 tipct.itp_EAN					[itp_EAN]

			            FROM tbItemPartsCheckingTable				tipct			WITH (NOLOCK)

						Where	tipct.ipc_guid			= @guid AND
								tipct.ipc_qtyConfirmed  <> 0

						)


				begin
						SET @lean = (SELECT top 1 tipct.itp_EAN					[itp_EAN]

										FROM tbItemPartsCheckingTable				tipct			WITH (NOLOCK)

										Where	tipct.ipc_guid			= @guid AND
												tipct.ipc_qtyConfirmed  <> 0
									 )
						SET		@lavailable = 0

				END
				ELSE
					BEGIN
							SET		@lavailable = 1
					END

	-- 0 : ERROR - Hay una parte que tiene una parte suelta.
	-- 1 : OK - No hay ninguna parte con parte sueltas.


SELECT @lavailable [Available],@lean [EAN]



END
GO






