CREATE PROCEDURE [dbo].[spItemPartsChecking_InitializeParts]
(

	@ipc_id			INT,
	@qtyconfirmed	DECIMAL(19,4)


)
AS

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- --------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------
	/*
		DECLARE
				@comp_id		INT,
				@guid			UNIQUEIDENTIFIER,
				@ipc_id			INT

		SELECT
				@comp_id		= 1,
				ipc_id			= 1,
				@guid			= 'DA4961C6-25DD-46FF-BBA1-F8C0086BFE62'

		*/
	-- --------------------------------------------------------------


	UPDATE tbItemPartsCheckingTable

			SET	ipc_qtyConfirmed	= ipc_qtyConfirmed - @qtyconfirmed,
