-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:
-- Si paso un codigo tomado se fija si es una PARTE de ARTICULO.
-- Si no lo es retorna el mismo codigo.
-- Si SI es una parte la pone en una temporal y se fija si puede armar un articulo completo con esa parte
-- si lo puede hacer retorna el PRIMER codigo que puede armar con esa parte.
-- ATENCION, se debe usar junto al SP: spItemPartsCheckingProcess_FreeParts
-- =============================================

CREATE PROCEDURE  [dbo].[spItemPartsCheckingProcess]
(
	@comp_id		AS INT,
	@guid			AS UNIQUEIDENTIFIER,
	@decQTY			AS DECIMAL(19,4) OUTPUT,
	@strReturnCode	AS nVARCHAR(50)	 OUTPUT
)
AS

BEGIN


	-- --------------------------------------------------
	-- Testing
	-- --------------------------------------------------
	/*
	DECLARE
			@comp_id		AS INT,
			@guid			AS UNIQUEIDENTIFIER,
			@decQTY			AS DECIMAL(19,4) ,
			@strReturnCode	AS nVARCHAR(50)
	SELECT	@comp_id		= 1 ,
			@guid			= '37795783-81FC-4C64-8413-6DC24CEB8ADB',
			@decQTY			= 1,
			@strReturnCode	='456'
	*/
	-- --------------------------------------------------


	DECLARE @strCODE AS NVARCHAR(50)
	SET		@strCODE = @strReturnCode

	-- Verifico si hay algun articulo que tenga ese numero de parte.
	IF	@strCODE <> '' AND
		EXISTS(
				SELECT 1
					FROM tbItemParts tip		WITH (NOLOCK)
					WHERE	tip.comp_id = @comp_id AND
							tip.itp_EAN = @strCODE
			)
		BEGIN

			SET @strReturnCode = '-1' -- Momentaneamente digo que NO se debe retornar nada ya que era una parte y aun no se si hay para armar un articulo terminado.

			-- Si aun no se cargo la doy de alta
			IF NOT EXISTS(
						SELECT 1
							FROM tbItemPartsCheckingTable tipct		WITH (NOLOCK)
							WHERE	tipct.ipc_guid	= @guid AND
									tipct.itp_EAN	= @strCODE
					)
				BEGIN
					INSERT INTO tbItemPartsCheckingTable
					(
						ipc_guid,
						itp_EAN,
						ipc_qtyChequed,
						ipc_qtyConfirmed,
						ipc_disabled
					)
					VALUES
					(
						@guid,
						@strCODE,
						@decQTY,
						@decQTY,
						'False'
					)
				END
			ELSE
				-- Si ya estaba agrego lo que viene informado.
				BEGIN
					UPDATE tbItemPartsCheckingTable
					SET
						ipc_qtyChequed		= ipc_qtyChequed	+ @decQTY,
						ipc_qtyConfirmed	= ipc_qtyConfirmed	+ @decQTY
					WHERE	ipc_guid	= @guid AND
							itp_EAN		= @strCODE
				END


			-- -----------------------------------------------------------
			-- Verifico que exista algun articulo para ser ingresado
			-- con lo que ya tengo en la temporal de accesos
			-- -----------------------------------------------------------
			DECLARE @tmpTable AS TABLE(item_id INT,itp_EAN NVARCHAR(50), partQTY INT)
			DECLARE @tmpItems4Check AS TABLE(item_id  INT)
			INSERT INTO @tmpItems4Check(item_id)
				SELECT DISTINCT tip.item_id
				FROM tbItemParts tip		WITH (NOLOCK)
				INNER JOIN tbItem ti		WITH (NOLOCK)
					ON	ti.comp_id	= tip.comp_id AND
						ti.item_id	= tip.item_id
				WHERE	tip.comp_id = @comp_id	AND
						tip.itp_EAN = @strCODE	AND
						ti.item_disabled = 'False'




			-- POngo todos los articulos que estan compuestos por esta parte
			INSERT INTO @tmpTable(
									item_id,
									itp_EAN,
									partQTY
								)
				SELECT tip.item_id, tip.itp_EAN,COUNT(*)
					FROM tbItemParts tip					WITH (NOLOCK)
					INNER JOIN @tmpItems4Check tmp
						ON		tmp.item_id	= tip.item_id
					WHERE		tip.comp_id = @comp_id
					GROUP BY	tip.item_id, tip.itp_EAN




			-- Resto de cada total de partes x articulo de la temporal el total de partes disponibles
			UPDATE @tmpTable
				SET partQTY = partQTY - tipct.ipc_qtyConfirmed
				FROM @tmpTable tmp
				INNER JOIN tbItemPartsCheckingTable tipct		WITH (NOLOCK)
					ON tipct.itp_EAN = tmp.itp_EAN
			WHERE tipct.ipc_guid = @guid




			-- POngo en CERO lo que quedo MENOR a cero
			--UPDATE @tmpTable
			--	SET partQTY = 0
			--	WHERE partQTY < 0

			-- POngo en otra temporal los articulos que NO pueieron completarse
			DECLARE @tmpItemNoCompleted TABLE(item_id INT PRIMARY KEY)
			INSERT INTO @tmpItemNoCompleted (item_id)
				SELECT DISTINCT item_id
					FROM @tmpTable
					WHERE partQTY > 0




			-- Borra todos los articulos que tuvieron algo no completado
			DELETE FROM @tmpTable
				FROM @tmpTable tmp
				INNER JOIN @tmpItemNoCompleted tmp1
					ON tmp1.item_id = tmp.item_id





			DECLARE @intItemId AS INT
			SET		@intItemId = NULL
			-- De los que quedan pone el primer codigo que se pueda completar con las partes seleccionadas
			SELECT TOP 1	@intItemId	   = ti.item_id,
							@strReturnCode = ti.item_code
				FROM @tmpTable tmp
				INNER JOIN tbItem ti		WITH (NOLOCK)
				ON	ti.comp_id = @comp_id AND
					ti.item_id = tmp.item_id
				WHERE ti.item_disabled = 'False'


			-- Ver que cantidad del codigo retornado se puede armar con lo que quedo en la tabla temporal





			-- Saca cual es la cantidad que puede armar con lo que YA HAY CONTADO
			delete from @tmpTable
			INSERT INTO @tmpTable(
									item_id,
									itp_EAN,
									partQTY
								)
				SELECT tip.item_id, tip.itp_EAN,COUNT(*)
					FROM tbItemParts tip		WITH (NOLOCK)
					WHERE		tip.comp_id = @comp_id   AND
								tip.item_id = @intItemId
					GROUP BY	tip.item_id, tip.itp_EAN

			SELECT @decQTY = round(MIN(tipct.ipc_qtyConfirmed / dbo.fnNoZDiv(tmp.partQTY)),0,2)
			FROM tbItemPartsCheckingTable tipct		WITH (NOLOCK)
			INNER JOIN @tmpTable tmp
				ON tmp.itp_EAN = tipct.itp_EAN
			WHERE tipct.ipc_guid = @guid







--SELECT @strReturnCode,@decQTY

			-- Recordar que si ese era el codigo que retornamos debemos llamar al SP:
			-- para que saque de disponible a las partes que se deben descontar de la
			-- QTY tomada hasta ahora de partes.

			-- -----------------------------------------------------------





		END




END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	Al finalizar la operacion en donde se reemplazo el codigo de articulo por el del
--              articulo contenedor de la parte se deben liberar las partes comprometidas del total disponible.
-- ATENCION, se debe usar cerrando el proceso del SP: ItemPartsCheckingProcess
-- =============================================

CREATE PROCEDURE  [dbo].[spItemPartsCheckingProcess_FreeParts]
(
	@comp_id		AS INT,
	@guid			AS UNIQUEIDENTIFIER,
	@intItemId		AS INT,
	@decQTY			AS DECIMAL(19,4)

)
AS


	-- -------------------------------------
	-- Test
	-- -------------------------------------
	/*
	DECLARE
	@comp_id		AS INT,
	@guid			AS UNIQUEIDENTIFIER,
	@intItemId		AS INT,
	@decQTY			AS DECIMAL(19,4)
	select
	@comp_id = 1,
	@guid	 = 'B95A7B80-E3C7-47E9-BDBE-AE89F0E7904E',
	@intItemId = 256,
	@decQTY	 = 1
	*/
	-- -------------------------------------

BEGIN

	UPDATE tbItemPartsCheckingTable
		SET
			ipc_qtyConfirmed	= ipc_qtyConfirmed - @decQTY
		FROM tbItemPartsCheckingTable tmp	WITH (NOLOCK)
		INNER JOIN tbItemParts tip			WITH (NOLOCK)
			ON	tip.comp_id		= @comp_id AND
				tip.itp_EAN		= tmp.itp_EAN
		WHERE	tmp.ipc_guid	= @guid AND
				tip.item_id		= @intItemId


END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	Al finalizar la operacion en donde se reemplazo el codigo de articulo por el del
--              articulo contenedor de la parte se deben liberar las partes comprometidas del total disponible.
-- ATENCION, se debe usar cerrando el proceso del SP: ItemPartsCheckingProcess
-- =============================================

CREATE PROCEDURE  [dbo].[spItemPartsCheckingProcess_InitializeParts]
(
	@comp_id		AS INT,
	@guid			AS UNIQUEIDENTIFIER,
	@intItemId		AS INT
)
AS


	-- -------------------------------------
	-- Test
	-- -------------------------------------
	/*
	DECLARE
	@comp_id		AS INT,
	@guid			AS UNIQUEIDENTIFIER,
	@intItemId		AS INT,
	@decQTY			AS DECIMAL(19,4)
	select
	@comp_id = 1,
	@guid	 = 'B95A7B80-E3C7-47E9-BDBE-AE89F0E7904E',
	@intItemId = 256,
	@decQTY	 = 1
	*/
	-- -------------------------------------

BEGIN

	UPDATE tbItemPartsCheckingTable
		SET
			ipc_qtyConfirmed	= 0,
			ipc_qtyChequed		= 0
		FROM tbItemPartsCheckingTable tmp		WITH (NOLOCK)
		INNER JOIN tbItemParts tip				WITH (NOLOCK)
			ON	tip.comp_id		= @comp_id AND
				tip.itp_EAN		= tmp.itp_EAN
		WHERE	tmp.ipc_guid	= @guid AND
				tip.item_id		= @intItemId


END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	Al finalizar la operacion en donde se reemplazo el codigo de articulo por el del
--              articulo contenedor de la parte se deben liberar las partes comprometidas del total disponible.
-- ATENCION, se debe usar cerrando el proceso del SP: ItemPartsCheckingProcess
-- =============================================

-- 12/02/2016 se modifico el sp , para que reste tambien la cantidad de partes sueltas.

CREATE PROCEDURE  [dbo].[spItemPartsCheckingProcess_MinusParts]
(
	@comp_id		AS INT,
	@guid			AS UNIQUEIDENTIFIER,
	@intItemId		AS INT,
	@decQTY			AS DECIMAL(19,4)

)
AS


	-- -------------------------------------
	-- Test
	-- -------------------------------------
	/*
	DECLARE
	@comp_id		AS INT,
	@guid			AS UNIQUEIDENTIFIER,
	@intItemId		AS INT,
	@decQTY			AS DECIMAL(19,4)
	select
	@comp_id = 1,
	@guid	 = 'B95A7B80-E3C7-47E9-BDBE-AE89F0E7904E',
	@intItemId = 256,
	@decQTY	 = 1
	*/
	-- -------------------------------------

BEGIN

	UPDATE tbItemPartsCheckingTable

	SET ipc_qtyChequed		= ipc_qtyChequed - @decQTY,
		ipc_qtyConfirmed	= ipc_qtyConfirmed - @decQTY -- 12/02/2016

	FROM tbItemPartsCheckingTable tmp

	INNER JOIN tbItemParts tip
		ON	tip.comp_id		= @comp_id AND
			tip.itp_EAN		= tmp.itp_EAN

	WHERE	tmp.ipc_guid	= @guid AND
			tip.item_id		= @intItemId


END
GO



CREATE PROCEDURE spItemPartsCheckingTable_DeleteDataByItemIdAndGuid
(
	@comp_id		INT,
	@itstkpld_id	INT,
	--@item_id		INT,
	@guid			UNIQUEIDENTIFIER
)
AS SET NOCOUNT ON

	BEGIN

		-- -----------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT,
				@guid		UNIQUEIDENTIFIER

			SELECT
				@comp_id	= 1,
				@item_id	= 256,
				@guid		= 'AD80A18D-1745-4AAD-8A4D-00775D13CF0C'

			DROP TABLE #tmpPartsEAN

		*/
		-- -----------------------------------------------------------

		DECLARE @litem_id INT

		SELECT
			@litem_id = tscod.item_id
		FROM tbStockControlOrders_Detail			tscod
		WHERE	tscod.comp_id		= @comp_id		AND
				tscod.itstkpld_id	= @itstkpld_id

		SELECT DISTINCT
			tip.itp_EAN
		INTO #tmpPartsEAN
		FROM tbItemParts				tip
		WHERE	tip.comp_id = @comp_id	AND
				tip.item_id = @litem_id

		DELETE FROM tbItemPartsCheckingTable

		WHERE	ipc_guid = @guid AND
				itp_EAN IN (SELECT
								TMP.itp_EAN
							FROM #tmpPartsEAN TMP)

	END



GO

