-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE spItemProductManager_userRelation_getCombo
	@comp_id	AS	INT,
	@user_id	AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SELECT	tipm.pm_id				[Id],
			tipm.pm_name			[Desc]
		FROM tbItemProductManager						AS tipm		WITH (NOLOCK)
		INNER JOIN tbItemProductManager_UserRelation	AS tipmur	WITH (NOLOCK)
			ON	tipmur.comp_id		= tipm.comp_id	AND
				tipmur.pm_id		= tipm.pm_id
		WHERE	tipmur.comp_id		= @comp_id		AND
				tipmur.[user_id]	= @user_id

END
GO




-- =========================================================
-- Author:		GA
-- Create date: 20-05-2015
-- Description:	getdata by FILTERS
-- =========================================================

CREATE PROCEDURE [dbo].[spItemPublication_GetDataByFilters]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@prof_id						INT,
	@user_id						INT,
	@option_status					INT,
	@option_status_publication		INT,
	@guid							VARCHAR(50),
	@pubh_id						INT,
	@page							INT,
	@bitShowQuoteInfo				BIT
)
AS



BEGIN

	SET NOCOUNT ON


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


	-- --------------------------------------
	-- Testing
	-- --------------------------------------
/*
	DECLARE
			@comp_id						INT,
			@lang_id						INT,
			@bra_id							INT,
			@prof_id						INT,
			@user_id						INT,
			@option_status					INT,
			@option_status_publication		INT,
			@guid							VARCHAR(50),
			@pubh_id						INT,
			@page							INT


	SELECT
			@comp_id						= 1,
			@bra_id							= 1,
			@option_status					= 0,
			@option_status_publication		= -1,
			@guid							= '79E0ABA5-39BE-4C3B-A512-6DD2E41C718F',
			@pubh_id						= -1,
			@lang_id						= 2,
			@page							= 0
*/
	-- --------------------------------------


		DECLARE @lGuid AS UNIQUEIDENTIFIER

		SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf			WITH (NOLOCK)
				WHERE tcf.sl_guid	  = @lGuid     AND
					  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti				WITH (NOLOCK)
						WHERE ti.comp_id = @comp_id
			END
		-- -------------------------------------------------------------


		SELECT
				'' [1],
				'' [2],
				'' [3],
				tiph.pubh_desc																												[pubh_desc],
				ti.item_code																												[item_code],
				ti.item_desc																												[item_desc],
				convert(decimal(19,2),isnull(tipd.pubd_cost,0) * dbo.fnGetPriceListItemTaxesCoeficient(ti.comp_id,ti.item_id))				[Cost],
				tc_cost.curr_symbol																											[curr_symbol],
				isnull(convert(decimal(19,2),tipd.pubd_priceInCash  * dbo.fnGetPriceListItemTaxesCoeficient(tipd.comp_id, tipd.item_id)),0)	[Precio_Contado],
				tc_InCash.curr_symbol																										[curr_symbol_contado],
				isnull(convert(decimal(19,2),tipd.pubd_price4Loan * dbo.fnGetPriceListItemTaxesCoeficient(tipd.comp_id, tipd.item_id)),0)	[Precio_Lista],
				tc_4Loan.curr_symbol																										[curr_symbol_lista],
				tov.optval_desc 																											[pubh_disabled],
				tiph.pubh_isAvailable4Publication																							[pubh_isAvailable4Publication],
				tipd.pubd_pageNumber																										[pubd_pageNumber],
				tipd.CreditQuotaQtyMaximum																									[CreditQuotaQtyMaximum],
				CASE
					WHEN @bitShowQuoteInfo = 'True' THEN
															(SELECT convert(decimal(19,2),IsNull(tbl.CreditQuote,0)  ) FROM dbo.fnCreditQuoteInfo(@comp_id,
																									  @bra_id,
																									  tb.st_id4Loan,
																									  tipd.item_id,
																									  tipd.pubd_price4Loan  * dbo.fnGetPriceListItemTaxesCoeficient(ti.comp_id,ti.item_id),
																									  tipd.CreditQuotaQtyMaximum,
																									  1,
																									  GETDATE(),
																									  1,
																									  0,
																									  'False',
																									  'True',
																									  tipd.creditI_up2Pays, tipd.creditI_creditInterest,
																									  tipd.creditII_up2Pays, tipd.creditII_creditInterest,
																									  tipd.creditIII_up2Pays, tipd.creditIII_creditInterest,
																									  tipd.creditIV_up2Pays, tipd.creditIV_creditInterest,
																									  0,
																									  tipd.CreditQuotaQtyMaximum) tbl)
					ELSE									0
				END																										[Cuota_Value],



				Convert(Varchar,tipd.item_id) + '-' + Convert(Varchar,tipd.pubh_id)+ '-' + Convert(Varchar,tipd.pubd_id)									[ID]



		FROM tbItemPublicationHeader						tiph		WITH(NOLOCK)

		INNER JOIN tbItemPublicationDetail					tipd		WITH(NOLOCK)
		ON	tipd.comp_id		= tiph.comp_id			AND
			tipd.pubh_id		= tiph.pubh_id

		INNER JOIN @tblComplexFilter_Items					tcf
		ON	tcf.item_id			= tipd.item_id

		INNER JOIN tbItem									ti			WITH(NOLOCK)
		ON	ti.comp_id			= tipd.comp_id			AND
			ti.item_id			= tipd.item_id

		LEFT JOIN tbsysCurrency							tc_cost		WITH(NOLOCK)
		ON	tc_cost.curr_id		= tipd.curr_idCost

		LEFT JOIN tbsysCurrency							tc_InCash	WITH(NOLOCK)
		ON	tc_InCash.curr_id	= tipd.curr_idInCash

		LEFT JOIN tbsysCurrency							tc_4Loan	WITH(NOLOCK)
		ON	tc_4Loan.curr_id	= tipd.curr_id4Loan

		INNER JOIN tbsysOptionsValues					tov			WITH(NOLOCK)
		ON  tov.lang_id			= @lang_id				AND
			tov.optval_id		= tiph.pubh_disabled	AND
			tov.optval_class	= 531

		INNER JOIN tbBranch								tb			WITH(NOLOCK)
		ON	tb.comp_id			= tiph.comp_id			AND
			tb.bra_id			= @bra_id






		WHERE	tiph.comp_id			= @comp_id											AND
			--	(isnull(tiph.bra_id,-1)	= @bra_id)			AND
				(@pubh_id				= -1 OR tiph.pubh_id			= @pubh_id)			AND
				CASE
	   				WHEN @option_status = -1														THEN 'True'
	   				WHEN @option_status =  1 AND isnull(tiph.pubh_disabled,'false') = 'True'		THEN 'True'
	   				WHEN @option_status =  0 AND isnull(tiph.pubh_disabled,'false') = 'False'		THEN 'True'
	   				ELSE 'False'
	   			END	= 'True'																AND
	   			CASE
	   				WHEN @option_status_publication = -1																	THEN 'True'
	   				WHEN @option_status_publication =  0 AND isnull(tiph.pubh_isAvailable4Publication,'false') = 'False'	THEN 'True'
	   				WHEN @option_status_publication =  1 AND isnull(tiph.pubh_isAvailable4Publication,'false') = 'True'		THEN 'True'
	   				ELSE 'False'
	   			END	= 'True'																AND
	   			(
	   				@page = -1 OR
	   				@page = tipd.pubd_pageNumber
	   			)



		ORDER BY ti.item_code,
				 ti.item_desc


END


GO

-- =========================================================
-- Author:		SL
-- Create date: 20-03-2017
-- Description:	getdata by FILTERS
-- =========================================================

CREATE PROCEDURE [dbo].[spItemPublication4MassiveUpdate_GetDataByFilters]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@prof_id						INT,
	@user_id						INT,
	@option_status					INT,
	@option_status_publication		INT,
	@guid							VARCHAR(50),
	@pubh_id						INT,
	@page							INT
)
AS



BEGIN

	SET NOCOUNT ON

--SI SE TOCA ALGO ACÁ EN LOS FILTROS, TAMBIÉN AGREGARLO EN spItemPublicationDetail_FullUpdateData4Publications
-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


	-- --------------------------------------
	-- Testing
	-- --------------------------------------
/*
	DECLARE
			@comp_id						INT,
			@lang_id						INT,
			@bra_id							INT,
			@prof_id						INT,
			@user_id						INT,
			@option_status					INT,
			@option_status_publication		INT,
			@guid							VARCHAR(50),
			@pubh_id						INT,
			@page							INT


	SELECT
			@comp_id						= 1,
			@bra_id							= 1,
			@option_status					= 0,
			@option_status_publication		= -1,
			@guid							= '79E0ABA5-39BE-4C3B-A512-6DD2E41C718F',
			@pubh_id						= -1,
			@lang_id						= 2,
			@page							= 0
*/
	-- --------------------------------------


		DECLARE @lGuid AS UNIQUEIDENTIFIER

		SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid	  = @lGuid     AND
					  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
		-- -------------------------------------------------------------


		SELECT
			--'' [1],
			--'' [2],
			--'' [3],
			tiph.pubh_desc																												[pubh_desc],
			ti.item_code																												[item_code],
			ti.item_desc																												[item_desc],
			CONVERT(decimal(19,2),ISNULL(tipd.pubd_cost,0) * dbo.fnGetPriceListItemTaxesCoeficient(ti.comp_id,ti.item_id))				[Cost],
			tc_cost.curr_symbol																											[curr_symbol],
			ISNULL(CONVERT(decimal(19,2),tipd.pubd_priceInCash  * dbo.fnGetPriceListItemTaxesCoeficient(tipd.comp_id, tipd.item_id)),0)	[Precio_Contado],
			tc_InCash.curr_symbol																										[curr_symbol_contado],
			ISNULL(CONVERT(decimal(19,2),tipd.pubd_price4Loan * dbo.fnGetPriceListItemTaxesCoeficient(tipd.comp_id, tipd.item_id)),0)	[Precio_Lista],
			tc_4Loan.curr_symbol																										[curr_symbol_lista],
			tov.optval_desc 																											[pubh_disabled],
			tiph.pubh_isAvailable4Publication																							[pubh_isAvailable4Publication],
			tipd.pubd_pageNumber																										[pubd_pageNumber],
			tipd.CreditQuotaQtyMaximum																									[CreditQuotaQtyMaximum],
			(SELECT CONVERT(decimal(19,2),ISNULL(tbl.CreditQuote,0)  ) FROM dbo.fnCreditQuoteInfo(@comp_id,
																								  @bra_id,
																								  tb.st_id4Loan,
																								  tipd.item_id,
																								  tipd.pubd_price4Loan  * dbo.fnGetPriceListItemTaxesCoeficient(ti.comp_id,ti.item_id),
																								  tipd.CreditQuotaQtyMaximum,
																								  1,
																								  GETDATE(),
																								  1,
																								  0,
																								  'False',
																								  'True',
																								  tipd.creditI_up2Pays, tipd.creditI_creditInterest,
																								  tipd.creditII_up2Pays, tipd.creditII_creditInterest,
																								  tipd.creditIII_up2Pays, tipd.creditIII_creditInterest,
																								  tipd.creditIV_up2Pays, tipd.creditIV_creditInterest,
																								  0,
																								  tipd.CreditQuotaQtyMaximum) tbl)						[Cuota_Value],
			CONVERT(Varchar,tipd.item_id) + '-' + CONVERT(Varchar,tipd.pubh_id)+ '-' + CONVERT(Varchar,tipd.pubd_id)									[ID]

			FROM tbItemPublicationHeader						tiph		WITH(NOLOCK)
			INNER JOIN tbItemPublicationDetail					tipd		WITH(NOLOCK)
			ON	tipd.comp_id		= tiph.comp_id				AND
				tipd.pubh_id		= tiph.pubh_id
			INNER JOIN @tblComplexFilter_Items					tcf
			ON	tcf.item_id			= tipd.item_id
			INNER JOIN tbItem									ti			WITH(NOLOCK)
			ON	ti.comp_id			= tipd.comp_id				AND
				ti.item_id			= tipd.item_id
			LEFT JOIN tbsysCurrency								tc_cost		WITH(NOLOCK)
			ON	tc_cost.curr_id		= tipd.curr_idCost
			LEFT JOIN tbsysCurrency								tc_InCash	WITH(NOLOCK)
			ON	tc_InCash.curr_id	= tipd.curr_idInCash
			LEFT JOIN tbsysCurrency								tc_4Loan	WITH(NOLOCK)
			ON	tc_4Loan.curr_id	= tipd.curr_id4Loan
			INNER JOIN tbsysOptionsValues						tov			WITH(NOLOCK)
			ON  tov.lang_id			= @lang_id					AND
				tov.optval_id		= tiph.pubh_disabled		AND
				tov.optval_class	= 531
			INNER JOIN tbBranch									tb			WITH(NOLOCK)
			ON	tb.comp_id			= tiph.comp_id				AND
				tb.bra_id			= @bra_id
		WHERE	tiph.comp_id			= @comp_id											AND
			--	(isnull(tiph.bra_id,-1)	= @bra_id)			AND
				(@pubh_id				= -1 OR tiph.pubh_id			= @pubh_id)			AND
				CASE
	   				WHEN @option_status = -1														THEN 'True'
	   				WHEN @option_status =  1 AND isnull(tiph.pubh_disabled,'false') = 'True'		THEN 'True'
	   				WHEN @option_status =  0 AND isnull(tiph.pubh_disabled,'false') = 'False'		THEN 'True'
	   				ELSE 'False'
	   			END	= 'True'																AND
	   			CASE
	   				WHEN @option_status_publication = -1																	THEN 'True'
	   				WHEN @option_status_publication =  0 AND isnull(tiph.pubh_isAvailable4Publication,'false') = 'False'	THEN 'True'
	   				WHEN @option_status_publication =  1 AND isnull(tiph.pubh_isAvailable4Publication,'false') = 'True'		THEN 'True'
	   				ELSE 'False'
	   			END	= 'True'																AND
	   			(
	   				@page = -1 OR
	   				@page = tipd.pubd_pageNumber
	   			)



		ORDER BY ti.item_code,
				 ti.item_desc


END
GO



-- =============================================
-- Author:		MOS
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spItemPublicationActiveItems]
	@comp_id		INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- POr velocidad lo pongo 1ro en una temporal y reciel LUEGO abro la transdaccion
	SELECT
			/*DISTINCT*/
			tipd.comp_id,
			tipd.pubh_id,
			tipd.pubd_id,
			tipd.item_id,
			viph.bra_id,
			viph.st_id,
			tipd.coslis_id,
			tipd.prli_idInCash,
			tipd.prli_id4Loan,
			viph.pubh_order
		INTO #tmpTable4Speed
		FROM vwItemPublicationHeader viph		WITH (NOLOCK)
		INNER JOIN tbItemPublicationDetail tipd	WITH (NOLOCK)
			ON	tipd.comp_id = viph.comp_id AND
				tipd.pubh_id = viph.pubh_id

		WHERE	viph.comp_id = @comp_id AND
				NOT EXISTS	(
								SELECT TOP 1 1
									FROM tbItemPublicationDetail tipd2			WITH (NOLOCK)	-- Trato de Eliminar Registros Duplicados
									INNER JOIN vwItemPublicationHeader tiph2	WITH (NOLOCK)
										ON	tiph2.comp_id	= tipd2.comp_id	AND
											tiph2.pubh_id	= tipd2.pubh_id
								WHERE 	tipd2.comp_id		= tipd.comp_id	AND
										tipd2.pubh_id		<> tipd.pubh_id	AND
										tipd2.item_id		 = tipd.item_id	AND
										tiph2.pubh_order	<= viph.pubh_order
							)
		ORDER BY viph.pubh_order




	--BEGIN TRANSACTION
	-- 10-2019: Antes se BORRABA y se hacia un insert dentro de la transaccion pero en Authogar parecia que esto consumia muchos recursos.
	-- Ahora se borran los que no correspondan, se actualizan los existentes y se dan de alta los que no existan como activosd.


		-- Borro TODOS los que YA no deben estar.
		DELETE FROM tbItemPublicationActiveItems			WITH (ROWLOCK)
			FROM tbItemPublicationActiveItems tipai
			LEFT JOIN #tmpTable4Speed tmp
				ON	tmp.comp_id = tipai.comp_id			AND
					tmp.pubh_id = tipai.pubh_id			AND
					tmp.pubd_id = tipai.pubd_id
			WHERE	tipai.comp_id = @comp_id	AND
					tmp.comp_id IS NULL


		-- Actualizo todos los ya existentes
		UPDATE tbItemPublicationActiveItems							WITH (ROWLOCK)
			SET  item_id		= tmp.item_id,
				 bra_id			= tmp.bra_id,
				 st_id			= tmp.st_id,
				 coslis_id		= tmp.coslis_id,
				 prli_id4inCash = tmp.prli_idInCash,
				 prli_id4Loan	= tmp.prli_id4Loan,
				 pubd_cd		= GETDATE(),
				 pubh_order		= tmp.pubh_order
			FROM		tbItemPublicationActiveItems	tipai
			INNER JOIN	#tmpTable4Speed					tmp
				ON	tmp.comp_id = tipai.comp_id AND
					tmp.pubh_id = tipai.pubh_id AND
					tmp.pubd_id = tipai.pubd_id




		-- Inserto los que faltan
		INSERT INTO tbItemPublicationActiveItems					WITH (ROWLOCK)
		(
			comp_id,
			pubh_id,
			pubd_id,
			item_id,
			bra_id,
			st_id,
			coslis_id,
			prli_id4inCash,
			prli_id4Loan,
			pubh_order		-- Al Pedo, solo para el DISTINCT
		)
		SELECT
				/*DISTINCT*/
				tmp.comp_id,
				tmp.pubh_id,
				tmp.pubd_id,
				tmp.item_id,
				tmp.bra_id,
				tmp.st_id,
				tmp.coslis_id,
				tmp.prli_idInCash,
				tmp.prli_id4Loan,
				tmp.pubh_order
			FROM  #tmpTable4Speed					tmp
			LEFT JOIN tbItemPublicationActiveItems	tipai		WITH (NOLOCK)
				ON	tipai.comp_id = tmp.comp_id AND
					tipai.pubh_id = tmp.pubh_id AND
					tipai.pubd_id = tmp.pubd_id
			WHERE tipai.comp_id IS NULL


		-- ------------------------------------------------------------------------------------------------------------
		-- MOS 11-2022: x Authogar q se incluyan en el WS de items modificados al activarse una publicacion / revista.
		-- ------------------------------------------------------------------------------------------------------------
		INSERT INTO tbItemsUpdated
		(
			item_id,
			upd_cd
		)
		SELECT	DISTINCT
				tmp.item_id,
				GETDATE()
			FROM #tmpTable4Speed		tmp
			LEFT JOIN tbItemsUpdated	tmp2	WITH (NOLOCK)		-- MOS 12-2022 para que no inserte duplicados al pedo.
				ON tmp2.item_id = tmp.item_id
			WHERE tmp2.item_id IS NULL
		-- ------------------------------------------------------------------------------------------------------------




	--COMMIT TRANSACTION

END
GO



-- =========================================================
-- Author:		GA
-- Create date: 21-05-2015
-- Description:	Borrar item publication detail
-- =========================================================


-- MOS 30-09-2019: Si sigue molestando la velocidad hay que hacer que el SP spItemPublicationActiveItems haga SOLO para el articulo que fue modificado y NO para TODOS los articulos publicables

CREATE PROCEDURE [dbo].[spItemPublicationDetail_DeleteData]

	@comp_id				INT,
	@item_id				INT,
	@pubh_id				INT,
	@pubd_id				INT


AS

-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 	@comp_id				INT,
			@item_id				INT,
			@pubh_id				INT,
			@pubd_id				INT


SELECT		@comp_id			=1,
			@item_id			=257,
			@pubh_id			=7,
			@pubd_id			=12
*/
-- -----------------------------------------------------



BEGIN

			DELETE FROM tbItemPublicationDetail	WITH (ROWLOCK)
			WHERE comp_id = @comp_id	AND
			      pubh_id = @pubh_id	AND
			      pubd_id = @pubd_id	AND
			      item_id = @item_id



END
GO


