			SELECT
				@comp_id					= 1,
				@lang_id					= 2,
				@bra_id						= 1,
				@user_id					= 119,
				@prof_id					= 1,
				@itemGuid					= '25892e17-80f6-415f-9c65-7395632f0223',
				@UpdateOption				= 2, --1 Sumar Valor / 2 Sumar Porcentaje / 3 Sobreescribir Valor
