						INSERT INTO @tblComplexFilter_Items
							SELECT ti.item_id
								FROM tbItem ti
								WHERE ti.comp_id = @comp_id
					END
			-- ------------------------------------------------------------------


			SELECT
				tipd.comp_id,
				tipd.pubh_id,
				tipd.pubd_id,
				tipd.item_id
				INTO #tmpItems2Update
				FROM tbItemPublicationHeader						tiph		WITH(NOLOCK)
				INNER JOIN tbItemPublicationDetail					tipd		WITH(NOLOCK)
				ON	tipd.comp_id		= tiph.comp_id				AND
					tipd.pubh_id		= tiph.pubh_id
				INNER JOIN @tblComplexFilter_Items					tcf
				ON	tcf.item_id			= tipd.item_id
				INNER JOIN tbItem									ti			WITH(NOLOCK)
				ON	ti.comp_id			= tipd.comp_id				AND
					ti.item_id			= tipd.item_id
				LEFT JOIN tbsysCurrency								tc_cost		WITH(NOLOCK)
				ON	tc_cost.curr_id		= tipd.curr_idCost
				LEFT JOIN tbsysCurrency								tc_InCash	WITH(NOLOCK)
				ON	tc_InCash.curr_id	= tipd.curr_idInCash
				LEFT JOIN tbsysCurrency								tc_4Loan	WITH(NOLOCK)
				ON	tc_4Loan.curr_id	= tipd.curr_id4Loan
				INNER JOIN tbsysOptionsValues						tov			WITH(NOLOCK)
				ON  tov.lang_id			= @lang_id					AND
					tov.optval_id		= tiph.pubh_disabled		AND
					tov.optval_class	= 531
				INNER JOIN tbBranch									tb			WITH(NOLOCK)
				ON	tb.comp_id			= tiph.comp_id				AND
					tb.bra_id			= @bra_id
			WHERE	tiph.comp_id			= @comp_id											AND
				--	(isnull(tiph.bra_id,-1)	= @bra_id)			AND
					(@pubh_id				= -1 OR tiph.pubh_id			= @pubh_id)			AND
					CASE
	   					WHEN @option_status = -1														THEN 'True'
	   					WHEN @option_status =  1 AND ISNULL(tiph.pubh_disabled,'False') = 'True'		THEN 'True'
	   					WHEN @option_status =  0 AND ISNULL(tiph.pubh_disabled,'False') = 'False'		THEN 'True'
	   					ELSE 'False'
	   				END	= 'True'																AND
	   				CASE
	   					WHEN @option_status_publication = -1																	THEN 'True'
	   					WHEN @option_status_publication =  0 AND ISNULL(tiph.pubh_isAvailable4Publication,'False') = 'False'	THEN 'True'
	   					WHEN @option_status_publication =  1 AND ISNULL(tiph.pubh_isAvailable4Publication,'False') = 'True'		THEN 'True'
	   					ELSE 'False'
	   				END	= 'True'																AND
	   				(
	   					@page = -1 OR
	   					@page = tipd.pubd_pageNumber
	   				)
			ORDER BY ti.item_code,
					 ti.item_desc





			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
			-- SUMA EL VALOR AL QUE YA ESTÁ CARGADO
			-- SOLO SE ACTUALIZARAN AQUELLOS VALORES CUYO CHK ESTE EN TRUE
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
				IF @UpdateOption = 1
					BEGIN
						UPDATE tbItemPublicationDetail		WITH (ROWLOCK)
						SET
							pubd_cost				= CASE @chkCostPrice	WHEN	'True'	THEN	(tipd.pubd_cost					+ @CostPrice)
																							ELSE	tipd.pubd_cost
																							END,

							item_purOrd_Disc1		= CASE @chkDiscount1	WHEN	'True'	THEN	(tipd.item_purOrd_Disc1			+ @Discount1)
																							ELSE	tipd.item_purOrd_Disc1
																							END,

							item_purOrd_Disc2		= CASE @chkDiscount2	WHEN	'True'	THEN	(tipd.item_purOrd_Disc2			+ @Discount2)
																							ELSE	tipd.item_purOrd_Disc2
																							END,

							item_purOrd_Disc3		= CASE @chkDiscount3	WHEN	'True'	THEN	(tipd.item_purOrd_Disc3			+ @Discount3)
																							ELSE	tipd.item_purOrd_Disc3
																							END,

							item_purOrd_Disc4		= CASE @chkDiscount4	WHEN	'True'	THEN	(tipd.item_purOrd_Disc4			+ @Discount4)
																							ELSE	tipd.item_purOrd_Disc4
																							END,

							item_purOrd_surcharge1	= CASE @chkCharge1		WHEN	'True'	THEN	(tipd.item_purOrd_surcharge1	+ @Charge1)
																							ELSE	tipd.item_purOrd_surcharge1
																							END,

							item_purOrd_surcharge2	= CASE @chkCharge2		WHEN	'True'	THEN	(tipd.item_purOrd_surcharge2	+ @Charge2)
																							ELSE	tipd.item_purOrd_surcharge2
																							END,

							item_purOrd_surcharge3	= CASE @chkCharge3		WHEN	'True'	THEN	(tipd.item_purOrd_surcharge3	+ @Charge3)
																							ELSE	tipd.item_purOrd_surcharge3
																							END,

							item_purOrd_surcharge4	= CASE @chkCharge4		WHEN	'True'	THEN	(tipd.item_purOrd_surcharge4	+ @Charge4)
																							ELSE	tipd.item_purOrd_surcharge4
																							END,

							item_markup_1			= CASE @chkMarkup1		WHEN	'True'	THEN	(tipd.item_markup_1				+ @markup1)
																							ELSE	tipd.item_markup_1
																							END,

							pubd_priceInCash		= CASE @chkPriceInCash	WHEN	'True'	THEN	(tipd.pubd_priceInCash			+ @PriceInCash)
																							ELSE	tipd.prli_idInCash
																							END,

							item_markup_2			= CASE @chkMarkup2		WHEN	'True'	THEN	(tipd.item_markup_2				+ @markup2)
																							ELSE	tipd.item_markup_2
																							END,

							pubd_price4Loan			= CASE @chkPriceLoan	WHEN	'True'	THEN	(tipd.pubd_price4Loan			+ @PriceLoan)
																							ELSE	tipd.pubd_price4Loan
																							END,

							CreditQuotaQtyMaximum	= CASE @chkQtyMaxCuota	WHEN	'True'	THEN	(tipd.CreditQuotaQtyMaximum		+ @QtyMaxCuota)
																							ELSE	tipd.CreditQuotaQtyMaximum
																							END,

							creditI_creditInterest  = CASE @chkTasa1		WHEN	'True'	THEN	(tipd.creditI_creditInterest	+ @Tasa1)
																							ELSE	tipd.creditI_creditInterest
																							END,

							creditI_up2Pays			= CASE @chkCuota1		WHEN	'True'	THEN	(tipd.creditI_up2Pays			+ @Cuota1)
																							ELSE	tipd.creditI_up2Pays
																							END,

							creditII_creditInterest = CASE @chkTasa2		WHEN	'True'	THEN	(tipd.creditII_creditInterest	+ @Tasa2)
																							ELSE	tipd.creditII_creditInterest
																							END,

							creditII_up2Pays		= CASE @chkCuota2		WHEN	'True'	THEN	(tipd.creditII_up2Pays			+ @Cuota2)
																							ELSE	tipd.creditII_up2Pays
																							END,

							creditIII_creditInterest= CASE @chkTasa3		WHEN	'True'	THEN	(tipd.creditIII_creditInterest	+ @Tasa3)
																							ELSE	tipd.creditIII_creditInterest
																							END,

							creditIII_up2Pays		= CASE @chkCuota3		WHEN	'True'	THEN	(tipd.creditIII_up2Pays			+ @Cuota3)
																							ELSE	tipd.creditIII_up2Pays
																							END,

							creditIV_creditInterest = CASE @chkTasa4		WHEN	'True'	THEN	(tipd.creditIV_creditInterest	+ @Tasa3)
																							ELSE	tipd.creditIV_creditInterest
																							END,

							creditIV_up2Pays		= CASE @chkCuota4		WHEN	'True'	THEN	(tipd.creditIV_up2Pays			+ @Cuota4)
																							ELSE	tipd.creditIV_up2Pays
																							END,
							pubd_isItemUpdated		= 'True'
						FROM tbItemPublicationDetail		tipd
						INNER JOIN #tmpItems2Update			tmp
						ON	tmp.comp_id	= tipd.comp_id	AND
							tmp.pubh_id = tipd.pubh_id	AND
							tmp.pubd_id = tipd.pubd_id	AND
							tmp.item_id	= tipd.item_id

					END
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------

			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
			-- SUMA EL PORCENTAJE DEL VALOR YA CARGADO
			-- SOLO SE ACTUALIZARAN AQUELLOS VALORES CUYO CHK ESTE EN TRUE
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
				IF @UpdateOption = 2
					BEGIN
						UPDATE tbItemPublicationDetail		WITH (ROWLOCK)
						SET
							pubd_cost				= CASE @chkCostPrice WHEN 'True'	THEN	(tipd.pubd_cost					+ (tipd.pubd_cost					* @CostPrice)	/ 100)
																						ELSE	tipd.pubd_cost
																						END,

							item_purOrd_Disc1		= CASE @chkDiscount1 WHEN 'True'	THEN	(tipd.item_purOrd_Disc1			+ (tipd.item_purOrd_Disc1			* @Discount1)	/ 100)
																						ELSE	tipd.item_purOrd_Disc1
																						END,

							item_purOrd_Disc2		= CASE @chkDiscount2 WHEN 'True'	THEN (	tipd.item_purOrd_Disc2			+ (tipd.item_purOrd_Disc2			* @Discount2)	/ 100)
																						ELSE	tipd.item_purOrd_Disc2
																						END,

							item_purOrd_Disc3		= CASE @chkDiscount3 WHEN 'True'	THEN	(tipd.item_purOrd_Disc3			+ (tipd.item_purOrd_Disc3			* @Discount3)	/ 100)
																						ELSE	tipd.item_purOrd_Disc3
																						END,

							item_purOrd_Disc4		= CASE @chkDiscount4 WHEN 'True'	THEN	(tipd.item_purOrd_Disc4			+ (tipd.item_purOrd_Disc4			* @Discount4)	/ 100)
																						ELSE	tipd.item_purOrd_Disc4
																						END,

							item_purOrd_surcharge1	= CASE @chkCharge1	 WHEN 'True'	THEN	(tipd.item_purOrd_surcharge1	+ (tipd.item_purOrd_surcharge1		* @Charge1)		/ 100)
																						ELSE	tipd.item_purOrd_surcharge1
																						END,

							item_purOrd_surcharge2	= CASE @chkCharge2	 WHEN 'True'	THEN	(tipd.item_purOrd_surcharge2	+ (tipd.item_purOrd_surcharge2		* @Charge2)		/ 100)
																						ELSE	tipd.item_purOrd_surcharge2
																						END,

							item_purOrd_surcharge3	= CASE @chkCharge3	 WHEN 'True'	THEN	(tipd.item_purOrd_surcharge3	+ (tipd.item_purOrd_surcharge3		* @Charge3)		/ 100)
																						ELSE	tipd.item_purOrd_surcharge3
																						END,

							item_purOrd_surcharge4	= CASE @chkCharge4	 WHEN 'True'	THEN	(tipd.item_purOrd_surcharge4	+ (tipd.item_purOrd_surcharge4		* @Charge4)		/ 100)
																						ELSE	tipd.item_purOrd_surcharge4
																						END,

							item_markup_1			= CASE @chkMarkup1	 WHEN 'True'	THEN	(tipd.item_markup_1				+ (tipd.item_markup_1				* @markup1)		/ 100)
																						ELSE	tipd.item_markup_1
																						END,

							pubd_priceInCash		= CASE @chkPriceInCash WHEN 'True'	THEN	(tipd.pubd_priceInCash			+ (tipd.pubd_priceInCash			* @PriceInCash)	/ 100)
																						ELSE	tipd.pubd_priceInCash
																						END,

							item_markup_2			= CASE @chkMarkup2	  WHEN 'True'	THEN	(tipd.item_markup_2				+ (tipd.item_markup_2				* @markup2)		/ 100)
																						ELSE	tipd.item_markup_2
																						END,

							pubd_price4Loan			= CASE @chkPriceLoan  WHEN 'True'	THEN	(tipd.pubd_price4Loan			+ (tipd.pubd_price4Loan				* @PriceLoan)	/ 100)
																						ELSE	tipd.pubd_price4Loan
																						END,

							CreditQuotaQtyMaximum	= CASE @chkQtyMaxCuota WHEN 'True'	THEN	(tipd.CreditQuotaQtyMaximum		+ (tipd.CreditQuotaQtyMaximum		* @QtyMaxCuota)	/ 100)
																						ELSE	tipd.CreditQuotaQtyMaximum
																						END,

							creditI_creditInterest  = CASE @chkTasa1	WHEN 'True'		THEN	(tipd.creditI_creditInterest	+ (tipd.creditI_creditInterest		* @Tasa1)		/ 100)
																						ELSE	tipd.creditI_creditInterest
																						END,

							creditI_up2Pays			= CASE @chkCuota1	WHEN 'True'		THEN	(tipd.creditI_up2Pays			+ (tipd.creditI_up2Pays				* @Cuota1)		/ 100)
																						ELSE	tipd.creditI_up2Pays
																						END,

							creditII_creditInterest = CASE @chkTasa2	WHEN 'True'		THEN	(tipd.creditII_creditInterest	+ (tipd.creditII_creditInterest		* @Tasa2)		/ 100)
																						ELSE	tipd.creditII_creditInterest
																						END,

							creditII_up2Pays		= CASE @chkCuota2	WHEN 'True'		THEN	(tipd.creditII_up2Pays			+ (tipd.creditII_up2Pays			* @Cuota2)		/ 100)
																						ELSE	tipd.creditII_up2Pays
																						END,
							creditIII_creditInterest= CASE @chkTasa3	WHEN 'True'		THEN	(tipd.creditIII_creditInterest	+ (tipd.creditIII_creditInterest	* @Tasa3)		/ 100)
																						ELSE	tipd.creditIII_creditInterest
																						END,

							creditIII_up2Pays		= CASE @chkCuota3	WHEN 'True'		THEN	(tipd.creditIII_up2Pays		+ (tipd.creditIII_up2Pays				* @Cuota3)		/ 100)
																						ELSE	tipd.creditIII_up2Pays
																						END,

							creditIV_creditInterest = CASE @chkTasa4	WHEN 'True'		THEN	(tipd.creditIV_creditInterest	+ (tipd.creditIV_creditInterest		* @Tasa3)		/ 100)
																						ELSE	tipd.creditIV_creditInterest
																						END,

							creditIV_up2Pays		= CASE @chkCuota4
															WHEN 'True'		THEN	(tipd.creditIV_up2Pays			+ (tipd.creditIV_up2Pays			* @Cuota3)		/ 100)
															ELSE	tipd.creditIV_up2Pays
													  END,
							pubd_isItemUpdated		= 'True'
						FROM tbItemPublicationDetail		tipd
						INNER JOIN #tmpItems2Update			tmp
						ON	tmp.comp_id	= tipd.comp_id	AND
							tmp.pubh_id = tipd.pubh_id	AND
							tmp.pubd_id = tipd.pubd_id	AND
							tmp.item_id	= tipd.item_id
					END
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------

			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
			-- SOBREESCRIBE LOS VALORES QUE ESTAN CARGADOS
			-- SOLO SE ACTUALIZARAN AQUELLOS VALORES CUYO CHK ESTE EN TRUE
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
				IF @UpdateOption = 3
					BEGIN
						UPDATE tbItemPublicationDetail		WITH (ROWLOCK)
						SET
							pubd_cost				= CASE @chkCostPrice	WHEN	'True'	THEN @CostPrice
																							ELSE tipd.pubd_cost
							         														END,

							item_purOrd_Disc1		= CASE @chkDiscount1	WHEN	'True'	THEN	@Discount1
																							ELSE	tipd.item_purOrd_Disc1
																							END,

							item_purOrd_Disc2		= CASE @chkDiscount2	WHEN	'True'	THEN	@Discount2
																							ELSE	tipd.item_purOrd_Disc2
																							END,

							item_purOrd_Disc3		= CASE @chkDiscount3	WHEN	'True'	THEN	@Discount3
																							ELSE	tipd.item_purOrd_Disc3
																							END,

							item_purOrd_Disc4		= CASE @chkDiscount4	WHEN	'True'	THEN	@Discount4
																							ELSE	tipd.item_purOrd_Disc4
																							END,

							item_purOrd_surcharge1	= CASE @chkCharge1		WHEN	'True'	THEN	@Charge1
																							ELSE	tipd.item_purOrd_surcharge1
																							END,

							item_purOrd_surcharge2	= CASE @chkCharge2		WHEN	'True'	THEN	@Charge2
																							ELSE	tipd.item_purOrd_surcharge2
																							END,

							item_purOrd_surcharge3	= CASE @chkCharge3		WHEN	'True'	THEN	@Charge3
																							ELSE	tipd.item_purOrd_surcharge3
																							END,

							item_purOrd_surcharge4	= CASE @chkCharge4		WHEN	'True'	THEN	@Charge4
																							ELSE	tipd.item_purOrd_surcharge4
																							END,

							item_markup_1			= CASE @chkMarkup1		WHEN	'True'	THEN	@markup1
																							ELSE	tipd.item_markup_1
																							END,

							pubd_priceInCash		= CASE @chkPriceInCash	WHEN	'True'	THEN	@PriceInCash
																							ELSE	tipd.pubd_priceInCash
																							END,

							item_markup_2			= CASE @chkMarkup2		WHEN	'True'	THEN	@markup2
																							ELSE	tipd.item_markup_2
																							END,

							pubd_price4Loan			= CASE @chkPriceLoan	WHEN	'True'	THEN	@PriceLoan
																							ELSE	tipd.pubd_price4Loan
																							END,

							CreditQuotaQtyMaximum	= CASE @chkQtyMaxCuota	WHEN	'True'	THEN	@QtyMaxCuota
																							ELSE	tipd.CreditQuotaQtyMaximum
																							END,

							creditI_creditInterest  = CASE @chkTasa1		WHEN	'True'	THEN	@Tasa1
																							ELSE	tipd.creditI_creditInterest
																							END,

							creditI_up2Pays			= CASE @chkCuota1		WHEN	'True'	THEN	@Cuota1
																							ELSE	tipd.creditI_up2Pays
																							END,

							creditII_creditInterest = CASE @chkTasa2		WHEN	'True'	THEN	@Tasa2
																							ELSE	tipd.creditII_creditInterest
																							END,

							creditII_up2Pays		= CASE @chkCuota2		WHEN	'True'	THEN	@Cuota2
																							ELSE	tipd.creditII_up2Pays
																							END,

							creditIII_creditInterest= CASE @chkTasa3		WHEN	'True'	THEN	@Tasa3
																							ELSE	tipd.creditIII_creditInterest
																							END,

							creditIII_up2Pays		= CASE @chkCuota3		WHEN	'True'	THEN	@Cuota3
																							ELSE	tipd.creditIII_up2Pays
																							END,

							creditIV_creditInterest = CASE @chkTasa4		WHEN	'True'	THEN	@Tasa4
																							ELSE	tipd.creditIV_creditInterest
																							END,

							creditIV_up2Pays		= CASE @chkCuota4		WHEN	'True'	THEN	@Cuota4
																							ELSE	tipd.creditIV_up2Pays
																							END,
							pubd_isItemUpdated		= 'True'
						FROM tbItemPublicationDetail		tipd
						INNER JOIN #tmpItems2Update			tmp
						ON	tmp.comp_id	= tipd.comp_id	AND
							tmp.pubh_id = tipd.pubh_id	AND
							tmp.pubd_id = tipd.pubd_id	AND
							tmp.item_id	= tipd.item_id
					END
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------

		DECLARE
			@intpubh_id		INT,
			@intpubd_id		INT,
			@item_id		INT,
			@decCost		DECIMAL(25,4),
			@curr_id4Cost	INT,
			@decDiscount1	DECIMAL(25,4),
			@decDiscount2	DECIMAL(25,4),
			@decDiscount3	DECIMAL(25,4),
			@decDiscount4	DECIMAL(25,4),
			@decSurcharge1	DECIMAL(25,4),
			@decSurcharge2	DECIMAL(25,4),
			@decSurcharge3	DECIMAL(25,4),
			@decSurcharge4	DECIMAL(25,4),
			@decMarkup1		DECIMAL(25,8),
			@decMarkup2		DECIMAL(25,8),
			@curr_id4Spot	INT,
			@curr_id4Price	INT


		DECLARE cursor_PriceCalculation CURSOR LOCAL FAST_FORWARD FOR

			SELECT
				tipd.pubh_id,
				tipd.pubd_id,
				tipd.item_id,
				tipd.pubd_cost,
				tipd.coslis_id,
				tipd.item_purOrd_Disc1,
				tipd.item_purOrd_Disc2,
				tipd.item_purOrd_Disc3,
				tipd.item_purOrd_Disc4,
				tipd.item_purOrd_surcharge1,
				tipd.item_purOrd_surcharge2,
				tipd.item_purOrd_surcharge3,
				tipd.item_purOrd_surcharge4,
				tipd.item_markup_1,
				tipd.item_markup_2,
				tipd.curr_idInCash,
				tipd.curr_id4Loan

			FROM #tmpItems2Update				tmp
			INNER JOIN tbItemPublicationDetail	tipd
			ON	tipd.comp_id	= tmp.comp_id	AND
				tipd.pubh_id	= tmp.pubh_id	AND
				tipd.pubd_id	= tmp.pubd_id	AND
				tipd.item_id	= tmp.item_id

		OPEN	cursor_PriceCalculation

			-- lectura anticipada del cursor
			FETCH	cursor_PriceCalculation
			INTO	@intpubh_id,
					@intpubd_id,
					@item_id,
					@decCost,
					@curr_id4Cost,
					@decDiscount1,
					@decDiscount2,
					@decDiscount3,
					@decDiscount4,
					@decSurcharge1,
					@decSurcharge2,
					@decSurcharge3,
					@decSurcharge4,
					@decMarkup1,
					@decMarkup2,
					@curr_id4Spot,
					@curr_id4Price

			WHILE   @@FETCH_STATUS = 0
				BEGIN

					--ACA SE PROCESA TODO
					UPDATE tbItemPublicationDetail
					SET
						pubd_priceInCash	= (SELECT fgpfc.Price4SpotNoTaxes
						                	     FROM dbo.fnGetPriceFromCost(
																									@comp_id,
																									@bra_id,
																									@item_id,
																									@decCost,
																									@curr_id4Cost,
						                															@decDiscount1,
						                															@decDiscount2,
						                															@decDiscount3,
						                															@decDiscount4,
						                															@decSurcharge1,
						                															@decSurcharge2,
						                															@decSurcharge3,
						                															@decSurcharge4,
						                															@decMarkup1,
						                															@decMarkup2,
						                															@curr_id4Spot,
						                															@curr_id4Price ) fgpfc),
						pubd_price4Loan		= (SELECT fgpfc.Price4ListNoTaxes
						               		     FROM dbo.fnGetPriceFromCost(
																									@comp_id,
																									@bra_id,
