-- Create date: 20-05-2015
-- Description:	getdata by id
-- =========================================================
CREATE PROCEDURE [dbo].[spItemPublicationDetail_GetDataByID]
(

	@comp_id	INT,
	@item_id	INT,
	@pubh_id    INT,
	@pubd_id    INT

)
AS
SET NOCOUNT ON


		BEGIN



		--------------------------------------------------------------------------------------------------
		-- Test
		--------------------------------------------------------------------------------------------------
		/*
		DECLARE @comp_id	INT,
				@item_id	INT	,
				@pubh_id    INT,
				@pubd_id    INT


		SELECT 	@comp_id	= 1 ,
				@item_id	= 492,
				@pubh_id    = 1,
				@pubd_id    = 4

		*/
		--------------------------------------------------------------------------------------------------



			SELECT  tipd.pubh_id,
					tipd.pubd_id,
					tipd.item_id,
					tipd.pubd_cost,
					tipd.pubd_pageNumber,
					tipd.creditI_up2Pays,
					tipd.creditI_creditInterest,
					tipd.creditII_up2Pays,
					tipd.creditII_creditInterest,
					tipd.creditIII_up2Pays,
					tipd.creditIII_creditInterest,
					tipd.creditIV_up2Pays,
					tipd.creditIV_creditInterest,
					tipd.item_purOrd_Disc1,
					tipd.item_purOrd_Disc2,
					tipd.item_purOrd_Disc3,
					tipd.item_purOrd_Disc4,
					tipd.item_purOrd_surcharge1,
					tipd.item_purOrd_surcharge2,
					tipd.item_purOrd_surcharge3,
					tipd.item_purOrd_surcharge4,
					tipd.prli_idInCash,
					tipd.item_markup_1,
					tipd.pubd_priceInCash,
					tipd.curr_idInCash,
					tipd.prli_id4Loan,
					tipd.item_markup_2,
					tipd.pubd_price4Loan,
					tipd.curr_id4Loan,
					tipd.coslis_id,
					tipd.curr_idCost,
					tipd.CreditQuotaQtyMaximum

			FROM tbItemPublicationDetail				tipd		WITH(NOLOCK)


			WHERE	tipd.comp_id = @comp_id		AND
					tipd.item_id = @item_id		AND
					tipd.pubh_id = @pubh_id		AND
					tipd.pubd_id = @pubd_id

		END



GO



CREATE PROCEDURE [dbo].[spItemPublicationDetail_InsertData]
(
	@comp_id		INT,
	@pubh_id		INT,
	@item_id		INT,
	@page			INT,
	@return_value	INT OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON

	IF NOT EXISTS (	SELECT TOP 1  1
						FROM  tbItemPublicationDetail	tipd   WITH (NOLOCK)
						WHERE	tipd.comp_id = @comp_id AND
								tipd.pubh_id = @pubh_id AND
								tipd.item_id = @item_id)
		BEGIN
			INSERT INTO tbItemPublicationDetail		WITH (ROWLOCK)
			(
				comp_id,
				pubh_id,
				item_id,
				pubd_pageNumber
			)
			VALUES
			(
				@comp_id,
				@pubh_id,
				@item_id,
				@page
			)
			SET @return_value = @@IDENTITY
		END
	ELSE
		BEGIN
			SET @return_value = -1
		END







	-- Actualiza datos de Hijos de Talles y Colores
	IF EXISTS (	SELECT TOP 1 1 --DISTINCT 1 MOS 03-2020
					FROM	tbItemSizeColorRelation tiscr	WITH (NOLOCK)
					WHERE	tiscr.comp_id = @Comp_id
					AND		tiscr.item_id = @Item_id)
    BEGIN

    	DECLARE @litem_id_child				INT,
    			@liscr_Coeficient4Price		DECIMAL(19,4)

    	--declaración de cursor para recuperar los items hijos y los coeficientes
    	DECLARE cursor_childs CURSOR LOCAL  FAST_FORWARD FOR
    		SELECT	tiscr.item_id_child,
    				tiscr.iscr_Coeficient4Price
    			FROM	tbItemSizeColorRelation		tiscr				WITH (NOLOCK)
    			WHERE	tiscr.comp_id = @Comp_id
    			AND		tiscr.item_id = @Item_id


    	OPEN cursor_childs

    	FETCH  cursor_childs INTO @litem_id_child, @liscr_Coeficient4Price

    	WHILE @@FETCH_STATUS = 0
    	BEGIN


			IF NOT EXISTS (	SELECT TOP 1  1
								FROM  tbItemPublicationDetail	tipd		WITH (NOLOCK)
								WHERE	tipd.comp_id = @comp_id AND
										tipd.pubh_id = @pubh_id AND
										tipd.item_id = @litem_id_child)
				BEGIN
					INSERT INTO tbItemPublicationDetail		WITH (ROWLOCK)
					(
						comp_id,
						pubh_id,
						item_id,
						pubd_pageNumber
					)
					VALUES
					(
						@comp_id,
						@pubh_id,
						@litem_id_child,
						@page
					)
					--SET @return_value = @@IDENTITY
				END

    		FETCH  cursor_childs INTO @litem_id_child, @liscr_Coeficient4Price

    	END

    	CLOSE cursor_childs
    	DEALLOCATE cursor_childs


	END






END
GO




