-- =========================================================

CREATE PROCEDURE [dbo].[spItemPublicationDetail_UpdateLoanInfo]
(
	@comp_id					INT,
	@item_id					INT,
	@pubh_id					INT,
	@pubd_id					INT,
	@creditI_up2Pays			INT,
	@creditI_creditInterest		DECIMAL(19,4),
	@creditII_up2Pays			INT,
	@creditII_creditInterest	DECIMAL(19,4),
	@creditIII_up2Pays			INT,
	@creditIII_creditInterest	DECIMAL(19,4),
	@creditIV_up2Pays			INT,
	@creditIV_creditInterest	DECIMAL(19,4),
	@CreditQuotaMaximum			INT
)
AS
SET NOCOUNT ON
BEGIN

	UPDATE tbItemPublicationDetail		WITH (ROWLOCK)
	SET
			creditI_up2Pays				= @creditI_up2Pays,
			creditI_creditInterest		= @creditI_creditInterest,
			creditII_up2Pays			= @creditII_up2Pays,
			creditII_creditInterest		= @creditII_creditInterest,
			creditIII_up2Pays			= @creditIII_up2Pays,
			creditIII_creditInterest	= @creditIII_creditInterest,
			creditIV_up2Pays			= @creditIV_up2Pays,
			creditIV_creditInterest		= @creditIV_creditInterest,
			CreditQuotaQtyMaximum		= @CreditQuotaMaximum,
			pubd_isItemUpdated			= 'True'


	WHERE	comp_id			= @comp_id		AND
			pubh_id			= @pubh_id		AND
			pubd_id			= @pubd_id		AND
			item_id			= @item_id





	-- Actualiza datos de Hijos de Talles y Colores
	IF EXISTS (SELECT DISTINCT 1
				FROM	tbItemSizeColorRelation tiscr		WITH (NOLOCK)
				WHERE	tiscr.comp_id = @Comp_id
				AND		tiscr.item_id = @Item_id)
    BEGIN

    	DECLARE @litem_id_child				INT,
    			@liscr_Coeficient4Price		DECIMAL(19,4)

    	--declaración de cursor para recuperar los items hijos y los coeficientes
    	DECLARE cursor_childs CURSOR LOCAL FAST_FORWARD FOR
    		SELECT	tiscr.item_id_child,
    				tiscr.iscr_Coeficient4Price
    			FROM	tbItemSizeColorRelation		tiscr				WITH (NOLOCK)
    			WHERE	tiscr.comp_id = @Comp_id
    			AND		tiscr.item_id = @Item_id


    	OPEN cursor_childs

    	FETCH  cursor_childs INTO @litem_id_child, @liscr_Coeficient4Price

    	WHILE @@FETCH_STATUS = 0
    	BEGIN


			IF  EXISTS (SELECT
								1
							FROM  tbItemPublicationDetail	tipd		WITH (NOLOCK)
						   WHERE	tipd.comp_id = @comp_id AND
									tipd.pubh_id = @pubh_id AND
									tipd.item_id = @litem_id_child
						)
				BEGIN

					-- Solo para que dispare un trigger que copia los datos del padre a los hijos de la publicacion.
					UPDATE tbItemPublicationDetail
					SET
					item_id			= @litem_id_child
						--pubd_cost					= @tmpcost,
						--item_purOrd_Disc1			= @Discount1,
						--item_purOrd_Disc2			= @Discount2,
						--item_purOrd_Disc3			= @Discount3,
						--item_purOrd_Disc4			= @Discount4,
						--item_purOrd_surcharge1		= @Charge1,
						--item_purOrd_surcharge2		= @Charge2,
						--item_purOrd_surcharge3		= @Charge3,
						--item_purOrd_surcharge4		= @Charge4,
						--item_markup_1				= @Markup1,
						--pubd_priceInCash			= @Price4SpotPrice,
						--curr_idInCash				= @Price4SpotPrice_Curr_Id,
						--item_markup_2				= @Markup2,
						--pubd_price4Loan				= @Price4PriceList,
						--curr_id4Loan				= @Price4PriceList_Curr_Id,
						--curr_idCost					= @tmpCost_Curr_Id,
						--CreditQuotaQtyMaximum		= @CreditQuotaQtyMaximum,
						--coslis_id					= @coslis_id,
						--prli_idInCash				= @prli_idInCash,
						--prli_id4Loan				= CASE
						--								  WHEN @prli_id4Loan = -1 THEN NULL
						--								  ELSE @prli_id4Loan
						--            				  END


					WHERE	comp_id			= @comp_id		AND
							pubh_id			= @pubh_id		AND
							--pubd_id			= @pubd_id		AND
							item_id			= @litem_id_child


				END

    		FETCH  cursor_childs INTO @litem_id_child, @liscr_Coeficient4Price

    	END

    	CLOSE cursor_childs
    	DEALLOCATE cursor_childs


	END



END
GO






CREATE PROCEDURE [dbo].[spItemPublicationHeader_getCombo]
(
	@comp_id			INT
)
AS

BEGIN

	set nocount on

	select		tiph.pubh_id								[id],
				tiph.pubh_desc								[desc]

		from		dbo.tbItemPublicationHeader tiph		WITH (NOLOCK)


		where	tiph.comp_id		 = @comp_id		AND
				tiph.pubh_disabled	 = 'False'


		Order By	pubh_desc


END
GO






-- =========================================================================================================
-- Author:		GA
-- Create date: 27-05-2015
-- Description:	getcombo para recargar las publicaciones en base al estado y si es publicable o no.
-- =========================================================================================================

CREATE PROCEDURE [dbo].[spItemPublicationHeader_getCombo4Filters]
(
	@comp_id						INT,
	@pubh_disabled					INT,
	@pubh_isAvailable4Publication	INT

)
AS

BEGIN

	-- --------------------------------------
	-- Testing
	-- --------------------------------------
/*
		DECLARE
				@comp_id						INT,
				@pubh_disabled					INT,
				@pubh_isAvailable4Publication	INT

		SELECT
				@comp_id						= 1,
				@pubh_disabled					= 1,
				@pubh_isAvailable4Publication	= 0
*/
	-- --------------------------------------



	set nocount on

		select		tiph.pubh_id								[id],
					tiph.pubh_desc								[desc]

		from	dbo.tbItemPublicationHeader			tiph		WITH (NOLOCK)


		where	(tiph.comp_id					= @comp_id)				AND
				(@pubh_disabled					= -1 OR tiph.pubh_disabled					= @pubh_disabled)			AND
				(@pubh_isAvailable4Publication	= -1 OR tiph.pubh_isAvailable4Publication	= @pubh_isAvailable4Publication)


		Order By	pubh_desc


END
GO










