CREATE PROCEDURE [dbo].[spItemRelations_Copy]
(


	@comp_id								INT,
	@lang_id								INT,
	@bra_id									INT,
	@prof_id								INT,
	@user_id								INT,
	@item_id_from							INT,
	@item_id_to								INT,
	@type									INT


)
as
set nocount ON


BEGIN


---------------------------------------------------------------------
--parametros de prueba
---------------------------------------------------------------------
/*
declare			@comp_id								INT,
				@lang_id								INT,
				@bra_id									INT,
				@prof_id								INT,
				@user_id								INT,
				@item_id_from							INT,
				@item_id_to								INT,
				@type									INT





select			@comp_id						= 1,
				@item_id_from					=256,
				@item_id_to						=229,
				@type							=2,
				@lang_id						=2


*/
---------------------------------------------------------------------
--
---------------------------------------------------------------------


	-- TYPE : 1 - ASOCIACION
	--		  2 - COMPOSICION



BEGIN TRANSACTION
BEGIN TRY

	-- 852 asociacion no realizada correctamente
	-- 853 composicion no realizada correctamente

	DECLARE @return_value		INT,
			@errormessage		VARCHAR(200)

	set @return_value = -1

	--declare @A int


	if @type = '1'

		BEGIN

			--set @A = 1/0



			delete from tbItemAssociation
			where comp_id = @comp_id
			and   item_id = @item_id_to


				insert into tbItemAssociation
				(
					comp_id,
					item_id,
					item_id_1,
					iasso_qty,
					itema_canDeleteInSO,
					itema_discountPercentage4PriceListSUM
				)

				select  tia.comp_id,
						@item_id_to,
						tia.item_id_1,
						tia.iasso_qty,
						tia.itema_canDeleteInSO,
						tia.itema_discountPercentage4PriceListSUM


				from tbItemAssociation tia

				where tia.comp_id = @comp_id
				and tia.item_id = @item_id_from

			SET @return_value = 1
			SET @errormessage = (select tut.utexts_desc FROM tbsysUniqueTexts tut
							 WHERE tut.lang_id = @lang_id AND tut.utexts_id = 852)

		END


	ELSE

		BEGIN

			--	set @A = 1/0

				delete from tbItemComposition
				where item_id = @item_id_to

				insert into tbItemComposition
				(
					comp_id,
					item_id,
					item_id_1,
					icomp_qty,
					color_id
				)


				select  tic.comp_id,
						@item_id_to,
						tic.item_id_1,
						tic.icomp_qty,
						tic.color_id

				from tbItemComposition tic

				where tic.comp_id = @comp_id
				and	  tic.item_id = @item_id_from

		SET @return_value = 2
		SET @errormessage = (select tut.utexts_desc FROM tbsysUniqueTexts tut
							 WHERE tut.lang_id = @lang_id AND tut.utexts_id = 853)

		END



	COMMIT TRANSACTION


END
TRY BEGIN CATCH

	ROLLBACK TRANSACTION

BEGIN

		if @return_value <> 1 and  @return_value <> 2
			BEGIN
			SET @return_value	= -1
			SET @errormessage	= ERROR_MESSAGE()
			END

		END


END CATCH


SELECT	@return_value [Value], @errormessage [Error]


END
GO









CREATE PROCEDURE [dbo].[spItemRelations_getData]
(

	@comp_id								INT,
	@lang_id								INT,
	@bra_id									INT,
	@prof_id								INT,
	@user_id								INT,
	@item_id								INT,
	@type									INT
)
as
set nocount ON



BEGIN


---------------------------------------------------------------------
--parametros de prueba
---------------------------------------------------------------------
/*
declare		@comp_id								INT,
			@lang_id								INT,
			@bra_id									INT,
			@prof_id								INT,
			@user_id								INT,
			@item_id								INT,
			@type									INT


select		@comp_id						= 1,
			@item_id						=229,
			@type							=1
*/
---------------------------------------------------------------------
--
---------------------------------------------------------------------


	-- TYPE : 1 - ASOCIACION
	--		  2 - COMPOSICION

	if @type = '1'
		BEGIN
			select  top 1
					ti.item_code,
					ti.item_desc,
					null  [iasso_qty]


			from	tbItemAssociation					tia

			inner join tbItem							ti
			on		ti.comp_id = tia.comp_id
			and		ti.item_id = tia.item_id


			where	tia.comp_id = @comp_id
			and		tia.item_id = @item_id

			union

			select  ti.item_code,
					ti.item_desc,
					tia.iasso_qty


			from	tbItemAssociation					tia


					inner join tbItem					ti
					on  ti.comp_id = tia.comp_id
					and ti.item_id = tia.item_id_1


			where	tia.comp_id = @comp_id
			and		tia.item_id = @item_id

			order by 3
		END

	ELSE

	BEGIN

		select  top 1 ti.item_code,
					  ti.item_desc,
					  null				[color_desc],
					  null              [icomp_qty]

		from	tbItemComposition					tic


		inner join tbItem							ti
		on  ti.comp_id		= tic.comp_id
		and ti.item_id		= tic.item_id


		where	tic.comp_id = @comp_id
		and		tic.item_id = @item_id

		union

		select  ti.item_code,
				ti.item_desc,
				tc.color_desc,
				tic.icomp_qty

		from	tbItemComposition						tic


				inner join tbItem						ti
				on  ti.comp_id		= tic.comp_id
				and ti.item_id		= tic.item_id_1

				Inner Join tbColor						tc
				On  tc.comp_id		= tic.comp_id
				And tc.color_id		= tic.color_id

		where	tic.comp_id = @comp_id
		and		tic.item_id = @item_id

		order by 3
	END







END
GO








