CREATE PROCEDURE [dbo].[spItemReplacement_getDataByFilters]
(
		@comp_id								Int,
		@item_id								Int,
     	@item_id_1								Int
)
as


BEGIN


	set nocount ON


	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
	declare	@comp_id								INT,
			@item_id								INT,
			@item_id_1								INT,
			@color_id								INT


	select		@comp_id		=1,
				@item_id		=-1,
				@item_id_1		=-1,
				@color_id       = -1

	*/
	-- ----------------------------------------------------------


	SELECT  ' ' [ ], ' ' [ ],' ' [ ],
			ti.item_code															[item_codeMain],
			ti.item_desc															[item_descMain],
			ti2.item_code															[item_codeChild],
			ti2.item_desc															[item_descChild],
			tir.ir_qty																[iasso_qty],
			CONVERT(VARCHAR,tir.item_id) + ' - ' + Convert(Varchar, tir.item_id_1)  [ID]

		From tbItemReplacement tir					WITH (NOLOCK)
		Inner Join tbItem ti						WITH (NOLOCK)
			On  ti.comp_id  = tir.comp_id
			And ti.item_id  = tir.item_id
		Inner Join tbitem ti2						WITH (NOLOCK)
			On  ti2.comp_id = tir.comp_id
			And ti2.item_id = tir.item_id_1

		WHERE	 tir.comp_id			 		   = @comp_id			AND
				(
					-- Reemplazos Mios
					(
						(@item_id   = -1 or tir.item_id		= @item_id)		AND
						(@item_id_1 = -1 or tir.item_id_1	= @item_id_1)
					)
					OR
					-- Si los pido al reves igual los obtengo
					(
						(@item_id   = -1 or tir.item_id_1   = @item_id)		AND
						(@item_id_1 = -1 or tir.item_id		= @item_id_1)
					)
				)

	END
GO







CREATE PROCEDURE [dbo].[spItemReplacement_getDataById]
(
		@comp_id			Int,
		@Item_id			Int,
		@Item_id_1			Int
)
as

set nocount on

/*
Declare @comp_id			Int,
		@Item_id			Int,
		@Item_id_1			Int


Select @comp_id				= 1,
	   @Item_id			    = 231,
	   @Item_id_1			= 264

		*/


Select tir.comp_id,
	   tir.item_id,
	   ti1.item_code,
	   ti1.item_desc,
	   tir.item_id_1,
	   ti2.item_code [item_code1],
	   ti2.item_desc [item_desc1],
	   tir.ir_qty

From tbItemReplacement tir

Inner Join tbItem ti1
On  ti1.comp_id = tir.comp_id
And ti1.item_id = tir.item_id


Inner Join tbItem ti2
On  ti2.comp_id = tir.comp_id
And ti2.item_id = tir.item_id_1

Where tir.comp_id    = @comp_id
And   tir.item_id    = @Item_id
And   tir.item_id_1  = @Item_id_1
GO








