CREATE PROCEDURE [dbo].[spItemReplacement_validateData]
(
	@comp_id		int,
	@origen			Int,
	@destino		Int,
	@level			Int,
	@return_value	Int Output
)
as
set nocount on


/*
Declare		@comp_id	int,
			@origen Int,
			@destino Int,
			@level	Int,
			@return_value Int
select		@comp_id	=1,
			@origen		=277,
			@destino	=229,
			@level		=0,
			@return_value = 0
*/


Set @level = @level + 1

-- -----------------------
-- Para Evitar StackFault
If @level > 30
Begin
    Return
End
-- -----------------------

--select		@level ,@origen,	@destino


If Exists (Select 1 From dbo.tbItemReplacement tir
           Where tir.comp_id	= @comp_id
           And   tir.item_id	= @origen
           And   tir.item_id_1	= @destino
           And   @level			= 1 )

	Begin

		-- esta condición es para evitar duplicados
		Set @return_value = 2
		--Select 33

	End

Else

	Begin

		If Exists (Select 1 From dbo.tbItemReplacement tir
				   Where tir.comp_id	= @comp_id
				   And	 tir.item_id	= @destino
				   And	 tir.item_id_1	= @origen )

			begin
				--esta condición es cuando se encuentra que algún origen es parte del destino
				Set @return_value = 1
				--Select 1

			End

		Else

			Begin

				Declare @lorigen Int,
						@lret_val Int
				Select @lret_val =0

				Declare @varCursor Cursor
				Set @varCursor = Cursor for
					Select	tir.item_id_1
					From	tbItemReplacement tir
					Where	tir.comp_id = @comp_id
					And		tir.item_id = @destino

				Open @varCursor
				--Select 2

				Fetch  @varCursor Into @lorigen

				While @@FETCH_STATUS = 0 And @lret_val = 0
				Begin

					--Select @lorigen
					Exec spItemReplacement_validateData
						@comp_id,
						@origen,
						@lorigen,
						@level,
						@return_value = @lret_val Output

					Fetch  @varCursor Into @lorigen

				End

				Close @varCursor
				Deallocate @varCursor

				Set @return_value = @lret_val

			End

	End








GO







create PROCEDURE [dbo].[spItemReplacement_VerificationReplacement]
(
	@comp_id				int,
	@item_id				int
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
		/*
		  DECLARE
  			@comp_id				int,
  			@item_id				INT


		  SELECT
  			@comp_id				= 1,
  			@item_id				= 495
		*/
		-- --------------------------------------------------------------------------

DECLARE @bolExistsData AS BIT

SET     @bolExistsData = 'False'


IF EXISTS (


		  SELECT tir.item_id, tir.item_id_1

		  FROM tbItemReplacement tir		WITH (NOLOCK)

		  Where			tir.comp_id		=		@comp_id
		  AND			tir.item_id		=		@item_id

)
BEGIN
	SET @bolExistsData = 'True'

END


ELSE
BEGIN

	SET @bolExistsData = 'False'
END


	IF @bolExistsData = 'True'
		BEGIN
			 SELECT 1 [IsOK]
			 SELECT	  tir.item_id,
					  tir.item_id_1,
					  tir.ir_qty

			  FROM tbItemReplacement tir		WITH (NOLOCK)

			  Where			tir.comp_id		=		@comp_id
			  AND			tir.item_id		=		@item_id
		END
	ELSE
		BEGIN
			SELECT 0 [IsOK]
		END




END

GO




CREATE PROCEDURE [dbo].[spItemReplacemente_GetCombo]
(
