CREATE PROCEDURE [dbo].[spItemReposition_getData]
(
	@comp_id				INT,
	@cust_id				INT,
	@stor_id				INT,
	@bra_id					INT,
	@OnlyItemswithStock		BIT,
	@datefrom				DATETIME,
	@dateto					DATETIME,
	@cb_id					INT,
	@guid					VARCHAR(50)


)
AS


BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON



	----------------------------------------------------------------------------
	-- TESTING
	----------------------------------------------------------------------------
	/*

	declare		@comp_id				INT,
				@cust_id				INT,
				@stor_id				INT,
				@bra_id					INT,
				@OnlyItemswithStock		BIT,
				@datefrom				DATETIME,
				@dateto					DATETIME,
				@cb_id					INT,
				@guid					VARCHAR(50)


	select		@comp_id			= 1,
				@cust_id			= 24294,
				@stor_id			= 3,
				@bra_id				= 1,
				@OnlyItemswithStock	= 'False',
				@datefrom			= '2010-01-10',
				@dateto				= '2015-12-31',
				@cb_id				= 46,
				@guid				= '79E0ABA5-39BE-4C3B-A512-6DD2E41C718F'
	*/
	----------------------------------------------------------------------------




	DECLARE @bitIsFromEnabled4ItemRepositionDocument AS BIT
	SET		@bitIsFromEnabled4ItemRepositionDocument = 'False'

	-- Si es negativo se usa para avisar que NO es un remito de transferencia sino un documento que habilita el boton de reposicion.
	IF @bra_id < 0
		BEGIN
			SET @bitIsFromEnabled4ItemRepositionDocument = 'True'
			SET @bra_id = @bra_id * -1
		END


	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid	  = @lGuid     AND
				  tcf.sl_selected = 'True'

	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

	DECLARE @intBraId4RepositionCheck AS INT
	SET @intBraId4RepositionCheck = NULL

	SELECT @intBraId4RepositionCheck = tb.bra_id
		FROM tbBranch2Customer4StockImport tb
		WHERE	tb.comp_id			= @comp_id AND
				tb.cust_id			= @cust_id AND
				tb.cb_id			= @cb_id   AND
				tb.bra_id_original	= @bra_id


	-- Si es por lo indicado arriba busca de la sucursal del combo.
	IF  @bitIsFromEnabled4ItemRepositionDocument = 'True'
		BEGIN
			SET @intBraId4RepositionCheck = @bra_id
		END



	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	set	@datefrom		= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto			= dbo.fnGetEnd_or_BeginOfDate(@dateto	,'True')




	SELECT	ti.item_id						[item_id],
			ti.item_desc					[item_desc],
			SUM(tit.it_price)				[it_price],
			SUM(tit.it_qty)					[it_qty],
			tit.curr_id						[curr_id]




		FROM tbCommercialTransactions									tct

		INNER JOIN tbCustomer											tc
		ON	tc.comp_id			= tct.comp_id			AND
			tc.cust_id			= tct.cust_id

		INNER JOIN tbItemTransactions									tit
		ON	tit.comp_id			= tct.comp_id			AND
			tit.bra_id			= tct.bra_id			AND
			tit.ct_transaction	= tct.ct_transaction

		--INNER JOIN tbItemStorage										tis
		--ON	tis.item_id			= tit.item_id			AND
		--	tis.stor_id			= tit.stor_id			AND
		--	tis.comp_id			= tit.comp_id

		INNER JOIN tbItem												ti
		ON	ti.comp_id			= tit.comp_id			AND
			ti.item_id			= tit.item_id

		INNER JOIN @tblComplexFilter_Items								tcf
		ON	tcf.item_id			= ti.item_id


		WHERE	tct.comp_id		=	@comp_id
		AND		tct.sd_id		IN (1,2) -- 1 Factura, 2 Remito
		AND		tct.bra_id		= @intBraId4RepositionCheck
		AND		tct.ct_date	between @datefrom and @dateto
		AND	   (tit.sdlmt_id IS NULL OR tit.sdlmt_id = 1) -- 1 Retira YA



		GROUP BY ti.item_id,
				 ti.item_desc,
				 tit.curr_id,
				 ti.cat_id,
				 ti.subcat_id,
				 ti.ic_id,
				 ti.item_desc

	HAVING
		CASE
			WHEN @OnlyItemswithStock = 'True' AND dbo.fnGetAStock(@comp_id, @stor_id, SUM(tit.it_qty), 99999999) > 0	THEN	1

			-- Este se pone porque si hay aunque sea uno para reponer manda la suma, queda en ROJO pero por lo menos se indica que hay algo como para reponer.
			WHEN @OnlyItemswithStock = 'True' AND dbo.fnGetAStock(@comp_id, @stor_id, 1, 99999999)				 > 0	THEN	1

			WHEN @OnlyItemswithStock = 'False'																			THEN	1
			ELSE																												0
		END	= 1

	ORDER BY	ti.cat_id,
				ti.subcat_id,
				ti.ic_id,
				ti.item_desc












END
GO

