-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spItems_funGetComboStorageByStorageGroup]
	@comp_id	AS INT,
	@storg_id	AS INT,
	@item_id	AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SELECT	ts.stor_id			[ID],
			ts.stor_desc		[Desc]
		FROM dbo.tbStorageGroupDetail	AS tsgd	WITH (NOLOCK)
		INNER JOIN dbo.tbStorage		AS ts	WITH (NOLOCK)
			ON	ts.comp_id = tsgd.comp_id AND
				ts.stor_id = tsgd.stor_id
		WHERE	tsgd.comp_id				= @comp_id		AND
				tsgd.storg_id				= @storg_id		AND
				ts.stor_disabled4Selection	= 'False'		AND
				dbo.fnGetAStock4MaxAssociation(tsgd.comp_id,tsgd.stor_id,@item_id,999999999) > 0
		ORDER BY tsgd.storg_order4SaleOrder	ASC


END
GO




