CREATE PROCEDURE [dbo].[spItems_GetAStock]
	@comp_id			INT,
	@item_id			INT,
	@stor_id			INT,
	@intPriority		INT

AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @decQTY AS DECIMAL(19,2)
	SELECT  @decQTY = IsNull(dbo.fnGetAStock(@comp_id, @stor_id,@item_id,@intPriority),0)

	SELECT  @decQTY

END
GO




