CREATE PROCEDURE [dbo].[spItems_GetImages4WebService]
(
	@comp_id				as INT,
	@bitOnlyNewOrUpdated	AS BIT,
	@item_id				AS INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	set nocount ON

	SELECT	ti.comp_id,
			ti.item_id,
			ti.item_picture,
			-1				[Order]
		FROM tbItem ti
		INNER JOIN tbCategory tc
			ON	tc.comp_id	= ti.comp_id AND
				tc.cat_id	= ti.cat_id
		INNER JOIN tbSubCategory tsc
			ON  tsc.comp_id		= ti.comp_id AND
				tsc.cat_id		= ti.cat_id  AND
				tsc.subcat_id   = ti.subcat_id

		INNER JOIN vwItemEnabledInBalance vieib
				ON	vieib.comp_id = ti.comp_id AND
					vieib.item_id = ti.item_id


		WHERE	ti.comp_id = @comp_id		AND
				ti.item_web		= 'true'	AND
				tc.cat_web		= 'True'	AND
				tsc.subcat_web	= 'True'	AND
				IsNull(ti.item_disabled,'False')			= 'False'  AND
				--IsNull(ti.item_disabledInBalance,'False')	= 'False'  AND
				(@bitOnlyNewOrUpdated = 'False' OR ti.item_RecentlyUpdated = 'True')	AND
				( @item_id = -1 OR  ti.item_id = @item_id )	AND
				ti.item_picture IS NOT NULL


	UNION ALL

		SELECT	tii.comp_id,
				tii.item_id,
				tii.itimg_image ,
				tii.itimg_order
			FROM tbItemImages tii
			INNER JOIN tbItem ti
				ON	ti.comp_id = tii.comp_id AND
					ti.item_id = tii.item_id
			INNER JOIN tbCategory tc
				ON	tc.comp_id	= ti.comp_id AND
					tc.cat_id	= ti.cat_id
			INNER JOIN tbSubCategory tsc
				ON  tsc.comp_id		= ti.comp_id AND
					tsc.cat_id		= ti.cat_id  AND
					tsc.subcat_id   = ti.subcat_id
			WHERE	ti.comp_id = @comp_id		AND
					ti.item_web		= 'true'	AND
					tc.cat_web		= 'True'	AND
					tsc.subcat_web	= 'True'	AND
					IsNull(ti.item_disabled,'False')			= 'False'  AND
					IsNull(ti.item_disabledInBalance,'False')	= 'False'  AND
					(@bitOnlyNewOrUpdated = 'False' OR ti.item_RecentlyUpdated = 'True') AND
					IsNull(tii.itimg_disabled,'False') = 'False'						 AND
					( @item_id = -1 OR  tii.item_id = @item_id )						 AND
					tii.itimg_image IS NOT NULL


--	-- Si pide solo los ULTIMOS modificados, borra el estado de modificados una vez que los lista.
--	IF @bitOnlyNewOrUpdated = 'True'
--		BEGIN
--			UPDATE tbitem SET item_RecentlyUpdated = 'False' WHERE comp_id = @comp_id
--		END

END





GO







CREATE PROCEDURE [dbo].[spItems_GetImages4WebService4MercadoLibre]
(
	@comp_id			 as INT,
	@item_id			 AS INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	set nocount ON

	SELECT	ti.item_id,
			ti.item_picture ,
			0					[Order]
		FROM tbItem ti								WITH (NOLOCK)

		INNER JOIN vwItemEnabled4MercadoLibre mle	WITH (NOLOCK)
			ON	mle.comp_id = ti.comp_id AND
				mle.item_id = ti.item_id


		WHERE	ti.comp_id = @comp_id						AND
			   (@item_id = -1 OR ti.item_id = @item_id)		AND
			   ti.item_picture IS NOT NULL

	UNION ALL


	SELECT	tii.item_id,
			tii.itimg_image,
			2+tii.itimg_order
		FROM tbItemImages tii						WITH (NOLOCK)
		INNER JOIN vwItemEnabled4MercadoLibre mle	WITH (NOLOCK)
			ON	mle.comp_id = tii.comp_id AND
				mle.item_id = tii.item_id

		WHERE	tii.comp_id = @comp_id						AND
			   (@item_id = -1 OR tii.item_id = @item_id)	AND
			    tii.itimg_disabled = 'False'				AND
			    tii.itimg_image IS NOT NULL


	ORDER BY [Order]


END





GO







