CREATE PROCEDURE [dbo].[spItems_GetItemIDFromCodeBQ]
(
	@comp_id				as INT,
	@item_code				AS NVARCHAR(50)
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	set nocount ON

	SELECT	ti.comp_id,
			ti.item_id
		FROM tbItem ti	WITH (NOLOCK)
		WHERE	ti.comp_id		= @comp_id		AND
				ti.item_code	= @item_code
END





GO







CREATE PROCEDURE [dbo].[spItems_GetStock4WebService]
(
	@comp_id		iNT,
	@stor_id		INT,
	@item_id		int
)
AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	set nocount ON

	SELECT  ti.item_id,
			CASE
				WHEN tis.stor_id IS NULL THEN	@stor_id
				ELSE							tis.stor_id
			END																[stor_id],
			ISNULL(tis.itst_cant,0)											[FS],
			dbo.fnGetAStock(@comp_id,
										CASE
											WHEN tis.stor_id IS NULL THEN	@stor_id
											ELSE							tis.stor_id
										END	,
							ti.item_id,
							99999999)										[PS],
			dbo.fnGetStockOfStorageGroup(	@comp_id,
											CASE
												WHEN tis.stor_id IS NULL THEN	@stor_id
												ELSE							tis.stor_id
											END,
											ti.item_id) 					[FS4StorageGroup],
			dbo.fnGetAStock4MaxAssociation(@comp_id,
											CASE
												WHEN tis.stor_id IS NULL THEN	@stor_id
												ELSE							tis.stor_id
											END,
											ti.item_id,
											99999999)						[Stock]
		FROM tbitem	ti												WITH (NOLOCK)
		LEFT JOIN  tbItemStorage tis								WITH (NOLOCK)
			ON	tis.comp_id = ti.comp_id and
				tis.item_id = ti.item_id and
				(@stor_id = -1 or TIS.stor_id = @stor_id)


	WHERE	ti.comp_id = @comp_id AND
			(
				CASE
					WHEN @stor_id = -1									THEN 1
					WHEN @stor_id <> -1 AND tis.stor_id IS NULL			THEN 1
					WHEN @stor_id <> -1 AND tis.stor_id IS NOT NULL AND tis.stor_id <> @stor_id		THEN 0
					ELSE 1
				END = 1
			)
			AND

			(
				@item_id = -1 OR ti.item_id  = @item_id
			)

END





GO







CREATE PROCEDURE [dbo].[spItems_GetStock4WebService4MercadoLibre]
(
	@comp_id		iNT,
	@stor_id		INT,
	@item_id		INT,
	@option			INT	-- 0: TODOS, 1: Solo con cambios, 2: Todos y guardar enviado
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------
	/*
	DECLARE
	@comp_id		INT,
	@stor_id		INT,
	@item_id		INT,
	@option			INT
	SET @comp_id = 1
	SET @stor_id = 28
	SET @item_id = -1
	SET @option  = 0
	*/
	-- -----------------------------------------------------------------------------


	-- para cagadas...
	IF @option > 2 OR @option < 0
		BEGIN
			SET @option  = 0
		END




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	set nocount ON



	DECLARE @tblItems TABLE(item_id	 INT  , stor_id INT,  UNIQUE NONCLUSTERED(item_id,stor_id))

	-- Inserta solo los que debe mostrar mas abajo
	INSERT INTO @tblItems(item_id, stor_id)
		SELECT	DISTINCT
				ml.item_id,
				CASE
					WHEN @stor_id = -1 THEN tis.stor_id
					ELSE @stor_id
				END
			FROM vwItemEnabled4MercadoLibre	ml							WITH (NOLOCK)
			LEFT JOIN  tbItemStorage tis								WITH (NOLOCK)
				ON	tis.comp_id = @comp_id and
					tis.item_id = ml.item_id and
					(@stor_id = -1 or TIS.stor_id = @stor_id)
			WHERE	ml.comp_id = @comp_id	AND
					(
						@item_id	= -1 OR
						ml.item_id	= @item_id
					)						AND
					(
					CASE
						WHEN @stor_id = -1									THEN 1
						WHEN @stor_id <> -1 AND tis.stor_id IS NULL			THEN 1
						WHEN @stor_id <> -1 AND tis.stor_id IS NOT NULL AND tis.stor_id <> @stor_id		THEN 0
						ELSE 1
					END = 1
					)						AND
					CASE
						WHEN @option = 0 THEN 1
						WHEN @option = 2 THEN 1
						WHEN @option = 1 AND dbo.fnGetAStock4MaxAssociation(@comp_id, tis.stor_id, tis.item_id, 99999999) <> ISNULL(tis.itst_LastQTYAtQuery,0) THEN 1
						ELSE 0
					END	= 1






	SELECT  ti.item_id,
			CASE
				WHEN tis.stor_id IS NULL THEN	@stor_id
				ELSE							tis.stor_id
			END																[stor_id],
			ISNULL(tis.itst_cant,0)											[FS],
			--fnGetAStock
			dbo.fnGetAStock4MaxAssociation(@comp_id,
										CASE
											WHEN tis.stor_id IS NULL THEN	@stor_id
											ELSE							tis.stor_id
										END	,
							ti.item_id,
							99999999)										[PS],
			dbo.fnGetStockOfStorageGroup(	@comp_id,
											CASE
												WHEN tis.stor_id IS NULL THEN	@stor_id
												ELSE							tis.stor_id
											END,
											ti.item_id) 					[FS4StorageGroup],
			dbo.fnGetAStock4MaxAssociation4Producteca(@comp_id,
										CASE
											WHEN tis.stor_id IS NULL THEN	@stor_id
											ELSE							tis.stor_id
										END	,
							ti.item_id,
							99999999)										[SD4Producteca]
		FROM tbitem	ti												WITH (NOLOCK)
		INNER JOIN @tblItems mle
			ON	mle.item_id = ti.item_id
		LEFT JOIN  tbItemStorage tis								WITH (NOLOCK)
			ON	tis.comp_id = @comp_id		and
				tis.item_id = mle.item_id	and
				tis.stor_id = mle.stor_id

		WHERE	ti.comp_id = @comp_id --AND
				--(
				--	CASE
				--		WHEN @stor_id = -1									THEN 1
				--		WHEN @stor_id <> -1 AND tis.stor_id IS NULL			THEN 1
				--		WHEN @stor_id <> -1 AND tis.stor_id IS NOT NULL AND tis.stor_id <> @stor_id		THEN 0
				--		ELSE 1
				--	END = 1
				--)
				--AND

				--(
				--	@item_id = -1 OR ti.item_id  = @item_id
				--)




	IF @option = 1 OR @option = 2
		BEGIN
			UPDATE tbItemStorage	WITH (ROWLOCK)
				SET itst_LastQTYAtQuery = dbo.fnGetAStock4MaxAssociation(@comp_id, its.stor_id, its.item_id, 99999999)
				FROM tbItemStorage its
				INNER JOIN @tblItems tmp
					ON	tmp.item_id = its.item_id AND
						tmp.stor_id = its.stor_id
				WHERE	its.comp_id = @comp_id
		END







END





GO







