	@item_newness				= 0,
	@item_outlet				= 0,
	@item_expser				= 0,
	@item_expean				= 1,
	@item_disabled				= 0,
	@item_comboDisc_Cant1		= 1,
	@item_comboDisc_Cant2		= 1,
	@item_comboDisc_Disc1		= 1,
	@item_comboDisc_Disc2		= 1,
	@item_purOrd_Disc1			= 1,
	@item_purOrd_Disc2			= 1,
	@item_purOrd_Disc3			= 1,
	@item_markup_1				= 0,
	@item_markup_2				= 0,
	@item_markup_3				= 0,
	@item_markup_4				= 0,
	@item_markup_5				= 0,
	@item_markup_6				= 0,
	@item_markup_7				= 0,
	@item_markup_8				= 0,
	@item_annotation1			='anotation1',
	@item_annotation2			='',
	@item_WebSite_desc			='',
	@item_WebSite_vendorPage	='',
	@item_WebSite_vendorDrivers	='@item_WebSite_vendorDrivers',
	@item_WebSite_url4Image1	='@item_WebSite_url4Image1',
	@item_WebSite_url4Image2	='@item_WebSite_url4Image2',
	@item_WebSite_url4Image3	='@item_WebSite_url4Image3',
	@item_WebSite_url4Image4	='@item_WebSite_url4Image4',
	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 10

*/
---------------------------------------------------------------------------------


set nocount on

BEGIN


	 --Si la categoría y la subcategoría  se importaron con sus importadores pueden tener un código original y
	 --tomará primero esa categoria y subcategoria relacionada a ese codigo original
	 IF @item_originalCODE <> ''
		BEGIN
			 declare @lcat_originalCODE			INT
			 declare @lsubcat_originalCODE		INT


			 SET @lcat_originalCODE		= -1
			 SET @lsubcat_originalCODE	= -1



			SET @lcat_originalCODE =  (SELECT top 1
											tc.cat_id
											FROM		tbSubCategory		tc		WITH (NOLOCK)
											WHERE	tc.comp_id					= @comp_id		AND
													tc.subcat_originalCODE		= @item_originalCODE)

			SET @lsubcat_originalCODE =  (SELECT top 1
											tc.subcat_id
											FROM tbSubCategory 		tc		WITH (NOLOCK)
											WHERE	tc.comp_id					= @comp_id		AND
													tc.subcat_originalCODE		= @item_originalCODE)

			if	@lcat_originalCODE		IS NULL  SET @lcat_originalCODE			= -1
			if	@lsubcat_originalCODE	IS NULL  SET @lsubcat_originalCODE		= -1


			IF @lcat_originalCODE <> -1
				BEGIN
					set @cat_id = @lcat_originalCODE
				END

			IF @lsubcat_originalCODE <> -1
				BEGIN
					set @subcat_id = @lsubcat_originalCODE
				END


		END


	declare @return_value	INT  = 0

	if	@bra_id			= -1  SET @bra_id		= NULL
	if	@subcataux_id	= -1  SET @subcataux_id = NULL
	if	@brag_id		= -1  SET @brag_id		= NULL
	if	@mu_id			= -1  SET @mu_id		= NULL

	if	@pd_id			= -1  SET @pd_id		= NULL
	if	@plm_id			= -1  SET @plm_id		= NULL
	SET @item_code		= dbo.fnStrAllTrim(@item_code)

	IF @itemAtrb1_id	= -1 SET @itemAtrb1_id = NULL
	IF @itemAtrb2_id	= -1 SET @itemAtrb2_id = NULL
	IF @itemAtrb3_id	= -1 SET @itemAtrb3_id = NULL
	IF @itemAtrb4_id	= -1 SET @itemAtrb4_id = NULL
	IF @tipi_id			= -1 SET @tipi_id	   = NULL

	BEGIN TRY


		-- Si YA existe NO usa el TRY como IF, YA SE DIJO QUE NO SE DEBE HACER MAS DE 500 VECES !!!
		IF EXISTS(
					SELECT TOP 1 1
						FROM tbItem AS ti	WITH (NOLOCK)
						WHERE	ti.comp_id		= @comp_id AND
								ti.item_code	= @item_code
				)
			BEGIN
				SELECT  0
				RETURN
			END


		INSERT INTO tbItem WITH (ROWLOCK)
			(
				comp_id,bra_id,item_code, cat_id, subcat_id,
				subcataux_id, ic_id, item_desc, item_detail,
				item_vendorCode, brand_id, pres_id,item_codeAlternative,
				curr_id,supp_id, item_trigger_tax_id, item_upb,
				item_upp, item_mult, item_commission,item_commission_byReceive,
				item_liquidation, item_newness,item_outlet,item_expser,
				item_expean, item_disabled,
				item_made ,item_withdecimal,item_disabledInBalance,
				item_comboDisc_Desc1,item_comboDisc_Desc2,item_comboDisc_Desc3,item_comboDisc_Desc4,
				item_comboDisc_Cant1,item_comboDisc_Cant2,item_comboDisc_Cant3,item_comboDisc_Cant4,
				item_comboDisc_Disc1,item_comboDisc_Disc2,item_comboDisc_Disc3,item_comboDisc_Disc4,
				item_purOrd_Disc1,item_purOrd_Disc2,item_purOrd_Disc3,item_purOrd_Disc4,
				item_purOrd_surcharge1,item_purOrd_surcharge2,item_purOrd_surcharge3,item_purOrd_surcharge4,
				item_markup_1, item_markup_2, item_markup_3,
				item_markup_4,item_markup_5,item_markup_6,item_markup_7,
				item_markup_8,
				item_markup_9, item_markup_10, item_markup_11,
				item_markup_12,item_markup_13,item_markup_14,item_markup_15,
				item_markup_16,
				item_web,item_annotation1,item_annotation2,item_WebSite_desc,
				item_WebSite_vendorPage,item_WebSite_vendorDrivers, item_WebSite_url4Image1,
				item_WebSite_url4Image2,item_WebSite_url4Image3,item_WebSite_url4Image4,
				item_WebSite_url4Image5,item_descHTML,
				brag_id,
				item_cantMin,item_cantOpt,item_guarantee,item_annotation,item_higth,
				item_large,item_wide,mu_id,item_weight,item_volume,item_isEW,item_ML_isAvailable,item_ML_desc,
				pd_id,plm_id, item_ML_title,item_web_groupingCode,item_originalCODE, item_isForAssociation_disablePrintOfAssociatedItems,
				itemAtrb1_id, item_ChkAtrb1,
				itemAtrb2_id, item_ChkAtrb2,
				itemAtrb3_id, item_ChkAtrb3,
				itemAtrb4_id, item_ChkAtrb4,
				tipi_id,
				item_discountByItem,
				item_discountByItem2,
				item_comboDisc_Desc5,
				item_comboDisc_Desc6,
				item_comboDisc_Cant5,
				item_comboDisc_Cant6,
				item_comboDisc_Disc5,
				item_comboDisc_Disc6

			)
			VALUES
			(
				@comp_id,@bra_id,dbo.fnStrAllTrim(@item_code), @cat_id, @subcat_id,
				@subcataux_id, @ic_id, @item_desc, @item_detail,
				@item_vendorCode, @brand_id, @pres_id,@item_codeAlternative,
				@curr_id,@supp_id, @item_trigger_tax_id, @item_upb,
				@item_upp, @item_mult, @item_commission,@item_commission_byReceive,
				@item_liquidation, @item_newness,@item_outlet,@item_expser,
				@item_expean, @item_disabled,
				@item_made ,@item_withdecimal,@item_disabledInBalance,
				@item_comboDisc_Desc1,@item_comboDisc_Desc2,@item_comboDisc_Desc3,@item_comboDisc_Desc4,
				@item_comboDisc_Cant1,@item_comboDisc_Cant2,@item_comboDisc_Cant3,@item_comboDisc_Cant4,
				@item_comboDisc_Disc1,@item_comboDisc_Disc2,@item_comboDisc_Disc3,@item_comboDisc_Disc4,
				@item_purOrd_Disc1,@item_purOrd_Disc2,@item_purOrd_Disc3,@item_purOrd_Disc4,
				@item_purOrd_surcharge1,@item_purOrd_surcharge2,@item_purOrd_surcharge3,@item_purOrd_surcharge4,
				@item_markup_1, @item_markup_2, @item_markup_3,
				@item_markup_4,@item_markup_5,@item_markup_6,@item_markup_7,
				@item_markup_8,
				@item_markup_9, @item_markup_10, @item_markup_11,
				@item_markup_12,@item_markup_13,@item_markup_14,@item_markup_15,
				@item_markup_16,
				@item_web,@item_annotation1,@item_annotation2,@item_WebSite_desc,
				@item_WebSite_vendorPage,@item_WebSite_vendorDrivers,@item_WebSite_url4Image1,
				@item_WebSite_url4Image2,@item_WebSite_url4Image3,@item_WebSite_url4Image4,
				@item_WebSite_url4Image5,@item_descHTML,
				@brag_id,
				@item_cantMin,@item_cantOpt,@item_guarantee,@item_annotation,@item_higth,
				@item_large,@item_wide,@mu_id,@item_weight,@item_volume,'False',@item_ML_isAvailable,@item_ML_desc,
				@pd_id,@plm_id, @item_ml_title,@item_web_groupingCode,@item_originalCODE, 'False',
				@itemAtrb1_id, 	@intUseAttribute1,
				@itemAtrb2_id, 	@intUseAttribute2,
				@itemAtrb3_id, 	@intUseAttribute3,
				@itemAtrb4_id,  @intUseAttribute4,
				@tipi_id,
				@item_discountByItem,
				@item_discountByItem2,
				@item_comboDisc_Desc5,
				@item_comboDisc_Desc6,
				@item_comboDisc_Cant5,
				@item_comboDisc_Cant6,
				@item_comboDisc_Disc5,
				@item_comboDisc_Disc6
			)


			SELECT 1 -- IDENT_CURRENT('tbItem')   -- @@identity
			SET @return_value = IDENT_CURRENT('tbItem')


			-- Se puso esto por separado ya que se importaba en TRUE y no se encontró donde se ponía ese valor.
			--UPDATE tbItem
			--	SET item_disablePrintInDocumentsPrint = 'False'
			--	WHERE	comp_id = @comp_id AND
			--			item_id = @return_value




			-- ---------------------------------------------------------------------------------
			-- EAN ADICIONAL / DUN
			-- ---------------------------------------------------------------------------------
			IF @strItemEanAdicional <> ''
				BEGIN

					IF @strItemEanDUN = '0'
						BEGIN
							SET @intItemDUNQty = 0
						END


					INSERT INTO tbItemEAN
					(
						comp_id,
						-- ie_id -- this column value is auto-generated
						item_id,
						ie_ean,
						ie_DUNQty
					)
					VALUES
					(
						@comp_id,
						@return_value,
						@strItemEanAdicional,
						@intItemDUNQty
					)
				END
			-- ---------------------------------------------------------------------------------



		END TRY
		BEGIN CATCH
			SELECT  0
		END CATCH

		IF @return_value <> 0
			BEGIN
				EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,@return_value,NULL
			END



END


















GO





