	@item_comboDisc_Desc3										NVARCHAR(200),
	@item_comboDisc_Desc4										NVARCHAR(200),

	@item_comboDisc_Cant1										DECIMAL(18,2),
	@item_comboDisc_Cant2										DECIMAL(18,2),
	@item_comboDisc_Cant3										DECIMAL(18,2),
	@item_comboDisc_Cant4										DECIMAL(18,2),

	@item_comboDisc_Disc1										DECIMAL(18,4),
	@item_comboDisc_Disc2										DECIMAL(18,4),
	@item_comboDisc_Disc3										DECIMAL(18,4),
	@item_comboDisc_Disc4										DECIMAL(18,4),

	@item_purOrd_Disc1											DECIMAL(18,4),
	@item_purOrd_Disc2											DECIMAL(18,4),
	@item_purOrd_Disc3											DECIMAL(18,4),
	@item_purOrd_Disc4											DECIMAL(18,4),

	@item_purOrd_surcharge1										DECIMAL(18,4),
	@item_purOrd_surcharge2										DECIMAL(18,4),
	@item_purOrd_surcharge3										DECIMAL(18,4),
	@item_purOrd_surcharge4										DECIMAL(18,4),


	@item_markup_1												DECIMAL(19,8),
	@item_markup_2												DECIMAL(19,8),
	@item_markup_3												DECIMAL(19,8),
	@item_markup_4												DECIMAL(19,8),
	@item_markup_5												DECIMAL(19,8),
	@item_markup_6												DECIMAL(19,8),
	@item_markup_7												DECIMAL(19,8),
	@item_markup_8												DECIMAL(19,8),
	@item_markup_9												DECIMAL(19,8),
	@item_markup_10												DECIMAL(19,8),
	@item_markup_11												DECIMAL(19,8),
	@item_markup_12												DECIMAL(19,8),
	@item_markup_13												DECIMAL(19,8),
	@item_markup_14												DECIMAL(19,8),
	@item_markup_15												DECIMAL(19,8),
	@item_markup_16												DECIMAL(19,8),

	@item_web													INT,
	@item_annotation1											NVARCHAR(4000),
	@item_annotation2											NVARCHAR(4000),
	@item_WebSite_desc											NVARCHAR(100),
	@item_WebSite_vendorPage									NVARCHAR(300),
	@item_WebSite_vendorDrivers									NVARCHAR(300),

	@item_WebSite_url4Image1									NVARCHAR(150),
	@item_WebSite_url4Image2									NVARCHAR(150),
	@item_WebSite_url4Image3									NVARCHAR(150),
	@item_WebSite_url4Image4									NVARCHAR(150),
	@item_WebSite_url4Image5									NVARCHAR(150),

	@item_descHTML												NVARCHAR(4000),
	@brag_id													INT,
	@guid														UNIQUEIDENTIFIER,
	@intROW														INT,
	@bra_id														INT,
	@bolIsOK													BIT,
	@item_cantMin												DECIMAL(18,4),
	@item_cantOpt												DECIMAL(18,4),
	@item_guarantee												INT,
	@item_annotation											NVARCHAR(4000),
	@item_higth													DECIMAL(21,9),
	@item_large													DECIMAL(21,9),
	@item_wide   												DECIMAL(21,9),
	@mu_id														INT,
	@item_weight												DECIMAL(21,9),
	@item_volume												DECIMAL(21,9),
	@item_ML_isAvailable										INT,
	@item_ML_desc												NVARCHAR(MAX),

	@plm_id														INT,
	@pd_id														INT,
	@item_ml_title												NVARCHAR(200),
	@item_web_title												NVARCHAR(250),
	@item_web_metaKeywords										NVARCHAR(250),
	@item_web_metaDescription									NVARCHAR(1000),

	@item_WebSite_leading											INT,
	@item_WebSite_HidePrices										INT,
	@item_WebSite_HideTaxes											INT,

	@item_ML_html4Publication										NVARCHAR(4000),
	@item_ML_url4video												NVARCHAR(50),
	@item_web_groupingCode											NVARCHAR(30),
	@item_repositionTime											DECIMAL(18,4),
	@item_GrowExpected												DECIMAL(18,4),
	@item_ifHasItemAssociationSumPrices								INT,
	@itemAtrb1_id													INT,
	@itemAtrb2_id													INT,
	@itemAtrb3_id													INT,
	@itemAtrb4_id													INT,
	@bolItem_ChkAtrb1												INT,
	@bolItem_ChkAtrb2												INT,
	@bolItem_ChkAtrb3												INT,
	@bolItem_ChkAtrb4												INT,
	@posara_id														INT,
	@bolItem_isAvailable4Community									INT,				-- Item_isAvailable4Community
	@bolitem_isAvailable4FullJaus									INT,				-- item_isAvailable4FullJaus
	@stor_id														INT,
	@intitem_isForAssociation_triggerRules4NOPriceListSUM			INT,
	@decitem_isForAssociation_discountPercentage4PriceListSUM		DECIMAL(18,4),
	@tipi_id														INT,				-- Tipo de Item
	@intitem_isForAssociation_disablePrintOfAssociatedItems			INT,
	@item_not4Purchase												INT,
	@item_WebSite_order												INT,
	@bolitem_SaleOrderSaveAndEmmition_BlockStockChk					INT,				-- Deshabilitar el Comportamiento definido en:  Documentos Solapa Pedidos, Controles de Stock (CTRLSTK)
	@bolbra_SaleOrderBlockItemsWithNOPotentialStock_BlockStockChk	INT,				-- Deshabilitar el Comportamiento definido en: Sucursales Solapa Ventas IV, (Ver Nota) (CTRLSTK I)
	@item_discountByItem											DECIMAL(10,4),
	@item_discountByItem2											DECIMAL(10,4),

	@item_comboDisc_Desc5											NVARCHAR(200),
	@item_comboDisc_Desc6											NVARCHAR(200),

	@item_comboDisc_Cant5											DECIMAL(18,2),
	@item_comboDisc_Cant6											DECIMAL(18,2),

	@item_comboDisc_Disc5											DECIMAL(18,4),
	@item_comboDisc_Disc6											DECIMAL(18,4)
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ESTO ES LO QUE ESTABA MAL
		-- PONIA EN NULL LOS CAMPOS ESTOS, ESTABA DESDE UN PRINCIPIO PERO NADIE USABA ESTOS CAMPOS ENTONCES
		-- SALTO EL PROBLEMA CON UNA EMPRESA
		-- STL 21-05-2020
		IF	@bra_id			= -2  SET @bra_id		= NULL
		IF	@subcataux_id	= -2  SET @subcataux_id = NULL
		IF	@brag_id		= -2  SET @brag_id		= NULL
		IF  @stor_id		= -2  SET @stor_id		= NULL
		--IF	@mu_id			= -1  SET @mu_id		= NULL
		--IF	@pd_id			= -1  SET @pd_id		= NULL
		--IF	@plm_id			= -1  SET @plm_id		= NULL

		-- ------------------------------------------------
		-- VARIABLES BOOLEAN LOCALES
		-- ------------------------------------------------
		DECLARE
			@Local_item_liquidation									BIT,
			@Local_item_newness										BIT,
			@Local_item_outlet										BIT,
			@Local_item_expser										BIT,
			@Local_item_expean										BIT,
			@Local_item_disabled									BIT,
			@Local_item_made										BIT,
			@Local_item_withdecimal									BIT,
			@Local_item_disabledInBalance							BIT,
			@Local_item_web											BIT,
			@Local_item_ML_isAvailable								BIT,
			@Local_item_WebSite_leading								BIT,
			@Local_item_WebSite_HidePrices							BIT,
			@Local_item_WebSite_HideTaxes							BIT,
			@Local_bolItem_ChkAtrb1									BIT,
			@Local_bolItem_ChkAtrb2									BIT,
			@Local_bolItem_ChkAtrb3									BIT,
			@Local_bolItem_ChkAtrb4									BIT,
			@Local_bolItem_isAvailable4Community					BIT,
			@Local_bolitem_not4Purchase								BIT,
			@Local_bolitem_SaleOrderSaveAndEmmition_BlockStockChk					BIT,
			@Local_bolbra_SaleOrderBlockItemsWithNOPotentialStock_BlockStockChk		BIT


			IF @item_liquidation		<> -1
				BEGIN
					SET @Local_item_liquidation = CONVERT(BIT, @item_liquidation)
				END

			IF @item_newness			<> -1
				BEGIN
					SET @Local_item_newness = CONVERT(BIT, @item_newness)
				END

			IF @item_outlet				<> -1
				BEGIN
					SET @Local_item_outlet = CONVERT(BIT, @item_outlet)
				END

			IF @item_expser				<> -1
				BEGIN
					SET @Local_item_expser = CONVERT(BIT, @item_expser)
				END

			IF @item_expean				<> -1
				BEGIN
					SET @Local_item_expean = CONVERT(BIT, @item_expean)
				END

			IF @item_disabled			<> -1
				BEGIN
					SET @Local_item_disabled = CONVERT(BIT, @item_disabled)
				END

			IF @item_made				<> -1
				BEGIN
					SET @Local_item_made = CONVERT(BIT, @item_made)
				END

			IF @item_withdecimal		<> -1
				BEGIN
					SET @Local_item_withdecimal = CONVERT(BIT, @item_withdecimal)
				END

			IF @item_disabledInBalance	<> -1
				BEGIN
					SET @Local_item_disabledInBalance = CONVERT(BIT, @item_disabledInBalance)
				END

			IF @item_web				<> -1
				BEGIN
