			item_WebSite_order					=	CASE WHEN @item_WebSite_order				= -1	THEN item_WebSite_order					ELSE @item_WebSite_order					END



			WHERE	comp_id				= @comp_id AND
					item_id				= @item_id

	END
GO


CREATE PROCEDURE [dbo].[spItems_Process_Auto_MassiveUpdate_Validate]
(
	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,
	@item_id					INT,

	@item_code					NVARCHAR(50),
	@cat_id						INT,
	@subcat_id					INT,
	@subcataux_id				INT,
	@ic_id						INT,
	@brand_id					INT,
	@pres_id					INT,
	@supp_id					INT,
	@item_trigger_tax_id		INT,
	@brag_id					INT,
	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT,
	@mu_id						INT,
	@plm_id						INT,
	@pd_id						INT,
	@itemAtrb1_id				INT,
	@itemAtrb2_id				INT,
	@itemAtrb3_id				INT,
	@itemAtrb4_id				INT,
	@posara_id					INT,
	@stor_id					INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------------------------------------
		-- PARAMETROS DE TESTING
		-- -------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id					INT,
				@lang_id					INT,
				@bra_id4session				INT,
				@user_id					INT,
				@prof_id					INT,
				@item_id					INT,

				@item_code					NVARCHAR(50),
				@cat_id						INT,
				@subcat_id					INT,
				@subcataux_id				INT,
				@ic_id						INT,
				@brand_id					INT,
				@pres_id					INT,
				@supp_id					INT,
				@item_trigger_tax_id		INT,
				@brag_id					INT,
				@guid						UNIQUEIDENTIFIER,
				@intROW						INT,
				@bra_id						INT,
				@mu_id						INT,
				@plm_id						INT,
				@pd_id						INT
		SELECT
				@comp_id					= 1,
				@lang_id					= 2,
				@bra_id4session				= 1,
				@user_id					= 119,
				@prof_id					= 1,
				@item_id					= 15625,

				@item_code					= '',
				@cat_id						= -1,
				@subcat_id					= -1,
				@subcataux_id				= -1,
				@ic_id						= -1,
				@brand_id					= -1,
				@pres_id					= -1,
				@supp_id					= -1,
				@item_trigger_tax_id		= -1,
				@brag_id					= -1,
				@guid						= '0f843892-62a9-4121-8a0a-d777c30df421',
				@intROW						= 10,
				@bra_id						= 4,
				@mu_id						= -1,
				@plm_id						= -1,
				@pd_id						= -1
		*/
		-- -------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

			DECLARE @errormessage   NVARCHAR(4000)
			DECLARE @return_value	INT
			DECLARE @bolIsOK		BIT

			SET     @bolIsOK		= 'True'
			SET		@errormessage	= ''

			-- ------------------------------------------------------------------------------------------------------------
			-- SUCURSAL
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@bra_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT
									1
									FROM tbBranch tb
									WHERE	tb.comp_id	= @comp_id AND
											tb.bra_id	= @bra_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Sucursal ingresado No existe'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- CODIGO DEL ARTICULO
			-- ------------------------------------------------------------------------------------------------------------
			IF (@item_code <> '')
				BEGIN
					IF EXISTS (SELECT
								ti.item_id
								FROM		tbItem						ti		WITH (NOLOCK)
								WHERE	ti.comp_id		= @comp_id		AND 
										ti.item_code	= @item_code	AND
										ti.item_id		<> @item_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El Código/EAN del Artículo ya está asociado a otro artículo'
						END

					IF EXISTS (SELECT
								tie.item_id
								FROM tbItemEAN						tie WITH(NOLOCK)
								WHERE	tie.comp_id	= @comp_id		AND
										tie.ie_ean	= @item_code)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El Código/EAN del Artículo ya está asociado como EAN adicional a otro artículo'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- CATEGORIA
			-- ------------------------------------------------------------------------------------------------------------
			IF (@cat_id <> -1)
				BEGIN
					IF NOT EXISTS (SELECT tc.cat_id
								   FROM		tbCategory		tc		WITH (NOLOCK)
									WHERE	tc.comp_id		= @comp_id		AND
											tc.cat_id		= @cat_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Categoría es incorrecto'
						END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- SUBCATEGORIA
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@subcat_id	<> -1)
				BEGIN
					IF NOT EXISTS (SELECT tsc.subcat_id
								   FROM		tbSubCategory	tsc		WITH (NOLOCK)
									WHERE	tsc.comp_id		= @comp_id		AND
											tsc.cat_id		= @cat_id		AND
											tsc.subcat_id	= @subcat_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de SubCategoría es incorrecto o no está relacionada a la Categoría'
						END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- CLASE DE ARTICULO
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@ic_id	<> -1)
				BEGIN
					IF NOT EXISTS (SELECT tic.ic_id
								   FROM		tbItemClass tic		WITH (NOLOCK)
									WHERE	tic.comp_id		= @comp_id		AND
											tic.ic_id		= @ic_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Clase es incorrecto'
						END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- MARCA
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@brand_id	<> -1)
				BEGIN
					IF NOT EXISTS (SELECT ttn.brand_id
								   FROM		tbBrand 		ttn			WITH (NOLOCK)
									WHERE	ttn.comp_id		= @comp_id		AND
											ttn.brand_id	= @brand_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Marca es incorrecto'
						END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- PRESENTACION
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@pres_id	<> -1)
				BEGIN
					IF NOT EXISTS (SELECT ttn.pres_id
								   FROM		tbPresentation  		ttn		WITH (NOLOCK)
									WHERE	ttn.comp_id		= @comp_id		AND
											ttn.pres_id		= @pres_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Presentación es incorrecto'
						END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- PROVEEDOR
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@supp_id	<> -1)
				BEGIN
					IF NOT EXISTS (SELECT ts.supp_id
								   FROM tbSupplier ts		WITH (NOLOCK)
									WHERE	ts.comp_id		= @comp_id		AND
											ts.supp_id		= @supp_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Proveedor es incorrecto'
						END
				END
			-- ------------------------------------------------------------------------------------------------------------


			-- ------------------------------------------------------------------------------------------------------------
			-- GRUPO DE SUCURSALES
			-- ------------------------------------------------------------------------------------------------------------
			--IF	(@brag_id	<> -1)
			IF	(@brag_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT tbg.brag_id
								   FROM tbBranchGroup tbg		WITH (NOLOCK)
								WHERE	tbg.comp_id		= @comp_id AND
										tbg.brag_id		= @brag_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Grupo de Sucursales es incorrecto'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------


			-- ------------------------------------------------------------------------------------------------------------
			-- ID INCREMENTOS / MARKUP
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@plm_id	<> -1)
				BEGIN
					IF NOT EXISTS (SELECT tplm.plm_id
								   FROM tbPriceListMarkup tplm	WITH (NOLOCK)
								WHERE	tplm.comp_id	= @comp_id AND
										tplm.plm_id		= @plm_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Incrementos / Markup es incorrecto'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- DESCUENTOS POR COMPRAS
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@pd_id	<> -1)
				BEGIN
					IF NOT EXISTS (SELECT tpd.pd_id
								   FROM tbPurchaseDiscount tpd		WITH (NOLOCK)
								WHERE	tpd.comp_id		= @comp_id AND
										tpd.pd_id		= @pd_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Descuento por Compras es incorrecto'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- UNIDAD DE MEDIDA
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@mu_id	<> -1)
				BEGIN
					IF NOT EXISTS (SELECT tmu.mu_id
								   FROM tbMetricUnits	tmu 		WITH (NOLOCK)
								WHERE	tmu.comp_id		= @comp_id AND
										tmu.mu_id		= @mu_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Unidad de Medida es incorrecto'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			------Impuesto-----------------------------------------------------------------------------------------------------------
			IF	(@item_trigger_tax_id	<> -1)
				BEGIN
					IF NOT EXISTS (SELECT ttn.tax_id
									FROM	tbTaxName		ttn			WITH (NOLOCK)
									WHERE	ttn.comp_id		= @comp_id		AND
											ttn.tax_id		= @item_trigger_tax_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Impuesto es incorrecto'
						END
				END
			-----------------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- Atributos del Artículo 1
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@itemAtrb1_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT
										1
										FROM tbItem_AddAttributes1				tiaa	WITH(NOLOCK)
										WHERE	tiaa.comp_id		= @comp_id	AND
												tiaa.itemAtrb1_id	= @itemAtrb1_id
								  )
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Atributos del Artículo 1 es incorrecto'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- Atributos del Artículo 2
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@itemAtrb2_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT
										1
										FROM tbItem_AddAttributes2				tiaa	WITH(NOLOCK)
										WHERE	tiaa.comp_id		= @comp_id	AND
												tiaa.itemAtrb2_id	= @itemAtrb2_id
								  )
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Atributos del Artículo 2 es incorrecto'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- Atributos del Artículo 3
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@itemAtrb3_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT
										1
										FROM tbItem_AddAttributes3				tiaa	WITH(NOLOCK)
										WHERE	tiaa.comp_id		= @comp_id	AND
												tiaa.itemAtrb3_id	= @itemAtrb3_id
								  )
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Atributos del Artículo 3 es incorrecto'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- Atributos del Artículo 4
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@itemAtrb4_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT
										1
										FROM tbItem_AddAttributes4				tiaa	WITH(NOLOCK)
										WHERE	tiaa.comp_id		= @comp_id	AND
												tiaa.itemAtrb4_id	= @itemAtrb4_id
								  )
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Atributos del Artículo 4 es incorrecto'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- Posición Arancelaria
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@posara_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT
										1
					               FROM tbImport_tariffPosition			titp	WITH(NOLOCK)
					               WHERE	titp.comp_id	= @comp_id	AND
											titp.posara_id	= @posara_id
								  )
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Posición Arancelaria es incorrecto'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------
			-- Depòsito
			-- ------------------------------------------------------------------------------------------------------------
			IF	(@stor_id	> 0)
				BEGIN
					IF NOT EXISTS (SELECT
										1
					               FROM tbStorage AS ts
					               WHERE	ts.comp_id = @comp_id AND
											ts.stor_id = @stor_id
								  )
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Depósito es incorrecto'
					END
				END
			-- ------------------------------------------------------------------------------------------------------------



			-- ------------------------------------------------------------------------------------------------------------
			-- ATENCION! NO PONER NADA DEBAJO DE ESTO
			-- ------------------------------------------------------------------------------------------------------------
			-- si no viene nada del excel para estos campos le pondra 0 : @item_upb	,@item_mult

			-- 1 True  : Todo ok para ACTUALIZAR.
			-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la ACTUALIZACIÓN.
			IF (@bolIsOK = 'True')
				BEGIN
					SELECT
						1				[bolIsOK],
						@intROW			[Nº Fila],
						@errormessage	[Error]
				END
			ELSE
				BEGIN

					EXEC [spItems_Process_ImportLog_InsertData] @comp_id, @guid, @user_id, @intROW, NULL, @errormessage

					SELECT
						0				[bolIsOK],
						@intROW			[Nº Fila],
						@errormessage	[Error]
				END
			-- ------------------------------------------------------------------------------------------------------------



	END



















GO





