	@item_WebSite_desc			NVARCHAR(100),
	@item_WebSite_vendorPage	NVARCHAR(300),
	@item_WebSite_vendorDrivers	NVARCHAR(300),
	@item_WebSite_url4Image1	NVARCHAR(150),
	@item_WebSite_url4Image2	NVARCHAR(150),
	@item_WebSite_url4Image3	NVARCHAR(150),
	@item_WebSite_url4Image4	NVARCHAR(150),
	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT



SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,

	@item_code					='D1',
	@cat_id						= 4078 ,
	@subcat_id					= 3823 ,
	@subcataux_id				= -1 ,
	@ic_id						= 2  ,
	@item_desc					='desc',
	@item_detail				='detail',
	@item_vendorCode			='vendor code',
	@brand_id					= 75 ,
	@pres_id					= 69,
	@item_codeAlternative		='alternative code',
	@curr_id					= 1,
	@supp_id					= 8110 ,
	@item_trigger_tax_id		= 1,
	@item_upb					= 1,
	@item_upp					= 1,
	@item_mult					= 1,
	@item_commission			= 1,
	@item_commission_byReceive  = 1,
	@item_liquidation			= 1,
	@item_newness				= 0,
	@item_outlet				= 0,
	@item_expser				= 0,
	@item_expean				= 1,
	@item_disabled				= 0,
	@item_comboDisc_Cant1		= 1,
	@item_comboDisc_Cant2		= 1,
