	@item_comboDisc_Disc2		= 1,
	@item_purOrd_Disc1			= 1,
	@item_purOrd_Disc2			= 1,
	@item_purOrd_Disc3			= 1,
	@item_markup_1				= 0,
	@item_markup_2				= 0,
	@item_markup_3				= 0,
	@item_markup_4				= 0,
	@item_markup_5				= 0,
	@item_markup_6				= 0,
	@item_markup_7				= 0,
	@item_markup_8				= 0,
	@item_annotation1			='anotation1',
	@item_annotation2			='',
	@item_WebSite_desc			='',
	@item_WebSite_vendorPage	='',
	@item_WebSite_vendorDrivers	='@item_WebSite_vendorDrivers',
	@item_WebSite_url4Image1	='@item_WebSite_url4Image1',
	@item_WebSite_url4Image2	='@item_WebSite_url4Image2',
	@item_WebSite_url4Image3	='@item_WebSite_url4Image3',
	@item_WebSite_url4Image4	='@item_WebSite_url4Image4',
	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 10,
	@bra_id4session				= 1

*/
---------------------------------------------------------------------------------


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


set nocount on

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''


	declare @lcat_originalCODE			INT
	declare @lsubcat_originalCODE		INT

	SET @lcat_originalCODE		= -1
	SET @lsubcat_originalCODE	= -1

	 --Si la categoría y la subcategoría  se importaron con sus importadores pueden tener un código original y
	 --tomará primero esa categoria y subcategoria relacionada a ese codigo original
	 IF @item_originalCODE <> ''
		BEGIN

			SET @lcat_originalCODE =  (SELECT top 1
											tc.cat_id
											FROM		tbSubCategory		tc		WITH (NOLOCK)
											WHERE	tc.comp_id					= @comp_id		AND
													tc.subcat_originalCODE		= @item_originalCODE)

			SET @lsubcat_originalCODE =  (SELECT top 1
											tc.subcat_id
											FROM tbSubCategory 		tc		WITH (NOLOCK)
											WHERE	tc.comp_id					= @comp_id		AND
													tc.subcat_originalCODE		= @item_originalCODE)

			if	@lcat_originalCODE		IS NULL  SET @lcat_originalCODE			= -1
			if	@lsubcat_originalCODE	IS NULL  SET @lsubcat_originalCODE		= -1


			--IF @lcat_originalCODE <> -1
			--	BEGIN
			--		set @cat_id = @lcat_originalCODE
			--	END

			--IF @lsubcat_originalCODE <> -1
			--	BEGIN
			--		set @subcat_id = @lsubcat_originalCODE
			--	END


		END



	------Sucursal-----------------------------------------------------------------------------------------------------------
	if	@bra_id	= 0
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Sucursal'
		END
	ELSE
	BEGIN
		if	@bra_id	<> -1
			BEGIN

				IF NOT EXISTS (SELECT TOP 1 tb.bra_id
								FROM tbBranch tb		WITH (NOLOCK)
								WHERE	tb.comp_id		= @comp_id		AND
										tb.bra_id		= @bra_id)
					BEGIN
						SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + 'El ID de Sucursal es incorrecto'
					END
			END

		END

	-----------------------------------------------------------------------------------------------------------------------


	------Codigo-----------------------------------------------------------------------------------------------------------
	if	@item_code	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Código/EAN del Artículo'
		END
	ELSE
	BEGIN
		IF @bitErrorItemCode = 'False'
		BEGIN
			IF EXISTS (SELECT TOP 1  ti.item_id
			               FROM		tbItem			ti		WITH (NOLOCK)
							WHERE	ti.comp_id		= @comp_id		AND
									ti.item_code	= @item_code)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El Código/EAN del Artículo ya existe'
				END

		END
	END

	-----------------------------------------------------------------------------------------------------------------------


	------Categoria-----------------------------------------------------------------------------------------------------------

	IF @lcat_originalCODE = -1
				BEGIN
					if	@cat_id	= -1
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Categoría'
						END
					ELSE
						BEGIN
							IF NOT EXISTS (SELECT TOP 1  tc.cat_id
										   FROM		tbCategory		tc		WITH (NOLOCK)
											WHERE	tc.comp_id		= @comp_id		AND
													tc.cat_id		= @cat_id)
								BEGIN
									SET	@bolIsOK		= 'False'
									SET @errormessage	= @errormessage + '---' + 'El ID de Categoría es incorrecto'
								END
						END
				END

	-----------------------------------------------------------------------------------------------------------------------

	------Subcategoria-----------------------------------------------------------------------------------------------------------
	IF @lsubcat_originalCODE = -1
	BEGIN
			if	@subcat_id	= -1
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'No ingresó el ID SubCategoría'
				END
			ELSE
				BEGIN
					IF NOT EXISTS (SELECT TOP 1  tsc.subcat_id
									   FROM		tbSubCategory	tsc		WITH (NOLOCK)
										WHERE	tsc.comp_id		= @comp_id		AND
												tsc.cat_id		= @cat_id		AND
												tsc.subcat_id	= @subcat_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de SubCategoría es incorrecto o no está relacionada a la Categoría'
						END
				END
	END

	-----------------------------------------------------------------------------------------------------------------------

	------Subcategoria Aux-----------------------------------------------------------------------------------------------------------
	IF	@subcataux_id	<> -1
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  tsc.subcataux_id
							   FROM tbSubCategoryAux 	tsc		WITH (NOLOCK)
								WHERE	tsc.comp_id			= @comp_id		AND
										tsc.subcataux_id	= @subcataux_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de SubCategoría Auxiliar es incorrecto'
				END
		END


	-----------------------------------------------------------------------------------------------------------------------


	------Clase-----------------------------------------------------------------------------------------------------------
	if	@ic_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Clase'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  tic.ic_id
			               FROM		tbItemClass tic		WITH (NOLOCK)
							WHERE	tic.comp_id		= @comp_id		AND
									tic.ic_id		= @ic_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Clase es incorrecto'
				END
		END
	-----------------------------------------------------------------------------------------------------------------------


	------Desc-----------------------------------------------------------------------------------------------------------
	if	@item_desc	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó la Descripción'
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Detalle-----------------------------------------------------------------------------------------------------------
	if	@item_detail	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Detalle'
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Marca-----------------------------------------------------------------------------------------------------------
	if	@brand_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Marca'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  ttn.brand_id
			               FROM		tbBrand 		ttn			WITH (NOLOCK)
							WHERE	ttn.comp_id		= @comp_id		AND
									ttn.brand_id	= @brand_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Marca es incorrecto'
				END
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Presentacion-----------------------------------------------------------------------------------------------------------
	if	@pres_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Presentación'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  ttn.pres_id
			               FROM		tbPresentation  		ttn		WITH (NOLOCK)
							WHERE	ttn.comp_id		= @comp_id		AND
									ttn.pres_id		= @pres_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Presentación es incorrecto'
				END
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Moneda-----------------------------------------------------------------------------------------------------------
	if	@curr_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Moneda'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  tc.curr_id
			               FROM tbsysCurrency tc		WITH (NOLOCK)
							WHERE	tc.curr_id		= @curr_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Moneda es incorrecto'
				END
		END
	-----------------------------------------------------------------------------------------------------------------------


	------Proveedor-----------------------------------------------------------------------------------------------------------
	if	@supp_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Proveedor'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  ts.supp_id
			               FROM tbSupplier ts		WITH (NOLOCK)
							WHERE	ts.comp_id		= @comp_id		AND
									ts.supp_id		= @supp_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Proveedor es incorrecto'
				END
		END
	-----------------------------------------------------------------------------------------------------------------------



	------Impuesto-----------------------------------------------------------------------------------------------------------
	if	@item_trigger_tax_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Impuesto'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  ttn.tax_id
							FROM	tbTaxName		ttn			WITH (NOLOCK)
							WHERE	ttn.comp_id		= @comp_id		AND
									ttn.tax_id		= @item_trigger_tax_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Impuesto es incorrecto'
				END
		END
	-----------------------------------------------------------------------------------------------------------------------


	------Grupo de Suc-----------------------------------------------------------------------------------------------------------
	IF	@brag_id	<> -1
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  tbg.brag_id
			               FROM tbBranchGroup tbg		WITH (NOLOCK)
						WHERE	tbg.comp_id		= @comp_id AND
								tbg.brag_id		= @brag_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Grupo de Sucursales es incorrecto'
			END
		END

	-----------------------------------------------------------------------------------------------------------------------


	------ID Incrementos / Markup-----------------------------------------------------------------------------------------------------------
	IF	@plm_id	<> -1
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  tplm.plm_id
			               FROM tbPriceListMarkup tplm	WITH (NOLOCK)
						WHERE	tplm.comp_id	= @comp_id AND
								tplm.plm_id		= @plm_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Incrementos / Markup es incorrecto'
			END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------ID Descuento por Compras-----------------------------------------------------------------------------------------------------------
	IF	@pd_id	<> -1
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  tpd.pd_id
			               FROM tbPurchaseDiscount tpd		WITH (NOLOCK)
						WHERE	tpd.comp_id		= @comp_id AND
								tpd.pd_id		= @pd_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Descuento por Compras es incorrecto'
			END
		END

	-----------------------------------------------------------------------------------------------------------------------


	------Unidad de Medida-----------------------------------------------------------------------------------------------------------
	IF	@mu_id	<> -1
		BEGIN
			IF NOT EXISTS (SELECT TOP 1  tmu.mu_id
			               FROM tbMetricUnits	tmu 		WITH (NOLOCK)
						WHERE	tmu.comp_id		= @comp_id AND
								tmu.mu_id		= @mu_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Unidad de Medida es incorrecto'
			END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------EAN ADICIONAL----------------------------------------------------------------------------------------------------
	IF	@strItemEanAdicional	<> ''
		BEGIN
			--NI COMO ITEM CODE NI COMO ITEM CODE ADDITIONAL

			IF EXISTS(SELECT TOP 1 ti.comp_id
			          FROM tbItem						AS ti
			          WHERE ti.comp_id		= @comp_id	AND
							ti.item_code	= @strItemEanAdicional)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El Código EAN Adicional del Artículo ya existe como código de artículo'
				END

			IF EXISTS (SELECT TOP 1 tie.comp_id
			           FROM tbItemEAN					AS tie	WITH(NOLOCK)
			           WHERE	tie.comp_id = @comp_id	AND
			           			tie.ie_ean	= @strItemEanAdicional)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El Código EAN Adicional del Artículo ya existe'
				END

		END


	-----------------------------------------------------------------------------------------------------------------------


	------Atributo1-----------------------------------------------------------------------------------------------------------
	IF	@itemAtrb1_id <> -1
		BEGIN
			IF NOT EXISTS (SELECT TOP 1 tiaa.comp_id
			               FROM tbItem_AddAttributes1				AS tiaa
			               WHERE	tiaa.comp_id		= @comp_id	AND
									tiaa.itemAtrb1_id	= @itemAtrb1_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Atributo 1 es incorrecto'
			END
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Atributo2-----------------------------------------------------------------------------------------------------------
	IF	@itemAtrb2_id <> -1
		BEGIN
			IF NOT EXISTS (SELECT TOP 1 tiaa.comp_id
			               FROM tbItem_AddAttributes2				AS tiaa
			               WHERE	tiaa.comp_id		= @comp_id	AND
									tiaa.itemAtrb2_id	= @itemAtrb2_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Atributo 2 es incorrecto'
			END
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Atributo3-----------------------------------------------------------------------------------------------------------
	IF	@itemAtrb3_id <> -1
		BEGIN
			IF NOT EXISTS (SELECT TOP 1 tiaa.comp_id
			               FROM tbItem_AddAttributes3				AS tiaa
			               WHERE	tiaa.comp_id		= @comp_id	AND
									tiaa.itemAtrb3_id	= @itemAtrb3_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Atributo 3 es incorrecto'
			END
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Atributo4-----------------------------------------------------------------------------------------------------------
	IF	@itemAtrb4_id <> -1
		BEGIN
			IF NOT EXISTS (SELECT TOP 1 tiaa.comp_id
			               FROM tbItem_AddAttributes4				AS tiaa
			               WHERE	tiaa.comp_id		= @comp_id	AND
									tiaa.itemAtrb4_id	= @itemAtrb4_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Atributo 4 es incorrecto'
			END
		END
	-----------------------------------------------------------------------------------------------------------------------



	-- si no viene nada del excel para estos campos le pondra 0 : @item_upb	,@item_mult

	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO



