CREATE PROCEDURE [dbo].[spItems_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SELECT
			isnull(ti.item_code,'')									[detail],
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbItem									ti		WITH (NOLOCK)
		ON	ti.comp_id		= tpclil.comp_id	AND
			ti.item_id		= tpclil.item_id

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO

CREATE PROCEDURE [dbo].[spItems_Process_ImportLog_InsertData]
(


	@comp_id		INT,
	@guid			UNIQUEIDENTIFIER,
	@user_id		INT,
	@introw			INT,
	@litem_id		INT,
	@errormessage	NVARCHAR(4000)

)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------------------------------------------------------
		-- PARAMETROS DE TESTING
		-- ------------------------------------------------------------------------------------------------
		/*
			DECLARE
					@comp_id		INT,
					@guid			UNIQUEIDENTIFIER,
					@user_id		INT,
					@introw			INT,
					@litem_id		INT,
					@item_code		NVARCHAR(50)
			SELECT
					@comp_id		= 1,
					@guid			='0995074c-dab6-4c00-af5d-7e82816fed4a',
					@user_id		= 1,
					@introw			= 10,
					@litem_id		= 768,
					@item_code		= '666666'
		*/
		-- ------------------------------------------------------------------------------------------------

		INSERT INTO tbPriceCostListImportLog WITH (ROWLOCK)
				(
					comp_id,
					pli_id,
					[user_id],
					item_id,
					code4Import,
					info

				)
				VALUES
				(
					@comp_id,
					@guid,
					@user_id,
					@litem_id,
					@introw,
					@errormessage
				)
	END
GO









CREATE procedure [dbo].[spItemSales_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@cat_id				int,
		@subcat_id			int,
		@item_id			int,
		@datefrom			datetime,
		@dateto				datetime,
		@item_made			INT,
		@bra_id				INT,
		@user_id			INT,
		@country_id			INT,
		@state_id			INT,
		@brag_id			INT,
		@guid				VARCHAR(50)--CF DE ITEMS

)
as



BEGIN

	set nocount ON
	set dateformat 'ymd'
/*
	-- ------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------

	Declare
			@comp_id			int,
			@lang_id			int,
			@page_id			int,

			@item_id			int,
			@cat_id				int,
			@subcat_id			int,
			@datefrom			datetime,
			@dateto				datetime,
			@item_made			INT,
			@bra_id				int,
			@user_id            int,
			@country_id			INT,
			@state_id			INT


	Select
			@comp_id			=1,
			@lang_id			=2,
			@page_id			=10020,

			@item_id			=-1,
			@cat_id				=-1,
			@subcat_id			=-1,
			@datefrom			='2000-10-01',
			@dateto				='2011-10-31',
			@item_made			=0,
			@bra_id				=1,
			@user_id            =1,
			@country_id			=61,
		    @state_id			=61003
*/
	-- ------------------------------------------------------------

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

	set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
		FROM tbBranchGroupDetail tbgd
		WHERE tbgd.brag_id = @brag_id


	DECLARE @fun_id INT
	SET @fun_id = 1

	--set	@dateto = @dateto + '23:59:59'--.990'

	select	IsNull(CA.cat_desc,'Item Manual')																				[cat_desc],
			IsNull(SC.subcat_desc,'Item Manual')																			[subcat_desc],
			IsNull(I.item_desc,ISNULL(titd.itm_desc,'Item Manual'))															[item_desc],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, IT.ct_transaction)								[Comprobante],
			IT.it_qty * vctfss.PlusOrMinus																					[it_qty],
			((IT.it_price - (it.it_itemDiscountTotal + it.it_totalDiscountTotal))* IT.it_qty)	*	vctfss.PlusOrMinus		[Total],
			isnull(it_itemDiscountTotal + it_totalDiscountTotal,0)	*	vctfss.PlusOrMinus									[Discount],
			i.item_made,
			IsNull(i.item_code,'*Item Manual*')																				[item_code]

	From	dbo.tbItemTransactions							IT

			left join 	dbo.tbItem							I
			on	I.comp_id			= IT.comp_id
			and I.item_id			= IT.item_id
			--and I.cat_id			= @cat_id
			--and I.subcat_id		= @subcat_id

			INNER JOIN @tblComplexFilter_Items				tempITEM
			ON tempitem.item_id						= I.item_id

			inner join dbo.tbCommercialTransactions			CT
			on  IT.comp_id			= CT.comp_id
			and	IT.bra_id			= CT.bra_id
			and IT.ct_transaction	= CT.ct_transaction

			LEFT JOIN tbItemTransactionDetails titd
				on  titd.comp_id		= it.comp_id
				and	titd.bra_id			= it.bra_id
				and titd.ct_transaction	= it.ct_transaction
				AND titd.it_transaction = it.it_transaction


			inner join tbsysDocuments td
			on td.sd_id = ct.sd_id

			inner join vwCommercialTransactions_forSalesStats vctfss
			on		vctfss.comp_id			= CT.comp_id
			--and		vctfss.bra_id			= CT.bra_id
			and		vctfss.ct_transaction	= CT.ct_transaction

			left join dbo.tbCategory						CA
			on  CA.comp_id			= I.comp_id
			--and CA.bra_id			= I.bra_id
			and CA.cat_id			= I.cat_id

			left join dbo.tbSubCategory						SC
			on  SC.comp_id			= I.comp_id
			--and SC.bra_id			= I.bra_id
			and SC.cat_id			= I.cat_id
			and SC.subcat_id		= I.subcat_id

			inner JOIN tbUsers4BranchFilter					vubf
			ON  vubf.comp_id		= ct.comp_id
			AND vubf.bra_id			= ct.bra_id
			AND vubf.[user_id]		= @user_id


-- help de solo fc y nc

	Where	IT.comp_id		= @comp_id
	--and		IT.bra_id		= @bra_id
	and		(I.cat_id		= @cat_id		or @cat_id		= -1)
	and		(I.subcat_id	= @subcat_id	or @subcat_id	= -1)
	and		(I.item_id		= @item_id		or @item_id		= -1)
	AND     (isnull(IT.it_isMade,'False')	= @item_made	OR @item_made	= -1)
	and		 CT.ct_date		between @datefrom and @dateto
	AND		ct.sd_id IN (1,3,    4,31,33)
	AND		(@country_id = -1 OR  (ct.country_id = @country_id AND ct.state_id = @state_id))
	And		(
				(@brag_id = -1	AND		it.bra_id	= @bra_id) OR
				(@brag_id <> -1 AND		EXISTS( SELECT 1
				                   					FROM	@tblBranchs tmpb
				                   					WHERE	tmpb.bra_id = it.bra_id ))
			)

	order by cat_desc, subcat_desc, item_desc

	exec [spReports_getData3] @comp_id,@bra_id, @lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/



	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 36
      				--AND t.[lang_id] = @lang_id
      				and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],
			CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		TC.cat_desc
						FROM	tbCategory tc
						WHERE	tC.comp_id = @comp_id AND tc.cat_id= @cat_id)
			END		[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],
			CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
						FROM	tbSubCategory tsc
						WHERE	tsc.comp_id = @comp_id AND tsc.subcat_id= @subcat_id)
			END		[params4],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 103
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],
			CASE @item_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ti.item_desc
						FROM	tbItem ti
						WHERE	ti.comp_id = @comp_id AND ti.item_id= @item_id)
			END		[params6],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params7],
      		 @datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom)) 	[params8],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],
      		 @dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto)) 	[params10]



	  (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 1684
      				--AND t.[lang_id] = @lang_id
      				and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params10],

			CASE @item_made WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
	   				(SELECT     tov.optval_desc
	 	   			 FROM		tbsysOptionsValues tov

					    WHERE   tov.optval_class = 122
					    AND     tov.optval_id	 = @item_made
	   					AND		tov.lang_id		 = @lang_id)

      	END 																		[params11],




     --
     (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 57
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params12],

		CASE @country_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(
	     	   SELECT tc.country_desc
	     		FROM tbsysCountry tc
	     		 WHERE tc.country_id = @country_id
	     	   )
	     End [params13],

	     (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 59
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params14],

		CASE @state_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
			(SELECT ts.state_desc
				 FROM tbsysCountry tc
				 INNER JOIN tbsysState ts
				 ON ts.country_id = tc.country_id

				 WHERE ts.state_id=@state_id
				)
		END		[params15]


END
GO




