-- Data  : Se agregaron dos campos, @itema_canDeleteInSO y @itema_discountPercentage4PriceListSUM
--------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spItemsAssociation_Process_Auto]
(
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@item_id_1					INT,
	@qty						DECIMAL(19,5),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT,
	@bolIsOK					BIT,

	@item_code_main								NVARCHAR(50),		-- Articulo combo
	@item_code_asoc								NVARCHAR(50),		-- Articulo asociado
	@itema_canDeleteInSO						BIT,				-- Permite borrar la parte en un pedido?
	@itema_discountPercentage4PriceListSUM		DECIMAL(15,4)		-- Porcentaje de Descuento en caso de que el combo sume el precio de las partes




)
AS


---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@item_id_1					INT,
	@qty						DECIMAL(19,5),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT,
	@bolIsOK					BIT




SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,
	@item_id					=229,
	@item_id_1					=404,
	@qty						=666,

	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 666

*/
---------------------------------------------------------------------------------


set nocount on



BEGIN


	--Recuperamos el item_id mediante el codigo
	DECLARE @litem_id_main AS INT

	SELECT
		@litem_id_main = ti.item_id

		FROM tbitem  ti	WITH (NOLOCK)

		WHERE	ti.comp_id		= @comp_id		AND
				ti.item_code	= @item_code_main


	--Recuperamos el item_id del asociado mediante el codigo del item asociado
	DECLARE @litem_id_asoc AS INT

	SELECT
		@litem_id_asoc = ti.item_id

		FROM tbitem  ti	WITH (NOLOCK)

		WHERE	ti.comp_id		= @comp_id		AND
				ti.item_code	= @item_code_asoc



	declare @return_value	INT ,
			@items_desc NVARCHAR(4000)

	SET	@return_value = 1
	SET @items_desc = CONVERT(VARCHAR,@litem_id_main) + ' - ' + Convert(Varchar, @litem_id_asoc)

		BEGIN TRY

			INSERT INTO tbItemAssociation WITH (ROWLOCK)
			(
				comp_id,
				item_id,
				item_id_1,
				iasso_qty,
				itema_canDeleteInSO,
				itema_discountPercentage4PriceListSUM
			)
			VALUES
			(
				@comp_id,
				@litem_id_main,
				@litem_id_asoc,
				@qty,
				@itema_canDeleteInSO,
				@itema_discountPercentage4PriceListSUM
			)


			--set	@return_value = IDENT_CURRENT('tbItemAssociation')   -- @@identity

			END TRY
			BEGIN CATCH
				set	@return_value = 0
			END CATCH

			SELECT @return_value
			IF @return_value <> 0
				BEGIN
					EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,NULL
				END



END


















GO





