CREATE PROCEDURE [dbo].[spItemsAssociation_Process_Auto_Validate]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@item_id_1					INT,
	@qty						DECIMAL(19,5),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT,

	@item_code_main				NVARCHAR(50),   -- Articulo combo
	@item_code_asoc				NVARCHAR(50)	-- Articulo asociado


)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@item_id_1					INT,
	@qty						DECIMAL(19,5),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT




SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,

	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 10,
	@bra_id4session				= 1

*/
---------------------------------------------------------------------------------


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


set nocount on

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''




	------Codigo del articulo combo -----------------------------------------------------------------------------------------------------------
	if	@item_code_main	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Código del Artículo principal'
		END
	ELSE
		BEGIN

			IF not EXISTS (SELECT top 1 ti.item_id
    								FROM tbitem ti								WITH (NOLOCK)
    								WHERE	ti.comp_id				= @comp_id AND
											ti.item_code			= @item_code_main
							)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'No existe un Artículo para el Código del Artículo principal ingresado'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	----Recuperamos el item_id mediante el codigo
	--DECLARE @litem_id_main AS INT

	--SELECT
	--	@litem_id_main = ti.item_id

	--	FROM tbitem  ti	WITH (NOLOCK)

	--	WHERE	ti.comp_id		= @comp_id		AND
	--			ti.item_code	= @item_code_main


	--------Articulo combo-----------------------------------------------------------------------------------------------------------

	--	IF NOT EXISTS (SELECT ti.item_id
	--					FROM	tbItem							ti		WITH (NOLOCK)
	--					WHERE	ti.comp_id		= @comp_id		AND
	--							ti.item_id		= @litem_id_main)
	--		BEGIN
	--			SET	@bolIsOK		= 'False'
	--			SET @errormessage	= @errormessage + '---' + 'El ID de Artículo es incorrecto'
	--		END

	-------------------------------------------------------------------------------------------------------------------------






	-- ITEM ASOCIADO

	------Codigo del articulo ASOCICADO -----------------------------------------------------------------------------------------------------------
	if	@item_code_asoc	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Código asociado'
		END
	ELSE
		BEGIN
			IF not EXISTS (SELECT top 1 ti.item_id
    								FROM tbitem ti								WITH (NOLOCK)
    								WHERE	ti.comp_id				= @comp_id AND
											ti.item_code			= @item_code_asoc
							)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'No existe un Artículo para el Código Asociado ingresado'
				END
		END
	-----------------------------------------------------------------------------------------------------------------------






	--Recuperamos el item_id mediante el codigo
	DECLARE @litem_id_main AS INT

	SELECT
		@litem_id_main = ti.item_id

		FROM tbitem  ti	WITH (NOLOCK)

		WHERE	ti.comp_id		= @comp_id		AND
				ti.item_code	= @item_code_main


	--Recuperamos el item_id del asociado mediante el codigo del item asociado
	DECLARE @litem_id_asoc AS INT

	SELECT
		@litem_id_asoc = ti.item_id

		FROM tbitem  ti	WITH (NOLOCK)

		WHERE	ti.comp_id		= @comp_id		AND
				ti.item_code	= @item_code_asoc


		DECLARE @returnItemAssociation_validateData_value	INT

		EXEC spItemAssociation_validateData  @comp_id,@litem_id_main,@litem_id_asoc,0,@returnItemAssociation_validateData_value OUTPUT


		IF @returnItemAssociation_validateData_value <> 0
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'Ya existe la asociación entre esos artículos'
			END


	----Recuperamos el item_id mediante el codigo
	--DECLARE @litem_id_asoc AS INT

	--SELECT
	--	@litem_id_asoc = ti.item_id

	--	FROM tbitem  ti	WITH (NOLOCK)

	--	WHERE	ti.comp_id		= @comp_id		AND
	--			ti.item_code	= @item_code_asoc



	--------Articulo Asociado-----------------------------------------------------------------------------------------------------------

	--IF NOT EXISTS (SELECT ti.item_id
	--		        FROM		tbItem ti		WITH (NOLOCK)
	--				WHERE	ti.comp_id		= @comp_id		AND
	--						ti.item_id		= @litem_id_asoc)
	--	BEGIN
	--		SET	@bolIsOK		= 'False'
	--		SET @errormessage	= @errormessage + '---' + 'El ID de Artículo Asociado es incorrecto'
	--	END

	-------------------------------------------------------------------------------------------------------------------------












	-- si no viene nada del excel para estos campos le pondra 0 : @qty

	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END





















		---- ------------------------------------------------------------------------------------------------------------
		---- CODIGO DEL ARTICULO COMBO
		---- ------------------------------------------------------------------------------------------------------------
		--IF (@item_code <> '')
		--	BEGIN
		--		IF EXISTS (SELECT
		--					ti.item_id
		--					FROM		tbItem						ti		WITH (NOLOCK)
		--					WHERE	ti.comp_id		= @comp_id		AND
		--							ti.item_code	= @item_code	AND
		--							ti.item_id		<> @item_id)
		--			BEGIN
		--				SET	@bolIsOK		= 'False'
		--				SET @errormessage	= @errormessage + '---' + 'El Código/EAN del Artículo ya está asociado a otro artículo'
		--			END

		--		IF EXISTS (SELECT
		--					tie.item_id
		--					FROM tbItemEAN						tie WITH(NOLOCK)
		--					WHERE	tie.comp_id	= @comp_id		AND
		--							tie.ie_ean	= @item_code)
		--		BEGIN
		--			SET	@bolIsOK		= 'False'
		--			SET @errormessage	= @errormessage + '---' + 'El Código/EAN del Artículo ya está asociado como EAN adicional a otro artículo'
		--		END
		--	END
		---- ------------------------------------------------------------------------------------------------------------


		---- ------------------------------------------------------------------------------------------------------------
		---- CODIGO DEL ARTICULO ASOCICADO
		---- ------------------------------------------------------------------------------------------------------------
		--IF (@item_code_asoc <> '')
		--	BEGIN
		--		IF EXISTS (SELECT
		--					ti.item_id
		--					FROM		tbItem						ti		WITH (NOLOCK)
		--					WHERE	ti.comp_id		= @comp_id		AND
		--							ti.item_code	= @item_code_asoc	AND
		--							ti.item_id		<> @item_id)
		--			BEGIN
		--				SET	@bolIsOK		= 'False'
