-- Date   : 27/12/16
-- Author : GA
-- Detail : Al finalizar el proceso de importacion se muestra en una grilla que registros fueron dados de alta y los que no.
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
create PROCEDURE [dbo].[spItemsAssociation_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SELECT
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)


	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO




CREATE PROCEDURE [dbo].[spItemSelection_GetPricesData4GenericGrid]
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@item_id	INT
)

AS



BEGIN


	-- ----------------------------------------
	-- TESTING
	-- ----------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@bra_id		INT,
			@prof_id	INT,
			@item_id	INT
		SELECT
			@comp_id	= 1,
			@bra_id		= 1,
			@prof_id	= 1,
			@item_id	= 492


*/
	-- ----------------------------------------



	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	SELECT	DISTINCT
			tis.comp_id,
			tis.prli_id
		INTO #tbItemSelection
		FROM tbItemSelection						tis		WITH (NOLOCK)
		WHERE	tis.comp_id		= @comp_id		AND
				(tis.bra_id		= @bra_id OR tis.bra_id IS NULL)		AND
				tis.prof_id		= @prof_id

		--ORDER BY tis.is_order



		SELECT
			tpl.prli_desc,
			tpli.prli_price	* dbo.fnGetPriceListItemTaxesCoeficient(tpli.comp_id,tpli.item_id)		[PricewithIVA],						-- Precio CON iva
			tpli.prli_price																			[PricewithoutIVA],					-- Precio SIN iva
			tc.curr_symbol


			FROM #tbItemSelection						tis		WITH (NOLOCK)

			INNER JOIN tbItem							ti		WITH (NOLOCK)
			ON	ti.comp_id		= tis.comp_id	AND
				ti.item_id		= @item_id

			INNER JOIN vwPriceListItems					tpli	WITH (NOLOCK)
			ON	tpli.comp_id	= ti.comp_id	AND
				tpli.item_id	= ti.item_id	AND
				tpli.prli_id	= tis.prli_id
			INNER JOIN tbPriceList						tpl		WITH (NOLOCK)
				ON	tpl.comp_id = tpli.comp_id AND
					tpl.prli_id = tpli.prli_id
			INNER JOIN tbsysCurrency					tc		WITH (NOLOCK)
				ON tc.curr_id = tpli.curr_id


		WHERE	ti.comp_id		= @comp_id	AND
				ti.item_id		= @item_id








	END
GO




CREATE PROCEDURE [dbo].[spItemSelection_GetStorageData4GenericGrid]
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@item_id	INT
)

AS



BEGIN


	-- ----------------------------------------
	-- TESTING
	-- ----------------------------------------
/*
		DECLARE
			@comp_id	INT,
			@bra_id		INT,
			@prof_id	INT,
			@item_id	INT
		SELECT
			@comp_id	= 1,
			@bra_id		= 1,
			@prof_id	= 1,
			@item_id	= 492
*/
	-- ----------------------------------------



	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

		SELECT
			ts.stor_desc,
			--ti.item_desc,
			tis.ise_Desc,
			convert(decimal(19,0),dbo.fnGetAStock(@comp_id, tis.stor_id,
																		CASE
																			WHEN tis.is_NoShowStorageGroup = 'True' THEN -1
																			ELSE 1
																		END
																		* tis2.item_id, 99999999))		[STKPotGD],
			convert(decimal(19,0),dbo.fnGetStockOfStorageGroup(@comp_id, tis.stor_id,

																		CASE
																			WHEN tis.is_NoShowStorageGroup = 'True' THEN -1
																			ELSE 1
																		END
																		* tis2.item_id))	[STKFisGD],
			convert(decimal(19,0),dbo.fnGetStock(@comp_id, tis.stor_id,

																		CASE
																			WHEN tis.is_NoShowStorageGroup = 'True' THEN -1
																			ELSE 1
																		END
																		* tis2.item_id))					[STKFisico],

			convert(decimal(19,0),dbo.fnGetAStock4MaxAssociation(@comp_id, tis.stor_id,

																		CASE
																			WHEN tis.is_NoShowStorageGroup = 'True' THEN -1
																			ELSE 1
																		END
																		* tis2.item_id,999999999))					[STKDCmb],
																		ISNULL(tis2.itst_PickingLocation,'')		[itst_PickingLocation],
																		ISNULL(tis2.itst_StorageLocation,'')		[itst_StorageLocation]


			--CASE ISNULL(tis.stor_showPhisicalStock,'False')
			--	WHEN 'True'	THEN	convert(decimal(19,0),dbo.fnGetStock(@comp_id, tis.stor_id, tis2.item_id))
			--	ELSE				convert(decimal(19,0),dbo.fnGetAStock(@comp_id, tis.stor_id, tis2.item_id, 99999999))

			--END																		[Stock]

		FROM tbItemSelection							tis

			INNER JOIN tbItemStorage					tis2
			on	tis2.comp_id	= tis.comp_id	AND
				tis2.stor_id	= tis.stor_id	AND
				tis2.item_id	= @item_id

			INNER JOIN tbItem							ti
			ON	ti.comp_id		= tis2.comp_id	AND
				ti.item_id		= tis2.item_id

			INNER JOIN tbStorage						ts
			on	ts.comp_id		= tis.comp_id	AND
				ts.stor_id		= tis.stor_id

		WHERE	tis.comp_id		= @comp_id		AND
				(tis.bra_id		= @bra_id OR tis.bra_id IS NULL)		AND
				tis.prof_id		= @prof_id		AND
				NOT tis.stor_id IS NULL			AND
				ti.item_id		= @item_id

		ORDER BY tis.is_order




		-- TOTALES
		SELECT

			convert(decimal(19,0),sum(dbo.fnGetAStock(@comp_id, tis.stor_id, CASE
																				WHEN tis.is_NoShowStorageGroup = 'True' THEN -1
																				ELSE 1
																			 END
																			 * tis2.item_id, 99999999)))		[STKPotGD],
			convert(decimal(19,0),sum(dbo.fnGetStockOfStorageGroup(@comp_id, tis.stor_id, CASE
																							WHEN tis.is_NoShowStorageGroup = 'True' THEN -1
																							ELSE 1
																						  END
																							* tis2.item_id)))	[STKFisGD],
			convert(decimal(19,0),sum(dbo.fnGetStock(@comp_id, tis.stor_id, CASE
																				WHEN tis.is_NoShowStorageGroup = 'True' THEN -1
																				ELSE 1
																			END
																			* tis2.item_id)))					[STKFis],
			convert(decimal(19,0),sum(dbo.fnGetAStock4MaxAssociation(@comp_id, tis.stor_id, CASE
																				WHEN tis.is_NoShowStorageGroup = 'True' THEN -1
																				ELSE 1
																			 END
																			 * tis2.item_id, 99999999)))		[STKDCmb]



		FROM tbItemSelection							tis

			INNER JOIN tbItemStorage					tis2
			on	tis2.comp_id	= tis.comp_id	AND
				tis2.stor_id	= tis.stor_id	AND
				tis2.item_id	= @item_id

			INNER JOIN tbItem							ti
			ON	ti.comp_id		= tis2.comp_id	AND
				ti.item_id		= tis2.item_id

			INNER JOIN tbStorage						ts
			on	ts.comp_id		= tis.comp_id	AND
				ts.stor_id		= tis.stor_id

		WHERE	tis.comp_id		= @comp_id		AND
				(tis.bra_id		= @bra_id OR tis.bra_id IS NULL)		AND
				tis.prof_id		= @prof_id		AND
				NOT tis.stor_id IS NULL			AND
				ti.item_id		= @item_id

		--GROUP BY ts.stor_id,ts.stor_desc,tis.ise_Desc



	END
GO






