-- Se usa para recuperar los numeros de serie a serializar por compras.
-- Modificado x MOS
-- 01-2009
-- 02-2010
-- 18-03-2010 = MOH = Agregado de comentarios para entender que hace
-- 21-03-2010 = MOH = Agregado de nuevo parámetro pdocnumber, que filtra, por ct_docnumber de tbCommercialTransactions
-- 22-07-2011 - GA = se agregó parametro @isAvailable para filtrar por los nº de serie disponilbes y no disponibles.




/***************************************************************************************************/
/*
* ATENCION -- SI SE MODIFICAN LOS CAMPOS DEL QUERY FINAL TAMBIEN SE DEBEN MODIFICAR DE LA MISMA
* FORMA LOS CAMPOS DEL SP [spItemSerials_getDataByGuid] YA QUE AMBOS SPS LLENAN LA MISMA GRILLA
* EN LA PÁGINA wfmItemSerialLoad_Update
*/
/***************************************************************************************************/

CREATE PROCEDURE [dbo].[spItemSerial_Load]
(
	@comp_id				INT,
	@lang_id				INT,
	@import_id				INT,
	@item_id				INT,
	@supp_id				INT,
	@cat_id					INT,
	@subcat_id				INT,
	@brand_id				INT,
	@pendientes				INT,
	@Cant					INT,
	@bitOnlyGenerated		BIT,
	@guid					UNIQUEIDENTIFIER,
	@MinimumDateUpdated		DATETIME,
	@bra_id					INT,
	@useGuid2Filter			BIT,
	@ct_docNumber			NVARCHAR(50),
	@isAvailable			INT,
	@serial					NVARCHAR(100),
	@stor_id				INT,
	@return_value			INT OUTPUT
)
AS


BEGIN




	SET NOCOUNT ON

-- ------------------------------------------------------------------------
-- Testing
-- ------------------------------------------------------------------------
/*
	Declare	@comp_id			int,
			@lang_id			INT = 2,
  			@import_id			int,
  			@item_id			int,
  			@supp_id			int,
  			@cat_id				int,
  			@subcat_id			int,
  			@brand_id			int,
  			@pendientes			Int,
  			@Cant				INT,
  			@bitOnlyGenerated   BIT,
  			@guid				UNIQUEIDENTIFIER,
  			@return_value		INT,
  			@MinimumDateUpdated DATETIME,
  			@bra_id				INT,
  			@ct_docNumber		NVARCHAR(50),
			@isAvailable		INT,
  			@useGuid2Filter		BIT,
  			@serial AS			NVARCHAR(100),
			@stor_id			INT

	Select	@comp_id			=1,
  			@import_id			=-1,
  			@item_id			=-1,
  			@supp_id			=-1,
  			@cat_id				=-1,
  			@subcat_id			=-1,
  			@brand_id			=-1,
  			@pendientes			=-1,
  			@Cant				=50,
  			@bitOnlyGenerated	='false',
  			@guid				='5CD6FD5B-165E-4496-9CAE-9B9217F7B5C7',
  			@MinimumDateUpdated ='2000-01-01',
  			@bra_id				=1,
  			@useGuid2Filter		='false',
  			@ct_docNumber		='',
			@isAvailable		= -1,
			@serial='',--'356552040381543',
			@stor_id			= -1

	--DROP TABLE #tmpSerials
*/
-- ------------------------------------------------------------------------


	DECLARE @bitMustPrintItemParts AS BIT = 'False'
	IF @lang_id < 0
		BEGIN
			SET @lang_id				= @lang_id * -1
			SET @bitMustPrintItemParts	= 'True'
		END



	SET @MinimumDateUpdated = ISNULL(@MinimumDateUpdated,CAST('01-01-1800' AS DATETIME))



	--cargar en temporal los artículos a serializar válidos para los filtros recibidos

			-- Genera Tabla temporal por un tema de optimizacion de la busqueda.  Puerde ser MUYYY costosa.!
			SELECT	Top(1)
					I.item_code,
					I.item_desc,
					ITS.is_serial,
					ITS.is_id,
					ts.supp_name,
					CASE	-- MOS 11-2022
						WHEN ISNULL(ti.impData_number,'')			<> ''	THEN ti.impData_number
						WHEN ISNULL(tid2.impData_Number_local,'')	<> ''	THEN tid2.impData_Number_local
						ELSE ''
					END																					[impData_number],
					--ti.impData_number,
					CASE	-- MOS 11-2022
						WHEN ISNULL(ti.impData_Custom,'')			<> ''	THEN ti.impData_Custom
						WHEN ISNULL(tid2.impData_Custom_local,'')	<> ''	THEN tid2.impData_Custom_local
						ELSE ''
					END																					[impData_Custom],
					--ti.impData_Custom,
					tc.country_desc,
					TS.supp_id,
					ITS.is_guid,
					I.item_id,
					tct.ct_date,
					ITS.ct_transaction,
					ITS.comp_id,
					tov.optval_desc [is_available],
					CASE	-- MOS 11-2022
						WHEN ISNULL(ti.impData_origin,'')			<> ''	THEN ti.impData_origin
						WHEN ISNULL(tid2.impData_Origin,'')			<> ''	THEN tid2.impData_Origin
						ELSE ''
					END																					[impData_origin],
					CASE	-- MOS 11-2022
						WHEN ISNULL(ti.impData_from,'')				<> ''	THEN ti.impData_from
						WHEN ISNULL(tid2.impData_From,'')			<> ''	THEN tid2.impData_From
						ELSE ''
					END																					[impData_from]



			INTO	#tmpSerials

			FROM	dbo.tbItemSerials								ITS		WITH (NOLOCK)

					left Join dbo.vwItemSerialsImportData			IM		WITH (NOLOCK)
						On	IM.comp_id			=	ITS.[comp_id]
						and IM.ct_transaction   =   ITS.ct_transaction
						and IM.it_transaction   =   ITS.it_transaction

					left Join  dbo.tbItem							I	WITH (NOLOCK)
						on  I.[comp_id]			=	ITS.[comp_id]
						and I.[item_id]			=   ITS.[item_id]

					left JOIN tbCategory							C		WITH (NOLOCK)
						ON	C.[comp_id]			=	I.[comp_id]
						AND C.[cat_id]			=	I.[cat_id]

					left JOIN tbSubCategory							SC	WITH (NOLOCK)
						ON	SC.[comp_id]		=	I.[comp_id]
						AND SC.[cat_id]			=	I.[cat_id]
						AND SC.[subcat_id]		=	I.[subcat_id]

					left JOIN tbBrand								B			WITH (NOLOCK)
						ON	B.[comp_id]			=	I.[comp_id]
						AND B.[brand_id]		=	I.[brand_id]

					Inner Join tbCommercialTransactions				tct	WITH (NOLOCK)
						On	tct.comp_id			=	ITS.comp_id
						AND tct.bra_id			=	ITS.bra_id
						AND tct.ct_transaction	=	ITS.ct_transaction


					left Join tbSupplier							ts		WITH (NOLOCK)
						On	ts.comp_id			=	tct.comp_id
						And ts.supp_id			=	tct.supp_id

					Left Join tbImportDetail						tid		WITH (NOLOCK)
						On  tid.comp_id         =	its.comp_id
						And tid.bra_id			=	its.bra_id
						And tid.ct_transaction  =	its.ct_transaction

					left Join tbImport								ti		WITH (NOLOCK)
						On	ti.comp_id			=	its.comp_id
						And ti.import_id		=	tid.import_id

					left Join tbsysCountry							tc
					On	tc.country_id		=	ISNULL(ti.country_id,tct.country_id)


					LEFT JOIN tbImportData AS tid2 WITH (NOLOCK)		-- MOS 11-2022		-- MOS 11-2022
						ON 	tid2.comp_id		=	ITS.[comp_id]
						and tid2.ct_transaction =   ITS.ct_transaction
						and tid2.it_transaction =   ITS.it_transaction


					left join tbsysOptionsValues					tov		WITH (NOLOCK)
						on  tov.optval_class	= 32
						and tov.lang_id			= @lang_id
						and tov.optval_id		= its.is_available

			where	its.comp_id = -1	AND
					its.is_id	= 0		AND
					(@stor_id	= -1	or ITS.stor_id = @stor_id)



--==
--SELECT COUNT(*) FROM #tmpSerials
--RETURN
--==
	-- ATENCION:!!!!!
	-- Verificar los DOS insert ya que si se hacen cambios
	-- deberan ponerse en la creacion de la temporal y en cada uno de los insert (DOS)

	IF @serial <> ''	-- Si se especifico un numero de serie en particular.
		BEGIN



			INSERT INTO #tmpSerials
				(
					I.item_code,
					item_desc,
					is_serial,
					is_id,
					supp_name,
					impData_number,
					impData_Custom,
					country_desc,
					supp_id,
					is_guid,
					item_id,
					ct_date,
					ct_transaction,
					ITS.comp_id,
					is_available,
					impData_origin,
					impData_from
					)
				(
					SELECT
							I.item_code,
							I.item_desc,
							ITS.is_serial,
							ITS.is_id,
							ts.supp_name,
							CASE	-- MOS 11-2022
								WHEN ISNULL(ti.impData_number,'')			<> ''	THEN ti.impData_number
								WHEN ISNULL(tid2.impData_Number_local,'')	<> ''	THEN tid2.impData_Number_local
								ELSE ''
							END																					[impData_number],
							--ti.impData_number,
							CASE	-- MOS 11-2022
								WHEN ISNULL(ti.impData_Custom,'')			<> ''	THEN ti.impData_Custom
								WHEN ISNULL(tid2.impData_Custom_local,'')	<> ''	THEN tid2.impData_Custom_local
								ELSE ''
							END																					[impData_Custom],
							--ti.impData_Custom,
							tc.country_desc,
							TS.supp_id,
							ITS.is_guid,
							I.item_id,
							tct.ct_date,
							ITS.ct_transaction,
							ITS.comp_id,
							tov.optval_desc [is_available],
							CASE	-- MOS 11-2022
								WHEN ISNULL(ti.impData_origin,'')			<> ''	THEN ti.impData_origin
								WHEN ISNULL(tid2.impData_Origin,'')			<> ''	THEN tid2.impData_Origin
								ELSE ''
							END																					[impData_origin],
							CASE	-- MOS 11-2022
								WHEN ISNULL(ti.impData_from,'')				<> ''	THEN ti.impData_from
								WHEN ISNULL(tid2.impData_From,'')			<> ''	THEN tid2.impData_From
								ELSE ''
							END																					[impData_from]


					FROM	dbo.tbItemSerials								ITS
					WITH (NOLOCK)

							-- MOS, NOOOOOOO
							--							left Join dbo.vwItemSerialsImportData			IM
							--								On	IM.comp_id			=	ITS.[comp_id]
							--								and IM.ct_transaction   =   ITS.ct_transaction
							--								and IM.it_transaction   =   ITS.it_transaction
							left Join  dbo.tbItem							I
							WITH (NOLOCK)
							on  I.[comp_id]			=	ITS.[comp_id]
							and I.[item_id]			=   ITS.[item_id]

							left JOIN tbCategory							C
							WITH (NOLOCK)
							ON	C.[comp_id]			=	I.[comp_id]
							AND C.[cat_id]			=	I.[cat_id]

							left JOIN tbSubCategory							SC
							WITH (NOLOCK)
							ON	SC.[comp_id]		=	I.[comp_id]
							AND SC.[cat_id]			=	I.[cat_id]
							AND SC.[subcat_id]		=	I.[subcat_id]

							left JOIN tbBrand								B
							WITH (NOLOCK)
							ON	B.[comp_id]			=	I.[comp_id]
							AND B.[brand_id]		=	I.[brand_id]

							Inner Join tbCommercialTransactions				tct
							WITH (NOLOCK)
							On	tct.comp_id			=	ITS.comp_id
							AND tct.bra_id			=	ITS.bra_id
							AND tct.ct_transaction	=	ITS.ct_transaction

							left Join tbSupplier							ts
							WITH (NOLOCK)
							On	ts.comp_id			=	tct.comp_id
							And ts.supp_id			=	tct.supp_id

							Left Join tbImportDetail						tid
							WITH (NOLOCK)
							On  tid.comp_id         =	its.comp_id
							And tid.bra_id			=	its.bra_id
							And tid.ct_transaction  =	its.ct_transaction

							left Join tbImport								ti
							WITH (NOLOCK)
							On	ti.comp_id			=	its.comp_id
							And ti.import_id		=	tid.import_id

							left Join tbsysCountry							tc
							WITH (NOLOCK)
							On	tc.country_id		= ISNULL(ti.country_id,tct.country_id)	--ti.country_id		-- MOS 11-2022

							left join tbsysOptionsValues					tov
							WITH (NOLOCK)
							on  tov.optval_class	= 32
							and tov.lang_id			= @lang_id
							and tov.optval_id		= its.is_available

							LEFT JOIN tbImportData AS tid2 WITH (NOLOCK)		-- MOS 11-2022
								ON 	tid2.comp_id		=	ITS.[comp_id]
								and tid2.ct_transaction =   ITS.ct_transaction
								and tid2.it_transaction =   ITS.it_transaction



					where	@comp_id		= its.comp_id and
							its.is_serial	= @serial
				)
		END

	ELSE		-- Si NO se especifico un numero de serie en particular.

		BEGIN



			INSERT INTO #tmpSerials
				(
					I.item_code,
					item_desc,
					is_serial,
					is_id,
					supp_name,
					impData_number,
					impData_Custom,
					country_desc,
					supp_id,
					is_guid,
					item_id,
					ct_date,
					ct_transaction,
					ITS.comp_id,
					is_available,
					impData_origin,
					impData_from
					)
				(

					SELECT	Top(@cant) --tct.ct_docNumber,
							I.item_code,
							I.item_desc,
							ITS.is_serial,
							ITS.is_id,
							ts.supp_name,
							CASE	-- MOS 11-2022
								WHEN ISNULL(ti.impData_number,'')			<> ''	THEN ti.impData_number
								WHEN ISNULL(tid2.impData_Number_local,'')	<> ''	THEN tid2.impData_Number_local
								ELSE ''
							END																					[impData_number],
							--ti.impData_number,
							CASE	-- MOS 11-2022
								WHEN ISNULL(ti.impData_Custom,'')			<> ''	THEN ti.impData_Custom
								WHEN ISNULL(tid2.impData_Custom_local,'')	<> ''	THEN tid2.impData_Custom_local
								ELSE ''
							END																					[impData_Custom],
							--ti.impData_Custom,
							tc.country_desc,
							TS.supp_id,
							ITS.is_guid,
							I.item_id,
							tct.ct_date,
							ITS.ct_transaction,
							ITS.comp_id,
							tov.optval_desc [is_available],
							CASE	-- MOS 11-2022
								WHEN ISNULL(ti.impData_origin,'')			<> ''	THEN ti.impData_origin
								WHEN ISNULL(tid2.impData_Origin,'')			<> ''	THEN tid2.impData_Origin
								ELSE ''
							END																					[impData_origin],
							CASE	-- MOS 11-2022
								WHEN ISNULL(ti.impData_from,'')				<> ''	THEN ti.impData_from
								WHEN ISNULL(tid2.impData_From,'')			<> ''	THEN tid2.impData_From
								ELSE ''
							END																					[impData_from]

					--INTO	#tmpSerials

					FROM	dbo.tbItemSerials								ITS
					WITH (NOLOCK)

							LEFT JOIN tbImportDetail IM
							WITH (NOLOCK)
								ON		im.comp_id		  = its.comp_id
									AND im.ct_transaction = its.ct_transaction
								-- Eliminad por MOS, SUPER LENTOOOOO
								--							left Join dbo.vwItemSerialsImportData			IM
								--							On	IM.comp_id			=	ITS.[comp_id]
								--								and IM.ct_transaction   =   ITS.ct_transaction
								--								and IM.it_transaction   =   ITS.it_transaction
							left Join  dbo.tbItem							I
							WITH (NOLOCK)
							on  I.[comp_id]			=	ITS.[comp_id]
							and I.[item_id]			=   ITS.[item_id]

							left JOIN tbCategory							C
							WITH (NOLOCK)
							ON	C.[comp_id]			=	I.[comp_id]
							AND C.[cat_id]			=	I.[cat_id]

							left JOIN tbSubCategory							SC
							WITH (NOLOCK)
							ON	SC.[comp_id]		=	I.[comp_id]
							AND SC.[cat_id]			=	I.[cat_id]
							AND SC.[subcat_id]		=	I.[subcat_id]

							left JOIN tbBrand								B
							WITH (NOLOCK)
							ON	B.[comp_id]			=	I.[comp_id]
							AND B.[brand_id]		=	I.[brand_id]

							Inner Join tbCommercialTransactions				tct
							WITH (NOLOCK)
							On	tct.comp_id			=	ITS.comp_id
							AND tct.bra_id			=	ITS.bra_id
							AND tct.ct_transaction	=	ITS.ct_transaction

							left Join tbSupplier							ts
							WITH (NOLOCK)
							On	ts.comp_id			=	tct.comp_id
							And ts.supp_id			=	tct.supp_id

							Left Join tbImportDetail						tid
							WITH (NOLOCK)
							On  tid.comp_id         =	its.comp_id
							And tid.bra_id			=	its.bra_id
							And tid.ct_transaction  =	its.ct_transaction

							left Join tbImport								ti
							WITH (NOLOCK)
							On	ti.comp_id			=	its.comp_id
							And ti.import_id		=	tid.import_id

							left Join tbsysCountry							tc
							WITH (NOLOCK)
							On	tc.country_id		=	ISNULL(ti.country_id,tct.country_id)  --ti.country_id	-- MOS 11-2022

							left join tbsysOptionsValues					tov
							WITH (NOLOCK)
							on  tov.optval_class	= 32
							and tov.lang_id			= @lang_id
							and tov.optval_id		= its.is_available

							LEFT JOIN tbImportData AS tid2 WITH (NOLOCK)			-- MOS 11-2022
								ON 	tid2.comp_id		=	ITS.[comp_id]
								and tid2.ct_transaction =   ITS.ct_transaction
								and tid2.it_transaction =   ITS.it_transaction

					where		 @comp_id   = its.comp_id
						and		(@import_id = -1 or		IM.[import_id]		= @import_id)
						and		(@item_id   = -1 or		ITS.[item_id]		= @item_id)
						and		(@cat_id    = -1 or		C.[cat_id]			= @cat_id)
						and		(@subcat_id = -1 or		SC.[subcat_id]		= @subcat_id)
						and		(@brand_id  = -1 or		B.[brand_id]		= @brand_id)
						and		(@supp_id	= -1 or		tct.[supp_id]		= @supp_id)
						AND		(@stor_id	= -1 or		ITS.stor_id			= @stor_id)
						-- --------------------------------------------------------------
						-- ATENCION si se toca este SP, corregir los filtros en el
						-- sp [spItemSerial_setAutonumericSerial]
						-- --------------------------------------------------------------
						--  @pendientes = -1  : traer todos
						--  @pendientes =  1  : pendientes
						--  @pendientes = 2  : no pendientes
						AND		(
									 @pendientes=-1											OR
									(@pendientes=1 AND  IsNull(ITS.is_serial,'')   =  '')	OR
									(@pendientes=2 AND  IsNull(ITS.[is_serial],'') <> '')	OR
									(@pendientes=3 AND  IsNull(ITS.[is_serial],'') <> '' AND its.is_IsOwnGeneration='true')
								)
						AND		its.is_cd >= @MinimumDateUpdated
						AND		(@bra_id = -1 OR its.bra_id = @bra_id)
						 ------------------------------------------------------------

						AND		(@bitOnlyGenerated	= 'false'	OR (@bitOnlyGenerated = 'true' AND its.is_IsOwnGeneration = 'true'))
						AND		(@useGuid2Filter	= 'false'	OR its.is_guid = @guid)
						AND		(ltrim(rtrim(tct.ct_docNumber))	= ltrim(rtrim(@ct_docNumber))	OR @ct_docNumber		= '')--CONVERT(NVARCHAR,''))
						AND		(@isAvailable		= -1		or its.is_available	= @isAvailable)




					--ORDER BY ITS.is_id
			)
		END


	--marcar con el guid los artículos cargados en temporal
	IF @useGuid2Filter ='false'
	BEGIN
		UPDATE	tbItemSerials
		SET		is_guid = @guid
		FROM	tbItemSerials			tis	WITH (NOLOCK)
				INNER JOIN #tmpSerials	tmp
				ON	tmp.is_id = tis.is_id
	END



	IF @bitMustPrintItemParts = 'False'
		BEGIN
			--recuperar los datos de la temporal
			SELECT	tmp.item_code,
					tmp.item_desc,
					tmp.is_serial,
					tmp.is_id,
					convert(nvarchar,tmp.supp_id) + '-' + tmp.supp_name	 [supplier],
					tmp.supp_name,
					tmp.impData_number,
					tmp.impData_Custom,
					tmp.impData_origin,
					tmp.impData_from,
					tmp.country_desc,
					dbo.fnStrPADR(ts.stor_desc,15,'-') + ' * ' +
					dbo.fnGetCommercialTransactionDescription(tmp.comp_id,@lang_id,tmp.ct_Transaction)	[Document],
					tmp.ct_date,
					tmp.supp_id,
					tmp.is_available,
					1									[itemPart],		-- MOS 07-2022
					1									[itemPartMAX],
					''									[itp_desc],		-- MOS 07-2022
					tis.item_id

				FROM	#tmpSerials					tmp		WITH (NOLOCK)
				INNER JOIN tbItemSerials			tis		WITH (NOLOCK)
					ON		tis.comp_id		= @comp_id
						AND tis.is_id		= tmp.is_id
				INNER JOIN tbStorage				ts		WITH (NOLOCK)
					ON		ts.comp_id		= @comp_id
						AND ts.stor_id		= tis.stor_id
				ORDER BY tmp.is_id
		END
	ELSE
		BEGIN	-- MOS 07-2022
			--recuperar los datos de la temporal y agregar PARTES de articulos
			SELECT	tmp.item_code,
					tmp.item_desc,
					tmp.is_serial,
					tmp.is_id,
					convert(nvarchar,tmp.supp_id) + '-' + tmp.supp_name	 [supplier],
					tmp.supp_name,
					tmp.impData_number,
					tmp.impData_Custom,
					tmp.impData_origin,
					tmp.impData_from,
					tmp.country_desc,
					dbo.fnStrPADR(ts.stor_desc,15,'-') + ' * ' +
					dbo.fnGetCommercialTransactionDescription(tmp.comp_id,@lang_id,tmp.ct_Transaction)	[Document],
					tmp.ct_date,
					tmp.supp_id,
					tmp.is_available,
					ROW_NUMBER() OVER(partition BY tis.item_id,tis.is_id ORDER BY tis.item_id,tis.is_id DESC)			  AS itemPart,
					ISNULL(tip.itp_desc,'')																[itp_desc],
					tis.item_id
				INTO #tmpPARTSMAX
				FROM	#tmpSerials					tmp	WITH (NOLOCK)
				INNER JOIN tbItemSerials			tis	WITH (NOLOCK)
					ON		tis.comp_id		= @comp_id
						AND tis.is_id		= tmp.is_id
				LEFT JOIN tbItemParts			 AS tip	WITH (NOLOCK)
					ON	tip.comp_id = tis.comp_id AND
						tip.item_id = tis.item_id

				INNER JOIN tbStorage				ts	WITH (NOLOCK)
					ON		ts.comp_id		= @comp_id
						AND ts.stor_id		= tis.stor_id
				ORDER BY tmp.is_id

				--SELECT 9999
				--SELECT * FROM #tmpPARTSMAX

			SELECT *,MAX(itemPart) OVER(PARTITION BY item_id,is_id) itemPartMAX
				FROM #tmpPARTSMAX

			DROP TABLE #tmpPARTSMAX


		END





	--este valor de retorno es para validar si todos los items recuperados pertenecen o no al mismo artículo -->>   Mira que hay que ser HDP retorcido ehh....
	SET @return_value =	(	SELECT	CASE
										WHEN COUNT(*) = 1 THEN 1
										ELSE 0
	                   	 	      	END
                   				FROM (
                   						SELECT DISTINCT item_id
                   							FROM #tmpSerials
                   					 ) AS aaa
						)
	--SELECT @return_value


	DROP TABLE #tmpSerials


END
GO








CREATE procedure [dbo].[spItemSerial_setAutonumericSerial]
(
	@comp_id				INT,
	@import_id				INT,
	@pendientes				INT,
	@item_id				INT,
	@supp_id				INT,
	@cat_id					INT,
	@subcat_id				INT,
	@brand_id				INT,
	@Cant					INT,
	@MinimumDateUpdated		DATETIME,
	@bra_id					INT,
	@guid					UNIQUEIDENTIFIER,
	@return_value			INT OUTPUT
)
AS
SET NOCOUNT ON


/*
Declare	@comp_id			int,
		@import_id			int,
		@item_id			int,
		@supp_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@pendientes			Int,
		@Cant				INT,
		@return_value		VARCHAR(100)
Select	@comp_id			=1,
		@import_id			=-1,
		@item_id			=400,
		@supp_id			=-1,
		@cat_id				=-1,
		@subcat_id			=-1,
		@brand_id			=-1,
		@pendientes			=1,
		@Cant				= 5,
		@return_value		= ' '
*/


DECLARE @counter_value	INT
DECLARE @lcant			INT,
		--@litem_code		Varchar(100),
		--@litem_desc		Varchar(100),
		@lis_serial		VARCHAR(100),
		@lis_id			INT,
		@lrv			INT


DECLARE cursor_IS_sAS_items CURSOR FOR

SELECT	tis.is_serial,
		tis.is_id
	FROM	tbItemSerials tis
	WHERE	tis.comp_id = @comp_id
		AND	tis.is_guid = @guid
		AND (tis.is_serial IS NULL OR tis.is_serial = '')
	ORDER BY tis.is_id

/*		SELECT	Top(@cant)
				--I.item_code,
				--I.item_desc,
				ITS.is_serial,
				ITS.is_id


		FROM dbo.tbItemSerials	ITS

		left Join dbo.vwItemSerialsImportData	IM
		on	IM.comp_id					=	ITS.[comp_id]
		and IM.ct_transaction			=   ITS.ct_transaction
		and IM.it_transaction			=   ITS.it_transaction

--		Inner join dbo.tbImport			IM
--		on  IM.[comp_id]				=	ITS.[comp_id]
--		and IM.[import_id]				=   ITS.[import_id]

		left Join  dbo.tbItem			I
		on  I.[comp_id]					=	ITS.[comp_id]
		and I.[item_id]					=   ITS.[item_id]

		left JOIN tbCategory			C
		ON	C.[comp_id]					=	I.[comp_id]
		AND C.[cat_id]					=	I.[cat_id]

		left JOIN tbSubCategory			SC
		ON	SC.[comp_id]				=	I.[comp_id]
		AND SC.[cat_id]					=	I.[cat_id]
		AND SC.[subcat_id]				=	I.[subcat_id]

		left JOIN tbBrand				B
		ON	B.[comp_id]					=	I.[comp_id]
		AND B.[brand_id]				=	I.[brand_id]

		left JOIN dbo.tbSupplier		SU
		ON  SU.[comp_id]				=	I.[comp_id]
		and SU.[supp_id]				=   I.[supp_id]


		where (@import_id = -1 or  IM.[import_id]   = @import_id)
		and	  (@item_id   = -1 or ITS.[item_id]     = @item_id)
		and	  (@cat_id    = -1 or   C.[cat_id]      = @cat_id)
		and   (@subcat_id = -1 or  SC.[subcat_id]	= @subcat_id)
		and	  (@brand_id  = -1 or   B.[brand_id]	= @brand_id)
		and   (@supp_id	  = -1 or  SU.[supp_id]		= @supp_id)

		--  @pendientes = -1  : traer todos
		--  @pendientes =  1  : pendientes
		--  @pendientes =  2  : no pendientes
		and	 ( @pendientes = -1 or
			  (@pendientes = 1 and (ITS.[is_serial]  = '' or ITS.[is_serial] is null)) or
			  (@pendientes = 2 and (ITS.[is_serial] <> '' or ITS.[is_serial] is not null)) or
			  (@pendientes=3 AND  IsNull(ITS.[is_serial],'') <> '' AND its.is_IsOwnGeneration='true')
		     )
		AND its.is_cd >= @MinimumDateUpdated
  		AND (@bra_id = -1 OR its.bra_id = @brand_id)
		And (ITS.is_serial = '' Or  ITS.is_serial Is NULL)
*/



BEGIN TRY

	Open cursor_IS_sAS_items

	Fetch	cursor_IS_sAS_items
	Into	--@litem_code,
			--@litem_desc,
			@lis_serial,
			@lis_id

	While @@FETCH_STATUS = 0
	BEGIN

		SET @return_value = @return_value + 1


		Exec dbo.spCounters_getNextValue 1, 1, 300, @counter_value output


		update	dbo.tbItemSerials
		set		is_serial								= dbo.fnStrPADL(convert(varchar,@counter_value),10,'0'),
				dbo.tbItemSerials.is_IsOwnGeneration	= 'True',
				dbo.tbItemSerials.is_available			= 'True',
				dbo.tbItemSerials.is_guid 				= @guid

		from	dbo.tbItemSerials	ITS
		where	ITS.[comp_id]		= @comp_id
		and     ITS.[is_id]			= @lis_id


		Fetch	cursor_IS_sAS_items
		Into	--@litem_code,
				--@litem_desc,
				@lis_serial,
				@lis_id

	End

	Close cursor_IS_sAS_items
	Deallocate cursor_IS_sAS_items


	SET @return_value = 0

END TRY
BEGIN CATCH
	SET @return_value = -1
END CATCH





GO






-- MOS 02-2010


CREATE procedure [dbo].[spItemSerial_Update]
(
	@comp_id			int,
	@is_serial			varchar(200),
	@is_id				int,
	@import_id			int,
	@return_value		Int output
)
AS

  BEGIN

	  SET NOCOUNT ON


-- --------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------
/*
	  DECLARE @comp_id			int,
  			@is_serial			varchar(200),
  			@is_id				int,
  			@import_id			Int,
  			@return_value		Int
	  SELECT	@comp_id			=1,
  			@is_serial			='V09300G10400492',
  			@is_id				=4566,
  			@import_id			=-1
*/
-- --------------------------------------------------------------


      -- MOS
	  -- No Actualizar IsAvailable si esta en falso y ya tiene un numero de serie
      DECLARE @bitNoUpdateIsAvailable AS BIT
	  SET @bitNoUpdateIsAvailable = 'False'
		if exists(	SELECT top 1 1
		          		FROM tbItemSerials tis	WITH (NOLOCK)
      					WHERE	tis.comp_id		 = @comp_id
      						AND tis.is_id		 = @is_id
      						and tis.is_available = 'false'
					        AND (tis.is_serial IS NOT NULL AND dbo.fnStrAllTrim(is_serial) <> '')
				)
			BEGIN
				SET @bitNoUpdateIsAvailable = 'True'
			END
	  -- ------------------------------------------------------------


	  -- MOS
	  -- Si el numero de serie no esta disponible y no esta vacio, no se lo puede vaciar.
		if exists(	SELECT TOP 1 1
		          		FROM tbItemSerials tis	WITH (NOLOCK)
      					WHERE	tis.comp_id		 = @comp_id
      						AND tis.is_id		 = @is_id
      						and tis.is_available = 'false'
					        AND (tis.is_serial IS NOT NULL AND dbo.fnStrAllTrim(is_serial) <> '')) and @is_serial = ''
			BEGIN
				SET	   @return_value = -1
				SELECT @return_value
				RETURN
			END
	  -- ------------------------------------------------------------

--==
--SELECT @bitNoUpdateIsAvailable
--SELECT 9999
--==




		------------------------------------------------------------------------------
		-- obtener una marca para saber si el serial actualizar es diferente del uno anterior ya cargado

		DECLARE @lserialexistente		BIT
		SET @lserialexistente	= 'false'

		IF EXISTS	(
						SELECT TOP 1	1
							FROM	tbItemSerials	tis	WITH (NOLOCK)
							WHERE	tis.comp_id		=	@comp_id
							AND		tis.is_id		=	@is_id
							AND		tis.is_serial	<>	''
							AND NOT tis.is_serial	IS	NULL
							AND		ltrim(rtrim(tis.is_serial)) <> ltrim(rtrim(@is_serial))
					)
			BEGIN
				SET @lserialexistente	= 'true'
			END
		------------------------------------------------------------------------------





	  update	dbo.tbItemSerials
		  set
  				is_available		= case
  										 when @is_serial <> '' AND @bitNoUpdateIsAvailable = 'False'	then 'True'
  										 WHEN @is_serial =  ''											THEN 'FALSE'
  										 ELSE is_available
  									  END,
  				is_serial			= case
  										 when @is_serial = '' THEN NULL
  										 ELSE @is_serial
  									  END
		  from	dbo.tbItemSerials	ITS
		  where	ITS.[comp_id]		= @comp_id
		  and   ITS.[is_id]			= @is_id
		  And	Not Exists (SELECT TOP 1	1
     							From	tbItemSerials tis WITH (NOLOCK)
  								Where	tis.comp_id   = @comp_id
  									And	tis.is_serial = @is_serial
									AND @is_serial	  <> '')
		-- MOS: 07-2011: Ahora permite cambiart cualquier numero de serie
		--		  AND	(	its.is_available='true'
		--					or ((its.is_serial IS NULL OR its.is_serial = '')  AND its.is_available='false')
		--		  )

	  Set @return_value = @@ROWCOUNT




--==
--SELECT '@@ROWCOUNT', @@ROWCOUNT
--==


	  -- MOS
	  -- Si el numero de serie no estaba disponible, retorna ese error
--	  IF @return_value = 0	and exists(	SELECT 1 FROM tbItemSerials tis
--	                      					WHERE	tis.comp_id		 = @comp_id
--	                      						AND tis.is_id		 = @is_id
--	                      						and tis.is_available = 'false'
--										        AND tis.is_serial IS NOT NULL)
--	      SET @return_value = -1
	  -- ------------------------------------------------------------





	  -- MOS
	  -- Si el numero de serie es el Mismo que tenia antes
	  IF @return_value = 0	and exists(	SELECT TOP 1 1
	                      	           		FROM tbItemSerials tis	WITH (NOLOCK)
	                      					WHERE	tis.comp_id		 = @comp_id
	                      						AND tis.is_id		 = @is_id
										        AND tis.is_serial    = @is_serial)
	      BEGIN
			SET @return_value = 1
	      END
	  -- ------------------------------------------------------------





		------------------------------------------------------------------------------
		-- se agrega esta condición para indicarle al código de la página que se modificó
		-- un serial existente, en ese caso retorna el valor 2

		IF @return_value = 1 AND @lserialexistente = 'true'
			BEGIN
				SET @return_value = 2
			END
		------------------------------------------------------------------------------



	  Select @return_value

  END
GO









/***************************************************************************************************/
/*
* ATENCION -- SI SE MODIFICAN LOS CAMPOS DEL QUERY FINAL TAMBIEN SE DEBEN MODIFICAR DE LA MISMA
* FORMA LOS CAMPOS DEL SP [spItemSerial_Load] YA QUE AMBOS SPS LLENAN LA MISMA GRILLA
* EN LA PÁGINA wfmItemSerialLoad_Update
*
* TAMBIÉN DEBE VARIFICARSE SI DEBE ACTUALIZARSE EL SP [spItemSerials_updateIncremental] YA QUE TOMA
* EN UNA TEMPORAL LOS DATOS QUE DEVUELVE EL QUERY FINAL DE ESTE SP
*/
/***************************************************************************************************/

CREATE PROCEDURE [dbo].[spItemSerials_getDataByGuid]
(
	@comp_id		INT,
	@lang_id		INT,
	@Guid			UNIQUEIDENTIFIER,
	@cant			INT,
	@is_serial		INT
)
AS

BEGIN

	-- ATENCION: Si se toca este SP hacerlo tambien en el spItemSerials_getDataByGuid										y spItemSerials_getDataByGuid2 (MOS 11-2022, este ultimo NO)

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	-- ------------------------------------------
	-- TEsting
	-- ------------------------------------------
	/*
	DECLARE	@comp_id	int,
			@Guid		UNIQUEIDENTIFIER
	SELECT 	@comp_id	=1,
			@Guid		='8b4ea3cc-a6b4-4315-9a01-15e875d8c517'
	*/
	-- ------------------------------------------

	SELECT	TOP(@cant)

			I.item_code,
			I.item_desc,
			ITS.is_serial,
			ITS.is_id,

			convert(nvarchar,ts.supp_id) + '-' + ts.supp_name									[supplier],
			ts.supp_name,

			CASE	-- MOS 11-2022
				WHEN ISNULL(ti.impData_number,'')			<> ''	THEN ti.impData_number
				WHEN ISNULL(tid2.impData_Number_local,'')	<> ''	THEN tid2.impData_Number_local
				ELSE ''
			END																					[impData_number],
			--ti.impData_number,
			CASE	-- MOS 11-2022
				WHEN ISNULL(ti.impData_Custom,'')			<> ''	THEN ti.impData_Custom
				WHEN ISNULL(tid2.impData_Custom_local,'')	<> ''	THEN tid2.impData_Custom_local
				ELSE ''
			END																					[impData_Custom],

			--ti.impData_number,
			--ti.impData_Custom,

			tc.country_desc,

			dbo.fnGetCommercialTransactionDescription(ITS.comp_id,@lang_id,ITS.ct_Transaction)	[Document],
			tct.ct_date,
			TS.supp_id,

			tov.optval_desc [is_available],
			CASE	-- MOS 11-2022
				WHEN ISNULL(ti.impData_origin,'')			<> ''	THEN ti.impData_origin
				WHEN ISNULL(tid2.impData_Origin,'')			<> ''	THEN tid2.impData_Origin
				ELSE ''
			END																					[impData_origin],
			CASE	-- MOS 11-2022
				WHEN ISNULL(ti.impData_from,'')				<> ''	THEN ti.impData_from
				WHEN ISNULL(tid2.impData_From,'')			<> ''	THEN tid2.impData_From
				ELSE ''
			END																					[impData_from]


	FROM	dbo.tbItemSerials							ITS		WITH (NOLOCK)

			LEFT JOIN  dbo.tbItem						I		WITH (NOLOCK)
			ON  I.[comp_id]			= ITS.[comp_id]
			AND I.[item_id]			= ITS.[item_id]

			INNER JOIN tbCommercialTransactions			tct		WITH (NOLOCK)
			ON	tct.comp_id			= ITS.comp_id
			AND tct.bra_id			= ITS.bra_id
			AND tct.ct_transaction	= ITS.ct_transaction

			left JOIN tbSupplier						ts		WITH (NOLOCK)
			ON	ts.comp_id			= tct.comp_id
			AND ts.supp_id			= tct.supp_id

			LEFT JOIN tbImportDetail					tid		WITH (NOLOCK)
			ON  tid.comp_id         = its.comp_id
			AND tid.bra_id			= its.bra_id
			AND tid.ct_transaction  = its.ct_transaction

			LEFT JOIN tbImport							ti		WITH (NOLOCK)
			ON	ti.comp_id			= its.comp_id
			AND ti.import_id		= tid.import_id

			LEFT JOIN tbsysCountry						tc		WITH (NOLOCK)
			ON	tc.country_id		= ti.country_id

			left join tbsysOptionsValues					tov	WITH (NOLOCK)
			on  tov.optval_class	= 32
			and tov.lang_id			= @lang_id
			and tov.optval_id		= its.is_available


			LEFT JOIN tbImportData AS tid2 WITH (NOLOCK)			-- MOS 11-2022
				ON 	tid2.comp_id		=	ITS.[comp_id]
				and tid2.ct_transaction =   ITS.ct_transaction
				and tid2.it_transaction =   ITS.it_transaction


	WHERE	ITS.comp_id		= @comp_id
	AND		ITS.is_guid		= @Guid
	AND		(
				(@is_serial =-1				                 ) OR
				(@is_serial = 0 AND     ISNULL(ITS.is_serial,'') = '') OR
				(@is_serial = 1 AND NOT ISNULL(ITS.is_serial,'') = '')
			)


END
GO









/***************************************************************************************************/
/*
* ATENCION -- SI SE MODIFICAN LOS CAMPOS DEL QUERY FINAL TAMBIEN SE DEBEN MODIFICAR DE LA MISMA
* FORMA LOS CAMPOS DEL SP [spItemSerial_Load] YA QUE AMBOS SPS LLENAN LA MISMA GRILLA
* EN LA PÁGINA wfmItemSerialLoad_Update
*
* TAMBIÉN DEBE VARIFICARSE SI DEBE ACTUALIZARSE EL SP [spItemSerials_updateIncremental] YA QUE TOMA
* EN UNA TEMPORAL LOS DATOS QUE DEVUELVE EL QUERY FINAL DE ESTE SP
*/
/***************************************************************************************************/


-- MOS 11-2022: no se usa en VB, solo lo llama: [spItemSerials_updateIncremental]

CREATE PROCEDURE [dbo].[spItemSerials_getDataByGuid2]
(
	@comp_id		INT,
	@lang_id		INT,
	@Guid			UNIQUEIDENTIFIER,
	@cant			INT,
	@is_serial		INT,
	@item_id		INT
)
AS

BEGIN


	-- ATENCION: Si se toca este SP hacerlo tambien en el spItemSerials_getDataByGuid y spItemSerials_getDataByGuid2


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON





	-- ------------------------------------------
	-- TEsting
	-- ------------------------------------------
	/*
	DECLARE	@comp_id	int,
			@Guid		UNIQUEIDENTIFIER
	SELECT 	@comp_id	=1,
			@Guid		='8b4ea3cc-a6b4-4315-9a01-15e875d8c517'
	*/
	-- ------------------------------------------

	SELECT	TOP(@cant)

			I.item_code,
			I.item_desc,
			ITS.is_serial,
			ITS.is_id,

			convert(nvarchar,ts.supp_id) + '-' + ts.supp_name									[supplier],
			ts.supp_name,

			ti.impData_number,
			ti.impData_Custom,
			tc.country_desc,

			dbo.fnGetCommercialTransactionDescription(ITS.comp_id,@lang_id,ITS.ct_Transaction)	[Document],
			tct.ct_date,
			TS.supp_id,

			tov.optval_desc [is_available]

	FROM	dbo.tbItemSerials							ITS		WITH (NOLOCK)

			LEFT JOIN  dbo.tbItem						I		WITH (NOLOCK)
			ON  I.[comp_id]			= ITS.[comp_id]
			AND I.[item_id]			= ITS.[item_id]

			INNER JOIN tbCommercialTransactions			tct		WITH (NOLOCK)
			ON	tct.comp_id			= ITS.comp_id
			AND tct.bra_id			= ITS.bra_id
			AND tct.ct_transaction	= ITS.ct_transaction

			left JOIN tbSupplier						ts		WITH (NOLOCK)
			ON	ts.comp_id			= tct.comp_id
			AND ts.supp_id			= tct.supp_id

			LEFT JOIN tbImportDetail					tid		WITH (NOLOCK)
			ON  tid.comp_id         = its.comp_id
			AND tid.bra_id			= its.bra_id
			AND tid.ct_transaction  = its.ct_transaction

			LEFT JOIN tbImport							ti		WITH (NOLOCK)
			ON	ti.comp_id			= its.comp_id
			AND ti.import_id		= tid.import_id

			LEFT JOIN tbsysCountry						tc		WITH (NOLOCK)
			ON	tc.country_id		= ti.country_id

			left join tbsysOptionsValues					tov		WITH (NOLOCK)
			on  tov.optval_class	= 32
			and tov.lang_id			= @lang_id
			and tov.optval_id		= its.is_available


	WHERE	ITS.comp_id		= @comp_id
	AND		ITS.is_guid		= @Guid
	AND		(
				(@is_serial =-1				                 ) OR
				(@is_serial = 0 AND     ISNULL(ITS.is_serial,'') = '') OR
				(@is_serial = 1 AND NOT ISNULL(ITS.is_serial,'') = '')
			)
	AND
			(@item_id = -1 OR its.item_id = @item_id)


END
GO








CREATE PROCEDURE [dbo].[spItemSerials_getDataById]
(
	@comp_id		INT,
	@is_id			INT
)
AS


BEGIN


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


/*
	DECLARE	@comp_id		INT,
			@isd_id			INT
	SELECT	@comp_id		= 1,
			@is_id			= 5122
*/


	DECLARE @strPartsSerials AS NVARCHAR(MAX) = ''
	SELECT  @strPartsSerials = @strPartsSerials + '/' + tis.is_serial
		FROM tbItemSerials4Production	AS tisp	WITH (NOLOCK)
		INNER JOIN tbItemSerials		AS tis	WITH (NOLOCK)
			ON	tis.comp_id			= tisp.comp_id AND
				tis.is_id			= tisp.is_idPart
		WHERE	tisp.comp_id		= @comp_id AND
				tisp.is_idProduced	= @is_id



	SELECT	ti.item_code,
			ti.item_desc,
			ti.item_annotation,
			tc.cat_desc,
			tsc.subcat_desc,
			tis.is_available,
			tis.stor_id,
			isnull(tis.is_serial,'')		[is_serial],
			ISNULL(@strPartsSerials,'')		[partsSerials]

		FROM	tbItemSerials					tis		WITH (NOLOCK)

		INNER JOIN tbItem				ti		WITH (NOLOCK)
			ON	ti.comp_id		= tis.comp_id
			AND ti.item_id		= tis.item_id

		INNER JOIN tbCategory			tc		WITH (NOLOCK)
			ON	tc.comp_id		= ti.comp_id
			AND tc.cat_id		= ti.cat_id

		INNER JOIN tbSubCategory		tsc			WITH (NOLOCK)
			ON	tsc.comp_id		= ti.comp_id
			AND tsc.cat_id		= ti.cat_id
			AND tsc.subcat_id	= ti.subcat_id

		WHERE	tis.comp_id		= @comp_id
		AND		tis.is_id		= @is_id


END
GO







CREATE PROCEDURE [dbo].[spItemSerials_getDataBySerials]
(
	@comp_id		INT,
	@serial			VARCHAR(100)
)
AS
SET NOCOUNT ON

/*
declare	@comp_id		INT,
		@serial			VARCHAR(100)

select	@comp_id		= 1,
		@serial			= 'cs001'
*/


SELECT	ti.item_code,
		ti.item_desc,
		tis.is_id,

		isnull(tit.it_price,0)  [it_price],
		isnull(tit.curr_id,0)	[curr_id],
		isnull(tit.stor_id,0)	[stor_id],
		isnull(tit.bra_id,0)	[bra_id],

		tis.item_id,
		tis.it_transaction,
		tis.is_available,
		tis.stor_id									[stor_serial],
		ts.stor_desc,

		tct.ct_date, --					+ ' - ' +
		ts2.supp_name				+ ' - ' +
		tid.impData_Custom_local	+ ' - ' +
		tid.impData_Number_local					[aditional_data]

FROM	tbItemSerials								tis			WITH (NOLOCK)

		INNER JOIN	tbItem							ti			WITH (NOLOCK)
		ON	ti.comp_id						=	tis.comp_id
		AND ti.item_id						=	tis.item_id
		--AND isnull(ti.item_expser,'false')	=	'true'

		LEFT JOIN	tbItemTransactions				tit			WITH (NOLOCK)
		ON	tit.comp_id			=	tis.comp_id
		AND tit.ct_transaction	=	tis.ct_transaction
		AND tit.it_transaction	=	tis.it_transaction

		LEFT JOIN	tbStorage						ts			WITH (NOLOCK)
		ON	ts.stor_id			= tis.stor_id
		AND ts.comp_id			= tis.comp_id

		LEFT JOIN	tbCommercialTransactions		tct			WITH (NOLOCK)
		ON	tct.comp_id			= tis.comp_id
		AND tct.bra_id			= tit.bra_id
		AND tct.ct_transaction	= tit.ct_transaction

		LEFT JOIN	tbSupplier						ts2			WITH (NOLOCK)
		ON  ts2.comp_id			= tis.comp_id
		AND ts2.supp_id			= tct.supp_id

		LEFT JOIN	tbImportData					tid			WITH (NOLOCK)
		ON  tid.comp_id			= tis.comp_id
		AND tid.item_id			= tis.item_id
		AND tid.it_transaction	= tis.it_transaction


WHERE	tis.comp_id				=	@comp_id
AND		tis.is_serial			=	@serial


GO


CREATE PROCEDURE [dbo].[spItemSerials_getDataByStorage]
(
	@comp_id			INT,
	@stor_id			INT,
	@it_transaction		INT,
	@item_id			INT
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT On

	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------
	/*
	DECLARE 	@comp_id		  INT,
				@stor_id		  INT,
				@it_transaction	  INT,
				@item_id		  INT

	SELECT      @comp_id        = 1,
				@stor_id		= 1,
				@it_transaction = 2892,
				@item_id		= 353
	*/
	-- -----------------------------------------------------------------------------


	SELECT	' '					[ ],
			tis.is_checked,
			ti.item_code,
			ti.item_desc,
			tis.is_serial,
			tis.is_id			[ID]

	FROM	tbItemSerials					tis		WITH (NOLOCK)

			INNER JOIN tbItem				ti		WITH (NOLOCK)
			ON  ti.comp_id = tis.comp_id
			AND ti.item_id = tis.item_id

			INNER JOIN tbBranch				tb		WITH (NOLOCK)
			ON	tb.comp_id = tis.comp_id
			AND tb.bra_id	= tis.bra_id


	WHERE	tis.comp_id			= @comp_id
	AND		(tb.bra_SaleOrderSerials4DifStorage = 'true' OR tis.stor_id = @stor_id)
	AND		tis.item_id			= @item_id
	AND		tis.it_transaction	= @it_transaction
	AND		tis.is_available	= 'true'
	AND     ti.item_expser		= 'true'




END
GO




CREATE PROCEDURE [dbo].[spItemSerials_getDataCommercialTransactionsBySerials]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@is_serial			VARCHAR(100)
)
AS
SET NOCOUNT ON


--------------------------------------------------------------------------------------------------------
/*

declare	@comp_id		INT,
		@serial			VARCHAR(100)

select	@comp_id		= 1,
		@serial			= 'ZZ9901'

*/
--------------------------------------------------------------------------------------------------------


SELECT TOP 1
	tct.ct_transaction

	FROM	tbItemTransactionSerials						tits	WITH (NOLOCK)

	INNER JOIN tbItemSerials								tis	WITH (NOLOCK)
	ON	tis.comp_id					= tits.comp_id
	AND tis.is_id					= tits.is_id

	INNER JOIN tbItemTransactions							tit	WITH (NOLOCK)
	ON  tit.comp_id					= tits.comp_id
	AND tit.it_transaction			= tits.it_transaction
	AND tit.ct_transaction			= tits.ct_transaction

	INNER JOIN tbCommercialTransactions						tct	WITH (NOLOCK)
	ON	tct.comp_id					= tit.comp_id
	AND tct.bra_id					= tit.bra_id
	AND tct.ct_transaction			= tit.ct_transaction

	left JOIN tbCustomer									tc	WITH (NOLOCK)
	ON  tc.comp_id					= tct.comp_id
	AND tc.cust_id					= tct.cust_id



	WHERE  tis.comp_id				= @comp_id
	and    tis.is_serial			= @is_serial
	AND	   tct.sd_id				= 1

	ORDER BY tct.ct_transaction desc
GO







CREATE PROCEDURE [dbo].[spItemSerials_getGridData]
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@lang_id	INT,

	@is_serial	varchar(100),
	@DetailSerial VARCHAR(100)
)
AS


BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------
	/*
		DECLARE
		@comp_id	INT,
		@bra_id		INT,
		@prof_id	INT,
		@user_id	INT,
		@lang_id	INT,

		@is_serial	varchar(100),
		@DetailSerial VARCHAR(100)
		SELECT
			@is_serial	= '0000003450',
			@DetailSerial	= '',@comp_id = 1
	*/
	-- -----------------------------------------------------------

	SELECT
		tis2.is_serial,
		ti.item_code,
		ti.item_desc,
		tisp.soh_id

	FROM tbItemSerials tis

			INNER JOIN tbItemSerials4Production tisp				WITH (NOLOCK)
			ON	tisp.comp_id		= tis.comp_id		AND
				tisp.is_idProduced	= tis.is_id

			INNER JOIN tbItemSerials tis2							WITH (NOLOCK)
			ON	tis2.comp_id	= tis.comp_id			AND
				tis2.is_id		= tisp.is_idPart

			INNER JOIN tbItem ti									WITH (NOLOCK)
			ON	ti.comp_id		= tis.comp_id			AND
				ti.item_id		= tis2.item_id


	WHERE	tis.comp_id		= @comp_id		AND
			tis.is_serial	= @is_serial	AND
			(@DetailSerial = '' OR tis2.is_serial = @DetailSerial)


END
GO







CREATE PROCEDURE [dbo].[spItemSerials_getMovementsLog]
(
	@comp_id		INT,
    @lang_id		INT,
    @bra_id			INT,
    @prof_id		INT,
    @user_id		INT,
	@serial			VARCHAR(100)
)
AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	-- - ----------------------------------------------------
	-- Testing
	-- - ----------------------------------------------------
	/*
	DECLARE @comp_id INT,
			@lang_id INT,
			@serial VARCHAR(100)


	SELECT  @comp_id = 1,
			@lang_id = 2,
			@serial = 'RRFFGG'
	*/
	-- - ----------------------------------------------------




	-- - ----------------------------------------------------
	-- Textos de la tbSysUniqueTexts para los Querys
	-- - ----------------------------------------------------

	DECLARE
		@litem_id					INT,
		@message1					VARCHAR(100),
		@message_supp				VARCHAR(100),
		@message_rma				VARCHAR(100),
		@message_rmanumber			VARCHAR(100),
		@message_cust				VARCHAR(100),
		@message_fromothererp		VARCHAR(100)


	SELECT @message1				= tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 950 --ING
	SELECT @message_supp			= tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 951 --PROVEEDOR
	SELECT @message_rma				= tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 952 --RMA
	SELECT @message_rmanumber		= tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 953 --Nº RMA:
	SELECT @message_cust			= tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 954 --CLIENTE
	SELECT @message_fromothererp	= tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 995 --IMPORTACIÓN

	-- - ----------------------------------------------------------------



	--------------------------
	DECLARE @lhideSuppByControlProfiles		INT

	SET @lhideSuppByControlProfiles = 0

	SET @lhideSuppByControlProfiles = (SELECT
											TOP 1 1
										    FROM tbControlProfiles AS tcp1	WITH (NOLOCK)
										    WHERE	tcp1.comp_id = @comp_id AND
										            tcp1.bra_id  = @bra_id  AND
										            tcp1.prof_id = @prof_id AND
										            tcp1.page_id = 187 AND
										            tcp1.ctrl_id = 6177)




	-------------------------------

	-- ------------------------------------------------------------------
	-- Trae Datos del Item
	-- ------------------------------------------------------------------


	-- SI existe en la itemserials muestra los datos de esa tabla
	IF EXISTS( SELECT top 1 is_id FROM tbItemSerials WHERE comp_id = @comp_id AND is_serial = @serial )
		BEGIN

			SELECT @litem_id = tis.item_id
				FROM tbItemSerials tis
				WHERE	tis.comp_id		= @comp_id AND
						tis.is_serial	= @serial

			SELECT	ti.item_code + ' - ' + ti.item_desc		[Desc],
					tis.item_id								[item_id],
					tis.is_id								[is_id],
					isnull(ti.item_guarantee,0)				[Guarantee],
					'False'									[isFromOtherERP]

				FROM	tbItemSerials											tis			WITH (NOLOCK)

						INNER JOIN tbItem										ti			WITH (NOLOCK)
						ON	ti.comp_id					= tis.comp_id
						AND ti.item_id					= tis.item_id

				WHERE  tis.comp_id						= @comp_id
				AND    tis.is_serial					= @serial

		END

	ELSE
		-- SINO verificamos si existe en la tbItemSerialsFromOtherERP y muestra los datos de esa tabla
		BEGIN
			IF EXISTS( SELECT top 1 isfo_id FROM tbItemSerialsFromOtherERP WHERE comp_id = @comp_id AND isfo_serial = @serial )
				BEGIN

					SELECT @litem_id = tisf.item_id
						FROM tbItemSerialsFromOtherERP tisf
						WHERE	tisf.comp_id		= @comp_id AND
								tisf.isfo_serial	= @serial

					SELECT	ti.item_code + ' - ' + ti.item_desc		[Desc],
							tisfoe.item_id							[item_id],
							tisfoe.isfo_id							[is_id],
							isnull(ti.item_guarantee,0)				[Guarantee],
							'True'									[isFromOtherERP]

						FROM	tbItemSerialsFromOtherERP tisfoe			WITH (NOLOCK)

								INNER JOIN tbItem										ti			WITH (NOLOCK)
								ON	ti.comp_id					= tisfoe.comp_id
								AND ti.item_id					= tisfoe.item_id

						WHERE  tisfoe.comp_id						= @comp_id
						AND    tisfoe.isfo_serial					= @serial
				END


		END

	-- ------------------------------------------------------------------



	-- ------------------------------------------------------------------
	-- Historiales
	-- ------------------------------------------------------------------

	-- Historial de Importacion desde otro ERP.-
	SELECT

		titf.ith_date											[dateDoc],
		@message_fromothererp									[type],
		tc.cust_id												[IDRef],
		tc.cust_name											[reference],
		td.sd_desc												[doc_number], --dbo.fnGetCommercialTransactionDescription(tct.comp_id,@lang_id,tct.ct_transaction),
		0														[ToDate],
		''														[RmaProc],
		ti.item_desc											[IsAvailable],
		''														[stor_desc],
		1														[order],
		''														[it_transaction]

		FROM tbItemSerialsFromOtherERP							tisfoe	WITH (NOLOCK)

		INNER JOIN tbItemTransactionsFromOtherERP				titf	WITH (NOLOCK)
		ON	titf.isfo_id		= tisfoe.isfo_id

		INNER JOIN tbItem										ti	WITH (NOLOCK)
		ON	ti.comp_id			= tisfoe.comp_id	AND
			ti.item_id			= tisfoe.item_id

		LEFT JOIN tbsysDocuments								td	WITH (NOLOCK)
		ON	td.sd_id			= titf.sd_id

		LEFT JOIN tbCustomer									tc	WITH (NOLOCK)
		ON  tc.comp_id			= titf.comp_id
		AND tc.cust_id			= titf.cust_id

		WHERE  tisfoe.comp_id				= @comp_id	AND
			   tisfoe.isfo_serial			= @serial	--AND
			   --tisfoe.item_id				= @litem_id


  UNION ALL


	-- Historial de Compras.-
	SELECT	tct.ct_date																			[dateDoc],
			@message_supp																		[type],
			ts.supp_id																			[IDRef],

			--ticket 13004
			CASE WHEN ISNULL(@lhideSuppByControlProfiles,0) = 1 THEN
				''
			ELSE
				ts.supp_name
			END
																								[reference],

			dbo.fnGetCommercialTransactionDescription(tis.comp_id,@lang_id,tis.ct_transaction)  [doc_number],
			DATEDIFF(day,tb.bra_processingDate,tct.ct_date)										[ToDate],
			''																					[RmaProc],
			tov2.optval_desc																	[IsAvailable],
			ts2.stor_desc																		[stor_desc],
			2																					[order],
			tis.it_transaction																	[it_transaction]

		FROM	tbItemSerials											tis	WITH (NOLOCK)

		inner JOIN tbCommercialTransactions						tct	WITH (NOLOCK)
		ON   tct.comp_id                = tis.comp_id
		AND  tct.ct_transaction			= tis.ct_transaction

		left JOIN tbSupplier									ts	WITH (NOLOCK)
		ON  ts.comp_id					= tis.comp_id
		AND ts.supp_id					= tct.supp_id

		inner join tbBranch										tb	WITH (NOLOCK)
		on  tb.comp_id					= tct.comp_id
		AND tb.bra_id					= tct.bra_id

		inner join tbsysOptionsValues							tov2	WITH (NOLOCK)
		on  tis.is_available			= tov2.optval_id
		and tov2.optval_class			= 123
		and tov2.lang_id				= @lang_id

		LEFT JOIN tbStorage ts2	WITH (NOLOCK)
			ON	ts2.comp_id = tis.comp_id AND
				ts2.stor_id = tis.stor_id

		WHERE	tis.comp_id						= @comp_id
		and     tis.is_serial					= @serial


  UNION ALL

	-- Historial de RMA
	SELECT	ISNULL(trd.rmad_Date_Reception, trh.rmah_cd)			[rmah_cd],
			@message_rma,
			tc.cust_id,
			tc.cust_name,
			@message_rmanumber + CONVERT(VARCHAR,trh.rmah_id) + ' ' +	CASE
																			WHEN trh.cust_id IS NULL THEN	@message_supp
																			ELSE							@message_cust
																		END,
			DATEDIFF(day,tb.bra_processingDate,tct.ct_date)			[ToDate],
			tov.optval_desc											[RmaProc],
			tov2.optval_desc										[IsAvailable],
			ts2.stor_desc											[stor_desc],
			2														[order],
			''														[it_transaction]

		FROM	tbRMA_Detail											trd	WITH (NOLOCK)

		INNER JOIN tbItemSerials								tis	WITH (NOLOCK)
		ON  tis.comp_id					= trd.comp_id
		AND tis.is_id					= trd.is_id

		INNER JOIN tbRMA_Header									trh	WITH (NOLOCK)
		ON  trh.comp_id					= trd.comp_id
		AND trh.rmah_id					= trd.rmah_id

		left JOIN tbCustomer									tc	WITH (NOLOCK)
		ON  tc.comp_id					= trh.comp_id
		AND tc.cust_id					= trh.cust_id

		inner JOIN tbCommercialTransactions						tct	WITH (NOLOCK)
		ON   tct.comp_id                = tis.comp_id
		AND  tct.ct_transaction			= tis.ct_transaction

		inner join tbBranch										tb	WITH (NOLOCK)
		on  tb.comp_id					= tct.comp_id
		AND tb.bra_id					= tct.bra_id

		inner join tbsysOptionsValues							tov	WITH (NOLOCK)
		on  trd.srpt_id					= tov.optval_id
		and tov.optval_class			= 109
		and tov.lang_id					= @lang_id

		inner join tbsysOptionsValues							tov2	WITH (NOLOCK)
		on  tis.is_available			= tov2.optval_id
		and tov2.optval_class			= 123
		and tov2.lang_id				= @lang_id

		LEFT JOIN tbStorage										ts2	WITH (NOLOCK)
		ON	ts2.comp_id					= trd.comp_id AND
			ts2.stor_id					= trd.stor_id


		WHERE  	tis.comp_id						= @comp_id
		and		tis.is_serial					= @serial



  UNION ALL


	-- Historial de Ventas
	SELECT	tct.ct_date,
			@message_cust,
			tc.cust_id,
			tc.cust_name,
			dbo.fnGetCommercialTransactionDescription(tct.comp_id,@lang_id,tct.ct_transaction),
			DATEDIFF(day,tb.bra_processingDate,tct.ct_date)			[ToDate],
			''														[RmaProc],
			tov2.optval_desc										[IsAvailable],
			ts2.stor_desc											[stor_desc],
			2														[order],
			tits.it_transaction										[it_transaction]



		FROM	tbItemTransactionSerials								tits	WITH (NOLOCK)

		INNER JOIN tbItemSerials								tis	WITH (NOLOCK)
		ON		tis.comp_id					= tits.comp_id
			AND tis.is_id					= tits.is_id

		INNER JOIN tbItemTransactions							tit	WITH (NOLOCK)
		ON  tit.comp_id					= tits.comp_id
		AND tit.it_transaction			= tits.it_transaction
		AND tit.ct_transaction			= tits.ct_transaction

		INNER JOIN tbCommercialTransactions						tct	WITH (NOLOCK)
		ON	tct.comp_id					= tit.comp_id
		AND tct.bra_id					= tit.bra_id
		AND tct.ct_transaction			= tit.ct_transaction

		left JOIN tbCustomer									tc	WITH (NOLOCK)
		ON  tc.comp_id					= tct.comp_id
		AND tc.cust_id					= tct.cust_id

		inner join tbBranch										tb	WITH (NOLOCK)
		on  tb.comp_id					= tct.comp_id
		AND tb.bra_id					= tct.bra_id

		inner join tbsysOptionsValues							tov2	WITH (NOLOCK)
		on  tis.is_available			= tov2.optval_id
		and tov2.optval_class			= 123
		and tov2.lang_id				= @lang_id

		LEFT JOIN tbStorage ts2	WITH (NOLOCK)
			ON	ts2.comp_id = tit.comp_id AND
				ts2.stor_id = tit.stor_id


		WHERE  tis.comp_id						= @comp_id
		and    tis.is_serial					= @serial


  UNION all


	-- Historial de Serializacion de PEDIDOS
	SELECT	GETDATE(),
			@message_cust,
			tc.cust_id,
			tc.cust_name,
			convert(varchar,tsos.bra_id) + '-' + CONVERT(VARCHAR,tsos.soh_id),
			0														[ToDate],
			''														[RmaProc],
			tov2.optval_desc										[IsAvailable],
			ts2.stor_desc											[stor_desc],
			2														[order],
			-1														[it_transaction]



		FROM	tbItemSerials								tis	WITH (NOLOCK)

		INNER JOIN tbSaleOrderSerials tsos	WITH (NOLOCK)
			ON	tsos.comp_id	= tis.comp_id	AND
				tsos.is_id		= tis.is_id

		INNER JOIN tbSaleOrderHeader tsoh	WITH (NOLOCK)
			ON	tsoh.comp_id	= tsos.comp_id	AND
				tsoh.bra_id		= tsos.bra_id	AND
				tsoh.soh_id		= tsos.soh_id

		INNER JOIN tbCustomer tc	WITH (NOLOCK)
			ON	tc.comp_id		= tsoh.comp_id	AND
				tc.cust_id		= tsoh.cust_id

		inner join tbsysOptionsValues							tov2	WITH (NOLOCK)
			on  tov2.optval_id				= 10
			and tov2.optval_class			= 123
			and tov2.lang_id				= @lang_id

		LEFT JOIN tbStorage ts2	WITH (NOLOCK)
			ON	ts2.comp_id = tis.comp_id AND
				ts2.stor_id = tis.stor_id

		WHERE  tis.comp_id						= @comp_id
		and    tis.is_serial					= @serial



		ORDER BY [order],1

END
GO






