CREATE procedure [dbo].[spItemSerials_getUnserializedItems]
(
	@comp_id	int,
	@lang_id	INT,
	@bra_id		INT		--SUCURSAL DE GENERACION
)

as set NOCOUNT on

	-- --------------------------------
	-- TESTING
	-- --------------------------------
	/*
	declare @comp_id	INT,
			@lang_id	INT,
			@bra_id		INT

	select	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1

	--drop table #tmpItemSerials
*/
	-- --------------------------------

begin
		-- ---------------------------------------------------------------
		-- Agrupamos por IT_TRANSACTION y lo enviamos a una temporal
		-- ---------------------------------------------------------------
--		select	tis.comp_id,
--				tis.it_transaction,
--				tis.item_id
--
--		into	#tmpItemSerials
--
--		from	tbItemSerials tis
--		where	tis.comp_id = @comp_id and
--				(@bra_id	= -1 or tis.bra_id	= @bra_id)  and
--				(tis.is_serial is null or tis.is_serial = '')
--
--		group by tis.comp_id,
--				 tis.it_transaction,
--				 tis.item_id

		-- ---------------------------------------------------------------


		-- ---------------------------------------------------------------
		-- Joineamos con la temporal para obtener los artículos no seria
		-- lizados y a que comprobante y depósito pertenecen
		-- ---------------------------------------------------------------

		select	ts2.supp_name																		[supp_name],
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tit.ct_transaction)	[document],
				ti.item_desc																		[item_desc],
				convert(decimal(17,0), tit.it_qty)																			[qty_inicial],
				count(*)																			[qty_pendiente],
				ts.stor_desc																		[stor_desc]

		from tbItemSerials									tis

			inner join tbItemTransactions					tit
			on	tit.comp_id			= tis.comp_id
			and tit.it_transaction	= tis.it_transaction

			inner join tbCommercialTransactions				tct
			on	tct.comp_id			= tit.comp_id
			AND tct.bra_id			= tit.bra_id
			AND tct.ct_transaction	= tit.ct_transaction

			inner join tbSupplier							ts2
			on  ts2.comp_id			= tct.comp_id
			AND ts2.supp_id			= tct.supp_id

			INNER JOIN tbItem								ti
			ON	ti.comp_id			= tis.comp_id
			AND ti.item_id			= tis.item_id

			inner join tbStorage							ts
			on	ts.comp_id			= tit.comp_id
			AND ts.stor_id			= tit.stor_id


		where	 tis.comp_id				= @comp_id
		and		(@bra_id					= -1 or tis.bra_id	= @bra_id)
		and		(tis.is_serial is null OR tis.is_serial = '')
		and		(ti.item_expser				= 'True')

		group by dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tit.ct_transaction),
				 tit.it_transaction,
				 item_desc,
				 stor_desc,
				 tct.ct_date,
				 ts2.supp_name,
				 tct.ct_transaction,
				 ti.cat_id,
				 ti.subcat_id,
				 tit.it_qty

		order by tct.ct_date,
				 ts2.supp_name,
				 tct.ct_transaction,
				 ti.cat_id,
				 ti.subcat_id

		-- ---------------------------------------------------------------

end

GO






-- 22-03-2010 = MOH = se cambia la condición de WHERE "AND is_IsOwnGeneration = 'False'" por is_printed = 'False'
--                  = con lo cuál se permiten inicializar seriales generados por cualquier método, pero no los
--                  = ya han sido impresos
--


CREATE PROCEDURE [dbo].[spItemSerials_InitialySerials]
(
	@comp_id		INT,
	@Guid			UNIQUEIDENTIFIER
)
AS
SET NOCOUNT ON


/*
DECLARE	@comp_id		int,
		@Guid			UNIQUEIDENTIFIER
SELECT 	@comp_id		=1,
		@Guid			= '8b4ea3cc-a6b4-4315-9a01-15e875d8c517'
*/


-- Inicializa solo los numeros de serie que NO fueron IMPRESOS


UPDATE	tbItemSerials

SET		is_serial		= NULL,
		--is_guid			= NULL,
		is_available	= 'false'

WHERE	comp_id						= @comp_id
AND		is_guid						= @Guid
AND		ISNULL(is_printed,'false')	= 'false'	-- esta condición evita que se inicialicen etiquetas que ya pueden haber sido pegadas en artículos
AND		is_available				= 'true'
GO






