CREATE PROCEDURE [dbo].[spItemSerials_insertQtyData]
(
    @comp_id			int,
	@bra_id				int,
	@ct_transaction		int,
	@it_transaction		int,
	@item_id			int,
	@stor_id			int,
	@qty				int
)
as

BEGIN


	set nocount ON


	-- --------------------------------------------------------------
	-- --------------------------------------------------------------
	/*
	declare   @comp_id			int,
		@bra_id				int,
		@ct_transaction		int,
		@it_transaction		int,
		@item_id			int,
		@stor_id			int,
		@qty				int

	select   @comp_id			= 1,
			@bra_id				=1,
			@ct_transaction		=1061,
		@it_transaction		=690,
		@item_id			=104,
		@stor_id			=3,
		@qty				=3
	*/
	-- --------------------------------------------------------------

	declare @is_cd datetime
	select @is_cd =  getdate()

	IF EXISTS(
				SELECT TOP 1 1
					FROM tbItem ti   WITH (NOLOCK)
					WHERE	ti.comp_id		= @comp_id AND
							ti.item_id		= @item_id AND
							ti.item_expser	= 'True'
				)

	BEGIN

		while @qty > 0
			begin
				insert into	dbo.tbitemserials	--WITH (ROWlock)
					(comp_id, bra_id, ct_transaction, it_transaction, item_id, is_serial,
					 is_cd, is_available, stor_id, is_guid)
				values
					(@comp_id, @bra_id, @ct_transaction, @it_transaction, @item_id, null,
					 @is_cd, 'False', @stor_id, null)

				--select @@identity

				set @qty = @qty - 1
			end

	END




END
GO






