update	dbo.tbItemSerials

set		is_available	= @is_available

where	comp_id			= @comp_id
and		is_serial		= @serial


GO




CREATE PROCEDURE [dbo].[spItemSerials_UpdateDataIsAvailableAndStorId]
(
	@comp_id		INT,
	@is_id			INT,
	@stor_id		INT,
	@is_available	BIT,
	@prof_id		INT,
	@user_id		INT,
	@bra_id			INT
)
AS SET NOCOUNT ON

	BEGIN

		-- ----------------------------------------------------------------------------
		-- VARIABLES LOCALES
		-- ----------------------------------------------------------------------------
		DECLARE
			@lisAvailableOriginal	BIT,
			@lStorIDOriginal		INT,
			@lserial				NVARCHAR(100),
			@lis_id					INT,
			@litem_id				INT,
			@lStorDescOriginal		VARCHAR(50),
			@lItemCode				VARCHAR(50),
			@lItemDesc				VARCHAR(500),
			@lStorDescUpdated		VARCHAR(50)

		SELECT
			@lisAvailableOriginal	= tis.is_available,
			@lStorIDOriginal		= ISNULL(tis.stor_id,0),
			@lis_id					= tis.is_id,
			@lserial				= tis.is_serial,
			@litem_id				= tis.item_id,
			@lStorDescOriginal		= ISNULL(ts.stor_desc,''),
			@litemcode				= ti.item_code,
			@litemdesc				= ti.item_desc
			FROM tbItemSerials		AS tis	WITH(NOLOCK)
			INNER JOIN tbItem		AS ti	WITH(NOLOCK)
				ON	ti.comp_id			= tis.comp_id AND
					ti.item_id			= tis.item_id
			LEFT JOIN tbStorage		AS ts	WITH(NOLOCK)
				ON	ts.comp_id			= tis.comp_id AND
					ts.stor_id			= tis.stor_id
			WHERE	tis.comp_id		= @comp_id	AND
					tis.is_id		= @is_id

		SELECT
			@lStorDescUpdated  = ts.stor_desc
			FROM tbStorage		AS ts	WITH(NOLOCK)
			WHERE	ts.comp_id = @comp_id AND
					ts.stor_id = @stor_id
		-- ----------------------------------------------------------------------------


		UPDATE tbItemSerials	WITH (ROWLOCK)
		SET
			is_available	= @is_available,
			stor_id			= @stor_id
		WHERE	comp_id		= @comp_id	AND
				is_id		= @is_id


		-- INSERTO EN LA SECURITYLOG
		INSERT INTO tbSecurityLog
		(
			comp_id,
			bra_id,
			user_id,
			seclog_obs_1,
			seclog_obs_2,
			seclog_cd,
			sysCode_id,
			prof_id
		)
		SELECT
			@comp_id,
			@bra_id,
			@user_id,
			'Valores anteriores: ID Artículo: ' + CONVERT(VARCHAR,@litem_id) + '  Código: ' + @lItemCode + ' Descripción: ' + @lItemDesc + ' Serie: ' + @lserial + ' Depósito: ' + CONVERT(VARCHAR,@lStorIDOriginal) + ' - ' + @lStorDescOriginal + ' Disponible: ' + CONVERT(VARCHAR,@lisAvailableOriginal) + ' | ' + 'Valores modificados: Depósito: ' + CONVERT(VARCHAR,@stor_id) + ' - ' + @lStorDescUpdated + ' Disponible: ' + CONVERT(VARCHAR,@is_available),
			'Valores modificados: Depósito: ' + CONVERT(VARCHAR,@stor_id) + ' - ' + @lStorDescUpdated + ' Disponible: ' + CONVERT(VARCHAR,@is_available),
			GETDATE(),
			2800,
			@prof_id

	END
GO






CREATE PROCEDURE [dbo].[spItemSerials_updateGridCheckedData]
(
	@comp_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@user_id		INT,
	@lang_id		INT,

	@guid			UNIQUEIDENTIFIER,
	@is_serial		NVARCHAR(100),

	@stor_id		INT,
	@it_transaction	INT,
	@item_id		INT,
	@return_value	BIT	OUTPUT
)

AS

BEGIN



	SET NOCOUNT ON


	-- ---------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------
	/*
		DECLARE
			@comp_id		INT,
			@bra_id			INT,
			@prof_id		INT,
			@user_id		INT,
			@lang_id		INT,

			@guid			UNIQUEIDENTIFIER,
			@is_serial		NVARCHAR(100),


			@stor_id		INT,
			@it_transaction	INT,
			@item_id		INT

		SELECT
			@comp_id		= 1,
			@bra_id			= 1,
			@prof_id		= 1,
			@user_id		= 1,
			@lang_id		= 2,

			@guid			= '26D99DE0-BEBF-405B-B77B-08A0347D00EB',
			@is_serial		= '980000181',

			@stor_id		= 1,
			@it_transaction	= 1050,
			@item_id		= 253
	*/

	-- ---------------------------------------------------------------


	DECLARE @is_id	INT

	SELECT @is_id = tis.is_id
		FROM tbItemSerials tis	WITH (NOLOCK)
		WHERE	tis.comp_id		= @comp_id
		AND		tis.is_serial	= @is_serial


	IF @is_id NOT IN (	SELECT tis.is_id
							FROM	tbItemSerials					tis		WITH (NOLOCK)
				  			INNER JOIN tbItem					ti		WITH (NOLOCK)
								ON  ti.comp_id = tis.comp_id
								AND ti.item_id = tis.item_id
							INNER JOIN tbBranch					tb		WITH (NOLOCK)
								ON	tb.comp_id = tis.comp_id
								AND tb.bra_id	= tis.bra_id
							WHERE	tis.comp_id			= @comp_id
							AND		(tb.bra_SaleOrderSerials4DifStorage = 'true' OR tis.stor_id = @stor_id)
							AND		tis.item_id			= @item_id
							AND		tis.it_transaction	= @it_transaction
							AND		tis.is_available	= 'true'
							AND     ti.item_expser		= 'true'
					 )


		SET @return_value = 0


	ELSE
		BEGIN

			UPDATE tbItemSerials	WITH (ROWLOCK)
			SET
				is_checked = 'True',
				is_guid	   =	CASE
									WHEN is_checked = 'true' THEN  NULL
									ELSE @guid
				       	    	END

			WHERE	comp_id		= @comp_id
			AND		is_serial	= @is_serial
			AND     is_id IN (SELECT tis.is_id
								  FROM	tbItemSerials					tis		WITH (NOLOCK)
									INNER JOIN tbItem					ti		WITH (NOLOCK)
										ON  ti.comp_id = tis.comp_id
										AND ti.item_id = tis.item_id
									INNER JOIN tbBranch					tb		WITH (NOLOCK)
										ON	tb.comp_id = tis.comp_id
										AND tb.bra_id	= tis.bra_id
									WHERE	tis.comp_id			= @comp_id
									AND		(tb.bra_SaleOrderSerials4DifStorage = 'true' OR tis.stor_id = @stor_id)
									AND		tis.item_id			= @item_id
									AND		tis.it_transaction	= @it_transaction
									AND		tis.is_available	= 'true'
									AND     ti.item_expser		= 'true'
							)

			SET @return_value = 1
		END



END
GO







-- Modificado x MOS
-- 01-2009
-- 02-2010


CREATE procedure [dbo].[spItemSerials_updateIncremental]
(
	@comp_id				INT,
	@import_id				INT,
	@pendientes				INT,
	@item_id				INT,
	@supp_id				INT,
	@cat_id					INT,
	@subcat_id				INT,
	@brand_id				INT,

	@Cant					INT,
	@bitOnlyGenerated		BIT,
	@initialSerial			VARCHAR(200),
	@Guid					UNIQUEIDENTIFIER,
	@return_value			INT OUTPUT
)
AS



BEGIN



	SET NOCOUNT ON

-- ------------------------------------------------------------------------
-- Testing
-- ------------------------------------------------------------------------
/*
	Declare	@comp_id			int,
			@import_id			int,
			@item_id			int,
			@supp_id			int,
			@cat_id				int,
			@subcat_id			int,
			@brand_id			int,
			@pendientes			Int,
			@Cant				int,
			@bitOnlyGenerated   BIT,
			@initialSerial		VARCHAR(200),
			@Guid				UNIQUEIDENTIFIER,
			@return_value		int
	Select	@comp_id			=1,
			@import_id			=-1,
			@item_id			=285,
			@supp_id			=-1,
			@cat_id				=-1,
			@subcat_id			=-1,
			@brand_id			=-1,
			@pendientes			=1,
			@Cant				= 10,
			@bitOnlyGenerated   ='false',
			@initialSerial		='0000003680',
			@Guid				='C2156392-4E31-413C-ACED-6713C77B9F06'
	DROP TABLE #tmp
*/
-- ------------------------------------------------------------------------

	DECLARE @tmp TABLE ([item_code]			VARCHAR(200)	NULL,
						[item_desc]			VARCHAR(200)	NULL,
						[is_serial]			VARCHAR(200)	NULL,
						[is_id]				INT				NULL,
						[supplier]			VARCHAR(500)	NULL,
						[Document]			VARCHAR(100)	NULL,
						[supp_name]			VARCHAR(200)	NULL,
						[impData_number]	VARCHAR(200)	NULL,
						[impData_Custom]	VARCHAR(200)	NULL,
						[country_desc]		VARCHAR(200)	NULL,
						[CT_DATE]			DATETIME,
						[supp_id]			INT				NULL,
						[is_available]		BIT )



	--CREATE TABLE #tmp (	[item_code]			VARCHAR(200)	NULL,
	--					[item_desc]			VARCHAR(200)	NULL,
	--					[is_serial]			VARCHAR(200)	NULL,
	--					[is_id]				INT				NULL,
	--					[supplier]			VARCHAR(500)	NULL,
	--					[Document]			VARCHAR(100)	NULL,
	--					[supp_name]			VARCHAR(200)	NULL,
	--					[impData_number]	VARCHAR(200)	NULL,
	--					[impData_Custom]	VARCHAR(200)	NULL,
	--					[country_desc]		VARCHAR(200)	NULL,
	--					[CT_DATE]			DATETIME,
	--					[supp_id]			INT				NULL,
	--					[is_available]		BIT )


	DECLARE @MinimumDateUpdated as DATETIME
	SET @MinimumDateUpdated = ISNULL(@MinimumDateUpdated,CAST('01-01-1800' AS DATETIME))


	set @return_value=0




	INSERT @tmp
		(
			[item_code],
			[item_desc],
			[is_serial],
			[is_id],
			[supplier],
			[supp_name],
			[impData_number],
			[impData_Custom],
			[country_desc],
			[Document],
			[ct_date],
			[supp_id],
			[is_available]
		)
			EXEC spItemSerials_getDataByGuid2 @comp_id, -1, @guid, @Cant, 0, @item_id


	--hay que hacer un cursor que recupere el is_id de la temporal
	--SELECT * FROM #tmp




	DECLARE @lis_id INT
	DECLARE @i INT
	SET		@i=0



	set @return_value=0

	DECLARE @newSerial VARCHAR(200)

	Declare curItemSerials CURSOR LOCAL FAST_FORWARD FOR
	SELECT t.is_id FROM @tmp t

	OPEN curItemSerials

	FETCH NEXT FROM curItemSerials INTO @lis_id

	WHILE @@Fetch_Status  <> -1
		BEGIN

			SELECT	@newSerial	=	dbo.fnGetSerialNumber4Incremental(@initialSerial,@i)
			SET		@i			=	@i+1

			SELECT @newSerial
					FROM   dbo.tbItemSerials tis		WITH (NOLOCK)
					WHERE  tis.comp_id		= @comp_id
					AND    tis.is_serial	= @newSerial
			-- si el serial no existe se actualiza
			IF NOT EXISTS(SELECT TOP 1 1
							  FROM   dbo.tbItemSerials tis	WITH (NOLOCK)
							  WHERE  tis.comp_id	= @comp_id
							  AND    tis.is_serial  = @newSerial)
			BEGIN
				UPDATE	dbo.tbItemSerials
					SET		is_serial		= @newSerial,
							is_available	= 'True'		-- MOS
					WHERE	comp_id			= @comp_id
					AND		is_id			= @lis_id
				--SELECT @newSerial
			END
			ELSE

				SET @return_value = @return_value - 1


			FETCH NEXT FROM curItemSerials INTO @lis_id

		END


	CLOSE		curItemSerials
	DEALLOCATE  curItemSerials



END
GO






