	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT,
	@bolIsOK					BIT



)
AS


---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@item_id_1					INT,
	@qty						DECIMAL(19,5),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT,
	@bolIsOK					BIT




SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,
	@item_id					=229,
	@item_id_1					=404,
	@qty						=666,

	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 666

*/
---------------------------------------------------------------------------------


set nocount on



BEGIN
	declare @return_value	INT

		BEGIN TRY

			INSERT INTO tbItemSerialsFromOtherERP
			(
				-- isfo_id -- this column value is auto-generated,
				isfo_serial,
				item_id,
