--------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spItemSerialsFromOtherERP_Process_Auto_Validate]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@isfo_serial				NVARCHAR(100),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT


)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@item_id_1					INT,
	@qty						DECIMAL(19,5),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bra_id						INT




SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,

	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 10,
	@bra_id4session				= 1

*/
---------------------------------------------------------------------------------


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


set nocount on

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''



	------Articulo -----------------------------------------------------------------------------------------------------------
	if	@item_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Artículo'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT ti.item_id
			               FROM		tbItem ti		WITH (NOLOCK)
							WHERE	ti.comp_id		= @comp_id		AND
									ti.item_id		= @item_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Artículo es incorrecto'
				END
		END
	-----------------------------------------------------------------------------------------------------------------------

	------serial-----------------------------------------------------------------------------------------------------------
	if	@isfo_serial	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Nº de Serie'
		END

	-----------------------------------------------------------------------------------------------------------------------

	-- si no viene nada del excel para estos campos le pondra 0 : @qty

	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO



----------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Date   : 30/12/16
-- Author : GA
-- Detail : Al finalizar el proceso de importacion se muestra en una grilla que registros fueron dados de alta y los que no.
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[spItemSerialsFromOtherERP_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SELECT
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)


	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO






-- Toma numeros de serie que se trajeron del sistema anterior
CREATE PROCEDURE [dbo].[spItemSerialsFromOtherERP_UpdateSerial]
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id     INT,
	@serial     VARCHAR(100)
)
AS

BEGIN

	SET NOCOUNT ON

-- ----------------------------------------------------------
-- Testing
-- ----------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@bra_id		INT,
			@soh_id     INT,
			@serial     VARCHAR(100)
	SELECT	@comp_id  = 1,
			@bra_id   = 1,
			@soh_id   = 8432,
			@serial   = '58'
	*/
-- ----------------------------------------------------------


	-- Si NO figura como numero de serie en el sistema GBP, lo busca en numeros importados.-
	IF NOT EXISTS(SELECT TOP 1 1 FROM tbItemSerials tis 	WITH (NOLOCK) WHERE tis.is_serial = @serial)
	BEGIN


		DECLARE @item_id AS INT
		DECLARE @intStor_ID AS INT

		--Con el serial, recupero el item.
		SELECT  @item_id	= item_id
			FROM    dbo.tbItemSerialsFromOtherERP	WITH (NOLOCK)
			WHERE 		comp_id	    = @comp_id
				AND 	isfo_serial = @serial
		--SELECT @item_id


		-- Busca el Deposito del Item   MOS
		SELECT Top 1
			@intStor_ID = sod.stor_id
			FROM tbsaleorderdetail sod		WITH (NOLOCK)
			WHERE	comp_id = @comp_id
				and	bra_id  = @bra_id
				and	soh_id  = @soh_id
				AND sod.stor_id IS NOT NULL



		IF NOT  @item_id  IS NULL
			BEGIN
				-- Verifico que exista en el pedido.
				if EXISTS (SELECT TOP 1 1
						   FROM tbsaleorderdetail		WITH (NOLOCK)
						   WHERE comp_id = @comp_id
							and	 bra_id  = @bra_id
							and	 soh_id  = @soh_id
							and	 item_id = @item_id )
					AND @intStor_ID IS NOT NULL

					BEGIN


						UPDATE      TOP (1) tbItemSerials

						SET         tbItemSerials.is_serial		= @serial,
									tbItemSerials.is_available	= 'True',
									tbItemSerials.stor_id		= @intStor_ID


						FROM	tbItemSerials							tis		WITH (NOLOCK)

								INNER JOIN tbItemSerialsFromOtherERP	tisfoe	WITH (NOLOCK)
								ON  tisfoe.comp_id	= tis.comp_id
								AND tisfoe.item_id	= tis.item_id

						WHERE	tis.comp_id					= @comp_id
						AND		tisfoe.isfo_serial			= @serial
						AND		isnull(tis.is_serial,'')	= ''
						AND		tis.is_available			= 'false'
						AND		NOT EXISTS (SELECT TOP 1  1 FROM tbItemSerials tis2	WITH (NOLOCK) WHERE tis2.comp_id = @comp_id
											AND tis2.is_serial = @serial)

					END

			END

		ELSE
		   RETURN
	END

ENd
GO







CREATE procedure [dbo].[spItemsImages_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@option				int,
		@item_desc			varchar(200),
		@option2			INT,
		@item_vendorCode	VARCHAR(200),
		@prli_id1			int,
		@prli_id2			int,
		@prli_id3			int,
		@prli_id4			int,
		@pres_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@bra_id				int,
		@curr_id			int,
		@byor_id			INT,
		@item_disabled		INT,
		@legends			INT,
		@orderby			INT,
		@stock				INT,
		@stor_id			INT,
		@withTaxes			INT,
		@itemclass			int,
		@guid				VARCHAR(50), -- cf de item
		@intBranch4Lang		int
)
as



BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- -------------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------------
/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			int,
			@option				int,
			@item_desc			varchar(200),

			@option2			INT,
			@item_vendorCode	VARCHAR(200),

			@prli_id1			int,
			@prli_id2			int,
			@prli_id3			int,
			@prli_id4			int,
			@pres_id			int,

			@cat_id				int,
			@subcat_id			int,

			@brand_id			int,
			@bra_id				int,
			@curr_id			int,
			@byor_id			int,
			@item_disabled		INT,
			@stock				INT,
			@legends			INT,
			@orderby			INT,
			@stor_id			INT,
			@withTaxes			INT,
			@itemclass			int,
			@guid				VARCHAR(50), -- cf de item
			@intBranch4Lang		int

	SELECT
			@comp_id			=1,
			@lang_id			=2,
			@page_id			=10017,
			@option				=-1,
			@item_desc			='',
			@option2			=-1,
			@item_vendorCode	='',
			@prli_id1			=1,
			@prli_id2			=-1,
			@prli_id3			=-1,
			@prli_id4			=-1,
			@pres_id			=-1,

			@cat_id				=-1,
			@subcat_id			=-1,

			@brand_id			=-1,
			@bra_id				=-1,
			@curr_id			=-1,
			@byor_id			=-1,
			@item_disabled		= 0,
			@stock				= -1,
			@legends			= 1,
			@orderby			= 1,
			@stor_id			= -1,
			@withTaxes			= 0,
			@itemclass		    = -1,
			@guid				= newid(),
			@intBranch4Lang		= 1

			DROP TABLE #tmp_ItemImages
*/
	-- -------------------------------------------------------------------------------------

	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------


	DECLARE @fun_id INT
	SET @fun_id = 1


	SELECT	I.[cat_id],
			C.cat_desc,
			C.cat_image,
			I.[subcat_id],
			SC.subcat_desc,
			SC.subcat_image,
			I.[bra_id],
			B.brand_desc,
			B.brand_image,
			I.item_code,
			I.item_desc,
			I.item_picture,



			CASE when @withTaxes = 1 THEN
				PLI1.prli_price + (pli1.prli_price * ttn.tax_percentage / 100)
			ELSE
				PLI1.prli_price
			END	[prli_price1],


--			PLI1.prli_price [prli_price9],
			CC1.curr_symbol [curr_desc1],

			CASE when @withTaxes = 1 THEN
				PLI2.prli_price + (pli2.prli_price * ttn.tax_percentage / 100)
			ELSE
				PLI2.prli_price
			END	[prli_price2],



--			PLI2.prli_price [prli_price2],
			CC2.curr_symbol [curr_desc2],

			CASE when @withTaxes = 1 THEN
				PLI3.prli_price + (PLI3.prli_price * ttn.tax_percentage / 100)
			ELSE
				PLI3.prli_price
			END	[prli_price3],

--			PLI3.prli_price [prli_price3],
			CC3.curr_symbol [curr_desc3],

			CASE when @withTaxes = 1 THEN
				PLI4.prli_price + (PLI4.prli_price * ttn.tax_percentage / 100)
			ELSE
				PLI4.prli_price
			END	[prli_price4],


--			PLI4.prli_price [prli_price4],
			CC4.curr_symbol [curr_desc4],

			--Aca agrego el TAX Asociado para cada item


			(SELECT TOP 1 ttn.tax_desc					--/*Parte 574
			 FROM tbItemTaxes						tit

				INNER JOIN tbTaxName				ttn
				ON	ttn.comp_id = tit.comp_id
				AND ttn.tax_id	= tit.tax_id

				INNER JOIN tbItem					ti
				ON	ti.comp_id = tit.comp_id
				AND ti.item_id = tit.item_id

			WHERE	tit.comp_id	= 1
			AND		ti.item_id		= I.item_id
			AND		ttn.tax_class	= 1)			[Item_Tax],			--Parte 574*/


			I.item_detail,
			i.item_vendorCode


		INTO #tmp_ItemImages

	FROM	dbo.tbItem								I

			INNER JOIN @tblComplexFilter_Items				tempITEM
			ON tempitem.item_id			= i.item_id

			LEFT JOIN [tbPresentation]				P
			ON	P.[comp_id]							=	I.[comp_id]
			AND P.[pres_id]							=	I.[pres_id]

			LEFT JOIN tbCategory					C
			ON	C.[comp_id]							= I.[comp_id]
			AND C.[cat_id]							= I.[cat_id]

			LEFT JOIN tbSubCategory					SC
			ON	SC.[comp_id]						= I.[comp_id]
			AND SC.[cat_id]							= I.[cat_id]
			AND SC.[subcat_id]						= I.[subcat_id]

			LEFT JOIN tbBrand						B
			ON	B.[comp_id]							= I.[comp_id]
			AND B.[brand_id]						= I.[brand_id]
			and B.[bra_id]							= I.[bra_id]

			LEFT JOIN	tbBranch					BR
			ON BR.[comp_id]							=	I.[comp_id]
			AND BR.[bra_id]							=	I.[bra_id]


			LEFT JOIN dbo.tbByOrder					BO
			ON	BO.[comp_id]						=	I.[comp_id]
			AND BO.[byor_id]						=	I.[byor_id]

			left JOIN [tbsysOptionsValues]			O
			ON	o.[optval_id]						= I.[item_liquidation]
			AND	o.[optval_class]					= 1
			and o.lang_id							= @lang_id

			Inner join tbPriceListItems				PLI1
			on	PLI1.[comp_id]						= I.[comp_id]
			and PLI1.[prli_id]						= @prli_id1
			and PLI1.item_id						= I.item_id

			Inner JOIN tbsysCurrency				CC1
			ON	CC1.[curr_id]						= PLI1.[curr_id]

			left join tbPriceListItems				PLI2
			on	PLI2.[comp_id]						= I.[comp_id]
			and PLI2.[prli_id]						= @prli_id2
			and PLI2.item_id						= I.item_id

			left JOIN tbsysCurrency					CC2
			ON	CC2.[curr_id]						= PLI2.[curr_id]

			left join tbPriceListItems				PLI3
			on	PLI3.[comp_id]						= I.[comp_id]
			and PLI3.[prli_id]						= @prli_id3
			and PLI3.item_id						= I.item_id

			left JOIN tbsysCurrency					CC3
			ON	CC3.[curr_id]						= PLI3.[curr_id]

			left join tbPriceListItems				PLI4
			on	PLI4.[comp_id]						= I.[comp_id]
			and PLI4.[prli_id]						= @prli_id4
			and PLI4.item_id						= I.item_id

			left JOIN tbsysCurrency					CC4
			ON	CC4.[curr_id]						= PLI4.[curr_id]



			--Ticket 219---------------------------------------------------

			INNER JOIN tbItemTaxes tit
			ON  tit.comp_id = I.comp_id
			AND tit.item_id = I.item_id

			INNER JOIN tbTaxName ttn
			ON  ttn.comp_id = tit.comp_id
			AND ttn.tax_id	= tit.tax_id

			INNER JOIN vwsysTaxClassIVA_Taxes vtcit
			ON vtcit.tax_class = ttn.tax_class


			---------------------------------------------------------------


			INNER JOIN vwItems_ParentStatus vwr
				ON		vwr.comp_id = i.comp_id
					AND vwr.item_id = i.item_id







			WHERE		I.[comp_id]		=	@comp_id
			AND			(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
			AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
			AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
			AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
			AND			(@bra_id		= -1 or I.[bra_id]		=	@bra_id)
			AND			(@curr_id		= -1 or I.[curr_id]		=	@curr_id)
			AND			(@byor_id		= -1 or I.[byor_id]		=	@byor_id)
			AND			CASE
							WHEN @stor_id = -1 THEN 1
							WHEN dbo.fnGetStock(@comp_id, @stor_id, i.item_id)> 0 THEN 1
							ELSE 0
						END = 1
						--(@stor_id		= -1 or dbo.fnGetStock(@comp_id, @stor_id, i.item_id)> 0 )
			AND			(@item_disabled = 0 AND isnull(i.item_disabled,'False') =	'False' OR		-- Habilitados
						 @item_disabled = 1 AND isnull(i.item_disabled,'False') =	'True'			-- des-Habilitados
					)
			and			(
							(@option	 = -1 ) or
							(@option	 = 0 and I.item_desc like @item_desc + '%') or
							(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
							(@option	 = 2 and I.item_desc = @item_desc ) or
							(@option	 = 3 and I.item_desc <> @item_desc ) or
							(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
						)

			and			(
							(@option2	 = -1 ) or
							(@option2	 = 0 and I.item_vendorCode like @item_vendorCode + '%') or
							(@option2	 = 1 and I.item_vendorCode like '%' + @item_vendorCode + '%') or
							(@option2	 = 2 and I.item_vendorCode = @item_vendorCode ) or
							(@option2	 = 3 and I.item_vendorCode <> @item_vendorCode ) or
							(@option2	 = 4 and I.item_vendorCode not like '%' + @item_vendorCode + '%')
			)
			AND
						CASE
							WHEN	@stock	= -1 THEN 1
							WHEN	@stock	= 1 AND dbo.fnGetAStock(@comp_id,@stor_id,i.item_id,888888888)  > 0 THEN 1
							WHEN @stock		= 2 AND dbo.fnGetAStock(@comp_id,@stor_id,i.item_id,888888888) <= 0 THEN 1
							ELSE 0
						END		= 1
						--(
						--	(@stock		 = -1)						 OR
						--	(@stock		 = 1 AND dbo.fnGetAStock(@comp_id,@stor_id,i.item_id,888888888)  > 0) OR
						--	(@stock		 = 2 AND dbo.fnGetAStock(@comp_id,@stor_id,i.item_id,888888888) <= 0)
						--)

			AND IsNull(I.item_disabledInPriceList,'False') = 'False'
			AND vtcit.tax_class = 1
			AND		(
							@itemclass = -1
						OR  (@itemclass = 1 AND vwr.[Master]	= 1)
						OR	(@itemclass = 2 AND vwr.Slave		= 1)
					)


	IF @orderby = 1
		BEGIN
			SELECT * FROM #tmp_ItemImages tmp
			ORDER BY tmp.cat_desc, tmp.item_desc
		END
	ELSE
		IF @orderby = 2
			BEGIN
				SELECT * FROM #tmp_ItemImages tmp
				ORDER BY tmp.subcat_desc
			END
		ELSE
			IF @orderby = 3
				BEGIN
					SELECT * FROM #tmp_ItemImages tmp
					ORDER BY tmp.brand_desc
				END
			ELSE
				IF @orderby = 4
					BEGIN
						SELECT * FROM #tmp_ItemImages tmp
						ORDER BY tmp.item_code ASC
					END
						IF @orderby = 5
							BEGIN
								SELECT * FROM #tmp_ItemImages tmp
								ORDER BY tmp.item_desc
							END







	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	select
	(select	P.prli_desc
	from	[tbPriceList]	P
	where	P.prli_id = @prli_id1) [Column1],
	(select	P.prli_desc
	from	[tbPriceList]	P
	where	P.prli_id = 	@prli_id2) [Column2],
	(select	P.prli_desc
	from	[tbPriceList]	P
	where	P.prli_id = 	@prli_id3) [Column3],
	(select	P.prli_desc
	from	[tbPriceList]	P
	where	P.prli_id = 	@prli_id4) [Column4],


	(SELECT tov.optval_desc
	 FROM tbsysOptionsValues tov
	 WHERE	tov.lang_id			= @lang_id
	 AND	tov.optval_class	= 91
     AND	tov.optval_id		= @legends) [Column5],

     (SELECT tov.optval_desc
      FROM tbsysOptionsValues tov
      WHERE tov.lang_id			= @lang_id
      AND	tov.optval_class	= 93
      AND	tov.optval_id		= @orderby) [Column6],

      (SELECT tra.sra_Annotation1
			  + ' - ' + tra.sra_Annotation2
			  + ' - ' + tra.sra_Annotation3
			  + ' - ' + tra.sra_Annotation4

       FROM tbReportsAnnotations tra
       WHERE	tra.comp_id = @comp_id
	   AND		tra.sra_id	= @legends) [Column7]









	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	SELECT
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 43
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params1],

			CASE @option WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tov.optval_desc + ISNULL(@item_desc,'')
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 2
					AND		tov.optval_id		= @option
					AND		tov.lang_id			= @lang_id)
			END																															[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 454
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			(SELECT tpl.prli_desc
				FROM dbo.tbPriceList tpl
				WHERE tpl.prli_id = @prli_id1)																							[params4],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 455
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params5],

				CASE @prli_id2 WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT tpl.prli_desc
						FROM dbo.tbPriceList tpl
						WHERE tpl.prli_id = @prli_id2)
				END																														[params6],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 456
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params7],

				CASE @prli_id3 WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT tpl.prli_desc
						FROM dbo.tbPriceList tpl
						WHERE tpl.prli_id = @prli_id3)
				END																														[params8],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 457
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params9],

				CASE @prli_id4 WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT tpl.prli_desc
						FROM dbo.tbPriceList tpl
						WHERE tpl.prli_id = @prli_id4)
				END																														[params10],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 36
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params11],

				CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cat_desc
						FROM	dbo.tbCategory tc
						WHERE	tc.cat_id = @cat_id)
				END																														[params12],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params13],

				CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
						FROM	dbo.tbSubCategory tsc
						WHERE	tsc.subcat_id = @subcat_id)
				END																														[params14],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 73
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],

				CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.brand_desc
						FROM	dbo.tbBrand tb
						WHERE	tb.brand_id = @brand_id)
				END																														[params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 371
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params17],

				CASE @pres_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tp.pres_desc
						FROM	dbo.tbPresentation tp
						WHERE	tp.pres_id = @pres_id)
				END																														[params18],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 28
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params19],

			CASE @bra_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.bra_desc
						FROM	dbo.tbBranch tb
						WHERE	tb.bra_id = @bra_id)
				END																														[params20],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 106
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params21],

			CASE @curr_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.curr_desc
						FROM	dbo.tbsysCurrency tc
						WHERE	tc.curr_id = @curr_id)
				END																														[params22],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 375
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params23],

			CASE @curr_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.curr_desc
						FROM	dbo.tbsysCurrency tc
						WHERE	tc.curr_id = @curr_id)
				END

	/*Arreglar del ultimo parametro la parte del ELSE porque no se que tiene que ir en el combo SEBASTIAN*/								[params24],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1392
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params25],

      		 CASE @item_disabled  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	TOP 1 tov.optval_desc
						FROM	  tbsysOptionsValues tov
						WHERE	  tov.optval_class = 111
						AND		  tov.optval_id = @item_disabled and tov.lang_id = @lang_id )
				END		                                                   [params26],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 111
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params27],

      		 CASE @stor_id  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 26)
				ELSE
					(SELECT	TOP 1 ts.stor_desc
						FROM	  tbStorage				ts
						WHERE	  ts.stor_id = @stor_id)
				END		                                                   [params28],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 241
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params29],

      		 CASE @withTaxes  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	TOP 1 tov.optval_desc
						FROM	  tbsysOptionsValues tov
						WHERE	  tov.optval_class = 1
						AND		  tov.lang_id = @lang_id
						AND		  tov.optval_id = @withTaxes)
				END		                                                   [params30]


END
GO






CREATE PROCEDURE [dbo].[spItemsImages_getReportWithoutGroupBy]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

		@option				int,
		@item_desc			varchar(200),
		@option2			INT,
		@item_vendorCode	VARCHAR(200),
		@prli_id1			int,
		@prli_id2			int,
		@prli_id3			int,
		@prli_id4			int,
		@pres_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@bra_id				int,
		@curr_id			int,
		@byor_id			INT,
		@item_disabled		INT,
		@legends			INT,
		@orderby			INT,
		@stock				INT,
		@stor_id			INT,
		@withTaxes			INT,
		@itemclass			int,
		@guid				VARCHAR(50), -- cf de item
		@intBranch4Lang		int


)
as


BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- -------------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------------
	/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			int,
			@option				int,
			@item_desc			varchar(200),

			@option2			INT,
			@item_vendorCode	VARCHAR(200),

			@prli_id1			int,
			@prli_id2			int,
			@prli_id3			int,
			@prli_id4			int,
			@pres_id			int,

			@cat_id				int,
			@subcat_id			int,

			@brand_id			int,
			@bra_id				int,
			@curr_id			int,
			@byor_id			int,
			@item_disabled		INT,
			@stock				INT,
			@legends			INT,
			@orderby			INT,
			@stor_id			INT,
			@withTaxes			INT

	SELECT
			@comp_id			=1,
			@lang_id			=2,
			@page_id			=10017,
			@option				=-1,
			@item_desc			='',
			@option2			=-1,
			@item_vendorCode	='',
			@prli_id1			=1,
			@prli_id2			=-1,
			@prli_id3			=-1,
			@prli_id4			=-1,
			@pres_id			=-1,

			@cat_id				=-1,
			@subcat_id			=-1,

			@brand_id			=-1,
			@bra_id				=-1,
			@curr_id			=-1,
			@byor_id			=-1,
			@item_disabled		= 0,
			@stock				= -1,
			@legends			= 1,
			@orderby			= 1,
			@stor_id			= -1,
			@withTaxes			= 0

			DROP TABLE #tmp_ItemImages
*/
	-- -------------------------------------------------------------------------------------



	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

	DECLARE @fun_id INT
	SET @fun_id = 1

	SET @page_id = 10017

	SELECT	I.[cat_id],
			C.cat_desc,
			C.cat_image,
			I.[subcat_id],
			SC.subcat_desc,
			SC.subcat_image,
			I.[bra_id],
			B.brand_desc,
			B.brand_image,
			I.item_code,
			I.item_desc,
			I.item_picture,

			CASE when @withTaxes = 1 THEN
				PLI1.prli_price + (pli1.prli_price * ttn.tax_percentage / 100)
			ELSE
				PLI1.prli_price
			END	[prli_price1],


--			PLI1.prli_price [prli_price9],
			CC1.curr_symbol [curr_desc1],

			CASE when @withTaxes = 1 THEN
				PLI2.prli_price + (pli2.prli_price * ttn.tax_percentage / 100)
			ELSE
				PLI2.prli_price
			END	[prli_price2],



--			PLI2.prli_price [prli_price2],
			CC2.curr_symbol [curr_desc2],

			CASE when @withTaxes = 1 THEN
				PLI3.prli_price + (PLI3.prli_price * ttn.tax_percentage / 100)
			ELSE
				PLI3.prli_price
			END	[prli_price3],

--			PLI3.prli_price [prli_price3],
			CC3.curr_symbol [curr_desc3],

			CASE when @withTaxes = 1 THEN
				PLI4.prli_price + (PLI4.prli_price * ttn.tax_percentage / 100)
			ELSE
				PLI4.prli_price
			END	[prli_price4],


--			PLI4.prli_price [prli_price4],
			CC4.curr_symbol [curr_desc4],

			--Aca agrego el TAX Asociado para cada item


			(SELECT TOP 1 ttn.tax_desc					--/*Parte 574
			 FROM tbItemTaxes						tit

				INNER JOIN tbTaxName				ttn
				ON	ttn.tax_id = tit.tax_id
				AND ttn.comp_id = tit.comp_id

				INNER JOIN tbItem					ti
				ON	ti.comp_id = tit.comp_id
				AND ti.item_id = tit.item_id

			WHERE	tit.comp_id	= 1
			AND		ti.item_id		= I.item_id
			AND		ttn.tax_class	= 1)			[Item_Tax],			--Parte 574*/


			I.item_detail,
			i.item_vendorCode


		INTO #tmp_ItemImages

	FROM	dbo.tbItem								I

			INNER JOIN @tblComplexFilter_Items				tempITEM
			ON tempitem.item_id			= i.item_id


			LEFT JOIN [tbPresentation]				P
			ON	P.[comp_id]							=	I.[comp_id]
			AND P.[pres_id]							=	I.[pres_id]

			LEFT JOIN tbCategory					C
			ON	C.[comp_id]							= I.[comp_id]
			AND C.[cat_id]							= I.[cat_id]

			LEFT JOIN tbSubCategory					SC
			ON	SC.[comp_id]						= I.[comp_id]
			AND SC.[cat_id]							= I.[cat_id]
			AND SC.[subcat_id]						= I.[subcat_id]

			LEFT JOIN tbBrand						B
			ON	B.[comp_id]							= I.[comp_id]
			AND B.[brand_id]						= I.[brand_id]
			and B.[bra_id]							= I.[bra_id]

			LEFT JOIN	tbBranch					BR
			ON BR.[comp_id]							=	I.[comp_id]
			AND BR.[bra_id]							=	I.[bra_id]


			LEFT JOIN dbo.tbByOrder					BO
			ON	BO.[comp_id]						=	I.[comp_id]
			AND BO.[byor_id]						=	I.[byor_id]

			left JOIN [tbsysOptionsValues]			O
			ON	o.[optval_id]						= I.[item_liquidation]
			AND	o.[optval_class]					= 1
			and o.lang_id							= @lang_id

			Inner join tbPriceListItems				PLI1
			on	PLI1.[comp_id]						= I.[comp_id]
			and PLI1.[prli_id]						= @prli_id1
			and PLI1.item_id						= I.item_id

			Inner JOIN tbsysCurrency				CC1
			ON	CC1.[curr_id]						= PLI1.[curr_id]

			left join tbPriceListItems				PLI2
			on	PLI2.[comp_id]						= I.[comp_id]
			and PLI2.[prli_id]						= @prli_id2
			and PLI2.item_id						= I.item_id

			left JOIN tbsysCurrency					CC2
			ON	CC2.[curr_id]						= PLI2.[curr_id]

			left join tbPriceListItems				PLI3
			on	PLI3.[comp_id]						= I.[comp_id]
			and PLI3.[prli_id]						= @prli_id3
			and PLI3.item_id						= I.item_id

			left JOIN tbsysCurrency					CC3
			ON	CC3.[curr_id]						= PLI3.[curr_id]

			left join tbPriceListItems				PLI4
			on	PLI4.[comp_id]						= I.[comp_id]
			and PLI4.[prli_id]						= @prli_id4
			and PLI4.item_id						= I.item_id

			left JOIN tbsysCurrency					CC4
			ON	CC4.[curr_id]						= PLI4.[curr_id]

			--Ticket 219---------------------------------------------------

			INNER JOIN tbItemTaxes tit
			ON  tit.comp_id = I.comp_id
			AND tit.item_id = I.item_id

			INNER JOIN tbTaxName ttn
			ON  ttn.comp_id = tit.comp_id
			AND ttn.tax_id	= tit.tax_id

			INNER JOIN vwsysTaxClassIVA_Taxes vtcit
			ON vtcit.tax_class = ttn.tax_class


			---------------------------------------------------------------

			INNER JOIN vwItems_ParentStatus vwr
				ON		vwr.comp_id = i.comp_id
					AND vwr.item_id = i.item_id


			WHERE		I.[comp_id]		=	@comp_id
			AND			(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
			AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
			AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
			AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
			AND			(@bra_id		= -1 or I.[bra_id]		=	@bra_id)
			AND			(@curr_id		= -1 or I.[curr_id]		=	@curr_id)
			AND			(@byor_id		= -1 or I.[byor_id]		=	@byor_id)
			AND			CASE
							WHEN @stor_id = -1 THEN 1
							WHEN dbo.fnGetStock(@comp_id, @stor_id, i.item_id)> 0 THEN 1
							ELSE 0
						END = 1
						--(@stor_id		= -1 or dbo.fnGetStock(@comp_id, @stor_id, i.item_id)> 0 )
			--AND			(@stor_id		= -1 or dbo.fnGetStock(@comp_id, @stor_id, i.item_id)> 0 )
			AND			(@item_disabled = 0 AND isnull(i.item_disabled,'False') =	'False' OR		-- Habilitados
						 @item_disabled = 1 AND isnull(i.item_disabled,'False') =	'True'			-- des-Habilitados
					)
			and			(
							(@option	 = -1 ) or
							(@option	 = 0 and I.item_desc like @item_desc + '%') or
							(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
							(@option	 = 2 and I.item_desc = @item_desc ) or
							(@option	 = 3 and I.item_desc <> @item_desc ) or
							(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
						)

			and			(
							(@option2	 = -1 ) or
							(@option2	 = 0 and I.item_vendorCode like @item_vendorCode + '%') or
							(@option2	 = 1 and I.item_vendorCode like '%' + @item_vendorCode + '%') or
							(@option2	 = 2 and I.item_vendorCode = @item_vendorCode ) or
							(@option2	 = 3 and I.item_vendorCode <> @item_vendorCode ) or
							(@option2	 = 4 and I.item_vendorCode not like '%' + @item_vendorCode + '%')
						)
			AND

						CASE
							WHEN	@stock	= -1 THEN 1
							WHEN	@stock	= 1 AND dbo.fnGetAStock(@comp_id,@stor_id,i.item_id,888888888)  > 0 THEN 1
							WHEN @stock		= 2 AND dbo.fnGetAStock(@comp_id,@stor_id,i.item_id,888888888) <= 0 THEN 1
							ELSE 0
						END		= 1
						--(
						--	(@stock		 = -1)						 OR
						--	(@stock		 = 1 AND dbo.fnGetAStock(@comp_id,@stor_id,i.item_id,888888888)  > 0) OR
						--	(@stock		 = 2 AND dbo.fnGetAStock(@comp_id,@stor_id,i.item_id,888888888) <= 0)
						--)

			AND IsNull(I.item_disabledInPriceList,'False') = 'False'
			AND vtcit.tax_class = 1
			AND		(
							@itemclass = -1
						OR  (@itemclass = 1 AND vwr.[Master]	= 1)
						OR	(@itemclass = 2 AND vwr.Slave		= 1)
					)

	SELECT * FROM #tmp_ItemImages tmp
	ORDER BY tmp.item_desc ASC


--	IF @orderby = 1
--		BEGIN
--			SELECT * FROM #tmp_ItemImages tmp
--			ORDER BY tmp.cat_desc, tmp.item_desc
--		END
--	ELSE
--		IF @orderby = 2
--			BEGIN
--				SELECT * FROM #tmp_ItemImages tmp
--				ORDER BY tmp.subcat_desc
--			END
--		ELSE
--			IF @orderby = 3
--				BEGIN
--					SELECT * FROM #tmp_ItemImages tmp
--					ORDER BY tmp.brand_desc
--				END
--			ELSE
--				IF @orderby = 4
--					BEGIN
--						SELECT * FROM #tmp_ItemImages tmp
--						ORDER BY tmp.item_code ASC
--					END
--						IF @orderby = 5
--							BEGIN
--								SELECT * FROM #tmp_ItemImages tmp
--								ORDER BY tmp.item_desc
--							END







	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	select
	(select	P.prli_desc
	from	[tbPriceList]	P
	where	P.prli_id = @prli_id1) [Column1],
	(select	P.prli_desc
	from	[tbPriceList]	P
	where	P.prli_id = 	@prli_id2) [Column2],
	(select	P.prli_desc
	from	[tbPriceList]	P
	where	P.prli_id = 	@prli_id3) [Column3],
	(select	P.prli_desc
	from	[tbPriceList]	P
	where	P.prli_id = 	@prli_id4) [Column4],


	(SELECT tov.optval_desc
	 FROM tbsysOptionsValues tov
	 WHERE	tov.lang_id			= @lang_id
	 AND	tov.optval_class	= 91
     AND	tov.optval_id		= @legends) [Column5],

     (SELECT tov.optval_desc
      FROM tbsysOptionsValues tov
      WHERE tov.lang_id			= @lang_id
      AND	tov.optval_class	= 93
      AND	tov.optval_id		= @orderby) [Column6],

      (SELECT tra.sra_Annotation1
			  + ' - ' + tra.sra_Annotation2
			  + ' - ' + tra.sra_Annotation3
			  + ' - ' + tra.sra_Annotation4

       FROM tbReportsAnnotations tra
       WHERE	tra.comp_id = @comp_id
	   AND		tra.sra_id	= @legends) [Column7]









	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	SELECT
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 43
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params1],

			CASE @option WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tov.optval_desc + ISNULL(@item_desc,'')
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 2
					AND		tov.optval_id		= @option
					AND		tov.lang_id			= @lang_id)
			END																															[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 454
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			(SELECT tpl.prli_desc
				FROM dbo.tbPriceList tpl
				WHERE tpl.prli_id = @prli_id1)																							[params4],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 455
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params5],

				CASE @prli_id2 WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT tpl.prli_desc
						FROM dbo.tbPriceList tpl
						WHERE tpl.prli_id = @prli_id2)
				END																														[params6],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 456
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params7],

				CASE @prli_id3 WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT tpl.prli_desc
						FROM dbo.tbPriceList tpl
						WHERE tpl.prli_id = @prli_id3)
				END																														[params8],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 457
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params9],

				CASE @prli_id4 WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT tpl.prli_desc
						FROM dbo.tbPriceList tpl
						WHERE tpl.prli_id = @prli_id4)
				END																														[params10],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 36
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params11],

				CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cat_desc
						FROM	dbo.tbCategory tc
						WHERE	tc.cat_id = @cat_id)
				END																														[params12],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params13],

				CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
						FROM	dbo.tbSubCategory tsc
						WHERE	tsc.subcat_id = @subcat_id)
				END																														[params14],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 73
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],

				CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.brand_desc
						FROM	dbo.tbBrand tb
						WHERE	tb.brand_id = @brand_id)
				END																														[params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 371
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params17],

				CASE @pres_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tp.pres_desc
						FROM	dbo.tbPresentation tp
						WHERE	tp.pres_id = @pres_id)
				END																														[params18],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 28
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params19],

			CASE @bra_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.bra_desc
						FROM	dbo.tbBranch tb
						WHERE	tb.bra_id = @bra_id)
				END																														[params20],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 106
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params21],

			CASE @curr_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.curr_desc
						FROM	dbo.tbsysCurrency tc
						WHERE	tc.curr_id = @curr_id)
				END																														[params22],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 375
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params23],

			CASE @curr_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.curr_desc
						FROM	dbo.tbsysCurrency tc
						WHERE	tc.curr_id = @curr_id)
				END

	/*Arreglar del ultimo parametro la parte del ELSE porque no se que tiene que ir en el combo SEBASTIAN*/								[params24],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1392
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params25],

      		 CASE @item_disabled  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	TOP 1 tov.optval_desc
						FROM	  tbsysOptionsValues tov
						WHERE	  tov.optval_class = 111
						AND		  tov.optval_id = @item_disabled and tov.lang_id = @lang_id )
				END		                               [params26],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 111
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params27],

      		 CASE @stor_id  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 26)
				ELSE
					(SELECT	TOP 1 ts.stor_desc
						FROM	  tbStorage				ts
						WHERE	  ts.stor_id = @stor_id)
				END		                                                   [params28],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 241
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params29],

      		 CASE @withTaxes  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	TOP 1 tov.optval_desc
						FROM	  tbsysOptionsValues tov
						WHERE	  tov.optval_class = 1
						AND		  tov.lang_id = @lang_id
						AND		  tov.optval_id = @withTaxes)
				END		                                                   [params30]


END
GO





CREATE PROCEDURE spItemSizeColor_deleteData
(
	@comp_id				INT,
	@item_id				INT,
	@return_value			INT OUTPUT,
	@ret_ErrorCode			INT OUTPUT,
	@ret_ErrorDescription	VARCHAR(200) OUTPUT
)
AS SET NOCOUNT ON

/*
DECLARE
	@comp_id	INT,
	@item_id	INT
SELECT
	@comp_id	= 1,
	@item_id	= 231
*/

	SET @return_value			= 0
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''

BEGIN TRY

	DELETE FROM tbItemSizeColorRelation
	WHERE comp_id = @comp_id
	AND item_id = @item_id

END TRY
BEGIN CATCH
	Set @ret_ErrorCode			= -1
	Set	@ret_ErrorDescription	= '1 - ' + ERROR_MESSAGE()
	RETURN
END CATCH
GO








CREATE PROCEDURE [dbo].[spItemSizeColor_GetData]
(
	@comp_id			INT,
	@item_id			INT,
	@filter				BIT,
	@prli_id			INT,
	@stor_id			INT,
	@horizontal_page	INT,
	@vertical_page		INT,
	@Sizec_id			INT,
	@Colors				VARCHAR(8000),
	@bra_id				AS INT,
	@prof_id			AS INT,
	@user_id			AS INT
)
AS





BEGIN

	SET NOCOUNT ON


	-- La verda nunca crei que pueiese haber gente tan ENFERRRMAAA e HIJA DE PUTAAAA   MOH sos de terrorrrrrrrrrr

	-- -------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@item_id	INT,
		@filter		BIT,
		@prli_id	INT,
		@stor_id	INT

		,@horizontal_page INT, @vertical_page int

	SELECT
		@comp_id	= 1,
		@item_id	= 497,
		@filter		= 'True',
		@prli_id	= -1,
		@stor_id	= 3

		,@horizontal_page =1, @vertical_page =0


	--DECLARE
	--@horizontal_page INT, @vertical_page int
	--SELECT
	--@horizontal_page =2, @vertical_page =1
	*/
	-- -------------------------------------------------------


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

		DECLARE @paging INT
		SET @paging = 12


		DECLARE @tmpSize  AS TABLE(size_id INT PRIMARY KEY)
		DECLARE @tmpColor AS TABLE(color_id INT PRIMARY KEY)
		IF @filter = 'False'  -- si viene de wfmItemSizeColor
			BEGIN

				IF @Sizec_id = -1
					BEGIN
						INSERT INTO @tmpSize( size_id)  SELECT ts.Size_id
															FROM tbSize ts
															WHERE ts.comp_id = @comp_id
					END
				ELSE
					BEGIN
						INSERT INTO @tmpSize( size_id)  SELECT tscr.Size_id
															FROM tbSizeCurveRelation tscr
															WHERE	tscr.comp_id	= @comp_id AND
																	tscr.Sizec_id	= @Sizec_id
					END

				IF @Colors = '-1'
					BEGIN
						INSERT INTO @tmpColor(color_id) SELECT tc.color_id
															FROM tbColor tc
															WHERE tc.comp_id = @comp_id
					END
				ELSE
				    BEGIN
						INSERT INTO @tmpColor(color_id) SELECT  convert(int,fst.items)
						                                    FROM dbo.fnSplitTable(@Colors,';') fst
					END
			END
		ELSE
			BEGIN

				-- Poner en las temporales los colores y talles que esten en la relacion del articulo solicitado
				INSERT INTO @tmpSize(size_id)
					SELECT distinct tiscr.size_id
						FROM tbItemSizeColorRelation tiscr
						WHERE	tiscr.comp_id = @comp_id AND
								tiscr.item_id = @item_id AND
								tiscr.iscr_Enabled = 'True'

				INSERT INTO @tmpColor(color_id)
					SELECT distinct tiscr.color_id
						FROM tbItemSizeColorRelation tiscr
						WHERE	tiscr.comp_id = @comp_id AND
								tiscr.item_id = @item_id AND
								tiscr.iscr_Enabled = 'True'

			END






		DECLARE @horizotal_begin INT, @horizontal_end INT,@vertical_begin INT, @vertical_end INT

		SELECT	@horizotal_begin	= (@paging * @horizontal_page + 1),
				@horizontal_end		= (@paging * (@horizontal_page + 1)),
				@vertical_begin		= (@paging * @vertical_page + 1),
				@vertical_end		= (@paging * (@vertical_page + 1))
		--SELECT	@horizotal_begin,@horizontal_end,@vertical_begin,@vertical_end




		IF @filter = 'true' --desde wfmsaleorder
			BEGIN

				--datatable(0)
				SELECT
					tc.color_id,
					tc.color_desc

					FROM tbColor tc
					INNER JOIN @tmpColor tmp
						ON tmp.color_id = tc.color_id
					WHERE	tc.comp_id = @comp_id
					--AND     ((@filter = 'true' and tc.color_id IN (SELECT color_id FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = @comp_id AND tiscr.item_id = @item_id) OR @filter='false'))
					AND		NOT tc.color_code IS NULL
					ORDER BY tc.color_desc

				--datatable(1)
				SELECT
					ts.size_id,
					ts.Size_desc

					FROM tbSize ts
					INNER JOIN @tmpSize tmp
						ON tmp.size_id = ts.Size_id

					WHERE	ts.comp_id = @comp_id
					--AND		((@filter = 'true' and ts.Size_id IN (SELECT size_id FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = @comp_id AND tiscr.item_id = @item_id) OR @filter='false'))
					AND		NOT ts.Size_code IS NULL
					ORDER BY ts.Size_order

			END
		ELSE				--desde wfmitemsizecolor
			BEGIN

				--datatable(0)
				;WITH resultado_total AS
				(
					SELECT	tc.color_id,	tc.color_desc  ,ROW_NUMBER()
						OVER (ORDER BY tc.color_desc ASC ) AS RowNumber
					FROM	tbColor tc
					INNER JOIN @tmpColor tmp
					ON tmp.color_id = tc.color_id
					WHERE	tc.comp_id = @comp_id
					--AND     ((@filter = 'true' and tc.color_id IN (SELECT color_id FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = @comp_id AND tiscr.item_id = @item_id) OR @filter='false'))
					AND		NOT tc.color_code IS NULL
				)
				SELECT [color_id],[color_desc] FROM resultado_total
				 WHERE RowNumber BETWEEN @vertical_begin AND @vertical_end


				--datatable(1)
				;WITH resultado_total AS
				(
					SELECT	ts.size_id,	ts.Size_desc   ,ROW_NUMBER()
						OVER (ORDER BY ts.size_desc ASC ) AS RowNumber
					FROM	tbSize ts
					INNER JOIN @tmpSize tmp
					ON tmp.size_id = ts.Size_id
					WHERE	ts.comp_id = @comp_id
					--AND		((@filter = 'true' and ts.Size_id IN (SELECT size_id FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = @comp_id AND tiscr.item_id = @item_id) OR @filter='false'))
					AND		NOT ts.Size_code IS NULL
				)
				SELECT [size_id],[size_desc] FROM resultado_total
				 WHERE RowNumber BETWEEN @horizotal_begin AND @horizontal_end

			END


		-- ------------------------------------------------
		--	Datatable(2)
		-- ------------------------------------------------
		SELECT	tiscr.color_id,
				tiscr.size_id,
				tiscr.iscr_Enabled,
				tiscr.iscr_Coeficient4Price,
				convert(decimal(15,2),dbo.fnGetAStock(tiscr.comp_id,@stor_id,tiscr.item_id_child,999999999))	[Stock],
				convert(decimal(15,2),ISNULL(tis.itst_cant,0))											    [PhisicalStock],
				tiscr.item_id_child,
				convert(decimal(15,2),ti.item_cantMin)														[item_cantMin],
				tiscr.item_id,
				ti.item_code,
				dbo.fnGetAStock2StringOfMyItemSelectionStorages(@comp_id, @bra_id, @prof_id, @user_id, @stor_id, tiscr.item_id_child)
																											[StockOfItemSelStorages]

		FROM	tbItemSizeColorRelation tiscr

				INNER JOIN tbItem ti
					ON	ti.comp_id	= @comp_id		AND
						ti.item_id	= tiscr.item_id_child

				LEFT JOIN tbItemStorage tis
					ON	tis.comp_id	= @comp_id	    AND
						tis.stor_id = @stor_id		AND
						tis.item_id = tiscr.item_id_child

		WHERE	tiscr.comp_id = @comp_id	AND
				tiscr.item_id = @item_id
				AND
				(
				CASE
					WHEN @filter = 'False' THEN 1
					WHEN @filter = 'true' AND tiscr.iscr_Enabled = 'True' AND tiscr.iscr_Coeficient4Price <> 0 THEN 1
					ELSE 0
				END = 1
				)
		-- ------------------------------------------------




		-- ------------------------------------------------
		/*Traigo los colores y los talles que no tienen CODIGO*/
		--datatable(3)
		-- ------------------------------------------------
		SELECT
			(SELECT COUNT(*)	FROM tbColor	tc
								INNER JOIN @tmpColor tmp
									ON tmp.color_id = tc.color_id
								WHERE tc.color_code IS NULL)		[Color],
			(SELECT COUNT(*)	FROM tbSize		ts
								INNER JOIN @tmpSize tmp
									ON tmp.size_id = ts.Size_id
								WHERE ts.Size_code IS NULL)		[Size]
		-- ------------------------------------------------


		-- ------------------------------------------------
		-- Datatables 4 y 5
		-- ------------------------------------------------
		IF @filter = 'True' --Cuando se llama desde SaleOrder
			BEGIN

				--datatable(4)
				SELECT
					tpli.prli_price,
					tpli.curr_id

				FROM tbPriceListItems tpli

					INNER JOIN tbItem ti
					ON ti.comp_id = tpli.comp_id
					AND ti.item_id = tpli.item_id

				WHERE tpli.comp_id	= @comp_id
				AND tpli.item_id	= @item_id
				AND tpli.prli_id	=  @prli_id


				--datatable(5)
				SELECT	ISNULL((SELECT	tis2.itst_cant
								FROM	tbItemStorage tis2
								WHERE	tis2.comp_id = @comp_id
								AND		tis2.item_id = @item_id
								AND		tis2.stor_id = @stor_id),0)	[itst_cant]--,
				--(SELECT SUM(ISNULL(tis.itst_cant,0)) FROM tbItemStorage tis	 WHERE tis.comp_id  = @comp_id AND tis.item_id  = @item_id)								[itst_cant_total]

			END

		ELSE		--desde wfmitemsizecolor

			BEGIN

				--traer la cantidad máxima de paginas horizontales y verticales
				--datatable(4)
				SELECT
					--colores: cantidad de páginas verticales
					(SELECT	CEILING((1.00 * COUNT(*)) / @paging)

						FROM	tbColor tc
						INNER JOIN @tmpColor tmp
						ON tmp.color_id = tc.color_id
						WHERE	tc.comp_id = @comp_id
						--AND     ((@filter = 'true' and tc.color_id IN (SELECT color_id FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = @comp_id AND tiscr.item_id = @item_id) OR @filter='false'))
						AND		NOT tc.color_code IS NULL)   [vertical_qty_pages],

					--talles:cantidad de paginas horizontales
					(SELECT	CEILING((1.00 * COUNT(*)) / @paging)

						FROM	tbSize ts
						INNER JOIN @tmpSize tmp
						ON tmp.size_id = ts.Size_id
						WHERE	ts.comp_id = @comp_id
						--AND		((@filter = 'true' and ts.Size_id IN (SELECT size_id FROM tbItemSizeColorRelation tiscr WHERE tiscr.comp_id = @comp_id AND tiscr.item_id = @item_id) OR @filter='false'))
						AND		NOT ts.Size_code IS NULL)	[horizontal_qty_pages]


			END

		-- ------------------------------------------------

END
GO


CREATE PROCEDURE [dbo].[spItemSizeColor_insertData]
(
	@comp_id				INT,
	@item_id				INT,
	@color_id				INT,
	@size_id				INT,
	@iscr_Coeficient4Price	DECIMAL(19,6),
	@iscr_Enabled			BIT,
	@return_value			INT OUTPUT,
	@ret_ErrorCode			INT OUTPUT,
	@ret_ErrorDescription	VARCHAR(500) OUTPUT
)
AS

BEGIN
	SET NOCOUNT ON


	-- -------------------------------------------------------------
	-- Test
	-- -------------------------------------------------------------
	/*
	DECLARE
		@comp_id				INT,
		@item_id				INT,
		@color_id				INT,
		@size_id				INT,
		@iscr_Coeficient4Price	DECIMAL(19,6),
		@iscr_Enabled			BIT,
		@return_value			INT,
		@ret_ErrorCode			INT,
		@ret_ErrorDescription	VARCHAR(500)

	SELECT
		@comp_id				= 1,
		@item_id				= 16,
		@color_id				= 4,
		@size_id				= 44,
		@iscr_Coeficient4Price	= 1,
		@iscr_Enabled			= 'True',
		@return_value			= 0,
		@ret_ErrorCode			= 0,
		@ret_ErrorDescription	= ''
	*/
	-- -------------------------------------------------------------


	-- Obtiene si ya esta creada esa relacion de padre e hijo de ese talle y color
	-- como lo quieren los ^%$^% de AU
	DECLARE @intItem_id_Child AS INT
	SET		@intItem_id_Child	= NULL
	SELECT	@intItem_id_Child	= tiscr.item_id_child
		FROM tbItemSizeColorRelation tiscr		WITH (NOLOCK)
		WHERE	 tiscr.comp_id	= @comp_id
		   AND	 tiscr.item_id	= @item_id
		   AND	 tiscr.color_id = @color_id
		   AND   tiscr.size_id	= @size_id


	-- -------------------------------------------------------------
	-- Si NO existe la relación y esta en Falso el habilitado, no hace nada
	-- -------------------------------------------------------------
	IF @intItem_id_Child IS NULL
		AND
	   @iscr_Enabled = 'False'
		BEGIN
			RETURN
		END
	-- -------------------------------------------------------------




	SET @return_value			= 0
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''


	DECLARE
		@color_code		NCHAR(5),
		@size_code		NCHAR(5),
		@strItemCode AS NVARCHAR(50),
		@strItemDesc AS NVARCHAR(100),
		@strColorDesc AS NVARCHAR(50),
		@strSizeDesc AS NVARCHAR(50)



	BEGIN TRY

		SELECT
			@color_code			= tc.color_code,
			@strColorDesc		= dbo.fnStrAllTrim( IsNull(tc.color_desc,''))
			FROM tbColor tc					WITH (NOLOCK)
			WHERE	tc.comp_id	= @comp_id
			AND		tc.color_id	= @color_id

		SELECT
			@size_code			= ts.size_code,
			@strSizeDesc		= dbo.fnStrAllTrim( IsNull(ts.Size_desc,''))
			FROM tbSize ts					WITH (NOLOCK)
			WHERE	ts.comp_id	= @comp_id
			AND		ts.size_id	= @size_id


		declare	@item_code nvarchar(50)
		select	@item_code		= ti.item_code,
				@strItemDesc	= IsNull(ti.item_desc,'item_desc->>NULL')
			from	tbItem	ti				WITH (NOLOCK)
			where	ti.comp_id = @comp_id
			and		ti.item_id = @item_id

		SET @strItemCode = LTRIM(RTRIM(@item_code))				+ '-' +
						   LTRIM(RTRIM(ISNULL(@color_code,'')))	+ '-' +
						   LTRIM(RTRIM(ISNULL(@size_code ,'')))

		SET @strItemDesc = @strItemDesc + ' ' + LTRIM(RTRIM(@strColorDesc)) + ' ' + LTRIM(RTRIM(@strSizeDesc))



		--DECLARE @item_id_child	INT


		-- verificamos si el artículo hijo que vamos a procesar ya existe, verificándolo por medio del item_code que es índice unique
		-- si no existe se da de alta, si existe, significa que la relación ya se había dado de alta y en algún momento se eliminó la relación
		-- en ese caso no se da de alta el artículo y sólo se recupera el item_id
		--IF NOT EXISTS	(	SELECT	1
		--						FROM	tbItem ti	WITH (NOLOCK)
