					'True'

				FROM	tbItem ti		WITH (NOLOCK)
				WHERE	ti.comp_id = @comp_id
				AND		ti.item_id = @item_id

				-- Se lo obtiene como corresponde HDP!
				SELECT	@intItem_id_Child	=	ti.item_id
					FROM	tbItem ti	WITH (NOLOCK)
					WHERE	ti.comp_id		=	@comp_id
					AND		ti.item_code	=	@strItemCode

			END
		ELSE
			-- Si está creado el articulo del TALLE y COLOR . . .
			BEGIN

				--SELECT	@item_id_child	=	ti.item_id
				--	FROM	tbItem ti	WITH (NOLOCK)
				--	WHERE	ti.comp_id		=	@comp_id
				--	AND		ti.item_code	=	@strItemCode

				UPDATE TBITEM		WITH (ROWLOCK)
					SET item_desc		= @strItemDesc,
						item_lastUpdate = GETDATE()
					WHERE	comp_id		= @comp_id									AND
							item_id		= @intItem_id_Child

			END





		-- ---------------------------------------------------------
		-- Actualiza tbItemSizeColorRelation
		-- ---------------------------------------------------------
		IF NOT EXISTS (	SELECT TOP 1  1
							FROM tbItemSizeColorRelation tiscr		--WITH (NOLOCK)
							WHERE	 tiscr.comp_id	= @comp_id
							   AND	 tiscr.item_id	= @item_id
							   AND	 tiscr.color_id = @color_id
							   AND   tiscr.size_id	= @size_id)
			BEGIN

				IF @intItem_id_Child IS NOT NULL
					BEGIN

						INSERT INTO tbItemSizeColorRelation		WITH (ROWLOCK)
							(
								comp_id,
								item_id,
								color_id,
								size_id,
								iscr_Coeficient4Price,
								iscr_Enabled,
								item_id_child
							)
						VALUES
							(
								@comp_id,
								@item_id,
								@color_id,
								@size_id,
								@iscr_Coeficient4Price,
								@iscr_Enabled,
								@intItem_id_Child
							)

					END


			END
		ELSE
			BEGIN

				UPDATE tbItemSizeColorRelation		WITH (ROWLOCK)
					SET
						iscr_Coeficient4Price	= @iscr_Coeficient4Price,
						iscr_Enabled			= @iscr_Enabled,
						item_id_child			= @intItem_id_Child

					WHERE	comp_id		= @comp_id
					AND		item_id		= @item_id
					AND		color_id	= @color_id
					AND		size_id		= @size_id


			END
		-- ---------------------------------------------------------



	DECLARE @intRowCount	AS INT = @@ROWCOUNT
	DECLARE @intCounter		AS INT  = 1

	-- ---------------------------------------------------------------
	-- Actualiza el PRECIO del padre para que se disparen las
	-- actualizaciones de los hijos
	-- Si hay Reglas no hace falta pero si no las hay si.-
	-- ---------------------------------------------------------------
	BEGIN TRY

		DECLARE		@tblPriceLIst
			TABLE(	intCounter	INT IDENTITY(1,1),
					prli_id	INT
	     			)

		INSERT INTO @tblPriceLIst(prli_id)
		SELECT DISTINCT	 tpli.prli_id
		FROM tbPriceListItems tpli	WITH (NOLOCK)
			WHERE	tpli.comp_id = @comp_id AND
					tpli.item_id = @item_id

		SET  @intRowCount		 = @@ROWCOUNT
		SET  @intCounter		 = 1
		WHILE @intCounter <= @intRowCount
			BEGIN

				-- De a uno x vez para que se disparen los triggers de actualizacion si es que hace falta ! ! !
				UPDATE tbPriceListItems		WITH (ROWLOCK)
					SET prli_price = prli_price
					FROM tbPriceListItems								ticl
					INNER JOIN @tblPriceLIst							tmp
						ON	tmp.intCounter	= @intCounter		AND
							tmp.prli_id		= ticl.prli_id
					WHERE	ticl.comp_id	= @comp_id			AND
							ticl.item_id	= @item_id

				SET @intCounter = @intCounter + 1

			END

	END TRY
	BEGIN CATCH
	END CATCH
	-- ---------------------------------------------------------------



	-- ---------------------------------------------------------------
	-- Actualiza el Costo del padre para que se disparen las
	-- actualizaciones de los hijos
	-- ---------------------------------------------------------------
	BEGIN TRY

		DECLARE		@tblCostLIst
			TABLE(	intCounter	INT IDENTITY(1,1),
					coslis_id	INT
	     			)

		INSERT INTO @tblCostLIst(coslis_id)
		SELECT DISTINCT	 ticl.coslis_id
			FROM tbItemCostList ticl	WITH (NOLOCK)
			WHERE	ticl.comp_id = @comp_id AND
					ticl.item_id = @item_id

		SET  @intRowCount		 = @@ROWCOUNT
		SET  @intCounter		 = 1
		WHILE @intCounter <= @intRowCount
			BEGIN

				-- De a uno x vez para que se disparen los triggers de actualizacion si es que hace falta ! ! !
				UPDATE tbItemCostList		WITH (ROWLOCK)
					SET	coslis_price =  coslis_price
					FROM tbItemCostList								ticl
					INNER JOIN @tblCostLIst							tmp
						ON	tmp.intCounter	= @intCounter		AND
							tmp.coslis_id	= ticl.coslis_id
					WHERE	ticl.comp_id	= @comp_id			AND
							ticl.item_id	= @item_id

				SET @intCounter = @intCounter + 1

			END

	END TRY
	BEGIN CATCH
	END CATCH
	-- ---------------------------------------------------------------


	END TRY
	BEGIN CATCH
		Set @ret_ErrorCode			= -1
		Set	@ret_ErrorDescription	= 'Error: itemID:' +
											convert(varchar,ISNULL(@item_id,-1))			+ ' / colorID:'		+
											convert(varchar,ISNULL(@color_id,-1))			+ ' / sizeID:'		+
											convert(varchar,ISNULL(@size_id,-1))			+ ' / itemIDChild:' +
											convert(varchar,ISNULL(@intItem_id_Child,-1))	+ ' / newItemCode:' + ISNULL(@strItemCode,'') + ' ->>' +  ERROR_MESSAGE()


		RETURN

	END CATCH


END
GO


CREATE PROCEDURE spItemSizeColorRelation_GetData4FullJaus
(
	@comp_id		INT,
	@wst_id			INT,
	@item_id_Parent	INT,
	@item_id_Child	INT
)
AS
	BEGIN
		SET NOCOUNT	ON

		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@item_id_padre	INT,
				@item_id_hijo	INT
			SELECT
				@comp_id		= 1,
				@item_id_padre	= -1,
				@item_id_hijo	= -1
		*/
		-- ---------------------------------------------

		-- SI QUIERE BUSCAR POR ART PADRE
		IF @item_id_Parent > 1 AND  @item_id_Child = -1
			BEGIN
				SELECT
					tiscr.comp_id,
					tiscr.item_id,
					tiscr.item_id_child,
					tiscr.size_id,
					ts.Size_desc,
					ts.Size_code,
					tiscr.color_id,
					tc.color_desc,
					tc.color_code
				FROM tbItemSizeColorRelation	AS tiscr	WITH(NOLOCK)
				INNER JOIN tbSize				AS ts		WITH(NOLOCK)
					ON	ts.comp_id		= tiscr.comp_id AND
						ts.Size_id		= tiscr.size_id
				INNER JOIN tbColor				AS tc		WITH(NOLOCK)
					ON	tc.comp_id		= tiscr.comp_id	AND
						tc.color_id		= tiscr.color_id
				WHERE	tiscr.comp_id	= @comp_id		AND
						tiscr.item_id	= @item_id_Parent
				RETURN
			END

			-- SI QUIERE BUSCAR POR ART HIJO
			IF @item_id_Child > 1 AND @item_id_Parent = -1
				BEGIN
					SELECT
						tiscr.comp_id,
						tiscr.item_id,
						tiscr.item_id_child,
						tiscr.size_id,
						ts.Size_desc,
						ts.Size_code,
						tiscr.color_id,
						tc.color_desc,
						tc.color_code
					FROM tbItemSizeColorRelation	AS tiscr	WITH(NOLOCK)
					INNER JOIN tbSize				AS ts		WITH(NOLOCK)
						ON	ts.comp_id			= tiscr.comp_id AND
							ts.Size_id			= tiscr.size_id
					INNER JOIN tbColor				AS tc		WITH(NOLOCK)
						ON	tc.comp_id			= tiscr.comp_id	AND
							tc.color_id			= tiscr.color_id
					WHERE	tiscr.comp_id		= @comp_id		AND
							tiscr.item_id_child = @item_id_Child
					RETURN
				END

			IF @item_id_Child = -1 AND @item_id_Parent = -1
				BEGIN
					-- SI BUSCA POR TODO
					SELECT
						tiscr.comp_id,
						tiscr.item_id,
						tiscr.item_id_child,
						tiscr.size_id,
						ts.Size_desc,
						ts.Size_code,
						tiscr.color_id,
						tc.color_desc,
						tc.color_code
					FROM tbItemSizeColorRelation	AS tiscr	WITH(NOLOCK)
					INNER JOIN tbSize				AS ts		WITH(NOLOCK)
						ON	ts.comp_id		= tiscr.comp_id AND
							ts.Size_id		= tiscr.size_id
					INNER JOIN tbColor				AS tc		WITH(NOLOCK)
						ON	tc.comp_id		= tiscr.comp_id	AND
							tc.color_id		= tiscr.color_id
					WHERE	tiscr.comp_id	= @comp_id
				END
	END
GO


CREATE PROCEDURE [dbo].[spItemSizeColorRelation_GetPendingData4ItemPublicadoVariations]
(
	@comp_id	INT,
	@mlp_id		INT,
	@item_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT,
				@item_id	INT,
				@guid		UNIQUEIDENTIFIER
			SELECT
				@comp_id	= 1,
				@mlp_id		= 2015,
				@item_id	= 15658,
				@guid		= '398D8AA8-5065-4248-9663-20DB67ABEE8D'
		*/
		-- -------------------------------------------------------------

		SELECT
			''													[ ],
			CONVERT(BIT,	CASE WHEN tts.tmpID IS NULL THEN	'False'
							ELSE								'True'
							END)								[Selected],
			ti.item_code,
			ti.item_desc,
			ti.item_id
			FROM tbItemSizeColorRelation						tiscr	WITH(NOLOCK)
			INNER JOIN tbItem									ti		WITH(NOLOCK)
			ON	ti.comp_id				= tiscr.comp_id			AND
				ti.item_id				= tiscr.item_id_child
			LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations	tmlipv	WITH(NOLOCK)
			ON	tmlipv.comp_id			= ti.comp_id			AND
				tmlipv.item_id			= ti.item_id
			LEFT JOIN tbTemporarySelection						tts		WITH(NOLOCK)
			ON	tts.tmpID				= tiscr.item_id_child	AND
				tts.tmpGUID				= @guid
			WHERE	tiscr.comp_id		= @comp_id				AND
					tiscr.item_id		= @item_id				AND
					tiscr.iscr_Enabled	= 'True'				AND
					tmlipv.comp_id		IS NULL
	END
GO












CREATE PROCEDURE [dbo].[spItemStorage_getCombo]
(
	@comp_id			int,
	@item_id			int
)
as

/*declare 	@comp_id			int,
			@item_id			int

select 		@comp_id			= 1,
			@item_id			= 1
*/
	select		s.stor_desc			[desc],
				s.stor_id			[id]


	from		dbo.tbItemStorage     ist

				inner join dbo.tbStorage  s
				on	s.comp_id		= ist.comp_id
				and ist.stor_id		= s.stor_id


	where		ist.comp_id =	@comp_id
	and			ist.item_id	=	@item_id

	Order By	s.stor_desc












GO












create PROCEDURE [dbo].[spItemStorage_getComboByStock]
(
	@comp_id			INT,
	@item_id			INT,
	@option				INT
)
as

/*
declare 	@comp_id			int,
			@item_id			INT,
			@option				INT

select 		@comp_id			= 1,
			@item_id			= 353,
			@option				= 2
*/


select		s.stor_desc			[desc],
			s.stor_id			[id]


from		dbo.tbItemStorage     ist

			inner join dbo.tbStorage  s
			on	s.comp_id		= ist.comp_id
			and ist.stor_id		= s.stor_id


where		ist.comp_id =	@comp_id
and			ist.item_id	=	@item_id
AND			(
			(@option = 0) OR
			(@option = 1 AND ist.itst_cant > 0) OR
			(@option = 2 AND ist.itst_cant < 0)
			)

Order By	s.stor_desc












GO







CREATE PROCEDURE [dbo].[spItemStorage_getDataByFilters]
(
	@comp_id				Int,
	@ct_transaction			int
)
AS



BEGIN



	SET NOCOUNT ON

	-- -------------------------------------------
	-- -------------------------------------------
	/*
	Declare @comp_id			Int,
			@ct_transaction		Int

	select  @comp_id			= 1,
			@ct_transaction		= 9330
	*/
	-- -------------------------------------------

	DECLARE @now DATETIME
	SET @now = GETDATE()


	Select	ti.item_code,
			ti.item_desc,
			ts.stor_desc,
			tit.it_storePrevious,
			tit.it_qty,
			tis.itst_cant,
			tu.user_lastname + ' ' + tu.user_firstname	[user_name],
			tct.ct_cd,
			tctn.ctn_note1,

			CONVERT(VARCHAR,ti.item_id			) + '-' +
			CONVERT(VARCHAR,tit.ct_transaction	) + '-' +
			CONVERT(VARCHAR,tit.it_transaction	) [ID]


	From	tbItemStorage							tis		WITH (NOLOCK)

			Inner Join tbItemTransactions			tit		WITH (NOLOCK)
			On  tit.item_id		= tis.item_id
			AND tit.stor_id		= tis.stor_id
			AND tit.comp_id		= tis.comp_id

			INNER JOIN tbCommercialTransactions		tct		WITH (NOLOCK)
			ON	tct.comp_id			= tit.comp_id
			--AND tct.bra_id			= tit.bra_id
			AND tct.ct_transaction	= tit.ct_transaction

			LEFT JOIN tbCommercialTransactionNotes tctn		WITH (NOLOCK)
			ON tctn.comp_id			= tct.comp_id
			AND tctn.bra_id			= tct.bra_id
			AND tctn.ct_transaction = tct.ct_transaction

			Inner Join tbItem						ti		WITH (NOLOCK)
			On  ti.comp_id		= tis.comp_id
			And ti.item_id		= tis.item_id

			Inner Join tbStorage					ts		WITH (NOLOCK)
			On	ts.comp_id		= tis.comp_id
			And ts.stor_id		= tis.stor_id

			LEFT JOIN tbUser						tu		WITH (NOLOCK)
			ON	tu.[user_id]	= tct.[user_id]


	Where	tit.comp_id			= @comp_id
	--and		tit.ct_transaction	= @ct_transaction
	AND		tct.sd_id			= 350
	AND		tct.ct_cd			> (dateadd(hour,-8,@now))

	ORDER BY tit.ct_transaction DESC, tit.it_transaction DESC

	/*
	Group By --tit.ct_transaction,
				ti.item_id,
				ti.item_code,
				ti.item_desc,
				ts.stor_desc,
				tis.itst_cant
	*/

END
GO






