CREATE PROCEDURE [dbo].[spItemStorage_getDataById]
(
	@comp_id			int,
	@stor_id			int,
	@item_id			int
)

as

BEGIN

	DECLARE @Picking AS VARCHAR(MAX)
	DECLARE @Storage AS VARCHAR(MAX)
	select	@Picking = itst_PickingLocation,
			@Storage = itst_StorageLocation
		FROM tbItemStorage tis
		WHERE	tis.comp_id = @comp_id
			AND tis.stor_id = @stor_id
			AND tis.item_id = @item_id


	Select dbo.fnGetStock (	@comp_id,
							@stor_id,
							@item_id
						  )							[Phisical],
		   dbo.fnGetAStock( @comp_id,
							@stor_id,
							@item_id,999999999)		[Available],
		   @Picking									[itst_PickingLocation],
		   @Storage									[itst_StorageLocation]


END






GO






