CREATE PROCEDURE [dbo].[spItemStorage_getDataById4Location]
(
	@comp_id			int,
	@stor_id			int,
	@item_id			int
)

AS

SET NOCOUNT ON


-- / - /- / - / - / - / - / - / - / - / --
-- / Parámetros de Prueba /
/*
DECLARE @comp_id			int,
		@stor_id			int,
		@item_id			INT

SELECT  @comp_id		= 1,
	   	@stor_id		= 1,
	   	@item_id        = 256
*/
-- / - /- / - / - / - / - / - / - / - / --

SELECT TOP 1
	   tis.comp_id,
	   tis.stor_id,
	   tis.item_id,
	   tis.itst_cant,
	   tis.itst_cd,
	   ISNULL(tis.itst_PickingLocation,'') [itst_PickingLocation],
	   ISNULL(tis.itst_StorageLocation,'') [itst_StorageLocation]

FROM tbItemStorage tis

WHERE tis.comp_id = @comp_id
AND   tis.stor_id = @stor_id
AND   tis.item_id = @item_id
GO







CREATE Procedure [dbo].[spItemStorage_getReport]
(
		@comp_id		int,
		@lang_id		int,
		@page_id		Int,

		@stor_id		Int,
		@cat_id			int,
		@subcat_id		int,
		@item_id		int,

		@brand_id		int,
		@pres_id		int,
		@user_id        INT,

		@bra_id			INT,
		@intBranch4Lang int




)
AS



BEGIN

	set nocount On

	-- - ---------------------------------------------------------------------------------------
	-- - Testing
	-- - ---------------------------------------------------------------------------------------
	/*
	declare
				@comp_id		int,
				@lang_id		int,
				@page_id		Int,

				@stor_id		Int,
				@cat_id			int,
				@subcat_id		int,
				@item_id		int,
				--@supp_id		int,
				@brand_id		int,
				@pres_id		INT,
				@user_id        INT,
				@bra_id			INT



	Select
				@comp_id		=1,
				@lang_id		=2,
				@page_id		=10049,

				@stor_id		=-1,
				@cat_id			=-1,
				@subcat_id		=-1,
				@item_id		=7087,
				--@supp_id		=-1,
				@brand_id		=-1,
				@pres_id		=-1,
				@user_id        = 1,
				@bra_id			=-1
	*/
	-- - ---------------------------------------------------------------------------------------

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	Create table #tmp	(	stor_id int,
							item_id Int,
							periodo Int,
							[Value] Decimal(19,6))



	Declare @date Datetime,
			@intDayCounter INT,
			@intDayCounterAdd	INT
	Set @date = convert(datetime, convert(char, getdate(), 1), 1) + 1
	--Select @date
	--:::::::::::::::::::::::::::::::::::::::::
	Declare @lstor_id				Int
	Declare @litem_id				Int
	declare @lstor_desc				Varchar(500)
	Declare @litem_code				Varchar(500)
	declare @litem_desc				Varchar(500)
	Declare @litst_cant				Decimal(18,5)
	Declare @lcant					Decimal(18,5)


	/*
	Select	tis.stor_id, ts.stor_desc, tis.item_id,ti.item_code, ti.item_desc,tis.itst_cant

	From	tbItemStorage tis

			Inner Join tbItem ti
			On	ti.comp_id = tis.comp_id
			AND ti.item_id = tis.item_id

			Inner Join tbStorage ts
			On ts.comp_id  = tis.comp_id
			And ts.stor_id =  tis.stor_id

	Where	tis.comp_id		=	@comp_id
	And		(@stor_id		=	-1			or tis.stor_id = @stor_id)
	And		(@item_id		=	-1			or tis.item_id = @item_id)
	and		tis.itst_cant	>	0
	*/





	DECLARE @fun_id INT
	SET @fun_id = 1


	declare cursor_IS_gR cursor For
	Select	tis.stor_id,
			ts.stor_desc,
			tis.item_id,
			ti.item_code,
			ti.item_desc,
			tis.itst_cant

	From	tbItemStorage tis

			Inner Join tbItem ti
			On		ti.comp_id = tis.comp_id
				AND ti.item_id = tis.item_id

			Inner Join tbStorage ts
			On		ts.comp_id  = tis.comp_id
				And ts.stor_id  =  tis.stor_id


	Where		tis.comp_id		=	@comp_id
		And		(@stor_id		=	-1			or tis.stor_id    = @stor_id)
		And		(@item_id		=	-1			or tis.item_id    = @item_id)
		And		(@cat_id		=	-1			or ti.cat_id      = @cat_id)
		And		(@subcat_id		=	-1			or ti.subcat_id   = @subcat_id)
		And		(@brand_id		=	-1			or ti.brand_id    = @brand_id)
		And		(@pres_id		=	-1			or ti.pres_id	  = @pres_id)
		and		tis.itst_cant	>	 0


	open cursor_IS_gR


	FETCH NEXT FROM cursor_IS_gR
	Into	@lstor_id,
			@litem_desc,
			@litem_id,
			@litem_code,
			@litem_desc,
			@litst_cant




	WHILE @@FETCH_STATUS = 0
	Begin
		--Select @lstor_id,@litem_desc, @litem_id, @litem_code, @litem_desc, @litst_cant
		--------------------------------------------

		Set @lcant = @litst_cant
		--Select @lcant


		Set @intDayCounter = 0
		SET @intDayCounterAdd = 0

		While @intDayCounter < 90
		begin

			--Select @i, @date- @i, @date - @i - 15
			--Select @lcant
			--IF @intDayCounter = 75 SET @intDayCounterAdd = 9999

			Insert into #tmp (stor_id, item_id,	[Value] , periodo)
			Select	@lstor_id [stor_id],
					tit.item_id,
					Case When isnull(Sum(tit.it_qty),0) < @lcant Then isnull(Sum(tit.it_qty),0)
						Else @lcant
					End ,
					@intDayCounter

			From	tbItemTransactions						tit
					Inner Join tbCommercialTransactions		tct
					On tct.comp_id			= tit.comp_id
					--AND tct.bra_id			= tit.bra_id
					AND tct.ct_transaction	= tit.ct_transaction
					And tct.sd_id			IN (101,102,104,121,124,130)

			Where	tit.item_id		= @litem_id
			And		tit.stor_id		= @lstor_id
			And		tct.ct_date		Between (@date - @intDayCounter - 15) And (@date -   @intDayCounter  - @intDayCounterAdd)
			And		@lcant			> 0
			Group By [stor_id], tit.item_id



--==
--SELECT @litem_id,@lstor_id,@lcant,(@date - @intDayCounter - 15),(@date -   @intDayCounter  - @intDayCounterAdd),@intDayCounter,@intDayCounterAdd
			--Select (@date - @i - 15), (@date - @i)

			--Select @lstor_id, @litem_id, @i, * From #tmp t
			--Select @lcant, [Value] From #tmp Where stor_id = @lstor_id And item_id = @litem_id And periodo = @i
			If Exists (Select 1 From #tmp Where stor_id = @lstor_id And item_id = @litem_id And periodo = @intDayCounter)
				Set @lcant = @lcant - (Select [Value] From #tmp Where stor_id = @lstor_id And item_id = @litem_id And periodo = @intDayCounter)
			--Select @lcant

			Set @intDayCounter = @intDayCounter + 15
			--

		End

--==
--select * from #tmp


		Insert into #tmp (stor_id, item_id,	[Value] , periodo)
		Select	@lstor_id [stor_id],
				tit.item_id,
				Case When isnull(Sum(tit.it_qty),0) < @lcant Then isnull(Sum(tit.it_qty),0)
						Else @lcant
					End ,
				@intDayCounter

		From	tbItemTransactions						tit
				Inner Join tbCommercialTransactions		tct
				On tct.comp_id			= tit.comp_id
				AND tct.bra_id			= tit.bra_id
				AND tct.ct_transaction	= tit.ct_transaction
				And tct.sd_id			= 101

				INNER JOIN tbUsers4BranchFilter vubf
				ON vubf.comp_id = tct.comp_id
				AND vubf.bra_id = tct.bra_id
				AND vubf.[user_id] = @user_id


		Where	tit.item_id		= @litem_id
		And		tit.stor_id		= @lstor_id
		And		tct.ct_date		Between '1800-01-01' and @date-@intDayCounter
		And		@lcant			> 0
		Group By [stor_id], tit.item_id


		--select * from #tmp


		--------------------------------------------


		fetch cursor_IS_gR
			Into	@lstor_id,
					@litem_desc,
					@litem_id,
					@litem_code,
					@litem_desc,
					@litst_cant


	END


	close cursor_IS_gR
	deallocate cursor_IS_gR


	--select * from #tmp


	select  ts.stor_desc,
			ti.item_code,
			ti.item_desc,
			Isnull([0],0)  Per1,
			Isnull([15],0) Per2,
			Isnull([30],0) Per3,
			Isnull([45],0) Per4,
			Isnull([60],0) Per5,
			Isnull([75],0) Per6,
			Isnull([90],0) Per7,
			tis.itst_cant
		From (Select t.stor_id [stor], t.item_id [item], t.periodo [Period], t.[Value] from #tmp t) as V
			PIVOT
			 (Sum( [Value] ) FOR [Period] IN ([0], [15], [30], [45], [60], [75], [90]) )			as PT

			  Inner Join tbStorage ts
			  On ts.comp_id = @comp_id
			  And ts.stor_id = stor

			  Inner Join tbItem ti
			  On ti.comp_id = @comp_id
			  And ti.item_id = item

			  Inner Join tbItemStorage tis
			  On tis.comp_id = @comp_id
			  And tis.stor_id = stor
			  And tis.item_id = item

	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 103
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

			CASE @item_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)

	     		Else
	     			(Select ti.item_desc From tbItem ti
	     			 Where ti.comp_id = @comp_id
	     			And ti.item_id = @item_id)
		 End [params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 36
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],
			CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		TC.cat_desc
						FROM	tbCategory tc
						WHERE	tC.comp_id = @comp_id AND tc.cat_id= @cat_id)
			END		[params4],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],
			CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
						FROM	tbSubCategory tsc
						WHERE	tsc.comp_id = @comp_id AND tsc.subcat_id= @subcat_id)
			END		[params6],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 73
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],
			CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.brand_desc
						FROM	tbBrand tb
						WHERE	tb.comp_id = @comp_id AND tb.brand_id= @brand_id)
			END		[params8],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 371
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],
			CASE @pres_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tp.pres_desc
						FROM	tbPresentation tp
						WHERE	tp.comp_id = @comp_id AND tp.pres_id= @pres_id)
			END		[params10],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 111
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],
			CASE @stor_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	ts.stor_desc
						FROM	tbStorage ts
						WHERE	ts.comp_id = @comp_id
						AND ts.stor_id=  @stor_id)
			END		[params12]

				Drop table #tmp

END
GO







-- =========================================================
-- Author		:	GA
-- Create date  :	29/05/15
-- Description  :	Reporte para Reposición de Artículos
-- =========================================================


CREATE procedure [dbo].[spItemStorage_getReport_ItemReposition]
(

	  @comp_id					INT,
	  @lang_id					INT,
	  @page_id					INT,

	  @guid						VARCHAR(50),
	  @stor_id					INT,
	  @option					INT,
	  @option2					INT,
	  @itst_StorageLocation		VARCHAR(200),
	  @itst_PickingLocation		VARCHAR(200),
	  @stock					INT,
	  @order					BIT,
	  @stock_option				INT,
	  @activity					INT,
	  @coslis_id				INT,
	  @bra_id					INT,
	  @intBranch4Lang			INT


)
AS


BEGIN

	SET NOCOUNT ON
	set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	--------------------------------------------------------------------------------
	-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
	--------------------------------------------------------------------------------
	/*
	DECLARE	  		  @comp_id					INT,
					  @lang_id					INT,
					  @page_id					INT,

					  @guid						VARCHAR(50),
					  @stor_id					INT,
					  @option					INT,
					  @option2					INT,
					  @itst_StorageLocation		VARCHAR(200),
					  @itst_PickingLocation		VARCHAR(200),
					  @stock					INT,
					  @order					BIT,
					  @stock_option				INT,
					  @activity					INT,
					  @bra_id					INT,
					  @intBranch4Lang			INT



	SELECT			@comp_id				= 1,
					@lang_id				= 2,
					@page_id				= 100952,

					@guid					= '3F2504E0-4F89-11D3-9A0C-0305E82C3301',

					@stor_id				= 1,
					@option					= -1,
					@option2				= -1,
					@itst_StorageLocation	= '',
					@itst_PickingLocation	= '',
					@bra_id					= 1,
					@stock					= 1,
					@order					= 0,
					@stock_option			= 10,
					@activity				= 0
	*/
	-- -------------------------------------------------------------------------------------------------

	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
				  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------



	DECLARE @fun_id INT
	SET		@fun_id = 1

	BEGIN


	declare @stock_data  table(item_id int, getStock DECIMAL(18,2), getAStock decimal(18,2))

	insert into @stock_data
	(		item_id,
			getStock,
			getAStock	)
		select	ti.item_id,
				dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id, ti.item_id),
				dbo.fnGetAStock(@comp_id, @stor_id, ti.item_id, 999999999)

			FROM	tbItem								ti			WITH (NOLOCK)
			INNER JOIN @tblComplexFilter_Items			tempITEM
				ON tempitem.item_id						= ti.item_id
			where	ti.comp_id = @comp_id
						AND	 (@activity		= -1	or tI.item_disabled	= @activity)
						--AND	 (@item_id		= -1	OR I.item_id		= @item_id)
						--AND  (@cat_id		= -1	OR I.cat_id			= @cat_id)
						--AND  (@subcat_id	= -1	OR I.subcat_id		= @subcat_id)
						--AND  (@brand_id		= -1	OR I.brand_id		= @brand_id)




	SELECT
			I.item_code																															[item_code],
			I.item_desc																															[item_desc],
			CASE
				WHEN @stock = 1 THEN	da.getStock
										--dbo.fnGetStockOfStorageGroup(tis2.comp_id,tis2.stor_id,tis2.item_id)
				ELSE
										da.getStock /*dbo.fnGetStockOfStorageGroup(tis2.comp_id,tis2.stor_id,tis2.item_id)*/ / dbo.fnNoZDiv(i.item_upb)
			END																																	[Stock],

			CASE
				WHEN @stock = 1 THEN	da.getAStock
									--dbo.fnGetAStock(tis2.comp_id,tis2.stor_id,tis2.item_id , 999999999)
				ELSE					da.getAStock
									/*dbo.fnGetAStock(tis2.comp_id,tis2.stor_id,tis2.item_id,999999999)*/ / dbo.fnNoZDiv(i.item_upb)
			END																																	[Available],
			ISNULL(i.item_cantMin,0)																											[item_cantMin],
			ISNULL(i.item_cantOpt,0)																											[item_cantOpt],
			CASE
				WHEN @stock = 1 then
									ISNULL(i.item_cantOpt,0) - da.getAStock /*dbo.fnGetAStock(tis2.comp_id,tis2.stor_id,tis2.item_id , 999999999)*/
				ELSE
									ISNULL(i.item_cantOpt,0) - da.getAStock /*dbo.fnGetAStock(tis2.comp_id,tis2.stor_id,tis2.item_id,999999999)*/ / dbo.fnNoZDiv(i.item_upb)
			END																																	[DisOptimo],
			CASE
				WHEN @stock = 1 then
									ISNULL(i.item_cantOpt,0) - da.getStock /*dbo.fnGetStockOfStorageGroup(tis2.comp_id,tis2.stor_id,tis2.item_id)*/
				ELSE
									ISNULL(i.item_cantOpt,0) - da.getStock /* dbo.fnGetStockOfStorageGroup(tis2.comp_id,tis2.stor_id,tis2.item_id)*/	/ dbo.fnNoZDiv(i.item_upb)
			END																																	[FisOptimo],
			isnull(vipot.qty,0)																													[PO_QtyPendiente],
			i.item_vendorCode																													[item_vendorCode]


	FROM	dbo.tbItem															I				WITH (NOLOCK)

			INNER JOIN @stock_data												da
				ON da.item_id						= I.item_id

			INNER JOIN @tblComplexFilter_Items									tempITEM
			ON	tempitem.item_id = I.item_id

			INNER join tbStorage												st				WITH (NOLOCK)
			on  ST.[comp_id]						= I.[comp_id]	AND
				ST.[stor_id]						= @stor_id

			--LEFT JOIN tbItemCostList											ticl			WITH (NOLOCK)
			--ON	ticl.comp_id						= I.comp_id		AND
			--	ticl.item_id						= I.item_id


			LEFT JOIN tbItemStorage												tis2			WITH (NOLOCK)
			on  tis2.comp_id						= I.comp_id		AND
				tis2.stor_id						= st.stor_id	AND
				tis2.item_id						= I.item_id

			LEFT JOIN vwItems_PurchaseOrderTotals								vipot			WITH (NOLOCK)
			ON vipot.comp_id						= i.comp_id		AND
			   vipot.item_id						= i.item_id

			WHERE I.[comp_id]	= @comp_id
			AND	  ST.stor_id	= @stor_id
			--AND	 (@coslis_id		= -1 or ticl.coslis_id		=	@coslis_id)
			AND		CASE
						WHEN @coslis_id = -1	THEN 1
						WHEN EXISTS(	SELECT TOP 1 1
							            	FROM tbItemCostList AS ticl	WITH (NOLOCK)
						            		WHERE	ticl.comp_id	= @comp_id		AND
						            				ticl.coslis_id	= @coslis_id	AND
						            				ticl.item_id	= I.item_id		AND
						            				ticl.coslis_price <> 0
									)			THEN 1
						ELSE					     0
					END = 1
			AND	 (
								(@option	 = -1 ) OR
								(@option	 = 0 AND tis2.itst_StorageLocation like @itst_StorageLocation + '%') or
								(@option	 = 1 AND tis2.itst_StorageLocation like '%' + @itst_StorageLocation + '%') or
								(@option	 = 2 AND tis2.itst_StorageLocation = @itst_StorageLocation ) or
								(@option	 = 3 AND tis2.itst_StorageLocation <> @itst_StorageLocation ) or
								(@option	 = 4 AND tis2.itst_StorageLocation not like '%' + @itst_StorageLocation + '%')
						)
			AND		(
								(@option2	 = -1 ) OR
								(@option2	 = 0 AND tis2.itst_PickingLocation like @itst_PickingLocation + '%') or
								(@option2	 = 1 AND tis2.itst_PickingLocation like '%' + @itst_PickingLocation + '%') or
								(@option2	 = 2 AND tis2.itst_PickingLocation = @itst_PickingLocation ) or
								(@option2	 = 3 AND tis2.itst_PickingLocation <> @itst_PickingLocation ) or
								(@option2	 = 4 AND tis2.itst_PickingLocation not like '%' + @itst_PickingLocation + '%')
			)


			AND		(
						(@stock_option = -1)									OR

						(@stock_option = 0 and da.getStock > 0)					OR

						(@stock_option = 1 and da.getAStock > 0)				OR

						(@stock_option = 2 and da.getStock = 0)					OR

						(@stock_option = 3 and da.getStock < 0)					OR

						(@stock_option = 4 and da.getStock <= 0)				OR


						(@stock_option = 5 and da.getAStock = 0)				OR


						(@stock_option = 6 and da.getAStock < 0)				OR


						(@stock_option = 7 and da.getAStock <= 0)				OR


						(@stock_option = 8 AND da.getAStock < I.item_cantMin)	OR

						(@stock_option = 9 AND da.getAStock < I.item_cantOpt)	OR

						(
							@stock_option = 10	AND	da.getAStock < I.item_cantMin			AND
													da.getStock  > 0
						)														OR

						(
							@stock_option = 11												AND
													da.getAStock < I.item_cantOpt			AND
													da.getStock  > 0
						)

						-- Si se ponen mas opciones se deben poner en estos dos sp: spItemStorage_getReport_ItemReposition y [spItemStorage_getReportStockCheck]
					)


	--WHERE I.[comp_id]	= @comp_id
	--AND	 (@stor_id		= -1	or ST.stor_id		= @stor_id)
	--AND	 (
	--					(@option	 = -1 ) or
	--					(@option	 = 0 and tis2.itst_StorageLocation like @itst_StorageLocation + '%') or
	--					(@option	 = 1 and tis2.itst_StorageLocation like '%' + @itst_StorageLocation + '%') or
	--					(@option	 = 2 and tis2.itst_StorageLocation = @itst_StorageLocation ) or
	--					(@option	 = 3 and tis2.itst_StorageLocation <> @itst_StorageLocation ) or
	--					(@option	 = 4 and tis2.itst_StorageLocation not like '%' + @itst_StorageLocation + '%')
	--			)
	--AND		(
	--					(@option2	 = -1 ) or
	--					(@option2	 = 0 and tis2.itst_PickingLocation like @itst_PickingLocation + '%') or
	--					(@option2	 = 1 and tis2.itst_PickingLocation like '%' + @itst_PickingLocation + '%') or
	--					(@option2	 = 2 and tis2.itst_PickingLocation = @itst_PickingLocation ) or
	--					(@option2	 = 3 and tis2.itst_PickingLocation <> @itst_PickingLocation ) or
	--					(@option2	 = 4 and tis2.itst_PickingLocation not like '%' + @itst_PickingLocation + '%')
	--)

	--AND		(@activity		= -1 or I.item_disabled		=	@activity)

	--AND		(
	--			(@stock_option = -1)													OR

	--			(@stock_option = 0 and i.item_id  in (	select da.item_id
	--													from @stock_data da
	--													where da.getStock > 0))			OR

	--			(@stock_option = 1 and i.item_id  in (	select da.item_id
	--													from @stock_data da
	--													where da.getAStock > 0))		OR

	--			(@stock_option = 2 and i.item_id  in (	select da.item_id
	--													from @stock_data da
	--													where da.getStock = 0))			OR

	--			(@stock_option = 3 and i.item_id  in (	select da.item_id
	--													from @stock_data da
	--													where da.getStock < 0))			OR

	--			(@stock_option = 4 and i.item_id  in (	select da.item_id
	--													from @stock_data da
	--													where da.getStock <= 0))		OR


	--			(@stock_option = 5 and i.item_id  in (	select da.item_id
	--													from @stock_data da
	--													where da.getAStock = 0))		OR


	--			(@stock_option = 6 and i.item_id  in (	select da.item_id
	--													from @stock_data da
	--													where da.getAStock < 0))		OR


	--			(@stock_option = 7 and i.item_id  in (	select da.item_id
	--													from @stock_data da
	--													where da.getAStock <= 0))

	--																					OR


	--			(
	--				@stock_option = 8 AND
	--				ISNULL((SELECT tmp.getAStock
	--							FROM @stock_data tmp
	--							WHERE tmp.item_id = i.item_id),0) < I.item_cantMin

	--			)
	--																					OR

	--			(
	--				@stock_option = 9 AND
	--				ISNULL((SELECT tmp.getAStock
	--							FROM @stock_data tmp
	--							WHERE tmp.item_id = i.item_id),0) < I.item_cantOpt

	--			)

	--																					OR

	--			(
	--				@stock_option = 10												AND
	--				ISNULL((SELECT tmp.getAStock
	--							FROM @stock_data tmp
	--							WHERE tmp.item_id = i.item_id),0) < I.item_cantMin	AND
	--				ISNULL((SELECT tmp.getStock
	--							FROM @stock_data tmp
	--							WHERE tmp.item_id = i.item_id),0) > 0
	--			)

	--																					OR

	--			(
	--				@stock_option = 11												AND
	--				ISNULL((SELECT tmp.getAStock
	--							FROM @stock_data tmp
	--							WHERE tmp.item_id = i.item_id),0) < I.item_cantOpt	AND
	--				ISNULL((SELECT tmp.getStock
	--							FROM @stock_data tmp
	--							WHERE tmp.item_id = i.item_id),0) > 0
	--			)

	--			-- Si se ponen mas opciones se deben poner en estos dos sp: spItemStorage_getReport_ItemReposition y [spItemStorage_getReportStockCheck]



	--		)


	ORDER BY I.item_desc


	exec [spReports_getData3] @comp_id,@intBranch4Lang,@lang_id,@page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	Select


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 111
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],
			CASE @stor_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	ts.stor_desc
						FROM	tbStorage ts
						WHERE	ts.comp_id = @comp_id
						AND ts.stor_id=  @stor_id)
			END		[params4],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 43
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1					) [params5],

			CASE @option WHEN -1 THEN
					(SELECT	tut.utexts_desc
					  FROM	tbsysUniqueTexts tut
					  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc + ' '+ISNULL(@itst_StorageLocation,'')
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 2
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @option)
			END		[params6],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 45
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1					) [params7],

			CASE @option2 WHEN -1 THEN
					(SELECT	tut.utexts_desc
					  FROM	tbsysUniqueTexts tut
					  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
				ELSE
				(SELECT		tov.optval_desc + ' '+ISNULL(@itst_PickingLocation,'')
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 2
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @option2)
			END		[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1505
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params15],
				CASE @stock WHEN -1 THEN
					(SELECT	tut.utexts_desc
					  FROM	tbsysUniqueTexts tut
					  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
				ELSE
				(SELECT		tov.optval_desc
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 171
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @stock)
			END		[params16],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1176
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params17],
				CASE @order WHEN -1 THEN
					(SELECT	tut.utexts_desc
					  FROM	tbsysUniqueTexts tut
					  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
				ELSE
				(SELECT		tov.optval_desc
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 1
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @order)
			END		[params18],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2378
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params19],
				CASE @stock_option WHEN -1 THEN
					(SELECT	tut.utexts_desc
					  FROM	tbsysUniqueTexts tut
					  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
				ELSE
				(SELECT		tov.optval_desc
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 316
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @stock_option)
			END		[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 529
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params21],

				CASE @activity WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 320
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @activity)
			END
			[params22],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 391
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params23],

				CASE @coslis_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
				ELSE
					(SELECT		ticl.coslis_desc
					FROM	dbo.tbItemCostListName ticl
					WHERE	ticl.comp_id	= @comp_id
					AND		ticl.coslis_id	= @coslis_id)
			END
			[params24]





	END

END
GO


-- =============================================
-- Author:		GA
-- Create date: 08/11/10
-- Description:	Reporte para control de Stock
-- =============================================


CREATE procedure [dbo].[spItemStorage_getReportStockCheck]
(
	  @comp_id					INT,
	  @lang_id					INT,
	  @page_id					INT,

	  @item_id					INT,
	  @cat_id				    INT,
	  @subcat_id				INT,
	  @brand_id					INT,
	  @stor_id					INT,
	  @option					INT,
	  @option2					INT,
	  @itst_StorageLocation		VARCHAR(200),
	  @itst_PickingLocation		VARCHAR(200),
	  --==STL parámetros nuevos
	  @stock					INT,
	  @order					BIT,
	  --GA . Parametro nuevo Opciones de Stock - 02-08-13
	  @stock_option				INT,
	   --GA . Parametro nuevo Estado(Inactivos/Activos) - 16-09-13
	  @activity					INT,
	  @guid					    VARCHAR(50), --CF DE ITEMS
	  @bra_id					INT,
	  @intBranch4Lang			INT
)
AS
	BEGIN
		-- para MOS
		-- Parametro @Order ( Descuenta pedidos cerrados )
		-- No = 0
		-- Si = 1

		SET NOCOUNT ON
		set dateformat 'ymd'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		--------------------------------------------------------------------------------
		-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
		--------------------------------------------------------------------------------
		/*
		DECLARE
			@comp_id					int,
			@lang_id					int,
			@page_id					int,

			@item_id					int,
			@cat_id						int,
			@subcat_id					int,
			@brand_id					int,
			@stor_id					int,
			@option						int,
			@option2					int,
			@itst_StorageLocation		varchar(200),
			@itst_PickingLocation		varchar(200),

			--==STL parámetros nuevos
			@stock						int,
			@order						bit,

			@stock_option				int,
			@activity					INT,

			@bra_id						int,
			@intBranch4Lang				int
		SELECT
			@comp_id				= 1,
			@lang_id				= 2,
			@page_id				= 10074,
			@item_id				= -1,
			@cat_id				    = -1,
			@subcat_id				= -1,
			@brand_id				= -1,
			@stor_id				= 4,
			@option					= 1,
			@option2				= 1,
			@itst_StorageLocation	= '',
			@itst_PickingLocation	= '',
			@bra_id					= 1,
			@stock					= 2,
			@order					= 0,
			@stock_option			= -1,
			@activity				= 0
		*/
		---------------------------------------------------------------------------------------------------
		--//////////////////////////////////////////////////////////////////////////////////////////////--
		---------------------------------------------------------------------------------------------------


		DECLARE @lGuid AS UNIQUEIDENTIFIER

		SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuid     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
		-- -------------------------------------------------------------

		DECLARE @fun_id INT
		SET		@fun_id = 1
		BEGIN

			DECLARE		@stock_data  TABLE(item_id INT PRIMARY KEY, getStock DECIMAL(18,2), getAStock DECIMAL(18,2))

			INSERT INTO @stock_data
			(
				item_id,
				getStock,
				getAStock
			)
			SELECT	
				I.item_id,
				dbo.fnGetStockOfStorageGroup(	@comp_id,	@stor_id, I.item_id),
				dbo.fnGetAStock(				@comp_id,	@stor_id, I.item_id, 999999999)
				FROM	tbItem											I	WITH (NOLOCK)
				INNER JOIN @tblComplexFilter_Items						tempITEM
				ON tempitem.item_id						= I.item_id
				WHERE	I.comp_id							= @comp_id
						AND	 (@activity		= -1	or I.item_disabled	= @activity)
						AND	 (@item_id		= -1	OR I.item_id		= @item_id)
						AND  (@cat_id		= -1	OR I.cat_id			= @cat_id)
						AND  (@subcat_id	= -1	OR I.subcat_id		= @subcat_id)
						AND  (@brand_id		= -1	OR I.brand_id		= @brand_id)






			SELECT
				I.item_code,
				I.item_desc,
				isnull(tis2.itst_StorageLocation,'')						[itst_StorageLocation],
				isnull(tis2.itst_PickingLocation,'')						[itst_PickingLocation],

				CASE
					WHEN @stock = 1 THEN da.getStock
						--dbo.fnGetStockOfStorageGroup(tis2.comp_id,tis2.stor_id,tis2.item_id) /*ISNULL(tis2.itst_cant,0)*/
					ELSE				 da.getStock / dbo.fnNoZDiv(i.item_upb)
						--.fnGetStockOfStorageGroup(tis2.comp_id,tis2.stor_id,tis2.item_id)/*ISNULL(tis2.itst_cant,0)*/	/ dbo.fnNoZDiv(i.item_upb)
				END															[Stock],
				'.....'														[Check],
				tc.cat_desc													[cat_desc],
				tsc.subcat_desc												[subcat_desc],
				IsNull((
							SELECT SUM(tsod.sod_qty)
								FROM tbSaleOrderDetail tsod
								INNER JOIN tbSaleOrderHeader tsoh			WITH (NOLOCK)
									ON		tsoh.comp_id	= tsod.comp_id
										AND tsoh.bra_id		= tsod.bra_id
										AND tsoh.soh_id		= tsod.soh_id
								INNER JOIN tbDocumentsFile tdf				WITH (NOLOCK)
									ON		tdf.comp_id		= tsoh.comp_id
										AND tdf.df_id		= tsoh.df_id
								WHERE	tsod.comp_id = @comp_id
									AND tsod.stor_id = @stor_id
									AND tdf.sd_id IN (1,2)
									AND tsod.item_id = i.item_id
									AND tsoh.ssos_id = 50
					  )	,0)													[SOClosed],
				CASE
					WHEN @stock = 1 THEN da.getAStock
						--dbo.fnGetAStock(tis2.comp_id,tis2.stor_id,tis2.item_id , 999999999) /*ISNULL(tis2.itst_cant,0)*/
					ELSE				 da.getAStock / dbo.fnNoZDiv(i.item_upb)
						--dbo.fnGetAStock(tis2.comp_id,tis2.stor_id,tis2.item_id,999999999)/*ISNULL(tis2.itst_cant,0)*/	/ dbo.fnNoZDiv(i.item_upb)
				END															[Available]

			FROM	dbo.tbItem											I			WITH (NOLOCK)
				INNER JOIN @stock_data									da
					ON da.item_id						= I.item_id
				INNER JOIN tbCategory									tc			WITH (NOLOCK)
				ON  tc.comp_id							= I.comp_id		AND
					tc.cat_id							= I.cat_id
				INNER JOIN tbSubCategory								tsc			WITH (NOLOCK)
				ON  tsc.comp_id							= I.comp_id		AND
					tsc.subcat_id						= I.subcat_id
				INNER JOIN tbBrand										tb			WITH (NOLOCK)
				ON  tb.comp_id							= I.comp_id		AND
					tb.brand_id							= I.brand_id
				INNER join tbStorage									st			WITH (NOLOCK)
				on  ST.[comp_id]						= I.[comp_id]	AND
					ST.[stor_id]						= @stor_id
				LEFT join tbItemStorage									tis2		WITH (NOLOCK)
				on  tis2.comp_id						= I.comp_id		AND
					tis2.stor_id						= st.stor_id	AND
					tis2.item_id						= I.item_id
			WHERE I.[comp_id]	= @comp_id
			AND	  ST.stor_id	= @stor_id
			AND	 (
								(@option	 = -1 ) OR
								(@option	 = 0 AND tis2.itst_StorageLocation like @itst_StorageLocation + '%') or
								(@option	 = 1 AND tis2.itst_StorageLocation like '%' + @itst_StorageLocation + '%') or
								(@option	 = 2 AND tis2.itst_StorageLocation = @itst_StorageLocation ) or
								(@option	 = 3 AND tis2.itst_StorageLocation <> @itst_StorageLocation ) or
								(@option	 = 4 AND tis2.itst_StorageLocation not like '%' + @itst_StorageLocation + '%')
						)
			AND		(
								(@option2	 = -1 ) OR
								(@option2	 = 0 AND tis2.itst_PickingLocation like @itst_PickingLocation + '%') or
								(@option2	 = 1 AND tis2.itst_PickingLocation like '%' + @itst_PickingLocation + '%') or
								(@option2	 = 2 AND tis2.itst_PickingLocation = @itst_PickingLocation ) or
								(@option2	 = 3 AND tis2.itst_PickingLocation <> @itst_PickingLocation ) or
								(@option2	 = 4 AND tis2.itst_PickingLocation not like '%' + @itst_PickingLocation + '%')
			)


			AND		(
						(@stock_option = -1)									OR

						(@stock_option = 0 and da.getStock > 0)					OR

						(@stock_option = 1 and da.getAStock > 0)				OR

						(@stock_option = 2 and da.getStock = 0)					OR

						(@stock_option = 3 and da.getStock < 0)					OR

						(@stock_option = 4 and da.getStock <= 0)				OR


						(@stock_option = 5 and da.getAStock = 0)				OR


						(@stock_option = 6 and da.getAStock < 0)				OR


						(@stock_option = 7 and da.getAStock <= 0)				OR


						(@stock_option = 8 AND da.getAStock < I.item_cantMin)	OR

						(@stock_option = 9 AND da.getAStock < I.item_cantOpt)	OR

						(
							@stock_option = 10	AND	da.getAStock < I.item_cantMin			AND
													da.getStock  > 0
						)														OR

						(
							@stock_option = 11												AND
													da.getAStock < I.item_cantOpt			AND
													da.getStock  > 0
						)

						-- Si se ponen mas opciones se deben poner en estos dos sp: spItemStorage_getReport_ItemReposition y [spItemStorage_getReportStockCheck]
					)
			ORDER BY tc.cat_desc,tsc.subcat_desc,I.item_desc


			EXEC [spReports_getData3] @comp_id,@intBranch4Lang,@lang_id,@page_id


			/* devolución de parámetros recibidos */
			DECLARE @related_page_id INT
			SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
			/*************************************************************************************************************/
			/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
			/*
					SELECT	t.ctrl_id,	t.[text_desc]
					FROM	[tbsysTexts]				t
							inner join [tbsysControls]	c
							on c.[ctrl_id] = t.[ctrl_id]
					where	t.[lang_id]	= @lang_id
					and		t.[page_id]	= @related_page_id
					and		t.[type_id]	= 1
			*/
			/*************************************************************************************************************/

			Select

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 103
      				and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )			[params1],
					CASE @item_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT	ti.item_desc
							 From tbItem ti
							 Where ti.comp_id=@comp_id And ti.item_id=@item_id)
					END		[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 111
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],
					CASE @stor_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT	ts.stor_desc
								FROM	tbStorage ts
								WHERE	ts.comp_id = @comp_id
								AND ts.stor_id=  @stor_id)
					END		[params4],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id   = 43
      				 and   t.[page_id] = @related_page_id
      				 and   t.[type_id] = 1					) [params5],

					CASE @option WHEN -1 THEN
							(SELECT	tut.utexts_desc
							  FROM	tbsysUniqueTexts tut
							  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT		tov.optval_desc + ' '+ISNULL(@itst_StorageLocation,'')
							FROM	dbo.tbsysOptionsValues tov
							WHERE	tov.optval_class	= 2
							AND		tov.lang_id			= @lang_id
							AND		tov.optval_id		= @option)
					END		[params6],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id   = 45
      				 and   t.[page_id] = @related_page_id
      				 and   t.[type_id] = 1					) [params7],

					CASE @option2 WHEN -1 THEN
							(SELECT	tut.utexts_desc
							  FROM	tbsysUniqueTexts tut
							  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
						ELSE
						(SELECT		tov.optval_desc + ' '+ISNULL(@itst_PickingLocation,'')
							FROM	dbo.tbsysOptionsValues tov
							WHERE	tov.optval_class	= 2
							AND		tov.lang_id			= @lang_id
							AND		tov.optval_id		= @option2)
					END		[params8],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 36
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params9],
					CASE @cat_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT tc.cat_desc
							 FROM tbCategory tc
							WHERE tc.comp_id = @comp_id
							AND	  tc.cat_id = @cat_id)

					END		[params10],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 38
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params11],
					CASE @subcat_id WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT tsc.subcat_desc
							 FROM tbSubCategory tsc

							 INNER JOIN tbCategory tc
							 ON tc.comp_id = tsc.comp_id
							 AND tc.cat_id = tsc.cat_id


							 WHERE tc.comp_id = @comp_id
							 AND tc.cat_id = @cat_id
							 AND tsc.subcat_id =@subcat_id)

					END		[params12],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 73
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params13],
					CASE @brand_id  WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT tb.brand_desc
							 FROM tbBrand tb
								WHERE tb.comp_id = @comp_id
								AND  tb.brand_id = @brand_id )
					END		[params14],


					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 1505
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params15],
						CASE @stock WHEN -1 THEN
							(SELECT	tut.utexts_desc
							  FROM	tbsysUniqueTexts tut
							  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
						ELSE
						(SELECT		tov.optval_desc
							FROM	dbo.tbsysOptionsValues tov
							WHERE	tov.optval_class	= 171
							AND		tov.lang_id			= @lang_id
							AND		tov.optval_id		= @stock)
					END		[params16],


					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 1176
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params17],
						CASE @order WHEN -1 THEN
							(SELECT	tut.utexts_desc
							  FROM	tbsysUniqueTexts tut
							  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
						ELSE
						(SELECT		tov.optval_desc
							FROM	dbo.tbsysOptionsValues tov
							WHERE	tov.optval_class	= 1
							AND		tov.lang_id			= @lang_id
							AND		tov.optval_id		= @order)
					END		[params18],

						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 2378
      				 --AND t.[lang_id] = @lang_id
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params19],
						CASE @stock_option WHEN -1 THEN
							(SELECT	tut.utexts_desc
							  FROM	tbsysUniqueTexts tut
							  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
						ELSE
						(SELECT		tov.optval_desc
							FROM	dbo.tbsysOptionsValues tov
							WHERE	tov.optval_class	= 316
							AND		tov.lang_id			= @lang_id
							AND		tov.optval_id		= @stock_option)
					END		[params20],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      						 WHERE t.ctrl_id = 529
      						 --AND t.[lang_id] = @lang_id
      						 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params21],

						CASE @activity WHEN -1 THEN
							(SELECT		tut.utexts_desc
								FROM	tbsysUniqueTexts tut
								WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
						ELSE
							(SELECT		tov.optval_desc
							FROM	dbo.tbsysOptionsValues tov
							WHERE	tov.optval_class	= 320
							AND		tov.lang_id			= @lang_id
							AND		tov.optval_id		= @activity)
					END
					[params22]

	END

END
GO




CREATE PROCEDURE spItemStorage_GetStockTooltip4PCConfig
(
	@comp_id	INT,
	@stor_id	INT,
	@bra_id		INT,
	@item_id	INT
)
AS

	SET NOCOUNT ON
		BEGIN

			-- ------------------------------
			-- TESTING
			-- ------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@stor_id	INT,
					@bra_id		INT,
					@item_id	INT
				SELECT
					@comp_id	= 1,
					@stor_id	= 113,
					@bra_id		= 1,
					@item_id	= 698
			*/
			-- ------------------------------



			--OBTENEMOS TODOS LOS STOR_ID A LOS QUE PERTENECE
			--Y LOS INSERTAMOS EN LA VARIABLE DE TABLA
			DECLARE @tmpStorageGroup TABLE(stor_id INT PRIMARY KEY)

			INSERT INTO @tmpStorageGroup
			(
				stor_id
			)
			SELECT DISTINCT
				tsgd.stor_id
			FROM tbStorageGroupDetail tsgd
			WHERE tsgd.stor_id = @stor_id

			--SELECT * FROM @tmpStorageGroup


			SELECT
				ts.stor_desc + ' : ' + CONVERT(VARCHAR, dbo.fnGetStock(@comp_id, @stor_id,@item_id)) [Tooltip]
			FROM tbItemStorage						tis
				INNER JOIN tbStorage				ts
					ON	ts.comp_id	= tis.comp_id	AND
						ts.stor_id	= tis.stor_id
				INNER JOIN @tmpStorageGroup			tmp
					ON	tmp.stor_id	= ts.stor_id

			WHERE	tis.comp_id		= @comp_id AND
					tis.item_id		= @item_id

		END

GO






-- =================================================================
-- Author:		MOS
-- Modif:		MOS  02-2009
-- Da de alta el articulo en el deposito
-- =================================================================

CREATE  PROCEDURE [dbo].[spItemStorage_insertData]
(
	@comp_id					As Int,
	@item_id					As Int,
	@stor_id					As Int,
	@itst_cant					As Decimal(18,4)
)

AS

BEGIN

	set nocount on;

	If	@item_id IS NOT NULL AND
		@stor_id IS NOT NULL AND
		NOT EXISTS(	SELECT TOP 1 1
						From tbItemStorage tis	WITH (NOLOCK)
             			Where		tis.comp_id = @comp_id
             					And tis.item_id = @item_id
             					And tis.stor_id = @stor_id )
		BEGIN

			Insert into tbItemStorage WITH (ROWLOCK)
			(
				comp_id,
				stor_id,
				item_id,
				itst_cant,
				itst_cd
			)
			VALUES
			(
				@comp_id,
				@stor_id,
				@item_id,
				@itst_cant,
				Getdate()
			)

		END

END



GO







CREATE PROCEDURE [dbo].spItemStorage_insertDataFromMercadoLibre
(
	@comp_id				INT,
	@item_id				INT,
	@stor_id				INT,
	@stock					DECIMAL(19,4),
	@return_value			INT	OUTPUT
)
AS


BEGIN


	SET NOCOUNT ON

	SET @return_value = 0


	IF EXISTS(
				SELECT 1
					FROM tbStorage tpl		WITH (NOLOCK)
					WHERE	tpl.comp_id						= @comp_id AND
							tpl.stor_id						= @stor_id AND
							tpl.stor_isAvailble4MLInsert	= 'True'
			)
		BEGIN
			IF NOT EXISTS(
						SELECT 1
							FROM tbItemStorage tpli		WITH (NOLOCK)
							WHERE	tpli.comp_id = @comp_id AND
									tpli.stor_id = @stor_id AND
									tpli.item_id = @item_id
					)
				BEGIN
					INSERT INTO tbItemStorage		WITH (ROWLOCK)
							 (
							 	comp_id, stor_id, item_id,
					            itst_cant, itst_cd, itst_PickingLocation,
					            itst_StorageLocation, itst_updateByInTransitStock,
					            itst_LastAvailableInRelalculation
							 )
						VALUES(
								@comp_id,
								@stor_id,
								@item_id,
								@stock,
								GETDATE(),
								'',
								'',
								NULL,
								0
								)
					SET @return_value = 1
				END
			ELSE
				BEGIN

					UPDATE tbItemStorage		WITH (ROWLOCK)
						SET		itst_cant = @stock
						WHERE	comp_id = @comp_id AND
								stor_id = @stor_id AND
								item_id = @item_id


					SET @return_value = 1

				END
		END




END
GO






CREATE  PROCEDURE [dbo].[spItemStorage_insertOneData]
(
	@comp_id					As Int,
	@item_id					As Int,
	@stor_id					As Int,
	@itst_cant					As Decimal(18,4),

	@return_value				as int			output,
	@ret_ErrorCode				as int			output,
	@ret_ErrorDescription		as varchar(200) Output
)

as

set nocount on;

Set @return_value			= 0
Set @ret_ErrorCode			= 0
Set @ret_ErrorDescription	= ''

If Not exists(	Select 1
					From tbItemStorage tis
             		Where		tis.comp_id = @comp_id
             				And tis.item_id = @item_id
             				And tis.stor_id = @stor_id )
	BEGIN

		Insert into tbItemStorage
		(
			comp_id,
			stor_id,
			item_id,
			itst_cant,
			itst_cd
		)
		VALUES
		(
			@comp_id,
			@stor_id,
			@item_id,
			@itst_cant,
			Getdate()
		)

	END





GO






-- =================================================================
-- Author:		MOS
-- Modif:		MOS  02-7-08
-- Actualiza el Stock Sumandole la cantidad de TempItemStock
-- NO SE USA MAS!!!!!!!   se hace lo mismo desde it_insertdata
-- =================================================================

CREATE  PROCEDURE [dbo].[spItemStorage_UpdateData]
(

	@comp_id					INT,
	@tis_guid					uniqueidentifier
)

as

set nocount on;

Update  dbo.tbItemStorage
	Set		itst_cant = (A.itst_cant - (B.tis_qty *
												  Case B.tis_isCredit
													When 'True'  Then -1
													When 'False' Then 1
												  End
										)
						)
	From	dbo.tbItemStorage A, dbo.tbTempItemStock B
	Where   A.comp_id = B.comp_id
		and	B.tis_guid = @tis_guid
		and A.stor_id = isnull(B.stor_id,0)
		and A.item_id = B.item_id






GO






CREATE PROCEDURE [dbo].[spItemStorage_updateLocationData]
(
	@comp_id					int,
	@stor_id					int,
	@item_id					int,
	@itst_cant					Decimal(18,4),
	@itst_PickingLocation		Varchar(250),
	@itst_StorageLocation		Varchar(250)
)
AS

BEGIN

	set nocount on

-- -----------------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------------
	/*
	declare
		@comp_id					int,
		@stor_id					int,
		@item_id					int,
		@itst_cant					Int,
		@itst_PickingLocation		Int,
		@itst_StorageLocation		int

	select
		@comp_id					=1,
		@stor_id					=1,
		@item_id					=238,
		@itst_cant					=11,
		@itst_PickingLocation		=A,
		@itst_StorageLocation		=S
	*/
-- -----------------------------------------------------------------------



	If Exists (SELECT TOP 1 1
				   From tbItemStorage tis	WITH (NOLOCK)
				   Where	tis.comp_id		= @comp_id
				   And		tis.stor_id		= @stor_id
				   And		tis.item_id		= @item_id)

		-- ------------------------------------------
		-- JAMAS tocar la CANTIDAD en este Lugar !!!!
		-- ------------------------------------------
		Update	tbItemStorage
			Set
				itst_PickingLocation = @itst_PickingLocation,
				itst_StorageLocation = @itst_StorageLocation
			Where		comp_id		= @comp_id
				And		stor_id		= @stor_id
				And		item_id		= @item_id
		-- ------------------------------------------

	Else

		Insert into tbItemStorage
		(
			comp_id,
			stor_id,
			item_id,
			itst_cant,
			itst_cd,
			itst_PickingLocation,
			itst_StorageLocation
		)
		VALUES
		(
			@comp_id,
			@stor_id,
			@item_id,
			@itst_cant,
			Getdate(),
			@itst_PickingLocation,
			@itst_StorageLocation
		)


END
GO






-- =================================================================
-- Author:		MOS
-- Modif:		MOS  07-2009
-- Da de alta el articulo en el deposito o actualiza la cantidad
-- =================================================================

CREATE  PROCEDURE [dbo].[spItemStorage_updateQty]
(
	@comp_id					As Int,
	@item_id					As Int,
	@stor_id					As Int,
	@itst_cant					As Decimal(18,4),

	--Agregado...
	@return_value						as int			output,
	@ret_ErrorCode						as int			output,
	@ret_ErrorDescription				as varchar(200) Output
)

as

BEGIN



	set nocount ON


	--------------------------------
	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''
	--------------------------------



	IF NOT EXISTS (	SELECT	1
	              		FROM	tbItemStorage tis			WITH (NOLOCK)
	              		WHERE 	tis.comp_id = @comp_id
	              		AND		tis.item_id = @item_id
             			AND		tis.stor_id = @stor_id )
		BEGIN

			-- Da de alta si no existe el item en el deposito
			INSERT INTO tbItemStorage
			(
				comp_id,
				stor_id,
				item_id,
				itst_cant,
				itst_cd
			)
			VALUES
			(
				@comp_id,
				@stor_id,
				@item_id,
				@itst_cant,
				GETDATE()
			)

		END


	ELSE
		BEGIN
			-- Actualiza la cantidad
			UPDATE	tbItemStorage
				SET		itst_cant	= (itst_cant + @itst_cant)
				WHERE	comp_id		= @comp_id
				AND		stor_id		= @stor_id
				AND		item_id		= @item_id
		END

END
GO


CREATE PROCEDURE [dbo].[spItemStoragePositions_CanTransferBeMade]
(
	@comp_id			INT,
	@item_id			INT,
	@storp_idOrigin		INT,
	@storp_idDestiny	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@item_id			INT,
				@storp_idOrigin		INT,
				@storp_idDestiny	INT
			SELECT
				@comp_id			= 1,
				@item_id			= 256,
				@storp_idOrigin		= 3,
				@storp_idDestiny	= 4
		*/
		-- ----------------------------------------------

		-- -----------------------------------------
		-- VARIABLES DE TRABAJO
		-- -----------------------------------------
		DECLARE
			@lImpDataIDOrigin	INT,
			@lImpDataIDDestiny	INT
		-- -----------------------------------------

		-- -----------------------------------------------------------------------------
		-- RECUPERO PARA LA POSICION ORIGEN Y ESE ITEM SI TIENE IMPDATAID
		-- -----------------------------------------------------------------------------
		SELECT
			@lImpDataIDOrigin		= tisp.impData_id
			FROM tbItemStoragePositions					AS tisp	WITH(NOLOCK)
			WHERE	tisp.comp_id	= @comp_id			AND
					tisp.storp_id	= @storp_idOrigin	AND
					tisp.item_id	= @item_id
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- RECUPERO PARA LA POS DESTINO Y ESE ITEM SI TIENE IMPDATAID
		-- -----------------------------------------------------------------------------
		SELECT
			@lImpDataIDDestiny		= tisp.impData_id
			FROM tbItemStoragePositions						AS tisp	WITH(NOLOCK)
			WHERE	tisp.comp_id	= @comp_id				AND
					tisp.storp_id	= @storp_idDestiny	AND
					tisp.item_id	= @item_id
		-- -----------------------------------------------------------------------------

		--==
			/*
			SET @lImpDataIDOrigin	= 1
			SET @lImpDataIDDestiny	= NULL
			SELECT @lImpDataIDOrigin,@lImpDataIDDestiny
			*/
		--==


		-- SI HAY DIFERENCIAS, NO LO DEJO
		--IF ISNULL(@lImpDataIDOrigin,0) <> ISNULL(@lImpDataIDDestiny,0) ESTO LO DEJO POR SI LAS DUDAS PARA PREG A MOS

		IF @lImpDataIDOrigin = @lImpDataIDDestiny
			BEGIN
				SELECT
					@lImpDataIDOrigin	[ImpDataIDOrigin],
					@lImpDataIDDestiny	[ImpDataIDDestiny],
					'True'				[CanTransferBeMade]
			END

		IF @lImpDataIDOrigin <> @lImpDataIDDestiny
			BEGIN
				SELECT
					@lImpDataIDOrigin	[ImpDataIDOrigin],
					@lImpDataIDDestiny	[ImpDataIDDestiny],
					'False' [CanTransferBeMade]
			END

		IF (@lImpDataIDOrigin IS NULL) AND (ISNULL(@lImpDataIDDestiny,0) > 0)
			BEGIN
				SELECT
					-1		[ImpDataIDOrigin],
					-1		[ImpDataIDDestiny],
					'False' [CanTransferBeMade]
			END

		IF (@lImpDataIDOrigin IS NULL) AND (@lImpDataIDDestiny IS NULL)
			BEGIN
				SELECT
					-1					[ImpDataIDOrigin],
					-1					[ImpDataIDDestiny],
					'True'				[CanTransferBeMade]
			END

		IF (ISNULL(@lImpDataIDOrigin,0) > 0) AND (@lImpDataIDDestiny IS NULL)
			BEGIN
				SELECT
					@lImpDataIDOrigin	[ImpDataIDOrigin],
					-1					[ImpDataIDDestiny],
					'True' [CanTransferBeMade]
			END


		/*
		IF @lImpDataIDOrigin <> @lImpDataIDDestiny
			BEGIN
				SELECT
					'False' [CanTransferBeMade]
			END
		ELSE
			BEGIN
				SELECT
					'True' [CanTransferBeMade]
			END
		*/
	END
GO


CREATE PROCEDURE [dbo].[spItemStoragePositions_GetAllImportDataAvailableByItem]
(
	@comp_id				INT,
	@item_id				INT,
	@qty					INT,
	@bolCantDispMayorOIgual	BIT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@item_id				INT,
				@qty					INT,
				@bolCantDispMayorOIgual	BIT
			SELECT
				@comp_id				= 1,
				@item_id				= 492,
				@qty					= 10,
				@bolCantDispMayorOIgual	= 'True'

			DROP TABLE #tmpAvailableImportdata
			DROP TABLE #tmpSUMCantidadAsignadaAPosiciones
			--DROP TABLE #tmpSaleOrderDetailImportDataGroupedByItem
		*/
		-- ---------------------------------------------------------

		-- -----------------------------------------------------------------------------------
		-- TABLA TEMPORAL DE CADA LOTE PARA ESE ITEM_ID
		-- -----------------------------------------------------------------------------------
		SELECT
			tia.impData_id													[impData_id],
			tia.impData_ActualQty											[CantDisponible],
			tia.impdata_LotNumber											[Lote],
			tia.item_id														[ItemID],
			CONVERT(VARCHAR, tia.impData_ExpirationDate, 103)				[impData_ExpirationDate]
			INTO #tmpAvailableImportdata
			FROM tbImportData												tia			WITH (NOLOCK)
			WHERE		tia.comp_id							= @comp_id		AND
						tia.item_id							= @item_id		AND
						tia.impData_ActualQty				> 0				AND
						tia.impData_id						IS NOT NULL		AND
						ISNULL(tia.impdata_LotNumber,'')	<> ''
			ORDER BY tia.impData_ExpirationDate, tia.impdata_Priority
		-- -----------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------
		-- SUM DE LOS ASIGNADOS DE ESOS LOTES EN POSICIONES
		-- -----------------------------------------------------------------------------------
		SELECT
			tisp.impData_id,
			SUM(tisp.itstp_cant)					[TotalAsignado]
			INTO #tmpSUMCantidadAsignadaAPosiciones
			FROM tbItemStoragePositions				AS tisp
				INNER JOIN #tmpAvailableImportdata	AS tmp
				ON tmp.impData_id	= tisp.impData_id
			WHERE tisp.comp_id		= @comp_id
			GROUP BY tisp.impData_id
		-- -----------------------------------------------------------------------------------



		-- -----------------------------------------------------------------------------------
		-- SUM DE LOS ASIGNADOS EN LA TABLA NUEVA
		-- -----------------------------------------------------------------------------------
			--SELECT
			--	tsodid.impData_id,
			--	ISNULL(SUM(ISNULL(tsod.sod_qty,0)),0)		[StockOnSODI]
			--INTO #tmpSaleOrderDetailImportDataGroupedByItem
			--FROM tbSaleOrderDetailImportData				AS tsodid	WITH(NOLOCK)
			--	INNER JOIN tbSaleOrderDetail				AS tsod	WITH(NOLOCK)
			--		ON	tsod.comp_id	= tsodid.comp_id	AND
			--			tsod.soh_id		= tsodid.soh_id		AND
			--			tsod.sod_id		= tsodid.sod_id
			--WHERE	tsodid.comp_id		= @comp_id AND
			--		tsod.item_id		= @item_id
			--GROUP BY tsodid.impData_id
		-- -----------------------------------------------------------------------------------

		IF @bolCantDispMayorOIgual = 'True'
			BEGIN
				--Y DESPUES HAGO UN LEFT JOIN CONTRA ESTA TABLA Y LA CANTIDAD PENDIENTE - LA CANTIDAD ASIGNADA EN POSICIONES
				--SEA MAYOR A LA CANTIDAD QUE YO QUIERO ASIGNAR A UN LOTE
				SELECT
					tmp.impData_id																				[ID],
					'Lote #: '					+ tmp.Lote  +
					' | Disponible: '			+ CONVERT(VARCHAR, (tmp.CantDisponible - ISNULL(tmp2.TotalAsignado,0)))	+
					' | Fecha de Vencimiento: ' + ISNULL(tmp.impData_ExpirationDate,'')							[DESC]
				FROM #tmpAvailableImportdata						tmp
					LEFT JOIN #tmpSUMCantidadAsignadaAPosiciones	tmp2
						ON tmp2.impData_id = tmp.impData_id
				--WHERE (tmp.CantDisponible - ISNULL(tmp2.TotalAsignado,0)) >= @qty
				WHERE (tmp.CantDisponible - ISNULL(tmp2.TotalAsignado,0)) > 0
				ORDER BY tmp.impData_ExpirationDate ASC
			END
		ELSE
			BEGIN
				--Y DESPUES HAGO UN LEFT JOIN CONTRA ESTA TABLA Y LA CANTIDAD PENDIENTE - LA CANTIDAD ASIGNADA EN POSICIONES
				--SEA MENOR A LA CANTIDAD QUE YO QUIERO ASIGNAR A UN LOTE
				SELECT
					tmp.impData_id																				[ID],
					'Lote #: '					+ tmp.Lote  +
					' | Disponible: '			+ CONVERT(VARCHAR, (tmp.CantDisponible - ISNULL(tmp2.TotalAsignado,0)))	+
					' | Fecha de Vencimiento: ' + ISNULL(tmp.impData_ExpirationDate,'')							[DESC]
				FROM #tmpAvailableImportdata						tmp
					LEFT JOIN #tmpSUMCantidadAsignadaAPosiciones	tmp2
						ON tmp2.impData_id = tmp.impData_id
				WHERE (tmp.CantDisponible - ISNULL(tmp2.TotalAsignado,0)) < @qty
				ORDER BY tmp.impData_ExpirationDate ASC
			END

	END
GO



-- Log
-- MOS 08-2024: @intPositionType, posiciones de cercania para PIcking y filtro de posiciones.
-- MOS 08-2024:  + (ISNULL(sp.storp_maxPalletQTY,0) * ti.item_upp)
-- MOS 08-2024: Se agrega la Clase de articulo


CREATE PROCEDURE [dbo].[spItemStoragePositions_getAvailableStockPositions]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@item_id			INT,
	@stor_id			INT,
	@qty				INT,
	@guid				UNIQUEIDENTIFIER,
	@impDataID			INT,
	@intPositionType	INT		-- 1 = PICKING / 2 = ESTIBA / -1 TODOS
)
AS



BEGIN

	SET NOCOUNT	ON

	-- -----------------------------------------------
	-- TESTING
	-- -----------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@prof_id	INT,
			@user_id	INT,
			@item_id	INT,
			@stor_id	INT,
			@qty		INT,
			@guid		UNIQUEIDENTIFIER,
			@impDataID			INT,
			@intPositionType	INT
		SELECT
			@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@prof_id	= 1,
			@user_id	= 1,
			@item_id	= 20096788,
			@stor_id	= 28,
			@qty		= 20,
			@guid		= 'FD3BA9CF-873F-441C-8181-06495712C5B2',
			@impDataID	= -1,
			@intPositionType = 2
	*/
	-- -----------------------------------------------






	-- -----------------------------------------------------------------------------------------------------------------------------
	-- Me debe traer las posiciones LIBRES para el item solicitado, en el deposito solicitado y la cantidad informada.
	-- Algunos videos de como es el WMS de SAP
	-- -----------------------------------------------------------------------------------------------------------------------------
	-- https://www.youtube.com/watch?v=TA6QmBVjZbU
	-- https://www.youtube.com/watch?v=ZmEVxidbT4E
	-- https://www.youtube.com/watch?v=6IWU5FEUaaY
	-- https://www.youtube.com/watch?v=TN8ThjJIjho   Operando SAP
	-- -----------------------------------------------------------------------------------------------------------------------------


	-- -----------------------------------------------------------------------------------------------------------------------------
	-- Ayudas generales de las tablas de WMS
	-- -----------------------------------------------------------------------------------------------------------------------------
	--SELECT 'Definición de Posiciones'
	--SELECT * FROM tbStoragePositions							AS tsp		-- Posiciones
	--SELECT * FROM tbStoragePositionsRelations					AS tspr		-- Relación entre POsiciones y Depósitos habilitados para cada una
	--SELECT * FROM tbItemStoragePositions4SaleOrderPreparation	AS tispsop	-- Posiciones HAbilitadas para la Preparación de Pedidos


	--SELECT 'Tablas Temporales para la Ubicación'
	--SELECT * FROM tbItemStoragePositionsTMP						AS tispt	-- Tabla Temporal para los Ingresos / Egresos de Stock a Posiciones

	--SELECT 'Tabla de Ubicación con las Cantidades por cada Posición'
	--SELECT * FROM tbItemStoragePositions						AS tisp		-- Posiciones , Deposito y cantidades asignadas

	--select * FROM tbItemStoragePositionsTransactions			AS tispt	-- Transacciones de Ingresos y Egresos a Posiciones

	--EXEC spBuscarTexto
	--	@SearchText = 'tbStoragePositionsRelations'
	-- -----------------------------------------------------------------------------------------------------------------------------

	DECLARE @item_upp AS integer = 0
	DECLARE @item_expLote AS BIT	= 'False'
	SELECT  @item_expLote			= ISNULL(ti.item_expLote,'False'),
			@item_upp				= ti.item_upp
		FROM tbitem	ti	WITH (NOLOCK)
		WHERE	comp_id = @comp_id AND
				item_id = @item_id


	IF (SELECT
			COUNT(*)
			FROM tbTempItemStorage_Positions AS ttisp	WITH(NOLOCK)
			WHERE ttisp.tmpguid = @guid) > 0
		BEGIN




			SELECT
				' ' [ ],
				sp.storp_nick,
				sp.storp_desc,
				ttisp.intqty					[assignedQTY],
				ttisp.intMaxQty,
				ttisp.intID							[ID]
				FROM tbTempItemStorage_Positions	AS ttisp WITH(NOLOCK)
				INNER JOIN tbStoragePositions		sp		WITH(NOLOCK)
					ON	sp.comp_id	= @comp_id		AND
						sp.storp_id = ttisp.storp_id
				INNER JOIN tbItem					AS ti	WITH(NOLOCK)
					ON	ti.comp_id	= @comp_id		AND
						ti.item_id	= ttisp.item_id
				WHERE ttisp.tmpguid = @guid
		END
	ELSE
		BEGIN

			-- MOS 08-2024: Busco que posicion es de Picking para este articulo y deposito para luego poder ordenar las posiciones de ingreso x posiciones de cercania.
			DECLARE @storp_id4Picking AS INT = NULL
			SELECT TOP 1  @storp_id4Picking = tisp.storp_id
				FROM tbItemStoragePositions		AS tisp	WITH (NOLOCK)
				INNER JOIN tbStoragePositions	AS tsp	WITH (NOLOCK)
					ON	tsp.comp_id		= tisp.comp_id AND
						tsp.storp_id	= tisp.storp_id
				WHERE	tisp.comp_id	= @comp_id	AND
						tisp.stor_id	= @stor_id	AND
						tisp.item_id	= @item_id	AND
						tsp.storp_is4Picking = 'True'	AND
						tisp.itstp_cant		 > 0




			DECLARE @tmpPositions TABLE(storp_id			INT PRIMARY KEY,
										preAssignedVolume	DECIMAL(19,4),
										preAssignedQTY		INT,
										preAssignedWeigth	DECIMAL(19,4),
										maxQTYAvailable		DECIMAL(19,4),
										priorityOrder		INT,
										hasItemIDAssigned	BIT,
										assignedQTY			DECIMAL(19,4),
										itemQTY				INT,
										itstp_lastInput		DATETIME,
										relatedPositionsOrder		INT NULL)



			-- --------------------------------------------------------------------------
			-- MOS 08-2024: Posiciones de CERCANIA
			-- 1-1 poner las posiciones disponibles en una temporasl para ese deposito (los que estan en esta tabla)
			-- --------------------------------------------------------------------------
			INSERT INTO @tmpPositions(	storp_id,
										preAssignedVolume,
										preAssignedQTY,
										preAssignedWeigth,
										maxQTYAvailable,
										priorityOrder,
										hasItemIDAssigned,
										assignedQTY,
										itemQTY,
										relatedPositionsOrder)
				SELECT					ipr.storp_id,
										0,
										0,
										0,
										0,
										0,
										'False',
										0,
										0,
										tspr.storpr_order4Input
					FROM tbStoragePositionsRelations 		AS ipr		WITH (NOLOCK)
					INNER JOIN tbStoragePositions			AS tsp		WITH (NOLOCK)
						ON	tsp.comp_id			= ipr.comp_id	AND
							tsp.storp_id		= ipr.storp_id
					INNER JOIN tbStoragePositionsRelated	AS tspr		WITH (NOLOCK)
						ON	tspr.comp_id = tsp.comp_id AND tspr.storp_id = tsp.storp_id
					INNER JOIN tbStoragePositionsRelated	AS tspr2	WITH (NOLOCK)
						ON	tspr2.comp_id		= tsp.comp_id	 AND
							tspr2.storp_id		= @storp_id4Picking
					INNER JOIN tbItem						AS ti		WITH (NOLOCK)
						ON	ti.comp_id			= @comp_id AND
							ti.item_id			= @item_id
					WHERE	@intPositionType IN (-1,2)			AND	-- Posiciones de cercania SOLO si es para TODOS o para Estiba
							ipr.comp_id			= @comp_id		AND
							ipr.stor_id			= @stor_id		AND
							ipr.storpr_disabled = 'False'		AND
							tsp.storp_is4Picking= 'False'		AND  -- MOS 08-2024: UNa pos de cercania es solo para cercania de pos de picking
							(
								tspr2.cat_id_Excluded IS NULL OR tspr2.cat_id_Excluded <> ti.cat_id
							)									AND
							(
								tspr2.subcat_id_Excluded IS NULL OR tspr2.subcat_id_Excluded <> ti.subcat_id
							)									AND
							(
								tspr2.ic_id_Excluded IS NULL OR tspr2.ic_id_Excluded <> ti.ic_id
							)
					ORDER BY tspr.storpr_order4Input
			-- --------------------------------------------------------------------------

			-- --------------------------------------------------------------------------
			-- 1-2 poner las posiciones disponibles en una temporasl para ese deposito (los que estan en esta tabla)
			-- --------------------------------------------------------------------------
			IF	( SELECT COUNT(*)
			  		FROM @tmpPositions
				) = 0
				BEGIN	-- MOS 08-2024: Esto era el x defecto, antes de las posiciones de cercania.  Ahora solo se ejecuta si NO se insertaron posiciones de cercania por no estar definidas o no tener espacio.

					-- OJOOOOO: NO PONER relatedPositionsOrder ya que en este caso debe quedar en NULL!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
					INSERT INTO @tmpPositions(	storp_id,
												preAssignedVolume,
												preAssignedQTY,
												preAssignedWeigth,
												maxQTYAvailable,
												priorityOrder,
												hasItemIDAssigned,
												assignedQTY,
												itemQTY)
						SELECT					ipr.storp_id,
												0,
												0,
												0,
												0,
												0,
												'False',
												0,
												0
							FROM tbStoragePositionsRelations ipr		WITH (NOLOCK)
							INNER JOIN tbStoragePositions AS tsp		WITH (NOLOCK)
								ON	tsp.comp_id			= ipr.comp_id	AND
									tsp.storp_id		= ipr.storp_id
							WHERE	ipr.comp_id			= @comp_id		AND
									ipr.stor_id			= @stor_id		AND
									ipr.storpr_disabled = 'False'		AND
									CASE
										WHEN @intPositionType = 1 AND tsp.storp_is4Picking		= 'True'	THEN 1
										WHEN @intPositionType = 2 AND tsp.storp_is4Picking		= 'False'	THEN 1
										WHEN @intPositionType = -1											THEN 1
										ELSE 0
									END = 1
									--(
									--	@bitAllAvailablePositions	= 'True'
									--		OR
									--	tsp.storp_is4Picking		= 'False'  				-- MOS: 08-2024  Saco las que son de Picking
									--)
				END
			-- --------------------------------------------------------------------------


			-- --------------------------------------------------------------------------
			-- MOS 07-2024
			-- 1.4- Borrar las que son de un expLote diferente y con exigen contol
			-- --------------------------------------------------------------------------
			IF @item_expLote = 'True'
				BEGIN
					;WITH ctePositionsCompleted3 AS (
					SELECT tp.storp_id
						FROM tbStoragePositions							AS sp		WITH (NOLOCK)
						INNER JOIN @tmpPositions						AS tp
							ON tp.storp_id		= sp.storp_id
						INNER JOIN tbItemStoragePositions				AS tisp		WITH (NOLOCK)
							ON	tisp.comp_id	= sp.comp_id	AND
								tisp.storp_id	= sp.storp_id
						INNER JOIN tbItem								AS ti		WITH (NOLOCK)
							ON	ti.comp_id		= @comp_id		AND
								ti.item_id		= tisp.item_id
						GROUP BY	tp.storp_id,
									sp.storp_maxUnitQTY,
									sp.storp_volume,
									tp.preAssignedVolume,
									tp.preAssignedQTY,
									tp.preAssignedWeigth,
									sp.storp_weight,
									tp.itemQTY,
									sp.storp_maxItemsQTY,
									tisp.itstp_cant,
									tisp.impData_id
						HAVING
								tisp.itstp_cant	 > 0				AND
								tisp.impData_id IS NOT NULL			AND
								tisp.impData_id <> @impDataID
													)


						DELETE		@tmpPositions
							FROM	@tmpPositions AS tp
							INNER JOIN ctePositionsCompleted3 cte
							ON tp.storp_id  = cte.storp_id

				END


			-- --------------------------------------------------------------------------
			-- 1.5- borrar las que NO tienen posibilidad de uso x sobre medidas
			-- --------------------------------------------------------------------------
			DELETE @tmpPositions
				FROM @tmpPositions tmp
				INNER JOIN tbStoragePositions				sp	WITH (NOLOCK)
					ON	sp.comp_id		= @comp_id AND
						sp.storp_id		= tmp.storp_id
				INNER JOIN tbItem						 AS ti	WITH (NOLOCK)
					ON	ti.comp_id		= @comp_id AND
						ti.item_id		= @item_id
				WHERE	ti.item_large	> sp.storp_large OR
						ti.item_higth	> sp.storp_higth OR
						ti.item_wide	> sp.storp_wide

		----==
		--SELECT * FROM @tmpPositions


			-- --------------------------------------------------------------------------
			-- 2- eliminar de esa temporal las posiciones completas  (ver volumen asignado en tbItemStoragePositionsTMP y en tbItemStoragePositions y compararlo con el volumen maximo asignable) + las que tienen asignados mas de lo indicado en maxUnitQty en la tabla tbStoragePositions o que alguna medida supere las medidas maximas en largo-alto-ancho
			-- --------------------------------------------------------------------------
			;WITH ctePositionsTMP AS (
				SELECT	SUM(ptmp.tmp_QTY * ti.item_volume)		[totalVolume],
						SUM(ptmp.tmp_QTY)						[totalQTY],
						SUM(ptmp.tmp_QTY * ti.item_weight)		[totalWeigth],
						ptmp.storp_id
					FROM @tmpPositions								AS tp
					INNER JOIN tbItemStoragePositionsTMP ptmp
						ON ptmp.storp_id		= tp.storp_id
					INNER JOIN tbItem								AS ti		WITH (NOLOCK)
						ON	ti.comp_id			= @comp_id AND
							ti.item_id			= @item_id
					WHERE ptmp.tmp_isDisabled	= 'False'
					GROUP BY ptmp.storp_id
									)
				-- Calcular la Cantidad Pre Asignada
				UPDATE @tmpPositions
					SET
						preAssignedVolume	= clr.totalVolume,
						preAssignedQTY		= clr.totalQTY,
						preAssignedWeigth	= clr.totalWeigth
					FROM @tmpPositions AS tp
					INNER JOIN ctePositionsTMP clr
						ON tp.storp_id = clr.storp_id

			-- Borro los que NO tienen mas lugar ni por estar asignados ni por estar en la temporal (Datos calculados en los dos CTE)
			;WITH ctePositionsCompleted AS (
			SELECT tp.storp_id	--,SUM(tisp.itstp_cant * ti.item_volume)	[totalVolumeAssigned]
				FROM tbStoragePositions							AS sp		WITH (NOLOCK)
				INNER JOIN @tmpPositions						AS tp
					ON tp.storp_id		= sp.storp_id
				INNER JOIN tbItemStoragePositions				AS tisp		WITH (NOLOCK)
					ON	tisp.comp_id	= sp.comp_id	AND
						tisp.storp_id	= sp.storp_id
				INNER JOIN tbItem								AS ti		WITH (NOLOCK)
					ON	ti.comp_id		= @comp_id		AND
						ti.item_id		= tisp.item_id
				GROUP BY	tp.storp_id,
							sp.storp_maxUnitQTY,
							sp.storp_volume,
							tp.preAssignedVolume,
							tp.preAssignedQTY,
							tp.preAssignedWeigth,
							sp.storp_weight
				HAVING	(SUM(tisp.itstp_cant * ti.item_volume) + tp.preAssignedVolume)	>= sp.storp_volume
							OR
						(SUM(tisp.itstp_cant)				   + tp.preAssignedQTY)		>= sp.storp_maxUnitQTY
							OR
						(SUM(tisp.itstp_cant * ti.item_weight) + tp.preAssignedWeigth)	>= sp.storp_weight
											)
				DELETE		@tmpPositions
					FROM	@tmpPositions AS tp
					INNER JOIN ctePositionsCompleted cte
					ON tp.storp_id  = cte.storp_id
			-- --------------------------------------------------------------------------



			-- --------------------------------------------------------------------------
			-- 2.5- eliminar de esa temporal las posiciones que tiene MAS de X Artículos diferentes asignados
			-- [itemQTY] es la cantidad de articulos diferentes asignados a la temporal
			-- --------------------------------------------------------------------------
			;WITH ctePositionsTMP2 AS (
										SELECT	COUNT(DISTINCT ptmp.item_id)			[itemQTY],
												ptmp.storp_id
											FROM @tmpPositions								AS tp
											INNER JOIN tbItemStoragePositionsTMP ptmp
												ON ptmp.storp_id		= tp.storp_id
											INNER JOIN tbItem								AS ti		WITH (NOLOCK)
												ON	ti.comp_id			= @comp_id	AND
													ti.item_id			= @item_id
											WHERE ptmp.tmp_isDisabled	= 'False'	AND
													ptmp.tmp_QTY			> 0
											GROUP BY ptmp.storp_id--,ptmp.item_id
									)
				-- Calcular la Cantidad de articulos DIFERENTES que tiene cada posicion actualmente asignados.
				UPDATE @tmpPositions
					SET itemQTY = clr.itemQTY
					FROM @tmpPositions AS tp
					INNER JOIN ctePositionsTMP2 clr
						ON tp.storp_id = clr.storp_id
					--GROUP BY clr.storp_id

			-- 2.6 Borro los que ya tienen asignados X cantidad de items o articulos DIFERENTES a la definida como máximo por cada posicion. ( sumados los que tambien estan en la temporal, ya que no se si van a estar o no.  OJO, puede ser que en la temporal sea el mismo articulo o no, se asume como riesgo o error )
			-- COUNT(DISTINCT tisp.item_id) es la cantidad de articulos diferentes asignados a la posicion.
			;WITH ctePositionsCompleted2 AS (
												SELECT tp.storp_id
													FROM tbStoragePositions							AS sp		WITH (NOLOCK)
													INNER JOIN @tmpPositions						AS tp
														ON tp.storp_id		= sp.storp_id
													INNER JOIN tbItemStoragePositions				AS tisp		WITH (NOLOCK)
														ON	tisp.comp_id	= sp.comp_id	AND
															tisp.storp_id	= sp.storp_id
													INNER JOIN tbItem								AS ti		WITH (NOLOCK)
														ON	ti.comp_id		= @comp_id		AND
															ti.item_id		= tisp.item_id
													WHERE	tisp.item_id   <> @item_id		-- MOS 09-2024: Para que los que son a borrar sean DIFERENTES a mi articulo a ubicar
													GROUP BY	tp.storp_id,
																sp.storp_maxUnitQTY,
																sp.storp_volume,
																tp.preAssignedVolume,
																tp.preAssignedQTY,
																tp.preAssignedWeigth,
																sp.storp_weight,
																tp.itemQTY,
																sp.storp_maxItemsQTY,
																tisp.itstp_cant
													HAVING	sp.storp_maxItemsQTY						> 0						AND
															tisp.itstp_cant								> 0						AND
															(COUNT(DISTINCT tisp.item_id) + tp.itemQTY)	>= sp.storp_maxItemsQTY			-- MOS 09-2024: Es >= ya que esta excluido el artoculo a ubicar

											)


				DELETE		@tmpPositions
					FROM	@tmpPositions AS tp
					INNER JOIN ctePositionsCompleted2 cte
					ON tp.storp_id  = cte.storp_id


			-- --------------------------------------------------------------------------




			-- --------------------------------------------------------------------------
			-- 3- ordenar 1ro las que ya tienen stock de ese articulo y ordenar luego x prioridad de entrada
			-- --------------------------------------------------------------------------
			UPDATE @tmpPositions
				SET	priorityOrder = sp.storp_priority4Input
				FROM @tmpPositions tmp
				INNER JOIN tbStoragePositions sp	WITH (NOLOCK)
					ON sp.storp_id = tmp.storp_id





			UPDATE @tmpPositions
				SET hasItemIDAssigned	= 'True',
					itstp_lastInput		= sp.itstp_lastInput		-- Para luego poder traer 1ro las de este item que se ingresaron la ULTIMA vez y no se mezclen viejos ingresos con nuevos ingresos
				FROM @tmpPositions tmp
				INNER JOIN tbItemStoragePositions sp	WITH (NOLOCK)
					ON  sp.comp_id		= @comp_id		AND
						sp.storp_id		= tmp.storp_id	AND
						sp.stor_id		= @stor_id		AND
						sp.item_id		= @item_id		AND
						sp.itstp_cant	> 0

			UPDATE @tmpPositions
				SET hasItemIDAssigned	= 'True',
					itstp_lastInput		= GETDATE()					-- Asi las que AUN no ingresaron a una posicion FISICA, están con fecha de HOY y no con fecha vieja.
				FROM @tmpPositions tmp
				INNER JOIN tbItemStoragePositionsTMP sp	WITH (NOLOCK)
					ON  sp.comp_id		= @comp_id		AND
						sp.storp_id		= tmp.storp_id	AND
						sp.stor_id		= @stor_id		AND
						sp.item_id		= @item_id		AND
						sp.tmp_QTY		> 0				AND
						sp.tmp_isDisabled = 'False'
			-- --------------------------------------------------------------------------


			-- --------------------------------------------------------------------------
			-- 3.1: MOS 06-2023:  Ordenar por Prioridad de Articulos para esa posicion actualizando, si esta en la tabla el articulo, la prioridad en NEGATIVO como (99999999 - la prioridad) * -1
			-- --------------------------------------------------------------------------
			DECLARE @intSubcat_Id	AS INT
			DECLARE @ic_id			AS INT
			SELECT  @intsubcat_Id	= subcat_id,
					@ic_id			= ti.ic_id
				FROM tbItem			AS ti	WITH (NOLOCK)
				WHERE	ti.comp_id = @comp_id AND
						ti.item_id = @item_id
			UPDATE @tmpPositions
				SET	priorityOrder = sp.storp_priority4Input
				FROM @tmpPositions tmp
				INNER JOIN tbStoragePositionsByItems AS  sp	WITH (NOLOCK)
					ON	sp.comp_id	= @comp_id							AND
						sp.storp_id = tmp.storp_id						AND
						sp.storpr_mustExclude	= 'False'				AND
						(sp.stor_id = @stor_id OR sp.stor_id IS NULL)	AND
						(
					   		sp.subcat_id		= @intSubcat_Id
					   		OR
					   		sp.item_id			= @item_id
					   		OR
					   		sp.ic_id			= @ic_id		-- MOS 08-2024: Se agrega la Clase de articulo
						)
			DELETE  @tmpPositions
				FROM @tmpPositions tmp
				INNER JOIN tbStoragePositionsByItems AS  sp	WITH (NOLOCK)
					ON	sp.comp_id	= @comp_id							AND
						sp.storp_id = tmp.storp_id						AND
						(sp.stor_id = @stor_id OR sp.stor_id IS NULL)	AND
						sp.storpr_mustExclude	= 'True' AND
						(
					   		sp.subcat_id		= @intSubcat_Id
					   		OR
					   		sp.item_id			= @item_id
					   		OR
					   		sp.ic_id			= @ic_id		-- MOS 08-2024: Se agrega la Clase de articulo
						)
			-- --------------------------------------------------------------------------


			-- --------------------------------------------------------------------------
			-- MOS 08-2024: Orden de Posiciones de CERCANIA
			-- --------------------------------------------------------------------------
			UPDATE @tmpPositions
				SET	priorityOrder = tmp.relatedPositionsOrder
				FROM @tmpPositions tmp
				WHERE tmp.relatedPositionsOrder IS NOT NULL
			-- --------------------------------------------------------------------------



			-- --------------------------------------------------------------------------
			-- 6- Sugerir x prioridad antes detallada TODAS las posiciones permitidas.  En cada posición se deberá informar el MAXIMO de unidades a asignar del articulo requerido.
			-- Aca tengo todas las posiciones disponibles en ORDEN con su cantidad, volumen y peso YA ASIGNADOS
			-- Debo recorrerlos con un cursor preasignando cantidades del artículo a las posiciones disponibes
			-- --------------------------------------------------------------------------
			DECLARE @curStorp_id				AS INT
			DECLARE @curPreAssignedVolume	AS DECIMAL(19,4)
			DECLARE @curPreAssignedQTY		AS DECIMAL(19,4)
			DECLARE @curPreAssignedWeigth	AS DECIMAL(19,4)
			DECLARE @curMaxQTYAvailable		AS DECIMAL(19,4)
			DECLARE @curPriorityOrder		AS INT
			DECLARE @curHasItemIDAssigned	AS BIT
			DECLARE @curItem_weight			AS DECIMAL(19,4)
			DECLARE @curItem_volume			AS DECIMAL(19,4)
			DECLARE @curItem_withDecimal	AS BIT
			DECLARE @curStorp_weight		AS DECIMAL(19,4)
			DECLARE @curStorp_volume		AS DECIMAL(19,4)
			DECLARE @curStorp_maxUnitQTY	AS DECIMAL(19,4)
			DECLARE @curstorp_maxPalletQTY  AS DECIMAL(19,4)

			DECLARE @decQTY4Assign			AS DECIMAL(19,4) = @qty
			DECLARE @decMAXWeigthAvailable	AS DECIMAL(19,4) = 0
			DECLARE @decMAXVolumeAvailable	AS DECIMAL(19,4) = 0
			DECLARE @decMAXQtyAvailable		AS DECIMAL(19,4) = 0
			DECLARE @decMAXQty4ThisPosition AS DECIMAL(19,4) = 0
			DECLARE @decMAXQtyAvailable4Item
											AS DECIMAL(19,4) = 0


		----==
		--SELECT * FROM @tmpPositions


			DECLARE curPOSICIONES CURSOR LOCAL FAST_FORWARD FOR
				SELECT	tp.storp_id,
						tp.preAssignedVolume,
						tp.preAssignedQTY,
						tp.preAssignedWeigth,
						tp.maxQTYAvailable,
						tp.priorityOrder,
						tp.hasItemIDAssigned,
						ti.item_weight,
						ti.item_volume,
						ISNULL(sp.storp_weight,0),
						ISNULL(sp.storp_volume,0),
						ISNULL(sp.storp_maxUnitQTY,0),
						ti.item_withDecimal,
						ISNULL(sp.storp_maxPalletQTY,0)
					FROM @tmpPositions AS tp
					INNER JOIN tbStoragePositions sp WITH (NOLOCK)
						ON	sp.comp_id	= @comp_id AND
							sp.storp_id = tp.storp_id
					INNER JOIN tbItem AS ti	WITH (NOLOCK)
						ON	ti.comp_id	= @comp_id AND
							ti.item_id	= @item_id
					ORDER BY
							CASE 	-- Primero las Posiciones que YA tienen ese artículo asignado para ese depósito
								WHEN  tp.hasItemIDAssigned = 'True' AND tp.itstp_lastInput IS NOT NULL  THEN	-9999999 + DATEDIFF(DAY,tp.itstp_lastInput,GETDATE()) 		-- Primero las que tengan ese articulo hace POCO tiempo y luego las q lo tengan hace MUCHO tiempo
								WHEN  tp.hasItemIDAssigned = 'True' AND tp.itstp_lastInput IS NULL		THEN	-1
								WHEN  tp.hasItemIDAssigned = 'True'										THEN	0
								ELSE																			1
							END,
							tp.priorityOrder
			OPEN curPOSICIONES

			FETCH NEXT FROM curPOSICIONES	INTO
												@curStorp_id,
												@curPreAssignedVolume,
												@curPreAssignedQTY,
												@curPreAssignedWeigth,
												@curMaxQTYAvailable,
												@curPriorityOrder,
												@curHasItemIDAssigned,
												@curItem_weight,
												@curItem_volume,
												@curStorp_weight,
												@curStorp_volume,
												@curStorp_maxUnitQTY,
												@curItem_withDecimal,
												@curstorp_maxPalletQTY

			WHILE @@FETCH_STATUS = 0
				BEGIN

					-- Asigno los DISPONIBLES de esta Posición
					SET @decMAXVolumeAvailable	= @curStorp_volume		- @curPreAssignedVolume
					SET @decMAXWeigthAvailable	= @curStorp_weight		- @curPreAssignedWeigth
					SET @decMAXQtyAvailable		= @curStorp_maxUnitQTY  - @curPreAssignedQTY

					SET @decMAXQty4ThisPosition = @decQTY4Assign  -- Arranco suponiendo q entra todo ! :-)


					-- Calculo la MAXIMA CANTIDAD de este item DISPONIBLE para poner en este casillero con su disponibilidad actual.
					SET @decMAXQtyAvailable4Item = 0
					SET @decMAXQtyAvailable4Item = @decMAXVolumeAvailable / dbo.fnNoZDiv(@curItem_volume)
					SET @decMAXQtyAvailable4Item = dbo.fnGetMinimumValue (  @decMAXWeigthAvailable / dbo.fnNoZDiv(@curItem_weight)      ,
																			@decMAXQtyAvailable4Item)
					SET @decMAXQtyAvailable4Item = dbo.fnGetMinimumValue (  @decMAXQtyAvailable     ,
																			@decMAXQtyAvailable4Item)
					-- ------------------------------------------------------------------------------------------------------------

					-- Recorto a la maxima cantidad que me permite por VOLUMEN
					IF ( @decMAXVolumeAvailable / dbo.fnNoZDiv(@curItem_volume) ) < @decMAXQty4ThisPosition
						BEGIN
							IF @curItem_withDecimal = 'True'
								BEGIN
									SET @decMAXQty4ThisPosition = ( @decMAXVolumeAvailable / dbo.fnNoZDiv(@curItem_volume) )
								END
							ELSE
								BEGIN
									SET @decMAXQty4ThisPosition = CONVERT(INT, ( @decMAXVolumeAvailable / dbo.fnNoZDiv(@curItem_volume) ))	-- Si NO tiene decimales saco solo la parte entera
								END
						END

					-- Recorto a la maxima cantidad que me permite por PESO
					IF ( @decMAXWeigthAvailable / dbo.fnNoZDiv(@curItem_weight) ) < @decMAXQty4ThisPosition
						BEGIN
							IF @curItem_withDecimal = 'True'
								BEGIN
									SET @decMAXQty4ThisPosition = ( @decMAXWeigthAvailable / dbo.fnNoZDiv(@curItem_weight) )
								END
							ELSE
								BEGIN
									SET @decMAXQty4ThisPosition = CONVERT(INT, ( @decMAXWeigthAvailable / dbo.fnNoZDiv(@curItem_weight) ))	-- Si NO tiene decimales saco solo la parte entera
								END
						END


					-- MOS 09-2024: como MAXIMO debe permitir la cantidad de pallets maximo
					IF @curstorp_maxPalletQTY > 0
						BEGIN
							IF @decMAXQtyAvailable > @curstorp_maxPalletQTY * @item_upp
								BEGIN
									SET @decMAXQtyAvailable = @curstorp_maxPalletQTY * @item_upp
								END
						END


					-- MOS 09-2024: Falta sacar la cantidad ACTUALMENTE ASIGNADA
					SELECT @decMAXQtyAvailable = @decMAXQtyAvailable - ISNULL(SUM(tisp.itstp_cant),0)
						FROM tbItemStoragePositions AS tisp	WITH (NOLOCK)
						WHERE	tisp.comp_id	= @comp_id		AND
								tisp.item_id	= @item_id		AND
								tisp.storp_id	= @curStorp_id

					-- MOS 09-2024: Falta sacar la cantidad ACTUALMENTE ASIGNADA en la TEMPORAL
					SELECT @decMAXQtyAvailable = @decMAXQtyAvailable - ISNULL(SUM(tisp.tmp_QTY),0)
						FROM tbItemStoragePositionsTMP AS tisp	WITH (NOLOCK)
						WHERE	tisp.comp_id	= @comp_id		AND
								tisp.item_id	= @item_id		AND
								tisp.storp_id	= @curStorp_id





					-- Recorto a la maxima cantidad que me permite por Cantidad Disponible
					IF @decMAXQtyAvailable < @decMAXQty4ThisPosition
						BEGIN
							IF @curItem_withDecimal = 'True'
								BEGIN
									SET @decMAXQty4ThisPosition = @decMAXQtyAvailable
								END
							ELSE
								BEGIN
									SET @decMAXQty4ThisPosition = CONVERT(INT, @decMAXQtyAvailable)	-- Si NO tiene decimales saco solo la parte entera
								END
						END


					SET @decQTY4Assign	= @decQTY4Assign - @decMAXQty4ThisPosition		-- Dejo como PENDIENTE  a lo PENDIENTE menos lo Asignado

					UPDATE @tmpPositions
						SET	assignedQTY		= @decMAXQty4ThisPosition,
							maxQTYAvailable = @decMAXQtyAvailable4Item
						WHERE storp_id	= @curStorp_id



					FETCH NEXT FROM curPOSICIONES	INTO
														@curStorp_id,
														@curPreAssignedVolume,
														@curPreAssignedQTY,
														@curPreAssignedWeigth,
														@curMaxQTYAvailable,
														@curPriorityOrder,
														@curHasItemIDAssigned,
														@curItem_weight,
														@curItem_volume,
														@curStorp_weight,
														@curStorp_volume,
														@curStorp_maxUnitQTY,
														@curItem_withDecimal,
														@curstorp_maxPalletQTY
				END
			CLOSE		curPOSICIONES
			DEALLOCATE	curPOSICIONES

			-- MOS 09-2024: Sacar posiciones en NEgativo
			DELETE FROM @tmpPositions WHERE assignedQTY < 0

--==
--SELECT * FROM @tmpPositions



			-- Finalmente retorno lo precalculado

			--CON MODIFICACIONES DE SL PARA LA GRILLA
			INSERT INTO tbTempItemStorage_Positions
			(
				-- intID -- this column value is auto-generated
				tmpguid,
				item_id,
				stor_id,
				storp_id,
				intqty,
				intMaxQty,
				intOrder
			)
			SELECT
				@guid,
				@item_id,
				@stor_id,
				sp.storp_id,
				tp.assignedQTY,
				maxQTYAvailable		,
				ROW_NUMBER() OVER (
									ORDER BY
									CASE tp.hasItemIDAssigned	-- Primero las Posiciones que YA tienen ese artículo asignado para ese depósito
										WHEN 'True' THEN	0
										ELSE				1
									END,
									tp.priorityOrder
									)
				FROM @tmpPositions					AS tp
				INNER JOIN tbStoragePositions			sp	WITH (NOLOCK)
					ON	sp.comp_id	= @comp_id		AND
						sp.storp_id = tp.storp_id
				INNER JOIN tbItem					AS	ti	WITH (NOLOCK)
					ON	ti.comp_id	= @comp_id		AND
						ti.item_id	= @item_id
				ORDER BY
						CASE tp.hasItemIDAssigned	-- Primero las Posiciones que YA tienen ese artículo asignado para ese depósito
							WHEN 'True' THEN	0
							ELSE				1
						END,
						tp.priorityOrder



			-- --------------------------------------------------------------------------
			-- 7. Eliminar de las posiciones VACIAS y dejar las 1ras 10 disponibles.
			-- Si alguien solicita mas cantidad poner la conf a nivel de compañia.
			-- --------------------------------------------------------------------------
			DECLARE		@tmpPositions4Delete TABLE (storp_id INT PRIMARY KEY,intOrder INT)
			INSERT INTO @tmpPositions4Delete
			(
				storp_id,
				intOrder
			)
			SELECT	ee.storp_id,
					ROW_NUMBER() OVER (
										ORDER BY ee.intOrder
										)
				FROM tbTempItemStorage_Positions ee WITH (NOLOCK)
				WHERE	ee.tmpguid	= @guid AND
						ee.intqty	= 0
				ORDER BY ee.intOrder

			DELETE   tbTempItemStorage_Positions
				FROM tbTempItemStorage_Positions tmp	WITH (NOLOCK)
				INNER JOIN @tmpPositions4Delete tmp2
					ON tmp2.storp_id	= tmp.storp_id
				WHERE	tmp.tmpguid		= @guid AND
						tmp.intqty		= 0		AND
						tmp2.intOrder   > 10
			-- --------------------------------------------------------------------------


			SELECT
				' ' [ ],
				sp.storp_nick,
				sp.storp_desc,
				ttisp.intqty			[assignedQTY],
				ttisp.intMaxQty,
				ttisp.intID [ID]
				FROM tbTempItemStorage_Positions	AS ttisp	WITH(NOLOCK)
				INNER JOIN tbStoragePositions		AS sp		WITH(NOLOCK)
					ON	sp.comp_id	= @comp_id		AND
						sp.storp_id = ttisp.storp_id
				INNER JOIN tbItem					AS ti		WITH(NOLOCK)
					ON	ti.comp_id	= @comp_id		AND
						ti.item_id	= ttisp.item_id
				WHERE ttisp.tmpguid = @guid
				ORDER BY ttisp.intOrder




	END


END
GO



-- Log
-- MOS 06-2024: Visto con SL
-- MOS 07-2024: Si el item es de LOTE, que ponga ordenado x vencimiento.
-- MOS 08-2024: Da prioridad a Posiciones de Picking


CREATE PROCEDURE [dbo].[spItemStoragePositions_getAvailableStockPositions_4Output]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@user_id		INT,
	@item_id		INT,
	@stor_id		INT,
	@qty			INT,
	@col_id			INT,
	@guid			UNIQUEIDENTIFIER,
	@soh_uniqueID	INT	,
	@soh_id			INT
)
AS

	BEGIN
		SET NOCOUNT	ON
		-- -----------------------------------------------
		-- TESTING
		-- -----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT,
				@item_id	INT,
				@stor_id	INT,
				@qty		INT,
				@guid		UNIQUEIDENTIFIER,
				@col_id		INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 1,
				@bra_id		= 1,
				@prof_id	= 1,
				@user_id	= 1,
				@item_id	= 16084,
				@stor_id	= 807,
				@qty		= 1,
				@guid		= 'FD3BA9CF-873F-441C-8181-06495712C5B2',
				@col_id		= -1
		*/
		-- -----------------------------------------------

		-- -----------------------------------------------------------------------------------------------------------------------------
		-- Me debe traer las posiciones LIBRES para el item solicitado, en el deposito solicitado y la cantidad informada.
		-- Algunos videos de como es el WMS de SAP
		-- -----------------------------------------------------------------------------------------------------------------------------
		-- https://www.youtube.com/watch?v=TA6QmBVjZbU
		-- https://www.youtube.com/watch?v=ZmEVxidbT4E
		-- https://www.youtube.com/watch?v=6IWU5FEUaaY
		-- https://www.youtube.com/watch?v=TN8ThjJIjho   Operando SAP
		-- -----------------------------------------------------------------------------------------------------------------------------



		-- -----------------------------------------------------------------------------------------------------------------------------
		-- Ayudas generales de las tablas de WMS
		-- -----------------------------------------------------------------------------------------------------------------------------
		--SELECT 'Definición de Posiciones'
		--SELECT * FROM tbStoragePositions							AS tsp		-- Posiciones
		--SELECT * FROM tbStoragePositionsRelations					AS tspr		-- Relación entre POsiciones y Depósitos habilitados para cada una
		--SELECT * FROM tbItemStoragePositions4SaleOrderPreparation	AS tispsop	-- Posiciones HAbilitadas para la Preparación de Pedidos


		--SELECT 'Tablas Temporales para la Ubicación'
		--SELECT * FROM tbItemStoragePositionsTMP						AS tispt	-- Tabla Temporal para los Ingresos / Egresos de Stock a Posiciones

		--SELECT 'Tabla de Ubicación con las Cantidades por cada Posición'
		--SELECT * FROM tbItemStoragePositions						AS tisp		-- Posiciones , Deposito y cantidades asignadas

		--select * FROM tbItemStoragePositionsTransactions			AS tispt	-- Transacciones de Ingresos y Egresos a Posiciones

		--EXEC spBuscarTexto
		--	@SearchText = 'tbStoragePositionsRelations'
		-- -----------------------------------------------------------------------------------------------------------------------------



		--SELECT * FROM tbSaleOrderCollectHeader AS tsoch
		--SELECT * FROM tbSaleOrderCollectDetail AS tsoch
		--SELECT * FROM tbStoragePositions AS tsp


		IF @col_id = -1 SET @col_id = NULL	-- MOS 06-2024: Visto con SL


		DECLARE @item_expLote AS BIT = 'False'
		SELECT  @item_expLote = ISNULL(item_expLote,'False')
			FROM tbitem WITH (NOLOCK)
			WHERE	comp_id = @comp_id AND
					item_id = @item_id



		IF (SELECT
				COUNT(*)
				FROM tbTempItemStorage_Positions_Output AS ttispo WITH(NOLOCK)
				WHERE ttispo.tmpguid = @guid) > 0
			BEGIN
				SELECT
					' '											[ ],
					ti.item_code,
					ti.item_desc,
					ts.stor_desc,
					tsp.storp_nick,
					ttispo.initQty								[assignedQTY],
					tsoch.col_desc,
					ttispo.intID								[ID]
					FROM tbTempItemStorage_Positions_Output	AS ttispo	WITH (NOLOCK)
					INNER JOIN tbItem						AS ti		WITH(NOLOCK)
						ON	ti.comp_id		= @comp_id		AND
							ti.item_id		= ttispo.item_id
					INNER JOIN tbStorage					AS ts		WITH(NOLOCK)
						ON  ts.comp_id		= @comp_id		AND
							ts.stor_id		= ttispo.stor_id
					INNER JOIN tbStoragePositions			AS tsp		WITH(NOLOCK)
						ON	tsp.comp_id		= @comp_id		AND
							tsp.storp_id	= ttispo.storp_id
					LEFT JOIN tbSaleOrderCollectHeader		AS tsoch	WITH(NOLOCK)
						ON	tsoch.comp_id	= ttispo.col_id	AND
							tsoch.col_id	= ttispo.col_id
					WHERE ttispo.tmpGuid		= @guid
			END
		ELSE
			BEGIN
				-- 1ro pongo en una tabla TODO lo que debo salir a colectar. SOLO va a traer de esta colecta SI NO está cerrada ni ya se colectó para WMS
				DECLARE		@tmpItems4Collect TABLE(item_id INT, stor_id INT, qty DECIMAL(19,4))

				-- COLECTA
				INSERT INTO @tmpItems4Collect(item_id, stor_id, qty)
					SELECT	tsod.item_id,
							tsod.stor_id,
							SUM(tsod.sod_qty)
						FROM tbSaleOrderCollectDetail			AS tsocd		WITH (NOLOCK)
						INNER JOIN tbSaleOrderCollectHeader		AS tsoch		WITH (NOLOCK)
							ON	tsoch.comp_id		= @comp_id AND
								tsoch.col_id		= @col_id
						INNER JOIN tbSaleOrderDetail			AS tsod			WITH (NOLOCK)
							ON	tsod.comp_id				= tsocd.comp_id		AND
								tsod.bra_id					= tsocd.soh_bra_id	AND
								tsod.soh_id					= tsocd.soh_id
						WHERE	tsocd.comp_id				= @comp_id			AND
								tsocd.col_id				= @col_id			AND
								tsoch.col_closed			= 'False'			AND
								tsoch.col_isCollected4WMS	= 'False'
						GROUP BY tsod.item_id,tsod.stor_id


				-- PEDIDO
				INSERT INTO @tmpItems4Collect(item_id, stor_id, qty)
					SELECT	tsod.item_id,
							tsod.stor_id,
							SUM(tsod.sod_qty)
					FROM	tbSaleOrderHeader								AS tsoh			WITH(NOLOCK)
						INNER JOIN tbSaleOrderDetail						AS tsod			WITH (NOLOCK)
							ON	tsod.comp_id			= tsoh.comp_id		AND
								tsod.bra_id				= tsoh.bra_id		AND
								tsod.soh_id				= tsoh.soh_id
						WHERE	tsoh.comp_id			= @comp_id			AND
								(
									tsoh.soh_uniqueID		= @soh_uniqueID
									OR
									(tsoh.bra_id = @bra_id AND tsoh.soh_id = @soh_id)
								)
						GROUP BY tsod.item_id,tsod.stor_id


				-- Si aparte mandaron un unico item, lo agrega
				IF @item_id > 0 AND @stor_id > 0
					BEGIN
						IF EXISTS(	SELECT TOP 1 1
		          						FROM @tmpItems4Collect AS tic
		          						WHERE	tic.item_id = @item_id AND
		          								tic.stor_id = @stor_id
								 )
							BEGIN
								UPDATE @tmpItems4Collect
									SET	qty = qty + @qty
									WHERE	item_id = @item_id AND
											stor_id = @stor_id

							END
						ELSE
							BEGIN
								INSERT INTO @tmpItems4Collect
								(
									item_id,
									stor_id,
									qty
								)
								VALUES
								(
									@item_id,
									@stor_id,
									@qty
								)
							END

					END



				-- 3- debo buscar en una temporal en que posicion debo ir a sacar la mercaderia con du id de posicion y cantidad parcial.
				DECLARE		@tmpPositionsWithStockAssigned TABLE(storp_id INT, stor_id INT  ,item_id INT, qty DECIMAL(19,4),priority4Out INT,storp_collectionOrder INT,itstp_lastInput DATETIME, impData_ExpirationDate DATETIME, impdata_id INT, is4Picking BIT )
				INSERT INTO @tmpPositionsWithStockAssigned
					(
						storp_id,
						stor_id,
						item_id,
						qty,
						priority4Out,
						storp_collectionOrder,
						itstp_lastInput,
						impData_ExpirationDate,
						impdata_id,
						is4Picking
					)
						SELECT	tisp.storp_id,
								tisp.stor_id,
								tisp.item_id,
								tisp.itstp_cant,
								tsp.storp_priority4Output,
								tsp.storp_collectionOrder,
								tisp.itstp_lastOutput,
								ISNULL(tid.impData_ExpirationDate,tisp.itstp_lastOutput),
								tisp.impData_id,
								ISNULL(tsp.storp_is4Picking,'False')
							FROM	tbItemStoragePositions	AS tisp		WITH (NOLOCK)
							INNER JOIN tbStoragePositions	AS tsp		WITH (NOLOCK)
								ON	tsp.comp_id		= tisp.comp_id AND
									tsp.storp_id	= tisp.storp_id
							INNER JOIN @tmpItems4Collect	AS tic
								ON	tic.stor_id		= tisp.stor_id AND
									tic.item_id		= tisp.item_id
							LEFT JOIN tbImportData			AS tid		WITH (NOLOCK)	-- MOS 07-2024, para que ordene x fecha de vto si el item es de LOTE
								ON	tid.comp_id		= tisp.comp_id			AND
									tid.impData_id	= tisp.impData_id


				-- En la ultima temporal debo poner todas las posiciones que voy a sacar la merc. con la qty que saco de cada una y de que deposito
				-- MOS 06-2023: Uso dos cursores anidados, se que es una mierda pero estoy recontra cansado y no se me ocurre algo mejor...

				DECLARE @tmpPositions4Output TABLE (item_id INT, storp_id INT, stor_id INT, qty DECIMAL(19,4),storp_collectionOrder INT,itstp_lastInput DATETIME)
				DECLARE @curItem_Id			AS INT
				DECLARE @curStor_id			AS INT
				DECLARE @curQty				AS DECIMAL(19,4)
				DECLARE @curStorp_id		AS INT
				DECLARE @curStorpQTY		AS DECIMAL(19,4)
				DECLARE @curCollectionOrder AS INT
				DECLARE curITEMS CURSOR LOCAL FAST_FORWARD FOR
					SELECT	tic.item_id,
							tic.stor_id,
							tic.qty
						FROM @tmpItems4Collect AS tic

					OPEN curITEMS
					--curPOSICIONES
					FETCH NEXT FROM curITEMS	INTO	@curItem_Id,
														@curstor_id,
														@curQty

					WHILE @@FETCH_STATUS = 0	-- Recorro cada articulo de la colecta
						BEGIN

							DECLARE @decPendingQTY AS DECIMAL(19,4) = @curQty

							-- Debo ir sacando de las posiciones correspondientes
							DECLARE curITEM_POSITIONS CURSOR LOCAL FAST_FORWARD FOR
								SELECT tpwsa.storp_id, tpwsa.qty,tpwsa.storp_collectionOrder
									FROM @tmpPositionsWithStockAssigned AS tpwsa
									WHERE	tpwsa.item_id = @curItem_Id AND
											tpwsa.stor_id = @curStor_id
									ORDER BY
												CASE	-- MOS 08-2024: Da prioridad a Posiciones de Picking
													WHEN tpwsa.is4Picking = 'True' THEN 1
													ELSE								2
												END,
												tpwsa.priority4Out,
												CASE	-- MOS 07-2024: Si el item es de LOTE, que ponga ordenado x vencimiento.
													WHEN @item_expLote = 'False'		THEN GETDATE()
													ELSE									 tpwsa.impData_ExpirationDate
												END,
												DATEDIFF(DAY,ISNULL(tpwsa.itstp_lastInput,GETDATE()),GETDATE()) DESC	-- para que saque PRIMERO a los mas VIEJOS


							OPEN		curITEM_POSITIONS

							FETCH NEXT FROM curITEM_POSITIONS INTO	@curStorp_id,
																	@curStorpQTY,
																	@curCollectionOrder
							WHILE	@@FETCH_STATUS = 0	AND
									@decPendingQTY > 0
								BEGIN

									IF @curStorpQTY >= @decPendingQTY
										BEGIN
											INSERT INTO @tmpPositions4Output
											(
												item_id,
												storp_id,
												stor_id,
												qty,
												storp_collectionOrder
											)
											VALUES
											(
												@curItem_Id,
												@curStorp_id,
												@curStor_id,
												@decPendingQTY,
												@curCollectionOrder
											)
											SET @decPendingQTY = 0
										END
									ELSE
										BEGIN
												INSERT INTO @tmpPositions4Output
												(
													item_id,
													storp_id,
													stor_id,
													qty,
													storp_collectionOrder
												)
												VALUES
												(
													@curItem_Id,
													@curStorp_id,
													@curStor_id,
													@curStorpQTY,
													@curCollectionOrder
												)
												SET @decPendingQTY = @decPendingQTY - @curStorpQTY
											END



									FETCH NEXT FROM curITEM_POSITIONS INTO	@curStorp_id,
																			@curStorpQTY,
																			@curCollectionOrder
								END
							CLOSE		curITEM_POSITIONS
							DEALLOCATE	curITEM_POSITIONS
							--curPOSICIONES
							FETCH NEXT FROM curITEMS	INTO	@curItem_Id,
																@curstor_id,
																@curqty
						END

					CLOSE curITEMS
					DEALLOCATE curITEMS




				-- ORIGINAL DE MOS
				-- Aca tengo en @tmpPositions4Output todo lo que hay que colectar de las posiciones.
				--SELECT	tmp.storp_id,
				--		tmp.item_id,
				--		tmp.stor_id,
				--		tmp.qty,
				--		tmp.storp_collectionOrder
				--	FROM @tmpPositions4Output tmp


				INSERT INTO tbTempItemStorage_Positions_Output
				(
					tmpGuid,
					item_id,
					stor_id,
					storp_id,
					initQty,
					col_id
				)
				SELECT
					@guid,
					tmp.item_id,
					tmp.stor_id,
					tmp.storp_id,
					tmp.qty	,
					@col_id
					FROM @tmpPositions4Output tmp

				SELECT
					' '											[ ],
					ti.item_code,
					ti.item_desc,
					ts.stor_desc,
					tsp.storp_nick,
					ttispo.initQty								[assignedQTY],
					tsoch.col_desc,
					ttispo.intID								[ID]
					FROM tbTempItemStorage_Positions_Output		AS ttispo
						INNER JOIN tbItem						AS ti		WITH(NOLOCK)
							ON	ti.comp_id		= @comp_id		AND
								ti.item_id		= ttispo.item_id
						INNER JOIN tbStorage					AS ts		WITH(NOLOCK)
							ON  ts.comp_id		= @comp_id		AND
								ts.stor_id		= ttispo.stor_id
						INNER JOIN tbStoragePositions			AS tsp		WITH(NOLOCK)
							ON	tsp.comp_id		= @comp_id		AND
								tsp.storp_id	= ttispo.storp_id
						LEFT JOIN tbSaleOrderCollectHeader		AS tsoch	WITH(NOLOCK)
							ON	tsoch.comp_id	= ttispo.col_id	AND
								tsoch.col_id	= ttispo.col_id
					WHERE ttispo.tmpGuid		= @guid

			END
	END

GO

CREATE PROCEDURE spItemStoragePositions_GetData4OutputQtyValidation
(
	@comp_id	INT,
	@stor_id	INT,
	@storp_id	INT,
	@item_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			tisp.itstp_cant
			FROM tbItemStoragePositions			AS tisp	WITH(NOLOCK)
			WHERE	tisp.comp_id	= @comp_id	AND
					tisp.stor_id	= @stor_id	AND
					tisp.storp_id	= @storp_id AND
					tisp.item_id	= @item_id

	END
GO

CREATE PROCEDURE [dbo].[spItemStoragePositions_GetDataByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@stor_id	INT,
	@storp_id	INT,
	@ItemsGuid	UNIQUEIDENTIFIER
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT,
				@stor_id	INT,
				@storp_id	INT,
				@ItemsGuid	UNIQUEIDENTIFIER
		*/
		-- ----------------------------------------------

		DECLARE @objGUID AS UNIQUEIDENTIFIER
		SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@ItemsGuid)
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf      WITH (NOLOCK)
				WHERE	tcf.sl_guid		= @objGUID      AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
					FROM tbItem			AS ti	WITH(NOLOCK)
					WHERE ti.comp_id	= @comp_id
			END

		SELECT
			ts.stor_desc,
			tsp.storp_nick,
			ti.item_code,
			ti.item_desc,
			tisp.itstp_cant,
			tisp.itstp_lastInput,
			tisp.itstp_lastOutput
			FROM tbItemStoragePositions					AS tisp WITH(NOLOCK)
			INNER JOIN @tblComplexFilter_Items		AS tcfi
				ON	tcfi.item_id	= tisp.item_id
			INNER JOIN tbItem						AS ti	WITH(NOLOCK)
				ON	ti.item_id		= tcfi.item_id
			INNER JOIN tbStoragePositions			AS tsp	WITH(NOLOCK)
				ON	tsp.comp_id		= tisp.comp_id	AND
					tsp.storp_id	= tisp.storp_id
			INNER JOIN tbStorage					AS ts	WITH(NOLOCK)
				ON	ts.comp_id		= tisp.comp_id	AND
					ts.stor_id		= tisp.stor_id
			WHERE	ts.comp_id			= @comp_id		AND
					(
						@stor_id		= -1 OR
						tisp.stor_id	= @stor_id
					)									AND
					(
						@storp_id		= -1 OR
						tisp.storp_id	= @storp_id
					)									AND
					tisp.itstp_cant		> 0
		ORDER BY tsp.storp_collectionOrder ASC

	END
GO

