CREATE PROCEDURE [dbo].[spItemStoragePositions_Transfer]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@item_id			INT,
	@stor_id			INT,
	@storp_id_Origin	INT,
	@storp_idDestiny	INT,
	@qty				INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@item_id			INT,
				@stor_id			INT,
				@storp_id_Origin	INT,
				@storp_idDestiny	INT,
				@qty				INT
		*/
		-- --------------------------------------------

		-- --------------------------------------------------------------
		-- Movimiento de Salida
		-- --------------------------------------------------------------
			DECLARE @itstp_lastInput AS DATETIME = GETDATE()
			SELECT	@itstp_lastInput = itstp_lastInput
				FROM   tbItemStoragePositions	WITH (NOLOCK)
				WHERE	comp_id		= @comp_id			AND
						stor_id		= @stor_id			AND
						storp_id	= @storp_id_Origin	AND
						item_id		= @item_id


			UPDATE tbItemStoragePositions
			SET
				itstp_cant			= itstp_cant - @qty,
				itstp_lastOutput	= GETDATE()
			WHERE	comp_id		= @comp_id			AND
					stor_id		= @stor_id			AND
					storp_id	= @storp_id_Origin	AND
					item_id		= @item_id

			--ACA CREO EL TRANSACTION OUTPUT
			INSERT INTO tbItemStoragePositionsTransactions
			(
				comp_id,
				-- ispt_id -- this column value is auto-generated
				ispt_transactionType,
				stor_id,
				storp_id,
				item_id,
				ispt_QTY,
				ispt_cd,
				[user_id],
				bra_id,
				prof_id
			)
			VALUES
			(
				@comp_id,
				2,
				@stor_id,
				@storp_id_Origin,
				@item_id,
				@qty,
				GETDATE(),
				@user_id,
				@bra_id,
				@prof_id
			)
		-- --------------------------------------------------------------

		-- --------------------------------------------------------------
		-- Movimiento de Entrada
		-- --------------------------------------------------------------
			IF EXISTS(	SELECT TOP 1 1
							FROM tbItemStoragePositions					AS tisp	WITH(NOLOCK)
							WHERE	tisp.comp_id	= @comp_id			AND
									tisp.stor_id	= @stor_id			AND
									tisp.storp_id	= @storp_idDestiny	AND
									tisp.item_id	= @item_id)
				BEGIN
					UPDATE tbItemStoragePositions
					SET
						itstp_cant		= itstp_cant + @qty,
						itstp_lastInput =	CASE
												WHEN @itstp_lastInput < itstp_lastInput THEN	@itstp_lastInput
												ELSE											itstp_lastInput
											END	-- traslada la fecha de entrada de la posicion de origen
					WHERE	comp_id		= @comp_id			AND
							stor_id		= @stor_id			AND
							storp_id	= @storp_idDestiny	AND
							item_id		= @item_id
				END
			ELSE
				BEGIN
					INSERT INTO tbItemStoragePositions
					(
						comp_id,
						stor_id,
						storp_id,
						item_id,
						itstp_cant,
						itstp_lastInput
					)
					VALUES
					(
						@comp_id,
						@stor_id,
						@storp_idDestiny,
						@item_id,
						@qty,
						@itstp_lastInput
					)
				END

			INSERT INTO tbItemStoragePositionsTransactions
			(
				comp_id,
				-- ispt_id -- this column value is auto-generated
				ispt_transactionType,
				stor_id,
				storp_id,
				item_id,
				ispt_QTY,
				ispt_cd,
				[user_id],
				bra_id,
				prof_id
			)
			VALUES
			(
				@comp_id,
				1,
				@stor_id,
				@storp_idDestiny,
				@item_id,
				@qty,
				GETDATE(),
				@user_id,
				@bra_id,
				@prof_id
			)
		-- --------------------------------------------------------------
	END





GO

CREATE PROCEDURE spItemStoragePositions_ValidateTransfer
(
	@comp_id	INT,
	@item_id	INT,
	@stor_id	INT,
	@storp_id	INT,
	@qty		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT,
				@stor_id	INT,
				@storp_id	INT,
				@qty		INT
			SELECT
				@comp_id	= 1,
				@item_id	= 1,
				@stor_id	= 807,
				@storp_id	= 1,
				@qty		= 1000
		*/
		-- ----------------------------------------------------

		-- --------------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- --------------------------------------------------------
		DECLARE
			@lMaxQty			INT,
			@bolHasErrors		BIT,
			@strErrorMessage	NVARCHAR(200)
		SET @lMaxQty			= 0
		SET @strErrorMessage	= ''
		SET @bolHasErrors		= 'False'
		-- --------------------------------------------------------

		--EXISTE ESTE ARTICULO PARA ESE DEPOSITO Y POSICION?
		IF EXISTS(SELECT 1
					FROM tbItemStoragePositions AS tisp
					WHERE	tisp.comp_id	= @comp_id AND
							tisp.stor_id	= @stor_id AND
							tisp.storp_id	= @storp_id AND
							tisp.item_id	= @item_id)
			BEGIN
				--RECUPERO LA CANTIDAD MAXIMA QUE PUEDE TRANSFERIR
				SELECT
					@lMaxQty = tisp.itstp_cant
				FROM tbItemStoragePositions AS tisp
				WHERE	tisp.comp_id	= @comp_id AND
						tisp.stor_id	= @stor_id AND
						tisp.storp_id	= @storp_id AND
						tisp.item_id	= @item_id

				-- TENGO LO SUFICIENTE PARA TRANSFERIR O ME PASO?
				IF @qty > @lMaxQty
					BEGIN
						SET @bolHasErrors		= 'True'
						SET @strErrorMessage	= 'La cantidad que se desea transferir es superior a la Cantidad disponible en la posición seleccionada. </br> La cantidad máxima disponible es: ' + CONVERT(VARCHAR,@lMaxQty)
					END

			END
		ELSE
			BEGIN
				SET @bolHasErrors		= 'True'
				SET @strErrorMessage	= 'El artículo que intenta transferir no pertenece a la posición de stock indicada.'
			END


		SELECT
			@bolHasErrors		[bolHasErrors],
			@strErrorMessage	[strErrorMessage]

	END


GO


CREATE PROCEDURE [dbo].[spItemStoragePositionsTMP_AssignFLUser2Movements]
(
	@comp_id	INT,
	@user_id	INT,
	@prof_id	INT,
	@bra_id		INT,
	@stor_id	INT,
	@tmp_id		INT,
	@isOutput	BIT,
	@flUser_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@user_id	INT,
				@prof_id	INT,
				@bra_id		INT,
				@stor_id	INT,
				@tmp_id		INT,
				@isOutput	BIT,
				@flUser_id	INT
			SELECT
				@comp_id	= 1,
				@user_id	= 134,
				@prof_id	= 1,
				@bra_id		= 1,
				@stor_id	= 1,
				@tmp_id		= 1,
				@isOutput	= 'False'
				@flUser_id	= 1
		*/
		-- ------------------------------------

		-- SI RECIBO -1 EN EL ID ES QUE TENGO QUE ASIGNAR TODOS LOS MOVIMIENTOS
		IF @tmp_id = -1
			BEGIN
				UPDATE tbItemStoragePositionsTMP
				SET
					fl_user_id			= @flUser_id
				WHERE	comp_id			= @comp_id	AND
						(
							@bra_id		= -1	OR
							bra_id		= @bra_id
						) 							AND
						(
							@stor_id	= -1	OR
							stor_id		= @stor_id
						)							AND
						(
							@user_id	= -1	OR
							[user_id]	= @user_id
						) 							AND
						(
							@prof_id	= -1	OR
							prof_id		= @prof_id
						)							AND
						tmp_is4Output	= @isOutput


			END
		ELSE
			BEGIN
				UPDATE tbItemStoragePositionsTMP
				SET
					fl_user_id	= @flUser_id
				WHERE	comp_id	= @comp_id	AND
						tmp_id	= @tmp_id

			END






	END
GO

