CREATE PROCEDURE [dbo].[spItemStoragePositionsTMP_GetDataByFilters]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@user_id		INT,
	@stor_id		INT,
	@tmp_is4Output	BIT
)
AS

	BEGIN
		SET NOCOUNT ON

		SET DATEFORMAT 'ymd'

		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT,
				@bolIsInput	BIT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@prof_id	= 1,
				@user_id	= 134,
				@bolIsInput	= 'False'
		*/
		-- ------------------------------------

		SELECT
				' ' [ ],												--CONFIRM
				' ' [ ],												--DELETE
				' ' [ ],												--ASSIGN USER WL
				' ' [ ],												--PRINTER
				ti.item_code,
				ti.item_desc,
				ts.stor_desc,
				tsp.storp_nick,
				tispt.tmp_QTY,
				tb.bra_desc,
				tu.user_lastname + ',' + tu.user_firstname				[user_name],
				ISNULL(tu2.user_lastname + ',' + tu2.user_firstname,'')	[user_name4FL],
				ISNULL(tispt.fl_movementConfirmed,'False')				[fl_movementConfirmed],
				tp.prof_desc,
				ISNULL(tispt.tmp_isDisabled,'False')					[tmp_isDisabled],
				ISNULL(tsoch.col_desc,'')								[col_desc],
				ISNULL(tispt.coli_id,'')								[coli_id],
				tispt.tmp_lastUpdate,
				tispt.tmp_id											[ID]

			FROM tbItemStoragePositionsTMP					AS tispt	WITH(NOLOCK)
				INNER JOIN tbItem							AS ti		WITH(NOLOCK)
					ON	ti.comp_id	= tispt.comp_id			AND
						ti.item_id	= tispt.item_id
				INNER JOIN tbStoragePositions				AS tsp		WITH(NOLOCK)
					ON	tsp.comp_id		= tispt.comp_id		AND
						tsp.storp_id	= tispt.storp_id
				INNER JOIN tbStorage						AS ts		WITH(NOLOCK)
					ON	ts.comp_id		= tispt.comp_id		AND
						ts.stor_id		= tispt.stor_id
				INNER JOIN tbUser							AS tu		WITH(NOLOCK)
					ON	tu.[user_id]	= tispt.[user_id]
				INNER JOIN tbProfile						AS tp		WITH(NOLOCK)
					ON	tp.comp_id		= tispt.comp_id		AND
						tp.prof_id		= tispt.prof_id
				INNER JOIN tbBranch							AS tb		WITH(NOLOCK)
					ON	tb.comp_id		= tispt.comp_id		AND
						tb.bra_id		= tispt.bra_id
				LEFT JOIN tbSaleOrderCollectDetail			AS tsocd	WITH(NOLOCK)
					ON	tispt.comp_id	= tsocd.comp_id		AND
						tispt.coli_id	= tsocd.cold_id
				LEFT JOIN tbSaleOrderCollectHeader			AS tsoch	WITH(NOLOCK)
					ON	tsoch.comp_id	= tsocd.comp_id		AND
						tsoch.col_id	= tsocd.col_id
				LEFT JOIN tbUser							AS tu2		WITH(NOLOCK)
					ON  tu2.[user_id]	= tispt.fl_user_id

			WHERE		tispt.comp_id		= @comp_id		AND
						(
							@bra_id				= -1 OR
							tispt.bra_id		= @bra_id
						)									AND
						(
							@prof_id			= -1 OR
							tispt.prof_id		= @prof_id
						)									AND
						(
							@user_id			= -1 OR
							tispt.[user_id]		= @user_id
						)									AND
						(
							@stor_id			= -1 OR
							tispt.stor_id		= @stor_id
						)									AND
						tispt.tmp_is4Output	= @tmp_is4Output
END
GO

