CREATE PROCEDURE [dbo].[spItemStoragePositionsTMP_InsertData4UserTransfer]
(
	@comp_id			INT,
	@item_id			INT,
	@stor_id			INT,
	@storp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@isDisabled			BIT,
	@isOutput			INT,
	@tmp_QTY			DECIMAL(18,4),
	@user4Transfer		INT,
	@storp_idDestiny	INT,
	@impdata_id			INT
)
AS
	BEGIN
		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
		DECLARE
			@comp_id		INT,
			@item_id		INT,
			@stor_id		INT,
			@storp_id		INT,
			@bra_id			INT,
			@prof_id		INT,
			@user_id		INT,
			@isDisabled		BIT,
			@isOutput		INT,
			@coli_id		INT
		*/
		-- ------------------------------------

		IF @impdata_id = -1
			BEGIN
				SET @impdata_id = NULL
			END

		INSERT INTO tbItemStoragePositionsTMP
		(
			comp_id,
			-- tmp_id -- this column value is auto-generated
			item_id,
			stor_id,
			storp_id,
			bra_id,
			prof_id,
			[user_id],
			tmp_cd,
			tmp_isDisabled,
			tmp_is4Output,
			tmp_QTY,
			fl_user_id,
			storp_id_destiny,
			impData_Id
		)
		VALUES
		(
			@comp_id,
			@item_id,
			@stor_id,
			@storp_id,
			@bra_id,
			@prof_id,
			@user_id,
			GETDATE(),
			@isDisabled,
			@isOutput,
			@tmp_QTY,
			@user4Transfer,
			@storp_idDestiny,
			@impdata_id
		)

	END


GO

CREATE PROCEDURE [dbo].[spItemStoragePositionsTMP_ProcessAllInputData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT
		*/
		-- -------------------------------------------------------

		--01 Recupero los datos a procesar, los tiro en una temporal y armo un cursor
		DECLARE
			@lcomp_id	INT,
			@ltmp_id	INT
		DECLARE cursor_WMSInputProcess CURSOR LOCAL FAST_FORWARD FOR
			SELECT
				tmp.comp_id,
				tmp.tmp_id
				FROM tbItemStoragePositionsTMP							tmp WITH(NOLOCK)
				WHERE	tmp.comp_id							= @comp_id	AND
						tmp.bra_id							= @bra_id	AND
						tmp.[user_id]						= @user_id	AND
						tmp.prof_id							= @prof_id	AND
						ISNULL(tmp.tmp_is4Output,'False')	= 'False'
		OPEN cursor_WMSInputProcess
		FETCH cursor_WMSInputProcess
		INTO
			@lcomp_id,
			@ltmp_id
			WHILE @@FETCH_STATUS = 0
				BEGIN
					--02 Por cada registro tengo que llamar al spItemStoragePositionsTMP_ProcessDataInput
					EXEC spItemStoragePositionsTMP_ProcessDataInput @lcomp_id, @ltmp_id
					FETCH cursor_WMSInputProcess
					INTO
						@lcomp_id,
						@ltmp_id
				END
		CLOSE cursor_WMSInputProcess
		DEALLOCATE cursor_WMSInputProcess
	END






GO


CREATE PROCEDURE [dbo].[spItemStoragePositionsTMP_ProcessAllOutputData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT
			SELECT
