				@user_id	= 134
		*/
		-- -------------------------------------------------------

		--01 Recupero los datos a procesar, los tiro en una temporal y armo un cursor
		DECLARE
			@lcomp_id	INT,
			@ltmp_id	INT
		DECLARE cursor_WMSOutputProcess CURSOR LOCAL FAST_FORWARD FOR
			SELECT
				tmp.comp_id,
