CREATE PROCEDURE [dbo].[spItemStoragePositionsTMP_ProcessDataByFLUser]
(
	@comp_id		INT,
	@user_id		INT,
	@is4Output		BIT,
	@movType		INT,	--1 = Confirmado / 2 = Confirmado y Procesado
	@PickingType	BIT,
	@position		VARCHAR(20),
	@etiqueta		VARCHAR(20)
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@user_id		INT,
				@is4Output		BIT,
				@movType		INT,	--1 = Confirmado / 2 = Confirmado y Procesado
				@PickingType	BIT,
				@position		VARCHAR(20),
				@etiqueta		VARCHAR(20)
			SELECT
				@comp_id		= 1,
				@user_id		= 134,
				@is4Output		= 'True',
				@movType		= 2,	--1 = Confirmado / 2 = Confirmado y Procesado
				@PickingType	= 'True',
				@position		= 'WMS-POS-1',
				@etiqueta		= 'ART-POS3'
		*/
		-- ------------------------------------
		DECLARE
			@lstorp_id	INT
		SELECT
					@lstorp_id		= tsp.storp_id
			FROM	tbStoragePositions			AS tsp	WITH(NOLOCK)
			WHERE	tsp.comp_id		= @comp_id	AND
					tsp.storp_nick	= @position


		--01 Recupero los datos a procesar, los tiro en una temporal y armo un cursor
		DECLARE
			@lcomp_id	INT,
			@ltmp_id	INT,
			@lqty		INT,
			@lcoli_id	INT
		DECLARE cursor_WMSFLProcess CURSOR LOCAL FAST_FORWARD FOR
			SELECT
					tispt.comp_id,
					tispt.tmp_id,
					tispt.tmp_QTY,
					tispt.coli_id
				FROM tbItemStoragePositionsTMP						AS tispt	WITH(NOLOCK)
					INNER JOIN	tbItem								AS ti		WITH(NOLOCK)
						ON	ti.comp_id				= tispt.comp_id AND
							ti.item_id				= tispt.item_id
				WHERE	tispt.comp_id		= @comp_id				AND
						--tispt.tmp_id		= @ltmpID
						tispt.fl_user_id	= @user_id				AND
						tispt.tmp_is4Output	= @is4Output			AND
						tispt.storp_id		= @lstorp_id			AND
						(
							@PickingType = 'False' OR
							ti.item_code = @etiqueta
						)											AND
						ISNULL(tispt.fl_movementConfirmed,'False') = 'False'
		OPEN cursor_WMSFLProcess
		FETCH cursor_WMSFLProcess
		INTO
			@lcomp_id,
			@ltmp_id,
			@lqty,
			@lcoli_id
			WHILE @@FETCH_STATUS = 0
				BEGIN
					--02 Por cada registro tengo que llamar al sp Correspondiente
					IF @is4Output = 'False'
						BEGIN
							UPDATE tbItemStoragePositionsTMP
							SET
								fl_movementConfirmed	= 'True',
								fl_processingDate		=	CASE @movType
																WHEN 2		THEN GETDATE()
																ELSE		NULL
															END
							FROM tbItemStoragePositionsTMP					AS tispt	WITH(NOLOCK)
							WHERE	tispt.comp_id		= @comp_id			AND
									tispt.tmp_id		= @ltmp_id

							IF @movType = 2
								BEGIN
									EXEC spItemStoragePositionsTMP_ProcessDataInput @lcomp_id, @ltmp_id
								END
						END
					ELSE
						BEGIN
							UPDATE tbItemStoragePositionsTMP
							SET
								fl_movementConfirmed	= 'True',
								fl_processingDate		=	CASE @movType
																WHEN 2		THEN GETDATE()
																ELSE		NULL
															END
							FROM tbItemStoragePositionsTMP					AS tispt	WITH(NOLOCK)
							WHERE	tispt.comp_id		= @comp_id			AND
									tispt.tmp_id		= @ltmp_id

							IF @movType = 2
								BEGIN
									EXEC spItemStoragePositionsTMP_ProcessDataOutput @lcomp_id, @ltmp_id
								END
							ELSE
								BEGIN
									-- --------------------------------------------------------------
									-- SI ES UN REGISTRO DE UNA COLECTA
									-- --------------------------------------------------------------
									IF @lcoli_id IS NOT NULL
										BEGIN
											UPDATE tbSaleOrderCollectItems
											SET
												coli_qty	= coli_qty + @lqty,
												[user_id]	= @user_id
											WHERE	comp_id = @comp_id AND
													coli_id = @lcoli_id
										END
									-- --------------------------------------------------------------
								END
						END
					FETCH cursor_WMSFLProcess
					INTO
						@lcomp_id,
						@ltmp_id,
						@lqty,
						@lcoli_id
				END
		CLOSE cursor_WMSFLProcess
		DEALLOCATE cursor_WMSFLProcess
	END
GO

CREATE PROCEDURE [dbo].[spItemStoragePositionsTMP_ProcessDataInput]
(
	@comp_id	INT,
	@tmp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@tmp_id		INT
		*/
		-- ----------------------------------------------------

		-- ------------------------------------
		-- VARIABLES DE TRABAJO
		-- ------------------------------------
		DECLARE
			@lstor_id		INT,
			@lstorp_id		INT,
			@litem_id		INT,
			@ltmp_QTY		INT,
			@limportdataid	INT
		-- ------------------------------------

		-- --------------------------------------------------------------
		-- 01 Recupero los datos del registro de la Temporal
		-- --------------------------------------------------------------
		SELECT
			@lstor_id				= tispt.stor_id,
			@lstorp_id				= tispt.storp_id,
			@litem_id				= tispt.item_id,
			@ltmp_QTY				= tispt.tmp_QTY,
			@limportdataid			= tispt.impData_Id
			FROM tbItemStoragePositionsTMP		AS tispt	WITH(NOLOCK)
			WHERE	tispt.comp_id	= @comp_id	AND
					tispt.tmp_id	= @tmp_id
		-- --------------------------------------------------------------

		-- --------------------------------------------------------------
		-- 02 GRABO EN LA TABLA FINAL EL REGISTRO DE LA TEMPORAL
		INSERT INTO tbItemStoragePositionsTransactions
		(
			comp_id,
			ispt_transactionType,
			stor_id,
			storp_id,
			item_id,
			ispt_QTY,
			ispt_cd,
			[user_id],
			bra_id,
			prof_id,
			fl_user_id,
			fl_processingDate,
			impData_id
		)
		SELECT
			tispt.comp_id,
			1,
			tispt.stor_id,
			tispt.storp_id,
			tispt.item_id,
			tispt.tmp_QTY,
			GETDATE(),
			tispt.[user_id],
			tispt.bra_id,
			tispt.prof_id,
			tispt.fl_user_id,
			tispt.fl_processingDate,
			tispt.impData_Id
			FROM tbItemStoragePositionsTMP		AS tispt	WITH(NOLOCK)
			WHERE	tispt.comp_id	= @comp_id	AND
					tispt.tmp_id	= @tmp_id
		-- --------------------------------------------------------------

		-- --------------------------------------------------------------
		-- 03 Actualizamos la tabla ItemStoragePositions, si el registro ya existe actualizamos solo la cantidad
		--    Si el registro NO existe, generamos uno nuevo y ponemos la cantidad
		-- --------------------------------------------------------------
		IF EXISTS (	SELECT TOP 1 1
						FROM	tbItemStoragePositions AS tisp
						WHERE	tisp.comp_id	= @comp_id AND
								tisp.stor_id	= @lstor_id AND
								tisp.storp_id	= @lstorp_id AND
								tisp.item_id	= @litem_id)
			BEGIN
				UPDATE tbItemStoragePositions
				SET
					itstp_cant		= itstp_cant +  @ltmp_QTY,
					itstp_lastInput = GETDATE()
				WHERE	comp_id		= @comp_id		AND
						stor_id		= @lstor_id		AND
						storp_id	= @lstorp_id	AND
						item_id		= @litem_id
			END
		ELSE
			BEGIN
				INSERT INTO tbItemStoragePositions
				(
					comp_id,
					stor_id,
					storp_id,
					item_id,
					itstp_cant,
					itstp_lastInput,
					impData_id
				)
				VALUES
				(
					@comp_id,
					@lstor_id,
					@lstorp_id,
					@litem_id,
					@ltmp_QTY,
					GETDATE(),
					@limportdataid
				)
			END
		-- --------------------------------------------------------------

		-- --------------------------------------------------------------
		-- 04 Borramos el registro de la temporal una vez terminados todos los procesos.
		-- --------------------------------------------------------------
		EXEC spItemStoragePositionsTMP_DeleteData @comp_id,@tmp_id
		-- --------------------------------------------------------------

	END















GO



-- Log
-- MOS 09-2024: Auto reposicion de posiciones de picking desde estiba: **RPEP


CREATE PROCEDURE [dbo].[spItemStoragePositionsTMP_ProcessDataOutput]
(
	@comp_id	INT,
	@tmp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@tmp_id		INT
		*/
		-- ----------------------------------------------------

		-- ------------------------------------
		-- VARIABLES DE TRABAJO
		-- ------------------------------------
		DECLARE
			@lstor_id			INT,
			@lstorp_id			INT,
			@litem_id			INT,
			@ltmp_QTY			INT,
			@storp_id_Destiny	INT,
			@coli_id			INT,
			@fl_user_id			INT
		-- ------------------------------------



		DECLARE @storp_is4PickingAutoReplenishment		AS BIT = 'False'
		DECLARE @storp_PickingAutoReplenishmentMINQty	AS INT = 0
		DECLARE @storp_PickingAutoReplenishmentOPTQty	AS INT = 0
		DECLARE @user_id								AS INT
		DECLARE @bra_id									AS INT
		DECLARE @prof_id								AS INT
		-- --------------------------------------------------------------
		-- 01 Recupero los datos del registro de la Temporal
		-- --------------------------------------------------------------
		SELECT
			@lstor_id				= tispt.stor_id,
			@lstorp_id				= tispt.storp_id,
			@litem_id				= tispt.item_id,
			@ltmp_QTY				= tispt.tmp_QTY,
			@storp_id_Destiny		= tispt.storp_id_destiny,
			@coli_id				= tispt.coli_id,
			@fl_user_id				= tispt.fl_user_id,
			@storp_is4PickingAutoReplenishment		= tsp.storp_is4PickingAutoReplenishment,
			@storp_PickingAutoReplenishmentMINQty	= tsp.storp_PickingAutoReplenishmentMINQty,
			@storp_PickingAutoReplenishmentOPTQty	= tsp.storp_PickingAutoReplenishmentOPTQty,
			@user_id								= tispt.[user_id],
			@bra_id									= tispt.bra_id,
			@prof_id								= tispt.prof_id
			FROM tbItemStoragePositionsTMP			AS tispt	WITH (NOLOCK)
			INNER JOIN tbStoragePositions			AS tsp		WITH (NOLOCK)
				ON	tsp.comp_id		= tispt.comp_id AND
					tsp.storp_id	= tispt.storp_id
			WHERE	tispt.comp_id	= @comp_id	AND
					tispt.tmp_id	= @tmp_id
		-- --------------------------------------------------------------

		-- --------------------------------------------------------------
		-- 02 GRABO EN LA TABLA FINAL EL REGISTRO DE LA TEMPORAL
		INSERT INTO tbItemStoragePositionsTransactions
		(
			comp_id,
			ispt_transactionType,
			stor_id,
			storp_id,
			item_id,
			ispt_QTY,
			ispt_cd,
			[user_id],
			bra_id,
			prof_id,
			fl_user_id,
			fl_processingDate,
			impData_id
		)
		SELECT
			tispt.comp_id,
			2,
			tispt.stor_id,
			tispt.storp_id,
			tispt.item_id,
			tispt.tmp_QTY,
			GETDATE(),
			tispt.[user_id],
			tispt.bra_id,
			tispt.prof_id,
			tispt.fl_user_id,
			tispt.fl_processingDate,
			tispt.impData_Id
		FROM tbItemStoragePositionsTMP		AS tispt	WITH(NOLOCK)
		WHERE	tispt.comp_id	= @comp_id	AND
				tispt.tmp_id	= @tmp_id
		-- --------------------------------------------------------------

		-- --------------------------------------------------------------
		-- 03 Actualizamos la tabla ItemStoragePositions y restamos
		-- la cantidad y si la cantidad queda en 0 y tiene un IMPDATA_ID
		-- tengo que ponerlo en null
		-- --------------------------------------------------------------
		UPDATE tbItemStoragePositions
			SET
				itstp_cant			= itstp_cant -  @ltmp_QTY,
				itstp_lastOutput	= GETDATE()
			WHERE	comp_id		= @comp_id		AND
					stor_id		= @lstor_id		AND
					storp_id	= @lstorp_id	AND
					item_id		= @litem_id

		DECLARE @item_id	 AS INT = NULL
		DECLARE	@lqty4Check		INT = NULL
		DECLARE @limpData_id	INT = NULL
		SELECT	@lqty4Check			= itstp_cant	,
				@limpData_id		= impData_id,
				@item_id			= item_id
			FROM tbItemStoragePositions		WITH (NOLOCK)
			WHERE	comp_id		= @comp_id		AND
					stor_id		= @lstor_id		AND
					storp_id	= @lstorp_id	AND
					item_id		= @litem_id
		IF @lqty4Check = 0
			BEGIN
				SET @limpData_id = NULL
				UPDATE tbItemStoragePositions
					SET		impData_id	= NULL
					WHERE	comp_id		= @comp_id		AND
							stor_id		= @lstor_id		AND
							storp_id	= @lstorp_id	AND
							item_id		= @litem_id
			END
		-- --------------------------------------------------------------

		-- --------------------------------------------------------------
		-- 04 SI ES UN REGISTRO DE UNA COLECTA
		-- --------------------------------------------------------------
		IF @coli_id IS NOT NULL
			BEGIN
				UPDATE tbSaleOrderCollectItems
				SET coli_qty	= coli_qty + @ltmp_QTY,
					[user_id]	= @fl_user_id
				WHERE	comp_id = @comp_id AND
						coli_id = @coli_id
			END
		-- --------------------------------------------------------------



		-- --------------------------------------------------------------
		-- 05 Si es una transferencia entre posiciones tengo que generar el registro
		-- --------------------------------------------------------------
		IF @storp_id_Destiny IS NOT NULL
			BEGIN
				INSERT INTO tbItemStoragePositionsTMP
				(
					comp_id,
					item_id,
					stor_id,
					storp_id,
					bra_id,
					prof_id,
					[user_id],
					tmp_isDisabled,
					tmp_lastUpdate,
					tmp_is4Output,
					coli_id,
					tmp_QTY,
					fl_user_id,
					impData_Id
				)
				SELECT
					tispt.comp_id,
					tispt.item_id,
					tispt.stor_id,
					tispt.storp_id_destiny,
					tispt.bra_id,
					tispt.prof_id,
					tispt.[user_id],
					'False',
					NULL,
					'False',
					tispt.coli_id,
					tispt.tmp_QTY,
					tispt.fl_user_id,
					tispt.impData_Id
				FROM tbItemStoragePositionsTMP		AS tispt	WITH(NOLOCK)
				WHERE	tispt.comp_id	= @comp_id	AND
						tispt.tmp_id	= @tmp_id
			END
		-- --------------------------------------------------------------


--INSERT INTO zTest
--(
--	dato,
--	valor
--)
--VALUES
--(
--	'',
--	0
--)


		-- --------------------------------------------------------------
		-- **RPEP
		-- MOS 09-2024: Auto reposicion de posiciones de picking
		-- @lqty4Check: Cantidad actual de stock de la posicion
		-- @limpData_id: despacho asignado a la posicion
		-- @storp_is4PickingAutoReplenishment
		-- @storp_PickingAutoReplenishmentMINQty
		-- @storp_PickingAutoReplenishmentOPTQty
		-- @lstor_id
		-- @lstorp_id
		-- --------------------------------------------------------------
		IF	@storp_is4PickingAutoReplenishment = 'True' AND
			@lqty4Check < @storp_PickingAutoReplenishmentMINQty
			BEGIN
				DECLARE @decQTY4Replenish AS INT	= 0
				SET		@decQTY4Replenish			= @storp_PickingAutoReplenishmentOPTQty - @lqty4Check
				-- 1:Ver de donde saco @decQTY4Replenish, que debe ser 1ro se posiciones de cercania en ORDEN de sacado y que tengan stock y sean del mismo lote
				-- 2:Insertar la solicitud de SACAR de esa posicion de cercania y generar el registro, informando en el registro que es una REPOSICION de PICKING con otro color
				--   poniendo el dato de @storp_id_Destiny que es la ACTUAL posicion

--INSERT INTO zTest
--(
--	dato,
--	valor
--)
--VALUES
--(
--	'1',
--	1
--)

			    DECLARE		@tmpTable4ReplenishOriginPositions TABLE( storp_id INT, order4Output INT, orderPriority int)

				INSERT INTO @tmpTable4ReplenishOriginPositions(
																storp_id,
																order4Output,
																orderPriority
															  )
				SELECT			tisp.storp_id_related,
								tisp.storpr_order4Output,
								CASE	-- Primer orden para las que en su totalidad puedan reponer la posicion de picking. Seguro algun forro va a pedir que en el caso en q no haya sufuciente, solo reponga hasta agotar el stock de la posicion.
									WHEN tis.itstp_cant >= @decQTY4Replenish THEN 0
									ELSE										  1
								END
					FROM tbStoragePositionsRelated AS tisp		WITH (NOLOCK)
					INNER JOIN tbStoragePositions  AS tsp		WITH (NOLOCK)  -- Posiciones de cercania relacionadas.
						ON	tsp.comp_id		= tisp.comp_id	AND
							tsp.storp_id	= tisp.storp_id_related
					INNER JOIN tbItemStoragePositions AS tis	WITH (NOLOCK)
						ON	tis.comp_id		= tsp.comp_id	AND
							tis.storp_id	= tsp.storp_id	AND
							tis.stor_id		= @lstor_id		AND
							tis.item_id		= @item_id
					WHERE	tisp.comp_id	= @comp_id		AND
							tisp.storp_id	= @lstorp_id	AND
							tsp.storp_is4Picking = 'False'	AND
							tis.itstp_cant  > 0				AND
							(
