CREATE PROCEDURE spItemStoragePositionsTMP_processMovementByID
(
	@comp_id	INT,
	@user_id	INT,
	@movType	INT,	--1 = Confirmado / 2 = Confirmado y Procesado
	@tmp_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@user_id	INT,
				@movType	INT, --1 = Confirmado / 2 = Confirmado y Procesado
				@tmp_id		INT
		*/
		-- -----------------------------------------------------

		UPDATE tbItemStoragePositionsTMP
		SET
			fl_movementConfirmed	= 'True',
			fl_processingDate		=	CASE @movType
											WHEN 2							THEN GETDATE()
											ELSE								 NULL
										END
		WHERE	comp_id = @comp_id AND
				tmp_id	= @tmp_id



	END

GO

