CREATE PROCEDURE spItemStoragePositionsTMP_ValidateData4Processing
(
	@comp_id		INT,
	@user_id		INT,
	@PickingType	BIT,
	@position		NVARCHAR(20),
	@item_code		NVARCHAR(50)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@user_id		INT,
				@PickingType	BIT,
				@position		NVARCHAR(20),
				@item_code		NVARCHAR(50)
			SELECT
				@comp_id		= 1,
				@user_id		= 134,
				@PickingType	= 'True',
				@position		= 'WMS-POS-2',
				@item_code		= 'ART-POS5'
		*/
		-- ----------------------------------------------------

		-- -----------------------------------------------------------
		-- VALIDO QUE LA POSICION SEA VALIDA
		-- -----------------------------------------------------------
			DECLARE
				@lstorp_id	INT
			SELECT
				@lstorp_id	= tsp.storp_id
			FROM	tbStoragePositions			AS tsp	WITH(NOLOCK)
			WHERE	tsp.comp_id		= @comp_id	AND
					tsp.storp_nick	= @position

			IF @lstorp_id IS NULL
				BEGIN
					SELECT 'El código de Pósición ingresado no existe.' [ErrorMessage]
					RETURN
				END
		-- -----------------------------------------------------------

		-- -----------------------------------------------------------
		-- VALIDO QUE EXISTA EL ARTICULO
		-- -----------------------------------------------------------
			DECLARE
				@litem_id	INT
			IF @PickingType = 'True'
				BEGIN
					SELECT
						@litem_id			= ti.item_id
						FROM tbItem						AS ti WITH(NOLOCK)
						WHERE ti.comp_id	= @comp_id	AND
							ti.item_code	= @item_code

					IF @litem_id IS NULL
						BEGIN
							SELECT 'El código de Artículo ingresado no existe.' [ErrorMessage]
							RETURN
						END
				END
		-- -----------------------------------------------------------


		-- -----------------------------------------------------------
		-- VALIDO QUE HAYA REGISTROS PENDIENTES DE PROCESAR PARA ESOS PARAMETROS
		-- -----------------------------------------------------------
			IF (SELECT COUNT(*)
				FROM tbItemStoragePositionsTMP			AS tispt	WITH(NOLOCK)
				WHERE	tispt.comp_id		= @comp_id	AND
						(
							@PickingType	= 'False' OR
							tispt.item_id	= @litem_id
						)								AND
						tispt.storp_id	= @lstorp_id	AND
						ISNULL(tispt.fl_movementConfirmed,'False') = 'False') = 0
				BEGIN
					SELECT 'No quedan registros por procesar con esos parámetros.' [ErrorMessage]
					RETURN
				END
		-- -----------------------------------------------------------

		SELECT 'Ok' [ErrorMessage]

	END



GO


CREATE PROCEDURE [dbo].[spItemStoragePositionsTransactions_GetDataByFilters]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@ItemsGuid				VARCHAR(50),
	@stor_id				INT,
	@dateTransactionFrom	DATETIME,
	@dateTransactionTo		DATETIME
)
AS

	BEGIN
		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@prof_id				INT,
				@user_id				INT,
				@ItemsGuid				VARCHAR(50),
				@stor_id				INT,
				@dateTransactionFrom	DATETIME,
				@dateTransactionTo		DATETIME
			SELECT
				@comp_id				= 1,
				@lang_id				= 2,
				@bra_id					= 1,
				@prof_id				= 1,
				@user_id				= -1,
				@ItemsGuid				= '3299d1a7-39d5-4514-8339-41a12ffb4b46',
				@stor_id				= -1,
				@dateTransactionFrom	= '2023-06-06',
				@dateTransactionTo		= '2023-06-06'
		*/
		-- -------------------------------------------

		SET DATEFORMAT 'YMD'
		SET @dateTransactionFrom = dbo.fnGetEnd_or_BeginOfDate(@dateTransactionFrom,'False')
		SET @dateTransactionTo	 = dbo.fnGetEnd_or_BeginOfDate(@dateTransactionTo,'True')

		DECLARE @objGUID AS UNIQUEIDENTIFIER
		SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@ItemsGuid)
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf      WITH (NOLOCK)
				WHERE	tcf.sl_guid		= @objGUID      AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
					FROM tbItem			AS ti	WITH(NOLOCK)
					WHERE ti.comp_id	= @comp_id
			END


		SELECT
			' ' [ ],
			' ' [ ],
			--' ' [ ],
			CASE
				WHEN tispt.ispt_transactionType = 1 THEN	'Ingreso'
				WHEN tispt.ispt_transactionType = 2 THEN	'Egreso'
			ELSE											''
			END												[MovType],


			ti.item_code,
			ti.item_desc,
			ts.stor_desc,
			tsp.storp_nick,
			tispt.ispt_QTY,
			tb.bra_desc,
			tp.prof_desc,
			tu.user_lastname + ',' + tu.user_firstname		[user_name]

		FROM tbItemStoragePositionsTransactions AS tispt	WITH(NOLOCK)
		INNER JOIN @tblComplexFilter_Items		AS tcfi
			ON	tcfi.item_id	= tispt.item_id
		INNER JOIN tbItem						AS ti		WITH(NOLOCK)
			ON	ti.comp_id		= tispt.comp_id	AND
				ti.item_id		= tcfi.item_id
		INNER JOIN tbStorage					AS ts		WITH(NOLOCK)
			ON	ts.comp_id		= tispt.comp_id	AND
				ts.stor_id		= tispt.stor_id
		INNER JOIN tbStoragePositions			AS tsp		WITH(NOLOCK)
			ON	tsp.comp_id		= tispt.comp_id	AND
				tsp.storp_id	= tispt.storp_id
		INNER JOIN tbBranch						AS tb		WITH(NOLOCK)
			ON	tb.comp_id		= tispt.comp_id	AND
				tb.bra_id		= tispt.bra_id
		INNER JOIN tbUser						AS tu		WITH(NOLOCK)
			ON	tu.[user_id]	= tispt.[user_id]
		INNER JOIN tbProfile					AS tp		WITH(NOLOCK)
			ON	tp.comp_id		= tispt.comp_id	AND
				tp.prof_id		= tispt.prof_id

		WHERE	tispt.comp_id = @comp_id			AND
				(	@stor_id		= -1 OR
					tispt.stor_id	= @stor_id
				)									AND
				(
					@user_id		= -1 OR
					tispt.[user_id] = @user_id
				)									AND
				tispt.bra_id		= @bra_id		AND
				tispt.ispt_cd		BETWEEN @dateTransactionFrom AND @dateTransactionTo
	END




GO

 CREATE PROCEDURE spItemStoragePositionsTransactions_GetReport
 (
 	@comp_id		INT,
	@lang_id		INT,
	@page_id		INT,
	--@bra_id		INT,
	--@prof_id		INT,
	@user_id		INT,
	@stor_id		INT,
	@dateFrom		DATETIME,
	@dateTo			DATETIME,
	@ItemsGuid		UNIQUEIDENTIFIER,
	@Is4Output		BIT,
	@intBranch4Lang	INT
 )
 AS
	BEGIN

		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@page_id		INT,
				--@bra_id		INT,
				--@prof_id		INT,
				@user_id		INT,
				@stor_id		INT,
				@dateFrom		DATETIME,
				@dateTo			DATETIME,
				@ItemGuid		UNIQUEIDENTIFIER,
				@Is4Output		BIT,
				@intBranch4Lang	INT

			SELECT
				@comp_id		= 1,
				@lang_id		= 2,
				@page_id		= 100972,
				@bra_id			= 1,
				@prof_id		= 1,
				@user_id		= 54,
				@stor_id		= 1,
				@dateFrom		= '2023-01-01',
				@dateTo			= '2023-12-01',
				@ItemsGuid		= '3299d1a7-39d5-4514-8339-41a12ffb4b46',
				@Is4Output		= 'False',
				@intBranch4Lang	= 1
		*/
		-- -------------------------------------------------

		SET @dateFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'False')
		SET @dateTo		= dbo.fnGetEnd_or_BeginOfDate(@dateTo,'True')

		DECLARE @objGUID AS UNIQUEIDENTIFIER
		SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@ItemsGuid)
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf      WITH (NOLOCK)
				WHERE	tcf.sl_guid		= @objGUID      AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
					FROM tbItem			AS ti	WITH(NOLOCK)
					WHERE ti.comp_id	= @comp_id
			END

		SELECT
			ts.stor_desc,
			tsp.storp_nick,
			ti.item_id,
			ti.item_code,
			ti.item_desc,
			tispt.ispt_QTY							AS tmp_QTY
		FROM tbItemStoragePositionsTransactions		AS tispt	WITH(NOLOCK)
			INNER JOIN @tblComplexFilter_Items		AS tcfi
				ON	tcfi.item_id	= tispt.item_id
			INNER JOIN tbItem						AS ti		WITH(NOLOCK)
				ON	ti.comp_id		= tispt.comp_id	AND
					ti.item_id		= tispt.item_id
			INNER JOIN tbStorage					AS ts		WITH(NOLOCK)
				ON  ts.comp_id		= tispt.comp_id	AND
					ts.stor_id		= tispt.stor_id
			INNER JOIN tbStoragePositions			AS tsp		WITH(NOLOCK)
				ON	tsp.comp_id		= tispt.comp_id	AND
					tsp.storp_id	= tispt.storp_id
		WHERE	tispt.comp_id = @comp_id	AND
				--(
				--	@bra_id			= -1 OR
				--	tispt.bra_id	= @bra_id
				--)							AND
				(
					@stor_id		= -1 OR
					tispt.stor_id	= @stor_id
				)							AND
				--(
				--	@prof_id		= -1 OR
				--	tispt.prof_id	= @prof_id
				--)							AND
				(
					@user_id		= -1 OR
					tispt.[user_id] = @user_id
				)							AND
				(
					@Is4Output					= -1 OR
					tispt.ispt_transactionType	= @Is4Output
					--tispt.tmp_is4Output =  @Is4Output
				)

		ORDER BY tsp.storp_priority4Output

		EXEC [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id
		/* devolución de parámetros recibidos */
		DECLARE @related_page_id INT
		SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

	END











GO


CREATE PROCEDURE [dbo].[spItemStoragePositonsTMP_InsertDataFromTempTable4Inputs]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@impdataID	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------
		-- TESTING
		-- --------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT,
				@guid		UNIQUEIDENTIFIER
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@prof_id	= 1,
				@user_id	= 1,
				@guid		= 'fa61c72b-41d7-46e5-812f-8bb916250d0d'
		*/
		-- --------------------------------------------------

		IF @impdataID = -1
			BEGIN
				SET @impdataID = NULL
			END

		INSERT INTO tbItemStoragePositionsTMP
		(
			comp_id,
			item_id,
			stor_id,
			storp_id,
			bra_id,
			prof_id,
			[user_id],
			tmp_cd,
			tmp_isDisabled,
			--tmp_lastUpdate,
			tmp_is4Output,
			coli_id,
			tmp_QTY,
			impData_Id
		)
		SELECT
			@comp_id,
			ttisp.item_id,
			ttisp.stor_id,
			ttisp.storp_id,
			@bra_id,
			@prof_id,
			@user_id,
			GETDATE(),
			'False',
			'False',
			NULL,
			ttisp.intqty,
			@impdataID
			FROM tbTempItemStorage_Positions	AS ttisp	WITH(NOLOCK)
			WHERE	ttisp.tmpguid	= @guid		AND
					ttisp.intqty	> 0

		--UNA VEZ QUE GRABA BORRO TODOS LOS REGISTROS CON ESE GUID
		DELETE FROM tbTempItemStorage_Positions WHERE tmpguid = @guid


	END

GO

CREATE PROCEDURE [dbo].[spItemStoragePositonsTMP_InsertDataFromTempTable4Outputs]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------
		-- TESTING
		-- --------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT,
				@guid		UNIQUEIDENTIFIER
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@prof_id	= 1,
				@user_id	= 1,
				@guid		= 'fa61c72b-41d7-46e5-812f-8bb916250d0d'
		*/
		-- --------------------------------------------------

		--ACA EN REALIDAD LO QUE TENGO QUE HACER ES UN CURSOR DE LO QUE ESTA EN LA TABLA TEMPORAL Y POR CADA REGISTRO QUE TENGA COL_ID TENGO QUE GENERAR
		--EN CASO DE QUE NO EXISTA EL COLI_ID de la colecta
		--POR COMP_ID, COL ID e ITEM_ID

		DECLARE
			@item_id	INT,
			@stor_id	INT,
			@storp_id	INT,
			@col_id		INT,
			@initQty	INT
		DECLARE curITEMS CURSOR LOCAL FAST_FORWARD FOR
			SELECT
				ttisp.item_id,
				ttisp.stor_id,
				ttisp.storp_id,
				ttisp.col_id,
				ttisp.initQty
				FROM tbTempItemStorage_Positions_Output	AS ttisp	WITH(NOLOCK)
				WHERE	ttisp.tmpguid	= @guid			AND
						ttisp.initQty	> 0
			OPEN curITEMS
			FETCH NEXT FROM curITEMS	INTO	@item_id,
												@stor_id,
												@storp_id,
												@col_id,
												@initQty
				WHILE @@FETCH_STATUS = 0
					BEGIN
						IF @col_id IS NOT NULL
							BEGIN
								--PRIMERO TENGO QUE INSERTAR EN LA COLLECT ITEMS
								DECLARE	@lcoli_id	INT
								SET		@lcoli_id = NULL
								IF NOT EXISTS(SELECT TOP 1 1
												FROM tbSaleOrderCollectItems		AS tsoci	WITH(NOLOCK)
												WHERE	tsoci.comp_id	= @comp_id	AND
														tsoci.col_id	= @col_id	AND
														tsoci.stor_id	= @stor_id	AND
														tsoci.item_id	= @item_id)
									BEGIN
										INSERT INTO tbSaleOrderCollectItems
										(
											comp_id,
											col_id,
											stor_id,
											item_id,
											coli_qty,
											[user_id]
										)
										VALUES
										(
											@comp_id,
											@col_id,
											@stor_id,
											@item_id,
											0,
											@user_id
										)
										SET @lcoli_id = @@IDENTITY
									END

									INSERT INTO tbItemStoragePositionsTMP
									(
										comp_id,
										item_id,
										stor_id,
										storp_id,
										bra_id,
										prof_id,
										[user_id],
										tmp_cd,
										tmp_isDisabled,
										--tmp_lastUpdate,
										tmp_is4Output,
										coli_id,
										tmp_QTY
									)
									SELECT
										@comp_id,
										@item_id,
										@stor_id,
										@storp_id,
										@bra_id,
										@prof_id,
