CREATE PROCEDURE spItemStorageStockControl_getData4Grid
(
	@comp_id		INT,
	@it_transaction	INT
)
AS
	SET NOCOUNT	 ON

		BEGIN

			-- --------------------------------
			-- TESTING
			-- --------------------------------
			/*
				DECLARE
					@comp_id		INT,
					@it_transaction	INT
				SELECT
					@comp_id		= 1,
					@it_transaction	= 3305
			*/
			-- --------------------------------

			--VARIABLES DE TRABAJO
			DECLARE
				@item_id	INT,
				@stor_id	INT

			--RECUPERAMOS ITEM_ID y STOR_ID del IT_TRANSACTION
			SELECT
				@item_id = tit.item_id,
				@stor_id = tit.stor_id
			FROM tbItemTransactions							tit
			WHERE	tit.comp_id			= @comp_id			AND
					tit.it_transaction	= @it_transaction



			--INFORMAMOS LOS ULTIMOS RECUENTOS DE STOCK DEL ARTICULO
			--PARA ESE DEPOSITO Y QUIEN LO CONTROLO
			SELECT
				ti.item_code,
				ti.item_desc,
				ts.stor_desc,
				tissc.itsi_cd,
				tu.user_lastname + ',' + tu.user_firstname	[user]

			FROM tbItemStorageStockControl		tissc

				INNER JOIN tbItem				ti
				ON	ti.comp_id = tissc.comp_id	AND
					ti.item_id = tissc.item_id

				INNER JOIN tbStorage			ts
				ON	ts.comp_id = tissc.comp_id	AND
					ts.stor_id = tissc.stor_id

				INNER JOIN tbUser				tu
				ON tu.[user_id] = tissc.[user_id]

			WHERE	tissc.comp_id = @comp_id	AND
					tissc.item_id = @item_id	AND
					tissc.stor_id = @stor_id

			ORDER BY tissc.itsi_cd DESC

		END

GO



