-- =============================================
-- Author:		MOS
-- Create date: 10-2010
-- Description:	Setea el campo de iva Forzado para que el total de iva de la factura de compra
--			    de el importe que necesitamos.
-- =============================================
CREATE PROCEDURE [dbo].[spItemsTransactionsTmp_ForcedIva]
	@comp_id		AS INT,
	@guid			AS UNIQUEIDENTIFIER,
	@decForcedIva	AS DECIMAL(19,6)

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @decTotalIvaTax AS DECIMAL(19,6)
	SELECT @decTotalIvaTax = SUM(tmt.tmt_total)
		FROM tbTaxMovementsTmp tmt
	WHERE	tmt.comp_id		= @comp_id
		AND tmt.tmt_guid	= @guid

	DECLARE @decPercent AS DECIMAL(35,14)
	SET @decPercent = @decForcedIva / dbo.fnnozdiv(@decTotalIvaTax)

	UPDATE tbItemTransactionsTmp
		SET
			tis_forcedValue = ttmt.tmt_total * @decPercent
		FROM tbItemTransactionsTmp titt
		inner JOIN tbTaxMovementsTmp ttmt
			ON		ttmt.comp_id	= titt.comp_id
				AND	ttmt.tis_id		= titt.tis_id



END
GO

CREATE PROCEDURE [dbo].[spItemsUpdated_GetLastItemsUpdated]
(
	@intLastUpdatedID	INT
)
AS
BEGIN
	SET NOCOUNT ON

	DECLARE @intMaxUpdatedID AS INT = 0
	SELECT  @intMaxUpdatedID = MAX(upd_id)
			FROM tbItemsUpdated WITH (NOLOCK)

	SELECT DISTINCT
					@intMaxUpdatedID	[intLAstID],
					tiu.item_id
		FROM tbItemsUpdated AS tiu	WITH(NOLOCK)
		WHERE tiu.upd_id BETWEEN  @intLastUpdatedID AND @intMaxUpdatedID
		ORDER BY tiu.item_id

	--BEGIN TRY
	--TRUNCATE TABLE tbItemsUpdated
	--END TRY
	--BEGIN CATCH
	--END CATCH

END
GO

CREATE PROCEDURE [dbo].[spItemsUpdated_GetLastItemsUpdated4BasicQuery]
(
	@intLastUpdatedID	INT
)
AS
BEGIN
	SET NOCOUNT ON

	DECLARE @intMaxUpdatedID AS INT = 0
	SELECT  @intMaxUpdatedID = MAX(upd_id)
			FROM tbItemsUpdated WITH (NOLOCK)

	SELECT DISTINCT
					@intMaxUpdatedID	[intLAstID],
					tiu.item_id
		FROM tbItemsUpdated AS tiu	WITH(NOLOCK)
		WHERE tiu.upd_id BETWEEN  @intLastUpdatedID AND @intMaxUpdatedID
