CREATE PROCEDURE [dbo].[spItemTaxes_getCombo]
(
	@comp_id		int,
	@bra_id			int,
	@item_id		int,
	@class_type		char(1)
)
as
set nocount on


	/*
	declare @comp_id		int,
			@bra_id			int,
			@item_id		int,
		@class_type		char(1)
	select 	@comp_id		=1,
			@bra_id			=1,
			@item_id		=113,
		@class_type		=''
	*/

	If @class_type = 'T' or @class_type = ''
			Begin
				Select		IT.tax_id			[id],
							TN.tax_desc			[desc]
					From	dbo.[tbItemTaxes]							IT
					Inner join [tbTaxName]								TN
						On	TN.comp_id		= IT.comp_id
						and TN.tax_id		= IT.tax_id
					Inner Join	dbo.vwsysTaxClassALL					TTC
						On	TTC.tax_class	= TN.tax_class
					Where   IT.[comp_id]	= @comp_id
						and (IT.[bra_id]	= @bra_id OR it.bra_id IS NULL )
						and IT.[item_id]	= @item_id
					Order by IT.[tax_itemComposed]
			End
	Else
		If @class_type = 'I'
			Begin
				Select		IT.tax_id			[id],
							TN.tax_desc			[desc]
					From	dbo.[tbItemTaxes]							IT
					Inner join [tbTaxName]								TN
						On	TN.comp_id		= IT.comp_id
						and TN.tax_id		= IT.tax_id
					Inner Join	dbo.vwsysTaxClassIVA_Taxes				TTC
						On	TTC.tax_class	= TN.tax_class
					Where   IT.[comp_id]	= @comp_id
						and (IT.[bra_id]	= @bra_id OR it.bra_id IS NULL)
						and IT.[item_id]	= @item_id
					Order by IT.[tax_itemComposed]
			End
	Else
		If @class_type = 'P'
			Begin
				Select		IT.tax_id			[id],
							TN.tax_desc			[desc]
					From	dbo.[tbItemTaxes]							IT
					Inner join [tbTaxName]								TN
						On	TN.comp_id		= IT.comp_id
						and TN.tax_id		= IT.tax_id
					Inner Join	dbo.vwsysTaxClassALL_Perceptions		TTC
						On	TTC.tax_class	= TN.tax_class
					Where   IT.[comp_id]	= @comp_id
						and (IT.[bra_id]	= @bra_id OR it.bra_id IS NULL)
						and IT.[item_id]	= @item_id
					Order by IT.[tax_itemComposed]
			End
	Else
		If @class_type = 'R'
			Begin
				Select		IT.tax_id			[id],
							TN.tax_desc			[desc]
					From	dbo.[tbItemTaxes]							IT
					Inner join [tbTaxName]								TN
						On	TN.comp_id		= IT.comp_id
						and TN.tax_id		= IT.tax_id
					Inner Join	dbo.vwsysTaxClassALL_Retentions			TTC
						On	TTC.tax_class	= TN.tax_class
					Where   IT.[comp_id]	= @comp_id
						and (IT.[bra_id]	= @bra_id OR it.bra_id IS NULL)
						and IT.[item_id]	= @item_id
					Order by IT.[tax_itemComposed]
			End
	Else
		If @class_type = 'B'
			Begin
				Select		IT.tax_id			[id],
							TN.tax_desc			[desc]
					From	dbo.[tbItemTaxes]							IT
					Inner join [tbTaxName]								TN
						On	TN.comp_id		= IT.comp_id
						and TN.tax_id		= IT.tax_id
					Inner Join	dbo.vwsysTaxClassIB_Taxes				TTC
						On	TTC.tax_class	= TN.tax_class
					Where   IT.[comp_id]	= @comp_id
						and (IT.[bra_id]	= @bra_id OR it.bra_id IS NULL)
						and IT.[item_id]	= @item_id
					Order by IT.[tax_itemComposed]
			End
	Else
		If @class_type = 'G'
			Begin
				Select		IT.tax_id			[id],
							TN.tax_desc			[desc]
					From	dbo.[tbItemTaxes]							IT
					Inner join [tbTaxName]								TN
						On	TN.comp_id		= IT.comp_id
						and TN.tax_id		= IT.tax_id
					Inner Join	dbo.vwsysTaxClassGAN_Taxes				TTC
						On	TTC.tax_class	= TN.tax_class
					Where   IT.[comp_id]	= @comp_id
						and (IT.[bra_id]	= @bra_id OR it.bra_id IS NULL)
						and IT.[item_id]	= @item_id
					Order by IT.[tax_itemComposed]
			End









GO







