GO





---------------------------------------------------------------------
---------------------------------------------------------------------
--Recupero la cantidad de impuestos del articulo y que impuesto tiene
--Author : GA
--Date: 06/12/13
---------------------------------------------------------------------



CREATE PROCEDURE [dbo].[spItemTaxes_getDataById]
(
	@comp_id				int,
	@item_id				int
)
as


Set NoCount ON

BEGIN


----------------------------------------------------------------
/*
DECLARE @comp_id				int,
		@item_id				int

SELECT  @comp_id				= 1,
		@item_id				= 402
*/
----------------------------------------------------------------

	--variable para guardar la cantidad de impuestos que tiene el item
	DECLARE @lqty_tax INT

	SET @lqty_tax = 1

	set @lqty_tax = (Select count(ttn.tax_id)

							From	dbo.tbItem							ti

							Inner join  dbo.tbItemTaxes					tit
							ON  tit.comp_id = ti.comp_id	AND
								tit.item_id = ti.item_id

							INNER JOIN tbTaxName						ttn
							ON  ttn.comp_id = tit.comp_id	AND
								ttn.tax_id = tit.tax_id

							inner JOIN vwsysTaxClassIVA_Taxes			vtcit
							ON 	vtcit.tax_class = ttn.tax_class

							Where	ti.comp_id		= @comp_id
							and		ti.item_id		= @item_id

	)

	-- Si tiene mas de un impuesto asociado , selecciono el 1ro
	IF  @lqty_tax > 1


	BEGIN
					Select top 1 ttn.tax_id		[tax_id],
								 ttn.tax_desc	[tax_desc],
								 ti.item_desc	[item_desc],
								 @lqty_tax		[qty_tax]

						From	dbo.tbItem							ti

						Inner join  dbo.tbItemTaxes					tit
						ON  tit.comp_id = ti.comp_id	AND
							tit.item_id = ti.item_id

						INNER JOIN tbTaxName						ttn
						ON  ttn.comp_id = tit.comp_id	AND
							ttn.tax_id = tit.tax_id

						inner JOIN vwsysTaxClassIVA_Taxes			vtcit
						ON 	vtcit.tax_class = ttn.tax_class

						Where	ti.comp_id		= @comp_id
						and		ti.item_id		= @item_id

	END

	ELSE

		-- Si tiene un solo iva asociado
		BEGIN
						Select	ttn.tax_id		[tax_id],
								ttn.tax_desc	[tax_desc],
								ti.item_desc	[item_desc],
								@lqty_tax		[qty_tax]

							From	dbo.tbItem							ti

							Inner join  dbo.tbItemTaxes					tit
							ON  tit.comp_id = ti.comp_id	AND
								tit.item_id = ti.item_id

							INNER JOIN tbTaxName						ttn
							ON  ttn.comp_id = tit.comp_id	AND
								ttn.tax_id = tit.tax_id

							inner JOIN vwsysTaxClassIVA_Taxes			vtcit
							ON 	vtcit.tax_class = ttn.tax_class

							Where	ti.comp_id		= @comp_id
							and		ti.item_id		= @item_id

		END



End
















GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2019
-- Description:	Obtiene datos para el control
--		        de precios.-
-- Lo que busca es UN porcentaje de IVA y
-- de Impuestos Internos
-- class_id = 1 y 20 en un mismo renglon.
-- =============================================

CREATE  PROCEDURE [dbo].[spItemTaxes_getDataByIdCoeficient]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@item_id	AS INT
AS

/*
DECLARE 	@comp_id	AS INT
DECLARE 	@bra_id		AS INT
DECLARE 	@item_id	AS INT
SET @comp_id = 1
SET @bra_id = 1
SET @item_id=223
*/

BEGIN

	SET NOCOUNT ON;


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	DECLARE @decCoeficient AS DECIMAL(30,15) = 0
	DECLARE @decPercen	   AS DECIMAL(30,15) = 0

	SELECT	@decCoeficient = ttn.tax_percentage / 100,
			@decPercen	   = ttn.tax_percentage
		FROM vwItemTaxesOnlyOneIvaTax	vitooit	WITH (NOLOCK)
		INNER JOIN tbTaxName			ttn		WITH (NOLOCK)
			ON	ttn.comp_id		= vitooit.comp_id AND
				ttn.tax_id		= vitooit.tax_id
		WHERE	vitooit.comp_id = @comp_id			AND
				vitooit.item_id = @item_id

	SELECT	@decCoeficient 				[Coeficient],
			@decPercen					[Percentaje]


END
GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2009
-- Description:	Obtiene datos para el control
--		        de precios.-
-- Lo que busca es UN porcentaje de IVA y
-- de Impuestos Internos
-- class_id = 1 y 20 en un mismo renglon.
-- =============================================

CREATE  PROCEDURE [dbo].spItemTaxes_getDataByIdCoeficient4Combo
	@comp_id	AS INT,
	@bra_id		AS INT,
	@item_id	AS INT,
	@prli_id	AS INT
AS

/*
DECLARE 	@comp_id	AS INT
DECLARE 	@bra_id		AS INT
DECLARE 	@item_id	AS INT
SET @comp_id = 1
SET @bra_id = 1
SET @item_id=223
*/

BEGIN

	SET NOCOUNT ON;


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	DECLARE @decCoeficient AS DECIMAL(30,15) = 0

	SET		@decCoeficient = dbo.fnGetPriceListItemTaxesCoeficient4Combo(@comp_id,@bra_id,@item_id, @prli_id)

	SELECT	@decCoeficient 				[Coeficient],
			(@decCoeficient - 1) * 100	[Percentaje]


END
GO



CREATE PROCEDURE spItemTaxes_getOnlyOneIvaTax
(
	@comp_id	INT,
	@item_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			vitooit.comp_id,
			vitooit.item_id,
			vitooit.tax_id
			FROM vwItemTaxesOnlyOneIvaTax vitooit
			WHERE	vitooit.comp_id = @comp_id AND
					vitooit.item_id = @item_id
	END



GO





CREATE PROCEDURE [dbo].[spItemTaxes_getTaxesbyBranch]
(
	@comp_id	int,
	@item_id	INT,
	@bra_id		INT
)
AS
BEGIN

	SET NOCOUNT ON

	/*
	DECLARE
		@comp_id	INT,
		@item_id	INT,
		@bra_id		INT

	SELECT
		@comp_id	= 1,
		@item_id	= 222,
		@bra_id		= 5
	*/

	SELECT
		tit.tax_DummyId [Id],
		case
			when tit.tax_itemComposed = 'true' THEN '(*)'
			ELSE '(-) '
		END + ' ' +
		ttn.tax_desc + ' - ' +
		isnull(tb.bra_desc,'All/Todas')  [desc]

	FROM	dbo.tbItemTaxes tit

	INNER JOIN	dbo.tbTaxName ttn
	ON		ttn.comp_id	= tit.comp_id
	AND		ttn.tax_id	= tit.tax_id

	LEFT JOIN	dbo.tbBranch tb
	ON		tb.comp_id	= tit.comp_id
	AND		tb.bra_id	= tit.bra_id


	WHERE	tit.comp_id = @comp_id
	AND		tit.item_id = @item_id
	AND		(tit.bra_id	IS NULL or tit.bra_id	= @bra_id)

END
GO





CREATE PROCEDURE [dbo].[spItemTaxes_insertData]
(
	@comp_id	INT,
	@item_id	INT,
	@tax_id		INT,
	@bra_id		INT,
	@it_comp	BIT
)
AS

BEGIN


	set nocount on

	/*
	DECLARE
		@comp_id	INT,
		@item_id	INT,
		@tax_id		INT,
		@bra_id		INT,
		@it_comp	BIT

	SELECT
		@comp_id	=1,
		@item_id	=220,
		@tax_id		=9,
		@bra_id		=1,
		@it_comp	='False'
	*/


	-- Saca la clase del nuevo impuesto a asignar.
	declare @intTaxClassNEW  AS INT
	SELECT @intTaxClassNEW	= tax_class
		FROM tbTaxName ttn
		WHERE	ttn.comp_id = @comp_id
			AND ttn.tax_id	= @tax_id

	IF	-- Si ya hay algun impuesto igual para todas las sucursales
		NOT EXISTS(	SELECT TOP 1  1
	              		FROM tbItemTaxes tit
	              		WHERE	tit.comp_id = @comp_id
	              			AND tit.item_id = @item_id
	              			AND tit.tax_id	= @tax_id
	              			AND tit.bra_id IS NULL)
		AND
		-- Si y HAY algun impuesto y trato de poner uno para todas las sucursales.
		NOT EXISTS(	SELECT TOP 1  1
	              				FROM tbItemTaxes tit
	              				WHERE	tit.comp_id = @comp_id
	              					AND tit.item_id = @item_id
	              					AND tit.tax_id	= @tax_id
	              					AND tit.bra_id	IS NOT NULL
									AND @bra_id		IS NULL)
		AND
		-- Que no exista un impuesto de la misma clase y que sea de la misma caracteristica de composicion, o sea, que no deje poner dos impuestos pára itemns fabricados del MISMO tipo.!
		NOT EXISTS(
					SELECT TOP 1  1
						FROM tbItemTaxes tit
						INNER JOIN tbTaxName ttn
							ON		ttn.comp_id = tit.comp_id
								AND ttn.tax_id	= tit.tax_id
						WHERE	tit.comp_id		= @comp_id
							AND	tit.item_id		= @item_id
							AND ttn.tax_class	= @intTaxClassNEW
							AND tit.tax_id		<> @tax_id
							AND (tit.bra_id IS NULL OR tit.bra_id = @bra_id)
							AND tit.tax_itemComposed = @it_comp

					)

		BEGIN

			DECLARE @tax_class INT = NULL
			SELECT  @tax_class = ttn.tax_class
				FROM tbTaxName AS ttn	WITH (NOLOCK)
				WHERE	ttn.comp_id = @comp_id AND
						ttn.tax_id	= @tax_id


			insert into	dbo.tbItemTaxes
			(comp_id,
			 item_id,
			 tax_id,
			 bra_id,
			 tax_itemComposed,
			 tax_class)

			values
			(@comp_id,
			@item_id,
			@tax_id,
			@bra_id,
			@it_comp,
			@tax_class)
		END



END
GO


CREATE PROCEDURE [dbo].[spItemTaxes_ReplaceTaxes4Items]
(
	@comp_id		INT,
	@lguid			UNIQUEIDENTIFIER,
	@tax_id_From	INT,
	@tax_id_To		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- --------------------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lguid			UNIQUEIDENTIFIER,
				@tax_id_From	INT,
				@tax_id_To		INT

			SELECT
				@comp_id		= 1,
				@lguid			= '7B370139-75C6-425A-B9CB-7C900057E31E',
				@tax_id_From	= 2,
				@tax_id_To		= 1
		*/
		-- --------------------------------------------------------------------------


		-- ---------------------------
		-- VARIABLES DE TRABAJO
		-- ---------------------------
		DECLARE	@CanProcess	BIT
		SET		@CanProcess = 'True'
		-- ---------------------------

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuid     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				SET @CanProcess = 'False'
			END
		--==
			--SELECT * FROM @tblComplexFilter_Items
			--SELECT @CanProcess
		--==
		-- -------------------------------------------------------------

		IF @CanProcess = 'True'
			BEGIN
				--ACA HAGO EL UPDATE
				UPDATE tbItemTaxes
				SET
					tax_id		= @tax_id_To,
					tax_class	= ttn.tax_class
				FROM tbItemTaxes					tit	WITH(NOLOCK)
				INNER JOIN tbTaxName			AS  ttn	WITH (NOLOCK)
					ON ttn.comp_id = tit.comp_id	AND
					   ttn.tax_id  = @tax_id_To
				INNER JOIN @tblComplexFilter_Items	tmp
					ON tmp.item_id = tit.item_id
				WHERE	tit.comp_id = @comp_id AND
						tit.tax_id	= @tax_id_From
			END
	END
GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2009
-- Description:	Obtiene datos para el control
--		        de precios.-
-- Lo que busca es UN porcentaje de IVA y
-- de Impuestos Internos
-- class_id = 1 y 20 en un mismo renglon.
-- =============================================

CREATE PROCEDURE [dbo].[spItemTaxes_TaxPercentageByItemId]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@item_id	AS INT
AS

/*
DECLARE 	@comp_id	AS INT
DECLARE 	@bra_id		AS INT
DECLARE 	@item_id	AS INT
SET @comp_id = 1
SET @bra_id = 1
SET @item_id=223
*/

BEGIN

	SET NOCOUNT ON;


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	SELECT  TOP 1
		ti.item_id								[item_id],
		(isnull(ttn1.tax_percentage,0))			[tax_percent],
		(isnull(tmpTBItemTaxes.ii_percent,0))	[ii_percent]

		FROM tbItem ti							WITH (NOLOCK)
		left JOIN vwItemTaxes tit1				WITH (NOLOCK)
			ON tit1.comp_id		= @comp_id
			AND tit1.item_id	= ti.item_id
		left JOIN tbTaxName ttn1				WITH (NOLOCK)
			ON ttn1.comp_id		= @comp_id
			AND ttn1.tax_id		= tit1.tax_id
			AND ttn1.tax_class	= 1

		INNER JOIN
		(
			SELECT TOP 1 tmpti.item_id,isnull(tmpttn.tax_percentage,0) [ii_percent]
				FROM tbItem tmpti								WITH (NOLOCK)
				left join  tbItemTaxes tmpit					WITH (NOLOCK)
					ON	tmpit.comp_id = tmpti.comp_id AND
						tmpit.item_id = tmpti.item_id AND
					  ( isnull(tmpit.bra_id,-1) = -1 OR tmpit.bra_id = @bra_id )
				left JOIN tbTaxName tmpttn						WITH (NOLOCK)
					ON	tmpttn.tax_class	= 20			and
						tmpttn.comp_id		= tmpit.comp_id AND
						tmpttn.tax_id		= tmpit.tax_id
				WHERE	tmpti.comp_id = @comp_id AND
						tmpti.item_id = @item_id
				ORDER BY tmpttn.tax_percentage DESC
		) tmpTBItemTaxes
		ON tmpTBItemTaxes.item_id = ti.item_id


	WHERE ti.comp_id = @comp_id
		AND ti.item_id = @item_id
		AND (isnull(tit1.bra_id,-1) = -1 OR tit1.bra_id = @bra_id)


END
GO





