------------------------------------------------------------------



CREATE PROCEDURE [dbo].[spItemTaxes_UpdateTax]
(
	@comp_id		int,
	@item_id		int,
	@tax_id			int
)
as
set nocount ON


--------------------------------------------------------
/*
DECLARE @comp_id    INT,
		@item_id	INT,
		@tax_id		INT


SELECT 	@comp_id	= 1,
		@item_id	= 220,
		@tax_id		= 1
*/
--------------------------------------------------------


BEGIN

	IF	(SELECT COUNT(*)
			FROM tbItemTaxes AS tit
				WHERE	comp_id		= @comp_id	AND
						item_id		= @item_id) = 1
		BEGIN
			UPDATE tbItemTaxes
				SET	tax_id		= @tax_id,
					tax_class	= ttn.tax_class
			FROM tbItemTaxes AS tit
			INNER JOIN tbTaxName AS ttn
				ON	ttn.tax_id		= @tax_id AND
					ttn.comp_id		= tit.comp_id
			WHERE	tit.comp_id		= @comp_id
			AND		tit.item_id		= @item_id

		END








END





GO








