CREATE PROCEDURE [dbo].[spItemTmp_getDataByFilters]
(
	@comp_id			INT,

	--@item_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@prli_id			INT,
	--@brand_id			INT,
	@bra_id				INT,
	--@cat_id			INT,
	--@subcat_id		INT,
	--@pres_id			INT,
	@CF_Guid			UNIQUEIDENTIFIER,
	@showtable			BIT,
	@withTaxes			INT
)
AS

BEGIN

	SET NOCOUNT ON
	-- ---------------------------------------------------------------
	-- TESTING
	-- ---------------------------------------------------------------
	/*
	DECLARE
		@comp_id			INT,
		@item_id			INT,
		@guid				UNIQUEIDENTIFIER,
		@prli_id			INT,
		@brand_id			INT,
		@bra_id				INT,
		@cat_id				INT,
		@subcat_id			INT,
		@pres_id			INT,
		@showtable			BIT,
		@withTaxes			INT,
		@CF_Guid			UNIQUEIDENTIFIER


	SELECT
		@comp_id			=  1,
		@item_id			= -1,
		@guid				= 'e761ec49-adbd-4e7d-9f9b-33f0af7e990e',
		@bra_id				= -1,
		@prli_id			=  1,
		@brand_id			= -1,
		@cat_id				= -1,
		@subcat_id			= -1,
		@pres_id			= -1,
		@showtable			= 'True',
		@withTaxes			= 0,
		@CF_Guid			= '2fb47b1e-aea7-4a97-9d21-6fd83dd68ac9'
	*/
	-- ---------------------------------------------------------------

	DECLARE @lCF_Guid AS UNIQUEIDENTIFIER
	SET @lCF_Guid = CONVERT(UNIQUEIDENTIFIER,@CF_Guid)

	-- ------------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros
	-- ------------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf		WITH (NOLOCK)
				WHERE tcf.sl_guid = @lCF_Guid     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti		WITH (NOLOCK)
						WHERE ti.comp_id = @comp_id
			END
	-- ------------------------------------------------------------------

	SELECT
		DISTINCT
			' '										[ ],
			' '										[ ],
			CASE WHEN tit.guid IS NULL THEN
				CONVERT(BIT,'False')
			ELSE
				CONVERT(BIT,'True')
			END										[Checked],
			ISNULL(tit.qty2Print,0)					[qty2Print],
			ti.item_code,
			ti.item_desc,
			CONVERT(VARCHAR(250),ti.item_detail)	[item_detail], -- tk 10176
			--ti.item_detail,
			ti.item_id
			FROM	tbItem							ti		WITH (NOLOCK)
				LEFT JOIN dbo.tbItemTmp				tit		WITH (NOLOCK)
				ON  tit.comp_id = ti.comp_id		AND
					tit.item_id = ti.item_id		AND
					tit.guid    = @guid
				LEFT JOIN tbPriceListItems			tpli		WITH (NOLOCK)
				ON  tpli.comp_id = ti.comp_id		AND
					tpli.item_id = ti.item_id		AND
					(
						@prli_id	 = -1		OR
						tpli.prli_id = @prli_id
					)
				--JOIN AGREGADO CON LA TABLA DE COMPLEX FILTERS
				INNER JOIN @tblComplexFilter_Items	tmp
					ON tmp.item_id	= ti.item_id
			WHERE	ti.comp_id  = @comp_id							AND
					--(@item_id	= -1 OR ti.item_id   = @item_id)	AND
					(@bra_id	= -1 OR ti.bra_id	 = @bra_id)		--AND
					--(@cat_id	= -1 OR ti.cat_id	 = @cat_id)		AND
					--(@subcat_id = -1 OR ti.subcat_id = @subcat_id)	AND
					--(@brand_id  = -1 OR ti.brand_id  = @brand_id)	AND
					--(@pres_id   = -1 OR ti.pres_id   = @pres_id)
			ORDER BY ti.item_code

	IF @showtable = 'True'
		BEGIN
			SELECT
				tit.comp_id,
				tit.item_id,
				tit.guid,
				ti.item_code,
				ti.item_vendorCode,
				ti.item_desc,
				ti.item_detail,
				--ttn.tax_percentage,
				--rtrim(ltrim(tc.curr_symbol)) + ' ' + convert(varchar,tpli.prli_price),

			   -- Precio con Moneda del item
			   CASE WHEN @withTaxes = 0 THEN
					RTRIM(LTRIM(tc.curr_symbol)) + ' ' +
   						CONVERT(VARCHAR,tpli.prli_price)
				 ELSE
	 				RTRIM(LTRIM(tc.curr_symbol)) + ' ' +
	 					CONVERT(VARCHAR,(CONVERT(DECIMAL(19,5),tpli.prli_price) + CONVERT(DECIMAL(19,5),ROUND(SUM(tpli.prli_price * ttn.tax_percentage /100),5))))
			   END										[prli_price],


			  -- Precio con Moneda del item con 2 decimales y con el signo "$"
			   CASE WHEN @withTaxes = 0 THEN
					RTRIM(LTRIM('$')) + ' ' +
   						CONVERT(VARCHAR,(CONVERT(DECIMAL(19,2),tpli.prli_price)))
				 ELSE
	 				RTRIM(LTRIM('$')) + ' ' +
	 					CONVERT(VARCHAR,(CONVERT(DECIMAL(19,2),tpli.prli_price) + CONVERT(DECIMAL(19,2),ROUND(SUM(tpli.prli_price * ttn.tax_percentage /100),2))))
			   END										[prli_price2dec],

			   -- Precio con Moneda de la lista
			   CASE WHEN @withTaxes = 0 THEN
					RTRIM(LTRIM(tcpli.curr_symbol)) + ' ' +
   						CONVERT(VARCHAR,tpli.prli_price)
				 ELSE
	 				RTRIM(LTRIM(tcpli.curr_symbol)) + ' ' +
	 					CONVERT(VARCHAR,(CONVERT(DECIMAL(19,5),tpli.prli_price) + CONVERT(DECIMAL(19,5),ROUND(SUM(tpli.prli_price * ttn.tax_percentage /100),5))))
			   END										[prli_price_curPLI],

			   -- Precio con Moneda de la lista  con 2 decimales y con el signo "$"
			   CASE WHEN @withTaxes = 0 THEN
					RTRIM(LTRIM('$')) + ' ' +
   						CONVERT(VARCHAR,(CONVERT(DECIMAL(19,2),tpli.prli_price)))
				 ELSE
	 				RTRIM(LTRIM('$')) + ' ' +
	 					CONVERT(VARCHAR,(CONVERT(DECIMAL(19,2),tpli.prli_price) + CONVERT(DECIMAL(19,2),ROUND(SUM(tpli.prli_price * ttn.tax_percentage /100),2))))
			   END										[prli_price2dec_curPLI],


			   -- Precio con Moneda del item con 2 decimales y en ARS
			   CASE WHEN @withTaxes = 0 THEN
					RTRIM(LTRIM('$')) + ' ' +
   						CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),dbo.fnGetExchange2(@comp_id,(CONVERT(DECIMAL(19,2),tpli.prli_price)), tc.curr_id, /*ARS*/ 1, 0,0,0,'False')))
				 ELSE
	 					RTRIM(LTRIM('$')) + ' ' +
	 					CONVERT(VARCHAR, (CONVERT(DECIMAL(19,2),dbo.fnGetExchange2(@comp_id,CONVERT(DECIMAL(19,2),tpli.prli_price),tc.curr_id, 1,0,0,0,'False'))) +
	 					CONVERT(DECIMAL(19,2),ROUND(SUM(dbo.fnGetExchange2(@comp_id,CONVERT(DECIMAL(19,2),tpli.prli_price),tc.curr_id, 1,0,0,0,'False') * ttn.tax_percentage /100),2)))


				 END										[prli_price2dec_ARS],

				isnull(ti.impData_Custom_origin,'')			[Origin],

				tc2.cat_desc,
				tsc.subcat_desc,
				tb.brand_desc,
				ISNULL(tc1.color_desc,'')				[color_desc],
				ISNULL(ts1.Size_desc,'')				[size_desc],
				ISNULL(tit.qty2Print,0)					[qty2Print],
				ISNULL(tba.bra_desc,'')					[branch_desc]

			FROM tbItemTmp									tit			WITH (NOLOCK)

				INNER JOIN tbItem							ti			WITH (NOLOCK)
				ON  ti.comp_id		= tit.comp_id			AND
					ti.item_id		= tit.item_id

				LEFT JOIN tbBranch							tba			WITH (NOLOCK)
				ON  tba.comp_id		= ti.comp_id			AND
				    tba.bra_id		= ti.bra_id

				--LEFT JOIN tbSupplier						ts			WITH (NOLOCK)
				--ON	ts.comp_id		= ti.comp_id			AND
				--	ts.supp_id		= ti.supp_id

				--LEFT JOIN tbsysCountry tc
				--ON tc.country_id	= ts.country_id

				--JOIN CON LA TABLA DE COMPLEX FILTERS
				INNER JOIN @tblComplexFilter_Items			tmp
					ON tmp.item_id		= ti.item_id

				LEFT JOIN tbPriceListItems					tpli		WITH (NOLOCK)
					ON  tpli.comp_id	= ti.comp_id		AND
						tpli.item_id	= ti.item_id		AND
						tpli.prli_id	= @prli_id

				LEFT JOIN tbsysCurrency						tcpli		WITH (NOLOCK)
				ON	tcpli.curr_id			= tpli.curr_id

				LEFT JOIN tbsysCurrency						tc			WITH (NOLOCK)
					ON	tc.curr_id		= ti.curr_id
				LEFT JOIN tbItemTaxes						tit2		WITH (NOLOCK)
					ON  tit2.comp_id	= tit.comp_id		AND
						tit2.item_id	= tit.item_id
				LEFT JOIN tbTaxName							ttn			WITH (NOLOCK)
					ON  ttn.comp_id		= tit.comp_id		AND
						ttn.tax_id		= tit2.tax_id
				INNER JOIN tbCategory						tc2			WITH (NOLOCK)
					ON	tc2.comp_id		= ti.comp_id		AND
						tc2.cat_id		= ti.cat_id
				INNER JOIN tbSubCategory					tsc			WITH (NOLOCK)
					ON	tsc.comp_id		= ti.comp_id		AND
						tsc.subcat_id	= ti.subcat_id
				INNER JOIN tbBrand							tb			WITH (NOLOCK)
					ON	tb.comp_id		= ti.comp_id		AND
						tb.brand_id		= ti.brand_id
				LEFT JOIN tbItemSizeColorRelation			tiscr		WITH (NOLOCK)
					ON	tiscr.comp_id		= tit.comp_id	AND
						tiscr.item_id_child	= tit.item_id
				LEFT JOIN tbColor							tc1			WITH (NOLOCK)
					ON	tc1.comp_id			= tit.comp_id	AND
						tc1.color_id		= tiscr.color_id
				LEFT JOIN tbSize							ts1			WITH (NOLOCK)
					ON	ts1.comp_id			= tit.comp_id	AND
						ts1.Size_id			= tiscr.size_id

			WHERE	tit.comp_id				= @comp_id		AND
					tit.guid				= @guid

			GROUP BY
					tit.comp_id,
					tit.item_id,
					tit.guid,
					ti.item_code,
					ti.item_desc,
					ti.item_detail,
					tc.curr_id,
					tc.curr_symbol,
					tcpli.curr_symbol,
					tpli.prli_price,
					tc2.cat_desc,
					tsc.subcat_desc,
					tb.brand_desc,
					tc1.color_desc,
					ts1.Size_desc,
					item_vendorCode,
					ti.impData_Custom_origin,
					tit.qty2Print,
					tba.bra_desc
		END
END
GO


CREATE PROCEDURE [dbo].[spItemTmp_getDataByFilters_ForItemPartsByItemID]
(
	@comp_id			INT,

	@item_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@prli_id			INT,
	--@brand_id			INT,
	@bra_id				INT,
	--@cat_id			INT,
	--@subcat_id		INT,
	--@pres_id			INT,
	@CF_Guid			UNIQUEIDENTIFIER,
	@showtable			BIT,
	@withTaxes			INT
)
AS

BEGIN

	SET NOCOUNT ON
	-- ---------------------------------------------------------------
	-- TESTING
	-- ---------------------------------------------------------------
	/*
	DECLARE
		@comp_id			INT,
		@item_id			INT,
		@guid				UNIQUEIDENTIFIER,
		@prli_id			INT,
		@brand_id			INT,
		@bra_id				INT,
		@cat_id				INT,
		@subcat_id			INT,
		@pres_id			INT,
		@showtable			BIT,
		@withTaxes			INT,
		@CF_Guid			UNIQUEIDENTIFIER,
		@bitPrintParts		BIT

	SELECT
		@comp_id			=  1,
		@item_id			=  17,
		@guid				= '05BB3865-D0AD-4094-8942-3C9CDE107071',
		@bra_id				= -1,
		@prli_id			=  1,
		@brand_id			= -1,
		@cat_id				= -1,
		@subcat_id			= -1,
		@pres_id			= -1,
		@showtable			= 'True',
		@withTaxes			= 0,
		@CF_Guid			= '2fb47b1e-aea7-4a97-9d21-6fd83dd68ac9',
		@bitPrintParts		= 'False'
	*/
	-- ---------------------------------------------------------------

	DECLARE @lCF_Guid AS UNIQUEIDENTIFIER
	SET @lCF_Guid = CONVERT(UNIQUEIDENTIFIER,@CF_Guid)

	DECLARE @lintItemTotalParts AS INT = 0
	DECLARE @lintItemPartNumber AS INT = 0

	SELECT
			@lintItemTotalParts = COUNT(*)
	FROM	tbItemParts				AS tip	WITH(NOLOCK)
	WHERE	tip.comp_id = @comp_id	AND
			tip.item_id = @item_id


	-- ------------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros
	-- ------------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf		WITH (NOLOCK)
				WHERE tcf.sl_guid = @lCF_Guid     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti		WITH (NOLOCK)
						WHERE ti.comp_id = @comp_id
			END
	-- ------------------------------------------------------------------
	SELECT

		tit.comp_id,
		tit.item_id,
		tit.guid,
		ti.item_code,
		ti.item_vendorCode,
		ti.item_desc,
		ti.item_detail,
		--ttn.tax_percentage,
		--rtrim(ltrim(tc.curr_symbol)) + ' ' + convert(varchar,tpli.prli_price),

		-- Precio con Moneda del item
		CASE WHEN @withTaxes = 0 THEN
			RTRIM(LTRIM(tc.curr_symbol)) + ' ' +
   				CONVERT(VARCHAR,tpli.prli_price)
			ELSE
	 		RTRIM(LTRIM(tc.curr_symbol)) + ' ' +
	 			CONVERT(VARCHAR,(CONVERT(DECIMAL(19,5),tpli.prli_price) + CONVERT(DECIMAL(19,5),ROUND(SUM(tpli.prli_price * ttn.tax_percentage /100),5))))
		END										[prli_price],


		-- Precio con Moneda del item con 2 decimales y con el signo "$"
		CASE WHEN @withTaxes = 0 THEN
			RTRIM(LTRIM('$')) + ' ' +
   				CONVERT(VARCHAR,(CONVERT(DECIMAL(19,2),tpli.prli_price)))
			ELSE
	 		RTRIM(LTRIM('$')) + ' ' +
	 			CONVERT(VARCHAR,(CONVERT(DECIMAL(19,2),tpli.prli_price) + CONVERT(DECIMAL(19,2),ROUND(SUM(tpli.prli_price * ttn.tax_percentage /100),2))))
		END										[prli_price2dec],

		-- Precio con Moneda de la lista
		CASE WHEN @withTaxes = 0 THEN
			RTRIM(LTRIM(tcpli.curr_symbol)) + ' ' +
   				CONVERT(VARCHAR,tpli.prli_price)
			ELSE
	 		RTRIM(LTRIM(tcpli.curr_symbol)) + ' ' +
	 			CONVERT(VARCHAR,(CONVERT(DECIMAL(19,5),tpli.prli_price) + CONVERT(DECIMAL(19,5),ROUND(SUM(tpli.prli_price * ttn.tax_percentage /100),5))))
		END										[prli_price_curPLI],

		-- Precio con Moneda de la lista  con 2 decimales y con el signo "$"
		CASE WHEN @withTaxes = 0 THEN
			RTRIM(LTRIM('$')) + ' ' +
   				CONVERT(VARCHAR,(CONVERT(DECIMAL(19,2),tpli.prli_price)))
			ELSE
	 		RTRIM(LTRIM('$')) + ' ' +
	 			CONVERT(VARCHAR,(CONVERT(DECIMAL(19,2),tpli.prli_price) + CONVERT(DECIMAL(19,2),ROUND(SUM(tpli.prli_price * ttn.tax_percentage /100),2))))
		END										[prli_price2dec_curPLI],


		-- Precio con Moneda del item con 2 decimales y en ARS
		CASE WHEN @withTaxes = 0 THEN
			RTRIM(LTRIM('$')) + ' ' +
   				CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),dbo.fnGetExchange2(@comp_id,(CONVERT(DECIMAL(19,2),tpli.prli_price)), tc.curr_id, /*ARS*/ 1, 0,0,0,'False')))
			ELSE
	 			RTRIM(LTRIM('$')) + ' ' +
	 			CONVERT(VARCHAR, (CONVERT(DECIMAL(19,2),dbo.fnGetExchange2(@comp_id,CONVERT(DECIMAL(19,2),tpli.prli_price),tc.curr_id, 1,0,0,0,'False'))) +
	 			CONVERT(DECIMAL(19,2),ROUND(SUM(dbo.fnGetExchange2(@comp_id,CONVERT(DECIMAL(19,2),tpli.prli_price),tc.curr_id, 1,0,0,0,'False') * ttn.tax_percentage /100),2)))


			END										[prli_price2dec_ARS],

		isnull(ti.impData_Custom_origin,'')			[Origin],

		tc2.cat_desc,
		tsc.subcat_desc,
		tb.brand_desc,
		ISNULL(tc1.color_desc,'')				[color_desc],
		ISNULL(ts1.Size_desc,'')				[size_desc],
		ISNULL(tit.qty2Print,0)					[qty2Print],

		tip.itp_EAN, tip.itp_desc,

		CONVERT(VARCHAR,@lintItemPartNumber + ROW_NUMBER() OVER( ORDER BY tit.item_id ))
		+ ' / ' +
		CONVERT(VARCHAR,@lintItemTotalParts)	[Item_PartNumber]


	FROM tbItemTmp									tit			WITH (NOLOCK)

		INNER JOIN tbItem							ti			WITH (NOLOCK)
		ON  ti.comp_id		= tit.comp_id			AND
			ti.item_id		= tit.item_id

		--JOIN CON LA TABLA DE COMPLEX FILTERS
		INNER JOIN @tblComplexFilter_Items			tmp
			ON tmp.item_id		= ti.item_id

		LEFT JOIN tbPriceListItems					tpli		WITH (NOLOCK)
			ON  tpli.comp_id	= ti.comp_id		AND
				tpli.item_id	= ti.item_id		AND
				tpli.prli_id	= @prli_id

		LEFT JOIN tbsysCurrency						tcpli		WITH (NOLOCK)
		ON	tcpli.curr_id			= tpli.curr_id

		LEFT JOIN tbsysCurrency						tc			WITH (NOLOCK)
			ON	tc.curr_id		= ti.curr_id
		LEFT JOIN tbItemTaxes						tit2		WITH (NOLOCK)
			ON  tit2.comp_id	= tit.comp_id		AND
				tit2.item_id	= tit.item_id
		LEFT JOIN tbTaxName							ttn			WITH (NOLOCK)
			ON  ttn.comp_id		= tit.comp_id		AND
				ttn.tax_id		= tit2.tax_id
		INNER JOIN tbCategory						tc2			WITH (NOLOCK)
			ON	tc2.comp_id		= ti.comp_id		AND
				tc2.cat_id		= ti.cat_id
		INNER JOIN tbSubCategory					tsc			WITH (NOLOCK)
			ON	tsc.comp_id		= ti.comp_id		AND
				tsc.subcat_id	= ti.subcat_id
		INNER JOIN tbBrand							tb			WITH (NOLOCK)
			ON	tb.comp_id		= ti.comp_id		AND
				tb.brand_id		= ti.brand_id
		LEFT JOIN tbItemSizeColorRelation			tiscr		WITH (NOLOCK)
			ON	tiscr.comp_id		= tit.comp_id	AND
				tiscr.item_id_child	= tit.item_id
		LEFT JOIN tbColor							tc1			WITH (NOLOCK)
			ON	tc1.comp_id			= tit.comp_id	AND
				tc1.color_id		= tiscr.color_id
		LEFT JOIN tbSize							ts1			WITH (NOLOCK)
			ON	ts1.comp_id			= tit.comp_id	AND
				ts1.Size_id			= tiscr.size_id

		LEFT JOIN tbItemParts						AS tip		WITH(NOLOCK)
		ON	tip.comp_id				= ti.comp_id AND
			tip.item_id				= ti.item_id



	WHERE	tit.comp_id				= @comp_id		AND
			tit.guid				= @guid			AND
			tit.item_id				= @item_id

	GROUP BY
			tit.comp_id,
			tit.item_id,
			tit.guid,
			ti.item_code,
			ti.item_desc,
			ti.item_detail,
			tc.curr_id,
			tc.curr_symbol,
			tcpli.curr_symbol,
			tpli.prli_price,
			tc2.cat_desc,
			tsc.subcat_desc,
			tb.brand_desc,
			tc1.color_desc,
			ts1.Size_desc,
			item_vendorCode,
			ti.impData_Custom_origin,
			tit.qty2Print,
			tip.itp_EAN,
			tip.itp_desc

END
GO




CREATE PROCEDURE [dbo].[spItemTmp_Insertdata]
(
	@comp_id			INT,
	@bra_id				INT,
	--@brand_id			INT,
	@prli_id			INT,
	--@cat_id			INT,
	--@subcat_id		INT,
	@item_id			INT,
	--@pres_id			INT,
	@CF_Guid			UNIQUEIDENTIFIER,
	@guid				UNIQUEIDENTIFIER,
	@option				BIT,				--TRUE = MARCAR TODOS // FALSE = DESMARCAR TODOS
	@showtable          BIT,
	@withTaxes			INT
)
AS
BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------
	-- Testing
	-- -----------------------------------------------------
		/*
		DECLARE 	@comp_id			INT,
					@item_id			INT,
					@prli_id			INT,
					@brand_id			INT,
					@bra_id				INT,
					@cat_id				INT,
					@subcat_id			INT,
					@pres_id			INT,
					@guid				UNIQUEIDENTIFIER,
					@option BIT,
					@showtable bit

		SELECT      @comp_id  =  1,
					@item_id  = -1,
					@guid	  = '5CD6FD5B-165E-4496-9CAE-9B9217F7B5C7',
					@bra_id   = -1,
					@prli_id  = -1,
					@brand_id = -1,
					@cat_id   = -1,
					@subcat_id= -1,
					@pres_id  = -1,
					@showtable='false',
 					@option =  'false'

		--DROP TABLE #tmp
		*/
	-- -----------------------------------------------------

	DECLARE @lCF_Guid AS UNIQUEIDENTIFIER
	SET @lCF_Guid = CONVERT(UNIQUEIDENTIFIER,@CF_Guid)

	-- ------------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros
	-- ------------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lCF_Guid     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
	-- ------------------------------------------------------------------

	IF @item_id = -1
		BEGIN
  			IF @option = 'True'
				BEGIN
					DELETE FROM tbItemTmp
					WHERE	comp_id = @comp_id	AND
							guid    = @guid
					--DROP TABLE #tmp
						CREATE TABLE #tmp (
										[a]						[VARCHAR](1),
										[b]						[VARCHAR](1),
										[checked]               [bit],
										[qty2Print]				[INT],
										[item_code]				[varchar](200)	null,
										[item_desc]				[varchar](200)	null,
										[item_detail]			[varchar](250)	null, -- tk 10176
										[item_id]				[int])
						INSERT #tmp
						(
							[a],
							[b],
							[checked],
							[qty2Print],
							[item_code],
							[item_desc],
							[item_detail],
							[item_id])
						EXEC  [spItemTmp_getDataByFilters]  @comp_id,	@guid,		@prli_id,	@bra_id,
															@CF_Guid,	@showtable,	@withTaxes

		--				EXEC  [spItemTmp_getDataByFilters] @comp_id,	@item_id,	@guid,		@prli_id,
		--												   @brand_id,	@bra_id,	@cat_id,	@subcat_id,
		--												   @pres_id,	@showtable,	@withTaxes


					INSERT INTO tbItemTmp
					(
						comp_id,
						item_id,
						guid
					)

					 SELECT
						@comp_id,
						ti.item_id,
						@guid
					 FROM #tmp ti
				END
			ELSE
				BEGIN
  					DELETE FROM tbItemTmp
					WHERE	comp_id = @comp_id	AND
							guid    = @guid
  				END
		END
	ELSE
	  BEGIN
			IF NOT EXISTS (SELECT
								1
								FROM tbItemTmp						tit
								WHERE	tit.comp_id		= @comp_id	AND
										tit.item_id		= @item_id	AND
										tit.guid	    = @guid)
			BEGIN
						INSERT INTO tbItemTmp
						(
							comp_id,
							item_id,
							guid
						)
						VALUES
						(
							@comp_id,
							@item_id,
 							@guid
						)

			END
			ELSE

					BEGIN
					   DELETE FROM tbItemTmp
					   WHERE	comp_id = @comp_id	AND
								item_id = @item_id	AND
								guid	= @guid
					END
	  END

	SELECT
		tmp.comp_id,
		tmp.item_id,
		tmp.guid
	FROM tbItemTmp	tmp

END
GO





-- =============================================
-- MOS: 07-2008
-- =============================================
-- Graba los Movimientos de Despachos +
-- los NUMEROS de SERIE correspondientes a esta
-- Operacion.!!!
-- =============================================

-- MOS: 10-2010, NO SE USA MAS!!!!
-- Se paso en las fiscales al cerrar el comprobante y tomarlos
-- de lo que graba la transaccion.!

-- MOS: 07-2013: Se vuelve a usar para sugerir en la descripcion de cada item que despacho tomará



CREATE PROCEDURE  [dbo].[spItemTransactionImportData_GetBeforeDataForFiscalPrinters]

(
		@comp_id				as int,
		@bra_id					as int,
		@ct_transaction			as int,
		@tis_guid			    as uniqueidentifier,
		@lang_id				as int,
		@return_value			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
)


As



BEGIN


		SET NOCOUNT ON;


	-- -----------------------------------------------
	-- Testing
	-- -----------------------------------------------
	/*
	DECLARE
	@comp_id				as int,
	@bra_id					as int,
	@ct_transaction			as int,
	@tis_guid			    as uniqueidentifier,
	@lang_id				as int,
	@return_value			as int			,
	@ret_ErrorCode			as int			,
	@ret_ErrorDescription	as varchar(200)

	SET @comp_id = 1
	SET @bra_id = 1
	SET @ct_transaction = 0
	SET @tis_guid = 'd1c6462f-8cf2-4fb4-a269-f863d8c60fe7'
	SET @lang_id = 2
	Set @return_value = 0
	Set @ret_ErrorCode = 0
	Set @ret_ErrorDescription = ''
	*/
	-- -----------------------------------------------




	-- Initial Settings
--	Set @ret_Identity = 0
--	Set @ret_ErrorCode = 0
--	Set @ret_ErrorDescription = ''


	-- Variables Auxiliares
	Declare @item_expser as bit
	Declare @SerialsAvailable as int

	-- Tabla Temporal para saber que numeros de serie y de que despacho se actualizo
	CREATE TABLE #tmpUpdatedSerials (
		impData_id	[int] NOT NULL,
		import_id   [int] NULL,				-- MOS: 08-2011, con datos migrados pone null y no procesaba.-
		is_id		[int] NOT NULL,
		item_id		[int] NOT NULL)



	CREATE TABLE #tmpCustomsUsed (
		impData_id	[int] NOT NULL,
		item_id		[int] NOT NULL,
		impData_Custom_local	NVARCHAR(200) NULL,
		impData_Number_local	NVARCHAR(200) NULL
									)




	-- Cursor
	  Declare cursor_ITID_GBDFFP CURSOR LOCAL FAST_FORWARD FOR
		Select	tis_id,
				tis_priority,
				item_id,
				tis_itemDesc,
				tis_detail,
				curr_id,
				tis_initQty,
				tis_qty,
				prli_id,
				tis_price,
				stor_id,
				doc_id,
				tis_CD,
				bra_id,
				soh_id,
				tis_insertDate,
				aure_id,
				tax_id,
				aure_itemComposed,
				tis_itemDiscount,
				tis_CreditInt,
				tis_CreditIntPlus,
				tis_itemDiscountTotal,
				tis_isQuotation,
				tis_isCredit,
				tis_production,
				so_id,
				it_transaction
		From	dbo.tbTempItemStock			WITH (NOLOCK)
		Where	comp_id  = @comp_id
			and tis_guid = @tis_guid
			AND item_id IS NOT NULL

	Open cursor_ITID_GBDFFP

	Declare @tis_id					as int
	Declare @tis_priority			as decimal(14,4)
	Declare @item_id				as int
	Declare @tis_itemDesc			as varchar(100)
	Declare @tis_detail				as varchar(100)
	Declare @tis_curr_id			as int
	Declare @tis_initQty			as decimal(19,5)
	Declare @tis_qty				as decimal(19,5)
	Declare @prli_id                as int
	Declare @tis_price				as decimal(19,6)
	Declare @stor_id				as int
	Declare @doc_id					as int
	Declare @tis_CD					as datetime
	Declare @soh_id					as int
	Declare @tis_insertDate			as datetime
	Declare @aure_id				as int
	Declare @tax_id					as int
	Declare @aure_itemComposed		as bit
	Declare @tis_itemDiscount		as decimal(10,6)
	Declare @tis_CreditInt			as decimal(19,6)
	Declare @tis_CreditIntPlus		as decimal(19,6)
	Declare @tis_itemDiscountTotal  as decimal(19,4)
	Declare @tis_isQuotation		as bit
	Declare @tis_isCredit			as bit
	Declare @tis_production			as bit
	Declare @so_id      			as int
	Declare @it_transaction			as INT
	DECLARE @soh_BraId				AS INT
	DECLARE @bitSaleOrderEmittion_AllImportDataByItem	AS BIT
	SET		@bitSaleOrderEmittion_AllImportDataByItem = 'False'
	DECLARE @df_id					AS INT

	Fetch Next From cursor_ITID_GBDFFP
		Into
			@tis_id,
			@tis_priority,
			@item_id,
			@tis_itemDesc,
			@tis_detail,
			@tis_curr_id,
			@tis_initQty,
			@tis_qty,
			@prli_id,
			@tis_price,
			@stor_id,
			@doc_id,
			@tis_CD,
			@soh_BraId,
			@soh_id,
			@tis_insertDate,
			@aure_id,
			@tax_id,
			@aure_itemComposed,
			@tis_itemDiscount,
			@tis_CreditInt,
			@tis_CreditIntPlus,
			@tis_itemDiscountTotal,
			@tis_isQuotation,
			@tis_isCredit,
			@tis_production,
			@so_id,
			@it_transaction

	-- Fin Cursor

	While @@Fetch_Status = 0
		Begin


			-- ------------------------------------
			-- Verrificaciones Previas
			-- ------------------------------------
			SELECT @df_id = ttis.df_id
				FROM tbTempItemStock ttis	 WITH (NOLOCK)
			WHERE	ttis.comp_id	= @comp_id AND
					ttis.tis_guid	= @tis_guid
--			SELECT	@df_id = tsoh.df_id
--				FROM tbSaleOrderHeader	tsoh			WITH (NOLOCK)
--			WHERE	tsoh.comp_id	= @comp_id
--				AND tsoh.bra_id		= @soh_BraId
--				AND tsoh.soh_id		= @soh_id

			SELECT	@bitSaleOrderEmittion_AllImportDataByItem	= ISNULL(tdf.df_SaleOrderEmittion_AllImportDataByItem,'False')
				FROM tbDocumentsFile	tdf				WITH (NOLOCK)
				WHERE	tdf.comp_id = @comp_id
					AND tdf.df_id	= @df_id
			-- ------------------------------------


			-- Obtiene la forma de procesar, si es x numero de serie o x despacho.-
			Select @item_expser = A.item_expser
				From dbo.tbItem A			WITH (NOLOCK)
				Where	comp_id = @comp_id
					and item_id = @item_id
			-- ------------------

									   -- Si esto esta en TRUE hace de cuenta que no usa Numeros de Serie
			If @item_expser='True' AND @bitSaleOrderEmittion_AllImportDataByItem = 'False'
			-- /////////////////////////////////////////////////////////////////////////////////////////////////
			-- Procesamiento si Posee Numero de Serie
			-- /////////////////////////////////////////////////////////////////////////////////////////////////
				Begin


					-- Verifica 1ro que tenga tomados suficientes numeros de serie para el renglon.-
					-- Sea un Debito o un Credito.!!!

					Select
									A.is_id,
									B.item_id,
									ISID.impData_id,
									ISID.import_id,
									@tis_id [ItemCounter],
									ISID.impData_Custom_local,
									ISID.impData_Number_local
								Into #tmpAvailableItemSerials
								From  dbo.tbSaleOrderSerials	A					WITH (NOLOCK)
								Inner Join tbItemSerials		B					WITH (NOLOCK)
									ON      A.comp_id =			B.Comp_id
										and A.is_id   =			B.is_id
								Inner Join dbo.vwItemSerialsImportData_SO	ISID	WITH (NOLOCK)	-- x Performance se puso el where en esta vista
									On		ISID.comp_id		= B.comp_id
										and ISID.ct_transaction = B.ct_transaction
										and ISID.it_transaction = B.it_transaction
										AND ISID.is_id			= B.is_id
										AND ISID.ITEM_ID		= b.item_id		-- mos 07-2013 X ERROR DE MIGRACION DE GRUPO NUCLEO
																				-- nO DEBERIA MOLESTAR YA QUE LOS ITEM_ID DEBEN SER IGUALES
																				-- TANTO EN LA tbImportData como en tbItemSerial e tbItemTransaction
								Where  ( A.comp_id = @comp_id
									and	(A.sose_guid = @tis_guid or ( A.bra_id = @soh_BraId AND A.soh_id = @soh_id))
									and B.item_id = @item_id
										)


					INSERT into #tmpAvailableItemSerials
								(is_id,
								 item_id,
								 impdata_id,
								 import_Id,
								 ItemCounter,
 								 impData_Custom_local,
								 impData_Number_local
								)
								(Select ttis.is_id,
										ttis.item_id,
										ISID.impData_id,
										ISID.import_id,
										@tis_id,
										ISID.impData_Custom_local,
										ISID.impData_Number_local
									FROM  tbTempItemStock ttis						WITH (NOLOCK)
									Inner Join tbItemSerials ItS					WITH (NOLOCK)
										ON      ItS.comp_id = ttis.Comp_id
											and ItS.is_id   = ttis.is_id
									Inner Join dbo.vwItemSerialsImportData	ISID	WITH (NOLOCK)
										On		ISID.comp_id		= ItS.comp_id
											and ISID.ct_transaction = ItS.ct_transaction
											and ISID.it_transaction = ItS.it_transaction
											AND ISID.item_id		= ITS.item_id			-- MOS: 7-2013  ERROR MIGRACION GRUPO NUCLEO
									WHERE	ttis.comp_id	= @comp_id
										AND ttis.tis_guid	= @tis_guid
										AND ttis.item_id	= @item_id
										AND not ttis.is_id  IS NULL
										AND ttis.tis_id		= @tis_id
										AND NOT EXISTS(
														SELECT 1
															FROM #tmpAvailableItemSerials tmp
															WHERE tmp.is_id = ttis.is_id
													  )
								)

						-- Cuenta cuantos son los disponibles
						Select @SerialsAvailable = Count(*)
							From #tmpAvailableItemSerials
							Where item_id = @item_id

						-- Si no alcanzan los numeros de serie, cancela

							Begin

								---
								--- 3ro!!!
								Insert #tmpUpdatedSerials
									( impData_id,
									  import_id,
									  is_id,
									  item_id
									 )
								Select TOP (Convert(int,@tis_qty)) B.impData_id,B.import_id,B.is_id,B.item_id
											From #tmpAvailableItemSerials B
											Where B.item_id = @item_id

							End
					Drop Table #tmpAvailableItemSerials
				End



			ELSE


				-- /////////////////////////////////////////////////////////////////////////////////////////////////
				-- Procesamiento si NO POSEE Numero de Serie
				-- /////////////////////////////////////////////////////////////////////////////////////////////////

				DECLARE @ID			   AS INT
				Declare @crImport_id   as int
				Declare @crImpData_Id  as int
				Declare @crQty		   as decimal(19,6)
				Declare @crtis_Qty     as decimal(19,6)

				Begin


					-- Pone en una Temporal los Despachos Disponibles ordenados de la misma manera que en InsertData
					Select	CONVERT(INT, ROW_NUMBER() OVER (Order By A.impdata_Priority,B.import_cd))		[ID] ,
							A.impData_ActualQty,
							A.impdata_InitialQty,
							A.item_id,
							VII.import_id,
							A.impData_Id,
							B.import_cd,
							dbo.fnStrAllTrim(
							CASE
							    WHEN ISNULL(b.impData_number,'') = '' THEN dbo.fnStrAllTrim(ISNULL(A.impData_Number_local,'')) + ' ' + dbo.fnStrAllTrim(ISNULL(A.impData_Origin,''))
							    ELSE									   dbo.fnStrAllTrim(ISNULL(b.impData_number,''))       + ' ' + dbo.fnStrAllTrim(ISNULL(b.impData_origin,''))
							END				)						[impData_number],
							CASE
							    WHEN ISNULL(b.impData_Custom,'') = '' THEN A.impData_Custom_local
							    ELSE b.impData_Custom
							END										[impData_Custom],
							@tis_id									[tis_id],
							0										[Qty]
						Into #tmpAvailableImportdataForDebit
						From dbo.tbImportData						A				WITH (NOLOCK)
							LEFT JOIN tbCommercialTransactions tct					WITH (NOLOCK)
								ON	tct.comp_id				= A.comp_id AND
									tct.ct_transaction		= A.ct_transaction
							Left Join vwImportdata_ImportId			VII				WITH (NOLOCK)
								On		VII.comp_id			= A.comp_id
									and VII.ct_transaction	= A.ct_transaction
							Left Join dbo.tbImport					B				WITH (NOLOCK)
							On      B.comp_id   = A.comp_id
								and B.import_id = VII.import_id
							INNER JOIN tbTempItemStock				ttis			WITH (NOLOCK)
								ON	ttis.comp_id	= @comp_id	AND
									ttis.tis_guid	= @tis_guid AND
									ttis.item_id	= A.item_id AND
									ttis.tis_id		= @tis_id
							INNER JOIN tbItem						ti				WITH (NOLOCK)
								ON	ti.comp_id = ttis.comp_id AND
									ti.item_id = ttis.item_id
						Where   A.comp_id = @comp_id
							and A.item_id = @item_id
							-- AND ti.item_expser = 0  NO por lo Nuevo de Nucleo
							and A.impData_ActualQty > 0
							AND (	ISNULL(b.impData_number,'') <> ''
								  OR
									A.impData_Number_local <> ''
								)
						Order By	A.impdata_Priority,
									CASE
									    WHEN [impData_number] <> '' THEN 1
									    ELSE							 2
									END,
									tct.ct_date,
									B.import_cd

					-- Setea la Cantidad Inicial como la Inicial de tbTempItemStock
					-- La idea es ver que esta variable llegue a 0 y asi asignar los despachos correspondientes
					Set @crTis_Qty = IsNull(@tis_qty,0)

					Declare crAvailableImportdataForDebit
					CURSOR LOCAL FAST_FORWARD FOR
						Select		ID,
									import_id,
									impData_Id,
									impData_ActualQty
							From #tmpAvailableImportdataForDebit
						ORDER BY [ID]

					Open crAvailableImportdataForDebit

					Fetch Next From crAvailableImportdataForDebit
						Into	@ID,
								@crImport_id,
								@crImpData_Id,
								@crQty


					DECLARE @impData_Custom_local AS NVARCHAR(200)
					DECLARE @impData_Number_local AS NVARCHAR(200)

					-- Actualiza la temporal con las cantidades de cada despacho hasta cumplir
					-- con el total del pedido, asi, mas abajo toma los nros de despacho
					-- que tienen asignada alguna cantidad
					While @@Fetch_Status = 0 and @crTis_Qty > 0
					Begin


						If @crTis_Qty <= @crQty
							BEGIN

								UPDATE #tmpAvailableImportdataForDebit
									SET Qty = Qty + @tis_qty
									WHERE ID=@ID

									Set @crTis_Qty = 0
							End
						Else
							Begin

								UPDATE #tmpAvailableImportdataForDebit
									SET Qty = Qty + @crQty
									WHERE ID=@ID

									Set @crTis_Qty = @crTis_Qty - @crQty
							End

						Fetch Next From crAvailableImportdataForDebit
							Into	@ID,
									@crImport_id,
									@crImpData_Id,
									@crQty
					End


					Close      crAvailableImportdataForDebit
					Deallocate crAvailableImportdataForDebit



					-- ---------------------------------------
					-- Actualiza la Temporal del pedido para
					-- que luego se ponga este despacho
					-- preasignado en la tbItemTransactionImportData
					-- en el campo adicional.-
					-- Depende de como sean las transacciones
					-- van a quedar iguales o diferentes
					-- Esto es por la asincronia de las impresoras fiscales
					-- ---------------------------------------



					SET @impData_Custom_local = ''
					SET @impData_Number_local = ''
					SELECT
						@impData_Custom_local = @impData_Custom_local + IsNull(tmp.impData_Custom,'') + ' ',
						@impData_Number_local = @impData_Number_local + IsNull(tmp.impData_number,'') + ' '
						FROM tbTempItemStock						ttis		WITH (NOLOCK)
						inner join 	#tmpAvailableImportdataForDebit tmp
							ON	tmp.tis_id		= ttis.tis_id	AND
								tmp.Qty			> 0
						WHERE	ttis.comp_id	= @comp_id	AND
								ttis.tis_id		= @tis_id





					UPDATE tbTempItemStock			WITH (ROWLOCK)
					SET
						impData_Number_localPreAssignedByFiscal = @impData_Number_local,
						impData_Custom_localPreAssignedByFiscal = @impData_Custom_local
						FROM tbTempItemStock						ttis		--WITH (NOLOCK)
						WHERE	ttis.comp_id	= @comp_id	AND
								ttis.tis_id		= @tis_id
					-- ---------------------------------------

					INSERT INTO  #tmpCustomsUsed
						SELECT	tmp.impdata_id,
								tmp.item_id,
								@impData_Custom_local,
								@impData_Number_local
							FROM #tmpAvailableImportdataForDebit tmp
							WHERE tmp.Qty > 0

					DROP TABLE #tmpAvailableImportdataForDebit


					-- Grabar los Movimientos Correspondientes de los despachos

				End

			-- /////////////////////////////////////////////////////////////////////////////////////////////////


			Fetch Next From cursor_ITID_GBDFFP
				Into
					@tis_id,
					@tis_priority,
					@item_id,
					@tis_itemDesc,
					@tis_detail,
					@tis_curr_id,
					@tis_initQty,
					@tis_qty,
					@prli_id,
					@tis_price,
					@stor_id,
					@doc_id,
					@tis_CD,
					@soh_BraId,
					@soh_id,
					@tis_insertDate,
					@aure_id,
					@tax_id,
					@aure_itemComposed,
					@tis_itemDiscount,
					@tis_CreditInt,
					@tis_CreditIntPlus,
					@tis_itemDiscountTotal,
					@tis_isQuotation,
					@tis_isCredit,
					@tis_production,
					@so_id,
					@it_transaction

		End --While

	Close      cursor_ITID_GBDFFP
    DEALLOCATE cursor_ITID_GBDFFP


	Select	A.item_id,
			A.impData_id,
			IsNull(D.impData_number,c.impData_Number_local)   [impData_number] -- Por si es un Despacho proveniente de compra Local
		From #tmpUpdatedSerials		A
			Inner Join dbo.tbImportData							C		WITH (NOLOCK)
				On		C.comp_id		= @comp_id
					and C.impData_id	= A.impData_id

			Left Join dbo.tbImport								D		WITH (NOLOCK)
				On		D.comp_id	= @comp_id
					and	D.import_id = A.import_id

	UNION

		Select	B.item_id,
				B.impData_id,
				IsNull(B.impData_Number_local,'') collate database_default   [impData_number] -- Por si es un Despacho proveniente de compra Local
			From #tmpCustomsUsed								B
			Inner Join dbo.tbImportData							C			WITH (NOLOCK)
				On		C.comp_id			= @comp_id
					and C.impData_id		= B.impData_id
			Left Join dbo.vwImportdata_ImportId				VII				WITH (NOLOCK)
				On		VII.comp_id			= C.comp_id
					and	VII.ct_transaction	= C.ct_transaction
			Left Join dbo.tbImport								D			WITH (NOLOCK)
				On		D.comp_id			= @comp_id
					and	D.import_id			= VII.import_id


	UNION 	-- x si es el Remito de una Fc para q traiga los nros de la factura original.!

		SELECT	tit.item_id,
				tid.impData_id,
				IsNull(tid.impData_Number_local,'')   collate database_default   [impData_number]
			FROM tbItemTransactionImportData tid							WITH (NOLOCK)
			INNER JOIN tbItemTransactions tit								WITH (NOLOCK)
				ON	tit.comp_id			= tid.comp_id AND
					tit.it_transaction	= tid.it_transaction
			WHERE	tid.comp_id			= @comp_id AND
					tid.ct_transaction	= @ct_transaction



--	UNION
--
--		SELECT	B.item_id,
--				B.impData_id,
--				IsNull(D.impData_number,c.impData_Number_local)   [impData_number]
--		FROM #tmpAvailableImportdataForDebit B
--		Inner Join dbo.tbImportData							C
--			On		C.comp_id			= @comp_id
--				and C.impData_id		= B.impData_id
--		Left Join dbo.vwImportdata_ImportId				VII
--			On		VII.comp_id			= C.comp_id
--				and	VII.ct_transaction	= C.ct_transaction
--		Left Join dbo.tbImport								D
--			On		D.comp_id			= @comp_id
--				and	D.import_id			= VII.import_id

	--- -----------------------------------------------------------------------------------------------
	Drop Table #tmpUpdatedSerials
	Drop Table #tmpCustomsUsed
	--DROP TABLE #tmpAvailableImportdataForDebit


END




GO





-- =============================================
-- MOS: 07-2008
-- =============================================
-- Graba los Movimientos de Despachos +
-- los NUMEROS de SERIE correspondientes a esta
-- Operacion.!!!
-- =============================================

-- MOS: 10-2010, NO SE USA MAS!!!!
-- Se paso en las fiscales al cerrar el comprobante y tomarlos
-- de lo que graba la transaccion.!

-- MOS: 07-2013: Se vuelve a usar para sugerir en la descripcion de cada item que despacho tomará



Create Procedure  [dbo].[spItemTransactionImportData_GetBeforeDataForFiscalPrinters_Old]

(
		@comp_id				as int,
		@bra_id					as int,
		@ct_transaction			as int,
		@tis_guid			    as uniqueidentifier,
		@lang_id				as int,
		@return_value			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
)


As



BEGIN


		SET NOCOUNT ON;


	-- -----------------------------------------------
	-- Testing
	-- -----------------------------------------------
	/*
	DECLARE
	@comp_id				as int,
	@bra_id					as int,
	@ct_transaction			as int,
	@tis_guid			    as uniqueidentifier,
	@lang_id				as int,
	@return_value			as int			,
	@ret_ErrorCode			as int			,
	@ret_ErrorDescription	as varchar(200)

	SET @comp_id = 1
	SET @bra_id = 1
	SET @ct_transaction = 0
	SET @tis_guid = 'd1c6462f-8cf2-4fb4-a269-f863d8c60fe7'
	SET @lang_id = 2
	Set @return_value = 0
	Set @ret_ErrorCode = 0
	Set @ret_ErrorDescription = ''
	*/
	-- -----------------------------------------------




	-- Initial Settings
--	Set @ret_Identity = 0
--	Set @ret_ErrorCode = 0
--	Set @ret_ErrorDescription = ''


	-- Variables Auxiliares
	Declare @item_expser as bit
	Declare @SerialsAvailable as int

	-- Tabla Temporal para saber que numeros de serie y de que despacho se actualizo
	CREATE TABLE #tmpUpdatedSerials (
		impData_id	[int] NOT NULL,
		import_id   [int] NULL,				-- MOS: 08-2011, con datos migrados pone null y no procesaba.-
		is_id		[int] NOT NULL,
		item_id		[int] NOT NULL)



	CREATE TABLE #tmpCustomsUsed (
		impData_id	[int] NOT NULL,
		item_id		[int] NOT NULL
									)




	-- Cursor
	  Declare cursor_ITID_GBDFFP Cursor For
		Select	tis_id,
				tis_priority,
				item_id,
				tis_itemDesc,
				tis_detail,
				curr_id,
				tis_initQty,
				tis_qty,
				prli_id,
				tis_price,
				stor_id,
				doc_id,
				tis_CD,
				bra_id,
				soh_id,
				tis_insertDate,
				aure_id,
				tax_id,
				aure_itemComposed,
				tis_itemDiscount,
				tis_CreditInt,
				tis_CreditIntPlus,
				tis_itemDiscountTotal,
				tis_isQuotation,
				tis_isCredit,
				tis_production,
				so_id,
				it_transaction
		From	dbo.tbTempItemStock
		Where	comp_id  = @comp_id
			and tis_guid = @tis_guid
			AND item_id IS NOT NULL

	Open cursor_ITID_GBDFFP

	Declare @tis_id					as int
	Declare @tis_priority			as decimal(14,4)
	Declare @item_id				as int
	Declare @tis_itemDesc			as varchar(100)
	Declare @tis_detail				as varchar(100)
	Declare @tis_curr_id			as int
	Declare @tis_initQty			as decimal(19,5)
	Declare @tis_qty				as decimal(19,5)
	Declare @prli_id                as int
	Declare @tis_price				as decimal(19,6)
	Declare @stor_id				as int
	Declare @doc_id					as int
	Declare @tis_CD					as datetime
	Declare @soh_id					as int
	Declare @tis_insertDate			as datetime
	Declare @aure_id				as int
	Declare @tax_id					as int
	Declare @aure_itemComposed		as bit
	Declare @tis_itemDiscount		as decimal(10,6)
	Declare @tis_CreditInt			as decimal(19,6)
	Declare @tis_CreditIntPlus		as decimal(19,6)
	Declare @tis_itemDiscountTotal  as decimal(19,4)
	Declare @tis_isQuotation		as bit
	Declare @tis_isCredit			as bit
	Declare @tis_production			as bit
	Declare @so_id      			as int
	Declare @it_transaction			as INT
	DECLARE @soh_BraId				AS INT



	Fetch Next From cursor_ITID_GBDFFP
		Into
			@tis_id,
			@tis_priority,
			@item_id,
			@tis_itemDesc,
			@tis_detail,
			@tis_curr_id,
			@tis_initQty,
			@tis_qty,
			@prli_id,
			@tis_price,
			@stor_id,
			@doc_id,
			@tis_CD,
			@soh_BraId,
			@soh_id,
			@tis_insertDate,
			@aure_id,
			@tax_id,
			@aure_itemComposed,
			@tis_itemDiscount,
			@tis_CreditInt,
			@tis_CreditIntPlus,
			@tis_itemDiscountTotal,
			@tis_isQuotation,
			@tis_isCredit,
			@tis_production,
			@so_id,
			@it_transaction

	-- Fin Cursor

	While @@Fetch_Status = 0
		Begin




			-- Obtiene la forma de procesar, si es x numero de serie o x despacho.-
			Select @item_expser = A.item_expser
				From dbo.tbItem A
				Where	comp_id = @comp_id
					and item_id = @item_id
			-- ------------------


			If @item_expser='True'
			-- /////////////////////////////////////////////////////////////////////////////////////////////////
			-- Procesamiento si Posee Numero de Serie
			-- /////////////////////////////////////////////////////////////////////////////////////////////////
				Begin


					-- Verifica 1ro que tenga tomados suficientes numeros de serie para el renglon.-
					-- Sea un Debito o un Credito.!!!

					Select
									A.is_id,
									B.item_id,
									ISID.impData_id,
									ISID.import_id,
									@tis_id [ItemCounter],
									ISID.impData_Custom_local,
									ISID.impData_Number_local
								Into #tmpAvailableItemSerials
								From  dbo.tbSaleOrderSerials	A					WITH (NOLOCK)
								Inner Join tbItemSerials		B					WITH (NOLOCK)
									ON      A.comp_id =			B.Comp_id
										and A.is_id   =			B.is_id
								Inner Join dbo.vwItemSerialsImportData_SO	ISID	WITH (NOLOCK)	-- x Performance se puso el where en esta vista
									On		ISID.comp_id		= B.comp_id
										and ISID.ct_transaction = B.ct_transaction
										and ISID.it_transaction = B.it_transaction
										AND ISID.is_id			= A.is_id
										AND ISID.ITEM_ID		= b.item_id		-- mos 07-2013 X ERROR DE MIGRACION DE GRUPO NUCLEO
																				-- nO DEBERIA MOLESTAR YA QUE LOS ITEM_ID DEBEN SER IGUALES
																				-- TANTO EN LA tbImportData como en tbItemSerial e tbItemTransaction
								Where  ( A.comp_id = @comp_id
									and	(A.sose_guid = @tis_guid or ( A.bra_id = @soh_BraId AND A.soh_id = @soh_id))
									and B.item_id = @item_id
										)


					INSERT into #tmpAvailableItemSerials
								(is_id,
								 item_id,
								 impdata_id,
								 import_Id,
								 ItemCounter,
 								 impData_Custom_local,
								 impData_Number_local
								)
								(Select ttis.is_id,
										ttis.item_id,
										ISID.impData_id,
										ISID.import_id,
										@tis_id,
										ISID.impData_Custom_local,
										ISID.impData_Number_local
									FROM  tbTempItemStock ttis
									Inner Join tbItemSerials ItS					WITH (NOLOCK)
										ON      ItS.comp_id = ttis.Comp_id
											and ItS.is_id   = ttis.is_id
									Inner Join dbo.vwItemSerialsImportData	ISID	WITH (NOLOCK)
										On		ISID.comp_id		= ttis.comp_id
											and ISID.ct_transaction = ItS.ct_transaction
											and ISID.it_transaction = ItS.it_transaction
											AND ISID.item_id		= ITS.item_id			-- MOS: 7-2013  ERROR MIGRACION GRUPO NUCLEO
									WHERE	ttis.comp_id	= @comp_id
										AND ttis.tis_guid	= @tis_guid
										AND ttis.item_id	= @item_id
										AND not ttis.is_id  IS NULL
										AND ttis.tis_id		= @tis_id
										AND NOT EXISTS(
														SELECT 1
															FROM #tmpAvailableItemSerials tmp
															WHERE tmp.is_id = ttis.is_id
													  )
								)

						-- Cuenta cuantos son los disponibles
						Select @SerialsAvailable = Count(*)
							From #tmpAvailableItemSerials
							Where item_id = @item_id

						-- Si no alcanzan los numeros de serie, cancela

							Begin

								---
								--- 3ro!!!
								Insert #tmpUpdatedSerials
									( impData_id,
									  import_id,
									  is_id,
									  item_id
									 )
								Select TOP (Convert(int,@tis_qty)) B.impData_id,B.import_id,B.is_id,B.item_id
											From #tmpAvailableItemSerials B
											Where B.item_id = @item_id

							End
					Drop Table #tmpAvailableItemSerials
				End



			ELSE


				-- /////////////////////////////////////////////////////////////////////////////////////////////////
				-- Procesamiento si NO POSEE Numero de Serie
				-- /////////////////////////////////////////////////////////////////////////////////////////////////

				Declare @crImport_id   as int
				Declare @crImpData_Id  as int
				Declare @crQty		   as decimal(19,6)
				Declare @crtis_Qty     as decimal(19,6)

				Begin


							-- ////////////////////////////////////////////////////
							-- Buscar los Despachos Correspondientes segun DEBITO
							-- ////////////////////////////////////////////////////
							BEGIN

								-- Busca un despacho con cantidad total mayor o igual a la del pedido
								Select TOP 1
										A.impData_ActualQty,
										A.impdata_InitialQty,
										A.item_id,
										VII.import_id,
										A.impData_Id,
										B.import_cd,
										CASE
										    WHEN ISNULL(b.impData_number,'') = '' THEN A.impData_Number_local
										    ELSE b.impData_number
										END										[impData_number],
										CASE
										    WHEN ISNULL(b.impData_Custom,'') = '' THEN A.impData_Custom_local
										    ELSE b.impData_Custom
										END										[impData_Custom],
										@tis_id									[tis_id]
									Into #tmpAvailableImportdataForDebit
									From dbo.tbImportData						A				WITH (NOLOCK)
										Left Join vwImportdata_ImportId			VII				WITH (NOLOCK)
											On		VII.comp_id			= A.comp_id
												and VII.ct_transaction	= A.ct_transaction
										Left Join dbo.tbImport					B				WITH (NOLOCK)
										On      B.comp_id   = A.comp_id
											and B.import_id = VII.import_id
										INNER JOIN tbTempItemStock				ttis			WITH (NOLOCK)
											ON	ttis.comp_id	= @comp_id	AND
												ttis.tis_guid	= @tis_guid AND
												ttis.item_id	= A.item_id AND
												ttis.tis_id		= @tis_id
										INNER JOIN tbItem						ti				WITH (NOLOCK)
											ON	ti.comp_id = ttis.comp_id AND
												ti.item_id = ttis.item_id
									Where   A.comp_id = @comp_id
										and A.item_id = @item_id
										AND ti.item_expser = 0
										and A.impData_ActualQty > = ttis.tis_qty

									Order By A.impdata_Priority,B.import_cd

									IF @@ROWCOUNT = 0		-- Si no encuentra busca un despacho con la cantidad total disponible . . .
										BEGIN


											INSERT INTO  #tmpAvailableImportdataForDebit
													 (	impData_ActualQty,
														impdata_InitialQty,
														item_id,
														import_id,
														impData_Id,
														import_cd,
														impData_number,
														impData_Custom,
														tis_id
													)
											Select TOP 1
													A.impData_ActualQty,
													A.impdata_InitialQty,
													A.item_id,
													VII.import_id,
													A.impData_Id,
													B.import_cd,
													CASE
														WHEN ISNULL(b.impData_number,'') = '' THEN A.impData_Number_local
														ELSE b.impData_number
													END										[impData_number],
													CASE
														WHEN ISNULL(b.impData_Custom,'') = '' THEN A.impData_Custom_local
														ELSE b.impData_Custom
													END										[impData_Custom],
													@tis_id									[tis_id]

												From dbo.tbImportData						A				WITH (NOLOCK)
													Left Join vwImportdata_ImportId			VII				WITH (NOLOCK)
														On		VII.comp_id			= A.comp_id
															and VII.ct_transaction	= A.ct_transaction
													Left Join dbo.tbImport					B				WITH (NOLOCK)
													On      B.comp_id  = A.comp_id
														and B.import_id = VII.import_id
													INNER JOIN tbTempItemStock				ttis			WITH (NOLOCK)
														ON	ttis.comp_id	= @comp_id	AND
															ttis.tis_guid	= @tis_guid AND
															ttis.item_id	= A.item_id AND
															ttis.tis_id		= @tis_id
													INNER JOIN tbItem						ti				WITH (NOLOCK)
														ON	ti.comp_id = ttis.comp_id AND
															ti.item_id = ttis.item_id
												Where   A.comp_id = @comp_id
													and A.item_id = @item_id
													AND ti.item_expser = 0
													and A.impData_ActualQty > 0

												Order By A.impdata_Priority,B.import_cd

										END

--==
--SELECT * FROM #tmpAvailableImportdataForDebit
--==
									INSERT INTO  #tmpCustomsUsed
										SELECT	tmp.impdata_id,
												tmp.item_id
											FROM #tmpAvailableImportdataForDebit tmp

									-- ---------------------------------------
									-- Actualiza la Temporal del pedido para
									-- que luego se ponga este despacho
									-- preasignado en la tbItemTransactionImportData
									-- en el campo adicional.-
									-- Depende de como sean las transacciones
									-- van a quedar iguales o diferentes
									-- Esto es por la asincronia de las impresoras fiscales
									-- ---------------------------------------
									UPDATE tbTempItemStock
									SET
										impData_Number_localPreAssignedByFiscal = tmp.impData_number,
										impData_Custom_localPreAssignedByFiscal = tmp.impData_Custom
										FROM tbTempItemStock						ttis
										inner join 	#tmpAvailableImportdataForDebit tmp
											ON	tmp.tis_id		= ttis.tis_id
										WHERE	ttis.comp_id	= @comp_id AND
												ttis.tis_id		= @tis_id
									-- ---------------------------------------

									DROP TABLE #tmpAvailableImportdataForDebit

							End

					-- Grabar los Movimientos Correspondientes de los despachos

				End

			-- /////////////////////////////////////////////////////////////////////////////////////////////////


			Fetch Next From cursor_ITID_GBDFFP
				Into
					@tis_id,
					@tis_priority,
					@item_id,
					@tis_itemDesc,
					@tis_detail,
					@tis_curr_id,
					@tis_initQty,
					@tis_qty,
					@prli_id,
					@tis_price,
					@stor_id,
					@doc_id,
					@tis_CD,
					@soh_BraId,
					@soh_id,
					@tis_insertDate,
					@aure_id,
					@tax_id,
					@aure_itemComposed,
					@tis_itemDiscount,
					@tis_CreditInt,
					@tis_CreditIntPlus,
					@tis_itemDiscountTotal,
					@tis_isQuotation,
					@tis_isCredit,
					@tis_production,
					@so_id,
					@it_transaction

		End --While




		Select	A.item_id,
				A.impData_id,
				IsNull(D.impData_number,c.impData_Number_local)   [impData_number] -- Por si es un Despacho proveniente de compra Local
			From #tmpUpdatedSerials		A
				Inner Join dbo.tbImportData							C		WITH (NOLOCK)
					On		C.comp_id		= @comp_id
						and C.impData_id	= A.impData_id

				Left Join dbo.tbImport								D		WITH (NOLOCK)
					On		D.comp_id	= @comp_id
						and	D.import_id = A.import_id

	Union

		Select	B.item_id,
				B.impData_id,
				IsNull(D.impData_number,c.impData_Number_local)   [impData_number] -- Por si es un Despacho proveniente de compra Local
			From #tmpCustomsUsed								B
			Inner Join dbo.tbImportData							C			WITH (NOLOCK)
				On		C.comp_id			= @comp_id
					and C.impData_id		= B.impData_id
			Left Join dbo.vwImportdata_ImportId				VII				WITH (NOLOCK)
				On		VII.comp_id			= C.comp_id
					and	VII.ct_transaction	= C.ct_transaction
			Left Join dbo.tbImport								D			WITH (NOLOCK)
				On		D.comp_id			= @comp_id
					and	D.import_id			= VII.import_id


--	UNION
--
--		SELECT	B.item_id,
--				B.impData_id,
--				IsNull(D.impData_number,c.impData_Number_local)   [impData_number]
--		FROM #tmpAvailableImportdataForDebit B
--		Inner Join dbo.tbImportData							C
--			On		C.comp_id			= @comp_id
--				and C.impData_id		= B.impData_id
--		Left Join dbo.vwImportdata_ImportId				VII
--			On		VII.comp_id			= C.comp_id
--				and	VII.ct_transaction	= C.ct_transaction
--		Left Join dbo.tbImport								D
--			On		D.comp_id			= @comp_id
--				and	D.import_id			= VII.import_id

	--- -----------------------------------------------------------------------------------------------
	Drop Table #tmpUpdatedSerials
	Drop Table #tmpCustomsUsed
	--DROP TABLE #tmpAvailableImportdataForDebit
	Close      cursor_ITID_GBDFFP
    DEALLOCATE cursor_ITID_GBDFFP

END




GO





-- =============================================
-- Author:		MOS
-- Create date: 09-2010
-- Description:	Trae un String con los despachos y otro con las aduanas
-- Correspondientes a un ingreso
-- =============================================
CREATE PROCEDURE [dbo].[spItemTransactionImportData_GetData]
	@comp_id			AS INT,
	@bra_id				AS INT,
	@ct_transaction		AS INT
AS

BEGIN

	SET NOCOUNT ON;

	SELECT	titid.comp_id,
			ti.item_id,
			ti.item_code,
			ti.item_desc,
			tit.it_order,
			isnull(titid.impData_Custom_local,'')		[CustomLoc],
			isnull(titid.impData_Number_local,'')		[CustomLocNumber],
			isnull(tid.impData_Custom_local,'')			[Custom],
			isnull(tid.impData_Number_local,'')			[CustomNumber]
		FROM tbItemTransactionImportData titid								WITH (NOLOCK)
		left JOIN tbImportData tid											WITH (NOLOCK)
			ON		tid.comp_id		= titid.comp_id
				AND tid.impData_id	= titid.impData_id
		INNER JOIN tbItemTransactions tit									WITH (NOLOCK)
			ON		tit.comp_id			= titid.comp_id
				AND tit.it_transaction	= titid.it_transaction
		INNER JOIN tbItem ti												WITH (NOLOCK)
			ON		ti.comp_id = tit.comp_id
				AND ti.item_id = tit.item_id
		WHERE	titid.comp_id			= @comp_id
			AND titid.bra_id			= @bra_id
			AND titid.ct_transaction	= @ct_transaction

END

GO



-- Log
-- MOS 06-2024: puse que hay que hacer para que el sistema soporte la venta de medicamentos con preasignacion de lotes desde preparacion de pedidos.
-- MOS 07-2024: Si NO encuentra ningun lote debe cancelar y dar error.


-- =============================================
-- MOS: 07-2008
-- MOS: 07-2010 Se modifico para Despacho Local
-- =============================================
-- Graba los Movimientos de Despachos +
-- los NUMEROS de SERIE correspondientes a esta
-- Operacion.!!!
-- =============================================

CREATE PROCEDURE [dbo].[spItemTransactionImportData_InsertData]

(
		@comp_id				as int,
		@bra_id					as int,
		@ct_transaction			as int,
		@tis_guid			    as uniqueidentifier,
		@lang_id				as int,
		@ret_Identity			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	varchar(200)    output
)


AS
BEGIN
	SET NOCOUNT ON;


-- ------------------------------------------------------------------------------------
-- Testing
-- ------------------------------------------------------------------------------------
/*
DECLARE			@comp_id				as int,
		@bra_id					as int,
		@ct_transaction			as int,
		@tis_guid			    as uniqueidentifier,
		@lang_id				as int,
		@ret_Identity			as int			,
		@ret_ErrorCode			as int			,
		@ret_ErrorDescription	varchar(200)

select
		@comp_id				=1,
		@bra_id					=1,
		@ct_transaction			=1,
		@tis_guid			    ='4FAF6F2E-4B16-4336-890A-029EB60902F6',
		@lang_id				=1
*/
-- ------------------------------------------------------------------------------------


	-- MOS 07-2024
	DECLARE @brag_id4ImportData AS INT = NULL
	DECLARE @tmpBranchs4ImportData TABLE(bra_id INT PRIMARY KEY)

	SELECT	@brag_id4ImportData = tb.brag_id4ImportData
		FROM tbBranch AS tb WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id

	IF @brag_id4ImportData IS NULL
		BEGIN
			INSERT INTO @tmpBranchs4ImportData
			(
				bra_id
			)
			SELECT tb.bra_id
				FROM tbbranch tb WITH (NOLOCK)
				WHERE	tb.comp_id		= @comp_id	AND
						tb.bra_disabled = 'False'
		END
	ELSE
		BEGIN
			INSERT INTO @tmpBranchs4ImportData
			(
				bra_id
			)
			SELECT	tbgd.bra_id
				FROM	tbBranchGroupDetail AS tbgd WITH (NOLOCK)
				WHERE	tbgd.comp_id = @comp_id AND
						tbgd.brag_id = @brag_id4ImportData
		END
	-- MOS 07-2024


	-- Initial Settings
	Set @ret_Identity = 0
	Set @ret_ErrorCode = 0
	Set @ret_ErrorDescription = ''


	-- Variables Auxiliares
	Declare @item_expser		as BIT
	Declare @SerialsAvailable	as INT
	DECLARE @item_expLote		AS BIT

	-- Tabla Temporal para saber que numeros de serie y de que despacho se actualizo
	CREATE TABLE #tmpUpdatedSerials (
		impData_id	[int] NOT NULL,
		import_id   [int]     NULL,
		is_id		[int] NOT NULL,
		item_id		[int] NOT NULL)


	-- Cursor
	  Declare cursor_ITID_ID CURSOR LOCAL  FAST_FORWARD For
		Select	tis_id,
				tis_priority,
				item_id,
				tis_itemDesc,
				tis_detail,
				curr_id,
				tis_initQty,
				tis_qty,
				prli_id,
				tis_price,
				stor_id,
				doc_id,
				tis_CD,
				bra_id,
				soh_id,
				tis_insertDate,
				aure_id,
				tax_id,
				aure_itemComposed,
				tis_itemDiscount,
				tis_CreditInt,
				tis_CreditIntPlus,
				tis_itemDiscountTotal,
				tis_isQuotation,
				tis_isCredit,
				tis_production,
				so_id,
				it_transaction,
				it_transaction_original,
				ISNULL(it_transaction_NoStockDiscount,'False')			[it_transaction_NoStockDiscount],
				ISNULL(impData_Number_localPreAssignedByFiscal,'')		[impData_Number_localPreAssignedByFiscal],
				ISNULL(impData_Custom_localPreAssignedByFiscal,'')		[impData_Custom_localPreAssignedByFiscal],
				sod_id	-- MOS 07-2024
		From	dbo.tbTempItemStock					  WITH (NOLOCK)
		Where	comp_id  = @comp_id		AND
				tis_guid = @tis_guid	AND
				item_id  IS NOT NULL		-- MOS 02-2014

	Open cursor_ITID_ID

	Declare @tis_id					as int
	Declare @tis_priority			as decimal(14,4)
	Declare @item_id				as int
	Declare @tis_itemDesc			as varchar(100)
	Declare @tis_detail				as varchar(100)
	Declare @tis_curr_id			as int
	Declare @tis_initQty			as decimal(19,5)
	Declare @tis_qty				as decimal(19,5)
	Declare @prli_id                as int
	Declare @tis_price				as decimal(19,6)
	Declare @stor_id				as int
	Declare @doc_id					as int
	Declare @tis_CD					as DATETIME
	DECLARE @soh_BraId				AS INT
	Declare @soh_id					as INT
	DECLARE @sod_id					AS INT
	Declare @tis_insertDate			as datetime
	Declare @aure_id				as int
	Declare @tax_id					as int
	Declare @aure_itemComposed		as bit
	Declare @tis_itemDiscount		as decimal(10,6)
	Declare @tis_CreditInt			as decimal(19,6)
	Declare @tis_CreditIntPlus		as decimal(19,6)
	Declare @tis_itemDiscountTotal  as decimal(19,4)
	Declare @tis_isQuotation		as bit
	Declare @tis_isCredit			as bit
	Declare @tis_production			as bit
	Declare @so_id      			as int
	Declare @it_transaction			as INT
	DECLARE @it_transaction_Original AS INT
	DECLARE @it_transaction_NoStockDiscount AS BIT
	DECLARE @df_id							AS INT
	DECLARE @bitEmissionWithOutSerialization AS BIT
	DECLARE @intSerialNumberDifference		 AS INT
	DECLARE @intAuxCounter					 AS INT
	declare @impData_Number_localPreAssignedByFiscal	AS NVARCHAR(200)
	DECLARE @impData_Custom_localPreAssignedByFiscal	AS NVARCHAR(200)
	DECLARE @bitSaleOrderEmittion_AllImportDataByItem	AS BIT
	SET		@bitSaleOrderEmittion_AllImportDataByItem = 'False'

	-- MOS: 03-2011, antes estaba justo debajo del fetch
	Declare @intItemCounter AS INT
	SET		@intItemCounter = 1

	Fetch Next From cursor_ITID_ID
		Into
			@tis_id,
			@tis_priority,
			@item_id,
			@tis_itemDesc,
			@tis_detail,
			@tis_curr_id,
			@tis_initQty,
			@tis_qty,
			@prli_id,
			@tis_price,
			@stor_id,
			@doc_id,
			@tis_CD,
			@soh_BraId,
			@soh_id,
			@tis_insertDate,
			@aure_id,
			@tax_id,
			@aure_itemComposed,
			@tis_itemDiscount,
			@tis_CreditInt,
			@tis_CreditIntPlus,
			@tis_itemDiscountTotal,
			@tis_isQuotation,
			@tis_isCredit,
			@tis_production,
			@so_id,
			@it_transaction,
			@it_transaction_Original,
			@it_transaction_NoStockDiscount,
			@impData_Number_localPreAssignedByFiscal,
			@impData_Custom_localPreAssignedByFiscal,
			@sod_id


	-- Fin Cursor

	-- ------------------------------------
	-- Verrificaciones Previas
	-- ------------------------------------
	SELECT TOP 1 @df_id = ttis.df_id			-- MOS 01-2020 top 1
		FROM tbTempItemStock ttis	 WITH (NOLOCK)
		WHERE	--ttis.comp_id	= @comp_id AND  MOS 05-2020
				ttis.tis_guid	= @tis_guid
--	SELECT	@df_id = tsoh.df_id
--		FROM tbSaleOrderHeader	tsoh			WITH (NOLOCK)
--	WHERE	tsoh.comp_id	= @comp_id
--		AND tsoh.bra_id		= @soh_BraId
--		AND tsoh.soh_id		= @soh_id


	DECLARE @stor_id4SaleOrderpreInvoiceCreditNote AS INT = NULL

	SELECT	@bitEmissionWithOutSerialization			= isnull(tdf.df_SaleOrderEmissionWithOutSerialization,'False'),
			@bitSaleOrderEmittion_AllImportDataByItem	= ISNULL(tdf.df_SaleOrderEmittion_AllImportDataByItem,'False'),
			@stor_id4SaleOrderpreInvoiceCreditNote		= stor_id4SaleOrderpreInvoiceCreditNote
		FROM tbDocumentsFile	tdf				WITH (NOLOCK)
		WHERE	tdf.comp_id = @comp_id
			AND tdf.df_id	= @df_id
	-- ------------------------------------



	-- SE FIJA SI ALGUN DEPOSITO DE LOS ITEMS PERMITE HACER LO MISMO.-
		IF @bitEmissionWithOutSerialization = 'False'
			BEGIN
				SELECT @bitEmissionWithOutSerialization = IsNull(ts.stor_Sales_DisableSerialControl,'False')
					FROM tbStorage					ts			WITH (NOLOCK)
					INNER JOIN tbSaleOrderDetail	tsod		WITH (NOLOCK)
						ON	tsod.comp_id    = ts.comp_id AND
							tsod.stor_id    = ts.stor_id
					WHERE		IsNull(ts.stor_Sales_DisableSerialControl,'False') = 'True'
							AND	tsod.comp_id	= @comp_id
							AND tsod.bra_id		= @soh_BraId
							AND tsod.soh_id		= @soh_id

			END


	While @@Fetch_Status = 0
		Begin

			-- Obtiene la forma de procesar, si es x numero de serie o x despacho.-
			Select	@item_expser	= ISNULL(A.item_expser,'False'),
					@item_expLote	= ISNULL(A.item_expLote,'False')
				From dbo.tbItem		A				WITH (NOLOCK)
				Where	comp_id = @comp_id
					and item_id = @item_id
			-- ------------------



			-- ----------------------------------------------------
			-- FIX por si se tomaron numeros de serie de articulos
			-- que luego se pusieron como NO serializables.!!!!!!!
			-- ----------------------------------------------------
			IF @item_expser = 'False' AND EXISTS(
													SELECT TOP 1 1
														FROM tbSaleOrderSerials tsos			WITH (NOLOCK)
														INNER JOIN tbItemSerials tis			WITH (NOLOCK)
															ON	tis.comp_id = tsos.comp_id AND
																tis.is_id	= tsos.is_id
														WHERE	tsos.comp_id	= @comp_id		AND
																tsos.bra_id		= @soh_BraId	AND
																tsos.soh_id		= @soh_id		AND
																tis.item_id     = @item_id
												)
				BEGIN

					DELETE FROM tbSaleOrderSerials			WITH (ROWLOCK)
						FROM tbSaleOrderSerials tsos
						INNER JOIN tbItemSerials tis		WITH (NOLOCK)
							ON	tis.comp_id = tsos.comp_id AND
								tis.is_id	= tsos.is_id
						WHERE	tsos.comp_id	= @comp_id		AND
								tsos.bra_id		= @soh_BraId	AND
								tsos.soh_id		= @soh_id		AND
								tis.item_id     = @item_id

				END
			-- ----------------------------------------------------



			-- -------------------------------------------------------------------------------------------------
			--Si se desconto Stock
			IF @it_transaction_NoStockDiscount = 'False'
				BEGIN


					If @item_expser='True' AND @bitSaleOrderEmittion_AllImportDataByItem = 'False' --AND (not @item_id IS NULL)
					-- -------------------------------------------------------------------------------------------------
					-- COMIENZO Verificación de Número de Serie ---------------------------------------------------
					-- -------------------------------------------------------------------------------------------------
						Begin


							-- Verifica 1ro que tenga tomados suficientes numeros de serie para el renglon.-
							-- Sea un Debito o un Credito.!!!

								Select
										A.is_id,
										B.item_id,
										ISID.impData_id,
										ISID.import_id,
										@tis_id [ItemCounter],
										ISID.impData_Custom_local,
										ISID.impData_Number_local,
										ROW_NUMBER() OVER (ORDER BY A.comp_id) AS 			[RefDuplicado]
									Into #tmpAvailableItemSerials
									From  dbo.tbSaleOrderSerials	A					WITH (NOLOCK)
									Inner Join tbItemSerials		B					WITH (NOLOCK)
										ON      B.comp_id =			A.Comp_id
											and B.is_id   =			A.is_id
									Inner Join dbo.vwItemSerialsImportData_SO	ISID	WITH (NOLOCK)	-- x Performance se puso el where en esta vista
										On		ISID.comp_id		= B.comp_id
											and ISID.ct_transaction = B.ct_transaction
											and ISID.it_transaction = B.it_transaction
											AND ISID.is_id			= B.is_id
											AND ISID.ITEM_ID		= B.item_id		-- mos 07-2013 X ERROR DE MIGRACION DE GRUPO NUCLEO
																					-- nO DEBERIA MOLESTAR YA QUE LOS ITEM_ID DEBEN SER IGUALES
																					-- TANTO EN LA tbImportData como en tbItemSerial e tbItemTransaction
									Where  ( A.comp_id		= @comp_id
										and	(A.sose_guid	= @tis_guid or ( A.bra_id = @soh_BraId AND A.soh_id = @soh_id))
										and B.item_id		= @item_id
											)



								-- Borra POsibles Duplicados en la Temporal
								DELETE FROM #tmpAvailableItemSerials
									FROM	#tmpAvailableItemSerials tmp
									WHERE EXISTS(
													SELECT TOP 1 1
														FROM	#tmpAvailableItemSerials tmp2
														WHERE	tmp2.is_id			=  tmp.is_id		AND
																tmp2.RefDuplicado	<> tmp.RefDuplicado
												)



								INSERT into #tmpAvailableItemSerials
									(is_id,
									 item_id,
									 impdata_id,
									 import_Id,
									 ItemCounter,
 									 impData_Custom_local,
									 impData_Number_local,
									 RefDuplicado
									)
									(Select
											ttis.is_id,
											ttis.item_id,
											ISID.impData_id,
											ISID.import_id,
											@tis_id,
											ISID.impData_Custom_local,
											ISID.impData_Number_local,
											((ROW_NUMBER() OVER (ORDER BY ttis.comp_id )) * -1)	[RefDuplicado]
										FROM  tbTempItemStock		ttis				WITH (NOLOCK)
										Inner Join tbItemSerials	ItS					WITH (NOLOCK)
											ON      ItS.comp_id = ttis.Comp_id
												and ItS.is_id   = ttis.is_id
										Inner Join dbo.vwItemSerialsImportData	ISID	WITH (NOLOCK)
											On		ISID.comp_id		= ItS.comp_id
												and ISID.ct_transaction = ItS.ct_transaction
												and ISID.it_transaction = ItS.it_transaction
												AND ISID.item_id		= ITS.item_id			-- MOS: 7-2013  ERROR MIGRACION GRUPO NUCLEO
										WHERE	ttis.comp_id	= @comp_id
											AND ttis.tis_guid	= @tis_guid
											AND ttis.item_id	= @item_id
											AND not ttis.is_id  IS NULL
											AND ttis.tis_id		= @tis_id
											AND NOT EXISTS(
															SELECT TOP 1 1
																FROM #tmpAvailableItemSerials tmp
																WHERE tmp.is_id = ttis.is_id
														  )
									)


								-- Borra POsibles Duplicados en la Temporal
								DELETE FROM #tmpAvailableItemSerials
									FROM	#tmpAvailableItemSerials tmp
									WHERE EXISTS(
													SELECT TOP 1 1
														FROM	#tmpAvailableItemSerials tmp2
														WHERE	tmp2.is_id			=  tmp.is_id		AND
																tmp2.RefDuplicado	<> tmp.RefDuplicado
												)



								-- Cuenta cuantos son los disponibles
								SELECT @SerialsAvailable = Count(*)
									From #tmpAvailableItemSerials
									Where item_id = @item_id


								SET @intSerialNumberDifference = @tis_qty - @SerialsAvailable

								-- MOS 10-2022 SO, si es nc de un rm de fc anticipada que NO se emitió y se hace x el deposito mentiroso conf en el documento.
								DECLARE @bitIsCreditNoteOfPreinvoiceWithOutPLEmmited AS BIT = 'False'
								IF	@stor_id								IS NOT NULL AND
									@stor_id4SaleOrderpreInvoiceCreditNote	IS NOT NULL AND
									@stor_id								=  @stor_id4SaleOrderpreInvoiceCreditNote
									BEGIN
										SET @bitIsCreditNoteOfPreinvoiceWithOutPLEmmited = 'True'
									END


								-- Si no alcanzan los numeros de serie, cancela
								If	@SerialsAvailable < @tis_qty								AND
									@bitEmissionWithOutSerialization				= 'False'	AND
									@bitIsCreditNoteOfPreinvoiceWithOutPLEmmited	= 'False'			-- MOS 10-2022
									Begin
										Set @ret_ErrorCode = -1
										Select @ret_ErrorDescription = isNull(utexts_desc,'* Error ImportData *')
											From dbo.tbsysUniqueTexts		WITH (NOLOCK)
											Where    lang_id   = @lang_id
												and  utexts_id = 200001
										Set @ret_ErrorDescription = @ret_ErrorDescription +	convert(varchar,IsNull(@item_id,0)) + '-' + IsNull(@tis_itemDesc,'*ItemDesc*') + ' Qty:' + CONVERT(VARCHAR,Isnull(@SerialsAvailable,0)) + '/' + convert(varchar,IsNull(@tis_qty,0))

										Return
									End
								Else
									Begin

										--- 1ro.!!!
										--- Insert en la tabla de movimientos de numeros
										--- de serie de los Numeros de Serie Recien pasados
										--- como no disponibles (En el Update 4to se ponen como NO DISP)
										INSERT INTO [dbo].[tbItemTransactionSerials]
												   ([comp_id]
												   ,[bra_id]
												   ,[it_transaction]
												   ,[is_id]
												   ,[impData_id]
												   ,[import_id]
												   ,[ct_transaction])
													(Select TOP (Convert(int,@tis_qty))
															 @comp_id,
															 @bra_id,
															 @it_transaction,
															 C.is_id,
															 C.impData_id,
															 C.import_id,
															 @ct_transaction
														From #tmpAvailableItemSerials C
													)



										--- -------------------------------------------------------------------
										--- 1.5
										--- Inserta los casilleros en blanco que quedaron en caso que el pedido
										--- se cerro FORZADO.!
										--- Esto es una MIERDA que la pidio Gastion de FAG
										--- Que NADIE lo use pls.!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
										--- -------------------------------------------------------------------
										SET @intAuxCounter = 1
										WHILE @intAuxCounter <= @intSerialNumberDifference
											BEGIN
												INSERT INTO [dbo].[tbItemTransactionSerials]		WITH (ROWLOCK)
														   ([comp_id]
														   ,[bra_id]
														   ,[it_transaction]
														   ,[is_id]
														   ,[impData_id]
														   ,[import_id]
														   ,[ct_transaction])
															(Select
																	 @comp_id,
																	 @bra_id,
																	 @it_transaction,
																	 NULL,
																	 NULL,
																	 NULL,
																	 @ct_transaction
															)
												SET @intAuxCounter = @intAuxCounter + 1
											END
										--- -------------------------------------------------------------------


										--- 2do.!!!
										--- Grabar los Movimientos de Despachos
										INSERT INTO [dbo].[tbItemTransactionImportData]				WITH (ROWLOCK)
												   ([comp_id],
													[bra_id],
													[ct_transaction],
													[it_transaction],
													[import_id],
													[impData_id],
													itid_qty,
													impData_Custom_local,
													impData_Number_local)

												   (Select TOP (Convert(int,@tis_qty))
															@comp_id,
															@bra_id,
															@ct_transaction,
															@it_transaction,
															C.import_id,
															C.impData_id,
															1,
															C.impData_Custom_local,
															C.impData_Number_local
														From #tmpAvailableItemSerials C
													)

										--- -------------------------------------------------------------------
										--- 2.5   Grabar aca los itemtransactionimportdata que estan vacios ( no serializados)
										-- luego DEBERAN ser llenados por la pagina de serializacion de ventas asi como los numeros de serie.
										--- -------------------------------------------------------------------
										SET @intAuxCounter = 1
										WHILE @intAuxCounter <= @intSerialNumberDifference
											BEGIN

												INSERT INTO [dbo].[tbItemTransactionImportData]		WITH (ROWLOCK)
														   ([comp_id],
															[bra_id],
															[ct_transaction],
															[it_transaction],
															[import_id],
															[impData_id],
															itid_qty,
															impData_Custom_local,
															impData_Number_local)
														VALUES
														   (
																	@comp_id,
																	@bra_id,
																	@ct_transaction,
																	@it_transaction,
																	NULL,
																	NULL,
																	1,
																	'',
																	''
															)

												SET @intAuxCounter = @intAuxCounter + 1
											END
										--- -------------------------------------------------------------------


										---
										--- 3ro!!!
										Insert #tmpUpdatedSerials
											( impData_id,
											  import_id,
											  is_id,
											  item_id
											 )
										Select TOP (Convert(int,@tis_qty)) B.impData_id,B.import_id,B.is_id,B.item_id
													From #tmpAvailableItemSerials B
													Where B.item_id = @item_id


										--- 4do.!!!
										--- Poner como NO Disponibles a todos los Seriales
										--- que son usados al menos x el item anterior
										--- por eso se usa el TOP
										Update tbItemSerials		WITH (ROWLOCK)
											Set is_Available = Case @tis_isCredit
																	When 'False' then 'False'
																	When 'True'  then 'True'
															   End,
												is_guid		 = @tis_guid
											From (Select TOP (Convert(int,@tis_qty)) B.is_id
													From #tmpAvailableItemSerials B
													Where B.item_id = @item_id
												  ) As C
											Where	tbItemSerials.comp_id = @comp_id
												and	tbItemSerials.is_id   = C.is_id
												AND tbItemSerials.is_serial IS NOT NULL		-- Solo x tema Performance.


										DELETE FROM tbSaleOrderSerials	WITH (ROWLOCK)
										WHERE	comp_id = @comp_id
											AND bra_id	= @soh_BraId
											AND soh_id	= @soh_id
											AND is_id IN (
																Select TOP (Convert(int,@tis_qty)) B.is_id
																	From #tmpAvailableItemSerials B
																	Where B.item_id = @item_id
															  )



									END

							TRUNCATE TABLE #tmpAvailableItemSerials

							Drop Table #tmpAvailableItemSerials

							SET @intItemCounter = @intItemCounter + 1
						END
						-- FIN Verificación de Número de Serie ---------------------------------------------------



					ELSE

						-- /////////////////////////////////////////////////////////////////////////////////////////////////
						-- Procesamiento si NO POSEE Numero de Serie
						-- /////////////////////////////////////////////////////////////////////////////////////////////////


						BEGIN

							Declare @crImport_id   as int
							Declare @crImpData_Id  as int
							Declare @crQty		   as decimal(19,6)
							Declare @crtis_Qty     as decimal(19,6)

							-- ////////////////////////////////////////////////////
							-- Buscar los Despachos Correspondientes segun CREDITO
							-- ////////////////////////////////////////////////////
							If @tis_isCredit = 'true'
								Begin
										Select  A.impData_ActualQty,
												A.impdata_InitialQty,
												(A.impdata_InitialQty - A.impData_ActualQty) as impdata_Available,
												A.item_id,
												VII.import_id,
												A.impData_Id,
												B.import_cd
										Into #tmpAvailableImportdataForCredit
										From dbo.tbImportData						A		WITH (NOLOCK)
										INNER JOIN  @tmpBranchs4ImportData	branchs		-- MOS 07-2024: para que solo se usen los despachos de ese grupo de sucursales.
											ON branchs.bra_id = A.bra_id
										LEFT JOIN tbCommercialTransactions tct			WITH (NOLOCK)
											ON	tct.comp_id				= A.comp_id AND
												tct.ct_transaction		= A.ct_transaction
										Left Join vwImportdata_ImportId			VII		WITH (NOLOCK)
											On		VII.comp_id			= A.comp_id
												and VII.ct_transaction	= A.ct_transaction
										Left Join dbo.tbImport					B		WITH (NOLOCK)
											On      A.comp_id			= B.comp_id
												and VII.import_id		= B.import_id
										Where   A.comp_id					= @comp_id
											and A.item_id					= @item_id
											and impData_ActualQty			< impdata_InitialQty
										Order BY	A.impdata_Priority,
													CASE
														WHEN [impData_number] <> '' THEN 1
														ELSE							 2
													END,
													tct.ct_date,
													B.import_cd

									Set @crTis_Qty = @tis_qty

									Declare crAvailableImportdataForCredit
									CURSOR LOCAL  FAST_FORWARD For
										Select import_id,impData_Id,impdata_Available
											From #tmpAvailableImportdataForCredit

									Open crAvailableImportdataForCredit

									Fetch Next From crAvailableImportdataForCredit
										Into @crImport_id,@crImpData_Id,@crQty

									While @@Fetch_Status = 0 and @crTis_Qty > 0
									Begin

										If @tis_qty <= @crQty
											Begin
												Update dbo.tbImportData
													Set impData_ActualQty = impData_ActualQty + @crTis_Qty
													Where	comp_id    = @comp_id AND
															item_id    = @item_id AND
															impdata_id = @crImpData_Id


														Insert dbo.tbItemTransactionImportData		WITH (ROWLOCK)
															(comp_id,
															 bra_id,
															 ct_transaction,
															 it_transaction,
															 impdata_id,
															 import_id,
															 itid_qty,
															 impData_Number_localPreAssignedByFiscal,
															 impData_Custom_localPreAssignedByFiscal
															)
														Values
															(@comp_id,
															 @bra_id,
															 @ct_transaction,
															 @it_transaction,
															 @crImpData_Id,
															 @crImport_id ,
															 @crTis_Qty,
															 @impData_Number_localPreAssignedByFiscal,
															 @impData_Custom_localPreAssignedByFiscal
															)

													Set @crTis_Qty   = 0
											End
										Else
											Begin
												Update dbo.tbImportData	WITH (ROWLOCK)
													Set impData_ActualQty = impData_InitialQty
													Where	comp_id    = @comp_id
														and item_id    = @item_id
														and impdata_id = @crImpData_Id



														Insert dbo.tbItemTransactionImportData		WITH (ROWLOCK)
															(comp_id,
															 bra_id,
															 ct_transaction,
															 it_transaction,
															 impdata_id,
															 import_id,
															 itid_qty,
															 impData_Number_localPreAssignedByFiscal,
															 impData_Custom_localPreAssignedByFiscal
															)
														Values
															(@comp_id,
															 @bra_id,
															 @ct_transaction,
															 @it_transaction,
															 @crImpData_Id,
															 @crImport_id ,
															 @crQty,
															 @impData_Number_localPreAssignedByFiscal,
															 @impData_Custom_localPreAssignedByFiscal
															)

													Set @crTis_Qty   = @crTis_Qty - @crQty
											End

										Fetch Next From crAvailableImportdataForCredit
											Into @crImport_id,@crImpData_Id,@crQty
									End

									Drop Table #tmpAvailableImportdataForCredit

									Close      crAvailableImportdataForCredit

									Deallocate crAvailableImportdataForCredit

								End



							Else
								-- ////////////////////////////////////////////////////
								-- Buscar los Despachos Correspondientes segun DEBITO
								-- ////////////////////////////////////////////////////
								BEGIN


									-- MOS 06-2024: x cada articulo de la tbTempItemStock se deberia generar una temporal que contenga SOLO los que se habilitaron en preparacion de pedidos para ser asignados, siempre y cuando el articulo diga
									--              q debe tener seguimiento de lote.  en preparacion de pedidos esos articulos deben tener lote asignado y debe ir descontandose lo que está asignado en la tabla temporal que gusrda esas asignaciones, la cual se debe liberar al terminar
									--              este proceso.
									-- La asignacion de un lote va a ser UNICA por cada saleorderdetail.
									-- Si el articulo es por lote, IS O SI debe estar en la tabla de detail de lotes, sino NO permitir asignar a NADA. y debe dar error al tratar de emitir la fatura.

									-- MOS 07-2024: Se hace que si el articulo PIDE LOTE, SI O SI deba estár la tabla de preparacion de pedidos con su lote asignado.
									Select  DISTINCT	-- MOS 07-2024
											A.impData_ActualQty,
											A.impdata_InitialQty,
											A.item_id,
											VII.import_id,
											A.impData_Id,
											B.import_cd,
											A.impdata_Priority,			-- MOS 07-2024: se agregó solo x el distinct x el left con tbSaleOrderDetailImportData
											A.impData_ExpirationDate	-- MOS 07-2024: se agregó solo x el distinct x el left con tbSaleOrderDetailImportData
										Into #tmpAvailableImportdataForDebit
										From dbo.tbImportData					AS	A			WITH (NOLOCK)
										INNER JOIN  @tmpBranchs4ImportData	branchs		-- MOS 07-2024: para que solo se usen los despachos de ese grupo de sucursales.
											ON branchs.bra_id = A.bra_id
										LEFT JOIN vwImportdata_ImportId			AS	VII			WITH (NOLOCK)
											On	VII.comp_id			= A.comp_id		AND
												VII.ct_transaction	= A.ct_transaction
										LEFT JOIN dbo.tbImport					AS	B			WITH (NOLOCK)
											On	B.comp_id			= A.comp_id		AND
												B.import_id			= VII.import_id
										LEFT JOIN tbSaleOrderDetailImportData	AS	tsodid		WITH (NOLOCK)	-- MOS 07-2024: solo LEFT asi NO molesta si el articulo NO tiene vencimiento.
											ON  tsodid.comp_id		= A.comp_id		AND
												tsodid.impData_id	= A.impData_id	AND
												tsodid.bra_id		= @soh_BraId	AND
												tsodid.soh_id		= @soh_id		AND
												tsodid.sod_id		= @sod_id
										Where   A.comp_id			= @comp_id		AND
												A.item_id			= @item_id		AND
												A.impData_ActualQty > 0				AND
												CASE	-- MOS 07-2024: Si es articulo con VENCIMIENTO, SI o SI DEBE tener el PEDIDO un impdata_id asignado
													WHEN @item_expLote		= 'False'									THEN 1
													WHEN @item_expLote		= 'True'	AND tsodid.comp_id IS NOT NULL	THEN 1
													WHEN @item_expLote		= 'True'	AND tsodid.comp_id IS NULL		THEN 0
													ELSE																	 0
												END = 1
										Order BY A.impdata_Priority,
												 A.impData_ExpirationDate,	-- MOS 07-2024
												 B.import_cd


									-- AYENCION: NO PONER NADA ENTRE LA QUERY ANTERIOR Y ESTA COMPARACION !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
									-- MOS 07-2024: Si NO encuentra ningun lote debe cancelar y dar error.
									IF @item_expLote = 'True' AND @@ROWCOUNT = 0
										BEGIN
											Set @ret_ErrorCode = -1
											Select @ret_ErrorDescription = 'Artículo con Verificación de Lote y Vencimiento: No hay sufucuente stock en el Lote asignado a un Articulo con control de Lote. '
											Set @ret_ErrorDescription = @ret_ErrorDescription +	convert(varchar,IsNull(@item_id,0)) + '-' + IsNull(@tis_itemDesc,'*ItemDesc*') + ' Qty:' + CONVERT(VARCHAR,Isnull(@SerialsAvailable,0)) + '/' + convert(varchar,IsNull(@tis_qty,0))
											Return
										END


									--Select  A.impData_ActualQty,
									--		A.impdata_InitialQty,
									--		A.item_id,
									--		VII.import_id,
									--		A.impData_Id,
									--		B.import_cd
									--	Into #tmpAvailableImportdataForDebit
									--	From dbo.tbImportData						A			WITH (NOLOCK)
									--	Left Join vwImportdata_ImportId				VII			WITH (NOLOCK)
									--		On	VII.comp_id			= A.comp_id		AND
									--			VII.ct_transaction	= A.ct_transaction
									--	Left Join dbo.tbImport						B			WITH (NOLOCK)
									--		On	B.comp_id			= A.comp_id				AND
									--			B.import_id			= VII.import_id
									--	Where   A.comp_id			= @comp_id
									--		and A.item_id			= @item_id
									--		and A.impData_ActualQty > 0
									--	Order BY A.impdata_Priority,B.import_cd







									Set @crTis_Qty = @tis_qty

									Declare crAvailableImportdataForDebit
									CURSOR LOCAL  FAST_FORWARD For
										Select import_id,impData_Id,impData_ActualQty
											From #tmpAvailableImportdataForDebit

									Open crAvailableImportdataForDebit

									Fetch Next From crAvailableImportdataForDebit
										Into	@crImport_id,
												@crImpData_Id,
												@crQty


									DECLARE @impData_Custom_local AS VARCHAR(20)
									DECLARE @impData_Number_local AS VARCHAR(20)

									While @@Fetch_Status = 0 and @crTis_Qty > 0
										Begin

											-- Busca los Despachos de compras Locales
											-- Estos se insertan siempre.  Si es una importacion
											-- propia, deberian estar en NULL.
											SELECT	@impData_Custom_local	= tid.impData_Custom_local,
													@impData_Number_local	= tid.impData_Number_local
												FROM tbImportData tid	WITH (NOLOCK)
												WHERE	tid.comp_id		= @comp_id
													AND TID.impData_id	= @crImpData_Id

											If @tis_qty <= @crQty
												Begin
													Update dbo.tbImportData	WITH (ROWLOCK)
														Set impData_ActualQty = impData_ActualQty - @crTis_Qty
														Where comp_id    = @comp_id
														  and impdata_id = @crImpData_Id
														  and item_id    = @item_id



														Insert dbo.tbItemTransactionImportData		WITH (ROWLOCK)
																(comp_id,
																 bra_id,
																 ct_transaction,
																 it_transaction,
																 impdata_id,
																 import_id,
																 itid_qty,
																 impData_Custom_local,
																 impData_Number_local,
																 impData_Number_localPreAssignedByFiscal,
																 impData_Custom_localPreAssignedByFiscal
																)
															Values
																(@comp_id,
																 @bra_id,
																 @ct_transaction,
																 @it_transaction,
																 @crImpData_Id,
																 @crImport_id ,
																 @crTis_Qty,
																 @impData_Custom_local,
																 @impData_Number_local,
																 @impData_Number_localPreAssignedByFiscal,
																 @impData_Custom_localPreAssignedByFiscal
																)

														Set @crTis_Qty = 0
												End
											ELSE	-- El Lote NO alzanza y hay que crear un lote nuevo a cuenta de un próximo ingreso
												BEGIN

														-- MOS 06-2024
														-- NO debe permitir emitir por Lote ya que un lote debe alcanzar POR COMPLETO para la emision de un articulo por Lote
														IF @item_expLote = 'True'
															BEGIN
																Set @ret_ErrorCode = -1
																Select @ret_ErrorDescription = 'ATENCIÓN: No hay sufucuente stock en el Lote asignado a un Articulo con control de Lote. '
																Set @ret_ErrorDescription = @ret_ErrorDescription +	convert(varchar,IsNull(@item_id,0)) + '-' + IsNull(@tis_itemDesc,'*ItemDesc*') + ' Qty:' + CONVERT(VARCHAR,Isnull(@SerialsAvailable,0)) + '/' + convert(varchar,IsNull(@tis_qty,0))

																Return
															END

														Update dbo.tbImportData		WITH (ROWLOCK)
															Set impData_ActualQty = 0
															Where comp_id    = @comp_id
															  and impdata_id = @crImpData_Id
															  and item_id    = @item_id


														Insert dbo.tbItemTransactionImportData		WITH (ROWLOCK)
															(comp_id,
																bra_id,
																ct_transaction,
																it_transaction,
																impdata_id,
																import_id,
																itid_qty,
																impData_Custom_local,
																impData_Number_local,
																impData_Number_localPreAssignedByFiscal,
																impData_Custom_localPreAssignedByFiscal)
														Values
															(@comp_id,
																@bra_id,
																@ct_transaction,
																@it_transaction,
																@crImpData_Id,
																@crImport_id ,
																@crQty,
																@impData_Custom_local,
																@impData_Number_local,
																@impData_Number_localPreAssignedByFiscal,
																@impData_Custom_localPreAssignedByFiscal)

															Set @crTis_Qty = @crTis_Qty - @crQty
													End

											Fetch Next From crAvailableImportdataForDebit
												Into	@crImport_id,
														@crImpData_Id,
														@crQty
										End

									Drop Table #tmpAvailableImportdataForDebit

									Close      crAvailableImportdataForDebit

									Deallocate crAvailableImportdataForDebit

								End


							-- Grabar los Movimientos Correspondientes de los despachos





						End

					-- -------------------------------------------------------------------------------------------------
					-- ATENCION
					-- Si se sacan los despachos como si no fuesen serializados hay que grabar si o si los numeros de serie,
					-- por eso se copia la parte de serializados sacando lo que no es necesario.-
					-- NUCLEO: Ya que cuando ingresan stock y ponen equivocado si es serializable o no
					--         quieren que no se tenga que anular y reingresar por lo que generan lotes solo para
					--         tomar los nros de serie y tampoco quieren que se ingrese el nro de despacho correspondiente
					--         en ese ajuste. NO USAR PARA NADIE MAS, ES INCORRECTO HACER ESTO!!!!!!
					-- -------------------------------------------------------------------------------------------------
					If @item_expser='True' AND @bitSaleOrderEmittion_AllImportDataByItem = 'True'

						Begin


							-- Verifica 1ro que tenga tomados suficientes numeros de serie para el renglon.-
							-- Sea un Debito o un Credito.!!!

								SELECT
										A.is_id,
										B.item_id,
										ISID.impData_id,
										ISID.import_id,
										@tis_id						[ItemCounter],
										ISID.impData_Custom_local,
										ISID.impData_Number_local,
										ROW_NUMBER() OVER (ORDER BY A.comp_id ) AS 			[RefDuplicado]
									Into #tmpAvailableItemSerialsV2
									From  dbo.tbSaleOrderSerials	A					WITH (NOLOCK)
									Inner Join tbItemSerials		B					WITH (NOLOCK)
										ON      A.comp_id =			B.Comp_id
											and A.is_id   =			B.is_id
									Inner Join dbo.vwItemSerialsImportData_SO	ISID	WITH (NOLOCK)	-- x Performance se puso el where en esta vista
										On		ISID.comp_id		= B.comp_id
											and ISID.ct_transaction = B.ct_transaction
											and ISID.it_transaction = B.it_transaction
											AND ISID.is_id			= B.is_id
											AND ISID.ITEM_ID		= B.item_id		-- mos 07-2013 X ERROR DE MIGRACION DE GRUPO NUCLEO
																					-- nO DEBERIA MOLESTAR YA QUE LOS ITEM_ID DEBEN SER IGUALES
																					-- TANTO EN LA tbImportData como en tbItemSerial e tbItemTransaction
									Where  ( A.comp_id		= @comp_id
										and	(A.sose_guid	= @tis_guid or ( A.bra_id = @soh_BraId AND A.soh_id = @soh_id))
										and B.item_id		= @item_id
											)



								-- Borra POsibles Duplicados en la Temporal
								DELETE FROM #tmpAvailableItemSerialsV2
									FROM	#tmpAvailableItemSerialsV2 tmp
									WHERE EXISTS(
													SELECT TOP 1 1
														FROM	#tmpAvailableItemSerialsV2 tmp2
														WHERE	tmp2.is_id			=  tmp.is_id		AND
																tmp2.RefDuplicado	<> tmp.RefDuplicado
												)


								INSERT into #tmpAvailableItemSerialsV2
									(is_id,
									 item_id,
									 impdata_id,
									 import_Id,
									 ItemCounter,
 									 impData_Custom_local,
									 impData_Number_local,
									 RefDuplicado
									)
									(Select
											ttis.is_id,
											ttis.item_id,
											ISID.impData_id,
											ISID.import_id,
											@tis_id,
											ISID.impData_Custom_local,
											ISID.impData_Number_local,
											((ROW_NUMBER() OVER (ORDER BY ttis.comp_id )) * -1)	[RefDuplicado]
										FROM  tbTempItemStock		ttis				WITH (NOLOCK)
										Inner Join tbItemSerials	ItS					WITH (NOLOCK)
											ON      ItS.comp_id = ttis.Comp_id
												and ItS.is_id   = ttis.is_id
										Inner Join dbo.vwItemSerialsImportData	ISID	WITH (NOLOCK)
											On		ISID.comp_id		= ItS.comp_id
												and ISID.ct_transaction = ItS.ct_transaction
												and ISID.it_transaction = ItS.it_transaction
												AND ISID.item_id		= ITS.item_id			-- MOS: 7-2013  ERROR MIGRACION GRUPO NUCLEO
										WHERE	ttis.comp_id	= @comp_id
											AND ttis.tis_guid	= @tis_guid
											AND ttis.item_id	= @item_id
											AND not ttis.is_id  IS NULL
											AND ttis.tis_id		= @tis_id
											AND NOT EXISTS(
															SELECT TOP 1 1
																FROM #tmpAvailableItemSerialsV2 tmp
																WHERE tmp.is_id = ttis.is_id
														  )
									)



								-- Borra POsibles Duplicados en la Temporal
								DELETE FROM #tmpAvailableItemSerialsV2
									FROM	#tmpAvailableItemSerialsV2 tmp
									WHERE EXISTS(
													SELECT TOP 1 1
														FROM	#tmpAvailableItemSerialsV2 tmp2
														WHERE	tmp2.is_id			=  tmp.is_id		AND
																tmp2.RefDuplicado	<> tmp.RefDuplicado
												)

								-- Cuenta cuantos son los disponibles
								SELECT @SerialsAvailable = Count(*)
									From #tmpAvailableItemSerialsV2
									Where item_id = @item_id


								-- MOS 10-2022 SO, si es nc de un rm de fc anticipada que NO se emitió y se hace x el deposito mentiroso conf en el documento.
								DECLARE @bitIsCreditNoteOfPreinvoiceWithOutPLEmmited2 AS BIT = 'False'
								IF	@stor_id								IS NOT NULL AND
									@stor_id4SaleOrderpreInvoiceCreditNote	IS NOT NULL AND
									@stor_id								=  @stor_id4SaleOrderpreInvoiceCreditNote
									BEGIN
										SET @bitIsCreditNoteOfPreinvoiceWithOutPLEmmited2 = 'True'
									END




								SET @intSerialNumberDifference = @tis_qty - @SerialsAvailable

								-- Si no alcanzan los numeros de serie, cancela
								If	@SerialsAvailable < @tis_qty								AND
									@bitEmissionWithOutSerialization				= 'False'	AND
									@bitIsCreditNoteOfPreinvoiceWithOutPLEmmited2	= 'False'			-- MOS 10-2022
									Begin
										Set @ret_ErrorCode = -1
										Select @ret_ErrorDescription = isNull(utexts_desc,'* Error ImportData *')
											From dbo.tbsysUniqueTexts		WITH (NOLOCK)
											Where    lang_id   = @lang_id
												and  utexts_id = 200001
										Set @ret_ErrorDescription = @ret_ErrorDescription +	convert(varchar,IsNull(@item_id,0)) + '-' + IsNull(@tis_itemDesc,'*ItemDesc*') + ' Qty:' + CONVERT(VARCHAR,Isnull(@SerialsAvailable,0)) + '/' + convert(varchar,IsNull(@tis_qty,0))

										Return
									End
								Else
									Begin

										--- 1ro.!!!
										--- Insert en la tabla de movimientos de numeros
										--- de serie de los Numeros de Serie Recien pasados
										--- como no disponibles (En el Update 4to se ponen como NO DISP)
										INSERT INTO [dbo].[tbItemTransactionSerials]		WITH (ROWLOCK)
												   ([comp_id]
												   ,[bra_id]
												   ,[it_transaction]
												   ,[is_id]
												   ,[impData_id]
												   ,[import_id]
												   ,[ct_transaction])
													(Select TOP (Convert(int,@tis_qty))
															 @comp_id,
															 @bra_id,
															 @it_transaction,
															 C.is_id,
															 C.impData_id,
															 C.import_id,
															 @ct_transaction
														From #tmpAvailableItemSerialsV2 C
													)



										--- -------------------------------------------------------------------
										--- 1.5
										--- Inserta los casilleros en blanco que quedaron en caso que el pedido
										--- se cerro FORZADO.!
										--- Esto es una MIERDA que la pidio Gastion de FAG
										--- Que NADIE lo use pls.!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
										--- -------------------------------------------------------------------
										SET @intAuxCounter = 1
										WHILE @intAuxCounter <= @intSerialNumberDifference
											BEGIN
												INSERT INTO [dbo].[tbItemTransactionSerials]		WITH (ROWLOCK)
														   ([comp_id]
														   ,[bra_id]
														   ,[it_transaction]
														   ,[is_id]
														   ,[impData_id]
														   ,[import_id]
														   ,[ct_transaction])
															(Select
																	 @comp_id,
																	 @bra_id,
																	 @it_transaction,
																	 NULL,
																	 NULL,
																	 NULL,
																	 @ct_transaction
															)
												SET @intAuxCounter = @intAuxCounter + 1
											END
										--- -------------------------------------------------------------------


	--									--- 2do.!!!
	--									--- Grabar los Movimientos de Despachos
	--									INSERT INTO [dbo].[tbItemTransactionImportData]
	--											   ([comp_id],
	--												[bra_id],
	--												[ct_transaction],
	--												[it_transaction],
	--												[import_id],
	--												[impData_id],
	--												itid_qty,
	--												impData_Custom_local,
	--												impData_Number_local)
	--
	--											   (Select TOP (Convert(int,@tis_qty))
	--														@comp_id,
	--														@bra_id,
	--														@ct_transaction,
	--														@it_transaction,
	--														C.import_id,
	--														C.impData_id,
	--														1,
	--														C.impData_Custom_local,
	--														C.impData_Number_local
	--													From #tmpAvailableItemSerialsV2 C
	--												)

										--- -------------------------------------------------------------------
										--- 2.5   Grabar aca los itemtransactionimportdata que estan vacios ( no serializados)
										-- luego DEBERAN ser llenados por la pagina de serializacion de ventas asi como los numeros de serie.
										--- -------------------------------------------------------------------
	--									SET @intAuxCounter = 1
	--									WHILE @intAuxCounter <= @intSerialNumberDifference
	--										BEGIN
	--
	--											INSERT INTO [dbo].[tbItemTransactionImportData]
	--													   ([comp_id],
	--														[bra_id],
	--														[ct_transaction],
	--														[it_transaction],
	--														[import_id],
	--														[impData_id],
	--														itid_qty,
	--														impData_Custom_local,
	--														impData_Number_local)
	--													VALUES
	--													   (
	--																@comp_id,
	--																@bra_id,
	--																@ct_transaction,
	--																@it_transaction,
	--																NULL,
	--																NULL,
	--																1,
	--																'',
	--																''
	--														)
	--
	--											SET @intAuxCounter = @intAuxCounter + 1
	--										END
										--- -------------------------------------------------------------------


	--									---
	--									--- 3ro!!!
	--									Insert #tmpUpdatedSerials
	--										( impData_id,
	--										  import_id,
	--										  is_id,
	--										  item_id
	--										 )
	--									Select TOP (Convert(int,@tis_qty)) B.impData_id,B.import_id,B.is_id,B.item_id
	--												From #tmpAvailableItemSerialsV2 B
	--												Where B.item_id = @item_id


										--- 4do.!!!
										--- Poner como NO Disponibles a todos los Seriales
										--- que son usados al menos x el item anterior
										--- por eso se usa el TOP
										Update tbItemSerials		WITH (ROWLOCK)
											Set is_Available = Case @tis_isCredit
																	When 'False' then 'False'
																	When 'True'  then 'True'
															   End,
												is_guid		 = @tis_guid
											From (Select TOP (Convert(int,@tis_qty)) B.is_id
													From #tmpAvailableItemSerialsV2 B
													Where B.item_id = @item_id
												  ) As C
											Where	tbItemSerials.comp_id = @comp_id
												and	tbItemSerials.is_id   = C.is_id
												AND tbItemSerials.is_serial IS NOT NULL		-- Solo x tema Performance.


										DELETE FROM tbSaleOrderSerials	WITH (ROWLOCK)
										WHERE	comp_id = @comp_id
											AND bra_id	= @soh_BraId
											AND soh_id	= @soh_id
											AND is_id IN (
																Select TOP (Convert(int,@tis_qty)) B.is_id
																	From #tmpAvailableItemSerialsV2 B
																	Where B.item_id = @item_id
															  )



									END

							TRUNCATE TABLE #tmpAvailableItemSerialsV2

							Drop Table #tmpAvailableItemSerialsV2

							SET @intItemCounter = @intItemCounter + 1
						END
						-- FIN Verificación de Número de Serie ---------------------------------------------------







				END


			-- /////////////////////////////////////////////////////////////////////////////////////////////////

			Fetch Next From cursor_ITID_ID
				Into
					@tis_id,
					@tis_priority,
					@item_id,
					@tis_itemDesc,
					@tis_detail,
					@tis_curr_id,
					@tis_initQty,
					@tis_qty,
					@prli_id,
					@tis_price,
					@stor_id,
					@doc_id,
					@tis_CD,
					@soh_BraId,
					@soh_id,
					@tis_insertDate,
					@aure_id,
					@tax_id,
					@aure_itemComposed,
					@tis_itemDiscount,
					@tis_CreditInt,
					@tis_CreditIntPlus,
					@tis_itemDiscountTotal,
					@tis_isQuotation,
					@tis_isCredit,
					@tis_production,
					@so_id,
					@it_transaction,
					@it_transaction_Original,
					@it_transaction_NoStockDiscount,
					@impData_Number_localPreAssignedByFiscal,
					@impData_Custom_localPreAssignedByFiscal,
					@sod_id


		End
	Close      cursor_ITID_ID
    DEALLOCATE cursor_ITID_ID


	--- Ultimo.!!!
	--- OJO, verificar x que no descuenta varias veces (seg. cant de items) si son del mismo despacho.-
	--- Descontar de  cantidad disponible de despachos
	Update tbImportData		WITH (ROWLOCK)
		Set impData_ActualQty = (impData_ActualQty - (C.parQty *
														  Case @tis_isCredit
															When 'True'  Then -1
															When 'False' Then 1
														  End
								   					  )
								)
		From (	Select Count(*)		[parQty],
					 B.item_id,
					 B.impdata_id
					From #tmpUpdatedSerials B
					Group By item_id,impdata_id) As C
		Where	tbImportData.comp_id    = @comp_id
			and	tbImportdata.impData_id = C.impData_id
	--- -----------------------------------------------------------------------------------------------

	Drop Table #tmpUpdatedSerials





    -- MOS: 09-2010
    -- Por ultimo, si el comprobante es del tipo Credito, debe dejar como disponibles
    -- a los numeros de serie involucrados en el mismo
	UPDATE tbItemSerials		WITH (ROWLOCK)
		SET
			is_available	= 'True',
			stor_id			= @stor_id		-- MOS 03-2018 x Enferma de Bursesi
		FROM tbItemSerials    tis
		INNER JOIN tbItemTransactionSerials tits			WITH (NOLOCK)
			ON		tits.comp_id		= tis.comp_id	AND
				    tits.is_id			= tis.is_id
		INNER JOIN tbCommercialTransactions tct				WITH (NOLOCK)
			ON		tct.comp_id			= tits.comp_id
				AND tct.ct_transaction	= tits.ct_transaction
	WHERE	tits.comp_id				= @comp_id
		AND tits.ct_transaction			= @ct_transaction
		AND tct.sd_id					= 3  -- Nota de Crédito.!




	-- 05-2012
	-- ----------------------------------------------------------------
	-- Si se puede cerrar sin estar serializado, actualiza despachos
	-- desde el ultimo despacho valido ingresado
	-- MOS 06-2023: Esto pone lento cuando mandan miles de unidades de un articulo SERIALIZABLE que NO tiene series tomados en el pedido.
	-- ----------------------------------------------------------------
	IF EXISTS(
			SELECT TOP 1 1
				FROM tbCommercialTransactions	tct		WITH (NOLOCK)
				INNER JOIN tbDocumentsFile		tdf		WITH (NOLOCK)
					ON		tdf.comp_id = tct.comp_id
						AND tdf.df_id	= tct.df_id
				WHERE	tct.comp_id			= @comp_id
					AND tct.ct_transaction	= @ct_transaction
					AND
					(
						IsNull(tdf.df_SaleOrderEmissionWithOutSerialization,'False')			= 'True'
						OR
						ISNULL(tdf.df_SaleOrderEmission_forceImportDataIfEmptyValues,'False')	= 'True'
					)
			)
		BEGIN
			UPDATE tbItemTransactionImportData		--WITH (ROWLOCK)  MOS 06-2023 x FAG  y agregue el campo impData_Number_local al indice IX_tbImportData_8
			SET
				impData_Custom_local = ISNULL((	SELECT TOP 1 IsNull(tid.impData_Custom_local,'')
													FROM	tbImportData tid								WITH (NOLOCK)
													INNER JOIN  @tmpBranchs4ImportData	branchs		-- MOS 07-2024: para que solo se usen los despachos de ese grupo de sucursales.
														ON branchs.bra_id = tid.bra_id
													WHERE	tid.comp_id = itid.comp_id
														AND tid.item_id = tit.item_id
														AND IsNull(tid.impData_Number_local,'') <> ''
													ORDER BY tid.impData_id DESC
										),''),
				impData_Number_local = ISNULL((	SELECT TOP 1 tid.impData_Number_local
													FROM	tbImportData tid								WITH (NOLOCK)
													INNER JOIN  @tmpBranchs4ImportData	branchs		-- MOS 07-2024: para que solo se usen los despachos de ese grupo de sucursales.
														ON branchs.bra_id = tid.bra_id
													WHERE	tid.comp_id = itid.comp_id
														AND tid.item_id = tit.item_id
														AND IsNull(tid.impData_Number_local,'') <> ''
													ORDER BY tid.impData_id DESC
										),'')
				FROM tbItemTransactionImportData	itid		WITH (NOLOCK)
				INNER JOIN tbItemTransactions	tit			WITH (NOLOCK)
					ON		tit.comp_id				= itid.comp_id
						AND tit.it_transaction		= itid.it_transaction
				WHERE	itid.comp_id				= @comp_id
					AND itid.ct_transaction			= @ct_transaction
					-- MOS 06-2023: x speed de FAG, verifica que sea null o ''
					AND (
							itid.impData_Number_local = ''
								OR
							itid.impData_Number_local IS NULL
						)
					--AND IsNull(itid.impData_Number_local,'') = ''

		END
	-- ----------------------------------------------------------------



	-- ----------------------------------------------------------------
	-- Para los items que digan que se debe forzar un despacho de no tenerlo y NO lo tienen en esta transaccion
	-- se debe generar un tbItemTransactionImportData con estos valores forzados.
	-- Se usa cuando se migra y no esta el tbImportData creado ya que solo se paso la tabla
	-- tbItemStorage y no los movimientos asociados.
	-- ----------------------------------------------------------------
	INSERT INTO tbItemTransactionImportData		WITH (ROWLOCK)
	(
		comp_id,
		it_transaction,
		bra_id,
		ct_transaction,
		import_id,
		impData_id,
		itid_qty,
		impData_Custom_local,
		impData_Number_local
	)
		SELECT	tit.comp_id,
				tit.it_transaction,
				tit.bra_id,
				tit.ct_transaction,
				NULL,
				NULL,
				tit.it_qty,
				ti.impData_Custom_local,
				ti.impData_Number_local
			FROM tbItemTransactions tit						WITH (NOLOCK)
			INNER JOIN tbitem		ti						WITH (NOLOCK)
			ON	ti.comp_id				= tit.comp_id	AND
				ti.item_id				= tit.item_id	AND
				ti.impData_ForceValue	= 'True'
			LEFT JOIN tbItemTransactionImportData itid		WITH (NOLOCK)
				ON itid.comp_id			= tit.comp_id	AND
				   itid.it_transaction  = tit.it_transaction
		WHERE	(
					itid.comp_id		IS NULL		OR
				   (itid.impData_Number_local = '' AND itid.impData_Custom_local = '')
				)
														AND
				tit.comp_id			= @comp_id			AND
				--tit.bra_id			= @bra_id			AND
				tit.ct_transaction	= @ct_transaction	AND
				ti.impData_Custom_local IS NOT NULL		AND
				ti.impData_Number_local IS NOT NULL


	-- ----------------------------------------------------------------


	-- ----------------------------------------------------------------
	-- Si es un remito de Transferencia , actualiza deposito totalizador de Articulos en transito
	-- ----------------------------------------------------------------
	-- se lo pone AFUERA de la trasaccion en wfmSaleOrder x si esto causaba interbloqueos en authogar
	--DECLARE @intDfIdOfThisTrans AS INT = NULL
	--SELECT	@intDfIdOfThisTrans = tct.df_id
	--	FROM tbCommercialTransactions tct				WITH (NOLOCK)
	--	WHERE	tct.comp_id			= @comp_id AND
	--			tct.ct_transaction	= @ct_transaction
	--IF @intDfIdOfThisTrans IS NOT NULL
	--	BEGIN
	--		EXEC spStorage_updateInTransitStock @comp_id,@intDfIdOfThisTrans
	--	END
	-- ----------------------------------------------------------------


END



GO





-- ----------------------------------------------------------------------------------------------------
-- Author : GA
-- Date   :	19/11/15
-- Data   : Para Recepcion de Transferencia entre Sucursales - Anulacion parcial o total de Articulos.
-- ----------------------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spItemTransactions_BranchTransferReception_CancelItem]
(
	@comp_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@ct_transaction			INT,
	@it_transaction			INT,
	@item_id				INT,
	@qtyOriginal			DECIMAL(19,5),
	@qtyCancel				DECIMAL(19,5),
	@stor_id				INT,

	@return_value			AS INT			OUTPUT,
	@ret_ErrorCode			AS INT			OUTPUT,
	@ret_ErrorDescription	AS VARCHAR(200) OUTPUT

)
AS


BEGIN
		SET NOCOUNT ON

		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@bra_id					INT,
				@user_id				INT,
				@ct_transaction			INT,
				@it_transaction			INT,
				@item_id				INT,
				@qtyOriginal			DECIMAL(19,5),
				@qtyCancel				DECIMAL(19,5),
				@stor_id				INT,

				@return_value			AS INT			OUTPUT,
				@ret_ErrorCode			AS INT			OUTPUT,
				@ret_ErrorDescription	AS VARCHAR(200) OUTPUT

			SELECT
				@comp_id				= 1,
				@bra_id					= 1,
				@user_id				= 119,
				@ct_transaction			= 11704,
				@it_transaction			= 11926,
				@qtyOriginal			= 12,
				@qtyCancel				= 1,
				@return_value			= 0,
				@ret_ErrorCode			= 0,
				@ret_ErrorDescription	= ''
		*/
		-- --------------------------------------------

	BEGIN TRY
				SET @return_value			= 0
				SET @ret_ErrorCode			= 0
				SET @ret_ErrorDescription	= ''

				--@qtycancel	-- cantidad a anular
				--@qtyOriginal	-- cantidad original

				IF @qtycancel = @qtyOriginal

					BEGIN
						--SI
						--la cantidad ingresada es IGUAL a la original ( por ende es el total ).

						UPDATE tbItemTransactions

							SET sitt_id = 150		--sitt_id Anulación de Articulos en Recepción de Transferencia entre Sucursales ( Paso 1 )

							WHERE comp_id			= @comp_id			AND
								  --bra_id			= @bra_id			AND
								  it_transaction	= @it_transaction	AND
								  item_id			= @item_id


						-------------------------------------------------------------------------------------------------------------------
						-- Actualizamos la tabla de verificacion de transferencia para seguir viendo lo mismo en esa y en la de anulacion
						UPDATE tbBranchTransferreceptionControl
							SET itr_qty_Transfered = 0

							WHERE comp_id		 = @comp_id				AND
								  ct_transaction = @ct_transaction		AND
								  item_id		 = @item_id
						-------------------------------------------------------------------------------------------------------------------
					END

				ELSE

					BEGIN
						--NO
						--la cantidad ingresada es MENOR a la original
						--Actualizamos

						UPDATE tbItemTransactions
							SET		it_qty = @qtyOriginal - @qtycancel
							WHERE comp_id			= @comp_id			AND
								  --bra_id			= @bra_id			AND
								  it_transaction	= @it_transaction	--AND
								  --item_id			= @item_id

						-------------------------------------------------------------------------------------------------------------------
						-- Actualizamos la tabla de verificacion de transferencia para seguir viendo lo mismo en esa y en la de anulacion
						UPDATE tbBranchTransferreceptionControl
							SET	itr_qty_Transfered = @qtyOriginal - @qtycancel

							WHERE comp_id		 = @comp_id				AND
								  ct_transaction = @ct_transaction		AND
								  item_id		 = @item_id
						 -------------------------------------------------------------------------------------------------------------------

--							-- Paso 1
--							-- ------------------------------------------------------------------------
--							--
--							-- ------------------------------------------------------------------------

							INSERT INTO tbItemTransactions
							(
								comp_id,
								bra_id,
								ct_transaction,
								item_id,
								it_qty,
								it_priceWithOutOthers,
								it_price,
								curr_id,
								it_exchangeToBranchCurrency,
