								it_priceBOfCostLastPurchase,
								it_OriginalPrice,
								it_OriginalPriceCurrency,
								it_exchangeToOriginalPriceCurrency,
								stor_id,
								it_storePrevious,
								prli_id,
								byor_id,
								it_isProduction,
								it_isAssociation,
								it_isAssociationGroup,
								it_cd,
								it_packingInvoicePend,
								it_order,
								so_id,
								it_guarantee,
								it_itemDiscountTotal,
								it_totalDiscountTotal,
								it_CreditInt,
								it_CreditIntPlus,
								puco_id,
								it_poh_bra_id,
								it_poh_id,
								it_soh_id,
								it_sod_id,
								rmah_id,
								rmad_id,
								it_qty_rma,
								it_tis_id_aux,
								it_note1,
								it_note2,
								it_packingInvoiceSelected,
								it_cancelled,
								it_priceB,
								it_isMade,
								it_item_id_origin,
								tmp_tis_id,
								it_packingInvoicePendOriginal,
								it_packingInvoiceSelectedGuid,
								it_transaction_original,
								it_transaction_NoStockDiscount,
								it_SalesCurrId4exchangeToBranchCurrency,
								it_AllUseTag1,
								it_AllUseTag2,
								it_AllUseTag3,
								it_AllUseTag4,
								it_Discount1,
								it_Discount2,
								it_Discount3,
								it_Discount4,
								coslis_id,
								coslis_idB,
								supp_id,
								camp_id,
								it_transaction_originalEW,
								it_IsInternalTransfer,
								it_isRMASupplierCreditNote,
								it_IsFastStockAdjustment,
								it_IsStockAdjustment,
								it_IsStockControl,
								sdlmt_id,
								sreas_id,
								it_loanNumberOfPays,
								sitt_id,
								it_deliveryDate,
								itstkpld_id,
								it_NoStockCheck,
								it_transaction_originaLDIV,
