								it_insuranceDays,
								insud_id,
								insud_certificateNumber
							)
							SELECT
								tit.comp_id,
								tit.bra_id,
								@ct_transaction,
								@item_id,
								@qtycancel,
								tit.it_priceWithOutOthers,
								tit.it_price,
								tit.curr_id,
								tit.it_exchangeToBranchCurrency,
								tit.it_priceOfCost,
								tit.it_priceOfCostPP,
								tit.it_priceOfCostLastPurchase,
								tit.it_priceBOfCost,
								tit.it_priceBOfCostPP,
								tit.it_priceBOfCostLastPurchase,
								tit.it_OriginalPrice,
								tit.it_OriginalPriceCurrency,
								tit.it_exchangeToOriginalPriceCurrency,
								tit.stor_id,
								tit.it_storePrevious,
								tit.prli_id,
								tit.byor_id,
								tit.it_isProduction,
								tit.it_isAssociation,
								tit.it_isAssociationGroup,
								GETDATE(),
								tit.it_packingInvoicePend,
								tit.it_order,
								tit.so_id,
								tit.it_guarantee,
								tit.it_itemDiscountTotal,
								tit.it_totalDiscountTotal,
								tit.it_CreditInt,
								tit.it_CreditIntPlus,
								tit.puco_id,
								tit.it_poh_bra_id,
								tit.it_poh_id,
								tit.it_soh_id,
								tit.it_sod_id,
								tit.rmah_id,
								tit.rmad_id,
								tit.it_qty_rma,
								tit.it_tis_id_aux,
								tit.it_note1,
								tit.it_note2,
								tit.it_packingInvoiceSelected,
								tit.it_cancelled,
								tit.it_priceB,
								tit.it_isMade,
								tit.it_item_id_origin,
								tit.tmp_tis_id,
								tit.it_packingInvoicePendOriginal,
								tit.it_packingInvoiceSelectedGuid,
								tit.it_transaction_original,
								tit.it_transaction_NoStockDiscount,
								tit.it_SalesCurrId4exchangeToBranchCurrency,
								tit.it_AllUseTag1,
								tit.it_AllUseTag2,
								tit.it_AllUseTag3,
								tit.it_AllUseTag4,
								tit.it_Discount1,
								tit.it_Discount2,
								tit.it_Discount3,
								tit.it_Discount4,
								tit.coslis_id,
								tit.coslis_idB,
								tit.supp_id,
								tit.camp_id,
								tit.it_transaction_originalEW,
								tit.it_IsInternalTransfer,
								tit.it_isRMASupplierCreditNote,
								tit.it_IsFastStockAdjustment,
								tit.it_IsStockAdjustment,
								tit.it_IsStockControl,
								tit.sdlmt_id,
								tit.sreas_id,
								tit.it_loanNumberOfPays,
								150,					--sitt_id Anulación de Articulos en Recepción de Transferencia entre Sucursales ( Paso 1 )
								tit.it_deliveryDate,
								tit.itstkpld_id,
								tit.it_NoStockCheck,
								tit.it_transaction_originaLDIV,
								tit.it_surcharge1,
								tit.it_surcharge2,
								tit.it_surcharge3,
								tit.it_surcharge4,
								tit.stor_id_related4BranchTransfer,
								tit.it_transaction_related4BranchTransfer,
								tit.it_pod_id,
								tit.pubh_id,
								tit.it_EWAddress,
								tit.it_insuranceDays,
								tit.insud_id,
								tit.insud_certificateNumber

								FROM tbItemTransactions							tit		WITH(NOLOCK)

								WHERE	tit.comp_id			= @comp_id			AND
										tit.ct_transaction	= @ct_transaction	AND
										tit.it_transaction	= @it_transaction


					END

				--Paso 2

				DECLARE @dec_StorePrevious2	DECIMAL(19,5)
				SET		@dec_StorePrevious2	= 0

				-- ------------------------------------------------------------------------
				-- OBTENEMOS EL STOREPREVIOUS
				-- ------------------------------------------------------------------------
				IF EXISTS(	SELECT
								1
								FROM	tbItemStorage				tis WITH(NOLOCK)
								WHERE	tis.comp_id = @comp_id		AND
										tis.stor_id	= @stor_id		AND
										tis.item_id	= @item_id
						  )
					BEGIN
						SELECT
							@dec_StorePrevious2	= tis.itst_cant
							FROM	tbItemStorage						tis	WITH(NOLOCK)
							Where	tis.comp_id			= @comp_id		AND
									tis.stor_id			= @stor_id		AND
									tis.item_id			= @item_id
					END
				ELSE
					BEGIN
						INSERT INTO tbItemStorage
						(
							comp_id,
							stor_id,
							item_id,
							itst_cant,
							itst_cd
						)
						VALUES
						(
							@comp_id,
							@stor_id,
							@item_id,
							0,
							GETDATE()
						)
						SET @dec_StorePrevious2 = 0
					END

				INSERT INTO tbItemTransactions
				(
					comp_id,
					bra_id,
					ct_transaction,
					item_id,
					it_qty,
					it_priceWithOutOthers,
					it_price,
					curr_id,
					it_exchangeToBranchCurrency,
					it_priceOfCost,
					it_priceOfCostPP,
					it_priceOfCostLastPurchase,
					it_priceBOfCost,
					it_priceBOfCostPP,
					it_priceBOfCostLastPurchase,
					it_OriginalPrice,
					it_OriginalPriceCurrency,
					it_exchangeToOriginalPriceCurrency,
					stor_id,
					it_storePrevious,
					prli_id,
					byor_id,
					it_isProduction,
					it_isAssociation,
					it_isAssociationGroup,
					it_cd,
					it_packingInvoicePend,
					it_order,
					so_id,
					it_guarantee,
					it_itemDiscountTotal,
					it_totalDiscountTotal,
					it_CreditInt,
					it_CreditIntPlus,
					puco_id,
					it_poh_bra_id,
					it_poh_id,
					it_soh_id,
					it_sod_id,
					rmah_id,
					rmad_id,
					it_qty_rma,
					it_tis_id_aux,
					it_note1,
					it_note2,
					it_packingInvoiceSelected,
					it_cancelled,
					it_priceB,
					it_isMade,
					it_item_id_origin,
					tmp_tis_id,
					it_packingInvoicePendOriginal,
					it_packingInvoiceSelectedGuid,
					it_transaction_original,
					it_transaction_NoStockDiscount,
					it_SalesCurrId4exchangeToBranchCurrency,
					it_AllUseTag1,
					it_AllUseTag2,
					it_AllUseTag3,
					it_AllUseTag4,
					it_Discount1,
					it_Discount2,
					it_Discount3,
					it_Discount4,
					coslis_id,
					coslis_idB,
					supp_id,
					camp_id,
					it_transaction_originalEW,
					it_IsInternalTransfer,
					it_isRMASupplierCreditNote,
					it_IsFastStockAdjustment,
					it_IsStockAdjustment,
					it_IsStockControl,
					sdlmt_id,
					sreas_id,
					it_loanNumberOfPays,
					sitt_id,
					it_deliveryDate,
					itstkpld_id,
					it_NoStockCheck,
					it_transaction_originaLDIV,
					it_surcharge1,
					it_surcharge2,
					it_surcharge3,
					it_surcharge4,
					stor_id_related4BranchTransfer,
					it_transaction_related4BranchTransfer,
					it_pod_id,
					pubh_id,
					it_EWAddress,
					it_insuranceDays,
					insud_id,
					insud_certificateNumber
				)
				SELECT
					tit.comp_id,
					tit.bra_id,
					@ct_transaction,
					tit.item_id,
					@qtycancel * -1,
					tit.it_priceWithOutOthers,
					tit.it_price,
					tit.curr_id,
					tit.it_exchangeToBranchCurrency,
					tit.it_priceOfCost,
					tit.it_priceOfCostPP,
					tit.it_priceOfCostLastPurchase,
					tit.it_priceBOfCost,
					tit.it_priceBOfCostPP,
					tit.it_priceBOfCostLastPurchase,
					tit.it_OriginalPrice,
					tit.it_OriginalPriceCurrency,
					tit.it_exchangeToOriginalPriceCurrency,
					@stor_id,									--tit.stor_id,
					@dec_StorePrevious2,						--tit.it_storePrevious,
					tit.prli_id,
					tit.byor_id,
					tit.it_isProduction,
					tit.it_isAssociation,
					tit.it_isAssociationGroup,
					GETDATE(),
					tit.it_packingInvoicePend,
					tit.it_order,
					tit.so_id,
					tit.it_guarantee,
					tit.it_itemDiscountTotal,
					tit.it_totalDiscountTotal,
					tit.it_CreditInt,
					tit.it_CreditIntPlus,
					tit.puco_id,
					tit.it_poh_bra_id,
					tit.it_poh_id,
					tit.it_soh_id,
					tit.it_sod_id,
					tit.rmah_id,
					tit.rmad_id,
					tit.it_qty_rma,
					tit.it_tis_id_aux,
					tit.it_note1,
					tit.it_note2,
					tit.it_packingInvoiceSelected,
					tit.it_cancelled,
					tit.it_priceB,
					tit.it_isMade,
					tit.it_item_id_origin,
					tit.tmp_tis_id,
					tit.it_packingInvoicePendOriginal,
					tit.it_packingInvoiceSelectedGuid,
					tit.it_transaction_original,
					tit.it_transaction_NoStockDiscount,
					tit.it_SalesCurrId4exchangeToBranchCurrency,
					tit.it_AllUseTag1,
					tit.it_AllUseTag2,
					tit.it_AllUseTag3,
					tit.it_AllUseTag4,
					tit.it_Discount1,
					tit.it_Discount2,
					tit.it_Discount3,
					tit.it_Discount4,
					tit.coslis_id,
					tit.coslis_idB,
					tit.supp_id,
					tit.camp_id,
					tit.it_transaction_originalEW,
					tit.it_IsInternalTransfer,
					tit.it_isRMASupplierCreditNote,
					tit.it_IsFastStockAdjustment,
					tit.it_IsStockAdjustment,
					tit.it_IsStockControl,
					tit.sdlmt_id,
					tit.sreas_id,
					tit.it_loanNumberOfPays,
					151,						--sitt_id Anulación de Articulos en Recepción de Transferencia entre Sucursales ( Paso 2 )
					tit.it_deliveryDate,
					tit.itstkpld_id,
					tit.it_NoStockCheck,
					tit.it_transaction_originaLDIV,
					tit.it_surcharge1,
					tit.it_surcharge2,
					tit.it_surcharge3,
					tit.it_surcharge4,
					tit.stor_id_related4BranchTransfer,
					tit.it_transaction_related4BranchTransfer,
					tit.it_pod_id,
					tit.pubh_id,
					tit.it_EWAddress,
					tit.it_insuranceDays,
					tit.insud_id,
					tit.insud_certificateNumber

					FROM tbItemTransactions							tit		WITH(NOLOCK)

					WHERE	tit.comp_id			= @comp_id			AND
							tit.ct_transaction	= @ct_transaction	AND
							tit.it_transaction	= @it_transaction	--AND
							--tit.item_id			= @item_id

				-- ---------------------------------------------------------------------------------
				-- ---------------------------------------------------------------------------------
					UPDATE	tbItemStorage
						SET		itst_cant	= (itst_cant + @qtycancel)
						WHERE	comp_id		= @comp_id
						AND		stor_id		= @stor_id
						AND		item_id		= @item_id
				-- ---------------------------------------------------------------------------------




				---------------------------------------------------------------------------------
				-- Si se anularon todos los items se actualiza el ispending en False para el CT
				---------------------------------------------------------------------------------
				IF NOT EXISTS (SELECT
								tit.it_transaction
								FROM tbItemTransactions tit
								WHERE tit.comp_id			= @comp_id			AND
									  tit.ct_transaction	= @ct_transaction	AND
									  tit.sitt_id			NOT IN (150,151)
								)

						BEGIN
							UPDATE tbCommercialTransactions
							SET		ct_Pending = 'False'

							WHERE	comp_id			= @comp_id			AND
									ct_transaction	= @ct_transaction
						END


				---------------------------------------------------------------------------------






			END TRY
		BEGIN CATCH
			--ROLLBACK TRANSACTION
			SET @ret_ErrorCode			= -1
			SET @ret_ErrorDescription	= ''
		END CATCH

END
GO

CREATE PROCEDURE [dbo].[spItemTransactions_GenerateInAndOutStockMovementsFromRemitosFromStoreOriginToStoreDestiny]
(
	@comp_id			INT,
	@bra_id				INT,
	@user_id			INT,
	@prof_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@ct_transaction		INT,
	@stor_id_Origin		INT,
	@stor_id_Destiny	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@user_id			INT,
				@prof_id			INT,
				@guid				UNIQUEIDENTIFIER,
				@ct_transaction		INT,
				@stor_id_Origin		INT,
				@stor_id_Destiny	INT
			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@user_id			= 119,
				@prof_id			= 1,
				@guid				= 'c1ea7685-c874-479a-a723-5badba9e2af0',
				@ct_transaction		= 1111,
				@stor_id_Origin		= 1,
				@stor_id_Destiny	= 1
		*/
		-- -------------------------------------------------------------------------------
		--#03082018STL

		-- -------------------------------------------------------------------------------------------
		--ACÁ RECUPERO LOS ARTÍCULOS SELECCIONADOS DESDE LOS REMITOS
		-- -------------------------------------------------------------------------------------------
		DECLARE @tblItemTrans_ArticulosSeleccionadosEnRemitos TABLE (
																		comp_id			INT,
																		ct_transaction	INT,
																		it_transaction	INT,
																		item_id			INT,
																		it_qty			INT,
																		stor_id			INT
																	)
		INSERT INTO @tblItemTrans_ArticulosSeleccionadosEnRemitos
		(
			comp_id,
			ct_transaction,
			it_transaction,
			item_id,
			it_qty,
			stor_id
		)
		SELECT
			tit.comp_id,
			tit.ct_transaction,
			tit.it_transaction,
			tit.item_id,
			tit.it_qty,
			tit.stor_id
		FROM tbItemTransactions tit
		WHERE	tit.comp_id							= @comp_id	AND
				tit.it_packingInvoiceSelected		= 'True'	AND
				tit.it_packingInvoiceSelectedGuid	= @guid		AND
				tit.stor_id							= @stor_id_Origin

		-- -------------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- MOVIMIENTOS DE SALIDA
		-- UTILIZA EL SITT_ID = 153 // Página: 72 Botón: Remitos - Salida de Depósito de Origen // IMDD
		-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		INSERT INTO tbItemTransactions
		(
			comp_id,						bra_id,									ct_transaction,														  item_id,
			it_qty,							it_priceWithOutOthers,					it_price,						curr_id,							  it_exchangeToBranchCurrency,
			it_priceOfCost,					it_priceOfCostPP,						it_priceOfCostLastPurchase,		it_priceBOfCost,					  it_priceBOfCostPP,
			it_priceBOfCostLastPurchase,	it_OriginalPrice,						it_OriginalPriceCurrency,		it_exchangeToOriginalPriceCurrency,	  stor_id,
			it_storePrevious,				prli_id,								byor_id,						it_isProduction,					  it_isAssociation,
			it_isAssociationGroup,			it_cd,									it_packingInvoicePend,			it_order,							  so_id,
			it_guarantee,					it_itemDiscountTotal,					it_totalDiscountTotal,			it_CreditInt,						  it_CreditIntPlus,
			puco_id,						it_poh_bra_id,							it_poh_id,						it_soh_id,							  it_sod_id,
			rmah_id,						rmad_id,								it_qty_rma,						it_tis_id_aux,						  it_note1,
			it_note2,						it_packingInvoiceSelected,				it_cancelled,					it_priceB,							  it_isMade,
			it_item_id_origin,				tmp_tis_id,								it_packingInvoicePendOriginal,	it_packingInvoiceSelectedGuid,		  it_transaction_original,
			it_transaction_NoStockDiscount,	it_SalesCurrId4exchangeToBranchCurrency,it_AllUseTag1,					it_AllUseTag2,						  it_AllUseTag3,
			it_AllUseTag4,					it_Discount1,							it_Discount2,					it_Discount3,						  it_Discount4,
			coslis_id,						coslis_idB,								supp_id,						camp_id,							  it_transaction_originalEW,
			it_IsInternalTransfer,			it_isRMASupplierCreditNote,				it_IsFastStockAdjustment,		it_IsStockAdjustment,				  it_IsStockControl,
			sdlmt_id,						sreas_id,								it_loanNumberOfPays,			sitt_id,							  it_deliveryDate,
			itstkpld_id,					it_NoStockCheck,						it_transaction_originaLDIV,		it_surcharge1,						  it_surcharge2,
			it_surcharge3,					it_surcharge4,							stor_id_related4BranchTransfer,	it_transaction_related4BranchTransfer,it_pod_id,
			pubh_id,						it_EWAddress,							it_insuranceDays,				insud_id,							  insud_certificateNumber,
			it_priceOfprli_id4CreditInCash,	it_isPCConfig,							it_isBlocked4Delivery,			it_isFromPCConfigCTRLId,			  item_idfromPreInvoice,
			it_MLCost,						it_isCompensed,							ws_price,						ws_curr_Id,							  mlo_id,
			it_deliveryCharge,				it_MPCost,								it_MECost,						it_packingInvoicePendCancell_user_id, it_packingInvoicePendCancell_cd,
			it_disablePrintInEmmition
		)
		SELECT
			tit.comp_id,						tit.bra_id,									@ct_transaction,															  tit.item_id,
			tit.it_qty * -1,					tit.it_priceWithOutOthers,					tit.it_price,						tit.curr_id,							  tit.it_exchangeToBranchCurrency,
			tit.it_priceOfCost,					tit.it_priceOfCostPP,						tit.it_priceOfCostLastPurchase,		tit.it_priceBOfCost,					  tit.it_priceBOfCostPP,
			tit.it_priceBOfCostLastPurchase,	tit.it_OriginalPrice,						tit.it_OriginalPriceCurrency,		tit.it_exchangeToOriginalPriceCurrency,	  @stor_id_Origin,
			ISNULL(tis.itst_cant,0),			tit.prli_id,								tit.byor_id,						tit.it_isProduction,					  tit.it_isAssociation,
			tit.it_isAssociationGroup,			tit.it_cd,									'False',							tit.it_order,							  tit.so_id,
			tit.it_guarantee,					tit.it_itemDiscountTotal,					tit.it_totalDiscountTotal,			tit.it_CreditInt,						  tit.it_CreditIntPlus,
			tit.puco_id,						tit.it_poh_bra_id,							tit.it_poh_id,						tit.it_soh_id,							  tit.it_sod_id,
			tit.rmah_id,						tit.rmad_id,								tit.it_qty_rma,						tit.it_tis_id_aux,						  tit.it_note1,
			tit.it_note2,						'False',									'False',							tit.it_priceB,							  tit.it_isMade,
			tit.it_item_id_origin,				tit.tmp_tis_id,								tit.it_packingInvoicePendOriginal,	tit.it_packingInvoiceSelectedGuid,		  tit.it_transaction_original,
			tit.it_transaction_NoStockDiscount,	tit.it_SalesCurrId4exchangeToBranchCurrency,tit.it_AllUseTag1,					tit.it_AllUseTag2,						  tit.it_AllUseTag3,
			tit.it_AllUseTag4,					tit.it_Discount1,							tit.it_Discount2,					tit.it_Discount3,						  tit.it_Discount4,
			tit.coslis_id,						tit.coslis_idB,								tit.supp_id,						tit.camp_id,							  tit.it_transaction_originalEW,
			tit.it_IsInternalTransfer,			tit.it_isRMASupplierCreditNote,				tit.it_IsFastStockAdjustment,		tit.it_IsStockAdjustment,				  tit.it_IsStockControl,
			tit.sdlmt_id,						tit.sreas_id,								tit.it_loanNumberOfPays,			153,									  tit.it_deliveryDate,
			tit.itstkpld_id,					tit.it_NoStockCheck,						tit.it_transaction_originaLDIV,		tit.it_surcharge1,						  tit.it_surcharge2,
			tit.it_surcharge3,					tit.it_surcharge4,							tit.stor_id_related4BranchTransfer,	tit.it_transaction_related4BranchTransfer,tit.it_pod_id,
			tit.pubh_id,						tit.it_EWAddress,							tit.it_insuranceDays,				tit.insud_id,							  tit.insud_certificateNumber,
			tit.it_priceOfprli_id4CreditInCash,	tit.it_isPCConfig,							tit.it_isBlocked4Delivery,			tit.it_isFromPCConfigCTRLId,			  tit.item_idfromPreInvoice,
			tit.it_MLCost,						tit.it_isCompensed,							tit.ws_price,						tit.ws_curr_Id,							  tit.mlo_id,
			tit.it_deliveryCharge,				tit.it_MPCost,								tit.it_MECost,						tit.it_packingInvoicePendCancell_user_id, tit.it_packingInvoicePendCancell_cd,
			tit.it_disablePrintInEmmition
		FROM tbItemTransactions tit				WITH (NOLOCK)
			INNER JOIN @tblItemTrans_ArticulosSeleccionadosEnRemitos	tmp
			ON	tmp.comp_id			= tit.comp_id						AND
				tmp.ct_transaction	= tit.ct_transaction				AND
				tmp.it_transaction	= tit.it_transaction				AND
				tmp.item_id			= tit.item_id
			LEFT JOIN tbItemStorage										tis		WITH (NOLOCK)
			ON	tis.comp_id = tit.comp_id								AND
				tis.stor_id = tit.stor_id								AND
				tis.item_id = tit.item_id

		-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- MOVIMIENTOS DE ENTRADA
		-- UTILIZA EL SITT_ID = 154 // Página: 72 Botón: Remitos - Ingreso en Depósito de Destino // EMDO
		-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		INSERT INTO tbItemTransactions
		(
			comp_id,						bra_id,									ct_transaction,														  item_id,
			it_qty,							it_priceWithOutOthers,					it_price,						curr_id,							  it_exchangeToBranchCurrency,
			it_priceOfCost,					it_priceOfCostPP,						it_priceOfCostLastPurchase,		it_priceBOfCost,					  it_priceBOfCostPP,
			it_priceBOfCostLastPurchase,	it_OriginalPrice,						it_OriginalPriceCurrency,		it_exchangeToOriginalPriceCurrency,	  stor_id,
			it_storePrevious,				prli_id,								byor_id,						it_isProduction,					  it_isAssociation,
			it_isAssociationGroup,			it_cd,									it_packingInvoicePend,			it_order,							  so_id,
			it_guarantee,					it_itemDiscountTotal,					it_totalDiscountTotal,			it_CreditInt,						  it_CreditIntPlus,
			puco_id,						it_poh_bra_id,							it_poh_id,						it_soh_id,							  it_sod_id,
			rmah_id,						rmad_id,								it_qty_rma,						it_tis_id_aux,						  it_note1,
			it_note2,						it_packingInvoiceSelected,				it_cancelled,					it_priceB,							  it_isMade,
			it_item_id_origin,				tmp_tis_id,								it_packingInvoicePendOriginal,	it_packingInvoiceSelectedGuid,		  it_transaction_original,
			it_transaction_NoStockDiscount,	it_SalesCurrId4exchangeToBranchCurrency,it_AllUseTag1,					it_AllUseTag2,						  it_AllUseTag3,
			it_AllUseTag4,					it_Discount1,							it_Discount2,					it_Discount3,						  it_Discount4,
			coslis_id,						coslis_idB,								supp_id,						camp_id,							  it_transaction_originalEW,
			it_IsInternalTransfer,			it_isRMASupplierCreditNote,				it_IsFastStockAdjustment,		it_IsStockAdjustment,				  it_IsStockControl,
			sdlmt_id,						sreas_id,								it_loanNumberOfPays,			sitt_id,							  it_deliveryDate,
			itstkpld_id,					it_NoStockCheck,						it_transaction_originaLDIV,		it_surcharge1,						  it_surcharge2,
			it_surcharge3,					it_surcharge4,							stor_id_related4BranchTransfer,	it_transaction_related4BranchTransfer,it_pod_id,
			pubh_id,						it_EWAddress,							it_insuranceDays,				insud_id,							  insud_certificateNumber,
			it_priceOfprli_id4CreditInCash,	it_isPCConfig,							it_isBlocked4Delivery,			it_isFromPCConfigCTRLId,			  item_idfromPreInvoice,
			it_MLCost,						it_isCompensed,							ws_price,						ws_curr_Id,							  mlo_id,
			it_deliveryCharge,				it_MPCost,								it_MECost,						it_packingInvoicePendCancell_user_id, it_packingInvoicePendCancell_cd,
			it_disablePrintInEmmition
		)
		SELECT
			tit.comp_id,						tit.bra_id,									@ct_transaction,															  tit.item_id,
			tit.it_qty,							tit.it_priceWithOutOthers,					tit.it_price,						tit.curr_id,							  tit.it_exchangeToBranchCurrency,
			tit.it_priceOfCost,					tit.it_priceOfCostPP,						tit.it_priceOfCostLastPurchase,		tit.it_priceBOfCost,					  tit.it_priceBOfCostPP,
			tit.it_priceBOfCostLastPurchase,	tit.it_OriginalPrice,						tit.it_OriginalPriceCurrency,		tit.it_exchangeToOriginalPriceCurrency,	  @stor_id_Destiny,
			ISNULL(tis.itst_cant,0),			tit.prli_id,								tit.byor_id,						tit.it_isProduction,					  tit.it_isAssociation,
			tit.it_isAssociationGroup,			tit.it_cd,									'False',							tit.it_order,							  tit.so_id,
			tit.it_guarantee,					tit.it_itemDiscountTotal,					tit.it_totalDiscountTotal,			tit.it_CreditInt,						  tit.it_CreditIntPlus,
			tit.puco_id,						tit.it_poh_bra_id,							tit.it_poh_id,						tit.it_soh_id,							  tit.it_sod_id,
			tit.rmah_id,						tit.rmad_id,								tit.it_qty_rma,						tit.it_tis_id_aux,						  tit.it_note1,
			tit.it_note2,						'False',									'False',							tit.it_priceB,							  tit.it_isMade,
			tit.it_item_id_origin,				tit.tmp_tis_id,								tit.it_packingInvoicePendOriginal,	tit.it_packingInvoiceSelectedGuid,		  tit.it_transaction_original,
			tit.it_transaction_NoStockDiscount,	tit.it_SalesCurrId4exchangeToBranchCurrency,tit.it_AllUseTag1,					tit.it_AllUseTag2,						  tit.it_AllUseTag3,
			tit.it_AllUseTag4,					tit.it_Discount1,							tit.it_Discount2,					tit.it_Discount3,						  tit.it_Discount4,
			tit.coslis_id,						tit.coslis_idB,								tit.supp_id,						tit.camp_id,							  tit.it_transaction_originalEW,
			tit.it_IsInternalTransfer,			tit.it_isRMASupplierCreditNote,				tit.it_IsFastStockAdjustment,		tit.it_IsStockAdjustment,				  tit.it_IsStockControl,
			tit.sdlmt_id,						tit.sreas_id,								tit.it_loanNumberOfPays,			154,									  tit.it_deliveryDate,
			tit.itstkpld_id,					tit.it_NoStockCheck,						tit.it_transaction_originaLDIV,		tit.it_surcharge1,						  tit.it_surcharge2,
			tit.it_surcharge3,					tit.it_surcharge4,							tit.stor_id_related4BranchTransfer,	tit.it_transaction_related4BranchTransfer,tit.it_pod_id,
			tit.pubh_id,						tit.it_EWAddress,							tit.it_insuranceDays,				tit.insud_id,							  tit.insud_certificateNumber,
			tit.it_priceOfprli_id4CreditInCash,	tit.it_isPCConfig,							tit.it_isBlocked4Delivery,			tit.it_isFromPCConfigCTRLId,			  tit.item_idfromPreInvoice,
			tit.it_MLCost,						tit.it_isCompensed,							tit.ws_price,						tit.ws_curr_Id,							  tit.mlo_id,
			tit.it_deliveryCharge,				tit.it_MPCost,								tit.it_MECost,						tit.it_packingInvoicePendCancell_user_id, tit.it_packingInvoicePendCancell_cd,
			tit.it_disablePrintInEmmition
		FROM tbItemTransactions tit							WITH (NOLOCK)
			INNER JOIN @tblItemTrans_ArticulosSeleccionadosEnRemitos	tmp
			ON	tmp.comp_id			= tit.comp_id						AND
				tmp.ct_transaction	= tit.ct_transaction				AND
				tmp.it_transaction	= tit.it_transaction				AND
				tmp.item_id			= tit.item_id
			LEFT JOIN tbItemStorage										tis			WITH (NOLOCK)
			ON	tis.comp_id			= tit.comp_id						AND
				tis.stor_id			= @stor_id_Destiny					AND
				tis.item_id			= tit.item_id
		-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


		-- INSERT DE LOS REGISTROS EN LA ItemStorage que NO existan según depósito Origen y Destino
		-- -----------------------------------------------------------------
		-- ORIGEN
		-- -----------------------------------------------------------------
		INSERT INTO tbItemStorage
		(
			comp_id,
			stor_id,
			item_id,
			itst_cant,
			itst_cd,
			itst_PickingLocation,
			itst_StorageLocation
		)
		SELECT DISTINCT
			tmp.comp_id,
			@stor_id_Origin,
			tmp.item_id,
			0,
			NULL,
			'',
			''
			FROM @tblItemTrans_ArticulosSeleccionadosEnRemitos	tmp
			LEFT JOIN tbItemStorage								tis		WITH (NOLOCK)
				ON	tis.comp_id			= tmp.comp_id				AND
					tis.stor_id			= @stor_id_Origin			AND
					tis.item_id			= tmp.item_id
			WHERE tis.comp_id IS NULL
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------
		-- DESTINO
		-- -----------------------------------------------------------------
		INSERT INTO tbItemStorage
		(
			comp_id,
			stor_id,
			item_id,
			itst_cant,
			itst_cd,
			itst_PickingLocation,
			itst_StorageLocation
		)
		SELECT DISTINCT
			tmp.comp_id,
			@stor_id_Destiny,
			tmp.item_id,
			0,
			NULL,
			'',
			''
			FROM @tblItemTrans_ArticulosSeleccionadosEnRemitos	tmp
			LEFT JOIN tbItemStorage								tis		WITH (NOLOCK)
			ON	tis.comp_id			= tmp.comp_id				AND
				tis.stor_id			= @stor_id_Destiny			AND
				tis.item_id			= tmp.item_id
			WHERE tis.comp_id IS NULL
		-- -----------------------------------------------------------------

		--UPDATE de las cantidades
		DECLARE
			@curStor_id					AS INT,
			@curItem_Id					AS INT,
			@curtis_qty					AS DECIMAL(19,6),
			@cur_itst_cant				AS DECIMAL(19,6),
			@cur_tis_PickingLocation	AS nVARCHAR(MAX),
			@cur_tis_StorageLocation	AS NVARCHAR(MAX)--,
			--@curTis_id					AS INT,
			--@curIt_Transaction			AS INT

		DECLARE  curUpdateItemStorage CURSOR LOCAL  FAST_FORWARD FOR
			--ACA VA EL SELECT
			SELECT
				tmp.stor_id,
				tmp.item_id,
				tmp.it_qty,
				tmp.it_qty,
				'',
				''
			FROM @tblItemTrans_ArticulosSeleccionadosEnRemitos	tmp
			--WHERE it_transaction IS NULL

		OPEN  curUpdateItemStorage
			FETCH NEXT FROM curUpdateItemStorage
			INTO	@curStor_id,
					@curItem_Id,
					@curtis_qty,
					@cur_itst_cant,
					@cur_tis_PickingLocation,
					@cur_tis_StorageLocation--,
					--@curTis_id,
					--@curIt_Transaction

		WHILE @@FETCH_STATUS = 0
			BEGIN
				--ACA VAN LOS UPDATES

				-- -----------------------------------------------------------------------------------------------
				-- SALIDA
				-- -----------------------------------------------------------------------------------------------
				UPDATE	dbo.tbItemStorage		WITH (ROWLOCK)
				SET		dbo.tbItemStorage.itst_cant				= its.itst_cant - @curtis_qty,
						dbo.tbItemStorage.itst_cd				= GETDATE(),
						dbo.tbItemStorage.itst_PickingLocation	= @cur_tis_PickingLocation,
						dbo.tbItemStorage.itst_StorageLocation	= @cur_tis_StorageLocation
					FROM	dbo.tbItemStorage							its
					WHERE	its.comp_id = @comp_id						AND
							its.item_id = @curItem_Id					AND
							its.stor_id = @stor_id_Origin
				-- -----------------------------------------------------------------------------------------------

				-- -----------------------------------------------------------------------------------------------
				-- ENTRADA
				-- -----------------------------------------------------------------------------------------------
				UPDATE	dbo.tbItemStorage		WITH (ROWLOCK)
				SET		dbo.tbItemStorage.itst_cant				= its.itst_cant + @curtis_qty,
						dbo.tbItemStorage.itst_cd				= GETDATE(),
						dbo.tbItemStorage.itst_PickingLocation	= @cur_tis_PickingLocation,
						dbo.tbItemStorage.itst_StorageLocation	= @cur_tis_StorageLocation
					FROM	dbo.tbItemStorage							its
					WHERE	its.comp_id = @comp_id						AND
							its.item_id = @curItem_Id					AND
							its.stor_id = @stor_id_Destiny
				-- -----------------------------------------------------------------------------------------------


				FETCH NEXT FROM curUpdateItemStorage
					INTO	@curStor_id,
							@curItem_Id,
							@curtis_qty,
							@cur_itst_cant,
							@cur_tis_PickingLocation,
							@cur_tis_StorageLocation--,
							--@curTis_id,
							--@curIt_Transaction
			END
		CLOSE curUpdateItemStorage
		DEALLOCATE curUpdateItemStorage

	END

GO







-- Updated MOS  04-2011
CREATE PROCEDURE [dbo].[spItemTransactions_GetCostsOfBranchCostList]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@item_id	INT,
	@cust_id	INT
)
AS

BEGIN



	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
		/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@item_id	INT,
			@cust_id	INT
		SELECT
			@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@item_id	=316,
			@cust_id	=8
		*/
-- ------------------------------------------------------



	DECLARE @bitCostPlusTax AS BIT
	SELECT @bitCostPlusTax	= IsNull(tb.bra_SaleOrderPricePlusTax,'False')
		FROM tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id



	SELECT		TOP 1
				CASE WHEN tb.bra_SaleOrderShowCost = 'false' THEN ''
					ELSE  CONVERT(VARCHAR, CONVERT(DECIMAL(19,4), ticl.coslis_price    + (
																							CASE
																								WHEN @bitCostPlusTax = 'True' THEN ticl.coslis_price * IsNull(ttn.tax_percentage,0) / 100
																								ELSE 0
																							END
																						  )
												   )) + ' / ' +
						  CONVERT(VARCHAR ,convert(decimal(19,4), ticl.coslis_price_aw + (
																							CASE
																								WHEN @bitCostPlusTax = 'True' THEN ticl.coslis_price_aw * IsNull(ttn.tax_percentage,0) / 100
																								ELSE 0
																							END
						  																 )
												   )) + ' '   + tc2.curr_symbol +
																							CASE
																								WHEN @bitCostPlusTax = 'True' THEN 'c/IVA'
																								ELSE ''
																							END


				END  [desc],
				CASE WHEN tb.bra_SaleOrderShowCost = 'false' THEN ''
					ELSE  CONVERT(VARCHAR, CONVERT(DECIMAL(19,4), ticl.coslis_price    + (
																							CASE
																								WHEN @bitCostPlusTax = 'True' THEN ticl.coslis_price * IsNull(ttn.tax_percentage,0) / 100
																								ELSE 0
																							END
																						  )
												   ))
				END  [descCost]		,
				CASE WHEN tb.bra_SaleOrderShowCost = 'false' THEN ''
					ELSE
						  CONVERT(VARCHAR ,convert(decimal(19,4), ticl.coslis_price_aw + (
																							CASE
																								WHEN @bitCostPlusTax = 'True' THEN ticl.coslis_price_aw * IsNull(ttn.tax_percentage,0) / 100
																								ELSE 0
																							END
						  																 )
												   )) + ' '   + tc2.curr_symbol
 +
																							CASE
																								WHEN @bitCostPlusTax = 'True' THEN 'c/IVA'
																								ELSE ''
																							END


				END  [descCostPPP]




				--tbItemCostList
		FROM	vwItemCostList ticl						WITH (NOLOCK)
				INNER JOIN tbbranch  tb					WITH (NOLOCK)
					ON		tb.comp_id	= @comp_id
						AND tb.bra_id	= @bra_id
				INNER JOIN tbsysCurrency tc2			WITH (NOLOCK)
					ON tc2.curr_id = ticl.curr_id
				left JOIN vwItemTaxesOnlyOneIvaTax	vit	WITH (NOLOCK)
					ON		vit.comp_id = ticl.comp_id
						AND vit.item_id = ticl.item_id
				LEFT JOIN tbTaxName ttn					WITH (NOLOCK)
					ON		ttn.comp_id = vit.comp_id
						AND ttn.tax_id	= vit.tax_id

		WHERE	ticl.comp_id	= @comp_id
			AND ticl.coslis_id	= tb.coslis_id
			AND	ticl.item_id	= @item_id


END
GO



