CREATE PROCEDURE [dbo].[spItemTransactions_getData]
(
	@comp_id					int,
	@bra_id						int,
	@ct_transaction				INT,
	@intItemTransactionFilter1	INT,
	@intItemTransactionFilter2	INT
)
as

BEGIN

	set nocount on



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 700
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
		/*
		  DECLARE
  			@comp_id				int,
  			@bra_id					int,
  			@ct_transaction			INT,
  			@intItemTransactionFilter1	INT,
			@intItemTransactionFilter2	INT
		  SELECT
  			@comp_id				=1,
  			@bra_id					=1,
  			@ct_transaction			=28319,
  			@intItemTransactionFilter1	= 0,
			@intItemTransactionFilter2	= 0
		*/
		-- --------------------------------------------------------------------------


		-- -------------------------------------------
		-- Obtengo Talle y Color
		-- -------------------------------------------
--		DECLARE @strColor	AS NVARCHAR(50)
--		DECLARE @strSize	AS NVARCHAR(200)
--		SELECT	TOP 1
--				@strColor = IsNull(tc.color_code,''),
--				@strSize  = IsNull(ts.Size_code,'')
--			FROM tbItemSizeColorRelation tiscr
--			INNER JOIN tbColor tc
--				ON		tc.comp_id	= tiscr.comp_id
--					AND tc.color_id = tiscr.color_id
--			INNER JOIN tbSize ts
--				ON		ts.comp_id	= tiscr.comp_id
--					and ts.Size_id	= tiscr.size_id
		-- -------------------------------------------


		DECLARE @strDelyveryAddress AS NVARCHAR(MAX)
		SET		@strDelyveryAddress = ''
		IF	@intItemTransactionFilter1 IS NOT NULL AND
			@intItemTransactionFilter1 > 0 AND
			@intItemTransactionFilter2 IS NOT NULL AND
			@intItemTransactionFilter2 > 0
			BEGIN
			--select 1 /  0
				SELECT @strDelyveryAddress = @strDelyveryAddress + dbo.fnStrAllTrim(ISNULL(tit.it_EWAddress,''))
					FROM tbItemTransactions tit			WITH (NOLOCK)
					WHERE tit.comp_id	= @comp_id AND
						 (
							tit.it_transaction = @intItemTransactionFilter1 OR
							tit.it_transaction = @intItemTransactionFilter2
						 )
				SET @strDelyveryAddress =  dbo.fnStrAllTrim(@strDelyveryAddress)
			END


	-- ----------------------------------------------------------------------------------------------------------------------------------------------------
	-- Pongo en una Temporal para hacer JOIN los campos de Talle y Color que se usaran para resumir renglones por talle si es que el documento lo requiere.
	-- ----------------------------------------------------------------------------------------------------------------------------------------------------
	SELECT
				ti.item_id																							AS sizeColor_item_id,
				ti.item_desc																						AS sizeColor_desc,
				tit.it_price																						AS sizeColor_it_price,
				--STRING_AGG (dbo.fnStrAllTrim(tc.color_code) + '-' +
				--			dbo.fnStrAllTrim(ts.Size_code) + ':' +
				--			CONVERT(VARCHAR(15),convert(int,tit.it_qty)) + ' ' , CHAR(15))				AS sizeColor_shortDesc,


				--STRING_AGG esta GENIAL pero solo se lo banca a partir de SQL 2017
				--STRING_AGG ( ';' + dbo.fnStrAllTrim(CONVERT(CHAR(10),tit.it_transaction)) + ';' , CHAR(8000))		AS sizeColor_ITTransaction,
				SUM(tit.it_qty)																						AS sizeColor_QTY,

				-- Se usa STUFF... emulando STRING_AGG.  Cuando ya no quede nadie con sql < 2017 se puede migrar ! ! !
				STUFF((
						SELECT N' ;;' + dbo.fnStrAllTrim(CONVERT(CHAR(10),tit2.it_transaction)) + ';'
							FROM tbItemTransactions				tit2	WITH (NOLOCK)
							INNER JOIN tbItemSizeColorRelation	tiscr2	WITH (NOLOCK)
								ON	tiscr2.comp_id		= tit2.comp_id	AND
									tiscr2.item_id_child= tit2.item_id
							 WHERE	tit2.comp_id		= @comp_id			AND
									tit2.ct_transaction	= @ct_transaction	AND
									tiscr2.item_id		= ti.item_id		AND
									tit2.it_price		= tit.it_price
							 FOR XML PATH,TYPE).value(N'.','nvarchar(max)'),1,2,'')									AS sizeColor_ITTransaction	,
				STUFF((
						SELECT N' ,' + dbo.fnStrAllTrim(tc2.color_code) + '-' +
									  dbo.fnStrAllTrim(ts2.Size_code) + ':' +
									  CONVERT(VARCHAR(15),convert(int,tit2.it_qty))
							FROM tbItemTransactions				tit2	WITH (NOLOCK)
							INNER JOIN tbItemSizeColorRelation	tiscr2	WITH (NOLOCK)
								ON	tiscr2.comp_id		= tit2.comp_id	AND
									tiscr2.item_id_child= tit2.item_id
							INNER JOIN tbColor					tc2		WITH (NOLOCK)
								ON	tc2.comp_id			= tiscr2.comp_id AND
									tc2.color_id		= tiscr2.color_id
							INNER JOIN tbSize					ts2		WITH (NOLOCK)
								ON	ts2.comp_id			= tiscr2.comp_id AND
									ts2.Size_id			= tiscr2.size_id
							 WHERE	tit2.comp_id		= @comp_id			AND
									tit2.ct_transaction	= @ct_transaction	AND
									tiscr2.item_id		= ti.item_id		AND
									tit2.it_price		= tit.it_price
							 FOR XML PATH,TYPE).value(N'.','nvarchar(max)'),1,2,'')									AS sizeColor_shortDesc

		INTO #tbItemTransactionsTMP
		FROM tbItemTransactions				tit		WITH (NOLOCK)
		INNER JOIN tbItemSizeColorRelation	tiscr	WITH (NOLOCK)
			ON	tiscr.comp_id		= tit.comp_id	AND
				tiscr.item_id_child = tit.item_id
		INNER JOIN tbitem					ti		WITH (NOLOCK)
			ON	ti.comp_id			= tiscr.comp_id AND
				ti.item_id			= tiscr.item_id
		INNER JOIN tbColor					tc		WITH (NOLOCK)
			ON	tc.comp_id			= tiscr.comp_id AND
				tc.color_id			= tiscr.color_id
		INNER JOIN tbSize					ts		WITH (NOLOCK)
			ON	ts.comp_id			= tiscr.comp_id AND
				ts.Size_id			= tiscr.size_id

		WHERE	tit.comp_id			= @comp_id AND
				tit.ct_transaction	= @ct_transaction
		GROUP BY	ti.item_id,
					ti.item_desc,
					tit.it_price

	--==
	--SELECT * FROM #tbItemTransactionsTMP
	-- ----------------------------------------------------------------------------------------------------------------------------------------------------


		--	Reemplaza al Bra_id por el Bra_+Id original de la transaccion !
		SELECT @bra_id = tct.bra_id
			FROM tbCommercialTransactions tct WITH (NOLOCK)
			WHERE	tct.comp_id			= @comp_id AND
					tct.ct_transaction	= @ct_transaction


		SELECT
				IT.comp_id,
  				IT.bra_id,
  				IT.ct_transaction,
  				IT.it_transaction,
  				IT.item_id,
  				CASE
  					WHEN	tidc.id4c_code IS NOT NULL				THEN tidc.id4c_code
  					WHEN	item.item_code IS NOT NULL				THEN item.item_code
  					WHEN	ITEM4PreInvoice.item_code IS NOT NULL	THEN ITEM4PreInvoice.item_code
  					WHEN	tiOrigin.item_code IS NOT NULL	AND		-- Si es un COMBO y el documento dice que se imprima...
  							tdf.df_SaleOrder_Emition_PrintComboCode = 'True'
  																	THEN tiOrigin.item_code
  					ELSE												 ''
  				END															[item_code],
  				isnull(tidc.id4c_desc, isnull(ITD.itm_desc,item.item_desc)) [item_desc]  /* MOS  12-09   para que salgan las descripciones modificadas en el pedido*/,
  				IT.it_qty,
  				IT.it_price,
  				IT.it_OriginalPrice,
  				IT.it_OriginalPriceCurrency,
  				IT.it_priceOfCost,
  				IT.it_priceOfCostPP,
  				IT.it_priceBOfCost,
  				IT.it_priceBOfCostPP,
  				ISNULL(it.it_CreditInt,0)				[it_CreditInt],
  				ISNULL(it.it_CreditIntPlus,0)			[it_CreditIntPlus],
  				--it.it_itemDiscountTotal,
  				it.it_totalDiscountTotal,
  				IT.stor_id,
  				IsNull(stor.stor_desc,'')				[stor_desc],
  				IT.it_storePrevious,
  				IT.prli_id,
  				ISNULL(prli.prli_desc,'')				[prli_desc],
  				IT.byor_id,
  				case
  					when IT.byor_id IS NULL THEN ' '
  					ELSE '*'
  				END				[IsByOrd],
  				ISNULL(tbo.byor_desc,'')				[byor_desc],
  				IT.it_cd,
  				IT.it_packingInvoicePend,
  				IT.it_order,
  				IT.so_id,
  				--IT.it_guarantee,
  				IT.it_transaction [ID] 	,
  				ITD.itm_desc,
  				ITD.itm_desc1,
  				ITD.itm_desc2,
  				isnull(ITEM.item_annotation,'')											[item_annotation],
  				IsNull(IT.it_itemDiscountTotal,0)										[it_itemDiscountTotal],
  				--IsNull(it.it_itemDiscountTotal / dbo.fnNoZDiv(it.it_price + it.it_itemDiscountTotal + it.it_totalDiscountTotal) * 100,0)
  				ISNULL(it.it_Discount1,0)												[it_itemDiscountPercentage],
  				ISNULL(it.it_Discount2,0)												[it_itemDiscountPercentage2],

  				-- FORRADA de GB de ticket 22217
  				it.it_priceWithOutOthers * ISNULL(1-(ISNULL(it.it_Discount1,0)/100),0) * ISNULL(1-(ISNULL(it.it_Discount2,0)/100),0)				[prcItemPriceWithDiscountI_II],
  				it.it_priceWithOutOthers * ISNULL(1-(ISNULL(it.it_Discount1,0)/100),0) * ISNULL(1-(ISNULL(it.it_Discount2,0)/100),0)	* it.it_qty	[prcItemTotalPriceWithDiscountI_II],
  			   (it.it_priceWithOutOthers * ISNULL(1-(ISNULL(it.it_Discount1,0)/100),0) * ISNULL(1-(ISNULL(it.it_Discount2,0)/100),0))
  				*	( 1 + (dbo.fnTaxMovements_IvaPercentageOfItemTransaction
  																	(
  																		@comp_id		,
  																		@bra_id			,
  																		@ct_transaction ,
  																		IT.it_transaction
  																	) / 100 ))																		[prcItemPriceWithDiscountI_IIPlusTax],
  			   (it.it_priceWithOutOthers * ISNULL(1-(ISNULL(it.it_Discount1,0)/100),0) * ISNULL(1-(ISNULL(it.it_Discount2,0)/100),0)	* it.it_qty)
  			    *	( 1 + (dbo.fnTaxMovements_IvaPercentageOfItemTransaction
  																	(
  																		@comp_id		,
  																		@bra_id			,
  																		@ct_transaction ,
  																		IT.it_transaction
  																	) / 100 ))																		[prcItemTotalPriceWithDiscountI_IIPlusTax],
  				-- FORRADA de GB de ticket 22217

  				ISNULL(
  				dbo.fnTaxMovements_IvaOfItemTransaction
  							(
  								@comp_id		,
  								@bra_id			,
  								@ct_transaction ,
  								IT.it_transaction
  							),0)															[it_ivaTax],	-- MOS 12-2021: en Beerman estaban tratando de RESUMIR un combo al cual x permisos le habian borrado TODAS sus partes
  				ISNULL(
  				dbo.fnTaxMovements_IvaDescriptionOfItemTransaction
  							(
  								@comp_id		,
  								@bra_id			,
  								@ct_transaction ,
  								IT.it_transaction
  							),'')															[it_ivaTaxDescription],
  				ISNULL(
  				dbo.fnTaxMovements_IvaPercentageOfItemTransaction
  							(
  								@comp_id		,
  								@bra_id			,
  								@ct_transaction ,
  								IT.it_transaction
  							)	,0)														[it_ivaTaxPercentage],
				ISNULL(
				dbo.fnTaxMovements_InternalTaxOfItemTransaction
  							(
  								@comp_id		,
  								@bra_id			,
  								@ct_transaction ,
  								IT.it_transaction
  							),0)															[it_InternalTax],
  				ISNULL(
  				dbo.fnTaxMovements_InternalTaxPercentageOfItemTransaction
  							(
  								@comp_id		,
  								@bra_id			,
  								@ct_transaction ,
  								IT.it_transaction
  							)	,0)														[it_InternalTaxPercentage],
  				dbo.fnGetImportData_Number(					@comp_id,
  															@bra_id,
  															@ct_transaction,
  															it.it_transaction)			[impData_number],
  				dbo.fnGetImportData_Custom(					@comp_id,
  															@bra_id,
  															@ct_transaction,
  															it.it_transaction)			[impData_custom],
  				dbo.fnGetImportData_From(					@comp_id,
  															@bra_id,
  															@ct_transaction,
  															it.it_transaction)			[impData_from],
  				dbo.fnGetImportData_Origin(					@comp_id,
  															@bra_id,
  															@ct_transaction,
  															it.it_transaction)			[impData_origin],
  				dbo.fnGetItemTransactionSerial(				@comp_id,
  															@bra_id,
  															@ct_transaction,
  															it.it_transaction)			[SerialNumbers],
  				ISNULL(ITEM.item_withDecimal,'False')									[item_withDecimal],
  				isnull(IT.it_qty * IT.it_price,0)										[itemTotal],
  				IT.[curr_id],
  				ISNULL(SC.curr_symbol,'')												[curr_symbol],
  				CASE
  					WHEN	it.it_OriginalPriceCurrency IS NOT NULL AND
  							it.curr_id <> it.it_OriginalPriceCurrency	THEN	'(' + dbo.fnStrAllTrim(CONVERT(VARCHAR(30),CONVERT (DECIMAL(19,2), it.it_price / dbo.fnNoZDiv (it.it_exchangeToOriginalPriceCurrency)  ))) + ' ' +	SCOr.curr_symbol + ')'
  					ELSE ''
  				END																		[priceInOriginalCurrency],
  				IsNull(it.it_note1,'')													[it_note1],
  				IsNull(it.it_note2,'')													[it_note2],
  				IsNull(IT.it_priceWithOutOthers,0)										[it_priceWithOutOthers],
  				IsNull(tc.color_code,'')												[Color],
  				IsNull(ts.Size_code,'')													[Size],
  				ISNULL(vtt.Total,0)														[it_ivaTaxGTotal],
  				ISNULL(tdf.df_UnitPriceDecimalPlaces,2)									[UnitPriceDecimalPlaces],
  				isnull(ITEM.item_upb,1)													[UPB],
  				CEILING(ISNULL(it.it_qty,0) / dbo.fnNoZDiv( IsNull(item.item_upb,1)))	[BOXES],
  				isnull(ITEM.item_upp,1)													[UPP],
  				CEILING(ISNULL(it.it_qty,0) / dbo.fnNoZDiv( IsNull(item.item_upp,1)))	[PALLETS],
  				CASE
  					when IsNull(it.it_isMade,'False') = 'True' THEN '*'
  					ELSE	''
  				END																		[isMade],
  				IsNull(tmu.mu_shortDesc,'')												[MUShortDesc],
  				tp.pres_desc															[DETAIL_Presentation],
  				ITEM.item_weight * it.it_qty											[DETAIL_Weight],


  				ISNULL(item.item_codeAlternative,'')									[DD_codeAlternative],
  				CASE
  					WHEN ISNULL(item.item_codeAlternative,'') = '' THEN item.item_code
  					ELSE												item.item_codeAlternative
  				END																		[DD_codeAlternativeOrCode],

  				ISNULL(item.item_vendorCode,'')											[DD_vendorCode],
  				CASE
  					WHEN ISNULL(item.item_vendorCode,'') = '' THEN	item.item_code
  					ELSE											item.item_vendorCode
  				END																		[item_vendorCodeOrCode],
  				CASE
  					WHEN @strDelyveryAddress <> ''								THEN    @strDelyveryAddress
  					WHEN IT.it_EWAddress IS NOT NULL AND IT.it_EWAddress <> ''	THEN	IsNull(IT.it_EWAddress,'')
  					WHEN tcf.comp_id IS NOT NULL								THEN	IsNull(tcf.custf_address,'')  + ' ' + IsNull(tcf.custf_city,'') + '(' + IsNull(tcf.custf_zip,'') + ')'
					ELSE																IsNull(tcl.cust_address,'')   + ' ' + IsNull(tcl.cust_city,'')  + '(' + IsNull(tcl.cust_zip,'')  + ')'
  				END																		[it_EWAddress],
  				IsNull(tdm.optval_desc,'')												[sdlmt_desc],
  				CASE
  					WHEN it.it_deliveryDate IS NULL THEN ''
  					ELSE dbo.fnGetDateTimeFromLang(it.it_deliveryDate,2)
  				END																		[it_deliveryDate],
  				CASE
  					WHEN it.it_deliveryDate IS NULL THEN ''
  					ELSE dbo.fnGetDateTimeAMPMFromLang(it.it_deliveryDate,2)
  				END																		[it_deliveryAMPMDate],
  				IsNull(ts2.supp_id,0)													[itemSupplierID],
  				IsNull(ts2.supp_name,'')												[itemSupplierName],
  				IsNull(ts2.supp_address,'') + ' ' +  IsNull(ts2.supp_city,'') + ' (' + ts2.supp_zip + ')'
  																						[itemSupplierAddress],
				IsNull(IT.it_guarantee,0)												[itemWarrantyDays],
				dbo.fnGetTEA(IT.it_price + IT.it_CreditInt + IT.it_CreditIntPlus, IT.it_price, IT.it_loanNumberOfPays)
																						[itemTEA],

				dbo.fnGetTNA(IT.it_price + IT.it_CreditInt + IT.it_CreditIntPlus, IT.it_price, IT.it_loanNumberOfPays)
																						[itemTNA],

				dbo.fnGetTEM(IT.it_price + IT.it_CreditInt + IT.it_CreditIntPlus, IT.it_price, IT.it_loanNumberOfPays)
																						[itemTEM],

				--
			    -- Fechas de Garantia Extendida
			    --
				CASE
					-- Si es un Articulo a Garantizar
					WHEN IT.it_transaction_originalEW IS NULL		THEN dbo.fnGetWarrantyDays(tct.ct_date,0,IT.it_guarantee,1)
					-- Si es una Garantia Extendida
					WHEN IT.it_transaction_originalEW IS NOT NULL	THEN dbo.fnGetWarrantyDays(tct.ct_date,(SELECT TOP 1 /*MOS 12-2021*/  titEW.it_guarantee
					                                             												FROM tbItemTransactions titEW	WITH (NOLOCK)
					                                             												WHERE	titEW.comp_id			= IT.comp_id AND
					                                             														titEW.it_transaction	= IT.it_transaction_originalEW
																										   ),IT.it_guarantee,1)
				END																		[itemWarrantyFrom],
				CASE
					-- Si es un Articulo a Garantizar
					WHEN IT.it_transaction_originalEW IS NULL		THEN dbo.fnGetWarrantyDays(tct.ct_date,0,IT.it_guarantee,2)
					-- Si es una Garantia Extendida
					WHEN IT.it_transaction_originalEW IS NOT NULL	THEN dbo.fnGetWarrantyDays(tct.ct_date,(SELECT TOP 1 /*MOS 12-2021*/  titEW.it_guarantee
					                                             												FROM tbItemTransactions titEW	WITH (NOLOCK)
					                                             												WHERE	titEW.comp_id			= IT.comp_id AND
					                                             														titEW.it_transaction	= IT.it_transaction_originalEW
																										   ),IT.it_guarantee,2)
				END																		[itemWarrantyTo],
				--
			    -- Fechas de Garantia Extendida
			    --

				IsNull(ITEM.item_detail,isnull(tidc.id4c_desc, isnull(ITD.itm_desc,item.item_desc)))	[item_detail],  -- MOS 09-2017 se aGREGO q si no tiene detalle ponga la desc de un artic para los items manuales.

				(
					SELECT TOP	1
								tmpSU9.supp_name
						FROM tbItemSupplier tisu		WITH (NOLOCK)
						INNER JOIN tbsupplier tmpSU9	WITH (NOLOCK)
						ON tmpSU9.comp_id = tisu.comp_id AND
						   tmpSU9.supp_id = tisu.supp_id
						WHERE	tisu.comp_id = IT.comp_id AND
								tisu.item_id = IT.item_id AND
								tisu.isu_is4Service = 'True'
				)																		[WARR_SupplierName],
				(
					SELECT TOP	1
								tmpSU9.supp_address
						FROM tbItemSupplier tisu			WITH (NOLOCK)
						INNER JOIN tbsupplier tmpSU9		WITH (NOLOCK)
							ON tmpSU9.comp_id = tisu.comp_id AND
							   tmpSU9.supp_id = tisu.supp_id
						WHERE	tisu.comp_id = IT.comp_id AND
								tisu.item_id = IT.item_id AND
								tisu.isu_is4Service = 'True'
				)																		[WARR_SupplierAddress],
				IsNull(it.it_insuranceDays,0)											[it_insuranceDays],
				IsNull(it.insud_certificateNumber,0)									[insud_certificateNumber],
			   (
			   	SELECT TOP 1 /*MOS 12-2021*/  tiabr.insud_certificateNote
					FROM tbInsuranceAgent_BranchRelation tiabr		WITH (NOLOCK)
					WHERE	tiabr.comp_id	= it.comp_id AND
							tiabr.insud_id	= it.insud_id
			   )																		[insud_certificateNote]	,
			   (
			   	SELECT TOP 1 /*MOS 12-2021*/  tiabr.insud_polizaNumber
					FROM tbInsuranceAgent_BranchRelation tiabr		WITH (NOLOCK)
					WHERE	tiabr.comp_id	= it.comp_id AND
							tiabr.insud_id	= it.insud_id
			   )																		[insud_polizaNumber],

				--
			    -- Fechas de Seguro
			    --
				CASE
					-- Si es un Articulo a Garantizar
					WHEN IT.it_transaction_originalEW IS NULL		THEN dbo.fnGetWarrantyDays(tct.ct_date,0,IT.it_insuranceDays,1)
					-- Si es una Garantia Extendida
					WHEN IT.it_transaction_originalEW IS NOT NULL	THEN dbo.fnGetWarrantyDays(tct.ct_date,(SELECT TOP 1 /*MOS 12-2021*/  titEW.it_insuranceDays
					                                             												FROM tbItemTransactions titEW		WITH (NOLOCK)
					                                             												WHERE	titEW.comp_id			= IT.comp_id AND
					                                             														titEW.it_transaction	= IT.it_transaction_originalEW
																										   ),IT.it_insuranceDays,1)
				END																		[itemInsuranceFrom],
				CASE
					-- Si es un Articulo a Garantizar
					WHEN IT.it_transaction_originalEW IS NULL		THEN dbo.fnGetWarrantyDays(tct.ct_date,0,IT.it_insuranceDays,2)
					-- Si es una Garantia Extendida
					WHEN IT.it_transaction_originalEW IS NOT NULL	THEN dbo.fnGetWarrantyDays(tct.ct_date,(SELECT TOP 1 /*MOS 12-2021*/  titEW.it_insuranceDays
					                                             												FROM tbItemTransactions titEW		WITH (NOLOCK)
					                                             												WHERE	titEW.comp_id			= IT.comp_id AND
					                 																					titEW.it_transaction	= IT.it_transaction_originalEW
																										   ),IT.it_insuranceDays,2)
				END
																				[itemInsuranceTo],
				--
				-- FIN Fechas de Seguro
				--


				ISNULL(it.it_priceOfprli_id4CreditInCash,0)	*
				dbo.fnTaxMovements_IvaPercentageOfItemTransaction
  							(
  								@comp_id		,
  								@bra_id			,
  								@ct_transaction ,
  								IT.it_transaction
  							)	/ 100											[it_priceOfprli_id4CreditInCash],
  				ISNULL(ITEM.item_EWDesc,'')										[item_EWDesc],
  				ISNULL(tbb.brand_desc,'')										[brand_desc],
  				ISNULL(TMP.sizeColor_item_id,-1)								AS sizeColor_item_id,
				TMP.sizeColor_desc,
				TMP.sizeColor_it_price,
				ISNULL(TMP.sizeColor_shortDesc,'')								AS sizeColor_shortDesc,
				TMP.sizeColor_ITTransaction,
				ISNULL(TMP.sizeColor_QTY,IT.it_qty)								AS sizeColor_QTY,
				isnull(TDF.df_documentsPrintResumeSizeColor,'False')			AS sizeColor_documentsPrintResumeSizeColor,
				dbo.fnGetSaleOrderNumber(it.comp_id,it.bra_id,it.so_id)			AS itemSaleOrderFrom,
  				dbo.fnGetImportData_Lote(					@comp_id,
  															@bra_id,
  															@ct_transaction,
  															it.it_transaction)			[impData_LotNumber],
  				dbo.fnGetImportData_ExpDate(				@comp_id,
  															@bra_id,
  															@ct_transaction,
  															it.it_transaction)			[impData_ExpDate]  	,
  				ROW_NUMBER() OVER (ORDER BY
											CASE
												WHEN TDF.df_documentsPrintResumeSizeColor = 'True' THEN ISNULL(TMP.sizeColor_item_id,-1)
												ELSE													-1
											END
											, IT.it_order
  								  ) AS rowOrder	,
  				it.it_isAssociationGroup,
  				tdf.df_isForAssociation_disablePrintOfAssociatedItems,

				ISNULL(tovMotorTipo.optval_desc,'')							[itemCAR_MotorTipo],
				ISNULL(tovMotorMarca.brand_desc,'')							[itemCAR_MotorMarca],
				ISNULL(item.itemCAR_EngineNumber,'')						[itemCAR_MotorNumero],
				ISNULL(tovChasisMarca.brand_desc,'')						[itemCAR_ChasisMarca],
				ISNULL(item.itemCAR_ChasisNymber,'')						[itemCAR_ChasisNumero],
				ISNULL(item.itemCAR_ChasisBrand,'')							[itemCAR_ChasisMarcaNota] ,
  				ISNULL(item.itemCAR_CertificateNumber,'')					[itemCAR_CertificateNumber],
  				ISNULL(item.itemCAR_CustomNumber,'')						[itemCAR_CustomNumber],
  				ISNULL(item.itemCAR_DNRPA,'')								[itemCAR_DNRPA],
  				ISNULL(item.item_id,'')										[Item___ID],
  				ISNULL(item.item_annotation1,'')							[item_annotation1],
  				ISNULL(item.item_annotation2,'')							[item_annotation2],
  				ISNULL(tis.itst_PickingLocation,'')							[itst_PickingLocation],
  				ISNULL(tis.itst_StorageLocation,'')							[itst_StorageLocation],
  				CONVERT(VARCHAR(MAX),'')									[itemDescPlusAssociatedItemDesc],
  				it.it_item_id_origin



			  INTO #tmpFinalQuery
			  From		dbo.tbItemTransactions							IT			WITH (NOLOCK)

					INNER JOIN tbCompany							tcm			WITH (NOLOCK)
						ON tcm.comp_id = IT.comp_id

  					INNER JOIN tbCommercialTransactions				tct			WITH (NOLOCK)
  						ON		tct.comp_id			= it.comp_id
  							AND tct.bra_id			= it.bra_id
  							AND tct.ct_transaction	= it.ct_transaction

					INNER JOIN tbCustomer							tcl			WITH (NOLOCK)
						ON	tcl.comp_id = tct.comp_id AND
							tcl.cust_id = tct.cust_id

					LEFT JOIN tbCustomerFamily						tcf			WITH (NOLOCK)
						ON	tcf.comp_id		= tct.comp_id AND
							tcf.cust_id		= tct.cust_id AND
							tcf.custf_id	= tct.custf_id

  					INNER JOIN tbDocumentsFile						tdf			WITH (NOLOCK)
  						ON		tdf.comp_id = tct.comp_id
  							AND tdf.df_id	= tct.df_id

  					LEFT JOIN tbItemDescription4Customer			tidc		WITH (NOLOCK)
  						ON		tidc.comp_id = it.comp_id
  							AND tidc.cust_id = tct.cust_id
  							AND tidc.item_id = it.item_id

  					Left Join dbo.tbItemTransactionDetails			ITD			WITH (NOLOCK)
  						ON	ITD.comp_id				=	IT.comp_id
  						and	ITD.bra_id				=   IT.bra_id
  						and ITD.it_transaction		=	IT.it_transaction

  					left join dbo.tbItem							ITEM		WITH (NOLOCK)
  						on  item.comp_id			=	IT.comp_id
  						AND (
  								item.item_id		=	IT.item_id
  									OR
  								item.item_id		= it.item_idfromPreInvoice
  							)

  					left join dbo.tbItem							ITEM4PreInvoice			WITH (NOLOCK)
  						on  ITEM4PreInvoice.comp_id			=	IT.comp_id					AND
  							ITEM4PreInvoice.item_id			=	IT.item_idfromPreInvoice

					LEFT JOIN tbItem							AS tiOrigin		WITH (NOLOCK)
						ON	tiOrigin.comp_id = IT.comp_id				AND
							tiOrigin.item_id = IT.it_item_id_origin

  					left join dbo.tbStorage							STOR		WITH (NOLOCK)
  						on  stor.comp_id			=	IT.comp_id
  						AND stor.stor_id			=	IT.stor_id

  					left join dbo.tbPriceList						PRLI		WITH (NOLOCK)
  						on  prli.comp_id			=	IT.comp_id
  						AND prli.prli_id			=	IT.prli_id

  					left join dbo.[tbsysCurrency]					SC			WITH (NOLOCK)
  						on	SC.curr_id				=	IT.curr_id

					LEFT JOIN tbsyscurrency							SCOr		WITH (NOLOCK)
						ON SCOr.curr_id				=	it.it_OriginalPriceCurrency

	  				LEFT JOIN tbItemSizeColorRelation				tiscr		WITH (NOLOCK)
	  					ON		tiscr.comp_id		= it.comp_id
	  						AND tiscr.item_id_child = it.item_id

					left JOIN tbColor tc										WITH (NOLOCK)
						ON		tc.comp_id	= tiscr.comp_id
							AND tc.color_id = tiscr.color_id

					left JOIN tbSize ts											WITH (NOLOCK)
						ON		ts.comp_id	= tiscr.comp_id
							and ts.Size_id	= tiscr.size_id

					LEFT JOIN vwTaxMovements_TotalIVATax			vtt			WITH (NOLOCK)
						ON		vtt.comp_id			= it.comp_id
							AND vtt.bra_id			= it.bra_id
							AND vtt.ct_transaction	= it.ct_transaction
							AND vtt.it_transaction	= it.it_transaction

	  				LEFT JOIN tbMetricUnits tmu									WITH (NOLOCK)
	  					ON		tmu.comp_id			= item.comp_id
	  						AND tmu.mu_id			= item.mu_id

	  				LEFT JOIN tbPresentation tp									WITH (NOLOCK)
	  					ON	tp.comp_id = ITEM.comp_id AND
	  						tp.pres_id = ITEM.pres_id

					LEFT JOIN tbSupplier ts2									WITH (NOLOCK)
						ON	ts2.comp_id = ITEM.comp_id AND
							ts2.supp_id = ITEM.supp_id



					LEFT JOIN tbByOrder tbo										WITH (NOLOCK)
						ON	tbo.comp_id = IT.comp_id AND
							tbo.byor_id = IT.byor_id

					LEFT JOIN tbBrand tbb										WITH (NOLOCK)
						ON	tbb.comp_id	= ITEM.comp_id AND
							tbb.brand_id = ITEM.brand_id

					--LEFT JOIN tbsysDeliveryMethod tdm							WITH (NOLOCK)
					--	ON tdm.sdlmt_id = IT.sdlmt_id

					LEFT JOIN tbsysOptionsValues tdm							WITH (NOLOCK)
						ON	tdm.optval_class = 520			AND
							tdm.optval_id    = it.sdlmt_id	AND
							tdm.lang_id		 = tcm.lang_id

					LEFT JOIN #tbItemTransactionsTMP TMP
						ON     TMP.sizeColor_ITTransaction LIKE '%;' + dbo.fnStrAllTrim(CONVERT(CHAR(10),IT.it_transaction)) + ';%'


					LEFT JOIN tbsysOptionsValues AS tovMotorTipo				WITH (NOLOCK)
						ON	tovMotorTipo.lang_id		=  1 AND
							tovMotorTipo.optval_class	= 690 AND
							tovMotorTipo.optval_id		= item.itemCAR_EngineType

					LEFT JOIN tbBrand AS tovMotorMarca							WITH (NOLOCK)
						ON	tovMotorMarca.comp_id		= item.comp_id AND
							tovMotorMarca.brand_id		= item.brand_id_carEngine

					LEFT JOIN tbBrand AS tovChasisMarca							WITH (NOLOCK)
						ON	tovChasisMarca.comp_id		= item.comp_id AND
							tovChasisMarca.brand_id		= item.brand_id_carChassis

					LEFT JOIN tbItemStorage					AS tis				WITH (NOLOCK)
						ON	tis.comp_id = IT.comp_id AND
							tis.stor_id = IT.stor_id AND
							tis.item_id = IT.item_id




		  Where		IT.comp_id					=		@comp_id
		  AND			IT.bra_id 				=		@bra_id
		  AND			IT.ct_transaction		=		@ct_transaction
		  AND		(@intItemTransactionFilter1 = 0						OR
					 it.it_transaction = @intItemTransactionFilter1		OR
					 it.it_transaction = @intItemTransactionFilter2
					)
		  AND		CASE
						WHEN item.comp_id IS NULL						THEN 1
						WHEN item.item_disablePrintInDocumentsPrint = 0 THEN 1
						WHEN it.it_isAssociationGroup IS NOT NULL	AND
							 it.it_price <> 0	/* MOS 01-2022: Maxi Playroom, para poder OCULTAR un item en la impresion NO RESUMIDA del Combo*/
																		THEN 1	-- MOS 06-01-2022 x Beerman y los forros q conf cualquier mierda  los vendedores q ponen cualquier mierda.  Pusieron q se resuma y ademas q este no imprima por lo que no lo resumia.
						ELSE 0
					END		=	1
		  AND		(
		  				it.it_disablePrintInEmmition = 'False'		OR
		  					(
		  						it.it_disablePrintInEmmition = 'True'
		  							AND
		  						it.it_isAssociationGroup IS NOT NULL
		  					)
					) -- para que NO imprima NO debe ser un combo y el campo debe estar en True, por ejemplo, Armado de PC
		ORDER BY
					CASE
						WHEN TDF.df_documentsPrintResumeSizeColor = 'True' THEN ISNULL(TMP.sizeColor_item_id,-1)
						ELSE													-1
					END
					, IT.it_order

--==
--SELECT it_ivatax,'#tmpFinalQuery',* FROM #tmpFinalQuery
		-- --------------------------------------------------------------------------------------------------------------
		-- Acá se hace que si el DOCUMENTO y los COMBOS dicen que NO debe imprimirse la COMPOSICION de un combo, NO LO HAGA y
		--		recalcule los importes del PADRE del combo para que sumen los importes de las PARTES para la IMPRESION UNICAMENTE!!!
		--
		-- DATASOFT, gente &%$&$%, hay que hacer toda esta MIERDA por ellos !!!
		-- poner en otra temporal para poder calcular los totales agrupados de las transacciones ocultas.
		-- verificar los campos de precio para saber si se pasan OK o hay que recalcularlos
		-- la idea es que si es un padre de combo, sacandolo por la transaccion asociada, y si los hijos NO se imprimen,
		--    se debe reemplazar en los registros del padre con la suma de los campos de los hijos y al final, retornar esta temporal con el orden sacando los que NO se imprimen.
		-- --------------------------------------------------------------------------------------------------------------
		IF EXISTS  (
						SELECT TOP 1 1
							FROM #tmpFinalQuery
							WHERE df_isForAssociation_disablePrintOfAssociatedItems = 1
					)
			BEGIN									-- ISNULL(...,it_price)  y el resto fueron puestos x el FORRO de BYF que hizo una fc de dos hojas y le quedo un combo x la mitad de cada factura
				UPDATE #tmpFinalQuery
					SET it_price =						ISNULL((	SELECT SUM(it_price * tmpft2.it_qty)    -- /** tmpft2.it_qty*/ MOS 08-2020, GUALA, si eran muchos combo remultiplicaba x la cantidad
					                   									FROM	#tmpFinalQuery tmpft2
					          									WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   											tmpft2.item_id IS NOT NULL
														),it_price)
															/	-- MOS 04-2021: Hay que DIVIDIR por la Cantidad de Combos solicitados para que quede finalmente el precio de UN combo como UNITARIO ! ! !
														dbo.fnNoZDiv(
																		(
																			SELECT	 TOP 1 /*MOS 12-2021*/ 	tmpft3.it_qty
					                   											FROM	#tmpFinalQuery tmpft3
					                   											WHERE	tmpft3.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   													tmpft3.item_id IS NULL
																		)
																	),
						it_priceWithOutOthers = ISNULL((	SELECT SUM(it_priceWithOutOthers * tmpft2.it_qty)    -- /** tmpft2.it_qty*/ MOS 08-2020, GUALA, si eran muchos combo remultiplicaba x la cantidad
					                   							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
												),it_priceWithOutOthers)
															/
														dbo.fnNoZDiv(
																		(
																			SELECT	 TOP 1 /*MOS 12-2021*/ 	tmpft3.it_qty
					                   											FROM	#tmpFinalQuery tmpft3
					                   											WHERE	tmpft3.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   													tmpft3.item_id IS NULL
																		)
																	),


						-- MOS 12-2021: ISNULL: en Beerman estaban tratando de RESUMIR un combo al cual x permisos le habian borrado TODAS sus partes
						it_ivatax =						ISNULL((	SELECT SUM(it_ivatax )    -- /** tmpft2.it_qty*/ MOS 08-2020, GUALA, si eran muchos combo remultiplicaba x la cantidad
					                   							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
														),0)


														-- -------------------------------------------------
														-- MOS 12-2021: No se quien fue el FORRO que paso esto
														-- pero en el diseñados de documentos, en los DOS
														-- lugares en que se los usa, se usan como total o dividido la QTY.
														--
														-- NO VOLVER A PONER el resumen DIVIDIDO la cantidad ! ! !
														--
														-- BYF Deco x Impresion de Combos en CR Resumidos
														-- -------------------------------------------------
														--
														--	/	-- MOS 04-2021: Hay que DIVIDIR por la Cantidad de Combos solicitados para que quede finalmente el precio de UN combo como UNITARIO ! ! !
														--dbo.fnNoZDiv(
														--				(
														--					SELECT		tmpft3.it_qty
					         --          											FROM	#tmpFinalQuery tmpft3
					         --          											WHERE	tmpft3.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					         --          													tmpft3.item_id IS NULL
														--				)
														--)
														-- -------------------------------------------------


														,
						-- este y el de abajo no se si dejarlos ya que pueden ser diferentes monedas.
						it_OriginalPrice =				ISNULL( (	SELECT SUM(it_OriginalPrice * tmpft2.it_qty)
					                   							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
														),it_OriginalPrice)
																					/
														dbo.fnNoZDiv(
																		(
																			SELECT	 TOP 1 /*MOS 12-2021*/ 	tmpft3.it_qty
					                   											FROM	#tmpFinalQuery tmpft3
					                   											WHERE	tmpft3.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   													tmpft3.item_id IS NULL
																		)
																	),
						it_OriginalPriceCurrency	=	(	SELECT TOP 1  it_OriginalPriceCurrency
					                   							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
														),
						it_priceOfCost =				ISNULL( (	SELECT SUM(it_priceOfCost * tmpft2.it_qty)
					                   							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
														)	,it_priceOfCost)					/
														dbo.fnNoZDiv(
																		(
																			SELECT	 TOP 1 /*MOS 12-2021*/ 	tmpft3.it_qty
					                   											FROM	#tmpFinalQuery tmpft3
					                   											WHERE	tmpft3.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   													tmpft3.item_id IS NULL
																		)
																	),
						it_priceOfCostPP =				 (	SELECT SUM(it_priceOfCostPP * tmpft2.it_qty)
					                   							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
														 )															/
														dbo.fnNoZDiv(
																		(
																			SELECT	 TOP 1 /*MOS 12-2021*/ 	tmpft3.it_qty
					                   											FROM	#tmpFinalQuery tmpft3
					                   											WHERE	tmpft3.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   													tmpft3.item_id IS NULL
																		)
																	),
						it_priceBOfCost =				ISNULL( (	SELECT SUM(it_priceBOfCost * tmpft2.it_qty)
					                   							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
														 ),it_priceBOfCost)				/
														dbo.fnNoZDiv(
																		(
																			SELECT	 TOP 1 /*MOS 12-2021*/ 	tmpft3.it_qty
					                   											FROM	#tmpFinalQuery tmpft3
					                   											WHERE	tmpft3.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   													tmpft3.item_id IS NULL
																		)
																	),
						it_priceBOfCostPP =				ISNULL( (	SELECT SUM(it_priceBOfCostPP * tmpft2.it_qty)
					                   							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
														 )	,it_priceBOfCostPP)			/
														dbo.fnNoZDiv(
																		(
																			SELECT	 TOP 1 /*MOS 12-2021*/ 	tmpft3.it_qty
					                   											FROM	#tmpFinalQuery tmpft3
					                   											WHERE	tmpft3.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   													tmpft3.item_id IS NULL
																		)
																	),
						itemTEA			  =				 (	SELECT AVG(itemTEA )
					                   							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
											),
						itemTNA			  =				 (	SELECT AVG(itemTNA )
					     							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
											),
						itemTEM			  =				 (	SELECT AVG(itemTEM )
					                   							FROM	#tmpFinalQuery tmpft2
					                   							WHERE	tmpft2.it_isAssociationGroup = tmpfq.it_isAssociationGroup AND
					                   									tmpft2.item_id IS NOT NULL
											)

					FROM	#tmpFinalQuery tmpfq
				WHERE		tmpfq.it_isAssociationGroup IS NOT NULL AND
							tmpfq.item_id IS NULL





				-- -----------------------------------------------------------------------------------------------------
				-- MOS: 06-01-2022
				-- Por los forros de Beerman que armaban dos combos para resumir, borraban todas las partes del 1ro y borraban la cabecera del segundo, quedando la cabecera del primero con las partes del segundo
				-- -----------------------------------------------------------------------------------------------------
				-- Borro TODAS las partes que TENGAN un mismo associationgroup y un AGRUPADOR de combo ( Item_ID is Nul)
				DELETE		#tmpFinalQuery
					FROM	#tmpFinalQuery  it
					INNER JOIN tbItemTransactions AS tit WITH (NOLOCK)
						ON	tit.comp_id					= it.comp_id				AND
							tit.bra_id					= it.bra_id					AND
							tit.ct_transaction			= it.ct_transaction			AND
							--tit.it_transaction			= it.it_transaction			AND
							tit.it_isAssociationGroup	= it.it_isAssociationGroup	AND
							tit.item_id IS NULL
					WHERE it.it_isAssociationGroup IS NOT NULL AND it.item_id IS NOT NULL


				-- Borro TODOS los Agrupadores que NO tengan ninguna parte asociada.
				DELETE		#tmpFinalQuery
					FROM	#tmpFinalQuery  it
					LEFT JOIN tbItemTransactions AS tit WITH (NOLOCK)
						ON	tit.comp_id					= it.comp_id				AND
							tit.bra_id					= it.bra_id					AND
							tit.ct_transaction			= it.ct_transaction			AND
							--tit.it_transaction			= it.it_transaction			AND
							tit.it_isAssociationGroup	= it.it_isAssociationGroup	AND
							tit.item_id IS NOT NULL
					WHERE	tit.comp_id IS NULL AND
							it.it_isAssociationGroup IS NOT NULL AND
							it.item_id  IS  NULL



				-- Antes del 06-01-2022
				--DELETE FROM #tmpFinalQuery
				--	WHERE it_isAssociationGroup IS NOT NULL AND item_id IS NOT NULL	-- Borra PARTES del COMBO


			END
			-- --------------------------------------------------------------------------------------------------------------





		-- --------------------------------------------------------------------------------------------------------------
		-- MOS 11-2022 x el FORRO MENTAL HDRMP de NG cd C1 q quiere los combos
		--					resumidos en 1 renglon con la desc de los items
		-- --------------------------------------------------------------------------------------------------------------
		DECLARE @curit_transaction AS INT
		DECLARE @curItemDesc AS VARCHAR(1000)
		DECLARE curFORRODEMIERDA CURSOR LOCAL FAST_FORWARD FOR
			SELECT		it_transaction,
					 CONVERT(VARCHAR(20),CONVERT(INT,tia.iasso_qty)) + 'x ' + ti.item_desc
				FROM    #tmpFinalQuery tmp
				INNER JOIN tbItemAssociation	AS tia	WITH (NOLOCK)
					ON	tia.comp_id = tmp.comp_id AND
						tia.item_id = tmp.it_item_id_origin
				INNER JOIN tbItem				AS ti	WITH (NOLOCK)
					ON	ti.comp_id	= tia.comp_id AND
						ti.item_id	= tia.item_id_1


		OPEN		curFORRODEMIERDA
		FETCH NEXT
			FROM	curFORRODEMIERDA
			INTO	@curit_transaction,
					@curItemDesc

		WHILE @@FETCH_STATUS = 0
			BEGIN

				UPDATE #tmpFinalQuery
					SET itemDescPlusAssociatedItemDesc =  itemDescPlusAssociatedItemDesc +	CASE
																								WHEN itemDescPlusAssociatedItemDesc = '' THEN	'Compuesto por: '
																								ELSE											', '
                                                                      						END  + @curItemDesc
					WHERE it_transaction = @curit_transaction

				FETCH NEXT
					FROM	curFORRODEMIERDA
					INTO	@curit_transaction,
							@curItemDesc

			END
		CLOSE		curFORRODEMIERDA
		DEALLOCATE	curFORRODEMIERDA
		-- --------------------------------------------------------------------------------------------------------------



		SELECT * FROM #tmpFinalQuery ORDER BY rowOrder

		DROP TABLE #tmpFinalQuery
		DROP TABLE #tbItemTransactionsTMP

END

GO





CREATE PROCEDURE [dbo].[spItemTransactions_getDataByFilters2]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@item_id		INT,
	@datefrom		DATETIME,
	@dateto			DATETIME,
	@supp_id		INT,
	@stor_id		INT,
	@cust_id		INT,
	@sd_id			INT,
	@serial			VARCHAR(100),
	@import_id		INT,
	@type			INT,
	@user_id		INT,
	@GuidItem		VARCHAR(50)

)
AS

BEGIN


	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

-- --------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------
/*
	DECLARE	@comp_id		INT,
			@lang_id		INT,
			@bra_id			INT,
			@item_id		INT,
			@supp_id		INT,
			@datefrom		DATETIME,
			@dateto			DATETIME,
			@sd_id			INT,
			@stor_id		INT,
			@cust_id		INT,
			@serial			VARCHAR(100),
			@import_id		Int,
			@type			INT,
			@user_id		INT,
			@GuidItem		VARCHAR(50) = newID()



	SELECT	@comp_id   =  1,
			@lang_id   =  2,
			@bra_id	   = -1,
			@item_id   = -1,
			@supp_id   = -1,
			@datefrom  = '2020-07-01',
			@dateto	   = '2999-07-15',
			@sd_id	   = -1,
			@stor_id   = -1,
			@cust_id   = -1,
			@serial    = '',
			@import_id = -1,
			@type      = -1,
			@user_id   =  1
*/
-- --------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')




	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT NULL UNIQUE CLUSTERED)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf	WITH (NOLOCK)
			WHERE	tcf.sl_guid		= @GuidItem     AND
					tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			IF @item_id > 0
				BEGIN
					INSERT INTO @tblComplexFilter_Items(item_id) VALUES (@item_id)
				END
			ELSE
				BEGIN
					INSERT INTO @tblComplexFilter_Items(item_id)
						SELECT item_id
							FROM tbItem ti	WITH (NOLOCK)
							WHERE ti.comp_id = @comp_id
					--INSERT INTO @tblComplexFilter_Items( item_id) VALUES (NULL)
				END
		END

	-- -------------------------------------------------------------



	-- --------------------------------------------------------------------
	-- Inserta en la tabla las transacciones correspondientes al numero
	-- de serie informado.
	-- --------------------------------------------------------------------
	DECLARE @tblSerials TABLE (ct_transaction int, it_transaction int)
	IF @serial <> ''
		BEGIN
			INSERT INTO @tblSerials (ct_transaction , it_transaction)
				SELECT	tis.ct_transaction,
						tis.it_transaction
					FROM	tbItemSerials tis				WITH (NOLOCK)
					WHERE	tis.comp_id		= @comp_id
					AND		tis.is_serial	= @serial

			UNION

			SELECT	tits.ct_transaction,
					tits.it_transaction
				FROM	tbItemTransactionSerials	tits	WITH (NOLOCK)
				INNER JOIN tbItemSerials			tis		WITH (NOLOCK)
				ON	tis.comp_id		= tits.comp_id	AND
					tis.is_id		= tits.is_id
			WHERE	tis.comp_id		= @comp_id AND
					tis.is_serial	= @serial
		END
	-- --------------------------------------------------------------------


	DECLARE @tblSuppliers4Transfer AS TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblSuppliers4Transfer( supp_id)
		SELECT distinct tbcsi.supp_id
			FROM tbBranch2Customer4StockImport tbcsi	WITH (NOLOCK)
			WHERE	tbcsi.comp_id = @comp_id AND
					tbcsi.supp_id IS NOT NULL



	-- ---------------------------------------------------
	-- Temporal de Sucursales
	-- ---------------------------------------------------
	DECLARE		@tmpBranchs TABLE (bra_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchs
	(
		bra_id
	)
		SELECT DISTINCT  bra_id
			FROM tbUsers4BranchFilter		WITH (NOLOCK)
			WHERE	comp_id		= @comp_id AND
					[user_id]	= @user_id
	IF @bra_id > 0	DELETE FROM @tmpBranchs WHERE bra_id <> @bra_id
	-- ---------------------------------------------------


	-- ---------------------------------------------------
	-- Temporal de Depositos
	-- ---------------------------------------------------
	DECLARE		@tmpStorage TABLE (stor_id INT PRIMARY KEY)
	INSERT INTO @tmpStorage
	(
		stor_id
	)
		SELECT DISTINCT  stor_id
			FROM tbStorage AS ts			WITH (NOLOCK)
			WHERE	comp_id		= @comp_id
	IF @stor_id > 0	DELETE FROM @tmpStorage WHERE stor_id <> @stor_id
	-- ---------------------------------------------------












	DECLARE @bitIsStockPhoto AS BIT
	SET		@bitIsStockPhoto = 'False'
	SELECT	@bitIsStockPhoto = 'True'
		FROM tbStorage ts	WITH (NOLOCK)
		WHERE	ts.comp_id = @comp_id AND
				ts.stor_savePhotoOnITTransaction = 'True'


	-- 05-2016 se saco la vista vwItemTransactions y se puso el PlusOrMinus de manera directa son tbsysDocuments para hacer la busqueda mas rapida.


	SELECT	'' [1],
			'' [2],
			tit.comp_id,
			tit.bra_id,
			tct.ct_cd,
			tb.bra_desc,
			ts.stor_desc,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tit.ct_transaction)[Comprobante],

			tit.it_qty *	CASE
								WHEN tsd.sd_isPurchase='false' AND tsd.sd_isCredit='false' THEN -1
								WHEN tsd.sd_isPurchase='false' AND tsd.sd_isCredit='True'  THEN  1
								WHEN tsd.sd_isPurchase='True'  AND tsd.sd_isCredit='false' THEN  1
								WHEN tsd.sd_isPurchase='True'  AND tsd.sd_isCredit='True'  THEN -1
							END											[it_qty],

			--convert(decimal(19,3),isnull(vit.vw_qty,0)) 				[it_qty],				-- (8)	--MOS 08-2010
			convert(decimal(19,3),isnull(tit.it_storePrevious,0))		[it_storePrevious],		-- (9)
			convert(decimal(19,3),ISNULL(tis.itst_cant,0))				[StockActual],			--(10)
			tov.optval_desc												[sd_desc],
			tsr.stor_desc												[tsrDesc],
			tit.ct_transaction,
			tit.it_transaction,
			IsNull(ti.item_code,'Manual')								[item_code],
			IsNull(ti.item_desc,IsNull(titd.itm_desc,'Item Manual'))	[item_desc],
			IsNull(tbr.brand_desc,'')									[brand_desc],
			CASE
				WHEN tct.st_id IS NOT NULL THEN tst.st_desc
				ELSE ''
			END															[st_desc],
			tct.ct_date,
			isnull(ti2.import_desc, ' ')								[import_desc],

			case
				When tct.cust_id IS NULL then	isnull(tsupp.supp_name, ' ')  + ' (' + CONVERT(NVARCHAR(15),ISNULL(tsupp.supp_id,0)) + ')'
				Else							Isnull(tccust.cust_name, ' ') + CASE
																					WHEN tcf.comp_id IS NOT NULL THEN ' => ' + ISNULL(tcf.custf_name,'')
																					WHEN tcb.comp_id IS NOT NULL THEN ' => ' + ISNULL(tcb.custb_name,'')
																					ELSE ''
																				END + ' (' + CONVERT(NVARCHAR(15),ISNULL(tccust.cust_id,0)) + ')'
			End															[supp_name],
			convert(decimal(19,4),isnull(tit.it_priceWithOutOthers,0))									[it_priceWithOutOthers],
			convert(decimal(19,4),tit.it_price)															[it_price],
			convert(decimal(19,4),isnull(tit.it_price,0) * isnull(

																	tit.it_qty *	CASE
																						WHEN tsd.sd_isPurchase='false' AND tsd.sd_isCredit='false' THEN -1
																						WHEN tsd.sd_isPurchase='false' AND tsd.sd_isCredit='True'  THEN  1
																						WHEN tsd.sd_isPurchase='True'  AND tsd.sd_isCredit='false' THEN  1
																						WHEN tsd.sd_isPurchase='True'  AND tsd.sd_isCredit='True'  THEN -1
																					END

															/*vit.vw_qty*/,0)	)						[Total],
			tc.curr_desc,
			(tu.user_firstname) + ', ' + dbo.fnStrAllTrim(tu.user_lastname)			[User],
			sm.sm_name,
			CONVERT(DECIMAL(19,5),tit.it_exchangeToBranchCurrency)		[it_exchangeToBranchCurrency],	-- MOS 03-2021
			isnull(tit.it_priceOfCost,0)								[it_priceOfCost],
			isnull(tit.it_priceOfCostPP,0)								[it_priceOfCostPP],
			isnull(tit.it_priceOfCostLastPurchase,0)					[it_priceOfCostLastPurchase],
			isnull(tit.it_priceBOfCost,0)								[it_priceBOfCost],
			isnull(tit.it_priceBOfCostPP,0)								[it_priceBOfCostPP],
			isnull(tit.it_priceBOfCostLastPurchase,0)					[it_priceBOfCostLastPurchase],
			isnull(tit.it_OriginalPrice,0)								[it_OriginalPrice],
			tc2.curr_desc,
			isnull(tit.it_exchangeToOriginalPriceCurrency,0)			[it_exchangeToOriginalPriceCurrency],
			isnull(tpl.prli_desc, ' ')									[prli_desc],
			tit.it_isProduction,
			tit.it_isAssociation,
			isnull(tit.it_isAssociationGroup,0)							[it_isAssociationGroup],
			tit.it_cd,
			tit.it_packingInvoicePend,
			isnull(tit.it_order,0)										[it_order] ,
			tit.so_id,
			isnull(tit.it_guarantee,0)									[it_guarantee],
			isnull(tit.it_itemDiscountTotal,0)							[it_itemDiscountTotal],
			isnull(tit.it_totalDiscountTotal,0)							[it_totalDiscountTotal],
			isnull(tit.it_note2,'')										[it_note2],
			isnull(tit.it_CreditInt,0)									[it_CreditInt],
			isnull(tit.it_CreditIntPlus,0)								[it_CreditIntPlus],

			-- MOS:02-2023 ticket 15934
			CONVERT(DECIMAL(19,5),dbo.fnGetReciprocoIfNeed( tct.ct_curr_IdExchange))			[ct_curr_IdExchange],
			CASE
				WHEN tct.ct_curr_IdExchange = 1 THEN	'   '
				ELSE									ISNULL(tc5.curr_symbolFEx,'')
			END																					[symbolcurr_IdExchange],
			-- MOS:02-2023 ticket 15934

			tpc.puco_desc,
			isnull(tit.it_poh_bra_id,0)									[it_poh_bra_id],
			isnull(tit.it_poh_id,0)										[it_poh_id],
			isnull(tit.it_soh_id,0)										[it_soh_id],
			isnull(tit.it_sod_id,0)										[it_sod_id],
			tit.rmah_id,
			tit.rmad_id,
			isnull(tit.it_qty_rma,0)									[it_qty_rma],
			isnull(tit.it_tis_id_aux,0)									[it_tis_id_aux],
			CASE
				WHEN tit.it_poh_id IS NOT NULL THEN isnull(Convert(Varchar,tit.it_poh_bra_id),0) + '-' + isnull(Convert(Varchar,tit.it_poh_id),0)
				ELSE ''
			END																								[ct_poh_id],
			CASE
				WHEN tct.ct_soh_id IS NOT NULL THEN	isnull(Convert(Varchar,tct.ct_soh_bra_id),0) + '-' + isnull(Convert(Varchar,tct.ct_soh_id),0)
				ELSE ''
			END																								[ct_soh_id],

			CASE @type
					WHEN -1 THEN (SELECT tov.optval_desc FROM tbsysOptionsValues tov WITH (NOLOCK) WHERE tov.lang_id = @lang_id AND tov.optval_class = 110  AND tov.optval_id = 0)
				    ELSE         (SELECT tov.optval_desc FROM tbsysOptionsValues tov WITH (NOLOCK) WHERE tov.lang_id = @lang_id AND tov.optval_class = 317 AND tov.optval_id = @type)
			END															[Type],
			CASE
				WHEN tit.sitt_id = 50 THEN 'Ctrl:' + tscod.itstkpld_noteOfController + CHAR(10) + CHAR(13) + 'Mgr:' + tscod.itstkpld_noteOfManager
				ELSE tctn.ctn_note1
			END															[ctn_note1],
			tov2.optval_desc											[isInternaTransfer],
			tit.it_transaction											[TransactionSTK],
			tit.it_NoStockCheck,
			td.sd_desc													[sd_Description],

			CASE
				WHEN @bitIsStockPhoto = 'False'			THEN	''
														ELSE	dbo.fnItemStoragePhoto(tit.comp_id,tit.it_transaction)
			END															[StoragePhoto],

			-- --------------------------------------------------------------------------------------------------------
			-- ATENCION!!!!!!
			-- No poner nada detras de este campo ya que se hacen controles de Count en la pagina 	wfmItemTransaction
			-- --------------------------------------------------------------------------------------------------------
			CASE
				WHEN tit.it_isInBranchTransferTotalizerStorage = 'True' AND tit.it_NoStockCheck = 'True' THEN 1
				ELSE 0
			END															[putStockInCero],		-- COUNT - 6

			tit.it_transaction											[ID],	-- COUNT - 5,
			tit.sitt_id													[sitt_id],				-- COUNT - 4
			tit.item_id,																		-- COUNT - 3
			convert(bit,CASE
				WHEN tit.sitt_id = 50 THEN  'True'
				ELSE						'False'
			END	)														[it_IsStockControl],	-- COUNT - 2

			CASE
				WHEN tit2.comp_id  IS NULL THEN '*'
				ELSE dbo.fnGetCommercialTransactionDescription(tit2.comp_id,@lang_id,tit2.ct_transaction)
			END															[InvoiceFromPacking]	-- COUNT - 1
			-- --------------------------------------------------------------------------------------------------------

	FROM	tbItemTransactions						tit			WITH (NOLOCK)

			INNER JOIN  @tmpBranchs		vubf
				ON  vubf.bra_id			= tit.bra_id

			INNER JOIN @tblComplexFilter_Items ttmp
				ON ttmp.item_id = tit.item_id

			INNER JOIN tbCommercialTransactions		tct			WITH (NOLOCK)
				ON  tct.comp_id			= tit.comp_id
				AND tct.ct_transaction	= tit.ct_transaction


			INNER JOIN @tmpStorage		ts2
				ON ts2.stor_id			= tit.stor_id

			INNER JOIN tbsysDocuments tsd					WITH (NOLOCK)
				ON tsd.sd_id = tct.sd_id

			INNER Join tbBranch						tb			WITH (NOLOCK)		-- LEFT
				On	TB.comp_id			= tit.comp_id
				And tb.bra_id			= tit.bra_id

			INNER  JOIN tbsysOptionsValues tov					WITH (NOLOCK)
				ON	tov.lang_id			= @lang_id	AND
					tov.optval_class	= 950		AND
					tov.optval_id		= tit.sitt_id


			LEFT JOIN tbUser tu									WITH (NOLOCK)
				ON tu.[user_id] = tct.[user_id]


			LEFT JOIN tbItemTransactionDetails titd				WITH (NOLOCK)

				ON	titd.comp_id		= tit.comp_id
				AND titd.bra_id			= tit.bra_id
				AND titd.ct_transaction	= tit.ct_transaction
				AND titd.it_transaction	= tit.it_transaction


			LEFT JOIN tbstorage tsr							WITH (NOLOCK)
				ON	tsr.comp_id = tit.comp_id AND
					tsr.stor_id = tit.stor_id_related4BranchTransfer


			LEFT JOIN tbSalesman sm								WITH (NOLOCK)
				ON	sm.comp_id	= tct.comp_id AND
					sm.sm_id	= tct.sm_id

			LEFT JOIN tbCommercialTransactionNotes	tctn		WITH (NOLOCK)

				ON  tctn.comp_id		= tct.comp_id
				AND tctn.bra_id			= tct.bra_id
				AND tctn.ct_transaction = tct.ct_transaction

			LEFT JOIN tbSupplier					tsupp		WITH (NOLOCK)

				ON  tsupp.comp_id		= tct.comp_id
				AND tsupp.supp_id		= tct.supp_id

			LEFT Join tbCustomer					tccust		WITH (NOLOCK)

				ON  tccust.comp_id		= tct.comp_id
				AND tccust.cust_id		= tct.cust_id

			LEFT JOIN tbCustomerBranch tcb						WITH (NOLOCK)
				ON	tcb.comp_id = tct.comp_id	AND
					tcb.cust_id = tct.cust_id	AND
					tcb.cb_id	= tct.cb_id

			LEFT JOIN tbCustomerFamily tcf						WITH (NOLOCK)
				ON	tcf.comp_id		= tct.comp_id AND
					tcf.cust_id		= tct.cust_id AND
					tcf.custf_id	= tct.custf_id

			LEFT JOIN tbItem						ti			WITH (NOLOCK)
				ON	ti.comp_id			= tit.comp_id
				AND ti.item_id			= tit.item_id


			LEFT JOIN tbBrand tbr								WITH (NOLOCK)
				ON	tbr.comp_id			= ti.comp_id AND
					tbr.brand_id			= ti.brand_id

			LEFT JOIN tbItemStorage tis							WITH (NOLOCK)
				ON		tis.comp_id = tit.comp_id
					AND tis.stor_id = tit.stor_id
					AND tis.item_id = tit.item_id

			LEFT JOIN tbsysCurrency					tc			WITH (NOLOCK)
				ON	tc.curr_id			= tit.curr_id

			LEFT JOIN tbsysCurrency					tc2			WITH (NOLOCK)
				ON	tc2.curr_id			= tit.it_OriginalPriceCurrency



			LEFT JOIN tbStorage						ts			WITH (NOLOCK)
				on  ts.comp_id			= tit.comp_id
				AND ts.stor_id			= tit.stor_id

			LEFT JOIN tbPriceList					tpl			WITH (NOLOCK)
				ON  tpl.comp_id			= tit.comp_id
				AND tpl.prli_id			= tit.prli_id

			LEFT JOIN tbPurchaseConcept				tpc			WITH (NOLOCK)
				ON  tpc.comp_id			= tit.comp_id
				AND Tpc.puco_id			= tit.puco_id

			LEFT JOIN tbsysDocuments				td			WITH (NOLOCK)
				ON	td.sd_id			= tct.sd_id

			LEFT JOIN tbImportDetail				tid			WITH (NOLOCK)
				ON  tid.comp_id			= tit.comp_id
				AND tid.ct_transaction	= tit.ct_transaction

			LEFT JOIN tbImport						ti2			WITH (NOLOCK)
				ON  ti2.comp_id			= tid.comp_id
				AND ti2.import_id		= tid.import_id

			LEFT JOIN tbItemTransactions tit2					WITH (NOLOCK)
				ON	tit2.comp_id						= tit.comp_id					AND
					tit2.it_transaction					= tit.it_transaction_original	AND
					tit.it_transaction_NoStockDiscount	= 1

			LEFT JOIN tbStockControlOrders_Detail tscod			WITH (NOLOCK)
				ON	tscod.comp_id		= tit.comp_id			AND
					tscod.itstkpld_id	= tit.itstkpld_id

			LEFT JOIN tbSalesTerms tst							WITH (NOLOCK)
				ON	tst.comp_id = tct.comp_id AND
					tst.st_id = tct.st_id

			LEFT JOIN tbsysOptionsValues tov2					WITH (NOLOCK)
				ON  tov2.lang_id = @lang_id
				AND tov2.optval_id = isnull(tit.it_IsInternalTransfer,'FALSE')
				AND tov2.optval_class = 1

			LEFT JOIN tbsysCurrency AS tc5						WITH (NOLOCK)
				ON tc5.curr_id = tct.curr_id4Exchange


	WHERE		tit.comp_id		= @comp_id
		--And		(@bra_id		= -1	OR tit.bra_id		= @bra_id)
		--AND		(@stor_id		= -1	OR tit.stor_id		= @stor_id)
		AND		(tct.ct_cd		BETWEEN		@datefrom	AND	@dateto)
		--AND		(tct.ct_date			BETWEEN		@datefrom	AND	@dateto)
		--AND		(@item_id		= -1	OR tit.item_id		= @item_id)
		AND		(@supp_id		= -1	OR tct.supp_id		= @supp_id)
		AND		(@cust_id		= -1	OR tct.cust_id		= @cust_id)
		AND		(@sd_id			= -1	OR tct.sd_id		= @sd_id)
		AND		(@import_id		= -1	OR ti2.import_id	= @import_id)
		AND		CASE
	   				WHEN @type = -1																	THEN 'True'	-- Todos
	   				WHEN @type =  0 AND td.sd_isPurchase = 'False'									THEN 'True'	-- Ventas
	   				WHEN @type =  8 AND tct.sd_id = 350 AND tit.it_IsFastStockAdjustment = 'True'	THEN 'True' -- Ajustes Rápidos de Stock
	   				WHEN @type =  1 AND td.sd_isPurchase = 'True'  AND	tct.supp_id IS NOT NULL		THEN 'True' -- Compras
	   				WHEN @type =  2 AND td.sd_isPurchase = 'True'  AND	tct.supp_id IS     NULL		THEN 'True' -- Ajustes
	   				WHEN @type =  3 AND td.sd_isPurchase = 'True'  AND	tct.supp_id IS     NULL AND tit.it_IsInternalTransfer='True' THEN 'True' -- Transferencias Internas entre Depósitos
	   				WHEN @type =  4 AND td.sd_isPurchase = 'True'  AND
	   									tct.supp_id IS NOT NULL	   and
	   									tct.sd_id IN (101,102,/*124*/130) AND
	   									NOT EXISTS (	SELECT 1
															FROM @tblSuppliers4Transfer tmpt
                                                      		WHERE tct.supp_id = tmpt.supp_id )  AND
                                        tit2.comp_id  IS NULL
                                                      												THEN 'True' -- Compras - Ingresos Sin Transferencias
                    WHEN @type =  5 AND tct.sd_id = 145												THEN 'True' -- Producción de Equipos - Ingresos por Producción
	   				WHEN @type =  6 AND td.sd_isPurchase = 'True'  AND	tct.supp_id IS     NULL AND tit.it_IsInternalTransfer='False' THEN 'True' -- Ajustes sin Transferencias Internas
	   				WHEN @type =  7 AND (
	   										tct.sd_id			IN (101,102,104,121,124,130,145)	AND
	   										IsNull(tit.it_transaction_NoStockDiscount,0) = 0		AND
	   										CASE
												WHEN tct.sd_id = 145 AND tit.it_qty >  0 THEN 1
												WHEN tct.sd_id = 145 AND tit.it_qty <= 0 THEN 0
												ELSE 1
											END	= 1
	   									)															THEN 'True' -- Ingresos a tener en cuenta en Ageing
	   				WHEN @type =  9 AND tit.sitt_id IN (130,131)									THEN 'True' -- Recepción de Armado de PC
	   				WHEN @type = 10 AND tit.sitt_id IN (140,141)									THEN 'True' -- Devolución de Artículo
	   				WHEN @type = 11 AND tit.sitt_id IN (150,151)									THEN 'True' -- Anulación de Articulos en Recepción de Transferencia entre Sucursales
					WHEN @type = 12 AND tit.sitt_id = 91											THEN 'True' -- Ajuste de Stock por Depurado de Pedidos
	   				ELSE 'False'
	   			END	= 'True'
		AND		CASE
					WHEN @serial = '' THEN 'True'
					WHEN tit.it_transaction IN (SELECT it_transaction FROM @tblSerials) THEN 'True'
					ELSE 'False'
				END = 'True'

		ORDER BY	tit.it_transaction



END
GO



