-- Movimientos de Items MANUALES
CREATE PROCEDURE [dbo].[spItemTransactions_getDataByFilters2_Manual]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@datefrom		DATETIME,
	@dateto			DATETIME,
	@stor_id		INT,
	@cust_id		INT,
	@sd_id			INT,
	@serial			VARCHAR(100),
	@import_id		INT,
	@type			INT,
	@user_id		INT

)
AS

BEGIN


	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

-- --------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------
/*
	DECLARE	@comp_id		INT,
			@lang_id		INT,
			@bra_id			INT,
			@item_id		INT,
			@supp_id		INT,
			@datefrom		DATETIME,
			@dateto			DATETIME,
			@sd_id			INT,
			@stor_id		INT,
			@cust_id		INT,
			@serial			VARCHAR(100),
			@import_id		Int,
			@type			INT,
			@user_id		INT



	SELECT	@comp_id   =  1,
			@lang_id   =  2,
			@bra_id	   = 1,
			@item_id   = -1,
			@supp_id   = -1,
			@datefrom  = '2015-01-01',
			@dateto	   = '2999-08-31',
			@sd_id	   = -1,
			@stor_id   = -1,
			@cust_id   = 24454,
			@serial    = '',
			@import_id = -1,
			@type      = -1,
			@user_id   =  1
*/
-- --------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')




	---- -------------------------------------------------------------
	---- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	---- -------------------------------------------------------------
	--DECLARE @tblComplexFilter_Items TABLE (item_id INT NULL UNIQUE CLUSTERED)
	--INSERT INTO @tblComplexFilter_Items
	--	SELECT tcf.sl_id
	--		FROM tbComplexFilter tcf	WITH (NOLOCK)
	--		WHERE	tcf.sl_guid		= @GuidItem     AND
	--				tcf.sl_selected = 'True'
	--IF @@ROWCOUNT = 0
	--	BEGIN
	--		IF @item_id > 0
	--			BEGIN
	--				INSERT INTO @tblComplexFilter_Items(item_id) VALUES (@item_id)
	--			END
	--		ELSE
	--			BEGIN
	--				INSERT INTO @tblComplexFilter_Items(item_id)
	--					SELECT item_id
	--						FROM tbItem ti	WITH (NOLOCK)
	--						WHERE ti.comp_id = @comp_id
	--				--INSERT INTO @tblComplexFilter_Items( item_id) VALUES (NULL)
	--			END
	--	END

	---- -------------------------------------------------------------



	-- --------------------------------------------------------------------
	-- Inserta en la tabla las transacciones correspondientes al numero
	-- de serie informado.
	-- --------------------------------------------------------------------
	DECLARE @tblSerials TABLE (ct_transaction int, it_transaction int)
	IF @serial <> ''
		BEGIN
			INSERT INTO @tblSerials (ct_transaction , it_transaction)
				SELECT	tis.ct_transaction,
						tis.it_transaction
					FROM	tbItemSerials tis				WITH (NOLOCK)
					WHERE	tis.comp_id		= @comp_id
					AND		tis.is_serial	= @serial

			UNION

			SELECT	tits.ct_transaction,
					tits.it_transaction
				FROM	tbItemTransactionSerials	tits	WITH (NOLOCK)
				INNER JOIN tbItemSerials			tis		WITH (NOLOCK)
				ON	tis.comp_id		= tits.comp_id	AND
					tis.is_id		= tits.is_id
			WHERE	tis.comp_id		= @comp_id AND
					tis.is_serial	= @serial
		END
	-- --------------------------------------------------------------------


	DECLARE @tblSuppliers4Transfer AS TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblSuppliers4Transfer( supp_id)
		SELECT distinct tbcsi.supp_id
			FROM tbBranch2Customer4StockImport tbcsi
			WHERE	tbcsi.comp_id = @comp_id AND
					tbcsi.supp_id IS NOT NULL





	DECLARE @bitIsStockPhoto AS BIT
	SET		@bitIsStockPhoto = 'False'
	SELECT	@bitIsStockPhoto = 'True'
		FROM tbStorage ts	WITH (NOLOCK)
		WHERE	ts.comp_id = @comp_id AND
				ts.stor_savePhotoOnITTransaction = 'True'


	-- 05-2016 se saco la vista vwItemTransactions y se puso el PlusOrMinus de manera directa son tbsysDocuments para hacer la busqueda mas rapida.


	SELECT	'' [1],
			'' [2],
			tit.comp_id,
			tit.bra_id,
			tct.ct_cd,
			tb.bra_desc,
			ts.stor_desc,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tit.ct_transaction)[Comprobante],

			tit.it_qty *	CASE
								WHEN tsd.sd_isPurchase='false' AND tsd.sd_isCredit='false' THEN -1
								WHEN tsd.sd_isPurchase='false' AND tsd.sd_isCredit='True'  THEN  1
								WHEN tsd.sd_isPurchase='True'  AND tsd.sd_isCredit='false' THEN  1
								WHEN tsd.sd_isPurchase='True'  AND tsd.sd_isCredit='True'  THEN -1
							END											[it_qty],

			--convert(decimal(19,3),isnull(vit.vw_qty,0)) 				[it_qty],				-- (8)	--MOS 08-2010
			convert(decimal(19,3),isnull(tit.it_storePrevious,0))		[it_storePrevious],		-- (9)
			convert(decimal(19,3),ISNULL(tis.itst_cant,0))				[StockActual],			--(10)
			tov.optval_desc												[sd_desc],
			tsr.stor_desc												[tsrDesc],
			tit.ct_transaction,
			tit.it_transaction,
			IsNull(ti.item_code,'Manual')								[item_code],
			IsNull(ti.item_desc,IsNull(titd.itm_desc,'Item Manual'))	[item_desc],
			IsNull(tbr.brand_desc,'')									[brand_desc],
			tct.ct_date,
			isnull(ti2.import_desc, ' ')								[import_desc],

			case
				When tct.cust_id IS NULL then	isnull(tsupp.supp_name, ' ')
				Else							Isnull(tccust.cust_name, ' ') + CASE
																					WHEN tcb.comp_id IS NULL THEN ''
																					ELSE ' => ' + ISNULL(tcb.custb_name,'')
																				END
			End															[supp_name],
			convert(decimal(19,4),isnull(tit.it_priceWithOutOthers,0))									[it_priceWithOutOthers],
			convert(decimal(19,4),tit.it_price)															[it_price],
			convert(decimal(19,4),isnull(tit.it_price,0) * isnull(

																	tit.it_qty *	CASE
																						WHEN tsd.sd_isPurchase='false' AND tsd.sd_isCredit='false' THEN -1
																						WHEN tsd.sd_isPurchase='false' AND tsd.sd_isCredit='True'  THEN  1
																						WHEN tsd.sd_isPurchase='True'  AND tsd.sd_isCredit='false' THEN  1
																						WHEN tsd.sd_isPurchase='True'  AND tsd.sd_isCredit='True'  THEN -1
																					END

															/*vit.vw_qty*/,0)	)						[Total],
			tc.curr_desc,
			(tu.user_firstname) + ', ' + dbo.fnStrAllTrim(tu.user_lastname)			[User],
			sm.sm_name,
			tit.it_exchangeToBranchCurrency,
			isnull(tit.it_priceOfCost,0)								[it_priceOfCost],
			isnull(tit.it_priceOfCostPP,0)								[it_priceOfCostPP],
			isnull(tit.it_priceOfCostLastPurchase,0)					[it_priceOfCostLastPurchase],
			isnull(tit.it_priceBOfCost,0)								[it_priceBOfCost],
			isnull(tit.it_priceBOfCostPP,0)								[it_priceBOfCostPP],
			isnull(tit.it_priceBOfCostLastPurchase,0)					[it_priceBOfCostLastPurchase],
			isnull(tit.it_OriginalPrice,0)								[it_OriginalPrice],
			tc2.curr_desc,
			isnull(tit.it_exchangeToOriginalPriceCurrency,0)			[it_exchangeToOriginalPriceCurrency],
			isnull(tpl.prli_desc, ' ')									[prli_desc],
			tit.it_isProduction,
			tit.it_isAssociation,
			isnull(tit.it_isAssociationGroup,0)							[it_isAssociationGroup],
			tit.it_cd,
			tit.it_packingInvoicePend,
			isnull(tit.it_order,0)										[it_order] ,
			tit.so_id,
			isnull(tit.it_guarantee,0)									[it_guarantee],
			isnull(tit.it_itemDiscountTotal,0)							[it_itemDiscountTotal],
			isnull(tit.it_totalDiscountTotal,0)							[it_totalDiscountTotal],
			isnull(tit.it_note2,'')										[it_note2],
			isnull(tit.it_CreditInt,0)									[it_CreditInt],
			isnull(tit.it_CreditIntPlus,0)								[it_CreditIntPlus],
			tpc.puco_desc,
			isnull(tit.it_poh_bra_id,0)									[it_poh_bra_id],
			isnull(tit.it_poh_id,0)										[it_poh_id],
			isnull(tit.it_soh_id,0)										[it_soh_id],
			isnull(tit.it_sod_id,0)										[it_sod_id],
			tit.rmah_id,
			tit.rmad_id,
			isnull(tit.it_qty_rma,0)									[it_qty_rma],
			isnull(tit.it_tis_id_aux,0)									[it_tis_id_aux],
			isnull(Convert(Varchar,tct.ct_soh_bra_id),0) + '-' + isnull(Convert(Varchar,tct.ct_soh_id),0) [ct_soh_id],

			CASE @type
					WHEN -1 THEN (SELECT tov.optval_desc FROM tbsysOptionsValues tov WITH (NOLOCK) WHERE tov.lang_id = @lang_id AND tov.optval_class = 110  AND tov.optval_id = 0)
				    ELSE         (SELECT tov.optval_desc FROM tbsysOptionsValues tov WITH (NOLOCK) WHERE tov.lang_id = @lang_id AND tov.optval_class = 317 AND tov.optval_id = @type)
			END															[Type],
			CASE
				WHEN tit.sitt_id = 50 THEN 'Ctrl:' + tscod.itstkpld_noteOfController + CHAR(10) + CHAR(13) + 'Mgr:' + tscod.itstkpld_noteOfManager
				ELSE tctn.ctn_note1
			END															[ctn_note1],
			tov2.optval_desc											[isInternaTransfer],
			tit.it_transaction											[TransactionSTK],
			tit.it_NoStockCheck,
			td.sd_desc													[sd_Description],

			CASE
				WHEN @bitIsStockPhoto = 'False'			THEN	''
														ELSE	dbo.fnItemStoragePhoto(tit.comp_id,tit.it_transaction)
			END															[StoragePhoto],

			-- ATENCION!!!!!!
			-- No poner nada detras de este campo ya que se hacen controles de Count en la pagina 	wfmItemTransaction
			tit.it_transaction											[ID],	-- COUNT - 5,
			tit.sitt_id													[sitt_id],				-- COUNT - 4
			tit.item_id,																		-- COUNT - 3
			convert(bit,CASE
				WHEN tit.sitt_id = 50 THEN  'True'
				ELSE						'False'
			END	)														[it_IsStockControl],	-- COUNT - 2

			CASE
				WHEN tit2.comp_id  IS NULL THEN '*'
				ELSE dbo.fnGetCommercialTransactionDescription(tit2.comp_id,@lang_id,tit2.ct_transaction)
			END															[InvoiceFromPacking]	-- COUNT - 1


	FROM	tbItemTransactions						tit			WITH (NOLOCK)

			--INNER JOIN @tblComplexFilter_Items ttmp
			--	ON ttmp.item_id = tit.item_id



			--INNER JOIN vwItemTransactions			vit			WITH (NOLOCK)
			--		-- esto puede llegar a poner lento a este sp.!
			--	ON	vit.comp_id			= tit.comp_id			-- DE ULTIMA HACER UNA VISTA QUE SOLO DE LA CANTIDAD
			--	AND vit.bra_id			= tit.bra_id			-- YA QUE ES LO UNICO QUE INFORMA ACA REALMENTE
			--	AND vit.ct_transaction	= tit.ct_transaction
			--	AND vit.it_transaction	= tit.it_transaction

			LEFT JOIN tbItemTransactionDetails titd				WITH (NOLOCK)

				ON	titd.comp_id		= tit.comp_id
				AND titd.bra_id			= tit.bra_id
				AND titd.ct_transaction	= tit.ct_transaction
				AND titd.it_transaction	= tit.it_transaction

			INNER JOIN tbCommercialTransactions		tct			WITH (NOLOCK)

				ON  tct.comp_id			= tit.comp_id
				AND tct.ct_transaction	= tit.ct_transaction

			INNER JOIN tbsysDocuments tsd					WITH (NOLOCK)
				ON tsd.sd_id = tct.sd_id



			-------------------------------------------------------------
			----para mostrar usuario de despacho
			--LEFT JOIN tbItemTransactionsDelivery			titdel		WITH (NOLOCK)
			--ON titdel.comp_id		 = tit.comp_id			AND
			--   titdel.it_transaction = tit.it_transaction

			--LEFT JOIN tbUser								tuitdel		WITH (NOLOCK)
			--ON tuitdel.[user_id]	 = titdel.[user_id]
			-------------------------------------------------------------

			INNER  JOIN tbsysOptionsValues tov
				ON	tov.lang_id			= @lang_id	AND
					tov.optval_class	= 950		AND
					tov.optval_id		= tit.sitt_id

			LEFT JOIN tbstorage tsr
				ON	tsr.comp_id = tit.comp_id AND
					tsr.stor_id = tit.stor_id_related4BranchTransfer


			LEFT JOIN tbSalesman sm
				ON	sm.comp_id	= tct.comp_id AND
					sm.sm_id	= tct.sm_id

			LEFT JOIN tbCommercialTransactionNotes	tctn		WITH (NOLOCK)

				ON  tctn.comp_id		= tct.comp_id
				AND tctn.bra_id			= tct.bra_id
				AND tctn.ct_transaction = tct.ct_transaction

			LEFT JOIN tbSupplier					tsupp		WITH (NOLOCK)

				ON  tsupp.comp_id		= tct.comp_id
				AND tsupp.supp_id		= tct.supp_id

			LEFT Join tbCustomer					tccust		WITH (NOLOCK)

				ON  tccust.comp_id		= tct.comp_id
				AND tccust.cust_id		= tct.cust_id

			LEFT JOIN tbCustomerBranch tcb						WITH (NOLOCK)
				ON	tcb.cb_id	= tct.cb_id		AND
					tcb.cust_id = tct.cust_id	AND
					tcb.comp_id = tct.comp_id

			LEFT JOIN tbItem						ti			WITH (NOLOCK)

				ON	ti.comp_id			= tit.comp_id
				AND ti.item_id			= tit.item_id


			LEFT JOIN tbBrand tbr
				ON	tbr.comp_id			= ti.comp_id AND
					tbr.brand_id			= ti.brand_id

			LEFT JOIN tbItemStorage tis							WITH (NOLOCK)

				ON		tis.comp_id = tit.comp_id
					AND tis.stor_id = tit.stor_id
					AND tis.item_id = tit.item_id

			LEFT JOIN tbsysCurrency					tc			WITH (NOLOCK)

				ON	tc.curr_id			= tit.curr_id

			LEFT JOIN tbsysCurrency					tc2
				WITH (NOLOCK)
				ON	tc2.curr_id			= tit.it_OriginalPriceCurrency

			INNER Join tbBranch						tb			-- LEFT
				WITH (NOLOCK)
				On	TB.comp_id			= tit.comp_id
				And tb.bra_id			= tit.bra_id

			LEFT JOIN tbStorage						ts
				WITH (NOLOCK)
				on  ts.comp_id			= tit.comp_id
				AND ts.stor_id			= tit.stor_id

			LEFT JOIN tbPriceList					tpl
				WITH (NOLOCK)
				ON  tpl.comp_id			= tit.comp_id
				AND tpl.prli_id			= tit.prli_id

			LEFT JOIN tbPurchaseConcept				tpc
				WITH (NOLOCK)
				ON  tpc.comp_id			= tit.comp_id
				AND Tpc.puco_id			= tit.puco_id

			LEFT JOIN tbsysDocuments				td
				WITH (NOLOCK)
				ON	td.sd_id			= tct.sd_id

			LEFT JOIN tbImportDetail				tid
				WITH (NOLOCK)
				ON  tid.comp_id			= tit.comp_id
				AND tid.ct_transaction	= tit.ct_transaction

			LEFT JOIN tbImport						ti2
				WITH (NOLOCK)
				ON  ti2.comp_id			= tid.comp_id
				AND ti2.import_id		= tid.import_id

			LEFT JOIN tbUser tu
				WITH (NOLOCK)
				ON tu.[user_id] = tct.[user_id]

			LEFT JOIN tbsysOptionsValues tov2
				WITH (NOLOCK)
				ON  tov2.lang_id = @lang_id
				AND tov2.optval_id = isnull(tit.it_IsInternalTransfer,'FALSE')
				AND tov2.optval_class = 1

			INNER JOIN  tbUsers4BranchFilter		vubf
				WITH (NOLOCK)
				ON  vubf.comp_id		= tit.comp_id
				AND vubf.bra_id			= tit.bra_id
				AND vubf.[user_id]		= @user_id

			LEFT JOIN tbItemTransactions tit2
				WITH (NOLOCK)
				ON	tit2.comp_id						= tit.comp_id					AND
					tit2.it_transaction					= tit.it_transaction_original	AND
					tit.it_transaction_NoStockDiscount	= 1

			LEFT JOIN tbStockControlOrders_Detail tscod
				ON	tscod.comp_id = tit.comp_id			AND
					tscod.itstkpld_id = tit.itstkpld_id

	WHERE		tit.comp_id		= @comp_id
		And		(@bra_id		= -1	OR tit.bra_id		= @bra_id)
		AND     tit.item_id IS NULL
		AND tit.item_idfromPreInvoice IS  NULL	-- MOS 01-2024  (para que NO traiga los de fc anticipada)
		--AND		(@stor_id		= -1	OR tit.stor_id		= @stor_id)
		AND		(tct.ct_cd		BETWEEN		@datefrom	AND	@dateto)
		--AND		(tct.ct_date			BETWEEN		@datefrom	AND	@dateto)
		--AND		(@item_id		= -1	OR tit.item_id		= @item_id)
		--AND		(@supp_id		= -1	OR tct.supp_id		= @supp_id)
		AND		(@cust_id		= -1	OR tct.cust_id		= @cust_id)
		AND		(@sd_id			= -1	OR tct.sd_id		= @sd_id)
		AND		(@import_id		= -1	OR ti2.import_id	= @import_id)
		AND		CASE
	   				WHEN @type = -1																	THEN 'True'	-- Todos
	   				WHEN @type =  0 AND td.sd_isPurchase = 'False'									THEN 'True'	-- Ventas
	   				WHEN @type =  8 AND tct.sd_id = 350 AND tit.it_IsFastStockAdjustment = 'True'	THEN 'True' -- Ajustes Rápidos de Stock
	   				WHEN @type =  1 AND td.sd_isPurchase = 'True'  AND	tct.supp_id IS NOT NULL		THEN 'True' -- Compras
	   				WHEN @type =  2 AND td.sd_isPurchase = 'True'  AND	tct.supp_id IS     NULL		THEN 'True' -- Ajustes
	   				WHEN @type =  3 AND td.sd_isPurchase = 'True'  AND	tct.supp_id IS     NULL AND tit.it_IsInternalTransfer='True' THEN 'True' -- Transferencias Internas entre Depósitos
	   				WHEN @type =  4 AND td.sd_isPurchase = 'True'  AND
	   									tct.supp_id IS NOT NULL	   and
	   									tct.sd_id IN (101,102,/*124*/130) AND
	   									NOT EXISTS (	SELECT 1
															FROM @tblSuppliers4Transfer tmpt
                                                      		WHERE tct.supp_id = tmpt.supp_id )  AND
                                        tit2.comp_id  IS NULL
                                                      												THEN 'True' -- Compras - Ingresos Sin Transferencias
                    WHEN @type =  5 AND tct.sd_id = 145												THEN 'True' -- Producción de Equipos - Ingresos por Producción
	   				WHEN @type =  6 AND td.sd_isPurchase = 'True'  AND	tct.supp_id IS     NULL AND tit.it_IsInternalTransfer='False' THEN 'True' -- Ajustes sin Transferencias Internas
	   				WHEN @type =  7 AND (
	   										tct.sd_id			IN (101,102,104,121,124,130,145)	AND
	   										IsNull(tit.it_transaction_NoStockDiscount,0) = 0		AND
	   										CASE
												WHEN tct.sd_id = 145 AND tit.it_qty >  0 THEN 1
												WHEN tct.sd_id = 145 AND tit.it_qty <= 0 THEN 0
												ELSE 1
											END	= 1
	   									)															THEN 'True' -- Ingresos a tener en cuenta en Ageing
	   				WHEN @type =  9 AND tit.sitt_id IN (130,131)									THEN 'True' -- Recepción de Armado de PC
	   				WHEN @type = 10 AND tit.sitt_id IN (140,141)									THEN 'True' -- Devolución de Artículo
	   				WHEN @type = 11 AND tit.sitt_id IN (150,151)									THEN 'True' -- Anulación de Articulos en Recepción de Transferencia entre Sucursales

	   				ELSE 'False'
	   			END	= 'True'
		--AND		CASE
		--			WHEN @serial = '' THEN 'True'
		--			WHEN tit.it_transaction IN (SELECT it_transaction FROM @tblSerials) THEN 'True'
		--			ELSE 'False'
		--		END = 'True'

		ORDER BY	tit.it_transaction







END
GO








CREATE PROCEDURE [dbo].[spItemTransactions_getDataById]
(
	@comp_id			INT,
	@lang_id			INT,
	@it_transaction		INT

)
as

/*


declare 	@comp_id		int,
			@it_transaction			int

select 		@comp_id		=1,
			@it_transaction	=6165



*/


	select  *

	FROM tbItemTransactions tit WITH (NOLOCK)

	where		tit.comp_id				=	@comp_id
	and			tit.it_transaction		=	@it_transaction











GO



CREATE procedure [dbo].[spItemTransactions_getDataByPacking]
(
	@comp_id		INT,
	@lang_id		INT,
	@datefrom		DATETIME,
	@dateto			DATETIME,
	@cust_id		INT,
	@option			INT,
	@guid			UNIQUEIDENTIFIER,
	@user_id		INT,
	@bra_id			INT,
	@prof_id		INT
)
AS
-- ==============================================================================================================
-- Author		: MOS
-- Creation Date: 2010-10-12
-- Parte		: Parte 616 ver detalle en wfmPurchasePackingListSelection
-- Description	: Se agrega la opción = 101 (factura de proveedores) que obtiene los items de remitos pendientes
-- ==============================================================================================================


-- Log
-- MOS 04-2024: Para que pasen items en NEGATIVO pedido x GAston y TangoID.   Creo q no molesta pero si lo hiciera, SACARLO




BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'



	-- -----------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------
	/*
	DECLARE @comp_id		INT ,
			@lang_id		INT,
			@datefrom		DATETIME,
			@dateto			DATETIME,
			@cust_id		INT,
			@option			INT,
			@guid			UNIQUEIDENTIFIER,
			@user_id		INT,
			@bra_id			INT,
			@prof_id		INT

	SELECT 	@comp_id		=1,
			@lang_id		=2,
			@cust_id		=8110,
			@datefrom		='1900-01-01',
			@dateto			='2999-12-31',
			@option			=101,
			@guid			='f957a6ca-d6d9-424e-a93b-187a8f7ab14a'
	*/
	-- -----------------------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'true')

	-- Ctrl x Perfil para q traiga de TODAS las sucursales
	DECLARE @bitDisableBranchFilter AS BIT = 'False'
	SELECT  @bitDisableBranchFilter = 'True'
		FROM tbControlProfiles AS tcp1	WITH (NOLOCK)
		WHERE	tcp1.comp_id	= @comp_id	AND
				tcp1.bra_id		= @bra_id	AND
				tcp1.prof_id	= @prof_id	AND
				tcp1.page_id	= 183		AND
				tcp1.ctrl_id	= 6084




	DECLARE @tmpCommTrans TABLE(ct_transaction INT PRIMARY KEY)

	IF @option = 1	-- Si intento traer los Remitos Pendientes de Facturacion.

		BEGIN


			-- -------------------------------------------------------------
			--	Repara algun error de algun REMITO que YA se haya facturado
			-- -------------------------------------------------------------
				--SELECT DISTINCT tit2.it_transaction
				--	INTO #tmpITTransactions
				--	FROM tbItemTransactions				tit				WITH (NOLOCK)
				--	INNER JOIN tbCommercialTransactions tct				WITH (NOLOCK)
				--		ON	tct.comp_id			= tit.comp_id AND
				--			tct.ct_transaction	= tit.ct_transaction
				--	LEFT JOIN tbItemTransactions		tit2			WITH (NOLOCK)
				--		ON	tit2.comp_id		= tit.comp_id AND
				--			tit2.it_transaction = tit.it_transaction_original
				--	LEFT JOIN tbCommercialTransactions	tct2			WITH (NOLOCK)
				--		ON	tct2.comp_id		= tit2.comp_id AND
				--			tct2.ct_transaction = tit2.ct_transaction
				--	WHERE	tct.comp_id = @comp_id					AND
				--			tct.cust_id = @cust_id					AND
				--			tct2.comp_id = @comp_id					AND
				--			tct2.cust_id = @cust_id					AND
				--			tit.it_transaction_original IS NOT NULL AND
				--			tit2.it_packingInvoicePend	= 'True'	AND
				--			tit2.comp_id IS not  NULL				AND
				--			tct.sd_id					= 1			AND
				--			tct2.sd_id					= 2			AND
				--			tit.it_packingInvoiceQTYInvoiced IS NULL			-- SI son de la manera vieja, anterior al 24-05-2019

				-- MOS 09-09-2019  CB, cust:85057, TKT: 7168.  No se porque ya que haciendo lo mismo aca funciona todo correctamente. Se hace esto
				--  para que los que figuran pendientes y la suma de las cantidades ya facturadas hayan igualado a la original queden como liquidados
				SELECT DISTINCT titRM.it_transaction		[it_transaction],
								SUM(tit.it_qty)				[packingInvoiceQTYInvoiced],
								MAX(titrm.it_qty)			[initQTY]
					INTO #tmpITTransactions
					FROM		tbItemTransactions				tit				WITH (NOLOCK)
					INNER JOIN	tbCommercialTransactions		tct				WITH (NOLOCK)
						ON	tct.comp_id				= tit.comp_id		AND
							tct.ct_transaction		= tit.ct_transaction
					INNER JOIN	tbItemTransactions				titRM			WITH (NOLOCK)
						ON	titRM.comp_id			= tit.comp_id		AND
							titRM.it_transaction	= tit.it_transaction_original
					INNER JOIN	tbCommercialTransactions		tctRM			WITH (NOLOCK)
						ON	tctRM.comp_id			= titRM.comp_id		AND
							tctRM.ct_transaction	= titRM.ct_transaction
					WHERE	tct.comp_id					= @comp_id		AND
							tct.cust_id					= @cust_id		AND
							tctRM.comp_id				= @comp_id		AND
							tctRM.cust_id				= @cust_id		AND
							titRM.it_packingInvoicePend	= 'True'		AND
							tct.sd_id					= 1				AND
							tctRM.sd_id					= 2				AND
							ISNULL(tct.ct_isCancelled,'False') = 'False'             AND   -- MOS: 12-2019
							ISNULL(titrm.it_packingInvoiceQTYInvoiced,0) = 0
					GROUP BY tit.it_transaction_original,titRM.it_transaction
					HAVING SUM(tit.it_qty) >= MAX(titrm.it_qty)


				--SELECT * FROM #tmpITTransactions
				IF @@ROWCOUNT > 0
					BEGIN
						UPDATE tbItemTransactions						WITH (ROWLOCK)
							SET it_packingInvoicePend			=
														CASE
															WHEN tmp.packingInvoiceQTYInvoiced >= tmp.initQTY	 THEN 0
															ELSE it_packingInvoicePend
														END,
								it_packingInvoiceQTYInvoiced	= tmp.packingInvoiceQTYInvoiced

							FROM tbItemTransactions				 tit
							INNER JOIN tbcommercialtransactions	 tct	WITH (NOLOCK)
							ON	tct.comp_id			= tit.comp_id AND
								tct.ct_transaction	= tit.ct_transaction
							INNER JOIN #tmpITTransactions tmp
								ON tit.it_transaction = tmp.it_transaction
							WHERE	tct.comp_id = @comp_id AND
									tct.cust_id = @cust_id AND
									tct.sd_id	= 2
					END
				DROP TABLE #tmpITTransactions
			-- -------------------------------------------------------------



			DECLARE @tmpCommTrans1 TABLE(ct_transaction INT PRIMARY KEY)
			INSERT INTO @tmpCommTrans1(ct_transaction)
				SELECT tct.ct_transaction
					FROM tbCommercialTransactions			tct		WITH (NOLOCK)
					WHERE  tct.comp_id			= @comp_id AND
						   tct.cust_id			= @cust_id AND
						   tct.sd_id			= 2		   AND
						   tct.ct_date	between @datefrom  and	@dateto

			SELECT 	' ' [ ],
					it.it_packingInvoiceSelected,
					dbo.fnGetCommercialTransactionDescription(@comp_id, 2, tct.[ct_transaction]) [doc_number],
					tct.ct_date,
					ti.item_code,
					CASE
						WHEN ti.comp_id IS NULL		THEN titd.itm_desc
						WHEN titd.itm_desc <> ''	THEN titd.itm_desc
						ELSE							 ti.item_desc
					END										[item_desc],
					--ISNULL(ti.item_desc,titd.itm_desc),
					it_qty 													[it_qty],
					it_qty - ISNULL(it.it_packingInvoiceQTYInvoiced,0)		[it_qtyPend],
					it_price,
					dbo.fnStrPADL(CONVERT(VARCHAR(12),ISNULL(it.bra_id,0)),4,'0') + '-' + dbo.fnStrPADL(CONVERT(VARCHAR(12),ISNULL(it.it_soh_id,0)),8,'0')	[soh_id],
					tc.curr_desc,
					ts2.stor_desc,
					ts.sm_name,
					it.it_transaction	[ID]

			from	dbo.tbItemTransactions     it		WITH (NOLOCK)

					INNER JOIN @tmpCommTrans1 tmp		-- Fast
						ON tmp.ct_transaction = it.ct_transaction

					LEFT JOIN tbItem ti		WITH (NOLOCK)
						ON	ti.item_id = it.item_id
						AND ti.comp_id = it.comp_id

					INNER JOIN tbsysCurrency					tc		WITH (NOLOCK)
						ON it.curr_id			= tc.curr_id

					INNER JOIN tbCommercialTransactions			tct		WITH (NOLOCK)
					ON		tct.comp_id			= it.comp_id
						AND tct.bra_id			= it.bra_id
						AND tct.ct_transaction	= it.ct_transaction
						--AND tct.sd_id			= 2
						--AND	tct.ct_date	between @datefrom  and	@dateto

					INNER JOIN tbDocumentsFile AS tdf	WITH (NOLOCK)
						ON	tdf.comp_id = tct.comp_id	AND
							tdf.df_id	= tct.df_id


					LEFT JOIN tbSalesman ts		WITH (NOLOCK)
						ON		ts.comp_id	= tct.comp_id
							AND ts.sm_id	= tct.sm_id

					LEFT JOIN tbItemTransactionDetails titd		WITH (NOLOCK)
					ON		titd.comp_id		= it.comp_id
						AND titd.bra_id			= it.bra_id
						AND titd.ct_transaction = it.ct_transaction
						AND titd.it_transaction = it.it_transaction

					LEFT JOIN tbStorage ts2		WITH (NOLOCK)
						ON	ts2.comp_id = it.comp_id AND
							ts2.stor_id = it.stor_id

			where   it.comp_id					= @comp_id
			AND
				CASE	-- MOS 08-2020 x MaxTrend
					WHEN tdf.df_PackingListSelection_allow2TakeFromAllBranches	= 1			THEN 1
					WHEN tct.bra_id												= @bra_id	THEN 1
					WHEN @bitDisableBranchFilter								= 'True'	THEN 1
					ELSE																	     0
				END = 1
				--tct.bra_id					= @bra_id		-- 02-2018: SOLO LA DE LA SUCURSAL QUE ESTA TRABANANDO AHORA !!!
			AND		it.it_packingInvoicePend	= 'true'
			AND     ISNULL(tct.ct_isCancelled,'False') = 'False'      -- MOS: 12-2019
			AND		(it.it_cancelled = 'False'	OR it.it_cancelled IS NULL)

			AND		it.it_transaction NOT IN (SELECT	ttis.it_transaction
	   											  FROM		tbTempItemStock ttis	WITH (NOLOCK)
	   											  WHERE		ttis.tis_guid	= @guid
													AND		NOT ttis.tis_function IS NULL)
			AND     it.it_transaction NOT IN (	SELECT tsod.it_transaction
													FROM tbSaleOrderDetail tsod	WITH (NOLOCK)
			                                  		WHERE	tsod.comp_id		= it.comp_id
			                                  			AND tsod.it_transaction = it.it_transaction)
			-- ----------------
			-- MOS 04-2024: Para que pasen items en NEGATIVO pedido x GAston y TangoID.   Creo q no molesta pero si lo hiciera, SACARLO
			-- ----------------
			--AND		(it.it_qty - ISNULL(it.it_packingInvoiceQTYInvoiced,0)) > 0
			AND		(ABS(it.it_qty) - ABS(ISNULL(it.it_packingInvoiceQTYInvoiced,0))) > 0
			-- ----------------
			ORDER BY it.ct_transaction DESC, it.it_order


		END

	ELSE	IF @option = 3	-- Si intento traer las facturas efectuadas que NO tienen una Nota de Credito relacionada
				BEGIN


					--DECLARE @tmpCommTrans TABLE(ct_transaction INT PRIMARY KEY)
					INSERT INTO @tmpCommTrans(ct_transaction)
						SELECT tct.ct_transaction
							FROM tbCommercialTransactions			tct		WITH (NOLOCK)
							WHERE  tct.comp_id			= @comp_id AND
								   tct.cust_id			= @cust_id AND
								   tct.sd_id			= 1		   AND
								   tct.ct_date	between @datefrom  and	@dateto




					SELECT 	' ' [ ],
							it.it_packingInvoiceSelected,
							dbo.fnGetCommercialTransactionDescription(@comp_id, 2, tct.[ct_transaction]) [doc_number],
							tct.ct_date,
							ti.item_code,
							CASE
								WHEN ti.comp_id IS NULL		THEN titd.itm_desc
								WHEN titd.itm_desc <> ''	THEN titd.itm_desc
								ELSE							 ti.item_desc
							END										[item_desc],
							--isnull(ti.item_desc, titd.itm_desc),
							it.it_qty,
							it.it_price,
							tc.curr_desc,
							ISNULL(tc2.curr_symbolFEx,'') + ':' +	CONVERT(NVARCHAR(30),CONVERT(DECIMAL(19,4),tct.ct_dfExchange))				[strExchange],
							ts2.stor_desc,
							ts.sm_name,
							ISNULL(tst.st_desc,'') + ' / ' + ISNULL(tcclp.ccp_desc,'')															[planDesc],



							-- OJO con poner cosas que va con count-!!
							ISNULL(
							(	SELECT TOP 1  1
							 		FROM tbSaleOrderDetailHistory AS tsodh	WITH (NOLOCK)
							 		WHERE	tsodh.comp_id	= it.comp_id	AND
							 				tsodh.bra_id	= it.bra_id		AND
							 				tsodh.soh_id	= it.it_soh_id	AND
							 				tsodh.sod_id	= it.so_id		AND
											tsodh.sod_isDivided = 'True'),0)																	[wasDivided],	-- Count - 2 -- MOS 07-2023: **fkjnwekfnwekn897234
							it.it_transaction																									[ID]			-- Count - 1

					FROM 	dbo.tbItemTransactions						it		WITH (NOLOCK)

							INNER JOIN @tmpCommTrans tmp		-- Fast
								ON tmp.ct_transaction = it.ct_transaction

							INNER JOIN tbsysCurrency				tc		WITH (NOLOCK)
							ON it.curr_id			= tc.curr_id

							INNER JOIN tbCommercialTransactions			tct	WITH (NOLOCK)
								ON tct.comp_id			= it.comp_id
								AND tct.bra_id			= it.bra_id
								AND tct.ct_transaction	= it.ct_transaction
							--AND tct.sd_id			= 1
							--AND	tct.ct_date	between @datefrom  and	@dateto

							LEFT JOIN tbItem ti				WITH (NOLOCK)
							ON	ti.item_id			= it.item_id
							AND ti.comp_id			= it.comp_id

							LEFT JOIN tbSalesman ts		WITH (NOLOCK)
							ON		ts.comp_id	= tct.comp_id
								AND ts.sm_id	= tct.sm_id


							LEFT JOIN tbItemTransactionDetails titd		WITH (NOLOCK)
							ON titd.comp_id = it.comp_id
							AND titd.bra_id = it.bra_id
							AND titd.ct_transaction = it.ct_transaction
							AND titd.it_transaction = it.it_transaction

							LEFT JOIN tbItemTransactions titAnt		WITH (NOLOCK)
								ON		titAnt.comp_id					= it.comp_id
									AND titAnt.it_transaction_original	= it.it_transaction

							LEFT JOIN tbStorage ts2		WITH (NOLOCK)
								ON	ts2.comp_id = it.comp_id AND
									ts2.stor_id = it.stor_id

							LEFT JOIN tbsysCurrency AS tc2
								ON tc2.curr_id = tct.curr_id4dfExchange

							LEFT JOIN tbSalesTerms AS tst	WITH (NOLOCK)
								ON tst.comp_id = tct.comp_id AND tst.st_id = tct.st_id

							LEFT JOIN tbCreditCardLoanPlan AS tcclp
								ON	tcclp.comp_id	= tct.comp_id AND
									tcclp.ccp_id	= tct.ccp_id



					WHERE		tct.comp_id				= @comp_id
					AND			(tct.bra_id				= @bra_id OR @bitDisableBranchFilter = 'True')		-- 02-2018: SOLO LA DE LA SUCURSAL QUE ESTA TRABANANDO AHORA !!!
					--AND     tct.cust_id				= @cust_id
					--AND		tct.sd_id				= 1
					AND		(it.it_cancelled = 'False'	OR it.it_cancelled IS NULL)

					AND		it.it_transaction NOT IN (SELECT	ttis.it_transaction
	   													  FROM		tbTempItemStock ttis	WITH (NOLOCK)
	   													  WHERE		ttis.tis_guid	= @guid
															AND		NOT ttis.tis_function IS NULL)
					AND     titAnt.comp_id IS NULL		-- (Que no se h Procesado antes.!) (Poner un indice x este campo si se pone lentoo!!!!)
					AND     it.it_transaction NOT IN (	SELECT tsod.it_transaction
															FROM tbSaleOrderDetail tsod	WITH (NOLOCK)
	                                  						WHERE	tsod.comp_id		= it.comp_id
	                                  							AND tsod.it_transaction = it.it_transaction)
					ORDER BY tmp.ct_transaction DESC,it.it_order

				END

	ELSE	IF @option = 4	-- Si intento traer las NC efectuadas que NO tienen una Nota de Debito relacionada
				BEGIN


					--DECLARE @tmpCommTrans TABLE(ct_transaction INT PRIMARY KEY)
					INSERT INTO @tmpCommTrans(ct_transaction)
						SELECT tct.ct_transaction
							FROM tbCommercialTransactions			tct		WITH (NOLOCK)
							WHERE  tct.comp_id			= @comp_id AND
								   tct.cust_id			= @cust_id AND
								   tct.sd_id			IN (1,3)   AND
								   tct.ct_date	between @datefrom  and	@dateto




					SELECT 	' ' [ ],
							it.it_packingInvoiceSelected,
							dbo.fnGetCommercialTransactionDescription(@comp_id, 2, tct.[ct_transaction]) [doc_number],
							tct.ct_date,
							ti.item_code,
							CASE
								WHEN ti.comp_id IS NULL		THEN titd.itm_desc
								WHEN titd.itm_desc <> ''	THEN titd.itm_desc
								ELSE							 ti.item_desc
							END										[item_desc],
							--isnull(ti.item_desc, titd.itm_desc),
							it.it_qty,
							it.it_price,
							tc.curr_desc,
							ISNULL(tc2.curr_symbolFEx,'') + ':' +	CONVERT(NVARCHAR(30),CONVERT(DECIMAL(19,4),tct.ct_dfExchange))				[strExchange],
							ts2.stor_desc,
							ts.sm_name,
							it.it_transaction	[ID]

					FROM 	dbo.tbItemTransactions						it		WITH (NOLOCK)

							INNER JOIN @tmpCommTrans tmp		-- Fast
								ON tmp.ct_transaction = it.ct_transaction

							INNER JOIN tbsysCurrency				tc		WITH (NOLOCK)
							ON it.curr_id			= tc.curr_id

							INNER JOIN tbCommercialTransactions			tct	WITH (NOLOCK)
								ON tct.comp_id			= it.comp_id
								AND tct.bra_id			= it.bra_id
								AND tct.ct_transaction	= it.ct_transaction
							--AND tct.sd_id			= 1
							--AND	tct.ct_date	between @datefrom  and	@dateto

							LEFT JOIN tbItem ti				WITH (NOLOCK)
							ON	ti.item_id			= it.item_id
							AND ti.comp_id			= it.comp_id

							LEFT JOIN tbSalesman ts		WITH (NOLOCK)
							ON		ts.comp_id	= tct.comp_id
								AND ts.sm_id	= tct.sm_id


							LEFT JOIN tbItemTransactionDetails titd		WITH (NOLOCK)
							ON titd.comp_id = it.comp_id
							AND titd.bra_id = it.bra_id
							AND titd.ct_transaction = it.ct_transaction
							AND titd.it_transaction = it.it_transaction

							LEFT JOIN tbItemTransactions titAnt		WITH (NOLOCK)
								ON		titAnt.comp_id					= it.comp_id
									AND titAnt.it_transaction_original	= it.it_transaction

							LEFT JOIN tbStorage ts2		WITH (NOLOCK)
								ON	ts2.comp_id = it.comp_id AND
									ts2.stor_id = it.stor_id

							LEFT JOIN tbsysCurrency AS tc2
								ON tc2.curr_id = tct.curr_id4dfExchange



					WHERE		tct.comp_id				= @comp_id
					AND			(tct.bra_id				= @bra_id OR @bitDisableBranchFilter = 'True')		-- 02-2018: SOLO LA DE LA SUCURSAL QUE ESTA TRABANANDO AHORA !!!
					--AND     tct.cust_id				= @cust_id
					--AND		tct.sd_id				= 1
					AND		(it.it_cancelled = 'False'	OR it.it_cancelled IS NULL)

					AND		it.it_transaction NOT IN (SELECT	ttis.it_transaction
	   													  FROM		tbTempItemStock ttis	WITH (NOLOCK)
	   													  WHERE		ttis.tis_guid	= @guid
															AND		NOT ttis.tis_function IS NULL)
					AND     titAnt.comp_id IS NULL		-- (Que no se h Procesado antes.!) (Poner un indice x este campo si se pone lentoo!!!!)
					AND     it.it_transaction NOT IN (	SELECT tsod.it_transaction
															FROM tbSaleOrderDetail tsod	WITH (NOLOCK)
	                                  						WHERE	tsod.comp_id		= it.comp_id
	                                  							AND tsod.it_transaction = it.it_transaction)
					ORDER BY tmp.ct_transaction DESC,it.it_order

				END



		ELSE	IF @option = 101	-- Si traigo los remitos pendientes de una Compra a ser ingresados a una Factura.-
					BEGIN

						DECLARE @bra_purchaseDocs_selectPLFromAnyBranch AS BIT = 'False'
						SELECT	@bra_purchaseDocs_selectPLFromAnyBranch = ISNULL(bra_purchaseDocs_selectPLFromAnyBranch,'False')
							FROM tbBranch tb	WITH (NOLOCK)
							WHERE 	tb.comp_id		= @comp_id AND
									tb.bra_id		= @bra_id


						SELECT 	' '					[ ],
								' '					[ ],
								ISNULL(it.it_packingInvoiceSelected,'false')
													[it_packingInvoiceSelected],

								dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.[ct_transaction])
													[doc_number],
								tct.ct_date,

								ti.item_code,
								ISNULL(ti.item_desc,titd.itm_desc),
								it_qty,
								it_price,
								tc.curr_desc,
								--it.ct_transaction,
								tct.ct_cd			[FechaRecepcion],
								it.it_transaction	[ID]

						FROM 	dbo.tbItemTransactions						it		WITH (NOLOCK)



								LEFT JOIN tbItem							ti		WITH (NOLOCK)
								ON	ti.item_id			= it.item_id
								AND ti.comp_id			= it.comp_id

								INNER JOIN tbsysCurrency					tc		WITH (NOLOCK)
								ON	it.curr_id			= tc.curr_id

								INNER JOIN tbCommercialTransactions			tct		WITH (NOLOCK)
								ON	tct.comp_id			= it.comp_id
								AND tct.bra_id			= it.bra_id
								AND tct.ct_transaction	= it.ct_transaction
								AND tct.sd_id			= 102
								AND	tct.ct_date	between @datefrom and @dateto

								LEFT JOIN tbItemTransactionDetails			titd		WITH (NOLOCK)
								ON	titd.comp_id		= it.comp_id
								AND titd.bra_id			= it.bra_id
								AND titd.ct_transaction = it.ct_transaction
								AND titd.it_transaction = it.it_transaction

						WHERE   it.comp_id									= @comp_id
						AND		(
									tct.bra_id								= @bra_id		-- 02-2018: SOLO LA DE LA SUCURSAL QUE ESTA TRABANANDO AHORA !!!
									OR
									@bra_purchaseDocs_selectPLFromAnyBranch = 'True'
								)
						AND     tct.supp_id									= @cust_id
						AND		ISNULL(it.it_packingInvoicePend	,'false')	= 'true'
						AND		ISNULL(it.it_cancelled			,'false')	= 'false'

						AND		it.it_transaction NOT IN (SELECT	ttis.it_transaction
	   														  FROM		tbItemTransactionsTmp ttis	WITH (NOLOCK)
	   														  WHERE		--ttis.comp_id	= @comp_id
																		--AND
																	ttis.tis_guid	= @guid)
						ORDER BY	it.ct_transaction DESC,
									ISNULL(it.it_poh_id,-1),		-- MOS 03-2022 x MF
									ISNULL(it.it_pod_id,-1),		-- MOS 03-2022 x MF
									it.it_order
						--AND		NOT ttis.tis_function IS NULL)
						--AND		isnull(it.it_packingInvoiceSelected,'false') = 'false'
					END

			ELSE	IF @option = 903	-- ' Si es un REMITO. Esto solo sirve para poder remitir varias facturas en un remito pero es solo a nivel informativo, no maneja NADA de stock, etc.
						BEGIN

							SELECT 	' '					[ ],
									ISNULL(tct.ct_isSelected,'false')			[it_packingInvoiceSelected],
									dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.[ct_transaction])
														[doc_number],
									tct.ct_date,
									'null'				[item_code],
									' '					[item_desc],
									1					[it_qty],
									0					[it_price],
									' '					[curr_desc],
									--tit.it_transaction	[ID]
									tct.ct_transaction	[ID]


							FROM tbCommercialTransactions tct		WITH (NOLOCK)


							WHERE   tct.comp_id									= @comp_id
							AND		(tct.bra_id									= @bra_id  OR @bitDisableBranchFilter = 'True')		-- 02-2018: SOLO LA DE LA SUCURSAL QUE ESTA TRABANANDO AHORA !!!
							AND     tct.cust_id									= @cust_id
							AND		tct.ct_date	between @datefrom and @dateto
							AND		tct.sd_id IN (1,4) -- Trae el detalle de las Fc a incluir en el remito
							ORDER BY tct.ct_transaction DESC
							--AND		tct.sd_id = 1
		--					AND		ISNULL(tit.it_packingInvoicePend	,'false')	= 'true'
		--					AND		ISNULL(tit.it_cancelled			,'false')	= 'false'
		--

						END

END
GO








CREATE PROCEDURE [dbo].[spItemTransactions_getDataForItems]
(
	@comp_id				INT,
	@bra_id					INT,
	@ct_transaction			INT,
	@prof_id				INT
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON




	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id				INT,
			@bra_id					INT,
			@ct_transaction			INT
	SELECT	@comp_id				=1,
			@bra_id					=1,
			@ct_transaction			=7614
	*/
	-- -------------------------------------------------------------------------------

	declare	@intCommTransShowCosts as INT
	set @intCommTransShowCosts = 0

	if exists (	SELECT TOP 1 1
					from tbControlProfiles tc		WITH (NOLOCK)
	           		where	tc.page_id	= 15 and
	           				tc.ctrl_id	= 1898 AND
	           				tc.bra_id	= @bra_id AND
	           				tc.prof_id	= @prof_id)
		begin
			set @intCommTransShowCosts = 1
		end




	-- ==========================================================================================================
	-- Ref. #1
	-- recuperamos el sd_id del comprobante correspondiente para saber si es ventas o compras
	DECLARE @sd_id		INT

	SELECT	@sd_id = tct.sd_id
		FROM	tbCommercialTransactions tct		WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id
		--AND		tct.bra_id			= @bra_id
		AND		tct.ct_transaction	= @ct_transaction
		-- SELECT @sd_id
	-- ==========================================================================================================





	IF @sd_id < 100 -- ventas  Ref. #1
		BEGIN
			SELECT		isnull(item.item_code,'')												[item_code],
						isnull(titd.itm_desc,isnull(item.item_desc,''))							[item_desc],
						convert(decimal(18,2),IT.it_qty)										[it_qty],
						convert(decimal(18,2),IT.it_price)										[it_price],
						convert(decimal(18,2),isnull(IT.it_qty * IT.it_price,0))				[itemTotal],
						SC.[curr_symbol],
						CASE	WHEN tct.sd_id IN (101,103,104) THEN tpc.puco_desc
								ELSE ''
						END																					[puco_desc],
						convert(decimal(18,2),isnull(sum(ttm.tm_total),0))									[tax],
						ISNULL(titd.itm_desc1,'')															[itm_desc1],
						ISNULL(titd.itm_desc2,'')															[itm_desc2],
						convert(decimal(18,2),isnull(IT.it_priceOfCost,0))    * @intCommTransShowCosts		[it_priceOfCost],
						convert(decimal(18,2),isnull(IT.it_priceOfCostPP,0))  * @intCommTransShowCosts		[it_priceOfCostPP],
						convert(decimal(18,2),isnull(IT.it_priceBOfCost,0))   * @intCommTransShowCosts		[it_priceBOfCost],
						convert(decimal(18,2),isnull(IT.it_priceBOfCostPP,0)) * @intCommTransShowCosts		[it_priceBOfCostPP],
						convert(decimal(18,2),isnull(it.it_MLCost,0))    * @intCommTransShowCosts			[it_MLCost],
						convert(decimal(18,2),isnull(it.it_MPCost,0))    * @intCommTransShowCosts			[it_MPCost],
						convert(decimal(18,2),isnull(it.it_MECost,0))    * @intCommTransShowCosts			[it_MECost],
						convert(varchar, convert(decimal(18,2),isnull(IT.it_OriginalPrice,0))  * @intCommTransShowCosts) + ' ' + TC.curr_symbol	[it_OriginalPrice],
						ts.stor_desc,
						IsNull(tb.brand_desc,'')			[brand_desc],
						ISNULL(sm.sm_name,'')				[sm_name],
						CASE
							WHEN  tmloh.ML_id IS NOT NULL THEN CONVERT(VARCHAR(20),tmloh.ML_id)
							ELSE ''
						END	+
						CASE
							WHEN  tmloh.ML_id IS NOT NULL AND tmloh2.ML_id IS NOT NULL THEN ' / '
							ELSE ''
						END	+
						CASE
							WHEN  tmloh2.ML_id IS NOT NULL THEN CONVERT(VARCHAR(20),tmloh2.ML_id)
							ELSE ''
						END
						[MeLiOrder]	,
						CASE	-- MOS: 01-2022 para poder ver en la cta cte los relacionados de fc anticipada.
							-- Si es una Fc Anticipada:
							WHEN	tct.sd_id = 1 AND
									tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL	THEN	(
																										SELECT TOP 1 dbo.fnGetCommercialTransactionDescription(tmpPR.comp_id,2,tmpPR.ct_transaction_packingList)	+
																												' / ' + dbo.fnStrPADL(  CONVERT(VARCHAR(15),ISNULL(tmpPR.bra_id,0)), 5, '0') 		+ '-'	+
																													  + dbo.fnStrPADL(  CONVERT(VARCHAR(15),ISNULL(tmpPR.soh_id,0)),8,'0')
																											FROM	dbo.vwCommercialTransactions_preInvoice_PackingListRelation tmpPR		WITH (NOLOCK)
																											WHERE	tmpPR.comp_id					= it.comp_id		AND
																													tmpPR.bra_id					= it.bra_id			AND
																													tmpPR.ct_transaction_preInvoice = it.ct_transaction AND
																													tmpPR.it_transaction_preInvoice = it.it_transaction
																									)
							-- Si es un Remito de Fc Anticipada
							WHEN	tct.sd_id = 2 AND
									tdf.df_SaleOrder_IsInvoiceFirstPacking = 'True'		THEN	(
																									SELECT  TOP 1 dbo.fnGetCommercialTransactionDescription(tmpPR.comp_id,2,tmpPR.ct_transaction_preInvoice)	+
																												' / ' + dbo.fnStrPADL(  CONVERT(VARCHAR(15),ISNULL(tmpPR.bra_id,0)), 5, '0') 	+ '-'	+
																													  + dbo.fnStrPADL(  CONVERT(VARCHAR(15),ISNULL(tmpPR.soh_id,0)),8,'0')
																										FROM	dbo.vwCommercialTransactions_preInvoice_PackingListRelation tmpPR			WITH (NOLOCK)
																										WHERE	tmpPR.comp_id						= it.comp_id			AND
																												tmpPR.bra_id						= it.bra_id				AND
																												tmpPR.ct_transaction_packingList	= it.ct_transaction		AND
																												tmpPR.it_transaction_packingList	= it.it_transaction
																								)
							ELSE																''
						END		[preInvoiceStatus],
						it.it_note1,
						it.it_note2




			FROM 		dbo.tbItemTransactions							IT		WITH (NOLOCK)

						INNER JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
							ON	tct.comp_id			=	IT.comp_id
							AND tct.bra_id			=	IT.bra_id
							AND tct.ct_transaction	=	IT.ct_transaction

						LEFT JOIN tbDocumentsFile AS					tdf		WITH (NOLOCK)
							ON	tdf.comp_id = tct.comp_id AND
								tdf.df_id   = tct.df_id

						LEFT JOIN tbSalesman							sm		WITH (NOLOCK)
							ON	sm.comp_id		= tct.comp_id AND
								sm.sm_id		= tct.sm_id

						left join dbo.tbItem							ITEM		WITH (NOLOCK)
							on  item.comp_id		=	IT.comp_id
							AND item.item_id		=	IT.item_id

						LEFT JOIN	 tbBrand							tb		WITH (NOLOCK)
							ON	tb.comp_id	= item.comp_id AND
								tb.brand_id = item.brand_id

						left join tbItemTransactionDetails				titd		WITH (NOLOCK)
							ON	it.comp_id			=	titd.comp_id
							AND it.bra_id			=	titd.bra_id
							AND it.ct_transaction	=	titd.ct_transaction
							AND it.it_transaction	=	titd.it_transaction

						left join dbo.[tbsysCurrency]					SC		WITH (NOLOCK)
						on	SC.curr_id			=	IT.curr_id

						LEFT JOIN tbPurchaseConcept						tpc		WITH (NOLOCK)
						ON	tpc.puco_id			=	IT.puco_id
						AND tpc.comp_id			=	IT.comp_id

						LEFT JOIN tbTaxMovements						ttm		WITH (NOLOCK)
						ON	ttm.comp_id			=	it.comp_id
						AND ttm.bra_id			=	it.bra_id
						AND ttm.ct_transaction	=	it.ct_transaction
						AND ttm.it_transaction	=	it.it_transaction

						left join tbsysCurrency							tc		WITH (NOLOCK)
						on tc.curr_id = IT.it_OriginalPriceCurrency

						left join tbStorage								ts		WITH (NOLOCK)
						on ts.stor_id			= it.stor_id


						LEFT JOIN tbMercadoLibre_ordersHeader AS tmloh WITH (NOLOCK)
							ON	tmloh.comp_id	= tct.comp_id AND
								tmloh.mlo_id	= tct.mlo_id

						LEFT JOIN tbMercadoLibre_ordersHeader AS tmloh2 WITH (NOLOCK)
							ON	tmloh2.comp_id	= it.comp_id AND
								tmloh2.mlo_id	= it.mlo_id


			WHERE 		IT.comp_id				=	@comp_id
			--AND			IT.bra_id 				=	@bra_id
			AND			IT.ct_transaction		=	@ct_transaction

			GROUP BY	item.item_code,
						item.item_desc, titd.itm_desc,
						IT.it_qty,
						IT.it_price,
						SC.[curr_symbol],
						tct.sd_id,tpc.puco_desc,
						it.it_transaction,
						itm_desc1,
						itm_desc2, --Ref. #1
						IT.it_OriginalPrice,
						TC.curr_symbol,
						IT.it_priceOfCost,
						IT.it_priceOfCostPP,
						IT.it_priceBOfCost,
						IT.it_priceBOfCostPP,
						ts.stor_desc,
						tb.brand_desc,
						sm.sm_name,
						it.it_MLCost,
						it_MPCost,
						it_MECost,
						tmloh.ML_id,
						tmloh2.ML_id,
						df_SaleOrder_InvoiceFirstPacking_df_id,
						df_SaleOrder_IsInvoiceFirstPacking,
						it.comp_id,
						it.bra_id,
						it.ct_transaction,
						it.it_note1,
						it.it_note2

			ORDER BY IT.it_transaction



		END
	ELSE --Ref. #1
		--compras

		BEGIN

			--HDP 20-04-2012
			--ES ESTA OPCIÓN SE REEMPLAZÓ EL UNION POR 2 SELECT QUE CARGAN UNA TEMPORAL,
			--YA QUE AMBOS SELECT DEL UNION TENÍAN UN GROUP BY DIFERENTE
			--Y NO SE COMPORTABA DE MANERA CORRECTA

			DECLARE @tabla_resultado AS TABLE
				(
					item_code		NVARCHAR	(50),
					item_desc		NVARCHAR	(200),
					it_qty			DECIMAL		(18,2),
					it_price		DECIMAL		(18,2),
					itemTotal		DECIMAL		(18,2),
					curr_symbol		NVARCHAR	(10),
					puco_desc		NVARCHAR	(50),
					tax				DECIMAL		(18,2),
					stor_desc		nvarchar	(500),
					ID	INT
				)


			-- =================================================================================================================
			-- Parte: 723
			INSERT INTO @tabla_resultado
				(	item_code,
					item_desc,
					it_qty,
					it_price,
					itemTotal,
					curr_symbol,
					puco_desc,
					tax,
					stor_desc,ID)
			SELECT		isnull(item.item_code,'')									[item_code],
						isnull(item.item_desc,isnull(titd.itm_desc,''))				[item_desc],
						convert(decimal(18,2),IT.it_qty)							[it_qty],
						convert(decimal(18,2),IT.it_price)							[it_price],
						convert(decimal(18,2),isnull(IT.it_qty * IT.it_price,0))	[itemTotal],
						SC.[curr_symbol],
						CASE	WHEN tct.sd_id IN (101,103,104) THEN tpc.puco_desc
								ELSE ''
						END															[puco_desc],
						convert(decimal(18,2),isnull(sum(ttm.tm_total),0))			[tax],
						isnull(ts.stor_desc,'')										[stor_desc],
						IT.it_transaction


			FROM 		dbo.tbItemTransactions							IT		WITH (NOLOCK)

						INNER JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
						ON	tct.comp_id			=	IT.comp_id
						AND tct.bra_id			=	IT.bra_id
						AND tct.ct_transaction	=	IT.ct_transaction

						left join dbo.tbItem							ITEM		WITH (NOLOCK)
						on  item.comp_id		=	IT.comp_id
						AND item.item_id		=	IT.item_id

						left join tbItemTransactionDetails				titd		WITH (NOLOCK)
						ON	it.comp_id			=	titd.comp_id
						AND it.bra_id			=	titd.bra_id
						AND it.ct_transaction	=	titd.ct_transaction
						AND it.it_transaction	=	titd.it_transaction

						left join dbo.[tbsysCurrency]					SC		WITH (NOLOCK)
						on	SC.curr_id			=	IT.curr_id

						LEFT JOIN tbPurchaseConcept						tpc		WITH (NOLOCK)
						ON	tpc.puco_id			=	IT.puco_id
						AND tpc.comp_id			=	IT.comp_id

						LEFT JOIN tbTaxMovements						ttm		WITH (NOLOCK)
						ON	ttm.comp_id			=	it.comp_id
						AND ttm.bra_id			=	it.bra_id
						AND ttm.ct_transaction	=	it.ct_transaction
						AND ttm.it_transaction	=	it.it_transaction

						left join tbStorage								ts		WITH (NOLOCK)
						on ts.stor_id			= it.stor_id


			WHERE 		IT.comp_id				=	@comp_id
			--AND			IT.bra_id 				=	@bra_id
			AND			IT.ct_transaction		=	@ct_transaction

			GROUP BY	item.item_code,
						item.item_desc, titd.itm_desc,
						IT.it_qty,
						IT.it_price,
						SC.[curr_symbol],
						tct.sd_id,tpc.puco_desc,
						it.it_transaction,
						stor_desc --Ref. #1

			--SELECT * FROM @tabla_resultado
			--UNION
			-- =================================================================================================================

			INSERT INTO @tabla_resultado
				(	item_code,
					item_desc,
					it_qty,
					it_price,
					itemTotal,
					curr_symbol,
					puco_desc,
					tax,
					stor_desc,ID)
			SELECT		'',
						isnull(tpcm.pcm_note1,'') + '-' + isnull(tpcm.pcm_note2,'') + '-' + isnull(tpc.puco_desc,'') [item_desc],
						convert(decimal(18,2),1),
						convert(decimal(18,2),tpcm.pcm_total),
						convert(decimal(18,2),tpcm.pcm_total),
						SC.[curr_symbol],
						tpc.puco_desc,
						convert(decimal(18,2),isnull(sum(ttm.tm_total),0))		[tax],
						'',
						tpcm.ct_transaction

			FROM		tbPurchaseConceptMovements						tpcm		WITH (NOLOCK)

						LEFT JOIN dbo.[tbsysCurrency]					SC		WITH (NOLOCK)
						on	SC.curr_id			=	tpcm.curr_id

						LEFT JOIN tbPurchaseConcept						tpc		WITH (NOLOCK)
						ON tpc.comp_id			=	tpcm.comp_id
						AND tpc.puco_id			=	tpcm.puco_id

						LEFT JOIN tbTaxMovements						ttm		WITH (NOLOCK)
						ON	ttm.comp_id			=	tpcm.comp_id
						AND ttm.bra_id			=	tpcm.bra_id
						AND ttm.pcm_id			=	tpcm.pcm_id

			WHERE 		tpcm.comp_id			=	@comp_id
			--AND			tpcm.bra_id 			=	@bra_id
			AND			tpcm.ct_transaction		=	@ct_transaction

			GROUP BY	tpcm.pcm_note1,
						tpcm.pcm_note2,
						tpc.puco_desc,
						tpcm.pcm_total,
						SC.[curr_symbol],
						tpc.puco_desc,tpcm.ct_transaction


			SELECT * FROM @tabla_resultado ORDER BY ID


		END


END
GO







