CREATE PROCEDURE [dbo].[spItemTransactions_getDataPending]

(

	@comp_id	  INT,
	@lang_id	  INT,
	@bra_id		  INT,
	@is_purchase  INT,
	@item_id	  INT,
	@datefrom	  DATETIME,
	@dateto		  DATETIME,
	@cust_id	  INT,
	@ct_docNumber NVARCHAR(50),
	@user_id	  INT


)

AS


BEGIN




	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


-- -----------------------------------------------------------
-- Testing
-- -----------------------------------------------------------
/*
	DECLARE

		@comp_id	 INT,
		@lang_id	 INT,
		@bra_id		 INT,
		@is_purchase INT,
		@item_id	 INT,
		@dateto		 DATETIME,
		@datefrom	 DATETIME,
		@cust_id	 INT,
		@ct_docNumber NVARCHAR(50)



	SELECT

		@comp_id	 = 1,
		@lang_id	 = 2,
		@bra_id		 =-1,
		@is_purchase =-1,
		@item_id	 =-1,
		@datefrom	 ='2000-01-01',
		@dateto		 ='2010-12-31',
		@cust_id	 = -1,
		@ct_docNumber = 0


	*/
-- -----------------------------------------------------------


	set @datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set @dateto   = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	SELECT
			' ' [ ],
			td.sd_desc,
			tb.bra_desc,
			CASE
			    WHEN	tit.item_id IS NULL	THEN '* ->' + ISNULL(titd.itm_desc,'')
			    ELSE	ti.item_desc
			END																					[item_desc],
			ISNULL(CONVERT(VARCHAR, tct.ct_date,103),'')										[ct_date],
			tc.cust_name,
		   dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[ct_docNumber],
		   tit.it_qty,
		   tit.it_qty - ISNULL(tit.it_packingInvoiceQTYInvoiced,0)								[it_qtyPend],
			CONVERT(VARCHAR,TIT.ct_transaction) + '-' +
			CONVERT(VARCHAR,tit.it_transaction) [ID]


		FROM tbItemTransactions tit

		LEFT JOIN tbItemTransactionDetails titd
			ON	titd.comp_id		= tit.comp_id			AND
				titd.bra_id			= tit.bra_id			AND
				titd.ct_transaction = tit.ct_transaction	AND
				titd.it_transaction = tit.it_transaction

		LEFT JOIN tbItem	 			ti
		ON  ti.item_id			= tit.item_id
		AND ti.comp_id			= tit.comp_id


		INNER JOIN tbCommercialTransactions tct
		ON tct.comp_id	= tit.comp_id
		AND tct.bra_id	= tit.bra_id
		AND tct.ct_transaction = tit.ct_transaction


		INNER JOIN tbsysDocuments td
		ON  td.sd_id = tct.sd_id
		AND td.sd_isPackingList = 'True'


		INNER JOIN tbCustomer tc
		ON  tc.comp_id  = tct.comp_id
		AND tc.cust_id = tct.cust_id


		INNER JOIN tbBranch tb
		ON  tb.comp_id = tit.comp_id
		AND tb.bra_id  = tit.bra_id


		INNER join tbUsers4BranchFilter					vubf
			ON  vubf.comp_id			= tct.comp_id
			AND vubf.bra_id				= tct.bra_id
			AND vubf.[user_id]			= @user_id

		WHERE	tit.comp_id = @comp_id
		AND		tit.it_packingInvoicePend = 'True'

		AND   (@bra_id  =   -1  OR tb.bra_id   = @bra_id)
		AND	  (@item_id =   -1  OR tit.item_id = @item_id)
		AND   (
			  (@ct_docNumber = 0) OR
			  ( tct.ct_docNumber IS NOT NULL  AND tct.ct_docNumber = @ct_docNumber)
	   		  )
		AND   (@cust_id =   -1  OR tc.cust_id  = @cust_id)
		AND   (tit.it_cd BETWEEN @datefrom AND @dateto)
		AND   (
				@is_purchase = -1 OR
				(@is_purchase =  0 AND td.sd_isPurchase = convert(bit,@is_purchase))  OR
				(@is_purchase =  1 AND td.sd_isPurchase = convert(bit,@is_purchase))
			  )





END
GO



CREATE PROCEDURE [dbo].[spItemTransactions_GetExtendedWarrantyItem]
(
	@comp_id		INT,
	@bra_id			INT,
	@ct_transaction	INT
)
AS

BEGIN

	SET NOCOUNT ON

	SELECT  tit.comp_id,
			tit.it_transaction,
			tit.it_transaction_originalEW,
			tit.item_id,
			ti.df_id4EW
		FROM tbItemTransactions tit							WITH (NOLOCK)
		INNER JOIN tbitem	ti
			ON	ti.comp_id = tit.comp_id AND
				ti.item_id = tit.item_id
		WHERE	tit.comp_id			= @comp_id				AND
				tit.bra_id			= @bra_id				AND
				tit.ct_transaction	= @ct_transaction		AND
				tit.it_transaction_originalEW IS NOT NULL	AND
				tit.item_id IS NOT NULL





END
GO



CREATE PROCEDURE [dbo].[spItemTransactions_GetItemInGuaranteeByIt_Transaction]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@it_transaction	INT
)
AS
	SET NOCOUNT ON
		BEGIN

			-- ---------------------------------------------
			-- TESTING
			-- ---------------------------------------------
			/*
				DECLARE
					@comp_id			INT,
					@it_transaction		INT

				SELECT
					@comp_id			= 1,
					@it_transaction		= 9680
			*/
			-- ---------------------------------------------

			-- ---------------------------------------------
			-- VARIABLES DE TRABAJO
			-- ---------------------------------------------
				DECLARE
					@ct_transaction				INT,
					@lit_guarantee				INT,
					@lit_guaranteeEW			INT,
					@lct_date					DATETIME,
					@Warranty_Date				DATETIME,
					@Ext_WarrantyDate			DATETIME,
					@lit_transaction_originalEW	INT
			-- ---------------------------------------------

			-- RECUPERAMOS LOS VALORES DE GARANTÍA Y LA FECHA DE LA VENTA
			-- EN BASE AL IT_TRANSACTION, ASÍ COMO TAMBIÉN EL IT_TRANSACTION
			-- REFERIDO A LA GARANTÍA EXTENDIDA
			SELECT
				@ct_transaction				= tit.ct_transaction,
				@lit_guarantee				= tit.it_guarantee,
				@lct_date					= tct.ct_date,
				@lit_transaction_originalEW	= tit.it_transaction_originalEW

			FROM tbItemTransactions							tit
				INNER JOIN tbCommercialTransactions			tct
					ON	tct.comp_id			= tit.comp_id	AND
						tct.bra_id			= tit.bra_id	AND
						tct.ct_transaction = tit.ct_transaction
			WHERE	tit.comp_id			= @comp_id			AND
					tit.it_transaction	= @it_transaction

			-- RECUPERAMOS LA CANTIDAD DE DÍAS DE GARANTÍA EXTENDIDA
			-- EN BASE AL IT_TRANSACTION RECUPERADO EN EL SELECT
			-- SUPERIOR
			SELECT
				@lit_guaranteeEW = tit.it_guarantee
			FROM tbItemTransactions tit
			WHERE	tit.comp_id = @comp_id AND
					tit.it_transaction = @lit_transaction_originalEW

			--SUMAMOS LOS DÍAS DE GARANTÍA A LA FECHA DE VENTA
			SET @lct_date = @lct_date + ISNULL(@lit_guarantee,0)

			-- PRIMERA PREGUNTA, SI LA FECHA ACTUAL ES MENOR A LA FECHA DE VENTA MAS LA GARANTIA
			-- ENTONCES MOSTRAMOS LA LEYENDA "EN GARANTIA"
				IF @lct_date > GETDATE()
					BEGIN
						SELECT
							tut.utexts_desc + ' ' + CONVERT(NVARCHAR(40),@lct_date, 106)
						  FROM tbsysUniqueTexts				tut
						WHERE	tut.lang_id		= @lang_id	AND
								tut.utexts_id	= 30731
					END
				ELSE
					BEGIN
						-- SEGUNDA PREGUNTA, SI LA FECHA ACTUAL ES MENOR A LA FECHA DE VENTA MAS LA GARANTIA + LA GARANTIA EXTENDIDA
						-- ENTONCES MOSTRAMOS LA LEYENDA "EN GARANTIA EXTENDIDA"
						IF @lit_transaction_originalEW IS NOT NULL
							BEGIN
								SET @lct_date = @lct_date + ISNULL(@lit_guaranteeEW,0)
								IF @lct_date > GETDATE()
									BEGIN
										SELECT
											tut.utexts_desc + ' ' + CONVERT(NVARCHAR(40),@lct_date, 106)
										  FROM tbsysUniqueTexts				tut
										WHERE	tut.lang_id		= @lang_id	AND
												tut.utexts_id	= 30732
									END
								ELSE
									-- SINO MOSTRAMOS LA LEYENDA "FUERA DE GARANTIA EXTENDIDA"
									BEGIN
										SELECT
											tut.utexts_desc + ' ' + CONVERT(NVARCHAR(40),@lct_date, 106)
										  FROM tbsysUniqueTexts				tut
										WHERE	tut.lang_id		= @lang_id	AND
												tut.utexts_id	= 30745
									END
							END
						ELSE
							BEGIN
								-- SINO MOSTRAMOS LA LEYENDA "FUERA DE GARANTIA"
								SELECT
									tut.utexts_desc + ' ' + CONVERT(NVARCHAR(40),@lct_date, 106)
								  FROM tbsysUniqueTexts				tut
								WHERE	tut.lang_id		= @lang_id	AND
										tut.utexts_id	= 30733
							END
					END

		END
GO




-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE spItemTransactions_getLastPrice4ItemAndCustomer
	@comp_id AS INT,
	@cust_id AS INT,
	@item_id AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	DECLARE @decPrice AS DECIMAL(19,4)
	DECLARE @intCurrId AS INT

	SELECT @intCurrId = tc.curr_id
	FROM tbCustomer tc WITH (NOLOCK)
	WHERE	tc.comp_id = @comp_id AND
			tc.cust_id = @cust_id



	SELECT TOP 1	@decPrice	= tit.it_price,
					@intCurrId	= tit.curr_id
		FROM tbItemTransactions tit									WITH (NOLOCK)
			INNER JOIN tbCommercialTransactions tct					WITH (NOLOCK)
				ON	tct.comp_id			= tit.comp_id				AND
					tct.ct_transaction	= tit.ct_transaction
		WHERE	tit.comp_id = @comp_id								AND
				tit.item_id = @item_id								AND
				tct.cust_id = @cust_id								AND
				tct.sd_id	= 1
		ORDER BY tit.it_transaction DESC

	SELECT	@decPrice		[price],
			@intCurrId		[curr_id]


END
GO







-- Updated MOS  03-2010
CREATE PROCEDURE [dbo].[spItemTransactions_getLastPrices]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@item_id	INT,
	@cust_id	INT
)
AS

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
		/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@item_id	INT,
			@cust_id	INT
		SELECT
			@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@item_id	=316,
			@cust_id	=8
		*/
-- ------------------------------------------------------



	DECLARE @bitCostPlusTax AS BIT
	SELECT @bitCostPlusTax	= IsNull(tb.bra_SaleOrderPricePlusTax,'False')
		FROM tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id



	SELECT TOP 1 tmp.[Order], tmp.[desc], tmp.it_transaction FROM
	(SELECT		TOP 1
				'1'	[Order],
				dbo.fnSplitPosition(tut.utexts_desc,'|',1) + ' ' + CONVERT(VARCHAR(12),max(tct.ct_date),105)	+ ' - ' +
				' ' + dbo.fnGetCommercialTransactionDescription(tit.comp_id,@lang_id,tit.ct_transaction) + ' ' +
				dbo.fnSplitPosition(tut.utexts_desc,'|',2) + ' ' + --LTRIM(RTRIM(tc.curr_symbol))				+

				CONVERT(VARCHAR,CONVERT(DECIMAL(19,4), (tit.it_price / (ISNULL(tit.it_exchangeToOriginalPriceCurrency,0))) + (
																															CASE
																																WHEN @bitCostPlusTax = 'True' THEN (tit.it_price / (ISNULL(tit.it_exchangeToOriginalPriceCurrency,0))) * IsNull(ttn.tax_percentage,0) / 100
																																ELSE 0
																															END
																															)
									   ) ) + ' ' + tc1.curr_symbol 				 [desc] ,
				tit.it_transaction

		FROM	tbItemTransactions							tit		WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions			tct		WITH (NOLOCK)
				ON tct.comp_id = tit.comp_id
				AND tct.bra_id = tit.bra_id
				AND tct.ct_transaction = tit.ct_transaction

				INNER JOIN tbsysCurrency tc1		WITH (NOLOCK)
					ON tc1.curr_id = tit.it_OriginalPriceCurrency

				INNER JOIN tbsysCurrency					tc		WITH (NOLOCK)
				ON tc.curr_id = tit.curr_id

				INNER JOIN tbBranch							tb		WITH (NOLOCK)
				ON tb.bra_id = @bra_id

				INNER JOIN tbsysUniqueTexts tut		WITH (NOLOCK)
				ON   	tut.lang_id = @lang_id
				AND		tut.utexts_id = 621

				INNER JOIN tbItemCostList ticl		WITH (NOLOCK)
					ON		ticl.comp_id	= @comp_id
						AND ticl.coslis_id	= tb.coslis_id
						AND ticl.item_id	= tit.item_id

				INNER JOIN tbsysCurrency tc2		WITH (NOLOCK)
					ON tc2.curr_id = ticl.curr_id

				left JOIN vwItemTaxesOnlyOneIvaTax	vit		WITH (NOLOCK)
					ON		vit.comp_id = tit.comp_id
						AND vit.item_id = tit.item_id
				LEFT JOIN tbTaxName ttn		WITH (NOLOCK)
					ON		ttn.comp_id = vit.comp_id
						AND ttn.tax_id	= vit.tax_id

		WHERE	tit.comp_id = @comp_id
		AND		tit.item_id = @item_id
		AND		tct.cust_id = @cust_id
		AND		tct.sd_id	= 1				-- Solo Facturas.!


		GROUP BY tc.curr_symbol, tit.it_price, tit.it_priceOfCost, tb.bra_SaleOrderShowCost,  tut.utexts_desc, tit.it_priceOfCostPP,tit.it_transaction,tit.comp_id,tit.ct_transaction,tit.it_exchangeToOriginalPriceCurrency,tc1.curr_symbol,ticl.coslis_price,ticl.coslis_price_aw,tc2.curr_symbol,ttn.tax_percentage
		ORDER BY tit.it_transaction desc
	)  tmp

	UNION

			SELECT 	'2',
					tut.utexts_desc,
					0				[it_transaction]
			FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
			WHERE  	tut.lang_id = @lang_id
					AND tut.utexts_id = 620

			ORDER BY	it_transaction	desc

END
GO


CREATE PROCEDURE [dbo].[spItemTransactions_getLastPrices4Purchase]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@item_id	INT,
	@supp_id	INT,
	@stor_id    INT,
	@user_id	INT,
	@prof_id	INT

)
AS

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
			/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@item_id	INT,
			@supp_id	INT,
			@stor_id    INT,
			@user_id	int
		SELECT
			@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@item_id	=492,
			@supp_id	=8103,
			@stor_id    = -1,@user_id = 1
*/
	-- ------------------------------------------------------


	DECLARE @tmpBranchs TABLE(bra_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchs(bra_id)
		SELECT DISTINCT tucp.bra_id
			FROM tbUserCompanyProfile tucp
			WHERE	tucp.comp_id	= @comp_id AND
					tucp.[user_id]	= @user_id





	DECLARE @bitCostPlusTax AS BIT
	SELECT @bitCostPlusTax	= IsNull(tb.bra_SaleOrderPricePlusTax,'False')
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id


	-- -------------------------------------------------------
	-- TEXTOS
	-- -------------------------------------------------------

		DECLARE
			@strDocument	VARCHAR(50),
			@strPriceNoTax	VARCHAR(50),
			@strPriceNoDiscounts	VARCHAR(50),
			@strTaxName		VARCHAR(50),
			@strDiscount1	VARCHAR(50),
			@strDiscount2	VARCHAR(50),
			@strDiscount3	VARCHAR(50),
			@strDiscount4	VARCHAR(50),
			@strSurcharge1	VARCHAR(50),
			@strSurcharge2	VARCHAR(50),
			@strSurcharge3	VARCHAR(50),
			@strSurcharge4	VARCHAR(50),
			@strSuppName	VARCHAR(50)

		SET @strDocument	= ''
		SET @strPriceNoTax	= ''
		SET @strTaxName		= ''
		SET @strDiscount1	= ''
		SET @strDiscount2	= ''
		SET @strDiscount3	= ''
		SET @strDiscount4	= ''
		SET @strSurcharge1	= ''
		SET @strSurcharge2	= ''
		SET @strSurcharge3	= ''
		SET @strSurcharge4	= ''
		SET @strPriceNoDiscounts = ''
		SET @strSuppName	= ''



		SELECT
			@strPriceNoDiscounts = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30890

		SELECT
			@strDocument = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 300027

		SELECT
			@strDiscount1 = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30854

		SELECT
			@strDiscount2 = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30855

		SELECT
			@strDiscount3 = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30856

		SELECT
			@strDiscount4 = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30857

		SELECT
			@strSurcharge1 = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30858

		SELECT
			@strSurcharge2 = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30859

		SELECT
			@strSurcharge3 = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30860

		SELECT
			@strSurcharge4 = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30861

		SELECT
			@strTaxName = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30862

		SELECT
			@strPriceNoTax = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30863

		SELECT
			@strSuppName = tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 400059


	-- -------------------------------------------------------

	DECLARE @viewp_PackingList AS BIT = 'False'
	SELECT  @stor_id =	CASE
	                 	    WHEN tcpprvp.stor_id4LastPurchase IS NOT NULL THEN  tcpprvp.stor_id4LastPurchase
	                 	    ELSE												@stor_id
	                 	END,
	       @viewp_PackingList = 	tcpprvp.viewp_PackingList
		FROM tbCostPricePercentRelation_ViewParameters tcpprvp	WITH (NOLOCK)
			WHERE	tcpprvp.comp_id = @comp_id	AND
					tcpprvp.bra_id	= @bra_id	AND
					tcpprvp.prof_id = @prof_id



	SELECT TOP 1	tmp.[Order],
					tmp.[desc],
					tmp.it_transaction,
					tmp.it_Discount1,
					tmp.it_Discount2,
					tmp.it_Discount3,
					tmp.it_Discount4,
					tmp.it_surcharge1,
					tmp.it_surcharge2,
					tmp.it_surcharge3,
					tmp.it_surcharge4,
					tmp.it_priceWithOutOthers,
					tmp.curr_id ,
					tmp.ct_date,
					tmp.ct_cd
		FROM
		(SELECT		TOP 1
					'1'	[Order],
					dbo.fnSplitPosition(tut.utexts_desc,'|',1) + ' ' + CONVERT(VARCHAR(12),MAX(tct.ct_date),105)				+ ' <BR> ' +
					@strDocument + ' : ' + dbo.fnGetCommercialTransactionDescription(tit.comp_id,@lang_id,tit.ct_transaction)	+ ' <BR> ' +
					@strSuppName + ' : ' + CONVERT(VARCHAR(50),ts.supp_name)													+ ' <BR> ' +
					@strTaxName  + ' ' + ttn.tax_desc																			+ ' <BR> ' +
					dbo.fnSplitPosition(tut.utexts_desc,'|',2) + ' ' +
					CONVERT(VARCHAR,CONVERT(DECIMAL(19,4), tit.it_price  + (
																			CASE
																				WHEN @bitCostPlusTax = 'True' THEN tit.it_price  * ISNULL(ttn.tax_percentage,0) / 100
																				ELSE 0
																			END
																			)
										   ) ) + ' ' + tc1.curr_symbol 			+
									   																							+ ' <BR> ' +



					@strPriceNoDiscounts + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,4), tit.it_priceWithOutOthers)) + ' ' + tc1.curr_symbol + ' <BR> ' +


					@strPriceNoTax + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,4), tit.it_price)) + ' ' + tc1.curr_symbol												+ ' <BR> ' +
					--DESCUENTOS
					@strDiscount1 + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,4),ISNULL(tit.it_Discount1,0)))															+ '  ' +
					@strDiscount2 + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,4),ISNULL(tit.it_Discount2,0)))															+ '  ' +
					@strDiscount3 + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,4),ISNULL(tit.it_Discount3,0)))															+ '  ' +
					@strDiscount4 + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,4),ISNULL(tit.it_Discount4,0)))															+ ' <BR> ' +

					--RECARGOS
					@strSurcharge1 + ' ' + CONVERt(VARCHAR,CONVERT(DECIMAL(19,4),ISNULL(tit.it_surcharge1,0)))															+ '  ' +
					@strSurcharge2 + ' ' + CONVERt(VARCHAR,CONVERT(DECIMAL(19,4),ISNULL(tit.it_surcharge2,0)))															+ '  ' +
					@strSurcharge3 + ' ' + CONVERt(VARCHAR,CONVERT(DECIMAL(19,4),ISNULL(tit.it_surcharge3,0)))															+ '  ' +
					@strSurcharge4 + ' ' + CONVERt(VARCHAR,CONVERT(DECIMAL(19,4),ISNULL(tit.it_surcharge4,0)))			+ ' <b> WIKI:**5874**  </b>'							[desc] ,
					tit.it_transaction,
					ISNULL(tit.it_Discount1,0)			[it_Discount1],
					ISNULL(tit.it_Discount2,0)			[it_Discount2],
					ISNULL(tit.it_Discount3,0)			[it_Discount3],
					ISNULL(tit.it_Discount4,0)			[it_Discount4],
					ISNULL(tit.it_surcharge1,0)			[it_surcharge1],
					ISNULL(tit.it_surcharge2,0)			[it_surcharge2],
					ISNULL(tit.it_surcharge3,0)			[it_surcharge3],
					ISNULL(tit.it_surcharge4,0)			[it_surcharge4],
					ISNULL(tit.it_priceWithOutOthers,0)	[it_priceWithOutOthers],
					tit.curr_id,
					tct.ct_date,
					tct.ct_cd

			FROM	tbItemTransactions								tit

				INNER JOIN @tmpBranchs tmp66
					ON tmp66.bra_id			= tit.bra_id
				INNER JOIN tbCommercialTransactions					tct
					ON	tct.comp_id			= tit.comp_id			AND
						--tct.bra_id			= tit.bra_id			AND
						tct.ct_transaction	= tit.ct_transaction

				inner join tbUsers4BranchFilter						vubf		WITH (NOLOCK)
					ON  vubf.comp_id		= tct.comp_id
					AND vubf.bra_id			= tct.bra_id
					AND vubf.[user_id]		= @user_id

				INNER JOIN tbSupplier								ts
					ON	ts.comp_id			= tct.comp_id			AND
						ts.supp_id			= tct.supp_id

				INNER JOIN tbsysCurrency							tc1
					ON	tc1.curr_id			= tit.curr_id
				INNER JOIN tbsysCurrency							tc
					ON	tc.curr_id			= tit.curr_id
				INNER JOIN tbBranch									tb
					ON	tb.comp_id			= tit.comp_id			AND
						tb.bra_id			= tit.bra_id
				INNER JOIN tbsysUniqueTexts							tut
					ON  tut.lang_id			= @lang_id				AND
						tut.utexts_id		= 30852
				--LEFT JOIN tbItemCostList							ticl
				--	ON	ticl.comp_id		= @comp_id				AND
				--		ticl.coslis_id		= tb.coslis_id			AND
				--		ticl.item_id		= tit.item_id
				--LEFT JOIN tbsysCurrency							tc2
				--	ON	tc2.curr_id			= ticl.curr_id
				LEFT JOIN vwItemTaxesOnlyOneIvaTax					vit
					ON	vit.comp_id			= tit.comp_id			AND
						vit.item_id			= tit.item_id
				LEFT JOIN tbTaxName									ttn
					ON	ttn.comp_id			= vit.comp_id			AND
						ttn.tax_id			= vit.tax_id
			WHERE	tit.comp_id				= @comp_id				AND
					--tit.bra_id				= @bra_id				AND
					tit.item_id				= @item_id				AND
					( @supp_id = -1 or tct.supp_id				= @supp_id	)			AND
					( @stor_id = -1 or tit.stor_id				= @stor_id	)			AND
					(
						tct.sd_id				= 101
						OR
						(tct.sd_id				= 102 AND @viewp_PackingList = 'True')
					)


			GROUP BY	tc.curr_symbol,
						tit.it_price,
						tit.it_priceOfCost,
						tb.bra_SaleOrderShowCost,
						tut.utexts_desc,
						tit.it_priceOfCostPP,
						tit.it_transaction,
						tit.comp_id,
						tit.ct_transaction,
						tit.it_exchangeToOriginalPriceCurrency,
						tc1.curr_symbol,
						--ticl.coslis_price,
						--ticl.coslis_price_aw,
						--tc2.curr_symbol,
						ttn.tax_percentage,
						tit.it_Discount1,
						tit.it_Discount2,
						tit.it_Discount3,
						tit.it_Discount4,
						tit.it_surcharge1,
						tit.it_surcharge2,
						tit.it_surcharge3,
						tit.it_surcharge4,
						ttn.tax_desc,
						tit.it_priceWithOutOthers,
						tit.curr_id,
						tct.ct_date,
						tct.ct_cd,
						ts.supp_name

			ORDER BY tit.it_transaction desc
		)  tmp

		UNION

				SELECT 	'2',
						tut.utexts_desc,
						0				[it_transaction],
						0				[it_Discount1],
						0				[it_Discount2],
						0				[it_Discount3],
						0				[it_Discount4],
						0				[it_surcharge1],
						0				[it_surcharge2],
						0				[it_surcharge3],
						0				[it_surcharge4],
						0				[it_priceWithOutOthers],
						1				[curr_id],
						GETDATE()       [tct.ct_date],
						GETDATE()		[ct_cd]
				FROM	tbsysUniqueTexts tut
				WHERE  	tut.lang_id = @lang_id
						AND tut.utexts_id = 30853

				ORDER BY	it_transaction	desc

END
GO




