CREATE Procedure [dbo].[spItemTransactions_getReportOfMarkupandProfit]
(
		@comp_id			INT,
		@lang_id			INT,
		@page_id			INT,

		@cat_id				INT,
		@subcat_id			INT,
		@brand_id			INT,
		@pres_id			INT,
		@country_id			INT,
		@state_id			INT,
		@item_id			INT,
		@supp_id			INT,
		@sm_id				INT,
		@prli_id			INT,
		@stor_id			INT,
		@cust_id			INT,
		@ck_id				INT,
		@datefrom			DATETIME,
		@dateto				DATETIME,
		@option_cost		INT,
		@bra_id				INT,
		@user_id			INT,
		@sd_id				INT,
		@ss_id				INT,
		@pricetype			INT,				-- 1 : Importe , 2 : Importe menos intereses
		@guid_item			VARCHAR(50),
		@guid_cust			VARCHAR(50),
		@intBranch4Lang		INT,
		@intReportCurrency	INT				-- -1: Moneda de la Operación , Cualquier otro valor es ID de moneda
)
AS

BEGIN


	-- GA, esto tiene que venir como PARAMETRO indicando -1 si es MOneda de la operación o el ID de la moneda seleccionada
	--DECLARE @intReportCurrency AS INT = -1

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- --------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------
/*
	Declare
			@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@cat_id			int,
			@subcat_id		int,
			@brand_id		int,
			@pres_id		int,
			@country_id		int,
			@state_id		int,
			@item_id		int,
			@supp_id		int,
			@sm_id			int,
			@prli_id		int,
			@stor_id		int,
			@cust_id		int,
			@ck_id			int,
			@datefrom		DATETIME,
			@dateto			DATETIME,
			@option_cost    int,
			@bra_id			int,
			@user_id        INT,
			@sd_id			INT,
			@ss_id			INT,
			@intBranch4Lang	int


	Select
			@comp_id		=1,
			@lang_id		=2,
			@page_id		=10026,

			@cat_id			=-1,
			@subcat_id		=-1,
			@brand_id		=-1,
			@pres_id		=-1,
			@country_id		=-1,
			@state_id		=-1,
			@item_id		=-1,
			@supp_id		=-1,
			@sm_id			=-1,
			@prli_id		=-1,
			@stor_id		=-1,
			@cust_id		=-1,
			@ck_id			=-1,
			@bra_id			= 1,
			@datefrom		='2000-10-01',
			@dateto			='2011-10-31',
			@user_id        = 1,
			@option_cost	= 1,
			@sd_id			= -1,
			@ss_id			= 1
*/

	-- --------------------------------------------------------------------------



	DECLARE @lGuid_Item AS UNIQUEIDENTIFIER

	SET @lGuid_Item = CONVERT(UNIQUEIDENTIFIER,@guid_item)

	DECLARE @lGuid_Cust AS UNIQUEIDENTIFIER

	SET @lGuid_Cust = CONVERT(UNIQUEIDENTIFIER,@guid_cust)


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Item TABLE (item_id INT NULL)
	INSERT INTO @tblComplexFilter_Item
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid_item     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Item
				SELECT ti.item_id
				FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	INSERT INTO @tblComplexFilter_Item(	item_id) VALUES (NULL)
	-- -------------------------------------------------------------

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Customer
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid_Cust     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Customer
				SELECT tc.cust_id
				FROM tbCustomer tc
					WHERE tc.comp_id = @comp_id
		END
	-- -------------------------------------------------------------












	set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	DECLARE @fun_id INT
	SET @fun_id = 1


	SELECT
			IsNull(CA.cat_desc,'Item Manual')		[cat_desc],
			IsNull(SC.subcat_desc,'Item Manual')	[subcat_desc],
			IsNull(BR.brand_desc,'Item Manual')		[brand_desc],
			IsNull(I.item_desc,'Item Manual')		[item_desc],
			ts.sm_id,
			ts.sm_name,
			SUBSTRING(
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, VW.ct_transaction) + ' ' +
				IsNull(substring( titd.itm_desc,1,60),'')
					,1,40)																														[Comprobante], -- Cambiar aca el Ancho
			IT.it_qty * vw.vwToBack																												[it_qty],
			CASE
				when @option_cost = 1			THEN (
														CASE
															WHEN @intReportCurrency = -1  THEN IT.it_priceOfCost
															ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceOfCost,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
														END					* IT.it_qty * vw.vwToBack)
				else								 (	CASE
															WHEN @intReportCurrency = -1  THEN IT.it_priceBOfCost
															ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceBOfCost,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
														END					* IT.it_qty * vw.vwToBack)
			END 																																[Costo],
			dbo.fngetProfit(	CASE
									WHEN @option_cost = 1 THEN	CASE
																	WHEN @intReportCurrency = -1  THEN IT.it_priceOfCost
																	ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceOfCost,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																END
									ELSE						CASE
																	WHEN @intReportCurrency = -1  THEN IT.it_priceBOfCost
																	ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceBOfCost,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																END
			                	END,(	CASE
											WHEN @intReportCurrency = -1  THEN IT.it_price
											ELSE dbo.fnGetExchange2(it.comp_id,IT.it_price,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
										END
			                					-	CASE
			                							WHEN @pricetype = 2 THEN	CASE
																						WHEN @intReportCurrency = -1  THEN IT.it_CreditInt
																						ELSE dbo.fnGetExchange2(it.comp_id,IT.it_CreditInt,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																					END
			                							ELSE 0
			                	                  	END ))																						[Profit],
			dbo.fngetMarkUp(	CASE
									WHEN @option_cost = 1 THEN 	CASE
																	WHEN @intReportCurrency = -1  THEN IT.it_priceOfCost
																	ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceOfCost,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																END
									ELSE						CASE
																	WHEN @intReportCurrency = -1  THEN IT.it_priceBOfCost
																	ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceBOfCost,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																END
			                	END,(	CASE
											WHEN @intReportCurrency = -1  THEN IT.it_price
											ELSE dbo.fnGetExchange2(it.comp_id,IT.it_price,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
										END
			                					-	CASE
			                							WHEN @pricetype = 2 THEN	CASE
																						WHEN @intReportCurrency = -1  THEN IT.it_CreditInt
																						ELSE dbo.fnGetExchange2(it.comp_id,IT.it_CreditInt,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																					END
			                							ELSE 0
			                	                  	END ))																						[MarkUp],
		    (	CASE
					WHEN @option_cost = 1 THEN							CASE
																			WHEN @intReportCurrency = -1  THEN IT.it_priceOfCostPP
																			ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceOfCostPP,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																		END
					ELSE												CASE
																			WHEN @intReportCurrency = -1  THEN IT.it_priceBOfCostPP
																			ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceBOfCostPP,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																		END
		     	END * IT.it_qty *  vw.vwToBack)																									[Costo_PPP],
			dbo.fngetProfit(CASE
								WHEN @option_cost = 1 THEN				CASE
																			WHEN @intReportCurrency = -1  THEN IT.it_priceOfCostPP
																			ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceOfCostPP,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																		END
								ELSE									CASE
																			WHEN @intReportCurrency = -1  THEN IT.it_priceBOfCostPP
																			ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceBOfCostPP,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																		END
			                END ,(	CASE
										WHEN @intReportCurrency = -1  THEN IT.it_price
										ELSE dbo.fnGetExchange2(it.comp_id,IT.it_price,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
									END
											-		CASE
														WHEN @pricetype = 2 THEN	CASE
																						WHEN @intReportCurrency = -1  THEN IT.it_CreditInt
																						ELSE dbo.fnGetExchange2(it.comp_id,IT.it_CreditInt,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																					END
														ELSE 0
			                                   		END ))																						[ProfitPP],
			dbo.fngetMarkUp(	CASE
									WHEN @option_cost = 1 THEN  CASE
																	WHEN @intReportCurrency = -1  THEN IT.it_priceOfCostPP
																	ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceOfCostPP,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																END
									ELSE						CASE
																	WHEN @intReportCurrency = -1  THEN IT.it_priceBOfCostPP
																	ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceBOfCostPP,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																END
			                	END ,(							CASE
																	WHEN @intReportCurrency = -1  THEN IT.it_price
																	ELSE dbo.fnGetExchange2(it.comp_id,IT.it_price,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																END
			                						 -
			                							CASE
			                								WHEN @pricetype = 2 THEN		CASE
																								WHEN @intReportCurrency = -1  THEN IT.it_CreditInt
																								ELSE dbo.fnGetExchange2(it.comp_id,IT.it_CreditInt,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																							END
			                								ELSE 0
			                	                   		END ))																					[MarkUpPP],
			(((					CASE
									WHEN @intReportCurrency = -1  THEN IT.it_price
									ELSE dbo.fnGetExchange2(it.comp_id,IT.it_price,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
								END
							-	CASE
									WHEN @pricetype = 2 THEN						CASE
																						WHEN @intReportCurrency = -1  THEN IT.it_CreditInt
																						ELSE dbo.fnGetExchange2(it.comp_id,IT.it_CreditInt,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																					END
									ELSE 0
			                	END ) * IT.it_qty) - (	CASE
			                								WHEN @option_cost = 1 THEN 	CASE
																							WHEN @intReportCurrency = -1  THEN IT.it_priceOfCost
																							ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceOfCost,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																						END
			                								ELSE  						CASE
																							WHEN @intReportCurrency = -1  THEN IT.it_priceBOfCost
																							ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceBOfCost,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																						END
			                	                      	END * IT.it_qty )) * vw.vwToBack														[Utilidad_Neta],
			(((					CASE
									WHEN @intReportCurrency = -1  THEN IT.it_price
									ELSE dbo.fnGetExchange2(it.comp_id,IT.it_price,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
								END
							-	CASE
									WHEN @pricetype = 2 THEN		CASE
																		WHEN @intReportCurrency = -1  THEN IT.it_CreditInt
																		ELSE dbo.fnGetExchange2(it.comp_id,IT.it_CreditInt,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																	END
									ELSE 0
			                	END ) * IT.it_qty) - (	CASE
			                								WHEN @option_cost = 1 THEN 	CASE
																							WHEN @intReportCurrency = -1  THEN IT.it_priceOfCostPP
																							ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceOfCostPP,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																						END
			                								ELSE						CASE
																							WHEN @intReportCurrency = -1  THEN IT.it_priceBOfCostPP
																							ELSE dbo.fnGetExchange2(it.comp_id,IT.it_priceBOfCostPP,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																						END
			                	                      	END * IT.it_qty )) * vw.vwToBack														[Utilidad_PPP],
			( (					CASE
									WHEN @intReportCurrency = -1  THEN IT.it_price
									ELSE dbo.fnGetExchange2(it.comp_id,IT.it_price,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
								END
							-	CASE
									WHEN @pricetype = 2 THEN			CASE
																			WHEN @intReportCurrency = -1  THEN IT.it_CreditInt
																			ELSE dbo.fnGetExchange2(it.comp_id,IT.it_CreditInt,ct.curr_id_transaction,@intReportCurrency,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
																		END
									ELSE 0
			                	END ) * IT.it_qty * vw.vwToBack)																				[Total], --Parte 535

						CASE
							WHEN @intReportCurrency = -1  THEN 1
							ELSE dbo.fnGetExchange2(it.comp_id,1,@intReportCurrency,ct.curr_id_transaction,ct.curr_id4Exchange,ct.curr_id_transaction,ct.ct_curr_IdExchange,0)
						END			                																							[Exchange],

						ISNULL(i.item_code,'Item Manual')																						[item_code]


	INTO #tmpData


	FROM	dbo.vwItemTransactions_forSalesWithInvoicePackingPending			VW

			INNER join dbo.tbItemTransactions			IT		WITH (NOLOCK)
			on  IT.comp_id			= VW.comp_id
			and IT.bra_id			= VW.bra_id
			and IT.ct_transaction	= VW.ct_transaction
			AND IT.it_transaction	= VW.it_transaction

			INNER JOIN tbBranch						AS	tb		WITH (NOLOCK)
				ON	tb.comp_id		= IT.comp_id AND
					tb.bra_id		= IT.bra_id

			LEFT JOIN tbItemTransactionDetails			titd	WITH (NOLOCK)
			on  titd.comp_id		= VW.comp_id
			and titd.bra_id			= VW.bra_id
			and titd.ct_transaction	= VW.ct_transaction
			AND titd.it_transaction	= VW.it_transaction

			LEFT join dbo.tbItem					I			WITH (NOLOCK)
			on  I.comp_id		= VW.comp_id
			and I.item_id		= IT.item_id

			INNER JOIN @tblComplexFilter_Item		tempItem
			ON (tempItem.item_id					= it.item_id or (tempItem.item_id is null and it.item_id is null ) )

			LEFT join dbo.tbCategory				CA			WITH (NOLOCK)
			on  CA.comp_id		= VW.comp_id
			and CA.cat_id		= I.cat_id

			LEFT join dbo.tbSubCategory				SC			WITH (NOLOCK)
			on  SC.comp_id		= VW.comp_id
			and SC.cat_id		= I.cat_id
			and SC.subcat_id		= I.subcat_id

			LEFT join dbo.tbBrand					BR			WITH (NOLOCK)
			on  BR.comp_id		= VW.comp_id
			and BR.brand_id		= I.brand_id

			LEFT join dbo.tbCommercialTransactions CT			WITH (NOLOCK)
			on  CT.comp_id			= VW.comp_id
			and CT.bra_id			= VW.bra_id
			and CT.ct_transaction	= VW.ct_transaction

			--Parte 535
			inner join tbsysDocuments				td			WITH (NOLOCK)
			ON td.sd_id			    = ct.sd_id

			INNER JOIN tbSalesman ts							WITH (NOLOCK)
				ON ts.comp_id = ct.comp_id
				AND ts.sm_id = ct.sm_id

			INNER join dbo.tbCustomer				CM			WITH (NOLOCK)
			on  CM.comp_id			= VW.comp_id
			and CM.cust_id			= CT.cust_id

			INNER JOIN @tblComplexFilter_Customer		tempCustomer
			ON tempCustomer.cust_id						= CM.cust_id

			INNER JOIN tbUsers4BranchFilter			vubf		WITH (NOLOCK)
			ON vubf.comp_id			= ct.comp_id
			AND vubf.bra_id			= ct.bra_id
			AND vubf.[user_id]		= @user_id

			INNER JOIN tbDocumentsFile				tdf			WITH (NOLOCK)
			ON tdf.comp_id			= CT.comp_id
			AND tdf.bra_id			= CT.bra_id
			AND tdf.df_id			= CT.df_id
			AND isnull(tdf.df_excludereports,'False') = 'False'
			LEFT JOIN	tbSaleSector				tss			WITH (NOLOCK)
			ON	tss.comp_id			= CM.comp_id AND
				tss.ss_id			= CM.ss_id



	WHERE	VW.comp_id		= @comp_id
	and		VW.bra_id		= @bra_id
	and		( @cat_id		= -1 or I.cat_id		= @cat_id)
	and		(@subcat_id		= -1 or I.subcat_id		= @subcat_id)
	and		( @item_id		= -1 or I.item_id		= @item_id)
	and		(@brand_id		= -1 or I.brand_id		= @brand_id)
	and		(@supp_id		= -1 or	I.supp_id		= @supp_id)
	and		(@prli_id		= -1 or	IT.prli_id		= @prli_id)
	and		(@stor_id		= -1 or	IT.stor_id		= @stor_id)
	and		(@pres_id		= -1 or I.pres_id		= @pres_id)
	and		(@cust_id		= -1 or CT.cust_id		= @cust_id)
	and		(@sm_id			= -1 or CT.sm_id		= @sm_id)
	and		(@country_id	= -1 or CT.country_id	= @country_id)
	and		(@state_id		= -1 or CT.state_id		= @state_id)
	and		(@ck_id			= -1 or CM.ck_id		= @ck_id)
	AND      CT.ct_date		between  @datefrom	and @dateto
	--Parte 535
	AND      ct.sd_id IN (1,3,4)	-- Factura, notas de credito y Nota de Débito.-
	--Parte 535
	AND     (
			 (@sd_id = -1 AND td.sd_id IN(1,3,4)) OR
			 (@sd_id =  1 AND td.sd_id IN (1)	) OR
			 (@sd_id =  3 AND td.sd_id IN (3)	) OR
			 (@sd_id =  4 AND td.sd_id IN (4)   ) OR
			 (@sd_id =  5 AND td.sd_id IN (1,3) )
			)
	and		(@ss_id			= -1 or tss.ss_id		= @ss_id)


	ORDER BY cat_desc,
			 subcat_desc,
			 brand_desc,
			 item_desc


	SELECT * FROM
				#tmpData
				ORDER BY cat_desc,
						 subcat_desc,
						 brand_desc,
						 item_desc


	EXEC [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id, @page_id





	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
