						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.country_desc
						FROM	tbsysCountry tc
						WHERE	tc.country_id = @country_id )
			END		[params10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 59
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params11],
			CASE @state_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.state_desc
						FROM	tbsysState ts
						WHERE	ts.country_id = @country_id and ts.state_id =@state_id)
			END		[params12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 103
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params13],
			CASE @item_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ti.item_desc
						FROM	tbItem ti
						WHERE	Ti.comp_id = @comp_id AND ti.item_id= @item_id)
			END		[params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 392
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params15],
			CASE @supp_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.supp_name
						FROM	tbSupplier ts
						WHERE	ts.comp_id = @comp_id AND ts.supp_id= @supp_id)
			END		[params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 172
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params17],
			CASE @sm_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.sm_name
						FROM	tbSalesman ts
						WHERE	ts.comp_id = @comp_id AND ts.sm_id= @sm_id)
			END		[params18],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 109
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params19],
			CASE @prli_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tpl.prli_desc
						FROM	tbPriceList tpl
						WHERE	tpl.comp_id = @comp_id AND tpl.prli_id= @prli_id)
			END		[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 111
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params21],
			CASE @stor_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.stor_desc
						FROM	tbStorage ts
						WHERE	Ts.comp_id = @comp_id AND ts.stor_id= @stor_id)
			END		[params22],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 174
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params23],
			CASE @cust_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cust_name
						FROM	tbCustomer tc
						WHERE	Tc.comp_id = @comp_id AND tc.cust_id= @cust_id)
			END		[params24],

	--		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
	--      	 WHERE t.ctrl_id = 174
	--      	 --AND t.[lang_id] = @lang_id
	--      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params25],
	--		CASE @cust_id WHEN -1 THEN
	--				(SELECT		tut.utexts_desc
	--					FROM	tbsysUniqueTexts tut
	--					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
	--			ELSE
	--				(SELECT		tc.cust_name
	--					FROM	tbCustomer tc
	--					WHERE	Tc.comp_id = @comp_id AND tc.cust_id= @cust_id)
	--		END		[params26],
	--
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 372
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params27],
			CASE @cust_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tck.ck_name
						FROM	tbCustomerKind tck
						WHERE	Tck.comp_id = @comp_id AND tck.ck_id= @ck_id)
			END		[params28],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params29],

      		 @datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom)) 	[params30],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params31],

      		 @dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto)) 	[params32]


				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1455
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params32],
			CASE @option_cost WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc
						FROM tbsysOptionsValues tov
						WHERE tov.optval_class=90 and tov.optval_id=@option_cost and tov.lang_id = @lang_id)
			END		[params33],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 964
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params34],

      		 CASE @sd_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc
						FROM tbsysOptionsValues tov
						WHERE tov.optval_class= 114 and tov.optval_id = @sd_id and tov.lang_id = @lang_id)
			END																				[params35],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 488
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params36],
			CASE @ss_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tss.ss_desc
						FROM	 tbSaleSector tss
						WHERE	tss.comp_id = @comp_id AND tss.ss_id= @ss_id)
			END		[params37],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 5332
  				 --AND t.[lang_id] = @lang_id
  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)							[params38],
  				CASE @pricetype WHEN -1 THEN
  					(SELECT		tut.utexts_desc
  						FROM	tbsysUniqueTexts				tut
  						WHERE	tut.lang_id			= @lang_id
  						AND		tut.utexts_id		= 1)
  				ELSE
  					(SELECT		tov.optval_desc
  						FROM	dbo.tbsysOptionsValues			tov
  						WHERE	tov.optval_class	= 736
  						And		tov.optval_order	= @pricetype
  						AND		tov.lang_id			= @lang_id)
  				END		[params39],

  			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  				 WHERE t.ctrl_id = 106
  				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)							[params40],

			CASE @intReportCurrency WHEN -1 THEN
  					(SELECT		tut.utexts_desc
  						FROM	tbsysUniqueTexts				tut
  						WHERE	tut.lang_id			= @lang_id
  						AND		tut.utexts_id		= 40403)
  				ELSE
  					(SELECT
  						tc.curr_desc
  					 FROM tbsysCurrency tc
  					 WHERE tc.curr_id = @intReportCurrency)
  				END		[params41]


	-- ----------------------------------------------------------------
	-- SubReportes
	-- ----------------------------------------------------------------

	-- Resumen Por subcategoria!

	SELECT	TMP.subcat_desc,
			Sum(TMP.Costo)																[Costo],
			Sum(TMP.Total)																[Total],
			dbo.fngetProfit(sum(TMP.Costo),sum(TMP.Total))								[Profit],
			dbo.fngetMarkUp(sum(TMP.Costo),sum(TMP.Total))								[MarkUp],
			Sum(TMP.Costo_PPP)															[Costo_PPP],
			dbo.fngetProfit(sum(TMP.Costo_PPP),sum(TMP.Total))							[ProfitPP],
			dbo.fngetMarkUp(sum(TMP.Costo_PPP),sum(TMP.Total))							[MarkUpPP],
			(Sum(Total) - Sum(Costo))													[Utilidad_Neta],
			(Sum(Total) - Sum(Costo_PPP))												[Utilidad_PPP]
	FROM #tmpData TMP
	GROUP BY TMP.subcat_desc

	-- Resumen Por marca!

	SELECT	TMP.brand_desc,
			Sum(TMP.Costo)																[Costo],
			Sum(TMP.Total)																[Total],
			dbo.fngetProfit(sum(TMP.Costo),sum(TMP.Total))								[Profit],
			dbo.fngetMarkUp(sum(TMP.Costo),sum(TMP.Total))								[MarkUp],
			Sum(TMP.Costo_PPP)															[Costo_PPP],
			dbo.fngetProfit(sum(TMP.Costo_PPP),sum(TMP.Total))							[ProfitPP],
			dbo.fngetMarkUp(sum(TMP.Costo_PPP),sum(TMP.Total))							[MarkUpPP],
			(Sum(Total) - Sum(Costo))													[Utilidad_Neta],
			(Sum(Total) - Sum(Costo_PPP))												[Utilidad_PPP]
	FROM #tmpData TMP
	GROUP BY TMP.brand_desc

	-- Resumen Por vendedor!

		SELECT	TMP.sm_name,
			Sum(TMP.Costo)																[Costo],
			Sum(TMP.Total)																[Total],
			dbo.fngetProfit(sum(TMP.Costo),sum(TMP.Total))								[Profit],
			dbo.fngetMarkUp(sum(TMP.Costo),sum(TMP.Total))								[MarkUp],
			Sum(TMP.Costo_PPP)															[Costo_PPP],
			dbo.fngetProfit(sum(TMP.Costo_PPP),sum(TMP.Total))							[ProfitPP],
			dbo.fngetMarkUp(sum(TMP.Costo_PPP),sum(TMP.Total))							[MarkUpPP],
			(Sum(Total) - Sum(Costo))													[Utilidad_Neta],
			(Sum(Total) - Sum(Costo_PPP))												[Utilidad_PPP]

	FROM #tmpData TMP
	GROUP BY TMP.sm_name

	drop table #tmpData
	------------------------------------------------------------------


END


