CREATE procedure [dbo].[spItemTransactions_getReportStockMovements]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,

--		@item_desc			varchar(200),
		@pres_id			int,
		@datefrom			datetime,
		@dateto				datetime,
		@item_id			int,
		@supp_id			int,
		@cat_id				int,
		@subcat_id			int,
		@cust_id			int,
		@sm_id				int,
		@brand_id			int,
		@dl_id				int,
		--@ispurchase			bit,
		@stor_id			int,
		@ss_id				int,
		@ck_id				Int,
		@bra_id				Int,
		@user_id			INT,
		@is_purchase        int,
		@guid				VARCHAR(50),--CF DE ITEMS
		@intBranch4Lang		int
)
AS

BEGIN


	SET NOCOUNT ON

	set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



-- -------------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------------
/*
	DECLARE	  @comp_id			int,
			  @lang_id			int,
			  @page_id			int,

			  @item_desc		varchar(200),
			  @pres_id			int,
			  @datefrom			datetime,
			  @dateto			datetime,
			  @item_id			int,
			  @supp_id			int,
			  @cat_id			int,
			  @subcat_id		int,
			  @cust_id			int,
			  @sm_id			int,
			  @brand_id			int,
			  @dl_id			int,
			  @ispurchase		bit,
			  @stor_id			int,
			  @ss_id			int,
			  @ck_id			INT,
			  @bra_id           INT,
			  @user_id          int,
			  @is_purchase      int,
			  @intBranch4Lang	int



	SELECT	@comp_id			=1,
			@lang_id			=2,
			@page_id			=10013,

			@item_desc			='',
			@pres_id			=-1,
			@datefrom			='2000-01-01',
			@dateto				='2010-12-31',
			@item_id			= -1,
			@Supp_id			= -1,
			@cat_id				= -1,
			@subcat_id			= -1,
			@cust_id			= -1,
			@sm_id				= -1,
			@brand_id			= -1,
			@dl_id				= -1,
			@ispurchase			='True',
			@stor_id			= -1,
			@ss_id				=-1,
			@ck_id				=-1,
			@user_id            =1,
			@bra_id             =1,
			@is_purchase        =-1
*/
-- -------------------------------------------------------------------------



	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------


	set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')



	DECLARE @fun_id INT
	SET @fun_id = 1



	SELECT	I.item_code,
			I.item_desc,

			CT.ct_date,

			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,CT.ct_transaction) [DF_SDesc],
			--ov.optval_desc [DF_SDesc],

			'0' [ct_pointOfSale],
			'0' [ct_docNumber],
			--dbo.PadString(ct_pointOfSale,'0',4)	[ct_pointOfSale],
			--dbo.PadString(ct_docNumber,'0',8)		[ct_docNumber],


			--case sd.sd_ispurchase when 'True' then IT.it_qty ELSE IT.it_qty * -1 END [it_qty],
			vit.vw_qty [it_qty],			-- MOS   08-2010

			CASE WHEN  ct.cust_id is NULL then
					isnull(SU.Supp_name,'')
			ELSE	isnull(CU.cust_name,'')

			END	 [cust_name],

			isnull(ST.stor_desc,'')	  [stor_desc],
			D.dl_name,
			P.pres_desc,

			C.cat_desc,
			isnull(SC.subcat_desc,'') [subcat_desc],
			isnull(S.sm_name, '')	  [sm_name],
			B.brand_desc,
			IT.it_priceOfCost		  [it_priceBOfCost],
			IT.it_priceOfCostPP		  [it_priceBOfCostPP],
--			IT.[it_priceBOfCost],
--			IT.[it_priceBOfCostPP],
			IT.it_exchangeToOriginalPriceCurrency,
			PL.prli_desc,
			SS.ss_desc,
			case sd.sd_ispurchase when 'True' then (it.[it_price]*-1)
			  else it.[it_price]
			end [it_price],
			OV1.optval_desc--,
			--CK.ck_name

	FROM	dbo.tbItemTransactions					IT						WITH (NOLOCK)

			INNER JOIN vwItemTransactions vit
				ON		vit.comp_id			= it.comp_id
					AND vit.bra_id			= it.bra_id
					AND vit.ct_transaction	= it.ct_transaction
					AND vit.it_transaction	= it.it_transaction

			inner JOIN tbItem						I						WITH (NOLOCK)
			ON	IT.[comp_id]						=	I.[comp_id]
			AND IT.[item_id]						=	I.[item_id]

			INNER JOIN @tblComplexFilter_Items									tempITEM
			ON tempitem.item_id						= I.item_id

			inner JOIN tbCommercialTransactions		CT						WITH (NOLOCK)
			ON	IT.[comp_id]						=	CT.[comp_id]
			and	IT.[bra_id]							=	CT.[bra_id]
			AND IT.[ct_transaction]					=	CT.[ct_transaction]

			LEFT JOIN [tbPresentation]				P						WITH (NOLOCK)
			ON	P.[comp_id]							=	I.[comp_id]
			AND P.[pres_id]							=	I.[pres_id]

			LEFT JOIN tbSupplier					SU						WITH (NOLOCK)
			ON	SU.[comp_id]						=	IT.[comp_id]
			AND SU.[supp_id]						=	CT.[supp_id]
			AND (@supp_id			= -1 or SU.[supp_id]	=	@supp_id)


			LEFT JOIN tbCustomer					CU						WITH (NOLOCK)
			ON	CU.[comp_id]		=	IT.[comp_id]
			AND CU.[cust_id]		=	CT.[cust_id]
			AND (@cust_id			= -1 or CU.[cust_id]	=	@cust_id)

			LEFT JOIN tbCustomerkind				CK						WITH (NOLOCK)
			ON	CK.[comp_id]						=	CU.[comp_id]
			AND CK.[ck_id]							=	CU.[ck_id]
			AND			(@ck_id				= -1 or CU.[ck_id]		=	@ck_id)


			left JOIN tbSaleSector					SS						WITH (NOLOCK)
			ON	SS.[comp_id]						=	IT.[comp_id]
			AND SS.[ss_id]							=	CU.[ss_id]
			AND			(@ss_id				= -1 or SS.[ss_id]		=	@ss_id)

			LEFT JOIN tbSalesman					S						WITH (NOLOCK)
			ON	CT.[comp_id]						=	S.[comp_id]
			AND CT.[sm_id]							=	S.[sm_id]

			left JOIN tbDelivery					D						WITH (NOLOCK)
			ON	CT.[comp_id]						=	D.[comp_id]
			AND CT.[dl_id]							=	D.[dl_id]

			left join tbStorage						ST						WITH (NOLOCK)
			on  ST.[comp_id]						=	IT.[comp_id]
			and ST.[stor_id]						=	IT.[stor_id]

			inner JOIN tbCategory					C						WITH (NOLOCK)
			ON	I.[comp_id]							=	C.[comp_id]
			AND I.[cat_id]							=	C.[cat_id]

			LEFT JOIN tbSubCategory					SC						WITH (NOLOCK)
			ON	I.[comp_id]							=	SC.[comp_id]
			AND I.[cat_id]							=	SC.[cat_id]
			AND I.[subcat_id]						=	SC.[subcat_id]

			LEFT JOIN tbBrand						B						WITH (NOLOCK)
			ON	B.[comp_id]							=	I.[comp_id]
			AND B.[brand_id]						=	I.[brand_id]

			left join dbo.tbPriceList				PL						WITH (NOLOCK)
			on  IT.[comp_id]						=	PL.[comp_id]
			and IT.[prli_id]						=	PL.[prli_id]

			left join dbo.tbDocumentsFile			DF						WITH (NOLOCK)
			on	ct.comp_id							= ct.comp_id
			and ct.bra_id							= ct.bra_id
			and ct.df_id							= df.df_id

			left join dbo.tbsysDocuments			SD						WITH (NOLOCK)
			on CT.[sd_id]							= SD.[sd_id]

			left join dbo.tbsysOptionsValues		OV						WITH (NOLOCK)
			on  OV.lang_id                          = @lang_id
			and OV.optval_id						= DF.sd_id
			and OV.optval_class						= 6

			left join dbo.tbsysOptionsValues		OV1						WITH (NOLOCK)
			on  OV1.lang_id                         = @lang_id
			and OV1.optval_id						= SD.sd_isPurchase
			and OV1.optval_class					= 9

			inner join tbUsers4BranchFilter vubf							WITH (NOLOCK)
			ON  vubf.comp_id    = IT.comp_id
			AND vubf.bra_id     = IT.bra_id
			AND vubf.[user_id]  = @user_id



	WHERE		 IT.[comp_id]		= @comp_id
	And          IT.bra_id			= @bra_id
	AND			 CT.ct_cd		between		 @datefrom and @dateto -- Se cambio ct_date por ct_cd para el filtro de fechas ,
	   			         		       		                       -- por ende se realizara sobre la fecha de ingreso al sistema y no sobre la fecha del comprobante.
	   			         		       		                       -- 12/09/13 GA
	AND			(@item_id			= -1 or I.[item_id]		 =	@item_id)
	AND			(@pres_id			= -1 or I.[pres_id]		 =	@pres_id)
	AND         (@sm_id				= -1 or CT.[sm_id]		 =	@sm_id)
	AND         (@dl_id				= -1 or CT.[dl_id]		 =	@dl_id)
	AND         (@cat_id			= -1 or I.[cat_id]		 =	@cat_id)
	AND         (@subcat_id			= -1 or I.[subcat_id]	 =	@subcat_id)
	AND			(@brand_id			= -1 or I.[brand_id]	 =	@brand_id)
	AND			(@stor_id			= -1 or IT.[stor_id]	 =	@stor_id)
	AND			(@cust_id			= -1 or CU.[cust_id]	 =	@cust_id)
	AND			(@supp_id			= -1 or SU.[supp_id]     =	@supp_id)
	AND         (@is_purchase       = -1 or SD.sd_isPurchase = convert(bit,@is_purchase))
	AND			(ISNULL(it.it_transaction_NoStockDiscount,'False')			 = 'False')

	order by   it.it_transaction,item_desc, ct.ct_date , ct_docNumber

	exec [spReports_getData3] @comp_id,@intBranch4Lang , @lang_id,@page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	Select

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 177
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )	[params1],
			@datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom))		[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
				 WHERE t.ctrl_id = 384
				 --AND t.[lang_id] = @lang_id
				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )	[params3],
			@dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto))		[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 103
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )			[params5],
			CASE @item_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	ti.item_desc
					 From tbItem ti
					 Where ti.comp_id=@comp_id And ti.item_id=@item_id)
			END		[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 392
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params7],
			CASE @supp_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.supp_name
						FROM	tbSupplier ts
						WHERE	ts.comp_id = @comp_id AND ts.supp_id = @supp_id)
			END		[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 174
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params9],
			CASE @cust_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cust_name
						FROM	tbCustomer tc
						WHERE	Tc.comp_id = @comp_id AND Tc.cust_id= @cust_id)
			END		[params10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 172
      		 --AND t.[lang_id] = @lang_id
    		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params11],
			CASE @sm_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.sm_name
						FROM	tbSalesman ts
						WHERE	ts.comp_id = @comp_id AND ts.sm_id = @sm_id)
			END		[params12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 170
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params13],
			CASE @dl_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		td.dl_name
						FROM	tbDelivery td
						WHERE	td.comp_id = @comp_id AND  td.dl_id= @dl_id)
			END		[params14],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 36
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params15],
			CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cat_desc
						FROM	tbCategory tc
						WHERE	tc.comp_id = @comp_id AND  tc.cat_id= @cat_id)
			END		[params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params17],
			CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
						FROM	tbSubCategory tsc
						WHERE	tsc.comp_id = @comp_id AND  tsc.subcat_id= @subcat_id)
			END		[params18],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 73
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params19],
			CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.brand_desc
						FROM	tbBrand tb
						WHERE	tb.comp_id = @comp_id AND  tb.brand_id= @brand_id)
			END		[params20],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 371
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params21],
			CASE @pres_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tp.pres_desc
						FROM	tbPresentation tp
						WHERE	tp.comp_id = @comp_id AND  tp.pres_id= @pres_id)
			END		[params22],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 111
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params23],
			CASE @stor_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.stor_desc
						FROM	tbStorage ts
						WHERE	Ts.comp_id = @comp_id AND  ts.stor_id= @stor_id)
			END		[params24],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
   		 WHERE t.ctrl_id = 410
   		 --AND t.[lang_id] = @lang_id
   		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params25],
			CASE @is_purchase  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tss.ss_desc
						FROM	tbSaleSector tss
						WHERE	Tss.comp_id = @comp_id AND  tss.ss_id= @ss_id)
			END		[params26],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 372
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params27],
			CASE @ck_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tck.ck_name
						FROM	tbCustomerKind tck
						WHERE	tck.comp_id = @comp_id AND  tck.ck_id= @ck_id)
			END		[params28],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 685
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params29],
			CASE @is_purchase WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
						FROM	tbsysOptionsValues tov
						WHERE	tov.lang_id = @lang_id
						AND     tov.optval_id =@is_purchase
						AND     tov.optval_class = 1001)
			END		[params30]


END
GO








-- ====================================================================================
-- Author:		Gastón Álvarez
-- Create date: 03/28/2011.
-- Parte:		860.
-- Description:	Ver items que se le vendieron al cliente
-- ====================================================================================


CREATE  PROCEDURE [dbo].[spItemTransactions_getSalesByCustomer]
(

	@comp_id	     INT,
	@lang_id	     INT,

    @cust_id	     INT,
    @bra_id          INT,
	@user_id		 INT

)

AS



BEGIN



-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	SET DATEFORMAT 'ymd'

	--------------------------------------------------------------------------------
	-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
	--------------------------------------------------------------------------------
	/*

	DECLARE		@comp_id	     INT,
				@lang_id	     INT,

				@cust_id	     INT,
				@bra_id          INT,
				@user_id		 INT


	SELECT		@comp_id		= 1,
				@lang_id		= 2,


				@cust_id		= 24288,
				@bra_id			= 1,
				@user_id		= 1
	*/
	--------------------------------------------------------------------------------

	SELECT  i.item_code		[item_code],
			i.item_desc		[item_desc],
			tit.it_qty		[it_qty],
			tit.it_price	[it_price],
			sc.curr_symbol	[curr_desc],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)[ct_transaction],
			tct.ct_date [ct_date]


	FROM tbItemTransactions tit


			inner join dbo.tbItem									i
			on  i.comp_id				=	tit.comp_id
			AND i.item_id				=	tit.item_id

			left join dbo.[tbsysCurrency]							sc
			on	sc.curr_id				=	tit.curr_id

			INNER JOIN tbCommercialTransactions						tct
			ON	tct.comp_id				=	tit.comp_id
			AND tct.bra_id				=	tit.bra_id
			AND tct.ct_transaction		=	tit.ct_transaction

			inner JOIN tbCustomer									tc
			ON  tc.comp_id				 = tct.comp_id
			AND tc.cust_id				 = tct.cust_id

			INNER JOIN vwCommercialTransactions_forSalesStats		vctfss
			ON	vctfss.comp_id			= tct.comp_id
			--AND vctfss.bra_id			= tct.bra_id
			AND vctfss.ct_transaction	= tct.ct_transaction

			inner JOIN tbUsers4BranchFilter							vubf
			ON	vubf.comp_id			= tit.comp_id
			AND vubf.bra_id				= tit.bra_id
			AND vubf.[user_id]			= @user_id



	WHERE	tit.comp_id	=	@comp_id
	AND		tct.cust_id	=	@cust_id
	AND		tit.bra_id	=	@bra_id




END
GO






CREATE PROCEDURE [dbo].[spItemTransactions_ImportCalculateCost]
(
		@comp_id			int,
		@lang_id			int,
		@import_id			int,
		@proration			int,
		@curr_id			int,
		@cot				decimal(19,6),
		@coslis_id			INT,
		@guid				UNIQUEIDENTIFIER,
		@proration_manual	DECIMAL(19,6),
		@proration_value	decimal(19,6) OUTPUT,
		@average			DECIMAL(19,6) OUTPUT,
		@add_proration		DECIMAL(19,6) OUTPUT
)
as
set nocount on

set dateformat 'ymd'
/*
declare
		@comp_id			int,
		@lang_id			int,
		@import_id			int,
		@proration			int,
		@curr_id			int,
		@cot				decimal(19,6),
		@coslis_id			INT,
		@guid				UNIQUEIDENTIFIER,
		@proration_value	decimal(19,6),
		@average			DECIMAL(19,6),
		@add_proration		DECIMAL(19,6)

select
		@comp_id			=1,
		@lang_id			=2,
		@import_id			=2,
		@proration			=4,
		@curr_id			=1,
		@cot				=1,
		@coslis_id			=1,
		@guid				='c8c0bfdd-7f1d-467d-8b21-25d5ea0122db'
*/


/***************************************************************************************************************/
/*Recupera aquellos comprobantes que no poseen items y formaran parte del total a Prorratear*/

declare @adds	decimal(19,6)
set		@adds = (
	Select	isnull(sum(dbo.fnGetExchange(@comp_id, CT.ct_total,CT.curr_id_transaction, BR.curr_id,@curr_id,@cot,'False')),0)	[ct_total]

	from	dbo.tbCommercialTransactions					CT

			inner join dbo.tbImportDetail					ID
			on		CT.comp_id			=	ID.comp_id
			and		CT.ct_transaction	=	ID.ct_transaction

			INNER JOIN tbBranch								BR
			ON		CT.comp_id			=	BR.comp_id
			AND		CT.bra_id			=	BR.bra_id

			INNER JOIN vwCommercialTransactions_forPurchase vctfp
			ON	vctfp.comp_id			=	ct.comp_id
			AND vctfp.bra_id			=	ct.bra_id
			AND vctfp.ct_transaction	=	ct.ct_transaction

	where	CT.comp_id = @comp_id
	AND		ID.import_id = @import_id
	and		CT.ct_transaction not in (Select	ct_transaction
										from	dbo.tbItemTransactions IT
										where	comp_id = CT.comp_id))

------------------------------------------------------------------------------
--Preguntar si aca tengo que filtrar por el ct_isAvailableForImport = 'True'--
--Y si en los demas WHERE tambien debo hacerlo								--
------------------------------------------------------------------------------


set	@proration_value = @adds
--select	@proration_value = 1000
--select	@proration_value
/***************************************************************************************************************/



/***************************************************************************************************************/

set @add_proration =
		(SELECT
		isnull(sum(dbo.fnGetExchange(@comp_id, IT.it_price,IT.curr_id, BR.curr_id, @curr_id,@cot,'False')),0) [final_cost]

		from	dbo.tbItemTransactions					IT

		inner join dbo.tbImportDetail					ID
		on	IT.comp_id			=	ID.comp_id
		and	IT.ct_transaction	=	ID.ct_transaction

		inner join dbo.tbItemCostList					IC
		on	IT.comp_id			=	IC.comp_id
		and	IT.item_id			=	IC.item_id

		inner join dbo.tbItem							I
		on	IT.comp_id			=	I.comp_id
		and	IT.item_id			=	I.item_id

		LEFT join	dbo.tbsupplier						S
		on	I.comp_id			=	S.comp_id
		and	I.supp_id			=	S.supp_id

		inner join dbo.tbCommercialTransactions			CT
		on	IT.comp_id			=	CT.comp_id
		and	IT.bra_id			=	CT.bra_id
		and	IT.ct_transaction	=	CT.ct_transaction

		INNER JOIN tbBranch								BR
		ON	 IT.comp_id			=	BR.comp_id
		AND  IT.bra_id			=	BR.bra_id

		INNER JOIN tbItemTransactionsICCTmp				titi
		ON		titi.comp_id			=	it.comp_id
		AND		titi.bra_id				=	it.bra_id
		AND		titi.ct_transaction		=	it.ct_transaction
		AND		titi.it_transaction		=	it.it_transaction
		AND		titi.itt_guid			=	@guid
		AND		titi.itt_include		=	'True'


where	IT.comp_id		=	@comp_id
and		ID.import_id	=	@import_id
and		IC.coslis_id	=	@coslis_id
and		IT.ct_transaction in (Select ct_transaction
							  from dbo.tbImportDetail
							  where comp_id	= @comp_id))


--SELECT @add_proration [add_proration]
/***************************************************************************************************************/




/***************************************************************************************************************/
/*Variable que acumula la suma total de la Item Transactions dependiendo del Prorrateo Seleccionado*/

declare @suma			decimal(19,6)
Select	@suma =
	CASE @proration
		WHEN 1 THEN isnull(sum(IT.it_qty * I.item_weight),0)
		WHEN 2 THEN isnull(sum(IT.it_qty * dbo.fnGetExchange(@comp_id, IT.it_price,IT.curr_id, BR.curr_id, @curr_id,@cot,'False')),0)
		WHEN 3 THEN isnull(sum(IT.it_qty * I.item_volume),0)
		WHEN 4 THEN isnull(sum(IT.it_qty),0)
		ELSE ''
	END

from	dbo.tbItemTransactions							IT

		inner join dbo.tbImportDetail					ID
		on	IT.comp_id			=	ID.comp_id
		and	IT.ct_transaction	=	ID.ct_transaction

		inner join dbo.tbItemCostList					IC
		on	IT.comp_id			=	IC.comp_id
		and	IT.item_id			=	IC.item_id

		inner join dbo.tbItem							I
		on	IT.comp_id			=	I.comp_id
		and	IT.item_id			=	I.item_id

		inner join dbo.tbCommercialTransactions			CT
		on	IT.comp_id			=	CT.comp_id
		and	IT.bra_id			=	CT.bra_id
		and	IT.ct_transaction	=	CT.ct_transaction

		INNER JOIN tbBranch								BR
		ON	 IT.comp_id			=	BR.comp_id
		AND  IT.bra_id			=	BR.bra_id

where	IT.comp_id		=	@comp_id
and		ID.import_id	=	@import_id
and		IC.coslis_id	=	@coslis_id
and		IT.ct_transaction in (Select	ct_transaction
								from	dbo.tbImportDetail
								where	comp_id		=	it.comp_id
								AND		bra_id		=	it.bra_id)
AND		it.it_transaction NOT IN (SELECT titi.it_transaction
								  FROM 	tbItemTransactionsICCTmp titi
								  where	titi.comp_id		=	 it.comp_id
								  AND	titi.bra_id			=	 it.bra_id
								  AND	titi.ct_transaction	=	 it.ct_transaction
								  AND	titi.it_transaction	=	 it.it_transaction
								  AND	titi.itt_include	=	 'True' )
--select @suma [Suma], dbo.fnNoZDiv(@suma)
/***************************************************************************************************************/








/***************************************************************************************************************/
/*Obtenemos la sumatoria de los porcentajes ingresados manualmente por el usuario y la sumatoria del valor
relacionado al @proration de los ítems que tienen porcentajes ingresados manualmente                           */

declare @percentage_applic			decimal(19,6)
declare @quantity_applic			decimal(19,6)

Select	@percentage_applic = isnull(sum(titi.itt_percentage),0),
		@quantity_applic =	CASE @proration
								WHEN 1 THEN isnull(sum(IT.it_qty * I.item_weight),0)
								WHEN 2 THEN isnull(sum(IT.it_qty * dbo.fnGetExchange(@comp_id, IT.it_price,IT.curr_id, BR.curr_id, @curr_id,@cot,'False')),0)
								WHEN 3 THEN isnull(sum(IT.it_qty * I.item_volume),0)
								WHEN 4 THEN isnull(sum(IT.it_qty),0)
								ELSE ''
							END

from	dbo.tbItemTransactions						  IT

		inner join dbo.tbImportDetail					ID
		on	IT.comp_id			=	ID.comp_id
		and	IT.ct_transaction	=	ID.ct_transaction

		inner join dbo.tbItemCostList					IC
		on	IT.comp_id			=	IC.comp_id
		and	IT.item_id			=	IC.item_id
		inner join dbo.tbItem						  I
		on	IT.comp_id			=	I.comp_id
		and	IT.item_id			=	I.item_id

		INNER JOIN tbBranch						      BR
		ON	 IT.comp_id			=	BR.comp_id
		AND  IT.bra_id			=	BR.bra_id

		LEFT JOIN tbItemTransactionsICCTmp				titi
		ON		titi.comp_id			=	it.comp_id
		AND		titi.bra_id				=	it.bra_id
		AND		titi.ct_transaction		=	it.ct_transaction
		AND		titi.it_transaction		=	it.it_transaction
		--AND		titi.itt_include		=	'False'

where	IT.comp_id		=	@comp_id
and		ID.import_id	=	@import_id
and		IC.coslis_id	=	@coslis_id
and		IT.ct_transaction in (Select	ct_transaction
								from	dbo.tbImportDetail
								where	comp_id			=	it.comp_id
								AND		bra_id			=	it.bra_id)
AND		it.it_transaction IN (SELECT titi.it_transaction
							  FROM 	tbItemTransactionsICCTmp titi
							  where	titi.comp_id		=	 it.comp_id
							  AND	titi.bra_id			=	 it.bra_id
							  AND	titi.ct_transaction	=	 it.ct_transaction
							  AND	titi.it_transaction	=	 it.it_transaction
							  AND	titi.itt_include	=	 'False')

--select @percentage_applic [percentage_applic], @quantity_applic [quantity_applic]
/***************************************************************************************************************/










/***************************************************************************************************************/
/*Insert de los porcentajes calculados en la tabla temporal, los mismos podran ser modif por el usuario,*/
/* y en base a las modificaciones se recalcularan los demas porcentajes restantes en la tabla           */

DELETE	dbo.tbItemTransactionsValuesTmp
WHERE	itvt_guid = @guid

INSERT INTO tbItemTransactionsValuesTmp
(
	comp_id,
	bra_id,
	ct_transaction,
	it_transaction,
	itvt_guid,
	itvt_qty,
	itvt_percentage,
	itvt_value
)
Select	it.comp_id,
		it.bra_id,
		it.ct_transaction,
		it.it_transaction,
		@guid,
		CASE @proration
			WHEN 1 THEN isnull(IT.it_qty * I.item_weight,0)
			WHEN 2 THEN isnull(IT.it_qty * dbo.fnGetExchange(@comp_id, IT.it_price,IT.curr_id, BR.curr_id, @curr_id,@cot,'False'),0)
			WHEN 3 THEN isnull(IT.it_qty * I.item_volume,0)
			WHEN 4 THEN isnull(IT.it_qty,0)
			ELSE ''
		END [qty],
		CASE @proration
				WHEN 1 THEN isnull((IT.it_qty * I.item_weight	/ dbo.fnNoZDiv(@suma)),0)*100
				WHEN 2 THEN isnull((IT.it_qty * IT.it_price		/ dbo.fnNoZDiv(@suma)),0)*100
				WHEN 3 THEN isnull((IT.it_qty * I.item_volume	/ dbo.fnNoZDiv(@suma)),0)*100
				WHEN 4 THEN isnull((IT.it_qty					/ dbo.fnNoZDiv(@suma)),0)*100
			ELSE ''
		END [percentage],
		--(IT.it_qty * I.item_weight) [hjhj],
		CASE isnull(titi.itt_percentage,0)
			WHEN 0	then
				CASE @proration
					WHEN 1 THEN isnull(IT.it_qty * I.item_weight,0)
					WHEN 2 THEN isnull(IT.it_qty * dbo.fnGetExchange(@comp_id, IT.it_price,IT.curr_id, BR.curr_id, @curr_id,@cot,'False'),0)
					WHEN 3 THEN isnull(IT.it_qty * I.item_volume,0)
					WHEN 4 THEN isnull(IT.it_qty,0)
					ELSE ''
				END  * ((100 - @percentage_applic) / dbo.fnNoZDiv(@suma - @quantity_applic))
			ELSE titi.itt_percentage
		END [value]

from	dbo.tbItemTransactions							IT

		inner join dbo.tbImportDetail					ID
		on	IT.comp_id			=	ID.comp_id
		and	IT.ct_transaction	=	ID.ct_transaction

		inner join dbo.tbItemCostList					IC
		on	IT.comp_id			=	IC.comp_id
		and	IT.item_id			=	IC.item_id

		inner join dbo.tbItem							I
		on	IT.comp_id			=	I.comp_id
		and	IT.item_id			=	I.item_id

		INNER JOIN tbBranch								BR
		ON	 IT.comp_id			=	BR.comp_id
		AND  IT.bra_id			=	BR.bra_id

		left JOIN tbItemTransactionsICCTmp				titi
		ON		titi.comp_id			=	it.comp_id
		AND		titi.bra_id				=	it.bra_id
		AND		titi.ct_transaction		=	it.ct_transaction
		AND		titi.it_transaction		=	it.it_transaction
		AND		titi.itt_guid			=	@guid
		AND		titi.itt_include		=	'False'

where	IT.comp_id		=	@comp_id
and		ID.import_id	=	@import_id
and		IC.coslis_id	=	@coslis_id
and		IT.ct_transaction in (Select	ct_transaction
							  from	dbo.tbImportDetail
							  where	comp_id	=	it.comp_id
							  AND	bra_id	=	it.bra_id)
AND		it.it_transaction NOT IN (SELECT	titi.it_transaction
   									FROM	tbItemTransactionsICCTmp	titi
									where	titi.comp_id			=	it.comp_id
									AND		titi.bra_id				=	it.bra_id
									AND		titi.ct_transaction		=	it.ct_transaction
									AND		titi.itt_guid			=	@guid
									AND		titi.itt_include		=	'True')

--SELECT * FROM dbo.tbItemTransactionsValuesTmp WHERE itvt_guid =	@guid
/***************************************************************************************************************/
--SELECT SUM(aa.itvt_percentage ) FROM tbItemTransactionsValuesTmp aa WHERE aa.itvt_guid =	@guid
--SELECT SUM(aa.itvt_percentage ) FROM tbItemTransactionsValuesTmp aa
--WHERE aa.itvt_guid = @guid AND aa.itvt_percentage > 1



--SELECT * FROM tbItemTransactionsICCTmp titi
--WHERE titi.itt_guid = @guid




/***************************************************************************************************************/
/*Select que recupera los datos necesarios para cargar en la grilla*/
select
	' ' [ ],
	I.item_code,
	I.item_desc,
	dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, IT.ct_transaction)		[doc_number],
	isnull(substring(S.supp_name,0,30),0)													[supp_name],
	isnull(CT.ct_date,'')																	[ct_date],
	IT.it_qty,
	dbo.fnGetExchange(@comp_id, IT.it_price,IT.curr_id, BR.curr_id, @curr_id,@cot,'False')	[it_price],

	tmp.itvt_value																			[percentage],

	dbo.fnGetExchange(@comp_id, IT.it_price,IT.curr_id, BR.curr_id,@curr_id,@cot,'False') +
	(((@proration_value + @proration_manual + @add_proration)* tmp.itvt_value / 100) / dbo.fnNoZDiv(it.it_qty))					[final_cost],

	CONVERT(VARCHAR,IT.comp_id) + '-' + CONVERT(VARCHAR,IT.bra_id) + '-' +
	CONVERT(VARCHAR,IT.ct_transaction) + '-' + CONVERT(VARCHAR,IT.it_transaction)			[ID]

from	dbo.tbItemTransactions							IT

		inner join dbo.tbCommercialTransactions			CT
		on	IT.comp_id			=	CT.comp_id
		and	IT.bra_id			=	CT.bra_id
		and	IT.ct_transaction	=	CT.ct_transaction

		inner join dbo.tbImportDetail					ID
		on	IT.comp_id			=	ID.comp_id
		and	IT.ct_transaction	=	ID.ct_transaction

		inner join dbo.tbItemCostList					IC
		on	IT.comp_id			=	IC.comp_id
		and	IT.item_id			=	IC.item_id

		inner join dbo.tbItem							I
		on	IT.comp_id			=	I.comp_id
		and	IT.item_id			=	I.item_id

		LEFT join	dbo.tbsupplier						S
		on	S.comp_id			=	CT.comp_id
		and	S.supp_id			=	CT.supp_id

		INNER JOIN tbBranch								BR
		ON	 IT.comp_id			=	BR.comp_id
		AND  IT.bra_id			=	BR.bra_id

		INNER JOIN dbo.tbItemTransactionsValuesTmp 		tmp
		ON	tmp.comp_id			=	it.comp_id
		AND tmp.bra_id			=	it.bra_id
		AND	tmp.ct_transaction	=	it.ct_transaction
		AND	tmp.it_transaction	=	it.it_transaction
		AND	tmp.itvt_guid		=	@guid




where	IT.comp_id		=	@comp_id
and		ID.import_id	=	@import_id
and		IC.coslis_id	=	@coslis_id
and		IT.ct_transaction in (Select ct_transaction
							  from dbo.tbImportDetail
							  where comp_id	= @comp_id)
AND		it.it_transaction NOT IN (SELECT	titi.it_transaction
   									FROM	tbItemTransactionsICCTmp	titi
									where	titi.comp_id			=	it.comp_id
									AND		titi.bra_id				=	it.bra_id
									AND		titi.ct_transaction		=	it.ct_transaction
									AND		titi.itt_guid			=	@guid
									AND		titi.itt_include		=	'True')

order by IT.ct_transaction, I.item_code, doc_number, ct_date, item_desc
/***************************************************************************************************************/










/***************************************************************************************************************/
/*Recordar que si todos los INNER JOIN del Subquery de arriba y la condicion misma (WHERE sufren modificaciones
* el UPDATE que sigue a continuacion debera ser modificado ya que tanto INNERS como CONDICION son identicas*/


/*Actualiza el campo PRICE de la tabla tbItemTransactionsValuesTmp */

UPDATE tbItemTransactionsValuesTmp

SET	tbItemTransactionsValuesTmp.itvt_price = dbo.fnGetExchange(@comp_id, IT.it_price,IT.curr_id, BR.curr_id,@curr_id,@cot,'False') +
		(((@proration_value + @proration_manual + @add_proration) * tmp.itvt_value / 100) / dbo.fnNoZDiv(it.it_qty))

from	tbItemTransactionsValuesTmp 		tmp

		inner join dbo.tbItemTransactions							IT
		ON	tmp.comp_id			=	it.comp_id
		AND tmp.bra_id			=	it.bra_id
		AND	tmp.ct_transaction	=	it.ct_transaction
		AND	tmp.it_transaction	=	it.it_transaction

		inner join dbo.tbImportDetail					ID
		on	IT.comp_id			=	ID.comp_id
		and	IT.ct_transaction	=	ID.ct_transaction

		inner join dbo.tbItemCostList					IC
		on	IT.comp_id			=	IC.comp_id
		and	IT.item_id			=	IC.item_id

		inner join dbo.tbItem							I
		on	IT.comp_id			=	I.comp_id
		and	IT.item_id			=	I.item_id

		LEFT join	dbo.tbsupplier						S
		on	I.comp_id			=	S.comp_id
		and	I.supp_id			=	S.supp_id

		inner join dbo.tbCommercialTransactions			CT
		on	IT.comp_id			=	CT.comp_id
		and	IT.bra_id			=	CT.bra_id
		and	IT.ct_transaction	=	CT.ct_transaction

		INNER JOIN tbBranch								BR
		ON	 IT.comp_id			=	BR.comp_id
		AND  IT.bra_id			=	BR.bra_id

where	IT.comp_id		=	@comp_id
AND		tmp.itvt_guid	=	@guid
and		ID.import_id	=	@import_id
and		IC.coslis_id	=	@coslis_id
and		IT.ct_transaction in (Select ct_transaction
							  from dbo.tbImportDetail
							  where comp_id	= @comp_id)
AND		it.it_transaction NOT IN (SELECT	titi.it_transaction
   									FROM	tbItemTransactionsICCTmp	titi
									where	titi.comp_id			=	it.comp_id
									AND		titi.bra_id				=	it.bra_id
									AND		titi.ct_transaction		=	it.ct_transaction
									AND		titi.itt_guid			=	@guid
									AND		titi.itt_include		=	'True')


--SELECT * FROM tbItemTransactionsValuesTmp
/***************************************************************************************************************/









/***************************************************************************************************************/
/*Select que recupera la sumatoria de los porcentajes del prorrateo y la devuelve en el footer de la grilla*/

DECLARE	@avg		DECIMAL(19,6)

SELECT	@avg = isnull(sum(tmp.itvt_value),0)

FROM	dbo.tbItemTransactionsValuesTmp 		tmp

WHERE	tmp.itvt_guid	= @guid


SET @average = round(@avg,2)
--SELECT @average
/***************************************************************************************************************/
GO



