CREATE PROCEDURE [dbo].[spItemTransactions_InsertData]
	(
		@comp_id				as int,
		@bra_id					as int,
		@ct_transaction			as int,
		@curr_id				as int,
		@forcedExchangeCurrency as int,
		@forcedExchange			as decimal(35,15),
		@purchaseExchange		as bit,
		@tis_guid			    as uniqueidentifier,
		@it_packingInvoicePend  as bit,
		@ret_Identity			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
	)
AS
BEGIN
	SET NOCOUNT ON;

-- --------------------------------------------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------------------------------------------
/*
	DECLARE @comp_id				as int,
			@bra_id					as int,
			@ct_transaction			as int,
			@curr_id				as int,
			@forcedExchangeCurrency as int,
			@forcedExchange			as decimal(19,6),
			@purchaseExchange		as bit,
			@tis_guid			    as uniqueidentifier,
			@it_packingInvoicePend  as bit,
			@ret_Identity			as int			,
			@ret_ErrorCode			as int			,
			@ret_ErrorDescription	as varchar(200)

	SELECT @comp_id				=1,
			@bra_id					=1,
			@ct_transaction			=3603,
			@curr_id				=1,
			@forcedExchangeCurrency =2,
			@forcedExchange			=1,
			@purchaseExchange		='false',
			@tis_guid			    ='0d868870-ee1f-49e8-bbe1-138a8307674c',
			@it_packingInvoicePend  ='false'

*/
-- --------------------------------------------------------------------------------------------------------


		-- --------------------------------------------------------------------------------------------------------
		-- Evitar Bloqueo de Interprocesos - CONSULTAR a Aquitecto
		-- --------------------------------------------------------------------------------------------------------
		SET LOCK_TIMEOUT 15000			-- 10 segundos
		SET DEADLOCK_PRIORITY HIGH		-- Tomar en cuenta para ULTIMA Opcion de Eliminación
		-- --------------------------------------------------------------------------------------------------------


		Set @ret_Identity			= 0
		Set @ret_ErrorCode			= 0
		Set @ret_ErrorDescription	= ''


		DECLARE @intTranCounter AS INT = @@TRANCOUNT;
		IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT_905		-- MOS 06-2020
		--SAVE TRANSACTION traPROTECT_905
		--BEGIN TRANSACTION

		BEGIN TRY

		-- OJO, Asignarlos
		Declare @it_cd							as datetime
		Declare @it_pointOfSale					as int
		Declare @sd_id							as int
		Declare @it_order						as int
		Declare @it_priceOfCost					as decimal(19,6)
		Declare @tmpCurr_Id						as int
		Declare @it_priceOfCostLastPurchase		as decimal(19,6)
		Declare @it_priceOfCostPP				as decimal(19,6)
		Declare @it_priceBOfCost				as decimal(19,6)
		Declare @it_priceBOfCostPP				as decimal(19,6)
		Declare @it_priceBOfCostLastPurchase	as decimal(19,6)
		Declare @it_OriginalPrice				as decimal(19,6)
		Declare @it_OriginalPriceCurrency		as decimal(35,15)
		Declare @it_exchangeToOriginalPriceCurrency as
												   decimal(35,15)
		DECLARE @it_exchangeToBranchCurrency    AS DECIMAL(35,15)
		Declare @it_storePrevious				as decimal(19,6)
		Declare @byor_id						as int
		Declare @it_guarantee					as INT
		Declare @it_guarantee4PCConfig			as INT


		DECLARE @coslis_id						AS INT
		DECLARE @coslis_idB						AS INT

		DECLARE @TMPcoslis_id					AS INT
		DECLARE @TMPcoslis_idB					AS INT
		DECLARE @intCounterDelivery				AS INT

		DECLARE @ta_id							AS INT
		DECLARE @intCounter						AS INT
		DECLARE @sod_MLCost						AS DECIMAL(19,4)	 = 0
		DECLARE @sod_MPCost						AS DECIMAL(19,4)	 = 0
		DECLARE @sod_MECost						AS DECIMAL(19,4)	 = 0
		DECLARE @ws_price						AS DECIMAL(25,10)
		DECLARE @ws_curr_id						AS INT
		DECLARE @tis_DeliveryCharge				AS BIT
		DECLARE @tis_itemDiscount2				AS DECIMAL(10,4)
		DECLARE @tis_itemDiscountTotal2			AS DECIMAL(26,6)

		-- ---------------------------------------------------------------------------------
		-- Obtiene las listas de Costos de la Sucursal Actual
		-- ---------------------------------------------------------------------------------
		DECLARE @intPRLi4InCash AS INT
		DECLARE @branch_curr_id AS INT
		SELECT	@branch_curr_id = curr_id ,
				@coslis_id		= tb.coslis_id,
				@coslis_idB		= tb.bra_saleorder_coslis_id_B,
				@intPRLi4InCash = tb.prli_id4CreditInCash
			FROM tbBranch tb								WITH (NOLOCK)
			WHERE	tb.comp_id = @comp_id
				AND tb.bra_id  = @bra_id
		-- ---------------------------------------------------------------------------------

		Set @it_cd = getdate()


		-- ---------------------------------------------------------------------------------
		-- ATENCION!!!
		-- REMITOS PENDIENTES - REMITO PENDIENTE
		-- Verifica si el remito es pendiente de Facturación.
		-- Se verifica desde el archivo tbDocumentsFile, no por el parámetro que llega desde
		-- wfmSaleOrder
		-- ---------------------------------------------------------------------------------
		DECLARE @df_id		AS INT
		DECLARE @cust_id	AS INT
		DECLARE @dl_id		as int
		DECLARE @sds_id4RMAWhenEmmited AS INT
		DECLARE @df_saleOrder_creditNotewithOriginalCost AS BIT = 'False'
		SELECT @df_id	= df_id ,
			   @cust_id = tct.cust_id,
			   @dl_id	= tct.dl_id
			FROM tbCommercialTransactions tct				WITH (NOLOCK)
			WHERE	tct.comp_id			= @comp_id
				--AND tct.bra_id			= @bra_id
				AND tct.ct_transaction	= @ct_transaction


		SELECT  @it_packingInvoicePend	= isnull(tdf.df_PackingInvoicePend,'false') ,
				@sd_id					= tdf.sd_id,
				@sds_id4RMAWhenEmmited	= tdf.sds_id4RMAWhenEmmited,
				@df_saleOrder_creditNotewithOriginalCost =	CASE
																WHEN tdf.sd_id = 3 AND tdf.df_saleOrder_creditNotewithOriginalCost = 'True' THEN	'True'
																ELSE																				'False'
															END
			FROM tbDocumentsFile tdf					WITH (NOLOCK)
			WHERE	tdf.comp_id = @comp_id
				AND tdf.df_id	= @df_id
		-- ---------------------------------------------------------------------------------


		-- ---------------------------------------------------------------------------------
		-- Como se cargo el it_transaction_original en el campo it_transaction
		-- pero luego se usa para pasar como parametro al prox sp cual es el nuevo it_transaction
		-- del item en cuestion, pongo el it_transaction en el campo it_transaction_original
		-- ---------------------------------------------------------------------------------
		UPDATE tbTempItemStock	-- MOS 07-2024 WITH (ROWLOCK)
			SET
				it_transaction_original = it_transaction
			From	dbo.tbTempItemStock	WITH (NOLOCK)
			Where	--comp_id  = @comp_id
						tis_guid = @tis_guid
		-- ---------------------------------------------------------------------------------



		-- ---------------------------------------------------------------------------------
		-- POngo que los Items de COMBO cuyo PADRE dice q NO IMPRIMA en DocumentsPrint...
		-- ---------------------------------------------------------------------------------
		UPDATE tbTempItemStock	-- MOS 07-2024 WITH (ROWLOCK)
			SET
				tis_disablePrintInEmmition = 1
			From	dbo.tbTempItemStock		tis		WITH (NOLOCK)
			INNER JOIN tbItemAssociation AS tia		WITH (NOLOCK)
				ON	tia.comp_id		= tis.comp_id AND
					tia.item_id_1	= tis.item_id
			INNER JOIN tbItem AS ti					WITH (NOLOCK)
				ON	ti.comp_id		= tia.comp_id AND
					ti.item_id		= tia.item_id
			Where	tis.tis_guid											= @tis_guid		AND
					ti.item_isForAssociation_disablePrintOfAssociatedItems	= 1				AND
					tis.tis_id_origin IS NOT NULL		-- SOLO SI FORMA PARTE DE UN COMBO  MOS 07-2020
		-- ---------------------------------------------------------------------------------





		-- Declaro Cursor para recorrer a tempitemstock
		Declare cursor_IT_ID CURSOR LOCAL FAST_FORWARD For
			Select	tis_id,
					tis_priority,
					item_id,
					tis_itemDesc,
					tis_detail,
					curr_id,
					tis_initQty,
					tis_qty,
					prli_id,
					tis_price,
					stor_id,
					doc_id,
					tis_CD,
					soh_id,
					sod_id,
					tis_insertDate,
					aure_id,
					tax_id,
					aure_itemComposed,
					tis_itemDiscount,
					tis_CreditInt			/ dbo.fnNoZDiv(tis_qty),
					tis_CreditIntPlus		/ dbo.fnNoZDiv(tis_qty),
					-- MOS 05-2024: Ticket 21542
					(tis_itemDiscountTotal + tis_itemDiscountTotal2	) / dbo.fnNoZDiv(tis_qty), -- Ya que esta en ese campo calculado el total de descuento
					--tis_itemDiscountTotal	/ dbo.fnNoZDiv(tis_qty), -- Ya que esta en ese campo calculado el total de descuento
					tis_totalDiscountTotal	/ dbo.fnNoZDiv(tis_qty), -- Ya que esta en ese campo calculado el total de descuento y se necesita el del item solamente.!!!!!
					tis_isQuotation,
					tis_isCredit,
					tis_production,
					so_id,
					tis_note1,
					tis_note2,
					tis_cost,
					tis_id_origin,
					tis_item_id_origin,
					tis_isMade,
					it_transaction,
					rmah_id,
					rmad_id,
					tis_itemDiscount,
					tis_idOfThisEW,
					tis_costForced2All,
					camp_id,
					sdlmt_id,
					tis_loanNumberOfPays  ,
					sreas_id,
					sod_itemDeliveryDate,
					sod_EWAddress,
					CASE
						WHEN sod_isFromPCConfigCTRLId IS NULL THEN	'False'
						ELSE										'True'
					END														[isPCConfig],
					sod_isFromPCConfigCTRLId,
					item_idfromPreInvoice,
					ISNULL(sod_MLCost,0),
					ws_price,
					ws_curr_Id,
					mlo_id,
					ISNULL(tis_DeliveryCharge,'False'),
					ISNULL(sod_MECost,0),
					ISNULL(sod_MPCost,0),
					ISNULL(tis_isDivided_costCoeficient,1),
					ISNULL(tis_disablePrintInEmmition,'False'),
					wscup_id,
					tis_discountPlan,
					tis_itemDiscount2,
					tis_itemDiscountTotal2

			From	dbo.tbTempItemStock	WITH (NOLOCK)
			Where	--comp_id  = @comp_id
					tis_guid = @tis_guid
			ORDER BY tis_order,tis_id

		Open cursor_IT_ID

		Declare @tis_id					as int
		Declare @tis_priority			as decimal(14,4)
		Declare @item_id				as int
		Declare @tis_itemDesc			as varchar(500)
		Declare @tis_detail				as varchar(100)
		Declare @tis_curr_id			as int
		Declare @tis_initQty			as decimal(19,5)
		Declare @tis_qty				as decimal(19,5)
		Declare @prli_id                as int
		Declare @tis_price				as decimal(19,6)
		Declare @tis_cost				as decimal(19,6)
		Declare @stor_id				as int
		Declare @doc_id					as int
		Declare @tis_CD					as datetime
		Declare @soh_id					as INT
		Declare @sod_id					as int
		Declare @tis_insertDate			as datetime
		Declare @aure_id				as int
		Declare @tax_id					as int
		Declare @aure_itemComposed		as bit
		Declare @tis_itemDiscount		as decimal(10,6)
		DECLARE @tis_discountPlan		AS DECIMAL(19,4)
		Declare @tis_CreditInt			as decimal(19,6)
		Declare @tis_CreditIntPlus		as decimal(19,6)
		Declare @tis_itemDiscountTotal  as decimal(19,4)
		Declare @tis_totalDiscountTotal as decimal(19,4)
		Declare @tis_isQuotation		as bit
		Declare @tis_isCredit			as bit
		Declare @tis_production			as bit
		Declare @tis_isAssociation		as bit
		Declare @so_id      			as int
		Declare @it_TTransaction		as INT
		DECLARE @strNote1				AS VARCHAR(100)
		DECLARE @strNote2				AS VARCHAR(100)
		DECLARE @tis_id_origin			INT
		DECLARE @tis_isMade				BIT
		DECLARE	@tis_item_id_origin		INT
		DECLARE @it_transaction_original AS INT
		DECLARE @bitNoStockDiscount		 AS BIT
		Declare @bitIsCredit		     AS BIT
		DECLARE @rmah_id				 AS INT
		DECLARE @rmad_id				 AS INT
		DECLARE @decItemDiscount		 AS DECIMAL(19,4)
		DECLARE @intTis_IdOfThisEW		 AS INT
		DECLARE @intLastITTransaction    AS INT
		DECLARE @decForcedCost			 AS DECIMAL(19,4)
		DECLARE @intCampId				 AS INT
		DECLARE @intPUBHId				 AS INT
		DECLARE @sdlmt_id				 AS INT
		DECLARE @it_loanNumberOfPays			AS INT
		DECLARE @sreas_id						AS INT
		DECLARE @datDeliveryDate				AS DATETIME
		DECLARE @sod_EWAddres					AS NVARCHAR(250)
		DECLARE @bitIsPCConfig					AS BIT
		DECLARE @intPCConfigCTRLId				AS INT
		DECLARE @item_idfromPreInvoice			AS INT
		DECLARE @mlo_id							AS INT
		DECLARE @tis_disablePrintInEmmition		AS BIT
		--DECLARE @mlo_id4CommercialTransactions  AS INT
		DECLARE @tis_isDivided_costCoeficient	AS DECIMAL(30,10)
		DECLARE @wscup_id						AS INT

		Set @it_order = 0

		Fetch Next From cursor_IT_ID
			Into
				@tis_id,
				@tis_priority,
				@item_id,
				@tis_itemDesc,
				@tis_detail,
				@tis_curr_id,
				@tis_initQty,
				@tis_qty,
				@prli_id,
				@tis_price,
				@stor_id,
				@doc_id,
				@tis_CD,
				@soh_id,
				@sod_id,
				@tis_insertDate,
				@aure_id,
				@tax_id,
				@aure_itemComposed,
				@tis_itemDiscount,
				@tis_CreditInt,
				@tis_CreditIntPlus,
				@tis_itemDiscountTotal,
				@tis_totalDiscountTotal,
				@tis_isQuotation,
				@tis_isCredit,
				@tis_production,
				@so_id,
				@strNote1,
				@strNote2,
				@tis_cost,
				@tis_id_origin,
				@tis_item_id_origin,
				@tis_isMade,
				@it_transaction_original,
				@rmah_id,
				@rmad_id,
				@decItemDiscount,
				@intTis_IdOfThisEW,
				@decForcedCost,
				@intCampId,
				@sdlmt_id	,
				@it_loanNumberOfPays	,
				@sreas_id	,
				@datDeliveryDate	,
				@sod_EWAddres,
				@bitIsPCConfig,
				@intPCConfigCTRLId,
				@item_idfromPreInvoice,
				@sod_MLCost,
				@ws_price,
				@ws_curr_id,
				@mlo_id,
				@tis_DeliveryCharge,
				@sod_MECost,
				@sod_MPCost,
				@tis_isDivided_costCoeficient,
				@tis_disablePrintInEmmition,
				@wscup_id,
				@tis_discountPlan,
				@tis_itemDiscount2,
				@tis_itemDiscountTotal2


		While @@Fetch_Status = 0
			Begin


				DECLARE @decInCashPrice AS DECIMAL(25,2)
				SET		@decInCashPrice = 0
				IF		@intPRLi4InCash IS NOT NULL AND
						@item_id		IS NOT NULL
					BEGIN
						SELECT @decInCashPrice = vpli.prli_price
							FROM vwPriceListItems vpli		WITH (NOLOCK)
							WHERE	vpli.comp_id = @comp_id AND
									vpli.item_id = @item_id AND
									vpli.prli_id = @intPRLi4InCash
					END



				SET @intPUBHId = NULL  -- Inicializa


				-- -------------------------------------------------------------
				-- Verifica si debe o no descontar stock del item
				-- -------------------------------------------------------------
				SET @bitNoStockDiscount = 'False'
				IF ((@sd_id = 1) AND (not @it_transaction_original IS NULL)) OR @tis_isQuotation = 'True'
					BEGIN
						SET @bitNoStockDiscount = 'True'
					END
				-- -------------------------------------------------------------

				-- -------------------------------------------------------------
				-- Calculos Auxiliares
				-- -------------------------------------------------------------
				Set @it_order = @it_order + 1

				-- Precio del Item a Moneda de la Factura
				Set @tis_price		= dbo.fnGetExchange2(@comp_id,
														@tis_price,
														@tis_curr_id,
														@curr_id,
														@branch_curr_id,
														@forcedExchangeCurrency,
														@forcedExchange,
														@purchaseExchange)

				-- Precio deCosto Item a Moneda de la Factura
				Set @tis_cost		= dbo.fnGetExchange2(@comp_id,
														@tis_cost,
														@tis_curr_id,
														@curr_id,
														@branch_curr_id,
														@forcedExchangeCurrency,
														@forcedExchange,
														@purchaseExchange)

				-- Recupero Costos de los Items.-
				If @item_id is NULL						-- ITEM MANUALES

					Begin
						SET @tis_cost					= ISNULL(@tis_cost,0)
						Set @it_priceOfCost             = @tis_cost
						Set @it_priceOfCostPP           = @tis_cost
						Set @it_priceOfCostLastPurchase = @tis_cost
						Set	@it_priceBOfCost            = @tis_cost
						Set	@it_priceBOfCostPP          = @tis_cost
						Set	@it_priceBOfCostLastPurchase= @tis_cost
					END

				ELSE IF IsNull(@decForcedCost,0) <> 0	-- El Costo Forzado ya viene calculado del ultimo recalculo

					BEGIN
						SET @tis_cost					= ISNULL(@decForcedCost,0)
						Set @it_priceOfCost             = @tis_cost
						Set @it_priceOfCostPP           = @tis_cost
						Set @it_priceOfCostLastPurchase = @tis_cost
						Set	@it_priceBOfCost            = @tis_cost
						Set	@it_priceBOfCostPP          = @tis_cost
						Set	@it_priceBOfCostLastPurchase= @tis_cost
					END

				Else

					Begin

						Set @it_priceOfCost             = 0
						Set @it_priceOfCostPP           = 0
						Set @it_priceOfCostLastPurchase = 0
						Set	@it_priceBOfCost            = 0
						Set	@it_priceBOfCostPP          = 0
						Set	@it_priceBOfCostLastPurchase= 0


						-- ---------------------------------------------------------------------------------
						-- Tomo la lista de precios de costo segun sucursal o segun lo definido en el deposito
						-- ---------------------------------------------------------------------------------
						SELECT @TMPcoslis_id = ISNULL(ts.coslis_id,@coslis_id)
							FROM tbStorage ts				WITH (NOLOCK)
							WHERE	ts.comp_id = @comp_id
								AND ts.stor_id = @stor_id
						-- ---------------------------------------------------------------------------------

						-- ---------------------------------------------------------------------------------
						-- Tomo la lista de precios de costo segun Cliente o lo antes definido
						-- ---------------------------------------------------------------------------------
						SELECT @TMPcoslis_id = ISNULL(tc.coslis_id,@TMPcoslis_id)
							FROM tbCustomer tc					WITH (NOLOCK)
								WHERE	tc.comp_id = @comp_id
									AND tc.cust_id = @cust_id
						-- ---------------------------------------------------------------------------------





						-- ----------------------------
						-- Costo del Item
						-- ----------------------------
						Select	@it_priceOfCost    = IsNull(A.coslis_price,0)	 *	CASE
																						WHEN ticln.coslis_SaleOrderApplyItemDisountAndCharges = 'True' AND tipd.comp_id IS NOT	NULL THEN dbo.fnGetFinalDiscountCoeficient(tipd.item_purOrd_Disc1, tipd.item_purOrd_Disc2, tipd.item_purOrd_Disc3, tipd.item_purOrd_Disc4)	* dbo.fnGetFinalDiscountCoeficient(-tipd.item_purOrd_surcharge1,	-tipd.item_purOrd_surcharge2,	-tipd.item_purOrd_surcharge3,	-tipd.item_purOrd_surcharge4)
																						WHEN ticln.coslis_SaleOrderApplyItemDisountAndCharges = 'True' AND tipd.comp_id IS		NULL THEN dbo.fnGetFinalDiscountCoeficient(ti.item_purOrd_Disc1, ti.item_purOrd_Disc2, ti.item_purOrd_Disc3, ti.item_purOrd_Disc4)			* dbo.fnGetFinalDiscountCoeficient(-ti.item_purOrd_surcharge1,		-ti.item_purOrd_surcharge2,		-ti.item_purOrd_surcharge3,		-ti.item_purOrd_surcharge4)
																						ELSE 1
																					END,
								@it_priceOfCostPP  = IsNull(A.coslis_price_aw,0) *	CASE
																						WHEN ticln.coslis_SaleOrderApplyItemDisountAndCharges = 'True' AND tipd.comp_id IS NOT	NULL THEN dbo.fnGetFinalDiscountCoeficient(tipd.item_purOrd_Disc1, tipd.item_purOrd_Disc2, tipd.item_purOrd_Disc3, tipd.item_purOrd_Disc4)	* dbo.fnGetFinalDiscountCoeficient(-tipd.item_purOrd_surcharge1,	-tipd.item_purOrd_surcharge2,	-tipd.item_purOrd_surcharge3,	-tipd.item_purOrd_surcharge4)
																						WHEN ticln.coslis_SaleOrderApplyItemDisountAndCharges = 'True' AND tipd.comp_id IS		NULL THEN dbo.fnGetFinalDiscountCoeficient(ti.item_purOrd_Disc1, ti.item_purOrd_Disc2, ti.item_purOrd_Disc3, ti.item_purOrd_Disc4)			* dbo.fnGetFinalDiscountCoeficient(-ti.item_purOrd_surcharge1,		-ti.item_purOrd_surcharge2,		-ti.item_purOrd_surcharge3,		-ti.item_purOrd_surcharge4)
																						ELSE 1
																					END,
								@tmpCurr_Id		   = IsNull(A.curr_id,@curr_id),
								@intPUBHId		   = A.pubh_id
							From	dbo.vwItemCostList A				WITH (NOLOCK)
							INNER JOIN tbitem			ti				WITH (NOLOCK)
								ON	ti.comp_id		= @comp_id AND
									ti.item_id		= @item_id
							INNER JOIN tbItemCostListName ticln			WITH (NOLOCK)
								ON	ticln.comp_id	= @comp_id AND
									ticln.coslis_id = @TMPcoslis_id
							LEFT JOIN tbItemPublicationDetail tipd		WITH (NOLOCK)
								ON	tipd.comp_id	= @comp_id		AND
									tipd.pubh_id	= A.pubh_id		AND
									tipd.item_id	= @item_id		AND
									tipd.coslis_id	= @TMPcoslis_id
							Where	A.comp_id   = @comp_id
								and	A.coslis_id = @TMPcoslis_id
								and	A.item_id   = @item_id

						Set @it_priceOfCost				= dbo.fnGetExchange2(@comp_id,
																			 @it_priceOfCost,
																			 @tmpCurr_Id,
																			 @curr_id,
																			 @branch_curr_id,
																			 @forcedExchangeCurrency ,
																			 @forcedExchange,
																			 @purchaseExchange)

						Set @it_priceOfCostPP			= dbo.fnGetExchange2(@comp_id,
																			 @it_priceOfCostPP,
																			 @tmpCurr_Id,
																			 @curr_id,
																			 @branch_curr_id,
																			 @forcedExchangeCurrency,
																			 @forcedExchange,
																			 @purchaseExchange)

						Set @it_priceOfCostLastPurchase = @it_priceOfCost				  -- En realidad deberia ir el sacado x numero de serie


						-- -------------------------------------------------------------------------------------------
						-- Tomo la lista de precios de costo B segun sucursal o segun lo definido en el deposito
						-- -------------------------------------------------------------------------------------------
						SELECT @TMPcoslis_idB = ISNULL(ts.coslis_idB,@coslis_idB)
							FROM tbStorage ts		WITH (NOLOCK)
							WHERE	ts.comp_id = @comp_id
								AND ts.stor_id = @stor_id
						-- -------------------------------------------------------------------------------------------

						-- -------------------------------------------------------------------------------------------
						-- Tomo la lista de precios de costo segun Cliente o lo antes definido
						-- -------------------------------------------------------------------------------------------
						SELECT @TMPcoslis_idB = ISNULL(tc.coslis_idB,@TMPcoslis_idB)
							FROM tbCustomer tc				WITH (NOLOCK)
							WHERE	tc.comp_id = @comp_id
								AND tc.cust_id = @cust_id
						-- -------------------------------------------------------------------------------------------


						-- ----------------------------
						-- Idem para costo Alternativo.-
						-- ----------------------------
						Select	@it_priceBOfCost    = IsNull(A.coslis_price,0)	  *	CASE
																						WHEN ticln.coslis_SaleOrderApplyItemDisountAndCharges = 'True' AND tipd.comp_id IS NOT	NULL THEN dbo.fnGetFinalDiscountCoeficient(tipd.item_purOrd_Disc1, tipd.item_purOrd_Disc2, tipd.item_purOrd_Disc3, tipd.item_purOrd_Disc4)	* dbo.fnGetFinalDiscountCoeficient(-tipd.item_purOrd_surcharge1,	-tipd.item_purOrd_surcharge2,	-tipd.item_purOrd_surcharge3,	-tipd.item_purOrd_surcharge4)
																						WHEN ticln.coslis_SaleOrderApplyItemDisountAndCharges = 'True' AND tipd.comp_id IS		NULL THEN dbo.fnGetFinalDiscountCoeficient(ti.item_purOrd_Disc1, ti.item_purOrd_Disc2, ti.item_purOrd_Disc3, ti.item_purOrd_Disc4)			* dbo.fnGetFinalDiscountCoeficient(-ti.item_purOrd_surcharge1,		-ti.item_purOrd_surcharge2,		-ti.item_purOrd_surcharge3,		-ti.item_purOrd_surcharge4)
																						ELSE 1
																					END,
								@it_priceBOfCostPP  = IsNull(A.coslis_price_aw,0) *	CASE
																						WHEN ticln.coslis_SaleOrderApplyItemDisountAndCharges = 'True' AND tipd.comp_id IS NOT	NULL THEN dbo.fnGetFinalDiscountCoeficient(tipd.item_purOrd_Disc1, tipd.item_purOrd_Disc2, tipd.item_purOrd_Disc3, tipd.item_purOrd_Disc4)	* dbo.fnGetFinalDiscountCoeficient(-tipd.item_purOrd_surcharge1,	-tipd.item_purOrd_surcharge2,	-tipd.item_purOrd_surcharge3,	-tipd.item_purOrd_surcharge4)
																						WHEN ticln.coslis_SaleOrderApplyItemDisountAndCharges = 'True' AND tipd.comp_id IS		NULL THEN dbo.fnGetFinalDiscountCoeficient(ti.item_purOrd_Disc1, ti.item_purOrd_Disc2, ti.item_purOrd_Disc3, ti.item_purOrd_Disc4)			* dbo.fnGetFinalDiscountCoeficient(-ti.item_purOrd_surcharge1,		-ti.item_purOrd_surcharge2,		-ti.item_purOrd_surcharge3,		-ti.item_purOrd_surcharge4)
																						ELSE 1
																					END,
								@tmpCurr_Id		   = IsNull(A.curr_id,@curr_id)
							From	dbo.vwItemCostList A				WITH (NOLOCK)
							INNER JOIN tbitem			ti				WITH (NOLOCK)
								ON	ti.comp_id		= @comp_id AND
									ti.item_id		= @item_id
							INNER JOIN tbItemCostListName ticln			WITH (NOLOCK)
								ON	ticln.comp_id	= @comp_id AND
									ticln.coslis_id = @TMPcoslis_idB
							LEFT JOIN tbItemPublicationDetail tipd		WITH (NOLOCK)
								ON	tipd.comp_id	= @comp_id		AND
									tipd.pubh_id	= A.pubh_id	AND
									tipd.item_id	= @item_id		AND
									tipd.coslis_id	= @TMPcoslis_idB
							Where	A.comp_id   = @comp_id
								and	A.coslis_id = @TMPcoslis_idB
								and	A.item_id   = @item_id

						Set @it_priceBOfCost			= dbo.fnGetExchange2(@comp_id,
																			 @it_priceBOfCost,
																			 @tmpCurr_Id,
																			 @curr_id,
																			 @branch_curr_id,
																			 @forcedExchangeCurrency ,
																			 @forcedExchange,
																			 @purchaseExchange)

						Set @it_priceBOfCostPP			= dbo.fnGetExchange2(@comp_id,
																			 @it_priceBOfCostPP,
																			 @tmpCurr_Id,
																			 @curr_id,
																			 @branch_curr_id,
																			 @forcedExchangeCurrency,
																			 @forcedExchange,
																			 @purchaseExchange)

						SET @it_priceBOfCostLastPurchase = @it_priceBOfCost  -- En realidad deberia ir el sacado x numero de serie

		-- NO Va Mas  MOS:!
		--				Set @it_priceBOfCost			 = @it_priceOfCost
		--				Set @it_priceBOfCostPP			 = @it_priceOfCostPP
		--				Set @it_priceBOfCostLastPurchase = @it_priceOfCostLastPurchase


					End
				--  -------------------------------------------------------------

				--  Recupero Precio Original de la Lista al Momento de la factura
				If @item_id is not null
					Begin
						Select	@it_OriginalPrice		  = A.prli_price,
								@it_OriginalPriceCurrency = A.curr_id
							From	dbo.vwPriceListItems A		WITH (NOLOCK)		-- tbPriceListItems MOS 03-2017
							Where	A.comp_id = @comp_id
								and	A.prli_id = @prli_id
								and	A.item_id = @item_id
					End
				Else
					Begin
						Set @it_OriginalPrice			= null
						Set @it_OriginalPriceCurrency	= null
					End

				Set @it_OriginalPrice					= IsNull(@it_OriginalPrice,@tis_price)
				Set @it_OriginalPriceCurrency			= IsNull(@it_OriginalPriceCurrency,@curr_id)
				Set @it_exchangeToOriginalPriceCurrency = dbo.fnGetExchange2(@comp_id,
																			 1,
																			 @it_OriginalPriceCurrency,--@tis_curr_id,
																			 @curr_id,
																			 @branch_curr_id,
																			 @forcedExchangeCurrency,
																			 @forcedExchange,
																			 @purchaseExchange)

				Set @it_exchangeToBranchCurrency		= dbo.fnGetExchange2(@comp_id,
																			 1,
																			 @tis_curr_id,
																			 @curr_id,
																			 @branch_curr_id,
																			 @forcedExchangeCurrency,
																			 @forcedExchange,
																			 @purchaseExchange)

				-- -------------------------------------------------------------

				-- Busca Stock Anterior a la Grabacion de este Movimiento
				Set    @it_storePrevious = 0
				Select @it_storePrevious = A.itst_cant
					From dbo.tbItemStorage A		WITH (NOLOCK)
					Where comp_id = @comp_id
					  and item_id = @item_id
					  and stor_id = @stor_id

				Set @it_storePrevious = IsNull(@it_storePrevious,0)
				-- -------------------------------------------------------------

				-- Recupera x Cuenta y Orden de quien es.-
				Set @it_guarantee			= 0
				SET @it_guarantee4PCConfig	= 0
				Select @byor_id					= A.byor_id,
					   @it_guarantee			= item_guarantee,
					   @it_guarantee4PCConfig	= A.item_guarantee4PCConfig
					From dbo.tbItem A		WITH (NOLOCK)
					Where comp_id = @comp_id
					  and item_id = @item_id


				-- Si esta aca definido toma lo de esta tabla y no lo de articulo.
				SELECT @byor_id = tibobb.byor_id
					FROM tbItemByOrderByBranch tibobb	WITH (NOLOCK)
					WHERE	tibobb.comp_id			= @comp_id	AND
							tibobb.bra_id			= @bra_id	AND
							tibobb.item_id			= @item_id	AND
							tibobb.icob_isDisabled	= 'False'


				-- Si tiene item asociados
				If @tis_item_id_origin IS not null
					Begin
						Set @tis_isAssociation  = 'true'
					end

				-- -------------------------------------------------------------
				-- Datos de Garantia Extendida y Seguros
				-- -------------------------------------------------------------
				DECLARE @it_transaction_originalEW	AS INT
				DECLARE @it_insuranceDays			AS INT
				DECLARE @insud_id					AS INT
				DECLARE @insud_certificateNumber	AS INT
				SET @it_transaction_originalEW	= NULL
				SET @insud_id					= NULL
				SET @insud_certificateNumber	= 0
				SET @it_insuranceDays			= 0

				-- Si es un articulo de Garantia Extendida
				IF	@intTis_IdOfThisEW		IS NOT NULL AND
					@intLastITTransaction	IS NOT NULL
					BEGIN
						SET @it_transaction_originalEW		= @intLastITTransaction
						SELECT	TOP 1
								@it_insuranceDays			= ti.item_insuranceDays,
								@insud_certificateNumber	= (tiabr.insud_certificateNumber + 1) ,
								@insud_id					= tiabr.insud_id
							FROM tbItem ti						WITH (NOLOCK)
							LEFT JOIN tbInsuranceAgent tia		WITH (NOLOCK)
								ON	tia.comp_id = ti.comp_id AND
									tia.insu_id = ti.insu_id
							LEFT JOIN tbInsuranceAgent_BranchRelation tiabr	WITH (NOLOCK)
								ON	tiabr.comp_id = tia.comp_id AND
									tiabr.insu_id = tia.insu_id
						WHERE	ti.comp_id			 = @comp_id	AND
								ti.item_id			 = @item_id	AND
								tiabr.bra_id		 = @bra_id	and
								tiabr.insud_disabled = 'False'	AND
								tia.insu_disabled    = 'False'	AND
								@datDeliveryDate BETWEEN tiabr.insud_fromDate AND tiabr.insud_toDate
						ORDER BY tiabr.insud_fromDate

						UPDATE tbInsuranceAgent_BranchRelation	WITH (ROWLOCK)
							SET insud_certificateNumber = @insud_certificateNumber
							WHERE	comp_id				= @comp_id	AND
									insud_id			= @insud_id

					END
				-- -------------------------------------------------------------


				SET @sod_MLCost = ISNULL(@sod_MLCost,0)


				IF
					@comp_id IS NOT NULL AND
					@stor_id IS NOT NULL AND
					@item_id IS NOT NULL AND
					NOT EXISTS (	SELECT TOP 1 1
										FROM tbItemStorage AS tis WITH (NOLOCK)
				               			WHERE	tis.comp_id = @comp_id AND
				               					tis.stor_id = @stor_id AND
				               					tis.item_id = @item_id
								)
					BEGIN
						INSERT INTO tbItemStorage
						(
							comp_id,
							stor_id,
							item_id,
							itst_cant,
							itst_cd,
							itst_PickingLocation,
							itst_StorageLocation,
							itst_updateByInTransitStock,
							itst_LastAvailableInRelalculation,
							itst_LastQTYAtQuery
						)
						VALUES
						(
							@comp_id,
							@stor_id,
							@item_id,
							0,
							GETDATE(),
							'',
							'',
							'False',
							0,
							0
						)
					END




				-- Si hay algun tema con este coeficiente de division de pedidos lo pone en 1
				IF	@tis_isDivided_costCoeficient IS NULL	OR
					@tis_isDivided_costCoeficient <= 0		OR
					@tis_isDivided_costCoeficient > 1
					BEGIN
						SET @tis_isDivided_costCoeficient = 1
					END






				-- MOS 05-2024 ticket 21542
					DECLARE	@tis_itemDiscountTOTALPlus2 AS DECIMAL(19,6) = @tis_itemDiscount
					IF @tis_itemDiscount2 <> 0
						BEGIN
							SET         @tis_itemDiscountTOTALPlus2=100-(@tis_itemDiscount)
							SET         @tis_itemDiscountTOTALPlus2=@tis_itemDiscountTOTALPlus2-(@tis_itemDiscountTOTALPlus2/100)*@tis_itemDiscount2
							SET         @tis_itemDiscountTOTALPlus2=(100 - @tis_itemDiscountTOTALPlus2)
						END
				-- MOS 05-2024 ticket 21542




				-- -------------------------------------------------------------
				-- Aca Graba finalmente la tabla de Movimientos de Stock
				-- -------------------------------------------------------------
				Insert Into dbo.tbItemTransactions	-- MOS 07-2024 WITH (ROWLOCK)
					(
						comp_id,
						bra_id,
						ct_transaction,
						it_cd,
						it_packingInvoicePend,
						it_packingInvoicePendOriginal,
						item_id,
						it_qty,
						it_priceWithOutOthers,
						it_price,
						curr_id,
						it_priceOfCost,
						it_priceOfCostPP,
						it_priceOfCostLastPurchase,
						it_priceBOfCost,
						it_priceBOfCostPP,
						it_priceBOfCostLastPurchase,
						it_OriginalPrice,
						it_OriginalPriceCurrency,
						stor_id,
						it_storePrevious,
						prli_id,
						byor_id,
						it_isProduction,
						it_isAssociation,
						it_order,
						so_id,
						it_guarantee,
						it_exchangeToOriginalPriceCurrency,
						it_itemDiscountTotal,
						it_totalDiscountTotal,
						it_CreditInt,
						it_CreditIntPlus,
						it_note1,
						it_note2,
						it_isAssociationGroup,
						it_item_id_origin,
						it_isMade,
						it_transaction_original,
						it_transaction_NoStockDiscount,
						it_SalesCurrId4exchangeToBranchCurrency,
						it_exchangeToBranchCurrency,
						rmah_id,
						rmad_id,
						it_Discount1,
						it_Discount2,		-- MOS 05-2024 ticket 21542
						it_transaction_originalEW,
						camp_id,
						sdlmt_id,
						it_loanNumberOfPays,
						sreas_id,
						it_soh_id,
						it_sod_id,
						it_deliveryDate,
						pubh_id,
						it_EWAddress,
						it_insuranceDays,
						insud_id,
						insud_certificateNumber,
						it_priceOfprli_id4CreditInCash,
						it_isPCConfig,
						it_isFromPCConfigCTRLId,
						item_idfromPreInvoice,
						it_MLCost,
						ws_price,
						ws_curr_Id,
						mlo_id,
						it_deliveryCharge,
						it_MPCost,
						it_MECost,
						it_disablePrintInEmmition,
						wscup_id,
						it_itemDiscount,
						tis_itemDiscountPlan
					 )
					Values
					(
						@comp_id,
						@bra_id,
						@ct_transaction,
						@it_cd,
						@it_packingInvoicePend,
						@it_packingInvoicePend,
						@item_id,
						@tis_qty,
						@tis_price,
						@tis_price - (@tis_itemDiscountTotal + @tis_totalDiscountTotal )
								   + (@tis_CreditInt		 + @tis_CreditIntPlus)			,
						@curr_id,
						CASE
							WHEN @tis_DeliveryCharge = 1 AND @it_priceOfCost = 0  THEN		 @tis_price - (@tis_itemDiscountTotal + @tis_totalDiscountTotal ) + (@tis_CreditInt + @tis_CreditIntPlus)
							ELSE															(@it_priceOfCost	+ @sod_MLCost + @sod_MECost /*@sod_MPCost +*/  )	-- Si se toca algo hacerlo tambien en el asiento de costos: [spAccountTransaction_InsertdataFromManagement_SalesCost]
						END * @tis_isDivided_costCoeficient,
						CASE
							WHEN @tis_DeliveryCharge = 1  AND @it_priceOfCostPP = 0 THEN	 @tis_price - (@tis_itemDiscountTotal + @tis_totalDiscountTotal ) + (@tis_CreditInt	+ @tis_CreditIntPlus)
							ELSE															(@it_priceOfCostPP	+ @sod_MLCost + @sod_MECost /*@sod_MPCost +*/  )	-- Si se toca algo hacerlo tambien en el asiento de costos: [spAccountTransaction_InsertdataFromManagement_SalesCost]
						END * @tis_isDivided_costCoeficient,
						@it_priceOfCostLastPurchase,
						CASE
							WHEN @tis_DeliveryCharge = 1 AND @it_priceBOfCost = 0  THEN		@tis_price -  (@tis_itemDiscountTotal + @tis_totalDiscountTotal ) + (@tis_CreditInt + @tis_CreditIntPlus)
							ELSE															@it_priceBOfCost
						END * @tis_isDivided_costCoeficient,
						CASE
							WHEN @tis_DeliveryCharge = 1 AND @it_priceBOfCostPP = 0  THEN	@tis_price -  (@tis_itemDiscountTotal + @tis_totalDiscountTotal ) + (@tis_CreditInt	+ @tis_CreditIntPlus)
							ELSE															@it_priceBOfCostPP
						END * @tis_isDivided_costCoeficient ,
						@it_priceBOfCostLastPurchase,
						@it_OriginalPrice,
						@it_OriginalPriceCurrency,
						@stor_id,
						@it_storePrevious,
						@prli_id,
						@byor_id,
						isnull(@tis_production,'false'),
						isNull(@tis_isAssociation,'False'),
						@it_order,
						@so_id,
						CASE
							WHEN @bitIsPCConfig = 'True' AND @it_guarantee4PCConfig > 0 THEN	@it_guarantee4PCConfig
							ELSE																@it_guarantee
						END,
						@it_exchangeToOriginalPriceCurrency,
						@tis_itemDiscountTotal,
						@tis_totalDiscountTotal,
						@tis_CreditInt,
						@tis_CreditIntPlus,
						@strNote1,
						@strNote2,
						@tis_id_origin,
						@tis_item_id_origin,
						@tis_isMade,
						@it_transaction_original,
						@bitNoStockDiscount,
						@tis_curr_id,
						@it_exchangeToBranchCurrency,
						@rmah_id,
						@rmad_id,
						@decItemDiscount,
						@tis_itemDiscount2,		-- MOS 05-2024
						@it_transaction_originalEW
						/*CASE
							WHEN @intTis_IdOfThisEW IS NOT NULL AND @intLastITTransaction IS NOT NULL THEN @intLastITTransaction
							ELSE NULL
						END*/,
						@intCampId,
						@sdlmt_id	,
						@it_loanNumberOfPays	,
						@sreas_id,
						@soh_id,
						@sod_id	,
						@datDeliveryDate,
						@intPUBHId,
						@sod_EWAddres,
						@it_insuranceDays,
						@insud_id,
						@insud_certificateNumber,
						@decInCashPrice	,
						@bitIsPCConfig,
						@intPCConfigCTRLId,
						@item_idfromPreInvoice,
						@sod_MLCost,
						@ws_price,
						@ws_curr_id,
						@mlo_id,
						@tis_DeliveryCharge,
						@sod_MPCost,
						@sod_MECost,
						@tis_disablePrintInEmmition,
						@wscup_id,
						--@tis_itemDiscount,
						-- MOS 05-2024 ticket 21542
						@tis_itemDiscountTOTALPlus2,
						@tis_discountPlan
					 )
					-- -------------------------------------------------------------
					-- Aca Pone la Identidad Correspondiente.- OJO, NO sacar de aca!
					-- -------------------------------------------------------------
					Set @it_TTransaction = IDENT_CURRENT('tbItemTransactions') -- Se puso asi porque NO SE PORQUE MIERDA devolvia cuelquier cosa el @@Identity




					-- -------------------------------------------------------------
					-- Si es una NC y debo poner los costos ORIGINALES, los reemplazo acá.
					-- -------------------------------------------------------------
					-- @it_transaction_original
					IF @df_saleOrder_creditNotewithOriginalCost = 'True'
						BEGIN
							UPDATE tmp2Update
								SET		it_priceOfCost				=  tit2.it_priceOfCost ,
							            it_priceOfCostPP			=  tit2.it_priceOfCostPP ,
							            it_priceOfCostLastPurchase	=  tit2.it_priceOfCostLastPurchase ,
							            it_priceBOfCost				=  tit2.it_priceBOfCost ,
							            it_priceBOfCostPP			=  tit2.it_priceBOfCostPP ,
							            it_priceBOfCostLastPurchase =  tit2.it_priceBOfCostLastPurchase ,
							            it_MPCost					=  tit2.it_MPCost ,
							            it_MECost					=  tit2.it_MECost,
							            it_MLCost					=  tit2.it_MLCost
								FROM		tbItemTransactions tmp2Update	WITH (NOLOCK)
								INNER JOIN	tbItemTransactions AS tit2		WITH (NOLOCK)
									ON	tit2.comp_id				= tmp2Update.comp_id	AND
										tit2.it_transaction			= tmp2Update.it_transaction_original
								WHERE	tmp2Update.comp_id			= @comp_id		AND
										tmp2Update.it_transaction	= @it_TTransaction
						END
					-- -------------------------------------------------------------





					-- Guarda esta como la ultima transaccion grabada porque si la proxima dice q es una
					-- Garantia Extendida debe actualizarla con el id de esta transaccion
					SET @intLastITTransaction = @it_TTransaction

					--IF @mlo_id4CommercialTransactions IS NULL AND @mlo_id IS NOT NULL
					--	BEGIN
					--		SET @mlo_id4CommercialTransactions = @mlo_id
					--	END


					Update dbo.tbTempItemStock	-- MOS 07-2024 WITH (ROWLOCK)
						Set		it_transaction					= @it_TTransaction,
								it_transaction_NoStockDiscount	= @bitNoStockDiscount
						Where	comp_id = @comp_id	AND  -- MOS 11/2018
								tis_id  = @tis_id



					-- -------------------------------------------------------------
					-- Si es un pedido de RMA y el documento dice q hay que poner un determinado estado, lo pone.
					-- -------------------------------------------------------------
					IF	@sds_id4RMAWhenEmmited IS NOT NULL	AND
						@rmad_id IS NOT NULL				AND
						@rmad_id > 0
						BEGIN
							UPDATE tbRMA_Detail		-- MOS 07-2024 WITH (ROWLOCK)
								SET	sds_id4Delivery = @sds_id4RMAWhenEmmited
								WHERE	comp_id = @comp_id AND
										rmah_id = @rmah_id AND
										rmad_id = @rmad_id
						END
					-- -------------------------------------------------------------




					-- -------------------------------------------------------------
					-- Actualiza el ct_transaction e it_transaction en Ensamblado!
					-- -------------------------------------------------------------

					SET		@ta_id	= NULL
					SELECT	@ta_id	= ta.ta_id
						FROM tbAssembly_Turns4Assembly TA		WITH (NOLOCK)
						WHERE	comp_id		= @comp_id	AND
								TA.tis_id	= @tis_id
								--bra_id	= @bra_id	AND
								--soh_id	= @soh_id	AND
								--sod_id	= @sod_id

					UPDATE tbAssembly_Turns4Assembly		-- MOS 07-2024 WITH (ROWLOCK)
						SET
							ct_transaction	= @ct_transaction,
							it_transaction	= @it_TTransaction,
							tis_id			= NULL
						WHERE	comp_id		= @comp_id	AND
								ta_id		= @ta_id


					IF @ta_id IS NOT NULL AND  @tis_qty > 1
						BEGIN
							SET @intCounter = 2
							WHILE	@intCounter <= @tis_qty	AND
									@intCounter <= 10000	-- MOS 07-2020 x q en Authogar cargaban 9999999 y bloqueaban todo.  En cado de necesitar agregar un campo con el MAXIMO PErmitido
								BEGIN

									INSERT INTO tbAssembly_Turns4Assembly	-- MOS 07-2024 WITH (ROWLOCK)
									(
										comp_id,
										tar_id,
										bra_id,
										soh_id,
										sod_id,
										ct_transaction,
										item_id,
										ta_isAssembled,
										ta_isCancelled,
										ta_note,
										ta_cd,
										user_id_cd,
										ta_date4Assembly,
										user_id_Supervisor,
										user_id_Assigned4Assembly,
										ta_date4begin,
										ta_date4End,
										it_transaction,
										tis_id,
										tar_cd,
										user_id_Assigned4Assembly2,
										user_id_Assigned4Assembly3,
										user_id_Assigned4Assembly4,
										user_id_Assigned4Assembly5,
										tar_guid4Selection,
										ta_order
									)
									SELECT	tata.comp_id,
											tata.tar_id,
											tata.bra_id,
											tata.soh_id,
											tata.sod_id,
											tata.ct_transaction,
											tata.item_id,
											tata.ta_isAssembled,
											tata.ta_isCancelled,
											tata.ta_note,
											tata.ta_cd,
											tata.user_id_cd,
											tata.ta_date4Assembly,
											tata.user_id_Supervisor,
											tata.user_id_Assigned4Assembly,
											tata.ta_date4begin,
											tata.ta_date4End,
											tata.it_transaction,
											tata.tis_id,
											tata.tar_cd,
											tata.user_id_Assigned4Assembly2,
											tata.user_id_Assigned4Assembly3,
											tata.user_id_Assigned4Assembly4,
											tata.user_id_Assigned4Assembly5,
											tata.tar_guid4Selection,
											@intCounter
										FROM tbAssembly_Turns4Assembly tata		WITH (NOLOCK)
										WHERE	comp_id = @comp_id	AND
												ta_id	= @ta_id
									SET @intCounter = @intCounter + 1


								END
						END
					-- -------------------------------------------------------------




					-- -------------------------------------------------------------
					-- Actualiza cantidad disponible en campañas comerciales
					-- -------------------------------------------------------------
					IF @intCampId IS NOT NULL
						BEGIN
							UPDATE tbItem_CommercialCampaign	-- MOS 07-2024 WITH (ROWLOCK)
							SET
								camp_qtyAvailable   = (IsNull(camp_qtyAvailable,0) - @tis_qty)
							WHERE	comp_id			= @comp_id		AND
									camp_id			= @intCampId	AND
									camp_qtyCheck	= 'True'
						END
					-- -------------------------------------------------------------




					-- -------------------------------------------------------------
					--	Descuenta o Suma Stock
					-- -------------------------------------------------------------
					IF @bitNoStockDiscount ='False'
						BEGIN

							SELECT @bitIsCredit = td.sd_isCredit
								FROM tbsysDocuments td		WITH (NOLOCK)
								WHERE  td.sd_id = @sd_id


							-- -------------------------------------------------
							-- Si no existe el articulo en tbTempItemStock, lo crea
							-- -------------------------------------------------
							INSERT INTO tbItemStorage	-- MOS 07-2024 WITH (ROWLOCK)
							(
								comp_id,
								stor_id,
								item_id,
								itst_cant,
								itst_cd,
								itst_PickingLocation,
								itst_StorageLocation
							)
							SELECT ttis.comp_id,
								   ttis.stor_id,
								   ttis.item_id,
								   0,
								   GETDATE(),
								   '',
								   ''
								From	tbTempItemStock ttis				WITH (NOLOCK)
								LEFT JOIN tbItemStorage tis					WITH (NOLOCK)
									ON		tis.comp_id = ttis.comp_id
										AND tis.stor_id = ttis.stor_id
										AND tis.item_id = ttis.item_id
								Where
										ttis.tis_guid	= @tis_guid
									AND tis.item_id  IS NULL
									AND ttis.item_id IS NOT NULL
							-- -------------------------------------------------


							-- Actualiza el stock
								Update  dbo.tbItemStorage	-- MOS 07-2024 WITH (ROWLOCK)
								Set		itst_cant = (A.itst_cant - (B.tis_qty *
																			  Case B.tis_isCredit
																				When 'True'  Then -1
																				When 'False' Then 1
																			  End
																	)
													)
								From	dbo.tbItemStorage A			WITH (NOLOCK)
								INNER JOIN  dbo.tbTempItemStock B	WITH (NOLOCK)
									ON	b.comp_id = a.comp_id AND
										b.item_id = a.item_id AND
										b.stor_id = a.stor_id
								Where   A.comp_id	= B.comp_id
									and	B.tis_guid	= @tis_guid
									And B.tis_id	= @tis_id
									AND B.item_id IS NOT NULL
								----					Update  dbo.tbItemStorage
								----						Set		itst_cant = (A.itst_cant - (B.tis_qty *
								----																	  Case B.tis_isCredit
								----																		When 'True'  Then -1
								----																		When 'False' Then 1
								----																	  End
								----															)
								----											)
								----						From	dbo.tbItemStorage A, dbo.tbTempItemStock B
								----						Where   A.comp_id	= B.comp_id
								----							and	B.tis_guid	= @tis_guid
								----							and A.stor_id	= isnull(B.stor_id,0)
								----							and A.item_id	= B.item_id
								----							And B.tis_id	= @tis_id

						END


					-- -------------------------------------------------------------
					-- Guarda las descripciones manuales o de articulos diferentes.-
					-- OJO, que siempre grabe solo UNO por cada it_transaction     -
					-- -------------------------------------------------------------
					If @item_id is null or (@tis_itemDesc <> (Select item_desc From dbo.tbItem WITH (NOLOCK) Where comp_id = @comp_id and item_id = @item_id))
						Begin
							Insert Into dbo.tbItemTransactionDetails	-- MOS 07-2024 WITH (ROWLOCK)
								(	comp_id,
									bra_id,
									ct_transaction,
									it_transaction,
									itm_desc,
									itm_desc1,
									itm_desc2)
								Values
								(	@comp_id,
									@bra_id,
									@ct_transaction,
									@it_TTransaction,
									@tis_itemDesc,
									@tis_detail,
									'')
						End

					-- -------------------------------------------------------------



					-- -------------------------------------------------------------
					-- Inserta el Pedido de Distribucion del articulo
					-- -------------------------------------------------------------
					IF @item_id IS NOT NULL
						BEGIN

							IF EXISTS(
										SELECT TOP 1  1
											FROM tbDelivery td	WITH (NOLOCK)
											WHERE	td.comp_id	= @comp_id	AND
													td.dl_id	= @dl_id	AND
													(
														(@sdlmt_id = 1 AND td.dl_deliveryType_pickUpNow					= 'True') OR
														(@sdlmt_id = 3 AND td.dl_deliveryType_warns4PickUp				= 'True') OR
														(@sdlmt_id = 2 AND td.dl_deliveryType_deliver					= 'True') OR
														(@sdlmt_id = 4 AND td.dl_deliveryType_warns4Deliver				= 'true') OR
														(@sdlmt_id = 5 AND td.dl_deliveryType_wait4GuarantorSignature	= 'True') OR
														(@sdlmt_id = 6 AND td.dl_deliveryType_wait4OwnerSignature		= 'True') OR
														(@sdlmt_id = 7 AND td.dl_deliveryType_wait4PurchaseOrderArrival	= 'True') OR
														(@sdlmt_id = 8 AND td.dl_deliveryType_other						= 'True')
													)
										)
								BEGIN

									SET		@intCounterDelivery =	1
									WHILE	@intCounterDelivery <=	@tis_qty AND
											@intCounterDelivery <= 10000		-- MOS 07-2020 x q en Authogar cargaban 9999999 y bloqueaban todo.  En cado de necesitar agregar un campo con el MAXIMO PErmitido
										BEGIN
											INSERT INTO tbItemTransactionsDelivery	-- MOS 07-2024 WITH (ROWLOCK)
											(
												comp_id,
												bra_id,
												ct_transaction,
												it_transaction,
												itd_isPending,
												stor_id
											)
											VALUES
											(
												@comp_id,
												@bra_id,
												@ct_transaction,
												@it_TTransaction,
												'True',
												@stor_id
											)
											SET @intCounterDelivery = @intCounterDelivery + 1
										END

								END

						END
					-- -------------------------------------------------------------


					-- Marca la ORDEN como EMITIDA !!!
					IF @mlo_id IS NOT NULL
						BEGIN
							-- Marca la orden como PROCESADA para que no se vuelva a procesar.
							UPDATE tbMercadoLibre_ordersHeader		-- MOS 07-2024 WITH (ROWLOCK)
								SET mlo_isSaleOrderEmmited = 1
								WHERE	comp_id = @comp_id AND
										mlo_id	= @mlo_id
						END



					-- -----------------------------------------------------------------------------------------
					-- Actualiza los Remitos seleccionados para Facturar poniendo el campo de Pendiente en False
					-- REMITOS PENDIENTES - REMITO PENDIENTE
					-- **lfwehwh0293784aksjdnhkqwdn
					-- FUTURO: si algun FORRO dice que no le gusta que NO se guarde como pedido y deba
					--         emitirse es porque se pierde el doble control del campo it_packingInvoiceSelected y
					--         it_packingInvoiceSelectedGuid.  Como las drogas, simplemente decirle NOOOOOOOOOO
					-- -----------------------------------------------------------------------------------------
					IF @it_transaction_original IS NOT NULL
						BEGIN
							--SELECT 1 / 0
							UPDATE tbItemTransactions		-- MOS 07-2024 WITH (ROWLOCK)
								SET
									it_packingInvoicePend			=
															CASE
																WHEN ISNULL(it_packingInvoiceQTYInvoiced,0) + @tis_qty >= it_qty THEN   'False'
																ELSE																	it_packingInvoicePend
															END,
									it_packingInvoiceQTYInvoiced	= ISNULL(it_packingInvoiceQTYInvoiced,0) + @tis_qty,
									it_packingInvoiceSelected		= 'false',
									it_packingInvoiceSelectedGuid	= NULL
								WHERE	comp_id										= @comp_id						AND
										it_packingInvoiceSelectedGuid				= @tis_guid						AND
										it_packingInvoiceSelected					= 'True'						AND
										it_transaction								=  @it_transaction_original
							--IF @@ROWCOUNT <= 0
							--	BEGIN
							--		DECLARE @strError AS NVARCHAR(MAX) = '@it_transaction_original:' + CONVERT(NVARCHAR(1000),@it_transaction_original) +
							--											 '@tis_guid:' + CONVERT(NVARCHAR(1000),@tis_guid)
							--		RAISERROR (15600,-1,-1,@strError );
							--		--SELECT 1 / 0
							--	END
						END

					-- -----------------------------------------------------------------------------------------



					Fetch Next From cursor_IT_ID
					Into
						@tis_id,
						@tis_priority,
						@item_id,
						@tis_itemDesc,
						@tis_detail,
						@tis_curr_id,
						@tis_initQty,
						@tis_qty,
						@prli_id,
						@tis_price,
						@stor_id,
						@doc_id,
						@tis_CD,
						@soh_id,
						@sod_id,
						@tis_insertDate,
						@aure_id,
						@tax_id,
						@aure_itemComposed,
						@tis_itemDiscount,
						@tis_CreditInt,
						@tis_CreditIntPlus,
						@tis_itemDiscountTotal,
						@tis_totalDiscountTotal,
						@tis_isQuotation,
						@tis_isCredit,
						@tis_production,
						@so_id,
						@strNote1,
						@strNote2,
						@tis_cost,
						@tis_id_origin,
						@tis_item_id_origin,
						@tis_isMade,
						@it_transaction_original,
						@rmah_id,
						@rmad_id,
						@decItemDiscount,
						@intTis_IdOfThisEW,
						@decForcedCost,
						@intCampId,
						@sdlmt_id,
						@it_loanNumberOfPays	,
						@sreas_id,
						@datDeliveryDate	,
						@sod_EWAddres,
						@bitIsPCConfig,
						@intPCConfigCTRLId,
						@item_idfromPreInvoice,
						@sod_MLCost,
						@ws_price,
						@ws_curr_id,
						@mlo_id,
						@tis_DeliveryCharge,
						@sod_MECost,
						@sod_MPCost,
						@tis_isDivided_costCoeficient,
						@tis_disablePrintInEmmition,
						@wscup_id,
						@tis_discountPlan,
						@tis_itemDiscount2,
						@tis_itemDiscountTotal2
			End

		Close cursor_IT_ID
		DEALLOCATE cursor_IT_ID



		---- -----------------------------------------------------------------------------------------
		---- Actualiza los Remitos seleccionados para Facturar poniendo el campo de Pendiente en False
		---- -----------------------------------------------------------------------------------------
		--UPDATE tbItemTransactions		WITH (ROWLOCK)
		--SET
		--	it_packingInvoicePend		= 'False',
		--	it_packingInvoiceSelected	= 'false'
		--WHERE	it_packingInvoiceSelectedGuid				= @tis_guid
		--	AND IsNull(it_packingInvoiceSelected,'False')	= 'True'
		---- -----------------------------------------------------------------------------------------

	---- Pone el MLO_ID en tbCommercialtransactions para cuando se borra un item cargado desde ml del pedido y se reemplaza por otro
	---- por lo que el mlo_id NO estara en tbItemTransactions pero si estara en tbCommercialtransactions
	---- para cuando se genera la cobranza
	--IF @mlo_id4CommercialTransactions IS NOT NULL
	--	BEGIN
	--		UPDATE tbCommercialTransactions
	--			SET mlo_id = @mlo_id4CommercialTransactions
	--			WHERE	comp_id			= @comp_id			AND
	--					bra_id			= @bra_id			AND
	--					ct_transaction	= @ct_transaction	AND
	--					mlo_id			IS NULL
	--	END



		--SELECT 1 / 0

    END TRY
    BEGIN CATCH
		IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT_905		-- MOS 06-2020
        --ROLLBACK TRANSACTION traPROTECT_905
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)
    END CATCH
    --IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT_905			-- MOS 06-2020

END
GO








-- -------------------------------------------------------------------------------------------------------------------------
-- ATENCION: SI SE MODIFICA ESTE SP SE DEBE REALIZAR LA MISMA MODIFICACION EN [spItemTransactions_insertData_ForPurchase]
-- -------------------------------------------------------------------------------------------------------------------------
CREATE  PROCEDURE [dbo].[spItemTransactions_insertData_ForBranchTransfer]
(
	@comp_id					int,
	@bra_id						int,
	@ct_transaction				int,
	@guid						uniqueidentifier,
	@currSupplier				int,
	@currBranch					int,
	@exchange					decimal(38,15),
	@isAvailableForImport		BIT,
	@updateInvoicePend			BIT,
	@updateCost					BIT,
	@return_value				as int			output,
	@ret_ErrorCode				as int			output,
	@ret_ErrorDescription		as varchar(200) output
)
AS

BEGIN

--DECLARE @www AS DECIMAL(19,3)

	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-04
	-- Parte		: 429
	-- Description	: Actualización de los valores de estiba y picking en tbItemStorage a partir de los valores
	--				  obtenidos de tbItemTransactionsTmp
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-09-03
	-- Referencia	: #1
	-- Description	: solo actualiza si es factura, remito y despacho (101,102,130)
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-10-14
	-- Parte		: 616
	-- Description	: se cambia la forma de actualizar el campo it_packingInvoicePend de tbItemTransactions y NO se
	--				  actualizan los costos, los despachos y los números de serie para los items que se cargan en la
	--				  factura que se tomaron de remitos y se actualiza en false el campo it_packingInvoicePend de la tabla
	--				  tbItemTransactions para los items que se tomaron de remitos
	-- =================================================================================================================
	-- =================================================================================================================
	-- Author		: STL
	-- Update Date	: 2010-10-25
	-- Parte		: 643
	-- Description	: Se agrega la actualización del campo item_recentlyPurchased con el valor TRUE en
	--				  tbItem para los items que se ingresaron siempre y cuando, sean Facturas o Remitos
	--
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-12-04
	-- Parte		: 709
	-- Description	: Se agrega la actualización de los nuevos campos impData_Origin y impData_From en la tabla tbImportData
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-12-06
	-- Parte		: 683
	-- Description	: Se agrega la actualización de costos dependiendo del @updateCost
	-- =================================================================================================================




	BEGIN

	-- ------------------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------------------
	/*
	declare	@comp_id				int ,
			@bra_id					int ,
			@ct_transaction			int ,
			@guid					uniqueidentifier ,
			@currSupplier			int ,
			@currBranch				int ,
			@exchange				decimal(18,5),
			@isAvailableForImport		Bit,
			@return_value				as int			,
			@ret_ErrorCode				as int			,
			@ret_ErrorDescription		as varchar(200)
	select	@comp_id				= 1,
			@bra_id					= 1,
			@ct_transaction			= 5207,
			@guid					= 'ce0e7c98-4503-4f4e-aba6-e8c3278f6fee',
			@currSupplier			= 1,
			@currBranch				= 1,
			@exchange				= 1,
			@isAvailableForImport = 'false'
	--DROP TABLE #tmpITT
	*/
	-- ------------------------------------------------------------------------------------------


		Set @return_value			= 0
		Set @ret_ErrorCode			= 0
		Set @ret_ErrorDescription	= ''



		BEGIN TRY

			-- --------------------------------------------
			-- Obtiene Descuentos Generales del Comprobante
			-- --------------------------------------------
			DECLARE @Discount1 AS DECIMAL(19,6)
			DECLARE @Discount2 AS DECIMAL(19,6)
			DECLARE @Discount3 AS DECIMAL(19,6)
			DECLARE @Discount4 AS DECIMAL(19,6)
			SELECT	@Discount1 = tct.ct_Discount1,
					@Discount2 = tct.ct_Discount2,
					@Discount3 = tct.ct_Discount3,
			        @Discount4 = tct.ct_Discount4
				FROM tbCommercialTransactions tct	WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id AND
						tct.ct_transaction	= @ct_transaction
			-- --------------------------------------------


			-- ------------------------------------------------------------------
			-- Obtiene el Proveedor
			-- ------------------------------------------------------------------
			DECLARE @supp_id AS INT
			SELECT @supp_id = tct.supp_id
				FROM tbCommercialTransactions tct	WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id
					AND tct.ct_transaction	= @ct_transaction
			-- ------------------------------------------------------------------

			-- --------------------------------------------------------------------
			-- MOS: Damos de alta en el deposito los items x storage que no existen
			-- --------------------------------------------------------------------
			insert into dbo.[tbItemStorage]
			(		[comp_id],
					[stor_id],
					[item_id],
					[itst_cant],
					[itst_cd],
					itst_PickingLocation,		-- Parte : 429
					itst_StorageLocation		-- Parte : 429
			)
				select distinct	itt.comp_id,
						itt.stor_id,
						itt.item_id,
						0 ,
						NULL,
						'',	-- Parte : 429
						''	-- Parte : 429

					from	dbo.tbItemTransactionsTmp						itt		WITH (NOLOCK)

						where	itt.comp_id		=	@comp_id
						and		itt.tis_guid	=   @guid
						and		not itt.item_id is null
						and     itt.item_id not in	(
														select it.item_id
															from	dbo.[tbItemStorage]	it		WITH (NOLOCK)
															where	it.[comp_id]	= itt.comp_id
															and		it.[item_id]	= itt.item_id
															and		it.[stor_id]	= itt.stor_id
													)
			-- --------------------------------------------------------------------

			-- --------------------------------------------------------------------
			/* obtenemos los items que si están en los depósitos con la cantidad ingresada */
			-- --------------------------------------------------------------------
			select	itt.comp_id,
					itt.stor_id,
					itt.item_id,
					case vctfp.sd_isCredit
						WHEN 'True'						THEN itt.tis_qty * -1
														ELSE itt.tis_qty
					END						[tis_qty],
					ISNULL(it.itst_cant,0)	[itst_cant],
					itt.tis_PickingLocation,	-- Parte : 429
					itt.tis_StorageLocation, 	-- Parte : 429
					itt.tis_id				[tisId],
					itt.it_transaction
				INTO	#tmpITT
				from	dbo.tbItemTransactionsTmp								itt		WITH (NOLOCK)

				LEFT JOIN 	dbo.[tbItemStorage]									it		WITH (NOLOCK)
				on		it.[comp_id]			=	itt.comp_id
				and		it.[item_id]			=	itt.item_id
				and		it.[stor_id]			=	itt.stor_id

				INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
					ON	tct.comp_id			= itt.comp_id
					AND tct.bra_id			= itt.bra_id
					AND tct.ct_transaction	= @ct_transaction

				INNER JOIN dbo.tbsysDocuments 		vctfp		WITH (NOLOCK)
					ON	vctfp.sd_id 		=	tct.sd_id

				where	itt.comp_id		=	@comp_id
				and		itt.tis_guid	=   @guid
				and		not itt.item_id is NULL
			-- --------------------------------------------------------------------

			-- --------------------------------------------------------------------
			-- debo recorrer la tabla temporal #tmpITT y verificar si ya existe el item anteriormente.  De ya existir debo sumarle el stock
			-- total que ingreso por los items anteriores al campo itst_cant para que pondere bien si hay dos items en el mismo ingreso.
			-- MOS 03-2011
			-- --------------------------------------------------------------------
			UPDATE 		#tmpITT
				SET itst_cant = isnull(itst_cant,0) +
							    ISNULL((SELECT SUM(tmp1.tis_qty)
											FROM #tmpITT tmp1
											WHERE	tmp1.tisId		< tmp.tisId
												AND tmp1.item_id	= tmp.item_id
												AND tmp1.comp_id	= tmp.comp_id
												AND tmp1.stor_id	= tmp.stor_id ),0)
			FROM #tmpITT tmp
			-- --------------------------------------------------------------------



			-- --------------------------------------------------------------------------------------------------------------------------
			-- Se Actualiza la cantidad del stock.
			-- No se puede usar UPDATE ya que si se actualiza la misma id solo pone la ultima, o sea, no va haciendo un commit de cada actualizacion
			-- --------------------------------------------------------------------------------------------------------------------------
			DECLARE @curStor_id AS INT,
					@curItem_Id AS INT,
					@curtis_qty AS DECIMAL(19,6),
					@cur_itst_cant AS decimal(19,6),
					@cur_tis_PickingLocation AS nVARCHAR(MAX),
					@cur_tis_StorageLocation AS NVARCHAR(MAX),
					@curTis_id	AS INT,
					@curIt_Transaction AS INT
			DECLARE  curUpdateItemStorage CURSOR LOCAL  FAST_FORWARD FOR
					SELECT
						stor_id,
						item_id,
						tis_qty,
						itst_cant,
						ISNULL(tis_PickingLocation,'')			[tis_PickingLocation],	-- Parte : 429
						ISNULL(tis_StorageLocation,'')			[tis_StorageLocation], 	-- Parte : 429
						tisId,
						it_transaction
					FROM #tmpITT
					WHERE it_transaction IS NULL -- que no venga de un remito ingresado anrteriormente

			OPEN  curUpdateItemStorage
			FETCH NEXT FROM curUpdateItemStorage
				INTO	@curStor_id,
						@curItem_Id,
						@curtis_qty,
						@cur_itst_cant,
						@cur_tis_PickingLocation,
						@cur_tis_StorageLocation,
						@curTis_id,
						@curIt_Transaction

			WHILE @@FETCH_STATUS = 0
			BEGIN
				--** qwlhdkqw92387aqwdnqwdn12445
				UPDATE	dbo.tbItemStorage		WITH (ROWLOCK)
					SET		dbo.tbItemStorage.itst_cant				= its.itst_cant + @curtis_qty,
							dbo.tbItemStorage.itst_cd				= GETDATE(),
							dbo.tbItemStorage.itst_PickingLocation	= REPLACE(
																		IsNull(its.itst_PickingLocation,'') +	CASE
							                                      													WHEN IsNull(its.itst_PickingLocation,'') <> '' THEN ','
							                                      													ELSE ''
							                                      												END + dbo.fnAddStringIfNotExists(IsNull(its.itst_PickingLocation,''),@cur_tis_PickingLocation)  --MOS 02-2023 x SO18276   --- @cur_tis_PickingLocation,	-- Parte : 429
							                                      			,',,',','),
							dbo.tbItemStorage.itst_StorageLocation	=	REPLACE(
																		IsNull(its.itst_StorageLocation,'') +	CASE
							                                      													WHEN IsNull(its.itst_StorageLocation,'') <> '' THEN ','
							                                      													ELSE ''
							                                      												END + dbo.fnAddStringIfNotExists(IsNull(its.itst_StorageLocation,''),@cur_tis_StorageLocation)   --MOS 02-2023 x SO18276   --- @cur_tis_StorageLocation 	-- Parte : 429
							                                      				,',,',',')
						FROM	dbo.tbItemStorage							its
						WHERE	its.comp_id = @comp_id
							AND its.item_id = @curItem_Id
							AND its.stor_id = @curStor_id

				FETCH NEXT FROM curUpdateItemStorage
					INTO	@curStor_id,
							@curItem_Id,
							@curtis_qty,
							@cur_itst_cant,
							@cur_tis_PickingLocation,
							@cur_tis_StorageLocation,
							@curTis_id,
							@curIt_Transaction

			END
			CLOSE curUpdateItemStorage
			DEALLOCATE curUpdateItemStorage
			-- --------------------------------------------------------------------------------------------------------------------------


			-- ==============================================================================================================
			-- 2010-10-13 - MOH - Parte:616 - Se obtiene el sd_id para actualizar el it_packingInvoicePend en base al sd_id
			/*Agregado para Serializar solo cuando es Factura o Remito, recuperando el SD_ID de la Commercial Transactions*/
			DECLARE	@sd_id INT
			SELECT	@sd_id = sd_id
				FROM	tbCommercialTransactions tct		WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id
					--AND tct.bra_id			= @bra_id
					AND tct.ct_transaction	= @ct_transaction
			-- ==============================================================================================================




			/* agregamos los items en itemTransactions */
			insert into dbo.tbItemTransactions
					-- it_OriginalPrice, it_OriginalPriceCurrency estos son el precio y cambio
			(		comp_id,
					bra_id,
					ct_transaction,
					item_id,
					it_qty,								-- it_priceWithOutOthers,
					it_price,
					curr_id,
					it_priceOfCostPP,
					it_priceOfCostLastPurchase,
					it_priceBOfCostLastPurchase,
					it_OriginalPriceCurrency,
					it_exchangeToOriginalPriceCurrency,
					stor_id,
					prli_id,
					it_cd,
					it_packingInvoicePend,
					so_id,
					it_guarantee,
					it_itemDiscountTotal,
					it_totalDiscountTotal,
					it_CreditInt,
					it_CreditIntPlus,
					it_priceBOfCostPP,
					it_priceOfCost,
					it_priceBOfCost,
					it_OriginalPrice,
					it_storePrevious,
					it_order,
					puco_id,
					it_exchangeToBranchCurrency,
					it_poh_id,
					it_poh_bra_id,
					it_tis_id_aux,
					it_priceB,
					tmp_tis_id,
					it_transaction_NoStockDiscount,

					it_transaction_related4BranchTransfer,
					stor_id_related4BranchTransfer,

					it_packingInvoicePendOriginal,
					it_Discount1,
					it_Discount2,
					it_Discount3,
					it_Discount4,
					it_priceWithOutOthers
			)
			(select
					@comp_id,
					@bra_id,
					@ct_transaction,
					ItTmp.item_id,
					ItTmp.tis_qty,		--Null,
				ItTmp.tis_price * dbo.fnGetFinalDiscountCoeficient(ittmp.tis_Discount1,ItTmp.tis_Discount2,ItTmp.tis_Discount3,ItTmp.tis_Discount4) * dbo.fnGetFinalDiscountCoeficient(@discount1 ,@discount2,@discount3,@discount4),
				ItTmp.curr_id,
					null,
					null,
					null,
					1,
					null,
					ItTmp.stor_id,
				ItTmp.prli_id,
				ItTmp.tis_CD,
					'False',
				ItTmp.so_id,
				ItTmp.tis_guarantee,
				ItTmp.tis_itemDiscountTotal,
				ItTmp.tis_totalDiscountTOTAL,
				ItTmp.tis_CreditInt,
				ItTmp.tis_CreditIntPlus,					0,
					0,									0,									0,
					isnull(itt.itst_cant,0),			0,
				ItTmp.puco_id,
					dbo.[fnGetExchange2](@comp_id, 1, ItTmp.curr_id, @currBranch, @currBranch,@currSupplier, @exchange, 0),
				ItTmp.poh_id,
				ItTmp.tis_poh_bra_id,
				ItTmp.tis_id,
				ItTmp.tis_PriceB,
				ItTmp.tis_id,
					'False',
					ItTmp.it_transaction4BranchTransfer	 ,
					tit.stor_id ,
					'False'	,
                    IsNull(ItTmp.tis_Discount1,0),
                    IsNull(ItTmp.tis_Discount2,0),
                    IsNull(ItTmp.tis_Discount3,0),
                    IsNull(ItTmp.tis_Discount4,0),
                    ItTmp.tis_price
				from	dbo.tbItemTransactionsTmp		ItTmp	WITH (NOLOCK)
				left JOIN #tmpITT			itt
				ON		ItTmp.comp_id	=	itt.comp_id
					AND ItTmp.stor_id	=	itt.stor_id
					AND ItTmp.item_id	=	itt.item_id
					AND ItTmp.tis_id	=   itt.tisId
				INNER JOIN tbItemTransactions			tit		WITH (NOLOCK)
					ON	tit.comp_id			= ItTmp.comp_id			 AND
						tit.it_transaction	= ItTMP.it_transaction4BranchTransfer
				where	ItTmp.comp_id		=	@comp_id
				and		ItTmp.tis_guid		= @guid
			)




			-- Le pone al ItTransaction ORIGINAL los datos de la recepcion
			UPDATE tbItemTransactions		WITH (rowlock	)
				SET	stor_id_related4BranchTransfer			= ItTmp.stor_id ,
					it_transaction_related4BranchTransfer	= (	SELECT TOP 1  titNew.it_transaction
				                                         	   		FROM tbItemTransactions titNew	WITH (NOLOCK)
				                                         			WHERE  titNew.it_transaction_related4BranchTransfer = tit.it_transaction )
				FROM tbItemTransactions					tit
				INNER JOIN tbItemTransactionsTmp		ItTmp	WITH (NOLOCK)
					ON	ItTmp.comp_id							= tit.comp_id			AND
						ItTmp.it_transaction4BranchTransfer		= tit.it_transaction
				where	ItTmp.comp_id		=	@comp_id			AND
						ItTmp.tis_guid		=   @guid







			-- ===============================================================================================================
			-- 2010-10-25 - STL - Parte:643 - se actualiza en TRUE el campo item_recentlyPurchased de la tabla
			-- tbItem para los items que se ingresaron siempre y cuando, sean Facturas o Remitos
			IF @sd_id = 101 OR @sd_id = 103
				BEGIN
					UPDATE	tbItem
						SET		item_recentlyPurchased	= 'True'
						FROM	tbItem										ti		WITH (NOLOCK)
						INNER JOIN tbItemTransactionsTmp			titt	WITH (NOLOCK)
							ON	titt.comp_id			= ti.comp_id
							AND titt.item_id			= ti.item_id
						WHERE 	titt.comp_id				= @comp_id
						AND 	titt.tis_guid				= @guid
				END

			-- ===============================================================================================================










			-- ===============================================================================================================
			-- 2010-10-13 - MOH - Parte:616 - se actualiza en false el campo it_packingInvoicePend de la tabla
			-- tbItemTransactions para los items que se tomaron de remitos
			UPDATE	tbItemTransactions
				SET		it_packingInvoicePend		= 'false'
				FROM	tbItemTransactions					tit		WITH (NOLOCK)
						INNER JOIN tbItemTransactionsTmp	titt	WITH (NOLOCK)
						ON	titt.comp_id			= tit.comp_id
						AND titt.it_transaction		= tit.it_transaction
				WHERE 	titt.comp_id				= @comp_id
				AND 	titt.tis_guid				= @guid
			-- ===============================================================================================================





	--		/* recorremos los items cargados para crear la lista vacía de items que necesitan serialización
	--		   y actualizamos la tabla importData */
			declare @lit_transaction	int,
					@litem_id			int,
					@lit_qty			decimal(19,6),
					@lstor_id			int,
					@litem_expser		Bit,
					@lPrice			As  Decimal(19,6),
					@lcurr_id		As  Int,
					@lstorePrevious As	Decimal(19,6),
					@lPriceB		As  Decimal(19,6)

			DECLARE @impData_Custom_local	AS VARCHAR(20)
			DECLARE @impData_Number_local	AS VARCHAR(20)
			DECLARE @impData_Origin			AS VARCHAR(100) --Parte : 709
			DECLARE @impData_From			AS VARCHAR(100) --Parte : 709
			DECLARE @stor_id				AS int




		END TRY
		BEGIN CATCH
				Set @return_value			= -1
				Set @ret_ErrorCode			= -1
				Set @ret_ErrorDescription	= 'spItemTransactions_insertData_ForBranchTransfer-' +
					(SELECT
					convert(varchar,ERROR_NUMBER())		+ '-' +
					convert(varchar,ERROR_SEVERITY())	+ '-' +
					convert(varchar,ERROR_STATE())		+ '-' +
					convert(varchar,ERROR_LINE())		+ '-' +
					ERROR_MESSAGE())

		END CATCH

	END

END

GO







-- Updated:   MOS  03-2009
-- -----------------------------------------------------------------------------------------------------------------------------
-- ATENCION: SI SE MODIFICA ESTE SP SE DEBE REALIZAR LA MISMA MODIFICACION EN [spItemTransactions_insertData_ForBranchTransfer]
-- -----------------------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[spItemTransactions_insertData_ForPurchase]
(
	@comp_id					int,
	@bra_id						int,
	@ct_transaction				int,
	@guid						uniqueidentifier,
	@currSupplier				int,
	@currBranch					int,
	@exchange					decimal(38,15),
	@isAvailableForImport		BIT,
	@updateInvoicePend			BIT,
	@updateCost					BIT,
	@user_id					INT,
	@return_value				as int			output,
	@ret_ErrorCode				as int			output,
	@ret_ErrorDescription		as varchar(600) output
)
AS

BEGIN

	-- OK- 09-04-2015

	SET NOCOUNT ON



	BEGIN

	-- ------------------------------------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------------------------------------
	/*
	declare	@comp_id				int ,
			@bra_id					int ,
			@ct_transaction			int ,
			@guid					uniqueidentifier ,
			@currSupplier			int ,
			@currBranch				int ,
			@exchange				decimal(18,5),
			@isAvailableForImport		Bit,
			@return_value				as int			,
			@ret_ErrorCode				as int			,
			@ret_ErrorDescription		as varchar(200)
	select	@comp_id				= 1,
			@bra_id					= 1,
			@ct_transaction			= 5207,
			@guid					= 'ce0e7c98-4503-4f4e-aba6-e8c3278f6fee',
			@currSupplier			= 1,
			@currBranch				= 1,
			@exchange				= 1,
			@isAvailableForImport = 'false'
	--DROP TABLE #tmpITT
	*/
	-- ------------------------------------------------------------------------------------------


	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''

	DECLARE @strDebug AS NVARCHAR(500) = ''

	DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT_955		-- MOS 06-2020
    --SAVE TRANSACTION traPROTECT
    --BEGIN TRANSACTION
    BEGIN TRY





		--BEGIN TRY

			-- --------------------------------------------
			-- Obtiene Descuentos Generales del Comprobante
			-- --------------------------------------------
			DECLARE	@sd_id INT
			DECLARE @supp_id AS INT
			DECLARE @bra_id_transaction AS INT = @bra_id
			DECLARE @Discount1 AS DECIMAL(19,6)
			DECLARE @Discount2 AS DECIMAL(19,6)
			DECLARE @Discount3 AS DECIMAL(19,6)
			DECLARE @Discount4 AS DECIMAL(19,6)
			SELECT	@Discount1	 = tct.ct_Discount1,
					@Discount2	= tct.ct_Discount2,
					@Discount3	= tct.ct_Discount3,
			        @Discount4	= tct.ct_Discount4,
			        @supp_id	= tct.supp_id,
			        @sd_id		= sd_id,
			        @bra_id_transaction = tct.bra_id
				FROM tbCommercialTransactions tct	WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id AND
						tct.ct_transaction	= @ct_transaction
			-- --------------------------------------------


			-- ------------------------------------------------------------------
			-- Obtiene el Proveedor
			-- ------------------------------------------------------------------
			--MOS 04-2021  se paso ´para arriba-
			--SELECT @supp_id = tct.supp_id, se paso arriba
			--	FROM tbCommercialTransactions tct		WITH (NOLOCK)
			--	WHERE	tct.comp_id			= @comp_id
			--		AND tct.ct_transaction	= @ct_transaction
			-- ------------------------------------------------------------------

			-- --------------------------------------------------------------------
			-- MOS: Damos de alta en el deposito los items x storage que no existen
			-- --------------------------------------------------------------------
			insert into dbo.[tbItemStorage]
			(		[comp_id],
					[stor_id],
					[item_id],
					[itst_cant],
					[itst_cd],
					itst_PickingLocation,		-- Parte : 429
					itst_StorageLocation		-- Parte : 429
			)
				select distinct	itt.comp_id,
						itt.stor_id,
						itt.item_id,
						0 ,
						NULL,
						'',	-- Parte : 429
						''	-- Parte : 429

					from	dbo.tbItemTransactionsTmp						itt WITH (NOLOCK)
					LEFT JOIN tbItemStorage									it	WITH (NOLOCK)
						ON	it.[comp_id]	= itt.comp_id	AND
							it.[item_id]	= itt.item_id	AND
							it.[stor_id]	= itt.stor_id

					where	itt.comp_id		=	@comp_id	AND
							itt.tis_guid	=   @guid		AND
							itt.item_id IS NOT NULL			AND
							it.comp_id  IS NULL
											-- LENTO x MOS 07-2017
											--not in	(
											--			select it.item_id
											--				from	dbo.[tbItemStorage]	it	WITH (NOLOCK)
											--				where	it.[comp_id]	= itt.comp_id
											--				and		it.[item_id]	= itt.item_id
											--				and		it.[stor_id]	= itt.stor_id
											--		)
			-- --------------------------------------------------------------------

			-- --------------------------------------------------------------------
			/* obtenemos los items que si están en los depósitos con la cantidad ingresada */
			-- --------------------------------------------------------------------
			select	itt.comp_id,
					itt.stor_id,
					itt.item_id,
					case vctfp.sd_isCredit
						WHEN 'True' THEN	itt.tis_qty * -1
						ELSE				itt.tis_qty
					END					[tis_qty],
					it.itst_cant,
					itt.tis_PickingLocation,	-- Parte : 429
					itt.tis_StorageLocation, 	-- Parte : 429
					itt.tis_id			[tisId],

					itt.it_transaction

				INTO	#tmpITT

				from	dbo.tbItemTransactionsTmp								itt WITH (NOLOCK)

				INNER JOIN 	dbo.[tbItemStorage]							it
					on		it.[comp_id]			=	itt.comp_id
					and		it.[item_id]			=	itt.item_id
					and		it.[stor_id]			=	itt.stor_id

				INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
					ON	tct.comp_id			= itt.comp_id
					--AND tct.bra_id			= itt.bra_id   HDPPPPPPPPP
					AND tct.ct_transaction	= @ct_transaction

				INNER JOIN dbo.tbsysDocuments 		vctfp		WITH (NOLOCK)
					ON	vctfp.sd_id 		=	tct.sd_id

			where	itt.comp_id		=	@comp_id
			and		itt.tis_guid	=   @guid
			and		not itt.item_id is NULL
			-- --------------------------------------------------------------------

			-- --------------------------------------------------------------------
			-- debo recorrer la tabla temporal #tmpITT y verificar si ya existe el item anteriormente.  De ya existir debo sumarle el stock
			-- total que ingreso por los items anteriores al campo itst_cant para que pondere bien si hay dos items en el mismo ingreso.
			-- MOS 03-2011
			-- --------------------------------------------------------------------
			UPDATE 		#tmpITT
				SET itst_cant = isnull(itst_cant,0) +
							    ISNULL((SELECT SUM(tmp1.tis_qty)
									FROM #tmpITT tmp1
									WHERE	tmp1.tisId		< tmp.tisId
										AND tmp1.item_id	= tmp.item_id
										AND tmp1.comp_id	= tmp.comp_id
										AND tmp1.stor_id	= tmp.stor_id ),0)
				FROM #tmpITT tmp
			-- --------------------------------------------------------------------



			-- --------------------------------------------------------------------------------------------------------------------------
			-- Se Actualiza la cantidad del stock.
			-- No se puede usar UPDATE ya que si se actualiza la misma id solo pone la ultima, o sea, no va haciendo un commit de cada actualizacion
			-- --------------------------------------------------------------------------------------------------------------------------
			DECLARE @curStor_id AS INT,
					@curItem_Id AS INT,
					@curtis_qty AS DECIMAL(19,6),
					@cur_itst_cant AS decimal(19,6),
					@cur_tis_PickingLocation AS nVARCHAR(MAX),
					@cur_tis_StorageLocation AS NVARCHAR(MAX),
					@curTis_id	AS INT,
					@curIt_Transaction AS INT
			DECLARE  curUpdateItemStorage CURSOR LOCAL FAST_FORWARD FOR
					SELECT
						stor_id,
						item_id,
						tis_qty,
						itst_cant,
						dbo.fnStrAllTrim(ISNULL(tis_PickingLocation,'')),	-- Parte : 429
						dbo.fnStrAllTrim(ISNULL(tis_StorageLocation,'')), 	-- Parte : 429
						tisId,
						it_transaction
					FROM #tmpITT
					WHERE it_transaction IS NULL -- que no venga de un remito ingresado anrteriormente

			OPEN  curUpdateItemStorage
			FETCH NEXT FROM curUpdateItemStorage
				INTO	@curStor_id,
						@curItem_Id,
						@curtis_qty,
						@cur_itst_cant,
						@cur_tis_PickingLocation,
						@cur_tis_StorageLocation,
						@curTis_id,
						@curIt_Transaction

			WHILE @@FETCH_STATUS = 0
				BEGIN

					UPDATE	dbo.tbItemStorage		WITH (ROWLOCK)
						SET		dbo.tbItemStorage.itst_cant				= its.itst_cant + @curtis_qty,
								dbo.tbItemStorage.itst_cd				= GETDATE(),
								dbo.tbItemStorage.itst_PickingLocation	=	CASE		-- MOS 07-2022, antes siempre ponia el valor del cursor y pisaba o borraba si el cursor estaba en blanco
																				WHEN @cur_tis_PickingLocation = '' THEN its.itst_PickingLocation
																				ELSE									@cur_tis_PickingLocation
																			END,	-- Parte : 429
								dbo.tbItemStorage.itst_StorageLocation	=	CASE
																				WHEN @cur_tis_StorageLocation = '' THEN its.itst_StorageLocation
																				ELSE									@cur_tis_StorageLocation
																			END-- Parte : 429
							FROM	dbo.tbItemStorage							its
							WHERE	its.comp_id = @comp_id
								AND its.item_id = @curItem_Id
								AND its.stor_id = @curStor_id

					FETCH NEXT FROM curUpdateItemStorage
						INTO	@curStor_id,
								@curItem_Id,
								@curtis_qty,
								@cur_itst_cant,
								@cur_tis_PickingLocation,
								@cur_tis_StorageLocation,
								@curTis_id,
								@curIt_Transaction

				END
			CLOSE		curUpdateItemStorage
			DEALLOCATE	curUpdateItemStorage
			-- --------------------------------------------------------------------------------------------------------------------------

			-- MOS 04-2021, se pasa para arriba
			---- ==============================================================================================================
			---- 2010-10-13 - MOSH - Parte:616 - Se obtiene el sd_id para actualizar el it_packingInvoicePend en base al sd_id
			--/*Agregado para Serializar solo cuando es Factura o Remito, recuperando el SD_ID de la Commercial Transactions*/
			--DECLARE	@sd_id INT
			--SELECT	@sd_id = sd_id
			--	FROM	tbCommercialTransactions tct	WITH (NOLOCK)
			--	WHERE	tct.comp_id			= @comp_id
			--		AND tct.bra_id			= @bra_id
			--		AND tct.ct_transaction	= @ct_transaction
			---- ==============================================================================================================


			--SET @strDebug = '@comp_id:' + CONVERT(NVARCHAR(10),@comp_id) + ' / @bra_id:' + CONVERT(NVARCHAR(10),@bra_id) +' / @bra_id_transaction:' + CONVERT(NVARCHAR(10),@bra_id_transaction) + '/ @ct_transaction:' + CONVERT(NVARCHAR(19),@ct_transaction) + '/'


			/* agregamos los items en itemTransactions */
			insert into dbo.tbItemTransactions		WITH (ROWLOCK)
					-- it_OriginalPrice, it_OriginalPriceCurrency estos son el precio y cambio
			(		comp_id,							bra_id,								ct_transaction,
					item_id, 							it_qty,								-- it_priceWithOutOthers,
					it_price,							curr_id,							it_priceOfCostPP,
					it_priceOfCostLastPurchase,			it_priceBOfCostLastPurchase,		it_OriginalPriceCurrency,
					it_exchangeToOriginalPriceCurrency,	stor_id,							prli_id,
					it_cd,
					it_packingInvoicePend,
					so_id,
					it_guarantee,						it_itemDiscountTotal,				it_totalDiscountTotal,
					it_CreditInt, 						it_CreditIntPlus,					it_priceBOfCostPP,
					it_priceOfCost, 					it_priceBOfCost,					it_OriginalPrice,
					it_storePrevious,					it_order,							puco_id,
					it_exchangeToBranchCurrency,
					it_poh_id,							it_poh_bra_id,						it_tis_id_aux,
					it_priceB,							tmp_tis_id,

					it_transaction_NoStockDiscount,

					it_transaction_original,
					it_packingInvoicePendOriginal,
					it_Discount1,
					it_Discount2,
					it_Discount3,
					it_Discount4,
					it_priceWithOutOthers,
					it_isRMASupplierCreditNote,
					it_surcharge1,
					it_surcharge2,
					it_surcharge3,
					it_surcharge4,
					it_pod_id
			)
			(select
					@comp_id,						@bra_id_transaction	/* MOS 02-2022 x Arg @bra_id*/,							@ct_transaction,
					ItTmp.item_id,		ItTmp.tis_qty,		--Null,
					tis_price *
					-- Descuento del Item
					dbo.fnGetFinalDiscountCoeficient(ittmp.tis_Discount1,ItTmp.tis_Discount2,ItTmp.tis_Discount3,ItTmp.tis_Discount4)			*
					-- Recargo del Item
					dbo.fnGetFinalDiscountCoeficient(-ItTmp.tis_surcharge1,-ItTmp.tis_surcharge2,-ItTmp.tis_surcharge3,-ItTmp.tis_surcharge4)	 *
					-- Descuento del Documento
					dbo.fnGetFinalDiscountCoeficient(@discount1 ,@discount2,@discount3,@discount4),
														curr_id,							null,
					null,								null,								1,
					null,								ItTmp.stor_id,		prli_id,
					tis_CD,
					CASE
						WHEN @sd_id = 102 AND @updateInvoicePend = 'true' THEN 'true'
						ELSE 'false'
					END,	--2010-10-13 - MOSH - Parte: 616
					so_id,
					tis_guarantee,						tis_itemDiscountTotal,				tis_totalDiscountTOTAL,
					tis_CreditInt,						tis_CreditIntPlus,					0,
					0,									0,									0,
					isnull(itt.itst_cant,0),			0,									puco_id,
					dbo.[fnGetExchange2](@comp_id, 1, curr_id, @currBranch, @currBranch,@currSupplier, @exchange, 0),
					poh_id,								tis_poh_bra_id,						tis_id,
					tis_PriceB,							tis_id,
					--si no está informado el tbItemTransactionsTmp.it_transaction pone 'true'
					--en it_transaction_NoStockDiscount, sino pone 'false'
					CASE
						WHEN NOT ItTmp.it_transaction IS NULL THEN 'true'
						ELSE 'false'
					END,--2010-10-13 - MOSH - Parte: 616

					ItTmp.it_transaction,													--2010-10-13 - MOSH - Parte: 616
					CASE
						WHEN @sd_id = 102 AND @updateInvoicePend = 'true' THEN		'true'
						ELSE														'false'
					END	,	--2010-10-13 - MOSH - Parte: 616
                    IsNull(ItTmp.tis_Discount1,0),
                    IsNull(ItTmp.tis_Discount2,0),
                    IsNull(ItTmp.tis_Discount3,0),
                    IsNull(ItTmp.tis_Discount4,0),
                    ItTmp.tis_price,
                    ItTmp.it_isRMASupplierCreditNote,
                    IsNull(ItTmp.tis_surcharge1,0),
                    IsNull(ItTmp.tis_surcharge2,0),
                    IsNull(ItTmp.tis_surcharge3,0),
                    IsNull(ItTmp.tis_surcharge4,0),
                    ItTmp.pod_id

				from	dbo.tbItemTransactionsTmp		ItTmp		WITH (NOLOCK)

				left JOIN #tmpITT			itt
					ON	ItTmp.comp_id	=	itt.comp_id
					AND ItTmp.stor_id	=	itt.stor_id
					AND ItTmp.item_id	=	itt.item_id
					AND ItTmp.tis_id	=   itt.tisId

				where	ItTmp.comp_id		=	@comp_id
				and		ItTmp.tis_guid		=   @guid

			)





			-- ===============================================================================================================
			-- 2010-10-25 - STL - Parte:643 - se actualiza en TRUE el campo item_recentlyPurchased de la tabla
			-- tbItem para los items que se ingresaron siempre y cuando, sean Facturas o Remitos
			IF @sd_id = 101 OR @sd_id = 103
				BEGIN

					UPDATE	tbItem		WITH (ROWLOCK)
						SET		item_recentlyPurchased	= 'True'
						FROM	tbItem								ti
						INNER JOIN tbItemTransactionsTmp			titt	WITH (NOLOCK)
							ON	titt.comp_id			= ti.comp_id
							AND titt.item_id			= ti.item_id
						WHERE 	titt.comp_id				= @comp_id
						AND 	titt.tis_guid				= @guid

				END

			-- ===============================================================================================================



			-- -----------------------------------------------------------------------------
			-- Actualiza Pendientes de ingreso de Nota de credito de RMA por metodo 2
			-- -----------------------------------------------------------------------------
			UPDATE tbRMA_SupplierCreditNotePending				WITH (ROWLOCK)
				SET	rmanc_isProcessed	= 'True',
					ct_transaction		= @ct_transaction
				FROM tbRMA_SupplierCreditNotePending tmp1
				INNER JOIN tbItemTransactionsTmp titt			WITH (NOLOCK)
					ON	titt.comp_id		= tmp1.comp_id AND
						titt.rmanc_id		= tmp1.rmanc_id
				WHERE  titt.tis_guid = @guid
			-- -----------------------------------------------------------------------------





			-- ===============================================================================================================
			-- 2010-10-13 - MOSH - Parte:616 - se actualiza en false el campo it_packingInvoicePend de la tabla
			-- tbItemTransactions para los items que se tomaron de remitos
			UPDATE	tbItemTransactions										WITH (ROWLOCK)
				SET		it_packingInvoicePend		= 'false'
				FROM	tbItemTransactions					tit
				INNER JOIN tbItemTransactionsTmp			titt			WITH (NOLOCK)
					ON	titt.comp_id			= tit.comp_id
					AND titt.it_transaction		= tit.it_transaction
				WHERE 	titt.comp_id				= @comp_id
				AND 	titt.tis_guid				= @guid
			-- ===============================================================================================================





	--		/* recorremos los items cargados para crear la lista vacía de items que necesitan serialización
	--		   y actualizamos la tabla importData */
			DECLARE @lit_transaction	int,
					@litem_id			int,
					@lit_qty			decimal(19,6),
					@lstor_id			int,
					@litem_expser		Bit,
					@lPrice			As  Decimal(19,6),
					@lcurr_id		As  Int,
					@lstorePrevious As	Decimal(19,6),
					@lPriceB		As  Decimal(19,6)

			DECLARE @impData_Custom_local		AS VARCHAR(20)
			DECLARE @impData_Number_local		AS VARCHAR(20)
			DECLARE @impData_Origin				AS VARCHAR(100) --Parte : 709
			DECLARE @impData_From				AS VARCHAR(100) --Parte : 709
			DECLARE @stor_id					AS INT
			DECLARE @impData_ExpirationDate		AS DATETIME
			DECLARE @bitIsFromPackingOrPurOrdR  AS BIT
			SET		@bitIsFromPackingOrPurOrdR	= 'False'

			DECLARE @impdata_LotNumber			AS NVARCHAR(50)






			-- ===============================================================================================================
			-- 2010-10-13 - MOSH - Parte:616 - este código se pone antes del insert en tbItemTransactions
			/*Agregado para Serializar solo cuando es Factura o Remito, recuperando el SD_ID de la Commercial Transactions*/
	--		DECLARE @sd_id INT
	--		SELECT @sd_id = sd_id
	--		FROM tbCommercialTransactions tct
	--		WHERE tct.comp_id = @comp_id AND tct.bra_id = @bra_id AND tct.ct_transaction = @ct_transaction
			-- ================================================================================================================

			DECLARE @bitMustUpdateImportData AS BIT = 'False'


			declare cursor_items_IT CURSOR LOCAL FAST_FORWARD FOR
				select	it.it_transaction,
						it.item_id,
						it.it_qty,
						it.stor_id,
						i.item_expser,
						it.it_price,
						it.curr_id,
						it.it_storePrevious,
						titt.tis_impData_Custom_local,
						titt.tis_impData_Number_local,
						titt.tis_PriceB,
						titt.tis_impData_Origin, --Parte : 709
						titt.tis_impData_From,	 --Parte : 709
						it.stor_id,
						titt.tis_impData_ExpirationDate,
						CASE
							WHEN	titt.it_transaction IS NULL THEN	'False'
							ELSE										'True'
						END										[IsFromPackingOrPurOrdRec],  -- Si es TRUE es un item q viene de un remito o recepcion de o.compra.
						titt.tis_impdata_LotNumber

					FROM	tbItemTransactions						it		WITH (NOLOCK)
							INNER JOIN tbItem						i		WITH (NOLOCK)
								ON	i.comp_id		=	it.comp_id
								AND i.item_id		=	it.item_id
							INNER JOIN tbItemTransactionsTmp		titt	WITH (NOLOCK)
								ON	titt.tis_id		=	it.it_tis_id_aux
								--AND titt.it_transaction IS NULL					-- 2010-10-14 - MOSH - Parte: 616   (Si no es Factura de Remito . . .!!!)
					where	it.comp_id			=	@comp_id
					and		it.bra_id			=   @bra_id
					and		it.ct_transaction	=	@ct_transaction


			open cursor_items_IT

			fetch	cursor_items_IT
			into	@lit_transaction,
					@litem_id,
					@lit_qty,
					@lstor_id,
					@litem_expser,
					@lPrice,
					@lcurr_id,
					@lstorePrevious,
					@impData_Custom_local,
					@impData_Number_local,
					@lPriceB,
					@impData_Origin,	--Parte : 709
					@impData_From,		--Parte : 709
					@stor_id,
					@impData_ExpirationDate,
					@bitIsFromPackingOrPurOrdR,
					@impdata_LotNumber

			-- OJO.!
			-- Todo lo que esta en este cursor no es una factura ingresada desde un remito.!!!
			while @@FETCH_STATUS = 0
				begin

					--IF @updateInvoicePend = 'false'
						BEGIN

							-- ----------------------------------------------------
							-- Serializacion de Compras
							-- ----------------------------------------------------
							if	@bitIsFromPackingOrPurOrdR = 'False' AND
								@litem_expser = 'True' AND (@sd_id = 101 OR			-- Factura
														    @sd_id = 102 OR			-- Remito
														    @sd_id = 104 OR			-- Nota de Debito
														    @sd_id = 130 OR			-- Despacho
														    @sd_id = 124)			-- Carga Inicial de Stock
								begin

									exec dbo.spItemSerials_insertQtyData
										@comp_id, @bra_id, @ct_transaction, @lit_transaction,
										@litem_id, @lstor_id, @lit_qty

								END

							IF @bitIsFromPackingOrPurOrdR = 'True' -- MOS 02-2021
								BEGIN
									SET @bitMustUpdateImportData = 'True'
								END
							-- ----------------------------------------------------

							-- ----------------------------------------------------
							-- Carga de Despachos
							-- ----------------------------------------------------
							IF  @bitIsFromPackingOrPurOrdR = 'False' AND
								(  @sd_id = 101 OR			-- Factura
								   @sd_id = 102 OR			-- Remito
								   @sd_id = 104 OR			-- Nota de Debito
								   @sd_id = 130 OR			-- Despacho
								   @sd_id = 124)			-- Carga Inicial de Stock
								BEGIN
									exec dbo.spImportData_insertData
														@comp_id,
														@litem_id,
														@lit_qty,
														@lit_qty,
														@ct_transaction,
														@lit_transaction,
														@bra_id,
														@impData_Custom_local,
														@impData_Number_local,
														@impData_Origin,	--Parte : 709
														@impData_From,		--Parte : 709
														@impData_ExpirationDate,
														@impdata_LotNumber
								END
							-- ----------------------------------------------------


							-- --------------------------------------------------------------------------
							-- MOS: Actualiza los Costos solo si debe hacerlo.
							-- --------------------------------------------------------------------------
							If  @updateCost = 'true'
								BEGIN

									DECLARE @decStockrevious AS DECIMAL(29,6)
									SET		@decStockrevious = ISNULL(@lstorePrevious,0)
									IF @bitIsFromPackingOrPurOrdR = 'True' -- Si viene de un remito o recep de o.compra se resta la cant recibida para que pondere correctamente.!
										BEGIN
											SET @decStockrevious = @decStockrevious - @lit_qty
										END


									Exec spItemCostList_UpdateFromPurchase	@comp_id,
																			@bra_id,
																			@litem_id,
																			@lit_qty,
																			@lPrice,
																			@lcurr_id,
																			@decStockrevious,
																			@currBranch	,
																			@currSupplier,
																			@exchange,
																			1,			-- Con Lista de Costos Original
																			@stor_id,
																			@supp_id,
																			@user_id

									IF @lPriceB <> 0 --(Para que no ejecute un trigger con precio cero ! ! !)
										BEGIN
											Exec spItemCostList_UpdateFromPurchase	@comp_id,
																					@bra_id,
																					@litem_id,
																					@lit_qty,
																					@lPriceB,
																					@lcurr_id,
																					@decStockrevious,
																					@currBranch	,
																					@currSupplier,
																					@exchange,
																					2,		-- Con Lista de Costos Alternativa
																					@stor_id,
																					@supp_id,
																					@user_id
										END

								END

						-- --------------------------------------------------------------------------
						END

					fetch	cursor_items_IT
					into	@lit_transaction,
							@litem_id,
							@lit_qty,
							@lstor_id,
							@litem_expser,
							@lPrice,
							@lcurr_id,
							@lstorePrevious,
							@impData_Custom_local,
							@impData_Number_local,
							@lPriceB,
							@impData_Origin,	--Parte : 709
							@impData_From,		--Parte : 709
							@stor_id,
							@impData_ExpirationDate,
							@bitIsFromPackingOrPurOrdR,
							@impdata_LotNumber


				end

			close cursor_items_IT
			deallocate cursor_items_IT




			-- -------------------------------------------------------------
			-- Si es una Fc que Viene desde un Remito actualiza los despachos
			-- MOS -  Fiesa - ticket 11917 - 02-2021
			-- -------------------------------------------------------------
			IF @sd_id = 101 AND @bitMustUpdateImportData = 'True'
				BEGIN
					declare cursor_items_IT_FROMinvoice CURSOR LOCAL FAST_FORWARD FOR
						select	it.it_transaction_original,
								titt.tis_impData_Custom_local,
								titt.tis_impData_Number_local,
								titt.tis_impData_Origin, --Parte : 709
								titt.tis_impData_From,	 --Parte : 709
								titt.tis_impData_ExpirationDate,
								titt.tis_impdata_LotNumber
							FROM	tbItemTransactions						it		WITH (NOLOCK)
									INNER JOIN tbItem						i		WITH (NOLOCK)
										ON	i.comp_id		=	it.comp_id
										AND i.item_id		=	it.item_id
									INNER JOIN tbItemTransactionsTmp		titt	WITH (NOLOCK)
										ON	titt.tis_id		=	it.it_tis_id_aux
										--AND titt.it_transaction IS NULL					-- 2010-10-14 - MOSH - Parte: 616   (Si no es Factura de Remito . . .!!!)
							where	it.comp_id			=	@comp_id
							and		it.bra_id			=   @bra_id
							and		it.ct_transaction	=	@ct_transaction
							AND		titt.it_transaction IS NOT NULL
							AND		@sd_id				= 101
							AND     (
										titt.tis_impData_Custom_local <> ''
										OR
										titt.tis_impData_Number_local <> ''
										OR
										titt.tis_impdata_LotNumber    <> ''
									)
					OPEN 		cursor_items_IT_FROMinvoice
					FETCH 		cursor_items_IT_FROMinvoice
						INTO 	@lit_transaction,
								@impData_Custom_local,
								@impData_Number_local,
								@impData_Origin,
								@impData_From,
								@impData_ExpirationDate,
								@impdata_LotNumber


					while @@FETCH_STATUS = 0
						BEGIN

							UPDATE tbimportdata	WITH (ROWLOCK)
								SET impData_Custom_local =		CASE
																	WHEN impData_Custom_local = '' OR impData_Custom_local IS NULL		THEN	@impData_Custom_local
																	ELSE																		impData_Custom_local
																END,
									impData_Number_local =		CASE
																	WHEN impData_Number_local = '' OR impData_Number_local IS NULL		THEN	@impData_Number_local
																	ELSE																		impData_Number_local
																END,
									impData_Origin =			CASE
																	WHEN impData_Origin = '' OR impData_Origin IS NULL					THEN	@impData_Origin
																	ELSE																		impData_Origin
																END,
									impData_From =				CASE
																	WHEN impData_From = '' OR impData_From IS NULL						THEN	@impData_From
																	ELSE																		impData_From
																END,
									impData_ExpirationDate =	CASE	-- OJO ESTE VA ASI!!!
																	WHEN impdata_LotNumber = '' OR impdata_LotNumber IS NULL OR impData_ExpirationDate IS NULL	THEN	@impData_ExpirationDate
																	ELSE																		impData_ExpirationDate
																END,
									impdata_LotNumber =			CASE
																	WHEN impdata_LotNumber = '' OR impdata_LotNumber IS NULL			THEN	@impdata_LotNumber
																	ELSE																		impdata_LotNumber
																END
								WHERE	comp_id			= @comp_id AND
										it_transaction	= @lit_transaction

							FETCH 		cursor_items_IT_FROMinvoice
								INTO 	@lit_transaction,
										@impData_Custom_local,
										@impData_Number_local,
										@impData_Origin,
										@impData_From,
										@impData_ExpirationDate,
										@impdata_LotNumber
						END
					CLOSE		cursor_items_IT_FROMinvoice
					DEALLOCATE	cursor_items_IT_FROMinvoice
				END
			-- -------------------------------------------------------------






			--//*actualizar los items en purchaseorders*//////////////////////////////////////////////////////////
			declare	@co_comp_id		int,
					@co_bra_id		int,
					@co_poh_id		int,
					@co_pod_id		int,
					@co_pod_qty		Decimal(19,6),
					@co_tis_qty		Decimal(19,6)

			declare cursor_orders CURSOR LOCAL FAST_FORWARD FOR
			select	tpod.comp_id,	tpod.bra_id,	tpod.poh_id,
					tpod.pod_id,	tpod.pod_qty,	titt.tis_qty
				from	dbo.tbItemTransactionsTmp					titt	WITH (NOLOCK)
						inner join dbo.tbPurchaseOrderDetail		tpod	WITH (NOLOCK)
						ON	tpod.comp_id	=	titt.comp_id
						AND tpod.bra_id		=	titt.tis_poh_bra_id
						AND tpod.poh_id		=	titt.poh_id
						AND tpod.pod_id		=	titt.pod_id
				where	titt.comp_id		=	@comp_id
				and		titt.tis_guid		=	@guid


			open cursor_orders

			fetch cursor_orders
			into	@co_comp_id,	@co_bra_id,		@co_poh_id,
					@co_pod_id,		@co_pod_qty,	@co_tis_qty

			while @@FETCH_STATUS = 0
				begin

					IF not @co_pod_qty > @co_tis_qty
						BEGIN

							/* si la cantidad ingresada en purchasedocsdetail es igual o mayor que la	*/
							/* de puchaseorderdetail sólo se actualiza el pod_isProcessed a 'True'		*/
							UPDATE	dbo.tbPurchaseOrderDetail
								SET		pod_isProcessed		= 'True',
										pod_initQty			= pod_qty
								WHERE	comp_id				= @co_comp_id
								AND		bra_id				= @co_bra_id
								AND		poh_id				= @co_poh_id
								AND		pod_id				= @co_pod_id

						END
					ELSE
						BEGIN


							/* si la cantidad ingresada en purchasedocsdetail es menor que la							*/
							/* de puchaseorderdetail se realiza un insert en purchaseorderdetail con la diferencia		*/
							/* entre la cantidad ingresada y la original y se realiza un update en purchaseorderdetail	*/
							/* del registro seleccionado actualizando el pod_isProcessed a 'True' y la cantidad con la	*/
							/* ingresada																				*/
							INSERT INTO tbPurchaseOrderDetail
								(	comp_id,
									bra_id,
									poh_id,
									item_id,
									curr_id,
									cont_id,
									pod_qty,
									pod_price,
									tax_id,
									pod_isProcessed,
									pod_obs,
									pod_priceB,
									pod_custom,
									pod_customNumber,
									pod_Discount1,
									pod_Discount2,
									pod_Discount3,
									pod_Discount4,
									djai_id,
									pod_initQty,
									pod_surcharge1,
									pod_surcharge2,
									pod_surcharge3,
									pod_surcharge4,
									pod_priceWithDiscountAndCharges,
									pod_id_from,
									pod_id_from_CD,	-- se usa para que en el trigger que auto asocia, si se actualizo este campo, NO asocie NADA de manera automática.  para los HDRMRP de CM
													-- --**sldkfnqw52353&%&%$#safdqwnqwfr		**lwqhf973249%&$#%$#%lkjnlkh  CM y LRCDTPM!
									pod_includeInAvailableStock		-- MOS 06-2023 x Marstech
								)
								SELECT	tpod.comp_id,
										tpod.bra_id,
										tpod.poh_id,
										tpod.item_id,
										tpod.curr_id,
										tpod.cont_id,
										@co_pod_qty -	@co_tis_qty,
										tpod.pod_price,
										tpod.tax_id,
										tpod.pod_isProcessed,
										tpod.pod_obs,
										tpod.pod_priceB,
										tpod.pod_custom,
										tpod.pod_customNumber,
										tpod.pod_Discount1,
										tpod.pod_Discount2,
										tpod.pod_Discount3,
										tpod.pod_Discount4,
										tpod.djai_id,
										tpod.pod_qty,
										tpod.pod_surcharge1,
										tpod.pod_surcharge2,
										tpod.pod_surcharge3,
										tpod.pod_surcharge4,
										tpod.pod_priceWithDiscountAndCharges,
										@co_pod_id,
										GETDATE(),	-- se usa para que en el trigger que auto asocia, si se actualizo este campo, NO asocie NADA de manera automática.
										pod_includeInAvailableStock	-- MOS 06-2023 x Marstech

									FROM	tbPurchaseOrderDetail				tpod	WITH (NOLOCK)
									WHERE 	tpod.comp_id		= @co_comp_id
									AND		tpod.bra_id			= @co_bra_id
									AND		tpod.poh_id			= @co_poh_id
									AND		tpod.pod_id			= @co_pod_id

							UPDATE 	tbPurchaseOrderDetail
								SET		pod_isProcessed		= 'True',
										pod_initQty			= pod_qty,
										pod_qty				= @co_tis_qty
								WHERE 	comp_id				= @co_comp_id
								AND		bra_id				= @co_bra_id
								AND		poh_id				= @co_poh_id
								AND		pod_id				= @co_pod_id

						END


					fetch cursor_orders
					into	@co_comp_id,	@co_bra_id,		@co_poh_id,
							@co_pod_id,		@co_pod_qty,	@co_tis_qty

				end

			close cursor_orders
			deallocate cursor_orders

			--//****************************************//////////////////////////////////////////////////////////


			-- Vuelve a tocar la fecha para que los precios actualizados queden con fecha
			-- anterior a la fecha del comprobante, esto es para los Orden 1..4 de wfmPurchaseDocsItemsDetail
			UPDATE tbCommercialTransactions WITH (ROWLOCK)
				SET ct_cd = GETDATE()
				WHERE	comp_id			= @comp_id AND
						ct_transaction	= @ct_transaction


		END TRY
		BEGIN CATCH
			--ROLLBACK TRANSACTION traPROTECT
			IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT_955		-- MOS 06-2020
			Set @return_value			= -1
			Set @ret_ErrorCode			= -1
			Set @ret_ErrorDescription	= 'spItemTransactions_insertData_ForPurchase-' +
		     							(SELECT
										@strDebug +							+ '-' +
										'ERROR_NUMBER: ' + convert(varchar,ERROR_NUMBER())		+ '-' +
										'ERROR_SEVERITY:' + convert(varchar,ERROR_SEVERITY())	+ '-' +
										'ERROR_STATE:' + convert(varchar,ERROR_STATE())		+ '-' +
										'ERROR_LINE:' + convert(varchar,ERROR_LINE())		+ '-' +
										'ERROR_MESSAGE:' + ERROR_MESSAGE())

			DECLARE @ErrorMessage   NVARCHAR(4000)
			DECLARE @ErrorSeverity  INT
			DECLARE @ErrorState     INT
			SELECT  @ErrorMessage    = @strDebug + ERROR_MESSAGE(),
					@ErrorSeverity   = ERROR_SEVERITY(),
					@ErrorState      = ERROR_STATE()
			IF      @ErrorState      = 0 SET @ErrorState = 1
	--==
		 -- NO PONER PLS:!!! RAISERROR (@ret_ErrorDescription,@ErrorSeverity,@ErrorState)
	--==
		END CATCH

		--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT

	END

END

GO







CREATE PROCEDURE [dbo].[spItemTransactions_InsertOneData]
(
	@comp_id							as int,
	@bra_id								as int,
	@ct_transaction						as int,
	@item_id							as Int,
	@it_qty								as decimal(19,5),
	@curr_id							as int,
	@stor_id							as Int,
	@AllowWithNoStock					AS BIT,

	@return_value						as int			OUTPUT,
	@ret_ErrorCode						as int			OUTPUT,
	@ret_ErrorDescription				as varchar(200) OUTPUT
)
AS

BEGIN




	SET NOCOUNT ON

	-- --------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------
	/*
	Declare
		@comp_id							as Int,
		@bra_id								as int,
		@ct_transaction						as int,
		@item_id							as Int,
		@it_qty								as decimal(19,5),
		@curr_id							as int,
		@stor_id							as Int,

		@return_value						as int			,
		@ret_ErrorCode						as int			,
		@ret_ErrorDescription				as varchar(200)
	Select  @comp_id							=1,
		@bra_id								=1,
		@ct_transaction						=1876,
		@item_id							=282,
		@it_qty								=10,
		@curr_id							=1,
		@stor_id							=4
	*/
	-- --------------------------------------------------------------------

	Set 	@return_value						=0
	Set 	@ret_ErrorCode						=0
	Set 	@ret_ErrorDescription				=''


    SAVE TRANSACTION traPROTECT
    BEGIN TRANSACTION
    BEGIN TRY


		-- MOS 06-2013  Si es una SALIDA y NO se permite Stock Negativo
		IF @AllowWithNoStock = 'False' AND @it_qty < 0
			BEGIN
				IF EXISTS(
							SELECT TOP 1  1
								FROM tbItemStorage tis
							WHERE	tis.comp_id = @comp_id AND
									tis.stor_id = @stor_id AND
									tis.item_id = @item_id AND
									((tis.itst_cant - Abs(@it_qty)) < 0)
						 )
					BEGIN
						Set 	@return_value						=-15
						Set 	@ret_ErrorCode						=-15
						Set 	@ret_ErrorDescription				='No hay stock disponible para la transferencia en el deposito de origen !'
						RETURN -- No lo temia, se puso en MAR-2014 MOS
					END
			END



		/* recuperamos el stock anterior para cagarlo en itemtransaction */
		declare @it_storePrevious as decimal(19,5)



		If Exists (	SELECT TOP 1  1
						From	tbItemStorage tis			WITH (NOLOCK)
						Where	tis.comp_id = @comp_id
						And		tis.stor_id = @stor_id
						And		tis.item_id = @item_id
				  )
			BEGIN
				Select	@it_storePrevious = tis.itst_cant
					From	tbItemStorage tis
					Where	tis.comp_id = @comp_id
					And		tis.stor_id = @stor_id
					And		tis.item_id = @item_id
			END
		Else
			BEGIN

				Insert into tbItemStorage
										(	comp_id,stor_id,item_id,itst_cant,itst_cd)
					VALUES
										(	@comp_id,@stor_id,@item_id,0,Getdate())

				Set @it_storePrevious = 0
			End


		Insert Into dbo.tbItemTransactions
			(
				comp_id,
				bra_id,
				ct_transaction,
				it_cd,
				it_packingInvoicePend,
				item_id,
				it_qty,
				it_priceWithOutOthers,
				it_price,
				curr_id,
				it_priceOfCost,
				it_priceOfCostPP,
				it_priceOfCostLastPurchase,
				it_priceBOfCost,
				it_priceBOfCostPP,
				it_priceBOfCostLastPurchase,
				it_OriginalPrice,
				it_OriginalPriceCurrency,
				stor_id,
				it_storePrevious,
				prli_id,
				byor_id,
				it_isProduction,
				it_isAssociation,
				it_order,
				so_id,
				it_guarantee,
				it_exchangeToOriginalPriceCurrency,
				it_itemDiscountTotal,
				it_totalDiscountTotal,
				it_CreditInt,
				it_CreditIntPlus
			 )
			Values
			(
				@comp_id,
				@bra_id,
				@ct_transaction,
				getdate(),
				'false',
				@item_id,
				@it_qty,
				0,
				0,
				@curr_id,
				0,
				0,
				0,
				0,
				0,
				0,
				0,
				@curr_id,
				@stor_id,
				@it_storePrevious,
				NULL,
				NULL,
				'false',
				'false',
				0,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL
			 )



    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION traPROTECT
        DECLARE @ErrorMessage  NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT

END
GO






-- ATENCION:!!!
-- Solo usar en Ajustes Rapidos de Stock.!!!!
CREATE PROCEDURE [dbo].[spItemTransactions_InsertStock4StorageFastAdjustment]
(
	@comp_id							as int,
	@bra_id								as int,
	@ct_transaction						as int,
	@item_id							as Int,
	@it_qty								as decimal(19,5),
	@curr_id							as int,
	@stor_id_To							as Int,
	@itstkpld_id						AS INT,
	@sitt_id							AS INT,
	@return_value						as int			OUTPUT,
	@ret_ErrorCode						as int			OUTPUT,
	@ret_ErrorDescription				as varchar(200) OUTPUT
)
AS

BEGIN




	SET NOCOUNT ON

	-- --------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------
	/*
	Declare		@comp_id							as Int,
				@bra_id								as int,
				@ct_transaction						as int,
				@item_id							as Int,
				@it_qty								as decimal(19,5),
				@curr_id							as int,
				@stor_id_From						as Int,
				@stor_id_To							as Int,

				@return_value						as int			,
				@ret_ErrorCode						as int			,
				@ret_ErrorDescription				as varchar(200)


	Select		@comp_id							=1,
				@bra_id								=1,
				@ct_transaction						=1876,
				@item_id							=282,
				@it_qty								=10,
				@curr_id							=1,
				@stor_id_From						=4,
				@stor_id_To							=10
	*/
	-- --------------------------------------------------------------------

	Set 	@return_value							=	0
	Set 	@ret_ErrorCode						=	0
	Set 	@ret_ErrorDescription				=	''

	IF @itstkpld_id = -1 SET @itstkpld_id = NULL



	IF @sitt_id <> 91 AND @sitt_id <> 152	-- MOS 05-2023
		BEGIN
			SAVE TRANSACTION traPROTECT
			BEGIN TRANSACTION
		END


	BEGIN TRY


		/* recuperamos el stock anterior para cagarlo en itemtransaction */
		declare @dec_StorePrevious as decimal(19,5)
		SET		@dec_StorePrevious = 0

		-- ------------------------------------------------------------------------
		-- INGRESO de stock en el deposito @stor_id_To
		-- ------------------------------------------------------------------------
		SET @dec_StorePrevious = 0
		If Exists (	Select TOP 1 1
						From	tbItemStorage	tis		WITH (NOLOCK)
						Where	tis.comp_id		= @comp_id
						And		tis.stor_id		= @stor_id_To
						And		tis.item_id		= @item_id
				  )
			BEGIN
				Select	@dec_StorePrevious		= tis.itst_cant
					From	tbItemStorage		tis		WITH (NOLOCK)
					Where	tis.comp_id				= @comp_id
					And		tis.stor_id				= @stor_id_To
					And		tis.item_id				= @item_id
			END
		Else
			BEGIN

				Insert into tbItemStorage	WITH (ROWLOCK)
										(	comp_id,		stor_id,			item_id,		itst_cant,	itst_cd)
					VALUES
										(	@comp_id,	@stor_id_To,	@item_id,	0,				Getdate())

				Set @dec_StorePrevious = 0
			End




		DECLARE @it_priceOfCost					DECIMAL(19,4) = 0
		DECLARE @it_priceOfCostPP				DECIMAL(19,4) = 0
		DECLARE @it_priceOfCostLastPurchase		DECIMAL(19,4) = 0
		DECLARE @it_priceBOfCost				DECIMAL(19,4) = 0
		DECLARE @it_priceBOfCostPP				DECIMAL(19,4) = 0
		DECLARE @it_priceBOfCostLastPurchase	DECIMAL(19,4) = 0


		SELECT	@it_priceOfCost		= ISNULL(ticl1.coslis_price,0),
				@it_priceOfCostPP	= ISNULL(ticl1.coslis_price_aw,0),
				@it_priceBOfCost	= ISNULL(ticl1.coslis_price,0),
				@it_priceBOfCostPP	= ISNULL(ticl1.coslis_price_aw,0)
			FROM tbBranch AS tb							WITH (NOLOCK)
			LEFT JOIN tbItemCostList AS ticl1			WITH (NOLOCK)
				ON	ticl1.comp_id	= tb.comp_id		AND
					ticl1.coslis_id = tb.coslis_id		AND
					ticl1.item_id	= @item_id
			LEFT JOIN tbItemCostList AS ticl2			WITH (NOLOCK)
				ON	ticl2.comp_id	= tb.comp_id		AND
					ticl2.coslis_id = tb.coslis_id_B	AND
					ticl2.item_id	= @item_id

			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id




		Insert Into dbo.tbItemTransactions	WITH (ROWLOCK)
			(
				comp_id,
				bra_id,
				ct_transaction,
				it_cd,
				it_packingInvoicePend,
				item_id,
				it_qty,
				it_priceWithOutOthers,
				it_price,
				curr_id,
				it_priceOfCost,
				it_priceOfCostPP,
				it_priceOfCostLastPurchase,
				it_priceBOfCost,
				it_priceBOfCostPP,
				it_priceBOfCostLastPurchase,
				it_OriginalPrice,
				it_OriginalPriceCurrency,
				stor_id,
				it_storePrevious,
				prli_id,
				byor_id,
				it_isProduction,
				it_isAssociation,
				it_order,
				so_id,
				it_guarantee,
				it_exchangeToOriginalPriceCurrency,
				it_itemDiscountTotal,
				it_totalDiscountTotal,
				it_CreditInt,
				it_CreditIntPlus,
				it_IsFastStockAdjustment,
				sitt_id,
				itstkpld_id
			 )
			Values
			(
				@comp_id,
				@bra_id,
				@ct_transaction,
				getdate(),
				'false',
				@item_id,
				@it_qty ,
				0,
				0,
				@curr_id,
				@it_priceOfCost,
				@it_priceOfCostPP,
				@it_priceOfCostLastPurchase,
				@it_priceBOfCost,
				@it_priceBOfCostPP,
				@it_priceBOfCostLastPurchase,
				0,
				@curr_id,
				@stor_id_To,
				@dec_StorePrevious,
				NULL,
				NULL,
				'false',
				'false',
				0,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				'True',
				@sitt_id,
				@itstkpld_id
			)


			UPDATE	tbItemStorage	WITH (ROWLOCK)
				SET		itst_cant	= (itst_cant + @it_qty)
				WHERE	comp_id		= @comp_id
				AND		stor_id		= @stor_id_To
				AND		item_id		= @item_id

			-- ------------------------------------------------------------------------


    END TRY
    BEGIN CATCH

		IF @sitt_id <> 91 AND @sitt_id <> 152	-- MOS 05-2023
			BEGIN
				ROLLBACK TRANSACTION traPROTECT
			END

        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH

	IF @sitt_id <> 91 AND @sitt_id <> 152	-- MOS 05-2023
		BEGIN
			IF @@TRANCOUNT > 0 COMMIT TRANSACTION  traPROTECT
		END



END
GO





-- ----------------------------------------------------------------------------------------------------
-- GA: 28/11/14 - si bien este sp se ejecuta cuando se recibe una mercaderia en transferencia interna
--   tambien se usa para salida y entrada de stock en modificacion de datos de ctacte de
--   clientes , y por eso se graba el siit_id ( tipo de itemtransaction ) con 60 y 61 ,
--   para transferencia interna hay un spupdate aparte que actualiza despues de grabar el
--   siit_id correspondiente para transferencia interna.
-- ----------------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spItemTransactions_InsertStock4StorageReceptionFromPCConfig]
(
	 @comp_id				AS INT,
	 @bra_id				AS INT,
	 @ct_transaction		AS INT,
	 @item_id				AS INT,
	 @it_qty				AS DECIMAL(19,5),
	 @curr_id				AS INT,
	 @stor_id_From			AS INT,
	 @stor_id_To			AS INT,

	 @return_value			AS INT OUTPUT,
	 @ret_ErrorCode			AS INT OUTPUT,
	 @ret_ErrorDescription	AS VARCHAR(200) OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------
		/*
			DECLARE
				@comp_id				AS INT,
				@bra_id					AS INT,
				@ct_transaction			AS INT,
				@item_id				AS INT,
				@it_qty					AS DECIMAL(19,5),
				@curr_id				AS INT,
				@stor_id_From			AS INT,
				@stor_id_To				AS INT,

				@return_value			AS INT OUTPUT,
				@ret_ErrorCode			AS INT OUTPUT,
				@ret_ErrorDescription	AS VARCHAR(200) OUTPUT


			Select
				@comp_id				= 1,
				@bra_id					= 1,
				@ct_transaction			= 11068,
				@item_id				= 465,
				@it_qty					= 1,
				@curr_id				= 1,
				@stor_id_From			= 3,
				@stor_id_To				= 10
		*/
		-- --------------------------------------------------------------------

		SET  @return_value = 0
		SET  @ret_ErrorCode = 0
		SET  @ret_ErrorDescription = ''

		SAVE TRANSACTION traPROTECT
		BEGIN TRANSACTION
		BEGIN TRY

			 /* recuperamos el stock anterior para cagarlo en itemtransaction */
			 DECLARE	@dec_StorePrevious AS DECIMAL(19,5)
			 SET		@dec_StorePrevious = 0

			 -- ------------------------------------------------------------------------
			 -- DESCUENTO de stock en el deposito @stor_id_From
			 -- ------------------------------------------------------------------------
			 IF EXISTS ( SELECT 1
						 FROM	tbItemStorage				tis WITH (NOLOCK)
						 WHERE	tis.comp_id = @comp_id		AND
								tis.stor_id = @stor_id_From AND
								tis.item_id = @item_id
			   )
			 BEGIN
				 SELECT
					@dec_StorePrevious	= tis.itst_cant
					 FROM tbItemStorage					tis	WITH(NOLOCK)
					 WHERE	tis.comp_id = @comp_id		AND
							tis.stor_id = @stor_id_From AND
							tis.item_id = @item_id
				 END
			 ELSE
				BEGIN
					INSERT INTO tbItemStorage WITH (ROWLOCK)
					(
						comp_id,
						stor_id,
						item_id,
						itst_cant,
						itst_cd
					)
					VALUES
					(
						@comp_id,
						@stor_id_From,
						@item_id,
						0,
						GETDATE())

						SET @dec_StorePrevious = 0
				END


			INSERT INTO dbo.tbItemTransactions WITH (ROWLOCK)
			(
				comp_id,
				bra_id,
				ct_transaction,
				it_cd,
				it_packingInvoicePend,
				item_id,
				it_qty,
				it_priceWithOutOthers,
				it_price,
				curr_id,
				it_priceOfCost,
				it_priceOfCostPP,
				it_priceOfCostLastPurchase,
				it_priceBOfCost,
				it_priceBOfCostPP,
				it_priceBOfCostLastPurchase,
				it_OriginalPrice,
				it_OriginalPriceCurrency,
				stor_id,
				it_storePrevious,
				prli_id,
				byor_id,
				it_isProduction,
				it_isAssociation,
				it_order,
				so_id,
				it_guarantee,
				it_exchangeToOriginalPriceCurrency,
				it_itemDiscountTotal,
				it_totalDiscountTotal,
				it_CreditInt,
				it_CreditIntPlus,
				sitt_id
			)
			VALUES
			(
				@comp_id,
				@bra_id,
				@ct_transaction,
				GETDATE(),
				'False',
				@item_id,
				@it_qty * -1,
				0,
				0,
				@curr_id,
				0,
				0,
				0,
				0,
				0,
				0,
				0,
				@curr_id,
				@stor_id_From,
				@dec_StorePrevious,
				NULL,
				NULL,
				'False',
				'False',
				0,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				130
			)


			UPDATE tbItemStorage WITH (ROWLOCK)
			SET	itst_cant	= (itst_cant - @it_qty)
			WHERE	comp_id		= @comp_id		AND
				stor_id		= @stor_id_From AND
				item_id		= @item_id

			-- ------------------------------------------------------------------------



			-- ------------------------------------------------------------------------
			-- INGRESO de stock en el deposito @stor_id_To
			-- ------------------------------------------------------------------------
			SET @dec_StorePrevious = 0
			IF EXISTS (SELECT 1
						FROM tbItemStorage					tis WITH (NOLOCK)
						WHERE	tis.comp_id = @comp_id		AND
								tis.stor_id = @stor_id_To	AND
								tis.item_id = @item_id
			)
				BEGIN
					Select
						@dec_StorePrevious	= tis.itst_cant
						From tbItemStorage					tis	WITH(NOLOCK)
						Where	tis.comp_id = @comp_id		AND
								tis.stor_id = @stor_id_To	AND
								tis.item_id = @item_id
				END
			ELSE
				BEGIN

					INSERT INTO tbItemStorage WITH (ROWLOCK)
					(
						comp_id,
						stor_id,
						item_id,
						itst_cant,
						itst_cd
					)
					VALUES
					(
						@comp_id,
						@stor_id_To,
						@item_id,
						0,
						GETDATE()
					)
					SET @dec_StorePrevious = 0
				END


			 INSERT INTO dbo.tbItemTransactions WITH ( ROWLOCK)
			 (
				 comp_id,
				 bra_id,
				 ct_transaction,
				 it_cd,
				 it_packingInvoicePend,
				 item_id,
				 it_qty,
				 it_priceWithOutOthers,
				 it_price,
				 curr_id,
				 it_priceOfCost,
				 it_priceOfCostPP,
				 it_priceOfCostLastPurchase,
				 it_priceBOfCost,
				 it_priceBOfCostPP,
				 it_priceBOfCostLastPurchase,
				 it_OriginalPrice,
				 it_OriginalPriceCurrency,
				 stor_id,
				 it_storePrevious,
				 prli_id,
				 byor_id,
				 it_isProduction,
				 it_isAssociation,
				 it_order,
				 so_id,
				 it_guarantee,
				 it_exchangeToOriginalPriceCurrency,
				 it_itemDiscountTotal,
				 it_totalDiscountTotal,
				 it_CreditInt,
				 it_CreditIntPlus,
				 sitt_id
			  )
			 VALUES
			 (
				 @comp_id,
				 @bra_id,
				 @ct_transaction,
				 GETDATE(),
				 'False',
				 @item_id,
				 @it_qty ,
				 0,
				 0,
				 @curr_id,
				 0,
				 0,
				 0,
				 0,
				 0,
				 0,
				 0,
				 @curr_id,
				 @stor_id_To,
				 @dec_StorePrevious,
				 NULL,
				 NULL,
				 'False',
				 'False',
				 0,
				 NULL,
				 NULL,
				 NULL,
				 NULL,
				 NULL,
				 NULL,
				 NULL,
				 131
			 )

			 UPDATE tbItemStorage WITH (ROWLOCK)
			 SET itst_cant	= (itst_cant + @it_qty)
			 WHERE	comp_id = @comp_id		AND
					stor_id = @stor_id_To	AND
					item_id = @item_id

			 -- ------------------------------------------------------------------------

			 -- Si el stock queda negativo en el deposito FROM cancela el proceso
			 IF EXISTS(
						SELECT 1
						FROM tbItemStorage						tis WITH (NOLOCK)
						WHERE	tis.comp_id		= @comp_id		AND
								tis.stor_id		= @stor_id_From AND
								tis.item_id		= @item_id		AND
								tis.itst_cant	< 0 -- (tis.itst_cant /*- Abs(@it_qty))*/ < 0)
					  )
			 BEGIN
				 SET  @return_value			= -15
				 SET  @ret_ErrorCode		= -15
				 SET  @ret_ErrorDescription = ' No hay stock disponible para la transferencia en el deposito de origen ( Depósito para Módulo de Armado de Configuraciones de PC ) '
			 END


		END TRY
		BEGIN CATCH
			ROLLBACK TRANSACTION traPROTECT
			DECLARE @ErrorMessage   NVARCHAR(4000)
			DECLARE @ErrorSeverity  INT
			DECLARE @ErrorState     INT
			SELECT  @ErrorMessage    = ERROR_MESSAGE(),
					@ErrorSeverity   = ERROR_SEVERITY(),
					@ErrorState      = ERROR_STATE()
			IF      @ErrorState      = 0 SET @ErrorState = 1
			RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)
		END CATCH
		IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT

END
GO




-- ----------------------------------------------------------------------------------------------------
-- GA: 28/11/14 - ATENCION ATENCION ATENCION ATENCION ATENCION

--				  si bien este sp se ejecuta cuando se recibe una mercaderia en transferencia interna ( wfmStorage_TransferTransactions )
--				  TAMBIEN se usa para salida y entrada de stock en modificacion de datos de ctacte de
--				  clientes ( wfmCommTrans_CustUpdate_ItemData_Detail ), y por eso se graba el siit_id ( tipo de itemtransaction ) con 60 y 61 ,
--				  para transferencia interna hay un spupdate aparte que actualiza despues de grabar el
--				  siit_id correspondiente para transferencia interna. =)

--				  ATENCION ATENCION ATENCION ATENCION ATENCION
--				  ATENCION ATENCION ATENCION ATENCION ATENCION
-- ----------------------------------------------------------------------------------------------------
-- wfmStorage_TransferTransactions
-- wfmCommTrans_CustUpdate_ItemData_Detail

CREATE PROCEDURE [dbo].[spItemTransactions_InsertStock4StorageTransferTransaction]
(
	@comp_id							as INT,
	@bra_id								as INT,
	@ct_transaction						as INT,
	@item_id							as INT,
	@it_qty								as decimal(19,5),
	@curr_id							as INT,
	@stor_id_From						as INT,
	@stor_id_To							as INT,

	@return_value						as INT			OUTPUT,
	@ret_ErrorCode						as INT			OUTPUT,
	@ret_ErrorDescription				as varchar(200) OUTPUT
)
AS

BEGIN



	SET NOCOUNT ON

	-- --------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------
	/*
	Declare		@comp_id							as Int,
				@bra_id								as int,
				@ct_transaction						as int,
				@item_id							as Int,
				@it_qty								as decimal(19,5),
				@curr_id							as int,
				@stor_id_From						as Int,
				@stor_id_To							as Int,

				@return_value						as int			,
				@ret_ErrorCode						as int			,
				@ret_ErrorDescription				as varchar(200)


	Select		@comp_id							=1,
				@bra_id								=1,
				@ct_transaction						=12112,
				@item_id							=282,
				@it_qty								=1,
				@curr_id							=1,
				@stor_id_From						=4,
				@stor_id_To							=3
	*/
	-- --------------------------------------------------------------------

	Set 	@return_value						=	0
	Set 	@ret_ErrorCode						=	0
	Set 	@ret_ErrorDescription				=	''




    SAVE TRANSACTION traPROTECT
    BEGIN TRANSACTION
    BEGIN TRY

		DECLARE @sd_id AS INT
		SELECT	@sd_id = tct.sd_id
			FROM tbCommercialTransactions tct		WITH (NOLOCK)
			WHERE	tct.comp_id			= @comp_id AND
					tct.ct_transaction	= @ct_transaction



		/* recuperamos el stock anterior para cagarlo en itemtransaction */
		declare @dec_StorePrevious as decimal(19,5)
		SET		@dec_StorePrevious = 0

		-- ------------------------------------------------------------------------
		-- DESCUENTO de stock en el deposito @stor_id_From
		-- ------------------------------------------------------------------------
		If Exists (	Select 1
							From	tbItemStorage tis	WITH (NOLOCK)
							Where	tis.comp_id = @comp_id
							And		tis.stor_id	= @stor_id_From
							And		tis.item_id	= @item_id
				  )
			BEGIN
				Select	@dec_StorePrevious		= tis.itst_cant
					From	tbItemStorage tis
					Where	tis.comp_id			= @comp_id
					And		tis.stor_id			= @stor_id_From
					And		tis.item_id			= @item_id
			END
		Else
			BEGIN

				Insert into tbItemStorage WITH (ROWLOCK)
										(
											comp_id,
											stor_id,
											item_id,
											itst_cant,
											itst_cd)
					VALUES
										(	@comp_id,
											@stor_id_From,
											@item_id,
											0,
											Getdate())

				Set @dec_StorePrevious = 0
			End


		Insert Into dbo.tbItemTransactions	WITH (ROWLOCK)
			(
				comp_id,
				bra_id,
				ct_transaction,
				it_cd,
				it_packingInvoicePend,
				item_id,
				it_qty,
				it_priceWithOutOthers,
				it_price,
				curr_id,
				it_priceOfCost,
				it_priceOfCostPP,
				it_priceOfCostLastPurchase,
				it_priceBOfCost,
				it_priceBOfCostPP,
				it_priceBOfCostLastPurchase,
				it_OriginalPrice,
				it_OriginalPriceCurrency,
				stor_id,
				it_storePrevious,
				prli_id,
				byor_id,
				it_isProduction,
				it_isAssociation,
				it_order,
				so_id,
				it_guarantee,
				it_exchangeToOriginalPriceCurrency,
				it_itemDiscountTotal,
				it_totalDiscountTotal,
				it_CreditInt,
				it_CreditIntPlus,
				sitt_id
			 )
			Values
			(
				@comp_id,
				@bra_id,
				@ct_transaction,
				getdate(),
				'false',
				@item_id,
				@it_qty * -1,
				0,
				0,
				@curr_id,
				0,
				0,
				0,
				0,
				0,
				0,
				0,
				@curr_id,
				@stor_id_From,
				@dec_StorePrevious,
				NULL,
				NULL,
				'false',
				'false',
				0,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				60
			)

			--SET @return_value = @@IDENTITY

			--DECLARE @intNewItemID	INT
				SET	@return_value = IDENT_CURRENT('tbItemTransactions')   -- @@identity

			UPDATE	tbItemStorage	WITH (ROWLOCK)
				SET		itst_cant	= (itst_cant - @it_qty)
				WHERE	comp_id		= @comp_id
				AND		stor_id		= @stor_id_From
				AND		item_id		= @item_id

			-- ------------------------------------------------------------------------







		-- ------------------------------------------------------------------------
		-- INGRESO de stock en el deposito @stor_id_To
		-- ------------------------------------------------------------------------
		SET @dec_StorePrevious = 0
		If Exists (	Select 1
							From	tbItemStorage tis	WITH (NOLOCK)
							Where	tis.comp_id		= @comp_id
							And		tis.stor_id		= @stor_id_To
							And		tis.item_id		= @item_id
				  )
			BEGIN
				Select	@dec_StorePrevious		= tis.itst_cant
					From	tbItemStorage tis
					Where	tis.comp_id				= @comp_id
					And		tis.stor_id				= @stor_id_To
					And		tis.item_id				= @item_id
			END
		Else
			BEGIN

				Insert into tbItemStorage	WITH (ROWLOCK)
										(	comp_id,		stor_id,			item_id,		itst_cant,	itst_cd)
					VALUES
										(	@comp_id,	@stor_id_To,	@item_id,	0,				Getdate())

				Set @dec_StorePrevious = 0
			End


		Insert Into dbo.tbItemTransactions	WITH (ROWLOCK)
			(
				comp_id,
				bra_id,
				ct_transaction,
				it_cd,
				it_packingInvoicePend,
				item_id,
				it_qty,
				it_priceWithOutOthers,
				it_price,
				curr_id,
				it_priceOfCost,
				it_priceOfCostPP,
				it_priceOfCostLastPurchase,
				it_priceBOfCost,
				it_priceBOfCostPP,
				it_priceBOfCostLastPurchase,
				it_OriginalPrice,
				it_OriginalPriceCurrency,
				stor_id,
				it_storePrevious,
				prli_id,
				byor_id,
				it_isProduction,
				it_isAssociation,
				it_order,
				so_id,
				it_guarantee,
				it_exchangeToOriginalPriceCurrency,
				it_itemDiscountTotal,
				it_totalDiscountTotal,
				it_CreditInt,
				it_CreditIntPlus,
				sitt_id
			 )
			Values
			(
				@comp_id,
				@bra_id,
				@ct_transaction,
				getdate(),
				'false',
				@item_id,
				@it_qty ,
				0,
				0,
				@curr_id,
				0,
				0,
				0,
				0,
				0,
				0,
				0,
				@curr_id,
				@stor_id_To,
				@dec_StorePrevious,
				NULL,
				NULL,
				'false',
				'false',
				0,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				61
			)



			UPDATE	tbItemStorage	WITH (ROWLOCK)
						SET		itst_cant	= (itst_cant + @it_qty)
						WHERE	comp_id		= @comp_id
						AND		stor_id		= @stor_id_To
						AND		item_id		= @item_id

			-- ------------------------------------------------------------------------


			---- Si el stock queda negativo en el deposito FROM cancela el proceso
			--IF
			--	EXISTS(
			--			SELECT 1
			--				FROM tbItemStorage tis	WITH (NOLOCK)
			--				WHERE	tis.comp_id		= @comp_id		AND
			--						tis.stor_id		= @stor_id_From	AND
			--						tis.item_id		= @item_id		AND
			--						tis.itst_cant	< 0				-- (tis.itst_cant /*- Abs(@it_qty))*/ < 0)
			--		 )
			--	BEGIN
			--		Set 	@return_value						=	-15
			--		Set 	@ret_ErrorCode						=	-15
			--		Set 	@ret_ErrorDescription				=	'No hay stock disponible para la transferencia en el deposito de origen !'
			--	END


    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION traPROTECT
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
    IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT


END
GO



CREATE PROCEDURE spItemTransactions_IsItemInDocument
(
	@comp_id		INT,
	@bra_id			INT,
	@ct_transaction	INT,
	@item_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------
		-- TESTING
		-- ------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@ct_transaction	INT,
				@item_id		INT
			SELECT
				@comp_id		= 1,
				@bra_id			= 1,
				@ct_transaction	= 11704,
				@item_id		= 492
		*/
		-- ------------------------------------------

		SELECT
			COUNT(*)											[Exists]
			FROM tbItemTransactions								tit
				INNER JOIN tbCommercialTransactions				tct	WITH(NOLOCK)
					ON	tct.comp_id			= tit.comp_id		AND
						tct.ct_transaction	= tit.ct_transaction
			WHERE	tit.comp_id				= @comp_id			AND
					tit.ct_transaction		= @ct_transaction	AND
					tit.item_id				= @item_id

	END




GO


CREATE PROCEDURE [dbo].[spItemTransactions_ItemGuaranteeByItTransaction]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@it_transaction	INT
)
AS

	BEGIN

		SET NOCOUNT ON



		-- -----------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@bra_id			INT,
				@it_transaction	INT

			SELECT
				@comp_id		= 1,
				@lang_id		= 2,
				@bra_id			= 28,
				@it_transaction	= 2189206
		*/
		-- -----------------------------------------------------------------------



		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------



		-- -----------------------------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- -----------------------------------------------------------------------
			DECLARE
				@it_transaction_originalEW	INT,
				@ct_transaction				INT,
				@it_bra_id					INT
		-- -----------------------------------------------------------------------

			SELECT
				@it_bra_id							= tit.bra_id,
				@ct_transaction						= tit.ct_transaction,
				@it_transaction_originalEW			= tit.it_transaction
			FROM tbItemTransactions tit		WITH (NOLOCK)
			WHERE	tit.comp_id						= @comp_id AND
					tit.it_transaction_originalEW	= @it_transaction


		EXEC spItemTransactions_getData
					@comp_id,
					@it_bra_id,
					@ct_transaction,
					@it_transaction,
					@it_transaction_originalEW




		DECLARE
			@strExtendedProtection	NVARCHAR(1000),
			@strExtendedDescription	NVARCHAR(1000),
			@strFrom				NVARCHAR(400),
			@strTo					NVARCHAR(400)

		SELECT
			@strExtendedProtection	= tov.optval_desc
		FROM tbsysOptionsValues					tov	WITH (NOLOCK)
		WHERE	tov.lang_id			= @lang_id	AND
				tov.optval_id		= 1 AND
				tov.optval_class	= 650

		SELECT
			@strExtendedDescription = tov.optval_desc
		FROM tbsysOptionsValues					tov	WITH (NOLOCK)
		WHERE	tov.lang_id			= @lang_id	AND
				tov.optval_id		= 2 AND
				tov.optval_class	= 650

		SELECT
			@strFrom				= tov.optval_desc
		FROM tbsysOptionsValues					tov	WITH (NOLOCK)
		WHERE	tov.lang_id			= @lang_id	AND
				tov.optval_id		= 3 AND
				tov.optval_class	= 650

		SELECT
			@strTo					= tov.optval_desc
		FROM tbsysOptionsValues					tov	WITH (NOLOCK)
		WHERE	tov.lang_id			= @lang_id	AND
				tov.optval_id		= 4 AND
				tov.optval_class	= 650

		SELECT
			@strExtendedProtection	[ExtendedProtection],
			@strExtendedDescription	[ExtendedDescription],
			@strFrom				[StrFrom],
			@strTo					[StrTo]

	END

GO



CREATE PROCEDURE [dbo].[spItemTransactions_ItemReturn4Change_CloneCommercialTransactions]
(
	@comp_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@ct_transaction			INT,
	@df_id					INT,			--DF_ID asignado para CAMBIOS (SUCURSAL - TAB CAMBIOS)
	@return_value			AS INT			OUTPUT,
	@ret_ErrorCode			AS INT			OUTPUT,
	@ret_ErrorDescription	AS VARCHAR(200) OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------
		-- TESTING
		-- ----------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@user_id		INT,
				@ct_transaction	INT,
				@df_id			INT,
				@return_value	INT,
				@ret_ErrorCode	INT

			SELECT
				@comp_id		= 1,
				@bra_id			= 1,
				@user_id		= 119,
				@ct_transaction	= 11704,
				@df_id			= 58,
				@return_value	= 0,
				@ret_ErrorCode	= 0
		*/
		-- ----------------------------------------

			SET @return_value			= 0
			SET @ret_ErrorCode			= 0
			SET @ret_ErrorDescription	= ''

			--BEGIN TRANSACTION
				BEGIN TRY

				-- -----------------------------------------------------------
				-- OBTENEMOS EL ÚLTIMO NÚMERO PARA EL COMPROBANTE CLONADO
				-- ACTUALIZAMOS LUEGO LA DOCUMENTSFILE CON EL NÚMERO GENERADO
				-- -----------------------------------------------------------
					DECLARE
						@lDocNumber	DECIMAL(25,0)
					SET @lDocNumber = 0
					SELECT
						@lDocNumber = tdf.df_number + 1
						FROM tbDocumentsFile			tdf	WITH(NOLOCK)
						WHERE	tdf.comp_id = @comp_id	AND
								tdf.df_id	= @df_id

					UPDATE tbDocumentsFile
					SET
						df_number	= @lDocNumber
						WHERE	comp_id = @comp_id	AND
								df_id	= @df_id
				-- -----------------------------------------------------------

				-- --------------------------------------------------------------------
				-- RECUPERAMOS EL SD_ID DEL DF_ID DEFINIDO EN LA SUCURSAL PARA CAMBIOS
				-- --------------------------------------------------------------------

					DECLARE
						@sd_id	INT
					SELECT
						@sd_id = tdf.sd_id
						FROM	tbDocumentsFile			tdf			WITH(NOLOCK)
						WHERE	tdf.comp_id = @comp_id	AND
								tdf.df_id	= @df_id

				-- --------------------------------------------------------------------



					INSERT INTO tbCommercialTransactions
					(
						comp_id,
						bra_id,
						-- ct_transaction -- this column value is auto-generated,
						ct_pointOfSale,
						ct_kindOf,
						ct_docNumber,
						ct_date,
						ct_taxDate,
						ct_payDate,
						supp_id,
						cust_id,
						ba_id,
						cb_id,
						user_id,
						ct_cd,
						ct_subtotal,
						ct_total,
						ct_discount,
						ct_adjust,
						ct_taxes,
						curr_id_transaction,
						hacc_transaction,
						sm_id,
						disc_id,
						ct_ATotal,
						ct_ABalance,
						ct_ACurrency,
						ct_ACurrencyExchange,
						df_id,
						dl_id,
						st_id,
						sd_id,
						puco_id,
						ct_CompanyCurrency,
						ct_Branch2CompanyCurrencyExchange,
						ct_Pending,
						country_id,
						state_id,
						ct_isAvailableForImport,
						ct_soh_bra_id,
						ct_soh_id,
						ct_CAI,
						ct_CAIDate,
						ct_CAIBarCodeImage,
						ct_isAvailableForPayment,
						ct_transaction_PackingList,
						ct_processingDate,
						ct_AAdjust,
						ct_dfExchange,
						curr_id4Exchange,
						ct_curr_IdExchange,
						curr_id4dfExchange,
						ct_AllUseTag1,
						ct_AllUseTag2,
						ct_AllUseTag3,
						ct_AllUseTag4,
						ct_FEIdNumber,
						ct_packagesQty,
						ct_isCancelled,
						sctt_id,
						ct_isSelected,
						ct_Discount1,
						ct_Discount2,
						ct_Discount3,
						ct_Discount4,
						ct_TransactionBarCode,
						suppa_id,
						pt_id,
						ct_optionalValue,
						ct_dfExchangeOriginal,
						ct_curr_IdExchangeOriginal,
						ct_Fiscal_Check4EmptyNumbers,
						custf_id,
						cust_id_guarantor,
						ct_guid,
						ct_transaction4ThirdSales,
						ct_inCash,
						ccp_id,
						ct_CreditIntPercentage,
						ct_CreditIntPlusPercentage
					)
					SELECT
						tct.comp_id,
						tct.bra_id,
						tct.ct_pointOfSale,
						tct.ct_kindOf,
						@lDocNumber,		--tct.ct_docNumber,
						GETDATE(),
						tct.ct_taxDate,
						tct.ct_payDate,
						tct.supp_id,
						tct.cust_id,
						tct.ba_id,
						tct.cb_id,
						@user_id,
						tct.ct_cd,
						tct.ct_subtotal,
						tct.ct_total,
						tct.ct_discount,
						tct.ct_adjust,
						tct.ct_taxes,
						tct.curr_id_transaction,
						tct.hacc_transaction,
						tct.sm_id,
						tct.disc_id,
						0,
						0,
						tct.ct_ACurrency,
						tct.ct_ACurrencyExchange,
						@df_id,
						tct.dl_id,
						tct.st_id,
						@sd_id,			--tct.sd_id,
						tct.puco_id,
						tct.ct_CompanyCurrency,
						tct.ct_Branch2CompanyCurrencyExchange,
						tct.ct_Pending,
						tct.country_id,
						tct.state_id,
						tct.ct_isAvailableForImport,
						tct.ct_soh_bra_id,
						tct.ct_soh_id,
						tct.ct_CAI,
						tct.ct_CAIDate,
						tct.ct_CAIBarCodeImage,
						tct.ct_isAvailableForPayment,
						tct.ct_transaction_PackingList,
						tct.ct_processingDate,
						tct.ct_AAdjust,
						tct.ct_dfExchange,
						tct.curr_id4Exchange,
						tct.ct_curr_IdExchange,
						tct.curr_id4dfExchange,
						tct.ct_AllUseTag1,
						tct.ct_AllUseTag2,
						tct.ct_AllUseTag3,
						tct.ct_AllUseTag4,
						tct.ct_FEIdNumber,
						tct.ct_packagesQty,
						tct.ct_isCancelled,
						tct.sctt_id,
						tct.ct_isSelected,
						tct.ct_Discount1,
						tct.ct_Discount2,
						tct.ct_Discount3,
						tct.ct_Discount4,
						tct.ct_TransactionBarCode,
						tct.suppa_id,
						tct.pt_id,
						tct.ct_optionalValue,
						tct.ct_dfExchangeOriginal,
						tct.ct_curr_IdExchangeOriginal,
						tct.ct_Fiscal_Check4EmptyNumbers,
						tct.custf_id, tct.cust_id_guarantor,
						tct.ct_guid,
						tct.ct_transaction4ThirdSales,
						tct.ct_inCash, tct.ccp_id,
						tct.ct_CreditIntPercentage,
						tct.ct_CreditIntPlusPercentage
						FROM tbCommercialTransactions				tct		WITH(NOLOCK)
						WHERE	tct.comp_id			= @comp_id		AND
								tct.ct_transaction	= @ct_transaction

						SET @return_value = @@IDENTITY

					--COMMIT TRANSACTION
				END TRY
			BEGIN CATCH
				--ROLLBACK TRANSACTION
				SET @ret_ErrorCode			= -1
				SET @ret_ErrorDescription	= ''
			END CATCH

	END
GO




CREATE PROCEDURE [dbo].[spItemTransactions_ItemReturn4Change_CloneData]
(
	@comp_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@ct_transaction			INT,			--ID DEL MOVIMIENTO ORIGINAL
	@ct_transaction_new		INT,			--ID DEL MOVIMIENTO CLONADO
	@item_id2Return			INT,			--ARTÍCULO QUE SE DEVUELVE
	@item_id4Change			INT,			--ARTÍCULO POR EL CUAL SE CAMBIA
	@stor_id				INT,			--DEPÓSITO SELECCIONADO EN LA PÁGINA
	@return_value			AS INT			OUTPUT,
	@ret_ErrorCode			AS INT			OUTPUT,
	@ret_ErrorDescription	AS VARCHAR(200) OUTPUT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@bra_id					INT,
				@user_id				INT,
				@ct_transaction			INT,
				@ct_transaction_new		INT,
				@item_id2Return			INT,			--ARTÍCULO QUE SE DEVUELVE
				@item_id4Change			INT,			--ARTÍCULO POR EL CUAL SE CAMBIA
				@return_value			INT,
				@ret_ErrorCode			INT,
				@ret_ErrorDescription	VARCHAR(200)
			SELECT
				@comp_id				= 1,
				@bra_id					= 1,
				@user_id				= 119,
				@ct_transaction			= 11704,
				@ct_transaction_new		= 11926,
				@item_id2Return			= 492,			--ARTÍCULO QUE SE DEVUELVE
				@item_id4Change			= 231,			--ARTÍCULO POR EL CUAL SE CAMBIA
				@return_value			= 0,
				@ret_ErrorCode			= 0,
				@ret_ErrorDescription	= ''
		*/
		-- --------------------------------------------
			BEGIN TRY
				SET @return_value			= 0
				SET @ret_ErrorCode			= 0
				SET @ret_ErrorDescription	= ''


				/* recuperamos el stock anterior para cagarlo en itemtransaction */
				DECLARE @dec_StorePrevious_Return	DECIMAL(19,5)
				SET		@dec_StorePrevious_Return	= 0

				-- ------------------------------------------------------------------------
				-- OBTENEMOS EL STOREPREVIOUS
				-- ------------------------------------------------------------------------
				IF EXISTS(	SELECT
								1
								FROM	tbItemStorage				tis WITH(NOLOCK)
								WHERE	tis.comp_id = @comp_id		AND
										tis.stor_id	= @stor_id		AND
										tis.item_id	= @item_id2Return
						  )
					BEGIN
						SELECT
							@dec_StorePrevious_Return	= tis.itst_cant
							FROM	tbItemStorage						tis	WITH(NOLOCK)
							Where	tis.comp_id			= @comp_id		AND
									tis.stor_id			= @stor_id		AND
									tis.item_id			= @item_id2Return
					END
				ELSE
					BEGIN
						INSERT INTO tbItemStorage
						(
							comp_id,
							stor_id,
							item_id,
							itst_cant,
							itst_cd
						)
						VALUES
						(
							@comp_id,
							@stor_id,
							@item_id2Return,
							0,
							GETDATE()
						)
						SET @dec_StorePrevious_Return = 0
					END

				-- ------------------------------------------------------------------
				-- PRIMER INSERT
				-- ------------------------------------------------------------------
				-- CLONAMOS EL REGISTRO DE ITEM TRANSACTIONS ORIGINAL
