				-- PRECIOS YA ASIGNADA AL REGISTRO ORIGINAL
				-- ------------------------------------------------------------------

				-- ------------------------------------------------------------------------
				-- EGRESO DE STOCK POR CAMBIO
				-- ------------------------------------------------------------------------
				DECLARE
					@dec_StorePrevious_4Change	INT
				SET @dec_StorePrevious_4Change = 0

				IF EXISTS (	SELECT
