					curr_id,
					it_exchangeToBranchCurrency,
					it_priceOfCost,
					it_priceOfCostPP,
					it_priceOfCostLastPurchase,
					it_priceBOfCost,
					it_priceBOfCostPP,
					it_priceBOfCostLastPurchase,
					it_OriginalPrice,
					it_OriginalPriceCurrency,
					it_exchangeToOriginalPriceCurrency,
					stor_id,
					it_storePrevious,
					prli_id,
					byor_id,
					it_isProduction,
					it_isAssociation,
