					it_packingInvoicePend,
					it_order,
					so_id,
					it_guarantee,
					it_itemDiscountTotal,
					it_totalDiscountTotal,
					it_CreditInt,
					it_CreditIntPlus,
					puco_id,
					it_poh_bra_id,
					it_poh_id,
					it_soh_id,
					it_sod_id,
					rmah_id,
					rmad_id,
					it_qty_rma,
					it_tis_id_aux,
					it_note1,
					it_note2,
					it_packingInvoiceSelected,
					it_cancelled,
					it_priceB,
					it_isMade,
					it_item_id_origin,
					tmp_tis_id,
					it_packingInvoicePendOriginal,
					it_packingInvoiceSelectedGuid,
					it_transaction_original,
					it_transaction_NoStockDiscount,
					it_SalesCurrId4exchangeToBranchCurrency,
					it_AllUseTag1,
					it_AllUseTag2,
					it_AllUseTag3,
					it_AllUseTag4,
					it_Discount1,
					it_Discount2,
					it_Discount3,
					it_Discount4,
					coslis_id,
					coslis_idB,
					supp_id,
					camp_id,
					it_transaction_originalEW,
					it_IsInternalTransfer,
					it_isRMASupplierCreditNote,
					it_IsFastStockAdjustment,
					it_IsStockAdjustment,
					it_IsStockControl,
					sdlmt_id,
					sreas_id,
					it_loanNumberOfPays,
					sitt_id,
					it_deliveryDate,
					itstkpld_id,
					it_NoStockCheck,
					it_transaction_originaLDIV,
					it_surcharge1,
					it_surcharge2,
					it_surcharge3,
					it_surcharge4,
					stor_id_related4BranchTransfer,
					it_transaction_related4BranchTransfer,
					it_pod_id,
					pubh_id,
					it_EWAddress,
					it_insuranceDays,
					insud_id,
					insud_certificateNumber
				)
				SELECT
					tit.comp_id,
					tit.bra_id,
					@ct_transaction_new,
					--tit.it_transaction,
					@item_id4Change,
					tit.it_qty,
					tit.it_priceWithOutOthers,
					(SELECT
							ISNULL(tpli.prli_price,0)
						FROM tbPriceListItems				tpli	WITH(NOLOCK)
						WHERE	tpli.comp_id = tit.comp_id	AND
								tpli.prli_id = tit.prli_id	AND
								tpli.item_id = @item_id4Change),	--tit.it_price,
					tit.curr_id,
					tit.it_exchangeToBranchCurrency,
					tit.it_priceOfCost,
					tit.it_priceOfCostPP,
					tit.it_priceOfCostLastPurchase,
					tit.it_priceBOfCost,
					tit.it_priceBOfCostPP,
					tit.it_priceBOfCostLastPurchase,
					tit.it_OriginalPrice,
					tit.it_OriginalPriceCurrency,
					tit.it_exchangeToOriginalPriceCurrency,
					@stor_id,										--tit.stor_id,
					@dec_StorePrevious_4Change,						--tit.it_storePrevious,
					tit.prli_id,
					tit.byor_id,
					tit.it_isProduction,
					tit.it_isAssociation,
					tit.it_isAssociationGroup,
					GETDATE(),
					tit.it_packingInvoicePend,
					tit.it_order,
					tit.so_id,
					tit.it_guarantee,
					tit.it_itemDiscountTotal,
					tit.it_totalDiscountTotal,
					tit.it_CreditInt,
					tit.it_CreditIntPlus,
					tit.puco_id,
					tit.it_poh_bra_id,
					tit.it_poh_id,
					tit.it_soh_id,
					tit.it_sod_id,
					tit.rmah_id,
					tit.rmad_id,
					tit.it_qty_rma,
					tit.it_tis_id_aux,
					tit.it_note1,
					tit.it_note2,
					tit.it_packingInvoiceSelected,
					tit.it_cancelled,
					tit.it_priceB,
					tit.it_isMade,
					tit.it_item_id_origin,
					tit.tmp_tis_id,
					tit.it_packingInvoicePendOriginal,
					tit.it_packingInvoiceSelectedGuid,
					tit.it_transaction_original,
					tit.it_transaction_NoStockDiscount,
					tit.it_SalesCurrId4exchangeToBranchCurrency,
					tit.it_AllUseTag1,
					tit.it_AllUseTag2,
					tit.it_AllUseTag3,
					tit.it_AllUseTag4,
					tit.it_Discount1,
					tit.it_Discount2,
					tit.it_Discount3,
					tit.it_Discount4,
					tit.coslis_id,
					tit.coslis_idB,
					tit.supp_id,
					tit.camp_id,
					tit.it_transaction_originalEW,
					tit.it_IsInternalTransfer,
					tit.it_isRMASupplierCreditNote,
					tit.it_IsFastStockAdjustment,
					tit.it_IsStockAdjustment,
					tit.it_IsStockControl,
					tit.sdlmt_id,
					tit.sreas_id,
					tit.it_loanNumberOfPays,
					141,					--sitt_id Devolución de Artículo - Egreso del Nuevo Artículo
					tit.it_deliveryDate,
					tit.itstkpld_id,
					tit.it_NoStockCheck,
					tit.it_transaction_originaLDIV,
					tit.it_surcharge1,
					tit.it_surcharge2,
					tit.it_surcharge3,
					tit.it_surcharge4,
					tit.stor_id_related4BranchTransfer,
					tit.it_transaction_related4BranchTransfer,
					tit.it_pod_id,
					tit.pubh_id,
					tit.it_EWAddress,
					tit.it_insuranceDays,
					tit.insud_id,
					tit.insud_certificateNumber
					FROM tbItemTransactions							tit		WITH(NOLOCK)
					WHERE	tit.comp_id			= @comp_id			AND
							tit.ct_transaction	= @ct_transaction	AND
							tit.item_id			= @item_id2Return


				-- ---------------------------------------------------------------------------------
				-- HACEMOS EL MOVIMIENTO DE STOCK DENTRO DEL DEPÓSITO CON EL ARTÍCULO QUE SE DA
				-- COMO CAMBIO, RESTAMOS 1
				-- ---------------------------------------------------------------------------------
					UPDATE	tbItemStorage
					SET		itst_cant	= (itst_cant - 1)
					WHERE	comp_id		= @comp_id
					AND		stor_id		= @stor_id
					AND		item_id		= @item_id4Change
				-- ---------------------------------------------------------------------------------

				--FIN SEGUNDO INSERT
				-- ------------------------------------------------------------------

				-- ------------------------------------------------------------------
				-- GRABAMOS LA RELACIÓN DE LOS CT_TRANSACTION
				-- ------------------------------------------------------------------
					INSERT INTO tbCommercialTransactions_Relations
					(
						comp_id,
						ct_transaction_1,
						ct_transaction_2,
						class
					)
					VALUES
					(
						@comp_id,
						@ct_transaction,
						@ct_transaction_new,
						1
					)
				--SELECT 'TODO OK TERCER INSERT'
				-- ------------------------------------------------------------------

				--COMMIT TRANSACTION
			END TRY
		BEGIN CATCH
			--ROLLBACK TRANSACTION
			SET @ret_ErrorCode			= -1
			SET @ret_ErrorDescription	= ''
		END CATCH
	END
GO




CREATE PROCEDURE [dbo].[spItemTransactions_ItemReturn4Change_getReport]
(
		@comp_id				INT,
		@lang_id				INT,
		@page_id				INT,

		@ct_transaction			INT,
		@item_id_2Return		INT,
		@ct_transaction_Cloned	INT,
		@item_id_4Change		INT,
		@intBranch4Lang			INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@lang_id				INT,
				@page_id				INT,

				@ct_transaction			INT,
				@item_id_2Return		INT,
				@ct_transaction_Cloned	INT,
				@item_id_4Change		INT,
				@intBranch4Lang			INT

			SELECT
				@comp_id				= 1,
				@lang_id				= 2,
				@page_id				= 10091,

				@ct_transaction			= 11704,
				@item_id_2Return		= 492,
				@ct_transaction_Cloned	= 11705,
				@item_id_4Change		= 231,
				@intBranch4Lang			= 1
		*/
		-- ----------------------------------------------

		-- -------------------------------------------------------------------------------------------------------------
		-- OBTENEMOS LOS DATOS DEL CT_TRANSACTION ORIGINAL
		-- -------------------------------------------------------------------------------------------------------------
			SELECT
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction)	[Document],
				ti.item_code,
				ti.item_desc,
				tit.it_qty,
				tpli.prli_price,
				ts.sm_name
				FROM tbCommercialTransactions						tct		WITH(NOLOCK)
					INNER JOIN tbItemTransactions					tit		WITH(NOLOCK)
						ON	tit.comp_id			= tct.comp_id		AND
							tit.ct_transaction	= tct.ct_transaction
					INNER JOIN tbItem								ti		WITH(NOLOCK)
						ON	ti.comp_id			= tit.comp_id		AND
							ti.item_id			= tit.item_id
					INNER JOIN tbPriceListItems						tpli	WITH(NOLOCK)
						ON	tpli.comp_id		= tct.comp_id		AND
							tpli.prli_id		= tit.prli_id		AND
							tpli.item_id		= @item_id_2Return
					INNER JOIN tbSalesman							ts
						ON	ts.comp_id			= tct.comp_id		AND
							ts.sm_id			= tct.sm_id
				WHERE	tct.comp_id				= @comp_id			AND
						tct.ct_transaction		= @ct_transaction	AND
						tit.item_id				= @item_id_2Return
		-- -------------------------------------------------------------------------------------------------------------

		-- -------------------------------------------------------------------------------------------------------------
		-- DATOS DE TABLA DE REPORTES
		-- -------------------------------------------------------------------------------------------------------------
			EXEC [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id
		-- -------------------------------------------------------------------------------------------------------------

		-- -------------------------------------------------------------------------------------------------------------
		--OBTENEMOS LOS DATOS DEL CT_TRANSACTION CLONADO PARA EL ARTÍCULO QUE SE DA COMO CAMBIO
		-- -------------------------------------------------------------------------------------------------------------
			SELECT
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction)	[Document_4Change],
				ti.item_code																		[item_code_4Change],
				ti.item_desc																		[item_desc_4Change],
				tit.it_qty																			[it_qty_4Change],
				tpli.prli_price																		[item_price_4Change],
				ts.sm_name																			[sm_name_4Change]
				FROM tbCommercialTransactions								tct		WITH(NOLOCK)
					INNER JOIN tbItemTransactions							tit		WITH(NOLOCK)
						ON	tit.comp_id			= tct.comp_id				AND
							tit.ct_transaction	= tct.ct_transaction
					INNER JOIN tbItem										ti		WITH(NOLOCK)
						ON	ti.comp_id			= tit.comp_id				AND
							ti.item_id			= tit.item_id
					INNER JOIN tbPriceListItems								tpli	WITH(NOLOCK)
						ON	tpli.comp_id		= tct.comp_id				AND
							tpli.prli_id		= tit.prli_id				AND
							tpli.item_id		= @item_id_4Change
					INNER JOIN tbSalesman									ts
						ON	ts.comp_id			= tct.comp_id				AND
							ts.sm_id			= tct.sm_id
				WHERE	tct.comp_id				= @comp_id					AND
						tct.ct_transaction		= @ct_transaction_Cloned	AND
						tit.item_id				= @item_id_4Change
		-- -------------------------------------------------------------------------------------------------------------

	END







GO



CREATE PROCEDURE [dbo].[spItemTransactions_PackingListDivision]
(
	@comp_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@it_transaction	INT,
	@qty			INT
)
AS
	SET NOCOUNT ON

		BEGIN

			--ACTUALIZAMOS LA ITEMTRANSACTIONS
			--RESTAMOS LA CANTIDAD QUE SE DIVIDIÓ

			UPDATE tbItemTransactions
			SET
				it_qty = it_qty - @qty
			WHERE	comp_id			= @comp_id			AND
					it_transaction	= @it_transaction


			--CREAMOS EL NUEVO REGISTRO QUE ES UNA COPIA DEL IT_TRANSACTION ORIGINAL
			--SOLO QUE LLEVA LA CANTIDAD DEFINIDA POR EL USUARIO
			INSERT INTO tbItemTransactions
			(
				comp_id,
				bra_id,
				ct_transaction,
				-- it_transaction -- this column value is auto-generated,
				item_id,
				it_qty,
				it_priceWithOutOthers,
				it_price,
				curr_id,
				it_exchangeToBranchCurrency,
				it_priceOfCost,
				it_priceOfCostPP,
				it_priceOfCostLastPurchase,
