CREATE PROCEDURE [dbo].[spItemTransactions_Relations_InsertData]
(
	@comp_id				AS	INT,
	@it_transaction_1		AS	INT,
	@it_transaction_2		AS	INT,
	@class					AS	INT,

	@return_value			AS	INT				OUTPUT,
	@ret_ErrorCode			AS	INT				OUTPUT,
	@ret_ErrorDescription	AS	VARCHAR(500)	OUTPUT
)
AS

	BEGIN
		SET NOCOUNT ON;
		-- ---------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------
			/*
			DECLARE
				@comp_id				INT,
				@it_transaction_1		INT,
				@it_transaction_2		INT,
				@class					INT,

				@return_value			INT,
				@ret_ErrorCode			INT,
				@ret_ErrorDescription	VARCHAR(200)
			SELECT
				@comp_id				= 1,
				@it_transaction_1		= 10340,
				@it_transaction_2		= 10406,
				@class					= 1,
				@return_value			= 0,
				@ret_ErrorCode			= 0,
				@ret_ErrorDescription	= ''
	*/
		-- ---------------------------------------------------
			BEGIN TRY

				SET @return_value			= 0
				SET @ret_ErrorCode			= 0
				SET @ret_ErrorDescription	= ''

			INSERT INTO tbItemTransactions_Relations
					(
						comp_id,
						it_transaction1,
						it_transaction2,
						class
					)
					VALUES
					(
						@comp_id,
						@it_transaction_1,
						@it_transaction_2,
						@class
					)

			END TRY
		BEGIN CATCH
			SET @ret_ErrorCode			= -1
			SET @ret_ErrorDescription	= ERROR_MESSAGE()
		END CATCH
	END
GO








CREATE PROCEDURE [dbo].[spItemTransactions_UpdateDataPending]

(
	@comp_id		INT,
	@bra_id			INT,
	@lang_id		INT,
	@it_transaction INT,
	@ct_transaction INT,
	@user_id		INT
)

AS

BEGIN

	SET NOCOUNT ON

	-- -------------------------------------------------
	-- Testing
	-- -------------------------------------------------
	/*
	DECLARE

		@comp_id		INT,
		@bra_id			INT,
		@lang_id		INT,
		@it_transaction INT,
		@ct_transaction INT


	SELECT


		@comp_id = 1,
		@bra_id = -1,
		@lang_id = 2,
		@it_transaction = 3305,
		@ct_transaction = 5231
	*/
	-- -------------------------------------------------

	BEGIN

		UPDATE	tbItemTransactions	WITH (ROWLOCK)
		SET		it_packingInvoicePend =  'False',
				it_packingInvoicePendCancell_user_id	= @user_id,
				it_packingInvoicePendCancell_cd			= GETDATE()
			WHERE  comp_id = @comp_id
			--AND   (@bra_id = -1 OR bra_id = @bra_id)
			--AND   (@it_transaction = -1 OR it_transaction = @it_transaction)
			AND   it_transaction = @it_transaction
			--AND   (@ct_transaction = -1 OR ct_transaction = @ct_transaction)  -- Quien pudo ser TAN pero TAN HIJO DE RE MIL PUTAS !!!!!!!!!!!!!!!!!!!
			AND   ct_transaction = @ct_transaction

	END


END
GO






CREATE PROCEDURE [dbo].[spItemTransactions_updateDiscounts]
(
	@comp_id			INT,
	@bra_id				INT,
	@ct_transaction		INT,
	@it_transaction		INT,
	@discount1			DECIMAL(19,6),
	@discount2			DECIMAL(19,6),
	@discount3			DECIMAL(19,6),
	@discount4			DECIMAL(19,6)
)
AS SET NOCOUNT ON



-- ------------------------------------------------------------
-- TESTING
-- ------------------------------------------------------------
/*
	DECLARE
		@comp_id			INT,
		@bra_id				INT,
		@ct_transaction		INT,
		@it_transaction		INT,
		@discount1			DECIMAL(19,6),
		@discount2			DECIMAL(19,6),
		@discount3			DECIMAL(19,6),
		@discount4			DECIMAL(19,6)

	SELECT
		@comp_id			= 1,
		@bra_id				= 1,
		@ct_transaction		= 3468,
		@it_transaction		= 2158,
		@discount1			= 1,
		@discount2			= 2,
		@discount3			= 3,
		@discount4			= 4
*/
-- ------------------------------------------------------------


DECLARE
	@loriginalPrice	DECIMAL(19,6)

SET @loriginalPrice = 0


SELECT
--	tit.it_OriginalPrice	= tit.it_price,
	@loriginalPrice			= tit.it_price

FROM tbItemTransactions		tit

WHERE	tit.comp_id			= @comp_id
AND		tit.bra_id			= @bra_id
AND		tit.ct_transaction	= @ct_transaction
AND		tit.it_transaction	= @it_transaction


DECLARE
	@lPricewithDiscounts	DECIMAL(19,6)

SET @lPricewithDiscounts = @loriginalPrice

-- ------------------------------------------------------------------------------------------------------------------
-- APLICACION DE DESCUENTOS AL PRECIO
-- ------------------------------------------------------------------------------------------------------------------

	--Se aplica el Primer Descuento
	SET @lPricewithDiscounts = @lPricewithDiscounts - (@lPricewithDiscounts * @discount1) / 100

	--Se aplica el Segundo Descuento
	SET @lPricewithDiscounts = @lPricewithDiscounts - (@lPricewithDiscounts * @discount2) / 100

	--Se aplica el Tercer Descuento
	SET @lPricewithDiscounts = @lPricewithDiscounts - (@lPricewithDiscounts * @discount3) / 100

	--Se aplica el Cuarto Descuento
	SET @lPricewithDiscounts = @lPricewithDiscounts - (@lPricewithDiscounts * @discount4) / 100
-- ------------------------------------------------------------------------------------------------------------------


-- -------------------------------------
-- Actualizamos la Tabla con el
-- resultado obtenido de los descuentos
-- -------------------------------------
UPDATE tbItemTransactions
SET
	it_price = @lPricewithDiscounts

WHERE	comp_id			= @comp_id
AND		bra_id			= @bra_id
AND		ct_transaction	= @ct_transaction
AND		it_transaction	= @it_transaction
-- -------------------------------------
GO







