CREATE PROCEDURE [dbo].[spItemTransactions_updateIsPacking]
(
	@comp_id				INT,
	@it_transaction			INT,
	@guid					UNIQUEIDENTIFIER
)
AS

BEGIN

	SET NOCOUNT ON


	/*seteamos el valor opuesto del que tiene en it_packingInvoiceSelected*/
	UPDATE	tbItemTransactions	WITH (ROWLOCK)
		SET		it_packingInvoiceSelected = Case
												When IsNull(it_packingInvoiceSelected,'false') = 'true' Then	'false'
												Else															'true'
											END,
				it_packingInvoiceSelectedGuid = @guid

		WHERE	it_transaction					=	@it_transaction
		AND		comp_id							=	@comp_id


END


GO




