-- Author:		GA
-- Create date: 12/23/2014.
-- Parte:		705.
-- Description:	Edición de Serialización de Ventas - Página de Detalle
-- ====================================================================================


CREATE PROCEDURE [dbo].[spItemTransactionSerial_Detail_Edit_Update]
(
	@comp_id			INT,
	@lang_id			INT,
	@serial_number		NVARCHAR(100),
	@its_id				INT
)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	--------------------------------------------------------------------------------
	-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
	--------------------------------------------------------------------------------
/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@serial_number		NVARCHAR(100),
			@its_id				INT

	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@serial_number		= 'V09300G10400494',
			@its_id				= 469
*/
	--------------------------------------------------------------------------------
	--------------------------------------------------------------------------------
	--------------------------------------------------------------------------------



BEGIN TRANSACTION
BEGIN TRY



	-- Recupera el viejo is_id
	DECLARE @is_id_original				INT,
			@lstor_id					INT,
			@it_transaction				INT,
			@sd_id						INT



	SELECT 	@is_id_original = tits.is_id,
			@it_transaction = tits.it_transaction,
			@sd_id			= tct.sd_id
		FROM	tbItemTransactionSerials tits		WITH (NOLOCK)
		LEFT JOIN tbCommercialTransactions AS tct	WITH (NOLOCK)
			ON	tct.comp_id			= tits.comp_id AND
				tct.ct_transaction	= tits.ct_transaction
		WHERE	tits.comp_id	= @comp_id
		AND		tits.its_id		= @its_id
		--SELECT 	@is_id_original,@it_transaction




	DECLARE @return_value		INT,
			@errormessage		VARCHAR(200)

	SET	@return_value = 0
	-- mensaje que el numero de serie se cambio correctamente.
	SET @errormessage = (select tut.utexts_desc
							FROM tbsysUniqueTexts tut
							WHERE	tut.lang_id		= @lang_id AND
									tut.utexts_id	= 224028)




	declare @litem_id			INT

	declare @lits_id			INT
	declare @lis_id_new			INT

	declare @lbra_id			INT
	declare @is_cd				DATETIME



	-- se guarda la sucursal, el artículo y el depósito del itemtransaction original
	-- recuperar el bra y el item desde tbitemtransaction porque si no tenía serial no sabe de donde sacar esos datos
	SELECT	@lbra_id	= tit.bra_id,
			@litem_id	= tit.item_id,
			@lstor_id	= stor_id
		FROM	tbItemTransactions		tit		WITH (NOLOCK)
		WHERE	tit.comp_id			= @comp_id
		AND		tit.it_transaction	= @it_transaction
	--SELECT	@lbra_id,@litem_id,@lstor_id




	SET		@is_cd		=  getdate()





	--verificamos que el numero de serie no sea el mismo que el que ya estaba.
	IF  @serial_number = (SELECT tis.is_serial FROM tbItemSerials tis WITH (NOLOCK) WHERE tis.is_id = @is_id_original)
		BEGIN
			-- mensaje que el numero de serie es el mismo.
			SET 	@return_value = 4
			SELECT	@errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 224027
		END



	--recuperamos el nuevo is_id
	if (select distinct tis.is_serial from tbItemSerials tis WITH (NOLOCK)  where tis.is_serial = @serial_number ) is not null
		begin
			set @lis_id_new = ( select tis.is_id from tbItemSerials tis WITH (NOLOCK)  where tis.is_serial = @serial_number )
		end
	else
		begin
			set @lis_id_new = null
		end



	--si llega null es por que no estaba el numero de serie y por ende no tiene is_id nuevo.
	IF @lis_id_new is null
		BEGIN
			-- mensaje que el numero de serie no existe.
			SET		@return_value = 3
			SELECT	@errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 224026
		END



	--verificamos que el item del is_id nuevo sea igual al is_id original
	IF @litem_id <> (SELECT tis.item_id FROM tbItemSerials tis  WITH (NOLOCK) WHERE tis.is_id = @lis_id_new)
		BEGIN
			-- mensaje que el numero de serie no corresponde al mismo articulo.
			SET 	@return_value = 2
			SELECT	@errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 224025
		END



	--verificamos si el nuevo is_id esta disponible
	if 'false' = (select tis.is_available from tbItemSerials tis  WITH (NOLOCK) where tis.is_id = @lis_id_new)
		BEGIN
			-- mensaje que el numero de serie no esta disponible.
			SET		@return_value = 1
			SELECT	@errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 224029
		END


	--MOS 03-2023: Solo se permiten serializar comprobantes que SACAN Stock y no los que INcorporan.
	if @sd_id NOT IN (1,2,4)
		BEGIN
			-- mensaje que el numero de serie no esta disponible.
			SET		@return_value = 1
			SELECT	@errormessage = 'ATENCIÓN: Solo se pueden serializar comprobantes de EGRESO de Stock.  Para Notas de Crédito u otros comprobantes, serializar el PEDIDO antes de EMITIRLO!'
		END




	IF @return_value = 0
		BEGIN

			--SET @return_value = 111



			--actualiza el campo disponible para el nuevo is_id ( en no disponible )
			UPDATE	tbItemSerials
				SET		is_available	= 'False',
						stor_id			= @lstor_id
				WHERE	comp_id			= @comp_id
				AND 	is_id			= @lis_id_new




			DECLARE @limpData_id				INT

			SELECT	@limpData_id	= tid.impData_id
				FROM	tbImportData				tid	WITH (NOLOCK)
				INNER JOIN tbItemSerials			tis	WITH (NOLOCK)
					ON	tis.comp_id			= tid.comp_id
					AND tis.ct_transaction	= tid.ct_transaction
					AND tis.it_transaction	= tid.it_transaction
					AND tis.item_id			= tid.item_id
					AND tis.is_id			= @lis_id_new
				WHERE	tid.comp_id		= @comp_id




			--actualiza el is_id original por el nuevo
			UPDATE	tbItemTransactionSerials
				SET		is_id			= @lis_id_new,
						impData_id		= @limpData_id
				WHERE	comp_id			= @comp_id
				AND   	its_id			= @its_id





			UPDATE	tbImportData
				SET		impData_ActualQty = impData_ActualQty - 1
				WHERE	comp_id		= @comp_id
				AND		item_id		= @litem_id
				AND		impData_id	= @limpData_id






			IF not @is_id_original IS NULL
				BEGIN

					--SET @return_value = 222



					--actualiza el campo disponible para el viejo is_id ( en disponible )
					UPDATE	tbItemSerials
						SET		is_available	= 'True'
						WHERE	comp_id			= @comp_id
						AND 	is_id			= @is_id_original




					SELECT	@limpData_id	= tid.impData_id
						FROM	tbImportData				tid	WITH (NOLOCK)
						INNER JOIN tbItemSerials	tis			WITH (NOLOCK)
							ON	tis.comp_id			= tid.comp_id
							AND tis.ct_transaction	= tid.ct_transaction
							AND tis.it_transaction	= tid.it_transaction
							AND tis.item_id			= tid.item_id
							AND tis.is_id			= @is_id_original
						WHERE	tid.comp_id		= @comp_id




					UPDATE	tbImportData
						SET		impData_ActualQty = impData_ActualQty + 1
						WHERE	comp_id		= @comp_id
						AND		item_id		= @litem_id
						AND		impData_id	= @limpData_id




					--insert (historial que se lleva con el is_id original y el nuevo).
					INSERT INTO tbItemTransactionSerials_Replacements
					(
						comp_id,
						bra_id,
						its_id,
						is_id_original,
						is_id_new,
						cd
					)
					VALUES
					(
						@comp_id,
						@lbra_id,
						@its_id,
						@is_id_original,
						@lis_id_new,
						@is_cd
					)


				END

		END


	COMMIT TRANSACTION


END
TRY BEGIN CATCH

	ROLLBACK TRANSACTION
	SET @return_value = -1
	SET @errormessage = ERROR_MESSAGE()

END CATCH


SELECT	@return_value [Value], @errormessage [Error]

END
GO







-- ====================================================================================
-- Author:		GA.
-- Create date: 11/30/2010.
-- Parte:		705.
-- Description:	Edicion de Serializacion de Ventas - Numero de series tomados.
-- ====================================================================================


CREATE PROCEDURE [dbo].[spItemTransactionSerial_Detail_getData]
(
	@comp_id			INT,
	@lang_id			INT,
	@ct_transaction		INT
)
AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	--------------------------------------------------------------------------------
	-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
	--------------------------------------------------------------------------------
/*
	DECLARE
		@comp_id			INT,
		@lang_id			INT,
		@ct_transaction		INT

	SELECT
		@comp_id			= 1,
		@lang_id			= 2,
		@ct_transaction		= 6668
*/
	--------------------------------------------------------------------------------
	--------------------------------------------------------------------------------
	--------------------------------------------------------------------------------


		SELECT	' ' [ ],
				ti.item_code,
				ti.item_desc,
				tits.its_id,
				isnull(tis.is_serial,'')		[is_serial],
				isnull(tits.its_id,'')			[ID]

		FROM	tbItemTransactionSerials					tits	WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions				tct		WITH (NOLOCK)
			ON	tct.comp_id			= tits.comp_id
			AND tct.bra_id			= tits.bra_id
			AND tct.ct_transaction	= tits.ct_transaction

			INNER JOIN tbItemTransactions					tit		WITH (NOLOCK)
			ON	tit.comp_id			= tits.comp_id
			AND tit.bra_id			= tits.bra_id
			AND tit.it_transaction	= tits.it_transaction
			AND tit.ct_transaction	= tits.ct_transaction

			LEFT JOIN tbItemSerials							tis		WITH (NOLOCK)
			ON	tis.comp_id			= tits.comp_id
			AND tis.is_id			= tits.is_id

			INNER JOIN tbItem								ti		WITH (NOLOCK)
			ON	ti.comp_id			= tits.comp_id
			AND ti.item_id			= tit.item_id

	WHERE	tits.comp_id			= @comp_id
	and		tits.ct_transaction		= @ct_transaction

END
GO







CREATE PROCEDURE [dbo].[spItemTransactionSerial_getData]

(

	@comp_id			INT,
	@lang_id			INT,


	@serial_number		NVARCHAR(100),
	@date_from			DATETIME,
	@date_to		    DATETIME,
	@cust_id			INT,
	@ct_docNumber	    NVARCHAR(50)


)

AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------
/*
	DECLARE

		@comp_id			INT,
		@lang_id			INT,


		@serial_number		NVARCHAR(100),
		@date_from			DATETIME,
		@date_to			DATETIME,
		@cust_id			INT,
		@ct_docNumber	    NVARCHAR(50)



	SELECT

		@comp_id		= 1,
		@lang_id		= 2,


		@serial_number  = '',
		@date_from		='2000-01-01',
		@date_to		='2010-12-31',
		@cust_id		= -1,
		@ct_docNumber	= 0
*/
	-- -----------------------------------------------------------------------------


	SELECT	DISTINCT
				' ' [ ],
				ISNULL(CONVERT(VARCHAR, tct.ct_date,103),'')										[Fecha],
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction)	[Comprobante],
				tc.cust_name																		[Cliente],
				td.dl_name																			[Transporte],
				tct.ct_total																		[Total],
				CONVERT(VARCHAR,tct.ct_transaction)													[ID]


				FROM tbCommercialTransactions												tct		WITH (NOLOCK)


				INNER JOIN vwCommercialTransactions_forSalesStatsPlusPackingList			vctfss		WITH (NOLOCK)

				ON  vctfss.comp_id		  = tct.comp_id
				--AND vctfss.bra_id		  = tct.bra_id
				AND vctfss.ct_transaction = tct.ct_transaction

				LEFT JOIN tbItemTransactions												tit		WITH (NOLOCK)

				ON	tit.bra_id			  = tct.bra_id
				AND tit.comp_id		      = tct.comp_id
				AND tit.ct_transaction	  = tct.ct_transaction

				INNER JOIN tbCustomer														tc		WITH (NOLOCK)

				ON tc.comp_id             = tct.comp_id
				AND tc.cust_id			  = tct.cust_id

				INNER JOIN tbDelivery														td		WITH (NOLOCK)

				ON td.comp_id			  = tct.comp_id
				AND td.dl_id			  = tct.dl_id

				LEFT JOIN tbItemTransactionSerials											tits		WITH (NOLOCK)

				ON  tits.it_transaction	  = tit.it_transaction
				AND tits.ct_transaction   = tit.ct_transaction
				AND tits.comp_id          = tit.comp_id

				LEFT JOIN tbItemSerials														tis		WITH (NOLOCK)

				ON	tis.comp_id			  = tits.comp_id
				AND tis.is_id			  = tits.is_id



	WHERE	tct.comp_id	= @comp_id
	AND		(@cust_id   = -1	OR tct.cust_id		= @cust_id)
	AND		(tct.ct_date BETWEEN @date_from AND @date_to)
	AND   (
			  (@ct_docNumber = 0) OR
			  (not tct.ct_docNumber IS null AND tct.ct_docNumber = @ct_docNumber)
	   		  )
	AND   (
			  (@serial_number = '') OR
			  (not  tis.is_serial IS null AND tis.is_serial = @serial_number)
	)

	ORDER BY ID

END
GO






-- ====================================================================================
-- Author:		GA.
-- Create date: 03/10/2011.
-- Parte:		-
-- Description:	Recuperar número de serie según el its_id
-- ====================================================================================


CREATE PROCEDURE [dbo].[spItemTransactionSerial_getSerial]

(

	@comp_id			INT,
	@lang_id			INT,

	@its_id				INT

)

AS


BEGIN



	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	--------------------------------------------------------------------------------
	-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
	--------------------------------------------------------------------------------
/*

	DECLARE

		@comp_id			INT,
		@lang_id			INT,

		@its_id				INT


	SELECT

		@comp_id		= 1,
		@lang_id		= 2,

		@its_id			= 647

*/
	--------------------------------------------------------------------------------
	--------------------------------------------------------------------------------
	--------------------------------------------------------------------------------


	SELECT	isnull(tis.is_serial,'') [is_serial]


			FROM tbItemTransactionSerials					tits		WITH (NOLOCK)


			INNER JOIN tbCommercialTransactions			tct		WITH (NOLOCK)
			ON	tct.comp_id			= tits.comp_id
			AND tct.bra_id			= tits.bra_id
			AND tct.ct_transaction	= tits.ct_transaction

			INNER JOIN tbItemTransactions				tit		WITH (NOLOCK)
			ON	tit.comp_id			= tits.comp_id
			AND tit.bra_id			= tits.bra_id
			AND tit.it_transaction	= tits.it_transaction
			AND tit.ct_transaction	= tits.ct_transaction

			left JOIN tbItemSerials					tis		WITH (NOLOCK)
			ON	tis.comp_id			= tits.comp_id
			AND tis.is_id			= tits.is_id

			INNER JOIN tbItem							ti		WITH (NOLOCK)
			ON	ti.comp_id			= tits.comp_id
			AND ti.item_id			= tit.item_id



	WHERE	tits.comp_id			= @comp_id
	and		tits.its_id				= @its_id




END
GO


CREATE PROCEDURE [dbo].[spItemTransactionSerials_getDataBySerials]
(
	@comp_id			INT,
	@cust_id			INT,
	@serial				NVARCHAR(100),
	@prof_id			INT,
	@bra_id				INT
)
AS

SET NOCOUNT ON


BEGIN

	-- ----------------------------------------------------
	-- Test
	-- ----------------------------------------------------
	/*
	declare	@comp_id		INT,
			@cust_id		INT,
			@serial			VARCHAR(100),
			@prof_id AS INT = 1,
			@bra_id AS INT = 1
	select	@comp_id		= 1,
			@cust_id		= 24300,
			@serial			= 'A04'
	*/
	-- ----------------------------------------------------



	-- MOS 04-2022 x Security One 14548
	-- (*) R.M.A. Clientes - Artículos comprados por el Cliente con Número de Serie, Cargar con PRECIO en Moneda de Orígen
	DECLARE @bra_saleOrder_RMAWithOriginalExchange AS BIT = 'False'
	IF EXISTS (	SELECT TOP 1  1
					FROM tbControlProfiles tcp1	WITH(NOLOCK)
					WHERE	tcp1.comp_id	= @comp_id	AND
							tcp1.bra_id		= @bra_id	AND
							tcp1.prof_id	= @prof_id	AND
							tcp1.page_id	= 80000		AND
							tcp1.ctrl_id	= 6285)
		BEGIN
			SET @bra_saleOrder_RMAWithOriginalExchange = 'True'
		END


--==
--SELECT '@bra_saleOrder_RMAWithOriginalExchange',@bra_saleOrder_RMAWithOriginalExchange



	SELECT	TOP 1
			ti.item_code,
			ti.item_desc,
			tis.is_id,


--==
--9999,
--tit.ct_transaction,tit.it_transaction,
--tit.it_SalesCurrId4exchangeToBranchCurrency ,	tit.it_OriginalPriceCurrency,tit.it_exchangeToBranchCurrency,tit.it_exchangeToOriginalPriceCurrency,
--9999,
--==


			-- MOS 04-2022 x Security One 14548
			--ISNULL(tit.it_price	,0)		[it_price],
			CASE
				WHEN
					@bra_saleOrder_RMAWithOriginalExchange = 'TRUE'	 THEN
					-- Busca el precio al tipo de cambio de la moneda original
					-- Se puso asi dado que hasta aqui, 11-2010, no se grababan los campos it_exchangeToBranchCurrency y it_SalesCurrId4exchangeToBranchCurrency
					dbo.fnGetExchange2(	@comp_id,
										tit.it_price,
										tit.curr_id,
										ISNULL(tit.it_SalesCurrId4exchangeToBranchCurrency ,	tit.it_OriginalPriceCurrency),
										CASE
											when tit.it_exchangeToBranchCurrency IS NULL THEN tit.it_OriginalPriceCurrency
											ELSE tit.it_SalesCurrId4exchangeToBranchCurrency
										END	,
										tit.curr_id,
										CASE
											when tit.it_exchangeToBranchCurrency IS NULL THEN tit.it_exchangeToOriginalPriceCurrency
											ELSE tit.it_exchangeToBranchCurrency
										END,
										'false')
				ELSE 	ISNULL(tit.it_price	,0)
			END				[it_price],

			-- MOS 04-2022 x Security One 14548
			--ISNULL(tit.curr_id	,0)		[curr_id],
			CASE
				WHEN
					@bra_saleOrder_RMAWithOriginalExchange = 'TRUE'	 THEN	ISNULL(tit.it_SalesCurrId4exchangeToBranchCurrency ,	tit.it_OriginalPriceCurrency)
				ELSE																	tit.curr_id
			END							[curr_id],




			ISNULL(tit.stor_id	,0)		[stor_id],
			ISNULL(tit.bra_id	,0)		[bra_id],

			tis.item_id,
			tis.it_transaction,
			tis.is_available,
			tis.stor_id																		[stor_serial],
			ts.stor_desc,

			tct2.ct_date, --fecha de compra

			ts2.supp_name				+ ' - ' +
			tid.impData_Custom_local	+ ' - ' +
			tid.impData_Number_local														[aditional_data],

			ISNULL(DATEDIFF(DAY,tct2.ct_date,tb.bra_processingDate),0)						[quatity_purchase_days],
			ISNULL(ti.item_guarantee,0)														[item_guarantee],
			-- MOS: 11-2021, para que sume las fechas de 2do RMA x 2do cambio y q tome la garantia de la 1ra venta.
			--ISNULL(ti.item_guarantee,0) -
			--	ISNULL(DATEDIFF(DAY,tct.ct_date,tb.bra_processingDate),0)					[pending_guarantee_days]

			CASE
				WHEN tctRMACambio.comp_id IS NOT NULL THEN
														ISNULL(ti.item_guarantee,0) -
														ISNULL(DATEDIFF(DAY,tctRMACambio.ct_date,tb.bra_processingDate),0)
				ELSE
														ISNULL(ti.item_guarantee,0) -
														ISNULL(DATEDIFF(DAY,tct.ct_date,tb.bra_processingDate),0)
			END																						[pending_guarantee_days],
			ISNULL(ISNULL(tctRMACambio.ct_cd,tct.ct_cd),GETDATE())									[purchaseDate],
			ISNULL(tct.ct_cd,GETDATE())																[lastPurchaseDate],
			CASE
				WHEN tctRMACambio.comp_id IS NOT NULL THEN '*'
				ELSE '-'
			END																							[isRMAChange],

			ISNULL(dbo.fnGetCommercialTransactionDescription(@comp_id, 2, tct2.ct_transaction),'')		[Comprobante]





	FROM	tbItemTransactionSerials					tits		WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions			tct			WITH (NOLOCK)
			ON	tct.comp_id			= tits.comp_id
			AND tct.ct_transaction	= tits.ct_transaction

			INNER JOIN tbItemSerials					tis			WITH (NOLOCK)
			ON	tis.comp_id			= tits.comp_id
			AND tis.is_id			= tits.is_id

			INNER JOIN tbItem							ti			WITH (NOLOCK)
			ON	ti.comp_id			= tits.comp_id
			AND ti.item_id			= tis.item_id

			INNER JOIN tbItemTransactions				tit			WITH (NOLOCK)
			ON	tit.comp_id			= tits.comp_id
			AND tit.bra_id			= tits.bra_id
			AND tit.it_transaction	= tits.it_transaction
			AND tit.ct_transaction	= tits.ct_transaction

			INNER JOIN tbStorage						ts			WITH (NOLOCK)
			ON	ts.comp_id			= tits.comp_id
			AND ts.stor_id			= tis.stor_id



			-----------------------------------------------------------
			-- FECHA DE Primera Compra si es un RMA de un CAMBIO
			LEFT JOIN tbRMA_Detail				 AS trdRMACambio		WITH (NOLOCK)
				ON	trdRMACambio.comp_id		= tit.comp_id AND
					trdRMACambio.rmah_id		= tit.rmah_id AND
					trdRMACambio.rmad_id		= tit.rmad_id

			LEFT JOIN tbItemTransactions		AS titRMACambio			WITH (NOLOCK)
				ON	titRMACambio.comp_id		= trdRMACambio.comp_id AND
					titRMACambio.it_transaction = trdRMACambio.it_transaction

			LEFT JOIN tbCommercialTransactions	AS tctRMACambio			WITH (NOLOCK)
				ON	tctRMACambio.comp_id		= titRMACambio.comp_id AND
					tctRMACambio.ct_transaction = titRMACambio.ct_transaction	--AND




			-----------------------------------------------------------
			-- FECHA DE COMPRA !!!
			LEFT JOIN	tbCommercialTransactions		tct2		WITH (NOLOCK)
			ON	tct2.comp_id		= tis.comp_id
			AND tct2.bra_id			= tis.bra_id
			AND tct2.ct_transaction	= tis.ct_transaction

			LEFT JOIN	tbSupplier						ts2			WITH (NOLOCK)
			ON  ts2.comp_id			= tis.comp_id
			AND ts2.supp_id			= tct2.supp_id

			LEFT JOIN	tbImportData					tid			WITH (NOLOCK)
			ON  tid.comp_id			= tis.comp_id
			AND tid.item_id			= tis.item_id
			AND tid.it_transaction	= tis.it_transaction
			-----------------------------------------------------------

			LEFT JOIN tbBranch							tb			WITH (NOLOCK)
			ON	tb.comp_id			= tct.comp_id
			AND tb.bra_id			= tct.bra_id


	WHERE	tits.comp_id			= @comp_id
	AND		tct.cust_id				= @cust_id
	AND		tis.is_serial			= @serial

	ORDER BY tits.it_transaction DESC







END
GO







CREATE PROCEDURE [dbo].[spItemTransactionSerials_getDataBySerials4RMAInternalCustomer]
(
	@comp_id			INT,
	@bra_id				INT,
	@cust_id			INT,
	@serial				NVARCHAR(100)
)
AS

SET NOCOUNT ON


BEGIN



	-- ---------------------------------------------------
	-- Solo deberia entrar por aca si el cliente es
	-- para RMA Interno
	-- ---------------------------------------------------
		BEGIN

			SELECT
					ti.item_code,
					ti.item_desc,
					tits.is_id,

					ISNULL(tit.it_price	,0)		[it_price],
					ISNULL(tit.curr_id	,0)		[curr_id],
					ISNULL(tb2.bra_RMA_storId4OK	,0)		[stor_id],
					ISNULL(tit.bra_id	,0)		[bra_id],

					tits.item_id,
					tit.it_transaction,
					tits.is_available,
					/*tit.stor_id*/ tb2.bra_RMA_storId4OK								[stor_serial],
					ts.stor_desc,

					tct.ct_date, --fecha de compra

					ts2.supp_name				+ ' - ' +
					tid.impData_Custom_local	+ ' - ' +
					tid.impData_Number_local											[aditional_data],

					ISNULL(DATEDIFF(DAY,tct.ct_date,tb.bra_processingDate),0)			[quatity_purchase_days],

					ISNULL(ti.item_guarantee,0) -
						ISNULL(DATEDIFF(DAY,tct.ct_date,tb.bra_processingDate),0)		[pending_guarantee_days]





			FROM tbItemSerials									tits		WITH (NOLOCK)

					INNER JOIN tbBranch tb2
						ON	tb2.comp_id = @comp_id AND
							tb2.bra_id	= @bra_id

					INNER JOIN tbCommercialTransactions			tct		WITH (NOLOCK)
					ON	tct.comp_id			= tits.comp_id
					AND tct.ct_transaction	= tits.ct_transaction


					INNER JOIN tbItem							ti		WITH (NOLOCK)
					ON	ti.comp_id			= tits.comp_id
					AND ti.item_id			= tits.item_id

					INNER JOIN tbItemTransactions				tit		WITH (NOLOCK)
					ON	tit.comp_id			= tits.comp_id
					AND tit.it_transaction	= tits.it_transaction

					INNER JOIN tbStorage						ts		WITH (NOLOCK)
					ON	ts.comp_id			= tb2.comp_id
					AND ts.stor_id			= tb2.bra_RMA_storId4OK


					-----------------------------------------------------------


					LEFT JOIN	tbSupplier						ts2		WITH (NOLOCK)
					ON  ts2.comp_id			= tct.comp_id
					AND ts2.supp_id			= tct.supp_id

					LEFT JOIN	tbImportData					tid		WITH (NOLOCK)
					ON  tid.comp_id			= tit.comp_id
					AND tid.item_id			= tit.item_id
					AND tid.it_transaction	= tit.it_transaction
					-----------------------------------------------------------

					LEFT JOIN tbBranch							tb		WITH (NOLOCK)
					ON	tb.comp_id			= tct.comp_id
					AND tb.bra_id			= tct.bra_id


			WHERE	tits.comp_id			= @comp_id
			AND		tits.is_serial			= @serial

			--ORDER BY tits.it_transaction DESC

		END
	-- ---------------------------------------------------






END
GO





