CREATE PROCEDURE [dbo].[spItemTransactionsFromOtherERP_Process_Auto_Validate]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@cust_id					INT,
	@ith_qty					DECIMAL(19,4),
	@ith_priceNoTax				DECIMAL(19,4),
	@ith_pricePlusTax			DECIMAL(19,4),
	@sd_id						INT,
	@ith_kindOf					CHAR(4),
	@ith_poitOfSale				INT,
	@ith_docNumber				NVARCHAR(50),
	@ith_date					DATETIME,
	@ith_desc					NVARCHAR(400),
	@isfo_id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@ith_date_error				BIT





)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@item_id					INT,
	@cust_id					INT,
	@ith_qty					DECIMAL(19,4),
	@ith_priceNoTax				DECIMAL(19,4),
	@ith_pricePlusTax			DECIMAL(19,4),
	@sd_id						INT,
	@ith_kindOf					CHAR(4),
	@ith_poitOfSale				INT,
	@ith_docNumber				NVARCHAR(50),
	@ith_date					DATETIME,
	@ith_desc					NVARCHAR(400),
	@isfo_id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT




SELECT
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@curr_id					INT,
	@cust_name					NVARCHAR(200),
	@cust_name1					NVARCHAR(200),
	@cust_address				NVARCHAR(150),
	@cust_city					NVARCHAR(60),
	@cust_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@cust_phone1				NVARCHAR(200),
	@cust_phone2				NVARCHAR(200),
	@cust_fax					NVARCHAR(200),

	@st_id						INT,
	@disc_id					INT,
	@dl_id						INT,
	@ck_id						INT,
	@sm_id						INT,
	@act_id						INT,
	@ss_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@cust_taxNumber				NVARCHAR(50),
	@cust_inactive				BIT,
	@stcIB_Id					INT,
	@cust_taxIBNumber			NVARCHAR(50),
	@cust_web					NVARCHAR(500),
	@cust_partnerOf				NVARCHAR(100),
	@cust_contact				NVARCHAR(100),
	@cust_email					NVARCHAR(300),
	@cust_credit_max			NUMERIC(17,2),
	@cust_credit_own			NUMERIC(17,2),
	@cust_note1					NVARCHAR(100),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------

SET NOCOUNT ON
SET DATEFORMAT 'YMD'

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''


	------Item-----------------------------------------------------------------------------------------------------------
	if	@item_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Artículo'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT ti.item_id
			               FROM tbItem ti		WITH (NOLOCK)
							WHERE	ti.comp_id = @comp_id AND
									ti.item_id	= @item_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Artículo es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------


	------Customer-----------------------------------------------------------------------------------------------------------
	if	@cust_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Cliente'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.cust_id
			               FROM tbCustomer tc		WITH (NOLOCK)
			               WHERE tc.comp_id = @comp_id AND
							     tc.cust_id	= @cust_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Cliente es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------


	------Cantidad-----------------------------------------------------------------------------------------------------------
	if	@ith_qty	= 0
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó la Cantidad'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Precio Sin Impuesto-----------------------------------------------------------------------------------------------------------
	if	@ith_priceNoTax	= 0
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Precio sin Impuesto'
		END
	-----------------------------------------------------------------------------------------------------------------------


	------Impuesto-----------------------------------------------------------------------------------------------------------
	if	@ith_pricePlusTax	= 0
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Impuesto'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Documento-----------------------------------------------------------------------------------------------------------
	if	@sd_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Documento'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT td.sd_id
			               FROM tbsysDocuments td		WITH (NOLOCK)
							WHERE	td.sd_id	= @sd_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Documento es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Tipo-----------------------------------------------------------------------------------------------------------
	if	@ith_kindOf	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Tipo'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Punto de venta-----------------------------------------------------------------------------------------------------------
	if	@ith_poitOfSale	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Punto de Venta'
		END
	-----------------------------------------------------------------------------------------------------------------------

		------Nro de doc-----------------------------------------------------------------------------------------------------------
	if	@ith_docNumber	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Número de Documento'
		END
	-----------------------------------------------------------------------------------------------------------------------


	------Fecha-----------------------------------------------------------------------------------------------------------
	if	@ith_date_error	= 1 --true
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó la Fecha o la misma es incorrecta'
		END
	------------------------------------------------------------------------------------------------------------------------------


	------Desc-----------------------------------------------------------------------------------------------------------
	if	@ith_desc	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó la Descripción'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------ISFO-----------------------------------------------------------------------------------------------------------
	if	@isfo_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Nº Serie'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.isfo_id
			               FROM tbItemSerialsFromOtherERP tc		WITH (NOLOCK)
			               WHERE tc.isfo_id	= @isfo_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID Nº Serie es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------


	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO


----------------------------------------------------------------------------------------------------------
create PROCEDURE [dbo].[spItemTransactionsFromOtherERP_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN



	SELECT
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151

	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO





