CREATE PROCEDURE [dbo].[spItemTransactionsICCTmp_insertData]
(
	@comp_id		INT,
	@bra_id			INT,
	@ct_transaction	INT,
	@it_transaction	INT,
	@guid			UNIQUEIDENTIFIER,
	@percentage		DECIMAL(19,6),
	@include		BIT
)

as
set nocount on

/*
DECLARE
	@comp_id		INT,
	@bra_id			INT,
	@ct_transaction	INT,
	@it_transaction	INT,
	@guid			UNIQUEIDENTIFIER,
	@percentage		DECIMAL(19,6),
	@include		BIT

SELECT
	@comp_id		=1,
	@bra_id			=1,
	@ct_transaction	=1304,
	@it_transaction	=831,
	@guid			='45b7f584-70ae-4d17-981d-392a3b8c75e9',
	@percentage		=15.56,
	@include		='False'
*/



IF EXISTS (SELECT 1 FROM dbo.tbItemTransactionsICCTmp
           WHERE	comp_id			=	@comp_id
		   AND		bra_id			=	@bra_id
		   AND		ct_transaction	=	@ct_transaction
		   AND		it_transaction	=	@it_transaction)

	DELETE dbo.tbItemTransactionsICCTmp
	WHERE	comp_id			=	@comp_id
	AND		bra_id			=	@bra_id
    AND		ct_transaction	=	@ct_transaction
    AND		it_transaction	=	@it_transaction



INSERT INTO dbo.tbItemTransactionsICCTmp
(
	comp_id,
	bra_id,
	ct_transaction,
	it_transaction,
	itt_guid,
	itt_percentage,
	itt_include
)
VALUES
(
	@comp_id,
	@bra_id,
	@ct_transaction,
	@it_transaction,
	@guid,
	@percentage,
	@include
)


GO


