CREATE  PROCEDURE [dbo].[spItemTransactionsTmp_CustomNumber_UpdateData]
(
	@comp_id						INT,
	@tis_guid						UNIQUEIDENTIFIER,
	@tis_impData_Custom_local		VARCHAR(20),		-- Aduana Operativa
	@tis_impData_Number_local		VARCHAR(20),		-- Despacho a Plaza
	@tis_impData_Origin				VARCHAR(100),		-- Origen
    @tis_impData_From				VARCHAR(100),		-- Procedencia
    @tis_impData_ExpirationDate		DATETIME,			-- Fecha de Vencimiento
    @tis_impdata_LotNumber			VARCHAR(50),		-- Numero de Lote
    @IsOverwrite					BIT					-- Sobreescribir todos los campos , True = sobreescribE los datos ingresados

)
AS
SET NOCOUNT ON

BEGIN

	UPDATE tbItemTransactionsTmp
	SET tis_impData_Custom_local		= @tis_impData_Custom_local

	WHERE	comp_id						= @comp_id
	AND		tis_guid					= @tis_guid
	AND		(ISNULL(tis_impData_Custom_local,'') = '' OR @IsOverwrite = 'True')

	--------

	UPDATE tbItemTransactionsTmp
	SET tis_impData_Number_local		= @tis_impData_Number_local

	WHERE	comp_id						= @comp_id
	AND		tis_guid					= @tis_guid
	AND		(ISNULL(tis_impData_Number_local,'') = '' OR @IsOverwrite = 'True')

	--------

	UPDATE tbItemTransactionsTmp
	SET tis_impData_Origin				= @tis_impData_Origin

	WHERE	comp_id						= @comp_id
	AND		tis_guid					= @tis_guid
	AND		(ISNULL(tis_impData_Origin,'')	= '' OR @IsOverwrite = 'True')

	--------

	UPDATE tbItemTransactionsTmp
	SET tis_impData_From				= @tis_impData_From

	WHERE	comp_id						= @comp_id
	AND		tis_guid					= @tis_guid
	AND		(ISNULL(tis_impData_From,'')	= '' OR @IsOverwrite = 'True')

	--------

	UPDATE tbItemTransactionsTmp
	SET tis_impData_ExpirationDate		= @tis_impData_ExpirationDate

	WHERE	comp_id						= @comp_id
	AND		tis_guid					= @tis_guid
	AND		(tis_impData_ExpirationDate	IS NULL OR @IsOverwrite = 'True')

	--------

	UPDATE tbItemTransactionsTmp
	SET tis_impdata_LotNumber			= @tis_impdata_LotNumber

	WHERE	comp_id						= @comp_id
	AND		tis_guid					= @tis_guid
	AND		(ISNULL(tis_impdata_LotNumber,'')	= '' OR @IsOverwrite = 'True')


END
GO






