CREATE   PROCEDURE [dbo].[spItemTransactionsTmp_deleteAndBlockData]
(
	@comp_id		INT,
	@bra_id			INT,
	@tis_id			INT,
	@return_value	INT OUTPUT
)
as
SET NOCOUNT ON

BEGIN TRANSACTION
BEGIN TRY

	--se elimina el item de orden de compra

	BEGIN

		--Prueba para que entre por -2
--		INSERT INTO tbBranch
--		(comp_id, bra_desc)
--		VALUES
--		(555, 'sdfsdfd')

		UPDATE	tbPurchaseOrderDetail		WITH (ROWLOCK)
		SET		pod_isEditing	= 'False',
				pod_isEditingCd = GETDATE()
		WHERE 	comp_id			= @comp_id
		AND		bra_id			= @bra_id
		AND		poh_id			IN (SELECT poh_id FROM tbItemTransactionsTmp	WITH (NOLOCK)
		  		      			    WHERE comp_id = @comp_id and tis_id	= @tis_id)
		AND		pod_id			IN (SELECT pod_id FROM tbItemTransactionsTmp	WITH (NOLOCK)
		  		      			    WHERE comp_id = @comp_id and tis_id	= @tis_id)


		EXEC spItemTransactionsTmp_deleteData @comp_id, @tis_id

		set	@return_value = @tis_id

	END

COMMIT TRANSACTION

END TRY
BEGIN CATCH
	set	@return_value = -2
	ROLLBACK TRANSACTION
END CATCH








GO






