CREATE  PROCEDURE [dbo].[spItemTransactionsTmp_deleteData]
(
	@comp_id			INT,
	@tis_id				INT
)
AS

BEGIN

	SET NOCOUNT ON

	DECLARE @intPOH AS INT = 0
	DECLARE @intPOD AS INT = 0

	SELECT	@intPOH = titt.poh_id,
			@intPOD = titt.pod_id
		FROM tbItemTransactionsTmp titt		WITH (NOLOCK)
		where	titt.comp_id	= @comp_id	AND
				titt.tis_id		= @tis_id


	-- LIbera Posibles Ordenes tomadas para se Ingresadas
	IF @intPOD > 0
		BEGIN
			UPDATE tbPurchaseOrderDetail
				SET pod_isEditing = 0
				WHERE	comp_id = @comp_id	AND
						poh_id	= @intPOH	AND
						pod_id	= @intPOD
		END


	--==============================================================================================
	UPDATE	tbItemTransactions
		SET		it_packingInvoiceSelected = 'false'
		WHERE	comp_id			= @comp_id
		AND		it_transaction	= (SELECT	isnull(titt.it_transaction,-1)
										FROM	tbItemTransactionsTmp titt		WITH (NOLOCK)
										WHERE 	comp_id			= @comp_id
											AND 	tis_id			= @tis_id)
	--==============================================================================================



	Delete	dbo.tbtmpTax
		where	comp_id			= @comp_id
			and tis_id			= @tis_id


	Delete	dbo.tbItemTransactionsTmp
		where	comp_id			= @comp_id
			and tis_id			= @tis_id



END
GO







-- -----------------------------------------------------------------
-- Modif. MOS 05-2008
-- OJO!!!!!    Si se agregan campos, agregarlos entre las etiquetas
-- de lugar de campos admitidos. JAMAS en otro lugar
-- porque hay problermas con la grilla de pedidos.-
-- -----------------------------------------------------------------


CREATE PROCEDURE [dbo].[spItemTransactionsTmp_getData]
(
	@comp_id			int,
	@tis_guid			uniqueidentifier
)
as

/*
declare @comp_id			int,
	@tis_guid			uniqueidentifier
select @comp_id			=1,
	@tis_guid			= '6b114ea4-7de0-4654-a7cd-12c9e871bceb'
*/

select	' ' [ ],
	    ' ' [ ],
        ' ' [ ],
		tis.tis_guid,
		tis.tis_priority,
		tis.item_id,
		tis.tis_itemDesc,
		s.stor_desc,
		tis.tis_qty,
		pl.prli_desc,
		tis.tis_price,
		c.curr_desc,
		tis.tis_detail,
		tis.curr_id,
		tis_itemDiscount,
		tis.tis_itemDiscountTotal,
		tis_CreditInt,
		tis_CreditIntPlus,
		i.item_code,
		tis.tis_initQty,
		tis.prli_id,
		tis.stor_id,
		tis.doc_id,
		tis.tis_CD,
		tis.bra_id,
		b.bra_desc,
		tis.soh_id,
		tis.tis_insertDate,
		tis.user_id,
		tis.aure_id,
		tis.puco_id,
		tax_id,
		aure_itemComposed,

		-- ----------------------------------------------------
		-- Agregar aca campos nuevos
	    -- ----------------------------------------------------



		-- ----------------------------------------------------


		-- Si tocas este orden final... se arma..!!!   jajaja
		dbo.fnGetAStock(@comp_id,
					tis.stor_id,
					tis.item_id,
					tis.tis_priority) as on_hand_included,
		isnull((select	1
				from	dbo.tbAutorizationRequest	ar
				where	ar.comp_id			=	tis.comp_id
				and		ar.aure_guid		=	tis.tis_guid
				and		ar.aure_genericId	=	tis.tis_id
				and		ar.aure_isok		=	'P'
				group by ar.aure_isok),0)  [P],
		isnull((select	1
				from	dbo.tbAutorizationRequest	ar
				where	ar.comp_id			=	tis.comp_id
				and		ar.aure_guid		=	tis.tis_guid
				and		ar.aure_genericId	=	tis.tis_id
				and		ar.aure_isok		=	'A'
				group by ar.aure_isok),0)  [A],
		isnull((select	1
				from	dbo.tbAutorizationRequest	ar
				where	ar.comp_id			=	tis.comp_id
				and		ar.aure_guid		=	tis.tis_guid
				and		ar.aure_genericId	=	tis.tis_id
				and		ar.aure_isok		=	'U'
				group by ar.aure_isok),0)  [U],

		tis.tis_id --el id tiene que estar obligatoriamente en última posición



from	dbo.tbItemTransactionsTmp			tis

		left join tbSysCurrency		c
		on	c.curr_id	= tis.curr_id

		left join dbo.tbPriceList		pl
		on	pl.comp_id	= tis.comp_id
		and pl.prli_id	= tis.prli_id

		left join dbo.tbStorage		s
		on	s.comp_id	= tis.comp_id
		and s.stor_id	= tis.stor_id

		left join dbo.tbBranch			b
		on	b.comp_id	= tis.comp_id
		and b.bra_id	= tis.bra_id

		left join dbo.tbItem			i
		on	i.comp_id	= tis.comp_id
		and i.item_id   = tis.item_id

where	tis.comp_id		=	@comp_id
and		tis.tis_guid	=	@tis_guid


order by tis.tis_id




















GO







