-- MOS 05-2008
-- ---------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spItemTransactionsTmp_getDataById]
(
	@comp_id			int,
	@tis_id				int
)
AS

BEGIN




	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-04
	-- Parte		: 429
	-- Description	: Obtener los valores de estiba y picking cargados en tbItemTransactionsTmp y los valores de
	--				  validación tbStorage
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-10-14
	-- Parte		: 616 - ver detalle de funcionalidad en wfmPurchaseDocs
	-- Description	: Se recupera el campo it_transacion, para ser utilizado en wfmPurchaseDocsItemsDetail, si el
	--				  valor es null se devuelve -1
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-12-04
	-- Parte		: 709
	-- Description	: Se recuperan los nuevos campos tis_impData_Origin y tis_impData_From
	-- =================================================================================================================



	/*
	declare		@comp_id		int,
				@tis_id			int
	select		@comp_id		=1,
				@tis_id			=1
	*/



	Select		tis.tis_priority,
				isnull(tis.item_id,-1)					[item_id],
				tis.tis_itemDesc,
				tis.tis_detail,
				tis.curr_id,
				c.curr_desc,
				tis.tis_initQty,
				tis.tis_qty,
				isnull(tis.prli_id,-1)					[prli_id],
				isnull(pl.prli_desc,'')					[prli_desc],
				tis.tis_price,
				tis.tis_cost,
				tis.tis_costTax,
				isnull(tis.stor_id,-1)					[stor_id],
				isnull(s.stor_desc,'')					[stor_desc],
				tis.doc_id,
				tis.tis_CD,
				b.bra_desc,
				tis.soh_id,
				tis.tax_id,
				tis.tis_insertDate,
				tis.user_id,
				i.item_code,
				i.[item_desc],
				tis.tis_id,
				isnull(cli.coslis_price,0)				[coslis_price],
				isnull(cli.coslis_price_aw,0)			[coslis_price_aw],
				tis.poh_id,
				tis.pod_id,
				tis.puco_id,
				pod.pod_price,
				pod.pod_qty,
				cli.curr_id								[coslis_Curr_Id],
				tis.tis_guarantee,
				isnull(tis.tis_impData_Custom_local,'')	[tis_impData_Custom_local],
				isnull(tis.tis_impData_Number_local,'') [tis_impData_Number_local],
				tis.tis_PriceB,
				isnull(tis.tis_PickingLocation,'')		[tis_PickingLocation],		-- Parte : 429
				isnull(tis.tis_StorageLocation,'')		[tis_StorageLocation],		-- Parte : 429
				isnull(ts.stor_REPicking,'')			[stor_REPicking],			-- Parte : 429
				isnull(ts.stor_REStorage,'')			[stor_REStorage],			-- Parte : 429
				isnull(tis.it_transaction,-1)			[it_transaction],			-- Parte : 616
				isnull(tis.tis_impData_Origin,'')		[tis_impData_Origin],		-- Parte : 709
				isnull(tis.tis_impData_From,'')			[tis_impData_From],			-- Parte : 709
				ISNULL(tis.tis_Discount1, 0)			[tis_Discount1],
				ISNULL(tis.tis_Discount2, 0)			[tis_Discount2],
				ISNULL(tis.tis_Discount3, 0)			[tis_Discount3],
				ISNULL(tis.tis_Discount4, 0)			[tis_Discount4],
				ISNULL(tis.it_isRMASupplierCreditNote,'False')	[it_isRMASupplierCreditNote],
				ISNULL(tis.tis_surcharge1, 0) [tis_surcharge1],
				ISNULL(tis.tis_surcharge2, 0) [tis_surcharge2],
				ISNULL(tis.tis_surcharge3, 0) [tis_surcharge3],
				ISNULL(tis.tis_surcharge4, 0)  [tis_surcharge4],
				ISNULL(tis.tis_impData_ExpirationDate,GETDATE())	[tis_impData_ExpirationDate],
				ISNULL(tis_impdata_LotNumber,'')	 [tis_impdata_LotNumber]


	From		dbo.tbItemTransactionsTmp			tis				WITH (NOLOCK)

				left join tbSysCurrency				c				WITH (NOLOCK)
				on	c.curr_id		= tis.curr_id

				left join dbo.tbPriceList			pl				WITH (NOLOCK)
				on	pl.comp_id		= tis.comp_id
				and pl.prli_id		= tis.prli_id

				left join dbo.tbStorage				s				WITH (NOLOCK)
				on	s.comp_id		= tis.comp_id
				and s.stor_id		= tis.stor_id

				left join dbo.tbBranch				b				WITH (NOLOCK)
				on	b.comp_id		= tis.comp_id
				and b.bra_id		= tis.bra_id

				left join dbo.tbItem				i				WITH (NOLOCK)
				on	i.comp_id		= tis.comp_id
				and i.item_id		= tis.item_id

				left join dbo.tbItemCostList		cli				WITH (NOLOCK)
				on	cli.comp_id		= i.comp_id
				and	cli.item_id		= i.item_id
				and cli.coslis_id	= b.coslis_id

				left join [tbPurchaseOrderDetail]	pod				WITH (NOLOCK)
				on	pod.comp_id		= tis.comp_id
				and pod.pod_id		= tis.pod_id

				LEFT JOIN tbStorage					ts				WITH (NOLOCK)
				ON	ts.comp_id		= tis.comp_id			-- Parte : 429
				AND ts.stor_id		= tis.stor_id			-- Parte : 429



	Where		tis.comp_id			= @comp_id
	and			tis.tis_id			= @tis_id


	Order by	tis.tis_id		-- IDIOTA !!!!


END
GO






CREATE  PROCEDURE [dbo].[spItemTransactionsTmp_insertandBlockData]
(
	@comp_id						int,
	@tis_guid						uniqueidentifier,
	@tis_priority					decimal(14,4),
	@item_id						int,
	@tis_itemDesc					varchar(100),
	@tis_detail						varchar(100),
	@curr_id						int,
	@tis_initQty					decimal(19,5),
	@tis_qty						decimal(19,5),
	@prli_id						int,
	@tis_price						decimal(19,6),
	@stor_id						int,
	@doc_id							int,
	@bra_id							int,
	@user_id						int,
	@insertDate						datetime,
	@lastUpdate						datetime,
	@tis_cost						decimal(19,5),
	@tis_costTax					int,
	@soh_id							int,
	@poh_id							int,
	@pod_id							int,
	@puco_id						int,
	@tis_guarantee					int,
	@tis_impData_Custom_local		VARCHAR(20),
	@tis_impData_Number_local		VARCHAR(20),
	@tis_pickinglocation			VARCHAR(20),		-- Parte : 429
	@tis_storagelocation			VARCHAR(20),		-- Parte : 429
	@tis_impData_Origin				VARCHAR(100),		-- Parte : 738
    @tis_impData_From				VARCHAR(100),		-- Parte : 738
    @decPriceB						decimal(19,6),
	@return_value					int output
)
AS

BEGIN




	SET NOCOUNT ON


-- -------------------------------------------------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------------------------------------------------
	/*
	DECLARE 		@comp_id					int,
		@tis_guid					uniqueidentifier,
		@tis_priority				decimal(14,4),
		@item_id					int,
		@tis_itemDesc				varchar(100),
		@tis_detail					varchar(100),
		@curr_id					int,
		@tis_initQty				decimal(19,5),
		@tis_qty					decimal(19,5),
		@prli_id					int,
		@tis_price					decimal(19,6),
		@stor_id					int,
		@doc_id						int,
		@bra_id						int,
		@user_id					int,
		@insertDate					datetime,
		@lastUpdate					datetime,
		@tis_cost					decimal(19,5),
		@tis_costTax				int,
		@soh_id						int,
		@poh_id						int,
		@pod_id						int,
		@puco_id					int,
		@tis_guarantee				int,
		@tis_impData_Custom_local	AS VARCHAR(20),
		@tis_impData_Number_local	AS VARCHAR(20),
		@tis_pickinglocation			VARCHAR(20),		-- Parte : 429
		@tis_storagelocation			VARCHAR(20),		-- Parte : 429
		@return_value				AS INT


	select 			@comp_id					=1,
		@tis_guid					='453bfd04-052b-47a1-9986-99e9ab444794',
		@tis_priority				=0,
		@item_id					=264,
		@tis_itemDesc				='ss',
		@tis_detail					='detalle',
		@curr_id					=1,
		@tis_initQty				=1,
		@tis_qty					=99,
		@prli_id					=null,
		@tis_price					=52,
		@stor_id					=1,
		@doc_id						=0,
		@bra_id						=1,
		@user_id					=1,
		@insertDate					='2010-01-01',
		@lastUpdate					='2010-01-01',
		@tis_cost					=0,
		@tis_costTax				=0,
		@soh_id						=null,
		@poh_id						=87,
		@pod_id						=19711,
		@puco_id					=2,
		@tis_guarantee				=0,
		@tis_impData_Custom_local	='',
		@tis_impData_Number_local	='',
		@tis_pickinglocation		='',
		@tis_storagelocation		=''
		--@return_value				AS int output
	*/
-- -------------------------------------------------------------------------------------------------------------
--set	@return_value = -1
--RETURN

	BEGIN TRANSACTION
	BEGIN TRY

		DECLARE @bitIsEditing AS BIT
		SET		@bitIsEditing = 'False'

		IF EXISTS(
					SELECT TOP 1   1
		           		from tbPurchaseOrderDetail tpod	WITH (NOLOCK)
						where	tpod.comp_id			= @comp_id
						--AND		tpod.bra_id				= @bra_id   MOS 11-2019, no deberia molestar por el Identity del detail
						AND		tpod.poh_id				= @poh_id
						AND		tpod.pod_id				= @pod_id
						AND		isnull(tpod.pod_isEditing,'False') = 'True'
				)
			BEGIN
				SET @bitIsEditing = 'True'
			END

		IF EXISTS(
					SELECT TOP 1   1
						from tbPurchaseOrderHeader tpoh	WITH (NOLOCK)
						where	tpoh.comp_id			= @comp_id
						AND		tpoh.bra_id				= @bra_id
						AND		tpoh.poh_id				= @poh_id
						AND		isnull(tpoh.poh_isEditing,'False') = 'True'
				)
			BEGIN
				SET @bitIsEditing = 'True'
			END




		--IF (
		--	ISNULL((	SELECT  1
		--           		from tbPurchaseOrderDetail tpod	WITH (NOLOCK)
		--				where	tpod.comp_id			= @comp_id
		--				AND		tpod.bra_id				= @bra_id
		--				AND		tpod.poh_id				= @poh_id
		--				AND		tpod.pod_id				= @pod_id
		--				AND		isnull(tpod.pod_isEditing,'False') = 'True'),0)

		--	+

		--	ISNULL((SELECT  1
		--				from tbPurchaseOrderHeader tpoh	WITH (NOLOCK)
		--				where	tpoh.comp_id			= @comp_id
		--				AND		tpoh.bra_id				= @bra_id
		--				AND		tpoh.poh_id				= @poh_id
		--				AND		isnull(tpoh.poh_isEditing,'False') = 'True'),0) = 0
		--	)


		IF @bitIsEditing = 'False'

			BEGIN



				DECLARE @rv INT

				UPDATE	tbPurchaseOrderDetail
				SET		pod_isEditing	= 'True',
						pod_isEditingCd = GETDATE()
				where	comp_id			= @comp_id
				--AND		bra_id			= @bra_id   MOS 11-2019
				AND		poh_id			= @poh_id
				AND		pod_id			= @pod_id



				EXEC spItemTransactionsTmp_insertData
					@comp_id,						@tis_guid,						@tis_priority,
					@item_id,						@tis_itemDesc,					@tis_detail,
					@curr_id,						@tis_initQty,					@tis_qty,
					@prli_id,						@tis_price,						@stor_id,
					@doc_id,						@bra_id,						@user_id,
					@insertDate,					@lastUpdate,					@tis_cost,
					@tis_costTax,					@soh_id,						@poh_id,
					@pod_id,						@puco_id,						@tis_guarantee,
					@tis_impData_Custom_local,		@tis_impData_Number_local,		@decPriceB ,
					@tis_pickinglocation,				-- Parte : 429
					@tis_storagelocation, 				-- Parte : 429
					0,									-- Ref #1
					@tis_impData_Origin,				-- Parte : 709, 738
					@tis_impData_From,					-- Parte : 709, 738
					@return_value = @rv OUTPUT


				SET @return_value = @rv


			END
		ELSE
			BEGIN
 				set	@return_value = -1
			END

		COMMIT TRANSACTION


	END TRY
	BEGIN CATCH
		set	@return_value = -2
		ROLLBACK TRANSACTION
	END CATCH



END
GO






CREATE  PROCEDURE [dbo].[spItemTransactionsTmp_insertData]
(
	@comp_id						int,
	@tis_guid						uniqueidentifier,
	@tis_priority					decimal(14,4),
	@item_id						int,
	@tis_itemDesc					varchar(100),
	@tis_detail						varchar(100),
	@curr_id						int,
	@tis_initQty					decimal(19,5),
	@tis_qty						decimal(19,5),
	@prli_id						int,
	@tis_price						decimal(19,6),
	@stor_id						int,
	@doc_id							int,
	@bra_id							int,
	@user_id						int,
	@insertDate						datetime,
	@lastUpdate						datetime,
	@tis_cost						decimal(19,5),
	@tis_costTax					int,
	@soh_id							int,
	@poh_id							int,
	@pod_id							int,
	@puco_id						int,
	@tis_guarantee					int,
	@tis_impData_Custom_local		VARCHAR(20),
	@tis_impData_Number_local		VARCHAR(20),
	@tis_PriceB						DECIMAL(19,6),
	@tis_pickinglocation			VARCHAR(250),		-- Parte : 429
	@tis_storagelocation			VARCHAR(250),		-- Parte : 429
	@forcedValue					DECIMAL(19,6),
	@tis_impData_Origin				VARCHAR(100),		-- Parte : 709
    @tis_impData_From				VARCHAR(100),		-- Parte : 709
	@return_value					INT				OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-04
	-- Parte		: 429
	-- Description	: Actualizar los valores de estiba y picking en tbItemTransactionsTmp
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-12-04
	-- Parte		: 709
	-- Description	: Se agrega la actualización de los nuevos campos tis_impData_Origin y tis_impData_From
	-- =================================================================================================================


	-- Enfermo y la recontra reputa madre que te recontra re nmil pario  HDPPPPPPPPPP FORROOOOOOOO  MOS 05-2023
	DECLARE		@tis_poh_bra_id		INT
	SELECT		@tis_poh_bra_id			= tpoh.bra_id
		FROM		tbPurchaseOrderDetail	tpoh		WITH (NOLOCK)
		WHERE		tpoh.comp_id		= @comp_id	AND
					tpoh.poh_id			= @poh_id	AND
					tpoh.pod_id			= @pod_id			-- MOS 05-2023: x adma, si se duplicaba

	--DECLARE		@tis_poh_bra_id		INT
	--SELECT		@tis_poh_bra_id		= tpoh.bra_id
	--	FROM		tbPurchaseOrderHeader	tpoh		WITH (NOLOCK)
	--	WHERE		tpoh.comp_id		= @comp_id	AND
	--				tpoh.poh_id			= @poh_id	AND
	--				tpoh.pod_id			= @pod_id			-- MOS 05-2023: x adma, si se duplicaba







	insert into dbo.tbItemTransactionsTmp
	(	comp_id,
		tis_guid,
		tis_priority,
		item_id,
		tis_itemDesc,
		tis_detail,
		curr_id,
		tis_initQty,
		tis_qty,
		prli_id,
		tis_price,
		tis_cost,
		tax_id,
		stor_id,
		doc_id,
		tis_CD,
		bra_id,
		soh_id,
		tis_insertDate,
		tis_itemDiscount,
		tis_IsEditingCd,
		user_id,
		poh_id,
		pod_id,
		puco_id,
		tis_guarantee,
		tis_impData_Custom_local,
		tis_impData_Number_local,
		tis_poh_bra_id,
		tis_PriceB,
		tis_PickingLocation,		-- Parte : 429
		tis_StorageLocation,		-- Parte : 429
		tis_forcedValue,
		tis_impData_Origin,			-- Parte : 709
		tis_impData_From			-- Parte : 709
	)
	values
	(
		@comp_id,
		@tis_guid,
		@tis_priority,
		@item_id,
		@tis_itemDesc,
		@tis_detail,
		@curr_id,
		@tis_initQty,
		@tis_qty,
		@prli_id,
		@tis_price,
		@tis_cost,
		@tis_costTax,
		@stor_id,
		@doc_id,
		@insertDate,
		@bra_id,
		@soh_id,
		@lastUpdate,
		0,
		getdate(),
		@user_id,
		@poh_id,
		@pod_id,
		@puco_id,
		@tis_guarantee,
		@tis_impData_Custom_local,
		@tis_impData_Number_local,
		@tis_poh_bra_id,
		@tis_PriceB,
		@tis_pickinglocation,		-- Parte : 429
		@tis_storagelocation,		-- Parte : 429
		@forcedValue,
		@tis_impData_Origin,		-- Parte : 709
		@tis_impData_From			-- Parte : 709
	)

	set	@return_value = @@identity

END

GO





-- OK 28-4-2015

CREATE PROCEDURE [dbo].[spItemTransactionsTmp_insertData_FromPurchasePacking]
(
	@comp_id			INT,
	@supp_id			INT,
	@guid				UNIQUEIDENTIFIER
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 200
	SET DEADLOCK_PRIORITY NORMAL
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- -----------------------------------------------------------------------------
	/*
	DECLARE		@comp_id		INT,
				@supp_id		INT,
				@guid			UNIQUEIDENTIFIER,
				@option			INT

	SELECT 		@comp_id		= 1,
				@supp_id		= 8103,
				@guid			= 'c1ea7685-c874-479a-a723-5badba9e2af0',
				@option			= 101
	*/
	-- -----------------------------------------------------------------------------


	BEGIN TRANSACTION
	BEGIN TRY




		--================================================================================================
		--recuperamos los tax_id que se puedan relacionar a los items que se cargan en PurchaseDocs
		--desde items de Remitos que no tienen tax_id relacionados
		SELECT	min(tit.tax_id) [tax_id], tit2.it_transaction

			INTO	#tmp_ItemTaxes

			FROM	tbItemTaxes								tit		WITH (NOLOCK)

					INNER JOIN tbItemTransactions			tit2		WITH (NOLOCK)
					ON	tit2.comp_id				= tit.comp_id
					AND tit2.item_id				= tit.item_id

			WHERE	tit.comp_id						= @comp_id
			AND   	tit2.it_packingInvoiceSelected	= 'true'

			GROUP BY tit2.it_transaction
		--================================================================================================







		INSERT INTO tbItemTransactionsTmp
		(		comp_id,						tis_guid,
				tis_priority, 					item_id,
				tis_itemDesc,
				tis_detail,
				curr_id, 						tis_initQty,
				tis_qty, 						prli_id,
				tis_price,						tis_cost,
				tax_id,
				stor_id,
				doc_id, 						tis_CD,
				bra_id, 						soh_id,
				tis_insertDate,					tis_itemDiscount,
				tis_IsEditingCd,				[user_id],
				poh_id, 						pod_id,
				puco_id,						tis_guarantee,

				tis_poh_bra_id,					tis_PriceB,
				tis_PickingLocation,			tis_StorageLocation,
				tis_forcedValue,				it_transaction,
				tis_Discount1, tis_Discount2,
				tis_Discount3, tis_Discount4,
				tis_surcharge1, tis_surcharge2,
				tis_surcharge3, tis_surcharge4,
				sod_id,
				tis_impData_Origin,
				tis_impData_From,
				tis_impData_ExpirationDate,
				tis_impdata_LotNumber,
				tis_impData_Custom_local,
				tis_impData_Number_local
		)

		SELECT	@comp_id,						@guid,
				0,								tit.item_id,
				CASE WHEN  tit.item_id IS NULL THEN titd.itm_desc else  ti.item_desc end,
				ti.item_detail,
				tit.curr_id,					tit.it_qty,
				tit.it_qty,						tit.prli_id,
				tit.it_priceWithOutOthers   /*tit.it_price*/,	-- MOS 04-2015
				tit.it_priceWithOutOthers	/*tit.it_price*/,
				tmpIT.tax_id,
				tit.stor_id,
				NULL,							tit.it_cd,
				tit.bra_id,						tit.it_soh_id,
				tit.it_cd,						tit.it_itemDiscountTotal,
				GETDATE(),						tct.[user_id],
				tit.it_poh_id,					tit.it_pod_id,
				tit.puco_id,					0,
				--NULL,							NULL,
				tit.it_poh_bra_id,				ISNULL(tit.it_priceB,ISNULL(tpod.pod_priceB,0)),
				NULL,							NULL,
				NULL,							tit.it_transaction,
				tit.it_Discount1, tit.it_Discount2,
				tit.it_Discount3, tit.it_Discount4,
				tit.it_surcharge1,tit.it_surcharge2,
				tit.it_surcharge3, tit.it_surcharge4,
				tit.it_sod_id,
				tpod.pod_Origin,
				tpod.pod_From,
				tpod.pod_ExpirationDate,
				tpod.pod_LotNumber,
				tpod.pod_custom,
				tpod.pod_customNumber

		FROM	tbItemTransactions								tit	WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions				tct	WITH (NOLOCK)
				ON  tct.comp_id			= tit.comp_id
				AND tct.bra_id			= tit.bra_id
				AND tct.ct_transaction	= tit.ct_transaction
				AND	tct.supp_id			= @supp_id


				left JOIN tbItem								ti	WITH (NOLOCK)
				ON	ti.comp_id			= tit.comp_id
				AND ti.item_id			= tit.item_id

				left JOIN tbItemTransactionDetails				titd	WITH (NOLOCK)
				ON	titd.comp_id		= tit.comp_id
				AND titd.bra_id			= tit.bra_id
				AND titd.ct_transaction = tit.ct_transaction
				AND titd.it_transaction = tit.it_transaction

				LEFT JOIN #tmp_ItemTaxes						tmpIT
				ON	tmpIT.it_transaction	= tit.it_transaction

				LEFT JOIN tbPurchaseOrderDetail AS tpod	WITH (NOLOCK)
					ON	tpod.comp_id	= tit.comp_id			AND
						tpod.bra_id		= tit.it_poh_bra_id		AND
						tpod.poh_id		= tit.it_poh_id			AND
						tpod.pod_id		= tit.it_pod_id

				--LEFT JOIN tbPurchaseOrderDetail tpod
				--	ON	tpod.comp_id	= tit.comp_id			AND
				--		tpod.bra_id		= tit.it_poh_bra_id		AND
				--		tpod.poh_id		= tit.it_poh_id			AND
				--		tpod.pod_id		= tit.it_pod_id


		WHERE 	tit.comp_id						= @comp_id
		AND		tit.it_packingInvoiceSelected	= 'true'
		AND		NOT EXISTS (SELECT TOP 1 	1
		   						FROM tbItemTransactionsTmp	titt	WITH (NOLOCK)
	   							WHERE	titt.it_transaction = tit.it_transaction
								AND		titt.comp_id		= @comp_id
								AND		titt.tis_guid		= @guid)

		ORDER BY	tit.ct_transaction DESC,
					ISNULL(tit.it_poh_id,-1),		-- MOS 03-2022 x MF
					ISNULL(tit.it_pod_id,-1),		-- MOS 03-2022 x MF
					tit.it_order


		COMMIT TRANSACTION

	END TRY
	BEGIN CATCH
		ROLLBACK TRANSACTION
	END CATCH


END
GO



create PROCEDURE [dbo].[spItemTransactionsTmp_PurchaseOrderReception_deleteData]
(
	@comp_id						INT,
	@guid							UNIQUEIDENTIFIER

)
as
set nocount on


DELETE FROM tbItemTransactionsTmp

WHERE	comp_id		=	@comp_id
AND		tis_guid	=	@guid
GO





