CREATE PROCEDURE [dbo].[spItemTransactionsTmp_PurchaseOrderReception_Detail_InsertData]
(

	 	 @comp_id					INT,
		 @guid						uniqueidentifier,
		 @user_id					INT,
		 @stor_id					INT,
		 @puco_id					INT,
		 @por_id					INT,
		 @IsavailablewithoutPO		BIT		-- habilitado para recepcion sin pedido previo

		 --@return_value				as int	output

)
AS



BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------

/*


DECLARE			 @comp_id					INT,
				 @guid						uniqueidentifier,
				 @user_id					INT,
				 @stor_id					INT,
				 @puco_id					INT,
				 @por_id					INT

SELECT			 @comp_id						= 1,
				 @guid							= '6e6f5998-9118-4c5c-bb58-723ada3ae6c6',
				 @user_id						= 1,
				 @stor_id						= 3,
				 @puco_id						= 1,
				 @por_id						= 88

*/
-- ------------------------------------------------------


				insert into dbo.tbItemTransactionsTmp	WITH (rowlock	)

					(	comp_id,
						tis_guid,
						tis_priority,
						item_id,
						tis_itemDesc,
						tis_detail,
						curr_id,
						tis_initQty,
						tis_qty,
						prli_id,
						tis_price,
						tis_cost,
						tax_id,
						stor_id,
						doc_id,
						tis_CD,
						bra_id,
						soh_id,
						tis_insertDate,
						tis_itemDiscount,
						tis_IsEditingCd,
						user_id,
						poh_id,
						pod_id,
						puco_id,
						tis_guarantee,
						tis_poh_bra_id,
						tis_Discount1,
						tis_Discount2,
						tis_Discount3,
						tis_Discount4,
						tis_surcharge1,
						tis_surcharge2,
						tis_surcharge3,
						tis_surcharge4
					)

				SELECT  @comp_id,
						@guid,
						0,
						tpod.item_id,
						ti.item_desc,
						'',
						tpod.curr_id,
						tprd.pord_qty,
						tprd.pord_qty,
						NULL,
						tpod.pod_price,
						0,
						tpod.tax_id,
						ISNULL(tpod.stor_id,@stor_id)					[stor_id],	-- MOS 09-2022 x MF
						--@stor_id,
						0,
						GETDATE(),
						tpod.bra_id,
						NULL,
						GETDATE(),
						0,
						GETDATE(),
						@user_id,
						tpod.poh_id,
						tpod.pod_id,
						@puco_id,
						0,
						tpoh.bra_id,
						tpod.pod_Discount1,
						tpod.pod_Discount2,
						tpod.pod_Discount3,
						tpod.pod_Discount4,
						tpod.pod_surcharge1,
						tpod.pod_surcharge2,
						tpod.pod_surcharge3,
						tpod.pod_surcharge4

				FROM 	 tbPurchaseOrderDetail								tpod		WITH (NOLOCK)

					INNER JOIN tbPurchaseOrderHeader						tpoh		WITH (NOLOCK)
					ON	tpoh.comp_id	= tpod.comp_id			AND
						tpoh.bra_id		= tpod.bra_id			AND
						tpoh.poh_id		= tpod.poh_id

					INNER JOIN tbItem										ti			WITH (NOLOCK)
					ON	ti.comp_id		= tpod.comp_id			AND
						ti.item_id		= tpod.item_id

					INNER JOIN tbPurchaseorderReceptionDetail				tprd		WITH (NOLOCK)
					ON  tprd.comp_id	= tpod.comp_id			AND
						tprd.poh_bra_id = tpod.bra_id			AND
						tprd.poh_id		= tpod.poh_id			AND
						tprd.pod_id		= tpod.pod_id

					INNER JOIN tbPurchaseorderReceptionHeader				tprh		WITH (NOLOCK)
					ON  tprh.comp_id	= tprd.comp_id			AND
						tprh.por_id		= tprd.por_id


				WHERE	tpod.comp_id	     = @comp_id		AND
					  	tprd.por_id			 = @por_id		AND
					  	tprh.por_isClosed	 = 'False'		AND
					  	tprd.pord_qty		 > 0



		IF @IsavailablewithoutPO = 'True'
				BEGIN
					-- SI NO TIENE ORDEN DE COMPRA
					-- Y SI EL CONTROL POR PERFIL ESTÁ HABILITADO.
							insert into dbo.tbItemTransactionsTmp		WITH (rowlock	)

								(	comp_id,
									tis_guid,
									tis_priority,
									item_id,
									tis_itemDesc,
									tis_detail,
									curr_id,
									tis_initQty,
									tis_qty,
									prli_id,
									tis_price,
									tis_cost,
									tax_id,
									stor_id,
									doc_id,
									tis_CD,
									bra_id,
									soh_id,
									tis_insertDate,
									tis_itemDiscount,
									tis_IsEditingCd,
									user_id,
									poh_id,
									pod_id,
									puco_id,
									tis_guarantee,
									tis_poh_bra_id,
									tis_Discount1,
									tis_Discount2,
									tis_Discount3,
									tis_Discount4,
									tis_surcharge1,
									tis_surcharge2,
									tis_surcharge3,
									tis_surcharge4
								)

					SELECT			@comp_id,
									@guid,
									0,
									ti.item_id,
									ti.item_desc,
									'',
									isnull(ticl.curr_id,ti.curr_id),
									tprd.pord_qty,
									tprd.pord_qty,
									NULL,
									isnull(ticl.coslis_price,0),
									0,
									(select
										top 1 tit.tax_id
										from tbItemTaxes tit		WITH (NOLOCK)
										INNER JOIN tbTaxName ttn	WITH (NOLOCK)
										ON ttn.comp_id		= tit.comp_id  AND
										   ttn.tax_id		= tit.tax_id
										WHERE ttn.comp_id	= @comp_id   AND
											  tit.item_id	= ti.item_id AND
										      ttn.tax_class = 1),
									ISNULL(tpod.stor_id,@stor_id)					[stor_id],	-- MOS 09-2022 x MF
									--@stor_id,
									0,
									GETDATE(),
									tprh.bra_id,
									NULL,
									GETDATE(),
									0,
									GETDATE(),
									@user_id,
									NULL,
									NULL,
									@puco_id,
									0,
									tprd.poh_bra_id,
									TI.item_purOrd_Disc1,
									TI.item_purOrd_Disc2,
									TI.item_purOrd_Disc3,
									TI.item_purOrd_Disc4,
									TI.item_purOrd_surcharge1,
									TI.item_purOrd_surcharge2,
									TI.item_purOrd_surcharge3,
									TI.item_purOrd_surcharge4

							FROM 	tbPurchaseorderReceptionHeader						tprh		WITH (NOLOCK)

								INNER JOIN 	 tbPurchaseorderReceptionDetail				tprd		WITH (NOLOCK)
								ON  tprd.comp_id	= tprh.comp_id			AND
									tprd.por_id		= tprh.por_id

								LEFT JOIN tbPurchaseOrderDetail					 AS tpod		WITH (NOLOCK)		-- MOS 09-2022
									ON	tpod.comp_id	= tprd.comp_id		AND
										tpod.bra_id		= tprd.poh_bra_id	AND
										tpod.poh_id		= tprd.poh_id		AND
										tpod.pod_id		= tprd.pod_id


								INNER JOIN tbBranch										tb			WITH (NOLOCK)
								ON	tb.comp_id		= tprh.comp_id				AND
									tb.bra_id		= tprh.bra_id

								INNER JOIN tbItem										ti			WITH (NOLOCK)
								ON	ti.comp_id		= tprd.comp_id			AND
									ti.item_id		= tprd.item_id

								left JOIN tbItemCostList								ticl		WITH (NOLOCK)
								ON	ticl.comp_id	= ti.comp_id				AND
									ticl.coslis_id	= tb.bra_PurDoc_coslis_id   AND
									ticl.item_id	= ti.item_id

								--inner JOIN tbItemTaxes									tit			WITH (NOLOCK)
								--ON	tit.comp_id = ti.comp_id				AND
								--	tit.item_id = ti.item_id



							WHERE	tprd.comp_id	     = @comp_id			AND
					  				tprd.por_id			 = @por_id			AND
					  				tprh.por_isClosed	 = 'False'			AND
					  				tprd.pord_qty		 > 0				AND
					  				tprd.poh_id			IS NULL
				END






				--insert into dbo.tbItemTransactionsTmp
				--	(	comp_id,
				--		tis_guid,
				--		tis_priority,
				--		item_id,
				--		tis_itemDesc,
				--		tis_detail,
				--		curr_id,
