SELECT			@comp_id						= 1,
				 @guid							= '6e6f5998-9118-4c5c-bb58-723ada3ae6c6',
				 @poh_id						= 220,
				 @pod_id						= 21147,
				 @user_id						= 1,
				 @AllItems						= 'False'

				 */
-- ------------------------------------------------------



	--Set @return_value	= 0


--	IF EXISTS ( SELECT tbtc.pod_id
--				FROM tbPurchaseorderReceptionDetail tbtc
--				WHERE	tbtc.comp_id		= @comp_id AND
--						tbtc.pod_id			= @pod_id
--					)
--		BEGIN



				insert into dbo.tbItemTransactionsTmp
					(	comp_id,
						tis_guid,
						tis_priority,
						item_id,
						tis_itemDesc,
						tis_detail,
						curr_id,
						tis_initQty,
						tis_qty,
						prli_id,
						tis_price,
