						user_id,
						poh_id,
						pod_id,
						puco_id,
						tis_guarantee,
						tis_poh_bra_id
					)

				SELECT  @comp_id,
						@guid,
						0,
						tpod.item_id,
						ti.item_desc,
						'',
						tpod.curr_id,
						tpod.pod_qty,
						tpod.pod_qty,
						NULL,
