						@user_id,
						tpod.poh_id,
						tpod.pod_id,
						@puco_id,
						0,
						tpoh.bra_id

				FROM 	 tbPurchaseOrderDetail		tpod		WITH (NOLOCK)

					INNER JOIN tbPurchaseOrderHeader	tpoh
					ON	tpoh.comp_id	= tpod.comp_id			AND
						tpoh.bra_id		= tpod.bra_id			AND
						tpoh.poh_id		= tpod.poh_id

					INNER JOIN tbItem					ti
					ON	ti.comp_id		= tpod.comp_id			AND
						ti.item_id		= tpod.item_id

					WHERE (
								CASE
									WHEN @AllItems = 'False' AND tpod.comp_id	= @comp_id AND tpod.poh_id	= @poh_id AND  tpod.pod_id	= @pod_id  THEN		1
									WHEN @AllItems = 'True'	 AND tpod.comp_id	= @comp_id	AND tpod.poh_id	= @poh_id 	THEN	1
									ELSE		0
								END	= 1

							  )



--					CASE
--									WHEN @AllItems = 'False' AND tpod.comp_id	= @comp_id AND tpod.poh_id	= @poh_id AND  tpod.pod_id	= @pod_id  THEN		1
--									WHEN @AllItems = 'True'	 AND tpod.comp_id	= @comp_id	AND tpod.poh_id	= @poh_id AND NOT EXISTS (	SELECT 1
--																																			FROM tbPurchaseorderReceptionDetail tbtc
--																																			WHERE	tbtc.comp_id		= @comp_id		AND
--																																					tbtc.poh_id			= tpod.poh_id	AND
--																																					tbtc.pod_id			= tpod.pod_id
--																																			)		THEN	1
--									ELSE		0
--								END	= 1
--

			--Set @return_value = @@IDENTITY



		--END

END
GO



