CREATE  PROCEDURE [dbo].[spItemTransactionsTmp_updateData]
(
	@tis_id							int,
	@tis_priority					decimal(14,4),
	@item_id						int,
	@tis_itemDesc					varchar(100),
	@tis_detail						varchar(100),
	@curr_id						int,
	@tis_qty						decimal(19,5),
	@prli_id						int,
	@tis_price						decimal(19,6),
	@tis_cost						decimal(19,6),
	@tis_costTax					int,
	@stor_id						int,
	@bra_id							int,
	@doc_id							int,
	@user_id						int,
	@comp_id						int,
	@poh_id							int,
	@pod_id							int,
	@puco_id						INT,
	@tis_guarantee					INT,
	@tis_impData_Custom_local		VARCHAR(20),
	@tis_impData_Number_local		VARCHAR(20),
	@tis_PriceB						DECIMAL(19,6),
	@tis_pickinglocation			VARCHAR(250),		-- Parte : 429
	@tis_storagelocation			VARCHAR(250),		-- Parte : 429
	@tis_impData_Origin				VARCHAR(100),		-- Parte : 709
    @tis_impData_From				VARCHAR(100)		-- Parte : 709
)
AS
SET NOCOUNT ON
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-08-04
-- Parte		: 429
-- Description	: Actualizar los valores de estiba y picking en tbItemTransactionsTmp
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-12-04
-- Parte		: 709
-- Description	: Se agrega la actualización de los nuevos campos tis_impData_Origin y tis_impData_From
-- =================================================================================================================




DECLARE		@tis_poh_bra_id		INT

SELECT		@tis_poh_bra_id		= tpoh.bra_id
FROM		tbPurchaseOrderHeader	tpoh
WHERE		tpoh.comp_id		= @comp_id
AND			tpoh.poh_id			= @poh_id



update	dbo.tbItemTransactionsTmp

set		tis_priority				= @tis_priority,
		item_id						= @item_id,
		tis_itemDesc				= @tis_itemDesc,
		tis_detail					= @tis_detail,
		curr_id						= @curr_id,
		tis_qty						= @tis_qty,
		prli_id						= @prli_id,
		tis_price					= @tis_price,
		tis_cost					= @tis_cost,
		tax_id						= @tis_costTax,
		stor_id						= @stor_id,
		bra_id						= @bra_id,
		doc_id						= @doc_id,
		user_id						= @user_id,
		poh_id						= @poh_id,
		pod_id						= @pod_id,
		puco_id						= @puco_id,
		tis_guarantee				= @tis_guarantee,
		tis_poh_bra_id				= @tis_poh_bra_id,
		tis_impData_Custom_local	= @tis_impData_Custom_local,
		tis_impData_Number_local	= @tis_impData_Number_local,
		tis_PriceB					= @tis_PriceB,
		tis_pickinglocation			= @tis_pickinglocation,		-- Parte : 429
		tis_storagelocation			= @tis_storagelocation,		-- Parte : 429
	    tis_impData_Origin			= @tis_impData_Origin,		-- Parte : 709
	    tis_impData_From			= @tis_impData_From			-- Parte : 709

WHERE 	comp_id						= @comp_id
AND		tis_id						= @tis_id


GO






CREATE PROCEDURE spItemTransactionsTmp_updateDataForProrration
(
	@comp_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@prorrationValue	DECIMAL(19,6),
	@prorrationValueAdd	DECIMAL(19,6)
)
AS SET NOCOUNT ON



-- ---------------------------------------------------------------
-- Testing
-- ---------------------------------------------------------------
/*
	DECLARE
		@comp_id			INT,
		@guid				UNIQUEIDENTIFIER,
		@prorrationValue	DECIMAL(19,6),
		@prorrationValueAdd	DECIMAL(19,6)

	SELECT
		@comp_id			= 1,
		@guid				= '98a73c59-664c-43ea-9265-4a0ec3c95bc8',
		@prorrationValue	= 50,
		@prorrationValueAdd	= 30
*/
-- ---------------------------------------------------------------



--/////////////////////////////////////////////////////////////////////////////////
--Variables que contendrán la SUMA total de los PRECIOS de la tabla

	DECLARE
		@totalPrice		DECIMAL(19,6),
		@totalPriceB	DECIMAL(19,6)

	SET @totalPrice = 0
	SET @totalPriceB = 0



SELECT
	@totalPrice  = SUM(ISNULL(titt.tis_price,0)  * ISNULL(titt.tis_qty,0)),
	@totalPriceB = SUM(ISNULL(titt.tis_PriceB,0) * ISNULL(titt.tis_qty,0))

FROM tbItemTransactionsTmp titt
WHERE titt.comp_id = @comp_id
AND titt.tis_guid = @guid


--SELECT @totalPrice,@totalPriceB

--/////////////////////////////////////////////////////////////////////////////////



--/////////////////////////////////////////////////////////////////////////////////
--Suma de los Totales y los Valores de Prorrateo dados por el usuario
	DECLARE
		@sumTotalProrrate	DECIMAL(19,6),
		@sumTotalBProrrate	DECIMAL(19,6)

	SET @sumTotalProrrate	= @totalPrice	+ @prorrationValue
	SET @sumTotalBProrrate	= @totalPriceB	+ @prorrationValueAdd

--SELECT @sumTotalProrrate,@sumTotalBProrrate

--/////////////////////////////////////////////////////////////////////////////////



--/////////////////////////////////////////////////////////////////////////////////
--Calculo de coeficientes para la actualización de la tabla tbItemtransactionsTmp

	DECLARE
		@coefProrrate		DECIMAL(19,6),
		@coefProrrateAdd	DECIMAL(19,6)

	SET @coefProrrate		= @sumTotalProrrate  / dbo.fnNoZDiv(isnull(@totalPrice,0))
	SET @coefProrrateAdd	= @sumTotalBProrrate / dbo.fnNoZDiv(isnull(@totalPriceB,0))

--SELECT @coefProrrate,@coefProrrateAdd

--/////////////////////////////////////////////////////////////////////////////////

UPDATE tbItemTransactionsTmp
SET
	tis_price	= (tis_price	* @coefProrrate),
	tis_PriceB	= (tis_priceB	* @coefProrrateAdd)

WHERE	comp_id		= @comp_id
AND		tis_guid	= @guid
GO





