)
AS

BEGIN



	SET NOCOUNT ON

	-- ------------------------------------------------------------
	-- TESTING
	-- ------------------------------------------------------------
	/*
		DECLARE
				@comp_id						INT,
				@tis_id							INT,
				@tis_guid						UNIQUEIDENTIFIER,
				@tis_impData_ExpirationDate		DATETIME

		SELECT
				@comp_id					= 1,
				@tis_id						= 12,
				@tis_guid					= '5CD6FD5B-165E-4496-9CAE-9B9217F7B5C7',
				@tis_impData_ExpirationDate	= 1
	*/
	-- ------------------------------------------------------------



	-- -------------------------------------
	-- Actualizamos la Temporal con la
	-- fecha de vencimiento
	-- -------------------------------------
	UPDATE tbItemTransactionsTmp
	SET tis_impData_ExpirationDate	= @tis_impData_ExpirationDate

	WHERE	comp_id		= @comp_id
	AND		tis_id		= @tis_id
	AND		tis_guid	= @tis_guid
	-- -------------------------------------


END
GO





CREATE PROCEDURE [dbo].[spItemTransactionsTmp_updateDiscounts]
(
	@comp_id	INT,
	@tis_id		INT,
	@tis_guid	UNIQUEIDENTIFIER,
	@discount1	DECIMAL(19,6),
	@discount2	DECIMAL(19,6),
	@discount3	DECIMAL(19,6),
	@discount4	DECIMAL(19,6),
	@chkRMA     BIT,
	@surcharge1	DECIMAL(19,6),
	@surcharge2	DECIMAL(19,6),
	@surcharge3	DECIMAL(19,6),
	@surcharge4	DECIMAL(19,6),
	@tis_impdata_LotNumber NVARCHAR(50)

)
AS

BEGIN



	SET NOCOUNT ON

	-- ------------------------------------------------------------
	-- TESTING
	-- ------------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@tis_id		INT,
			@tis_guid	UNIQUEIDENTIFIER,
			@discount1	DECIMAL(19,6),
			@discount2	DECIMAL(19,6),
			@discount3	DECIMAL(19,6),
			@discount4	DECIMAL(19,6)

		SELECT
			@comp_id	= 1,
			@tis_id		= 12,
			@tis_guid	= '5CD6FD5B-165E-4496-9CAE-9B9217F7B5C7',
			@discount1	= 1,
			@discount2	= 2,
			@discount3	= 3,
			@discount4	= 4
	*/
	-- ------------------------------------------------------------


	DECLARE	@loriginalPrice	DECIMAL(19,6)

	SET @loriginalPrice = 0


	SELECT
		@loriginalPrice = titt.tis_price

	FROM tbItemTransactionsTmp			titt

	WHERE	titt.comp_id	= @comp_id
	AND		titt.tis_id		= @tis_id
	AND		titt.tis_guid	= @tis_guid


	DECLARE
		@lPricewithDiscounts	DECIMAL(19,6)

	SET @lPricewithDiscounts = @loriginalPrice

	-- ------------------------------------------------------------------------------------------------------------------
	-- APLICACION DE DESCUENTOS AL PRECIO
	-- ------------------------------------------------------------------------------------------------------------------
		SET @lPricewithDiscounts = @lPricewithDiscounts * DBO.fnGetFinalDiscountCoeficient(@discount1,@discount2,@discount3,@discount4)
	-- ------------------------------------------------------------------------------------------------------------------


	-- -------------------------------------
	-- Actualizamos la Temporal con el
	-- resultado obtenido de los descuentos
	-- -------------------------------------
	UPDATE tbItemTransactionsTmp
	SET
		--tis_price		= @lPricewithDiscounts,   no, MOS
		tis_Discount1				= @discount1,
		tis_Discount2				= @discount2,
		tis_Discount3				= @discount3,
		tis_Discount4				= @discount4,
		it_isRMASupplierCreditNote	= @chkRMA,
		tis_surcharge1				= @surcharge1,
		tis_surcharge2				= @surcharge2,
		tis_surcharge3				= @surcharge3,
		tis_surcharge4				= @surcharge4,
		tis_impdata_LotNumber		= @tis_impdata_LotNumber

	WHERE	comp_id		= @comp_id
	AND		tis_id		= @tis_id
	AND		tis_guid	= @tis_guid
	-- -------------------------------------


END
GO





