CREATE procedure [dbo].[spListItem_Update]
(
		@comp_id			int,
		@typelist			int,
		@prli_id			int,
		@prli_price			decimal(19,5),
		@item_id			int,
		@update_ppp			BIT,
		@user_id			INT

)
as

BEGIN




	SET NOCOUNT ON


	-- ------------------------------------------
	-- Testing
	-- ------------------------------------------
	/*
	DECLARE @comp_id			int,
			@typelist			int,
			@prli_id			int,
			@prli_price			int,
			@item_id			int,
			@update_ppp			bit


	SELECT	@comp_id			=1,
			@typelist			=1,
			@prli_id			=1,
			@prli_price			=15,
			@item_id			=113,
			@update_ppp			='true'

	*/
	-- ------------------------------------------

	IF @user_id = -1 SET @user_id = NULL


	IF @typelist = 2	-- Costos
		begin

			if @update_ppp = 'true'
				begin
					update	dbo.tbItemCostList
						set		coslis_price		= @prli_price,
								coslis_price_aw		= @prli_price,
								user_id_lastUpdate	= @user_id,
								coslis_lastUpdate	= GETDATE()		-- MOS 03-2022 x BC

						from	dbo.tbItemCostList	ICL
						where	ICL.[comp_id]		= @comp_id
						and     ICL.[item_id]		= @item_id
						and     ICL.[coslis_id]		= @prli_id
				end
			else
				begin
					update	dbo.tbItemCostList
						set		coslis_price		= @prli_price,
								user_id_lastUpdate	= @user_id,
								coslis_lastUpdate	= GETDATE()		-- MOS 03-2022 x BC
						from	dbo.tbItemCostList	ICL
						where	ICL.[comp_id]		= @comp_id
						and     ICL.[item_id]		= @item_id
						and     ICL.[coslis_id]		= @prli_id
				end

				-- MOS 03-2022, QUE MIERDA ES ESTO  ????????????????????????????
				--SELECT comp_id, coslis_id, item_id, coslis_price
				--	FROM dbo.tbItemCostList

		end

	else

		begin
			IF @typelist = 1	-- Ventas
				begin

					update	dbo.tbPriceListItems
						set		prli_price				= @prli_price,
								user_id_lastUpdate		= @user_id,
								prli_updatedAt			= GETDATE(),  -- MOS 03-2022 x BC
								prli_lastModuleUpdate	= 120

						from	dbo.tbPriceListItems	pli
						where	pli.[comp_id]		= @comp_id
						and     pli.[item_id]		= @item_id
						and     pli.[prli_id]		= @prli_id

					-- MOS 03-2022, QUE MIERDA ES ESTO  ????????????????????????????
					--SELECT comp_id, prli_id, item_id, prli_price
					--	FROM dbo.tbPriceListItems

				end
			ELSE		-- Costo PPP
				begin
					--actualizar el ppp (aw)
					update	dbo.tbItemCostList
						set		coslis_price_aw		= @prli_price,
								user_id_lastUpdate	= @user_id,
								coslis_lastUpdate	= GETDATE()		-- MOS 03-2022 x BC
						from	dbo.tbItemCostList	ICL
						where	ICL.[comp_id]		= @comp_id
						and     ICL.[item_id]		= @item_id
						and     ICL.[coslis_id]		= @prli_id
				end
		end




	-- ----------------------------------
	-- MOS 06-2022: para q act los combos, talles, etc.
	-- ----------------------------------
	UPDATE tbitem
		SET item_lastUpdate_byProcess = GETDATE()
		WHERE	comp_id = @comp_id AND
				item_id = @item_id
	-- ----------------------------------


END
GO








