CREATE PROCEDURE [dbo].[spMail_Recipientes_CheckOrUncheckCustomersCatAndSubcatPurchaseByPeriod]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@cat_id		INT,
	@subcat_id	INT,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@Mark		BIT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- ------------------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@guid		UNIQUEIDENTIFIER,
				@cat_id		INT,
				@subcat_id	INT,
				@datefrom	DATETIME,
				@dateto		DATETIME,
				@Mark		BIT
			SELECT
				@comp_id	= 1,
				@guid		= 'a40b29bf-1429-4ae9-a76c-3d94dbb31112',
				@cat_id		= 3,
				@subcat_id	= 2,
				@datefrom	= '2016-08-01',
				@dateto		= '2016-08-31',
				@Mark		= 'True'
		*/
		-- ------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom, 'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto, 'True')

		-- ------------------------------------------------------------------------
		-- CREO LA TABLA EN DONDE SE GUARDAN LOS CLIENTES QUE HAYAN REALIZADO
		-- UNA COMPRA (FACTURA / REMITO) DE UN ARTÍCULO DE DETERMINADA CATEGORÍA
		-- Y/O SUBCATEGORÍA DENTRO DEL RANGO DE FECHAS ESTIPULADO
		-- ------------------------------------------------------------------------
			DECLARE @Customers TABLE
			(
				Comp_Id	INT,
				Cust_Id	INT
			)

			INSERT INTO @Customers
			(
				Comp_Id,
				Cust_Id
			)
			SELECT DISTINCT
				tct.comp_id,
				tct.cust_id
			FROM tbCommercialTransactions						tct
				INNER JOIN tbItemTransactions					tit
					ON	tit.comp_id			= tct.comp_id		AND
						tit.ct_transaction	= tct.ct_transaction
				INNER JOIN tbItem								ti
					ON	ti.comp_id			= tct.comp_id		AND
						ti.item_id			= tit.item_id
			WHERE	tct.comp_id = @comp_id						AND
					tct.ct_date BETWEEN @datefrom AND @dateto	AND
					(tct.sd_id		= 1		OR tct.sd_id = 2)	AND
					ti.cat_id		= @cat_id					AND
					ti.subcat_id	= @subcat_id


		-- ------------------------------------------------------------------------

		-- ------------------------------------------------------------------------
		-- ACTUALIZO LA TABLA DE DESTINATARIOS DEL MAILING, MARCANDO O DESMARCANDO
		-- SOLAMENTE LOS QUE CUMPLAN CON LOS REQUISITOS
		-- ------------------------------------------------------------------------
			UPDATE tbMail_Recipients
			SET
				mr_checked			= @Mark
			FROM tbMail_Recipients						tmr
				INNER JOIN @Customers					tmp
					ON	tmp.Comp_Id	= tmr.comp_id		AND
						tmp.Cust_Id	= tmr.mr_recipientId
			WHERE	tmr.comp_id		= @comp_id			AND
					tmr.guid		= @guid
		-- ------------------------------------------------------------------------

	END
GO


create PROCEDURE [dbo].[spMail_Recipientes_CheckOrUncheckCustomersKind]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@ck_id		INT,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@Mark		BIT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- ------------------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@guid		UNIQUEIDENTIFIER,
				@item_id	INT,
				@datefrom	DATETIME,
				@dateto		DATETIME,
				@Mark		BIT
			SELECT
				@comp_id	= 1,
				@guid		= '7B61E640-A7AA-4C17-8DF2-147E730E181A',
				@item_id	= 492,
				@datefrom	= '2016-08-01',
				@dateto		= '2016-08-30',
				@Mark		= 'True'
		*/
		-- ------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom, 'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto, 'True')

		-- ------------------------------------------------------------------------
		-- CREO LA TABLA EN DONDE SE GUARDAN LOS CLIENTES QUE HAYAN REALIZADO
		-- UNA COMPRA (FACTURA / REMITO) DE UNA CLASE DE CLIENTE DETERMINADA
		-- DENTRO DEL RANGO DE FECHAS ESTIPULADO
		-- ------------------------------------------------------------------------
			DECLARE @Customers TABLE
			(
				Comp_Id	INT,
				Cust_Id	INT
			)

			INSERT INTO @Customers
			(
				Comp_Id,
				Cust_Id
			)
			SELECT DISTINCT
				tct.comp_id,
				tct.cust_id
			FROM tbCommercialTransactions						tct

			INNER JOIN tbCustomer AS tc
			ON tct.comp_id = tc.comp_id AND
			   tct.cust_id = tc.cust_id


			WHERE	tct.comp_id = @comp_id						AND
					tct.ct_date BETWEEN @datefrom AND @dateto	AND
					tct.cust_id IS NOT NULL						AND
					(tct.sd_id	= 1		OR tct.sd_id = 2)		AND
					tc.ck_id = @ck_id

		-- ------------------------------------------------------------------------

		-- ------------------------------------------------------------------------
		-- ACTUALIZO LA TABLA DE DESTINATARIOS DEL MAILING, MARCANDO O DESMARCANDO
		-- SOLAMENTE LOS QUE CUMPLAN CON LOS REQUISITOS
		-- ------------------------------------------------------------------------
			UPDATE tbMail_Recipients
			SET
				mr_checked			= @Mark
			FROM tbMail_Recipients						tmr
				INNER JOIN @Customers					tmp
					ON	tmp.Comp_Id	= tmr.comp_id		AND
						tmp.Cust_Id	= tmr.mr_recipientId
			WHERE	tmr.comp_id		= @comp_id			AND
					tmr.guid		= @guid
		-- ------------------------------------------------------------------------
	END
GO


CREATE PROCEDURE spMail_Recipientes_CheckOrUncheckCustomersPurchaseByPeriod
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@Mark		BIT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'


		-- ------------------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@guid		UNIQUEIDENTIFIER,
				@datefrom	DATETIME,
				@dateto		DATETIME,
				@Mark		BIT
			SELECT
				@comp_id	= 1,
				@guid		= 'a40b29bf-1429-4ae9-a76c-3d94dbb31112',
				@datefrom	= '2016-01-01',
				@dateto		= '2016-01-31',
				@Mark		= 'True'
		*/
		-- ------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom, 'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto, 'True')

		-- ------------------------------------------------------------------------
		-- CREO LA TABLA EN DONDE SE GUARDAN LOS CLIENTES QUE HAYAN REALIZADO
		-- UNA COMPRA (FACTURA / REMITO) DENTRO DEL RANGO DE FECHAS ESTIPULADO
		-- ------------------------------------------------------------------------
			DECLARE @Customers TABLE
			(
				Comp_Id	INT,
				Cust_Id	INT
			)

			INSERT INTO @Customers
			(
				Comp_Id,
				Cust_Id
			)
			SELECT DISTINCT
				tct.comp_id,
				tct.cust_id
			FROM tbCommercialTransactions						tct
			WHERE	tct.comp_id = @comp_id						AND
					tct.ct_date BETWEEN @datefrom AND @dateto	AND
					tct.cust_id IS NOT NULL						AND
					(tct.sd_id = 1 OR tct.sd_id = 2)


		-- ------------------------------------------------------------------------

		-- ------------------------------------------------------------------------
		-- ACTUALIZO LA TABLA DE DESTINATARIOS DEL MAILING, MARCANDO O DESMARCANDO
		-- SOLAMENTE LOS QUE CUMPLAN CON LOS REQUISITOS
		-- ------------------------------------------------------------------------
			UPDATE tbMail_Recipients
			SET
				mr_checked			= @Mark
			FROM tbMail_Recipients						tmr
				INNER JOIN @Customers					tmp
					ON	tmp.Comp_Id	= tmr.comp_id		AND
						tmp.Cust_Id	= tmr.mr_recipientId
			WHERE	tmr.comp_id		= @comp_id			AND
					tmr.guid		= @guid
		-- ------------------------------------------------------------------------

	END


GO


CREATE PROCEDURE [dbo].[spMail_Recipientes_CheckOrUncheckCustomersPurchasedItemByPeriod]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@item_id	INT,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@Mark		BIT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- ------------------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@guid		UNIQUEIDENTIFIER,
				@item_id	INT,
				@datefrom	DATETIME,
				@dateto		DATETIME,
				@Mark		BIT
			SELECT
				@comp_id	= 1,
				@guid		= '7B61E640-A7AA-4C17-8DF2-147E730E181A',
				@item_id	= 492,
				@datefrom	= '2016-08-01',
				@dateto		= '2016-08-30',
				@Mark		= 'True'
		*/
		-- ------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom, 'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto, 'True')

		-- ------------------------------------------------------------------------
		-- CREO LA TABLA EN DONDE SE GUARDAN LOS CLIENTES QUE HAYAN REALIZADO
		-- UNA COMPRA (FACTURA / REMITO) DE UN ARTÍCULO DETERMINADO
		-- DENTRO DEL RANGO DE FECHAS ESTIPULADO
		-- ------------------------------------------------------------------------
			DECLARE @Customers TABLE
			(
				Comp_Id	INT,
				Cust_Id	INT
			)

			INSERT INTO @Customers
			(
				Comp_Id,
				Cust_Id
			)
			SELECT DISTINCT
				tct.comp_id,
				tct.cust_id
			FROM tbCommercialTransactions						tct
				INNER JOIN tbItemTransactions					tit
					ON	tit.comp_id			= tct.comp_id		AND
						tit.ct_transaction	= tct.ct_transaction
			WHERE	tct.comp_id = @comp_id						AND
					tct.ct_date BETWEEN @datefrom AND @dateto	AND
					tct.cust_id IS NOT NULL						AND
					(tct.sd_id	= 1		OR tct.sd_id = 2)		AND
					tit.item_id	= @item_id						AND
					tit.item_id IS NOT NULL

		-- ------------------------------------------------------------------------

		-- ------------------------------------------------------------------------
		-- ACTUALIZO LA TABLA DE DESTINATARIOS DEL MAILING, MARCANDO O DESMARCANDO
		-- SOLAMENTE LOS QUE CUMPLAN CON LOS REQUISITOS
		-- ------------------------------------------------------------------------
			UPDATE tbMail_Recipients
			SET
				mr_checked			= @Mark
			FROM tbMail_Recipients						tmr
				INNER JOIN @Customers					tmp
					ON	tmp.Comp_Id	= tmr.comp_id		AND
						tmp.Cust_Id	= tmr.mr_recipientId
			WHERE	tmr.comp_id		= @comp_id			AND
					tmr.guid		= @guid
		-- ------------------------------------------------------------------------
	END
GO


