CREATE PROCEDURE [dbo].[spMail_Recipientes_CheckOrUncheckCustomersVisitingSpecificItemFromWebsite]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@item_id	INT,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@ws_id		UNIQUEIDENTIFIER,
	@Mark		BIT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- ------------------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@guid		UNIQUEIDENTIFIER,
				@item_id	INT,
				@datefrom	DATETIME,
				@dateto		DATETIME,
				@Mark		BIT
			SELECT
				@comp_id	= 1,
				@guid		= '7B61E640-A7AA-4C17-8DF2-147E730E181A',
				@item_id	= 492,
				@datefrom	= '2016-08-01',
				@dateto		= '2016-08-30',
				@Mark		= 'True'
		*/
		-- ------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom, 'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto, 'True')

		-- ------------------------------------------------------------------------
		-- CREO UNA TABLA CON LOS CLIENTES QUE VISITARON LA PÁGINA Y VIERON UN
		-- ARTÍCULO ESPECÍFICO EN UN RANGO DE FECHAS DETERMINADO
		-- ------------------------------------------------------------------------
			DECLARE @Customers TABLE
			(
				Comp_Id	INT,
				Cust_Id	INT
			)

			INSERT INTO @Customers
			(
				Comp_Id,
				Cust_Id
			)
			SELECT DISTINCT
				tc.comp_id,
				tc.cust_id
			FROM tbCustomer								tc		WITH(NOLOCK)
				INNER JOIN tbWebSiteII_ActivityLOG		twsial	WITH(NOLOCK)
					ON	twsial.comp_id	= tc.comp_id	AND
						twsial.cust_id	= tc.cust_id
			WHERE	tc.comp_id			= @comp_id				AND
					twsial.wsm_cd BETWEEN @datefrom AND @dateto	AND
					twsial.ws_id		= @ws_id		AND
					twsial.item_id		= @item_id


		-- ------------------------------------------------------------------------

		-- ------------------------------------------------------------------------
		-- ACTUALIZO LA TABLA DE DESTINATARIOS DEL MAILING, MARCANDO O DESMARCANDO
		-- SOLAMENTE LOS QUE CUMPLAN CON LOS REQUISITOS
		-- ------------------------------------------------------------------------
			UPDATE tbMail_Recipients
			SET
				mr_checked			= @Mark
			FROM tbMail_Recipients						tmr
				INNER JOIN @Customers					tmp
					ON	tmp.Comp_Id	= tmr.comp_id		AND
						tmp.Cust_Id	= tmr.mr_recipientId
			WHERE	tmr.comp_id		= @comp_id			AND
					tmr.guid		= @guid
		-- ------------------------------------------------------------------------



	END
GO





