create PROCEDURE [dbo].[spMail_UpdateDataForContacts_Selection]
(
		@comp_id			Int,
		@selection          Bit,
		@guid				UNIQUEIDENTIFIER,
		@strWhere			VARCHAR(MAX)
	)
AS

BEGIN


	set nocount on

	/*
	DECLARE
		@comp_id			Int,
		@selection          Bit,
		@guid				Uniqueidentifier

	SELECT
		@comp_id			= 1,
		@selection          = 'True',
		@guid				= '88dc6cdb-efd5-4759-a0b8-3a4b4b086d47'
	*/


	CREATE TABLE #tmpContactFiltered (contact_id INT PRIMARY KEY)

	DECLARE @strAux AS VARCHAR(MAX)
	SET @strAux = CASE
			              WHEN	@strWhere = '' THEN '1 = 1'
			              ELSE	@strWhere
			          END
	EXEC ( '
	INSERT INTO #tmpContactFiltered
		SELECT contact_id
			FROM tbContact 	WITH (NOLOCK)
			WHERE ' + @strAux
		)




	UPDATE	tbMail_Recipients
		SET		mr_checked  = @selection
		FROM	tbMail_Recipients	tmr			WITH (NOLOCK)
		INNER JOIN #tmpContactFiltered tmp		WITH (NOLOCK)
			ON tmp.contact_id = tmr.mr_recipientId
		WHERE	comp_id		= @comp_id
		AND		guid		= @guid


END
GO





