CREATE PROCEDURE [dbo].[spMailAttachments_getData]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS SET NOCOUNT ON

/*
DECLARE
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER

SELECT
	@comp_id	=1,
	@guid		= '45b7f584-70ae-4d17-981d-392a3b8c75e9'
*/

SELECT
	' ' [ ],
	ma.ma_fullfilename,
	ma.ma_kbsize,
	ma_id [ID]

FROM	tbmail_attachments ma

WHERE	ma.comp_id	= @comp_id
AND		ma.guid		= @guid


SELECT
		isnull(SUM(ma.ma_kbsize),0)

FROM	tbmail_attachments ma

WHERE	ma.comp_id	= @comp_id
AND		ma.guid		= @guid
GO






