CREATE PROCEDURE [dbo].[spMailing_Scripts_ExecScripts]
(
	@comp_id	INT,
	@camp_id	INT,
	@cust_id	INT,
	@mails_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- MOS 08-2023: Por seguridad NO se permiten ejecutar SQLScripts con usuario sa
		IF SUSER_NAME() = 'sa' OR SUSER_NAME() = 'SA' OR SUSER_NAME() = 'Sa' OR SUSER_NAME() = 'sA'
			BEGIN
				SELECT 'WARNING: sa user NOT Allowed to execute GlobalBluePoint Scripts.'
				RETURN
			END






		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@camp_id	INT,
				@cust_id	INT,
				@mails_id	INT
			SELECT
				@comp_id	= 1,
				@camp_id	= -1,
				@cust_id	= 12,
				@mails_id	= 1
		*/
		-- --------------------------------------------


		-- --------------------------------------
		-- MAIL SCRIPTS
		-- --------------------------------------
		DECLARE @Message AS NVARCHAR(MAX)
		DECLARE @Subject AS NVARCHAR(MAX)
		-- --------------------------------------

		-- --------------------------------------
		-- CAMPAIGN
		-- --------------------------------------
		--DECLARE @Campaign_Message AS NVARCHAR(MAX)
		--DECLARE @Campaign_Subject AS NVARCHAR(MAX)
		-- --------------------------------------

		BEGIN TRY

			-- ------------------------------------------------------------------
			-- MAILING SCRIPTS
			-- ------------------------------------------------------------------
			SELECT
				@Subject				= ISNULL(tms.mails_script4Subject	,''),
				@Message				= ISNULL(tms.mails_script4Body		,'')
				FROM tbMailing_Scripts				tms	WITH(NOLOCK)
				WHERE	tms.comp_id		= @comp_id  AND
						tms.mails_id	= @mails_id
			-- ------------------------------------------------------------------

			-- ------------------------------------------------------------------
			-- CAMPAIGN
			-- ------------------------------------------------------------------
			--SELECT
			--	@Campaign_Subject	= ISNULL(tcc.camp_email4SendSubject	,''),
			--	@Campaign_Message	= ISNULL(tcc.camp_email4SendBody	,'')
			--	FROM tbCRM_Campaign tcc
			--	WHERE	tcc.comp_id = @comp_id AND
			--			tcc.camp_id = @camp_id
			-- ------------------------------------------------------------------





			-- ------------------------------------------------------------------------------------------------------------------
			-- SUBJECT - Mailing Scripts
			-- ------------------------------------------------------------------------------------------------------------------
			SET @Subject = REPLACE(@Subject,'@comp_id' ,CONVERT(NVARCHAR(8),@comp_id))
			SET @Subject = REPLACE(@Subject,'@camp_id' ,CONVERT(NVARCHAR(8),@camp_id))
			SET @Subject = REPLACE(@Subject,'@cust_id' ,CONVERT(NVARCHAR(8),@cust_id))
			SET @Subject = REPLACE(@Subject,'@mails_id',CONVERT(NVARCHAR(8),@mails_id))

			IF  @Subject	LIKE '%update%'			OR
				@Subject	LIKE '%dbcc%'			OR
				@Subject	LIKE '%truncate%'		OR
				@Subject	LIKE '%drop%'			OR
				@Subject	LIKE '%sp_configure%'	OR
				@Subject	LIKE '%sp_executesql%'	OR
				@Subject	LIKE '%delete%'
					BEGIN
						SET @Subject = ''
					END

			IF  @Subject NOT LIKE '%select%'
				BEGIN
					SET @Subject = ''
				END

			IF @Subject <> ''
				BEGIN
					DECLARE @strMessage		AS VARCHAR(8000) = ''
					DECLARE @param			AS NVARCHAR(100) = N'@strParamOUT VARCHAR(8000) OUTPUT'

					EXEC sp_executesql @Subject, @param, @strMessage OUTPUT;
					IF @strMessage <> ''
						BEGIN
							SET @Subject = @strMessage
						END
					ELSE
						BEGIN
							SET @Subject = 'SUBJECT: Script Error'
						END
				END
			-- ------------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------------
			-- BODY - Mailing Scripts
			-- ------------------------------------------------------------------------------------------------------------------
			SET @Message = REPLACE(@Message,'@comp_id' ,CONVERT(NVARCHAR(8),@comp_id))
			SET @Message = REPLACE(@Message,'@camp_id' ,CONVERT(NVARCHAR(8),@camp_id))
			SET @Message = REPLACE(@Message,'@cust_id' ,CONVERT(NVARCHAR(8),@cust_id))
			SET @Message = REPLACE(@Message,'@mails_id',CONVERT(NVARCHAR(8),@mails_id))

			IF  @Message	LIKE '%update%'			OR
				@Message	LIKE '%dbcc%'			OR
				@Message	LIKE '%truncate%'		OR
				@Message	LIKE '%drop%'			OR
				@Message	LIKE '%sp_configure%'	OR
				@Message	LIKE '%delete%'
				BEGIN
					SET @Message = ''
				END

			IF  @Message NOT LIKE '%select%'
				BEGIN
					SET @Message = ''
				END

			IF @Message <> ''
				BEGIN
					DECLARE @strMessageBody		AS VARCHAR(8000) = ''
					DECLARE @param_Body			AS NVARCHAR(100) = '@strParamOUT varchar(8000) OUTPUT'

					EXEC sp_executesql @Message, @param_Body, @strMessageBody OUTPUT;
					IF @strMessageBody <> ''
						BEGIN
							SET @Message = @strMessageBody
						END
					ELSE
						BEGIN
							SET @Message ='BODY: Script Error'
						END
				END
			-- ------------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------------
			-- SUBJECT - CAMPAIGN
			-- ------------------------------------------------------------------------------------------------------------------
			--SET @Campaign_Subject = REPLACE(@Campaign_Subject,'@camp_id',CONVERT(NVARCHAR(8),@mails_id))
			--SET @Campaign_Subject = REPLACE(@Campaign_Subject,'@cust_id' ,CONVERT(NVARCHAR(8),@cust_id))

			--IF  @Campaign_Subject	LIKE '%update%'		OR
			--	@Campaign_Subject	LIKE '%dbcc%'		OR
			--	@Campaign_Subject	LIKE '%truncate%'	OR
			--	@Campaign_Subject	LIKE '%drop%'		OR
			--	@Campaign_Subject	LIKE '%table%'		OR
			--	@Campaign_Subject	LIKE '%delete%'
			--		BEGIN
			--			SET @Campaign_Subject = ''
			--		END

			--	IF  @Campaign_Subject NOT LIKE '%select%'
			--		BEGIN
			--			SET @Campaign_Subject = ''
			--		END

			--	IF @Campaign_Subject <> ''
			--		BEGIN
			--			DECLARE @strMessageCampaignSubject		AS VARCHAR(8000) = ''
			--			DECLARE @param_CampaignSubject			AS NVARCHAR(100) = '@strParamOUT varchar(8000) OUTPUT'

			--			EXEC sp_executesql @Campaign_Subject, @param_CampaignSubject, @strMessageCampaignSubject OUTPUT;
			--			IF @strMessageBody <> ''
			--				BEGIN
			--					SET @Campaign_Subject = @strMessageCampaignSubject
			--				END
			--		END
			-- ------------------------------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------------------------------
			-- BODY - CAMPAIGN
			-- ------------------------------------------------------------------------------------------------------------------
			--SET @Campaign_Message = REPLACE(@Campaign_Message,'@camp_id',CONVERT(NVARCHAR(8),@mails_id))
			--SET @Campaign_Message = REPLACE(@Campaign_Message,'@cust_id' ,CONVERT(NVARCHAR(8),@cust_id))

			--IF  @Campaign_Message	LIKE '%update%'		OR
			--	@Campaign_Message	LIKE '%dbcc%'		OR
			--	@Campaign_Message	LIKE '%truncate%'	OR
			--	@Campaign_Message	LIKE '%drop%'		OR
			--	@Campaign_Message	LIKE '%table%'		OR
			--	@Campaign_Message	LIKE '%delete%'
			--		BEGIN
			--			SET @Campaign_Message = ''
			--		END

			--	IF  @Campaign_Message NOT LIKE '%select%'
			--		BEGIN
			--			SET @Campaign_Message = ''
			--		END

			--	IF @Campaign_Message <> ''
			--		BEGIN
			--			DECLARE @strMessageCampaignBody		AS VARCHAR(8000) = ''
			--			DECLARE @param_CampaignBody			AS NVARCHAR(100) = '@strParamOUT varchar(8000) OUTPUT'

			--			EXEC sp_executesql @Campaign_Message, @param_CampaignBody, @strMessageCampaignBody OUTPUT;
			--			IF @strMessageBody <> ''
			--				BEGIN
			--					SET @Campaign_Message = @strMessageCampaignBody
			--				END
			--		END
			-- ------------------------------------------------------------------------------------------------------------------

		END TRY

		BEGIN CATCH
			SET @Subject			= ''
			SET @Message			= ''
			--SET @Campaign_Subject	= ''
			--SET @Campaign_Message	= ''
		END CATCH

		SELECT
			ISNULL(@Subject,'')				[Mails_Subject],
			ISNULL(@Message,'')				[Mails_Message]
			--ISNULL(@Campaign_Subject,'')	[Campaign_Subject],
			--ISNULL(@Campaign_Message,'')	[Campaign_Body]

	END


GO

CREATE PROCEDURE spMailing_Scripts_GetCombo
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@prof_id	INT
			DECLARE
				@comp_id	= 1,
				@bra_id		= 1,
				@prof_id	= 1
		*/
		-- ------------------------------------

		SELECT
			tms.mails_id					[Id],
			tms.mails_desc					[Desc]
			FROM tbMailing_Scripts			tms
			WHERE tms.comp_id	= @comp_id	AND
			(
				tms.bra_id		IS NULL OR
				tms.bra_id		= @bra_id
			)								AND
			(
				tms.prof_id		IS NULL OR
				tms.prof_id		= @prof_id
			)
	END
GO






