CREATE PROCEDURE [dbo].[spMailRecipients_getDataForMail]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@quantity	INT
)
AS


BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@guid		UNIQUEIDENTIFIER,
		@quantity	INT

	SELECT
		@comp_id	= 1,
		@guid		='29fac94c-dac3-4b80-97d8-86c74ea0e9ba',
		@quantity	= 5

		--DROP TABLE #tmpMail_Recipients
	*/
	-- -----------------------------------------------------------------------------


	CREATE TABLE #tmpMail_Recipients (mail_recipients VARCHAR(8000),cust_id INT)


	DECLARE
		@recipient_mail	VARCHAR(150),	--Variable donde se almacena el mail del receptor
		@recipients		VARCHAR(8000),	--Variable que contendra el STRING completo de los mails de los receptores
		@lcounter		INT,
		@intCustID		AS INT = -1

	SET @recipients = ''
	SET @lcounter	= 0

	DECLARE cursor_mails CURSOR FOR
		SELECT	tc.cust_email, tc.cust_id
			FROM	tbMail_Recipients tmr
			INNER JOIN tbCustomer tc
				ON	tc.comp_id			= tmr.comp_id		AND
					tmr.mr_recipientId	= tc.cust_id
			WHERE	tmr.comp_id			= @comp_id			AND
					tmr.guid			= @guid				AND
					tmr.mr_checked		= 'True'

	OPEN cursor_mails
	FETCH NEXT FROM cursor_mails
		INTO @recipient_mail, @intCustID

		WHILE @@FETCH_STATUS = 0		-- El que hizo esto es un FLOR DE HIJO DE PUTA !!!
			BEGIN


				-- Si no se seleccionó un llenador de Texto a enviar... pone el cliente en -1 para que NO vaya cliente x cliente buscando que cosa poner en el Body y Subject
				-- Esto es todo una mierda pero está así y vamos a aprovecharlo...
				IF @quantity > 1
					BEGIN
						SET @intCustID = -1
					END


				IF @quantity <> 0
					BEGIN
						IF @lcounter = @quantity
							BEGIN
								BEGIN
									SET @lcounter = 0
									SET @recipients = SUBSTRING(@recipients,2,LEN(@recipients) - 1)
									INSERT INTO #tmpMail_Recipients
										(mail_recipients,cust_id)
										values
											(@recipients,@intCustID)
									SET @recipients = ''
								END
							END
					END


				IF @recipient_mail <> ''
					BEGIN
						SET @lcounter	= @lcounter		+ 1
						SET @recipients = @recipients	+ ';' + dbo.fnstrEmailCheck(@recipient_mail)
					END

				FETCH NEXT FROM cursor_mails
					INTO	@recipient_mail, @intCustID

			END

		IF LEN(@recipients) > 0
			BEGIN
				SET @recipients = SUBSTRING(@recipients,2,LEN(@recipients) - 1)
				INSERT INTO #tmpMail_Recipients
				(mail_recipients,cust_id)
				values
				(@recipients,@intCustID)
			END


		CLOSE cursor_mails
	DEALLOCATE cursor_mails

	SELECT * FROM #tmpMail_Recipients



END
GO





