create PROCEDURE [dbo].[spMailRecipients_getDataForMail4Contact]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@quantity	INT
)
AS
SET NOCOUNT ON


/*
DECLARE
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@quantity	INT

SELECT
	@comp_id	= 1,
	@guid		='29fac94c-dac3-4b80-97d8-86c74ea0e9ba',
	@quantity	= 2

	DROP TABLE #tmpMail_Recipients
*/


CREATE TABLE #tmpMail_Recipients (mail_recipients VARCHAR(8000))


DECLARE
	@recipient_mail	VARCHAR(150),	--Variable donde se almacena el mail del receptor
	@recipients		VARCHAR(8000),	--Variable que contendra el STRING completo de los mails de los receptores
	@lcounter		INT

SET @recipients = ''
SET @lcounter	= 0

DECLARE cursor_mails CURSOR FOR

	SELECT	tc.contact_email

	FROM	tbMail_Recipients tmr

			INNER JOIN tbContact	 tc
			ON	tc.comp_id			= tmr.comp_id
			AND tmr.mr_recipientId	= tc.contact_id

	WHERE	tmr.comp_id		= @comp_id
	AND		tmr.guid		= @guid
	AND		tmr.mr_checked	= 'True'

OPEN cursor_mails
FETCH NEXT FROM cursor_mails
INTO
	@recipient_mail

	WHILE @@FETCH_STATUS = 0
	BEGIN

	IF NOT @quantity = 0
		IF @lcounter = @quantity
		BEGIN
			BEGIN
				SET @lcounter = 0
				SET @recipients = SUBSTRING(@recipients,2,LEN(@recipients) - 1)
				INSERT INTO #tmpMail_Recipients
				(mail_recipients)
				values
				(@recipients)
				SET @recipients = ''
			END
		END

			IF @recipient_mail <> ''
				BEGIN
					SET @lcounter = @lcounter + 1
					SET @recipients = @recipients + ';' + @recipient_mail
				END

			FETCH NEXT FROM cursor_mails
				INTO
					@recipient_mail

	END

	IF LEN(@recipients) > 0
		BEGIN
			SET @recipients = SUBSTRING(@recipients,2,LEN(@recipients) - 1)
			INSERT INTO #tmpMail_Recipients
			(mail_recipients)
			values
			(@recipients)
		END


	CLOSE cursor_mails
DEALLOCATE cursor_mails

SELECT * FROM #tmpMail_Recipients
GO





