CREATE PROCEDURE [dbo].[spMenuGrants_CloneDataFromProfile]
(
	@comp_id			INT,
	@user_id			INT,
	@prof_id_origen		INT,
	@prof_id_destiny	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		INSERT INTO tbMenuGrants
		(
			comp_id,
			prof_id,
			menu_id
		)
		SELECT	tmg.comp_id,
				@prof_id_destiny,
				tmg.menu_id
			FROM tbMenuGrants		AS tmg	WITH (NOLOCK)
			LEFT JOIN tbMenuGrants	AS tmg2	WITH (NOLOCK)
				ON	tmg2.comp_id	= tmg.comp_id		AND
					tmg2.prof_id	= @prof_id_destiny	AND
					tmg2.menu_id	= tmg.menu_id
			WHERE	tmg.comp_id		= @comp_id			AND
					tmg.prof_id		= @prof_id_origen	AND
					tmg2.comp_id IS NULL





	END
GO







CREATE  PROCEDURE [dbo].[spMenuGrants_deleteData]
(
	@comp_id		int,
	@prof_id		int,
	@menu_id		int,
	@level			int
)
as

BEGIN



	set nocount on

	if @level = -1
	begin

		Delete	dbo.tbMenuGrants
			where	comp_id		=	@comp_id
			and		prof_id		=	@prof_id
			and		(@menu_id = -1 or menu_id =	@menu_id)

	end
	else
	begin
	--Begin Transaction spAccountTransactionHead_deleteData

	Set @level = @level + 1

	-- -----------------------
	-- Para Evitar StackFault
	If @level > 30
	Begin
		Return
	End
	-- -----------------------


	Delete	dbo.tbMenuGrants
	where	comp_id		=	@comp_id
	and		prof_id		=	@prof_id
	and		menu_id		=	@menu_id


	declare @lmenu_id	int

	Declare @varCursor Cursor
	Set @varCursor = CURSOR LOCAL FAST_FORWARD for
		Select menu_id
			From [tbSysMenu]	WITH (NOLOCK)
			where menu_id_sup = @menu_id

	Open @varCursor

	Fetch Next From @varCursor
	Into @lmenu_id

	While @@FETCH_STATUS = 0
	Begin

		Exec spMenuGrants_deleteData @comp_id, @prof_id, @lmenu_id,	@level

		Fetch Next From @varCursor
		Into @lmenu_id

	End

	Close @varCursor
	Deallocate @varCursor



	--IF @@Error = 0
	--	Commit Transaction spAccountTransactionHead_deleteData
	--Else
	--	ROLLBACK TRANSACTION spAccountTransactionHead_deleteData

	end

END
GO






CREATE  PROCEDURE [dbo].[spMenuGrants_getComboMenu]
(
	@comp_id			integer,
	@prof_id			integer,
	@lang_id			int
)
as

SET NOCOUNT ON

/*
declare @comp_id	int,
		@prof_id    int,
		@lang_id	int

select	@comp_id	= 2,
		@prof_id	= 3,
		@lang_id	= 1
*/

select	distinct
		a.menu_id	[id],
		b.mid_desc	[desc]

from	[tbMenuGrants]		a

		inner join [tbsysMenuLanguage]		b
		on	b.menu_id		= a.menu_id

where	a.comp_id			= @comp_id
and		a.prof_id			= @prof_id
and     b.lang_id		    = @lang_id

order by b.mid_desc



















GO







CREATE  PROCEDURE [dbo].[spMenuGrants_insertData]
(
	@comp_id		int,
	@prof_id		int,
	@menu_id		int,
	@level			int
)
as

BEGIN



	set nocount on

	if @level = -1
	begin

		if not exists(select TOP 1 1
						from dbo.tbMenuGrants	WITH (NOLOCK)
						where comp_id = @comp_id and prof_id = @prof_id and menu_id = @menu_id)
		begin
			insert into dbo.tbMenuGrants	(comp_id,	prof_id,	menu_id)
			values							(@comp_id,	@prof_id,	@menu_id)
		end

	end
	else
	begin

	--Begin Transaction spAccountTransactionHead_deleteData

	Set @level = @level + 1

	-- -----------------------
	-- Para Evitar StackFault
	If @level > 30
	Begin
		Return
	End
	-- -----------------------


	insert into dbo.tbMenuGrants
	(comp_id,  prof_id,  menu_id)
	values
	(@comp_id, @prof_id, @menu_id)


	declare @lmenu_id	int

	Declare @varCursor Cursor
	Set @varCursor = Cursor LOCAL FAST_FORWARD for Select menu_id From [tbSysMenu] WITH (NOLOCK) where menu_id_sup = @menu_id

	Open @varCursor

	Fetch Next From @varCursor
	Into @lmenu_id

	While @@FETCH_STATUS = 0
	Begin

		Exec spMenuGrants_insertData @comp_id, @prof_id, @lmenu_id,	@level

		Fetch Next From @varCursor
		Into @lmenu_id

	End

	Close @varCursor
	Deallocate @varCursor



	--IF @@Error = 0
	--	Commit Transaction spAccountTransactionHead_deleteData
	--Else
	--	ROLLBACK TRANSACTION spAccountTransactionHead_deleteData

	--insert into dbo.tbMenuGrants
	--(comp_id,  prof_id,  menu_id)
	--select  @comp_id, @prof_id, [menu_id] from [tbsysMenu]
	--where menu_id_sup = @menu_id
	end


END











GO



