CREATE PROCEDURE [dbo].[spMercadoLibre_Branchs_GetData4GridByFilters]
(
	@comp_id	INT,
	@mls_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------
		-- TESTING
		-- ---------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mls_id		INT
			SELECT
				@comp_id	= 1,
				@mls_id		= 5
		*/
		-- ---------------------------------

		SELECT
			''									[1],--UPDATE
			''									[2], --DELETE
			tmlb.mlbra_desc,
			tmlb.mlbra_disabled,
			tmlb.MLId,
			ts.stor_desc						[stor_id4LocalStock],
			ts2.stor_desc						[stor_id4RemoteStock],
			tmls.mls_desc,
			tmlb.mlbra_availability_time_in_hours,
			tmlb.open_hours,
			tmlb.phone_areaCode,
			tmlb.phone_number,
			tmlb.address_line,
			tmlb.mlbra_latitude,
			tmlb.mlbra_longitude,
			tmlb.mlbra_id						[ID]
			FROM tbMercadoLibre_Branchs			tmlb		WITH(NOLOCK)
			LEFT JOIN tbMercadoLibre_Stores	tmls		WITH(NOLOCK)
			ON	tmls.comp_id	= tmlb.comp_id	AND
				tmls.mls_id		= tmlb.mls_id
			LEFT JOIN tbStorage				ts			WITH(NOLOCK)
			ON	ts.comp_id		= tmlb.comp_id	AND
				ts.stor_id		= tmlb.stor_id4LocalStock
			LEFT JOIN tbStorage				ts2			WITH(NOLOCK)
			ON	ts2.comp_id		= tmlb.comp_id	AND
				ts2.stor_id		= tmlb.stor_id4RemoteStock
			WHERE	tmlb.comp_id	= @comp_id	AND
					(
						@mls_id		= -1		OR
						tmlb.mls_id	= @mls_id
					)

	END

GO

