CREATE PROCEDURE [dbo].[spMercadoLibre_callbackHistory_getProcessesPending]
AS
BEGIN

	SET NOCOUNT ON
	DECLARE @datActualDate AS DATETIME = GETDATE()

	-- ver si no habria que traer tambien las que titnen tmlch.MLLog_status con 430 que significa que NO habia access token.  vi  en ADMA que pasaba, en ninguna otra....

	SELECT	tmlch.MLLog_id,
			ISNULL(tmlch.MLLog_URL,'')			[MLLog_URL],
			ISNULL(tmlch.MLLog_JSon,'')			[MLLog_JSon]
		FROM tbMercadoLibre_callbackHistory AS tmlch	WITH (NOLOCK)
		WHERE	(
					tmlch.MLLog_endDate IS NULL
					OR
					tmlch.MLLog_status = 430
				)														AND
				tmlch.MLLog_JSon	<> ''								AND
				tmlch.MLLog_JSon	NOT LIKE '%__EVENTTARGET%' 			AND
				DATEDIFF(minute,tmlch.MLLog_cd,@datActualDate)	>  20	AND
				DATEDIFF(hour,  tmlch.MLLog_cd,@datActualDate)	<= 24
		ORDER BY tmlch.MLLog_id ASC		-- Primero los mas viejos y ultimos los mas nuevos

END


--__EVENTTARGET=&__EVENTARGUMENT=&__VIEWSTATE=%2FwEPDwULLTE1NDA5Mjk5NzdkZBDP62TSmkHLMBqPXrR4%2BBUfYy99&__VIEWSTATEGENERATOR=C2D69029&btnPostback=Button
GO

