				@MLcategoryID				NVARCHAR(30),
				--@mlpc_cd					,
				@MLprice					DECIMAL(19,4),
				@MLcurrency_id				NCHAR(10),
				@MLavailable_quantity		INT,
				@MLsold_quantity			INT,
				@MLbuying_mode				NVARCHAR(20),
				@MLlisting_type_id			NVARCHAR(20),
				@MLthumbnail				NVARCHAR(1000),
				@MLaccepts_mercadopago		BIT,
				@MLfree_shipping			BIT,
				@MLseller_country			NVARCHAR(20),
				@MLseller_state				NVARCHAR(40),
				@MLseller_city				NVARCHAR(100),
				@MLattributes_brand			NVARCHAR(300),
				@MLattributes_model			NVARCHAR(300),
				@MLofficial_store_id		INT,
				@MLcatalog_product_id		NVARCHAR(30),
				@MLreviews_Total			BIGINT,
				@MLreviews_rating_average	INT,
				@MLamount					DECIMAL(19,4),
				@MLinstallments_quantity	INT,
				@MLinstallments_price		DECIMAL(19,4),
				@MLinstallments_rate		DECIMAL(19,4),
				@MLinstallments_currency	NCHAR(10),
		*/
		-- ---------------------------------------------------------------

		INSERT INTO tbMercadoLibre_categoryCompare
		(
			comp_id,
			MLcategoryID,
			MLprice,
			MLcurrency_id,
			MLavailable_quantity,
			MLsold_quantity,
			MLbuying_mode,
			MLlisting_type_id,
			MLthumbnail,
			MLaccepts_mercadopago,
			MLfree_shipping,
			MLseller_country,
			MLseller_state,
			MLseller_city,
			MLattributes_brand,
			MLattributes_model,
			MLofficial_store_id,
			MLcatalog_product_id,
			MLreviews_Total,
			MLreviews_rating_average,
			MLamount,
			MLinstallments_quantity,
			MLinstallments_price,
			MLinstallments_rate,
			MLinstallments_currency,
			MLtitle,
			MLpermalink
		)
		VALUES
		(
			@comp_id,
			@MLcategoryID,
			@MLprice,
			@MLcurrency_id,
			@MLavailable_quantity,
			@MLsold_quantity,
			@MLbuying_mode,
			@MLlisting_type_id,
			@MLthumbnail,
			@MLaccepts_mercadopago,
			@MLfree_shipping,
			@MLseller_country,
			@MLseller_state,
			@MLseller_city,
			@MLattributes_brand,
			@MLattributes_model,
			@MLofficial_store_id,
			@MLcatalog_product_id,
			@MLreviews_Total,
			@MLreviews_rating_average,
			@MLamount,
			@MLinstallments_quantity,
			@MLinstallments_price,
			@MLinstallments_rate,
			@MLinstallments_currency,
			@MLtitle,
			@MLpermalink
		)

		SET @return_value = @@IDENTITY

	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_CheckMercadoPago]
(
	@comp_id				INT,
	@strMercadoLibre_SOID	VARCHAR(50),
	@strMercadoPago_SOID	VARCHAR(50),
	@intCC_Id				INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- --------------------------------
		-- TESTING
		-- --------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@intCC_Id				INT,
				@strMercadoLibre_SOID	VARCHAR(50),
				@strMercadoPago_SOID	VARCHAR(50)
			SELECT
				@comp_id				= 1,
				@intCC_Id				= 31,
				@strMercadoLibre_SOID	= '',
				@strMercadoPago_SOID	= 'Cobranza desde MercadoPago'
		*/
		-- --------------------------------


		IF EXISTS(
					SELECT TOP 1  1
						FROM tbCreditCardMovements tccm		WITH (NOLOCK)
						WHERE	tccm.comp_id				= @comp_id				AND
								tccm.cc_id					= @intCC_Id				AND
								(
									tccm.ccm_AutorizationCode	= @strMercadoPago_SOID
										OR
									tccm.ccm_receiptNumber		= @strMercadoPago_SOID
								)
				)
			BEGIN
				IF @strMercadoPago_SOID = 'Cobranza desde MercadoPago'
					BEGIN
						SET @strMercadoPago_SOID = CONVERT(VARCHAR(50),NEWID())
					END

				INSERT INTO tbMercadoLibre_Producteca_CollectionInserted(soh_MLId)
					VALUES (@strMercadoPago_SOID)

				SELECT '1' [ISFOUND]
			END
		ELSE
			BEGIN
				SELECT '0' [ISFOUND]
			END

	END
GO

