CREATE PROCEDURE [dbo].[spMercadoLibre_Claims_GetDataBy_Mlo_ID]
(
	@comp_id			INT,
	@mlo_id				INT	,
	@OnlyNotClosed		BIT
)
AS
	BEGIN

		SET NOCOUNT ON
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------


		IF @OnlyNotClosed = 'False'
			BEGIN
				SELECT
					tmlc.comp_id,
					tmlc.claim_id,
					tmlc.id,
					tmlc.[type],
					tmlc.stage,
					tmlc.[status],
					ISNULL(tmlc.claim_closed,'False')			[claim_closed],
					tmlc.resource_id,
					tmlc.resource,
					tmlc.reason_id,
					tmlc.claim_json,
					tmlc.mlo_id
					FROM tbMercadoLibre_Claims			tmlc	WITH(NOLOCK)
					WHERE	tmlc.comp_id	= @comp_id	AND
							tmlc.mlo_id		= @mlo_id
			END
		ELSE
			BEGIN
				SELECT
					tmlc.comp_id,
					tmlc.claim_id,
					tmlc.id,
					tmlc.[type],
					tmlc.stage,
					tmlc.[status],
					ISNULL(tmlc.claim_closed,'False')			[claim_closed],
					tmlc.resource_id,
					tmlc.resource,
					tmlc.reason_id,
					tmlc.claim_json,
					tmlc.mlo_id
					FROM tbMercadoLibre_Claims			tmlc	WITH(NOLOCK)
					WHERE	tmlc.comp_id		= @comp_id	AND
							tmlc.mlo_id			= @mlo_id	AND
							tmlc.claim_closed	= 'False'
			END



	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_Claims_GetDataByClaimID]
(
	@comp_id	INT,
	@mlClaimID	BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------
		-- TESTING
		-- ---------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlClaimID	BIGINT
		*/
		-- ---------------------------------------

		SELECT
			tmlc.comp_id,
			tmlc.claim_id,
			tmlc.id,
			tmlc.[type],
			tmlc.stage,
			tmlc.[status],
			tmlc.claim_closed,
			tmlc.resource_id,
			tmlc.resource,
			tmlc.reason_id,
			tmlc.claim_json,
			tmlc.mlo_id,
			ISNULL(tmloh.ML_id,-1)						[ML_id]
			FROM tbMercadoLibre_Claims					AS tmlc		WITH(NOLOCK)
