				ON	tmloh.comp_id	= tmlc.comp_id		AND
					tmloh.mlo_id	= tmlc.mlo_id
			WHERE	tmlc.comp_id	= @comp_id	AND
					tmlc.id			= @mlClaimID

	END
GO

CREATE PROCEDURE spMercadoLibre_Claims_GetOpenClaimByMLOID
(
	@comp_id	INT,
	@mlo_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlo_id		INT
			SELECT
				@comp_id	= 1,
				@mlo_id		= 131
		*/
		-- ------------------------------------

		SELECT TOP 1
			tmlc.*
			FROM tbMercadoLibre_Claims									tmlc	WITH(NOLOCK)
			WHERE	tmlc.comp_id						= @comp_id		AND
					tmlc.mlo_id							= @mlo_id		AND
					ISNULL(tmlc.claim_closed,'False')	= 'False'		AND
					tmlc.id								IS NOT NULL
			ORDER BY tmlc.claim_id DESC
	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_Claims_InsertOrUpdate]
(
	@comp_id		INT,
	@id				BIGINT,
	@type			NVARCHAR(50),
	@stage			NCHAR(20),
	@status			NCHAR(20),
	@claim_closed	BIT,
	@resource_id	BIGINT,
	@resource		NCHAR(20),
	@reason_id		NVARCHAR(50),
	@claim_json		NTEXT,
	@mlo_id			INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@id				BIGINT,
				@type			NVARCHAR(50),
				@stage			NCHAR(20),
				@status			NCHAR(20),
				@claim_closed	BIT,
				@resource_id	BIGINT,
				@resource		NCHAR(20),
				@reason_id		NVARCHAR(50),
				@claim_json		NTEXT,
				@mlo_id			INT
		*/
		-- ------------------------------------------------

		IF @mlo_id = -1
			BEGIN
				SET @mlo_id = NULL
			END


		DECLARE @claim_id AS INT = NULL
		SELECT
			@claim_id = tmlc.claim_id
			FROM tbMercadoLibre_Claims			tmlc	WITH(NOLOCK)
			WHERE	tmlc.comp_id	= @comp_id	AND
					tmlc.id			= @id


		IF @claim_id IS NULL
			BEGIN
				INSERT INTO tbMercadoLibre_Claims	WITH (ROWLOCK)
				(
					comp_id,
					id,
					[type],
					stage,
					[status],
					claim_closed,
					resource_id,
					resource,
					reason_id,
					claim_json,
					mlo_id
				)
				VALUES
				(
					@comp_id,
					@id,
					@type,
					@stage,
					@status,
					@claim_closed,
					@resource_id,
					@resource,
					@reason_id,
					@claim_json,
					@mlo_id
				)


				SELECT @claim_id = @@IDENTITY
				SELECT @claim_id	[claim_id]
			END
		ELSE
			BEGIN
				UPDATE tbMercadoLibre_Claims			WITH (ROWLOCK)
				SET
					[type]			= @type,
					stage			= @stage,
					[status]		= @status,
					claim_closed	= @claim_closed,
					resource_id		= @resource_id,
					resource		= @resource,
					reason_id		= @reason_id,
					claim_json		.WRITE( @claim_json,0,NULL) ,
					mlo_id			= @mlo_id
					WHERE	comp_id	= @comp_id AND
							id		= @id


				SELECT @claim_id	[claim_id]

			END



		DECLARE @strURL		AS NVARCHAR(1000) = 'https://mediations.mercadolibre.com.ar/received_claims/' + CONVERT(NVARCHAR(50),@id)
		DECLARE @nickname	AS NVARCHAR(100) = ''
		DECLARE @user_id	AS INT = -1
		DECLARE @bra_id		AS INT	= -1
		DECLARE @mlOrderID AS BIGINT = 0
		SELECT TOP 1  @bra_id	= tmls.bra_id,
					  @user_id  = tmls.[user_id],
					  @nickname = tmlud.nickname,
					  @mlOrderID= tmloh2.MLorder_id
			FROM tbMercadoLibre_ordersDetail tmloh					WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ordersHeader tmloh2			WITH (NOLOCK)
				ON	tmloh2.comp_id		= tmloh.comp_id AND
					tmloh2.mlo_id		= tmloh.mlo_id
			INNER JOIN tbMercadoLibre_UsersData tmlud				WITH (NOLOCK)
				ON tmlud.MLUser_Id      = tmloh2.MLUser_Id
			INNER JOIN tbMercadoLibre_ItemsPublicados tmlip			WITH (NOLOCK)
				ON	tmlip.comp_id		= tmloh.comp_id AND
					tmlip.mlp_id		= tmloh.mlp_id
			INNER JOIN tbMercadoLibre_Stores tmls					WITH (NOLOCK)
				ON	tmls.comp_id		= tmlip.comp_id AND
					tmls.mls_id			= tmlip.mls_id
			WHERE	tmloh.comp_id		= @comp_id		AND
					tmloh.mlo_id		= @mlo_id


		-- Si no esta en WorkFlow este reclamo abierto, lo inserta ahora.
		IF NOT EXISTS (
							SELECT TOP 1  1
								FROM tbWorkflow tw	WITH (NOLOCK)
								WHERE	tw.comp_id			= @comp_id	AND
										tw.claim_id			= @claim_id AND
										tw.wf_isProcessed	= 0
					  )   AND
			@bra_id <> -1
			BEGIN
				IF @claim_closed = 'False'
					BEGIN
						INSERT INTO tbWorkflow	WITH (ROWLOCK)
						(
							comp_id,
							bra_id,
							wf_type,
							wf_isProcessed,
							user_id_from,
							user_id_assigned,
							user_id_processed,
							prof_id_assigned,
							wf_dateOfAssigned,
							wf_dateOfProcessing,
							wf_link,
							wf_message1,
							wf_message2,
							wf_message3,
							wf_message4,
							wf_htmlTop,
							wf_htmlBody,
							wf_html_Bottom,
							claim_id
						)
						SELECT	TOP 1
								@comp_id,
								NULL,
								850,
								'False',
								NULL,
								@user_id, --@intUser4Notify,
								NULL,
								tp.prof_id,
								GETDATE(),
								NULL,
								@strURL,
								'MercadoLibre: Reclamo/Claim#:' + CONVERT(NVARCHAR(50),@id),
								'NickName:' + @nickname ,
								'Order#' + CONVERT(NVARCHAR(50),@mlOrderID),
								'Type:' + @type + ' / Stage:' + @stage + ' / Status:' + @status,
								'', --@strRet_ErrorDescription,
								'',
								'',
								@claim_id
							FROM tbProfile tp	WITH (NOLOCK)
							WHERE	tp.comp_id					= @comp_id AND
									tp.prof_workFlow4MLClaims	= 1

					END

				END
			ELSE
				BEGIN
						IF @claim_closed = 'False'
							BEGIN
								UPDATE tbworkflow		WITH (ROWLOCK)
									SET
										wf_dateOfAssigned = GETDATE(),
										wf_message3			= 'Order#' + CONVERT(NVARCHAR(50),@mlOrderID),
										wf_message4			= 'Type:' + @type + ' / Stage:' + @stage + ' / Status:' + @status
									WHERE	comp_id		= @comp_id AND
											claim_id	= @claim_id

							END
						ELSE
							BEGIN
								DELETE FROM tbWorkflow		WITH (ROWLOCK)
									WHERE	comp_id			= @comp_id  AND
											claim_id		= @claim_id AND
											wf_isProcessed	= 0
							END
					END


	END
GO

