CREATE PROCEDURE [dbo].[spMercadoLibre_ClaimsMessages_GetDataByClaimID]
(
	@comp_id	INT,
	@claim_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		SELECT
			tmlcm.comp_id,
			tmlcm.claimm_id,
			tmlcm.claim_id,
			tmlcm.sender_role,
			tmlcm.receiver_role,
			tmlcm.[message]				[message],
			tmlcm.stage,
			tmlcm.date_created,
			ISNULL(tmlc.id,0)			[id],
			isnull(tmlc.[type],'')		[type],
			isnull(tmlc.stage,'')		[claims_stage],
			isnull(tmlc.[status],'')	[status]

		FROM tbMercadoLibre_ClaimsMessages	tmlcm			WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_Claims	tmlc			WITH (NOLOCK)
			ON		tmlc.comp_id	= tmlcm.comp_id AND
					tmlc.claim_id	= tmlcm.claim_id
		WHERE		tmlcm.comp_id	= @comp_id AND
					tmlcm.claim_id	= @claim_id
		ORDER BY	tmlcm.date_created asc

	END
GO

