CREATE PROCEDURE [dbo].[spMercadoLibre_CommercialCampaign_SendMessages]
(
	@comp_id				INT,
	@lang_id				INT,
	@user_id				INT,
	@CustGuid				UNIQUEIDENTIFIER,
	@SuppGuid				UNIQUEIDENTIFIER,
	@ItemGuid				UNIQUEIDENTIFIER,
	@PublicationCategory	INT,
	@mls_id					INT,
	@datefrom				DATETIME,
	@dateto					DATETIME,
	@message				NVARCHAR(MAX),
	@guid2Execute			UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@lang_id				INT,
				@user_id				INT,
				@CustGuid				UNIQUEIDENTIFIER,
				@SuppGuid				UNIQUEIDENTIFIER,
				@ItemGuid				UNIQUEIDENTIFIER,
				@PublicationCategory	INT,
				@mls_id					INT,
				@datefrom				DATETIME,
				@dateto					DATETIME,
				@message				NVARCHAR(MAX),
				@guid2Execute			UNIQUEIDENTIFIER
			SELECT
				@comp_id				= 1,
				@lang_id				= 2,
				@user_id				= 134,
				@CustGuid				= 'ea7010db-eba2-4fd3-aec0-4eb2fe279b97',
				@SuppGuid				= '465b88fe-c5dd-43be-ab08-f49f000a438f',
				@ItemGuid				= '396e78ba-5f97-4c7f-9036-ccabc42b49d4',
				@PublicationCategory	= -1,
				@mls_id					= -1,
				@datefrom				= '2018-10-01',
				@dateto					= '2018-11-30',
				@message				= 'Holiiii'	,
				@guid2Execute			= '396e78ba-5f97-4c7f-9036-ccabc42b49d5'
		*/
		-- -----------------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom, 'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto, 'True')
		-- ---------------------------------------------------------------------------
		-- RECUPERO LOS CLIENTES QUE VIENEN EN EL GUID
		-- ---------------------------------------------------------------------------
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
		SELECT
			tcf.sl_id
			FROM tbComplexFilter				tcf
			WHERE	tcf.sl_guid		= @CustGuid AND
					tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
				SELECT
					tc.cust_id
					FROM tbCustomer					tc
					WHERE	tc.comp_id		= @comp_id	AND
							tc.MLUser_Id	IS NOT NULL
			END
		ELSE
			BEGIN
				-- BORRO TODOS LOS QUE NO TENGAN CUENTA EN MELI
				DELETE FROM @tblComplexFilter_Customer
				FROM @tblComplexFilter_Customer tmp
					INNER JOIN tbCustomer		tc
					ON tc.cust_id		= tmp.cust_id
					WHERE tc.MLUser_Id	IS NULL
			END
		-- ---------------------------------------------------------------------------

		-- ---------------------------------------------------------------------------
		-- RECUPERO TODOS LOS ARTICULOS PARA EL GUID
		-- ---------------------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
		SELECT
			tcf.sl_id
			FROM tbComplexFilter				tcf
			WHERE	tcf.sl_guid		= @ItemGuid AND
					tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
			SELECT
				ti.item_id
				FROM tbItem ti
				WHERE ti.comp_id	= @comp_id
		END
		-- ---------------------------------------------------------------------------

		-- ---------------------------------------------------------------------------
		-- RECUPERO TODOS LOS PROVEEDORES PARA EL GUID
		-- ---------------------------------------------------------------------------
		DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Supplier
		SELECT
			tcf.sl_id
			FROM tbComplexFilter				tcf
			WHERE	tcf.sl_guid		= @SuppGuid AND
					tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Supplier
			SELECT
				ts.supp_id
				FROM tbSupplier ts
				WHERE ts.comp_id	= @comp_id
		END
		-- ---------------------------------------------------------------------------


		-- ---------------------------------------------------------------------------
		-- FILTRO LOS ARTÍCULOS QUE TENGAN LOS PROVEEDORES DEL FILTRO
		-- ---------------------------------------------------------------------------
		DECLARE @tblComplexFilter_FinalItemsBySupplier TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_FinalItemsBySupplier
		SELECT
			ti.item_id
			FROM tbItem								ti		WITH(NOLOCK)
			INNER JOIN @tblComplexFilter_Items		tmpItem
			ON tmpItem.item_id = ti.item_id
			INNER JOIN @tblComplexFilter_Supplier	tmpSupp
			ON tmpSupp.supp_id = ti.supp_id
			WHERE ti.comp_id = @comp_id
		-- ---------------------------------------------------------------------------

		-- ---------------------------------------------------------------------------
		-- Clientes que hayan realizado alguna compra, ya sea por mercadolibre o no y
		-- que tengan al menos una ORDER dentro del rango de fechas
		-- ---------------------------------------------------------------------------
		DECLARE @tblComplexFilter_FinalCustomers TABLE (cust_id INT PRIMARY KEY, MLUserID BIGINT, mlo_id INT)
		INSERT INTO @tblComplexFilter_FinalCustomers
		SELECT DISTINCT
			tc.cust_id,
			tc.MLUser_Id,
			MAX(tmloh.mlo_id)--,
			--tmloh.MLorder_id
			FROM tbCustomer										tc		WITH(NOLOCK)
			INNER JOIN @tblComplexFilter_Customer				tmp
			ON	tmp.cust_id	  = tc.cust_id
			INNER JOIN tbCommercialTransactions					tct		WITH(NOLOCK)
			ON  tct.comp_id	  = tc.comp_id						AND
				tct.cust_id	  = tmp.cust_id
			INNER JOIN tbItemTransactions						tit		WITH(NOLOCK)
			ON	tit.comp_id = tct.comp_id						AND
				tit.ct_transaction = tct.ct_transaction
			INNER JOIN @tblComplexFilter_FinalItemsBySupplier	tmpItem
			ON tmpItem.item_id = tit.item_id
			INNER JOIN tbMercadoLibre_ordersHeader				tmloh	WITH(NOLOCK)
			ON	tmloh.comp_id = tct.comp_id						AND
				tmloh.mlo_id  = tct.mlo_id
			WHERE	tc.comp_id	= @comp_id						AND
					tct.ct_date BETWEEN @datefrom	AND @dateto
		GROUP BY tc.cust_id, tc.MLUser_Id
		-- ---------------------------------------------------------------------------


		INSERT INTO tbMercadoLibre_updateQueue
		(
			comp_id,
			mlp_id,
			mlproc_cd,
			[user_id],
			mlproc_option,
			mlproc_stringValue,
			mlproc_integerValue,
			mlproc_decimalValue,
			mlproc_priority,
			mlproc_guid,
			mlproc_bigintegerValue,
			mlproc_textValue,
			mlproc_internalID
		)
		SELECT
			@comp_id,
			tmlod.mlp_id,
			GETDATE(),
			@user_id,
			14,
			'',
			tmp.mlo_id,
			tmp.MLUserID,
			-1,
			@guid2Execute,
			tmloh.MLorder_id,
			@message,
			9996
		FROM @tblComplexFilter_FinalCustomers		tmp
		INNER JOIN tbMercadoLibre_ordersHeader		tmloh	WITH(NOLOCK)
		ON	tmloh.comp_id	= @comp_id				AND
			tmloh.mlo_id	= tmp.mlo_id
		INNER JOIN tbMercadoLibre_ordersDetail		tmlod	WITH(NOLOCK)
		ON	tmlod.comp_id	= tmloh.comp_id			AND
			tmlod.mlo_id	= tmloh.mlo_id
		INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip	WITH(NOLOCK)
		ON	tmlip.comp_id	= tmlod.comp_id			AND
			tmlip.mlp_id	= tmlod.mlp_id
		WHERE tmlip.comp_id = @comp_id				AND
		(
			@mls_id					= -1 OR
			tmlip.mls_id			= @mls_id)		AND
		(
			@PublicationCategory	= -1 OR
			tmlip.mlipc_id			= @PublicationCategory
		)


	END
GO



