CREATE PROCEDURE [dbo].[spMercadoLibre_Delivery_ExistsGuideNumber]
(
	@comp_id	INT,
	@mlguia		NVARCHAR(50)
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@mlguia		NVARCHAR(50)
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@mlguia		= '38675000000148875939'
		*/
		-- ----------------------------------------------------


		-- A veces las pistolas le ponen un - al final y se debe sacar ya que eso no va informado en el nro q pasa el ws
		SET @mlguia = dbo.fnSplitPosition (@mlguia,'-',1)
		SET @mlguia = dbo.fnGetOnlyNumbers(@mlguia)


		DECLARE
			@lStrGuide	NVARCHAR(200)
		SET @lStrGuide = dbo.fnGetOnlyNumbers(@mlguia)
		DECLARE @tmpSohId TABLE(soh_id INT PRIMARY KEY)

		--RECUPERAMOS TODOS LOS SOH_ID QUE TENGAN EL NUMERO DE GUIA
		INSERT INTO @tmpSohId
		(
			soh_id
		)
		SELECT DISTINCT
			tsoh.soh_id
			FROM tbSaleOrderHeaderHistory				tsoh		WITH (NOLOCK)	-- MOs 02-2016
			WHERE	tsoh.comp_id	= @comp_id			AND
					--STL 03-03-2016
					(
						tsoh.soh_MLGUIA = @lStrGuide
							OR
						tsoh.soh_MLId	= @lStrGuide
					)

		--SI EL COUNT ES MAYOR A CERO IMPLICA QUE EXISTE, SINO ES INCORRECTO
		SELECT
			COUNT(*)
			FROM @tmpSohId

	END
GO




CREATE PROCEDURE [dbo].[spMercadoLibre_Delivery_GetMercadoLibreGridReport]
(
	@comp_id	INT,
	@lang_id	INT,
	@MLGuide	NVARCHAR(50),
	@dateFrom	DATETIME,
	@dateTo		DATETIME,
	@soh_MLId	NVARCHAR(30),
	@st_id		INT,
	@custGuid	UNIQUEIDENTIFIER,
	@optionFilterByStatus AS INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- ---------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@MLGuide	NVARCHAR(50),
				@dateFrom	DATETIME,
				@dateTo		DATETIME,
				@soh_MLId	NVARCHAR(30),
				@st_id		INT,
				@custGuid	UNIQUEIDENTIFIER,
				@optionFilterByStatus  INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@MLGuide	= '',
				@dateFrom	= '2010-03-01',
				@dateTo		= '2016-03-31',
				@soh_MLId	= '',
				@st_id		= -1,
				@custGuid	= '25892e17-80f6-415f-9c65-7395632f0223',
				@optionFilterByStatus = -1
		*/
		-- ---------------------------------------------------

		-- ------------------------------------------------------------------------
		-- SI TIENE ALGO EN LA COMPLEX FILTERS CARGAMOS LOS CLIENTES QUE ESTEN AHÍ
		-- ------------------------------------------------------------------------
		DECLARE
			@tblCustomers	TABLE(
									CustId			INT PRIMARY KEY
								 )

		IF EXISTS (	SELECT 1
						FROM tbComplexFilter tcf WITH(NOLOCK)
		           		WHERE tcf.sl_guid = @custGuid)
			BEGIN
				INSERT INTO @tblCustomers
				(
					CustId
				)
				SELECT
					tcf.sl_id
  					FROM tbComplexFilter tcf	WITH(NOLOCK)
  					WHERE tcf.sl_guid = @custGuid
			END
		ELSE
			BEGIN
				--SI NO HAY NADA EN LA COMPLEXFILTERS CARGAMOS TODOS LOS CLIENTES
				INSERT INTO @tblCustomers (CustId)
				SELECT tc.cust_id
					FROM tbCustomer tc		WITH(NOLOCK)
				    WHERE tc.comp_id = @comp_id
			END
		-- ------------------------------------------------------------------------

		SET @dateFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateFrom	,'False')
		SET @dateTo		= dbo.fnGetEnd_or_BeginOfDate(@dateTo	,'True')


		SELECT DISTINCT
			' '																					[ ], --BOTON REIMPRIMIR COMPROBANTE
			CONVERT(BIT,
			ISNULL(
			(
				SELECT TOP 1 1
					FROM tbSaleOrderHeader_MercadoLibreHistory mk3
					WHERE	mk3.comp_id = tsohh.comp_id AND
							mk3.bra_id	= tsohh.bra_id	AND
							mk3.soh_id	= tsohh.soh_id	AND
							(
								mk3.mls_blockPreparation	= 1 OR
								mk3.mls_blockEmmition		= 1 OR
								mk3.mls_blockDelivery		= 1
							)
			),0))																				[ ], --BOTON VER MEDIACIONES
			tc.cust_id,
			tc.cust_name,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)	[Document],
			tct.ct_ATotal,
			tct.ct_ABalance,
			tst.st_desc,
			tct.ct_deliveryDate,
			tmldd.mld_cd,
			ISNULL(tsohh.soh_MLId,'')								[soh_MLId],
			ISNULL(tsohh.soh_MLGUIA,'')								[soh_MLGUIA],
			ISNULL(tmldh.mld_guide,'')								[mld_guide],
			ISNULL(tmldh.mld_note,'')								[mld_note],
			tct.ct_transaction,
			CONVERT(nvarchar(15),tct.ct_transaction) + '-' + CONVERT(nvarchar(15),tsohh.bra_id) + '-' + CONVERT(nvarchar(15),tsohh.soh_id)	[ID]
			FROM tbCommercialTransactions								tct
				LEFT JOIN tbSaleOrderHeaderHistory						tsohh
					ON	tsohh.comp_id			= tct.comp_id			AND
						tsohh.ct_transaction	= tct.ct_transaction
				LEFT JOIN tbMercadoLibre_DeliveryDetail				tmldd
					ON	tmldd.comp_id			= tct.comp_id			AND
						tmldd.ct_transaction	= tct.ct_transaction
				LEFT JOIN tbMercadoLibre_DeliveryHeader				tmldh
					ON	tmldh.comp_id			= tmldd.comp_id			AND
						tmldh.mld_id			= tmldd.mld_id
				INNER JOIN @tblCustomers								tctmp
					ON tctmp.CustId				= tct.cust_id
				INNER JOIN tbCustomer									tc
					ON	tc.comp_id				= tct.comp_id			AND
						tc.cust_id				= tct.cust_id
				INNER JOIN tbSalesTerms									tst
					ON	tst.comp_id				= tct.comp_id			AND
						tst.st_id				= tct.st_id

			WHERE	tct.comp_id					= @comp_id								AND
					CASE
						WHEN @optionFilterByStatus = -1									THEN 1
						WHEN @optionFilterByStatus =  2 AND tmldd.comp_id IS     NULL	THEN 1
						WHEN @optionFilterByStatus =  1 AND tmldd.comp_id IS NOT NULL	THEN 1
						ELSE																					 0
					END	 = 1																AND
					CASE
						WHEN @optionFilterByStatus = -1 AND tct.ct_date		BETWEEN @dateFrom AND @dateTo	THEN 1
						WHEN @optionFilterByStatus =  2	AND tct.ct_date		BETWEEN @dateFrom AND @dateTo	THEN 1
						WHEN @optionFilterByStatus =  1 AND tmldd.mld_cd	BETWEEN @dateFrom AND @dateTo	THEN 1
						ELSE																					 0
					END	 = 1																AND
					CASE
						WHEN @MLGuide			= ''			THEN 1
						WHEN tsohh.soh_MLGUIA	= @MLGuide		THEN 1
						ELSE										 0
					END	= 1																	AND
					CASE
						WHEN @soh_MLId 	= ''			THEN 1
						WHEN tsohh.soh_MLId = @soh_MLId THEN 1
						ELSE								 0
					END = 1																	AND
					(@st_id						= -1 OR	tct.st_id		 = @st_id)			AND
					ISNULL(tsohh.soh_MLId,'')	<> ''										AND
					tsohh.comp_id = @comp_id
			ORDER BY tct.ct_transaction DESC

	END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_Delivery_GetReport]
(
	@comp_id		INT,
	@lang_id		INT,
	@page_id		INT,
	@mld_id			INT,
	@intBranch4Lang	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- ---------------------------------
		-- TESTING
		-- ---------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@page_id		INT,
				@mld_id			INT,
				@intBranch4Lang	INT

			SELECT
				@comp_id		= 1,
				@lang_id		= 2,
				@page_id		= 10000,
				@mld_id			= 181,
				@intBranch4Lang	= 1
		*/
		-- ---------------------------------

		SELECT
			td.dl_name,
			td.dl_address,
			td.dl_city,
			td.dl_zip,

			tmldh.mld_guide,
			ISNULL(tmldh.mld_note,'')				[mld_note]
			FROM tbMercadoLibre_DeliveryHeader		tmldh
				INNER JOIN tbDelivery				td
					ON	td.comp_id	= tmldh.comp_id AND
						td.dl_id	= tmldh.dl_id
			WHERE	tmldh.comp_id	= @comp_id		AND
					tmldh.mld_id	= @mld_id


		EXEC [spReports_getData3] @comp_id, @intBranch4Lang , @lang_id, @page_id

		DECLARE
			@lINTBultos	INT,
			@lINTGuias	INT

		--SUMAMOS LA CANTIDAD DE BULTOS POR CT_TRANSACTION
		SELECT
			@lINTBultos  = ISNULL(SUM(tct.ct_packagesQty),0)
			FROM tbMercadoLibre_DeliveryDetail						tmldd
				INNER JOIN tbCommercialTransactions					tct
					ON	tct.comp_id			= tmldd.comp_id			AND
						tct.ct_transaction	= tmldd.ct_transaction
			WHERE	tmldd.comp_id			= @comp_id				AND
					tmldd.mld_id			= @mld_id

		--CONTAMOS LA CANTIDAD DE GUÍAS
		SELECT
			@lINTGuias  = COUNT(*)
			FROM tbMercadoLibre_DeliveryDetail						tmldd
				INNER JOIN tbCommercialTransactions					tct
					ON	tct.comp_id			= tmldd.comp_id			AND
						tct.ct_transaction	= tmldd.ct_transaction
			WHERE	tmldd.comp_id			= @comp_id				AND
					tmldd.mld_id			= @mld_id


		DECLARE
			@lMessage	VARCHAR(600),
			@lMessage2	VARCHAR(600)

		--Cantidad Total de Bultos
		SELECT
			@lMessage = tut.utexts_desc
		FROM tbsysUniqueTexts				tut
		WHERE	tut.lang_id		= @lang_id	AND
				tut.utexts_id	= 30761

		--Cantidad Total de # de Guía
		SELECT
			@lMessage2 = tut.utexts_desc
		FROM tbsysUniqueTexts				tut
		WHERE	tut.lang_id		= @lang_id	AND
				tut.utexts_id	= 30762


		SELECT
			@lMessage			[Bulto_Leyenda],
			@lINTBultos			[Bultos],
			@lMessage2			[Guias_Leyenda],
			@lINTGuias			[Guias]


		--ATENCION.Tener en cuenta que si anda lento es porque no deberia ir el distinct y deberia ir una subconsulta mostrando mlguia
		SELECT DISTINCT
			tsoh.soh_MLGUIA,
			dbo.fnGetCommercialTransactionDescription(tmldd.comp_id,@lang_id,tmldd.ct_transaction)	[Document],
			tc.cust_name,
			tct.ct_ATotal
		FROM tbMercadoLibre_DeliveryDetail						tmldd	WITH(NOLOCK)
			INNER JOIN tbCommercialTransactions					tct		WITH(NOLOCK)
				ON	tct.comp_id			= tmldd.comp_id			AND
					tct.ct_transaction	= tmldd.ct_transaction
			INNER JOIN tbItemTransactions						tit		WITH(NOLOCK)
				ON	tit.comp_id			= tct.comp_id			AND
					tit.ct_transaction	= tct.ct_transaction
			--CORREGIDO FALTABA EL BRA_ID EN EL JOIN
			INNER JOIN tbSaleOrderHeaderHistory					tsoh
				ON	tsoh.comp_id		= tit.comp_id			AND
					tsoh.soh_id			= tit.it_soh_id			AND
					tsoh.bra_id			= tit.bra_id
			INNER JOIN tbCustomer								tc
				ON	tc.comp_id			= tct.comp_id			AND
					tc.cust_id			= tct.cust_id
		WHERE	tmldd.comp_id	= @comp_id AND
				tmldd.mld_id	= @mld_id




	END









GO



CREATE PROCEDURE [dbo].[spMercadoLibre_Delivery_IsSOHBlocked4Delivery]
(
	@comp_id	INT,
	@mlguia		NVARCHAR(50)
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@mlguia		NVARCHAR(50)
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@mlguia		= '38675000000148875940'
		*/
		-- ----------------------------------------------------

		DECLARE
			@lStrGuide	NVARCHAR(200)
		SET @lStrGuide = dbo.fnGetOnlyNumbers(@mlguia)
		DECLARE @tmpSohId TABLE(bra_id INT, soh_id INT PRIMARY KEY)

		--RECUPERAMOS TODOS LOS SOH_ID QUE TENGAN EL NUMERO DE GUIA
		INSERT INTO @tmpSohId
		(
			bra_id,
			soh_id
		)
		SELECT DISTINCT
			tsohh.bra_id,
			tsohh.soh_id
			FROM tbSaleOrderHeaderHistory				tsohh		WITH (NOLOCK)
			WHERE	tsohh.comp_id		= @comp_id		AND
					--STL 03-03-2016
					(
						tsohh.soh_MLGUIA	= @lStrGuide
							OR
						tsohh.soh_MLId		= @lStrGuide
					)

		--SI EL COUNT ES MAYOR A CERO IMPLICA QUE TIENE AL MENOS UNA MEDIACION QUE NO LE PERMITE SER ENVIADO
		SELECT
			COUNT(*)
			FROM tbSaleOrderHeader_MercadoLibreHistory						tsohmlh		WITH (NOLOCK)
			INNER JOIN @tmpSohId										tmp
				ON	tmp.bra_id									= tsohmlh.bra_id	AND
					tmp.soh_id									= tsohmlh.soh_id
			WHERE	tsohmlh.comp_id								= @comp_id			AND
					ISNULL(tsohmlh.mls_blockDelivery,'False')	= 'True'

	END
GO



