CREATE PROCEDURE [dbo].[spMercadoLibre_DeliveryDetail_GetDataByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@mld_id		INT--,
	--@user_id	INT,
	--@isMailed	INT
)
AS
	BEGIN
		SET NOCOUNT ON


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@mld_id		INT,
				@user_id	INT,
				@isMailed	INT
		*/
		-- ---------------------------------------------

		SELECT
			' '																							[ ],
			dbo.fnGetCommercialTransactionDescription(tmldd.comp_id, @lang_id, tmldd.ct_transaction)	[Document],
			tct.ct_ATotal,
			tc.cust_name,
			tu.user_lastname + ',' + tu.user_firstname													[user_name],
			tmldd.mld_cd,
			ISNULL(tmldd.mldd_isMailed,'False')															[mldd_isMailed],
			ISNULL(
			(
				SELECT TOP 1 tsohh.soh_MLGUIA
					FROM tbItemTransactions tit
					INNER JOIN tbSaleOrderHeaderHistory tsohh
						ON	tsohh.comp_id	= tit.comp_id	AND
							tsohh.bra_id	= tit.bra_id	AND
							tsohh.soh_id	= tit.it_soh_id
					WHERE	tit.comp_id			= tct.comp_id AND
							tit.ct_transaction	= tct.ct_transaction
			),'*')
																										[ml_Guia],
			CONVERT(VARCHAR,tmldd.mld_id) + '-' + CONVERT(VARCHAR,tmldd.ct_transaction)					[ID]
			FROM tbMercadoLibre_DeliveryDetail															tmldd			WITH(NOLOCK)
				INNER JOIN tbUser																		tu				WITH(NOLOCK)
					ON tu.[user_id]			= tmldd.[user_id]
				INNER JOIN tbCommercialTransactions														tct				WITH(NOLOCK)
					ON	tct.comp_id			= tmldd.comp_id												AND
						tct.ct_transaction	= tmldd.ct_transaction
				INNER JOIN tbCustomer																	tc				WITH(NOLOCK)
					ON	tc.comp_id			= tmldd.comp_id												AND
						tc.cust_id			= tct.cust_id
			WHERE	tmldd.comp_id	= @comp_id															AND
					tmldd.mld_id	= @mld_id															--AND
					--(-1				= @user_id			OR @user_id		= tmldd.[user_id])				AND
					--(-1				= @isMailed			OR @isMailed	= ISNULL(tmldd.mldd_isMailed,'False'))
	END
GO




CREATE PROCEDURE [dbo].[spMercadoLibre_DeliveryDetail_InsertData]
(
	@comp_id		INT,
	@mld_id			INT,
	@user_id		INT,
	@mlguia			NVARCHAR(50)
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------
		-- TESTING
		-- ----------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@mld_id				INT,
				@ct_transaction		INT,
				@user_id			INT,
				@mlguia				DECIMAL(25,0)

			SELECT
				@comp_id			= 1,
				@bra_id				= 1,
				@mld_id				= 285,
				@ct_transaction		= 1,
				@user_id			= 1,
				@mlguia				= '21527032819'
		*/
		-- ----------------------------------------




		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		DECLARE
			@lStrGuide	NVARCHAR(200)


		-- A veces las pistolas le ponen un - al final y se debe sacar ya que eso no va informado en el nro q pasa el ws
		set @mlguia = dbo.fnSplitPosition(@mlguia,'-',1)

		SET @lStrGuide = dbo.fnGetOnlyNumbers(@mlguia)

		--RECUPERAMOS TODOS LOS CT_TRANSACTION DE LA ITEMTRANSACTIONS QUE ESTEN
		--RELACIONADOS A LOS SOH_ID QUE TENGAN COMO NÚMERO DE GUÍA LEIDOS POR
		--LA PISTOLA.
		--LEFT JOIN CON LA MERCADOLIBREHISTORY PARA QUE NO TRAIGA LOS QUE ESTEN BLOQUEADOS
		--LEFT JOIN CON LA MERCADOLIBRE_DELIVERYDETAIL PARA QUE NO INSERTE REPETIDOS


		DECLARE @tmpCT_Transactions TABLE(ct_transaction INT PRIMARY KEY)
		INSERT INTO @tmpCT_Transactions
		(
			ct_transaction
		)
		SELECT DISTINCT
			tit.ct_transaction
			FROM tbItemTransactions											tit			WITH (NOLOCK)

			INNER JOIN tbSaleOrderHeaderHistory								tsoh		WITH (NOLOCK)		-- MOS 02-2016
				ON	tsoh.comp_id			= tit.comp_id					AND
					tsoh.ct_transaction		= tit.ct_transaction
					--tsoh.bra_id				= tit.bra_id					AND
					--tsoh.soh_id				= tit.it_soh_id

			LEFT JOIN tbSaleOrderHeader_MercadoLibreHistory					tsohmlh		WITH (NOLOCK)
				ON	tsohmlh.comp_id				= tsoh.comp_id				AND
					tsohmlh.bra_id				= tsoh.bra_id				AND
					tsohmlh.soh_id				= tsoh.soh_id				AND
					tsohmlh.mls_blockDelivery	= 'True'

			LEFT JOIN tbMercadoLibre_DeliveryDetail							tmldd		WITH (NOLOCK)
				ON	tmldd.comp_id			= tit.comp_id					AND
					tmldd.ct_transaction	= tit.ct_transaction

			WHERE	tit.comp_id									= @comp_id		AND
					--STL 03-03-2016
					(
						tsoh.soh_MLId								= @lStrGuide
							OR
						tsoh.soh_MLGUIA								= @lStrGuide
					)															AND
					ISNULL(tsohmlh.mls_blockDelivery,'False')	= 'False'		AND
					tmldd.ct_transaction						IS NULL


		INSERT INTO tbMercadoLibre_DeliveryDetail
		(
			comp_id,
			mld_id,
			ct_transaction,
			mld_cd,
			user_id,
			mldd_isMailed
		)
		SELECT
			@comp_id,
			@mld_id,
			tmp.ct_transaction,
			GETDATE(),
			@user_id,
			'False'
			FROM @tmpCT_Transactions tmp


		--VARIABLE PARA SABER SI LA TABLA QUE VA A INSERTAR TIENE ALGO
		--EN CASO DE NO TENER NADA, DEVOLVEMOS -1 E INFORMAMOS QUE EL
		--NUMERO DE GUIA NO HA SIDO CERRADO AUN O QUE YA SE ENCUENTRA GRABADO EN OTRO DESPACHO
		--Y DEVOLVEMOS 1 SI TIENE YA TIENE ALGO PARA INSERTAR
		DECLARE
			@intCounter INT
		SET @intCounter = 0

		IF (SELECT COUNT(*) FROM @tmpCT_Transactions) > 0
			BEGIN
				SET @intCounter = 1
			END
		ELSE
			BEGIN
				SET @intCounter = -1
			END

		SELECT @intCounter

	END







GO




CREATE PROCEDURE [dbo].[spMercadoLibre_DeliveryHeader_CloseOrOpen]
(
	@comp_id	INT,
	@lang_id	INT,
	@mld_id		INT,
	@user_id	INT
)
AS

	BEGIN

		-- --------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@mld_id		INT,
				@user_id	INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@mld_id		= 11,
				@user_id	= 119
		*/
		-- --------------------------------------------------------------



		SET NOCOUNT ON
		DECLARE @IsClosed BIT
		SET @IsClosed = 'False'

		SELECT
			@IsClosed = CASE WHEN tmldh.user_id_closer IS NULL THEN
							'False'
						ELSE
							'True'
						END
		FROM tbMercadoLibre_DeliveryHeader tmldh
		WHERE	tmldh.comp_id	= @comp_id AND
				tmldh.mld_id	= @mld_id


		IF @IsClosed = 'False'
			BEGIN

				--SE DA COMO CERRADO EL HEADER
				UPDATE tbMercadoLibre_DeliveryHeader
				SET
					user_id_closer	= @user_id,
					mld_closeDate	= GETDATE()
				WHERE	comp_id = @comp_id AND
						mld_id	= @mld_id

				-- -----------------------------------------------------------------------------
				-- UNA VEZ CERRADO EL LOTE DE ENVÍOS ENVIAR MAIL A TODOS LOS CLIENTES
				-- -----------------------------------------------------------------------------
					DECLARE @subject		AS NVARCHAR(300)
					DECLARE @MailBody		AS NVARCHAR(MAX)
					DECLARE @strMailString	AS NVARCHAR(MAX)
					DECLARE @strMail		AS NVARCHAR(MAX)
					DECLARE @strMailFrom    AS NVARCHAR(MAX)

					DECLARE @dl_eMailWhenDeliveredHead		NVARCHAR(MAX)
					DECLARE @dl_eMailWhenDeliveredFooter	NVARCHAR(MAX)
					DECLARE @dl_eMailWhenDeliveredFromEmail	NVARCHAR(MAX)
					DECLARE @dl_eMailWhenDelivered			BIT

					SELECT
						@dl_eMailWhenDelivered			= ISNULL(td.dl_eMailWhenDelivered,'False'),
						@subject						= ISNULL(td.dl_eMailWhenDeliveredSubject,''),
						@strMailFrom					= ISNULL(td.dl_eMailWhenDeliveredFromEmail,''),
						@dl_eMailWhenDeliveredHead		= ISNULL(td.dl_eMailWhenDeliveredHead,''),
						@dl_eMailWhenDeliveredFooter	= ISNULL(td.dl_eMailWhenDeliveredFooter,''),
						@dl_eMailWhenDeliveredFromEmail = ISNULL(td.dl_eMailWhenDeliveredFromEmail,'')
						FROM tbDelivery td
							INNER JOIN tbMercadoLibre_DeliveryHeader	tmldh
								ON	tmldh.comp_id	= td.comp_id		AND
									tmldh.dl_id		= td.dl_id
						WHERE	td.comp_id			= @comp_id			AND
								tmldh.mld_id		= @mld_id


					--VARIABLES DE TRABAJO
					DECLARE
						@cust_name		VARCHAR(200),
						@cust_email		VARCHAR(200),
						@soh_MLId		VARCHAR(200),
						@soh_MLGUIA		VARCHAR(200),
						@ct_transaction	INT

					DECLARE cursor_Customer2Email CURSOR FOR

						SELECT DISTINCT
							tc.cust_name,
							tc.cust_email,
							tsoh.soh_MLId,
							tsoh.soh_MLGUIA,
							tmldd.ct_transaction
							FROM tbMercadoLibre_DeliveryDetail						tmldd
								INNER JOIN tbCommercialTransactions					tct
									ON	tct.comp_id			= tmldd.comp_id			AND
										tct.ct_transaction	= tmldd.ct_transaction
								INNER JOIN tbCustomer								tc
									ON	tc.comp_id			= tct.comp_id			AND
										tc.cust_id			= tct.cust_id
								INNER JOIN tbItemTransactions						tit
									ON	tit.comp_id			= tct.comp_id			AND
										tit.bra_id			= tct.bra_id			AND
										tit.ct_transaction	= tct.ct_transaction
								INNER JOIN tbSaleOrderHeader						tsoh
									ON	tsoh.comp_id		= tit.comp_id			AND
										tsoh.bra_id			= tit.bra_id			AND
										tsoh.soh_id			= tit.it_soh_id
								INNER JOIN tbSaleOrderDetail						tsod
									ON	tsod.comp_id		= tsoh.comp_id			AND
										tsod.soh_id			= tsoh.soh_id
							WHERE	tmldd.comp_id							= @comp_id	AND
									tmldd.mld_id							= @mld_id	AND
									ISNULL(tmldd.mldd_isMailed, 'False')	= 'False'

					OPEN cursor_Customer2Email

					FETCH NEXT FROM cursor_Customer2Email INTO
										@cust_name,
										@cust_email,
										@soh_MLId,
										@soh_MLGUIA,
										@ct_transaction

					WHILE @@FETCH_STATUS = 0
						BEGIN

							--SI EL CLIENTE TIENE UN MAIL, LO ENVIAMOS
							IF (@cust_email IS NOT NULL) AND (@dl_eMailWhenDelivered = 'True')
								BEGIN

									SET @MailBody = @dl_eMailWhenDeliveredHead														+ ' ' +
													dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, @ct_transaction)	+ ' ' +
													@soh_MLGUIA																		+ ' ' +
													@dl_eMailWhenDeliveredFooter


									EXEC spSystem_sendEMail
													@compId					= @comp_id,
													@precipients			= @cust_email,
													@pcopy_recipients		= NULL,
													@psubject				= @subject,
													@pbody_format			= 'HTML',
													@pbody					= @Mailbody,
													@pfile_attachments		= NULL,
													@pReplyTo				= @strMailFrom,
													@pblind_copy_recipients	= NULL,
													@pUser_Id				= @user_id


									--UNA VEZ ENVIADO ACTUALIZAMOS EL ESTADO A ENVIADO EN LA DETAIL DE MERCADO LIBRE
									UPDATE tbMercadoLibre_DeliveryDetail
									SET
										mldd_isMailed = 'True'
									WHERE	comp_id			= @comp_id AND
											mld_id			= @mld_id  AND
											ct_transaction	= @ct_transaction

								END

							FETCH NEXT FROM cursor_Customer2Email INTO
												@cust_name,
												@cust_email,
												@soh_MLId,
												@soh_MLGUIA,
												@ct_transaction
						END
					CLOSE cursor_Customer2Email
					DEALLOCATE cursor_Customer2Email


			END
		ELSE
			BEGIN
				UPDATE tbMercadoLibre_DeliveryHeader
				SET
					user_id_closer	= NULL,
					mld_closeDate	= NULL
				WHERE	comp_id = @comp_id AND
						mld_id	= @mld_id
			END

	END



GO



