CREATE PROCEDURE [dbo].[spMercadoLibre_DeliveryHeader_GetDataByFilters]
(
	@comp_id			INT,
	@GuideNumber		VARCHAR(100),
	@IsClosed			INT,
	@user_id_creator	INT,
	@user_id_closer		INT,
	@MLGuideNumber		VARCHAR(100),
	@datFromCreationDate	DATETIME,
	@datToCreationDate		DATETIME
)
AS

	BEGIN

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		SET NOCOUNT ON
		-- --------------------------------------------------
		-- TESTING
		-- --------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@GuideNumber		VARCHAR(100),
				@IsClosed			BIT,
				@user_id_creator	INT,
				@user_id_closer		INT
			SELECT
				@comp_id			=  1,
				@GuideNumber		= 'sabadaba',
				@IsClosed			=  1,
				@user_id_creator	= -1,
				@user_id_closer		= -1
		*/
		-- --------------------------------------------------


		SET @datFromCreationDate	= dbo.fnGetEnd_or_BeginOfDate(@datFromCreationDate,'False')
		SET @datToCreationDate		= dbo.fnGetEnd_or_BeginOfDate(@datToCreationDate,  'False')




		SELECT
			' '														[ ],	--MODIFICAR
			' '														[ ],	--BORRAR
			' '														[ ],	--CERRAR
			' '														[ ],	--REPORTE
			' '														[ ],	--MODIFICAR NOTA / TRANSPORTE
			CONVERT(VARCHAR(500),ISNULL(tmldh.mld_guide,''))		[mld_guide],
			td.dl_name,
			tu.user_lastname + ',' + tu.user_firstname				[user_Creator],
			tmldh.mld_creationDate,
			ISNULL(tu2.user_lastname + ',' + tu.user_firstname,'')	[user_Closer],
--			CASE WHEN tmldh.mld_closeDate IS NULL THEN
--				''
--			ELSE
--				tmldh.mld_closeDate
--			END														[mld_closeDate],
			tmldh.mld_closeDate,
			ISNULL(tmldh.mld_note,'')								[mld_note],
			tmldh.mld_id											[ID]

		FROM tbMercadoLibre_DeliveryHeader							tmldh		WITH (NOLOCK)
			INNER JOIN tbDelivery									td			WITH (NOLOCK)
				ON	td.comp_id		= tmldh.comp_id					AND
					td.dl_id		= tmldh.dl_id
			INNER JOIN tbUser										tu			WITH (NOLOCK)
				ON	tu.[user_id]	= tmldh.user_id_creator
			LEFT JOIN tbUser										tu2			WITH (NOLOCK)
				ON	tu2.[user_id]	= tmldh.user_id_closer
		WHERE	tmldh.comp_id	= @comp_id														AND
				tmldh.mld_creationDate BETWEEN @datFromCreationDate AND @datToCreationDate		AND
				(@GuideNumber	= '' OR tmldh.mld_guide = @GuideNumber)							AND
				(	-1			= @user_id_creator	OR tmldh.user_id_creator = @user_id_creator)AND
				(	-1			= @user_id_closer	OR tmldh.user_id_closer  = @user_id_closer)	AND
				(
					(-1			= @IsClosed)										OR	--TODOS
					(@IsClosed	= 1			AND tmldh.user_id_closer IS NOT NULL)	OR	--LOS CERRADOS
					(@IsClosed	= 0			AND tmldh.user_id_closer IS NULL)			--LOS ABIERTOS
				)																				AND
				-- Si se pide buscar solo los que tengan un nro de guia de ML dentro . . .  es lento pero lo busca.
				CASE
					WHEN @MLGuideNumber = ''	THEN	1
					WHEN EXISTS(	SELECT TOP 1  1
					            		FROM tbMercadoLibre_DeliveryDetail tmldd	WITH (NOLOCK)
					            		INNER JOIN tbItemTransactions tit			WITH (NOLOCK)
					            			ON	tit.comp_id			= tmldd.comp_id AND
					            				tit.ct_transaction	= tmldd.ct_transaction
					            		INNER JOIN tbSaleOrderHeaderHistory tsohh	WITH (NOLOCK)
					            			ON	tsohh.comp_id	= tit.comp_id AND
					            				tsohh.bra_id	= tit.bra_id AND
					            				tsohh.soh_id	= tit.it_soh_id

					            		WHERE	tsohh.comp_id		= @comp_id			AND
					            				tsohh.soh_MLGUIA	= @MLGuideNumber	AND
					            				tmldd.comp_id		= @comp_id			AND
					           				tmldd.mld_id		= tmldh.mld_id
								) 				THEN	1
					ELSE								0
				END	= 1


		ORDER BY tmldh.mld_id DESC

	END





GO



