CREATE  PROCEDURE [dbo].[spMercadoLibre_GBPMeLiID4url_InsertData2WS]
AS

BEGIN

	SET NOCOUNT ON

	DECLARE @Obj		int
	DECLARE @Result		INT
	DECLARE @HTTPStatus int
	DECLARE @comp_guid AS NVARCHAR(100)
	DECLARE @MLUser_Id AS BIGINT

	DECLARE curMeLiID CURSOR LOCAL FAST_FORWARD FOR
	SELECT	DISTINCT
			CONVERT(NVARCHAR(100),tc.comp_guid),
			tmls.MLUser_Id
		FROM tbMercadoLibre_Stores	AS tmls	WITH (NOLOCK)
		INNER JOIN tbCompany		AS tc	WITH (NOLOCK)
			ON	tc.comp_id = tmls.comp_id
		WHERE	tmls.mls_disabled	= 'False' AND
				tmls.MLUser_Id		> 0

	OPEN		curMeLiID

	FETCH NEXT FROM curMeLiID INTO @comp_guid,@MLUser_Id

	DECLARE @URL AS NVARCHAR(250)
	DECLARE @strRET		AS NVARCHAR(MAX)
	WHILE @@FETCH_STATUS = 0
		BEGIN

			SELECT	@URL =  'https://erp.globalbluepoint.com/wfmMercadoLibre_UpdateMLId4Listener.aspx?comp_guid=' + @comp_guid + '&MLUser_Id=' + CONVERT(NVARCHAR(100),@MLUser_Id)

			set @strRET  = dbo.clrActivateURL(@URL)

			--SELECT	@URL =  'http://192.168.1.150/gbperp/wfmMercadoLibre_UpdateMLId4Listener.aspx?comp_guid=' + @comp_guid + '&MLUser_Id=' + CONVERT(NVARCHAR(100),@MLUser_Id)

			FETCH NEXT FROM curMeLiID INTO @comp_guid,@MLUser_Id
		END

	CLOSE		curMeLiID
	DEALLOCATE	curMeLiID


END


GO



-- Este SP se va a usar poco, salvo cuando den de alta una nueva tienda o cuando se corra actualizacion x primera vez en la que cada BD llamara a l WS e insertará los valores
-- para que no nos rompan las pelotas.
-- Esta tabla la usa la pagina de ProcessListener.
CREATE  PROCEDURE [dbo].[spMercadoLibre_GBPMeLiID4url_UpdateData]
(
	@comp_Guid	AS NVARCHAR(100) ,
	@intMeLiID	AS BIGINT
)
AS

BEGIN

	SET NOCOUNT ON

	DECLARE @cust_id AS INT = -1
	SELECT	@cust_id		= cust_id
		FROM tbCustomer AS tc  WITH (NOLOCK )
		WHERE	tc.cust_GBPCG		= @comp_Guid	AND
				tc.cust_GBPUserQty	> 0



	IF @cust_id > 0
		BEGIN
			IF NOT EXISTS(
							SELECT TOP 1 1
								FROM tbMercadoLibre_GBPMeLiID4url AS tmlgli	WITH (NOLOCK)
								WHERE	tmlgli.comp_id			= 1 AND
										tmlgli.cust_id			= @cust_id AND
										tmlgli.cust_GBPMeLi_ID	= @intMeLiID
							)
			AND
			   NOT EXISTS(
							SELECT TOP 1 1
								FROM tbMercadoLibre_GBPMeLiID4url AS tmlgli	WITH (NOLOCK)
								WHERE	tmlgli.cust_GBPMeLi_ID	= @intMeLiID
						)
				BEGIN
					INSERT INTO tbMercadoLibre_GBPMeLiID4url
					(
						comp_id,
						cust_id,
						cust_GBPMeLi_ID
					)
					VALUES
					(
						1,
						@cust_id,
						@intMeLiID
					)
				END
		END



END


GO


CREATE PROCEDURE [dbo].[spMercadoLibre_GenerateItems2Publicate4Excel]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,

	@ItemGuid				UNIQUEIDENTIFIER,
	@mls_id					INT,
	@mlipc_id				INT,
	@prli_id				INT,
	@stor_id				INT,
	@mlp_listing_type_id	NVARCHAR(100),
	@strCategoryID			NVARCHAR(30),
	@strAttributes			NVARCHAR(MAX)
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@prof_id				INT,
				@user_id				INT,

				@ItemGuid				UNIQUEIDENTIFIER,
				@mls_id					INT,
				@mlipc_id				INT,
				@prli_id				INT,
				@stor_id				INT,
				@mlp_listing_type_id	NVARCHAR(100),
				@strCategoryID			NVARCHAR(30),
				@strAttributes			NVARCHAR(MAX)

			SELECT
				@comp_id				= 1,
				@lang_id				= 2,
				@bra_id					= 1,
				@prof_id				= 1,
				@user_id				= 10001,

				@ItemGuid				= '41863E35-DDA2-4F10-9E0F-D13B6E2A6729',
				@mls_id					= 5,
				@mlipc_id				= 5,
				@prli_id				= 1,
				@stor_id				= 1,
				@mlp_listing_type_id	= 'gold_special',
				@strCategoryID			= 'MLA1099',
				@strAttributes			= ''

				DROP TABLE #tmpItems2Publicate
		*/
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- TABLA DE ARTICULOS
		-- -----------------------------------------------------------------------------
			DECLARE @objGUID AS UNIQUEIDENTIFIER
			SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@ItemGuid)

			DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)

			INSERT INTO @tblComplexFilter_Items

				SELECT
					tcf.sl_id
					FROM tbComplexFilter tcf      WITH (NOLOCK)
					WHERE tcf.sl_guid	  = @objGUID      AND
							tcf.sl_selected = 'True'

			IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		--SELECT PRINCIPAL CON LOS ARTICULOS Y PARÁMETROS DEFINIDOS EN AL PÁGINA
		-- -----------------------------------------------------------------------------
		SELECT
			@strCategoryID														[CategoryID],
			@mls_id																[mls_id],
			@mlipc_id															[mlipc_id],
			@mlp_listing_type_id												[ListingType],
			ti.item_code														[item_code],
			CASE WHEN ISNULL(ti.item_ML_title,'') = '' THEN ti.item_desc
			ELSE											ti.item_ML_title
			END																	[ml_Title],
			ISNULL(ti.item_ML_desc ,'')											[Description],
			@prli_id															[prli_desc],
			@stor_id															[stor_desc],


			CASE WHEN ISNULL(ti.MLPictureId1,ISNULL(ti.item_WebSite_url4Image1,'')) = '' THEN	''
			ELSE																				ISNULL(ti.MLPictureId1,ISNULL(ti.item_WebSite_url4Image1,''))
			END																	[URLImage1],
			CASE WHEN ISNULL(ti.MLPictureId2,ISNULL(ti.item_WebSite_url4Image2,'')) = '' THEN	''
			ELSE																				ISNULL(ti.MLPictureId2,ISNULL(ti.item_WebSite_url4Image2,''))
			END																	[URLImage2],
			CASE WHEN ISNULL(ti.MLPictureId3,ISNULL(ti.item_WebSite_url4Image3,'')) = '' THEN	''
			ELSE																				ISNULL(ti.MLPictureId3,ISNULL(ti.item_WebSite_url4Image3,''))
			END																	[URLImage3],
			CASE WHEN ISNULL(ti.MLPictureId4,ISNULL(ti.item_WebSite_url4Image4,'')) = '' THEN	''
			ELSE																				ISNULL(ti.MLPictureId4,ISNULL(ti.item_WebSite_url4Image4,''))
			END																	[URLImage4],
			CASE WHEN ISNULL(ti.MLPictureId5,ISNULL(ti.item_WebSite_url4Image5,'')) = '' THEN	''
			ELSE																				ISNULL(ti.MLPictureId5,ISNULL(ti.item_WebSite_url4Image5,''))
			END																	[URLImage5],

			CASE WHEN ISNULL(ti.MLPictureId6,ISNULL(ti.item_WebSite_url4Image6,'')) = '' THEN	''
			ELSE																				ISNULL(ti.MLPictureId6,ISNULL(ti.item_WebSite_url4Image6,''))
			END																	[URLImage6],

			CASE WHEN ISNULL(ti.MLPictureId7,ISNULL(ti.item_WebSite_url4Image7,'')) = '' THEN	''
			ELSE																				ISNULL(ti.MLPictureId7,ISNULL(ti.item_WebSite_url4Image7,''))
			END																	[URLImage7],

			CASE WHEN ISNULL(ti.MLPictureId8,ISNULL(ti.item_WebSite_url4Image8,'')) = '' THEN	''
			ELSE																				ISNULL(ti.MLPictureId8,ISNULL(ti.item_WebSite_url4Image8,''))
			END																	[URLImage8],

			CASE WHEN ISNULL(ti.MLPictureId9,ISNULL(ti.item_WebSite_url4Image9,'')) = '' THEN	''
			ELSE																				ISNULL(ti.MLPictureId9,ISNULL(ti.item_WebSite_url4Image9,''))
			END																	[URLImage9],

			CASE WHEN ISNULL(ti.MLPictureId10,ISNULL(ti.item_WebSite_url4Image10,'')) = '' THEN	''
			ELSE																				ISNULL(ti.MLPictureId10,ISNULL(ti.item_WebSite_url4Image10,''))
			END																	[URLImage10],


			''																	[mlp_price4AdditionalCost],
			''																	[Para usos futuros 2],

			''																	[max_qty2Publicate],
			''																	[Warranty_Type],
			''																	[Warranty_TimeValue],
			''																	[Warranty_Time]


			INTO #tmpItems2Publicate
			FROM tbItem															ti	WITH(NOLOCK)
			INNER JOIN @tblComplexFilter_Items									tmp
			ON tmp.Item_Id = ti.item_id

		-- -----------------------------------------------------------------------------
		-- ACA ARMAMOS EL PACK DE COLUMNAS DINAMICAS A AGREGAR A LA TABLA
		-- -----------------------------------------------------------------------------

		-- -------------------------------------------------------------------
		-- Variables para el Cursor
		-- -------------------------------------------------------------------
			DECLARE
				@AttributeID				NVARCHAR(100),
				@AttributeName				NVARCHAR(100),
				@AttributeValue				NVARCHAR(100),
				@AtrributeString			NVARCHAR(1000)
		-- -------------------------------------------------------------------
			DECLARE @intAttributeCounter AS INT
			SET @intAttributeCounter = 0
													  -- MOS NUEBVO 12-2-15
			DECLARE Cursor_ModTMPTable4Columns CURSOR LOCAL FAST_FORWARD FOR

				--ACA VA EL STRING QUE VA A SEPARAR EN UNA TABLA DE TRIADAS DE ATRIBUTOS
				SELECT
					fst.items
				FROM
					dbo.fnSplitTable(@strAttributes,'|') fst

			OPEN Cursor_ModTMPTable4Columns

			FETCH NEXT FROM Cursor_ModTMPTable4Columns

			INTO
				@AtrributeString

			WHILE @@FETCH_STATUS = 0
				BEGIN
					DECLARE @ColName	NVARCHAR(100)
					DECLARE @TableMod	VARCHAR(500)
					SET @intAttributeCounter = @intAttributeCounter + 1
					--ACA HAGO EL SPLIT DE CADA TRIADA PARA ARMAR LAS COLUMNAS
					SELECT
						@AttributeID = dbo.fnSplitPosition(@AtrributeString, '/*\', 1)

					SELECT
						@AttributeName = dbo.fnSplitPosition(@AtrributeString, '/*\', 2)


					--COLUMNA 1
					SET @ColName = 'ID de Atributo ' + CONVERT(VARCHAR,@intAttributeCounter)
					SET @TableMod = 'ALTER TABLE #tmpItems2Publicate ADD ['+ CAST(@ColName AS NVARCHAR(2000)) +   '] NVARCHAR(2000) '
					EXEC (@TableMod)
					SET @TableMod = 'UPDATE #tmpItems2Publicate SET ['+ CAST(@ColName AS NVARCHAR(2000)) +   '] = ' + '''' + @AttributeID + ''''
					EXEC (@TableMod)


					--COLUMNA 2
					SET @ColName = 'Nombre de Atributo '  + CONVERT(VARCHAR,@intAttributeCounter)
					SET @TableMod = 'ALTER TABLE #tmpItems2Publicate ADD ['+ CAST(@ColName AS NVARCHAR(2000)) +   '] NVARCHAR(2000) '
					EXEC (@TableMod)
					SET @TableMod = 'UPDATE #tmpItems2Publicate SET ['+ CAST(@ColName AS NVARCHAR(2000)) +   '] = ' + '''' + @AttributeName + ''''
					EXEC (@TableMod)

					--COLUMNA 3
					SET @ColName = 'Valor de Atributo '  + CONVERT(VARCHAR,@intAttributeCounter)
					SET @TableMod = 'ALTER TABLE #tmpItems2Publicate ADD ['+ CAST(@ColName AS NVARCHAR(2000)) +   '] NVARCHAR(2000) '
					EXEC (@TableMod)
					SET @TableMod = 'UPDATE #tmpItems2Publicate SET ['+ CAST(@ColName AS NVARCHAR(2000)) +   '] = ' + '''' + '' + ''''
					EXEC (@TableMod)

					FETCH NEXT FROM Cursor_ModTMPTable4Columns
					INTO
						@AtrributeString
				END
			CLOSE Cursor_ModTMPTable4Columns
			DEALLOCATE Cursor_ModTMPTable4Columns
		-- -------------------------------------------------------------------

		SELECT * FROM #tmpItems2Publicate

	END
GO

CREATE PROCEDURE spMercadoLibre_GetMLNickNameByMLO_ID
(
	@comp_id	INT,
	@mlo_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------
		-- TESTING
		-- ----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlo_id		INT
			SELECT
				@comp_id	= 1,
				@mlo_id		= 132
		*/
		-- ----------------------------------------------
		SELECT
			tmlud.MLUser_Id,
			tmlud.nickname
			FROM tbMercadoLibre_UsersData			tmlud
			INNER JOIN tbMercadoLibre_ordersHeader	tmloh
			ON tmloh.MLUser_Id		= tmlud.MLUser_Id
			WHERE	tmloh.comp_id	= @comp_id		AND
					tmloh.mlo_id	= @mlo_id

	END


GO

CREATE PROCEDURE [dbo].[spMercadoLibre_getOrdersOK4SaleOrder]
(
	@comp_id	INT,
	@mls_id	    INT,
	@mlo_id		BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------
		-- TESTING
		-- ------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlod_id	INT
			SELECT
				@comp_id	= 1,
				@mlod_id	= 1
		*/
		-- ------------------------------------------

		BEGIN TRY
			-- Pone como CANCELADAS las ordenes que se generaron antes de IMPORTAR una publicacion
			-- ya que no deben estar como pedidos en el sistema

			IF EXISTS(
						SELECT TOP 1 1
							FROM		tbMercadoLibre_ordersHeader		tmloh 		WITH (NOLOCK)
							INNER JOIN 	tbMercadoLibre_ordersDetail		tmlod		WITH (NOLOCK)
								ON	tmloh.comp_id = tmlod.comp_id		AND
									tmloh.mlo_id  = tmlod.mlo_id
							INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
								ON	tmlip.comp_id = tmlod.comp_id		AND
									tmlip.mlp_id  = tmlod.mlp_id
							INNER JOIN tbMercadoLibre_Stores			tmls		WITH (NOLOCK)
								ON	tmls.comp_id  = tmlip.comp_id		AND
									tmls.mls_id   = tmlip.mls_id
							WHERE	tmlod.comp_id = @comp_id									AND
									tmloh.mlo_isSaleOrderGenerated	= 'False'					AND
									tmlip.mlp_creationDate		    > tmloh.ML_date_created		AND
									( @mls_id = -1 OR tmlip.mls_id  = @mls_id )					AND
									tmls.mls_disabled				= 'False'					AND
									tmloh.mlo_isCancelled			= 'False'
				     )

				BEGIN
					UPDATE tbMercadoLibre_ordersHeader		WITH (ROWLOCK)
						SET tbMercadoLibre_ordersHeader.mlo_isCancelled = 'True'
						FROM tbMercadoLibre_ordersDetail			tmlod		WITH (NOLOCK)
						INNER JOIN tbMercadoLibre_ordersHeader		tmloh		--WITH (NOLOCK)
							ON	tmloh.comp_id = tmlod.comp_id	AND
								tmloh.mlo_id  = tmlod.mlo_id
						INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
							ON	tmlip.comp_id = tmlod.comp_id		AND
								tmlip.mlp_id  = tmlod.mlp_id
						INNER JOIN tbMercadoLibre_Stores			tmls		WITH (NOLOCK)
							ON	tmls.comp_id  = tmlip.comp_id		AND
								tmls.mls_id   = tmlip.mls_id
						WHERE	tmlod.comp_id = @comp_id									AND
								tmloh.mlo_isSaleOrderGenerated	= 'False'					AND
								tmlip.mlp_creationDate		    > tmloh.ML_date_created		AND
								( @mls_id = -1 OR tmlip.mls_id  = @mls_id )					AND
								tmls.mls_disabled				= 'False'					AND
								tmloh.mlo_isCancelled			= 'False'
				END

		END TRY
		BEGIN CATCH
		END CATCH

		-- ------------------------------------------------------------------------------
		-- MOS 05-2022
		-- ------------------------------------------------------------------------------
		DECLARE @datFromDate DATETIME = DATEADD(day,-2,GETDATE())	-- MOS 05-2022, para que no busque al pedo pedidos q nunca van a cargarse FAS Motos.
																	-- si algun FORRO desconecta la tienda , la vuelve a conectar dias mas tarde y quiere q se carguen los pedidos
																	-- cambiarle solo a EL donde dice days x week x dos dias y volver a dejarlo como estaba
		IF DATEPART(hour,GETDATE()) BETWEEN 1 AND 8 AND	-- una vez x dia mira todos los de la ultima semana.
		   @mlo_id = -1
			BEGIN
				DECLARE @bitCanIDoIt AS BIT = 'False'
				SET		@bitCanIDoIt = 'False'
				EXEC spSystem_LastExecutionControl_CanDoIt -1,
														   -1,
													   702904,
														 1440,	-- MOS 02-2022, era cada 10 y lo pase a cada 20.         cada 10 minutos hace el recalculo.!
												 @bitCanIDoIt OUTPUT


				IF @bitCanIDoIt = 'True'
					BEGIN
						SET @datFromDate  = DATEADD(week,-2,GETDATE())
					END
			END
		IF @mlo_id > 0	-- Si es una ORDEN en particular dejo hasta 5 semanas
			BEGIN
				SET @datFromDate  = DATEADD(week,-5,GETDATE())
			END
		SET @datFromDate = dbo.fnGetEnd_or_BeginOfDate(@datFromDate,'False')
		-- ------------------------------------------------------------------------------





		SELECT
			tmloh.comp_id,
			tmloh.mlo_id,
			tmloh.MLorder_id,
			tmloh.mlo_lastJSON,
			tmls.bra_id,
			tmls.mls_accessToken,
			tmloh.ML_id,
			tmloh.ML_date_created,
			tmloh.ML_last_updated,
			1			AS orderClassPart
			FROM tbMercadoLibre_ordersHeader			tmloh 		WITH (NOLOCK)
			INNER JOIN 	tbMercadoLibre_ordersDetail		tmlod		WITH (NOLOCK)
				ON	tmloh.comp_id = tmlod.comp_id		AND
					tmloh.mlo_id  = tmlod.mlo_id
			INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
				ON	tmlip.comp_id = tmlod.comp_id		AND
					tmlip.mlp_id  = tmlod.mlp_id
			INNER JOIN tbMercadoLibre_Stores			tmls		WITH (NOLOCK)
				ON	tmls.comp_id  = tmlip.comp_id		AND
					tmls.mls_id   = tmlip.mls_id
			WHERE	tmloh.comp_id = @comp_id									AND
					tmloh.mlo_isSaleOrderGenerated	= 'False'					AND
					tmloh.mlo_isSaleOrderEmmited    = 'False'					AND	-- MOS 06-01-2021
					tmloh.mlo_iscollected			= 'False'					AND	-- MOS 06-01-2021
					tmloh.mlo_isCancelled			= 'False'					AND
					tmloh.mlo_status				= 'paid'					AND
					tmlip.mlp_creationDate		   <= tmloh.ML_date_created		AND
					( @mls_id = -1 OR tmlip.mls_id  = @mls_id )					AND
					( @mlo_id = -1 OR tmloh.mlo_id  = @mlo_id)					AND -- MOS 05-2022: Para que solo traiga la orden informada y no trate de levantar todas cada vez que llega una nueva orden.  Todas lo hace solo cuando se procesa el 11 !!!
					tmls.mls_disabled				= 'False'					AND
					tmloh.ML_date_created > @datFromDate	-- MOS 05-2022: Para que no busque siempre para atras ordenes que NO se van a cargar nunca o que ya se debieron cargar


		UNION ALL

		-- Ordenes de Items SIN PUBLICACION
		SELECT
			tmloh.comp_id,
			tmloh.mlo_id,
			tmloh.MLorder_id,
			tmloh.mlo_lastJSON,
			tmls.bra_id,
			tmls.mls_accessToken,
			tmloh.ML_id,
			tmloh.ML_date_created,
			tmloh.ML_last_updated,
			2		AS orderClassPart
			FROM		tbMercadoLibre_ordersHeader		tmloh 		WITH (NOLOCK)
			INNER JOIN 	tbMercadoLibre_ordersDetail		tmlod		WITH (NOLOCK)
				ON	tmloh.comp_id = tmlod.comp_id	AND
					tmloh.mlo_id  = tmlod.mlo_id
			INNER JOIN tbMercadoLibre_Stores			tmls		WITH (NOLOCK)
				ON	tmls.comp_id  = tmloh.comp_id		AND
					tmls.mls_id   = tmloh.mls_id
			WHERE	tmloh.comp_id = @comp_id									AND
					tmls.mls_disabled				= 'False'					AND
					tmls.mls_orderWithNoPublicatedItem_Enabled = 'True'			AND
					tmloh.mlo_isSaleOrderGenerated	= 'False'					AND
					tmloh.mlo_isSaleOrderEmmited    = 'False'					AND	-- MOS 06-01-2021
					tmloh.mlo_iscollected			= 'False'					AND	-- MOS 06-01-2021
					tmloh.mlo_status				= 'paid'					AND
					tmloh.mlo_isCancelled			= 'False'					AND
					( @mls_id = -1 OR tmloh.mls_id  = @mls_id )					AND
					( @mlo_id = -1 OR tmloh.mlo_id  = @mlo_id)					AND -- MOS 05-2022: Para que solo traiga la orden informada y no trate de levantar todas cada vez que llega una nueva orden.  Todas lo hace solo cuando se procesa el 11 !!!
					(
						tmlod.item_id = tmls.mls_orderWithNoPublicatedItem_itemId1
							OR
						tmlod.item_id = tmls.mls_orderWithNoPublicatedItem_itemId2
					)															AND
					tmloh.ML_date_created > @datFromDate	-- MOS 05-2022: Para que no busque siempre para atras ordenes que NO se van a cargar nunca o que ya se debieron cargar




	END
GO

