CREATE PROCEDURE [dbo].[spMercadoLibre_hasMercadoLibreStoresEnabled]
	-- Add the parameters for the stored procedure here
	@comp_id AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @bolHasMercadoLibreStores AS BIT = 'False'
	SELECT  @bolHasMercadoLibreStores = 'True'
		FROM tbMercadoLibre_Stores tmls  WITH (NOLOCK)
		WHERE	tmls.comp_id		= @comp_id AND
				tmls.mls_disabled	='False'

	DECLARE @boldisableProcessQueueLaunch AS BIT = 'False'
	SELECT  @boldisableProcessQueueLaunch = 'True'
		FROM tbMercadoLibre_Stores tmls  WITH (NOLOCK)
		WHERE	tmls.comp_id						=	@comp_id AND
				tmls.mls_disabled					=	'False'	AND
				tmls.mls_disableProcessQueueLaunch	=	'True'


	SELECT	@bolHasMercadoLibreStores AS hasMercadoLibreStores,
			@boldisableProcessQueueLaunch AS disableProcessQueueLaunch



END
GO


