-- **wefkwefkl987** Si el pedido es de MercadoLibre se calculan los campos: sod_MLCost, 	sod_MECost, sod_MPCost
CREATE PROCEDURE [dbo].[spMercadoLibre_insertSaleOrder]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@mlo_id				INT,
	@guid				UNIQUEIDENTIFIER,
	@strTNT				NVARCHAR(10),
	@strDocumentNumber	NVARCHAR(20),
	@MLshipping_id		NVARCHAR(50),
	@GUID4QUEUEMODE		UNIQUEIDENTIFIER
)
AS


BEGIN


	-- -------------------------------------------------------------------------------
	-- Testing ARG
	-- -------------------------------------------------------------------------------
	/*
	DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@mlo_id				INT,
			@guid				UNIQUEIDENTIFIER,
			@strTNT				NVARCHAR(10),
			@strDocumentNumber	NVARCHAR(20),
			@MLshipping_id		NVARCHAR(50),
			@GUID4QUEUEMODE		UNIQUEIDENTIFIER

	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@bra_id				= 1,
			@mlo_id				= 93225,
			@guid				= '2e202799-7b8b-4ee7-8e74-e499c43b5d6b',
			@strTNT				= 'DNI',
			@strDocumentNumber	= '29910010',
			@MLshipping_id		= '27652977538',
			GUID4QUEUEMODE		= newID()
	 */
	 -------------------------------------------------------------------------------


	-- -------------------------------------------------------------------------------
	-- Testing CHILE
	-- -------------------------------------------------------------------------------
	/*
	DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@mlo_id				INT,
			@guid				UNIQUEIDENTIFIER,
			@strTNT				NVARCHAR(10),
			@strDocumentNumber	NVARCHAR(20),
			@MLshipping_id		NVARCHAR(50),
			@GUID4QUEUEMODE		UNIQUEIDENTIFIER

	SELECT	@comp_id			= 18,
			@lang_id			= 2,
			@bra_id				= 27,
			@mlo_id				= 1,
			@guid				= '2e202799-7b8b-4ee7-8e74-e499c43b5d6b',
			@strTNT				= '',
			@strDocumentNumber	= '',
			@MLshipping_id		= '',
			@GUID4QUEUEMODE		= NEWID()
	 */
	 -------------------------------------------------------------------------------












	-- --------------------------------------------------------------------------------------------------------
	-- Evitar Bloqueo de Interprocesos - CONSULTAR a Aquitecto
	-- --------------------------------------------------------------------------------------------------------
	SET LOCK_TIMEOUT 1000			-- 25 segundos
	SET DEADLOCK_PRIORITY HIGH		-- Tomar en cuenta para ULTIMA Opcion de Eliminación
	-- --------------------------------------------------------------------------------------------------------

	SET NOCOUNT ON


	DECLARE @strInternalAnnotation AS VARCHAR(100) = ''

	DECLARE @storg_id		AS INT
	DECLARE @stor_id		AS INT
	DECLARE @item_id		AS INT
	DECLARE @prli_id		AS INT
	DECLARE @item_qty		AS DECIMAL(18,5)
	DECLARE @sdlmt_id		AS INT
	DECLARE @tis_itemDesc   AS NVARCHAR(300)
	DECLARE @tis_itemDeta   AS NVARCHAR(300)
	DECLARE @curr_id		AS INT
	DECLARE @tis_price		AS DECIMAL(19,4)
	DECLARE @tis_priority	AS INT
	DECLARE @user_id		AS INT
	DECLARE @user_id4MLT	AS INT
	DECLARE @rv				AS INT
	SET		@rv		= -1
	DECLARE @wsID			AS UNIQUEIDENTIFIER
	SET		@wsID	= NEWID()
	DECLARE	@MLUser_Id		AS BIGINT
	DECLARE @strCustomerEMail
							AS NVARCHAR(300)

	DECLARE	@getdate		AS DATETIME
	SET		@getdate = GETDATE()
	DECLARE @cust_id_A		AS INT
	DECLARE @cust_id_B		AS INT
	DECLARE
			@intSM_id			INT,
			@intST_id			INT,
			@intDISC_id			INT,
			@intDL_Id			INT,
			@curr_id_cust		INT
	DECLARE @decTotalOfOrder    DECIMAL(30,6)				   = 0
	DECLARE @decTotalGastosDeEnvioFacturables AS DECIMAL(30,6) = 0
	DECLARE @decTotalOfCouponDiscounts		  AS DECIMAL(30,6) = 0


	DECLARE @tmpMLOProcessed TABLE (mlo_id INT PRIMARY KEY)
	DECLARE @intMLStoreOfOrder AS INT = -1	-- TP3d: x q si tenian un carrito con items de DOS tiendas, cargaba el pedido todo junto o abajo sumaba los precios en el control de precios...


	-- ----------------------------------------------------------------------------------
	-- MOS 02-2022  **6541ewrwefrwe**wefwe
	-- POr los NABOS de MF, por las dudas busco el ID del USUARIO
	-- ----------------------------------------------------------------------------------
	DECLARE @strIdentificationType		AS NVARCHAR(30),
			@strIdentificationNumber	AS NVARCHAR(30)
	SELECT	@strIdentificationType			=	CASE
													WHEN dbo.fnStrAllTrim(ISNULL(tmlud.billing_DOC_TYPE,'')) <> ''		THEN  dbo.fnStrAllTrim(ISNULL(tmlud.billing_DOC_TYPE,''))
													WHEN dbo.fnStrAllTrim(ISNULL(tmlud.identificationType,'')) <> ''	THEN  dbo.fnStrAllTrim(ISNULL(tmlud.identificationType,''))
													WHEN dbo.fnStrAllTrim(ISNULL(tmloh.identificationType,'')) <> ''	THEN  dbo.fnStrAllTrim(ISNULL(tmloh.identificationType,''))
													ELSE ''
												END,
			@strIdentificationNumber		=	CASE
													WHEN dbo.fnStrAllTrim(ISNULL(tmlud.billing_DOC_NUMBER,'')) <> ''	THEN  dbo.fnStrAllTrim(ISNULL(tmlud.billing_DOC_NUMBER,''))
													WHEN dbo.fnStrAllTrim(ISNULL(tmlud.identificationNumber,'')) <> ''	THEN  dbo.fnStrAllTrim(ISNULL(tmlud.identificationNumber,''))
													WHEN dbo.fnStrAllTrim(ISNULL(tmloh.identificationNumber,'')) <> ''	THEN  dbo.fnStrAllTrim(ISNULL(tmloh.identificationNumber,''))
													ELSE ''
												END ,
			@intMLStoreOfOrder				=	tmloh.mls_id		-- Para traer TODOS los de un posible carrito pero de la MISMA tienda de esta orden!!!
		FROM tbMercadoLibre_ordersHeader   AS tmloh		WITH (NOLOCK)
		LEFT JOIN tbMercadoLibre_UsersData AS tmlud		WITH (NOLOCK)
			ON tmlud.MLUser_Id				= tmloh.MLUser_Id
		WHERE	tmloh.comp_id	= @comp_id AND
				tmloh.mlo_id	= @mlo_id
	-- ----------------------------------------------------------------------------------




	-- ----------------------------------------------------------------------------------
	-- Control x las dudas . . .   IDEM en **65654fewefwlihweflhwe
	-- ----------------------------------------------------------------------------------
	IF
	EXISTS(
				SELECT TOP 1 1
					FROM tbMercadoLibre_ordersHeader hh	WITH (NOLOCK)
					WHERE	hh.comp_id	= @comp_id	AND
							hh.mlo_id	= @mlo_id	AND
							hh.mlo_isSaleOrderGenerated = 'True'
			)
		OR
	EXISTS(
				SELECT TOP 1  1
					FROM tbSaleOrderDetail tsod    WITH (NOLOCK)
					WHERE	tsod.comp_id	= @comp_id AND
							tsod.mlo_id		= @mlo_id
			)
		OR
	EXISTS(
				SELECT TOP 1  1
				FROM tbSaleOrderHeader  tsod    WITH (NOLOCK)
					WHERE	tsod.comp_id	= @comp_id AND
							tsod.mlo_id		= @mlo_id
		)
		OR
	EXISTS(
				SELECT TOP 1  1
				FROM tbItemTransactions AS tit  WITH (NOLOCK)
					WHERE	tit.comp_id	= @comp_id AND
							tit.mlo_id	= @mlo_id
	)
		OR
	EXISTS(
				SELECT TOP 1  1
				FROM tbCommercialTransactions  AS tit  WITH (NOLOCK)
					WHERE	tit.comp_id	= @comp_id AND
							tit.mlo_id	= @mlo_id
			)
		BEGIN

			-- Marca la orden como PROCESADA para que no se vuelva a procesar.
			UPDATE tbMercadoLibre_ordersHeader		WITH (ROWLOCK)
				SET	mlo_isSaleOrderGenerated = 1
				WHERE	comp_id = @comp_id	AND
						mlo_id	= @mlo_id   --AND			-- MOS 02-2023 x colucci que se generaba una orden sin MLO_ID asignado.   (Por las dudas)
						--mlo_isSaleOrderGenerated = 0



			UPDATE tbMercadoLibre_ordersDetail		WITH (ROWLOCK)
				SET	mlo_is4AvailableStock = 0
				WHERE	comp_id = @comp_id AND
						mlo_id	= @mlo_id  AND
						mlo_is4AvailableStock = 1

			SELECT	-1						[code],
					'El pedido YA fue Generado'	[error_description]
			RETURN
		END
	-- ----------------------------------------------------------------------------------



	-- ----------------------------------------------------------------------------------
	-- MOS 05-2021
	-- X LAS DUDAS Q LOS HDRMP DE MELI MANDEN 1000 VECES LA MISMA ORDEN Y LO ATRAPEN DOS HILOS DIFERENTES
	-- Y QUEDE DUPLICADA LA ORDEN, NO CARGA EL PEDIDO.
	-- NO QUIERO CAMBIAR EL ISOLATION-LEVEL DE LA INSERCION DE LA ORDEN PARA EVITAR INTERBLOQUEOS.
	-- ----------------------------------------------------------------------------------
	DECLARE @mlOrderID AS BIGINT
	SELECT  @mlOrderID = tmloh.MLorder_id
		FROM tbMercadoLibre_ordersHeader AS tmloh	WITH (NOLOCK)
		WHERE	tmloh.comp_id	= @comp_id AND
				tmloh.mlo_id	= @mlo_id
	SELECT	1		-- NO PONER TOP !!!!!!!!!
		FROM tbMercadoLibre_ordersHeader AS tmloh	WITH (NOLOCK)
		WHERE	tmloh.comp_id		= @comp_id AND
				tmloh.MLorder_id	= @mlOrderID

	IF @@ROWCOUNT = 2
		BEGIN
			SELECT	-1						[code],
					'Orden DUPLICADA, no se Ingresará el Pedido.'	[error_description]
			RETURN
		END
	-- ----------------------------------------------------------------------------------








	-- --------------------------------------------------------------------------
	-- Datos para Facturacion de Cargos de Envio
	-- --------------------------------------------------------------------------
	DECLARE @bitforceSO4Commercial		AS BIT = 'False'
	DECLARE @mls_id						AS INT
	DECLARE @mlp_PublicationID			AS NVARCHAR(30)
	SELECT  @mls_id					= ISNULL(tmlip.mls_id,tmloh.mls_id),
			@mlp_PublicationID		= ISNULL(tmlip.mlp_publicationID,''),
			@bitforceSO4Commercial	= ISNULL(tmlip.mlp_forceSO4Commercial,'False')
		FROM tbMercadoLibre_ordersDetail			ll		WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_ordersHeader		tmloh	WITH (NOLOCK)
			ON	tmloh.comp_id	= ll.comp_id	AND
				tmloh.mlo_id	= ll.mlo_id
		LEFT JOIN tbMercadoLibre_ItemsPublicados	tmlip	WITH (NOLOCK)
			ON	tmlip.comp_id	= ll.comp_id	AND
				tmlip.mlp_id	= ll.mlp_id
		WHERE	ll.comp_id		= @comp_id		AND
				ll.mlo_id		= @mlo_id

	DECLARE @item_id4UserPayDelivery	AS INT = NULL
	DECLARE @cust_id_4Full4Countries	AS INT = NULL
	DECLARE @st_id4Full4Countries		AS INT = NULL
	DECLARE @df_id4Full4Countries		AS INT = NULL
	SELECT  @item_id4UserPayDelivery	= tmls.item_id4UserPayDelivery,
			@cust_id_4Full4Countries	= tmls.cust_id_4Full4Countries,
			@st_id4Full4Countries		= tmls.st_id4Full4Countries,
			@df_id4Full4Countries		= tmls.df_id4Full4Countries
		FROM tbMercadoLibre_Stores					tmls	WITH (NOLOCK)
		WHERE	tmls.comp_id	= @comp_id			AND
				tmls.mls_id		= @mls_id

	DECLARE @item_id4UserPayDelivery_TAX_Id AS INT = -1
	SELECT TOP 1 @item_id4UserPayDelivery_TAX_Id = tit.tax_id
		FROM tbItemTaxes tit		WITH (NOLOCK)
		WHERE tit.comp_id = @comp_id AND tit.item_id = @item_id4UserPayDelivery

	DECLARE @item_id4UserPayDelivery_TAX_Percentage AS DECIMAL(19,4) = 0
	SELECT  @item_id4UserPayDelivery_TAX_Percentage = ttn.tax_percentage
		FROM tbTaxName ttn		WITH (NOLOCK)
		WHERE	ttn.comp_id = @comp_id AND
				ttn.tax_id	= @item_id4UserPayDelivery_TAX_Id
	-- --------------------------------------------------------------------------



	CREATE TABLE #tmpTaxes (item_id INT PRIMARY KEY, ivaTax  DECIMAL(19,4), InternalTax DECIMAL(19,4))


	BEGIN TRY

		DECLARE @ret_ErrorDescription	VARCHAR(1000)
		SET		@ret_ErrorDescription	= ''

		DECLARE @return_value		AS INT
		DECLARE @errormessage		AS NVARCHAR(500)
		DECLARE @intItemsInserted	AS INT
		SET		@intItemsInserted	= 0
		DECLARE @intMLOId			AS BIGINT

		DECLARE @str2MLorder_id		AS NVARCHAR(50)
		DECLARE @str2NickName		AS NVARCHAR(100)
		DECLARE @bitHasDeliveryChargesGenerated AS BIT = 'False'
		DECLARE @mls_putSaleOrderwithTotalPrice AS BIT = 'False'
		DECLARE @ML_logistic_type AS VARCHAR(200) = ''
		DECLARE @MLShippmentColectaDayTime AS DATETIME = GETDATE()
		DECLARE @curMLshippingID AS BIGINT
		DECLARE @curCupon_amount AS DECIMAL(30,6) = 0
		DECLARE @mls_OrdersWithDiscountCouponIncludeInPriceV2 AS BIT = 'False'
	-- ------------------------------------------------------------------------------------------------------
	-- Inserta datos en tbTempItemStock
	-- ------------------------------------------------------------------------------------------------------







		DECLARE curItems CURSOR LOCAL FAST_FORWARD FOR
		SELECT	DISTINCT   -- Por las dudas por un error que se vio en Samudio que duplicaba el item en el mismo pedido.  30-11-2018	** lkndwql98347lkn**
				tmlod.item_id,
				CASE		-- MOS 08-10-2019 x DENSO de Colucci que dice que NO le gusta que se le carguen con la descripcion de la publi de meli.
							-- Si algun otro FORRO rompe las pelotas con que ahora lo quiere, ponerlo conf en la tienda.
					WHEN (ti.item_id = tmls.mls_orderWithNoPublicatedItem_itemId1	AND tmls.mls_orderWithNoPublicatedItem_itemId1 IS NOT NULL )
							OR
						 (ti.item_id = tmls.mls_orderWithNoPublicatedItem_itemId2	AND tmls.mls_orderWithNoPublicatedItem_itemId2 IS NOT NULL )
																							THEN	ISNULL(tmlod.mlo_title,ISNULL(ti.item_desc,''))
					WHEN ISNULL(ti.item_desc,'') <> ''										THEN	ti.item_desc
					ELSE																			ISNULL(tmlod.mlo_title,ISNULL(ti.item_desc,''))
				END,
				ISNULL(ti.item_detail,''),
				tmlod.mlo_quantity,
				CASE
					WHEN tmloh.mlo_ismshops = 'True' AND tmlip.prli_id4MercadoShop IS NOT NULL	THEN tmlip.prli_id4MercadoShop	-- MOS 01-2022 x Arg 14756
					WHEN tmlip.prli_id IS NOT NULL												THEN tmlip.prli_id
					ELSE																			 tmls.prli_id
				END,

				CASE		--  tmlod.mlo_unit_price    -->>													 -- MOS 06-2024: Ver si no hay que DIVIDIR mlo_cupon_amount por los items!!!
					WHEN tmls.mls_OrdersWithDiscountCouponIncludeInPriceV2	= 'True' THEN tmlod.mlo_unit_price - tmloh.mlo_cupon_amount	-- 06-2024: para que cargue el precio del item MENOS el descuento del cupon.
					-- MOS 06-2024: No funcionaba mas de esta manera. WHEN tmls.mls_OrdersWithDiscountCouponIncludeInPrice	= 'True' THEN tmlod.mlo_unit_price - tmloh.mlo_cupon_amount	-- MOS 04-2023  x ADMA **wqlkn142231lklnk
					ELSE tmlod.mlo_unit_price
				END,

				CASE									-- MOS 12-2022
					WHEN (tmlos.MLfulfilled = 'True' OR tmlos.ML_logistic_type = 'fulfillment')  AND tmls.stor_id4FulFillment IS NOT NULL
																								THEN tmls.stor_id4FulFillment		-- MOS 11-10-2019: x Colucci Si la ORDEN se cargo como FulFillment y esta ese depo definido en la tienda, lo pongo ahí
					WHEN tmlod.stor_id IS NOT NULL												THEN tmlod.stor_id
					ELSE																			 tmls.stor_id
				END,
				ISNULL(tmlos.ML_logistic_type,'')																		[ML_logistic_type],	-- MOS 12-2022 para que NO tome grupos si es full
				CASE	-- MOS 05-2024: Para poder hacer q un pedido de FLEX se carge en OTRA sucursal
					WHEN tmlos.ML_logistic_type = 'self_service'	AND tmls.bra_id4Flex IS NOT NULL THEN tmls.bra_id4Flex
					WHEN tmlos.ML_logistic_type = 'self_services'	AND tmls.bra_id4Flex IS NOT NULL THEN tmls.bra_id4Flex
					ELSE tmls.bra_id
				END								[bra_id],
				ISNULL(tmls.curr_id,1)			[curr_id],  --1,   MOS 01-2023 x Chile   Antes estaba en Duro con 1, ahora pone la Moneda de la TIENDA ! ! !
				tmls.[user_id],
				tmloh.MLUser_Id,
				tmls.cust_id_4newCustomersA,
				tmls.cust_id_4newCustomersB,
				tmls.sm_id,
				CASE
					WHEN tmlip.st_id IS NOT NULL THEN tmlip.st_id
					ELSE tmls.st_id
				END,
				CASE
					WHEN tmlip.disc_id IS NOT NULL THEN tmlip.disc_id
					ELSE tmls.disc_id
				END,
				--Contenidos
				--→Mercado Envíos (drop_off)
				--→Mercado Envíos Places (xd_drop_off)
				--→Mercado Envíos Colecta (cross_docking)
				--→Mercado Envíos Flex (self_services)				OK
				--→Mercado Envíos Full (fulfillment)				OK
				CASE

					WHEN tmlos.MLshipping_mode	= 'me1'				THEN tmls.dl_id4ME1
					WHEN tmlos.ML_logistic_type = 'fulfillment'		AND
						 tmls.dl_id4Full IS NOT NULL 				THEN tmls.dl_id4Full

					-- Estos PELOTUDOS lo mandan como quieren
					WHEN tmlos.ML_logistic_type = 'self_service'	AND
						 tmls.dl_id4Flex IS NOT NULL					THEN tmls.dl_id4Flex
					WHEN tmlos.ML_logistic_type = 'self_services'	AND
						 tmls.dl_id4Flex IS NOT NULL					THEN tmls.dl_id4Flex

					-- -------------------------------------------------
					-- Si es MercadoEnvios
					-- -------------------------------------------------
					WHEN tmlos.ML_logistic_type = 'drop_off'			AND
						 tmls.dl_id4MercadoEnvios IS NOT NULL			THEN tmls.dl_id4MercadoEnvios

					WHEN tmlos.ML_logistic_type = 'xd_drop_off'		AND
						 tmls.dl_id4MercadoEnviosPlaces IS NOT NULL		THEN tmls.dl_id4MercadoEnviosPlaces		--Places
					WHEN tmlos.ML_logistic_type = 'cross_docking'	AND
						 tmls.dl_id4MercadoEnviosColecta IS NOT NULL	THEN tmls.dl_id4MercadoEnviosColecta	--Colecta

					-- x Compatibilidad con Conf Anteriores
					WHEN tmlos.ML_logistic_type = 'xd_drop_off'			AND
						 tmls.dl_id4MercadoEnvios IS NOT NULL			THEN tmls.dl_id4MercadoEnvios
					WHEN tmlos.ML_logistic_type = 'cross_docking'			AND
						 tmls.dl_id4MercadoEnvios IS NOT NULL			THEN tmls.dl_id4MercadoEnvios
					-- -------------------------------------------------

					WHEN tmloh.MLShippingID IS NULL					AND
						 tmls.dl_id4Local IS NOT NULL					THEN tmls.dl_id4Local
					--WHEN tmlos.MLlogistic_type	= 'shipping'			THEN tmls.dl_id
					WHEN tmlip.dl_id IS NOT NULL						THEN tmlip.dl_id
					ELSE tmls.dl_id
				END	,
				tmlod.mlo_id	,
				convert(nvarchar(50),tmloh.MLorder_id),
				ISNULL(tmlud.nickname,'**')		,
				ISNULL(tmls.mls_putSaleOrderwithTotalPrice,'False')	[mls_putSaleOrderwithTotalPrice]	,
				tmlip.storg_id	,
				tmlos.MLShippmentColectaDayTime		,
				ISNULL(tmlos.MLshippingID,0)						[MLshippingID],
				CASE		--  tmlod.mlo_unit_price    -->>
					WHEN tmls.mls_OrdersWithDiscountCouponIncludeInPriceV2 = 'True' THEN  tmloh.mlo_cupon_amount	-- MOS 06-2024: porque sino abajo ajustaba el total al total del pedido y no aplicaba el descuento.
					ELSE 0
				END	,
				ISNULL(tmls.mls_OrdersWithDiscountCouponIncludeInPriceV2,'False')	[mls_OrdersWithDiscountCouponIncludeInPriceV2]
			FROM tbMercadoLibre_ordersDetail			tmlod		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ordersHeader		tmloh		WITH (NOLOCK)
				ON	tmloh.comp_id	= tmlod.comp_id		AND
					tmloh.mlo_id	= tmlod.mlo_id
			LEFT JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
				ON	tmlip.comp_id	= tmlod.comp_id		AND
					tmlip.mlp_id	= tmlod.mlp_id
			INNER JOIN tbItem							ti			WITH (NOLOCK)
				ON	ti.comp_id		= tmlod.comp_id		AND
					ti.item_id		= tmlod.item_id
			INNER JOIN tbMercadoLibre_Stores			tmls		WITH (NOLOCK)
				ON	tmls.comp_id	= tmloh.comp_id		AND
					tmls.mls_id		= tmloh.mls_id
			LEFT JOIN tbMercadoLibre_UsersData tmlud				WITH (NOLOCK)
				ON tmlud.MLUser_Id = tmloh.MLUser_Id
			LEFT JOIN tbMercadoLibre_ordersShipping		tmlos		WITH (NOLOCK)
				ON	tmlos.comp_id	= tmloh.comp_id		AND
					tmlos.mlo_id	= tmloh.mlo_id
			WHERE	tmlod.comp_id	= @comp_id			AND
					(
						tmloh.mlo_id		= @mlo_id
							OR
						tmloh.MLShippingID	= @MLshipping_id
					)									AND
					tmloh.mlo_isSaleOrderGenerated = 0	AND
					tmloh.mlo_status='paid'				AND
					(@intMLStoreOfOrder = -1 OR tmloh.mls_id = @intMLStoreOfOrder )	-- MOS 04-2023 x TP3D (18711), tenian un pedido de carrito de dos tiendas diferentes y se les cargaba en el mismo pedido.


		OPEN		curItems
		FETCH curItems INTO
							@item_id ,
							@tis_itemDesc,
							@tis_itemDeta,
							@item_qty,
							@prli_id,
							@tis_price,
							@stor_id,
							@ML_logistic_type,
							@bra_id,
							@curr_id, -- MOS 01-2023 se cambió a la moneda de la TIENDA  -- PESOS, va en duro pero deberia estar en la TIENDA
							@user_id,
							@MLUser_Id,
							@cust_id_A,
							@cust_id_B,
							@intSM_id,
							@intST_id,
							@intDISC_id,
							@intDL_Id,
							@intMLOId,
							@str2MLorder_id,
							@str2NickName,
							@mls_putSaleOrderwithTotalPrice	,
							@storg_id,
							@MLShippmentColectaDayTime,
							@curMLshippingID,
							@curCupon_amount,
							@mls_OrdersWithDiscountCouponIncludeInPriceV2

		WHILE @@FETCH_STATUS = 0
			BEGIN


				---- ----------------------------------------------------------------------------------
				---- Control x las dudas . . .   IDEM en **65654fewefwlihweflhwe
				---- ----------------------------------------------------------------------------------
				--IF
				--EXISTS(
				--			SELECT TOP 1 1
				--				FROM tbMercadoLibre_ordersHeader hh	WITH (NOLOCK)
				--				WHERE	hh.comp_id	= @comp_id	AND
				--						hh.mlo_id	= @intMLOId	AND
				--						hh.mlo_isSaleOrderGenerated = 'True'
				--		)
				--	OR
				--EXISTS(
				--			SELECT TOP 1  1
				--				FROM tbSaleOrderDetail tsod    WITH (NOLOCK)
				--				WHERE	tsod.comp_id	= @comp_id AND
				--						tsod.mlo_id		= @intMLOId
				--		)
				--	OR
				--EXISTS(
				--			SELECT TOP 1  1
				--			FROM tbSaleOrderHeader  tsod    WITH (NOLOCK)
				--				WHERE	tsod.comp_id	= @comp_id AND
				--						tsod.mlo_id		= @intMLOId
				--	)
				--	OR
				--EXISTS(
				--			SELECT TOP 1  1
				--			FROM tbItemTransactions AS tit  WITH (NOLOCK)
				--				WHERE	tit.comp_id	= @comp_id AND
				--						tit.mlo_id	= @intMLOId
				--)
				--	OR
				--EXISTS(
				--			SELECT TOP 1  1
				--			FROM tbCommercialTransactions  AS tit  WITH (NOLOCK)
				--				WHERE	tit.comp_id	= @comp_id AND
				--						tit.mlo_id	= @intMLOId
				--		)
				--	BEGIN

				--		-- Marca la orden como PROCESADA para que no se vuelva a procesar.
				--		UPDATE tbMercadoLibre_ordersHeader		WITH (ROWLOCK)
				--			SET	mlo_isSaleOrderGenerated = 1
				--			WHERE	comp_id = @comp_id AND
				--					mlo_id	= @mlo_id



				--		UPDATE tbMercadoLibre_ordersDetail		WITH (ROWLOCK)
				--			SET	mlo_is4AvailableStock = 0
				--			WHERE	comp_id = @comp_id AND
				--					mlo_id	= @mlo_id

				--		FETCH curItems INTO
				--							@item_id ,
				--							@tis_itemDesc,
				--							@tis_itemDeta,
				--							@item_qty,
				--							@prli_id,
				--							@tis_price,
				--							@stor_id,
				--							@bra_id,
				--							@curr_id,  -- PESOS, va en duro pero deberia estar en la TIENDA
				--							@user_id,
				--							@MLUser_Id,
				--							@cust_id_A,
				--							@cust_id_B,
				--							@intSM_id,
				--							@intST_id,
				--							@intDISC_id,
				--							@intDL_Id,
				--							@intMLOId,
				--							@str2MLorder_id,
				--							@str2NickName,
				--							@mls_putSaleOrderwithTotalPrice

				--		CONTINUE
				--	END
				---- ----------------------------------------------------------------------------------



				---- ----------------------------------------------------------------------------------
				-- Ticket 11482, Colucci, para que tome del deposito del grupo que Tenga Stock Disponible
				---- ----------------------------------------------------------------------------------
				IF	@storg_id IS NOT NULL	AND
					@storg_id			> 0 AND
					@ML_logistic_type  <> 'fulfillment'	-- MOS 12-2022: x Colucci, si tenian definidos los grupos de deposito a cambiar, NO le da pelota si es FULL
					BEGIN
						DECLARE			@stor_idTMP AS integer = NULL
						SELECT TOP 1	@stor_idTMP = stor_id
							FROM tbStorageGroupDetail AS tsgd	WITH (NOLOCK)
							WHERE	tsgd.comp_id	= @comp_id		AND
									tsgd.storg_id	= @storg_id		AND
									dbo.fnGetAStock4MaxAssociation(tsgd.comp_id,tsgd.stor_id,@item_id,999999999) > 0
							ORDER BY tsgd.storg_order4MercadoLibre	ASC

						IF @stor_idTMP IS NOT NULL
							BEGIN
								SET @stor_id = @stor_idTMP
							END
					END
				---- ----------------------------------------------------------------------------------



				EXEC spCounters_getNextValue
						@comp_id,
						@stor_id ,
						1, --contador prioridades
						@counter_value = @tis_priority OUTPUT


				DELETE FROM #tmpTaxes


				-- ----------------------------------------------------------------
				-- Obtiene el precio SIN IMPUESTOS para poder cargar al pedido
				-- de la misma manera que el control de seleccion de precios
				-- le carga impuestos.
				-- ----------------------------------------------------------------
				INSERT INTO #tmpTaxes(item_id, ivaTax, InternalTax)
					EXEC spItemTaxes_TaxPercentageByItemId @comp_id,@bra_id,@item_id

				IF ISNULL(@mls_putSaleOrderwithTotalPrice,'False') = 'False'
					BEGIN
						SELECT @tis_price = @tis_price / (1 + (tmp.ivaTax / 100))
							FROM #tmpTaxes tmp

						SELECT @tis_price = @tis_price / (1 + (tmp.InternalTax / 100))
							FROM #tmpTaxes tmp
					END
				-- ----------------------------------------------------------------

				SET @user_id4MLT = @user_id * -1

				-- MOS 06-2024: Suma el total de Cupones de descuento para mas abajo restarlos al total y que den los numeros del pedido cargado como corresponde.
				SET @decTotalOfCouponDiscounts = @decTotalOfCouponDiscounts + @curCupon_amount

				EXEC spTempItemStock_insertData
					@comp_id,
					@guid,
					@tis_priority,
					@item_id,
					@tis_itemDesc,
					@tis_itemDesc,
					@curr_id,
					@item_qty,
					@item_qty,
					@prli_id,
					@tis_price,
					@stor_id,
					0,						--@doc_id
					@bra_id,
					@user_id4MLT /*@user_id*/,
					@getdate,				--@insertDate = null,
					@getdate,				--@lastUpdate = null,
					0,						--@tis_cost = null,
					1,						--@tis_costTax = null,
					null,					--@soh_id = null,
					null,					--@sod_id = null,
					'true',					--@to_associate = null,
					null,					--@is_id = null,
					'false',				--@tis_isMade = null,
					@wsID,'',
					-1,
					@return_value = @rv OUTPUT


				-- Guarda TODOS los mlo que ingresaron en esta vuelta x mlo o x Shippment
				IF NOT EXISTS (	SELECT TOP 1 1
				               		FROM @tmpMLOProcessed AS tm
				               		WHERE tm.mlo_id = @intMLOId)
					BEGIN
						INSERT INTO @tmpMLOProcessed
						(
							mlo_id
						)
						VALUES
						(
							@intMLOId
						)
					END

				--para que no borre los items el depurador
				UPDATE tbTempItemStock		WITH (ROWLOCK)
					SET	tis_IsEditingCd = DATEADD(hour,1,GETDATE()),
						sdlmt_id		= @sdlmt_id,
						mlo_id			= @intMLOId, -- @mlo_id
						tis_note2		= ISNULL(tis_note2,'') + ' Orden#' +dbo.fnStrAllTrim(ISNULL(@str2MLorder_id,'')) + ' NickName:' + dbo.fnStrAllTrim(ISNULL(@str2NickName ,'') )
					WHERE tis_id = @rv





				-- MOS 02-2024: 29-02-2024 V2
				DECLARE @strMLShippingID AS VARCHAR(30) = ''
				IF @curMLshippingID > 0
					BEGIN
						SET @strMLShippingID = dbo.fnStrAllTrim(CONVERT(VARCHAR(30),@curMLshippingID))
					END
				SET @strMLShippingID = dbo.fnStrAllTrim(dbo.fnAddStringIfNotExists(@strInternalAnnotation,@strMLShippingID))
				IF  @strMLShippingID <> ''
					BEGIN
						-- MOS 02-2024 x ARG
						SET @strInternalAnnotation = dbo.fnStrAllTrim(@strInternalAnnotation)
						IF DATALENGTH(@strInternalAnnotation) + DATALENGTH(@strMLShippingID) < 98
							BEGIN
								SET @strInternalAnnotation =	@strInternalAnnotation +
																CASE
																	WHEN @strInternalAnnotation <> '' THEN ','
																	ELSE ''
																END +
																dbo.fnStrAllTrim(@strMLShippingID)
							END
					END



				SET		@ret_ErrorDescription	= 'Insert OK'
				SET		@intItemsInserted		= @intItemsInserted + 1


				-- ---------------------------------------------------------------------------------------------------------------------
				-- Verifica si el Costo de Envio lo PAGO EL CLIENTE para poner asi el NUEVO ARTICULO con su Costo de Envio Facturado
				-- Ya que ML le FACTURA al vendedor el gasto de envio pagado por el cliente por lo que debe facturarlo
				-- ---------------------------------------------------------------------------------------------------------------------
				IF	@item_id4UserPayDelivery IS NOT NULL			AND
					@item_id4UserPayDelivery_TAX_Percentage > 0		AND
					@bitHasDeliveryChargesGenerated = 'False'  -- MOS 10-2019, lo pone para que SOLO lo genere UNA VEZ si son items de carrito en UN solo shippment ( carrito real )
					BEGIN

						SET @bitHasDeliveryChargesGenerated = 'True'

						DECLARE		 @decShippingCost AS DECIMAL(26,10) = 0
						--SELECT TOP 1 @decShippingCost = tmlop.MLshipping_cost
						--	FROM tbMercadoLibre_ordersPayments tmlop	WITH (NOLOCK)
						--	WHERE	tmlop.comp_id	= @comp_id		AND
						--			tmlop.mlo_id	= @intMLOId

						SELECT TOP 1 @decShippingCost = tmlop.MLShippmentCost4Buyer
							FROM tbMercadoLibre_ordersShipping  tmlop	WITH (NOLOCK)
							WHERE	tmlop.comp_id	= @comp_id		AND
									tmlop.mlo_id	= @intMLOId


						SET @decTotalGastosDeEnvioFacturables = @decShippingCost -- Deja guardado el importe FINAL para hacer el ajuste mas abajo.

						SELECT @decShippingCost = @decShippingCost / (1 + (@item_id4UserPayDelivery_TAX_Percentage / 100))



						IF @decShippingCost > 0
							BEGIN

								SET @tis_itemDesc = 'Envío Pago:' + @tis_itemDesc


								SET @user_id4MLT = @user_id * -1

								EXEC spTempItemStock_insertData
									@comp_id,
									@guid,
									@tis_priority,
									@item_id4UserPayDelivery,
									@tis_itemDesc,
									@tis_itemDesc,
									@curr_id,
									1,
									1,
									@prli_id,
									@decShippingCost,
									@stor_id,
									0,						--@doc_id
									@bra_id,
								    @user_id4MLT			/*@user_id*/,
									@getdate,				--@insertDate = null,
									@getdate,				--@lastUpdate = null,
									@decShippingCost,						--@tis_cost = null,
									@item_id4UserPayDelivery_TAX_Id,						--@tis_costTax = null,
									null,					--@soh_id = null,
									null,					--@sod_id = null,
									'true',					--@to_associate = null,
									null,					--@is_id = null,
									'false',				--@tis_isMade = null,
									@wsID,'',
									-1,
									@return_value = @rv OUTPUT


								--para que no borre los items el depurador
								UPDATE tbTempItemStock		WITH (ROWLOCK)
									SET	tis_IsEditingCd		= DATEADD(hour,1,GETDATE()),
										sdlmt_id			= @sdlmt_id,
										tis_costForced2All	= @decShippingCost,
										mlo_id				= @intMLOId   -- 07-2018
									WHERE tis_id = @rv


--   @MLorder_id			= convert(nvarchar(50),tmloh.MLorder_id),
--   		   @strNickName			= tmlud.nickname,
--INNER JOIN tbMercadoLibre_UsersData tmlud	WITH (NOLOCK)
--ON tmlud.MLUser_Id = tmloh.MLUser_Id

--UPDATE tbSaleOrderDetail
--	SET	sod_note2 = ISNULL(sod_note2,'') + 'Orden#' +dbo.fnStrAllTrim(ISNULL(@MLorder_id,'')) + ' NickName:' + dbo.fnStrAllTrim(ISNULL(@strNickName ,'') )
--	WHERE	comp_id					= @comp_id AND
--			bra_id					= @bra_id AND
--			soh_id					= @rv



							END




					END
				-- ---------------------------------------------------------------------------------------------------------------------





					-- ---------------------------------------------------------------------------------------------------------------------
					-- Genera solicitud de actualizacion de Stock de los items del pedido para TODAS las publicaciones en las que esten.
					-- ---------------------------------------------------------------------------------------------------------------------
					INSERT INTO tbMercadoLibre_updateQueue(	comp_id,
															mlp_id,
															[user_id],
															mlproc_option,
															mlproc_integerValue,
															mlproc_isProcessed,
															mlproc_isCancelled,
															mlproc_priority,
															mlproc_guid,
															mlproc_integerValue2,
															mlproc_internalID)	--WITH (ROWLOCK)
						SELECT	DISTINCT
								tmlip.comp_id,
								tmlip.mlp_id,
								tmls.[user_id],
								4,
								1,
								'False',
								'False',
								-1,
								@GUID4QUEUEMODE,
								1,
								99888001
							FROM tbMercadoLibre_ItemsPublicados tmlip				WITH (NOLOCK)
							INNER JOIN tbMercadoLibre_Stores	tmls				WITH (NOLOCK)
								ON	tmls.comp_id	= tmlip.comp_id AND
									tmls.mls_id		= tmlip.mls_id
							WHERE	tmlip.comp_id							= @comp_id	AND
									tmlip.item_id							= @item_id	AND
									tmls.mls_disabled						= 'False'	AND
									tmls.mls_forcePublicationStatus2Paused	= 'False'	AND
									tmlip.mlp_Active						= 'True'	AND
									NOT EXISTS (
												SELECT TOP 1 1
													FROM tbMercadoLibre_updateQueue AS tmluq			WITH (NOLOCK)
													WHERE
														tmluq.comp_id			 = tmlip.comp_id	AND
														tmluq.mlp_id			 = tmlip.mlp_id		AND
														tmluq.mlproc_option      = 4				AND
														tmluq.mlproc_isProcessed = 0				AND
														tmluq.mlproc_isCancelled = 0
												)
					-- ---------------------------------------------------------------------------------------------------------------------





				FETCH curItems INTO
									@item_id ,
									@tis_itemDesc,
									@tis_itemDeta,
									@item_qty,
									@prli_id,
									@tis_price,
									@stor_id,
									@ML_logistic_type,
									@bra_id,
									@curr_id , -- PESOS, va en duro pero deberia estar en la TIENDA
									@user_id,
									@MLUser_Id,
									@cust_id_A,
									@cust_id_B,
									@intSM_id,
									@intST_id,
									@intDISC_id,
									@intDL_Id,
									@intMLOId,
									@str2MLorder_id,
									@str2NickName,
									@mls_putSaleOrderwithTotalPrice	,
									@storg_id,
									@MLShippmentColectaDayTime,
									@curMLshippingID,
									@curCupon_amount,
									@mls_OrdersWithDiscountCouponIncludeInPriceV2


			END
		CLOSE		curItems
		DEALLOCATE	curItems

		IF @intItemsInserted = 0
			BEGIN
				SET @rv = -2
				SET @errormessage = '-2: No hay Items Ingresados'
				RETURN
			END
	-- ------------------------------------------------------------------------------------------------------



	DECLARE @MLorder_id   AS NVARCHAR(50)


	-- ------------------------------------------------------------------------------------------------------
	-- Busca el Cliente o lo da de alta
	-- ------------------------------------------------------------------------------------------------------
	DECLARE @strCustomerName	AS NVARCHAR(200)
	DECLARE @strCustomerPhone	AS NVARCHAR(200)
	DECLARE @strNickName		AS NVARCHAR(100)
	DECLARE @strCustomerAddress AS NVARCHAR(200)
	DECLARE @strCustomercity	AS NVARCHAR(200)
	DECLARE @strCustomerZIP     AS NVARCHAR(10)
	DECLARE @intCountryID		AS INT
	DECLARE @intStateID			AS INT
	DECLARE @strStateDesc		AS NVARCHAR(200)
	DECLARE @strCompleteAddresds AS NVARCHAR(4000) = ''
	DECLARE @intShippingID		AS BIGINT = NULL
	DECLARE @strMLUserReciberName	AS NVARCHAR(1000) = ''
	DECLARE @strMLUserReceiverPhone AS NVARCHAR(1000) = ''
	DECLARE @strDeliveryAddress		AS NVARCHAR(4000) = ''

	DECLARE @intMLCustID AS BIGINT = 0


	SELECT @strMLUserReciberName	= tmloh.MLUser_receiver_name,
		   @strMLUserReceiverPhone	=	CASE
											WHEN dbo.fnStrAllTrim(ISNULL(tmloh.MLUser_receiver_phone,''))	<> '' THEN dbo.fnStrAllTrim(ISNULL(tmloh.MLUser_receiver_phone,''))
											WHEN dbo.fnStrAllTrim(ISNULL(tmlos.MLreceiver_phone,''))		<> '' THEN dbo.fnStrAllTrim(ISNULL(tmlos.MLreceiver_phone,''))
											WHEN dbo.fnStrAllTrim(ISNULL(tmloh.MLUser_phone,''))			<> '' THEN dbo.fnStrAllTrim(ISNULL(tmloh.MLUser_phone,''))
											WHEN dbo.fnStrAllTrim(ISNULL(tmlud.phone,''))					<> '' THEN dbo.fnStrAllTrim(ISNULL(tmlud.phone,''))
											ELSE 'XXXXXXX'
										END,
		   @strCustomerEMail	= dbo.fnStrAllTrim(tmloh.mlo_email) ,
		   @MLorder_id			= convert(nvarchar(50),tmloh.MLorder_id),
		   @MLUser_Id			= tmloh.MLUser_Id,
		   @strTNT				= tmloh.identificationType,
		   @strDocumentNumber	= tmloh.identificationNumber,
		   @strCustomerName		=	CASE
		                   		 	    WHEN ISNULL(tmloh.MLUser_last_name,'') + ISNULL(tmloh.MLUser_first_name,'') <> ''	-- MOS 01-2020
		                   		 															THEN	ISNULL(tmloh.MLUser_last_name,'') + ' ' + ISNULL(tmloh.MLUser_first_name,'')
		                   		 	    WHEN ISNULL(tmloh.MLUser_receiver_name,'')	<> ''	THEN	tmloh.MLUser_receiver_name
		                   		 	    WHEN ISNULL(tmlud.receiver_name,'')			<> ''	THEN	tmlud.receiver_name
		                   		 	    ELSE														tmlud.nickname
		                   		 	END,
		   @strCustomerPhone	=	CASE
										WHEN ISNULL(tmloh.MLUser_receiver_phone,'') <> ''	THEN tmloh.MLUser_receiver_phone
										WHEN ISNULL(tmlud.receiver_phone,'')		<> ''   THEN tmlud.receiver_phone
										ELSE													 ''
									END,
		   @strNickName			= tmlud.nickname,
		   @strCustomerAddress  =	CASE
										WHEN ISNULL(tmloh.MLUser_address,'')		<> ''	THEN tmloh.MLUser_address
										WHEN tmlos.comp_id IS NOT NULL						THEN tmlos.MLreceiver_address  -- MOS 10-2021
										ELSE													 ISNULL(tmlud.[address],'**')
									END,
		   @strCustomercity		=	CASE
										WHEN ISNULL(tmloh.MLUser_citi,'')			<> ''	THEN tmloh.MLUser_citi
										WHEN ISNULL(tmlos.MLcity_name,'')			<> ''   THEN tmlos.MLcity_name
										ELSE													 '**'
									END,

		   @strCustomerZIP		=	CASE
										WHEN ISNULL(tmloh.MLUser_zip_code,'')		<> ''	THEN tmloh.MLUser_zip_code
										WHEN ISNULL(tmlud.zip_code,'')				<> ''   THEN tmlud.zip_code
										ELSE													 '9999'
									END,
		   @intCountryID		=	ISNULL(tmls.country_id, 54),
		   @strStateDesc		=	CASE
										WHEN dbo.fnStrAllTrim (ISNULL(tmloh.MLUser_state,''))	<> ''	THEN tmloh.MLUser_state
										ELSE																 tmlud.[state]
									END,
		   @intShippingID		= tmloh.MLShippingID,
		   @strDeliveryAddress	=	CASE
										WHEN tmlos.comp_id IS NOT NULL						THEN tmlos.MLreceiver_address
										WHEN ISNULL(tmloh.MLUser_address,'')		<> ''	THEN tmloh.MLUser_address
										ELSE													 tmlud.[address]
									END,
			@intMLCustID		= tmloh.MLUser_Id
		FROM tbMercadoLibre_ordersHeader			tmloh	WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_UsersData			tmlud	WITH (NOLOCK)
			ON tmlud.MLUser_Id = tmloh.MLUser_Id
		LEFT JOIN tbMercadoLibre_ordersShipping AS	tmlos	WITH (NOLOCK)
			ON	tmlos.comp_id	= tmloh.comp_id	AND
				tmlos.mlo_id	= tmloh.mlo_id
		LEFT JOIN tbmercadolibre_stores				tmls	WITH (NOLOCK)
			ON  tmls.mls_id =   tmloh.mls_id
		WHERE	tmloh.comp_id	= @comp_id AND
				tmloh.mlo_id	= @mlo_id


	-- ------------------------------------------
	-- Intenta obtener algun telefono
	-- MOS 10-2021
	-- ------------------------------------------
	SET @strCustomerPhone = dbo.fnStrAllTrim(ISNULL(@strCustomerPhone,''))
	IF  @strCustomerPhone = 'XXXXXXX' SET @strCustomerPhone = ''
	SET @strMLUserReceiverPhone = dbo.fnStrAllTrim(ISNULL(@strMLUserReceiverPhone,''))
	IF  @strMLUserReceiverPhone = 'XXXXXXX' SET @strMLUserReceiverPhone = ''

	IF  @strCustomerPhone		= '' SET @strCustomerPhone			= @strMLUserReceiverPhone
	IF  @strMLUserReceiverPhone = '' SET @strMLUserReceiverPhone	= @strCustomerPhone
	-- ------------------------------------------

	-- ------------------------------------------
	-- Normaliza las direcciones
	-- MOS 10-2021
	-- ------------------------------------------
	SET @strCustomerAddress = dbo.fnStrAllTrim(ISNULL(@strCustomerAddress,''))

	SET @strDeliveryAddress = dbo.fnStrAllTrim(ISNULL(@strDeliveryAddress,''))
	IF  @strDeliveryAddress = '' SET @strDeliveryAddress = @strCustomerAddress
	SET @strDeliveryAddress = @strDeliveryAddress + ' ' +
							  'RECIBE:'   + dbo.fnStrAllTrim(ISNULL(@strMLUserReciberName,'')) +  ' / ' +
							  'Teléfono:' + dbo.fnStrAllTrim(ISNULL(@strMLUserReceiverPhone,''))

	SET @strCompleteAddresds =	dbo.fnStrAllTrim(ISNULL(@strCustomerAddress,'')) + ', ' +
								dbo.fnStrAllTrim(ISNULL(@strCustomercity,'')) + ' (' +
								dbo.fnStrAllTrim(ISNULL(@strCustomerZIP,'')) + ') ' +
								dbo.fnStrAllTrim(ISNULL(@strStateDesc,'')) + ' ' +
								'RECIBE:'   + dbo.fnStrAllTrim(ISNULL(@strMLUserReciberName,'')) +  ' ' +
								'Teléfono:' + dbo.fnStrAllTrim(ISNULL(@strMLUserReceiverPhone,''))
	-- ------------------------------------------



	-- https://developers.mercadolibre.com.ar/es_ar/facturacion#Consultar-los-datos-de-facturaci%C3%B3n
	-- Domicilios Fiscales	, el antes puesto es el de entrega que era lo que ANTES se devolvia cuando no estaba el recurso de /billing_info de /orders
	SELECT
		   @strTNT				=	CASE
										WHEN ISNULL(tmlud.billing_DOC_TYPE,'') <> ''		THEN tmlud.billing_DOC_TYPE
										ELSE													 @strTNT
									END	,
		   @strDocumentNumber	=	CASE
										WHEN ISNULL(tmlud.billing_DOC_NUMBER,'') <> ''		THEN tmlud.billing_DOC_NUMBER
										ELSE													 @strDocumentNumber
									END,
		   @strCustomerName		=	CASE
		                   		 	    WHEN ISNULL(tmlud.billing_DOC_TYPE,'') = 'CUIT' AND
		                   		 			 ISNULL(tmlud.billing_FIRST_NAME,'') <> ''		THEN ISNULL(tmlud.billing_FIRST_NAME,'')	-- MOS 05-2024: Como los FORROS cambiaron e billing, hacemos esto para que carge solo la razon social y no la RS mas el nombre del receptor.
										WHEN ISNULL(tmlud.billing_LAST_NAME,'')  <> ''		THEN ISNULL(tmlud.billing_LAST_NAME,'') + ' ' + ISNULL(tmlud.billing_FIRST_NAME,'')
		                   		 	    ELSE													 @strCustomerName
		                   		 	END,
		   @strCustomerAddress  =	CASE
										WHEN ISNULL(tmlud.billing_STREET_NAME,'') <> ''		THEN ISNULL(tmlud.billing_STREET_NAME,'') + ' ' + ISNULL(tmlud.billing_STREET_NUMBER,'')
										ELSE											         @strCustomerAddress
									END,
		   @strCustomercity		=	CASE
										WHEN ISNULL(tmlud.billing_CITY_NAME,'')	<> ''		THEN ISNULL(tmlud.billing_CITY_NAME,'')
										ELSE												     @strCustomercity
									END,
		   @strCustomerZIP		=	CASE
										WHEN ISNULL(tmlud.billing_ZIP_CODE,'')	<> ''		THEN ISNULL(tmlud.billing_ZIP_CODE,'')
										ELSE													 @strCustomerZIP
									END,
		   @intCountryID		= ISNULL(tmls.country_id, 54),  --54,
		   @strStateDesc		=	CASE
										WHEN ISNULL(tmlud.billing_STATE_NAME,'')	<> ''	THEN ISNULL(tmlud.billing_STATE_NAME,'')
										ELSE													 @strStateDesc
									END
		FROM tbMercadoLibre_ordersHeader	tmloh	WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_UsersData tmlud	WITH (NOLOCK)
			ON tmlud.MLUser_Id = tmloh.MLUser_Id
		LEFT JOIN tbmercadolibre_stores				tmls	WITH (NOLOCK)
			ON  tmls.mls_id =   tmloh.mls_id
		WHERE	tmloh.comp_id	= @comp_id AND
				tmloh.mlo_id	= @mlo_id



	-- --------------------------------------------------------------------------------------------------------
	-- Asignacion de PROVINCIAS
	-- --------------------------------------------------------------------------------------------------------
	SET		@strStateDesc	= dbo.fnStrAllTrim(@strStateDesc)
	SET		@intStateID		= 54019 -- x defecto es CAPITAl
	IF		@intCountryID   = 56	SET @intStateID = 56011	-- Si es Chile pone Metropolitana de Santiago

	-- Busca Provincias en Argentina
	IF		@strStateDesc	<> '' AND @intCountryID = 54
		BEGIN
			SELECT	@intStateID		= ts.state_id
				FROM tbsysState ts	WITH (NOLOCK)
				WHERE	ts.country_id			= @intCountryID						AND
						ts.MLStateDescription	LIKE '%' + @strStateDesc  + '%'
		END

	-- Busca Regiones en Chile
	IF		@strStateDesc	<> '' AND @intCountryID = 56
		BEGIN
			SELECT	@intStateID		= ts.state_id
				FROM tbsysState ts	WITH (NOLOCK)
				WHERE	ts.country_id			= @intCountryID						AND
						ts.MLStateDescription	LIKE '%' + @strStateDesc  + '%'
			IF @@ROWCOUNT = 0
				BEGIN
					SELECT	@intStateID		= ts.state_id
						FROM tbsysState ts	WITH (NOLOCK)
						WHERE	ts.country_id			= @intCountryID						AND
								SUBSTRING(ts.MLStateDescription,1,2)	=  SUBSTRING( @strStateDesc,1,2)
				END
		END
	-- --------------------------------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------------------
	-- MOS 02-2022  **6541ewrwefrwe**wefwe
	-- POr los NABOS de MF, por las dudas busco el ID del USUARIO
	-- ----------------------------------------------------------------------------------
	IF dbo.fnStrAllTrim(@strTNT)			= ''
		BEGIN
			SET @strTNT						= @strIdentificationType
		END

	IF dbo.fnStrAllTrim(@strDocumentNumber) = ''
		BEGIN
			SET @strDocumentNumber			= @strIdentificationNumber
		END


	-- MOS 03-2023: x Latamly, si NO tengo documento, le pongo RUT y el numero de cliente de meli del usuario que compra
	IF	@intCountryID = 56 AND
		dbo.fnStrAllTrim(@strTNT)	= ''
		BEGIN
			SET @strTNT = 'RUT'
		END
	IF	@intCountryID = 56 AND
		 dbo.fnStrAllTrim(@strDocumentNumber) = ''
		BEGIN
			SET @strDocumentNumber = CONVERT(VARCHAR(20),@intMLCustID)
			SELECT 	@strCustomerAddress = tc.cust_address,
					@strCustomercity	= tc.cust_city,
					@strCustomerZIP		= tc.cust_zip,
					@intStateID			= tc.state_id,
					@strCustomerPhone	= tc.cust_phone1
				FROM tbCustomer tc	WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id =	CASE
											WHEN @strTNT = 'CUIT'	THEN @cust_id_A
											WHEN @strTNT = 'DNI'	THEN @cust_id_B
											WHEN @strTNT = 'RUT'	THEN @cust_id_A
											WHEN @strTNT = 'RUN'	THEN @cust_id_B
											ELSE						 @cust_id_B
										END
		END
	-- MOS 03-2023: x Latamly, si NO tengo documento, le pongo RUT y el numero de cliente de meli del usuario que compra


	IF dbo.fnStrAllTrim(@strDocumentNumber) = ''
		BEGIN
			SELECT	-1						[code],
					'El Documento del Cliente está VACIO'	[error_description]
			RETURN
		END
	-- ----------------------------------------------------------------------------------




	DECLARE @bitIsValidationValid AS BIT = 'False'
	DECLARE @strValidation AS NVARCHAR(20) = @strDocumentNumber
	IF @strTNT = 'CUIT'
		BEGIN
			EXEC spGeneric_validateTaxNumber 54, 1, @strValidation OUTPUT, @bitIsValidationValid OUTPUT
			IF @bitIsValidationValid = 'True'
				BEGIN
					SET @strDocumentNumber = @strValidation
				END
		END
	DECLARE @strDocumentNumberNoSlash AS NVARCHAR(20)
	SET		@strDocumentNumberNoSlash = REPLACE(@strDocumentNumber,'-','')


	DECLARE @cust_id AS INT
	SET		@curr_id = NULL
	SELECT	@cust_id = tc.cust_id
		FROM tbCustomer tc		WITH (NOLOCK)
		WHERE	tc.comp_id			= @comp_id	AND				-- OJO con esto, si comienza a haber lios por autoasignar clientes poner estricto por DNI o CUIT y listo . . .
				(
					(
						tc.cust_taxNumber	= @strDocumentNumber
							OR
						REPLACE(tc.cust_taxNumber,'-','')	= @strDocumentNumberNoSlash
					)
				)								AND
				tc.tnt_id		=	CASE
										WHEN @strTNT = 'CUIT'	THEN 1
										WHEN @strTNT = 'DNI'	THEN 5
										WHEN @strTNT = 'RUT'	THEN 56001
										ELSE						 5
									END			AND
				tc.cust_taxNumber <> ''



