					@fc_id				= tta.afip_fiscalClass
				FROM tbsysTaxAFIP tta	WITH (NOLOCK)
				WHERE tta.afip_cuit		= REPLACE(@strDocumentNumber,'-','')

			SET @cust_id = IDENT_CURRENT('tbCustomer') -- Para Comparar x las dudas . . .

			-- MOS 03-2023: Si es Chile, pone siempre BOLETA ya que NO se sabe que es finalmente el cliente.
			IF @intCountryID = 56
				BEGIN
