--SELECT 2,'@cust_id',@cust_id
----==

			-- Si no se dio de alta nada nuevo . . .  se hace asi x posibles triggers
			IF @cust_id = IDENT_CURRENT('tbCustomer')
				BEGIN
					SET @rv = -3
					SET @errormessage = '-3: NO se pudo dar de alta al cliente o encontrar el correspondiente'
					RETURN
				END

			SET @cust_id = IDENT_CURRENT('tbCustomer')



			--actualización de los datos de la tabla de ciudades con los datos ya cargados en customer
			DECLARE @strExecute AS NVARCHAR(4000)
			SET @strExecute = '
			INSERT      INTO tbCities ( comp_id,  country_id,       state_id,         city_desc )
			SELECT      DISTINCT        1      ,  tc.country_id,    tc.state_id,      tc.cust_city
				FROM  tbCustomer  tc	WITH (NOLOCK)
				WHERE
							tc.comp_id = ' + CONVERT(NVARCHAR(10),@comp_id) +  '
				AND         tc.cust_id = ' + CONVERT(NVARCHAR(10),@cust_id) +  '
				AND			not tc.country_id is null
				AND         not tc.state_id         IS NULL
				and         not tc.cust_city  IS NULL
				and         tc.cust_city            <> ''''
				AND         NOT EXISTS (SELECT top 1 1 FROM vwCities tc1 WITH (NOLOCK)
											WHERE tc1.country_id    = tc.country_id		AND
											      tc1.state_id      = tc.state_id		AND
											      ltrim(rtrim(tc1.city_desc))  = ltrim(rtrim(tc.cust_city))
											      COLLATE Modern_Spanish_CI_AI )
							'
			EXEC (@strExecute)

			SET @strExecute = '
								UPDATE      tbCustomer
								SET         city_id = tc2.city_id
									FROM  tbCustomer tc
										INNER JOIN vwCities tc2	WITH (NOLOCK)
											ON    tc2.country_id    = tc.country_id
											AND tc2.state_id  = tc.state_id
											AND ltrim(rtrim(tc2.city_desc))    = ltrim(rtrim(tc.cust_city))
											COLLATE Modern_Spanish_CI_AI
									WHERE
										tc.comp_id = ' + CONVERT(NVARCHAR(10),@comp_id) +  '	AND
										tc.cust_id = ' + CONVERT(NVARCHAR(10),@cust_id) +  '	AND
										tc.city_id IS NULL
												'
			EXEC (@strExecute)

		END

	-- ------------------------------------------------------------------------------------------------------


----==
--SELECT 3,'@cust_id',@cust_id
----==


	-- ------------------------------------------------------------------------------------------------------
	-- Actualiza Datos del Cliente
	-- ------------------------------------------------------------------------------------------------------
				 --CONVERT(NVARCHAR(150),@strCustomerAddress)	,
				 --CONVERT(NVARCHAR(60),@strCustomercity)	,
				 --@strCustomerZIP	,
				 --@intCountryID	,
				 --@intStateID	,
	UPDATE tbcustomer	WITH (ROWLOCK)
		SET		MLUser_Id	= @MLUser_Id ,
				--cust_email  =
				--				CASE
				--					WHEN cust_email LIKE '%mercadolibre%'
				--							OR
				--						 cust_email = ''					THEN	@strCustomerEMail
				--					ELSE											cust_email
				--				END ,
				fc_id		=
								CASE
									WHEN fc_id = 0 THEN 2
									ELSE fc_id
								END ,
				--cust_name	= @strCustomerName,	-- MOS 10-2021
				cust_name1	=	CASE
									WHEN dbo.fnStrAllTrim (ISNULL(cust_name1,'')) = '' THEN @strNickName
									ELSE													cust_name1
								END,		-- MOS 10-2021
				cust_MercadoLibreNickName	=	CASE
													WHEN dbo.fnStrAllTrim (ISNULL(cust_MercadoLibreNickName,'')) = '' THEN @strNickName
													ELSE																   cust_MercadoLibreNickName
												END,		-- MOS 10-2021
				cust_phone1 =	CASE	-- MOS 10-2021
									WHEN dbo.fnStrAllTrim (ISNULL(cust_phone1,'')) = '' AND  @strCustomerPhone			<> '' THEN @strCustomerPhone
									ELSE cust_phone1
								END ,
				cust_phone2 =   CASE	-- MOS 10-2021
									WHEN dbo.fnStrAllTrim (ISNULL(cust_phone2,'')) = '' AND  @strMLUserReceiverPhone	<> '' THEN @strMLUserReceiverPhone
									ELSE cust_phone2
								END ,


				cust_email	=	CASE	-- MOS 10-2021
									WHEN dbo.fnStrAllTrim(ISNULL(cust_email,'')) = ''				THEN	@strCustomerEMail
									WHEN dbo.fnStrAllTrim(ISNULL(cust_email,'')) like '%mercadoli%'	THEN	@strCustomerEMail
									WHEN @strCustomerEMail LIKE '%mercado%'							THEN	cust_email
									ELSE																	cust_email --@strCustomerEMail
								END
		WHERE	comp_id		= @comp_id		AND
				cust_id		= @cust_id
	-- ------------------------------------------------------------------------------------------------------



	-- ------------------------------------------------------------------------------------------------------
	-- Inserta el Pedido
	-- ------------------------------------------------------------------------------------------------------

	DECLARE @sd_id AS INT
	SET		@sd_id = 1  -- FACTURA

	-- Busca el Documento


	SELECT
		@intSM_id		=	CASE
								WHEN @intSM_id IS NULL   THEN	tc.sm_id
								ELSE							@intSM_id
							END,
		@intST_id		=	CASE
								WHEN @intST_id IS NULL	 THEN	tc.st_id
								ELSE							@intST_id
							END,
		@intDISC_id		=	CASE
								WHEN @intDISC_id IS NULL THEN	tc.disc_id
								ELSE							@intDISC_id
							END	,
		@intDL_Id		=	CASE
								WHEN @intDL_Id	 IS NULL THEN   tc.dl_id
								ELSE							@intDL_Id
							END,
		@curr_id_cust	= tc.curr_id
		FROM tbCustomer					tc     WITH (NOLOCK)
		WHERE	tc.comp_id  = @comp_id	AND
				tc.cust_id  = @cust_id


	-- Si se especifica un pto de vta x cond de vta reemplaza al que informa producteca.
	-- Esto es para que busque 1ro los documentos disponibles de este punto de ventas en particular
	-- y si no encuentra nada q busque un documento . . .
	DECLARE @PointOfSale AS INT
	SET		@PointOfSale = -1
	SELECT
		TOP 1
			@PointOfSale =	CASE
								WHEN ISNULL(tst.st_pointOfSale4MercadoLibre,0) > 0   THEN tst.st_pointOfSale4MercadoLibre
							ELSE              @PointOfSale
							END
		FROM tbSalesTerms				tst		WITH (NOLOCK)
		INNER JOIN tbDocumentsFile		tdf		WITH (NOLOCK)
			ON	tdf.comp_id = @comp_id	AND
				tdf.bra_id	= @bra_id	AND
				tdf.sd_id	= @sd_id
		WHERE	tst.comp_id = @comp_id	AND
				tst.st_id	= @intST_id AND
		(
			(tst.st_pointOfSale4MercadoLibre  = tdf.df_pointOfSale AND tst.st_pointOfSale4MercadoLibre > 0 )
			OR
			(tst.st_pointOfSale4MercadoLibre2 = tdf.df_pointOfSale AND tst.st_pointOfSale4MercadoLibre2 > 0)
			OR
			(tst.st_pointOfSale4MercadoLibre3 = tdf.df_pointOfSale AND tst.st_pointOfSale4MercadoLibre3 > 0)
			OR
			(tst.st_pointOfSale4MercadoLibre4 = tdf.df_pointOfSale AND tst.st_pointOfSale4MercadoLibre4 > 0)
		)
		AND tdf.df_Disabled = 'False'
		ORDER BY tdf.df_order




	--obtenemos el df_id para generar el pedido
	DECLARE	@df_id  INT
	SET		@df_id  = NULL
	DECLARE
		@bitForce2Preparation AS BIT
	SET @bitForce2Preparation = 0

	DECLARE @bitIsFulFilled AS BIT = 'FALSE'
	SELECT	@bitIsFulFilled = 'True'
	FROM tbMercadoLibre_ordersShipping tmloh	WITH (NOLOCK) 
	WHERE	tmloh.comp_id		= @comp_id	AND
			tmloh.mlo_id		= @mlo_id	AND
			tmloh.MLfulfilled	= 'True'


	-- Primero intentando por en numero de PUnto de Venta
	SELECT
		TOP 1
			@df_id = df_id
		FROM  dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
		WHERE	@PointOfSale	> 0					AND
				sd_id			= @sd_id			AND
				df_pointOfSale	= @PointOfSale
		ORDER BY	CASE
						WHEN mls_id					= @mls_id	AND
							 @bitIsFulFilled		= 'True'	AND
							 df_is4mlo4FulFillment	= 'True' 			THEN -3		-- Si es favorito de esa tienda va 1ro FULFILLMENT
						WHEN --mls_id					= @mls_id	AND
							 @bitIsFulFilled		= 'True'	AND
							 df_is4mlo4FulFillment	= 'True' 			THEN -2		-- Si es favorito de esa tienda va 1ro FULFILLMENT
						WHEN mls_id					= @mls_id	AND
							 @bitIsFulFilled		= 'False'	AND
							 df_is4mlo4FulFillment	= 'False' 			THEN -1		-- Si es favorito de esa tienda va 1ro
						WHEN @bitIsFulFilled		= 'False'	AND					-- Si tiene prioridad para FULL
							 df_is4mlo4FulFillment	= 'True' 			THEN  8
						WHEN is4ML = 1									THEN  5		-- Luego si es favorito de Meli
						ELSE												  10		-- el 1ro que venga
					END,
					df_order

	IF @df_id IS NULL
		BEGIN
			SELECT
				TOP 1
					@df_id = df_id
				FROM  dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
				WHERE sd_id   = @sd_id
				ORDER BY	CASE
								WHEN mls_id					= @mls_id	AND
									 @bitIsFulFilled		= 'True'	AND
									 df_is4mlo4FulFillment	= 'True' 			THEN -2		-- Si es favorito de esa tienda va 1ro FULFILLMENT
								WHEN mls_id					= @mls_id	AND
									 @bitIsFulFilled		= 'False'	AND
									 df_is4mlo4FulFillment	= 'False' 			THEN -1		-- Si es favorito de esa tienda va 1ro
								WHEN @bitIsFulFilled		= 'False'	AND					-- Si tiene prioridad para FULL
									 df_is4mlo4FulFillment	= 'True' 			THEN  8
								WHEN is4ML = 1									THEN  5		-- Luego si es favorito de Meli
								ELSE												  10		-- el 1ro que venga
							END,
							df_order
				--ORDER BY	CASE
				--				WHEN mls_id					= @mls_id	AND
				--					 @bitIsFulFilled		= 'True'	AND
				--					 df_is4mlo4FulFillment	= 'True' 			THEN -2		-- Si es favorito de esa tienda va 1ro FULFILLMENT
				--				WHEN mls_id					= @mls_id	AND
				--					 @bitIsFulFilled		= 'False'	AND
				--					 df_is4mlo4FulFillment	= 'False' 			THEN -1		-- Si es favorito de esa tienda va 1ro
				--				WHEN is4ML = 1									THEN  0		-- Luego si es favorito de Meli
				--				ELSE												  1		-- el 1ro que venga
				--			END,
				--			df_order
				-- MOS 12-2020
				--ORDER BY
				--		CASE
				--			WHEN is4ML = 1 THEN 0		-- Favoritos Primero
				--			ELSE				1
				--		END,
				--		df_order
		END


	-- obtengo el documento para REMITOS asociado a este documento si es que lo tiene y otros datos.. .
	DECLARE @ssos_id				AS INT
	DECLARE @intDFId4PackingList	AS INT
	SET		@ssos_id					= 20
	SET		@intDFId4PackingList		= NULL
	SELECT
			@intDFId4PackingList = tdf.df_SaleOrderPL_df_Id,
			@ssos_id =	CASE
							WHEN @bitforceSO4Commercial					= 'True'	THEN	10
							WHEN tdf.df_forceOKEmission					= 'True'	THEN	50
							WHEN tdf.df_forcePreparation				= 'True'	THEN	20
							WHEN tdf.df_SaleOrderCommercialSuggests		= 'True'	THEN	10
							WHEN tb.bra_SaleOrderCommercialSuggests		= 'True'	THEN	10
							ELSE															20
						END
		FROM tbDocumentsFile					tdf  WITH (NOLOCK)
		INNER JOIN tbBranch						tb   WITH (NOLOCK)
			ON	tb.comp_id	= tdf.comp_id	AND
				tb.bra_id	= tdf.bra_id
		WHERE	tdf.comp_id = @comp_id			AND
				tdf.df_id	= @df_id			AND
				tdf.df_Disabled = 'False'



	-- MOS 10-07-2019
	-- Si es FullFillment lo pone como OK Emision para que cuando este como delivered lo deje emitir sin preparar.
	DECLARE @bitIsFulFillment AS BIT = 'False'
	SELECT  @ssos_id			= 50 ,
			@bitIsFulFillment	= 'True'
		FROM tbMercadoLibre_ordersShipping tmloh	WITH (NOLOCK)
		WHERE	tmloh.comp_id			= @comp_id	AND
				tmloh.mlo_id			= @mlo_id	AND
				(
					tmloh.MLfulfilled		= 'True'
						OR
					tmloh.ML_logistic_type	= 'fulfillment'
				)



	IF @df_id IS NULL
		BEGIN

			SET @return_value = 43
			SELECT
				@errormessage		= tut.utexts_desc
				FROM tbsysUniqueTexts				tut  WITH (NOLOCK)
				WHERE	tut.lang_id		= @lang_id	AND
						tut.utexts_id	= 91

			SELECT
				@return_value [code],
				@errormessage [error_description]

			RETURN
		END

	-- ------------------------------------------------------------------------------------------------------




	-- ------------------------------------------------------------------------------------------------------
	-- Si es CHILE y FULL, debe ponerse ese documento ya que lo factura directo MercadoLibre
	-- ------------------------------------------------------------------------------------------------------
	IF	@bitIsFulFillment		= 'True'			AND
		@intCountryID			= 56				AND
		@cust_id_4Full4Countries	IS NOT NULL		AND
		@st_id4Full4Countries		IS NOT NULL		AND
		@df_id4Full4Countries		IS NOT NULL
		BEGIN
			SET @df_id		= @df_id4Full4Countries
			SET @intST_id	= @st_id4Full4Countries
			SET @cust_id	= @cust_id_4Full4Countries
		END
	-- ------------------------------------------------------------------------------------------------------








	-- ------------------------------------------------------------------------------------------------------
	-- Graba el Pedido
	-- ------------------------------------------------------------------------------------------------------
	DECLARE @rvp	 AS INT


	DECLARE
		@curr_id_branch					INT,
		@bra_PriceDecimalPlaces			INT,
		@bra_SaleOrderDisposeLimitDay	INT,
		@country_id						INT,
		@state_id						INT

	SELECT
		@curr_id_branch					= tb.curr_id,
		@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
		@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
		@country_id						= tb.country_id,
		@state_id						= tb.state_id
		FROM tbBranch					tb   WITH (NOLOCK)
		WHERE	tb.comp_id  = @comp_id	AND
				tb.bra_id	= @bra_id


	DECLARE @bitML_cancellMailWithSaleOrderCreation BIT
	SET		@bitML_cancellMailWithSaleOrderCreation = 1























	-- -----------------------------------------------------
	-- Hago los calculos de Importes del Pedido
	-- -----------------------------------------------------
	DECLARE
			@total			DECIMAL(19,6) = 0,
			@soh_discount   DECIMAL(19,6) = 0,
			@bitFirstPass   BIT = 'True'


	CREATE TABLE #tmpGetTotalsData
	(
		t1  INT,
		t2  DECIMAL(18,2),
		t3  DECIMAL(19,6),
		t4  DECIMAL(19,6),
		t5  DECIMAL(19,6),
		t6  DECIMAL(18,2),
		t7  DECIMAL(19,5),
		t8  INT,
		t9  DECIMAL(19,6),
		T10  NVARCHAR(4000),
		TotalNoInterest  DECIMAL(25,6)
	)


	-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
	DECLARE @exchange  DECIMAL(19,6)

	SELECT @exchange = dbo.fnGetExchange(@comp_id,1,@curr_id_branch,@curr_id_cust,0,0,'false')

	DECLARE @intCompIdTMP AS INT = -1 * @comp_id -- Variable para que calcule SIN PERCEPCIONES


	subRecalculate:
	DELETE FROM #tmpGetTotalsData
	-- -----------------------------------------------------
	-- recuperar los totales generales SIN PERCEPCIONES !!!
	-- -----------------------------------------------------
	INSERT INTO #tmpGetTotalsData
	EXEC sptmpTax_calculate
		@intCompIdTMP,
		@bra_id,
		@cust_id,
		@guid,
		@curr_id_branch,
		@intDISC_id,
		@country_id,
		@state_id,
		@intST_id,
		@curr_id_branch,
		@curr_id_cust,
		@exchange,
		'false',
		@df_id,
		'true',
		@intDL_Id,
		0,
		'false',
		'false',
		-1,
		-1 -- @ccp_id No INformado


	SELECT
		@total			= t2,
		@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces)

		FROM #tmpGetTotalsData

	DELETE FROM #tmpGetTotalsData
	-- -----------------------------------------------------




	-- -----------------------------------------------------
	-- LLeva el pedido al Importe de la Orden
	-- x si tuvo diferencias - AJUSTE - RECALCULO
	-- -----------------------------------------------------
	DECLARE		@intMLShippingID AS BIGINT = -1
	SELECT		@intMLShippingID = tmloh.MLShippingID
		FROM tbMercadoLibre_ordersHeader tmloh	WITH (NOLOCK)
		WHERE	tmloh.comp_id	= @comp_id AND
				tmloh.mlo_id	= @mlo_id

	IF ISNULL(@intMLShippingID,0) <= 0											-- NO CARRITO
		BEGIN
			SELECT @decTotalOfOrder = tmlod.mlo_transaction_amount
				FROM tbMercadoLibre_ordersHeader tmlod		WITH (NOLOCK)
				WHERE	tmlod.comp_id	= @comp_id AND
						tmlod.mlo_id	= @mlo_id
		END
	ELSE
		BEGIN
			SELECT @decTotalOfOrder = SUM(tmlod.mlo_transaction_amount)			-- SI CARRITO
				FROM tbMercadoLibre_ordersHeader tmlod		WITH (NOLOCK)
				WHERE	tmlod.comp_id		= @comp_id				AND
						tmlod.MLShippingID	= @intMLShippingID		AND
						(tmlod.mls_id		= @intMLStoreOfOrder
							OR
						 @intMLStoreOfOrder = -1
						)	-- MOS 09-2023: TP3D: (19349) **wefjkn32894684**342 Ticket  Se agregó esto para que si es un carrito de DOS tiendas diferentes, SOLO sume los items de la tienda del mlo_id que se pasó por parámetro y de esta manera NO ponga el total del item = al total de la orden!
		END


	SET @decTotalOfOrder =	ISNULL(@decTotalOfOrder,0) +
							ISNULL(@decTotalGastosDeEnvioFacturables,0)

	-- MOS 06-2024: que ponga el cupon de descuento asi no recalcula importes.
	IF @mls_OrdersWithDiscountCouponIncludeInPriceV2 = 'True'
		BEGIN
			SET @decTotalOfOrder =	@decTotalOfOrder -
									ISNULL(@decTotalOfCouponDiscounts,0)
		END

	IF	@bitFirstPass = 'TRUE' AND
		--@total		  <> @decTotalOfOrder
		ABS(@total	- @decTotalOfOrder) > 2	-- MOS 06-2024: para que tenga algo de tolerancia
		BEGIN
			EXEC spTempItemStock_setNewTotal
												@comp_id			,
												@bra_id				,
												@guid				,
												@total				,
												@decTotalOfOrder	,
												1
			SET @bitFirstPass	= 'False'
			GOTO subRecalculate		-- NO ABUSAR... en este caso Simplifica y mucho ! ! !
		END
	-- -----------------------------------------------------





	-- -----------------------------------------------------
	-- Vuelvo a calcular los TOTALES generales.
	-- con TODOS los impuestos incluidos.
	-- -----------------------------------------------------
	DELETE FROM #tmpGetTotalsData
	INSERT INTO #tmpGetTotalsData
	EXEC sptmpTax_calculate
		@comp_id,
		@bra_id,
		@cust_id,
		@guid,
		@curr_id_branch,
		@intDISC_id,
		@country_id,
		@state_id,
		@intST_id,
		@curr_id_branch,
		@curr_id_cust,
		@exchange,
		'false',
		@df_id,
		'true',
		@intDL_Id,
		0,
		'false',
		'false',
		-1,
		-1 -- @ccp_id No INformado


	SELECT
		@total			= t2,
		@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces)
		FROM #tmpGetTotalsData

	DROP TABLE #tmpGetTotalsData
	-- -----------------------------------------------------




	-- -----------------------------------------------------
	-- MOS 02-2023: x Colucci para evitar que se carguen pedidos sin mlo asignados.
	-- -----------------------------------------------------
	IF ISNULL(@mlo_id,0) <= 0
		BEGIN
			RETURN
		END
	-- -----------------------------------------------------




	-- ----------------------------------------------------------------------------------
	-- Control x las dudas . . .   IDEM en **65654fewefwlihweflhwe
	-- ----------------------------------------------------------------------------------
	IF
	EXISTS(
				SELECT TOP 1 1
					FROM tbMercadoLibre_ordersHeader hh	WITH (NOLOCK)
					WHERE	hh.comp_id	= @comp_id	AND
							hh.mlo_id	= @mlo_id	AND
							hh.mlo_isSaleOrderGenerated = 'True'
			)
		OR
	EXISTS(
				SELECT  TOP 1 1
					FROM tbSaleOrderDetail tsod    WITH (NOLOCK)
					WHERE	tsod.comp_id	= @comp_id AND
							tsod.mlo_id		= @mlo_id
			)
		OR
	EXISTS(
				SELECT TOP 1 1
				FROM tbSaleOrderHeader  tsod    WITH (NOLOCK)
					WHERE	tsod.comp_id	= @comp_id AND
							tsod.mlo_id		= @mlo_id
			)			OR
	EXISTS(
				SELECT TOP 1  1
				FROM tbItemTransactions AS tit  WITH (NOLOCK)
					WHERE	tit.comp_id	= @comp_id AND
							tit.mlo_id	= @mlo_id
			)
		OR
	EXISTS(
				SELECT TOP 1  1
				FROM tbCommercialTransactions  AS tit  WITH (NOLOCK)
					WHERE	tit.comp_id	= @comp_id AND
							tit.mlo_id	= @mlo_id
			)
		BEGIN

			-- Marca la orden como PROCESADA para que no se vuelva a procesar.
			UPDATE tbMercadoLibre_ordersHeader		WITH (ROWLOCK)
				SET	mlo_isSaleOrderGenerated = 1
				WHERE	comp_id = @comp_id	AND
						mlo_id	= @mlo_id	--AND   MOS 02-2023
						--mlo_isSaleOrderGenerated = 0



			UPDATE tbMercadoLibre_ordersDetail		WITH (ROWLOCK)
				SET	mlo_is4AvailableStock = 0
				WHERE	comp_id = @comp_id	AND
						mlo_id	= @mlo_id	AND
						mlo_is4AvailableStock = 1

			SELECT	-1						[code],
					'El pedido YA fue Generado'	[error_description]
			RETURN
		END
	-- ----------------------------------------------------------------------------------



	DECLARE @limitdate  DATETIME
	DECLARE @onlydate  DATETIME

	SET  @getdate = GETDATE()
	SELECT
		@onlydate = DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
	SET  @limitdate = @onlydate + @bra_SaleOrderDisposeLimitDay

	SET @limitdate = ISNULL(@limitdate, DATEADD(MONTH,1,GETDATE()))

	-- MOS 01-2024
	IF @MLShippmentColectaDayTime IS NULL
		BEGIN
			SET @MLShippmentColectaDayTime = GETDATE()
		END

	EXEC spSaleOrder_insertData
							-1,
							@guid,
							@comp_id,
							@bra_id			OUTPUT,
							@onlydate,
							@MLShippmentColectaDayTime,   -- MOS 01-2024 para que quede la fecha de colecta o de entrega.  hasta ahora quedaba la fecha del DIA./*@onlydate*/
							'',
							'',
							'',
							'',
							'false',
							@intSM_id,
							@cust_id,
							@intST_id,
							@intDISC_id,
							@intDL_Id,
							null,
							@onlydate,
							@limitdate,
							1,    --+------------------------------------------------------------------------------------
							'A',   --|estos 3 campos van así en duro, está igual que en el código de wfmSaleOrder.aspx.vb
							1,    --+------------------------------------------------------------------------------------
							@user_id,
							'false',
							@getdate  ,
							@total,
							@df_id,
							@ssos_id /*20*/,  -- a Preparacion directo
							@exchange,
							@curr_id_cust,
							NULL ,
							NULL,
							@return_value = @rv OUTPUT



	IF @rv IS NULL OR @rv <=0
		BEGIN
			SELECT @rv				= -10
			SELECT @errormessage	= '-10, No se pudo insertar el pedido'
			RETURN
		END


	EXEC spSaleOrderHeader_updatePL_df_id
		@comp_id,
		@bra_id,
		@rv,
		@intDFId4PackingList,
		null,
		@soh_discount,
		''


	EXEC spSaleOrder_updateCurrExchange
		@comp_id,
		@bra_id,
		@rv,
		@curr_id_cust,
		@exchange,
		0 --@decInCash


	-- MOS 02-2024: x FORRADA de Arg q quiere q el numero de orden se ponga en anotacion interna
	-- es al PEDO x q si es carrito son varias ordenes.
	-- Debo saber si es o no carrito para poner el shippment o el order
	-- Se agregó @strInternalAnnotation calculado más arriba como la union hasta 100 caracteres de los numeros de orden.

	UPDATE tbSaleOrderHeader	WITH (ROWLOCK)
		SET
			--soh_MLdeliveryLabel		= @deliveryLabel ,
			--soh_MLQuestionsAndAnswers	= @xmlQuestionsAndAnswers,
			soh_MLId					= @MLorder_id,
			soh_MLGUIA					= dbo.fnGetOnlyNumbers(@MLshipping_id),
			prli_id						= @prli_id,
			stor_id						= @stor_id,
			mlo_id						= @intMLOId   /*MOS 01-2024: x si llega con Shipping y no con Order ID  @mlo_id*/,
			soh_deliveryAddress			= @strDeliveryAddress, -- MOS 10-2021  @strCompleteAddresds,
			soh_isEditing				= 0,
			soh_internalAnnotation		= @strInternalAnnotation	-- MOS 02-2024
			--soh_observation1			= CONVERT(VARCHAR(200),@strDeliveryAddress) -- MOS 10-2021, AL PEDO, mejor lo saco
		WHERE	comp_id					= @comp_id AND
				bra_id					= @bra_id AND
				soh_id					= @rv


	UPDATE tbSaleOrderDetail		WITH (ROWLOCK)
		SET sod_isEditing				= 0
		WHERE	comp_id					= @comp_id AND
				bra_id					= @bra_id AND
				soh_id					= @rv


	--UPDATE tbSaleOrderDetail
	--	SET	sod_note2 = ISNULL(sod_note2,'') + 'Orden#' +dbo.fnStrAllTrim(ISNULL(@MLorder_id,'')) + ' NickName:' + dbo.fnStrAllTrim(ISNULL(@strNickName ,'') )
	--	WHERE	comp_id					= @comp_id AND
	--			bra_id					= @bra_id AND
	--			soh_id					= @rv



	-- Marca la orden como PROCESADA para que no se vuelva a procesar.
	UPDATE tbMercadoLibre_ordersHeader		WITH (ROWLOCK)
		SET	mlo_isSaleOrderGenerated						= 1,
			mlo_OrdersWithDiscountCouponIncludeInPriceV2	= @mls_OrdersWithDiscountCouponIncludeInPriceV2	-- MOS 06-2024: pone si se generó con la opcion de V2
		FROM tbMercadoLibre_ordersHeader mloh	-- MOS 23-04-2020 ya que NO quedaban marcadas las ordenes de carrito, solo la principal
		INNER JOIN @tmpMLOProcessed  tmp
			ON tmp.mlo_id = mloh.mlo_id
		WHERE	comp_id = @comp_id		--AND		-- MOS 02-2023
				--mlo_isSaleOrderGenerated = 0




	UPDATE tbMercadoLibre_ordersDetail		WITH (ROWLOCK)
		SET	mlo_is4AvailableStock = 0
	FROM tbMercadoLibre_ordersDetail mloh		-- MOS 23-04-2020, idem arriba
		INNER JOIN @tmpMLOProcessed  tmp
			ON tmp.mlo_id = mloh.mlo_id
		WHERE	comp_id = @comp_id		--AND		MOS 02-2023
				--mlo_is4AvailableStock = 1




	DELETE FROM tbtmpTax				WITH (ROWLOCK)	WHERE tis_guid = @guid
	DELETE FROM tbTempItemStock			WITH (ROWLOCK)	WHERE tis_guid = @guid

	SET @return_value = @rv
	SET @errormessage = '#000 SaleOrder OK'





	-- ------------------------------------------------------------------------------------------------------



	-- ------------------------------------------------------------------------------------------------------
	-- Mandar notificacion al cliente del comienzo de proceso del pedido, como un Mensaje de la VENTA.-
	-- Haciendo un Insert de Mens en la processQueue
	-- ------------------------------------------------------------------------------------------------------

		DECLARE
			@mlp_id		INT,
			@mlipc_orderReceiptMessage							AS NVARCHAR(4000),
			@mlipc_orderReceiptMessageSQL						AS VARCHAR(8000),
			@mlipc_orderReceiptMessageInvoiceDataRequest		AS NVARCHAR(4000),
			@ML_id		BIGINT

		SELECT
			@mlp_id		= tmlip.mlp_id,
			@item_id	=	CASE
								WHEN @item_id > 0 THEN	@item_id		-- NO MODIFICAR, es para CAGADAS si sacas esto de acá !!!!!!!! NOOOOOOOO!!!!!!
								ELSE 					tmlip.item_id
							END,
			@stor_id						= tmls.stor_id,
			@mlipc_orderReceiptMessage		= ISNULL(tmlipc.mlipc_orderReceiptMessage,''),
			@mlipc_orderReceiptMessageInvoiceDataRequest = ISNULL(tmlipc.mlipc_orderReceiptMessageInvoiceDataRequest,''),
			@user_id						= tmls.[user_id],
			@mlipc_orderReceiptMessageSQL	= ISNULL(tmlipc.mlipc_orderReceiptMessageSQL,'')
		FROM tbMercadoLibre_ItemsPublicados			tmlip			WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_Stores		tmls			WITH (NOLOCK)
				ON	tmls.comp_id	= tmlip.comp_id		AND
					tmls.mls_id		= tmlip.mls_id
			INNER JOIN tbMercadoLibre_ItemsPublicadosCategories tmlipc	WITH (NOLOCK)
				ON	tmlipc.comp_id		= tmlip.comp_id AND
					tmlipc.mlipc_id		= tmlip.mlipc_id
		WHERE	tmlip.comp_id			= @comp_id	AND
				tmlip.mlp_publicationID = @mlp_PublicationID


		-- ------------------------------------------------------------------------------------------------------
		-- Verifica si DEBE mandar mens de carga del pedido y LO BORRA al toque.
		-- ------------------------------------------------------------------------------------------------------
		DECLARE	@mlo_isorderReceiptMessage AS BIT = 'False'	-- Verifica si YA no mandó los mens q se cargan al cargar un NUEVO pedido.
		SELECT	@mlo_isorderReceiptMessage	= ISNULL(tmloh.mlo_isorderReceiptMessage,'False'),
				@ML_id						= tmloh.ML_id
			FROM tbMercadoLibre_ordersHeader tmloh	WITH (NOLOCK)   --  mos 05-2022  LO AGREGUE PARA EVITAR BLOQUEOS YA QUE NO SE VE QUE SE USE EN OTRO LUGAR QUE NO SEA ESTO. Y COMO SE ELIMINIO LO DE ABAJIO.. SE SACA..	--WITH (NOLOCK)   NO PONERLO !!!
			WHERE	tmloh.comp_id	= @comp_id AND
					tmloh.mlo_id	= @mlo_id


		IF @mlo_isorderReceiptMessage = 'False'		-- MOS 05-2022: Agregue esto ya que es al pedo que lo sobreescriba si ya esta en true
			BEGIN
				UPDATE tbMercadoLibre_ordersHeader	WITH (ROWLOCK)
					SET	mlo_isorderReceiptMessage = 'True'
					WHERE	comp_id = @comp_id AND
							mlo_id	= @mlo_id
			END
		-- ------------------------------------------------------------------------------------------------------


		-- mos 05-2022: eLIMINADO
		-- ------------------------------------------------------------------------------------------------------
		-- Si tiene un Script SQL trata de ejecutarlo y sobre-escribe el Mensaje con el resultado.
		-- ------------------------------------------------------------------------------------------------------
		--IF	@mlo_isorderReceiptMessage		= 'False'	AND
		--	@mlipc_orderReceiptMessageSQL	<> ''		AND
		--	@bitIsFulFillment				= 'False'			-- MOS 27-12-2020: Si es FULL NO se debe mandar mens ya que es mnoderado.
		--	BEGIN
