CREATE PROCEDURE spMercadoLibre_ItemPublicado_GetBrandAndModelAttributes
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 1030
		*/
		-- ------------------------------------

		SELECT
			tmlipa.MLid,
			tmlipa.mlat_valueString,
			tmlipa.mlat_text4Combos
			FROM tbMercadoLibre_ItemsPublicadosAttributes AS tmlipa	WITH(NOLOCK)
			WHERE	tmlipa.comp_id	= @comp_id	AND
					tmlipa.mlp_id	= @mlp_id	AND
					(
						tmlipa.MLid = 'BRAND'				OR
						tmlipa.MLid = 'MODEL'				OR
						tmlipa.MLid = 'ALPHANUMERIC_MODEL'
					)

	END



GO




CREATE PROCEDURE [dbo].[spMercadoLibre_ItemPublicado_GetPrice4MercadoShops]
(
	@comp_id			INT,
	@mlp_PublicationID	NVARCHAR(30)
)
AS


BEGIN
	SET NOCOUNT ON

	-- ------------------------------------------
	-- TESTING
	-- ------------------------------------------
	/*
		DECLARE
			@comp_id			INT,
			@mlp_PublicationID	NVARCHAR(30)
		SELECT
			@comp_id			= 1,
			@mlp_PublicationID	= 'MLA630000366'
	*/
	-- ------------------------------------------

	-- ----------------------------------------
	-- VARIABLES DE TRABAJO
	-- ----------------------------------------
		DECLARE
			@lIntItem_ID				INT,
			@lintPrliId_4MercadoShops	INT,
			@ldecDeliveryPrice			DECIMAL(19,2),
			@ldecAdditionalPrice		DECIMAL(19,2),
			@mls_id					 AS INT,
			@curr_id				 AS INT,
			@curr_symbol			 AS NVARCHAR(10),
			@mlp_prli_id4MercadoShopPlusDeliveryCharge	AS BIT = 'False',
			@mlp_free_shippingMShops_Coeficient			AS DECIMAL(10,2) = 0

	-- ----------------------------------------


	-- ----------------------------------------------------------------------------
	-- RECUPERO EL PRLI_ID DE MSHOPS
	-- ----------------------------------------------------------------------------
		SELECT
			@lIntItem_ID				= tmlip.item_id,
			@lintPrliId_4MercadoShops	= ISNULL(tmlip.prli_id4MercadoShop,-1),
			@ldecDeliveryPrice			= ISNULL(tmlip.mlp_price4FreeShipping,0),
			@ldecAdditionalPrice		= ISNULL(tmlip.mlp_price4AdditionalCost,0),
			@mls_id						= tmlip.mls_id,
			@curr_id					= tmls.curr_id,
			@curr_symbol				= dbo.fnStrAllTrim(tc.curr_symbol),
			@mlp_prli_id4MercadoShopPlusDeliveryCharge
										= ISNULL(tmlip.mlp_prli_id4MercadoShopPlusDeliveryCharge,'False'),
			@mlp_free_shippingMShops_Coeficient
										= ISNULL(tmlip.mlp_free_shippingMShops_Coeficient,0)
		FROM tbMercadoLibre_ItemsPublicados			AS tmlip	WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_Stores			AS tmls		WITH (NOLOCK)
			ON	tmls.comp_id			= tmlip.comp_id AND
				tmls.mls_id				= tmlip.mls_id
		INNER JOIN tbsysCurrency					AS tc		WITH (NOLOCK)
			ON tc.curr_id = tmls.curr_id
		WHERE	tmlip.comp_id			= @comp_id	AND
				tmlip.mlp_publicationID = @mlp_PublicationID
	-- ----------------------------------------------------------------------------

	IF @mlp_prli_id4MercadoShopPlusDeliveryCharge = 'False'
		BEGIN
			SET @ldecDeliveryPrice = 0
		END


	-- MOS 08-2022
	IF @mlp_free_shippingMShops_Coeficient = 0
		BEGIN
			SET @mlp_free_shippingMShops_Coeficient = 1
		END
	SET @ldecDeliveryPrice = @ldecDeliveryPrice * @mlp_free_shippingMShops_Coeficient
	-- MOS 08-2022



	-- SI NO TIENE LISTA DE PRECIOS, NO PUEDO ACTUALIZAR EL PRECIO, DEVUELVO 0.
	-- MOS 08-2022, aclaracion.
	-- IMPORTANTE: Si devuelve 0 CERO, Luego lo atrapa la funcion funMercadoLibre_Publication_UpdateMercadoShopPrice y si tiene 0 NO pone precio diferenciado para mShops.
	IF @lintPrliId_4MercadoShops = -1
		BEGIN
			SELECT
				0		[mlp_pricePlusTax],
				'ARS'	[curr_symbol]
		END
	ELSE
		BEGIN

			IF NOT EXISTS (
							SELECT TOP 1 1
								FROM tbPriceListItems AS tpli	WITH (NOLOCK)
								WHERE	tpli.comp_id = @comp_id AND
										tpli.prli_id = @lintPrliId_4MercadoShops	AND
										tpli.item_id = @lIntItem_ID
							)
				BEGIN
					SELECT
						0		[mlp_pricePlusTax],
						'ARS'	[curr_symbol]
					RETURN
				END


			-- LE TENGO QEU SUMAR EL ADICIONAL Y EL GASTO DE ENVIO???
			SELECT
				CONVERT(DECIMAL(25,2),
				dbo.fnGetExchange2( @comp_id,
									CONVERT(DECIMAL(25,2),
												tpli.prli_price
												+
												(tpli.prli_price  * ISNULL(ttnIVA.tax_percentage,0) / 100)
												+
												(tpli.prli_price  * ISNULL(ttnII.tax_percentage,0) / 100)
											),
											tpli.curr_id,
											@curr_id,
											0,
											0,
											0,
											'False') )
											+
											@ldecDeliveryPrice -- MOS 10-2021 sug PLayRoom
									[mlp_pricePlusTax], --@ldecDeliveryPrice + @ldecAdditionalPrice
				@curr_symbol							[curr_symbol]

			FROM tbPriceListItems								AS tpli		WITH(NOLOCK)

				INNER JOIN tbsysCurrency						tc2			WITH (NOLOCK)
					ON  tc2.curr_id		= tpli.curr_id
				LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit				WITH (NOLOCK)
					ON 	vitooit.comp_id = tpli.comp_id AND
						vitooit.item_id = tpli.item_id

				LEFT JOIN tbTaxName								ttnIVA		WITH (NOLOCK)
					ON	ttnIVA.comp_id  = vitooit.comp_id AND
						ttnIVA.tax_id   = vitooit.tax_id

				LEFT JOIN vwItemTaxesOnlyOneInternalTax			vitooit2	WITH (NOLOCK)
					ON 	vitooit2.comp_id = tpli.comp_id AND
						vitooit2.item_id = tpli.item_id

				LEFT JOIN tbTaxName								ttnII		WITH (NOLOCK)
					ON	ttnII.comp_id   = vitooit2.comp_id AND
						ttnII.tax_id    = vitooit2.tax_id
			WHERE	tpli.comp_id = @comp_id						AND
					tpli.prli_id = @lintPrliId_4MercadoShops	AND
					tpli.item_id = @lIntItem_ID
		END


END









GO

CREATE PROCEDURE spMercadoLibre_ItemPublicado_GetTotalSalePrice
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	--**987489738947238ASKJDKLASD
	-- SI SE TOCA ALGO ACA TOCAR TAMBIEN EN spMercadoLibre_ItemsPublicados_GetDataByFilters
	BEGIN
		SET NOCOUNT ON

		SELECT
			CONVERT(DECIMAL(25,2),(
									(
										tmlip.mlp_price +
										(tmlip.mlp_price  * ISNULL(ttnIVA.tax_percentage,0) / 100)
											+
										(tmlip.mlp_price  * ISNULL(ttnII.tax_percentage,0) / 100)
									)
										/  ( (ISNULL(tmlip.mlp_priceDirectDiscountPercenage,0) / 100) + 1 )
								  )
								+
									ISNULL(tmlip.mlp_price4AdditionalCost,0)
								+   ISNULL(tmlip.mlp_price4FreeShipping,0)
					)														[totalSale]

		FROM tbMercadoLibre_ItemsPublicados					AS tmlip	WITH(NOLOCK)
			INNER JOIN tbItem								ti			WITH(NOLOCK)
				ON	ti.comp_id		= tmlip.comp_id			AND
					ti.item_id		= tmlip.item_id
			LEFT JOIN vwItemTaxesOnlyOneIvaTax				vitooit		WITH(NOLOCK)
				ON 	vitooit.comp_id = ti.comp_id			AND
					vitooit.item_id = ti.item_id
			LEFT JOIN tbTaxName								ttnIVA		WITH(NOLOCK)
				ON	ttnIVA.comp_id  = vitooit.comp_id		AND
					ttnIVA.tax_id   = vitooit.tax_id
			LEFT JOIN vwItemTaxesOnlyOneInternalTax			vitooit2	WITH(NOLOCK)
				ON 	vitooit2.comp_id = ti.comp_id			AND
					vitooit2.item_id = ti.item_id
			LEFT JOIN tbTaxName ttnII						WITH (NOLOCK)
				ON	ttnII.comp_id   = vitooit2.comp_id		AND
					ttnII.tax_id    = vitooit2.tax_id
		WHERE	tmlip.comp_id		= @comp_id				AND
				tmlip.mlp_id		= @mlp_id

	END

GO



CREATE PROCEDURE [dbo].[spMercadoLibre_ItemPublicadoAttributes_GetAttributes4SizeChart]
(
	@comp_id		INT,
	@mlp_id			INT,
	@strAttributes	NVARCHAR(4000)
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@mlp_id			INT,
				@strAttributes	NVARCHAR(4000)

			SELECT
				@comp_id		= 1,
				@mlp_id			= 1150,
				@strAttributes	= 'BRAND|GENDER|'
		*/
		-- ----------------------------------------------------

		-- CREO UNA TABLA EN DONDE GUARDO TODOS LOS ATRIBUTOS QUE DEBO ENVIAR COMO FILTRO
		DECLARE @tblAttributes TABLE (ID NVARCHAR(100))

		-- HAGO UN SPLIT A TABLA DEL STRING QUE ENVIO DESDE EL SISTEMA Y LO INSERTO
		INSERT INTO @tblAttributes
		(
			ID
		)
		SELECT
			fst.items
		FROM
			dbo.fnSplitTable(@strAttributes,'|') AS fst

		--BORRO LO QUE TENGA VALOR ''
		DELETE FROM @tblAttributes WHERE ID = ''

		-- ME TRAIGO TODOS LOS ATRIBUTOS CON SUS VALORES PARA LA PUBLICACION ELEGIDA
		SELECT
			tmlipa.MLid,
			tmlipa.MLname,
			tmlipa.MLvalue_type,
			tmlipa.mlat_valueString,
			tmlipa.mlat_id,
			tmlipa.MLnumberUnitSelectedValue,
			tmlipa.mlat_text4Combos,
			tmlipa.mlat_isAlternativeValue
		FROM tbMercadoLibre_ItemsPublicadosAttributes	AS tmlipa	WITH(NOLOCK)
			INNER JOIN @tblAttributes					tmp
			ON	tmp.ID			= tmlipa.MLid
		WHERE	tmlipa.comp_id	= @comp_id				AND
				tmlipa.mlp_id	= @mlp_id


	END


GO


CREATE PROCEDURE spMercadoLibre_ItemPublicados_CloneAttributesData
(
	@comp_id		INT,
	@mlp_id_origin	INT,
	@mlp_id_destiny	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------
		-- TESTING
		-- --------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@mlp_id_origin	INT,
				@mlp_id_Destiny	INT
			SELECT
				@comp_id		= 1,
				@mlp_id_origin	= 1591,
				@mlp_id_Destiny	= 1593
		*/
		-- --------------------------------------

		-- -----------------------------------------------------------------------------------------
		-- CLONO LOS ATRIBUTOS DE LA PUBLICACION
		-- -----------------------------------------------------------------------------------------
			INSERT INTO tbMercadoLibre_ItemsPublicadosAttributes
			(
				comp_id,
				mlp_id,
				MLid,
				MLname,
				MLtooltip,
				MLvalue_type,
				MLvalue_max_length,
				MLfixed,
				mlat_valueString,
				--mlat_id,
				MLnumberUnitSelectedValue,
				mlat_text4Combos,
				mlat_isAlternativeValue
			)
			SELECT
				tmlipa.comp_id,
				@mlp_id_destiny,
				tmlipa.MLid,
				tmlipa.MLname,
				tmlipa.MLtooltip,
				tmlipa.MLvalue_type,
				tmlipa.MLvalue_max_length,
				tmlipa.MLfixed,
				tmlipa.mlat_valueString,
				--tmlipa.mlat_id,
				tmlipa.MLnumberUnitSelectedValue,
				tmlipa.mlat_text4Combos,
				tmlipa.mlat_isAlternativeValue
				FROM tbMercadoLibre_ItemsPublicadosAttributes	tmlipa	WITH(NOLOCK)
				WHERE	tmlipa.comp_id	= @comp_id				AND
						tmlipa.mlp_id	= @mlp_id_origin
		-- -----------------------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------------------
		-- CLONO LAS VARIACIONES Y SUS ATRIBUTOS
		-- -----------------------------------------------------------------------------------------
			DECLARE
				@mlpv_id		INT,
				@mlp_id			INT,
				@item_id		INT,
				@mlpv_disabled	BIT

			DECLARE cursor_VariationAttributes CURSOR FOR
				--ACA HAGO EL SELECT DE LAS VARIACIONES
				SELECT
					tmlipv.mlpv_id,
					tmlipv.mlp_id,
					tmlipv.item_id,
					tmlipv.mlpv_disabled
				FROM tbMercadoLibre_ItemsPublicadosVariations tmlipv	WITH(NOLOCK)
				WHERE	tmlipv.comp_id = @comp_id				AND
						tmlipv.mlp_id  = @mlp_id_origin

			OPEN	cursor_VariationAttributes
			FETCH cursor_VariationAttributes
			INTO
				@mlpv_id,
				@mlp_id,
				@item_id,
				@mlpv_disabled

			WHILE   @@FETCH_STATUS = 0
				BEGIN

					DECLARE @mlpv_id_LOCAL	INT
					--PRIMERO INSERTO LA VARIACIÖN
					INSERT INTO tbMercadoLibre_ItemsPublicadosVariations
					(
						comp_id,
						mlp_id,
						item_id,
						mlpv_disabled
					)
					VALUES
					(
						@comp_id,
						@mlp_id_Destiny,
						@item_id,
						@mlpv_disabled
					)
					SET @mlpv_id_LOCAL = @@IDENTITY

					-- -----------------------------------------------------------------------------
					-- CON EL NUEVO ID CLONO LOS ATRIBUTOS DE LA VARIACIÖN
					-- -----------------------------------------------------------------------------
					INSERT INTO tbMercadoLibre_ItemsPublicadosVariations_Combinations
					(
						comp_id,
						mlpv_id,
						attribute_combinations_name,
						attribute_combinations_value_id,
						attribute_combinations_value_name,
						mlpvc_disabled,
						MLattributeID,
						MLnumberUnitSelectedValue,
						mlat_text4Combos,
						mlat_isAlternativeValue,
						MLtooltip,
						MLvalue_type,
						MLvalue_max_length,
						MLfixed,
						mlat_valueString
					)
					SELECT
						tmlipvc.comp_id,
						@mlpv_id_LOCAL,
						tmlipvc.attribute_combinations_name,
						tmlipvc.attribute_combinations_value_id,
						tmlipvc.attribute_combinations_value_name,
						tmlipvc.mlpvc_disabled,
						tmlipvc.MLattributeID,
						tmlipvc.MLnumberUnitSelectedValue,
						tmlipvc.mlat_text4Combos,
						tmlipvc.mlat_isAlternativeValue,
						tmlipvc.MLtooltip,
						tmlipvc.MLvalue_type,
						tmlipvc.MLvalue_max_length,
						tmlipvc.MLfixed,
						tmlipvc.mlat_valueString
						FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations	tmlipvc WITH(NOLOCK)
						WHERE	tmlipvc.comp_id = @comp_id							AND
								tmlipvc.mlpv_id = @mlpv_id
					-- -----------------------------------------------------------------------------
				FETCH 	cursor_VariationAttributes
				INTO
					@mlpv_id,
					@mlp_id,
					@item_id,
					@mlpv_disabled
				END
				CLOSE cursor_VariationAttributes
				DEALLOCATE cursor_VariationAttributes
	END


GO


CREATE PROCEDURE spMercadoLibre_ItemPublicados_EnabledVariationsQtyByMLPID
(
	@comp_id			INT,
	@mlp_id				INT,
	@qtyFromPublicator	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@mlp_id				INT,
				@qtyFromPublicator	INT
			SELECT
				@comp_id			= 1,
				@mlp_id				= 1185,
				@qtyFromPublicator	= 33
		*/
		-- ----------------------------------------------------

		-- ---------------------------
		-- Variables de Trabajo
		-- ---------------------------
		DECLARE
			@lint_ReturnQty		INT
			SET @lint_ReturnQty = 0
		-- ---------------------------
		--Cuento la cantida de variaciones que la publicación tiene cargadas y que NO esten deshabilitadas
		SELECT
				@lint_ReturnQty  = COUNT(*)
		FROM tbMercadoLibre_ItemsPublicadosVariations	tmlipv
		WHERE	tmlipv.comp_id			= @comp_id		AND
				tmlipv.mlp_id			= @mlp_id		AND
				tmlipv.mlpv_disabled	= 'False'

		--En caso de que la cantidad sea 0(CERO), devuelvo la cantidad que cargó en el control de Cantidad en el Formulario
		IF @lint_ReturnQty = 0
			BEGIN
				SET @lint_ReturnQty = @qtyFromPublicator
			END

		SELECT @lint_ReturnQty	[ReturnQty]

	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_Items_GetItems4MassivePublication]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@prof_id				INT,
	@ItemGuid				UNIQUEIDENTIFIER,
	@mls_id					INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@user_id				INT,
				@prof_id				INT,
				@ItemGuid				UNIQUEIDENTIFIER,
				@mls_id					INT
			SELECT
				@comp_id				= 1,
				@lang_id				= 2,
				@bra_id					= 1,
				@user_id				= 10001,
				@prof_id				= 1,
				@ItemGuid				= 'cb52deaa-fd79-40a9-8cfb-f874ee4a25e3',
				@mls_id					= 4
		*/
		-- ---------------------------------------------------------------

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
			DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
			INSERT INTO @tblComplexFilter_Items
				SELECT
					tcf.sl_id
					FROM tbComplexFilter tcf
					WHERE tcf.sl_guid = @ItemGuid     AND
						  tcf.sl_selected = 'True'
			IF @@ROWCOUNT = 0
				BEGIN
					INSERT INTO @tblComplexFilter_Items
						SELECT
							ti.item_id
							FROM tbItem ti
							WHERE ti.comp_id = @comp_id
				END
			--SELECT * FROM @tblComplexFilter_Items
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- ACA BORRA TODOS LOS ARTÍCULOS QUE ESTAN PUBLICADOS DE LA TABLA
		-- DE SELECCION PARA LA TIENDA ACTUAL
		-- -------------------------------------------------------------
			DELETE @tblComplexFilter_Items
			FROM @tblComplexFilter_Items tmp
			INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip
			ON	tmlip.comp_id = @comp_id				AND
				tmlip.item_id = tmp.item_id				AND
				tmlip.mls_id  = @mls_id
		-- -------------------------------------------------------------

		SELECT
			ti.item_id,
			ti.item_code,
			ti.item_desc,
			ISNULL(ti.item_ML_title,'')													[item_ML_title],
			ISNULL(ti.item_ML_desc,'')													[item_ML_desc],
			ISNULL(ti.item_ML_html4Publication,'')										[item_ML_html4Publication],
			ISNULL(ti.item_ML_url4video,'')												[item_ML_url4video],
			ISNULL(ti.item_descHTML,'')													[item_descHTML],
			ISNULL(item_WebSite_desc,'')												[item_WebSite_desc],
			ISNULL(ti.item_annotation,'')												[item_annotation],
			ISNULL(ti.item_guarantee,0)													[item_guarantee]
		FROM tbItem ti
		INNER JOIN @tblComplexFilter_Items	tmp
			ON ti.item_id = tmp.item_id

	END
GO

