CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_BranchsRelations_GetDataByMLPID]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 1150
		*/
		-- -----------------------------------------------------------

		SELECT
			''																					[1],	--MARCAR REGISTRO
			''																					[2],	--MODIFICAR HORAS
			CONVERT(BIT,CASE WHEN tmlipbr.comp_id IS NULL THEN 0 ELSE 1 END)					[Checked],
			tmlb.mlbra_desc,
			ISNULL(tmlipbr.MLavailability_time_in_hours,0)										[Availability_time_in_hours],
			--tmlipbr.mlpbr_disabled,
			tmlipbr.mlpbr_Status,
			--tmlipbr.mlpbr_lastSynchStatus,
			--tmlipbr.mlbra_minQTY4LocalPicking,
			tmlb.mlbra_id																		[ID]
			FROM tbMercadoLibre_Branchs									tmlb
			LEFT JOIN tbMercadoLibre_ItemsPublicados_BranchsRelations	tmlipbr
				ON	tmlipbr.comp_id		= tmlb.comp_id					AND
					tmlipbr.mlbra_id	= tmlb.mlbra_id					AND
					tmlipbr.mlp_id		= @mlp_id
			WHERE	tmlb.comp_id		= @comp_id						AND
					--tmlipbr.mlp_id		= @mlp_id						AND
					ISNULL(tmlb.mlbra_disabled,'False') = 'False'

	END
GO

