CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_BranchsRelations_MarkOrUnMarkBranch]
(
	@comp_id	INT,
	@user_id	INT,
	@mlbra_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlbra_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlbra_id	= 1,
				@mlp_id		= 170
		*/
		-- -------------------------------------------------------

		--SI EXISTE INDICA QUE ESTÁ MARCADO, SI NO EXISTE, LO GENERAMOS CON LAS HORAS DISPONIBLES DE LA SUCURSAL QUE MARCA
		IF EXISTS (SELECT
						1
						FROM tbMercadoLibre_ItemsPublicados_BranchsRelations	tmlipbr
						WHERE	tmlipbr.comp_id		= @comp_id					AND
								tmlipbr.mlbra_id	= @mlbra_id					AND
								tmlipbr.mlp_id		= @mlp_id)
			BEGIN
				DELETE FROM tbMercadoLibre_ItemsPublicados_BranchsRelations
				WHERE	comp_id		= @comp_id	AND
						mlbra_id	= @mlbra_id AND
						mlp_id		= @mlp_id

			-- ----------------------------------------------------------------------------------------------
			-- GENERAMOS UN REGISTRO EN LA PROCESS QUEUE PARA QUE ELIMINE ESTA SUCURSAL DE LA PUBLICACIÓN
			-- ----------------------------------------------------------------------------------------------
				INSERT INTO tbMercadoLibre_updateQueue
				(
					comp_id,
					mlp_id,
					mlproc_cd,
					[user_id],
					mlproc_option,
					mlproc_integerValue,
					mlproc_decimalValue,
					mlproc_priority
				)
				VALUES
				(
					@comp_id,
					@mlp_id,
					GETDATE(),
					@user_id,
					35,
					@mlbra_id,
					0,
					30050
				)
			-- ----------------------------------------------------------------------------------------------
			END
		ELSE
			BEGIN

				DECLARE
					@Availability_Time_In_Hours AS INT
				SELECT
					@Availability_Time_In_Hours			= tmlb.mlbra_availability_time_in_hours
					FROM tbMercadoLibre_Branchs			tmlb
					WHERE	tmlb.comp_id	= @comp_id	AND
							tmlb.mlbra_id	= @mlbra_id

				INSERT INTO tbMercadoLibre_ItemsPublicados_BranchsRelations
				(
					comp_id,
					mlbra_id,
					mlp_id,
					MLavailability_time_in_hours,
					mlpbr_disabled,
					mlpbr_Status,
					mlpbr_lastSynchStatus,
					mlbra_minQTY4LocalPicking
				)
				VALUES
				(
					@comp_id,
					@mlbra_id,
					@mlp_id,
					@Availability_Time_In_Hours,
					'False',
					NULL,
					NULL,
					NULL
				)

				-- ----------------------------------------------------------------------------------------------
				-- GENERAMOS UN REGISTRO EN LA PROCESS QUEUE PARA QUE INSERTE ESTA SUCURSAL DE LA PUBLICACIÓN
				-- ----------------------------------------------------------------------------------------------
				INSERT INTO tbMercadoLibre_updateQueue
				(
					comp_id,
					mlp_id,
					mlproc_cd,
					[user_id],
					mlproc_option,
					mlproc_integerValue,
					mlproc_decimalValue,
					mlproc_priority
				)
				VALUES
				(
					@comp_id,
					@mlp_id,
					GETDATE(),
					@user_id,
					30,
					@mlbra_id,
					@Availability_Time_In_Hours,
					30000
				)
				-- ----------------------------------------------------------------------------------------------
			END

	END





GO


