CREATE PROCEDURE [dbo].[spMercadolibre_ItemsPublicados_CanItemBePublicatedByStockAvailability]
(
	@comp_id	INT,
	@mls_id		INT,
	@item_id	INT,
	@qty		INT
)
AS

	BEGIN
		SET NOCOUNT	 ON

		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mls_id		INT,
				@item_id	INT,
				@qty		INT
			SELECT
				@comp_id	= 1,
				@mls_id		= 5,
				@item_id	= 15554,
				@qty		= 10
		*/
		-- --------------------------------------------

		/*
		NOTA 23-03-18 STL cambie el >= por > solamente
		*/


		DECLARE
			@lstor_id4StockAvailability	INT

		SELECT
			@lstor_id4StockAvailability = tmls.stor_id4StockAvailability
			FROM tbMercadoLibre_Stores			tmls		WITH (NOLOCK)
			WHERE	tmls.comp_id	= @comp_id	AND
					tmls.mls_id		= @mls_id

		DECLARE @decStock AS DECIMAL(19,4)
		SET		@decStock = ISNULL(dbo.fnGetAStock4MaxAssociation(@comp_id, @lstor_id4StockAvailability, @item_id,999999999),0)

		SELECT
			CASE
				WHEN @decStock > 0 /* Si hay que publique !!!!!!!!!!@qty*/ THEN	'True'
				ELSE						'False'
			END																[CanItemBePublicated],
			@decStock														[StockAvailable]

	END

GO



CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_CloneAllPublicationData]
(
	@comp_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@prof_id				INT,
	@mlp_Origin				INT,
	@mlp_listing_type_id	NVARCHAR(100),
	@prli_id				INT,
	@stor_id				INT,
	@Guid4Selection			UNIQUEIDENTIFIER,
	@lstrPublicationTitle	NVARCHAR(100),
	@mls_id_to				INT,
	@freeShipping			INT,
	@mlPublicatioNChannel	INT,
	@mlipc_id				INT

)
AS

	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@bra_id					INT,
				@user_id				INT,
				@prof_id				INT,
				@mlp_Origin				INT,
				@mlp_listing_type_id	NVARCHAR(100),
				@prli_id				INT,
				@stor_id				INT
			SELECT
				@comp_id				= 1,
				@bra_id					= 1,
				@user_id				= 1,
				@prof_id				= 1,
				@mlp_Origin				= 1179,
				@mlp_listing_type_id	= 'gold',
				@prli_id				= 1,
				@stor_id				= 3
		*/
		-- ---------------------------------------------------------


		--CLONAMOS LA PUBLICACIÓN
		INSERT INTO tbMercadoLibre_ItemsPublicados
		(
			comp_id,
			--mlp_id,
			bra_id,
			stor_id,
			prli_id,
			item_id,
			mlp_initQty,
			mlp_price,
			curr_id,
			optval_statusId,
			mlp_inicDate,
			mlp_endDate,
			mlp_lastUpdate,
			[user_id],
			mlp_Active,
			mlp_itemHTML2,
			mlp_itemHTML3,
			mls_id,
			mlp_itemTitle,
			mlp_minQty4Pause,
			mlp_listing_type_id,
			mlp_listing_fee_amount,
			mlp_sale_fee_amount,
			mlp_buying_mode,
			mlp_itemSubTitle,
			mlp_start_time,
			mlp_stop_time,
			mlp_sold_quantity,
			mlp_permalink,
			mlp_thumbnail,
			mlp_video_id,
			mlp_accepts_mercadopago,
			mlp_warranty,
			mlp_local_pick_up,
			mlp_free_shipping,
			mlp_publicationCategoryID,
			mlp_subTitle,
			mlipc_id,
			mlp_isFixedPrice,
			mlp_lastPublicatedPrice,
			mlp_lastPublicatedCurrID,
			st_id,
			disc_id,
			dl_id,
			mlp_free_method,
			mlmp_id,
			mlp_itemDesc,
			mlp_itemHTML,
			mlp_lastJSonValidation,
			mlp_allowPublicationsWithNoStock,
			mlp_creationDate,
			mlp_lastPublicatedExchange,
			mlp_force2CheckStock,
			mlp_price4FreeShipping,
			mlp_lastPublicatedAvailableQTY,
			mlp_4Revision,
			mlp_revisionMessage,
			mlp_official_store_id,
			mlp_lastStatusID,
			mlp_price4AdditionalCost,
			mlp_priceDirectDiscountPercenage,
			mlp_channelID
		)
		SELECT
			tmlip.comp_id,
			--tmlip.mlp_id,
			tmlip.bra_id,
			@stor_id,
			@prli_id,
			tmlip.item_id,
			tmlip.mlp_initQty,
			CASE
				WHEN tpli.comp_id IS NOT NULL THEN	dbo.fnGetExchange2(@comp_id,tpli.prli_price,tpli.curr_id,1,0,0,0,'False')
				ELSE								tmlip.mlp_price
			END,
			--tmlip.mlp_price,
			tmlip.curr_id,
			tmlip.optval_statusId,
			tmlip.mlp_inicDate,
			tmlip.mlp_endDate,
			tmlip.mlp_lastUpdate,
			tmlip.[user_id],
			tmlip.mlp_Active,
			tmlip.mlp_itemHTML2,
			tmlip.mlp_itemHTML3,
			--tmlip.mls_id,
			@mls_id_to,
			CASE WHEN @lstrPublicationTitle = '' THEN	tmlip.mlp_itemTitle
			ELSE										@lstrPublicationTitle
			END,
			tmlip.mlp_minQty4Pause,
			@mlp_listing_type_id,
			tmlip.mlp_listing_fee_amount,
			tmlip.mlp_sale_fee_amount,
			tmlip.mlp_buying_mode,
			tmlip.mlp_itemSubTitle,
			tmlip.mlp_start_time,
			tmlip.mlp_stop_time,
			tmlip.mlp_sold_quantity,
			NULL,
			NULL,
			tmlip.mlp_video_id,
			tmlip.mlp_accepts_mercadopago,
			tmlip.mlp_warranty,
			tmlip.mlp_local_pick_up,
			CASE WHEN @freeShipping = -1 THEN	tmlip.mlp_free_shipping
			ELSE								@freeShipping
			END,
			tmlip.mlp_publicationCategoryID,
			tmlip.mlp_subTitle,
			CASE WHEN @mlipc_id = -1 THEN	tmlip.mlipc_id
			ELSE							@mlipc_id
			END,
			tmlip.mlp_isFixedPrice,
			0, -- MOS 08-2021, sino NO ACTUALIZA UN PUTOI PREWCIO SI ES QUE CAMBIO X ELK MISMOOOO
			tmlip.mlp_lastPublicatedCurrID,
			tmlip.st_id,
			tmlip.disc_id,
			tmlip.dl_id,
			tmlip.mlp_free_method,
			tmlip.mlmp_id,
			tmlip.mlp_itemDesc,
			tmlip.mlp_itemHTML,
			tmlip.mlp_lastJSonValidation,
			tmlip.mlp_allowPublicationsWithNoStock,
			tmlip.mlp_creationDate,
			tmlip.mlp_lastPublicatedExchange,
			tmlip.mlp_force2CheckStock,
			tmlip.mlp_price4FreeShipping,
			tmlip.mlp_lastPublicatedAvailableQTY,
			tmlip.mlp_4Revision,
			tmlip.mlp_revisionMessage,
			tmlip.mlp_official_store_id,
			tmlip.mlp_lastStatusID,
			tmlip.mlp_price4AdditionalCost,
			tmlip.mlp_priceDirectDiscountPercenage,
			@mlPublicatioNChannel
		FROM tbMercadoLibre_ItemsPublicados tmlip	WITH (NOLOCK)
		LEFT JOIN tbPriceListItems			tpli	WITH (NOLOCK)
			ON 	tpli.comp_id = @comp_id AND
				tpli.prli_id = @prli_id AND
				tpli.item_id = tmlip.item_id
		WHERE	tmlip.comp_id	= @comp_id	AND
				tmlip.mlp_id	= @mlp_Origin

		DECLARE
			@intLocal_mlp_id	INT
		SET @intLocal_mlp_id = @@IDENTITY

		--CLONAMOS LOS ATRIBUTOS, VARIACIONES, ATRIBUTOS DE VARIACIONES
		EXEC spMercadoLibre_ItemPublicados_CloneAttributesData @comp_id, @mlp_Origin, @intLocal_mlp_id

		--GENERAMOS EL REGISTRO EN LA PROCESSQUEUE PARA QUE HAGA LA PUBLICACIÓN
		INSERT INTO tbMercadoLibre_updateQueue
		(
			comp_id,
			mlp_id,
			mlproc_cd,
			[user_id],
			mlproc_option,
			mlproc_stringValue,
			mlproc_integerValue,
			mlproc_decimalValue,
			mlproc_priority,
			mlproc_guid,
			mlproc_textValue
		)
		SELECT
			@comp_id,
			@intLocal_mlp_id,
			GETDATE(),
			@user_id,
			1,
			'',
			0,
			0,
			-99999999,
			@Guid4Selection,
			''

		--GENERAMOS EL INSERT PARA EL REGISTRO DE VARIACIONES
		INSERT INTO tbMercadoLibre_updateQueue
		(
			comp_id,
			mlp_id,
			mlproc_cd,
			[user_id],
			mlproc_option,
			mlproc_stringValue,
			mlproc_integerValue,
			mlproc_decimalValue,
			mlproc_priority,
			mlproc_guid,
			mlproc_textValue
		)
		SELECT
			@comp_id,
			@intLocal_mlp_id,
			GETDATE(),
			@user_id,
			22,
			'',
			0,
			0,
			-999999,
			@Guid4Selection,
			''


	END

GO

