CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_DeleteAllData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@user_id	INT,
	@prof_id	INT,
	@mlp_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------
		-- TESTING
		-- -----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@user_id	INT,
				@prof_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 1,
				@bra_id		= 1,
				@user_id	= 1,
				@prof_id	= 1,
				@mlp_id		= 1
		*/
		-- -----------------------------------------------

		-- ---------------------------------------------------------
		-- RECUPERO LA URL DE LA PUBLICACIÓN ANTES DE BORRARLA
		-- ---------------------------------------------------------
		DECLARE
			@ML_URL NVARCHAR(1000)
		SELECT
			@ML_URL = tmlip.mlp_permalink
		FROM tbMercadoLibre_ItemsPublicados tmlip	WITH(NOLOCK)
		WHERE	tmlip.comp_id	= @comp_id	AND
				tmlip.mlp_id	= @mlp_id
		-- ---------------------------------------------------------

		-- ---------------------------------------------------------------------------------------------------------------------------
		-- SI TIENE ORDEN DE MELI ASOCIADA NO PUEDE BORRARLA
		-- ---------------------------------------------------------------------------------------------------------------------------
		IF EXISTS (SELECT
					1
					FROM tbMercadoLibre_ordersHeader			tmloh	WITH(NOLOCK)
					INNER JOIN tbMercadoLibre_ordersDetail		tmlod	WITH(NOLOCK)
					ON	tmlod.comp_id		= tmloh.comp_id		AND
						tmlod.mlo_id		= tmloh.mlo_id
					WHERE	tmloh.comp_id	= @comp_id			AND
							tmlod.mlp_id	= @mlp_id)
			BEGIN
				SELECT 'No se puede borrar la públicación porque la misma tiene una Orden de MercadoLibre© asociada'		[Message]
				RETURN
			END
		-- ---------------------------------------------------------------------------------------------------------------------------

		-- ---------------------------------------------------------------------------------------------------------------------------
		-- SI TIENE PREGUNTAS ASOCIADAS A LA PUBLICACION, NO PUEDE SER BORRADA
		-- ---------------------------------------------------------------------------------------------------------------------------
		IF EXISTS(SELECT
					1
					FROM tbMercadoLibre_QuestionsAndAnswers tmlqaa	WITH(NOLOCK)
					WHERE	tmlqaa.comp_id	= @comp_id		AND
							tmlqaa.mlp_id	= @mlp_id)
			BEGIN
				SELECT 'No se puede borrar la públicación porque la misma tiene una Preguntas de MercadoLibre© asociadas'	[Message]
				RETURN
			END
		-- ---------------------------------------------------------------------------------------------------------------------------

		-- ---------------------------------------------------------------------------------------------------------------------------
		-- BORRADO DE LA PUBLICACIÓN
		-- ---------------------------------------------------------------------------------------------------------------------------
		-- -----------------------------------------------------------------------------------
		--BORRO PROCESSQUEUE
		-- -----------------------------------------------------------------------------------
		DELETE FROM tbMercadoLibre_updateQueue
		WHERE	comp_id = @comp_id AND
				mlp_id	= @mlp_id
		-- -----------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------
		--BORRO ATRIBUTOS
		-- -----------------------------------------------------------------------------------
		DELETE FROM tbMercadoLibre_ItemsPublicadosAttributes
		WHERE	comp_id	= @comp_id AND
				mlp_id	= @mlp_id
		-- -----------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------
		--BORRO ATRIBUTOS DE LAS VARIACIONES
		-- -----------------------------------------------------------------------------------
		DELETE tbMercadoLibre_ItemsPublicadosVariations_Combinations
		FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations	tmlipvc	WITH(NOLOCK)
		INNER JOIN tbMercadoLibre_ItemsPublicadosVariations			tmlipv	WITH(NOLOCK)
		ON	tmlipv.comp_id		= tmlipvc.comp_id					AND
			tmlipv.mlpv_id		= tmlipvc.mlpv_id
		WHERE	tmlipv.comp_id	= @comp_id							AND
				tmlipv.mlp_id	= @mlp_id
		-- -----------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------
		--BORRO ATRIBUTOS DE LAS VARIACIONES - NUEVA TABLA
		-- -----------------------------------------------------------------------------------
		DELETE FROM tbMercadoLibre_ItemsPublicadosVariations_Attributes
		FROM tbMercadoLibre_ItemsPublicadosVariations_Attributes	tmlipvc	WITH(NOLOCK)
		INNER JOIN tbMercadoLibre_ItemsPublicadosVariations			tmlipv	WITH(NOLOCK)
		ON	tmlipv.comp_id		= tmlipvc.comp_id					AND
			tmlipv.mlpv_id		= tmlipvc.mlpv_id
		WHERE	tmlipv.comp_id	= @comp_id							AND
				tmlipv.mlp_id	= @mlp_id
		-- -----------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------
		--UNA VEZ BORRADOS LOS ATRIBUTOS DE LAS VARIACIONES
		--BORRO LAS MISMAS
		-- -----------------------------------------------------------------------------------
		DELETE FROM tbMercadoLibre_ItemsPublicadosVariations
		WHERE	comp_id = @comp_id AND
				mlp_id	= @mlp_id
		-- -----------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------
		-- BORRO LA PUBLICACIÓN
		-- -----------------------------------------------------------------------------------
		DELETE FROM tbMercadoLibre_ItemsPublicados
		WHERE	comp_id = @comp_id AND
				mlp_id	= @mlp_id
		-- -----------------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------------
		-- GUARDAMOS EL LOG DE QUIEN REALIZO EL BORRADO DE LA PUBLICACION
		-- -----------------------------------------------------------------------------------
		DECLARE
			@description NVARCHAR(500)
		SELECT
			@description		= tut.utexts_desc
		FROM tbsysUniqueTexts				tut	WITH(NOLOCK)
		WHERE	tut.lang_id		= @lang_id	AND
				tut.utexts_id	= 40315


		INSERT INTO tbSecurityLog
		(
			comp_id,
			bra_id,
			[user_id],
			seclog_obs_1,
			seclog_obs_2,
			seclog_image,
			seclog_obs_3,
			seclog_obs_4,
			seclog_cd,
			aut_id,
			sysCode_id,
			menu_id,
			menu_ts,
			request_ip,
			request_name,
			aure_isok,
			aure_user_id,
			seclog_pageHTML,
			prof_id,
			aure_cd,
			aure_id,
			seclog_id1,
			seclog_id2,
			seclog_id3
		)
		VALUES
		(
			@comp_id,
			@bra_id,
			@user_id,
			@description,
			@ML_URL,
			NULL,
			'ID original de Publicación' + ':' + CONVERT(VARCHAR,@mlp_id),
			NULL,
			GETDATE(),
			NULL,
			1900,
			NULL,
			NULL,
			NULL,
			NULL,
			NULL,
			NULL,
			NULL,
			@prof_id,
			NULL,
			NULL,
			NULL,
			NULL,
			NULL
		)
		-- -----------------------------------------------------------------------------------



		-- -----------------------------------------------------------------------------------
		--SI TODO SALE BIEN MANDA MENSAJE
		-- -----------------------------------------------------------------------------------
		SELECT 'La publicación ha sido borrada con éxito' [Message]
		-- -----------------------------------------------------------------------------------
		-- ---------------------------------------------------------------------------------------------------------------------------
	END

GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_DeleteAllFinishedPublications]
(
	@comp_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------
		-- TESTING
		-- ----------------------------------------
		/*
			DECLARE
				@comp_id	INT
			SELECT
				@comp_id	= 1
		*/
		-- ----------------------------------------


		-- -------------------------------------------------------------
		-- BUSCO TODOS LOS MLP_ID que esten FINALIZADOS
		-- -------------------------------------------------------------
		DECLARE @tblPublicacionesFinalizadas TABLE (mlp_id INT PRIMARY KEY)
		INSERT INTO @tblPublicacionesFinalizadas
		(
			mlp_id
		)
		SELECT
			tmlip.mlp_id
		FROM tbMercadoLibre_ItemsPublicados AS tmlip	WITH(NOLOCK)
		WHERE	tmlip.comp_id			= @comp_id AND
				tmlip.optval_statusId	= 5	--FINALIZADA
		-- SI NO HAY PUBLICACIONES FINALIZADAS QUE VUELVA
		IF @@ROWCOUNT = 0
			BEGIN
				RETURN
			END


		-- -------------------------------------------------------------
		-- POR CADA PUBLICACION TENGO QUE BORRAR LOS ATRIBUTOS
		-- -------------------------------------------------------------
			DELETE		tbMercadoLibre_ItemsPublicadosAttributes
				FROM    tbMercadoLibre_ItemsPublicadosAttributes tb1	WITH(NOLOCK)
				INNER JOIN @tblPublicacionesFinalizadas tmp
					ON tmp.mlp_id = tb1.mlp_id
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- BORRO TODAS LAS PREGUNTAS Y RESPUESTAS
		-- -------------------------------------------------------------
			DELETE		tbMercadoLibre_QuestionsAndAnswers
				FROM	tbMercadoLibre_QuestionsAndAnswers		AS	tmlqaa	WITH(NOLOCK)
				INNER JOIN @tblPublicacionesFinalizadas				tmp
					ON	tmp.mlp_id = tmlqaa.mlp_id

			DELETE		tbMercadoLibre_QuestionsAndAnswersSuggestions4Publications
				FROM	tbMercadoLibre_QuestionsAndAnswersSuggestions4Publications AS	tmlqaasp	WITH(NOLOCK)
				INNER JOIN @tblPublicacionesFinalizadas									tmp
					ON	tmp.mlp_id = tmlqaasp.mlp_id
		-- -------------------------------------------------------------


		-- -------------------------------------------------------------
		-- CURSOR
		-- POR CADA MLP_ID tengo que recuperar los MLPV_ID
		-- POR CADA MLPV_ID TENGO QUE BORRAR TODOS LOS MLPVA_ID y todos los MLPVC_ID
		-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
		DECLARE
			@lcomp_id	INT,
			@lmlpv_id	INT,
			@lmlp_id	INT

		DECLARE cursor_VariationsAndAttributes CURSOR LOCAL FAST_FORWARD FOR
			SELECT
				tmlipv.comp_id,
				tmlipv.mlpv_id,
				tmlipv.mlp_id
				FROM tbMercadoLibre_ItemsPublicadosVariations AS	tmlipv	WITH(NOLOCK)
					INNER JOIN @tblPublicacionesFinalizadas			tmp
					ON	tmp.mlp_id = tmlipv.mlp_id


		OPEN	cursor_VariationsAndAttributes

		-- lectura anticipada del cursor
		FETCH NEXT FROM cursor_VariationsAndAttributes
		INTO	@lcomp_id,
				@lmlpv_id,
				@lmlp_id
		-- se recorre el cursor hasta el fin del mismo
		WHILE	@@FETCH_STATUS = 0
			BEGIN
				--BORRO ATRIBUTOS DE LAS VARIACIONES
				DELETE FROM tbMercadoLibre_ItemsPublicadosVariations_Attributes
				WHERE	comp_id = @lcomp_id AND
						mlpv_id = @lmlpv_id

				--BORRO LOS COMBINATIONS DE LAS VARIACIONES
				DELETE FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations
				WHERE	comp_id = @lcomp_id AND
						mlpv_id = @lmlpv_id

				-- próxima lectura del cursor
				FETCH NEXT FROM cursor_VariationsAndAttributes
				INTO	@lcomp_id,
							@lmlpv_id,
							@lmlp_id
			END
		CLOSE cursor_VariationsAndAttributes
		DEALLOCATE cursor_VariationsAndAttributes


		-- -------------------------------------------------------------
		-- TENGO QUE PONER COMO NULL LOS ID DE PUBLICACION Y ID DE VARIACION DE LA TABLA ORDERSDETAIL
		-- REVISAR MOS PARA SABER SI ESTA OK
		UPDATE tbMercadoLibre_ordersDetail
			SET mlp_id			= NULL,
				MLVariationID	= NULL
			FROM tbMercadoLibre_ordersDetail AS tmlod	WITH(NOLOCK)
			INNER JOIN @tblPublicacionesFinalizadas tmp
				ON	tmp.mlp_id = tmlod.mlp_id

		-- -------------------------------------------------------------
		-- UNA VEZ BORRADOS LOS ATRIBUTOS DE VARIACIONES Y LAS COMBINACIONES BORRO LAS VARIACIONES
		-- -------------------------------------------------------------
			DELETE tbMercadoLibre_ItemsPublicadosVariations
				FROM tbMercadoLibre_ItemsPublicadosVariations AS	tmlipv	WITH(NOLOCK)
				INNER JOIN @tblPublicacionesFinalizadas			tmp
					ON tmp.mlp_id = tmlipv.mlp_id
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- BORRO LAS RELACIONES DE LA PUBLICACION CON LAS SUCURSALES
		-- -------------------------------------------------------------
			DELETE  tbMercadoLibre_ItemsPublicados_BranchsRelations
				FROM	tbMercadoLibre_ItemsPublicados_BranchsRelations AS tmlipbr WITH(NOLOCK)
				INNER JOIN @tblPublicacionesFinalizadas tmp
					ON tmp.mlp_id = tmlipbr.mlp_id
		-- -------------------------------------------------------------


		-- -------------------------------------------------------------
		-- BORRO LA UPDATEQUEUE
		-- -------------------------------------------------------------
			DELETE  tbMercadoLibre_updateQueue
				FROM tbMercadoLibre_updateQueue AS tmluq	WITH(NOLOCK)
				INNER JOIN @tblPublicacionesFinalizadas tmp
					ON tmp.mlp_id = tmluq.mlp_id
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- POR ULTIMO BORRO TODAS LAS PUBLICACIONES FINALIZADAS
		-- -------------------------------------------------------------
			DELETE  tbMercadoLibre_ItemsPublicados
				FROM tbMercadoLibre_ItemsPublicados AS tmlip	WITH(NOLOCK)
				INNER JOIN @tblPublicacionesFinalizadas tmp
					ON tmp.mlp_id = tmlip.mlp_id
		-- -------------------------------------------------------------

	END


GO





