CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_DeleteData4MassivePublicationsWithErrors]
(
	@comp_id	INT,
	@mlmp_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------
		-- TESTING
		-- ------------------------------------------
		/*
			DECLARE
				@comp_id	INT,r
				@mlmp_id	INT
			SELECT
				@comp_id	= 1,
				@mlmp_id	= 0
		*/
		-- ------------------------------------------

		-- optval_statusId = 7 = Publicación Masiva con Error

		--BORRO LAS RELACIONES CON LAS SUCURSALES
		DELETE FROM tbMercadoLibre_ItemsPublicados_BranchsRelations
		FROM tbMercadoLibre_ItemsPublicados_BranchsRelations	tmlipbr	WITH(NOLOCK)
		INNER JOIN tbMercadoLibre_ItemsPublicados				tmlip	WITH(NOLOCK)
		ON	tmlip.comp_id		= tmlipbr.comp_id				AND
			tmlip.mlp_id		= tmlipbr.mlp_id
		WHERE	tmlip.comp_id	= @comp_id						AND
				(
					@mlmp_id		= 0		OR
					tmlip.mlmp_id	= @mlmp_id
				)												AND
				optval_statusId		= 7



		--BORRO LAS PUBLICACIONES QUE TENGAN ERROR
		DELETE FROM tbMercadoLibre_ItemsPublicados
		WHERE	comp_id	= @comp_id				AND
				(
					@mlmp_id		= 0		OR
					mlmp_id			= @mlmp_id
				)								AND
				optval_statusId		= 7

	END
GO


