CREATE PROCEDURE spMercadoLibre_ItemsPublicados_DeleteNonPublished
(
	@comp_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
			DECLARE
				@comp_id	INT
			SELECT
				@comp_id	= 1
		*/
		-- -------------------------------------------

		--ACÁ GUARDO TODOS LOS MLP_ID DE LAS PUBLICACIONES QUE NO SE PUDIERON DAR DE ALTA EN MERCADOLIBRE
		DECLARE @tblMercadoLibre_ItemsWithNoPublicationID TABLE(comp_id INT, mlp_id INT)
		INSERT INTO @tblMercadoLibre_ItemsWithNoPublicationID
		(
			comp_id,
			mlp_id
		)
		SELECT
			tmlip.comp_id,
			tmlip.mlp_id
		FROM tbMercadoLibre_ItemsPublicados						tmlip
		WHERE	tmlip.comp_id						=  @comp_id	AND
				ISNULL(tmlip.mlp_publicationID,'')	= ''

		--==
		--SELECT * FROM @tblMercadoLibre_ItemsWithNoPublicationID
		--==


		-- BORRAMOS ATRIBUTOS
		DELETE FROM tbMercadoLibre_ItemsPublicadosAttributes
			FROM tbMercadoLibre_ItemsPublicadosAttributes			tmlipa
			INNER JOIN @tblMercadoLibre_ItemsWithNoPublicationID	tbl
			ON	tbl.comp_id		= tmlipa.comp_id					AND
				tbl.mlp_id		= tmlipa.mlp_id

		--BORRAMOS COMBINACIONES DE VARIACIONES
		DELETE FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations
		FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations	tmlipvc
			INNER JOIN tbMercadoLibre_ItemsPublicadosVariations		tmlipv
			ON	tmlipv.comp_id	= tmlipvc.comp_id					AND
				tmlipv.mlpv_id	= tmlipvc.mlpv_id
			INNER JOIN @tblMercadoLibre_ItemsWithNoPublicationID	tbl
			ON	tbl.comp_id		= tmlipv.comp_id					AND
				tbl.mlp_id		= tmlipv.mlp_id

		--BORRAMOS LAS VARIACIONES
		DELETE FROM tbMercadoLibre_ItemsPublicadosVariations
			FROM tbMercadoLibre_ItemsPublicadosVariations			tmlipv
			INNER JOIN @tblMercadoLibre_ItemsWithNoPublicationID	tbl
			ON	tbl.comp_id		= tmlipv.comp_id					AND
				tbl.mlp_id		= tmlipv.mlp_id

		--BORRAMOS LA COLA DE PROCESOS
		DELETE FROM tbMercadoLibre_updateQueue
			FROM tbMercadoLibre_updateQueue							tmluq
			INNER JOIN @tblMercadoLibre_ItemsWithNoPublicationID	tbl
			ON	tbl.comp_id		= tmluq.comp_id						AND
				tbl.mlp_id		= tmluq.mlp_id

		--BORRAMOS LAS PUBLICACIONES
		DELETE FROM tbMercadoLibre_ItemsPublicados
			FROM tbMercadoLibre_ItemsPublicados						tmlip
			INNER JOIN @tblMercadoLibre_ItemsWithNoPublicationID	tbl
			ON	tbl.comp_id		= tmlip.comp_id						AND
				tbl.mlp_id		= tmlip.mlp_id


	END



GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_FamilyRelations_getAllPublicationsFamilyDataByMLP_Id]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 1
		*/
		-- -------------------------------------------------

		DECLARE
			@lFamilyID AS BIGINT
		SELECT TOP 1
			@lFamilyID = tmlipfr.family_id
			FROM tbMercadoLibre_ItemsPublicados_FamilyRelations AS tmlipfr	WITH(NOLOCK)
			WHERE	tmlipfr.comp_id = @comp_id					AND
					tmlipfr.mlp_id	= @mlp_id

		SELECT DISTINCT
			' '													[ ],
			tmlip.mlp_publicationID,
			tmlip.mlp_family_name,
			tmlip.mlp_userProductID,
			tmlip.mlp_itemTitle,
			ti.item_code,
			ti.item_desc,
			tmlipfr.mlp_id
			FROM tbMercadoLibre_ItemsPublicados_FamilyRelations AS tmlipfr	WITH(NOLOCK)
				INNER JOIN tbMercadoLibre_ItemsPublicados		AS tmlip	WITH(NOLOCK)
					ON	tmlip.comp_id	= tmlipfr.comp_id		AND
						tmlip.mlp_id	= tmlipfr.mlp_id
				INNER JOIN tbItem								AS ti		WITH(NOLOCK)
					ON	ti.comp_id		= tmlip.comp_id AND
						ti.item_id		= tmlip.item_id
			WHERE	tmlipfr.comp_id		= @comp_id				AND
					tmlipfr.family_id	= @lFamilyID			AND
					tmlipfr.mlp_id		<> @mlp_id

		ORDER BY tmlip.mlp_itemTitle

	END

GO

