GO

CREATE PROCEDURE spMercadoLibre_ItemsPublicados_FamilyRelations_InsertData
(
	@comp_id		INT,
	@family_id		BIGINT,
	@userProductID	VARCHAR(30),
	@mlp_id			INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@family_id		BIGINT,
				@userProductID	VARCHAR(30),
				@mlp_id			INT
			SELECT
				@comp_id		= 1,
				@family_id		= 1,
				@userProductID	= '',
				@mlp_id			= 1
		*/
		-- ------------------------------------------------------------------
		IF NOT EXISTS(SELECT
				TOP 1 1
				FROM tbMercadoLibre_ItemsPublicados_FamilyRelations AS tmlipfr	WITH(NOLOCK)
				WHERE	tmlipfr.comp_id			= @comp_id			AND
						tmlipfr.family_id		= @family_id		AND
						tmlipfr.user_product_id = @userProductID)
		BEGIN
			INSERT INTO tbMercadoLibre_ItemsPublicados_FamilyRelations
			(
				comp_id,
				family_id,
				user_product_id,
				mlp_id
			)
			VALUES
			(
				@comp_id,
				@family_id,
				@userProductID,
				@mlp_id
			)
			SELECT @@IDENTITY [ID]
		END
	END


GO


CREATE PROCEDURE spMercadoLibre_ItemsPublicados_FamilyRelations_InsertOrUpdateData
(
	@comp_id			INT,
	@mlp_id				INT,
	@family_id			BIGINT,
	@User_Product_Id	NVARCHAR(30)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@mlp_id				INT,
				@family_id			BIGINT,
				@User_Product_Id	NVARCHAR(30)
		*/
		-- -----------------------------------------------------------------

		IF NOT EXISTS(SELECT TOP 1 1
						FROM tbMercadoLibre_ItemsPublicados_FamilyRelations AS tmlipfr	WITH(NOLOCK)
						WHERE	comp_id					= @comp_id			AND
								family_id				= @family_id		AND
								tmlipfr.user_product_id = @User_Product_Id	AND
								mlp_id					= @mlp_id)
			BEGIN
				--Primero borro la relación existente
				DELETE FROM tbMercadoLibre_ItemsPublicados_FamilyRelations
					WHERE	comp_id		= @comp_id		AND
							family_id	= @family_id	AND
							mlp_id		= @mlp_id
				--Segundo inserto la relación(Por si cambió algo y para que no queden registros desactualizados que ensucian todo)
				INSERT INTO tbMercadoLibre_ItemsPublicados_FamilyRelations
				(
					comp_id,
					family_id,
					user_product_id,
					mlp_id
				)
				VALUES
				(
					@comp_id,
					@family_id,
					@User_Product_Id,
					@mlp_id
				)
			END
	END





GO

