CREATE PROCEDURE spMercadoLibre_ItemsPublicados_GeneratePriceAndStockUpdateForPublicationMigration
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 1
		*/
		-- ----------------------------------------------------------

		--VARIABLES LOCALES DE TRABAJO
		DECLARE
			@mls_id		INT,
			@decPrice	DECIMAL(19,5),
			@intQty		INT,
			@luser_id	INT


		-- RECUPERO LOS DATOS DE LA PUBLICACION
		SELECT
			@decPrice				= tmlip.mlp_price,
			@intQty					= tmlip.mlp_initQty,
			@mls_id					= tmlip.mls_id
			FROM tbMercadoLibre_ItemsPublicados AS tmlip	WITH(NOLOCK)
			WHERE	tmlip.comp_id	= @comp_id	AND
					tmlip.mlp_id	= @mlp_id

		--RECUPERO EL USER_ID DE LA TIENDA
		SELECT
			@luser_id				= tmls.[user_id]
			FROM tbMercadoLibre_Stores			AS tmls	WITH(NOLOCK)
			WHERE	tmls.comp_id	= @comp_id	AND
					tmls.mls_id		= @mls_id

		--Registro para Update de Precio
		INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				mlproc_cd,
				[user_id],
				mlproc_option,
				mlproc_decimalValue,
				mlproc_isProcessed,
				mlproc_isCancelled,
				mlproc_priority,
				mlproc_stringValue,
				mlproc_integerValue,
				mlproc_isWithErrorTryNumber,
				mlproc_bigintegerValue,
				mlproc_textValue,
				mlproc_internalID
			)
			VALUES
			(
				@comp_id,
				@mlp_id,
				GETDATE(),
				@luser_id,
				8,
				@decPrice,	-- Le suima el IVA en subUpdatePrice mas el costo de envio
				'False',
				'False',
				0,
				'',
				0,
				0,
				0,
				'',
				357951852
			)

		-- Registro para update de Available Qty
		INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				mlproc_cd,
				[user_id],
				mlproc_option,
				mlproc_decimalValue,
				mlproc_isProcessed,
				mlproc_isCancelled,
				mlproc_priority,
				mlproc_stringValue,
				mlproc_integerValue,
				mlproc_isWithErrorTryNumber,
				mlproc_bigintegerValue,
				mlproc_textValue,
				mlproc_internalID
			)
			VALUES
			(
				@comp_id,
				@mlp_id,
				GETDATE(),
				@luser_id,
				4,
				0,
				'False',
				'False',
				0,
				'',
				@intQty,
				0,
				0,
				'',
				357951852
			)

	END
GO

CREATE PROCEDURE spMercadoLibre_ItemsPublicados_GetAllItemsFromPublication
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 1181
		*/
		-- -------------------------------------------------

		SELECT
			tmlip.comp_id,
			tmlip.mlp_id,
			ISNULL(tmlip.mlp_publicationID,'')		[mlp_publicationID],
			ti.item_code,
			ti.item_desc
			FROM tbMercadoLibre_ItemsPublicados		AS tmlip	WITH(NOLOCK)
				INNER JOIN tbItem					AS ti		WITH(NOLOCK)
					ON	ti.comp_id	= tmlip.comp_id AND
						ti.item_id	= tmlip.item_id
			WHERE	tmlip.comp_id	= @comp_id		AND
					tmlip.mlp_id	= @mlp_id

		SELECT
			tmlipv.comp_id,
			tmlipv.mlpv_id,
			ISNULL(tmlipv.MLVariationID,0)					[MLVariationID],
			ti.item_code,
			ti.item_desc
			FROM tbMercadoLibre_ItemsPublicadosVariations	AS tmlipv	WITH(NOLOCK)
				INNER JOIN tbItem							AS ti		WITH(NOLOCK)
					ON	ti.comp_id	= tmlipv.comp_id		AND
						ti.item_id	= tmlipv.item_id
			WHERE	tmlipv.comp_id	= @comp_id AND
					tmlipv.mlp_id	= @mlp_id

	END

GO

CREATE PROCEDURE spMercadoLibre_ItemsPublicados_GetAllPublicationCategories

AS
	BEGIN
