	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_GetAllPublicationsWithEANS]

AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------

		-- -----------------------------------------

		--ACA HACEMOS UNA VARIABLE DE TABLA, EN DONDE VAMOS A GRABAR TODO TODO TODO
		DECLARE @tblPublications AS TABLE(	mlp_id						INT PRIMARY KEY,
											mlp_publicationCategoryID	NVARCHAR(30),
											strEans						NVARCHAR(4000),
											MinPrice4Category			DECIMAL(19,2),
											MaxPrice4Category			DECIMAL(19,2),
											PromPrice4Category			DECIMAL(19,2),
											MinPrice4EAN				DECIMAL(19,2),
											MaxPrice4EAN				DECIMAL(19,2),
											PromPrice4EAN				DECIMAL(19,2),
											totalSoldQTY				INT,
											totalAvailableQTY			INT,
											averageLastWeekSoldQTY		INT
										 )


		-- VARIABLES DE TRABAJO DEL CURSOR
		DECLARE
			@mlp_id						INT,
			@mlp_publicationCategoryID	NVARCHAR(30)




		DECLARE cursor_forPublicationEans CURSOR LOCAL FAST_FORWARD FOR
			SELECT
				tmlip.mlp_id,
				tmlip.mlp_publicationCategoryID
				FROM tbMercadoLibre_ItemsPublicados			AS tmlip
				INNER JOIN tbMercadoLibre_Stores			AS tmls
				ON	tmls.comp_id				= tmlip.comp_id AND
					tmls.mls_id					= tmlip.mls_id
				WHERE	tmls.mls_disabled		= 'False'		AND
						tmlip.optval_statusId	= 2


		OPEN	cursor_forPublicationEans
		-- lectura anticipada del cursor
		FETCH	cursor_forPublicationEans
		INTO	@mlp_id,
				@mlp_publicationCategoryID
		-- se recorre el cursor hasta el fin del mismo
		WHILE   @@FETCH_STATUS = 0
			BEGIN

				--ACA SUCEDE LA MAGIA

				DECLARE
					@strEans	NVARCHAR(4000)

				SET @strEans = ''

				-- -------------------------------------------------------------------------------------
				-- RECUPERO LOS EANS DE LOS ATRIBUTOS
				-- -------------------------------------------------------------------------------------
					SELECT
						@strEans = @strEans + tmlipa.mlat_valueString + ','
					FROM tbMercadoLibre_ItemsPublicadosAttributes	AS tmlipa
					WHERE	tmlipa.mlp_id	= @mlp_id				AND
							(
								tmlipa.MLid = 'GTIN'	OR
								tmlipa.MLid = 'EAN'
							)										AND
							ISNULL(tmlipa.mlat_valueString,'') <> ''
				-- -------------------------------------------------------------------------------------

				-- -------------------------------------------------------------------------------------
				-- RECUPERO LOS EANS DE LOS ATRIBUTOS DE VARIACIONES
				-- -------------------------------------------------------------------------------------
					SELECT
						@strEans = @strEans + tmlipva.MLvalue_name + ','
						FROM tbMercadoLibre_ItemsPublicadosVariations					AS tmlipv
						INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Attributes	AS tmlipva
						ON	tmlipva.comp_id			= tmlipv.comp_id					AND
							tmlipva.mlpv_id			= tmlipv.mlpv_id
						WHERE	tmlipv.mlp_id		= @mlp_id							AND
								(
									tmlipva.MLid	= 'EAN' OR
									tmlipva.MLid	= 'GTIN'
								)														AND
								ISNULL(tmlipva.MLvalue_name,'') <> ''
				-- -------------------------------------------------------------------------------------

				-- -------------------------------------------------------------------------------------
				-- ACA INSERTO EN LA TABLA CREADA TODAS LAS PUBLICACIONES CON SUS RESPECTIVOS EANS
				-- -------------------------------------------------------------------------------------
					INSERT INTO @tblPublications
					(
						mlp_id,
						mlp_publicationCategoryID,
						strEans,
						MinPrice4Category,
						MaxPrice4Category,
						PromPrice4Category,
						MinPrice4EAN,
						MaxPrice4EAN,
						PromPrice4EAN,
						totalSoldQTY,
						totalAvailableQTY,
						averageLastWeekSoldQTY
					)
					SELECT
						@mlp_id,
						@mlp_publicationCategoryID,
						@strEans,
						0,
						0,
						0,
						0,
						0,
						0,
						0,
						0,
						0
				-- -------------------------------------------------------------------------------------

				-- próxima lectura del cursor
				FETCH	cursor_forPublicationEans
				INTO	@mlp_id,
						@mlp_publicationCategoryID
			END
		CLOSE		cursor_forPublicationEans
		DEALLOCATE	cursor_forPublicationEans


		--DEVOLVEMOS TODOS LOS DATOS
		SELECT
			tmp.mlp_id,
			tmp.mlp_publicationCategoryID,
			tmp.strEans,
			tmp.MinPrice4Category,
			tmp.MaxPrice4Category,
			tmp.PromPrice4Category,
			tmp.MinPrice4EAN,
			tmp.MaxPrice4EAN,
			tmp.PromPrice4EAN,
			tmp.totalSoldQTY,
			tmp.totalAvailableQTY,
			tmp.averageLastWeekSoldQTY
			FROM @tblPublications	tmp
			WHERE tmp.strEans <> ''


	END
GO



