	@mlp_catalog_forewarning_dateFrom	DATETIME,
	@mlp_catalog_forewarning_dateTo		DATETIME,
	@OptionShippingTypeFilter			INT,			-- -1 TODAS / 1 SOLO ME1 / 2 TODAS MENOS ME1
	@mlp_channelID						INT,			-- -1 TODAS / 0 Sin canal asignado / 1 MercadoLibre / 2 MercadoShops / 3 MercadoLibre + MercadoShops
	@mlp_fixPublicationDeliveryCharge	INT,
	@mlp_blockPriceUpdate				INT,
	@OptionPlanAhora					INT,			-- -1 TODOS / 1 Algún Plan AHORA / 3 Ahora 3 / 6 Ahora 6 / 12 Ahora 12 / 18 Ahora 18 / 24 Ahora 24 / 30 Ahora 30
	@prli_id4MercadoShop				INT,
	@mlp_prli_id4MercadoShopPlusDeliveryCharge	INT,
	@stor_id4StockAvailability			INT,
	@mlp_isInCampaign					INT,
	@mlp_free_shippingMShops			INT,
	@mlp_hasIncompleteCompatibilities	INT,
	@mlp_FreeShippingAndShippingPriceFilter		INT,	-- -1 TODOS / 1 Free Shipping = True y Costo de Envío = 0 / 2 Free Shipping = True y Costo de Envío mayor a 0
	@mlp_hasCandidate					INT,
