	@mlp_hasPrice2WinActive				INT,
	@mlp_isAvailable4Price2Win			INT,
	@mlp_notExistsInMeli_by404			INT
)
AS

	BEGIN

		SET NOCOUNT ON
		set dateformat 'ymd'

		-- ------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@user_id			INT,
				@prof_id			INT,
				@ItemGuid			UNIQUEIDENTIFIER,
				@cat_id				INT,
				@subcat_id			INT,
				@brand_id			INT,
				@pres_id			INT,
				@subcataux_id		INT,
				@optval_statusId	INT,
				@mlp_Active			INT,
				@mlmp_id			INT,
				@mltitle			NVARCHAR(500),
				@MLID				NVARCHAR(30),
				@mlp_allowPublicationsWithNoStock	INT,
				@mlp_free_shipping	INT,
				@mls_id				INT,
				@hasAttributes		INT,
				@hasVariations		INT,
				@mlipc_id							INT,
				@mlp_4Revision						INT,
				@mlp_listing_type_id				NVARCHAR(50),
				@canOrderByAvailableQTY				BIT,
				@fixed_price						INT,
				@prli_id							INT,
				@hasVariationErrors					INT,
				@PublicationHealthFrom				DECIMAL(5,2),
				@PublicationHealthTo				DECIMAL(5,2),
				@HasVariationsWithNoItemIDAssigned	INT,				-- -1 todos, 1 si   0 no
				@HasSizeChartAssigned				INT,					-- -1 todos, 1 si	0 no
				@stor_id							INT,
				@mlp_attributesVerificationNeeded	INT,
				@mlp_sold_qty_from					INT,
				@mlp_sold_qty_to					INT,
				@mlp_hasAhora12						INT,
				@mlp_is4FulFillment					INT,
				@mlp_forceSO4Commercial				INT,
				@mlp_isInDeal						INT,
				@mlp_isInCatalog					INT,
				@mlp_CostAnaliticsOption			INT = -1,
				@mlp_loyalty_discount_eligible		INT = -1,
				@mlp_poorImage						INT = -1,
				@mlp_catalog_boost					INT = -1,
				@mlp_catalog_isAvailable			INT = -1,
				@hasAdditionalPrice					INT = -1,
				@hasAdditionalDiscount				INT = -1,
				@mlp_local_pickup					INT = -1,
				@mlp_catalog_forewarning			INT = -1,
				@mlp_catalog_forewarning_dateFrom	DATETIME,
				@mlp_catalog_forewarning_dateTo		DATETIME




			SELECT
				@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@user_id			= 119,
				@prof_id			= 1,
				@ItemGuid			= '00000000-0000-0000-0000-000000000000',
				@cat_id				= -1,
				@subcat_id			= -1,
				@brand_id			= -1,
				@pres_id			= -1,
				@subcataux_id		= -1,
				@optval_statusId	= -1,
				@mlp_Active			= -1,
				@mlmp_id			= -1,
				@mltitle			= '',
				@MLID				= '',
				@mlp_allowPublicationsWithNoStock	= -1,
				@mlp_free_shipping	= -1,
				@mls_id				= -1,
				@hasAttributes		= -1,
				@hasVariations		= -1,
				@mlipc_id							= -1,
				@mlp_4Revision						= -1,
				@mlp_listing_type_id				= '-1',
				@canOrderByAvailableQTY				= 'False',
				@fixed_price						= -1,
				@prli_id							= -1,
				@hasVariationErrors					= -1,
				@PublicationHealthFrom				= 0,
				@PublicationHealthTo				= 100,
				@HasVariationsWithNoItemIDAssigned	= -1,				-- -1 todos, 1 si   0 no
				@HasSizeChartAssigned				= -1,					-- -1 todos, 1 si	0 no
				@stor_id							= -1,
				@mlp_attributesVerificationNeeded	= -1,
				@mlp_sold_qty_from					= 0,
				@mlp_sold_qty_to					= 999999,
				@mlp_hasAhora12						= -1,
				@mlp_is4FulFillment					= -1,
				@mlp_forceSO4Commercial				= -1,
				@mlp_isInDeal						= -1,
				@mlp_isInCatalog					= -1,
				@mlp_catalog_forewarning_dateFrom	= '1900-01-01',--convert(datetime,),
				@mlp_catalog_forewarning_dateTo		= '2999-12-31'



		*/
		-- ------------------------------------------------------------


		SET @PublicationHealthFrom = @PublicationHealthFrom / 100
		SET @PublicationHealthTo   = @PublicationHealthTo   / 100

		SET @mlp_catalog_forewarning_dateFrom	= dbo.fnGetEnd_or_BeginOfDate(@mlp_catalog_forewarning_dateFrom,'False')
		SET @mlp_catalog_forewarning_dateTo		= dbo.fnGetEnd_or_BeginOfDate(@mlp_catalog_forewarning_dateTo,  'True')


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- ------------------------------------------------------------
		-- Optimiza las búsquedas
		-- ------------------------------------------------------------
		SET @MLID = UPPER(@MLID)
		SET @MLID = REPLACE(@MLID,'-','')
		SET @MLID = dbo.fnStrAllTrim(@MLID)
		-- ------------------------------------------------------------



		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf		WITH (NOLOCK)
				WHERE tcf.sl_guid = @ItemGuid     AND
					  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti	WITH (NOLOCK)
						WHERE ti.comp_id = @comp_id
			END

		--SELECT * FROM @tblComplexFilter_Items
		-- -------------------------------------------------------------


		-- -------------------------------------------------------------
		-- ACÁ SE GUARDAN TODOS LOS MLP_ID DE LAS PUBLICACIONES QUE
		-- TENGAN VARIACIONES
		-- -------------------------------------------------------------
			DECLARE @tblPublicationsWithVariations TABLE (mlp_id INT PRIMARY KEY, comp_id	INT)

			-- SI DICE -1 INSERTO TODOS LOS DE PUBLICACIONES
			IF (@hasVariations = -1) AND @HasVariationsWithNoItemIDAssigned <> 1
				BEGIN
					INSERT INTO @tblPublicationsWithVariations
					(
						mlp_id,
						comp_id
					)
					SELECT
						tmlip.mlp_id,
						tmlip.comp_id
					FROM tbMercadoLibre_ItemsPublicados tmlip	WITH(NOLOCK)
					WHERE tmlip.comp_id = @comp_id
				END

			-- SI DICE 1 = CON VARIACIONES, INSERTO TODOS LOS QUE TIENEN VARIACIONES
			IF (@hasVariations = 1)
				BEGIN
					INSERT INTO @tblPublicationsWithVariations
					(
						mlp_id,
						comp_id
					)
					SELECT DISTINCT
						tmlipv.mlp_id,
						tmlipv.comp_id
					FROM tbMercadoLibre_ItemsPublicadosVariations tmlipv	WITH(NOLOCK)
					WHERE tmlipv.comp_id = @comp_id
				END

			-- SI DICE 0 = TODAS LAS PUBLICACIONES LEFT JOIN CON VARIACIONES Y PONGO LO QUE ESTAN EN NULL
			IF (@hasVariations = 0)
				BEGIN
					INSERT INTO @tblPublicationsWithVariations
					(
						mlp_id,
						comp_id
					)
					SELECT	DISTINCT
						tmlip.mlp_id,
						tmlip.comp_id
					FROM tbMercadoLibre_ItemsPublicados					tmlip	WITH(NOLOCK)
					LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations	tmlipv	WITH(NOLOCK)
					ON	tmlipv.comp_id	= tmlip.comp_id					AND
						tmlipv.mlp_id	= tmlip.mlp_id
					WHERE tmlip.comp_id = @comp_id AND tmlipv.comp_id IS NULL
				END

			--SELECT * FROM @tblPublicationsWithVariations
		-- -------------------------------------------------------------


		IF @HasVariationsWithNoItemIDAssigned = 1
			BEGIN
				DELETE FROM @tblPublicationsWithVariations
				INSERT INTO @tblPublicationsWithVariations
				(
					mlp_id,
					comp_id
				)
				SELECT DISTINCT
					tmlipv.mlp_id,
					tmlipv.comp_id
				FROM tbMercadoLibre_ItemsPublicadosVariations tmlipv	WITH(NOLOCK)
				WHERE	tmlipv.comp_id = @comp_id	 AND
						tmlipv.item_id IS NULL
			END




		-- -------------------------------------------------------------
		-- ACÁ SE GUARDAN TODOS LOS MLP_ID DE LAS PUBLICACIONES QUE
		-- TENGAN ATRIBUTOS
		-- -------------------------------------------------------------
			DECLARE @tblPublicationsWithAttributes TABLE (mlp_id INT PRIMARY KEY, comp_id INT)

			-- SI DICE -1 INSERTO TODOS LOS DE PUBLICACIONES
			IF (@hasAttributes = -1)
				BEGIN
					INSERT INTO @tblPublicationsWithAttributes
					(
						mlp_id,
						comp_id
					)
					SELECT
						tmlip.mlp_id,
						tmlip.comp_id
					FROM tbMercadoLibre_ItemsPublicados tmlip	WITH(NOLOCK)
					WHERE tmlip.comp_id = @comp_id
				END


			-- SI DICE 1 = CON ATRIBUTOS, INSERTO TODOS LOS QUE TIENEN ATRIBUTOS
			IF (@hasAttributes = 1)
				BEGIN
					INSERT INTO @tblPublicationsWithAttributes
					(
						mlp_id,
						comp_id
					)
					SELECT DISTINCT
						tmlipa.mlp_id,
						tmlipa.comp_id
					FROM tbMercadoLibre_ItemsPublicadosAttributes tmlipa	WITH(NOLOCK)
					WHERE tmlipa.comp_id = @comp_id
				END


			-- SI DICE 0 = TODAS LAS PUBLICACIONES LEFT JOIN CON ATRIBUTOS Y PONGO LO QUE ESTAN EN NULL
			IF (@hasAttributes = 0)
				BEGIN
					INSERT INTO @tblPublicationsWithAttributes
					(
						mlp_id,
						comp_id
					)
					SELECT	DISTINCT
						tmlip.mlp_id,
						tmlip.comp_id
					FROM tbMercadoLibre_ItemsPublicados					tmlip	WITH(NOLOCK)
					LEFT JOIN tbMercadoLibre_ItemsPublicadosAttributes tmlipa	WITH(NOLOCK)
						ON	tmlipa.comp_id	= tmlip.comp_id AND
							tmlipa.mlp_id	= tmlip.mlp_id
					WHERE tmlip.comp_id = @comp_id --AND tmlipa.comp_id IS NULL
				END

			--SELECT * FROM @tblPublicationsWithAttributes
		-- -------------------------------------------------------------




		SET DATEFORMAT 'YMD'

		SELECT
			CASE
				WHEN ISNULL(tmlip.health * 100,0) = 0 THEN 1
				ELSE										ISNULL(tmlip.health * 100,0)
			END
			 *
			CASE
				WHEN tmlip.mlp_attributesVerificationNeeded = 'True' THEN  -1
				ELSE														1
			END												[ ], --MODIFICAR		Cell(3)	---ESTE CAMPO ES EL QUE COLOREA EL TITULO DE LA PUBLICACION EN CASO DE QUE TENGGA ATRIBUTOS DEFECTUOSOS SE CALCULA EN EL ITEM CON spMercadoLibre_ItemsPublicadosAttributes_IsPublicationOK
			CASE
				WHEN tmlip.mlp_is4FulFillment = 'True' AND tmlip.stor_id <> tmls.stor_id	THEN 11
				WHEN tmlip.stor_id <> tmls.stor_id											THEN 1
				WHEN tmlip.mlp_is4FulFillment = 'True' 										THEN 10
				ELSE									0
			END												[ ], --ELIMINAR			Cell(4)
			CASE
				WHEN tmlip.prli_id <> tmls.prli_id THEN 1
				ELSE									0
			END												[ ], --CLONAR			Cell(5)
			tmlip.mlp_publicationID,											--	Cell(6)
			tov.optval_desc									[publicationStatus],--	Cell(7)
			ti.item_code,														--	Cell(8)
			ti.item_desc,														--	Cell(9)
			tmlip.mlp_itemTitle,												--	Cell(10)

			CASE
			  WHEN tmlip.mlp_listing_type_id = 'gold_pro'		THEN 'Premium'
			  WHEN tmlip.mlp_listing_type_id = 'gold_premium'	THEN 'Oro Premium'
			  WHEN tmlip.mlp_listing_type_id = 'gold_special'	THEN 'Clásica'
			  WHEN tmlip.mlp_listing_type_id = 'gold'			THEN 'Oro'
			  WHEN tmlip.mlp_listing_type_id = 'silver'			THEN 'Plata'
			  WHEN tmlip.mlp_listing_type_id = 'bronze'			THEN 'Bronce'
			  WHEN tmlip.mlp_listing_type_id = 'free'			THEN 'Gratuita'
				ELSE												 tmlip.mlp_listing_type_id
			END													[mlp_listing_type_id],

			tmlip.mlp_initQty,
			tmlip.mlp_minQty4Pause,



			-- -----------------------------------------------------------------------------------------------------------------------------------------
			--NO PONER NADA DESPUËS DE ESTO! EN CASO DE TENER QUE MODIFICAR EL ORDEN HACERLO TAMBIEN EN EL COUNT DE LA PÁGINA wfmMercadoLibre_Publicaciones
			--32a1sd32a1sd23a1sd231as2d3
			CONVERT(DECIMAL(10,2),tmlip.mlp_priceDirectDiscountPercenage)					[DiscountPercent]	,		--COUNT -26
			CASE
				WHEN @canOrderByAvailableQTY = 'True' THEN	CONVERT(INT,ROUND(dbo.fnGetAStock4MaxAssociation(tmlip.comp_id, CASE
																																WHEN tmlip.stor_id4StockAvailability IS NOT NULL THEN	tmlip.stor_id4StockAvailability
																																ELSE													tmls.stor_id4StockAvailability
																															END, tmlip.item_id, 99999999),0))
				ELSE										0
			END													[stock_Availability],									--COUNT -25
			tmlip.mlp_sold_quantity,																					--COUNT -24
			CONVERT(decimal(25,2),tmlip.mlp_price)				[mlp_price],											--COUNT -23
			CONVERT(decimal(25,2),
			tmlip.mlp_price +
			(tmlip.mlp_price  * ISNULL(ttnIVA.tax_percentage,0) / 100)
			+
			(tmlip.mlp_price  * ISNULL(ttnII.tax_percentage,0) / 100)
					)											[mlp_pricePlusTax],										--COUNT -22
			tc2.curr_symbol,																							--COUNT -21
			ISNULL(tmlip.mlp_price4FreeShipping,0)	[mlp_price4FreeShipping],											--COUNT -20
			CONVERT(decimal(25,2),tmlip.mlp_listing_fee_amount)					[mlp_listing_fee_amount],																				--COUNT -19
			CONVERT(decimal(25,2),tmlip.mlp_sale_fee_amount)					[mlp_sale_fee_amount],																					--COUNT -18


			-- Costo con Impuestos mas Costo Venta en Meli Maximo
			CONVERT(decimal(25,2),
						(
							(
								ISNULL(dbo.fnGetExchange2(ticl.comp_id, ISNULL(ticl.coslis_price,0),ISNULL(ticl.curr_id,tb2.curr_id),tmls.curr_id /* tmlip.curr_id*/,0,0,0,'False'),0)
								*
								(1 + (ISNULL(ttnIVA.tax_percentage,0) / 100))
							)									 +
						--ISNULL(tmlip.mlp_listing_fee_amount,0)	 +
						ISNULL(tmlip.mlp_sale_fee_amount,0)
						)
					)															[totalCost],							--COUNT -17

			-- Precio de Venta TOTAL --**987489738947238ASKJDKLASD
			-- SI SE TOCA ALGO EN EL CAMPO TOTALSALE cambiar también en spMercadoLibre_ItemPublicado_GetTotalSalePrice
			CONVERT(decimal(25,2),(
									(
										tmlip.mlp_price +
										(tmlip.mlp_price  * ISNULL(ttnIVA.tax_percentage,0) / 100)
											+
										(tmlip.mlp_price  * ISNULL(ttnII.tax_percentage,0) / 100)
									)
									  /  ( (ISNULL(tmlip.mlp_priceDirectDiscountPercenage,0) / 100) + 1 )
								  )
								+
									ISNULL(tmlip.mlp_price4AdditionalCost,0)
								+   ISNULL(tmlip.mlp_price4FreeShipping,0)


					)														[totalSale],								--COUNT -16






			CONVERT(INT,tmlip.health * 100)									[health],									--COUNT -15
			tmlip.mlp_permalink,																						--COUNT -14
			ISNULL(tov2.optval_desc,'')				[mlp_isFixedPrice],													--COUNT -13
			tu.user_nick,																								--COUNT -12
			tmlip.mlp_Active,									--	Cell(21)											--COUNT -11

			tmls.mls_desc,																								--COUNT -10
			tpl.prli_desc,																								--COUNT -9
			ts.stor_desc,																								--COUNT -8
			tmlip.mlp_start_time,																						--COUNT -7
			tmlip.mlp_stop_time,																						--COUNT -6
			tmlip.mlp_lastUpdate,																						--COUNT -5
			-- -----------------------------------------
			tu2.user_lastname + ',' + tu2.user_firstname					[User_LastUpdate],							--COUNT -4
			tmlip.dateof_lastUpdate,																					--COUNT -3
			tmlip.dateof_lastUpdateFromMeLi,																			--COUNT -2

			-- -----------------------------------------
			tmlip.mlp_id													[ID]										--COUNT -1


			--tmlip.mlp_warranty,																							--COUNT -6
												--COUNT -1
			FROM tbMercadoLibre_ItemsPublicados					tmlip	WITH (NOLOCK)

				INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id			= tmlip.item_id
				INNER JOIN tbItem								ti	WITH (NOLOCK)
					ON	ti.comp_id			= tmlip.comp_id		AND
						ti.item_id			= tmlip.item_id
				INNER JOIN tbCategory							tc	WITH (NOLOCK)
					ON	tc.comp_id			= ti.comp_id		AND
						tc.cat_id			= ti.cat_id
				INNER JOIN tbSubCategory						tsc	WITH (NOLOCK)
					ON  tsc.comp_id			= ti.comp_id		AND
						tsc.subcat_id		= ti.subcat_id
				LEFT JOIN tbSubCategoryAux						tsca	WITH (NOLOCK)
					ON  tsca.comp_id		= ti.comp_id		AND
						tsca.subcataux_id	= ti.subcataux_id
				INNER JOIN tbBrand								tb	WITH (NOLOCK)
					ON  tb.comp_id			= ti.comp_id		AND
						tb.brand_id			= ti.brand_id
				LEFT JOIN tbPresentation						tp	WITH (NOLOCK)
					ON  tp.comp_id				= ti.comp_id	AND
						tp.pres_id				= ti.pres_id
				INNER JOIN tbsysCurrency						tc2	WITH (NOLOCK)
					ON  tc2.curr_id				= tmlip.curr_id
				INNER JOIN tbUser								tu	WITH (NOLOCK)
					ON  tu.[user_id]			= tmlip.[user_id]
				INNER JOIN tbsysOptionsValues					tov	WITH (NOLOCK)
					ON  tov.lang_id				= @lang_id		AND
						tov.optval_class		= 173			AND
						tov.optval_id			= tmlip.optval_statusId
				INNER JOIN tbMercadoLibre_Stores					tmls	WITH (NOLOCK)
					ON	tmls.comp_id			= tmlip.comp_id AND
						tmls.mls_id				= tmlip.mls_id
				INNER JOIN @tblPublicationsWithVariations		tmpVariations
					ON	tmpVariations.mlp_id	= tmlip.mlp_id	--AND
						--tmpVariations.comp_id	= tmlip.comp_id
				INNER JOIN @tblPublicationsWithAttributes		tmpAttributes
					ON	tmpAttributes.mlp_id	= tmlip.mlp_id	--AND
						--tmpAttributes.comp_id	= tmlip.comp_id


				LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit		WITH (NOLOCK)
					ON 	vitooit.comp_id = ti.comp_id AND
						vitooit.item_id = ti.item_id

				LEFT JOIN tbTaxName ttnIVA	WITH (NOLOCK)
					ON	ttnIVA.comp_id  = vitooit.comp_id AND
						ttnIVA.tax_id   = vitooit.tax_id


				LEFT JOIN vwItemTaxesOnlyOneInternalTax vitooit2	WITH (NOLOCK)
					ON 	vitooit2.comp_id = ti.comp_id AND
						vitooit2.item_id = ti.item_id

				LEFT JOIN tbTaxName ttnII	WITH (NOLOCK)
					ON	ttnII.comp_id   = vitooit2.comp_id AND
						ttnII.tax_id    = vitooit2.tax_id

				INNER JOIN tbPriceList					tpl			WITH(NOLOCK)
				ON		tpl.comp_id		= tmlip.comp_id AND
						tpl.prli_id		= tmlip.prli_id

				INNER JOIN tbStorage					ts			WITH(NOLOCK)
				ON	ts.comp_id			= tmlip.comp_id AND
					ts.stor_id			= tmlip.stor_id

				LEFT JOIN tbUser						tu2			WITH(NOLOCK)
				ON	tu2.[user_id]		= tmlip.userid_lastUpdate

				LEFT JOIN tbsysOptionsValues			tov2		WITH(NOLOCK)
				ON	tov2.lang_id			= @lang_id		AND
					tov2.optval_class		= 723			AND
					tov2.optval_id			= tmlip.mlp_isFixedPrice

				INNER JOIN tbBranch					AS tb2			WITH (NOLOCK)
					ON	tb2.comp_id = tmls.comp_id AND
						tb2.bra_id	= tmls.bra_id

				LEFT JOIN tbItemCostList				AS ticl		WITH (NOLOCK)
					ON	ticl.comp_id	= tmlip.comp_id AND
						ticl.coslis_id	= tb2.coslis_id	AND
						ticl.item_id	= tmlip.item_id

			WHERE	tmlip.comp_id	= @comp_id										AND
					(@cat_id		= -1		OR ti.cat_id		= @cat_id)		AND
					(@subcat_id		= -1		OR ti.subcat_id		= @subcat_id)	AND
					(@subcataux_id	= -1		OR ti.subcataux_id	= @subcataux_id)AND
					(@brand_id		= -1		OR ti.brand_id		= @brand_id)	AND
					(@pres_id		= -1		OR ti.pres_id		= @pres_id)		AND
					(
						(@optval_statusId		= -3 AND tmlip.mlp_Active = 'True')		OR
						(@optval_statusId		= -1)									OR
						(@optval_statusId		= -2 AND tmlip.optval_statusId <> 5)	OR
						(tmlip.optval_statusId	= @optval_statusId)
					)																AND
					(	@mlp_Active	= -1								OR
						@mlp_Active	= 1 AND tmlip.mlp_Active = 'True'	OR
						@mlp_Active	= 0 AND tmlip.mlp_Active = 'False'
					)																AND
					(
						@mlmp_id		= -1							OR
						tmlip.mlmp_id	= @mlmp_id
					)																AND
					(
						@mltitle		= ''							OR
						tmlip.mlp_itemTitle LIKE '%'+ @mltitle +'%'
					)																AND
					(
						@MLID			= ''							OR
						tmlip.mlp_publicationID LIKE '%' + @MLID + '%'
					)																AND
					(
						(@mlp_allowPublicationsWithNoStock = -1)		OR
						(@mlp_allowPublicationsWithNoStock = 1	AND ISNULL(tmlip.mlp_allowPublicationsWithNoStock,'False') = 'True')
																		OR
						(@mlp_allowPublicationsWithNoStock = 0	AND ISNULL(tmlip.mlp_allowPublicationsWithNoStock,'False') = 'False')
					)																AND
					(
						(@mlp_free_shipping = -1)						OR
						(@mlp_free_shipping = 1 AND ISNULL(tmlip.mlp_free_shipping,'False') = 'True')
																		OR
						(@mlp_free_shipping	= 0 AND ISNULL(tmlip.mlp_free_shipping,'False') = 'False')

					)																AND
					(
						(@mls_id				= -1)					OR
						(@mls_id				= tmlip.mls_id)
					)																AND
					(
						(@mlipc_id				= -1)					OR
						(@mlipc_id				= tmlip.mlipc_id)
					)																AND
					(
						(@mlp_4Revision			= -1)					OR
						(tmlip.mlp_4Revision	= @mlp_4Revision)
					)																AND
					(
						@mlp_listing_type_id	= '-1'					OR
						tmlip.mlp_listing_type_id = @mlp_listing_type_id
					)																AND
					(
						@fixed_price			= -1					OR
						tmlip.mlp_isFixedPrice	= @fixed_price
					)																AND
					(
						@prli_id				= -1					OR
						tmlip.prli_id			= @prli_id
					)																AND
					(
						@hasVariationErrors		= -1					OR
						ISNULL(tmlip.mlp_variationError,'False') = @hasVariationErrors
					)																AND
					(
						tmlip.health BETWEEN @PublicationHealthFrom AND @PublicationHealthTo
					)																AND
					(
						@HasSizeChartAssigned	= -1								OR
						(@HasSizeChartAssigned	= 1 AND tmlip.mlp_sizeChartID > 0)	OR
						(@HasSizeChartAssigned	= 0 AND tmlip.mlp_sizeChartID = 0)
					)																AND
					(
						@stor_id				= -1					OR
						tmlip.stor_id			= @stor_id
					)																AND
					(
						@mlp_attributesVerificationNeeded = -1			OR
						tmlip.mlp_attributesVerificationNeeded = @mlp_attributesVerificationNeeded
					)																AND
					(
						tmlip.mlp_sold_quantity	BETWEEN @mlp_sold_qty_from AND @mlp_sold_qty_to
					)																AND
					(
						@mlp_hasAhora12						= -1		OR
						ISNULL(tmlip.mlp_ahora12,'False')	= @mlp_hasAhora12
					)																AND
					(
						@mlp_is4FulFillment					= -1		OR
						ISNULL(tmlip.mlp_is4FulFillment,'False') = @mlp_is4FulFillment
					)																AND
					(
						@mlp_forceSO4Commercial				= -1		OR
						ISNULL(tmlip.mlp_forceSO4Commercial,'False') = @mlp_forceSO4Commercial
					)																AND
					(
						@mlp_isInDeal						= -1		OR
						ISNULL(tmlip.mlp_isInDeal, 'False')	= @mlp_isInDeal
					)																AND
					(
						@mlp_isInCatalog						= -1									OR
						(@mlp_isInCatalog = 1  AND ISNULL(tmlip.mlp_catalog_product_id,'') <> '')	OR
						(@mlp_isInCatalog = 0  AND ISNULL(tmlip.mlp_catalog_product_id,'')  = '')
					)																AND
					(
						@mlp_loyalty_discount_eligible			= -1	OR
						tmlip.mlp_loyalty_discount_eligible		= @mlp_loyalty_discount_eligible
					)																AND
					(
						@mlp_poorImage							= -1	OR
						ISNULL(tmlip.mlp_poorImage,'False')		= @mlp_poorImage
					)																AND
					(
						@mlp_catalog_boost						= -1	OR
						ISNULL(tmlip.mlp_catalog_boost,'False')	= @mlp_catalog_boost
					)																AND
					(
						@mlp_catalog_isAvailable				= -1	OR
						ISNULL(tmlip.mlp_catalog_isAvailable,'False') = @mlp_catalog_isAvailable
					)																AND
					(
						@hasAdditionalPrice = -1 OR
						(@hasAdditionalPrice = 1 AND tmlip.mlp_price4AdditionalCost > 0) OR
						(@hasAdditionalPrice = 0 AND tmlip.mlp_price4AdditionalCost = 0)
					)																AND
					(
						@hasAdditionalDiscount = -1 OR
						(@hasAdditionalDiscount = 1 AND tmlip.mlp_priceDirectDiscountPercenage > 0) OR
						(@hasAdditionalDiscount = 0 AND tmlip.mlp_priceDirectDiscountPercenage = 0)
					)																AND
					(
						@mlp_local_pickup	  = -1 OR
						tmlip.mlp_local_pick_up = @mlp_local_pickup
					)																AND
					(
						@mlp_catalog_forewarning		= -1 OR
						tmlip.mlp_catalog_forewarning	= @mlp_catalog_forewarning
					)																AND
					(
						ISNULL(tmlip.mlp_catalog_forewarning_date,GETDATE()) BETWEEN @mlp_catalog_forewarning_dateFrom AND @mlp_catalog_forewarning_dateTo
					)																AND
					(
						@OptionShippingTypeFilter		= -1														OR		--TODOS
						@OptionShippingTypeFilter		=  1 AND ISNULL(tmlip.mlp_isME1Available,'False') = 'True' 	OR		--SOLO ME1
						@OptionShippingTypeFilter		=  2 AND ISNULL(tmlip.mlp_isME1Available,'False') = 'False'			--TODOS MENOS ME1
					)																AND
					(
						@mlp_channelID					= -1 OR
						tmlip.mlp_channelID				= @mlp_channelID
					)																AND
					(
						@mlp_fixPublicationDeliveryCharge						= -1	OR
						ISNULL(tmlip.mlp_fixPublicationDeliveryCharge, 'False')	= @mlp_fixPublicationDeliveryCharge
					)																AND
					(
						@mlp_blockPriceUpdate			= -1 OR
						tmlip.mlp_blockPriceUpdate		= @mlp_blockPriceUpdate
					)
					AND
					CASE	-- -- -1 TODOS / 1 Algún Plan AHORA / 3 Ahora 3 / 6 Ahora 6 / 12 Ahora 12 / 18 Ahora 18 / 24 Ahora 24 / 30 Ahora 30
						WHEN @OptionPlanAhora = -1										THEN 1
						WHEN @OptionPlanAhora = 1	AND (
															tmlip.mlp_ahora3				= 'True' OR
															tmlip.mlp_ahora6				= 'True' OR
															tmlip.mlp_ahora12				= 'True' OR
															tmlip.mlp_ahora18				= 'True' OR
															tmlip.mlp_ahora24				= 'True' OR
															tmlip.mlp_ahora30				= 'True' OR
															tmlip.mlp_ahora3mshops			= 'True' OR
															tmlip.mlp_ahora6mshops			= 'True' OR
															tmlip.mlp_ahora12mshops			= 'True' OR
															tmlip.mlp_ahora24mshops			= 'True' OR
															tmlip.mlp_ahora12_paidByBuyer	= 'True' OR
															tmlip.mlp_ahora3plan			= 'True'
														)								THEN 1

						WHEN @OptionPlanAhora = 3	AND (
															tmlip.mlp_ahora3		= 'True' OR
															tmlip.mlp_ahora3mshops	= 'True' OR
															tmlip.mlp_ahora3plan	= 'True'
														)								THEN 1
						WHEN @OptionPlanAhora = 6	AND (
															tmlip.mlp_ahora6		= 'True' OR
															tmlip.mlp_ahora6mshops	= 'True'
														)								THEN 1
						WHEN @OptionPlanAhora = 12	AND (
															tmlip.mlp_ahora12				= 'True' OR
															tmlip.mlp_ahora12mshops			= 'True' OR
															tmlip.mlp_ahora12_paidByBuyer	= 'True'
														)								THEN 1
						WHEN @OptionPlanAhora = 18	AND tmlip.mlp_ahora18  = 'True'		THEN 1
						WHEN @OptionPlanAhora = 24	AND (
															tmlip.mlp_ahora24		= 'True' OR
															tmlip.mlp_ahora24mshops	= 'True'
														)								THEN 1
						WHEN @OptionPlanAhora = 30	AND tmlip.mlp_ahora30  = 'True'		THEN 1
						ELSE 0
					END = 1															AND
					(
						@prli_id4MercadoShop = -1 OR
						tmlip.prli_id4MercadoShop = @prli_id4MercadoShop
					)																AND
					(
						@mlp_prli_id4MercadoShopPlusDeliveryCharge = -1 OR
						ISNULL(tmlip.mlp_prli_id4MercadoShopPlusDeliveryCharge,'False') = @mlp_prli_id4MercadoShopPlusDeliveryCharge
					)																AND
					(
						@stor_id4StockAvailability		= -1 OR
						tmlip.stor_id4StockAvailability = @stor_id4StockAvailability
					)																AND
					(
						@mlp_isInCampaign				= -1 OR
						tmlip.mlp_isInCampaign			= @mlp_isInCampaign
					)																AND
					(
						@mlp_free_shippingMShops						= -1 OR
						ISNULL(tmlip.mlp_free_shippingMShops,'False')	= @mlp_free_shippingMShops
					)																AND
					(
						@mlp_hasIncompleteCompatibilities						= -1 OR
						ISNULL(tmlip.mlp_hasIncompleteCompatibilities,'False')	= @mlp_hasIncompleteCompatibilities
					)																AND
					(
							@mlp_FreeShippingAndShippingPriceFilter		= -1
								OR
							(
								@mlp_FreeShippingAndShippingPriceFilter	=  1		AND
								tmlip.mlp_free_shipping					= 'True'	AND
								tmlip.mlp_price4FreeShipping			= 0
							)
								OR
							(
								@mlp_FreeShippingAndShippingPriceFilter	=  2		AND
								tmlip.mlp_free_shipping					= 'True'	AND
								tmlip.mlp_price4FreeShipping			> 0
							)
					)																AND
					(
						@mlp_hasCandidate								= -1 OR
						tmlip.mlp_hasCandidate							= @mlp_hasCandidate
					)																AND
					(
						@mlp_hasOffer									= -1 OR
						tmlip.mlp_hasOffer								= @mlp_hasOffer
					)																AND
					(
						@mlp_hasPrice2WinActive							= -1 OR
						tmlip.mlp_hasPrice2WinActive					= @mlp_hasPrice2WinActive
					)																AND
					(
						@mlp_isAvailable4Price2Win						= -1 OR
						tmlip.mlp_isAvailable4Price2Win					= @mlp_isAvailable4Price2Win
					)														 AND
					(
						@mlp_notExistsInMeli_by404						= -1 OR
						ISNULL(tmlip.mlp_notExistsInMeli_by404,'False') = @mlp_notExistsInMeli_by404
					)




		ORDER BY
				--tmlip.mlp_Active DESC,
				tmlip.mlp_id DESC
				-- MOS 12-2020, no se x q mierda ordenar x tmlip.mlp_Active DESC, es SUPER LENTO, si le saco esto VUELA
				--CASE
				--	WHEN tmlip.mlp_Active = 1 THEN	0
				--	ELSE							1
				--END		,
				--tmlip.mlp_id DESC



	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_GetDataById]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		DECLARE			@bitHasVariations AS BIT = 'False'
		SELECT  TOP 1	@bitHasVariations		 = 'True'
			FROM tbMercadoLibre_ItemsPublicados					tmlip		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ItemsPublicadosVariations tmlipv		WITH (NOLOCK)
				ON	tmlipv.comp_id	= tmlip.comp_id		AND
					tmlipv.mlp_id	= tmlip.mlp_id
			WHERE	tmlip.comp_id	= @comp_id			AND
					tmlip.mlp_id	= @mlp_id			AND
					tmlipv.mlpv_disabled = 'False'		AND
					tmlipv.item_id IS NOT NULL			AND
					tmlipv.MLVariationID IS NOT NULL	AND
					ISNULL(tmlipv.MLVariationID,0) > 100000


		SELECT
			tmlip.comp_id,
			tmlip.mlp_id,
			tmlip.bra_id,
			tmlip.stor_id,
			tmlip.prli_id,
			tmlip.item_id,
			tmlip.mlp_initQty,
			tmlip.mlp_price,
			tmlip.curr_id,
			dbo.fnGetExchange2(tmlip.comp_id,tmlip.mlp_price,tmlip.curr_id,tmls.curr_id,0,0,0,'False')		[priceInStoreCurrency],
			tmls.curr_id																					[storeCurrency],
			tmlip.optval_statusId,
			tmlip.mlp_inicDate,
			tmlip.mlp_endDate,
			tmlip.mlp_lastUpdate,
			tmlip.[user_id],
			tmlip.mlp_Active,
			tmlip.mlp_itemDesc,
			ISNULL(tmlip.mlp_itemHTML,'')									[mlp_itemHTML],
			tmlip.mls_id,
			tmlip.mlp_itemTitle,
			tmlip.mlp_minQty4Pause,
			tmlip.mlp_listing_type_id,
			tmlip.mlp_listing_fee_amount,
			tmlip.mlp_sale_fee_amount,
			tmlip.mlp_publicationID,
			tmlip.mlp_buying_mode,
			tmlip.mlp_itemSubTitle,
			tmlip.mlp_start_time,
			tmlip.mlp_stop_time,
			tmlip.mlp_sold_quantity,
			ISNULL(tmlip.mlp_permalink ,'')									[mlp_permalink],
			ISNULL(tmlip.mlp_thumbnail,'')									[mlp_thumbnail],
			ISNULL(tmlip.mlp_video_id,'')									[mlp_video_id],
			tmlip.mlp_accepts_mercadopago,
			ISNULL(tmlip.mlp_warranty,'')									[mlp_warranty],
			tmlip.mlp_local_pick_up,
			tmlip.mlp_free_shipping,
			tmlip.mlp_publicationCategoryID,
			tmlip.mlp_isFixedPrice,
			tmlip.mlp_lastPublicatedPrice,
			tmlip.mlp_lastPublicatedCurrID,
			tmlip.st_id,
			tmlip.disc_id,
			tmlip.dl_id,
			tmlip.mlp_free_method,
			tmlip.mlp_allowPublicationsWithNoStock,
			ISNULL(tmlip.mlipc_id,-1)										[mlipc_id],
			tmlip.mlp_creationDate,
			ISNULL(tmlip.mlp_price4FreeShipping,0)							[mlp_price4FreeShipping],
			ISNULL(tmlip.mlp_4Revision,'False')								[mlp_4Revision],
			ISNULL(tmlip.mlp_revisionMessage,'')							[mlp_revisionMessage],
			ISNULL(tmlip.mlp_official_store_id,'')							[mlp_official_store_id],
			ISNULL(tmlip.mlp_price4AdditionalCost,0)						[mlp_price4AdditionalCost],
			ISNULL(tmlip.mlp_priceDirectDiscountPercenage,0)				[mlp_priceDirectDiscountPercenage],
			tmlip.userid_lastUpdate,
			tmlip.dateof_lastUpdate,
			tmlip.dateof_lastUpdateFromMeLi,
			ISNULL(tmls.mls_disablePriceListUpdate,'False')					[mls_disablePriceListUpdate],
			CONVERT(INT,tmlip.health * 100)									[health],
			tmlip.mlp_sizeChartID,
			ISNULL(tmls.mls_disableImagesImport,'False')					[mls_disableImagesImport],
			ISNULL(tmlip.mlp_catalog_product_id, '')						[mlp_catalog_product_id],

			ISNULL(tmlip.mlp_is4FulFillment,'False')						[mlp_is4FulFillment],
			ISNULL(tmlip.mlp_forceSO4Commercial,'False')					[mlp_forceSO4Commercial],
			@bitHasVariations												[HasVariations],
			ISNULL(tmlip.mlp_labelPrintModuleNoPrintSecondLabel,'False')	[mlp_labelPrintModuleNoPrintSecondLabel],
			ISNULL(tmlip.mlp_priceDirectDiscountPercenage, 0)				[mlp_priceDirectDiscountPercenage],
			ISNULL(tmlip.mlp_warranty_type,'')								[mlp_warranty_type],
			ISNULL(tmlip.mlp_warranty_time,'')								[mlp_warranty_time],
			ISNULL(tmlip.mlp_warranty_time_value,0)							[mlp_warranty_time_value],
			tmlip.stor_id4StockAvailability,
			tmlip.mlp_creationDate,
			ISNULL(tmlip.mlp_blockCatalogPriceUpdateFromNormalPublication,'False') [mlp_blockCatalogPriceUpdateFromNormalPublication],
			tmlip.storg_id,
			CASE
				WHEN tmls.mls_blockCatalogPriceUpdateFromNormalPublication = 'True' OR tmlip.mlp_blockCatalogPriceUpdateFromNormalPublication = 'True' THEN 'True'
				ELSE 'False'
			END																[blockCatalogPriceUpdateFromNormalPublication],
			ISNULL(tmlip.mlp_isME1Available,'False')						[mlp_isME1Available],
			tmlip.prli_id4MercadoShop,
			ISNULL(tmlip.mlp_fixPublicationDeliveryCharge,'False')			[mlp_fixPublicationDeliveryCharge],
			ISNULL(tmlip.mlp_channelID,0)									[mlp_channelID],
			ISNULL(tmlip.mlp_blockPriceUpdate,'False')						[mlp_blockPriceUpdate],
			--tmlip.mlp_blockPriceUpdate,
			ISNULL(tmlip.mlp_ahora3,'False')								[mlp_ahora3],
			ISNULL(tmlip.mlp_ahora6,'False')								[mlp_ahora6],
			ISNULL(tmlip.mlp_ahora12,'False')								[mlp_ahora12],
			ISNULL(tmlip.mlp_ahora18,'False')								[mlp_ahora18],
			ISNULL(tmlip.mlp_ahora24,'False')								[mlp_ahora24],
			ISNULL(tmlip.mlp_ahora30,'False')								[mlp_ahora30],
			ISNULL(tmlip.mlp_prli_id4MercadoShopPlusDeliveryCharge,'False')	[mlp_prli_id4MercadoShopPlusDeliveryCharge]	,
			ISNULL(tmls.mls_accessToken,'')									[mls_accessToken],
			tmlip.mlp_free_shippingMShops,		-- NO PONER ISNULLLLLLLLLLLLL!!!!!!!!!!!!!!!
			ISNULL(tmlip.mlp_free_shippingMShops_Coeficient,0)				[mlp_free_shippingMShops_Coeficient],
			tmlip.mlp_isAvailable4Price2Win,
			tmlip.mlp_hasPrice2WinActive,
			ISNULL(tmlip.mlp_ahora3mshops,'False')								[mlp_ahora3mshops],
			ISNULL(tmlip.mlp_ahora6mshops,'False')								[mlp_ahora6mshops],
			ISNULL(tmlip.mlp_ahora12mshops,'False')								[mlp_ahora12mshops],
			ISNULL(tmlip.mlp_ahora24mshops,'False')								[mlp_ahora24mshops],
			dbo.fnMercadoLibre_getMLValue(tmls.country_id)						[countryML],
			ISNULL(tmlip.mlp_ahora12_paidByBuyer,'False')						[mlp_ahora12_paidByBuyer],
			ISNULL(tc.curr_symbol,'ARS')										[curr_symbol],
			ISNULL(tmlip.mlp_manufacturing_time,0)								[mlp_manufacturing_time],
			ISNULL(tmlip.mlp_blockPriceUpdate4mercadoShops,'False')				[mlp_blockPriceUpdate4mercadoShops],
			ISNULL(tmlip.mlp_is4FullAndFlex,'False')					 		[mlp_is4FullAndFlex],
			ISNULL(tmlip.mlp_ahora3plan,'False')								[mlp_ahora3plan],
			ISNULL(tmlip.mlp_pcjcofunded,'False')								[mlp_pcjcofunded],
			ISNULL(tmlip.mlp_pcjcofundedmshops,'False')							[mlp_pcjcofundedmshops],
			ISNULL(tmlip.mlp_ahora3planmshops,'False')							[mlp_ahora3planmshops],
			ISNULL(tmlip.mlp_cuotasimple3,'False')								[mlp_cuotasimple3],
			ISNULL(tmlip.mlp_cuotasimple6,'False')								[mlp_cuotasimple6],
			ISNULL(tmlip.mlp_cuotasimple_paidbybuyer,'False')					[mlp_cuotasimple_paidbybuyer],
			ISNULL(tmlip.mlp_cuotasimple3mshops,'False')						[mlp_cuotasimple3mshops],
			ISNULL(tmlip.mlp_cuotasimple6mshops,'False')						[mlp_cuotasimple6mshops],
			ISNULL(tmlip.mlp_9xCampaign, 'False')								[mlp_9xCampaign],
			ISNULL(tmlip.mlp_9xCampaignmshops,'False')							[mlp_9xCampaignmshops],
			ISNULL(tmlip.mlp_family_name,'')									[mlp_family_name],
			ISNULL(tmlip.mlp_cuotasimple12,'False')								[mlp_cuotasimple12],
			ISNULL(tmlip.mlp_12xCampaign,'False')								[mlp_12xCampaign],
			ISNULL(tmlip.mlp_cuotasimple12mshops,'False')						[mlp_cuotasimple12mshops],
			ISNULL(tmlip.mlp_12xCampaignmshops,'False')							[mlp_12xCampaignmshops],
			ISNULL(tmlip.mlp_Aut_Int_Ext_Enabled,'False')						[mlp_Aut_Int_Ext_Enabled],
			ISNULL(tmlip.mlp_Aut_Int_Ext_Percentage,0)							[mlp_Aut_Int_Ext_Percentage]

			FROM tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_Stores	tmls		WITH (NOLOCK)
				ON	tmls.comp_id	= tmlip.comp_id AND
					tmls.mls_id		= tmlip.mls_id
			LEFT JOIN tbsysCurrency AS tc					WITH (NOLOCK)
				ON tc.curr_id		=  tmlip.curr_id
			WHERE	tmlip.comp_id	= @comp_id		AND
					tmlip.mlp_id	= @mlp_id
	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_GetDataByPublicationID]
(
	@comp_id			INT,
	@mlp_publicationID	NVARCHAR(30)
)
AS

