		SET NOCOUNT ON

		SELECT
			tmlip.comp_id,
			tmlip.mlp_id,
			tmlip.bra_id,
			tmlip.stor_id,
			ISNULL(tmlip.prli_id,tmls.prli_id)								[prli_id],
			tmlip.item_id,
			tmlip.mlp_initQty,
			tmlip.mlp_price,
			tmlip.curr_id,
			tmlip.optval_statusId,
			tmlip.mlp_inicDate,
			tmlip.mlp_endDate,
			tmlip.mlp_lastUpdate,
			tmlip.[user_id],
			tmlip.mlp_Active,
			tmlip.mlp_itemDesc,
			tmlip.mlp_itemHTML,
			tmlip.mls_id,
			tmlip.mlp_itemTitle,
			tmlip.mlp_minQty4Pause,
			tmlip.mlp_listing_type_id,
			tmlip.mlp_listing_fee_amount,
			tmlip.mlp_sale_fee_amount,
			tmlip.mlp_publicationID,
			tmlip.mlp_buying_mode,
			tmlip.mlp_itemSubTitle,
			tmlip.mlp_start_time,
			tmlip.mlp_stop_time,
			tmlip.mlp_sold_quantity,
			tmlip.mlp_permalink,
			tmlip.mlp_thumbnail,
			tmlip.mlp_video_id,
			tmlip.mlp_accepts_mercadopago,
			tmlip.mlp_warranty,
			tmlip.mlp_local_pick_up,
			ISNULL(tmlip.mlp_free_shipping,'False')								[mlp_free_shipping],
			tmlip.mlp_publicationCategoryID,
			ISNULL(tmlip.mlp_isFixedPrice,'False')								[mlp_isFixedPrice],
			tmlip.mlp_lastPublicatedPrice,
			tmlip.mlp_lastPublicatedCurrID,
			tmlip.st_id,
			tmlip.disc_id,
			tmlip.dl_id,
			tmlip.mlp_free_method,
			ISNULL(tmls.mls_enableUpdatePublicationsFromMercadoLibre,'False')	[mls_enableUpdatePublicationsFromMercadoLibre],
			tmlip.mlp_allowPublicationsWithNoStock,
			tmlip.mlipc_id,
			tmlip.mlp_creationDate,
			ISNULL(tmlip.mlp_price4FreeShipping,0)								[mlp_price4FreeShipping],
			ISNULL(tmlpc.mlipc_desc4Header,'')									[mlipc_desc4Header],
			ISNULL(tmlpc.mlipc_desc4Footer,'')									[mlipc_desc4Footer],
			ISNULL(tmls.mls_updatePublicationPriceFromML,'False')				[mls_updatePublicationPriceFromML],
			ISNULL(tmls.mls_updatePublicationPriceListFromML,'False')			[mls_updatePublicationPriceListFromML],
			ISNULL(tmls.mls_updatePublicationAttributesFromML,'False')			[mls_updatePublicationAttributesFromML],
			dbo.fnGetExchange2(tmlip.comp_id,tmlip.mlp_price,tmlip.curr_id,tmls.curr_id,0,0,0,'False')		[priceInStoreCurrency],
			tmls.curr_id																					[storeCurrency]	,
			ISNULL(tmlip.mlp_price4AdditionalCost,0)							[mlp_price4AdditionalCost]	,
			ISNULL(tmlip.mlp_priceDirectDiscountPercenage,0)					[mlp_priceDirectDiscountPercenage],
			ISNULL(tmlip.mlp_lastUpdateFromERP,GETDATE())						[mlp_lastUpdateFromERP],
			ISNULL(tmlip.mlp_warranty_type,'')									[mlp_warranty_type],
			ISNULL(tmlip.mlp_warranty_time,'')									[mlp_warranty_time],
			ISNULL(tmlip.mlp_warranty_time_value,'')							[mlp_warranty_time_value],
			ISNULL(tmls.mls_carritoAddTime4LoadSO,0)							[mls_carritoAddTime4LoadSO],
			CASE
				WHEN tmls.mls_blockCatalogPriceUpdateFromNormalPublication = 'True' OR tmlip.mlp_blockCatalogPriceUpdateFromNormalPublication = 'True' THEN 'True'
				ELSE 'False'
			END																	[blockCatalogPriceUpdateFromNormalPublication],
			ISNULL(tmlip.mlp_isME1Available,'False')							[mlp_isME1Available],
			ISNULL(tmlip.prli_id4MercadoShop,-1)								[prli_id4MercadoShop],
			ISNULL(tmlip.mlp_fixPublicationDeliveryCharge,'False')				[mlp_fixPublicationDeliveryCharge],
			ISNULL(tmlip.mlp_channelID,0)										[mlp_channelID],
			ISNULL(tmlip.mlp_blockPriceUpdate,'False')							[mlp_blockPriceUpdate],
			ISNULL(tmlip.mlp_ahora3,'False')									[mlp_ahora3],
			ISNULL(tmlip.mlp_ahora6,'False')									[mlp_ahora6],
			ISNULL(tmlip.mlp_ahora18,'False')									[mlp_ahora18],
			ISNULL(tmlip.mlp_ahora24,'False')									[mlp_ahora24],
			ISNULL(tmlip.mlp_ahora30,'False')									[mlp_ahora30],
			ISNULL(tmlip.mlp_prli_id4MercadoShopPlusDeliveryCharge,'False')		[mlp_prli_id4MercadoShopPlusDeliveryCharge],
			ISNULL(tmlpc.mlipc_freeShippingCharge,0)							[mlipc_freeShippingCharge],
			ISNULL(tmlip.mlp_free_shippingMShops_Coeficient,0)					[mlp_free_shippingMShops_Coeficient],
			CASE
				WHEN tpli.comp_id IS NULL THEN	0
				ELSE							dbo.fnGetExchange2(tmlip.comp_id,tpli.prli_price,tpli.curr_id,tmlip.curr_id,0,0,0,'False')
			END																	[price2Win_MinimumPriceListByList],
			CASE
				WHEN tpli2.comp_id IS NULL THEN 0
				ELSE							dbo.fnGetExchange2(tmlip.comp_id,tpli2.prli_price,tpli2.curr_id,tmlip.curr_id,0,0,0,'False')
			END																	[price2Win_MinimumPriceListByPublicationList],
			CASE
				WHEN	tmlpc.mlipc_isAvailable4Price2Win	= 'True' AND
						tmlip.mlp_isAvailable4Price2Win		= 'True' THEN  1
				ELSE													   0
			END																	[isAvailable4Price2Win],
			ISNULL(tmlpc.mlipc_discount4PublicationPriceList4MinimumPrice,0)	[mlipc_discount4PublicationPriceList4MinimumPrice]	,
			ISNULL(tmlpc.mlipc_Price2Win_force2MinimumByConfig,'False')			[mlipc_Price2Win_force2MinimumByConfig],
			ISNULL(tmlip.mlp_ahora3mshops,'False')								[mlp_ahora3mshops],
			ISNULL(tmlip.mlp_ahora6mshops,'False')								[mlp_ahora6mshops],
			ISNULL(tmlip.mlp_ahora12mshops,'False')								[mlp_ahora12mshops],
			ISNULL(tmlip.mlp_ahora24mshops,'False')								[mlp_ahora24mshops],
			dbo.fnMercadoLibre_getMLValue(tmls.country_id)						[countryML],
			ISNULL(tmlip.mlp_ahora12_paidByBuyer,'False')						[mlp_ahora12_paidByBuyer],
			dbo.fnMercadoLibre_getMLValue(tmls.country_id)						[countryML],
			ISNULL(tmlip.mlp_manufacturing_time,0)								[mlp_manufacturing_time],
			ISNULL(tmlip.mlp_is4FullAndFlex,'False')					 		[mlp_is4FullAndFlex],
			ISNULL(tmlip.mlp_ahora3plan,'False')								[mlp_ahora3plan],
			ISNULL(tmlip.mlp_cuotasimple3,'False')								[mlp_cuotasimple3],
			ISNULL(tmlip.mlp_cuotasimple6,'False')								[mlp_cuotasimple6],
			ISNULL(tmlip.mlp_cuotasimple_paidbybuyer,'False')					[mlp_cuotasimple_paidbybuyer],
			ISNULL(tmlip.mlp_cuotasimple3mshops,'False')						[mlp_cuotasimple3mshops],
			ISNULL(tmlip.mlp_cuotasimple6mshops,'False')						[mlp_cuotasimple6mshops]				,
			ISNULL(tmls.mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice,'False')
																				[mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice],
			ISNULL(tmls.mls_desc,'')											[mls_desc],
			dbo.fnStrAllTrim (ISNULL(tmls.mls_strSendTo4ForcedUpdate,''))		[mls_strSendTo4ForcedUpdate],
			dbo.fnStrAllTrim (ISNULL(tmls.mls_strSendFrom4ForcedUpdate,''))		[mls_strSendFrom4ForcedUpdate],
			ISNULL(tmls.mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice_not4Deal,'False')
																				[mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice_not4Deal],
			ISNULL(tmlip.mlp_9xCampaign, 'False')								[mlp_9xCampaign],
			ISNULL(tmlip.mlp_9xCampaignmshops,'False')							[mlp_9xCampaignmshops]	,
			ISNULL(tmlip.mlp_family_name,'')									[mlp_family_name],
			ISNULL(tmlip.mlp_cuotasimple12,'False')								[mlp_cuotasimple12],
			ISNULL(tmlip.mlp_12xCampaign,'False')								[mlp_12xCampaign],
			ISNULL(tmlip.mlp_cuotasimple12mshops,'False')						[mlp_cuotasimple12mshops],
			ISNULL(tmlip.mlp_12xCampaignmshops,'False')							[mlp_12xCampaignmshops],
			ISNULL(tmlip.mlp_Aut_Int_Ext_Enabled,'False')						[mlp_Aut_Int_Ext_Enabled],
			ISNULL(tmlip.mlp_Aut_Int_Ext_Percentage,0)							[mlp_Aut_Int_Ext_Percentage]



		FROM tbMercadoLibre_ItemsPublicados					tmlip		WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_Stores					tmls		WITH (NOLOCK)
			ON	tmls.comp_id	= tmlip.comp_id				AND
				tmls.mls_id		= tmlip.mls_id
		INNER JOIN tbMercadoLibre_ItemsPublicadosCategories	tmlpc		WITH (NOLOCK)
			ON	tmlpc.comp_id	= tmlip.comp_id				AND
				tmlpc.mlipc_id	= tmlip.mlipc_id
		LEFT JOIN tbPriceListItems			AS tpli						WITH (NOLOCK)
			ON	tpli.comp_id	= tmlpc.comp_id							AND
				tpli.prli_id	= tmlpc.prli_id4Price2Win4MinimumPrice	AND
				tpli.item_id	= tmlip.item_id
		LEFT JOIN tbPriceListItems			AS tpli2					WITH (NOLOCK)
			ON	tpli2.comp_id	= tmlip.comp_id				AND
				tpli2.prli_id	= tmlip.prli_id				AND
				tpli2.item_id	= tmlip.item_id
		WHERE	tmlip.comp_id			= @comp_id			AND
				tmlip.mlp_publicationID = @mlp_publicationID
	END




GO








CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_getDataByText]
(
	@text	VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id  AS INT
)
AS



BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*

		DECLARE
			@text		VARCHAR(300),
			@count		INT,
			@lang_id	INT,
			@comp_id AS INT,
			@bra_id  AS INT

		SELECT
			@text		='A',
			@count		= 2,
			@lang_id	= 2,
			@comp_id	= 1,
			@bra_id		= 1
	*/
	-- ----------------------------------------------------------------





	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')



	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)
	DECLARE @text6	varchar(300)
	DECLARE @text7	varchar(300)
	DECLARE @text8	varchar(300)
	DECLARE @text9	varchar(300)
	DECLARE @text10	varchar(300)

	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR LOCAL  FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0 else
			IF @text2 IS NULL SET @text2 = @text0 else
			IF @text3 IS NULL SET @text3 = @text0 else
			IF @text4 IS NULL SET @text4 = @text0 else
			IF @text5 IS NULL SET @text5 = @text0 else
			IF @text6 IS NULL SET @text6 = @text0 else
			IF @text7 IS NULL SET @text7 = @text0 else
			IF @text8 IS NULL SET @text8 = @text0 else
			IF @text9 IS NULL SET @text9 = @text0 else
			IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------





	SELECT		TOP (@count)

				Upper(dbo.PadRightString( IsNull(tc.mlp_itemTitle,''),'.',50)) + ' | ' + isnull(convert(VARCHAR(10),tc.mlp_id ),'')	[mlp_itemTitle],
				tc.mlp_id
	FROM tbMercadoLibre_ItemsPublicados  tc
			WHERE		tc.comp_id = @comp_id
					AND (tc.bra_id IS NULL OR tc.bra_id = @bra_id)
		AND
			(

						CASE
							WHEN @selection_method = 0 AND tc.mlp_itemTitle	LIKE @text + '%'	 THEN	'True'
							WHEN @selection_method = 1 AND tc.mlp_itemTitle LIKE '%' + @text1 + '%'	 THEN	'True'
							WHEN @selection_method = 2 AND tc.mlp_itemTitle LIKE '%' + @text1 + '%' AND tc.mlp_itemTitle LIKE '%' + @text2 + '%'		 THEN	'True'
							WHEN @selection_method = 3 AND tc.mlp_itemTitle LIKE '%' + @text1 + '%' AND tc.mlp_itemTitle LIKE '%' + @text2 + '%' AND tc.mlp_itemTitle LIKE '%' + @text3 + '%'	 THEN	'True'
							WHEN @selection_method = 4 AND tc.mlp_itemTitle LIKE '%' + @text1 + '%' AND tc.mlp_itemTitle LIKE '%' + @text2 + '%' AND tc.mlp_itemTitle LIKE '%' + @text3 + '%' AND tc.mlp_itemTitle LIKE '%' + @text4 + '%'		 THEN	'True'
							WHEN @selection_method = 5 AND tc.mlp_itemTitle LIKE '%' + @text1 + '%' AND tc.mlp_itemTitle LIKE '%' + @text2 + '%' AND tc.mlp_itemTitle LIKE '%' + @text3 + '%' AND tc.mlp_itemTitle LIKE '%' + @text4 + '%' AND tc.mlp_itemTitle LIKE '%' + @text5 + '%'		 THEN	'True'
							WHEN @selection_method = 6 AND tc.mlp_itemTitle LIKE '%' + @text1 + '%' AND tc.mlp_itemTitle LIKE '%' + @text2 + '%' AND tc.mlp_itemTitle LIKE '%' + @text3 + '%' AND tc.mlp_itemTitle LIKE '%' + @text4 + '%' AND tc.mlp_itemTitle LIKE '%' + @text5 + '%' AND tc.mlp_itemTitle LIKE '%' + @text6 + '%'	 THEN	'True'
							WHEN @selection_method = 7 AND tc.mlp_itemTitle LIKE '%' + @text1 + '%' AND tc.mlp_itemTitle LIKE '%' + @text2 + '%' AND tc.mlp_itemTitle LIKE '%' + @text3 + '%' AND tc.mlp_itemTitle LIKE '%' + @text4 + '%' AND tc.mlp_itemTitle LIKE '%' + @text5 + '%' AND tc.mlp_itemTitle LIKE '%' + @text6 + '%' AND tc.mlp_itemTitle LIKE '%' + @text7 + '%'	 THEN	'True'
							WHEN @selection_method = 8 AND tc.mlp_itemTitle LIKE '%' + @text1 + '%' AND tc.mlp_itemTitle LIKE '%' + @text2 + '%' AND tc.mlp_itemTitle LIKE '%' + @text3 + '%' AND tc.mlp_itemTitle LIKE '%' + @text4 + '%' AND tc.mlp_itemTitle LIKE '%' + @text5 + '%' AND tc.mlp_itemTitle LIKE '%' + @text6 + '%' AND tc.mlp_itemTitle LIKE '%' + @text7 + '%' AND tc.mlp_itemTitle LIKE '%' + @text8 + '%'		 THEN	'True'
							WHEN @selection_method = 9 AND tc.mlp_itemTitle LIKE '%' + @text1 + '%' AND tc.mlp_itemTitle LIKE '%' + @text2 + '%' AND tc.mlp_itemTitle LIKE '%' + @text3 + '%' AND tc.mlp_itemTitle LIKE '%' + @text4 + '%' AND tc.mlp_itemTitle LIKE '%' + @text5 + '%' AND tc.mlp_itemTitle LIKE '%' + @text6 + '%' AND tc.mlp_itemTitle LIKE '%' + @text7 + '%' AND tc.mlp_itemTitle LIKE '%' + @text8 + '%' AND tc.mlp_itemTitle LIKE '%' + @text9 + '%'		 THEN	'True'
							WHEN @selection_method =10 AND tc.mlp_itemTitle LIKE '%' + @text1 + '%' AND tc.mlp_itemTitle LIKE '%' + @text2 + '%' AND tc.mlp_itemTitle LIKE '%' + @text3 + '%' AND tc.mlp_itemTitle LIKE '%' + @text4 + '%' AND tc.mlp_itemTitle LIKE '%' + @text5 + '%' AND tc.mlp_itemTitle LIKE '%' + @text6 + '%' AND tc.mlp_itemTitle LIKE '%' + @text7 + '%' AND tc.mlp_itemTitle LIKE '%' + @text8 + '%' AND tc.mlp_itemTitle LIKE '%' + @text9 + '%' AND tc.mlp_itemTitle LIKE '%' + @text10 + '%'		 THEN 'True'
							ELSE	'False'
						END	= 'True'

			)



			ORDER BY	tc.mlp_itemTitle

END
GO


CREATE PROCEDURE spMercadoLibre_ItemsPublicados_GetGDTData4UpdateByMLPID
(
	@comp_id	INT,
	@mlp_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------
		-- TESTING
		-- -----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 1163
		*/
		-- -----------------------------------------------

		-- ----------------------------------------------------------------------------
		-- RECUPERO SI TIENE EL ID DE GRILLA Y DEVUELVO EL DATO
		-- ----------------------------------------------------------------------------
			DECLARE @lHasSizeGrid	AS BIT = 'False'
			DECLARE @lGridSizeID	AS BIGINT = -1
				IF EXISTS (SELECT 1
							FROM tbMercadoLibre_ItemsPublicadosAttributes AS tmlipa	WITH(NOLOCK)
							WHERE	tmlipa.comp_id	= @comp_id AND
									tmlipa.mlp_id	= @mlp_id AND
									tmlipa.MLid		= 'SIZE_GRID_ID')
					BEGIN
						SET @lHasSizeGrid = 'True'
						SELECT @lGridSizeID = tmlipa.mlat_valueString
							FROM tbMercadoLibre_ItemsPublicadosAttributes AS tmlipa	WITH(NOLOCK)
							WHERE	tmlipa.comp_id	= @comp_id AND
									tmlipa.mlp_id	= @mlp_id AND
									tmlipa.MLid		= 'SIZE_GRID_ID'
					END

			SELECT
				'SIZE_GRID_ID'	[FIELD],
				@lGridSizeID	[GRID_ID]
		-- ----------------------------------------------------------------------------


		-- ----------------------------------------------------------------------------
		-- RECUPERO LAS VARIACIONES Y SI TIENE VALORES DE ROW ID DE TALLE
		-- ----------------------------------------------------------------------------
			SELECT
				tmlipv.comp_id, tmlipv.mlpv_id, tmlipv.MLVariationID, tmlipva.MLid,
				tmlipva.MLvalue_name
			FROM tbMercadoLibre_ItemsPublicadosVariations					AS tmlipv	WITH(NOLOCK)
			INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Attributes	AS tmlipva	WITH(NOLOCK)
			ON	tmlipva.comp_id = tmlipv.comp_id AND
				tmlipva.mlpv_id = tmlipv.mlpv_id AND
				tmlipva.MLid	= 'SIZE_GRID_ROW_ID'
			WHERE	tmlipv.comp_id	= @comp_id AND
					tmlipv.mlp_id	= @mlp_id
		-- ----------------------------------------------------------------------------



	END



GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_GetPublicationEansByMLP_ID]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 1000
		*/
		-- -----------------------------------------

		DECLARE @strEans	NVARCHAR(4000)
		SET		@strEans	= ''

		-- -------------------------------------------------------------------------------------
		-- RECUPERO LOS EANS DE LOS ATRIBUTOS
		-- -------------------------------------------------------------------------------------
			SELECT
				@strEans = @strEans + tmlipa.mlat_valueString + ','
			FROM tbMercadoLibre_ItemsPublicadosAttributes	AS tmlipa
			WHERE	tmlipa.comp_id	= @comp_id				AND
					tmlipa.mlp_id	= @mlp_id				AND
					(
						tmlipa.MLid = 'GTIN'	OR
						tmlipa.MLid = 'EAN'
					)										AND
					ISNULL(tmlipa.mlat_valueString,'') <> ''
		-- -------------------------------------------------------------------------------------

		-- -------------------------------------------------------------------------------------
		-- RECUPERO LOS EANS DE LOS ATRIBUTOS DE VARIACIONES
		-- -------------------------------------------------------------------------------------
			SELECT
				@strEans = @strEans + tmlipva.MLvalue_name + ','
				FROM tbMercadoLibre_ItemsPublicadosVariations					AS tmlipv
				INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Attributes	AS tmlipva
				ON	tmlipva.comp_id			= tmlipv.comp_id					AND
					tmlipva.mlpv_id			= tmlipv.mlpv_id
				WHERE	tmlipv.comp_id		= @comp_id							AND
						tmlipv.mlp_id		= @mlp_id							AND
						(
							tmlipva.MLid	= 'EAN' OR
							tmlipva.MLid	= 'GTIN'
						)														AND
						ISNULL(tmlipva.MLvalue_name,'') <> ''
		-- -------------------------------------------------------------------------------------


		--DEVOLVEMOS LOS EANS CONCATENADOS
		SELECT
			@strEans											[EANS],
			ISNULL(tmlip.mlp_statistics_MinPrice4Category,0)	[mlp_statistics_MinPrice4Category],
			ISNULL(tmlip.mlp_statistics_MaxPrice4Category,0)	[mlp_statistics_MaxPrice4Category],
			ISNULL(tmlip.mlp_statistics_AvgPrice4Category,0)	[mlp_statistics_AvgPrice4Category],
			ISNULL(tmlip.mlp_statistics_MinPrice4EAN,0)			[mlp_statistics_MinPrice4EAN],
			ISNULL(tmlip.mlp_statistics_MaxPrice4EAN,0)			[mlp_statistics_MaxPrice4EAN],
			ISNULL(tmlip.mlp_statistics_AvgPrice4EAN,0)			[mlp_statistics_AvgPrice4EAN],
			ISNULL(tmlip.mlp_statistics_AvgSales4Week,0)		[mlp_statistics_AvgSales4Week],
			tmlip.mlp_statistics_lastUpdate
		FROM tbMercadoLibre_ItemsPublicados AS	tmlip
		WHERE	tmlip.comp_id	= @comp_id		AND
				tmlip.mlp_id	= @mlp_id

	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_GetPublicationsByItemID]
(
	@comp_id	INT,
	@item_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT
			SELECT
				@comp_id	= 1,
				@item_id	= 15572
		*/
		-- -----------------------------------------

		SELECT DISTINCT
			tmlip.mlp_itemTitle,
			tmlip.mlp_permalink,
			tmls.mls_desc,
			CASE
			  WHEN tmlip.mlp_listing_type_id = 'gold_pro'		THEN 'Premium'
			  WHEN tmlip.mlp_listing_type_id = 'gold_premium'	THEN 'Oro Premium'
			  WHEN tmlip.mlp_listing_type_id = 'gold_special'	THEN 'Clásica'
			  WHEN tmlip.mlp_listing_type_id = 'gold'			THEN 'Oro'
			  WHEN tmlip.mlp_listing_type_id = 'silver'			THEN 'Plata'
			  WHEN tmlip.mlp_listing_type_id = 'bronze'			THEN 'Bronce'
			  WHEN tmlip.mlp_listing_type_id = 'free'			THEN 'Gratuita'
				ELSE												 tmlip.mlp_listing_type_id
			END													[mlp_listing_type_id]
		FROM tbMercadoLibre_ItemsPublicados					AS	tmlip	WITH(NOLOCK)
		LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations	AS	tmlipv	WITH(NOLOCK)
		ON	tmlipv.comp_id		= tmlip.comp_id					AND
			tmlipv.mlp_id		= tmlip.mlp_id
		INNER JOIN tbMercadoLibre_Stores					AS tmls		WITH (NOLOCK)
			ON	tmls.comp_id	= tmlip.comp_id AND
				tmls.mls_id		= tmlip.mls_id
		WHERE	tmlip.comp_id	= @comp_id						AND
				(
					tmlip.item_id	= @item_id		OR
					tmlipv.item_id	= @item_id
				)												AND
				tmlip.optval_statusId	= 2

	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_GetStockAvailability]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- ---------------------------------
		-- TESTING
		-- ---------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 1188
		*/
		-- ---------------------------------

		SELECT
			CONVERT(INT,ROUND(dbo.fnGetAStock4MaxAssociation(tmlip.comp_id, CASE
																				WHEN tmlip.stor_id4StockAvailability IS NOT NULL THEN	tmlip.stor_id4StockAvailability
																				ELSE													tmls.stor_id4StockAvailability
																			END, tmlip.item_id, 99999999),0))		[stock_Availability]
			FROM tbMercadoLibre_ItemsPublicados		tmlip	WITH(NOLOCK)
			INNER JOIN tbMercadoLibre_Stores		tmls	WITH(NOLOCK)
			ON	tmls.comp_id		= tmlip.comp_id AND
				tmls.mls_id			= tmlip.mls_id
			WHERE	tmlip.comp_id	= @comp_id		AND
					tmlip.mlp_id	= @mlp_id

	END
GO

CREATE PROCEDURE spMercadoLibre_ItemsPublicados_HasSKUorGTIN
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
		*/
		-- ---------------------------------------------------------------


		DECLARE
			@bitHasGTIN			BIT = 'False',
			@bitHasSELLER_SKU	BIT = 'False'


		SELECT TOP 1
			@bitHasGTIN = 'True'
			FROM tbMercadoLibre_ItemsPublicadosVariations					AS tmlipv	WITH(NOLOCK)
			INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Attributes	AS tmlipva	WITH(NOLOCK)
			ON		tmlipva.comp_id = tmlipv.comp_id	AND
					tmlipva.mlpv_id = tmlipv.mlpv_id
			WHERE	tmlipv.comp_id	= @comp_id			AND
					tmlipv.mlp_id	= @mlp_id			AND
					tmlipva.MLid	= 'GTIN'

		SELECT TOP 1
			@bitHasSELLER_SKU = 'True'
			FROM tbMercadoLibre_ItemsPublicadosVariations					AS tmlipv	WITH(NOLOCK)
			INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Attributes	AS tmlipva	WITH(NOLOCK)
			ON		tmlipva.comp_id = tmlipv.comp_id	AND
					tmlipva.mlpv_id = tmlipv.mlpv_id
			WHERE	tmlipv.comp_id	= @comp_id			AND
					tmlipv.mlp_id	= @mlp_id			AND
					tmlipva.MLid	= 'SELLER_SKU'

		SELECT
			@bitHasGTIN			[bitHasGTIN],
			@bitHasSELLER_SKU	[bitHasSELLER_SKU]

	END


GO



