	@mlp_forceSO4Commercial								BIT,
	@mlp_priceDirectDiscountPercentage					DECIMAL(19,2),
	@mlp_labelPrintModuleNoPrintSecondLabel				BIT,
	@mlp_warranty_type									NVARCHAR(25),
	@mlp_warranty_time									NVARCHAR(25),
	@mlp_warranty_time_value							INT,
	@stor_id4StockAvailability							INT,
	@mlp_blockCatalogPriceUpdateFromNormalPublication	BIT,
	@storg_id											INT,
	@prli_id4MercadoShop								INT,
	@mlp_fixPublicationDeliveryCharge					BIT,
	@mlp_channelID										INT,
	@mlp_blockPriceUpdate								BIT,
	@mlp_ahora6											BIT,
	@mlp_ahora24										BIT,
	@mlp_ahora3											BIT,
	@mlp_ahora18										BIT,
	@mlp_ahora30										BIT,
	@mlp_prli_id4MercadoShopPlusDeliveryCharge			BIT,
	@mlp_free_shippingMShops							BIT,
	@mlp_isAvailable4Price2Win							BIT,
	@mlp_ahora3mshops									BIT,
	@mlp_ahora6mshops									BIT,
	@mlp_ahora12mshops									BIT,
	@mlp_ahora24mshops									BIT,
	@mlp_ahora12_paidByBuyer							BIT,
	@mlp_blockPriceUpdate4mercadoShops					BIT,
	@mlp_is4FullAndFlex									BIT,
	@mlp_ahora3plan										BIT,
	@mlp_ahora3planmshops								BIT,
	@mlp_pcjcofunded									BIT,
	@mlp_pcjcofundedmshops								BIT,
	@mlp_cuotasimple3									BIT,
	@mlp_cuotasimple6									BIT,
	@mlp_cuotasimple_paidbybuyer						BIT,
	@mlp_cuotasimple3mshops								BIT,
	@mlp_cuotasimple6mshops								BIT,
	@mlp_9xCampaign										BIT,
	@mlp_9xCampaignmshops								BIT,
	@mlp_family_name									VARCHAR(500),
	@mlp_cuotasimple12									BIT,
	@mlp_12xCampaign									BIT,
	@mlp_cuotasimple12mshops							BIT,
	@mlp_12xCampaignmshops								BIT,
	@return_value										INT OUTPUT
)
AS

	BEGIN
		SET NOCOUNT ON

		SET DATEFORMAT 'ymd'

		--SACAR DESPUES ESTO
		--*99999999
		-- -------------------------------------------
		-- RECUPERO EL PRLI_ID Y EL STOR_ID DE LA
		-- STORE SELECCIONADA DE ML
		-- -------------------------------------------
		DECLARE
			--@lprli_id	INT,
			@lstor_id	INT
		SELECT
			@lstor_id = tmls.stor_id,
			@prli_id  = CASE
							WHEN @prli_id = -1			THEN TMLS.prli_id
							ELSE							 @prli_id
						END
			FROM tbMercadoLibre_Stores			tmls			WITH (NOLOCK)
			WHERE	tmls.comp_id	= @comp_id	AND 
					tmls.mls_id		= @mls_id
		-- -------------------------------------------

		IF @st_id = -1
			BEGIN
				SET @st_id = NULL
			END

		IF @disc_id = -1
			BEGIN
				SET @disc_id = NULL
			END

		IF @dl_id = -1
			BEGIN
				SET @dl_id = NULL
			END

		IF @mlp_free_method = -1
			BEGIN
				SET @mlp_free_method = NULL
			END

		IF @mlmp_id = -1
			BEGIN
				SET @mlmp_id = NULL
			END

		IF @mlipc_id = -1
			BEGIN
				SET @mlipc_id = NULL
			END

		IF @mlp_warranty_type = ''
			BEGIN
				SET @mlp_warranty_type = NULL
			END

		IF @mlp_warranty_time = ''
			BEGIN
				SET @mlp_warranty_time = NULL
			END

		IF @mlp_warranty_time_value = 0
			BEGIN
				SET @mlp_warranty_time_value = NULL
			END

		IF @stor_id4StockAvailability = -1
			BEGIN
				SET @stor_id4StockAvailability = NULL
			END

		IF @storg_id = -1
			BEGIN
				SET @storg_id = NULL
			END

		IF @mlp_channelID	= -1
			BEGIN
				SET @mlp_channelID = NULL
			END

		IF @prli_id4MercadoShop = -1
			BEGIN
				SET @prli_id4MercadoShop = NULL
			END





		INSERT INTO tbMercadoLibre_ItemsPublicados
		(
			comp_id,
			bra_id,
			stor_id,
			prli_id,
			item_id,
			mlp_initQty,
			mlp_price,
			curr_id,
			optval_statusId,
			mlp_inicDate,
			mlp_endDate,
			mlp_lastUpdate,
			[user_id],
			mlp_Active,
			mlp_itemDesc,
			mlp_itemHTML,
			mls_id,
			mlp_itemTitle,
			mlp_minQty4Pause,
			mlp_listing_type_id,
			mlp_listing_fee_amount,
			mlp_sale_fee_amount,
			--mlp_publicationID,
			mlp_buying_mode,
			mlp_itemSubTitle,
			mlp_start_time,
			mlp_stop_time,
			mlp_sold_quantity,
			mlp_permalink,
			mlp_thumbnail,
			mlp_video_id,
			mlp_accepts_mercadopago,
			mlp_warranty,
			mlp_local_pick_up,
			mlp_free_shipping,
			mlp_publicationCategoryID,
			mlp_isFixedPrice,
			st_id,
			disc_id,
			dl_id,
			mlp_free_method,
			mlmp_id,
			mlipc_id,
			mlp_lastJSonValidation,
			mlp_allowPublicationsWithNoStock,
			mlp_price4FreeShipping,
			mlp_price4AdditionalCost,
			mlp_ahora12,
			mlp_forceSO4Commercial,
			mlp_priceDirectDiscountPercenage,
			mlp_labelPrintModuleNoPrintSecondLabel,
			mlp_warranty_type,
			mlp_warranty_time,
			mlp_warranty_time_value,
			stor_id4StockAvailability,
			mlp_blockCatalogPriceUpdateFromNormalPublication,
			storg_id,
			prli_id4MercadoShop,
			mlp_fixPublicationDeliveryCharge,
			mlp_channelID,
			mlp_blockPriceUpdate,
			mlp_ahora6,
			mlp_ahora24,
			mlp_ahora3,
			mlp_ahora18,
			mlp_ahora30,
			mlp_prli_id4MercadoShopPlusDeliveryCharge,
			mlp_free_shippingMShops,
			mlp_isAvailable4Price2Win,
			mlp_blockPriceUpdate4mercadoShops,
			mlp_is4FullAndFlex,
			mlp_ahora3plan,
			mlp_ahora3planmshops,
			mlp_pcjcofunded,
			mlp_pcjcofundedmshops,
			mlp_cuotasimple3,
			mlp_cuotasimple6,
			mlp_cuotasimple_paidbybuyer,
			mlp_cuotasimple3mshops,
			mlp_cuotasimple6mshops,
			mlp_9xCampaign,
			mlp_9xCampaignmshops,
			mlp_family_name,
			mlp_cuotasimple12,
			mlp_12xCampaign,
			mlp_cuotasimple12mshops,
			mlp_12xCampaignmshops
		)
		VALUES
		(
			@comp_id,
			@bra_id,
			@lstor_id,
			@prli_id, --@lprli_id,
			@item_id,
			@mlp_initQty,
			@mlp_price,
			@curr_id,
			@optval_statusId,
			@mlp_inicDate,
			@mlp_endDate,
			GETDATE(),
			@user_id,
			'False',
			@mlp_itemDesc,
			@mlp_itemHTML,
			@mls_id,
			@mlp_itemTitle,
			@mlp_minQty4Pause,
			@listing_type_id,
			@listing_fee_amount,
			@sale_fee_amount,
			@buying_mode,
			@itemSubTitle,
			@start_time,
			@stop_time,
			@sold_quantity,
			@permalink,
			@thumbnail,
			@video_id,
			@accepts_mercadopago,
			@warranty,
			@local_pick_up,
			@free_shipping,
			@mlp_publicationCategoryID,
			@mlp_isFixedPrice,
			@st_id,
			@disc_id,
			@dl_id,
			@mlp_free_method,
			@mlmp_id,
			@mlipc_id,
			@mlp_lastJSonValidation,
			@mlp_allowPublicationsWithNoStock,
			@mlp_price4FreeShipping,
			@mlp_price4AdditionalCost,
			@mlp_ahora12,
			@mlp_forceSO4Commercial,
			@mlp_priceDirectDiscountPercentage,
			@mlp_labelPrintModuleNoPrintSecondLabel,
			@mlp_warranty_type,
			@mlp_warranty_time,
			@mlp_warranty_time_value,
			@stor_id4StockAvailability,
			@mlp_blockCatalogPriceUpdateFromNormalPublication,
			@storg_id,
			@prli_id4MercadoShop,
			@mlp_fixPublicationDeliveryCharge,
			@mlp_channelID,
			@mlp_blockPriceUpdate,
			@mlp_ahora6,
			@mlp_ahora24,
			@mlp_ahora3,
			@mlp_ahora18,
			@mlp_ahora30,
			@mlp_prli_id4MercadoShopPlusDeliveryCharge,
			@mlp_free_shippingMShops,
			@mlp_isAvailable4Price2Win,
			@mlp_blockPriceUpdate4mercadoShops,
			@mlp_is4FullAndFlex,
			@mlp_ahora3plan,
			@mlp_ahora3planmshops,
			@mlp_pcjcofunded,
			@mlp_pcjcofundedmshops,
			@mlp_cuotasimple3,
			@mlp_cuotasimple6,
			@mlp_cuotasimple_paidbybuyer,
			@mlp_cuotasimple3mshops,
			@mlp_cuotasimple6mshops,
			@mlp_9xCampaign,
			@mlp_9xCampaignmshops,
			@mlp_family_name,
			@mlp_cuotasimple12,
			@mlp_12xCampaign,
			@mlp_cuotasimple12mshops,
			@mlp_12xCampaignmshops
		)

		SET	@return_value = @@IDENTITY

		--COMO PASO FINAL PONEMOS COMO DISPONIBLE PARA ML EL ARTÍCULO
		IF @overWriteDescriptions = 'True'
			BEGIN
				UPDATE tbItem
				SET
					item_ML_isAvailable			= 'True',

					item_ML_desc				= @mlp_itemDesc,
					item_ML_html4Publication	= @mlp_itemHTML,
					item_ML_url4video			= @video_id,
					item_ML_title				= @mlp_itemTitle
				WHERE	comp_id = @comp_id	AND
						item_id = @item_id
			END
		ELSE
			BEGIN
				UPDATE tbItem
				SET
					item_ML_isAvailable			= 'True',

					item_ML_desc				= CASE WHEN item_ML_title		= ''	THEN @mlp_itemDesc	ELSE item_ML_desc				END,
					item_ML_html4Publication	= CASE WHEN item_ML_title		= ''	THEN @mlp_itemHTML	ELSE item_ML_html4Publication	END,
					item_ML_url4video			= CASE WHEN item_ML_url4video	= ''	THEN @video_id		ELSE item_ML_url4video			END,
					item_ML_title				= CASE WHEN item_ML_title		= ''	THEN @mlp_itemTitle ELSE item_ML_title				END
				WHERE	comp_id = @comp_id	AND
						item_id = @item_id
			END





	END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_InsertDataForMassivePublicationByExcel]
(
	@comp_id							INT,
	@lang_id							INT,
	@bra_id								INT,
	@user_id							INT,
	@prof_id							INT,
	@mls_id								INT,
	@strML_CategoryID					NVARCHAR(50),
	@strML_ListingType					NVARCHAR(50),
	@item_code							NVARCHAR(50),
	@strML_Title						NVARCHAR(100),
	@strML_Desc							NVARCHAR(MAX),
	@prli_id							INT,
	@stor_id							INT,
	@strImageIDorURL1					NVARCHAR(500),
	@strImageIDorURL2					NVARCHAR(500),
	@strImageIDorURL3					NVARCHAR(500),
	@strImageIDorURL4					NVARCHAR(500),
	@strImageIDorURL5					NVARCHAR(500),
	@strAttributes						NVARCHAR(MAX),
	@mlp_accepts_mercadopago			BIT,
	@mlp_local_pick_up					BIT,
	@mlp_free_shipping					BIT,
	@mlp_isFixedPrice					BIT,
	@mlp_allowPublicationsWithNoStock	BIT,
	@mlipc_id							INT,
	@guid								UNIQUEIDENTIFIER,
	@strImageIDorURL6					NVARCHAR(500),
	@strImageIDorURL7					NVARCHAR(500),
	@strImageIDorURL8					NVARCHAR(500),
	@strImageIDorURL9					NVARCHAR(500),
	@strImageIDorURL10					NVARCHAR(500),

	@strWarrantyType					NVARCHAR(25),
	@strWarrantyTime					NVARCHAR(25),
	@intWarrantyTime_Value				INT,
	@mlp_initQty						INT,
	@mlp_price4AdditionalCost			DECIMAL(19,2)

)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id							INT,
				@lang_id							INT,
				@bra_id								INT,
				@user_id							INT,
				@mls_id								INT,
				@strML_CategoryID					NVARCHAR(50),
				@strML_ListingType					NVARCHAR(50),
				@item_code							NVARCHAR(50),
				@strML_Title						NVARCHAR(100),
				@strML_Desc							NVARCHAR(MAX),
				@prli_id							INT,
				@stor_id							INT,
				@strImageIDorURL1					NVARCHAR(500),
				@strImageIDorURL2					NVARCHAR(500),
				@strImageIDorURL3					NVARCHAR(500),
				@strImageIDorURL4					NVARCHAR(500),
				@strImageIDorURL5					NVARCHAR(500),
				@strAttributes						NVARCHAR(MAX),
				@mlp_accepts_mercadopago			BIT,
				@mlp_local_pick_up					BIT,
				@mlp_free_shipping					BIT,
				@mlp_isFixedPrice					BIT,
				@mlp_allowPublicationsWithNoStock	BIT,
				@mlipc_id							INT,
				@guid								UNIQUEIDENTIFIER,
				@strWarrantyType					NVARCHAR(25),
				@strWarrantyTime					NVARCHAR(25),
				@intWarrantyTime_Value				INT,
				@mlp_initQty						INT
			SELECT
				@comp_id							= 1,
				@lang_id							= 2,
				@bra_id								= 1,
				@user_id							= 1,
				@mls_id								= 5,
				@strML_CategoryID					= 'MLA377254',
				@strML_ListingType					= 'gold_special',
				@item_code							= 'KitFiltros',
				@strML_Title						= 'Kit 2 filtros + Aceite Peugeot Partner 1.6 Nafta vti',
				@strML_Desc							= '',
				@prli_id							= 1,
				@stor_id							= 3,
				@strImageIDorURL1					= '',
				@strImageIDorURL2					= '',
				@strImageIDorURL3					= '',
				@strImageIDorURL4					= '',
				@strImageIDorURL5					= '',
				@strAttributes						= 'BRAND&*&Original|PART_NUMBER&*&1444TV / 1109AY / 1906E6 / 6479A1|INCLUDES_AIR_FILTER&*&Si|INCLUDES_OIL_FILTER&*&Si|INCLUDES_AC_FILTER&*&Si|INCLUDES_FUEL_FILTER&*&Si|INCLUDES_OIL&*&Si|',
				@mlp_accepts_mercadopago			= 'True',
				@mlp_local_pick_up					= 'True',
				@mlp_free_shipping					= 'True',
				@mlp_isFixedPrice					= 'False',
				@mlp_allowPublicationsWithNoStock	= 'False',
				@mlipc_id							= 8,
				@guid								= '75a79f2d-49a3-463d-ad97-6d0299adc19a',
				@strWarrantyType					= 'Garantía del vendedor',
				@strWarrantyTime					= '',
				@intWarrantyTime_Value				= '',
				@mlp_initQty						= 3
		*/
		-- -----------------------------------------------------------------------------


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -------------------------------------------------------------
		-- RECUPERAR EL ID DEL ARTICULO POR CODIGO
		-- -------------------------------------------------------------
			DECLARE @lItemID	AS INT
			DECLARE @lVideoYT	AS NVARCHAR(300)
			SELECT
				@lItemID			= ti.item_id,
				@lVideoYT			= ti.item_ML_url4video
			FROM tbItem							ti	WITH(NOLOCK)
			WHERE	ti.comp_id		= @comp_id	AND
					ti.item_code	= @item_code
			IF @lItemID IS NULL
				BEGIN
					SELECT -1 [lMLP_ID]
					RETURN
				END
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- RECUPERO LA MONEDA DE LA TIENDA
		-- -------------------------------------------------------------
			DECLARE @MLS_curr_id	INT
			SELECT
				@MLS_curr_id		= tmls.curr_id
			FROM tbMercadoLibre_Stores			tmls	WITH(NOLOCK)
			WHERE	tmls.comp_id	= @comp_id	AND
					tmls.mls_id		= @mls_id
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- RECUPERAR EL PRECIO DEL ARTÍCULO Y LA MONEDA
		-- -------------------------------------------------------------
			DECLARE	@decPrice AS	DECIMAL(19,4)
			SELECT
				@decPrice	= dbo.fnGetExchange2(tpli.comp_id, tpli.prli_price, tpli.curr_id, @MLS_curr_id, 0, 0, 0, 'False')
			FROM tbPriceListItems			tpli	WITH(NOLOCK)
			WHERE	tpli.comp_id = @comp_id AND
					tpli.prli_id = @prli_id AND
					tpli.item_id = @lItemID
			IF ISNULL(@decPrice,0) = 0
				BEGIN
					SELECT -1 [lMLP_ID]
					RETURN
				END
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- RECUPERAR EL STOCK DISPONIBLE PARA EL DEPÓSITO
		-- -------------------------------------------------------------
			DECLARE @intStockDisponible AS INT
			SELECT
				@intStockDisponible = dbo.fngetastock4maxassociation(@comp_id,
																    @stor_id,
																    @lItemID,
																    99999999)


				--@intStockDisponible = dbo.fnGetAStock(@comp_id,
				--									  @stor_id,
				--									  @lItemID,
				--									  99999999)

			IF	@mlp_allowPublicationsWithNoStock	= 'False' AND
				@intStockDisponible					<= 0
				BEGIN
					SELECT -1 [lMLP_ID]
					RETURN
				END
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- RECUPERAR DE LA TIENDA ST_ID DISC_ID DL_ID SM_ID
		-- -------------------------------------------------------------
			DECLARE
				@st_id		INT,
				@disc_id	INT,
				@dl_id		INT,
				@sm_id		INT
			SELECT
				@st_id		= tmls.st_id,
				@disc_id	= tmls.disc_id,
				@dl_id		= tmls.dl_id,
				@sm_id		= tmls.sm_id
			FROM tbMercadoLibre_Stores			tmls	WITH(NOLOCK)
			WHERE	tmls.comp_id	= @comp_id	AND
					tmls.mls_id		= @mls_id
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- GARANTIA
		-- -------------------------------------------------------------
			--SEGUN LA GARANTIA QUE LE PONGO ES EL ID QUE LE TENGO QUE GRABAR
			IF @strWarrantyType = 'Garantía del vendedor'
				BEGIN
					SET @strWarrantyType = '2230280'
				END
			IF @strWarrantyType = 'Garantía de fábrica'
				BEGIN
					SET @strWarrantyType = '2230279'
				END
			IF @strWarrantyType = 'Sin garantía'
				BEGIN
					SET @strWarrantyType = '6150835'
				END

			-- SI ALGUNO NO TIENE VALOR, NO LE PONGO NADA EN LA GARANTIA
			-- YA ESTA EXPLICADO EN EL HELP DE LA PAGINA TAMBIEN
			IF(@strWarrantyType)= '' OR
				(@strWarrantyTime = '') OR
					(@intWarrantyTime_Value = 0)
				BEGIN
					SET @strWarrantyType		= ''
					SET @strWarrantyTime		= ''
					SET @intWarrantyTime_Value	= 0
				END
		-- -------------------------------------------------------------




		INSERT INTO tbMercadoLibre_ItemsPublicados
		(
			comp_id,
			bra_id,
			stor_id,
			prli_id,
			item_id,
			mlp_initQty,
			mlp_price,
			curr_id,
			optval_statusId,
			[user_id],
			mlp_Active,
			mls_id,
			mlp_itemTitle,
			mlp_listing_type_id,
			mlp_buying_mode,
			mlp_sold_quantity,
			mlp_permalink,
			mlp_thumbnail,
			mlp_video_id,
			mlp_accepts_mercadopago,
			mlp_local_pick_up,
			mlp_free_shipping,
			mlp_publicationCategoryID,
			mlipc_id,
			mlp_isFixedPrice,
			st_id,
			disc_id,
			dl_id,
			mlp_itemDesc,
			mlp_allowPublicationsWithNoStock,
			mlp_listing_fee_amount,
			mlp_sale_fee_amount,
			mlp_warranty_type,
			mlp_warranty_time,
			mlp_warranty_time_value
		)
		SELECT
			@comp_id,
			@bra_id,
			@stor_id,
			@prli_id,
			@litemID,
			@mlp_initQty,	--@intStockDisponible,
			@decPrice,
			@MLS_curr_id,
			1,
			@user_id,
			'True',
			@mls_id,
			@strML_Title,
			@strML_ListingType,
			'buy_it_now',
			0,
			NULL,
			NULL,
			@lVideoYT,
			@mlp_accepts_mercadopago,
			@mlp_local_pick_up,
			@mlp_free_shipping,
			@strML_CategoryID,
			@mlipc_id,
			@mlp_isFixedPrice,
			@st_id,
			@disc_id,
			@dl_id,
			@strML_Desc,
			@mlp_allowPublicationsWithNoStock,
			0,
			0,
			@strWarrantyType,
			@strWarrantyTime,
			@intWarrantyTime_Value


		DECLARE	@lMLP_ID AS INT
		SET		@lMLP_ID = -1
		SET		@lMLP_ID = @@IDENTITY

		-- ACTUALIZO EL PRECIO ADICIONAL
		UPDATE tbMercadoLibre_ItemsPublicados
		SET
			mlp_price4AdditionalCost	= @mlp_price4AdditionalCost
		WHERE	comp_id					= @comp_id AND
				mlp_id					= @lMLP_ID

		-- -------------------------------------------------------------------
		-- Variables para el Cursor
		-- -------------------------------------------------------------------
			DECLARE
				@AttributeID				NVARCHAR(100),
				@AttributeValue				NVARCHAR(100),
				@AtrributeString			NVARCHAR(1000)
		-- -------------------------------------------------------------------
			--DECLARE @intAttributeCounter AS INT
			--SET @intAttributeCounter = 0

			DECLARE Cursor_PublicationAttributes CURSOR LOCAL FAST_FORWARD FOR
				--ACA VA EL STRING QUE VA A SEPARAR EN UNA TABLA DE TRIADAS DE ATRIBUTOS
				SELECT
					fst.items
				FROM
					dbo.fnSplitTable(@strAttributes,'|') fst

			OPEN Cursor_PublicationAttributes
			FETCH NEXT FROM Cursor_PublicationAttributes
			INTO
				@AtrributeString
			WHILE @@FETCH_STATUS = 0
				BEGIN
					--ACA HAGO EL SPLIT DE CADA DUPLA PARA ARMAR LAS COLUMNAS
					SELECT
						@AttributeID = dbo.fnSplitPosition(@AtrributeString, '&*&', 1)
					SELECT
						@AttributeValue = dbo.fnSplitPosition(@AtrributeString, '&*&', 2)

					IF @AttributeValue <> ''
						BEGIN

							IF @AttributeValue = 'N/A'
								BEGIN
									SET @AttributeValue = '-1'
								END

							INSERT INTO tbMercadoLibre_ItemsPublicadosAttributes
							(
								comp_id,
								mlp_id,
								MLid,
								mlat_valueString
							)
							SELECT
								@comp_id,
								@lMLP_ID,
								@AttributeID,
								@AttributeValue
						END
					FETCH NEXT FROM Cursor_PublicationAttributes
					INTO
						@AtrributeString
				END
			CLOSE Cursor_PublicationAttributes
			DEALLOCATE Cursor_PublicationAttributes
		-- -------------------------------------------------------------------

		-- -------------------------------------------------------------------
		-- GENERAMOS EL REGISTRO EN LA PROCESSQUEUE PARA QUE HAGA LA PUBLICACIÓN
		-- -------------------------------------------------------------------
			INSERT INTO tbMercadoLibre_updateQueue
			(
				comp_id,
				mlp_id,
				mlproc_cd,
				[user_id],
				mlproc_option,
				mlproc_stringValue,
				--mlproc_integerValue,
				--mlproc_decimalValue,
				mlproc_priority,
				mlproc_guid,
				mlproc_textValue
			)
			SELECT
				@comp_id,
				@lMLP_ID,
				GETDATE(),
				@user_id,
				1,
				'',
				--0,
				--0,
				-99999999,
				@guid,
				''
				DECLARE @processQueue AS INT
				SET @processQueue = -1
				SET @processQueue = @@IDENTITY
		-- -------------------------------------------------------------------


		-- -------------------------------------------------------------------
		-- GENERO UN REGISTRO MAS PARA QUE ACTUALICE LA DESCRIPCION
		-- -- 02-01-2020 STL
		-- -------------------------------------------------------------------
		INSERT INTO tbMercadoLibre_updateQueue
			(
				comp_id,
				mlp_id,
				mlproc_cd,
				[user_id],
				mlproc_option,
				mlproc_stringValue,
				--mlproc_integerValue,
				--mlproc_decimalValue,
				mlproc_priority,
				mlproc_guid,
				mlproc_textValue
			)
			SELECT
				@comp_id,
				@lMLP_ID,
				GETDATE(),
				@user_id,
				3,
				'',
				--0,
				--0,
				0,
				@guid,
				''
		-- -------------------------------------------------------------------

		-- -------------------------------------------------------------------
		-- DEVOLVEMOS EL MLP_ID QUE SE GENERÓ
		-- -------------------------------------------------------------------
			SELECT @lMLP_ID [lMLP_ID], @processQueue [ProcessQueue]
		-- -------------------------------------------------------------------

	END
GO


CREATE  PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_InsertDataFromMercadoLibrePublication]
(
	@comp_id							INT,
	@bra_id								INT,
	@stor_id							INT,
	@prli_id							INT,
	@item_id							INT,
	@mlp_initQty						INT,
	@mlp_price							DECIMAL(19,4),
	@curr_id							INT,
	@optval_statusId					INT,
	@mlp_inicDate						DATETIME,
	@mlp_endDate						DATETIME,
	@user_id							INT,
	@mlp_Active							BIT,
	@mls_id								INT,
	@mlp_itemTitle						NVARCHAR(500),
	@mlp_minQty4Pause					INT,
	@mlp_listing_type_id				NVARCHAR(100),
	@mlp_listing_fee_amount				DECIMAL(19,6),
	@mlp_sale_fee_amount				DECIMAL(19,6),
	@mlp_publicationID					NVARCHAR(30),
	@mlp_buying_mode					NVARCHAR(20),
	@mlp_start_time						DATETIME,
	@mlp_stop_time						DATETIME,
	@mlp_sold_quantity					INT,
	@mlp_permalink						NVARCHAR(1000),
	@mlp_thumbnail						NVARCHAR(1000),
	@mlp_video_id						NVARCHAR(1000),
	@mlp_accepts_mercadopago			BIT,
	@mlp_warranty						NVARCHAR(500),
	@mlp_local_pick_up					BIT,
	@mlp_free_shipping					BIT,
	@mlp_publicationCategoryID			NVARCHAR(30),
	@mlipc_id							INT,
	@mlp_isFixedPrice					BIT,
	@mlp_lastPublicatedPrice			DECIMAL(19,4),
	@mlp_lastPublicatedCurrID			INT,
	@st_id								INT,
	@disc_id							INT,
	@dl_id								INT,
	@mlp_free_method					BIGINT,
	@mlp_itemDesc						NTEXT,
	@mlp_itemHTML						NTEXT,
	@mlp_lastJSonValidation				NTEXT,
	@overWriteDescriptions				BIT,
	@mlp_allowPublicationsWithNoStock	BIT,
	@mlp_ahora12						BIT,
	@mlp_forceSO4Commercial				BIT,
	@mlp_official_store_id				NVARCHAR(20),
	@mlp_catalog_product_id				NVARCHAR(20),
	@mlp_warranty_type					NVARCHAR(25),
	@mlp_warranty_time					NVARCHAR(25),
	@mlp_warranty_time_value			INT
)
AS
BEGIN
	SET NOCOUNT ON

	IF @mlipc_id = -1
		BEGIN
			SET @mlipc_id = NULL
		END

	IF @mlp_warranty_type = ''
			BEGIN
				SET @mlp_warranty_type = NULL
			END

		IF @mlp_warranty_time = ''
			BEGIN
				SET @mlp_warranty_time = NULL
			END

		IF @mlp_warranty_time_value = 0
			BEGIN
				SET @mlp_warranty_time_value = NULL
			END

	INSERT INTO tbMercadoLibre_ItemsPublicados
	(
		comp_id,
		bra_id,
		stor_id,
		prli_id,
		item_id,
		mlp_initQty,
		mlp_price,
		curr_id,
		optval_statusId,
		mlp_inicDate,
		mlp_endDate,
		[user_id],
		mlp_Active,
		mls_id,
		mlp_itemTitle,
		mlp_minQty4Pause,
		mlp_listing_type_id,
		mlp_listing_fee_amount,
		mlp_sale_fee_amount,
		mlp_publicationID,
		mlp_buying_mode,
		mlp_start_time,
		mlp_stop_time,
		mlp_sold_quantity,
		mlp_permalink,
		mlp_thumbnail,
		mlp_video_id,
		mlp_accepts_mercadopago,
		mlp_warranty,
		mlp_local_pick_up,
		mlp_free_shipping,
		mlp_publicationCategoryID,
		mlipc_id,
		mlp_isFixedPrice,
		mlp_lastPublicatedPrice,
		mlp_lastPublicatedCurrID,
		st_id,
		disc_id,
		dl_id,
		mlp_free_method,
		mlp_itemDesc,
		mlp_itemHTML,
		mlp_lastJSonValidation,
		mlp_allowPublicationsWithNoStock,
		mlp_ahora12,
		mlp_forceSO4Commercial,
		mlp_official_store_id,
		mlp_catalog_product_id,
		mlp_warranty_type,
		mlp_warranty_time,
		mlp_warranty_time_value
	)
	VALUES
	(
		@comp_id,
		@bra_id,
		@stor_id,
		@prli_id,
		@item_id,
		@mlp_initQty,
		@mlp_price,
		@curr_id,
		@optval_statusId,
		@mlp_inicDate,
		@mlp_endDate,
		@user_id,
		@mlp_Active,
		@mls_id,
		@mlp_itemTitle,
		@mlp_minQty4Pause,
		@mlp_listing_type_id,
		@mlp_listing_fee_amount,
		@mlp_sale_fee_amount,
		@mlp_publicationID,
		@mlp_buying_mode,
		@mlp_start_time,
		@mlp_stop_time,
		@mlp_sold_quantity,
		@mlp_permalink,
		@mlp_thumbnail,
		@mlp_video_id,
		@mlp_accepts_mercadopago,
		@mlp_warranty,
		@mlp_local_pick_up,
		@mlp_free_shipping,
		@mlp_publicationCategoryID,
		@mlipc_id,
		@mlp_isFixedPrice,
		@mlp_lastPublicatedPrice,
		@mlp_lastPublicatedCurrID,
		@st_id,
		@disc_id,
		@dl_id,
		@mlp_free_method,
		@mlp_itemDesc,
		@mlp_itemHTML,
		@mlp_lastJSonValidation,
		@mlp_allowPublicationsWithNoStock,
		@mlp_ahora12,
		@mlp_forceSO4Commercial,
		@mlp_official_store_id,
		@mlp_catalog_product_id,
		@mlp_warranty_type,
		@mlp_warranty_time,
		@mlp_warranty_time_value
	)

	SELECT @@IDENTITY	[MLP_ID]


	DELETE FROM tbMercadoLibre_ItemsPublicados_LinkPending	WITH (ROWLOCK)
		WHERE	comp_id				= @comp_id				AND
				mlpp_publicationID	= @mlp_publicationID


	RETURN


	IF @overWriteDescriptions = 'True'
		BEGIN
			UPDATE tbItem
			SET
				item_ML_isAvailable			= 'True',
				item_ML_desc				= @mlp_itemDesc,
				item_ML_html4Publication	= @mlp_itemHTML,
				item_ML_url4video			= @mlp_video_id,
				item_ML_title				= SUBSTRING(@mlp_itemTitle,0,250)
			WHERE	comp_id = @comp_id	AND
					item_id = @item_id
		END
	ELSE
		BEGIN
			UPDATE tbItem
			SET
				item_ML_isAvailable			= 'True',
				item_ML_desc				= CASE WHEN ISNULL(item_ML_title,'')		= ''	THEN @mlp_itemDesc	ELSE item_ML_desc				END,
				item_ML_html4Publication	= CASE WHEN ISNULL(item_ML_title,'')		= ''	THEN @mlp_itemHTML	ELSE item_ML_html4Publication	END,
				item_ML_url4video			= CASE WHEN ISNULL(item_ML_url4video,'')	= ''	THEN @mlp_video_id	ELSE item_ML_url4video			END,
				-- SIEMPRE DEJAR ULTIMO ESTE CAMPO !!!!!!!
				item_ML_title				= CASE WHEN ISNULL(item_ML_title,'')		= ''	THEN SUBSTRING(@mlp_itemTitle,0,250) ELSE item_ML_title				END
			WHERE	comp_id = @comp_id	AND
					item_id = @item_id
		END

END
GO

