					tmlip.mlp_Price2WinLastActivation,
					tmlip.mlp_Price2WinLastPrice,
					tmlip.mlp_ahora3mshops,
					tmlip.mlp_ahora6mshops,
					tmlip.mlp_ahora12mshops,
					tmlip.mlp_ahora24mshops,
					tmlip.mlp_ahora12_paidByBuyer,
					tmlip.mlp_manufacturing_time,
					tmlip.mlp_blockPriceUpdate4mercadoShops,
					tmlip.mlp_is4FullAndFlex,
					tmlip.mlp_ahora3plan,
					tmlip.mlp_pcjcofunded,
					tmlip.mlp_pcjcofundedmshops,
					tmlip.mlp_ahora3planmshops,
					tmlip.mlp_cuotasimple3,
					tmlip.mlp_cuotasimple6,
					tmlip.mlp_cuotasimple_paidbybuyer,
					tmlip.mlp_cuotasimple3mshops,
					tmlip.mlp_cuotasimple6mshops,
					tmlip.mlp_notExistsInMeli_by404,
					tmlip.mlp_9xCampaign,
					tmlip.mlp_9xCampaignmshops,
					@ml_FamilyName
					FROM tbMercadoLibre_ItemsPublicados AS tmlip	WITH(NOLOCK)
					WHERE	tmlip.comp_id	= @comp_id AND
							tmlip.mlp_id	= @mlp_id

					SELECT ISNULL(@@IDENTITY,-1) [mlp_id]
			END
		ELSE
			BEGIN
				SELECT
					tmlip.mlp_id
					FROM tbMercadoLibre_ItemsPublicados				AS tmlip	WITH(NOLOCK)
					WHERE	tmlip.comp_id			= @comp_id		AND
							tmlip.mlp_publicationID = @ml_PublicationID_New
			END


	END


GO

