CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_Massive_Clone_getDataByFilters]
(


	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,

	@ItemGuid				UNIQUEIDENTIFIER,
	@mls_id					INT,
	@mlp_listing_type_id	NVARCHAR(100),
	@prli_id				INT,
	@stor_id				INT,
	@Guid4Selection			UNIQUEIDENTIFIER,
	@mlipc_id				INT


)
AS

	BEGIN

		SET NOCOUNT ON

		-- ------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------
			/*
		DECLARE
			@comp_id				INT,
			@lang_id				INT,
			@bra_id					INT,
			@user_id				INT,
			@prof_id				INT,
			@ItemGuid				UNIQUEIDENTIFIER,
			@mls_id					INT,
			@mlp_listing_type_id	NVARCHAR(100),
			@prli_id				INT,
			@stor_id				INT


		SELECT
			@comp_id				= 1,
			@lang_id				= 2,
			@bra_id					= 1,
			@user_id				= 1,
			@prof_id				= 1,
			@ItemGuid				= '9E569AD0-BF26-49F1-A532-AA3B380023BF',
			@mls_id					= -1,
			@mlp_listing_type_id	='-1',
			@prli_id				=-1,
			@stor_id				=-1
			*/

		-- ------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		------------------------------------------------------------------------------------
		DECLARE @objGUID AS UNIQUEIDENTIFIER
		SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@ItemGuid)

		DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)

		INSERT INTO @tblComplexFilter_Items

			SELECT
				tcf.sl_id
				FROM tbComplexFilter tcf      WITH (NOLOCK)
				WHERE tcf.sl_guid	  = @objGUID      AND
					  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
		------------------------------------------------------------------------------------

		SELECT
			' '																							[ ],
			tttmu.bitValue1																				[checked],
			--tmlip.item_id																				[item_id],
			--ti.item_code																				[item_code],
			CASE
			  WHEN tmlip.mlp_listing_type_id = 'gold_pro'		THEN 'Premium'
			  WHEN tmlip.mlp_listing_type_id = 'gold_premium'	THEN 'Oro Premium'
			  WHEN tmlip.mlp_listing_type_id = 'gold_special'	THEN 'Clásica'
			  WHEN tmlip.mlp_listing_type_id = 'gold'			THEN 'Oro'
			  WHEN tmlip.mlp_listing_type_id = 'silver'			THEN 'Plata'
			  WHEN tmlip.mlp_listing_type_id = 'bronze'			THEN 'Bronce'
			  WHEN tmlip.mlp_listing_type_id = 'free'			THEN 'Gratuita'
			ELSE													 ''
			END																							[mlp_listing_type_id],
			tmlip.mlp_itemTitle																			[mlp_itemTitle],
			tpl.prli_desc																				[prli_desc],
			ts.stor_desc																				[stor_desc],
			tmlipc.mlipc_desc																			[mlipc_desc],
			tmlip.mlp_publicationID																		[mlp_publicationID],
			tmlip.mlp_id																				[ID]

			FROM tbMercadoLibre_ItemsPublicados					tmlip		WITH (NOLOCK)
			INNER JOIN tbItem									ti			WITH (NOLOCK)
				ON	ti.comp_id			= tmlip.comp_id			AND
					ti.item_id			= tmlip.item_id
			INNER JOIN @tblComplexFilter_Items					tmp
				ON	tmp.item_id			= tmlip.item_id
			LEFT JOIN tbTemporaryTable4MultipleUse				tttmu		WITH (NOLOCK)
				ON	tttmu.guidID		= @Guid4Selection
				AND tttmu.integerValue1  = tmlip.mlp_id
			LEFT JOIN tbPriceList								tpl			WITH (NOLOCK)
				ON tpl.comp_id			= tmlip.comp_id			AND
				   tpl.prli_id			= tmlip.prli_id
			LEFT JOIN tbStorage									ts			WITH (NOLOCK)
				ON	ts.comp_id			= tmlip.comp_id			AND
					ts.stor_id			= tmlip.stor_id
			LEFT JOIN tbMercadoLibre_ItemsPublicadosCategories	AS tmlipc	WITH(NOLOCK)
				ON	tmlipc.comp_id		= tmlip.comp_id			AND
					tmlipc.mlipc_id		= tmlip.mlipc_id
			WHERE tmlip.comp_id = @comp_id						AND
				  tmlip.mls_id = @mls_id						AND
				(
					@mlp_listing_type_id		= '-1' OR
					tmlip.mlp_listing_type_id	= @mlp_listing_type_id
				)												AND
				(
					@prli_id		= -1				OR
					tmlip.prli_id	= @prli_id
				)												AND
				(
					@stor_id		= -1				OR
					tmlip.stor_id	= @stor_id
				)												AND
				ISNULL(tmlip.mlp_publicationID,'') <> ''		AND
				(
					@mlipc_id		= -1				OR
					tmlip.mlipc_id	= @mlipc_id
				)



	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_Massive_Clone_Process]
(
	 @comp_id				INT,
	 @lang_id				INT,
	 @bra_id				INT,
	 @prof_id				INT,
	 @user_id				INT,

	 @Guid4Selection		UNIQUEIDENTIFIER,
	 @mlp_listing_type_id   NVARCHAR(100),
	 @prli_id				INT,
	 @stor_id				INT,
	 @mls_id_to				INT,
	 @freeShipping			INT,
	 @mlPublicatioNChannel	INT,
	 @mlipc_id				INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@user_id				INT,
				@prof_id				INT,
				@Guid4Selection			UNIQUEIDENTIFIER,
				@mlp_listing_type_id	NVARCHAR(100),
				@prli_id				INT,
				@stor_id				INT,
				@mls_id_to				INT


			SELECT
				@comp_id				= 1,
				@lang_id				= 2,
				@bra_id					= 1,
				@user_id				= 1,
				@prof_id				= 1,
				@Guid4Selection			= '7bdec082-d56c-482e-8588-1ff258f7a06e',
				@mlp_listing_type_id	= 'gold_special',
				@prli_id				= 4,
				@stor_id				= 1,
				@mls_id_to				= 5
		 */
		-- ------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- En una tabla guardamos las publicaciones seleccionadas.
		DECLARE @tblItemsPublicadosSelected TABLE (mlp_id INT PRIMARY KEY, intPrli_ID INT, intStor_ID INT, strPublicationTitle NVARCHAR(100) )
		INSERT INTO @tblItemsPublicadosSelected
		SELECT
			tttmu.integerValue1,
			tttmu.integerValue2,
			tttmu.integerValue3,
			CONVERT(NVARCHAR(100),tttmu.stringValue1)
			FROM tbTemporaryTable4MultipleUse tttmu WITH (NOLOCK)
			WHERE tttmu.guidID = @Guid4Selection


		--Cursor para ir clonando las publicaciones

		DECLARE
			@mlp_id INT,
			@lintPrli_ID INT,
			@lintStor_ID INT,
			@lstrPublicationTitle NVARCHAR(100)

		DECLARE cursor_MassiveClone CURSOR FOR

		SELECT
			tmlipv.mlp_id,
			tmlipv.intPrli_ID,
			tmlipv.intStor_ID,
			tmlipv.strPublicationTitle
			FROM @tblItemsPublicadosSelected tmlipv


		OPEN cursor_MassiveClone
		FETCH cursor_MassiveClone
		INTO
			@mlp_id,
			@lintPrli_ID,
			@lintStor_ID,
			@lstrPublicationTitle

		WHILE   @@FETCH_STATUS = 0
		BEGIN

			--SI PUSO CUALQUIER VERDURA EN EL ID DE LISTA DE PRECIOS EN EL EXCEL, QUE TOME EL DE LA PUBLICACION ORIGINAL
			IF NOT @lintPrli_ID IS NULL
			BEGIN
				IF EXISTS (SELECT 1 FROM tbPriceList tpl WHERE tpl.comp_id = @comp_id AND tpl.prli_id = @lintPrli_ID)
					BEGIN
					SET @prli_id = @lintPrli_ID
					END
			END

			--SI PUSO CUALQUIER VERDURA EN EL ID DE DEPOSITO EN EL EXCEL, QUE TOME EL DE LA PUBLICACION ORIGINAL
			IF NOT @lintStor_ID IS NULL
				BEGIN
					IF EXISTS (SELECT 1 FROM tbStorage ts WHERE ts.comp_id = @comp_id AND ts.stor_id = @lintStor_ID)
						BEGIN
							SET @stor_id = @lintStor_ID
						END
				END

			--SI NO TIENE NADA EN EL TITULO DEL EXCEL LO PASO VACIO PARA QUE TOME EL DE LA PUBLICACION ORIGINAL
			IF ISNULL(@lstrPublicationTitle,'') = ''
				BEGIN
					SET @lstrPublicationTitle = ''
				END

			EXEC spMercadoLibre_ItemsPublicados_CloneAllPublicationData		@comp_id,
																			@bra_id,
																			@user_id,
																			@prof_id,
																			@mlp_id,
																			@mlp_listing_type_id,
																			@prli_id,
																			@stor_id,
																			@Guid4Selection,
																			@lstrPublicationTitle,
																			@mls_id_to,
																			@freeShipping,
																			@mlPublicatioNChannel,
																			@mlipc_id

			FETCH  cursor_MassiveClone
			INTO
				@mlp_id,
				@lintPrli_ID,
				@lintStor_ID,
				@lstrPublicationTitle
		END
		CLOSE cursor_MassiveClone
		DEALLOCATE cursor_MassiveClone


	END
GO

