CREATE PROCEDURE spMercadoLibre_ItemsPublicados_PriceUpdate_GetData
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'
		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 2190
		*/
		-- -----------------------------------------
		SELECT
			tmlippu.mlp_modifiedPrice_Old,
			tmlippu.mlp_modifiedPrice_New,
			tu.user_lastname + ',' + tu.user_firstname		[UserName],
			tmlippu.mlph_cd
			FROM tbMercadoLibre_ItemsPublicados_PriceUpdate AS tmlippu	WITH(NOLOCK)
				INNER JOIN tbUser							AS tu		WITH(NOLOCK)
					ON tu.[user_id] = tmlippu.[user_id]
			WHERE	tmlippu.comp_id = @comp_id				AND
					tmlippu.mlp_id	= @mlp_id
			ORDER BY tmlippu.mlph_cd DESC

	END
GO

