CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_Update_LinkPending]
(
	@comp_id				INT,
	@PublicationID			NVARCHAR(30),
	@Title					NVARCHAR(250),
	@MLuser_id				BIGINT,
	@ItemSKU				VARCHAR(100)
)
AS
	BEGIN
		SET NOCOUNT ON



		UPDATE tbMercadoLibre_ItemsPublicados_LinkPending
			SET		mlpp_title			= @Title,
					mlpp_SKU			= @ItemSKU,
					mlpp_reviewTimes	= ISNULL(mlpp_reviewTimes,1) + 1
			WHERE	comp_id				= @comp_id AND
					mlpp_publicationID	= @PublicationID


		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO tbMercadoLibre_ItemsPublicados_LinkPending
				(
					comp_id,
					-- mlpp_id -- this column value is auto-generated
					mlpp_publicationID,
					mlpp_title,
					mlpp_cd,
					MLUser_Id,
					mlpp_reviewTimes,
					mlpp_SKU
				)
				VALUES
				(
					@comp_id,
					@PublicationID,
					@Title,
					GETDATE(),
					@MLuser_id,
					1,
					@ItemSKU
				)
			END

	END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_Update_LinkPending_getDataByFilters]
(

	@comp_id							INT,
	@MLuser_id							BIGINT,

	@MLID								NVARCHAR(30),
	@mltitle							NVARCHAR(500)

)
AS

BEGIN
	SET NOCOUNT ON

	SELECT
			--lp.comp_id,
			' '									[ ],
			' '									[ ],
			lp.mlpp_publicationID,
			lp.mlpp_title,
			--lp.mlpp_cd,
			tmls.mls_desc,
			ISNULL(lp.mlpp_reviewTimes,1)		[qtyInformed],
			ISNULL(lp.mlpp_SKU,'')				[mlpp_SKU],
			lp.mlpp_id							[mlpp_id]



		FROM tbMercadoLibre_ItemsPublicados_LinkPending		lp		WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_Stores					tmls	WITH (NOLOCK)
			ON	tmls.comp_id	= lp.comp_id		AND
				tmls.MLUser_Id	= lp.MLUser_Id

		WHERE	lp.comp_id		= @comp_id		AND
				lp.MLUser_Id	= @MLuser_id	AND
				(
					@mltitle		= ''							OR
					lp.mlpp_title LIKE '%'+ @mltitle +'%'
				)																AND
				(
					@MLID			= ''							OR
					lp.mlpp_publicationID LIKE '%' + @MLID + '%'
				)

		ORDER BY	qtyInformed DESC

END
GO

