		WHERE	lp.comp_id		= @comp_id AND
				lp.mlpp_id		= @mlpp

END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_UpdateAdditionalData]
(
	@comp_id				INT,
	@mlp_id					INT,
	@mlp_official_store_id	INT,
	@userid_lastUpdate		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@mlp_id					INT,
				@mlp_official_store_id	NVARCHAR(20)
		*/
		-- ---------------------------------------------------
		IF @mlp_official_store_id = -1
			BEGIN
				SET @mlp_official_store_id = NULL
			END

		UPDATE tbMercadoLibre_ItemsPublicados
		SET
			mlp_official_store_id	= @mlp_official_store_id,
			userid_lastUpdate		= @userid_lastUpdate,
			dateof_lastUpdate		= GETDATE()
