			mlp_catalog_forewarning			= @mlp_catalog_forewarning,
			mlp_catalog_forewarning_date	= @mlp_catalog_forewarning_date
		WHERE	comp_id						= @comp_id AND
				mls_id						= @mls_id AND
				mlp_publicationID			= @mlPublication

	END



GO

