	@mlp_free_method									BIGINT,
	@mlipc_id											INT,
	@mlp_itemHTML										NTEXT,
	@mlp_lastJSonValidation								NTEXT,
	@overWriteDescriptions								BIT,
	@mlp_allowPublicationsWithNoStock					BIT,
	@item_id											INT,
	@mlp_price4FreeShipping								DECIMAL(19,2),
	@prli_id											INT,
	@mlp_price4AdditionalCost							DECIMAL(19,2),
	@mlp_ahora12										BIT,
	@mlp_forceSO4Commercial								BIT,
	@mlp_priceDirectDiscountPercentage					DECIMAL(19,2),
	@mlp_labelPrintModuleNoPrintSecondLabel				BIT,
	@mlp_warranty_type									NVARCHAR(25),
	@mlp_warranty_time									NVARCHAR(25),
	@mlp_warranty_time_value							INT,
	@stor_id4StockAvailability							INT,
	@mlp_catalog_product_id								NVARCHAR(20),
	@mlp_blockCatalogPriceUpdateFromNormalPublication	BIT,
	@storg_id											INT,
	@prli_id4MercadoShop								INT,
	@mlp_fixPublicationDeliveryCharge					BIT,
	@mlp_channelID										INT,
	@mlp_blockPriceUpdate								BIT,
	@mlp_ahora6											BIT,
	@mlp_ahora24										BIT,
	@mlp_ahora3											BIT,
	@mlp_ahora18										BIT,
	@mlp_ahora30										BIT,
	@mlp_prli_id4MercadoShopPlusDeliveryCharge			BIT,
	@mlp_free_shippingMShops							BIT,
	@mlp_free_shippingMShops_Coeficient					DECIMAL(5,2),
	@mlp_isAvailable4Price2Win							BIT,
	@mlp_ahora3mshops									BIT,
	@mlp_ahora6mshops									BIT,
	@mlp_ahora12mshops									BIT,
	@mlp_ahora24mshops									BIT,
	@mlp_ahora12_paidByBuyer							BIT,
	@mlp_manufacturing_time								INT,
	@mlp_blockPriceUpdate4mercadoShops					BIT,
	@mlp_is4FullAndFlex									BIT,
	@mlp_ahora3plan										BIT,
	@mlp_ahora3planmshops								BIT,
	@mlp_pcjcofunded									BIT,
	@mlp_pcjcofundedmshops								BIT,
	@mlp_cuotasimple3									BIT,
	@mlp_cuotasimple6									BIT,
	@mlp_cuotasimple_paidbybuyer						BIT,
	@mlp_cuotasimple3mshops								BIT,
	@mlp_cuotasimple6mshops								BIT,
	@mlp_9xCampaign										BIT,
	@mlp_9xCampaignmshops								BIT,
	@mlp_family_name									VARCHAR(500),
	@mlp_cuotasimple12									BIT,
	@mlp_12xCampaign									BIT,
	@mlp_cuotasimple12mshops							BIT,
	@mlp_12xCampaignmshops								BIT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'

		/*
		ACA TENEMOS QUE PREGUNTAR POR LAS MODIFICACIONES DE ESTADO YA QUE SI UNA VEZ FUE 1 NO PUEDE VOLVER JAMAS A SERLO!!!!
		VER LA FORMA OPTIMA DE QUE NO NOS CAGUEN, SI RECUPERAR DE ANTEMANO EL ESTADO Y AL ACTUALIZAR DAR EL OK O AGREGAR UN
		CAMPO BOOLEAN PARA QUE SEA TRUE CUANDO FUE 1 Y FUE MODIFICADO!!!!!!!
		*/

		--SACAR ESTO DESPUES
		--*99999999
		-- -------------------------------------------
		-- RECUPERO EL PRLI_ID Y EL STOR_ID DE LA
		-- STORE SELECCIONADA DE ML
		-- -------------------------------------------
		DECLARE
			--@lprli_id	INT,
			@lstor_id	INT
		SELECT
			@lstor_id = tmls.stor_id--,
			--@lprli_id = tmls.prli_id
		FROM tbMercadoLibre_Stores			tmls
		WHERE	tmls.comp_id	= @comp_id	AND
				tmls.mls_id		= @mls_id
		-- -------------------------------------------

		IF @st_id = -1
			BEGIN
				SET @st_id = NULL
			END

		IF @disc_id = -1
			BEGIN
				SET @disc_id = NULL
			END

		IF @dl_id = -1
			BEGIN
				SET @dl_id = NULL
			END

		IF @mlp_free_method = -1
			BEGIN
				SET @mlp_free_method = NULL
			END

		IF @mlipc_id = -1
			BEGIN
				SET @mlipc_id = NULL
			END

		IF @mlp_warranty_type = ''
			BEGIN
				SET @mlp_warranty_type = NULL
			END

		IF @mlp_warranty_time = ''
			BEGIN
				SET @mlp_warranty_time = NULL
			END

		IF @mlp_warranty_time_value = 0
			BEGIN
				SET @mlp_warranty_time_value = NULL
			END

		IF @stor_id4StockAvailability = -1
			BEGIN
				SET @stor_id4StockAvailability = NULL
			END

		IF @storg_id = -1
			BEGIN
				SET @storg_id = NULL
			END

		IF @mlp_channelID	= -1
			BEGIN
				SET @mlp_channelID = NULL
			END

		IF @prli_id4MercadoShop = -1
			BEGIN
				SET @prli_id4MercadoShop = NULL
			END

		--DECLARE
		--	@item_id	INT
		--SELECT
		--	@item_id = tmlip.item_id
		--FROM tbMercadoLibre_ItemsPublicados tmlip
		--WHERE	comp_id			= @comp_id	AND
		--		bra_id			= @bra_id	AND
		--		mlp_id			= @mlp_id


		UPDATE tbMercadoLibre_ItemsPublicados
		SET
			stor_id												= @lstor_id,
			prli_id												= @prli_id, --@lprli_id,
			mlp_initQty											= @mlp_initQty,
			mlp_price											= @mlp_price,
			curr_id												= @curr_id,
			optval_statusId										= @optval_statusId,
			mlp_inicDate										= @mlp_inicDate,
			mlp_endDate											= @mlp_endDate,
			mlp_lastUpdate										= GETDATE(),
			mlp_Active											= @mlp_Active,
			mlp_itemDesc										= @mlp_itemDesc,
			mls_id												= @mls_id,
			mlp_itemTitle										= @mlp_itemTitle,
			mlp_minQty4Pause									= @mlp_minQty4Pause,
			mlp_listing_type_id									= @listing_type_id,
			mlp_listing_fee_amount								= @listing_fee_amount,
			mlp_sale_fee_amount									= @sale_fee_amount,
			mlp_buying_mode										= @buying_mode,
			mlp_itemSubTitle									= @itemSubTitle,
			mlp_start_time										= @start_time,
			mlp_stop_time										= @stop_time,
			mlp_sold_quantity									= @sold_quantity,
			mlp_permalink										= @permalink,
			mlp_thumbnail										= @thumbnail,
			mlp_video_id										= @video_id,
			mlp_accepts_mercadopago								= @accepts_mercadopago,
			mlp_warranty										= @warranty,
			mlp_local_pick_up									= @local_pick_up,
			mlp_free_shipping									= @free_shipping,
			mlp_publicationCategoryID							= @mlp_publicationCategoryID,
			mlp_isFixedPrice									= @mlp_isFixedPrice,
			st_id												= @st_id,
			disc_id												= @disc_id,
			dl_id												= @dl_id,
			mlp_free_method										= @mlp_free_method,
			mlipc_id											= @mlipc_id,
			mlp_itemHTML										= @mlp_itemHTML,
			mlp_lastJSonValidation								.WRITE( @mlp_lastJSonValidation,0,NULL) ,
			mlp_allowPublicationsWithNoStock					= @mlp_allowPublicationsWithNoStock,
			item_id												= @item_id,
			mlp_price4FreeShipping								= @mlp_price4FreeShipping,
			mlp_4Revision										= 'False',
			mlp_revisionMessage									= '',
			mlp_price4AdditionalCost							= @mlp_price4AdditionalCost,
			mlp_ahora12											= @mlp_ahora12,
			mlp_forceSO4Commercial								= @mlp_forceSO4Commercial,
			mlp_labelPrintModuleNoPrintSecondLabel				= @mlp_labelPrintModuleNoPrintSecondLabel,
			mlp_priceDirectDiscountPercenage					= @mlp_priceDirectDiscountPercentage,
			mlp_warranty_type									= @mlp_warranty_type,
			mlp_warranty_time									= @mlp_warranty_time,
			mlp_warranty_time_value								= @mlp_warranty_time_value,
			stor_id4StockAvailability							= @stor_id4StockAvailability,
			mlp_catalog_product_id								= CASE WHEN @mlp_catalog_product_id = '' THEN mlp_catalog_product_id ELSE @mlp_catalog_product_id END,
			mlp_blockCatalogPriceUpdateFromNormalPublication	= @mlp_blockCatalogPriceUpdateFromNormalPublication,
			storg_id											= @storg_id,
			prli_id4MercadoShop									= @prli_id4MercadoShop,
			mlp_fixPublicationDeliveryCharge					= @mlp_fixPublicationDeliveryCharge,
			mlp_channelID										= @mlp_channelID,
			mlp_blockPriceUpdate								= @mlp_blockPriceUpdate,
			mlp_ahora6											= @mlp_ahora6,
			mlp_ahora24											= @mlp_ahora24,
			mlp_ahora3											= @mlp_ahora3,
			mlp_ahora18											= @mlp_ahora18,
			mlp_ahora30											= @mlp_ahora30,
			mlp_prli_id4MercadoShopPlusDeliveryCharge			= @mlp_prli_id4MercadoShopPlusDeliveryCharge,
			mlp_free_shippingMShops								= @mlp_free_shippingMShops,
			mlp_free_shippingMShops_Coeficient					= @mlp_free_shippingMShops_Coeficient,
			mlp_isAvailable4Price2Win							= @mlp_isAvailable4Price2Win,
			mlp_ahora3mshops									= @mlp_ahora3mshops,
			mlp_ahora6mshops									= @mlp_ahora6mshops,
			mlp_ahora12mshops									= @mlp_ahora12mshops,
			mlp_ahora24mshops									= @mlp_ahora24mshops,
			mlp_ahora12_paidByBuyer								= @mlp_ahora12_paidByBuyer,
			mlp_manufacturing_time								= @mlp_manufacturing_time,
			mlp_blockPriceUpdate4mercadoShops					= @mlp_blockPriceUpdate4mercadoShops,
			mlp_is4FullAndFlex									= @mlp_is4FullAndFlex,
			mlp_ahora3plan										= @mlp_ahora3plan,
			mlp_ahora3planmshops								= @mlp_ahora3planmshops,
			mlp_pcjcofunded										= @mlp_pcjcofunded,
			mlp_pcjcofundedmshops								= @mlp_pcjcofundedmshops,
			mlp_cuotasimple3									= @mlp_cuotasimple3,
			mlp_cuotasimple6									= @mlp_cuotasimple6,
			mlp_cuotasimple_paidbybuyer							= @mlp_cuotasimple_paidbybuyer,
			mlp_cuotasimple3mshops								= @mlp_cuotasimple3mshops,
			mlp_cuotasimple6mshops								= @mlp_cuotasimple6mshops,
			mlp_9xCampaign										= @mlp_9xCampaign,
			mlp_9xCampaignmshops								= @mlp_9xCampaignmshops,
			mlp_family_name										= @mlp_family_name,
			mlp_cuotasimple12									= @mlp_cuotasimple12,
			mlp_12xCampaign										= @mlp_12xCampaign,
			mlp_cuotasimple12mshops								= @mlp_cuotasimple12mshops,
			mlp_12xCampaignmshops								= @mlp_12xCampaignmshops


			WHERE	comp_id			= @comp_id	AND
					--bra_id			= @bra_id	AND ESTO LO SACÓ STL PORQUE SI CREABA PUBLIS DESDE LA SUCURSAL A Y LAS QUERÏA MODIFICAR DESDE LA B, NO LO HACIA
					mlp_id			= @mlp_id	--AND
					--[user_id]		= @user_id




			--COMO PASO FINAL PONEMOS COMO DISPONIBLE PARA ML EL ARTÍCULO
			IF @overWriteDescriptions = 'True'
				BEGIN
					UPDATE tbItem
					SET
						item_ML_isAvailable			= 'True',

						item_ML_desc				= @mlp_itemDesc,
						item_ML_html4Publication	.WRITE( @mlp_itemHTML,0,NULL) ,
						item_ML_url4video			= @video_id,
						item_ML_title				= @mlp_itemTitle
					WHERE	comp_id = @comp_id	AND
							item_id = @item_id
				END
			ELSE
				BEGIN
					UPDATE tbItem
					SET
						item_ML_isAvailable			= 'True',

						item_ML_desc				=	CASE
															WHEN item_ML_title		= '' 	THEN convert(nvarchar(4000),@mlp_itemDesc)
															ELSE item_ML_desc
						            				 	END,
						item_ML_html4Publication	=	CASE --ACA FALTA JSON
															WHEN item_ML_title		= ''	THEN convert(nvarchar(4000),@mlp_itemHTML)
															ELSE item_ML_html4Publication
						                        	 	END,
						item_ML_url4video			= CASE WHEN item_ML_url4video	= ''	THEN @video_id		ELSE item_ML_url4video			END,
						item_ML_title				= CASE WHEN item_ML_title		= ''	THEN @mlp_itemTitle ELSE item_ML_title				END
					WHERE	comp_id = @comp_id	AND
							item_id = @item_id
				END

	END
GO

