CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_UpdateIsInCampaign]
(
	@comp_id			INT,
	@mlp_id				INT,
	@mlp_isInCampaign	BIT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------
		-- TESTING
		-- ---------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@mlp_id				INT,
				@mlp_isInCampaign	BIT
		*/
		-- ---------------------------------


		-- Obtiene el estado ACTUAL de Campaña
		DECLARE @bitmlp_isInCampaign AS BIT = 'False'
		SELECT  @bitmlp_isInCampaign = ISNULL(mlp_isInCampaign,'False')
			FROM tbMercadoLibre_ItemsPublicados	WITH (NOLOCK)
			WHERE	comp_id			 = @comp_id AND
					mlp_id			 = @mlp_id


		-- Solo si hubo algún cambio, lo actualizo.
		IF @bitmlp_isInCampaign <> @mlp_isInCampaign
			BEGIN
				UPDATE tbMercadoLibre_ItemsPublicados
					SET	mlp_isInCampaign	 = @mlp_isInCampaign,
						mlp_forcePriceUpdate =	CASE
													-- Si ESTABA en Campaña y ahora DEJA de estar, fuerza actualizacion de precios en la proxima ronda.
													WHEN @bitmlp_isInCampaign = 'True' AND @mlp_isInCampaign = 'False' 	THEN 1
													-- Si Ahora se pone en campaña, y habia algun forzado a actualizar, lo saco.
													WHEN @mlp_isInCampaign = 'True'										THEN 0
													ELSE																	ISNULL(mlp_forcePriceUpdate,'False')
												END
					WHERE	comp_id			 = @comp_id AND
							mlp_id			 = @mlp_id
			END



	END


GO

