CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_updatePrice2Win]
(
	@comp_id			INT,
	@mlp_publicationID	NVARCHAR(30),
	@decPrice2Win		DECIMAL(19,4)
)
AS
	BEGIN



		SET NOCOUNT ON
		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@mlp_publicationID	NVARCHAR(30),
				@@bolIsPublicOffer	BIT
			SELECT
				@comp_id			= 1,
				@mlp_publicationID	= '',
				@@bolIsPublicOffer	= 'False'
		*/
		-- ------------------------------------------------

		UPDATE tbMercadoLibre_ItemsPublicados
			SET mlp_hasPrice2WinActive		= 'True',
				mlp_Price2WinLastActivation = GETDATE(),
				mlp_Price2WinLastPrice		= @decPrice2Win,
				mlp_price					= @decPrice2Win
			WHERE	comp_id				= @comp_id AND
					mlp_publicationID	= @mlp_publicationID

		DECLARE @intUserID AS INT
		DECLARE @mlp_id    AS INT
		SELECT  @intUserID = tmls.[user_id],
				@mlp_id    = tmlip.mlp_id
			FROM tbMercadoLibre_ItemsPublicados tmlip	WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_Stores AS tmls	WITH (NOLOCK)
				ON	tmls.comp_id			= tmlip.comp_id AND
					tmls.mls_id				= tmlip.mls_id
			WHERE	tmlip.comp_id			= @comp_id		AND
					tmlip.mlp_publicationID	= @mlp_publicationID


		INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
		(
			comp_id,
			mlp_id,
			mlproc_cd,
			[user_id],
			mlproc_option,
			mlproc_decimalValue,
			mlproc_isProcessed,
			mlproc_isCancelled,
			mlproc_priority,
			mlproc_stringValue,
			mlproc_integerValue,
			mlproc_isWithErrorTryNumber,
			mlproc_bigintegerValue,
			mlproc_textValue,
			mlproc_internalID
		)
		VALUES
		(
			@comp_id,
			@mlp_id,
			GETDATE(),
			@intUserID,
			8,
			@decPrice2Win,	-- Le suima el IVA en subUpdatePrice mas el costo de envio
			'False',
			'False',
			0,
			'',
			0,
			0,
			0,
			'',
			598876
		)





	END
GO

CREATE PROCEDURE spMercadoLibre_ItemsPublicados_UpdatePricingAutomation
(
	@comp_id				INT,
	@mlp_id					INT,
	@Aut_Int_Ext_Enabled	BIT,
	@Aut_Int_Ext_Percentage	DECIMAL(6,3)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@mlp_id					INT,
				@Aut_Int_Ext_Enabled	BIT,
				@Aut_Int_Ext_Percentage	DECIMAL(6,3)
			SELECT
				@comp_id				= 1,
				@mlp_id					= 1,
				@Aut_Int_Ext_Enabled	= 'False',
				@Aut_Int_Ext_Percentage	= 30
		*/
		-- ------------------------------------------------------------
		UPDATE tbMercadoLibre_ItemsPublicados
		SET
			mlp_Aut_Int_Ext_Enabled		= @Aut_Int_Ext_Enabled,
			mlp_Aut_Int_Ext_Percentage	= @Aut_Int_Ext_Percentage
			WHERE	comp_id				= @comp_id AND
					mlp_id				= @mlp_id

	END




GO

