CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_UpdatePublicationFromML]
(
	@comp_id										INT,
	@mlp_publicationID								NVARCHAR(30),
	@mls_enableUpdatePublicationsFromMercadoLibre	BIT,
	@mlp_price										DECIMAL(19,4),
	@optval_statusId								INT,
	@mlp_listing_type_id							NVARCHAR(100),
	@mlp_buying_mode								NVARCHAR(20),
	@mlp_sold_quantity								INT,
	@mlp_permalink									NVARCHAR(1000),
	@mlp_thumbnail									NVARCHAR(1000),
	@mlp_accepts_mercadopago						BIT,
	@mlp_local_pick_up								BIT,
	@mlp_free_shipping								BIT,
	@mlp_publicationCategoryID						NVARCHAR(30),
	@title											NVARCHAR(500),
	@mlp_itemDesc									NTEXT,
	@mlp_itemHTML									NTEXT,
	@mlp_totalPrice									DECIMAL(19,4),
	@mlp_health										DECIMAL(5,2),
	@dec_listing_fee_amount							DECIMAL(19,2),
	@dec_sale_fee_amount							DECIMAL(19,2),
	@isFulFillment									BIT,
	@mlp_warranty_type								NVARCHAR(25),
	@mlp_warranty_time								NVARCHAR(25),
	@mlp_warranty_time_value						INT,
	@mlp_poorImage									BIT,
	@mlp_catalog_boost								BIT,
	@mlp_catalog_Listing							BIT,
	@mlp_free_shippingMShops						BIT	,
	@mlp_lastPriceInformedByML						DECIMAL(19,4),
	@mlp_family_name								VARCHAR(500),
	@mlp_userProductID								VARCHAR(30),
	@intOfficialStoreID								INT

)
AS
BEGIN

	SET NOCOUNT ON

	-- -------------------------------------------------------------------------------
	-- TESTING
	-- -------------------------------------------------------------------------------
	/*
		DECLARE
			@comp_id										INT,
			@mlp_publicationID								NVARCHAR(30),
			@mls_enableUpdatePublicationsFromMercadoLibre	BIT,
			@mlp_price										DECIMAL(19,4),
			@optval_statusId								INT,
			@mlp_listing_type_id							NVARCHAR(100),
			@mlp_buying_mode								NVARCHAR(20),
			@mlp_sold_quantity								INT,
			@mlp_permalink									NVARCHAR(1000),
			@mlp_thumbnail									NVARCHAR(1000),
			@mlp_accepts_mercadopago						BIT,
			@mlp_local_pick_up								BIT,
			@mlp_free_shipping								BIT,
			@mlp_publicationCategoryID						NVARCHAR(30)
	*/
	-- -------------------------------------------------------------------------------

	IF @mlp_warranty_type = ''
		BEGIN
			SET @mlp_warranty_type = NULL
		END

	IF @mlp_warranty_time = ''
		BEGIN
			SET @mlp_warranty_time = NULL
		END

	IF @mlp_warranty_time_value = 0
		BEGIN
			SET @mlp_warranty_time_value = NULL
		END



	DECLARE @strOfficialStoreID AS VARCHAR(10) = ''
	IF @intOfficialStoreID > 0 SET @strOfficialStoreID = dbo.fnStrAllTrim( CONVERT(VARCHAR(10),@intOfficialStoreID))


	DECLARE @mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice AS BIT = 'False'
	DECLARE @strSendFrom	AS VARCHAR(250) = ''
	DECLARE @strSendTo		AS VARCHAR(250) = ''
	DECLARE @strStoreName	AS VARCHAR(200) = ''



	DECLARE @mlp_isFixedPrice						AS BIT = 'False'
	DECLARE @mls_updatePublicationPriceFromML		AS BIT = 'False'
	DECLARE @mls_updatePublicationPriceListFromML	AS BIT = 'False'
	DECLARE @mlp_id									AS INT = -1
	DECLARE @curr_id								AS INT
	DECLARE @prli_id4secondUpdate					AS INT
	DECLARE @item_id								AS INT
	DECLARE @prli_id								AS INT
	DECLARE @mlp_price4AdditionalCost				AS DECIMAL(19,2)
	DECLARE @mlp_priceDirectDiscountPercentage		AS DECIMAL(19,2)
	DECLARE @user_idOfMeLi							AS INT = null
	SELECT	@mls_enableUpdatePublicationsFromMercadoLibre	= ISNULL(tmls.mls_enableUpdatePublicationsFromMercadoLibre,'False'),
			@mls_updatePublicationPriceFromML				= tmls.mls_updatePublicationPriceFromML,
		    @mls_updatePublicationPriceListFromML			= tmls.mls_updatePublicationPriceListFromML,
		    @mlp_id											= tmlip.mlp_id,
		    @curr_id										= tmls.curr_id,
		    @prli_id4secondUpdate							= CASE
		      														WHEN	tmls.prli_id4secondUpdate IS NOT NULL AND
		      																tmlip.prli_id <> tmls.prli_id4secondUpdate		THEN tmls.prli_id4secondUpdate
		      														ELSE NULL
		      													END,
			@item_id										= tmlip.item_id,
			@prli_id										= tmlip.prli_id,
			@mlp_price4AdditionalCost						= tmlip.mlp_price4AdditionalCost,
			@mlp_priceDirectDiscountPercentage				= ISNULL(tmlip.mlp_priceDirectDiscountPercenage,0)	,
			@user_idOfMeLi									= tmls.[user_id]	,
			@mlp_isFixedPrice								= ISNULL(tmlip.mlp_isFixedPrice,'False')  ,
			@strStoreName									= ISNULL(tmls.mls_desc,'') ,
			@mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice = ISNULL(tmls.mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice,'False') ,
			@strSendTo												= dbo.fnStrAllTrim (ISNULL(tmls.mls_strSendTo4ForcedUpdate,'')),
			@strSendFrom											= dbo.fnStrAllTrim (ISNULL(tmls.mls_strSendFrom4ForcedUpdate,''))
		FROM tbMercadoLibre_ItemsPublicados tmlip					WITH (NOLOCK)
		--INNER JOIN tbMercadoLibre_ItemsPublicadosCategories tmlpc	WITH (NOLOCK)
		--	ON	tmlpc.comp_id	= tmlip.comp_id			AND
		--		tmlpc.mlipc_id	= tmlip.mlipc_id
		INNER JOIN tbMercadoLibre_Stores	tmls					WITH (NOLOCK)
			ON	tmls.comp_id	= tmlip.comp_id			AND
				tmls.mls_id		= tmlip.mls_id
		WHERE	tmlip.comp_id				= @comp_id	AND
				tmlip.mlp_publicationID		= @mlp_publicationID


	-- Buscar una Publicacion con el MISMO articulo, que este ACTIVA y NO sea de catalogo
	DECLARE @bitDisablePriceListUpdate AS BIT = 'False'
	IF @mlp_catalog_Listing = 'True'
		BEGIN
			IF EXISTS(
						SELECT TOP 1  1
							FROM tbMercadoLibre_ItemsPublicados AS tmlip	WITH (NOLOCK)
							WHERE	tmlip.comp_id = @comp_id	AND
									tmlip.item_id = @item_id	AND
									tmlip.mlp_publicationID <> @mlp_publicationID AND
									tmlip.optval_statusId  = 2
					 )
				BEGIN
					SET @bitDisablePriceListUpdate = 'True'
				END
		END



	-- Si DEBE actualizarse la lista y la lista es Diferente...  SOLO si la moneda es la MISMA
	IF	@mls_updatePublicationPriceFromML		= 'True'	AND
		@mls_updatePublicationPriceListFromML	= 'True'	AND
		@mlp_priceDirectDiscountPercentage      = 0			AND
		@mlp_isFixedPrice						= 'False'	AND			-- MOS 03-2021
		@bitDisablePriceListUpdate			    = 'False'
		BEGIN

			DECLARE @datLastPriceUpdate AS DATETIME = NULL
			SELECT  @datLastPriceUpdate = tpli.plh_cd
				FROM tbPriceListHistory tpli							WITH (NOLOCK)
				WHERE	tpli.comp_id = @comp_id					AND
						tpli.prli_id = @prli_id					AND
						tpli.item_id = @item_id					AND
						tpli.curr_id = @curr_id

			-- Para que no se entre en LOOPS de bajada de precios si hay dos publicaciones con el MISMO
			-- articulo pero con DIFERENTE gasto de envio, da para cagadas de redondeo y baja o suba indiscriminada
			-- de precios de LISTA, por lo que SOLO se permitirá la actualizacion de una lista para el MISMO articulo cada
			-- un MINUTO , desde MeLi.
			IF ABS(DATEDIFF(SECOND,@datLastPriceUpdate,GETDATE())) > 180
				BEGIN
					UPDATE tbpricelistitems
						SET		prli_price			= @mlp_price	,
								curr_id				= @curr_id,
								user_id_lastUpdate	= @user_idOfMeLi
						FROM tbPriceListItems tpli							WITH (NOLOCK)
						WHERE	tpli.comp_id = @comp_id					AND
								tpli.prli_id = @prli_id					AND
								tpli.item_id = @item_id					AND
								tpli.curr_id = @curr_id
				END

		END


	-- Lista ADICIONAL a actualizar SIN descontar el cargo de envio
	IF	@prli_id4secondUpdate IS NOT NULL		AND
		@mlp_isFixedPrice			= 'False'	AND 			-- MOS 03-2021
		@bitDisablePriceListUpdate	= 'False'
		BEGIN

			DECLARE @datLastPriceUpdate2 AS DATETIME = NULL
			SELECT  @datLastPriceUpdate2 = tpli.plh_cd
				FROM tbPriceListHistory tpli							WITH (NOLOCK)
				WHERE	tpli.comp_id = @comp_id					AND
						tpli.prli_id = @prli_id4secondUpdate	AND
						tpli.item_id = @item_id

			-- Para que no se entre en LOOPS de bajada de precios si hay dos publicaciones con el MISMO
			-- articulo pero con DIFERENTE gasto de envio, da para cagadas de redondeo y baja o suba indiscriminada
			-- de precios de LISTA, por lo que SOLO se permitirá la actualizacion de una lista para el MISMO articulo cada
			-- un MINUTO , desde MeLi.
			IF ABS(DATEDIFF(SECOND,@datLastPriceUpdate2,GETDATE())) > 180
				BEGIN
					UPDATE tbpricelistitems
						SET		prli_price			= @mlp_totalPrice	,
								curr_id				= @curr_id,
								user_id_lastUpdate	= @user_idOfMeLi
						FROM tbPriceListItems tpli							WITH (NOLOCK)
						WHERE	tpli.comp_id = @comp_id					AND
								tpli.prli_id = @prli_id4secondUpdate	AND
								tpli.item_id = @item_id
				END
		END


	DECLARE @bitHasForce2UpdatePrice AS BIT = 'False'
	DECLARE @decPriceInERP AS DECIMAL(19,2) = 0


	IF @mls_enableUpdatePublicationsFromMercadoLibre = 'True'
		BEGIN

			UPDATE tbMercadoLibre_ItemsPublicados		WITH (ROWLOCK)
			SET
				-- --------------------------------------------------------------
				-- MOS 03-2024: Si la tienda dice que si es mas bajo vuelva a pasar el precio a Meli, lo hace
				-- Variable para mas abajo poder mandar un mail informando q se actualizo el precio.
				--@decPriceInERP				= ISNULL(mlp_price,0),
				--@bitHasForce2UpdatePrice	=	CASE
				--									WHEN	mlp_forcePriceUpdate = 'True'		THEN	'False'		-- si ya tiene, q no joda
				--									WHEN	@mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice = 'True'	AND
				--											@mls_updatePublicationPriceFromML						= 'False'	AND
				--											@mlp_price < (mlp_price * 0.98)		THEN	'True'
				--									ELSE												'False'
				--								END,
				--mlp_forcePriceUpdate		=	CASE
				--									WHEN	@mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice = 'True'	AND
				--											@mls_updatePublicationPriceFromML						= 'False'	AND
				--											@mlp_price < (mlp_price * 0.98)		THEN	'True'
				--									ELSE												mlp_forcePriceUpdate
				--								END ,
				-- --------------------------------------------------------------
				mlp_price					=	CASE
													WHEN @mls_updatePublicationPriceFromML  = 'True'
															AND
														 @mlp_priceDirectDiscountPercentage = 0 AND
														 @mlp_isFixedPrice					= 'False'	THEN	@mlp_price	-- MOS 03-2021
													ELSE														mlp_price
												END	  ,

				curr_id						=	CASE
													WHEN @mls_updatePublicationPriceFromML  = 'True' AND
														 @mlp_isFixedPrice					= 'False'	THEN	@curr_id
													ELSE														curr_id
												END	  ,
				optval_statusId				=	CASE
													WHEN optval_statusId  = 10 THEN 10		-- Desenlazada  MOS 09-2020
													WHEN optval_statusId  = 6  THEN 6		-- Pausado Forzado
													WHEN @optval_statusId = -1 THEN optval_statusId
													ELSE @optval_statusId
												END,
				mlp_listing_type_id			= @mlp_listing_type_id,
				mlp_buying_mode				= @mlp_buying_mode,
				mlp_sold_quantity			= @mlp_sold_quantity,
				mlp_permalink				= @mlp_permalink,
				mlp_thumbnail				= @mlp_thumbnail,
				mlp_accepts_mercadopago		= @mlp_accepts_mercadopago,
				mlp_local_pick_up			= @mlp_local_pick_up,
				mlp_free_shipping			= @mlp_free_shipping,
				mlp_price4FreeShipping		=	CASE
													WHEN @mlp_free_shipping = 'True' THEN	mlp_price4FreeShipping
													ELSE									0
												END,
				mlp_publicationCategoryID	= @mlp_publicationCategoryID,
				mlp_itemTitle				= @title ,
				mlp_itemDesc				=	CASE
													WHEN DATALENGTH (@mlp_itemDesc) = 0		THEN	mlp_itemDesc
													ELSE											@mlp_itemDesc
												END,
				dateof_lastUpdateFromMeLi	= GETDATE(),
				health						= @mlp_health,
				mlp_listing_fee_amount		= @dec_listing_fee_amount,
				mlp_sale_fee_amount			= @dec_sale_fee_amount,
				mlp_is4FulFillment			= @isFulFillment,
				mlp_warranty_type			= @mlp_warranty_type,
				mlp_warranty_time			= @mlp_warranty_time,
				mlp_warranty_time_value		= @mlp_warranty_time_value,
				mlp_poorImage				= @mlp_poorImage,
				mlp_catalog_boost			= @mlp_catalog_boost,
				mlp_catalog_listing			= @mlp_catalog_Listing,
				mlp_free_shippingMShops		= @mlp_free_shippingMShops ,
				mlp_lastPriceInformedByML	= @mlp_lastPriceInformedByML,
				-- MOS 08-2024: actualización de Familia y userproduct
				mlp_userProductID			= @mlp_userProductID,
				mlp_family_name				=	CASE
													WHEN dbo.fnStrAllTrim (@mlp_family_name) <> '' THEN @mlp_family_name
													ELSE mlp_family_name
												END,
				mlp_official_store_id		= @strOfficialStoreID

				WHERE	comp_id				= @comp_id				AND
						mlp_publicationID	= @mlp_publicationID

		END

	ELSE
		-- No Actualiza ni Titulo ni Descripción.
		BEGIN
			UPDATE tbMercadoLibre_ItemsPublicados		WITH (ROWLOCK)
			SET
				-- --------------------------------------------------------------
				-- MOS 03-2024: Si la tienda dice que si es mas bajo vuelva a pasar el precio a Meli, lo hace
				-- Variable para mas abajo poder mandar un mail informando q se actualizo el precio.
				--@decPriceInERP				= ISNULL(mlp_price,0),
				--@bitHasForce2UpdatePrice	=	CASE
				--									WHEN	mlp_forcePriceUpdate = 'True'		THEN	'False'		-- si ya tiene, q no joda
				--									WHEN	@mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice = 'True'	AND
				--											@mls_updatePublicationPriceFromML						= 'False'	AND
				--											@mlp_price < (mlp_price * 0.98)		THEN	'True'
				--									ELSE												'False'
				--								END,
				--mlp_forcePriceUpdate		=	CASE
				--									WHEN	@mls_updatePublicationPriceIfMLPriceIsMinorThanERPPrice = 'True'	AND
				--											@mls_updatePublicationPriceFromML						= 'False'	AND
				--											@mlp_price < (mlp_price * 0.98)		THEN	'True'
				--									ELSE												mlp_forcePriceUpdate
				--								END ,
				-- --------------------------------------------------------------
				mlp_price					=	CASE
													--WHEN @mls_updatePublicationPriceFromML = 'True' THEN	@mlp_price
													WHEN @mls_updatePublicationPriceFromML  = 'True'
															AND
														 @mlp_priceDirectDiscountPercentage = 0	AND
														 @mlp_isFixedPrice					= 'False'	THEN	@mlp_price
													ELSE														mlp_price
												END	  ,
				optval_statusId				=	CASE
													WHEN optval_statusId  = 10 THEN 10		-- Desenlazada  MOS 09-2020  se agrego aca 03-2023
													WHEN optval_statusId  = 6  THEN 6
													WHEN @optval_statusId = -1 THEN optval_statusId
													ELSE @optval_statusId
												END,
				mlp_listing_type_id			= @mlp_listing_type_id,
				mlp_buying_mode				= @mlp_buying_mode,
				mlp_sold_quantity			= @mlp_sold_quantity,
				mlp_permalink				= @mlp_permalink,
				mlp_thumbnail				= @mlp_thumbnail,
				mlp_accepts_mercadopago		= @mlp_accepts_mercadopago,
				mlp_local_pick_up			= @mlp_local_pick_up,
				mlp_free_shipping			= @mlp_free_shipping,
				mlp_price4FreeShipping		=	CASE
													WHEN @mlp_free_shipping = 'True' THEN	mlp_price4FreeShipping
													ELSE									0
												END,
				mlp_publicationCategoryID	= @mlp_publicationCategoryID,
				mlp_itemTitle				= @title ,
				dateof_lastUpdateFromMeLi	= GETDATE(),
				health						= @mlp_health,
				mlp_is4FulFillment			= @isFulFillment,
				mlp_warranty_type			= @mlp_warranty_type,
				mlp_warranty_time			= @mlp_warranty_time,
				mlp_warranty_time_value		= @mlp_warranty_time_value,
				mlp_poorImage				= @mlp_poorImage,
				mlp_catalog_boost			= @mlp_catalog_boost,
				mlp_catalog_listing			= @mlp_catalog_Listing,
				mlp_free_shippingMShops		= @mlp_free_shippingMShops,
				mlp_lastPriceInformedByML	= @mlp_lastPriceInformedByML,
				-- MOS 08-2024: actualización de Familia y userproduct
				mlp_userProductID			= @mlp_userProductID,
				mlp_family_name				=	CASE
													WHEN dbo.fnStrAllTrim (@mlp_family_name) <> '' THEN @mlp_family_name
													ELSE mlp_family_name
												END,
				mlp_official_store_id		= @strOfficialStoreID


				--mlp_itemDesc				= @mlp_itemDesc
				WHERE	comp_id				= @comp_id				AND
						mlp_publicationID	= @mlp_publicationID
		END


	-- Se paso a la updatequeue
	IF 1 = 2 AND  @bitHasForce2UpdatePrice = 'True'
		BEGIN
			-- Mandar el mail con el aviso si es q tiene cargadas las dos direcciones de email
			INSERT INTO tbsendEMailQueue
			(
				comp_id,
				-- smtpJob_id -- this column value is auto-generated
				[user_id],
				replyTo,
				sendTo,
				sendToCC,
				sendToCCO,
				[subject],
				body,
				displayName,
				sq_cd,
				smtpJob_priority
			)
			VALUES
			(
				@comp_id,
				@user_idOfMeLi,
				@strSendFrom,
				@strSendTo,
				'',
				'',
				'Mercadolibre: Forzado de Actualización de Precios',
				'Se ha solicitado el forzado de actualización de precios para la publicación:' + @mlp_publicationID + CHAR(10) +
				'El precio informado desde MercadoLibre SIN impuestos es: ' + CONVERT(VARCHAR(100),@mlp_price)  + CHAR(10) +
				'El precio actual SIN impuestos en el sistema es de: ' + CONVERT(VARCHAR(100),@decPriceInERP) + CHAR(10) + CHAR(10) + CHAR(10),
				@strStoreName,
				GETDATE(),
				-5000
			)
		END






END


GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_UpdatePublicationFromML_price4FreeShipping]
(
	@comp_id										INT,
	@mlp_publicationID								NVARCHAR(30),
	@mlp_price4FreeShipping							DECIMAL(19,4)
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id										INT,
				@mlp_publicationID								NVARCHAR(30),
				@mlp_price										DECIMAL(19,4),
		*/
		-- -------------------------------------------------------------------------------


		UPDATE tbMercadoLibre_ItemsPublicados		WITH (ROWLOCK)
			SET mlp_price4FreeShipping	= @mlp_price4FreeShipping,
			    mlp_free_shipping		=	CASE		-- Si en MILE PONEN x q SI una publi con envio gratis, debe actualizarse este campo, sino como en GIGANTE se act el rojo con el importe pero no el checkbox de envio gratis
												WHEN @mlp_price4FreeShipping > 0 THEN	'True'
												ELSE									mlp_free_shipping
											END
				WHERE	comp_id								= @comp_id AND
						mlp_publicationID					= @mlp_publicationID AND
						mlp_fixPublicationDeliveryCharge	= 'False'		-- MOS 08-2021


	END


GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_UpdatePublicationID]
(
	@comp_id			INT,
	@mlp_id				INT,
	@mlp_publicationID	NVARCHAR(30),
	@permalink			NVARCHAR(300),
	@thumbnail			NVARCHAR(300)
)
AS
BEGIN
	SET NOCOUNT ON

	UPDATE tbMercadoLibre_ItemsPublicados				WITH (ROWLOCK)
		SET mlp_publicationID		= @mlp_publicationID,
			mlp_permalink			= @permalink,
			mlp_thumbnail			= @thumbnail,
			mlp_lastPublicatedPrice = mlp_price
		WHERE	comp_id				= @comp_id			AND
				mlp_id				= @mlp_id




	-- Actualiza los precios de la tabla
	UPDATE tbMercadoLibre_ItemsPublicados				WITH (ROWLOCK)
		SET	mlp_lastPublicatedPrice		= tpli.prli_price,
			mlp_lastPublicatedCurrID	= tpli.curr_id
		FROM tbMercadoLibre_ItemsPublicados mlp
		INNER JOIN tbPriceListItems			tpli		WITH (NOLOCK)
			ON	tpli.comp_id = mlp.comp_id AND
				tpli.prli_id = mlp.prli_id AND
				tpli.item_id = mlp.item_id
		WHERE	mlp.comp_id = @comp_id AND
				mlp.mlp_id	= @mlp_id


	SELECT IDENT_CURRENT( 'tbMercadoLibre_ItemsPublicados' )  [ID]


END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_UpdatePublicationStatusByExcel]
(
	@comp_id										INT,
	@user_id										INT,
	@mlPublicationID								NVARCHAR(50),
	@intStatus										INT,
	@strType										NVARCHAR(100),
	@intPriceUpdate									INT,
	@intFreeShipping								INT,
	@intprli_id										INT,
	@decDiscountPercentage							DECIMAL(19,2),
	@intMaxQty2Publicate							INT,
	@intAllow2PublishWithNoStock					INT,
	@decAdditionalPrice								DECIMAL(19,2),
	@intstor_id										INT,
	@strMLPublicationID2Replace						NVARCHAR(50),
	@intRetiraEnLocal								INT,
	@intCantMinParaPausar							INT,
	@intStorgId										INT,
	@shippingCost									DECIMAL(19,2),
	@intstor_id4StockAvailability					INT,
	@intprli_id4MercadoShop							INT,
	@intmlp_prli_id4MercadoShopPlusDeliveryCharge	INT,

	@intmlipc_id									INT,
	@intmlp_free_shippingMShops						INT,
	@intmlp_mustUpdate_prli_id4MercadoShop			INT,
	@decmlp_free_shippingMShops_Coeficient			DECIMAL(5,2),
	@intmlp_fixPublicationDeliveryCharge			INT,
	@intmlp_blockPriceUpdate						INT,
	@intmlp_blockPriceUpdate4mercadoShops			INT,
	@intst_id										INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------
		-- TESTING
		-- --------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@user_id			INT,
				@mlPublicationID	NVARCHAR(50),
				@intStatus			INT
		*/

		IF @strType = '-1'
			BEGIN
				SET @strType = NULL
			END

		IF @intStorgId = -2
			BEGIN
				SET @intStorgId = NULL
			END

		IF @intstor_id4StockAvailability = -2
			BEGIN
				SET @intstor_id4StockAvailability = NULL
			END

		IF @intprli_id4MercadoShop = -2
			BEGIN
				SET @intprli_id4MercadoShop = NULL
			END

		-- --------------------------------------------------
		IF EXISTS (SELECT 1
					FROM tbMercadoLibre_ItemsPublicados				tmlip	WITH(NOLOCK)
					WHERE	tmlip.comp_id			= @comp_id		AND
							tmlip.mlp_publicationID = @mlPublicationID)
			BEGIN
				UPDATE tbMercadoLibre_ItemsPublicados
				SET
					optval_statusId						= CASE WHEN @intStatus						= -1		THEN	optval_statusId						ELSE @intStatus						END,
					mlp_isFixedPrice					= CASE WHEN @intPriceUpdate					= -1		THEN	mlp_isFixedPrice					ELSE @intPriceUpdate				END,
					mlp_free_shipping					= CASE WHEN @intFreeShipping				= -1		THEN	mlp_free_shipping					ELSE @intFreeShipping				END,

					--PRECIO DE ENVÏO
					--SI PONE EL FREE SHIPPING EN FALSE, DEBO PONER EN 0 EL VALOR DEL PRECIO DE ENVÍO
					--mlp_price4FreeShipping				= CASE WHEN @intFreeShipping				= 0			THEN 	0									ELSE mlp_price4FreeShipping			END,

					mlp_price4FreeShipping				=	CASE WHEN	@intFreeShipping				= 0			THEN 	0
															ELSE		CASE WHEN @shippingCost					= -1		THEN	mlp_price4FreeShipping				ELSE @shippingCost		END
					                      				 	END,

					prli_id										= CASE WHEN @intprli_id						= -1		THEN    prli_id								ELSE @intprli_id					END,
					mlp_priceDirectDiscountPercenage			= CASE WHEN @decDiscountPercentage			= -1		THEN    mlp_priceDirectDiscountPercenage	ELSE @decDiscountPercentage			END,
					mlp_initQty									= CASE WHEN @intMaxQty2Publicate			<  1		THEN	mlp_initQty							ELSE @intMaxQty2Publicate			END,
					mlp_allowPublicationsWithNoStock			= CASE WHEN @intAllow2PublishWithNoStock	= -1		THEN  	mlp_allowPublicationsWithNoStock	ELSE @intAllow2PublishWithNoStock	END,
					mlp_price4AdditionalCost					= CASE WHEN @decAdditionalPrice				= -1		THEN	mlp_price4AdditionalCost			ELSE @decAdditionalPrice			END,
					stor_id										= CASE WHEN @intstor_id						= -1		THEN	stor_id								ELSE @intstor_id					END,
					mlp_publicationID							= CASE WHEN @strMLPublicationID2Replace		= ''		THEN	mlp_publicationID					ELSE @strMLPublicationID2Replace	END,
					mlp_local_pick_up							= CASE WHEN @intRetiraEnLocal				= -1		THEN	mlp_local_pick_up					ELSE @intRetiraEnLocal				END,
					mlp_minQty4Pause							= CASE WHEN @intCantMinParaPausar			= -1		THEN    mlp_minQty4Pause					ELSE @intCantMinParaPausar			END,
					storg_id									= CASE WHEN @intStorgId						= -1		THEN    storg_id							ELSE @intStorgId					END,
					stor_id4StockAvailability					= CASE WHEN @intstor_id4StockAvailability	= -1		THEN	stor_id4StockAvailability			ELSE @intstor_id4StockAvailability	END,
					prli_id4MercadoShop							= CASE WHEN @intprli_id4MercadoShop			= -1		THEN	prli_id4MercadoShop					ELSE @intprli_id4MercadoShop		END,
					mlp_prli_id4MercadoShopPlusDeliveryCharge	= CASE WHEN @intmlp_prli_id4MercadoShopPlusDeliveryCharge	= -1 THEN mlp_prli_id4MercadoShopPlusDeliveryCharge ELSE @intmlp_prli_id4MercadoShopPlusDeliveryCharge	END,
					mlipc_id									= CASE WHEN @intmlipc_id					= -1		THEN	mlipc_id							ELSE @intmlipc_id					END,
					mlp_free_shippingMShops						= CASE WHEN @intmlp_free_shippingMShops		= -1		THEN	mlp_free_shippingMShops				ELSE @intmlp_free_shippingMShops	END,
					mlp_mustUpdate_prli_id4MercadoShop			= CASE WHEN @intmlp_mustUpdate_prli_id4MercadoShop			= -1 THEN mlp_mustUpdate_prli_id4MercadoShop		ELSE @intmlp_mustUpdate_prli_id4MercadoShop			END,
					mlp_free_shippingMShops_Coeficient			= CASE WHEN @decmlp_free_shippingMShops_Coeficient			= -1 THEN mlp_free_shippingMShops_Coeficient		ELSE @decmlp_free_shippingMShops_Coeficient			END,
					mlp_fixPublicationDeliveryCharge			= CASE WHEN @intmlp_fixPublicationDeliveryCharge			= -1 THEN mlp_fixPublicationDeliveryCharge			ELSE @intmlp_fixPublicationDeliveryCharge			END,
					mlp_blockPriceUpdate						= CASE WHEN @intmlp_blockPriceUpdate		= -1		THEN	mlp_blockPriceUpdate				ELSE @intmlp_blockPriceUpdate		END,
					mlp_blockPriceUpdate4mercadoShops			= CASE WHEN @intmlp_blockPriceUpdate4mercadoShops			= -1 THEN	mlp_blockPriceUpdate4mercadoShops		ELSE @intmlp_blockPriceUpdate4mercadoShops			END,
					st_id										= CASE WHEN @intst_id						= -1		THEN	st_id								ELSE @intst_id						END







				WHERE	comp_id				= @comp_id AND
						mlp_publicationID	= @mlPublicationID

				IF @strType IS NOT NULL
					BEGIN
						UPDATE tbMercadoLibre_ItemsPublicados
						SET
							mlp_listing_type_id		= @strType
						WHERE	comp_id				= @comp_id AND
								mlp_publicationID	= @mlPublicationID

						-- -------------------------------------------------------------------------------------------
						-- SI ACTUALIZO EL TIPO DE PUBLICACIÓN TENGO QUE GENERAR UN REGISTRO PARA ACTUALIZAR EL TIPO
						-- RECUPERO EL MLP_ID DE LA PUBLICACION
						-- ESTO ES UNA PRUEBA, BORRAR AL TERMINAR
						-- -------------------------------------------------------------------------------------------
							DECLARE @lintMLP_ID	INT
							SELECT
								@lintMLP_ID = tmlip.mlp_id
							FROM tbMercadoLibre_ItemsPublicados AS tmlip
							WHERE	tmlip.comp_id			= @comp_id AND
									tmlip.mlp_publicationID = @mlPublicationID

							INSERT INTO tbMercadoLibre_updateQueue
							(
								comp_id,
								mlp_id,
								mlproc_cd,
								[user_id],
								mlproc_option,
								mlproc_stringValue,
								mlproc_integerValue,
								mlproc_decimalValue
							)
							VALUES
							(
								@comp_id,
								@lintMLP_ID,
								GETDATE(),
								@user_id,
								9,
								@strType,
								0,
								0
							)
						-- -------------------------------------------------------------------------------------------


					END

				SELECT 'True' [Exists]
			END
		ELSE
			BEGIN
				SELECT 'False' [Exists]
			END
	END

GO

