	@mlp_statistics_AvgSales4Week		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------------
		/*
			DECLARE
				@mlp_id								INT
				@mlp_statistics_MinPrice4Category	DECIMAL(19,2),
				@mlp_statistics_MaxPrice4Category	DECIMAL(19,2),
				@mlp_statistics_AvgPrice4Category	DECIMAL(19,2),
