			mlp_statistics_MaxPrice4EAN			= @mlp_statistics_MaxPrice4EAN,
			mlp_statistics_MinPrice4EAN			= @mlp_statistics_MinPrice4EAN,
			mlp_statistics_AvgPrice4EAN			= @mlp_statistics_AvgPrice4EAN,
			mlp_statistics_AvgSales4Week		= @mlp_statistics_AvgSales4Week,
			mlp_statistics_lastUpdate			= GETDATE(),
			mlp_statistics_hasData				= 1
			WHERE	mlp_id						= @mlp_id
	END



GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicados_UpdatestatusID]
(
	@comp_id			INT,
	@mlp_id				INT,
	@optval_statusId	INT
)
AS
BEGIN
	SET NOCOUNT ON

	UPDATE tbMercadoLibre_ItemsPublicados				WITH (ROWLOCK)
		SET		optval_statusId = CASE
									  WHEN optval_statusId = 6			THEN 6			-- NO se puede cambiar el estado de Pausado Forzado				MOS 09-2020
									  WHEN optval_statusId = 10			THEN 10			-- NO se puede cambiar el estado de Publicacion Desenlazada		MOS 09-2020
									  ELSE 									 @optval_statusId
								  END,
				mlp_Active		= CASE

				          		      WHEN	@optval_statusId IN (2,4)	THEN 'True'
				          		      ELSE									 'False'
				          		  END
		WHERE	comp_id			= @comp_id			AND
				mlp_id			= @mlp_id



	IF @optval_statusId = 5 -- Si la Publicacion esta CERRADA Borra todos los trabajos pendientes
		BEGIN
			UPDATE tbMercadoLibre_updateQueue			WITH (ROWLOCK)
				SET mlproc_isCancelled = 1
				WHERE	comp_id				= @comp_id	AND
						mlp_id				= @mlp_id	AND
						mlproc_isProcessed	= 'False'	AND
						mlproc_isCancelled	= 'False'
		END


	SELECT @mlp_id  [ID]




END
GO

