CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosAttributes_GetDataByMLPID]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT DISTINCT
			tmlipa.comp_id,
			tmlipa.mlat_id,
			tmlipa.mlp_id,
			tmlipa.MLid,
			ISNULL(tmlipa.MLname,'')						[MLname],
			ISNULL(tmlipa.MLtooltip,'')						[MLtooltip],
			ISNULL(tmlipa.MLvalue_type,'')					[MLvalue_type],
			tmlipa.MLvalue_max_length,
			ISNULL(tmlipa.MLfixed,'False')					[MLfixed],
			ISNULL(tmlipa.mlat_valueString,'')				[mlat_valueString],
			ISNULL(tmlipa.MLnumberUnitSelectedValue,'')		[MLnumberUnitSelectedValue],
			ISNULL(tmlipa.mlat_text4Combos,'')				[mlat_text4Combos],
			ISNULL(tmlipa.mlat_isAlternativeValue,'False')	[mlat_isAlternativeValue]
			FROM tbMercadoLibre_ItemsPublicadosAttributes	tmlipa
			WHERE	tmlipa.comp_id	= @comp_id				AND
					tmlipa.mlp_id	= @mlp_id

	END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosAttributes_GetDataByMLPID_4Publicate]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS



	-- -------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------
	/*
	DECLARE 	@comp_id	INT,
				@mlp_id		INT
	SET @comp_id = 1
	SET @mlp_id = 1540
	*/
	-- -------------------------------------------------------------------




	BEGIN

		SET NOCOUNT ON

		DECLARE @bitHasVariations AS BIT = 'False'
		IF EXISTS(
					SELECT TOP 1  1
						FROM tbMercadoLibre_ItemsPublicadosVariations	tmv		WITH (NOLOCK)
						WHERE	tmv.comp_id			= @comp_id	AND
								tmv.mlp_id			= @mlp_id	AND
								tmv.mlpv_disabled	= 'False'
				 )
			BEGIN
				SET @bitHasVariations = 'True'
			END



		SELECT	DISTINCT
			tmlipa.comp_id,
			tmlipa.mlat_id,
			tmlipa.mlp_id,
			tmlipa.MLid,
			ISNULL(tmlipa.MLname,'')						[MLname],
			ISNULL(tmlipa.MLtooltip,'')						[MLtooltip],
			ISNULL(tmlipa.MLvalue_type,'')					[MLvalue_type],
			tmlipa.MLvalue_max_length,
			ISNULL(tmlipa.MLfixed,'False')					[MLfixed],
			CASE
				WHEN tml.comp_id IS NULL THEN		CASE
														WHEN tmlipa.MLvalue_type='number_unit' THEN  REPLACE(ISNULL(tmlipa.mlat_valueString,''),',','.')
														ELSE										 ISNULL(tmlipa.mlat_valueString,'')
													END

				--ELSE								'-1'
				ELSE								'null'
			END												[mlat_valueString],
			CASE
				WHEN tml.comp_id IS NULL THEN	ISNULL(tmlipa.MLnumberUnitSelectedValue,'')
				ELSE								'null'
			END												[MLnumberUnitSelectedValue],
			CASE
				WHEN tml.comp_id IS NULL THEN	ISNULL(tmlipa.mlat_text4Combos,'')
				ELSE								'null'
			END												[mlat_text4Combos],
			ISNULL(tmlipa.mlat_isAlternativeValue,'False')	[mlat_isAlternativeValue],
			CASE
				WHEN tmlipv.comp_id IS NULL THEN 0
				ELSE							 1
			END												[publicationHasVariations]
			INTO #tmpAtributes
			FROM tbMercadoLibre_ItemsPublicadosAttributes		tmlipa		WITH (NOLOCK)
			LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations  tmlipv		WITH (NOLOCK)						-- Esto es porque a los FORROSSSSSS de ML se les ocurrio de un REPUTO DIA para el otro que los atributos no se sobreescriben sino que hay que matarlos con un PUTO NULL
				ON	tmlipv.comp_id	= tmlipa.comp_id	AND
					tmlipv.mlp_id	= tmlipa.mlp_id		AND
					tmlipv.mlpv_disabled = 'False'
			LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations	tml		WITH (NOLOCK)
				ON	tml.comp_id = tmlipv.comp_id	AND
					tml.mlpv_id = tmlipv.mlpv_id	AND
					(
						dbo.fnStrAllTrim(tml.MLattributeID) = dbo.fnStrAllTrim(tmlipa.MLid)
						OR
						dbo.fnStrAllTrim(tml.attribute_combinations_name)     = dbo.fnStrAllTrim(tmlipa.MLname)
						OR
						(dbo.fnStrAllTrim(tml.MLattributeID) = 'COLOR' AND  dbo.fnStrAllTrim(tmlipa.MLid) = 'MAIN_COLOR')			-- MOS 12-2018
					)


			WHERE	tmlipa.comp_id	= @comp_id				AND
					tmlipa.mlp_id	= @mlp_id				--AND
					--NOT EXISTS (
					--				SELECT 1
					--					FROM tbMercadoLibre_ItemsPublicadosVariations						tmv		WITH (NOLOCK)
					--					INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations	tml		WITH (NOLOCK)
					--						ON	tml.comp_id = tmv.comp_id	AND
					--							tml.mlpv_id = tmv.mlpv_id
					--					WHERE 	tmv.comp_id = @comp_id		AND
					--							tmv.mlp_id	= @mlp_id		AND
					--							tmv.mlpv_disabled = 'False' AND
					--							(
					--								dbo.fnStrAllTrim(tml.MLattributeID) = dbo.fnStrAllTrim(tmlipa.MLid)
					--								OR
					--								dbo.fnStrAllTrim(tml.attribute_combinations_name)     = dbo.fnStrAllTrim(tmlipa.MLname)
					--							)
					--			)



		-- -------------------------------------------------------------------------------------
		-- ATENCIÓN
		-- Pone NUEVO ya que en la publicacion pone NUEVO y si le ponen USADO NO PUBLICA.
		-- En principio no se pueden vender items usados.
		-- Si se vende algo usado o alguien lo requiere hay que modificar tambien el publicador
		-- para que no ponga nuevo o se permira poner si es nuevo o usado y aca tome lo que se puso
		-- a nivel de PUBLICACION ! ! !
		-- -------------------------------------------------------------------------------------
		UPDATE #tmpAtributes SET mlat_text4Combos = 'Nuevo' WHERE MLid = 'ITEM_CONDITION'
		-- -------------------------------------------------------------------------------------


		-- -------------------------------------------------------------------------------------
		-- MOS SL 07-2021, para que NO mande el COLOR si NO lo tiene
		-- -------------------------------------------------------------------------------------
		DELETE FROM #tmpAtributes WHERE MLid	=    'COLOR'		AND mlat_valuestring = 'null'
		-- -------------------------------------------------------------------------------------


		-- -------------------------------------------------------------------------------------
		-- Atributos que deben ser borrados para que no molesten al publicar.
		-- -------------------------------------------------------------------------------------
		DELETE FROM #tmpAtributes WHERE MLid				= 'ITEM_CONDITION'
		--DELETE FROM #tmpAtributes WHERE MLid				= 'SELLER_SKU' MOS 02-2020
		--DELETE FROM #tmpAtributes WHERE mlat_text4Combos	= 'Ninguno'
		-- -------------------------------------------------------------------------------------


		-- -------------------------------------------------------------------------------------
		-- GTIN, No se si esta bien borrar esto. Si alguien lo reclama ver de ponerlo nuevamente: Código universal de producto
		-- -------------------------------------------------------------------------------------
		-- DELETE FROM #tmpAtributes WHERE MLid				= 'GTIN-14'	MOS 27-2-2019: Se saco el borrado y se puso como Update.

		UPDATE #tmpAtributes
			SET		mlat_valueString	= 'NULL'
			WHERE MLid = 'GTIN-14'

		UPDATE #tmpAtributes
			SET		mlat_valueString	= 'NULL'
			WHERE MLid = 'GTIN14'

		UPDATE #tmpAtributes
			SET		mlat_valueString	= 'NULL'		-- MOS: 25-06-2019
			WHERE MLid = 'GTIN'							AND  dbo.fnStrAllTrim(ISNULL( mlat_valueString,''))	<> '-1'


		-- Si NO tiene  nada cargado que lo ponga como No Aplica para que no moleste.
		UPDATE #tmpAtributes
			SET		mlat_valueString	= '-1',
					mlat_text4Combos    = NULL		-- MOS: 25-06-2019
			WHERE	MLid = 'GTIN'										AND
					dbo.fnStrAllTrim(ISNULL(mlat_valueString,'')) = ''	AND
					dbo.fnStrAllTrim(ISNULL(mlat_text4Combos,'')) = ''

		-- Si NO tiene  nada cargado que lo ponga como No Aplica para que no moleste.
		UPDATE #tmpAtributes
			SET		mlat_valueString	= 'NULL'		-- MOS: 25-06-2019
			WHERE MLid = 'EAN'							AND  dbo.fnStrAllTrim(ISNULL( mlat_valueString,''))	<> '-1'

		UPDATE #tmpAtributes
			SET		mlat_valueString	= '-1',
					mlat_text4Combos    = NULL		-- MOS: 25-06-2019
			WHERE	MLid = 'EAN'										AND
					dbo.fnStrAllTrim(ISNULL(mlat_valueString,'')) = ''	AND
					dbo.fnStrAllTrim(ISNULL(mlat_text4Combos,'')) = ''

		-- Si tiene VARIACIONES no debe tener este puto atributo si es que no lo tiene definido.  Debe estar al FINAL de esta seccion.!!!
		DELETE FROM #tmpAtributes
			WHERE	MLid						= 'GTIN'		AND
					mlat_valueString			= '-1'			AND
					publicationHasVariations	= 1


		-- MOS 05-2022: DG, si se manda esta mierda como lo sugiere MeLi saca del canal mandado correctamente x lo que hay que ELIMINARLO!
		DELETE FROM #tmpAtributes
			WHERE	MLid						= 'EXCLUSIVE_CHANNEL'



		-- -------------------------------------------------------------------------------------


		DECLARE @strIDorCODE	AS NVARCHAR(50) = ''
		SELECT  @strIDorCODE	=	CASE
										WHEN tmls.mls_SKU_byItemCode = 'True' THEN	ti.item_code
										ELSE										CONVERT (NVARCHAR(10),ti.item_id)
									END
			FROM tbMercadoLibre_ItemsPublicados				tmlipu	WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_Stores				tmls	WITH (NOLOCK)
				ON	tmls.comp_id	= tmlipu.comp_id AND
					tmls.mls_id		= tmlipu.mls_id
			INNER JOIN tbItem								ti		WITH (NOLOCK)
				ON	ti.comp_id		= tmlipu.comp_id AND
					ti.item_id		= tmlipu.item_id
			WHERE	tmlipu.comp_id	= @comp_id AND
					tmlipu.mlp_id	= @mlp_id


		IF NOT EXISTS (SELECT TOP 1 1 FROM #tmpAtributes WHERE MLid = 'SELLER_SKU')
			BEGIN



				IF @bitHasVariations = 'False'
					BEGIN

						DECLARE @item_id	AS INT = -1
						SELECT  @item_id = ti.item_id
							FROM tbMercadoLibre_ItemsPublicados		tmlip	WITH (NOLOCK)
							INNER JOIN tbItem						ti		WITH (NOLOCK)
								ON	ti.comp_id		= tmlip.comp_id AND
									ti.item_id		= tmlip.item_id
							WHERE	tmlip.comp_id	= @comp_id AND
									tmlip.mlp_id	= @mlp_id
						IF @item_id > 0
							BEGIN
								INSERT INTO #tmpAtributes(	comp_id,
															mlat_id,
															mlp_id,
															MLid,
															mlat_valueString,
															mlat_isAlternativeValue,
															MLname,
															MLtooltip,
															MLvalue_type,
															MLfixed,
															MLnumberUnitSelectedValue,
															mlat_text4Combos,
															MLvalue_max_length,
															publicationHasVariations
														 )
									VALUES(					@comp_id,
															-1,
															@mlp_id,
															'SELLER_SKU',
															@strIDorCODE /*CONVERT(NVARCHAR(10),@item_id)*/ ,
															'False',
															'SKU',
															'',
															'',
															'False',
															'',
															'',
															0,0)

							END
					END
				ELSE
					BEGIN

						INSERT INTO #tmpAtributes(	comp_id,
													mlat_id,
													mlp_id,
													MLid,
													mlat_valueString,
													mlat_isAlternativeValue,
													MLname,
													MLtooltip,
													MLvalue_type,
													MLfixed,
													MLnumberUnitSelectedValue,
													mlat_text4Combos,
													MLvalue_max_length,
													publicationHasVariations
													)
							VALUES(					@comp_id,
													-1,
													@mlp_id,
													'SELLER_SKU',
													'null' ,
													'False',
													'SKU',
													'',
													'',
													'False',
													'null',
													'',
													0,0)

					END
			END

		-- Borra el SELLER_SKU si esta como NO APLICA
		DELETE FROM #tmpAtributes WHERE MLid	=    'SELLER_SKU'	AND mlat_valuestring = '-1'

		-- Borra los Atributos que YA esten cargados como Atributo de Variacion de GTIN o SELLER_SKU
		DELETE		 #tmpAtributes
				FROM #tmpAtributes	tmp
				INNER JOIN tbMercadoLibre_ItemsPublicadosAttributes tmlipa				WITH (NOLOCK)
					ON	tmlipa.comp_id	= tmp.comp_id AND
						tmlipa.mlp_id	= tmp.mlp_id
				INNER JOIN tbMercadoLibre_ItemsPublicadosVariations AS tmlipv			WITH (NOLOCK)
					ON	tmlipv.comp_id	= tmp.comp_id AND
						tmlipv.mlp_id	= tmp.mlp_id
				INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Attributes AS tml	WITH (NOLOCK)
					ON	tml.comp_id		= tmlipv.comp_id AND
						tml.mlpv_id		= tmlipv.mlpv_id
				WHERE	tml.MLid		= tmp.MLid AND
						tml.MLid		IN ('SELLER_SKU','GTIN')


		SELECT *
			FROM #tmpAtributes
			ORDER BY MLid

		DROP TABLE #tmpAtributes

	END
GO

