CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosAttributes_IsPublicationOK]
(
	@comp_id				INT,
	@mlp_id					INT,
	@strAttributesMustHave	NVARCHAR(MAX)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@mlp_id					INT,
				@strAttributesMustHave	NVARCHAR(MAX)
		*/
		-- -----------------------------------------------------


		-- -------------------------------------------------------------------
		-- Variables para el Cursor
		-- -------------------------------------------------------------------
		DECLARE
			@AttributeID				NVARCHAR(100),
			@IsPublicationOK			BIT
			--@bitLoop					BIT

		SET @IsPublicationOK = 'True'
		--SET @bitLoop		 = 'True'
		-- ----------------------------------------------------------------------
		--ACA VA EL STRING QUE VA A SEPARAR EN UNA TABLA LOS ID DE LOS ATRIBUTOS
		-- ----------------------------------------------------------------------
		DECLARE Cursor_AttributesMustHave CURSOR LOCAL  FAST_FORWARD FOR
			SELECT	fst.items
				FROM	dbo.fnSplitTable(@strAttributesMustHave,',') fst

		OPEN Cursor_AttributesMustHave
		FETCH NEXT FROM Cursor_AttributesMustHave
			INTO	@AttributeID

		WHILE (@@FETCH_STATUS = 0) --AND (@bitLoop = 'True')
			BEGIN


				SET @AttributeID = dbo.fnStrAllTrim(@AttributeID)


				IF @AttributeID = ''
					BEGIN
						FETCH NEXT FROM Cursor_AttributesMustHave
							INTO	@AttributeID
						CONTINUE;
					END


				IF EXISTS(
								SELECT TOP 1 1
									FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations tmlipvc	WITH (NOLOCK)
									INNER JOIN tbMercadoLibre_ItemsPublicadosVariations		   tmlipv	WITH (NOLOCK)
										ON	tmlipv.comp_id			= tmlipvc.comp_id	AND
											tmlipv.mlpv_id			= tmlipvc.mlpv_id
									WHERE	tmlipv.comp_id			= @comp_id			AND
											tmlipv.mlp_id			= @mlp_id			AND
											tmlipvc.MLattributeID	= @AttributeID
						)
					BEGIN
						FETCH NEXT FROM Cursor_AttributesMustHave
							INTO	@AttributeID
						CONTINUE;
					END


				IF NOT EXISTS(	SELECT TOP 1	1
									FROM tbMercadoLibre_ItemsPublicadosAttributes	tmlipa		WITH (NOLOCK	)
									WHERE	tmlipa.comp_id	= @comp_id					AND
											tmlipa.mlp_id	= @mlp_id					AND
											tmlipa.MLid		= @AttributeID				AND
											ISNULL(tmlipa.mlat_valueString,'') <> '-1'	AND  -- MOS:
											ISNULL(tmlipa.mlat_valueString,'') <> ''
							)
					BEGIN
						SET @IsPublicationOK = 'False'
						BREAK;
						--SET @bitLoop		 = 'False'
					END
				FETCH NEXT FROM Cursor_AttributesMustHave
					INTO	@AttributeID
			END
		CLOSE Cursor_AttributesMustHave
		DEALLOCATE Cursor_AttributesMustHave
		-- ----------------------------------------------------------------------

		SELECT @IsPublicationOK [IsPublicationOK]

	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosAttributes_UpdateData]
(
	@comp_id					INT,
	@mlp_id						INT,
	@MLid						NVARCHAR(100),
	@MLname						NVARCHAR(500),
	@MLtooltip					NVARCHAR(500),
	@MLvalue_type				NVARCHAR(50),
	@MLvalue_max_length			INT,
	@MLfixed					BIT,
	@mlat_valueString			NVARCHAR(4000),
	@MLnumberUnitSelectedValue	NVARCHAR(200),
	@SelectedTextDDL			NVARCHAR(4000),
	@isAlternativeValue			BIT
)
AS
	BEGIN
		SET NOCOUNT ON


		-- IF @MLid = 'SELLER_SKU' RETURN  MOS 02-2020

		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@mlp_id					INT,
				@MLid					NVARCHAR(100),
				@MLname					NVARCHAR(500),
				@MLtooltip				NVARCHAR(500),
				@MLvalue_type			NVARCHAR(50),
				@MLvalue_max_length		INT,
				@MLfixed				BIT,
				@mlat_valueString		NVARCHAR(4000)
		*/
		-- ----------------------------------------------------


		--SI EL ATRIBUTO EXISTE, ACTUALIZA EL VALOR, SINO, LO INSERTA
		IF EXISTS(SELECT TOP 1
					1
					FROM tbMercadoLibre_ItemsPublicadosAttributes	tmlipa
					WHERE	tmlipa.comp_id	= @comp_id				AND
							tmlipa.mlp_id	= @mlp_id				AND
							tmlipa.MLid		= @MLid)
			BEGIN

				IF @mlat_valueString = '-1'
					BEGIN
						SET @SelectedTextDDL = NULL
					END

				UPDATE tbMercadoLibre_ItemsPublicadosAttributes		WITH (ROWLOCK)
				SET
					mlat_valueString			= @mlat_valueString,
					MLnumberUnitSelectedValue	= @MLnumberUnitSelectedValue,
					mlat_text4Combos			= @SelectedTextDDL,
					mlat_isAlternativeValue		= @isAlternativeValue
					WHERE	comp_id				= @comp_id			AND
							mlp_id				= @mlp_id			AND
							MLid				= @MLid
			END
		ELSE
			BEGIN

				IF @mlat_valueString = '-1'
					BEGIN
						SET @SelectedTextDDL = NULL
					END

				EXEC spMercadoLibre_ItemsPublicadosAttributes_InsertData
						@comp_id					= @comp_id,
						@mlp_id						= @mlp_id,
						@MLid						= @MLid,
						@MLname						= @MLname,
						@MLtooltip					= @MLtooltip,
						@MLvalue_type				= @MLvalue_type,
						@MLvalue_max_length			= @MLvalue_max_length,
						@MLfixed					= @MLfixed,
						@mlat_valueString			= @mlat_valueString,
						@MLnumberUnitSelectedValue	= @MLnumberUnitSelectedValue,
						@SelectedTextDDL			= @SelectedTextDDL,
						@isAlternativeValue			= @isAlternativeValue
			END

	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosCategories_ExecSQLData]
(
	@comp_id								INT,
	@mlo_id									INT,
	@mlipc_orderReceiptMessageSQL			NVARCHAR(MAX),
	@mlp_PublicationID						NVARCHAR(30),
	@item_id								INT,
	@intShippingID							BIGINT,
	@mlipc_orderReceiptMessage				NVARCHAR(MAX) OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON

		DECLARE @mlipc_orderReceiptMessageOLD AS VARCHAR(MAX) = ISNULL(@mlipc_orderReceiptMessage,'')

		BEGIN TRY

			-- ------------------------------------------------------------------
			--  ATENCION: NO USARLO porque sino si se logea con un usuario
			--            que no sea sysadmin o serveradmin da error ! !
			--
			-- SHELL (?????? Lo pongo así para que quede todo compartimentado
			-- ------------------------------------------------------------------
			--DECLARE @bitIsXMDShellActive AS BIT = 'False'
			--SELECT  @bitIsXMDShellActive = CONVERT(INT, ISNULL(value, value_in_use))
			--FROM  sys.configurations
			--WHERE  name = 'xp_cmdshell'

			--IF @bitIsXMDShellActive = 'False'
			--	BEGIN
			--		EXEC sp_configure 'xp_cmdshell', 1;
			--		RECONFIGURE;
			--	END
			-- ------------------------------------------------------------------


			SET @mlipc_orderReceiptMessageSQL = REPLACE(@mlipc_orderReceiptMessageSQL,'@comp_id'			,CONVERT(NVARCHAR(8),@comp_id))
			SET @mlipc_orderReceiptMessageSQL = REPLACE(@mlipc_orderReceiptMessageSQL,'@mlo_id'				,CONVERT(NVARCHAR(8),@mlo_id))
			SET @mlipc_orderReceiptMessageSQL = REPLACE(@mlipc_orderReceiptMessageSQL,'@item_id'			,CONVERT(NVARCHAR(8),@item_id))
			SET @mlipc_orderReceiptMessageSQL = REPLACE(@mlipc_orderReceiptMessageSQL,'@intShippingID'		,CONVERT(NVARCHAR(15),@intShippingID))

			IF  @mlipc_orderReceiptMessageSQL LIKE '%update%'  OR
				@mlipc_orderReceiptMessageSQL LIKE '%dbcc%'  OR
				@mlipc_orderReceiptMessageSQL LIKE '%truncate%'  OR
				@mlipc_orderReceiptMessageSQL LIKE '%sp_configure%'  OR
				@mlipc_orderReceiptMessageSQL LIKE '%sp_executesql%'  OR
				@mlipc_orderReceiptMessageSQL LIKE '%drop%'  OR
				@mlipc_orderReceiptMessageSQL LIKE '%table%'  OR
				@mlipc_orderReceiptMessageSQL LIKE '%delete%'
				BEGIN
					SET @mlipc_orderReceiptMessageSQL = ''
				END

			IF  @mlipc_orderReceiptMessageSQL NOT LIKE '%select%'
				BEGIN
					SET @mlipc_orderReceiptMessageSQL = ''
				END

			IF @mlipc_orderReceiptMessageSQL <> ''
				BEGIN


					DECLARE @strMessage		AS VARCHAR(8000) = ''
					DECLARE @strParamOUT	AS VARCHAR(8000) = ''
					DECLARE @param			AS NVARCHAR(100) = N'@strParamOUT varchar(8000) OUTPUT'



					EXEC sp_executesql @mlipc_orderReceiptMessageSQL, @param, @strMessage OUTPUT;
					IF @strMessage <> ''
						BEGIN
							SET @mlipc_orderReceiptMessage = @strMessage
						END

				END

			END TRY
			BEGIN CATCH
				SET @mlipc_orderReceiptMessage = @mlipc_orderReceiptMessageOLD
			END CATCH

			IF ISNULL(@mlipc_orderReceiptMessage,'') = '' SET @mlipc_orderReceiptMessage = @mlipc_orderReceiptMessageOLD



END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosCategories_ExecSQLData4Test]
(
	@comp_id								INT,
	@mlo_id									INT,
	@mlipc_orderReceiptMessageSQL			NVARCHAR(MAX),
	@mlp_PublicationID						NVARCHAR(30),
	@item_id								INT,
	@intShippingID							BIGINT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------------------------------------------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id						INT,
				@mlo_id							INT,
				@mlipc_orderReceiptMessageSQL	NVARCHAR(MAX),
				@mlp_PublicationID				NVARCHAR(30),
