				@mlipc_orderReceiptMessageSQL	= 'SELECT @strParamOUT = tc.cust_name FROM tbCustomer tc WHERE cust_id = 24289',
				@mlp_PublicationID				= '',
				@item_id						= 0,
				@intShippingID					= 0
		*/
		-- --------------------------------------------------------------------------------------------------------------------------------

		DECLARE
			@sqlReturn AS NVARCHAR(MAX)
		SET @sqlReturn = ''
		
		EXEC spMercadoLibre_ItemsPublicadosCategories_ExecSQLData @comp_id, @mlo_id, @mlipc_orderReceiptMessageSQL, @mlp_PublicationID, @item_id, @intShippingID, @sqlReturn OUTPUT
		SELECT @sqlReturn	[sqlReturn]
	END
GO

