			tmlipc.comp_id,
			tmlipc.mlipc_id,
			tmlipc.mlipc_desc,
			ISNULL(tmlipc.mlipc_desc4Header,'')									[mlipc_desc4Header],
			ISNULL(tmlipc.mlipc_desc4Footer,'')									[mlipc_desc4Footer],
			ISNULL(tmlipc.mlipc_isAvailable4Price2Win,'False')					[mlipc_isAvailable4Price2Win],
