CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_Attributes_InsertOrUpdate]
(
	@comp_id		INT,
	@mlpv_id		INT,
	@MLid			NVARCHAR(50),
	@MLvalue_name	NVARCHAR(4000)
)
AS
	BEGIN
		SET NOCOUNT ON

		IF NOT EXISTS (SELECT TOP
						1  1 FROM tbMercadoLibre_ItemsPublicadosVariations_Attributes	tmlipva	WITH(NOLOCK)
						WHERE	tmlipva.comp_id = @comp_id								AND
								tmlipva.mlpv_id = @mlpv_id								AND
								tmlipva.MLid	= @MLid)
			BEGIN
				INSERT INTO tbMercadoLibre_ItemsPublicadosVariations_Attributes
				(
					comp_id,
					mlpv_id,
					MLid,
					MLvalue_name
				)
				VALUES
				(
					@comp_id,
					@mlpv_id,
					@MLid,
					@MLvalue_name
				)
			END
		ELSE
			BEGIN
				UPDATE tbMercadoLibre_ItemsPublicadosVariations_Attributes
				SET
					mlpv_id			= @mlpv_id,
					MLvalue_name	= @MLvalue_name
				WHERE	comp_id		= @comp_id	AND
						mlpv_id		= @mlpv_id	AND
						MLid		= @MLid
			END

	END
GO

CREATE PROCEDURE spMercadoLibre_ItemsPublicadosVariations_CheckExistsVariation
(
	@comp_id		INT,
	@mlpv_id		INT,
	@intVariationID	BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------
		-- TESTING
		-- ---------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@mlpv_id		INT,
				@intVariationID	BIGINT
		*/
		-- ---------------------------------
		IF EXISTS(	SELECT
						1
						FROM tbMercadoLibre_ItemsPublicadosVariations tmlipv	WITH(NOLOCK)
						WHERE	tmlipv.comp_id			= @comp_id				AND
								tmlipv.MLVariationID	= @intVariationID		AND
								(
									@mlpv_id = -1 OR
									tmlipv.mlpv_id			<> @mlpv_id
								))
			BEGIN
				SELECT 'True'	[Exists]
			END
		ELSE
			BEGIN
				SELECT 'False'	[Exists]
			END
	END
GO

