CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_Combinations_GetData]
(
	@comp_id	INT,
	@mlpv_id	INT
)
AS
BEGIN
	SET NOCOUNT ON



	-- MOS 11-2019 para que vaya el item_id como estaba o el Item_code
	DECLARE @strIDorCODE	AS NVARCHAR(50) = ''
	DECLARE @item_id		AS INT
	SELECT  @item_id		= ti.item_id,
			@strIDorCODE	=	CASE
									WHEN tmls.mls_SKU_byItemCode = 'True' THEN	ti.item_code
									ELSE										CONVERT (NVARCHAR(10),ti.item_id)
								END
		FROM tbMercadoLibre_ItemsPublicadosVariations 	tmlip	WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_ItemsPublicados		tmlipu	WITH (NOLOCK)
			ON	tmlipu.comp_id	= tmlip.comp_id AND
				tmlipu.mlp_id	= tmlip.mlp_id
		INNER JOIN tbMercadoLibre_Stores				tmls	WITH (NOLOCK)
			ON	tmls.comp_id	= tmlipu.comp_id AND
				tmls.mls_id		= tmlipu.mls_id
		INNER JOIN tbItem						ti		WITH (NOLOCK)
			ON	ti.comp_id		= tmlip.comp_id AND
				ti.item_id		= tmlip.item_id
		WHERE	tmlip.comp_id	= @comp_id AND
				tmlip.mlpv_id	= @mlpv_id








	SELECT
		tmlipvc.comp_id,
		tmlipvc.mlpvc_id,
		tmlipvc.mlpv_id,
		ISNULL(tmlipvc.attribute_combinations_name,'')				[attribute_combinations_name],

		CASE
			WHEN dbo.fnStrAllTrim(ISNULL(tmlipvc.attribute_combinations_value_id,'')) = 'Discontinued_Attribute' THEN	''
			ELSE																										ISNULL(tmlipvc.attribute_combinations_value_id,'')
		END															[attribute_combinations_value_id],
		ISNULL(tmlipvc.attribute_combinations_value_name,'')		[attribute_combinations_value_name],
		tmlipvc.mlpvc_disabled,
		CASE
			WHEN dbo.fnStrAllTrim(ISNULL(tmlipvc.MLattributeID,'')) = '-111' THEN	''
			ELSE																	ISNULL(tmlipvc.MLattributeID,'')
		END															[MLattributeID],
		ISNULL(tmlipvc.MLnumberUnitSelectedValue,'')				[MLnumberUnitSelectedValue],
		ISNULL(tmlipvc.mlat_text4Combos,'')							[mlat_text4Combos],
		ISNULL(tmlipvc.mlat_isAlternativeValue,'False')				[mlat_isAlternativeValue],
		ISNULL(tmlipvc.MLtooltip,'')								[MLtooltip],
		ISNULL(tmlipvc.MLvalue_type,'')								[MLvalue_type],
		ISNULL(tmlipvc.MLvalue_max_length,0)						[MLvalue_max_length],
		ISNULL(tmlipvc.MLfixed,'False')								[MLfixed],
		CASE
			WHEN tmlipvc.MLvalue_type = 'number_unit' THEN	REPLACE(ISNULL(tmlipvc.mlat_valueString,''),',','.')
			ELSE											ISNULL(tmlipvc.mlat_valueString,'')
		END															[mlat_valueString],
		dbo.fnStrAllTrim(ISNULL(tmlipvc.attribute_combinations_value_id,''))	[attribute_combinations_value_id_Original],
		@strIDorCODE												[strIDorCODE]

		INTO #tmpAtributes
		FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations	tmlipvc	WITH(NOLOCK)
		WHERE	tmlipvc.comp_id = @comp_id							AND
				tmlipvc.mlpv_id = @mlpv_id							--AND
				--tmlipvc.MLattributeID <> 'SELLER_SKU'

	--UNION ALL

	--SELECT	TOP 1
	--	tmlipvc.comp_id,
	--	tmlipvc.mlpvc_id,
	--	tmlipvc.mlpv_id,
	--	'SKU'				[attribute_combinations_name],

	--	CASE
	--		WHEN dbo.fnStrAllTrim(ISNULL(tmlipvc.attribute_combinations_value_id,'')) = 'Discontinued_Attribute' THEN	''
	--		ELSE																										ISNULL(tmlipvc.attribute_combinations_value_id,'')
	--	END															[attribute_combinations_value_id],
	--	''		[attribute_combinations_value_name],
	--	tmlipvc.mlpvc_disabled,
	--	'SELLER_SKU'												[MLattributeID],
	--	ISNULL(tmlipvc.MLnumberUnitSelectedValue,'')				[MLnumberUnitSelectedValue],
	--	@strIDorCODE												[mlat_text4Combos],
	--	ISNULL(tmlipvc.mlat_isAlternativeValue,'False')				[mlat_isAlternativeValue],
	--	ISNULL(tmlipvc.MLtooltip,'')								[MLtooltip],
	--	ISNULL(tmlipvc.MLvalue_type,'')								[MLvalue_type],
	--	ISNULL(tmlipvc.MLvalue_max_length,0)						[MLvalue_max_length],
	--	ISNULL(tmlipvc.MLfixed,'False')								[MLfixed],
	--	CASE
	--		WHEN tmlipvc.MLvalue_type = 'number_unit' THEN	REPLACE(ISNULL(tmlipvc.mlat_valueString,''),',','.')
	--		ELSE											ISNULL(tmlipvc.mlat_valueString,'')
	--	END															[mlat_valueString],
	--	dbo.fnStrAllTrim(ISNULL(tmlipvc.attribute_combinations_value_id,''))	[attribute_combinations_value_id_Original],
	--	@strIDorCODE												[strIDorCODE]
	--	FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations	tmlipvc	WITH(NOLOCK)
	--	WHERE	tmlipvc.comp_id = @comp_id							AND
	--			tmlipvc.mlpv_id = @mlpv_id




	DELETE FROM #tmpAtributes WHERE MLattributeID = 'SELLER_SKU'

	SELECT * FROM #tmpAtributes
		ORDER BY MLattributeID

END
GO

