CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_Combinations_hasVariationError]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 1147
		*/
		-- --------------------------------------------


		DECLARE @bolHasError AS BIT = 'False'

		SELECT
			@bolHasError = 'True'
			FROM tbMercadoLibre_ItemsPublicadosVariations						tmlipv			WITH (NOLOCK)
			LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations		tmlipvc			WITH (NOLOCK)
				ON	tmlipvc.comp_id				= tmlipv.comp_id				AND
					tmlipvc.mlpv_id				= tmlipv.mlpv_id
			WHERE	tmlipv.comp_id			= @comp_id							AND
					tmlipv.mlp_id			= @mlp_id							AND
					tmlipv.mlpv_disabled	= 'False'							AND
					tmlipvc.comp_id IS NULL



		SELECT @bolHasError [hasError]


	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_Combinations_InsertData]
(
	@comp_id							INT,
	@mlpv_id							INT,
