CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_ExistsData4OtherVariation]
(
	@comp_id		INT,
	@mlp_id			INT,
	@mlpv_id		INT,
	@MLVariationID	BIGINT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@mlp_id			INT,
				@mlpv_id		INT,
				@MLVariationID	BIGINT
			SELECT
				@comp_id		= 1,
				@mlp_id			= 1185,
				@mlpv_id		= 78,
				@MLVariationID	= 25463317094
		*/
		-- ---------------------------------------------
		--SI EL ID DE VARIACIÓN QUE LE PONE ES 0 (CERO) QUE NO HAGA NADA, YA QUE PUEDE TENER DESFAZADOS LOS ID DE VARIACIONES
		IF @MLVariationID = 0
			BEGIN
				SELECT 'False' [Exists]
				RETURN
			END

		IF EXISTS(SELECT
						1
						FROM tbMercadoLibre_ItemsPublicadosVariations		tmlipv	WITH(NOLOCK)
						WHERE	tmlipv.comp_id			= @comp_id			AND
								tmlipv.mlp_id			= @mlp_id			AND
								tmlipv.MLVariationID	= @MLVariationID	AND
								tmlipv.mlpv_id			<> @mlpv_id)
			BEGIN
				SELECT 'True'	[Exists]
			END
		ELSE
			BEGIN
				SELECT 'False'	[Exists]
			END

	END
GO


