CREATE PROCEDURE spMercadoLibre_ItemsPublicadosVariations_ExistsVariationAttribute_ForNonAllowVariationAttributes
(
	@comp_id		INT,
	@mlp_id			INT,
	@attributeID	NVARCHAR(50)
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@mlp_id			INT,
				@attributeID	NVARCHAR(50)
			SELECT
				@comp_id		= 1,
				@mlp_id			= 795,
				@attributeID	= 'COLOR'
		*/
		-- ---------------------------------------------------------

		IF EXISTS (	SELECT
						TOP 1 1
						FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations	AS tmlipvc	WITH(NOLOCK)
						INNER JOIN tbMercadoLibre_ItemsPublicadosVariations			AS tmlipv	WITH(NOLOCK)
						ON	tmlipv.comp_id				= tmlipvc.comp_id			AND
							tmlipv.mlpv_id				= tmlipvc.mlpv_id
						INNER JOIN tbMercadoLibre_ItemsPublicados					AS tmlip	WITH(NOLOCK)
						ON	tmlip.comp_id				= tmlipv.comp_id			AND
							tmlip.mlp_id				= tmlipv.mlp_id
						WHERE	tmlip.comp_id			= @comp_id					AND
								tmlip.mlp_id			= @mlp_id					AND
								tmlipvc.MLattributeID	= @attributeID				AND
								tmlipv.mlpv_disabled	= 'False')
			BEGIN
