			END
		ELSE
			BEGIN
				SELECT 'False'  [Exists]
			END

	END



GO

CREATE PROCEDURE spMercadoLibre_ItemsPublicadosVariations_GetActiveVariations
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------
		-- TESTING
		-- -------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT
			SELECT
				@comp_id	= 1,
				@mlp_id		= 666
		*/
		-- -------------------------------------

		SELECT DISTINCT
			tmlipv.mlpv_id,
			tmlipv.MLVariationID
