				ON	tmlipvc.comp_id							= tmlipv.comp_id		AND
					tmlipvc.mlpv_id							= tmlipv.mlpv_id
			WHERE	tmlipv.comp_id							= @comp_id				AND
					tmlipv.mlp_id							= @mlp_id				AND
					ISNULL(tmlipv.MLVariationID,0)			> 0						AND
					ISNULL(tmlipv.mlpv_disabled,'False')	= 'False'
	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_GetData]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON



		DECLARE @strIDorCODE	AS NVARCHAR(50) = ''
		SELECT  @strIDorCODE	=	CASE
										WHEN tmls.mls_SKU_byItemCode = 'True' THEN	ti.item_code
										ELSE										CONVERT (NVARCHAR(10),ti.item_id)
									END
			FROM tbMercadoLibre_ItemsPublicados				tmlipu	WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_Stores				tmls	WITH (NOLOCK)
				ON	tmls.comp_id	= tmlipu.comp_id AND
					tmls.mls_id		= tmlipu.mls_id
			INNER JOIN tbItem								ti		WITH (NOLOCK)
				ON	ti.comp_id		= tmlipu.comp_id AND
					ti.item_id		= tmlipu.item_id
			WHERE	tmlipu.comp_id	= @comp_id AND
					tmlipu.mlp_id	= @mlp_id




		SELECT	DISTINCT
			tmlipv.comp_id,
			tmlipv.mlpv_id,
			tmlipv.mlp_id,
			tmlipv.item_id,
			tmlipv.mlpv_disabled,
			ti.item_code,
			tmlipv.MLVariationID,
			tmlipv.mlpv_order,
			@strIDorCODE   [strIDorCODE]
			FROM	   tbMercadoLibre_ItemsPublicadosVariations					tmlipv	WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations	tmlipvc WITH (NOLOCK)
				ON	tmlipvc.comp_id = tmlipv.comp_id		AND
					tmlipvc.mlpv_id = tmlipv.mlpv_id
			INNER JOIN tbitem													ti		WITH (NOLOCK)
				ON	ti.comp_id		= tmlipv.comp_id		AND
					ti.item_id		= tmlipv.item_id
			WHERE	tmlipv.comp_id	= @comp_id				AND
					tmlipv.mlp_id	= @mlp_id
			ORDER BY tmlipv.mlpv_order ASC
	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_GetDataActive]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		DECLARE			@bitHasPending2Associate AS BIT = 'False'
		SELECT TOP 1	@bitHasPending2Associate		= 'True'
			FROM tbMercadoLibre_ItemsPublicadosVariations AS tmlipv	WITH (NOLOCK)
			WHERE
					tmlipv.comp_id			= @comp_id				AND
					tmlipv.mlp_id			= @mlp_id				AND
					tmlipv.mlpv_disabled	= 1						AND
					tmlipv.item_id IS NULL							AND
					tmlipv.MLVariationID > 0




		SELECT	DISTINCT
			tmlipv.comp_id,
			tmlipv.mlpv_id,
			tmlipv.mlp_id,
			tmlipv.item_id,
			tmlipv.mlpv_disabled,
			ti.item_code,
			tmlipv.MLVariationID,
			tmlipv.mlpv_order,
			CASE
				WHEN tmlipv.MLVariationID = 0 THEN  1
				ELSE								0
			END											[isInsert],
			CASE
				WHEN tmls.mls_SKU_byItemCode = 'True' THEN	ti.item_code
				ELSE										CONVERT (NVARCHAR(10),ti.item_id)
			END											[strIDorCODE],
			@bitHasPending2Associate					[bitHasPending2Associate]	,
			ISNULL(tmlipv.mlpv_pauseVariation,'False')	[mlpv_pauseVariation]


			FROM	   tbMercadoLibre_ItemsPublicadosVariations					tmlipv	WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations	tmlipvc WITH (NOLOCK)
				ON	tmlipvc.comp_id = tmlipv.comp_id		AND
					tmlipvc.mlpv_id = tmlipv.mlpv_id
			INNER JOIN tbitem													ti		WITH (NOLOCK)
				ON	ti.comp_id		= tmlipv.comp_id		AND
					ti.item_id		= tmlipv.item_id
			INNER JOIN tbMercadoLibre_ItemsPublicados							tmlipu	WITH (NOLOCK)
				ON	tmlipu.comp_id	= tmlipv.comp_id AND
					tmlipu.mlp_id	= tmlipv.mlp_id
			INNER JOIN tbMercadoLibre_Stores									tmls	WITH (NOLOCK)
				ON	tmls.comp_id	= tmlipu.comp_id AND
					tmls.mls_id		= tmlipu.mls_id
			WHERE	tmlipv.comp_id	= @comp_id				AND
					tmlipv.mlp_id	= @mlp_id				AND
					ISNULL(tmlipv.mlpv_disabled,'False') = 'False'
			ORDER BY
					CASE
						WHEN tmlipv.MLVariationID = 0 THEN  1
						ELSE								0
					END,
					tmlipv.mlpv_order ASC
	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_GetDataById]
(
	@comp_id	INT,
	@mlpv_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			tmlipv.comp_id,
			tmlipv.mlpv_id,
			tmlipv.mlp_id,
			tmlipv.item_id,
			tmlipv.mlpv_disabled,
			tmlipv.MLVariationID,
			ISNULL(ti.item_code,'')							[item_code],
			ISNULL(ti.item_desc,'')							[item_desc],
			ISNULL(tmlipv.mlpv_order,0)						[mlpv_order],
			ISNULL(tmlipv.mlpv_pauseVariation, 'False')		[mlpv_pauseVariation]
			FROM tbMercadoLibre_ItemsPublicadosVariations	tmlipv	WITH(NOLOCK)
			LEFT JOIN tbItem							ti			WITH(NOLOCK)		-- MOS 03-2021  LEFT - LO CAMBIO POR INNER Y EXPLOTABA EN VARIACIONES
				ON	ti.comp_id		= tmlipv.comp_id		AND
					ti.item_id		= tmlipv.item_id
			WHERE	tmlipv.comp_id = @comp_id						AND
					tmlipv.mlpv_id = @mlpv_id
	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_GetDataByMLP_ID]
(
	@comp_id	INT,
	@mlp_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			''												[1], --CARGAR/MODIFICAR VARIACIONES
			''												[2], --VER TODAS LAS VARIACIONES CARGADAS
			''												[3], --ELIMINAR VARIACIONES
			--''												[4], --MODIFICAR VARIATIONID
			ISNULL(ti.item_code,'')							[item_code],
			ISNULL(ti.item_desc,'')							[item_desc],
			CONVERT(INT,ROUND(dbo.fnGetAStock4MaxAssociation(tmlip.comp_id, CASE
																				WHEN tmlip.stor_id4StockAvailability IS NOT NULL THEN	tmlip.stor_id4StockAvailability
																				ELSE													tmls.stor_id4StockAvailability
																			END	, tmlipv.item_id, 99999999),0))		[stock_Availability],
			ISNULL(tmlipv.mlpv_disabled,'False')			[mlpv_disabled],
			tmlipv.MLVariationID,
			ISNULL(tmlipv.mlpv_order,0)						[mlpv_order],
			--ti.item_id,
			tmlipv.mlpv_id									[ID]
			FROM tbMercadoLibre_ItemsPublicadosVariations	tmlipv	WITH(NOLOCK)
			INNER JOIN tbMercadoLibre_ItemsPublicados		tmlip	WITH(NOLOCK)
			ON	tmlip.comp_id	= tmlipv.comp_id			AND
				tmlip.mlp_id	= tmlipv.mlp_id
			INNER JOIN tbMercadoLibre_Stores				tmls	WITH(NOLOCK)
			ON	tmls.comp_id	= tmlip.comp_id				AND
				tmls.mls_id		= tmlip.mls_id
			LEFT JOIN tbItem								ti		WITH(NOLOCK)
			ON	ti.comp_id		= tmlipv.comp_id			AND
				ti.item_id		= tmlipv.item_id
			WHERE	tmlipv.comp_id	= @comp_id				AND
					tmlipv.mlp_id	= @mlp_id
	END
GO

