CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_InsertData4VariationsImportFromButton]
(
	@comp_id			INT,
	@mlp_id				INT,
	@MLVariationID		BIGINT	,
	@TotalVariations	INT
)
AS

BEGIN
	SET NOCOUNT ON
	-- ------------------------------------------------
	-- TESTING
	-- ------------------------------------------------
	/*
		DECLARE
			@comp_id		INT,
			@mlp_id			INT,
			@MLVariationID	BIGINT
		SELECT
			@comp_id		= 1,
			@mlp_id			= 1,
			@MLVariationID	= 111111
	*/
	-- ------------------------------------------------

	DECLARE @bitHasVariationsInserted AS BIT = 'False'
	DECLARE @return_value	INT







	-- MOS 29-12-2020 x tema muñoz q no se procesaban unas rows
	IF   @TotalVariations = 1 AND
		EXISTS(SELECT TOP 1
					1
					FROM tbMercadoLibre_ItemsPublicadosVariations	tmlipv	WITH(NOLOCK)
					WHERE	tmlipv.comp_id			= @comp_id		AND
							tmlipv.mlp_id			= @mlp_id		AND
							tmlipv.item_id			= 				CASE
																		WHEN @TotalVariations = 1 THEN (	SELECT tmlip.item_id
						                                														FROM tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
						                                														WHERE	tmlip.comp_id	= @comp_id AND
						                                																tmlip.mlp_id	= @mlp_id
																										)
																		ELSE -999999999
																	END	AND
							(tmlipv.MLVariationID = 0 OR tmlipv.MLVariationID = @MLVariationID OR tmlipv.MLVariationID <> @MLVariationID )					AND
							tmlipv.mlpv_disabled = 'True'
			)
		BEGIN
			SET @bitHasVariationsInserted = 'False'
			UPDATE tbMercadoLibre_ItemsPublicadosVariations
				SET mlpv_disabled	=	0,
					MLVariationID	=	@MLVariationID
				WHERE	comp_id = @comp_id	AND
						mlp_id	= @mlp_id	AND
						item_id =	CASE
										WHEN @TotalVariations = 1 THEN (	SELECT tmlip.item_id
						                                						FROM tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
						                                						WHERE	tmlip.comp_id	= @comp_id AND
						                                								tmlip.mlp_id	= @mlp_id
																		)
										ELSE -999999999
									END
			SELECT @bitHasVariationsInserted, @return_value [ID]
			return
		END




	IF EXISTS(SELECT TOP 1
					1
					FROM tbMercadoLibre_ItemsPublicadosVariations	tmlipv	WITH(NOLOCK)
					WHERE	tmlipv.comp_id			= @comp_id		AND
							tmlipv.mlp_id			= @mlp_id		AND
							tmlipv.MLVariationID	= @MLVariationID
			)
		BEGIN
			SET @bitHasVariationsInserted = 'False'
		END
	ELSE
		BEGIN
			SET @bitHasVariationsInserted = 'True'
			INSERT INTO tbMercadoLibre_ItemsPublicadosVariations	WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				item_id,
				mlpv_disabled,
				MLVariationID,
				mlpv_order
			)
			VALUES
			(
				@comp_id,
				@mlp_id,
				CASE
					WHEN @TotalVariations = 1 THEN (	SELECT tmlip.item_id
						                                	FROM tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
						                                	WHERE	tmlip.comp_id	= @comp_id AND
						                                			tmlip.mlp_id	= @mlp_id
													)
					ELSE NULL
				END,
				CASE
					WHEN @TotalVariations = 1 THEN  'False'
					ELSE							'True'
				END,
				@MLVariationID,
				0
			)

			SET @return_value = @@IDENTITY

		END

	SELECT @bitHasVariationsInserted, @return_value [ID]

END

GO

