CREATE PROCEDURE [dbo].[spMercadoLibre_ItemsPublicadosVariations_UpdateVariationID]
(
	@comp_id		INT,
	@mlp_id			INT,
	@item_id		INT,
	@MLVariationID	BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON

		--STL ES UN IDIOTA QUE SIN QUERER Y POR NO LEER BIEN EL NOMBRE DEL SP CAMBIÓ UN PARÁMETRO DE NOMBRE
		--SIEMPRE PASABA EL MLP_ID Y POR IMBECIL PUSO MLPV

		UPDATE tbMercadoLibre_ItemsPublicadosVariations		WITH (ROWLOCK)
		SET
			MLVariationID	= @MLVariationID
			WHERE	comp_id	= @comp_id		AND
					mlp_id	= @mlp_id		AND
					item_id	= @item_id		AND
				   (
				   	MLVariationID = 0
				   		OR
				    MLVariationID IS NULL
				   )

	END
GO

