		*/
		-- ------------------------------------------
		--
		SELECT
			' '													[ ],
			' '													[ ],
			tmlm.mlmd_dateCreated,
			tmlm.mlmd_publicationID,
			tmlip.mlp_itemTitle,
			tmls.mls_desc,
			tmlm.mlmd_reason,
			--tmlm.mlmd_remedy,
			-- NO PONER NADA DEBAJO DE ESTOS CAMPOS
			tmlm.mlmd_id,															-- COUNT -3
			CASE
				WHEN  ISNULL(tmlm.mlmd_verified,'False') = 'True' THEN	1
				ELSE													0
			END													[mlmd_verified],	-- COUNT -2
			tmlip.mlp_id										[ID]				-- COUNT -1
			FROM tbMercadoLibre_Moderations						AS tmlm	WITH(NOLOCK)
				INNER JOIN tbMercadoLibre_Stores				AS tmls WITH(NOLOCK)
					ON	tmls.comp_id			= tmlm.comp_id	AND
						tmls.mls_id				= tmlm.mls_id
				INNER JOIN tbMercadoLibre_ItemsPublicados		AS tmlip WITH(NOLOCK)
					ON	tmlip.comp_id			= tmlm.comp_id	AND
						tmlip.mlp_publicationID = tmlm.mlmd_publicationID
			WHERE	tmlm.comp_id				= @comp_id		AND
					tmlm.mls_id					= @mls_id		AND
					(
						@intFilter				= -1													OR
						@intFilter = 1 AND tmlm.mlmd_reason LIKE '%cambio inusual%'						OR
						@intFilter = 2 AND tmlm.mlmd_reason LIKE '%no tuvo ventas%'						OR
						@intFilter = 3 AND tmlm.mlmd_reason LIKE '%verificando que tu foto%'			OR
						@intFilter = 3 AND tmlm.mlmd_reason LIKE '%La foto no se cargó correctamente%'	OR
						@intFilter = 4 AND tmlm.mlmd_reason LIKE '%catálogo%'							OR
						@intFilter = 5 AND tmlm.mlmd_reason LIKE '%política%'							OR
						@intFilter = 6 AND tmlm.mlmd_reason LIKE '%revisión%'
					)											AND
					(
						@strFilter				= ''					OR
						tmlm.mlmd_reason		LIKE '%' + @strFilter + '%'
					)
			ORDER BY tmlm.mlmd_dateCreated DESC

	END
GO





