CREATE PROCEDURE spMercadoLibre_Moderations_GetDataByID
(
	@comp_id	INT,
	@mlmd_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlmd_id	INT
			SELECT
				@comp_id	= 1,
				@mlmd_id	= 1
		*/
		-- ---------------------------------------------------------
		SELECT
			tmlm.comp_id,
			tmlm.mlmd_id,
			tmlm.mls_id,
			tmlm.mlmd_publicationID,
			ISNULL(tmlm.mlmd_reason,'') [mlmd_reason],
			tmlm.mlmd_remedy			[mlmd_remedy],
			tmlm.mlmd_dateCreated,
			tmlm.mlmd_verified
		FROM tbMercadoLibre_Moderations AS tmlm	WITH(NOLOCK)
		WHERE	tmlm.comp_id = @comp_id AND
				tmlm.mlmd_id = @mlmd_id
	END
GO

CREATE PROCEDURE [dbo].spMercadoLibre_Moderations_GetDataByMLA
(
	@comp_id	INT,
	@mlPublicationID	VARCHAR(30)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlmd_id	INT
			SELECT
				@comp_id	= 1,
				@mlmd_id	= 1
		*/
		-- ---------------------------------------------------------



		SELECT TOP 1
			tmlm.comp_id,
			tmlm.mlmd_id,
			tmlm.mls_id,
			tmlm.mlmd_publicationID,
			ISNULL(tmlm.mlmd_reason,'')			[mlmd_reason],
			ISNULL(tmlm.mlmd_remedy,'')			[mlmd_remedy],
			tmlm.mlmd_dateCreated,
			tmlm.mlmd_verified
			FROM tbMercadoLibre_Moderations				AS tmlm		WITH(NOLOCK)
			INNER JOIN tbMercadoLibre_ItemsPublicados	AS tmlip	WITH (NOLOCK)
				ON	tmlip.comp_id			= tmlm.comp_id		AND
					tmlip.mlp_publicationID = tmlm.mlmd_publicationID
			WHERE	tmlip.comp_id			= @comp_id			AND
					tmlip.mlp_publicationID = @mlPublicationID	AND
					tmlm.mlmd_verified		= 0
			ORDER BY tmlm.mlmd_dateCreated DESC


		IF @@ROWCOUNT > 0
			BEGIN
				UPDATE tbMercadoLibre_Moderations
					SET	mlmd_verified			= 1
					WHERE	comp_id				= @comp_id AND
							mlmd_publicationID	= @mlPublicationID
			END



	END

GO

