CREATE PROCEDURE [dbo].[spMercadoLibre_ordersDetail_InsertData]
(
	@comp_id				INT,
	@mlo_id					INT,
	@mlp_PublicationID		NVARCHAR(30),
	@mlp_PublicationID2		NVARCHAR(30),
	@item_id				INT,
	@mlo_unit_price			DECIMAL(19,4),
	@mlo_quantity			INT,
	@mlo_currency_id		NCHAR(10),
	@mlo_note				NVARCHAR(4000),
	@mlo_listing_fee_amount	DECIMAL(19,4),
	@mlo_sale_fee_amount	DECIMAL(19,4),
	@intShippingID			BIGINT,
	@guiGUID4QUEUEMODE		UNIQUEIDENTIFIER,
	@strTitle				NVARCHAR(500),
	@intVariationID			BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON

		IF @intVariationID <= 0 SET @intVariationID = NULL

		SET @mlp_PublicationID2 = dbo.fnStrAllTrim(@mlp_PublicationID2)


		DECLARE
			@mlp_id		INT,
			@stor_id	INT,
			@user_id	INT

		-- ----------------------------------------------------------------------------------------
		-- Busca datos en la Publicacion Actual
		-- ----------------------------------------------------------------------------------------
		SELECT TOP 1
			@mlp_id		= tmlip.mlp_id,
			@item_id	=	CASE
								WHEN @item_id > 0						THEN @item_id		-- NO MODIFICAR, es para CAGADAS si sacas esto de acá !!!!!!!! NOOOOOOOO!!!!!!
								WHEN @item_id <= 0					AND
									 @intVariationID > 0			AND
									 tmlipv.mlp_id = tmlip.mlp_id	AND
									 tmlipv.item_id IS NOT NULL			THEN tmlipv.item_id
								ELSE 										 tmlip.item_id
							END,
			@stor_id						=	CASE
													WHEN tmlip.stor_id IS NOT NULL THEN tmlip.stor_id
													ELSE								tmls.stor_id
												END,
			@user_id						= tmls.[user_id]
		FROM tbMercadoLibre_ItemsPublicados			tmlip			WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_Stores		tmls			WITH (NOLOCK)
				ON	tmls.comp_id	= tmlip.comp_id		AND
					tmls.mls_id		= tmlip.mls_id
			INNER JOIN tbMercadoLibre_ItemsPublicadosCategories tmlipc	WITH (NOLOCK)
				ON	tmlipc.comp_id			= tmlip.comp_id AND
					tmlipc.mlipc_id			= tmlip.mlipc_id
			LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations AS tmlipv	WITH (NOLOCK)
				ON	tmlipv.comp_id			= @comp_id			AND
					tmlipv.MLVariationID	= @intVariationID
		WHERE	tmlip.comp_id				= @comp_id	AND
				(
					tmlip.mlp_publicationID = @mlp_PublicationID
						OR
					( @mlp_PublicationID2 <> '' AND tmlip.mlp_publicationID = @mlp_PublicationID2)
				)
		-- ----------------------------------------------------------------------------------------



		-- ----------------------------------------------------------------------------------------
		-- Si NO llega el ID se fija si la tienda trabaja cargando pedidos de items NO PUBLICADOS.
		-- ----------------------------------------------------------------------------------------
		IF @item_id <= 0 OR @item_id IS NULL
			BEGIN
				SELECT	@item_id =
						CASE
							WHEN	@strTitle LIKE '%' +  tmls.mls_orderWithNoPublicatedItem_itemId2_OnlyIfContains + '%'
										AND
									tmls.mls_orderWithNoPublicatedItem_itemId2 IS NOT NULL									THEN tmls.mls_orderWithNoPublicatedItem_itemId2
							WHEN	tmls.mls_orderWithNoPublicatedItem_itemId1 IS NOT NULL									THEN tmls.mls_orderWithNoPublicatedItem_itemId1
							ELSE																							     @item_id
						END,
						@stor_id = tmls.stor_id,
						@user_id = tmls.[user_id],
						@mlp_id  = NULL
					FROM tbMercadoLibre_ordersHeader tmloh		WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_Stores tmls		WITH (NOLOCK)
						ON  tmls.comp_id	= tmloh.comp_id AND
							tmls.mls_id		= tmloh.mls_id
					WHERE	tmloh.comp_id	= @comp_id		AND
							tmloh.mlo_id	= @mlo_id		AND
							tmls.mls_orderWithNoPublicatedItem_Enabled = 'True'
			END
		-- ----------------------------------------------------------------------------------------


		-- ----------------------------------------------------------------------------------------
		-- MOS 05-2021
		-- Como esta MAL hecho esto, se pone como NO disponible para stock si es que YA se generó el pedido para esta ORDEN.!!!
		-- ----------------------------------------------------------------------------------------
		DECLARE @mlo_is4AvailableStock AS BIT = 1
		SELECT	@mlo_is4AvailableStock =	CASE
												WHEN tmloh.mlo_isSaleOrderGenerated = 1				THEN 0
												WHEN tmloh.mlo_isSaleOrderEmmited   = 1				THEN 0
												WHEN tmloh.mlo_isCancelled		    = 1				THEN 0
												WHEN tmloh.mlo_status				= 'cancelled'	THEN 0
												ELSE													 1
											END
			FROM    tbMercadoLibre_ordersHeader tmloh		WITH (NOLOCK)
			WHERE	tmloh.comp_id	= @comp_id AND
					tmloh.mlo_id	= @mlo_id
		-- ----------------------------------------------------------------------------------------




		DECLARE @bolExistData AS BIT = 'False'
		SELECT	@bolExistData		 = 'True'
			FROM tbMercadoLibre_ordersDetail	WITH (NOLOCK)
			WHERE	comp_id = @comp_id AND
					mlo_id	= @mlo_id

		IF @bolExistData = 'False'
			BEGIN
				INSERT INTO tbMercadoLibre_ordersDetail	--WITH (ROWLOCK)
				(
					comp_id,
					mlo_id,
					-- mlod_id -- this column value is auto-generated,
					mlp_id,
					item_id,
					mlo_unit_price,
					mlo_quantity,
					mlo_currency_id,
					mlo_note,
					stor_id,
					mlo_listing_fee_amount,
					mlo_sale_fee_amount,
					mlo_title,
					MLVariationID,
					mlo_is4AvailableStock,
					mlod_lastUpdate
				)
				VALUES
				(
					@comp_id,
					@mlo_id,
					@mlp_id,
					@item_id,
					@mlo_unit_price,
					@mlo_quantity,
					@mlo_currency_id,
					@mlo_note,
					@stor_id,
					@mlo_listing_fee_amount,
					@mlo_sale_fee_amount,
					@strTitle,
					@intVariationID,
					@mlo_is4AvailableStock,
					GETDATE()
				)
			END
		ELSE
			BEGIN
				UPDATE tbMercadoLibre_ordersDetail	WITH (ROWLOCK)
					SET
						mlp_id					= @mlp_id,
						item_id					= @item_id,
						mlo_unit_price			= @mlo_unit_price,
						mlo_quantity			= @mlo_quantity,
						mlo_currency_id			= @mlo_currency_id,
						mlo_note				= @mlo_note,
						stor_id					= @stor_id,
						mlo_listing_fee_amount	= @mlo_listing_fee_amount,
						mlo_sale_fee_amount		= @mlo_sale_fee_amount,
						mlo_title				= @strTitle,
						MLVariationID			= @intVariationID,
						mlo_is4AvailableStock	= @mlo_is4AvailableStock,
						mlod_lastUpdate			= GETDATE()
					WHERE	comp_id = @comp_id AND
							mlo_id	= @mlo_id
			END








		IF @mlp_id IS NOT NULL	AND
			NOT EXISTS (
						SELECT TOP 1 1
							FROM tbMercadoLibre_updateQueue AS tmluq			WITH (NOLOCK)
							WHERE
								tmluq.comp_id			 = @comp_id	AND
								tmluq.mlp_id			 = @mlp_id	AND
								tmluq.mlproc_option      = 4		AND
								tmluq.mlproc_isProcessed = 0		AND
								tmluq.mlproc_isCancelled = 0
						)
			AND
			EXISTS(
					SELECT TOP 1 1
						FROM tbMercadoLibre_ItemsPublicados AS tmlip			WITH (NOLOCK)
						WHERE	tmlip.comp_id		= @comp_id	AND
								tmlip.mlp_id		= @mlp_id	AND
								tmlip.mlp_Active	= 'True'
					)
			BEGIN

				-- MOS 06-2024: x las dudas actualizo el precio, x caso FAS
				INSERT INTO tbMercadoLibre_updateQueue	WITH (ROWLOCK)
					(
						comp_id,
						mlp_id,
						mlproc_option,
						mlproc_integerValue,
						mlproc_isProcessed,
						mlproc_isCancelled,
						mlproc_priority,
						mlproc_internalID
					)
					VALUES
					(
						@comp_id,
						@mlp_id,
						8,
						0,
						'False',
						'False',
						0,
						91355
					)

				-- Mando a que le recargue stock segun pueda y la active   **864654ef987987
				INSERT INTO tbMercadoLibre_updateQueue	WITH (ROWLOCK)
				(
					comp_id,
					mlp_id,
					mlproc_option,
					mlproc_integerValue,
					mlproc_isProcessed,
					mlproc_isCancelled,
					mlproc_priority,
					mlproc_internalID,
					mlproc_guid
				)
				VALUES
				(
					@comp_id,
					@mlp_id,
					4,
					0,
					'False',
					'False',
					0,
					99888987,
					@guiGUID4QUEUEMODE
				)
			END




	END
GO

