CREATE PROCEDURE [dbo].[spMercadoLibre_ordersHeader_GetCTTransactionByMLO_ID]
(
	@comp_id	INT,
	@mlo_id		INT
)
AS
	BEGIN


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET NOCOUNT ON
		-- -------------------------------------
		-- TESTING
		-- -------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlo_id		INT
			SELECT
				@comp_id	= 1,
				@mlo_id		= 21
		*/
		-- -------------------------------------

		-- -------------------------------------
		--	VARIABLES DE TRABAJO
		-- -------------------------------------
			DECLARE
				@lsoh_id			INT,
				@lsoh_bra_id		INT,
				@lct_transaction	INT,
				@lsd_id				INT
			SET @lsoh_id			= 0
			SET @lsoh_bra_id		= 0
			SET @lct_transaction	= 0
			SET @lsd_id				= 0
		-- -------------------------------------

		--RECUPERO EL SOH_ID
		SELECT
			@lsoh_id		= tsohh.soh_id,
			@lsoh_bra_id	= tsohh.bra_id
		FROM tbSaleOrderHeaderHistory tsohh		WITH(NOLOCK)
		WHERE	tsohh.comp_id	= @comp_id AND
				tsohh.mlo_id	= @mlo_id


		--Con el SOH_ID recupero el CT_TRANSACTION
		SELECT
			@lct_transaction		= tct.ct_transaction,
			@lsd_id					= tct.sd_id
		FROM tbCommercialTransactions				tct			WITH(NOLOCK)
		WHERE	tct.comp_id			= @comp_id		AND
				tct.ct_soh_bra_id	= @lsoh_bra_id	AND
				tct.ct_soh_id		= @lsoh_id

		SELECT
			@lct_transaction	[ct_transaction],
			@lsd_id				[sd_id]

	END
GO


-- =================================================================================================================
-- Author		: STL
-- Updates
-- STL			: 12-09-2018 Se agregó el INNER JOIN contra la tabla tbMercadoLibre_ItemsPublicados para poder
--				  agregar el filtro de Tiendas de MercadoLibre pedido por Colucci #STL12092018
-- =================================================================================================================

CREATE PROCEDURE [dbo].[spMercadoLibre_ordersHeader_getDataByFilters]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@fc_id					INT,
	@nickname				NVARCHAR(100),
	@option_status			INT,			--  1  Pendientes de Pago
											-- -1 Todos
											--  2  Pendientes de generar Pedido
											--  3  Pendientes de Facturación
											--  4  Facturadas
											--  5  Canceladas
	@datefrom				DATETIME,
	@dateto					DATETIME,
	@isWithFraud			INT,
	@deliverystatus			INT,			-- 1: Pendiente con envio, 2: pendiente sin envio , -1 : Todos
	@mls_id					INT,
	@ItemGuid				UNIQUEIDENTIFIER,
	@MLorder_Id				BIGINT,			-- ID de Orden de Mercadolibre©
	@option_LabelPrinted	INT,			-- Etiquetas Impresas : -1 Todos, 0 Pendientes, 1 Impresas
	@MLtracking_number		NVARCHAR(100),
	@mlo_ismshops			INT,				-- Es MercadoShops? : -1 Todos, 0 MercadoLibre, 1 MercadoShops
	@CustGuid				UNIQUEIDENTIFIER,
	@storg_id				INT,
	@intME1Status			INT,
	@mlo_ismshops_invited	INT	,			--SI ES UNA VENTA DE MSHOPS QUE INGRESO COMO INVITADO
	@deliveryDateFrom		DATETIME,
	@deliveryDateTo			DATETIME,
	@dl_id					INT,
	@sm_id					INT


)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- Testing
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@fc_id				INT,
				@nickname			NVARCHAR(100),
				@option_status		INT	,
				@datefrom			DATETIME,
				@dateto				DATETIME,
				@isWithFraud		INT,
				@deliverystatus		INT,			-- 1: Pendiente con envio, 2: pendiente sin envio , -1 : Todos
				@mls_id				INT,
				@storg_id				INT = 1,
				@ItemGuid				UNIQUEIDENTIFIER ,
				@MLorder_Id				BIGINT = 0,			-- ID de Orden de Mercadolibre©
				@option_LabelPrinted	INT = -1,			-- Etiquetas Impresas : -1 Todos, 0 Pendientes, 1 Impresas
				@MLtracking_number		NVARCHAR(100) = '',
				@mlo_ismshops			INT = -1,				-- Es MercadoShops? : -1 Todos, 0 MercadoLibre, 1 MercadoShops
				@CustGuid				UNIQUEIDENTIFIER


			SELECT
				@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 39,
				@fc_id				= -1,
				@nickname			= '',
				@option_status		= 3,
				@datefrom			= '2020-10-21',
				@dateto				= '2055-12-31',
				@isWithFraud		= 0,
				@deliverystatus		= -1,
				@mls_id				= -1

		*/
		-- -----------------------------------------------------------------------------

		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,  'True')

		-- ---------------------------------------------------------------------------
		-- RECUPERO TODOS LOS ARTICULOS PARA EL GUID
		-- ---------------------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items (item_id)
		SELECT
			tcf.sl_id
			FROM tbComplexFilter				tcf  	WITH (NOLOCK)
			WHERE	tcf.sl_guid		= @ItemGuid AND
					tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items(item_id)
			SELECT
				ti.item_id
				FROM tbItem ti	WITH (NOLOCK)
				WHERE ti.comp_id	= @comp_id
		END
		-- ---------------------------------------------------------------------------



		-- ---------------------------------------------------------------------------
		-- RECUPERO TODOS LOS ARTICULOS PARA EL GUID
		-- ---------------------------------------------------------------------------
		DECLARE		@bitFilterByCustID AS BIT = 'False'
		DECLARE		@tblComplexFilter_Customers TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customers(cust_id)
		SELECT
			tcf.sl_id
			FROM tbComplexFilter				tcf		WITH (NOLOCK)
			WHERE	tcf.sl_guid		= @CustGuid AND
					tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customers	(cust_id)
					SELECT
						ti.cust_id
						FROM tbCustomer ti	WITH (NOLOCK)
						WHERE ti.comp_id	= @comp_id
			END
		ELSE
			BEGIN
				SET @bitFilterByCustID = 'True'
			END
		-- ---------------------------------------------------------------------------

		-- ---------------------------------------------------------------------------
		-- Depositos del Grupo de depositos
		-- ---------------------------------------------------------------------------
		DECLARE @tblStorage TABLE(stor_id  INT PRIMARY KEY)
		IF @storg_id = -1
			BEGIN
				INSERT INTO @tblStorage
				(
					stor_id
				)
				SELECT ts.stor_id
					FROM tbStorage AS ts	WITH (NOLOCK)
					WHERE ts.comp_id = @comp_id
			END
		ELSE
			BEGIN
				INSERT INTO @tblStorage
				(
					stor_id
				)
				SELECT DISTINCT  tsgd.stor_id
					FROM tbStorageGroupDetail AS tsgd	WITH (NOLOCK)
					WHERE	tsgd.comp_id	= @comp_id AND
							tsgd.storg_id	= @storg_id
			END
		-- ---------------------------------------------------------------------------


--SELECT * FROM @tblStorage


		SELECT
			''												[1],	-- VER PAYMENTS
			''												[2],	-- VER SHIPPING
			''												[3],	-- VER PEDIDO
			''												[4],	-- VER PREPARACIÓN Y SERIALIZACIÓN DEL PEDIDO
			''												[5],	-- VER COMPROBANTE
			''												[6],	-- ENVIAR MENSAJE POR Mercadolibre
			''												[7],	-- ACTUALIZAR SI ESTÁ EMITIDO O NO EL PEDIDO
			''												[8],	-- VER ARTÍCULOS DE LA ORDEN
			''												[9],	-- DIGITALIZACIÓN
			''												[10],	-- MARCAR COMO ENVIADA
			''												[11],	-- IMPRIMIR ETIQUETA ML
			''												[12],	-- IMPRIMIR ETIQUETA Adicional de detalle de pedido

			convert(bit,ISNULL(tmloh.mlo_isWithFraud,'False'))		[mlo_isWithFraud],
			ISNULL(tmloh.mlo_ismshops,'False')						[mlo_ismshops],
			CASE
				WHEN tcct.cust_id	IS NOT NULL		THEN tcct.cust_name --commercial
				WHEN tcsoh.cust_id	IS NOT NULL		THEN tcsoh.cust_name
				ELSE								''
			END																									[cust_name],
			--tct.ct_transaction,tsoh.soh_id,
			--tcsoh.cust_id,tcct.cust_id,
			tmlud.nickname,
			CASE
				WHEN tcct.cust_id	IS NOT NULL		THEN	convert(nvarchar(200),dbo.fnGetCommercialTransactionDescription(tct.comp_id,2,tct.ct_transaction))
				WHEN tcsoh.cust_id	IS NOT NULL		THEN 	convert(nvarchar(200),tdf.df_desc + '(' + convert(nvarchar(10),tsoh.bra_id) + '-'+ convert(nvarchar(10),tsoh.soh_id) +')')
				ELSE ''
			END +
			CASE
				WHEN tmlip.comp_id IS NULL THEN '** No Publication **'
				ELSE ''
			END
				[doc_Number],
			convert(decimal(19,2),tmloh.mlo_transaction_amount)		[mlo_transaction_amount],
			convert(decimal(19,2),tmloh.mlo_shippingCost)			[mlo_shippingCost],
			convert(decimal(19,2),tmloh.mlo_total_paid_amount)		[mlo_total_paid_amount],
			convert(decimal(19,2),tmloh.mlo_cupon_amount)			[mlo_cupon_amount],
			convert(decimal(19,2),tmloh.mlo_overpaid_amount)		[mlo_overpaid_amount],


			tmloh.mlo_status,

			ISNULL(tmloh.mlo_isLabelPrinted,'False')				[mlo_isLabelPrinted],
			ISNULL(tmlos.MLtracking_number,'')						[MLtracking_number],
			--tmloh.mlo_firstJSON,
			--tmloh.mlo_lastJSON,
			--tmloh.ML_id,
			tmloh.ML_date_created,
			tmloh.ML_date_closed,
			tmloh.ML_last_updated,
			tmls.mls_desc												,
			CONVERT(VARCHAR(20),tmloh.MLorder_id)					[MLorder_id],
			tmloh.MLUser_Id,

			ISNULL(tmloh.mlo_isCollected, 'False')					[mlo_isCollected],
			CONVERT(VARCHAR(20),tmloh.MLShippingID)					[MLShippingID],
			CONVERT(VARCHAR(20),tmloh.ML_pack_id)					[MLPackID],
			tmlip.mlp_publicationID,
			tmloh.mlo_cd											[loadDate],
			tmlos.MLShippmentColectaDayTime							[colectaDate],
			td.dl_name,



			--NO PONER NADA DESPUÉS DE ESTO-----------------------------------------------------
			ISNULL(tmloh.mlo_isDelivered,'False')			[mlo_isDelivered],				-- -5
			ISNULL(tmloh.mlo_isSaleOrderEmmited,'False')	[mlo_isSaleOrderEmmited],		-- -4
			ISNULL(tmloh.mlo_isSaleOrderGenerated,'False')	[mlo_isSaleOrderGenerated],		-- -3
			ISNULL(tmloh.mlo_isCancelled,'False')			[mlo_isCancelled],			 	-- -2
			tmloh.mlo_id									[ID]							-- -1

			FROM		tbMercadoLibre_ordersHeader			tmloh		WITH (NOLOCK)

			INNER JOIN tbMercadoLibre_ordersDetail			tmlod		WITH (NOLOCK)
			ON	tmlod.comp_id		= tmloh.comp_id			AND
				tmlod.mlo_id		= tmloh.mlo_id

			INNER JOIN tbMercadoLibre_Stores			 AS tmls		WITH (NOLOCK)
				ON	tmls.comp_id	= tmloh.comp_id AND
					tmls.mls_id		= tmloh.mls_id

			INNER JOIN @tblStorage ttm
				ON ttm.stor_id = tmlod.stor_id

			LEFT JOIN tbMercadoLibre_ItemsPublicados		tmlip		WITH (NOLOCK)		--#STL12092018
			ON	tmlip.comp_id		= tmlod.comp_id			AND
				tmlip.mlp_id		= tmlod.mlp_id

			--INNER JOIN tbItem								ti			WITH (NOLOCK)
			--ON	ti.comp_id			= tmlod.comp_id			AND
			--	ti.item_id			= tmlod.item_id

			LEFT JOIN tbMercadoLibre_UsersData				tmlud		WITH (NOLOCK)
			ON	tmlud.MLUser_Id		= tmloh.MLUser_Id

			LEFT JOIN tbSaleOrderHeader						tsoh		WITH (NOLOCK)
			ON	tsoh.comp_id		= tmloh.comp_id			AND
				tsoh.mlo_id			= tmloh.mlo_id

			LEFT JOIN tbDelivery						 AS td			WITH (NOLOCK)
				ON	td.comp_id		= tsoh.comp_id AND
					td.dl_id		= tsoh.dl_id

			LEFT JOIN tbDocumentsFile						tdf			WITH (NOLOCK)
			ON	tdf.comp_id			= tsoh.comp_id AND
				tdf.df_id			= tsoh.df_id

			LEFT JOIN tbCommercialTransactions				tct			WITH (NOLOCK)
			ON	tct.comp_id			= tmloh.comp_id AND
				tct.mlo_id			= tmloh.mlo_id

			LEFT JOIN tbCustomer							tcsoh		WITH (NOLOCK)
			ON	tcsoh.comp_id		= tsoh.comp_id			AND
				tcsoh.cust_id		= tsoh.cust_id

			LEFT JOIN tbCustomer							tcct		WITH (NOLOCK)
			ON	tcct.comp_id		= tct.comp_id			AND
				tcct.cust_id		= tct.cust_id

			INNER JOIN @tblComplexFilter_Items				tmp
			ON	tmp.item_id			= tmlod.item_id

			LEFT JOIN tbMercadoLibre_ordersShipping			tmlos		WITH (NOLOCK)
			ON	tmlos.comp_id		= tmloh.comp_id			AND
				tmlos.mlo_id		= tmloh.mlo_id


			LEFT JOIN @tblComplexFilter_Customers tmpCU
				ON tmpCU.cust_id	= tsoh.cust_id

			LEFT JOIN @tblComplexFilter_Customers tmpCT
				ON tmpCT.cust_id	= tct.cust_id



			WHERE	tmloh.comp_id	= @comp_id				AND

					-- MOS 04-2024: Si se pone un rango de fecha de entrega, debe poner solo los que tienen entrega.
					(YEAR(@deliveryDateFrom) < 2000 OR tmlos.MLShippmentColectaDayTime BETWEEN @deliveryDateFrom AND @deliveryDateTo)	AND

					CASE
						WHEN @MLorder_Id				= 0				THEN 1
						WHEN tmloh.MLorder_id			= @MLorder_Id	THEN 1
						WHEN tmloh.MLShippingID			= @MLorder_Id	THEN 1
						WHEN tmloh.ML_pack_id			= @MLorder_Id	THEN 1
						ELSE 0
					END = 1 AND
					--(@MLorder_Id	= 0		OR tmloh.MLorder_id			= @MLorder_Id) AND -- 0 TODOS




					CASE
						WHEN	@option_LabelPrinted	= -1												THEN 1
						WHEN	@option_LabelPrinted	= 0			AND
								tmloh.mlo_isLabelPrinted = 'False'	AND
								(tmlos.MLLaben_ZPL2 IS NOT NULL OR tmloh.mlo_mustPrintLabel = 'True')		THEN 1
						WHEN	@option_LabelPrinted	= 1	AND
								tmloh.mlo_isLabelPrinted = 'True'											THEN 1
						ELSE											 0
					END	 = 1	 AND


					CASE
						WHEN @MLtracking_number		= '' THEN 1
						WHEN tmlos.MLtracking_number	LIKE '%' + @MLtracking_number + '%' THEN 1
						ELSE 0
					END = 1 AND
					--(
					--	@MLtracking_number		= ''									OR
					--	tmlos.MLtracking_number	LIKE '%' + @MLtracking_number + '%'
					--)
					--AND



					CASE
						WHEN @option_status = -1 THEN 1
						WHEN 	(@option_status =  1 AND ISNULL(tmloh.mlo_isPaid,'False')				= 'False'
											 AND
								 ISNULL(tmloh.mlo_isCancelled,'False')			= 'False')		THEN 1	-- 1  Pendientes de Pago

						WHEN 	(@option_status =  2 AND ISNULL(tmloh.mlo_isSaleOrderGenerated,'False')	= 'False'
											 AND
								 ISNULL(tmloh.mlo_isCancelled,'False')			= 'False')		THEN 1	-- 2  Pendientes de generar Pedido
						WHEN	(@option_status =  3 AND ISNULL(tmloh.mlo_isSaleOrderEmmited,'False')	= 'False'
											 AND
							     ISNULL(tmloh.mlo_isCancelled,'False')			= 'False')		THEN 1	-- 3  Pendientes de Facturación
						WHEN	(@option_status =  4 AND ISNULL(tmloh.mlo_isSaleOrderEmmited,'False')	= 'True' ) THEN 1
						WHEN	(@option_status =  5 AND ISNULL(tmloh.mlo_isCancelled,'False')			= 'True' ) THEN 1
						ELSE 0
					END = 1	AND
					--(
					--	 @option_status = -1																	OR	-- -1 Todos
					--	(@option_status =  1 AND ISNULL(tmloh.mlo_isPaid,'False')				= 'False'
					--						 AND ISNULL(tmloh.mlo_isCancelled,'False')			= 'False')		OR	-- 1  Pendientes de Pago
					--	(@option_status =  2 AND ISNULL(tmloh.mlo_isSaleOrderGenerated,'False')	= 'False'
					--						 AND ISNULL(tmloh.mlo_isCancelled,'False')			= 'False')		OR	-- 2  Pendientes de generar Pedido
					--	(@option_status =  3 AND ISNULL(tmloh.mlo_isSaleOrderEmmited,'False')	= 'False'
					--						 AND ISNULL(tmloh.mlo_isCancelled,'False')			= 'False')		OR	-- 3  Pendientes de Facturación
					--	(@option_status =  4 AND ISNULL(tmloh.mlo_isSaleOrderEmmited,'False')	= 'True' )		OR	-- 4  Facturadas
					--	(@option_status =  5 AND ISNULL(tmloh.mlo_isCancelled,'False')			= 'True' )			-- 5  Canceladas
					--)																	AND
					tmloh.ML_date_created BETWEEN @datefrom AND @dateto					AND



					CASE
						WHEN  @isWithFraud = -1 THEN 1
						WHEN @isWithFraud = 1 AND tmloh.mlo_isWithFraud = 'True' THEN 1
						WHEN @isWithFraud = 0 AND tmloh.mlo_isWithFraud = 'False'	THEN 1
						ELSE 0
					END = 1	AND
					--(
					--	@isWithFraud = -1										OR
					--	(@isWithFraud = 1 AND tmloh.mlo_isWithFraud = 'True' )	OR
					--	(@isWithFraud = 0 AND tmloh.mlo_isWithFraud = 'False')
					--)
					--
					--																AND


					CASE
						WHEN @nickname		= '' THEN 1
						WHEN tmlud.nickname	LIKE '%' + @nickname + '%' THEN 1
						ELSE 0
					END = 1 AND
					--(
					--	@nickname		= ''									OR
					--	tmlud.nickname	LIKE '%' + @nickname + '%'
					--)

					CASE	-- MOS 04-2024
						WHEN @dl_id = -1			THEN 1
						WHEN @dl_id = tsoh.dl_id	THEN 1
						ELSE							 0
					END = 1		AND

					CASE	-- MOS 04-2024
						WHEN @sm_id = -1			THEN 1
						WHEN @sm_id = tsoh.sm_id	THEN 1
						ELSE							 0
					END = 1		AND


					CASE
						WHEN @deliverystatus = -1 THEN 1
						WHEN (@deliverystatus =  1 AND ISNULL(tmloh.mlo_isDelivered,'False')				= 'False'
											  AND tmloh.MLShippingID	IS NOT NULL)								THEN 1	-- Pendiente de entrega con envio
						WHEN (@deliverystatus =  2 AND ISNULL(tmloh.mlo_isDelivered,'False')				= 'False'
											  AND tmloh.MLShippingID	IS NULL)									THEN 1	-- Pendiente de entrega sin envio
						ELSE 0
					END = 1	AND
					--(
					--	 @deliverystatus = -1																		OR	-- -1 Todos
					--	(@deliverystatus =  1 AND ISNULL(tmloh.mlo_isDelivered,'False')				= 'False'
					--						  AND tmloh.MLShippingID	IS NOT NULL)								OR	-- Pendiente de entrega con envio
					--	(@deliverystatus =  2 AND ISNULL(tmloh.mlo_isDelivered,'False')				= 'False'
					--						  AND tmloh.MLShippingID	IS NULL)										-- Pendiente de entrega sin envio
					--)																	AND



					CASE
						WHEN @mls_id			= -1  THEN 1
						WHEN tmlip.mls_id	= @mls_id THEN 1
						ELSE 0
					END = 1	AND
					--(													--#STL12092018
					--	@mls_id			= -1				OR
					--	tmlip.mls_id	= @mls_id
					--)

					--	AND


					CASE
						WHEN @mlo_ismshops	= -1 THEN 1
						WHEN ISNULL(tmloh.mlo_ismshops,'False')	= @mlo_ismshops THEN 1
						ELSE 0
					END = 1	AND

					--(
					--	@mlo_ismshops	= -1				OR
					--	ISNULL(tmloh.mlo_ismshops,'False')	= @mlo_ismshops			-- Es MercadoShops? : -1 Todos, 0 MercadoLibre, 1 MercadoShops
					--)
					--AND
					CASE
						WHEN @bitFilterByCustID = 'False'							   THEN 1
						WHEN @bitFilterByCustID = 'True' AND tmpCU.cust_id IS NOT NULL THEN 1
						WHEN @bitFilterByCustID = 'True' AND tmpCT.cust_id IS NOT NULL THEN 1
						ELSE 0
					END = 1																AND
					CASE
						WHEN @intME1Status					= -1				THEN 1
						WHEN tmloh.mlo_ME1_deliveryStatus	= @intME1Status AND
							 tmlos.MLshipping_mode			= 'me1'				THEN 1
						ELSE														 0
					END = 1	AND

					(
						@mlo_ismshops_invited						= -1 OR
						ISNULL(tmloh.mlo_ismshops_invited, 'False') = @mlo_ismshops_invited
					)


					--(
					--	@intME1Status					= -1 OR
					--	tmloh.mlo_ME1_deliveryStatus	= @intME1Status
					--)


				-- Si es "Etiquetas impresas = Pendientes de imprimir" ordena de la mas vieja a la mas nueva
				-- Sino al reves, primero las nuevas ordenes.
				ORDER BY
					CASE @option_LabelPrinted	WHEN 0	THEN tmloh.mlo_id   END ASC,
					CASE @option_LabelPrinted	WHEN 1	THEN tmloh.mlo_id	END DESC,
					CASE @option_LabelPrinted	WHEN -1 THEN tmloh.mlo_id	END DESC





	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ordersHeader_GetDataByID]
(
	@comp_id	INT,
	@mlo_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlo_id		INT
			SELECT
				@comp_id	= 1,
				@mlo_id		= 1
		*/
		-- ------------------------------------------------

		SELECT
			tmloh.comp_id,
			tmloh.mlo_id,
			tmloh.MLUser_Id,
			tmloh.cust_id,
			tmloh.mlo_firstJSON,
			tmloh.mlo_lastJSON,
			tmloh.ML_id,
			tmloh.ML_date_created,
			tmloh.ML_date_closed,
			tmloh.ML_last_updated,
			tmloh.mlo_shippingCost,
			tmloh.mlo_transaction_amount,
			tmloh.mlo_cupon_amount,
			tmloh.mlo_overpaid_amount,
			ISNULL(tmloh.mlo_isSaleOrderGenerated,'False')	[mlo_isSaleOrderGenerated],
			ISNULL(tmloh.mlo_isCancelled,'False')			[mlo_isCancelled],
			ISNULL(tmloh.mlo_isCollected,'False')			[mlo_isCollected],
			tmloh.MLorder_id,
			ISNULL(tmloh.mlo_isDelivered,'False')			[mlo_isDelivered],
			ISNULL(tmloh.mlo_isLabelPrinted,'False')		[mlo_isLabelPrinted],
			ISNULL(tmloh.ML_pack_id,-1)						[ML_pack_id],
			tmloh.mls_id,


			tmloh.MLShippingID,
			ISNULL(tmloh.mlo_ME1_deliveryTracking,'')		[mlo_ME1_deliveryTracking],
			ISNULL(tmloh.mlo_ME1_deliveryStatus,-1)			[mlo_ME1_deliveryStatus],
			ISNULL(tmlos.MLshipping_mode,'')				[MLshipping_mode],
			ISNULL(tmls.mls_accessToken,'')					[mls_accessToken],
			ISNULL(tmloh.mlo_mustPrintLabel,'False')		[mlo_mustPrintLabel]


			FROM tbMercadoLibre_ordersHeader				tmloh		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_Stores			 AS tmls		WITH (NOLOCK)
				ON	tmls.comp_id	= tmloh.comp_id	AND
					tmls.mls_id		= tmloh.mls_id
			LEFT JOIN tbMercadoLibre_ordersShipping			AS tmlos	WITH(NOLOCK)
			ON	tmlos.comp_id		= tmloh.comp_id				AND
				tmlos.mlo_id		= tmloh.mlo_id
			WHERE	tmloh.comp_id	= @comp_id	AND
					tmloh.mlo_id	= @mlo_id

	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ordersHeader_GetDataByID4UpdateIsDelivered]
(
	@comp_id	INT,
	@mlo_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlo_id		INT
			SELECT
				@comp_id	= 1,
				@mlo_id		= 64
		*/
		-- ------------------------------------------------

		SELECT
			top 1
			tmloh.comp_id,
			tmloh.mlo_id,
			tmloh.MLUser_Id,
			tmloh.cust_id,
			tmloh.mlo_firstJSON,
			tmloh.mlo_lastJSON,
			tmloh.ML_id,
			tmloh.ML_date_created,
			tmloh.ML_date_closed,
			tmloh.ML_last_updated,
			tmloh.mlo_shippingCost,
			tmloh.mlo_transaction_amount,
			tmloh.mlo_cupon_amount,
			tmloh.mlo_overpaid_amount,
			ISNULL(tmloh.mlo_isSaleOrderGenerated,'False')	[mlo_isSaleOrderGenerated],
			ISNULL(tmloh.mlo_isCancelled,'False')			[mlo_isCancelled],
			ISNULL(tmloh.mlo_isCollected,'False')			[mlo_isCollected],
			tmloh.MLorder_id,
			ISNULL(tmls.mls_qualifiedOKMessage,'') +		CASE
																	WHEN tmls.mls_qualifiedOKInsertLink4UserQualification = 1 THEN 'Por favor te pedimos si podes calificarnos https://feedback.mercadolibre.com.ar/feedback?orderId=' + dbo.fnStrAllTrim( convert(nvarchar(30),tmloh.ML_id)) + '" target="_blank">haciendo clic acá '
																	ELSE ''
			                                        		END [qualifiedMessage],
			tmlod.mlp_id										[mlp_id]



			FROM tbMercadoLibre_ordersHeader						tmloh			WITH (NOLOCK)

			INNER JOIN tbMercadoLibre_ordersDetail					tmlod			WITH (NOLOCK)
			ON	tmlod.comp_id		= tmloh.comp_id		AND
				tmlod.mlo_id		= tmloh.mlo_id

			INNER JOIN tbMercadoLibre_ItemsPublicados				tmlip			WITH (NOLOCK)
			ON	tmlip.comp_id		= tmlod.comp_id AND
				tmlip.mlp_id		= tmlod.mlp_id

			INNER JOIN tbMercadoLibre_Stores						tmls			WITH (NOLOCK)
			ON	tmls.comp_id		= tmlip.comp_id AND
				tmls.mls_id			= tmlip.mls_id

			WHERE	tmloh.comp_id	= @comp_id			AND
					tmloh.mlo_id	= @mlo_id

	END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_ordersHeader_GetDataByIDMLUserId]
(
	@comp_id	INT,
	@MLUser_Id   BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlo_id		INT
			SELECT
				@comp_id	= 1,
				@mlo_id		= 1
		*/
		-- ------------------------------------------------

		SELECT
			TOP 1
			tmloh.comp_id,
			tmloh.mlo_id,
			tmloh.MLUser_Id,
			tmloh.cust_id,
			tmloh.mlo_firstJSON,
			tmloh.mlo_lastJSON,
			tmloh.ML_id,
			tmloh.ML_date_created,
			tmloh.ML_date_closed,
			tmloh.ML_last_updated,
			tmloh.mlo_shippingCost,
			tmloh.mlo_transaction_amount,
			tmloh.mlo_cupon_amount,
			tmloh.mlo_overpaid_amount,
			ISNULL(tmloh.mlo_isSaleOrderGenerated,'False')	[mlo_isSaleOrderGenerated],
			ISNULL(tmloh.mlo_isCancelled,'False')			[mlo_isCancelled],
			ISNULL(tmloh.mlo_isCollected,'False')			[mlo_isCollected],
			tmloh.MLorder_id,
			ISNULL(tmloh.mlo_isDelivered,'False')			[mlo_isDelivered],
			ISNULL(tmloh.mlo_isLabelPrinted,'False')		[mlo_isLabelPrinted],
			ISNULL(tmloh.ML_pack_id,-1)						[ML_pack_id]


			FROM tbMercadoLibre_ordersHeader	tmloh		WITH (NOLOCK)
			WHERE	tmloh.comp_id	= @comp_id	AND
