			ORDER BY tmloh.mlo_id desc

	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ordersHeader_GetDataByMLOrderID]
(
	@comp_id	INT,
	@mlOrderID	BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT TOP 1
			tmloh.comp_id,
			tmloh.mlo_id,
			tmloh.MLUser_Id,
			tmloh.cust_id,
			tmloh.mlo_firstJSON,
			tmloh.mlo_lastJSON,
			tmloh.ML_id,
			tmloh.ML_date_created,
			tmloh.ML_date_closed,
			tmloh.ML_last_updated,
			tmloh.mlo_shippingCost,
			tmloh.mlo_transaction_amount,
			tmloh.mlo_cupon_amount,
			tmloh.mlo_overpaid_amount,
			tmloh.mlo_total_paid_amount,
			tmloh.mlo_status,
			tmloh.MLorder_id,
			tmls.[user_id]
		FROM tbMercadoLibre_ordersHeader			tmloh		WITH (NOLOCK)

		-- ATENCIÓN:
		-- MOS: 12-2019
		-- NO PONER NUNCA JOIN contra DETAIL, hacer NUEVO si hace falta !!!

		--INNER JOIN tbMercadoLibre_ordersDetail		tmlod		WITH (NOLOCK)
		--	ON	tmlod.comp_id	= tmloh.comp_id		AND
		--		tmlod.mlo_id	= tmloh.mlo_id
		--INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)		-- NO, x Articulos SIN PUBLICACION, OJO !!!!!
		--	ON	tmlip.comp_id	= tmlod.comp_id	AND
		--		tmlip.mlp_id	= tmlod.mlp_id
		INNER JOIN tbMercadoLibre_Stores			tmls		WITH (NOLOCK)
			ON	tmls.comp_id	= tmloh.comp_id		AND
				tmls.mls_id		= tmloh.mls_id
		WHERE	tmloh.comp_id		= @comp_id		AND
				(
				tmloh.MLorder_id	= @mlOrderID
					OR
				tmloh.ML_pack_id    = @mlOrderID
				)

	END
GO

