CREATE PROCEDURE spMercadoLibre_ordersHeader_GetSohIdByMLO_ID
(
	@comp_id	INT,
	@mlo_id		BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------
		-- TESTING
		-- --------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlo_id		INT
			SELECT
				@comp_id	= 1,
				@mlo_id		= 21
		*/
		-- --------------------------------------

		-- ---------------------------
		-- VARIBLES DE TRABAJO
		-- ---------------------------
			DECLARE
				@lsoh_id	INT,
				@lbra_id	INT
			SET	@lsoh_id	= 0
			SET @lbra_id	= 0

		-- ---------------------------
		--Recupero el SOH_ID correspondiente al MLO_ID
		SELECT
			@lbra_id  = tsoh.bra_id,
			@lsoh_id  = tsoh.soh_id
			FROM tbSaleOrderHeader				tsoh	WITH(NOLOCK)
			WHERE	tsoh.comp_id	= @comp_id	AND
					tsoh.mlo_id		= @mlo_id

		SELECT
			@lbra_id	[bra_id],
			@lsoh_id	[soh_id]

	END
GO






CREATE PROCEDURE [dbo].[spMercadoLibre_ordersHeader_GetStatus4PrintSecondLabel]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@mlo_id				INT

)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@ml_id		INT
			SELECT
				@comp_id	= 1,
				@ml_id		= 1254512
		*/
		-- ---------------------------------------------

		IF EXISTS (SELECT
						1

					   FROM tbMercadoLibre_ordersHeader							tmloh		WITH(NOLOCK)

					   	INNER JOIN tbMercadoLibre_Stores						tmls		WITH(NOLOCK)
						ON	tmls.comp_id		=	tmloh.comp_id	AND
							tmls.mls_id			=	tmloh.mls_id

					   INNER JOIN tbMercadoLibre_ordersDetail					tmlod		WITH(NOLOCK)
					   ON	tmlod.comp_id		=	tmloh.comp_id		AND
							tmlod.mlo_id		=	tmloh.mlo_id

						INNER JOIN tbMercadoLibre_ItemsPublicados				tmlip		WITH(NOLOCK)
						ON	tmlip.comp_id		=	tmlod.comp_id			AND
							tmlip.mlp_id		=	tmlod.mlp_id




						WHERE	tmloh.comp_id													= @comp_id		AND
								tmloh.mlo_id													= @mlo_id		AND
								isnull(tmls.mls_labelPrintModulePrintSecondLabel,'False')		= 'True'		AND
								isnull(tmlip.mlp_labelPrintModuleNoPrintSecondLabel,'False')	= 'False'
					)

			BEGIN
				SELECT 'True' [PrintSecondLabel]
			END
		ELSE
			BEGIN
				SELECT 'False' [PrintSecondLabel]
			END
	END
GO


