			BEGIN
				SET @intPickUpID = NULL
			END

		if @intMLbra_id = -1
			BEGIN
				SET @intMLbra_id = NULL
			END

		IF @intPack_Id = -1
			BEGIN
				SET @intPack_Id = NULL
			END

		-- Pasan cualquier mierda gigante desde Meli, aca se trunca a maximo de 200
		DECLARE @strMLUser_address AS NVARCHAR(200)  = dbo.fnStrAllTrim( dbo.fnStrPADR( @address_line + ' ' + @comment,200,' '))

		DECLARE @intOrderID AS BIGINT = NULL
		SELECT	@intOrderID = tmloh.MLorder_id
			FROM tbMercadoLibre_ordersHeader		tmloh	--WITH (NOLOCK)
			WHERE	tmloh.comp_id		= @comp_id	AND
					tmloh.MLorder_id	= @MLorder_id
					--(
					--	tmloh.MLorder_id	= @MLorder_id
					--	OR
					--	tmloh.MLShippingID  = @intShippingID
					--)

		--IF @intOrderID IS NOT NULL
		--	BEGIN
		--		SET @MLorder_id = @intOrderID
		--	END



		-- --------------------------------------------------------------------------------
		-- MOS y SL 06052021 No sabemos porque MIERDA se cargan las ordenes duplicadas
		-- por lo que buscamos hasta 10 veces si es que NO la encuentra
		-- y se puso otro tiempo RASNDOM antes de abrir la transaccion en VB
		-- Esto para porque Meli manda en el MISMO milisegundo la MISMA orden duplicada.
		-- IHIOH&%$%&$waqdqwdwq  VS
		-- --------------------------------------------------------------------------------
		--DECLARE @intCounter AS integer = 0
		--WHILE   @intOrderID IS NULL AND @intCounter < 10
		--	BEGIN
		--		SELECT	@intOrderID = tmloh.MLorder_id
		--			FROM tbMercadoLibre_ordersHeader		tmloh	WITH (NOLOCK)
		--			WHERE	tmloh.comp_id		= @comp_id	AND
		--					tmloh.MLorder_id	= @MLorder_id

		--		SET @intCounter = @intCounter + 1
		--	END
		-- --------------------------------------------------------------------------------
		-- Al Pedo, reemplazado x el indice UNIQUE de mas abajo:tbMercadoLibre_ordersHeader_UniqueControl



		-- Si existe la ORDEN o ya hay un envio lo pone en la misma orden
		IF @intOrderID IS NOT NULL
			BEGIN

				UPDATE tbMercadoLibre_ordersHeader	WITH (ROWLOCK)
					SET
						MLUser_Id				= @MLUser_Id,
						cust_id					= @cust_id,
						mlo_lastJSON			.WRITE( @mlo_lastJSON,0,NULL) ,
						ML_id					= @ML_id,
						ML_date_created			= @ML_date_created,
						ML_date_closed			= @ML_date_closed,
						ML_last_updated			= @ML_last_updated,
						mlo_shippingCost		= @mlo_shippingCost,
						mlo_transaction_amount	= @mlo_transaction_amount,
						mlo_cupon_amount		= @mlo_cupon_amount,
						mlo_overpaid_amount		= @mlo_overpaid_amount,
						mlo_total_paid_amount	= @mlo_total_paid_amount,
						mlo_status				= @mlo_status,
						mlo_email				= @mlo_email,
						identificationNumber	= @identificationNumber,
						identificationType		= @identificationType,
						mlo_isPaid				= @isPaid,
						mlo_isDelivered			= @isDelivered,
						mlo_isWithFraud			= @bolHasFraudDetection,
						MLUser_identificationType	= @identificationType,
						MLUser_identificationNumber = @identificationNumber,
						MLUser_address				= @strMLUser_address,--@address_line + ' ' + @comment,
						MLUser_state				= @state,
						MLUser_citi					= @city,
						MLUser_zip_code				= @zip_code,
						MLUser_phone				= @phone,
						MLUser_email				= @email,
						MLUser_receiver_name		= @receiver_name,
						MLUser_receiver_phone		= @receiver_phone,
						MLUser_alternative_phone	= @alternative_phone,
						MLShippingID				= CASE
														  WHEN @intShippingID = -1 THEN NULL
														  ELSE							@intShippingID
													  END,
						MLPickUpID					= @intPickUpID,
						MLPickUpPerson				= @strPickUpPerson,
						mlbra_id					= @intMLbra_id,
						ML_pack_id					= @intPack_Id,
						mls_id						= @mls_id,
						MLUser_first_name			= @first_name,
						MLUser_last_name			= @last_name,
						mlo_ismshops				= @isFromMercadoShops,
						mlo_mustPrintLabel			= @MustPrintLabel,
						mlo_ismshops_invited		= @isFromMercadoShopsInvited

					WHERE	comp_id		= @comp_id		AND
							MLorder_id	= @MLorder_id

				--DEVUELVE EL MLO_ID DEL REGISTRO QUE MODIFICÓ
				SELECT
					tmloh.mlo_id						[ID]
					FROM tbMercadoLibre_ordersHeader		tmloh		WITH (NOLOCK)
					WHERE	tmloh.comp_id		= @comp_id	AND
							tmloh.MLorder_id	= @MLorder_id


				--SI EXISTE EL USUARIO ACTUALIZO LOS CAMPOS
				IF EXISTS (	SELECT TOP 1  1
								FROM tbMercadoLibre_UsersData tmlud		WITH (NOLOCK)
				           		WHERE tmlud.MLUser_Id = @MLUser_Id)
					BEGIN
						UPDATE tbMercadoLibre_UsersData	WITH (ROWLOCK)
							SET
								identificationType		= @identificationType,
								identificationNumber	= @identificationNumber,
								[address]				= @strMLUser_address, --@address_line + ' ' + @comment,
								[state]					= @state,
								citi					= @city,
								zip_code				= @zip_code,
								phone					= @receiver_phone,
								email					= @email
							WHERE MLUser_Id				= @MLUser_Id
					END
				ELSE
					BEGIN
						INSERT INTO tbMercadoLibre_UsersData	WITH (ROWLOCK)
						(
							MLUser_Id,
							nickname,
							identificationType,
							identificationNumber,
							[address],
							[state],
							citi,
							zip_code,
							phone,
							alternative_phone,
							email
						)
						VALUES
						(
							@MLUser_Id,
							@nickname,
							@identificationType,
							@identificationNumber,
							@strMLUser_address /*@address_line*/,
							@state,
							@city,
							@zip_code,
							@phone,
							@alternative_phone ,
							@email
						)
					END


			END
		ELSE
			BEGIN

				-- MOS 05-2021
				-- Tiene que CANCELAR si INSERTA UNA ORDEN DUPLICADA.!
				-- Es cosa de villa esto pero no hay manera de conreolar
				-- salvo que se cambie el nivel de aislamiento lo que causa interbloqueos
				-- si meli manda 1000 notificaciones al mismo tiempo y las atrapan hilos diferentes
				-- que llegan a cargar al MISMO tiempo y NO se validan las verificaciones ya que se hacen simultaneamente.
				-- Esta tabla tiene un indice UNIQUE por lo que si o si debe explorar.
				INSERT INTO tbMercadoLibre_ordersHeader_UniqueControl(comp_id,MLorder_id)
					VALUES(@comp_id,@MLorder_id)




				INSERT INTO tbMercadoLibre_ordersHeader	WITH (ROWLOCK)
				(
					comp_id,
					MLUser_Id,
					cust_id,
					mlo_firstJSON,
					mlo_lastJSON,
					ML_id,
					ML_date_created,
					ML_date_closed,
					ML_last_updated,
					mlo_shippingCost,
					mlo_transaction_amount,
					mlo_cupon_amount,
					mlo_overpaid_amount,
					mlo_total_paid_amount,
					MLorder_id,
					mlo_status,
					mlo_email,
					identificationNumber,
					identificationType,
					mlo_isPaid,
					mlo_isDelivered,
					mlo_isWithFraud,
					MLUser_identificationType,
					MLUser_identificationNumber,
					MLUser_address				,
					MLUser_state				,
					MLUser_citi					,
					MLUser_zip_code				,
					MLUser_phone				,
					MLUser_email				,
					MLUser_receiver_name		,
					MLUser_receiver_phone		,
					MLUser_alternative_phone,
					MLShippingID	,
					MLPickUpID,
					MLPickUpPerson,
					mlbra_id,
					ML_pack_id,
					mls_id,
					MLUser_first_name,
					MLUser_last_name,
					mlo_ismshops,
					mlo_mustPrintLabel
				)
				VALUES
				(
					@comp_id,
					@MLUser_Id,
					@cust_id,
					@mlo_firstJSON,
					@mlo_firstJSON,
					@ML_id,
					@ML_date_created,
					@ML_date_closed,
					@ML_last_updated,
					@mlo_shippingCost,
					@mlo_transaction_amount,
					@mlo_cupon_amount,
					@mlo_overpaid_amount,
					@mlo_total_paid_amount,
					@MLorder_id,
					@mlo_status,
					@mlo_email,
					@identificationNumber,
					@identificationType,
					@isPaid,
					@isDelivered,
					@bolHasFraudDetection,
					@identificationType,
					@identificationNumber,
					@strMLUser_address/*@address_line + ' ' + @comment*/,
					@state,
					@city,
					@zip_code,
					@phone,
					@email,
					@receiver_name,
					@receiver_phone,
					@alternative_phone	,
					CASE
						WHEN @intShippingID = -1 THEN NULL
						ELSE							@intShippingID
					END,
					@intPickUpID,
					@strPickUpPerson,
					@intMLbra_id,
					@intPack_Id,
					@mls_id	,
					@first_name,
					@last_name,
					@isFromMercadoShops	,
					@MustPrintLabel
				)
				SELECT @@IDENTITY [ID]



				--SI EXISTE EL USUARIO ACTUALIZO LOS CAMPOS
				IF EXISTS (	SELECT TOP 1 1
								FROM tbMercadoLibre_UsersData tmlud			WITH (NOLOCK)
				           		WHERE tmlud.MLUser_Id = @MLUser_Id)
					BEGIN
						UPDATE tbMercadoLibre_UsersData		WITH (rowlock)
							SET
								identificationType		= @identificationType,
								identificationNumber	= @identificationNumber,
								[address]				= @strMLUser_address/*@address_line + ' ' + @comment*/,
								[state]					= @state,
								citi					= @city,
								zip_code				= @zip_code,
								phone					= @receiver_phone,
								email					= @email
							WHERE MLUser_Id				= @MLUser_Id
					END
				ELSE
					BEGIN
						INSERT INTO tbMercadoLibre_UsersData		WITH (ROWLOCK)
						(
							MLUser_Id,
							nickname,
							identificationType,
							identificationNumber,
							[address],
							[state],
							citi,
							zip_code,
							phone,
							alternative_phone,
							email
						)
						VALUES
						(
							@MLUser_Id,
							@nickname,
							@identificationType,
							@identificationNumber,
							@strMLUser_address/*@address_line*/,
							@state,
							@city,
							@zip_code,
							@phone,
							@alternative_phone ,
							@email
						)
					END
				END

	END
