CREATE PROCEDURE [dbo].[spMercadoLibre_ordersHeader_UpdateData]
(
	@comp_id				INT,
	@mlo_id					INT,
	@mlo_lastJSON			NTEXT,
	@ML_date_closed			DATETIME,
	@mlo_shippingCost		DECIMAL(19,4),
	@mlo_transaction_amount	DECIMAL(19,4),
	@mlo_cupon_amount		DECIMAL(19,4),
	@mlo_overpaid_amount	DECIMAL(19,4),
	@mlo_total_paid_amount	DECIMAL(19,4)
)
AS
	BEGIN
		SET NOCOUNT ON

		UPDATE tbMercadoLibre_ordersHeader	WITH (ROWLOCK)
		SET
			mlo_lastJSON			.WRITE( @mlo_lastJSON,0,NULL) ,
			ML_date_closed			= @ML_date_closed,
			ML_last_updated			= GETDATE(),
			mlo_shippingCost		= @mlo_shippingCost,
			mlo_transaction_amount	= @mlo_transaction_amount,
			mlo_cupon_amount		= @mlo_cupon_amount,
			mlo_overpaid_amount		= @mlo_overpaid_amount,
			mlo_total_paid_amount	= @mlo_total_paid_amount
		WHERE	comp_id = @comp_id	AND
				mlo_id	= @mlo_id

	END
GO

CREATE PROCEDURE spMercadoLibre_OrdersHeader_UpdateDeliveryStatus
(
	@comp_id					INT,
	@mlo_id						INT,
	@mlo_ME1_deliveryStatus		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		UPDATE tbMercadoLibre_ordersHeader
		SET
			mlo_ME1_deliveryStatus = @mlo_ME1_deliveryStatus
		WHERE	comp_id = @comp_id AND
				mlo_id	= @mlo_id
	END
GO

create PROCEDURE [dbo].[spMercadoLibre_ordersHeader_UpdateIsDelivered]
(
	@comp_id				INT,
	@mlo_id					INT

)
AS
	SET NOCOUNT ON
	BEGIN

		UPDATE tbMercadoLibre_ordersHeader

		SET mlo_isDelivered = 'True'

		WHERE	comp_id = @comp_id		AND
				mlo_id	= @mlo_id
	END
GO

create PROCEDURE [dbo].[spMercadoLibre_ordersHeader_UpdateIsLabelPrinted]
(
	@comp_id				INT,
	@mlo_id					INT

)
AS
	SET NOCOUNT ON
		BEGIN

			UPDATE tbMercadoLibre_ordersHeader
			SET
				mlo_isLabelPrinted	= 'True'

				WHERE	comp_id = @comp_id AND
						mlo_id	= @mlo_id
		END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ordersHeader_UpdateIsSaleOrderGenerated]
(
	@comp_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@prof_id				INT,
	@mlo_id					INT,
	@isSaleOrderGenerated	BIT,
	@isCancelled			BIT,
	@IsCollected			BIT,
	@IsDelivered			BIT,
	@IsLabelPrinted			BIT

)
AS
SET NOCOUNT ON
BEGIN

	-- -------------------------------------------------------
	-- ACA GRABO EL LOG CON EL REGISTRO ANTERIOR
	-- -------------------------------------------------------
	-- -------------------------------------------------------
	INSERT INTO tbSecurityLog
	(
		comp_id,
		bra_id,
		user_id,
		seclog_obs_1,
		seclog_cd,
		sysCode_id,
		prof_id

	)
	SELECT
		@comp_id,
		@bra_id,
		@user_id,
		'Old Status: ' + 'Mlo_ID : ' + CONVERT(VARCHAR,tmloh.mlo_id) + ' Order_ID : ' + CONVERT(VARCHAR,tmloh.ML_id) + ' Bra_ID : ' + CONVERT(VARCHAR,@bra_id) + ' mlo_isSaleOrderGenerated : ' + CASE WHEN ISNULL(tmloh.mlo_isSaleOrderGenerated,'False') = 'True' THEN ' Generada' ELSE ' No Generada' END,
		GETDATE(),
		2700,
		@prof_id

	FROM tbMercadoLibre_ordersHeader AS tmloh
	WHERE	tmloh.comp_id	= @comp_id AND
			tmloh.mlo_id	= @mlo_id


	-- -------------------------------------------------------------------------------------------------------------------------------------
	-- Si estoy SACANDO la marca de generacion de Pedido ya efectuada y antes la tenia activa, la saco en TODAS las ordenes de ese carrito.
	-- -------------------------------------------------------------------------------------------------------------------------------------
	IF @isSaleOrderGenerated = 'False'
		BEGIN
			DECLARE @intShippingID					AS BIGINT	= NULL
			DECLARE @bitmlo_isSaleOrderGenerated	AS BIT		= 0
			SELECT  @intShippingID					= tmloh.MLShippingID,
					@bitmlo_isSaleOrderGenerated	= tmloh.mlo_isSaleOrderGenerated
				FROM tbMercadoLibre_ordersHeader AS tmloh	WITH (NOLOCK)
				WHERE	tmloh.comp_id	= @comp_id AND
						tmloh.mlo_id	= @mlo_id

			IF	@intShippingID IS NOT NULL	AND
				@intShippingID > 0			AND
				@bitmlo_isSaleOrderGenerated = 'True'
				BEGIN
					UPDATE tbMercadoLibre_ordersHeader		WITH (ROWLOCK)
						SET mlo_isSaleOrderGenerated = 0
						WHERE	comp_id			= @comp_id AND
								MLShippingID	= @intShippingID
				END
		END
	-- -------------------------------------------------------------------------------------------------------------------------------------



	UPDATE tbMercadoLibre_ordersHeader	WITH (ROWLOCK)
	SET
		mlo_isSaleOrderGenerated	= @isSaleOrderGenerated,
		mlo_isCancelled				= @isCancelled,
		mlo_isCollected				= @IsCollected,
		mlo_isDelivered				= @IsDelivered,
		mlo_isLabelPrinted			= @IsLabelPrinted

		WHERE	comp_id = @comp_id AND
				mlo_id	= @mlo_id


	IF @IsDelivered = 'True'
		BEGIN
			UPDATE tbMercadoLibre_ordersShipping	WITH (ROWLOCK)	-- MOS 06-2020 para que se pueda facturar Fulfillment que NO recibieron el estado de ENTREGADOS
				SET MLstatus = 'delivered'
				WHERE	comp_id = @comp_id AND
						mlo_id	= @mlo_id
		END



	-- -------------------------------------------------------
	-- ACA GRABO EL LOG CON EL REGISTRO ACTUAL
	-- -------------------------------------------------------
	INSERT INTO tbSecurityLog
	(
		comp_id,
		bra_id,
		user_id,
		seclog_obs_1,
		seclog_cd,
		sysCode_id,
		prof_id
	)
	SELECT
		@comp_id,
		@bra_id,
		@user_id,
		'New Status: ' + 'Mlo_ID : ' + CONVERT(VARCHAR,tmloh.mlo_id) + ' Order_ID : ' + CONVERT(VARCHAR,tmloh.ML_id) + ' Bra_ID : ' + CONVERT(VARCHAR,@bra_id) + ' mlo_isSaleOrderGenerated : ' + CASE WHEN ISNULL(tmloh.mlo_isSaleOrderGenerated,'False') = 'True' THEN ' Generada' ELSE ' No Generada' END,
		GETDATE(),
		2700,
		@prof_id

	FROM tbMercadoLibre_ordersHeader AS tmloh
	WHERE	tmloh.comp_id	= @comp_id AND
			tmloh.mlo_id	= @mlo_id
	-- -------------------------------------------------------

END



GO


