CREATE PROCEDURE [dbo].[spMercadoLibre_ordersMessages_Getdata4Customer]
(
	@comp_id		INT,
	@lang_id        INT,
	@bra_id			INT,
	@prof_id		INT,
	@user_id		INT,
	@mlme_id		INT, -- Si viene de Mensajes Post Venta, si es <> 0 entonces mlqat_id = 0
	@mlqat_id		INT  -- Si viene de Preguntas y respuestas, si es <> 0 entonces mlme_id = 0
)
AS


	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------
		-- TESTING
		-- --------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id        INT,
				@bra_id			INT,
				@prof_id		INT,
				@user_id		INT,
				@mlme_id		INT, -- Si viene de Mensajes Post Venta, si es <> 0 entonces mlqat_id = 0
				@mlqat_id		INT  -- Si viene de Preguntas y respuestas, si es <> 0 entonces mlme_id = 0
			SELECT
				@comp_id		= 1,
				@mlme_id		= 0,
				@user_id		= 1 ,
				@lang_id		= 2,
				@mlqat_id		= 70
		*/
		-- --------------------------------------

		DECLARE @lMLUser_Id AS INT

		IF @mlme_id <> 0
			--Mensajes Post Venta
			BEGIN
				SET @lMLUser_Id = (SELECT
									tmlom.MLUser_id
									FROM tbMercadoLibre_ordersMessages			tmlom	WITH (NOLOCK)
									WHERE	tmlom.comp_id = @comp_id AND
											tmlom.mlme_id = @mlme_id)

			END
		ELSE
			--Preguntas y Respuestas
			BEGIN
				SET @lMLUser_Id = (SELECT
									tmlqaa.MLUser_id
				                    FROM tbMercadoLibre_QuestionsAndAnswers		tmlqaa	WITH (NOLOCK)
									WHERE	tmlqaa.comp_id	= @comp_id AND
											tmlqaa.mlpqa_id = @mlqat_id)
			END


		--Movimientos ya hechos
		SELECT
			tct.ct_date																									[ct_date],
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)							[document],
			ti.item_desc																								[item_desc],
			ISNULL(CONVERT(VARCHAR,tc.cust_id)+ '-' + CONVERT(VARCHAR,tc.cust_name),'')									[cust_name],
			ISNULL(tc.cust_address	,'')																				[cust_address],
			ISNULL(tc.cust_city,'')																						[cust_city],
			ISNULL(tc.cust_phone1,'')																					[cust_phone1],
			ISNULL(tc.cust_email,'')																					[cust_email]

			FROM	tbCustomer										tc					WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions						tct					WITH (NOLOCK)
			ON	tct.comp_id		= tc.comp_id				AND
				tct.cust_id		= tc.cust_id

			INNER JOIN dbo.vwCommercialTransactions_forSales		vwct				WITH (NOLOCK)
			on  tct.comp_id			= vwct.comp_id			AND
				tct.bra_id			= vwct.bra_id			AND
				tct.ct_transaction	= vwct.ct_transaction

			INNER JOIN tbUsers4BranchFilter							vubf				WITH (NOLOCK)
			ON	vubf.comp_id		= tct.comp_id			AND
				vubf.bra_id			= tct.bra_id			AND
				vubf.[user_id]		= @user_id

			INNER JOIN tbItemTransactions							tit					WITH (NOLOCK)
			ON	tit.comp_id			= tct.comp_id			AND
				tit.bra_id			= tct.bra_id			AND
				tit.ct_transaction	= tct.ct_transaction

			INNER JOIN tbItem										ti					WITH (NOLOCK)
			ON	ti.comp_id			= tit.comp_id			AND
				ti.item_id			= tit.item_id


			WHERE tc.comp_id		= @comp_id				AND
				  tc.MLUser_Id		= @lMLUser_Id



		UNION ALL

		--Pedidos
		SELECT
			tsoh.soh_deliveryDate														[ct_date],
			'# ' + CONVERT(VARCHAR,tsoh.soh_id) + '-' + CONVERT(VARCHAR,tsoh.soh_id)	[document],
			ti.item_desc																[item_desc],
			ISNULL(CONVERT(VARCHAR,tc.cust_id)+ '-' + CONVERT(VARCHAR,tc.cust_name),'')	[cust_name],
			ISNULL(tc.cust_address	,'')												[cust_address],
			ISNULL(tc.cust_city,'')														[cust_city],
			ISNULL(tc.cust_phone1,'')													[cust_phone1],
			ISNULL(tc.cust_email,'')													[cust_email]

			FROM	tbCustomer										tc					WITH (NOLOCK)

			INNER JOIN tbSaleOrderHeader							tsoh				WITH (NOLOCK)
			ON	tsoh.comp_id	= tc.comp_id				AND
				tsoh.cust_id	= tc.cust_id

			INNER JOIN tbSaleOrderDetail							tsod				WITH (NOLOCK)
			ON	tsod.comp_id	= tsoh.comp_id				AND
				tsod.bra_id		= tsoh.bra_id				AND
				tsod.soh_id		= tsoh.soh_id

			INNER JOIN tbItem										ti					WITH (NOLOCK)
			ON	ti.comp_id		= tsod.comp_id				AND
				ti.item_id		= tsod.item_id

			INNER JOIN tbDocumentsFile								tdf					WITH (NOLOCK)
			ON	tdf.comp_id		= tsoh.comp_id				AND
				tdf.bra_id		= tsoh.bra_id				AND
				tdf.df_id		= tsoh.df_id				AND
				tdf.sd_id		= 1


			WHERE tc.comp_id		= @comp_id				AND
				  tc.MLUser_Id		= @lMLUser_Id



		ORDER BY [ct_date]

	END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_ordersMessages_getDataByFilters]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@option_status		INT,-- -1 : Todos, 1 : Pendientes , 2 : Respondidas
	@cust_id			INT,
	@soh_bra_id			INT,
	@soh_id				INT,
	@nickname			NVARCHAR(200),
	@MLUser_Id			BIGINT,
	@datefrom			DATETIME,
	@dateto				DATETIME
)
AS


	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- --------------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------------
		/*
			DECLARE
					@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@prof_id			INT,
					@user_id			INT,
					@option_status		INT,-- -1 : Todos, 1 : Pendientes , 2 : Respondidas
					@cust_id			INT,
					@soh_bra_id			INT,
					@soh_id				INT,
					@nickname			NVARCHAR(200),
					@MLUser_Id			BIGINT,
					@datefrom			DATETIME,
					@dateto				DATETIME
			SELECT
					@comp_id			=  1,
					@lang_id			=  2,
					@bra_id				= 1,
					@prof_id			= 1,
					@user_id			= 3,
					@option_status		= -1,
					@cust_id			= 24697,
					@soh_bra_id			= 1,
					@soh_id				= 34068,
					@datefrom			= '2017-10-01',
					@dateto				= '2017-10-31',
					@MLUser_Id			= 0,
					@nickname			= ''
		*/
		-- --------------------------------------------------------------------


		SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


		SELECT
			''															[1], -- RESPONDER
			''															[2], -- BORRAR
			tc.cust_name												[cust_name],
			tdf.df_desc + '(' + convert(nvarchar(10),tsoh.bra_id) + '-'+ convert(nvarchar(10),tsoh.soh_id) +')'	[doc_Number],
			tmlom.MLdate												[date],
			tmlom.MLsubject												[MLsubject],
			tmlom.MLtext												[MLtext],
			tmlud.nickname												[Nickname],
			tovisReaded.optval_desc										[isReaded],
			tuReaded.user_lastname + ', ' + tuReaded.user_firstname		[user_nameisReaded],
			tovisAnswered.optval_desc									[isAnswered],
			tuAnswered.user_lastname + ', ' + tuAnswered.user_firstname	[user_nameisanswered],
			tsoh.soh_observation1,

			-- -----------------------------------------------------------------------------
			-- ATENCION!!!!!!
			-- No poner nada detras de este campo ya que se hacen controles de Count en la pagina 	wfmMercadoLibre_QuestionsAndAnswers
			-- -----------------------------------------------------------------------------
			ISNULL(tmlom.mlme_isFromML,'False')							[isFromML],		-- Count - 2
			tmlom.mlme_id												[ID]			-- Count - 1

			FROM	tbMercadoLibre_ordersMessages				tmlom			WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_UsersData					tmlud			WITH (NOLOCK)
				ON	tmlud.MLUser_Id			= tmlom.MLUser_Id
			LEFT JOIN tbMercadoLibre_ordersHeader				tmloh			WITH (NOLOCK)
				ON	tmloh.comp_id			= tmlom.comp_id		AND
					tmloh.mlo_id			= tmlom.mlo_id
			LEFT JOIN tbSaleOrderHeader							tsoh
				ON	tsoh.comp_id			= tmloh.comp_id		AND
					tsoh.mlo_id				= tmloh.mlo_id
			LEFT JOIN tbDocumentsFile						tdf			WITH (NOLOCK)
				ON	tdf.comp_id		= tsoh.comp_id AND
					tdf.df_id		= tsoh.df_id
			LEFT JOIN tbCustomer								tc				WITH (NOLOCK)
				ON	tc.comp_id				= tsoh.comp_id		AND
					tc.cust_id				= tsoh.cust_id
			INNER JOIN tbsysOptionsValues						tovisReaded		WITH (NOLOCK)
				ON tovisReaded.lang_id		= @lang_id			AND
				   tovisReaded.optval_class = 17				AND
				   tovisReaded.optval_id	= isnull(tmlom.mlme_isReaded,'False')
			INNER JOIN tbsysOptionsValues						tovisAnswered	WITH (NOLOCK)
				ON tovisAnswered.lang_id	= @lang_id			AND
				   tovisAnswered.optval_class = 17				AND
				   tovisAnswered.optval_id	= isnull(tmlom.mlme_isAnswered,'False')
			INNER JOIN tbsysOptionsValues						tovisFromML		WITH (NOLOCK)
				ON tovisFromML.lang_id		= @lang_id			AND
				   tovisFromML.optval_class = 17				AND
				   tovisFromML.optval_id	= 	isnull(tmlom.mlme_isFromML,'False')
			LEFT JOIN tbUser									tuReaded				WITH (NOLOCK)
				ON	tuReaded.[user_id]		= tmlom.[user_id]
			LEFT JOIN tbUser									tuAnswered				WITH (NOLOCK)
				ON	tuAnswered.[user_id]	= tmlom.user_id_answer
			WHERE	tmlom.comp_id		= @comp_id											AND
					(tmlom.MLdate		BETWEEN	   @datefrom		AND		@dateto)		AND
					(@cust_id			= -1	OR tsoh.cust_id			= @cust_id)		AND
					(@MLUser_Id			= 0		OR tmlom.MLUser_Id			= @MLUser_Id)	AND
					(@nickname			= ''	OR tmlud.nickname			= @nickname)	AND
					(
						(
							@soh_Bra_id = 0 AND
							@soh_id		= 0
						)
							OR
						(
							tsoh.bra_id = @soh_Bra_id AND
							tsoh.soh_id = @soh_id
						)
					)
																							AND

					CASE
						WHEN @option_status = -1														THEN 1	--TODOS
						WHEN @option_status = 1 AND ISNULL(tmlom.mlme_isAnswered,'False')	= 'False'
												AND mlme_isFromML = 'True'								THEN 1	--NO RESPONDIDOS
						WHEN @option_status = 2 AND ISNULL(tmlom.mlme_isReaded,'False')		= 'False'
												AND mlme_isFromML = 'True'								THEN 1	--NO LEIDOS
						WHEN @option_status = 3 AND tmlom.mlme_isAnswered					= 'True'	THEN 1	--RESPONDIDOS
						WHEN @option_status = 4 AND tmlom.mlme_isReaded						= 'True'	THEN 1	--LEIDOS
					END = 1



					-- que clase de MIERDA es esto ?????????????????????????????????????????????????????????
					--(
					--	@option_status = -1														OR	--TODOS
					--	@option_status = 1 AND ISNULL(tmlom.mlme_isAnswered,'False') = 'False'	OR	--NO RESPONDIDOS
					--	@option_status = 2 AND ISNULL(tmlom.mlme_isReaded,'False') = 'False'	OR	--NO LEIDOS
					--	@option_status = 3 AND tmlom.mlme_isAnswered = 'True'					OR  --RESPONDIDOS
					--	@option_status = 4 AND tmlom.mlme_isReaded = 'True'							--LEIDOS
					--)


			ORDER BY tmlom.MLdate

	END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_ordersMessages_GetDataById]
(
	@comp_id		INT,
	@mlme_id		INT

)
AS


BEGIN
SET NOCOUNT ON

/*

DECLARE @comp_id		INT,
	@mlme_id		INT


SELECT @comp_id		= 1 ,
	@mlme_id		=63
*/

		SELECT
			tmlom.comp_id,
			tmlom.mlme_id,
			tmlom.MLmessage_id,
			tmlom.MLdate,
			tmlom.MLUser_id,
			tmlom.MLsubject,
			tmlom.MLtext,
			tmlom.mlme_JSON,
			tmlom.mlo_id,
			tmlom.MLmoderation_status,
			tmlom.mlme_isReaded,
			tmlom.mlme_isAnswered,
			tmlom.[user_id],
			tmlom.user_id_answer,
			tmlom.mlme_answer_cd,
			tmlom.mlme_id_related,
			tmlom.mlme_isFromML,
			tmlod.mlp_id,
			tmlud.nickname

			FROM tbMercadoLibre_ordersMessages				tmlom	WITH (NOLOCK)

			INNER JOIN tbMercadoLibre_UsersData				tmlud	WITH (NOLOCK)
			ON	tmlud.MLUser_Id		= tmlom.MLUser_id

			LEFT JOIN tbMercadoLibre_ordersHeader			tmloh	WITH (NOLOCK)
			ON	tmloh.comp_id		= tmlom.comp_id AND
				tmloh.mlo_id		= tmlom.mlo_id

			LEFT JOIN tbMercadoLibre_ordersDetail			tmlod	WITH (NOLOCK)
			ON	tmlod.comp_id		= tmloh.comp_id AND
				tmlod.mlo_id		= tmloh.mlo_id

			WHERE	tmlom.comp_id	= @comp_id AND
					tmlom.mlme_id	= @mlme_id


END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_ordersMessages_GetMessageByUser]
(
	@comp_id			INT,
	@MLUser_Id			bigint
)

as


	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------
		-- TESTING
		-- --------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@MLUser_Id			bigint
			SELECT
				@comp_id		= 1,
				@MLUser_Id		= 266710754
		*/
		-- --------------------------------------

		SELECT
			tmlom.MLsubject						[MLsubject],
			tmlom.MLtext						[MLtext] ,
			CASE
				WHEN	tmlom.[user_id] = tmls.[user_id] THEN	1
				ELSE											0
			END									[isFromMLUser]
			FROM tbMercadoLibre_ordersMessages			tmlom		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ordersDetail		tmloh		WITH (NOLOCK)
				ON	tmloh.comp_id	= tmlom.comp_id AND
					tmloh.mlo_id	= tmlom.mlo_id
			INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
				ON	tmlip.comp_id	= tmloh.comp_id AND
					tmlip.mlp_id	= tmloh.mlp_id
			INNER JOIN tbMercadoLibre_Stores			tmls		WITH (NOLOCK)
				ON	tmls.comp_id	= tmlip.comp_id AND
					tmls.mls_id		= tmlip.mls_id
			WHERE	tmlom.comp_id	= @comp_id			AND
					tmlom.MLUser_id	= @MLUser_Id
			ORDER BY tmlom.mlme_id	DESC

	END
GO

CREATE PROCEDURE spMercadoLibre_ordersMessages_GetMessageHistoryByOrder
(
	@comp_id	INT,
	@mlo_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------
		-- TESTING
		-- --------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlo_id		INT
			SELECT
				@comp_id	= 1,
				@mlo_id		= 31
		*/
		-- --------------------------------------

		SELECT
			tmlom.MLdate,
			ISNULL(tmlom.MLsubject,'')						[MLsubject],
			ISNULL(tmlom.MLtext,'')							[MLtext],
			'#' + ' ' + CONVERT(VARCHAR,tmloh.MLorder_id)	[MLorder_id],
			tmlom.mlme_id									[ID]
		FROM tbMercadoLibre_ordersMessages			tmlom
			INNER JOIN tbMercadoLibre_ordersHeader	tmloh
			ON	tmloh.comp_id	= tmlom.comp_id		AND
				tmloh.mlo_id	= tmlom.mlo_id
		WHERE	tmlom.comp_id	= @comp_id			AND
				tmlom.mlo_id	= @mlo_id

		ORDER BY tmlom.mlme_id	DESC

	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_ordersMessages_InsertData]
(

	@comp_id									INT,
	@MLmessage_id								NVARCHAR(50),
	@MLdate										DATETIME,
	@MLUser_id									INT,
	@MLsubject									NVARCHAR(300),
	@MLtext										NVARCHAR(4000),
	@mlme_JSON									NVARCHAR(4000),
	@mlo_id										INT,
	@MLmoderation_status						NVARCHAR(50),
	@mlme_isFromML								BIT,
	@user_id									INT,
	@mlme_id_related							INT,
	@return_value								AS INT	OUTPUT

)
AS
BEGIN


	SET NOCOUNT ON


	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
		DECLARE
			@comp_id						INT,
			@MLmessage_id					NVARCHAR(50),
			@MLdate							DATETIME,
			@MLUser_id						INT,
			@MLsubject						NVARCHAR(300),
			@MLtext							NVARCHAR(4000),
			@mlme_JSON						NVARCHAR(4000),
			@mlo_id							INT,
			@MLmoderation_status			NVARCHAR(50),
			@return_value					AS INT	OUTPUT
		SELECT
			@comp_id						=1
	*/
	-- ------------------------------------------------------
	SET @return_value	= 0
	DECLARE @intMLUser_IdOfStore AS BIGINT


	-- Hay veces que estos HDP mandan lo mismo 1000 veces.
	IF EXISTS(	SELECT TOP 1 1
	          		FROM tbMercadoLibre_ordersMessages WITH (NOLOCK)
	          		WHERE	comp_id			= @comp_id AND
	          				MLmessage_id	= @MLmessage_id
			)
		BEGIN
			RETURN
		END



	IF @mlme_id_related = -1 SET @mlme_id_related = NULL


	SELECT	@intMLUser_IdOfStore = tmls.MLUser_Id
		FROM tbMercadoLibre_ordersDetail tmlod				WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
			ON	tmlip.comp_id		= tmlod.comp_id AND
				tmlip.mlp_id		= tmlod.mlp_id
		INNER JOIN tbMercadoLibre_Stores tmls				WITH (NOLOCK)
			ON	tmls.comp_id		= tmlip.comp_id AND
				tmls.mls_id			= tmlip.mls_id
		WHERE	tmlod.comp_id		= @comp_id AND
				tmlod.mlo_id		= @mlo_id





	INSERT INTO tbMercadoLibre_ordersMessages
	(
		comp_id,
		-- mlme_id -- this column value is auto-generated,
		MLmessage_id,
		MLdate,
		MLUser_id,
		MLsubject,
		MLtext,
		mlme_JSON,
		mlo_id,
		MLmoderation_status,
		mlme_isFromML,
		mlme_isReaded,
		mlme_isAnswered,
		[user_id],
		mlme_answer_cd,
		mlme_id_related
	)
	VALUES
	(
		@comp_id,
		-- mlme_id -- this column value is auto-generated,
		@MLmessage_id,
		@MLdate,
		@MLUser_id,
		@MLsubject,
		@MLtext,
		@mlme_JSON,
		@mlo_id,
		@MLmoderation_status,
		@mlme_isFromML,
		CASE
			WHEN @MLUser_id = @intMLUser_IdOfStore THEN 'True'
			ELSE										'False'
		END,
		CASE
			WHEN @MLUser_id = @intMLUser_IdOfStore THEN 'True'
			ELSE										'False'
		END,
		@user_id,
		GETDATE(),
		@mlme_id_related

	)

	SET @return_value = @@IDENTITY

END
GO




CREATE PROCEDURE [dbo].[spMercadoLibre_ordersMessages_InsertData_4WorkFlow]
(
	@comp_id				INT,
	@MLmessage_id			NVARCHAR(50),
	@MLdate					DATETIME,
	@MLUser_id				INT,
	@MLsubject				NVARCHAR(300),
	@MLtext					NVARCHAR(4000),
	@mlme_JSON				NVARCHAR(4000),
	@mlo_id					INT,
	@MLmoderation_status	NVARCHAR(50),
	@mlme_isFromML			BIT,
	@user_id				INT,
	@mlme_id_related		INT,
	@strURL					NVARCHAR(4000)
)
AS

	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------
		/*
			DECLARE
				@comp_id									INT,
				@MLmessage_id								NVARCHAR(50),
				@MLdate										DATETIME,
				@MLUser_id									INT,
				@MLsubject									NVARCHAR(300),
				@MLtext										NVARCHAR(4000),
				@mlme_JSON									NVARCHAR(4000),
				@mlo_id										INT,
				@MLmoderation_status						NVARCHAR(50),
				@mlme_isFromML								BIT,
				@user_id									INT,
				@mlme_id_related							INT
		*/
		-- --------------------------------------------------------------

		DECLARE @nickname		AS NVARCHAR(100)	= ''
		DECLARE @user_id_local	AS INT				= -1
		DECLARE @bra_id			AS INT				= -1
		DECLARE @mlOrderID		AS BIGINT			=  0

		SELECT TOP 1
			@bra_id						= tmls.bra_id,
			@user_id_local				= tmls.[user_id],
			@nickname					= tmlud.nickname,
			@mlOrderID					= tmloh2.MLorder_id
			FROM tbMercadoLibre_ordersDetail tmloh					WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ordersHeader tmloh2			WITH (NOLOCK)
				ON	tmloh2.comp_id		= tmloh.comp_id AND
					tmloh2.mlo_id		= tmloh.mlo_id
			INNER JOIN tbMercadoLibre_UsersData tmlud				WITH (NOLOCK)
				ON tmlud.MLUser_Id      = tmloh2.MLUser_Id
			INNER JOIN tbMercadoLibre_ItemsPublicados tmlip			WITH (NOLOCK)
				ON	tmlip.comp_id		= tmloh.comp_id AND
					tmlip.mlp_id		= tmloh.mlp_id
			INNER JOIN tbMercadoLibre_Stores tmls					WITH (NOLOCK)
				ON	tmls.comp_id		= tmlip.comp_id AND
					tmls.mls_id			= tmlip.mls_id
			WHERE	tmloh.comp_id		= @comp_id		AND
					tmloh.mlo_id		= @mlo_id





			-- MOS 10-2022: esto es DELIRANTE, NO SE A QUIEN CUARNOS SE LE OCURRIÓ HACER SEMEJANTE BARRABASADA!!!!!!!!!!!!!!!!!!!!
			-- Lo cambie x un campo en el archivo de PERFILEWS.  despues yo me terngo que bancar a mr DICIENDO QUE SOMOS UNA MANGA DE PELOTUDOS!!!!!!!
			--
			--SI HAY AL MENOS UN PERFIL QUE TENGA PUESTO QUE NO SE CARGUEN LOS MENSAJES DE RECLAMOS EN LA WORKFLOW, NO HACE NADA, CASO CONTRARIO GRABA SIEMRE
			--IF (SELECT COUNT(*) FROM tbControlProfiles AS tcp1 WITH (NOLOCK) WHERE tcp1.comp_id = @comp_id AND tcp1.ctrl_id = 5857 ) = 0
			--	BEGIN

					INSERT INTO tbWorkflow	WITH (ROWLOCK)
					(
						comp_id,
						bra_id,
						wf_type,
						wf_isProcessed,
						user_id_from,
						user_id_assigned,
						user_id_processed,
						prof_id_assigned,
						wf_dateOfAssigned,
						wf_dateOfProcessing,
						wf_link,
						wf_message1,
						wf_message2,
						wf_message3,
						wf_message4,
						wf_htmlTop,
						wf_htmlBody,
						wf_html_Bottom,
						mlo_id
					)
					SELECT
						@comp_id,
						NULL,
						860,
						'False',
						NULL,
						@user_id,
						NULL,
						tp.prof_id,	-- MOS 10-2022
						GETDATE(),
						NULL,
						@strURL,
						'MercadoLibre: Mensaje PosVenta:' + CONVERT(NVARCHAR(50),@MLmessage_id),
						'NickName:' + @nickname ,
						'Order#' + CONVERT(NVARCHAR(50),@mlOrderID),
						@MLtext,
						'',
						'',
						'',
						@mlo_id
						FROM tbProfile tp	WITH (NOLOCK)			-- MOS 10-2022: Como corresponde...
						WHERE	tp.comp_id							= @comp_id AND
								tp.prof_workFlow4MLordersMessages	= 1

				--END


	END
GO

