CREATE procedure [dbo].[spMercadoLibre_ordersMessages_UpdateData]
(
	@comp_id				INT,
	@mlme_id				INT,
	@user_id				INT,
	@mlpqa_answer			NVARCHAR(4000)

)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'

		EXEC spMercadoLibre_ordersMessages_UpdateData_OnlyReaded @comp_id,@mlme_id,@user_id,@mlpqa_answer


		UPDATE tbMercadoLibre_ordersMessages	WITH (ROWLOCK)
		SET mlme_isAnswered = 'True',
			user_id_answer  = @user_id

		WHERE comp_id		= @comp_id AND
			  mlme_id		= @mlme_id





	END
