CREATE PROCEDURE [dbo].[spMercadoLibre_ordersPayments_InsertData]
(
	@comp_id				INT,
	@mlo_id					INT,
	@mlop_total				DECIMAL(19,4),
	@curr_id				INT,
	@mlop_date				DATETIME,
	@mlop_concept			NVARCHAR(1000),
	@mlop_activation_uri	NVARCHAR(1000),
	@mlop_isPending			BIT,
	@MLpaymentsID			BIGINT,
	@MLstatus				NVARCHAR(30),
	@MLstatus_code			NVARCHAR(10),
	@MLstatus_detail		NCHAR(10),
	@MLtransaction_amount	DECIMAL(19,4),
	@MLshipping_cost		DECIMAL(19,4),
	@MLcoupon_amount		DECIMAL(19,4),
	@MLoverpaid_amount		DECIMAL(19,4),
	@MLtotal_paid_amount	DECIMAL(19,4),
	@MLinstallment_amount	DECIMAL(19,4),
	@mlop_JSON				NVARCHAR(4000),
	@MLinstallments			INT,
	@MLreason				NVARCHAR(1000),
	@MLoperation_type		NVARCHAR(100),
	@MLtaxes_amount			DECIMAL(19,4)
)
AS
	BEGIN
		SET NOCOUNT ON


		-- -----------------------------------------------------------------------------
		-- MOS 01-2023 para que tome la moneda de la tienda pero no explote si x algun motivo no la tiene definida...
		-- -----------------------------------------------------------------------------
		SELECT @curr_id = ISNULL(tmls.curr_id,1)
			FROM tbMercadoLibre_ordersHeader AS tmloh	WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_Stores AS tmls	WITH (NOLOCK)
				ON  tmls.comp_id	= tmloh.comp_id AND
					tmls.mls_id		= tmloh.mls_id
			WHERE	tmloh.comp_id	= @comp_id		AND
					tmloh.mlo_id	= @mlo_id

		SELECT @curr_id = ISNULL(@curr_id,1)
		-- -----------------------------------------------------------------------------


		INSERT INTO tbMercadoLibre_ordersPayments	WITH (ROWLOCK)
		(
			comp_id,
			mlo_id,
			-- mlop_id -- this column value is auto-generated,
			mlop_total,
			curr_id,
			mlop_date,
			mlop_concept,
			mlop_activation_uri,
			mlop_isPending,
			MLpaymentsID,
			MLstatus,
			MLstatus_code,
			MLstatus_detail,
			MLtransaction_amount,
			MLshipping_cost,
			MLcoupon_amount,
			MLoverpaid_amount,
			MLtotal_paid_amount,
			MLinstallment_amount,
			mlop_JSON,
			MLinstallments,
			MLreason,
			MLoperation_type,
			MLtaxes_amount
		)
		VALUES
		(
			@comp_id,
			@mlo_id,
			@mlop_total,
			@curr_id,
			@mlop_date,
			@mlop_concept,
			@mlop_activation_uri,
			@mlop_isPending,
			@MLpaymentsID,
			@MLstatus,
			@MLstatus_code,
			@MLstatus_detail,
			@MLtransaction_amount,
			@MLshipping_cost,
			@MLcoupon_amount,
			@MLoverpaid_amount,
			@MLtotal_paid_amount,
			@MLinstallment_amount,
			@mlop_JSON,
			@MLinstallments,
			@MLreason,
			@MLoperation_type,
			@MLtaxes_amount
		)

	END
GO

