			@curr_id,
			@mlop_date,
			@mlop_concept,
			@mlop_activation_uri,
			@mlop_isPending
		)

	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_ordersPaymets_GetDataByMLO_ID]
(
	@comp_id	INT,
	@mlo_id		BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlo_id		BIGINT
			SELECT
				@comp_id	= 1,
				@mlo_id		= 21
		*/
		-- ------------------------------------------------

		SELECT
			tmlop.mlo_id,
			tmlop.mlop_total,
			tc.curr_symbol							[curr_id],
			tmlop.mlop_date,
			tmlop.mlop_concept,
			tmlop.mlop_activation_uri,
			--tmlop.mlop_isPending,   MOS 08-2022: para que no pregunten . . .
			tmlop.MLstatus,
			tmlop.MLstatus_code,
			tmlop.MLstatus_detail,
			tmlop.MLtransaction_amount,
			tmlop.MLshipping_cost,
			tmlop.MLcoupon_amount,
			tmlop.MLoverpaid_amount,
			tmlop.MLtotal_paid_amount,
			tmlop.MLinstallment_amount,
			tmlop.MLdate_last_modified,
			tmlop.MLinstallments,
			tmlop.MLreason,
			tmlop.MLoperation_type
			FROM tbMercadoLibre_ordersPayments			tmlop
			INNER JOIN tbsysCurrency					tc
				ON tc.curr_id		= tmlop.curr_id
			WHERE	tmlop.comp_id	= @comp_id			AND
					tmlop.mlo_id	= @mlo_id

	END
GO

