CREATE PROCEDURE [dbo].[spMercadoLibre_ordersShipping_GetDataByMLO_ID]
(
	@comp_id	INT,
	@mlo_id		BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlo_id		BIGINT
			SELECT
				@comp_id	= 1,
				@mlo_id		= 21
		*/
		-- ------------------------------------------------

		SELECT
			tmlos.MLshippingID,
			tmlos.MLshipment_type,
			tmlos.MLshipping_mode,
			tmlos.MLcost,
			tmlos.MLlogistic_type,
			tmlos.MLstatus,
			tmlos.MLestimated_handling_limit,
			tmlos.MLestimated_delivery_final,
			tmlos.MLestimated_delivery_limit,
			tmlos.MLstreet_name,
			tmlos.MLstreet_number,
			tmlos.MLcomment,
			tmlos.MLzip_code,
			tmlos.MLreceiver_name,
			tmlos.MLreceiver_phone,
			ISNULL(tmlos.MLLaben_ZPL2,'')				[MLLaben_ZPL2],
			ISNULL(tmloh.ML_pack_id,-1)					[ML_pack_id]
			FROM tbMercadoLibre_ordersShipping		tmlos	WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ordersHeader  tmloh	WITH (NOLOCK)
				ON	tmloh.comp_id	= tmlos.comp_id AND
					tmloh.mlo_id	= tmlos.mlo_id
			WHERE	tmlos.comp_id	= @comp_id AND
					tmlos.mlo_id	= @mlo_id

	END
GO

