CREATE PROCEDURE [dbo].[spMercadoLibre_ordersShippingInsertData]
(
    @comp_id                                 INT
   ,@mlo_id                                  INT
   ,@MLshippingID                            BIGINT
   ,@MLshipment_type                         NVARCHAR(50)
   ,@MLshipping_mode                         NVARCHAR(20)
   ,@mlm_JSON                                NVARCHAR(4000)
   ,@MLcost                                  DECIMAL(19 ,4)
   ,@MLlogistic_type                         NVARCHAR(30)
   ,@MLstatus                                NVARCHAR(50)
   ,@MLestimated_handling_limit              DATETIME
   ,@MLestimated_delivery_final              DATETIME
   ,@MLestimated_delivery_limit              DATETIME
   ,@MLreceiver_address                      NVARCHAR(4000)
   ,@MLstreet_name                           NVARCHAR(1000)
   ,@MLstreet_number                         NVARCHAR(1000)
   ,@MLcomment                               NVARCHAR(1000)
   ,@MLzip_code                              NVARCHAR(1000)
   ,@MLcity_name                             NVARCHAR(1000)
   ,@MLstate_name                            NVARCHAR(1000)
   ,@MLcity_id                               NVARCHAR(1000)
   ,@MLstate_id                              NVARCHAR(1000)
   ,@MLconuntry_name                         NVARCHAR(1000)
   ,@MLreceiver_name                         NVARCHAR(1000)
   ,@MLreceiver_phone                        NVARCHAR(1000)
   ,@MLLabel_PDF                             IMAGE
   ,@MLLaben_ZPL2                            IMAGE
   ,@MLlist_cost                             DECIMAL(19 ,4)
   ,@MLdelivery_type                         NVARCHAR(50)
   ,@MLshipping_method_id                    INT
   ,@MLtracking_number                       NVARCHAR(100)
   ,@MLShippmentCost4Buyer                   DECIMAL(19 ,4)
   ,@MLShippmentCost4Seller                  DECIMAL(19 ,4)
   ,@MLShippmentGrossAmount                  DECIMAL(19 ,4)
   ,@MLfulfilled                             BIT
   ,@MLSelfService                           BIT
   ,@ML_logistic_type                        NVARCHAR(30)
   ,@ML_tracking_method                      NVARCHAR(50)
   ,@ML_date_first_printed                   DATETIME
   ,@ML_base_cost                            DECIMAL(15 ,2)
   ,@ML_estimated_delivery_time_date         AS DATETIME
   ,@ML_estimated_delivery_time_shipping     AS INT
   ,@ColectaDateTime                         DATETIME,
   @MLTurbo									 BIT
)

-- MOS 03-2024: X Q MIERDA las COMAS en CUALQUIER LADO si SE SABE que VAN A LA DERECHA ???????????????????????????????????????????
AS
BEGIN
    SET NOCOUNT ON


    IF YEAR(@ML_date_first_printed)<2000
    BEGIN
        SET @ML_date_first_printed = NULL
    END

    DECLARE @bitIsInserted AS BIT='True'

    SELECT @MLLaben_ZPL2 = CASE
                                WHEN @MLLaben_ZPL2 IS NULL THEN tmlos.MLLaben_ZPL2
                                ELSE @MLLaben_ZPL2
                           END
          ,@bitIsInserted = 'False'
		FROM   tbMercadoLibre_ordersShipping AS tmlos WITH (NOLOCK)
		WHERE  tmlos.comp_id = @comp_id
			   AND tmlos.mlo_id = @mlo_id



    IF @bitIsInserted='True'
		BEGIN
			INSERT INTO tbMercadoLibre_ordersShipping WITH
			  (
				ROWLOCK
			  )(
				   comp_id
				  ,mlo_id
				  ,MLshippingID
				  ,MLshipment_type
				  ,MLshipping_mode
				  ,mlm_JSON
				  ,MLcost
				  ,MLlogistic_type
				  ,MLstatus
				  ,MLestimated_handling_limit
				  ,MLestimated_delivery_final
				  ,MLestimated_delivery_limit
				  ,MLreceiver_address
				  ,MLstreet_name
				  ,MLstreet_number
				  ,MLcomment
				  ,MLzip_code
				  ,MLcity_name
				  ,MLstate_name
				  ,MLcity_id
				  ,MLstate_id
				  ,MLconuntry_name
				  ,MLreceiver_name
				  ,MLreceiver_phone
				  ,MLLabel_PDF
				  ,MLLaben_ZPL2
				  ,MLlist_cost
				  ,MLdelivery_type
				  ,MLshipping_method_id
				  ,MLtracking_number
				  ,MLShippmentCost4Buyer
				  ,MLShippmentCost4Seller
				  ,MLShippmentGrossAmount
				  ,MLfulfilled
				  ,MLSelf_Service
				  ,ML_logistic_type
				  ,ML_tracking_method
				  ,ML_date_first_printed
				  ,ML_base_cost
				  ,ML_estimated_delivery_time_date
				  ,ML_estimated_delivery_time_shipping
				  ,mlos_lastUpdate
				  ,MLShippmentColectaDayTime
			   )
			VALUES
			  (
				@comp_id
			   ,@mlo_id
			   ,@MLshippingID
			   ,@MLshipment_type
			   ,@MLshipping_mode
			   ,@mlm_JSON
			   ,@MLcost
			   ,@MLlogistic_type
			   ,@MLstatus
			   ,@MLestimated_handling_limit
			   ,@MLestimated_delivery_final
			   ,@MLestimated_delivery_limit
			   ,@MLreceiver_address
			   ,@MLstreet_name
			   ,@MLstreet_number
			   ,@MLcomment
			   ,@MLzip_code
			   ,@MLcity_name
			   ,@MLstate_name
			   ,@MLcity_id
			   ,@MLstate_id
			   ,@MLconuntry_name
			   ,@MLreceiver_name
			   ,@MLreceiver_phone
			   ,@MLLabel_PDF
			   ,@MLLaben_ZPL2
			   ,@MLlist_cost
			   ,@MLdelivery_type
			   ,@MLshipping_method_id
			   ,@MLtracking_number
			   ,@MLShippmentCost4Buyer
			   ,@MLShippmentCost4Seller
			   ,@MLShippmentGrossAmount
			   ,@MLfulfilled
			   ,@MLSelfService
			   ,@ML_logistic_type
			   ,@ML_tracking_method
			   ,@ML_date_first_printed
			   ,@ML_base_cost
			   ,@ML_estimated_delivery_time_date
			   ,@ML_estimated_delivery_time_shipping
			   ,GETDATE()
			   ,@ColectaDateTime
			  )
		END
    ELSE
		BEGIN
			UPDATE tbMercadoLibre_ordersShipping WITH (ROWLOCK)
			SET    MLshippingID               = @MLshippingID
				  ,MLshipment_type            = @MLshipment_type
				  ,MLshipping_mode            = @MLshipping_mode
				  ,mlm_JSON                   = @mlm_JSON
				  ,MLcost                     = @MLcost
				  ,MLlogistic_type            = @MLlogistic_type
				  ,MLstatus                   = @MLstatus
				  ,MLestimated_handling_limit = @MLestimated_handling_limit
				  ,MLestimated_delivery_final = @MLestimated_delivery_final
				  ,MLestimated_delivery_limit = @MLestimated_delivery_limit
				  ,MLreceiver_address         = @MLreceiver_address
				  ,MLstreet_name              = @MLstreet_name
				  ,MLstreet_number            = @MLstreet_number
				  ,MLcomment                  = @MLcomment
				  ,MLzip_code                 = @MLzip_code
				  ,MLcity_name                = @MLcity_name
				  ,MLstate_name               = @MLstate_name
				  ,MLcity_id                  = @MLcity_id
				  ,MLstate_id                 = @MLstate_id
				  ,MLconuntry_name            = @MLconuntry_name
				  ,MLreceiver_name            = @MLreceiver_name
				  ,MLreceiver_phone           = @MLreceiver_phone
				  ,MLLabel_PDF                = @MLLabel_PDF
				  ,MLLaben_ZPL2               = @MLLaben_ZPL2
				  ,MLlist_cost                = @MLlist_cost
				  ,MLdelivery_type            = @MLdelivery_type
				  ,MLshipping_method_id       = @MLshipping_method_id
				  ,MLtracking_number          = @MLtracking_number
				  ,MLShippmentCost4Buyer      = @MLShippmentCost4Buyer
				  ,MLShippmentCost4Seller     = @MLShippmentCost4Seller
				  ,MLShippmentGrossAmount     = @MLShippmentGrossAmount
				  ,MLfulfilled                = @MLfulfilled
				  ,MLSelf_Service             = @MLSelfService
				  ,ML_logistic_type           = @ML_logistic_type
				  ,ML_tracking_method         = @ML_tracking_method
				  ,ML_date_first_printed      = @ML_date_first_printed
				  ,ML_base_cost               = @ML_base_cost
				  ,ML_estimated_delivery_time_date = @ML_estimated_delivery_time_date
				  ,ML_estimated_delivery_time_shipping = @ML_estimated_delivery_time_shipping
				  ,mlos_lastUpdate            = GETDATE()
				  ,MLShippmentColectaDayTime  = @ColectaDateTime
			WHERE  comp_id                   = @comp_id
				   AND mlo_id                 = @mlo_id
		END



	-- MOS 09-2024: Se actualiza la fecha de Entrega con la informada x MeLi
	IF @ColectaDateTime IS NOT NULL
		BEGIN
			UPDATE tbSaleOrderHeader
				SET soh_deliveryDate = @ColectaDateTime
				WHERE	comp_id = @comp_id AND
						mlo_id	= @mlo_id
		END


END
GO


