CREATE PROCEDURE [dbo].[spMercadoLibre_PublicationStatistics_GetAllPublicationsByEan]
(
	@strEANString	NVARCHAR(4000)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------------------------
		/*
			DECLARE
				@strEANString	AS NVARCHAR(4000)
			SELECT
				@strEANString	= '7730737004103,KPI047,819937002441,'
		*/
		-- --------------------------------------------------------------------------------

		DECLARE		@tmpEAN2Search TABLE(EANCode NVARCHAR(30) PRIMARY KEY CLUSTERED)
		INSERT INTO @tmpEAN2Search (EANCode)
			SELECT	DISTINCT dbo.fnStrAllTrim(fst.items)
				FROM dbo.fnSplitTable(@strEANString,',') fst
				WHERE dbo.fnStrAllTrim(fst.items) <> ''


		DECLARE		@tmpStatistics TABLE(mlsts_id INT PRIMARY KEY CLUSTERED,EANCode NVARCHAR(30) )
		INSERT INTO @tmpStatistics(mlsts_id,EANCode)
			SELECT DISTINCT tmlps.mlsts_id,tmp.EANCode
				FROM tbMercadoLibre_PublicationStatistics AS tmlps	WITH (NOLOCK)
				INNER JOIN @tmpEAN2Search tmp
					ON	tmlps.publicationEAN  LIKE '%' + tmp.EANCode  + '%'
							OR
						tmlps.publicationGTIN  LIKE '%' + tmp.EANCode  + '%'

		DECLARE		@tmpFinalStatistics TABLE(mlsts_id INT PRIMARY KEY CLUSTERED )
		INSERT INTO @tmpFinalStatistics(mlsts_id)
		SELECT DISTINCT tmp.mlsts_id
			FROM @tmpStatistics	tmp


		SELECT
			tmlps.publicationID,
			tmlps.soldQTY,
			tmlps.availableQTY,
			tmlps.permalink,
			tmlps.categoryID,
			tmlps.categoryDescription,
			tmlps.dateCreated,
			tmlps.seller_addressCITY,
			tmlps.seller_addressSTATE,
			tmlps.seller_addressCOUNTRY,
			tmlps.seller_addressNEIGHBORHOOD,
			tmlps.seller_ID, tmlps.currencyID,
			tmlps.publicationListing_type_id,
			tmlps.publicationCondition,
			tmlps.publicationPrice,
			tmlps.hasVariations,
			tmlps.publicationEAN,
			tmlps.publicationGTIN,
			tmlps.publicationSKU,
			tmlps.publicationHealth,
			tmlps.lastScrap,
			tmlps.lastSoldQTY,
			tmlps.lastAvailableQTY,
			tmlps.lastWeekAvgSoldQTY,
			tmlps.seller_permalink,
			tmlps.seller_nickname
			FROM tbMercadoLibre_PublicationStatistics AS tmlps	WITH (NOLOCK)
			INNER JOIN @tmpFinalStatistics AS tfs
				ON tfs.mlsts_id = tmlps.mlsts_id

	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_PublicationStatistics_InsertOrUpdateData]
(
	@publicationID				NVARCHAR(30),
	@soldQTY					INT,
	@availableQTY				INT,
	@permalink					NVARCHAR(200),
	@categoryID					NVARCHAR(300),
	@categoryDescription		NVARCHAR(300),
	@dateCreated				DATETIME,
	@seller_addressCITY			NVARCHAR(300),
	@seller_addressSTATE		NVARCHAR(300),
	@seller_addressCOUNTRY		NVARCHAR(300),
	@seller_addressNEIGHBORHOOD	NVARCHAR(300),
	@seller_ID					BIGINT,
	@currencyID					VARCHAR(5),
	@publicationListing_type_id	NVARCHAR(20),
	@publicationCondition		NCHAR(10),
	@publicationPrice			DECIMAL(19,2),
	@hasVariations				BIT,
	@publicationEAN				NVARCHAR(MAX),
	@publicationGTIN			NVARCHAR(MAX),
	@publicationSKU				NVARCHAR(MAX),
	@publicationHealth			DECIMAL(19,2),
	@sellerNickName				NVARCHAR(100),
	@sellerPermaLink			NVARCHAR(250)
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@mlsts_id					INT,
				@publicationID				NVARCHAR(30),
				@publicationEAN				NVARCHAR(30),
				@soldQTY					INT,
				@availableQTY				INT,
				@permalink					NVARCHAR(200),
				@categoryID					NVARCHAR(300),
				@categoryDescription		NVARCHAR(300),
				@dateCreated				DATETIME,
				@seller_addressCITY			NVARCHAR(300),
				@seller_addressSTATE		NVARCHAR(300),
				@seller_addressCOUNTRY		NVARCHAR(300),
				@seller_addressNEIGHBORHOOD	NVARCHAR(300),
				@seller_ID					BIGINT,
				@currencyID					VARCHAR(5),
				@publicationListing_type_id	NVARCHAR(20),
				@publicationCondition		NCHAR(10),
				@publicationPrice			DECIMAL(19,2),
				@hasVariations				BIT
		*/
		-- -----------------------------------------------------------------------------

		IF NOT EXISTS (SELECT
							TOP 1 1
							FROM tbMercadoLibre_PublicationStatistics tmlps		WITH (NOLOCK)
							WHERE tmlps.publicationID = @publicationID)
			BEGIN

				INSERT INTO tbMercadoLibre_PublicationStatistics
				(
					publicationID,
					soldQTY,
					availableQTY,
					permalink,
					categoryID,
					categoryDescription,
					dateCreated,
					seller_addressCITY,
					seller_addressSTATE,
					seller_addressCOUNTRY,
					seller_addressNEIGHBORHOOD,
					seller_ID,
					currencyID,
					publicationListing_type_id,
					publicationCondition,
					publicationPrice,
					hasVariations,
					publicationEAN,
					publicationGTIN,
					publicationSKU,
					publicationHealth,
					lastScrap,
					lastSoldQTY,
					lastAvailableQTY,
					lastWeekAvgSoldQTY,
					seller_nickname,
					seller_permalink,
					lastpublicationPrice
				)
				VALUES
				(
					@publicationID,
					@soldQTY,
					@availableQTY,
					@permalink,
					@categoryID,
					@categoryDescription,
					@dateCreated,
					@seller_addressCITY,
					@seller_addressSTATE,
					@seller_addressCOUNTRY,
					@seller_addressNEIGHBORHOOD,
					@seller_ID,
					@currencyID,
					@publicationListing_type_id,
					@publicationCondition,
					@publicationPrice,
					@hasVariations,
					@publicationEAN,
					@publicationGTIN,
					@publicationSKU,
					@publicationHealth,
					GETDATE(),
					@soldQTY,
					@availableQTY,
					@soldQTY,
					@sellerNickName,
					@sellerPermaLink,
					@publicationPrice

				)
			END
		ELSE
			BEGIN

				UPDATE tbMercadoLibre_PublicationStatistics
				SET
					lastScrap					= GETDATE(),
					lastWeekAvgSoldQTY			= CONVERT(INT,(ISNULL(lastSoldQTY,@soldQTY) - @soldQTY) / 7),
					lastSoldQTY					= soldQTY,
					lastAvailableQTY			= availableQTY,
					lastpublicationPrice		= publicationPrice,
					soldQTY						= @soldQTY,
					availableQTY				= @availableQTY,
					permalink					= @permalink,
					categoryID					= @categoryID,
					categoryDescription			= @categoryDescription,
					dateCreated					= @dateCreated,
					seller_addressCITY			= @seller_addressCITY,
					seller_addressSTATE			= @seller_addressSTATE,
					seller_addressCOUNTRY		= @seller_addressCOUNTRY,
					seller_addressNEIGHBORHOOD	= @seller_addressNEIGHBORHOOD,
					seller_ID					= @seller_ID,
					currencyID					= @currencyID,
					publicationListing_type_id	= @publicationListing_type_id,
					publicationCondition		= @publicationCondition,
					publicationPrice			= @publicationPrice,
					hasVariations				= @hasVariations,
					publicationEAN				= @publicationEAN,
					publicationGTIN				= @publicationGTIN,
					publicationSKU				= @publicationSKU,
					publicationHealth			= @publicationHealth,
					seller_nickname				= @sellerNickName,
					seller_permalink			= @sellerPermaLink
					WHERE publicationID			= @publicationID

			END
	END

GO

CREATE PROCEDURE [dbo].[spMercadoLibre_PublicationStatistics_ProcessPublicationByEan]
(
	@strEANString	NVARCHAR(4000)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------------------------
		/*
			DECLARE
				@strEANString	AS NVARCHAR(4000)
			SELECT
				@strEANString	= '7730737004103,KPI047,819937002441,'
		*/
		-- --------------------------------------------------------------------------------

		DECLARE		@tmpEAN2Search TABLE(EANCode NVARCHAR(30) PRIMARY KEY CLUSTERED)
		INSERT INTO @tmpEAN2Search (EANCode)
			SELECT	DISTINCT dbo.fnStrAllTrim(fst.items)
				FROM dbo.fnSplitTable(@strEANString,',') fst
				WHERE dbo.fnStrAllTrim(fst.items) <> ''


		DECLARE		@tmpStatistics TABLE(mlsts_id INT PRIMARY KEY CLUSTERED,EANCode NVARCHAR(30) )
		INSERT INTO @tmpStatistics(mlsts_id,EANCode)
			SELECT DISTINCT tmlps.mlsts_id,tmp.EANCode
				FROM tbMercadoLibre_PublicationStatistics AS tmlps	WITH (NOLOCK)
				INNER JOIN @tmpEAN2Search tmp
					ON	tmlps.publicationEAN  LIKE '%' + tmp.EANCode  + '%'
							OR
						tmlps.publicationGTIN  LIKE '%' + tmp.EANCode  + '%'

		DECLARE		@tmpFinalStatistics TABLE(mlsts_id INT PRIMARY KEY CLUSTERED )
		INSERT INTO @tmpFinalStatistics(mlsts_id)
		SELECT DISTINCT tmp.mlsts_id
			FROM @tmpStatistics	tmp



		DECLARE	@tmpMLCategories	TABLE(categoryID NVARCHAR(30) PRIMARY KEY CLUSTERED )
		DECLARE @MinPrice4Category	AS DECIMAL(19,2) = 0
		DECLARE @MaxPrice4Category	AS DECIMAL(19,2) = 0
		DECLARE @PromPrice4Category AS DECIMAL(19,2) = 0

		INSERT INTO @tmpMLCategories(categoryID)
		SELECT	DISTINCT tmlps.categoryID
			FROM tbMercadoLibre_PublicationStatistics AS tmlps	WITH (NOLOCK)
			INNER JOIN @tmpFinalStatistics AS tfs
				ON tfs.mlsts_id = tmlps.mlsts_id

			SELECT
				@PromPrice4Category = AVG(tmlps.publicationPrice),
				@MaxPrice4Category  = MAX(tmlps.publicationPrice),
				@MinPrice4Category  = MIN(tmlps.publicationPrice)
			FROM tbMercadoLibre_PublicationStatistics AS tmlps	WITH (NOLOCK)
			INNER JOIN @tmpMLCategories AS tfs
				ON tfs.categoryID = tmlps.categoryID



		SELECT	SUM(tmlps.soldQTY)								[totalSoldQTY],
				SUM(tmlps.availableQTY)							[totalAvailableQTY],
				SUM(ISNULL(tmlps.lastWeekAvgSoldQTY,0))			[averageLastWeekSoldQTY],
				AVG(tmlps.publicationPrice)						[averagePublicationPrice],
				MAX(tmlps.publicationPrice)						[maxPublicationPrice],
				MIN(tmlps.publicationPrice)						[minPublicationPrice],
				@MinPrice4Category								[MinPrice4Category],
				@MaxPrice4Category								[MaxPrice4Category],
				@PromPrice4Category								[PromPrice4Category]
			FROM tbMercadoLibre_PublicationStatistics AS tmlps	WITH (NOLOCK)
			INNER JOIN @tmpFinalStatistics AS tfs
				ON tfs.mlsts_id = tmlps.mlsts_id

	END


GO

CREATE PROCEDURE [dbo].[spMercadoLibre_PublicationStatisticsCategories_GetAllData]

AS
	BEGIN
		SET NOCOUNT ON

		SET DATEFORMAT YMD
		DECLARE @dateFarFromNow AS DATETIME = '2000-01-01'


		SELECT
			tmlpsc.mlstsc_id,
			tmlpsc.mlstsc_cd,
			tmlpsc.categoryID,
			tmlpsc.mlstsc_lastScrap,
			ISNULL(tmlpsc.mlstsc_processNOW, 'False') [mlstsc_processNOW]
		FROM tbMercadoLibre_PublicationStatisticsCategories tmlpsc	WITH (NOLOCK)
		WHERE	(
					ISNULL(tmlpsc.mlstsc_processNOW,'False') = 'True'		OR
					DATEDIFF(DAY,ISNULL(tmlpsc.mlstsc_lastScrap,@dateFarFromNow),GETDATE()) >= 7
				)
	END
GO

