CREATE PROCEDURE [dbo].[spMercadoLibre_PublicationStatisticsCategories_InsertDataFromOtherERPS]
(
	@mlCategoryID	NVARCHAR(30)
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@mlCategoryID	NVARCHAR(30)
		*/
		-- -----------------------------------------------------

		IF NOT EXISTS(SELECT TOP 1
							1
							FROM tbMercadoLibre_PublicationStatisticsCategories tmlpsc WITH(NOLOCK)
							WHERE tmlpsc.categoryID = @mlCategoryID)
			BEGIN
				INSERT INTO tbMercadoLibre_PublicationStatisticsCategories
				(
					mlstsc_cd,
					categoryID,
					mlstsc_lastScrap,
					mlstsc_processNOW
				)
				VALUES
				(
					GETDATE(),
					@mlCategoryID,
					NULL,
					'False'
				)
			END
		ELSE
			BEGIN
				UPDATE tbMercadoLibre_PublicationStatisticsCategories
				SET
					mlstsc_lastUpdatefromSeller = GETDATE()
				WHERE categoryID = @mlCategoryID
			END

	END
GO

