CREATE PROCEDURE [dbo].[spMercadoLibre_QuestionsAndAnswers_Detail_AllQuestionsAnwers]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@MLUser_Id			bigint,
	@mlp_publicationID	NVARCHAR(30)

)

AS



BEGIN


	-- ----------------------------------------
	-- TESTING
	-- ----------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@bra_id		INT,
			@prof_id	INT,
			@item_id	INT
		SELECT
			@comp_id	= 1,
			@bra_id		= 1,
			@prof_id	= 1,
			@item_id	= 9130
*/
	-- ----------------------------------------



	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	SELECT
	tmlqaa.mlpqa_question					[mlpqa_question],
	tmlqaa.mlpqa_answer						[mlpqa_answer]

	FROM tbMercadoLibre_QuestionsAndAnswers					tmlqaa			WITH (NOLOCK)

	INNER JOIN tbMercadoLibre_ItemsPublicados				tmlip			WITH (NOLOCK)
	ON	tmlip.comp_id	= tmlqaa.comp_id		AND
