			(tmlqaa.MLUser_Id = @MLUser_Id and tmlip.mlp_publicationID = @mlp_publicationID)    --VER RESPUESTAS DEL USUARIO Y DE LA PUBLICACION


	ORDER BY tmlqaa.mlpqa_cd desc


END



GO





