CREATE PROCEDURE [dbo].[spMercadoLibre_QuestionsAndAnswers_GetData4GenericGrid]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@option				INT,			-- 1 : Usuario , 2 : Publicacion , 3 : Usuario + Publicacion
	@MLUser_Id			bigint,
	@mlp_publicationID	NVARCHAR(30)

)

AS



BEGIN


	-- ----------------------------------------
	-- TESTING
	-- ----------------------------------------
	/*
		DECLARE
		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@option				INT,			-- 1 : Usuario , 2 : Publicacion , 3 : Usuario + Publicacion
		@MLUser_Id			bigint,
		@mlp_publicationID	NVARCHAR(30)
		SELECT
			@comp_id	= 1,
			@bra_id		= 1,
			@prof_id	= 1,
			@lang_id	= 2,
			@user_id	= 3,
			@option		= 1,
			@MLUser_Id			= 1,
			@mlp_publicationID	= 'MLA685822963'

			*/
	-- ----------------------------------------



	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	SELECT
		tmlqaa.mlpqa_question										[mlpqa_question],
		tmlqaa.mlpqa_answer											[mlpqa_answer],
		tmlqaa.mlpqa_cd												[date],
		tmlqaa.mlpqa_answerDate										[mlpqa_answerDate],
			CASE isnull(tu.user_lastname,'') WHEN ' ' THEN
			(SELECT tut.utexts_desc
			   FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 40241)
			ELSE
				tu.user_lastname + ', ' + tu.user_firstname
			END														[user_name],
		tmlud.nickname												[Nickname]


		FROM tbMercadoLibre_QuestionsAndAnswers					tmlqaa			WITH (NOLOCK)


		INNER JOIN tbMercadoLibre_ItemsPublicados				tmlip			WITH (NOLOCK)
		ON	tmlip.comp_id	= tmlqaa.comp_id		AND
			tmlip.mlp_id	= tmlqaa.mlp_id

		LEFT JOIN tbUser										tu				WITH (NOLOCK)
		ON	tu.[user_id]	= tmlqaa.user_id_answer

		LEFT JOIN tbMercadoLibre_UsersData						tmlud			WITH (NOLOCK)
		ON	tmlud.MLUser_Id = tmlqaa.MLUser_Id


		WHERE tmlqaa.comp_id	= @comp_id			AND
			  isnull(tmlqaa.mlpqa_answer,'') <> ''  AND
		 CASE
			WHEN @option = -1												THEN 'True'
			WHEN @option =  1 AND isnull(tmlqaa.mlpqa_answer,'') <> '' AND tmlqaa.MLUser_Id			= @MLUser_Id			THEN 'True'		--VER RESPUESTAS DEL USUARIO
			WHEN @option =  2 AND isnull(tmlqaa.mlpqa_answer,'') <> '' AND tmlip.mlp_publicationID	= @mlp_publicationID	THEN 'True'		--VER RESPUESTAS DE LA PUBLICACION
			WHEN @option =  3 AND isnull(tmlqaa.mlpqa_answer,'') <> ''
							  AND tmlqaa.MLUser_Id			= @MLUser_Id OR tmlip.mlp_publicationID	= @mlp_publicationID THEN 'True'    --VER RESPUESTAS DEL USUARIO Y DE LA PUBLICACION
			ELSE 'False'
		END	= 'True'




END








	--		--VER RESPUESTAS DEL USUARIO
	--IF @option = 1

