	--		WHERE tmlqaa.comp_id			= @comp_id				AND
	--			  tmlip.mlp_publicationID	= @mlp_publicationID	AND
	--		      tmlqaa.mlpqa_answer		<> ''
	--	END

	----VER RESPUESTAS DEL USUARIO Y DE LA PUBLICACION
