CREATE PROCEDURE [dbo].[spMercadoLibre_QuestionsAndAnswers_getDataByFilters]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@item_id			INT,
	@user_id_answer		INT,			-- -1 : Todos, -2 :Respondido desde la aplicación de Mercadolibre©
	@MLUser_Id			bigint,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@datefromanswer		DATETIME,
	@datetoanswer		DATETIME,
	@option_status		INT,			-- -1 : Todos, 1 : Pendientes , 2 : Respondidas
	@nickname			NVARCHAR(200),
	@mlipc_id			INT
)
AS

BEGIN


	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

-- --------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------
/*

	DECLARE
		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@item_id			INT,
		@user_id_answer		INT,
		@MLUser_Id			bigint,
		@datefrom			DATETIME,
		@dateto				DATETIME,
		@datefromanswer		DATETIME,
		@datetoanswer		DATETIME,
		@nickname			NVARCHAR(200) = '',
		@mlipc_id			INT = -1,
		@option_status		INT = 1



	SELECT
		@comp_id   =  1,
		@lang_id   =  2,
		@bra_id	   = 1,
		@prof_id	= 1,
		@user_id			= 1,
		@item_id   = -1,
		@user_id_answer   = -1,
		@MLUser_Id   = 0,
		@datefrom  = '2021-10-01',
		@dateto	   = '2999-08-31',
		@datefromanswer		= '2021-10-01',
		@datetoanswer		= '2999-08-31'

*/
-- --------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	SET @datefromanswer	= dbo.fnGetEnd_or_BeginOfDate(@datefromanswer,'False')
	SET @datetoanswer		= dbo.fnGetEnd_or_BeginOfDate(@datetoanswer,'True')




	SELECT
		'' [1], -- RESPONDER
		'' [2], -- BORRAR
		'' [3], -- VER RESPUESTAS DEL USUARIO
		'' [4], -- VER RESPUESTAS DE LA PUBLICACION
		'' [5], -- VER RESPUESTAS DEL USUARIO Y LA PUBLICACION
		'' [6], -- MODIFICAR PUBLICACIÓN
		'' [7], -- Mercadolibre©: Gestionar Mensajes Post Venta

		tmls.mls_desc									[mls_desc],
		ti.item_desc									[item_desc],
		tmlqaa.mlpqa_question							[mlpqa_question],
		tmlqaa.mlpqa_cd									[Date],
		tmlqaa.mlpqa_answer								[mlpqa_answer],
		tu.user_lastname + ', ' + tu.user_firstname		[user_name],
		tmlqaa.mlpqa_answerDate							[mlpqa_answerDate],
		tmlqaa.mlpqa_answerTime							[mlpqa_answerTime],
		tmlud.nickname									[nickname],
		tovisAnswer.optval_desc							[mlpqa_isAnswered],
		tovisAutoAnswer.optval_desc						[mlpqa_isAutoAnswer],

		-- ATENCION!!!!!!
		-- No poner nada detras de este campo ya que se hacen controles de Count en la pagina 	wfmMercadoLibre_QuestionsAndAnswers
		CASE
			WHEN EXISTS(
							SELECT TOP 1 1
								FROM tbMercadoLibre_ordersHeader	tmloh		WITH (NOLOCK)
											WHERE	tmloh.comp_id	= tmlqaa.comp_id	AND
													tmloh.MLUser_Id	= tmlqaa.MLUser_Id
						)									THEN 1
			ELSE												 0
		END												[hasOrders],	-- ENU 5
		tmlqaa.MLUser_Id								[MLUser_Id],    -- ENU 4
		tmlqaa.MLQuestionID								[MLQuestionID], -- ENU 3
		tmlip.mlp_publicationID							[mlp_id],		-- ENU 2
		tmlqaa.mlpqa_id									[ID]


		FROM	tbMercadoLibre_QuestionsAndAnswers				tmlqaa			WITH (NOLOCK)

		INNER JOIN tbMercadoLibre_UsersData						tmlud			WITH (NOLOCK)
		ON	tmlud.MLUser_Id	= tmlqaa.MLUser_Id

		INNER JOIN tbMercadoLibre_ItemsPublicados				tmlip			WITH (NOLOCK)
		ON	tmlip.comp_id	= tmlqaa.comp_id		AND
			tmlip.mlp_id	= tmlqaa.mlp_id

		INNER JOIN tbItem										ti				WITH (NOLOCK)
		ON  ti.comp_id		= tmlip.comp_id			AND
			ti.item_id		= tmlip.item_id

		LEFT JOIN tbUser										tu				WITH (NOLOCK)
		ON	tu.[user_id]	= tmlqaa.user_id_answer

		left JOIN tbsysOptionsValues							tovisAnswer		WITH (NOLOCK)
		ON	tovisAnswer.lang_id			= @lang_id			AND
			tovisAnswer.optval_class	= 137				AND
			tovisAnswer.optval_id		= isnull(tmlqaa.mlpqa_isAnswered,'False')

		left JOIN tbsysOptionsValues							tovisAutoAnswer	WITH (NOLOCK)
		ON	tovisAutoAnswer.lang_id			= @lang_id			AND
			tovisAutoAnswer.optval_class	= 137				AND
			tovisAutoAnswer.optval_id		= isnull(tmlqaa.mlpqa_isAutoAnswer,'False')

		-- #STL10092018
		INNER JOIN tbMercadoLibre_Stores						tmls
		ON	tmls.comp_id					= tmlip.comp_id		AND
			tmls.mls_id						= tmlip.mls_id

		WHERE	tmlqaa.comp_id	= @comp_id
		AND		(tmlqaa.mlpqa_cd				BETWEEN		@datefrom	AND	@dateto)

		AND		(@item_id			= -1	OR ti.item_id					= @item_id)
		AND		((@user_id_answer	= -1	OR	 tmlqaa.user_id_answer		= @user_id_answer) OR
				 @user_id_answer	= -2	AND  isnull(tmlqaa.mlpqa_isAnswered,'false') = 'True' AND tmlqaa.user_id_answer IS NULL --Respondido desde la aplicacion de ML
				)
		AND		(@MLUser_Id			= 0		OR tmlqaa.MLUser_Id				= @MLUser_Id)
		AND		(@nickname			= ''	OR tmlud.nickname				= @nickname)
		AND		(@mlipc_id			= -1	OR tmlip.mlipc_id				= @mlipc_id)
		AND
		--(
		--@option_status = -1 OR
		--@option_status =  1 AND isnull(tmlqaa.mlpqa_isAnswered,'False') = 'False' AND  isnull(tmlqaa.mlpqa_isDeleted,'false') = 'false' OR
		--@option_status =  2 AND isnull(tmlqaa.mlpqa_isAnswered,'False')   = 'True' OR
		--@option_status =  3 AND isnull(tmlqaa.mlpqa_isAutoAnswer,'False') = 'True'
		--)
		CASE
			WHEN @option_status = -1														THEN	1
			WHEN @option_status =  1 AND isnull(tmlqaa.mlpqa_isAnswered,'False') = 'False' AND
									     isnull(tmlqaa.mlpqa_isDeleted,'false') = 'false'	THEN	1 --Pendientes
			WHEN @option_status =  2 AND isnull(tmlqaa.mlpqa_isAnswered,'False')   = 'True'	THEN	1 --Respondidas
			WHEN @option_status =  3 AND isnull(tmlqaa.mlpqa_isAutoAnswer,'False') = 'True'	THEN	1 --Respondidas automaticamente
			ELSE																					0
		END	= 1
		AND		(
					tmlqaa.mlpqa_answerDate IS NULL
						OR
					tmlqaa.mlpqa_answerDate	BETWEEN		@datefromanswer	AND	@datetoanswer
				)


		ORDER BY tmlqaa.mlpqa_cd DESC







END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_QuestionsAndAnswers_GetDataById]
(
	@comp_id		INT,
	@mlpqa_id		INT

)
AS


BEGIN
SET NOCOUNT ON

		SELECT
			 tmlqaa.mlpqa_id,
			 tmlqaa.mlp_id,
			 tmlqaa.mlpqa_question,
			 isnull(tmlqaa.mlpqa_answer,'') [mlpqa_answer],
			 tmlqaa.mlpqa_cd,
			 tmlqaa.user_id_answer,
			 tmlqaa.mlpqa_answerDate,
			 tmlqaa.mlpqa_answerTime,
			 tmlqaa.MLUser_Id,
			 tmlqaa.MLQuestionID,
			 isnull(tmlqaa.mlpqa_isDeleted,'False') [mlpqa_isDeleted],
			 isnull(tmlqaa.mlpqa_isAnswered,'False') [mlpqa_isAnswered],
			 isnull(tmlqaa.mlpqa_isAutoAnswer,'False') [mlpqa_isAutoAnswer],
			 tmls.mls_answerHeader,
			 tmls.mls_answerFooter,
			 isnull(tmlip.mlipc_id,-1)	 [mlipc_id],
			 tmlud.nickname [nickname]

		FROM tbMercadoLibre_QuestionsAndAnswers			tmlqaa		WITH (NOLOCK)

		INNER JOIN tbMercadoLibre_UsersData				tmlud		WITH (NOLOCK)
		ON		tmlud.MLUser_Id = tmlqaa.MLUser_Id

		INNER JOIN tbMercadoLibre_ItemsPublicados		tmlip		WITH (NOLOCK)
		ON		tmlip.comp_id	= tmlqaa.comp_id AND
				tmlip.mlp_id	= tmlqaa.mlp_id

		INNER JOIN tbMercadoLibre_Stores				tmls		WITH (NOLOCK)
		ON		tmls.comp_id	= tmlip.comp_id AND
				tmls.mls_id		= tmlip.mls_id

			WHERE	tmlqaa.comp_id		= @comp_id AND
					tmlqaa.mlpqa_id		= @mlpqa_id


END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_QuestionsAndAnswers_GetSuggestAnswer]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@mlpqa_id			INT,
	@mlipc_id			INT,
	@bitSelectByDate	BIT

)

AS


BEGIN


	-- ----------------------------------------
	-- TESTING
	-- ----------------------------------------
	/*
		DECLARE
					@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@prof_id			INT,
					@user_id			INT,
					@mlpqa_id			INT,
					@mlipc_id			INT,
					@bitSelectByDate	BIT


		SELECT
			@comp_id			= 1,
			@lang_id			= 2,
			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 1,
			@mlipc_id			= 5,
			@mlpqa_id			= 74,
			@bitSelectByDate	= 'True'
	*/
	-- ----------------------------------------



	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	SET DATEFIRST 7


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	DECLARE @lmls_id				AS INT
	DECLARE @lmlp_id				AS INT
	DECLARE	@lmlpqa_question		AS NVARCHAR(4000)
	DECLARE	@lmls_answerHeader		AS NVARCHAR(500)
	DECLARE	@lmls_answerFooter		AS NVARCHAR(500)
	DECLARE @item_id				AS INT = NULL

	--Guardamos el id item publicacion
	SELECT @lmlp_id = tmlqaa.mlp_id
		FROM tbMercadoLibre_QuestionsAndAnswers		tmlqaa		WITH (NOLOCK)
		WHERE tmlqaa.comp_id		= @comp_id AND
			  tmlqaa.mlpqa_id		= @mlpqa_id

	--Guardamos el id de la tienda relacionada a la item publicacion
	SELECT	@lmls_id			= tmlip.mls_id ,
			@item_id			= tmlip.item_id
		FROM tbMercadoLibre_ItemsPublicados			tmlip		WITH (NOLOCK)
		WHERE tmlip.comp_id		= @comp_id AND
			  tmlip.mlp_id		= @lmlp_id

	--Guardamos la pregunta
	SELECT @lmlpqa_question = tmlqaa.mlpqa_question
		FROM tbMercadoLibre_QuestionsAndAnswers		tmlqaa		WITH (NOLOCK)
		WHERE tmlqaa.comp_id		= @comp_id AND
			  tmlqaa.mlpqa_id		= @mlpqa_id

	--Guardamos el encabezado cargado en la tienda
	SELECT @lmls_answerHeader = isnull(tmls.mls_answerHeader,'')
		FROM tbMercadoLibre_Stores					tmls		WITH (NOLOCK)
		WHERE tmls.comp_id		= @comp_id AND
			  tmls.mls_id		= @lmls_id

	--Guardamos el pie cargado en la tienda
	SELECT @lmls_answerFooter = isnull(tmls.mls_answerFooter,'')
		FROM tbMercadoLibre_Stores					tmls		WITH (NOLOCK)
		WHERE tmls.comp_id		= @comp_id AND
			  tmls.mls_id		= @lmls_id




	--SELECT  @item_id		= tmlip.item_id
	--	FROM tbMercadoLibre_ItemsPublicados AS tmlip		WITH (NOLOCK)
	--	WHERE	tmlip.comp_id = @comp_id AND
	--			tmlip.mlp_id  = @lmlp_id

	DECLARE		@tmpAnswers TABLE(mlp_id INT , mlqat_id  INT PRIMARY KEY )
	INSERT INTO @tmpAnswers(mlp_id, mlqat_id)
		SELECT	@lmlp_id,tmlqaasp.mlqat_id
			FROM tbMercadoLibre_QuestionsAndAnswersSuggestions4Publications tmlqaasp		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_QuestionsAndAnswersSuggestions		tmlqaas			WITH (NOLOCK)
				ON	tmlqaas.comp_id  = tmlqaasp.comp_id		AND
					tmlqaas.mlqat_id = tmlqaasp.mlqat_id
			WHERE	tmlqaasp.comp_id		= @comp_id		AND
					tmlqaasp.item_id		= @item_id		AND
					tmlqaas.mlqat_disabled	= 'False'
	IF @@ROWCOUNT = 0	-- Ticket 15513
		BEGIN
			INSERT INTO @tmpAnswers(mlp_id, mlqat_id)
				SELECT  @lmlp_id,tmlqaasp.mlqat_id
					FROM tbMercadoLibre_QuestionsAndAnswersSuggestions						tmlqaasp	WITH (NOLOCK)
					LEFT JOIN tbMercadoLibre_QuestionsAndAnswersSuggestions4Publications	kk			WITH (NOLOCK)   -- MOS 03-2023: SOLO las que NO esten relacionadas a NINGUN articulo - ticket 15513
						ON	kk.comp_id	= tmlqaasp.comp_id		AND
							kk.mlqat_id = tmlqaasp.mlqat_id
					WHERE	tmlqaasp.comp_id		= @comp_id 	AND
							tmlqaasp.mlqat_disabled = 'False'	AND
							kk.comp_id IS NULL
		END



-- ==
--Select * from @tmpAnswers

	----------------
	-- test
	--SELECT @lmls_id [id de tienda],@lmlpqa_question [pregunta]


	--SELECT tmlqaas.mlqat_magicWord1, tmlqaas.mlqat_magicWord2,
	--       tmlqaas.mlqat_magicWord3, tmlqaas.mlqat_magicWord4,
	--       tmlqaas.mlqat_magicWord5
	--  FROM tbMercadoLibre_QuestionsAndAnswersSuggestions tmlqaas WHERE tmlqaas.mls_id = @lmls_id

	----------------
	----------------

	DECLARE @lSuggestAnswersFinal AS NVARCHAR(MAX) = ''


	IF @bitSelectByDate = 'False' -- Si se pide desde el boton lo hace normalmente
		BEGIN

			SELECT
				@lSuggestAnswersFinal =		@lSuggestAnswersFinal + '' +
						 					tmlqaas.mlqat_answer + CHAR(13) + CHAR(10)
				FROM tbMercadoLibre_QuestionsAndAnswersSuggestions			tmlqaas			WITH (NOLOCK)
				INNER JOIN @tmpAnswers tmp
					ON tmp.mlqat_id = tmlqaas.mlqat_id
				WHERE	tmlqaas.comp_id		= @comp_id
				AND		(isnull(tmlqaas.mls_id,-1)	 = -1	OR tmlqaas.mls_id	= @lmls_id)
				AND		(isnull(tmlqaas.mlipc_id,-1) = -1	OR tmlqaas.mlipc_id	= @mlipc_id)
				AND		(
							( @lmlpqa_question LIKE  '%'+ tmlqaas.mlqat_magicWord1 + '%' AND ISNULL(tmlqaas.mlqat_magicWord1,'') <> '')
							OR
							( @lmlpqa_question LIKE  '%'+ tmlqaas.mlqat_magicWord2 + '%' AND ISNULL(tmlqaas.mlqat_magicWord2,'') <> '')
							OR
							( @lmlpqa_question LIKE  '%'+ tmlqaas.mlqat_magicWord3 + '%' AND ISNULL(tmlqaas.mlqat_magicWord3,'') <> '')
							OR
							( @lmlpqa_question LIKE  '%'+ tmlqaas.mlqat_magicWord4 + '%' AND ISNULL(tmlqaas.mlqat_magicWord4,'') <> '')
							OR
							( @lmlpqa_question LIKE  '%'+ tmlqaas.mlqat_magicWord5 + '%' AND ISNULL(tmlqaas.mlqat_magicWord5,'') <> '')
				)

		END
	ELSE	-- Si es por una Auto Respuesta generada en el insert de la pregunta . . .
		BEGIN

			SELECT
				@lSuggestAnswersFinal =  REPLACE(@lSuggestAnswersFinal,tmlqaas.mlqat_answer + CHAR(13) + CHAR(10),'') + -- POr si trae algo duplicado . . .
										 '' +
										 tmlqaas.mlqat_answer + CHAR(13) + CHAR(10)
				FROM tbMercadoLibre_QuestionsAndAnswersSuggestions						tmlqaas			WITH (NOLOCK)
				INNER JOIN @tmpAnswers tmp
					ON tmp.mlqat_id = tmlqaas.mlqat_id
				INNER JOIN tbMercadoLibre_QuestionsAndAnswersSuggestions_AutoTimes		ata				WITH (NOLOCK)
					ON	ata.comp_id		= tmlqaas.comp_id AND
						ata.mlqat_id	= tmlqaas.mlqat_id

				WHERE	tmlqaas.comp_id		= @comp_id
				AND		(isnull(tmlqaas.mls_id,-1)	 = -1	OR tmlqaas.mls_id	= @lmls_id)
				AND		(isnull(tmlqaas.mlipc_id,-1) = -1	OR tmlqaas.mlipc_id	= @mlipc_id)
				AND		(
							( @lmlpqa_question LIKE  '%'+ tmlqaas.mlqat_magicWord1 + '%' AND ISNULL(tmlqaas.mlqat_magicWord1,'') <> '')
							OR
							( @lmlpqa_question LIKE  '%'+ tmlqaas.mlqat_magicWord2 + '%' AND ISNULL(tmlqaas.mlqat_magicWord2,'') <> '')
							OR
							( @lmlpqa_question LIKE  '%'+ tmlqaas.mlqat_magicWord3 + '%' AND ISNULL(tmlqaas.mlqat_magicWord3,'') <> '')
							OR
							( @lmlpqa_question LIKE  '%'+ tmlqaas.mlqat_magicWord4 + '%' AND ISNULL(tmlqaas.mlqat_magicWord4,'') <> '')
							OR
							( @lmlpqa_question LIKE  '%'+ tmlqaas.mlqat_magicWord5 + '%' AND ISNULL(tmlqaas.mlqat_magicWord5,'') <> '')
				)
				AND ata.mlqata_isDisabled = 'False'
				AND ( ata.mlqata_dayOfWeek IS NULL or   ata.mlqata_dayOfWeek  = DATEPART(weekday,GETDATE()))		-- MOS 09-2022: agregue el is null
				AND (DATEPART(hour,GETDATE()) BETWEEN ata.mlqata_fromTimeHour AND ata.mlqata_toTimeHour)


		END

	SELECT /*@lmls_answerHeader + CHAR(13) + CHAR(10) +*/ @lSuggestAnswersFinal  /*+ CHAR(13) + CHAR(10) + @lmls_answerFooter*/ [SuggestAnswersFinal]

END



GO



CREATE PROCEDURE [dbo].[spMercadoLibre_QuestionsAndAnswers_InsertData]
(
	 @comp_id						INT,
	 @mlp_id						INT,
	 @MLUser_Id						BIGINT,
	 @mlpqa_question				NVARCHAR(4000),
	 @MLQuestionID					BIGINT,
	 @mlpqa_answer					NVARCHAR(4000),
	 @guid							UNIQUEIDENTIFIER
)
AS

BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
	DECLARE	  	 @comp_id						INT,
				 @mlp_id						INT,
				 @mlpqa_MLUserId				BIGINT,
				 @mlpqa_question				NVARCHAR(4000),
				 @mlpqa_answer					NVARCHAR(4000),
				 @mlpqa_cd						DATETIME,
				 @user_id_answer				INT,
				 @mlpqa_answerDate				DATETIME,

				 @return_value					AS INT	OUTPUT


	SELECT		 @comp_id						=1,
				 @mlp_id						=43,
				 @mlpqa_MLUserId				=266710754,
				 @mlpqa_question				='',
				 @mlpqa_answer					='',
				 @mlpqa_cd						=1,
				 @user_id_answer				=1,
				 @mlpqa_answerDate				=1

	*/
	-- ------------------------------------------------------


	DECLARE @intmlproc_id	INT		= -1
	DECLARE @return_value	AS INT	= 0

	UPDATE tbMercadoLibre_QuestionsAndAnswers	WITH (ROWLOCK)
		SET mlpqa_answer		= @mlpqa_answer,
			mlpqa_answerDate	= GETDATE(),
			mlpqa_isAnswered	= CASE
			                	      WHEN @mlpqa_answer <> '' THEN 1
			                	      ELSE							0
			                	  END
		WHERE	comp_id			= @comp_id AND
				MLQuestionID	= @MLQuestionID

	-- Si NO estaba grabada, la graba.
	IF @@ROWCOUNT = 0
		BEGIN

			INSERT INTO tbMercadoLibre_QuestionsAndAnswers		WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				MLUser_Id,
				mlpqa_question,
				mlpqa_cd,
				MLQuestionID,
				mlpqa_answer ,
				mlpqa_answerDate,
				mlpqa_isAnswered
			)
			VALUES
			(
				 @comp_id,
				 @mlp_id,
				 @MLUser_Id,
				 @mlpqa_question,
				 GETDATE(),
				 @MLQuestionID,
				 @mlpqa_answer,
				 CASE
					 WHEN @mlpqa_answer <> '' THEN GETDATE()
					 ELSE						  NULL
				 END,
			     CASE
            	     WHEN @mlpqa_answer <> '' THEN 1
            	     ELSE						   0
             	 END
			)

			Set @return_value = @@IDENTITY

		END



	-- --------------------------------------------------------------------
	-- Auto rerspuesta de preguntas
	-- --------------------------------------------------------------------
	DECLARE @user_id	AS int
	DECLARE @mlipc_id	AS INT
	DECLARE @mls_id		AS INT
	DECLARE @mlp_publicationID AS NVARCHAR(50)
	SELECT	@mlipc_id		= tmlip.mlipc_id,
			@user_id		= tmls.[user_id]	,
			@mls_id			= tmls.mls_id,
			@mlp_publicationID		= tmlip.mlp_publicationID
		FROM tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_Stores tmls		WITH (NOLOCK)
				ON	tmls.comp_id	= tmlip.comp_id AND
					tmls.mls_id		= tmlip.mls_id
			WHERE	tmlip.comp_id	= @comp_id		AND
					tmlip.mlp_id	= @mlp_id

	DECLARE @tblAnswers TABLE (answer NVARCHAR(4000))
	INSERT INTO @tblAnswers (answer)
		EXEC spMercadoLibre_QuestionsAndAnswers_GetSuggestAnswer	@comp_id,
																	2,
																	-1,
																	-1,
																	-1,
																	@return_value,
																	@mlipc_id,
																	'True'


	DECLARE @strAnswer AS NVARCHAR(4000)
	SET		@strAnswer = ''
	SELECT	@strAnswer = ISNULL(tmp.answer,'')
		FROM @tblAnswers	tmp


	IF @strAnswer <> ''
		BEGIN

			DECLARE	@lmls_answerHeader		AS NVARCHAR(500)
			DECLARE	@lmls_answerFooter		AS NVARCHAR(500)

			--Guardamos el encabezado cargado en la tienda
			SELECT @lmls_answerHeader = isnull(tmls.mls_answerHeader,'')
				FROM tbMercadoLibre_Stores					tmls		WITH (NOLOCK)
				WHERE tmls.comp_id		= @comp_id AND
					  tmls.mls_id		= @mls_id

			--Guardamos el pie cargado en la tienda
			SELECT @lmls_answerFooter = isnull(tmls.mls_answerFooter,'')
				FROM tbMercadoLibre_Stores					tmls		WITH (NOLOCK)
				WHERE tmls.comp_id		= @comp_id AND
					  tmls.mls_id		= @mls_id


			SELECT @strAnswer = @lmls_answerHeader + CHAR(13) + CHAR(10) + @strAnswer + CHAR(13) + CHAR(10) + @lmls_answerFooter

			UPDATE tbMercadoLibre_QuestionsAndAnswers	WITH (ROWLOCK)
				SET mlpqa_answer		= @strAnswer,
					mlpqa_answerDate	= GETDATE(),
					user_id_answer		= @user_id,
					mlpqa_isAnswered	= 'True',
					mlpqa_isAutoAnswer	= 'True'
				WHERE	comp_id			= @comp_id AND
						mlpqa_id		= @return_value




			INSERT INTO tbMercadoLibre_updateQueue
			(
				comp_id,
				mlp_id,
				mlproc_cd,
				[user_id],
				mlproc_option,
				mlproc_stringValue,
				mlproc_isProcessed,
				mlproc_isCancelled,
				mlproc_priority,
				mlproc_bigintegerValue,
				mlproc_textValue,
				mlproc_guid
			)
			VALUES
			(
				@comp_id,
				@mlp_id,
				GETDATE(),
				@user_id,
				5,
				@strAnswer,
				'False',
				'False',
				0,
				@MLQuestionID,
				@strAnswer,
				@guid
			)

			SET @intmlproc_id = @@IDENTITY		-- Para que al toque procese la respuesta desde GBP.

		END

	ELSE

		BEGIN

			-- MOS 11-2022, x los forros de grem,iotech q dicen que sin esto no pueden vivir
			-- Mira si tiene que meterlo en la barra de workflow
			DECLARE @strUrl AS NVARCHAR(500) = 'wfmMercadoLibre_QuestionsAndAnswers_Detail.aspx?&VSOpenModalAjax=True&VS_ISFromWorkFlow=True&Action=O&Id=' + convert(nvarchar(20),@return_value)

			INSERT INTO tbWorkflow	WITH (ROWLOCK)
			(
				comp_id,
				bra_id,
				wf_type,
				wf_isProcessed,
				user_id_from,
				user_id_assigned,
				user_id_processed,
				prof_id_assigned,
				wf_dateOfAssigned,
				wf_dateOfProcessing,
				wf_link,
				wf_message1,
				wf_message2,
				wf_message3,
				wf_message4,
				wf_htmlTop,
				wf_htmlBody,
				wf_html_Bottom,
				mlpqa_id
			)
			SELECT
				@comp_id,
				NULL,
				960,	-- de donde lo copie decia 860
				'False',
				NULL,
				@user_id,
				NULL,
				tp.prof_id,	-- MOS 10-2022
				GETDATE(),
				NULL,
				@strURL,
				'MercadoLibre: Pregunta sobre Publicación:' + CONVERT(NVARCHAR(50),@mlp_publicationID),
				'NickName:'  ,
				'',
				@mlpqa_answer,
				'',
				'',
				'',
				@return_value
				FROM tbProfile tp	WITH (NOLOCK)			-- MOS 10-2022: Como corresponde...
				WHERE	tp.comp_id							= @comp_id AND
						tp.prof_workFlow4MLordersQuestions	= 1

		END









	-- --------------------------------------------------------------------


	SELECT	ISNULL(@return_value,-1)	[answerID],
			ISNULL(@intmlproc_id,-1)	[mlprocID]


END
GO


CREATE procedure [dbo].[spMercadoLibre_QuestionsAndAnswers_UpdateData]
(
	@comp_id				INT,
	@mlpqa_id				INT,
	@user_id_answer			INT,
	@mlpqa_answer			NVARCHAR(4000)

)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'


		UPDATE tbMercadoLibre_QuestionsAndAnswers	WITH (ROWLOCK)
		SET
			mlpqa_answer		= @mlpqa_answer,
			user_id_answer		= @user_id_answer,
			mlpqa_answerDate	= GETDATE(),
			mlpqa_isAnswered	= 'True'

		WHERE comp_id		= @comp_id AND
			  mlpqa_id		= @mlpqa_id


		-- -----------------------------------------------------------------------------
		-- STL 11-11-2022
		-- UNA VEZ QUE SE RESPONDE UNA PREGUNTA, SI ESTA EN LA WORKFLOW, HAY QUE VOLAR
		-- TODOS LOS REGISTROS ASOCIADOS A ESTA PREGUNTA
		-- -----------------------------------------------------------------------------
		DELETE FROM tbWorkflow
		WHERE	comp_id		= @comp_id AND
				mlpqa_id	= @mlpqa_id
		-- -----------------------------------------------------------------------------





	END
GO


CREATE procedure [dbo].[spMercadoLibre_QuestionsAndAnswers_UpdateData_Delete]
(
	@comp_id				INT,
	@mlpqa_id				INT

)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'


		UPDATE tbMercadoLibre_QuestionsAndAnswers	WITH (ROWLOCK)
		SET mlpqa_isDeleted = 'True'

		WHERE comp_id		= @comp_id AND
			  mlpqa_id		= @mlpqa_id





	END
GO


