CREATE PROCEDURE [dbo].[spMercadoLibre_QuestionsAndAnswersSuggestions_GetCombo]
(
	@comp_id	INT,
	@mlp_id		INT,
	@mlipc_id	INT


)
AS

BEGIN


	----------------------------------------------------------------
	----------testing-----------------------------------------------
	----------------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@mlp_id		INT,
			@mlipc_id	INT

	SELECT	@comp_id		= 1,
			@mlp_id			= 11,
			@mlipc_id		= 1

*/
----------------------------------------------------------------
------------------------------------------------------------------


	SET NOCOUNT ON


	DECLARE @lmls_id	AS INT
	--Guardamos el id de la tienda relacionada a la item publicacion
	SELECT
		@lmls_id		= tmlip.mls_id
		FROM tbMercadoLibre_ItemsPublicados			tmlip		WITH (NOLOCK)
		WHERE tmlip.comp_id		= @comp_id AND
			  tmlip.mlp_id		= @mlp_id

	SELECT
		tmlqaas.mlqat_label												[Desc],
		tmlqaas.mlqat_id												[Id]

	FROM tbMercadoLibre_QuestionsAndAnswersSuggestions	tmlqaas				WITH (NOLOCK)


	WHERE	tmlqaas.comp_id	= @comp_id		AND
			(isnull(tmlqaas.mls_id,-1)	 = -1	OR tmlqaas.mls_id	= @lmls_id)		AND
			(isnull(tmlqaas.mlipc_id,-1) = -1	OR tmlqaas.mlipc_id	= @mlipc_id)



END
GO



