CREATE PROCEDURE [dbo].[spMercadoLibre_Stores_funGetDataByMLPublicationID]
(
	@mlp_PublicationID		NVARCHAR(50)
)
AS


BEGIN


	SET NOCOUNT ON

	SELECT ISNULL(tmls.mls_setAsLabelPrintedInOrderProcess,'False')  [mls_setAsLabelPrintedInOrderProcess]
		FROM tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_Stores tmls			WITH (NOLOCK)
			ON	tmls.comp_id			= tmlip.comp_id AND
				tmls.mls_id				= tmlip.mls_id
		WHERE tmlip.mlp_publicationID	= @mlp_PublicationID




END
GO

