CREATE PROCEDURE [dbo].[spMercadoLibre_Stores_GetDataByApplicationID]
(
	@mls_clientID		NCHAR(100),
	@MLUser_Id			BIGINT
)
AS


BEGIN

		SET @mls_clientID = dbo.fnStrAllTrim(@mls_clientID)

		SET NOCOUNT ON

		SELECT TOP 1
			tmls.comp_id,
			tmls.mls_id,
			tmls.mls_desc												[mls_desc],
			ISNULL(tmls.mls_disabled,'False')							[mls_disabled],
			tmls.mls_clientID,
			tmls.mls_clientSecret,
			tmls.stor_id,
			tmls.prli_id,
			tmls.stor_id4StockAvailability								[stor_id4StockAvailability],
			ISNULL(tmls.mls_is4Sandbox,'False')							[mls_is4Sandbox],
			ISNULL(tmls.mls_url4S2Sdialog,'')							[mls_url4S2Sdialog],
			ISNULL(tmls.mls_official_store_id,'')						[mls_official_store_id],
			ISNULL(tmls.mls_seller_id,'')								[mls_seller_id],
			ISNULL(tmls.mls_url4Mercadolibre_processQueue,'')			[mls_url4Mercadolibre_processQueue],
			ISNULL(tmls.mls_isDisabled,'False')							[mls_isDisabled],
			tmls.mls_answerHeader,
			tmls.mls_answerFooter,
			tmls.bra_id,
			tmls.[user_id],
			tmls.cust_id_4newCustomersA,
			tmls.cust_id_4newCustomersB,
			tmls.st_id,
			tmls.disc_id,
			tmls.dl_id,
			tmls.sm_id,
			ISNULL(tmls.MLUser_Id,-1)									[MLUser_Id],
			ISNULL(tmls.mls_ServerGeneratedAuthorizationCode,'')		[mls_ServerGeneratedAuthorizationCode],
			ISNULL(tmls.mls_accessToken,'')								[mls_accessToken],
			ISNULL(tmls.mls_accessTokenValidUp2Date,GETDATE() - 1000)	[mls_accessTokenValidUp2Date],
			ISNULL(tmls.mls_refresh_Token,'')							[mls_refresh_Token],
			GETDATE()													[processDate],
			tmls.MLUser_Id,
			ISNULL(tmls.mls_orderWithNoPublicatedItem_Enabled,'False')				[mls_orderWithNoPublicatedItem_Enabled],
			ISNULL(tmls.mls_orderWithNoPublicatedItem_itemId1,-1)					[mls_orderWithNoPublicatedItem_itemId1],
			ISNULL(tmls.mls_orderWithNoPublicatedItem_itemId2,-1)					[mls_orderWithNoPublicatedItem_itemId2],
			ISNULL(tmls.mls_orderWithNoPublicatedItem_itemId2_OnlyIfContains,'')	[mls_orderWithNoPublicatedItem_itemId2_OnlyIfContains],
			ISNULL(tmls.mls_enabled4MercadoPagoVerificationsLastPayments,100)		[mls_enabled4MercadoPagoVerificationsLastPayments],
			dbo.fnMercadoLibre_getMLValue(tmls.country_id)							[CountryML]

			FROM tbMercadoLibre_Stores						tmls	WITH (NOLOCK)
			WHERE	CASE
						WHEN @MLUser_Id = -1 AND tmls.mls_clientID	= @mls_clientID		THEN 1
						WHEN tmls.MLUser_Id		= @MLUser_Id							THEN 1
						ELSE																 0
					END = 1
					--tmls.mls_clientID	= @mls_clientID AND
					--(tmls.MLUser_Id		= @MLUser_Id OR @MLUser_Id = -1)
			ORDER BY tmls.mls_desc

END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_Stores_GetDataByID]
(
	@comp_id	INT,
	@mls_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			tmls.comp_id,
			tmls.mls_id,
			tmls.mls_desc,
			tmls.mls_disabled,
			tmls.mls_clientID,
			tmls.mls_clientSecret,
			tmls.stor_id,
			tmls.prli_id,
			tmls.stor_id4StockAvailability,
			tmls.mls_is4Sandbox,
			tmls.mls_url4S2Sdialog,
			tmls.mls_official_store_id,
			tmls.mls_seller_id,
			tmls.mls_url4Mercadolibre_processQueue,
			tmls.mls_isDisabled,
			tmls.mls_answerHeader,
			tmls.mls_answerFooter,
			tmls.bra_id,
			tmls.[user_id],
			tmls.cust_id_4newCustomersA,
			tmls.cust_id_4newCustomersB,
			tmls.st_id,
			tmls.disc_id,
			tmls.dl_id,
			tmls.sm_id,
			tmls.MLUser_Id,
			'False'   															[mls_enableHTMLPublications],					-- ISNULL(tmls.mls_enableHTMLPublications,'False')
			ISNULL(tmls.mls_enableUpdatePublicationsFromMercadoLibre,'False')	[mls_enableUpdatePublicationsFromMercadoLibre],
			tmls.mls_imageTOP,
			tmls.mls_imageMIDDLE,
			tmls.mls_imageBOTTOM1,
			tmls.mls_imageBOTTOM2,
			ISNULL(tmls.mls_allowPublicationsWithNoStock,'False')				[mls_allowPublicationsWithNoStock],
			ISNULL(tmls.mls_updatePublicationFreeShippingFromML,'False')		[mls_updatePublicationFreeShippingFromML],
			ISNULL(tmls.mls_isOfficial_Store,'False')							[mls_isOfficial_Store],
			ISNULL(tmls.mls_allowImagesMLStatic,'False')                        [mls_allowImagesMLStatic],
			tmls.curr_id,
			ISNULL(tmls.mls_updatePublicationImagesFromML,'False')				[mls_updatePublicationImagesFromML],
			ISNULL(tmls.mls_disablePriceListUpdate,'False')						[mls_disablePriceListUpdate],
			ISNULL(tmls.mls_importPublication_ImportImages,'False')				[mls_importPublication_ImportImages],
			ISNULL(tmls.mls_disableImagesImport,'False')						[mls_disableImagesImport],
			tmls.mls_System_MercadoLibreProcessQueue_lastCicleExecution,
			ISNULL(tmls.mls_setPriceToInteger,'False')							[mls_setPriceToInteger],
			ISNULL(tmls.mls_imagesJsonGeneratedFromMLPublication,'False')		[mls_imagesJsonGeneratedFromMLPublication]	,
			tmls.mls_accessToken												[mls_accessToken],
			ISNULL(tmls.mls_labelPrintModulePrinterName,'')						[mls_labelPrintModulePrinterName],
			ISNULL(tmls.mls_labelPrintModuleFixedText,'')						[mls_labelPrintModuleFixedText],
			ISNULL(tmls.mls_accessTokenValidUp2Date,GETDATE())					[mls_accessTokenValidUp2Date],
			ISNULL(tmls.printQueue_Enabled,'False')								[printQueue_Enabled],
			ISNULL(tmls.printQueue_id,'')										[printQueue_id],
			ISNULL(tmls.printQueue_printerName,'')								[printQueue_printerName],
			dbo.fnMercadoLibre_getMLValue(tmls.country_id)						[CountryML],
			ISNULL(tmls.country_id,54)											[country_id],
			ISNULL(tc.curr_symbol,'ARS')										[curr_symbol],
			ISNULL(tmls.mls_enableFamilyProducts,'False')						[mls_enableFamilyProducts]
			FROM tbMercadoLibre_Stores			tmls		WITH (NOLOCK)
			LEFT JOIN tbsysCurrency AS tc					WITH (NOLOCK)
				ON tc.curr_id		=  tmls.curr_id
			WHERE	tmls.comp_id	= @comp_id	AND
					tmls.mls_id		= @mls_id

	END
GO

