CREATE PROCEDURE [dbo].[spMercadoLibre_subValidateDataForMassivePublicationByExcel]
(
	@comp_id							INT,
	@mls_id								INT,
	@strML_CategoryID					NVARCHAR(50),
	@strML_ListingType					NVARCHAR(50),
	@item_code							NVARCHAR(50),
	@strML_Title						NVARCHAR(100),
	@strML_Desc							NVARCHAR(MAX),
	@prli_id							INT,
	@stor_id							INT,
	@mlipc_id							INT,
	@guid								UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- --------------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------------
		/*
			DECLARE
				@comp_id							INT,
				@mls_id								INT,
				@strML_CategoryID					NVARCHAR(50),
				@strML_ListingType					NVARCHAR(50),
				@item_code							NVARCHAR(50),
				@strML_Title						NVARCHAR(100),
				@strML_Desc							NVARCHAR(MAX),
				@prli_id							INT,
				@stor_id							INT,
				@mlipc_id							INT--,
				--@guid								UNIQUEIDENTIFIER

			SELECT
				@comp_id							= 1,
				@mls_id								= 878,
				@strML_CategoryID					= '',
				@strML_ListingType					= 'caracas',
				@item_code							= 'a4d54as5',
				@strML_Title						= '',
				@strML_Desc							= '',
				@prli_id							= 1515,
				@stor_id							= 51151,
				@mlipc_id							= 4584--,
				--@guid								UNIQUEIDENTIFIER
		*/
		-- --------------------------------------------------------------

		DECLARE @ErrorLog	NVARCHAR(MAX)
		SET @ErrorLog		= ''


		-- ----------------------------------------------------------------------------------
		-- SI LA TIENDA NO EXISTE O NO ESTA HABILITADA
		-- ----------------------------------------------------------------------------------
			IF NOT EXISTS(SELECT TOP 1
							1
							FROM tbMercadoLibre_Stores			tmls	WITH(NOLOCK)
							WHERE	tmls.comp_id	= @comp_id	AND
									tmls.mls_id		= @mls_id)
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | El ID de tienda no existe'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END

			IF (SELECT
					ISNULL(tmls.mls_disabled,'False')
					FROM tbMercadoLibre_Stores			tmls	WITH(NOLOCK)
					WHERE	tmls.comp_id	= @comp_id	AND
							tmls.mls_id		= @mls_id ) = 'True'
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | La tienda seleccionada no se encuentra habilitada'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END
		-- ----------------------------------------------------------------------------------

		-- ----------------------------------------------------------------------------------
		-- SI NO LE PASAN ID DE CATEGORIA
		-- ----------------------------------------------------------------------------------
			IF @strML_CategoryID = ''
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | No hay ningún ID de categoría asignado'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END
		-- ----------------------------------------------------------------------------------

		-- ----------------------------------------------------------------------------------
		-- RECUPERO EL ITEM_ID EN BASE AL CODIGO, SI NO ENCUENTRA NADA, TIRO ERROR
		-- ----------------------------------------------------------------------------------
			DECLARE @item_id AS INT
			SELECT
				@item_id = ti.item_id
			FROM tbItem							ti	WITH(NOLOCK)
			WHERE	ti.comp_id		= @comp_id	AND
					ti.item_code	= @item_code

			IF @item_id IS NULL
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | El código de artículo ingresado no existe'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END
		-- ----------------------------------------------------------------------------------



		-- ----------------------------------------------------------------------------------
		-- SI NO LE PUSIERON TITULO O DESCRIPCION
		-- ----------------------------------------------------------------------------------
			IF @strML_Title = ''
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | No hay un título cargado para la publicación'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END

			IF @strML_Desc = ''
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | No hay una descripción cargada para la publicación'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END
		-- ----------------------------------------------------------------------------------

		-- ----------------------------------------------------------------------------------
		-- SI EL ID DE LISTA DE PRECIOS NO EXISTE O EL ARTICULO NO TIENE PRECIO PARA LA
		-- LISTA SELECCIONADA
		-- ----------------------------------------------------------------------------------

			IF NOT EXISTS(SELECT TOP 1
							1
							FROM tbPriceList				tpl	WITH(NOLOCK)
							WHERE	tpl.comp_id = @comp_id	AND
									tpl.prli_id = @prli_id)
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | No existe el ID de lista de precios'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END

			IF NOT EXISTS (SELECT TOP 1
							1
							FROM tbPriceListItems			tpli	WITH(NOLOCK)
							WHERE	tpli.comp_id = @comp_id AND
									tpli.prli_id = @prli_id AND
									tpli.item_id = @item_id)
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | El artículo seleccionado no existe para la lista seleccionada'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END

			IF (SELECT
					tpli.prli_price
					FROM tbPriceListItems			tpli WITH(NOLOCK)
					WHERE	tpli.comp_id = @comp_id AND
							tpli.prli_id = @prli_id AND
							tpli.item_id = @item_id) = 0
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | El artículo seleccionado no tiene un precio cargado para la lista de precios'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END
		-- ----------------------------------------------------------------------------------

		-- ----------------------------------------------------------------------------------
		-- NO EXISTE EL DEPÓSITO
		-- ---------------------------------------------------------------------------------
			IF NOT EXISTS (SELECT TOP 1
							1
							FROM tbStorage					ts	WITH(NOLOCK)
							WHERE	ts.comp_id = @comp_id	AND
									ts.stor_id = @stor_id)
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | El depósito cargado no existe'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END
		-- ----------------------------------------------------------------------------------

		-- ----------------------------------------------------------------------------------
		-- NO LA CATEGORIA DE PUBLICACION
		-- ---------------------------------------------------------------------------------
			IF NOT EXISTS (SELECT TOP 1
							1
							FROM tbMercadoLibre_ItemsPublicadosCategories	tmlipc	WITH(NOLOCK)
							WHERE	tmlipc.comp_id	= @comp_id				AND
									tmlipc.mlipc_id = @mlipc_id)
				BEGIN
					SELECT @ErrorLog = @ErrorLog + ' | La categoría de publicación seleccionada no existe'
					SELECT @ErrorLog [ErrorLog]
					RETURN
				END
		-- ----------------------------------------------------------------------------------

		-- ----------------------------------------------------------------------------------
		-- SI NO HUBO NINGUN RETURN, ESTA TODO OK Y DEVUELVE ''
		-- ----------------------------------------------------------------------------------

		SELECT @ErrorLog [ErrorLog]

	END




GO

