CREATE PROCEDURE [dbo].[spMercadoLibre_updateQueue_GenerateUpdateRecords]
(
	@comp_id				INT,
	@user_id				INT,
	@item_id				INT,
	@mlproc_option			INT,
	@mlproc_guid			UNIQUEIDENTIFIER
)
AS
BEGIN
	SET NOCOUNT ON

	-- ----------------------------------------------------------------------
	-- TESTING
	-- ----------------------------------------------------------------------
	/*
		DECLARE
			@comp_id				INT,
			@lang_id				INT,
			@user_id				INT,
			@item_id				INT,
			@mlproc_option			INT,
			@mlproc_guid			UNIQUEIDENTIFIER
		SELECT
			@comp_id				= 1,
			@lang_id				= 2,
			@user_id				= 134,
			@item_id				= 15549,
			@mlproc_option			= 4,
			@mlproc_guid			= 'f202e88f-16c0-4223-9ae7-94feb15688f4'
	*/
	-- ----------------------------------------------------------------------

	-- ----------------------------------------------------------------------
	-- Tabla Temporal con todas las publicaciones de ML que tengan
	-- el ITEM_ID que viene por parámetro y a su vez se encuentren
	-- activas
	-- ----------------------------------------------------------------------

	DECLARE @bitWasInserted AS BIT = 'False'

	DECLARE @tblMercadoLibre_ItemsPublicados TABLE (comp_id INT,
													prli_id	INT,
													curr_id	INT,
													mlp_id INT PRIMARY KEY)
	INSERT INTO @tblMercadoLibre_ItemsPublicados
	(
		comp_id,
		prli_id,
		curr_id,
		mlp_id
	)
		-- SOLO INSERTO LOS ID DE LOS ARTICULOS QUE SE ENCUENTREN ACTIVOS
		SELECT	DISTINCT
			tmlip.comp_id,
			tmlip.prli_id,
			tmlip.curr_id,
			tmlip.mlp_id
			FROM tbMercadoLibre_ItemsPublicados							tmlip		WITH (NOLOCK)
			LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations			tmlipv		WITH (NOLOCK)
				ON	tmlipv.comp_id						= tmlip.comp_id	AND
					tmlipv.mlp_id						= tmlip.mlp_id
			INNER JOIN tbMercadoLibre_Stores							tmls		WITH (NOLOCK)
				ON	tmls.comp_id						= tmlip.comp_id AND
					tmls.mls_id							= tmlip.mls_id
			WHERE	tmlip.comp_id						= @comp_id		AND
					(
						tmlip.item_id						= @item_id
							OR
						tmlipv.item_id						= @item_id
							OR
							EXISTS(
										SELECT TOP 1 1
											FROM tbItemAssociation AS tia		WITH (NOLOCK)
											WHERE	tia.comp_id		= @comp_id AND
													tia.item_id_1	= @item_id AND
													(
														tia.item_id = tmlip.item_id
															OR
														tia.item_id = tmlipv.item_id
													)
									)
					) AND
					tmls.mls_disabled					= 'False'		AND
					tmlip.optval_statusId				IN (1,2,3,4/*,6*/)	AND   -- MOS 18-08-2019, Saqué Pausado Forzado e INCLUI las putas VARIACIONES que no se porque MIERDA no estaban.!!!
					tmls.mls_accessToken	<> ''						AND
					CASE
						WHEN @mlproc_option = 4											THEN 1	-- MLQO_UpdateAvailableQuantity
						WHEN @mlproc_option = 8 AND tmlip.mlp_isFixedPrice = 'False'	THEN 1	-- MLQO_Publication_Price
						ELSE																 0
					END = 1
-- ----------------------------------------------------------------------



	-- ------------------------------------------------------------------
	--MLQO_UpdateAvailableQuantity	Stock
	-- ------------------------------------------------------------------
	IF (@mlproc_option = 4)
		BEGIN

			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
				(
					comp_id,
					mlp_id,
					[user_id],
					mlproc_option,
					mlproc_stringValue,
					mlproc_integerValue,
					mlproc_decimalValue,
					mlproc_priority,
					mlproc_guid,
					mlproc_bigintegerValue,
					mlproc_textValue,
					mlproc_integerValue2,
					mlproc_internalID
				)
			SELECT
					tmp.comp_id,
					tmp.mlp_id,
					@user_id,
					@mlproc_option,
					'',
					0,
					0,
					-10000,
					@mlproc_guid,
					0,
					'',
					0	,
					8798341			-- MOS 03-2022
					FROM @tblMercadoLibre_ItemsPublicados	tmp

			IF @@ROWCOUNT > 0 SET @bitWasInserted = 'True'

			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
				(
					comp_id,
					mlp_id,
					[user_id],
					mlproc_option,
					mlproc_stringValue,
					mlproc_integerValue,
					mlproc_decimalValue,
					mlproc_priority,
					mlproc_guid,
					mlproc_bigintegerValue,
					mlproc_textValue,
					mlproc_integerValue2,
					mlproc_internalID
				)
			SELECT
					tmp.comp_id,
					tmp.mlp_id,
					@user_id,
					8,
					'',
					0,
					0,
					-10001,
					@mlproc_guid,
					0,
					'',
					0	,
					8798343			-- MOS 03-2022
					FROM @tblMercadoLibre_ItemsPublicados	tmp


		END
	-- ------------------------------------------------------------------


	-- ------------------------------------------------------------------
	--MLQO_Publication_Price
	-- ------------------------------------------------------------------
	IF (@mlproc_option = 8)
		BEGIN

			UPDATE tbMercadoLibre_ItemsPublicados				WITH (ROWLOCK)
				SET	 mlp_price = dbo.fnGetExchange2(tmp.comp_id,  tpli.prli_price,tpli.curr_id, tip.curr_id, 0, 0, 0, 'False')
				FROM		tbMercadoLibre_ItemsPublicados tip
				INNER JOIN	@tblMercadoLibre_ItemsPublicados tmp
					ON	tmp.comp_id = tip.comp_id AND
						tmp.mlp_id	= tip.mlp_id
				INNER JOIN	tbPriceListItems				tpli	WITH (NOLOCK)
					ON	tpli.comp_id = tmp.comp_id	AND
						tpli.prli_id = tmp.prli_id	AND
						tpli.item_id = tip.item_id  -- @item_id
				WHERE
						tip.comp_id								= @comp_id		AND
						--tip.item_id		= @item_id	AND	--MOS 06-2020 x La Cobacha, Combos.
						tpli.prli_price							> 0

			--
			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
				(
					comp_id,
					mlp_id,
					[user_id],
					mlproc_option,
					mlproc_stringValue,
					mlproc_integerValue,
					mlproc_decimalValue,
					mlproc_priority,
					mlproc_guid,
					mlproc_bigintegerValue,
					mlproc_textValue,
					mlproc_integerValue2,
					mlproc_internalID
				)
			SELECT
					tmp.comp_id,
					tmp.mlp_id,
					@user_id,
					@mlproc_option,
					'',
					0,
					dbo.fnGetExchange2(tmp.comp_id,  tpli.prli_price,tpli.curr_id, tmp.curr_id, 0, 0, 0, 'False'),
					-10000,
					@mlproc_guid,
					0,
					'',
					0	,
					8798342			-- MOS 03-2022
					FROM @tblMercadoLibre_ItemsPublicados	  AS tmp
					INNER JOIN tbMercadoLibre_ItemsPublicados AS tmlip
						ON	tmlip.comp_id	= tmp.comp_id AND
							tmlip.mlp_id	= tmp.mlp_id
					INNER JOIN tbPriceListItems				tpli	WITH (NOLOCK)
						ON	tpli.comp_id = tmp.comp_id	AND
							tpli.prli_id = tmp.prli_id	AND
							tpli.item_id = tmlip.item_id /*@item_id*/
					WHERE	tpli.prli_price > 0

			IF @@ROWCOUNT > 0 SET @bitWasInserted = 'True'

		END
	-- ------------------------------------------------------------------


	SELECT @bitWasInserted [wasInserted]

END


GO

