CREATE PROCEDURE [dbo].[spMercadoLibre_updateQueue_getDataByFilters]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@option_status		INT,			-- -1 TODOS / 1 NO PROCESADOS / 2 PROCESADOS / 3 CANCELADOS
	@mlproc_option		INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@MLID				NVARCHAR(30),	--id de pub
	@ItemGuid			UNIQUEIDENTIFIER,
	@mls_id				INT	,
	@mlproc_id			INT,
	@ResponseFilter		VARCHAR(250)
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------




		-- --------------------------------------------------------------------
		-- TESTING
		---------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@option_status		INT,		-- -1 TODOS / 1 NO PROCESADOS / 2 PROCESADOS / 3 CANCELADOS
				@mlproc_option		INT,
				@datefrom			DATETIME,
				@dateto				DATETIME,
				@MLID				NVARCHAR(30),
				@ItemGuid			UNIQUEIDENTIFIER,
				@mls_id				INT	,
				@mlproc_id			INT

			SELECT
				@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= -1,
				@prof_id			= 1,
				@user_id			= 1,
				@option_status		= -1,		-- -1 TODOS / 1 NO PROCESADOS / 2 PROCESADOS / 3 CANCELADOS
				@mlproc_option		= -1,
				@datefrom			='01/01/1999',
				@dateto				='12/31/2999',
				@MLID				='',	--id,
				@ItemGuid			='96439a79-04ef-4128-bc81-b1139a073fd1',
				@mls_id				= -1,
				@mlproc_id			=  0
		*/
		-- --------------------------------------------------------------------



		SET @ResponseFilter = dbo.fnStrAllTrim(@ResponseFilter)
		SET @datefrom		= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		SET @dateto			= dbo.fnGetEnd_or_BeginOfDate(@dateto  ,'True')

		-- ------------------------------------------------------------
		-- Optimiza las búsquedas
		-- ------------------------------------------------------------
		SET @MLID = UPPER(@MLID)
		SET @MLID = REPLACE(@MLID,'-','')
		SET @MLID = dbo.fnStrAllTrim(@MLID)
		-- ------------------------------------------------------------

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @bitItemFilter BIT = 'False'

		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf	WITH (NOLOCK)
				WHERE tcf.sl_guid = @ItemGuid     AND
					  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti	WITH (NOLOCK)
						WHERE	ti.comp_id = @comp_id AND
								ti.comp_id = @comp_id
			END
		ELSE
			BEGIN
				SET @bitItemFilter = 'True'
			END

		--SELECT * FROM @tblComplexFilter_Items
		-- -------------------------------------------------------------





		SELECT
			''											[1], -- Ver Json
			''											[2], -- Cancelar
			''											[3], -- Detalle de publi
			tmlip.mlp_publicationID						[mlp_publicationID],
			CONVERT(nvarchar(10),tmluq.mlproc_option) + '-' + ISNULL(tov.optval_desc,'')			[optval_desc],
			ti.item_desc								[item_desc],
			tu.user_lastname + ', ' + tu.user_firstname	[user_name],
			ISNULL(tmluq.mlproc_isProcessed,'False')	[mlproc_isProcessed],
			ISNULL(tmluq.mlproc_isCancelled,'False')	[mlproc_isCancelled],
			-- Atención: ANTES DE AQUI NO PONER NADA MAS . EN LA PAGINA DESHABILITA CONTROL PREGUNTANDO POR [mlproc_isProcessed]


			TMLUQ.mlproc_cd,
			tmluq.mlproc_isProcessedCD,
			ISNULL(tmlip.mlp_permalink,'')				[mlp_permalink],
			ISNULL(tmls.mls_desc,'')					[mls_desc],
			tmluq.mlproc_internalID						[internalID],



			-- NO AGREGAR NADA DESPUES DE ESTA LINEA !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
			CASE
				WHEN tmluq.mlproc_blockCancell = 'False'												THEN 0
				WHEN tmluq.mlproc_blockCancell = 'True'		AND tmluq.mlproc_response LIKE '%**889%'	THEN 1	-- Si NO procesa porque faltan asociar item_id a Variaciones...  que NO los depure a los 10 intentos...
				WHEN tmluq.mlproc_blockCancell = 'True'		AND tmluq.mlproc_response LIKE '%**879%'	THEN 2	-- ATENCIÓN: NO se pudo actualizar el Stock debido a un error informado por MercadoLibre©
				WHEN tmluq.mlproc_blockCancell = 'True'		AND tmluq.mlproc_response LIKE '%**869%'	THEN 3	-- ATENCIÓN: NO se pudo actualizar el PRECIO debido a un error informado por MercadoLibre© (Publicación SIN Variación)
				WHEN tmluq.mlproc_blockCancell = 'True'		AND tmluq.mlproc_response LIKE '%**859%'	THEN 4	-- ATENCIÓN: NO se pudo actualizar el PRECIO debido a un error informado por MercadoLibre© (Publicación Con Variaciónes)
				ELSE 0
			END											[mlproc_blockCancell],	-- Count - 3
			tmlip.mlp_id								[mlp_id],	-- Count - 2
			tmluq.mlproc_id								[ID]		-- Count - 1

			FROM tbMercadoLibre_updateQueue 			tmluq			WITH (NOLOCK)
			LEFT JOIN tbMercadoLibre_ItemsPublicados	tmlip			WITH (NOLOCK)
				ON	tmlip.comp_id		= tmluq.comp_id		AND
					tmlip.mlp_id		= tmluq.mlp_id
			LEFT JOIN tbMercadoLibre_Stores				tmls			WITH (NOLOCK)
				ON	tmls.comp_id		= tmlip.comp_id		AND
					tmls.mls_id			= tmlip.mls_id
			LEFT JOIN tbItem							ti				WITH (NOLOCK)
				ON  ti.comp_id			= tmlip.comp_id		AND
					ti.item_id			= tmlip.item_id
			LEFT JOIN @tblComplexFilter_Items			tmp				-- Esto hace q no se vean los cptes pendientes de enviar por mens interna.
				ON	tmp.item_id			= tmlip.item_id
			LEFT JOIN tbUser							tu				WITH (NOLOCK)
				ON	tu.[user_id]		= tmluq.[user_id]
			LEFT JOIN tbsysOptionsValues				tov				WITH (NOLOCK)
				ON	tov.lang_id			= @lang_id			AND
					tov.optval_id		= tmluq.mlproc_option AND
					tov.optval_class	= 730
			WHERE	tmluq.comp_id	= @comp_id									AND

					(
						@option_status = -1																													OR	--	TODOS
						@option_status = 1 AND ISNULL(tmluq.mlproc_isProcessed,'False') = 'False' AND ISNULL(tmluq.mlproc_isCancelled,'False') = 'False'	OR	--	NO PROCESADOS
						@option_status = 2 AND ISNULL(tmluq.mlproc_isProcessed,'False') = 'True'  AND ISNULL(tmluq.mlproc_isCancelled,'False') = 'False'	OR	--	PROCESADOS
						@option_status = 3 AND ISNULL(tmluq.mlproc_isCancelled,'False') = 'True'  																--	CANCELADOS
					)									AND
					(
						@mlproc_option		= -1													OR
						tmluq.mlproc_option = @mlproc_option
					)									AND
					(
						@MLID			= ''									OR
						tmlip.mlp_publicationID LIKE '%' + @MLID + '%'
					)															AND
					tmluq.mlproc_cd BETWEEN @datefrom AND @dateto				AND
					(
						@mls_id			= -1									OR
						tmlip.mls_id	= @mls_id
					)															AND
					ISNULL(tmls.mls_disabled,'False')	= 'False'				AND
					(
						@mlproc_id		= 0
							OR
						tmluq.mlproc_id = @mlproc_id
					)															AND
					(
						@bitItemFilter = 'False' OR
						tmp.item_id IS NOT NULL
					)															AND
					CASE	-- MOS 08-2024: Para que se pueda filtrar x un determinado error
						WHEN @ResponseFilter = ''															THEN 1
						WHEN tmluq.mlproc_ProcessedWithErrorDescription LIKE '%' + @ResponseFilter + '%'	THEN 1
						WHEN tmluq.mlproc_response LIKE '%' + @ResponseFilter + '%'							THEN 1
						ELSE																					 0
					END	 = 1

			ORDER BY	-- MMOS 01-2022:
						CASE tmluq.mlproc_blockCancell	-- Primero las que estan en AMARILLO ( Variaciones q tienen ID de articulo PENDIENTE de relacionar
							WHEN 'True'	 THEN 0
							ELSE 1
						END,
						tmluq.mlproc_id DESC

	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_updateQueue_GetDataById]
(
	@comp_id	INT,
	@mlproc_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			tmluq.comp_id,
			tmluq.mlproc_id,
			tmluq.mlp_id,
			tmluq.mlproc_cd,
			tmluq.[user_id],
			tmluq.mlproc_option,
			tmluq.mlproc_stringValue,
			ISNULL(tmluq.mlproc_integerValue,0)						[mlproc_integerValue],
			tmluq.mlproc_decimalValue,
			ISNULL(tmluq.mlproc_isProcessed,'False')				[mlproc_isProcessed],
			tmluq.mlproc_isProcessedCD,
			ISNULL(tmluq.mlproc_isCancelled,'False')				[mlproc_isCancelled],
			tmluq.mlproc_priority,
			tmluq.mlproc_response,
			tmluq.mlproc_isWithError,
			tmluq.mlproc_isWithErrorTryNumber,
			tmluq.mlproc_bigintegerValue,
			ISNULL(tmluq.mlproc_textValue,'')						[mlproc_textValue],
			tmluq.mlproc_imageValue,
			ISNULL(tmluq.mlproc_integerValue2,0)					[mlproc_integerValue2],
			ISNULL(tmluq.mlproc_URL,'')								[mlproc_URL],
			ISNULL(tmluq.mlproc_isProcessedWithError,'False')		[mlproc_isProcessedWithError],
			ISNULL(tmluq.mlproc_ProcessedWithErrorDescription,'')	[mlproc_ProcessedWithErrorDescription],
			ISNULL(tmluq.mlproc_ProcessedWithErrorNumber,'')		[mlproc_ProcessedWithErrorNumber],
			tmluq.mlproc_JSON
			FROM tbMercadoLibre_updateQueue		tmluq		--WITH (NOLOCK)   NO PONERLO !!
			WHERE	tmluq.comp_id	= @comp_id	AND
					tmluq.mlproc_id	= @mlproc_id

	END
