CREATE PROCEDURE [dbo].[spMercadoLibre_updateQueue_getJobsPending]
	@Only4Guid	AS BIT,
	@Guid		AS UNIQUEIDENTIFIER
AS



BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON;



	-- ----------------------------------------------
	-- Testing
	-- ----------------------------------------------
	/*
	DECLARE	@Only4Guid	AS BIT,
			@Guid		AS UNIQUEIDENTIFIER
	SET		@Only4Guid	= 0
	SET 	@Guid		= NEWID()
	*/
	-- ----------------------------------------------



	SELECT	tmluq.comp_id,
			tmluq.mlproc_id,
			tmlip.mls_id,
			tmluq.mlp_id,
			tmluq.mlproc_cd,
			tmluq.[user_id],
			tmluq.mlproc_option,
			tmluq.mlproc_stringValue,
			tmluq.mlproc_integerValue,
			tmluq.mlproc_decimalValue,
			tmluq.mlproc_isProcessed,
			tmluq.mlproc_isProcessedCD,
			tmluq.mlproc_isCancelled,
			tmluq.mlproc_priority,
			dbo.fnStrAllTrim(tmlip.mlp_publicationID)			[mlp_publicationID],
			tmls.mls_clientID,
			tmls.mls_clientSecret,
			tmluq.mlproc_bigintegerValue,
			tmluq.mlproc_textValue,
			tmlip.item_id,
			CASE
				WHEN tmlip.stor_id4StockAvailability IS NOT NULL THEN	tmlip.stor_id4StockAvailability
				ELSE													tmls.stor_id4StockAvailability
			END																								[stor_id4StockAvailability],
			tmluq.mlproc_integerValue2,
			tmls.bra_id,
			ISNULL(tmlip.mlp_allowPublicationsWithNoStock,'False')	[mlp_allowPublicationsWithNoStock],
			tmlip.mlp_initQty,
			ISNULL(tmlip.mlp_price4FreeShipping,0)					[mlp_price4FreeShipping],
			ISNULL(tmlip.mlp_price4AdditionalCost,0)				[mlp_price4AdditionalCost],
			ISNULL(tmlip.mlp_price,0)								[mlp_price],
			CONVERT(DECIMAL(24,6),dbo.fnGetExchange2(tmlip.comp_id,tmlip.mlp_price,tmlip.curr_id,tmls.curr_id,0,0,0,'False'))		[priceInStoreCurrency],   -- MOS 09-2022: le agregue el convert
			tmls.curr_id																					[storeCurrency],
			(
				SELECT COUNT(*)
					FROM tbMercadoLibre_ItemsPublicadosVariations						tmlipv	WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations	tmlipvc	WITH (NOLOCK)
						ON	tmlipvc.comp_id			= tmlipv.comp_id	AND
							tmlipvc.mlpv_id			= tmlipv.mlpv_id
					WHERE	tmlipv.comp_id			= tmlip.comp_id		AND
							tmlipv.mlp_id			= tmlip.mlp_id		AND
							tmlipv.mlpv_disabled	= 'False'
			)														[hasVariations],
			(
				SELECT COUNT(*)
					FROM tbMercadoLibre_ItemsPublicadosVariations						tmlipv	WITH (NOLOCK)
					LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations	    tmlipvc	WITH (NOLOCK)
						ON	tmlipvc.comp_id = tmlipv.comp_id AND
							tmlipvc.mlpv_id = tmlipv.mlpv_id
					WHERE	tmlipv.comp_id	= tmlip.comp_id AND
							tmlipv.mlp_id	= tmlip.mlp_id  AND
							tmlipv.mlpv_disabled = 'False'	AND
							tmlipvc.comp_id IS NULL
			)														[hasVariationsWithPossibleError],
			ISNULL(tmlip.mlp_minQty4Pause,0)						[mlp_minQty4Pause],
			ti.item_code,
			ISNULL(tmlip.mlp_official_store_id,'')					[mls_official_store_id],
			tmls.MLUser_Id,
			ISNULL(tmlip.optval_statusId,0)							[optval_statusId],
			ISNULL(tmlip.prli_id,tmls.prli_id)						[prli_id],
			ISNULL(tmluq.mlproc_isWithErrorTryNumber,0)				[mlproc_isWithErrorTryNumber],
			ISNULL(tmluq.mlproc_internalID,0)						[mlproc_internalID],
			ISNULL(tmls.mls_setPriceToInteger,'False')				[setPriceToInteger],
			ISNULL(tmlip.mlp_video_id,'')							[mlp_video_id],
			ISNULL(tmlip.mlp_priceDirectDiscountPercenage,0)		[mlp_priceDirectDiscountPercenage],
			ISNULL(tmlip.mlp_sold_quantity,0)						[mlp_sold_quantity],
			CASE
				WHEN tmluq.mlproc_option = 21 THEN	0
				ELSE								1
			END														[intPriority]	,
			tmls.mls_accessToken,
			ISNULL(tmlip.mlp_blockPriceUpdate,'False')				[mlp_blockPriceUpdate]	,
			ISNULL(tmlip.mlp_blockPriceUpdate4mercadoShops,'False')	[mlp_blockPriceUpdate4mercadoShops]	,
			ISNULL(tmlip.prli_id4MercadoShop,-1)					[prli_id4MercadoShop],
			ISNULL(tmlip.mlp_channelID,-1)							[mlp_channelID],
			CASE tmluq.mlproc_option	-- MOS 03-2024: NUEVO orden de prioridades
				-- ATENCION: POnerlo en TODOS los UNION !!!!!
				WHEN 48 THEN 888888	-- MLQ_OneOrder_Verification
				WHEN 4	THEN 10		-- MLQO_UpdateAvailableQuantity
				WHEN 8	THEN 10		-- MLQO_Publication_Price			8 y 4 y 7 en el orden en que entraron
				WHEN 7	THEN 10		-- MLQO_Publication_Status
				WHEN 40 THEN 34		-- MLQO_Publication_UpdateTAGS
				WHEN 9	THEN 32		-- MLQO_Publication_ListingType
				WHEN 12 THEN 35     -- MLQO_Publication_ShippingChange
				WHEN 18 THEN 36		-- MLQO_Publication_SetItemAttributes
				WHEN 11 THEN 37		-- MLQO_Publication_InsertSaleOrder
				WHEN 21 THEN 40		-- MLQO_Order_Verification
				WHEN 13 THEN 99		-- MLQO_Order_Qualificate
				WHEN 51 THEN 9999	-- MLQO_Publication_RefreshToken
				ELSE		 1000	-- Prioridades x defecto

			END 													[internalPriority],
			dbo.fnMercadoLibre_getMLValue(tmls.country_id)			[countryML],
			ISNULL(tmlip.mlp_is4FullAndFlex,'False')				[mlp_is4FullAndFlex],
			ISNULL(tmlip.mlp_Aut_Int_Ext_Enabled,'False')			[mlp_Aut_Int_Ext_Enabled],
			ISNULL(tmlip.mlp_Aut_Int_Ext_Percentage,0)				[mlp_Aut_Int_Ext_Percentage]
		FROM tbMercadoLibre_updateQueue tmluq							WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip				WITH (NOLOCK)
			ON	tmlip.comp_id	= tmluq.comp_id AND
				tmlip.mlp_id	= tmluq.mlp_id
		INNER JOIN tbMercadoLibre_Stores			tmls				WITH (NOLOCK)
			ON	tmls.comp_id	= tmlip.comp_id	AND
				tmls.mls_id		= tmlip.mls_id
		INNER JOIN tbItem							ti					WITH (NOLOCK)
			ON  ti.comp_id = tmlip.comp_id AND
				ti.item_id = tmlip.item_id
		WHERE	tmluq.mlproc_isProcessed = 'False'					AND
				tmluq.mlproc_isCancelled = 'False'					AND
				(@Only4Guid = 'False' OR tmluq.mlproc_guid = @Guid)	AND

				-- MOS 04-2023:-- **ewñflm34059230  MOS 04-2023 para que NO borre los que están con error y no procesados por estar en deal
				-- ISNULL(tmluq.mlproc_isWithErrorTryNumber,0) <= 10
				CASE
					WHEN ISNULL(tmluq.mlproc_isWithErrorTryNumber,0) <= 10		THEN 1
					WHEN mlproc_response  LIKE '%item.price.freezed_by_deal%'	THEN 1
					ELSE 0
				END = 1												AND
				tmluq.mlproc_option <> 11							AND
				tmluq.mlproc_option <> 14							AND
				tmluq.mlproc_option <> 54							AND	-- MOS 07-2024
				tmluq.mlproc_option <> 23							AND
				CASE
					WHEN tmluq.mlproc_option <> 1 AND ISNULL(tmlip.mlp_publicationID,'') <> '' THEN 1
					WHEN tmluq.mlproc_option <> 1 AND ISNULL(tmlip.mlp_publicationID,'') =  '' THEN 0
					WHEN tmluq.mlproc_option =  1 AND ISNULL(tmlip.mlp_publicationID,'') =  '' THEN 1
					ELSE																		    0
				END = 1												AND
				tmls.mls_disabled		= 'False'					AND
				tmlip.optval_statusId		 <> 10		-- No DesEnlazada



		UNION ALL


	-- Proceso de PEDIDOS pendientes
	SELECT	tmluq.comp_id,
			tmluq.mlproc_id,
			tmlip.mls_id,
			tmluq.mlp_id,
			tmluq.mlproc_cd,
			tmluq.[user_id],
			tmluq.mlproc_option,
			tmluq.mlproc_stringValue,
			tmluq.mlproc_integerValue,
			tmluq.mlproc_decimalValue,
			tmluq.mlproc_isProcessed,
			tmluq.mlproc_isProcessedCD,
			tmluq.mlproc_isCancelled,
			-999999999 + tmluq.mlproc_priority,
			dbo.fnStrAllTrim(tmlip.mlp_publicationID)			[mlp_publicationID],
			tmls.mls_clientID,
			tmls.mls_clientSecret,
			tmluq.mlproc_bigintegerValue,
			tmluq.mlproc_textValue,
			tmlip.item_id,
			CASE
				WHEN tmlip.stor_id4StockAvailability IS NOT NULL THEN	tmlip.stor_id4StockAvailability
				ELSE													tmls.stor_id4StockAvailability
			END																								[stor_id4StockAvailability],
			tmluq.mlproc_integerValue2,
			tmls.bra_id,
			ISNULL(tmlip.mlp_allowPublicationsWithNoStock,'False')	[mlp_allowPublicationsWithNoStock],
			tmlip.mlp_initQty,
			ROUND(ISNULL(tmlip.mlp_price4FreeShipping,0),2)			[mlp_price4FreeShipping],
			ROUND(ISNULL(tmlip.mlp_price4AdditionalCost,0),2)		[mlp_price4AdditionalCost],
			ISNULL(tmlip.mlp_price,0)								[mlp_price],
			CONVERT(DECIMAL(24,6),dbo.fnGetExchange2(tmlip.comp_id,tmlip.mlp_price,tmlip.curr_id,ISNULL(tmls.curr_id,tmlip.curr_id),0,0,0,'False'))		[priceInStoreCurrency],	-- MOS 09-2022: le agregue el convert
			ISNULL(tmls.curr_id,tmlip.curr_id)																						[storeCurrency],
			(
				SELECT COUNT(*)
					FROM tbMercadoLibre_ItemsPublicadosVariations						tmlipv	WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations	tmlipvc	WITH (NOLOCK)
						ON	tmlipvc.comp_id = tmlipv.comp_id AND
							tmlipvc.mlpv_id = tmlipv.mlpv_id
					WHERE	tmlipv.comp_id	= tmlip.comp_id AND
							tmlipv.mlp_id	= tmlip.mlp_id	AND
							tmlipv.mlpv_disabled = 'False'
			)														[hasVariations],
			(
				SELECT COUNT(*)
					FROM tbMercadoLibre_ItemsPublicadosVariations						tmlipv	WITH (NOLOCK)
					LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations	    tmlipvc	WITH (NOLOCK)
						ON	tmlipvc.comp_id = tmlipv.comp_id AND
							tmlipvc.mlpv_id = tmlipv.mlpv_id
					WHERE	tmlipv.comp_id	= tmlip.comp_id AND
							tmlipv.mlp_id	= tmlip.mlp_id  AND
							tmlipv.mlpv_disabled = 'False'	AND
							tmlipvc.comp_id IS NULL
			)														[hasVariationsWithPossibleError],
			ISNULL(tmlip.mlp_minQty4Pause,0)						[mlp_minQty4Pause],
			ISNULL(ti.item_code,'')									[item_code],
			ISNULL(tmlip.mlp_official_store_id,'')					[mls_official_store_id],
			tmls.MLUser_Id,
			ISNULL(tmlip.optval_statusId,0)							[optval_statusId],
			ISNULL(tmlip.prli_id,tmls.prli_id)						[prli_id],
			ISNULL(tmluq.mlproc_isWithErrorTryNumber,0)				[mlproc_isWithErrorTryNumber],
			ISNULL(tmluq.mlproc_internalID,0)						[mlproc_internalID],
			ISNULL(tmls.mls_setPriceToInteger,'False')				[setPriceToInteger],
			ISNULL(tmlip.mlp_video_id,'')							[mlp_video_id],
			ISNULL(tmlip.mlp_priceDirectDiscountPercenage,0)		[mlp_priceDirectDiscountPercenage],
			ISNULL(tmlip.mlp_sold_quantity,0)						[mlp_sold_quantity],
			CASE
				WHEN tmluq.mlproc_option = 21 THEN	0
				ELSE								1
			END														[intPriority],
			tmls.mls_accessToken,
			ISNULL(tmlip.mlp_blockPriceUpdate,'False')				[mlp_blockPriceUpdate]	,
			ISNULL(tmlip.mlp_blockPriceUpdate4mercadoShops,'False')	[mlp_blockPriceUpdate4mercadoShops]	,
			ISNULL(tmlip.prli_id4MercadoShop,-1)					[prli_id4MercadoShop]	,
			ISNULL(tmlip.mlp_channelID,-1)							[mlp_channelID]	,
			CASE tmluq.mlproc_option	-- MOS 03-2024: NUEVO orden de prioridades
				-- ATENCION: POnerlo en TODOS los UNION !!!!!
				WHEN 48 THEN 888888	-- MLQ_OneOrder_Verification
				WHEN 4	THEN 10		-- MLQO_UpdateAvailableQuantity
				WHEN 8	THEN 10		-- MLQO_Publication_Price			8 y 4 y 7 en el orden en que entraron
				WHEN 7	THEN 10		-- MLQO_Publication_Status
				WHEN 40 THEN 32		-- MLQO_Publication_UpdateTAGS
				WHEN 9	THEN 34		-- MLQO_Publication_ListingType
				WHEN 12 THEN 35     -- MLQO_Publication_ShippingChange
				WHEN 18 THEN 36		-- MLQO_Publication_SetItemAttributes
				WHEN 11 THEN 37		-- MLQO_Publication_InsertSaleOrder
				WHEN 21 THEN 40		-- MLQO_Order_Verification
				WHEN 13 THEN 99		-- MLQO_Order_Qualificate
				WHEN 51 THEN 9999	-- MLQO_Publication_RefreshToken
				ELSE		 1000	-- Prioridades x defecto

			END 													[internalPriority],
			dbo.fnMercadoLibre_getMLValue(tmls.country_id)			[countryML],
			ISNULL(tmlip.mlp_is4FullAndFlex,'False')				[mlp_is4FullAndFlex],
			ISNULL(tmlip.mlp_Aut_Int_Ext_Enabled,'False')			[mlp_Aut_Int_Ext_Enabled],
			ISNULL(tmlip.mlp_Aut_Int_Ext_Percentage,0)				[mlp_Aut_Int_Ext_Percentage]

		FROM tbMercadoLibre_updateQueue tmluq				WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_Stores			tmls	WITH (NOLOCK)
			ON	tmls.comp_id	= tmluq.comp_id	AND
				tmls.mls_id		= tmluq.mlproc_integerValue
		-- Al pedo
		LEFT JOIN tbMercadoLibre_ItemsPublicados	tmlip	WITH (NOLOCK)
			ON	tmlip.comp_id	= tmluq.comp_id AND
				tmlip.mlp_id	= tmluq.mlp_id
		LEFT JOIN tbItem							ti					WITH (NOLOCK)
			ON  ti.comp_id = tmlip.comp_id AND
				ti.item_id = tmlip.item_id
		WHERE	tmluq.mlproc_isProcessed = 'False'	AND
				tmluq.mlproc_isCancelled = 'False'	AND
				(@Only4Guid = 'False' OR tmluq.mlproc_guid = @Guid)	AND  -- MOS 11-2021
				tmluq.mlproc_option		 IN (11,48,49,   50,51)		AND		-- MOS 10-2023: 51 y puse el 50 que NADIE miro NUNCA que funcione!!!!!
				tmls.mls_disabled		 = 'False'	--AND
				--tmlip.optval_statusId		 <> 10		-- No DesEnlazada   NOOOOOOOOOOOOOOOOOOOOOOOOOO

	UNION ALL

	-- Proceso de Mensajeria post venta
	SELECT	tmluq.comp_id,
			tmluq.mlproc_id,
			tmlip.mls_id,
			tmluq.mlp_id,
			tmluq.mlproc_cd,
			tmluq.[user_id],
			tmluq.mlproc_option,
			tmluq.mlproc_stringValue,
			tmluq.mlproc_integerValue,
			tmluq.mlproc_decimalValue,
			tmluq.mlproc_isProcessed,
			tmluq.mlproc_isProcessedCD,
			tmluq.mlproc_isCancelled,
			-999999999 + tmluq.mlproc_priority,
			dbo.fnStrAllTrim(tmlip.mlp_publicationID)			[mlp_publicationID],
			tmls.mls_clientID,
			tmls.mls_clientSecret,
			tmluq.mlproc_bigintegerValue,
			tmluq.mlproc_textValue,
			tmlip.item_id,
			CASE
				WHEN tmlip.stor_id4StockAvailability IS NOT NULL THEN	tmlip.stor_id4StockAvailability
				ELSE													tmls.stor_id4StockAvailability
			END																								[stor_id4StockAvailability],
			tmluq.mlproc_integerValue2,
			tmls.bra_id,
			ISNULL(tmlip.mlp_allowPublicationsWithNoStock,'False')	[mlp_allowPublicationsWithNoStock],
			tmlip.mlp_initQty,
			ROUND(ISNULL(tmlip.mlp_price4FreeShipping,0),2)			[mlp_price4FreeShipping],
			ROUND(ISNULL(tmlip.mlp_price4AdditionalCost,0),2)		[mlp_price4AdditionalCost],
			ISNULL(tmlip.mlp_price,0)								[mlp_price],
			CONVERT(DECIMAL(24,6),dbo.fnGetExchange2(tmlip.comp_id,tmlip.mlp_price,tmlip.curr_id,ISNULL(tmls.curr_id,tmlip.curr_id),0,0,0,'False'))		[priceInStoreCurrency],	-- MOS 09-2022: le agregue el convert
			ISNULL(tmls.curr_id,tmlip.curr_id)																						[storeCurrency],
			(
				SELECT COUNT(*)
					FROM tbMercadoLibre_ItemsPublicadosVariations						tmlipv	WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations	tmlipvc	WITH (NOLOCK)
						ON	tmlipvc.comp_id = tmlipv.comp_id AND
							tmlipvc.mlpv_id = tmlipv.mlpv_id
					WHERE	tmlipv.comp_id	= tmlip.comp_id AND
							tmlipv.mlp_id	= tmlip.mlp_id	AND
							tmlipv.mlpv_disabled = 'False'
			)														[hasVariations],
			(
				SELECT COUNT(*)
					FROM tbMercadoLibre_ItemsPublicadosVariations						tmlipv	WITH (NOLOCK)
					LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations_Combinations	    tmlipvc	WITH (NOLOCK)
						ON	tmlipvc.comp_id = tmlipv.comp_id AND
							tmlipvc.mlpv_id = tmlipv.mlpv_id
					WHERE	tmlipv.comp_id	= tmlip.comp_id AND
							tmlipv.mlp_id	= tmlip.mlp_id  AND
							tmlipv.mlpv_disabled = 'False'	AND
							tmlipvc.comp_id IS NULL
			)														[hasVariationsWithPossibleError],
			ISNULL(tmlip.mlp_minQty4Pause,0)						[mlp_minQty4Pause],
			ISNULL(ti.item_code,'')									[item_code],
			ISNULL(tmlip.mlp_official_store_id,'')					[mls_official_store_id],
			tmls.MLUser_Id,
			ISNULL(tmlip.optval_statusId,0)							[optval_statusId],
			ISNULL(tmlip.prli_id,tmls.prli_id)						[prli_id],
			ISNULL(tmluq.mlproc_isWithErrorTryNumber,0)				[mlproc_isWithErrorTryNumber],
			ISNULL(tmluq.mlproc_internalID,0)						[mlproc_internalID],
			ISNULL(tmls.mls_setPriceToInteger,'False')				[setPriceToInteger],
			ISNULL(tmlip.mlp_video_id,'')							[mlp_video_id],
			ISNULL(tmlip.mlp_priceDirectDiscountPercenage,0)		[mlp_priceDirectDiscountPercenage],
			ISNULL(tmlip.mlp_sold_quantity,0)						[mlp_sold_quantity],
			CASE
				WHEN tmluq.mlproc_option = 21 THEN	0
				ELSE								1
			END														[intPriority], -- MOS 03-2024: NO se va a usar mas abajo para ordenar, se pone todo en el case de mas abajo
			tmls.mls_accessToken,
			ISNULL(tmlip.mlp_blockPriceUpdate,'False')				[mlp_blockPriceUpdate]		,
			ISNULL(tmlip.mlp_blockPriceUpdate4mercadoShops,'False')	[mlp_blockPriceUpdate4mercadoShops]		,
			ISNULL(tmlip.prli_id4MercadoShop,-1)					[prli_id4MercadoShop],
			ISNULL(tmlip.mlp_channelID,-1)							[mlp_channelID]	,
			CASE tmluq.mlproc_option	-- MOS 03-2024: NUEVO orden de prioridades
				-- ATENCION: POnerlo en TODOS los UNION !!!!!
				WHEN 48 THEN 888888	-- MLQ_OneOrder_Verification
				WHEN 4	THEN 10		-- MLQO_UpdateAvailableQuantity
				WHEN 8	THEN 10		-- MLQO_Publication_Price			8 y 4 y 7 en el orden en que entraron
				WHEN 7	THEN 10		-- MLQO_Publication_Status
				WHEN 40 THEN 32		-- MLQO_Publication_UpdateTAGS
				WHEN 9	THEN 34		-- MLQO_Publication_ListingType
				WHEN 12 THEN 35     -- MLQO_Publication_ShippingChange
				WHEN 18 THEN 36		-- MLQO_Publication_SetItemAttributes
				WHEN 11 THEN 37		-- MLQO_Publication_InsertSaleOrder
				WHEN 21 THEN 40		-- MLQO_Order_Verification
				WHEN 13 THEN 99		-- MLQO_Order_Qualificate
				WHEN 51 THEN 9999	-- MLQO_Publication_RefreshToken
				ELSE		 1000	-- Prioridades x defecto

			END 													[internalPriority],
			dbo.fnMercadoLibre_getMLValue(tmls.country_id)			[countryML],
			ISNULL(tmlip.mlp_is4FullAndFlex,'False')				[mlp_is4FullAndFlex],
			ISNULL(tmlip.mlp_Aut_Int_Ext_Enabled,'False')			[mlp_Aut_Int_Ext_Enabled],
			ISNULL(tmlip.mlp_Aut_Int_Ext_Percentage,0)				[mlp_Aut_Int_Ext_Percentage]

		FROM tbMercadoLibre_updateQueue tmluq				WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_ordersHeader		tmloh	WITH (NOLOCK)
			ON	tmloh.comp_id	= tmluq.comp_id	AND
				tmloh.mlo_id	= tmluq.mlproc_integerValue
		INNER JOIN tbMercadoLibre_Stores			tmls	WITH (NOLOCK)
			ON	tmls.comp_id	= tmloh.comp_id	AND
				tmls.mls_id		= tmloh.mls_id
		-- Al pedo
		LEFT JOIN tbMercadoLibre_ItemsPublicados	tmlip	WITH (NOLOCK)
			ON	tmlip.comp_id	= tmluq.comp_id AND
				tmlip.mlp_id	= tmluq.mlp_id
		LEFT JOIN tbItem							ti					WITH (NOLOCK)
			ON  ti.comp_id = tmlip.comp_id AND
				ti.item_id = tmlip.item_id
		WHERE	tmluq.mlproc_isProcessed = 'False'	AND
				tmluq.mlproc_isCancelled = 'False'	AND
				tmluq.mlproc_option		 IN (14,23,54)	AND		-- MOS 07-2024: puse el 54
				(@Only4Guid = 'False' OR tmluq.mlproc_guid = @Guid)	AND  -- MOS 11-2021
				tmls.mls_disabled		 = 'False'	AND
				ISNULL(tmluq.mlproc_isWithErrorTryNumber,0) <= 15



		ORDER BY	ISNULL(tmluq.mlproc_isWithErrorTryNumber,0)	,		-- MOS 03-2024: Lo pongo ARRIBA para que 1ro se procesen las que NO tuvieron errores anteriores
						--tmluq.comp_id			ASC,						-- MOS 03-2024, al pedo
					internalPriority		ASC,
						--intPriority,										-- MOS 03-2024, de puso en internalPriority
						--ISNULL(tmluq.mlproc_isWithErrorTryNumber,0)	,   MOS 03-2024: Lo pongo ARRIBA para que 1ro se procesen as que NO uvieron error

					tmluq.mlproc_priority	ASC,
					tmluq.mlproc_id			DESC

END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_updateQueue_InsertAllPublications4FastStockAdjustmentCheck]
(
	@comp_id	INT,
	@lang_id	INT,
	@user_id	INT,
	@item_id	INT,
	@qty		INT,
	@guid		UNIQUEIDENTIFIER
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ----------------------------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@user_id	INT,
				@item_id	INT,
				@qty		INT,
				@guid		UNIQUEIDENTIFIER
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@user_id	= 134,
				@item_id	= 15549,
				@qty		= 10,
				@guid		= 'f202e88f-16c0-4223-9ae7-94feb15688f4'
		*/
		-- ----------------------------------------------------------------------

		-- ----------------------------------------------------------------------
		-- Tabla Temporal con todas las publicaciones de ML que tengan
		-- el ITEM_ID que viene por parámetro y a su vez se encuentren
		-- activas
		-- ----------------------------------------------------------------------
			DECLARE @tblMercadoLibre_ItemsPublicados TABLE (comp_id INT,
															mlp_id INT PRIMARY KEY)
			INSERT INTO @tblMercadoLibre_ItemsPublicados
			(
				comp_id,
				mlp_id
			)
			-- SOLO INSERTO LOS ID DE LOS ARTICULOS QUE SE ENCUENTREN ACTIVOS
			SELECT
				tmlip.comp_id,
				tmlip.mlp_id
			FROM tbMercadoLibre_ItemsPublicados						tmlip		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_Stores						tmls		WITH (NOLOCK)
				ON	tmls.comp_id = tmlip.comp_id AND
					tmls.mls_id  = tmlip.mls_id
			WHERE	tmlip.comp_id						= @comp_id	AND
					tmlip.item_id						= @item_id	AND
					ISNULL(tmlip.mlp_Active,'False')	= 'True'	AND
					ISNULL(tmls.mls_disabled,'False')	= 'False'
		-- ----------------------------------------------------------------------

		-- ----------------------------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- ----------------------------------------------------------------------
			DECLARE
				@mlproc_option	INT
			SET @mlproc_option	= 4
		-- ----------------------------------------------------------------------


		-- ----------------------------------------------------------------------
		-- INSERTO TODOS LOS ID DE PUBLICACION QUE CONTENGAN EL ARTÏCULO AL
		-- CUAL SE LE MODIFICÖ EL STOCK
		-- ----------------------------------------------------------------------
			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				[user_id],
				mlproc_option,
				mlproc_stringValue,
				mlproc_integerValue,
				mlproc_decimalValue,
				mlproc_priority,
				mlproc_guid,
				mlproc_bigintegerValue,
				mlproc_textValue,
				mlproc_integerValue2,
				mlproc_internalID
			)
			SELECT
				tmp.comp_id,
				tmp.mlp_id,
				@user_id,
				@mlproc_option,
				'',
				@qty,
				0,
				0,
				@guid,
				0,
				'',
				0,
				8798541			-- MOS 03-2022
			FROM @tblMercadoLibre_ItemsPublicados	tmp
		-- ----------------------------------------------------------------------

	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_UpdateQueue_InsertData4OrderRegeneration]
(
	@comp_id		INT,
	@user_id		INT,
	@option			INT,
	@intValue		INT,
	@biginitValue	BIGINT,
	@guid			UNIQUEIDENTIFIER
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
		DECLARE
			@comp_id		INT,
			@user_id		INT,
			@option			INT,
			@intValue		INT,
			@biginitValue	INT,
			@guid			UNIQUEIDENTIFIER
		*/
		-- -------------------------------------------



		-- -------------------------------------------
		-- Si se pide Reprocesar Todos los Pedidos
		-- -------------------------------------------
		IF @option = 21
			BEGIN

				IF NOT EXISTS (
									SELECT TOP 1 1
										FROM tbMercadoLibre_updateQueue AS tmluq	WITH (NOLOCK)
										WHERE	tmluq.comp_id				= @comp_id AND
												tmluq.mlproc_option			= @option AND
												tmluq.mlproc_isProcessed	= 0 AND
												tmluq.mlproc_isCancelled	= 0
							)
					BEGIN

						DECLARE @mlp_id AS INT = -1
						SELECT TOP 1  @mlp_id		= tmlip.mlp_id,
									  @biginitValue = TMLS.MLUser_Id
							FROM tbMercadoLibre_ItemsPublicados AS tmlip	WITH (NOLOCK)
							INNER JOIN tbMercadoLibre_Stores	AS tmls		WITH (NOLOCK)
								ON	tmls.comp_id	= tmlip.comp_id AND
									TMLS.mls_id		= TMLIP.mls_id
							WHERE	tmlip.comp_id	= @comp_id		AND
									tmlip.mls_id	= @intValue		AND
									tmlip.mlp_Active = 1 AND
									tmlip.optval_statusId = 2

						INSERT INTO tbMercadoLibre_updateQueue
						(
							comp_id,
							mlp_id,
							[user_id],
							mlproc_option,
							mlproc_integerValue,
							mlproc_guid,
							mlproc_bigintegerValue,
							mlproc_internalID
						)
						VALUES
						(
							@comp_id,
							@mlp_id,
							@user_id,
							@option,
							@intValue,
							@guid,
							@biginitValue,
							90013
						)
					END

				RETURN
			END
		-- -------------------------------------------










		-- -------------------------------------------
		-- Reprocesar solo UNA ORDEN
		-- -------------------------------------------
		INSERT INTO tbMercadoLibre_updateQueue
		(
			comp_id,
			[user_id],
			mlproc_option,
			mlproc_integerValue,
			mlproc_guid,
			mlproc_bigintegerValue
		)
		VALUES
		(
			@comp_id,
			@user_id,
			@option,
			@intValue,
			@guid,
			@biginitValue
		)

		IF @option <> 48
			BEGIN
				INSERT INTO tbMercadoLibre_updateQueue
				(
					comp_id,
					[user_id],
					mlproc_option,
					mlproc_integerValue,
					mlproc_guid,
					mlproc_bigintegerValue,
					mlproc_priority,
					mlproc_internalID
				)
				VALUES
				(
					@comp_id,
					@user_id,
					11,
					@intValue,
					@guid,
					@biginitValue,
					99999999,
					8798641			-- MOS 03-2022
				)
			END
		-- -------------------------------------------



	END


GO

CREATE PROCEDURE [dbo].[spMercadoLibre_UpdateQueue_InsertData4PriceListActualizations]
(
	@comp_id					INT,
	@user_id					INT,
	@guid						UNIQUEIDENTIFIER,
	@prli_id					INT,
	@item_code					NVARCHAR(50),
	@intoptionprice				INT,			--1 : Precios Sin Impuestos , 2 : Precios con Impuesto al Valor Agregado
	@intoptioncode				INT,			--1 : Código / EAN o EAN Adicional , 2 : Código de Fabricante, 3 : COdigo Adicional
	@price						DECIMAL(19,5),
	@supp_id					INT,
	@chkAllowNegativeImport		BIT				--  : Permitir grabar importes menor o igual a 0.
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@user_id	INT,
				@guid		UNIQUEIDENTIFIER,
				@prli_id	INT,
				@item_id	INT,
				@price		DECIMAL(19,2)
		*/
		-- -------------------------------------------------

		-- -------------------------------------------------------------------------------------------------------
		--Recuperamos el item_id mediante el codigo
		DECLARE @litem_id AS INT
		DECLARE @tmpTable TABLE(item_id INT PRIMARY KEY)


		IF @intoptioncode = 1  --Código / EAN o EAN Adicional
			BEGIN

				SELECT
					TOP 1 @litem_id = ti.item_id
					FROM tbitem				ti	WITH (NOLOCK)
					LEFT JOIN tbItemEAN		tie	WITH(NOLOCK)--17/10/16
						ON	tie.comp_id = ti.comp_id AND
							tie.item_id = ti.item_id
					WHERE	ti.comp_id		= @comp_id								AND
							(ti.item_code = @item_code OR tie.ie_ean = @item_code)	AND --17/10/16
							@price			<> -1									AND
						  (
	  						@supp_id = -1 OR
	  						ti.supp_id = @supp_id OR
	  						EXISTS (
	  								SELECT 1 FROM tbItemSupplier tis	WITH (NOLOCK)
	  									WHERE tis.comp_id = @comp_id	AND
	  										  tis.item_id = ti.item_id	AND
	  										  tis.supp_id = @supp_id

	  								)
						  )


				IF @chkAllowNegativeImport ='False' AND @price <= 0 SET @litem_id = NULL

				IF @litem_id IS NOT NULL
					BEGIN
						INSERT INTO @tmpTable(item_id) VALUES (@litem_id)
					END

			END
		ELSE

			IF @intoptioncode = 2 --Código de Fabricante
				BEGIN

					INSERT INTO @tmpTable(item_id)
					SELECT
						ti.item_id
						FROM tbitem				ti	WITH (NOLOCK)
						WHERE	ti.comp_id			= @comp_id		AND
								(ti.item_vendorCode = @item_code )	AND
								@price				<> -1			AND
							  (
	  							@supp_id = -1 OR
	  							ti.supp_id = @supp_id OR
	  							EXISTS (
	  									SELECT TOP 1 1
	  										FROM tbItemSupplier tis	WITH (NOLOCK)
	  										WHERE tis.comp_id = @comp_id	AND
	  											  tis.item_id = ti.item_id	AND
	  											  tis.supp_id = @supp_id

	  									)
							  )

					IF (@chkAllowNegativeImport ='False' AND @price <= 0) SET @litem_id = NULL


				END

				ELSE

					BEGIN
						--Código Alternativo/Adicional
						SELECT
							TOP 1 @litem_id = ti.item_id
							FROM tbitem				ti	WITH (NOLOCK)
							LEFT JOIN tbItemEAN		tie	WITH(NOLOCK)
								ON	tie.comp_id = ti.comp_id AND
									tie.item_id = ti.item_id

							WHERE	ti.comp_id				= @comp_id								AND
									ti.item_codeAlternative = @item_code 							AND
									@price					<> -1									AND
								  (
	  								@supp_id = -1 OR
	  								ti.supp_id = @supp_id OR
	  								EXISTS (
	  										SELECT TOP 1  1 FROM tbItemSupplier tis	WITH (NOLOCK)
	  											WHERE tis.comp_id = @comp_id	AND
	  												  tis.item_id = ti.item_id	AND
	  												  tis.supp_id = @supp_id

	  										)
								  )

						IF @chkAllowNegativeImport ='False' AND @price <= 0 SET @litem_id = NULL

						IF @litem_id IS NOT NULL
							BEGIN
								INSERT INTO @tmpTable(item_id) VALUES (@litem_id)
							END
					END
		-- -------------------------------------------------------------------------------------------------------

		IF @intoptionprice = 2 --Opcion 2 con IVA es
			BEGIN
				SET @price = @price / dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,@litem_id))
			END


		INSERT INTO tbMercadoLibre_updateQueue
		(
			comp_id,
			--mlproc_id,
			mlp_id,
			mlproc_cd,
			[user_id],
			mlproc_option,
			mlproc_stringValue,
			mlproc_integerValue,
			mlproc_decimalValue,
			mlproc_isProcessed,
			mlproc_isCancelled,
			mlproc_priority,
			mlproc_isWithError,
			mlproc_isWithErrorTryNumber,
			mlproc_guid,
			mlproc_internalID
		)
		SELECT
			tmlip.comp_id,
			tmlip.mlp_id,
			GETDATE(),
			@user_id,
			8,
			'',
			0,
			@price,
			'False',
			'False',
			0,
			0,
			0,
			@guid	,
			8798751			-- MOS 03-2022
			FROM tbMercadoLibre_ItemsPublicados				tmlip	WITH(NOLOCK)
				INNER JOIN tbMercadoLibre_Stores			tmls	WITH(NOLOCK)
				ON	tmls.comp_id			= tmlip.comp_id AND
					tmls.mls_id				= tmlip.mls_id
				INNER JOIN @tmpTable					tbItems
				ON	tbItems.item_id			= tmlip.item_id
			WHERE	tmlip.comp_id			= @comp_id		AND
					tmlip.prli_id			= @prli_id		AND
					tmls.mls_disabled		= 'False'		AND
					tmlip.optval_statusId	= 2 -- PUBLICADA

	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_UpdateQueue_InsertData4StorageUpdate]
(
	@comp_id	INT,
	@user_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@item_id	INT,
	@stor_id	INT,
	@qty		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@user_id	INT,
				@guid		UNIQUEIDENTIFIER,
				@item_id	INT,
				@stor_id	INT,
				@qty		INT
		*/
		-- -----------------------------------------------------

		INSERT INTO tbMercadoLibre_updateQueue
		(
			comp_id,
			mlp_id,
			mlproc_cd,
			[user_id],
			mlproc_option,
			mlproc_integerValue,
			mlproc_isProcessed,
			mlproc_priority,
			mlproc_guid	,
			mlproc_internalID
		)
		SELECT
			tmlip.comp_id,
			tmlip.mlp_id,
			GETDATE(),
			@user_id,
			4,
			@qty,
			'False',
			0,
			@guid,
			8793247			-- MOS 03-2022
			FROM tbMercadoLibre_ItemsPublicados				tmlip	WITH(NOLOCK)
			INNER JOIN tbMercadoLibre_Stores				tmls	WITH(NOLOCK)
				ON	tmls.comp_id			= tmlip.comp_id AND
					tmls.mls_id				= tmlip.mls_id
			LEFT JOIN tbMercadoLibre_updateQueue		 AS tmluq	WITH (NOLOCK)	-- MOS 05-2024: para que no inserte duplicados AL PEDO ( mccars )
				ON  tmluq.comp_id				= tmlip.comp_id AND
					tmluq.mlp_id				= tmlip.mlp_id AND
					tmluq.mlproc_option			= 4 AND
					tmluq.mlproc_isProcessed	= 0 AND
					tmluq.mlproc_isCancelled	= 0
			WHERE	tmlip.comp_id			= @comp_id		AND
					tmlip.item_id			= @item_id		AND
					tmls.mls_disabled		= 'False'		AND
					tmlip.optval_statusId	= 2				AND -- PUBLICADA
					tmluq.comp_id IS NULL

	END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_updateQueue_InsertJobsPending]
(
	@comp_id						INT,
	@mlp_id							INT,
	@user_id						INT,
	@mlproc_option					INT,
	@mlproc_stringValue				NVARCHAR(4000),
	@mlproc_integerValue			INT,
	@mlproc_decimalValue			DECIMAL(19,4),
	@mlproc_priority				INT,
	@guid							UNIQUEIDENTIFIER,
	@mlproc_bigIntegerValue			BIGINT,
	@mlproc_textValue				NVARCHAR(MAX),
	@mlproc_integerValue2			INT,
	@mlproc_internalID				INT,
	@return_value					INT OUTPUT
)
AS
	BEGIN
		SET	NOCOUNT ON

		IF @mlp_id <= 0
			BEGIN
				SET @mlp_id = NULL
			END

		DECLARE @bitDoIt AS BIT = 'True'		-- Solo INSERTA si la tienda esta HABILITADA
		IF @mlp_id > 0
			BEGIN
				SELECT @bitDoIt =	CASE
				                 	    WHEN tmls.mls_disabled = 'True'  THEN 'False'
				                 	    ELSE								  'True'
				                 	END
					FROM tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_Stores	tmls		WITH (NOLOCK)
						ON	TMLIP.comp_id	= TMLS.comp_id AND
							TMLIP.mls_id	= tmls.mls_id
					WHERE	tmlip.comp_id	= @comp_id AND
							tmlip.mlp_id	= @mlp_id
			END


		IF @bitDoIt = 'True'
			BEGIN


				-- Si es Estado, Stock o Precio y YA hay uno para esta publicacion, NO lo guarda dos veces.
				IF @mlproc_option IN (4,7,8)	AND
					EXISTS(
								SELECT TOP 1 1
									FROM tbMercadoLibre_updateQueue tmluq	WITH (NOLOCK)
									WHERE	tmluq.comp_id				= @comp_id			AND
											tmluq.mlp_id				= @mlp_id			AND
											tmluq.mlproc_option			= @mlproc_option	AND
											tmluq.mlproc_isProcessed	= 0					AND
											tmluq.mlproc_isCancelled	= 0
							)
					BEGIN
						SET @return_value = -1
						RETURN
					END


				INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
				(
					comp_id,
					mlp_id,
					[user_id],
					mlproc_option,
					mlproc_stringValue,
					mlproc_integerValue,
					mlproc_decimalValue,
					mlproc_priority,
					mlproc_isProcessed,
					mlproc_isCancelled,
					mlproc_guid,
					mlproc_bigintegerValue,
					mlproc_textValue,
					mlproc_integerValue2,
					mlproc_internalID
				)
				VALUES
				(
					@comp_id,
					@mlp_id,
					@user_id,
					@mlproc_option,
					@mlproc_stringValue,
					@mlproc_integerValue,
					@mlproc_decimalValue,
					@mlproc_priority,
					'False',
					'False',
					@guid,
					@mlproc_bigIntegerValue,
					@mlproc_textValue,
					@mlproc_integerValue2,
					@mlproc_internalID
				)
				SET @return_value = @@IDENTITY

			END
		ELSE
			BEGIN
				SET @return_value = -1
			END


	END
GO





