-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spMercadoLibre_updateQueue_updateClosedPublication]
	@comp_id				AS INT,
	@mlproc_id				AS INT,
	@strResponse			AS NVARCHAR(4000),
	@bitIsOK				AS BIT,
	@mlproc_URL				AS NVARCHAR(500),
	@mlproc_JSON			AS NVARCHAR(4000),
	@mlproc_ProcessedWithErrorNumber		AS INT,
	@mlproc_ProcessedWithErrorDescription	AS NVARCHAR(4000)
AS
BEGIN


	-- ---------------------------------------------------------------------------------------------------------------------------
	--  NOTA IMPORTANTE:
	--  Si se dio de baja una publicacion y el sistema nunca se enteró, la pone como dada de baja y borra todo lo pendiente
	--  de procesar
	-- ---------------------------------------------------------------------------------------------------------------------------


	SET NOCOUNT ON;

	DECLARE
	@ret_ErrorCode			AS INT			,
	@ret_ErrorDescription	AS NVARCHAR(1000)
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''


	DECLARE @mlproc_option		AS INT
	DECLARE @mlp_id				AS INT
	DECLARE @mls_id				AS INT

	SELECT
			@mlproc_option		= tmluq.mlproc_option,
			@mlp_id				= tmluq.mlp_id
		FROM tbMercadoLibre_updateQueue				tmluq	WITH (NOLOCK)
		WHERE	tmluq.comp_id	= @comp_id AND
				tmluq.mlproc_id = @mlproc_id


	SELECT
			@mls_id				= tmlip.mls_id
		FROM tbMercadoLibre_ItemsPublicados	tmlip	WITH (NOLOCK)
		WHERE	tmlip.comp_id   = @comp_id		AND
				tmlip.mlp_id	= @mlp_id


	-- Pongo como CERRADA a la publicacion
	UPDATE tbMercadoLibre_ItemsPublicados	WITH (ROWLOCK)
		SET	optval_statusId = 5,
			mlp_Active		= 'False'
		WHERE	comp_id = @comp_id AND
				mlp_id	= @mlp_id


	-- Saco toda la mierda que aun tenga pendiente para procesar
	UPDATE tbMercadoLibre_updateQueue			WITH (ROWLOCK)
		SET		mlproc_isCancelled						= 1,
				mlproc_isProcessed						= 1,
				mlproc_isProcessedWithError				= 1,
				mlproc_ProcessedWithErrorDescription	= '* Publicación Cerrada *   ' + mlproc_ProcessedWithErrorDescription
		WHERE	comp_id				= @comp_id	AND
				mlp_id				= @mlp_id	AND
				mlproc_isProcessed	= 0




	SELECT  @ret_ErrorCode			[ret_ErrorCode],
			@ret_ErrorDescription	[ret_ErrorDescription]



END
GO


-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spMercadoLibre_updateQueue_updateJobsPending]
	@comp_id				AS INT,
	@mlproc_id				AS INT,
	@strResponse			AS VARCHAR(MAX),
	--@strResponse			AS NVARCHAR(MAX),
	@bitIsOK				AS BIT,
	@mlproc_URL				AS VARCHAR(500),
	@mlproc_JSON			AS VARCHAR(MAX),
	--@mlproc_URL				AS NVARCHAR(500),
	--@mlproc_JSON			AS NVARCHAR(MAX),
	@mlproc_ProcessedWithErrorNumber		AS INT,
	--@mlproc_ProcessedWithErrorDescription	AS NVARCHAR(4000)
	@mlproc_ProcessedWithErrorDescription	AS VARCHAR(4000)
AS
BEGIN


	-- ---------------------------------------------------------------------------------------------------------------------------
	--  NOTA IMPORTANTE:
	--  Tener en cuenta que si hay 10 pedidos de lo mismo, como siempre se arranca por el ultimo ingresado, al procesar ese ULTIMO
	--  todos os pedidos anteriores de lo mismo quedar'an como PROCESADOS por mas que nunca se haya hecho.
	-- ---------------------------------------------------------------------------------------------------------------------------


	SET NOCOUNT ON;

	DECLARE
	@ret_ErrorCode			AS INT			,
	@ret_ErrorDescription	AS NVARCHAR(1000)
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''


	DECLARE @mlproc_option		AS INT
	DECLARE @mlp_id				AS INT
	DECLARE @mls_id				AS INT

	SELECT
			@mlproc_option		= tmluq.mlproc_option,
			@mlp_id				= tmluq.mlp_id
		FROM tbMercadoLibre_updateQueue				tmluq	WITH (NOLOCK)
		WHERE	tmluq.comp_id	= @comp_id AND
				tmluq.mlproc_id = @mlproc_id


	SELECT
			@mls_id				= tmlip.mls_id
		FROM tbMercadoLibre_ItemsPublicados			tmlip	WITH (NOLOCK)
		WHERE	tmlip.comp_id   = @comp_id		AND
				tmlip.mlp_id	= @mlp_id


	-- ----------------------------------------------------
	-- Forzado de OK Proceso segun valores de strResponse
	-- ----------------------------------------------------
	IF @strResponse = '**877'
		BEGIN
			SET @bitIsOK = 'True'
		END

	DECLARE @mlproc_blockCancell AS BIT = 'False'
	IF @strResponse LIKE '%**889%'	-- Si NO procesa porque faltan asociar item_id a Variaciones...  que NO los depure a los 10 intentos...
		BEGIN
			SET @mlproc_blockCancell = 'True'
		END
	-- MOS 05-2023
	IF @strResponse LIKE '%**879%'	-- **879, ATENCIÓN: NO se pudo actualizar el Stock debido a un error informado por MercadoLibre©
		BEGIN
			SET @mlproc_blockCancell = 'True'
		END
	IF @strResponse LIKE '%**869%'	-- **869, ATENCIÓN: NO se pudo actualizar el PRECIO debido a un error informado por MercadoLibre© (Publicación SIN Variación)
		BEGIN
			SET @mlproc_blockCancell = 'True'
		END
	IF @strResponse LIKE '%**859%'	-- **859, ATENCIÓN: NO se pudo actualizar el PRECIO debido a un error informado por MercadoLibre© (Publicación Con Variaciónes)
		BEGIN
			SET @mlproc_blockCancell = 'True'
		END





	-- ----------------------------------------------------




	IF @bitIsOK = 'True' SET  @mlproc_ProcessedWithErrorDescription = ''  -- MOS 07-2020 para que no guarde mas info al pedo




	-- a Custom Field Lo hace Atributos ahora, se unificaron
	IF @mlproc_option = 19 SET @mlproc_option = 18



	-- ----------------------------------------------------
	-- Si la Publicacion esta INACTIVA necesita alguna
	-- revision por lo que se la pone como Pausado Forzado
	-- ----------------------------------------------------
	IF @mlproc_ProcessedWithErrorDescription LIKE '%status:inactive%'
		BEGIN
			UPDATE tbMercadoLibre_updateQueue		WITH (ROWLOCK)
				SET mlproc_isCancelled = 'True'
				WHERE	comp_id				= @comp_id  AND -- MOS 04-2023
						mlp_id				= @mlp_id	AND
						mlproc_isProcessed	= 'False'	AND
						mlproc_isCancelled	= 'False'

			UPDATE tbMercadoLibre_ItemsPublicados	WITH (ROWLOCK)
				SET optval_statusId		= 6, 
					mlp_Active			= 'False',
					mlp_4Revision		= 'True',
					mlp_revisionMessage = 'ATENCIÓN: (1110) Status-Inactive, Requiere Revisión desde el Sitio de MercadoLibre.'
				WHERE	comp_id		= @comp_id AND
						mlp_id		= @mlp_id
			SELECT  @ret_ErrorCode			[ret_ErrorCode],
					@ret_ErrorDescription	[ret_ErrorDescription]
			RETURN
