	-- ----------------------------------------------------
	IF @mlproc_option = 1 -- MLQO_Publicate
	-- ----------------------------------------------------
		BEGIN
			UPDATE tbMercadoLibre_updateQueue	WITH (ROWLOCK)
				SET
					mlproc_isProcessed			= @bitIsOK,
					mlproc_isProcessedCD		= GETDATE(),
					mlproc_isCancelled			= 0,
					mlproc_response				.WRITE( @strResponse,0,NULL) ,
					mlproc_isWithError			=	CASE
														WHEN @bitIsOK = 0 THEN	1
														ELSE					0
													END,
					mlproc_isWithErrorTryNumber =	ISNULL(mlproc_isWithErrorTryNumber,0) +
													CASE
														WHEN @bitIsOK = 'False' AND @mlproc_blockCancell = 'False' THEN	1   -- MOS 01-2022: AND @mlproc_blockCancell = 'False' : Para que NO cancele el procesamiento pasados 10 intentos.  Se usa cuando hay Variaciones SIN item_Id asignados.  Sale en AMARILLo en la COla de Procesos
														ELSE					0
													END,
					mlproc_URL					= @mlproc_URL,
					mlproc_isProcessedWithError =	CASE
														WHEN @mlproc_ProcessedWithErrorNumber > 0 THEN 'True'
														ELSE										   'False'
													END,
					mlproc_ProcessedWithErrorDescription
												= @mlproc_ProcessedWithErrorDescription,
					mlproc_ProcessedWithErrorNumber
												= @mlproc_ProcessedWithErrorNumber,
					mlproc_JSON					.WRITE( @mlproc_JSON,0,NULL) ,
					mlproc_blockCancell			= @mlproc_blockCancell


				WHERE	comp_id				= @comp_id			AND
						mlp_id				= @mlp_id			AND
						mlproc_option		= @mlproc_option	AND
						mlproc_isProcessed	= 'False'			AND
						mlproc_isCancelled	= 'False'	-- Nunca se va a cambiar el estado de Procesado a No Procesado y si le saco esto va a actualizar TODOS los registros históricos...


			-- Marca como Publicado
			UPDATE tbMercadoLibre_ItemsPublicados	WITH (ROWLOCK)
				SET optval_statusId =	 CASE
				                     	     WHEN optval_statusId = 1 AND @bitIsOK = 1  THEN 2
				                     	     ELSE optval_statusId
				                     	 END
				WHERE	comp_id = @comp_id AND
						mlp_id	= @mlp_id



		END
