	-- ----------------------------------------------------
	IF @mlproc_option = 4 -- MLQO_UpdateAvailableQuantity
	-- ----------------------------------------------------
		BEGIN
			UPDATE tbMercadoLibre_updateQueue	WITH (ROWLOCK)
				SET
					mlproc_isProcessed			= @bitIsOK,
					mlproc_isProcessedCD		= GETDATE(),
					mlproc_isCancelled			= 0,
					mlproc_response				.WRITE( @strResponse,0,NULL),
					mlproc_isWithError			=	CASE
														WHEN @bitIsOK = 0 THEN	1
														ELSE					0
													END,
					mlproc_isWithErrorTryNumber =	ISNULL(mlproc_isWithErrorTryNumber,0) +
													CASE
														WHEN @bitIsOK = 'False' AND @mlproc_blockCancell = 'False' THEN	1
														ELSE					0
													END,
					mlproc_URL					= @mlproc_URL,
					mlproc_isProcessedWithError =	CASE
														WHEN @mlproc_ProcessedWithErrorNumber > 0 THEN 'True'
														ELSE										   'False'
													END,
					mlproc_ProcessedWithErrorDescription
												= @mlproc_ProcessedWithErrorDescription,
					mlproc_ProcessedWithErrorNumber
												= @mlproc_ProcessedWithErrorNumber,
					mlproc_JSON					.WRITE( @mlproc_JSON,0,NULL),
					mlproc_blockCancell			= @mlproc_blockCancell

				WHERE	comp_id				= @comp_id			AND
						mlproc_id			<= @mlproc_id		AND	-- MOS 01-2024: en GS se mandaron la cagara de act muy seguido una lista, mientras se estaba procesando una cola.  el proceso marco como procesada a la nueva que se agregó segundos despues de procesar la primera y NO haberse terminado. X si algun FORRO hace esto de nuevo, deberia solucionarse.  PD: CARGA MAS AL SISTEMA.
						mlp_id				= @mlp_id			AND
						mlproc_option		IN ( @mlproc_option,22)	AND
						CASE
							WHEN @bitIsOK = 1								THEN 1
							WHEN @bitIsOK = 0 AND mlproc_id = @mlproc_id	THEN 1
							ELSE												 0
						END = 1									AND
						mlproc_isProcessed	= 'False'			AND
						mlproc_isCancelled	= 'False'	-- Nunca se va a cambiar el estado de Procesado a No Procesado y si le saco esto va a actualizar TODOS los registros históricos...

				DECLARE @decLasQTY AS DECIMAL(19,4) = 0
				SELECT  @decLasQTY  = SUM(
											CASE
												WHEN tmlipv.item_id IS NULL THEN	dbo.fnGetAStock4MaxAssociation(tmlip.comp_id, tmls.stor_id4StockAvailability, tmlip.item_id, 999999999)
												ELSE								dbo.fnGetAStock4MaxAssociation(tmlip.comp_id, tmls.stor_id4StockAvailability, tmlipv.item_id, 999999999)
											END
										   )
					FROM tbMercadoLibre_ItemsPublicados		tmlip				WITH (NOLOCK)
					LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations tmlipv	WITH (NOLOCK)
						ON	tmlipv.comp_id		= tmlip.comp_id AND
							tmlipv.mlp_id		= tmlip.mlp_id	AND
							tmlipv.mlpv_disabled= 'False'
					INNER JOIN tbMercadoLibre_Stores		tmls				WITH (NOLOCK)
						ON	tmls.comp_id		= tmlip.comp_id		AND
							tmls.mls_id			= tmlip.mls_id
					WHERE	tmlip.comp_id					= @comp_id	AND
							tmlip.mlp_id					= @mlp_id



				-- Saca el estado de Forzar a verificar
				UPDATE tbMercadoLibre_ItemsPublicados	WITH (ROWLOCK)
					SET mlp_force2CheckStock			= 'False',
						mlp_lastPublicatedAvailableQTY  = @decLasQTY
					WHERE	comp_id						= @comp_id	AND
							mlp_id						= @mlp_id


		END
