						mlproc_id			= @mlproc_id	--AND
						--mlp_id				= @mlp_id	AND
						--mlproc_option		= @mlproc_option


			DECLARE @mlo_id AS INT
			SELECT	@mlo_id = mlproc_integerValue
				FROM tbMercadoLibre_updateQueue			WITH (NOLOCK)
				WHERE	comp_id		= @comp_id AND
						mlproc_id	= @mlproc_id

			IF @bitIsOK = 'True'
				BEGIN
					UPDATE tbMercadoLibre_ordersHeader		WITH (ROWLOCK)
						SET	mlo_isqualified = 1,
							mlo_isDelivered = 1
						WHERE	comp_id = @comp_id AND
