CREATE PROCEDURE [dbo].[spMercadoLibre_updateQueue_updateUnderReviewPublication]
	@comp_id				AS INT,
	@mlproc_id				AS INT,
	@strResponse			AS NVARCHAR(4000),
	@bitIsOK				AS BIT,
	@mlproc_URL				AS NVARCHAR(500),
	@mlproc_JSON			AS NVARCHAR(4000),
	@mlproc_ProcessedWithErrorNumber		AS INT,
	@mlproc_ProcessedWithErrorDescription	AS NVARCHAR(4000)
AS
BEGIN


	-- ---------------------------------------------------------------------------------------------------------------------------
	--  NOTA IMPORTANTE:
	--  Si se dio de baja una publicacion y el sistema nunca se enteró, la pone como dada de baja y borra todo lo pendiente
	--  de procesar
	-- ---------------------------------------------------------------------------------------------------------------------------


	SET NOCOUNT ON;

	DECLARE
	@ret_ErrorCode			AS INT			,
	@ret_ErrorDescription	AS NVARCHAR(1000)
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''


	DECLARE @mlproc_option		AS INT
	DECLARE @mlp_id				AS INT
	DECLARE @mls_id				AS INT

	SELECT
			@mlproc_option		= tmluq.mlproc_option,
			@mlp_id				= tmluq.mlp_id
		FROM tbMercadoLibre_updateQueue				tmluq	WITH (NOLOCK)
		WHERE	tmluq.comp_id	= @comp_id AND
				tmluq.mlproc_id = @mlproc_id


	SELECT
			@mls_id				= tmlip.mls_id
		FROM tbMercadoLibre_ItemsPublicados	tmlip	WITH (NOLOCK)
		WHERE	tmlip.comp_id   = @comp_id		AND
				tmlip.mlp_id	= @mlp_id


	-- Pongo como CERRADA a la publicacion
	UPDATE tbMercadoLibre_ItemsPublicados	WITH (ROWLOCK)
		SET	optval_statusId = 8,
			mlp_Active		= 'False'
		WHERE	comp_id = @comp_id AND
				mlp_id	= @mlp_id


	-- Saco toda la mierda que aun tenga pendiente para procesar
	UPDATE tbMercadoLibre_updateQueue			WITH (ROWLOCK)
		SET		mlproc_isCancelled						= 1,
				mlproc_isProcessed						= 1,
				mlproc_isProcessedWithError				= 1,
				mlproc_ProcessedWithErrorDescription	= '* Publicación en Revisión *   ' + mlproc_ProcessedWithErrorDescription
		WHERE	comp_id				= @comp_id	AND
				mlp_id				= @mlp_id	AND
				mlproc_isProcessed	= 0




	SELECT  @ret_ErrorCode			[ret_ErrorCode],
			@ret_ErrorDescription	[ret_ErrorDescription]



END
GO



CREATE PROCEDURE [dbo].[spMercadoLibre_UsersData_GetDataById]
(
	@MLUser_Id		BIGINT
)
AS


BEGIN
SET NOCOUNT ON

		SELECT
			tmlud.MLUser_Id,
			isnull(tmlud.nickname,'')				[nickname],
			isnull(tmlud.identificationType,'')		[identificationType],
			isnull(tmlud.identificationNumber,'')	[identificationNumber],
			isnull(tmlud.[address],'')				[address],
			isnull(tmlud.[state],'')				[state],
			isnull(tmlud.citi,'')					[citi],
			isnull(tmlud.zip_code,'')				[zip_code],
			isnull(tmlud.phone,'')					[phone],
			isnull(tmlud.alternative_phone,'')		[alternative_phone],
			isnull(tmlud.secure_email,'')			[secure_email],
			isnull(tmlud.email,'')					[email]

			FROM tbMercadoLibre_UsersData tmlud
			WHERE	tmlud.MLUser_Id		= @MLUser_Id

END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_UsersData_InsertData]
(

	 @MLUser_Id					AS BIGINT,
     @nickname					As NVARCHAR(200),
     @identificationType		As NVARCHAR(30),
     @identificationNumber		As NVARCHAR(30),
     @address					As NVARCHAR(200),
     @state						As NVARCHAR(10),
     @citi						As NVARCHAR(200),
     @zip_code					As NVARCHAR(10),
     @phone						As NVARCHAR(100),
     @alternative_phone			As NVARCHAR(100),
     @secure_email				As NVARCHAR(300),
     @email						As NVARCHAR(300),
     @billing_STATE_NAME		AS NVARCHAR(100),
     @billing_DOC_NUMBER		AS NVARCHAR(50),
     @billing_STREET_NAME		AS NVARCHAR(250),
     @billing_CITY_NAME			AS NVARCHAR(150),
     @billing_ZIP_CODE			AS NVARCHAR(20),
     @billing_STREET_NUMBER		AS NVARCHAR(50),
     @billing_DOC_TYPE			AS NVARCHAR(20),
     @billing_FIRST_NAME		AS NVARCHAR(250),
     @billing_LAST_NAME			AS NVARCHAR(250),
     @billing_SITE_ID			AS NVARCHAR(10)



)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE	  	 @comp_id						INT,
				 @mlp_id						INT,
				 @mlpqa_MLUserId				BIGINT,
				 @mlpqa_question				NVARCHAR(4000),
				 @mlpqa_answer					NVARCHAR(4000),
				 @mlpqa_cd						DATETIME,
				 @user_id_answer				INT,
				 @mlpqa_answerDate				DATETIME,

				 @return_value					AS INT	OUTPUT


	SELECT		 @comp_id						=1,
				 @mlp_id						=1,
				 @mlpqa_MLUserId				=1234234234,
				 @mlpqa_question				='',
				 @mlpqa_answer					='',
				 @mlpqa_cd						=1,
				 @user_id_answer				=1,
				 @mlpqa_answerDate				=1

*/
-- ------------------------------------------------------


	IF NOT EXISTS (
						SELECT 1
							FROM tbMercadoLibre_UsersData tmlud		WITH (NOLOCK)
							WHERE tmlud.MLUser_Id = @MLUser_Id
					)

		BEGIN
			INSERT INTO tbMercadoLibre_UsersData
			(
				MLUser_Id,
				nickname,
				identificationType,
				identificationNumber,
				[address],
				[state],
				citi,
				zip_code,
				phone,
				alternative_phone,
				secure_email,
				email,
				billing_STATE_NAME	,
				billing_DOC_NUMBER	,
				billing_STREET_NAME	,
				billing_CITY_NAME	,
				billing_ZIP_CODE	,
				billing_STREET_NUMBER	,
				billing_DOC_TYPE		,
				billing_FIRST_NAME	,
				billing_LAST_NAME	,
				billing_SITE_ID
			)
			VALUES
			(
				 @MLUser_Id	,
				 @nickname,
				 @identificationType,
				 @identificationNumber,
				 @address,
				 @state,
				 @citi,
				 @zip_code,
				 @phone,
				 @alternative_phone,
				 @secure_email,
				 @email,
				 @billing_STATE_NAME,
				 @billing_DOC_NUMBER,
				 @billing_STREET_NAME,
				 @billing_CITY_NAME	,
				 @billing_ZIP_CODE	,
				 @billing_STREET_NUMBER,
				 @billing_DOC_TYPE		,
				 @billing_FIRST_NAME	,
				 @billing_LAST_NAME		,
				 @billing_SITE_ID


			)
		END
	ELSE
		BEGIN

			UPDATE  tbMercadoLibre_UsersData					WITH (ROWLOCK)
				SET
				nickname					= @nickname,
				identificationType			= @identificationType,
				identificationNumber		= @identificationNumber,
				[address]					= @address,
				[state]						= @state,
				citi						= @citi,
				zip_code					= @zip_code,
				phone						= @phone,
				alternative_phone			= @alternative_phone,
				secure_email				= @secure_email,
				email						= @email,
				billing_STATE_NAME			=	CASE
													WHEN @billing_STATE_NAME <> ''	THEN @billing_STATE_NAME
													ELSE								billing_STATE_NAME
												END,
				billing_DOC_NUMBER			= 	CASE
													WHEN @billing_DOC_NUMBER <> ''	THEN @billing_DOC_NUMBER
													ELSE								billing_DOC_NUMBER
												END 	,
				billing_STREET_NAME			= 	CASE
													WHEN @billing_STREET_NAME <> '' THEN @billing_STREET_NAME
													ELSE								 billing_STREET_NAME
												END 	,
				billing_CITY_NAME			= 	CASE
													WHEN @billing_CITY_NAME <> ''	THEN @billing_CITY_NAME
													ELSE								billing_CITY_NAME
												END	,
				billing_ZIP_CODE			= 	CASE
													WHEN @billing_ZIP_CODE <> ''	THEN @billing_ZIP_CODE
													ELSE								billing_ZIP_CODE
												END	,
				billing_STREET_NUMBER		= 	CASE
													WHEN @billing_STREET_NUMBER <> '' THEN @billing_STREET_NUMBER
													ELSE								billing_STREET_NUMBER
												END 	,
				billing_DOC_TYPE			= 	CASE
													WHEN @billing_DOC_TYPE <> ''	THEN @billing_DOC_TYPE
													ELSE								billing_DOC_TYPE
												END 	,
				billing_FIRST_NAME			= 	CASE
													WHEN @billing_FIRST_NAME <> ''	THEN @billing_FIRST_NAME
													ELSE								billing_FIRST_NAME
												END 	,
				billing_LAST_NAME			= 	CASE
													WHEN @billing_LAST_NAME <> ''	THEN @billing_LAST_NAME
													ELSE								billing_LAST_NAME
												END 	,
				billing_SITE_ID				= 	CASE
													WHEN @billing_SITE_ID <> ''		THEN @billing_SITE_ID
													ELSE								billing_SITE_ID
												END
				WHERE MLUser_Id = @MLUser_Id

		END


END
GO

CREATE PROCEDURE [dbo].[spMercadoLibre_UsersData_UpdateData]
(
	@MLUser_Id			BIGINT,
	@address			NVARCHAR(200),
	@state				NVARCHAR(200),
	@citi				NVARCHAR(200),
	@zip_code			NCHAR(10),
	@phone				NVARCHAR(100),
	@alternative_phone	NVARCHAR(100),
	@secure_email		NVARCHAR(300),
	@email				NVARCHAR(300)
)
AS

-- UNUSED

RETURN

	BEGIN
		SET NOCOUNT ON

		UPDATE tbMercadoLibre_UsersData	WITH (ROWLOCK)
		SET
			[address]			= CASE WHEN @address			= '' THEN [address]			ELSE @address			END,
			citi				= CASE WHEN @citi				= '' THEN citi				ELSE @citi				END,
			zip_code			= CASE WHEN @zip_code			= '' THEN zip_code			ELSE @zip_code			END,
			phone				= CASE WHEN @phone				= '' THEN phone				ELSE @phone				END,
			alternative_phone	= CASE WHEN @alternative_phone	= '' THEN alternative_phone	ELSE @alternative_phone	END,
			secure_email		= CASE WHEN @secure_email		= '' THEN secure_email		ELSE @secure_email		END,
			email				= CASE WHEN @email				= '' THEN email				ELSE @email				END,
			[state]				= CASE WHEN @state				= '' THEN [state]			ELSE @state				END

		WHERE MLUser_Id = @MLUser_Id

	END
GO


CREATE PROCEDURE [dbo].[spMercadoLibre_Variations_DeleteVariationsAndAllAttributes]
(
	@comp_id	INT,
	@mlp_id		INT,
	@mlpv_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@mlp_id		INT,
				@mlpv_id	INT
		*/
		-- -------------------------------------------------------

		DELETE FROM tbMercadoLibre_ItemsPublicadosVariations_Attributes
		WHERE	comp_id = @comp_id AND
				mlpv_id = @mlpv_id

		DELETE FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations
		WHERE	comp_id = @comp_id AND
				mlpv_id = @mlpv_id

		DELETE FROM tbMercadoLibre_ItemsPublicadosVariations
		WHERE	comp_id = @comp_id AND
				mlpv_id	= @mlpv_id



	END

GO

