--'10     Desenlazada



CREATE PROCEDURE [dbo].[spMercadoLibre_verifications4updateQueue]
AS


BEGIN

	SET NOCOUNT ON;

	BEGIN TRY
		EXEC spMercadoLibre_updateQueue_lockTable
	END TRY
	BEGIN CATCH
		RETURN
	END CATCH



		-- --------------------------------------------------------------------------------------------------------------------------
		-- Precalculo el Stock para que no tarde 100 años en hacer los SUM y MAX
		-- --------------------------------------------------------------------------------------------------------------------------
		DECLARE @tblStock TABLE(mlp_id			INT ,
								maxStock DECIMAL(19,4),
								sumStock DECIMAL(19,4),
								Uniqueifier INT NOT NULL IDENTITY(1,1),
								UNIQUE CLUSTERED (mlp_id,Uniqueifier))


		;WITH ctrStock AS (
							SELECT
									tmlip.mlp_id,
									(
										CASE
											WHEN tmlip.optval_statusId = 6 THEN 0		-- MOS 01-2024: Estan Pausadas Forzadas, el stock se debe poner en 0 ya que solo se usa opara actualizar precios.
											WHEN tmlipv.item_id IS NULL    THEN	dbo.fnGetAStock4MaxAssociation(tmlip.comp_id,							CASE
																																							WHEN tmlip.mlp_is4FulFillment = 'True'			AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
																																							WHEN tmls.stor_id4FulFillment = tmlip.stor_id	AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
																																							WHEN tmlip.stor_id4StockAvailability IS NOT NULL										 THEN tmlip.stor_id4StockAvailability
																																							ELSE																						  tmls.stor_id4StockAvailability
																																						END, tmlip.item_id, 999999999)
											ELSE								dbo.fnGetAStock4MaxAssociation(tmlip.comp_id,							CASE
																																							WHEN tmlip.mlp_is4FulFillment = 'True'			AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
																																							WHEN tmls.stor_id4FulFillment = tmlip.stor_id	AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
																																							WHEN tmlip.stor_id4StockAvailability IS NOT NULL										 THEN tmlip.stor_id4StockAvailability
																																							ELSE																						  tmls.stor_id4StockAvailability
																																						END, tmlipv.item_id, 999999999)
										END
									)		[CalcutatedStock]
								FROM tbMercadoLibre_ItemsPublicados		tmlip				WITH (NOLOCK)
								LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations tmlipv	WITH (NOLOCK)
									ON	tmlipv.comp_id		= tmlip.comp_id AND
										tmlipv.mlp_id		= tmlip.mlp_id	AND
										tmlipv.mlpv_disabled= 'False'
								INNER JOIN tbMercadoLibre_Stores		tmls				WITH (NOLOCK)
									ON	tmls.comp_id		= tmlip.comp_id		AND
										tmls.mls_id			= tmlip.mls_id
								WHERE
										ISNULL(tmls.mls_disabled,'False') = 'False'	AND
										(
											(
												tmlip.mlp_Active	= 'True'		AND
												tmlip.optval_statusId IN (1,2,3,4)
											)
												OR
											(
												tmlip.mlp_Active	= 'False'		AND
												tmlip.optval_statusId IN (2,/*MOS 24-04-2020 McCars*/ 3 /*MOS 24-04-2020 McCars*/,4,/*MOS 01-2024 x Global Sound q pretendia q se le act los precios si estaba pausado forzado*/6)
											)
										)											AND
										ISNULL(tmlip.mlp_publicationID,'') <> ''	--AND  /*MOS 01-2024 x Global Sound q pretendia q se le act los precios si estaba pausado forzado*/
										--tmlip.optval_statusId <> 6		-- Por Las Dudas que NUNCA tome las Pausado Forzado
							)

		INSERT INTO @tblStock
		(
			mlp_id,
			maxStock,
			sumStock
		)
			SELECT tmp.mlp_id,
					MAX(tmp.CalcutatedStock),
					SUM(
							CASE	-- MOS 06-2022 x FAS, si una variacion tiene MENOS que cero y otra mas y se compensan y dan 0, pausa la publicacion.
								WHEN tmp.CalcutatedStock > 0 THEN tmp.CalcutatedStock
								ELSE 0
							END
							-- tmp.CalcutatedStock
						)
				FROM ctrStock tmp
				GROUP BY mlp_id
		-- --------------------------------------------------------------------------------------------------------------------------



	-- 1ro tomo las publicaciones que necesiten verificaciones.
	DECLARE curPublicaciones CURSOR LOCAL  FAST_FORWARD FOR
		SELECT	tmlip.comp_id,
				tmlip.mlp_id,
				tmlip.optval_statusId,
				tmlip.mlp_Active,
				tmlip.mls_id,
				tmp.maxStock,	-- MOS 30-04-2021 x velocidad y uso de disco
				--MAX(
				--	CASE
				--		WHEN tmlipv.item_id IS NULL THEN	dbo.fnGetAStock4MaxAssociation(tmlip.comp_id,							CASE
				--																														WHEN tmlip.mlp_is4FulFillment = 'True'			AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
				--																														WHEN tmls.stor_id4FulFillment = tmlip.stor_id	AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
				--																														WHEN tmlip.stor_id4StockAvailability IS NOT NULL										 THEN tmlip.stor_id4StockAvailability
				--																														ELSE																						  tmls.stor_id4StockAvailability
				--																													END, tmlip.item_id, 999999999)
				--		ELSE								dbo.fnGetAStock4MaxAssociation(tmlip.comp_id,							CASE
				--																														WHEN tmlip.mlp_is4FulFillment = 'True'			AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
				--																														WHEN tmls.stor_id4FulFillment = tmlip.stor_id	AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
				--																														WHEN tmlip.stor_id4StockAvailability IS NOT NULL										 THEN tmlip.stor_id4StockAvailability
				--																														ELSE																						  tmls.stor_id4StockAvailability
				--																													END, tmlipv.item_id, 999999999)
				--	END
				--   ),
				tmp.sumStock,  -- MOS 30-04-2021 x velocidad y uso de disco ( Tarda 1/5 de lo q tardaba antes )
				--SUM(
				--	CASE	-- MOS 19-08-2019, NUNCA NADIE probo una MIERDA y haciendo pruebas SALTA TODO, solo hay que hacer una PUTA PRUEBA!!!    si el stock de alguna parte es MUY NEGATIVO se pausaba  ya que esta variable debe sumar si hay stock de alguna parte.
				--		WHEN tmlipv.item_id IS NULL THEN	dbo.fnGetMaximumValue(0,dbo.fnGetAStock4MaxAssociation(tmlip.comp_id,	CASE
				--																														WHEN tmlip.mlp_is4FulFillment = 'True'			AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
				--																														WHEN tmls.stor_id4FulFillment = tmlip.stor_id	AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
				--																														WHEN tmlip.stor_id4StockAvailability IS NOT NULL										 THEN tmlip.stor_id4StockAvailability
				--																														ELSE																						  tmls.stor_id4StockAvailability
				--																													END	/*tmls.stor_id4StockAvailability*/, tmlip.item_id, 999999999))
				--		ELSE								dbo.fnGetMaximumValue(0,dbo.fnGetAStock4MaxAssociation(tmlip.comp_id,   CASE
				--																														WHEN tmlip.mlp_is4FulFillment = 'True'			AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
				--																														WHEN tmls.stor_id4FulFillment = tmlip.stor_id	AND tmls.stor_id4FulFillment IS NOT NULL THEN tmls.stor_id4FulFillment
				--																														WHEN tmlip.stor_id4StockAvailability IS NOT NULL										 THEN tmlip.stor_id4StockAvailability
				--																														ELSE																						  tmls.stor_id4StockAvailability
				--																													END /*tmls.stor_id4StockAvailability*/, tmlipv.item_id, 999999999))
				--	END
				--   ),
				CASE
					WHEN tmlip.stor_id4StockAvailability IS NOT NULL										 THEN tmlip.stor_id4StockAvailability
					ELSE																						  tmls.stor_id4StockAvailability
				END								[stor_id4StockAvailability]	,
				tmlip.item_id,
				tmlip.mlp_initQty,
				ISNULL(tmlip.mlp_minQty4Pause,0),
				ISNULL(tmls.mls_disableAutoActivationFromStockAvailability,'False'),
				ISNULL(tmlip.mlp_allowPublicationsWithNoStock,'False'),
				ISNULL(tmlip.mlp_force2CheckStock,'False'),
				CASE
					WHEN tmlipv.comp_id IS NULL THEN	'False'
					ELSE								'True'
				END,
				ISNULL(tmlip.mlp_lastPublicatedAvailableQTY,-9999999),
				tmlip.mlp_price
			FROM tbMercadoLibre_ItemsPublicados		tmlip				WITH (NOLOCK)
			INNER JOIN @tblStock					tmp
				ON tmp.mlp_id = tmlip.mlp_id
			LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations tmlipv	WITH (NOLOCK)
				ON	tmlipv.comp_id		= tmlip.comp_id AND
					tmlipv.mlp_id		= tmlip.mlp_id	AND
					tmlipv.mlpv_disabled= 'False'
			INNER JOIN tbMercadoLibre_Stores		tmls				WITH (NOLOCK)
				ON	tmls.comp_id		= tmlip.comp_id		AND
					tmls.mls_id			= tmlip.mls_id
			WHERE
					ISNULL(tmls.mls_disabled,'False') = 'False'	AND
					(
						(
							tmlip.mlp_Active	= 'True'		AND
							tmlip.optval_statusId IN (1,2,3,4)
						)
							OR
						(
							tmlip.mlp_Active	= 'False'		AND
							tmlip.optval_statusId IN (2,/*MOS 24-04-2020 McCars*/ 3 /*MOS 24-04-2020 McCars*/,4,/*MOS 01-2024 x Global Sound q pretendia q se le act los precios si estaba pausado forzado*/6)
						)
					)											AND
					ISNULL(tmlip.mlp_publicationID,'') <> ''	--AND
					--tmlip.optval_statusId <> 6  -- Por Las Dudas que NUNCA tome las Pausado Forzado  -->> MOS 01-2024, lo saque x los FORROS de GlobalSound, ver si no molesta al resto.  mire abajo y lo unico q toma 6 es el precio
			GROUP BY	tmlip.comp_id,
						tmlip.mlp_id,
						tmlip.optval_statusId,
						tmlip.mlp_Active,
						tmlip.mls_id,
						tmls.stor_id4StockAvailability,
						tmlip.stor_id4StockAvailability,
						tmlip.item_id,
						tmlip.mlp_initQty,
						ISNULL(tmlip.mlp_minQty4Pause,0),
						ISNULL(tmls.mls_disableAutoActivationFromStockAvailability,'False'),
						ISNULL(tmlip.mlp_allowPublicationsWithNoStock,'False'),
						ISNULL(tmlip.mlp_force2CheckStock,'False'),
						tmlipv.comp_id,
						tmlip.mlp_lastPublicatedAvailableQTY,
						tmlip.mlp_price,
						tmp.maxStock,
						tmp.sumStock


	DECLARE		@comp_id							AS INT
	DECLARE     @mlp_id								AS INT
	DECLARE		@optval_statusId					AS INT
	DECLARE		@mlp_Active							AS BIT
	DECLARE		@mls_id								AS INT
	DECLARE		@decAvailableStockMAX				AS DECIMAL(19,4)
	DECLARE		@decAvailableStockSUM				AS DECIMAL(19,4)
	DECLARE		@stor_id4StockAvailability			AS INT
	DECLARE		@intItemID							AS INT
	DECLARE		@mlp_initQty						AS INT
	DECLARE     @mlp_minQty4Pause					AS INT
	DECLARE		@mls_disableAutoActivationFromStockAvailability AS BIT
	DECLARE     @mlp_allowPublicationsWithNoStock				AS BIT
	DECLARE		@mlp_force2CheckStock							AS BIT
	DECLARE		@bitHasVariations								AS BIT
	DECLARE		@decmlp_lastPublicatedAvailableQTY				AS DECIMAL(19,4)
	DECLARE		@decmlp_price									AS DECIMAL(26,6)



	OPEN		curPublicaciones
	FETCH NEXT FROM curPublicaciones INTO @comp_id,
										  @mlp_id,
										  @optval_statusId,
										  @mlp_Active,
										  @mls_id,
										  @decAvailableStockMAX,
										  @decAvailableStockSUM,
										  @stor_id4StockAvailability,
										  @intItemID,
										  @mlp_initQty,
										  @mlp_minQty4Pause	,
										  @mls_disableAutoActivationFromStockAvailability,
										  @mlp_allowPublicationsWithNoStock	,
										  @mlp_force2CheckStock	,
										  @bitHasVariations	,
										  @decmlp_lastPublicatedAvailableQTY,
										  @decmlp_price

	WHILE @@FETCH_STATUS = 0
		BEGIN

			-- -------------------------------------------------------------------------------
			-- Testing
			-- -------------------------------------------------------------------------------
			--SELECT	'@mlp_id',@mlp_id
			--		'@mlp_Active',@mlp_Active,
			--		'@optval_statusId',@optval_statusId,
			--		'@decAvailableStockMAX',@decAvailableStockMAX,
			--		'@mlp_minQty4Pause',@mlp_minQty4Pause,
			--		'@mlp_force2CheckStock',@mlp_force2CheckStock,
			--		'@mlp_allowPublicationsWithNoStock',@mlp_allowPublicationsWithNoStock
			-- -------------------------------------------------------------------------------



			-- Si esta Inactiva y tiene stock, la activa x las dudas. Esta condicion no deberia darse nunca.
			IF	@mlp_Active = 'False'		AND
				@optval_statusId IN (2,4)	AND
				@decAvailableStockMAX > @mlp_minQty4Pause
				BEGIN
					-- Activarla y poner stock
					UPDATE tbMercadoLibre_ItemsPublicados	WITH (ROWLOCK)
						SET	mlp_Active	= 'True'
						WHERE	comp_id = @comp_id AND
								mlp_id	= @mlp_id


					-- MOS 06-2024: x las dudas actualizo el precio, x caso FAS
					INSERT INTO tbMercadoLibre_updateQueue	WITH (ROWLOCK)
						(
							comp_id,
							mlp_id,
							mlproc_option,
							mlproc_integerValue,
							mlproc_isProcessed,
							mlproc_isCancelled,
							mlproc_priority,
							mlproc_internalID
						)
						VALUES
						(
							@comp_id,
							@mlp_id,
							8,
							@mlp_initQty,
							'False',
							'False',
							0,
							90355
						)

					-- Mando a que le recargue stock segun pueda y la active   **864654ef987987  MOS 03-06-2019
					INSERT INTO tbMercadoLibre_updateQueue	WITH (ROWLOCK)
						(
							comp_id,
							mlp_id,
							mlproc_option,
							mlproc_integerValue,
							mlproc_isProcessed,
							mlproc_isCancelled,
							mlproc_priority,
							mlproc_internalID
						)
						VALUES
						(
							@comp_id,
							@mlp_id,
							4,
							@mlp_initQty,
							'False',
							'False',
							0,
							355
						)

					INSERT INTO tbMercadoLibre_updateQueue	WITH (ROWLOCK)
					(
						comp_id,
						mlp_id,
						mlproc_option,
						mlproc_integerValue,
						mlproc_isProcessed,
						mlproc_isCancelled,
						mlproc_priority,
						mlproc_decimalValue,
						mlproc_stringValue,
						mlproc_internalID
					)
					VALUES
					(
						@comp_id,
						@mlp_id,
						7,
						2,
						'False',
						'False',
						0,
						0,
						'*5',
						356
					)
				END





			-- Si esta activa y el precio esta en 0, la pausa.
			IF		(@mlp_Active = 'True'	OR  @optval_statusId IN (2,4))
						AND
					 @decmlp_price <= 0
				BEGIN

					UPDATE tbMercadoLibre_ItemsPublicados	WITH (ROWLOCK)
						SET optval_statusId = 3
						WHERE	comp_id = @comp_id AND
								mlp_id	= @mlp_id

					IF NOT EXISTS (	SELECT TOP 1 1
					               		FROM tbMercadoLibre_updateQueue			WITH (NOLOCK)
					               		WHERE	comp_id				= @comp_id	AND
					               				mlp_id				= @mlp_id	AND
					               				mlproc_option		= 7			AND
					               				mlproc_integerValue = 3			AND
					               				mlproc_isProcessed	= 'False'	AND
					               				mlproc_isCancelled	= 'False')

					BEGIN
						INSERT INTO tbMercadoLibre_updateQueue	WITH (ROWLOCK)
						(
							comp_id,
							mlp_id,
							mlproc_option,
							mlproc_integerValue,
							mlproc_isProcessed,
							mlproc_isCancelled,
							mlproc_priority,
							mlproc_decimalValue,
							mlproc_stringValue,
							mlproc_internalID
						)
						VALUES
						(
							@comp_id,
							@mlp_id,
							7,
							3,
							'False',
							'False',
							-1000,
							0,
							'*1',
							97
						)
					END


				END

			----==
			--IF @mlp_id IN (916,917)
			--	BEGIN
			--		SELECT @mlp_id,@mlp_Active,@optval_statusId,@decAvailableStockSUM,@decAvailableStockSUM,@mlp_minQty4Pause,@mlp_force2CheckStock
			--	END


			-- Si esta activa y no tiene stock o esta por debajo del minimo para pausar la publicacion, la pausa.
			IF		(@mlp_Active = 'True'	OR  @optval_statusId IN (2,4))
						AND
					(@decAvailableStockSUM <= 0 OR @decAvailableStockSUM < @mlp_minQty4Pause OR @mlp_force2CheckStock = 'True')
				BEGIN
					IF @mlp_allowPublicationsWithNoStock = 'False'
						BEGIN

							DECLARE @bitPutActive	AS BIT				= 'True'
							DECLARE @strFRC			AS NVARCHAR(200)	= '*31 '
							IF @mlp_force2CheckStock = 'True'
								BEGIN
									SET @strFRC = @strFRC + ' FCSTK '
								END
							SET @strFRC = @strFRC + 'STKMax:' +  CONVERT(NVARCHAR(45),@decAvailableStockSUM)

							-- Por si es un chequeo forzado ve aca si trata de pausar o de activar.  - MOS 08-2018
							IF @decAvailableStockSUM <= 0 OR @decAvailableStockSUM < @mlp_minQty4Pause
								BEGIN
									SET @bitPutActive = 'False'
								END


							IF NOT EXISTS (	SELECT TOP 1 1
					               				FROM tbMercadoLibre_updateQueue			WITH (NOLOCK)
					               				WHERE	comp_id				= @comp_id	AND
					               						mlp_id				= @mlp_id	AND
					               						mlproc_option		= 7			AND
  														mlproc_integerValue =
  														CASE
															WHEN @bitPutActive = 'True' THEN 2
															ELSE							 3
														END								AND
					               						mlproc_isProcessed	= 'False'	AND
					               						mlproc_isCancelled	= 'False')

							BEGIN
								INSERT INTO tbMercadoLibre_updateQueue	WITH (ROWLOCK)
								(
									comp_id,
									mlp_id,
									mlproc_option,
									mlproc_integerValue,
									mlproc_isProcessed,
									mlproc_isCancelled,
									mlproc_priority,
									mlproc_decimalValue,
									mlproc_stringValue,
									mlproc_internalID
								)
								VALUES
								(
									@comp_id,
									@mlp_id,
									7,
									CASE
										WHEN @bitPutActive = 'True' THEN 2
										ELSE							 3
									END,
									'False',
									'False',
									0,
									0,
									@strFRC,		--*31
									2
								)
							END




						END
				END


			-- Si esta activa pero en estado pausada, la desactiva. Esta condicion no deberia darse nunca
			IF @mlp_Active = 'True' AND @optval_statusId IN (3,5)
				BEGIN
					UPDATE tbMercadoLibre_ItemsPublicados	WITH (ROWLOCK)
						SET	mlp_Active	= 'False'
						WHERE	comp_id = @comp_id AND
								mlp_id	= @mlp_id
				END


			DECLARE @bitWasActivedByStock AS BIT = 'False'





			-- Esta inactiva esperando que ingrese stock, cuando ingresa, la activa.
			IF	@mlp_Active = 'False' AND
				@optval_statusId IN (3,4) AND
				@decAvailableStockMAX > 0 AND
				@decAvailableStockMAX > @mlp_minQty4Pause AND	-- MOS 07-03-2022: Vi en MS que se generaban estos registros de a miles al pedo ya que terminaba dejando pausadas las publicaciones.
				@decmlp_price > 0	AND
				@mls_disableAutoActivationFromStockAvailability = 'False'		-- MOS 04-2023
				BEGIN

					IF NOT EXISTS (	SELECT TOP 1 1
					               		FROM tbMercadoLibre_updateQueue			WITH (NOLOCK)
					               		WHERE	comp_id				= @comp_id	AND
					               				mlp_id				= @mlp_id	AND
					               				mlproc_option		= 4			AND
					               				mlproc_isProcessed	= 'False'	AND
					               				mlproc_isCancelled	= 'False')

					BEGIN


						-- MOS 06-2024: x las dudas actualizo el precio, x caso FAS
						INSERT INTO tbMercadoLibre_updateQueue	WITH (ROWLOCK)
							(
								comp_id,
								mlp_id,
								mlproc_option,
								mlproc_integerValue,
								mlproc_isProcessed,
								mlproc_isCancelled,
								mlproc_priority,
								mlproc_internalID
							)
							VALUES
							(
								@comp_id,
								@mlp_id,
								8,
								@mlp_initQty,
								'False',
								'False',
								0,
								90356
							)



						SET @bitWasActivedByStock = 'True'
						-- Mando a que le recargue stock segun pueda y la active   **864654ef987987
						INSERT INTO tbMercadoLibre_updateQueue	WITH (ROWLOCK)
						(
							comp_id,
							mlp_id,
							mlproc_option,
							mlproc_integerValue,
							mlproc_isProcessed,
							mlproc_isCancelled,
							mlproc_priority,
							mlproc_internalID
						)
						VALUES
						(
							@comp_id,
							@mlp_id,
							4,
							@mlp_initQty,
							'False',
							'False',
							0,
							300021   --  NO CAMBIAR ESTE NUMERO POR FAVOR, lo usa la processqueue para tambien actualizar el PRECIO de la publicacion
						)
					END

				END


			-- MLQO_UpdateAvailableQuantity    Hacer este
			-- Si la cantidad disponible es mayor a cero y SI esta activa y
			-- el ultimo stock informado difiere del stock actual (SUM) y
			-- el stock disponible es menor al de la publicacion O tiene variaciones @bitHasVariations
			-- DEDE actualizar la cantidad disponible !!!
			-- O lastavailableQTY = -999999999


--SELECT @mlp_id, @mlp_Active,@optval_statusId,@decAvailableStockSUM, @decmlp_lastPublicatedAvailableQTY, 	@mlp_initQty,	@bitHasVariations
--SELECT @decAvailableStockSUM,	@decmlp_lastPublicatedAvailableQTY

			IF	(
					@mlp_Active = 'True'					AND
					@optval_statusId IN (2,3,4)				AND
					@decAvailableStockSUM > 0				AND
					@decAvailableStockSUM <> @decmlp_lastPublicatedAvailableQTY AND	-- Si vario el stock con respecto a la ultima vez que se actualizo el stock
					(
						@decAvailableStockSUM < @mlp_initQty OR	-- Si el Stock es MENOR a la Cantidad MAXIMA a publicar ! --  Si tiene publicado mucho es al pedo que lo genere, total si lo faturan lo va a actualizar al toque.
						@bitHasVariations		= 'True'
					)
				)
				OR
				-- MOS 04-2024: es al pedo insertar si esta como pausado forzado ya que mas abajo lo  pone como cancelado.
				(@decmlp_lastPublicatedAvailableQTY = -999999999 AND @optval_statusId <> 6)
				--@decmlp_lastPublicatedAvailableQTY = -999999999
				BEGIN


					IF NOT EXISTS (	SELECT TOP 1 1
					               		FROM tbMercadoLibre_updateQueue			WITH (NOLOCK)
					               		WHERE	comp_id				= @comp_id	AND
					               				mlp_id				= @mlp_id	AND
					               				mlproc_option		= 4			AND
					               				mlproc_isProcessed	= 'False'	AND
					               				mlproc_isCancelled	= 'False')

					BEGIN
						--SELECT 'HDP'
						INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
						(
							comp_id,
							mlp_id,
							mlproc_option,
							mlproc_integerValue,
							mlproc_isProcessed,
							mlproc_isCancelled,
							mlproc_priority,
							mlproc_internalID
						)
						VALUES
						(
							@comp_id,
							@mlp_id,
							4,
							@mlp_initQty,
							'False',
							'False',
							0,
							4
						)
					END

				END





			-- Verifica que aun este activa y no se haya cambiado el precio de lista y no sea precio fijo
			-- para que si esto paso se actualice el precio
			DECLARE @item_id			AS INT = -1
			DECLARE @prli_id			AS INT = -1
			DECLARE @decPrecio			AS DECIMAL(19,4)
			DECLARE @decPrecio2			AS DECIMAL(19,4)
			DECLARE @intCurrID			AS INT
			DECLARE @intCurrIDStore		AS INT
			DECLARE @intUserID			AS INT
			DECLARE @intPrecioML		AS DECIMAL(19,4)		-- 30052019, antes era INT
			DECLARE @mlp_isFixedPrice	AS BIT
			DECLARE @mlp_lastPublicatedExchange AS DECIMAL(30,15)	= 0
			DECLARE @bitHasPriceChanged AS BIT	= 'False'
			DECLARE @mlp_mustUpdate_prli_id4MercadoShop AS BIT = 'False'
			SET		@intUserID					= NULL
			SET		@mlp_isFixedPrice			= 'False'
			SET		@mlp_mustUpdate_prli_id4MercadoShop = 'False'

			SELECT	@decPrecio					= ISNULL(tpli.prli_price,0),
					@intCurrID					= tpli.curr_id,
					@intUserID					= tmls.[user_id],
					@mlp_isFixedPrice			= ISNULL(tmlip.mlp_isFixedPrice,'False'),
					@mlp_lastPublicatedExchange = tmlip.mlp_lastPublicatedExchange,
					@intCurrIDStore				= tmls.curr_id,
					@item_id					= tmlip.item_id,
					@prli_id					= tmlip.prli_id,
					@bitHasPriceChanged			= 'True',
					@mlp_mustUpdate_prli_id4MercadoShop = tmlip.mlp_mustUpdate_prli_id4MercadoShop
				FROM	tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
				INNER JOIN tbMercadoLibre_Stores		tmls		WITH (NOLOCK)  -- agregado 09-2021 MOS
					ON	tmls.comp_id = tmlip.comp_id AND
						tmls.mls_id	 = tmlip.mls_id
				INNER JOIN tbPriceListItems				tpli		WITH (NOLOCK)  -- agregado 09-2021 MOS
					ON	tpli.comp_id = tmlip.comp_id AND
						tpli.prli_id = tmlip.prli_id AND
						tpli.item_id = tmlip.item_id
				WHERE	tmlip.comp_id			= @comp_id	AND
						tmlip.mlp_id			= @mlp_id	AND
						(
							tmlip.mlp_isFixedPrice	= 'False'
								OR
							tmlip.mlp_mustUpdate_prli_id4MercadoShop = 'True'
						)									AND
						round(tpli.prli_price,2) > 0		AND
						(
							Round(ISNULL(tmlip.mlp_lastPublicatedPrice,0),2)		<> round(tpli.prli_price,2)
								OR
							ISNULL(tmlip.mlp_lastPublicatedCurrID,1)				<> tpli.curr_id
								OR
							ROUND(ISNULL(tmlip.mlp_lastPublicatedExchange,0),4)		<> ROUND( dbo.fnGetExchange2(@comp_id, 1, tpli.curr_id, /*ARS*/tmls.curr_id, 0,0,0,'False'),4)	--**54654654
								OR
							tmlip.mlp_mustUpdate_prli_id4MercadoShop = 'True'
								OR
							tmlip.mlp_forcePriceUpdate				 = 'True'
						)


			SELECT @decPrecio2 = tpli.prli_price
				FROM tbPriceListItems tpli	WITH (NOLOCK)
				WHERE	tpli.comp_id = @comp_id AND
						tpli.prli_id = @prli_id AND
						tpli.item_id = @item_id

--' Estado de Publicacion en tbSysOptionValues: Clase 173

--'1		Pendiente de Publicación
--'2		Publicado
--'3		Publicación Pausada
--'4		Republicado
--'5		Finalizado
--'6		Publicación Pausada FORZADA
--'7		Publicación Masiva con Error
--'8      under_review
--'10     Desenlazada



--IF @mlp_id  = 2191 SELECT 8888,@intUserID,@mlp_isFixedPrice, @mlp_Active,@optval_statusId,@decPrecio, @decPrecio2,@comp_id,@prli_id,@item_id


			-- Genera una actualizacion de precios si es que no es precio fijo ! ! !
			IF (@intUserID IS NOT NULL	AND (@mlp_isFixedPrice = 'False' OR @mlp_mustUpdate_prli_id4MercadoShop = 'True'))
					AND
			   (
			   		@mlp_Active = 'True'
			   			OR
			   		@optval_statusId IN (2,4,   /*  MOS 01-2024 X LOS forros DE gLOBALsOUND  */3,6)
			   			OR
			   		@bitWasActivedByStock	= 'True'
			   			OR
			   		@bitHasPriceChanged		= 'True'	-- MOS 11-2020, Munoz, si habia una publi pausada , se cambia el precio y luego se activa x stock, hasta el proximo ciclo de revision quedaba el precio desactualizado.
			   			OR
			   		@mlp_mustUpdate_prli_id4MercadoShop = 'True'
			   )	-- MOS 11-2017
					AND
			    @decPrecio > 0
					AND
				-- Por las dudas, no sabemos si está habiendo algun problema con esto, no creo, pero por las dudas lo ponemos.
				( @decPrecio = @decPrecio2 )                    	                              	--
				BEGIN


					-- Redondeo para CERO Decimales !!!
					--SET @intPrecioML = ROUND( dbo.fnGetExchange2(@comp_id, @decPrecio, @intCurrID, /*ARS*/@intCurrIDStore, 0,0,0,'False'),0)   MOS 30052019    se redondeaba el NETO y esto debe ser sobre el FINAL que ya lo hace el actualizador.
					IF @intCurrID <> @intCurrIDStore
						BEGIN
							SET @intPrecioML =  dbo.fnGetExchange2(@comp_id, @decPrecio, @intCurrID, /*ARS*/@intCurrIDStore, 0,0,0,'False')
						END
					ELSE
						BEGIN
							SET @intPrecioML = @decPrecio
						END


					IF @intPrecioML > 0
						BEGIN

							-- Actualiza los precios de la tabla y el tipo de cambio de esta actualizacion
							UPDATE tbMercadoLibre_ItemsPublicados			WITH (ROWLOCK)
								SET	mlp_price									= @intPrecioML,
									mlp_lastPublicatedPrice						= tpli.prli_price,
									mlp_lastPublicatedCurrID					= tpli.curr_id 	,
									mlp_lastPublicatedExchange					= ROUND( dbo.fnGetExchange2(@comp_id, 1, tpli.curr_id, /*ARS*/ @intCurrIDStore, 0,0,0,'False'),4),	--**54654654
									mlp_lastPublicatedPriceOrExchangeChanged	= GETDATE(),
									mlp_mustUpdate_prli_id4MercadoShop			= 'False',
									mlp_forcePriceUpdate						= 'False',
									mlp_hasPrice2WinActive						= 'False'
								FROM tbMercadoLibre_ItemsPublicados mlp
								INNER JOIN tbPriceListItems			tpli	WITH (NOLOCK)
									ON	tpli.comp_id = mlp.comp_id AND
										tpli.prli_id = mlp.prli_id AND
										tpli.item_id = mlp.item_id
								WHERE	mlp.comp_id = @comp_id  AND
										mlp.mlp_id	= @mlp_id	AND
										ISNULL(mlp.mlp_isFixedPrice,'False') = 'False'

							IF @mlp_mustUpdate_prli_id4MercadoShop = 'True'
								BEGIN
									UPDATE tbMercadoLibre_ItemsPublicados			WITH (ROWLOCK)
										SET	mlp_mustUpdate_prli_id4MercadoShop			= 'False'
										FROM tbMercadoLibre_ItemsPublicados mlp
										WHERE	mlp.comp_id = @comp_id  AND
												mlp.mlp_id	= @mlp_id
								END

							IF @optval_statusId IN (2,4)  -- mos 014-2024: Solo manda a Meli si estan Activas. Se puso esto x q arriba se puso q act x mas q esten en pausado o en pausado forzado
								BEGIN
									INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
									(
										comp_id,
										mlp_id,
										mlproc_cd,
										[user_id],
										mlproc_option,
										mlproc_decimalValue,
										mlproc_isProcessed,
										mlproc_isCancelled,
										mlproc_priority,
										mlproc_stringValue,
										mlproc_integerValue,
										mlproc_isWithErrorTryNumber,
										mlproc_bigintegerValue,
										mlproc_textValue,
										mlproc_internalID
									)
									VALUES
									(
										@comp_id,
										@mlp_id,
										GETDATE(),
										@intUserID,
										8,
										@intPrecioML,	-- Le suima el IVA en subUpdatePrice mas el costo de envio
										'False',
										'False',
										0,
										'',
										0,
										0,
										0,
										'',
										5
									)

								END





						END
				END


			FETCH NEXT FROM curPublicaciones INTO @comp_id,
												  @mlp_id,
												  @optval_statusId,
												  @mlp_Active,
												  @mls_id,
												  @decAvailableStockMAX,
												  @decAvailableStockSUM,
												  @stor_id4StockAvailability,
												  @intItemID,
												  @mlp_initQty,
												  @mlp_minQty4Pause	,
												  @mls_disableAutoActivationFromStockAvailability,
												  @mlp_allowPublicationsWithNoStock	,
												  @mlp_force2CheckStock	,
												  @bitHasVariations,
												  @decmlp_lastPublicatedAvailableQTY	,
												  @decmlp_price

	END
	CLOSE		curPublicaciones
	DEALLOCATE	curPublicaciones




	-- -------------------------------------------------------------------------------
	-- Inserta verificacion de todas las ORDENES pendientes de convertirse en PEDIDO
	-- de todas las tiendas activas y de todas las compañias.
	-- -------------------------------------------------------------------------------
	INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK) -- mos 09-08-2019
	(
		comp_id,
		mlproc_option,
		mlproc_integerValue,
		mlproc_isProcessed,
		mlproc_isCancelled,
		mlproc_priority,
		mlproc_internalID
	)
		SELECT	DISTINCT
				tmls.comp_id,
				11,
				tmls.mls_id,
				0,
				0,
				9999999,
				6
			FROM tbMercadoLibre_Stores					tmls		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
				ON	tmlip.comp_id	= tmls.comp_id AND
					tmlip.mls_id	= tmls.mls_id
			INNER JOIN tbMercadoLibre_ordersDetail		tmlod		WITH (NOLOCK)
				ON	tmlod.comp_id	= tmlip.comp_id AND
					tmlod.mlp_id	= tmlip.mlp_id
			INNER JOIN tbMercadoLibre_ordersHeader		tmloh		WITH (NOLOCK)
				ON	tmloh.comp_id	= tmlod.comp_id AND
					tmloh.mlo_id	= tmlod.mlo_id
			LEFT JOIN tbMercadoLibre_updateQueue		tmluq		WITH (NOLOCK)
				ON	tmluq.comp_id				= tmls.comp_id	AND
					tmluq.mlproc_option			= 11			AND
					tmluq.mlproc_integerValue	= tmls.mls_id	AND
					tmluq.mlproc_isProcessed	= 0				AND
					tmluq.mlproc_isCancelled	= 0
			WHERE	ISNULL(tmls.mls_disabled,'False')	= 'False'	AND
					tmloh.mlo_isSaleOrderGenerated	= 'False'		AND
					tmloh.mlo_isCancelled			= 'False'		AND
					tmloh.mlo_status				= 'paid'		AND
					tmlip.mlp_creationDate		   <= tmloh.ML_date_created	AND
					ISNULL(tmlip.mlp_publicationID,'') <> ''		AND
					tmluq.comp_id IS NULL

	-- Carga verificacion por Posibles Ordenes Sin Publicacion en el Sistema.
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK) -- mos 09-08-2019
			(
				comp_id,
				mlproc_option,
				mlproc_integerValue,
				mlproc_isProcessed,
				mlproc_isCancelled,
				mlproc_priority,
				mlproc_internalID
			)
				SELECT	DISTINCT
						tmls.comp_id,
						11,
						tmls.mls_id,
						0,
						0,
						9999999,
						687
					FROM tbMercadoLibre_Stores					tmls		WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_ordersHeader		tmloh		WITH (NOLOCK)
						ON	tmloh.comp_id	= tmls.comp_id AND
							tmloh.mls_id	= tmls.mls_id
					--INNER JOIN tbMercadoLibre_ItemsPublicados	tmlip		WITH (NOLOCK)
					--	ON	tmlip.comp_id	= tmls.comp_id AND
					--		tmlip.mls_id	= tmls.mls_id
					INNER JOIN tbMercadoLibre_ordersDetail		tmlod		WITH (NOLOCK)
						ON	tmlod.comp_id	= tmloh.comp_id AND
							tmlod.mlo_id	= tmloh.mlo_id

					LEFT JOIN tbMercadoLibre_updateQueue		tmluq		WITH (NOLOCK)
						ON	tmluq.comp_id				= tmls.comp_id	AND
							tmluq.mlproc_option			= 11			AND
							tmluq.mlproc_integerValue	= tmls.mls_id	AND
							tmluq.mlproc_isProcessed	= 0				AND
							tmluq.mlproc_isCancelled	= 0
					WHERE	ISNULL(tmls.mls_disabled,'False')	= 'False'						AND
							ISNULL(tmls.mls_orderWithNoPublicatedItem_Enabled,'False') = 'True' AND
							tmloh.mlo_isSaleOrderGenerated	= 'False'							AND
							tmloh.mlo_isCancelled			= 'False'							AND
							tmloh.mlo_status				= 'paid'							AND
							--tmlip.mlp_creationDate		   <= tmloh.ML_date_created	AND
							--ISNULL(tmlip.mlp_publicationID,'') <> ''		AND
							tmluq.comp_id IS NULL

		END

