	-- -------------------------------------------------------------------------------
	-- Si esta Inactiva y tiene stock y permite reactivar automaticamente lo hace.
	-- MOS: 13-08-2019, ver abajo
	-- -------------------------------------------------------------------------------

		BEGIN

			-- -------------------------------------------------------------------------------
			-- MOS 08-2024: pongo las publis a activar en una TEMPORAL para activarlas pero tambien actualizar precio y stock
			-- -------------------------------------------------------------------------------
			DECLARE		@tmpPublicacionesAActivar TABLE(mlp_id INT)
			INSERT INTO @tmpPublicacionesAActivar
			(
				mlp_id
			)
				SELECT 		tmlip.mlp_id
					FROM	tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_Stores		tmls		WITH (NOLOCK)
						ON	tmls.comp_id = tmlip.comp_id		AND
							tmls.mls_id  = tmlip.mls_id
					LEFT JOIN tbMercadoLibre_ItemsPublicadosVariations tmlipv	WITH (NOLOCK)
						ON	tmlipv.comp_id		= tmlip.comp_id AND
							tmlipv.mlp_id		= tmlip.mlp_id	AND
							tmlipv.mlpv_disabled= 'False'
					LEFT JOIN tbMercadoLibre_updateQueue	tmp			WITH (NOLOCK)
						ON	tmp.comp_id			= tmlip.comp_id AND
							tmp.mlp_id			= tmlip.mlp_id  AND
							(tmp.mlproc_isProcessed = 0 AND tmp.mlproc_isCancelled = 0)		AND
							tmp.mlproc_option	= 7
					WHERE	ISNULL(tmls.mls_disabled,'False')	= 'False'					AND
							tmp.comp_id IS NULL												AND
							tmlip.mlp_Active		= 'False'								AND
							tmlip.optval_statusId	= 3										AND
							ISNULL(tmlip.mlp_publicationID,'') <> ''						AND
							tmls.mls_disableAutoActivationFromStockAvailability = 'False'	AND
							-- MOS   13-8-2019, se saco esto y se puso el control en el HAVING para que sirva para las variaciones.
							--dbo.fnGetAStock4MaxAssociation(tmlip.comp_id, tmls.stor_id4StockAvailability, tmlip.item_id, 999999999) > tmlip.mlp_minQty4Pause	AND
							ISNULL(tmlip.mlp_publicationID,'') <> ''
					GROUP BY	tmlip.comp_id,
								tmlip.mlp_id,
								tmlip.optval_statusId,
								tmlip.mlp_Active,
								tmlip.mls_id,
								tmls.stor_id4StockAvailability,
								tmlip.item_id,
								tmlip.mlp_initQty,
								ISNULL(tmlip.mlp_minQty4Pause,0),
								ISNULL(tmls.mls_disableAutoActivationFromStockAvailability,'False'),
								ISNULL(tmlip.mlp_allowPublicationsWithNoStock,'False'),
								ISNULL(tmlip.mlp_force2CheckStock,'False'),
								tmlipv.comp_id,
								tmlip.mlp_lastPublicatedAvailableQTY,
								tmlip.mlp_price,
								tmlip.mlp_minQty4Pause
					HAVING  SUM(
								CASE
									WHEN tmlipv.item_id IS NULL THEN  dbo.fnGetMaximumValue(0,	dbo.fnGetAStock4MaxAssociation(tmlip.comp_id,
																																CASE
																																	WHEN tmlip.stor_id4StockAvailability IS NOT NULL THEN	tmlip.stor_id4StockAvailability
																																	ELSE													tmls.stor_id4StockAvailability
																																END
																															   , tmlip.item_id, 999999999))
									ELSE							  dbo.fnGetMaximumValue(0,	dbo.fnGetAStock4MaxAssociation(tmlip.comp_id,	CASE
																																					WHEN tmlip.stor_id4StockAvailability IS NOT NULL THEN	tmlip.stor_id4StockAvailability
																																					ELSE													tmls.stor_id4StockAvailability
																																				END, tmlipv.item_id, 999999999))
								END
								) > tmlip.mlp_minQty4Pause


				INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
				(
					comp_id,
					mlp_id,
					mlproc_option,
					mlproc_integerValue,
					mlproc_isProcessed,
					mlproc_isCancelled,
					mlproc_priority,
					mlproc_decimalValue,
					mlproc_stringValue,
					mlproc_internalID
				)
					SELECT 		@comp_id,
								tmlip.mlp_id,
								8,
								0,
								'False',
								'False',
								0,
								0,
								'*3',
								8233
						FROM	@tmpPublicacionesAActivar tmlip


					-- Mando a que le recargue stock segun pueda y la active   **864654ef987987  MOS 03-06-2019
				INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
				(
					comp_id,
