					mlproc_option,
					mlproc_integerValue,
					mlproc_isProcessed,
					mlproc_isCancelled,
					mlproc_priority,
					mlproc_decimalValue,
					mlproc_stringValue,
					mlproc_internalID
				)
					SELECT 		@comp_id,
								tmlip.mlp_id,
								4,
								0,
								'False',
								'False',
								1,
								0,
								'*3',
								8234
						FROM	@tmpPublicacionesAActivar tmlip


				INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
