	-- -------------------------------------------------------------------------------
	-- Si un Articulo esta DESHABILITADO pone la publicacion en PAUSADO Forzado
	-- -------------------------------------------------------------------------------
	UPDATE tbMercadoLibre_ItemsPublicados
		SET optval_statusId = 6
		FROM tbMercadoLibre_ItemsPublicados		tmlip
		INNER JOIN tbItem						ti			WITH (NOLOCK)
			ON	ti.comp_id			= tmlip.comp_id		AND
				ti.item_id			= tmlip.item_id
		INNER JOIN tbMercadoLibre_Stores		tmls		WITH (NOLOCK)
			ON	tmls.comp_id		= tmlip.comp_id		AND
				tmls.stor_id		= tmlip.stor_id
		WHERE	tmls.mls_disabled	= 'False'			AND
				ti.item_disabled	= 'True'
	-- -------------------------------------------------------------------------------
	-- -------------------------------------------------------------------------------
	-- Si esta en FORZAR PAUSADO, LA PAUSA SI O SI.		    -->> Ver Paso ANTERIOR !!!
	-- -------------------------------------------------------------------------------
	INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
	(
		comp_id,
		mlp_id,
		mlproc_option,
		mlproc_integerValue,
		mlproc_isProcessed,
		mlproc_isCancelled,
		mlproc_priority,
		mlproc_decimalValue,
		mlproc_stringValue,
		mlproc_internalID
	)
	SELECT 		tmlip.comp_id,
				tmlip.mlp_id,
				7,
				6,
				'False',
				'False',
				0,
				0,
				'*4',
				9
		FROM	tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_Stores		tmls		WITH (NOLOCK)
			ON	tmls.comp_id	= tmlip.comp_id		AND
				tmls.mls_id		= tmlip.mls_id
		WHERE	ISNULL(tmls.mls_disabled,'False')	= 'False'	AND
				tmlip.mlp_Active					= 'True'	AND
				tmlip.optval_statusId				= 6			AND
				ISNULL(tmlip.mlp_publicationID,'') <> ''
			-- -------------------------------------------------------------------------------



	-- -------------------------------------------------------------------------------
	-- Califica todas las ordenes ENTREGADAS (CON ENVIOS) pendientes de calificar.
	-- -------------------------------------------------------------------------------
	-- MOS 02-2022: en JFC es esta MIERDA lo que revienta los logs.
	INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
	(
		comp_id,
		mlproc_option,
		mlproc_integerValue,
		mlproc_isProcessed,
		mlproc_isCancelled,
		mlproc_priority,
		mlp_id,
		mlproc_bigintegerValue,
		mlproc_stringValue,
		mlproc_internalID
	)
		SELECT	tmls.comp_id,
				13,
				tmloh.mlo_id,
				0,
				0,
				99999999	 ,
				tmlod.mlp_id,
				tmloh.ML_id,
				'',
				-- MOS 02-2022
				--ISNULL(tmls.mls_qualifiedOKMessage,'') +		CASE
				--													WHEN tmls.mls_qualifiedOKInsertLink4UserQualification = 1 THEN 'Por favor te pedimos si podes calificarnos https://feedback.mercadolibre.com.ar/feedback?orderId=' + dbo.fnStrAllTrim( convert(nvarchar(30),tmloh.ML_id)) + '" target="_blank">haciendo clic acá '
				--													ELSE ''
				--												END,
				10
			FROM tbMercadoLibre_ordersHeader		tmloh		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ordersDetail	tmlod		WITH (NOLOCK)
				ON	tmlod.comp_id	= tmloh.comp_id AND
					tmlod.mlo_id	= tmloh.mlo_id
			INNER JOIN tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
				ON	tmlip.comp_id	= tmlod.comp_id AND
					tmlip.mlp_id	= tmlod.mlp_id
			INNER JOIN tbMercadoLibre_ordersShipping AS tmlos	WITH (NOLOCK)
				ON	tmlos.comp_id	= tmloh.comp_id	AND
					tmlos.mlo_id	= tmloh.mlo_id
			INNER JOIN tbMercadoLibre_Stores		  tmls		WITH (NOLOCK)
				ON	tmls.comp_id	= tmlip.comp_id AND
					tmls.mls_id		= tmlip.mls_id
			WHERE	tmloh.mlo_isqualified			= 0			AND
					tmloh.mlo_isDelivered			= 1			AND
					(tmlos.MLshipping_mode = 'me1' OR tmlos.MLSelf_Service = 1) AND  -- MOS 02-2022: Solo decir que ya fue entregada si YO la entrego, no si la entrega MeLi  (RETIRA EN TIENDA o ME1, el resto ya lo informa MeLi)
					tmloh.mlo_isSaleOrderGenerated	= 1			AND
					ISNULL(tmlip.mlp_publicationID,'') <> ''	AND
					ISNULL(tmls.mls_disabled,'False')	= 'False'


			UPDATE tbMercadoLibre_ordersHeader	WITH (ROWLOCK)
				SET mlo_isqualified = 1
				FROM tbMercadoLibre_ordersHeader tmloh
				INNER JOIN tbMercadoLibre_ordersDetail	tmlod		WITH (NOLOCK)
					ON	tmlod.comp_id	= tmloh.comp_id AND
						tmlod.mlo_id	= tmloh.mlo_id
				INNER JOIN tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
					ON	tmlip.comp_id	= tmlod.comp_id AND
						tmlip.mlp_id	= tmlod.mlp_id
				INNER JOIN tbMercadoLibre_ordersShipping AS tmlos	WITH (NOLOCK)
					ON	tmlos.comp_id	= tmloh.comp_id	AND
						tmlos.mlo_id	= tmloh.mlo_id
				INNER JOIN tbMercadoLibre_Stores		  tmls		WITH (NOLOCK)
					ON	tmls.comp_id	= tmlip.comp_id AND
						tmls.mls_id		= tmlip.mls_id
				WHERE	tmloh.mlo_isqualified			= 0			AND
						tmloh.mlo_isDelivered			= 1			AND
						(tmlos.MLshipping_mode = 'me1' OR tmlos.MLSelf_Service = 1) AND  -- MOS 02-2022: Solo decir que ya fue entregada si YO la entrego, no si la entrega MeLi  (RETIRA EN TIENDA o ME1, el resto ya lo informa MeLi)
						tmloh.mlo_isSaleOrderGenerated	= 1			AND
						ISNULL(tmlip.mlp_publicationID,'') <> ''	AND
						ISNULL(tmls.mls_disabled,'False')	= 'False'
	-- -------------------------------------------------------------------------------



