	-- -------------------------------------------------------------------------------








	-- -------------------------------------------------------------------------------
	-- Verifica que no haya quedado alguna ORDEN de ML sin cargar en el sistema
	-- cada 4 horas
	-- -------------------------------------------------------------------------------
	DECLARE			@lastMercadoLibreOrderVerification		AS DATETIME
	DECLARE			@lastMercadoLibreCatalogVerification	AS DATETIME
	DECLARE			@lastMercadoLibreOrderVerification90012 AS DATETIME
	DECLARE			@lastMercadoLibreOrderVerification90014 AS DATETIME
	SELECT TOP 1	@lastMercadoLibreOrderVerification		= ISNULL(tsdv.lastMercadoLibreOrderVerification,GETDATE()-1000),
					@lastMercadoLibreCatalogVerification	= ISNULL(tsdv.lastMercadoLibreCatalogVerification,GETDATE()-1000),
					@lastMercadoLibreOrderVerification90012 = ISNULL(tsdv.lastMercadoLibreOrderVerification90012,GETDATE()-1000),
					@lastMercadoLibreOrderVerification90014 = ISNULL(tsdv.lastMercadoLibreOrderVerification90014,GETDATE()-1000)
		FROM tbSystem_DatabaseVersion tsdv	WITH (NOLOCK)

	-- Verificacion de las ultimas 600 - NOCTURNA, Estén o NO Cargadas x si no se actualizó algún estado cada 72 horas.
	-- No bajar de 3 dias, esto HACE MIERDA EL SERVER
	IF ABS(DATEDIFF(DAY, GETDATE(), @lastMercadoLibreOrderVerification90014)) >= 3 AND DATEPART(hour,GETDATE()) BETWEEN 2 AND 4
		BEGIN

			UPDATE tbSystem_DatabaseVersion	WITH (ROWLOCK)
				SET lastMercadoLibreOrderVerification		= GETDATE(),
					lastMercadoLibreOrderVerification90014	= GETDATE()	,
					lastMercadoLibreOrderVerification90012  =  GETDATE()

			-- MOS 03-2024: Borro cualquier otra mierda que este pendiente de procesar y pongo esta q es la q me interesa.
			UPDATE tbMercadoLibre_updateQueue
				SET mlproc_isCancelled = 1
				WHERE	mlproc_option		= 21	AND
						mlproc_isProcessed	= 0		AND
						mlproc_isCancelled	= 0


			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				mlproc_option,
				mlproc_integerValue,
				mlproc_bigintegerValue,
				mlproc_isProcessed,
				mlproc_isCancelled,
				mlproc_priority,
				mlproc_internalID
			)

			SELECT 		DISTINCT
						tmlip.comp_id,
						(
							SELECT TOP 1 oo.mlp_id
								FROM tbMercadoLibre_ItemsPublicados oo		WITH (NOLOCK)
								WHERE	oo.comp_id		= tmls.comp_id AND
										oo.mls_id       = tmls.mls_id  AND
										oo.mlp_Active	= 'True'

						)    [mlp_id],
						21,
						tmls.mls_id,
						tmls.MLUser_Id,
						'False',
						'False',
						99999,
						90014		-- NO CAMBIAR se usa en Código ASP
				FROM	tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
				INNER JOIN tbMercadoLibre_Stores		tmls		WITH (NOLOCK)
					ON	tmls.comp_id			= tmlip.comp_id		AND
						tmls.mls_id				= tmlip.mls_id
				WHERE	ISNULL(tmls.mls_disabled,'False')	= 'False'	AND
						tmlip.mlp_Active					= 'True'	AND
						ISNULL(tmlip.mlp_publicationID,'')	<> ''

		END
	-- Verificacion de las ultimas 200, eran 400 - NOCTURNA, Solo las No Cargadas
	ELSE IF ABS(DATEDIFF(hour, GETDATE(), @lastMercadoLibreOrderVerification)) >= 12 AND DATEPART(hour,GETDATE()) BETWEEN 2 AND 4
		BEGIN

			UPDATE tbSystem_DatabaseVersion	WITH (ROWLOCK)
				SET lastMercadoLibreOrderVerification		=  GETDATE(),
					lastMercadoLibreOrderVerification90012  =  GETDATE()	-- que NO se ejecute esto si ya pedi la grande

			-- MOS 03-2024: Borro cualquier otra mierda que este pendiente de procesar y pongo esta q es la q me interesa.
			UPDATE tbMercadoLibre_updateQueue
				SET mlproc_isCancelled = 1
				WHERE	mlproc_option		= 21	AND
						mlproc_isProcessed	= 0		AND
						mlproc_isCancelled	= 0

			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				mlproc_option,
				mlproc_integerValue,
				mlproc_bigintegerValue,
				mlproc_isProcessed,
				mlproc_isCancelled,
				mlproc_priority,
				mlproc_internalID
			)

			SELECT 		DISTINCT
						tmlip.comp_id,
						(
							SELECT TOP 1 oo.mlp_id
								FROM tbMercadoLibre_ItemsPublicados oo		WITH (NOLOCK)
								WHERE	oo.comp_id		= tmls.comp_id AND
										oo.mls_id       = tmls.mls_id  AND
										oo.mlp_Active	= 'True'

						)    [mlp_id],
						21,
						tmls.mls_id,
						tmls.MLUser_Id,
						'False',
						'False',
						99999,
						12
				FROM	tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
				INNER JOIN tbMercadoLibre_Stores		tmls		WITH (NOLOCK)
					ON	tmls.comp_id			= tmlip.comp_id		AND
						tmls.mls_id				= tmlip.mls_id
				WHERE	ISNULL(tmls.mls_disabled,'False')	= 'False'	AND
						tmlip.mlp_Active					= 'True'	AND
						ISNULL(tmlip.mlp_publicationID,'')	<> ''

		END
	ELSE  IF ABS(DATEDIFF(minute, GETDATE(), @lastMercadoLibreOrderVerification90012)) >= 240 --**jhy7ilgrd MOS 05-2023, es DEMASIADO  180 -- MOS 03-2022, eran 120	-- Verificacion rapida de los generados en la ultimas X horas
		BEGIN

			UPDATE tbSystem_DatabaseVersion	WITH (ROWLOCK)
							SET lastMercadoLibreOrderVerification90012  =  GETDATE()

			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				mlproc_option,
				mlproc_integerValue,
				mlproc_bigintegerValue,
				mlproc_isProcessed,
				mlproc_isCancelled,
				mlproc_priority,
				mlproc_internalID
			)

			SELECT 		DISTINCT
						tmlip.comp_id,
						(
							SELECT TOP 1 oo.mlp_id
								FROM tbMercadoLibre_ItemsPublicados oo		WITH (NOLOCK)
								WHERE	oo.comp_id		= tmls.comp_id AND
										oo.mls_id       = tmls.mls_id  AND
										oo.mlp_Active	= 'True'

						)    [mlp_id],
						21,
						tmls.mls_id,
						tmls.MLUser_Id,
						'False',
						'False',
						99999,
						90012 -- NO CAMBIAR se usa en Código ASP
				FROM	tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
				INNER JOIN tbMercadoLibre_Stores		tmls		WITH (NOLOCK)
					ON	tmls.comp_id			= tmlip.comp_id		AND
						tmls.mls_id				= tmlip.mls_id
				WHERE	ISNULL(tmls.mls_disabled,'False')	= 'False'	AND
						tmlip.mlp_Active					= 'True'	AND
						ISNULL(tmlip.mlp_publicationID,'')	<> ''

		END



	DECLARE @mustVerifyCatalog AS BIT = 'False'
	-- cada 12 horas verifica las publicaciones disponibles para catalogo.
	IF ABS(DATEDIFF(hour, GETDATE(), @lastMercadoLibreCatalogVerification)) >= 72 AND DATEPART(hour,GETDATE()) BETWEEN 3 AND 5
		BEGIN

			SET @mustVerifyCatalog = 'True'
			UPDATE tbSystem_DatabaseVersion	WITH (ROWLOCK)
				SET lastMercadoLibreCatalogVerification =  GETDATE()

			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				mlproc_option,
				mlproc_integerValue,
				mlproc_bigintegerValue,
				mlproc_isProcessed,
				mlproc_isCancelled,
				mlproc_priority,
				mlproc_internalID
			)

			SELECT 		DISTINCT
						tmlip.comp_id,
						(
							SELECT TOP 1 oo.mlp_id
								FROM tbMercadoLibre_ItemsPublicados oo		WITH (NOLOCK)
								WHERE	oo.comp_id		= tmls.comp_id AND
										oo.mls_id       = tmls.mls_id  AND
										oo.mlp_Active	= 'True'

						)    [mlp_id],
						47,
						tmls.mls_id,
						tmls.MLUser_Id,
						'False',
						'False',
						99999,
						1265
				FROM	tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
				INNER JOIN tbMercadoLibre_Stores		tmls		WITH (NOLOCK)
					ON	tmls.comp_id			= tmlip.comp_id		AND
						tmls.mls_id				= tmlip.mls_id
				WHERE	ISNULL(tmls.mls_disabled,'False')	= 'False'	AND
						tmlip.mlp_Active					= 'True'	AND
						ISNULL(tmlip.mlp_publicationID,'')	<> ''

		END
	-- -------------------------------------------------------------------------------



	-- si el de arriba se generó, este también.
	IF @mustVerifyCatalog = 'true'
		BEGIN

			UPDATE tbSystem_DatabaseVersion	WITH (ROWLOCK)
				SET lastMercadoLibreCatalogVerification =  GETDATE()

			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				mlproc_option,
				mlproc_integerValue,
				mlproc_bigintegerValue,
				mlproc_isProcessed,
				mlproc_isCancelled,
				mlproc_priority,
				mlproc_internalID
			)

			SELECT 		DISTINCT
						tmlip.comp_id,
						(
							SELECT TOP 1 oo.mlp_id
								FROM tbMercadoLibre_ItemsPublicados oo		WITH (NOLOCK)
								WHERE	oo.comp_id		= tmls.comp_id AND
										oo.mls_id       = tmls.mls_id  AND
										oo.mlp_Active	= 'True'

						)    [mlp_id],
						49,
						tmls.mls_id,
						tmls.MLUser_Id,
						'False',
						'False',
						99999,
						1265
				FROM	tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
				INNER JOIN tbMercadoLibre_Stores		tmls		WITH (NOLOCK)
					ON	tmls.comp_id			= tmlip.comp_id		AND
						tmls.mls_id				= tmlip.mls_id
				WHERE	ISNULL(tmls.mls_disabled,'False')	= 'False'	AND
						tmlip.mlp_Active					= 'True'	AND
						ISNULL(tmlip.mlp_publicationID,'')	<> ''

		END
	-- -------------------------------------------------------------------------------


	-- -------------------------------------------------------------------------------
	-- Pone a forzar a actualizar el token cada 2 horas
	-- -------------------------------------------------------------------------------
	DECLARE @bitCanIDoIt AS BIT = 'False'
	SET @bitCanIDoIt = 'False'
	EXEC spSystem_LastExecutionControl_CanDoIt -1,
												-1,
											123789,
				   								180,
										@bitCanIDoIt OUTPUT
	IF @bitCanIDoIt = 'True'
		BEGIN

			INSERT INTO tbMercadoLibre_updateQueue		WITH (ROWLOCK)
			(
				comp_id,
				mlp_id,
				mlproc_option,
				mlproc_integerValue,
				mlproc_bigintegerValue,
				mlproc_isProcessed,
				mlproc_isCancelled,
				mlproc_priority,
				mlproc_internalID
			)

			SELECT 		DISTINCT
						tmls.comp_id,
						NULL [mlp_id],
						51,
						tmls.mls_id,
						tmls.MLUser_Id,
						'False',
						'False',
						99999,
						2265
				FROM	tbMercadoLibre_Stores		tmls		WITH (NOLOCK)
				WHERE	ISNULL(tmls.mls_disabled,'False')	= 'False'
		END
	-- -------------------------------------------------------------------------------




	-- -------------------------------------------------------------------------------
	-- Por las dudas se fuerza a que toda orden con PEDIDO generado no comprometa
	-- stock. Esto igualmente ya lo hace dbo.spMercadoLibre_insertSaleOrder
	-- -------------------------------------------------------------------------------
	UPDATE  tbMercadoLibre_ordersDetail						WITH (ROWLOCK)
		SET mlo_is4AvailableStock = 0
		FROM tbMercadoLibre_ordersDetail		tmlod
		INNER JOIN tbMercadoLibre_ordersHeader	tmloh		WITH (NOLOCK)
		ON	tmloh.comp_id			= tmlod.comp_id		AND
			tmloh.mlo_id			= tmlod.mlo_id
		WHERE	tmlod.mlo_is4AvailableStock			= 'True'  AND
				(
				  tmloh.mlo_isSaleOrderGenerated	= 'True'  OR
				  tmloh.mlo_isCancelled				= 'True'  OR
				  tmloh.mlo_isSaleOrderEmmited      = 'True'  OR
				  tmloh.mlo_status					= 'cancelled'
				)
	-- -------------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------
	-- Verifica Ordenes que Ya fueron generadas y estan como NO generadas
	-- -------------------------------------------------------------------------------
	IF (
			DATEPART(hh,GETDATE()) BETWEEN 3 AND 4
	   )
		BEGIN
			UPDATE tbMercadoLibre_ordersHeader
				SET mlo_isSaleOrderGenerated = 1
				FROM tbMercadoLibre_ordersHeader	tmloh		WITH (NOLOCK)
				LEFT JOIN tbSaleOrderDetail			sod			WITH (NOLOCK)
					ON	sod.comp_id		= tmloh.comp_id		AND
						sod.mlo_id		= tmloh.mlo_id
				LEFT JOIN tbSaleOrderHeader			soh			WITH (NOLOCK)
					ON	soh.comp_id		= tmloh.comp_id		AND
						soh.mlo_id		= tmloh.mlo_id
				LEFT JOIN tbItemTransactions		it			WITH (NOLOCK)
					ON	it.comp_id		= tmloh.comp_id		AND
						it.mlo_id		= tmloh.mlo_id
				LEFT JOIN tbCommercialTransactions	ct			WITH (NOLOCK)
					ON	ct.comp_id		= tmloh.comp_id		AND
						ct.mlo_id		= tmloh.mlo_id
				WHERE	tmloh.mlo_isSaleOrderGenerated	= 0 AND
						tmloh.mlo_isSaleOrderEmmited	= 0 AND
						tmloh.mlo_isCollected			= 0	AND
						(
							soh.comp_id IS NOT NULL OR
							sod.comp_id IS NOT NULL OR
							it.comp_id  IS NOT NULL OR
							ct.comp_id  IS NOT NULL
						)
		END
	-- -------------------------------------------------------------------------------




	-- -------------------------------------------------------------------------------
	-- SI UNA pUBLICACION ESTA finalizada no DEBE ESTAR COMO pENDIENTE DE rEVISION
	-- para NO Molestar al Pedo ya que jamas se podrá grabar nuevamente.
	-- -------------------------------------------------------------------------------
	UPDATE tbMercadoLibre_ItemsPublicados	WITH (ROWLOCK)
		SET mlp_4Revision		= 'False' ,
			mlp_revisionMessage = ''
		WHERE	comp_id			= @comp_id	AND
				optval_statusId = 5			AND
				mlp_4Revision	= 'True'
	-- -------------------------------------------------------------------------------



	-- -------------------------------------------------------------------------------
	-- SI UNA pUBLICACION ESTA Pausada fORZADA SACA CUALQUIER ACTUALIZACION QUE NO SEA
	-- LA DE pAUSAR LA pUBLICACION.
	-- -------------------------------------------------------------------------------
	UPDATE tbMercadoLibre_updateQueue						WITH (ROWLOCK)
		SET mlproc_isCancelled = 1
		FROM tbMercadoLibre_updateQueue tmp
		INNER JOIN tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
			ON	tmlip.comp_id	= tmp.comp_id AND
				tmlip.mlp_id	= tmp.mlp_id
		WHERE	tmp.mlproc_option <> 7		AND
				tmlip.optval_statusId = 6	AND
				tmp.mlproc_isCancelled = 0	AND
				tmp.mlproc_isProcessed = 0




	-- ------------------------------------------------------------------------------
	-- Borra lod Jobs de una tienda deshabilitada que no sean de cambiar estado
	-- o de publicaciones desenlazadas
	-- o de publicaciones sin ID que no sean Publicar!
	-- ------------------------------------------------------------------------------
	DELETE FROM tbMercadoLibre_updateQueue			WITH (ROWLOCK)
		FROM tbMercadoLibre_updateQueue tmluq
		INNER JOIN tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
			ON	tmlip.comp_id	= tmluq.comp_id AND
				tmlip.mlp_id	= tmluq.mlp_id
		INNER JOIN tbMercadoLibre_Stores tmls				WITH (NOLOCK)
			ON	tmls.comp_id	= tmlip.comp_id AND
				tmls.mls_id		= tmlip.mls_id
		WHERE tmls.mls_disabled		= 'True'
				OR
			  tmlip.optval_statusId = 10
				OR
			  (
				ISNULL(tmlip.mlp_publicationID,'') = ''
					AND
				tmluq.mlproc_option		<> 1
			  )
	-- ------------------------------------------------------------------------------



	--DELETE FROM tbMercadoLibre_updateQueue			WITH (ROWLOCK)
	--	FROM tbMercadoLibre_updateQueue tmluq
	--	INNER JOIN tbMercadoLibre_ItemsPublicados tmlip		WITH (NOLOCK)
	--		ON	tmlip.comp_id	= tmluq.comp_id AND
	--			tmlip.mlp_id	= tmluq.mlp_id
	--	INNER JOIN tbMercadoLibre_Stores tmls				WITH (NOLOCK)
	--		ON	tmls.comp_id	= tmlip.comp_id AND
	--			tmls.mls_id		= tmlip.mls_id
	--	WHERE	ISNULL(tmlip.mlp_publicationID,'') = '' AND
	--			tmluq.mlproc_option		<> 1
	--			--tmluq.mlproc_option		= 8	   MOS 29-05-2019





	-- Borra los pendientes de enlazar que ya esten enlazados.
	DELETE FROM tbMercadoLibre_ItemsPublicados_LinkPending				WITH (ROWLOCK)
		FROM tbMercadoLibre_ItemsPublicados_LinkPending tmp
		INNER JOIN tbMercadoLibre_ItemsPublicados		tmlip			WITH (NOLOCK)
			ON	tmlip.comp_id			= tmp.comp_id			AND
				tmlip.mlp_publicationID = tmp.mlpp_publicationID




	--** que las verificaciones de stock se hagan del deposito: stor_id4StockAvailability
	--** Verificar todas las publicaciones que esten como inactivas por no haber stock para que se restauren automaticamente.
	--** Verificar las publicaciones que esten para reactivar y no tengan stock
	--** Verificar las publicaciones ACTIVAS y PUBLICADAS que se hayan quedado sin stock
	--   Una vez x dia verificar TODAS las publicaciones para saber si hay alguna discrepancia entre el estado de actividad de GBP y el de mercadolibre
	--		poniendo como activas las que gbp dice que deben estar activas y como pausadas las que gbp dice que deben estar pausadas y difieron entre esos estados.
	--      Esto deberia poder ejecutarse desde el llamado a la pagina de process.

	--** verificar para todas las publicaciones activas que tenga stock, si no hay pausarla
	--** verificar para todas las publicaciones en republicar que si hay stock dse pongan como activas.
	--   si hay publoicaciones en una tienda inactiva debo pausar a todas las publicaciones
	--** si el stock es menor al minimo, pausarla


	-- -----------------------------------------------------------------------
	-- POne ALERTA si hay tienda con token vencido
	-- -----------------------------------------------------------------------
	BEGIN TRY

		DECLARE @datMeLiToken		AS DATETIME = DATEADD(minute,-360,GETDATE())
		DECLARE @compWithOldToken	AS INT		= NULL
		DECLARE			@bitStoreWithOldToken AS BIT	= 'False'
		SELECT TOP 1	@bitStoreWithOldToken			= 'True',
						@compWithOldToken				= tmls.comp_id
			FROM tbMercadoLibre_Stores	AS tmls	WITH (NOLOCK)
			WHERE	tmls.mls_disabled					= 'False'			AND
					tmls.mls_accessTokenValidUp2Date	< @datMeLiToken		AND
					ISNULL(tmls.mls_enabled4MercadoPagoVerifications,'False') = 'False'



		IF	@bitStoreWithOldToken = 'True'	 --AND
			--1 = 2  -- MOS 03-2024: saque esto asi no joden mas.
			BEGIN
				SELECT ' Insertando Alerta de Token Vencido'
				INSERT INTO tbWorkflow	WITH (ROWLOCK)
				(
					comp_id,
					bra_id,
					wf_type,
					wf_isProcessed,
					user_id_from,
					user_id_assigned,
					user_id_processed,
					--prof_id_assigned,
					wf_dateOfAssigned,
					wf_dateOfProcessing,
					wf_link,
					wf_message1,
					wf_message2,
					wf_message3,
					wf_message4,
					wf_htmlTop,
					wf_htmlBody,
					wf_html_Bottom,
					mlo_id
				)
				SELECT TOP 1
					tmls.comp_id,
					NULL,
					6666,
					'False',
					tmls.[user_id],
					tmls.[user_id] ,
					NULL,
					--tp.prof_id,
					GETDATE(),
					NULL,
					'',
					'MercadoLibre: Token VENCIDO en alguna de las Tiendas ACTIVAS Configuradas.',   -- //+ tmls.mls_desc,
					'' ,
					'',
					'',
					'',
					'',
					'',
					0
					FROM tbMercadoLibre_Stores	AS tmls	WITH (NOLOCK)
					LEFT JOIN tbWorkflow		AS tw	WITH (NOLOCK)
						ON	tw.comp_id							= tmls.comp_id		AND
							tw.wf_type							= 6666				AND
							tw.wf_isProcessed					= 'False'
					WHERE	tmls.mls_disabled					= 'False'			AND
							tmls.mls_accessTokenValidUp2Date	< @datMeLiToken		AND
							tw.comp_id IS  NULL
			END
		ELSE
			BEGIN
				SELECT ' Borrando Alerta de Token Vencido'
				DELETE FROM tbWorkflow		WITH (ROWLOCK)
					WHERE 	wf_type							= 6666				AND
							wf_isProcessed					= 'False'
			END



	END TRY
	BEGIN CATCH
	END CATCH
	-- -----------------------------------------------------------------------


	-- -----------------------------------------------------------------------
	-- MOS 04-2024: a la noche pone que se verifiquen las ordenes de full y flex que figuran como NO entregadas
	-- -----------------------------------------------------------------------
	BEGIN TRY



		IF DATEPART(hh,GETDATE()) BETWEEN 1 AND 4

			BEGIN

				SET @bitCanIDoIt = 'False'
				EXEC spSystem_LastExecutionControl_CanDoIt -1,
															-1,
														5397269,
				   											1200,
													@bitCanIDoIt OUTPUT

				IF @bitCanIDoIt = 'True'
					BEGIN

						INSERT INTO tbMercadoLibre_updateQueue
						(
							comp_id,
							mlproc_cd,
							[user_id],
							mlproc_option,
							mlproc_integerValue,
							mlproc_isProcessed,
							mlproc_isCancelled,
							mlproc_priority,
							mlproc_isWithError,
							mlproc_isWithErrorTryNumber,
							mlproc_guid,
							mlproc_bigintegerValue,
							mlproc_textValue,
							mlproc_integerValue2,
							mlproc_URL,
							mlproc_isProcessedWithError,
							mlproc_ProcessedWithErrorDescription,
							mlproc_ProcessedWithErrorNumber,
							mlproc_internalID,
							mlproc_response,
							mlproc_JSON,
							mlproc_blockCancell
						)


						SELECT	tmloh.comp_id,
								GETDATE(),
								tmls.[user_id],
								48,
								tmloh.mls_id,
								'False',
								'False',
								99999,
								0,
								0,
								NEWID(),
								tmloh.MLorder_id,
								'',
								0,
								'',
								'False',
								'',
								0,
								787878,
								'',
								'',
								'False'

							FROM tbMercadoLibre_ordersHeader			AS tmloh	WITH (NOLOCK)
							INNER JOIN tbMercadoLibre_Stores			AS tmls		WITH (NOLOCK)
								ON	tmls.comp_id	= tmloh.comp_id	AND
									tmls.mls_id		= tmloh.mls_id
							INNER JOIN tbMercadoLibre_ordersShipping	AS tmlos	WITH (NOLOCK)
								ON	tmlos.comp_id	= tmloh.comp_id	AND
									tmlos.mlo_id	= tmloh.mlo_id
							WHERE  (
										tmlos.MLfulfilled		= 1					OR
										tmlos.MLCross_Docking	= 1					OR
										tmlos.ML_logistic_type	= 'cross_docking'	OR
										tmlos.ML_logistic_type	= 'fulfillment'
									)																			AND
									tmloh.mlo_isDelivered = 0													AND
									tmloh.mlo_status <> 'cancelled'												AND
									DATEDIFF(day,tmloh.ML_date_created,GETDATE()) BETWEEN	CASE -- MOS 05-2024: POngo diferentes dias para full o flex
																								WHEN tmlos.ML_logistic_type	= 'cross_docking' THEN 1
																								ELSE 3
									                                                     	END		AND 21		AND
									NOT EXISTS(	SELECT TOP 1  1
													FROM tbMercadoLibre_updateQueue AS tmluq	WITH (NOLOCK)
			           								WHERE	tmluq.comp_id = tmloh.comp_id					AND
			           										tmluq.mlproc_option = 48						AND
			           										tmluq.mlproc_bigintegerValue = tmloh.MLorder_id AND
			           										tmluq.mlproc_isProcessed = 0					AND
			           										tmluq.mlproc_isCancelled = 0
												)

							order by ML_date_created

					END

			END
	END TRY
	BEGIN CATCH
	END CATCH
	-- -----------------------------------------------------------------------






END
GO



