CREATE PROCEDURE [dbo].[spMoneyMovements_insertData]

(
	@comp_id				as int,
	@bra_id					as int,
	@ct_transaction			AS INT,
	@Total					AS DECIMAL(19,4),
	@curr_id				AS INT,
	@BranchCurrencyExchange AS DECIMAL(19,5),
	@isCancelled			AS BIT,
	@svtt_id				AS INT,
	@return_value			AS INT			OUTPUT,
	@ret_ErrorCode			AS INT			OUTPUT,
	@ret_ErrorDescription	AS VARCHAR(100)	OUTPUT
)

as

BEGIN

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''

	INSERT INTO tbMoneyMovements
	(
		comp_id,
		bra_id,
		ct_transaction,
		mm_total,
		curr_id,
		mm_BranchCurrencyExchange,
		mm_isCancelled,
		svtt_id
	)
	VALUES
	(
		@comp_id,
		@bra_id,
		@ct_transaction,
		@Total,
		@curr_id,
		@BranchCurrencyExchange,
		@isCancelled,
		@svtt_id
	)

	Set @return_value = @@IDENTITY

END




GO



