CREATE PROCEDURE [dbo].[spPayments_checkBasicData]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			INT,
	@user_id			INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	/*

	DECLARE @comp_id		INT,
			@bra_id			INT
	DECLARE @lang_id		INT
	DECLARE @user_id		INT
	SELECT	@comp_id		=1,
			@bra_id			=2,
			@lang_id		=2,
			@user_id		=8
	DROP TABLE #tmpData
	*/


	CREATE TABLE #tmpData ( [check] INT )

	/*
	por cada control que se realice al comienzo de las páginas y no esté correcto,
	hay que hacer un insert en la temporal creada arriba
	con el valor correspondiente al table_id de la tabla tbSysTables (siempre deberá ser un valor negativo)
	y este valor está relacionado con la tabla tbSysHelpPages que si tendrá el mensaje de error
	a mostrar al usuario
	*/


	if NOT EXISTS (select 1 from tbCashNumbers				WHERE comp_id = @comp_id and bra_id = @bra_id )
															INSERT INTO #tmpData ([check]) VALUES (-8)
	if NOT EXISTS (select 1 from tbCurrencyExchange			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-9)
	if NOT EXISTS (select 1 from tbCashNumber4Branch4User
				   WHERE comp_id = @comp_id AND bra_id = @bra_id AND [user_id] = @user_id) INSERT INTO #tmpData ([check]) VALUES (-10)
				   --WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-10)
	if NOT EXISTS (select 1 from tbCashAccountant			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-11)

	if NOT EXISTS (select 1 FROM tbBankingAccounts			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-13)
	if NOT EXISTS (select 1 FROM tbTaxName					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-14)
	IF NOT EXISTS (SELECT 1 FROM tbCurrencyExchange tce
				   WHERE	tce.comp_id = @comp_id
				   AND		tce.curr_id_1 = (	SELECT	tc.curr_id
												FROM	tbCompany tc
												WHERE	tc.comp_id	= @comp_id)
				   AND		tce.curr_id_2 = (	SELECT	curr_id
												FROM	tbBranch tb
												WHERE	tb.comp_id	= @comp_id
												AND		tb.bra_id	= @bra_id))
	AND
	   NOT EXISTS (SELECT 1 FROM tbCurrencyExchange tce
				   WHERE	tce.comp_id = @comp_id
				   AND		tce.curr_id_2 = (	SELECT	tc.curr_id
												FROM	tbCompany tc
												WHERE	tc.comp_id	= @comp_id)
				   AND		tce.curr_id_1 = (	SELECT	curr_id
												FROM	tbBranch tb
												WHERE	tb.comp_id	= @comp_id
												AND		tb.bra_id	= @bra_id))		  INSERT INTO #tmpData ([check]) VALUES (-16)

	if NOT EXISTS (select 1 from tbBranchGroupDetail      WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-17)

	SELECT	tut.utexts_desc, tut.utexts_id
	FROM	tbsysUniqueTexts tut
	WHERE	tut.lang_id			= @lang_id
	AND		tut.utexts_id		IN(4, 5, 6)
	AND		EXISTS(SELECT 1 FROM #tmpData)

	UNION

	SELECT	cast(thp.hp_desc AS NVARCHAR(MAX)), thp.page_id
	FROM	tbsysHelpPages			thp
			INNER JOIN #tmpData		td
			ON	td.[check]		= thp.table_id
	WHERE	thp.page_id			= -100020 --este valor está en duro e indica la funcionalidad que se está chequeando
	AND		thp.lang_id			= @lang_id

	ORDER BY 2 DESC


END
GO








CREATE procedure [dbo].[spPayments_getHeaderData]
(
	@comp_id	int,
	@bra_id		int,
	@supp_id	int
)
AS


BEGIN



	set nocount on

	/*
	declare @comp_id	int,
			@bra_id		int,
			@supp_id	int

	select	@comp_id	= 1,
			@bra_id		= 1,
			@supp_id	= 8109
	*/


	declare @curr_id_1							int,
			@curr_id_2							int,
			@bra_PaymentMaximumAdjust			decimal(19,6)
			--@bra_CollectionDefaultDocument		int



	select	@curr_id_1						= b.curr_id							,
				@bra_PaymentMaximumAdjust	= b.bra_PaymentMaximumAdjust
		from	[tbBranch] b				WITH (NOLOCK)
		where	b.bra_id = @bra_id


	select	@curr_id_2 = b.curr_id
		from	[tbSupplier] b				WITH (NOLOCK)
		where	b.[supp_id] = @supp_id


	-- La verdad con esto llegaste al maximo nivel de HIJO DE PUTAAAAAAAAA


--	select
--		@curr_id_2															[CurrIdSupp],
--		LTRIM(RTRIM(ISNULL((select	c.[curr_symbol]
--							from	[tbSupplier] b		WITH (NOLOCK)
--									inner join [tbsysCurrency] c on c.[curr_id] = b.[curr_id]
--							where	b.[supp_id] = @supp_id),'')))			[Currency Supplier],
--		1																	[Value Supplier],
--		@curr_id_1															[CurrIdBranch],
--		(select c.[curr_symbol]	from [tbBranch] b
--		inner join [tbsysCurrency] c on c.[curr_id] = b.[curr_id]
--		where b.bra_id = @bra_id)											[Currency Branch],
--		(dbo.[fnGetExchange](@comp_id, 1, @curr_id_2, @curr_id_1, 0, 0, 0)) [Value Branch],
--		@bra_PaymentMaximumAdjust											[PaymentMaximumAdjust]


	DECLARE @strPaymentAddress AS NVARCHAR(MAX)
	SELECT	@strPaymentAddress = IsNull(ts.supp_paymentAddress,'*')
		FROM tbSupplier ts
		WHERE	ts.comp_id = @comp_id AND
				ts.supp_id = @supp_id


	SELECT
		@strPaymentAddress													[paymentAdress],
		@curr_id_2															[CurrIdSupp],
		LTRIM(RTRIM(ISNULL((select	c.[curr_symbol]
							from	[tbSupplier] b		WITH (NOLOCK)
									inner join [tbsysCurrency] c on c.[curr_id] = b.[curr_id]
							where	b.[supp_id] = @supp_id),'')))			[Currency Supplier],
		1																	[Value Supplier],
		@curr_id_1															[CurrIdBranch],
		(select c.[curr_symbol]	from [tbBranch] b
		inner join [tbsysCurrency] c on c.[curr_id] = b.[curr_id]
		where b.bra_id = @bra_id)											[Currency Branch],
		(dbo.[fnGetExchange](@comp_id, 1, @curr_id_2, @curr_id_1, 0, 0, 0)) [Value Branch],
		@bra_PaymentMaximumAdjust											[PaymentMaximumAdjust]


END
GO







CREATE PROCEDURE [dbo].[spPayments_getMailData]
(
		@comp_id			INT,
		@lang_id			INT	,
		@ct_transaction		INT,
		@bra_id				INT

)
AS

BEGIN


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-----------------------------------------------------------------------------------
	-- Testing
	-----------------------------------------------------------------------------------
	/*

	DECLARE	@comp_id				INT,
			@lang_id				INT	,
			@ct_transaction			INT,
			@bra_id					INT

	SELECT	@comp_id				=1,
			@lang_id				=2,
			@ct_transaction			=10574,
			@bra_id					=1

	*/
	-----------------------------------------------------------------------------------
	BEGIN



		SELECT	tb.bra_MainDesc								[comp_desc],
				tc.smtp_host,
				tc.smtp_port,
				tc.smtp_ssc,
				tc.smtp_user,
				tc.smtp_password,
				isnull(tu.user_email,'')																		[from],
				isnull(ts.supp_email,'')																		[to],
				dbo.fnGetCommercialTransactionDescription(tct.comp_id,	@lang_id,tct.ct_transaction)			[DocumentNumber],
				isnull(tb.bra_body4Payorder,'')																	[bra_body4Payorder]

		FROM	tbCompany										tc

				inner join tbCommercialTransactions				tct
				on  tct.comp_id			= tct.comp_id
				AND tct.bra_id			= tct.bra_id
				AND tct.ct_transaction	= tct.ct_transaction

				INNER JOIN tbBranch								tb
				ON	tb.comp_id			= tct.comp_id	AND
					tb.bra_id			= tct.bra_id

				Inner Join tbsysDocuments						td
				On  td.sd_id			= tct.sd_id

				left JOIN tbUser								tu
				ON tu.[user_id] = tct.[user_id]

				inner JOIN tbSupplier							ts
				on  ts.comp_id			= tct.comp_id
				AND ts.supp_id			= tct.supp_id

		WHERE	tc.comp_id			=   @comp_id
		and		tct.ct_transaction	=   @ct_transaction
		--and		tct.bra_id			=	@bra_id   NO, pasan la re PUTA SESION, FORROS !!!!











	END



end
GO





-- MOS 08-2023, modificaciones de velocidad con indices para vistas.


CREATE  PROCEDURE [dbo].[spPayments_getTotals]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@supp_id			INT,
	@forcedCurrId1		INT,
	@forcedCurrId2		INT,
	@exchange			DECIMAL(19,6),
	@guid				UNIQUEIDENTIFIER,
	@puco_id			INT,
	@tax_id				INT
)
as

BEGIN




	set nocount on
	-- =================================================================================================================
	-- 2010-08-26 - MOH - Parte	: 473
	-- Se agrega un nuevo tab de Conceptos a Pagar en Pagos, este query se agrega para alimentar la nueva funcionalidad
	-- =================================================================================================================
	-- 2010-08-29 - MOH - Ref #1
	-- Se actualiza el cálculo del total del proveedor para los casos en que la moneda del mimso sea diferente de la
	-- moneda de la sucursal
	-- =================================================================================================================



	-- -----------------------------------------------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------------------------------------------
	/*
	declare	@comp_id	int,
			@lang_id	int,
			@bra_id		int,
			@supp_id	int,
			@forcedCurrId1		INT,
			@forcedCurrId2		INT,
			@exchange			DECIMAL(19,6),
			@guid				UNIQUEIDENTIFIER,
			@puco_id			INT,
			@tax_id				INT
	select	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@supp_id	= 8109,
			@forcedCurrId1	=2,
			@forcedCurrId2	=1,
			@exchange	= 4.01,
			@guid		= '2D78DF5D-DC46-4D49-9E46-BE1C6670C3A3',
			@puco_id	= 11,
			@tax_id		= 23
	*/
	-- -----------------------------------------------------------------------------------------------------------------


	declare @d int
	set		@d = 2


	/*** recuperar la moneda de la sucursal pasada como parametro
			(sucursal de donde se ejecuta la consulta)****/
	declare @bra_curr_id	int
	select	@bra_curr_id = b.curr_id
		from	[tbBranch] b	WITH (NOLOCK)
		where	b.comp_id = @comp_id AND -- MOS 08-2023 agregue el comp_id
				b.bra_id = @bra_id
	/************************************************************************************/
	--select @bra_curr_id



	/*** recuperar la moneda del proveedor pasada como parametro 	****/
	declare @supp_curr_id	int
	set		@supp_curr_id = isnull((select	b.curr_id
										from	[tbSupplier] b	WITH (NOLOCK)
										WHERE b.comp_id = @comp_id AND 	b.supp_id = @supp_id),@bra_curr_id)	-- MOS 08-2023 le agregue el comp_id
	/************************************************************************************/
	--select @supp_curr_id

				--47530522


	select

		isnull((select	convert(decimal(18,2),round(sum(round(ctct.[ctct_total],@d) *
																dbo.fnNoZDiv (																-- Ref #1
																ct_ACurrencyExchange																		-- Ref #1
																)
													),@d))
					from	dbo.[tbCommercialTransactionsTmp]								ctct		WITH (NOLOCK)
							inner join [tbCommercialTransactions]							ct			WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))   -- MOS 08-2023WITH (NOLOCK)
							on	ct.comp_id			= ctct.comp_id AND
								ct.[ct_transaction] = ctct.[ctct_transaction]
							inner join dbo.[vwCommercialTransactions_forPurchase]			VCTFS		WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forPurchase))	-- MOS 08-2023
							on	VCTFS.comp_id					=	ct.comp_id
							and VCTFS.ct_transaction			=	ct.ct_transaction
					where	ctct.ctct_guid	=	@guid
					and     VCTFS.[sd_isInBalance]				=	'True'
					and	    VCTFS.[sd_isCredit]					=	'False'
					and	    VCTFS.[sd_isReceipt]				=	'False'),0)							[totalSupplier],



		isnull((select	convert(decimal(18,2),sum(round(dbo.fnGetExchange2(ct.comp_id,
																			ctct.ctct_total,
																			ct.ct_ACurrency  ,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	dbo.[tbCommercialTransactionsTmp]								ctct	WITH (NOLOCK)
						inner join [tbCommercialTransactions]							ct		WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))   -- MOS 08-2023WITH (NOLOCK)
						on	ct.comp_id			= ctct.comp_id	AND
							ct.[ct_transaction] = ctct.[ctct_transaction]
						inner join dbo.[vwCommercialTransactions_forPurchase]			VCTFS		WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_forPurchase))	-- MOS 08-2023
						on	VCTFS.comp_id					=	ct.comp_id
						and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid
				and     VCTFS.[sd_isInBalance]				=	'True'
				and	    VCTFS.[sd_isCredit]					=	'False'
				and	    VCTFS.[sd_isReceipt]				=	'False'),0)							[totalPay],



		isnull((select  convert(decimal(18,2),sum(round(dbo.fnGetExchange2(@comp_id,
															   				vct.amount,
															   				vct.curr_id,
															   				@bra_curr_id,
															   				@forcedCurrId1,
															   				@forcedCurrId2,
															   				@exchange,
															   				'FALSE'),@d)))
				from	vwPaymentsTmp												vct
				where	vct.guid		=	@guid and vct.lang_id = @lang_id),0)					[totalHow],



		isnull((select	convert(decimal(18,2),sum(round(dbo.fnGetExchange2(tmt.comp_id,
																			tmt.tmt_total,
																			tmt.curr_id,
																			@bra_curr_id,
																			@forcedCurrId1,
																			@forcedCurrId2,
																			@exchange,
																			'FALSE'),@d)))
				from	dbo.tbTaxMovementsTmp										tmt
				where	tmt.tmt_guid	=	@guid),0)												[totalRetention],



		isnull((select  convert(decimal(18,2),sum(round(dbo.fnGetExchange2(ctct.comp_id,
																		   ctct.[ctct_total],
																		   ct.curr_id_transaction,
																		   ct.ct_ACurrency,
																		   ct.curr_id_transaction,
																		   ct.ct_ACurrency,
																		   ctct.ctct_exchange,
																		   'FALSE')
														,@d)))
					from	dbo.[tbCommercialTransactionsTmp]							ctct		WITH (NOLOCK)
						inner join [tbCommercialTransactions]						ct				WITH (NOLOCK,INDEX(IX_tbCommercialTransactions_1OLP))   -- MOS 08-2023WITH (NOLOCK)
						on	ct.comp_id			= ctct.comp_id			AND
							ct.[ct_transaction] = ctct.[ctct_transaction]
						inner join dbo.[vwCommercialTransactions_PaymentOnAccount]	VCTFS			WITH (NOLOCK,NOEXPAND,INDEX(CIX_vwCommercialTransactions_PaymentOnAccount)) -- MOS 08-2023
						on	VCTFS.comp_id					=	ct.comp_id
						and VCTFS.ct_transaction			=	ct.ct_transaction
				where	ctct.ctct_guid	=	@guid),0)												[totalOnAccount],



		-- =================================================================================================================
		-- Parte: 473
		-- =================================================================================================================
		isnull((select  convert(decimal(18,2),sum(round(tctopdt.ctopdt_total,@d)))
				from	dbo.tbCommercialTransactionsOtherPaymentsDetailTmp			tctopdt	WITH (NOLOCK)
				where	tctopdt.ctopdt_guid		=	@guid),0)										[totalConcepts]
		-- =================================================================================================================



END
GO




-- ----------------------------------------------------------
-- MOS
-- 04-2009
-- Calcula las retenciones que se deben efectuar en Payments
-- MOS 03-2010
-- MOS 03-2023: [fnGetNETOWithOutRetentionsOfGanancias4OnAccount]
-- ---------------------------------------------------------

CREATE  PROCEDURE [dbo].[spPayments_setRetentions]
(
	@comp_id				as int,
	@bra_id					as int,
	@guid					as UNIQUEIDENTIFIER,
	@onaccount				as decimal(19,6),
	@CurrencyExchange		AS DECIMAL(19,6),
	@user_id				AS INT,
	@processing_Date		AS DATETIME,
	@puco_id				as INT,
	@tax_id					as INT ,
	@intSupplierId			AS int
)
as


BEGIN



	SET NOCOUNT ON
	set dateformat 'ymd'





	-- --------------------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------------------
	/*
	DECLARE @intSupplierId		AS INT
	DECLARE @comp_id			AS INT
	DECLARE @bra_id				AS int
	DECLARE @guid				AS UNIQUEIDENTIFIER
	DECLARE @onaccount			AS DECIMAL(19,6)
	DECLARE @user_id			AS INT
	DECLARE @processing_Date	AS DATETIME
	DECLARE @CurrencyExchange	AS DECIMAL(19,4)
	declare @puco_id			as INT
	declare @tax_id				as INT
	SET @comp_id			= 1
	SET @bra_id				= 1
	Set @onaccount			= 0
	SET @guid				= 'CC14AF72-915F-473F-976B-630DC09B8B6E'
	SET @CurrencyExchange	= 1
	SET @user_id			= 1
	SET @processing_Date	= CONVERT(DATETIME,'2023-01-29')
	SET @puco_id			= 10
	SET @tax_id				= 2
	SET @intSupplierId      = 8110

	--DROP TABLE #tmpDocumentsToPay
	--DROP TABLE #tmpPurchaseConceptsToPay
	--drop table #tmpPurchaseConceptsToPay_Retentions
	--DROP TABLE #tmpTotalRetentionsDoneOfThisMonth
	--DROP TABLE #tmpTotalRetentionsMustDoInThisMonth
	--DROP TABLE #tmpCTBySuppId
	*/
	-- --------------------------------------------------------------------------------------



	-- Borro retenciones Previamente Calculadas para este pago
	DELETE FROM tbTaxMovementsTmp WHERE tmt_guid = @guid AND isCalculated = 'true'

	-- Recupero la Moneda del Proveedor
	DECLARE @intSupplierTaxId		AS INT
	DECLARE @intSupplierCurrency	AS INT
	DECLARE @intSupplierPuco_id		AS INT
	DECLARE @intSupplierCountryId   AS INT
	DECLARE @intSupplierStateId		AS INT
	DECLARE @strSupplierCUIT		AS VARCHAR(20)






	SELECT  Top 1 @intSupplierCurrency = ts.curr_id ,
				  @intSupplierTaxId	   = ts.tax_id_PaymentsRetention,
				  @intSupplierPuco_id  = ts.puco_id,
				  --@comp_id			   = tctt.comp_id,
				  --@bra_id			   = tctt.bra_id,
				  @intSupplierId	   = ts.supp_id,
				  @intSupplierCountryId= ts.country_id,
				  @intSupplierStateId  = ts.state_id,
				  @strSupplierCUIT	   = ts.supp_taxNumber
		FROM tbSupplier ts		WITH (NOLOCK)
		WHERE	ts.comp_id = @comp_id
			AND ts.supp_id = @intSupplierId


	-- Saco los guiones del CUIT para poder buscarlo en las tablas de afip
	SET @strSupplierCUIT = dbo.fnStrCHRTRAN(@strSupplierCUIT,'-','')

	-- Recupero la Moneda de la Sucursal
	DECLARE @intBranchCurrency		AS INT
	DECLARE @datProcessingDate		AS DATETIME
	SELECT  @intBranchCurrency = tb.curr_id ,
			@datProcessingDate = tb.bra_processingDate
		FROM tbBranch tb	WITH (NOLOCK)
		WHERE tb.comp_id  = @comp_id
			AND tb.bra_id = @bra_id




	-- Setea la Fecha de Procesamiento según lo que figura en wfmPayments
	SET @datProcessingDate = @processing_Date





	--=================================================================================================================
	--16-11-2010 -- MOH
	--generación de la fecha del primer y último día del mes a tratar apra reemplazar las funciones month y year
	--en los where correspondientes

	DECLARE @datProcessingDate_from		DATETIME
	DECLARE @datProcessingDate_to		DATETIME

	--obtener el primer día del mes
	SET		@datProcessingDate_from		= @datProcessingDate - DAY(@datProcessingDate) + 1

	--obtener el último día del mes
	SET		@datProcessingDate_to		= DATEADD(MONTH,1,@datProcessingDate - DAY(@datProcessingDate)+1) -1

	--setear la hora 0 en el primer día del mes
	SELECT  @datProcessingDate_from		= dbo.fnGetEnd_or_BeginOfDate(@datProcessingDate_from,'false')

	--setear la máxima hora, minutos y segundos en el último día del mes
	SELECT  @datProcessingDate_to		= dbo.fnGetEnd_or_BeginOfDate(@datProcessingDate_to,'true')

	--SELECT @datProcessingDate_from, @datProcessingDate_to
	--=================================================================================================================

	-- -----------------------------------------------------------------------------------------------------------------
	-- Pongo en una tabla las Sucursales que pertenecen al grupo de sucursales de la actual sucursal incluida la actual.
	-- -----------------------------------------------------------------------------------------------------------------
	DECLARE @tbBranchsOfBranchGroup TABLE(bra_id INT PRIMARY KEY CLUSTERED)
	DECLARE @intBragID AS INT
	SELECT @intBragID = tb.brag_id
		FROM tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id
	INSERT INTO @tbBranchsOfBranchGroup (bra_id) VALUES (@bra_id)
	IF @intBragID IS NOT NULL
		BEGIN
			INSERT INTO @tbBranchsOfBranchGroup
				SELECT tbgd.bra_id
					FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
					WHERE	tbgd.comp_id	= @comp_id		AND
							tbgd.brag_id	= @intBragID	AND
							tbgd.bra_id		<> @bra_id
		END
	-- -----------------------------------------------------------------------------------------------------------------



	-- ------------------------------------------------------------------------------
	-- PREPARACION DE LOS IMPUESTOS A CALCULAR
	-- ------------------------------------------------------------------------------
	--**88
	-- Pongo en una temporal que importe se esta aplicando por cada factura selsccionada
	SELECT		tctt.ctct_transaction											[ct_transaction],
				dbo.fnGetExchange(@comp_id ,
						          tctt.ctct_total,
								  @intSupplierCurrency,
								  @intBranchCurrency,
								  @intSupplierCurrency,
								  @CurrencyExchange,
								  'False')
								    /
				dbo.fnNoZDiv(	  dbo.fnGetExchange(  @comp_id,
														(SELECT tct.ct_ATotal
															FROM tbCommercialTransactions tct	WITH (NOLOCK)
				                  							WHERE	tct.comp_id			= tctt.comp_id
				                  								AND tct.ct_transaction  = tctt.ctct_transaction),
													  @intSupplierCurrency,
													  @intBranchCurrency,
													  @intSupplierCurrency,
													  @CurrencyExchange,
													  'False')
													   )							[Coef]
		INTO	#tmpDocumentsToPay
		FROM	tbCommercialTransactionsTmp tctt	WITH (NOLOCK)
		WHERE	tctt.ctct_guid = @guid AND tctt.ctct_origin = 'h'


	-- Cuanto apliqué a cuenta
	DECLARE @decOnAccountTOTAL AS DECIMAL(19,2) = 0
	DECLARE @decPayTOTAL       AS DECIMAL(19,2) = 0
	DECLARE @decBalanceCoeficient AS DECIMAL(25,10) = 0
	SELECT  @decOnAccountTOTAL		=	SUM(CASE
											WHEN tctt.ctct_origin	= 'a' THEN tctt.ctct_total			*	dbo.fnGetReciprocoIfNeed(tctt.ctct_exchange)	-- MOS 03-2023
											ELSE							   0
										END),
		    @decPayTOTAL		    =	SUM(CASE
											WHEN tctt.ctct_origin	= 'h' THEN tctt.ctct_total			*	dbo.fnGetReciprocoIfNeed(tctt.ctct_exchange)	-- MOS 03-2023
											ELSE							   0
										END)
		FROM	tbCommercialTransactionsTmp tctt	WITH (NOLOCK)
		WHERE	tctt.ctct_guid		= @guid

	SELECT @decBalanceCoeficient	= (@decPayTOTAL - @decOnAccountTOTAL) / dbo.fnNoZDiv(@decPayTOTAL)


--====
--SELECT @decBalanceCoeficient


	CREATE NONCLUSTERED INDEX #tmpDocumentsToPayIndex ON #tmpDocumentsToPay
			(
			ct_transaction
			) WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]



	-- PONER ACA la conf de CB de impuestos que permitan calcular retencion por mas que de cero el total. ! ! !
	-- Saco los totales por Concepto de Compra de las facturas aplicadas para luego calcular segun el % aplicado
	SELECT	(tit.it_qty * tit.it_price * dbo.fnGetReciprocoIfNeed(tit.it_exchangeToBranchCurrency) )	* tmp.coef	[Price],		-- MOS 03-2023: Se agrega el dbo.fnGetReciprocoIfNeed(
			 tit.puco_id																[puco_id],
			 tit.ct_transaction															[ct_transaction],
			 tit.bra_id																	[bra_id],
			 tit.it_transaction															[ID],
			 CONVERT(BIT,'False')														[onAccount]
		INTO #tmpPurchaseConceptsToPay
		FROM tbItemTransactions tit	WITH (NOLOCK)
		INNER JOIN 	#tmpDocumentsToPay tmp
			ON tmp.ct_transaction = tit.ct_transaction
		WHERE	-- Solo lo que tenga algun impuesto calculado. Si es Exento NO lleva RETENCION
				EXISTS(	SELECT TOP 1  1
		             		FROM tbTaxMovements ttm		WITH (NOLOCK)
		             		INNER JOIN tbTaxName ttn	WITH (NOLOCK)
		             			ON	ttn.tax_id	= ttm.tax_id AND
		             				ttn.comp_id = ttm.comp_id
		             		WHERE	ttm.comp_id			= tit.comp_id			AND
		             				ttm.it_transaction	= tit.it_transaction	AND
		       						(ttm.tm_total		<> 0 OR ttn.ret_doRetIfTaxZero = 'True'))
		--WHERE tit.ct_transaction IN (SELECT ct_transaction FROM #tmpDocumentsToPay)
								-- Reemplazar despues x Inner.. esto causa full scan sobte CT!!!!!
	UNION ALL
		SELECT
		   (tpcm.pcm_total * dbo.fnGetReciprocoIfNeed(tpcm.pcm_exchangeToBranchCurrency) ) * tmp.coef			[Price],			-- MOS 03-2023: Se agrega el dbo.fnGetReciprocoIfNeed(
			tpcm.puco_id															[puco_id],
			tpcm.ct_transaction														[ct_transaction],
			tct.bra_id																[bra_id],
			tpcm.pcm_id	* -1														[ID],
			 CONVERT(BIT,'False')													[onAccount]
			FROM tbPurchaseConceptMovements tpcm			WITH (NOLOCK)
			INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
				ON	TCT.comp_id			= TPCM.comp_id AND
					TCT.ct_transaction	= TPCM.ct_transaction
			INNER JOIN 	#tmpDocumentsToPay tmp
				ON tmp.ct_transaction = tpcm.ct_transaction
			WHERE 	-- Solo lo que tenga algun impuesto calculado. Si es Exento NO lleva RETENCION
					(
						TCT.ct_kindOf = 'C'
							OR
						EXISTS(	SELECT TOP 1  1
	             					FROM tbTaxMovements ttm		WITH (NOLOCK)
		             				INNER JOIN tbTaxName ttn	WITH (NOLOCK)
		             					ON	ttn.tax_id	= ttm.tax_id AND
		             						ttn.comp_id = ttm.comp_id
	             					WHERE	ttm.comp_id			= tpcm.comp_id			AND
	             							ttm.pcm_id			= tpcm.pcm_id	AND
	             							(ttm.tm_total		<> 0  OR ttn.ret_doRetIfTaxZero = 'True' ))
		            )
					--EXISTS(	SELECT 1
		   --          			FROM tbTaxMovements ttm
		   --          			WHERE	ttm.comp_id			= tpcm.comp_id			AND
		   --          					ttm.pcm_id			= tpcm.pcm_id	AND
		   --          					ttm.tm_total		<> 0)



	CREATE NONCLUSTERED INDEX #tmpPurchaseConceptsToPayIndex1 ON #tmpPurchaseConceptsToPay
			(
			ct_transaction
			) WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]

	CREATE NONCLUSTERED INDEX #tmpPurchaseConceptsToPayIndex2 ON #tmpPurchaseConceptsToPay
			(
			ID
			) WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]






	-- --------------------------------------------------------------------
	-- Agrego el Importe a cuenta que debo pagar en este pago.-
	-- --------------------------------------------------------------------

	DECLARE @decOnAccountTmp AS DECIMAL(19,6)
	SET		@decOnAccountTmp	= @onaccount
	SELECT  @decOnAccountTmp	= @decOnAccountTmp / ( 1 + (ttn.tax_percentage / 100) )
		FROM tbTaxName ttn	WITH (NOLOCK)
		WHERE	ttn.comp_id		= @comp_id AND
				ttn.tax_id		= @tax_id
	IF @decOnAccountTmp <> 0
		BEGIN
			INSERT INTO #tmpPurchaseConceptsToPay
						(price,puco_id,ID,bra_id,onAccount)
				VALUES	(@decOnAccountTmp,@puco_id,0,@bra_id,'True')
		END
	-- --------------------------------------------------------------------








	-- Pone en una nueva temporal todas las retenciones que debo calcular por este pago
	SELECT Price,
		   tpctp.puco_id,
		   TPCTP.ct_transaction,
		   ttn.tax_id,
		   ttn.tax_class,
		   TPCTP.bra_id,
		   onAccount
		INTO #tmpPurchaseConceptsToPay_Retentions
		FROM #tmpPurchaseConceptsToPay TPCTP
		INNER JOIN tbTaxName ttn	WITH (NOLOCK)
			ON ttn.comp_id = @comp_id
		INNER JOIN tbTaxNameRetentions4PurchaseConcept ttnrpc	WITH (NOLOCK)
			ON		ttnrpc.comp_id	= @comp_id
				AND ttnrpc.tax_id	= ttn.tax_id
				AND TPCTP.puco_id	= ttnrpc.puco_id
		INNER JOIN vwsysTaxClassALL_Retentions vtcar	WITH (NOLOCK)
			ON		vtcar.tax_class = ttn.tax_class
		WHERE	ttnrpc.comp_id		= @comp_id	AND
				ttnrpc.bra_id		= @bra_id	AND
				ttn.tax_disabled	= 'False'	AND -- MOS 03-2022
				ttn.ret_overPayment = 'False'		-- MOS 08-2023 x Retencion CBA



	-- MOS 18-04-2019.  Se agregaron automaticvamente en tbTaxByFiscalClass todas las RETENCIONES de compras ACTIVAS que no estaban relacionadas en el actualizador con Fecha y sin usuario.
	-- Borra las retenciones que NO estan relacionadas a la clase fiscal del Proveedor
	DELETE		#tmpPurchaseConceptsToPay_Retentions
		FROM	#tmpPurchaseConceptsToPay_Retentions			Tmp
		INNER JOIN tbSupplier ts			WITH (NOLOCK)
			ON	ts.comp_id = @comp_id			AND
				ts.supp_id = @intSupplierId
		LEFT JOIN tbTaxByFiscalClass ttbfc	WITH (NOLOCK)
			ON	ttbfc.comp_id	= ts.comp_id	AND
				ttbfc.fc_id		= ts.fc_id		AND
				(
					ttbfc.bra_id IS NULL
						OR
					ttbfc.bra_id = tmp.bra_id
				)								AND
				ttbfc.fc_PurchaseOrSale = 'True'	AND
				ttbfc.tax_id	 = tmp.tax_id
		WHERE ttbfc.comp_id IS NULL




	-- MOS 12-2022 GN. ticket 15602 - Se borran las retenciones que NO son del tipo Selected si es que el Proveedor SI es del tipo Selected
	--								- Se borran las retenciones que SI son del tipo Selected si es que el Proveedor NO es del tipo Selected
	DELETE		#tmpPurchaseConceptsToPay_Retentions
		FROM	#tmpPurchaseConceptsToPay_Retentions			Tmp
		INNER JOIN tbSupplier ts			WITH (NOLOCK)
			ON	ts.comp_id	= @comp_id			AND
				ts.supp_id	= @intSupplierId
		INNER JOIN tbTaxName AS ttn	WITH (NOLOCK)
			ON	ttn.comp_id = ts.comp_id AND
				ttn.tax_id	= tmp.tax_id
		WHERE	(
					ts.supp_applyOnlySelectedRetentions = 'True' AND
					ttn.ret_isSelectedRetention			= 'False'
				)
				OR
				(
					ts.supp_applyOnlySelectedRetentions = 'False' AND
					ttn.ret_isSelectedRetention			= 'True'
				)









	-- MOS: 07-2011
	--	Borra las retenciones a las que el proveedor no es PASIBLe de ser retenido  (De IB)
	DELETE #tmpPurchaseConceptsToPay_Retentions
		FROM #tmpPurchaseConceptsToPay_Retentions			Tmp
		inner JOIN tbTaxName								ttn		WITH (NOLOCK)
			ON		ttn.comp_id = @comp_id
				AND ttn.tax_id	= Tmp.tax_id
		INNER JOIN vwsysTaxClassIB_Retentions				vtcir	WITH (NOLOCK)
			ON vtcir.tax_class = ttn.tax_class
		WHERE NOT EXISTS(
							SELECT TOP 1  1
								FROM	vwSupplier_RetentionsAvailable			t4s		WITH (NOLOCK)
								where	t4s.comp_id		= @comp_id
									AND t4s.supp_id		= @intSupplierId
									AND t4s.tax_class	= ttn.tax_class
						)

	-- Borra las retenciones a las que el proveedor esta exento
	DELETE #tmpPurchaseConceptsToPay_Retentions
		FROM #tmpPurchaseConceptsToPay_Retentions			Tmp
		INNER JOIN tbTaxFree4Suppliers						t4s		WITH (NOLOCK)
			ON		t4s.comp_id		= @comp_id
				AND t4s.bra_id		= @bra_id
				AND t4s.supp_id		= @intSupplierId
				AND t4s.tax_id		= Tmp.tax_id


	-- Borra las retenciones exentas por la clase de comprobante que le da origen
	DELETE #tmpPurchaseConceptsToPay_Retentions
		FROM #tmpPurchaseConceptsToPay_Retentions			Tmp
		INNER JOIN tbCommercialTransactions					tct		WITH (NOLOCK)
			ON	tct.comp_id			= @comp_id			AND
				tct.ct_transaction	= Tmp.ct_transaction
		INNER JOIN tbTaxFree4Retentions4KindOf 				t4s		WITH (NOLOCK)
			ON		t4s.comp_id		= @comp_id			AND
					t4s.bra_id		= @bra_id			AND
					t4s.tax_id		= Tmp.tax_id		AND
					t4s.ct_kindOf   = tct.ct_kindOf



	-- Borra las retenciones exentas por la clase de comprobante si es un Importe a Cuenta
	DELETE #tmpPurchaseConceptsToPay_Retentions
		FROM #tmpPurchaseConceptsToPay_Retentions			Tmp
		INNER JOIN tbSupplier ts									WITH (NOLOCK)
			ON	ts.comp_id = @comp_id			AND
				ts.supp_id = @intSupplierId
		INNER JOIN tbsysFiscalClass tfc								WITH (NOLOCK)
			ON tfc.fc_id = ts.fc_id
		INNER JOIN tbTaxFree4Retentions4KindOf 				t4s		WITH (NOLOCK)
			ON		t4s.comp_id		= @comp_id			AND
					t4s.bra_id		= @bra_id			AND
					t4s.tax_id		= Tmp.tax_id		AND
					t4s.ct_kindOf   = tfc.fc_KindOf4Purchase AND
					Tmp.ct_transaction IS NULL		-- MOS 7-2017


	-- Borra Temporales No Usadas
	DROP TABLE #tmpPurchaseConceptsToPay
	DROP TABLE #tmpDocumentsToPay

	-- ------------------------------------------------------------------------------
	-- fin PREPARACION DE LOS IMPUESTOS A CALCULAR
	-- ------------------------------------------------------------------------------








	-- ------------------------------------------------------------------------------
	-- Pongo en esta temporal todas las retenciones efectuadas durante el mes a este
	-- proveedor
	-- ------------------------------------------------------------------------------
	SELECT		ttm.tax_id,
				ttm.tm_total ,
				ttm.tm_subtotal
		INTO #tmpTotalRetentionsDoneOfThisMonth
		FROM	tbTaxMovements ttm						WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
			ON		tct.comp_id			= @comp_id
				AND tct.ct_transaction	= ttm.ct_transaction

		INNER JOIN @tbBranchsOfBranchGroup tbg
			ON tbg.bra_id = tct.bra_id

		INNER JOIN tbTaxName				ttn			WITH (NOLOCK)
			ON	ttn.comp_id = ttm.comp_id	AND
				ttn.tax_id	= ttm.tax_id

		INNER JOIN vwsysTaxClassALL_Retentions vtcar	WITH (NOLOCK)
			ON vtcar.tax_class = ttn.tax_class

		INNER JOIN tbUsers4BranchFilter							vubf	WITH (NOLOCK)
		ON		vubf.comp_id			=  tct.comp_id
		AND		vubf.bra_id				=  tct.bra_id
		AND		vubf.[user_id]			=  @user_id



		WHERE
			ttm.comp_id		= @comp_id			AND
			tct.sd_id		= 106				AND
			tct.supp_id		= @intSupplierId	AND
			tct.ct_taxDate	BETWEEN @datProcessingDate_from AND @datProcessingDate_to



	-- ------------------------------------------------------------------------------
	-- Pongo en una temporal todas las retenciones que se debieron efectuar
	-- durante el mes al proveedor en cuestion, para las retenciones que tengan
	-- calculo x acumulados en el mes.- (por PurchaseConcepts y por Articulo - UNION)
	-- mas los pagos a cuenta que debian tener retencion.-
	-- ------------------------------------------------------------------------------
	DECLARE @tmpCTBySuppId TABLE (ct_transaction INT PRIMARY KEY CLUSTERED)
	INSERT INTO @tmpCTBySuppId (ct_transaction)

		SELECT tct.ct_transaction --,VWInvoices.PaymentDate
			--INTO #tmpCTBySuppId
			FROM tbCommercialTransactions tct			WITH (NOLOCK)
					--INNER JOIN tbUsers4BranchFilter	   vubf		WITH (NOLOCK)
					--	ON		vubf.comp_id			=  tct.comp_id
					--	AND		vubf.bra_id				=  tct.bra_id
					--	AND		vubf.[user_id]			=  @user_id

					INNER JOIN @tbBranchsOfBranchGroup tbg
							ON tbg.bra_id = tct.bra_id

		--			INNER JOIN vwCommercialTransactions_PayOrdersApplications2Invoices						VWInvoices
		--				ON		VWInvoices.comp_id		  = tct.comp_id
		--					and VWInvoices.ct_transaction = tct.ct_transaction
			WHERE	tct.comp_id = @comp_id AND
					tct.supp_id = @intSupplierId

		--CREATE NONCLUSTERED INDEX #tmpCTBySuppIdIndex ON #tmpCTBySuppId
		--	(
		--	ct_transaction
		--	) WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]











	-- 1ro x Conceptos de Compra
	SELECT  tct.ct_transaction												[ct_transaction],
			tpcm.puco_id													[puco_id],
			tpcm.pcm_total * tpcm.pcm_exchangeToBranchCurrency * VWInvoices.appl_coef / 100						[Total] ,
			ttn.tax_id														[tax_id],
			VWInvoices.appl_coef											[ApplCoef],
			1																[Class]
		INTO #tmpTotalRetentionsMustDoInThisMonth
		FROM tbCommercialTransactions										tct		WITH (NOLOCK)



		INNER JOIN @tmpCTBySuppId tmpbu
			ON	@comp_id             = tct.comp_id			  AND	  -- x velocidad dejar asi !
				tmpbu.ct_transaction = tct.ct_transaction

		INNER JOIN vwCommercialTransactions_PayOrdersApplications2Invoices	VWInvoices		WITH (NOLOCK)
			ON		VWInvoices.comp_id		  = tct.comp_id
				and VWInvoices.ct_transaction = tct.ct_transaction

		INNER JOIN tbPurchaseConceptMovements								tpcm			WITH (NOLOCK)
			ON	tpcm.comp_id			= tct.comp_id		AND
				tpcm.ct_transaction     = tct.ct_transaction

		INNER JOIN tbTaxNameRetentions4PurchaseConcept ttnrpc								WITH (NOLOCK)
			ON		ttnrpc.comp_id = @comp_id
				AND ttnrpc.bra_id  = @bra_id
				AND ttnrpc.puco_id = tpcm.puco_id

		INNER JOIN tbTaxName ttn															WITH (NOLOCK)
			ON		ttn.comp_id = @comp_id
				AND ttn.tax_id  = ttnrpc.tax_id
				AND (ISNULL(ttn.ret_bra_id,-1) = -1 OR ttn.ret_bra_id = @bra_id)
				AND (ISNULL(ttn.state_id,-1)   = -1 OR ttn.state_id   = @intSupplierStateId)
				AND (ISNULL(ttn.country_id,-1) = -1 OR ttn.country_id = @intSupplierCountryId)
		INNER JOIN vwsysTaxClassALL_Retentions vtcar										WITH (NOLOCK)
			ON		vtcar.tax_class = ttn.tax_class
		WHERE   VWInvoices.PaymentDate	BETWEEN @datProcessingDate_from AND @datProcessingDate_to	AND
				ttn.tax_disabled	= 'False'	AND -- MOS 03-2022
				ttn.ret_overPayment = 'False'		-- MOS 08-2023 x Retencion CBA

	UNION ALL


		-- 2do x Items
		SELECT  tct.ct_transaction																	[ct_transaction],
				tit.puco_id																			[puco_id],
				tit.it_price * tit.it_qty * tit.it_exchangeToBranchCurrency * VWInvoices.appl_coef / 100	[Total],
				ttn.tax_id																			[tax_id],
				VWInvoices.appl_coef																[ApplCoef],
				2																					[Class]

			FROM tbCommercialTransactions															tct				WITH (NOLOCK)



			INNER JOIN @tmpCTBySuppId tmpbu
				ON	@comp_id             = tct.comp_id			  AND	  -- x velocidad dejar asi !
					tmpbu.ct_transaction = tct.ct_transaction

			INNER JOIN vwCommercialTransactions_PayOrdersApplications2Invoices						VWInvoices		WITH (NOLOCK)
				ON		VWInvoices.comp_id		  = tct.comp_id			AND
						VWInvoices.ct_transaction = tct.ct_transaction

			INNER JOIN tbItemTransactions															tit				WITH (NOLOCK)
				ON		tit.comp_id			= tct.comp_id
					AND tit.bra_id			= tct.bra_id
					AND tit.ct_transaction	= tct.ct_transaction

			INNER JOIN tbTaxNameRetentions4PurchaseConcept											ttnrpc			WITH (NOLOCK)
				ON		ttnrpc.comp_id = @comp_id
					AND ttnrpc.bra_id  = @bra_id
					AND ttnrpc.puco_id = tit.puco_id

			INNER JOIN tbTaxName																	ttn				WITH (NOLOCK)
				ON		ttn.comp_id = @comp_id
					AND ttn.tax_id  = ttnrpc.tax_id
					AND (ISNULL(ttn.ret_bra_id,-1) = -1 OR ttn.ret_bra_id = @bra_id)
					AND (ISNULL(ttn.state_id,-1)   = -1 OR ttn.state_id   = @intSupplierStateId)
					AND (ISNULL(ttn.country_id,-1) = -1 OR ttn.country_id = @intSupplierCountryId)

			INNER JOIN vwsysTaxClassALL_Retentions													vtcar			WITH (NOLOCK)
				ON		vtcar.tax_class = ttn.tax_class

			WHERE   VWInvoices.PaymentDate	BETWEEN @datProcessingDate_from AND @datProcessingDate_to	AND
					ttn.tax_disabled	= 'False' AND	-- MOS 03-2022
					ttn.ret_overPayment = 'False'		-- MOS 08-2023 x Retencion CBA

	UNION ALL

		-- 3ro x Pagos a Cuenta que debieron efectuar Retencion.-
		-- MOS 02-2023: x CM, se modificó la funcion [fnGetNETOWithOutRetentionsOfGanancias4OnAccount] x si era un pago a cuenta que NO habia calculado retenciones
		SELECT  tct.ct_transaction																	[ct_transaction],
				tctpa.puco_id																		[puco_id],
				dbo.[fnGetNETOWithOutRetentionsOfGanancias4OnAccount](tct.comp_id,  tct.ct_transaction,tct.ct_ABalance / dbo.fnNoZDiv(tct.CT_ATOTAL) )	[Total],	-- MOS 09-2022, fnGetNETOWithOutRetentionsOfGanancias, se cambio para que los acumulados calculen bien la base imponible
				ttnrpc.tax_id																		[tax_id],
				tct.ct_ABalance / dbo.fnNoZDiv(tct.CT_ATOTAL) * 100  /*  MOS 09-2022 x CM100*/		[ApplCoef],
				3																					[Class]
			FROM tbCommercialTransactions															tct			WITH (NOLOCK)

			INNER JOIN @tbBranchsOfBranchGroup tbg	-- MOS 06-2016
					ON
						tct.comp_id = @comp_id AND
						tbg.bra_id	= tct.bra_id

			INNER JOIN tbCommercialTransactionsPaymentsAdditionals									tctpa		WITH (NOLOCK)
				ON		tctpa.comp_id			= tct.comp_id
					AND tctpa.bra_id			= tct.bra_id
					AND tctpa.ct_transaction	= tct.ct_transaction

			INNER JOIN tbTaxNameRetentions4PurchaseConcept											ttnrpc		WITH (NOLOCK)
				ON		ttnrpc.comp_id = TCTPA.comp_id
					AND ttnrpc.bra_id  = tctpa.bra_id
					AND ttnrpc.puco_id = tctpa.puco_id

			INNER JOIN tbTaxName																	ttn			WITH (NOLOCK)
				ON		ttn.comp_id = @comp_id
					AND ttn.tax_id  = ttnrpc.tax_id
					AND ( ttn.ret_bra_id IS NULL OR ttn.ret_bra_id = @bra_id)
					AND ( ttn.state_id   IS NULL OR ttn.state_id   = @intSupplierStateId)
					AND ( ttn.country_id IS NULL OR ttn.country_id = @intSupplierCountryId)

			INNER JOIN tbTaxName																	ttnOnAcc	WITH (NOLOCK)
				ON		ttnOnAcc.comp_id	= tctpa.comp_id
					AND ttnOnAcc.tax_id		= tctpa.tax_id

			INNER JOIN vwsysTaxClassALL_Retentions													vtcar		WITH (NOLOCK)
				ON		vtcar.tax_class = ttn.tax_class

			-- MOS 06-2016
			--INNER JOIN tbUsers4BranchFilter	   vubf																WITH (NOLOCK)
			--	ON		vubf.comp_id			=  tct.comp_id
			--	AND		vubf.bra_id				=  tct.bra_id
			--	AND		vubf.[user_id]			=  @user_id



			WHERE   tct.comp_id		   = @comp_id
				AND	tct.supp_id		   = @intSupplierId
				AND tct.sd_id		   = 106			-- Ordenes de Pago
				AND tct.ct_ABalance	   > 0				-- Con Saldo y del mes.-
				AND tct.ct_date	BETWEEN @datProcessingDate_from AND @datProcessingDate_to
				AND ttn.tax_disabled		= 'False'	-- MOS 03-2022
				AND ttn.ret_overPayment		= 'False'	-- MOS 08-2023 x Retencion CBA
				AND ttnOnAcc.tax_disabled	= 'False'	-- MOS 03-2022

	-- ------------------------------------------------------------------------------


--==
--SELECT * FROM tbTaxMovementsTmp ttmt WHERE ttmt.tmt_guid = @guid
--RETURN
--==

--SELECT * FROM #tmpTotalRetentionsMustDoInThisMonth
--	-- Toma en cuenta Comprobantes a APLICAR con este pago
--	UPDATE #tmpTotalRetentionsMustDoInThisMonth
--		SET Total = Total * @decBalanceCoeficient
--SELECT * FROM #tmpTotalRetentionsMustDoInThisMonth



	-- ------------------------------------------------------------------------------
	-- Variables para el Calculo
	-- ------------------------------------------------------------------------------
	DECLARE @decMinimumNoTaxableTotal	AS DECIMAL(19,2)
	DECLARE @decUntilTotal1				AS DECIMAL(17,2)
	DECLARE @decPercentage1				AS DECIMAL(17,2)
	DECLARE @decUntilTotal2				AS DECIMAL(17,2)
	DECLARE @decPercentage2				AS DECIMAL(17,2)
	DECLARE @decUntilTotal3				AS DECIMAL(17,2)
	DECLARE @decPercentage3				AS DECIMAL(17,2)
	DECLARE @decUntilTotal4				AS DECIMAL(17,2)
	DECLARE @decPercentage4				AS DECIMAL(17,2)
	DECLARE @decUntilTotal5				AS DECIMAL(17,2)
	DECLARE @decPercentage5				AS DECIMAL(17,2)
	DECLARE @decUntilTotal6				AS DECIMAL(17,2)
	DECLARE @decPercentage6				AS DECIMAL(17,2)
	DECLARE @decUntilTotal7				AS DECIMAL(17,2)
	DECLARE @decPercentage7				AS DECIMAL(17,2)
	DECLARE @decUntilTotal8				AS DECIMAL(17,2)
	DECLARE @decPercentage8				AS DECIMAL(17,2)
	DECLARE @decUntilTotal9				AS DECIMAL(17,2)
	DECLARE @decPercentage9				AS DECIMAL(17,2)
	DECLARE @decUntilTotal10			AS DECIMAL(17,2)
	DECLARE @decPercentage10			AS DECIMAL(17,2)
	DECLARE @decMinimumTotal			AS DECIMAL(17,2)

	DECLARE @decTotalBase2TaxDoneOfThisMonth			AS DECIMAL(19,4)
	DECLARE @decTotalBase2RetentionMustDoInThisMonth	AS DECIMAL(19,4)
	DECLARE @decCurBaseRetentionOfThisPayment			AS DECIMAL(19,4)
	DECLARE @intCurTaxId								AS INT
	DECLARE @decTotalRetention							AS DECIMAL(19,2)
	DECLARE @decTotalRetentionBase   					AS DECIMAL(19,2)
	DECLARE @decRetentionPercentaje						AS DECIMAL(19,4)
	DECLARE @intTaxClass								AS INT
	DECLARE @decTotalUntilBase							AS DECIMAL(19,4)


	DECLARE @decRetentionBaseDiscountTotal				AS DECIMAL(19,4)
	DECLARE @decRetentionBaseDiscount1					AS DECIMAL(19,4)
	DECLARE @decRetentionBaseDiscount2					AS DECIMAL(19,4)
	DECLARE @decRetentionBaseDiscount3					AS DECIMAL(19,4)
	DECLARE @decRetentionBaseDiscount4					AS DECIMAL(19,4)
	DECLARE @decRetentionBaseDiscount5					AS DECIMAL(19,4)
	DECLARE @decRetentionBaseDiscount6					AS DECIMAL(19,4)
	DECLARE @decRetentionBaseDiscount7					AS DECIMAL(19,4)
	DECLARE @decRetentionBaseDiscount8					AS DECIMAL(19,4)
	DECLARE @decRetentionBaseDiscount9					AS DECIMAL(19,4)
	DECLARE @decRetentionBaseDiscount10					AS DECIMAL(19,4)


	DECLARE @decMinimum1				AS DECIMAL(17,2)
	DECLARE @decMinimum2				AS DECIMAL(17,2)
	DECLARE @decMinimum3				AS DECIMAL(17,2)
	DECLARE @decMinimum4				AS DECIMAL(17,2)
	DECLARE @decMinimum5				AS DECIMAL(17,2)
	DECLARE @decMinimum6				AS DECIMAL(17,2)
	DECLARE @decMinimum7				AS DECIMAL(17,2)
	DECLARE @decMinimum8				AS DECIMAL(17,2)
	DECLARE @decMinimum9				AS DECIMAL(17,2)
	DECLARE @decMinimum10				AS DECIMAL(17,2)
	DECLARE @decMinimum2RetIfHasRetention
										AS DECIMAL(17,2)

--==
--SELECT * FROM #tmpPurchaseConceptsToPay_Retentions
--==


	-- ------------------------------------------------------------------------------
	-- Calculo de Retenciones de Ganancias.-
	-- ------------------------------------------------------------------------------
	-- Por cada retencion que deberia efectuar en este pago
	DECLARE  curRetencion_Ganancias CURSOR LOCAL  FAST_FORWARD FOR
		SELECT sum(TPCTPR.Price *	CASE
										WHEN onAccount = 'True' THEN 1
										ELSE @decBalanceCoeficient
									END)						[Price],
			   TPCTPR.tax_id							[tax_id]
			FROM #tmpPurchaseConceptsToPay_Retentions	TPCTPR
			INNER JOIN vwsysTaxClassGAN_Retentions		vtcgp		WITH (NOLOCK)
				ON vtcgp.tax_class = TPCTPR.tax_class
		GROUP BY TPCTPR.tax_id


	OPEN curRetencion_Ganancias

	FETCH NEXT FROM curRetencion_Ganancias
		INTO @decCurBaseRetentionOfThisPayment,
			 @intCurTaxId

	WHILE @@FETCH_STATUS = 0
		BEGIN

			-- Descuenta las mierdas A CUENTA
			SET		@decCurBaseRetentionOfThisPayment = @decCurBaseRetentionOfThisPayment --* @decBalanceCoeficient


			SELECT	@decMinimumNoTaxableTotal	= ttn.ret_mni,
					@decUntilTotal1	    		= ttn.ret_b1,
					@decPercentage1				= ttn.ret_por1,
					@decUntilTotal2				= ttn.ret_b2,
					@decPercentage2				= ttn.ret_por2,
					@decUntilTotal3				= ttn.ret_b3,
					@decPercentage3				= ttn.ret_por3,
					@decUntilTotal4				= ttn.ret_b4,
					@decPercentage4				= ttn.ret_por4,
					@decUntilTotal5				= ttn.ret_b5,
					@decPercentage5				= ttn.ret_por5,
					@decUntilTotal6				= ttn.ret_b6,
					@decPercentage6				= ttn.ret_por6,
					@decUntilTotal7				= ttn.ret_b7,
					@decPercentage7				= ttn.ret_por7,
					@decUntilTotal8				= ttn.ret_b8,
					@decPercentage8				= ttn.ret_por8,
					@decUntilTotal9				= ttn.ret_b9,
					@decPercentage9				= ttn.ret_por9,
					@decUntilTotal10			= ttn.ret_b10,
					@decPercentage10			= ttn.ret_por10,
					@decMinimumTotal			= ttn.ret_impmin,
					@decMinimum1				= ttn.ret_min1,
					@decMinimum2				= ttn.ret_min2,
					@decMinimum3				= ttn.ret_min3,
					@decMinimum4				= ttn.ret_min4,
					@decMinimum5				= ttn.ret_min5,
					@decMinimum6				= ttn.ret_min6,
					@decMinimum7				= ttn.ret_min7,
					@decMinimum8				= ttn.ret_min8,
					@decMinimum9				= ttn.ret_min9,
					@decMinimum10				= ttn.ret_min10
				FROM tbTaxName ttn		WITH (NOLOCK)
				WHERE	ttn.comp_id = @comp_id		AND
						ttn.tax_id  = @intCurTaxId


			-- -------------------------------------------------------------------------------------------------
			-- MOS 09-2022 x los FORROS de CM
			-- Si ponen una Base Imponible a cuenta, que NO tome el minimo no imponible y que lo calculen ellos.
			-- Solo si YA le calculé alguna retencion este mes...
			-- -------------------------------------------------------------------------------------------------
			IF @decMinimumNoTaxableTotal <> 0 AND @tax_id = -1
				AND 1 = 2   -- MOS 04-2023 x CM, otra vez estos FORROS , para que se comporte meramente como nueva base imponible y no haga nada mas.
				BEGIN
					DECLARE @bitHasAnyRetention AS BIT	= 'False'
					SELECT  @bitHasAnyRetention			= 'True'
						FROM #tmpTotalRetentionsDoneOfThisMonth
						WHERE tm_total > 0
					IF @bitHasAnyRetention = 'True'
						BEGIN
							SET @decMinimumNoTaxableTotal = 0
						END
				END
			-- -------------------------------------------------------------------------------------------------

			-- -------------------------------------------------------------------------------------------------
			-- Debo obtener todos los pagos a cuyenta efectuados este mes que NO esten aplicados
			-- -------------------------------------------------------------------------------------------------
			IF @decMinimumNoTaxableTotal <> 0 AND @tax_id = -1
				AND 1 = 2   -- MOS 04-2023 x CM, otra vez estos FORROS , para que se comporte meramente como nueva base imponible y no haga nada mas.
				BEGIN
					DECLARE @decOnAccountMustCalculateRetention AS DECIMAL = 0
					SELECT  @decOnAccountMustCalculateRetention =
							SUM (
								(tct.ct_ABalance / (1 + (ttn.tax_percentage / 100)))
								*
								(tct.ct_ABalance / dbo.fnNoZDiv(tct.CT_ATOTAL))  -- % del total que está A Auenta ( Sin Aplicar )
							)
						FROM tbCommercialTransactions															tct			WITH (NOLOCK)
						INNER JOIN @tbBranchsOfBranchGroup tbg	-- MOS 06-2016
								ON
									tct.comp_id = @comp_id AND
									tbg.bra_id	= tct.bra_id
						INNER JOIN tbCommercialTransactionsPaymentsAdditionals									tctpa		WITH (NOLOCK)
							ON		tctpa.comp_id			= tct.comp_id
								AND tctpa.bra_id			= tct.bra_id
								AND tctpa.ct_transaction	= tct.ct_transaction
						INNER JOIN tbTaxNameRetentions4PurchaseConcept											ttnrpc		WITH (NOLOCK)
							ON		ttnrpc.comp_id = TCTPA.comp_id
								AND ttnrpc.bra_id  = tctpa.bra_id
								AND ttnrpc.puco_id = tctpa.puco_id
						INNER JOIN tbTaxName																	ttn			WITH (NOLOCK)
							ON		ttn.comp_id = @comp_id
								AND ttn.tax_id  = tctpa.tax_id
						WHERE   tct.comp_id		   = @comp_id
							AND	tct.supp_id		   = @intSupplierId
							AND tct.sd_id		   = 106			-- Ordenes de Pago
							AND tct.ct_ABalance	   > 0				-- Con Saldo y del mes.-
							AND tct.ct_date	BETWEEN @datProcessingDate_from AND @datProcessingDate_to




					IF @decMinimumNoTaxableTotal > 	@decOnAccountMustCalculateRetention
						BEGIN
							SET @decMinimumNoTaxableTotal = @decMinimumNoTaxableTotal - @decOnAccountMustCalculateRetention
						END
					ELSE IF  @decMinimumNoTaxableTotal <= 	@decOnAccountMustCalculateRetention
						BEGIN
							SET @decMinimumNoTaxableTotal = 0
						END
				END

			-- -------------------------------------------------------------------------------------------------
			--SELECT '@decOnAccountMustCalculateRetention',@decOnAccountMustCalculateRetention
			--SELECT '#tmpTotalRetentionsMustDoInThisMonth',* FROM #tmpTotalRetentionsMustDoInThisMonth
			--SELECT '#tmpTotalRetentionsDoneOfThisMonth',* FROM #tmpTotalRetentionsDoneOfThisMonth



			-- Saco las retenciones que SI se efectuaron en el mes.
			SET			 @decTotalBase2TaxDoneOfThisMonth  = 0
			SELECT		 @decTotalBase2TaxDoneOfThisMonth  = SUM(tm_total)
				FROM	 #tmpTotalRetentionsDoneOfThisMonth
				WHERE	 tax_id = @intCurTaxId
				GROUP BY tax_id







			-- Sumo las retenciones que se debieron efectuar durante este mes
			SET			 @decTotalBase2RetentionMustDoInThisMonth  = 0
			SELECT		 @decTotalBase2RetentionMustDoInThisMonth  = SUM(total)
				FROM	 #tmpTotalRetentionsMustDoInThisMonth
				WHERE	 tax_id = @intCurTaxId
				GROUP BY tax_id



			-- Si se supera el minimo no imponible, calculo la retencion.-
			-- (@decTotalTaxDoneOfThisMonth + @decCurRetentionOfThisPayment) > @decMinimumNoTaxableTotal
			IF (@decTotalBase2RetentionMustDoInThisMonth  + @decCurBaseRetentionOfThisPayment) > @decMinimumNoTaxableTotal
				BEGIN



					Set @decTotalRetentionBase = @decTotalBase2RetentionMustDoInThisMonth	+
												 @decCurBaseRetentionOfThisPayment			-
												 @decMinimumNoTaxableTotal

--==
--SELECT @decTotalRetentionBase,@decTotalBase2RetentionMustDoInThisMonth,@decCurBaseRetentionOfThisPayment,@decMinimumNoTaxableTotal
--==
					-- ----------------------------------
					-- Calculo las Bases para Sumar Luego
					-- 06-2018, MOS : agregué las 8,9,10
					-- ----------------------------------
					SET @decRetentionBaseDiscount1 = 0
					SET @decRetentionBaseDiscount2 = (@decUntilTotal1 * @decPercentage1 / 100)
					SET @decRetentionBaseDiscount3 = ((@decUntilTotal2 - @decUntilTotal1)
																	 * @decPercentage2 / 100)
													 +	@decRetentionBaseDiscount2
					SET @decRetentionBaseDiscount4 = ((@decUntilTotal3 - @decUntilTotal2)
																	 * @decPercentage3 / 100)
													 +	@decRetentionBaseDiscount3
					SET @decRetentionBaseDiscount5 = ((@decUntilTotal4 - @decUntilTotal3)
																	 * @decPercentage4 / 100)
													 +	@decRetentionBaseDiscount4
					SET @decRetentionBaseDiscount6 = ((@decUntilTotal5 - @decUntilTotal4)
																	 * @decPercentage5 / 100)
													 +	@decRetentionBaseDiscount5
					SET @decRetentionBaseDiscount7 = ((@decUntilTotal6 - @decUntilTotal5)
																	 * @decPercentage6 / 100)
													 +	@decRetentionBaseDiscount6
					SET @decRetentionBaseDiscount8 = ((@decUntilTotal7 - @decUntilTotal6)
																	 * @decPercentage7 / 100)
													 +	@decRetentionBaseDiscount7
					SET @decRetentionBaseDiscount9 = ((@decUntilTotal8 - @decUntilTotal7)
																	 * @decPercentage8 / 100)
													 +	@decRetentionBaseDiscount8
					SET @decRetentionBaseDiscount10 = ((@decUntilTotal9 - @decUntilTotal8)
																	 * @decPercentage9 / 100)
													 +	@decRetentionBaseDiscount9
					-- ------

					SET @decRetentionBaseDiscountTotal = CASE
															WHEN @decTotalRetentionBase <= @decUntilTotal1 THEN @decRetentionBaseDiscount1
															WHEN @decTotalRetentionBase <= @decUntilTotal2 THEN @decRetentionBaseDiscount2
															WHEN @decTotalRetentionBase <= @decUntilTotal3 THEN @decRetentionBaseDiscount3
															WHEN @decTotalRetentionBase <= @decUntilTotal4 THEN @decRetentionBaseDiscount4
															WHEN @decTotalRetentionBase <= @decUntilTotal5 THEN @decRetentionBaseDiscount5
															WHEN @decTotalRetentionBase <= @decUntilTotal6 THEN @decRetentionBaseDiscount6
															WHEN @decTotalRetentionBase <= @decUntilTotal7 THEN @decRetentionBaseDiscount7
															WHEN @decTotalRetentionBase <= @decUntilTotal8 THEN @decRetentionBaseDiscount8
															WHEN @decTotalRetentionBase <= @decUntilTotal9 THEN @decRetentionBaseDiscount9
															ELSE												@decRetentionBaseDiscount10
														 END

					-- ----------------------------------

					SET @decRetentionPercentaje= CASE
														WHEN @decTotalRetentionBase <= @decUntilTotal1 THEN @decPercentage1
														WHEN @decTotalRetentionBase <= @decUntilTotal2 THEN @decPercentage2
														WHEN @decTotalRetentionBase <= @decUntilTotal3 THEN @decPercentage3
														WHEN @decTotalRetentionBase <= @decUntilTotal4 THEN @decPercentage4
														WHEN @decTotalRetentionBase <= @decUntilTotal5 THEN @decPercentage5
														WHEN @decTotalRetentionBase <= @decUntilTotal6 THEN @decPercentage6
														WHEN @decTotalRetentionBase <= @decUntilTotal7 THEN @decPercentage7
														WHEN @decTotalRetentionBase <= @decUntilTotal8 THEN @decPercentage8
														WHEN @decTotalRetentionBase <= @decUntilTotal9 THEN @decPercentage9
														ELSE												@decPercentage10
					                             END


					SET @decTotalUntilBase = CASE
														WHEN @decTotalRetentionBase <= @decUntilTotal1 THEN 0
														WHEN @decTotalRetentionBase <= @decUntilTotal2 THEN @decUntilTotal1
														WHEN @decTotalRetentionBase <= @decUntilTotal3 THEN @decUntilTotal2
														WHEN @decTotalRetentionBase <= @decUntilTotal4 THEN @decUntilTotal3
														WHEN @decTotalRetentionBase <= @decUntilTotal5 THEN @decUntilTotal4
														WHEN @decTotalRetentionBase <= @decUntilTotal6 THEN @decUntilTotal5
														WHEN @decTotalRetentionBase <= @decUntilTotal7 THEN @decUntilTotal6
														WHEN @decTotalRetentionBase <= @decUntilTotal8 THEN @decUntilTotal7
														WHEN @decTotalRetentionBase <= @decUntilTotal9 THEN @decUntilTotal8
														ELSE												@decUntilTotal9
					                             END


					SET @decMinimum2RetIfHasRetention =
												CASE
														WHEN @decTotalRetentionBase <= @decUntilTotal1 THEN @decMinimum1
														WHEN @decTotalRetentionBase <= @decUntilTotal2 THEN @decMinimum2
														WHEN @decTotalRetentionBase <= @decUntilTotal3 THEN @decMinimum3
														WHEN @decTotalRetentionBase <= @decUntilTotal4 THEN @decMinimum4
														WHEN @decTotalRetentionBase <= @decUntilTotal5 THEN @decMinimum5
														WHEN @decTotalRetentionBase <= @decUntilTotal6 THEN @decMinimum6
														WHEN @decTotalRetentionBase <= @decUntilTotal7 THEN @decMinimum7
														WHEN @decTotalRetentionBase <= @decUntilTotal8 THEN @decMinimum8
														WHEN @decTotalRetentionBase <= @decUntilTotal9 THEN @decMinimum9
														ELSE												@decMinimum10
					                             END





					-- Lo que debo retener es el % del total correspondiente a la tabla mas el acumulado de
					-- cada renglon de la tabla.- (@decRetentionBaseDiscountTotal) y descontarle el importe
					-- de retenciones ya efectuado durante el mes en curso
					SET @decTotalRetention = ( (   (@decTotalRetentionBase - @decTotalUntilBase ) * @decRetentionPercentaje / 100 )
												+ @decRetentionBaseDiscountTotal )
											    - @decTotalBase2TaxDoneOfThisMonth

					--  MOS 02-10 @decMinimumTotal
					IF @decTotalRetention < @decMinimumTotal
						BEGIN
							SET @decTotalRetention = 0
						END

					-- MOS 06-2018
					IF	@decMinimum2RetIfHasRetention	> 0					AND
						@decTotalRetention				< @decMinimum2RetIfHasRetention	AND
						@decTotalRetention				<> 0
						BEGIN
							SET @decTotalRetention = @decMinimum2RetIfHasRetention
						END


					INSERT INTO tbTaxMovementsTmp
					(
						comp_id,
						bra_id,
						tmt_guid,
						tax_id,
						tmt_subtotal,
						percentaje,
						tmt_total,
						curr_id,
						isCalculated,
						puco_id,
						tmT_exchangeToBranchCurrency
					)
					VALUES
					(
						@comp_id,
						@bra_id,
						@guid,
						@intCurTaxId,
						@decTotalRetentionBase,
						@decRetentionPercentaje,
						@decTotalRetention,
						@intBranchCurrency,
						'true',
						@intSupplierPuco_id,				-- Puede haber un error aca.!! OJO.!!
						@CurrencyExchange)


				END

			FETCH NEXT FROM curRetencion_Ganancias
				INTO @decCurBaseRetentionOfThisPayment ,
					 @intCurTaxId

		END

	CLOSE curRetencion_Ganancias
	DEALLOCATE curRetencion_Ganancias



	-- ------------------------------------------------------------------------------
	-- Calculo de Retenciones de IVA
	-- ------------------------------------------------------------------------------
	-- Por cada retencion que deberia efectuar en este pago
	DECLARE  curRetencion_IVA CURSOR LOCAL FAST_FORWARD FOR
		SELECT sum(TPCTPR.Price *	CASE
										WHEN onAccount = 'True' THEN 1
										ELSE @decBalanceCoeficient
									END)						[Price],
			   TPCTPR.tax_id							[tax_id]
			FROM #tmpPurchaseConceptsToPay_Retentions	TPCTPR
			INNER JOIN vwsysTaxClassIVA_Retentions   	vtcgp	WITH (NOLOCK)
				ON vtcgp.tax_class = TPCTPR.tax_class
		GROUP BY TPCTPR.tax_id


	OPEN curRetencion_IVA

	FETCH NEXT FROM curRetencion_IVA
		INTO @decCurBaseRetentionOfThisPayment,
			 @intCurTaxId

	WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @decCurBaseRetentionOfThisPayment = @decCurBaseRetentionOfThisPayment --* @decBalanceCoeficient

			SELECT	@decMinimumNoTaxableTotal	= ttn.ret_mni,
					@decUntilTotal1	    		= ttn.ret_b1,
					@decPercentage1				= ttn.ret_por1,
					@decUntilTotal2				= ttn.ret_b2,
					@decPercentage2				= ttn.ret_por2,
					@decUntilTotal3				= ttn.ret_b3,
					@decPercentage3				= ttn.ret_por3,
					@decUntilTotal4				= ttn.ret_b4,
					@decPercentage4				= ttn.ret_por4,
					@decUntilTotal5				= ttn.ret_b5,
					@decPercentage5				= ttn.ret_por5,
					@decUntilTotal6				= ttn.ret_b6,
					@decPercentage6				= ttn.ret_por6,
					@decUntilTotal7				= ttn.ret_b7,
					@decPercentage7				= ttn.ret_por7,
					@decMinimumTotal			= ttn.ret_impmin
				FROM tbTaxName ttn			WITH (NOLOCK)
				WHERE	ttn.comp_id = @comp_id
					AND ttn.tax_id  = @intCurTaxId


					Set @decTotalRetentionBase = @decCurBaseRetentionOfThisPayment

					SET @decRetentionPercentaje= CASE
														WHEN @decTotalRetentionBase <= @decUntilTotal1 THEN @decPercentage1
														WHEN @decTotalRetentionBase <= @decUntilTotal2 THEN @decPercentage2
														WHEN @decTotalRetentionBase <= @decUntilTotal3 THEN @decPercentage3
														WHEN @decTotalRetentionBase <= @decUntilTotal4 THEN @decPercentage4
														WHEN @decTotalRetentionBase <= @decUntilTotal5 THEN @decPercentage5
														WHEN @decTotalRetentionBase <= @decUntilTotal6 THEN @decPercentage6
														ELSE												@decPercentage7
					                             END

					SET @decTotalRetention = @decTotalRetentionBase * @decRetentionPercentaje / 100
					IF @decTotalRetention < @decMinimumTotal SET @decTotalRetention =  0  --  MOS 02-10 @decMinimumTotal


					INSERT INTO tbTaxMovementsTmp
					(
						comp_id,
						bra_id,
						tmt_guid,
						tax_id,
						tmt_subtotal,
						percentaje,
						tmt_total,
						curr_id,
						isCalculated,
						puco_id,
						tmT_exchangeToBranchCurrency
					)
					VALUES
					(
						@comp_id,
						@bra_id,
						@guid,
						@intCurTaxId,
						@decTotalRetentionBase,
						@decRetentionPercentaje,
						@decTotalRetention,
						@intBranchCurrency,
						'true',
						@intSupplierPuco_id,				-- Puede haber un error aca.!! OJO.!!
						@CurrencyExchange)




			FETCH NEXT FROM curRetencion_IVA
				INTO @decCurBaseRetentionOfThisPayment ,
					 @intCurTaxId

		END

	CLOSE curRetencion_IVA
	DEALLOCATE curRetencion_IVA


	-- ------------------------------------------------------------------------------
	-- Calculo de Retenciones de Ingresos Brutos
	-- ------------------------------------------------------------------------------
	-- Por cada retencion que deberia efectuar en este pago
	DECLARE  curRetencion_IB CURSOR LOCAL  FAST_FORWARD FOR
		SELECT sum(TPCTPR.Price *	CASE
										WHEN onAccount = 'True' THEN 1
										ELSE @decBalanceCoeficient
									END)						[Price],
			   TPCTPR.tax_id							[tax_id]
			FROM #tmpPurchaseConceptsToPay_Retentions	TPCTPR
			INNER JOIN vwsysTaxClassIB_Retentions   	vtcgp			WITH (NOLOCK)
				ON vtcgp.tax_class = TPCTPR.tax_class
		GROUP BY TPCTPR.tax_id


	OPEN curRetencion_IB

	FETCH NEXT FROM curRetencion_IB
		INTO @decCurBaseRetentionOfThisPayment,
			 @intCurTaxId

	WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @decCurBaseRetentionOfThisPayment = @decCurBaseRetentionOfThisPayment --* @decBalanceCoeficient

			SELECT	@decMinimumNoTaxableTotal	= ttn.ret_mni,
					@decUntilTotal1	    		= ttn.ret_b1,
					@decPercentage1				= ttn.ret_por1,
					@decUntilTotal2				= ttn.ret_b2,
					@decPercentage2				= ttn.ret_por2,
					@decUntilTotal3				= ttn.ret_b3,
					@decPercentage3				= ttn.ret_por3,
					@decUntilTotal4				= ttn.ret_b4,
					@decPercentage4				= ttn.ret_por4,
					@decUntilTotal5				= ttn.ret_b5,
					@decPercentage5				= ttn.ret_por5,
					@decUntilTotal6				= ttn.ret_b6,
					@decPercentage6				= ttn.ret_por6,
					@decUntilTotal7				= ttn.ret_b7,
					@decPercentage7				= ttn.ret_por7,
					@decMinimumTotal			= ttn.ret_impmin,
					@intTaxClass				= ttn.tax_class
				FROM tbTaxName ttn				WITH (NOLOCK)
				WHERE	ttn.comp_id = @comp_id
					AND ttn.tax_id  = @intCurTaxId

					Set @decTotalRetentionBase = @decCurBaseRetentionOfThisPayment

					IF @decTotalRetentionBase < @decMinimumNoTaxableTotal
						BEGIN
							SET @decTotalRetentionBase = 0
						END


					SET @strSupplierCUIT = RTRIM(@strSupplierCUIT)
					--	------------------------------------------
					--	Calcula Porcentaje de Retencion
					--	segun la jurisdiccion.
					--	------------------------------------------
					IF @intTaxClass = 202	-- ARBA
						BEGIN
							SET @decRetentionPercentaje    = null
							select @decRetentionPercentaje = CONVERT(decimal(19, 6), replace(tta.arba_retencion,',','.'))
								FROM tbsysTaxARBA tta			WITH (NOLOCK)
							WHERE tta.arba_cuit = @strSupplierCUIT
							-- Si no se encontro en el padron, pone el % x defecto del impuesto.-
							IF ISNULL(@decRetentionPercentaje,-1) = -1
								BEGIN
									SELECT @decRetentionPercentaje = ttn.ret_Percentaje_ArgBsAs_NotInPadron
										FROM tbTaxName ttn		WITH (NOLOCK)
										WHERE	ttn.comp_id = @comp_id
											AND ttn.tax_id  = @intCurTaxId
								END
							--SELECT 'ARBA'
							--SELECT @decRetentionPercentaje
						END

					ELSE IF @intTaxClass = 210	-- JUJUY
						BEGIN
							SET @decRetentionPercentaje    = null
							select @decRetentionPercentaje = CONVERT(decimal(19, 6), replace(tta.retencion,',','.'))
								FROM tbsysTaxJUJUY tta			WITH (NOLOCK)
							WHERE tta.cuit = @strSupplierCUIT
							-- Si no se encontro en el padron, pone el % x defecto del impuesto.-
							IF ISNULL(@decRetentionPercentaje,-1) = -1
								BEGIN
									SELECT @decRetentionPercentaje = ttn.ret_Percentaje_ArgBsAs_NotInPadron
										FROM tbTaxName ttn		WITH (NOLOCK)
										WHERE	ttn.comp_id = @comp_id
											AND ttn.tax_id  = @intCurTaxId
								END
						END

					ELSE IF @intTaxClass = 224	-- Tucuman
						BEGIN
							DECLARE @intState AS INT = -1
							DECLARE @TUCUMANGeneral_Exento			AS BIT				= 'False'
							DECLARE @TUCUMANGeneral_Tipo			AS NCHAR(10)		= ' '
							DECLARE @TUCUMANGeneral_Porcentaje		AS DECIMAL(19,6)	= NULL
							DECLARE @TUCUMANCoeficiente_Porcentaje  AS DECIMAL(19,6)	= NULL
							DECLARE @TUCUMANCoeficiente_Coeficiente AS DECIMAL(19,6)	= NULL
							--SET		@TUCUMANPercepcion = NULL -- NO es CERO, OJO, sino abajo calcula siempre hasta cuando no corresponde
							SELECT	@TUCUMANCoeficiente_Coeficiente = ttt.tucuman_coeficiente,
									@TUCUMANCoeficiente_Porcentaje  = ttt.tucuman_porcentaje
								FROM tbsysTaxTUCUMAN ttt	WITH (NOLOCK)
								WHERE ttt.afip_cuit = @strSupplierCUIT

							SELECT	@TUCUMANGeneral_Porcentaje	= ttt.tuge_porcentaje,
									@TUCUMANGeneral_Exento		= ttt.tuge_isExento,
	      							@TUCUMANGeneral_Tipo		= ttt.tuge_Tipo
								FROM tbsysTaxTUCUMAN_General AS  ttt	WITH (NOLOCK)
								WHERE ttt.cuit = @strSupplierCUIT


							SELECT @intState = ts.state_id
								FROM tbSupplier AS ts	WITH (NOLOCK)
								WHERE	ts.comp_id = @comp_id AND
										ts.supp_id = @intSupplierId

							SET @decRetentionPercentaje    = NULL

							SET @decRetentionPercentaje    = CASE -- Hay DOS Padrones,
									                  	     			-- Padrón GENERAL      (ACREDITAN.TXT        -> @TUCUMANGeneral_) que indica los datos básicos de los contribuyentes a Percibir
									                  	     			-- Padrón COEFICIENTES (archivocoefrg116.TXT -> @TUCUMANCoeficiente_) para CM que NO son de Tucumán.
									                  	     			-- El Tipo de Contribuyente lo sacamos del PADRÓN y NO del sistema.
									                  	     			-- tc.state_id =  54003 significa que el cliente ES de Tucuman según el Archivo de Clientes
									                  	     			-- Si Es:
																		-- Exento
																	WHEN @TUCUMANGeneral_Exento = 'True'								THEN 0
																		-- C.Local de TUCUMAN	     incluido en el Padrón General
																	WHEN @TUCUMANGeneral_Tipo	= 'CL'	AND @intState =  54003		THEN @TUCUMANGeneral_Porcentaje
																		-- C.Local de Otra Provincia incluido en el Padrón General (Por si se diera el caso...)
																	WHEN @TUCUMANGeneral_Tipo	= 'CL'	AND @intState <> 54003		THEN @TUCUMANGeneral_Porcentaje
																	-- CM de TUCUMAN
																	WHEN @TUCUMANGeneral_Tipo	= 'CM'	AND @intState =  54003		THEN @TUCUMANGeneral_Porcentaje / 2
																	-- CM de Otra Provincia
																	WHEN @TUCUMANGeneral_Tipo	= 'CM'	AND @intState <> 54003		THEN	CASE
																																					WHEN @TUCUMANCoeficiente_Coeficiente = 0 THEN	@TUCUMANCoeficiente_Porcentaje
																																					ELSE											@TUCUMANCoeficiente_Coeficiente * @TUCUMANCoeficiente_Porcentaje / 2
																																				END

																	ELSE																	 0

									                  	     	END
							SET @decRetentionPercentaje = ROUND(@decRetentionPercentaje,3)	-- MOS 20-09-2021  x contador de Nucleo, Hay que redondear a 3 decimales ya que luego el aplicativo solo soporta 3 decimales

						END


					ELSE IF @intTaxClass = 201	-- AGIP MOS: 07-2011
						BEGIN
							SET @decRetentionPercentaje    = null
							select @decRetentionPercentaje = CONVERT(decimal(19, 6), replace(tta.agip_retencion,',','.'))
								FROM tbsysTaxAGIP tta		WITH (NOLOCK)
							WHERE tta.agip_cuit = @strSupplierCUIT
							-- Si no se encontro en el padron, pone el % x defecto del impuesto.-
							IF ISNULL(@decRetentionPercentaje,-1) = -1
								BEGIN
									SET @decRetentionPercentaje= CASE
																	WHEN @decTotalRetentionBase <= @decUntilTotal1 THEN @decPercentage1
																	WHEN @decTotalRetentionBase <= @decUntilTotal2 THEN @decPercentage2
																	WHEN @decTotalRetentionBase <= @decUntilTotal3 THEN @decPercentage3
																	WHEN @decTotalRetentionBase <= @decUntilTotal4 THEN @decPercentage4
																	WHEN @decTotalRetentionBase <= @decUntilTotal5 THEN @decPercentage5
																	WHEN @decTotalRetentionBase <= @decUntilTotal6 THEN @decPercentage6
																	ELSE												@decPercentage7
																 END

								END
						END
					ELSE
						BEGIN
							SET @decRetentionPercentaje= CASE
															WHEN @decTotalRetentionBase <= @decUntilTotal1 THEN @decPercentage1
															WHEN @decTotalRetentionBase <= @decUntilTotal2 THEN @decPercentage2
															WHEN @decTotalRetentionBase <= @decUntilTotal3 THEN @decPercentage3
															WHEN @decTotalRetentionBase <= @decUntilTotal4 THEN @decPercentage4
															WHEN @decTotalRetentionBase <= @decUntilTotal5 THEN @decPercentage5
															WHEN @decTotalRetentionBase <= @decUntilTotal6 THEN @decPercentage6
															ELSE												@decPercentage7
														 END
						END
					--	------------------------------------------

					SET @decTotalRetention = @decTotalRetentionBase * @decRetentionPercentaje / 100
					IF @decTotalRetention < @decMinimumTotal SET @decTotalRetention =  0  --  MOS 02-10 @decMinimumTotal


					INSERT INTO tbTaxMovementsTmp	WITH (ROWLOCK)
					(
						comp_id,
						bra_id,
						tmt_guid,
						tax_id,
						tmt_subtotal,
						percentaje,
						tmt_total,
						curr_id,
						isCalculated,
						puco_id,
						tmT_exchangeToBranchCurrency
					)
					VALUES
					(
						@comp_id,
						@bra_id,
						@guid,
						@intCurTaxId,
						@decTotalRetentionBase,
						@decRetentionPercentaje,
						@decTotalRetention,
						@intBranchCurrency,
						'true',
						@intSupplierPuco_id,				-- Puede haber un error aca.!! OJO.!!
						@CurrencyExchange)




			FETCH NEXT FROM curRetencion_IB
				INTO @decCurBaseRetentionOfThisPayment ,
					 @intCurTaxId

		END

	CLOSE curRetencion_IB
	DEALLOCATE curRetencion_IB


	DELETE FROM tbTaxMovementsTmp	WITH (ROWLOCK)
		WHERE tmt_guid = @guid AND tmt_total = 0

	-- Drop temporary Tables ----------------------------
	DROP TABLE #tmpPurchaseConceptsToPay_Retentions
	DROP TABLE #tmpTotalRetentionsDoneOfThisMonth
	DROP TABLE #tmpTotalRetentionsMustDoInThisMonth
	-- --------------------------------------------------






	-- --------------------------------------------------
	-- MOS 08-2023: Retenciones por VALORES del Recibo
	-- POr ejemplo se usa para los HDRMP de Cordoba
	-- que retienen sobre el TOTAL PAGADO
	-- --------------------------------------------------
	-- Referencia de los FORROS y CHORROS de cba: www.rentascordoba.gob.ar/ImpuestosFront/lua/agentes
	-- Busco la base imponible en base al TOTAL DE VALORES llevados a la moneda de la sucursal

	-- Calculo el TOTAL de los valores pagos x si es un pago a cuenta
	DECLARE @decPayedAmount AS DECIMAL(19,2)
	SELECT  @decPayedAmount =	SUM(
									dbo.fnGetExchange(@comp_id ,
													  vct.amount,
													  vct.curr_id,
													  @intBranchCurrency,
													  @intSupplierCurrency,
													  @CurrencyExchange,
													  'False')
									)
		--SUM(vct.amount)
		FROM vwCollectionTmp			AS vct	WITH (NOLOCK)
		WHERE	vct.lang_id = 2		AND
				vct.guid	= @guid

	-- MOS 09-2023: Calculo el TOTAL de los comprobantes pagos
	DECLARE @decTotal2Pay AS DECIMAL(19,2) = 0
	SELECT  @decTotal2Pay = SUM(ctct_total)
		FROM tbCommercialTransactionsTmp tmp WITH (NOLOCK)
		WHERE	tmp.comp_id		= @comp_id AND
				tmp.ctct_guid	= @guid
	-- Si se pagan comprobantes, retengo sobre los comprobantes pagados y NO sob re importes ya que sino nunca voy a poder cerrar el pago.
	IF @decTotal2Pay <> 0
		BEGIN
			SET @decPayedAmount = @decTotal2Pay
		END


	-- Obtengo los impuestos de este tipo: ttn.ret_overPayment = 'True'
	-- Si la RETENCIOn es de CORDOBA y está en el padron, debo tomar la alicuota informada en el padron.
	SELECT	ttn.tax_id,
			CASE
				WHEN ttn.tax_class = 206 THEN	ISNULL(cor.alicuota,ttn.tax_percentage)		-- Retención Ingresos Brutos Cordoba
				ELSE							ttn.tax_percentage
			END																		[tax_percentage],
			(@decPayedAmount * ISNULL(ttn.ret_overPaymentPercentage,0) / 100)		[decBaseImponible]
		INTO #tmpPayedAmount
		FROM tbTaxName								AS ttn		WITH (NOLOCK)
		INNER JOIN vwsysTaxClassIB_Retentions		AS vtcir	WITH (NOLOCK)
			ON vtcir.tax_class = ttn.tax_class
		INNER JOIN vwSupplier_RetentionsAvailable	AS sr		WITH (NOLOCK)
			ON	sr.comp_id		= ttn.comp_id		AND
				sr.supp_id		= @intSupplierId	AND
				sr.tax_class	= ttn.tax_class
		LEFT JOIN tbsysTaxCORDOBA_Retenciones		AS cor		WITH (NOLOCK)
			ON cor.cuit = @strSupplierCUIT
		WHERE	ttn.comp_id = @comp_id					AND
				ttn.tax_disabled = 'False'				AND
				ttn.ret_overPayment = 'True'			AND
				ttn.ret_overPaymentPercentage > 0






	IF @@ROWCOUNT > 0
		BEGIN
			INSERT INTO tbTaxMovementsTmp	WITH (ROWLOCK)
			(
				comp_id,
				bra_id,
				tmt_guid,
				tax_id,
				tmt_subtotal,
				percentaje,
				tmt_total,
				curr_id,
				isCalculated,
				puco_id,
				tmT_exchangeToBranchCurrency
			)
				SELECT
						@comp_id,
						@bra_id,
						@guid,
						tmp.tax_id,
						tmp.decBaseImponible,
						tmp.tax_percentage,
						tmp.decBaseImponible * tmp.tax_percentage / 100,
						@intBranchCurrency,
						'true',
						NULL,				-- Puede haber un error aca.!! OJO.!!
						@CurrencyExchange
					FROM #tmpPayedAmount tmp
		END
	DROP TABLE #tmpPayedAmount
	-- --------------------------------------------------












	-- MOS 09-2017
	-- Borra a los excluidos de hacer retenciones de Ganancias por Padron
	DELETE tbTaxMovementsTmp
		FROM tbTaxMovementsTmp					tmp			WITH (NOLOCK)
		INNER JOIN tbTaxName					ttn			WITH (NOLOCK)
			ON	ttn.comp_id		= tmp.comp_id AND
				ttn.tax_id		= tmp.tax_id
		INNER JOIN vwsysTaxClassGAN_Retentions	vtcgr		WITH (NOLOCK)
			ON	vtcgr.tax_class = ttn.tax_class
		INNER JOIN tbsysTaxGANANCIAS			excg		WITH (NOLOCK)
			ON	excg.stge_cuit	= @strSupplierCUIT
		INNER JOIN tbBranch						tb			WITH (NOLOCK)
			ON	tb.comp_id		= tmp.comp_id AND
				tb.bra_id		= tmp.bra_id
		--WHERE tb.bra_processingDate BETWEEN CONVERT(DATE,excg.stge_fromDate,103)  AND CONVERT(DATE,excg.stge_toDate	,103)
		-- 11/03/2019 Para ciertos cuit desde afip graba caracteres raros entonces se agrego convert varchar 10
		WHERE tb.bra_processingDate BETWEEN CONVERT(DATE,convert(Varchar(10),excg.stge_fromDate),103)  AND CONVERT(DATE,convert(Varchar(10),excg.stge_toDate),103)


END


SELECT *
	FROM tbTaxMovementsTmp ttmt		WITH (NOLOCK)
	WHERE ttmt.tmt_guid = @guid
GO



CREATE PROCEDURE spPaymentsAvailability_getCombo
(
	@comp_id	INT
)
AS
	SET NOCOUNT ON
		BEGIN
			SELECT
				tpa.pap_id								[Id],
				tpa.pap_desc							[Desc]
			FROM tbPaymentsAvailability					tpa
			WHERE	tpa.comp_id							= @comp_id	AND
					ISNULL(tpa.pap_isClosed,'False')	= 'False'
		END
GO




CREATE PROCEDURE [dbo].[spPaymentsAvailability_GetDataByFilters4Grid]
(
	@comp_id	INT,
	@pap_id		INT
)
AS

	--***************************************************************************
	/*
		SI SE MODIFICA ALGÚN SELECT DE ESTE STORED PROCEDURE O CUALQUIER SUM,
		HAY QUE MODIFICAR TAMBIEN EN LOS STORED PROCEDURE
		spPaymentsAvailability_GetDataByFilters4GridTotalsView
		spPaymentsAvailability_GetTotals
		spPaymentsAvailability_GetDataByFilters4GridAnalyticalReport
	*/
	--***************************************************************************

	SET NOCOUNT	ON
		BEGIN


			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
			-- -----------------------------------------------------------------------------

			SET DATEFORMAT 'YMD'


			-- -----------------------------------
			-- Testing
			-- -----------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@pap_id		INT

				SELECT
					@comp_id	= 1,
					@pap_id		= 75
			*/
			-- -----------------------------------



			-- Por las dudas recalcula el porcentaje de recepcion de las ordenes de compra
			EXEC spPurchaseOrderDetail_calculatePendingCoeficient @comp_id

			DECLARE
				@lang_id	INT

			SELECT
				@lang_id = tc.lang_id
			FROM tbCompany tc	WITH (NOLOCK)
			WHERE tc.comp_id = @comp_id




			--ENSAMBLAMOS LAS FECHAS PARA INICIO Y FIN DE MES
			DECLARE
				@datefrom	DATETIME,
				@dateto		DATETIME

			SELECT
				@datefrom	= dbo.fnGetEnd_or_BeginOfDate(tpa.pap_fromDate,		'False'),
				@dateto		= dbo.fnGetEnd_or_BeginOfDate(tpa.pap_toDate,		'True')

			FROM tbPaymentsAvailability		tpa	WITH (NOLOCK)
			WHERE	tpa.comp_id = @comp_id	AND
					tpa.pap_id	= @pap_id


			DECLARE	@intDays		INT
			SELECT	@intDays =  DATEPART(DAY, DATEADD(s,-1,DATEADD(mm, DATEDIFF(m,0,@datefrom)+1,0)))



				-- -------------------------------------------------------------------
				-- CREAMOS LA TABLA EN DONDE SE VAN A GUARDAR LOS DATOS
				-- AL INICIO SOLO CARGAMOS LOS CAMPOS QUE POR DEFECTO SABEMOS
				-- QUE VAMOS A TENER
				-- -------------------------------------------------------------------
					CREATE TABLE #tmpPurchaseAvailability
					(
						Button INT	DEFAULT 0
					)
				-- -------------------------------------------------------------------

				-- -------------------------------------------------------------------
				-- TABLA DONDE SE GUARDA EL ID CON EL CAMPO EN 0 PARA SER ACTUALIZADO
				-- -------------------------------------------------------------------
					CREATE TABLE #tmpPurchaseAvailability_ID
					(
						ID	INT
					)
				-- -------------------------------------------------------------------

			DECLARE
				@intDayCounter	INT
			SET @intDayCounter = 1
			--MODIFICAMOS LA TABLA PRINCIPAL QUE CREAMOS
			--LE AGREGAMOS LA CANTIDAD DE COLUMNAS EQUIVALENTES A LA CANTIDAD DE DIAS QUE TENGA EL MES

			WHILE @intDayCounter <= @intDays
				BEGIN
					DECLARE @TableMod	VARCHAR(500)
					SET @TableMod = 'ALTER TABLE #tmpPurchaseAvailability ADD ['+'d' + CAST(@intDayCounter AS NVARCHAR(100)) +   '] NVARCHAR(100) DEFAULT ''0'''
					EXEC (@TableMod)
					SET @intDayCounter = @intDayCounter + 1
				END
			--LE AGREGAMOS UN CAMPO ID (IDENTITY) AL FINAL PARA OPERAR CON MAYOR COMODIDAD DENTRO DEL CURSOR
			DECLARE @TableMod2 as VARCHAR(500)
			SET @TableMod2 = 'ALTER TABLE #tmpPurchaseAvailability ADD [ID] INT NOT NULL IDENTITY (1, 1)'
			EXEC (@TableMod2)

--			SELECT
--				@datefrom	= CONVERT(DATETIME, CONVERT(VARCHAR(10),@year) + '-' + CONVERT(VARCHAR(10),@month) + '-' + CONVERT(VARCHAR(10),1)),
--				@dateto		= CONVERT(DATETIME, CONVERT(VARCHAR(10),@year) + '-' + CONVERT(VARCHAR(10),@month) + '-' + CONVERT(VARCHAR(10),@intDays))

			-- -------------------------------------------
			-- VARIABLES DE TRABAJO
			-- -------------------------------------------
				DECLARE
					@day	INT,
					@data	VARCHAR(200),
					@sd_id	INT,
					@ID		INT
			-- -------------------------------------------

				--FACTURAS
				--******************************************************************************************************************************************************************************************************************************************************************************
				DECLARE @CURSOR_GENERATEROWS CURSOR
					SET @CURSOR_GENERATEROWS = CURSOR LOCAL FAST_FORWARD
					FOR

						SELECT
							CASE
								WHEN tctpl.ctpl_payDate IS NULL THEN DAY(tct.ct_date)
								ELSE DAY(tctpl.ctpl_payDate)
							END		[Date],
							CONVERT(VARCHAR,
											CONVERT(DECIMAL(19,2),
											CASE
												WHEN tctpl.comp_id IS NULL THEN CONVERT(DECIMAL(19,2),tct.ct_ABalance)
												ELSE CONVERT(DECIMAL(19,2),tctpl.ctpl_balance)
							                END))			--VALOR
							+ '|' +
							CONVERT(VARCHAR,tct.ct_transaction)																			--CT_TRANSACTION
							+ '|' +
								'ROJO'																									--COLOR
							+ '|' +
								'30720'																									--UNIQUETEXTSID POR SI NECESITA TOOLTIP
							+ '|' +
							CONVERT(VARCHAR(10),tct.sd_id)
							+ '|' +
							dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id, tct.ct_transaction) + ' #' + CONVERT(nvarchar(10),ISNULL(tctpl.ctpl_payNumber,0))						[Data]
						FROM tbCommercialTransactions							tct	WITH (NOLOCK)

							LEFT JOIN tbCommercialTransactionsPurchaseLoan		tctpl	WITH (NOLOCK)
								ON	tctpl.comp_id			= tct.comp_id		AND
									tctpl.ct_transaction	= tct.ct_transaction

						WHERE	tct.comp_id = @comp_id							AND
								tct.sd_id	IN(101)								AND
								CASE
									WHEN tctpl.comp_id IS NULL THEN tct.ct_date
									ELSE	tctpl.ctpl_payDate
								END	BETWEEN @datefrom AND @dateto				AND
								CASE
									WHEN tctpl.comp_id IS NULL THEN tct.ct_ABalance
									ELSE	tctpl.ctpl_balance
								END > 0											--QUE EL BALANCE SEA MAYOR A CERO

						OPEN @CURSOR_GENERATEROWS
						FETCH NEXT FROM @CURSOR_GENERATEROWS

						INTO
							@day,
							@data

					WHILE @@FETCH_STATUS = 0
						BEGIN
							TRUNCATE TABLE #tmpPurchaseAvailability_ID
							SET @ID		= NULL
							DECLARE
								@Insert				VARCHAR(2000),
								@Update				VARCHAR(2000),
								@InsertIntoTBPA_ID	VARCHAR(2000)

							SET @Insert				= ''
							SET @Update				= ''
							SET @InsertIntoTBPA_ID	= ''


							--OBTENEMOS EL REGISTRO QUE TIENE EL VALOR EN CERO PARA ACTUALIZAR O EN SU DEFECTO INSERTAR
							SELECT
								@InsertIntoTBPA_ID = ('INSERT INTO #tmpPurchaseAvailability_ID (ID) SELECT TOP 1 tmp.ID FROM #tmpPurchaseAvailability tmp WHERE tmp.d' + CONVERT(VARCHAR(200),@day) + ' = ''0'' ORDER BY tmp.ID ASC')
							EXEC (@InsertIntoTBPA_ID)
							--RECUPERAMOS EL ID EN CASO DE HABERSE INSERTADO O ENCONTRADO EL VALOR
							SELECT
								@ID = ID
							FROM #tmpPurchaseAvailability_ID

							IF EXISTS (SELECT 1 FROM #tmpPurchaseAvailability_ID)
								BEGIN
									SELECT
										@Update = 'UPDATE #tmpPurchaseAvailability SET d' + CONVERT(VARCHAR(200),@day) + ' = ''' + CONVERT(VARCHAR(200),@data) + ''' WHERE ID = ' + CONVERT(VARCHAR(200),@ID)
									EXEC (@Update)
								END
							ELSE
								BEGIN
									SELECT
										@Insert = 'INSERT INTO #tmpPurchaseAvailability (' + 'd' + CONVERT(VARCHAR(200),@day) + ') VALUES(''' + CONVERT(VARCHAR(200),@data) + ''')'
									EXEC (@Insert)
								END

						FETCH NEXT FROM @CURSOR_GENERATEROWS
						INTO
							@day,
							@data
						END
					CLOSE @CURSOR_GENERATEROWS
				DEALLOCATE @CURSOR_GENERATEROWS
				--******************************************************************************************************************************************************************************************************************************************************************************

				--ÓRDENES DE PAGO
				--******************************************************************************************************************************************************************************************************************************************************************************
				DECLARE @CURSOR_GENERATEROWSOP CURSOR
					SET @CURSOR_GENERATEROWSOP = CURSOR LOCAL FAST_FORWARD
					FOR

						SELECT
							DAY(tct.ct_date)																				[Date],
							CONVERT(VARCHAR,CONVERT(DECIMAL(19,2), tct.ct_total - ISNULL(vctpwec.ct_totalEC,0) - ISNULL(vctpwRE.ct_totalRET,0)))									--VALOR
							+ '|' +
							CONVERT(VARCHAR,tct.ct_transaction)																--CT_TRANSACTION
							+ '|' +
								'BLANCO'																					--COLOR
							+ '|' +
								'30721'																						--UNIQUETEXTSID POR SI NECESITA TOOLTIP
							+ '|' +
							CONVERT(VARCHAR(10),tct.sd_id)
							+ '|' +
							dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id, tct.ct_transaction)				[Data]
						FROM tbCommercialTransactions										tct	WITH (NOLOCK)

						LEFT JOIN vwCommercialTransactions_PaymentsWithEmmitedCheque	vctpwec	WITH (NOLOCK)
							ON	vctpwec.comp_id			= tct.comp_id AND
								vctpwec.ct_transaction	= tct.ct_transaction

						LEFT JOIN vwCommercialTransactions_PaymentsWithRetentions		vctpwRE WITH (NOLOCK)
							ON	vctpwRE.comp_id			= tct.comp_id AND
								vctpwRE.ct_transaction	= tct.ct_transaction

						WHERE	tct.comp_id		= @comp_id						AND
								tct.sd_id		IN(106)							AND
								--tct.ct_ABalance > 0								AND
								tct.ct_date BETWEEN @datefrom AND @dateto		AND
								(
									vctpwec.comp_id IS NULL			OR
									vctpwec.ct_totalEC <> tct.ct_total
								)

						OPEN @CURSOR_GENERATEROWSOP
						FETCH NEXT FROM @CURSOR_GENERATEROWSOP

						INTO
							@day,
							@data

					WHILE @@FETCH_STATUS = 0
						BEGIN
							TRUNCATE TABLE #tmpPurchaseAvailability_ID
							SET @ID		= NULL
							DECLARE
								@InsertOP				VARCHAR(2000),
								@UpdateOP				VARCHAR(2000),
								@InsertIntoTBPA_IDOP	VARCHAR(2000)

							SET @InsertOP				= ''
							SET @UpdateOP				= ''
							SET @InsertIntoTBPA_IDOP	= ''


							--OBTENEMOS EL REGISTRO QUE TIENE EL VALOR EN CERO PARA ACTUALIZAR O EN SU DEFECTO INSERTAR
							SELECT
								@InsertIntoTBPA_IDOP = ('INSERT INTO #tmpPurchaseAvailability_ID (ID) SELECT TOP 1 tmp.ID FROM #tmpPurchaseAvailability tmp WHERE tmp.d' + CONVERT(VARCHAR(200),@day) + ' = ''0'' ORDER BY tmp.ID ASC')
							EXEC (@InsertIntoTBPA_IDOP)
							--RECUPERAMOS EL ID EN CASO DE HABERSE INSERTADO O ENCONTRADO EL VALOR
							SELECT
								@ID = ID
							FROM #tmpPurchaseAvailability_ID

							IF EXISTS (SELECT TOP 1  1 FROM #tmpPurchaseAvailability_ID)
								BEGIN
									SELECT
										@UpdateOP = 'UPDATE #tmpPurchaseAvailability SET d' + CONVERT(VARCHAR(200),@day) + ' = ''' + CONVERT(VARCHAR(200),@data) + ''' WHERE ID = ' + CONVERT(VARCHAR(200),@ID)
									EXEC (@UpdateOP)
								END
							ELSE
								BEGIN
									SELECT
										@InsertOP = 'INSERT INTO #tmpPurchaseAvailability (' + 'd' + CONVERT(VARCHAR(200),@day) + ') VALUES(''' + CONVERT(VARCHAR(200),@data) + ''')'
									EXEC (@InsertOP)
								END

						FETCH NEXT FROM @CURSOR_GENERATEROWSOP
						INTO
							@day,
							@data
						END
					CLOSE @CURSOR_GENERATEROWSOP
				DEALLOCATE @CURSOR_GENERATEROWSOP
				--******************************************************************************************************************************************************************************************************************************************************************************

				-- -----------------------------------------------------------------------------------------------------------------
				--PARTE NUEVA, CURSORES PARA CHEQUES EMITIDOS Y ORDENES DE COMPRA
				-- -----------------------------------------------------------------------------------------------------------------

				--EMMITED CHECKES
				--******************************************************************************************************************************************************************************************************************************************************************************
				DECLARE @CURSOR_GENERATEROWSEC		CURSOR
				SET @CURSOR_GENERATEROWSEC =	CURSOR LOCAL FAST_FORWARD
				FOR
					-- EMMITED CHECKES
					SELECT
						DAY(tec.ec_PayDate)			   							 [Date],
						CONVERT(VARCHAR(50),CONVERT(DECIMAL(19,2),tec.ec_Total)) +'|'+
						CONVERT(VARCHAR(50),tct.ct_transaction) 				 +'|'+
						'VERDE'													 +'|'+
						'30718'													 +'|'+
						CONVERT(VARCHAR(10),tct.sd_id)
							   													 +'|'+
						dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id, tct.ct_transaction) [Data]

					FROM tbCommercialTransactions					tct	WITH (NOLOCK)
						INNER JOIN tbEmmitedChecks					tec	WITH (NOLOCK)
							ON	tec.comp_id			= tct.comp_id	AND
								tec.ct_transaction	= tct.ct_transaction
					WHERE	tct.comp_id			= @comp_id			AND
							tct.sd_id			IN (106)			AND
							tec.ec_PayDate			BETWEEN @datefrom	AND @dateto
							--tct.ct_date			BETWEEN @datefrom	AND @dateto

					ORDER BY [Date]ASC

					OPEN @CURSOR_GENERATEROWSEC
					FETCH NEXT FROM @CURSOR_GENERATEROWSEC

					INTO
						@day,
						@data

				WHILE @@FETCH_STATUS = 0
					BEGIN
						TRUNCATE TABLE #tmpPurchaseAvailability_ID
						SET @ID		= NULL
						DECLARE
							@InsertEC				VARCHAR(2000),
							@UpdateEC				VARCHAR(2000),
							@InsertIntoTBPA_IDEC	VARCHAR(2000)

						SET @InsertEC				= ''
						SET @UpdateEC				= ''
						SET @InsertIntoTBPA_IDEC	= ''


						--OBTENEMOS EL REGISTRO QUE TIENE EL VALOR EN CERO PARA ACTUALIZAR O EN SU DEFECTO INSERTAR
						SELECT
							@InsertIntoTBPA_IDEC = ('INSERT INTO #tmpPurchaseAvailability_ID (ID) SELECT TOP 1 tmp.ID FROM #tmpPurchaseAvailability tmp WHERE tmp.d' + CONVERT(VARCHAR(200),@day) + ' = ''0'' ORDER BY tmp.ID ASC')
						EXEC (@InsertIntoTBPA_IDEC)
						--RECUPERAMOS EL ID EN CASO DE HABERSE INSERTADO O ENCONTRADO EL VALOR
						SELECT
							@ID = ID
						FROM #tmpPurchaseAvailability_ID

						IF EXISTS (SELECT TOP 1  1 FROM #tmpPurchaseAvailability_ID)
							BEGIN
								SELECT
									@UpdateEC = 'UPDATE #tmpPurchaseAvailability SET d' + CONVERT(VARCHAR(200),@day) + ' = ''' + CONVERT(VARCHAR(200),@data) + ''' WHERE ID = ' + CONVERT(VARCHAR(200),@ID)
								EXEC (@UpdateEC)
							END
						ELSE
							BEGIN
								SELECT
									@InsertEC = 'INSERT INTO #tmpPurchaseAvailability (' + 'd' + CONVERT(VARCHAR(200),@day) + ') VALUES(''' + CONVERT(VARCHAR(200),@data) + ''')'
								EXEC (@InsertEC)
							END

					FETCH NEXT FROM @CURSOR_GENERATEROWSEC
					INTO
						@day,
						@data
					END
				CLOSE @CURSOR_GENERATEROWSEC
			DEALLOCATE @CURSOR_GENERATEROWSEC
			--******************************************************************************************************************************************************************************************************************************************************************************

			--PURCHASEORDER
			--11-02-21 STL AGREGUE SEGUN TICKET 11580 LA  RESTA DE LOS PAGOS RELACIONADOS A LA OC
			--******************************************************************************************************************************************************************************************************************************************************************************
			DECLARE @CURSOR_GENERATEROWSPO		CURSOR
				SET @CURSOR_GENERATEROWSPO =	CURSOR LOCAL FAST_FORWARD
				FOR
					-- PURCHASEORDER
					--CONVERT(VARCHAR(50),CONVERT(DECIMAL(19,2),tpod.pod_price))+'|'+
					SELECT
						--DAY(tctpl.ctpl_date) 										[Date],
						DAY (CASE WHEN tctpl.comp_id IS NULL THEN tpoh.poh_cd
							 ELSE tctpl.ctpl_payDate
							 END)													[Date],
						--CONVERT(VARCHAR,CONVERT(DECIMAL(19,2), tctpl.ctpl_balance)) + '|' +
						CONVERT(VARCHAR,
										CONVERT(DECIMAL(19,2),
										CASE
											WHEN tctpl.comp_id IS NULL THEN 0
										ELSE
												(tctpl.ctpl_balance * tpoh.poh_pendingCoeficient)

												- (SELECT  ISNULL(SUM(ISNULL(tct.ct_total,0)),0)
																										FROM tbPurchaseOrder_PaymentsRelations		AS tpopr WITH(NOLOCK)
																										INNER JOIN tbCommercialTransactions			AS tct	WITH(NOLOCK)
																											ON	tct.comp_id			= tpopr.comp_id AND
																												tct.ct_transaction	= tpopr.ct_transaction
																										 WHERE	tpopr.comp_id	= tpoh.comp_id AND
																												tpopr.bra_id	= tpoh.bra_id AND
																												tpopr.poh_id	= tpoh.poh_id) /** tpoh.poh_taxCoeficient*/
										END))										+ '|' +
						CONVERT(VARCHAR,tpoh.poh_id) 								+ '|' +	--POH_ID
						'ORANGE'													+ '|' +
						'30723'														+ '|' + --Órden de Compra
						CASE WHEN tctpl.comp_id  IS NOT NULL
							THEN	'30727'
						ELSE		'-1'
						END  														+ '|' +
						CONVERT(VARCHAR,tpoh.bra_id)			[Data]
					FROM tbPurchaseOrderHeader							tpoh		WITH (NOLOCK)
						INNER JOIN tbCommercialTransactionsPurchaseLoan	tctpl		WITH (NOLOCK)
							ON	tctpl.comp_id		= tpoh.comp_id		AND
								tctpl.bra_id		= tpoh.bra_id		AND
								tctpl.poh_id		= tpoh.poh_id




					WHERE	tpoh.comp_id	= @comp_id			AND
							CASE
								WHEN tctpl.comp_id IS NULL THEN tpoh.poh_cd
								ELSE	tctpl.ctpl_payDate
							END	BETWEEN @datefrom AND @dateto	AND
							(tctpl.ctpl_balance * tpoh.poh_pendingCoeficient /** tpoh.poh_taxCoeficient*/) > 0						--QUE EL BALANCE SEA MAYOR A CERO

					ORDER BY [Date]ASC

					OPEN @CURSOR_GENERATEROWSPO
					FETCH NEXT FROM @CURSOR_GENERATEROWSPO

					INTO
						@day,
						@data

				WHILE @@FETCH_STATUS = 0
					BEGIN
						TRUNCATE TABLE #tmpPurchaseAvailability_ID
						SET @ID		= NULL
						DECLARE
							@InsertPO				VARCHAR(2000),
							@UpdatePO				VARCHAR(2000),
							@InsertIntoTBPA_IDPO	VARCHAR(2000)

						SET @InsertPO				= ''
						SET @UpdatePO				= ''
						SET @InsertIntoTBPA_IDPO	= ''


						--OBTENEMOS EL REGISTRO QUE TIENE EL VALOR EN CERO PARA ACTUALIZAR O EN SU DEFECTO INSERTAR
						SELECT
							@InsertIntoTBPA_IDPO = ('INSERT INTO #tmpPurchaseAvailability_ID (ID) SELECT TOP 1 tmp.ID FROM #tmpPurchaseAvailability tmp WHERE tmp.d' + CONVERT(VARCHAR(200),@day) + ' = ''0'' ORDER BY tmp.ID ASC')
						EXEC (@InsertIntoTBPA_IDPO)
						--RECUPERAMOS EL ID EN CASO DE HABERSE INSERTADO O ENCONTRADO EL VALOR
						SELECT
							@ID = ID
						FROM #tmpPurchaseAvailability_ID

						IF EXISTS (SELECT 1 FROM #tmpPurchaseAvailability_ID)
							BEGIN
								SELECT
									@UpdatePO = 'UPDATE #tmpPurchaseAvailability SET d' + CONVERT(VARCHAR(200),@day) + ' = ''' + CONVERT(VARCHAR(200),@data) + ''' WHERE ID = ' + CONVERT(VARCHAR(200),@ID)
								EXEC (@UpdatePO)
							END
						ELSE
							BEGIN
								SELECT
									@InsertPO = 'INSERT INTO #tmpPurchaseAvailability (' + 'd' + CONVERT(VARCHAR(200),@day) + ') VALUES(''' + CONVERT(VARCHAR(200),@data) + ''')'
								EXEC (@InsertPO)
							END

					FETCH NEXT FROM @CURSOR_GENERATEROWSPO
					INTO
						@day,
						@data
					END
				CLOSE @CURSOR_GENERATEROWSPO
				DEALLOCATE @CURSOR_GENERATEROWSPO
				--******************************************************************************************************************************************************************************************************************************************************************************

				--PaymentsRequest_EmmitedChecksTmp
				--******************************************************************************************************************************************************************************************************************************************************************************
				DECLARE @CURSOR_GENERATEROWSECTMP		CURSOR
				SET @CURSOR_GENERATEROWSECTMP =	CURSOR LOCAL FAST_FORWARD
				FOR
					--PaymentsRequest_EmmitedChecksTmp
					SELECT
						DAY(tpr.preq_emittionDate),
						CONVERT(VARCHAR(100),CONVERT(DECIMAL(19,2),tprect.ect_total))	+'|'+
						''										+'|'+
						'AMARILLO'								+'|'+
						'30719'									+'|'+
						''  									+'|'+
														''				[Data]
					FROM tbPaymentsRequest_EmmitedChecksTmp				tprect	WITH (NOLOCK)
							INNER JOIN tbPaymentsRequest				tpr	WITH (NOLOCK)
								ON	tpr.comp_id = tprect.comp_id		AND
									tpr.preq_id = tprect.preq_id
						WHERE	tprect.comp_id			= @comp_id		AND
								tpr.preq_emittionDate	BETWEEN @datefrom	AND @dateto AND
								tpr.preq_isEmitted		= 'False'

					OPEN @CURSOR_GENERATEROWSECTMP
					FETCH NEXT FROM @CURSOR_GENERATEROWSECTMP

					INTO
						@day,
						@data

				WHILE @@FETCH_STATUS = 0
					BEGIN
						TRUNCATE TABLE #tmpPurchaseAvailability_ID
						SET @ID		= NULL
						DECLARE
							@InsertECTMP				VARCHAR(2000),
							@UpdateECTMP				VARCHAR(2000),
							@InsertIntoTBPA_IDECTMP	VARCHAR(2000)

						SET @InsertECTMP				= ''
						SET @UpdateECTMP				= ''
						SET @InsertIntoTBPA_IDECTMP	= ''


						--OBTENEMOS EL REGISTRO QUE TIENE EL VALOR EN CERO PARA ACTUALIZAR O EN SU DEFECTO INSERTAR
						SELECT
							@InsertIntoTBPA_IDECTMP = ('INSERT INTO #tmpPurchaseAvailability_ID (ID) SELECT TOP 1 tmp.ID FROM #tmpPurchaseAvailability tmp WHERE tmp.d' + CONVERT(VARCHAR(200),@day) + ' = ''0'' ORDER BY tmp.ID ASC')
						EXEC (@InsertIntoTBPA_IDECTMP)
						--RECUPERAMOS EL ID EN CASO DE HABERSE INSERTADO O ENCONTRADO EL VALOR
						SELECT
							@ID = ID
						FROM #tmpPurchaseAvailability_ID

						IF EXISTS (SELECT TOP 1  1 FROM #tmpPurchaseAvailability_ID)
							BEGIN
								SELECT
									@UpdateECTMP = 'UPDATE #tmpPurchaseAvailability SET d' + CONVERT(VARCHAR(200),@day) + ' = ''' + CONVERT(VARCHAR(200),@data) + ''' WHERE ID = ' + CONVERT(VARCHAR(200),@ID)
								EXEC (@UpdateECTMP)
							END
						ELSE
							BEGIN
								SELECT
									@InsertECTMP = 'INSERT INTO #tmpPurchaseAvailability (' + 'd' + CONVERT(VARCHAR(200),@day) + ') VALUES(''' + CONVERT(VARCHAR(200),@data) + ''')'
								EXEC (@InsertECTMP)
							END

					FETCH NEXT FROM @CURSOR_GENERATEROWSECTMP
					INTO
						@day,
						@data
					END
				CLOSE @CURSOR_GENERATEROWSECTMP
				DEALLOCATE @CURSOR_GENERATEROWSECTMP
			--******************************************************************************************************************************************************************************************************************************************************************************

			--PAYMENTREQUESTCHECKPORTFOLIO
			--******************************************************************************************************************************************************************************************************************************************************************************
				DECLARE @CURSOR_GENERATEROWSPRCP		CURSOR
				SET @CURSOR_GENERATEROWSPRCP =	CURSOR LOCAL FAST_FORWARD
				FOR
					--CHEQUES EN CARTERA
					SELECT
						DAY(tpr.preq_emittionDate)								[Date],
						CONVERT(VARCHAR(100),CONVERT(DECIMAL(19,2),tcp1.chp_total))	+'|'+
						''										+'|'+
						'AMARILLO'								+'|'+
						'30719'									+'|'+
						''										+'|'+
						''														[Data]
					FROM tbPaymentsRequest_CheckPortfolio						tprcp	WITH (NOLOCK)
							INNER JOIN tbCheckPortfolio							tcp1	WITH (NOLOCK)
								ON	tcp1.comp_id			= tprcp.comp_id		AND
									tcp1.chp_id				= tprcp.chp_id
							INNER JOIN tbPaymentsRequest						tpr	WITH (NOLOCK)
								ON	tpr.comp_id				= tprcp.comp_id		AND
									tpr.preq_id				= tprcp.preq_id
						WHERE	tcp1.comp_id				= @comp_id			AND
								tpr.preq_emittionDate	BETWEEN @datefrom	AND @dateto AND
								tpr.preq_isEmitted			= 'False'

					OPEN @CURSOR_GENERATEROWSPRCP
					FETCH NEXT FROM @CURSOR_GENERATEROWSPRCP

					INTO
						@day,
						@data

				WHILE @@FETCH_STATUS = 0
					BEGIN
						TRUNCATE TABLE #tmpPurchaseAvailability_ID
						SET @ID		= NULL
						DECLARE
							@InsertPRCP				VARCHAR(2000),
							@UpdatePRCP				VARCHAR(2000),
							@InsertIntoTBPA_IDPRCP	VARCHAR(2000)

						SET @InsertPRCP				= ''
						SET @UpdatePRCP				= ''
						SET @InsertIntoTBPA_IDPRCP	= ''


						--OBTENEMOS EL REGISTRO QUE TIENE EL VALOR EN CERO PARA ACTUALIZAR O EN SU DEFECTO INSERTAR
						SELECT
							@InsertIntoTBPA_IDPRCP = ('INSERT INTO #tmpPurchaseAvailability_ID (ID) SELECT TOP 1 tmp.ID FROM #tmpPurchaseAvailability tmp WHERE tmp.d' + CONVERT(VARCHAR(200),@day) + ' = ''0'' ORDER BY tmp.ID ASC')
						EXEC (@InsertIntoTBPA_IDPRCP)
						--RECUPERAMOS EL ID EN CASO DE HABERSE INSERTADO O ENCONTRADO EL VALOR
						SELECT
							@ID = ID
						FROM #tmpPurchaseAvailability_ID

						IF EXISTS (SELECT TOP 1  1 FROM #tmpPurchaseAvailability_ID)
							BEGIN
								SELECT
									@UpdatePRCP = 'UPDATE #tmpPurchaseAvailability SET d' + CONVERT(VARCHAR(200),@day) + ' = ''' + CONVERT(VARCHAR(200),@data) + ''' WHERE ID = ' + CONVERT(VARCHAR(200),@ID)
								EXEC (@UpdatePRCP)
							END
						ELSE
							BEGIN
								SELECT
									@InsertPRCP = 'INSERT INTO #tmpPurchaseAvailability (' + 'd' + CONVERT(VARCHAR(200),@day) + ') VALUES(''' + CONVERT(VARCHAR(200),@data) + ''')'
								EXEC (@InsertPRCP)
							END

					FETCH NEXT FROM @CURSOR_GENERATEROWSPRCP
					INTO
						@day,
						@data
					END
				CLOSE @CURSOR_GENERATEROWSPRCP
				DEALLOCATE @CURSOR_GENERATEROWSPRCP
			--******************************************************************************************************************************************************************************************************************************************************************************

			--BANKING TRANSACTIONS
			--******************************************************************************************************************************************************************************************************************************************************************************
				DECLARE @CURSOR_GENERATEROWSBT		CURSOR
				SET @CURSOR_GENERATEROWSBT =	CURSOR LOCAL FAST_FORWARD
				FOR
					--BANKING TRANSACTIONS
					SELECT
						DAY(tpr.preq_emittionDate)								[Date],
						CONVERT(VARCHAR(100),CONVERT(DECIMAL(19,2),tprbtt.btt_total))	+'|'+
						''										+'|'+
						'AMARILLO'								+'|'+
						'30719'									+'|'+
						''										+'|'+
						''														[Data]
					FROM tbPaymentsRequest_BankingTransactionsTmp				tprbtt	WITH (NOLOCK)
							INNER JOIN tbPaymentsRequest						tpr	WITH (NOLOCK)
								ON	tpr.comp_id = tprbtt.comp_id				AND
									tpr.preq_id = tprbtt.preq_id
						WHERE	tprbtt.comp_id				= @comp_id			AND
								tpr.preq_emittionDate	BETWEEN @datefrom	AND @dateto AND
								tpr.preq_isEmitted			= 'False'

					OPEN @CURSOR_GENERATEROWSBT
					FETCH NEXT FROM @CURSOR_GENERATEROWSBT

					INTO
						@day,
						@data

				WHILE @@FETCH_STATUS = 0
					BEGIN
						TRUNCATE TABLE #tmpPurchaseAvailability_ID
						SET @ID		= NULL
						DECLARE
							@InsertBT				VARCHAR(2000),
							@UpdateBT				VARCHAR(2000),
							@InsertIntoTBPA_IDBT	VARCHAR(2000)

						SET @InsertBT				= ''
						SET @UpdateBT				= ''
						SET @InsertIntoTBPA_IDBT	= ''


						--OBTENEMOS EL REGISTRO QUE TIENE EL VALOR EN CERO PARA ACTUALIZAR O EN SU DEFECTO INSERTAR
						SELECT
							@InsertIntoTBPA_IDBT = ('INSERT INTO #tmpPurchaseAvailability_ID (ID) SELECT TOP 1 tmp.ID FROM #tmpPurchaseAvailability tmp WHERE tmp.d' + CONVERT(VARCHAR(200),@day) + ' = ''0'' ORDER BY tmp.ID ASC')
						EXEC (@InsertIntoTBPA_IDBT)
						--RECUPERAMOS EL ID EN CASO DE HABERSE INSERTADO O ENCONTRADO EL VALOR
						SELECT
							@ID = ID
						FROM #tmpPurchaseAvailability_ID

						IF EXISTS (SELECT TOP 1  1 FROM #tmpPurchaseAvailability_ID)
							BEGIN
								SELECT
									@UpdateBT = 'UPDATE #tmpPurchaseAvailability SET d' + CONVERT(VARCHAR(200),@day) + ' = ''' + CONVERT(VARCHAR(200),@data) + ''' WHERE ID = ' + CONVERT(VARCHAR(200),@ID)
								EXEC (@UpdateBT)
							END
						ELSE
							BEGIN
								SELECT
									@InsertBT = 'INSERT INTO #tmpPurchaseAvailability (' + 'd' + CONVERT(VARCHAR(200),@day) + ') VALUES(''' + CONVERT(VARCHAR(200),@data) + ''')'
								EXEC (@InsertBT)
							END

					FETCH NEXT FROM @CURSOR_GENERATEROWSBT
					INTO
						@day,
						@data
					END
				CLOSE @CURSOR_GENERATEROWSBT
				DEALLOCATE @CURSOR_GENERATEROWSBT
			--******************************************************************************************************************************************************************************************************************************************************************************

			--CASH MOVEMENTS
			--******************************************************************************************************************************************************************************************************************************************************************************
				DECLARE @CURSOR_GENERATEROWSCM		CURSOR
				SET @CURSOR_GENERATEROWSCM =	CURSOR LOCAL FAST_FORWARD
				FOR
					--BANKING TRANSACTIONS
					SELECT
						DAY(tpr.preq_emittionDate)						[Date],
						CONVERT(VARCHAR(100),CONVERT(DECIMAL(19,2),tprcmt.cmt_amount))	+'|'+
						''										+'|'+
						'AMARILLO'								+'|'+
						'30719'									+'|'+
						''										+'|'+
						''												[Data]
					FROM tbPaymentsRequest_CashMovementsTMP				tprcmt	WITH (NOLOCK)
							INNER JOIN tbPaymentsRequest				tpr	WITH (NOLOCK)
								ON	tpr.comp_id = tprcmt.comp_id		AND
									tpr.preq_id = tprcmt.preq_id
						WHERE	tprcmt.comp_id			= @comp_id		AND
								tpr.preq_emittionDate	BETWEEN @datefrom AND @dateto AND
								tpr.preq_isEmitted		= 'False'

					OPEN @CURSOR_GENERATEROWSCM
					FETCH NEXT FROM @CURSOR_GENERATEROWSCM

					INTO
						@day,
						@data

				WHILE @@FETCH_STATUS = 0
					BEGIN
						TRUNCATE TABLE #tmpPurchaseAvailability_ID
						SET @ID		= NULL
						DECLARE
							@InsertCMTMP				VARCHAR(2000),
							@UpdateCMTMP				VARCHAR(2000),
							@InsertIntoTBPA_IDCMTMP		VARCHAR(2000)

						SET @InsertCMTMP				= ''
						SET @UpdateCMTMP				= ''
						SET @InsertIntoTBPA_IDCMTMP	= ''


						--OBTENEMOS EL REGISTRO QUE TIENE EL VALOR EN CERO PARA ACTUALIZAR O EN SU DEFECTO INSERTAR
						SELECT
							@InsertIntoTBPA_IDCMTMP = ('INSERT INTO #tmpPurchaseAvailability_ID (ID) SELECT TOP 1 tmp.ID FROM #tmpPurchaseAvailability tmp WHERE tmp.d' + CONVERT(VARCHAR(200),@day) + ' = ''0'' ORDER BY tmp.ID ASC')
						EXEC (@InsertIntoTBPA_IDCMTMP)
						--RECUPERAMOS EL ID EN CASO DE HABERSE INSERTADO O ENCONTRADO EL VALOR
						SELECT
							@ID = ID
						FROM #tmpPurchaseAvailability_ID

						IF EXISTS (SELECT TOP 1  1 FROM #tmpPurchaseAvailability_ID)
							BEGIN
								SELECT
									@UpdateCMTMP = 'UPDATE #tmpPurchaseAvailability SET d' + CONVERT(VARCHAR(200),@day) + ' = ''' + CONVERT(VARCHAR(200),@data) + ''' WHERE ID = ' + CONVERT(VARCHAR(200),@ID)
								EXEC (@UpdateCMTMP)
							END
						ELSE
							BEGIN
								SELECT
									@InsertCMTMP = 'INSERT INTO #tmpPurchaseAvailability (' + 'd' + CONVERT(VARCHAR(200),@day) + ') VALUES(''' + CONVERT(VARCHAR(200),@data) + ''')'
								EXEC (@InsertCMTMP)
							END

					FETCH NEXT FROM @CURSOR_GENERATEROWSCM
					INTO
						@day,
						@data
					END
				CLOSE @CURSOR_GENERATEROWSCM
				DEALLOCATE @CURSOR_GENERATEROWSCM
			--******************************************************************************************************************************************************************************************************************************************************************************

			--OTROS GASTOS
			--******************************************************************************************************************************************************************************************************************************************************************************
				DECLARE @CURSOR_GENERATEROWCFOC		CURSOR
				SET @CURSOR_GENERATEROWCFOC =	CURSOR LOCAL FAST_FORWARD
				FOR
					--tbCashFlowOtherConcepts
					SELECT
						DAY(tcfoc.cfo_date)						[Date],
						CONVERT(VARCHAR(100),CONVERT(DECIMAL(19,2),ISNULL(tcfoc.cfo_credit,0)))	+'|'+
						--CONVERT(VARCHAR(100),CONVERT(DECIMAL(19,2),ISNULL(tcfoc.cfo_debit,0) - ISNULL(tcfoc.cfo_credit,0)))	+'|'+
						''										+'|'+
						'BRICK'									+'|'+
						'30725'									+'|'+
						tcfoc.cfo_desc							+'|'+
						''
					FROM tbCashFlowOtherConcepts						tcfoc	WITH (NOLOCK)
					WHERE	tcfoc.comp_id	= @comp_id					AND
							tcfoc.cfo_date	BETWEEN @datefrom AND @dateto



					OPEN @CURSOR_GENERATEROWCFOC
					FETCH NEXT FROM @CURSOR_GENERATEROWCFOC

					INTO
						@day,
						@data

				WHILE @@FETCH_STATUS = 0
					BEGIN
						TRUNCATE TABLE #tmpPurchaseAvailability_ID
						SET @ID		= NULL
						DECLARE
							@InsertCFOC				VARCHAR(2000),
							@UpdateCFOC				VARCHAR(2000),
							@InsertIntoTBPA_IDCFOC	VARCHAR(2000)

						SET @InsertCFOC				= ''
						SET @UpdateCFOC				= ''
						SET @InsertIntoTBPA_IDCFOC	= ''


						--OBTENEMOS EL REGISTRO QUE TIENE EL VALOR EN CERO PARA ACTUALIZAR O EN SU DEFECTO INSERTAR
						SELECT
							@InsertIntoTBPA_IDCFOC = ('INSERT INTO #tmpPurchaseAvailability_ID (ID) SELECT TOP 1 tmp.ID FROM #tmpPurchaseAvailability tmp WHERE tmp.d' + CONVERT(VARCHAR(200),@day) + ' = ''0'' ORDER BY tmp.ID ASC')
						EXEC (@InsertIntoTBPA_IDCFOC)
						--RECUPERAMOS EL ID EN CASO DE HABERSE INSERTADO O ENCONTRADO EL VALOR
						SELECT
							@ID = ID
						FROM #tmpPurchaseAvailability_ID

						IF EXISTS (SELECT TOP 1  1 FROM #tmpPurchaseAvailability_ID)
							BEGIN
								SELECT
									@UpdateCFOC = 'UPDATE #tmpPurchaseAvailability SET d' + CONVERT(VARCHAR(200),@day) + ' = ''' + CONVERT(VARCHAR(200),@data) + ''' WHERE ID = ' + CONVERT(VARCHAR(200),@ID)
								EXEC (@UpdateCFOC)
							END
						ELSE
							BEGIN
								SELECT
									@InsertCFOC = 'INSERT INTO #tmpPurchaseAvailability (' + 'd' + CONVERT(VARCHAR(200),@day) + ') VALUES(''' + CONVERT(VARCHAR(200),@data) + ''')'
								EXEC (@InsertCFOC)
							END

					FETCH NEXT FROM @CURSOR_GENERATEROWCFOC
					INTO
						@day,
						@data
					END
				CLOSE @CURSOR_GENERATEROWCFOC
				DEALLOCATE @CURSOR_GENERATEROWCFOC
			--******************************************************************************************************************************************************************************************************************************************************************************


			-- FIN CURSORES NUEVOS ---------------------------------------------------------------
			-- -----------------------------------------------------------------------------------------------------------------------------------------


			--SELECT CON LOS DATOS FINALES PARA LA GRILLA
			SELECT
				*
			FROM #tmpPurchaseAvailability

			--BORRAMOS LAS TABLAS TEMPORALES
			DROP TABLE #tmpPurchaseAvailability
			DROP TABLE #tmpPurchaseAvailability_ID

		END


GO




CREATE PROCEDURE [dbo].[spPaymentsAvailability_GetDataByFilters4GridAnalyticalReport]
(
	@comp_id	INT,
	@lang_id	INT,
	@pap_id		INT
)
AS

	SET NOCOUNT ON
		BEGIN
			--***************************************************************************
			/*
				SI SE MODIFICA ALGÚN SELECT DE ESTE STORED PROCEDURE O CUALQUIER SUM,
				HAY QUE MODIFICAR TAMBIEN EN LOS STORED PROCEDURE
				spPaymentsAvailability_GetDataByFilters4GridTotalsView
				spPaymentsAvailability_GetTotals
				spPaymentsAvailability_GetDataByFilters4Grid
			*/
			--***************************************************************************

			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
			-- -----------------------------------------------------------------------------

			SET DATEFORMAT 'YMD'



			-- ----------------------------------------------------
			-- TESTING
			-- ----------------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@lang_id	INT,
					@pap_id		INT
				SELECT
					@comp_id	= 1,
					@lang_id	= 2,
					@pap_id		= 75
			*/
			-- ----------------------------------------------------




			--ENSAMBLAMOS LAS FECHAS PARA INICIO Y FIN DE MES
			DECLARE
				@datefrom	DATETIME,
				@dateto		DATETIME

			SELECT
				@datefrom	= dbo.fnGetEnd_or_BeginOfDate(tpa.pap_fromDate,		'False'),
				@dateto		= dbo.fnGetEnd_or_BeginOfDate(tpa.pap_toDate,		'True')

			FROM tbPaymentsAvailability		tpa	WITH (NOLOCK)
			WHERE	tpa.comp_id = @comp_id	AND
					tpa.pap_id	= @pap_id


			DECLARE @tmpAnalyticalReport TABLE(Date DATETIME, supp_name VARCHAR(200), sk_desc VARCHAR(200), Documento VARCHAR(200), Monto DECIMAL(25,2), Class INT)

			INSERT INTO @tmpAnalyticalReport (Date, supp_name, sk_desc, Documento, Monto, Class)

				SELECT
					--CASE WHEN tctpl.comp_id IS NULL THEN tct.ct_date ELSE tctpl.ctpl_date END									[Date],
					CASE WHEN tctpl.comp_id IS NULL THEN tct.ct_payDate ELSE tctpl.ctpl_payDate END								[Date],
					ts.supp_name,
					ISNULL(tsk.sk_desc,'')																						[sk_desc],
					dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)							[Document],
					CONVERT(DECIMAL(19,2), CASE WHEN tctpl.comp_id IS NULL THEN tct.ct_ABalance ELSE tctpl.ctpl_balance END)	[Monto],
					tct.sd_id																									[Class]
					--tct.ct_transaction,
					--ts.supp_id
					FROM tbCommercialTransactions							tct	WITH (NOLOCK)
						LEFT JOIN tbCommercialTransactionsPurchaseLoan		tctpl	WITH (NOLOCK)
							ON	tctpl.comp_id			= tct.comp_id		AND
								tctpl.ct_transaction	= tct.ct_transaction
						LEFT JOIN tbSupplier								ts	WITH (NOLOCK)
							ON	ts.comp_id				= tct.comp_id		AND
								ts.supp_id				= tct.supp_id
						LEFT JOIN tbSupplierKind							tsk	WITH (NOLOCK)
							ON	tsk.comp_id				= ts.comp_id		AND
								tsk.sk_id				= ts.sk_id
					WHERE	tct.comp_id = @comp_id							AND
							tct.sd_id	= 101								AND	--101 = Factura 106 = Orden de Pago
							CASE
								WHEN tctpl.comp_id IS NULL THEN
								tct.ct_ABalance
							ELSE
								tctpl.ctpl_balance
							END > 0											AND --QUE EL BALANCE SEA MAYOR A CERO
							CASE
								WHEN tctpl.comp_id IS NULL THEN tct.ct_payDate
								ELSE	tctpl.ctpl_payDate
							END	BETWEEN @datefrom AND @dateto

				--ORDER BY [Date] ASC
			UNION
				SELECT
					tct.ct_date																		[Date],
					ts.supp_name										,
					ISNULL(tsk.sk_desc,'')															[sk_desc],
					dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction)	[Document],
					tct.ct_total - ISNULL(vctpwec.ct_totalEC,0)  - ISNULL(vctpwRE.ct_totalRET,0)	[Monto],
					tct.sd_id																		[Class]
					FROM tbCommercialTransactions											tct	WITH (NOLOCK)
							LEFT JOIN tbSupplier											ts	WITH (NOLOCK)
							ON	ts.comp_id					= tct.comp_id					AND
								ts.supp_id					= tct.supp_id
							LEFT JOIN tbSupplierKind										tsk	WITH (NOLOCK)
							ON	tsk.comp_id					= ts.comp_id					AND
								tsk.sk_id					= ts.sk_id
							LEFT JOIN vwCommercialTransactions_PaymentsWithEmmitedCheque	vctpwec	WITH (NOLOCK)
								ON	vctpwec.comp_id			= tct.comp_id AND
									vctpwec.ct_transaction	= tct.ct_transaction

							LEFT JOIN vwCommercialTransactions_PaymentsWithRetentions		vctpwRE WITH (NOLOCK)
								ON	vctpwRE.comp_id			= tct.comp_id AND
									vctpwRE.ct_transaction	= tct.ct_transaction

					WHERE	tct.comp_id		= @comp_id						AND
							tct.sd_id		= 106							AND	--ANTES ERA IN(106)
							--tct.ct_ABalance > 0								AND
							tct.ct_payDate BETWEEN @datefrom AND @dateto		AND
							--tct.ct_date BETWEEN @datefrom AND @dateto		AND
							(
								vctpwec.comp_id IS NULL			OR
								vctpwec.ct_totalEC <> tct.ct_total
							)
			UNION
				SELECT
					--tct.ct_date												[Date],
					tec.ec_PayDate											[Date],
					ts.supp_name,
					ISNULL(tsk.sk_desc,'')									[sk_desc],
					'Cheque' + ' # ' + CONVERT(VARCHAR(30),tec.ec_Number)	[Document],
					CONVERT(DECIMAL(19,2),tec.ec_Total)						[Monto],
					500														[Class]
					--tct.ct_transaction
					FROM tbCommercialTransactions							tct	WITH (NOLOCK)
						INNER JOIN tbEmmitedChecks							tec	WITH (NOLOCK)
							ON	tec.comp_id			= tct.comp_id			AND
								tec.ct_transaction	= tct.ct_transaction
						LEFT JOIN tbSupplier								ts	WITH (NOLOCK)
							ON	ts.comp_id				= tct.comp_id		AND
								ts.supp_id				= tct.supp_id
						LEFT JOIN tbSupplierKind							tsk	WITH (NOLOCK)
							ON	tsk.comp_id				= ts.comp_id		AND
								tsk.sk_id				= ts.sk_id
					WHERE	tct.comp_id = @comp_id							AND
							tct.sd_id	= 106								AND	--ANTES ERA IN(106)
							tec.ec_PayDate	BETWEEN @datefrom AND @dateto
							--tct.ct_date	BETWEEN @datefrom AND @dateto


			UNION
				SELECT
					CASE WHEN tctpl.comp_id IS NULL THEN tpoh.poh_cd
							ELSE tctpl.ctpl_payDate
					END																				[Date],
					ts.supp_name,
					ISNULL(tsk.sk_desc,'')															[sk_desc],
					'OC #' + CONVERT(VARCHAR(30),tpoh.poh_id)										[Document],

					CONVERT(DECIMAL(19,2),
					CASE
						WHEN tctpl.comp_id IS NULL THEN 0
					ELSE
							(tctpl.ctpl_balance * tpoh.poh_pendingCoeficient) - (SELECT ISNULL(SUM(ISNULL(tct.ct_total,0)),0)
																					FROM tbPurchaseOrder_PaymentsRelations		AS tpopr WITH(NOLOCK)
																					INNER JOIN tbCommercialTransactions			AS tct	WITH(NOLOCK)
																						ON	tct.comp_id			= tpopr.comp_id AND
																							tct.ct_transaction	= tpopr.ct_transaction
																						WHERE	tpopr.comp_id	= tpoh.comp_id AND
																							tpopr.bra_id	= tpoh.bra_id AND
																							tpopr.poh_id	= tpoh.poh_id) /** tpoh.poh_taxCoeficient*/
					END) 																			[Monto],
					600																				[Class]
				FROM tbPurchaseOrderHeader							tpoh		WITH (NOLOCK)
					INNER JOIN tbCommercialTransactionsPurchaseLoan	tctpl		WITH (NOLOCK)
						ON	tctpl.comp_id	= tpoh.comp_id			AND
							tctpl.bra_id	= tpoh.bra_id			AND
							tctpl.poh_id	= tpoh.poh_id
					LEFT JOIN tbCommercialTransactions				AS tct		WITH(NOLOCK)
						ON	tct.comp_id		= tctpl.comp_id			AND
							tct.ct_transaction = tctpl.ct_transaction
					INNER JOIN tbSupplier							AS ts		WITH(NOLOCK)
						ON	ts.comp_id		= tpoh.comp_id			AND
							ts.supp_id		= tpoh.supp_id
					LEFT JOIN tbSupplierKind						AS tsk		WITH(NOLOCK)
						ON	tsk.comp_id		= ts.comp_id			AND
							tsk.sk_id		= ts.sk_id


				WHERE	tpoh.comp_id	= @comp_id			AND
						CASE
							WHEN tctpl.comp_id IS NULL THEN tpoh.poh_cd
							ELSE	tctpl.ctpl_payDate
						END	BETWEEN @datefrom AND @dateto	AND
						(tctpl.ctpl_balance * tpoh.poh_pendingCoeficient /** tpoh.poh_taxCoeficient*/) > 0						--QUE EL BALANCE SEA MAYOR A CERO

				--ORDER BY [Date]ASC
				ORDER BY [Date], [Class] ASC
			-- ---------------------------------------------------------
			-- TABLA QUE MUESTRA LOS VALORES SEPARADOS
			-- ---------------------------------------------------------
				SELECT
					' '							[ ],
					TMP.*
					FROM @tmpAnalyticalReport	TMP
					--WHERE TMP.Date BETWEEN @datefrom AND @dateto
					ORDER BY Date ASC
			-- ---------------------------------------------------------

			-- ---------------------------------------------------------
			--TABLA CON LOS TOTALES AGRUPADOS POR TIPO DE PROVEEDOR
			-- ---------------------------------------------------------
				SELECT
					' '							[ ],
					TMP.sk_desc,
					SUM(TMP.Monto)				[Total]
					FROM @tmpAnalyticalReport	TMP
					--WHERE TMP.Date BETWEEN @datefrom AND @dateto
					GROUP BY TMP.sk_desc
			-- ---------------------------------------------------------
		END

GO



CREATE PROCEDURE [dbo].[spPaymentsAvailability_GetDataByFilters4GridTotalsView]
(
	@comp_id	INT,
	@pap_id		INT
)
AS

	SET NOCOUNT ON
	--***************************************************************************
	/*
		SI SE MODIFICA ALGÚN SELECT DE ESTE STORED PROCEDURE O CUALQUIER SUM,
		HAY QUE MODIFICAR TAMBIEN EN LOS STORED PROCEDURE
		spPaymentsAvailability_GetDataByFilters4Grid
		spPaymentsAvailability_GetTotals
		spPaymentsAvailability_GetDataByFilters4GridAnalyticalReport
	*/
	--***************************************************************************

		BEGIN

			-- -----------------------------------
			-- Testing
			-- -----------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@pap_id		INT

				SELECT
					@comp_id	= 1,
					@pap_id		= 75
			*/
			-- -----------------------------------


			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
			-- -----------------------------------------------------------------------------

			SET DATEFORMAT 'YMD'






			-- Por las dudas recalcula el porcentaje de recepcion de las ordenes de compra
			EXEC spPurchaseOrderDetail_calculatePendingCoeficient @comp_id


			-- -------------------------------------------------------------------
			-- TABLA QUE CONTENDRÁ TODOS LOS VALORES A MOSTRAR
			-- -------------------------------------------------------------------
				CREATE TABLE #tmpPurchaseAvailability
				(
					Date				DATETIME,
					Payment_Pending		DECIMAL(19,2),
					Emmited				DECIMAL(19,2),
					PaymentsRequest		DECIMAL(19,2),
					PurchaseOrder		DECIMAL(19,2),
					Other				DECIMAL(19,2),
					Total				DECIMAL(19,2),
					Cash_ThirdCheques	DECIMAL(19,2),
					ID					INT NOT NULL IDENTITY (1, 1)
				)
			-- -------------------------------------------------------------------

			--ENSAMBLAMOS LAS FECHAS PARA INICIO Y FIN DE MES
			DECLARE
				@datefrom	DATETIME,
				@dateto		DATETIME

			SELECT
				@datefrom	= dbo.fnGetEnd_or_BeginOfDate(tpa.pap_fromDate,		'False'),
				@dateto		= dbo.fnGetEnd_or_BeginOfDate(tpa.pap_toDate,		'True')
				FROM tbPaymentsAvailability		tpa	WITH (NOLOCK)
				WHERE	tpa.comp_id = @comp_id	AND
						tpa.pap_id	= @pap_id

			DECLARE
				@year	INT,
				@month	INT

			SET @year	= YEAR(@datefrom)
			SET @month	= MONTH(@datefrom)

			-- ---------------------------------------------------------------------------------------------------
			-- OBTENGO LA CANTIDAD DE DÍAS QUE TIENE EL MES
			-- ---------------------------------------------------------------------------------------------------
				DECLARE
					--@AssembledDate	VARCHAR(20),
					@intDays		INT
				--SET @AssembledDate = CONVERT(VARCHAR,@year) + '-' + CONVERT(VARCHAR,@month) + '-' + '01'
--				SELECT
--					@intDays  = DATEDIFF(DAY, CONVERT(DATETIME,@AssembledDate), DATEADD(MONTH, 1, @AssembledDate))

				SELECT @intDays =  DATEPART(DAY, DATEADD(s,-1,DATEADD(mm, DATEDIFF(m,0,@datefrom)+1,0)))
				--SET @intDays  = DATEDIFF(DAY, @datefrom, @dateto + 1)
			-- ---------------------------------------------------------------------------------------------------

			-- --------------------------------------------------------------------------------------------------------------------------------------------------
			-- CARGAMOS LOS VALORES EN LA TABLA
			-- --------------------------------------------------------------------------------------------------------------------------------------------------
				DECLARE
					@intDayCounter	INT
				SET @intDayCounter = 1
				WHILE @intDayCounter <= @intDays
					BEGIN

						DECLARE
							@lDateFrom4InternalProcessing	DATETIME,
							@lDateTo4InternalProcessing		DATETIME,
							@Pending						DECIMAL(19,2),
							@Emmited						DECIMAL(19,2),
							@PaymentsRequest				DECIMAL(19,2),
							@PurchaseOrder					DECIMAL(19,2),
							@Other							DECIMAL(19,2)

						SET @lDateFrom4InternalProcessing	= dbo.fnGetEnd_or_BeginOfDate(	CONVERT(DATETIME, CONVERT(VARCHAR(10),@year)	+ '-' +
																							CONVERT(VARCHAR(10),@month)						+ '-' +
																							CONVERT(VARCHAR(10),@intDayCounter)),'False')

						SET @lDateTo4InternalProcessing		= dbo.fnGetEnd_or_BeginOfDate(	CONVERT(DATETIME, CONVERT(VARCHAR(10),@year)	+ '-' +
																							CONVERT(VARCHAR(10),@month)						+ '-' +
																							CONVERT(VARCHAR(10),@intDayCounter)),'True')

						SET @Pending			= 0
						SET @Emmited			= 0
						SET @PaymentsRequest	= 0
						SET @Other				= 0
						SET @PurchaseOrder		= 0

						--********************************************************************************************************************************
						--PENDIENTES
						--********************************************************************************************************************************
						--tbCommercialTransactions
--						SELECT
--							@Pending = 	SUM(ISNULL(tct.ct_total,0))
--						FROM tbCommercialTransactions		tct
--						WHERE	tct.comp_id		= @comp_id	AND
--								tct.sd_id		= 101		AND
--								tct.ct_ABalance > 0			AND
--								tct.ct_date		BETWEEN @lDateFrom4InternalProcessing AND @lDateTo4InternalProcessing


						SELECT
							@Pending = SUM(CASE WHEN tctpl.comp_id IS NULL THEN tct.ct_ABalance ELSE tctpl.ctpl_balance END)
							FROM tbCommercialTransactions							tct	WITH (NOLOCK)
								LEFT JOIN tbCommercialTransactionsPurchaseLoan		tctpl	WITH (NOLOCK)
									ON	tctpl.comp_id			= tct.comp_id		AND
										tctpl.ct_transaction	= tct.ct_transaction
							WHERE	tct.comp_id = @comp_id							AND
									tct.sd_id	= 101								AND	--101 = Factura
									CASE
										WHEN tctpl.comp_id IS NULL THEN tct.ct_ABalance
										ELSE	tctpl.ctpl_balance
									END > 0											AND --QUE EL BALANCE SEA MAYOR A CERO
									CASE
										WHEN tctpl.comp_id IS NULL THEN
											tct.ct_date
										ELSE
											tctpl.ctpl_payDate
									END	BETWEEN @lDateFrom4InternalProcessing AND @lDateTo4InternalProcessing

						--********************************************************************************************************************************

						--********************************************************************************************************************************
						--EMITIDOS
						--********************************************************************************************************************************
						--	tbEmmitedChecks
						SELECT
							@Emmited = SUM(ISNULL(tec.ec_Total,0))
							FROM tbCommercialTransactions					tct	WITH (NOLOCK)
								INNER JOIN tbEmmitedChecks					tec	WITH (NOLOCK)
									ON	tec.comp_id			= tct.comp_id	AND
										tec.ct_transaction	= tct.ct_transaction
							WHERE	tct.comp_id = @comp_id					AND
									tct.sd_id	= 106						AND
									tec.ec_PayDate	BETWEEN @lDateFrom4InternalProcessing AND @lDateTo4InternalProcessing

						--********************************************************************************************************************************

						--********************************************************************************************************************************
						--PAYMENTS REQUEST
						--********************************************************************************************************************************
						DECLARE
							@Emmited_PRTMP		DECIMAL(19,2),
							@BankTrans_PRTMP	DECIMAL(19,2),
							@ChkPortfolio_PRTMP	DECIMAL(19,2),
							@CashMov_PRTMP		DECIMAL(19,2),
							@TotalPR			DECIMAL(19,2)


						--	tbPaymentsRequest_EmmitedChecksTmp
						SELECT
							@Emmited_PRTMP  = ISNULL(SUM(ISNULL(tprect.ect_total,0)),0)
							FROM tbPaymentsRequest_EmmitedChecksTmp			tprect	WITH (NOLOCK)
								INNER JOIN tbPaymentsRequest				tpr	WITH (NOLOCK)
									ON	tpr.comp_id = tprect.comp_id		AND
										tpr.preq_id = tprect.preq_id
							WHERE	tprect.comp_id			= @comp_id		AND
									tprect.ect_payDate BETWEEN @lDateFrom4InternalProcessing	AND @lDateTo4InternalProcessing AND
									tpr.preq_isEmitted		= 'False'

									--tpr.preq_emittionDate	BETWEEN @lDateFrom4InternalProcessing	AND @lDateTo4InternalProcessing


						--tbPaymentsRequest_BankingTransactionsTmp
						SELECT
							@BankTrans_PRTMP = ISNULL(SUM(ISNULL(tprbtt.btt_total,0)),0)
							FROM tbPaymentsRequest_BankingTransactionsTmp			tprbtt	WITH (NOLOCK)
								INNER JOIN tbPaymentsRequest						tpr	WITH (NOLOCK)
									ON	tpr.comp_id = tprbtt.comp_id				AND
										tpr.preq_id = tprbtt.preq_id
							WHERE	tprbtt.comp_id				= @comp_id			AND
									tpr.preq_emittionDate	BETWEEN @lDateFrom4InternalProcessing	AND @lDateTo4InternalProcessing AND
									tpr.preq_isEmitted			= 'False'



						--tbPaymentsRequest_CheckPortfolio
						SELECT
							@ChkPortfolio_PRTMP = ISNULL(SUM(ISNULL(tcp1.chp_total,0)),0)
							FROM tbPaymentsRequest_CheckPortfolio					tprcp	WITH (NOLOCK)
								INNER JOIN tbCheckPortfolio							tcp1	WITH (NOLOCK)
									ON	tcp1.comp_id			= tprcp.comp_id		AND
										tcp1.chp_id				= tprcp.chp_id
								INNER JOIN tbPaymentsRequest						tpr	WITH (NOLOCK)
									ON	tpr.comp_id				= tprcp.comp_id		AND
										tpr.preq_id				= tprcp.preq_id
							WHERE	tcp1.comp_id				= @comp_id			AND
									tcp1.chp_PayDate		BETWEEN @lDateFrom4InternalProcessing	AND @lDateTo4InternalProcessing AND
									tpr.preq_isEmitted			= 'False'
									--tpr.preq_emittionDate	BETWEEN @lDateFrom4InternalProcessing	AND @lDateTo4InternalProcessing


						--tbPaymentsRequest_CashMovementsTMP
						SELECT
							@CashMov_PRTMP = ISNULL(SUM(ISNULL(tprcmt.cmt_amount,0)),0)
							FROM tbPaymentsRequest_CashMovementsTMP tprcmt	WITH (NOLOCK)
								INNER JOIN tbPaymentsRequest tpr	WITH (NOLOCK)
									ON	tpr.comp_id = tprcmt.comp_id AND
										tpr.preq_id = tprcmt.preq_id
							WHERE	tprcmt.comp_id			= @comp_id		AND
									tpr.preq_emittionDate	BETWEEN @lDateFrom4InternalProcessing AND @lDateTo4InternalProcessing AND
									tpr.preq_isEmitted		= 'False'



						--TOTAL FINAL
						SET @TotalPR = @Emmited_PRTMP + @BankTrans_PRTMP + @ChkPortfolio_PRTMP + @CashMov_PRTMP
						--********************************************************************************************************************************

						--********************************************************************************************************************************
						--PURCHASEORDER
						--********************************************************************************************************************************

						SELECT
							@PurchaseOrder = ISNULL(SUM( /*tpoh.poh_taxCoeficient*/   tpoh.poh_pendingCoeficient * ISNULL(tctpl.ctpl_balance,0) - ISNULL(tct.ct_total,0) ),0)
							FROM tbPurchaseOrderHeader							tpoh	WITH (NOLOCK)
								INNER JOIN tbCommercialTransactionsPurchaseLoan tctpl	WITH (NOLOCK)
									ON	tctpl.comp_id	= tpoh.comp_id			AND
										tctpl.bra_id	= tpoh.bra_id			AND
										tctpl.poh_id	= tpoh.poh_id
								LEFT JOIN tbPurchaseOrder_PaymentsRelations		AS tpopr	WITH(NOLOCK)
									ON	tpopr.comp_id		= tpoh.comp_id		AND
										tpopr.bra_id		= tpoh.bra_id		AND
										tpopr.poh_id		= tpoh.poh_id
								LEFT JOIN tbCommercialTransactions				AS tct		WITH(NOLOCK)
									ON	tct.comp_id			= tpopr.comp_id		AND
										tct.ct_transaction	= tpopr.ct_transaction
							WHERE	tpoh.comp_id		= @comp_id AND
									CASE
										WHEN tctpl.comp_id IS NULL THEN tpoh.poh_cd
										ELSE	tctpl.ctpl_payDate
									END	BETWEEN @lDateFrom4InternalProcessing	AND @lDateTo4InternalProcessing


						/*
						SELECT
							@PurchaseOrder =  ISNULL(SUM(ISNULL(tpod.pod_price * tpod.pod_qty,0)),0)
						FROM tbPurchaseOrderDetail							tpod
							INNER JOIN tbPurchaseOrderHeader				tpoh
								ON	tpoh.comp_id = tpod.comp_id				AND
									tpoh.poh_id = tpod.poh_id

						WHERE	tpod.comp_id	= @comp_id			AND
								tpoh.poh_cd		BETWEEN @lDateFrom4InternalProcessing	AND @lDateTo4InternalProcessing
						*/

						--********************************************************************************************************************************


						--********************************************************************************************************************************
						--OTROS GASTOS
						--********************************************************************************************************************************
						--tbCashFlowOtherConcepts
						SELECT
							@Other = ISNULL(SUM(ISNULL(tcfoc.cfo_credit,0)),0)
							FROM tbCashFlowOtherConcepts				tcfoc	WITH (NOLOCK)
							WHERE	tcfoc.comp_id	= @comp_id			AND
									tcfoc.cfo_date	BETWEEN @lDateFrom4InternalProcessing AND @lDateTo4InternalProcessing

						--********************************************************************************************************************************



						--********************************************************************************************************************************
						--ORDEN DE PAGO = TODO MENOS CHEQUES
						--********************************************************************************************************************************
						DECLARE
							@PaymentOrderTotal	DECIMAL(19,2)

						SELECT
							@PaymentOrderTotal  = ISNULL(SUM(tct.ct_total - ISNULL(vctpwec.ct_totalEC,0) - ISNULL(vctpwRE.ct_totalRET,0)),0)
							FROM tbCommercialTransactions											tct	WITH (NOLOCK)
									LEFT JOIN vwCommercialTransactions_PaymentsWithEmmitedCheque	vctpwec	WITH (NOLOCK)
									ON	vctpwec.comp_id			= tct.comp_id						AND
										vctpwec.ct_transaction	= tct.ct_transaction
									LEFT JOIN vwCommercialTransactions_PaymentsWithRetentions		vctpwRE WITH (NOLOCK)
										ON	vctpwRE.comp_id			= tct.comp_id AND
											vctpwRE.ct_transaction	= tct.ct_transaction

							WHERE	tct.comp_id		= @comp_id										AND
									tct.sd_id		IN(106)											AND
									--tct.ct_ABalance > 0								AND
									tct.ct_date BETWEEN @lDateFrom4InternalProcessing AND @lDateTo4InternalProcessing		AND
									(
										vctpwec.comp_id IS NULL			OR
										vctpwec.ct_totalEC <> tct.ct_total
									)



						--********************************************************************************************************************************

						--INSERTAMOS LOS VALORES EN LA TABLA TEMPORAL
						INSERT INTO #tmpPurchaseAvailability
						(
							Date,
							Payment_Pending,
							Emmited,
							PaymentsRequest,
							PurchaseOrder,
							Other,
							Total,
							Cash_ThirdCheques
						)
						SELECT
							@lDateFrom4InternalProcessing,
							@Pending,											--PENDIENTES DE PAGO
							@Emmited,											--EMITIDOS
							@TotalPR,											--SOLICITUD DE PAGOS
							ISNULL(@PurchaseOrder,0),							--PURCHASEORDERS
							--(ISNULL(@PurchaseOrder,0) - ISNULL(@Emmited,0)),	--PURCHASEORDERS - EMITIDOS (ANTERIOR LO DEJO POR SI LAS DUDAS)
							@Other,												--OTROS GASTOS
							ISNULL(@Pending,0) +
							ISNULL(@Emmited,0) +
							ISNULL(@Other,0),									--TOTAL

							@PaymentOrderTotal									--CASH_THIRDCHEQUES

						SET @intDayCounter = @intDayCounter + 1

					END
			-- --------------------------------------------------------------------------------------------------------------------------------------------------

			--ORDENES DE PAGO
			--SELECT
			--	tct.ct_ATotal
			--FROM tbCommercialTransactions				tct
			--WHERE	tct.comp_id		= @comp_id			AND
			--		tct.sd_id		= 106				AND
			--		tct.ct_date		BETWEEN @datefrom	AND @dateto

			-- ------------------------------------------------------------------
			-- BORRAMOS TODAS LAS ROWS QUE TENGAN TODOS LOS VALORES EN NULL
			-- YA QUE NO SUMAN AL MOMENTO DE MOSTRAR LOS DATOS
			-- SOLO GENERAN FILAS BASURA
			-- ------------------------------------------------------------------
				DELETE FROM #tmpPurchaseAvailability
				WHERE	Payment_Pending		IS NULL AND
						Emmited				IS NULL AND
						Other				IS NULL AND
						Total				IS NULL AND
						Cash_ThirdCheques	IS NULL
			-- ------------------------------------------------------------------


			-- --------------------------------------------------------------------------------------------------------------------
			-- ACTUALIZAMOS LOS VALORES QUE HAYAN QUEDADO EN NULL Y LOS PONEMOS EN CERO
			-- --------------------------------------------------------------------------------------------------------------------
				UPDATE #tmpPurchaseAvailability
				SET
					Payment_Pending		= CASE WHEN Payment_Pending		IS NULL		THEN 0 ELSE Payment_Pending		END,
					Emmited				= CASE WHEN Emmited				IS NULL		THEN 0 ELSE Emmited				END,
					Other				= CASE WHEN Other				IS NULL		THEN 0 ELSE Other				END,
					Cash_ThirdCheques	= CASE WHEN Cash_ThirdCheques	IS NULL		THEN 0 ELSE Cash_ThirdCheques	END,
					Total				= ISNULL(Emmited,0) + ISNULL(Other,0)


				DELETE FROM #tmpPurchaseAvailability
				WHERE	Payment_Pending		= 0 AND
						Emmited				= 0 AND
						PaymentsRequest		= 0 AND
						PurchaseOrder		= 0 AND
						Other				= 0 AND
						Cash_ThirdCheques	= 0
			-- --------------------------------------------------------------------------------------------------------------------



			-- SELECT FINAL
			SELECT
				' '						[ ],
				tmp.Date,
				tmp.Payment_Pending,
				tmp.Emmited,
				tmp.Other,
				tmp.Total,
				tmp.Cash_ThirdCheques,
				tmp.PaymentsRequest,
				CONVERT(DECIMAL(19,2), tmp.PurchaseOrder) [PurchaseOrder]
				FROM #tmpPurchaseAvailability tmp

			--TOTALES PARA LOS C1
			SELECT
				ISNULL(SUM(ISNULL(tmp.Payment_Pending,0)),0)		[Payment_Pending],
				ISNULL(SUM(ISNULL(tmp.Emmited,0)),0)				[Emmited],
				ISNULL(SUM(ISNULL(tmp.PaymentsRequest,0)),0)		[PaymentsRequest],
				ISNULL(SUM(ISNULL(tmp.Other,0)),0)					[Other],
				ISNULL(SUM(ISNULL(tmp.Cash_ThirdCheques,0)),0)		[Cash_ThirdCheques],
				ISNULL(SUM(ISNULL(tmp.PurchaseOrder,0)),0)			[PurchaseOrder]
				FROM #tmpPurchaseAvailability tmp

			-- --------------------------------------------------------------
			-- VACIAMOS LA TABLA TEMPORAL AL FINALIZAR LA DEVOLUCIÓN DE DATOS
			-- --------------------------------------------------------------
				DROP TABLE #tmpPurchaseAvailability
			-- --------------------------------------------------------------

		END

GO



CREATE PROCEDURE [dbo].[spPaymentsAvailability_GetDataById]
(
	@comp_id	INT,
	@pap_id		INT
)
AS
	SET NOCOUNT ON
		BEGIN
			SELECT
				tpa.comp_id,
				tpa.pap_id,
				tpa.pap_desc,
				tpa.pap_note,
				tpa.pap_fromDate,
				tpa.pap_toDate,
				tpa.pap_totalAvailable,
				tpa.pap_isClosed,
				tpa.brag_id

			FROM tbPaymentsAvailability		tpa
			WHERE	tpa.comp_id = @comp_id	AND
					tpa.pap_id	= @pap_id
		END
GO




CREATE PROCEDURE [dbo].[spPaymentsAvailability_GetEmmitedChecks]
(
	@comp_id	INT,
	@pap_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		SET DATEFORMAT 'YMD'



		-- -----------------------------------
		-- Testing
		-- -----------------------------------
/*
			DECLARE
				@comp_id	INT,
				@pap_id		INT

			SELECT
				@comp_id	= 1,
				@pap_id		= 33
--			DROP TABLE #tmpBankingAccountsForColumnTitles
--			DROP TABLE #tmpPurchaseAvailability
--			DROP TABLE #tmpPurchaseAvailability_ID
*/
		-- -----------------------------------




		-- ------------------------------------------------------------------------------------
		-- ENSAMBLAMOS LAS FECHAS PARA INICIO Y FIN DE MES
		-- ------------------------------------------------------------------------------------
		DECLARE
			@datefrom	DATETIME,
			@dateto		DATETIME

		SELECT
			@datefrom	= dbo.fnGetEnd_or_BeginOfDate(tpa.pap_fromDate,		'False'),
			@dateto		= dbo.fnGetEnd_or_BeginOfDate(tpa.pap_toDate,		'True')
			FROM tbPaymentsAvailability		tpa	WITH (NOLOCK)
			WHERE	tpa.comp_id = @comp_id	AND
					tpa.pap_id	= @pap_id
		-- ------------------------------------------------------------------------------------

		-- --------------------------------------------------
		-- CREAMOS LA TABLA QUE VA A CONTENER LAS COLUMNAS
		-- CON LOS DATOS FINALES
		CREATE TABLE #tmpBankingAccountsForColumnTitles
		(
			ID		INT NOT NULL IDENTITY,
			ba_id	INT,
			ba_desc	VARCHAR(500)
		)
		-- --------------------------------------------------

		-- -------------------------------------------------------------------------------------------------------------------------------------------------------
		-- QUIERO SABER CUANTAS CUENTAS BANCARIAS HAY EN EMMITED CHECKS
		-- PARA NO GENERAR COLUMNAS INNECESARIAS
		-- -------------------------------------------------------------------------------------------------------------------------------------------------------
		INSERT INTO #tmpBankingAccountsForColumnTitles
		(
			ba_id,
			ba_desc
		)
		SELECT
				tba.ba_id,
				tba.ba_desc
			FROM tbEmmitedChecks					tec	WITH (NOLOCK)
				INNER JOIN tbBankingAccounts		tba	WITH (NOLOCK)
					ON	tba.comp_id = tec.comp_id	AND
						tba.ba_id	= tec.ba_id
		GROUP BY tba.ba_desc, tba.ba_id
		ORDER BY tba.ba_id ASC

		-- -------------------------------------------------------------------------------------------------------------------------------------------------------

		-- -------------------------------------------------------------------
		-- CREAMOS LA TABLA EN DONDE SE VAN A GUARDAR LOS DATOS
		-- AL INICIO SOLO CARGAMOS LOS CAMPOS QUE POR DEFECTO SABEMOS
		-- QUE VAMOS A TENER
		-- -------------------------------------------------------------------
			CREATE TABLE #tmpPurchaseAvailability
			(
				Date	DATETIME DEFAULT NULL
			)
		-- -------------------------------------------------------------------

		-- -------------------------------------------------------------------
		-- TABLA DONDE SE GUARDA EL ID CON EL CAMPO EN 0 PARA SER ACTUALIZADO
		-- -------------------------------------------------------------------
			CREATE TABLE #tmpPurchaseAvailability_ID
			(
				ID	INT
			)
		-- -------------------------------------------------------------------

		-- VARIABLES DE TRABAJO
		DECLARE
			@lIntRowCount	INT,	--VARIABLE PARA EL BUCLE QUE VA A CONTAR LA CANTIDAD DE CUENTAS BANCARIAS
			@lIntBARowCount INT		--TOTAL DE CUENTAS BANCARIAS

		SET @lIntRowCount = 1

		SELECT
			@lIntBARowCount = COUNT(*)
		FROM #tmpBankingAccountsForColumnTitles

		--GENERAMOS LAS COLUMNAS DE LA TABLA POR CADA CUENTA BANCARIA
		WHILE @lIntRowCount <= @lIntBARowCount
		BEGIN

			DECLARE
				@lStrBA_DESC	VARCHAR(200),
				@lStrBA_ID		INT
			SET @lStrBA_DESC	= ''
			SET @lStrBA_ID		= 0

			SELECT
					--@lStrBA_DESC  = REPLACE(REPLACE(tmp.ba_desc,' ','_'),'.','_')
					@lStrBA_ID	= tmp.ba_id
				FROM #tmpBankingAccountsForColumnTitles	tmp
				WHERE tmp.ID = @lIntRowCount

			DECLARE @TableMod	VARCHAR(500)
			--SET @TableMod = 'ALTER TABLE #tmpPurchaseAvailability ADD [z_'+ CAST(@lStrBA_DESC AS NVARCHAR(200)) +   '] NVARCHAR(100) DEFAULT ''0'''
			SET @TableMod = 'ALTER TABLE #tmpPurchaseAvailability ADD [z_'+ CAST(@lStrBA_ID AS NVARCHAR(200)) +   '] decimal(25,2) DEFAULT ''0'''
			EXEC (@TableMod)

			SET @lIntRowCount = @lIntRowCount + 1

		END

		--LE AGREGAMOS UN CAMPO ID (IDENTITY) AL FINAL PARA OPERAR CON MAYOR COMODIDAD DENTRO DEL CURSOR
		DECLARE @TableMod2 as VARCHAR(500)
		SET @TableMod2 = 'ALTER TABLE #tmpPurchaseAvailability ADD [ID] INT NOT NULL IDENTITY (1, 1)'
		EXEC (@TableMod2)

		-- -------------------------------------------
		-- VARIABLES DE TRABAJO PARA EL CURSOR
		-- -------------------------------------------
			DECLARE
				@day		INT,
				@ba_desc	VARCHAR(200),
				@ba_id		INT,
				@em_date	DATETIME,
				@data		VARCHAR(200),
				@ID			INT
		-- -------------------------------------------

		DECLARE @CURSOR_GENERATEROWS CURSOR
			SET @CURSOR_GENERATEROWS = CURSOR LOCAL FAST_FORWARD
			FOR

				SELECT
					--DAY(tec.ec_EmissionDate),
					DAY(tec.ec_PayDate),
					--REPLACE(REPLACE(tba.ba_desc,' ','_'),'.','_')				[ba_desc],
					tba.ba_id,
					dbo.fnGetEnd_or_BeginOfDate(tec.ec_PayDate,'False')			[ec_PayDate],
					--dbo.fnGetEnd_or_BeginOfDate(tec.ec_EmissionDate,'False')	[ec_EmissionDate],
					CONVERT(DECIMAL(24,2),SUM(ISNULL(tec.ec_Total,0)))			[ec_Total]

					FROM tbEmmitedChecks							tec	WITH (NOLOCK)
					INNER JOIN tbCommercialTransactions				tct	WITH (NOLOCK)
						ON	tct.comp_id			= tec.comp_id		AND
							tct.ct_transaction	= tec.ct_transaction
					INNER JOIN tbBankingAccounts					tba	WITH (NOLOCK)
						ON	tba.comp_id			= tec.comp_id		AND
							tba.ba_id			= tec.ba_id
					WHERE	tec.comp_id			= @comp_id AND
							tec.ec_PayDate		BETWEEN @datefrom AND @dateto

				GROUP BY tec.ec_PayDate, tba.ba_id, tec.ec_PayDate
				ORDER BY tec.ec_PayDate ASC

				OPEN @CURSOR_GENERATEROWS
				FETCH NEXT FROM @CURSOR_GENERATEROWS
					INTO
						@day,
						--@ba_desc,
						@ba_id,
						@em_date,
						@data
			WHILE @@FETCH_STATUS = 0
				BEGIN

					TRUNCATE TABLE #tmpPurchaseAvailability_ID
						SET @ID		= NULL
						DECLARE
							@Insert				VARCHAR(2000),
							@Update				VARCHAR(2000),
							@InsertIntoTBPA_ID	VARCHAR(2000)

						SET @Insert				= ''
						SET @Update				= ''
						SET @InsertIntoTBPA_ID	= ''

						--OBTENEMOS EL REGISTRO QUE TIENE EL VALOR EN CERO PARA ACTUALIZAR O EN SU DEFECTO INSERTAR
							SELECT
								@InsertIntoTBPA_ID = ('INSERT INTO #tmpPurchaseAvailability_ID (ID) SELECT TOP 1 tmp.ID FROM #tmpPurchaseAvailability tmp WHERE tmp.z_' + CONVERT(VARCHAR(200),REPLACE(REPLACE(@ba_id,' ','_'),'.','_')) + ' = ''0'' AND DATE = ' + '''' + CONVERT(VARCHAR(30),@em_date) + '''' + ' ORDER BY tmp.ID ASC')
								EXEC (@InsertIntoTBPA_ID)
							--RECUPERAMOS EL ID EN CASO DE HABERSE INSERTADO O ENCONTRADO EL VALOR
							SELECT
								@ID = ID
							FROM #tmpPurchaseAvailability_ID


							IF EXISTS (SELECT TOP 1 1 FROM #tmpPurchaseAvailability_ID)
								BEGIN
									SELECT
										@Update = 'UPDATE #tmpPurchaseAvailability SET z_' + CONVERT(VARCHAR(200),REPLACE(REPLACE(@ba_id,' ','_'),'.','_')) + ' = ''' + CONVERT(NVARCHAR(200),@data) + ''' WHERE ID = ' + CONVERT(VARCHAR(200),@ID)
									EXEC (@Update)
								END
							ELSE
								BEGIN
									SELECT
										@Insert = 'INSERT INTO #tmpPurchaseAvailability (' + 'z_' + CONVERT(VARCHAR(200),REPLACE(REPLACE(@ba_id,' ','_'),'.','_')) + ',Date' + ') VALUES(''' + CONVERT(VARCHAR(200),@data) + ''',''' + CONVERT(VARCHAR(30),@em_date) + ''')'
									EXEC (@Insert)
								END


					FETCH NEXT FROM @CURSOR_GENERATEROWS
						INTO
							@day,
							--@ba_desc,
							@ba_id,
							@em_date,
							@data
				END
			CLOSE @CURSOR_GENERATEROWS
		DEALLOCATE @CURSOR_GENERATEROWS


		-- SELECT FINAL QUE MUESTRA LOS DATOS CARGADOS EN LA TABLA Y POSTERIOR ELIMINACIÓN DE LAS TABLAS TEMPORALES
			SELECT
				' '	[ ],
				*
				FROM #tmpPurchaseAvailability


	DROP TABLE #tmpBankingAccountsForColumnTitles
	DROP TABLE #tmpPurchaseAvailability
	DROP TABLE #tmpPurchaseAvailability_ID


	END




















GO




CREATE PROCEDURE [dbo].[spPaymentsAvailability_GetTotals]
(
	@comp_id	INT,
	@pap_id		INT
)
AS

	SET NOCOUNT ON

	--***************************************************************************
	/*
		SI SE MODIFICA ALGÚN SELECT DE ESTE STORED PROCEDURE O CUALQUIER SUM,
		HAY QUE MODIFICAR TAMBIEN EN LOS STORED PROCEDURE
		spPaymentsAvailability_GetDataByFilters4GridTotalsView
		spPaymentsAvailability_GetDataByFilters4Grid
		spPaymentsAvailability_GetDataByFilters4GridAnalyticalReport
	*/
	--***************************************************************************

		BEGIN

			SET DATEFORMAT 'YMD'

			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
			-- -----------------------------------------------------------------------------



			-- -----------------------------------
			-- Testing
			-- -----------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@pap_id		INT

				SELECT
					@comp_id	= 1,
					@pap_id		= 75
			*/
			-- -----------------------------------




			-- *************************************************************************************
			-- ENSAMBLAMOS LAS FECHAS PARA INICIO Y FIN DE MES
			-- *************************************************************************************
				DECLARE
					@datefrom	DATETIME,
					@dateto		DATETIME

				SELECT
					@datefrom	= dbo.fnGetEnd_or_BeginOfDate(tpa.pap_fromDate,		'False'),
					@dateto		= dbo.fnGetEnd_or_BeginOfDate(tpa.pap_toDate,		'True')

				FROM tbPaymentsAvailability		tpa
				WHERE	tpa.comp_id = @comp_id	AND
						tpa.pap_id	= @pap_id
			-- *************************************************************************************

			-- *************************************************************************************
			-- VARIABLES DE TRABAJO ( TOTALES )
			-- *************************************************************************************
				DECLARE
					@lDecFacturasYOrdenesDePago		DECIMAL(19,2),
					@lDecEmmitedCheckes				DECIMAL(19,2),
					@lDecPurchaseOrders				DECIMAL(19,2),
					@lDecPR_EmmitedChecksTmp		DECIMAL(19,2),
					@lDecPR_CheckPortfolio			DECIMAL(19,2),
					@lDecPR_BankingTransactionsTmp	DECIMAL(19,2),
					@lDecPR_CashMovementsTMP		DECIMAL(19,2),
					@lDecTOTAL						DECIMAL(19,2)

				SET @lDecFacturasYOrdenesDePago		= 0
				SET @lDecEmmitedCheckes				= 0
				SET @lDecPurchaseOrders				= 0
				SET @lDecPR_EmmitedChecksTmp		= 0
				SET @lDecPR_CheckPortfolio			= 0
				SET @lDecPR_BankingTransactionsTmp	= 0
				SET @lDecPR_CashMovementsTMP		= 0
				SET @lDecTOTAL						= 0

			-- *************************************************************************************

			-- FACTURAS
			SELECT
				@lDecFacturasYOrdenesDePago = ISNULL(SUM(CASE WHEN tctpl.comp_id IS NULL THEN ISNULL(tct.ct_ABalance,0) ELSE ISNULL(tctpl.ctpl_balance,0) END),0)			--VALOR
			FROM tbCommercialTransactions							tct			WITH (NOLOCK)

				LEFT JOIN tbCommercialTransactionsPurchaseLoan		tctpl	WITH (NOLOCK)
					ON	tctpl.comp_id			= tct.comp_id		AND
						tctpl.ct_transaction	= tct.ct_transaction

			WHERE	tct.comp_id = @comp_id							AND
					tct.sd_id	IN(101)							AND
					CASE
						WHEN tctpl.comp_id IS NULL THEN tct.ct_date
						ELSE	tctpl.ctpl_payDate
					END	BETWEEN @datefrom AND @dateto				AND
					CASE
						WHEN tctpl.comp_id IS NULL THEN tct.ct_ABalance
						ELSE	tctpl.ctpl_balance
					END > 0											--QUE EL BALANCE SEA MAYOR A CERO


			--ORDEN DE PAGO = TODO MENOS CHEQUES
			DECLARE
				@PaymentOrderTotal	DECIMAL(19,2)

			SELECT
				@PaymentOrderTotal  = ISNULL(SUM(tct.ct_total - ISNULL(vctpwec.ct_totalEC,0) - ISNULL(vctpwRE.ct_totalRET,0)),0)
			FROM tbCommercialTransactions							tct	WITH (NOLOCK)
				LEFT JOIN vwCommercialTransactions_PaymentsWithEmmitedCheque	vctpwec	WITH (NOLOCK)
					ON	vctpwec.comp_id			= tct.comp_id AND
						vctpwec.ct_transaction	= tct.ct_transaction
				LEFT JOIN vwCommercialTransactions_PaymentsWithRetentions		vctpwRE WITH (NOLOCK)
					ON	vctpwRE.comp_id			= tct.comp_id AND
						vctpwRE.ct_transaction	= tct.ct_transaction

			WHERE	tct.comp_id		= @comp_id						AND
					tct.sd_id		IN(106)							AND
					--tct.ct_ABalance > 0								AND
					tct.ct_date BETWEEN @datefrom AND @dateto		AND
					(
						vctpwec.comp_id IS NULL			OR
						vctpwec.ct_totalEC <> tct.ct_total
					)


			-- EMMITED CHECKES
			SELECT
				@lDecEmmitedCheckes = ISNULL(SUM(ISNULL(tec.ec_Total,0)),0)
			FROM tbCommercialTransactions					tct	WITH (NOLOCK)
				INNER JOIN tbEmmitedChecks					tec	WITH (NOLOCK)
					ON	tec.comp_id			= tct.comp_id	AND
						tec.ct_transaction	= tct.ct_transaction
			WHERE	tct.comp_id			= @comp_id			AND
					tct.sd_id			IN (106)			AND
					tct.ct_date			BETWEEN @datefrom	AND @dateto


			-- PURCHASEORDER
			SELECT
				@lDecPurchaseOrders = ISNULL(SUM( /*tpoh.poh_taxCoeficient **/ tpoh.poh_pendingCoeficient * ISNULL(tctpl.ctpl_balance,0) - ISNULL(tct.ct_total,0)  ),0)


			FROM tbPurchaseOrderHeader								tpoh	WITH (NOLOCK)
				INNER JOIN tbCommercialTransactionsPurchaseLoan		tctpl	WITH (NOLOCK)
					ON	tctpl.comp_id		= tpoh.comp_id			AND
						tctpl.bra_id		= tpoh.bra_id			AND
						tctpl.poh_id		= tpoh.poh_id
				LEFT JOIN tbPurchaseOrder_PaymentsRelations			AS tpopr	WITH(NOLOCK)
					ON	tpopr.comp_id		= tpoh.comp_id			AND
						tpopr.bra_id		= tpoh.bra_id			AND
						tpopr.poh_id		= tpoh.poh_id
				LEFT JOIN tbCommercialTransactions					AS tct		WITH(NOLOCK)
					ON	tct.comp_id			= tpopr.comp_id			AND
						tct.ct_transaction	= tpopr.ct_transaction
			WHERE	tpoh.comp_id		= @comp_id AND
					CASE
						WHEN tctpl.comp_id IS NULL THEN tpoh.poh_cd
						ELSE	tctpl.ctpl_payDate
					END	BETWEEN @datefrom	AND @dateto



--			SELECT
--				@lDecPurchaseOrders = ISNULL(SUM(ISNULL(tpod.pod_price,0)),0)
--			FROM tbPurchaseOrderDetail							tpod
--				INNER JOIN tbPurchaseOrderHeader				tpoh
--					ON	tpoh.comp_id = tpod.comp_id				AND
--						tpoh.bra_id = tpod.bra_id				AND
--						tpoh.poh_id = tpod.poh_id
--
--			WHERE	tpod.comp_id	= @comp_id			AND
--					tpoh.poh_cd		BETWEEN @datefrom	AND @dateto




			--PaymentsRequest_EmmitedChecksTmp
			SELECT
				@lDecPR_EmmitedChecksTmp = ISNULL(SUM(ISNULL(tprect.ect_total,0)),0)
			FROM tbPaymentsRequest_EmmitedChecksTmp			tprect	WITH (NOLOCK)
					INNER JOIN tbPaymentsRequest				tpr	WITH (NOLOCK)
						ON	tpr.comp_id = tprect.comp_id		AND
							tpr.preq_id = tprect.preq_id
				WHERE	tprect.comp_id			= @comp_id		AND
						tpr.preq_emittionDate	BETWEEN @datefrom	AND @dateto AND
						tpr.preq_isEmitted		= 'False'


			--CHEQUES EN CARTERA
			SELECT
				@lDecPR_CheckPortfolio = ISNULL(SUM(ISNULL(tcp1.chp_total,0)),0)
			FROM tbPaymentsRequest_CheckPortfolio						tprcp	WITH (NOLOCK)
					INNER JOIN tbCheckPortfolio							tcp1	WITH (NOLOCK)
						ON	tcp1.comp_id			= tprcp.comp_id		AND
							tcp1.chp_id				= tprcp.chp_id
					INNER JOIN tbPaymentsRequest						tpr	WITH (NOLOCK)
						ON	tpr.comp_id				= tprcp.comp_id		AND
							tpr.preq_id				= tprcp.preq_id
				WHERE	tcp1.comp_id				= @comp_id			AND
						tpr.preq_emittionDate	BETWEEN @datefrom	AND @dateto AND
						tpr.preq_isEmitted			= 'False'

			--BANKING TRANSACTIONS
			SELECT
				@lDecPR_BankingTransactionsTmp = ISNULL(SUM(ISNULL(tprbtt.btt_total,0)),0)
			FROM tbPaymentsRequest_BankingTransactionsTmp				tprbtt	WITH (NOLOCK)
					INNER JOIN tbPaymentsRequest						tpr	WITH (NOLOCK)
						ON	tpr.comp_id = tprbtt.comp_id				AND
							tpr.preq_id = tprbtt.preq_id
				WHERE	tprbtt.comp_id				= @comp_id			AND
						tpr.preq_emittionDate	BETWEEN @datefrom	AND @dateto AND
						tpr.preq_isEmitted			= 'False'

			--CashMovements
			SELECT
				@lDecPR_CashMovementsTMP = ISNULL(SUM(ISNULL(tprcmt.cmt_amount,0)),0)
			FROM tbPaymentsRequest_CashMovementsTMP				tprcmt	WITH (NOLOCK)
					INNER JOIN tbPaymentsRequest				tpr	WITH (NOLOCK)
						ON	tpr.comp_id = tprcmt.comp_id		AND
							tpr.preq_id = tprcmt.preq_id
				WHERE	tprcmt.comp_id = @comp_id				AND
						tpr.preq_emittionDate	BETWEEN @datefrom AND @dateto AND
						tpr.preq_isEmitted		= 'False'


			SET @lDecTOTAL = @lDecFacturasYOrdenesDePago + @lDecPurchaseOrders + @PaymentOrderTotal + @lDecEmmitedCheckes + @lDecPR_EmmitedChecksTmp + @lDecPR_CheckPortfolio + @lDecPR_BankingTransactionsTmp + @lDecPR_CashMovementsTMP


			SELECT
				@lDecTOTAL		[TOTAL]

		END
GO



CREATE PROCEDURE spPaymentsAvailabilityAlertDays_DeleteData
(
	@comp_id	INT,
	@pap_id		INT,
	@date		DATETIME
)
AS
	SET NOCOUNT ON
		BEGIN
			DELETE FROM tbPaymentsAvailabilityAlertDays
			WHERE	comp_id = @comp_id	AND
					pap_id	= @pap_id	AND
					paa_cd	= @date
		END

GO




CREATE PROCEDURE spPaymentsAvailabilityAlertDays_GetDataById
(
	@comp_id	INT,
	@pap_id		INT,
	@date		DATETIME
)
AS

	SET NOCOUNT ON
		BEGIN
			/*
				DECLARE
					@comp_id	INT,
					@pap_id		INT,
					@date		DATETIME
				SELECT
					@comp_id	= 1,
					@pap_id		= 1,
					@date		= '07/01/2015'
			*/
			SET DATEFORMAT 'YMD'

			SELECT
				tpaad.comp_id,
				tpaad.pap_id,
				tpaad.paa_cd

			FROM tbPaymentsAvailabilityAlertDays	tpaad
			WHERE	tpaad.comp_id	= @comp_id		AND
					tpaad.pap_id	= @pap_id		AND
					tpaad.paa_cd	= @date

		END
GO



CREATE PROCEDURE spPaymentsAvailabilityAlertDays_InsertData
(
	@comp_id	INT,
	@pap_id		INT,
	@date		DATETIME
)
AS
	SET NOCOUNT ON
		BEGIN
			INSERT INTO tbPaymentsAvailabilityAlertDays
			(
				comp_id,
				pap_id,
				paa_cd
			)
			VALUES
			(
				@comp_id,
				@pap_id,
				@date
			)
		END



GO



CREATE PROCEDURE spPaymentsAvailabilityAlertDays_InsertDataOrDeleteData
(
	@comp_id	INT,
	@pap_id		INT,
	@date		DATETIME
)
AS
	SET NOCOUNT ON
		BEGIN
			SET DATEFORMAT 'YMD'
			IF EXISTS (SELECT 1 FROM tbPaymentsAvailabilityAlertDays tpaad WHERE tpaad.comp_id = @comp_id AND tpaad.pap_id = @pap_id AND tpaad.paa_cd = @date)
				BEGIN

					EXEC spPaymentsAvailabilityAlertDays_DeleteData @comp_id, @pap_id, @date

				END
			ELSE
				BEGIN
					INSERT INTO tbPaymentsAvailabilityAlertDays
					(
						comp_id,
						pap_id,
						paa_cd
					)
					VALUES
					(
						@comp_id,
						@pap_id,
						@date
					)
				END



		END



GO



