CREATE PROCEDURE [dbo].[spPaymentsRequest_CommercialTransactionsTMP_InsertData]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@preq_id				INT,
	@guid					UNIQUEIDENTIFIER
)
AS
	SET NOCOUNT ON

		BEGIN

			INSERT INTO tbPaymentsRequest_CommercialTransactionsTMP
			(
				comp_id,
				preq_id,
				-- preqt_id -- this column value is auto-generated,
				bra_id,
				ctct_transaction,
				ctct_total,
				ctct_origin,
				ctct_exchange,
				ctl_id
			)
			SELECT
				tctt.comp_id,
				@preq_id,
				tctt.bra_id,
				tctt.ctct_transaction,
				tctt.ctct_total,
				tctt.ctct_origin,
				tctt.ctct_exchange,
				tctt.ctl_id
			FROM tbCommercialTransactionsTmp	tctt
			LEFT JOIN tbPaymentsRequest_CommercialTransactionsTMP tmp
			ON	tmp.comp_id				= tctt.comp_id			AND
				tmp.ctct_transaction	= tctt.ctct_transaction
			WHERE	tctt.comp_id	= @comp_id	AND
					tctt.ctct_guid	= @guid		AND
					tmp.comp_id IS NULL	-- Si el comprobante seleccionado ya esta en otra transaccion no lo guarda!!!


		END

GO



CREATE PROCEDURE [dbo].[spPaymentsRequest_DeleteAllData]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@preq_id				INT
)
AS
	SET NOCOUNT ON

		BEGIN
			/*
			DECLARE
				@comp_id	INT,
				@preq_id	INT
			SELECT
				@comp_id	= 1,
				@preq_id	= 21
			*/

			DELETE FROM tbPaymentsRequest_CommercialTransactionsTMP						WHERE comp_id = @comp_id AND preq_id = @preq_id

			DELETE FROM tbPaymentsRequest_CashMovementsTMP								WHERE comp_id = @comp_id AND preq_id = @preq_id

			DELETE FROM tbPaymentsRequest_BankingTransactionsTmp						WHERE comp_id = @comp_id AND preq_id = @preq_id

			DELETE FROM tbPaymentsRequest_CommercialTransactionsOtherPaymentsDetailTmp	WHERE comp_id = @comp_id AND preq_id = @preq_id

			DELETE FROM tbPaymentsRequest_EmmitedChecksTmp								WHERE comp_id = @comp_id AND preq_id = @preq_id

			DELETE FROM tbPaymentsRequest_TaxMovementsTMP								WHERE comp_id = @comp_id AND preq_id = @preq_id

			DELETE FROM tbPaymentsRequest_CheckPortfolio								WHERE comp_id = @comp_id AND preq_id = @preq_id

		END
GO



CREATE PROCEDURE spPaymentsRequest_DeleteData
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@preq_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN

			--BORRAMOS TODOS LOS REGISTROS DE LAS TEMPORALES
			EXEC spPaymentsRequest_DeleteAllData
				@comp_id	= @comp_id,
				@lang_id	= @lang_id,
				@bra_id		= @bra_id,
				@prof_id	= @prof_id,
				@user_id	= @user_id,
				@preq_id	= @preq_id

			--UNA VEZ BORRADAS LAS TEMPORALES PROCEDEMOS A BORRAR LA HEADER
			DELETE FROM tbPaymentsRequest
			WHERE comp_id = @comp_id AND preq_id = @preq_id

		END


GO



CREATE PROCEDURE spPaymentsRequest_EmittedChecksTMP_InsertData
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@preq_id				INT,
	@guid					UNIQUEIDENTIFIER
)
AS
	SET NOCOUNT ON

		BEGIN

			INSERT INTO tbPaymentsRequest_EmmitedChecksTmp
			(
				comp_id,
				preq_id,
				-- preqec_id -- this column value is auto-generated,
				bra_id,
				ba_id,
				ect_number,
				ect_total,
				curr_id,
				ect_emissionDate,
				ect_payDate,
				ct_transaction,
				ect_note,
				ect_isCancelled,
				ect_isPaid,
				ect_isPrinted,
				ect_exchangeToBranchCurrency,
				ect_not_to_order,
				ect_PaymentFinalDate,
				ect_isDocument,
				ec_memo,
				ec_payto,
				ecct_id
			)
			SELECT
				tect.comp_id,
				@preq_id,
				--tect.ect_id,
				tect.bra_id,
				tect.ba_id,
				tect.ect_Number,
				tect.ect_Total,
				tect.curr_id,
				tect.ect_EmissionDate,
				tect.ect_PayDate,
				tect.ct_transaction,
				tect.ect_Note,
				tect.ect_isCancelled,
				tect.ect_isPaid,
				tect.ect_isPrinted,
				tect.ect_exchangeToBranchCurrency,
				tect.ect_not_to_order,
				tect.ect_PaymentFinalDate,
				tect.ect_isDocument,
				tect.ec_memo,
				tect.ec_payto,
				tect.ecct_id

			FROM tbEmmitedChecksTmp tect
			WHERE	tect.comp_id  = @comp_id AND
					tect.ect_guid = @guid

		END
GO



CREATE PROCEDURE [dbo].[spPaymentsRequest_GetDataByFilters]
(
	@comp_id				INT,
	@bra_id					INT,
	@supp_id				INT,
	@cn_id					INT,
	@isOtherPayment			INT,
	@isWithOutRetention		INT,
	@datefrom_lastUpdate	DATETIME,
	@dateto_lastUpdate		DATETIME,
	@intEmmitionStatus		INT,
	@OptionAuthorization    INT

)
AS


BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


			SET @datefrom_lastUpdate = dbo.fnGetEnd_or_BeginOfDate(@datefrom_lastUpdate,'False')
			SET @dateto_lastUpdate   = dbo.fnGetEnd_or_BeginOfDate(@dateto_lastUpdate,'True')

			SELECT
				ISNULL(tpr.preq_isEmitted,'False')	[ ],
				' '									[ ],
				tb.bra_desc,
				ts.supp_name,
				tpr.preq_emittionDate,
				tcn.cn_desc,
				tpr.preq_isOtherPayment,
				tpr.preq_OtherPaymentsTo,
				tpr.preq_isWithOutRetention,
				tpr.preq_fixNumber,
				tpr.preq_onAccount,
				tpr.preq_adjust,
				tpr.preq_note1,
				tpr.preq_note2,
				tpr.preq_note3,
				tpr.preq_note4,
				tpr.preq_cd,
				tpr.preq_isOK4Emittion											   [preq_isOK4Emittion],
				ISNULL(tu.user_lastname,'') + ',' + ISNULL(tu.user_firstname,'')   [user4Create],
				tpr.preq_lastUpdate,
				ISNULL(tu1.user_lastname,'') + ',' + ISNULL(tu1.user_firstname,'') [user4Update],
				ISNULL(tu2.user_lastname,'') + ',' + ISNULL(tu2.user_firstname,'') [user4Emittion],
				tpr.preq_id							[ID]

			FROM tbPaymentsRequest				tpr

				INNER JOIN tbSupplier			ts
				ON	ts.comp_id	= tpr.comp_id	AND
					ts.supp_id	= tpr.supp_id

				INNER JOIN tbCashNumbers		tcn
				ON	tcn.comp_id = tpr.comp_id	AND
					tcn.cn_id	= tpr.cn_id

				INNER JOIN tbBranch				tb
				ON	tb.comp_id	= tpr.comp_id	AND
					tb.bra_id	= tpr.bra_id

				LEFT JOIN tbUser tu
					ON tu.[user_id] = tpr.user_id4Create

				LEFT JOIN tbUser tu1
					ON tu1.[user_id] = tpr.user_id4LastUpdate

				LEFT JOIN tbUser tu2
					ON tu2.[user_id] = tpr.user_id4Emittion

			WHERE	tpr.comp_id			= @comp_id													AND
					tpr.bra_id			= @bra_id													AND
					(@supp_id			= -1 OR tpr.supp_id = @supp_id)								AND
					(@cn_id				= -1 OR tpr.cn_id	= @cn_id)								AND
					(@isOtherPayment	= -1 OR tpr.preq_isOtherPayment = @isOtherPayment)			AND
					(@OptionAuthorization	= -1 OR tpr.preq_isOK4Emittion = @OptionAuthorization)	AND
					(@isWithOutRetention= -1 OR tpr.preq_isWithOutRetention = @isWithOutRetention)	AND
					tpr.preq_emittionDate BETWEEN @datefrom_lastUpdate AND @dateto_lastUpdate		AND
					CASE
						WHEN @intEmmitionStatus = -1								 THEN 'True'
						WHEN @intEmmitionStatus = 0 AND tpr.preq_isEmitted = 'False' THEN 'True'
						WHEN @intEmmitionStatus = 1 AND tpr.preq_isEmitted = 'True'  THEN 'True'
						ELSE															  'False'
					END = 'True'

END
GO



CREATE PROCEDURE [dbo].[spPaymentsRequest_GetDataById]
(
	@comp_id	INT,
	@lang_id	INT,
	@preq_id	INT
)
AS
