				tpr.bra_id,
				tpr.supp_id,
				tpr.preq_cd,
				tpr.cn_id,
				tpr.preq_isOtherPayment,
				tpr.preq_isWithOutRetention,
				tpr.preq_fixNumber,
				tpr.preq_onAccount,
				tpr.preq_adjust,
				tpr.preq_lastUpdate	,
				tpr.preq_isOK4Emittion,
				tpr.preq_OtherPaymentsTo,
				tpr.tax_id,
				tpr.puco_id,
				tpr.preq_note1,
				tpr.preq_note2,
