				tpr.preq_note4,
				tpr.preq_isEmitted,
				tpr.preq_emittionDate

			FROM tbPaymentsRequest tpr	WITH (NOLOCK)

			WHERE	tpr.comp_id = @comp_id AND
					tpr.preq_id = @preq_id

		END
GO





CREATE PROCEDURE [dbo].[spPaymentsRequest_InsertAllData]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@preq_id				INT,
	@guid					UNIQUEIDENTIFIER
)
AS

	SET NOCOUNT ON

		BEGIN
			/*
			DECLARE
				@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@prof_id				INT,
				@user_id				INT,
				@preq_id				INT,
				@guid					UNIQUEIDENTIFIER

			SELECT
				@comp_id				= 1,
				@lang_id				= 2,
				@bra_id					= 1,
				@prof_id				= 1,
				@user_id				= 1,
				@preq_id				= 21,
				@guid					= 'a7e96ff8-5ea9-43c8-8673-535d59772db6'
			*/

			-- -------------------------------------------------------------------------------
			-- ANTES DE CARGAR LAS TABLAS NUEVAMENTE, BORRAMOS TODOS LOS DATOS ANTERIORES
			-- -------------------------------------------------------------------------------
			EXEC spPaymentsRequest_DeleteAllData
				@comp_id	= @comp_id,
				@lang_id	= @lang_id,
				@bra_id		= @bra_id,
				@prof_id	= @prof_id,
				@user_id	= @user_id,
				@preq_id	= @preq_id
			-- -------------------------------------------------------------------------------


			-- -------------------------------------------------------------------------------
			-- LUEGO INSERTAMOS TODOS LOS VALORES EN LAS TABLAS
			-- -------------------------------------------------------------------------------

			EXEC spPaymentsRequest_CommercialTransactionsTMP_InsertData
				@comp_id	= @comp_id,
				@lang_id	= @lang_id,
				@bra_id		= @bra_id,
				@prof_id	= @prof_id,
				@user_id	= @user_id,
				@preq_id	= @preq_id,
				@guid		= @guid

			EXEC spPaymentsRequest_CashMovementsTMP_InsertData
				@comp_id	= @comp_id,
				@lang_id	= @lang_id,
				@bra_id		= @bra_id,
				@prof_id	= @prof_id,
				@user_id	= @user_id,
				@preq_id	= @preq_id,
				@guid		= @guid

			EXEC spPaymentsRequest_CheckPortfolio_InsertData
				@comp_id	= @comp_id,
				@lang_id	= @lang_id,
				@bra_id		= @bra_id,
				@prof_id	= @prof_id,
				@user_id	= @user_id,
				@preq_id	= @preq_id,
				@guid		= @guid

			EXEC spPaymentsRequest_EmittedChecksTMP_InsertData
				@comp_id	= @comp_id,
				@lang_id	= @lang_id,
				@bra_id		= @bra_id,
				@prof_id	= @prof_id,
				@user_id	= @user_id,
				@preq_id	= @preq_id,
				@guid		= @guid

			EXEC spPaymentsRequest_BankingTransactionsTmp_InsertData
				@comp_id	= @comp_id,
				@lang_id	= @lang_id,
				@bra_id		= @bra_id,
				@prof_id	= @prof_id,
				@user_id	= @user_id,
				@preq_id	= @preq_id,
				@guid		= @guid

			EXEC spPaymentsRequest_CommercialTransactionsOtherPaymentsDetailTmp_InsertData
				@comp_id	= @comp_id,
				@lang_id	= @lang_id,
				@bra_id		= @bra_id,
				@prof_id	= @prof_id,
				@user_id	= @user_id,
				@preq_id	= @preq_id,
				@guid		= @guid

			EXEC spPaymentsRequest_TaxMovementsTMPInsertData
				@comp_id	= @comp_id,
				@lang_id	= @lang_id,
				@bra_id		= @bra_id,
				@prof_id	= @prof_id,
				@user_id	= @user_id,
				@preq_id	= @preq_id,
				@guid		= @guid



			-- -------------------------------------------------------------------------------

		END
GO



CREATE PROCEDURE [dbo].[spPaymentsRequest_InsertAllDataInTMPTables]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@preq_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS
	SET NOCOUNT ON

		BEGIN

			-------------------------------------------------------------------------------------------------------
			-- tbCommercialTransactionsTmp
			-------------------------------------------------------------------------------------------------------
			INSERT INTO tbCommercialTransactionsTmp
			(
				comp_id,
				-- ctct_id -- this column value is auto-generated,
				bra_id,
				ctct_guid,
				ctct_transaction,
				ctct_total,
				ctct_origin,
				ctct_exchange,
				ctl_id
			)
			SELECT
				tprctt.comp_id,
				tprctt.bra_id,
				@guid,
				tprctt.ctct_transaction,
				tprctt.ctct_total,
				tprctt.ctct_origin,
				tprctt.ctct_exchange,
				tprctt.ctl_id
			FROM tbPaymentsRequest_CommercialTransactionsTMP	tprctt
			INNER JOIN tbCommercialTransactions tct
				ON	tct.comp_id			= tprctt.comp_id AND
					tct.ct_transaction	= tprctt.ctct_transaction
			WHERE	tprctt.comp_id = @comp_id					AND
					tprctt.preq_id = @preq_id					AND
					tprctt.ctct_total <= tct.ct_ABalance
			-------------------------------------------------------------------------------------------------------



			-------------------------------------------------------------------------------------------------------
			-- tbCashMovementsTmp
			-------------------------------------------------------------------------------------------------------
			INSERT INTO tbCashMovementsTmp
			(
				comp_id,
				bra_id,
				cmt_guid,
				-- cmt_id -- this column value is auto-generated,
				ca_id,
				cmt_amount,
				curr_id,
				cmt_desc,
				cn_id,
				cmt_branchCurrencyExchange
			)
			SELECT
				tprcmt.comp_id,
				tprcmt.bra_id,
				@guid,
				tprcmt.ca_id,
				tprcmt.cmt_amount,
				tprcmt.curr_id,
				tprcmt.cmt_desc,
				tprcmt.cn_id,
				tprcmt.cmt_branchCurrencyExchange

			FROM tbPaymentsRequest_CashMovementsTMP tprcmt
			WHERE	tprcmt.comp_id = @comp_id		AND
					tprcmt.preq_id = @preq_id
			-------------------------------------------------------------------------------------------------------


			-------------------------------------------------------------------------------------------------------
			-- tbBankingTransactionsTmp
			-------------------------------------------------------------------------------------------------------
			INSERT INTO tbBankingTransactionsTmp
			(
				comp_id,
				-- bttmp_id -- this column value is auto-generated,
				btt_guid,
				ba_id,
				bra_id,
				btt_id,
				ec_id,
				chp_id,
				btt_total,
				curr_id,
				btt_imputationDate,
				btt_isConciliated,
				btt_isCancelled,
				ct_transaction,
				ccm_id,
				btt_note,
				btt_Number,
				v4c_id
			)
			SELECT
				tprbtt.comp_id,
				@guid,
				tprbtt.ba_id,
				tprbtt.bra_id,
				tprbtt.btt_id,
				tprbtt.ec_id,
				tprbtt.chp_id,
				tprbtt.btt_total,
				tprbtt.curr_id,
				tprbtt.btt_imputationDate,
				tprbtt.btt_isConciliated,
				tprbtt.btt_isCancelled,
				tprbtt.ct_transaction,
				tprbtt.ccm_id,
				tprbtt.btt_note,
				tprbtt.btt_Number,
				tprbtt.v4c_id

			FROM tbPaymentsRequest_BankingTransactionsTmp	tprbtt
			WHERE	tprbtt.comp_id = @comp_id				AND
					tprbtt.preq_id = @preq_id
			-------------------------------------------------------------------------------------------------------


			-------------------------------------------------------------------------------------------------------
			-- tbCommercialTransactionsOtherPaymentsDetail
			-------------------------------------------------------------------------------------------------------
			INSERT INTO tbCommercialTransactionsOtherPaymentsDetailTmp
				(comp_id,
			     ctopdt_guid,
			     ctopdt_desc,
			     ctopdt_total,
			     acc_count_id,
			 puco_id,
			     cc_code
			     )
			SELECT
				tprctopdt.comp_id,
				@guid,
				tprctopdt.ctopdt_desc,
				tprctopdt.ctoptd_total,
				tprctopdt.acc_count_id,
				tprctopdt.puco_id,
				tprctopdt.cc_code

				FROM tbPaymentsRequest_CommercialTransactionsOtherPaymentsDetailTmp tprctopdt
				INNER JOIN tbPaymentsRequest tpr
					ON	tpr.comp_id = tprctopdt.comp_id AND
						tpr.preq_id = tprctopdt.preq_id
				WHERE	tprctopdt.comp_id = @comp_id								AND
						tprctopdt.preq_id = @preq_id
			-------------------------------------------------------------------------------------------------------


			-------------------------------------------------------------------------------------------------------
			-- tbEmmitedChecksTmp
			-------------------------------------------------------------------------------------------------------
			INSERT INTO tbEmmitedChecksTmp
			(
				comp_id,
				ect_guid,
				-- ect_id -- this column value is auto-generated,
				bra_id,
				ba_id,
				ect_Number,
				ect_Total,
				curr_id,
				ect_EmissionDate,
				ect_PayDate,
				ct_transaction,
				ect_Note,
				ect_isCancelled,
				ect_isPaid,
				ect_isPrinted,
				ect_exchangeToBranchCurrency,
				ect_not_to_order,
				ect_PaymentFinalDate,
				ect_isDocument,
				ec_memo,
				ec_payto,
				ecct_id
			)
			SELECT
				tprect.comp_id,
				@guid,
				tprect.bra_id,
				tprect.ba_id,
				tprect.ect_number,
				tprect.ect_total,
				tprect.curr_id,
				tprect.ect_emissionDate,
				tprect.ect_payDate,
				tprect.ct_transaction,
				tprect.ect_note,
				tprect.ect_isCancelled,
				tprect.ect_isPaid,
				tprect.ect_isPrinted,
				tprect.ect_exchangeToBranchCurrency,
				tprect.ect_not_to_order,
				tprect.ect_PaymentFinalDate,
				tprect.ect_isDocument,
				tprect.ec_memo,
				tprect.ec_payto,
				tprect.ecct_id

			FROM tbPaymentsRequest_EmmitedChecksTmp tprect
			WHERE	tprect.comp_id = @comp_id		AND
					tprect.preq_id = @preq_id
			-------------------------------------------------------------------------------------------------------


			-------------------------------------------------------------------------------------------------------
			-- tbTaxMovementsTmp
			-------------------------------------------------------------------------------------------------------
			INSERT INTO tbTaxMovementsTmp
			(
				comp_id,
				bra_id,
				-- tmt_transaction -- this column value is auto-generated,
				tmt_guid,
				ct_transaction,
				it_transaction,
				tmt_cd,
				tax_id,
				tmt_total,
				percentaje,
				curr_id,
				tmt_docKindOf,
				tmt_docPointOfSale,
				tmt_docNumber,
				tmt_docDate,
				tmt_originalDocument,
				State_Id,
				Country_Id,
				tmt_originalDocumentTypeOf,
				isCalculated,
				puco_id,
				tmT_exchangeToBranchCurrency,
				tmt_subtotal,
				tmt_isEditingCD,
				pcm_id,
				pcmt_id,
				tis_id,
				tm_id_original
			)
			SELECT
				tprtmt.comp_id,
				tprtmt.bra_id,
				@guid,
				tprtmt.ct_transaction,
				tprtmt.it_transaction,
				tprtmt.tmt_cd,
				tprtmt.tax_id,
				tprtmt.tmt_total,
				tprtmt.percentaje,
				tprtmt.curr_id,
				tprtmt.tmt_docKindOf,
				tprtmt.tmt_docPointOfSale,
				tprtmt.tmt_docNumber,
				tprtmt.tmt_docDate,
				tprtmt.tmt_originalDocument,
				tprtmt.state_id,
				tprtmt.country_id,
				tprtmt.tmt_originalDocumentTypeOf,
				tprtmt.isCalculated,
				tprtmt.puco_id,
				tprtmt.tmt_exchangeToBranchCurrency,
				tprtmt.tmt_subtotal,
				tprtmt.tmt_isEditingCD,
				tprtmt.pcm_id,
				tprtmt.pcmt_id,
				tprtmt.tis_id,
				tprtmt.tm_id_original

			FROM tbPaymentsRequest_TaxMovementsTMP	tprtmt
			WHERE	tprtmt.comp_id = @comp_id		AND
					tprtmt.preq_id = @preq_id
			-------------------------------------------------------------------------------------------------------



			-------------------------------------------------------------------------------------------------------
			-- tbCheckPortfolio
			-------------------------------------------------------------------------------------------------------
			UPDATE tbCheckPortfolio
			SET
				chp_guid = @guid
			WHERE	comp_id = @comp_id AND
					chp_id	IN (SELECT tprcp.chp_id
			                    FROM tbPaymentsRequest_CheckPortfolio	tprcp
			                    WHERE	tprcp.comp_id	= @comp_id		AND
										tprcp.preq_id	= @preq_id)
			-------------------------------------------------------------------------------------------------------


		END



GO



CREATE PROCEDURE [dbo].[spPaymentsRequest_InsertData]
(
	@comp_id				INT,
	@bra_id					INT,
	@supp_id				INT,
	@cn_id					INT,
	@isOtherPayment			BIT,
	@isWithOutRetention		BIT,
	@fixNumber				NVARCHAR(20),
	@onAccount				DECIMAL(19,4),
	@adjust					DECIMAL(19,4),
	@user_id4Create			INT,
	@user_id4LastUpdate		INT,
	@isOK4Emittion			BIT,
	@isEmitted				BIT,
	@preq_OtherPaymentsTo   NVARCHAR(1000),
	@tax_id					INT,
	@puco_id				INT,
	@preq_note1				NVARCHAR(1000),
	@preq_note2				NVARCHAR(1000),
	@preq_note3				NVARCHAR(1000),
	@preq_note4				NVARCHAR(1000),
	@preq_emittionDate		DATETIME,
	@return_value			INT OUTPUT
)
As
	SET NOCOUNT ON

		BEGIN






			INSERT INTO tbPaymentsRequest
			(
				comp_id,
				bra_id,
				supp_id,
				preq_cd,
				cn_id,
				preq_isOtherPayment,
				preq_isWithOutRetention,
				preq_fixNumber,
				preq_onAccount,
				preq_adjust,
				preq_lastUpdate,
				user_id4Create,
				user_id4LastUpdate,
				preq_isOK4Emittion,
				preq_isEmitted,
				tax_id,
				puco_id,
				preq_note1,
				preq_note2,
				preq_note3,
				preq_note4,
				preq_OtherPaymentsTo,
				preq_emittionDate
			)
			VALUES
			(
				@comp_id,
				@bra_id,
				@supp_id,
				GETDATE(),
				@cn_id,
				@isOtherPayment,
				@isWithOutRetention,
				@fixNumber,
				@onAccount,
				@adjust,
				GETDATE(),
				@user_id4Create,
				@user_id4LastUpdate,
				@isOK4Emittion,
				@isEmitted,
				@tax_id,
				@puco_id,
				@preq_note1,
				@preq_note2,
				@preq_note3,
				@preq_note4,
				@preq_OtherPaymentsTo,
				@preq_emittionDate
			)
			SET @return_value = @@IDENTITY

		END


GO



CREATE PROCEDURE [dbo].[spPaymentsRequest_TaxMovementsTMPInsertData]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@preq_id				INT,
	@guid					UNIQUEIDENTIFIER
)
AS

	SET NOCOUNT ON

		BEGIN

			INSERT INTO tbPaymentsRequest_TaxMovementsTMP
			(
				comp_id,
				preq_id,
				bra_id,
				ct_transaction,
				it_transaction,
				tmt_cd,
				tax_id,
				tmt_total,
				percentaje,
				curr_id,
				tmt_docKindOf,
				tmt_docPointOfSale,
				tmt_docNumber,
				tmt_docDate,
				tmt_originalDocument,
				state_id,
				country_id,
				tmt_originalDocumentTypeOf,
				isCalculated,
				puco_id,
				tmt_exchangeToBranchCurrency,
				tmt_subtotal,
				tmt_isEditingCD,
				pcm_id,
				pcmt_id,
				tis_id,
				tm_id_original
			)
			SELECT
				ttmt.comp_id,
				@preq_id,
				ttmt.bra_id,
				--ttmt.tmt_transaction,
				ttmt.ct_transaction,
				ttmt.it_transaction,
				ttmt.tmt_cd,
				ttmt.tax_id,
				ttmt.tmt_total,
				ttmt.percentaje,
				ttmt.curr_id,
				ttmt.tmt_docKindOf,
				ttmt.tmt_docPointOfSale,
				ttmt.tmt_docNumber,
				ttmt.tmt_docDate,
				ttmt.tmt_originalDocument,
				ttmt.State_Id,
				ttmt.Country_Id,
				ttmt.tmt_originalDocumentTypeOf,
				ttmt.isCalculated,
				ttmt.puco_id,
				ttmt.tmT_exchangeToBranchCurrency,
				ttmt.tmt_subtotal,
				ttmt.tmt_isEditingCD,
				ttmt.pcm_id,
				ttmt.pcmt_id,
				ttmt.tis_id,
				ttmt.tm_id_original

			FROM tbTaxMovementsTmp				ttmt
			WHERE	ttmt.comp_id	= @comp_id	AND
					ttmt.tmt_guid	= @guid

		END
GO



CREATE PROCEDURE [dbo].[spPaymentsRequest_UpdateData]
(
	@comp_id			INT,
	@preq_id			INT,
	@supp_id			INT,
	@cn_id				INT,
	@isOtherPayment		BIT,
	@isWithOutRetention	BIT,
	@fixNumber			NVARCHAR(20),
	@onAccount			DECIMAL(19,4),
	@preq_adjust		DECIMAL(19,4),
	@isOK4Emittion		BIT,
	@user_id4LastUpdate INT,
	@preq_OtherPaymentsTo   NVARCHAR(1000),
	@tax_id					INT,
	@puco_id				INT,
	@preq_note1				NVARCHAR(1000),
	@preq_note2				NVARCHAR(1000),
	@preq_note3				NVARCHAR(1000),
	@preq_note4				NVARCHAR(1000),
	@preq_emittionDate		DATETIME
)
AS
	SET NOCOUNT ON

		BEGIN

			UPDATE tbPaymentsRequest
			SET
				supp_id					= @supp_id,
				cn_id					= @cn_id,
				preq_isOtherPayment		= @isOtherPayment,
				preq_isWithOutRetention = @isWithOutRetention,
				preq_fixNumber			= @fixNumber,
				preq_onAccount			= @onAccount,
				preq_adjust				= @preq_adjust,
				preq_lastUpdate			= GETDATE(),
				preq_isOK4Emittion		= @isOK4Emittion,
				user_id4LastUpdate		= @user_id4LastUpdate,
				preq_OtherPaymentsTo	= @preq_OtherPaymentsTo,
				tax_id					= @tax_id,
				puco_id					= @puco_id,
				preq_note1				= @preq_note1,
				preq_note2				= @preq_note2,
				preq_note3				= @preq_note3,
				preq_note4				= @preq_note4,
				preq_emittionDate		= @preq_emittionDate
			WHERE	comp_id				= @comp_id	AND
					preq_id				= @preq_id

		END
GO



CREATE PROCEDURE spPaymentsRequest_UpdateProcessAndEmittionData
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@preq_id	INT,
	@em_date	DATETIME
)
AS
	SET NOCOUNT ON

		BEGIN

			UPDATE tbPaymentsRequest
			SET
				user_id4LastUpdate	= @user_id,
				user_id4Emittion	= @user_id,
				preq_emittionDate	= @em_date,
				preq_isOK4Emittion	= 'True',
				preq_isEmitted		= 'True'

			WHERE	comp_id = @comp_id AND
					preq_id = @preq_id

			UPDATE tbPaymentsRequest_CheckPortfolio
			SET
				preqchp_isProcessed = 'True'
			WHERE	comp_id = @comp_id AND
					preq_id = @preq_id

		END

GO







CREATE PROCEDURE [dbo].[spPaymentsTmp_getDataByFilters]
(
	@lang_id			int,
	@guid				uniqueidentifier
)
as

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	set nocount on

	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------
	/*
	declare	@lang_id		int,
			@guid			uniqueidentifier

	select	@lang_id		=2,
			@guid			='e14ab4aa-91b3-4457-8cae-607975830ab2'
	*/
	-- -----------------------------------------------------------------------------


	declare @d int
	set		@d = 2


	select	' ' [ ], ' ' [ ],
			vct.guid,
			vct.description										[function],
			case vct.class
				when '1' then vct.[type]
				when '2' then vct.[type]
				when '3' then vct.[type]
				when '4' then vct.[type]
				when '5' then vct.[type]
			end													[type],
			convert(decimal(18,2),round(vct.amount,@d))			[amount],
			vct.currency,
			vct.emissionDate,
			vct.[Date],
			vct.[desc],
			vct.class + '-' + convert(varchar,vct.ID)			[ID2]

	from	vwPaymentsTmp		vct		WITH (NOLOCK)

	where	vct.guid	=	@guid
	and		vct.lang_id =	@lang_id


	ORDER BY vct.class,vct.Date

				--when '2' then (select ov.[optval_desc] from dbo.[tbsysOptionsValues] ov
				--				where ov.[optval_class]	= 28 and ov.[optval_id]	= vct.type and ov.[lang_id]	= @lang_id)


END
GO








CREATE PROCEDURE [dbo].[spPaymentsTmp_getDataToAccount]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@supp_id			int,
	@curr_id			int,
	@currExchange		decimal(19,6),
	@guid				UNIQUEIDENTIFIER,
	@user_id			int
)
AS

BEGIN


	set nocount ON

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
	declare	@comp_id			int,
			@lang_id			int,
			@bra_id				int,
			@supp_id			int,
			@curr_id			int,
			@currExchange		decimal(19,6),
			@guid				uniqueidentifier

	select	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@supp_id			=8103,
			@curr_id			=1,
			@currExchange		=3.4,
			@guid				='45b7f584-70ae-4d17-981d-392a3b8c75e9'
	*/
	-- ------------------------------------------------------

	declare @d int
	set		@d = 2


	select	' ' [1], ' ' [2], ' ' [3],
			dbo.fnGetCommercialTransactionDescription(ct.[comp_id],@lang_id,ct.[ct_transaction])	[doc],
			ct.[ct_date],
			convert(decimal(18,2),round(ct.[ct_total],@d))						[ct_total],
			convert(decimal(18,2),round(ct.[ct_ATotal],@d))						[ct_ATotal],
			convert(decimal(18,2),round(ct.[ct_ABalance],@d))					[ct_ABalance],
			convert(decimal(18,2),round(isnull(ctct.ctct_total,0),@d))			[aCtaTotal],
			sct.[curr_symbol],
			ct.[ct_ACurrencyExchange],
			convert(decimal(18,2),round(dbo.[fnGetExchange](@comp_id, ct.[ct_ABalance], ct.ct_ACurrency, ct.curr_id_transaction, 0, @currExchange, 0),@d)) [ct_Balance],
			ct.[ct_transaction]													[ID4]


	from	dbo.tbCommercialTransactions									ct				WITH (NOLOCK)

			left join dbo.[tbCommercialTransactionsTmp]						ctct			WITH (NOLOCK)
			on	ctct.comp_id					=	ct.[comp_id]
			and	ctct.ctct_transaction			=	ct.[ct_transaction]
			and	ctct.ctct_guid					=	@guid

			LEFT JOIN tbPaymentsRequest_CommercialTransactionsTMP tprctt
				ON	tprctt.comp_id			= ct.comp_id						AND
					tprctt.ctct_transaction = ct.ct_transaction

			inner join dbo.[vwCommercialTransactions_PaymentOnAccount]		VCTFS			WITH (NOLOCK)
			On	VCTFS.comp_id					=	ct.comp_id
			--and VCTFS.bra_id					=	ct.bra_id
			and VCTFS.ct_transaction			=	ct.ct_transaction

			inner join [tbsysCurrency]										sct				WITH (NOLOCK)
			on  sct.[curr_id]					=	ct.[curr_id_transaction]

			inner join	[tbBranch]											b1				WITH (NOLOCK)
			on	b1.[comp_id]					=	ct.[comp_id]
			and b1.[bra_id]						=	@bra_id

			INNER JOIN tbUsers4BranchFilter							vubf					WITH (NOLOCK)
			ON		vubf.comp_id			=  ct.comp_id
			AND		vubf.bra_id				=  ct.bra_id
			AND		vubf.[user_id]			=  @user_id

			INNER JOIN tbbranch												b2				WITH (NOLOCK)
				ON	b2.comp_id				= ct.comp_id AND
					b2.bra_id				= ct.bra_id

	where	--1 = 2 AND
			ct.[comp_id]						=	@comp_id
	and	    ct.[supp_id]						=	@supp_id
	and		ct.[curr_id_transaction]			=   b1.curr_id
	and     ct.[ct_Abalance]					<>	0
	and		ct.[ct_docNumber]					<>	''

	and		(
				(	b1.bra_PaymentsOfAllBranches	=	'True'		AND
					b2.curr_id						= @curr_id
				)
				OR
				(
						b1.bra_PaymentsOfAllBranches		=	'False'		AND
						ct.bra_id							=	@bra_id
				)
			)

	AND		NOT ct.sd_id IN  (56,66)			-- Recibos Anulados
	AND	   (ct.sd_id not BETWEEN 150 AND 199)	-- Cptes de Compra Anulados


	order by [aCtaTotal] desc, ct.[ct_payDate], [ID4]


END
GO








CREATE PROCEDURE [dbo].[spPaymentsTmp_getDataToPay]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@supp_id			int,
	@curr_id			int,
	@guid				UNIQUEIDENTIFIER,
	@user_id			int
)
AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on



	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------

	/*


	declare	@comp_id	int,
			@lang_id	int,
			@bra_id		int,
			@supp_id	int,
			@curr_id	int,
			@guid		uniqueidentifier,
			@user_id	int

	select	@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@supp_id	=8110,
			@curr_id	=1,
			@guid		='7FFEBB88-FEEC-4C36-A30D-36CF5D67BB10',
			@user_id	=1

	*/
	-- -----------------------------------------------------------------------------




	declare @d int
	set		@d = 2


	DECLARE @bra_POPCI		BIT

	SELECT	@bra_POPCI	=	'False'  --isnull(tb.bra_PaymentOnlyPayConfirmedInvoice,'False')   Se des-habilito por contar con nuevo modulo
		FROM	tbBranch		tb			WITH (NOLOCK)
		WHERE	tb.comp_id	=	@comp_id
		AND		tb.bra_id	=	@bra_id





	select	CASE	-- NO SE USA MAS!!!   se reemplaza por estados de dosumentos de Compra
				WHEN @bra_POPCI = 'True' THEN
					case
						when ct.ct_isAvailableForPayment = 'True' AND tprctt.comp_id IS NULL THEN 1
						ELSE 0
					END
				ELSE
					CASE
						WHEN  tprctt.comp_id IS NULL  OR tpr.preq_isEmitted = 'True' THEN	1
						ELSE								0
					END

			END [ ],
			dbo.fnGetItemTransactions(ct.comp_id,ct.ct_transaction)	 [ ],
			' ' [ ],
			dbo.fnGetCommercialTransactionDescription(ct.[comp_id],@lang_id,ct.[ct_transaction])	[doc],
			convert(decimal(18,2),round(		ct.[ct_total],		@d))							[ct_total],

			convert(decimal(18,2),round(		ct.[ct_ATotal],		@d))									[ct_ATotal],
			convert(decimal(18,2),round(		ct.[ct_ABalance],	@d))									[ct_ABalance],
			convert(decimal(18,2),round(isnull(	ctct.ctct_total,0),	@d))									[payTotal],
			convert(decimal(18,2),round(ISNULL(ct.[ct_ABalance],0) - isnull(	ctct.ctct_total,0),	@d))	[Balance],
			ct.[ct_payDate],		-- **KHKHddd Columna 12, OJO que explota si agregan algo ! ! !
			--scat.[curr_desc]																		[CustomerCurrency],
			dbo.fnGetMyExchange(ct.[ct_ACurrencyExchange])											[ct_ACurrencyExchange],
			s.[sm_name],
			b.[bra_desc],
			case
				when exists(SELECT TOP 1 1
								 from tbPurchaseDocumentsStatus tpds	WITH (NOLOCK)
								 where	tpds.comp_id		= @comp_id
								 and	tpds.bra_id			= @bra_id
								 and	tpds.ct_transaction = ct.ct_transaction
								 and	tpds.pds_isOk		= 'False') AND tprctt.comp_id IS NULL
																			then		0
				else																	1
			end																						[pds_isOk],
			isnull(tsa.suppa_name,'')																[suppa_name],
			ct.[ct_transaction]																		[ID1]

	--**ATENCION** , SI SE AGREGA UNA COLUMNA MAS EN EL SELECT AGREGARLA TAMBIEN EN [spPaymentsTmp_insertAllData]
	--				  PARA QUE NO DE ERROR XQ FALTA EN LA TABLA LA COLUMNA. - GA 16-08-2013

	-- Ver tambien el codigo de **KHKHddd  en wfmPayments


	from	dbo.tbCommercialTransactions								ct			WITH (NOLOCK)

			left join dbo.[tbCommercialTransactionsTmp]					ctct		WITH (NOLOCK)
			on	ctct.comp_id					=	ct.[comp_id]
			and	ctct.ctct_transaction			=	ct.[ct_transaction]
			and	ctct.ctct_guid					=	@guid

			LEFT JOIN tbPaymentsRequest_CommercialTransactionsTMP tprctt			WITH (NOLOCK)
			ON	tprctt.comp_id					= ct.comp_id						AND
				tprctt.ctct_transaction			= ct.ct_transaction

			LEFT JOIN tbPaymentsRequest									tpr			WITH (NOLOCK)
			ON	tpr.comp_id						= tprctt.comp_id					AND
				tpr.preq_id						= tprctt.preq_id

			inner join dbo.[vwCommercialTransactions_forPurchase]		VCTFS		WITH (NOLOCK)
			On	VCTFS.comp_id					=	ct.comp_id
			and VCTFS.bra_id					=	ct.bra_id
			and VCTFS.ct_transaction			=	ct.ct_transaction

			inner join [tbsysCurrency]									sct			WITH (NOLOCK)
			on  sct.[curr_id]					=	ct.[curr_id_transaction]

			inner join [tbsysCurrency]									scat		WITH (NOLOCK)
			on  scat.[curr_id]					=	ct.[ct_ACurrency]

			left join [tbSalesman]										s			WITH (NOLOCK)
			on	s.[comp_id]						=	ct.[comp_id]
			and	s.[sm_id]						=	ct.[sm_id]

			inner join	[tbBranch]										b			WITH (NOLOCK)
			on	b.[comp_id]						=	ct.[comp_id]
			and b.[bra_id]						=	ct.[bra_id]

			inner join	[tbBranch]										b1			WITH (NOLOCK)
			on	b1.[comp_id]					=	ct.[comp_id]
			and b1.[bra_id]						=	@bra_id

			INNER JOIN tbUsers4BranchFilter								vubf		WITH (NOLOCK)
			ON		vubf.comp_id				=  ct.comp_id
			AND		vubf.bra_id					=  ct.bra_id
			AND		vubf.[user_id]				=  @user_id

			LEFT JOIN tbSupplierAssociated								tsa			WITH (NOLOCK)
			ON		tsa.comp_id					=	ct.comp_id
			AND		tsa.suppa_id				=	ct.suppa_id



	where	ct.[comp_id]						=	@comp_id
	and	    ct.[supp_id]						=	@supp_id
	and		ct.[curr_id_transaction]			=   b1.curr_id

	and		VCTFS.[sd_isInBalance]				=	'True'
	and		VCTFS.[sd_isCredit]					=	'False'
	and		VCTFS.[sd_isReceipt]				=	'False'

	and     ct.[ct_Abalance]					<>	0
	and		ct.[ct_docNumber]					<>	''

	and		((IsNull(b1.bra_PaymentsOfAllBranches,'False')	=	'True'
			and ct.bra_id in (select bra_id from [tbBranch] WITH (NOLOCK) where curr_id = @curr_id)) or
			(IsNull(b1.bra_PaymentsOfAllBranches,'False')		=	'False'
			and ct.bra_id						=	@bra_id))




	order by [payTotal] desc, ct.[ct_payDate], [ID1]


END
GO







CREATE PROCEDURE [dbo].[spPaymentsTmp_insertAllData]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@supp_id			INT,
	@curr_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@origin				VARCHAR(1),
	@user_id			INT
)
AS

BEGIN



	set nocount on


-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
	/*
	declare	@comp_id	int,
			@lang_id	int,
			@bra_id		int,
			@supp_id	int,
			@curr_id	int,
			@guid		UNIQUEIDENTIFIER,
			@origin		varchar(1),
			@user_id	INT

	select	@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@supp_id	=8103,
			@curr_id	=1,
			@guid		='3d434091-1694-441d-a6dd-24a500caaf72',
			@origin		='h',
			@user_id	=1
	DROP TABLE #tmpDataToPay
	*/
-- ------------------------------------------------------

	CREATE TABLE #tmpDataToPay
	(
		column1					NVARCHAR(4000),
		column2					NVARCHAR(4000),
		column3					NVARCHAR(4000),
		doc						VARCHAR(150),
		ct_total				DECIMAL(18,2),
		--BranchCurrency			VARCHAR(50),
		ct_ATotal				DECIMAL(18,2),
		ct_ABalance				DECIMAL(18,2),
		payTotal				DECIMAL(18,2),
		ctBalance2Pay			DECIMAL(19,2),
		ct_payDate				DATETIME,
		--CustomerCurrency		VARCHAR(50),
		ct_ACurrencyExchange	DECIMAL(18,2),
		sm_name					VARCHAR(150),
		bra_desc				VARCHAR(150),
		pds_isOk				BIT,
		suppa_name				VARCHAR(150),
		ID						INT
	)


	INSERT INTO #tmpDataToPay
		EXEC spPaymentsTmp_getDataToPay
                          		@comp_id,
                          		@lang_id,
                          		@bra_id,
                          		@supp_id,
                          		@curr_id,
                          		@guid,
                          		@user_id



	DECLARE 	@lcolumn1					NVARCHAR(4000),
				@lcolumn2					NVARCHAR(4000),
				@lcolumn3					NVARCHAR(4000),
				@ldoc						VARCHAR(150),
				@lct_total					DECIMAL(18,2),
				@lBranchCurrency			VARCHAR(150),
				@lct_ATotal					DECIMAL(18,2),
				@lct_ABalance				DECIMAL(18,2),
				@lpayTotal					DECIMAL(18,2),
				@lct_payDate				DATETIME,
				@lCustomerCurrency			VARCHAR(50),
				@lct_ACurrencyExchange		DECIMAL(18,2),
				@lsm_name					VARCHAR(150),
				@lbra_desc					VARCHAR(150),
				@lID					    INT,
				@lsuppa_name				VARCHAR(150),
				@lreturn_value 				INT


	DECLARE cursor_PT_iAD_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT 	doc,
				ct_total,
				--BranchCurrency,
				ct_ATotal,
				ct_ABalance,
				payTotal,
				ct_payDate,
				--CustomerCurrency,
				ct_ACurrencyExchange,
				sm_name,
				bra_desc,
				ID,
				suppa_name
			FROM #tmpDataToPay
		WHERE pds_isOk = 1   -- Que NO tengan autorizaciones de pago pendientes!!!


	OPEN cursor_PT_iAD_data

	fetch cursor_PT_iAD_data into
							@ldoc,
							@lct_total,
							--@lBranchCurrency,
							@lct_ATotal,
							@lct_ABalance,
							@lpayTotal,
							@lct_payDate,
							--@lCustomerCurrency,
							@lct_ACurrencyExchange,
							@lsm_name,
							@lbra_desc,
							@lID,
							@lsuppa_name


	while @@FETCH_STATUS = 0
	BEGIN


		EXEC spCommercialTransactionsTmp_insertData
			@comp_id,
			@bra_id,
			@guid,
			@lID,
			@lct_ABalance,
			@origin,
			@lct_ACurrencyExchange,
			@lreturn_value

		fetch cursor_PT_iAD_data
			into	@ldoc,
					@lct_total,
					--@lBranchCurrency,
					@lct_ATotal,
					@lct_ABalance,
					@lpayTotal,
					@lct_payDate,
					--@lCustomerCurrency,
					@lct_ACurrencyExchange,
					@lsm_name,
					@lbra_desc,
					@lID,
					@lsuppa_name

	END

	close cursor_PT_iAD_data
	deallocate cursor_PT_iAD_data


	--DROP TABLE #tmpDataToPay

END
GO







CREATE PROCEDURE [dbo].[spPresentation_GetCombo]
(
	@comp_id			int,
	@bra_id				int
)
as
set nocount ON


/*
DECLARE 	@comp_id			int,
			@bra_id				int
SELECT 		@comp_id			=1,
			@bra_id				=-1
*/



select		pres_id			[id],
			pres_desc		[desc]

from		dbo.tbPresentation

where		comp_id			= @comp_id
and		    (@bra_id		= -1 OR
			 bra_id			= @bra_id OR
			 bra_id			IS null)

order by	pres_desc















