CREATE PROCEDURE [dbo].[spPresentation_getData4WebSite]
(
	@comp_id				INT,
    @subcat_id				INT,
    @brand_id				INT,
	@stor_id				INT,
	@showzerostock			BIT,
	@potentialstocklimit	INT
)
AS

SET NOCOUNT ON


/*
DECLARE @comp_id		INT,
		@subcat_id		INT,
		@brand_id		INT,
		@stor_id		INT,
		@showzerostock	BIT,
		@potentialstocklimit	INT
SELECT	@comp_id		= 1,
		@subcat_id		= 2,
		@brand_id		= 2,
		@stor_id		= 1,
		@showzerostock	='false',
		@potentialstocklimit = 60
*/


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


SELECT	tp.pres_id,
		dbo.fnGetWordsCutByChar(tp.pres_desc,' ',15)		[pres_desc]

FROM	tbPresentation tp

WHERE	tp.comp_id	= @comp_id
AND		tp.pres_id IN	(SELECT	ti.pres_id
     						FROM 	tbItem ti
     						WHERE	ti.comp_id		= tp.comp_id
							AND		ti.subcat_id	= @subcat_id
							AND		ti.brand_id		= @brand_id
							AND		ISNULL(ti.item_web,'false')			= 'true'
							AND		ISNULL(ti.item_disabled,'false')	= 'false'
							AND		ISNULL(ti.item_not4Sale,'false')	= 'false'

							AND		(
										(@showzerostock = 'true') OR
										(@showzerostock = 'false' AND
										 CONVERT(integer,
											(dbo.fnGetAStock(@comp_id,@stor_id,ti.item_id,999999999.99) *
											@potentialstocklimit / 100)) > 0
										)
									)
							AND		ti.item_id NOT IN (SELECT tia.item_id FROM tbItemAssociation tia WHERE tia.comp_id = @comp_id)
						)


ORDER BY tp.pres_desc






GO








