CREATE PROCEDURE [dbo].[spPriceCost_CreateList]
(
	@comp_id			INT,
	@bra_id				INT,
	@cat_id				INT,
	@subcat_id			INT,
	@brand_id			INT,
--	@supp_id			INT,
	@type_id_from		INT,
	@list_id_from		INT,
	@curr_id			INT,
--	@item_id			INT,
	@Item_Guid			UNIQUEIDENTIFIER,
	@return_value		INT OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON

-- -------------------------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------------------------
	/*
	DECLARE
			@comp_id			INT,
			@bra_id				INT,
			@supp_id			INT,
			@cat_id				INT,
			@subcat_id			INT,
			@brand_id			INT,
			@curr_id			INT,
			@type_id_from		INT,
			@list_id_from		INT,
			@item_id			INT

	SELECT
			@comp_id			=1,
			@bra_id				=1,
			@supp_id			=-1,
			@cat_id				=24,
			@subcat_id			=1,
			@brand_id			=1,
			@curr_id			=1,
			@type_id_from		=1,   --tipo de combo seleccionado en origen (que readiobutton seleccionó)
			@list_id_from		=3,
			@item_id			=-1
	DROP  TABLE  #tmp_newlist
	DROP  TABLE  #tmpItems
	*/
-- -------------------------------------------------------------------------------------

	BEGIN TRY


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros
		-- NOTA: Para buscar todas las incidencias
		-- de este método ejecutar el "BuscarTexto" en la base de datos
		-- con el valor de referencia "#8600"
		-- Página de EJEMPLO:App_Reports_App_WebForms_wfmRptFilters_PriceLists2_Testing
		-- -------------------------------------------------------------
		DECLARE @objGUID AS UNIQUEIDENTIFIER
		SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@Item_Guid)
		DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf      WITH (NOLOCK)
				WHERE tcf.sl_guid	  = @objGUID      AND
					  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
				FROM tbItem ti
				WHERE ti.comp_id = @comp_id
			END






		CREATE TABLE  #tmp_newlist	(item_id INT)
		CREATE TABLE  #tmpItems		(item_id INT)



		/******************************************************************************************/
		/* recuperamos los items que ya están en la lista seleccionada*****************************/
		/******************************************************************************************/
		IF  @type_id_from = 1	/*Lista de Precios*/

			INSERT 	INTO #tmpItems (item_id)
			SELECT	item_id
			FROM	tbPriceListItems
			WHERE	comp_id		= @comp_id
			AND		prli_id		= @list_id_from


		ELSE					/*Lista de Costos*/

			INSERT 	INTO #tmpItems (item_id)
			SELECT  item_id
			FROM	tbItemCostList
   			WHERE	comp_id		= @comp_id
   			AND		coslis_id	= @list_id_from

		--SELECT * FROM #tmpItems
		/******************************************************************************************/




		/******************************************************************************************/
		/* recuperamos items que no están en la lista seleccionada aplicando los filtros **********/
		/******************************************************************************************/
		INSERT 	INTO [#tmp_newlist] (item_id)
		SELECT 	i.item_id
		FROM 	tbItem			I

			INNER JOIN @tblComplexFilter_Items	TEMP
			ON TEMP.item_id = I.item_id

		WHERE 	i.comp_id		= @comp_id
		--AND		(@supp_id		= -1  or	i.supp_id	= @supp_id	)
		--AND		(@item_id		= -1  or	i.item_id	= @item_id	)
		AND		(@cat_id		= -1  or	i.cat_id	= @cat_id	)
		AND		(@subcat_id		= -1  or	i.subcat_id	= @subcat_id)
		AND		(@brand_id		= -1  or	i.brand_id	= @brand_id	)
		and		i.item_id not in (SELECT	item_id	FROM	#tmpItems)

		--SELECT * FROM #tmp_newlist
		/******************************************************************************************/




		/******************************************************************************************/
		/* agregado de los items recuperados en la lista seleccionada  ****************************/
		/******************************************************************************************/
		IF @type_id_from = 1	/*Lista de Precios*/

			INSERT INTO dbo.tbPriceListItems
					(comp_id,		prli_id, 			item_id,
					prli_price,		curr_id, 			bra_id)
			SELECT 	@comp_id, 		@list_id_from, 		tmp.item_id,
					0,				@curr_id, 			@bra_id
			FROM    #tmp_newlist	tmp

		ELSE					/*Lista de Costos*/

			INSERT INTO dbo.tbItemCostList
					(comp_id,		coslis_id,			item_id,
					coslis_price,	coslis_price_aw,	curr_id)
			SELECT  @comp_id,		@list_id_from,		tmp.item_id,
					0,				0,					@curr_id
			FROM	#tmp_newlist	tmp
		/******************************************************************************************/

		SET @return_value = @@ROWCOUNT

		DROP table #tmp_newlist
		DROP table #tmpItems

	END TRY
	BEGIN CATCH
		SET @return_value = 0
	END CATCH

END
GO






create PROCEDURE [dbo].[spPriceCostList_Deletedata]
(

	@comp_id					INT,
	@bra_id						INT,
	@Item_Guid					UNIQUEIDENTIFIER,
	@typeFrom					INT,				--1 : Lista de precios , 2 : Lista de Costos
	@list_id					INT				    -- ID de la lista seleccionada

)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
		@comp_id					INT,
		@bra_id						INT,
		@Item_Guid					UNIQUEIDENTIFIER,
		@typeFrom					INT, --1 : Lista de precios , 2 : Lista de Costos
		@list_id					INT -- Id de la lista seleccionada

SELECT
		@comp_id					= 1,
		@typeFrom					= 1,
		@list_id					= 1,
		@bra_id						= 1,
		@Item_Guid					= '159d87d5-976c-4cd3-8f30-9b36a3788931'

*/
---------------------------------------------------------------------------------
---------------------------------------------------------------------------------
---------------------------------------------------------------------------------



set nocount on



BEGIN


	------------------------------------------------------------------------------------
	DECLARE @objGUID AS UNIQUEIDENTIFIER
	SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@Item_Guid)

	DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)

	INSERT INTO @tblComplexFilter_Items

		SELECT
			tcf.sl_id
			FROM tbComplexFilter tcf      WITH (NOLOCK)
			WHERE tcf.sl_guid	  = @objGUID      AND
				  tcf.sl_selected = 'True'
	------------------------------------------------------------------------------------


		--@typeFrom 1 : Lista de precios , 2 : Lista de Costos
		IF @typeFrom = 1
			-- ----------------------------------
			-- Lista de Precios
			-- ----------------------------------

			BEGIN


					DELETE tpli

					FROM tbPriceListItems						tpli

					INNER JOIN tbItem							ti	WITH (NOLOCK)
					ON	ti.comp_id	= tpli.comp_id	AND
						ti.item_id	= tpli.item_id

					INNER JOIN @tblComplexFilter_Items			tmp
					ON	tmp.item_id	= ti.item_id

					WHERE  tpli.comp_id = @comp_id		AND
						   tpli.prli_id = @list_id
			END

		ELSE

			-- ----------------------------------
			-- Lista de Costos
			-- ----------------------------------

			BEGIN


				DELETE tpli

				FROM tbItemCostList							tpli

				INNER JOIN tbItem							ti		WITH (NOLOCK)
				ON	ti.comp_id	= tpli.comp_id	AND
					ti.item_id	= tpli.item_id

				INNER JOIN @tblComplexFilter_Items			tmp
				ON	tmp.item_id	= ti.item_id

				WHERE  tpli.comp_id		= @comp_id		AND
					   tpli.coslis_id	= @list_id


			END


END


















GO






CREATE PROCEDURE [dbo].[spPriceCostList_UpdatePrices_Auto]
(

	@comp_id					INT,
	@typeFrom					INT,			--1 : Lista de precios , 2 : Lista de Costos
	@list_id					INT,
	@chkiscreate				BIT,			--Si NO hay asignado un precio para el Código del Artículo, desea crearlo?
	@item_code					NVARCHAR(50),
	@price						DECIMAL(19,5),
	@curr_id					INT,
	@bra_id						INT,
	@decDiscount1				DECIMAL(18,4),
	@decDiscount2				DECIMAL(18,4),
	@decDiscount3				DECIMAL(18,4),
	@decDiscount4				DECIMAL(18,4),
	@decSurCharge1				DECIMAL(18,4),
	@decSurCharge2				DECIMAL(18,4),
	@decSurCharge3				DECIMAL(18,4),
	@decSurCharge4				DECIMAL(18,4),
	@user_id					INT,
	@pli_id						UNIQUEIDENTIFIER,
	@supp_id					INT,
	@intoptionprice				INT,			--1 : Precios Sin Impuestos , 2 : Precios con Impuesto al Valor Agregado
	@intoptioncode				INT,			--1 : Código / EAN o EAN Adicional , 2 : Código de Fabricante, 3 : COdigo Adicional
	@chkAllowNegativeImport		BIT,			-- Permitir grabar importes menor o igual a 0.
	@strprefix					NVARCHAR(50),	-- Prefijo para el codigo de articulos.
	@stor_id					INT				-- Excluir Artículos con Stock Distinto de Cero en este DEPOSITO ( q admita sumarizadores )
)
AS


-- -------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
-- -------------------------------------------------------------------------------
/*
DECLARE 	@comp_id					INT,
			@typeFrom					INT,
			@list_id					INT,
			@chkiscreate				BIT,
			@item_code					NVARCHAR(50),
			@price						DECIMAL(19,5),
			@curr_id					INT,
			@bra_id						INT,
			@decDiscount1				DECIMAL(18,4),
			@decDiscount2				DECIMAL(18,4),
			@decDiscount3				DECIMAL(18,4),
			@decDiscount4				DECIMAL(18,4),
			@decSurCharge1				DECIMAL(18,4),
			@decSurCharge2				DECIMAL(18,4),
			@decSurCharge3				DECIMAL(18,4),
			@decSurCharge4				DECIMAL(18,4),
			@user_id					INT,
			@pli_id						UNIQUEIDENTIFIER,
			@supp_id					INT





SELECT 		@comp_id					= 1,
			@typeFrom					= 2,
			@list_id					= 1,
			@chkiscreate				= 0,
			@item_code					= 'F1',
			@price						= 32.5,
			@curr_id					= 1,
			@bra_id						= 1
*/
-- -------------------------------------------------------------------------------


set nocount on

--@typeFrom 1 : Lista de precios , 2 : Lista de Costos

BEGIN



	DECLARE @bolIsOK AS BIT
	SET     @bolIsOK = 'False'

	---------------------------------------------------------------------------------------------------------
	-- Si no le llega la moneda o no existe el id le pone por defecto la primera
	IF NOT EXISTS (	SELECT	TOP 1
						tc.curr_id
	           			FROM tbsysCurrency				tc		WITH (NOLOCK)
						WHERE	tc.curr_id = @curr_id)
		BEGIN
			SET @curr_id = ( SELECT
								tc.curr_id
								FROM	tbbranch		tc		WITH (NOLOCK)
								WHERE	tc.comp_id	= @comp_id AND
										tc.bra_id	= @bra_id
			               )
		END
	---------------------------------------------------------------------------------------------------------

	---------------------------------------------------------------------------------------------------------
	--Recuperamos el item_id mediante el codigo
	DECLARE @litem_id AS INT
	DECLARE @tmpTable TABLE(item_id INT PRIMARY KEY)


	SET @item_code = dbo.fnStrAllTrim(@strprefix) + dbo.fnStrAllTrim(@item_code)


	IF @intoptioncode = 1  --Código / EAN o EAN Adicional
		BEGIN

			SELECT
				TOP 1 @litem_id = ti.item_id
				FROM tbitem										ti				WITH (NOLOCK)

				LEFT JOIN tbItemEAN								tie				WITH(NOLOCK)--17/10/16
					ON	tie.comp_id = ti.comp_id AND
						tie.item_id = ti.item_id



				WHERE	ti.comp_id		= @comp_id															AND
					    CASE	-- GA y MOS  12/10/21 Excluir Artículos con Stock MAYOR que Cero
							WHEN @stor_id = -1															THEN 1
							WHEN dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id,ti.item_id ) <= 0		THEN 1
							ELSE																			 0
					    END = 1 AND
						(ti.item_code = @item_code OR tie.ie_ean = @item_code)								AND --17/10/16
						 @price			<> -1																AND
					  (
	  					@supp_id = -1 OR
	  					ti.supp_id = @supp_id OR
	  					EXISTS (
	  							SELECT TOP  1 1 FROM tbItemSupplier tis	WITH (NOLOCK)
	  								WHERE tis.comp_id = @comp_id	AND
	  									  tis.item_id = ti.item_id	AND
	  									  tis.supp_id = @supp_id

	  							)
					  )


			IF @chkAllowNegativeImport ='False' AND @price <= 0 SET @litem_id = NULL

			IF @litem_id IS NOT NULL
				BEGIN
					INSERT INTO @tmpTable(item_id) VALUES (@litem_id)
				END

		END
	ELSE

		IF @intoptioncode = 2 --Código de Fabricante
			BEGIN

				INSERT INTO @tmpTable(item_id)
				SELECT
					ti.item_id
					FROM tbitem				ti	WITH (NOLOCK)
					WHERE	ti.comp_id			= @comp_id		AND
							(ti.item_vendorCode = @item_code )	AND
							CASE	-- GA y MOS  12/10/21 Excluir Artículos con Stock MAYOR que Cero
								WHEN @stor_id = -1															THEN 1
								WHEN dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id,ti.item_id ) <= 0		THEN 1
								ELSE																			 0
							END = 1 AND
							@price				<> -1			AND
						  (
	  						@supp_id = -1 OR
	  						ti.supp_id = @supp_id OR
	  						EXISTS (
	  								SELECT TOP 1  1
	  									FROM tbItemSupplier tis	WITH (NOLOCK)
	  									WHERE tis.comp_id = @comp_id	AND
	  										  tis.item_id = ti.item_id	AND
	  										  tis.supp_id = @supp_id

	  								)
						  )

				IF (@chkAllowNegativeImport ='False' AND @price <= 0) SET @litem_id = NULL


			END

			ELSE

				BEGIN
					--Código Alternativo/Adicional
					SELECT
						TOP 1 @litem_id = ti.item_id
						FROM tbitem				ti	WITH (NOLOCK)
						LEFT JOIN tbItemEAN		tie	WITH(NOLOCK)
							ON	tie.comp_id = ti.comp_id AND
								tie.item_id = ti.item_id

						WHERE	ti.comp_id				= @comp_id								AND
								ti.item_codeAlternative = @item_code 							AND
								CASE	-- GA y MOS  12/10/21 Excluir Artículos con Stock MAYOR que Cero
									WHEN @stor_id = -1															THEN 1
									WHEN dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id,ti.item_id ) <= 0		THEN 1
									ELSE																			 0
								END = 1 AND
								@price					<> -1									AND
							  (
	  							@supp_id = -1 OR
	  							ti.supp_id = @supp_id OR
	  							EXISTS (
	  									SELECT TOP 1 1 FROM tbItemSupplier tis	WITH (NOLOCK)
	  										WHERE tis.comp_id = @comp_id	AND
	  											  tis.item_id = ti.item_id	AND
	  											  tis.supp_id = @supp_id

	  									)
							  )


					IF @chkAllowNegativeImport ='False' AND @price <= 0 SET @litem_id = NULL

					IF @litem_id IS NOT NULL
						BEGIN
							INSERT INTO @tmpTable(item_id) VALUES (@litem_id)
						END

				END
	---------------------------------------------------------------------------------------------------------




	-- -------------------------------------------------------------------------------------------------------
	-- Declara un cursor para recorrer todos los items que se debe actualizar
	-- -------------------------------------------------------------------------------------------------------
	DECLARE curItems CURSOR LOCAL FAST_FORWARD FOR
		SELECT item_id
		FROM @tmpTable

	OPEN curItems
	FETCH NEXT FROM curItems
		INTO @litem_id
	WHILE @@FETCH_STATUS = 0
		BEGIN

			-- --------------------------------------------------------------------------------------------------------------
			-- Comienza a actualizar a todos los Item_id que corresponda segun lo insertado en la tabla temporal de arriba
			-- --------------------------------------------------------------------------------------------------------------
			IF @litem_id IS NOT NULL
				BEGIN

					IF @typeFrom = 1
							-- Lista de precios
						BEGIN

							IF EXISTS (	SELECT TOP 1 	1
	           								FROM tbPriceListItems tpli2	WITH (NOLOCK)
											WHERE	tpli2.comp_id = @comp_id	AND
													tpli2.item_id = @litem_id	AND
													tpli2.prli_id = @list_id)

								BEGIN

									--'Insertamos en la tabla de Historico
									EXEC spPriceCostList_UpdatePrices_Auto_PriceCostListImportLog_InsertData	@comp_id, @pli_id, @user_id,
																												@list_id, @litem_id,
																												@item_code, 1

										--'Actualziamos el precio y la moneda de la lista de precios

										IF @intoptionprice = 2 --Opcion 2 con IVA es
											BEGIN
												SET @price = @price / dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,@litem_id))
											END

										UPDATE tbPriceListItems	WITH (ROWLOCK)
											SET	prli_price			= @price,
												curr_id				= @curr_id,
												user_id_lastUpdate	= @user_id,
												prli_disabled4Rules = 0
											WHERE  comp_id = @comp_id  AND
												   item_id = @litem_id AND
												   prli_id = @list_id

										SET @bolIsOK = 'True'

										UPDATE tbitem	WITH (ROWLOCK)
											SET item_recentlyPurchased		= 'True',
												item_lastUpdate_byProcess	= GETDATE()
											WHERE	comp_id = @comp_id AND
													item_id = @litem_id



								END


							ELSE

								BEGIN

									IF @chkiscreate = 1
									--Lo creamos si el check de crear esta en true
										BEGIN

											--'Insertamos en la tabla de Historico
											EXEC spPriceCostList_UpdatePrices_Auto_PriceCostListImportLog_InsertData
																								 @comp_id, @pli_id, @user_id,
																								 @list_id, @litem_id,
																								 @item_code, 1


											IF @intoptionprice = 2 --Opcion 2 con IVA es
												BEGIN
													SET @price = @price / dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,@litem_id))
												END

											INSERT INTO tbPriceListItems	WITH (ROWLOCK)
											(
												comp_id,
												prli_id,
												item_id,
												prli_price,
												curr_id,
												bra_id,
												prli_cd,
												user_id_lastUpdate,
												prli_disabled4Rules
											)
											VALUES
											(
												@comp_id,
												@list_id,
												@litem_id,
												@price,
												@curr_id,
												NULL/*@bra_id*/,
												GETDATE(),
												@user_id,'False'
											)
											SET @bolIsOK = 'True'

											UPDATE tbitem
												SET item_recentlyPurchased		= 'True',
													item_lastUpdate_byProcess	= GETDATE()
												WHERE	comp_id = @comp_id AND
														item_id = @litem_id


										END

									ELSE

										BEGIN

											--'Insertamos en la tabla de Historico
											EXEC spPriceCostList_UpdatePrices_Auto_PriceCostListImportLog_InsertData @comp_id,@pli_id, @user_id,
																													 @list_id, @litem_id,
																													 @item_code,3

											-- No existe el id de artiuclo para ese codigo
											SET @bolIsOK = 'False'
										END


								END

						END

					ELSE

						-- ----------------------------------
						-- Lista de Costos
						-- ----------------------------------

						BEGIN

							IF EXISTS (	SELECT TOP 1 	1
       										FROM tbItemCostList ticl	WITH (NOLOCK)
											WHERE	ticl.comp_id	= @comp_id	AND
													ticl.item_id	= @litem_id	AND
													ticl.coslis_id	= @list_id)

								BEGIN

									--'Insertamos en la tabla de Historico
									EXEC spPriceCostList_UpdatePrices_Auto_PriceCostListImportLog_InsertData @comp_id, @pli_id, @user_id,
																								 @list_id, @litem_id,
																								 @item_code, 2

										------------------------------------------------------------
										--Actualizamos descuentos y recargos del aitem
										exec spPriceCostList_UpdatePrices_Auto_UpdateDiscounts	 @comp_id,
																								 @litem_id, @decDiscount1,
																								 @decDiscount2, @decDiscount3,
																								 @decDiscount4, @decSurCharge1,
																								 @decSurCharge2, @decSurCharge3,
																								 @decSurCharge4
										------------------------------------------------------------

										IF @intoptionprice = 2 --Opcion 2 con IVA es
											BEGIN
												SET @price = @price / dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,@litem_id))
											END

										------------------------------------------------------------
										--Actualizamos precio y moneda de la lista de costo e item correspondiente.
										UPDATE tbItemCostList	WITH (ROWLOCK)
										SET	coslis_price		= @price,
											coslis_price_aw		= @price,
											curr_id				= @curr_id,
											user_id_lastUpdate	= @user_id,
											coslis_disabled4Rules			= 0,
											coslis_blockLastUpdate4Rules	= 0
										WHERE  comp_id   = @comp_id  AND
											   item_id   = @litem_id AND
											   coslis_id = @list_id
										------------------------------------------------------------



										SET @bolIsOK = 'True'

										UPDATE tbitem	WITH (ROWLOCK)
											SET item_recentlyPurchased		= 'True',
												item_lastUpdate_byProcess	= GETDATE()
											WHERE	comp_id = @comp_id AND
													item_id = @litem_id


								END

							ELSE

								BEGIN

									IF @chkiscreate = 1

										BEGIN

											--'Insertamos en la tabla de Historico
											EXEC spPriceCostList_UpdatePrices_Auto_PriceCostListImportLog_InsertData @comp_id, @pli_id, @user_id,
																								 @list_id, @litem_id,
																								 @item_code, 2

											------------------------------------------------------------
											--Actualizamos descuentos y recargos del aitem

											exec spPriceCostList_UpdatePrices_Auto_UpdateDiscounts	 @comp_id,
																									 @litem_id, @decDiscount1,
																									 @decDiscount2, @decDiscount3,
																									 @decDiscount4, @decSurCharge1,
																									 @decSurCharge2, @decSurCharge3,
																									 @decSurCharge4

											------------------------------------------------------------

											IF @intoptionprice = 2 --Opcion 2 con IVA es
												BEGIN
													SET @price = @price / dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,@litem_id))
												END

											INSERT INTO tbItemCostList	WITH (ROWLOCK)
											(
												comp_id,
												coslis_id,
												item_id,
												coslis_price,
												coslis_price_aw,
												curr_id,
												coslis_cd,
												user_id_lastUpdate,coslis_disabled4Rules,coslis_blockLastUpdate4Rules
											)
											VALUES
											(

												@comp_id,
												@list_id,
												@litem_id,
												@price,
												@price,
												@curr_id,
												GETDATE(),
												@user_id,'False','False'
											)



											SET @bolIsOK = 'True'

											UPDATE tbitem	WITH (ROWLOCK)
											SET item_recentlyPurchased		= 'True',
												item_lastUpdate_byProcess	= GETDATE()
											WHERE	comp_id = @comp_id AND
													item_id = @litem_id

										END

									ELSE

										BEGIN

											--'Insertamos en la tabla de Historico
											EXEC spPriceCostList_UpdatePrices_Auto_PriceCostListImportLog_InsertData @comp_id,@pli_id, @user_id,
																													 @list_id, @litem_id,
																													 @item_code,3

											-- No existe el id de artiuclo para ese codigo
											SET @bolIsOK = 'False'
										END
								END
						END
				END
			-- --------------------------------------------------------------------------------------------------------------


			FETCH NEXT FROM curItems
				INTO @litem_id
		END

	CLOSE		curItems
	DEALLOCATE	curItems
	-- -------------------------------------------------------------------------------------------------------







	-- --------------------------------------------------------------------------------------------------------------
	-- Informa que no logro encontrar nada para actualizar con ese codigo
	-- --------------------------------------------------------------------------------------------------------------
	IF @litem_id IS NULL
		-- No existe el id de artiuclo para ese codigo
		BEGIN

			--'Insertamos en la tabla de Historico
			EXEC spPriceCostList_UpdatePrices_Auto_PriceCostListImportLog_InsertData @comp_id,@pli_id, @user_id,
																					 @list_id, @litem_id,
																					 @item_code,3

			-- No existe el id de artiuclo para ese codigo
			SET @bolIsOK = 'False'
		END
	-- --------------------------------------------------------------------------------------------------------------





	-- Indica si actualizo o inserto OR no hizo nada
	-- 1 : Insert/Update
	-- 0 : No hizo nada
	IF @bolIsOK = 'True'
		BEGIN
			SELECT 1  [bolIsOK]
		END
	ELSE
		BEGIN
			SELECT 0  [bolIsOK]
		END


END


















GO





CREATE PROCEDURE [dbo].[spPriceCostList_UpdatePrices_Auto_PriceCostListImportLog_InsertData]
(


	@comp_id		INT,
	@pli_id			UNIQUEIDENTIFIER,
	@user_id		INT,
	@list_id		INT,
	@litem_id		INT,
	@item_code		NVARCHAR(50),
	@option_insert	INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*

declare
		@comp_id		INT,
		@pli_id			INT,
		@user_id		INT,
		@list_id		INT,
		@litem_id		INT,
		@item_code		NVARCHAR(50),
		@option_insert	INT


select	@comp_id		= 1,
		@pli_id			='01b880c3-a129-4675-8da0-3ac973b68132',
		@list_id		= 10

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN


	--@option_insert 1 : LISTA DE PRECIOS , 2 : LSITA DE COSTOS , 3 : NO ENCONTRO ITEM PARA ESE CODIGO


	IF @option_insert = 1
		BEGIN
						INSERT INTO tbPriceCostListImportLog	WITH (ROWLOCK)
								(
									comp_id,
									pli_id,
									[user_id],
									prli_id,
									coslis_id,
									item_id,
									code4Import
								)
								VALUES
								(
									@comp_id,
									@pli_id,
									@user_id,
									@list_id,
									NULL,
									@litem_id,
									@item_code
								)

		END

		ELSE
			IF @option_insert = 2
					BEGIN
							INSERT INTO tbPriceCostListImportLog	WITH (ROWLOCK)
									(
										comp_id,
										pli_id,
										[user_id],
										prli_id,
										coslis_id,
										item_id,
										code4Import
									)
									VALUES
									(
										@comp_id,
										@pli_id,
										@user_id,
										NULL,
										@list_id,
										@litem_id,
										@item_code
									)

					END

			ELSE
					BEGIN

							INSERT INTO tbPriceCostListImportLog	WITH (ROWLOCK)
									(
										comp_id,
										pli_id,
										[user_id],
										prli_id,
										coslis_id,
										item_id,
										code4Import
									)
									VALUES
									(
										@comp_id,
										@pli_id,
										@user_id,
										NULL,
										NULL,
										NULL,
										@item_code
									)


						END



END
GO





CREATE PROCEDURE [dbo].[spPriceCostList_UpdatePrices_Auto_UpdateDiscounts]
(

	@comp_id					INT,
	@litem_id					INT,
	@decDiscount1				DECIMAL(18,4),
	@decDiscount2				DECIMAL(18,4),
	@decDiscount3				DECIMAL(18,4),
	@decDiscount4				DECIMAL(18,4),
	@decSurCharge1				DECIMAL(18,4),
	@decSurCharge2				DECIMAL(18,4),
	@decSurCharge3				DECIMAL(18,4),
	@decSurCharge4				DECIMAL(18,4)

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*

declare
		@comp_id					INT,
		@litem_id					INT,
		@decDiscount1				DECIMAL(18,4),
		@decDiscount2				DECIMAL(18,4),
		@decDiscount3				DECIMAL(18,4),
		@decDiscount4				DECIMAL(18,4),
		@decSurCharge1				DECIMAL(18,4),
		@decSurCharge2				DECIMAL(18,4),
		@decSurCharge3				DECIMAL(18,4),
		@decSurCharge4				DECIMAL(18,4)


select	@comp_id		= 1,
		@litem_id		= 10

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN



	------------------------------------------------------------
	--Actualizamos descuentso y recargos del aitem
	IF @decDiscount1 <> -99999999
		BEGIN
			UPDATE tbItem	WITH (ROWLOCK)
			SET item_purOrd_Disc1 = @decDiscount1
			WHERE comp_id   = @comp_id  AND
				  item_id   = @litem_id

		END

		IF @decDiscount2 <> -99999999
		BEGIN
			UPDATE tbItem	WITH (ROWLOCK)
			SET item_purOrd_Disc2 = @decDiscount2
			WHERE comp_id   = @comp_id  AND
				  item_id   = @litem_id

		END

		IF @decDiscount3 <> -99999999
		BEGIN
			UPDATE tbItem	WITH (ROWLOCK)
			SET item_purOrd_Disc3 = @decDiscount3
			WHERE comp_id   = @comp_id  AND
				  item_id   = @litem_id

		END

		IF @decDiscount4 <> -99999999
		BEGIN
			UPDATE tbItem	WITH (ROWLOCK)
			SET item_purOrd_Disc4 = @decDiscount4
			WHERE comp_id   = @comp_id  AND
				  item_id   = @litem_id

		END

		IF @decSurCharge1 <> -99999999
			BEGIN
				UPDATE tbItem	WITH (ROWLOCK)
				SET item_purOrd_surcharge1 = @decSurCharge1
				WHERE comp_id   = @comp_id  AND
					  item_id   = @litem_id

			END

			IF @decSurCharge2 <> -99999999
			BEGIN
				UPDATE tbItem	WITH (ROWLOCK)
				SET item_purOrd_surcharge2 = @decSurCharge2
				WHERE comp_id   = @comp_id  AND
					  item_id   = @litem_id

			END

			IF @decSurCharge3 <> -99999999
			BEGIN
				UPDATE tbItem	WITH (ROWLOCK)
				SET item_purOrd_surcharge3 = @decSurCharge3
				WHERE comp_id   = @comp_id  AND
					  item_id   = @litem_id

			END

			IF @decSurCharge4 <> -99999999
			BEGIN
				UPDATE tbItem	WITH (ROWLOCK)
				SET item_purOrd_surcharge4 = @decSurCharge4
				WHERE comp_id   = @comp_id  AND
					  item_id   = @litem_id

			END
		------------------------------------------------------------



END
GO





CREATE PROCEDURE [dbo].[spPriceCostListImportLog_getDataByFilters]
(
	@comp_id			int,
	@pli_id				uniqueidentifier,
	@list_id			INT,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*

declare	@comp_id		int,
		@pli_id			UNIQUEIDENTIFIER,
		@list_id		INT


select	@comp_id		= 1,
		@pli_id			='01b880c3-a129-4675-8da0-3ac973b68132',
		@list_id		= 10

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN



	SELECT  isnull(ti.item_desc,tut.utexts_desc)					[item_desc],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			isnull(tpl.prli_desc,'')								[prli_desc],
			tpli.prli_price											[price],
			isnull(ticln.coslis_desc,'')							[coslis_desc],
			ticl.coslis_price										[Precio_Contado],
			tpclil.pli_cd											[pli_cd],
			tpclil.code4Import										[code4Import],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbItem									ti		WITH (NOLOCK)
	ON	ti.comp_id		= tpclil.comp_id		AND
		ti.item_id		= tpclil.item_id

	LEFT JOIN tbPriceListItems							tpli	WITH (NOLOCK)
	ON	tpli.comp_id	= tpclil.comp_id			AND
		tpli.prli_id	= @list_id					AND
		tpli.item_id	= tpclil.item_id

	LEFT JOIN tbItemCostList							ticl	WITH (NOLOCK)
	ON  ticl.comp_id	= tpclil.comp_id			AND
		ticl.coslis_id	= @list_id					AND
		ticl.item_id	= tpclil.item_id

	LEFT JOIN tbPriceList								tpl		WITH (NOLOCK)
	ON	tpl.comp_id		= tpclil.comp_id		AND
		tpl.prli_id		= tpclil.prli_id

	LEFT JOIN tbItemCostListName						ticln	WITH (NOLOCK)
	ON	ticln.comp_id	= tpclil.comp_id		AND
		ticln.coslis_id = tpclil.coslis_id

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
	ON tu.[user_id] = tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
	ON	tut.lang_id		= @lang_id			AND
		tut.utexts_id	= 40156


	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @pli_id


	ORDER BY tpclil.item_id asc




END
GO





CREATE PROCEDURE [dbo].[spPriceLabel_ComplexFilter_CheckStock]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@stor_id			INT


AS


-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*
DECLARE 		@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@guid				UNIQUEIDENTIFIER,
				@stor_id			INT

SELECT			@comp_id			=1,
				@bra_id				=1,
				@prof_id			=1,
				@user_id			=1,
				@guid				='BE41D364-AD65-4FC0-960B-6C036FF5D1C9',
				@stor_id			=2
*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	DELETE

	FROM tbComplexFilter

