		  dbo.fnGetAStock(@comp_id, @stor_id, sl_id, 9999999999) <= 0





	--DECLARE @tmpItemWithOutStock TABLE(item_id INT PRIMARY KEY)

	-- --DE TODOS LOS ARTICULOS SELECCIONADOS EN LA COMPLEX FILTER SOLO VOY A GUARDAR LOS Q NO TENGAN STOCK !
	--INSERT INTO @tmpItemWithOutStock (item_id)	SELECT tcf.sl_id
	--                                          	FROM tbComplexFilter						tcf		WITH (NOLOCK)
	--                                          	WHERE tcf.sl_selected = 'True'	AND
