CREATE PROCEDURE [dbo].[spPriceList_getComboByProfile]
(
	@comp_id			INT,
	@prof_id			INT
)
AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON


	/*
	DECLARE 	@comp_id			INT, @prof_id			INT
	SELECT		@comp_id=1, @prof_id=2
	*/


		select		tpl.prli_id		[id],
					tpl.prli_desc	[desc]

		from		dbo.tbPriceList tpl

		where		 tpl.comp_id		= @comp_id
		AND			 tpl.prli_disabled	= 'False'
		AND			(tpl.prli_id IN (SELECT	tplp.prli_id
	   									  FROM		tbPriceList4Profile tplp
	   									  WHERE		tplp.comp_id	= @comp_id
										  AND		tplp.prof_id	= @prof_id) OR
					 NOT EXISTS (SELECT	1
	   								  FROM		tbPriceList4Profile tplp
	   								  WHERE		tplp.comp_id	= @comp_id
									  AND		tplp.prof_id	= @prof_id))

		Order By	prli_desc


END







GO






