CREATE PROCEDURE [dbo].[spPriceList_getComboByStorageProfile]
(
	@comp_id			INT,
	@prof_id			INT,
	@stor_id			INT
)
AS

BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

-- --------------------------------------------------------
-- TEsting
-- --------------------------------------------------------
/*
DECLARE 	@comp_id	INT,
			@prof_id	INT,
			@stor_id	INT
SELECT		@comp_id	=1,
			@prof_id	=2,
			@stor_id	=10
*/
-- --------------------------------------------------------

-- MOS 07-2012
	DECLARE @bitHaveSomeIntbPriceList4Profile AS BIT
	SET @bitHaveSomeIntbPriceList4Profile = 'False'


	select		tpl.prli_id		[id],
				tpl.prli_desc	[desc]

		INTO #Tmp
		from		dbo.tbPriceList tpl

		where	 tpl.comp_id		=	@comp_id
			AND  tpl.prli_disabled	= 'False'
			AND
				(tpl.prli_id IN (SELECT	tplp.prli_id
	   								FROM		tbPriceList4Profile tplp
	   								WHERE		tplp.comp_id	= @comp_id
										AND		tplp.prof_id	= @prof_id) OR
					 NOT EXISTS (SELECT	1
	   								FROM		tbPriceList4Profile tplp
	   								WHERE		tplp.comp_id	= @comp_id
										AND		tplp.prof_id	= @prof_id))

	--Order By	prli_desc

	select		tpl.prli_id		[id],
				tpl.prli_desc	[desc]
		INTO #Tmp1
		from	dbo.tbPriceList tpl
		where	 tpl.comp_id		=	@comp_id
			AND	 tpl.prli_disabled	= 'False'
			AND
				(
					tpl.prli_id IN (SELECT	tplp.prli_id
   										FROM		tbPriceList4Storage4Profile tplp
   										WHERE		tplp.comp_id	= @comp_id
										  AND		tplp.prof_id	= @prof_id
										  AND		tplp.stor_id	= @stor_id) OR
					(
						 NOT EXISTS (	 SELECT	1
   											FROM		tbPriceList4Storage4Profile tplp
    										WHERE		tplp.comp_id	= @comp_id
											  AND		tplp.prof_id	= @prof_id
											  AND		tplp.stor_id	= @stor_id)
					AND
						 NOT EXISTS (	 SELECT	1
   											FROM		tbPriceList4Profile tplp
    										WHERE		tplp.comp_id	= @comp_id
											  AND		tplp.prof_id	= @prof_id
									)

					)
				)

	SELECT Distinct *
		FROM #Tmp		tplp
		UNION
	SELECT *
		FROM #Tmp1		tplpd

	ORDER BY [desc]

	DROP table #Tmp
	DROP table #Tmp1


END






GO







CREATE  PROCEDURE [dbo].[spPriceList_Getdata]
(
	@comp_id	as int
)
AS
