SELECT	tpl.comp_id,
		tpl.prli_id,
		tpl.prli_desc,
		tpl.bra_id,
      	tpl.prili_AuthorizationRequired,
      	tpl.prli_commission,
      	tpl.prli_commission_byReceive

FROM 	dbo.tbPriceList tpl		WITH (NOLOCK)

WHERE 	tpl.comp_id = @comp_id



GO





