CREATE procedure [dbo].[spPriceList_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,
		@option				int,
		@item_desc			varchar(200),
		@option2			INT,
		@item_vendorCode	VARCHAR(200),
		@prli_id1			int,
		@pres_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@bra_id				int,
		@curr_id			int,
		@stor_id			INT,
		@currList_id		int,
		@orderby			INT,
		@strItemClass		VARCHAR(MAX),
		@intBranch4Lang		INT

)
as


BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- -------------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------------
/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			int,

			@option				int,
			@item_desc			varchar(200),
			@option2			INT,
			@item_vendorCode	VARCHAR(200),
			@prli_id1			int,
			@pres_id			int,
			@cat_id				int,
			@subcat_id			int,
			@brand_id			int,
			@bra_id				int,
			@curr_id			int,
			@item_disabled		INT,
			@stor_id			INT,
			@currList_id		int,
			@orderby			INT,
			@intBranch4Lang		int,
		@strItemClass		VARCHAR(MAX)

	SELECT
			@comp_id			=1,
			@lang_id			=2,
			@page_id			=10017,

			@option				=-1,
			@item_desc			='',
			@option2			=-1,
			@item_vendorCode	='',

			@prli_id1			=1,
			@pres_id			=-1,
			@cat_id				=-1,
			@subcat_id			=-1,
			@brand_id			=-1,
			@bra_id				=-1,
			@curr_id			=-1,
			@item_disabled		= 0,
			@stor_id			= -1,
			@currList_id		= -1,
			@orderby			= 2,
			@strItemClass = ''

			DROP TABLE #tmp_PriceList
*/
	-- -------------------------------------------------------------------------------------



	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbItemClass
	-- -------------------------------------------------------------------------------------
	DECLARE @tmpItemClass TABLE(ic_id INT PRIMARY KEY)
	IF @strItemClass = '-1' OR @strItemClass = ''
		BEGIN
			INSERT INTO @tmpItemClass (ic_id)	SELECT tic.ic_id
			                                 		FROM tbItemClass tic
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItemClass ( ic_id)	SELECT items
			                                  		FROM dbo.fnSplitTable(@strItemClass,',') fst
		END
	-- -------------------------------------------------------------------------------------



	DECLARE @fun_id INT
	SET @fun_id = 1

	--
	--* Me guardo el Simbolo de la Moneda de la lista.
	declare @lcurr_symbol_oflist NVARCHAR(50)

	set @lcurr_symbol_oflist = ( select tc.curr_symbol
	                             from tbsysCurrency			tc
								 where tc.curr_id =  @currList_id )

	--select @lcurr_symbol_oflist
	--**
	--

	SELECT 	I.item_code																				[item_code],
			I.item_desc																				[item_desc],

			ttn.tax_percentage	 [Neto],

			case when @currList_id = -1 then
				PLI1.prli_price + (pli1.prli_price * IsNull(ttn.tax_percentage,0) / 100)
			else
				dbo.fnGetExchange2(@comp_id,PLI1.prli_price + (pli1.prli_price * IsNull(ttn.tax_percentage,0) / 100),cc1.curr_id,@currList_id,0,0,0,0) end	[masIVA],

			case when @currList_id = -1 then
				CC1.curr_symbol
			else
				@lcurr_symbol_oflist
			end																						[curr_desc],
			C.cat_desc																				[cat_desc],
			SC.subcat_desc																			[subcat_desc],
			isnull(B.brand_desc,'')																	[brand_desc]
	INTO #tmp_PriceList

	FROM	dbo.tbItem								I					WITH (NOLOCK)

			LEFT JOIN [tbPresentation]				P					WITH (NOLOCK)
			ON	P.[comp_id]							= I.[comp_id]
			AND P.[pres_id]							= I.[pres_id]

			LEFT JOIN tbCategory					C					WITH (NOLOCK)
			ON	C.[comp_id]							= I.[comp_id]
			AND C.[cat_id]							= I.[cat_id]

			LEFT JOIN tbSubCategory					SC					WITH (NOLOCK)
			ON	SC.[comp_id]						= I.[comp_id]
			AND SC.[cat_id]							= I.[cat_id]
			AND SC.[subcat_id]						= I.[subcat_id]

			LEFT JOIN tbBrand						B					WITH (NOLOCK)
			ON	B.[comp_id]							= I.[comp_id]
			AND B.[brand_id]						= I.[brand_id]

			LEFT JOIN	tbBranch					BR					WITH (NOLOCK)
			ON  BR.[comp_id]						= I.[comp_id]
			AND BR.[bra_id]							= I.[bra_id]

			LEFT JOIN dbo.tbByOrder					BO					WITH (NOLOCK)
			ON	BO.[comp_id]						= I.[comp_id]
			AND BO.[byor_id]						= I.[byor_id]

			left JOIN [tbsysOptionsValues]			O					WITH (NOLOCK)
			ON	o.[optval_id]						= I.[item_liquidation]
			AND	o.[optval_class]					= 1
			and o.lang_id							= @lang_id

			Inner join tbPriceListItems				PLI1				WITH (NOLOCK)
			on	PLI1.[comp_id]						= I.[comp_id]
			and PLI1.[prli_id]						= @prli_id1
			and PLI1.item_id						= I.item_id

			Inner JOIN tbsysCurrency				CC1					WITH (NOLOCK)
			ON	CC1.[curr_id]						= PLI1.[curr_id]

			LEFT JOIN vwItemTaxesOnlyOneIvaTax		vit					WITH (NOLOCK)
			ON	vit.comp_id							= i.comp_id
			AND vit.item_id							= i.item_id

			LEFT JOIN tbTaxName						ttn					WITH (NOLOCK)
			ON	ttn.comp_id							= vit.comp_id
			AND ttn.tax_id							= vit.tax_id

			INNER JOIN vwsysTaxClassIVA_Taxes		vtcit				WITH (NOLOCK)
			ON vtcit.tax_class						= ttn.tax_class

			INNER JOIN vwItems_ParentStatus			vwr					WITH (NOLOCK)
			ON	vwr.comp_id							= i.comp_id
			AND vwr.item_id						    = i.item_id

			INNER JOIN @tmpItemClass tmpic
				ON tmpic.ic_id						= i.ic_id

			WHERE		I.[comp_id]		=	@comp_id
			AND			(@pres_id		= -1 or I.[pres_id]		=	@pres_id)
			AND			(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
			AND			(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
			AND			(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
			AND			(@bra_id		= -1 or I.[bra_id]		=	@bra_id)
			AND			(@curr_id		= -1 or CC1.[curr_id]	=	@curr_id)
			AND			(@stor_id		= -1 or dbo.fnGetAStock(@comp_id, @stor_id, i.item_id,999999999)> 0 )
			AND			(
							(@option	 = -1 ) or
							(@option	 = 0 and I.item_desc like @item_desc + '%') or
							(@option	 = 1 and I.item_desc like '%' + @item_desc + '%') or
							(@option	 = 2 and I.item_desc = @item_desc ) or
							(@option	 = 3 and I.item_desc <> @item_desc ) or
							(@option	 = 4 and I.item_desc not like '%' + @item_desc + '%')
						)

			AND			(
							(@option2	 = -1 ) or
							(@option2	 = 0 and I.item_code like @item_vendorCode + '%') or
							(@option2	 = 1 and I.item_code like '%' + @item_vendorCode + '%') or
							(@option2	 = 2 and I.item_code = @item_vendorCode ) or
							(@option2	 = 3 and I.item_code <> @item_vendorCode ) or
							(@option2	 = 4 and I.item_code not like '%' + @item_vendorCode + '%')
			)

			AND IsNull(I.item_disabledInPriceList,'False') = 'False'
			AND vtcit.tax_class = 1





	IF @orderby = 1 -- Descripcion
		BEGIN
			SELECT * FROM #tmp_PriceList tmp
			ORDER BY	tmp.item_desc
		END
	ELSE
		IF @orderby = 2 -- Categoría, SubCategoría, Descripción
			BEGIN
				SELECT * FROM #tmp_PriceList tmp
				ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.item_desc
			END
		ELSE
			IF @orderby = 3 -- Categoría, SubCategoría, Código
				BEGIN
					SELECT * FROM #tmp_PriceList tmp
					ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.item_code
				END
			ELSE
				IF @orderby = 4 -- Còdigo
					BEGIN
						SELECT * FROM #tmp_PriceList tmp
						ORDER BY tmp.item_code ASC
					END
						IF @orderby = 5 -- Marca, Descripción
							BEGIN
								SELECT * FROM #tmp_PriceList tmp
								ORDER BY tmp.brand_desc, tmp.item_desc
							END

						ELSE
							IF @orderby = 6 -- Marca, Código
								BEGIN
									SELECT * FROM #tmp_PriceList tmp
									ORDER BY tmp.brand_desc,tmp.item_code
								END
							ELSE
								IF @orderby = 7 -- Categoría, SubCategoría, Marca, Descripción
									BEGIN
										SELECT * FROM #tmp_PriceList tmp
										ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.brand_desc,tmp.item_desc
									END
										IF @orderby = 8 -- Categoría, SubCategoría, Marca, Código
											BEGIN
												SELECT * FROM #tmp_PriceList tmp
												ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.brand_desc,tmp.item_code
											END



	exec [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id,	@page_id





	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	SELECT
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 43
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params1],

			CASE @option WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tov.optval_desc + ISNULL(@item_desc,'')
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 2
					AND		tov.optval_id		= @option
					AND		tov.lang_id			= @lang_id)
			END																															[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 109
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			(SELECT tpl.prli_desc
				FROM dbo.tbPriceList tpl
				WHERE tpl.prli_id = @prli_id1)																							[params4],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 36
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params11],

				CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.cat_desc
						FROM	dbo.tbCategory tc
						WHERE	tc.cat_id = @cat_id)
				END																														[params12],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params13],

				CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
						FROM	dbo.tbSubCategory tsc
						WHERE	tsc.subcat_id = @subcat_id)
				END																														[params14],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 73
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],

				CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.brand_desc
						FROM	dbo.tbBrand tb
						WHERE	tb.brand_id = @brand_id)
				END																														[params16],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 371
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params17],

				CASE @pres_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tp.pres_desc
						FROM	dbo.tbPresentation tp
						WHERE	tp.pres_id = @pres_id)
				END																														[params18],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 28
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params19],

			CASE @bra_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.bra_desc
						FROM	dbo.tbBranch tb
						WHERE	tb.bra_id = @bra_id)
				END																														[params20],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 106
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params21],

			CASE @curr_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tc.curr_desc
						FROM	dbo.tbsysCurrency tc
						WHERE	tc.curr_id = @curr_id)
				END																														[params22],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 111
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params27],

      		 CASE @stor_id  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 26)
				ELSE
					(SELECT	TOP 1 ts.stor_desc
						FROM	  tbStorage				ts
						WHERE	  ts.stor_id = @stor_id)
				END		                                                   [params28],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2363
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params29],

      		 CASE @currList_id  WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 27)
				ELSE
					(SELECT	TOP 1 tc.curr_desc
						FROM	  tbsysCurrency tc
						WHERE	  tc.curr_id = @currList_id)
				END		                                                   [params30],



			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1467
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params31],

			CASE @orderby WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tov.optval_desc
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 327
					AND		tov.optval_id		= @orderby
					AND		tov.lang_id			= @lang_id)
			END																															[params32]








END
GO





CREATE procedure [dbo].[spPriceList_getReport_ByWeight]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,
		@prli_id1			int,
		@bra_id				int,
		@curr_id			int,
		@stor_id			INT,
		@currList_id		int,
		@orderby			INT,
		@guid				VARCHAR(50),
		@intBranch4Lang		INT,
		@displayType		INT

)
as



BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- -------------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------------
/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			int,

			@option				int,
			@item_desc			varchar(200),
			@option2			INT,
			@item_vendorCode	VARCHAR(200),
			@prli_id1			int,
			@pres_id			int,
			@cat_id				int,
			@subcat_id			int,
			@brand_id			int,
			@bra_id				int,
			@curr_id			int,
			@item_disabled		INT,
			@stor_id			INT,
			@currList_id		int,
			@orderby			INT,
			@guid				VARCHAR(50),
			@intBranch4Lang		INT,
			@displayType		INT

	SELECT
			@comp_id			=1,
			@lang_id			=2,
			@page_id			=10017,

			@option				=-1,
			@item_desc			='',
			@option2			=-1,
			@item_vendorCode	='',

			@prli_id1			=1,
			@pres_id			=-1,
			@cat_id				=-1,
			@subcat_id			=-1,
			@brand_id			=-1,
			@bra_id				=-1,
			@curr_id			=-1,
			@item_disabled		= 0,
			@stor_id			= -1,
			@currList_id		= -1,
			@orderby			= 2,
			@guid				= '4944f036-b9b3-437f-8804-9f715e05c9f4',
			@displayType		= 1

			DROP TABLE #tmp_PriceList
	*/
	-- -------------------------------------------------------------------------------------

	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guid)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------





	-- -------------------------------------------------------------------------------------
	-- FILTRO por tbItemClass
	-- -------------------------------------------------------------------------------------
--	DECLARE @tmpItemClass TABLE(ic_id INT PRIMARY KEY)
--	IF @strItemClass = '-1' OR @strItemClass = ''
--		BEGIN
--			INSERT INTO @tmpItemClass (ic_id)	SELECT tic.ic_id
--			                                 		FROM tbItemClass tic
--		END
--	ELSE
--		BEGIN
--			INSERT INTO @tmpItemClass ( ic_id)	SELECT items
--			                                  		FROM dbo.fnSplitTable(@strItemClass,',') fst
--		END
	-- -------------------------------------------------------------------------------------



	DECLARE @fun_id INT
	SET @fun_id = 1

	--
	--* Me guardo el Simbolo de la Moneda de la lista.
	declare @lcurr_symbol_oflist NVARCHAR(50)

	set @lcurr_symbol_oflist = ( select tc.curr_symbol
	                             from tbsysCurrency			tc
								 where tc.curr_id =  @currList_id )

	--select @lcurr_symbol_oflist
	--**
	--

	SELECT 	I.item_code																				[item_code],
			I.item_desc																				[item_desc],

			case when @currList_id = -1 then
				PLI1.prli_price
			else
				dbo.fnGetExchange2(@comp_id,PLI1.prli_price,cc1.curr_id,@currList_id,0,0,0,0) end	 [Neto],

			case when @currList_id = -1 then
				PLI1.prli_price + (pli1.prli_price * IsNull(ttn.tax_percentage,0) / 100)
			else
				dbo.fnGetExchange2(@comp_id,PLI1.prli_price + (pli1.prli_price * IsNull(ttn.tax_percentage,0) / 100),cc1.curr_id,@currList_id,0,0,0,0) end	[masIVA],

			case when @currList_id = -1 then
				CC1.curr_symbol
			else
				@lcurr_symbol_oflist
			end																						[curr_desc],
			C.cat_desc																				[cat_desc],
			SC.subcat_desc																			[subcat_desc],
			isnull(B.brand_desc,'')																	[brand_desc],

			ISNULL(I.item_weight,0)																	[Weigth],

			case when @currList_id = -1 then
				PLI1.prli_price * ISNULL(I.item_weight,0)
			else
				dbo.fnGetExchange2(@comp_id,PLI1.prli_price,cc1.curr_id,@currList_id,0,0,0,0) * ISNULL(I.item_weight,0)
			end																						[PriceXWeight],
			case when @currList_id = -1 then
				(PLI1.prli_price + (pli1.prli_price * IsNull(ttn.tax_percentage,0) / 100)) * ISNULL(I.item_weight,0)
			else
				(dbo.fnGetExchange2(@comp_id,PLI1.prli_price + (pli1.prli_price * IsNull(ttn.tax_percentage,0) / 100),cc1.curr_id,@currList_id,0,0,0,0)) * ISNULL(I.item_weight,0)
			end																						[PriceIVAXWeight],
			convert(DECIMAL(19,5),ttn.tax_percentage)												[tax_percentage],
			case when @currList_id = -1 then
				(PLI1.prli_price + (pli1.prli_price * IsNull(ttn.tax_percentage,0) / 100)) - (PLI1.prli_price)
			else
				(dbo.fnGetExchange2(@comp_id,PLI1.prli_price + (pli1.prli_price * IsNull(ttn.tax_percentage,0) / 100),cc1.curr_id,@currList_id,0,0,0,0)) - (dbo.fnGetExchange2(@comp_id,PLI1.prli_price,cc1.curr_id,@currList_id,0,0,0,0)) end	[IVAImporte]





	INTO #tmp_PriceList

	FROM	dbo.tbItem								I					WITH (NOLOCK)

			LEFT JOIN [tbPresentation]				P					WITH (NOLOCK)
			ON	P.[comp_id]							= I.[comp_id]
			AND P.[pres_id]							= I.[pres_id]

			LEFT JOIN tbCategory					C					WITH (NOLOCK)
			ON	C.[comp_id]							= I.[comp_id]
			AND C.[cat_id]							= I.[cat_id]

			LEFT JOIN tbSubCategory					SC					WITH (NOLOCK)
			ON	SC.[comp_id]						= I.[comp_id]
			AND SC.[cat_id]							= I.[cat_id]
			AND SC.[subcat_id]						= I.[subcat_id]

			LEFT JOIN tbBrand						B					WITH (NOLOCK)
			ON	B.[comp_id]							= I.[comp_id]
			AND B.[brand_id]						= I.[brand_id]

			LEFT JOIN	tbBranch					BR					WITH (NOLOCK)
			ON  BR.[comp_id]						= I.[comp_id]
			AND BR.[bra_id]							= I.[bra_id]

			LEFT JOIN dbo.tbByOrder					BO					WITH (NOLOCK)
			ON	BO.[comp_id]						= I.[comp_id]
			AND BO.[byor_id]						= I.[byor_id]

			left JOIN [tbsysOptionsValues]			O					WITH (NOLOCK)
			ON	o.[optval_id]						= I.[item_liquidation]
			AND	o.[optval_class]					= 1
			and o.lang_id							= @lang_id

			Inner join tbPriceListItems				PLI1				WITH (NOLOCK)
			on	PLI1.[comp_id]						= I.[comp_id]
			and PLI1.[prli_id]						= @prli_id1
			and PLI1.item_id						= I.item_id

			Inner JOIN tbsysCurrency				CC1					WITH (NOLOCK)
			ON	CC1.[curr_id]						= PLI1.[curr_id]

			LEFT JOIN vwItemTaxesOnlyOneIvaTax		vit					WITH (NOLOCK)
			ON	vit.comp_id							= i.comp_id
			AND vit.item_id							= i.item_id

			LEFT JOIN tbTaxName						ttn					WITH (NOLOCK)
			ON	ttn.comp_id							= vit.comp_id
			AND ttn.tax_id							= vit.tax_id

			INNER JOIN vwsysTaxClassIVA_Taxes		vtcit				WITH (NOLOCK)
			ON vtcit.tax_class						= ttn.tax_class

			INNER JOIN vwItems_ParentStatus			vwr					WITH (NOLOCK)
			ON	vwr.comp_id							= i.comp_id
			AND vwr.item_id						    = i.item_id

			INNER JOIN @tblComplexFilter_Items		tempITEM
			ON tempitem.item_id						= I.item_id


			WHERE	I.[comp_id]						=	@comp_id 											AND
					(@bra_id						= -1			OR I.[bra_id]		=	@bra_id) 		AND
					(@curr_id						= -1			OR CC1.[curr_id]	=	@curr_id)		AND
					(@stor_id						= -1			OR dbo.fnGetAStock(@comp_id, @stor_id, i.item_id,999999999)> 0 )	AND
					IsNull(I.item_disabledInPriceList,'False') = 'False'									AND
					vtcit.tax_class					= 1														AND
					(
						(@displayType				= 0 AND			PLI1.prli_price > 0)		OR
						(@displayType				= 1)
					)






	IF @orderby = 1 -- Descripcion
		BEGIN
			SELECT * FROM #tmp_PriceList tmp
			ORDER BY	tmp.item_desc
		END
	ELSE
		IF @orderby = 2 -- Categoría, SubCategoría, Descripción
			BEGIN
				SELECT * FROM #tmp_PriceList tmp
				ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.item_desc
			END
		ELSE
			IF @orderby = 3 -- Categoría, SubCategoría, Código
				BEGIN
					SELECT * FROM #tmp_PriceList tmp
					ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.item_code
				END
			ELSE
				IF @orderby = 4 -- Còdigo
					BEGIN
						SELECT * FROM #tmp_PriceList tmp
						ORDER BY tmp.item_code ASC
					END
						IF @orderby = 5 -- Marca, Descripción
							BEGIN
								SELECT * FROM #tmp_PriceList tmp
								ORDER BY tmp.brand_desc, tmp.item_desc
							END

						ELSE
							IF @orderby = 6 -- Marca, Código
								BEGIN
									SELECT * FROM #tmp_PriceList tmp
									ORDER BY tmp.brand_desc,tmp.item_code
								END
							ELSE
								IF @orderby = 7 -- Categoría, SubCategoría, Marca, Descripción
									BEGIN
										SELECT * FROM #tmp_PriceList tmp
										ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.brand_desc,tmp.item_desc
									END
										IF @orderby = 8 -- Categoría, SubCategoría, Marca, Código
											BEGIN
												SELECT * FROM #tmp_PriceList tmp
												ORDER BY tmp.cat_desc, tmp.subcat_desc,tmp.brand_desc,tmp.item_code
											END



	exec [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id,	@page_id





	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/
	SELECT
--				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
--      		 WHERE t.ctrl_id = 43
--      		 --AND t.[lang_id] = @lang_id
--      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params1],
--
--			CASE @option WHEN -1 THEN
--				(SELECT		tut.utexts_desc
--					FROM	tbsysUniqueTexts tut
--					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
--			ELSE
--				(SELECT		tov.optval_desc + ISNULL(@item_desc,'')
--					FROM	dbo.tbsysOptionsValues tov
--					WHERE	tov.optval_class	= 2
--					AND		tov.optval_id		= @option
--					AND		tov.lang_id			= @lang_id)
--			END																															[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 109
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			(SELECT tpl.prli_desc
				FROM dbo.tbPriceList tpl
				WHERE tpl.prli_id = @prli_id1)																							[params4],

--				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
--      		 WHERE t.ctrl_id = 36
--      		 --AND t.[lang_id] = @lang_id
--      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params11],
--
--				CASE @cat_id WHEN -1 THEN
--					(SELECT		tut.utexts_desc
--						FROM	tbsysUniqueTexts tut
--						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
--				ELSE
--					(SELECT		tc.cat_desc
--						FROM	dbo.tbCategory tc
--						WHERE	tc.cat_id = @cat_id)
--				END																														[params12],

--				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
--      		 WHERE t.ctrl_id = 38
--      		 --AND t.[lang_id] = @lang_id
--      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params13],
--
--				CASE @subcat_id WHEN -1 THEN
--					(SELECT		tut.utexts_desc
--						FROM	tbsysUniqueTexts tut
--						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
--				ELSE
--					(SELECT		tsc.subcat_desc
--						FROM	dbo.tbSubCategory tsc
--						WHERE	tsc.subcat_id = @subcat_id)
--				END																														[params14],

--				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
--      		 WHERE t.ctrl_id = 73
--      		 --AND t.[lang_id] = @lang_id
--      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],
--
--				CASE @brand_id WHEN -1 THEN
