				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 109
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			(SELECT tpl.prli_desc
				FROM dbo.tbPriceList tpl
				WHERE tpl.prli_id = @prli_id1)																							[params4],

--				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
--      		 WHERE t.ctrl_id = 36
--      		 --AND t.[lang_id] = @lang_id
--      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params11],
--
--				CASE @cat_id WHEN -1 THEN
--					(SELECT		tut.utexts_desc
--						FROM	tbsysUniqueTexts tut
--						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
--				ELSE
--					(SELECT		tc.cat_desc
--						FROM	dbo.tbCategory tc
--						WHERE	tc.cat_id = @cat_id)
--				END																														[params12],

--				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
--      		 WHERE t.ctrl_id = 38
--      		 --AND t.[lang_id] = @lang_id
--      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)				[params13],
--
