CREATE procedure [dbo].[spPriceList_Load]
(
		@comp_id			int,
		@typelist			int,
		@prli_id			int,
--		@coslis_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			int,
		@pres_id			int,
		@curr_id			Int,
		@option				INT,
		@supp_id			INT,
		@order				int
)
AS

BEGIN

	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------
	/*
	Declare
		@comp_id			int,
		@typelist			int,
		@prli_id			int,
		@coslis_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			INT,
		--@bra_id			int,
		@pres_id			int,
		@curr_id			int,
		@option				INT,
		@order				int
	Select
		@comp_id			= 1,
		@typelist			= 1,
		@prli_id			= 1,
		@cat_id				=-1,
		@subcat_id			=-1,
		@brand_id			=-1,
		--@bra_id			=-1,
		@pres_id			=-1,
		@curr_id			=-1,
		@option				= -1,
		@order				= 7
	*/
	-- -----------------------------------------------------------------



	IF @typelist = 1
	BEGIN

		SELECT	I.item_desc,
				I.item_code,
				PLI.item_id,
				PLI.prli_price [price],
				CUR.curr_desc

		FROM	dbo.tbPriceListItems			PLI

				inner join [tbItem]				I
				on	i.comp_id	= pli.comp_id
				and i.item_id	= pli.item_id

				inner join [tbsysCurrency]		CUR
				on	CUR.curr_id = PLI.curr_id

				INNER JOIN tbBrand tb
					ON		tb.comp_id	= i.comp_id
						AND tb.brand_id = i.brand_id
				INNER JOIN tbCategory tc
					ON		tc.comp_id	= i.comp_id
						AND tc.cat_id	= i.cat_id
				INNER JOIN tbSubCategory tsc
					ON		tsc.comp_id = i.comp_id
						AND tsc.cat_id	= i.cat_id
						AND tsc.subcat_id = i.subcat_id

	--	WHERE	PLI.item_id in (SELECT I.item_id
	--							FROM dbo.tbItem I
	--							WHERE	I.comp_id	 = @comp_id
	--							and		(@cat_id	 = -1 or I.cat_id     = @cat_id)
	--							and		(@subcat_id  = -1 or I.subcat_id  = @subcat_id)
	--							and		(@brand_id	 = -1 or I.brand_id   = @brand_id)
	--							and		(@pres_id	 = -1 or I.pres_id	  = @pres_id))


		WHERE
				I.comp_id	 = @comp_id
		and		IsNull(I.item_disabled,'False')   = 'False'
		and		(@cat_id	 = -1 or I.cat_id     = @cat_id)
		and		(@subcat_id  = -1 or I.subcat_id  = @subcat_id)
		and		(@brand_id	 = -1 or I.brand_id   = @brand_id)
		and		(@pres_id	 = -1 or I.pres_id	  = @pres_id)

		and		PLI.prli_id		=  @prli_id
		and		(@curr_id		= -1 or PLI.curr_id  = @curr_id)

		and		((@option = -1 ) or
				( @option = 1 and PLI.prli_price = 0)  OR
				( @option = 4 and PLI.prli_price =  0 )  OR
				( @option = 5 and PLI.prli_price =  0 )  or
				( @option = 6 and PLI.prli_price <> 0 )  OR
				( @option = 7 and PLI.prli_price <> 0 )  or
				( @option = 2 and PLI.prli_price <> 0) or
				( @option = 3 and PLI.prli_cd
							Between dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'false')
							And		dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'true')))
		and		(@supp_id		= -1 or I.supp_id			=  @supp_id)

		-- todos los campos que son incluidos en un "order by" con "case" deben ser convertidos al mismo tipo, en este caso varchar
		-- prestar atención si se agregan nuevas opciones
		ORDER BY CASE
					When @order = 0 Then convert(varchar,I.item_id)
					When @order = 1 Then I.item_code
					When @order = 2 Then dbo.fnStrPADL( rtrim(I.item_code),50,' ')
					When @order = 3 Then i.item_desc + i.item_code
					When @order = 4 THEN tb.brand_desc
					When @order = 5 Then tc.cat_desc + tsc.subcat_desc + i.item_code
					When @order = 6 Then tc.cat_desc + tsc.subcat_desc + i.item_desc
					WHEN @order = 7 THEN convert(varchar,i.item_disabled)
					ELSE I.item_code
				 END

	END

	ELSE

		IF @typelist = 2
		BEGIN

			SELECT	I.item_desc,
					I.item_code,
					ICL.item_id,
					ICL.coslis_price [price],
					CUR.curr_desc

			FROM	dbo.tbItemCostList				ICL

					inner join [tbItem]				I
					on	i.comp_id = icl.comp_id
					and i.item_id = icl.item_id

					inner join [tbsysCurrency]		CUR
					on CUR.curr_id = ICL.curr_id

					INNER JOIN tbBrand tb
						ON		tb.comp_id	= i.comp_id
							AND tb.brand_id = i.brand_id
					INNER JOIN tbCategory tc
						ON		tc.comp_id	= i.comp_id
							AND tc.cat_id	= i.cat_id
					INNER JOIN tbSubCategory tsc
						ON		tsc.comp_id = i.comp_id
							AND tsc.cat_id	= i.cat_id
							AND tsc.subcat_id = i.subcat_id


			WHERE
--					ICL.item_id in (SELECT I.item_id
--									FROM dbo.tbItem I
--									WHERE	I.comp_id	 = @comp_id
--
--									and		(@cat_id	 = -1 or I.cat_id       = @cat_id)
--									and		(@subcat_id  = -1 or I.subcat_id    = @subcat_id)
--									and		(@brand_id	 = -1 or I.brand_id     = @brand_id)
--									and		(@pres_id	 = -1 or I.pres_id	    = @pres_id))
					I.comp_id = @comp_id
			and		IsNull(I.item_disabled,'False')   = 'False'
			and		(@cat_id	 = -1 or I.cat_id     = @cat_id)
			and		(@subcat_id  = -1 or I.subcat_id  = @subcat_id)
			and		(@brand_id	 = -1 or I.brand_id   = @brand_id)
			and		(@pres_id	 = -1 or I.pres_id	  = @pres_id)

			and		(@prli_id	 = ICL.coslis_id)
			and		(@curr_id	 = -1 or ICL.curr_id	= @curr_id)

			and		((@option = -1 ) OR
					( @option = 4 and isnull(i.item_disabled,'false') = 'False' AND ICL.coslis_price =  0 )  OR
					( @option = 5 and isnull(i.item_disabled,'false') = 'True'  AND ICL.coslis_price =  0 )  or
					( @option = 6 and isnull(i.item_disabled,'false') = 'False' AND ICL.coslis_price <> 0 )  OR
					( @option = 7 and isnull(i.item_disabled,'false') = 'True'  AND ICL.coslis_price <> 0 )  or
					( @option = 1 and ICL.coslis_price = 0)  or
					( @option = 2 and ICL.coslis_price <> 0) or
					( @option = 3 and ICL.coslis_cd
								Between dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'false')
								And		dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'true')))
			and		(@supp_id		= -1 or I.supp_id			=  @supp_id)

		-- todos los campos que son incluidos en un "order by" con "case" deben ser convertidos al mismo tipo, en este caso varchar
		-- prestar atención si se agregan nuevas opciones
		ORDER BY CASE
					When @order = 0 Then convert(varchar,I.item_id)
					When @order = 1 Then I.item_code
					When @order = 2 Then dbo.fnStrPADL( rtrim(I.item_code),50,' ')
					When @order = 3 Then i.item_desc + i.item_code
					When @order = 4 THEN tb.brand_desc
					When @order = 5 Then tc.cat_desc + tsc.subcat_desc + i.item_code
					When @order = 6 Then tc.cat_desc + tsc.subcat_desc + i.item_desc
					WHEN @order = 7 THEN convert(varchar,i.item_disabled)
					ELSE I.item_code
				 END


		END

		ELSE

		BEGIN

			SELECT	I.item_desc,
					I.item_code,
					ICL.item_id,
					ICL.coslis_price_aw [price],
					CUR.curr_desc

			FROM	dbo.tbItemCostList				ICL

					inner join [tbItem]				I
					on	i.comp_id = icl.comp_id
					and i.item_id = icl.item_id

					inner join [tbsysCurrency]		CUR
					on CUR.curr_id = ICL.curr_id

					INNER JOIN tbBrand tb
						ON		tb.comp_id	= i.comp_id
							AND tb.brand_id = i.brand_id
					INNER JOIN tbCategory tc
						ON		tc.comp_id	= i.comp_id
							AND tc.cat_id	= i.cat_id
					INNER JOIN tbSubCategory tsc
						ON		tsc.comp_id = i.comp_id
							AND tsc.cat_id	= i.cat_id
							AND tsc.subcat_id = i.subcat_id


			WHERE

--					ICL.item_id in (SELECT I.item_id
--									FROM dbo.tbItem I
--									WHERE	I.comp_id	 = @comp_id
--									and		(@cat_id	 = -1 or I.cat_id       = @cat_id)
--									and		(@subcat_id  = -1 or I.subcat_id    = @subcat_id)
--									and		(@brand_id	 = -1 or I.brand_id     = @brand_id)
--									and		(@pres_id	 = -1 or I.pres_id	    = @pres_id))
					I.comp_id = @comp_id
			and		IsNull(I.item_disabled,'False')   = 'False'
			and		(@cat_id	 = -1 or I.cat_id     = @cat_id)
			and		(@subcat_id  = -1 or I.subcat_id  = @subcat_id)
			and		(@brand_id	 = -1 or I.brand_id   = @brand_id)
			and		(@pres_id	 = -1 or I.pres_id	  = @pres_id)

			and		(@prli_id	 = -1 or ICL.coslis_id  = @prli_id)
			and		(@curr_id	 = -1 or ICL.curr_id	= @curr_id)

			and		((@option = -1 ) or
					(@option = 1 and ICL.coslis_price = 0)  or
					(@option = 2 and ICL.coslis_price <> 0) or
					(@option = 3 and ICL.coslis_cd
								Between dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'false')
								And		dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'true')))
			and		(@supp_id		= -1 or I.supp_id			=  @supp_id)


		-- todos los campos que son incluidos en un "order by" con "case" deben ser convertidos al mismo tipo, en este caso varchar
		-- prestar atención si se agregan nuevas opciones
		ORDER BY CASE
					When @order = 0 Then convert(varchar,I.item_id)
					When @order = 1 Then I.item_code
					When @order = 2 Then dbo.fnStrPADL( rtrim(I.item_code),50,' ')
					When @order = 3 Then i.item_desc + i.item_code
					When @order = 4 THEN tb.brand_desc
					When @order = 5 Then tc.cat_desc + tsc.subcat_desc + i.item_code
					When @order = 6 Then tc.cat_desc + tsc.subcat_desc + i.item_desc
					WHEN @order = 7 THEN convert(varchar,i.item_disabled)
					ELSE I.item_code
				 END



		END



END
GO







CREATE procedure [dbo].[spPriceList_Load4ComplexFilter]
(
		@comp_id			int,
		@typelist			int,
		@prli_id			int,
		@curr_id			Int,
		@option				INT,
		@order				INT,
		@guid				NVARCHAR(50)
)
AS

BEGIN

	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------
	/*
	Declare
		@comp_id			int,
		@typelist			int,
		@prli_id			int,
		@coslis_id			int,
		@cat_id				int,
		@subcat_id			int,
		@brand_id			INT,
		--@bra_id			int,
		@pres_id			int,
		@curr_id			int,
		@option				INT,
		@order				int
	Select
		@comp_id			= 1,
		@typelist			= 1,
		@prli_id			= 1,
		@cat_id				=-1,
		@subcat_id			=-1,
		@brand_id			=-1,
		--@bra_id			=-1,
		@pres_id			=-1,
		@curr_id			=-1,
		@option				= -1,
		@order				= 7
	*/
	-- -----------------------------------------------------------------


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros
	-- NOTA: Para buscar todas las incidencias
	-- de este método ejecutar el "BuscarTexto" en la base de datos
	-- con el valor de referencia "#8600"
	-- Página de EJEMPLO:App_Reports_App_WebForms_wfmRptFilters_PriceLists2_Testing
	-- -------------------------------------------------------------
	DECLARE @objGUID AS UNIQUEIDENTIFIER
	SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@guid)
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf      WITH (NOLOCK)
			WHERE tcf.sl_guid = @objGUID      AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

	DECLARE @tmpTable TABLE (
								item_desc	NVARCHAR(300),
								item_code	NVARCHAR(50),
								item_id		INT,
								price		DECIMAL(25,6),
								curr_desc   NVARCHAR(50),
								[intOrder]  INT IDENTITY(1,1)
							)



	IF @typelist = 1
		BEGIN


			INSERT INTO @tmpTable(item_desc, item_code, item_id, price, curr_desc)

			SELECT	I.item_desc,
					I.item_code,
					PLI.item_id,
					PLI.prli_price [price],
					CUR.curr_desc

			FROM	dbo.tbPriceListItems			PLI		WITH (NOLOCK)

					INNER JOIN @tblComplexFilter_Items tmp
						ON tmp.item_id = pli.item_id

					inner join [tbItem]				I		WITH (NOLOCK)
					on	i.comp_id	= pli.comp_id
					and i.item_id	= pli.item_id

					inner join [tbsysCurrency]		CUR		WITH (NOLOCK)
					on	CUR.curr_id = PLI.curr_id

					INNER JOIN tbBrand tb		WITH (NOLOCK)
						ON		tb.comp_id	= i.comp_id
							AND tb.brand_id = i.brand_id
					INNER JOIN tbCategory tc		WITH (NOLOCK)
						ON		tc.comp_id	= i.comp_id
							AND tc.cat_id	= i.cat_id
					INNER JOIN tbSubCategory tsc		WITH (NOLOCK)
						ON		tsc.comp_id = i.comp_id
							AND tsc.cat_id	= i.cat_id
							AND tsc.subcat_id = i.subcat_id



		--	WHERE	PLI.item_id in (SELECT I.item_id
		--							FROM dbo.tbItem I
		--							WHERE	I.comp_id	 = @comp_id
		--							and		(@cat_id	 = -1 or I.cat_id     = @cat_id)
		--							and		(@subcat_id  = -1 or I.subcat_id  = @subcat_id)
		--							and		(@brand_id	 = -1 or I.brand_id   = @brand_id)
		--							and		(@pres_id	 = -1 or I.pres_id	  = @pres_id))


			WHERE
					I.comp_id	 = @comp_id
			and		IsNull(I.item_disabled,'False')   = 'False'
			--and		(@cat_id	 = -1 or I.cat_id     = @cat_id)
			--and		(@subcat_id  = -1 or I.subcat_id  = @subcat_id)
			--and		(@brand_id	 = -1 or I.brand_id   = @brand_id)
			--and		(@pres_id	 = -1 or I.pres_id	  = @pres_id)

			and		PLI.prli_id		=  @prli_id
			and		(@curr_id		= -1 or PLI.curr_id  = @curr_id)

			and		((@option = -1 ) or
					( @option = 1 and PLI.prli_price = 0)  OR
					( @option = 4 and PLI.prli_price =  0 )  OR
					( @option = 5 and PLI.prli_price =  0 )  or
					( @option = 6 and PLI.prli_price <> 0 )  OR
					( @option = 7 and PLI.prli_price <> 0 )  or
					( @option = 2 and PLI.prli_price <> 0) or
					( @option = 3 and PLI.prli_cd
								Between dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'false')
								And		dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'true')))
			--and		(@supp_id		= -1 or I.supp_id			=  @supp_id)

			-- todos los campos que son incluidos en un "order by" con "case" deben ser convertidos al mismo tipo, en este caso varchar
			-- prestar atención si se agregan nuevas opciones



			ORDER BY CASE
						When @order = 0 Then convert(varchar,I.item_id)
						When @order = 1 Then I.item_code
						When @order = 2 Then dbo.fnStrPADL( rtrim(I.item_code),50,' ')
						When @order = 3 Then i.item_desc + i.item_code
						When @order = 4 THEN tb.brand_desc
						When @order = 5 Then tc.cat_desc + tsc.subcat_desc + i.item_code
						When @order = 6 Then tc.cat_desc + tsc.subcat_desc + i.item_desc
						WHEN @order = 7 THEN convert(varchar,i.item_disabled)
						ELSE I.item_code
					 END


			IF @@ROWCOUNT = 1
				BEGIN
					INSERT INTO @tmpTable( item_id, item_desc)
						SELECT	-1,NULL
				END
			SELECT
				item_desc,
				item_code,
				item_id,
				price,
				curr_desc,
				ISNULL(tpl.prli_desc,'')	[ListName]
				FROM @tmpTable
				LEFT JOIN tbPriceList AS tpl	 WITH (NOLOCK)
					ON	tpl.comp_id = @comp_id AND
						tpl.prli_id = @prli_id
			ORDER BY intOrder


		END

	ELSE

		IF @typelist = 2
			BEGIN

				INSERT INTO @tmpTable(item_desc, item_code, item_id, price, curr_desc)

				SELECT	I.item_desc,
						I.item_code,
						ICL.item_id,
						ICL.coslis_price [price],
						CUR.curr_desc

				FROM	dbo.tbItemCostList				ICL		WITH (NOLOCK)


						INNER JOIN @tblComplexFilter_Items tmp
							ON tmp.item_id = icl.item_id

						inner join [tbItem]				I		WITH (NOLOCK)
						on	i.comp_id = icl.comp_id
						and i.item_id = icl.item_id

						inner join [tbsysCurrency]		CUR		WITH (NOLOCK)
						on CUR.curr_id = ICL.curr_id

						INNER JOIN tbBrand tb		WITH (NOLOCK)
							ON		tb.comp_id	= i.comp_id
								AND tb.brand_id = i.brand_id
						INNER JOIN tbCategory tc		WITH (NOLOCK)
							ON		tc.comp_id	= i.comp_id
								AND tc.cat_id	= i.cat_id
						INNER JOIN tbSubCategory tsc		WITH (NOLOCK)
							ON		tsc.comp_id = i.comp_id
								AND tsc.cat_id	= i.cat_id
								AND tsc.subcat_id = i.subcat_id

				WHERE
	--					ICL.item_id in (SELECT I.item_id
	--									FROM dbo.tbItem I
	--									WHERE	I.comp_id	 = @comp_id
	--
	--									and		(@cat_id	 = -1 or I.cat_id       = @cat_id)
	--									and		(@subcat_id  = -1 or I.subcat_id    = @subcat_id)
	--									and		(@brand_id	 = -1 or I.brand_id     = @brand_id)
	--									and		(@pres_id	 = -1 or I.pres_id	    = @pres_id))
						I.comp_id = @comp_id
				and		IsNull(I.item_disabled,'False')   = 'False'
				--and		(@cat_id	 = -1 or I.cat_id     = @cat_id)
				--and		(@subcat_id  = -1 or I.subcat_id  = @subcat_id)
				--and		(@brand_id	 = -1 or I.brand_id   = @brand_id)
				--and		(@pres_id	 = -1 or I.pres_id	  = @pres_id)

				and		(@prli_id	 = ICL.coslis_id)
				and		(@curr_id	 = -1 or ICL.curr_id	= @curr_id)

				and		((@option = -1 ) OR
						( @option = 4 and isnull(i.item_disabled,'false') = 'False' AND ICL.coslis_price =  0 )  OR
						( @option = 5 and isnull(i.item_disabled,'false') = 'True'  AND ICL.coslis_price =  0 )  or
						( @option = 6 and isnull(i.item_disabled,'false') = 'False' AND ICL.coslis_price <> 0 )  OR
						( @option = 7 and isnull(i.item_disabled,'false') = 'True'  AND ICL.coslis_price <> 0 )  or
						( @option = 1 and ICL.coslis_price = 0)  or
						( @option = 2 and ICL.coslis_price <> 0) or
						( @option = 3 and ICL.coslis_cd
									Between dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'false')
									And		dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'true')))
				--and		(@supp_id		= -1 or I.supp_id			=  @supp_id)

			-- todos los campos que son incluidos en un "order by" con "case" deben ser convertidos al mismo tipo, en este caso varchar
			-- prestar atención si se agregan nuevas opciones




				ORDER BY CASE
							When @order = 0 Then convert(varchar,I.item_id)
							When @order = 1 Then I.item_code
							When @order = 2 Then dbo.fnStrPADL( rtrim(I.item_code),50,' ')
							When @order = 3 Then i.item_desc + i.item_code
							When @order = 4 THEN tb.brand_desc
							When @order = 5 Then tc.cat_desc + tsc.subcat_desc + i.item_code
							When @order = 6 Then tc.cat_desc + tsc.subcat_desc + i.item_desc
							WHEN @order = 7 THEN convert(varchar,i.item_disabled)
							ELSE I.item_code
						 END

				IF @@ROWCOUNT = 1
					BEGIN
						INSERT INTO @tmpTable( item_id, item_desc)
							SELECT	-1,NULL
					END
				SELECT
					item_desc,
					item_code,
					item_id,
					price,
					curr_desc,
					ISNULL(tpl.coslis_desc,'')	[ListName]
					FROM @tmpTable
				LEFT JOIN  tbItemCostListName  AS tpl	 WITH (NOLOCK)
					ON	tpl.comp_id		= @comp_id AND
						tpl.coslis_id	= @prli_id
				ORDER BY intOrder



			END

		ELSE

			BEGIN


					INSERT INTO @tmpTable(item_desc, item_code, item_id, price, curr_desc)
					SELECT	I.item_desc,
							I.item_code,
							ICL.item_id,
							ICL.coslis_price_aw [price],
							CUR.curr_desc

					FROM	dbo.tbItemCostList				ICL		WITH (NOLOCK)

							INNER JOIN @tblComplexFilter_Items tmp
								ON tmp.item_id = icl.item_id

							inner join [tbItem]				I		WITH (NOLOCK)
							on	i.comp_id = icl.comp_id
							and i.item_id = icl.item_id

							inner join [tbsysCurrency]		CUR		WITH (NOLOCK)
							on CUR.curr_id = ICL.curr_id

							INNER JOIN tbBrand tb		WITH (NOLOCK)
								ON		tb.comp_id	= i.comp_id
									AND tb.brand_id = i.brand_id
							INNER JOIN tbCategory tc		WITH (NOLOCK)
								ON		tc.comp_id	= i.comp_id
									AND tc.cat_id	= i.cat_id
							INNER JOIN tbSubCategory tsc		WITH (NOLOCK)
								ON		tsc.comp_id = i.comp_id
									AND tsc.cat_id	= i.cat_id
									AND tsc.subcat_id = i.subcat_id


					WHERE

		--					ICL.item_id in (SELECT I.item_id
		--									FROM dbo.tbItem I
		--									WHERE	I.comp_id	 = @comp_id
		--									and		(@cat_id	 = -1 or I.cat_id       = @cat_id)
		--									and		(@subcat_id  = -1 or I.subcat_id    = @subcat_id)
		--									and		(@brand_id	 = -1 or I.brand_id     = @brand_id)
		--									and		(@pres_id	 = -1 or I.pres_id	    = @pres_id))
							I.comp_id = @comp_id
					and		IsNull(I.item_disabled,'False')   = 'False'
					--and		(@cat_id	 = -1 or I.cat_id     = @cat_id)
					--and		(@subcat_id  = -1 or I.subcat_id  = @subcat_id)
					--and		(@brand_id	 = -1 or I.brand_id   = @brand_id)
					--and		(@pres_id	 = -1 or I.pres_id	  = @pres_id)

					and		(@prli_id	 = -1 or ICL.coslis_id  = @prli_id)
					and		(@curr_id	 = -1 or ICL.curr_id	= @curr_id)

					and		((@option = -1 ) or
							(@option = 1 and ICL.coslis_price = 0)  or
							(@option = 2 and ICL.coslis_price <> 0) or
							(@option = 3 and ICL.coslis_cd
										Between dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'false')
										And		dbo.fnGetEnd_or_BeginOfDate(GETDATE(), 'true')))
					--and		(@supp_id		= -1 or I.supp_id			=  @supp_id)


				-- todos los campos que son incluidos en un "order by" con "case" deben ser convertidos al mismo tipo, en este caso varchar
				-- prestar atención si se agregan nuevas opciones
				ORDER BY CASE
							When @order = 0 Then convert(varchar,I.item_id)
							When @order = 1 Then I.item_code
							When @order = 2 Then dbo.fnStrPADL( rtrim(I.item_code),50,' ')
							When @order = 3 Then i.item_desc + i.item_code
							When @order = 4 THEN tb.brand_desc
							When @order = 5 Then tc.cat_desc + tsc.subcat_desc + i.item_code
							When @order = 6 Then tc.cat_desc + tsc.subcat_desc + i.item_desc
							WHEN @order = 7 THEN convert(varchar,i.item_disabled)
							ELSE I.item_code
						 END


				IF @@ROWCOUNT = 1
					BEGIN
						INSERT INTO @tmpTable( item_id, item_desc)
							SELECT	-1,NULL
					END
				SELECT
					item_desc,
					item_code,
					item_id,
					price,
					curr_desc,
					ISNULL(tpl.coslis_desc,'')	[ListName]
					FROM @tmpTable
				LEFT JOIN  tbItemCostListName  AS tpl	 WITH (NOLOCK)
					ON	tpl.comp_id		= @comp_id AND
						tpl.coslis_id	= @prli_id
				ORDER BY intOrder



			END



END
GO






CREATE PROCEDURE [dbo].[spPriceList_MailOfChanges]
(
	@comp_id	int,
	@lang_id	INT,
	@bra_id		int
)

as set NOCOUNT on


BEGIN

-- ----------------------------------------------
-- TESTING
-- ----------------------------------------------
/*
	declare
		@comp_id	INT,
		@lang_id	INT,
		@bra_id		INT
	select
		@comp_id	= 1,
		@lang_id	= 2,
		@bra_id		= 1
*/
-- ----------------------------------------------

	/*ACA OBTENEMOS LA PROCESSING DATE DE LA SUCURSAL
	  Y LA CONVERTIMOS EN DATEFROM Y DATETO					*/
	declare
		@datefrom	DATETIME,
		@dateto		DATETIME

	select
		@datefrom		= tb.bra_processingDate,
		@dateto			= tb.bra_processingDate
	from tbBranch									tb
	where	tb.comp_id	= @comp_id
	and		tb.bra_id	= @bra_id

	set @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	/*********************************************************/

		-- Arranca servicio de email
		--exec msdb.dbo.sysmail_start_sp


		--Variables para el cursor Principal
		--USUARIOS QUE RECIBIRAN MAIL
		declare
			@user_id	INT,
			@user_nick	nvarchar(100),
			@user_email	nvarchar(200)

		--Variables del Cursor Interno
		--Precios que Cambiaron
		declare
			@cat_desc		nvarchar(200),
			@subcat_desc	nvarchar(200),
			@item_code		nvarchar(200),
			@item_desc		nvarchar(200),
			@plh_price		decimal(19,6),
			@curr_symbol	nvarchar(10)

		--variables para el formateo del html email
		DECLARE
			@subject	NVARCHAR(MAX),
			@body		NVARCHAR(MAX)



		--Variables de Trabajo
		DECLARE
			@lFirstTime		BIT,
			@table			nvarchar(max),
			@closeTable		nvarchar(max)



		/*ACA ABRIMOS LA TABLA EN DONDE LUEGO METEREMOS LAS ROWS Y CELLS*/
		set @table = '<table style="font-family:Verdana;font-size:x-small;color:Black" ' +
								'cellpadding="1" cellspacing="1" border="1">'
		set @closeTable = '</table><br /><br />'

		set @body = ''

		select @subject = tut.utexts_desc from tbsysUniqueTexts tut where tut.lang_id = @lang_id and tut.utexts_id = 224037


		DECLARE CURSOR_USERS CURSOR LOCAL  FAST_FORWARD FOR

			select
				tu.[user_id],
				tu.user_nick,
				tu.user_email

			from tbPriceList_MailingOfChanges					tplmoc

				inner join tbUser								tu
				on tu.[user_id]				= tplmoc.[user_id]

			where	tplmoc.comp_id			= @comp_id
			and		tplmoc.bra_id			= @bra_id
			and		tplmoc.prmc_disabled	= 'False'
			and		NOT tu.user_email		IS NULL


			OPEN	CURSOR_USERS
			FETCH	CURSOR_USERS
			INTO
				@user_id,
				@user_nick,
				@user_email

		WHILE @@FETCH_STATUS = 0
				BEGIN
					--ACA VAMOS A HACER OTRO CURSOR PARA PODER ARMAR LA TABLA CON LAS COSAS QUE CAMBIARON Y ANTES DE QUE FINALICE EL PRIMER CURSOR
					--ENVIAREMOS EL MAIL
					DECLARE CURSOR_CHANGES CURSOR FOR

						--DATOS DE LOS PRECIOS QUE CAMBIARON
						select
							tc.cat_desc,
							tsc.subcat_desc,
							ti.item_code,
							ti.item_desc,
							tplh.plh_price,
							tc2.curr_symbol

						from tbPriceListHistory						tplh

							inner join tbPriceList					tpl
							on	tpl.comp_id		= tplh.comp_id
							AND tpl.prli_id		= tplh.prli_id

							inner join tbItem						ti
							on	tplh.comp_id	= ti.comp_id
							and ti.item_id		= tplh.item_id

							inner join tbCategory					tc
							on  tc.comp_id		= ti.comp_id
							AND tc.cat_id		= ti.cat_id

							inner join tbSubCategory				tsc
							on	tsc.comp_id		= ti.comp_id
							AND tsc.cat_id		= ti.cat_id
							AND tsc.subcat_id	= ti.subcat_id

							inner join tbsysCurrency				tc2
							on tc2.curr_id		= tplh.curr_id

						where tplh.comp_id									= @comp_id
						and tplh.plh_cd										between @datefrom and @dateto
						and isnull(tpl.prli_DisableMailOfChanges,'False')	= 'False'



					OPEN	CURSOR_CHANGES
					FETCH	CURSOR_CHANGES
					INTO
						@cat_desc,
						@subcat_desc,
						@item_code,
						@item_desc,
						@plh_price,
						@curr_symbol

						WHILE @@FETCH_STATUS = 0
						BEGIN

							declare
								@lROW as nvarchar(max)

							select @lROW =
								'<tr><td align="center">'			+
									@cat_desc						+
								'</td><td align="center">'			+
									@subcat_desc					+
								'</td><td align="center">'			+
									@item_code						+
								'</td><td align="center">'			+
									@item_desc						+
								'</td><td align="center">'			+
									convert(varchar,@plh_price)		+
								'</td><td align="center">'			+
									@curr_symbol					+
								'</td></tr>'

							BEGIN TRY
								set @body = @body + ltrim(rtrim(@lROW))
							END TRY
							BEGIN CATCH
							END CATCH
							set @lROW = ''

					FETCH	CURSOR_CHANGES
					INTO
						@cat_desc,
						@subcat_desc,
						@item_code,
						@item_desc,
						@plh_price,
						@curr_symbol

					END


					CLOSE		CURSOR_CHANGES
					DEALLOCATE	CURSOR_CHANGES

					--CREAMOS EL BODY
					set @body = @table + ltrim(rtrim(@body)) + @closeTable


					--
					--ENVIAMOS EL MAIL AL USUARIO
					EXEC spSystem_sendEMail @comp_id,
											@user_email,
											NULL,
											@subject,
											'HTML',
											@body,
											NULL,
											NULL,
											'',
											@user_id



			FETCH	CURSOR_USERS
			INTO
				@user_id,
				@user_nick,
				@user_email

			END

		CLOSE		CURSOR_USERS
		DEALLOCATE	CURSOR_USERS

END
GO








CREATE PROCEDURE spPriceListImports_getCombo
(
	@comp_id		INT
)
AS
SET NOCOUNT ON

BEGIN


	SELECT	tpli.prliimp_id		[ID],
			tpli.prliimp_desc	[Desc]

	FROM	tbPriceListImports tpli

	WHERE	tpli.comp_id = @comp_id


END
GO







CREATE PROCEDURE spPriceListImports_Process
(
	@comp_id		INT,
	@lang_id		INT,
	@prliimp_id		INT
)
AS
SET NOCOUNT ON


/*
DECLARE @comp_id INT, @lang_id INT, @prliimp_id INT
SELECT  @comp_id =1,  @lang_id =2,  @prliimp_id =2
*/


IF EXISTS (	SELECT	1
			FROM	tbPriceListImports			tpli
			WHERE	tpli.comp_id		= @comp_id
			AND		tpli.prliimp_id		= @prliimp_id )
BEGIN

	DECLARE @process VARCHAR(8000)
	SELECT	@process = tpli.prliimp_code
	FROM	tbPriceListImports			tpli
	WHERE	tpli.comp_id		= @comp_id
	AND		tpli.prliimp_id		= @prliimp_id

	EXEC	(@process)


END


GO






CREATE PROCEDURE [dbo].[spPriceListItem_FullUpdate]
(
	@comp_id			INT,
	@cat_id				INT,
	@subcat_id			INT,
	@item_id            INT,
	@supp_id			INT,
	@brand_id			INT,
	@type_id_from		INT,
	@list_id_from		INT,
	@type_id_to			INT,
	@list_id_to			INT,
	@update_type		INT,
	@update_value		DECIMAL(18,6),
	@curr_id			INT,
	@Item_Guid			UNIQUEIDENTIFIER,
	@user_id			INT
)
AS


BEGIN


	SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------------------

	/*
	DECLARE @comp_id			int,
			@cat_id				int,
			@subcat_id			int,
			@item_id            int,
			@supp_id			int,
			@brand_id			int,
			@type_id_from		int,	--tipo de combo seleccionado en origen (que readiobutton seleccionó)
			@list_id_from		int,
			@type_id_to			int,	--tipo de combo seleccionado en destino (que readiobutton seleccionó)
			@list_id_to			int,
			@update_type		int,
			@update_value		decimal(18,6),
			@curr_id			int

	SELECT	@comp_id			= 1,
			@cat_id				=-1,
			@subcat_id			=-1,
			@item_id            =-1,
			@supp_id			=-1,
			@brand_id			=-1,
			@list_id_from		=1,
			@list_id_to			=1,
			@type_id_from		=1,
			@type_id_to			=1,
			@update_type		=1,
			@update_value		=50,
			@curr_id			=-1

	--drop table #tmp

	*/

-- -----------------------------------------------------------------------------






	IF @user_id = -1 SET @user_id = NULL




		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros
		-- NOTA: Para buscar todas las incidencias
		-- de este método ejecutar el "BuscarTexto" en la base de datos
		-- con el valor de referencia "#8600"
		-- Página de EJEMPLO:App_Reports_App_WebForms_wfmRptFilters_PriceLists2_Testing
		-- -------------------------------------------------------------
		DECLARE @objGUID AS UNIQUEIDENTIFIER
		SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@Item_Guid)
		DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf      WITH (NOLOCK)
				WHERE tcf.sl_guid	  = @objGUID      AND
					  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
				FROM tbItem ti
				WHERE ti.comp_id = @comp_id
			END


	create table #tmp (	comp_id		int,
						item_id		int,
						prli_price	decimal(18,6),
						item_price	decimal(18,6),
						curr_id		INT,
						list_id_to	INT)




	IF @type_id_from = 1 --lista de precios
		BEGIN

			INSERT INTO [#tmp] ([comp_id], [item_id], [prli_price], [item_price], [curr_id], list_id_to)
			SELECT	L.comp_id,
					L.item_id,
					L.[prli_price],
					CASE @update_type
						WHEN 1	then L.[prli_price] + @update_value
						WHEN 2	then L.[prli_price] + (L.[prli_price] * @update_value / 100)
						WHEN 3  then L.[prli_price] * @update_value
						WHEN 4  then L.[prli_price] / dbo.fnNoZDiv( @update_value )
						WHEN 5	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_1],0) / 100)
						WHEN 6	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_2],0) / 100)
						WHEN 7	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_3],0) / 100)
						WHEN 8	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_4],0) / 100)
						WHEN 9	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_5],0) / 100)
						WHEN 10	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_6],0) / 100)
						WHEN 11	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_7],0) / 100)
						WHEN 12	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_8],0) / 100)
						WHEN 13	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_9],0) / 100)
						WHEN 14	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_10],0) / 100)
						WHEN 15	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_11],0) / 100)
						WHEN 16	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_12],0) / 100)
						WHEN 17	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_13],0) / 100)
						WHEN 18	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_14],0) / 100)
						WHEN 19	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_15],0) / 100)
						WHEN 20	then L.[prli_price] + (L.[prli_price] * isnull(I.[item_markup_16],0) / 100)
					END						[item_price],
					l.curr_id,
					CASE
					    WHEN @list_id_to = -1 THEN l.prli_id
					    ELSE @list_id_to
					END


			FROM	dbo.tbPriceListItems L

					INNER JOIN tbPriceList tpl						WITH (NOLOCK)
						ON	tpl.comp_id = l.comp_id AND
							tpl.prli_id = l.prli_id

					INNER JOIN tbItem I								WITH (NOLOCK)
					ON  I.[comp_id]					= L.[comp_id]
					AND I.[item_id]					= L.[item_id]

					INNER JOIN @tblComplexFilter_Items	TEMP
					ON TEMP.item_id = I.item_id

			WHERE	L.[comp_id]		=	@comp_id
			AND 	(
						(	L.[prli_id]							=	@list_id_from)   -- haces esto mismo para las otras y abajo hacer los inner join contra el nuevo campo (ultimo de la temp) y verificar que funcione ok.
						OR
						(	@list_id_from						= -1 AND
							tpl.prli_available4AllUpdateMode	= 'True')
					)
			AND 	(@curr_id		= -1 or L.[curr_id]		=   @curr_id)
			AND		NOT L.prli_price IS NULL
			AND		(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
			AND		(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
			AND		(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
			AND		(@supp_id		= -1 or I.supp_id		=	@supp_id)
			AND		(@item_id		= -1 or L.[item_id]		=	@item_id)

		end

	else

	begin

	if @type_id_from = 2 --lista de costos
		begin

			INSERT INTO [#tmp] ([comp_id], [item_id], [item_price], [curr_id], list_id_to)
			SELECT	L.comp_id,
					L.item_id,
					CASE @update_type
						WHEN 1	then L.[coslis_price] + @update_value
						WHEN 2	then L.[coslis_price] + (L.[coslis_price] * @update_value / 100)
						WHEN 3  then L.[coslis_price] * @update_value
						WHEN 4  then L.[coslis_price] / dbo.fnNoZDiv( @update_value )
						WHEN 5	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_1],0) / 100)
						WHEN 6	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_2],0) / 100)
						WHEN 7	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_3],0) / 100)
						WHEN 8	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_4],0) / 100)
						WHEN 9	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_5],0) / 100)
						WHEN 10	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_6],0) / 100)
						WHEN 11	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_7],0) / 100)
						WHEN 12	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_8],0) / 100)
						WHEN 13	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_9],0) / 100)
						WHEN 14	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_10],0) / 100)
						WHEN 15	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_11],0) / 100)
						WHEN 16	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_12],0) / 100)
						WHEN 17	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_13],0) / 100)
						WHEN 18	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_14],0) / 100)
						WHEN 19	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_15],0) / 100)
						WHEN 20	then L.[coslis_price] + (L.[coslis_price] * isnull(I.[item_markup_16],0) / 100)
					END 					[item_price],
					l.curr_id,
					CASE
					    WHEN @list_id_to = -1 THEN l.coslis_id
					    ELSE @list_id_to
					END


			FROM	dbo.tbItemCostList L

					INNER JOIN tbItem I							WITH (NOLOCK)
					ON  I.[comp_id]					= L.[comp_id]
					AND I.[item_id]					= L.[item_id]

					INNER JOIN tbItemCostListName ticln			WITH (NOLOCK)
						ON	ticln.comp_id			= l.comp_id AND
							ticln.coslis_id			= l.coslis_id

					INNER JOIN @tblComplexFilter_Items	TEMP
					ON TEMP.item_id = I.item_id

			WHERE	L.[comp_id]		=	@comp_id
			AND 	(
						L.[coslis_id]	=	@list_id_from
						OR
						(
							@list_id_from						= -1 AND
							ticln.coslis_available4AllUpdateMode='True'
						)
					)
			AND 	(@curr_id		= -1 OR  L.[curr_id]		=   @curr_id)
			AND		NOT L.coslis_price IS NULL
			AND		(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
			AND		(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
			AND		(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
			AND		(@supp_id		= -1 or I.supp_id		=	@supp_id)
			AND		(@item_id		= -1 or I.[item_id]		=	@item_id)

		end

	else

		begin

			if @type_id_from = 3 --lista de costos promedio ponderado
				begin

					insert into [#tmp] ([comp_id], [item_id], [item_price], [curr_id], list_id_to)
					SELECT	L.comp_id,
							L.item_id,
							case @update_type
								when 1	then L.[coslis_price_aw] + @update_value
								when 2	then L.[coslis_price_aw] + (L.[coslis_price_aw] * @update_value / 100)
								when 3  then L.[coslis_price_aw] * @update_value
								when 4  then L.[coslis_price_aw] / dbo.fnNoZDiv( @update_value )
								WHEN 5	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_1],0) / 100)
								WHEN 6	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_2],0) / 100)
								WHEN 7	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_3],0) / 100)
								WHEN 8	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_4],0) / 100)
								WHEN 9	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_5],0) / 100)
								WHEN 10	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_6],0) / 100)
								WHEN 11	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_7],0) / 100)
								WHEN 12	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_8],0) / 100)
								WHEN 13	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_9],0) / 100)
								WHEN 14	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_10],0) / 100)
								WHEN 15	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_11],0) / 100)
								WHEN 16	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_12],0) / 100)
								WHEN 17	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_13],0) / 100)
								WHEN 18	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_14],0) / 100)
								WHEN 19	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_15],0) / 100)
								WHEN 20	then L.[coslis_price_aw] + (L.[coslis_price_aw] * isnull(I.[item_markup_16],0) / 100)
							end						[item_price],
							l.curr_id,
							CASE
							    WHEN @list_id_to = -1 THEN l.coslis_id
							    ELSE @list_id_to
							END


					FROM	dbo.tbItemCostList L

							INNER JOIN tbItem I							WITH (NOLOCK)
							ON  I.[comp_id]					= L.[comp_id]
							AND I.[item_id]					= L.[item_id]

							INNER JOIN tbItemCostListName ticln			WITH (NOLOCK)
								ON	ticln.comp_id			= l.comp_id AND
									ticln.coslis_id			= l.coslis_id

							INNER JOIN @tblComplexFilter_Items	TEMP
							ON TEMP.item_id = I.item_id

					WHERE	L.[comp_id]		=	@comp_id
					AND 	(
								L.[coslis_id]	=	@list_id_from
								OR
								(
									@list_id_from						= -1 AND
									ticln.coslis_available4AllUpdateMode='True'
								)
							)
					AND 	(@curr_id		= -1 OR L.[curr_id]		=   @curr_id)
					AND		NOT L.coslis_price_aw IS NULL
					AND		(@cat_id		= -1 or I.[cat_id]		=	@cat_id)
					AND		(@subcat_id		= -1 or I.[subcat_id]	=	@subcat_id)
					AND		(@brand_id		= -1 or I.[brand_id]	=	@brand_id)
					AND		(@supp_id		= -1 or I.supp_id		=	@supp_id)
					AND		(@item_id		= -1 or I.[item_id]		=	@item_id)

				end

			end

		end



	--select * from [#tmp]



	-- Si no esta creada la lista de destino, hay que crearla primero.
	-- Chequear lista de Ventas
	IF @type_id_to = 1
		BEGIN

			INSERT INTO tbPriceListItems
			(
				comp_id,
				prli_id,
				item_id,
				prli_price,
				curr_id,
				prli_cd
			)
				SELECT	@comp_id,
						tmp.list_id_to,  --@list_id_to,
						tmp.item_id,
						0,
						tmp.curr_id,
						GETDATE()
					FROM #tmp tmp
					INNER JOIN tbPriceList tpl	WITH (NOLOCK)
						ON	tpl.comp_id											= @comp_id			AND
							tpl.prli_id											= tmp.list_id_to	AND
							tpl.prli_wfmPriceCostFullUpdate_CreateDestinyPrice	= 'True'
				WHERE NOT EXISTS		(	SELECT TOP 1  tpli.item_id
												FROM tbPriceListItems tpli	WITH (NOLOCK)
				                      			WHERE	tpli.comp_id = @comp_id								AND
				                      				    tpli.prli_id = tmp.list_id_to						AND
				                      					tpli.item_id = tmp.item_id
									     )


		END




	----primero hay que actualizar la tabla destino (costo o precios)
	--IF @type_id_to = 1 --lista de precios
	--	BEGIN
	--		DECLARE @a AS INT = 1
	--		-- MOS 02-2020
	--		--UPDATE 	dbo.tbPriceListItems			WITH (ROWLOCK)
	--		--SET 	prli_price_PreLastUpdate	= pli.prli_price,
	--		--		curr_id_PreLastUpdate		= pli.curr_id,
	--		--		prli_price					= dbo.fnGetExchange2(@comp_id, tmp.item_price, tmp.curr_id, pli.curr_id,pli.curr_id,pli.curr_id,1,'false'),
	--		--		user_id_lastUpdate			= @user_id,
	--		--		prli_updatedAt				= GETDATE()
	--		--FROM 	dbo.tbPriceListItems		pli
	--		--	INNER JOIN [#tmp]			tmp
	--		--	ON	tmp.comp_id		= pli.comp_id		AND
	--		--		tmp.item_id		= pli.[item_id]		AND
	--		--		tmp.list_id_to	= pli.prli_id

	--		--WHERE 	pli.[comp_id]		= @comp_id
	--		--AND     (@curr_id			= -1 OR pli.[curr_id]		= @curr_id)

	--	END

	--ELSE

	--	BEGIN



			---- -----------
			---- COSTOS
			---- -----------
			--IF @type_id_to = 2 --lista de costos
			--	BEGIN

			--		UPDATE 	dbo.[tbItemCostList]		WITH (ROWLOCK)
			--		SET 	coslis_price_PreLastUpdate	= icl.coslis_price,
			--				curr_id_PreLastUpdate		= icl.curr_id,
			--				coslis_price				= dbo.fnGetExchange2(@comp_id, tmp.item_price, tmp.curr_id, icl.curr_id,icl.curr_id,icl.curr_id,1,'false'),
			--				user_id_lastUpdate			= @user_id,
			--				coslis_lastUpdate			= GETDATE()
			--		FROM 	dbo.[tbItemCostList]	icl

			--				INNER JOIN  [#tmp]		tmp
			--				ON	tmp.comp_id		= icl.comp_id		AND
			--					tmp.item_id		= icl.[item_id]		AND
			--					tmp.list_id_to  = icl.coslis_id

			--		WHERE 	icl.[comp_id]		= @comp_id
			--		AND     (@curr_id			= -1 OR icl.[curr_id]		= @curr_id)
			--		--AND     icl.[coslis_id]		= @list_id_to

			--	END

			--ELSE

			--	BEGIN

			--		IF @type_id_to = 3 --lista de costos promedio ponderado

			--			BEGIN

			--				UPDATE 	dbo.[tbItemCostList]		WITH (ROWLOCK)
			--				SET 	coslis_price_aw		= dbo.fnGetExchange2(@comp_id, tmp.item_price, tmp.curr_id, icl.curr_id,icl.curr_id,icl.curr_id,1,'false')
			--				FROM 	dbo.[tbItemCostList]	icl

			--						INNER JOIN [#tmp]		tmp
			--						on	tmp.comp_id		= icl.comp_id		AND
			--							tmp.item_id		= icl.item_id		AND
			--							tmp.list_id_to	= icl.coslis_id

			--				WHERE 	icl.[comp_id]		= @comp_id
			--				AND     (@curr_id			= -1 OR icl.[curr_id]		= @curr_id)
			--				--AND     icl.[coslis_id]		= @list_id_to

			--			END

			--	END
			---- -----------
			---- COSTOS
			---- -----------


		--END


	-- --------------------------------------------------------
	-- Se sobreescriben si se actualizaron listas de COSTOS
	-- para que se puedan disparar los triggers.
	-- --------------------------------------------------------
	DECLARE @intItemId		AS INT
	IF @type_id_to = 2 OR @type_id_to = 3
		BEGIN

			DECLARE @intCosLisId	AS INT
			DECLARE curItemCostList CURSOR LOCAL FAST_FORWARD FOR
					SELECT
							ticl.item_id,
							ticl.coslis_id
						FROM tbItemCostList ticl			WITH (NOLOCK)
						INNER JOIN  #tmp		tmp
							ON	tmp.comp_id		= ticl.comp_id	AND
								tmp.item_id		= ticl.item_id	AND
								tmp.list_id_to	= ticl.coslis_id
						INNER JOIN tbitem TI				WITH (NOLOCK)
							ON		ti.comp_id	= ticl.comp_id
								AND ti.item_id	= ticl.item_id
					WHERE
							ticl.comp_id	= @comp_id
						--AND ticl.coslis_id	= @list_id_to

			OPEN curItemCostList
			FETCH NEXT FROM curItemCostList INTO @intItemId,@intCosLisId
			WHILE @@FETCH_STATUS = 0
				BEGIN

					-- -----------
					-- COSTOS
					-- -----------
					IF @type_id_to = 2 --lista de costos
						BEGIN

							UPDATE 	dbo.[tbItemCostList]		WITH (ROWLOCK)
							SET 	coslis_price_PreLastUpdate	= icl.coslis_price,
									curr_id_PreLastUpdate		= icl.curr_id,
									coslis_price				= dbo.fnGetExchange2(@comp_id, tmp.item_price, tmp.curr_id, icl.curr_id,icl.curr_id,icl.curr_id,1,'false'),
									user_id_lastUpdate			= @user_id,
									coslis_lastUpdate			= GETDATE(),
									coslis_disabled4Rules		= 0
							FROM 	dbo.[tbItemCostList]	icl

									INNER JOIN  [#tmp]		tmp
									ON	tmp.comp_id		= icl.comp_id		AND
										tmp.item_id		= icl.[item_id]		AND
										tmp.list_id_to  = icl.coslis_id

							WHERE 	icl.[comp_id]			= @comp_id
								AND icl.coslis_id			= @intCosLisId
								AND icl.item_id				= @intItemId
								AND     (@curr_id			= -1 OR icl.[curr_id]		= @curr_id)
							--AND     icl.[coslis_id]		= @list_id_to

						END

					ELSE

						BEGIN

							IF @type_id_to = 3 --lista de costos promedio ponderado

								BEGIN

									UPDATE 	dbo.[tbItemCostList]		WITH (ROWLOCK)
									SET 	coslis_price_aw			= dbo.fnGetExchange2(@comp_id, tmp.item_price, tmp.curr_id, icl.curr_id,icl.curr_id,icl.curr_id,1,'false'),
											coslis_disabled4Rules	= 0
									FROM 	dbo.[tbItemCostList]	icl

											INNER JOIN [#tmp]		tmp
											on	tmp.comp_id		= icl.comp_id		AND
												tmp.item_id		= icl.item_id		AND
												tmp.list_id_to	= icl.coslis_id

									WHERE 	icl.[comp_id]		= @comp_id
										AND icl.coslis_id		= @intCosLisId
										AND icl.item_id			= @intItemId
									AND     (@curr_id			= -1 OR icl.[curr_id]		= @curr_id)
									--AND     icl.[coslis_id]		= @list_id_to

								END

						END
					-- -----------
					-- COSTOS
					-- -----------

					-- ----------------------------------
					-- MOS 06-2022: para q act los combos, talles, etc.
					-- ----------------------------------
					UPDATE tbitem
						SET item_lastUpdate_byProcess = GETDATE()
						WHERE	comp_id = @comp_id AND
								item_id = @intItemId
					-- ----------------------------------

					--UPDATE tbItemCostList
					--	SET
					--		coslis_price			= coslis_price,
					--		coslis_triggerUpdateCD	= GETDATE()
					--	WHERE	comp_id		= @Comp_Id
					--		AND coslis_id	= @intCosLisId     --@list_id_to
					--		AND item_id		= @intItemId

					FETCH NEXT FROM curItemCostList INTO @intItemId,@intCosLisId
				END
			CLOSE		curItemCostList
			DEALLOCATE	curItemCostList
		END
	-- --------------------------------------------------------


	-- --------------------------------------------------------
	-- Se sobreescriben si se actualizaron listas de VENTAS
	-- para que se puedan disparar los triggers.
	-- --------------------------------------------------------
	IF @type_id_to = 1
		BEGIN

			DECLARE @intPrLiId	AS INT
			DECLARE curPriceListItems CURSOR LOCAL  FAST_FORWARD FOR
					SELECT
							ticl.item_id,
							ticl.prli_id
						FROM tbPriceListItems ticl			WITH (NOLOCK)
						INNER JOIN  #tmp		tmp
							ON	tmp.comp_id		= ticl.comp_id	AND
								tmp.item_id		= ticl.item_id	AND
								tmp.list_id_to	= ticl.prli_id
						INNER JOIN tbitem TI				WITH (NOLOCK)
							ON		ti.comp_id	= ticl.comp_id
								AND ti.item_id	= ticl.item_id
					WHERE
							ticl.comp_id	= @comp_id
						--AND ticl.coslis_id	= @list_id_to

			OPEN			curPriceListItems
			FETCH NEXT FROM curPriceListItems INTO @intItemId,@intPrLiId
			WHILE @@FETCH_STATUS = 0
				BEGIN

					UPDATE 	dbo.tbPriceListItems			WITH (ROWLOCK)
						SET 	prli_price_PreLastUpdate	= pli.prli_price,
								curr_id_PreLastUpdate		= pli.curr_id,
								prli_price					= dbo.fnGetExchange2(@comp_id, tmp.item_price, tmp.curr_id, pli.curr_id,pli.curr_id,pli.curr_id,1,'false'),
								user_id_lastUpdate			= @user_id,
								prli_updatedAt				= GETDATE(),
								prli_disabled4Rules			= 0
						FROM 	dbo.tbPriceListItems		pli
						INNER JOIN [#tmp]					tmp
						ON	tmp.comp_id		= pli.comp_id		AND
							tmp.item_id		= pli.[item_id]		AND
							tmp.list_id_to	= pli.prli_id

						WHERE 	pli.[comp_id]		= @comp_id		AND
								pli.prli_id			= @intPrLiId	AND
								pli.item_id			= @intItemId	AND
								(@curr_id			= -1 OR pli.[curr_id]		= @curr_id)


					-- ----------------------------------
					-- MOS 06-2022: para q act los combos, talles, etc.
					-- ----------------------------------
					UPDATE tbitem
						SET item_lastUpdate_byProcess = GETDATE()
						WHERE	comp_id = @comp_id AND
								item_id = @intItemId
					-- ----------------------------------

					--UPDATE tbPriceListItems
					--	SET		prli_price				= prli_price ,
					--			prli_triggerUpdateCD	= GETDATE()
					--	WHERE	comp_id		= @Comp_Id
					--		AND prli_id		= @intPrLiId     --@list_id_to
					--		AND item_id		= @intItemId

					FETCH NEXT FROM curPriceListItems INTO @intItemId,@intPrLiId
				END
			CLOSE		curPriceListItems
			DEALLOCATE	curPriceListItems
		END
	-- --------------------------------------------------------



END
GO







CREATE PROCEDURE [dbo].[spPriceListItem_insertDataFromMercadoLibre]
(
	@comp_id				INT,
	@item_id				INT,
	@prli_id				INT,
	@price					DECIMAL(19,4),
	@currency_id			INT,
	@return_value			INT	OUTPUT
)
AS


BEGIN


	SET NOCOUNT ON

	SET @return_value = 0


	IF EXISTS(
				SELECT 1
					FROM tbPriceList tpl		WITH (NOLOCK)
					WHERE	tpl.comp_id						= @comp_id AND
							tpl.prli_id						= @prli_id AND
							tpl.prli_isAvailble4MLInsert	= 'True'
			)
		BEGIN
			IF not EXISTS(
						SELECT 1
							FROM tbPriceListItems tpli		WITH (NOLOCK)
							WHERE	tpli.comp_id = @comp_id AND
									tpli.prli_id = @prli_id AND
									tpli.item_id = @item_id
					)
				BEGIN
					INSERT INTO tbPriceListItems	WITH (ROWLOCK)
					(
						comp_id,
						prli_id,
						item_id,
						prli_price,
						curr_id,
						bra_id,
						prli_cd,
						prli_updatedAt,
						prli_price_PreLastUpdate,
						curr_id_PreLastUpdate,
						prli_triggerUpdateCD,
						user_id_lastUpdate,
						prli_disabled4Rules
					)
					VALUES
					(
						@comp_id,
						@prli_id,
						@item_id,
						@price,
						@currency_id,
						NULL,
						GETDATE(),
						GETDATE(),
						NULL ,
						NULL,
						NULL,
						NULL,
						NULL
					)
					SET @return_value = 1
				END
			ELSE
				BEGIN

					UPDATE tbPriceListItems		WITH (ROWLOCK)
						SET
							prli_updatedAt				= GETDATE(),
							prli_price_PreLastUpdate	=  prli_price,
							curr_id_PreLastUpdate		= curr_id,
							prli_price					= @price,
							curr_id						= @currency_id
						WHERE	comp_id = @comp_id AND
								prli_id = @prli_id AND
								item_id = @item_id


					SET @return_value = 1

				END
		END




END
GO






