CREATE PROCEDURE [dbo].[spPriceListItems_getCombo]
(
      @comp_id                int,
      @item_id                int,
      @prof_id                INT,
      @stor_id                INT
)
AS

BEGIN

	set nocount ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------
	/*
		  declare @comp_id             int,
				@item_id               INT,
				@prof_id               INT,
				@stor_id               INT
		  select @comp_id              =1,
				@item_id               =347 ,
				@prof_id                =1,
				@stor_id                =1

	*/
	-- -----------------------------------------------------------------------------

	/*Se verifica esxistencia en tbPriceListItems, si se encuentra es un artículo NO HIJO (un padre o un posible padre),
	* sino se encuentra, es un hijo, en ese caso se toma el valor de la lista de precios del PADRE                                    */

	IF EXISTS (SELECT TOP 1  1
			   FROM   dbo.tbPriceListItems              pri		WITH (NOLOCK)
			   WHERE  pri.comp_id = @comp_id
				 AND  pri.item_id = @item_id)


		  SELECT      pri.prli_id       [id],
					  pr.prli_desc      [desc]

		  FROM dbo.tbPriceListItems                     pri	WITH (NOLOCK)
		  INNER JOIN dbo.tbPriceList        pr	WITH (NOLOCK)
			  ON  pr.comp_id    = pri.comp_id
			  AND pr.prli_id    = pri.prli_id

		  WHERE pri.comp_id			= @comp_id
		  AND   pri.item_id			= @item_id
		  AND	pr.prli_disabled	= 'False'
		  AND   (pri.prli_id IN (  SELECT tplp.prli_id
									  FROM   vwPriceList4Storage4Profile tplp	WITH (NOLOCK)
									  WHERE  tplp.comp_id     = @comp_id
										AND  tplp.prof_id     = @prof_id
										AND  (tplp.stor_id     = @stor_id OR tplp.stor_id = -1)) OR
										NOT EXISTS (SELECT   TOP 1    1
														FROM    vwPriceList4Storage4Profile tplp	WITH (NOLOCK)
														WHERE   tplp.comp_id   = @comp_id
														 AND    tplp.prof_id   = @prof_id
														 AND    (tplp.stor_id  = @stor_id or tplp.stor_id = -1 )))

		  ORDER BY    [desc]

	ELSE

		  SELECT      pri.prli_id       [id],
					  pr.prli_desc      [desc]

		  FROM  dbo.tbPriceListItems                    pri	WITH (NOLOCK)
		  INNER JOIN dbo.tbPriceList					pr	WITH (NOLOCK)
			  ON pr.comp_id     = pri.comp_id
			  AND pr.prli_id    = pri.prli_id

		  WHERE pri.comp_id			= @comp_id
		  AND	pr.prli_disabled	= 'False'
		  AND   pri.item_id IN (SELECT tiscr.item_id
									  FROM tbItemSizeColorRelation   tiscr	WITH (NOLOCK)
									  WHERE tiscr.comp_id            = @comp_id
									  AND   tiscr.item_id_child = @item_id)
		  AND         (pri.prli_id IN (SELECT tplp.prli_id
											FROM           tbPriceList4Storage4Profile tplp	WITH (NOLOCK)
											WHERE          tplp.comp_id      = @comp_id
												 AND       tplp.prof_id      = @prof_id
												 AND       tplp.stor_id      = @stor_id) OR
											   NOT EXISTS (SELECT  TOP 1     1
																FROM           tbPriceList4Storage4Profile tplp	WITH (NOLOCK)
																WHERE          tplp.comp_id      = @comp_id
																	 AND       tplp.prof_id      = @prof_id
																	 AND       tplp.stor_id      = @stor_id))

		  ORDER BY    [desc]

END
GO






