CREATE PROCEDURE [dbo].[spPriceListItems_getData]
(
	@comp_id			int,
	@prli_id			int
)
as
set nocount on

select	i.item_desc,
		p.prli_price

from	dbo.tbPriceListItems p

		inner join [tbItem] i
		on	i.comp_id = p.comp_id
		and i.item_id = p.item_id

where	p.comp_id = @comp_id
And     (@prli_id = -1 or p.prli_id = @prli_id)


GO


CREATE PROCEDURE [dbo].[spPriceListItems_getDataByFilters2]
(
	@comp_id	INT,
	@prli_id	INT,
	@item_id	INT
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON


/*
	DECLARE @comp_id	INT,
			@prli_id	INT,
			@item_id	INT
	SELECT  @comp_id	= 1,
			@prli_id	= -1,
			@item_id	= -1
*/



	SELECT	tpli.comp_id,
			tpli.prli_id,
			tpli.item_id,
			tpli.prli_price,
			tpli.curr_id,
			tpli.bra_id,
			ti.item_code,
      		isnull(convert(varchar,vitooit.tax_id), '')						[tax_id],
      		ttn.tax_percentage,
      		isnull(convert(varchar,vitooit2.tax_id), '')					[tax_id_II],
      		IsNull(ttn2.tax_percentage,0)									[tax_percentage_II],
      		dbo.fnGetExchange2(@comp_id, 1, 2, 1, 0, 0, 0, 'False')			[Cotizacion_Dolar],
      		dbo.fnGetExchange2(@comp_id,(
      										 tpli.prli_price +
      										(tpli.prli_price  * ISNULL(ttn.tax_percentage,0)  / 100) +
      										(tpli.prli_price  * ISNULL(ttn2.tax_percentage,0) / 100)
      									)
      								   , tpli.curr_id, 1, 0, 0, 0, 'False')			[prli_price_Final_Pesos]


		FROM	tbPriceListItems	tpli			WITH (NOLOCK)
		INNER JOIN tbItem ti						WITH (NOLOCK)
			ON	ti.comp_id = tpli.comp_id AND
				ti.item_id = tpli.item_id


		LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit		WITH (NOLOCK)
			ON	vitooit.comp_id		= ti.comp_id
			AND vitooit.item_id		= ti.item_id

		LEFT JOIN tbTaxName						ttn			WITH (NOLOCK)
			ON	ttn.comp_id			= ti.comp_id
			AND ttn.tax_id			= vitooit.tax_id

		LEFT JOIN vwItemTaxesOnlyOneInternalTax vitooit2	WITH (NOLOCK)
			ON	vitooit2.comp_id	= ti.comp_id
			AND vitooit2.item_id	= ti.item_id

		LEFT JOIN tbTaxName						ttn2		WITH (NOLOCK)
			ON	ttn2.comp_id		= ti.comp_id
			AND ttn2.tax_id			= vitooit2.tax_id


		WHERE	tpli.comp_id	= @comp_id
		AND     (@prli_id		= -1		OR tpli.prli_id		= @prli_id)
		AND		(@item_id		= -1		OR tpli.item_id		= @item_id)
		AND		ISNULL(ti.item_disabled,'False')				= 'False'			-- MOS 02-2023

		ORDER BY ti.item_code

END
GO



CREATE PROCEDURE [dbo].[spPriceListItems_getDataByFilters2_4WebServiceShort]
(
	@comp_id	INT,
	@prli_id	INT,
	@item_id	INT
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON


	/*
	DECLARE @comp_id	INT,
			@prli_id	INT,
			@item_id	INT
	SELECT  @comp_id	= 1,
			@prli_id	= -1,
			@item_id	= -1

	*/


	SELECT
			tpli.comp_id,
			tpli.bra_id,
			tpli.prli_id,
			tpli.item_id,
			tpli.curr_id,
      		dbo.fnGetExchange2(@comp_id,(
      										 tpli.prli_price +
      										(tpli.prli_price  * ISNULL(ttn.tax_percentage,0)  / 100) +
      										(tpli.prli_price  * ISNULL(ttn2.tax_percentage,0) / 100)
      									)
      								   , tpli.curr_id, 1, 0, 0, 0, 'False')			[prli_price_Final_Pesos]


		FROM	tbPriceListItems	tpli			WITH (NOLOCK)
		INNER JOIN tbItem ti						WITH (NOLOCK)
			ON	ti.comp_id = tpli.comp_id AND
				ti.item_id = tpli.item_id

		LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit		WITH (NOLOCK)
			ON	vitooit.comp_id		= ti.comp_id
			AND vitooit.item_id		= ti.item_id

		LEFT JOIN tbTaxName						ttn			WITH (NOLOCK)
			ON	ttn.comp_id			= ti.comp_id
			AND ttn.tax_id			= vitooit.tax_id

		LEFT JOIN vwItemTaxesOnlyOneInternalTax vitooit2	WITH (NOLOCK)
			ON	vitooit2.comp_id	= ti.comp_id
			AND vitooit2.item_id	= ti.item_id

		LEFT JOIN tbTaxName						ttn2		WITH (NOLOCK)
			ON	ttn2.comp_id		= ti.comp_id
			AND ttn2.tax_id			= vitooit2.tax_id


		WHERE	tpli.comp_id	= @comp_id
		AND     (@prli_id		= -1		OR tpli.prli_id		= @prli_id)
		AND		(@item_id		= -1		OR tpli.item_id		= @item_id)

		ORDER BY ti.item_code

END
GO


CREATE PROCEDURE [dbo].[spPriceListItems_getDataByFilters4FullJaus]
(
	@comp_id	INT,
	@prli_id	INT,
	@item_id	INT,
	@bra_id		int
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON


/*
	DECLARE @comp_id	INT,
			@prli_id	INT,
			@item_id	INT
	SELECT  @comp_id	= 1,
			@prli_id	= -1,
			@item_id	= -1
*/



	SELECT	tpli.comp_id,
			tpli.prli_id,
			tpli.item_id,
			tpli.prli_price,
			tpli.curr_id,
			tpli.bra_id,
			ti.item_code,
      		isnull(convert(varchar,vitooit.tax_id), '')						[tax_id],
      		ttn.tax_percentage,
      		isnull(convert(varchar,vitooit2.tax_id), '')					[tax_id_II],
      		IsNull(ttn2.tax_percentage,0)									[tax_percentage_II],
      		dbo.fnGetExchange2(@comp_id, 1, 2, 1, 0, 0, 0, 'False')			[Cotizacion_Dolar],
      		dbo.fnGetExchange2(@comp_id,(
      										 tpli.prli_price +
      										(tpli.prli_price  * ISNULL(ttn.tax_percentage,0)  / 100) +
      										(tpli.prli_price  * ISNULL(ttn2.tax_percentage,0) / 100)
      									)
      								   , tpli.curr_id, 1, 0, 0, 0, 'False')			[prli_price_Final_Pesos]


		FROM	tbPriceListItems	tpli			WITH (NOLOCK)
		INNER JOIN vwFullJaus_ItemsData tmp			WITH (NOLOCK)
			ON	tmp.comp_id = tpli.comp_id AND
				tmp.item_id = tpli.item_id
		INNER JOIN tbItem ti						WITH (NOLOCK)
			ON	ti.comp_id = tpli.comp_id AND
				ti.item_id = tpli.item_id
		LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit		WITH (NOLOCK)
			ON	vitooit.comp_id		= ti.comp_id
			AND vitooit.item_id		= ti.item_id
		LEFT JOIN tbTaxName						ttn			WITH (NOLOCK)
			ON	ttn.comp_id			= ti.comp_id
			AND ttn.tax_id			= vitooit.tax_id
		LEFT JOIN vwItemTaxesOnlyOneInternalTaxByBranch AS  vitooit2	WITH (NOLOCK)
			ON	vitooit2.comp_id	= ti.comp_id	AND
				vitooit2.item_id	= ti.item_id	AND
				(
					vitooit2.bra_id = @bra_id
						OR
					vitooit2.bra_id IS NULL
				)
		LEFT JOIN tbTaxName						ttn2		WITH (NOLOCK)
			ON	ttn2.comp_id	= ti.comp_id
			AND ttn2.tax_id		= vitooit2.tax_id
		WHERE	tpli.comp_id	= @comp_id	AND
		       (@prli_id		= -1		OR tpli.prli_id		= @prli_id )	AND
		       (@item_id		= -1		OR tpli.item_id		= @item_id )

		ORDER BY ti.item_code

END
GO


