CREATE PROCEDURE [dbo].[spPriceListItems_getDataByFilters4MercadoLibre]
(
	@comp_id	INT,
	@prli_id	INT,
	@item_id	INT,
	@coslis_id	INT
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON



	/*
	DECLARE @comp_id	INT,
			@prli_id	INT,
			@item_id	INT
	SELECT  @comp_id	= 1,
			@prli_id	= -1,
			@item_id	= -1
	*/



	SELECT	tpli.comp_id,
			tpli.prli_id,
			tpli.item_id,
			dbo.fnGetExchange2(tpli.comp_id,  tpli.prli_price,tpli.curr_id, 1, 0,0, 0 , 'False')	[prli_price],
			1 /*tpli.curr_id*/																		[curr_id],
			tpli.bra_id,
			ti.item_code,
      		isnull(convert(varchar,vitooit.tax_id), '')						[tax_id],
      		ttn.tax_percentage,
      		isnull(convert(varchar,vitooit2.tax_id), '')					[tax_id_II],
      		IsNull(ttn2.tax_percentage,0)									[tax_percentage_II],
      		tpli.curr_id													[curr_idOriginal],
      		tpli.prli_price													[prli_priceOriginal],
      		dbo.fnGetExchange2(tpli.comp_id, ISNULL( ticl.coslis_price,0),		ISNULL(ticl.curr_id,-1), 1, 0,0, 0 , 'False')	[coslis_price],
      		dbo.fnGetExchange2(tpli.comp_id, ISNULL( ticl.coslis_price_aw,0),	ISNULL(ticl.curr_id,-1), 1, 0,0, 0 , 'False')	[coslis_priceAW]


		FROM	tbPriceListItems	tpli					WITH (NOLOCK)

		INNER JOIN tbItem ti								WITH (NOLOCK)
			ON	ti.comp_id = tpli.comp_id AND
				ti.item_id = tpli.item_id

		LEFT JOIN tbItemCostList ticl						WITH (NOLOCK)
			ON	ticl.comp_id	= @comp_id AND
				ticl.coslis_id	= @coslis_id AND
				ticl.item_id	= ti.item_id

		LEFT JOIN vwItemTaxesOnlyOneIvaTax		vitooit		WITH (NOLOCK)
			ON	vitooit.comp_id		= ti.comp_id
			AND vitooit.item_id		= ti.item_id

		LEFT JOIN tbTaxName						ttn			WITH (NOLOCK)
			ON	ttn.comp_id			= ti.comp_id
			AND ttn.tax_id			= vitooit.tax_id

		LEFT JOIN vwItemTaxesOnlyOneInternalTax vitooit2	WITH (NOLOCK)
			ON	vitooit2.comp_id	= ti.comp_id
			AND vitooit2.item_id	= ti.item_id

		LEFT JOIN tbTaxName						ttn2		WITH (NOLOCK)
			ON	ttn2.comp_id		= ti.comp_id
			AND ttn2.tax_id			= vitooit2.tax_id

		INNER JOIN vwItemEnabled4MercadoLibre mle			WITH (NOLOCK)
			ON	mle.comp_id = ti.comp_id AND
				mle.item_id = ti.item_id


		WHERE	tpli.comp_id	= @comp_id
		AND     (@prli_id		= -1		OR tpli.prli_id		= @prli_id)
		AND		(@item_id		= -1		OR tpli.item_id		= @item_id)
		AND		 tpli.prli_price <> 0

		ORDER BY ti.item_code

END
GO





-- Si se toca algo aca ver tambien en : spPriceListItems_getDataByIdfromVIEW
CREATE  PROCEDURE [dbo].[spPriceListItems_getDataById]
(
	@comp_id			int,
	@bra_id				INT,
	@item_id			int,
	@prli_id			int
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on

	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------
	/*
	DECLARE 	@comp_id			int,
				@item_id			int,
				@prli_id			int

		SELECT 	@comp_id			=1,
				@item_id			=347,
				@prli_id			=1
	*/
	-- -----------------------------------------------------------------------------

	DECLARE @tmpItem AS TABLE (comp_id int,item_id INT PRIMARY KEY)
	INSERT INTO @tmpItem(	comp_id,
							item_id)
		SELECT	DISTINCT
				tpli.comp_id,
				tpli.item_id
			FROM tbPriceListItems tpli				WITH (NOLOCK)	-- se saco la vista que estaba antes, NO PONERLA y usar spPriceListItems_getDataByIdfromVIEW
			WHERE	tpli.comp_id = @comp_id AND
					tpli.prli_id = @prli_id AND
					tpli.item_id = @item_id --AND


	DECLARE @tmpItemRelation AS TABLE(item_id INT PRIMARY KEY)
	INSERT INTO @tmpItemRelation(item_id)
		SELECT tiscr.item_id
			FROM tbItemSizeColorRelation tiscr WITH (NOLOCK)
			WHERE	tiscr.comp_id		= @comp_id AND
					tiscr.item_id_child = @item_id



	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpItem(	comp_id,
									item_id)
				select	DISTINCT
						pli.comp_id,
						pli.item_id
					from	dbo.tbPriceListItems  pli	WITH (NOLOCK)
					where	pli.comp_id = @comp_id
					And     pli.prli_id = @prli_id
					and		(
							   pli.item_id IN (	SELECT tiscr.item_id
   													FROM	@tmpItemRelation tiscr
												)

							)
		END



	select	prli_price,
			pli.curr_id,
			pli.bra_id,
			dbo.fnGetPriceListItemTaxesCoeficient(pli.comp_id, pli.item_id) * pli.prli_price	[prli_priceWithTaxes],		-- OJO que es SOLO LECTURA, CAMPO CALCULADO !!!
			ISNULL(tc.curr_symbol,'   ')														[curr_symbol]
		from	dbo.vwPriceListItems  pli	WITH (NOLOCK)
		INNER JOIN @tmpItem tmp
			ON tmp.comp_id = pli.comp_id AND
			   tmp.item_id = pli.item_id
		LEFT JOIN tbsysCurrency tc
			ON tc.curr_id = pli.curr_id
		WHERE	pli.comp_id = @comp_id AND
				pli.prli_id = @prli_id


END


GO




