			ON tmp.comp_id = pli.comp_id AND
			   tmp.item_id = pli.item_id
		WHERE	pli.comp_id = @comp_id AND
				pli.prli_id = @prli_id



END


GO


CREATE PROCEDURE [dbo].[spPriceListItems_getDataInMLStoreCurrency]
(
	@comp_id	INT,
	@prli_id	INT,
	@item_id	INT,
	@mls_id		INT
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON


	SELECT dbo.fnGetExchange2(tpli.comp_id, tpli.prli_price, tpli.curr_id, tmls.curr_id, 0,0,0,'False')		[prli_priceInStoreCurrency],
		   tmls.curr_id																						[storeCurrency],
		   tpli.prli_price,
		   tpli.curr_id
		FROM tbPriceListItems				tpli	WITH (NOLOCK)
		INNER JOIN tbMercadoLibre_Stores	tmls	WITH (NOLOCK)
			ON	tmls.comp_id = @comp_id AND
				tmls.mls_id	 = @mls_id
		WHERE	tpli.comp_id = @comp_id AND
				tpli.prli_id = @prli_id AND
				tpli.item_id = @item_id



END
GO






CREATE PROCEDURE [dbo].[spPriceListItems_getListForMailing]
(
	@comp_id		INT,
	@bra_id			INT,
	@lang_id		INT,
	@prli_id		INT
)
AS


BEGIN



	SET NOCOUNT ON


	-- -------------------------------------------
	-- Testing
	-- -------------------------------------------
	/*
	DECLARE
		@comp_id		INT,
		@lang_id		INT,
		@prli_id		INT

	SELECT
		@comp_id		= 1,
		@lang_id		= 2,
		@prli_id		= 8
	*/
	-- -------------------------------------------


	DECLARE @message VARCHAR(100)
	SELECT @message = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 160 AND tut.lang_id = @lang_id

	DECLARE @message2 VARCHAR(100)
	SELECT @message2 = utexts_desc FROM	tbsysUniqueTexts tut WHERE tut.utexts_id = 161 AND tut.lang_id = @lang_id



	-- --------------------------------------------------
	-- ATENCION!!!!!!!!!!!!!!!
	-- NO modificar el orden de las columnas
	-- Si hay que agregar algo hacerlo AL FINALLLLLLLL!!
	-- --------------------------------------------------
	SELECT
		tc.cat_desc,
		tsc.subcat_desc,
		tb.brand_desc,
		ti.item_id,
		ti.item_code,
		ti.item_desc,
		CONVERT(decimal(18,2),CONVERT(VARCHAR,  tpli.prli_price))												[price],
		convert(DECIMAL(18,2),CONVERT(VARCHAR,((tpli.prli_price * IsNull(ttn.tax_percentage  ,0)) / 100) +
											  ((tpli.prli_price * IsNull(ttnII.tax_percentage,0)) / 100) +
												tpli.prli_price
									 )
			   )																								[price_plus_tax],
		tc2.curr_symbol,
		@message,
		@message2

	FROM tbItem											ti				WITH (NOLOCK)

		INNER JOIN tbPriceListItems						tpli			WITH (NOLOCK)
		ON	tpli.comp_id = ti.comp_id
		AND tpli.item_id = ti.item_id

		INNER JOIN tbCategory							tc				WITH (NOLOCK)
		ON	tc.comp_id = ti.comp_id
		AND tc.cat_id = ti.cat_id

		INNER JOIN tbSubCategory						tsc				WITH (NOLOCK)
		ON	tsc.comp_id = ti.comp_id
		AND tsc.cat_id = ti.cat_id
		AND tsc.subcat_id = ti.subcat_id

		INNER JOIN tbBrand								tb				WITH (NOLOCK)
		ON		tb.comp_id	= ti.comp_id
			AND tb.brand_id = ti.brand_id

	--	LEFT JOIN tbItemTaxes							tit
	--	ON		tit.comp_id = ti.comp_id
	--		AND tit.item_id = ti.item_id

		left join dbo.vwItemTaxesOnlyOneIvaTax			vttn			WITH (NOLOCK)
			ON		vttn.comp_id = ti.comp_id
				AND vttn.item_id = ti.item_id

		LEFT JOIN tbTaxName								ttn				WITH (NOLOCK)
		ON  ttn.comp_id = vttn.comp_id
		AND ttn.tax_id  = vttn.tax_id

		left join dbo.vwItemTaxesOnlyOneInternalTax			vttnII		WITH (NOLOCK)
			ON		vttnII.comp_id = ti.comp_id
				AND vttnII.item_id = ti.item_id

		LEFT JOIN tbTaxName								ttnII			WITH (NOLOCK)
		ON  ttnII.comp_id = vttnII.comp_id
		AND ttnII.tax_id  = vttnII.tax_id

		LEFT JOIN tbsysTaxClass							ttc				WITH (NOLOCK)
		ON ttc.tax_class = ttn.tax_class

		INNER JOIN tbsysCurrency						tc2				WITH (NOLOCK)
		ON tc2.curr_id = tpli.curr_id

	WHERE	ti.comp_id									= @comp_id
	AND		tpli.prli_id								= @prli_id
	AND		ttc.taxcl_isIVA								= 'True'
	AND		ttc.taxcl_isPerception						= 'False'
	AND		ttc.taxcl_isRetention						= 'False'
	AND		isnull(ti.item_disabled,'False')			= 'False'
	AND		isnull(ti.item_disabledInPriceList,'False')	= 'False'
	AND		tpli.prli_price <> 0

	ORDER BY	tc.cat_desc,
				tc.cat_id,
				tsc.subcat_desc,
				tsc.subcat_id,
				tb.brand_desc,
				tb.brand_id,
				ti.item_desc


	SELECT
		tc.bra_MainDesc2,
		tpl.prli_desc,
		@message,
		@message2

	FROM tbBranch tc

	INNER JOIN tbPriceList tpl
	ON tpl.comp_id = tc.comp_id

	WHERE	tc.comp_id	= @comp_id	AND
			tc.bra_id	= @bra_id	AND
			tpl.prli_id = @prli_id



END
GO


CREATE PROCEDURE [dbo].[spPriceListItems_getPriceList4CustomerByBrand]
(
	@comp_id	INT,
	@item_id	INT,
	@cust_id	INT
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- MOS 02-2022
	-- LIsta de precios x Tipo de Artículo y Cliente ( Manera NUEVA de FIESA )
	-- -----------------------------------------------------------------------------
	SELECT	tpl.prli_id				[prli_id]
		INTO #tmpTable
		FROM tbPriceListItemByItemType	AS tcplbst	WITH (NOLOCK)
		INNER JOIN	tbPriceList			AS tpl		WITH (NOLOCK)
			ON	tpl.comp_id		= tcplbst.comp_id	AND
				tpl.prli_id		= tcplbst.prli_id
		WHERE	tcplbst.comp_id = @comp_id AND
				tcplbst.cust_id = @cust_id AND
				tcplbst.item_id = @item_id

	IF @@ROWCOUNT > 0
		BEGIN
			SELECT * FROM  #tmpTable
			DROP     TABLE #tmpTable
			RETURN
		END
	-- -----------------------------------------------------------------------------






	-- Manera VIEJA de FIESA
	SELECT  TOP 1 qq.prli_id
		FROM tbCustomerPriceListBySOItem	AS qq	WITH (NOLOCK)
		INNER JOIN tbCompany				AS tc	WITH (NOLOCK)
			ON tc.comp_id = @comp_id
		INNER JOIN tbItem					AS ti	WITH (NOLOCK)
			ON	ti.comp_id		= qq.comp_id		AND
				ti.item_id		= @item_id
		WHERE	tc.comp_tbCustomerPriceListBySOItem_isEnabled = 'True'	AND
				qq.comp_id		= @comp_id								AND
				qq.cust_id		= @cust_id								AND
				qq.brand_id		= ti.brand_id

	--ORDER BY qq.



END
GO



CREATE PROCEDURE [dbo].[spPriceListItems_getPriceListBySOItem]
(
	@comp_id	INT,
	@cust_id	INT,
	@item_id	INT
)
AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@cust_id	INT,
			@item_id	INT
	SELECT  @comp_id	= 1,
			@cust_id	= 24300,
			@item_id	= 16050
	*/
	-- -----------------------------------------------------------------------------


	-- -----------------------------------------------------------------------------
	-- LIsta de precios x Tipo de Artículo y Cliente ( Manera NUEVA de FIESA )
	-- -----------------------------------------------------------------------------
	SELECT	tpl.prli_id								[ID],
			tpl.prli_desc							[DESC],
			ISNULL(tcplbst.tipi_discount,0)			[Discount],
			ISNULL(tcplbst.combo_price,0)			[combo_price],			-- FORRADAS de FIESA de Combos Precalculados segun la ENFERMA manera de trabajar.
			ISNULL(tcplbst.combo_pricePlusTax,0)	[combo_pricePlusTax],	-- FORRADAS de FIESA de Combos Precalculados segun la ENFERMA manera de trabajar.
			ISNULL(tcplbst.curr_id,-1)				[combo_curr_id]			-- FORRADAS de FIESA de Combos Precalculados segun la ENFERMA manera de trabajar.
		INTO #tmpTable
		FROM tbPriceListItemByItemType	AS tcplbst	WITH (NOLOCK)
		INNER JOIN	tbPriceList			AS tpl		WITH (NOLOCK)
			ON	tpl.comp_id		= tcplbst.comp_id	AND
				tpl.prli_id		= tcplbst.prli_id
		WHERE	tcplbst.comp_id = @comp_id AND
				tcplbst.cust_id = @cust_id AND
				tcplbst.item_id = @item_id

	IF @@ROWCOUNT > 0
		BEGIN
			SELECT * FROM  #tmpTable
			DROP     TABLE #tmpTable
			RETURN
		END
	-- -----------------------------------------------------------------------------




	-- LIsta de precios x Marca  y Cliente ( Manera Vieja de FIESA )
	SELECT	tpl.prli_id		[ID],
			tpl.prli_desc	[DESC],
			0				[Discount],
			0				[combo_price],
			0				[combo_pricePlusTax],
			-1				[combo_curr_id]
		FROM		tbItem						AS	ti		WITH (NOLOCK)
		INNER JOIN	tbCustomerPriceListBySOItem		tco		WITH (NOLOCK)
			ON	tco.comp_id		= ti.comp_id	AND
				tco.cust_id		= @cust_id		AND
				tco.brand_id	= ti.brand_id
		INNER JOIN	tbPriceList					AS tpl		WITH (NOLOCK)
			ON	tpl.comp_id		= tco.comp_id	AND
				tpl.prli_id		= tco.prli_id
		INNER JOIN tbPriceListItems				AS tpli		WITH (NOLOCK)
			ON	tpli.comp_id = @comp_id			AND
				tpli.prli_id = tco.prli_id		AND
				tpli.item_id = @item_id
		INNER JOIN tbCompany					AS tc		WITH (NOLOCK)
			ON tc.comp_id = @comp_id
		WHERE	tc.comp_tbCustomerPriceListBySOItem_isEnabled = 'True'	AND
				ti.comp_id		= @comp_id								AND
				ti.item_id		= @item_id


END
GO

CREATE PROCEDURE [dbo].[spPriceListItems_UpdatePriceFromMLPublication]
(
	@comp_id	INT,
	@user_id	INT,
	@item_id	INT,
	@prli_id	INT,
	@price		DECIMAL(19,4),
	@curr_id	INT	--ID DE MONEDA DE LA PUBLICACION
	--@mls_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 1000
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- ---------------------------------------
		-- TESTING
		-- ---------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@user_id	INT,
				@item_id	INT,
				@prli_id	INT,
				@curr_id	INT,
				@price		DECIMAL(19,4)
			SELECT
				@comp_id	= 1,
				@user_id	= 135,
				@item_id	= 1,
				@prli_id	= 1,
				@curr_id	= 1,
				@price		= 100
		*/
		-- ---------------------------------------


		-- -------------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- -------------------------------------------------------
			DECLARE
				@prli_curr_id	INT,
				@original_price	DECIMAL(19,6),
				@mls_curr_id	INT
		-- -------------------------------------------------------

		-- -------------------------------------------------------
		-- ME GUARDO LOS VALORES ORIGINALES DE LA LISTA DE PRECIOS
		-- -------------------------------------------------------
			SELECT
				@prli_curr_id		= tpli.curr_id,
				@original_price		= tpli.prli_price
			FROM tbPriceListItems			tpli	WITH(NOLOCK)
			WHERE	tpli.comp_id = @comp_id AND
					tpli.prli_id = @prli_id AND
					tpli.item_id = @item_id
		-- -------------------------------------------------------

		-- -------------------------------------------------------
		-- ME GUARDO LA MONEDA DE LA TIENDA DE MERCADOLIBRE
		-- -------------------------------------------------------
			--SELECT
			--	@mls_curr_id		= tmls.curr_id
			--FROM tbMercadoLibre_Stores			tmls	WITH(NOLOCK)
			--WHERE	tmls.comp_id	= @comp_id	AND
			--		tmls.mls_id		= @mls_id
		-- -------------------------------------------------------

		-- -------------------------------------------------------
		-- ACTUALIZO EL PRECIO EN LA LISTA
		-- -------------------------------------------------------
			UPDATE tbPriceListItems	WITH(ROWLOCK)
			SET
				prli_price					= dbo.fnGetExchange2(@comp_id, @price, @curr_id, @prli_curr_id, 0,0,0,'False'),
				prli_price_PreLastUpdate	= @original_price,
				curr_id_PreLastUpdate		= @prli_curr_id,
				user_id_lastUpdate			= @user_id
				WHERE	comp_id				= @comp_id AND
						prli_id				= @prli_id AND
						item_id				= @item_id
		-- -------------------------------------------------------


	END
GO

