CREATE PROCEDURE [dbo].[spPrintQueue_GetDataByQueueID]
(
	@printQueue_id	UNIQUEIDENTIFIER
)
AS


	BEGIN

		/*
		-- -----------------------------------
		-- Test
		-- -----------------------------------
		declare @printQueue_id	UNIQUEIDENTIFIER = 'AD496862-30E5-443A-B3EB-E7FC4373A464'
		-- -----------------------------------
		*/




		SET NOCOUNT ON
		SELECT TOP 10
			tpq.printQueue_JobID,
			--tpq.printQueue_id,
			tpq.printQueue_printerName,
			tpq.printQueue_printCopies,
			ISNULL(tpq.printQueue_Content,'')			[printQueue_Content],
			tpq.printQueue_ContentRAW,
			tpq.ct_transaction,
			tpq.printQueue_typeRAW,
			tpq.printQueue_typePDF,
			tpq.[USER_ID],
			tpq.printQueue_fileName
			INTO #tmpTable
			FROM tbPrintQueue AS tpq	WITH(NOLOCK)
			WHERE tpq.printQueue_id = @printQueue_id
			ORDER BY tpq.printQueue_JobID


		DELETE FROM tbPrintQueue
			FROM tbPrintQueue AS tpq	WITH (NOLOCK)
			INNER JOIN #tmpTable tmp
				ON tmp.printQueue_JobID = tpq.printQueue_JobID

		SELECT * FROM #tmpTable

		DROP TABLE #tmpTable

	END
GO

CREATE PROCEDURE [dbo].[spPrintQueue_InsertData]
(
	@printQueue_id			UNIQUEIDENTIFIER,
	@printQueue_printerName	VARCHAR(250),
	@printQueue_printCopies	INT,
	@printQueue_Content		IMAGE,
	@printQueue_ContentRAW	NTEXT,
	@ct_transaction			INT,
	@printQueue_typeRAW		BIT,
	@printQueue_typePDF		BIT,
	@USER_ID				INT,
	@printQueue_fileName    VARCHAR(50)
)
AS
	BEGIN
		SET NOCOUNT	ON

		IF @ct_transaction <= 0 SET @ct_transaction = NULL



		INSERT INTO tbPrintQueue
		(
			-- printQueue_JobID -- this column value is auto-generated
			printQueue_id,
			printQueue_printerName,
			printQueue_printCopies,
			printQueue_Content,
			ct_transaction,
			printQueue_typeRAW,
			printQueue_typePDF,
			[USER_ID],
			printQueue_ContentRAW,
			printQueue_fileName
		)
		VALUES
		(
			@printQueue_id,
			@printQueue_printerName,
			@printQueue_printCopies,
			@printQueue_Content,
			@ct_transaction,
			@printQueue_typeRAW,
			@printQueue_typePDF,
			@USER_ID,
			@printQueue_ContentRAW,
			@printQueue_fileName
		)
	END
GO






