CREATE PROCEDURE [dbo].[spProcedureManual_GetDataByFilters]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@procc_id				UNIQUEIDENTIFIER


)
AS


BEGIN



	-----------------------------------------------------------------------------------
	--Test
	----------------------------------------------------------------------------------
	/*
	declare
		@comp_id				INT,
		@lang_id				INT,
		@bra_id					INT,
		@prof_id				INT,
		@user_id				INT

	SELECT

		@comp_id				 = 1,
		@lang_id				= 2,
		@bra_id					= 1,
		@prof_id				= 1,
		@user_id				= 1,

		@GuidItem				='b65d24ab-f319-48d1-8d97-a169136a1c7b',
		@GuidSupp				='f5b83bf5-b48c-4d6f-b3ad-c429405dc7d4',
		@import_id				= -1,
		@brag_id				=-1,
		@datefrom				='1900-01-01',
		@dateto					='2099-04-06'

	*/
	-----------------------------------------------------------------------------------
	--Test
	---------------------------------------------------------------------

		SET NOCOUNT ON



		SELECT
			''																		[1],
			tpmc.proc_desc															[proc_desc],	-- Contenido de Procedimiento
			tpm.procc_desc															[procc_desc],	-- Grupo de Procedimiento
			tpmc.proc_id															[ID]

			FROM tbProcedureManual_Contents						tpmc				WITH (NOLOCK)

			INNER JOIN tbProcedureManual						tpm					WITH (NOLOCK)
			ON	tpm.comp_id			= tpmc.comp_id		AND
				tpm.procc_id		= tpmc.procc_id

			INNER JOIN tbProcedureManual_ProfileRelations		tpmpr				WITH (NOLOCK)
			ON	tpmpr.comp_id		= tpm.comp_id 		AND
				tpmpr.prof_id		= @prof_id			AND
				tpmpr.procc_id		= tpm.procc_id

			WHERE	tpmc.comp_id						= @comp_id		AND
					isnull(tpmc.proc_disabled,'false')	= 'False'		AND
					(@procc_id	= '00000000-0000-0000-0000-000000000000' OR	tpm.procc_id	= @procc_id	)

			ORDER BY tpm.procc_id desc



END
GO



