		@tax_id		INT,
		@tax_id_to	INT
*/
-- -----------------------------------------------


--Cargo el texto
DECLARE
	@message	VARCHAR (150)

SELECT  @message = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 5102



UPDATE	tbItemTaxes

SET		tax_id = @tax_id_to

FROM	tbItemTaxes			tit
		INNER JOIN tbItem	ti
		ON	tit.comp_id = ti.comp_id
		AND tit.item_id = ti.item_id

WHERE	tit.tax_id	= @tax_id
AND		(@cat_id	= -1		OR ti.cat_id	= @cat_id	)
AND		(@subcat_id = -1		OR ti.subcat_id	= @subcat_id)




INSERT INTO tbSecurityLog
						(
							comp_id,
							bra_id,
							[user_id],
							seclog_obs_1,
							seclog_obs_2,
							seclog_image,
							seclog_obs_3,
							seclog_obs_4,
							seclog_cd,
							aut_id,
							sysCode_id,
							menu_id,
							menu_ts,
							request_ip,
							request_name,
							aure_isok,
							aure_user_id,
							seclog_pageHTML,
							prof_id,
							aure_cd,
							aure_id,
							seclog_id1,
							seclog_id2,
							seclog_id3
						)
						VALUES
						(
							@comp_id,
							@bra_id,
							@user_id,
							@message,
							NULL,
							NULL,
							NULL,
							NULL,
							GETDATE(),
							NULL,
							700,
							NULL,
							NULL,
							NULL,
							NULL,
							NULL,
							NULL,
							NULL,
							@prof_id,
							NULL,
							NULL,
							NULL,
							NULL,
							NULL
						)
GO



CREATE PROCEDURE [dbo].[spProcess_UpdateSerialsQty]
(
	@comp_id	INT,
	@bra_id		INT,
	@lang_id	INT,
	@prof_id	INT,
	@user_id	INT
)
AS

SET NOCOUNT ON

BEGIN


	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@bra_id		INT,
			@lang_id	INT,
			@prof_id	INT,
			@user_id	INT
	SELECT	@comp_id	=1,
			@bra_id		=1,
			@lang_id	=2,
			@prof_id	=1,
			@user_id	=1
	*/
	-- -----------------------------------------------------------------------

	DECLARE	@ct_transaction			INT,
			@it_transaction			INT,
			@it_qty					DECIMAL(19,6),

			@it_qty_pending			DECIMAL(19,6),

			@item_serial			NVARCHAR(100),
			@item_expser			INT,

			@item_id				INT,
			@stor_id				INT,
			@stock					DECIMAL(18,5),
			@value					INT,

			@serial_qty				INT,
			@itemserials_qty		INT,
			@bra_id_transaction		INT,

			@message				NVARCHAR(200),
			@errormessage			NVARCHAR(500),

			@getdate				DATETIME





	--variable de tabla definida para ser utilizada luego para la generación de repeticiones en los
	--inserts masivos en tbItemsSerials
	DECLARE @tmpRepet AS TABLE (id INT)



	BEGIN TRANSACTION
	BEGIN TRY

		SET @getdate  = GETDATE()

		--recupero en un cursor los artículos que tienen stock por depósito	y cuyo stock es mayor que
		--la cantidad de registros para serializar existentes
		DECLARE cursorProcess CURSOR LOCAL FAST_FORWARD FOR
		SELECT	ti.item_id,
				tis.stor_id,
				dbo.fnGetStock(@comp_id,tis.stor_id, ti.item_id),		--stock físico
				SUM(CASE WHEN tis2.comp_id IS NULL THEN 0 ELSE 1 END) 	--sumatoria de registros para serializar existentes

		FROM	tbItem							ti		WITH (NOLOCK)

				INNER JOIN tbItemStorage		tis		WITH (NOLOCK)
				ON  tis.comp_id = ti.comp_id
				AND tis.item_id = ti.item_id

				INNER JOIN tbStorage			ts		WITH (NOLOCK)
				ON	ts.comp_id	= tis.comp_id
				AND ts.stor_id	= tis.stor_id
				AND isnull(ts.stor_web4ALL, 'false') = 'true'

				LEFT JOIN tbItemSerials			tis2		WITH (NOLOCK)
				ON  tis2.comp_id	= ti.comp_id
				AND tis2.item_id	= ti.item_id
				AND tis2.stor_id	= tis.stor_id
				--AND tis2.is_available = 'true'
				AND ISNULL(tis2.is_serial,'') = ''

		WHERE	ti.comp_id		= @comp_id
		AND		ti.item_expser	= 'true'
		AND		dbo.fnGetStock(@comp_id, tis.stor_id, tis.item_id)		> 0

		--AND		ti.item_id=12

		GROUP BY ti.item_id,	tis.stor_id

		HAVING	dbo.fnGetStock(@comp_id,tis.stor_id, ti.item_id) >
					SUM(CASE WHEN tis2.comp_id IS NULL THEN 0 ELSE 1 END)

		ORDER BY ti.item_id,	tis.stor_id





		OPEN	cursorProcess

		FETCH	cursorProcess
		INTO	@item_id,
				@stor_id,
				@stock,
				@value


		WHILE @@FETCH_STATUS = 0
		BEGIN

			--SELECT 'a', @item_id [item_id], @stor_id [sotr_id], @stock [stock], @value [itemserials]



			--seteo en una variable la cantidad de seriales efectivos que se deben cargar en tbitemserials
			--esto es el stock físico menos la cantidad de registros existentes para serializar
			SET @it_qty_pending = @stock - @value




			--recupero en un cursor los datos de los items comprados para el depósito correspondiente ordenados
			--por fecha de compra en forma descendente y la cantidad de registros que ya tienen generados para
			--serializar si es que tuvieran
			DECLARE cursor_item_transactions CURSOR LOCAL FAST_FORWARD FOR
			SELECT	tit.ct_transaction,
					tit.it_transaction,
					tit.it_qty,
					tit.bra_id,
					SUM(CASE WHEN tis.comp_id IS NULL THEN 0 ELSE 1 END)

			FROM	tbItemTransactions						tit		WITH (NOLOCK)

					INNER JOIN tbCommercialTransactions		tct		WITH (NOLOCK)
					ON	tct.comp_id			= tit.comp_id
					AND tct.ct_transaction	= tit.ct_transaction
					AND tct.sd_id			IN (101,102,124,130,350)

					LEFT JOIN tbItemSerials					tis		WITH (NOLOCK)
					ON	tis.comp_id			= tit.comp_id
					AND tis.ct_transaction	= tit.ct_transaction
					AND tis.it_transaction	= tit.it_transaction
					AND tis.stor_id			= tit.stor_id


			WHERE	tit.comp_id		= @comp_id
			AND		tit.item_id		= @item_id
			AND		tit.stor_id		= @stor_id

			GROUP BY	tit.ct_transaction,
						tit.it_transaction,
						tit.it_qty,
						tit.bra_id,
						tct.ct_date

			HAVING	tit.it_qty > SUM(CASE WHEN tis.comp_id IS NULL THEN 0 ELSE 1 END)

			ORDER BY tct.ct_date DESC



			OPEN cursor_item_transactions


			FETCH	cursor_item_transactions
			INTO	@ct_transaction,
					@it_transaction,
					@it_qty,
					@bra_id_transaction,
					@itemserials_qty



			--recorremos el cursor de items comprados mientras haya registros en el cursor y haya item pendientes
			--de generar espacios para serializar
			WHILE @@FETCH_STATUS = 0 AND @it_qty_pending > 0
			BEGIN


				--seteo una variable con la cantidad de registros que se deben insertar en tbItemSerials
				--si la cantidad pendiente de generar es mayor que la cantidad de itemTransaction recuperado
				--se toma esta última cantidad, sino se toma la cantidad pendiente
				IF @it_qty_pending > (@it_qty - @itemserials_qty)
					SET @serial_qty = (@it_qty - @itemserials_qty)
				ELSE
					SET @serial_qty = @it_qty_pending




				/*
				SELECT	'b',
						@item_id			[item_id],
						@stor_id			[stor_id],
						@ct_transaction		[ct_transaction],
						@it_transaction		[it_transaction],
						@it_qty				[it_qty],
						@it_qty_pending		[it_qty_pending],
						@itemserials_qty	[@itemserials_qty],
						@serial_qty			[@serial_qty]
				*/



				--SELECT @serial_qty
				--en la tabla creada al inicio del sp, insertamos la cantidad de registros que se deben insertar
				--en la tabla tbItemSerials (no encontré la manera de hacer el insert sin el select, utilizo todos
				--los union all para poder hacer inserts masivos hasta 60000 registros, utilizo la tbSysWordsIni porque
				--tiene más de 3500 registros)
				INSERT TOP(@serial_qty) INTO @tmpRepet(id)
					SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
						UNION ALL SELECT 1 FROM tbSysWordsIni
				--SELECT COUNT(*) FROM @tmpRepet




				--insertar en tbitemserials los registros faltantes para serializar, la cantidad de registros
				--está resuelta por el inner join con la tabla @tmpRepet

				INSERT INTO tbItemSerials
				(
					comp_id,
					bra_id,
					ct_transaction,
					it_transaction,
					item_id,
					is_serial,
					is_cd,
					is_available,
					stor_id,
					is_guid,
					is_IsOwnGeneration,
					is_checked,
					is_printed
				)

				SELECT 	tit.comp_id,
						tit.bra_id,
						tit.ct_transaction,
						tit.it_transaction,
						tit.item_id,
						NULL,
						@getdate, --tit.it_cd,
						'False',
						tit.stor_id,
						NULL,
						'False',
						'False',
						'False'

				FROM	tbItemTransactions	tit

						INNER JOIN @tmpRepet ON 1=1

				WHERE	tit.comp_id			= @comp_id
				AND		tit.ct_transaction	= @ct_transaction
				AND 	tit.it_transaction	= @it_transaction
				AND		tit.stor_id			= @stor_id




				--elimino los registros cargadoe en la tabla @tmpRepet para el próximo insert
				DELETE FROM @tmpRepet




				--actualizamos la tbImportData
				IF EXISTS (	SELECT TOP 1 	1
								FROM	tbImportData			tid
								WHERE	tid.comp_id			= @comp_id
								AND		tid.item_id			= @item_id
								AND		tid.ct_transaction	= @ct_transaction
								AND		tid.it_transaction	= @it_transaction	)
					BEGIN

						DECLARE @itemSerialFree		INT

						SELECT	@itemSerialFree		= COUNT(*)
							FROM	tbItemSerials		tis
							WHERE	tis.comp_id					= @comp_id
							AND		tis.ct_transaction			= @ct_transaction
							AND		tis.it_transaction			= @it_transaction
							AND		tis.item_id					= @item_id
							AND		ISNULL(tis.is_serial,'')	= ''
							AND		tis.is_available			='true'


						UPDATE	tbImportData
							SET		impData_InitialQty	=	@it_qty,
									impData_ActualQty	=	@itemSerialFree
							WHERE	comp_id			= @comp_id
							AND		item_id			= @item_id
							AND		ct_transaction	= @ct_transaction
							AND		it_transaction	= @it_transaction

					END
				ELSE
					BEGIN
						--SELECT 'insert tbImportData'

						INSERT INTO tbImportData
						(
							comp_id,
							item_id,
							impData_InitialQty,
							impData_ActualQty,
							ct_transaction,
							it_transaction,
							bra_id,
							impData_Custom_local,
							impData_Number_local,
							impData_ExpirationDate,
							impData_Origin,
							impData_From,
							impdata_Stamp
						)
						VALUES
						(
							@comp_id,
							@item_id,
							@serial_qty,
							@serial_qty,
							@ct_transaction,
							@it_transaction,
							@bra_id_transaction,
							'',
							'',
							NULL,
							'',
							'',
							''
						)

					END




				--actualizo la cantidad pendiente, restándole lo que se acaba de insertar
				SELECT @it_qty_pending = @it_qty_pending - @serial_qty




				FETCH	cursor_item_transactions
				INTO	@ct_transaction,
						@it_transaction,
						@it_qty,
						@bra_id_transaction,
						@itemserials_qty


			END

			CLOSE cursor_item_transactions
			DEALLOCATE cursor_item_transactions





			FETCH	cursorProcess
			INTO	@item_id,
					@stor_id,
					@stock,
					@value


		END


		CLOSE cursorProcess
		DEALLOCATE cursorProcess








		/*****************************************************************************************************************************/
		/* eliminación de seriales de más con respecto al stock*/
		DECLARE		@lstor_id		INT,
					@litem_id		INT,
					@litst_cant		DECIMAL(18,5),
					@COUNT_			DECIMAL(18,5),
					@diferencia		INT

		DECLARE itemstock CURSOR FOR
		SELECT	tis.stor_id, tis.item_id, tis.itst_cant, COUNT(*), COUNT(*) - tis.itst_cant
			FROM	tbItemStorage					tis			WITH (NOLOCK)
			INNER JOIN tbItemSerials				tis2		WITH (NOLOCK)
				ON	tis2.comp_id = tis.comp_id
				AND tis2.stor_id = tis.stor_id
				AND tis2.item_id = tis.item_id
				AND isnull(tis2.is_serial,'') = ''
			WHERE	tis.comp_id		= @comp_id
			AND		tis.itst_cant	> 0
			GROUP BY	tis.stor_id, tis.item_id, tis.itst_cant
			HAVING		tis.itst_cant < COUNT(*)

		OPEN itemstock

		FETCH itemstock INTO
				@lstor_id,
				@litem_id,
				@litst_cant,
				@COUNT_,
				@diferencia

		WHILE @@FETCH_STATUS = 0
		BEGIN

			DELETE FROM tbItemSerials
				WHERE is_id IN (	SELECT TOP (@diferencia) tis.is_id
			                			FROM tbItemSerials					tis			WITH (NOLOCK)
			                			LEFT JOIN tbItemTransactionSerials	tits		WITH (NOLOCK)
			                				ON  tits.comp_id	= tis.comp_id	AND
			                					tits.is_id		= tis.is_id
										WHERE	tis.comp_id = @comp_id	AND
												tis.item_id = @litem_id	AND
												tis.stor_id = @lstor_id	AND
												tits.comp_id IS NULL
										ORDER BY tis.is_cd )


			FETCH itemstock INTO
					@lstor_id,
					@litem_id,
					@litst_cant,
					@COUNT_,
					@diferencia

		END

		CLOSE itemstock
		DEALLOCATE itemstock

		/*****************************************************************************************************************************/







		COMMIT TRANSACTION

		SET @errormessage = ''

	END
	TRY BEGIN CATCH
		ROLLBACK TRANSACTION

		SET @errormessage = ERROR_MESSAGE()

	END CATCH



	--Se loguea el proceso de generación de seriales pendientes



	SELECT  @message	= tut.utexts_desc
		FROM	tbsysUniqueTexts				tut		WITH (NOLOCK)
		WHERE	tut.lang_id		= @lang_id
		AND		tut.utexts_id	= 5100



	DECLARE @rv INT--, @getdate DATETIME
	--SET @getdate = GETDATE()



	EXEC spSecurityLog_insertData
		@comp_id		= @comp_id,
		@bra_id			= @bra_id,
		@user_id		= @user_id,
		@seclog_obs_1	= @message,
		@seclog_obs_2	= @errormessage,
		@seclog_obs_3	= null,
		@seclog_obs_4	= null,
		@aut_id			= null,
		@sysCode_id		= 700,
		@menu_id		= null,
		@request_ip		= null,
		@request_name	= null,
		@aure_isok		= null,
		@aure_user_id	= null,
		@prof_id		= @prof_id,
		@aure_id		= null,
		@aure_cd		= @getdate,
		@seclog_id1		= null,
		@seclog_id2		= null,
		@seclog_id3		= null,
		@seclog_pageHTML = null,
		@return_value	= @rv



END

GO







CREATE Procedure [dbo].[spProcesses_getCombo]
(
	@comp_id			INT
)
AS
SET NOCOUNT ON


/*
DECLARE	@comp_id			INT
SELECT	@comp_id =           1
*/


SELECT  tp.proc_id     [Id],
	    tp.proc_desc  [Desc]


FROM   tbProcesses tp

WHERE comp_id = @comp_id

GO







CREATE Procedure [dbo].[spProcesses_getComboFiltered]
(
	@comp_id			INT,
	@proc_id			INT
)
AS
SET NOCOUNT ON


/*
DECLARE	@comp_id			INT
SELECT	@comp_id =           1
*/


SELECT  tp.proc_id     [Id],
	    tp.proc_desc  [Desc]


FROM   tbProcesses tp

WHERE	comp_id = @comp_id
AND		tp.proc_id <> @proc_id

GO







