CREATE PROCEDURE spProduction_GetFinalCost4Item2Produce
(
	@comp_id		INT,
	@bra_id			INT,
	@ProductionType	INT,
	@intID			INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------
		-- TESTING
		-- -------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@ProductionType	INT,	-- 1 Orden de Producción / 2 Fórmula Standard
				@intID			INT
			SELECT
				@comp_id		= 1,
				@bra_id			= 1,
				@ProductionType	= 1,
				@intID			= 3
		*/
		-- -------------------------------------

		--	dbo.fnGetExchange(tsod.comp_id, tsod.sod_price, tsod.curr_id, @bra_curr_id, 0, 0, 0)

		-- -------------------------------------
		-- VARIABLES DE TRABAJO
		-- -------------------------------------
			DECLARE
				@coslis_id		INT,
				@curr_Symbol	VARCHAR(10)
		-- -------------------------------------

		-- RECUPERO LA LISTA DE COSTOS DE LA SUCURSAL
			SELECT
				@coslis_id			= tb.coslis_id
				FROM tbBranch					tb
				WHERE	tb.comp_id	= @comp_id	AND
						tb.bra_id	= @bra_id

		--RECUPERO EL SIMBOLO DE LA MONEDA
			SELECT
				@curr_Symbol = tc.curr_symbol
				FROM tbsysCurrency					tc
				INNER JOIN tbItemCostList			ticl
				ON ticl.curr_id = tc.curr_id
				WHERE	ticl.comp_id	= @comp_id	AND
						ticl.coslis_id	= @coslis_id

		-- -----------------------------------------------------------------------------------------
		-- OBTENGO MONEDA DE LA SUCURSAL
		-- -----------------------------------------------------------------------------------------
			DECLARE
				@bra_curr_id		INT,
				@bra_curr_symbol	VARCHAR(10)
			SELECT
				@bra_curr_id		= tb.curr_id,
				@bra_curr_symbol	= tc.curr_symbol
				FROM tbBranch					tb
					INNER JOIN tbsysCurrency	tc
					ON	tc.curr_id	= tb.curr_id
				WHERE	tb.comp_id	= @comp_id	AND
						tb.bra_id	= @bra_id
		-- -----------------------------------------------------------------------------------------



		IF @ProductionType = 1
			BEGIN

				DECLARE @tbProductionOrderItems TABLE (
														comp_id						INT,
														prorh_id					INT,
														prord_id					INT,
														item_id						INT,
														qty							INT,
														additionalPercentFromCost	DECIMAL(19,4),
														additionalPrice				DECIMAL(19,4),
														curr_id						INT,
														coslis_price				DECIMAL(19,4),
														coslis_curr_id				INT,
														finalCost					DECIMAL(19,4)
													  )

				INSERT INTO @tbProductionOrderItems
				(
					comp_id,
					prorh_id,
					prord_id,
					item_id,
					qty,
					additionalPercentFromCost,
					additionalPrice,
					curr_id,
					coslis_price,
					coslis_curr_id
				)
				SELECT
					tpod.comp_id,
					tpod.prorh_id,
					tpod.prord_id,
					tpod.item_id,
					tpod.prsfd_QTY,
					tpod.prsfd_additionalPercentFromCost,
					tpod.prsfd_additionalPrice,
					tpod.curr_id,
					ticl.coslis_price,
					ticl.curr_id
					FROM tbProduction_ORDER_detail		tpod
					INNER JOIN tbItemCostList			ticl
					ON	ticl.comp_id	= tpod.comp_id	AND
						ticl.item_id	= tpod.item_id	AND
						ticl.coslis_id	= @coslis_id
					WHERE	tpod.comp_id	= @comp_id	AND
							tpod.prorh_id	= @intID
				--==
					/*
					SELECT
						*
					FROM @tbProductionOrderItems
					*/
				--==

				--ACÁ ACTUALIZO EL COSTO, SE LE SUMAN LOS PORCENTAJES ADICIONALES Y EL ADICIONAL DE COSTO
				UPDATE @tbProductionOrderItems
				SET
					finalCost = (dbo.fnGetExchange(comp_id, coslis_price, coslis_curr_id, @bra_curr_id, 0, 0, 0) * qty) +														--COSTO ARTÍCULOS
								(((dbo.fnGetExchange(comp_id, coslis_price, coslis_curr_id, @bra_curr_id, 0, 0, 0) * qty) * additionalPercentFromCost) / dbo.fnNoZDiv(100)) +	--SUMA DE PORCENTAJE ADICIONAL
								dbo.fnGetExchange(comp_id, additionalPrice, curr_id, @bra_curr_id,0 ,0 ,0)																		--PRECIO ADICIONAL


				--ACA VAMOS A SUMAR EL COSTO TOTAL DEL PRODUCTO A PRODUCIR
				DECLARE @totalCostOrder	DECIMAL(19,4)

				SELECT
					@totalCostOrder =  SUM(finalCost)
				FROM @tbProductionOrderItems

				-- COSTO TOTAL DEL ARTÍCULO A PRODUCIR EN MONEDA DE LA SUCURSAL
				SELECT
					@bra_curr_symbol	[curr_Symbol],
					@totalCostOrder		[TotalCost]

			END

		IF @ProductionType = 2
			BEGIN
				INSERT INTO @tbProductionOrderItems
				(
					comp_id,
					prorh_id,
					prord_id,
					item_id,
					qty,
					additionalPercentFromCost,
					additionalPrice,
					curr_id,
					coslis_price,
					coslis_curr_id
				)
				SELECT
					tpsfd.comp_id,
					tpsfd.prsf_id,
					tpsfd.prsfd_id,
					tpsfd.item_id,
					tpsfd.prsfd_QTY,
					tpsfd.prsfd_additionalPercentFromCost,
					tpsfd.prsfd_additionalPrice,
					tpsfd.curr_id,
					ticl.coslis_price,
					ticl.curr_id
					FROM tbProduction_StandardFormula_detail tpsfd
					INNER JOIN tbItemCostList			ticl
					ON	ticl.comp_id	= tpsfd.comp_id	AND
						ticl.item_id	= tpsfd.item_id	AND
						ticl.coslis_id	= @coslis_id
					WHERE	tpsfd.comp_id	= @comp_id	AND
							tpsfd.prsf_id	= @intID
				--==
					/*
					SELECT
						*
					FROM @tbProductionOrderItems
					*/
				--==

				--ACÁ ACTUALIZO EL COSTO, SE LE SUMAN LOS PORCENTAJES ADICIONALES Y EL ADICIONAL DE COSTO
				UPDATE @tbProductionOrderItems
				SET
					finalCost = (dbo.fnGetExchange(comp_id, coslis_price, coslis_curr_id, @bra_curr_id, 0, 0, 0) * qty) +														--COSTO ARTÍCULOS
								(((dbo.fnGetExchange(comp_id, coslis_price, coslis_curr_id, @bra_curr_id, 0, 0, 0) * qty) * additionalPercentFromCost) / dbo.fnNoZDiv(100)) +	--SUMA DE PORCENTAJE ADICIONAL
								dbo.fnGetExchange(comp_id, additionalPrice, curr_id, @bra_curr_id,0 ,0 ,0)																		--PRECIO ADICIONAL


				--ACA VAMOS A SUMAR EL COSTO TOTAL DEL PRODUCTO A PRODUCIR
				DECLARE @totalCostFormula	DECIMAL(19,4)

				SELECT
					@totalCostFormula =  SUM(finalCost)
				FROM @tbProductionOrderItems

				-- COSTO TOTAL DEL ARTÍCULO A PRODUCIR EN MONEDA DE LA SUCURSAL
				SELECT
					@bra_curr_symbol		[curr_Symbol],
					@totalCostFormula		[TotalCost]

			END

	END



GO

