CREATE PROCEDURE [dbo].[spProduction_Order_Detail_GetData4Header]
(
	@comp_id	INT,
	@prorh_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@prsf_id	INT
			SELECT
				@comp_id	= 1,
				@prorh_id	= 1
		*/
		-- ------------------------------------

		SELECT
			' '											[ ],		--1 Ver Stock
			' '											[ ],		--2 Modificar
			' '											[ ],		--3 Eliminar
			' '											[ ],		--4 Otros 1
			' '											[ ],		--5 Otros 2
			' '											[ ],		--6 Otros 3
			' '											[ ],		--7	Ver FC

			ti.item_code,
			ti.item_desc,
			tmu.mu_desc,
			tpod.prsfd_QTY,
			tpct.spft_desc,
			tpod.prsfd_note,
			tpod.prsfd_additionalPercentFromCost,
			tpod.prsfd_additionalPrice,
			tc.curr_symbol,
			tpod.prord_id								[ID]
			FROM tbProduction_ORDER_detail				tpod
			INNER JOIN tbItem							ti
			ON	ti.comp_id		= tpod.comp_id			AND
				ti.item_id		= tpod.item_id
			INNER JOIN tbMetricUnits					tmu
			ON	tmu.comp_id		= tpod.comp_id			AND
				tmu.mu_id		= tpod.mu_id
			INNER JOIN tbsysProduction_componentType	tpct
			ON	tpct.spft_id	= tpod.spft_id
			INNER JOIN tbsysCurrency					tc
			ON	tc.curr_id		= tpod.curr_id
			WHERE	tpod.comp_id	= @comp_id			AND
					tpod.prorh_id	= @prorh_id


	END
GO

