CREATE PROCEDURE [dbo].[spProduction_Order_Header_UpdateData]
(
	@comp_id				INT,
	@prorh_id				INT,
	@prsf_qty				INT,
	@user_id				INT,
	@brag_id				INT,
	@stor_id4Production		INT,
	@stor_id4RawMaterial	INT,
	@mu_id					INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@prorh_id				INT,
				@prsf_qty				INT,
				@user_id				INT,
				@brag_id				INT,
				@stor_id4Production		INT,
				@stor_id4RawMaterial	INT
		*/
