CREATE PROCEDURE [dbo].[spProduction_Order_InsertDataFromStandardFormula]
(
	@comp_id	INT,
	@prsf_id	INT,
	@user_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@prsf_id	INT,
				@user_id	INT
		*/
		-- -------------------------------------------


		-- ---------------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- ---------------------------------------------------------
			DECLARE
				@intprsf_id	INT
			SET @intprsf_id = -1
		-- ---------------------------------------------------------

		-- ---------------------------------------------------------
		--GRABAMOS EL HEADER
		-- ---------------------------------------------------------

			INSERT INTO tbProduction_ORDER_header
			(
				comp_id,
				-- prorh_id -- this column value is auto-generated,
				item_id,
				prsfc_id,
				prsf_standardQTY,
				mu_id,
				user_id_creator,
				prsf_cd,
				brag_id,
				stor_id4Production,
				stor_id4RawMaterial
			)
			SELECT
				tpsfh.comp_id,
				tpsfh.item_id,
				tpsfh.prsfc_id,
				tpsfh.prsf_standardQTY,
				tpsfh.mu_id,
				@user_id,
				GETDATE(),
				tpsfh.brag_id,
				tpsfh.stor_id4Production,
				tpsfh.stor_id4RawMaterial
			FROM tbProduction_StandardFormula_header	tpsfh
			WHERE	tpsfh.comp_id = @comp_id			AND
					tpsfh.prsf_id = @prsf_id

			SET @intprsf_id = @@IDENTITY

		-- ---------------------------------------------------------


		-- ---------------------------------------------------------
		-- GRABAMOS EL DETALLE
		-- ---------------------------------------------------------
		--SI grabó la header, grabamos el detalle
		IF @intprsf_id <> 0
			BEGIN

				INSERT INTO tbProduction_ORDER_detail
				(
					comp_id,
					prorh_id,
					item_id,
					mu_id,
					prsfd_QTY,
					spft_id,
					prsfd_note,
					prsfd_additionalPercentFromCost,
					prsfd_additionalPrice,
					curr_id--,
					--stor_id DE DONDE SACO ESTE STOR_ID ??????
				)
				SELECT
					tpsfd.comp_id,
					@intprsf_id,
					tpsfd.item_id,
					tpsfd.mu_id,
					tpsfd.prsfd_QTY,
					tpsfd.spft_id,
					tpsfd.prsfd_note,
					tpsfd.prsfd_additionalPercentFromCost,
					tpsfd.prsfd_additionalPrice,
					tpsfd.curr_id
				FROM tbProduction_StandardFormula_detail	tpsfd
				WHERE	tpsfd.comp_id = @comp_id			AND
						tpsfd.prsf_id = @prsf_id

			END
		-- ---------------------------------------------------------

		SELECT @intprsf_id

	END
GO

