CREATE PROCEDURE [dbo].[spProduction_StandardFormula_Header_GetData4ProductionPattern]
(
	@comp_id	INT,
	@item_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------
		-- TESTING
		-- -----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT
			SELECT
				@comp_id	= 1,
				@item_id	= 492
		*/
		-- -----------------------------------------------



		SELECT
			' '											[ ],	--BOTON PARA SELECCIONAR
			' '											[ ],	--BOTON PARA VER DETALLE
			ti.item_code,
			ti.item_desc,
			tpsfh.prsf_standardQTY,
			tpsfc.prsfc_desc,
			tbg.brag_desc,
			ts.stor_desc								[stor_desd4Production],
			ts2.stor_desc								[stor_desc4RawMaterial],
			tpsfh.prsf_id								[ID]
		FROM tbProduction_StandardFormula_header		tpsfh	WITH(NOLOCK)
		INNER JOIN tbItem								ti		WITH(NOLOCK)
		ON	ti.comp_id		= tpsfh.comp_id				AND
			ti.item_id		= tpsfh.item_id
		INNER JOIN tbProduction_StandardFormula_Class	tpsfc	WITH(NOLOCK)
		ON	tpsfc.comp_id	= tpsfh.comp_id AND
			tpsfc.prsfc_id	= tpsfh.prsfc_id
		INNER JOIN tbBranchGroup						tbg		WITH(NOLOCK)
		ON	tbg.comp_id		= tpsfh.comp_id				AND
			tbg.brag_id		= tpsfh.brag_id
		INNER JOIN tbStorage							ts		WITH(NOLOCK)
		ON	ts.comp_id		= tpsfh.comp_id				AND
			ts.stor_id		= tpsfh.stor_id4Production
		INNER JOIN tbStorage							ts2		WITH(NOLOCK)
		ON	ts2.comp_id		= tpsfh.comp_id				AND
			ts2.stor_id		= tpsfh.stor_id4RawMaterial
		WHERE	tpsfh.comp_id = @comp_id				AND
				(
					@item_id		= -1	OR
					tpsfh.item_id	= @item_id
				)

	END
GO


CREATE PROCEDURE [dbo].[spProduction_StandardFormula_Header_GetDataByFilters]
(
	@comp_id			INT,
	@brag_id			INT,
	@user_idCreator		INT,
	@user_idLastUpdate	INT,
	@dateFrom			DATETIME,
	@dateTo				DATETIME,
	@guid_Item			VARCHAR(50)
)
AS

	BEGIN
		SET NOCOUNT ON

		SET DATEFORMAT 'YMD'

		-- ------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@brag_id			INT,
				@user_idCreator		INT,
				@user_idLastUpdate	INT,
				@dateFrom			DATETIME,
				@dateTo				DATETIME,
				@guid_Item			VARCHAR(50)

			SELECT
				@comp_id			=  1,
				@brag_id			= -1,
				@user_idCreator		= -1,
				@user_idLastUpdate	= -1,
				@dateFrom			= '2017-01-01',
				@dateTo				= '2017-12-31',
				@guid_Item			= '027e3ee1-f91d-49fd-9e38-274e6c5f4e19'
		*/
		-- ------------------------------------------------------

		SET @dateFrom	= dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'False')
		SET @dateTo		= dbo.fnGetEnd_or_BeginOfDate(@dateTo,'True')

		DECLARE @lGuid_Item AS UNIQUEIDENTIFIER
		SET		@lGuid_Item = CONVERT(UNIQUEIDENTIFIER,@guid_Item)

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuid_Item     AND
					  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
		-- -------------------------------------------------------------




		SELECT
			'' [ ],
			'' [ ],
			'' [ ],
			ti.item_code,
			ti.item_desc,
			tpsfh.prsf_standardQTY,
			tmu.mu_desc,
			tu.user_lastname  + ',' + tu.user_firstname		[user_creator],
			tu2.user_lastname + ',' + tu2.user_firstname	[user_lastUpdate],
			tbg.brag_desc,
			ts.stor_desc									[stor_4Production],
			ts2.stor_desc									[stor_4RawMaterial],
			tpsfh.prsf_id									[ID]
			FROM tbProduction_StandardFormula_header		tpsfh	WITH(NOLOCK)
			INNER JOIN @tblComplexFilter_Items				tmp
			ON	tmp.item_id		= tpsfh.item_id
			INNER JOIN tbItem								ti		WITH(NOLOCK)
			ON	ti.comp_id		= tpsfh.comp_id				AND
				ti.item_id		= tpsfh.item_id
			INNER JOIN tbMetricUnits						tmu		WITH(NOLOCK)
			ON	tmu.comp_id		= tpsfh.comp_id				AND
				tmu.mu_id		= tpsfh.mu_id
			LEFT JOIN tbBranchGroup							tbg		WITH(NOLOCK)
			ON	tbg.comp_id		= tpsfh.comp_id				AND
				tbg.brag_id		= tpsfh.brag_id
			INNER JOIN tbStorage							ts		WITH(NOLOCK)
			ON	ts.comp_id		= tpsfh.comp_id				AND
				ts.stor_id		= tpsfh.stor_id4Production
			INNER JOIN tbStorage							ts2		WITH(NOLOCK)
			ON	ts2.comp_id		= tpsfh.comp_id				AND
				ts2.stor_id		= tpsfh.stor_id4RawMaterial
			LEFT JOIN tbUser								tu		WITH(NOLOCK)
			ON	tu.[user_id]	= tpsfh.user_id_creator
			LEFT JOIN tbUser								tu2		WITH(NOLOCK)
			ON tu2.[user_id]	= tpsfh.user_id_lastUpdate
			WHERE		tpsfh.comp_id	= @comp_id				AND
					(
						@brag_id				= -1		OR
						tpsfh.brag_id			= @brag_id
					)											AND
					(
						@user_idCreator			= -1		OR
						tpsfh.user_id_creator	= @user_idCreator
					)											AND
					(
						@user_idLastUpdate		= -1		OR
						tpsfh.user_id_lastUpdate= @user_idLastUpdate
					)											AND
					tpsfh.prsf_cd BETWEEN @dateFrom AND @dateTo

	END
GO

