CREATE PROCEDURE [dbo].[spProduction_StandardFormula_Header_InsertData]
(
	@comp_id					INT,
	@item_id					INT,
	@prsfc_id					INT,
	@prsf_standardQTY			INT,
	@mu_id						INT,
	@user_id_creator			INT,
	@brag_id					INT,
	@stor_id4Production			INT,
	@stor_id4RawMaterial		INT,
	@return_value				INT OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id					INT,
				@item_id					INT,
				@prsfc_id					INT,
				@prsf_standardQTY			INT,
				@mu_id						INT,
				@user_id_creator			INT,
				@brag_id					INT,
				@stor_id4Production			INT,
				@stor_id4RawMaterial		INT,
				@return_value				INT
		*/
		-- -------------------------------------------------

		IF @mu_id = -1
			BEGIN
				SET @mu_id = NULL
			END

		INSERT INTO tbProduction_StandardFormula_header
		(
			comp_id,
			item_id,
			prsfc_id,
			prsf_standardQTY,
			mu_id,
			user_id_creator,
			prsf_cd,
			brag_id,
			stor_id4Production,
			stor_id4RawMaterial
		)
		VALUES
		(
			@comp_id,
			@item_id,
			@prsfc_id,
			@prsf_standardQTY,
			@mu_id,
			@user_id_creator,
			GETDATE(),
			@brag_id,
			@stor_id4Production,
			@stor_id4RawMaterial
		)

		SET @return_value = @@IDENTITY

	END
GO

