CREATE PROCEDURE spProduction_StantardFormula_Detail_GetData4Header
(
	@comp_id	INT,
	@prsf_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@prsf_id	INT
			SELECT
				@comp_id	= 1,
				@prsf_id	= 1
		*/
		-- ------------------------------------

		SELECT
			' '											[ ],		--1 Ver Stock
			' '											[ ],		--2 Modificar
			' '											[ ],		--3 Eliminar
			' '											[ ],		--4 Otros 1
			' '											[ ],		--5 Otros 2
			' '											[ ],		--6 Otros 3
			' '											[ ],		--7	Ver FC

			ti.item_code,
			ti.item_desc,
			tmu.mu_desc,
			tpsfd.prsfd_QTY,
			tpct.spft_desc,
			tpsfd.prsfd_note,
			tpsfd.prsfd_additionalPercentFromCost,
			tpsfd.prsfd_additionalPrice,
			tc.curr_symbol,
			tpsfd.prsfd_id								[ID]
