			INNER JOIN tbMetricUnits					tmu
			ON	tmu.comp_id		= tpsfd.comp_id			AND
				tmu.mu_id		= tpsfd.mu_id
			INNER JOIN tbsysProduction_componentType	tpct
			ON	tpct.spft_id	= tpsfd.spft_id
