CREATE PROCEDURE [dbo].[spProfile_validateData]
(
	@comp_id			int,
	@lang_id			int,
	@errormessage		varchar(200) output
)
as
set nocount on

/*
DECLARE @comp_id INT, @lang_id INT, @errormessage		varchar(200)
SELECT @comp_id = 2, @lang_id = 2
drop table [#tmp]
*/


declare @return_value int
set @return_value = 0
set @errormessage = ''




--crear tabla temporal para descripciones de posibles errores
CREATE TABLE #tmp (	[field_id]				[int]			null,
					[type_id]				[int]			null,
					[type_desc]				[varchar](200)	null,
					[name_desc]				[varchar](200)	null,
					[name_join]				[varchar](200)	null,
					[name_combo]			[varchar](200)	null,
					[name_column]			[varchar](200)	null,
					[name_comboact]			[varchar](200)	null,
					[name_errormessage]		[varchar](200)	null,
					[name_errormessage2]	[varchar](200)	null,
					[ctrl_id]				[int]			null,
					[ctrl_desc]				[varchar](200)	null,
					[prop_id]				[int]			null,
					[prop_desc]				[varchar](200)	null)



--recuperar las descripciones de los posibles errores que pudieran ocurrir en la validación
INSERT #tmp
(	[field_id],[type_id],[type_desc],[name_desc],
	[name_join],[name_combo],[name_column],[name_comboact],[name_errormessage], [name_errormessage2],
	[ctrl_id],[ctrl_desc],[prop_id],[prop_desc])
		exec dbo.spSysNames_getDataByTab @lang_id, 70, 121 ,-1




if (SELECT COUNT(*)	FROM tbprofile WHERE comp_id = @comp_id AND prof_isSA = 'True') = 1
	begin
		set	@errormessage = (select [name_errormessage] from #tmp where ctrl_id = 287)
		set @return_value = 287
	end



--SELECT @return_value, @errormessage
return @return_value
GO









CREATE  PROCEDURE [dbo].[spProfileAuthorization_checkExistsData]
(
	@comp_id		int,
	@prof_id		int,
	@user_id		INT,
	@return_value   bit output
)
AS

BEGIN



	set nocount on

	/*
	declare		@comp_id		int,
				@prof_id		int
	select		@comp_id		= 20,
				@prof_id		= 1
	*/

	if exists	(
					SELECT TOP 1 1
						from	dbo.tbProfileAuthorization		pa		WITH (NOLOCK)
						where	pa.comp_id = @comp_id
						and		pa.prof_id = @prof_id)
			set @return_value = 1
	else
			set @return_value = 0


	IF EXISTS(
					SELECT TOP 1 1
						FROM tbWorkflow tw							WITH (NOLOCK)
						WHERE tw.comp_id = @comp_id AND
								(
									tw.prof_id_assigned = @prof_id
										OR
									tw.user_id_assigned = @user_id
								)
				)
		BEGIN
			set @return_value = 1
		END


END








GO






