create PROCEDURE [dbo].[spProfileAuthorization_insertData]

(
	@comp_id				int,
	@prof_id				int,
	@aut_id					int,
	@user_id				int
)
as

insert into	dbo.tbProfileAuthorization
(
	comp_id,
	prof_id,
	aut_id,
	proaut_cd,
	proaut_user_id_creator
)

values
(
	@comp_id,
	@prof_id,
	@aut_id,
	getdate(),
	@user_id
)

GO






CREATE PROCEDURE [dbo].[spProfileAuthorizations_getProfiles]
(
	@comp_id			int,
	@lang_id			int,
	@prof_id			int
)
as

set nocount on
/*
declare 	@comp_id			int,
			@lang_id			int,
			@prof_id			int,
			@aut_id				int

select		@comp_id			= 1,
			@lang_id			= 2,
			@prof_id			= 1,
			@aut_id				= 66
*/

select	Pa.aut_id			[id],
		REPLACE (REPLACE(A.optval_desc,'<B>',''), '</B>', '') [desc]
