CREATE PROCEDURE [dbo].[spProject_getDataByText]
(
	@text	VARCHAR(300),
	@count		INT,
	@lang_id	INT	,
	@comp_id AS INT,
	@bra_id  AS INT
)
AS



BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*

		DECLARE
			@text		VARCHAR(300),
			@count		INT,
			@lang_id	INT,
			@comp_id AS INT,
			@bra_id  AS INT

		SELECT
			@text		='A',
			@count		= 2,
			@lang_id	= 2,
			@comp_id	= 1,
			@bra_id		= 1
	*/
	-- ----------------------------------------------------------------





	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')



	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)
	DECLARE @text6	varchar(300)
	DECLARE @text7	varchar(300)
	DECLARE @text8	varchar(300)
	DECLARE @text9	varchar(300)
	DECLARE @text10	varchar(300)

	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0 else
			IF @text2 IS NULL SET @text2 = @text0 else
			IF @text3 IS NULL SET @text3 = @text0 else
			IF @text4 IS NULL SET @text4 = @text0 else
			IF @text5 IS NULL SET @text5 = @text0 else
			IF @text6 IS NULL SET @text6 = @text0 else
			IF @text7 IS NULL SET @text7 = @text0 else
			IF @text8 IS NULL SET @text8 = @text0 else
			IF @text9 IS NULL SET @text9 = @text0 else
			IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------





	SELECT		TOP (@count)

				Upper(dbo.PadRightString( IsNull(tc.pro_desc,''),'.',50)) + ' | ' + isnull(convert(VARCHAR(10),tc.pro_id),'')	[pro_desc],
				tc.pro_id
	FROM tbProject tc
			WHERE		tc.comp_id = @comp_id
					AND (tc.bra_id IS NULL OR tc.bra_id = @bra_id)
		AND
			(

						CASE
							WHEN @selection_method = 0 AND tc.pro_desc LIKE @text + '%'	 THEN	'True'
							WHEN @selection_method = 1 AND tc.pro_desc LIKE '%' + @text1 + '%'	 THEN	'True'
							WHEN @selection_method = 2 AND tc.pro_desc LIKE '%' + @text1 + '%' AND tc.pro_desc LIKE '%' + @text2 + '%'		 THEN	'True'
							WHEN @selection_method = 3 AND tc.pro_desc LIKE '%' + @text1 + '%' AND tc.pro_desc LIKE '%' + @text2 + '%' AND tc.pro_desc LIKE '%' + @text3 + '%'	 THEN	'True'
							WHEN @selection_method = 4 AND tc.pro_desc LIKE '%' + @text1 + '%' AND tc.pro_desc LIKE '%' + @text2 + '%' AND tc.pro_desc LIKE '%' + @text3 + '%' AND tc.pro_desc LIKE '%' + @text4 + '%'		 THEN	'True'
							WHEN @selection_method = 5 AND tc.pro_desc LIKE '%' + @text1 + '%' AND tc.pro_desc LIKE '%' + @text2 + '%' AND tc.pro_desc LIKE '%' + @text3 + '%' AND tc.pro_desc LIKE '%' + @text4 + '%' AND tc.pro_desc LIKE '%' + @text5 + '%'		 THEN	'True'
							WHEN @selection_method = 6 AND tc.pro_desc LIKE '%' + @text1 + '%' AND tc.pro_desc LIKE '%' + @text2 + '%' AND tc.pro_desc LIKE '%' + @text3 + '%' AND tc.pro_desc LIKE '%' + @text4 + '%' AND tc.pro_desc LIKE '%' + @text5 + '%' AND tc.pro_desc LIKE '%' + @text6 + '%'	 THEN	'True'
							WHEN @selection_method = 7 AND tc.pro_desc LIKE '%' + @text1 + '%' AND tc.pro_desc LIKE '%' + @text2 + '%' AND tc.pro_desc LIKE '%' + @text3 + '%' AND tc.pro_desc LIKE '%' + @text4 + '%' AND tc.pro_desc LIKE '%' + @text5 + '%' AND tc.pro_desc LIKE '%' + @text6 + '%' AND tc.pro_desc LIKE '%' + @text7 + '%'	 THEN	'True'
							WHEN @selection_method = 8 AND tc.pro_desc LIKE '%' + @text1 + '%' AND tc.pro_desc LIKE '%' + @text2 + '%' AND tc.pro_desc LIKE '%' + @text3 + '%' AND tc.pro_desc LIKE '%' + @text4 + '%' AND tc.pro_desc LIKE '%' + @text5 + '%' AND tc.pro_desc LIKE '%' + @text6 + '%' AND tc.pro_desc LIKE '%' + @text7 + '%' AND tc.pro_desc LIKE '%' + @text8 + '%'		 THEN	'True'
							WHEN @selection_method = 9 AND tc.pro_desc LIKE '%' + @text1 + '%' AND tc.pro_desc LIKE '%' + @text2 + '%' AND tc.pro_desc LIKE '%' + @text3 + '%' AND tc.pro_desc LIKE '%' + @text4 + '%' AND tc.pro_desc LIKE '%' + @text5 + '%' AND tc.pro_desc LIKE '%' + @text6 + '%' AND tc.pro_desc LIKE '%' + @text7 + '%' AND tc.pro_desc LIKE '%' + @text8 + '%' AND tc.pro_desc LIKE '%' + @text9 + '%'		 THEN	'True'
							WHEN @selection_method =10 AND tc.pro_desc LIKE '%' + @text1 + '%' AND tc.pro_desc LIKE '%' + @text2 + '%' AND tc.pro_desc LIKE '%' + @text3 + '%' AND tc.pro_desc LIKE '%' + @text4 + '%' AND tc.pro_desc LIKE '%' + @text5 + '%' AND tc.pro_desc LIKE '%' + @text6 + '%' AND tc.pro_desc LIKE '%' + @text7 + '%' AND tc.pro_desc LIKE '%' + @text8 + '%' AND tc.pro_desc LIKE '%' + @text9 + '%' AND tc.pro_desc LIKE '%' + @text10 + '%'		 THEN 'True'
							ELSE	'False'
						END	= 'True'

			)



			ORDER BY	tc.pro_desc

END
GO


CREATE PROCEDURE [dbo].[spProjectManagement_GetCollectionByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@pro_id		INT
)
AS

	BEGIN

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@pro_id		INT,
				@user_id	INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= -1,
				@pro_id		= 1,
				@user_id	= 119
		*/
		-- ------------------------------------------------

		-- ------------------------------------------------
		-- RECUPERO LA MONEDA DEL PROYECTO
		-- ------------------------------------------------

			DECLARE
				@pro_curr_id	INT
			SELECT
				@pro_curr_id = tp.curr_id
			FROM tbProject					tp
			WHERE	tp.comp_id	= @comp_id	AND
					tp.pro_id	= @pro_id

		-- ------------------------------------------------

		-- RECUPERO LA MONEDA DE LA SUCURSAL PARA EL CROSS APPLY
		-- Y LA FECHA DE PROCESO
		-- -----------------------------------------------------------
			DECLARE
				@bra_curr_id			INT,
				@bra_processing_date	DATETIME
			SELECT
				@bra_curr_id			= tb.curr_id,
				@bra_processing_date	= tb.bra_processingDate
				FROM tbBranch					tb
				WHERE	tb.comp_id	= @comp_id	AND
						tb.bra_id	= @bra_id
		-- -----------------------------------------------------------


		SELECT
			' '																				[ ],
			' '																				[ ],
			' '																				[ ],
			' '																				[ ],
			ct.cust_id,
			c.cust_name,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.ct_transaction) [Comprobante],
			ct_date,
			ct_payDate,
			isnull(sm.sm_name,'')					[sm_name],
			-- [MB , Parte 755 ];
			CASE ct.sd_id WHEN 66 THEN
 			ISNULL(ct.ct_total,0) * (-1)
			ELSE
			ISNULL(ct.ct_total,0)
			END						 [ct_total],
			--ct_total,
			(ct_Abalance * ct_AcurrencyExchange)	[Balance],
			 CASE ct.sd_id WHEN 66 THEN
 			ISNULL(ct.ct_Atotal,0) * (-1)
			ELSE
			ISNULL(ct.ct_Atotal,0)
			END										[ct_ATotal],
			 tc.curr_symbol							[curr_symbol],
			ct.ct_transaction						[ID]
			FROM	dbo.tbCommercialTransactions										ct					WITH (NOLOCK)
				INNER JOIN dbo.tbCustomer												c					WITH (NOLOCK)
					ON	ct.comp_id				= c.comp_id								AND
						ct.cust_id				= c.cust_id
				INNER JOIN tbsysCurrency												tc					WITH (NOLOCK)
					ON	tc.curr_id				= c.curr_id
				INNER JOIN 	dbo.tbDocumentsFile											df					WITH (NOLOCK)
					ON	ct.comp_id				= df.comp_id							AND
						ct.bra_id				= df.bra_id								AND
						ct.df_id				= df.df_id
				INNER JOIN dbo.tbSalesman												sm					WITH (NOLOCK)
					ON  sm.comp_id				= ct.comp_id							AND
						sm.sm_id				= c.sm_id
				--Agregado...Join a la vista de la tabla Commercial Transactions
				INNER  JOIN  dbo.vwCommercialTransactions_forSales						vwct				WITH (NOLOCK)
					ON  ct.comp_id				= vwct.comp_id							AND
						ct.bra_id				= vwct.bra_id							AND
						ct.ct_transaction		= vwct.ct_transaction					AND
						vwct.sd_isReceipt		= 'True'								AND
						vwct.sd_isInBalance		= 'True'
				INNER JOIN tbUsers4BranchFilter											vubf				WITH (NOLOCK)
					ON  vubf.comp_id			= CT.comp_id							AND
						vubf.bra_id			    = CT.bra_id								AND
						vubf.[user_id]			= @user_id
				LEFT JOIN tbCustomerDefaultLevel										tcdl
					ON	tcdl.comp_id			= ct.comp_id							AND
						tcdl.def_id				= ct.def_id

			WHERE	    ct.comp_id		=	@comp_id										AND
						(@bra_id		= -1 OR		ct.bra_id	=	@bra_id)				AND
						ct.pro_id		= @pro_id											AND
						ct.sd_id		IN (6,13)

		ORDER BY ct.ct_date, ct.sd_id ,dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, ct.ct_transaction)

		-- ---------------------------------------------------------------------------------------------------
		-- TOTALES CONVERTIDOS A LA MONEDA DEL PROYECTO
		-- ---------------------------------------------------------------------------------------------------
		SELECT
			SUM(dbo.fnGetExchange(ct.comp_id,ct.ct_ATotal, ct.ct_ACurrency, @pro_curr_id, 0, 0, 0))			[Project_Collection_Total]
			FROM	dbo.tbCommercialTransactions										ct					WITH (NOLOCK)
				INNER JOIN dbo.tbCustomer												c					WITH (NOLOCK)
					ON	ct.comp_id				= c.comp_id								AND
						ct.cust_id				= c.cust_id
				INNER JOIN tbsysCurrency												tc					WITH (NOLOCK)
					ON	tc.curr_id				= c.curr_id
				INNER JOIN 	dbo.tbDocumentsFile											df					WITH (NOLOCK)
					ON	ct.comp_id				= df.comp_id							AND
						ct.bra_id				= df.bra_id								AND
						ct.df_id				= df.df_id
				INNER JOIN dbo.tbSalesman												sm					WITH (NOLOCK)
					ON  sm.comp_id				= ct.comp_id							AND
						sm.sm_id				= c.sm_id
				--Agregado...Join a la vista de la tabla Commercial Transactions
				INNER  JOIN  dbo.vwCommercialTransactions_forSales						vwct				WITH (NOLOCK)
					ON  ct.comp_id				= vwct.comp_id							AND
						ct.bra_id				= vwct.bra_id							AND
						ct.ct_transaction		= vwct.ct_transaction					AND
						vwct.sd_isReceipt		= 'True'								AND
						vwct.sd_isInBalance		= 'True'
				INNER JOIN tbUsers4BranchFilter											vubf				WITH (NOLOCK)
					ON  vubf.comp_id			= CT.comp_id							AND
						vubf.bra_id			    = CT.bra_id								AND
						vubf.[user_id]			= @user_id
				LEFT JOIN tbCustomerDefaultLevel										tcdl
					ON	tcdl.comp_id			= ct.comp_id							AND
						tcdl.def_id				= ct.def_id

			WHERE	    ct.comp_id		=	@comp_id										AND
						(@bra_id		= -1 OR		ct.bra_id	=	@bra_id)				AND
						ct.pro_id		= @pro_id											AND
						ct.sd_id		IN (6,13)


	END
GO


CREATE PROCEDURE [dbo].[spProjectManagement_GetPaymentsByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@pro_id		INT
)
AS

	BEGIN

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------
		SET NOCOUNT ON

		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@user_id	INT,
				@prof_id	INT,
				@pro_id		INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= -1,
				@user_id	= 119,
				@prof_id	= 1,
				@pro_id		= 1
		*/
		-- ----------------------------------------------------

		-- ------------------------------------------------
		-- RECUPERO LA MONEDA DEL PROYECTO
		-- ------------------------------------------------

			DECLARE
				@pro_curr_id	INT
			SELECT
				@pro_curr_id = tp.curr_id
			FROM tbProject					tp
			WHERE	tp.comp_id	= @comp_id	AND
					tp.pro_id	= @pro_id

		-- ------------------------------------------------


		SELECT
			' '																				[ ],
			' '																				[ ],
			' '																				[ ],
			' '																				[ ],
			ts.supp_id																		[supp_id],
			ts.supp_name																	[supp_name],
			dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [Comprobante],
			tct.ct_date,
			vph.Date																		[ct_payDate],
			(vph.amount * vph.exchange) 													[ct_total],
			(tct.ct_Abalance * tct.ct_AcurrencyExchange)									[Balance],
			ISNULL(vph.[description],'') + ISNULL(vph.[type],'')							[description],
			tc.curr_desc,
			tc.curr_symbol,
			tb.bra_desc,
			isnull(tctop.op_paymentTo,ts.supp_name)											[op_paymentTo],
			tct.ct_total																	[Total],
			--tct.ct_taxDate																	[ct_taxDate],
			tct.ct_transaction																[ID]
			FROM	tbCommercialTransactions						tct
			INNER JOIN dbo.vwCommercialTransactions_forPurchase		vctfp
			ON  tct.comp_id				= vctfp.comp_id				AND
				tct.bra_id				= vctfp.bra_id				AND
				tct.ct_transaction		= vctfp.ct_transaction		AND
				vctfp.sd_isReceipt		= 'True'					AND
				vctfp.sd_isInBalance	= 'True'
			INNER JOIN tbSupplier									ts
			ON	ts.comp_id				= tct.comp_id				AND
				ts.supp_id				= tct.supp_id
			INNER JOIN dbo.vwPaymentsHow							vph
			ON	vph.comp_id				= tct.comp_id				AND
				vph.ct_transaction		= tct.ct_transaction		AND
				vph.lang_id				= @lang_id
			INNER JOIN tbsysCurrency								tc
			ON	tc.curr_id				= tct.curr_id_transaction
			INNER JOIN tbBranch										tb
			ON	tb.comp_id				= tct.comp_id				AND
				tb.bra_id				= tct.bra_id
			INNER JOIN tbUsers4BranchFilter							vubf
			ON  vubf.comp_id			= tct.comp_id				AND
				vubf.bra_id				= tct.bra_id				AND
				vubf.[user_id]			= @user_id
			LEFT JOIN tbCommercialTransactionsOtherPayments			tctop
			ON	tctop.comp_id			= tct.comp_id				AND
				tctop.bra_id			= tct.bra_id				AND
				tctop.ct_transaction	= tct.ct_transaction
			WHERE 	 tct.comp_id		= @comp_id					AND
					 (
						@bra_id			= -1 OR
						tct.bra_id		= @bra_id
					 )												AND
					 tct.pro_id			= @pro_id					AND
					 tct.sd_id			= 106
			--@OptionSupp 1 - todos los proveedores
			--			  2 - proveedores
			--			  3 - otros pagos
			ORDER BY tct.ct_date, tct.ct_transaction

			-- ---------------------------------------------------------------------------------------------------
			-- TOTALES CONVERTIDOS A LA MONEDA DEL PROYECTO
			-- ---------------------------------------------------------------------------------------------------

			SELECT
				SUM(dbo.fnGetExchange(tct.comp_id,(vph.amount * vph.exchange),vph.curr_id, @pro_curr_id, 0, 0, 0))			[Project_Payments_Total]
				FROM	tbCommercialTransactions						tct
				INNER JOIN dbo.vwCommercialTransactions_forPurchase		vctfp
				ON  tct.comp_id				= vctfp.comp_id				AND
					tct.bra_id				= vctfp.bra_id				AND
					tct.ct_transaction		= vctfp.ct_transaction		AND
					vctfp.sd_isReceipt		= 'True'					AND
					vctfp.sd_isInBalance	= 'True'
				INNER JOIN tbSupplier									ts
				ON	ts.comp_id				= tct.comp_id				AND
					ts.supp_id				= tct.supp_id
				INNER JOIN dbo.vwPaymentsHow							vph
				ON	vph.comp_id				= tct.comp_id				AND
					vph.ct_transaction		= tct.ct_transaction		AND
					vph.lang_id				= @lang_id
				INNER JOIN tbsysCurrency								tc
				ON	tc.curr_id				= tct.curr_id_transaction
				INNER JOIN tbBranch										tb
				ON	tb.comp_id				= tct.comp_id				AND
					tb.bra_id				= tct.bra_id
				INNER JOIN tbUsers4BranchFilter							vubf
				ON  vubf.comp_id			= tct.comp_id				AND
					vubf.bra_id				= tct.bra_id				AND
					vubf.[user_id]			= @user_id
				LEFT JOIN tbCommercialTransactionsOtherPayments			tctop
				ON	tctop.comp_id			= tct.comp_id				AND
					tctop.bra_id			= tct.bra_id				AND
					tctop.ct_transaction	= tct.ct_transaction
				WHERE 	 tct.comp_id		= @comp_id					AND
						 (
							@bra_id			= -1 OR
							tct.bra_id		= @bra_id
						 )												AND
						 tct.pro_id			= @pro_id					AND
						 tct.sd_id			= 106
				--@OptionSupp 1 - todos los proveedores
				--			  2 - proveedores
				--			  3 - otros pagos




	END
GO


CREATE PROCEDURE [dbo].[spProjectManagement_GetPurchaseDocsByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@pro_id		INT
)
AS

	BEGIN
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@user_id	INT,
				@prof_id	INT,
				@pro_id		INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@user_id	= 119,
				@prof_id	= 1,
				@pro_id		= 1
		*/
		-- ----------------------------------------------------

		-- ------------------------------------------------
		-- RECUPERO LA MONEDA DEL PROYECTO
		-- ------------------------------------------------

			DECLARE
				@pro_curr_id	INT
			SELECT
				@pro_curr_id = tp.curr_id
			FROM tbProject					tp
			WHERE	tp.comp_id	= @comp_id	AND
					tp.pro_id	= @pro_id

		-- ------------------------------------------------



		SELECT
			' '																						[ ],
			' '																						[ ],
			' '																						[ ],
			' '																						[ ],
			ts.supp_id,
			ts.supp_name,
			dbo.fnGetCommercialTransactionDescription(tct.comp_id, @lang_id, tct.ct_transaction)	[Document],
			tct.ct_date,
			tct.ct_payDate,
			tc.curr_symbol,
			tct.ct_ATotal,
			tct.ct_transaction																		[ID]
		FROM tbCommercialTransactions						tct
			INNER JOIN vwCommercialTransactions_forPurchase vctfp
			ON	vctfp.comp_id = tct.comp_id					AND
				vctfp.ct_transaction = tct.ct_transaction
			INNER JOIN tbUsers4BranchFilter					tubf
			ON	tubf.comp_id	= tct.comp_id				AND
				tubf.bra_id		= tct.bra_id				AND
				tubf.[user_id]	= @user_id
			INNER JOIN tbSupplier							ts
			ON	ts.comp_id		= tct.comp_id				AND
				ts.supp_id		= tct.supp_id
			INNER JOIN tbsysCurrency						tc
			ON	tc.curr_id		= tct.ct_ACurrency
		WHERE	tct.comp_id		= @comp_id		AND
				tct.pro_id		= @pro_id		AND
				tct.supp_id		IS NOT NULL		AND
				tct.sd_id		<> 106

		-- ---------------------------------------------------------------------------------------------------
		-- TOTALES CONVERTIDOS A LA MONEDA DEL PROYECTO
		-- ---------------------------------------------------------------------------------------------------
		SELECT
			SUM(dbo.fnGetExchange(tct.comp_id,tct.ct_ATotal, tct.ct_ACurrency, @pro_curr_id, 0, 0, 0))			[Project_PurchaseDocs_Total]
			FROM tbCommercialTransactions						tct
				INNER JOIN vwCommercialTransactions_forPurchase vctfp
				ON	vctfp.comp_id = tct.comp_id					AND
					vctfp.ct_transaction = tct.ct_transaction
				INNER JOIN tbUsers4BranchFilter					tubf
				ON	tubf.comp_id	= tct.comp_id				AND
					tubf.bra_id		= tct.bra_id				AND
					tubf.[user_id]	= @user_id
				INNER JOIN tbSupplier							ts
				ON	ts.comp_id		= tct.comp_id				AND
					ts.supp_id		= tct.supp_id
				INNER JOIN tbsysCurrency						tc
				ON	tc.curr_id		= tct.ct_ACurrency
			WHERE	tct.comp_id		= @comp_id		AND
					tct.pro_id		= @pro_id		AND
					tct.supp_id		IS NOT NULL		AND
					tct.sd_id		<> 106

	END
GO


CREATE PROCEDURE [dbo].[spProjectManagement_GetPurchaseOrderByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@pro_id		INT
)
AS

	BEGIN
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@user_id	INT,
				@prof_id	INT,
				@pro_id		INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@user_id	= 119,
				@prof_id	= 1,
				@pro_id		= 1
		*/
		-- ----------------------------------------------------

		-- ------------------------------------------------
		-- RECUPERO LA MONEDA DEL PROYECTO
		-- ------------------------------------------------

			DECLARE
				@pro_curr_id	INT
			SELECT
				@pro_curr_id = tp.curr_id
			FROM tbProject					tp
			WHERE	tp.comp_id	= @comp_id	AND
					tp.pro_id	= @pro_id

		-- ------------------------------------------------

		DECLARE
			@bra_curr_id	INT
		SELECT
			@bra_curr_id		= curr_id
			From tbBranch					tb
			Where	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id



		SELECT
			' '																					[ ],
			' '																					[ ],
			' '																					[ ],
			' '																					[ ],
			tov.optval_desc,
			ISNULL(ts.supp_name,'')   [supp_name],
			tpoh.poh_cd,
			tpoh.poh_estDeliveryDate,
			tpoh.poh_deliveryDate,
			ISNULL(tpoh.poh_observation1,'') [poh_observation1],
			ISNULL(tpoh.poh_observation2,'') [poh_observation2],
			ISNULL(tpoh.poh_observation3,'') [poh_observation3],
			ISNULL(tpoh.poh_observation4,'') [poh_observation4],
			tpt.pt_desc,
			ISNULL(tpt2.ptr_name,'')		[ptr_name],
			tc2.curr_desc,
			tc2.curr_symbol,
			CONVERT(VARCHAR,tpoh.comp_id)	+ '-' +
			CONVERT(VARCHAR,tpoh.bra_id)	+ '-' +
			CONVERT(VARCHAR,tpoh.poh_id)	[ID]


			FROM tbPurchaseOrderHeader						tpoh
				INNER JOIN tbSupplier						ts
					ON  ts.comp_id			= tpoh.comp_id	AND
						ts.supp_id			= tpoh.supp_id
				INNER JOIN tbsysCurrency					tc2
					ON	tc2.curr_id			= tpoh.poh_ACurrency
				LEFT JOIN tbPurchaseTerms					tpt
					ON  tpt.comp_id			= tpoh.comp_id	AND
						tpt.pt_id			= tpoh.pt_id
				INNER JOIN tbsysOptionsValues				tov
					ON	tov.lang_id			= @lang_id		AND
						tov.optval_class	= 27			AND
						tov.optval_id		= tpoh.poh_quotation
				LEFT JOIN tbPurchaseTransport				tpt2
					ON	tpt2.comp_id		= tpoh.comp_id	AND
						tpt2.ptr_id			= tpoh.ptr_id
				INNER JOIN tbUsers4BranchFilter				tubf
					ON	tubf.comp_id		= tpoh.comp_id	AND
						tubf.bra_id			= tpoh.bra_id	AND
						tubf.[user_id]		= @user_id
			WHERE	tpoh.comp_id	= @comp_id		AND
				(	@bra_id			= -1		OR
					tpoh.bra_id		= @bra_id
				)									AND
					tpoh.pro_id		= @pro_id


			-- ---------------------------------------------------------------------------------------------------
			-- TOTALES CONVERTIDOS A LA MONEDA DEL PROYECTO
			-- ---------------------------------------------------------------------------------------------------
			SELECT
				SUM(dbo.fnGetExchange(tpoh.comp_id,(tpod.pod_price * tpod.pod_qty), tpod.curr_id, @pro_curr_id, 0, 0, 0))			[Project_PurchaseOrder_Total]
				FROM tbPurchaseOrderHeader						tpoh
					INNER JOIN tbPurchaseOrderDetail			tpod
						ON	tpod.comp_id		= tpoh.comp_id	AND
							tpod.bra_id			= tpoh.bra_id	AND
							tpod.poh_id			= tpoh.poh_id
					INNER JOIN tbSupplier						ts
						ON  ts.comp_id			= tpoh.comp_id	AND
							ts.supp_id			= tpoh.supp_id
					INNER JOIN tbsysCurrency					tc2
						ON	tc2.curr_id			= tpoh.poh_ACurrency
					LEFT JOIN tbPurchaseTerms					tpt
						ON  tpt.comp_id			= tpoh.comp_id	AND
							tpt.pt_id			= tpoh.pt_id
					INNER JOIN tbsysOptionsValues				tov
						ON	tov.lang_id			= @lang_id		AND
							tov.optval_class	= 27			AND
							tov.optval_id		= tpoh.poh_quotation
					LEFT JOIN tbPurchaseTransport				tpt2
						ON	tpt2.comp_id		= tpoh.comp_id	AND
							tpt2.ptr_id			= tpoh.ptr_id
					INNER JOIN tbUsers4BranchFilter				tubf
						ON	tubf.comp_id		= tpoh.comp_id	AND
							tubf.bra_id			= tpoh.bra_id	AND
							tubf.[user_id]		= @user_id
				WHERE	tpoh.comp_id	= @comp_id		AND
					(	@bra_id			= -1		OR
						tpoh.bra_id		= @bra_id
					)									AND
						tpoh.pro_id		= @pro_id


	END
GO

CREATE PROCEDURE [dbo].[spProjectManagement_GetSaleOrderByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@pro_id		INT
)
AS
	BEGIN

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@pro_id		INT,
				@user_id	INT,
				@prof_id	INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@pro_id		= 1,
				@user_id	= 119,
				@prof_id	= 1
		*/
		-- ------------------------------------------------

		-- ------------------------------------------------
		-- RECUPERO LA MONEDA DEL PROYECTO
		-- ------------------------------------------------

			DECLARE
				@pro_curr_id	INT
			SELECT
				@pro_curr_id = tp.curr_id
			FROM tbProject					tp
			WHERE	tp.comp_id	= @comp_id	AND
					tp.pro_id	= @pro_id

		-- ------------------------------------------------


		SELECT
			' '																	[ ],
			' '																	[ ],
			' '																	[ ],
			' '																	[ ],
			tc.cust_id,
			tc.cust_name,
			tdf.df_desc,
			dbo.fnGetSaleOrderNumber(tsoh.comp_id, tsoh.bra_id, tsoh.soh_id)	[soh_id],
			tsoh.soh_cd,
			tc2.curr_symbol,
			tsoh.soh_total,
			CONVERT(VARCHAR, tsoh.bra_id)	+ '-' +
			CONVERT(VARCHAR, tsoh.soh_id)										[ID]
			FROM tbSaleOrderHeader					tsoh
				INNER JOIN tbUsers4BranchFilter		tubf
				ON	tubf.comp_id	= tsoh.comp_id	AND
					tubf.bra_id		= tsoh.bra_id	AND
					tubf.[user_id]	= @user_id
				INNER JOIN tbDocumentsFile			tdf
				ON	tdf.comp_id		= tsoh.comp_id	AND
					tdf.df_id		= tsoh.df_id
				INNER JOIN tbCustomer				tc
				ON	tc.comp_id		= tsoh.comp_id	AND
					tc.cust_id		= tsoh.cust_id
				INNER JOIN tbsysCurrency			tc2
				ON	tc2.curr_id		= tsoh.curr_id4Exchange
			WHERE	tsoh.comp_id	= @comp_id						AND
					(@bra_id		= -1 OR tsoh.bra_id = @bra_id)	AND
					tsoh.pro_id		= @pro_id


			-- ---------------------------------------------------------------------------------------------------
			-- TOTALES CONVERTIDOS A LA MONEDA DEL PROYECTO
			-- ---------------------------------------------------------------------------------------------------
			SELECT
				SUM(dbo.fnGetExchange(tsoh.comp_id,tsoh.soh_total , tsoh.curr_id4Exchange, @pro_curr_id, 0, 0, 0))	[Project_SaleOrder_Total]
				FROM tbSaleOrderHeader					tsoh
					INNER JOIN tbUsers4BranchFilter		tubf
					ON	tubf.comp_id	= tsoh.comp_id	AND
						tubf.bra_id		= tsoh.bra_id	AND
						tubf.[user_id]	= @user_id
					INNER JOIN tbDocumentsFile			tdf
					ON	tdf.comp_id		= tsoh.comp_id	AND
						tdf.df_id		= tsoh.df_id
					INNER JOIN tbCustomer				tc
					ON	tc.comp_id		= tsoh.comp_id	AND
						tc.cust_id		= tsoh.cust_id
					INNER JOIN tbsysCurrency			tc2
					ON	tc2.curr_id		= tsoh.curr_id4Exchange
				WHERE	tsoh.comp_id	= @comp_id						AND
						(@bra_id		= -1 OR tsoh.bra_id = @bra_id)	AND
						tsoh.pro_id		= @pro_id

	END
GO


CREATE PROCEDURE [dbo].[spProjectManagement_GetSalesByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@pro_id		INT
)
AS

	BEGIN

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@pro_id		INT,
				@user_id	INT,
				@prof_id	INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@pro_id		= 1,
				@user_id	= 119,
				@prof_id	= 1
		*/
		-- ------------------------------------------------

		-- ------------------------------------------------
		-- RECUPERO LA MONEDA DEL PROYECTO
		-- ------------------------------------------------

			DECLARE
				@pro_curr_id	INT
			SELECT
				@pro_curr_id = tp.curr_id
			FROM tbProject					tp
			WHERE	tp.comp_id	= @comp_id	AND
					tp.pro_id	= @pro_id

		-- ------------------------------------------------


		DECLARE @bitWithProfit AS BIT
			Set @bitWithProfit = 'False'
			IF  EXISTS(
						SELECT 1
							FROM tbControlProfiles tcp1				WITH (NOLOCK)
               				WHERE	tcp1.ctrl_id = 1749
               					AND tcp1.comp_id = @comp_id
               					AND tcp1.bra_id  = @bra_id
               					AND tcp1.prof_id = @prof_id
						)
			BEGIN
				Set @bitWithProfit = 'True'
			END


			DECLARE @fun_id INT
			SET @fun_id = 1





			SELECT
				' '																	[ ],
				' '																	[ ],
				' '																	[ ],
				' '																	[ ],
				ct.cust_id,
				c.cust_name,
				ov.optval_desc + ' ' +
				ISNULL(ct.ct_kindOf,'*') + ' ' +
				dbo.PadString(ISNULL(ct.ct_pointOfSale,''),'0',4) + '-' +
				dbo.PadString(ISNULL(ct.ct_docNumber,''),'0',8)						[Comprobante],
				ct_date,
				ct_payDate,
				sm.sm_name,
				tc.curr_symbol,
				ISNULL(tst.st_desc,'')												[st_desc],
				CASE	WHEN vwct.sd_isCredit  = 'false' THEN	ct.ct_total
				ELSE											ct.ct_total	* -1
				END																	[ct_total],
				(CASE WHEN vwct.sd_isCredit = 'false' THEN	ct.ct_Abalance
				ELSE										ct.ct_Abalance  * -1
				END * ct_AcurrencyExchange)											[Balance],
				CONVERT(VARCHAR,ct.ct_transaction) + '-' +
				CONVERT(VARCHAR,ct.sd_id)											[ID]
				FROM	dbo.tbCommercialTransactions								ct
				INNER JOIN tbUsers4BranchFilter										vubf
				ON  vubf.comp_id				= ct.comp_id						AND
					vubf.bra_id					= ct.bra_id							AND
					vubf.[user_id]				= @user_id
				--Agregado...Join a la vista de la tabla Commercial Transactions
				INNER JOIN dbo.vwCommercialTransactions_forSales					vwct
				ON  ct.comp_id					= vwct.comp_id						AND
					ct.bra_id					= vwct.bra_id 						AND
					ct.ct_transaction			= vwct.ct_transaction
				INNER JOIN vwCommercialTransactionsProfitAndMarckup					vctpam
				ON	vctpam.comp_id				= ct.comp_id						AND
					vctpam.bra_id				= ct.bra_id							AND
					vctpam.ct_transaction		= ct.ct_transaction
				INNER JOIN tbDocumentsFile											tdf
				ON	tdf.comp_id					= ct.comp_id						AND
					tdf.bra_id					= ct.bra_id							AND
					tdf.df_id					= ct.df_id
				INNER JOIN dbo.tbCustomer											c
				ON	ct.comp_id					= c.comp_id							AND
					ct.cust_id					= c.cust_id
				INNER JOIN dbo.tbsysOptionsValues									ov
				ON	ov.lang_id					= @lang_id							AND
					ov.optval_id				= ct.sd_id							AND
					ov.optval_class				= 6
				INNER JOIN dbo.tbSalesman											sm
				ON  sm.comp_id					= ct.comp_id						AND
					sm.sm_id					= ct.sm_id
				INNER JOIN tbCustomerKind											ck
				ON  ck.comp_id					= c.comp_id							AND
					ck.ck_id					= c.ck_id
				LEFT JOIN tbSalesTerms												tst
				ON  tst.comp_id					= ct.comp_id						AND
					tst.st_id					= ct.st_id
				LEFT JOIN tbActivity												ta
				ON  ta.comp_id					= c.comp_id							AND
					ta.act_id					= c.act_id
				INNER JOIN tbsysCurrency											tc
				ON	tc.curr_id					= ct.curr_id_transaction
				WHERE	ct.comp_id					= @comp_id						AND
						vwct.sd_isReceipt			= 'False'						AND
						vwct.sd_isInBalance			= 'True'						AND
						(
							@bra_id					=	-1 OR
							ct.bra_id				= @bra_id
						)															AND
						(
							@pro_id					= -1 OR
							ct.pro_id				= @pro_id
		 				)															AND
						(
							ct.sd_id				= 1 OR
							ct.sd_id				= 3 OR
							ct.sd_id				= 4
						)															AND
						ct.pro_id					= @pro_id

				ORDER BY ct.ct_date, Comprobante
				OPTION ( MAXDOP 1 )

				-- ---------------------------------------------------------------------------------------------------
				-- TOTALES CONVERTIDOS A LA MONEDA DEL PROYECTO
				-- ---------------------------------------------------------------------------------------------------
				SELECT
					SUM(dbo.fnGetExchange(ct.comp_id,ct.ct_ATotal, ct.ct_ACurrency, @pro_curr_id, 0, 0, 0))			[Project_Sales_Total]
					FROM	dbo.tbCommercialTransactions								ct
					INNER JOIN tbUsers4BranchFilter										vubf
					ON  vubf.comp_id				= ct.comp_id						AND
						vubf.bra_id					= ct.bra_id							AND
						vubf.[user_id]				= @user_id
					--Agregado...Join a la vista de la tabla Commercial Transactions
					INNER JOIN dbo.vwCommercialTransactions_forSales					vwct
					ON  ct.comp_id					= vwct.comp_id						AND
						ct.bra_id					= vwct.bra_id 						AND
						ct.ct_transaction			= vwct.ct_transaction
					INNER JOIN vwCommercialTransactionsProfitAndMarckup					vctpam
					ON	vctpam.comp_id				= ct.comp_id						AND
						vctpam.bra_id				= ct.bra_id							AND
						vctpam.ct_transaction		= ct.ct_transaction
					INNER JOIN tbDocumentsFile											tdf
					ON	tdf.comp_id					= ct.comp_id						AND
						tdf.bra_id					= ct.bra_id							AND
						tdf.df_id					= ct.df_id
					INNER JOIN dbo.tbCustomer											c
					ON	ct.comp_id					= c.comp_id							AND
						ct.cust_id					= c.cust_id
					INNER JOIN dbo.tbsysOptionsValues									ov
					ON	ov.lang_id					= @lang_id							AND
						ov.optval_id				= ct.sd_id							AND
						ov.optval_class				= 6
					INNER JOIN dbo.tbSalesman											sm
					ON  sm.comp_id					= ct.comp_id						AND
						sm.sm_id					= ct.sm_id
					INNER JOIN tbCustomerKind											ck
					ON  ck.comp_id					= c.comp_id							AND
						ck.ck_id					= c.ck_id
					LEFT JOIN tbSalesTerms												tst
					ON  tst.comp_id					= ct.comp_id						AND
						tst.st_id					= ct.st_id
					LEFT JOIN tbActivity												ta
					ON  ta.comp_id					= c.comp_id							AND
						ta.act_id					= c.act_id
					INNER JOIN tbsysCurrency											tc
					ON	tc.curr_id					= ct.curr_id_transaction
					WHERE	ct.comp_id					= @comp_id						AND
							vwct.sd_isReceipt			= 'False'						AND
							vwct.sd_isInBalance			= 'True'						AND
							(
								@bra_id					=	-1 OR
								ct.bra_id				= @bra_id
							)															AND
							(
								@pro_id					= -1 OR
								ct.pro_id				= @pro_id
		 					)															AND
							(
								ct.sd_id				= 1 OR
								ct.sd_id				= 3 OR
								ct.sd_id				= 4
							)															AND
							ct.pro_id					= @pro_id
					OPTION ( MAXDOP 1 )



	END
GO





