CREATE PROCEDURE [dbo].[spPrueba_getReport]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int
)
as

/*
declare	@comp_id			int,
		@lang_id			int,
		@page_id			int
select 	@comp_id			=1,
		@lang_id			=2,
		@page_id			=998
*/

/************************************************************************************************/
/*Query que recupera los valores que debe mostrar el reporte, esto es diferente de cada reporte*/
select		a.[acc_count_id],
			a.[acc_code],
			a.[acc_desc]
from		[tbAccountant]	a
where		a.comp_id =	@comp_id
order by a.acc_desc
/*************************************************************************************************/





/************************************************************************************************/
/*Query que recupera los valores de títulos y todo aquello necesario que sea un valor único, y debe
estar cargado de misma manera que para los textos a mostrar en las páginas, este query no debe modificarse*/
declare @ctrl_desc	varchar(100),
		@text_desc	varchar(100),
		@fun_id		varchar(2),
		@select		varchar(8000)

set @select = 'select '

declare cursor_P_gR_values cursor for
select	c.[ctrl_desc], t.[text_desc]
from	[tbsysTexts]				t
		inner join [tbsysControls]	c
		on c.[ctrl_id] = t.[ctrl_id]
where	t.[lang_id]	= @lang_id
and		t.[page_id]	= @page_id
and		t.[type_id]	= 31
order by t.[ctrl_id]

open cursor_P_gR_values

fetch cursor_P_gR_values
into	@ctrl_desc, @text_desc

while @@FETCH_STATUS = 0
BEGIN

	set @select = @select + '''' + @text_desc + '''' + ' [' + @ctrl_desc + '], '

	fetch cursor_P_gR_values
	into	@ctrl_desc, @text_desc

END

close cursor_P_gR_values
deallocate cursor_P_gR_values

set @select = substring(@select,1,len(@select)-1)
exec (@select)
/************************************************************************************************/




/************************************************************************************************/
/*Query que recupera los valores de títulos de cada columna del reporte, y debe
estar cargado de misma manera que para los textos a mostrar en las páginas, este query no debe modificarse*/
set @select = 'select '

declare cursor_P_gR_values cursor for
select	c.[ctrl_desc], t.[text_desc], t.[fun_id]
from	[tbsysTexts]				t
		inner join [tbsysControls]	c
		on c.[ctrl_id] = t.[ctrl_id]
where	t.[lang_id]	= @lang_id
and		t.[page_id]	= @page_id
and		t.[type_id]	= 32
order by t.[fun_id]

open cursor_P_gR_values

fetch cursor_P_gR_values
into	@ctrl_desc, @text_desc, @fun_id

while @@FETCH_STATUS = 0
BEGIN

	set @select = @select + '''' + @text_desc + '''' + ' [' + @ctrl_desc + @fun_id + '], '

	fetch cursor_P_gR_values
	into	@ctrl_desc, @text_desc, @fun_id

END

close cursor_P_gR_values
deallocate cursor_P_gR_values

set @select = substring(@select,1,len(@select)-1)
exec (@select)
/************************************************************************************************/
GO






