CREATE PROCEDURE [dbo].[spPurchaseConcept_GetCombo]
(
		@comp_id		INT,
		@btt_id		AS	int
)
as
set nocount on
/*
declare @comp_id		int
select @comp_id		= 1
*/

SELECT
		puco_id		[Id],
		puco_desc	[Desc]

FROM	tbPurchaseConcept	WITH (NOLOCK)

WHERE	comp_id = @comp_id
	AND	((@btt_id  = -1 AND isnull(btt_id,-1) = -1 ) OR
		 (@btt_id  =  1 AND isnull(btt_id,-1) <> -1 )
	     )

Order By puco_desc
GO











CREATE  PROCEDURE [dbo].[spPurchaseConcept_getDataByCostCenter]
(
	@comp_id		INT,
	@puco_id		INT
)
AS

BEGIN

	set nocount on

	select	pc.acc_count_id,												-- MOS 01-2016, espero q no joda . . .
			isnull(a.acc_enable4CostCenter,'false')[acc_enable4CostCenter],
			a.acc_code,
			a.acc_desc

		from	dbo.tbPurchaseConcept pc			WITH (NOLOCK)

		left JOIN dbo.tbAccountant a				WITH (NOLOCK)
			ON	a.comp_id		= pc.comp_id
			AND a.acc_count_id	= pc.acc_count_id

		where	pc.comp_id	= @comp_id
		and		pc.puco_id	= @puco_id


END

GO


CREATE PROCEDURE [dbo].[spPurchaseConcept_GetDataById]
(
	@comp_id	INT,
	@puco_id	INT
)
AS

	BEGIN


		SET NOCOUNT ON


		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@puco_id	INT
			SELECT
				@comp_id	= 1,
				@puco_id	= 9
		*/
		-- -------------------------------------------



		SELECT
			tpc.comp_id,
			tpc.puco_id,
			tpc.puco_desc,
			tpc.puco_group,
			tpc.acc_count_id,
			tpc.puco_item_entrance,
			tpc.bra_id,
			tpc.btt_id,
			tpc.puco_is4Result,
			tpc.puco_TaxEngineColumn4Bancking,
			tpc.puco_importCost_isExentConcept,
			CASE
				WHEN ISNULL(ta.acc_enable4CostCenter,'False') = 'True' THEN ISNULL(tpc.puco_numberOfCostCenterByDefault,1)
				ELSE 1
			END		[puco_numberOfCostCenterByDefault],
			ISNULL(puco_calculateTaxesInBankingMovements,'False')			[puco_calculateTaxesInBankingMovements]

			FROM tbPurchaseConcept			tpc		WITH (NOLOCK)
			LEFT JOIN tbAccountant			ta		WITH (NOLOCK)
				ON	ta.comp_id		= tpc.comp_id AND
					ta.acc_count_id = tpc.acc_count_id
			WHERE	tpc.comp_id		= @comp_id	AND
					tpc.puco_id		= @puco_id

	END
GO





