CREATE  PROCEDURE [dbo].[spPurchaseConceptEdit_getData]
(
	@comp_id		INT,
	@lang_id	    INT,
	@bra_id			INT
)
AS
SET NOCOUNT ON


/*
DECLARE
			@comp_id	INT,
			@lang_id    INT,
			@bra_id		INT

SELECT
		 	@comp_id  = 1,
			@lang_id =  2,
		    @bra_id	 = -1
*/


SELECT	' ' [ ],
		tpc.puco_desc,
		tcc.cc_desc,
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction) [Comprobante],
		tpcm.pcm_note1,
		tpcm.pcm_note2,
		tpcm.pcm_id [ID]



FROM tbPurchaseConceptMovements tpcm


INNER JOIN tbCommercialTransactions tct
ON  tct.bra_id = tpcm.bra_id
AND tct.ct_transaction = tpcm.ct_transaction
AND tct.comp_id = tpcm.comp_id


INNER JOIN tbCostCenter tcc
ON  tcc.comp_id = tpcm.comp_id
AND tcc.cc_code = tpcm.cc_code


INNER JOIN tbPurchaseConcept tpc
ON	tpc.comp_id = tpcm.comp_id
AND tpc.puco_id = tpcm.puco_id


WHERE   tpcm.comp_id = @comp_id










GO





-- *** MARTIN BLOISE *** --
-- *** PARTE : 892 *** --



CREATE  PROCEDURE [dbo].[spPurchaseConceptEdit_getDataByFilters]
(
	@comp_id		INT,
	@lang_id	    INT,
	@bra_id			INT,
	@supp_id		INT
)

AS
SET NOCOUNT ON


/*
DECLARE
			@comp_id	INT,
			@lang_id    INT,
			@bra_id		INT,
			@supp_id	INT

SELECT
		 	@comp_id  = 1,
			@lang_id =  2,
		    @bra_id	 = -1,
		    @supp_id = -1
*/


SELECT	' ' [ ],
		tpc.puco_desc,
		tcc.cc_desc,
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction) [Comprobante],
		tpcm.pcm_note1,
		tpcm.pcm_note2,
		tpcm.pcm_id [ID]



FROM tbPurchaseConceptMovements tpcm


INNER JOIN tbCommercialTransactions tct
ON  tct.bra_id = tpcm.bra_id
AND tct.ct_transaction = tpcm.ct_transaction
AND tct.comp_id = tpcm.comp_id


INNER JOIN tbCostCenter tcc
ON  tcc.comp_id = tpcm.comp_id
AND tcc.cc_code = tpcm.cc_code


INNER JOIN tbPurchaseConcept tpc
ON	tpc.comp_id = tpcm.comp_id
AND tpc.puco_id = tpcm.puco_id


INNER JOIN tbSupplier ts
ON  ts.comp_id = tct.comp_id
AND ts.supp_id = tct.supp_id


WHERE   tpcm.comp_id = @comp_id
AND     (@supp_id  = -1  OR  ts.supp_id = @supp_id)










GO







-- *** MARTIN BLOISE *** --
-- *** PARTE : 892 *** --


CREATE PROCEDURE [dbo].[spPurchaseConceptMovements_getDataByID]
(

		@comp_id    INT,
		@lang_id	INT,
		@pcm_id		INT

)
as

set nocount on
/*

DECLARE
		@comp_id   INT,
		@lang_id   INT,
		@pcm_id AS INT

SELECT
		@comp_id = 1,
		@lang_id = 2,
		@pcm_id  = '402'


*/
select
		dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction) [Comprobante],
		puco.puco_desc,
		tcc.cc_desc,
		pcm.pcm_note1,
		pcm.pcm_note2,
		ts.supp_id,
		ts.supp_name,
		pcm.puco_id,
		pcm.cc_code,
		pcm.pcm_total,
		pcm.curr_id,
		pcm.tmp_pcmt_id,
		pcm.pcm_total_original,
		pcm.pcm_available4BankingTotals,
		tct.sd_id

from	dbo.tbPurchaseConceptMovements          pcm


		INNER JOIN tbCommercialTransactions tct
		ON  tct.bra_id = pcm.bra_id
		AND tct.ct_transaction = pcm.ct_transaction
		AND tct.comp_id = pcm.comp_id

		INNER JOIN	tbPurchaseConcept		puco
		on puco.comp_id		= pcm.comp_id
		and puco.puco_id	= pcm.puco_id

		left JOIN tbCostCenter				tcc
		ON  tcc.cc_code  = pcm.cc_code
		AND tcc.comp_id  = pcm.comp_id

		left JOIN tbSupplier ts
		ON  ts.comp_id = tct.comp_id
		AND ts.supp_id = tct.supp_id


	WHERE	pcm.pcm_id	=	@pcm_id












GO







create  PROCEDURE [dbo].[spPurchaseConceptMovements_insertData]
(
		@comp_id			int,
		@bra_id				int,
		@ct_transaction		int,
		@puco_id			int,
		@cc_code			int,
		@pcm_total			decimal(19,6),
		@curr_id			int,
		@pcm_note1			varchar(100),
		@pcm_note2			varchar(100),
		@return_value		int output
)
as
set nocount on

insert into dbo.tbPurchaseConceptMovements
(comp_id, bra_id, ct_transaction, puco_id,
	cc_code, pcm_total, curr_id, pcm_note1, pcm_note2)


values
(@comp_id, @bra_id, @ct_transaction, @puco_id,
	@cc_code, @pcm_total, @curr_id, @pcm_note1, @pcm_note2)

set	@return_value = @@identity
GO






-- Alter By MOS
--			06-2009


CREATE PROCEDURE [dbo].[spPurchaseConceptMovements_insertData_ForPurchase]
(
	@comp_id				int,
	@bra_id					int,
	@ct_transaction			int,
	@guid					uniqueidentifier,
	@currSupplier			int,
	@currBranch				int,
	@exchange				decimal(18,5),
	@return_value			as int			output,
	@ret_ErrorCode			as int			output,
	@ret_ErrorDescription	as varchar(200) OUTPUT
)
AS
set nocount on
Set @return_value			= 0
Set @ret_ErrorCode			= 0
Set @ret_ErrorDescription	= ''



BEGIN TRY

			-- --------------------------------------------
			-- Obtiene Descuentos Generales del Comprobante
			-- --------------------------------------------
			DECLARE @Discount1 AS DECIMAL(19,6)
			DECLARE @Discount2 AS DECIMAL(19,6)
			DECLARE @Discount3 AS DECIMAL(19,6)
			DECLARE @Discount4 AS DECIMAL(19,6)
			SELECT	@Discount1 = tct.ct_Discount1,
					@Discount2 = tct.ct_Discount2,
					@Discount3 = tct.ct_Discount3,
			        @Discount4 = tct.ct_Discount4
				FROM tbCommercialTransactions tct
				WHERE tct.comp_id = @comp_id AND tct.ct_transaction = @ct_transaction
			-- --------------------------------------------


	-- Moneda de la Sucursal.!!!!!
	SELECT @currBranch = curr_id
		FROM tbBranch tb				WITH (NOLOCK)
		WHERE	tb.comp_id = @comp_id
			AND tb.bra_id = @bra_id

		-- para bancos-----
		-- en caso de ser imputacion bancaria (entrada o salida ) y si no efectua asiento contable se pone en true Available4bankingTotals
		DECLARE @Available4bankingTotals AS BIT
		DECLARE @lbra_Banks_InputOutputCharges_DisableAccounting AS BIT
		DECLARE @lsd_id AS INT

		SET @Available4bankingTotals = 'False'

		--DOCUMENTO
		SELECT @lsd_id = tct.sd_id
				FROM tbCommercialTransactions						tct			WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id			AND
						tct.ct_transaction	= @ct_transaction

		--Asiento contable deshabilitado?
		SELECT @lbra_Banks_InputOutputCharges_DisableAccounting = tb.bra_Banks_InputOutputCharges_DisableAccounting
					FROM tbBranch tb				WITH (NOLOCK)
					WHERE	tb.comp_id	= @comp_id AND
							tb.bra_id	= @bra_id


		IF @lsd_id = 140 OR @lsd_id = 141
		BEGIN
			IF @lbra_Banks_InputOutputCharges_DisableAccounting = 'True'
				SET @Available4bankingTotals = 'True'
		END
		-------------




	insert into dbo.tbPurchaseConceptMovements
	   (comp_id,
	    bra_id,
	    ct_transaction,
	    puco_id,
		cc_code,
		pcm_total,
		curr_id,
		pcm_note1,
		pcm_note2,
		pcm_exchangeToBranchCurrency,
		tmp_pcmt_id,
		pcm_total_original,
		pcm_available4BankingTotals,
		pcm_id_original)

		SELECT
			@comp_id,
			@bra_id,
			@ct_transaction,
			puco_id,
			cc_code,
			pcmt_total * dbo.fnGetFinalDiscountCoeficient(@Discount1,@Discount2,@Discount3,@Discount4),
			curr_id,
			pcmt_note1,
			pcmt_note2,
			dbo.[fnGetExchange](@comp_id, 1, curr_id, @currBranch, @currSupplier, @exchange, 0),
			pcmt_id,
			pcmt_total,
			@Available4bankingTotals,
			pcm_id_original

			from dbo.tbPurchaseConceptMovementsTmp	WITH (NOLOCK)
			where	comp_id		= @comp_id
				and pcmt_guid	= @guid



		-- ----------------------------------------------------
		-- Verifica que no tenga un Doble Postback en el Alta.!
		-- ----------------------------------------------------
		IF NOT EXISTS(	SELECT 1
							FROM tbCommercialTransactions2Guid tctg
					  		WHERE tctg.guid = @guid)
			BEGIN
				INSERT INTO tbCommercialTransactions2Guid
				(
					comp_id,
					ct_transaction,
					guid
				)
				VALUES
				(
					@comp_id,
					@ct_transaction,
					@guid
				)
			END
		ELSE
			BEGIN
				Set @return_value			= -1
				Set @ret_ErrorCode			= -1
				Set @ret_ErrorDescription	= 'spPurchaseConceptMovements_insertData_ForPurchase -> Double PostBack'
			END
		-- ----------------------------------------------------



		-- ----------------------------------------------------
		-- Grarda plan de Pagos
		-- ----------------------------------------------
		UPDATE tbCommercialTransactionsPurchaseLoan
			SET ct_transaction	=  @ct_transaction,
				ctpl_guid		= NULL
				WHERE ctpl_guid = @guid
		-- ----------------------------------------------------




END TRY
BEGIN CATCH
		Set @return_value			= -1
		Set @ret_ErrorCode			= -1
		Set @ret_ErrorDescription	= 'spPurchaseConceptMovements_insertData_ForPurchase-' +
			(SELECT
			convert(varchar,ERROR_NUMBER())		+ '-' +
			convert(varchar,ERROR_SEVERITY())	+ '-' +
			convert(varchar,ERROR_STATE())		+ '-' +
			convert(varchar,ERROR_LINE())		+ '-' +
			ERROR_MESSAGE())
END CATCH
GO








