-- ------------------------------------------------------------------
-- Modificacion de datos cta cte de proveedores
-- Modificacion de concepto de compra
--
-- ------------------------------------------------------------------


CREATE  PROCEDURE [dbo].[spPurchaseConceptMovements_UpdateForCommTrans]
(
		@comp_id			int,
		@puco_id		    int,
        @pcm_id				INT,
        @cc_code			INT		-- centro de costos 29/12/22 tkt 16331

)

AS



	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
	/*
			DECLARE
					@comp_id			int,
					@puco_id		    int,
					@pcm_id				int
			SELECT
					@comp_id			= 1,
					@puco_id			= 1,
					@pcm_id				= 6662
	*/
	-- -----------------------------------------------------------------------

BEGIN
	SET NOCOUNT ON




		-- ------------------------------------------------------------------
		-- Intenta generar una reversion a la cuenta corecta del asiento contable
		-- que se hara SOLO si no se modifico la cta contable en la que imputa
		-- el impuesto original.
		-- ------------------------------------------------------------------

		DECLARE @dacc_transactionOriginal	AS INT
		SET		@dacc_transactionOriginal = NULL
		DECLARE @ct_transaction				AS INT
		DECLARE @decTotal					AS DECIMAL(30,6)
		DECLARE @acc_count_id				AS INT
		DECLARE @acc_count_id_original		AS INT
		DECLARE @puco_id_Original			AS INT
		DECLARE @bra_id						AS INT
		DECLARE @sd_id						AS INT





		SELECT
			@ct_transaction		= ttm.ct_transaction,
			@decTotal			= ttm.pcm_total,
			@puco_id_Original	= ttm.puco_id,
			@bra_id				= ttm.bra_id,
			@sd_id				= tct.sd_id
			FROM tbPurchaseConceptMovements						ttm	WITH  (NOLOCK)
			INNER JOIN tbCommercialTransactions					tct	WITH  (NOLOCK)
			ON	tct.comp_id			= ttm.comp_id			AND
				tct.ct_transaction	= ttm.ct_transaction
			WHERE	ttm.comp_id		= @comp_id AND
					ttm.pcm_id		= @pcm_id

			BEGIN


				-- Obtengo la cuenta contable original
				SELECT
					@acc_count_id_original	= tpc.acc_count_id
					FROM tbPurchaseConcept tpc	WITH  (NOLOCK)
					WHERE	tpc.comp_id	= @comp_id			AND
							tpc.puco_id	= @puco_id_Original


				-- Obtengo la cuenta contable destino
				SELECT
					@acc_count_id		= tpc2.acc_count_id
					FROM tbPurchaseConcept tpc2		WITH  (NOLOCK)
					WHERE	tpc2.comp_id	= @comp_id		AND
							tpc2.puco_id	= @puco_id



				-- Obtengo la imputacion contable que se hizo
				SELECT @dacc_transactionOriginal = tatd.dacc_transaction
					FROM tbAccountTransactionDetail tatd	WITH  (NOLOCK)
					WHERE	tatd.comp_id		= @comp_id AND
							tatd.ct_transaction = @ct_transaction AND
							tatd.acc_count_id	= @acc_count_id_original AND
						   (
			   				tatd.dacc_debit		= @decTotal OR
							tatd.dacc_credit	= @decTotal
						   )
					ORDER BY tatd.dacc_debit, tatd.dacc_credit

				-- Si logro enconrar la cuenta contable, la cambia
				IF @acc_count_id IS NOT NULL
					BEGIN

						UPDATE tbAccountTransactionDetail
							SET		acc_count_id		= @acc_count_id,
									cc_code				= @cc_code		-- MOS 12-2022
							WHERE	comp_id				= @comp_id					AND
									dacc_transaction	= @dacc_transactionOriginal

					END
			END
		-- ------------------------------------------------------------------


	-- Actualiza el concepto
	UPDATE 	dbo.tbPurchaseConceptMovements
		SET
				puco_id 		= @puco_id,
				cc_code			= @cc_code	-- MOS 12-2022
		WHERE	comp_id			= @comp_id	and
				pcm_id			= @pcm_id


END



GO






