CREATE PROCEDURE [dbo].[spPurchaseDocs_checkBasicData]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	/*
	DECLARE @comp_id		INT
	DECLARE @lang_id		INT
	DECLARE @bra_id			INT
	SELECT	@comp_id		=1,
			@lang_id		=2,
			@bra_id=1
	DROP TABLE #tmpData

	*/

	CREATE TABLE #tmpData ( [check] INT )

	/*
	por cada control que se realice al comienzo de las páginas y no esté correcto,
	hay que hacer un insert en la temporal creada arriba
	con el valor correspondiente al table_id de la tabla tbSysTables (siempre deberá ser un valor negativo)
	y este valor está relacionado con la tabla tbSysHelpPages que si tendrá el mensaje de error
	a mostrar al usuario
	*/

	if not exists (select 1 from tbPurchaseTerms			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (80005)
	if not exists (select 1 from tbPurchaseTransport		WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (80003)
	if not exists (select 1 FROM tbPurchaseConcept 			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (80002)
	if not exists (select 1 from tbSupplier					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (80001)

	/*
	if not exists (select 1 from tbSalesTerms				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-2)
	if not exists (select 1 from tbDelivery					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-3)
	if not exists (select 1 from tbDiscount					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-4)
	if not exists (select 1 from tbPriceList				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-5)
	IF NOT EXISTS (SELECT 1 FROM tbDocumentsFile df
							inner join dbo.[tbsysDocuments]	sd on sd.[sd_id] = df.[sd_id]
				   where df.comp_id	= @comp_id and df.bra_id = @bra_id
				   and sd.[sd_isReceipt] = 'True' and sd.[sd_isPurchase] = 'False')	  INSERT INTO #tmpData ([check]) VALUES (-7)
	if not exists (select 1 from tbCashNumbers				WHERE comp_id = @comp_id and bra_id = @bra_id )
															INSERT INTO #tmpData ([check]) VALUES (-8)
	if not exists (select 1 from tbCurrencyExchange			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-9)
	if not exists (select 1 from tbCashNumber4Branch4User	WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-10)
	if not exists (select 1 from tbCashAccountant			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-11)
	if not exists (select 1 from tbCreditCard				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-12)
	if not exists (select 1 FROM tbBankingAccounts			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-13)
	if not exists (select 1 FROM tbTaxName					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-14)
	*/
	IF NOT EXISTS (SELECT 1 FROM tbCurrencyExchange tce
				   WHERE	tce.comp_id = @comp_id
				   AND		tce.curr_id_1 = (	SELECT	tc.curr_id
												FROM	tbCompany tc
												WHERE	tc.comp_id	= @comp_id)
				   AND		tce.curr_id_2 = (	SELECT	curr_id
												FROM	tbBranch tb
												WHERE	tb.comp_id	= @comp_id
												AND		tb.bra_id	= @bra_id))
	AND
	   NOT EXISTS (SELECT 1 FROM tbCurrencyExchange tce
				   WHERE	tce.comp_id = @comp_id
				   AND		tce.curr_id_2 = (	SELECT	tc.curr_id
												FROM	tbCompany tc
												WHERE	tc.comp_id	= @comp_id)
				   AND		tce.curr_id_1 = (	SELECT	curr_id
												FROM	tbBranch tb
												WHERE	tb.comp_id	= @comp_id
												AND		tb.bra_id	= @bra_id))		INSERT INTO #tmpData ([check]) VALUES (-16)

	if   EXISTS (select 1 FROM tbBranch WHERE comp_id = @comp_id AND bra_id = @bra_id AND bra_PurDoc_coslis_id IS null)INSERT INTO #tmpData ([check]) VALUES(-17)

	SELECT	tut.utexts_desc, tut.utexts_id
	FROM	tbsysUniqueTexts tut
	WHERE	tut.lang_id			= @lang_id
	AND		tut.utexts_id		IN(4, 5, 6)
	AND		EXISTS(SELECT 1 FROM #tmpData)

	UNION

	SELECT	cast(thp.hp_desc AS NVARCHAR(MAX)), thp.page_id
	FROM	tbsysHelpPages			thp
			INNER JOIN #tmpData		td
			ON	td.[check]		= thp.table_id
	WHERE	thp.page_id			= -100030 --este valor está en duro e indica la funcionalidad que se está chequeando
	AND		thp.lang_id			= @lang_id

	ORDER BY 2 DESC



END
GO









CREATE PROCEDURE [dbo].[spPurchaseDocs_checkDocument]
(
	@comp_id				INT,
	@bra_id					INT,
	@ct_kindOf				VARCHAR(10),
	@ct_pointOfSale			INT,
	@ct_docNumber			VARCHAR(40),
	@sd_id					INT,
	@supp_id				AS	INT,
	@ct_transaction			INT,
	@return_value			INT OUTPUT
)
as

BEGIN

	set nocount on

	-- -------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------
/*
	declare		@comp_id				INT,
				@bra_id					INT,
				@ct_kindOf				VARCHAR(10),
				@ct_pointOfSale			INT,
				@ct_docNumber			VARCHAR(40),
				@sd_id					INT,
				@supp_id				AS	INT,
				@ct_transaction			INT,
				@return_value			INT

	select		@comp_id				= 1,
				@bra_id					= 1,
				@ct_kindOf				='A',
				@ct_pointOfSale			= 34,
				@ct_docNumber			='34634',
				@sd_id					= 101,
				@ct_transaction			= -1,
				@supp_id				= 8110
*/
	-- -------------------------------------------------------------------


	SET @ct_docNumber = dbo.fnStrPADL(ltrim(rtrim(@ct_docNumber)), 40,'0')

	IF EXISTS(	SELECT	1
				FROM	tbCommercialTransactions									tct			WITH (NOLOCK)
						INNER JOIN dbo.vwCommercialTransactions_forPurchase_All		vctfp		WITH (NOLOCK)
						ON		vctfp.comp_id			= tct.comp_id
						AND		vctfp.bra_id			= tct.bra_id
						AND		vctfp.ct_transaction	= tct.ct_transaction
						AND		vctfp.supp_id			= tct.supp_id
						AND		vctfp.sd_id				= tct.sd_id
				WHERE	tct.comp_id			= @comp_id
				--AND		tct.bra_id			= @bra_id   MOS 11-2018.   Ver si no molesta, el tema era que cargaban lo mismo en dos sucursales diferentes.
				AND		tct.ct_kindOf		= @ct_kindOf
				AND		tct.ct_pointOfSale	= @ct_pointOfSale
				AND		dbo.fnStrPADL(ltrim(rtrim(tct.ct_docNumber)),40,'0')	= @ct_docNumber
				AND     tct.sd_id			= @sd_id
				AND		tct.supp_id			= @supp_id
				AND		(@ct_transaction = -1 or tct.ct_transaction	<> @ct_transaction))

			set @return_value = 0
	ELSE
			set @return_value = 1

--==
--SELECT @ct_docNumber,@return_value
--==

END
GO






CREATE PROCEDURE [dbo].[spPurchaseDocs_getDataByFilters]
(
	@lang_id			int,
	@guid				uniqueidentifier
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	set nocount on

	-- -----------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------

/*

	declare		@lang_id		int,
				@guid			uniqueidentifier
	select		@lang_id		= 2,
				@guid			= '9F4C2609-A0B9-43C3-9282-833F47879208'

*/
	-- -----------------------------------------------------------------------------

		select	' ' [ ], ' ' [ ],
				[guid],
				[code],
				IsNull(vpd.[desc],'')	[desc],
				[qty],
				[price],
				tc.curr_symbol,
				[total],
				IsNull(ttn.tax_desc,'*')  [iva],
				[class],
				[puco_desc],
				vpd.stor_desc,
				vpd.Discount1,
				vpd.Discount2,
				vpd.Discount3,
				vpd.Discount4,
				vpd.SurCharge1,
				vpd.SurCharge2,
				vpd.SurCharge3,
				vpd.SurCharge4,
				class + '-' + convert(varchar,ID) [ID]

		from	vwPurchaseDocs	 vpd

				left Join tbsysCurrency tc
				On	tc.curr_id	= vpd.curr_id

				Left Join tbTaxName ttn
				On	ttn.tax_id	= vpd.tax_id

		where  vpd.guid			=	@guid
		And	   vpd.class		<> '5'

	Union

		select	' ' [ ], ' ' [ ],
				[guid],
				[code],
				[desc],
				[qty],
				[price],
				tc.curr_symbol,
				Sum(total) [total],
				IsNull(ttn.tax_desc,'*')  [iva],
				[class],
				[puco_desc],
				vpd5.stor_desc,
				vpd5.Discount1,
				vpd5.Discount2,
				vpd5.Discount3,
				vpd5.Discount4,
				vpd5.SurCharge1,
				vpd5.SurCharge2,
				vpd5.SurCharge3,
				vpd5.SurCharge4,
				class + '-' + convert(varchar,ID) [ID]

		from	vwPurchaseDocs	 vpd5

				left Join tbsysCurrency tc
				On tc.curr_id	= vpd5.curr_id

				Left Join tbTaxName ttn
				On ttn.tax_id	= vpd5.tax_id

		where  vpd5.guid		= @guid
		And    vpd5.class		= '5'


		Group By vpd5.guid,
				 vpd5.class,
				 vpd5.code,
				 vpd5.curr_id,
				 vpd5.tax_id,
				 vpd5.tax_desc,
				 vpd5.qty,
				 vpd5.price,
				 tc.curr_symbol,
				 ttn.tax_desc,
				 vpd5.class,
				 vpd5.puco_desc,
				 vpd5.stor_desc,
				 vpd5.Discount1,
				 vpd5.Discount2,
				 vpd5.Discount3,
				 vpd5.Discount4,
				 vpd5.SurCharge1,
				 vpd5.SurCharge2,
				 vpd5.SurCharge3,
				 vpd5.SurCharge4,
				 vpd5.ID,vpd5.[desc]

		ORDER BY [Class],[ID]

	Select 0


END
GO








CREATE procedure [dbo].[spPurchaseDocs_getHeaderData]
(
	@comp_id	int,
	@bra_id		int,
	@supp_id	int
)
as

set nocount on

/*
declare @comp_id	int,
		@bra_id		int,
		@supp_id	int

select	@comp_id	= 1,
		@bra_id		= 1,
		@supp_id	= 79
*/

declare @curr_id_1							int,
		@curr_id_2							int,
		@bra_CollectionMaximumAdjust		decimal(19,6),
		@bra_CollectionDefaultDocument		int,
		@state_id							int,
		@country_id							int


select	@curr_id_1						= b.curr_id							,
		@bra_CollectionMaximumAdjust	= b.bra_CollectionMaximumAdjust		,
		@bra_CollectionDefaultDocument	= b.bra_CollectionDefaultDocument
from	[tbBranch] b

where	b.bra_id = @bra_id


select	@curr_id_2		= b.curr_id,
		@country_id		= b.[country_id],
		@state_id		= b.[state_id]
from	dbo.tbSupplier b
where	b.[supp_id] = @supp_id


select
	@curr_id_2															[CurrIdSupp],
	(select	c.[curr_symbol]	from [tbSupplier] b
	inner join [tbsysCurrency] c on c.[curr_id] = b.[curr_id]
	where b.[supp_id] = @supp_id)										[Currency Supplier],
	1																	[Value Supplier],
	@curr_id_1															[CurrIdBranch],
	(select c.[curr_symbol]	from [tbBranch] b
	inner join [tbsysCurrency] c on c.[curr_id] = b.[curr_id]
	where b.bra_id = @bra_id)											[Currency Branch],
	(dbo.[fnGetExchange](@comp_id, 1, @curr_id_2, @curr_id_1, 0, 0, 0)) [Value Branch],
	@bra_CollectionMaximumAdjust										[CollectionMaximumAdjust],
	@bra_CollectionDefaultDocument										[CollectionDefaultDocument],
	@country_id															[SupplierCountry],
	@state_id															[SupplierState]


GO

CREATE PROCEDURE [dbo].[spPurchaseDocs_getSupplierDataByTaxNumber]
(
	@comp_id		INT,
	@bra_id			INT,
	@suppTaxNumber	VARCHAR(20)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------
		-- TESTING
		-- ----------------------------------------
		/*
		*/
		-- ----------------------------------------

		-- ----------------------------------------
		-- VARIABLES LOCALES DE TRABAJO
		-- ----------------------------------------
		DECLARE
			@puco_id	INT,
			@cc_code	INT
		-- ----------------------------------------

		-- -------------------------------------------------------
		-- EN CASO DE QUE NO TENGA ME GUARDO EL PRIMER PUCO
		-- -------------------------------------------------------
		SELECT
			TOP 1
				@puco_id		= tpc.puco_id
			FROM tbPurchaseConcept AS tpc	WITH(NOLOCK)
			WHERE tpc.comp_id	= @comp_id
			ORDER BY tpc.puco_desc
		-- -------------------------------------------------------

		-- -------------------------------------------------------
		-- EN CASO DE QUE NO TENGA ME GUARDO EL PRIMER COST CENTER
		-- -------------------------------------------------------
		SELECT
			TOP 1
				@cc_code	= cc_code
			FROM	dbo.tbCostCenter
			WHERE	comp_id	= @comp_id
			ORDER BY	CASE
							WHEN bra_id IS NOT NULL AND bra_id = @bra_id THEN	0
							ELSE													1
						END,
						cc_desc
		-- -------------------------------------------------------
		SET @suppTaxNumber = dbo.fnStrAllTrim(REPLACE(@suppTaxNumber,'-',''))

		SELECT
			ts.supp_id,
			ts.supp_name,
			ts.supp_taxNumber,
			ts.curr_id,
			ISNULL(ts.puco_id,@puco_id)									[puco_id],
			ISNULL(ts.cc_code,@cc_code)									[cc_code]
			FROM tbSupplier												AS ts	WITH(NOLOCK)
			WHERE	ts.comp_id										= @comp_id	AND
					RTRIM(LTRIM(REPLACE(ts.supp_taxNumber,'-','')))	= @suppTaxNumber

	END
GO


CREATE PROCEDURE spPurchaseDocs_getTaxIDByPercentage4PDF
(
	@comp_id	INT,
	@taxPercent	DECIMAL(19,5)
)
AS

	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@taxPercent	DECIMAL(19,5)
			SELECT
				@comp_id	= 1,
				@taxPercent	= 10.5
		*/
		-- --------------------------------------------
		SELECT
			ttn.tax_id
			FROM tbTaxName								AS ttn WITH(NOLOCK)
			INNER JOIN vwsysTaxClassIVA_ALL				AS vtcia	WITH(NOLOCK)
				ON	vtcia.tax_class		= ttn.tax_class
			WHERE	ttn.comp_id			= @comp_id		AND
					ttn.tax_percentage	= @taxPercent
	END

GO






-- MOS: 12-2009
-- Calculo teniendo en cuenta la Moneda

CREATE  PROCEDURE [dbo].[spPurchaseDocs_getTotals]

(
	@comp_id				As int,
	@lang_id				As int,
	@bra_id					AS int,
	@guid					As Uniqueidentifier,
	@forcedExchangeCurrency AS INT,
	@forcedExchange			As Decimal(29,6),
	@isBanking				AS BIT,
	@supp_id				AS INT,
	@discount1				AS DECIMAL(19,6),
	@discount2				AS DECIMAL(19,6),
	@discount3				AS DECIMAL(19,6),
	@discount4				AS DECIMAL(19,6)
)
AS

BEGIN

	set nocount on


-- ----------------------------------------------------------------------
-- Testing
-- ----------------------------------------------------------------------
/*
	declare	@comp_id	int,
			@lang_id	int,
			@bra_id		int,
			@guid		UNIQUEIDENTIFIER,
			@forcedExchangeCurrency AS INT,
			@forcedExchange			As Decimal(29,6),
			@isBanking				AS BIT,
			@supp_id				AS INT,
			@discount1				AS DECIMAL(19,6),
			@discount2				AS DECIMAL(19,6),
			@discount3				AS DECIMAL(19,6),
			@discount4				AS DECIMAL(19,6)


	select	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@guid		= 'A8A5B70D-C3BC-4D41-961A-42E371E44101',
			@forcedExchangeCurrency = 1,
			@forcedExchange = 4.01,
			@isBanking = 'True',
			@supp_id = 0,
			@discount1=0,
			@discount2=0,
			@discount3=0,
			@discount4=0
*/
-- ----------------------------------------------------------------------


	-- Buscar Moneda de la Sucursal Activa.
	Declare	@BranchCurrency As INT
	DECLARE @country_id		AS INT = -1
	Select	@BranchCurrency = tb.curr_id,
			@country_id		= tb.country_id
		From	tbBranch	tb	WITH (NOLOCK)
		Where	tb.comp_id		= @comp_id
			And	tb.bra_id		= @bra_id


	-- Buscar la Clase Fiscal del Proveedor
	DECLARE @fc_id AS INT
	SELECT  @fc_id = fc_id
		FROM tbSupplier ts		WITH (NOLOCK)
		where	ts.comp_id = @comp_id
			AND ts.supp_id = @supp_id


--	Declare @forcedExchangeCurrency As Int
--	Set		@forcedExchangeCurrency = @BranchCurrency



		-- Borrar Impuestos Calculados (De Items)
		Delete tbTaxMovementsTmp Where tmt_guid = @guid And isCalculated = 'true'


		IF @isBanking = 'False'
			BEGIN
				-- re-Calcular Impuestos de Items.
				Insert into tbTaxMovementsTmp
				(
					comp_id,
					bra_id,
					tmt_guid,
					tmt_cd,
					tax_id,
					tmt_subtotal,
					tmt_total,
					curr_id,
					percentaje,
					isCalculated,
					puco_id,
					pcmt_id,
					tis_id
				)

					(
						Select	@comp_id,
								@bra_id,
								titt.tis_guid,
								Getdate(),
								titt.tax_id,
								round(dbo.fnGetExchange(@comp_id,
														 titt.tis_price * titt.tis_qty *
														 dbo.fnGetFinalDiscountCoeficient(titt.tis_Discount1,titt.tis_Discount2,titt.tis_Discount3,titt.tis_Discount4) *
														 dbo.fnGetFinalDiscountCoeficient(-titt.tis_surcharge1,-titt.tis_surcharge2,-titt.tis_surcharge3,-titt.tis_surcharge4) *
														 dbo.fnGetFinalDiscountCoeficient(@discount1,@discount2,@discount3,@discount4),    -- Descuento por Item mas Descuento general
														 titt.curr_id,
														 @BranchCurrency,
														 @forcedExchangeCurrency,
														 @forcedExchange,
														 'false'),2),
								CASE
									WHEN  titt.tis_forcedValue <> 0 THEN titt.tis_forcedValue
									ELSE
											round((dbo.fnGetExchange(@comp_id,
														 titt.tis_price * titt.tis_qty *
														 dbo.fnGetFinalDiscountCoeficient(titt.tis_Discount1,titt.tis_Discount2,titt.tis_Discount3,titt.tis_Discount4) *
														 dbo.fnGetFinalDiscountCoeficient(-titt.tis_surcharge1,-titt.tis_surcharge2,-titt.tis_surcharge3,-titt.tis_surcharge4) *
														 dbo.fnGetFinalDiscountCoeficient(@discount1,@discount2,@discount3,@discount4),
														 titt.curr_id,
														 @BranchCurrency,
														 @forcedExchangeCurrency,
														 @forcedExchange,
														 'false') * (ttn.tax_percentage ) / 100),2)
								END
								,
								@BranchCurrency,
								ttn.tax_percentage ,
								'true',
								titt.puco_id,
								NULL,
								titt.tis_id
						From tbItemTransactionsTmp titt				WITH (NOLOCK)

						Inner Join tbTaxName ttn					WITH (NOLOCK)
						On		ttn.comp_id = titt.comp_id
							And ttn.tax_id  = titt.tax_id


						INNER JOIN tbTaxByFiscalClass ttbfc			WITH (NOLOCK)
						on ttbfc.comp_id		= @comp_id
							AND ttbfc.tax_id	= ttn.tax_id
							AND ttbfc.fc_id		= @fc_id

						Where	titt.tis_guid			= @guid
							AND ttbfc.fc_PurchaseOrSale = 'True'
							AND (ttbfc.bra_id IS NULL OR ttbfc.bra_id = @bra_id)
					)





				-- re-Calcular Impuestos de Conceptos.

				Insert into tbTaxMovementsTmp
				(
					comp_id,
					bra_id,
					tmt_guid,
					tmt_cd,
					tax_id,
					tmt_subtotal,
					tmt_total,
					curr_id,
					percentaje,
					isCalculated,
					puco_id,
					pcmt_id,
					tis_id

				)

				(
					Select	@comp_id,
							@bra_id,
							@guid,
							Getdate(),
							tpcmt.tax_id,
							round(dbo.fnGetExchange(@comp_id ,
											  tpcmt.pcmt_total * dbo.fnGetFinalDiscountCoeficient(@discount1,@discount2,@discount3,@discount4),    -- Descuento General
											  tpcmt.curr_id,
											  @BranchCurrency,
											  @forcedExchangeCurrency,
											  @forcedExchange,
											  'false'),2),
							CASE
								WHEN isnull(tpcmt.pcmt_forcedTAX,0) = 0		 THEN	-- Si se calcula el IVA Automaticamente
									round(dbo.fnGetExchange(@comp_id ,
        													tpcmt.pcmt_total * dbo.fnGetFinalDiscountCoeficient(@discount1,@discount2,@discount3,@discount4),
															tpcmt.curr_id,
															@BranchCurrency,
															@forcedExchangeCurrency,
															@forcedExchange,
															'false') * (ttn.tax_percentage ) / 100,2)
								ELSE												-- Si se pone un IVA forzado
									round(dbo.fnGetExchange(@comp_id ,
        													tpcmt.pcmt_forcedTAX ,
															tpcmt.curr_id,
															@BranchCurrency,
															@forcedExchangeCurrency,
															@forcedExchange,
															'false'),2)
								end
											  ,
							@BranchCurrency,
							ttn.tax_percentage ,
							'true',
							tpcmt.puco_id,
							tpcmt.pcmt_id,
							NULL

						From tbPurchaseConceptMovementsTmp tpcmt	WITH (NOLOCK)
						Inner Join tbTaxName ttn					WITH (NOLOCK)
							On		ttn.comp_id = tpcmt.comp_id
								And ttn.tax_id  = tpcmt.tax_id
						INNER JOIN tbTaxByFiscalClass ttbfc			WITH (NOLOCK)
						on ttbfc.comp_id		= @comp_id
							AND ttbfc.tax_id	= ttn.tax_id
							AND ttbfc.fc_id		= @fc_id
						Where	tpcmt.pcmt_guid			= @guid
							AND ttbfc.fc_PurchaseOrSale = 'True'
							AND (ttbfc.bra_id IS NULL OR ttbfc.bra_id = @bra_id)


				)


				-- MOS: 03-2012   fix
				UPDATE tbTaxMovementsTmp
					SET percentaje	= Tmp.percentaje - (Tmp.percentaje * ISNULL(ttfs.percentaje,0) / 100),
						tmt_total	= Tmp.tmt_total -  (Tmp.tmt_total * ISNULL(ttfs.percentaje,0) / 100)
					FROM tbTaxMovementsTmp Tmp				WITH (NOLOCK)
					INNER JOIN tbTaxFree4Suppliers ttfs		WITH (NOLOCK)
						ON		ttfs.comp_id = @comp_id
							AND ttfs.bra_id  = @bra_id
							AND ttfs.supp_id = @supp_id
							AND ttfs.tax_id  = Tmp.tax_id
					WHERE Tmp.tmt_guid = @guid


			END
		ELSE
			BEGIN	-- MOS 27-02-2021 para q calcule iva si el concepto lo habilita x ABM.
			     	-- el BURRO que habia pasado el parametro @isBanking habioa puesto INT en la clase y pasaba siempre FALSE x lo que esto NO deberia molestar ya q es la 1ra vez que se pasa
			     	-- y solo funciona si el concepto tiene el NUEVO campo puco_calculateTaxesInBankingMovements en true


				Insert into tbTaxMovementsTmp
				(
					comp_id,
					bra_id,
					tmt_guid,
					tmt_cd,
					tax_id,
					tmt_subtotal,
					tmt_total,
					curr_id,
					percentaje,
					isCalculated,
					puco_id,
					pcmt_id,
					tis_id

				)

				(
					Select	@comp_id,
							@bra_id,
							@guid,
							Getdate(),
							tpcmt.tax_id,
							round(dbo.fnGetExchange(@comp_id ,
											  tpcmt.pcmt_total * dbo.fnGetFinalDiscountCoeficient(@discount1,@discount2,@discount3,@discount4),    -- Descuento General
											  tpcmt.curr_id,
											  @BranchCurrency,
											  @forcedExchangeCurrency,
											  @forcedExchange,
											  'false'),2),
							CASE
								WHEN isnull(tpcmt.pcmt_forcedTAX,0) = 0		 THEN	-- Si se calcula el IVA Automaticamente
									round(dbo.fnGetExchange(@comp_id ,
        													tpcmt.pcmt_total * dbo.fnGetFinalDiscountCoeficient(@discount1,@discount2,@discount3,@discount4),
															tpcmt.curr_id,
															@BranchCurrency,
															@forcedExchangeCurrency,
															@forcedExchange,
															'false') * (ttn.tax_percentage ) / 100,2)
								ELSE												-- Si se pone un IVA forzado
									round(dbo.fnGetExchange(@comp_id ,
        													tpcmt.pcmt_forcedTAX ,
															tpcmt.curr_id,
															@BranchCurrency,
															@forcedExchangeCurrency,
															@forcedExchange,
															'false'),2)
								end
											  ,
							@BranchCurrency,
							ttn.tax_percentage ,
							'true',
							tpcmt.puco_id,
							tpcmt.pcmt_id,
							NULL

						From tbPurchaseConceptMovementsTmp tpcmt	WITH (NOLOCK)
						INNER JOIN tbPurchaseConcept AS tpc			WITH (NOLOCK)
							ON	tpc.comp_id = tpcmt.comp_id AND
								tpc.puco_id = tpcmt.puco_id
						Inner Join tbTaxName ttn					WITH (NOLOCK)
							On		ttn.comp_id = tpcmt.comp_id
								And ttn.tax_id  = tpcmt.tax_id
						--INNER JOIN tbTaxByFiscalClass ttbfc			WITH (NOLOCK)
						--on ttbfc.comp_id		= @comp_id
						--	AND ttbfc.tax_id	= ttn.tax_id
						--	AND ttbfc.fc_id		= @fc_id
						Where	tpcmt.pcmt_guid			= @guid
							--AND ttbfc.fc_PurchaseOrSale = 'True'
							--AND (ttbfc.bra_id IS NULL OR ttbfc.bra_id = @bra_id)
							AND tpc.puco_calculateTaxesInBankingMovements = 'True'


				)

				IF @@ROWCOUNT > 0
					BEGIN
						-- MOS: 03-2012   fix
						UPDATE tbTaxMovementsTmp
							SET percentaje	= Tmp.percentaje - (Tmp.percentaje * ISNULL(ttfs.percentaje,0) / 100),
								tmt_total	= Tmp.tmt_total -  (Tmp.tmt_total * ISNULL(ttfs.percentaje,0) / 100)
							FROM tbTaxMovementsTmp			Tmp			WITH (NOLOCK)
							INNER JOIN tbTaxFree4Suppliers	ttfs		WITH (NOLOCK)
								ON		ttfs.comp_id = @comp_id
									AND ttfs.bra_id  = @bra_id
									AND ttfs.supp_id = @supp_id
									AND ttfs.tax_id  = Tmp.tax_id
							WHERE Tmp.tmt_guid = @guid

					END



			END




		-- Calcular Totales

		select

			isnull((select sum(
								dbo.fnGetExchange(@comp_id ,
												  VTi.total *
												  dbo.fnGetFinalDiscountCoeficient(vti.Discount1,vti.Discount2,vti.Discount3,vti.Discount4) *
												  dbo.fnGetFinalDiscountCoeficient(-vti.surcharge1,-vti.surcharge2,-vti.surcharge3,-vti.surcharge4) *
												  dbo.fnGetFinalDiscountCoeficient(@discount1,@discount2,@discount3,@discount4),
												  VTi.curr_id,
												  @BranchCurrency,
												  @forcedExchangeCurrency,
												  @forcedExchange,
												  'false')
							  )
					from	vwPurchaseDocs vTi
					where	VTi.guid = @guid and VTi.class in (1,2)),0)						[TotalItems],


			isnull((select sum(
								dbo.fnGetExchange(@comp_id ,
												  VTc.total * dbo.fnGetFinalDiscountCoeficient(@discount1,@discount2,@discount3,@discount4),
												  VTc.curr_id,
												  @BranchCurrency,
												  @forcedExchangeCurrency,
												  @forcedExchange,
												  'false')
							  )
			        from	vwPurchaseDocs VTc
					where	VTc.guid = @guid and VTc.class = 3),0)							[TotalConceptos],


			isnull((select sum(
								dbo.fnGetExchange(@comp_id ,
												  VTIm.total,
												  VTIm.curr_id,
												  @BranchCurrency,
												  @forcedExchangeCurrency,
												  @forcedExchange,
												  'false')
							  )
			        from	vwPurchaseDocs VTIm
					where	VTIm.guid = @guid and (VTIm.class = 4 Or VTIm.class = 5)),0)	[TotalImpuestos],


			(SELECT COUNT(*)
					from	vwPurchaseDocs vTi
					where	VTi.guid = @guid and VTi.class in (1,2, 3))						[TotalQty],


			isnull((select sum(
								dbo.fnGetExchange(@comp_id ,
												  vTiB.totalB,
												  vTiB.curr_id,
												  @BranchCurrency,
												  @forcedExchangeCurrency,
												  @forcedExchange,
												  'false')
							  )
					from	vwPurchaseDocs vTiB		WITH (NOLOCK)
					where	vTiB.guid = @guid and vTiB.class in (1,2)),0)					[TotalItemsB],
			@country_id																		[country_id]


	-- -----------------------------------------
	-- Si es Nota de Credito de Proveedor
	-- Actualiza los stor_id con los de la tabla
	-- tbRMA_SupplierCreditNotePending
	-- -----------------------------------------
	UPDATE tbItemTransactionsTmp								WITH (ROWLOCK)
		SET stor_id = trscnp.stor_id
		FROM tbItemTransactionsTmp tmp
		INNER JOIN tbRMA_SupplierCreditNotePending trscnp		WITH (NOLOCK)
			ON trscnp.rmanc_id = tmp.rmanc_id
		WHERE tmp.tis_guid = @guid AND
			  trscnp.stor_id IS NOT null
	-- -----------------------------------------

END
GO






CREATE procedure [dbo].[spPurchaseDocs_RMA_getDataByFilters]
(
	@comp_id			int,
	@supp_id			int,
	@guid				UNIQUEIDENTIFIER
)
AS
SET NOCOUNT ON


-----------------------------------------------------------------------
/*
DECLARE		@comp_id			int,
			@supp_id			INT,
			@guid				UNIQUEIDENTIFIER

SELECT 		@comp_id			= 1,
			@supp_id			= 8137,
			@guid				= '67FE0473-68CF-487A-AB23-6FBB4D84173C'
*/
-----------------------------------------------------------------------



select	' ' [ ],
		tbi.item_code																		[item_code],
		tbi.item_desc																		[item_desc],
		trscnp.rmanc_qty																	[rmanc_qty],
		trscnp.rmanc_price																	[rmanc_price],
		trscnp.rmanc_id																		[ID]


FROM	tbRMA_SupplierCreditNotePending						trscnp

		left JOIN dbo.tbItem								tbi
		ON  trscnp.comp_id			= tbi.comp_id		AND
			trscnp.item_id			= tbi.item_id


where   trscnp.comp_id						= @comp_id		AND
		trscnp.supp_id						= @supp_id		AND
		trscnp.rmanc_isProcessed			= 'False'		AND
		NOT EXISTS (
					SELECT 1 FROM tbItemTransactionsTmp			titt
					WHERE titt.tis_guid	= @guid				AND
						  titt.rmanc_id = trscnp.rmanc_id
					)


GO






CREATE procedure [dbo].[spPurchaseDocs_RMA_getDataById]
(
	@comp_id			int,
	@rmanc_id			int
)
AS
SET NOCOUNT ON



-----------------------------------------------------------------------
/*
DECLARE		@comp_id			int,
			@rmanc_id			int

SELECT 		@comp_id			= 1,
			@rmanc_id			= 4
*/
-----------------------------------------------------------------------



select	i.item_code																		[item_code],
		i.item_desc																		[item_desc],
		i.item_id,
		trscnp.curr_id,
		trscnp.rmanc_qty																[rmanc_qty],
		trscnp.rmanc_price																[rmanc_price],
		trscnp.rmanc_id																	[ID]


FROM	tbRMA_SupplierCreditNotePending					trscnp

		INNER JOIN dbo.tbItem							i
		ON  trscnp.comp_id			= i.comp_id
		AND trscnp.item_id			= i.item_id


where   trscnp.comp_id						= @comp_id
and		trscnp.rmanc_id						= @rmanc_id


GO






CREATE PROCEDURE [dbo].[spPurchaseDocs_RMA_UpdateData]
(
	@comp_id				INT,
	@ct_transaction			INT,
	@rmanc_id				INT


)
AS
SET NOCOUNT ON


-----------------------------------------------------------------------
/*

DECLARE		@comp_id				INT,
			@ct_transaction			INT,
			@rmanc_id				INT

SELECT 		@comp_id				= 1,
			@ct_transaction			= 8137,
			@rmanc_id				= 5
*/
-----------------------------------------------------------------------



UPDATE tbRMA_SupplierCreditNotePending

SET		rmanc_isProcessed	= 'True',
		ct_transaction		= @ct_transaction


WHERE	 comp_id			= @comp_id
AND		 rmanc_id			= @rmanc_id


GO







CREATE PROCEDURE [dbo].[spPurchaseDocs_setTaxMovements]
(
	@comp_id				As int,
	--@lang_id				As int,
	@bra_id					AS int,
	@guid					As UNIQUEIDENTIFIER,
	@forcedExchange			As Decimal(29,6)
)
as
set nocount on


/*
declare	@comp_id	int,
		@lang_id	int,
		@bra_id		int,
		@guid		uniqueidentifier
select	@comp_id	= 1,
		@lang_id	= 2,
		@bra_id		= 1,
		@guid		= '3d434091-1694-441d-a6dd-24a500caaf72'
*/


-- Buscar Moneda de la Sucursal Activa.
Declare	@BranchCurrency As Int
Select	@BranchCurrency =  tb.curr_id
From	tbBranch tb
Where	tb.comp_id		= @comp_id
And		tb.bra_id		= @bra_id

Declare @forcedExchangeCurrency As Int
Set		@forcedExchangeCurrency = @BranchCurrency



-- Borrar Impuestos Calculados (De Items)
Delete	tbTaxMovementsTmp
Where	tmt_guid		= @guid
And		isCalculated	= 'true'



-- re-Calcular Impuestos de Items.
Insert into tbTaxMovementsTmp
(
		comp_id,
		bra_id,
		tmt_guid,
		tmt_cd,
		tax_id,
		tmt_total,
		curr_id,
		percentaje,
		isCalculated,
		puco_id
)
(
Select	@comp_id,
		@bra_id,
		titt.tis_guid,
		Getdate(),
		titt.tax_id,
		dbo.fnGetExchange(@comp_id ,
						  titt.tis_price * titt.tis_qty,
						  titt.curr_id,
						  @BranchCurrency,
						  @forcedExchangeCurrency,
						  @forcedExchange,
						  'false') * ttn.tax_percentage / 100 ,
		@BranchCurrency,
		ttn.tax_percentage,
		'true',
		titt.puco_id

From	tbItemTransactionsTmp titt

		Inner Join tbTaxName ttn
		ON	ttn.comp_id = titt.comp_id
		And ttn.tax_id  = titt.tax_id

Where	titt.tis_guid	= @guid
)


-- re-Calcular Impuestos de Conceptos.
Insert into tbTaxMovementsTmp
(
		comp_id,
		bra_id,
		tmt_guid,
		tmt_cd,
		tax_id,
		tmt_total,
		curr_id,
		percentaje,
		isCalculated,
		puco_id
)
(
Select	@comp_id,
		@bra_id,
		@guid,
		Getdate(),
		tpcmt.tax_id,
		dbo.fnGetExchange(@comp_id ,
						  tpcmt.pcmt_total ,
						  tpcmt.curr_id,
						  @BranchCurrency,
						  @forcedExchangeCurrency,
						  @forcedExchange,
						  'false') * ttn.tax_percentage / 100 ,
		@BranchCurrency,
		ttn.tax_percentage,
		'true',
		tpcmt.puco_id

From	tbPurchaseConceptMovementsTmp tpcmt

		Inner Join tbTaxName ttn
		On	ttn.comp_id = tpcmt.comp_id
		And	ttn.tax_id  = tpcmt.tax_id

Where	tpcmt.pcmt_guid = @guid
)
GO






CREATE PROCEDURE [dbo].[spPurchaseDocsBankExtract_getDataConceptMovements]

(

	@comp_id		INT,
	@ba_id			INT

)

AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	--------------------------------------------------------------
	--------------------------------------------------------------
	/*
	DECLARE		@comp_id	 INT


	SELECT		@comp_id	 = 1
	*/
	--------------------------------------------------------------
	--------------------------------------------------------------


		SELECT	' ' [ ],
				puco.puco_desc,
				CASE WHEN tct.sd_id = 141
			     THEN
					  pcm.pcm_total * -1
				 ELSE
				 	  pcm.pcm_total
			END							[pcm_total],
				tct.ct_date,
				tcc.cc_desc,
				tc.curr_desc,
				pcm.pcm_note1,
				pcm.pcm_note2,
				td.sd_desc,
				pcm.pcm_id				[ID]

		FROM	dbo.tbPurchaseConceptMovements          pcm			WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions		tct			WITH (NOLOCK)
				ON  tct.comp_id			= pcm.comp_id
				--AND tct.bra_id			= pcm.bra_id
				AND tct.ct_transaction	= pcm.ct_transaction

				LEFT JOIN tbsysDocuments				td			WITH (NOLOCK)
				ON	td.sd_id			= tct.sd_id

				INNER JOIN	tbPurchaseConcept			puco		WITH (NOLOCK)
				on puco.comp_id		= pcm.comp_id
				and puco.puco_id	= pcm.puco_id

				INNER JOIN tbCostCenter					tcc			WITH (NOLOCK)
				ON  tcc.comp_id  = pcm.comp_id
				AND tcc.cc_code  = pcm.cc_code

				INNER JOIN tbsysCurrency				tc			WITH (NOLOCK)
				ON tc.curr_id = pcm.curr_id



		WHERE	 pcm.comp_id					 = @comp_id		AND
				 tct.ba_id						 = @ba_id		AND
				 pcm.pcm_available4BankingTotals = 'True'		AND
				 tct.sd_id IN (140,141)							AND
				 NOT EXISTS(SELECT TOP 1 1		-- que no este en la temporal
							FROM tbPurchaseConceptMovementsTmp tpcmt			WITH (NOLOCK)
							WHERE   tpcmt.comp_id			= @comp_id
							and		tpcmt.pcm_id_original	= pcm.pcm_id )
																AND
				NOT EXISTS (				-- que no se haya cargado en otro ingreso
								SELECT TOP 1 1
									FROM tbPurchaseConceptMovements tpcm		WITH (NOLOCK)
									WHERE	tpcm.comp_id = pcm.comp_id AND
											tpcm.pcm_id_original = pcm.pcm_id
							)









END
GO







CREATE	PROCEDURE [dbo].[spPurchaseDocsBankExtract_getDataTaxMovements]
(
	@comp_id			INT,
	@ba_id				INT
)
as

BEGIN
--------------------------------------------------------------
--------------------------------------------------------------
/*
declare 	@comp_id		INT,
			@ba_id			int

select 		@comp_id		=1,
			@ba_id			=49
*/
--------------------------------------------------------------
--------------------------------------------------------------


	select  ' ' [ ],
		    ttn.tax_desc ,
			CASE WHEN tct.sd_id = 141
			     THEN
					  ttm.tm_total * -1
				 ELSE
				 	  ttm.tm_total
			END							[tm_total],
			ttm.percentaje,
			ttm.tm_originalDocument,
			ttm.tm_docDate,
			ttm.tm_docKindOf,
			ttm.tm_docPointOfSale,
			ttm.tm_docNumber,
			tc.country_desc,
			ts.state_desc,
			tpc.puco_desc,
			td.sd_desc,
			ttm.tm_transaction [ID]

	from		tbTaxMovements						ttm			WITH (NOLOCK)


	LEFT JOIN tbTaxName								ttn			WITH (NOLOCK)
	ON	ttn.comp_id		= ttm.comp_id AND
		ttn.tax_id		= ttm.tax_id

	LEFT JOIN tbCommercialTransactions				tct			WITH (NOLOCK)
	ON	tct.comp_id			= ttm.comp_id
	AND	tct.bra_id			= ttm.bra_id
	AND	tct.ct_transaction	= ttm.ct_transaction

	LEFT JOIN tbsysDocuments						td			WITH (NOLOCK)
	ON	td.sd_id			= tct.sd_id

	LEFT JOIN tbsysCountry							tc			WITH (NOLOCK)
	ON	tc.country_id	= ttm.Country_Id

	LEFT JOIN tbsysState							ts			WITH (NOLOCK)
	ON	ts.country_id	= ttm.Country_Id AND
		ts.state_id		= ttm.State_Id

	LEFT JOIN tbPurchaseConcept						tpc			WITH (NOLOCK)
	ON	tpc.comp_id		= ttm.comp_id	AND
		tpc.puco_id		= ttm.puco_id

	where		ttm.comp_id						=	@comp_id			AND
				tct.ba_id						=	@ba_id				AND
				ttm.tm_available4BankingTotals	=	'True'				AND
				tct.sd_id IN (140,141)									AND
			 NOT EXISTS(SELECT 1
	   						FROM tbTaxMovementsTmp ttmt	WITH (NOLOCK)
							WHERE   ttmt.comp_id			= @comp_id
							and		ttmt.tm_id_original	= ttm.tm_transaction )
																		AND
			NOT EXISTS (
						SELECT 1
							FROM tbTaxMovements ttmt		WITH (NOLOCK)
							WHERE	ttmt.comp_id		= ttm.comp_id AND
									ttmt.tm_id_original = ttm.tm_transaction
						)






END




GO







