-- -------------------------------------------------------------------------------------
-- Recuperamos el coeficiente de descuento de compras relacionado al item y proveedor.
-- -------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spPurchaseDocsItemsDetail_getDiscountCoeficient]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@item_id	INT,
	@supp_id	INT

)
AS

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@item_id	INT,
			@supp_id	INT,
			@user_id    INT,
			@prof_id	INT



		SELECT
			@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@item_id	=257,
			@supp_id	=8103,
			@user_id    = 3
*/
	-- ------------------------------------------------------

	DECLARE @lpd_id AS INT
	SET @lpd_id = 0

	DECLARE @ldiscountcoeficient AS DECIMAL(25,10)
	SET @ldiscountcoeficient = 1

	SET @lpd_id =(SELECT
					CASE
						WHEN ti.pd_id IS NOT NULL  THEN ti.pd_id
						WHEN ts.pd_id IS NOT NULL  THEN ts.pd_id
						ELSE						    -1
					END									[pd_id]
					FROM tbItem				ti		WITH (NOLOCK)
					LEFT JOIN tbSupplier	ts		WITH (NOLOCK)
						ON	ts.comp_id = ti.comp_id AND
							ts.supp_id = ti.supp_id
					WHERE ti.comp_id = @comp_id			AND
						  ti.item_id = @item_id
					)

			IF @lpd_id > 0

				BEGIN


					SELECT 	@ldiscountcoeficient =	 ISNULL(tpd.pd_discountCoeficient,0)
						FROM tbPurchaseDiscount					 tpd	WITH (NOLOCK)
						WHERE	tpd.comp_id							= @comp_id	AND
								tpd.pd_id							= @lpd_id	AND
								tpd.pd_discount_apply4PurchaseDocs = 'True'	AND
								tpd.pd_isDisabled					= 'False'


					SELECT 	@ldiscountcoeficient =	(@ldiscountcoeficient + ISNULL(tpd.pd_bonificationCoeficient,0)) - ( @ldiscountcoeficient *  ISNULL(tpd.pd_bonificationCoeficient,0) )
						FROM tbPurchaseDiscount					 tpd	WITH (NOLOCK)
						WHERE	tpd.comp_id								= @comp_id	AND
								tpd.pd_id								= @lpd_id	AND
								tpd.pd_bonification_apply4PurchaseDocs  = 'True'	AND
								tpd.pd_isDisabled						= 'False'


					SELECT 	@ldiscountcoeficient =  (@ldiscountcoeficient + ISNULL(tpd.pd_bonificationCNCoeficient,0)) - ( @ldiscountcoeficient *  ISNULL(tpd.pd_bonificationCNCoeficient,0) )
						FROM tbPurchaseDiscount					 tpd	WITH (NOLOCK)
						WHERE	tpd.comp_id									= @comp_id	AND
								tpd.pd_id									= @lpd_id	AND
								tpd.pd_bonificationCN_apply4PurchaseDocs	= 'True'	AND
								tpd.pd_isDisabled							= 'False'

					--SELECT 	@ldiscountcoeficient = ISNULL(tpd.pd_discountCoeficient,1)
					--	FROM tbPurchaseDiscount					 tpd	WITH (NOLOCK)
					--	WHERE	tpd.comp_id							= @comp_id	AND
					--			tpd.pd_id							= @lpd_id	AND
					--			tpd.pd_discount_apply4PurchaseDocs  = 'True'	AND
					--			tpd.pd_isDisabled					= 'False'


					--SELECT 	@ldiscountcoeficient = @ldiscountcoeficient * ISNULL(tpd.pd_bonificationCoeficient,1)
					--	FROM tbPurchaseDiscount					 tpd	WITH (NOLOCK)
					--	WHERE	tpd.comp_id								= @comp_id	AND
					--			tpd.pd_id								= @lpd_id	AND
					--			tpd.pd_bonification_apply4PurchaseDocs	= 'True'	AND
					--			tpd.pd_isDisabled						= 'False'

					--SELECT 	@ldiscountcoeficient = @ldiscountcoeficient * ISNULL(tpd.pd_bonificationCNCoeficient,1)
					--	FROM tbPurchaseDiscount					 tpd	WITH (NOLOCK)
					--	WHERE	tpd.comp_id									= @comp_id	AND
					--			tpd.pd_id									= @lpd_id	AND
					--			tpd.pd_bonificationCN_apply4PurchaseDocs	= 'True'	AND
					--			tpd.pd_isDisabled							= 'False'


				END


				--Si es NULL quiere decir que o no está habilitado para OC o está deshabilitado el descuento de compras.
				SELECT isnull(@ldiscountcoeficient,1) [discountcoeficient]

END
GO








