CREATE PROCEDURE [dbo].[spPurchaseDocumentsStatusConcept_UpdateStatus]
(

	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,

	@ct_transaction		INT,
	@pdsc_id			INT

)
as

BEGIN


	-----------------------------------------
	-- parametros de test
	-----------------------------------------
	/*
	declare 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,

				@ct_transaction		INT,
				@pdsc_id			INT


	select		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@pdsc_id			= 1,
				@ct_transaction		= 8526
	*/
	-----------------------------------------
	-- parametros de test
	-----------------------------------------

	declare @lis_ok  BIT
	SET @lis_ok = 'False'

	select @lis_ok = (select tpds.pds_isOk
						from tbPurchaseDocumentsStatus tpds

						where	comp_id			= @comp_id		  and
								bra_id			= @bra_id	      and
								ct_transaction	= @ct_transaction and
								pdsc_id			= @pdsc_id)


	if  @lis_ok = 'false'
				BEGIN
					update tbPurchaseDocumentsStatus
						SET		pds_isOk = 'true'

					where	comp_id			= @comp_id		  and
							bra_id			= @bra_id	      and
							ct_transaction	= @ct_transaction and
							pdsc_id			= @pdsc_id
				END
	else
				BEGIN
					update tbPurchaseDocumentsStatus
						SET		pds_isOk = 'false'
					where	comp_id			= @comp_id	      and
							bra_id			= @bra_id		  and
							ct_transaction	= @ct_transaction and
							pdsc_id			= @pdsc_id
				END






END


GO








CREATE PROCEDURE [dbo].[spPurchaseFormula_validateData]
(
	@lang_id			INT,
	@pf_condition		VARCHAR(8000),
	@pf_AffFormula		VARCHAR(8000),
	@pf_negFormula		VARCHAR(8000),
	@errormessage		VARCHAR(200) OUTPUT
)
AS

SET NOCOUNT ON


/*
DECLARE		@lang_id			INT,
			@pf_condition		VARCHAR(8000),
			@pf_AffFormula		VARCHAR(8000),
			@pf_negFormula		VARCHAR(8000),
			@errormessage		varchar(200)
SELECT		@lang_id			= 2,
			@pf_condition		='@PF_ITEM_STOCK < @PF_ITEM_QTYMIN1 ',
			@pf_AffFormula		='@PF_ITEM_QTYMIN1 * 20',
			@pf_negFormula		='@PF_ITEM_QTYMIN1 * 1'
DROP TABLE #tmp_tmp
drop table #tmp
*/



declare @return_value int
set @return_value = 0
set @errormessage = ''



--crear tabla temporal para descripciones de posibles errores
CREATE TABLE #tmp (	[field_id]				[int]			null,
					[type_id]				[int]			null,
					[type_desc]				[varchar](200)	null,
					[name_desc]				[varchar](200)	null,
					[name_join]				[varchar](200)	null,
					[name_combo]			[varchar](200)	null,
					[name_column]			[varchar](200)	null,
					[name_comboact]			[varchar](200)	null,
					[name_errormessage]		[varchar](200)	null,
					[name_errormessage2]	[varchar](200)	null,
					[ctrl_id]				[int]			null,
					[ctrl_desc]				[varchar](200)	null,
					[prop_id]				[int]			null,
					[prop_desc]				[varchar](200)	null)


--recuperar las descripciones de los posibles errores que pudieran ocurrir en la validación
INSERT #tmp
(	[field_id],[type_id],[type_desc],[name_desc],
	[name_join],[name_combo],[name_column],[name_comboact],[name_errormessage], [name_errormessage2],
	[ctrl_id],[ctrl_desc],[prop_id],[prop_desc])
		exec dbo.spSysNames_getDataByTab @lang_id, 119 , -1 ,-1




SELECT @pf_condition	= dbo.fnGetFormula(@pf_condition	,2)
SELECT @pf_AffFormula	= dbo.fnGetFormula(@pf_AffFormula	,2)
SELECT @pf_negFormula	= dbo.fnGetFormula(@pf_negFormula	,2)



CREATE TABLE #tmp_tmp ( id INT )


BEGIN TRY

	EXEC	('select 1 from #tmp_tmp where ' + @pf_condition + ' and 1 = 2' )

END TRY
BEGIN CATCH
	begin
		set	@errormessage = (select [name_errormessage] from #tmp where ctrl_id = 287)
		set @return_value = 287

		return @return_value
	end
END CATCH





BEGIN TRY

		EXEC	('select ' + @pf_AffFormula + ' from #tmp_tmp where 1 = 2')

END TRY
BEGIN CATCH
	begin
		set	@errormessage = (select [name_errormessage] from #tmp where ctrl_id = 288)
		set @return_value = 288

		return @return_value
	end
END CATCH





BEGIN TRY

		EXEC	('select ' + @pf_negFormula + ' from #tmp_tmp where 1 = 2')

END TRY
BEGIN CATCH
	begin
		set	@errormessage = (select [name_errormessage] from #tmp where ctrl_id = 289)
		set @return_value = 289

		return @return_value
	end
END CATCH
GO






CREATE PROCEDURE [dbo].[spPurchaseOrder_checkBasicData]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			INT
)
AS


BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	/*
	DECLARE @comp_id		INT
	DECLARE @lang_id		INT
	SELECT	@comp_id		=1,
			@lang_id		=2
	DROP TABLE #tmpData
	*/


	CREATE TABLE #tmpData ( [check] INT )

	/*
	por cada control que se realice al comienzo de las páginas y no esté correcto,
	hay que hacer un insert en la temporal creada arriba
	con el valor correspondiente al table_id de la tabla tbSysTables (siempre deberá ser un valor negativo)
	y este valor está relacionado con la tabla tbSysHelpPages que si tendrá el mensaje de error
	a mostrar al usuario
	*/

	if not exists (select 1 from tbSupplier					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-1)
	if not exists (select 1 from tbPurchaseTerms			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-2)
	if not exists (select 1 from tbPurchaseTransport		WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-3)
	if not exists (select 1 from tbItem						WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-4)


	/*
	if not exists (select 1 from tbSalesman					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-1)
	if not exists (select 1 from tbSalesTerms				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-2)
	if not exists (select 1 from tbDelivery					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-3)
	if not exists (select 1 from tbDiscount					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-4)
	if not exists (select 1 from tbPriceList				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-5)

	IF NOT EXISTS (SELECT 1 FROM tbDocumentsFile df
							inner join dbo.[tbsysDocuments]	sd on sd.[sd_id] = df.[sd_id]
				   where df.comp_id	= @comp_id and df.bra_id = @bra_id
				   and sd.[sd_isReceipt] = 'True' and sd.[sd_isPurchase] = 'False')	  INSERT INTO #tmpData ([check]) VALUES (-7)
	if not exists (select 1 from tbCashNumbers				WHERE comp_id = @comp_id and bra_id = @bra_id )
															INSERT INTO #tmpData ([check]) VALUES (-8)
	if not exists (select 1 from tbCurrencyExchange			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-9)
	if not exists (select 1 from tbCashNumber4Branch4User	WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-10)
	if not exists (select 1 from tbCashAccountant			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-11)
	if not exists (select 1 from tbCreditCard				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-12)
	if not exists (select 1 FROM tbBankingAccounts			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-13)
	if not exists (select 1 FROM tbTaxName					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-14)
	*/
	IF NOT EXISTS (SELECT 1 FROM tbCurrencyExchange tce
				   WHERE	tce.comp_id = @comp_id
				   AND		tce.curr_id_1 = (	SELECT	tc.curr_id
												FROM	tbCompany tc
												WHERE	tc.comp_id	= @comp_id)
				   AND		tce.curr_id_2 = (	SELECT	curr_id
												FROM	tbBranch tb
												WHERE	tb.comp_id	= @comp_id
												AND		tb.bra_id	= @bra_id))
	AND
	   NOT EXISTS (SELECT 1 FROM tbCurrencyExchange tce
				   WHERE	tce.comp_id = @comp_id
				   AND		tce.curr_id_2 = (	SELECT	tc.curr_id
												FROM	tbCompany tc
												WHERE	tc.comp_id	= @comp_id)
				   AND		tce.curr_id_1 = (	SELECT	curr_id
												FROM	tbBranch tb
												WHERE	tb.comp_id	= @comp_id
												AND		tb.bra_id	= @bra_id))		INSERT INTO #tmpData ([check]) VALUES (-16)


	SELECT	tut.utexts_desc, tut.utexts_id
	FROM	tbsysUniqueTexts tut
	WHERE	tut.lang_id			= @lang_id
	AND		tut.utexts_id		IN(4, 5, 6)
	AND		EXISTS(SELECT 1 FROM #tmpData)

	UNION

	SELECT	cast(thp.hp_desc AS NVARCHAR(MAX)), thp.page_id
	FROM	tbsysHelpPages			thp
			INNER JOIN #tmpData		td
			ON	td.[check]		= thp.table_id
	WHERE	thp.page_id			= -100050 --este valor está en duro e indica la funcionalidad que se está chequeando
	AND		thp.lang_id			= @lang_id

	ORDER BY 2 DESC


END
GO






CREATE PROCEDURE [dbo].[spPurchaseOrder_checkStatusGrant]
(
		@comp_id		INT,
		@bra_id			INT,
		@poh_id			INT,
		@user_id		INT,
		@return_value	INT output
)
as
set nocount on

/*
	DECLARE		@comp_id		INT,
				@bra_id			INT,
				@poh_id			INT,
				@user_id		INT,
				@return_value	INT

	SELECT		@comp_id		= 1,
				@bra_id			= 1,
				@poh_id			= 89,
				@user_id		= 1
*/


SET @return_value = 0

/*este query es para habilitar las modificaciones de ordenes de compra*/
/*si los estados de tbPurchaseOrderState son true o el perfil no tiene permisos
* de actualización recuperados de tbPurchaseOrderStateRelations se retorna el
* valor 1 que significa que NO se puede modificar */
IF EXISTS (	SELECT	1
			FROM	tbPurchaseOrderState tpos

	 				LEFT JOIN tbPurchaseOrderStateRelations tposr
					ON tposr.comp_id = tpos.comp_id
					AND tposr.bra_id = tpos.bra_id
					AND tposr.poc_id = tpos.poc_id
					--AND tposr.prof_id = tucp.


					LEFT JOIN tbUserCompanyProfile		tucp
					ON	tucp.comp_id	=	tposr.comp_id
					AND tucp.bra_id		=	tposr.bra_id
					AND tucp.prof_id	=	tposr.prof_id
					AND	tucp.[user_id]	=	@user_id


			WHERE	tpos.comp_id	=	@comp_id
			AND		tpos.bra_id		=	@bra_id
			AND		tpos.poh_id		=	@poh_id
			AND		(tpos.pos_ok	=	'true' AND isnull(tposr.pocr_canUpdate,'false') = 'false'))

			BEGIN
				SET @return_value = 1
			END


	--SELECT @return_value
GO







CREATE  PROCEDURE [dbo].[spPurchaseOrder_deleteData]
(
	@comp_id				INT,
	@bra_id					INT,
	@poh_id					int,
	@podt_guid				UNIQUEIDENTIFIER,
	@return_value			INT OUTPUT
)
as

BEGIN


	set nocount off

-- --------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------
	/*
		declare	@poh_id				int,
				@podt_guid			UNIQUEIDENTIFIER,
				@return_value			INT

		SELECT 	@poh_id				= 67--,
				--@podt_guid			UNIQUEIDENTIFIER

	*/
-- --------------------------------------------------------------

	BEGIN TRANSACTION
	BEGIN TRY


		-- Controla que se pueda borrar la re puta OC
		DECLARE @bitCanDeleteByReceptionCancelled AS BIT = 'False'
		IF EXISTS(
						SELECT TOP 1 1
							FROM tbPurchaseorderReceptionDetail			AS	tprd	WITH (NOLOCK)
							INNER JOIN tbPurchaseorderReceptionHeader		tprh	WITH (NOLOCK)
								ON	tprh.comp_id	= tprd.comp_id AND
									tprh.por_id		= tprd.por_id
							INNER JOIN tbPurchaseOrderHeader			AS	tpoh	WITH (NOLOCK)
								ON	tpoh.comp_id	= tprd.comp_id		AND
									tpoh.bra_id		= tprd.poh_bra_id	AND
									tpoh.poh_id		= tprd.poh_id
						WHERE	tprd.comp_id	= @comp_id	AND
								tprd.poh_bra_id = @bra_id	AND
								tprd.poh_id		= @poh_id	AND
								(
									tpoh.pho_selectedInRecepcion = 'True'	OR
									tprd.it_transaction IS NOT NULL			OR
									tprd.pord_qty				 > 0		OR
									tprh.por_isCancelled		= 'False'
								)
				)
			BEGIN
				SET @bitCanDeleteByReceptionCancelled = 'True'
			END


			IF
				(
					SELECT COUNT(*)										-- x MOS, 7-2011, sino nunca se podia borrar una oc ya que el propio usuario actualizaba el isediting
						FROM	tbPurchaseOrderDetail tpod			WITH (NOLOCK)
						WHERE		tpod.poh_id			= @poh_id
							AND		tpod.comp_id		= @comp_id
							AND		tpod.bra_id			= @bra_id
							AND		tpod.pod_isEditing	= 'True'
				) = 0
						AND

				-- MOS 04-2022 x los &/%&/%&/$ de MF
				@bitCanDeleteByReceptionCancelled = 'False'
				--NOT EXISTS(												-- MOS 06-2020 por si tienen una recepcion NO cancelada, que no permita.
				--			SELECT TOP 1 1
				--				FROM tbPurchaseorderReceptionDetail			tmp			WITH (NOLOCK)
				--				INNER JOIN tbPurchaseorderReceptionHeader	tprh		WITH (NOLOCK)
				--					ON	tprh.comp_id	= tmp.comp_id AND
				--						tprh.por_id		= tmp.por_id
				--				WHERE	tmp.comp_id					= @comp_id	AND
				--						tmp.poh_bra_id				= @bra_id	AND
				--						tmp.poh_id					= @poh_id	AND
				--						tprh.por_isCancelled		= 'False'
				--			)
				BEGIN

					SET @return_value = 1

					exec dbo.[spPurchaseOrderDetailTmp_deleteAllData]	@podt_guid

					DELETE FROM tbPurchaseorderReceptionDetail
						WHERE comp_id = @comp_id AND poh_bra_id = @bra_id AND poh_id = @poh_id

					exec dbo.[spPurchaseOrderDetail_deleteAllData] 		@comp_id, @bra_id, @poh_id


					DELETE FROM tbPurchaseOrderState
						WHERE	comp_id = @comp_id	AND
								bra_id	= @bra_id	AND
								poh_id	= @poh_id


					--== BORRAMOS PLAN DE PAGO DE COMPRAS SIEMPRE Y CUANDO NO TENGA YA UNA FACTURA ASOCIADA.
					DELETE FROM tbCommercialTransactionsPurchaseLoan
					WHERE	comp_id			= @comp_id AND
							bra_id			= @bra_id AND
							poh_id			= @poh_id AND
							ct_transaction	IS NULL
					--==

					if @poh_id <> -1
					begin

						exec dbo.[spPurchaseOrderHeader_deleteData] @comp_id,
																	@bra_id,
																	@poh_id

					end

				END

			ELSE
				BEGIN
					SET @return_value = 0
				END


			SELECT @return_value


			COMMIT TRANSACTION

	END TRY
	BEGIN CATCH
		set	@return_value = -1
		ROLLBACK TRANSACTION

	END CATCH


END
GO







CREATE procedure [dbo].[spPurchaseOrder_getDataByFilters]
(
	@comp_id			int,
	@bra_id				int,
	@supp_id			int,
	@item_id			int
)
AS

BEGIN




	SET NOCOUNT ON

	-- -----------------------------------------------------------------
	-- -----------------------------------------------------------------
	/*
	declare		@comp_id			int,
				@bra_id				int,
				@supp_id			int,
				@item_id			int

	select 		@comp_id			= 1,
				@bra_id				= 27,
				@supp_id			= 8103,
				@item_id			= -1

	DROP TABLE #tmpPOS
	*/
	-- -----------------------------------------------------------------




	-- -----------------------------------------------------------------
	-- Sucursales de las cuales TRAERA las OC
	-- -----------------------------------------------------------------
	DECLARE @tmpBranchs TABLE(bra_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchs
	(
		bra_id
	)
	SELECT	DISTINCT  tbg.bra_id
		FROM tbBranch					tb	WITH (NOLOCK)
		INNER JOIN  tbBranchGroupDetail tbg	WITH (NOLOCK)
			ON	tbg.comp_id = tb.comp_id AND
				tbg.brag_id = tb.brag_id4PurchaseOrder_page48
		WHERE	tb.comp_id						= @comp_id		AND
				tb.bra_id						= @bra_id		AND
				tb.bra_disabled					= 'False'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpBranchs
				(
					bra_id
				)
				VALUES(@bra_id)
		END
	-- -----------------------------------------------------------------




	--obtengo la cantidad de estados aprobados que debe tener cada Orden de Compra
	DECLARE	@pos_qty		INT
	SELECT	@pos_qty		= COUNT(*)
		FROM	tbPurchaseOrderStateConcept		tposc		WITH (NOLOCK)
		WHERE	tposc.comp_id	= @comp_id
	--SELECT @pos_qty




	--recupero solo las Ordenes de Compra que tienen todos los estados aprobados
	SELECT	tpos.bra_id,
			tpos.poh_id,
			COUNT(*)		[count]
		INTO	#tmpPOS
		FROM	tbPurchaseOrderState			tpos			WITH (NOLOCK)
		INNER JOIN @tmpBranchs tmp
			ON tmp.bra_id = tpos.bra_id
		WHERE		tpos.comp_id	= @comp_id
			--AND		tpos.bra_id		= @bra_id
			AND     tpos.pos_ok		= 'True'
		GROUP BY tpos.poh_id,tpos.bra_id
		HAVING	COUNT(*)		= @pos_qty
		--SELECT * FROM #tmpPOS

	select	pod.item_id,
			i.item_code,
			i.item_desc,
			pod.curr_id,
			sc.curr_desc,
			pod.cont_id,
			pod.pod_qty,
			ISNULL(pod.pod_confirmedQTY,0)									[pod_confirmedQTY],
			pod.pod_price,
			ISNULL(pod.tax_id,0)											[tax_id],
			ISNULL(tax.tax_desc,'')											[tax_desc],
			pod.pod_isProcessed,
			isnull(tpt.pt_desc,'')											[pt_desc],
			CONVERT(VARCHAR,pod.poh_id) + '-' + CONVERT(VARCHAR,pod.pod_id)	[ID]


	FROM	dbo.tbPurchaseOrderHeader				poh		WITH (NOLOCK)

			INNER JOIN @tmpBranchs tmp
				ON tmp.bra_id			= poh.bra_id

			INNER JOIN dbo.tbPurchaseOrderDetail	pod		WITH (NOLOCK)
				ON  poh.comp_id			= pod.comp_id
				AND poh.bra_id			= pod.bra_id
				AND poh.poh_id			= pod.poh_id

			LEFT JOIN dbo.tbTaxName					tax		WITH (NOLOCK)
				ON  pod.comp_id			= tax.comp_id
				AND pod.tax_id			= tax.tax_id

			INNER JOIN dbo.tbsysCurrency			sc		WITH (NOLOCK)
				ON  pod.curr_id			= sc.curr_id

			INNER JOIN dbo.tbItem					i		WITH (NOLOCK)
				ON  pod.comp_id			= i.comp_id
				AND pod.item_id			= i.item_id

			LEFT JOIN #tmpPOS						pos		WITH (NOLOCK)
				ON	poh.bra_id			= pos.bra_id	AND
					poh.poh_id			= pos.poh_id

			LEFT JOIN tbPurchaseTerms				tpt		WITH (NOLOCK)
				ON	tpt.comp_id			= poh.comp_id	AND
					tpt.pt_id			= poh.pt_id


	where   poh.comp_id				= @comp_id
	--and     poh.bra_id				= @bra_id
	and		poh.supp_id				= @supp_id
	and		pod.pod_isProcessed		= 'False'
	and     (@item_id				= -1		OR	pod.item_id = @item_id)

	AND		poh.poh_id NOT IN (	SELECT	tpoh.poh_id
   									FROM	tbPurchaseOrderHeader	tpoh		WITH (NOLOCK)
   									INNER JOIN @tmpBranchs tmp2
										ON tmp2.bra_id				= tpoh.bra_id
   									WHERE	tpoh.comp_id			= @comp_id
   									--AND		tpoh.bra_id				= @bra_id
									AND		tpoh.poh_isEditing		= 'True')

	AND		pod.pod_id NOT IN (	SELECT	tpod.pod_id
   									FROM	tbPurchaseOrderDetail	tpod		WITH (NOLOCK)
   									INNER JOIN @tmpBranchs tmp3
										ON tmp3.bra_id				= tpod.bra_id
   									WHERE	tpod.comp_id			= @comp_id
   									AND		tpod.bra_id				= @bra_id
   									AND		tpod.pod_isEditing		= 'True')


END

GO







CREATE procedure [dbo].[spPurchaseOrder_getDataByFilters2]
(
	@comp_id			int,
	@bra_id				int,
	@supp_id			int,
	@item_id			INT,
	@guid				UNIQUEIDENTIFIER
)
AS

BEGIN




	SET NOCOUNT ON

	-- -----------------------------------------------------------------
	-- -----------------------------------------------------------------
	/*
	declare		@comp_id			int,
				@bra_id				int,
				@supp_id			int,
				@item_id			int

	select 		@comp_id			= 1,
				@bra_id				= 27,
				@supp_id			= 8103,
				@item_id			= -1

	DROP TABLE #tmpPOS
	*/
	-- -----------------------------------------------------------------




	-- -----------------------------------------------------------------
	-- Sucursales de las cuales TRAERA las OC
	-- -----------------------------------------------------------------
	DECLARE @tmpBranchs TABLE(bra_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchs
	(
		bra_id
	)
	SELECT	DISTINCT  tbg.bra_id
		FROM tbBranch					tb	WITH (NOLOCK)
		INNER JOIN  tbBranchGroupDetail tbg	WITH (NOLOCK)
			ON	tbg.comp_id = tb.comp_id AND
				tbg.brag_id = tb.brag_id4PurchaseOrder_page48
		WHERE	tb.comp_id						= @comp_id		AND
				tb.bra_id						= @bra_id		AND
				tb.bra_disabled					= 'False'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpBranchs
				(
					bra_id
				)
				VALUES(@bra_id)
		END
	-- -----------------------------------------------------------------




	--obtengo la cantidad de estados aprobados que debe tener cada Orden de Compra
	DECLARE	@pos_qty		INT
	SELECT	@pos_qty		= COUNT(*)
		FROM	tbPurchaseOrderStateConcept		tposc		WITH (NOLOCK)
		WHERE	tposc.comp_id	= @comp_id
	--SELECT @pos_qty




	--recupero solo las Ordenes de Compra que tienen todos los estados aprobados
	SELECT	tpos.bra_id,
			tpos.poh_id,
			COUNT(*)		[count]
		INTO	#tmpPOS
		FROM	tbPurchaseOrderState			tpos			WITH (NOLOCK)
		INNER JOIN @tmpBranchs tmp
			ON tmp.bra_id = tpos.bra_id
		WHERE		tpos.comp_id	= @comp_id
			--AND		tpos.bra_id		= @bra_id
			AND     tpos.pos_ok		= 'True'
		GROUP BY tpos.poh_id,tpos.bra_id
		HAVING	COUNT(*)		= @pos_qty
		--SELECT * FROM #tmpPOS

	select	pod.item_id,
			i.item_code,
			i.item_desc,
			pod.curr_id,
			sc.curr_desc,
			pod.cont_id,
			pod.pod_qty,
			ISNULL(pod.pod_confirmedQTY,0)									[pod_confirmedQTY],
			pod.pod_price,
			ISNULL(pod.tax_id,0)											[tax_id],
			ISNULL(tax.tax_desc,'')											[tax_desc],
			pod.pod_isProcessed,
			isnull(tpt.pt_desc,'')											[pt_desc],
			CONVERT(VARCHAR,pod.bra_id) + '-' + CONVERT(VARCHAR,pod.poh_id) + '-' + CONVERT(VARCHAR,pod.pod_id)	[ID]


	FROM	dbo.tbPurchaseOrderHeader				poh		WITH (NOLOCK)

			INNER JOIN @tmpBranchs tmp
				ON tmp.bra_id			= poh.bra_id

			INNER JOIN dbo.tbPurchaseOrderDetail	pod		WITH (NOLOCK)
				ON  poh.comp_id			= pod.comp_id
				AND poh.bra_id			= pod.bra_id
				AND poh.poh_id			= pod.poh_id

			LEFT JOIN dbo.tbTaxName					tax		WITH (NOLOCK)
				ON  pod.comp_id			= tax.comp_id
				AND pod.tax_id			= tax.tax_id

			INNER JOIN dbo.tbsysCurrency			sc		WITH (NOLOCK)
				ON  pod.curr_id			= sc.curr_id

			INNER JOIN dbo.tbItem					i		WITH (NOLOCK)
				ON  pod.comp_id			= i.comp_id
				AND pod.item_id			= i.item_id

			LEFT JOIN #tmpPOS						pos		WITH (NOLOCK)
				ON	poh.bra_id			= pos.bra_id	AND
					poh.poh_id			= pos.poh_id

			LEFT JOIN tbPurchaseTerms				tpt		WITH (NOLOCK)
				ON	tpt.comp_id			= poh.comp_id	AND
					tpt.pt_id			= poh.pt_id


	where   poh.comp_id				= @comp_id
	--and     poh.bra_id				= @bra_id
	and		poh.supp_id				= @supp_id
	and		pod.pod_isProcessed		= 'False'
	and     (@item_id				= -1		OR	pod.item_id = @item_id)

	AND		poh.poh_id NOT IN (	SELECT	tpoh.poh_id
   									FROM	tbPurchaseOrderHeader	tpoh		WITH (NOLOCK)

   									WHERE	tpoh.comp_id			= poh.comp_id
   									AND		tpoh.bra_id				= poh.bra_id
									AND		tpoh.poh_isEditing		= 'True')

	AND		pod.pod_id NOT IN (	SELECT	tpod.pod_id
   									FROM	tbPurchaseOrderDetail	tpod		WITH (NOLOCK)

   									WHERE	tpod.comp_id			= poh.comp_id
   									AND		tpod.bra_id				= poh.bra_id
   									AND		tpod.pod_isEditing		= 'True')

	AND		pod.pod_id NOT IN (	SELECT	tpod.pod_id
   									FROM	 tbItemTransactionsTmp	tpod		WITH (NOLOCK)
   									WHERE	tpod.comp_id			= poh.comp_id	AND
   											tpod.tis_guid			= @guid	)--		AND
   											--tpod.tis_IsEditing		= 'True')

	ORDER BY pod.comp_id, pod.bra_id, pod.poh_id, pod.pod_id

END

GO







CREATE PROCEDURE [dbo].[spPurchaseOrder_getDataById]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			int,
	@poh_id				int,
	@podt_guid			uniqueidentifier
)
AS

BEGIN



	set nocount on
	-- ------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------
	/*
	declare @comp_id int,
			@bra_id INT,
			@lang_id				int,
			@poh_id					int,
			@podt_guid				uniqueidentifier
	select  @comp_id				=1,
			@bra_id					=1,
			@lang_id				=2,
			@poh_id					=52,
			@podt_guid				='1c3569cb-a508-4a92-b0ba-0ccd0ac83b2b'
	*/
	-- ------------------------------------------------------------


	--Controlar si la orden de compra no esté siendo editado por otro usuario
	IF exists (	select 1
					from dbo.[tbPurchaseOrderHeader] WITH (NOLOCK)
	           		WHERE	comp_id = @comp_id	AND
	           				bra_id	= @bra_id	AND
	           				poh_id	= @poh_id	and
	           				ISNULL([poh_isEditing],'False') = 'False')

		begin
			-- el registro NO ESTÁ tomado por lo tanto recupera el registro seleccionado, lo marca
			-- como tomado y carga todos los registros detalle en la temporal correspondiente


			--recuperar los valores de la cabecera
			exec dbo.[spPurchaseOrderHeader_getDataById] @comp_id,  @bra_id , @lang_id, @poh_id


			-- EWNFERMIO hiujo de re mil repitasssssssssss
			----declare @comp_id int, @bra_id int
			--select @comp_id = comp_id, @bra_id = bra_id
			--	from dbo.[tbPurchaseOrderHeader]
			--	where poh_id = @poh_id

			--actualizar el estado para indicar que el registro está tomado
			--exec dbo.[spPurchaseOrderHeader_updateIsEditing] @comp_id, @bra_id, @poh_id, 'True'


			declare @pricedisc	DECIMAL(19,6)

			-- declaración de variables para obtener los datos del cursor
			declare
				@lcomp_id			int,
				@lbra_id			int,
				@lpoh_id			int,
				@lpod_id			int,
				@litem_id			int,
				@lcurr_id			int,
				@lcont_id			int,
				@lpod_qty			decimal(19,5),
				@lpod_price			decimal(19,6),
				@ltax_id			int,
				@lpod_isprocessed	bit,
				@oberv				NVARCHAR(500),
				@pod_priceB			DECIMAL(19,6),
				@pod_custom			NVARCHAR(50),
				@pod_customNumber	NVARCHAR(50),
				@discount1			DECIMAL(19,6),
				@discount2			DECIMAL(19,6),
				@discount3			DECIMAL(19,6),
				@discount4			DECIMAL(19,6),
				@surcharge1			DECIMAL(19,6),
				@surcharge2			DECIMAL(19,6),
				@surcharge3			DECIMAL(19,6),
				@surcharge4			DECIMAL(19,6),
				@djai_id			int,
				@podt_confirmedQTY	DECIMAL(19,6),
				@podt_initialQTY	DECIMAL(19,6),
				@lrv				INT,
				@simi_id			INT,
				@simid_id			INT,
				@pod_Origin			NVARCHAR(200),
				@pod_From			NVARCHAR(200),
				@pod_Stamp			NVARCHAR(200),
				@pod_LotNumber		NVARCHAR(50),
				@pod_ExpirationDate	DATETIME,
				@pod_includeInAvailableStock		BIT,
				@stor_id							INT


			-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
			declare cursor_PO_gDBI_items CURSOR LOCAL FAST_FORWARD FOR
			select	comp_id,
					bra_id,
					poh_id,
					pod_id,
					item_id,
					curr_id,
					cont_id,
					pod_qty,
					pod_price,
					tax_id,
					pod_isprocessed,
					pod_obs,
					pod_priceB,
					pod_custom,
					pod_customNumber,
					isnull(pod_Discount1,0)		[pod_Discount1],
					isnull(pod_Discount2,0)		[pod_Discount2],
					isnull(pod_Discount3,0)		[pod_Discount3],
					isnull(pod_Discount4,0)		[pod_Discount4],
					ISNULL(pod_surcharge1,0)	[pod_surcharge1],
					ISNULL(pod_surcharge2,0)	[pod_surcharge2],
					ISNULL(pod_surcharge3,0)	[pod_surcharge3],
					ISNULL(pod_surcharge4,0)	[pod_surcharge4],
					djai_id,
					pod_initQty,
					pod_confirmedQTY,
					simi_id,
					simid_id,
					pod_Origin,
					pod_From,
					pod_Stamp,
					pod_LotNumber,
					pod_ExpirationDate,
					ISNULL(pod_includeInAvailableStock,'False')	[pod_includeInAvailableStock],
					stor_id


			from	[tbPurchaseOrderDetail]			WITH (NOLOCK)
			where	comp_id	= @comp_id	AND
					bra_id  = @bra_id	AND
					poh_id	= @poh_id



			open	cursor_PO_gDBI_items

			-- lectura anticipada del cursor
			fetch	cursor_PO_gDBI_items
			into	@lcomp_id,
					@lbra_id,
					@lpoh_id,
					@lpod_id,
					@litem_id,
					@lcurr_id,
					@lcont_id,
					@lpod_qty,
					@lpod_price,
					@ltax_id,
					@lpod_isprocessed,
					@oberv,
					@pod_priceB,
					@pod_custom,
					@pod_customNumber,
					@discount1,
					@discount2,
					@discount3,
					@discount4,
					@surcharge1,
					@surcharge2,
					@surcharge3,
					@surcharge4,
					@djai_id,
					@podt_initialQTY,
					@podt_confirmedQTY,
					@simi_id,
					@simid_id,
					@pod_Origin,
					@pod_From,
					@pod_Stamp,
					@pod_LotNumber,
					@pod_ExpirationDate,
					@pod_includeInAvailableStock,
					@stor_id


			-- se recorre el cursor hasta el fin del mismo
			while   @@fetch_status = 0
			begin

				-- Borra Inserts que previamente quedaron grabados
				DELETE FROM tbPurchaseOrderDetailTmp WHERE pod_id = @lpod_id


				-- por cada registro del cursor se realiza el insert en la *DetailTmp
				exec	dbo.[spPurchaseOrderDetailTmp_insertData]
						@lcomp_id,		@podt_guid,			@litem_id,
						@lcurr_id,		@lbra_id,			@lcont_id,
						@ltax_id,		@lpod_qty,			@lpod_price,	@lpod_isprocessed,
						@oberv,			@pod_priceB,		@pod_custom,	@pod_customNumber,
						@return_value = @lrv OUTPUT

				exec spPurchaseOrderDetailTMP_UpdateDJAIData
					@comp_id	= @comp_id,
					--@guid		= @podt_guid,
					@podt_id	= @lrv,
					@djai_id	= @djai_id

				--Al modificar las PurchaseOrder actualiza los campos insertados en la temporal con los descuentos
				EXEC spPurchaseOrderTmp_updateDiscounts @lcomp_id, @lrv, @discount1, @discount2, @discount3, @discount4, @surcharge1,@surcharge2,@surcharge3,@surcharge4


				-- Calcula el precio con Descuento y Recargo
				SET		@pricedisc = @lpod_price
				set		@pricedisc = @pricedisc * dbo.fnGetFinalDiscountCoeficient( @discount1,	 @discount2,  @discount3,  @discount4)
				set		@pricedisc = @pricedisc * dbo.fnGetFinalDiscountCoeficient(-@surcharge1,-@surcharge2,-@surcharge3,-@surcharge4)


				UPDATE tbpurchaseorderdetailtmp
					SET pod_id							= @lpod_id ,
						podt_confirmedQTY				= @podt_confirmedQTY,
						podt_initQTY					= @podt_initialQTY,
						pod_priceWithDiscountAndCharges = @pricedisc
					WHERE	comp_id = @comp_id and
							podt_id = @lrv

				UPDATE tbpurchaseorderdetailtmp
					SET
						simi_id		= @simi_id,
						simid_id	= @simid_id
					WHERE	comp_id = @comp_id AND
							podt_id = @lrv

				UPDATE tbpurchaseorderdetailtmp
					SET pod_includeInAvailableStock = @pod_includeInAvailableStock

					WHERE	comp_id = @comp_id AND
							podt_id = @lrv

				UPDATE tbpurchaseorderdetailtmp
					SET stor_id		= @stor_id

					WHERE	comp_id = @comp_id AND
							podt_id = @lrv


				-- TICKET 5464 - WALD
				UPDATE tbpurchaseorderdetailtmp
				SET
					pod_Origin			= @pod_Origin,
					pod_From			= @pod_From,
					pod_Stamp			= @pod_Stamp,
					pod_LotNumber		= @pod_LotNumber,
					pod_ExpirationDate	= @pod_ExpirationDate
					WHERE	comp_id		= @comp_id	AND
							podt_id		= @lrv


				-- próxima lectura del cursor
				fetch	cursor_PO_gDBI_items
				into	@lcomp_id,
						@lbra_id,
						@lpoh_id,
						@lpod_id,
						@litem_id,
						@lcurr_id,
						@lcont_id,
						@lpod_qty,
						@lpod_price,
						@ltax_id,
						@lpod_isprocessed,
						@oberv,
						@pod_priceB,
						@pod_custom,
						@pod_customNumber,
						@discount1,
						@discount2,
						@discount3,
						@discount4,
						@surcharge1,
						@surcharge2,
						@surcharge3,
						@surcharge4,
						@djai_id,
						@podt_initialQTY,
						@podt_confirmedQTY,
						@simi_id,
						@simid_id,
						@pod_Origin,
						@pod_From,
						@pod_Stamp,
						@pod_LotNumber,
						@pod_ExpirationDate,
						@pod_includeInAvailableStock,
						@stor_id

			end

			close cursor_PO_gDBI_items
			deallocate cursor_PO_gDBI_items

		end


	else



		begin
			-- el registro ESTÁ tomado por lo tanto retorna sólo los datos de la cabecera

			exec dbo.[spPurchaseOrderHeader_getDataById]   @comp_id , @bra_id , @lang_id,	@poh_id

		end



	-- INserta las cuotas como temporales
	INSERT INTO tbCommercialTransactionsPurchaseLoan
			(	comp_id,
				ctpl_date,
	            ctpl_Total,
	            ctpl_balance,
	            ctpl_payDate,
	            user_id_creator,
	            user_id_payer,
	            ctpl_guid,
	            ctpl_cd,
	            ctpl_paysQTY,
	            ctpl_paysFirstDate,
	            ctpl_payNumber)

		SELECT	tmp.comp_id,
				tmp.ctpl_date,
				tmp.ctpl_Total,
				tmp.ctpl_balance,
				tmp.ctpl_payDate,
				tmp.user_id_creator,
				tmp.user_id_payer,
				@podt_guid,
				tmp.ctpl_cd,
				tmp.ctpl_paysQTY,
				tmp.ctpl_paysFirstDate,
				tmp.ctpl_payNumber
			FROM tbCommercialTransactionsPurchaseLoan tmp
			WHERE	tmp.comp_id = @comp_id	AND
					tmp.bra_id	= @bra_id	AND
					tmp.poh_id	= @poh_id




END
GO



-- Date  : 08/04/2016
-- Author: GA,MOS
-- Desc  : Genrecacion automatica de ordenes de compra / Aplicar filtros
-- sp original [spItem_getDataForPurchaseOrders]


CREATE PROCEDURE [dbo].[spPurchaseOrder_getItems4GenerationAutomatic]
(
		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@user_id			INT,
		@prof_id			INT,

		@guid				UNIQUEIDENTIFIER,
		@pf_id				INT,
		@stor_id			INT,
		@pQuestion			BIT, -- para limpiar la tbPurchaseOrderDetailTmp
		@guidItem			UNIQUEIDENTIFIER
)
as
set nocount on

-----------------------------------------------------------------------------------------------------------
-- TESTING
-----------------------------------------------------------------------------------------------------------
/*
	DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@user_id			INT,
			@prof_id			INT,

			@guid				UNIQUEIDENTIFIER,
			@pf_id				INT,
			@stor_id			INT,
			@guidItem			UNIQUEIDENTIFIER,
			@pQuestion			BIT


	SELECT
			@comp_id			= 1,
			@lang_id			= 1,
			@bra_id				= 1,
			@user_id			= 3,
			@prof_id			= 1,

			@guid				='7cc93967-f5ec-44d4-a5fa-5100fcf0370c',
			@pf_id				= 2,
			@stor_id			=-1,
			@guidItem			='92cca722-f6d4-4517-a014-9b5848370385',
			@pQuestion			='True'

*/
-----------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------


BEGIN



	DECLARE
		@lGuidItem AS UNIQUEIDENTIFIER

	SET
		@lGuidItem = CONVERT(UNIQUEIDENTIFIER,@guidItem)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE
		@tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT
			tcf.sl_id
			FROM tbComplexFilter			tcf
			WHERE tcf.sl_guid		= @lGuidItem     AND
				  tcf.sl_selected	= 'True'
	-- -------------------------------------------------------------



	If @pQuestion = 'True'
	BEGIN

		   DELETE FROM tbPurchaseOrderDetailTmp
		   WHERE	comp_id		= @comp_id
		   AND		podt_guid	= @guid
		   AND		NOT podt_Selection IS NULL



			declare @strQuery	VARCHAR(8000)

			DECLARE @litem_id INT, @lpf_id INT

			DECLARE cursor_items CURSOR  LOCAL FAST_FORWARD FOR

			SELECT
				ti.item_id,
				ti.pf_id
				FROM tbItem								ti	WITH (NOLOCK)

				INNER JOIN @tblComplexFilter_Items		tempITEM
				ON tempitem.item_id	= ti.item_id

				WHERE	ti.comp_id	= @comp_id
				AND		ti.pf_id IS NOT null

			OPEN cursor_items
			FETCH cursor_items INTO @litem_id,
									@lpf_id

			WHILE @@FETCH_STATUS = 0
			BEGIN

				DECLARE @decQty AS DECIMAL(30,6)

				SET @strQuery = ''

				IF	@pf_id > 0
					BEGIN
						SELECT	@strQuery		=   pf_query
							FROM	dbo.tbPurchaseFormula pf	WITH (NOLOCK)
							WHERE	pf.comp_id		= @comp_id
							AND		pf.pf_id		= @pf_id
					END
				ELSE
					BEGIN
						SELECT	@strQuery		=   UPPER(pf_query)
							FROM tbItem ti	WITH (NOLOCK)
							INNER JOIN  dbo.tbPurchaseFormula pf	WITH (NOLOCK)
								ON	pf.comp_id	= ti.comp_id AND
									pf.pf_id	= ti.pf_id
							WHERE	ti.comp_id		= @comp_id
							AND		ti.pf_id		= @lpf_id
							AND     ti.item_id		= @litem_id


					END

				IF @strQuery <> ''
					BEGIN

						SET @strQuery = REPLACE(@strQuery,'LBL_ITEM_ID',	CONVERT(nvarchar(20),@litem_id))
						SET @strQuery = REPLACE(@strQuery,'LBL_LANG_ID',	CONVERT(nvarchar(20),@lang_id))
						SET @strQuery = REPLACE(@strQuery,'LBL_BRA_ID' ,	CONVERT(nvarchar(20),@bra_id))
						SET @strQuery = REPLACE(@strQuery,'LBL_COMP_ID' ,	CONVERT(nvarchar(20),@comp_id))
						SET @strQuery = REPLACE(@strQuery,'LBL_STOR_ID' ,	CONVERT(nvarchar(20),@stor_id))
						SET @strQuery = REPLACE(@strQuery,'LBL_PROF_ID' ,	CONVERT(nvarchar(20),@prof_id))
						SET @strQuery = REPLACE(@strQuery,'LBL_USER_ID' ,	CONVERT(nvarchar(20),@user_id))

						SET @strQuery = REPLACE(@strQuery,'DROP ' ,'')
						SET @strQuery = REPLACE(@strQuery,'DELETE ' ,'')
						SET @strQuery = REPLACE(@strQuery,'INSERT ' ,'')
						SET @strQuery = REPLACE(@strQuery,'ALTER ' ,'')
						SET @strQuery = REPLACE(@strQuery,'EXEC ' ,'')
						SET @strQuery = REPLACE(@strQuery,'TRUNCATE ' ,'')
						SET @strQuery = REPLACE(@strQuery,'DBCC ' ,'')

						DECLARE @tblQTY4Purchase TABLE(decQty DECIMAL(30,6))
							BEGIN TRY
								INSERT	@tblQTY4Purchase
									EXEC(@strQuery)
							END TRY
							BEGIN CATCH
								INSERT	@tblQTY4Purchase VALUES (-999)
							END CATCH

							SELECT  @decQty = tmp.decQty
								FROM @tblQTY4Purchase tmp

							INSERT INTO tbPurchaseOrderDetailTmp
						(
							comp_id,
							podt_guid,
							item_id,
							curr_id,
							bra_id,
							cont_id,
							tax_id,
							podt_qty,
							podt_price,
							podt_cd,
							podt_isProcessed,
							podt_Selection
						)

								SELECT	@comp_id,
										@guid,
										ti.item_id,
										ticl.curr_id,
										@bra_id,
										NULL,
										vitooit.tax_id,
										@decQty,
										CASE CONVERT(BIT, tb2.bra_costlist_type)
											WHEN 'TRUE' THEN ticl.coslis_price
											ELSE ticl.coslis_price_aw
										END,
										GETDATE(),
										'False',
										'False'
								From	tbItem									ti	WITH (NOLOCK)

										LEFT JOIN vwItemTaxesOnlyOneIvaTax vitooit	WITH (NOLOCK)
											ON	vitooit.comp_id = ti.comp_id AND
												vitooit.item_id = ti.item_id

										left join tbBrand						tb	WITH (NOLOCK)
										On  tb.comp_id		=   ti.comp_id
										And tb.brand_id		=   ti.brand_id

										left Join tbCategory					tc	WITH (NOLOCK)
										On  tc.comp_id		=   ti.comp_id
										And tc.cat_id		=   ti.cat_id

										left Join tbSubCategory					tsc	WITH (NOLOCK)
										On  tsc.comp_id		=   ti.comp_id	AND
											tsc.cat_id		=   ti.cat_id	AND
											tsc.subcat_id	=   ti.subcat_id

										left Join tbSupplier					ts	WITH (NOLOCK)
										On  ts.comp_id		=   ti.comp_id	AND
											ts.supp_id		=   ti.supp_id

										INNER JOIN tbBranch tb2	WITH (NOLOCK)
											ON	tb2.comp_id = ti.comp_id	AND
												tb2.bra_id	= @bra_id

										left JOIN tbItemCostList ticl	WITH (NOLOCK)
										ON	ticl.comp_id	= ti.comp_id	AND
											ticl.coslis_id	= tb2.coslis_id	AND
											ticl.item_id	= ti.item_id



								where	ti.comp_id	= @comp_id	AND
										ti.item_id  = @litem_id

					END


				FETCH cursor_items INTO @litem_id,
										@lpf_id



			END
			CLOSE cursor_items
			DEALLOCATE cursor_items



	end


	SELECT	' ' [ ],
			tpodt.podt_Selection,
			ti.item_code,
			ti.item_desc,
			tb.brand_desc,
			tc.cat_desc,
			tsc.subcat_desc,
			ts.supp_name,
			--deposito
			ISNULL(ts2.stor_desc,'') [stor_desc],
			ti.item_cantMin,
			ti.item_cantOpt,
			tpodt.podt_qty		[qty],
			tpodt.item_id

	FROM	tbPurchaseOrderDetailTmp				tpodt	WITH (NOLOCK)

			INNER JOIN tbItem						ti	WITH (NOLOCK)
			ON	ti.comp_id		=	tpodt.comp_id
			AND ti.item_id		=	tpodt.item_id

			left join tbBrand						tb	WITH (NOLOCK)
			On  tb.comp_id		=   ti.comp_id
			And tb.brand_id		=   ti.brand_id

			left Join tbCategory					tc	WITH (NOLOCK)
			On  tc.comp_id		=   ti.comp_id
			And tc.cat_id		=   ti.cat_id

			left Join tbSubCategory					tsc	WITH (NOLOCK)
			On  tsc.comp_id		=   ti.comp_id
			And tsc.cat_id		=   ti.cat_id
			And tsc.subcat_id	=   ti.subcat_id

			left Join tbSupplier					ts	WITH (NOLOCK)
			On  ts.comp_id		=   ti.comp_id
			And ts.supp_id		=   ti.supp_id

			Left Join tbBranch tb2	WITH (NOLOCK)
			On tb2.comp_id		= tpodt.comp_id
			And TB2.bra_id		= tpodt.bra_id

			Left Join tbStorage ts2	WITH (NOLOCK)
			On  ts2.comp_id		= tb2.comp_id
			And ts2.stor_id		= tb2.stor_id



	WHERE	tpodt.comp_id	=	@comp_id
	AND 	tpodt.podt_guid =	@guid
	And		Not tpodt.podt_Selection Is Null





END





GO








--------------------------------
-- ticket number : 1199
-- Desc : detalle de las o.c
-- Subject : wfmSelItem
--------------------------------

CREATE PROCEDURE [dbo].[spPurchaseOrder_getLastData]

(

	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@user_id		INT,
	@item_id		INT



)
AS
SET NOCOUNT ON




BEGIN

------------------------------------------------------------------------
--PARAMETROS DE PRUEBA--
------------------------------------------------------------------------
/*

DECLARE	@comp_id		INT,
		@lang_id		INT,
		@bra_id			INT,
		@prof_id		INT,
		@user_id		INT,
		@item_id		INT




SELECT	@comp_id		=	1,
		@bra_id			=	1,
		@prof_id		=	1,
		@user_id		=	1,
		@lang_id		=   2,
		@item_id		=  257

*/
------------------------------------------------------------------------

------------------------------------------------------------------------


	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )

	INSERT INTO @tblBranchs
	(
		bra_id
	)
	SELECT	bra_id
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.bra_id = @bra_id						OR
				tb.bra_idEnabled4POInselItem = 'True'		-- sino q pongan esto en true y filtren x perfiles, que igual se hace mas abajo


	SELECT top 5	case
						when len(ts.supp_name) > 30 then substring(ts.supp_name,1,30)
						else ts.supp_name
	            	end								[supp_name],
				 tpoh.poh_id,
				 tpoh.poh_estDeliveryDate,
				 pod.pod_qty


	FROM	tbPurchaseOrderHeader						tpoh		WITH (NOLOCK)

			INNER JOIN @tblBranchs							tb
				ON	tb.bra_id	= tpoh.bra_id

			INNER JOIN tbPurchaseOrderDetail				pod		WITH (NOLOCK)
			ON  tpoh.comp_id	= pod.comp_id
			AND tpoh.bra_id		= pod.bra_id
			AND tpoh.poh_id		= pod.poh_id
			AND pod.pod_isProcessed = 'false'

			INNER JOIN tbItem								i		WITH (NOLOCK)
			ON  pod.comp_id		= i.comp_id
			AND pod.item_id		= i.item_id

			INNER JOIN tbSupplier							ts		WITH (NOLOCK)
			ON  ts.comp_id		= tpoh.comp_id
			AND ts.supp_id		= tpoh.supp_id

			INNER JOIN tbUsers4BranchFilter					vubf	WITH (NOLOCK)
				ON	vubf.comp_id						= tpoh.comp_id	AND
					vubf.bra_id							= tpoh.bra_id	AND
					vubf.[user_id]						= @user_id




	where   tpoh.comp_id			= @comp_id
	--and     tpoh.bra_id				= @bra_id
	and     pod.item_id				= @item_id
	and		tpoh.poh_quotation		= 'false' -- Orden de Compra




	order by tpoh.poh_estDeliveryDate












END
GO






CREATE PROCEDURE [dbo].[spPurchaseOrder_getMailData]
(
	@comp_id		INT,
	@bra_id			INT,
	@poh_id			INT,
	@user_id		INT,
	@lang_id		INT
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON


	-- -------------------------------------------
	-- -------------------------------------------
	/*
	DECLARE	@comp_id		INT,
			@bra_id			INT,
			@poh_id			INT,
			@user_id		INT,
			@lang_id		INT
	SELECT	@comp_id		=	1,
			@bra_id			=	1,
			@poh_id			=	93,
			@user_id		=	1,
			@lang_id		=   2
	*/
	-- -------------------------------------------


	SELECT	tb.bra_MainDesc								[comp_desc],
			tc.smtp_host,
			tc.smtp_port,
			tc.smtp_ssc,
			tc.smtp_user,
			tc.smtp_password,
			ISNULL(tu.user_email,'')					[from],
			ISNULL(ts.supp_eMail_PurchaseSector,'')		[to],
			tov.optval_desc								[title]

	FROM	tbCompany									tc

			INNER JOIN tbUser							tu
			ON		tu.[user_id]	=	@user_id

			INNER JOIN tbPurchaseOrderHeader			tpoh
			ON		tpoh.comp_id	=	tc.comp_id
			AND		tpoh.bra_id		=	@bra_id
			AND		tpoh.poh_id		=	@poh_id

			INNER JOIN tbSupplier						ts
			ON		ts.comp_id		=	tpoh.comp_id
			AND		ts.supp_id		=	tpoh.supp_id

			INNER JOIN tbsysOptionsValues				tov
			ON		tov.lang_id		=	@lang_id
			AND		tov.optval_class=	27
			AND		tov.optval_id	=	tpoh.poh_quotation

			INNER JOIN tbBranch tb
				ON	tb.comp_id		= @comp_id AND
					tb.bra_id		= @bra_id


	WHERE	tc.comp_id		=	@comp_id


END
GO


CREATE  PROCEDURE [dbo].[spPurchaseOrder_getReportById]
(
 @comp_id  int,
 @lang_id  int,
 @page_id  int,
 @bra_id   int,
 @poh_id   int,
 @intBranch4Lang INT
)
AS


BEGIN


 set nocount on

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	-- --------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------
	/*
	 declare @comp_id int,
	   @lang_id int,
	   @page_id int,
	   @bra_id  int,
	   @poh_id  int,
	   @intBranch4Lang int

	 select @comp_id =1,
	   @lang_id =2,
	   @page_id =10027,
	   @bra_id  =1,
	   @poh_id  =485

	 drop table #tmpGetTexts
	 drop table #tmpPurchaseOrderHeader
	 drop table #tmpGetTextByControl
	*/
	-- --------------------------------------------------------------------


 DECLARE @supp_id AS INT
 SELECT  @supp_id = tpoh.supp_id
  FROM tbPurchaseOrderHeader tpoh
  WHERE tpoh.comp_id = @comp_id AND
    tpoh.bra_id  = @bra_id AND
    tpoh.poh_id  = @poh_id




 declare @curr_id int
 select @curr_id = curr_id from dbo.[tbBranch] where comp_id = @comp_id and bra_id = @bra_id
 --Select @curr_id



 DECLARE @intCountryId AS INT
 SELECT @intCountryId = tb.country_id
  FROM tbBranch tb
  WHERE tb.comp_id = @comp_id AND
    tb.bra_id = @bra_id



 CREATE TABLE #tmpGetTexts
  (
  t1 int,
  t2 VARCHAR(500),
  t3 int,
  t4 VARCHAR(500),
  t5 int,
  t6 VARCHAR(500),
  t7 int,
  t8 VARCHAR(500),
  t9 VARCHAR(500)
  )

 insert into #tmpGetTexts exec dbo.[spGetTexts] 2,  49, 1,@intCountryId




 CREATE TABLE #tmpPurchaseOrderHeader
  (
  t1      varchar,
  t2      varchar,
  comp_id     int,
  bra_id     int,
  poh_cd     datetime,
  poh_estDeliveryDate  datetime,
  poh_deliveryDate  datetime,
  poh_observation1  varchar(100),
  poh_observation2  varchar(100),
  poh_observation3  varchar(100),
  poh_observation4  varchar(100),
  supp_id     int,
  supp_name    varchar(200),
  poh_quotation   bit,
  optval_desc    varchar(100),
  pt_id     int,
  pt_desc     varchar(50),
  poh_isEditing   bit,
  poh_isEditingCd   datetime,
  ptr_id     int,
  ptr_name    varchar(200),
  pod_isprocessed   INT,
  pod_obs     NVARCHAR(500),
  pod_isUsed    INT,

  poh_ACurrency   INT,
  poh_ACurrencyExchange DECIMAL(19,6),
  poh_Perceptions   DECIMAL(19,6),
  poh_Taxes    DECIMAL(19,6),
  poh_Charges    DECIMAL(19,6),
  CurrIdSupp    INT,

  poh_Discount1   DECIMAL(19,6),
  poh_Discount2   DECIMAL(19,6),
  poh_Discount3   DECIMAL(19,6),
  poh_Discount4   DECIMAL(19,6),
  bra_purchaseOrderNote1 NVARCHAR(400),
  bra_purchaseOrderNote2  NVARCHAR(400),
  supp_Phone1    NVARCHAR(200),
  bra_address    NVARCHAR(100),
  bra_address1   NVARCHAR(100),
  bra_taxNumber   NVARCHAR(50),
  bra_desc    NVARCHAR(200),
  pho_selectedInRecepcion BIT,
  poh_validUp2Date  DATETIME,
  poa_id     INT,
  poa_desc    NVARCHAR(250),
  poa_contactName   NVARCHAR(2000),
  poa_contactEmail  NVARCHAR(1000),
  poa_contactPhone  NVARCHAR(200),
  poa_contactAddress  NVARCHAR(2000),
  poa_contactNote   NVARCHAR(1000),
  simi_id			INT,
  proy_id			INT,
  bra_phone			NVARCHAR(100),
  bra_zip			NVARCHAR(50)

  )


 --recuperar los valores de la cabecera
 --*** REFERENCIA : LPQLP *** ATENCION *** spPurchaseOrderHeader_getDataById
 insert into [#tmpPurchaseOrderHeader]
   exec dbo.[spPurchaseOrderHeader_getDataById] @comp_id, @bra_id, @lang_id, @poh_id


   -- ---------------------------------------------------------------------------------------------
   -- DATOS DEL PROVEEDOR
   -- ---------------------------------------------------------------------------------------------
   DECLARE
   		@supp_annotation	NVARCHAR(4000)
	SELECT
		@supp_annotation = ISNULL(ts.supp_annotation,'')
		FROM tbPurchaseOrderHeader					tpoh	WITH(NOLOCK)
		INNER JOIN tbSupplier						ts		WITH(NOLOCK)
		ON	ts.comp_id			= tpoh.comp_id		AND
			ts.supp_id			= tpoh.supp_id
		WHERE	tpoh.comp_id	= @comp_id			AND
				tpoh.poh_id		= @poh_id
   -- ---------------------------------------------------------------------------------------------

    -- ---------------------------------------------------------------------------------------------
   -- CONDICION DE COMPRA COMO NOTA 3
   -- ---------------------------------------------------------------------------------------------
   DECLARE
   		@bra_purchaseOrderNote3	NVARCHAR(4000)
	SELECT
		@bra_purchaseOrderNote3 = ISNULL(tb.bra_purchaseOrderNote3,'')
		FROM tbBranch			tb						WITH(NOLOCK)
		WHERE	tb.comp_id	= @comp_id			AND
				tb.bra_id	= @bra_id
   -- ---------------------------------------------------------------------------------------------




 select
  --(select t9      from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 29)    [lblTitle]     ,
  (SELECT tov.optval_desc FROM tbsysOptionsValues tov WHERE tov.lang_id = @lang_id AND tov.optval_class = 27
        AND tov.optval_id = (SELECT TOP 1 poh_quotation FROM #tmpPurchaseOrderHeader)  ) [lblTitle],
  (select t9        from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 436)   [lblQuotation]   ,
  (select t9        from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 272)   [lblNumber]    ,
  (@poh_id)                         [lblPurchaseNumber]  ,
  (select TOP 1 [optval_desc]    from [#tmpPurchaseOrderHeader])          [optval_desc]   ,
  (select t9        from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 276)   [lblDate]    ,
  (select TOP 1 [poh_cd]     from [#tmpPurchaseOrderHeader])          [poh_cd]    ,
  (select t9        from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 106)   [lblCurrency]   ,
  (select curr_desc      from [tbsysCurrency]where [curr_id] = @curr_id   )   [curr_desc]    ,
  (select t9        from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 392)   [lblSupplier]   ,
  (select TOP 1 [supp_id]     from [#tmpPurchaseOrderHeader])          [supp_id]    ,
  (select TOP 1 [supp_name]    from [#tmpPurchaseOrderHeader])          [supp_name]    ,
  (select t9        from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 501)   [lblDeliveryDate]  ,
  (select TOP 1 [poh_deliveryDate]  from [#tmpPurchaseOrderHeader])          [poh_deliveryDate]  ,
  (select t9        from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 502)   [lblEstDeliveryDate] ,
  (select TOP 1 [poh_estDeliveryDate]  from [#tmpPurchaseOrderHeader])          [poh_estDeliveryDate] ,
  (select t9        from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 435)   [lblPurchaseTerms]  ,
  (select TOP 1 [pt_desc]     from [#tmpPurchaseOrderHeader])          [pt_desc]    ,
  (select t9        from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 434)   [lblPurchaseTransport] ,
  (select TOP 1 [ptr_name]    from [#tmpPurchaseOrderHeader])          [ptr_name]    ,
  (select t9        from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 503)   [lblObservations]  ,
  (select TOP 1 [poh_observation1]  from [#tmpPurchaseOrderHeader])          [poh_observation1]  ,
  (select TOP 1 [poh_observation2]  from [#tmpPurchaseOrderHeader])          [poh_observation2]  ,
  (select TOP 1 [poh_observation3]  from [#tmpPurchaseOrderHeader])          [poh_observation3]  ,
  (select TOP 1 [poh_observation4]  from [#tmpPurchaseOrderHeader])          [poh_observation4]  ,
  (SELECT TOP 1 [pod_obs]     FROM [#tmpPurchaseOrderHeader])          [pod_obs],
  (SELECT TOP 1 [bra_purchaseOrderNote1] FROM [#tmpPurchaseOrderHeader])          [bra_purchaseOrderNote1],
  (SELECT TOP 1 [bra_purchaseOrderNote2] FROM [#tmpPurchaseOrderHeader])          [bra_purchaseOrderNote2],
  (SELECT TOP 1 [supp_Phone1]    FROM [#tmpPurchaseOrderHeader])          [supp_Phone1],
  (SELECT TOP 1 [bra_address]    FROM [#tmpPurchaseOrderHeader])          [bra_address],
  (SELECT TOP 1 [bra_address1]   FROM [#tmpPurchaseOrderHeader])          [bra_address1],
  (SELECT TOP 1 [bra_taxNumber]   FROM [#tmpPurchaseOrderHeader])          [bra_taxNumber],
  (SELECT TOP 1 [bra_desc]    FROM [#tmpPurchaseOrderHeader])          [bra_desc],
  (SELECT TOP 1 [pho_selectedInRecepcion] FROM [#tmpPurchaseOrderHeader])          [pho_selectedInRecepcion],
  (SELECT TOP 1 [poh_validUp2Date]  FROM [#tmpPurchaseOrderHeader])          [poh_validUp2Date],
  (SELECT TOP 1 [poa_id]     FROM [#tmpPurchaseOrderHeader])          [poa_id],
  (SELECT TOP 1 [poa_desc]    FROM [#tmpPurchaseOrderHeader])          [poa_desc],
  (SELECT TOP 1 [poa_contactName]    FROM [#tmpPurchaseOrderHeader])         [poa_contactName],
  (SELECT TOP 1 [poa_contactEmail]    FROM [#tmpPurchaseOrderHeader])        [poa_contactEmail],
  (SELECT TOP 1 [poa_contactPhone]    FROM [#tmpPurchaseOrderHeader])        [poa_contactPhone],
  (SELECT TOP 1 [poa_contactAddress]    FROM [#tmpPurchaseOrderHeader])        [poa_contactAddress],
  (SELECT TOP 1 [poa_contactNote]    FROM [#tmpPurchaseOrderHeader])         [poa_contactNote],
  (SELECT TOP 1 [simi_id] FROM [#tmpPurchaseOrderHeader]),
  (SELECT TOP 1 [bra_phone]    FROM [#tmpPurchaseOrderHeader])					[bra_phone],
  (SELECT TOP 1 [bra_zip]    FROM [#tmpPurchaseOrderHeader])					[bra_zip],
  @supp_annotation																[supp_annotation],
  @bra_purchaseOrderNote3														[bra_purchaseOrderNote3]



 DECLARE	@poh_ACurrency				INT,
			@poh_ACurrency_Branch			INT,
			@poh_ACurrencyExchange		DECIMAL(19,6)
 --si existe el registro en [#tmpPurchaseOrderHeader] con poh_ACurrency = 0 significa que no está informada esa moneda
 --y debe tomarse la moneda de la sucursal, sino debe tomarse ese poh_ACurrency que es la moneda informada en la OC
 IF EXISTS (SELECT 1 FROM [#tmpPurchaseOrderHeader] WHERE poh_ACurrency = 0)
	  BEGIN
		   SET @poh_ACurrency			= @curr_id --asigno la moneda de la sucursal para hacer los cálculos
		   SET @poh_ACurrency_Branch		= 0
		   SET @poh_ACurrencyExchange	= 0
	  END
 ELSE
	  BEGIN
		   SELECT TOP 1 @poh_ACurrency			= poh_ACurrency			FROM [#tmpPurchaseOrderHeader]
		   SELECT TOP 1 @poh_ACurrency_Branch		= poh_ACurrency			FROM [#tmpPurchaseOrderHeader]
		   SELECT TOP 1 @poh_ACurrencyExchange	= poh_ACurrencyExchange FROM [#tmpPurchaseOrderHeader]
	  END

 SELECT @poh_ACurrency_Branch = tb.curr_id
	FROM tbBranch tb	WITH (NOLOCK)
	WHERE	tb.comp_id = @comp_id AND
			tb.bra_id  = @bra_id


--==
--SELECT '**', @poh_ACurrency, @poh_ACurrency_Branch, @poh_ACurrencyExchange
--SELECT '**99',* FROM [#tmpPurchaseOrderHeader]


-- -----------------------------

-- -----------------------------
	DECLARE @strCurrIdTo	AS nVARCHAR(40)
	DECLARE @strCurrIdFrom	AS nVARCHAR(40)
	DECLARE @strText1		AS NVARCHAR(20)
	DECLARE @strText2		AS NVARCHAR(20)
	DECLARE @decCurrIdTo	AS DECIMAL(19,6)
	DECLARE @leyendacambio	AS NVARCHAR(200)

	SELECT @strCurrIdTo = dbo.fnStrAllTrim(tc.curr_symbol)
		FROM tbsysCurrency tc											WITH (NOLOCK)
		WHERE tc.curr_id = 2

	SELECT @strCurrIdFrom = dbo.fnStrAllTrim(tc.curr_symbol)
		FROM tbsysCurrency tc											WITH (NOLOCK)
		WHERE tc.curr_id = @poh_ACurrency

	SELECT @strText1 = dbo.fnStrAllTrim(tut.utexts_desc)
		FROM tbsysUniqueTexts tut										WITH (NOLOCK)
		WHERE tut.lang_id = @lang_id AND tut.utexts_id = 166

	SELECT @strText2 = dbo.fnStrAllTrim(tut.utexts_desc)
		FROM tbsysUniqueTexts tut										WITH (NOLOCK)
		WHERE tut.lang_id = @lang_id AND tut.utexts_id = 167

	SELECT TOP 1
		@decCurrIdTo	= tce.ce_exchange
		FROM tbCurrencyExchange tce
		WHERE	tce.comp_id		= @comp_id AND
				tce.curr_id_1	= @poh_ACurrency AND
				tce.curr_id_2	= 2
		ORDER BY tce.ce_lastUpdate DESC

	--SELECT @strText1, @strText2

--TIPO DE CAMBIO A MONEDA DOLAR
SELECT
	@leyendacambio = @strText1 + ' ' + CONVERT(NVARCHAR ,CONVERT(DECIMAL(18,4),@decCurrIdTo)) + ' ' + @strCurrIdFrom + ' ' + @strText2 + ' ' + @strCurrIdTo
-- -----------------------------




 SELECT  i.item_code    [d_item_code],
   i.[item_desc]   [d_item_desc],

   convert(decimal(19,2),round(pod.pod_qty,2)) [pod_qty],
   convert(decimal(19,4),round(ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),4))[pod_price],
   --ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),

   convert(decimal(19,2),isnull(round((pod.pod_qty * ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price)),2),0)) [subtotal],



   --convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False')),2),0))
   --        [subtotal_branch_curr],
   convert(decimal(19,2),
    isnull(
     round(
      (
      	dbo.fnGetExchange2(	@comp_id,
      						pod.pod_qty * ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),
							pod.curr_id,
							@poh_ACurrency_Branch,
							@poh_ACurrency,
							@poh_ACurrency_Branch,
							@poh_ACurrencyExchange,
							'False')
      ),2),0))
                 [subtotal_branch_curr],




   --convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') *
   --dbo.fnGetTaxPercentage (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0,NULL) / 100 ),2),0))
   --        [tax_branch_curr],
   convert(decimal(19,2),
    isnull(
     round(
      (dbo.[fnGetExchange2](	@comp_id,
								pod.pod_qty * ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),
								pod.curr_id,
								@poh_ACurrency_Branch,
								@poh_ACurrency,
								@poh_ACurrency_Branch,
								@poh_ACurrencyExchange,
								'False'
							) *
      dbo.fnGetTaxPercentage4Suppliers (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0, @supp_id /*NULL*/ ) / 100 ),2),0))
                 [tax_branch_curr],



   --convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') +
   --(dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') *
   -- dbo.fnGetTaxPercentage (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0,NULL) / 100)),2),0))
   --        [total_branch_curr],
   convert(decimal(19,2),
    isnull(
     round(
      (dbo.[fnGetExchange2](	@comp_id,
								pod.pod_qty * ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),
								pod.curr_id,
								@poh_ACurrency_Branch,
								@poh_ACurrency,
								@poh_ACurrency_Branch,
								@poh_ACurrencyExchange,
								'False'
							) +
      (dbo.[fnGetExchange2](	@comp_id,
								pod.pod_qty * ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),
								pod.curr_id,
								@poh_ACurrency,
								@poh_ACurrency,
								@poh_ACurrency_Branch,
								@poh_ACurrencyExchange,
								'False'
							) *
      dbo.fnGetTaxPercentage4Suppliers (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0,@supp_id /*NULL*/) / 100)),2),0))
                 [total_branch_curr],



   isnull(ct.[cont_desc],'') [cont_desc],
   isnull(t.[tax_desc],'')  [tax_desc],
   isnull(i.[item_upb],0)  [item_upb],
   isnull(i.[item_upp],0)  [item_upp],
   pod.pod_obs     [pod_obs],
   i.item_vendorCode,
   i.item_guarantee,
   CASE
    WHEN pod.pod_isProcessed = 'True' THEN
     (SELECT
      tut.utexts_desc
      FROM tbsysUniqueTexts tut
      WHERE tut.lang_id   = @lang_id and
        tut.utexts_id = 40132)
    ELSE
     ''
    END      [pod_isProcessed],
    ISNULL(CONVERT(VARCHAR,i.item_large),'')															[item_large],
    ISNULL(tmu.mu_shortDesc,'')																			[mu_shortDesc],
    CONVERT(DECIMAL(19,2),dbo.fnGetExchange2(	pod.comp_id,
												1,
												pod.curr_id,
												@poh_ACurrency,
												@poh_ACurrency,
												@poh_ACurrency_Branch,
												@poh_ACurrencyExchange,
												'false'
											))	[Exchange],
	c.curr_symbol,
	tb.brand_desc,
	pod.pod_customNumber,
	dbo.fnStrAllTrim(ISNULL(tis.itemsupp_CODE, ' ')) [itemsupp_CODE]



 from [tbPurchaseOrderDetail]					pod

   left join dbo.[tbItem]						i
   on i.[comp_id]  = pod.[comp_id]
   and i.[item_id]  = pod.[item_id]

    LEFT JOIN tbItemSupplier AS					tis
	ON tis.comp_id	= pod.comp_id	AND
      tis.item_id	= i.item_id		AND
      tis.supp_id	= @supp_id

   left join dbo.[tbsysCurrency]  c
   on c.[curr_id]  = pod.[curr_id]

   left join dbo.[tbContainer]   ct
   on ct.[comp_id] = pod.[comp_id]
   and ct.[bra_id]  = pod.[bra_id]
   and ct.[cont_id] = pod.[cont_id]

   left join dbo.[tbTaxName]   t
   on t.[comp_id]  = pod.[comp_id]
   and t.[tax_id]  = pod.[tax_id]

   LEFT JOIN tbMetricUnits		tmu
   ON	tmu.comp_id = i.comp_id AND
		tmu.mu_id	= i.mu_id

   LEFT JOIN tbBrand			tb
   ON	tb.comp_id	= i.comp_id AND
		tb.brand_id = i.brand_id


 where pod.[comp_id]  = @comp_id
 and  pod.[bra_id]  = @bra_id
 and  pod.poh_id   = @poh_id

 ORDER BY i.item_desc ASC







	 select
	--   sum(convert(decimal(19,2),round(pod.pod_qty,2)))
	--   [pod_qty],

	   ''
	   [pod_qty],

	   --sum(convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id ,  @curr_id , 0, 0, 'False')),2),0)))
	   --[subtotal],
	   sum(
		convert(decimal(19,2),
		 isnull(
		  round(
		   (dbo.fnGetExchange2(	@comp_id,
								pod.pod_qty * ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),
								pod.curr_id,
								@poh_ACurrency,
								@poh_ACurrency,
								@poh_ACurrency_Branch,
								@poh_ACurrencyExchange,
								'False'
							  )
		   ),2),0)))
					 [subtotal],



	   --sum(convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id ,  @curr_id , 0, 0, 'False')),2),0)))
	   --[subtotal_branch_curr],
	   sum(
		convert(decimal(19,2),
		 isnull(
		  round(
		   (dbo.[fnGetExchange2](	@comp_id,
									pod.pod_qty * ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),
									pod.curr_id,
									@poh_ACurrency,
									@poh_ACurrency,
									@poh_ACurrency_Branch,
									@poh_ACurrencyExchange,
									'False'
								)),2),0)))
					 [subtotal_branch_curr],




	   --sum(convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') *
	   --dbo.fnGetTaxPercentage (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0,NULL) / 100 ),2),0)))
	   --[tax_branch_curr],
	   sum(
		convert(decimal(19,2),
		 isnull(
		  round(
		   (dbo.fnGetExchange2(@comp_id,
				pod.pod_qty * ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),
				pod.curr_id,
				@poh_ACurrency,
				@poh_ACurrency,
				@poh_ACurrency_Branch,
				@poh_ACurrencyExchange,
				'False') *
				dbo.fnGetTaxPercentage4Suppliers (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0,@supp_id /*NULL*/) / 100 ),2),0)))
										 [tax_branch_curr],


	   --sum(convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') +
	   --(dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') *
	   -- dbo.fnGetTaxPercentage (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0,NULL) / 100)),2),0)))
	   --[total_branch_curr],
	   sum(
		convert(decimal(19,2),
		 isnull(
		  round(
		   (dbo.[fnGetExchange2]( @comp_id,
				 pod.pod_qty * ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),
				 pod.curr_id,
				 @poh_ACurrency,
 				 @poh_ACurrency,
				 @poh_ACurrency_Branch,
				 @poh_ACurrencyExchange,
				 'False') +
		   (dbo.[fnGetExchange2]( @comp_id,
				 pod.pod_qty * ISNULL(pod.pod_priceWithDiscountAndCharges,pod.pod_price),
				 pod.curr_id,
				 @poh_ACurrency,
				 @poh_ACurrency,
				 @poh_ACurrency_Branch,
				 @poh_ACurrencyExchange,
				 'False') *
				dbo.fnGetTaxPercentage4Suppliers ( @comp_id,
						 pod.bra_id,
						 pod.tax_id,
						 0,
						 0,
						 0,
						 0,
						 @supp_id /*NULL*/) / 100)),2),0)))
								[total_branch_curr],

	   isnull(sum(pod.pod_qty/(dbo.fnNoZDiv(isnull(i.[item_upb],0)))),0)  [item_upb],
	   -- ticket 2364 --isnull(sum(i.[item_upb]),0)   [item_upb],
	   isnull(sum(pod.pod_qty/(dbo.fnNoZDiv(isnull(i.[item_upp],0)))),0)  [item_upp],
	   --isnull(sum(i.[item_upp]),0)   [item_upp],

	   ''         [curr_desc1],
	   ''         [curr_symbol1],

	   isnull(tc2.curr_desc,'')   [curr_desc_branch],
	   isnull(tc2.curr_symbol,'')   [curr_symbol_branch],

	   ''         [curr_descPO],
	   ''         [curr_symboPO],

	   (SELECT TOP 1 [poh_Perceptions] FROM [#tmpPurchaseOrderHeader]) [poh_Perceptions],
	   (SELECT TOP 1 [poh_Taxes]  FROM [#tmpPurchaseOrderHeader]) [poh_Taxes],
	   (SELECT TOP 1 [poh_Charges]  FROM [#tmpPurchaseOrderHeader]) [poh_Charges],
	   @leyendacambio												[Leyenda]



	 from dbo.tbPurchaseOrderDetail   pod

	   left join tbItem     i
	   on i.comp_id  = pod.comp_id
	   and i.[item_id]  = pod.[item_id]

	   ---agregué la moneda del item
	   left Join tbsysCurrency tc
	   On tc.curr_id       = pod.curr_id

	   left Join tbsysCurrency tc2
	   On tc2.curr_id  = @poh_ACurrency

	 where	  pod.[comp_id]		= @comp_id
		 and  pod.[bra_id]		= @bra_id
		 and  pod.poh_id	= @poh_id
	 group by
	   tc2.curr_desc,
	   tc2.curr_symbol






 CREATE TABLE #tmpGetTextByControl
  (
  t1      int,
  t2      varchar(100),
  t3      int,
  t4      varchar(100),
  t5      int,
  t6      varchar(100),
  t7      int,
  t8      varchar(100),
  text_desc    varchar(200)
  )



 --recuperar los valores de la cabecera
 insert into [#tmpGetTextByControl] exec dbo.[spGetTexts_byControl] 2,  49, 12, 1


 select (SELECT TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 77)  [item_code]    ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 78)  [item_desc]    ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 513)  [podt_qty]    ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 514)  [podt_price]   ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 515)  [subtotal]    ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 516)  [subtotal_branch_curr] ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 517)  [tax_branch_curr]  ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 518)  [total_branch_curr]  ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 519)  [cont_desc]    ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 520)  [tax_desc]    ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 1356) [pod_obs]    ,
   (select TOP 1 text_desc from [#tmpGetTextByControl] where t3 = 1728) [item_guarantee]

-- select * from #tmpGetTextByControl order by t3

 exec [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id, @page_id





 -- --------------------------------------------------
 -- /*:::::: Subreporte - tbPurchaseOrderDeliveryAllocation ::::::*/


 -- SELECT  isnull(tpoda.poa_desc,'')     [poa_desc],
 --   isnull(tpoda.poa_contactName,'')   [poa_contactName],
 --   isnull(tpoda.poa_contactEmail,'')   [poa_contactEmail],
 --   isnull(tpoda.poa_contactPhone,'')   [poa_contactPhone],
 --   isnull(tpoda.poa_contactAddress,'')   [poa_contactAddress],
 --   isnull(tpoda.poa_contactNote,'')   [poa_contactNote]


 -- FROM tbPurchaseOrderDeliveryAllocation          tpoda  WITH (NOLOCK)


 -- INNER JOIN tbPurchaseOrderHeader           tpoh  WITH (NOLOCK)
 -- ON tpoh.comp_id = tpoda.comp_id  AND
 --  tpoh.poa_id  = tpoda.poa_id


 -- WHERE tpoda.comp_id = @comp_id
