CREATE  PROCEDURE [dbo].[spPurchaseOrder_getReportById2]
(
	@comp_id	int,
	@lang_id	int,
	@page_id	int,
	@bra_id		int,
	@poh_id		int,
	@intBranch4Lang	int
)
AS



BEGIN


	set nocount on

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

-- --------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------
/*
	declare	@comp_id	int,
			@lang_id	int,
			@page_id	int,
			@bra_id		int,
			@poh_id		int

	select	@comp_id	=1,
			@lang_id	=2,
			@page_id	=10076,
			@bra_id		=1,
			@poh_id		=159
	drop table #tmpGetTexts
	drop table #tmpPurchaseOrderHeader
	drop table #tmpGetTextByControl
*/
-- --------------------------------------------------------------------


-- - ------------------------------------------------------------------------------------------
-- Carga la moneda de la Sucursal
-- - ------------------------------------------------------------------------------------------
	declare @curr_id int
	select @curr_id	= curr_id from dbo.[tbBranch] where comp_id = @comp_id and bra_id = @bra_id
	--Select @curr_id
-- - ------------------------------------------------------------------------------------------



	DECLARE @intCountryId AS INT
	SELECT @intCountryId = tb.country_id
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id



-- - ------------------------------------------------------------------------------------------
-- Carga las temporales con los Textos y con los datos de la PurchaseOrderHeader con el ID recibido
-- - ------------------------------------------------------------------------------------------
	CREATE TABLE #tmpGetTexts
		(
		t1 int,
		t2 VARCHAR(255),
		t3 int,
		t4 VARCHAR(255),
		t5 int,
		t6 VARCHAR(255),
		t7 int,
		t8 VARCHAR(255),
		t9 VARCHAR(255)
		)

	insert into #tmpGetTexts exec dbo.[spGetTexts] 2,  49, 1,@intCountryId




	--CREATE TABLE #tmpPurchaseOrderHeader
	--	(
	--	t1						varchar,
	--	t2						varchar,
	--	comp_id					int,
	--	bra_id					int,
	--	poh_cd					datetime,
	--	poh_estDeliveryDate		datetime,
	--	poh_deliveryDate		datetime,
	--	poh_observation1		varchar(100),
	--	poh_observation2		varchar(100),
	--	poh_observation3		varchar(100),
	--	poh_observation4		varchar(100),
	--	supp_id					int,
	--	supp_name				varchar(200),
	--	poh_quotation			bit,
	--	optval_desc				varchar(100),
	--	pt_id					int,
	--	pt_desc					varchar(50),
	--	poh_isEditing			bit,
	--	poh_isEditingCd			datetime,
	--	ptr_id					int,
	--	ptr_name				varchar(200),
	--	pod_isprocessed			INT,
	--	pod_obs					NVARCHAR(500),
	--	pod_isUsed				INT
	--	)

CREATE TABLE #tmpPurchaseOrderHeader
  (
  t1      varchar,
  t2      varchar,
  comp_id     int,
  bra_id     int,
  poh_cd     datetime,
  poh_estDeliveryDate  datetime,
  poh_deliveryDate  datetime,
  poh_observation1  varchar(100),
  poh_observation2  varchar(100),
  poh_observation3  varchar(100),
  poh_observation4  varchar(100),
  supp_id     int,
  supp_name    varchar(200),
  poh_quotation   bit,
  optval_desc    varchar(100),
  pt_id     int,
  pt_desc     varchar(50),
  poh_isEditing   bit,
  poh_isEditingCd   datetime,
  ptr_id     int,
  ptr_name    varchar(200),
  pod_isprocessed   INT,
  pod_obs     NVARCHAR(500),
  pod_isUsed    INT,

  poh_ACurrency   INT,
  poh_ACurrencyExchange DECIMAL(19,6),
  poh_Perceptions   DECIMAL(19,6),
  poh_Taxes    DECIMAL(19,6),
  poh_Charges    DECIMAL(19,6),
  CurrIdSupp    INT,

  poh_Discount1   DECIMAL(19,6),
  poh_Discount2   DECIMAL(19,6),
  poh_Discount3   DECIMAL(19,6),
  poh_Discount4   DECIMAL(19,6),
  bra_purchaseOrderNote1 NVARCHAR(400),
  bra_purchaseOrderNote2  NVARCHAR(400),
  supp_Phone1    NVARCHAR(200),
  bra_address    NVARCHAR(100),
  bra_address1   NVARCHAR(100),
  bra_taxNumber   NVARCHAR(50),
  bra_desc    NVARCHAR(200),
  pho_selectedInRecepcion BIT,
  poh_validUp2Date  DATETIME,
  poa_id     INT,
  poa_desc    NVARCHAR(250),
  poa_contactName   NVARCHAR(2000),
  poa_contactEmail  NVARCHAR(1000),
  poa_contactPhone  NVARCHAR(200),
  poa_contactAddress  NVARCHAR(2000),
  poa_contactNote   NVARCHAR(1000),
  simi_id		INT,
  proy_id		INT

  )

	insert into [#tmpPurchaseOrderHeader]
			exec dbo.[spPurchaseOrderHeader_getDataById] @comp_id, @bra_id, @lang_id,  @poh_id

	--SELECT * FROM #tmpPurchaseOrderHeader
	--select * from [#tmpPurchaseOrderHeader]
-- - -----------------------------------------------------------------------------------------




	select
			i.item_code																[d_item_code],
			i.[item_desc]															[d_item_desc],
			convert(decimal(19,2),round(pod.pod_qty,2))								[pod_qty],
			pod.pod_price,

			convert(decimal(19,2),isnull(round((pod.pod_qty * pod.pod_price),2),0)) [subtotal],

			convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False')),2),0))
																					[subtotal_branch_curr],

			convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') *
			dbo.fnGetTaxPercentage4Suppliers (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0,NULL) / 100 ),2),0))
																					[tax_branch_curr],

			convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') +
			(dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') *
				dbo.fnGetTaxPercentage4Suppliers (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0,NULL) / 100)),2),0))
																					[total_branch_curr],

			isnull(ct.[cont_desc],'')												[cont_desc],
			isnull(t.[tax_desc],'')													[tax_desc],
			isnull(i.[item_upb],0)													[item_upb],
			isnull(i.[item_upp],0)													[item_upp],
			pod.pod_obs																[pod_obs],
			i.item_vendorCode

	from	[tbPurchaseOrderDetail]				pod

			left join dbo.[tbItem]				i
			on	i.[comp_id]		=	pod.[comp_id]
			and	i.[item_id]		=	pod.[item_id]

			left join dbo.[tbsysCurrency]		c
			on	c.[curr_id]		=	pod.[curr_id]

			left join dbo.[tbContainer]			ct
			on	ct.[comp_id]	=	pod.[comp_id]
			and	ct.[bra_id]		=	pod.[bra_id]
			and	ct.[cont_id]	=	pod.[cont_id]

			left join dbo.[tbTaxName]			t
			on	t.[comp_id]		=	pod.[comp_id]
			and	t.[tax_id]		=	pod.[tax_id]

	where	pod.[comp_id]		=	@comp_id
	and		pod.[bra_id]		=	@bra_id
	and		pod.poh_id			=	@poh_id


	CREATE TABLE #tmpGetTextByControl
		(
		t1						int,
		t2						varchar(100),
		t3						int,
		t4						varchar(100),
		t5						int,
		t6						varchar(100),
		t7						int,
		t8						varchar(100),
		text_desc				varchar(200)
		)


	--recuperar los valores de la cabecera
	insert into [#tmpGetTextByControl] exec dbo.[spGetTexts_byControl] 2,  49, 12, 1

	-- - ----------------------------------------------------------------------------------------------------------------------------------------
--   Aca se recuperan todos los datos para la cabecera del Reporte (Titulos específicos)
-- - ----------------------------------------------------------------------------------------------------------------------------------------

	select
	(SELECT tov.optval_desc				FROM tbsysOptionsValues tov WHERE tov.lang_id = @lang_id AND tov.optval_class = 27
										AND tov.optval_id = (SELECT TOP 1 poh_quotation FROM #tmpPurchaseOrderHeader)  )	[lblTitle],
	(select t9							from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 436)							[lblQuotation]			,
	(select t9							from [#tmpGetTexts]	where t5 = 1 and t7 = 1 and t3 = 272)							[lblNumber] 			,
	(@poh_id)																												[lblPurchaseNumber]		,
	(select TOP 1 [optval_desc]			from [#tmpPurchaseOrderHeader])														[optval_desc]			,
	(select t9							from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 276)							[lblDate]				,
	(select TOP 1 [poh_cd]				from [#tmpPurchaseOrderHeader])														[poh_cd]				,
	(select t9							from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 106)							[lblCurrency]			,
	(select curr_desc					from [tbsysCurrency]where [curr_id] = @curr_id			)							[curr_desc]				,
	(select t9							from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 392)							[lblSupplier]			,
	(select TOP 1 [supp_id]				from [#tmpPurchaseOrderHeader])														[supp_id]				,
	(select TOP 1 [supp_name]			from [#tmpPurchaseOrderHeader])														[supp_name]				,
	(select t9							from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 501)							[lblDeliveryDate]		,
	(select TOP 1 [poh_deliveryDate]	from [#tmpPurchaseOrderHeader])														[poh_deliveryDate]		,
	(select t9							from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 502)							[lblEstDeliveryDate]	,
	(select TOP 1 [poh_estDeliveryDate]	from [#tmpPurchaseOrderHeader])														[poh_estDeliveryDate]	,
	(select t9							from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 435)							[lblPurchaseTerms]		,
	(select TOP 1 [pt_desc]				from [#tmpPurchaseOrderHeader])														[pt_desc]				,
	(select t9							from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 434)							[lblPurchaseTransport]	,
	(select TOP 1 [ptr_name]			from [#tmpPurchaseOrderHeader])														[ptr_name]				,
	(select t9							from [#tmpGetTexts] where t5 = 1 and t7 = 1 and t3 = 503)							[lblObservations]		,
	(select TOP 1 [poh_observation1]	from [#tmpPurchaseOrderHeader])														[poh_observation1]		,
	(select TOP 1 [poh_observation2]	from [#tmpPurchaseOrderHeader])														[poh_observation2]		,
	(select TOP 1 [poh_observation3]	from [#tmpPurchaseOrderHeader])														[poh_observation3]		,
	(select TOP 1 [poh_observation4]	from [#tmpPurchaseOrderHeader])														[poh_observation4]		,
	(SELECT TOP 1 [pod_obs]				FROM [#tmpPurchaseOrderHeader])														[pod_obs]

-- - ----------------------------------------------------------------------------------------------------------------------------------------


select		(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 77)	[item_code]				,
			(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 78)	[item_desc]				,
			(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 513)	[podt_qty]				,
			(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 514)	[podt_price]			,
			(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 515)	[subtotal]				,
			(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 516)	[subtotal_branch_curr]	,
			(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 517)	[tax_branch_curr]		,
			(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 518)	[total_branch_curr]		,
			(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 519)	[cont_desc]				,
			(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 520)	[tax_desc],
			(select TOP 1 text_desc	from [#tmpGetTextByControl]	where t3 = 1356)[pod_obs]

-- - ----------------------------------------------------------------------------------------------------------------------------------------
--   Aca se recuperan las sumatorias y las monedas de los datos del cuerpo principal del reporte
-- - ----------------------------------------------------------------------------------------------------------------------------------------

	select	sum(convert(decimal(19,2),round(pod.pod_qty,2)))
												[pod_qty],

			sum(convert(decimal(19,2),isnull(round((pod.pod_qty * pod.pod_price),2),0)))
												[subtotal],

			sum(convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False')),2),0)))
												[subtotal_branch_curr],

			sum(convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') *
			dbo.fnGetTaxPercentage4Suppliers (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0,NULL) / 100 ),2),0)))
												[tax_branch_curr],

			sum(convert(decimal(19,2),isnull(round((dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') +
			(dbo.[fnGetExchange](@comp_id, pod.pod_qty * pod.pod_price, pod.curr_id, @curr_id , 0, 0, 'False') *
				dbo.fnGetTaxPercentage4Suppliers (@comp_id, pod.bra_id, pod.tax_id,0,0,0,0,NULL) / 100)),2),0)))
												[total_branch_curr],

			isnull(sum(i.[item_upb]),0)			[item_upb],
			isnull(sum(i.[item_upp]),0)			[item_upp],

			isnull(tc2.curr_desc,'')			[curr_desc1],
			isnull(tc2.curr_symbol,'')			[curr_symbol1],

			isnull(tc2.curr_desc,'')			[curr_desc_branch],
			isnull(tc2.curr_symbol,'')			[curr_symbol_branch],

			isnull(tc.curr_desc,'')				[curr_descPO],
			isnull(tc.curr_symbol,'')			[curr_symboPO]

	from	dbo.tbPurchaseOrderDetail			pod

			left join dbo.[tbItem]				i
			on	i.comp_id		= pod.comp_id
			and	i.[item_id]		= pod.[item_id]


			---agregué la moneada del item
			left Join tbsysCurrency tc
			On tc.curr_id       = pod.curr_id

			left Join tbsysCurrency tc2
			On tc2.curr_id       = @curr_id

	where	pod.[comp_id]		=	@comp_id
	and		pod.[bra_id]		=	@bra_id
	and		pod.poh_id			=	@poh_id

	group by
			tc2.curr_desc,
			tc2.curr_symbol,
			tc.curr_desc,
			tc.curr_symbol
-- - ----------------------------------------------------------------------------------------------------------------------------------------


	exec [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id, @page_id





END
GO







create PROCEDURE [dbo].[spPurchaseOrder_HeaderandDetail_DeleteData]
(
	@comp_id				INT,
	@por_id					INT
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*
		  DECLARE
  			@comp_id				int,
  			@por_id					int

		  SELECT
  			@comp_id				= 1,
  			@por_id					= 179
*/
		-- --------------------------------------------------------------------------

		DELETE

		FROM tbPurchaseorderReceptionDetail

		WHERE	comp_id			= @comp_id	AND
				por_id			= @por_id


		DELETE

		FROM tbPurchaseorderReceptionHeader

		WHERE	comp_id			= @comp_id	AND
				por_id			= @por_id






END

GO







CREATE PROCEDURE [dbo].[spPurchaseOrder_insertData]
(
		@podt_guid					uniqueidentifier,
		@comp_id					int,
		@bra_id						int,
		@poh_id						int,
		@poh_estDeliveryDate		datetime,
		@poh_deliveryDate			datetime,
		@poh_observation1			varchar(100),
		@poh_observation2			varchar(100),
		@poh_observation3			varchar(100),
		@poh_observation4			varchar(100),
		@supp_id					int,
		@poh_quotation				bit,
		@pt_id						int,
		@ptr_id						int,
		@poh_ACurrency				INT,
		@poh_ACurrencyExchange		DECIMAL(19,6),
		@poh_Perceptions			DECIMAL(19,6),
		@poh_Taxes					DECIMAL(19,6),
		@poh_Charges				DECIMAL(19,6),
		@return_value				int output
)
AS
SET NOCOUNT ON



	-- ---------------------------------------------------------------
	-- Test
	-- ---------------------------------------------------------------
	/*

	--ver como recuperamos el valor correspondiente
	declare
			@podt_guid					uniqueidentifier,
			@comp_id					int,
			@bra_id						int,
			@poh_id						int,
			@poh_estDeliveryDate		datetime,
			@poh_deliveryDate			datetime,
			@poh_observation1			varchar(100),
			@poh_observation2			varchar(100),
			@poh_observation3			varchar(100),
			@poh_observation4			varchar(100),
			@supp_id					int,
			@poh_quotation				bit,
			@pt_id						int,
			@ptr_id						int,
			@return_value				int

	select  @podt_guid					= 'f77b5ec8-90ff-4fc8-9bb7-ee4324e31323',
			@comp_id					= 1,
			@bra_id						= 1,
			@poh_id						= 1,
			@poh_estDeliveryDate		= getdate (),
			@poh_deliveryDate			= getdate (),
			@poh_observation1			= 'asdasd',
			@poh_observation2			= 'asdas asdasdd',
			@poh_observation3			= 'asdasd  asdasdsad',
			@poh_observation4			= 'asdasd  saasdas asdasd asdasdas',
			@supp_id					=74,
			@poh_quotation				='False',
			@pt_id						=5,
			@ptr_id						=1

	--declare @lpoh_id		int


	*/
	-- ---------------------------------------------------------------



BEGIN TRANSACTION
BEGIN TRY

IF @ptr_id = -1
	BEGIN
		SET @ptr_id = NULL
	END


-- insertar datos en el Header
EXEC	dbo.[spPurchaseOrderHeader_insertData]
			@comp_id,				@bra_id,				@poh_id,
			@poh_estDeliveryDate,	@poh_deliveryDate,		@poh_observation1,
			@poh_observation2,		@poh_observation3,		@poh_observation4,
			@supp_id,				@poh_quotation,			@pt_id,
			@ptr_id,				@poh_ACurrency,			@poh_ACurrencyExchange,
			@poh_Perceptions,		@poh_Taxes,				@poh_Charges




IF @@ERROR = 0 and @@ROWCOUNT = 1
BEGIN





		/*****************************************************************************************/
		/*Agregado de los estados a verificar por la órden de compra                             */
		/*****************************************************************************************/
		INSERT	INTO	tbPurchaseOrderState
		(		comp_id,		bra_id,		poh_id,		poc_id,			pos_ok		)
		SELECT	tposc.comp_id,	@bra_id,	@poh_id,	tposc.poc_id,	'False'
		FROM	tbPurchaseOrderStateConcept		tposc
		WHERE	tposc.comp_id	=	@comp_id
		/*****************************************************************************************/




		-- declaración de variables para obtener los datos del cursor
		DECLARE @lcomp_id				int,
				@lpodt_guid				uniqueidentifier,
				@lpodt_id				int,
				@litem_id				int,
				@lcurr_id				int,
				@lbra_id				int,
				@lcont_id				int,
				@ltax_id				int,
				@lpodt_qty				decimal(19, 5),
				@lpodt_price			decimal(19, 6),
				@lrv					INT,
				@obser					NVARCHAR(500),
				@priceB					DECIMAL(16,5),
				@custom					VARCHAR(50),
				@customNumber			VARCHAR(50),
				@discount1				DECIMAL(19,6),
				@discount2				DECIMAL(19,6),
				@discount3				DECIMAL(19,6),
				@discount4				DECIMAL(19,6),
				@djai_id				INT,
				@surcharge1				DECIMAL(19,6),
				@surcharge2				DECIMAL(19,6),
				@surcharge3				DECIMAL(19,6),
				@surcharge4				DECIMAL(19,6),
				@simi_id				INT,
				@simid_id				INT,
				@pod_Origin				NVARCHAR(200),
				@pod_From				NVARCHAR(200),
				@pod_Stamp				NVARCHAR(200),
				@pod_LotNumber			NVARCHAR(50),
				@pod_ExpirationDate					DATETIME,
				@pod_priceWithDiscountAndCharges	DECIMAL(19,6),
				@pod_includeInAvailableStock		BIT,
				@stor_id							INT



		-- declaración del cursor para obtener los datos de la tabla detalle temporal
		declare cursor_PO_iD_items CURSOR LOCAL FAST_FORWARD FOR

		select	comp_id,
				podt_guid,
				podt_id,
				item_id,
				curr_id,
				bra_id,
				cont_id,
				tax_id,
				podt_qty,
				podt_price,
				podt_obs,
				podt_priceB,
				podt_custom,
				podt_customNumber,
				pod_Discount1,
				pod_Discount2,
				pod_Discount3,
				pod_Discount4,
				djai_id,
				ISNULL(pod_surcharge1,0)	[pod_surcharge1],
				ISNULL(pod_surcharge2,0)	[pod_surcharge2],
				ISNULL(pod_surcharge3,0)	[pod_surcharge3],
				ISNULL(pod_surcharge4,0)	[pod_surcharge4],
				simi_id,
				simid_id,
				pod_Origin,
				pod_From,
				pod_Stamp,
				pod_LotNumber,
				pod_ExpirationDate,
				pod_priceWithDiscountAndCharges,
				pod_includeInAvailableStock,
				stor_id

		from	dbo.[tbPurchaseOrderDetailTmp]	WITH (NOLOCK)
		where	[podt_guid] = @podt_guid


		open	cursor_PO_iD_items


		-- lectura anticipada del cursor
		fetch	cursor_PO_iD_items
		into	@lcomp_id,
				@lpodt_guid,
				@lpodt_id,
				@litem_id,
				@lcurr_id,
				@lbra_id,
				@lcont_id,
				@ltax_id,
				@lpodt_qty,
				@lpodt_price,
				@obser,
				@priceB,
				@custom,
				@customNumber,
				@discount1,
				@discount2,
				@discount3,
				@discount4,
				@djai_id,
				@surcharge1,
				@surcharge2,
				@surcharge3,
				@surcharge4,
				@simi_id,
				@simid_id,
				@pod_Origin,
				@pod_From,
				@pod_Stamp,
				@pod_LotNumber,
				@pod_ExpirationDate,
				@pod_priceWithDiscountAndCharges,
				@pod_includeInAvailableStock,
				@stor_id


		-- se recorre el cursor hasta el fin del mismo
		while   @@fetch_status = 0
		begin

				-- por cada registro del cursor se realiza el insert en la tabla detalle
				exec	dbo.[spPurchaseOrderDetail_insertData]
							@lcomp_id,		@lbra_id,	@poh_id,
							@litem_id,		@lcurr_id,	@lcont_id,		@lpodt_qty,
							@lpodt_price,	@ltax_id,	'False',		@obser,
							@priceB,		@custom ,	@customNumber,  @discount1,
							@discount2,		@discount3,	@discount4,
							@return_value	= @lrv output

				--STL DJAI
				UPDATE tbPurchaseOrderDetail		WITH (ROWLOCK)
				SET
					djai_id							= @djai_id,
					pod_surcharge1					= @surcharge1,
					pod_surcharge2					= @surcharge2,
					pod_surcharge3					= @surcharge3,
					pod_surcharge4					= @surcharge4,
					simi_id							= @simi_id,
					simid_id						= @simid_id,
					pod_priceWithDiscountAndCharges = @pod_priceWithDiscountAndCharges

				WHERE	comp_id = @comp_id	AND
						poh_id	= @poh_id	AND
						pod_id	= @lrv


				UPDATE tbPurchaseOrderDetail
				SET
					pod_Origin			= @pod_Origin,
					pod_From			= @pod_From,
					pod_Stamp			= @pod_Stamp,
					pod_LotNumber		= @pod_LotNumber,
					pod_ExpirationDate	= @pod_ExpirationDate
					WHERE	comp_id		= @comp_id	AND
							poh_id		= @poh_id	AND
							pod_id		= @lrv

				UPDATE tbPurchaseOrderDetail
				SET pod_includeInAvailableStock = @pod_includeInAvailableStock
					WHERE	comp_id		= @comp_id	AND
							poh_id		= @poh_id	AND
							pod_id		= @lrv

				--Deposito para ROC
				UPDATE tbPurchaseOrderDetail
				SET stor_id = @stor_id
					WHERE	comp_id		= @comp_id	AND
							poh_id		= @poh_id	AND
							pod_id		= @lrv

				----STL SIMI  Si ya esta arriba para que MIERDA lo hacen en dos putas veces !!!
				--UPDATE tbPurchaseOrderDetail
				--SET
				--	simi_id		= @simi_id,
				--	simid_id	= @simid_id
				--WHERE	comp_id = @comp_id	AND
				--		poh_id	= @poh_id	AND
				--		pod_id	= @lrv

				-- por cada registro del cursor se realiza el delete del registro de la tabla detalle temporal
				exec    dbo.[spPurchaseOrderDetailTmp_deleteData]		@lpodt_id



				-- próxima lectura del cursor
				fetch	cursor_PO_iD_items
				into	@lcomp_id,
						@lpodt_guid,
						@lpodt_id,
						@litem_id,
						@lcurr_id,
						@lbra_id,
						@lcont_id,
						@ltax_id,
						@lpodt_qty,
						@lpodt_price,
						@obser,
						@priceB,
						@custom,
						@customNumber,
						@discount1,
						@discount2,
						@discount3,
						@discount4,
						@djai_id,
						@surcharge1,
						@surcharge2,
						@surcharge3,
						@surcharge4,
						@simi_id,
						@simid_id,
						@pod_Origin,
						@pod_From,
						@pod_Stamp,
						@pod_LotNumber,
						@pod_ExpirationDate	,
						@pod_priceWithDiscountAndCharges,
						@pod_includeInAvailableStock,
						@stor_id


		end

		close cursor_PO_iD_items
		deallocate cursor_PO_iD_items

end


-- retornar el valor del id insertado en la cabecera
set	@return_value = @poh_id


	COMMIT TRANSACTION

END TRY
BEGIN CATCH
	set	@return_value = -1
	ROLLBACK TRANSACTION
END CATCH
GO






-- --------------------------------------------------------------
-- MOS  10-2008
-- Borra los temporales que no se estan usando y no se han
-- actualizado, pasados 2 minutos.-
-- --------------------------------------------------------------

CREATE pROCEDURE [dbo].[spPurchaseOrder_IsEditingPurgeStatus]
AS

BEGIN

	set nocount on

	/*
	declare @comp_id	int
	select	@comp_id	= 1
	*/

	declare @DeleteTime		as	datetime
	set		@DeleteTime		=	DATEADD(minute, -3, getdate())

	-- cabeceras sin actualizar
	Update dbo.tbPurchaseOrderHeader	WITH(ROWLOCK)
		Set poh_isEditing = 'False'
			Where   poh_isEditing = 'True'
				and	poh_isEditingCd < @DeleteTime

	-- Detalles sin actualizar
	UPDATE tbPurchaseOrderDetail	WITH(ROWLOCK)
		Set pod_isEditing = 'False'
			Where   pod_isEditing = 'True'
				and	pod_isEditingCd < @DeleteTime

END






GO





------------------------------------------------------------------------------------------------------
--Date: 29/01/2021
--Author:GA
--Desc: Recuperamos las relaciones de la OC
------------------------------------------------------------------------------------------------------



CREATE PROCEDURE [dbo].[spPurchaseOrder_PaymentsRelations_getData]
(

		@comp_id			INT,
		@bra_id				INT,
		@poh_id				INT


)
as


SET NOCOUNT ON

-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
		@bra_id				INT,
		@poh_id				INT,
		@ct_transaction		INT



	SELECT		@comp_id			= 1,
				@bra_id			= 1,
				@poh_id				= 259,
				@ct_transaction = 10079
*/

-------------------------------------------------------------------------------------------

BEGIN

	SELECT
		tb.bra_desc						[bra_desc],				-- Sucursal
		tpoh.poh_id						[poh_id],				-- Número de Orden de Compra
		tct.ct_docNumber				[ct_transaction],		-- Número de Orden de Pago
		tpoh.poop_id					[ID]					-- ID de la relación

		FROM tbPurchaseOrder_PaymentsRelations  AS tpoh			WITH (NOLOCK)

		INNER JOIN tbBranch						AS tb			WITH (NOLOCK)
		ON	tb.comp_id				= tpoh.comp_id AND
			tb.bra_id				= tpoh.bra_id

		INNER JOIN tbCommercialTransactions		AS tct			WITH (NOLOCK)
		ON	tct.comp_id				= tpoh.comp_id AND
			tct.ct_transaction		= tpoh.ct_transaction

		WHERE	tpoh.comp_id	= @comp_id		AND
				tpoh.bra_id		= @bra_id		AND
				tpoh.poh_id		= @poh_id


END
GO







------------------------------------------------------------------------------------------------------
--Date   : 25/01/21
--Author :	GA
--Desc   :  agregar relacion entre OC y OP
------------------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spPurchaseOrder_PaymentsRelations_InsertRelation]
(

		@comp_id			INT,
		@bra_id				INT,
		@poh_id				INT,
		@ct_transaction		INT,
		@return_value as int output

)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE			@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@por_id			INT,
				@user_id			INT,
				@supp_id			INT,
				@item_id			INT


SELECT			@comp_id			= 1,
				@item_id			= 229,
				@supp_id			= 8145,
				@bra_id				= 1,
				@por_id				= 374

*/

-- ------------------------------------------------------



	DECLARE @lsuppOC AS INT		-- Proveedor de la OC
	SET @lsuppOC = 0

	SET @lsuppOC = (SELECT
						tpoh.supp_id
						FROM tbPurchaseOrderHeader AS tpoh			WITH (NOLOCK)
						WHERE	tpoh.comp_id	= @comp_id		AND
								tpoh.bra_id		= @bra_id		AND
								tpoh.poh_id		= @poh_id
					)

		--select @lsuppOC



		DECLARE @lct_transaction AS INT


		-----------------
		-- Para saber si buscó por numero de orden de pago o por id d comprobante
		IF EXISTS (SELECT TOP 1
						tpoh.ct_transaction
						FROM  tbCommercialTransactions  AS tpoh		WITH (NOLOCK)
						WHERE tpoh.comp_id = @comp_id AND tpoh.ct_docNumber = (CONVERT(NVARCHAR,@ct_transaction)) AND tpoh.supp_id = @lsuppOC
					    ORDER BY tpoh.ct_transaction desc)

					BEGIN
						SET @lct_transaction =  (SELECT TOP 1
													tpoh.ct_transaction
													FROM  tbCommercialTransactions  AS tpoh		WITH (NOLOCK)
													WHERE tpoh.comp_id = @comp_id AND tpoh.ct_docNumber = (CONVERT(NVARCHAR,@ct_transaction))  AND tpoh.supp_id = @lsuppOC
													ORDER BY tpoh.ct_transaction desc)

					END

					ELSE
						BEGIN
							SET @lct_transaction = @ct_transaction


						END
		-----------------



		SET @return_value = 0

		IF NOT EXISTS (SELECT poop_id
						 FROM tbPurchaseOrder_PaymentsRelations
						 WHERE bra_id = @bra_id AND poh_id = @poh_id)

						BEGIN
								INSERT INTO tbPurchaseOrder_PaymentsRelations
								(
									comp_id,
									-- poop_id -- this column value is auto-generated
									ct_transaction,
									bra_id,
									poh_id
								)
								VALUES
								(
									@comp_id,
									@lct_transaction,
									@bra_id,
									@poh_id

								)

								Set @return_value = @@IDENTITY

						END


END












GO





------------------------------------------------------------------------------------------------------
--Date: 25/01/2021
--Author:GA
--Desc: Validamos que el proveedor de la orden de pago sea el mismo que el proveedor de la orden de compra
------------------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spPurchaseOrder_PaymentsRelations_IsValid4Relation]
(

		@comp_id			INT,
		@bra_id				INT,
		@poh_id				INT,
		@ct_transaction		INT

)
as


SET NOCOUNT ON

-----------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
		@bra_id				INT,
		@poh_id				INT,
		@ct_transaction		INT



	SELECT		@comp_id			= 1,
				@bra_id			= 1,
				@poh_id				= 536,
				@ct_transaction = 60

*/

-------------------------------------------------------------------------------------------

BEGIN



	DECLARE @lsuppOC AS INT		-- Proveedor de la OC
	SET @lsuppOC = 0
	DECLARE @lsuppOP AS INT		-- Proveedor de la OP
	SET @lsuppOP = 0
	DECLARE @lavailable4relation AS INT

	SET @lavailable4relation = 1


	SET @lsuppOC = (SELECT
						tpoh.supp_id
						FROM tbPurchaseOrderHeader AS tpoh			WITH (NOLOCK)
						WHERE	tpoh.comp_id	= @comp_id		AND
								tpoh.bra_id		= @bra_id		AND
								tpoh.poh_id		= @poh_id
					)

		--select @lsuppOC


	DECLARE @lct_transaction AS INT


	-----------------
	-- Para saber si buscó por numero de orden de pago o por id d comprobante
	IF EXISTS (SELECT TOP 1
					tpoh.ct_transaction
					FROM  tbCommercialTransactions  AS tpoh		WITH (NOLOCK)
					WHERE tpoh.comp_id = @comp_id AND tpoh.ct_docNumber = (CONVERT(NVARCHAR,@ct_transaction))  AND tpoh.supp_id = @lsuppOC
					ORDER BY tpoh.ct_transaction desc)

				BEGIN
					SET @lct_transaction =  (SELECT TOP 1
												tpoh.ct_transaction
												FROM  tbCommercialTransactions  AS tpoh		WITH (NOLOCK)
												WHERE tpoh.comp_id = @comp_id AND tpoh.ct_docNumber = (CONVERT(NVARCHAR,@ct_transaction))  AND tpoh.supp_id = @lsuppOC
												ORDER BY tpoh.ct_transaction desc)

				END

				ELSE
					BEGIN
					 	SET @lct_transaction = @ct_transaction


					END
	-----------------



	SET @lsuppOP = (SELECT
						tpoh.supp_id
					    FROM tbCommercialTransactions  AS tpoh		WITH (NOLOCK)
						WHERE	tpoh.comp_id			= @comp_id			AND
								tpoh.bra_id				= @bra_id			AND
								tpoh.ct_transaction		= @lct_transaction  AND
								tpoh.sd_id				= 106
					)


					IF @lsuppOP IS NULL SET @lsuppOP = 0

					--select @lsuppOP

					-- Si el proveedor de la OC es diferente al proveedor de la OP no se puede relacionar
					IF @lsuppOC <> @lsuppOP
						BEGIN
						SET @lavailable4relation = 0
						END

					--Preguntamos si ya existe la OP en la tabla de relaciones
					IF @lsuppOP <> 0 AND EXISTS (SELECT
													tpopr.poop_id
					                                FROM tbPurchaseOrder_PaymentsRelations AS tpopr		WITH (NOLOCK)
													WHERE tpopr.comp_id = @comp_id AND tpopr.ct_transaction = @lct_transaction )
						BEGIN
						SET @lavailable4relation = 0
						END


-- 1 : Se puede relacionar
-- 0 :NO se puede relacionar
SELECT @lavailable4relation [Available4relation]

END
GO







CREATE PROCEDURE [dbo].[spPurchaseOrder_updateData]
(
	@comp_id					int,
	@bra_id						int,
	@poh_id						int,
	@podt_guid					uniqueidentifier,
	@poh_estDeliveryDate		datetime,
	@poh_deliveryDate			datetime,
	@poh_observation1			varchar(100),
	@poh_observation2			varchar(100),
	@poh_observation3			varchar(100),
	@poh_observation4			varchar(100),
	@supp_id					int,
	@poh_quotation				int,
	@pt_id						int,
	@ptr_id						int,
	@poh_ACurrency				INT,
	@poh_ACurrencyExchange		DECIMAL(19,6),
	@poh_Perceptions			DECIMAL(19,6),
	@poh_Taxes					DECIMAL(19,6),
	@poh_Charges				DECIMAL(19,6),
	@return_value				int output
)
AS
BEGIN





	set nocount on


	-- ---------------------------------------------------------------
	-- Test
	-- ---------------------------------------------------------------
	/*
	--ver como recuperamos el valor correspondiente
	declare	@podt_guid					uniqueidentifier,
			@comp_id					int,
			@bra_id						int,
			@poh_id						int,
			@poh_estDeliveryDate		datetime,
			@poh_deliveryDate			datetime,
			@poh_observation1			varchar(100),
			@poh_observation2			varchar(100),
			@poh_observation3			varchar(100),
			@poh_observation4			varchar(100),
			@supp_id					int,
			@poh_quotation				int,
			@pt_id						int,
			@ptr_id						int,
			@return_value				int

	select  @podt_guid					= 'f77b5ec8-90ff-4fc8-9bb7-ee4324e31323',
			@comp_id					= 1,
			@bra_id						= 1,
			@poh_id						= 2,
			@poh_estDeliveryDate		=getdate(),
			@poh_deliveryDate			=getdate(),
			@poh_observation1			='sdfsdfs sdfsdfs',
			@poh_observation2			='cbcvb cvbcvbc',
			@poh_observation3			='rtyrty rtuy',
			@poh_observation4			='mikmik mikmik , mikm',
			@supp_id					=74,
			@poh_quotation				=0,
			@pt_id						=5,
			@ptr_id						=1
	*/
	-- ---------------------------------------------------------------




	set	@return_value = 0


	BEGIN TRANSACTION
	BEGIN TRY


	--actualizar cabecera
	exec dbo.[spPurchaseOrderHeader_updateData]
			@comp_id,				@bra_id,				@poh_id,
			@poh_estDeliveryDate,	@poh_deliveryDate,		@poh_observation1,
			@poh_observation2,		@poh_observation3,		@poh_observation4,
			@supp_id,				@poh_quotation,			@pt_id,
			@ptr_id,				@poh_ACurrency,			@poh_ACurrencyExchange,
			@poh_Perceptions,		@poh_Taxes,				@poh_Charges


	set @return_value = @poh_id



	--eliminar todos los registro detalle relacionados a la cabecera actualizada
	--exec dbo.[spPurchaseOrderDetail_deleteAllData]	@poh_id



	-- Si no re recibio o si se anulo la recepcion permite borra el articulo.
	DELETE tbPurchaseorderReceptionDetail				WITH (ROWLOCK)
		FROM	tbPurchaseorderReceptionDetail tmp
		INNER JOIN tbPurchaseorderReceptionHeader tprh	WITH (NOLOCK)
			ON	tprh.comp_id	= tmp.comp_id AND
				tprh.por_id		= tmp.por_id
		LEFT JOIN tbPurchaseOrderDetailTmp tpodt		WITH (NOLOCK)
			ON	tpodt.podt_guid = @podt_guid	AND
				tpodt.pod_id	= tmp.pod_id
		WHERE	tmp.comp_id		= @comp_id		AND
				tmp.poh_bra_id	= @bra_id		AND
				tmp.poh_id		= @poh_id		AND
				tpodt.pod_id IS NULL			AND
				(
					tmp.pord_qty = 0
					OR
					tprh.por_isCancelled = 'True'
				)



	DELETE FROM tbPurchaseOrderDetail					WITH (ROWLOCK)
		FROM tbPurchaseOrderDetail tmp
		LEFT JOIN tbPurchaseOrderDetailTmp tpodt		WITH (NOLOCK)
			ON  tpodt.podt_guid = @podt_guid	AND
				tpodt.pod_id	= tmp.pod_id
		WHERE	tmp.comp_id		= @comp_id	AND
				tmp.bra_id		= @bra_id	AND
				tmp.poh_id		= @poh_id	AND
				tpodt.pod_id	IS NULL




	-- declareción de variables para obtener los datos del cursor
	declare
			@lcomp_id							int,
			@lpodt_guid							uniqueidentifier,
			@lpodt_id							int,
			@litem_id							int,
			@lcurr_id							int,
			@lbra_id							int,
			@lcont_id							int,
			@ltax_id							int,
			@lpodt_qty							decimal(19,5),
			@lpodt_price						decimal(19,6),
			@lpodt_cd							datetime,
			@lrv								INT,
			@obser								NVARCHAR(500),
			@bitIsProcessed						BIT,

			@podt_priceB						DECIMAL(19,6),
			@podt_custom						NVARCHAR(50),
			@podt_customNumber					NVARCHAR(50),
			@discount1							DECIMAL(19,6),
			@discount2							DECIMAL(19,6),
			@discount3							DECIMAL(19,6),
			@discount4							DECIMAL(19,6),
			@djai_id							INT,
			@podId								INT,
			@surcharge1							DECIMAL(19,6),
			@surcharge2							DECIMAL(19,6),
			@surcharge3							DECIMAL(19,6),
			@surcharge4							DECIMAL(19,6),
			@podt_confirmedQTY					DECIMAL(19,6),
			@podt_initialQTY					DECIMAL(19,6),
			@pod_priceWithDiscountAndCharges	DECIMAL(19,6),
			@simi_id							INT,
			@simid_id							INT,
			@pod_Origin							NVARCHAR(200),
			@pod_From							NVARCHAR(200),
			@pod_Stamp							NVARCHAR(200),
			@pod_LotNumber						NVARCHAR(50),
			@pod_ExpirationDate					DATETIME,
			@pod_includeInAvailableStock		BIT,
			@stor_id							INT


	-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
	declare cursor_PO_uD_items CURSOR LOCAL FAST_FORWARD FOR

	select	comp_id,
			podt_guid,
			podt_id,
			item_id,
			curr_id,
			bra_id,
			cont_id,
			tax_id,
			podt_qty,
			podt_price,
			podt_cd,
			podt_obs,
			podt_isProcessed,

			podt_priceB,
			podt_custom,
			podt_customNumber,
			pod_Discount1,
			pod_Discount2,
			pod_Discount3,
			pod_Discount4,
			djai_id,
			pod_id,
			ISNULL(pod_surcharge1,0)	[pod_surcharge1],
			ISNULL(pod_surcharge2,0)	[pod_surcharge2],
			ISNULL(pod_surcharge3,0)	[pod_surcharge3],
			ISNULL(pod_surcharge4,0)	[pod_surcharge4],
			IsNull(podt_initQTY,podt_qty),
			ISNULL(podt_confirmedQTY,0),
			pod_priceWithDiscountAndCharges,
			simi_id,
			simid_id,
			pod_Origin,
			pod_From,
			pod_Stamp,
			pod_LotNumber,
			pod_ExpirationDate,
			pod_includeInAvailableStock,
			stor_id


	from	dbo.[tbPurchaseOrderDetailTmp]
	where	podt_guid = @podt_guid
	ORDER BY
		CASE
			WHEN pod_id IS NULL THEN	1
			ELSE						0
		END,
		pod_id



	open	cursor_PO_uD_items

	-- lectura anticipada del cursor
	fetch	cursor_PO_uD_items
	into	@lcomp_id,
			@lpodt_guid,
			@lpodt_id,
			@litem_id,
			@lcurr_id,
			@lbra_id,
			@lcont_id,
			@ltax_id,
			@lpodt_qty,
			@lpodt_price,
			@lpodt_cd,
			@obser,
			@bitIsProcessed,

			@podt_priceB,
			@podt_custom,
			@podt_customNumber,
			@discount1,
			@discount2,
			@discount3,
			@discount4,
			@djai_id,
			@podId,
			@surcharge1,
			@surcharge2,
			@surcharge3,
			@surcharge4	,
			@podt_initialQTY,
			@podt_confirmedQTY	,
			@pod_priceWithDiscountAndCharges,
			@simi_id,
			@simid_id,
			@pod_Origin,
			@pod_From,
			@pod_Stamp,
			@pod_LotNumber,
			@pod_ExpirationDate,
			@pod_includeInAvailableStock,
			@stor_id





	-- se recorre el cursor hasta el fin del mismo
	while   @@fetch_status = 0
	begin

		SET @lrv = NULL
		IF @podId IS NULL
			BEGIN

				-- por cada registro del cursor se realiza el insert en la tabla detalle
				exec	dbo.[spPurchaseOrderDetail_insertData]
						@lcomp_id,		@lbra_id,			@poh_id,			@litem_id,
						@lcurr_id,		@lcont_id,			@lpodt_qty,			@lpodt_price,
						@ltax_id,		@bitIsProcessed,	@obser,
						@podt_priceB,	@podt_custom,		@podt_customNumber		, @discount1,
						@discount2,		@discount3,			@discount4,
						@return_value		= @lrv output

			END
		ELSE
			BEGIN
				UPDATE tbPurchaseOrderDetail		WITH (ROWLOCK)
				SET
					item_id				= @litem_id,
					curr_id				= @lcurr_id,
					cont_id				= @lcont_id,
					pod_qty				= @lpodt_qty,
					pod_price			= @lpodt_price,
					tax_id				= @ltax_id,
					pod_isProcessed		= @bitIsProcessed,
					pod_isEditing		= 'true',
					pod_isEditingCd		= GETDATE(),
					pod_obs				= @obser,
					pod_priceB			= @podt_priceB,
					pod_custom			= @podt_custom,
					pod_customNumber	= @podt_customNumber,
					pod_Discount1		= @discount1,
					pod_Discount2		= @discount2,
					pod_Discount3		= @discount3,
					pod_Discount4		= @discount4
				WHERE	comp_id = @comp_id	AND
						bra_id	= @bra_id	AND
						poh_id	= @poh_id	AND
						pod_id	= @podId
				SET @lrv = @podId
			END


		--STL DJAI
		UPDATE tbPurchaseOrderDetail		WITH (ROWLOCK)
		SET
			djai_id							= @djai_id,
			pod_surcharge1					= @surcharge1,
			pod_surcharge2					= @surcharge2,
			pod_surcharge3					= @surcharge3,
			pod_surcharge4					= @surcharge4,
			pod_initQty						= @podt_initialQTY,
			pod_confirmedQTY				= @podt_confirmedQTY,
			pod_priceWithDiscountAndCharges = @pod_priceWithDiscountAndCharges,
			simi_id							= @simi_id,
			simid_id						= @simid_id,
			pod_Origin						= @pod_Origin,
			pod_From						= @pod_From,
			pod_Stamp						= @pod_Stamp,
			pod_LotNumber					= @pod_LotNumber,
			pod_ExpirationDate				= @pod_ExpirationDate,
			pod_includeInAvailableStock		= @pod_includeInAvailableStock

		WHERE	comp_id = @comp_id	AND
				poh_id	= @poh_id	AND
				pod_id	= @lrv

		----STL SIMI
		--UPDATE tbPurchaseOrderDetail		WITH (ROWLOCK)
		--SET
		--	simi_id		= @simi_id,
		--	simid_id	= @simid_id
		--WHERE	comp_id = @comp_id	AND
		--		poh_id	= @poh_id	AND
		--		pod_id	= @lrv

		UPDATE tbPurchaseOrderDetail		WITH (ROWLOCK)
		SET stor_id				= @stor_id

		WHERE	comp_id = @comp_id	AND
				poh_id	= @poh_id	AND
				pod_id	= @lrv

		-- por cada registro del cursor se realiza el delete de la tabla temporal
		exec	dbo.[spPurchaseOrderDetailTmp_deleteData]	@lpodt_id


		UPDATE tbpurchaseorderdetail		WITH (ROWLOCK)
			SET pod_isEditing = 'False'
			WHERE	comp_id = @comp_id	AND
					bra_id	= @bra_id	AND
					poh_id	= @poh_id

		-- próxima lectura del cursor
		fetch	cursor_PO_uD_items
		into	@lcomp_id,
				@lpodt_guid,
				@lpodt_id,
				@litem_id,
				@lcurr_id,
				@lbra_id,
				@lcont_id,
				@ltax_id,
				@lpodt_qty,
				@lpodt_price,
				@lpodt_cd,
				@obser,
				@bitIsProcessed,

				@podt_priceB,
				@podt_custom,
				@podt_customNumber,
				@discount1,
				@discount2,
				@discount3,
				@discount4,
				@djai_id,
				@podId,
				@surcharge1,
				@surcharge2,
				@surcharge3,
				@surcharge4	,
				@podt_initialQTY,
				@podt_confirmedQTY,
				@pod_priceWithDiscountAndCharges,
				@simi_id,
				@simid_id,
				@pod_Origin,
				@pod_From,
				@pod_Stamp,
				@pod_LotNumber,
				@pod_ExpirationDate,
				@pod_includeInAvailableStock,
				@stor_id

	end

	close cursor_PO_uD_items
	deallocate cursor_PO_uD_items


		COMMIT TRANSACTION

	END TRY
	BEGIN CATCH
		set	@return_value = -1
		ROLLBACK TRANSACTION
	END CATCH


END
GO





CREATE PROCEDURE spPurchaseOrder_updateDiscounts
(
	@comp_id					INT,
	@bra_id						INT,
	@POH_Id						INT,
	@discount1					DECIMAL(19,6),
	@discount2					DECIMAL(19,6),
	@discount3					DECIMAL(19,6),
	@discount4					DECIMAL(19,6),
	@ret_ErrorCode				as int			output,
	@ret_ErrorDescription		as varchar(200) output
)
AS SET NOCOUNT ON

-- ---------------------------------------------------
-- Testing
-- ---------------------------------------------------
/*
	DECLARE
		@comp_id		INT,
		@bra_id			INT,
		@ct_transaction	INT,
		@discount1		DECIMAL(19,6),
		@discount2		DECIMAL(19,6),
		@discount3		DECIMAL(19,6),
		@discount4		DECIMAL(19,6)

	SELECT
		@comp_id		= 1,
		@bra_id			= 1,
		@ct_transaction	= 3237,
		@discount1		= 1,
		@discount2		= 2,
		@discount3		= 3,
		@discount4		= 4
*/
-- ---------------------------------------------------

Set @ret_ErrorCode			= 0
Set @ret_ErrorDescription	= ''


BEGIN TRY

	UPDATE tbPurchaseOrderHeader

	SET
		poh_Discount1 = @discount1,
		poh_Discount2 = @discount2,
		poh_Discount3 = @discount3,
		poh_Discount4 = @discount4

	WHERE	comp_id			= @comp_id
	AND		bra_id			= @bra_id
	AND		poh_id			= @POH_Id

END TRY
BEGIN CATCH
	Set @ret_ErrorCode			= -1
	Set @ret_ErrorDescription	= 'spPurchaseOrder_updateDiscounts-' +
		(SELECT
			convert(varchar,ERROR_NUMBER	())	+ '-' +
			convert(varchar,ERROR_SEVERITY	())	+ '-' +
			convert(varchar,ERROR_STATE		())	+ '-' +
			convert(varchar,ERROR_LINE		())	+ '-' +
							ERROR_MESSAGE	())
END CATCH
GO





