CREATE PROCEDURE [dbo].[spPurchaseOrder_updateLoanData]
(
	@comp_id					INT,
	@bra_id						INT,
	@POH_Id						INT,
	@guid		     			UNIQUEIDENTIFIER,
	@ret_ErrorCode				as int			output,
	@ret_ErrorDescription		as varchar(200) output
)
AS

BEGIN



	SET NOCOUNT ON

	set @ret_ErrorCode			= -1
	set @ret_ErrorDescription	= ''



	BEGIN TRY

		-- Borro los originales
		DELETE FROM tbCommercialTransactionsPurchaseLoan
			WHERE	comp_id = @comp_id	AND
					bra_id	= @bra_id	AND
					poh_id	= @POH_Id

		-- Le pongo a los temporales los datos del original
		UPDATE tbCommercialTransactionsPurchaseLoan
			SET
				ctpl_guid = NULL,
				bra_id = @bra_id,
				poh_id = @POH_Id
			WHERE ctpl_guid = @guid


	END TRY
	BEGIN CATCH

	END CATCH


END
GO


