CREATE PROCEDURE [dbo].[spPurchaseOrder_updateProject]
(
	@comp_id		AS INT,
	@bra_id			AS INT,
	@poh_id			AS INT,
	@pro_id			AS INT
)
AS
BEGIN
	SET NOCOUNT ON;
	UPDATE tbPurchaseOrderHeader	WITH (ROWLOCK)
		SET			pro_id =	CASE
	   								WHEN @pro_id = -1  THEN NULL
	   								ELSE @pro_id
	   							END

		WHERE	comp_id			= @comp_id			AND
				bra_id			= @bra_id			AND
				poh_id			= @poh_id

END

GO


