CREATE PROCEDURE spPurchaseOrderBuyerGroupByUser_IsValidSupplier
(
	@comp_id	INT,
	@bra_id		INT,
	@user_id	INT,
	@supp_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN
			-- --------------------------------
			-- Testing
			-- --------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@bra_id		INT,
					@user_id	INT,
					@supp_id	INT
				SELECT
					@comp_id	= 1,
					@bra_id		= 1,
					@user_id	= 119,
					@supp_id	= 8110
			*/
			-- --------------------------------

			DECLARE
				@HasGroups			BIT,
				@IsSupplierValid	BIT

			IF EXISTS(SELECT 1 FROM tbPurchaseOrderBuyerGroupByUser tpobgbu WHERE tpobgbu.comp_id = @comp_id AND tpobgbu.[user_id] = @user_id)
				BEGIN
					SELECT @HasGroups = 'True'
				END
			ELSE
				BEGIN
					SELECT @HasGroups = 'False'
				END


			--EXISTE EL PROVEEDOR PARA EL GRUPO???
			IF EXISTS(
						SELECT
							1
						FROM tbPurchaseOrderBuyerGroupByUser				tpobgbu

							INNER JOIN tbPurchaseOrderBuyerGroupBySupplier	tpobgbs
								ON	tpobgbs.comp_id = tpobgbu.comp_id		AND
									tpobgbs.pobg_id = tpobgbu.pobg_id

						WHERE	tpobgbu.comp_id		= @comp_id				AND
								tpobgbu.[user_id]	= @user_id				AND
								tpobgbs.bra_id		= @bra_id				AND
								tpobgbs.supp_id		= @supp_id
					 )

					SELECT @IsSupplierValid = 'True'
			ELSE
					SELECT @IsSupplierValid = 'False'


			--@HasGroups		= Dice si tiene algún grupo asignado
			--@IsSupplierValid	= Si tiene un grupo asignado, dice si el proveedor es correcto para la sucursal actual
			SELECT @HasGroups,@IsSupplierValid

		END

GO



