-- Recalcula el estado de pendiente de recepcion de Ordenes de Compra de una Compañia
CREATE PROCEDURE [dbo].spPurchaseOrderDetail_calculatePendingCoeficient
(
	@comp_id		int
)
as


BEGIN
	DECLARE @bra_id		AS INT
	DECLARE @poh_id		AS INT
	DECLARE @pod_id		AS INT

	DECLARE curPO  CURSOR LOCAL FAST_FORWARD FOR
	SELECT DISTINCT
					poh.bra_id,
					poh.poh_id
		FROM tbPurchaseOrderHeader poh
		WHERE poh.comp_id = @comp_id

	OPEN curPO

	FETCH NEXT FROM curPO INTO @bra_id,@poh_id

	WHILE @@FETCH_STATUS = 0
		BEGIN

			SELECT TOP 1 @pod_id = pod_id
				FROM tbPurchaseOrderDetail tpod
				WHERE	tpod.comp_id	= @comp_id	AND
						tpod.bra_id		= @bra_id	AND
						tpod.poh_id		= @poh_id

			UPDATE tbPurchaseOrderDetail
				SET pod_confirmedQTY = pod_confirmedQTY
				WHERE	comp_id = @comp_id	AND
						bra_id	= @bra_id	AND
						poh_id  = @poh_id	AND
						pod_id	= @pod_id

			FETCH NEXT FROM curPO INTO @bra_id,@poh_id
		END
	CLOSE		curPO
	DEALLOCATE	curPO

END



GO









CREATE  PROCEDURE [dbo].[spPurchaseOrderDetail_deleteAllData]
(
	@comp_id		INT,
	@bra_id			INT,
	@poh_id			int
)
as

BEGIN

	set nocount on


	-- Borra recepciones ANULADAS
	DELETE FROM tbPurchaseorderReceptionDetail
		FROM tbPurchaseorderReceptionDetail tmp
		INNER JOIN tbPurchaseorderReceptionHeader tprh
			ON	tprh.comp_id	= tmp.comp_id AND
				tprh.por_id		= tmp.por_id
		WHERE	tmp.comp_id					= @comp_id	AND
				tmp.poh_bra_id				= @bra_id	AND
				tmp.poh_id					= @poh_id	AND
				tprh.por_isCancelled		= 'True'


	delete	dbo.[tbPurchaseOrderDetail]
		WHERE	comp_id		= @comp_id	AND
				bra_id		= @bra_id	AND
				poh_id		= @poh_id


END
GO









