CREATE PROCEDURE [dbo].[spPurchaseOrderDetail_getDataById]
(
	@comp_id		int,
	@bra_id			int,
	@poh_id			int,
	@pod_id			int
)
as
set nocount on

/*
declare @comp_id		int,
		@bra_id			int,
		@poh_id			int,
		@pod_id			int

select	@comp_id		=1,
		@bra_id			=1,
		@poh_id			=225,
		@pod_id			=3237
*/

select	pod.comp_id		,
		pod.bra_id		,
		pod.poh_id		,
		pod.pod_id		,
		pod.item_id		,
		i.item_code		,
		i.item_desc		,
		pod.curr_id		,
		pod.cont_id		,
		pod.pod_qty		,
		pod.pod_price	,
		pod.tax_id		,
		pod.pod_obs		,
		pod.pod_isProcessed,
		pod.pod_priceB,
		pod.pod_custom,
		pod.pod_customNumber,
		ISNULL(pod.pod_confirmedQTY,0)		[pod_confirmedQTY],
		pod.pod_Discount1,
		pod.pod_Discount2,
		pod.pod_Discount3,
		pod.pod_Discount4,
		pod.pod_surcharge1,
		pod.pod_surcharge2,
		pod.pod_surcharge3,
		pod.pod_surcharge4,
		ISNULL(pod.pod_Origin,'')			[pod_Origin],
		ISNULL(pod.pod_From,'')				[pod_From],
		ISNULL(pod.pod_Stamp,'')			[pod_Stamp],
		ISNULL(pod.pod_LotNumber,'')		[pod_LotNumber],
		pod.pod_ExpirationDate,
		ISNULL(pod.pod_includeInAvailableStock,'False')	[pod_includeInAvailableStock]


from	dbo.tbPurchaseOrderDetail			pod

		left join dbo.[tbItem]				i
		on	i.comp_id		=	pod.comp_id
		and	i.[item_id]		=	pod.[item_id]

where	pod.pod_id			=	@pod_id
and		pod.poh_id			=   @poh_id
and		pod.comp_id			=	@comp_id
and		pod.bra_id			=	@bra_id























GO



-- -------------------------------------------------------------------------------------
-- Recuperamos el coeficiente de descuento de compras relacionado al item y proveedor.
-- -------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spPurchaseOrderDetail_getDiscountCoeficient]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@item_id	INT,
	@supp_id	INT

)
AS

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@item_id	INT,
			@supp_id	INT,
			@user_id    INT,
			@prof_id	INT



		SELECT
			@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@item_id	=492,
			@supp_id	=8103,
			@user_id    = 3
*/
	-- ------------------------------------------------------

	DECLARE @lpd_id AS INT
	SET		@lpd_id = 0

	DECLARE @ldiscountcoeficient AS DECIMAL(25,10)
	SET @ldiscountcoeficient = 0

	SET @lpd_id =(	SELECT
						CASE
							WHEN ti.pd_id IS NOT NULL  THEN ti.pd_id
							WHEN ts.pd_id IS NOT NULL  THEN ts.pd_id
							ELSE						    -1
						END									[pd_id]
						FROM tbItem				ti		WITH (NOLOCK)
						LEFT JOIN tbSupplier	ts		WITH (NOLOCK)
							ON	ts.comp_id = ti.comp_id AND
								ts.supp_id = ti.supp_id
						WHERE ti.comp_id = @comp_id			AND
							  ti.item_id = @item_id

				)

	IF @lpd_id > 0

		BEGIN

			SELECT 	@ldiscountcoeficient =	 ISNULL(tpd.pd_discountCoeficient,0)
				FROM tbPurchaseDiscount					 tpd	WITH (NOLOCK)
				WHERE	tpd.comp_id							= @comp_id	AND
						tpd.pd_id							= @lpd_id	AND
						tpd.pd_discount_apply4PurchaseOrder = 'True'	AND
						tpd.pd_isDisabled					= 'False'


			SELECT 	@ldiscountcoeficient =	(@ldiscountcoeficient + ISNULL(tpd.pd_bonificationCoeficient,0)) - ( @ldiscountcoeficient *  ISNULL(tpd.pd_bonificationCoeficient,0) )
				FROM tbPurchaseDiscount					 tpd	WITH (NOLOCK)
				WHERE	tpd.comp_id								= @comp_id	AND
						tpd.pd_id								= @lpd_id	AND
						tpd.pd_bonification_apply4PurchaseOrder = 'True'	AND
						tpd.pd_isDisabled						= 'False'


			SELECT 	@ldiscountcoeficient =  (@ldiscountcoeficient + ISNULL(tpd.pd_bonificationCNCoeficient,0)) - ( @ldiscountcoeficient *  ISNULL(tpd.pd_bonificationCNCoeficient,0) )
				FROM tbPurchaseDiscount					 tpd	WITH (NOLOCK)
				WHERE	tpd.comp_id									= @comp_id	AND
						tpd.pd_id									= @lpd_id	AND
						tpd.pd_bonificationCN_apply4PurchaseOrder	= 'True'	AND
						tpd.pd_isDisabled							= 'False'


		END


		--Si es NULL quiere decir que o no está habilitado para OC o está deshabilitado el descuento de compras.
		SELECT isnull(@ldiscountcoeficient,0) [discountcoeficient]

END
GO


