CREATE PROCEDURE [dbo].[spPurchaseOrderDetail_getDiscountCoeficient4Price]
(
	@comp_id					INT,
	@lang_id					INT,
	@bra_id						INT,
	@prof_id					INT,
	@user_id					INT,
	@coslis_price				DECIMAL(19,5),
	@item_purOrd_Disc1			DECIMAL(18,4),
	@item_purOrd_Disc2			DECIMAL(18,4),
	@item_purOrd_Disc3			DECIMAL(18,4),
	@item_purOrd_Disc4			DECIMAL(18,4),

	@item_purOrd_surcharge1		DECIMAL(18,4),
	@item_purOrd_surcharge2		DECIMAL(18,4),
	@item_purOrd_surcharge3		DECIMAL(18,4),
	@item_purOrd_surcharge4		DECIMAL(18,4)

)
AS

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
/*
		DECLARE
			@comp_id					INT,
			@lang_id					INT,
			@bra_id						INT,
			@prof_id					INT,
			@user_id					INT,
			@coslis_price				DECIMAL(19,5),
			@item_purOrd_Disc1			DECIMAL(18,4),
			@item_purOrd_Disc2			DECIMAL(18,4),
			@item_purOrd_Disc3			DECIMAL(18,4),
			@item_purOrd_Disc4			DECIMAL(18,4),

			@item_purOrd_surcharge1		DECIMAL(18,4),
			@item_purOrd_surcharge2		DECIMAL(18,4),
			@item_purOrd_surcharge3		DECIMAL(18,4),
			@item_purOrd_surcharge4		DECIMAL(18,4)

		SELECT
			@comp_id		=1,
			@lang_id		=2,
			@bra_id			=1,
			@prof_id		=1,
			@coslis_price	=80,
			@user_id		= 3,

			@item_purOrd_Disc1			= 76,
			@item_purOrd_Disc2			= 8,
			@item_purOrd_Disc3			= 0,
			@item_purOrd_Disc4			= 0,

			@item_purOrd_surcharge1		= 0,
			@item_purOrd_surcharge2		= 0,
			@item_purOrd_surcharge3		= 0,
			@item_purOrd_surcharge4		= 0
		*/

	-- ------------------------------------------------------


	SELECT
		isnull(@coslis_price,0)	* dbo.fnGetFinalDiscountCoeficient(@item_purOrd_Disc1,@item_purOrd_Disc2,@item_purOrd_Disc3,@item_purOrd_Disc4)
				* dbo.fnGetFinalDiscountCoeficient(-@item_purOrd_surcharge1,-@item_purOrd_surcharge2,-@item_purOrd_surcharge3,-@item_purOrd_surcharge4) [Price_FinalDiscountCoeficient]

END
GO



