CREATE PROCEDURE [dbo].[spPurchaseOrderDetail_getPendingData]
(
	@comp_id	INT,
	@bra_id		INT,
	@item_id	INT,
	@user_id	INT
)
AS


BEGIN
	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'
	-- ---------------------------------------------------
	-- TESTING
	-- ---------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@bra_id		INT,
			@item_id	INT,
			@user_id	INT
		SELECT
			@comp_id	= 1,
			@bra_id		= -4,
			@item_id	= 492,
			@user_id	= 119
	*/
	-- ---------------------------------------------------

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )

	--SI EL BRA ID ES NEGATIVO, ES BRAG_ID
	--SINO ES BRA_ID
	IF @bra_id < 0
		BEGIN
			INSERT INTO @tblBranchs
			SELECT DISTINCT	bra_id
				FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
				WHERE	tbgd.comp_id = @comp_id AND
						tbgd.brag_id = (@bra_id * -1)
		END
	ELSE
		BEGIN
			INSERT INTO @tblBranchs
			(
				bra_id
			)
			SELECT	bra_id
				FROM tbBranch tb		WITH (NOLOCK)
				WHERE	tb.bra_id = @bra_id						OR
						tb.bra_idEnabled4POInselItem = 'True'		-- sino q pongan esto en true y filtren x perfiles, que igual se hace mas abajo
		END




	SELECT
		tpod.bra_id,
		tpod.poh_id,
		ts.supp_name,
		tpod.pod_qty,
		tpoh.poh_estDeliveryDate,
		(
			SELECT tpod.pod_qty -  ISNULL(SUM(tsod.sod_qty),0)
				FROM tbSaleOrderHeader_PurchaseOrderRelation	AS ore	WITH (NOLOCK)
				INNER JOIN tbSaleOrderDetail					AS tsod	WITH (NOLOCK)
					ON	tsod.comp_id	= ore.comp_id	AND
						tsod.bra_id		= ore.so_bra_id AND
						tsod.soh_id		= ore.so_soh_id AND
						tsod.sod_id		= ore.so_sod_id
				WHERE	ore.comp_id		= tpod.comp_id	AND
						ore.po_bra_id	= tpod.bra_id	AND
						ore.po_poh_id	= tpod.poh_id	AND
						ore.po_pod_id	= tpod.pod_id
		)																[qtyPending4Relation],
		ti.item_code,
		ti.item_desc,
		ti.item_vendorCode
		FROM	tbPurchaseOrderDetail											tpod	WITH (NOLOCK)
				LEFT JOIN tbItem												AS ti	WITH (NOLOCK)
					ON	ti.comp_id							= tpod.comp_id AND
						ti.item_id							= tpod.item_id
				INNER JOIN	tbPurchaseOrderHeader								tpoh	WITH (NOLOCK)
					ON	tpoh.comp_id						= tpod.comp_id		AND
						tpoh.bra_id							= tpod.bra_id		AND
						tpoh.poh_id							= tpod.poh_id		AND
						ISNULL(tpoh.poh_isEditing,'False')	= 'False'			AND
						ISNULL(tpoh.poh_quotation,'False')	= 'False'
				INNER JOIN tbSupplier											ts		WITH (NOLOCK)
					ON	ts.comp_id							= tpoh.comp_id		AND
						ts.supp_id							= tpoh.supp_id
				INNER JOIN @tblBranchs											tb
					ON	tb.bra_id							= tpoh.bra_id
				INNER JOIN tbUsers4BranchFilter									vubf	WITH (NOLOCK)
					ON	vubf.comp_id						= tpod.comp_id	AND
						vubf.bra_id							= tpod.bra_id	AND
						vubf.[user_id]						= @user_id
		WHERE	tpod.comp_id								= @comp_id		AND
				--tpod.bra_id		 = @bra_id
				tpod.item_id								= @item_id		AND
				ISNULL(tpod.pod_isEditing,	'False')		= 'False'		AND
				ISNULL(tpod.pod_isProcessed,'False')		= 'False'

	ORDER BY tpod.poh_id ASC

END
GO








CREATE procedure [dbo].[spPurchaseOrderDetail_insertData]
(
	@comp_id			int,
	@bra_id				int,
	@poh_id				int,
	@item_id			int,
	@curr_id			int,
	@cont_id			int,
	@pod_qty			decimal(19,5),
	@pod_price			decimal(19,6),
	@tax_id				int,
	@pod_isProcessed	bit,
	@obser				VARCHAR (500),
	@priceb				DECIMAL(16,5),
	@custom				VARCHAR(50),
	@customNumber		VARCHAR(50),
	@discount1			DECIMAL(19,5),
	@discount2			DECIMAL(19,5),
	@discount3			DECIMAL(19,5),
	@discount4			DECIMAL(19,5),
	@return_value		int OUTPUT
)
as
set nocount on


insert into dbo.tbPurchaseOrderDetail
(
	comp_id,
	bra_id,
	poh_id,
	item_id,
	curr_id,
	cont_id,
	pod_qty,
	pod_price,
	tax_id,
	pod_isProcessed,
	pod_obs,
	pod_priceB,
	pod_custom,
	pod_customNumber,
	pod_Discount1,
	pod_Discount2,
	pod_Discount3,
	pod_Discount4
)
values
(
	@comp_id,
	@bra_id,
	@poh_id,
	@item_id,
	@curr_id,
	@cont_id,
	@pod_qty,
	@pod_price,
	@tax_id,
	@pod_isProcessed,
	@obser,
	@priceb,
	@custom,
	@customNumber,
	@discount1,
	@discount2,
	@discount3,
	@discount4
)


set	@return_value = @@identity
GO







------------------------------------------------------------------------------------------------------
--Date   :
--Author :	GA
--Desc   :  Verificar si el item esta relacionado al proveedor para poder agregarlo.
------------------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spPurchaseOrderDetail_ItemSupplier]
(

		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@supp_id			INT,
		@item_id			INT

)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE			@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@supp_id			INT,
				@item_id			INT


SELECT			@comp_id			= 1,
				@item_id			= 229,
				@supp_id			= 8145,
				@bra_id				= 1,
				@prof_id			= 1
*/
-- ------------------------------------------------------

	-- 1 : Puede Agregar cualquier articulo
	-- 0 : No puede agregar el articulo porque no esta relacioando al proveedor
	-- 2 : Puede agregar el articulo xq esta relacioando al proveedor

	DECLARE @lavailable AS INT

	SET		@lavailable = 1



		IF NOT EXISTS ( SELECT top 1 1

						FROM tbItemSupplierCheck				tisc	WITH (NOLOCK)

						Where	tisc.comp_id	= @comp_id		AND
								tisc.bra_id		= @bra_id		AND
								tisc.prof_id	= @prof_id
					  )

			BEGIN

				SET @lavailable = 1
			END

		ELSE


			BEGIN

			IF  EXISTS ( SELECT top 1 ti.item_id

						 FROM tbItem ti	WITH (NOLOCK)


						 Where	ti.comp_id	= @comp_id		AND
								ti.supp_id 	= @supp_id		AND
								ti.item_id	= @item_id		AND
								(ti.bra_id	= @bra_id OR ti.bra_id IS NULL)
			)

				BEGIN
						--Puede agregar ese item para ese proveedor
						SET @lavailable = 2

				END
			ELSE

				BEGIN

						IF NOT EXISTS ( SELECT tis.item_id
										FROM tbItemSupplier					tis

										WHERE	tis.comp_id	= @comp_id		AND
												tis.supp_id = @supp_id		AND
												tis.item_id	= @item_id		AND
												(tis.bra_id	= @bra_id OR tis.bra_id IS NULL)
										)
							BEGIN
								SET @lavailable = 0
							END

						ELSE
							BEGIN
								SET @lavailable = 2
							END



				END


				END



-- 1 : Puede Agregar cualquier articulo
-- 0 : No puede agregar el articulo porque no esta relacioando al proveedor
-- 2 : Puede agregar el articulo xq esta relacioando al proveedor


SELECT @lavailable [Available]



END











GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[spPurchaseOrderDetail_update_SaleOrderHeader_PurchaseOrderRelation]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@poh_id		AS INT,
	@pod_id		AS INT,
	@item_id	AS INT,
	@pod_qty	AS INT
AS



BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	-- ----------------------------------------
	-- Test
	-- ----------------------------------------
	/*
	DECLARE 	@comp_id	AS INT  = 1,
				@bra_id		AS INT  = 1,
				@poh_id		AS INT  = 573,
				@pod_id		AS INT  = 21874,
				@item_id	AS INT  = 492,
				@pod_qty	AS INT = 888888
	*/
	-- ----------------------------------------







	-- ------------------------------------------------------------------------------------------------------
	-- Verificar si hay algun PEDIDO PENDIENTE de Relacionar ( poner INDICE con WHERE para eso en Pedidos )
	-- ------------------------------------------------------------------------------------------------------
	IF EXISTS(	SELECT TOP 1 1
	          		FROM tbSaleOrderDetail AS tsod	WITH (NOLOCK,INDEX(IX_tbSaleOrderDetail_4sod_pending4pod_IdRelation))
	          		WHERE	tsod.comp_id					= @comp_id	AND
	          				tsod.item_id					= @item_id	AND
	          				tsod.sod_pending4pod_IdRelation = 'True'
			)
		BEGIN
			DECLARE @decQTYRelated AS DECIMAL(19,4) = 0
			SELECT  @decQTYRelated = ISNULL(SUM(tsod.sod_qty),0)
				FROM tbSaleOrderHeader_PurchaseOrderRelation	AS tsohpor	WITH (NOLOCK)
				INNER JOIN tbSaleOrderDetail					AS tsod		WITH (NOLOCK)
					ON	tsod.comp_id		= tsohpor.comp_id	AND
						tsod.bra_id			= tsohpor.so_bra_id AND
						tsod.soh_id			= tsohpor.so_soh_id AND
						tsod.sod_id			= tsohpor.so_sod_id
				WHERE	tsohpor.comp_id		= @comp_id			AND
						tsohpor.po_bra_id	= @bra_id			AND
						tsohpor.po_poh_id	= @poh_id			AND
						tsohpor.po_pod_id	= @pod_id


--==
--select '@decQTYRelated','@pod_qty',@decQTYRelated,@pod_qty

			IF @decQTYRelated < @pod_qty
				BEGIN

					DECLARE @curbra_id	AS INT
					DECLARE @cursoh_id	AS INT
					DECLARE @cursod_id	AS INT
					DECLARE @cursod_qty AS DECIMAL(19,4)
					DECLARE @decAvailableQTY AS DECIMAL(19,4) = ISNULL(@pod_qty,0) - ISNULL(@decQTYRelated,0)

--==
					--SELECT
					--		tsod.bra_id,
					--		tsod.soh_id,
					--		tsod.sod_id,
					--		tsod.sod_qty
					--	FROM tbSaleOrderDetail AS tsod WITH (NOLOCK,INDEX(IX_tbSaleOrderDetail_4sod_pending4pod_IdRelation))
					--	WHERE	tsod.comp_id					= @comp_id	AND
					--			tsod.item_id					= @item_id	AND
					--			tsod.sod_pending4pod_IdRelation = 'True'
					--	ORDER BY tsod.soD_ID
--==




					DECLARE curSaleOrderPending CURSOR LOCAL FAST_FORWARD FOR
					SELECT
							tsod.bra_id,
							tsod.soh_id,
							tsod.sod_id,
							tsod.sod_qty
						FROM tbSaleOrderDetail AS tsod WITH (NOLOCK,INDEX(IX_tbSaleOrderDetail_4sod_pending4pod_IdRelation))
						WHERE	tsod.comp_id					= @comp_id	AND
								tsod.item_id					= @item_id	AND
								tsod.sod_pending4pod_IdRelation = 'True'
						ORDER BY tsod.soD_ID


					OPEN curSaleOrderPending

					FETCH NEXT FROM curSaleOrderPending INTO @curbra_id,
															 @cursoh_id,
															 @cursod_id,
															 @cursod_qty

					WHILE @@FETCH_STATUS = 0
						BEGIN

							DECLARE @datReceptionDate AS DATETIME = NULL

							IF	@decAvailableQTY >= @cursod_qty	AND
								@decAvailableQTY >  0
								BEGIN

									INSERT INTO tbSaleOrderHeader_PurchaseOrderRelation(comp_id,
																						so_bra_id,
																						so_soh_id,
																						so_sod_id,
																						po_bra_id,
																						po_poh_id,
																						po_pod_id,
																						posor_POReceived)
										VALUES(
												@comp_id,
												@curbra_id,
												@cursoh_id,
												@cursod_id,
												@bra_id,
												@poh_id,
												@pod_id,
												'False'
												)

									-- -----------------------------------------------------------------------------------
									-- MR quiere q se ponga UN DIA DESPUES de la recepcion estimada.  Ticket 13399 Claudia Muebles
									-- -----------------------------------------------------------------------------------
									SET		@datReceptionDate   = NULL
									SELECT  @datReceptionDate   = DATEADD( DAY,1, tpod.poh_estDeliveryDate)
										FROM tbPurchaseOrderHeader AS tpod	WITH (NOLOCK)
										WHERE	tpod.comp_id	= @comp_id	AND
												tpod.bra_id		= @bra_id	AND
												tpod.poh_id		= @poh_id

									UPDATE tbsaleorderdetail
										SET sod_pending4pod_IdRelation	= 0,
											sod_exclude4AvailableStock	= 1,
											sod_itemDeliveryDate		= ISNULL(@datReceptionDate,sod_itemDeliveryDate)
										WHERE	comp_id = @comp_id		AND
												bra_id	= @curbra_id	AND
												soh_id	= @cursoh_id	AND
												sod_id	= @cursod_id
									-- -----------------------------------------------------------------------------------

									SET @decAvailableQTY = @decAvailableQTY - @cursod_qty

								END
							ELSE IF @decAvailableQTY > 0	-- que DIVIDA el pedido por la cantidad que Tiene como Disponible esta OC ya que lo va a usar TODO en esta relacion.
								BEGIN						-- **lwqhf973249%&$#%$#%lkjnlkh  CM y LRCDTPM!


									EXEC spSaleOrderDetail_divideSaleOrderbySOD_Id  @comp_id,
																					@curbra_id,
																					@cursoh_id,
																					@cursod_id,
																					@decAvailableQTY,
																					0



									INSERT INTO tbSaleOrderHeader_PurchaseOrderRelation(comp_id,
																						so_bra_id,
																						so_soh_id,
																						so_sod_id,
																						po_bra_id,
																						po_poh_id,
																						po_pod_id,
																						posor_POReceived)
										VALUES(
												@comp_id,
												@curbra_id,
												@cursoh_id,
												@cursod_id,
												@bra_id,
												@poh_id,
												@pod_id,
												'False'
												)

									-- -----------------------------------------------------------------------------------
									-- MR quiere q se ponga UN DIA DESPUES de la recepcion estimada.  Ticket 13399 Claudia Muebles
									-- -----------------------------------------------------------------------------------
									SET		@datReceptionDate   = NULL
									SELECT  @datReceptionDate   = DATEADD( DAY,1, tpod.poh_estDeliveryDate)
										FROM tbPurchaseOrderHeader AS tpod	WITH (NOLOCK)
										WHERE	tpod.comp_id	= @comp_id	AND
												tpod.bra_id		= @bra_id	AND
												tpod.poh_id		= @poh_id

									UPDATE tbsaleorderdetail
										SET sod_pending4pod_IdRelation	= 0,
											sod_exclude4AvailableStock	= 1,
											sod_itemDeliveryDate		= ISNULL(@datReceptionDate,sod_itemDeliveryDate)
										WHERE	comp_id = @comp_id		AND
												bra_id	= @curbra_id	AND
												soh_id	= @cursoh_id	AND
												sod_id	= @cursod_id
									-- -----------------------------------------------------------------------------------

									SET @decAvailableQTY = 0
								END


							FETCH NEXT FROM curSaleOrderPending INTO @curbra_id,
																	 @cursoh_id,
																	 @cursod_id,
																	 @cursod_qty

						END


					CLOSE curSaleOrderPending
					DEALLOCATE curSaleOrderPending

				END


		END
		-- ------------------------------------------------------------------------------------------------------


END
GO






CREATE  PROCEDURE [dbo].[spPurchaseOrderDetail_Update4Annulment]
(
	@comp_id					INT,
	@bra_id						INT,
	@ct_transaction				INT
)
AS

BEGIN


	-- Esto es MIERDA que NO ANDA.
	-- Se anula
	RETURN


	set nocount ON


		DECLARE @lpor_id INT

		SELECT @lpor_id = ( SELECT tprh.por_id
							  FROM tbPurchaseorderReceptionHeader				tprh		WITH (NOLOCK)
							  WHERE tprh.comp_id			= @comp_id			AND
									tprh.bra_id				= @bra_id			AND
									tprh.ct_transaction		= @ct_transaction
						   )


		UPDATE tbPurchaseOrderDetail
			SET	pod_isProcessed		= 'False'

			FROM tbPurchaseOrderDetail						pod		WITH (NOLOCK)

			INNER JOIN tbPurchaseorderReceptionDetail		tprd	WITH (NOLOCK)
			ON	tprd.comp_id		= pod.comp_id	AND
				tprd.poh_bra_id		= pod.bra_id	AND
				tprd.poh_id			= pod.poh_id	AND
				tprd.pod_id			= pod.pod_id

			WHERE   tprd.comp_id    = @comp_id	AND
					tprd.por_id		= @lpor_id




		UPDATE tbPurchaseorderReceptionHeader
			SET		por_isCancelled		= 'True'
			WHERE	comp_id				= @comp_id			AND
					bra_id				= @bra_id			AND
					ct_transaction		= @ct_transaction



END
GO





-- DATA : RECIBIR CON LA OPCION SOLO CONFIRMAR.



CREATE  PROCEDURE [dbo].[spPurchaseOrderDetail_updateConfirmedQTY]
(
	@comp_id					int,
	@por_id						int,
	@guid						UNIQUEIDENTIFIER,
	@user_id					int
)
AS

BEGIN

	set nocount ON



	--SI EL INGRESO ES PARCIAL GENERA EL OTRO REGISTRO CON LA OTRA PARTE Y NO PROCESADO.
	INSERT INTO tbPurchaseOrderDetail
			(	comp_id,bra_id,poh_id,item_id,
				curr_id,cont_id,pod_qty,pod_price,
				tax_id,pod_isProcessed,pod_obs,
				pod_priceB,pod_custom,pod_customNumber,
				pod_Discount1,pod_Discount2,pod_Discount3,
				pod_Discount4,djai_id,pod_initQty,
				pod_surcharge1, pod_surcharge2,
				pod_surcharge3, pod_surcharge4, pod_priceWithDiscountAndCharges,
				simi_id, simid_id, pod_Origin, pod_From, pod_Stamp, pod_LotNumber,
				pod_ExpirationDate, pod_includeInAvailableStock,pod_id_from
			)
			SELECT
				tpod.comp_id,tpod.bra_id,tpod.poh_id,
				tpod.item_id,tpod.curr_id,tpod.cont_id,
				tpod.pod_qty - tprd.pord_qty,
				tpod.pod_price,tpod.tax_id,'False',
				tpod.pod_obs,tpod.pod_priceB,tpod.pod_custom,
				tpod.pod_customNumber,tpod.pod_Discount1,
				tpod.pod_Discount2,tpod.pod_Discount3,
				tpod.pod_Discount4,tpod.djai_id,tpod.pod_qty - tprd.pord_qty,
				tpod.pod_surcharge1,
				tpod.pod_surcharge2,
				tpod.pod_surcharge3,
				tpod.pod_surcharge4,
				tpod.pod_priceWithDiscountAndCharges,
				tpod.simi_id,
				tpod.simid_id,
				tpod.pod_Origin,
				tpod.pod_From,
				tpod.pod_Stamp,
				tpod.pod_LotNumber,
				tpod.pod_ExpirationDate,
				tpod.pod_includeInAvailableStock,
				tpod.pod_id
				FROM tbPurchaseOrderDetail tpod					WITH (NOLOCK)
				INNER JOIN tbPurchaseorderReceptionDetail tprd	WITH (NOLOCK)
					ON	tprd.comp_id	= tpod.comp_id	AND
						tprd.poh_bra_id = tpod.bra_id	AND
						tprd.poh_id		= tpod.poh_id	AND
						tprd.pod_id		= tpod.pod_id
				WHERE   tprd.comp_id    = @comp_id	AND
						tprd.por_id		= @por_id   AND
						tpod.pod_qty	<> tprd.pord_qty


	-- SI EL INGRESO ES PARCIAL ACTUALIZA CANT CONFIRMADA , LE RESTA A LA CANT LA PARTE PARCIAL Y QUEDA PROCESADO EL REGISTRO ORIGINAL.
	-- Y SE TIENE QUE GENERAR EL OTRO REGISTRO CON LA OTRA PARTE Y NO PROCESADO. lo hace primero
	UPDATE tbPurchaseOrderDetail
		SET	pod_confirmedQTY	= tprd.pord_qty,
			pod_qty				= tprd.pord_qty,
			pod_isProcessed		= 'True'
		FROM tbPurchaseOrderDetail pod					WITH (NOLOCK)
		INNER JOIN tbPurchaseorderReceptionDetail tprd	WITH (NOLOCK)
		ON	tprd.comp_id	= pod.comp_id	AND
			tprd.poh_bra_id = pod.bra_id	AND
			tprd.poh_id		= pod.poh_id	AND
			tprd.pod_id		= pod.pod_id
		WHERE   tprd.comp_id    = @comp_id	AND
				tprd.por_id		= @por_id   AND
				pod.pod_qty		<> tprd.pord_qty




	-- SI EL INGRESO ES TOTAL QUEDA PROCESADO.  -->> En serio, dos update al PEDO, seguidos ?????   en serio ????
	UPDATE tbPurchaseOrderDetail
		SET	pod_isProcessed				= 'True'
		FROM tbPurchaseOrderDetail pod
		INNER JOIN tbPurchaseorderReceptionDetail tprd
		ON	tprd.comp_id	= pod.comp_id	AND
			tprd.poh_bra_id = pod.bra_id	AND
			tprd.poh_id		= pod.poh_id	AND
			tprd.pod_id		= pod.pod_id
		WHERE   tprd.comp_id    = @comp_id	AND
				tprd.por_id		= @por_id	AND
				pod.pod_qty		= tprd.pord_qty




	--QUEDA CERRADA LA RECEPCION Y SE GRABA EL USUARIO QUE HIZO LA RECEPCION
	UPDATE tbPurchaseorderReceptionHeader
		SET	    por_isClosed			= 'True',
				user_id_closeReception	= @user_id
		WHERE	comp_id = @comp_id AND
				por_id	= @por_id


END
GO







CREATE procedure [dbo].[spPurchaseOrderDetail_updateData]
(
	@comp_id			int,
	@bra_id				int,
	@poh_id				int,
	@pod_id				int,
	@item_id			int,
	@curr_id			int,
	@cont_id			int,
	@pod_qty			decimal(19,5),
	@pod_price			decimal(19,6),
	@tax_id				int,
	@obser				NVARCHAR(500),
	@pod_isProcessed	BIT,
	@priceB				DECIMAL(16,5),
	@custom				VARCHAR(50),
	@customNumber		VARCHAR(50)
)
as

set nocount on


update dbo.[tbPurchaseOrderDetail]



set		item_id				= @item_id,
		curr_id				= @curr_id,
		cont_id				= @cont_id,
		pod_qty				= @pod_qty,
		pod_price			= @pod_price,
		tax_id				= @tax_id,
		pod_obs				= @obser,
		pod_isProcessed		= @pod_isProcessed,
		pod_priceB			= @priceB,
		pod_custom			= @custom,
		pod_customNumber	= @customNumber




where	[comp_id]			= @comp_id
and		[bra_id]			= @bra_id
and	    [poh_id]			= @poh_id
and	    [pod_id]			= @pod_id
GO








CREATE  PROCEDURE [dbo].[spPurchaseOrderDetail_updateIsEditing]
(
	@comp_id					int,
	@bra_id						int,
	@guid						UNIQUEIDENTIFIER,
	@state						bit
)
AS

BEGIN



	set nocount ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	/*
	DECLARE  	@comp_id					int,
				@bra_id						int,
				@guid						UNIQUEIDENTIFIER,
				@state						bit

	SELECT		@comp_id					= 1,
				@bra_id						= 1,
				@guid						='30c2732a-2684-44ac-84fb-c8b5fff7cadb',
				@state						= 'False'
	*/



	UPDATE	tbPurchaseOrderDetail	WITH (ROWLOCK)

	SET		pod_isEditing		= @state,
			pod_isEditingCd		= GETDATE()

	FROM	tbPurchaseOrderDetail		tpod

			JOIN tbItemTransactionsTmp	titt		WITH (NOLOCK)
			ON	titt.comp_id	= tpod.comp_id
			--AND titt.bra_id		= tpod.bra_id	-- MOS 11-2019
			AND titt.poh_id		= tpod.poh_id
			AND titt.pod_id		= tpod.pod_id

	WHERE	tpod.comp_id		= @comp_id
	--AND		tpod.bra_id			= @bra_id  -- MOS 11-2019
	AND		titt.tis_guid		= @guid


	IF @state = 'False'
		BEGIN
			DELETE FROM tbPurchaseConceptMovementsTmp
				WHERE pcmt_guid = @guid

			DELETE FROM tbTaxMovementsTmp
				WHERE tmt_guid = @guid
		END



END
GO

CREATE PROCEDURE spPurchaseOrderDetail_UpdateOriginData
(
	@comp_id			INT,
	@poh_id				INT,
	@pod_id				INT,
	@pod_Origin			NVARCHAR(200),
	@pod_From			NVARCHAR(200),
	@pod_Stamp			NVARCHAR(200),
	@pod_LotNumber		NVARCHAR(50),
	@pod_ExpirationDate	DATETIME
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		UPDATE tbPurchaseOrderDetail
		SET
			pod_Origin			= @pod_Origin,
			pod_From			= @pod_From,
			pod_Stamp			= @pod_Stamp,
			pod_LotNumber		= @pod_LotNumber,
			pod_ExpirationDate	= @pod_ExpirationDate
			WHERE	comp_id		= @comp_id	AND
					poh_id		= @poh_id	AND
					pod_id		= @pod_id
	END
GO

