CREATE PROCEDURE [dbo].[spPurchaseOrderDetail_ValidateData4ExcelInsert]
(
	@comp_id	INT,
	@item_ean	NVARCHAR(50),
	@curr_id	INT,
	@cont_id	INT,
	@intDjai	INT,
	@simi_id	INT,
	@simid_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_ean	NVARCHAR(30),
				@curr_id	INT,
				@cont_id	INT,
				@intDjai	INT,
				@simi_id	INT,
				@simid_id	INT
		*/
		-- -----------------------------------------------------------

		DECLARE
			@strErrorMessage	NVARCHAR(4000),
			@bolHasErrores		BIT
		SET @strErrorMessage	= ''
		SET @bolHasErrores		= 'False'
		-- -----------------------------------------------------------------
		-- VALIDAR EAN DEL ARTICULO
		-- -----------------------------------------------------------------
		DECLARE @lintItemID AS integer = NULL
		SELECT
			@lintItemID = ti.item_id
		FROM tbItem							AS ti WITH(NOLOCK)
		WHERE	ti.comp_id		= @comp_id	AND
				ti.item_code	= @item_ean

		IF @lintItemID IS NULL
			BEGIN
				SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El Código EAN ingresado no corresponde con ningún artículo existente en el sistema.'
				SET @bolHasErrores		= 'True'
			END
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------
		-- VALIDAR ID DE MONEDA
		-- -----------------------------------------------------------------
		IF @curr_id <> -1
			BEGIN
				IF NOT EXISTS (SELECT 1 FROM tbsysCurrency AS tc WHERE tc.curr_id = @curr_id)
					BEGIN
						SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El ID de Moneda ingresado no corresponde con ningún ID de moneda existente en el Sistema.'
						SET @bolHasErrores		= 'True'
					END
			END
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------
		-- VALIDO CONTENEDOR
		-- -----------------------------------------------------------------
		IF @cont_id <> -1
			BEGIN
				IF NOT EXISTS (SELECT
								1
								FROM tbContainer					AS tc WITH(NOLOCK)
								WHERE	tc.comp_id = @comp_id	AND
										tc.cont_id = @cont_id)
					BEGIN
						SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El ID de Contenedor  ingresado no corresponde con ningún ID de Contenedor existente en el Sistema.'
						SET @bolHasErrores		= 'True'
					END
			END
		-- -----------------------------------------------------------------


		-- -----------------------------------------------------------------
		-- VALIDO LAS DJAI
		-- -----------------------------------------------------------------
		IF @intDjai <> -1
			BEGIN
				IF NOT EXISTS (SELECT
								1
								FROM tbCustoms_DJAI				AS tcd WITH(NOLOCK)
								WHERE	tcd.comp_id = @comp_id	AND
										tcd.djai_id = @intDjai)
					BEGIN
						SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El ID de DJAI  ingresado no corresponde con ningún ID de DJAI existente en el Sistema.'
						SET @bolHasErrores		= 'True'
					END
			END
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------
		-- VALIDO LAS SIMI
		-- -----------------------------------------------------------------
		IF @simi_id <> -1 --SI INGRESO UN SIMI
			BEGIN
				IF NOT EXISTS (SELECT
								1
								FROM tbImport_SIMIHeader		AS tis WITH (NOLOCK)
								WHERE	tis.comp_id = @comp_id	AND
										tis.simi_id = @simi_id)
					BEGIN
						SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El ID de S.I.M.I  ingresado no corresponde con ningún ID de S.I.M.I existente en el Sistema.'
						SET @bolHasErrores		= 'True'
					END
				ELSE
					BEGIN
						IF @simid_id <> -1 --SI INGRESO UN SIMID
							BEGIN
								IF NOT EXISTS(SELECT
												1
												FROM tbImport_SIMIDetail			AS tis WITH(NOLOCK)
												WHERE	tis.comp_id		= @comp_id	AND
														tis.simi_id		= @simi_id	AND
														tis.simid_id	= @simid_id)
									BEGIN
										SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El ID de S.I.M.I Detalle  ingresado no corresponde con ningún ID de S.I.M.I Detalle existente en el Sistema.'
										SET @bolHasErrores		= 'True'
									END
							END
						ELSE
							BEGIN --SI INGRESO UN SIMI PERO NO INGRESO UN SIMID
								SET @strErrorMessage	= @strErrorMessage + ' / ' + 'Si selecciona un ID de S.I.M.I deberá también elegir un ID de S.I.M.I Detalle.'
								SET @bolHasErrores		= 'True'
							END
					END
			END
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------
		-- VALIDAMOS QUE TENGA ITEM_TAXES
		-- -----------------------------------------------------------------
			IF @lintItemID IS NOT NULL
				BEGIN
					IF (SELECT COUNT(ttn.tax_id)
							FROM	dbo.tbItem							ti	WITH(NOLOCK)
							INNER JOIN  dbo.tbItemTaxes					tit	WITH(NOLOCK)
								ON  tit.comp_id			= ti.comp_id	AND
									tit.item_id			= ti.item_id
							INNER JOIN tbTaxName						ttn	WITH(NOLOCK)
								ON  ttn.comp_id			= tit.comp_id	AND
									ttn.tax_id			= tit.tax_id
							INNER JOIN vwsysTaxClassIVA_Taxes			vtcit	WITH(NOLOCK)
								ON 	vtcit.tax_class		= ttn.tax_class
							WHERE	ti.comp_id			= @comp_id		AND
									ti.item_id			= @lintItemID) = 0
						BEGIN
							SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El artículo con el Código EAN ingresado no tiene impuestos asociados.'
							SET @bolHasErrores		= 'True'
						END
				END
		-- -----------------------------------------------------------------


		SELECT
			@lintItemID			[item_id],
			@bolHasErrores		[HasErrors],
			@strErrorMessage	[ErrorMessage]


	END
GO






