create procedure [dbo].[spPurchaseOrderDetailTmp_deleteAllData]
(
	@podt_guid			uniqueidentifier
)
as
set nocount on

Delete	dbo.tbPurchaseOrderDetailTmp

where	podt_guid		= @podt_guid



GO







CREATE  PROCEDURE [dbo].[spPurchaseOrderDetailTmp_deleteData]
(
		@podt_id			int
)
as

BEGIN

	set nocount on

	IF EXISTS	(
					SELECT TOP 1 1
						FROM tbPurchaseOrderDetailTmp AS tpodt							WITH (NOLOCK)
						INNER JOIN	tbSaleOrderHeader_PurchaseOrderRelation AS tsohpor	WITH (NOLOCK)
							ON	tsohpor.comp_id		= tpodt.comp_id AND
								tsohpor.po_bra_id	= tpodt.bra_id	AND
								tsohpor.po_pod_id	= tpodt.pod_id
						WHERE   tpodt.podt_id 		= @podt_id
				)
		BEGIN
			SELECT -1
			RETURN
		END



	Delete	dbo.tbPurchaseOrderDetailTmp
		FROM tbPurchaseOrderDetailTmp tmp
		where	podt_id			= @podt_id

		--AND
		--		NOT EXISTS(	SELECT 1
		--		           		FROM tbPurchaseorderReceptionDetail tprd
		--		           		WHERE tprd.pod_id = tmp.pod_id )

END
GO









CREATE PROCEDURE [dbo].[spPurchaseOrderDetailTmp_deleteOldData]
as
set nocount on

/*
declare @comp_id	int
select	@comp_id	= 1
*/

declare @time		int
set		@time		= -120000


declare @comp_id	int

declare cursor_PODT_dOD cursor for
select	comp_id
from	tbCompany

open	cursor_PODT_dOD

fetch next from cursor_PODT_dOD
into	@comp_id

while @@fetch_status = 0
begin

	delete	dbo.tbPurchaseOrderDetailTmp
	where	dbo.tbPurchaseOrderDetailTmp.comp_id		=	@comp_id
	and		dbo.tbPurchaseOrderDetailTmp.podt_guid in (
											select	distinct tdat.podt_guid
											from	dbo.tbPurchaseOrderDetailTmp tdat
											where	tdat.comp_id		=	@comp_id
											and		tdat.podt_cd		<	DATEADD(minute, @time, getdate())
											)

	fetch next from cursor_PODT_dOD
	into	@comp_id

end

close		cursor_PODT_dOD
deallocate	cursor_PODT_dOD




GO



CREATE PROCEDURE [dbo].[spPurchaseOrderDetailTmp_getData]
(
	@comp_id				INT,
	@podt_guid				UNIQUEIDENTIFIER,
	@curr_id				INT,
	@curr_id_other			INT,
	@currExchange			DECIMAL(19,6),
	@discount1				DECIMAL(19,6),
	@discount2				DECIMAL(19,6),
	@discount3				DECIMAL(19,6),
	@discount4				DECIMAL(19,6),
	@supp_id				INT
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	SET NOCOUNT ON


-- -----------------------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------------------
/*
	declare @comp_id				INT,
			@podt_guid				UNIQUEIDENTIFIER,
			@curr_id				INT,
			@curr_id_other			INT,
			@currExchange			DECIMAL(19,6),
			@discount1				DECIMAL(19,6),
			@discount2				DECIMAL(19,6),
			@discount3				DECIMAL(19,6),
			@discount4				DECIMAL(19,6),
			@supp_id				INT

	select	@comp_id			=1,
			@podt_guid			= 'cae0750d-fa21-4c93-b679-2f8a88c29796',
			@curr_id			=1,
			@curr_id_other		=1,
			@currExchange		=1,
			@discount1			= 10,
			@discount2			= 0,
			@discount3			= 0,
			@discount4			= 0,
			@supp_id			= 8110
*/
-- -----------------------------------------------------------------------------

	-- ATENCION!!!
	-- Los tipos de IVA se obtienen pasando DESDE el Proveedor HACIA Nuestra Sucursal







	-- -----------------------------------------------------------------------------
	--OJOOOOOO
	-- NO tocar el ORDEN de los campos ya que el HDRMP que hizo el calculo aca lo hizo x loi q va en las columnas de la query
	--OJOOOOOO
	-- -----------------------------------------------------------------------------


	select	' ' [ ], ' ' [ ],
			convert(bit,podt.podt_isProcessed) [podt_isProcessed],
			podt.podt_guid,
			podt.item_id,
			i.[item_code],
			i.item_vendorCode,
			i.item_desc,
			convert(decimal(19,2),round(podt.podt_qty,2))			[podt_qty],
			ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
			podt.curr_id,
			c.curr_symbol											[curr_desc],

			convert(decimal(19,2),
				isnull(
					round((podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price)),2),0))	[subtotal],


	--		convert(decimal(19,2),
	--			isnull(
	--				round(
	--					(dbo.[fnGetExchange](@comp_id, podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price), podt.curr_id, @curr_id , 0, 0, 'False')),2),0))
	--																[subtotal_branch_curr],
			convert(decimal(19,2),
				isnull(
					round(
						(dbo.[fnGetExchange2](	@comp_id,
												podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
												podt.curr_id,
												@curr_id_other,
												@curr_id_other,
												@curr_id,
												@currExchange,
												'False')),2),0))
																	[subtotal_branch_curr],




	--		convert(decimal(19,2),
	--			isnull(
	--				round(
	--					(dbo.[fnGetExchange](@comp_id, podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price), podt.curr_id, @curr_id , 0, 0, 'False') *
	--					dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id,0,0,0,0,NULL) / 100 ),2),0))
	--																[tax_branch_curr],
			convert(decimal(19,2),
				isnull(
					round(
						(dbo.[fnGetExchange2](	@comp_id,
												podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
												podt.curr_id,
												@curr_id_other,
												@curr_id_other,
												@curr_id,
												@currExchange,
												'False') *
						dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id, ts.country_id, b.country_id, ts.state_id, b.state_id,NULL) / 100 ),2),0))
																	[tax_branch_curr],



	--		convert(decimal(19,2),
	--			isnull(
	--				round(
	--					(dbo.[fnGetExchange](@comp_id, podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price), podt.curr_id, @curr_id , 0, 0, 'False') +
	--					(dbo.[fnGetExchange](@comp_id, podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price), podt.curr_id, @curr_id , 0, 0, 'False') *
	--					dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id,0,0,0,0,NULL) / 100)),2),0))
	--																[total_branch_curr],
			convert(decimal(19,2),
				isnull(
					round(
						(dbo.[fnGetExchange2](	@comp_id,
												podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
												podt.curr_id,
												@curr_id_other,
												@curr_id_other,
												@curr_id,
												@currExchange,
												'False') +
						(dbo.[fnGetExchange2](	@comp_id,
												podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
												podt.curr_id,
												@curr_id_other,
												@curr_id_other,
												@curr_id,
												@currExchange,
												'False') *
						dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id,ts.country_id, b.country_id, ts.state_id, b.state_id,NULL) / 100)),2),0))
																	[total_branch_curr],  -- Cells(6)

			--convert(decimal(19,2),
			--	isnull(
			--		round(
			--			(dbo.[fnGetExchange2](	@comp_id,
			--									podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
			--									podt.curr_id,
			--									ts.curr_id,
			--									@curr_id_other,
			--									@curr_id,
			--									@currExchange,
			--									'False') +
			--			(dbo.[fnGetExchange2](	@comp_id,
			--									podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
			--									podt.curr_id,
			--									ts.curr_id,
			--									@curr_id_other,
			--									@curr_id,
			--									@currExchange,
			--									'False') *
			--			dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id,ts.country_id, b.country_id, ts.state_id, b.state_id,NULL) / 100)),2),0))
			--														[total_supp_curr],	-- cells(7)

			podt.bra_id,
			b.bra_desc,
			podt.cont_id,
			t.cont_desc,
			podt.tax_id,
			it.tax_desc,
			podt.podt_obs,


			--Parte 681 STL Agregado de los 3 nuevos campos para que se vean en la grilla

			ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price)B,
			podt.podt_custom,
			podt.podt_customNumber,
			ISNULL(i.item_expser,'False')	[item_expser],
			ISNULL(podt.pod_Discount1,0)	[pod_Discount1],
			ISNULL(podt.pod_Discount2,0)	[pod_Discount2],
			ISNULL(podt.pod_Discount3,0)	[pod_Discount3],
			ISNULL(podt.pod_Discount4,0)	[pod_Discount4],
			ISNULL(podt.pod_surcharge1,0)	[pod_surcharge1],
			ISNULL(podt.pod_surcharge2,0)	[pod_surcharge2],
			ISNULL(podt.pod_surcharge3,0)	[pod_surcharge3],
			ISNULL(podt.pod_surcharge4,0)	[pod_surcharge4],


			podt.podt_id	[ID]


	from	dbo.tbPurchaseOrderDetailTmp		podt		WITH (NOLOCK)

			left join dbo.[tbItem]				i		WITH (NOLOCK)
			on	i.comp_id		= podt.comp_id
			and	i.[item_id]		= podt.[item_id]

			left join dbo.[tbsysCurrency]		c		WITH (NOLOCK)
			on	c.[curr_id]		= podt.[curr_id]

			left join dbo.[tbBranch]			b		WITH (NOLOCK)
			on	b.[comp_id]		= podt.[comp_id]
			and b.[bra_id]		= podt.[bra_id]

			left join dbo.[tbContainer]			t		WITH (NOLOCK)
			on  t.[comp_id]		= podt.[comp_id]
			and t.[cont_id]		= podt.[cont_id]

			left join dbo.[tbTaxName]	        it		WITH (NOLOCK)
			on	it.[comp_id]	= podt.[comp_id]
			and it.[tax_id]		= podt.[tax_id]

			INNER JOIN tbSupplier ts		WITH (NOLOCK)
				ON	ts.comp_id = @comp_id AND
					ts.supp_id = @supp_id

	where	podt.comp_id		=	@comp_id
	and		podt.podt_guid		=	@podt_guid


	order by podt.[podt_id]



	-- TOTALES
	-- MOS 03-2022: Se cambia @curr_id_other x b.curr_id para que queden los totales en la moneda de la SUCURSAL y el segundo renglon en la moneda del Proveedor
	select	sum(convert(decimal(19,2),round(podt.podt_qty,2)))
			[podt_qty],

			sum(
				convert(decimal(19,2),
					isnull(
						round(
							(podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price)),2),0)))
																[subtotal],


			sum(
				convert(decimal(19,2),
					isnull(
						round(
							(dbo.[fnGetExchange2](	@comp_id,
													podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
													podt.curr_id,
													b.curr_id,
													@curr_id_other,
													@curr_id,
													@currExchange,
													'False')),2),0)))
																[subtotal_branch_curr],


			sum(
				convert(decimal(19,2),
					isnull(
						round(
							(dbo.[fnGetExchange2](	@comp_id,
													podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
													podt.curr_id,
													b.curr_id,
													@curr_id_other,
													@curr_id,
													@currExchange,
													'False') *
							dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id,ts.country_id, b.country_id, ts.state_id, b.state_id,NULL) / 100 ),2),0)))
																[tax_branch_curr],


			sum(
				convert(decimal(19,2),
					isnull(
						round(
							(dbo.[fnGetExchange2](	@comp_id,
													podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
													podt.curr_id,
													b.curr_id,
													@curr_id_other,
													@curr_id,
													@currExchange,
													'False') +
							(dbo.[fnGetExchange2](	@comp_id,
													podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
													podt.curr_id,
													b.curr_id,
													@curr_id_other,
													@curr_id,
													@currExchange,
													'False') *
							dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id,ts.country_id, b.country_id, ts.state_id, b.state_id,NULL) / 100)),2),0)))
																[total_branch_curr],


			-- MOS 03-2022: Nuevo, Total en la Moneda del Proveedor SI o SI
			SUM(
			convert(decimal(19,2),
				isnull(
					round(
						(dbo.[fnGetExchange2](	@comp_id,
												podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
												podt.curr_id,
												ts.curr_id,
												@curr_id_other,
												@curr_id,
												@currExchange,
												'False') +
						(dbo.[fnGetExchange2](	@comp_id,
												podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
												podt.curr_id,
												ts.curr_id,
												@curr_id_other,
												@curr_id,
												@currExchange,
												'False') *
						dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id,ts.country_id, b.country_id, ts.state_id, b.state_id,NULL) / 100)),2),0)))
																		[total_supp_curr],	-- cells(5)
						ctp.curr_symbol									[supp_currency],	-- cells(6)
						ctb.curr_symbol									[branch_currency],	-- cells(7)
						SUM(podt.podt_qty * ISNULL(i.item_weight,0)) / 1000
																		[total_Weight]		-- cells(8)  Pseo en KILOS


		from	dbo.tbPurchaseOrderDetailTmp		podt		WITH (NOLOCK)

				left join dbo.[tbItem]				i		WITH (NOLOCK)
				on	i.comp_id		= podt.comp_id
				and	i.[item_id]		= podt.[item_id]

				left join dbo.[tbsysCurrency]		c		WITH (NOLOCK)
				on	c.[curr_id]		= podt.[curr_id]

				left join dbo.[tbBranch]			b		WITH (NOLOCK)
				on	b.[comp_id]		= podt.[comp_id]
				and b.[bra_id]		= podt.[bra_id]

				left join dbo.[tbContainer]			t		WITH (NOLOCK)
				on  t.[comp_id]		= podt.[comp_id]
				and t.[cont_id]		= podt.[cont_id]

				left join dbo.[tbTaxName]	        it		WITH (NOLOCK)
				on	it.[comp_id]	= podt.[comp_id]
				and it.[tax_id]		= podt.[tax_id]


				INNER JOIN tbSupplier ts		WITH (NOLOCK)
					ON	ts.comp_id = @comp_id AND
						ts.supp_id = @supp_id

				INNER JOIN tbsysCurrency AS ctP		WITH (NOLOCK)
					ON ctP.curr_id = ts.curr_id

				INNER JOIN tbsysCurrency AS ctB		WITH (NOLOCK)
					ON ctB.curr_id = b.curr_id


		where	podt.comp_id		=	@comp_id
		and		podt.podt_guid		=	@podt_guid

		group by podt.podt_guid,ctp.curr_symbol,ctb.curr_symbol

	--select	sum(convert(decimal(19,2),round(podt.podt_qty,2)))
	--		[podt_qty],

	--		sum(
	--			convert(decimal(19,2),
	--				isnull(
	--					round(
	--						(podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price)),2),0)))
	--															[subtotal],


	--		sum(
	--			convert(decimal(19,2),
	--				isnull(
	--					round(
	--						(dbo.[fnGetExchange2](	@comp_id,
	--												podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
	--												podt.curr_id,
	--												@curr_id_other,
	--												@curr_id_other,
	--												@curr_id,
	--												@currExchange,
	--												'False')),2),0)))
	--															[subtotal_branch_curr],


	--		sum(
	--			convert(decimal(19,2),
	--				isnull(
	--					round(
	--						(dbo.[fnGetExchange2](	@comp_id,
	--												podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
	--												podt.curr_id,
	--												@curr_id_other,
	--												@curr_id_other,
	--												@curr_id,
	--												@currExchange,
	--												'False') *
	--						dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id,ts.country_id, b.country_id, ts.state_id, b.state_id,NULL) / 100 ),2),0)))
	--															[tax_branch_curr],


	--		sum(
	--			convert(decimal(19,2),
	--				isnull(
	--					round(
	--						(dbo.[fnGetExchange2](	@comp_id,
	--												podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
	--												podt.curr_id,
	--												@curr_id_other,
	--												@curr_id_other,
	--												@curr_id,
	--												@currExchange,
	--												'False') +
	--						(dbo.[fnGetExchange2](	@comp_id,
	--												podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
	--												podt.curr_id,
	--												@curr_id_other,
	--												@curr_id_other,
	--												@curr_id,
	--												@currExchange,
	--												'False') *
	--						dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id,ts.country_id, b.country_id, ts.state_id, b.state_id,NULL) / 100)),2),0)))
	--															[total_branch_curr],
	--		SUM(
	--		convert(decimal(19,2),
	--			isnull(
	--				round(
	--					(dbo.[fnGetExchange2](	@comp_id,
	--											podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
	--											podt.curr_id,
	--											ts.curr_id,
	--											@curr_id_other,
	--											@curr_id,
	--											@currExchange,
	--											'False') +
	--					(dbo.[fnGetExchange2](	@comp_id,
	--											podt.podt_qty * ISNULL(podt.pod_priceWithDiscountAndCharges,podt.podt_price),
	--											podt.curr_id,
	--											ts.curr_id,
	--											@curr_id_other,
	--											@curr_id,
	--											@currExchange,
	--											'False') *
	--					dbo.fnGetTaxPercentage4Suppliers (@comp_id, podt.bra_id, podt.tax_id,ts.country_id, b.country_id, ts.state_id, b.state_id,NULL) / 100)),2),0)))
	--																[total_supp_curr],	-- cells(5)
	--					ctp.curr_symbol								[supp_currency],	-- cells(6)
