CREATE PROCEDURE [dbo].[spPurchaseOrderDetailTmp_getDataById]
(
	@podt_id		int
)
as
set nocount on
/*
declare @dacc_transaction			int
select @dacc_transaction			=3
*/
select	' ' [ ], ' ' [ ],
		podt.podt_guid,
		podt.item_id,
		i.item_desc,
		podt.curr_id,
		c.curr_desc,
		podt.bra_id,
		b.bra_desc,
		podt.cont_id,
		t.cont_desc,
		podt.tax_id,
		it.tax_desc,
		podt.podt_qty,
		podt.podt_price,
		i.item_code,
		i.posara_id,
		isnull(podt.podt_obs,'')				[podt_obs],
		isnull(podt.podt_priceB,0)				[podt_priceB],
		isnull(podt.podt_custom,'')				[podt_custom],
		isnull(podt.podt_customNumber,'')		[podt_customNumber],
		isnull(podt.pod_Discount1,0)			[pod_Discount1],
		isnull(podt.pod_Discount2,0)			[pod_Discount2],
		isnull(podt.pod_Discount3,0)			[pod_Discount3],
		isnull(podt.pod_Discount4,0)			[pod_Discount4],
		isNull(podt.pod_surcharge1,0)			[pod_surcharge1],
		isNull(podt.pod_surcharge2,0)			[pod_surcharge2],
		isNull(podt.pod_surcharge3,0)			[pod_surcharge3],
		isNull(podt.pod_surcharge4,0)			[pod_surcharge4],
		ISNULL(podt.djai_id,0)					[djai_id],
		ISNULL(podt.podt_isProcessed,'False')	[podt_isProcessed],
		podt.simi_id,
		podt.simid_id,
		ISNULL(podt.pod_Origin,'')							[pod_Origin],
		ISNULL(podt.pod_From,'')							[pod_From],
		ISNULL(podt.pod_Stamp,'')							[pod_Stamp],
		ISNULL(podt.pod_LotNumber,'')						[pod_LotNumber],
		podt.pod_ExpirationDate,
		ISNULL(podt.pod_includeInAvailableStock,'False')	[pod_includeInAvailableStock],
		podt.stor_id										[stor_id],
		podt.podt_id										[ID]

from	dbo.tbPurchaseOrderDetailTmp		podt

		left join dbo.[tbItem]				i
		on	i.comp_id		= podt.comp_id
		and	i.[item_id]		= podt.[item_id]

		left join dbo.[tbsysCurrency]		c
		on	c.[curr_id]		= podt.[curr_id]

		left join dbo.[tbBranch]			b
		on	b.[comp_id]		= podt.[comp_id]
		and b.[bra_id]		= podt.[bra_id]

		left join dbo.[tbContainer]			t
		on  t.[comp_id]		= podt.[comp_id]
		and t.[cont_id]		= podt.[cont_id]

		left join dbo.[tbTaxName]	        it
		on	it.[comp_id]	= podt.[comp_id]
		and it.[tax_id]		= podt.[tax_id]

where	podt.podt_id	=	@podt_id

order by podt.podt_id






















GO







CREATE PROCEDURE [dbo].[spPurchaseOrderDetailTmp_insertData]
(
		@comp_id			INT,
		@podt_guid			UNIQUEIDENTIFIER,
		@item_id			INT,
		@curr_id			INT,
		@bra_id				INT,
		@cont_id			INT,
		@tax_id				INT,
		@podt_qty			DECIMAL(19,5),
		@podt_price			DECIMAL(19,6),
		@podt_isprocessed	BIT,
		@obser              NVARCHAR(500),
		@priceB				DECIMAL(19,6),
		@custom				VARCHAR(50),
		@customnumber		VARCHAR(50),
		@return_value		INT OUTPUT

)
AS
	BEGIN
		SET NOCOUNT ON

			--SI VIENE EL TAX_ID = -1 GRABAMOS NULL
			DECLARE
				@intTax_ID	INT

			IF @tax_id = -1
				BEGIN
					SET @intTax_ID = NULL
				END
			ELSE
				BEGIN
					SET @intTax_ID = @tax_id
				END


		INSERT INTO dbo.tbPurchaseOrderDetailTmp
		(
			comp_id,
			podt_guid,
			item_id,
			curr_id,
			bra_id,
			cont_id,
			tax_id,
			podt_qty,
			podt_price,
			podt_cd,
			podt_isprocessed,
			podt_obs,
			podt_priceB,
			podt_custom,
			podt_customNumber
		)
		VALUES
		(
			@comp_id,
			@podt_guid,
			@item_id,
			@curr_id,
			@bra_id,
			@cont_id,
			@intTax_ID,
			@podt_qty,
			@podt_price,
			GETDATE(),
			@podt_isprocessed,
			@obser,
			@priceB,
			@custom,
			@customnumber
		)

		SET	@return_value = @@IDENTITY

	END



GO





