CREATE PROCEDURE [dbo].[spPurchaseOrderDetailTMP_UpdateQty_UPB]
(
	@comp_id		INT,
	@podt_id		INT,
	@podt_qty		DECIMAL(19,5),
	@item_id		INT


)
AS
	SET NOCOUNT ON

	BEGIN

		--------------------------------------------------------
		-- Guardamos el upb del item
		DECLARE @litem_upb DECIMAL(18,4)

		SET	@litem_upb  = (SELECT
			ti.item_upb
			FROM tbItem									ti WITH (NOLOCK)
			WHERE	ti.comp_id	= @comp_id		AND
					ti.item_id	= @item_id)
		--------------------------------------------------------

		--------------------------------------------------------
		-- Calculo final con upb
		DECLARE @lqtywithupb DECIMAL(18,4)
		SET	@lqtywithupb  =
		CASE @podt_qty % dbo.fnNoZDiv(@litem_upb) WHEN 0 THEN
			@podt_qty
		ELSE
			@podt_qty + ( @litem_upb - (@podt_qty % dbo.fnNoZDiv(@litem_upb)))

		END
		--------------------------------------------------------



		UPDATE tbPurchaseOrderDetailTmp

			SET podt_qty = @lqtywithupb
			WHERE	comp_id		= @comp_id	AND
					podt_id		= @podt_id

	END
GO


