CREATE PROCEDURE [dbo].[spPurchaseOrderHeader_getDataByFilters]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@supp_id			int,
	@item_id			int,
	@estdatefrom		datetime,
	@estdateto			datetime,
	@datefrom			datetime,
	@dateto				datetime,
	@ptr_id				int,
	@pt_id				int,
	@poh_quotation		int,
	@pod_isProcessed	INT,
	@pro_id				INT,
	@poh_id				INT
)
as



BEGIN



	set nocount on
	set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------







	-- -------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------
	/*
	declare @comp_id			int,
			@lang_id			int,
			@bra_id				int,
			@supp_id			int,
			@item_id			int,
			@estdatefrom		datetime,
			@estdateto			datetime,
			@datefrom			datetime,
			@dateto				datetime,
			@ptr_id				int,
			@pt_id				int,
			@poh_quotation		int,
			@pod_isProcessed	int,
			@pro_id				INT,
			@poh_id				INT

	select	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@supp_id			=-1,
			@item_id			=-1,
			@estdatefrom		='2000-01-01',
			@estdateto			='9999-12-31',
			@datefrom			='2000-01-01',
			@dateto				='9999-12-31',
			@ptr_id				=-1,
			@pt_id				=-1,
			@poh_quotation		=-1,
			@pod_isProcessed	=-1,
			@pro_id				= -1,
			@poh_id				= 0

	--drop table #tmpOptionsValues
	*/
	-- -------------------------------------------------------




	--DECLARE @bitFilterByPartial AS BIT = 'False'
	--IF @pod_isProcessed = 2
	--	BEGIN
	--		SET @bitFilterByPartial = 'True'
	--		SET @pod_isProcessed	= -1
	--	END





	-- -----------------------------------------------------------------
	-- Sucursales de las cuales TRAERA las OC
	-- -----------------------------------------------------------------
	DECLARE @tmpBranchs TABLE(bra_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchs
	(
		bra_id
	)
	SELECT	DISTINCT  tbg.bra_id
		FROM tbBranch					tb	WITH (NOLOCK)
		INNER JOIN  tbBranchGroupDetail tbg	WITH (NOLOCK)
			ON	tbg.comp_id = tb.comp_id AND
				tbg.brag_id = tb.brag_id4PurchaseOrder_page48
		WHERE	tb.comp_id						= @comp_id		AND
				tb.bra_id						= @bra_id		AND
				tb.bra_disabled					= 'False'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpBranchs
				(
					bra_id
				)
				VALUES(@bra_id)
		END
	-- -----------------------------------------------------------------













	select	[optval_id], [optval_desc]
	into	#tmpOptionsValues
	from	dbo.tbsysOptionsValues		WITH (NOLOCK)
	where	lang_id = @lang_id
	and		optval_class = 31





	select	' ' [ ], ' ' [ ], ' ' [ ], ' ' [ ], ' ' [ ], ' ' [ ], ' ' [ ],
			[comp_id],
			[bra_id],
			poh_quotation,
			[table].[optval_desc],
			poh_cd,											-- e.Row.Cells(15)		-- MOS 03-2022: x el FORRO de NG la pase aca arriba antes era 21
			poh_deliveryDate,								-- e.Row.Cells(16)		-- Ex 15
			poh_estDeliveryDate,							-- e.Row.Cells(17)		-- Ex 16
			supp_id,
			[supp_name],
		--sum(convert(int,[pod_isProcessed])) * count(*)		[ENFERMO],

			-- Se puede ser TAN HDRMP  ENFERMOOOO
			--case
			--	when sum(convert(int,[pod_isProcessed])) = 0 then (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 0)
			--	when sum(convert(int,[pod_isProcessed])) > 0 AND sum(convert(int,[pod_isProcessed])) = COUNT(*) then (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 1)
			--	ELSE  (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 2)
			--	--when 2 then (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 2)
			--end	[processed],
			CASE
				WHEN @pod_isProcessed = -1 THEN ''
				ELSE (select a.optval_desc from #tmpOptionsValues a where a.optval_id = @pod_isProcessed)
			END																							[processed],
			--case ( sum(convert(int,[pod_isProcessed])) * count(*) )
			--	when 0 then (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 0)
			--	when 1 then (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 1)
			--	ELSE  (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 2)
			--	--when 2 then (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 2)
			--end	[processed],
			pt_id,
			pt_desc,
			ptr_id,
			[ptr_name],
			--poh_cd,											-- e.Row.Cells(21)
			poh_total,											-- e.Row.Cells(22)
			poh_totalinSuppCurrency,							-- e.Row.Cells(23) -- MOS 05-2022 x el FORRO de NG
			poh_iseMailEnvied,									-- e.Row.Cells(24) -- MOS 08-2022 x el FORRO de CM

			-- ATENCION!!!!!!
			-- NO PONER NADA DELANTE DE ESTOS CAMPOS !!!!



			poh_observation1,
			poh_observation2,
			poh_observation3,
			poh_observation4,
			sum(convert(int,[pod_isProcessed])) /** count(*)*/ [processed_value],
			[user_name],
			poh_validUp2Date,
			pro_desc,		-- MOS 02-2024

			[ID]

	from (	select	--distinct MOS 05-2022: No poner ya que deja de calcular los items procesados si se lo agrega ya que hace arriba un PUTO SUM en esta MIERDA de SP que no se quien fue el HDP que lo hizo...
					poh.[comp_id],
					poh.[bra_id],
					poh.poh_id,
					poh.poh_quotation,
					ov.[optval_desc] + ':' + dbo.fnStrPADL (CONVERT(VARCHAR(5),poh.bra_id),5,'0') + '-' + dbo.fnStrPADL (CONVERT(VARCHAR(8),poh.poh_id),8,'0')	[optval_desc],
					poh.poh_deliveryDate,
					poh.poh_estDeliveryDate,
					poh.supp_id,
					s.[supp_name],
					pod.[pod_isProcessed],
					poh.pt_id,
					pt.pt_desc,
					poh.ptr_id,
					ISNULL(p.[ptr_name],'')						[ptr_name],
					poh.poh_cd,
					poh.poh_observation1,
					poh.poh_observation2,
					poh.poh_observation3,
					poh.poh_observation4,
					tu.user_lastname + ',' + tu.user_firstname	[user_name],
					poh.poh_validUp2Date,
					CASE
						WHEN poh.poh_iseMailEnvied = 'True' THEN '1'
						ELSE '0'
					END											[poh_iseMailEnvied],

					CONVERT(DECIMAL(19,2),ISNULL(poh.poh_total,0))						[poh_total],
					CONVERT(DECIMAL(19,2),ISNULL(poh.poh_totalinSuppCurrency,0))		[poh_totalinSuppCurrency],
					--poh.poh_id						[ID]  MOS 11-2019
					CONVERT(VARCHAR(10),poh.comp_id) + '-' +
					CONVERT(VARCHAR(10),poh.bra_id) + '-' +
					CONVERT(VARCHAR(10),poh.poh_id)
														[ID],
					tp.pro_desc


			from	dbo.[tbPurchaseOrderHeader]			poh	WITH (NOLOCK)

					INNER JOIN @tmpBranchs				tbm
						ON tbm.bra_id = poh.bra_id



					inner join dbo.[tbSupplier]			s	WITH (NOLOCK)
					on	s.comp_id   = poh.comp_id
					and	s.supp_id	= poh.supp_id

					inner join dbo.[tbPurchaseTerms]	pt	WITH (NOLOCK)
					on  pt.comp_id  = poh.[comp_id]
					and pt.pt_id	= poh.[pt_id]

					inner join dbo.[tbsysOptionsValues] ov	WITH (NOLOCK)
					on	ov.[lang_id]		= @lang_id
					and ov.[optval_class]	= 27
					and ov.[optval_id]		= poh.[poh_quotation]

					inner join dbo.[tbPurchaseOrderDetail]	pod	WITH (NOLOCK)
					on	pod.[comp_id]		= poh.comp_id
					and pod.[bra_id]		= poh.bra_id
					and pod.[poh_id]		= poh.poh_id

					-- MOS  06-2020  Lo puse en el where
					--and	(@item_id			= -1 or @item_id			= pod.[item_id]			)
					--and	(@pod_isProcessed	= -1 or convert(bit,@pod_isProcessed)	= pod.[pod_isProcessed]	)

					LEFT join dbo.tbPurchaseTransport  p	WITH (NOLOCK)
					on	p.comp_id   = poh.comp_id
					and	p.ptr_id	= poh.ptr_id

					LEFT JOIN tbUser						tu	WITH (NOLOCK)
					ON	tu.[user_id]		= poh.[user_id]

					LEFT JOIN tbProject AS tp				WITH (NOLOCK)		-- MOS 02-2024
						ON	tp.comp_id	= poh.comp_id AND
							tp.pro_id	= poh.pro_id

			where	poh.comp_id		= @comp_id
			--and		poh.bra_id  	= @bra_id
			and     (@supp_id		= -1 or @supp_id	= poh.supp_id		)
			and     (@ptr_id		= -1 or @ptr_id		= poh.ptr_id		)
			and     (@pt_id			= -1 or @pt_id		= poh.pt_id			)
			and     (@pro_id		= -1 or @pro_id		= poh.pro_id		) -- Proyecto
			and		poh.[poh_estDeliveryDate]	between @estdatefrom	and @estdateto
			and		poh.[poh_deliveryDate]		between @datefrom		and @dateto
			and	    (@poh_quotation	= -1 or convert(bit,@poh_quotation)	= poh.poh_quotation	)
			and	(@item_id			= -1 or @item_id			= pod.[item_id]			)
			AND
			CASE
				WHEN	@pod_isProcessed			= -1									THEN	1
				WHEN	@pod_isProcessed			= 2										THEN	1
				WHEN	@pod_isProcessed			= 3										THEN	1
				WHEN	@pod_isProcessed			= 4										THEN	1
				WHEN convert(bit,@pod_isProcessed)	= pod.[pod_isProcessed]					THEN	1
				ELSE																				0
			END	 = 1
			--and	(
			--		@pod_isProcessed				= -1						-- Todos
			--			OR
			--		convert(bit,@pod_isProcessed)	= pod.[pod_isProcessed]		-- Procesado o No Procesado
			--			OR
			--		(@pod_isProcessed = 2 AND pod.pod_initQty <> pod.pod_qty)	-- Parcial
			--	)
			AND (@poh_id			=  0 OR poh.poh_id	= @poh_id)

		) [table]

	group by [comp_id],
			[bra_id],
			poh_quotation,
			[table].[optval_desc],
			poh_deliveryDate,
			poh_estDeliveryDate,
			supp_id,
			[supp_name],
			pt_id,
			pt_desc,
			ptr_id,
			[ptr_name],
			poh_cd,
			poh_observation1,
			poh_observation2,
			poh_observation3,
			poh_observation4,
			[user_name],
			poh_validUp2Date,
			[ID],
			[TABLE].[poh_id],
			poh_total,
			poh_totalinSuppCurrency,
			[poh_iseMailEnvied],
			pro_desc

	HAVING	-- Se clona la MIERDA que hizo el ENFERMO HDP mas arriba para que siga andando igual
			CASE
				--WHEN @bitFilterByPartial = 'False' THEN 1
				WHEN @pod_isProcessed = 0 OR @pod_isProcessed = 1 OR @pod_isProcessed = -1																		THEN 1
				WHEN @pod_isProcessed = 3 AND  SUM(CONVERT(INT,[pod_isProcessed])) = count(*) AND SUM(CONVERT(INT,[pod_isProcessed])) > 0	THEN 1
				WHEN @pod_isProcessed = 4 AND  SUM(CONVERT(INT,[pod_isProcessed])) = 0														THEN 1
				WHEN @pod_isProcessed = 2 AND  SUM(CONVERT(INT,[pod_isProcessed])) <> count(*) AND SUM(CONVERT(INT,[pod_isProcessed])) > 0  THEN 1
				-- MOS 06-2023				WHEN (sum(convert(int,[pod_isProcessed])) * count(*)) = 2 THEN 1
				ELSE 0
			END = 1

	order by [TABLE].[comp_id],[TABLE].[bra_id],[TABLE].[poh_id]  DESC




	drop table #tmpOptionsValues


















END
GO







