-- *** ATENCION ****** ATENCION ****** ATENCION ****** ATENCION ****** ATENCION ****** ATENCION ***
--
-- SI SE AGREGA UN CAMPO EN EL SELECT AGREGARLO EN EL INSERT INTO DE spPurchaseOrder_getReportById
--
-- REFERENCIA : LPQLP
--
-- *** ATENCION ****** ATENCION ****** ATENCION ****** ATENCION ****** ATENCION ****** ATENCION ***
------------------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spPurchaseOrderHeader_getDataById]
(
 @comp_id   int,
 @bra_id    int,
 @lang_id   int,
 @poh_id    int
)


AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	 set nocount on

	 set dateformat 'ymd'

	-- --------------------------------------------------------------------
	-- TResting
	-- --------------------------------------------------------------------
	 /*


	 declare  @comp_id   int,
		@bra_id    int,
		@lang_id   int,
		@poh_id    int


	 select  @comp_id   =1,
		@bra_id    =1,
		@lang_id   =2,
		@poh_id    =208


	 */
	-- --------------------------------------------------------------------


	 select ' ' [ ], ' ' [ ],
	   poh.comp_id,
	   poh.bra_id,
	   poh.poh_cd,
	   poh.poh_estDeliveryDate,
	   poh.poh_deliveryDate,
	   poh.poh_observation1,
	   poh.poh_observation2,
	   poh.poh_observation3,
	   poh.poh_observation4,
	   poh.supp_id,
	   s.[supp_name],
	   ISNULL(poh.poh_quotation,'False') [poh_quotation],
	   ov.[optval_desc],
	   poh.pt_id,
	   pt.pt_desc,
	   poh.poh_isEditing,
	   poh.poh_isEditingCd,
	   poh.ptr_id,
	   ISNULL(ptr.ptr_name,'')											[ptr_name],
	   dbo.fngetpurchaseorderstate (poh.comp_id, poh.bra_id, @poh_id) [pod_isProcessed],
	   tpod.pod_obs,
	   ((SELECT COUNT(*)
		FROM tbPurchaseOrderHeader tpoh
		WHERE tpoh.comp_id  = poh.comp_id
		AND tpoh.poh_id   = @poh_id
		AND tpoh.poh_isEditing = 'True')
		+
	   (SELECT COUNT(*)
	   FROM tbPurchaseOrderDetail tpod
		WHERE tpod.comp_id  = poh.comp_id
		AND tpod.poh_id   = @poh_id
		AND tpod.pod_isEditing = 'True'))  [pod_isUsed],

		isnull(poh.poh_ACurrency,0)    [poh_ACurrency],
		isnull(poh.poh_ACurrencyExchange,0)  [poh_ACurrencyExchange],
		isnull(poh.poh_Perceptions,0)    [poh_Perceptions],
		isnull(poh.poh_Taxes,0)     [poh_Taxes],
		isnull(poh.poh_Charges,0)     [poh_Charges],
		s.curr_id         [CurrIdSupp],
		isnull(poh.poh_Discount1,0)    [poh_Discount1],
		isnull(poh.poh_Discount2,0)    [poh_Discount2],
		isnull(poh.poh_Discount3,0)    [poh_Discount3],
		isnull(poh.poh_Discount4,0)    [poh_Discount4],
		isnull(tb.bra_purchaseOrderNote1,'')  [bra_purchaseOrderNote1],
		isnull(tb.bra_purchaseOrderNote2,'')  [bra_purchaseOrderNote2],
		isnull(s.supp_Phone1,'')     [supp_Phone1],
		isnull(tb.bra_address,'')     [bra_address],
		isnull(tb.bra_address1,'')     [bra_address1],
		isnull(tb.bra_taxNumber,'')    [bra_taxNumber],
		isnull(tb.bra_desc,'')      [bra_desc],
		isnull(poh.pho_selectedInRecepcion,'false')[pho_selectedInRecepcion],
		poh.poh_validUp2Date      [poh_validUp2Date],
		poh.poa_id         [poa_id],
	   isnull(tpoda.poa_desc,'')     [poa_desc],
	   isnull(tpoda.poa_contactName,'')   [poa_contactName],
	   isnull(tpoda.poa_contactEmail,'')   [poa_contactEmail],
	   isnull(tpoda.poa_contactPhone,'')   [poa_contactPhone],
	   isnull(tpoda.poa_contactAddress,'')   [poa_contactAddress],
	   isnull(tpoda.poa_contactNote,'')   [poa_contactNote],
	   poh.simi_id,
	   ISNULL(poh.pro_id,-1)				[pro_id],
	   isnull(tb.bra_phone,'')				[bra_phone],
	   isnull(tb.bra_zip,'')				[bra_zip]




	 from dbo.[tbPurchaseOrderHeader]     poh

	   LEFT join dbo.[tbPurchaseTransport]  ptr
	   on	ptr.comp_id   = poh.comp_id
	   and	ptr.[ptr_id]  = poh.[ptr_id]

	   inner JOIN tbBranch       tb
	   ON  tb.comp_id   = poh.comp_id
	   AND tb.bra_id   = poh.bra_id

	   inner join dbo.[tbSupplier]     s
	   on s.comp_id   = poh.comp_id
	   and s.supp_id   = poh.supp_id

	   inner join dbo.[tbPurchaseTerms]   pt
	   on  pt.comp_id   = poh.[comp_id]
	   and pt.pt_id   = poh.[pt_id]

	   inner join dbo.[tbsysOptionsValues]   ov
	   on ov.[lang_id]  = @lang_id
	   and ov.[optval_class] = 27
	   and ov.[optval_id]  = poh.[poh_quotation]

	   LEFT JOIN tbPurchaseOrderDetail    tpod
	   ON  tpod.comp_id  = poh.comp_id
	   AND tpod.bra_id   = poh.bra_id
	   AND tpod.poh_id   = poh.poh_id

	   LEFT JOIN tbPurchaseOrderDeliveryAllocation tpoda
	   ON tpoda.comp_id = poh.comp_id AND
		  tpoda.poa_id  = poh.poa_id


	 where poh.poh_id  = @poh_id
	 AND  poh.comp_id  = @comp_id
	 AND  poh.bra_id  = @bra_id



END
GO



CREATE procedure [dbo].[spPurchaseOrderHeader_getReport]
(
		@comp_id			INT,
		@lang_id			INT,
		@page_id			INT,
		@bra_id				INT,
		--@poh_id			INT,
		@cat_id				INT,
		@subcat_id			INT,
		@brand_id			INT,
		@item_id			INT,
		@supp_id			INT,
		@pt_id				INT,
		@brag_id			INT,

		@date_from						datetime,			-- fecha desde
		@date_to						datetime,			-- fecha desde
		@deliveryestimateddatefrom		datetime,			-- Fecha Estimada de Entrega Desde
		@deliveryestimateddateto		datetime,			-- Fecha Estimada de Entrega hasta
		@deliverydatefrom				datetime,			-- Fecha Entrega Desde
		@deliverydateto					datetime,			-- Fecha Entrega hasta

		@type							INT,				-- Tipo : -1 Ambos 0 OC 1 Solic de Coti
		@optionstatus					INT,				-- Opción 1 Solo Pendientes, 2 Solo Recibidos,  -1 Todos
		@order							INT,				-- Orden : -1 Ninguno - 1 ID Artículo + Orden de Compra
		@SupplierGuid					VARCHAR(50),
		@ItemGuid						VARCHAR(50),

		@intBranch4Lang					INT
)
AS

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ----------------------------------------------------------------------
	-- Test
	-- ----------------------------------------------------------------------
	/*
		DECLARE @comp_id			INT,
				@lang_id			INT,
				@page_id			INT,
				@bra_id				INT,
				--@poh_id			INT,
				@cat_id				INT,
				@subcat_id			INT,
				@brand_id			INT,
				@item_id			INT,
				@supp_id			INT,
				@pt_id				INT,
				@brag_id			INT,

				@date_from						datetime,			-- fecha desde
				@date_to						datetime,			-- fecha desde
				@deliveryestimateddatefrom		datetime,			-- Fecha Estimada de Entrega Desde
				@deliveryestimateddateto		datetime,			-- Fecha Estimada de Entrega hasta
				@deliverydatefrom				datetime,			-- Fecha Entrega Desde
				@deliverydateto					datetime,			-- Fecha Entrega hasta

				@type							INT,				-- Tipo : -1 Ambos 0 OC 1 Solic de Coti
				@optionstatus					INT,				-- Opción 1 Solo Pendientes, 2 Solo Recibidos,  -1 Todos
				@order							INT,				-- Orden : -1 Ninguno - 1 ID Artículo + Orden de Compra
				@SupplierGuid					VARCHAR(50),
				@ItemGuid						VARCHAR(50),

				@intBranch4Lang					INT

		SELECT
				@comp_id			=1,
				@lang_id			=2,
				@page_id			=10058,
				@bra_id				=1,
				--@poh_id			=62,
				@cat_id				=-1,
				@subcat_id			=-1,
				@brand_id			=-1,
				@item_id			=-1,
				@supp_id			= -1,
				@pt_id				= -1,

				@brag_id			=-1,

				@date_from						='2022-01-01',			-- fecha desde
				@date_to						='2022-05-31',			-- fecha desde
				@deliveryestimateddatefrom		='2022-01-01',			-- Fecha Estimada de Entrega Desde
				@deliveryestimateddateto		='2022-05-31',			-- Fecha Estimada de Entrega hasta
				@deliverydatefrom				='2022-01-01',			-- Fecha Entrega Desde
				@deliverydateto					='2022-05-31',			-- Fecha Entrega hasta

				@type							= -1,					-- Tipo : -1 Ambos 0 OC 1 Solic de Coti
				@optionstatus					= -1,					-- Opción 1 Solo Pendientes, 2 Solo Recibidos,  -1 Todos
				@order							= -1,					-- Orden : -1 Ninguno - 1 ID Artículo + Orden de Compra
				@SupplierGuid					='b5200bd7-ad50-42a6-ac5d-8d8a67207332',
				@ItemGuid						='f7a79378-2dcd-418d-93d9-3bfc69d943f6',

				@intBranch4Lang					= 1

		drop table #tmpOptionsValues

*/
	-- ----------------------------------------------------------------------






		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @lGuidSupplier AS UNIQUEIDENTIFIER
		SET		@lGuidSupplier = CONVERT(UNIQUEIDENTIFIER,@SupplierGuid)
		DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Supplier
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf	WITH(NOLOCK)
				WHERE tcf.sl_guid = @lGuidSupplier     AND
							  tcf.sl_selected = 'True'

		--IF @@ROWCOUNT = 0 AND @supp_id > 0
		--	BEGIN
		--		INSERT INTO @tblComplexFilter_Supplier(supp_id)
		--			SELECT @supp_id
		--	END

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Supplier
					SELECT ts.supp_id
					FROM tbSupplier ts	WITH(NOLOCK)
						WHERE ts.comp_id = @comp_id
			END
		-- -------------------------------------------------------------


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Items para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @lGuidItems AS UNIQUEIDENTIFIER
		SET		@lGuidItems = CONVERT(UNIQUEIDENTIFIER,@ItemGuid)
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf	WITH(NOLOCK)
				WHERE tcf.sl_guid = @lGuidItems     AND
							  tcf.sl_selected = 'True'

		--IF @@ROWCOUNT = 0 AND @item_id > 0
		--	BEGIN
		--		INSERT INTO @tblComplexFilter_Items(item_id)
		--			SELECT @item_id
		--	END

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ts.item_id
					FROM tbItem ts	WITH(NOLOCK)
						WHERE ts.comp_id = @comp_id
			END
		-- -------------------------------------------------------------




		DECLARE @tblBranch TABLE(bra_id INT PRIMARY KEY CLUSTERED)
		IF @brag_id <> -1
			BEGIN
				INSERT INTO @tblBranch(bra_id)
					SELECT tbgd.bra_id
						FROM tbBranchGroupDetail tbgd	WITH(NOLOCK)
						WHERE	tbgd.comp_id = @comp_id AND
								tbgd.brag_id = @brag_id
			END
		ELSE
			BEGIN
				INSERT INTO @tblBranch(bra_id) VALUES (@bra_id)
			END



		select
			[optval_id], [optval_desc]
			into	#tmpOptionsValues
			from	dbo.tbsysOptionsValues	WITH(NOLOCK)
			where	lang_id = @lang_id
			and		optval_class = 31

		Select  tpoh.poh_id,
				tpoh.poh_cd,
				tpoh.poh_estDeliveryDate,
				tpoh.poh_deliveryDate,
				isnull(tpoh.poh_observation1,'') [poh_observation1],
				isnull(tpoh.poh_observation2,'') [poh_observation2],
				isnull(tpoh.poh_observation3,'') [poh_observation3],
				isnull(tpoh.poh_observation4,'') [poh_observation4],
				ts.supp_id,
				isnull(ts.supp_name,'')   [supp_name],
				isnull(ts.supp_name1,'')  [supp_name1],
				tpoh.poh_quotation,
				tpoh.pt_id,
				tpoh.poh_isEditing,
				tpoh.poh_isEditingCd,
				tpoh.ptr_id,
				Isnull(ti.item_code,'')   [item_code],
				isnull(ti.item_desc,'')   [item_desc],
				Isnull(ti.item_detail,'') [item_detail],
				isnull(tc.cat_desc,'')    [cat_desc] ,
				isnull(tsc.subcat_desc,'')[subcat_desc]  ,
				isnull(tb.brand_desc,'')  [brand_desc],
				case (sum(convert(int,[pod_isProcessed])) * count(*))
					when 0 then (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 0)
					--when 1 then (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 1)
					--Else ''
					when 2 then (select a.optval_desc from #tmpOptionsValues a where a.optval_id = 2)
					Else ''
				end	[processed],
				--tpod.pod_price,
				SUM(tpod.pod_qty) [pod_qty],
				dbo.fnGetExchange(@comp_id,tpod.pod_price,tpod.curr_id, tb1.curr_id ,0,0,'False')																						 [pod_price],
				rtrim(tc2.curr_symbol) + ' ' + replace(convert(varchar,convert(decimal(19, 2),dbo.fnGetExchange(@comp_id,tpod.pod_price,tpod.curr_id,tb1.curr_id ,0,0,'False'))),',','') [pod_price2],
				-- MOS 11-2021: Me pregiunto, se puede ser TAB HDP !!!!!
				--dbo.fnGetExchange(@comp_id,tpod.pod_price,tb1.curr_id ,@bra_id,0,0,'False') [pod_price],
				--rtrim(tc2.curr_symbol) + ' ' + replace(convert(varchar,convert(decimal(19, 2),dbo.fnGetExchange(@comp_id,tpod.pod_price,tb1.curr_id ,@bra_id,0,0,'False'))),',','') [pod_price2],
				tc2.curr_desc,
				tc2.curr_symbol,
				tb1.bra_desc,

				-- ----------------------------------------------------------------
				-- MOS 03-2022: Nuevos campos para nuevos reportes del FORRO de C1
				-- ----------------------------------------------------------------
				dbo.fnGetExchange(@comp_id,tpod.pod_price,tpod.curr_id, ts.curr_id ,0,0,'False')																						[pod_priceInSupplierCurrency],
				rtrim(tc3.curr_symbol) + ' ' + replace(convert(varchar,convert(decimal(19, 2),dbo.fnGetExchange(@comp_id,tpod.pod_price,tpod.curr_id,ts.curr_id ,0,0,'False'))),',','') [pod_priceInSupplierCurrency2],
				tc3.curr_symbol																																							[curr_symbolInSupplierCurrency],
				--
				tpod.pod_price																																							[pod_priceInOriginalCurrency],
				rtrim(tc4.curr_symbol) + ' ' + replace(convert(varchar,convert(decimal(19, 2),tpod.pod_price)),',','')																	[pod_priceInOriginalCurrency2],
				tc3.curr_symbol																																							[curr_symbolInOriginalCurrency]
				-- ----------------------------------------------------------------


		From tbPurchaseOrderHeader							tpoh		WITH(NOLOCK)



		Inner Join tbPurchaseOrderDetail					tpod		WITH(NOLOCK)
		On  tpod.comp_id	= tpoh.comp_id
		And tpod.poh_id		= tpoh.poh_id
		AND tpod.bra_id		= tpoh.bra_id

		INNER JOIN @tblBranch								tmpb
			ON tmpb.bra_id		= tpoh.bra_id

		Inner Join tbSupplier								ts			WITH(NOLOCK)
		On  ts.comp_id		= tpoh.comp_id
		And ts.supp_id		= tpoh.supp_id

		inner JOIN @tblComplexFilter_Supplier				tmpS
		ON tmpS.supp_id = ts.supp_id

		Inner Join tbItem									ti			WITH(NOLOCK)
		On  ti.comp_id		= tpod.comp_id
		And ti.item_id		= tpod.item_id

		inner JOIN @tblComplexFilter_Items tmpI
		ON tmpI.item_id = ti.item_id

		Inner Join tbCategory								tc			WITH(NOLOCK)
		On  tc.comp_id		= ti.comp_id
		And tc.cat_id		= ti.cat_id

		Inner Join tbSubCategory							tsc			WITH(NOLOCK)
		On  tsc.comp_id		= ti.comp_id
		And tsc.cat_id		= ti.cat_id
		And tsc.subcat_id	= ti.subcat_id

		Inner Join tbBranch									tb1			WITH(NOLOCK)
		On  tb1.comp_id		= tpoh.comp_id
		And tb1.bra_id		= tpoh.bra_id --@bra_id--tpod.bra_id

		Inner Join tbsysCurrency							tc2			WITH(NOLOCK)
		On tc2.curr_id		= tb1.curr_id

		Inner Join tbsysCurrency							tc3			WITH(NOLOCK)
		On tc3.curr_id		= ts.curr_id

		Inner Join tbsysCurrency							tc4			WITH(NOLOCK)
		On tc4.curr_id		= tpod.curr_id


		Inner Join tbBrand									tb			WITH(NOLOCK)
		On  tb.comp_id		= tpoh.comp_id
		And tb.brand_id		= ti.brand_id

		LEFT JOIN tbPurchaseTerms							tpt			WITH(NOLOCK)
		ON  tpt.comp_id		= tpoh.comp_id
		AND tpt.pt_id		= tpoh.pt_id

		Where tpoh.comp_id = @comp_id
		--And    tpod.pod_isProcessed <> 'true'		-- MOS 01-2024: Se saco esto para que fuincione el filtro de mas abajo.  Cuando lo agregaron NO sacaron esto.!!!
		and   (@item_id    = -1 or ti.item_id     = @item_id   )		-- MOS 11-2021 x filtro verde y tabla temporal mas arriba
		and   (@cat_id     = -1 or tc.cat_id      = @cat_id    )
		and   (@subcat_id  = -1 or tsc.subcat_id  = @subcat_id )
		and   (@brand_id   = -1 or tb.brand_id    = @brand_id  )
		and   (@supp_id	   = -1 or tpoh.supp_id	  = @supp_id   )	-- MOS 11-2021 x filtro verde y tabla temporal mas arriba
		and   (@pt_id	   = -1 or tpt.pt_id	  = @pt_id   )
		AND CASE		-- @type							INT,				-- Tipo : -1 Ambos 0 OC 1 Solic de Coti
				WHEN @type =-1  THEN 1
				WHEN @type = 0 AND tpoh.poh_quotation = 'False'  THEN 1
				WHEN @type = 1 AND tpoh.poh_quotation = 'True'   THEN 1
				ELSE 0
			END		= 1
		AND CASE		-- @optionstatus					INT,				-- Opción 1 Solo Pendientes, 2 Solo Recibidos,  -1 Todos
				WHEN @optionstatus = -1										THEN 1
				WHEN @optionstatus = 1 AND tpod.pod_isProcessed = 'False'	THEN 1
				WHEN @optionstatus = 2 AND tpod.pod_isProcessed = 'True'	THEN 1
				ELSE 0
		    END	= 1
		AND	(tpoh.poh_cd BETWEEN @date_from AND @date_to )
		AND	(tpoh.poh_estDeliveryDate BETWEEN @deliveryestimateddatefrom AND @deliveryestimateddateto)
		AND (tpoh.poh_deliveryDate BETWEEN @deliverydatefrom AND @deliverydateto )

		group By tpoh.poh_id,
				 tpoh.poh_cd,
				 tpoh.poh_estDeliveryDate,
				 tpoh.poh_deliveryDate,
				 [poh_observation1],
				 [poh_observation2],
				 [poh_observation3],
				 [poh_observation4],
				 ts.supp_id,
				 [supp_name1],
				 [supp_name],
				 tpoh.poh_quotation,
				 tpoh.pt_id,
				 tpoh.poh_isEditing,
				 tpoh.poh_isEditingCd,
				 tpoh.ptr_id,
				 [item_code],
				 [item_desc],
				 [item_detail],
				 [cat_desc] ,
				 [subcat_desc],
				 [brand_desc],
				 tpod.pod_qty,
				 [pod_price],
				 tb1.curr_id,
				 tc2.curr_desc,
				 tc2.curr_symbol,
				 tb1.bra_desc,
				 tpod.curr_id,
				 tpod.item_id,
				 ts.curr_id,
				 tc3.curr_symbol,
				 tc4.curr_symbol
		ORDER BY	-- @order							INT,				-- Orden : -1 Ninguno - 1 ID Artículo + Orden de Compra
				CASE
					WHEN @order = -1 THEN tpoh.poh_id
					WHEN @order =  1 THEN tpod.item_id
				END,
				CASE
					WHEN @order = -1 THEN tpod.item_id
					WHEN @order =  1 THEN tpoh.poh_id
				END

   			    --tpod.pod_price,
				--         tpod.curr_id,
				--         tc2.curr_desc,
				--         tc2.curr_symbol
   				---[processed]
				--order by ID

	exec [spReports_getData3]@comp_id,@intBranch4Lang ,@lang_id,@page_id

	DECLARE @fun_id INT
	SET @fun_id = 1

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 392
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params1],

			CASE @supp_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut	WITH(NOLOCK)
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)

	     		Else
	     			(Select ts.supp_name
	     			 From tbSupplier ts	WITH(NOLOCK)
	     			 Where ts.comp_id = @comp_id
	     			 And   ts.supp_id = @supp_id
	     				)
			 End [params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 103
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)	[params3],

			CASE @item_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut	WITH(NOLOCK)
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)

	     		Else
	     			(Select ti.item_desc
	     			 From tbItem ti
	     			 Where ti.comp_id = @comp_id
	     			 And   ti.item_id = @item_id
	     				)
			 End [params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t 	WITH(NOLOCK) INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 36
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],
			CASE @cat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut	WITH(NOLOCK)
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		TC.cat_desc
						FROM	tbCategory tc	WITH(NOLOCK)
						WHERE	tc.comp_id = @comp_id
						AND		tc.cat_id  = @cat_id)
			END		[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params7],
			CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut	WITH(NOLOCK)
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
						FROM	tbSubCategory tsc	WITH(NOLOCK)

						WHERE	tsc.comp_id		  = @comp_id
								And tsc.cat_id    = @cat_id
								AND tsc.subcat_id = @subcat_id)
			END		[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 73
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params9],
			CASE @brand_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut	WITH(NOLOCK)
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tb.brand_desc
						FROM	tbBrand tb	WITH(NOLOCK)
						WHERE	tb.comp_id = @comp_id AND tb.brand_id= @brand_id)
			END		[params10],



		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 435
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params11],
			CASE @pt_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut	WITH(NOLOCK)
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tpt.pt_desc
					 FROM tbPurchaseTerms tpt	WITH(NOLOCK)
						WHERE	tpt.comp_id = @comp_id AND tpt.pt_id= @pt_id)
			END		[params12]





			--- 21-08-2013 Se le agrego el filtro de condicion de compra ! GA



END
GO







CREATE PROCEDURE [dbo].[spPurchaseOrderHeader_insertData]
(
	@comp_id				int,
	@bra_id					int,
	@poh_id					int,
	@poh_estDeliveryDate	datetime,
	@poh_deliveryDate		datetime,
	@poh_observation1		varchar(100),
	@poh_observation2		varchar(100),
	@poh_observation3		varchar(100),
	@poh_observation4		varchar(100),
	@supp_id				int,
	@poh_quotation			bit,
	@pt_id					int,
	@ptr_id					INT,
	@poh_ACurrency			INT,
	@poh_ACurrencyExchange	DECIMAL(19,6),
	@poh_Perceptions		DECIMAL(19,6),
	@poh_Taxes				DECIMAL(19,6),
	@poh_Charges			DECIMAL(19,6)
)
as


set nocount on
set dateformat 'ymd'



insert into dbo.[tbPurchaseOrderHeader]		WITH (ROWLOCK)
	(
		comp_id,
		bra_id,
		poh_id,
		poh_cd,
		poh_estDeliveryDate,
		poh_deliveryDate,
		poh_observation1,
		poh_observation2,
		poh_observation3,
		poh_observation4,
		supp_id,
		poh_quotation,
		pt_id,
		poh_isEditing,
		poh_isEditingCd,
		ptr_id,poh_ACurrency,
		poh_ACurrencyExchange,
		poh_Perceptions,
		poh_Taxes,
		poh_Charges
	)
values
	(
		@comp_id,
		@bra_id,
		@poh_id,
		getdate(),
		@poh_estDeliveryDate,
		@poh_deliveryDate,
		@poh_observation1,
		@poh_observation2,
		@poh_observation3,
		@poh_observation4,
		@supp_id,
		@poh_quotation,
		@pt_id,
		'False',
		null,
		@ptr_id,
		@poh_ACurrency,
		@poh_ACurrencyExchange,
		@poh_Perceptions,
		@poh_Taxes,
		@poh_Charges

	)


--set	@return_value = @@identity



























GO







create PROCEDURE [dbo].[spPurchaseOrderHeader_PurchaseLoan_getDataById]
(
	@comp_id			int,
	@bra_id				int,
	@poh_id				int
)


AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	set nocount on

	set dateformat 'ymd'

-- --------------------------------------------------------------------
-- TResting
-- --------------------------------------------------------------------

/*

	declare 	@comp_id			int,
				@bra_id				int,
				@poh_id				int


	select		@comp_id			=1,
				@bra_id				=1,
				@poh_id				=211

*/
-- --------------------------------------------------------------------


	select	*



	from	dbo.[tbPurchaseOrderHeader]					poh



	where	poh.comp_id		= @comp_id
	AND		poh.bra_id		= @bra_id
	AND		poh.poh_id		= @poh_id



END
GO






create PROCEDURE [dbo].[spPurchaseOrderHeader_Quotation_getDataById]
(
 @comp_id   int,
 @lang_id   int,
 @bra_id    int,
 @poh_id    INT

)


AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	 set nocount on

	 set dateformat 'ymd'

	-- --------------------------------------------------------------------
	-- TResting
	-- --------------------------------------------------------------------
	 /*


	 declare  @comp_id   int,
		@bra_id    int,
		@lang_id   int,
		@poh_id    int


	 select  @comp_id   =1,
		@bra_id    =1,
		@lang_id   =2,
		@poh_id    =208


	 */
	-- --------------------------------------------------------------------


	 SELECT
