		AND		poh.poh_id		= @poh_id



END
GO







CREATE PROCEDURE [dbo].[spPurchaseOrderHeader_updateData]
(
	@comp_id					int,
	@bra_id						int,
	@poh_id						int,
	@poh_estDeliveryDate		datetime,
	@poh_deliveryDate			datetime,
	@poh_observation1			varchar(100),
	@poh_observation2			varchar(100),
	@poh_observation3			varchar(100),
	@poh_observation4			varchar(100),
	@supp_id					int,
	@poh_quotation				bit,
	@pt_id						int,
	@ptr_id						INT,
	@poh_ACurrency				INT,
	@poh_ACurrencyExchange		DECIMAL(19,6),
	@poh_Perceptions			DECIMAL(19,6),
	@poh_Taxes					DECIMAL(19,6),
	@poh_Charges				DECIMAL(19,6)
)
AS



BEGIN



	set nocount on

	/*
	declare
			@comp_id					int,
			@bra_id						int,
			@poh_id						int,
			@poh_estDeliveryDate		datetime,
			@poh_deliveryDate			datetime,
			@poh_observation1			varchar(100),
			@poh_observation2			varchar(100),
			@poh_observation3			varchar(100),
			@poh_observation4			varchar(100),
			@supp_id					int,
			@poh_quotation				int,
			@pt_id						int,
			@ptr_id						int,
			@return_value				int

	select
			@comp_id					= 1,
			@bra_id						= 1,
			@poh_id						= 3,
			@poh_estDeliveryDate		=getdate(),
			@poh_deliveryDate			=getdate(),
			@poh_observation1			='AAAAAAAAAAAAAAAAAAAAa',
			@poh_observation2			='',
			@poh_observation3			='lllllllllllllll',
			@poh_observation4			='',
			@supp_id					=74,
			@poh_quotation				=0,
			@pt_id						=5,
			@ptr_id						=1
	*/


	UPDATE 	dbo.[tbPurchaseOrderHeader]		WITH (ROWLOCK)

		SET 	poh_estDeliveryDate		=	@poh_estDeliveryDate	,
				poh_deliveryDate		=	@poh_deliveryDate		,
				poh_observation1		=	@poh_observation1		,
				poh_observation2		=	@poh_observation2		,
				poh_observation3		=	@poh_observation3		,
				poh_observation4		=	@poh_observation4		,
				supp_id					=	@supp_id				,
				poh_quotation			=	@poh_quotation			,
				pt_id					=	@pt_id					,
				poh_isEditing			=	'False'					,
				poh_isEditingCd			=	getdate()				,
				ptr_id					=	@ptr_id					,

				poh_ACurrency			=	@poh_ACurrency			,
				poh_ACurrencyExchange	=	@poh_ACurrencyExchange	,
				poh_Perceptions			=	@poh_Perceptions		,
				poh_Taxes				=	@poh_Taxes				,
				poh_Charges				=	@poh_Charges

		WHERE 	comp_id					=	@comp_id
		AND 	bra_id					=	@bra_id
		AND     poh_id					=	@poh_id




END























GO








CREATE  PROCEDURE [dbo].[spPurchaseOrderHeader_updateIsEditing]
(
	@comp_id					int,
	@bra_id						int,
	@poh_id						int,
	@poh_IsEditing				bit
)
AS


BEGIN



	set nocount on

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	/*
	DECLARE @comp_id					int,
			@bra_id						int,
			@poh_id						int,
			@poh_IsEditing				BIT

	SELECT  @comp_id					= 1,
			@bra_id						= 1,
			@poh_id						= 52,
			@poh_IsEditing				='true'
	*/

	update	dbo.[tbPurchaseOrderHeader] WITH (ROWLOCK)

		set	   	poh_IsEditing				= @poh_IsEditing,
				poh_isEditingCd				= getdate ()

		where	comp_id						= @comp_id
		and		bra_id						= @bra_id
		and		poh_id						= @poh_id


END
GO

CREATE PROCEDURE [dbo].[spPurchaseOrderHeader_updateisEmailEnvied]
(
	@comp_id						INT,
	@bra_id							INT,
	@poh_id							INT,
	@piseMailEnvied					BIT
)
AS
	BEGIN
		SET	NOCOUNT ON
		-- --------------------------------
		-- TESTING
		-- --------------------------------
		/*
			DECLARE
				@comp_id						INT,
				@bra_id							INT,
				@soh_id							INT,
				@soh_isPrintedFromSOPreparation	BIT
		*/
		-- --------------------------------

		UPDATE tbPurchaseOrderHeader
			SET		poh_iseMailEnvied		= @piseMailEnvied
			WHERE	comp_id					= @comp_id AND
					bra_id					= @bra_id	AND
					poh_id					= @poh_id
	END
GO



