CREATE procedure [dbo].[spPurchaseOrderPending_getDataByFilters]
(
	@comp_id			int,
	@bra_id				int,
	@supp_id			int,
	@item_id			int,
	@stor_id			int,
	@poh_id				int

)
AS

BEGIN




	SET NOCOUNT ON

	-- -----------------------------------------------------------------
	--  Test
	-- -----------------------------------------------------------------
	/*

	declare		@comp_id			int,
				@bra_id				int,
				@supp_id			int,
				@item_id			INT,
				@stor_id			int,
				@poh_id				int

	select 		@comp_id			= 1,
				@bra_id				= 1,
				@supp_id			= 8103,
				@item_id			= -1,
				@stor_id			= 3,
				@poh_id				= 0

	DROP TABLE #tmpPOS
	*/
	-- -----------------------------------------------------------------








	-- -----------------------------------------------------------------
	-- Sucursales de las cuales TRAERA las OC
	-- -----------------------------------------------------------------
	DECLARE @tmpBranchs TABLE(bra_id INT PRIMARY KEY)
	INSERT INTO @tmpBranchs
	(
		bra_id
	)
	SELECT	DISTINCT  tbg.bra_id
		FROM tbBranch					tb	WITH (NOLOCK)
		INNER JOIN  tbBranchGroupDetail tbg	WITH (NOLOCK)
			ON	tbg.comp_id = tb.comp_id AND
				tbg.brag_id = tb.brag_id4PurchaseOrder_page48
		WHERE	tb.comp_id						= @comp_id		AND
				tb.bra_id						= @bra_id		AND
				tb.bra_disabled					= 'False'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tmpBranchs
				(
					bra_id
				)
				VALUES(@bra_id)
		END
	-- -----------------------------------------------------------------




	--obtengo la cantidad de estados aprobados que debe tener cada Orden de Compra
	DECLARE	@pos_qty		INT
	SELECT	@pos_qty		= COUNT(*)
		FROM	tbPurchaseOrderStateConcept		tposc	WITH (NOLOCK)
		WHERE	tposc.comp_id	= @comp_id
	--SELECT @pos_qty




	--recupero solo las Ordenes de Compra que tienen todos los estados aprobados
	SELECT	tpos.poh_id,tpos.bra_id,
			COUNT(*)		[count]
		INTO	#tmpPOS
		FROM	tbPurchaseOrderState			tpos	WITH (NOLOCK)
		WHERE	tpos.comp_id	= @comp_id
			AND		tpos.bra_id		= @bra_id
			AND     tpos.pos_ok		= 'True'
		GROUP BY tpos.poh_id,tpos.bra_id
		HAVING	COUNT(*)		= @pos_qty

	--SELECT * FROM #tmpPOS




	select	pod.item_id,
			i.item_code,
			i.item_desc,
			pod.curr_id,
			pod.poh_id,
			pod.pod_id,
			ISNULL(sc.curr_desc,'')											[curr_desc],
			ISNULL(pod.cont_id,0),
			pod.pod_qty,
			ISNULL(pod.pod_confirmedQTY,0)									[pod_confirmedQTY],
			ISNULL(pod.pod_price,0)											[pod_price],
			ISNULL(pod.tax_id,0)											[tax_id],
			ISNULL(tax.tax_desc,'')											[tax_desc],
			ISNULL(pod.pod_isProcessed,'false')								[pod_isProcessed],
			isnull(tpt.pt_desc,'')											[pt_desc],
			ISNULL(pod.pod_priceB,0)										[pod_priceB],
			isnull(it.itst_PickingLocation,'')								[itst_PickingLocation],
			isnull(it.itst_StorageLocation,'')								[itst_StorageLocation],
			i.stor_id,
			isnull(pod.pod_custom,'')										[pod_custom],
			isnull(pod.pod_customNumber,'')									[pod_customNumber],
			isnull(pod.pod_Discount1,0)										[pod_Discount1],
			isnull(pod.pod_Discount2,0)										[pod_Discount2],
			isnull(pod.pod_Discount3,0)										[pod_Discount3],
			isnull(pod.pod_Discount4,0)										[pod_Discount4],
			isnull(pod.pod_surcharge1,0)									[pod_surcharge1],
			isnull(pod.pod_surcharge2,0)									[pod_surcharge2],
			isnull(pod.pod_surcharge3,0)									[pod_surcharge3],
			isnull(pod.pod_surcharge4,0)									[pod_surcharge4],
			ISNULL(pod.pod_Origin,'')										[pod_Origin],
			ISNULL(pod.pod_From,'')											[pod_From],
			ISNULL(pod.pod_LotNumber,'')									[pod_LotNumber],
			ISNULL(pod.pod_ExpirationDate,'')								[pod_ExpirationDate],
			CONVERT(VARCHAR,pod.poh_id) + '-' + CONVERT(VARCHAR,pod.pod_id)	[ID]


	FROM	dbo.tbPurchaseOrderHeader				poh	WITH (NOLOCK)

			INNER JOIN @tmpBranchs tmpp
				ON tmpp.bra_id = poh.bra_id

			INNER JOIN dbo.tbPurchaseOrderDetail	pod	WITH (NOLOCK)
			ON  poh.comp_id			= pod.comp_id
			AND poh.bra_id			= pod.bra_id
			AND poh.poh_id			= pod.poh_id

			LEFT JOIN dbo.tbTaxName					tax	WITH (NOLOCK)
			ON  pod.comp_id			= tax.comp_id
			AND pod.tax_id			= tax.tax_id

			INNER JOIN dbo.tbsysCurrency			sc	WITH (NOLOCK)
			ON  pod.curr_id			= sc.curr_id

			INNER JOIN dbo.tbItem					i	WITH (NOLOCK)
			ON  pod.comp_id			= i.comp_id
			AND pod.item_id			= i.item_id

			LEFT JOIN tbItemStorage					it	WITH (NOLOCK)
			ON	it.comp_id			= i.comp_id		AND
				it.stor_id			= @stor_id		AND
				it.item_id			= i.item_id

			LEFT JOIN #tmpPOS						pos
			ON	poh.poh_id			= pos.poh_id	AND
				poh.bra_id			= pos.bra_id

			LEFT JOIN tbPurchaseTerms				tpt	WITH (NOLOCK)
			ON	tpt.comp_id			= poh.comp_id AND
				tpt.pt_id			= poh.pt_id


	where   poh.comp_id				= @comp_id
	--and     poh.bra_id				= @bra_id
	and		poh.supp_id				= @supp_id
	and		pod.pod_isProcessed		= 'False'
	and     (@item_id				= -1		OR	pod.item_id = @item_id)
	and     (@poh_id				= 0			or  poh.poh_id  = @poh_id)	-- 0 : Todas las ordenes.
	AND		poh.poh_id NOT IN (	SELECT	tpoh.poh_id
   									FROM	tbPurchaseOrderHeader	tpoh	WITH (NOLOCK)
   									WHERE	tpoh.comp_id			= @comp_id
   									AND		tpoh.bra_id				= @bra_id
									AND		tpoh.poh_isEditing		= 'True')

	AND		pod.pod_id NOT IN (	SELECT	tpod.pod_id
   									FROM	tbPurchaseOrderDetail	tpod	WITH (NOLOCK)
   									WHERE	tpod.comp_id			= @comp_id
   									AND		tpod.bra_id				= @bra_id
   									AND		tpod.pod_isEditing		= 'True')

	ORDER BY pod.comp_id, pod.bra_id, pod.poh_id, pod.pod_id



END
GO

