--Author:GA
--Desc: Grilla de recepcion que suma las cantidades por articulo
--
------------------------------------------------------------------------------------------------------


CREATE procedure [dbo].[spPurchaseOrderReception_Detail_GetData]
(

		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@supp_id			INT,
		@poh_id				INT


)
AS


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON


-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@user_id			INT,
				@prof_id			INT,
				@supp_id			INT,
				@poh_id				INT


	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@supp_id			= 8145,
				@user_id			= 1,
				@prof_id			= 1,
				@poh_id				= 245
*/
-------------------------------------------------------------------------------------------

BEGIN

		SELECT	' '																				[ ],
				ti.item_code,
				ti.item_desc																	[item_desc],
				cast(convert(DECIMAL(19,5),sum(tpod.pod_qty)) AS DECIMAL(18,0))					[pod_qty],
				ts.stor_desc


		FROM tbPurchaseOrderHeader						tpoh		WITH (NOLOCK)

		Inner Join tbPurchaseOrderDetail				tpod		WITH (NOLOCK)
		On  tpod.comp_id	= tpoh.comp_id		AND
			tpod.poh_id		= tpoh.poh_id		AND
			tpod.bra_id		= tpoh.bra_id

		INNER JOIN tbPurchaseorderReceptionDetail		tprd		WITH (NOLOCK)
		ON  tprd.comp_id	= tpod.comp_id		AND
			tprd.poh_bra_id = tpod.bra_id		AND
			tprd.poh_id		= tpod.poh_id		AND
			tprd.pod_id		= tpod.pod_id

		INNER JOIN tbItem								ti			WITH (NOLOCK)
		On  ti.comp_id		= tpod.comp_id		AND
			ti.item_id		= tpod.item_id

		INNER JOIN tbPurchaseorderReceptionHeader		tprh		WITH (NOLOCK)
		ON tprd.comp_id		= tprh.comp_id
		AND tprd.por_id		= tprh.por_id

		LEFT JOIN tbStorage							 AS ts			WITH (NOLOCK)
			ON	ts.comp_id	= tpod.comp_id AND
				ts.stor_id	= tpod.stor_id



		Where	tpod.comp_id			= @comp_id		AND
				tpoh.supp_id			= @supp_id		AND
				(tpod.comp_id IS NULL OR tpod.pod_isProcessed = 'False' )	AND
				--tpoh.poh_id				= @poh_id		AND
				--tpoh.pho_selectedInRecepcion = 'True' AND
				tprh.por_isClosed		= 'false'

		GROUP BY tpod.item_id,ti.item_desc, ti.item_code,ts.stor_desc

		ORDER BY ti.item_desc


END
GO





