		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@qty				DECIMAL(19,4),
		@item_id			INT,
		@supp_id			INT,
		@poh_id				INT


)
AS


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON

-----------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@user_id			INT,
				@prof_id			INT,
				@qty				DECIMAL(19,4),
				@item_id			INT,
				@supp_id			INT,
				@poh_id				INT


	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@user_id			= 1,
				@prof_id			= 1,
				@qty				= 5,
				@item_id			= 256,
				@supp_id			= 8149,
				@poh_id				= 240

*/
-------------------------------------------------------------------------------------------

BEGIN
		-- ATENCION
		-- OJO con poner columnas aqui ya que se hace referencia por numero de columna yy si se agregan EXPLOTA la pagina !!!!!!!!!!!!
		SELECT ' '																				[ ],
			   ' '																				[ ],
			   ' '																				[ ],
			   ti.item_code,
			   ti.item_desc																				[item_desc],
--			   CASE
--				  WHEN tpod.comp_id IS NULL THEN	'*'
--				  ELSE								''
--			   END																						[bolEntryType],
			   -- NO PONER NADA DESPUES DE ESTOS CAMPOS
			   -- ' *654654erggerer654
			   cast(isnull(sum(IsNull(tpod.pod_qty,0)) - (sum(tprd.pord_qty)),0) AS DECIMAL(18,0))		[qty_pendiente],	-- Count - 3
			   cast(isnull(sum(tprd.pord_qty),0) AS DECIMAL(18,0))										[pord_qty],			-- Count - 2
			   CONVERT(VARCHAR,tprh.por_id)	+ '-' + CONVERT(VARCHAR,tprd.item_id)						[ID]				-- Count - 1




		FROM tbPurchaseorderReceptionDetail				tprd 		WITH (NOLOCK)

		left JOIN tbPurchaseOrderDetail					tpod		WITH (NOLOCK)
		ON  tpod.comp_id	= tprd.comp_id		AND
			tpod.bra_id		= tprd.poh_bra_id	AND
			tpod.poh_id		= tprd.poh_id		AND
			tpod.pod_id		= tprd.pod_id

		INNER JOIN tbPurchaseorderReceptionHeader		tprh		WITH (NOLOCK)
		ON  tprh.comp_id	= tprd.comp_id		AND
			tprh.por_id		= tprd.por_id

		INNER Join tbItem								ti			WITH (NOLOCK)
		On  ti.comp_id		= tprd.comp_id		AND
			ti.item_id		= tprd.item_id


		Where	tprd.comp_id		= @comp_id	AND
				tprh.supp_id		= @supp_id	AND
				(tpod.comp_id IS NULL OR tpod.pod_isProcessed = 'False' ) AND
				tprh.por_isClosed   = 'false'

		GROUP BY	ti.item_desc,
					tprh.por_id,
					tprd.item_id,
					ti.item_code


		ORDER BY ti.item_desc



END




