------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: Data para saber si borro o inicializo
------------------------------------------------------------------------------------------------------


CREATE procedure [dbo].[spPurchaseOrderReception_Detail_GetDataPending_Status]
(

	@comp_id			INT,
	@por_id				int,
	@item_id			INT,
	@supp_id			INT

)
as
SET NOCOUNT ON


-------------------------------------------------------------------------------------------
	/*

	DECLARE 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@user_id			INT,
				@prof_id			INT,
				@por_id				int,
				@item_id			INT,
				@supp_id			INT


	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@user_id			= 1,
				@prof_id			= 1,
				@por_id				= 43,
				@item_id			= 229,
				@supp_id			= 8145
*/
-------------------------------------------------------------------------------------------

BEGIN

DECLARE @Intqtypendiente AS INT


	SET @Intqtypendiente =	(SELECT sum(tpod.pod_qty) - (sum(tprd.pord_qty))	[qty_pendiente]

								FROM tbPurchaseorderReceptionDetail				tprd 		WITH (NOLOCK)

								left JOIN tbPurchaseOrderDetail					tpod		WITH (NOLOCK)
								ON  tpod.comp_id	= tprd.comp_id		AND
									tpod.bra_id		= tprd.poh_bra_id	AND
									tpod.poh_id		= tprd.poh_id		AND
									tpod.pod_id		= tprd.pod_id

								INNER JOIN tbPurchaseorderReceptionHeader		tprh		WITH (NOLOCK)
								ON  tprh.comp_id	= tprd.comp_id		AND
									tprh.por_id		= tprd.por_id

								INNER Join tbItem								ti			WITH (NOLOCK)
								On  ti.comp_id		= tprd.comp_id		AND
									ti.item_id		= tprd.item_id


								Where	tprd.comp_id	= @comp_id	AND
										tprh.supp_id	= @supp_id	AND
										tprh.por_id		= @por_id	AND
										tprd.item_id	= @item_id
								)



		IF @Intqtypendiente < 0

			BEGIN
				--Tiene pendiente negativo, borra
				SELECT 0 [qty_pendiente_status]
			END

		ELSE
			BEGIN
				--Es parcial o puede recibir xq no tiene pendiente,inicializa
				SELECT 1 [qty_pendiente_status]
			END





END
GO



------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: Data para saber si cantidad recibida de items total hasta el momento.
------------------------------------------------------------------------------------------------------


CREATE procedure [dbo].[spPurchaseOrderReception_Detail_GetQtyTotalReceived]
(

	@comp_id			INT,
	@por_id				INT

)
as
SET NOCOUNT ON


-------------------------------------------------------------------------------------------
	/*

	DECLARE 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@user_id			INT,
				@prof_id			INT,
				@por_id				int,
				@item_id			INT,
				@supp_id			INT


	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@user_id			= 1,
				@prof_id			= 1,
				@por_id				= 43,
				@item_id			= 229,
				@supp_id			= 8145
*/
-------------------------------------------------------------------------------------------

BEGIN

	SELECT
		sum(isnull(tprd.pord_qty,0))	[qtytotalreceived]

		FROM tbPurchaseorderReceptionDetail				tprd 		WITH (NOLOCK)

		Where	tprd.comp_id	= @comp_id	AND
				tprd.por_id		= @por_id



END
GO





------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: Si se ingreso la cantidad de mercaderia solicitada habilita o no el recibir
------------------------------------------------------------------------------------------------------



CREATE PROCEDURE [dbo].[spPurchaseOrderReception_Detail_IsValid4Receive]
(

		@comp_id			INT,
		@supp_id			INT,
		@por_id				INT

)
as
SET NOCOUNT ON

-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@supp_id			INT,
				@por_id				INT



	SELECT		@comp_id			= 1,
				@supp_id			= 8145,
				@por_id				= 386

*/
-------------------------------------------------------------------------------------------

BEGIN

	DECLARE @lavailable AS INT

	SET @lavailable = 1


			--declare para el cursor
			DECLARE @lpod_qty_available DECIMAL(19,5)

			--cursor para recorrer PurchaseOrderDetail para traer la cantidad disponible ( cantidad de pod menos la cantidad de pord )
			DECLARE cursor_PORD CURSOR LOCAL FAST_FORWARD FOR


					SELECT isnull(sum(isnull(tpod.pod_qty,0)) - (sum(tprd.pord_qty)),0)	[qty_pendiente]

					FROM tbPurchaseorderReceptionDetail				tprd 		WITH (NOLOCK)

					LEFT JOIN tbPurchaseOrderDetail					tpod		WITH (NOLOCK)
					ON  tpod.comp_id	= tprd.comp_id		AND
						tpod.bra_id		= tprd.poh_bra_id	AND
						tpod.poh_id		= tprd.poh_id		AND
						tpod.pod_id		= tprd.pod_id

					INNER JOIN tbPurchaseorderReceptionHeader		tprh		WITH (NOLOCK)
					ON  tprh.comp_id	= tprd.comp_id		AND
						tprh.por_id		= tprd.por_id

					INNER Join tbItem								ti			WITH (NOLOCK)
					On  ti.comp_id		= tprd.comp_id		AND
						ti.item_id		= tprd.item_id


					Where	tprd.comp_id		= @comp_id	AND
							tprh.supp_id		= @supp_id	AND
							tprh.por_id			= @por_id	AND
							(tpod.comp_id IS NULL OR tpod.pod_isProcessed = 'False' )

					GROUP BY	ti.item_desc,
								tprh.por_id,
								tprd.item_id

					ORDER BY ti.item_desc

				OPEN cursor_PORD

				-- lectura anticipada del cursor
				FETCH cursor_PORD INTO @lpod_qty_available
				WHILE @@FETCH_STATUS = 0
				BEGIN

							--Si la cantidad ingresada es menor igual que la disponible
							--IF @lpod_qty_available < 0 OR @lpod_qty_available > 0
							--GA 29 de sep , solo si la mercaderia es mayor se deshabilita el recibir
							IF @lpod_qty_available < 0

								BEGIN
								SET @lavailable = 0
								END

						FETCH cursor_PORD INTO @lpod_qty_available



			END

			CLOSE cursor_PORD
			DEALLOCATE cursor_PORD

-- 1 : Se habilita el recibir
-- 0 : No se habilita el recibir
SELECT @lavailable [Available]

END
GO





------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: Si se ingreso la cantidad de mercaderia solicitada habilita o no el recibir
------------------------------------------------------------------------------------------------------



create procedure [dbo].[spPurchaseOrderReception_Detail_IsValidForReceive]
(

		@comp_id			INT,
		@supp_id			INT

)
as
SET NOCOUNT ON

-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@supp_id			INT


	SELECT		@comp_id			= 1,
				@supp_id			= 8145
*/
-------------------------------------------------------------------------------------------

BEGIN



		SELECT sum(tpod.pod_qty) - (sum(tprd.pord_qty))						[qty_pendiente]


		FROM tbPurchaseorderReceptionDetail				tprd 		WITH (NOLOCK)

		left JOIN tbPurchaseOrderDetail					tpod		WITH (NOLOCK)
		ON  tpod.comp_id	= tprd.comp_id		AND
			tpod.bra_id		= tprd.poh_bra_id	AND
			tpod.poh_id		= tprd.poh_id		AND
			tpod.pod_id		= tprd.pod_id

		INNER JOIN tbPurchaseorderReceptionHeader		tprh		WITH (NOLOCK)
		ON  tprh.comp_id	= tprd.comp_id		AND
			tprh.por_id		= tprd.por_id

		Where	tprd.comp_id	= @comp_id	AND
				tprh.supp_id	= @supp_id





END
GO




------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: Grilla principal de ORdenes de Compra
-----------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spPurchaseOrderReception_GetDataByFilters]
(

		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@supp_id			INT,
		@poh_id				INT
)
as
SET NOCOUNT ON

-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@user_id			INT,
				@prof_id			INT,
				@supp_id			INT,
				@poh_id				INT


	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@supp_id			= 8145,
				@user_id			= 1,
				@prof_id			= 1,
				@poh_id				= 245
*/
-------------------------------------------------------------------------------------------

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

		SELECT  ' '																										[ ],
				' '																										[ ],
				' '																										[ ],
				tpoh.poh_id																								[poh_id],
				isnull(ti.item_code,'')																					[item_code], --e.Row.Cells(7)
				isnull(ti.item_desc,'')																					[item_desc], --e.Row.Cells(8)
				cast(isnull(tpod.pod_qty,0) AS DECIMAL(18,0))															[pod_qty],
				--convert(DECIMAL(19,5),dbo.fnGetExchange(@comp_id,tpod.pod_price,tb1.curr_id ,@bra_id,0,0,'False'))	[pod_price],
				ISNULL(tpod.pod_obs,'')																					[pod_obs],
				tpoh.poh_cd																								[poh_cd],
				tpoh.poh_deliveryDate																					[poh_deliveryDate],
				CONVERT(VARCHAR,tpod.poh_id) + '-' + CONVERT(VARCHAR,tpod.pod_id)										[ID]


		FROM tbPurchaseOrderHeader						tpoh		WITH (NOLOCK)

		Inner Join tbPurchaseOrderDetail				tpod		WITH (NOLOCK)
		On  tpod.comp_id	= tpoh.comp_id		AND
			tpod.poh_id		= tpoh.poh_id		AND
			tpod.bra_id		= tpoh.bra_id

		Inner Join tbSupplier							ts			WITH (NOLOCK)
		On  ts.comp_id		= tpoh.comp_id		AND
			ts.supp_id		= tpoh.supp_id

		Inner Join tbItem								ti			WITH (NOLOCK)
		On  ti.comp_id		= tpod.comp_id		AND
			ti.item_id		= tpod.item_id

		--Inner Join tbBranch								tb1			WITH (NOLOCK)
		--On  tb1.comp_id		= tpoh.comp_id		AND
		--	tpoh.bra_id		= @bra_id


		Where	tpoh.comp_id						= @comp_id			AND
				tpod.pod_isProcessed				<> 'true'			AND
				tpoh.pho_selectedInRecepcion		=  'true'			AND
				tpoh.supp_id						= @supp_id			AND
				ISNULL(tpod.pod_confirmedQTY,0)		= 0					--AND
				--tpoh.bra_id							= @bra_id


		GROUP BY
					tpoh.poh_id,
					item_code,
					item_desc,
					pod_qty,
					--tb1.curr_id,
					poh_cd,
					tpod.poh_id,
					tpod.pod_id,
					poh_deliveryDate,
					tpod.pod_obs




		ORDER BY poh_deliveryDate,tpoh.poh_id




END
GO



------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: Data para saber si se habilita el borrar o no dependiendo la cantidad
------------------------------------------------------------------------------------------------------


CREATE procedure [dbo].[spPurchaseOrderReception_Header_DeleteStatus]
(

	@comp_id			INT,
	@pod_id				INT,
	@poh_id				INT

)
as
SET NOCOUNT ON


-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@pod_id				INT,
				@poh_id				INT



	SELECT		@comp_id			= 1,
				@pod_id				= 21239,
				@poh_id				=240

*/
-------------------------------------------------------------------------------------------

BEGIN

DECLARE @IntDeleteStatus AS INT


	SET @IntDeleteStatus =	(SELECT tprd.pord_qty	[pord_qty]

								FROM tbPurchaseorderReceptionDetail				tprd 		WITH (NOLOCK)

									INNER JOIN tbPurchaseorderReceptionHeader		tprh WITH (NOLOCK)
									ON tprh.comp_id		= tprd.comp_id AND
									tprh.por_id			= tprd.por_id

								Where	tprd.comp_id	    = @comp_id		AND
										tprd.pod_id		    = @pod_id		AND
									--	tprd.poh_id			= @poh_id  AND
										tprh.por_isClosed	= 'false'
								)



		IF @IntDeleteStatus = 0

			BEGIN
				--CANTIDAD = 0 ENTONCES HABILITA BORRAR
				SELECT 1 [DeleteStatus]
			END

		ELSE
			BEGIN
				--NO HABILITA BOTON BORRAR XQ LA CANTIDAD NO ES 0
				SELECT 0 [DeleteStatus]
			END





END
GO




------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: Grilla principal de ORdenes de Compra
------------------------------------------------------------------------------------------------------


CREATE procedure [dbo].[spPurchaseOrderReception_OnlyOrders_GetDataByFilters]
(

		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@supp_id			INT

)
AS

BEGIN


	SET NOCOUNT ON

	------------------------------------------------------------------------------------------
	/*
		DECLARE 	@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@user_id			INT,
					@prof_id			INT,
					@supp_id			INT


		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@supp_id			= 8145,
					@user_id			= 1,
					@prof_id			= 1
	*/
	-------------------------------------------------------------------------------------------

	BEGIN

		-- ----------------------------------------------------------
		-- Sucursales Habilitadas
		-- ----------------------------------------------------------
		DECLARE @tblBranchs TABLE(bra_id INT PRIMARY KEY)
		INSERT INTO @tblBranchs(bra_id)
			SELECT DISTINCT tbgd.bra_id
				FROM tbBranch					tb		WITH (NOLOCK)
				INNER JOIN tbBranchGroupDetail	tbgd	WITH (NOLOCK)
					ON	tbgd.comp_id		= tb.comp_id	AND
						tbgd.brag_id		= tb.bra_purchaseOrderReception_brag_id
				INNER JOIN tbBranch				tb2		WITH (NOLOCK)
					ON	tb2.comp_id			= tbgd.comp_id	AND
						tb2.bra_id			= tbgd.bra_id
				WHERE	tb.comp_id			= @comp_id		AND
						tb.bra_id			= @bra_id		AND
						tb2.bra_disabled	= 'False'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblBranchs(bra_id)
					SELECT tb.bra_id
						FROM tbBranch tb		WITH (NOLOCK)
						WHERE	tb.comp_id		= @comp_id	AND
								tb.bra_id		= @bra_id	AND
								tb.bra_disabled = 'False'
			END
		-- ----------------------------------------------------------




		SELECT  DISTINCT ' '																							[ ],
						 ' '																							[ ],
				tpoh.bra_id,
				tpoh.poh_id																								[poh_id],
				tpoh.poh_cd																								[poh_cd],
				tpoh.poh_estDeliveryDate																				[poh_estDeliveryDate],
				--11/09/15 AutoHogar sacar fecha tpoh.poh_deliveryDate																					[poh_deliveryDate],
				tpoh.poh_observation1																					[poh_observation1],
			convert(nvarchar(10),tpoh.bra_id) + '-' + convert(nvarchar(10),tpoh.poh_id	)																							[ID]


		FROM tbPurchaseOrderHeader						tpoh		WITH (NOLOCK)

		INNER JOIN @tblBranchs tmp
			ON tmp.bra_id = tpoh.bra_id

		Inner Join tbPurchaseOrderDetail				tpod		WITH (NOLOCK)
		On  tpod.comp_id	= tpoh.comp_id		AND
			tpod.poh_id		= tpoh.poh_id		AND
			tpod.bra_id		= tpoh.bra_id

		Inner Join tbSupplier							ts			WITH (NOLOCK)
		On  ts.comp_id		= tpoh.comp_id		AND
			ts.supp_id		= tpoh.supp_id

		--Inner Join tbBranch								tb1			WITH (NOLOCK)
		--On  tb1.comp_id		= tpoh.comp_id		AND
		--	tb1.bra_id		= @bra_id


		Where	tpoh.comp_id			= @comp_id			AND
				tpod.pod_isProcessed	<> 'true'			AND
				tpoh.supp_id			= @supp_id			AND
				ISNULL(tpod.pod_confirmedQTY,0)		= 0		AND
				tpoh.poh_quotation		= 'False'
				--tpoh.bra_id				= @bra_id

		ORDER BY tpoh.poh_id




	END


END
GO



------------------------------------------------------------------------------------------------------
--Date: 01/04/15
--Author:GA
--Desc: Data para saber si se habilita el borrar o no dependiendo la cantidad
------------------------------------------------------------------------------------------------------


create procedure [dbo].[spPurchaseOrderReception_Orders_DeleteStatus_CheckQty]
(

	@comp_id					INT,
	@supp_id					INT,
	@poh_id						INT

)
as
SET NOCOUNT ON


-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id					INT,
				@supp_id					INT,
				@poh_id						INT



	SELECT		@comp_id			= 1,
				@supp_id			= 8145,
				@poh_id				= 262

*/
-------------------------------------------------------------------------------------------

BEGIN


	IF EXISTS (	SELECT tprd.pord_qty

							FROM tbPurchaseorderReceptionDetail			tprd	WITH (NOLOCK)

							INNER JOIN tbPurchaseOrderHeader			tpoh	WITH (NOLOCK)
							ON	tpoh.comp_id	= tprd.comp_id
							AND tpoh.bra_id		= tprd.poh_bra_id
							AND tpoh.poh_id		= tprd.poh_id

							INNER JOIN tbPurchaseorderReceptionHeader	tprh	WITH (NOLOCK)
							ON	tprh.comp_id	= tprd.comp_id AND
								tprh.por_id		= tprd.por_id

				          	WHERE	tprd.comp_id			= @comp_id	AND
      								tprd.poh_id				= @poh_id	AND
      								tpoh.supp_id			= @supp_id	AND
      								tprh.por_isClosed		= 'False'  AND
      								tprd.pord_qty			> 0
								)

			BEGIN
				--NO HABILITA BOTON BORRAR XQ LA CANTIDAD NO ES 0
				SELECT 0 [DeleteStatus]
			END

		ELSE
		BEGIN
			--CANTIDAD = 0 ENTONCES HABILITA BORRAR

				SELECT 1 [DeleteStatus]
			END





END
GO






