	@UserBarCode				NVARCHAR(50)



)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE	  	@comp_id					INT,
			@UserBarCode				NVARCHAR(50)


SELECT		@comp_id				= 1,
			@UserBarCode		    = 'LACONCHADETUMADRE'

