CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionControl_getData_SearchCode]
(
	@comp_id				int,
	@bra_id					int,
	@poh_id					INT,
	@strCodeToSearch		NVARCHAR(200)
)
as

BEGIN

	set nocount on

	-- --------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------
/*
	  DECLARE
		@comp_id				int,
		@bra_id					int,
		@poh_id			INT,
		@strCodeToSearch		NVARCHAR(200)
	  SELECT
		@comp_id				= 1,
		@bra_id					= 1,
		@poh_id					= 208,
		@strCodeToSearch		= 'F1'
*/
	-- --------------------------------------------------------------------------


	DECLARE @bolIdUpdated AS BIT
	SET     @bolIdUpdated = 'False'


	-- Por Codigo
	UPDATE tbPurchaseOrderReceptionControl

	SET	por_qty_Chequed = por_qty_Chequed + 1


	FROM tbPurchaseOrderReceptionControl	tmp		WITH (NOLOCK)
	INNER JOIN tbItem						ti		WITH (NOLOCK)
		ON	ti.comp_id = tmp.comp_id AND
			ti.item_id = tmp.item_id

	WHERE	tmp.comp_id			= @comp_id						AND
			tmp.poh_id			= @poh_id						AND
			tmp.por_qty_Chequed < tmp.por_qty_Ordered			AND
			ti.item_code		= @strCodeToSearch


	IF @@ROWCOUNT > 0 SET @bolIdUpdated = 'True'


	-- Por Numero de Serie
	IF @bolIdUpdated = 'False'
		BEGIN

			UPDATE tbPurchaseOrderReceptionControl

			SET	por_qty_Chequed = por_qty_Chequed + 1

			FROM tbPurchaseOrderReceptionControl tmp		WITH (NOLOCK)
			INNER JOIN tbItemSerials			 tis		WITH (NOLOCK)
				ON	tis.comp_id		= tmp.comp_id			AND
					tis.item_id		= tmp.item_id

			WHERE	tmp.comp_id			= @comp_id						AND
					tmp.poh_id			= @poh_id						AND
					tmp.por_qty_Chequed < tmp.por_qty_Ordered			AND
					tis.is_serial		= @strCodeToSearch

		END

	IF @@ROWCOUNT > 0 SET @bolIdUpdated = 'True'


	-- Indica si estan todos los items tomados
	-- 1 : Sumo 1
	-- 0 : No hizo nada
	IF @bolIdUpdated = 'True'
		BEGIN
			SELECT 1
		END
	ELSE
		BEGIN
			SELECT 0
		END


END

GO






CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionControl_getDataById]
(

	@comp_id					INT,
	@poh_id						INT


)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE	  	@comp_id				INT,
			@poh_id					INT


SELECT		@comp_id						= 1,
			@poh_id							= 211
*/
-- ------------------------------------------------------


	SELECT  top 1	tporc.comp_id,
					tporc.bra_id,
					tporc.poh_id,
					tporc.item_id,
					tporc.por_qty_Ordered,
					tporc.por_qty_Chequed,
					isnull(tporc.por_userId4Close,-1)	[por_userId4Close],
					tporc.por_closeDate,
					isnull(tporc.por_Receipted,'false') [por_Receipted]


	FROM tbPurchaseOrderReceptionControl	tporc		WITH (NOLOCK)


	WHERE	tporc.comp_id		 = @comp_id			AND
			tporc.poh_id		 = @poh_id


END
GO







CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionControl_Initialize_qtyChequed]
(
	@comp_id				int,
	@poh_id					int,
	@item_id				int
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*
		  DECLARE
  			@comp_id				int,
  			@poh_id					int,
  			@item_id				int

		  SELECT
  			@comp_id				= 1,
  			@poh_id					= 211,
  			@item_id				= 256
*/
		-- --------------------------------------------------------------------------




		UPDATE tbPurchaseOrderReceptionControl


		SET	 por_qty_Chequed		= 0,
			 por_userId4Close		= NULL,
