CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionControl_InsertData]
(

	@comp_id					INT,
	@poh_id						INT

)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE	  	@comp_id				INT,
				@poh_id					INT


	SELECT		@comp_id					= 1,
				@poh_id						= 211

*/
-- ------------------------------------------------------


	IF NOT EXISTS ( SELECT tporc.poh_id
						FROM tbPurchaseOrderReceptionControl		tporc
						WHERE	tporc.comp_id		= @comp_id AND
								tporc.poh_id		= @poh_id
				  )
		BEGIN

				INSERT INTO tbPurchaseOrderReceptionControl
				(
							comp_id,
							bra_id,
							poh_id,
							item_id,
							por_qty_Ordered,
							por_qty_Chequed,
							por_Receipted

				)
				SELECT
							tpod.comp_id,
							tpod.bra_id,
							tpod.poh_id,
							tpod.item_id,
							SUM(tpod.pod_qty),
							0,
							'FALSE'

					FROM	tbPurchaseOrderDetail				tpod		WITH (NOLOCK)

					WHERE	tpod.comp_id	= @comp_id			AND
							tpod.poh_id		= @poh_id			AND
							tpod.item_id	IS NOT NULL

				GROUP BY	tpod.comp_id,
							tpod.bra_id,
							tpod.poh_id,
							tpod.item_id

		END

END
GO







