CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionControl_UpdateData]
(
	@comp_id				int,
	@poh_id					int
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*


		  DECLARE
  			@comp_id				int,
  			@poh_id					int

		  SELECT
  			@comp_id				= 1,
  			@poh_id					= 211

  			DROP TABLE #tmpPurchaseOrderReceptionControl
*/
		-- ------------------------------------------------------------------------

		IF NOT EXISTS ( SELECT tporc.poh_id
						FROM tbPurchaseOrderReceptionControl		tporc
						WHERE	tporc.comp_id		= @comp_id AND
								tporc.poh_id		= @poh_id
				  )
			BEGIN

					INSERT INTO tbPurchaseOrderReceptionControl
					(
								comp_id,
								bra_id,
								poh_id,
								item_id,
								por_qty_Ordered,
								por_qty_Chequed,
								por_Receipted

					)
					SELECT
								tpod.comp_id,
								tpod.bra_id,
								tpod.poh_id,
								tpod.item_id,
								SUM(tpod.pod_qty),
								0,
								'false'

						FROM	tbPurchaseOrderDetail				tpod		WITH (NOLOCK)

						WHERE	tpod.comp_id	= @comp_id			AND
								tpod.poh_id		= @poh_id			AND
								tpod.item_id	IS NOT NULL

					GROUP BY	tpod.comp_id,
								tpod.bra_id,
								tpod.poh_id,
								tpod.item_id

			END

			ELSE

				BEGIN

						CREATE TABLE #tmpPurchaseOrderReceptionControl
							(
								item_id				INT,
								qty_chequed			DECIMAL(19,4)
							)



						INSERT INTO #tmpPurchaseOrderReceptionControl
							  (
							  	item_id,
							  	qty_chequed
							  )

						SELECT		tporc.item_id,
									tporc.por_qty_Chequed

						FROM tbPurchaseOrderReceptionControl tporc		WITH (NOLOCK)



						WHERE	tporc.comp_id	= @comp_id			AND
								tporc.poh_id	= @poh_id



		   			  	DELETE

		   			  	FROM tbPurchaseOrderReceptionControl

						WHERE   comp_id			= @comp_id			AND
								poh_id			= @poh_id



						INSERT INTO tbPurchaseOrderReceptionControl
							(
										comp_id,
										bra_id,
										poh_id,
										item_id,
										por_qty_Ordered,
										por_qty_Chequed,
										por_userId4Close,
										por_closeDate,
										por_Receipted

							)
							SELECT
										tpod.comp_id,
										tpod.bra_id,
										tpod.poh_id,
										tpod.item_id,
										SUM(tpod.pod_qty),
										isnull(tmppo.qty_chequed,0),
										NULL,
										NULL,
										'false'


								FROM	tbPurchaseOrderDetail					tpod		WITH (NOLOCK)

								LEFT JOIN #tmpPurchaseOrderReceptionControl		tmppo
									ON tmppo.item_id	= tpod.item_id

								WHERE	tpod.comp_id	= @comp_id			AND
										tpod.poh_id		= @poh_id			AND
										tpod.item_id	IS NOT NULL

							GROUP BY	tpod.comp_id,
										tpod.bra_id,
										tpod.poh_id,
										tpod.item_id,
										tmppo.qty_chequed

				END



END

GO






create PROCEDURE [dbo].[spPurchaseOrderReceptionControl_VerificationBeforeCloseReception]
(

	@comp_id					INT,
	@poh_id						INT


)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE	  	@comp_id				INT,
			@poh_id					INT


SELECT		@comp_id				= 1,
			@poh_id					= 211

*/
-- ------------------------------------------------------




	IF NOT EXISTS ( SELECT tporc.poh_id
						FROM tbPurchaseOrderReceptionControl		tporc
						WHERE	tporc.comp_id		= @comp_id AND
								tporc.poh_id		= @poh_id  AND
								tporc.por_qty_Chequed > tporc.por_qty_Ordered
					)

		BEGIN
			--SELECT 'NO HAY NINGUN ARTICULO DONDE LA CANTIDAD PENDIENTE SEA MAYOR QUE LA CANTIDAD ORIGINAL '
			SELECT 1 [VerificationBeforeCloseReception]

		END
	ELSE

			BEGIN
			 --SELECT 'HAY ALGUN ARTICULO DONDE LA CANTIDAD PENDIENTE ES MAYOR QUE LA ORIGINAL'
			 SELECT 2 [VerificationBeforeCloseReception]

			END







END
GO






CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionControl_VerificationReceipted]
(

	@comp_id					INT,
	@poh_id						INT


)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE	  	@comp_id				INT,
			@poh_id					INT


SELECT		@comp_id				= 1,
			@poh_id					= 213
*/
-- ------------------------------------------------------




	IF NOT EXISTS ( SELECT tporc.poh_id
						FROM tbPurchaseOrderReceptionControl		tporc
						WHERE	tporc.comp_id		= @comp_id AND
								tporc.poh_id		= @poh_id  AND
								tporc.por_Receipted = 'False'
					)

		BEGIN
			--SELECT 'Ya está recibida la orden'
			SELECT 1 [VerificationReceipted]

		END
	ELSE

		BEGIN
		 --SELECT 'No está recibida la orden'
		 SELECT 0 [VerificationReceipted]

		END







END
GO




