--Desc	: Pagina de filtros de informe detallado de Recepcion de orden de compra
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spPurchaseOrderReceptionData_getDatabyFilters]
(

		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@supp_id			INT,
		@item_id			INT,
		@datefrom			DATETIME,
		@dateto				DATETIME,
		@ptr_id				INT,
		@optionStatus		INT,
		@por_id				INT,
		@guidItem			VARCHAR(50)



)
as
SET NOCOUNT ON

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@supp_id			INT,
				@item_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME,
				@ptr_id				INT,
				@optionStatus		INT,
				@por_id				INT,
				@guidItem			VARCHAR(50)



	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@supp_id			= -1,
				@user_id			= 1,
				@prof_id			= 1,
				@item_id			= -1,
				@ptr_id				= -1,
				@optionStatus		= -1,
				@datefrom			= '2010-12-01',
				@dateto				= '2015-12-31',
				@por_id				= 0
*/
-------------------------------------------------------------------------------------------

	SET @dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	DECLARE @lGuid AS UNIQUEIDENTIFIER

	SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@guidItem)

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Items
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Items
				SELECT ti.item_id
					FROM tbItem ti
					WHERE ti.comp_id = @comp_id
		END
	-- -------------------------------------------------------------




	--DECLARE @bithideDecimalsOnStock AS BIT
	--SELECT	@bithideDecimalsOnStock = tc.comp_hideDecimalsOnStock
	--	    FROM tbCompany tc
	--	    WHERE tc.comp_id = @comp_id


		SELECT  --tpoh.poh_deliveryDate																[poh_deliveryDate],
				ti.item_code																		[item_code],
				ti.item_desc																		[item_desc],
				sum(tprd.pord_qty)																	[pord_qty],
				tprh.por_id																			[por_id],
				ts.supp_id																			[supp_id],
				ts.supp_name																		[supp_name],
				--CASE
				--    WHEN @bithideDecimalsOnStock = 'True' THEN	 convert(nvarchar(50),Convert(decimal(19,0),tprd.pord_qty))
				--    ELSE   										convert(nvarchar(50),tprd.pord_qty)
				--END																					[pord_qty],
				--tprh.por_charge2Supplier_Note														[por_charge2Supplier_Note],
				--tprh.por_charge2Delivery_Note														[por_charge2Delivery_Note],
			    --tprd.poh_id																			[poh_id],
				--dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)	[ct_desc],
				--tprh.por_docNumber																	[por_docNumber],
				--isnull(ts2.stor_desc,'')															[stor_desc],
				--tu.user_lastname + ', ' + tu.user_firstname											[user_name],
				--tprh.por_lastClose																	[por_lastClose],
				--tovcharge2Supplier.optval_desc														[por_charge2Supplier],
				--tovcharge2Delivery.optval_desc														[por_charge2Delivery],
				isnull(tpt.ptr_name,'')																[ptr_name],
				--tov.optval_desc																		[status]

					CASE isnull(tprh.por_isCancelled,'False')
						WHEN 'True' THEN	tov2.optval_desc	-- Recepción Anulada
						ELSE
							CASE isnull(tprh.por_isClosed,0)
								WHEN 1 THEN
									CASE isnull(tprh.ct_transaction,0)
										WHEN 0 THEN	tov3.optval_desc
										ELSE		tov.optval_desc
									END
								ELSE	tov.optval_desc
							END
					END																					[status]



		FROM tbPurchaseorderReceptionHeader					tprh	WITH (NOLOCK)


		inner JOIN tbPurchaseorderReceptionDetail			tprd	WITH (NOLOCK)
		ON	tprd.comp_id		= tprh.comp_id		AND
			tprd.por_id			= tprh.por_id

		inner JOIN tbPurchaseOrderHeader					tpoh	WITH (NOLOCK)
		ON	tpoh.comp_id		= tprd.comp_id		AND
			tpoh.bra_id			= tprd.poh_bra_id	AND
			tpoh.poh_id			= tprd.poh_id

		inner JOIN tbItem									ti		WITH (NOLOCK)
		ON	ti.comp_id			= tprd.comp_id		AND
			ti.item_id			= tprd.item_id

		INNER JOIN @tblComplexFilter_Items tcf
		ON	tcf.item_id			= ti.item_id

		LEFT JOIN tbCommercialTransactions					tct		WITH (NOLOCK)
		ON	tct.comp_id			= tprh.comp_id		AND
			tct.ct_transaction	= tprh.ct_transaction

		--left JOIN tbItemTransactions						tit		WITH (NOLOCK)
		--ON	tit.comp_id			= tprh.comp_id		AND
		--	tit.bra_id			= tprh.bra_id		AND
		--	tit.ct_transaction	= tct.ct_transaction

		--LEFT JOIN tbStorage									ts2		WITH (NOLOCK)
		--ON	ts2.comp_id			= tit.comp_id		AND
		--	 ts2.stor_id		= tit.stor_id

		LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]		= tprh.user_id_closeReception

		LEFT JOIN tbPurchaseTransport						tpt		WITH (NOLOCK)
		ON	tpt.comp_id			= tprh.comp_id		AND
			tpt.ptr_id			= tprh.ptr_id

		LEFT JOIN tbSupplier								ts		WITH (NOLOCK)
		ON	ts.comp_id			= tprh.comp_id		AND
			ts.supp_id			= tprh.supp_id


		LEFT JOIN tbsysOptionsValues						tov		WITH (NOLOCK)
		ON	tov.lang_id			= @lang_id			AND
			tov.optval_id		= tprh.por_isClosed	AND
			tov.optval_class	= 523

		LEFT JOIN tbsysOptionsValues						tovcharge2Supplier		WITH (NOLOCK)
		ON	tovcharge2Supplier.lang_id			= @lang_id					AND
			tovcharge2Supplier.optval_id		= tprh.por_charge2Supplier	AND
			tovcharge2Supplier.optval_class		= 1

		LEFT JOIN tbsysOptionsValues						tovcharge2Delivery		WITH (NOLOCK)
		ON	tovcharge2Delivery.lang_id			= @lang_id					AND
			tovcharge2Delivery.optval_id		= tprh.por_charge2Delivery	AND
			tovcharge2Delivery.optval_class		= 1


		LEFT JOIN tbsysOptionsValues						tov2		WITH (NOLOCK)
		ON	tov2.lang_id		= @lang_id				AND
			tov2.optval_id		= 2						AND
			tov2.optval_class	= 523

		LEFT JOIN tbsysOptionsValues						tov3		WITH (NOLOCK)
		ON	tov3.lang_id		= @lang_id				AND
			tov3.optval_id		= 3						AND
			tov3.optval_class	= 523


		Where	tprh.comp_id	= @comp_id										 AND
				(@item_id		= -1	OR ti.item_id		= @item_id)			 AND
				(@por_id		= 0		OR tprh.por_id		= @por_id)			 AND
				(@supp_id		= -1	OR tprh.supp_id		= @supp_id)			 AND
				(@ptr_id		= -1	OR tprh.ptr_id		= @ptr_id)			 AND
				(tprh.por_lastClose		BETWEEN		@datefrom	AND	@dateto) AND
				--CASE
	   --				WHEN @chargeTo = -1																	THEN 'True'
	   --				WHEN @chargeTo =  1 AND tprh.por_charge2Supplier = 'True'							THEN 'True'
	   --				WHEN @chargeTo =  2 AND tprh.por_charge2Delivery = 'True'							THEN 'True'
	   --				ELSE 'False'
	   --			END	= 'True' AND

	   			--CASE
	   			--	WHEN @optionStatus = -1																THEN 'True'
	   			--	WHEN @optionStatus =  1 AND tprh.por_isClosed = 'True' AND tprd.pord_qty <> 0		THEN 'True'
	   			--	WHEN @optionStatus =  0 AND tprh.por_isClosed = 'False'								THEN 'True'
	   			--	ELSE 'False'
	   			--END	= 'True'

	   			CASE
	   				WHEN @optionStatus = -1																						 THEN 'True'
	   				WHEN @optionStatus =  1 AND tprh.por_isClosed	 = 'True' AND tprd.pord_qty <> 0 AND isnull(tprh.por_isCancelled,'False') = 'False' AND isnull(tprh.ct_transaction,0) <> 0 THEN 'True'
	   				WHEN @optionStatus =  0 AND tprh.por_isClosed	 = 'False' 													 THEN 'True'
	   				WHEN @optionStatus =  2 AND isnull(tprh.por_isCancelled,'False') = 'True'									 THEN 'True'
	   				WHEN @optionStatus =  3 AND isnull(tprh.por_isClosed,0) = 1 AND isnull(tprh.ct_transaction,0) = 0			 THEN 'True'
	   				ELSE 'False'
	   			END	= 'True'


		GROUP BY

				--tpoh.poh_deliveryDate,
				tprh.por_id	,
				ts.supp_id	,
				ts.supp_name,
				ti.item_code,
				ti.item_desc,
				tpt.ptr_name,
				tov.optval_desc,
				tprh.por_isCancelled,
				tprh.por_isClosed,
				tprh.ct_transaction,
				tov2.optval_desc,
				tov3.optval_desc


		--ORDER BY tpoh.poh_deliveryDate




END
GO




------------------------------------------------------------------------------------------------------
--Date	: 27/03/15
--Author: GA
--Desc	: Pagina de filtros de Recepcion de orden de compra sin datos de articulos
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spPurchaseOrderReceptionData_NoItems_getDatabyFilters]
(

		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@supp_id			INT,
		@datefrom			DATETIME,
		@dateto				DATETIME,
		@chargeTo			INT,
		@ptr_id				INT,
		@optionStatus		INT,
		@por_id				INT



)
as
SET NOCOUNT ON

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@supp_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME,
				@chargeTo			INT,
				@ptr_id				INT,
				@optionStatus		INT,
				@por_id				INT



	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@supp_id			= -1,
				@user_id			= 1,
				@prof_id			= 1,
				@chargeTo			= -1,
				@ptr_id				= -1,
				@optionStatus		= 0,
				@datefrom			= '2014-12-01',
				@dateto				= '2015-12-31',
				@por_id				= 0
*/
-------------------------------------------------------------------------------------------

	SET @dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')



		SELECT  DISTINCT ' '																					[ ],
						 ' '																					[ ],
						 ' '																					[ ],

				tprh.por_cd																			[por_cd],
				tprh.por_id																			[por_id],
				ts.supp_id																			[supp_id],
				--tprd.poh_id																			[poh_id],
				--tpoh.poh_deliveryDate																[poh_deliveryDate],
				ts.supp_name																		[supp_name],
				--tprh.por_charge2Supplier_Note														[por_charge2Supplier_Note],
				--tprh.por_charge2Delivery_Note														[por_charge2Delivery_Note],
				--dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)	[ct_desc],
				--tprh.por_docNumber																[por_docNumber],
				--tprd.pord_qty																		[pord_qty],
				isnull(tstor.stor_desc,'')															[stor_desc],
				--tprh.por_lastClose																	[por_lastClose],
				--tovcharge2Supplier.optval_desc														[por_charge2Supplier],
				--tovcharge2Delivery.optval_desc														[por_charge2Delivery],
				isnull(tpt.ptr_name,'')																[ptr_name],
				tu.user_lastname + ', ' + tu.user_firstname											[user_name],
				--tov.optval_desc																		[status],
				CASE isnull(tprh.por_isCancelled,'False') WHEN 'True' THEN
						tov2.optval_desc
				ELSE
					CASE isnull(tprh.por_isClosed,0) WHEN 1 THEN

						CASE isnull(tprh.ct_transaction,0) WHEN 0 THEN

							tov3.optval_desc
						ELSE
							tov.optval_desc
						END
					ELSE
						tov.optval_desc

					END

				END																					[status],
				--convert(varchar,isnull(tct.ct_transaction,0)) + '-'+ convert(varchar,ts.supp_id)	[ID],

				CASE isnull(tprh.por_isClosed,0) WHEN 1 THEN

									CASE isnull(tprh.ct_transaction,0) WHEN 0 THEN
									convert(varchar,-1) + '|'+ convert(varchar,ts.supp_id)
									ELSE
									convert(varchar,isnull(tct.ct_transaction,0)) + '|'+ convert(varchar,ts.supp_id)

									END
							ELSE
									convert(varchar,isnull(tct.ct_transaction,0)) + '|'+ convert(varchar,ts.supp_id)
							END										[ID]




		FROM tbPurchaseorderReceptionHeader					tprh	WITH (NOLOCK)

		LEFT JOIN tbCommercialTransactions					tct		WITH (NOLOCK)
		ON	tct.comp_id			= tprh.comp_id		AND
			tct.ct_transaction	= tprh.ct_transaction

		LEFT JOIN tbItemTransactions						tit		WITH (NOLOCK)
		ON	tit.comp_id			= tct.comp_id		AND
			tit.bra_id			= tct.bra_id		AND
			tit.ct_transaction	= tct.ct_transaction

		LEFT JOIN tbStorage									tstor	WITH (NOLOCK)
		ON	tstor.comp_id		= tit.comp_id		AND
			tstor.stor_id		= tit.stor_id

		LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]		= isnull(tct.[user_id],tprh.user_id_closeReception)

		LEFT JOIN tbPurchaseTransport						tpt		WITH (NOLOCK)
		ON	tpt.comp_id			= tprh.comp_id		AND
			tpt.ptr_id			= tprh.ptr_id

		LEFT JOIN tbSupplier								ts		WITH (NOLOCK)
		ON	ts.comp_id			= tprh.comp_id		AND
			ts.supp_id			= tprh.supp_id

		LEFT JOIN tbsysOptionsValues						tov		WITH (NOLOCK)
		ON	tov.lang_id			= @lang_id			AND
			tov.optval_id		= tprh.por_isClosed	AND
			tov.optval_class	= 523

		LEFT JOIN tbsysOptionsValues						tov2		WITH (NOLOCK)
		ON	tov2.lang_id		= @lang_id				AND
			tov2.optval_id		= 2						AND
			tov2.optval_class	= 523

		LEFT JOIN tbsysOptionsValues						tov3		WITH (NOLOCK)
		ON	tov3.lang_id		= @lang_id				AND
			tov3.optval_id		= 3						AND
			tov3.optval_class	= 523

		LEFT JOIN tbsysOptionsValues						tovcharge2Supplier		WITH (NOLOCK)
		ON	tovcharge2Supplier.lang_id			= @lang_id					AND
			tovcharge2Supplier.optval_id		= tprh.por_charge2Supplier	AND
			tovcharge2Supplier.optval_class		= 1

		LEFT JOIN tbsysOptionsValues						tovcharge2Delivery		WITH (NOLOCK)
		ON	tovcharge2Delivery.lang_id			= @lang_id					AND
			tovcharge2Delivery.optval_id		= tprh.por_charge2Delivery	AND
			tovcharge2Delivery.optval_class		= 1


		Where	tprh.comp_id	= @comp_id										 AND
				--(@item_id		= -1	OR tprd.item_id		= @item_id)			 AND
				(@por_id		= 0		OR tprh.por_id		= @por_id)			 AND
				(@supp_id		= -1	OR tprh.supp_id		= @supp_id)			 AND
				(@ptr_id		= -1	OR tprh.ptr_id		= @ptr_id)			 AND
				(tprh.por_lastClose		BETWEEN		@datefrom	AND	@dateto) AND
				CASE
	   				WHEN @chargeTo = -1																	THEN 'True'
	   				WHEN @chargeTo =  1 AND tprh.por_charge2Supplier = 'True'							THEN 'True'
	   				WHEN @chargeTo =  2 AND tprh.por_charge2Delivery = 'True'							THEN 'True'
	   				ELSE 'False'
	   			END	= 'True' AND

	   			CASE
	   				WHEN @optionStatus = -1																						 THEN 'True'
	   				WHEN @optionStatus =  1 AND tprh.por_isClosed	 = 'True' AND isnull(tprh.por_isCancelled,'False') = 'False' AND isnull(tprh.ct_transaction,0) <> 0 THEN 'True'
	   				WHEN @optionStatus =  0 AND tprh.por_isClosed	 = 'False' 													 THEN 'True'
	   				WHEN @optionStatus =  2 AND isnull(tprh.por_isCancelled,'False') = 'True'									 THEN 'True'
	   				WHEN @optionStatus =  3 AND isnull(tprh.por_isClosed,0) = 1 AND isnull(tprh.ct_transaction,0) = 0			 THEN 'True'
	   				ELSE 'False'
	   			END	= 'True'



		ORDER BY tprh.por_id desc




END
GO







