--Desc   :  agregar articulo q no esta en la orden de compra
------------------------------------------------------------------------------------------------------


create PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_AddItemValidate]
(

		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@supp_id			INT,
		@item_id			INT,
		@por_id				INT

)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE			@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@por_id			INT,
				@user_id			INT,
				@supp_id			INT,
				@item_id			INT


SELECT			@comp_id			= 1,
				@item_id			= 229,
				@supp_id			= 8145,
				@bra_id				= 1,
				@por_id				= 374

*/

-- ------------------------------------------------------


	-- 0 : Ya esta ese articulo en la recepcion
	-- 1 : Puede Agregar el articulo


	DECLARE @lavailable AS INT

	SET		@lavailable = 0



			IF EXISTS ( SELECT top 1 tpod.item_id			[item_id]

							FROM tbPurchaseOrderHeader						tpoh		WITH (NOLOCK)

							Inner Join tbPurchaseOrderDetail				tpod		WITH (NOLOCK)
							On  tpod.comp_id	= tpoh.comp_id		AND
								tpod.poh_id		= tpoh.poh_id		AND
								tpod.bra_id		= tpoh.bra_id

							INNER JOIN tbPurchaseorderReceptionDetail		tprd		WITH (NOLOCK)
							ON  tprd.comp_id	= tpod.comp_id		AND
								tprd.poh_bra_id = tpod.bra_id		AND
								tprd.poh_id		= tpod.poh_id		AND
								tprd.pod_id		= tpod.pod_id

							Where	tpod.comp_id	= @comp_id		AND
									tpod.item_id	= @item_id		AND
									tpoh.supp_id	= @supp_id		AND
									tprd.por_id		= @por_id
							)


				begin

						SET		@lavailable = 0

				END
				ELSE
					BEGIN
							SET		@lavailable = 1
					END

	-- 0 : Ya esta ese articulo en la recepcion
	-- 1 : Puede Agregar el articulo


SELECT @lavailable [Available]



END











GO





