CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_ByCancelled_InsertData]
(

	 	 @comp_id					INT,
		 @por_id					INT,
		 @poh_id					INT,
		 @pod_id					INT,
		 @user_id					INT,
		 @impData_Custom_local		NVARCHAR(200),
		 @impData_Number_local		NVARCHAR(200),
		 @impData_ExpirationDate	DATETIME,
		 @impData_Origin			NVARCHAR(200),
		 @impData_From				NVARCHAR(200),
		 @impdata_Stamp				NVARCHAR(200),
		 @AllItems					BIT,
		 @por_idCancelled			INT,
		 @return_value				as int	output

)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE			 @comp_id					INT,
				 @por_id					INT,
				 @poh_id					INT,
				 @pod_id					INT,
				 @user_id					INT,
				 @impData_Custom_local		NVARCHAR(200),
				 @impData_Number_local		NVARCHAR(200),
				 @impData_ExpirationDate	NVARCHAR(200),
				 @impData_Origin			NVARCHAR(200),
				 @impData_From				NVARCHAR(200),
				 @impdata_Stamp				NVARCHAR(200),
				 @AllItems					BIT,
				 @return_value				INT,
				 @por_idCancelled			INT

	SELECT		 @comp_id						= 1,
				 @por_id						= 464,
				 @poh_id						= 348,
				 @pod_id						= 21499,
				 @user_id						= 3,
				 @impData_Custom_local			= '',
				 @impData_Number_local			= '',
				 @impData_ExpirationDate		= '',
				 @impData_Origin				= '',
				 @impData_From					= '',
				 @impdata_Stamp					= '',
				 @por_idCancelled				= 461,
				 @AllItems						= 'True'
 */
-- ------------------------------------------------------



	Set @return_value	= 0

			INSERT INTO tbPurchaseorderReceptionDetail
			(
						comp_id,
						por_id,
						item_id,
						poh_bra_id,
						poh_id,
						pod_id,
						pord_qty,
						[user_id],
						impData_Custom_local,
						impData_Number_local,
						impData_ExpirationDate,
						impData_Origin,
						impData_From,
						impdata_Stamp
			)

				SELECT  @comp_id,
						@por_id,
						tpod.item_id,
						tpod.poh_bra_id,
						tpod.poh_id,
						tpod.pod_id,
						0,
						@user_id,
						@impData_Custom_local,
						@impData_Number_local,
						GETDATE(),
						@impData_Origin,
						@impData_From,
						@impdata_Stamp


				FROM	 tbPurchaseorderReceptionDetail		tpod			WITH (NOLOCK)


				WHERE	tpod.por_id		= @por_idCancelled  AND
						tpod.comp_id	= @comp_id			AND
						tpod.poh_id		= @poh_id			AND NOT EXISTS (SELECT 1
																			FROM tbPurchaseorderReceptionDetail			tbtc		WITH (NOLOCK)
																			WHERE	tbtc.comp_id		 = @comp_id		AND
																					tbtc.pod_id			 = tpod.pod_id	AND
																					tbtc.por_id			 = @por_id
																			)


		IF @@ERROR = 0 and @@ROWCOUNT = 1
		BEGIN
				Set @return_value = @@IDENTITY
		END



		-- ------------------------------------------------
		-- INtenta ubicar los POD que estan en NULL
		-- para compensar las nuevas O.Compra Seleccionadas
		-- ------------------------------------------------
		DECLARE @curpord_id		AS INT
		DECLARE @curitem_id		AS INT
		DECLARE @curpord_qty	AS DECIMAL(19,4)
		DECLARE @auxPordId		AS INT
		DECLARE @auxQTY			AS DECIMAL(19,4)

		DECLARE curPurchaseOrderReceptionDetail CURSOR LOCAL FAST_FORWARD FOR

			SELECT	tprd.pord_id,
					tprd.item_id,
					tprd.pord_qty

			FROM tbPurchaseorderReceptionDetail tprd
			WHERE	tprd.comp_id	= @comp_id AND
					tprd.por_id		= @por_id  AND
					tprd.poh_bra_id IS NULL

		OPEN curPurchaseOrderReceptionDetail
		-- lectura anticipada del cursor
		FETCH  curPurchaseOrderReceptionDetail INTO	@curpord_id,
													@curitem_id,
													@curpord_qty
		WHILE @@FETCH_STATUS = 0
			BEGIN


				SET @auxPordId = NULL

				-- Obtengo la QTY de la Orden de Compra
				SELECT TOP 1	@auxPordId	= tmp.pord_id,
								@auxQTY		= tpod.pod_qty - tmp.pord_qty

				FROM tbPurchaseorderReceptionDetail tmp
					INNER JOIN tbPurchaseOrderDetail tpod
						ON	tpod.comp_id	= tmp.comp_id AND
							tpod.bra_id		= tmp.poh_bra_id AND
							tpod.poh_id		= tmp.poh_id AND
							tpod.pod_id		= tmp.pod_id

				WHERE	tmp.comp_id = @comp_id			AND
						tmp.por_id	= @por_id			AND
						tmp.item_id = @curitem_id		AND
						tmp.pord_qty < tpod.pod_qty


				IF @auxPordId IS NOT NULL
					BEGIN

						IF @curpord_qty <= @auxQTY
							BEGIN

								UPDATE tbPurchaseorderReceptionDetail
									SET	pord_qty = pord_qty + @curpord_qty
									WHERE	comp_id = @comp_id	AND
											por_id	= @por_id	AND
											pord_id = @auxPordId

								DELETE FROM tbPurchaseorderReceptionDetail
									WHERE	comp_id = @comp_id	AND
											por_id	= @por_id	AND
											pord_id = @curpord_id
							END

						ELSE
							BEGIN

								UPDATE tbPurchaseorderReceptionDetail
									SET	pord_qty = pord_qty + @auxQTY
									WHERE	comp_id = @comp_id	AND
											por_id	= @por_id	AND
											pord_id = @auxPordId

								UPDATE  tbPurchaseorderReceptionDetail
									SET pord_qty = pord_qty  - @auxQTY
									WHERE	comp_id = @comp_id	AND
											por_id	= @por_id	AND
											pord_id = @curpord_id

							END

					END


				FETCH  curPurchaseOrderReceptionDetail INTO	@curpord_id,
															@curitem_id,
															@curpord_qty

			END

			CLOSE curPurchaseOrderReceptionDetail
			DEALLOCATE curPurchaseOrderReceptionDetail

		-- ------------------------------------------------



END



GO







CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_DeleteData]
(
	@comp_id				INT,
	@por_id					INT,
	@item_id				INT,
	@guid					UNIQUEIDENTIFIER,
	@qtyreceived			DECIMAL(19,4)
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------

		/*
		  DECLARE
  				@comp_id				INT,
				@por_id					INT,
				@item_id				INT



		  SELECT
  			@comp_id				= 1,
  			@por_id					= 243,
  			@item_id				= 256


		*/

		-- --------------------------------------------------------------------------
		DECLARE @lqtyfinal AS DECIMAL(19,4)

		SET @lqtyfinal = @qtyreceived


			IF EXISTS ( SELECT 1

						FROM tbPurchaseorderReceptionDetail

						WHERE	comp_id			= @comp_id	AND
								por_id			= @por_id	AND
								item_id			= @item_id	AND
								poh_bra_id		IS NULL		AND
								poh_id			IS NULL		AND
								pod_id			IS NULL
						)

            BEGIN

			DELETE

			FROM tbPurchaseorderReceptionDetail

			WHERE	comp_id			= @comp_id	AND
					por_id			= @por_id	AND
					item_id			= @item_id	AND
					poh_bra_id		IS NULL		AND
					poh_id			IS NULL		AND
					pod_id			IS NULL



            END


            ELSE


            	BEGIN


					DECLARE @lpoh_id	AS INT,
							@lpod_id	AS INT,
							@lqty		AS DECIMAL(19,4),
							@lpord_qty	AS DECIMAL(19,4)




					SET @lpoh_id = (
					SELECT TOP 1 tprd.poh_id
					 FROM tbPurchaseorderReceptionDetail tprd
							WHERE	tprd.comp_id		= @comp_id	AND
									tprd.por_id			= @por_id	AND
									tprd.item_id		= @item_id
					)

					SET @lpod_id = (
					SELECT TOP 1 tprd.pod_id
					 FROM tbPurchaseorderReceptionDetail tprd
							WHERE	tprd.comp_id		= @comp_id	AND
									tprd.por_id			= @por_id	AND
									tprd.item_id		= @item_id
					)




					SET @lpord_qty = (
					SELECT TOP 1 tprd.pord_qty
					 FROM tbPurchaseorderReceptionDetail tprd
							WHERE	tprd.comp_id		= @comp_id	AND
									tprd.por_id			= @por_id	AND
									tprd.item_id		= @item_id	AND
									tprd.pod_id			= @lpod_id
					)

					set @lqty =(SELECT TOP 1 tpod.pod_qty

								FROM tbPurchaseOrderHeader tpoh

								INNER JOIN tbPurchaseOrderDetail tpod
								ON tpod.comp_id = tpoh.comp_id AND
								   tpod.bra_id = tpoh.bra_id   AND
								   tpod.poh_id = tpoh.poh_id

								WHERE tpoh.comp_id = @comp_id AND
									  tpoh.poh_id  = @lpoh_id AND
									  tpod.item_id = @item_id AND
									  TPOD.pod_id  = @lpod_id )



					IF @lqty < @lpord_qty

					BEGIN

						UPDATE tbPurchaseorderReceptionDetail

						SET pord_qty = @lqty

						WHERE comp_id		= @comp_id  AND
							  por_id		= @por_id	AND
							  item_id		= @item_id	AND
							  pod_id		= @lpod_id
					END


            	END





		DECLARE @decPending AS DECIMAL(19,4)
		SET		@decPending = -1 * @qtyreceived

		exec spItemPartsCheckingProcess_InitializeParts @comp_id,@guid ,@item_id








--DECLARE @lpoh_id	AS INT,
