CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_DeleteItem]
(
	@comp_id				INT,
	@item_id				INT,
	@por_id					INT,
	@guid					UNIQUEIDENTIFIER,
	@qtyreceived			DECIMAL(19,4)
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*
		  DECLARE
  			@comp_id				int,
  			@pod_id					int

		  SELECT
  			@comp_id				= 1,
  			@pod_id					= 21149
*/
		-- --------------------------------------------------------------------------

		DELETE

		FROM tbPurchaseorderReceptionDetail

		WHERE	comp_id			= @comp_id	AND
				por_id			= @por_id	AND
				item_id			= @item_id



			IF NOT EXISTS ( SELECT 1

				FROM tbPurchaseorderReceptionDetail tprd		WITH (NOLOCK)

				WHERE	tprd.comp_id	= @comp_id AND
						tprd.por_id		= @por_id
				)

            BEGIN
            	DELETE

            		FROM tbPurchaseorderReceptionHeader

					WHERE	comp_id			= @comp_id	AND
							por_id			= @por_id

            END



		exec spItemPartsCheckingProcess_MinusParts @comp_id,@guid ,@item_id, @qtyreceived



END

GO







CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_Initialize_qty]
(
	@comp_id				INT,
	@por_id					INT,
	@item_id				INT,
	@guid					UNIQUEIDENTIFIER,
	@qtyreceived			DECIMAL(19,4)


)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*
		  DECLARE
  					@comp_id				INT,
					@por_id					INT,
					@item_id				INT

		  SELECT
  					@comp_id				= 1,
  					@por_id					= 43,
  					@item_id				=256
*/
		-- --------------------------------------------------------------------------




		UPDATE tbPurchaseorderReceptionDetail

		SET		pord_qty = 0


		WHERE  comp_id			= @comp_id	AND
			   por_id			= @por_id	AND
			   item_id			= @item_id


		exec spItemPartsCheckingProcess_MinusParts @comp_id,@guid ,@item_id, @qtyreceived



END

GO






------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: Graba en la Detail tbPurchaseorderReceptionDetail
--


-- 17/11/14 se comento los poh_id para que no filtre por una orden sola
------------------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_InsertData]
(

	  @comp_id INT,
	  @por_id INT,
	  @poh_id INT,
	  @pod_id INT,
	  @user_id INT,
	  @impData_Custom_local NVARCHAR(200),
	  @impData_Number_local NVARCHAR(200),
	  @impData_ExpirationDate DATETIME,
	  @impData_Origin NVARCHAR(200),
	  @impData_From NVARCHAR(200),
	  @impdata_Stamp NVARCHAR(200),
	  @AllItems BIT,
	  @return_value as int output

)
AS

BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
	DECLARE  @comp_id INT,
	@por_id INT,
	@poh_id INT,
	@pod_id INT,
	@user_id INT,
	@impData_Custom_local NVARCHAR(200),
	@impData_Number_local NVARCHAR(200),
	@impData_ExpirationDate NVARCHAR(200),
	@impData_Origin NVARCHAR(200),
	@impData_From NVARCHAR(200),
	@impdata_Stamp NVARCHAR(200),
	@AllItems BIT,
	@return_value int

	SELECT  @comp_id = 1,
	@por_id = 366,
	@poh_id = 261,
	@pod_id = 21319,
	@user_id = 3,
	@impData_Custom_local = '',
	@impData_Number_local = '',
	@impData_ExpirationDate = '',
	@impData_Origin = '',
	@impData_From = '',
	@impdata_Stamp = '',
	@AllItems = 'False'
	*/
	-- ------------------------------------------------------



	Set @return_value = 0


	IF NOT EXISTS ( SELECT TOP 1  tbtc.pod_id
						FROM tbPurchaseorderReceptionDetail tbtc		WITH (NOLOCK)
						INNER JOIN tbPurchaseorderReceptionHeader tprh	WITH (NOLOCK)
							ON	tprh.comp_id	= tbtc.comp_id AND
								tprh.por_id		= tbtc.por_id
						WHERE	tbtc.comp_id	= @comp_id AND
								tbtc.pod_id		= @pod_id  AND
						-- tbtc.poh_id = @poh_id  AND
								tprh.por_isClosed = 'false'
				)
	BEGIN



	INSERT INTO tbPurchaseorderReceptionDetail
	(
	comp_id,
	por_id,
	item_id,
	poh_bra_id,
	poh_id,
	pod_id,
	pord_qty,
	[user_id],
	impData_Custom_local,
	impData_Number_local,
	impData_ExpirationDate,
	impData_Origin,
	impData_From,
	impdata_Stamp
	)

	SELECT  @comp_id,
		@por_id,
		tpod.item_id,
		tpod.bra_id,
		tpod.poh_id,
		tpod.pod_id,
		0,
		@user_id,
		@impData_Custom_local,
		@impData_Number_local,
		GETDATE(),
		@impData_Origin,
		@impData_From,
		@impdata_Stamp

	FROM		tbPurchaseOrderDetail			tpod WITH (NOLOCK)
	INNER JOIN	tbPurchaseOrderHeader			tpoh WITH (NOLOCK)
		ON  tpoh.comp_id = tpod.comp_id AND
		tpoh.bra_id = tpod.bra_id AND
		tpoh.poh_id = tpod.poh_id
	WHERE
		tpod.pod_isProcessed ='False' AND
		ISNULL(tpod.pod_confirmedQTY,0) = 0  AND
		CASE
			WHEN @AllItems = 'False' AND tpod.comp_id = @comp_id AND tpoh.pho_selectedInRecepcion='True' AND    tpod.pod_id = @pod_id  THEN 1

			WHEN @AllItems = 'True'  AND tpod.comp_id = @comp_id AND  tpoh.pho_selectedInRecepcion= 'True' AND tpoh.poh_id = @poh_id AND NOT EXISTS (	SELECT TOP 1  1
																																							FROM tbPurchaseorderReceptionDetail tbtc WITH (NOLOCK)
																																							WHERE	tbtc.comp_id  = @comp_id AND
																																									tbtc.pod_id   = tpod.pod_id AND
																																									tbtc.por_id   = @por_id
 																																							) THEN 1
			ELSE 0
		END = 1







	Set @return_value = @@IDENTITY



	END


	-- ------------------------------------------------
	-- INtenta ubicar los POD que estan en NULL
	-- para compensar las nuevas O.Compra Seleccionadas
	-- ------------------------------------------------
	DECLARE @curpord_id AS INT
	DECLARE @curitem_id AS INT
	DECLARE @curpord_qty AS DECIMAL(19,4)
	DECLARE @auxPordId AS INT
	DECLARE @auxQTY AS DECIMAL(19,4)

	DECLARE curPurchaseOrderReceptionDetail CURSOR LOCAL FAST_FORWARD FOR

	SELECT	tprd.pord_id,
			tprd.item_id,
			tprd.pord_qty
		FROM tbPurchaseorderReceptionDetail tprd	WITH (NOLOCK)
		WHERE	tprd.comp_id	= @comp_id AND
				tprd.por_id		= @por_id  AND
				tprd.poh_bra_id IS NULL

	OPEN curPurchaseOrderReceptionDetail
	-- lectura anticipada del cursor
	FETCH  curPurchaseOrderReceptionDetail INTO @curpord_id,
												@curitem_id,
												@curpord_qty
	WHILE @@FETCH_STATUS = 0
		BEGIN


		SET @auxPordId = NULL

		-- Obtengo la QTY de la Orden de Compra
		SELECT TOP 1 @auxPordId = tmp.pord_id,
			@auxQTY = tpod.pod_qty - tmp.pord_qty
			FROM tbPurchaseorderReceptionDetail tmp		WITH (NOLOCK)
				INNER JOIN tbPurchaseOrderDetail tpod	WITH (NOLOCK)
				ON	tpod.comp_id = tmp.comp_id AND
					tpod.bra_id  = tmp.poh_bra_id AND
					tpod.poh_id  = tmp.poh_id AND
					tpod.pod_id  = tmp.pod_id
			WHERE	tmp.comp_id  = @comp_id AND
					tmp.por_id   = @por_id AND
					tmp.item_id  = @curitem_id AND
					tmp.pord_qty < tpod.pod_qty




		IF @auxPordId IS NOT NULL
		BEGIN

		IF @curpord_qty <= @auxQTY
			BEGIN

				UPDATE tbPurchaseorderReceptionDetail
					SET pord_qty = pord_qty + @curpord_qty
					WHERE	comp_id = @comp_id AND
							por_id = @por_id AND
							pord_id = @auxPordId

				DELETE FROM tbPurchaseorderReceptionDetail
					WHERE	comp_id = @comp_id AND
							por_id = @por_id AND
							pord_id = @curpord_id

			END

		ELSE
			BEGIN

				UPDATE tbPurchaseorderReceptionDetail
					SET pord_qty = pord_qty + @auxQTY
					WHERE	comp_id = @comp_id AND
							por_id = @por_id AND
							pord_id = @auxPordId

				UPDATE  tbPurchaseorderReceptionDetail
					SET pord_qty = pord_qty  - @auxQTY
					WHERE	comp_id = @comp_id AND
							por_id = @por_id AND
							pord_id = @curpord_id

			END

		END


		FETCH  curPurchaseOrderReceptionDetail INTO @curpord_id,
		@curitem_id,
		@curpord_qty

		END

	CLOSE curPurchaseOrderReceptionDetail
	DEALLOCATE curPurchaseOrderReceptionDetail

	-- ------------------------------------------------



END



GO







------------------------------------------------------------------------------------------------------
--Date   : 29/12
--Author :	GA
--Desc   :  agregar articulo q no esta en la orden de compra
------------------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_InsertItemOnlyCheck]
(

		@comp_id			INT,
		@item_id			INT,
		@por_id				INT,
		@qty_entered		DECIMAL(19,4)

)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE			@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@por_id			INT,
				@user_id			INT,
				@supp_id			INT,
				@item_id			INT


SELECT			@comp_id			= 1,
				@item_id			= 229,
				@supp_id			= 8145,
				@bra_id				= 1,
				@por_id				= 374

*/

-- ------------------------------------------------------

IF NOT EXISTS ( SELECT tprd.item_id
					FROM tbPurchaseorderReceptionDetail tprd
					WHERE	tprd.comp_id	= @comp_id  AND
							tprd.item_id	= @item_id  AND
							tprd.poh_bra_id IS NULL		AND
							tprd.poh_id		IS NULL		AND
							tprd.pod_id		IS NULL		AND
							tprd.por_id		= @por_id
					)

		BEGIN


				--Agregamos un registro en "ROJO" sin poh_id ,pod_id con la cantidad correspondiente(se paso de la mercaderia solicitada)
				INSERT INTO tbPurchaseorderReceptionDetail
				(
							comp_id,
							por_id,
							item_id,
							poh_bra_id,
							poh_id,
							pod_id,
							pord_qty,
							[user_id],
							impData_Custom_local,
							impData_Number_local,
							impData_ExpirationDate,
							impData_Origin,
							impData_From,
							impdata_Stamp
				)

				VALUES
				(
							@comp_id,
							@por_id,
							@item_id,
							NULL,
							NULL,
							NULL,
							@qty_entered,
							NULL,
							NULL,
							NULL,
							GETDATE(),
							NULL,
							NULL,
							NULL

				)


		END

	ELSE

		BEGIN
			UPDATE tbPurchaseorderReceptionDetail
			SET

				pord_qty = pord_qty + @qty_entered

			WHERE	comp_id		= @comp_id  AND
					item_id		= @item_id  AND
					poh_bra_id  IS NULL		AND
					poh_id		IS NULL		AND
					pod_id		IS NULL		AND
					por_id		= @por_id
		END







END












GO






CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_ItemSelected]
(

	 	 @comp_id					INT,
		 @pod_id					INT,
		 @poh_id					int

)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE		 @comp_id					INT,
				 @pod_id					INT,
				 @poh_id					int


	SELECT		 @comp_id						= 1,
				 @pod_id						= 21239,
				 @poh_id						= 240
*/
-- ------------------------------------------------------


	IF NOT EXISTS ( SELECT tbtc.pod_id
					FROM tbPurchaseorderReceptionDetail				tbtc WITH (NOLOCK)

					INNER JOIN tbPurchaseorderReceptionHeader		tprh WITH (NOLOCK)
					ON tprh.comp_id		= tbtc.comp_id AND
