------------------------------------------------------------------------------------------------------
--Date   : 29/12
--Author :	GA
--Desc   :  recepcion de orden de compra .Verificar si el item esta relacionado al proveedor para poder agregarlo.
------------------------------------------------------------------------------------------------------


create PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_ItemSupplier]
(

		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@supp_id			INT,
		@item_id			INT

)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE			@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@supp_id			INT,
				@item_id			INT


SELECT			@comp_id			= 1,
				@item_id			= 229,
				@supp_id			= 8145,
				@bra_id				= 1,
				@prof_id			= 1
 */
-- ------------------------------------------------------

	-- 1 : Puede Agregar cualquier articulo
	-- 0 : No puede agregar el articulo porque no esta relacioando al proveedor
	-- 2 : Puede agregar el articulo xq esta relacioando al proveedor

	DECLARE @lavailable AS INT

	SET		@lavailable = 1



		IF NOT EXISTS ( SELECT top 1 1

						FROM tbItemSupplier				tis	WITH (NOLOCK)

						Where	tis.comp_id	= @comp_id		AND
								tis.bra_id	= @bra_id		AND
								tis.item_id = @item_id
					  )

			BEGIN
				 --Puede Agregar cualquier articulo
				SET @lavailable = 1
			END

		ELSE


			BEGIN

			IF  EXISTS ( SELECT top 1 ti.item_id

						 FROM tbItem ti	WITH (NOLOCK)


						 Where	ti.comp_id	= @comp_id		AND
								ti.supp_id 	= @supp_id		AND
								ti.item_id	= @item_id		AND
								(ti.bra_id	= @bra_id OR ti.bra_id IS NULL)
			)

				BEGIN
						--Puede agregar ese item para ese proveedor
						SET @lavailable = 2

				END
			ELSE

				BEGIN

						IF NOT EXISTS ( SELECT tis.item_id
										FROM tbItemSupplier					tis

										WHERE	tis.comp_id	= @comp_id		AND
												tis.supp_id = @supp_id		AND
												tis.item_id	= @item_id		AND
												(tis.bra_id	= @bra_id OR tis.bra_id IS NULL)
										)
							BEGIN
								SET @lavailable = 0
							END

						ELSE
							BEGIN
								SET @lavailable = 2
							END



				END


				END



-- 1 : Puede Agregar cualquier articulo
-- 0 : No puede agregar el articulo porque no esta relacioando al proveedor
-- 2 : Puede agregar el articulo xq esta relacioando al proveedor


SELECT @lavailable [Available]



END











GO





CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_QtyMinus]
(
	@comp_id				INT,
	@por_id				    INT,
	@item_id				INT,
	@guid					UNIQUEIDENTIFIER




)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*
		  DECLARE
  					@comp_id				INT,
					@por_id				    INT,
					@item_id				INT

		  SELECT
  					@comp_id				= 1,
  					@item_id				= 229,
  					@por_id					= 273
*/
		-- --------------------------------------------------------------------------






IF EXISTS ( SELECT 1

			FROM tbPurchaseorderReceptionDetail

			WHERE	comp_id			= @comp_id	AND
					por_id			= @por_id	AND
					item_id			= @item_id	AND
					poh_bra_id		IS NULL		AND
					poh_id			IS NULL		AND
					pod_id			IS NULL
			)

	BEGIN

		DECLARE @lpord_qty	AS DECIMAL(19,4)

					SET @lpord_qty = (
							SELECT TOP 1 tprd.pord_qty
							 FROM tbPurchaseorderReceptionDetail tprd
							WHERE	tprd.comp_id			= @comp_id	AND
									tprd.por_id				= @por_id	AND
									tprd.item_id			= @item_id	AND
									tprd.poh_bra_id		IS NULL		AND
									tprd.poh_id			IS NULL		AND
									tprd.pod_id			IS NULL
					)



					if @lpord_qty = 1
					BEGIN
						DELETE

						FROM tbPurchaseorderReceptionDetail

						WHERE	comp_id			= @comp_id	AND
								por_id			= @por_id	AND
								item_id			= @item_id	AND
								poh_bra_id		IS NULL		AND
								poh_id			IS NULL		AND
								pod_id			IS NULL

					END
						ELSE

							BEGIN
									UPDATE tbPurchaseorderReceptionDetail

									SET		pord_qty = pord_qty - 1

									WHERE	comp_id			= @comp_id	AND
											por_id			= @por_id	AND
											item_id			= @item_id	AND
											poh_bra_id		IS NULL		AND
											poh_id			IS NULL		AND
											pod_id			IS NULL

							END


	END
		ELSE
		BEGIN

			DECLARE @lpod_id AS INT


			SET @lpod_id = (
								SELECT TOP 1 tpod.pod_id


								FROM tbPurchaseorderReceptionDetail tpod

								WHERE tpod.comp_id			= @comp_id AND
									  tpod.por_id			= @por_id  AND
									  tpod.item_id			= @item_id AND
									  tpod.PORD_QTY			> 0


								ORDER BY tpod.poh_id DESC
			)


				UPDATE tbPurchaseorderReceptionDetail

				SET		pord_qty = pord_qty - 1


				WHERE  comp_id			= @comp_id	AND
					   pod_id			= @lpod_id




			END




		exec spItemPartsCheckingProcess_MinusParts @comp_id,@guid ,@item_id, 1




END

GO







------------------------------------------------------------------------------------------------------
--Date:
--Author:GA
--Desc: Actualiza la cantidad del articulo correspondiente.
------------------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_UpdateData]
(

	 	 @comp_id					INT,
	 	 @supp_id					INT,
		 @item_id					INT,
		 @qty_entered				DECIMAL(19,4),
		 @por_id					INT,
		 @guid						uniqueidentifier,
		 @strEAN					NVARCHAR(50)

)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE			 @comp_id					INT,
	 				 @supp_id					INT,
					 @item_id					INT,
					 @qty_entered				DECIMAL(19,4),
					 @por_id					INT,
					 @guid						uniqueidentifier,
					 @strEAN					NVARCHAR(50)


	SELECT			 @comp_id					= 1,
					 @item_id					= -1,
					 @supp_id					= 8149,
					 @qty_entered				= 1,
					 @por_id					= 327,
					 @guid						= '8395475c-507d-4e3b-bfa3-b0ff0e19bcc9',
					 @strEAN					= '123'

	*/
-- ------------------------------------------------------



--mos
--llamas a sp
--si es = -1 lo que tiene strean RETURN
--SET @item_id = buscar @strEAN en item_code
--si existe seguir
--sino, return

	DECLARE @qty_CheckingTable AS DECIMAL(19,4)



	IF @strEAN <> ''

		BEGIN

			exec [spItemPartsCheckingProcess]@comp_id,@guid ,@qty_entered OUTPUT,@strEAN OUTPUT

			SET @qty_CheckingTable = @qty_entered

			IF @strEAN = '-1'
				BEGIN
					RETURN
				END
			ELSE
				BEGIN
					SET @item_id = ( select TOP 1 ti.item_id
										 from tbItem		ti		WITH(NOLOCK)
										 LEFT JOIN tbItemEAN tie	WITH(NOLOCK)
											ON	tie.comp_id = ti.comp_id AND
												tie.item_id = ti.item_id
										 WHERE ti.comp_id	= @comp_id AND
											   (ti.item_code = @strEAN OR tie.ie_ean = @strEAN)
									)

				END
		END


	IF @item_id IS NULL
		BEGIN
			RETURN
		END
	ELSE
		BEGIN

			IF EXISTS ( SELECT top 1 tpod.item_id			[item_id]

							FROM tbPurchaseOrderHeader						tpoh		WITH (NOLOCK)

							Inner Join tbPurchaseOrderDetail				tpod		WITH (NOLOCK)
							On  tpod.comp_id	= tpoh.comp_id		AND
								tpod.poh_id		= tpoh.poh_id		AND
								tpod.bra_id		= tpoh.bra_id

							INNER JOIN tbPurchaseorderReceptionDetail		tprd		WITH (NOLOCK)
							ON  tprd.comp_id	= tpod.comp_id		AND
								tprd.poh_bra_id = tpod.bra_id		AND
								tprd.poh_id		= tpod.poh_id		AND
								tprd.pod_id		= tpod.pod_id

							Where	tpod.comp_id	= @comp_id		AND
									tpod.item_id	= @item_id		AND
									tpoh.supp_id	= @supp_id		AND
									tprd.por_id		= @por_id
							)


				begin



						--declare para el cursor
						DECLARE @lpod_id INT ,@litem_id INT, @lpod_qty_available DECIMAL(19,5)

						--cursor para recorrer PurchaseOrderDetail para traer la cantidad disponible ( cantidad de pod menos la cantidad de pord )
						DECLARE cursor_PORD CURSOR LOCAL FAST_FORWARD FOR

							SELECT tpod.pod_id					[pod_id],
								   tpod.item_id					[item_id],
								   tpod.pod_qty - tprd.pord_qty [lpod_qty_available]


							FROM tbPurchaseOrderHeader						tpoh		WITH (NOLOCK)

							Inner Join tbPurchaseOrderDetail				tpod		WITH (NOLOCK)
							On  tpod.comp_id	= tpoh.comp_id		AND
								tpod.poh_id		= tpoh.poh_id		AND
								tpod.bra_id		= tpoh.bra_id

							INNER JOIN tbPurchaseorderReceptionDetail		tprd		WITH (NOLOCK)
							ON tprd.comp_id		= tpod.comp_id		AND
								tprd.poh_bra_id = tpod.bra_id		AND
								tprd.poh_id		= tpod.poh_id		AND
								tprd.pod_id		= tpod.pod_id		AND
								tprd.por_id		= @por_id

							Where	tpod.comp_id	= @comp_id		AND
									tpod.item_id	= @item_id		AND
									tpoh.supp_id	= @supp_id

							ORDER BY tpoh.poh_deliveryDate,tprd.pord_id


						OPEN cursor_PORD
							-- lectura anticipada del cursor
							FETCH cursor_PORD INTO @lpod_id,@litem_id,@lpod_qty_available
							WHILE @@FETCH_STATUS = 0
							BEGIN



										--Si la cantidad ingresada es menor igual que la disponible
										IF @qty_entered <= @lpod_qty_available

											BEGIN


														UPDATE tbPurchaseorderReceptionDetail
															SET		pord_qty		= pord_qty + @qty_entered
															WHERE	comp_id			= @comp_id
															AND		item_id 		= @litem_id
															AND		pod_id 			= @lpod_id
															AND		por_id			= @por_id

														SET @qty_entered = 0

											END
										ELSE
											BEGIN
												--La cantidad ingresada es mayor que la disponible.
													UPDATE tbPurchaseorderReceptionDetail
														SET		pord_qty		= pord_qty + @lpod_qty_available
														WHERE	comp_id			= @comp_id
														AND		item_id 		= @litem_id
														AND		pod_id 			= @lpod_id
														AND		por_id			= @por_id


													SET @qty_entered = @qty_entered - @lpod_qty_available


											END

							FETCH cursor_PORD INTO @lpod_id, @litem_id , @lpod_qty_available



						END

						CLOSE cursor_PORD
						DEALLOCATE cursor_PORD


						IF @qty_entered > 0
							BEGIN

								IF NOT EXISTS ( SELECT tprd.item_id
													FROM tbPurchaseorderReceptionDetail tprd		WITH (NOLOCK)
													WHERE	tprd.comp_id	= @comp_id  AND
															tprd.item_id	= @item_id  AND
															tprd.poh_bra_id IS NULL		AND
															tprd.poh_id		IS NULL		AND
															tprd.pod_id		IS NULL		AND
															tprd.por_id		= @por_id
													)

										BEGIN


												--Agregamos un registro en "ROJO" sin poh_id ,pod_id con la cantidad correspondiente(se paso de la mercaderia solicitada)
												INSERT INTO tbPurchaseorderReceptionDetail
												(
															comp_id,
															por_id,
															item_id,
															poh_bra_id,
															poh_id,
															pod_id,
															pord_qty,
															[user_id],
															impData_Custom_local,
															impData_Number_local,
															impData_ExpirationDate,
															impData_Origin,
															impData_From,
															impdata_Stamp
												)

												VALUES
												(
															@comp_id,
															@por_id,
															@item_id,
															NULL,
															NULL,
															NULL,
															@qty_entered,
															NULL,
															NULL,
															NULL,
															GETDATE(),
															NULL,
															NULL,
															NULL

												)


										END

									ELSE

										BEGIN
											UPDATE tbPurchaseorderReceptionDetail
												SET
													pord_qty = pord_qty + @qty_entered
												WHERE	comp_id		= @comp_id  AND
														item_id		= @item_id  AND
														poh_bra_id  IS NULL		AND
														poh_id		IS NULL		AND
														pod_id		IS NULL		AND
														por_id		= @por_id
										END



							END

						--mos poner 2doi sp aca

							exec [spItemPartsCheckingProcess_FreeParts] @comp_id,@guid ,@item_id,@qty_CheckingTable
				END

			ELSE


					BEGIN


							IF NOT EXISTS ( SELECT top 1 1
												FROM tbItemSupplier				tis	WITH (NOLOCK)
												Where	tis.comp_id	= @comp_id		AND
														tis.item_id = @item_id
									  )

							BEGIN
								 --Puede Agregar cualquier articulo
								exec [spPurchaseOrderReceptionDetail_InsertItemOnlyCheck] @comp_id ,@item_id,@por_id , @qty_entered
							END

						ELSE


							BEGIN

								IF  EXISTS ( SELECT top 1 ti.item_id
												 FROM tbItem ti	WITH (NOLOCK)
												 Where	ti.comp_id	= @comp_id		AND
														ti.supp_id 	= @supp_id		AND
														ti.item_id	= @item_id
											)

									BEGIN
											--Puede agregar ese item para ese proveedor
											exec [spPurchaseOrderReceptionDetail_InsertItemOnlyCheck] @comp_id ,@item_id,@por_id , @qty_entered

									END
								ELSE

									BEGIN

											IF NOT EXISTS ( SELECT tis.item_id
																FROM tbItemSupplier					tis		WITH (NOLOCK)

																WHERE	tis.comp_id	= @comp_id		AND
																		tis.supp_id = @supp_id		AND
																		tis.item_id	= @item_id
															)
												BEGIN
													RETURN
												END

											ELSE
												BEGIN
													exec [spPurchaseOrderReceptionDetail_InsertItemOnlyCheck] @comp_id ,@item_id,@por_id , @qty_entered
												END



									END


							END



					END



			END

END
GO







CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_UpdateIT_Transaction]
(
@comp_id					INT,
@por_id						INT,
@bra_id						INT,
@ct_transaction				INT


)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
		/*
		  DECLARE		@comp_id					INT,
						@por_id						INT,
						@bra_id						INT,
						@ct_transaction				INT

		  SELECT
  						@comp_id				= 1,
  						@ct_transaction			= 10356,
  						@por_id					= 368,
  						@bra_id					= 1

  		*/
		-- --------------------------------------------------------------------------

			--declare para el cursor
			DECLARE @lit_transaction INT ,@litem_id INT,@lit_poh_id INT



			DECLARE cursor_ITtransaction CURSOR LOCAL FAST_FORWARD FOR

				SELECT tit.it_transaction		[it_transaction],
					   tit.item_id				[item_id],
					   tit.it_poh_id			[it_poh_id]


				FROM tbItemTransactions									tit			WITH (NOLOCK)

				WHERE  tit.comp_id			= @comp_id			AND
					   tit.bra_id			= @bra_id			AND
					   tit.ct_transaction	= @ct_transaction

			OPEN cursor_ITtransaction

							-- lectura anticipada del cursor
							FETCH cursor_ITtransaction INTO @lit_transaction,@litem_id,@lit_poh_id
							WHILE @@FETCH_STATUS = 0
							BEGIN


									UPDATE tbPurchaseorderReceptionDetail
										SET it_transaction		= @lit_transaction
										WHERE	comp_id			= @comp_id
											AND		por_id			= @por_id
											AND		item_id 		= @litem_id
											AND		poh_id			= @lit_poh_id


								FETCH cursor_ITtransaction INTO @lit_transaction,@litem_id,@lit_poh_id

						END

						CLOSE cursor_ITtransaction
						DEALLOCATE cursor_ITtransaction




END

GO







CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionDetail_UpdateSelectedOrder]
(
	@comp_id					INT,
	@supp_id					INT,
	@poh_id						INT,
	@pho_selectedInRecepcion	BIT,
	@bra_id						INT,
	@por_id						INT




)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*
		  DECLARE
  					@comp_id				INT,
					@supp_id				INT,
					@poh_id					INT,
					@bra_id						INT

		  SELECT
  					@comp_id				= 1,
  					@supp_id				= 8145,
  					@poh_id					= 256,
  					@bra_id					= 1
*/
		-- --------------------------------------------------------------------------



		IF @pho_selectedInRecepcion = 'False'
			BEGIN

				-- Si tiene una recepcionj abierta la usa, por ahora no dependiendo de la sucursal en cuestion.
				-- o sea, si se recibe de mas de una sucursal van todas a la misma recepcion.
				IF EXISTS(	SELECT 1

								FROM tbPurchaseorderReceptionDetail			tprd	WITH (NOLOCK)

								INNER JOIN tbPurchaseOrderHeader			tpoh	WITH (NOLOCK)
								ON	tpoh.comp_id	= tprd.comp_id
								AND tpoh.bra_id		= tprd.poh_bra_id
								AND tpoh.poh_id		= tprd.poh_id

								INNER JOIN tbPurchaseorderReceptionHeader	tprh	WITH (NOLOCK)
								ON	tprh.comp_id	= tprd.comp_id AND
									tprh.por_id		= tprd.por_id

				          		WHERE	tprd.comp_id			= @comp_id	AND
      									tprd.poh_id				= @poh_id	AND
      									tpoh.supp_id			= @supp_id	AND
      									tprh.por_isClosed		= 'False'	AND
      									tprd.pord_qty			> 0
						)
					BEGIN
						RETURN
					END


					DELETE FROM tbPurchaseorderReceptionDetail
						WHERE	comp_id = @comp_id	AND
								poh_id	= @poh_id	AND
								por_id	= @por_id



					UPDATE tbPurchaseOrderHeader
						SET	   pho_selectedInRecepcion = @pho_selectedInRecepcion
						WHERE  comp_id			= @comp_id	AND
							   bra_id			= @bra_id	AND
							   poh_id			= @poh_id	AND
							   supp_id			= @supp_id

		END





		UPDATE tbPurchaseOrderHeader
			SET
				pho_selectedInRecepcion = @pho_selectedInRecepcion
			WHERE  comp_id			= @comp_id	AND
				   bra_id			= @bra_id	AND
				   poh_id			= @poh_id	AND
				   supp_id			= @supp_id






END

GO







CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionHeader_DeleteData]
(
	@comp_id				INT,
	@pod_id					INT,
	@por_id					INT
)
as

BEGIN

	set nocount on

		-- --------------------------------------------------------------------------
		-- Testing
		-- --------------------------------------------------------------------------
/*
		  DECLARE
  			@comp_id				int,
  			@pod_id					int

		  SELECT
  			@comp_id				= 1,
  			@pod_id					= 21149
*/
		-- --------------------------------------------------------------------------

		DELETE
			FROM tbPurchaseorderReceptionDetail
			WHERE	comp_id			= @comp_id	AND
					pod_id			= @pod_id	AND
					por_id			= @por_id





		DELETE
			FROM tbItemTransactionsTmp
			WHERE comp_id			= @comp_id	AND
				  pod_id			= @pod_id




		IF NOT EXISTS ( SELECT TOP 1 1

						FROM tbPurchaseorderReceptionDetail tprd		WITH (NOLOCK)

						WHERE	tprd.comp_id	= @comp_id AND
								tprd.por_id		= @por_id
						)

            BEGIN
            	DELETE

            		FROM tbPurchaseorderReceptionHeader

					WHERE	comp_id			= @comp_id	AND
							por_id			= @por_id

            END







END

GO






CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionHeader_getDataById]
(

	@comp_id					INT,
	@por_id						INT,
	@poh_id						INT



)
AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
DECLARE	  	@comp_id				INT,
			@por_id					INT


SELECT		@comp_id						= 1,
			@por_id							= 105
*/
-- ------------------------------------------------------


	SELECT top 1	tprh.por_id,
					tprh.bra_id,
					isnull(tprh.por_isClosed,'False')					[por_isClosed],
					tprh.user_id_closeReception,
					tprh.por_lastClose,
					tprh.por_lastSave,
					tprh.user_id_lastSave,
					isnull(tprh.por_docNumber,'')						[por_docNumber],
					tprh.sd_id,
					isnull(tprh.por_charge2Delivery_Note,'')			[por_charge2Delivery_Note],
					isnull(tprh.por_charge2Delivery,'False')			[por_charge2Delivery],
					isnull(tprh.por_charge2Supplier_Note,'')			[por_charge2Supplier_Note],
					isnull(tprh.por_charge2Supplier,'False')			[por_charge2Supplier],
					tprh.supp_id,
					tprh.ptr_id,
					isnull(tprh.por_liquidated,'false')					[por_liquidated],
					tprh.por_cd,
					tprd.poh_id	,
					tprd.pod_id,
					isnull(tprh.por_isCancelled,'false') [por_isCancelled],
					tprh.ct_transaction



	FROM tbPurchaseorderReceptionHeader			tprh		WITH (NOLOCK)

	LEFT JOIN tbPurchaseorderReceptionDetail	tprd		WITH (NOLOCK)
	ON	tprd.comp_id	= tprh.comp_id
	AND tprd.por_id		= tprh.por_id

	WHERE	tprh.comp_id	 = @comp_id			AND
			tprh.por_id		 = @por_id		--	AND
			--tprd.poh_id		 = @poh_id


END
GO






