CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionHeader_InsertData]
(

		 @comp_id						INT,
		 @bra_id						INT,
		 @por_cd						DATETIME,
		 @supp_id						INT,
		 @por_charge2Supplier			BIT,
		 @por_charge2Supplier_Note		NVARCHAR(4000),
		 @por_charge2Delivery			BIT,
		 @por_charge2Delivery_Note		NVARCHAR(4000),
		 @sd_id							INT,
		 @por_docNumber					NVARCHAR(50),
		 @user_id_lastSave				INT,
		 @por_lastSave					DATETIME,
		 @por_isClosed					BIT,
		 @user_id_closeReception		INT,
		 @por_lastClose					DATETIME,
		 @ptr_id							INT,
		 @return_value					as int	output

)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE	  	 @comp_id						INT,
				 @bra_id						INT,
				 @por_cd						DATETIME,
				 @supp_id						INT,
				 @por_charge2Supplier			BIT,
				 @por_charge2Supplier_Note		NVARCHAR(4000),
				 @por_charge2Delivery			BIT,
				 @por_charge2Delivery_Note		NVARCHAR(4000),
				 @sd_id							INT,
				 @por_docNumber					NVARCHAR(50),
				 @user_id_lastSave				INT,
				 @por_lastSave					DATETIME,
				 @por_isClosed					BIT,
				 @user_id_closeReception		INT,
				 @por_lastClose					DATETIME


	SELECT		 @comp_id						= 1,
				 @bra_id						= 1,
				 @por_cd						= '',
				 @supp_id						= 8145,
				 @por_charge2Supplier			= 1,
				 @por_charge2Supplier_Note		='ASDDAA' ,
				 @por_charge2Delivery			= 1,
				 @por_charge2Delivery_Note		= 'DASASD',
				 @sd_id							= 1,
				 @por_docNumber					= '434334',
				 @user_id_lastSave				= 1,
				 @por_lastSave					= '',
				 @por_isClosed					= 1,
				 @user_id_closeReception		= 3,
				 @por_lastClose					= ''

*/
-- ------------------------------------------------------

Set @return_value			= 0

	IF NOT EXISTS ( SELECT TOP 1  tprh.supp_id
						FROM tbPurchaseorderReceptionHeader				tprh	WITH (NOLOCK)
						WHERE	tprh.comp_id			= @comp_id AND
								tprh.supp_id			= @supp_id AND
								tprh.por_isClosed		= 'False'
					)
		BEGIN

			INSERT INTO tbPurchaseorderReceptionHeader
			(
					 comp_id,
					 bra_id,
					 por_cd,
					 supp_id,
					 por_charge2Supplier,
					 por_charge2Supplier_Note,
					 por_charge2Delivery,
					 por_charge2Delivery_Note,
					 sd_id,
					 por_docNumber,
					 user_id_lastSave,
					 por_lastSave,
					 por_isClosed,
					 user_id_closeReception,
					 por_lastClose,
					 ptr_id
			)
			VALUES
			(
					 @comp_id,
					 @bra_id,
					 @por_cd,
					 @supp_id,
					 @por_charge2Supplier,
					 @por_charge2Supplier_Note,
					 @por_charge2Delivery,
					 @por_charge2Delivery_Note,
					 @sd_id,
					 @por_docNumber,
					 @user_id_lastSave,
					 @por_lastSave,
					 @por_isClosed,
					 @user_id_closeReception,
					 @por_lastClose,
					 @ptr_id
			)



			Set @return_value = @@IDENTITY



		END

		ELSE

		BEGIN

				Set @return_value = (SELECT tprh.por_id
										 FROM tbPurchaseorderReceptionHeader tprh  WITH (NOLOCK)
										 WHERE  tprh.comp_id		= @comp_id AND
												tprh.supp_id		= @supp_id AND
												tprh.por_isClosed	= 'False')
		END





END
GO





