CREATE PROCEDURE [dbo].[spPurchaseOrderReceptionHeader_Receive_UpdateData]
(

		 @comp_id						INT,
		 @supp_id						INT,
		 @por_charge2Supplier			BIT,
		 @por_charge2Supplier_Note		NVARCHAR(4000),
		 @por_charge2Delivery			BIT,
		 @por_charge2Delivery_Note		NVARCHAR(4000),
		 @por_docNumber					NVARCHAR(50),
		 @por_isClosed					BIT,
		 @user_id_closeReception		INT,
		 @por_lastClose					DATETIME,
		 @por_id						INT,
		 @ptr_id						INT,
		 @ct_transaction				INT



)
AS


BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
/*
	DECLARE	  	 @comp_id						INT,
				 @supp_id						INT,
				 @por_lastSave					DATETIME,
				 @por_isClosed					BIT,
				 @user_id_closeReception		INT,
				 @por_lastClose					DATETIME


	SELECT		 @comp_id						= 1,
				 @bra_id						= 1,
				 @por_cd						= '',
				 @supp_id						= 8145,
				 @por_charge2Supplier			= 1,
				 @por_charge2Supplier_Note		='ASDDAA' ,
				 @por_charge2Delivery			= 1,
				 @por_charge2Delivery_Note		= 'DASASD',
				 @sd_id							= 1,
				 @por_docNumber					= '434334',
				 @user_id_lastSave				= 1,
				 @por_lastSave					= '',
				 @por_isClosed					= 1,
				 @user_id_closeReception		= 3,
				 @por_lastClose					= ''

*/
-- ------------------------------------------------------

--	DECLARE @lpor_id INT
--
--
--	Set @lpor_id = (SELECT tprh.por_id
--						 FROM tbPurchaseorderReceptionHeader tprh  WITH (NOLOCK)
--						 WHERE  tprh.comp_id = @comp_id AND
--								tprh.supp_id = @supp_id )




--			UPDATE tbPurchaseorderReceptionHeader
--
--			SET	comp_id						= @comp_id,
--				por_isClosed				= @por_isClosed,
--				user_id_closeReception		= @user_id_closeReception,
--				por_lastClose				= @por_lastClose
--
--			WHERE por_id					= @por_id
--

			UPDATE tbPurchaseorderReceptionHeader			WITH (ROWLOCK)
				SET	comp_id						= @comp_id,
					por_charge2Supplier			= @por_charge2Supplier,
					por_charge2Supplier_Note	= @por_charge2Supplier_Note,
					por_charge2Delivery			= @por_charge2Delivery,
					por_charge2Delivery_Note	= @por_charge2Delivery_Note,
					por_docNumber				= @por_docNumber,
					por_isClosed				= @por_isClosed,
					user_id_closeReception		= @user_id_closeReception,
					por_lastClose				= @por_lastClose,
					ptr_id						= @ptr_id,
					ct_transaction				= @ct_transaction
				WHERE	comp_id = @comp_id AND
						por_id	= @por_id


		-- Saca la seleccion para la proxima recepcion del proveedor.
		UPDATE tbPurchaseOrderHeader				WITH (ROWLOCK)
			SET pho_selectedInRecepcion = 'False'
			WHERE	comp_id = @comp_id AND
					supp_id = @supp_id




END
GO





