CREATE PROCEDURE [dbo].[spPurchaseOrderState_enableData]
(
	@comp_id		INT,
	@bra_id			INT ,
	@poh_id			INT,
	@return_value	INT OUTPUT
)
AS
SET NOCOUNT ON

/*
DECLARE @comp_id INT, @bra_id INT , @poh_id INT, @return_value int
SELECT @comp_id = 1
*/


IF EXISTS(	SELECT DISTINCT 1
				FROM tbItemTransactions tit
				WHERE	tit.comp_id		= @comp_id AND
						tit.bra_id      = @bra_id  AND
						tit.it_poh_id	= @poh_id

			UNION

			SELECT	DISTINCT 1
				FROM	tbItemTransactionsTmp titt
						INNER JOIN tbPurchaseOrderDetail tpod
							ON tpod.comp_id = titt.comp_id
							AND tpod.bra_id = titt.bra_id
							AND tpod.poh_id = titt.poh_id
							AND tpod.pod_id = titt.pod_id

				WHERE	titt.comp_id = @comp_id		AND
						titt.poh_id  = @poh_id		AND
						tpod.pod_isEditing = 'true')

	SET @return_value = 0
ELSE
	SET @return_value = 1
GO






CREATE PROCEDURE [dbo].[spPurchaseOrderState_getDataByFilters]
(
	@comp_id			int,
	@bra_id				int,
	@poh_id				INT,
	@user_id			INT
)
AS

BEGIN

	set nocount on

	-- --------------------------------------------------
	-- Test
	-- --------------------------------------------------
	/*
	declare @comp_id			int,
			@bra_id				int,
			@poh_id				int,
			@user_id			INT


	select	@comp_id			= 1,
			@bra_id				= 1,
			@poh_id				= 508,
			@user_id			= 3

*/
	-- --------------------------------------------------

	SELECT	DISTINCT
			tposc.poc_desc																				[poc_desc],
			tpos.pos_ok																					[pos_ok],
			tpos.poc_id																					[poc_id],
			CASE
				WHEN /*tposr.pocr_canUpdate = 'True' AND */ tucp.comp_id IS NOT NULL THEN	1
				ELSE																		0
			END																							[enable]

		FROM	tbPurchaseOrderState				tpos		WITH (NOLOCK)

		INNER JOIN tbPurchaseOrderStateConcept		tposc		WITH (NOLOCK)
		ON		tposc.poc_id	=	tpos.poc_id	AND
				tposc.comp_id	=	tpos.comp_id

		INNER JOIN tbPurchaseOrderStateRelations	tposr		WITH (NOLOCK)
		ON		tposr.comp_id	=	tpos.comp_id
		AND		tposr.bra_id	=	tpos.bra_id
		AND		tposr.poc_id	=	tpos.poc_id

		left JOIN tbUserCompanyProfile				tucp		WITH (NOLOCK)
		ON		tucp.comp_id	=	tposr.comp_id
		AND		tucp.bra_id		=	tposr.bra_id
		AND		tucp.prof_id	=	tposr.prof_id
		AND		tucp.[user_id]	=	@user_id

		WHERE	tpos.comp_id	=	@comp_id
		AND		tpos.bra_id		=	@bra_id
		AND		tpos.poh_id		=	@poh_id

		ORDER BY tposc.poc_desc



END
GO






