CREATE PROCEDURE [dbo].[spPurchaseOrderTmp_updateDiscounts]
(
	@comp_id	INT,
	@podt_id	INT,
	@discount1	DECIMAL(19,6),
	@discount2	DECIMAL(19,6),
	@discount3	DECIMAL(19,6),
	@discount4	DECIMAL(19,6),
	@surcharge1	DECIMAL(19,6),
	@surcharge2	DECIMAL(19,6),
	@surcharge3	DECIMAL(19,6),
	@surcharge4	DECIMAL(19,6)
)
AS

BEGIN


	SET NOCOUNT ON


	-- ---------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@podt_id	INT,
			@discount1	DECIMAL(19,6),
			@discount2	DECIMAL(19,6),
			@discount3	DECIMAL(19,6),
			@discount4	DECIMAL(19,6)
		SELECT
			@comp_id	= 1,
			@podt_id	= 1530
	*/
	-- ---------------------------------------------------------

	DECLARE
		@price		DECIMAL(19,6),
		@pricedisc	DECIMAL(19,6)

	SET @price = 0

	SELECT @price = tpodt.podt_price
		FROM tbPurchaseOrderDetailTmp tpodt  WITH (NOLOCK)
		WHERE	tpodt.comp_id = @comp_id AND
				tpodt.podt_id = @podt_id

	--Agregar Funcion dbo.fnGetFinalDiscountCoeficient

	SET @pricedisc = @price

	set @pricedisc = @pricedisc * dbo.fnGetFinalDiscountCoeficient( @discount1,  @discount2,  @discount3,  @discount4)
	set @pricedisc = @pricedisc * dbo.fnGetFinalDiscountCoeficient(-@surcharge1,-@surcharge2,-@surcharge3,-@surcharge4)

	UPDATE tbPurchaseOrderDetailTmp
	SET
		--podt_price		= @pricedisc,
		pod_Discount1	= @discount1,
		pod_Discount2	= @discount2,
		pod_Discount3	= @discount3,
		pod_Discount4	= @discount4,
		pod_surcharge1  = @surcharge1,
		pod_surcharge2  = @surcharge2,
		pod_surcharge3  = @surcharge3,
		pod_surcharge4  = @surcharge4,
		pod_priceWithDiscountAndCharges = @pricedisc

	WHERE	comp_id = @comp_id
	AND		podt_id = @podt_id

END
GO



CREATE PROCEDURE spPurchasePlanning_getSuppliers4PO
(
	@SelectionGuid	UNIQUEIDENTIFIER,
	@item_id		INT
)
AS
	SET NOCOUNT ON

		BEGIN

			-- ----------------------------------------
			-- TESTING
			-- ----------------------------------------
			/*
				DECLARE
					@SelectionGuid	UNIQUEIDENTIFIER,
					@item_id		INT
				SELECT
					@SelectionGuid	= '2728114D-5718-4CEC-B541-AB084518F5F6',
					@item_id		= -1
			*/
			-- ----------------------------------------

			SELECT DISTINCT
				ti.supp_id			--SUPP_ID

			FROM tbComplexFilter					tcf

				INNER JOIN tbItem					ti
					ON ti.item_id	= tcf.sl_id

			WHERE	tcf.sl_guid = @SelectionGuid	AND
					(@item_id	= -1 OR tcf.sl_id = @item_id)	AND
					ti.supp_id IS NOT NULL

			ORDER BY ti.supp_id

		END
GO




CREATE PROCEDURE [dbo].[spPurchasePlanning_Update_QtySuggested]
(
	@comp_id			INT,
	@Guid				UNIQUEIDENTIFIER,
	@SelectionGuid		UNIQUEIDENTIFIER,
	@stor_id			INT,
	@brag_id			INT,
	@user_id			INT,
	@field4Update		INT


)
AS


SET NOCOUNT ON

BEGIN


	----------------------------------------------------------------------------------------
	-- Testing
	----------------------------------------------------------------------------------------
	/*
	DECLARE @comp_id			INT,
			@Guid				UNIQUEIDENTIFIER,
			@SelectionGuid		UNIQUEIDENTIFIER,
			@stor_id			INT,
			@brag_id		INT,
			@user_id		INT


	SELECT  @comp_id			= 1,
			@Guid				= 'a112331f-a764-4fe7-a9ed-cf03eddfe60a',
			@SelectionGuid		= '2c854b2f-280b-4e22-b9ad-2d5457cb67ae',
			@stor_id			= 3,
			@brag_id			= 4,
			@user_id			= 3

	*/
	----------------------------------------------------------------------------------------




	DECLARE @tblComplexFilter_AllItems TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_AllItems
			SELECT
				tcf.sl_id
				FROM tbComplexFilter tcf			WITH (NOLOCK)
				WHERE tcf.sl_guid = @SelectionGuid

		DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
			INSERT INTO @tblBranchs
				SELECT DISTINCT	bra_id
					FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
					WHERE	tbgd.comp_id = @comp_id		AND
							tbgd.brag_id = @brag_id




		-- Borro todas las sucursales a las que no pueda acceder
		DELETE	FROM @tblBranchs
				FROM @tblBranchs												tbl
			LEFT JOIN tbUsers4BranchFilter									vubf	WITH (NOLOCK)
				ON	vubf.comp_id						= @comp_id		AND
					vubf.bra_id							= tbl.bra_id	AND
					vubf.[user_id]						= @user_id
			WHERE vubf.comp_id IS NULL



			--*****************************************************************************************************************************
			-- CREAMOS UNA VARIABLE DE TABLE EN DONDE VAMOS A IR VOLCANDO LOS TOTALES POR ARTICULO
			-- UNA SUMATORIA POR VEZ, PARA EVITAR QUE SE HAGA UN PROCESO ENGORROSO AL TENER TANTOS LEFT JOIN
			--*****************************************************************************************************************************
			DECLARE @tbItemTotals TABLE (
											comp_id					INT,
											item_id					INT,
											Stock					INT,
											Articulos_OC			DECIMAL(19,2),  -- ARTÍCULOS + ORDENES DE COMPRAS
											Articulos_Pedidos		DECIMAL(19,2),	-- ARTÍCULOS + PEDIDOS
											StockOptimo				DECIMAL(18,4),
											item_upb				DECIMAL(18,4)
										)
			--SE AGREGARON LAS ÚLTIMAS 3 COLUMNAS STL

			--*****************************************************************************************************************************


			--*****************************************************************************************************************************
			-- ARTICULOS + STOCK
			--*****************************************************************************************************************************
			INSERT INTO @tbItemTotals
			(
				comp_id,
				item_id,
				Stock,
				Articulos_OC,
				Articulos_Pedidos,
				StockOptimo,
				item_upb
			)
			SELECT
				ti.comp_id,
				ti.item_id,
				dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id,ti.item_id),
				0,
				0,
				ti.item_cantOpt,
				ti.item_upb
			FROM tbItem									ti			WITH (NOLOCK)
				INNER JOIN @tblComplexFilter_AllItems	tbCFAI
					ON tbCFAI.item_id	= ti.item_id
			WHERE	ti.comp_id			= @comp_id


			--*****************************************************************************************************************************


			--*****************************************************************************************************************************
			--ARTICULOS + ORDENES DE COMPRA
			--*****************************************************************************************************************************

			;WITH Items_TotalSales (ItemId, Articulos_OC)
			AS
			(
				SELECT
					ti.item_id															[ItemId],
					SUM(CASE
							WHEN tpoh.comp_id IS NULL THEN 0
							ELSE tpod.pod_qty
					    END)															[Disponible]
					FROM @tbItemTotals										ti
						LEFT JOIN tbPurchaseOrderDetail						tpod	WITH (NOLOCK)
						ON	tpod.comp_id			= ti.comp_id			AND
							tpod.item_id			= ti.item_id			AND
							tpod.pod_isProcessed	= 'False'
						LEFT JOIN tbPurchaseOrderHeader						tpoh	WITH (NOLOCK)
							ON	tpoh.comp_id		= tpod.comp_id			AND
								tpoh.bra_id			= tpod.bra_id			AND
								tpoh.poh_id			= tpod.poh_id			AND
								ISNULL(tpoh.poh_isEditing,'False')= 'False'	AND
								ISNULL(tpoh.poh_quotation,'False')= 'False'
						INNER JOIN @tblBranchs								tbBGC
							ON tbBGC.bra_id			= tpoh.bra_id
						INNER JOIN tbUsers4BranchFilter						vubf	WITH (NOLOCK)
							ON	vubf.comp_id		= tpod.comp_id			AND
								vubf.bra_id			= tpod.bra_id			AND
								vubf.[user_id]		= @user_id

					WHERE	tpoh.comp_id							= @comp_id	AND
							ISNULL(tpod.pod_isProcessed,'False')	= 'False'	AND
							ISNULL(tpod.pod_isEditing,	'False')	= 'False'
					GROUP BY ti.item_id
			)
			UPDATE @tbItemTotals
			SET
				Articulos_OC = ITS.Articulos_OC
				FROM Items_TotalSales ITS
				WHERE ITS.ItemId = item_id

			--*****************************************************************************************************************************

			--*****************************************************************************************************************************
			--	ARTICULOS + PEDIDOS
			--*****************************************************************************************************************************

			;WITH Items_TotalDisponible (ItemId, Articulos_Pedidos)
			AS
			(
				SELECT
					ti.item_id															[ItemId],
					SUM(CASE
							WHEN	tdf.df_disable4PurchasePlanning = 'True'		THEN 0
							WHEN	tsoh.comp_id IS NULL THEN 0
							WHEN	tdf.sd_id = 1	OR
									tdf.sd_id = 2	OR
									tdf.sd_id = 21	OR
									tdf.sd_id = 31									THEN tsod.sod_qty
							WHEN	tdf.sd_id = 3	OR
									tdf.sd_id = 12  OR
									tdf.sd_id = 23	OR
									tdf.sd_id = 33									THEN tsod.sod_qty  * -1
							ELSE						  0
							--WHEN tsoh.comp_id IS NULL THEN 0
							--ELSE tsod.sod_qty
						END)															[Sales]
					FROM @tbItemTotals													ti
						LEFT JOIN tbSaleOrderDetail										tsod		WITH (NOLOCK)
							ON	tsod.comp_id			= ti.comp_id					AND
								tsod.item_id			= ti.item_id
						LEFT JOIN tbSaleOrderHeader										tsoh		WITH (NOLOCK)
							ON	tsoh.comp_id			= tsod.comp_id					AND
								tsoh.bra_id				= tsod.bra_id					AND
								tsoh.soh_id				= tsod.soh_id
						INNER JOIN @tblBranchs											tbBGC
							ON tbBGC.bra_id				= tsoh.bra_id
						LEFT JOIN tbDocumentsFile										tdf			WITH (NOLOCK)
							ON	tdf.comp_id = tsoh.comp_id AND
								tdf.df_id	= tsoh.df_id
					WHERE	tsod.comp_id				= @comp_id
					GROUP BY ti.item_id
			)
			UPDATE @tbItemTotals
			SET
				Articulos_Pedidos = ITD.Articulos_Pedidos
				FROM Items_TotalDisponible ITD				WITH (NOLOCK)
				WHERE ITD.ItemId = item_id

			--*****************************************************************************************************************************




			--------------------------------------------------------------------------------------------------------------
			-- test
			-- ejemplo de como se calcula la cantidad sugerida para que sea multiplo del upb
			-- test
			--------------------------------------------------------------------------------------------------------------
			/*
			DECLARE @Residuo decimal(8,2)
			DECLARE @ValASumar decimal(8,2)
			DECLARE @cantidadsugerida2 integer
			DECLARE	@UPB2 integer

			select 	@cantidadsugerida2 = -73386.967742,
					@UPB2 =20

			set @Residuo=@cantidadsugerida2 % dbo.fnNoZDiv(@UPB2)
			--SELECT @Residuo
			IF @Residuo=0
			select @cantidadsugerida2
			ELSE
			select @cantidadsugerida2+(@UPB2-@Residuo)
			*/
			--------------------------------------------------------------------------------------------------------------



			--UPDATE  tbComplexFilter
			--SET	sl_tmpData  =  tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)



    		IF @field4Update = 1
				BEGIN
					UPDATE  tbComplexFilter
					SET	sl_tmpData  =

									dbo.fnGetPurchaseLote2Buy(tit.comp_id,tit.item_id,
																CASE (tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb) WHEN 0 THEN
																	 tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)
																ELSE
																	(tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb)))
																END
															)

					FROM tbComplexFilter			tcf		WITH (NOLOCK)
					INNER JOIN @tbItemTotals		tit
					ON tit.item_id	= tcf.sl_id

					WHERE	tcf.sl_guid			= @SelectionGuid AND
							tit.StockOptimo - ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos) > 0 AND
							(tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb))) > 0

				END
			ELSE
				BEGIN
					UPDATE  tbComplexFilter
					SET	sl_tmpData  =
									dbo.fnGetPurchaseLote2Buy(tit.comp_id,tit.item_id,
																CASE (tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb) WHEN 0 THEN
																	 tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)
																ELSE
																	(tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb)))

																END
															 )

					FROM tbComplexFilter			tcf		WITH (NOLOCK)
					INNER JOIN @tbItemTotals		tit
					ON tit.item_id	= tcf.sl_id

					WHERE	tcf.sl_guid			= @SelectionGuid AND
							tit.StockOptimo - ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos) > 0 AND
							(tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb))) > 0

				END





			--SELECT tit.StockOptimo - ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos) [catidad sugerida],
			--tit.item_upb  [upb],
			--	(tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockOptimo - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb)))  [calculo final upbcatidad sugerida],
			--	*
			--	 FROM tbComplexFilter tcf
			--	INNER JOIN @tbItemTotals		tit
			--ON tit.item_id	= tcf.sl_id



END












	--SELECT * FROM @tbItemTotals

	--SELECT

	--			dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id,ti.item_id)			[Stock],
