-- (00667) Planificación de Compras
-- Requerimiento de Claudia Muebles

-- DDL: Stock MÍNIMO - (Stock DISPONIBLE - Pedidos Pendientes a Vincular + Compras Pendientes de Vincular)
--[12:05, 20/9/2021] Saracco Martin: HOla, lo de Claudia, de PLanificacion.   es
--	SI el Stock Minimo >	(Stock DISPONIBLE - Pedidos Pendientes a Vincular + Compras Pendientes de Vincular  )  para que se incluyan , o sea, NO ALCANZAN para llegaR AL minimo!!!
--[12:06, 20/9/2021] Saracco Martin: y se deben pedir: Stock MINIMO - (Stock DISPONIBLE - Pedidos Pendientes a Vincular + Compras Pendientes de Vincular)


CREATE PROCEDURE [dbo].[spPurchasePlanning_Update_QtySuggested_cantMinStockAvailablePurchaseOrderRelation]
(
	@comp_id			INT,
	@Guid				UNIQUEIDENTIFIER,
	@SelectionGuid		UNIQUEIDENTIFIER,
	@stor_id			INT,
	@brag_id			INT,
	@user_id			INT,
	@field4Update		INT


)
AS


SET NOCOUNT ON

BEGIN


	----------------------------------------------------------------------------------------
	-- Testing
	----------------------------------------------------------------------------------------
	/*
	DECLARE @comp_id			INT,
			@Guid				UNIQUEIDENTIFIER,
			@SelectionGuid		UNIQUEIDENTIFIER,
			@stor_id			INT,
			@brag_id		INT,
			@user_id		INT


	SELECT  @comp_id			= 1,
			@Guid				= 'a112331f-a764-4fe7-a9ed-cf03eddfe60a',
			@SelectionGuid		= '2c854b2f-280b-4e22-b9ad-2d5457cb67ae',
			@stor_id			= 3,
			@brag_id			= 4,
			@user_id			= 3

	*/
	----------------------------------------------------------------------------------------




	DECLARE @tblComplexFilter_AllItems TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_AllItems
			SELECT
				tcf.sl_id
				FROM tbComplexFilter tcf			WITH (NOLOCK)
				WHERE tcf.sl_guid = @SelectionGuid

		DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
			INSERT INTO @tblBranchs
				SELECT DISTINCT	bra_id
					FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
					WHERE	tbgd.comp_id = @comp_id		AND
							tbgd.brag_id = @brag_id




		-- Borro todas las sucursales a las que no pueda acceder
		DELETE	FROM @tblBranchs
				FROM @tblBranchs												tbl
			LEFT JOIN tbUsers4BranchFilter									vubf	WITH (NOLOCK)
				ON	vubf.comp_id						= @comp_id		AND
					vubf.bra_id							= tbl.bra_id	AND
					vubf.[user_id]						= @user_id
			WHERE vubf.comp_id IS NULL



			--*****************************************************************************************************************************
			-- CREAMOS UNA VARIABLE DE TABLE EN DONDE VAMOS A IR VOLCANDO LOS TOTALES POR ARTICULO
			-- UNA SUMATORIA POR VEZ, PARA EVITAR QUE SE HAGA UN PROCESO ENGORROSO AL TENER TANTOS LEFT JOIN
			--*****************************************************************************************************************************
			DECLARE @tbItemTotals TABLE (
											comp_id					INT,
											item_id					INT,
											Stock					INT,
											Articulos_OC			DECIMAL(19,2),  -- ARTÍCULOS + ORDENES DE COMPRAS
											Articulos_Pedidos		DECIMAL(19,2),	-- ARTÍCULOS + PEDIDOS
											StockMin				DECIMAL(18,4),
											item_upb				DECIMAL(18,4)
										)
			--SE AGREGARON LAS ÚLTIMAS 3 COLUMNAS STL

			--*****************************************************************************************************************************


			--*****************************************************************************************************************************
			-- ARTICULOS + STOCK
			--*****************************************************************************************************************************
			INSERT INTO @tbItemTotals
			(
				comp_id,
				item_id,
				Stock,
				Articulos_OC,
				Articulos_Pedidos,
				StockMin,
				item_upb
			)
			SELECT
				ti.comp_id,
				ti.item_id,
				dbo.fnGetAStock(@comp_id, @stor_id, ti.item_id,999999999), --Stock Disponible
				0,
				0,
				ti.item_cantMin,
				ti.item_upb
				FROM tbItem									ti			WITH (NOLOCK)
					INNER JOIN @tblComplexFilter_AllItems	tbCFAI
						ON tbCFAI.item_id	= ti.item_id
				WHERE	ti.comp_id			= @comp_id AND
						ti.item_disabled	= 'False'


			--*****************************************************************************************************************************


			--*****************************************************************************************************************************
			--ARTICULOS + ORDENES DE COMPRA
			--*****************************************************************************************************************************

			;WITH Items_TotalSales (ItemId, Articulos_OC)
			AS
			(
				SELECT
					ti.item_id															[ItemId],
					SUM(tpod.pod_qty)-SUM(ISNULL(tsod.sod_qty,0))						[Disponible]
					FROM @tbItemTotals										ti
					INNER JOIN tbPurchaseOrderDetail						tpod	WITH (NOLOCK)
						ON	tpod.comp_id			= ti.comp_id			AND
							tpod.item_id			= ti.item_id
					INNER JOIN tbPurchaseOrderHeader						tpoh	WITH (NOLOCK)
						ON	tpoh.comp_id		= tpod.comp_id			AND
							tpoh.bra_id			= tpod.bra_id			AND
							tpoh.poh_id			= tpod.poh_id
					INNER JOIN @tblBranchs								tbBGC
						ON tbBGC.bra_id			= tpoh.bra_id

					-- Para que perder mas tiempo si ya lo borraste mas arriba ..... en @tblBranchs
					--INNER JOIN tbUsers4BranchFilter						vubf		WITH (NOLOCK)
					--	ON	vubf.comp_id		= tpod.comp_id			AND
					--		vubf.bra_id			= tpod.bra_id			AND
					--		vubf.[user_id]		= @user_id
					LEFT JOIN tbSaleOrderHeader_PurchaseOrderRelation uu	     	WITH (NOLOCK)
						 ON uu.comp_id			= tpod.comp_id			AND
							uu.po_bra_id		= tpod.bra_id			AND
							uu.po_poh_id		= tpod.poh_id			AND
							uu.po_pod_id		= tpod.pod_id
					LEFT JOIN tbSaleOrderDetail					AS tsod			WITH (NOLOCK)
						ON	tsod.comp_id		= uu.comp_id			AND
							tsod.bra_id			= uu.so_bra_id			AND
							tsod.soh_id			= uu.so_soh_id			AND
							tsod.sod_id			= uu.so_sod_id
					WHERE	tpoh.comp_id							= @comp_id	AND
							ISNULL(tpod.pod_isProcessed,'False')	= 'False'	AND
							ISNULL(tpod.pod_isEditing,	'False')	= 'False'	AND
							tpod.pod_isProcessed					= 'False'	AND
							ISNULL(tpoh.poh_isEditing,'False')		= 'False'	AND
							ISNULL(tpoh.poh_quotation,'False')		= 'False'

					GROUP BY ti.item_id
			)
			UPDATE @tbItemTotals
				SET
					Articulos_OC = ITS.Articulos_OC
					FROM Items_TotalSales ITS
					WHERE ITS.ItemId = item_id

			--*****************************************************************************************************************************

			--*****************************************************************************************************************************
			--	ARTICULOS + PEDIDOS
			--*****************************************************************************************************************************

			;WITH Items_TotalDisponible (ItemId, Articulos_Pedidos)
			AS
			(
				SELECT
					ti.item_id															[ItemId],
					SUM(CASE
							WHEN	tdf.df_disable4PurchasePlanning = 'True'		THEN 0
							WHEN	tsoh.comp_id IS NULL THEN 0
							WHEN	tdf.sd_id = 1	OR
									tdf.sd_id = 2	OR
									tdf.sd_id = 21	OR
									tdf.sd_id = 31									THEN tsod.sod_qty
							WHEN	tdf.sd_id = 3	OR
									tdf.sd_id = 12  OR
									tdf.sd_id = 23	OR
									tdf.sd_id = 33									THEN tsod.sod_qty  * -1
							ELSE						  0
							--WHEN tsoh.comp_id IS NULL THEN 0
							--ELSE tsod.sod_qty
						END)															[Sales]
					FROM @tbItemTotals													ti
						LEFT JOIN tbSaleOrderDetail										tsod		WITH (NOLOCK)
							ON	tsod.comp_id			= ti.comp_id					AND
								tsod.item_id			= ti.item_id
						LEFT JOIN tbSaleOrderHeader										tsoh		WITH (NOLOCK)
							ON	tsoh.comp_id			= tsod.comp_id					AND
								tsoh.bra_id				= tsod.bra_id					AND
								tsoh.soh_id				= tsod.soh_id
						INNER JOIN @tblBranchs											tbBGC
							ON tbBGC.bra_id				= tsoh.bra_id
						INNER JOIN tbDocumentsFile										tdf			WITH (NOLOCK)
							ON	tdf.comp_id = tsoh.comp_id AND
								tdf.df_id	= tsoh.df_id
					WHERE	tsod.comp_id					= @comp_id	AND
							tsod.sod_pending4pod_IdRelation = 'True'
					GROUP BY ti.item_id
			)
			UPDATE @tbItemTotals
			SET
				Articulos_Pedidos = ITD.Articulos_Pedidos
				FROM Items_TotalDisponible ITD				WITH (NOLOCK)
				WHERE ITD.ItemId = item_id

			--*****************************************************************************************************************************




			-- --------------------------------------------------------------------------------------
			-- Sabiendo que:	tit.Stock: Stock DISPONIBLE SIN pedidos pendientes de relacionar.
			--					tit.Articulos_OC: Ordenes de compra NO relacionadas a pedidos
			--					tit.Articulos_Pedidos: Pedidos PENDIENTES a relacionar a Ordenes de compra.
			-- --------------------------------------------------------------------------------------


    		IF @field4Update = 1
				BEGIN
					UPDATE  tbComplexFilter
						SET	sl_tmpData  =
									dbo.fnGetPurchaseLote2Buy(tit.comp_id,tit.item_id,
																tit.StockMin - ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)		-- Pedir lo NECESARIO para llegar a tener el Stock MINIMO!!!!!!!
															)
							-- Que es esto ??????
							--CASE (tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb) WHEN 0 THEN
							--	 tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)
							--ELSE
							--	(tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb)))
							--END

						FROM tbComplexFilter			tcf		WITH (NOLOCK)
						INNER JOIN @tbItemTotals		tit
							ON tit.item_id	= tcf.sl_id

						WHERE	-- Solo si  (Stock DISPONIBLE - Pedidos Pendientes a Vincular + Compras Pendientes de Vincular  ) nO LLEGA AL NIVEL DEL sTOCK mínimo
								tcf.sl_guid			= @SelectionGuid AND
								tit.StockMin > ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)  --AND
								--  ???????   (tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb))) > 0

				END
			ELSE
				BEGIN
					UPDATE  tbComplexFilter
						SET	sl_tmpData2  =
									dbo.fnGetPurchaseLote2Buy(tit.comp_id,tit.item_id,
																tit.StockMin - ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)		-- Pedir lo NECESARIO para llegar a tener el Stock MINIMO!!!!!!!
																)
							-- Que es esto ??????
							--CASE (tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb) WHEN 0 THEN
							--	 tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)
							--ELSE
							--	(tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb)))
							--END

						FROM tbComplexFilter			tcf		WITH (NOLOCK)
						INNER JOIN @tbItemTotals		tit
							ON tit.item_id	= tcf.sl_id

						WHERE	-- Solo si  (Stock DISPONIBLE - Pedidos Pendientes a Vincular + Compras Pendientes de Vincular  ) nO LLEGA AL NIVEL DEL sTOCK mínimo
								tcf.sl_guid			= @SelectionGuid AND
								tit.StockMin > ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)  --AND
								--  ???????   (tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb))) > 0

				END






END


GO



-- MOS 09-2022: Santitades Pendientes de relacionar a OC


CREATE PROCEDURE [dbo].[spPurchasePlanning_Update_QtySuggested_cantOptSaleOrderPendingOfRelation2PurchaseOrder]
(
	@comp_id			INT,
	@Guid				UNIQUEIDENTIFIER,
	@SelectionGuid		UNIQUEIDENTIFIER,
	@stor_id			INT,
	@brag_id			INT,
	@user_id			INT,
	@field4Update		INT


)
AS


SET NOCOUNT ON

BEGIN


	----------------------------------------------------------------------------------------
	-- Testing
	----------------------------------------------------------------------------------------
	/*
	DECLARE @comp_id			INT,
			@Guid				UNIQUEIDENTIFIER,
			@SelectionGuid		UNIQUEIDENTIFIER,
			@stor_id			INT,
			@brag_id			INT,
			@user_id			INT,
			@field4Update		INT = 1


	SELECT  @comp_id			= 1,
			@Guid				= '56628e31-b9a6-4419-ae6c-31aa268ba5b0',
			@SelectionGuid		= 'b9b294b6-9f1c-4e2d-b7ff-3c11e307d6c5',
			@stor_id			= 3,
			@brag_id			= 4,
			@user_id			= 3

	*/
	----------------------------------------------------------------------------------------




	DECLARE @tblComplexFilter_AllItems TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_AllItems
			SELECT
				tcf.sl_id
				FROM tbComplexFilter tcf			WITH (NOLOCK)
				WHERE tcf.sl_guid = @SelectionGuid

		DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
			INSERT INTO @tblBranchs
				SELECT DISTINCT	bra_id
					FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
					WHERE	tbgd.comp_id = @comp_id		AND
							tbgd.brag_id = @brag_id




		-- Borro todas las sucursales a las que no pueda acceder
		DELETE	FROM @tblBranchs
				FROM @tblBranchs												tbl
			LEFT JOIN tbUsers4BranchFilter									vubf	WITH (NOLOCK)
				ON	vubf.comp_id						= @comp_id		AND
					vubf.bra_id							= tbl.bra_id	AND
					vubf.[user_id]						= @user_id
			WHERE vubf.comp_id IS NULL



			--*****************************************************************************************************************************
			-- CREAMOS UNA VARIABLE DE TABLE EN DONDE VAMOS A IR VOLCANDO LOS TOTALES POR ARTICULO
			-- UNA SUMATORIA POR VEZ, PARA EVITAR QUE SE HAGA UN PROCESO ENGORROSO AL TENER TANTOS LEFT JOIN
			--*****************************************************************************************************************************
			DECLARE @tbItemTotals TABLE (
											comp_id					INT,
											item_id					INT,
											Stock					INT,
											Articulos_OC			DECIMAL(19,2),  -- ARTÍCULOS + ORDENES DE COMPRAS
											Articulos_Pedidos		DECIMAL(19,2),	-- ARTÍCULOS + PEDIDOS
											StockMin				DECIMAL(18,4),
											item_upb				DECIMAL(18,4)
										)
			--SE AGREGARON LAS ÚLTIMAS 3 COLUMNAS STL

			--*****************************************************************************************************************************


			--*****************************************************************************************************************************
			-- ARTICULOS + STOCK
			--*****************************************************************************************************************************
			INSERT INTO @tbItemTotals
			(
				comp_id,
				item_id,
				Stock,
				Articulos_OC,
				Articulos_Pedidos,
				StockMin,
				item_upb
			)
			SELECT
				ti.comp_id,
				ti.item_id,
				0,--dbo.fnGetAStock(@comp_id, @stor_id, ti.item_id,999999999), --Stock Disponible
				0,
				0,
				ti.item_cantOpt,
				ti.item_upb
				FROM tbItem									ti			WITH (NOLOCK)
				INNER JOIN @tblComplexFilter_AllItems	tbCFAI
					ON tbCFAI.item_id	= ti.item_id
				WHERE	ti.comp_id			= @comp_id AND
						ti.item_disabled	= 'False'


			--*****************************************************************************************************************************


			--*****************************************************************************************************************************
			--ARTICULOS pendientes de relacionar a OC
			--*****************************************************************************************************************************

			;WITH Items_TotalSales (ItemId, Articulos_OC)
			AS
			(
				SELECT
					ti.item_id															[ItemId],
					SUM(ISNULL(tsod.sod_qty,0))											[Disponible]
					FROM @tbItemTotals										ti
					INNER JOIN tbSaleOrderDetail					AS tsod			WITH (NOLOCK)
						ON	tsod.comp_id		= @comp_id	AND
							tsod.item_id		= ti.item_id
					INNER JOIN @tblBranchs								tbBGC
						ON tbBGC.bra_id			= tsod.bra_id
					WHERE	tsod.comp_id							= @comp_id	AND
							tsod.sod_pending4pod_IdRelation			= 'True'
					GROUP BY ti.item_id
			)
			UPDATE @tbItemTotals
				SET	Articulos_OC = ITS.Articulos_OC
				FROM Items_TotalSales ITS
				WHERE ITS.ItemId = item_id

			--*****************************************************************************************************************************




    		IF @field4Update = 1
				BEGIN
					UPDATE  tbComplexFilter
						SET	sl_tmpData  = tit.Articulos_OC
						FROM tbComplexFilter			tcf		WITH (NOLOCK)
						INNER JOIN @tbItemTotals		tit
							ON tit.item_id	= tcf.sl_id
						WHERE	tcf.sl_guid			= @SelectionGuid AND
								tit.Articulos_OC    > 0

				END
			ELSE
				BEGIN
					UPDATE  tbComplexFilter
						SET	sl_tmpData2  = tit.Articulos_OC
						FROM tbComplexFilter			tcf		WITH (NOLOCK)
						INNER JOIN @tbItemTotals		tit
							ON tit.item_id	= tcf.sl_id
						WHERE	tcf.sl_guid			= @SelectionGuid AND
								tit.Articulos_OC    > 0
				END


END


GO



-- (00667) Planificación de Compras
-- Requerimiento de Claudia Muebles

-- DDL: Stock MÍNIMO - (Stock DISPONIBLE - Pedidos Pendientes a Vincular + Compras Pendientes de Vincular)
--[12:05, 20/9/2021] Saracco Martin: HOla, lo de Claudia, de PLanificacion.   es
--	SI el Stock OPTIMO >	(Stock DISPONIBLE - Pedidos Pendientes a Vincular + Compras Pendientes de Vincular  )  para que se incluyan , o sea, NO ALCANZAN para llegaR AL OPTIMO!!!
--[12:06, 20/9/2021] Saracco Martin: y se deben pedir: Stock OPTIMO - (Stock DISPONIBLE - Pedidos Pendientes a Vincular + Compras Pendientes de Vincular)


CREATE PROCEDURE [dbo].[spPurchasePlanning_Update_QtySuggested_cantOptStockAvailablePurchaseOrderRelation]
(
	@comp_id			INT,
	@Guid				UNIQUEIDENTIFIER,
	@SelectionGuid		UNIQUEIDENTIFIER,
	@stor_id			INT,
	@brag_id			INT,
	@user_id			INT,
	@field4Update		INT


)
AS


SET NOCOUNT ON

BEGIN


	----------------------------------------------------------------------------------------
	-- Testing
	----------------------------------------------------------------------------------------
	/*
	DECLARE @comp_id			INT,
			@Guid				UNIQUEIDENTIFIER,
			@SelectionGuid		UNIQUEIDENTIFIER,
			@stor_id			INT,
			@brag_id		INT,
			@user_id		INT


	SELECT  @comp_id			= 1,
			@Guid				= 'a112331f-a764-4fe7-a9ed-cf03eddfe60a',
			@SelectionGuid		= '2c854b2f-280b-4e22-b9ad-2d5457cb67ae',
			@stor_id			= 3,
			@brag_id			= 4,
			@user_id			= 3

	*/
	----------------------------------------------------------------------------------------




	DECLARE @tblComplexFilter_AllItems TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_AllItems
			SELECT
				tcf.sl_id
				FROM tbComplexFilter tcf			WITH (NOLOCK)
				WHERE tcf.sl_guid = @SelectionGuid

		DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
			INSERT INTO @tblBranchs
				SELECT DISTINCT	bra_id
					FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
					WHERE	tbgd.comp_id = @comp_id		AND
							tbgd.brag_id = @brag_id




		-- Borro todas las sucursales a las que no pueda acceder
		DELETE	FROM @tblBranchs
				FROM @tblBranchs												tbl
			LEFT JOIN tbUsers4BranchFilter									vubf	WITH (NOLOCK)
				ON	vubf.comp_id						= @comp_id		AND
					vubf.bra_id							= tbl.bra_id	AND
					vubf.[user_id]						= @user_id
			WHERE vubf.comp_id IS NULL



			--*****************************************************************************************************************************
			-- CREAMOS UNA VARIABLE DE TABLE EN DONDE VAMOS A IR VOLCANDO LOS TOTALES POR ARTICULO
			-- UNA SUMATORIA POR VEZ, PARA EVITAR QUE SE HAGA UN PROCESO ENGORROSO AL TENER TANTOS LEFT JOIN
			--*****************************************************************************************************************************
			DECLARE @tbItemTotals TABLE (
											comp_id					INT,
											item_id					INT,
											Stock					INT,
											Articulos_OC			DECIMAL(19,2),  -- ARTÍCULOS + ORDENES DE COMPRAS
											Articulos_Pedidos		DECIMAL(19,2),	-- ARTÍCULOS + PEDIDOS
											StockMin				DECIMAL(18,4),
											item_upb				DECIMAL(18,4)
										)
			--SE AGREGARON LAS ÚLTIMAS 3 COLUMNAS STL

			--*****************************************************************************************************************************


			--*****************************************************************************************************************************
			-- ARTICULOS + STOCK
			--*****************************************************************************************************************************
			INSERT INTO @tbItemTotals
			(
				comp_id,
				item_id,
				Stock,
				Articulos_OC,
				Articulos_Pedidos,
				StockMin,
				item_upb
			)
			SELECT
				ti.comp_id,
				ti.item_id,
				dbo.fnGetAStock(@comp_id, @stor_id, ti.item_id,999999999), --Stock Disponible
				0,
				0,
				ti.item_cantOpt,
				ti.item_upb
				FROM tbItem									ti			WITH (NOLOCK)
					INNER JOIN @tblComplexFilter_AllItems	tbCFAI
						ON tbCFAI.item_id	= ti.item_id
				WHERE	ti.comp_id			= @comp_id AND
						ti.item_disabled	= 'False'


			--*****************************************************************************************************************************


			--*****************************************************************************************************************************
			--ARTICULOS + ORDENES DE COMPRA
			--*****************************************************************************************************************************

			;WITH Items_TotalSales (ItemId, Articulos_OC)
			AS
			(
				SELECT
					ti.item_id															[ItemId],
					SUM(tpod.pod_qty)-SUM(ISNULL(tsod.sod_qty,0))						[Disponible]
					FROM @tbItemTotals										ti
					INNER JOIN tbPurchaseOrderDetail						tpod	WITH (NOLOCK)
						ON	tpod.comp_id			= ti.comp_id			AND
							tpod.item_id			= ti.item_id
					INNER JOIN tbPurchaseOrderHeader						tpoh	WITH (NOLOCK)
						ON	tpoh.comp_id		= tpod.comp_id			AND
							tpoh.bra_id			= tpod.bra_id			AND
							tpoh.poh_id			= tpod.poh_id
					INNER JOIN @tblBranchs								tbBGC
						ON tbBGC.bra_id			= tpoh.bra_id

					-- Para que perder mas tiempo si ya lo borraste mas arriba ..... en @tblBranchs
					--INNER JOIN tbUsers4BranchFilter						vubf		WITH (NOLOCK)
					--	ON	vubf.comp_id		= tpod.comp_id			AND
					--		vubf.bra_id			= tpod.bra_id			AND
					--		vubf.[user_id]		= @user_id
					LEFT JOIN tbSaleOrderHeader_PurchaseOrderRelation uu	     	WITH (NOLOCK)
						 ON uu.comp_id			= tpod.comp_id			AND
							uu.po_bra_id		= tpod.bra_id			AND
							uu.po_poh_id		= tpod.poh_id			AND
							uu.po_pod_id		= tpod.pod_id
					LEFT JOIN tbSaleOrderDetail					AS tsod			WITH (NOLOCK)
						ON	tsod.comp_id		= uu.comp_id			AND
							tsod.bra_id			= uu.so_bra_id			AND
							tsod.soh_id			= uu.so_soh_id			AND
							tsod.sod_id			= uu.so_sod_id
					WHERE	tpoh.comp_id							= @comp_id	AND
							ISNULL(tpod.pod_isProcessed,'False')	= 'False'	AND
							ISNULL(tpod.pod_isEditing,	'False')	= 'False'	AND
							tpod.pod_isProcessed					= 'False'	AND
							ISNULL(tpoh.poh_isEditing,'False')		= 'False'	AND
							ISNULL(tpoh.poh_quotation,'False')		= 'False'

					GROUP BY ti.item_id
			)
			UPDATE @tbItemTotals
				SET
					Articulos_OC = ITS.Articulos_OC
					FROM Items_TotalSales ITS
					WHERE ITS.ItemId = item_id

			--*****************************************************************************************************************************

			--*****************************************************************************************************************************
			--	ARTICULOS + PEDIDOS
			--*****************************************************************************************************************************

			;WITH Items_TotalDisponible (ItemId, Articulos_Pedidos)
			AS
			(
				SELECT
					ti.item_id															[ItemId],
					SUM(CASE
							WHEN	tdf.df_disable4PurchasePlanning = 'True'		THEN 0
							WHEN	tsoh.comp_id IS NULL THEN 0
							WHEN	tdf.sd_id = 1	OR
									tdf.sd_id = 2	OR
									tdf.sd_id = 21	OR
									tdf.sd_id = 31									THEN tsod.sod_qty
							WHEN	tdf.sd_id = 3	OR
									tdf.sd_id = 12  OR
									tdf.sd_id = 23	OR
									tdf.sd_id = 33									THEN tsod.sod_qty  * -1
							ELSE						  0
							--WHEN tsoh.comp_id IS NULL THEN 0
							--ELSE tsod.sod_qty
						END)															[Sales]
					FROM @tbItemTotals													ti
						LEFT JOIN tbSaleOrderDetail										tsod		WITH (NOLOCK)
							ON	tsod.comp_id			= ti.comp_id					AND
								tsod.item_id			= ti.item_id
						LEFT JOIN tbSaleOrderHeader										tsoh		WITH (NOLOCK)
							ON	tsoh.comp_id			= tsod.comp_id					AND
								tsoh.bra_id				= tsod.bra_id					AND
								tsoh.soh_id				= tsod.soh_id
						INNER JOIN @tblBranchs											tbBGC
							ON tbBGC.bra_id				= tsoh.bra_id
						INNER JOIN tbDocumentsFile										tdf			WITH (NOLOCK)
							ON	tdf.comp_id = tsoh.comp_id AND
								tdf.df_id	= tsoh.df_id
					WHERE	tsod.comp_id					= @comp_id	AND
							tsod.sod_pending4pod_IdRelation = 'True'
					GROUP BY ti.item_id
			)
			UPDATE @tbItemTotals
			SET
				Articulos_Pedidos = ITD.Articulos_Pedidos
				FROM Items_TotalDisponible ITD				WITH (NOLOCK)
				WHERE ITD.ItemId = item_id

			--*****************************************************************************************************************************




			-- --------------------------------------------------------------------------------------
			-- Sabiendo que:	tit.Stock: Stock DISPONIBLE SIN pedidos pendientes de relacionar.
			--					tit.Articulos_OC: Ordenes de compra NO relacionadas a pedidos
			--					tit.Articulos_Pedidos: Pedidos PENDIENTES a relacionar a Ordenes de compra.
			-- --------------------------------------------------------------------------------------


    		IF @field4Update = 1
				BEGIN
					UPDATE  tbComplexFilter
						SET	sl_tmpData  =
									dbo.fnGetPurchaseLote2Buy(tit.comp_id,tit.item_id,
											tit.StockMin - ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)		-- Pedir lo NECESARIO para llegar a tener el Stock OPTIMO!!!!!!!
															)
							-- Que es esto ??????
							--CASE (tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb) WHEN 0 THEN
							--	 tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)
							--ELSE
							--	(tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb)))
							--END

						FROM tbComplexFilter			tcf		WITH (NOLOCK)
						INNER JOIN @tbItemTotals		tit
							ON tit.item_id	= tcf.sl_id

						WHERE	-- Solo si  (Stock DISPONIBLE - Pedidos Pendientes a Vincular + Compras Pendientes de Vincular  ) nO LLEGA AL NIVEL DEL sTOCK mínimo
								tcf.sl_guid			= @SelectionGuid AND
								tit.StockMin > ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)  --AND
								--  ???????   (tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb))) > 0

				END
			ELSE
				BEGIN
					UPDATE  tbComplexFilter
						SET	sl_tmpData2  =
									dbo.fnGetPurchaseLote2Buy(tit.comp_id,tit.item_id,
											tit.StockMin - ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)		-- Pedir lo NECESARIO para llegar a tener el Stock OPTIMO!!!!!!!
															)
							-- Que es esto ??????
							--CASE (tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb) WHEN 0 THEN
							--	 tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)
							--ELSE
							--	(tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb)))
							--END

						FROM tbComplexFilter			tcf		WITH (NOLOCK)
						INNER JOIN @tbItemTotals		tit
							ON tit.item_id	= tcf.sl_id

						WHERE	-- Solo si  (Stock DISPONIBLE - Pedidos Pendientes a Vincular + Compras Pendientes de Vincular  ) nO LLEGA AL NIVEL DEL sTOCK mínimo
								tcf.sl_guid			= @SelectionGuid AND
								tit.StockMin > ( tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)  --AND
								--  ???????   (tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) + ( tit.item_upb - ((tit.StockMin - (tit.Stock + tit.Articulos_OC - tit.Articulos_Pedidos)) % dbo.fnNoZDiv(tit.item_upb))) > 0

				END






END


GO




CREATE PROCEDURE [dbo].[spPurchasePlanning_Update_QtySuggested_WithDays]
(
	@comp_id			INT,
	@Guid				UNIQUEIDENTIFIER,
	@SelectionGuid		UNIQUEIDENTIFIER,
	@stor_id			INT,
	@brag_id			INT,
	@user_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@daystorep			INT,
	@field4Update		INT


)
AS


SET NOCOUNT ON

BEGIN


	----------------------------------------------------------------------------------------
	-- Testing
	----------------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@Guid				UNIQUEIDENTIFIER,
			@SelectionGuid		UNIQUEIDENTIFIER,
			@stor_id			INT,
			@brag_id			INT,
			@user_id			INT,
			@datefrom			DATETIME,
			@dateto				DATETIME,
			@daystorep			int


	SELECT  @comp_id			= 1,
			@Guid				= 'a112331f-a764-4fe7-a9ed-cf03eddfe60a',
			@SelectionGuid		= '2c854b2f-280b-4e22-b9ad-2d5457cb67ae',
			@datefrom			= '10/01/2000',
			@dateto				= '10/31/2017',
			@daystorep			= 30,
			@stor_id			= 3,
			@brag_id			= 4,
			@user_id			= 3
	*/
	----------------------------------------------------------------------------------------
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom	, 'false')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto	,'true')


	DECLARE @tblComplexFilter_AllItems TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_AllItems
			SELECT
				tcf.sl_id

				FROM tbComplexFilter tcf			WITH (NOLOCK)

				WHERE tcf.sl_guid = @SelectionGuid

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
		INSERT INTO @tblBranchs
			SELECT DISTINCT	bra_id
				FROM tbBranchGroupDetail tbgd		WITH (NOLOCK)
				WHERE	tbgd.comp_id = @comp_id		AND
						tbgd.brag_id = @brag_id



	-- Borro todas las sucursales a las que no pueda acceder
	DELETE	FROM @tblBranchs
			FROM @tblBranchs												tbl
		LEFT JOIN tbUsers4BranchFilter									vubf	WITH (NOLOCK)
			ON	vubf.comp_id						= @comp_id		AND
				vubf.bra_id							= tbl.bra_id	AND
				vubf.[user_id]						= @user_id
		WHERE vubf.comp_id IS NULL








			--*****************************************************************************************************************************
			-- CREAMOS UNA VARIABLE DE TABLE EN DONDE VAMOS A IR VOLCANDO LOS TOTALES POR ARTICULO
			-- UNA SUMATORIA POR VEZ, PARA EVITAR QUE SE HAGA UN PROCESO ENGORROSO AL TENER TANTOS LEFT JOIN
			--*****************************************************************************************************************************
			DECLARE @tbItemTotals TABLE (
											comp_id								INT,
											item_id								INT,
											Stock								INT,
											Total_Vendido						DECIMAL(19,2),
											item_upb							DECIMAL(18,4),
											Articulos_OC						DECIMAL(19,2),  -- ARTÍCULOS + ORDENES DE COMPRAS
											Articulos_Pedidos_Pendientes		DECIMAL(19,2)	-- ARTÍCULOS + PEDIDOS PENDIENTES
										)
			--SE AGREGARON LAS ÚLTIMAS 3 COLUMNAS STL

			--*****************************************************************************************************************************


			--*****************************************************************************************************************************
			-- ARTICULOS + STOCK
			--*****************************************************************************************************************************

			INSERT INTO @tbItemTotals
			(
				comp_id,
				item_id,
				Stock,
				Total_Vendido,
				item_upb,
				Articulos_OC,
				Articulos_Pedidos_Pendientes
			)
			SELECT
				ti.comp_id,
				ti.item_id,
				dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id,ti.item_id),
				0,
				ti.item_upb,
				0,
				0

			FROM tbItem									ti			WITH (NOLOCK)
				INNER JOIN @tblComplexFilter_AllItems	tbCFAI
					ON tbCFAI.item_id	= ti.item_id
			WHERE	ti.comp_id			= @comp_id


			--*****************************************************************************************************************************


			--*****************************************************************************************************************************
			-- ARTICULOS + TOTAL VENDIDO
			--*****************************************************************************************************************************

			;WITH Items_TotalVendido (ItemId, Total_Vendido)
			AS
			(
				SELECT
					ti.item_id																				[ItemId],
					SUM(CASE WHEN tct.comp_id IS NULL THEN 0 ELSE tit.it_qty * vctfs.PlusOrMinus END)		[Total_Vendido]
					FROM @tbItemTotals								ti
						LEFT JOIN tbItemTransactions				tit			WITH (NOLOCK)
						ON	tit.comp_id				= ti.comp_id	AND
							tit.item_id				= ti.item_id
						LEFT JOIN tbCommercialTransactions			tct			WITH (NOLOCK)
							ON	tct.comp_id			= tit.comp_id	AND
								tct.bra_id			= tit.bra_id	AND
								tct.ct_transaction	= tit.ct_transaction AND
								tct.sd_id			IN (1,3)			-- FC y NC
						LEFT JOIN vwCommercialTransactions_forSales vctfs		WITH (NOLOCK)
							ON	vctfs.comp_id			= tct.comp_id AND
								vctfs.ct_transaction	= tct.ct_transaction
						INNER JOIN @tblBranchs						tbBG
							ON tbbg.bra_id				= tct.bra_id
					WHERE	tct.comp_id					= @comp_id		AND
							tct.ct_date					BETWEEN @datefrom AND @dateto

					GROUP BY ti.item_id
			)
			UPDATE @tbItemTotals
			SET
				Total_Vendido = ITV.Total_Vendido
				FROM Items_TotalVendido ITV
				WHERE ITV.ItemId = item_id

			--*****************************************************************************************************************************


				--*****************************************************************************************************************************
			--ARTICULOS + ORDENES DE COMPRA
			--*****************************************************************************************************************************

			;WITH Items_TotalSales (ItemId, Articulos_OC)
			AS
			(
				SELECT
					ti.item_id															[ItemId],
					SUM(CASE WHEN tpoh.comp_id IS NULL THEN 0 ELSE tpod.pod_qty END)	[Disponible]
					FROM @tbItemTotals										ti
						LEFT JOIN tbPurchaseOrderDetail						tpod	WITH (NOLOCK)
						ON	tpod.comp_id			= ti.comp_id			AND
							tpod.item_id			= ti.item_id			AND
							tpod.pod_isProcessed	= 'False'
						LEFT JOIN tbPurchaseOrderHeader						tpoh	WITH (NOLOCK)
							ON	tpoh.comp_id		= tpod.comp_id			AND
								tpoh.bra_id			= tpod.bra_id			AND
								tpoh.poh_id			= tpod.poh_id			AND
								ISNULL(tpoh.poh_isEditing,'False')= 'False'	AND
								ISNULL(tpoh.poh_quotation,'False')= 'False'
						INNER JOIN @tblBranchs								tbBGC
							ON tbBGC.bra_id			= tpoh.bra_id
						INNER JOIN tbUsers4BranchFilter						vubf	WITH (NOLOCK)
							ON	vubf.comp_id		= tpod.comp_id			AND
								vubf.bra_id			= tpod.bra_id			AND
								vubf.[user_id]		= @user_id
					WHERE	tpoh.comp_id							= @comp_id	AND
							ISNULL(tpod.pod_isProcessed,'False')	= 'False'	AND
							ISNULL(tpod.pod_isEditing,	'False')	= 'False'
					GROUP BY ti.item_id
			)
			UPDATE @tbItemTotals
			SET
				Articulos_OC = ITS.Articulos_OC
				FROM Items_TotalSales ITS
				WHERE ITS.ItemId = item_id

			--*****************************************************************************************************************************

			--*****************************************************************************************************************************
			--	ARTICULOS + PEDIDOS PENDIENTES
			--*****************************************************************************************************************************

			;WITH Items_TotalDisponible (ItemId, Articulos_Pedidos_Pendientes)
			AS
			(
				SELECT
					ti.item_id															[ItemId],
					SUM(CASE
							WHEN tdf.df_disable4PurchasePlanning = 'True'			THEN 0
							WHEN	tsoh.comp_id IS NULL THEN 0
							WHEN	tdf.sd_id = 1	OR
									tdf.sd_id = 2	OR
									tdf.sd_id = 21	OR
									tdf.sd_id = 31									THEN tsod.sod_qty
							WHEN	tdf.sd_id = 3	OR
									tdf.sd_id = 12  OR
									tdf.sd_id = 23	OR
									tdf.sd_id = 33									THEN tsod.sod_qty  * -1
							ELSE						  0
							--WHEN tsoh.comp_id IS NULL THEN 0
							--ELSE tsod.sod_qty
					    END)															[Sales]
					FROM @tbItemTotals													ti
						LEFT JOIN tbSaleOrderDetail										tsod		WITH (NOLOCK)
							ON	tsod.comp_id			= ti.comp_id					AND
								tsod.item_id			= ti.item_id
						LEFT JOIN tbSaleOrderHeader										tsoh		WITH (NOLOCK)
							ON	tsoh.comp_id			= tsod.comp_id					AND
								tsoh.bra_id				= tsod.bra_id					AND
								tsoh.soh_id				= tsod.soh_id
						INNER JOIN @tblBranchs											tbBGC
							ON tbBGC.bra_id				= tsoh.bra_id

						LEFT JOIN tbDocumentsFile										tdf			WITH (NOLOCK)
						ON tdf.comp_id					= tsoh.comp_id					AND
						   tdf.df_id					= tsoh.df_id

					WHERE	tsod.comp_id				= @comp_id		--AND
							--(tdf.sd_id = 1 OR tdf.sd_id = 2 OR tdf.sd_id = 31 OR tdf.sd_id IS NULL)
					GROUP BY ti.item_id
			)
			UPDATE @tbItemTotals
			SET
				Articulos_Pedidos_Pendientes = ITD.Articulos_Pedidos_Pendientes
				FROM Items_TotalDisponible ITD				WITH (NOLOCK)
				WHERE ITD.ItemId = item_id

			--*****************************************************************************************************************************

			--------------------------------------------------------------------------------------------------------------
			-- test
			-- ejemplo de como se calcula la cantidad sugerida para que sea multiplo del upb
			-- test
			--------------------------------------------------------------------------------------------------------------
			/*
			DECLARE @Residuo decimal(8,2)
			DECLARE @ValASumar decimal(8,2)
			DECLARE @cantidadsugerida2 integer
			DECLARE	@UPB2 integer

			select 	@cantidadsugerida2 = -73386.967742,
					@UPB2 =20

			set @Residuo=@cantidadsugerida2 % dbo.fnNoZDiv(@UPB2)
			--SELECT @Residuo
			IF @Residuo=0
			select @cantidadsugerida2
			ELSE
			select @cantidadsugerida2+(@UPB2-@Residuo)
			*/
			--------------------------------------------------------------------------------------------------------------

    		IF @field4Update = 1
				BEGIN
					UPDATE  tbComplexFilter
					SET	sl_tmpData  =
									dbo.fnGetPurchaseLote2Buy(tit.comp_id,tit.item_id,
																CASE ((((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes) % dbo.fnNoZDiv(tit.item_upb)) WHEN 0 THEN
																	((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes
																ELSE
																	(((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes)+(tit.item_upb-((((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes) % dbo.fnNoZDiv(tit.item_upb)))
																END
															)
					FROM tbComplexFilter			tcf		WITH (NOLOCK)
					INNER JOIN @tbItemTotals		tit
					ON tit.item_id	= tcf.sl_id

					WHERE	tcf.sl_guid			= @SelectionGuid AND
							((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes > 0 AND -- actualiza solo si es mayor a 0
							(((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes)+(tit.item_upb-((((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes) % dbo.fnNoZDiv(tit.item_upb))) > 0

				END
			ELSE
				BEGIN
					UPDATE  tbComplexFilter
					SET	sl_tmpData2  =
									dbo.fnGetPurchaseLote2Buy(tit.comp_id,tit.item_id,
																CASE ((((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes) % dbo.fnNoZDiv(tit.item_upb)) WHEN 0 THEN
																	((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes
																ELSE
																	(((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes)+(tit.item_upb-((((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes) % dbo.fnNoZDiv(tit.item_upb)))
																END
															)
					FROM tbComplexFilter			tcf		WITH (NOLOCK)
					INNER JOIN @tbItemTotals		tit
					ON tit.item_id	= tcf.sl_id

					WHERE	tcf.sl_guid			= @SelectionGuid AND
							((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes > 0 AND -- actualiza solo si es mayor a 0
							(((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes)+(tit.item_upb-((((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes) % dbo.fnNoZDiv(tit.item_upb))) > 0

				END



			--SELECT
			--tit.item_id,
			--tit.Stock,
			--tit.Total_Vendido,
			--tit.item_upb,
			--tit.Articulos_OC ,
			--tit.Articulos_Pedidos_Pendientes,
			--dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1),
			--@daystorep,
			--((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ),
			--(((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes),

			--	CASE ((((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes) % dbo.fnNoZDiv(tit.item_upb)) WHEN 0 THEN
			--			(((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes)
			--	ELSE
			--			(((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes)+(tit.item_upb-((((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes) % dbo.fnNoZDiv(tit.item_upb)))

			--	END				[cantsugetotal]-- cantidad sugerida ( multiplo de upb )

			--FROM tbComplexFilter			tcf		WITH (NOLOCK)
			--INNER JOIN @tbItemTotals		tit
			--ON tit.item_id	= tcf.sl_id

			--	WHERE	tcf.sl_guid			= @SelectionGuid AND
			--        ((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes < 0 and
			--        (((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes)+(tit.item_upb-((((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes) % dbo.fnNoZDiv(tit.item_upb))) < 0



	--SELECT
	--	((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes [cantidad sugerida],
	--	tit.item_upb [upb],
	--(((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes)+(tit.item_upb-((((tit.Total_Vendido / dbo.fnNoZDiv(DATEDIFF(day, @datefrom, @dateto)+1)) * @daystorep ) - tit.Stock - tit.Articulos_OC + tit.Articulos_Pedidos_Pendientes) % dbo.fnNoZDiv(tit.item_upb))) [cant final con upb]
	--FROM tbComplexFilter			tcf		WITH (NOLOCK)
	--		INNER JOIN @tbItemTotals		tit
	--		ON tit.item_id	= tcf.sl_id



END










GO






-- =================================================================
-- Desc: Verificacion para saber si imprime o no el reporte de compra.
-- Date: 13/09/13
-- Author: GA
-- =================================================================


CREATE PROCEDURE [dbo].[spPurchasePrintExclusion_GetData]
(
	@comp_id			INT,
	@bra_id				INT,
	@user_id			INT,
	@prof_id			INT
)

As
Set NoCount On


BEGIN


	------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@bra_id				INT,
				@user_id			INT,
				@prof_id			INT

	SELECT		@comp_id		= 1,
				@user_id		= 3,
				@prof_id		= 1,
				@bra_id			= 1
*/

	------------------------------------------------------

	-- Si existe el perfil o usuario en la tabla devuelve un 0 , si no existe devuelve un 1 .

		IF EXISTS	(	 SELECT tppe.ppe_id, tppe.[user_id],tppe.prof_id

		         	 	 FROM tbPurchasePrintExclusion tppe

						 WHERE	 tppe.comp_id				= @comp_id		AND
								 tppe.bra_id				= @bra_id		AND
								(tppe.[user_id] = @user_id OR tppe.prof_id = @prof_id)

					)
						-- Ya existe el perfil o usuario por ende NO imprime reporte de compra
						SELECT 0	[StatusPrint]

		ELSE
						-- NO existe el perfil o usuario por ende SI imprime reporte de compra
						SELECT 1	[StatusPrint]







END


GO







CREATE procedure [dbo].[spPurchaseStatusConcept_GetDataByFilters]
(
			@comp_id			int,
			@lang_id			int,
			@bra_id				int,
			@prof_id			int,
			@user_id			int,

			@ct_datefrom		datetime,
			@ct_paydatefrom		datetime,
			@ct_dateto			datetime,
			@ct_paydateto		datetime,
			@sk_id				int,
			@supp_id			int,
			@is_ok				BIT

)
AS
SET NOCOUNT ON


BEGIN

--------------------------------------------------
------------------prueba-parametros---------------
--------------------------------------------------
/*
declare		@comp_id			int,
			@lang_id			int,
			@bra_id				int,
			@prof_id			int,
			@user_id			int,

			@ct_datefrom		datetime,
			@ct_paydatefrom		datetime,
			@ct_dateto			datetime,
			@ct_paydateto		datetime,
			@sk_id				int,
			@supp_id			int,
			@is_ok				BIT

select
			@comp_id			= 1,
			@lang_id			= 2,
			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 1,

			@ct_datefrom		= '01-01-1999',
			@ct_dateto			= '12-31-9999',
			@ct_paydatefrom		= '01-01-1999',
			@ct_paydateto		= '12-31-9999',
			@sk_id				= -1,
			@supp_id			= -1,
			@is_ok				= 'false'

*/
--------------------------------------------------
------------------prueba-parametros---------------
--------------------------------------------------

		declare @luser_purchasedocuments_AuthorizeAllStatus	bit

		SELECT	@luser_purchasedocuments_AuthorizeAllStatus	= isnull(tu.user_PurchaseDocuments_AuthorizeAllStatus, 'false')
		FROM	tbUser tu
		WHERE	tu.[user_id] = @user_id



		select	' ' [ ],
				' ' [ ],
				tpdsc.pdsc_desc																		[pdsc_desc],
				tct.ct_date																			[ct_date],
				dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction)	[desc],
				tct.ct_ATotal																		[ct_ATotal],
				tct.ct_ABalance																		[ct_ABalance],
				tc.curr_desc																		[curr_desc],
				ts.supp_name																		[supp_name],
				tsk.sk_desc																			[sk_desc],
				tu.user_lastname + ', ' + tu.user_firstname											[user_Request],
				tu2.user_lastname + ', ' + tu2.user_firstname										[user_id_Authorization],
				tpds.pds_date																		[pds_date],
				tpds.pds_dateOfAuthorization														[pds_dateOfAuthorization],
				tov.optval_desc																		[pds_is_ok],
				convert(varchar,tpds.comp_id) + '-' + convert(varchar,tpds.bra_id) + '-' + convert(varchar,tpds.ct_transaction) + '-' + convert(varchar,tpds.pdsc_id)		 [ID]


		FROM	dbo.tbPurchaseDocumentsStatus							tpds

				inner join tbPurchaseDocumentsStatusConcept 			tpdsc
				on	tpdsc.comp_id		= tpds.comp_id	AND
					tpdsc.pdsc_id		= tpds.pdsc_id

				inner join tbCommercialTransactions						tct
				on  tct.comp_id			= tpds.comp_id	AND
					tct.bra_id			= tpds.bra_id	AND
					tct.ct_transaction	= tpds.ct_transaction

				inner join tbSupplier									ts
				on  ts.comp_id			= tct.comp_id	AND
					ts.supp_id			= tct.supp_id

				left join tbSupplierKind								tsk
				on	tsk.comp_id			= ts.comp_id	AND
					tsk.sk_id			= ts.sk_id

				left join tbUser										tu
				on  tu.[user_id]		= tpds.user_id_Request

				left join tbUser										tu2
				on	tu2.[user_id]		= tpds.user_id_Authorization

				inner join tbsysOptionsValues							tov
				on	tov.lang_id			= @lang_id		AND
					tov.optval_class	= 1				AND
					tov.optval_id		= tpds.pds_isOk

				left join tbsysCurrency								tc
				on	tc.curr_id = tct.ct_ACurrency



		where   (tpdsc.comp_id				= @comp_id)
		AND     (tct.bra_id					= @bra_id)
		AND		(@supp_id					= -1 OR tct.supp_id					= @supp_id )
		AND		(@sk_id						= -1 OR tsk.sk_id					= @sk_id )
		AND		(tpdsc.prof_id				= @prof_id or tpdsc.prof_id_2		= @prof_id OR @luser_purchasedocuments_AuthorizeAllStatus = 'true')
		AND		(tpds.pds_isOk				= @is_ok)
		AND		tct.ct_date		between @ct_datefrom		and @ct_dateto
		AND		tct.ct_paydate	between @ct_paydatefrom		and @ct_paydateto

		AND		( TPDSC.brag_id IS NULL OR
					EXISTS(SELECT 1
							FROM	tbBranchGroupDetail tbgd
							WHERE   TBGD.bra_id		= @bra_id  AND
									TBGD.comp_id	= @comp_id AND
									TBGD.brag_id	= tpdsc.brag_id )
				)


END
GO






CREATE procedure [dbo].[spPurchaseTerms_GetCombo]
(
		@comp_id		int
)
as
set nocount on

SELECT
		[pt_id]			[Id],
		[pt_desc]		[Desc]

FROM	[tbPurchaseTerms]

WHERE	comp_id = @comp_id

Order By [pt_desc]
GO











create  PROCEDURE [dbo].[spPurchaseTerms_getDataById]
(
	@comp_id		int,
	@pt_id			int
)
as
set nocount on

/*
DECLARE 	@comp_id		int,
			@pt_id			int

	SELECT 	@comp_id		=1,
			@pt_id			=5
*/

BEGIN



		SELECT tpt.pt_id,
		isnull(tpt.pt_desc,'')				 [pt_desc],
		isnull(tpt.pt_quoteQTY,0)			 [pt_quoteQTY],
		isnull(tpt.pt_days4FirstQuote,0)	 [pt_days4FirstQuote]

		FROM tbPurchaseTerms tpt

		where	tpt.comp_id = @comp_id	AND
				tpt.pt_id   = @pt_id




END




GO



CREATE PROCEDURE spPurchaseTerms_GetFirstTerm
(
	@comp_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN

			SELECT
				TOP 1
					tpt.pt_id,
					tpt.pt_desc
			FROM tbPurchaseTerms tpt
			WHERE tpt.comp_id = @comp_id
			ORDER BY tpt.pt_id DESC

		END
GO



