CREATE PROCEDURE [dbo].[spReports_getData]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,
	@func_id			int = 1
)
AS



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



SET NOCOUNT ON
------------------------------------------------------------------------
---  ACTUALIZADO CON tbSysNamesNew 26/02/2010---------------------------
------------------------------------------------------------------------


/*
declare	@comp_id	INT,
		@lang_id	int,
		@page_id	INT,
		@func_id	int
select 	@comp_id    = 1,
		@lang_id	= 2,
		@page_id	= 10009,
		@func_id	= 1
*/




/************************************************************************************************/
/*Query que recupera los valores de títulos y para la página determinada*/
declare @ctrl_desc	varchar(100),
		@text_desc	varchar(300),
		@fun_id		varchar(2),
		@select		varchar(8000)

set @select = 'select comp_desc [rptCompanyName], comp_logo [rptCompanyLogo], '

declare cursor_R_gD_values cursor for
select	c.[ctrl_desc], tswn.word_desc --t.[text_desc]
from	[tbsysTextsNew]				t
		inner join [tbsysControls]	c
		on	c.[ctrl_id]		= t.[ctrl_id]
		INNER JOIN tbSysWordsNew tswn
		ON	tswn.lang_id	= @lang_id
		AND tswn.wordsi_id	= t.wordsi_id

where	--t.[lang_id]	= @lang_id
--and
		t.[page_id]	= @page_id
and		t.[type_id]	= 31
AND		t.fun_id	= @func_id
order by t.[ctrl_id]


open cursor_R_gD_values

fetch cursor_R_gD_values
into	@ctrl_desc, @text_desc

while @@FETCH_STATUS = 0
BEGIN

	set @select = @select + '''' + ISNULL(@text_desc,' ') + '''' + ' [' + @ctrl_desc + '], '

	fetch cursor_R_gD_values
	into	@ctrl_desc, @text_desc

END

close cursor_R_gD_values
deallocate cursor_R_gD_values

set @select = substring(@select,1,len(@select)-1) +
			' from tbCompany where comp_id = ' + convert(varchar,@comp_id)
--SELECT @select
IF LEN(@select) > 20
	exec (@select)
/************************************************************************************************/





/************************************************************************************************/
/*Query que recupera los valores de aquello que sea un valor único, y debe
estar cargado de misma manera que para los textos a mostrar en las páginas, este query no debe modificarse*/
--declare @ctrl_desc	varchar(100),
--		@text_desc	varchar(100),
--		@fun_id		varchar(2),
--		@select		varchar(8000)

set @select = 'select '

declare cursor_R_gD_values cursor for
select	c.[ctrl_desc], tswn.word_desc -- t.[text_desc]
from	[tbsysTextsNew]				t
		inner join [tbsysControls]	c
		on c.[ctrl_id] = t.[ctrl_id]
		INNER JOIN tbSysWordsNew tswn
		ON	tswn.lang_id	= @lang_id
		AND tswn.wordsi_id	= t.wordsi_id

where	--t.[lang_id]	= @lang_id
--and
		t.[page_id]	= 10000
and		t.[type_id]	= 35
order by t.[ctrl_id]

open cursor_R_gD_values

fetch cursor_R_gD_values
into	@ctrl_desc, @text_desc

while @@FETCH_STATUS = 0
BEGIN

	set @select = @select + '''' + ISNULL(@text_desc,' ') + '''' + ' [' + @ctrl_desc + '], '

	fetch cursor_R_gD_values
	into	@ctrl_desc, @text_desc

END

close cursor_R_gD_values
deallocate cursor_R_gD_values

set @select = substring(@select,1,len(@select)-1)
--SELECT @select
IF LEN(@select) > 20
	exec (@select)
/************************************************************************************************/









/************************************************************************************************/
/*query para recuperar los nombres de las columnas del reporte*/

/*verificar la existencia de una tabla para la página seleccionada*/
/*Para recuperar los títulos de tbsysnamesNew y de tbsysfields sólo se debe actualiza el campo table_id correspondiente en la tabla tbsyspages*/
if (select table_id  from [tbsysPages] where [page_id] = @page_id) is null
 	begin

		/*no hay tabla asociada a la página*/
		/*se deben recuperar los valores de los headers desde tbsysTexts*/

		/************************************************************************************************/
		/*Query que recupera los valores de títulos de cada columna del reporte, y debe
		estar cargado de misma manera que para los textos a mostrar en las páginas, este query no debe modificarse*/
		set @select = 'select '

		declare cursor_R_gD_values cursor for
		select	c.[ctrl_desc], tswn.word_desc, t.[fun_id]
		from	[tbsysTextsNew]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
				INNER JOIN tbSysWordsNew tswn
				ON	tswn.lang_id	= @lang_id
				AND tswn.wordsi_id	= t.wordsi_id

		where	--t.[lang_id]	= @lang_id
		--and
				t.[page_id]	= @page_id
		and		t.[type_id]	= 32
		order by t.[fun_id]

		open cursor_R_gD_values

		fetch cursor_R_gD_values
		into	@ctrl_desc, @text_desc, @fun_id

		while @@FETCH_STATUS = 0
		BEGIN

			set @select = @select + '''' + @text_desc + '''' + ' [' + @ctrl_desc + @fun_id + '], '

			fetch cursor_R_gD_values
			into	@ctrl_desc, @text_desc, @fun_id

		END

		close cursor_R_gD_values
		deallocate cursor_R_gD_values

		set @select = substring(@select,1,len(@select)-1)
		--SELECT @select
		IF LEN(@select) > 20
			exec (@select)
		ELSE
			BEGIN
				EXEC ('select '' '' [rptColumn1], '' '' [rptColumn2], '' '' [rptColumn3], '' '' [rptColumn4],
							'' '' [rptColumn5], '' '' [rptColumn6], '' '' [rptColumn7], '' '' [rptColumn8],
							'' '' [rptColumn9], '' '' [rptColumn10], '' '' [rptColumn11], '' '' [rptColumn12],
							'' '' [rptColumn13], '' '' [rptColumn14], '' '' [rptColumn15], '' '' [rptColumn16],
							'' '' [rptColumn17], '' '' [rptColumn18], '' '' [rptColumn19], '' '' [rptColumn20]')
			END
		/************************************************************************************************/


	end
else
	begin

		/*hay tabla asociada a la página*/
		/*se deben recuperar los valores de los headers desde tbsysFileds y tbsysNamesNew*/

		declare	@nameColumn		varchar(9),
				@numberColumn	int
		set		@nameColumn		= 'rptColumn'
		set		@numberColumn	= 0

		set @select = 'select '

		declare cursor_R_gD_values cursor for
		select 	'[' + tswn.word_desc + ']'		name_desc

		from 	tbSysTables					t

				inner join tbSysFields		f
				on 		f.table_id			= t.table_id

				inner join tbSysNamesNew	n
				on 		n.table_id			= t.table_id
				and		n.field_id			= f.field_id

				LEFT JOIN tbSysWordsNew		tswn
				ON tswn.lang_id				= @lang_id
				AND tswn.wordsi_id			= n.name_desc_id

		where 	t.table_id					= (select table_id  from [tbsysPages] where [page_id] = @page_id) --4 --@table_id
		--and		n.lang_id 					= @lang_id
		and		f.field_visible				= 'True'
		and		f.field_function			<> 'P'

		order by f.field_order

		open cursor_R_gD_values

		fetch cursor_R_gD_values	into @ctrl_desc

		while @@FETCH_STATUS = 0
		begin

			set @numberColumn = @numberColumn + 1

			set @select = @select + '''' + replace(replace(@ctrl_desc,'[',''),']','') + '''' +
							' [' + @nameColumn + convert(varchar(2),@numberColumn) + '], '

			fetch cursor_R_gD_values into @ctrl_desc

		end

		close cursor_R_gD_values

		deallocate cursor_R_gD_values

		set @select = substring(@select,1,len(@select)-1)

		IF LEN(@select) > 20
		begin
			exec (@select)
		end

	end

/************************************************************************************************/
GO







CREATE Procedure [dbo].[spReports_getData2]
(
	@comp_id			int,
	@bra_id				INT,
	@lang_id			int,
	@ten_id				int,
	@page_id			int
)
AS




-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



SET NOCOUNT ON



/*
declare	@comp_id	int,
		@lang_id	int,
		@ten_id		int,
		@page_id	int
select 	@comp_id    = 1,
		@lang_id	= 2,
		@ten_id		= 2,
		@page_id	= 10033
*/





/************************************************************************************************/
/*Query que recupera los valores de títulos y para la página determinada*/
declare
		@ctrl_desc	varchar(100),
		@text_desc	varchar(100),
		@fun_id		varchar(2),
		@select		varchar(8000)


	-- ------------------------------------------------------------------------
	-- Trae el nombre y logo de la empresa para los titulos
	-- ------------------------------------------------------------------------
	SET @select = ''
	SELECT	@select =	CASE WHEN tb.bra_logo IS NULL
							THEN 'select tc.comp_MainDesc2 [rptCompanyName], tc.comp_logo [rptCompanyLogo], ' --tc.comp_Logo
							ELSE 'select tb.bra_MainDesc2  [rptCompanyName], tb.bra_logo  [rptCompanyLogo], ' --tb.bra_logo
						END
		FROM	tbCompany					tc
				Inner JOIN tbBranch			tb
				ON	tb.comp_id	= tc.comp_id	AND
					tb.bra_id	= @bra_id
		WHERE	tc.comp_id		= @comp_id
	IF @select = ''
		BEGIN
			SELECT	@select = 'select tc.comp_MainDesc2 [rptCompanyName], tc.comp_logo [rptCompanyLogo], '
				FROM	tbCompany					tc
				WHERE	tc.comp_id		= @comp_id

		END
	-- ------------------------------------------------------------------------




declare cursor_R_gD2_values cursor for

/*Modificación para que el titulo del reporte lo traiga desde la tbTaxEngineName en lugar de
la tbSysTexts*/

Select	ten.ten_printname
from	[tbTaxEngineName]	ten
where	ten.ten_id = @ten_id

/*Select anterior que recuperaba el titulo del reporte de la tbSysTexts*/

/*select	c.[ctrl_desc], t.[text_desc]
from	[tbsysTexts]				t
		inner join [tbsysControls]	c
		on c.[ctrl_id] = t.[ctrl_id]

where	t.[lang_id]	= @lang_id
and		t.[page_id]	= @page_id
and		t.[type_id]	= 31
order by t.[ctrl_id]*/

open cursor_R_gD2_values

fetch cursor_R_gD2_values
into	@text_desc

while @@FETCH_STATUS = 0
BEGIN

	set @select = @select + '''' + ISNULL(@text_desc,' ') + '''' + ' [rptTitle], '

	fetch cursor_R_gD2_values
	into	@text_desc

END

close cursor_R_gD2_values
deallocate cursor_R_gD2_values


set @select = substring(@select,1,len(@select)-1) +
				' from tbCompany tc ' +
				' left join tbBranch tb ON	tb.comp_id	= tc.comp_id AND tb.bra_id	= ' + convert(varchar,@bra_id) +
				' where tc.comp_id = ' + convert(varchar,@comp_id)



--
--set @select = substring(@select,1,len(@select)-1) +
--			' from tbCompany where comp_id = ' + convert(varchar,@comp_id)
--SELECT @select
IF LEN(@select) > 20
	exec (@select)
/************************************************************************************************/

/************************************************************************************************/
/*Query que recupera los valores de aquello que sea un valor único, y debe
estar cargado de misma manera que para los textos a mostrar en las páginas, este query no debe modificarse*/
--declare @ctrl_desc	varchar(100),
--		@text_desc	varchar(100),
--		@fun_id		varchar(2),
--		@select		varchar(8000)

set @select = 'select '

declare cursor_R_gD2_values cursor for
select	c.[ctrl_desc], tswn.word_desc
from	[tbsysTextsNew]				t
		inner join [tbsysControls]	c
		on c.[ctrl_id] = t.[ctrl_id]
		INNER JOIN tbSysWordsNew tswn
		ON tswn.lang_id	= @lang_id
		AND tswn.wordsi_id = t.wordsi_id

where	--t.[lang_id]	= @lang_id
--and
		t.[page_id]	= 10000
and		t.[type_id]	= 35
order by t.[ctrl_id]

open cursor_R_gD2_values

fetch cursor_R_gD2_values
into	@ctrl_desc, @text_desc

while @@FETCH_STATUS = 0
BEGIN

	set @select = @select + '''' + ISNULL(@text_desc,' ') + '''' + ' [' + @ctrl_desc + '], '

	fetch cursor_R_gD2_values
	into	@ctrl_desc, @text_desc

END

close cursor_R_gD2_values
deallocate cursor_R_gD2_values

set @select = substring(@select,1,len(@select)-1)

--SELECT @select
IF LEN(@select) > 20
	exec (@select)



/*******************************************************************************************************************/
/*query que recupera los nombres de las columnas del reporte que estan en la tabla tbTaxEngineName_Taxes*/
declare @query varchar (8000)
select @query = 'select '



declare cursor_R_gD2_values cursor for
select	c.[ctrl_desc], tswn.word_desc, t.[fun_id]
from	[tbsysTextsNew]					t
		inner join [tbsysControls]		c
		on c.[ctrl_id] = t.[ctrl_id]
		INNER JOIN tbSysWordsNew		tswn
		ON tswn.lang_id	= @lang_id
		AND tswn.wordsi_id = t.wordsi_id

where	--t.[lang_id]	= @lang_id
--and
		t.[page_id]	= @page_id
and		t.[type_id]	= 32
order by t.[fun_id]

open cursor_R_gD2_values

fetch cursor_R_gD2_values
into	@ctrl_desc, @text_desc, @fun_id

while @@FETCH_STATUS = 0
BEGIN

	set @query = @query + '''' + @text_desc + '''' + ' [' + @ctrl_desc + @fun_id + '], '

	fetch cursor_R_gD2_values
	into	@ctrl_desc, @text_desc, @fun_id

END

close cursor_R_gD2_values
deallocate cursor_R_gD2_values



DECLARE @i  INT
SET 	@i	= 1
WHILE	@i < 12
BEGIN
   if exists (select	1
				from	[tbTaxEngineName_Taxes]		ttent
						INNER JOIN #tmpColumns		tmpc
						ON	ttent.tent_column = tmpc.tent_column
				where	ttent.[ten_id]						= @ten_id
				and		tmpc.id								= @i
				AND		isnull(ttent.tent_isHidden,'false')	= 'false')
		begin
			set @query = @query + '(select	[tent_columnName]
			                        from	[tbTaxEngineName_Taxes]		ttent
											INNER JOIN #tmpColumns		tmpc
											ON	ttent.tent_column = tmpc.tent_column
			                        where	[ten_id] = ' + convert(varchar,@ten_id) + '
			                        and		tmpc.id  = ' + convert(varchar,@i)      + ' ) '
		end
   else
		begin
			set @query = @query + '(select '''') '
		end

	set @query = @query + ' [rptColumn' + convert(varchar,@i) + '], '
   set @i = @i + 1
END
set @query = substring(@query,1,len(@query)-1)



--select @query
exec (@query)

GO




CREATE PROCEDURE [dbo].[spReports_getData3]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			INT,
	@page_id			INT,
	@func_id			INT = 1
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE @intCountryId AS INT
	SELECT @intCountryId = br.country_id
		FROM tbbranch	br			WITH (NOLOCK)
		WHERE	br.comp_id	= @comp_id AND
				br.bra_id	= @bra_id
	IF @intCountryId IS NULL
		BEGIN
			SET @intCountryId = 54
		END






	SET NOCOUNT ON

	------------------------------------------------------------------------
	---  ACTUALIZADO CON tbSysNamesNew 26/02/2010---------------------------
	------------------------------------------------------------------------
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-11-10
	-- Parte		: 671
	-- Description	: Se agrega la funcionalidad que, de existir la imagen de la sucursal, se devuelve la imagen y la
	--                descripción de la sucursal informada, sino se informa la imagen y la descripción de la compañía
	-- =================================================================================================================




	/*
	declare	@comp_id		INT,
			@bra_id			INT,
			@lang_id		INT,
			@page_id		INT,
			@func_id		INT
	select 	@comp_id		= 1,
			@bra_id			= 2,
			@lang_id		= 2,
			@page_id		= 10009,
			@func_id		= 1
	*/




	/************************************************************************************************/
	/*Query que recupera los valores de títulos y para la página determinada*/
	declare @ctrl_desc	varchar(100),
			@text_desc	varchar(300),
			@fun_id		varchar(2),
			@select		varchar(8000)




	-- ------------------------------------------------------------------------
	-- Trae el nombre y logo de la empresa para los titulos
	-- ------------------------------------------------------------------------
	SET @select = ''
	SELECT	@select =	CASE
							WHEN tb.bra_logo IS NULL	THEN	'select tc.comp_MainDesc2 [rptCompanyName], tc.comp_logo [rptCompanyLogo], ' --tc.comp_Logo
							ELSE								'select tb.bra_MainDesc2  [rptCompanyName], tb.bra_logo  [rptCompanyLogo], ' --tb.bra_logo
						END
		FROM	tbCompany					tc				WITH (NOLOCK)
				LEFT JOIN tbBranch			tb				WITH (NOLOCK)
				ON	tb.comp_id	= tc.comp_id	AND
					tb.bra_id	= @bra_id
		WHERE	tc.comp_id		= @comp_id
	IF @select = ''
		BEGIN
			SELECT	@select = 'select tc.comp_MainDesc2 [rptCompanyName], tc.comp_logo [rptCompanyLogo], '
					FROM	tbCompany					tc	WITH (NOLOCK)
							LEFT JOIN tbBranch			tb	WITH (NOLOCK)
							ON	tb.comp_id	= tc.comp_id	AND
								tb.bra_id	= @bra_id
					WHERE	tc.comp_id		= @comp_id

		END
	-- ------------------------------------------------------------------------


	--set @select = 'select comp_desc [rptCompanyName], comp_logo [rptCompanyLogo], '



	declare cursor_R_gD_values CURSOR LOCAL FAST_FORWARD FOR
	--select	c.[ctrl_desc], tswn.word_desc --t.[text_desc]
	select	c.[ctrl_desc],
			dbo.fnSysWordsNew_GetText( @lang_id,@intCountryId,t.wordsi_id) [word_desc] --t.[text_desc]
		from	[tbsysTextsNew]				t			WITH (NOLOCK)
				inner join [tbsysControls]	c			WITH (NOLOCK)
				on	c.[ctrl_id]		= t.[ctrl_id]
				--			INNER JOIN tbSysWordsNew tswn
				--			ON	tswn.lang_id	= @lang_id
				--			AND tswn.wordsi_id	= t.wordsi_id

	where	--t.[lang_id]	= @lang_id
	--and
			t.[page_id]	= @page_id
	and		t.[type_id]	= 31
	AND		t.fun_id	= @func_id
	order by t.[ctrl_id]


	open cursor_R_gD_values

	fetch cursor_R_gD_values
	into	@ctrl_desc, @text_desc

	while @@FETCH_STATUS = 0
	BEGIN

		set @select = @select + '''' + ISNULL(@text_desc,' ') + '''' + ' [' + @ctrl_desc + '], '

		fetch cursor_R_gD_values
		into	@ctrl_desc, @text_desc

	END

	close cursor_R_gD_values
	deallocate cursor_R_gD_values


	set @select = substring(@select,1,len(@select)-1) +
				'	from tbCompany tc 	WITH (NOLOCK)' +
				'	left join tbBranch tb	WITH (NOLOCK)
						ON	tb.comp_id	= tc.comp_id AND
							tb.bra_id	= ' + convert(varchar,@bra_id) +
				'	where tc.comp_id = ' + convert(varchar,@comp_id)


	IF LEN(@select) > 20
		exec (@select)
	/************************************************************************************************/





	/************************************************************************************************/
	/*Query que recupera los valores de aquello que sea un valor único, y debe
	estar cargado de misma manera que para los textos a mostrar en las páginas, este query no debe modificarse*/
	--declare @ctrl_desc	varchar(100),
	--		@text_desc	varchar(100),
	--		@fun_id		varchar(2),
	--		@select		varchar(8000)

	set @select = 'select '

	declare cursor_R_gD_values CURSOR LOCAL FAST_FORWARD FOR
	select	c.[ctrl_desc], --tswn.word_desc -- t.[text_desc]
			dbo.fnSysWordsNew_GetText( @lang_id,@intCountryId,t.wordsi_id)	[word_desc]
	from	[tbsysTextsNew]				t			WITH (NOLOCK)
			inner join [tbsysControls]	c			WITH (NOLOCK)
			on c.[ctrl_id] = t.[ctrl_id]
--			INNER JOIN tbSysWordsNew tswn
--			ON	tswn.lang_id	= @lang_id
--			AND tswn.wordsi_id	= t.wordsi_id

	where	--t.[lang_id]	= @lang_id
	--and
			t.[page_id]	= 10000
	and		t.[type_id]	= 35
	order by t.[ctrl_id]

	open cursor_R_gD_values

	fetch cursor_R_gD_values
	into	@ctrl_desc, @text_desc

	while @@FETCH_STATUS = 0
	BEGIN

		set @select = @select + '''' + ISNULL(@text_desc,' ') + '''' + ' [' + @ctrl_desc + '], '

		fetch cursor_R_gD_values
		into	@ctrl_desc, @text_desc

	END

	close cursor_R_gD_values
	deallocate cursor_R_gD_values

	set @select = substring(@select,1,len(@select)-1)
	--SELECT @select
	IF LEN(@select) > 20
		exec (@select)
	/************************************************************************************************/









	/************************************************************************************************/
	/*query para recuperar los nombres de las columnas del reporte*/

	/*verificar la existencia de una tabla para la página seleccionada*/
	/*Para recuperar los títulos de tbsysnamesNew y de tbsysfields sólo se debe actualiza el campo table_id correspondiente en la tabla tbsyspages*/
	if (select table_id  from [tbsysPages] 	WITH (NOLOCK) where [page_id] = @page_id) is null
 		begin

			/*no hay tabla asociada a la página*/
			/*se deben recuperar los valores de los headers desde tbsysTexts*/

			/************************************************************************************************/
			/*Query que recupera los valores de títulos de cada columna del reporte, y debe
			estar cargado de misma manera que para los textos a mostrar en las páginas, este query no debe modificarse*/
			set @select = 'select '

			declare cursor_R_gD_values CURSOR LOCAL FAST_FORWARD FOR
			select	c.[ctrl_desc],
					dbo.fnSysWordsNew_GetText( @lang_id,@intCountryId,t.wordsi_id) [word_desc],
					t.[fun_id]
			from	[tbsysTextsNew]				t			WITH (NOLOCK)
					inner join [tbsysControls]	c			WITH (NOLOCK)
					on c.[ctrl_id] = t.[ctrl_id]
--					INNER JOIN tbSysWordsNew tswn
--					ON	tswn.lang_id	= @lang_id
--					AND tswn.wordsi_id	= t.wordsi_id

			where	--t.[lang_id]	= @lang_id
			--and
					t.[page_id]	= @page_id
			and		t.[type_id]	= 32
			order by t.[fun_id]

			open cursor_R_gD_values

			fetch cursor_R_gD_values
			into	@ctrl_desc, @text_desc, @fun_id

			while @@FETCH_STATUS = 0
			BEGIN

				set @select = @select + '''' + @text_desc + '''' + ' [' + @ctrl_desc + @fun_id + '], '

				fetch cursor_R_gD_values
				into	@ctrl_desc, @text_desc, @fun_id

			END

			close cursor_R_gD_values
			deallocate cursor_R_gD_values

			set @select = substring(@select,1,len(@select)-1)
			--SELECT @select
			IF LEN(@select) > 20
				exec (@select)
			ELSE
				BEGIN
					EXEC ('select '' '' [rptColumn1], '' '' [rptColumn2], '' '' [rptColumn3], '' '' [rptColumn4],
								'' '' [rptColumn5], '' '' [rptColumn6], '' '' [rptColumn7], '' '' [rptColumn8],
								'' '' [rptColumn9], '' '' [rptColumn10], '' '' [rptColumn11], '' '' [rptColumn12],
								'' '' [rptColumn13], '' '' [rptColumn14], '' '' [rptColumn15], '' '' [rptColumn16],
								'' '' [rptColumn17], '' '' [rptColumn18], '' '' [rptColumn19], '' '' [rptColumn20]')
				END
			/************************************************************************************************/


		end
	else
		begin

			/*hay tabla asociada a la página*/
			/*se deben recuperar los valores de los headers desde tbsysFileds y tbsysNamesNew*/

			declare	@nameColumn		varchar(9),
					@numberColumn	int
			set		@nameColumn		= 'rptColumn'
			set		@numberColumn	= 0

			set @select = 'select '

			declare cursor_R_gD_values CURSOR LOCAL FAST_FORWARD FOR
			select 	'[' + dbo.fnSysWordsNew_GetText( @lang_id,@intCountryId,n.name_desc_id)  + ']'		name_desc

			from 	tbSysTables					t				WITH (NOLOCK)

					inner join tbSysFields		f				WITH (NOLOCK)
					on 		f.table_id			= t.table_id

					inner join tbSysNamesNew	n				WITH (NOLOCK)
					on 		n.table_id			= t.table_id
					and		n.field_id			= f.field_id

--					LEFT JOIN tbSysWordsNew		tswn
--					ON tswn.lang_id				= @lang_id
--					AND tswn.wordsi_id			= n.name_desc_id

			where 	t.table_id					= (select table_id  from [tbsysPages] where [page_id] = @page_id) --4 --@table_id
			--and		n.lang_id 					= @lang_id
			and		f.field_visible				= 'True'
			and		f.field_function			<> 'P'

			order by f.field_order

			open cursor_R_gD_values

			fetch cursor_R_gD_values	into @ctrl_desc

			while @@FETCH_STATUS = 0
			begin

				set @numberColumn = @numberColumn + 1

				set @select = @select + '''' + replace(replace(@ctrl_desc,'[',''),']','') + '''' +
								' [' + @nameColumn + convert(varchar(2),@numberColumn) + '], '

				fetch cursor_R_gD_values into @ctrl_desc

			end

			close cursor_R_gD_values

			deallocate cursor_R_gD_values

			set @select = substring(@select,1,len(@select)-1)

			IF LEN(@select) > 20
			begin
				exec (@select)
			end

		end

	/************************************************************************************************/



END
GO





