-- Author:		<Author,,JAG>
-- Create date: <Create Date,,07/09/2010>
-- Description:	<Description,, "Reimpresion de comprobantes">
-- =============================================

CREATE PROCEDURE [dbo].[spRePrint_getDataByFilters]
(
    @comp_id				INT,
	@lang_id				INT,

	@datefrom				DATETIME,
	@dateto					DATETIME,
	@bra_id					INT,
	@sd_id					INT,

	@option					INT,
	@desc_number			NVARCHAR(50),
	@is_purchase			INT,
	@CustSupp_id			INT,
	@df_id					INT,
	@deliverydatefrom		DATETIME,		--	 fecha de entrega desde tkt 20352
	@deliverydateto			DATETIME		--	 fecha de entrega hasta tkt 20352
)
AS

BEGIN
	SET NOCOUNT ON

-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2011-01-11
-- Parte		: S/P - Referencia: #1
-- Description	: Se cambian las condiciones de where para que filtren correctamente
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2011-06-08
-- TN			: S/T - Referencia: #2
-- Description	: Se agregó la condición de where para que sólo recupere comprobantes que puedan ser reimpresos en
--				  la página correspondiente wfmRePrint
-- =================================================================================================================


-- =================================================================================================================
-- Task 304 - GA - Se agrego Filtro de Clientes/Proveedores
-- 22/04/15
-- =================================================================================================================


-- ============================================
/*
DECLARE @comp_id		INT,
		@lang_id		INT,
		@bra_id			INT,
		@sd_id			INT,
		@datefrom		DATETIME,
		@dateto			DATETIME,
		@option			INT,
		@desc_number	NVARCHAR(50),
		@is_purchase	INT,
		@CustSupp_id	INT,
		@df_id			INT


SELECT  @comp_id     = 1,
        @lang_id     = 2,
        @bra_id      = 1,
        @sd_id       = -1,
		@datefrom    = '01/01/2018',
		@dateto      = '12/31/2018',
		@option	     = -1,
		@desc_number = '',
		@is_purchase = 0 ,
		@CustSupp_id = 24294,
		@df_id	     = -1
*/
-- ============================================



--@is_purchase = 0 = Ventas - Clientes
--@is_purchase = 1 = Compras - Proveedores

SELECT	' ' [ ], ' ' [ ],
		dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction) [ct_transaction],
		CASE WHEN NOT tct.cust_id IS NULL THEN tc.cust_name
			ELSE ts.supp_name
		END																				[name],
		tct.ct_date,
		tct.ct_deliverydate,
		tb.bra_desc,
		convert(varchar,tct.sd_id) + '|' + convert(varchar,tct.ct_transaction) [ID]

FROM	tbCommercialTransactions		tct		WITH (NOLOCK)

		LEFT JOIN tbBranch				tb		WITH (NOLOCK)
		ON  tb.comp_id = tct.comp_id
		AND tb.bra_id  = tct.bra_id

		LEFT JOIN tbCustomer			tc		WITH (NOLOCK)
		ON	tc.comp_id = tct.comp_id
		AND tc.cust_id = tct.cust_id

		LEFT JOIN tbSupplier			ts		WITH (NOLOCK)
		ON  ts.comp_id = tct.comp_id
		AND ts.supp_id = tct.supp_id

WHERE	tct.comp_id					= @comp_id
AND		tct.bra_id					= @bra_id
AND		tct.ct_date					BETWEEN @datefrom			AND @dateto
AND		((tct.ct_deliveryDate		BETWEEN      @deliverydatefrom		AND @deliverydateto) OR tct.ct_deliveryDate IS NULL)
------------------------------------------------------------------------------------------------
-- Task 304 - GA - Filtro de Clientes/Proveedores----
-- 22/04/15
AND		((@is_purchase = 0 AND @CustSupp_id = -1 OR tct.cust_id = @CustSupp_id) OR  --Ventas
		(@is_purchase = 1 AND @CustSupp_id = -1 OR tct.supp_id = @CustSupp_id))		--COmpras
------------------------------------------------------------------------------------------------


--==================================================================================================
-- Referencia: #1
AND		(
		(@sd_id = -1)							OR
		(@sd_id = 1 and tct.sd_id IN (1,101))	OR
		(@sd_id = 2 and tct.sd_id IN (2,102))	OR
		(@sd_id = 3 and tct.sd_id IN (3,103))	OR
		(@sd_id = 4 and tct.sd_id IN (4,104))	OR
		(@sd_id = 5 and tct.sd_id IN (5,105))	OR
		(tct.sd_id = @sd_id)
		)

AND		(
			((
			(@is_purchase = 0 AND NOT tct.cust_id is null) OR
			(@is_purchase = 1 AND NOT tct.supp_id is null)
			)
			AND tct.sd_id <> 200) OR

			tct.sd_id = 200

		)
--==================================================================================================


AND		(
		(@option	 = -1)															OR
		(@option	 = 0 and tct.ct_docNumber like		@desc_number + '%'		)	OR
		(@option	 = 1 and tct.ct_docNumber like		'%' + @desc_number + '%')	OR
		(@option	 = 2 and tct.ct_docNumber =			@desc_number			)	OR
		(@option	 = 3 and tct.ct_docNumber <>		@desc_number			)	OR
		(@option	 = 4 and tct.ct_docNumber not like	'%' + @desc_number + '%')
		)

AND		tct.sd_id IN (1,2,3,4,5,101,102,103,104,105,106,6,13,200,43,44)		-- Ref: #2
AND		(@df_id		= -1	OR	tct.df_id	= @df_id)



ORDER BY tct.ct_transaction DESC

END
GO



CREATE PROCEDURE [dbo].[spRePrint_getDocuments2Reprint]
(
    @comp_id		INT,
	@lang_id		INT,

	@datefrom		DATETIME,
	@dateto			DATETIME,
	@bra_id			INT,
	@sd_id			INT,

	@option			INT,
	@desc_number	NVARCHAR(50),
	@is_purchase	INT,
	@CustSupp_id	INT,
	@df_id			INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- =================================================================================================================
		-- Author		: MOH
		-- Update Date	: 2011-01-11
		-- Parte		: S/P - Referencia: #1
		-- Description	: Se cambian las condiciones de where para que filtren correctamente
		-- =================================================================================================================
		-- Author		: MOH
		-- Update Date	: 2011-06-08
		-- TN			: S/T - Referencia: #2
		-- Description	: Se agregó la condición de where para que sólo recupere comprobantes que puedan ser reimpresos en
		--				  la página correspondiente wfmRePrint
		-- =================================================================================================================


		-- =================================================================================================================
		-- Task 304 - GA - Se agrego Filtro de Clientes/Proveedores
		-- 22/04/15
		-- =================================================================================================================


		-- ============================================
		-- TESTING
		-- ============================================
		/*
			DECLARE @comp_id		INT,
					@lang_id		INT,
					@bra_id			INT,
					@sd_id			INT,
					@datefrom		DATETIME,
					@dateto			DATETIME,
					@option			INT,
					@desc_number	NVARCHAR(50),
					@is_purchase	INT,
					@CustSupp_id	INT,
					@df_id			INT


			SELECT  @comp_id		= 1,
					@lang_id		= 2,
					@bra_id			= 1,
					@sd_id			= -1,
					@datefrom		= '2016-01-01',
					@dateto			= '2016-06-30',
					@option			= -1,
					@desc_number	= '',
					@is_purchase	= 0 ,
					@CustSupp_id	= -1,
					@df_id			= 84
		*/
		-- ============================================



		--@is_purchase = 0 = Ventas - Clientes
		--@is_purchase = 1 = Compras - Proveedores

		SELECT
			tct.comp_id,
			tct.bra_id,
			tct.ct_transaction,
			tct.cust_id,
			tct.sd_id
			FROM	tbCommercialTransactions	tct		WITH (NOLOCK)
			LEFT JOIN tbBranch					tb		WITH (NOLOCK)
				ON  tb.comp_id	= tct.comp_id	AND
				tb.bra_id		= tct.bra_id
			LEFT JOIN tbCustomer				tc		WITH (NOLOCK)
				ON	tc.comp_id	= tct.comp_id	AND
				tc.cust_id		= tct.cust_id
			LEFT JOIN tbSupplier				ts		WITH (NOLOCK)
				ON  ts.comp_id	= tct.comp_id	AND
				ts.supp_id		= tct.supp_id
			INNER JOIN tbDocumentsFile			tdf		WITH(NOLOCK)
				ON	tdf.comp_id = tct.comp_id	AND
					tdf.df_id	= tct.df_id
			WHERE	tct.comp_id			= @comp_id
			AND		tct.bra_id			= @bra_id
			AND		tct.ct_date			BETWEEN @datefrom AND @dateto
		--==================================================================================================
		-- Task 304 - GA - Filtro de Clientes/Proveedores----
		-- 22/04/15
			AND		((@is_purchase	= 0 AND @CustSupp_id = -1 OR tct.cust_id = @CustSupp_id) OR  --Ventas
					(@is_purchase	= 1 AND @CustSupp_id = -1 OR tct.supp_id = @CustSupp_id))		--COmpras
		--==================================================================================================

		--==================================================================================================
		-- Referencia: #1
			AND		(
					(@sd_id		= -1)							OR
					(@sd_id		= 1 and tct.sd_id IN (1,101))	OR
					(@sd_id		= 2 and tct.sd_id IN (2,102))	OR
					(@sd_id		= 3 and tct.sd_id IN (3,103))	OR
					(@sd_id		= 4 and tct.sd_id IN (4,104))	OR
					(tct.sd_id = @sd_id)
					)

			AND		(
						((
						(@is_purchase = 0 AND NOT tct.cust_id is null) OR
						(@is_purchase = 1 AND NOT tct.supp_id is null)
						)
						AND tct.sd_id <> 200) OR

						tct.sd_id = 200

					)
		--==================================================================================================
			AND		(
					(@option	= -1)															OR
					(@option	= 0 and tct.ct_docNumber like		@desc_number + '%'		)	OR
					(@option	= 1 and tct.ct_docNumber like		'%' + @desc_number + '%')	OR
					(@option	= 2 and tct.ct_docNumber =			@desc_number			)	OR
					(@option	= 3 and tct.ct_docNumber <>			@desc_number			)	OR
					(@option	= 4 and tct.ct_docNumber not like	'%' + @desc_number + '%')
					)

			AND		tct.sd_id IN (1,2,3,4,101,102,103,104,106,6,13,200,43,44)		-- Ref: #2
			AND		tdf.df_id	= @df_id
		ORDER BY tct.ct_transaction DESC

	END
GO







CREATE PROCEDURE [dbo].[spRetention_getReport]
(
	@comp_id			Int,
	@lang_id			Int,
	@page_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@intBranch4Lang		int
)
As

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	--Test
	-- -----------------------------------------------------------------------------
	/*

	DECLARE		@comp_id			Int,
				@lang_id			Int,
				@page_id			Int,
				@bra_id				Int,
				@ct_transaction		Int

	SELECT		@comp_id			=1,
				@lang_id			=2,
				@page_id			=10038,
				@bra_id				=1,
				@ct_transaction		=1400
	*/
	-- -----------------------------------------------------------------------------


	--::CABECERA::
	Select --Agente de Reteción:
		   tc.comp_desc,
		   --C.U.I.T
		   --DOMICILIO
		   --LOCALIDAD

		   --Datos del contribuyente:
			ts.supp_name,
			ts.supp_address,
			ts.supp_taxNumber,
			ts.supp_city,
			tct.ct_ATotal,
			tc2.curr_desc + ':' [curr_desc]

			--Importe abonado
			--Min. No Imponible
			--Base Imponible
			--Total Retenido

	From tbTaxMovements ttm			WITH (NOLOCK)

	inner Join tbCommercialTransactions tct	WITH (NOLOCK)
	On  tct.comp_id		   = ttm.comp_id
	AND tct.bra_id		   = ttm.bra_id
	AND tct.ct_transaction = ttm.ct_transaction

	Inner Join tbSupplier ts	WITH (NOLOCK)
	On  ts.comp_id		   = tct.comp_id
	And ts.supp_id		   = tct.supp_id

	Inner Join tbCompany tc	WITH (NOLOCK)
	ON  tc.comp_id		   = ttm.comp_id

	Inner Join tbBranch tb	WITH (NOLOCK)
	ON  tb.comp_id		   = ttm.comp_id
	And tb.bra_id		   = ttm.bra_id

	Inner Join tbsysCurrency tc2	WITH (NOLOCK)
	On tc2.curr_id		  = ttm.curr_id

	Where ttm.comp_id	  = @comp_id
	--And ttm.ct_transaction=@ct_transaction




	--::DETALLE::

	Select ttm.tm_total,
		   ttm.tm_subtotal

	From tbTaxMovements ttm	WITH (NOLOCK)

	Where ttm.comp_id = @comp_id



	exec [spReports_getData3]@comp_id,@intBranch4Lang, @lang_id,@page_id


END
GO





CREATE PROCEDURE [dbo].[spRetentions_order]
(
	@comp_id		INT,
	@lang_id		INT,
	@page_id		INT,
	@bra_id			INT,
	@ct_transaction INT,
	@type			INT,
	@intBranch4Lang	INT,
	@tm_transaction	INT
)
AS

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ----------------------------------------------
	-- Testing
	-- ----------------------------------------------
	/*
		DECLARE @comp_id		Int,
				@lang_id		Int,
				@page_id		Int,
				@bra_id			INT,
				@ct_transaction INT,
				@type			INT,
				@letters		VARCHAR(8000),
				@intBranch4Lang	INT,
				@tm_transaction	INT

		SELECT  @comp_id		= 1,
				@lang_id		= 2,
				@page_id		= 10039,
				@bra_id			= 1,
				@ct_transaction = 1863,
				@type			= 12,
				@letters		= '',
	@intBranch4Lang	= 1,
	@tm_transaction	= 1
	*/
	-- ----------------------------------------------

	DECLARE @doc_number VARCHAR(20)
	SET @doc_number = ''


	/*Detalle de la retención*/
	SELECT	ttn.tax_desc	,
			ttn.ret_impmin	,
			ttm.tm_subtotal	,
			ttm.percentaje	,
			ttm.tm_total	,
			tc.curr_desc,
			ISNULL(ttn.ret_RegimenDescription,'')   [ret_RegimenDescription],
			ttm.tm_docNumber						[ret_DocNumber]

	FROM	tbTaxMovements								ttm		WITH (NOLOCK)
			INNER JOIN tbTaxName						ttn		WITH (NOLOCK)
			ON	ttn.comp_id			=	ttm.comp_id
			AND	ttn.tax_id			=	ttm.tax_id
			INNER JOIN tbsysCurrency					tc		WITH (NOLOCK)
			ON	tc.curr_id			=	ttm.curr_id

			LEFT JOIN vwsysTaxClassGAN_Retentions		vtcgr		WITH (NOLOCK)
			ON	vtcgr.tax_class		=	ttn.tax_class
			LEFT JOIN vwsysTaxClassIVA_Retentions		vtcir		WITH (NOLOCK)
			ON	vtcir.tax_class		=	ttn.tax_class
			LEFT JOIN vwsysTaxClassIB_Retentions		vtcir2		WITH (NOLOCK)
			ON	vtcir2.tax_class	=	ttn.tax_class
			LEFT JOIN vwsysTaxClassSUSS_Retentions		vtcsr		WITH (NOLOCK)
			ON	vtcsr.tax_class		=	ttn.tax_class
			LEFT JOIN vwsysTaxClassOTHER_Retentions		vtcor		WITH (NOLOCK)
			ON	vtcor.tax_class		=	ttn.tax_class

	WHERE	ttm.comp_id				=	@comp_id
	AND		ttm.ct_transaction		=	@ct_transaction
	AND		ttm.tm_transaction		=	@tm_transaction
--	AND		((vtcgr.tax_class		=	ttn.tax_class	AND @type	=	14) OR	-- GANANCIAS
--			 (vtcir.tax_class		=	ttn.tax_class	AND @type	=	12) OR	-- IVA
--			 (vtcir2.tax_class		=	ttn.tax_class	AND @type	=	13) OR	-- IIBB
--			 (vtcsr.tax_class		=	ttn.tax_class	AND @type	=	16) OR	-- SUSS
--			 (vtcor.tax_class		=	ttn.tax_class	AND @type	=	17))	-- OTRAS





	/*Devolución del total en Letras*/
	DECLARE @total DECIMAL (19,5)
	SELECT	@total = SUM(ttm.tm_total)
	FROM	tbTaxMovements								ttm		WITH (NOLOCK)
			INNER JOIN tbTaxName						ttn		WITH (NOLOCK)
			ON	ttn.comp_id			=	ttm.comp_id
			AND	ttn.tax_id			=	ttm.tax_id
			INNER JOIN tbsysCurrency					tc		WITH (NOLOCK)
			ON	tc.curr_id			=	ttm.curr_id

			LEFT JOIN vwsysTaxClassGAN_Retentions		vtcgr		WITH (NOLOCK)
			ON	vtcgr.tax_class		=	ttn.tax_class
			LEFT JOIN vwsysTaxClassIVA_Retentions		vtcir		WITH (NOLOCK)
			ON	vtcir.tax_class		=	ttn.tax_class
			LEFT JOIN vwsysTaxClassIB_Retentions		vtcir2		WITH (NOLOCK)
			ON	vtcir2.tax_class	=	ttn.tax_class
			LEFT  JOIN vwsysTaxClassSUSS_Retentions		vtcsr		WITH (NOLOCK)
			ON	vtcsr.tax_class		=	ttn.tax_class
			LEFT JOIN vwsysTaxClassOTHER_Retentions		vtcor		WITH (NOLOCK)
			ON	vtcor.tax_class		=	ttn.tax_class

	WHERE	ttm.comp_id				=	@comp_id
	AND		ttm.ct_transaction		=	@ct_transaction
	AND		ttm.tm_transaction		=	@tm_transaction
--	AND		((vtcgr.tax_class		=	ttn.tax_class	AND @type	=	14) OR	-- GANANCIAS
--			 (vtcir.tax_class		=	ttn.tax_class	AND @type	=	12) OR	-- IVA
--			 (vtcir2.tax_class		=	ttn.tax_class	AND @type	=	13) OR	-- IIBB
--			 (vtcsr.tax_class		=	ttn.tax_class	AND @type	=	16) OR	-- SUSS
--			 (vtcor.tax_class		=	ttn.tax_class	AND @type	=	17))	-- OTRAS

	DECLARE @text VARCHAR(8000)
	EXEC spSysTexts_convertNumberToLetters @lang_id, @total, @letters = @text OUTPUT



	/*Datos del Proveedor*/
	DECLARE @supp_id INT

	-- Obtiene el Numero de Comprobante de Retencion desde el Movimiento de Impuesto
	-- Por compatibilidad hacia atras si no esta grabado pone como numero el de la OP
	SELECT @doc_number = IsNull(ttm.tm_docNumber,'')
		FROM tbTaxMovements ttm		WITH (NOLOCK)
		INNER JOIN tbTaxName ttn		WITH (NOLOCK)
			ON	ttn.comp_id = ttm.comp_id AND
				ttn.tax_id	= ttm.tax_id
		INNER JOIN tbTaxName4RetentionRelations ttnrr		WITH (NOLOCK)
			ON	ttnrr.comp_id	= ttm.comp_id	AND
				ttnrr.bra_id	= ttm.bra_id	AND
				ttnrr.tax_id	= ttm.tax_id
		WHERE	ttm.comp_id				=	@comp_id
		AND		ttm.ct_transaction		=	@ct_transaction
		AND		ttm.tm_transaction		=	@tm_transaction



	SELECT	@supp_id	= supp_id,
			@bra_id     = tct.bra_id,
			@doc_number = dbo.fnStrPADL(CONVERT(NVARCHAR,tb.bra_PaymentPointOfSale),4,'0') + '-' + dbo.fnStrPADL(dbo.fnStrAllTrim( tct.ct_docNumber),10,'0')
--			@doc_number =	CASE
--			             	    WHEN @doc_number <> ''	THEN	@doc_number
--			             		ELSE							tct.ct_docNumber
--			             	END

									-- NOOOO, traerlo de la transaccion y si no tiene poner este (POr Compatibilidad hacia atras.  MOS 07-2013)
		FROM	tbCommercialTransactions tct		WITH (NOLOCK)
		INNER JOIN tbBranch tb		WITH (NOLOCK)
			ON	tb.comp_id			= tct.comp_id		AND
				tb.bra_id			= tct.bra_id
		WHERE	tct.comp_id			= @comp_id			AND
				tct.ct_transaction	= @ct_transaction

	/*Datos de la Sucursal + Datos del Proveedor + Tipo de Retencion y Valor escrito del Total*/

	SELECT
		tb.bra_desc				[bra_Desc],
		tb.bra_address			[bra_address],
		tb.bra_zip				[bra_zip],
		tb.bra_address1			[bra_address1],
		tb.bra_taxNumber		[bra_taxNumber],
		ts.supp_name			[supp_name],
		ts.supp_address			[supp_address],
		ts.supp_city			[supp_city],
		ts.supp_taxNumber		[supp_taxNumber],
		tov.optval_desc			[optval_desc],
		@text					[text_value],
		@doc_number				[doc_number],
		tct.ct_date				[bra_processingDate],			--Modificación STL
		tb.bra_MainDesc2		[bra_MainDesc],
		tsBranch.state_desc		[bra_State],
		tsSupplier.state_desc	[Supp_State],
		tb.bra_Payment_retentionManagerSign [bra_Payment_retentionManagerSign]


		FROM dbo.tbBranch tb		WITH (NOLOCK)

		LEFT JOIN dbo.tbSupplier ts		WITH (NOLOCK)
			ON  ts.comp_id			= @comp_id		AND
				ts.supp_id			= @supp_id

		LEFT JOIN tbsysOptionsValues tov		WITH (NOLOCK)
			ON  tov.lang_id			= @lang_id
			AND	tov.optval_id		= @type
			AND	tov.optval_class	= 55

		LEFT JOIN tbCommercialTransactions tct			WITH (NOLOCK)				--Modificación STL
			ON	tct.comp_id			= @comp_id		AND
				tct.ct_transaction	= @ct_transaction

		LEFT JOIN tbsysState tsBranch		WITH (NOLOCK)
			ON tsBranch.state_id = tb.state_id

		LEFT JOIN tbsysState tsSupplier		WITH (NOLOCK)
			ON tsSupplier.state_id = ts.state_id


		WHERE tb.comp_id = @comp_id
		AND	  tb.bra_id  = @bra_id



	exec [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id,@page_id



	-- Retorna la lista de comprobantes que generaron las retenciones.-
	SELECT dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,ta.ct_transaction_Source) [DocumentDescription]
		FROM tbApplication ta		WITH (NOLOCK)
	WHERE	ta.comp_id					= @comp_id AND
			ta.ct_transaction_destiny	= @ct_transaction




END
GO




CREATE PROCEDURE [dbo].[spRMA_BranchTransfers_CancelReception]
(
	@comp_id			INT,
	@rmabt_id			INT,
	@user_id_toCancel	INT
)
AS

	SET NOCOUNT ON
		BEGIN

			-- ----------------------------------------
			-- TESTING
			-- ----------------------------------------
			/*
				DECLARE
					@comp_id			INT,
					@rmabt_id			INT,
					@user_id_toCancel	INT
				SELECT
					@comp_id			= 1,
					@rmabt_id			= 11,
					@user_id_toCancel	= 1
			*/
			-- ----------------------------------------

			--VARIABLES DE TRABAJO
			DECLARE
				@lrmah_id		INT,
				@isReceived		BIT,
				@bra_id_origen	INT
			--RECUPERAMOS LOS VALORES SIGUIENTES
			-- RMAH_ID PARA MODIFICAR EN CASO DE ESTAR RECIBIDO LA HEADER Y DETAIL
			-- IS RECEIVED PARA SABER SI DEBEMOS O NO ACTUALIZAR DICHAS TABLAS
			-- Y EL BRA_ID QUE ORIGINALMENTE POSEIA EL RMA
			SELECT
				@lrmah_id		= ISNULL(trbt.rmah_id,'False'),
				@isReceived		= trbt.rmabt_isReceived,
				@bra_id_origen	= trbt.bra_id_from

			FROM tbRMA_BranchTransfers			trbt
			WHERE	trbt.comp_id = @comp_id		AND
					trbt.rmabt_id = @rmabt_id


			UPDATE tbRMA_BranchTransfers
			SET
				rmabt_isEnvied			= 'False',
				--rmabt_isReceived		= 'False',
				rmabt_isReceived		= NULL,
				bra_id_to				= NULL,
				user_id_to				= NULL,
				rmabr_toNote			= NULL,
				user_id_toCancel		= @user_id_toCancel,
				rmabt_toCancelDate		= GETDATE()
			WHERE	comp_id		= @comp_id	AND
					rmabt_id	= @rmabt_id


			IF @isReceived = 'True'
				BEGIN

					--ACTUALIZAMOS LA SUCURSAL PRIMERO EN EL DETALLE DEL RMA
					UPDATE tbRMA_Detail
					SET
						bra_id		= @bra_id_origen
					WHERE	comp_id = @comp_id	AND
							rmah_id = @lrmah_id

					--Y LUEGO LO ACTUALIZAMOS EN LA HEADER
					UPDATE tbRMA_Header
					SET
						bra_id		= @bra_id_origen
					WHERE	comp_id = @comp_id	AND
							rmah_id = @lrmah_id

				END



		END

GO



CREATE PROCEDURE spRMA_BranchTransfers_CanResend
(
	@comp_id	INT,
	@rmah_id	INT
)
AS
	SET NOCOUNT ON
		BEGIN

			SELECT
				TOP 1
					trbt.rmabt_id
			FROM tbRMA_BranchTransfers					trbt
			WHERE	trbt.comp_id = @comp_id				AND
					trbt.rmah_id = @rmah_id

			ORDER BY trbt.rmabt_id DESC

		END


GO



CREATE PROCEDURE spRMA_BranchTransfers_DeleteData
(
	@comp_id	INT,
	@rmabt_id	INT
)
AS
	SET NOCOUNT ON
		BEGIN

			DELETE FROM tbRMA_BranchTransfers
			WHERE	comp_id		= @comp_id		AND
					rmabt_id	= @rmabt_id

		END
GO



