CREATE PROCEDURE [dbo].[spRMA_BranchTransfers_GetDataByFilters]
(
	@comp_id		INT,
	@bra_id			INT,
	@CustomerGuid	UNIQUEIDENTIFIER,
	@ItemGuid		UNIQUEIDENTIFIER,
	@datefrom		DATETIME,
	@dateto			DATETIME,
	@status			INT,
	@RMA_Status		INT
)
AS

	SET NOCOUNT ON
		BEGIN
			SET DATEFORMAT 'YMD'
			-- ------------------------------------------------------------------------
			-- TESTING
			-- ------------------------------------------------------------------------
			/*
				DECLARE
					@comp_id		INT,
					@bra_id			INT,
					@CustomerGuid	UNIQUEIDENTIFIER,
					@ItemGuid		UNIQUEIDENTIFIER,
					@datefrom		DATETIME,
					@dateto			DATETIME,
					@status			INT,
					@RMA_Status		INT

				SELECT
					@comp_id		= 1,
					@bra_id			= 1,
					@CustomerGuid	= '8B2E387B-93AD-4746-98F7-4A9E553187D0',
					@ItemGuid		= '8F3979B9-D398-4A33-9DC6-DC356345881A',
					@datefrom		= '2000-01-01',
					@dateto			= '2024-08-31',
					@status			= -1,
					@RMA_Status		= -1
			*/
			-- ------------------------------------------------------------------------

			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			-- -----------------------------------------------------------------------------

			-- -----------------------------------------------------------------------------
			-- Tabla para los clientes seleccionados
			-- -----------------------------------------------------------------------------
			DECLARE @lCustomerGuid AS UNIQUEIDENTIFIER
			SET @lCustomerGuid = CONVERT(UNIQUEIDENTIFIER,@CustomerGuid)


			DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)

			INSERT INTO @tblComplexFilter_Customer(cust_id)
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lCustomerGuid     AND
						tcf.sl_selected = 'True'

			IF @@ROWCOUNT = 0
				BEGIN
					INSERT INTO @tblComplexFilter_Customer(cust_id)
					SELECT
						tc.cust_id
						FROM tbCustomer tc	WITH (NOLOCK)
						WHERE tc.comp_id = @comp_id			-- MOS 08-2024: y la compañia para queien mierda es ?????
				END
			-- -----------------------------------------------------------------------------


			-- -----------------------------------------------------------------------------
			-- Tabla para los artículos seleccionados
			-- -----------------------------------------------------------------------------
			DECLARE @bolAllItems AS BIT = 'False'
			DECLARE @lItemGuid AS UNIQUEIDENTIFIER
			SET		@lItemGuid = CONVERT(UNIQUEIDENTIFIER,@ItemGuid)

			DECLARE @tblComplexFilter_AllItems TABLE (item_id INT PRIMARY KEY)

			INSERT INTO @tblComplexFilter_AllItems(item_id)
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf	WITH (NOLOCK)
				WHERE (tcf.sl_guid = @lItemGuid)    AND
						tcf.sl_selected = 'True'
			IF @@ROWCOUNT = 0
				BEGIN
					SET @bolAllItems = 'True'
					INSERT INTO @tblComplexFilter_AllItems(item_id)		-- MOS 08-2024: cualquier MIERDAAAAAAAAAAAAAAAAAAAAAAAAAAAA, estaba con tbCUSTOMER, QUE MIERDA PROBASSSDSS?????????
						SELECT	Ti.item_id
							FROM tbItem TI		WITH (NOLOCK)
							WHERE TI.comp_id = @comp_id
				END

			-- QUIEN CUERNOS TE DIJO QUE ESTO SE HACE ASI????????????  y si DESSELECCIONANN TODOS Y DESPUES NO SE LISTA NADA ?????????
			-- en CLIENTES, ARRIBA estaba IGUALK, o sea MALLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLL
			-- y despues los clientes dicen que es todo mierda que anda a medias y TIENEN RAZONNNNNNNNNN NNNN
			--IF (SELECT COUNT(*) FROM tbComplexFilter tcf WHERE tcf.sl_guid = @ItemGuid) > 0
			--	BEGIN
			--		INSERT INTO @tblComplexFilter_AllItems(item_id)
			--		SELECT tcf.sl_id
			--			FROM tbComplexFilter tcf	WITH (NOLOCK)
			--			WHERE (tcf.sl_guid = @lItemGuid)    AND
			--				   tcf.sl_selected = 'True'
			--	END
			--ELSE
			--	BEGIN
			--		SET @bolAllItems = 'True'
			--		INSERT INTO @tblComplexFilter_AllItems(item_id)		-- MOS 08-2024: cualquier MIERDAAAAAAAAAAAAAAAAAAAAAAAAAAAA, estaba con tbCUSTOMER, QUE MIERDA PROBASSSDSS?????????
			--			SELECT	Ti.item_id
			--				FROM tbItem TI		WITH (NOLOCK)
			--				WHERE TI.comp_id = @comp_id
			--	END

			-- -----------------------------------------------------------------------------


			SELECT	DISTINCT	-- MOS 08-2024: agregue el distinct x el JOIN de abajo
				ISNULL(trbt.rmabt_isEnvied,'False')			[ ], --ENVIAR
				ISNULL(trbt.rmabt_isReceived,'False')		[ ], --BORRAR ENVÍO SIN RECIBIR
				ISNULL(trbt.bra_id_from,'')					[ ], --RECIBIR
				ISNULL(trbt.bra_id_to,'')					[ ], --CANCELAR RECEPCIÓN
				trh.bra_id									[ ], --REIMPRIMIR REMITO

				tc.cust_name								[cust_name],

				trh.rmah_cd,
				ISNULL(trh.rmah_note1,'')					[rmah_note1],
				ISNULL(trh.rmah_note2,'')					[rmah_note2],

				CASE
					WHEN trbt.comp_id IS NULL THEN
						''
				ELSE
					ISNULL(tu2.user_lastname,'') + ',' +
					ISNULL(tu2.user_firstname,'')
				END											[user_name_sender],

				ISNULL(tb.bra_desc,'')						[bra_origin],

				ISNULL(trbt.rmabr_fromNote,'')				[rmabr_fromNote],

				CASE
					WHEN trbt.comp_id IS NULL THEN
						''
				ELSE
					ISNULL(tu3.user_lastname,'') + ',' +
					ISNULL(tu3.user_firstname,'')
				END											[user_name_receiver],

				ISNULL(
						CASE
							WHEN trbt.comp_id IS NULL THEN
								''
						ELSE
								trbt.rmabt_toCD
						END, ''
					   )									[rmabt_toCD],

				ISNULL(tb2.bra_desc,'')						[bra_destiny],



				ISNULL(trbt.rmabr_toNote,'')				[rmabr_toNote],


				CASE
					WHEN trbt.comp_id IS NULL THEN
						''
				ELSE
					CASE WHEN trbt.user_id_toCancel IS NULL THEN
						''
					ELSE
						ISNULL(tu.user_lastname,'') + ',' +
						ISNULL(tu.user_firstname,'')
					END
				END											[user_name_Cancel],

				CASE
					WHEN trbt.comp_id IS NULL THEN
						''
				ELSE
						trbt.rmabt_toCancelDate
				END											[rmabt_toCancelDate],





				-- NO PONER NADA DESPUÉS DE ESTO

				CASE
					WHEN ISNULL(trbt.rmabt_disableCancell,'False') = 'False' THEN ' '
					ELSE 'x'
				END											[rmabt_disableCancell],



				--CONVERT(BIT,ISNULL(trbt.rmabt_disableCancell,'False'))
				--											[rmabt_disableCancell], --DISABLECANCELL

				ISNULL((SELECT
					TOP 1 isnull(ti.item_code + ' - ' + ti.item_desc ,'')
					FROM tbRMA_Detail trd
						INNER JOIN tbItem			ti	WITH(NOLOCK)
							ON	ti.comp_id = trd.comp_id AND
								ti.item_id = trd.item_id
					WHERE	trd.comp_id = @comp_id		AND
							trd.rmah_id = trh.rmah_id ),'')				[Item_desc],


				CASE WHEN trbt.comp_id IS NULL	THEN
					CONVERT(VARCHAR,trh.rmah_id)
				ELSE
					CONVERT(VARCHAR,trh.rmah_id) + '-' +
					CONVERT(VARCHAR,trbt.rmabt_id)
				END
															[ID]
			FROM tbRMA_Header							trh		WITH(NOLOCK)

			INNER JOIN tbRMA_Detail					 AS trd30	WITH (NOLOCK)		-- MOS 08-2024: todo esto esta MAL, NO filtra x artículos ni por RMA que NO este procesado.
				ON	trd30.comp_id	= trh.comp_id AND
					trd30.rmah_id	= trh.rmah_id

			INNER JOIN @tblComplexFilter_Customer	tmpCust
				ON	tmpCust.cust_id = trh.cust_id

			INNER JOIN tbCustomer					tc		WITH(NOLOCK)
				ON	tc.comp_id		= @comp_id		AND
					tc.cust_id		= tmpcust.cust_id

			LEFT JOIN @tblComplexFilter_AllItems	tmpI
				ON tmpI.item_id		= trd30.item_id


			LEFT JOIN tbRMA_BranchTransfers			trbt	WITH(NOLOCK)
				ON	trbt.comp_id	= trh.comp_id	AND
					trbt.rmah_id	= trh.rmah_id	--AND
					--trbt.rmabt_isEnvied = 'False'

			--USUARIO QUE CANCELA LA RECEPCION
			LEFT JOIN tbUser						tu	WITH(NOLOCK)
				ON	tu.[user_id]	= trbt.user_id_toCancel

			--USUARIO QUE ENVIA
			LEFT JOIN tbUser						tu2	WITH(NOLOCK)
				ON	tu2.[user_id]	= trbt.user_id_from

			--USUARIO QUE RECIBIO
			LEFT JOIN tbUser						tu3	WITH(NOLOCK)
				ON	tu3.[user_id]	= trbt.user_id_to

			--SUCURSAL DE ORIGEN
			LEFT JOIN tbBranch						tb	WITH(NOLOCK)
				ON	tb.comp_id		= trbt.comp_id	AND
					tb.bra_id		= trbt.bra_id_from

			--SUCURSAL DE DESTINO
			LEFT JOIN tbBranch						tb2	WITH(NOLOCK)
				ON	tb2.comp_id		= trbt.comp_id	AND
					tb2.bra_id		= trbt.bra_id_to


			WHERE	trh.comp_id = @comp_id																AND
					trh.rmah_cd BETWEEN @datefrom AND @dateto											AND
					(
						tmpI.item_id = trd30.item_id
						OR
						@bolAllItems = 'True'
					)																					AND
					--(@bra_id = -1	OR trh.bra_id = @bra_id)											AND
					--ESTADOS DE RMA
					(
						@RMA_Status = -1 OR
						trh.rmah_id IN (SELECT
											trd.rmah_id
										FROM tbRMA_Detail trd	WITH(NOLOCK)
										WHERE	trd.comp_id = @comp_id AND
												trd.rmas_id = @RMA_Status)
					)																					AND
					(
						--TODOS
						(@status = -1)																							OR
						--RECIBIDOS
						(@status = 1 AND trbt.rmabt_isReceived						= 'True'  AND trbt.bra_id_to	= @bra_id)	OR
						--ENVIADOS PENDIENTE DE RECEPCIÓN
						(@status = 2	AND ISNULL(trbt.rmabt_isReceived,'False')	= 'False' AND trbt.bra_id_from	= @bra_id)	OR
						--ENVIADOS RECIBIDOS
						(@status = 3 AND trbt.rmabt_isReceived						= 'True'  AND trbt.bra_id_from	= @bra_id)	OR
						--NO ENVIADOS
						(@status = 4 AND trbt.comp_id IS NULL)																	OR
						--PENDIENTES DE RECEPCIÓN
						(@status = 5	AND ISNULL(trbt.rmabt_isReceived,'False')	= 'False' AND trbt.bra_id_to	= @bra_id)
					)
			ORDER BY trh.rmah_cd ASC

		END








GO




CREATE PROCEDURE [dbo].[spRMA_BranchTransfers_GetReport]
(
	@comp_id		INT,
	@lang_id		INT,
	@page_id		INT,
	@rmabt_id		INT,
	@rmah_id		INT,
	@intBranch4Lang INT
)
AS

	SET NOCOUNT ON
		BEGIN

			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			SET LOCK_TIMEOUT 500
			SET DEADLOCK_PRIORITY LOW
			-- -----------------------------------------------------------------------------

			-- ------------------------------------------------
			-- TESTING
			-- ------------------------------------------------
			/*
				DECLARE
					@comp_id		INT,
					@lang_id		INT,
					@page_id		INT,
					@rmabt_id		INT,
					@rmah_id		INT,
					@intBranch4Lang INT
				SELECT
					@comp_id		= 1,
					@lang_id		= 2,
					@page_id		= 100953,
					@rmabt_id		= 5,
					@rmah_id		= 1001,
					@intBranch4Lang = 2
			*/
			-- ------------------------------------------------




			SELECT
				--SUCURSAL DE ORIGEN
				tb.bra_desc,
				tc2.country_desc,
				ts.state_desc,
				tb.bra_address,
				tb.bra_zip,

				--DATOS DEL CLIENTE
				tc.cust_name,
				tc4.country_desc							[country_desc_cust],
				ts3.state_desc								[state_desc_cust],
				tc.cust_address								[cust_address_cust],
				tc.cust_city								[cust_city_to],
				tc.cust_zip									[cust_zip_to],

				--SUCURSAL DE DESTINO
				tb2.bra_desc								[bra_desc_to],
				tc3.country_desc							[country_desc,to],
				ts2.state_desc								[state_desc_to],
				tb2.bra_address								[bra_address_to],
				tb2.bra_zip									[bra_zip_to],

				--DATOS ADICIONALES PARA DESCRIPCIÓN DEL REMITO INTERNO
				'#' + ' ' + CONVERT(VARCHAR, trbt.rmabt_id)	[Comprobante],
				'#' + ' ' + CONVERT(VARCHAR, trh.rmah_id)	[rmah_id],

				--FECHAS DE EGRESO E INGRESO A LA SUCURSAL
				trbt.rmabt_fromCD,
				trbt.rmabt_toCD


			FROM tbRMA_BranchTransfers						trbt	WITH (NOLOCK)
				INNER JOIN tbRMA_Header						trh		WITH (NOLOCK)
					ON	trh.comp_id		= trbt.comp_id		AND
						trh.rmah_id		= trbt.rmah_id

				INNER JOIN tbCustomer						tc		WITH (NOLOCK)
					ON	tc.comp_id		= trh.comp_id		AND
						tc.cust_id		= trh.cust_id

				INNER JOIN tbsysCountry						tc4		WITH (NOLOCK)
					ON	tc4.country_id	= tc.country_id

				INNER JOIN tbsysState						ts3		WITH (NOLOCK)
					ON	ts3.country_id	= tc.country_id		AND
						ts3.state_id	= tc.state_id

				INNER JOIN tbBranch							tb		WITH (NOLOCK)
					ON	tb.comp_id		= trbt.comp_id		AND
						tb.bra_id		= trbt.bra_id_from

				INNER JOIN tbsysCountry						tc2		WITH (NOLOCK)
					ON	tc2.country_id	= tb.country_id

				INNER JOIN tbsysState						ts		WITH (NOLOCK)
					ON	ts.country_id	= tb.country_id		AND
						ts.state_id		= tb.state_id

				INNER JOIN tbBranch							tb2		WITH (NOLOCK)
					ON	tb2.comp_id		= trbt.comp_id		AND
						tb2.bra_id		= trbt.bra_id_to

				INNER JOIN tbsysCountry						tc3		WITH (NOLOCK)
					ON  tc3.country_id	= tb2.country_id

				INNER JOIN tbsysState						ts2		WITH (NOLOCK)
					ON  ts2.country_id	= tb2.country_id	AND
						ts2.state_id	= tb2.state_id

			WHERE	trbt.comp_id		= @comp_id			AND
					trbt.rmabt_id		= @rmabt_id



			EXEC [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


			--DATOS DEL RMA (TODOS LOS ARTÍCULOS Y EN CASO DE TENER SUS NÚMEROS DE SERIE Y EL ESTADO DE CADA ITEM EN PARTICULAR
			SELECT
				ti.item_code,
				ISNULL(tis.is_serial,'')			[is_serial],
				ti.item_desc,
				trs.rmas_desc

			FROM tbRMA_Detail						trd		WITH (NOLOCK)
				INNER JOIN tbItem					ti		WITH (NOLOCK)
					ON	ti.comp_id	= trd.comp_id	AND
						ti.item_id	= trd.item_id
				LEFT JOIN tbItemSerials				tis		WITH (NOLOCK)
					ON	tis.comp_id = trd.comp_id	AND
						tis.is_id	= trd.is_id
				LEFT JOIN tbRMA_Status				trs		WITH (NOLOCK)
					ON	trs.comp_id = trd.comp_id	AND
						trs.rmas_id = trd.rmas_id

			WHERE	trd.comp_id = @comp_id			AND
					trd.rmah_id = @rmah_id

		END
GO



CREATE PROCEDURE [dbo].[spRMA_BranchTransfers_InsertData]
(
	@comp_id		INT,
	@rmah_id		INT,
	@bra_id_from	INT,
	@user_id_from	INT,
	@fromNote		VARCHAR(500),
	@bra_id_to		INT
)
AS
	SET NOCOUNT ON
		BEGIN
			SET DATEFORMAT 'YMD'
			-- -------------------------------------------------
			-- TESTING
			-- -------------------------------------------------
			/*
				DECLARE
					@comp_id		INT,
					@rmah_id		INT,
					@bra_id_from	INT,
					@user_id_from	INT,
					@fromNote		VARCHAR(500)
				SELECT
					@comp_id		= 1,
					@rmah_id		= 2,
					@bra_id_from	= 1,
					@user_id_from	= 119,
					@fromNote		= 'Probando la Notita!!!'
			*/
			-- -------------------------------------------------



			-- MOS 08-2024: como esto esta MAL, y SOLO se debe poder transferir RMA NO PROCESADOS, lo verifico aca y si tiene algun item procesado NO hago nada.  Lo agrego en la AYUDA de la pagina.
			IF EXISTS(
						SELECT TOP 1 1
							FROM tbRMA_Detail AS trd	WITH (NOLOCK)
							WHERE	trd.comp_id = @comp_id AND
									trd.rmah_id = @rmah_id AND
									trd.srpt_id <> 1
					 )
				BEGIN
					SELECT -1
					RETURN
				END






			--SI EXISTEN REGISTROS ANTERIORES, PONEMOS ESTE CAMPO EN TRUE, PARA QUE NO PERMITA CANCELAR LOS REGISTROS YA INSERTADOS
			--QUE TENGAN OTRO MOVIMIENTO MÁS RECIENTE
			UPDATE tbRMA_BranchTransfers
			SET
				rmabt_disableCancell = 'True'
			WHERE	comp_id = @comp_id AND
					rmah_id = @rmah_id



			INSERT INTO tbRMA_BranchTransfers
			(
				comp_id,
				rmah_id,
				rmabt_isEnvied,
				bra_id_from,
				user_id_from,
				rmabt_fromCD,
				rmabr_fromNote,
				rmabt_isReceived,
				bra_id_to,
				user_id_to,
				rmabt_toCD,
				rmabr_toNote,
				user_id_toCancel,
				rmabt_toCancelDate,
				rmabt_disableCancell
			)
			VALUES
			(
				@comp_id,
				@rmah_id,
				'True',
				@bra_id_from,
				@user_id_from,
				GETDATE(),
				@fromNote,
				'False',
				@bra_id_to,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				'False'
			)

			SELECT @@IDENTITY

		END


GO



CREATE PROCEDURE spRMA_BranchTransfers_IsAvailable4RMA
(
	@comp_id	INT,
	@rmah_id	INT
)
AS
	SET NOCOUNT ON
