					  FROM tbRMA_BranchTransfers					trbt
					  WHERE		trbt.comp_id			= @comp_id	AND
								trbt.rmah_id			= @rmah_id	AND
								trbt.rmabt_isEnvied		= 'True'	AND
								trbt.rmabt_isReceived	= 'False')
				BEGIN
