				END

			ELSE
				BEGIN
					SELECT 'True'
				END

		END




GO



CREATE PROCEDURE [dbo].[spRMA_BranchTransfers_UpdateData]
(
	@comp_id	INT,
	@rmabt_id	INT,
	@isReceived	BIT,
	@bra_id_To	INT,
	@user_id_To	INT,
	@ToNote		VARCHAR(500)
)
AS
	SET NOCOUNT ON
		BEGIN
			-- ---------------------------------------------
			-- TESTING
			-- ---------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@rmah_id	INT,
					@isReceived	BIT,
					@bra_id_To	INT,
					@user_id_To	INT,
					@ToNote		VARCHAR(500)
				SELECT
					@comp_id	= 1,
					@rmah_id	= 1,
					@isReceived	= 'True',
					@bra_id_To	= 1,
					@user_id_To	= 1,
					@ToNote		= 'LO RECIBI ANGUILA'
			*/
			-- ---------------------------------------------

			UPDATE tbRMA_BranchTransfers
			SET
				rmabt_isReceived	= @isReceived,
				bra_id_to			= @bra_id_To,
				user_id_to			= @user_id_To,
				rmabt_toCD			= GETDATE(),
				rmabr_toNote		= @ToNote
			WHERE	comp_id			= @comp_id AND
					rmabt_id		= @rmabt_id

			--VARIABLE DE TRABAJO
			DECLARE
				@lrmah_id	INT
			--RECUPERAMOS EL RMAH_ID DE LA TABLA
			SELECT
				@lrmah_id = trbt.rmah_id
			FROM tbRMA_BranchTransfers			trbt	WITH (NOLOCK)
			WHERE	trbt.comp_id	= @comp_id	AND
					trbt.rmabt_id	= @rmabt_id

			--ACTUALIZAMOS LA SUCURSAL PRIMERO EN EL DETALLE DEL RMA
			UPDATE tbRMA_Detail
			SET
				bra_id		= @bra_id_To
			WHERE	comp_id = @comp_id	AND
					rmah_id = @lrmah_id

			--Y LUEGO LO ACTUALIZAMOS EN LA HEADER
			UPDATE tbRMA_Header
			SET
				bra_id		= @bra_id_To
			WHERE	comp_id = @comp_id	AND
					rmah_id = @lrmah_id



		END

GO



