CREATE PROCEDURE spRMA_Customer_HasPurchasedItem
(
	@comp_id	INT,
	@cust_id	INT,
	@item_id	INT
)
AS
	SET NOCOUNT ON
		BEGIN
			-- -----------------------------
			-- TESTING
			-- -----------------------------
			/*
				DECLARE
					@comp_id	INT,
					@cust_id	INT,
					@item_id	INT
				SELECT
					@comp_id	= 1,
					@cust_id	= 24294,
					@item_id	= 492
			*/
			-- -----------------------------


			IF (SELECT
					COUNT(*)
				FROM tbItemTransactions								tit
					INNER JOIN tbCommercialTransactions				tct
					ON	tct.comp_id			= tit.comp_id			AND
						tct.ct_transaction	= tit.ct_transaction
				WHERE	tit.comp_id = @comp_id						AND
						tct.cust_id = @cust_id						AND
						tit.item_id	= @item_id) > 0
				BEGIN
					SELECT 'True'
				END
			ELSE
				BEGIN
					SELECT 'False'
				END
		END

GO







CREATE  PROCEDURE [dbo].[spRMA_deleteData]
(
	@comp_id			INT,
	@rmah_id			INT,
	@rmadt_guid			uniqueidentifier
)
as

BEGIN

	set nocount off

	-- -------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------
	/*
	DECLARE			@comp_id			INT,
					@rmah_id			INT,
					@rmadt_guid			uniqueidentifier

	SELECT			@comp_id			= 1,
					@rmah_id			= 238,
					@rmadt_guid			= '9f0fc0c6-46f8-4666-9760-d6410aef92bb'
	*/
	-- -------------------------------------------------------------------

		--SAVE TRANSACTION traPROTECT
		--BEGIN TRANSACTION
		DECLARE @intTranCounter AS INT = @@TRANCOUNT;
		IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT		-- MOS 06-2020
		BEGIN TRY


			IF	(
					(SELECT		COUNT( * )
						FROM	tbRMA_Detail_Tmp trdt
						WHERE	trdt.rmadt_guid = @rmadt_guid)
					=
					(SELECT		COUNT( * )
						FROM	tbRMA_Detail_Tmp trdt
						WHERE	trdt.rmadt_guid = @rmadt_guid
						AND		trdt.srpt_id	= 1)
				)

			BEGIN


					EXEC spRMADetailTmp_deleteAllData	@rmadt_guid


					--actualizo saleorderdetail para aquellos registros que están
					-- relacionados a los rmadetail que se van a eliminar
					UPDATE	tbsaleorderdetail
					SET		rmah_id = NULL,
							rmad_id = NULL
					WHERE	comp_id = comp_id
					AND		rmah_id = @rmah_id
					AND		rmad_id IN (SELECT	rmad_id FROM tbRMA_Detail trd
										WHERE	trd.comp_id = @comp_id
										AND		trd.rmah_id = @rmah_id )


					EXEC dbo.spRMADetail_deleteAllData	@comp_id ,@rmah_id


					EXEC spRMAHeader_deleteData			@rmah_id

			END


		END TRY
		BEGIN CATCH
			--ROLLBACK TRANSACTION traPROTECT
			IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT		-- MOS 06-2020
			DECLARE @ErrorMessage   NVARCHAR(4000)
			DECLARE @ErrorSeverity  INT
			DECLARE @ErrorState     INT
			SELECT  @ErrorMessage    = ERROR_MESSAGE(),
					@ErrorSeverity   = ERROR_SEVERITY(),
					@ErrorState      = ERROR_STATE()
			IF      @ErrorState      = 0 SET @ErrorState = 1
			RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

		END CATCH
		--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT

END
GO

