CREATE PROCEDURE spRMA_Deliver2SupplierDetail_GetDataByFilters
(
	@comp_id				INT,
	@rmast_id				INT,
	@user_id_4Return		INT,
	@isReturned				INT,
	@dateFromEstimated		DATETIME,
	@dateToEstimated		DATETIME,
	@dateFromReturn			DATETIME,
	@dateToReturn			DATETIME
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- ---------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@rmast_id				INT,
				@user_id_4Return		INT,
				@isReturned				INT,
				@dateFromEstimated		DATETIME,
				@dateToEstimated		DATETIME,
				@dateFromReturn			DATETIME,
				@dateToReturn			DATETIME
		*/
		-- ---------------------------------------------------------

		SELECT
			trdsd.comp_id,
			trdsd.rmastd_id,
			trdsd.rmah_id,
			trdsd.rmad_id,
			trdsd.rmastd_note,
			trdsd.rmastd_estimatedReturnDate,
			ISNULL(trdsd.rmastd_isReturned,'False')											[rmastd_isReturned],
			ISNULL(tu.user_lastname + ',' + tu.user_firstname, '')							[User],
			trdsd.rmastd_returnDate
		FROM tbRMA_Deliver2SupplierDetail													trdsd
			LEFT JOIN tbUser																tu
				ON	tu.[user_id] = trdsd.user_id_4Return
		WHERE	trdsd.comp_id			= @comp_id													AND
				trdsd.rmast_id			= @rmast_id													AND
				(@user_id_4Return = -1	OR trdsd.user_id_4Return = @user_id_4Return)				AND
				(@isReturned = -1		OR trdsd.rmastd_isReturned = @isReturned)					AND
				trdsd.rmastd_estimatedReturnDate BETWEEN @dateFromEstimated AND @dateToEstimated	AND
				trdsd.rmastd_returnDate			 BETWEEN @dateFromReturn	AND @dateToReturn


	END



GO


