CREATE PROCEDURE spRMA_Deliver2SupplierHeader_GetDataByFilters
(
	@comp_id	INT,
	@bra_id		INT,
	@user_id	INT,
	@isEnvied	INT,
	@SuppGuid	UNIQUEIDENTIFIER
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@user_id	INT,
				@isEnvied	INT,
				@SuppGuid	UNIQUEIDENTIFIER

			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@user_id	= 119,
				@isEnvied	= 1,
				@SuppGuid	= '25892e17-80f6-415f-9c65-7395632f0223'
		*/
		-- -------------------------------------------------------------------

		SELECT
			trdsh.comp_id,
			trdsh.rmast_cd,
			tu.user_lastname + ',' + tu.user_firstname	[User],
			trdsh.rmast_note,
			ts.supp_name,
			tb.bra_desc,
			trdsh.rmast_isEnvied,
			trdsh.rmast_id								[ID]
		FROM tbRMA_Deliver2SupplierHeader				trdsh
			INNER JOIN tbSupplier						ts
				ON	ts.comp_id	= trdsh.comp_id			AND
					ts.supp_id	= trdsh.supp_id
			INNER JOIN tbUser							tu
				ON tu.[user_id] = trdsh.[user_id]
			INNER JOIN tbBranch							tb
				ON	tb.comp_id	= trdsh.comp_id			AND
					tb.bra_id	= trdsh.bra_id
		WHERE	trdsh.comp_id = @comp_id							AND
				(@bra_id = -1 OR trdsh.bra_id = @bra_id)			AND
				(@isEnvied = -1 OR trdsh.rmast_isEnvied = @isEnvied)

	END

GO


