CREATE procedure [dbo].[spRMA_Detail_AddItems_GetDataByFilters]
(
	@comp_id	int,
	@bra_id		INT,
	@rmah_id	int,
	@rmad_id	INT
)

AS

BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	-- --------------------------------------------
	-- TESTING
	-- --------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@bra_id		INT,
			@rmah_id	INT,
			@rmad_id	INT

		SELECT
			@comp_id	= 1,
			@bra_id		= 1,
			@rmah_id	= 1061,
			@rmad_id	= 84645
	*/
	-- --------------------------------------------

	DECLARE	@bra_prli_id4RMAAdditionalItems	INT

	SELECT
		@bra_prli_id4RMAAdditionalItems = tb.bra_RMA_prli_id4AdditionalItems
		FROM tbBranch					tb
		WHERE	tb.comp_id	= @comp_id	AND
				tb.bra_id	= @bra_id


	SELECT
		' '	[ ],
		' '	[ ],
		tc.cust_name,
		ti.item_desc,
		trdai.rmaa_qty,
		tpli.prli_price,
		tc2.curr_symbol,
		dbo.fnGetAStock(@comp_id,trdai.stor_id, trdai.item_id, 99999999)	[STKAvailable],
		trdai.rmaa_id	[ID]
		FROM tbRMA_Detail_AddItems			trdai
		INNER JOIN tbItem				ti
			ON	ti.comp_id = trdai.comp_id  AND
				ti.item_id = trdai.item_id
		INNER JOIN tbRMA_Header			trh
			ON	trh.comp_id = trdai.comp_id	AND
				trh.rmah_id = trdai.rmah_id
		INNER JOIN tbCustomer			tc
			ON	tc.comp_id = trh.comp_id	AND
				tc.cust_id = trh.cust_id
		LEFT JOIN tbPriceListItems		tpli
			ON	tpli.comp_id = ti.comp_id	AND
				tpli.item_id = ti.item_id	AND
				tpli.prli_id = @bra_prli_id4RMAAdditionalItems
		LEFT JOIN tbsysCurrency			tc2
			ON tc2.curr_id	 = tpli.curr_id
		WHERE	trdai.comp_id	= @comp_id		AND
				trh.bra_id		= @bra_id		AND
				trdai.rmah_id	= @rmah_id		AND
				(
					@rmad_id		= -1		OR
					trdai.rmad_id	= @rmad_id
				)
	ORDER BY trdai.rmaa_order

end
GO






CREATE procedure [dbo].[spRMA_Detail_AddItems_GetDataById]
(
	@comp_id	int,
	@rmaa_id	int
)

as set NOCOUNT ON

begin

	select
		' '	[ ],
		' '	[ ],
		tc.cust_name,
		ti.item_desc,
		ti.item_code,
		trdai.rmaa_qty,
		trdai.rmah_id,
		trdai.rmad_id,
		trdai.stor_id,
		trdai.item_id,
		isnull(trdai.is_id,0)	[is_id],
		trdai.rmaa_id			[ID]

	from tbRMA_Detail_AddItems			trdai

		inner join tbItem				ti
		on	ti.comp_id = trdai.comp_id
		AND ti.item_id = trdai.item_id

		inner join tbRMA_Header			trh
		on	trh.comp_id = trdai.comp_id
		--and trh.bra_id	= trdai.bra_id
		and trh.rmah_id = trdai.rmah_id

		inner join tbCustomer			tc
		on	tc.comp_id = trh.comp_id
		AND tc.cust_id = trh.cust_id

--		left join tbItemSerials			tis
--		on	tis.comp_id = trdai.comp_id
--		AND tis.is_id	= trdai.is_id

	where trdai.comp_id = @comp_id
	and trdai.rmaa_id	= @rmaa_id

end
GO



CREATE procedure [dbo].[spRMA_Detail_AddItems_HasStock]
(
	@comp_id	int,
	@lang_id	int,
	@bra_id		int,
	@prof_id	int,
	@user_id	int,
	@stor_id	int,
	@item_id	INT
)

as


BEGIN

	set NOCOUNT on

	-- ------------------------------------
	-- Testing
	-- ------------------------------------
	/*
		declare
			@comp_id	int,
			@stor_id	int,
			@item_id	INT,
			@lang_id	int,
			@bra_id		int,
			@prof_id	int,
			@user_id	int

		select
			@comp_id	= 1,
			@stor_id	= 687,
			@item_id	= 15519,
			@lang_id	= 2,
			@bra_id		= 1,
			@prof_id	= 1,
			@user_id	= 1
	*/
	-- ------------------------------------


	IF EXISTS(
				SELECT 1
					FROM tbItemAssociation tia			WITH (NOLOCK)
					WHERE	tia.comp_id = @comp_id AND
							tia.item_id = @item_id
			)
		BEGIN
			SELECT MIN(dbo.fnGetAStock(tia.comp_id, @stor_id, tia.item_id_1,999999999)) [Stock]
				FROM tbItemAssociation tia				WITH (NOLOCK)
				WHERE	tia.comp_id = @comp_id AND
						tia.item_id = @item_id
		END
	ELSE
		BEGIN
			select
				dbo.fnGetAStock(@comp_id, @stor_id, @item_id,999999999) [Stock]
		END




END
GO





CREATE PROCEDURE [dbo].[spRMA_Detail_AddItems_InsertData]
(
	@comp_id		int,
	@bra_id			int,
	@rmah_id		INT,
	@rmad_id		INT,
	@stor_id		INT,
	@item_id		INT,
	@rmaa_qty		int,
	@is_id			int,
	@return_value	INT			OUTPUT
)

AS

BEGIN

	SET	NOCOUNT ON


	DECLARE @intOrder AS INT
	SET		@intOrder = 0

	DECLARE
		@lis_id AS INT

	IF (@is_id = -1)
		BEGIN
			SET @lis_id = null
		END
	ELSE
		BEGIN
			SET @lis_id = @is_id
		END

	-- oBTIENE EL oRDEN DE INSERCION
	SELECT @intOrder = MAX(trdai.rmaa_order)
		FROM tbRMA_Detail_AddItems trdai
		WHERE	trdai.comp_id = @comp_id AND
				trdai.rmah_id = @rmah_id

	INSERT INTO tbRMA_Detail_AddItems(
										comp_id,
										rmah_id,
										rmad_id,
										stor_id,
										item_id,
										rmaa_qty,
										is4AbailableStock,
										rmaa_order)
		SELECT							tia.comp_id,
										@rmah_id,
										@rmad_id,
										@stor_id,
										tia.item_id_1,
										@rmaa_qty * tia.iasso_qty,
										'True',
										ISNULL(@intOrder,0) + 10
			FROM tbItemAssociation tia
			WHERE	tia.comp_id = @comp_id AND
					tia.item_id = @item_id

	IF @@ROWCOUNT > 0
		BEGIN
			INSERT INTO tbRMA_Detail_AddItems
			(
				comp_id,
				-- rmaa_id -- this column value is auto-generated,
				rmah_id,
				rmad_id,
				stor_id,
				item_id,
				rmaa_qty,
				is_id,
				is4AbailableStock,
				rmaa_order
			)
			VALUES
			(
				@comp_id,
				@rmah_id,
				@rmad_id,
				@stor_id,
				@item_id,
				0,
				@lis_id,
				'False'
				,ISNULL(@intOrder,0) + 9
			)
		END
	ELSE
		BEGIN
			INSERT INTO tbRMA_Detail_AddItems
			(
				comp_id,
				-- rmaa_id -- this column value is auto-generated,
				rmah_id,
				rmad_id,
				stor_id,
				item_id,
				rmaa_qty,
				is_id,
				rmaa_order
			)
			VALUES
			(
				@comp_id,
				@rmah_id,
				@rmad_id,
				@stor_id,
				@item_id,
				@rmaa_qty,
				@lis_id,
				ISNULL(@intOrder,0) + 1
			)
		END


	SET	@return_value = @@IDENTITY

END
GO





CREATE procedure [dbo].[spRMA_Detail_AddItems_UpdateData]
(
	@comp_id	int,
	@rmaa_id	int,
	@rmaa_qty	int,
	@is_id		int
)

as set nocount ON

begin

	declare
		@lis_id as int

	if (@is_id = -1)
		set @lis_id = null
	else
		set @lis_id = @is_id



	update tbRMA_Detail_AddItems
	SET
