		is_id		= @lis_id
	where comp_id	= @comp_id
	and rmaa_id		= @rmaa_id


end
GO


CREATE PROCEDURE [dbo].[spRMA_Detail_AttributesHistory_InsertData]
(
	@comp_id		INT,
	@rmah_id		INT,
	@rmad_id		INT,
	@user_id		INT,
	@srpt_id		INT,
	@rmas_id		INT,
	@rmap_id		INT,
	@rmaw_id		INT,
	@rmamt_id		INT,
	@return_value	INT OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON

	-- -----------------------------
	-- TESTING
	-- -----------------------------
	/*
		DECLARE
			@comp_id	INT,
			@rmah_id	INT,
			@rmad_id	INT,
			@user_id	INT,
			@srpt_id	INT,
			@rmas_id	INT,
			@rmap_id	INT,
			@rmaw_id	INT,
			@rmamt_id	INT
	*/
	-- -----------------------------



		DECLARE
			@srpt_idOld		INT,
			@rmas_idOld		INT,
			@rmap_idOld		INT,
			@rmaw_idOld		INT,
			@rmamt_idOld	INT

		SET @srpt_idOld		= 0
		SET @rmas_idOld		= 0
		SET @rmap_idOld		= 0
		SET @rmaw_idOld		= 0
		SET @rmamt_idOld	= 0


		SELECT
			@srpt_idOld	= 	t.srpt_id,
			@rmas_idOld	=   t.rmas_id,
			@rmap_idOld =	t.rmap_id,
			@rmaw_idOld	=	t.rmaw_id,
			@rmamt_idOld=   t.rmamt_id
			FROM tbRMA_Detail_AttributesHistory t	WITH (NOLOCK)
			WHERE	t.comp_id = @comp_id AND
					t.rmah_id = @rmah_id AND
					t.rmad_id = @rmad_id



	IF
		@srpt_idOld		<>	@srpt_id		OR
		@rmas_idOld		<>	@rmas_id		OR
		@rmap_idOld		<>	@rmap_id		OR
		@rmaw_idOld		<>	@rmaw_id		OR
		@rmamt_idOld	<>	@rmamt_id
		BEGIN

			INSERT INTO tbRMA_Detail_AttributesHistory
			(
				comp_id,
				rmah_id,
				rmad_id,
				[user_id],
				srpt_id,
				rmas_id,
				rmap_id,
				rmaw_id,
				rmamt_id
			)
			VALUES
			(
				@comp_id,
				@rmah_id,
				@rmad_id,
				@user_id,
				@srpt_id,
				@rmas_id,
				@rmap_id,
				@rmaw_id,
				@rmamt_id
			)

		END

	SET @return_value = @@IDENTITY

END
GO

CREATE PROCEDURE [dbo].[spRMA_Detail_GetLastCustomerDiagnostic4_BySerialNumber]
(
	@comp_id	INT,
	@lang_id	INT,
	@serial		VARCHAR(100)
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@serial		VARCHAR(100)
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@serial		= 'D10015'

				--'D10015' TIENE DIAGNOSTICO
				--''
		*/
		-- ------------------------------------

		-- ------------------------------------
		-- VARIABLES DE TRABAJO
		-- ------------------------------------
			DECLARE
				@DiagnosticNote	NVARCHAR(500),
				@CT_Document	NVARCHAR(100),
				@CT_Date		DATETIME,
				@is_id			INT
			SET @DiagnosticNote	= ''
			SET @CT_Document	= ''
			SET @is_id			= -1
		-- ------------------------------------

		-- -------------------------------------------------------------------------------------------------------
		-- RECUPERO EL IS_ID EN BASE AL NUMERO DE SERIE QUE INGRESARON
		-- -------------------------------------------------------------------------------------------------------
			SELECT
				@is_id				= tis.is_id
			FROM tbItemSerials					tis
			WHERE	tis.comp_id		= @comp_id	AND
					tis.is_serial	= @serial
		-- -------------------------------------------------------------------------------------------------------

		-- -------------------------------------------------------------------------------------------------------
		-- RECUPERO EL ULTIMO DIAGNOSTICO QUE TUVO ESE IS_ID PARA UN RMA DE CLIENTES
		-- -------------------------------------------------------------------------------------------------------
			SELECT TOP 1
				@DiagnosticNote = ISNULL(trd.rmad_DiagnosticNote,'')
			FROM tbRMA_Detail						trd	WITH(NOLOCK)
				INNER JOIN tbRMA_Header				trh	WITH(NOLOCK)
					ON	trh.comp_id = trd.comp_id	AND
						trh.rmah_id = trd.rmah_id
			WHERE	trd.comp_id = @comp_id			AND
					trd.is_id	= @is_id			AND
					trh.cust_id IS NOT NULL
			ORDER BY trd.rmad_id DESC
		-- -------------------------------------------------------------------------------------------------------

		-- -------------------------------------------------------------------------------------------------------
		-- RECUPERO LA FC DE COMPRA DEL ARTICULO Y LA FECHA
		-- -------------------------------------------------------------------------------------------------------
			SELECT
				@CT_Document	= dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction),
				@CT_Date		= tct.ct_date
			FROM tbItemSerials tis
			INNER JOIN tbCommercialTransactions					tct
				ON	tct.comp_id			= tis.comp_id			AND
					tct.bra_id			= tis.bra_id			AND
					tct.ct_transaction	= tis.ct_transaction
			WHERE	tis.comp_id			= @comp_id				AND
					tis.is_id			= @is_id
		-- -------------------------------------------------------------------------------------------------------


		--DEVOLVEMOS TODO LO QUE ENCONTRÓ
		SELECT
			@CT_Document		[Document],
			@CT_Date			[Date],
			@DiagnosticNote		[Diagnostic]
	END
GO

CREATE PROCEDURE [dbo].[spRMA_Detail_Tmp_GetItems4Selection]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------
		-- TESTING
		-- -----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@guid		UNIQUEIDENTIFIER
			SELECT
				@comp_id	= 1,
				@guid		= '11382563-64C3-4ED4-9E9A-EB75384237FD'
		*/
		-- -----------------------------------------------

		--TENGO QUE TRAER LOS RMAD QUE NO ESTEN PROCESADOS DENTRO DE UN MISMO RMA
		SELECT
			' '										[ ],
			ISNULL(trdt.rmad_isSelected, 'False')	[Is_Selected],
			ISNULL(ti.item_code,'')					[item_code],
			ISNULL(ti.item_desc,'')					[item_desc],
			trdt.rmadt_originalPrice				[rmafp_Price],
			trdt.rmadt_qty,
			ISNULL(trdt.rmah_id,-1)					[rmah_id],
			ISNULL(trdt.rmad_id,-1)					[rmad_id],
			trdt.rmadt_id							[ID]
		FROM tbRMA_Detail_Tmp						AS trdt WITH(NOLOCK)
		LEFT JOIN tbItem							AS ti	WITH(NOLOCK)
			ON	ti.comp_id		= trdt.comp_id		AND
				ti.item_id		= trdt.item_id
		WHERE	trdt.comp_id	= @comp_id			AND
				trdt.rmadt_guid = @guid				AND
				trdt.rmadt_Date_Proc IS NULL
	END
GO

