CREATE PROCEDURE [dbo].[spRMA_Detail_Update_DeliverySheetDetail]
(
	@comp_id		   INT,
	@bra_id			   INT,
	@dsd_id			   INT,
	@user_id		   INT



)
AS
SET NOCOUNT ON


BEGIN

		DECLARE @lrmah_id			INT,
				@lrmad_id			INT,
				@ldsd_isRMA4Picking INT,
				@lds_status			INT



		SET @lrmah_id = (SELECT
							isnull(tdsd.rmah_id,0)
							FROM tbDeliverySheetDetail tdsd			WITH (NOLOCK)
							WHERE	comp_id  = @comp_id
							AND		bra_id   = @bra_id
							AND		dsd_id   = @dsd_id
		)

		SET @lrmad_id = (SELECT
							isnull(tdsd.rmad_id,0)
							FROM tbDeliverySheetDetail tdsd			WITH (NOLOCK)
							WHERE	comp_id  = @comp_id
							AND		bra_id   = @bra_id
							AND		dsd_id   = @dsd_id
		)

		SET @ldsd_isRMA4Picking = (SELECT
							isnull(tdsd.dsd_isRMA4Picking,0)
							FROM tbDeliverySheetDetail tdsd			WITH (NOLOCK)
							WHERE	comp_id  = @comp_id
							AND		bra_id   = @bra_id
							AND		dsd_id   = @dsd_id
		)

		SET @lds_status = (SELECT
								isnull(tdsd.sds_id,0)
								FROM tbDeliverySheetDetail tdsd			WITH (NOLOCK)
								WHERE	comp_id  = @comp_id
								AND		bra_id   = @bra_id
								AND		dsd_id   = @dsd_id
			)

		IF @ldsd_isRMA4Picking = 0
			-- ENVIO PICKING = FALSE
			BEGIN
					UPDATE  tbRMA_Detail

					SET sds_id4Delivery = @lds_status,
						dsd_id4Delivery = @dsd_id

					FROM tbRMA_Detail trd				WITH (NOLOCK)

					WHERE trd.comp_id = @comp_id	AND
						  trd.rmah_id = @lrmah_id	AND
						  trd.rmad_id = @lrmad_id
			END

		ELSE
			BEGIN
				-- RETIRO PICKING = TRUE
				UPDATE  tbRMA_Detail

				SET sds_id4Picking = @lds_status,
					dsd_id4Picking = @dsd_id

				FROM tbRMA_Detail trd				WITH (NOLOCK)

				WHERE trd.comp_id = @comp_id	AND
					  trd.rmah_id = @lrmah_id	AND
					  trd.rmad_id = @lrmad_id
			END





END
GO



