		END

GO

CREATE PROCEDURE [dbo].[spRMA_Detail_validateSerialFromSupplierByControl4Profile]
(
	@comp_id	INT,
	@lang_id	INT,
	@serial		VARCHAR(100)
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@serial		VARCHAR(100)
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@serial		= 'RMA0003'
		*/
		-- -------------------------------------------

		DECLARE @lis_id	AS INT

		SELECT TOP 1
			@lis_id = tis.is_id
			FROM	tbItemSerials			tis	WITH(NOLOCK)
			WHERE	tis.comp_id				= @comp_id
			AND		tis.is_serial			= @serial


		IF @lis_id IS NOT NULL    AND
			EXISTS (SELECT TOP 1 1
			   		FROM	tbRMA_Detail					trd	WITH(NOLOCK)
			   		        INNER JOIN tbRMA_Header			trh	WITH(NOLOCK)
			   		        ON	trh.comp_id		=	trd.comp_id
			   		        AND trh.rmah_id		=	trd.rmah_id
			   		WHERE	trd.comp_id			=	@comp_id		AND
			   				trd.is_id			=	@lis_id			AND
							trh.cust_id			IS NOT NULL			AND
							trd.srpt_id			IN (30,35,40,60,110)
					)
			BEGIN
				SELECT
					'' [Message]
			END
		ELSE
			BEGIN
				SELECT
					tut.utexts_desc					[Message]
				FROM tbsysUniqueTexts				tut	WITH(NOLOCK)
				WHERE	tut.lang_id		= @lang_id	AND
						tut.utexts_id	= 40364
			END

	END




GO



