CREATE PROCEDURE [dbo].[spRMA_FailedPart_getCombo]
(
	@comp_id	INT
)
AS

	SET NOCOUNT ON

		BEGIN

			SELECT
				trfp.rmafailP_id				[Id],
				trfp.rmafailP_desc				[Desc]
				FROM tbRMA_FailedPart			trfp
			WHERE	trfp.comp_id	= @comp_id	AND
					trfp.rmafailP_disabled	= 'False'

			ORDER BY [Desc]

		END


GO


CREATE procedure [dbo].[spRMA_FixPrices_GetCombo]
(
	@comp_id	INT,
	@bra_id		INT
)
as

BEGIN

	SET  NOCOUNT ON

	SELECT
		trfp.rmafp_id		[Id],
		dbo.fnStrPADR(trfp.rmafp_desc,50,'-')	+ ' ' +
		tc.curr_symbol							+ ' ' +
		CONVERT(VARCHAR,trfp.rmafp_price) 		[Desc]
		from tbRMA_FixPrices trfp					WITH (NOLOCK)
		INNER JOIN tbsysCurrency tc					WITH (NOLOCK)
			ON	tc.curr_id	= trfp.curr_id
		WHERE	trfp.comp_id	= @comp_id AND
				trfp.bra_id		= @bra_id
		ORDER BY trfp.rmafp_desc

END

GO




