CREATE PROCEDURE [dbo].[spRMA_getDataById]
(
	@lang_id			int,		-- esto es ser HIJO DE PUTA, y la re puta coimnpañiaaaa???????????????????
	@rmah_id			int,
	@rmadt_guid			uniqueidentifier
)
AS

BEGIN




	SET NOCOUNT ON

	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-06-23
	-- TN			: Referencia: #1
	-- Description	: Por el cambio de funcionalidad de no eliminación de la tbRMA_detail cuando se actualiza desde
	--				  la tbRMA_Detail_Tmp, sino que actualiza los registros existentes, se cargan los rmah_id y
	--				  rmad_id de la tbRMA_detail en la tbRMA_Detail_Tmp
	-- =================================================================================================================



	/*
	declare		@lang_id			int,
				@rmah_id			int,
				@rmadt_guid			UNIQUEIDENTIFIER

	select		@lang_id			= 2,
				@rmah_id			= 611,
				@rmadt_guid			= '84da4f9e-47f3-41f8-9e91-65593976891e'
	*/



	--Controlar si RMA no esté siendo editado por otro usuario
	IF exists (SELECT TOP 1  1
					from dbo.tbRMA_Header	WITH (NOLOCK)
					where	rmah_id			= @rmah_id and
							rmah_isEditing	= 'False')

	begin
		-- el registro NO ESTÁ tomado por lo tanto recupera el registro seleccionado, lo marca
		-- como tomado y carga todos los registros detalle en la temporal correspondiente


		--recuperar los valores de la cabecera
		exec dbo.[spRMAHeader_getDataById] @lang_id, @rmah_id


		declare @comp_id	int,
				@bra_id		INT
		select	@comp_id	= comp_id,
				@bra_id		= bra_id
			from dbo.tbRMA_Header	WITH (NOLOCK)
			where rmah_id	= @rmah_id

		-- declaración de variables para obtener los datos del cursor
		DECLARE
				@bitIs4Supplier				BIT,
				@lcomp_id					int,
				@lrmah_id					int,
				@lrmad_id					int,
				@lbra_id					int,
				@lit_transaction			int,
				@litem_id					int,
				@lstor_id					int,
				@lrmad_Manual				VARCHAR(100),
				@lrmad_originalPrice		DECIMAL(19,6),
				@lcurr_id					int,
				@lrmad_qty					DECIMAL(19,5),
				@luser_id_Reception			int,
				@lrmad_ReceptionNote		VARCHAR(8000),
				@lsrpt_id					int,
				@lis_id						int,
				@lrmad_procNote				VARCHAR(8000),
				@lrmad_DiagnosticNote		VARCHAR(8000),
				@ldf_id4CreditNote			INT,
				@lrmadt_isNewItem			BIT,
				@lrv						INT,
				@lsupp_id					INT,
				@impData_Custom_local		NVARCHAR(200),
				@impData_Number_local		NVARCHAR(200),
				@rmad_IncludeInPotentialStock bit,
				--STL PUNTO 22 NUCLEO
				@rmas_id					int,
				@rmap_id					int,
				@rmaw_id					INT,
				@rmamt_id					INT,
				@user_id_Diagnostic			INT,
				@rmad_Date_Diagnostic		DATETIME,
				@user_id_Proc				INT,
				@rmad_Date_Proc				DATETIME,
				@user_id_Delivery			INT,
				@rmad_Date_Delivery			DATETIME,
				@it_transactionCN			INT,
				@rmafailP_id				INT,
				@rmad_serial				VARCHAR(200),
				@case_id					INT,
				@rmad_relatedID				INT,
				@it_transaction_Origin		INT,
				@rmad_insertWarrantyDetail	NVARCHAR(1000),
				@rmad_insertWarrantyCertificates	NVARCHAR(100),
				@bra_id_original			INT,
				@rmad_isAvailable4DeliverySheet	BIT,
				@sds_id4Delivery			INT,
				@sds_id4Picking				INT,
				@dl_id4Picking				INT,
				@dl_id4Delivery				INT,
				@rmad_deliveryDate4Picking	DATETIME,
				@rmad_deliveryDate4Delivery	DATETIME,
				@rmad_up2price				DECIMAL(19,4)



		SET @bitIs4Supplier = 'False'


		-- declaración del cursor para obtener los datos de tbAccountTransactionDetailTmp
		declare cursor_RMA_gDBI_items CURSOR LOCAL FAST_FORWARD FOR
		select	comp_id,
				rmah_id,
				rmad_id,
				bra_id,
				it_transaction,
				item_id,
				stor_id,
				rmad_Manual,
				rmad_originalPrice,
				curr_id,
				rmad_qty,
				user_id_Reception,
				rmad_ReceptionNote,
				srpt_id,
				is_id,
				rmad_procNote,
				rmad_DiagnosticNote,
				df_id4CreditNote,
				rmad_isNewItem,
				supp_id,
				impData_Custom_local,
				impData_Number_local,
				rmad_IncludeInPotentialStock,
				--STL PUNTO 22 NUCLEO
				rmas_id,
				rmap_id,
				rmaw_id,
				rmamt_id,
				user_id_Diagnostic,
				rmad_Date_Diagnostic,
				user_id_Proc,
				rmad_Date_Proc,
				user_id_Delivery,
				rmad_Date_Delivery,
				it_transaction_CN,
				rmafailP_id,
				ISNULL(rmad_serial, ''),
				case_id,
				rmad_relatedID,
				it_transaction_Origin,
				rmad_insertWarrantyDetail,
				rmad_insertWarrantyCertificates,
				bra_id_original,
				rmad_isAvailable4DeliverySheet,
				sds_id4Delivery,
				sds_id4Picking,
				dl_id4Picking,
				dl_id4delivery,
				rmad_deliveryDate4Picking,
				rmad_deliveryDate4Delivery,
				rmad_up2price




			from	tbRMA_Detail	WITH (NOLOCK)
			WHERE	comp_id = @comp_id AND
					rmah_id = @rmah_id


		open	cursor_RMA_gDBI_items

		-- lectura anticipada del cursor
		fetch	cursor_RMA_gDBI_items
		into
				@lcomp_id,
				@lrmah_id,
				@lrmad_id,
				@lbra_id,
				@lit_transaction,
				@litem_id,
				@lstor_id,
				@lrmad_Manual,
				@lrmad_originalPrice,
				@lcurr_id,
				@lrmad_qty,
				@luser_id_Reception,
				@lrmad_ReceptionNote,
				@lsrpt_id,
				@lis_id	,
				@lrmad_procNote,
				@lrmad_DiagnosticNote,
				@ldf_id4CreditNote,
				@lrmadt_isNewItem,
				@lsupp_id,
				@impData_Custom_local,
				@impData_Number_local,
				@rmad_IncludeInPotentialStock,
				--STL PUNTO 22 NUCLEO
				@rmas_id,
				@rmap_id,
				@rmaw_id,
				@rmamt_id,
				@user_id_Diagnostic,
				@rmad_Date_Diagnostic,
				@user_id_Proc,
				@rmad_Date_Proc,
				@user_id_Delivery,
				@rmad_Date_Delivery,
				@it_transactionCN,
				@rmafailP_id,
				@rmad_serial,
				@case_id,
				@rmad_relatedID,
				@it_transaction_Origin,
				@rmad_insertWarrantyDetail,
				@rmad_insertWarrantyCertificates,
				@bra_id_original,
				@rmad_isAvailable4DeliverySheet,
				@sds_id4Delivery,
				@sds_id4Picking,
				@dl_id4Picking,
				@dl_id4Delivery,
				@rmad_deliveryDate4Picking,
				@rmad_deliveryDate4Delivery,
				@rmad_up2price


		-- se recorre el cursor hasta el fin del mismo
		while   @@fetch_status = 0
			begin


				IF @lsupp_id IS NOT NULL SET @bitIs4Supplier = 'True'

				-- por cada registro del cursor se realiza el insert en la *DetailTmp
				exec	dbo.spRMADetailTmp_insertData
						@lcomp_id,			@rmadt_guid,			@lbra_id,
						@lit_transaction,	@litem_id,				@lstor_id,
						@lrmad_Manual,		@lrmad_originalPrice,	@lcurr_id,
						@lrmad_qty,			@luser_id_Reception,	@lrmad_ReceptionNote,
						@lis_id,			@lrmad_ProcNote,		@lrmad_DiagnosticNote,
						@lsrpt_id,			@ldf_id4CreditNote, 	'FALSE',
						@lrmah_id,			@lrmad_id,				@lsupp_id,
						@impData_Custom_local,
						@impData_Number_local,
						--STL PUNTO 22 NUCLEO
						@rmas_id,			@rmap_id,
						@rmaw_id,			@rmamt_id,
						@user_id_Diagnostic,@rmad_Date_Diagnostic,
						@user_id_Proc,		@rmad_Date_Proc,
						@user_id_Delivery,  @rmad_Date_Delivery,@bitIs4Supplier,
						@return_value = @lrv OUTPUT

						--==STL PARA NO TOCAR EL SP ANTERIOR
						UPDATE tbRMA_Detail_Tmp	WITH (ROWLOCK)
							SET
								it_transaction_CN	= @it_transactionCN,
								rmafailP_id			= @rmafailP_id,
								rmadt_serial		= @rmad_serial,
								bra_id_original		= @bra_id_original,
								rmadt_up2Price		= @rmad_up2price
							WHERE	comp_id			= @comp_id	AND
									rmadt_id		= @lrv


				IF @lsrpt_id <> 1
				BEGIN
					UPDATE tbRMA_Detail_Tmp	WITH (ROWLOCK)
					SET --rmadt_isNew				= 'True',
						rmadt_srpt_id_previous		= srpt_id
					WHERE rmadt_id					= @lrv
				END

				-- Actualiza el nuevo campo
				UPDATE tbRMA_Detail_Tmp	WITH (ROWLOCK)
					SET
						rmad_IncludeInPotentialStock	= @rmad_IncludeInPotentialStock,
						case_id							= @case_id,
						rmad_relatedID					= @rmad_relatedID,
						it_transaction_Origin			= @it_transaction_Origin,
						rmad_insertWarrantyDetail		= @rmad_insertWarrantyDetail,
						rmad_insertWarrantyCertificates = @rmad_insertWarrantyCertificates,
						rmad_isAvailable4DeliverySheet	= @rmad_isAvailable4DeliverySheet,
						sds_id4Delivery					= @sds_id4Delivery,
						sds_id4Picking					= @sds_id4Picking,
						dl_id4Picking					= @dl_id4Picking,
						dl_id4delivery					= @dl_id4Delivery,
						rmad_deliveryDate4Picking		= @rmad_deliveryDate4Picking,
						rmad_deliveryDate4Delivery		= @rmad_deliveryDate4Delivery
					WHERE rmadt_id				= @lrv

				-- próxima lectura del cursor
				fetch	cursor_RMA_gDBI_items
				into
						@lcomp_id,
						@lrmah_id,
						@lrmad_id,
						@lbra_id,
						@lit_transaction,
						@litem_id,
						@lstor_id,
						@lrmad_Manual,
						@lrmad_originalPrice,
						@lcurr_id,
						@lrmad_qty,
						@luser_id_Reception,
						@lrmad_ReceptionNote,
						@lsrpt_id,
						@lis_id	,
						@lrmad_procNote,
						@lrmad_DiagnosticNote,
						@ldf_id4CreditNote,
						@lrmadt_isNewItem,
						@lsupp_id,
						@impData_Custom_local,
						@impData_Number_local,
						@rmad_IncludeInPotentialStock,
						--STL PUNTO 22 NUCLEO
						@rmas_id,
						@rmap_id,
						@rmaw_id,
						@rmamt_id,
						@user_id_Diagnostic,
						@rmad_Date_Diagnostic,
						@user_id_Proc,
						@rmad_Date_Proc,
						@user_id_Delivery,
						@rmad_Date_Delivery,
						@it_transactionCN,
						@rmafailP_id,
						@rmad_serial,
						@case_id,
						@rmad_relatedID,
						@it_transaction_Origin,
						@rmad_insertWarrantyDetail,
						@rmad_insertWarrantyCertificates,
						@bra_id_original,
						@rmad_isAvailable4DeliverySheet,
						@sds_id4Delivery,
						@sds_id4Picking,
						@dl_id4Picking,
						@dl_id4Delivery,
						@rmad_deliveryDate4Picking,
						@rmad_deliveryDate4Delivery,
						@rmad_up2price

			END

		close cursor_RMA_gDBI_items
		deallocate cursor_RMA_gDBI_items
	END

	ELSE

	BEGIN
		-- el registro ESTÁ tomado por lo tanto retorna sólo los datos de la cabecera

		exec dbo.[spRMAHeader_getDataById] @lang_id, @rmah_id

	END


END
GO








CREATE  PROCEDURE [dbo].[spRMA_getDataPending]
(
	@comp_id		INT,
	@cust_id		INT
)
AS


BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	set nocount ON

	/*
	declare		@comp_id		INT,
				@cust_id		INT

	select		@comp_id		= 1,
				@cust_id		=24288
	*/

	SELECT	trh.rmah_id,
			trh.rmah_cd,
			trt.srpt_desc,
			ti.item_code,
			ti.item_desc,
			trd.rmad_qty,
			trd.rmad_originalPrice

	FROM tbRMA_Header				trh

		INNER JOIN tbRMA_Detail		trd
		ON trd.comp_id	= trh.comp_id
		AND trd.rmah_id = trh.rmah_id

		INNER JOIN tbsysRMAProcType trt
		ON  trd.srpt_id	= trt.srpt_id

		INNER JOIN tbItem			ti
		ON ti.comp_id	= trd.comp_id
		AND ti.item_id	= trd.item_id

		WHERE trh.comp_id	= @comp_id
		AND trh.cust_id		= @cust_id
		AND trt.srpt_id		= 1





END
GO





