-- Author:		MOS
-- Create date: 02-2013
-- Description:	Retorna RMA para Web Service de consultas
-- =============================================
CREATE PROCEDURE [dbo].[spRMA_GetHistory]
	-- Add the parameters for the stored procedure here
	@comp_id AS INT,
	@lang_id AS INT,
	@bra_id	 AS INT,
	@wst_id  AS INT,
	@user_id AS INT,
	@cust_id AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SELECT *
		FROM tbRMA_Header trh
		INNER JOIN tbRMA_Detail trd
			ON		trd.comp_id = trh.comp_id
				AND trd.rmah_id = trh.rmah_id

		INNER JOIN tbUsers4BranchFilter vubf
			ON	vubf.comp_id	= trh.comp_id	AND
				vubf.bra_id		= trh.bra_id	AND
				vubf.[user_id]	= @user_id

		INNER JOIN tbsysRMAProcType trt
			ON trt.srpt_id = trd.srpt_id

	WHERE trh.cust_id = @cust_id

END
GO





CREATE PROCEDURE [dbo].[spRMA_getItemLastDateOfPurchase]
(
	@comp_id	INT,
	@cust_id	INT,
	@item_id	INT
)

AS

SET NOCOUNT ON

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- -------------------------------
	-- Testing
	-- -------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@cust_id	INT,
		@item_id	INT
	SELECT
		@comp_id	= 1,
		@cust_id	= 24288,
		@item_id	= 256
	*/
	-- -------------------------------

	SET DATEFORMAT 'ymd'


	SELECT	TOP 1
		CONVERT (CHAR(10), tit.it_cd, 103)			[Date]
		FROM tbItemTransactions							tit
			INNER JOIN tbCommercialTransactions			tct
			ON	tct.comp_id			= tit.comp_id		AND
				tct.ct_transaction	= tit.ct_transaction
		WHERE	tit.comp_id			= @comp_id			AND
				tit.item_id			= @item_id			AND
				tct.cust_id			= @cust_id			AND
				(
					tct.sd_id		= 1 OR
					tct.sd_id		= 2
				)
		ORDER BY tit.it_transaction DESC


END
GO




CREATE PROCEDURE [dbo].[spRMA_GetItemsPurchasedByCustomer]
(
	@comp_id	INT,
	@lang_id	INT,
	@cust_id	INT
)
AS

SET NOCOUNT ON

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- --------------------------------
	-- TESTING
	-- --------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@cust_id	INT
		SELECT
			@comp_id	= 1,
			@lang_id	= 2,
			@cust_id	= 24483
	*/
	-- --------------------------------
	SELECT
		ISNULL(ti.item_expser,'False')						[ ],
		dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction)	[Document],
		tct.ct_date,
		ti.item_code,
		ti.item_desc,

		tit.it_price,	-- Precio sin Impuestos
		tc.curr_symbol,
		tit.curr_id,

		CONVERT(VARCHAR,ti.item_id) + '-' +
		CONVERT(VARCHAR,tit.it_transaction)					[ID]
	FROM tbCommercialTransactions							tct		WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forSales		vctfs	WITH(NOLOCK)
		ON	vctfs.comp_id			= tct.comp_id			AND
			vctfs.ct_transaction	= tct.ct_transaction	AND
			vctfs.cust_id			= tct.cust_id
		INNER JOIN tbItemTransactions						tit		WITH(NOLOCK)
		ON	tit.comp_id				= tct.comp_id AND
			tit.ct_transaction		= tct.ct_transaction
		INNER JOIN tbItem									ti		WITH(NOLOCK)
		ON	ti.comp_id				= tit.comp_id			AND
			ti.item_id				= tit.item_id
		INNER JOIN tbsysCurrency							AS tc	WITH(NOLOCK)
		ON	tc.curr_id				= tit.curr_id
	WHERE	tct.comp_id				= @comp_id				AND
			tct.cust_id				= @cust_id				AND
			tct.sd_id				IN (1,2,4)

	ORDER BY tct.ct_transaction DESC

END
GO






CREATE PROCEDURE [dbo].[spRMA_getMailData]
(
	@comp_id		INT,
	@bra_id			INT,
	@rmah_id		INT,
	@selection_id	bit,
	@user_id		INT
)
AS


BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------
	/*
	DECLARE	@comp_id		INT,
			@bra_id			INT,
			@rmah_id		INT,
			@selection_id	BIT ,
			@user_id		INT
	SELECT	@comp_id		=	1,
			@bra_id			=	1,
			@rmah_id		=	960,
			@selection_id	=   'False',
			@user_id		=	119
	*/
	-- -----------------------------------------------------------------------------


	SELECT	tb.bra_MainDesc								[comp_desc],
			tc.smtp_host,
			tc.smtp_port,
			tc.smtp_ssc,
			tc.smtp_user,
			tc.smtp_password,
			tu.user_email								[from],
			CASE @selection_id WHEN 'true'
				THEN	isnull(ts.supp_eMail_PurchaseSector,'')
				else	isnull(tc2.cust_email4RMA, isnull(tc2.cust_email,''))
			END											[to],
			ISNULL(tb.bra_RMAeMailBody,'')				[bra_RMAeMailBody],
			dbo.fnStrPADL (dbo.fnStrAllTrim(convert(NVARCHAR(10),c.rmah_id)),10,'0')		[rmaNumber]


	FROM	tbCompany									tc		WITH (NOLOCK)

			INNER JOIN tbUser							tu		WITH (NOLOCK)
			ON		tu.[user_id]	=	@user_id

			INNER JOIN tbRMA_Header						c		WITH (NOLOCK)
			ON		c.comp_id		=	tc.comp_id
			AND		c.bra_id		=	@bra_id
			AND		c.rmah_id		=	@rmah_id

			LEFT JOIN tbSupplier						ts		WITH (NOLOCK)
			ON		ts.comp_id		=	c.comp_id
			AND		ts.supp_id		=	c.supp_id
			AND		@selection_id	=	'True'

			LEFT JOIN tbCustomer						tc2		WITH (NOLOCK)
			ON		tc2.comp_id		=	c.comp_id
			AND		tc2.cust_Id		=	c.cust_id
			AND		@selection_id	=	'False'

			INNER JOIN tbBranch							tb		WITH (NOLOCK)
				ON	tb.comp_id		= @comp_id AND
					tb.bra_id		= @bra_id

			WHERE	tc.comp_id		=	@comp_id


END
GO


CREATE procedure [dbo].[spRMA_getReport]
(
  @comp_id			int,
  @lang_id			int,
  @page_id			Int,
  @rma				int,
  @prof_id			int,
  @bra_id			int
)
as

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- - -----------------------------------------
	-- Testing
	-- - -----------------------------------------
	/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			Int,
			@rma				INT,
			@prof_id			INT,
			@bra_id				INT

	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10040,
			@rma				= 1121,
			@prof_id			= 1,
			@bra_id				= 1


	--DROP TABLE #tmpAdditionalItems_Totals
	*/
	-- - -----------------------------------------


	-- -----------------------------------------------
	-- CUENTO SI TIENE ARTÍCULOS ADICIONALES EL RMA
		DECLARE
			@AdditionalItems4RMA_Count	INT

		SELECT
			@AdditionalItems4RMA_Count	 = COUNT(*)
			FROM tbRMA_Detail_AddItems		trai
			WHERE	trai.comp_id = @comp_id AND
					trai.rmah_id = @rma

	-- -----------------------------------------------



	--Cabecera

	set DATEFORMAT 'ymd'

	Declare @bra INT
	Set @bra = (Select bra_id
				From tbRMA_Header trh
				Where trh.comp_id	= @comp_id
				And   trh.rmah_id   = @rma)

	-- Guardo el cliente del rma para saber en el detalle si el rma es de cliente o proveedor.
	Declare @cust INT
	Set @cust = (SELECT trh.cust_id
				From tbRMA_Header trh
				Where trh.comp_id	= @comp_id
				And   trh.rmah_id   = @rma)


	--Recupero en una variable el estado en controles por perfil . 0 - No Habilitado . 1 - Habilitado
	Declare @ctrl_price_cust INT
	Set @ctrl_price_cust = 1
	IF EXISTS(

					select 1
						from tbControlProfiles			WITH (NOLOCK)
						where	comp_id			= @comp_id	AND
								bra_id			= @bra		AND
								prof_id			= @prof_id	AND
								page_id			= 80000		AND
								ctrl_id			= 2784

				 )

			BEGIN

				Set @ctrl_price_cust = 0

			END

	Declare @ctrl_price_supp INT
	Set @ctrl_price_supp = 1
	IF EXISTS(

					select 1
						from tbControlProfiles			WITH (NOLOCK)
						where	comp_id			= @comp_id	AND
								bra_id			= @bra		AND
								prof_id			= @prof_id  AND
								page_id			= 80000		AND
								ctrl_id			= 2785

				 )

			BEGIN

				Set @ctrl_price_supp = 0

			END




	declare @bra_SaleOrderPricePlusTax	bit

	set @bra_SaleOrderPricePlusTax = (select isnull(tb.bra_SaleOrderPricePlusTax,'false')
									  from tbBranch					tb
									  where tb.comp_id = @comp_id
									  and   tb.bra_id  = @bra)

	---select @bra_SaleOrderPricePlusTax
	---Select @bra


	Select
			--customer
			CASE WHEN tc.cust_id IS NULL THEN ''
				ELSE '(' + convert(varchar,tc.cust_id) + ') - ' + ISNULL(tc.cust_name,'')
			END									[cust_name],
			tb.bra_desc,
			tc.cust_taxNumber ,
			tc.cust_address ,
			tc.cust_zip,
			tc.cust_city,
			tc.cust_Phone1,
			--supplier
			CASE WHEN ts.supp_id IS NULL THEN ''
				ELSE '(' + convert(varchar,ts.supp_id) + ') - ' + isnull(ts.supp_name,'')
			END									[supp_name],
			ts.supp_taxNumber,
			ts.supp_address,
			ts.supp_zip,
			ts.supp_city,
			ts.supp_Phone1,
			trh.rmah_isEditing,
			trh.rmah_cd,
			convert(VARCHAR,trh.rmah_id) [rmah_isEditingCD],
			isnull(td.dl_name,'')		 [dl_name],
			ISNULL(tc.cust_phone4RMA,'') [cust_phone4RMA], --,trn.rn_note,trn.rn_order
			@AdditionalItems4RMA_Count	[AdditionalItems4RMACount],

			-- -----------------------------------------------------------
			-- TICKET #3546 PEDIDO POR SINTAGMA
			-- -----------------------------------------------------------
			ISNULL(tb.bra_address,'')			[bra_address],
			ISNULL(tb.bra_zip, '')				[bra_zip],
			ts2.state_desc,
			ISNULL(tb.bra_phone,'')				[bra_phone],
			ISNULL(tb.bra_taxNumber,'')			[bra_taxNumber],
			ISNULL(tb.bra_taxNumber2,'')		[bra_taxNumbe2],
			ISNULL(tb.bra_taxNumber3,'')		[bra_taxNumber3]
			-- -----------------------------------------------------------



	FROM	dbo.tbRMA_Header						trh		WITH (NOLOCK)

			Inner Join tbCompany					tc2		WITH (NOLOCK)
			On	tc2.comp_id	= trh.comp_id

			left Join tbCustomer					tc		WITH (NOLOCK)
			On  tc.comp_id	= trh.comp_id
			And tc.cust_id	= trh.cust_id

			left Join tbSupplier					ts		WITH (NOLOCK)
			On  ts.comp_id	= trh.comp_id
			and ts.supp_id	= trh.supp_id

			Inner Join tbBranch						tb		WITH (NOLOCK)
			On	tb.comp_id	= trh.comp_id
			And tb.bra_id	= trh.bra_id

			LEFT JOIN tbDelivery					td		WITH (NOLOCK)
			ON	td.comp_id	= tc.comp_id AND
				td.dl_id	= tc.dl_id

			INNER JOIN tbsysState					ts2		WITH(NOLOCK)
			ON	ts2.country_id	= tb.country_id		AND
				ts2.state_id	= tb.state_id



	Where	trh.comp_id = trh.comp_id
	And		trh.rmah_id = @rma

	--Order By rn_order




	--Detalle
	Select	trd.rmah_id,
			ti.item_id,
	   		case when ti.item_id is not null then
				convert(varchar,ti.item_id) + ' - ' + ti.item_code + ' - '+ ti.item_desc
			else
				trd.rmad_Manual
			end [item_desc],
			isnull(tis.is_serial,'') [is_serial],
			trd.rmad_qty,

			CASE WHEN @cust IS NULL THEN
				case when @ctrl_price_supp = 1 then

						convert(varchar,tc.curr_symbol) +

						case when @bra_SaleOrderPricePlusTax = 'true'
							then
								convert(varchar,trd.rmad_originalPrice + (trd.rmad_originalPrice * isnull(ttn.tax_percentage,0) / 100))
							else
								convert(varchar,trd.rmad_originalPrice)
						END
				ELSE
						convert(varchar,'')
				end

				ELSE
					case when @ctrl_price_cust = 1 then

							convert(varchar,tc.curr_symbol) +

							case when @bra_SaleOrderPricePlusTax = 'true'
								then
									convert(varchar,trd.rmad_originalPrice + (trd.rmad_originalPrice * isnull(ttn.tax_percentage,0) / 100))
								else
									convert(varchar,trd.rmad_originalPrice)
							END
					ELSE
							convert(varchar,'')
					end

				END


			[rmafp_Price],

			ts.stor_desc,
			tc.curr_desc,
			trt.srpt_desc [curr_symbol],

			trd.rmad_DiagnosticNote,
			trd.rmad_ReceptionNote,


			tu.user_firstname,
			trd.rmad_ProcNote,
			convert(VARCHAR,trd.rmad_id)																[rmad_id],
			max(tct.ct_date)																			[ct_date],

			--trd.user_id_Reception,
			isnull(tu.user_nick,'')																		[user_nick_Reception],
			trd.rmad_Date_Reception																		[rmad_Date_Reception],

		   --trd.user_id_Diagnostic,
		   isnull(tu2.user_nick,'')																		[user_nick_Diag],
		   trd.rmad_Date_Diagnostic																		[rmad_Date_Diagnostic],

		   --trd.user_id_Proc,
		   isnull(tu3.user_nick,'')																		[user_nick_Proc],
		   trd.rmad_Date_Proc																			[rmad_Date_Proc],

		   --trd.user_id_Delivery
		   isnull(tu4.user_nick, '')																	[user_nick_Delivery],
		   trd.rmad_Date_Delivery																		[rmad_Date_Delivery],
		   dbo.fnRMAHeader_getReportDetail_GetNC_Rm(trd.comp_id, trd.rmah_id, trd.rmad_id,@lang_id)		[Document4Cancel],
		   isnull(trwt.rmaw_desc,'')																	[rmaw_desc],
		   ISNULL(trfp.rmafp_desc,'')																	[rmafp_desc],
		   CONVERT(DECIMAL(19,2),ISNULL(trfp.rmafp_price,0))											[rmafp_priceFP],
		   isnull(trd.rmad_serial,'')																	[rmad_serial],
		   ISNULL(tov.optval_desc,'')																	[rmad_SheetDeliveryStatus]


	From	tbRMA_Detail							trd			WITH (NOLOCK)

			left Join tbItem						ti			WITH (NOLOCK)
			On  ti.comp_id			= trd.comp_id
			And ti.item_id			= trd.item_id

			left Join tbItemSerials					tis			WITH (NOLOCK)
			ON  tis.comp_id			= trd.comp_id
			And tis.is_id			= trd.is_id
			And tis.item_id			= trd.item_id

			Inner Join tbStorage					ts			WITH (NOLOCK)
			On  ts.comp_id			= trd.comp_id
			And ts.stor_id			= trd.stor_id

			Inner Join tbsysCurrency				tc			WITH (NOLOCK)
			On	tc.curr_id			= trd.curr_id

			Inner Join tbUser						tu			WITH (NOLOCK)
			On	tu.[user_id]		= trd.user_id_Reception

			Inner Join tbsysRMAProcType				trt			WITH (NOLOCK)
			On	trt.srpt_id			= trd.srpt_id

			LEFT JOIN tbItemTransactionSerials		tits		WITH (NOLOCK)
			ON	tits.comp_id		= trd.comp_id
			AND tits.is_id			= trd.is_id

			LEFT JOIN tbCommercialTransactions		tct			WITH (NOLOCK)
			ON	tct.comp_id			= trd.comp_id
			AND tct.bra_id			= tits.bra_id
			AND tct.ct_transaction	= tits.ct_transaction
			AND tct.sd_id			IN (1,101)

			left join vwItemTaxesOnlyOneIvaTax		vit			WITH (NOLOCK)
			on  vit.comp_id			= trd.comp_id
			and vit.item_id			= trd.item_id

			left join tbItemTaxes					tit			WITH (NOLOCK)
			on  tit.comp_id			= trd.comp_id
			and tit.item_id			= trd.item_id
			and vit.tax_id			= tit.tax_id

			left join tbTaxName						ttn			WITH (NOLOCK)
			on  ttn.comp_id			= trd.comp_id
			and ttn.tax_id			= vit.tax_id

			--STL GRUPO NUCLEO JOINS PARA USUARIOS

	--		LEFT JOIN tbUser						tu
	--		ON tu.user_id	 = trd.user_id_Reception

			LEFT JOIN tbUser						tu2			WITH (NOLOCK)
			ON tu2.user_id	 = trd.user_id_Diagnostic

			LEFT JOIN tbUser						tu3			WITH (NOLOCK)
			ON tu3.user_id	 = trd.user_id_Proc

			LEFT JOIN tbUser						tu4			WITH (NOLOCK)
			ON tu4.user_id	 = trd.user_id_Delivery

			LEFT JOIN tbRMA_WarrantyType			trwt		WITH (NOLOCK)
			ON  trwt.comp_id = trd.comp_id		AND
				trwt.rmaw_id = trd.rmaw_id

			LEFT JOIN tbRMA_FixPrices				trfp		WITH(NOLOCK)
			ON	trfp.comp_id	= trd.comp_id		AND
				trfp.rmafp_id	= trd.rmafp_id

			LEFT JOIN tbsysOptionsValues				tov
			ON	tov.lang_id		= @lang_id				AND
				tov.optval_id	= trd.sds_id4Delivery	AND
				tov.optval_class= 711


	--		LEFT JOIN tbsysCurrency					tcFix
	--		ON tc.curr_id		= trfp.curr_id




	Where	trd.comp_id		= @comp_id
	And		trd.rmah_id		= @rma


	GROUP BY trd.rmah_id,
			ti.item_id,
	   		 --when ti.item_id is not null then
			ti.item_code,
			ti.item_desc,
			--else
			trd.rmad_Manual,
			--end
			--[item_desc],
			--isnull(tis.is_serial,'')
			[is_serial],
			trd.rmad_qty,
			--convert(varchar,tc.curr_symbol) + convert(varchar,
			trd.rmad_originalPrice,
			--[rmafp_Price],
			ts.stor_desc,
			tc.curr_desc,
			trt.srpt_desc,
			[curr_symbol],

			trd.rmad_DiagnosticNote,
			trd.rmad_ReceptionNote,


			tu.user_firstname,
			trd.rmad_ProcNote,
			--convert(VARCHAR,trd.rmad_id)
			[rmad_id],
			ttn.tax_percentage,
			tu.user_nick,
			trd.rmad_Date_Reception,
			tu2.user_nick,
			trd.rmad_Date_Diagnostic,
			tu3.user_nick,
			trd.rmad_Date_Proc,
			tu4.user_nick,
			trd.rmad_Date_Delivery,
			trd.comp_id,
			trwt.rmaw_desc,
			trfp.rmafp_desc,
			trfp.rmafp_price,
			trd.rmad_serial,
			tov.optval_desc

	order by trd.rmad_id


	EXEC spReports_getData3 @comp_id, @bra_id, @lang_id, @page_id, 1


	-- -------------------------------------------------
	-- rn_note
	-- -------------------------------------------------
	SELECT
		TOP 1
		trn.rn_note,
		trn.rn_order
		FROM	tbRmaNotes trn				WITH (NOLOCK)
		WHERE	trn.comp_id = @comp_id AND
				trn.bra_id	= @bra
		ORDER BY trn.rn_order
	-- -------------------------------------------------
	-- -------------------------------------------------

		DECLARE @prli_id4RMA	INT,
				@lcurr_id		INT


		SELECT
			@prli_id4RMA		= tb.bra_RMA_prli_id4AdditionalItems,
			@lcurr_id			= tb.curr_id
			FROM tbBranch		tb
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

		-- -------------------------------------------------
		-- ARTÍCULOS ADICIONALES - TOTALES
		-- -------------------------------------------------
		DECLARE @tmpAdditionalItemsTotals TABLE(qty DECIMAL(19,4),price DECIMAL(19,4),curr_symbol nchar(10),pricewihtax DECIMAL(19,4))
		INSERT INTO @tmpAdditionalItemsTotals(qty,price,curr_symbol,pricewihtax)
		SELECT
			SUM(trdai.rmaa_qty)																							[rmaa_qty],
			SUM(convert(decimal(19,2),trdai.rmaa_qty * dbo.fnGetExchange2(@comp_id, tpli.prli_price, tc.curr_id, @lcurr_id, 0,0,0,0)))	[item_price],
			tc2.curr_symbol																								[curr_symbol],
			SUM(convert(decimal(19,2),trdai.rmaa_qty * dbo.fnGetExchange2(@comp_id, tpli.prli_price * dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,ti.item_id)), tc.curr_id, @lcurr_id, 0,0,0,0)))	[item_pricewithtax]

			--INTO #tmpAdditionalItems_Totals

			FROM tbRMA_Detail_AddItems			trdai		WITH (NOLOCK)
			INNER JOIN tbItem					ti			WITH (NOLOCK)
				ON	ti.comp_id		= trdai.comp_id	AND
					ti.item_id		= trdai.item_id
			LEFT JOIN tbPriceListItems			tpli		WITH (NOLOCK)
				ON	tpli.comp_id	= trdai.comp_id	AND
					tpli.prli_id	= @prli_id4RMA	AND
					tpli.item_id	= trdai.item_id
			LEFT JOIN tbsysCurrency				tc			WITH (NOLOCK)
				ON	tc.curr_id		= tpli.curr_id
			LEFT JOIN tbsysCurrency				tc2			WITH (NOLOCK)
				ON	tc2.curr_id		= @lcurr_id

			WHERE	trdai.comp_id	= @comp_id		AND
					trdai.rmah_id	= @rma

			GROUP BY tc2.curr_symbol


		-- -------------------------------------------------
		-- ARTÍCULOS ADICIONALES
		-- -------------------------------------------------

		SELECT
			ti.item_code						[item_code],
			ti.item_desc						[item_desc],
			ISNULL(tis.is_serial,'')			[is_serial],
			trdai.rmaa_qty						[rmaa_qty],
			tpli.prli_price						[item_price],
			tc.curr_symbol						[curr_symbol],
			0									[order],
			(tpli.prli_price * dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,ti.item_id)))[item_pricewithtax]

			FROM tbRMA_Detail_AddItems			trdai			WITH (NOLOCK)
			INNER JOIN tbItem					ti				WITH (NOLOCK)
				ON	ti.comp_id		= trdai.comp_id	AND
					ti.item_id		= trdai.item_id
			LEFT JOIN tbItemSerials			tis					WITH (NOLOCK)
				ON	tis.comp_id		= trdai.comp_id	AND
					tis.is_id		= trdai.is_id
			LEFT JOIN tbPriceListItems			tpli			WITH (NOLOCK)
				ON	tpli.comp_id	= trdai.comp_id	AND
					tpli.prli_id	= @prli_id4RMA	AND
					tpli.item_id	= trdai.item_id
			LEFT JOIN tbsysCurrency				tc				WITH (NOLOCK)
				ON	tc.curr_id		= tpli.curr_id
			WHERE	trdai.comp_id	= @comp_id		AND
					trdai.rmah_id	= @rma
			--ORDER BY trdai.rmaa_order
		-- -------------------------------------------------


		UNION ALL


		SELECT
			(SELECT tut.utexts_desc
			FROM tbsysUniqueTexts tut
			WHERE tut.lang_id = @lang_id AND tut.utexts_id = 203)		[item_code],
			''									[item_desc],
			''									[is_serial],
			tait.qty							[rmaa_qty],
			tait.price							[item_price],
			tait.curr_symbol					[curr_symbol],
			1									[order],
			tait.pricewihtax					[item_pricewithtax]

			FROM	@tmpAdditionalItemsTotals					tait

			ORDER BY [order]

END
GO



CREATE PROCEDURE [dbo].[spRMA_GetReport_ServiceOrder]
(
	@comp_id   INT,
	@lang_id   INT,
	@page_id   INT,
	@bra_id   INT,
	@prof_id   INT,
	@rmah_id   INT,
	--@rmad_id INT,
	@CopyNumber  INT
)
AS

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON

	-- ---------------------------------------
	-- TESTING
	-- ---------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@page_id	INT,
			@rmah_id	INT,
			--@rmad_id	INT,
			@CopyNumber INT
		SELECT
			@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@page_id	= 10032,
			@rmah_id	= 343,
			@CopyNumber = 1
	*/
	-- ---------------------------------------


	DECLARE
	@CopyType AS NVARCHAR(50)

	SELECT
		@CopyType = tov.optval_desc
		FROM tbsysOptionsValues			tov	WITH (NOLOCK)
		WHERE tov.lang_id   = @lang_id	AND
		 tov.optval_class	= 560		AND
		 tov.optval_id		= @CopyNumber

	SELECT
		--DATOS SUCURSAL
		tb.bra_desc							[bra_MainDesc],
		tb.bra_address,
		tb.bra_taxNumber,
		tb.bra_taxNumber2,
		tb.bra_taxNumber3,
		tb.bra_taxFiscalClass,

		--DATOS CLIENTE
		tc.cust_name,
		tc.cust_taxNumber,
		tc.cust_address,
		ISNULL(tc.cust_phone1,'') + ' / ' + ISNULL(tc.cust_cellPhone,'') [Cust_Phone],

		--

		@CopyType							[CopyType],
		trh.rmah_cd + 30					[rmah_consultationDate],
		trh.rmah_cd,
		tc.cust_id
		FROM tbRMA_Header					trh	WITH (NOLOCK)
		INNER JOIN tbBranch					tb	WITH (NOLOCK)
		  ON	tb.comp_id	= trh.comp_id	AND
				tb.bra_id	= trh.bra_id
		INNER JOIN tbCustomer				tc	WITH (NOLOCK)
			ON	tc.comp_id	= trh.comp_id	AND
				tc.cust_id	= trh.cust_id
		WHERE trh.comp_id	= @comp_id		AND
		  trh.rmah_id  = @rmah_id

	EXEC spReports_getData3  @comp_id, @bra_id, @lang_id, @page_id, 1


	SELECT
		--DATOS ARTÍCULO
		ti.item_code,
		ti.item_desc,
		tb.brand_desc,

		trd.rmad_DiagnosticNote,
		ISNULL(tis.is_serial,'') + ISNULL(trd.rmad_serial,'')								[is_serial],
		dbo.fnGetEAN_Encode4EAN13(dbo.fnStrPADL(dbo.fnGetOnlyNumbers(ISNULL(trd.rmad_id,'')),13, '0'),'False')  [rmad_id],
		--'*' + ' ' + dbo.fnStrPADL(trd.rmad_id,10, '0') + ' ' + '*'       [rmad_id],
		trd.rmad_qty,
		trd.rmad_ReceptionNote, --PREGUNTAR



		--DATOS PROVEEDOR
		ts.supp_name,
		ts.supp_taxNumber,
		tfc.fc_desc,
		ISNULL(
		CASE tct.comp_id WHEN NULL THEN	''
		ELSE tct.ct_date
		END ,'')																			[CT_Date],
		--DATOS DE COMPROBANTE
		ISNULL(trs.rmas_desc,'')															[rmas_desc],
		ISNULL(trfp.rmafailP_desc,'')														[rmafailP_desc],
		ISNULL(tu.user_lastname + ',' + tu.user_firstname,'')								[UserName],
		dbo.fnStrPADL(CAST(trd.bra_id AS NVARCHAR), 4,'0') + '-' +
		dbo.fnstrpadl(CAST(trd.rmad_id AS NVARCHAR),8,'0')									[DocNumber],

		ISNULL(CONVERT(VARCHAR,tiabr.insud_polizaNumber),'') +	' / ' +
		ISNULL(CONVERT(VARCHAR,tit.insud_certificateNumber),'')								[insud_polizaNumber],
		ISNULL(tct.ct_CAI,'')																[ct_CAI],
		tct.ct_CAIDate,
		dbo.fnGetCommercialTransactionDescription(tct.comp_id,@lang_id,tct.ct_transaction)	[DocName],
		dbo.fnRMA_GetHTMLTable4StatusChanges(@comp_id, @lang_id, trd.rmah_id, trd.rmad_id)	[RMA_StatusChanges],
		ISNULL(trd.rmad_insertWarrantyDetail,'')											[rmad_insertWarrantyDetail],
		ISNULL(trd.rmad_insertWarrantyCertificates,'')										[rmad_insertWarrantyCertificates]

		FROM tbRMA_Detail							trd	WITH (NOLOCK)
		INNER JOIN tbItem							ti	WITH (NOLOCK)
			ON	ti.comp_id			= trd.comp_id	AND
				ti.item_id			= trd.item_id
		LEFT JOIN tbBrand							tb	WITH (NOLOCK)
			ON	tb.comp_id			= ti.comp_id	AND
				tb.brand_id			= ti.brand_id
		LEFT JOIN tbItemSerials						tis	WITH (NOLOCK)
			ON	tis.comp_id			= trd.comp_id	AND
				tis.is_id			= trd.is_id
		LEFT JOIN tbSupplier						ts	WITH (NOLOCK)
			ON	ts.comp_id			= trd.comp_id	AND
				ts.supp_id			= trd.supp_id
		LEFT JOIN tbsysFiscalClass					tfc	WITH (NOLOCK)
			ON	tfc.fc_id			= ts.fc_id
		LEFT JOIN tbItemTransactions				tit	WITH (NOLOCK)
			ON	tit.comp_id			= trd.comp_id	AND
				tit.it_transaction	= trd.it_transaction_Origin
		LEFT JOIN tbCommercialTransactions			tct	WITH (NOLOCK)
			ON	tct.comp_id			= tit.comp_id	AND
				tct.ct_transaction	= tit.ct_transaction
		LEFT JOIN tbRMA_Status						trs	WITH (NOLOCK)
			ON	trs.comp_id			= trd.comp_id	AND
				trs.rmas_id			= trd.rmas_id
		LEFT JOIN tbRMA_FailedPart					trfp	WITH (NOLOCK)
			ON	trfp.comp_id		= trd.comp_id	AND
				trfp.rmafailP_id	= trd.rmafailP_id
		INNER JOIN tbUser							tu	WITH (NOLOCK)
			ON	tu.[user_id]		= trd.user_id_Reception
		LEFT JOIN tbInsuranceAgent_BranchRelation	tiabr	WITH (NOLOCK)
			ON	tiabr.comp_id		= tit.comp_id	AND
				tiabr.insud_id		= tit.insud_id
		WHERE	trd.comp_id			= @comp_id		AND
				trd.rmah_id			= @rmah_id

END
GO


create procedure [dbo].[spRMA_getReport2]
(
  @comp_id			int,
  @lang_id			int,
  @page_id			Int,
  @rma				int,
  @prof_id			int,
  @bra_id			int
)
as

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- - -----------------------------------------
	-- Testing
	-- - -----------------------------------------
	/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			Int,
			@rma				INT,
			@prof_id			INT,
			@bra_id				INT

	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10040,
			@rma				= 1121,
			@prof_id			= 1,
			@bra_id				= 1


	--DROP TABLE #tmpAdditionalItems_Totals
	*/
	-- - -----------------------------------------


	-- -----------------------------------------------
	-- CUENTO SI TIENE ARTÍCULOS ADICIONALES EL RMA
		DECLARE
			@AdditionalItems4RMA_Count	INT

		SELECT
			@AdditionalItems4RMA_Count	 = COUNT(*)
			FROM tbRMA_Detail_AddItems		trai
			WHERE	trai.comp_id = @comp_id AND
					trai.rmah_id = @rma

	-- -----------------------------------------------



	--Cabecera

	set DATEFORMAT 'ymd'

	Declare @bra INT
	Set @bra = (Select bra_id
				From tbRMA_Header trh
				Where trh.comp_id	= @comp_id
				And   trh.rmah_id   = @rma)

	-- Guardo el cliente del rma para saber en el detalle si el rma es de cliente o proveedor.
	Declare @cust INT
	Set @cust = (SELECT trh.cust_id
				From tbRMA_Header trh
				Where trh.comp_id	= @comp_id
				And   trh.rmah_id   = @rma)


	--Recupero en una variable el estado en controles por perfil . 0 - No Habilitado . 1 - Habilitado
	Declare @ctrl_price_cust INT
	Set @ctrl_price_cust = 1
	IF EXISTS(

					select 1
						from tbControlProfiles			WITH (NOLOCK)
						where	comp_id			= @comp_id	AND
								bra_id			= @bra		AND
								prof_id			= @prof_id	AND
								page_id			= 80000		AND
								ctrl_id			= 2784

				 )

			BEGIN

				Set @ctrl_price_cust = 0

			END

	Declare @ctrl_price_supp INT
	Set @ctrl_price_supp = 1
	IF EXISTS(

					select 1
						from tbControlProfiles			WITH (NOLOCK)
						where	comp_id			= @comp_id	AND
								bra_id			= @bra		AND
								prof_id			= @prof_id  AND
								page_id			= 80000		AND
								ctrl_id			= 2785

				 )

			BEGIN

				Set @ctrl_price_supp = 0

			END




	declare @bra_SaleOrderPricePlusTax	bit

	set @bra_SaleOrderPricePlusTax = (select isnull(tb.bra_SaleOrderPricePlusTax,'false')
									  from tbBranch					tb
									  where tb.comp_id = @comp_id
									  and   tb.bra_id  = @bra)

	---select @bra_SaleOrderPricePlusTax
	---Select @bra


	Select
			--customer
			CASE WHEN tc.cust_id IS NULL THEN ''
				ELSE '(' + convert(varchar,tc.cust_id) + ') - ' + ISNULL(tc.cust_name,'')
			END									[cust_name],
			tb.bra_desc,
			tc.cust_taxNumber ,
			tc.cust_address ,
			tc.cust_zip,
			tc.cust_city,
			tc.cust_Phone1,
			--supplier
			CASE WHEN ts.supp_id IS NULL THEN ''
				ELSE '(' + convert(varchar,ts.supp_id) + ') - ' + isnull(ts.supp_name,'')
			END									[supp_name],
			ts.supp_taxNumber,
			ts.supp_address,
			ts.supp_zip,
			ts.supp_city,
			ts.supp_Phone1,
			trh.rmah_isEditing,
			trh.rmah_cd,
			convert(VARCHAR,trh.rmah_id) [rmah_isEditingCD],
			isnull(td.dl_name,'')		 [dl_name],
			ISNULL(tc.cust_phone4RMA,'') [cust_phone4RMA], --,trn.rn_note,trn.rn_order
			@AdditionalItems4RMA_Count	[AdditionalItems4RMACount],

			-- -----------------------------------------------------------
			-- TICKET #3546 PEDIDO POR SINTAGMA
			-- -----------------------------------------------------------
			ISNULL(tb.bra_address,'')			[bra_address],
			ISNULL(tb.bra_zip, '')				[bra_zip],
			ts2.state_desc,
			ISNULL(tb.bra_phone,'')				[bra_phone],
			ISNULL(tb.bra_taxNumber,'')			[bra_taxNumber],
			ISNULL(tb.bra_taxNumber2,'')		[bra_taxNumbe2],
			ISNULL(tb.bra_taxNumber3,'')		[bra_taxNumber3]
			-- -----------------------------------------------------------



	FROM	dbo.tbRMA_Header						trh		WITH (NOLOCK)

			Inner Join tbCompany					tc2		WITH (NOLOCK)
			On	tc2.comp_id	= trh.comp_id

			left Join tbCustomer					tc		WITH (NOLOCK)
			On  tc.comp_id	= trh.comp_id
			And tc.cust_id	= trh.cust_id

			left Join tbSupplier					ts		WITH (NOLOCK)
			On  ts.comp_id	= trh.comp_id
			and ts.supp_id	= trh.supp_id

			Inner Join tbBranch						tb		WITH (NOLOCK)
			On	tb.comp_id	= trh.comp_id
			And tb.bra_id	= trh.bra_id

			LEFT JOIN tbDelivery					td		WITH (NOLOCK)
			ON	td.comp_id	= tc.comp_id AND
				td.dl_id	= tc.dl_id

			INNER JOIN tbsysState					ts2		WITH(NOLOCK)
			ON	ts2.country_id	= tb.country_id		AND
				ts2.state_id	= tb.state_id



	Where	trh.comp_id = trh.comp_id
	And		trh.rmah_id = @rma

	--Order By rn_order




	--Detalle
	Select	trd.rmah_id,
			ti.item_id,
	   		case when ti.item_id is not null then
				convert(varchar,ti.item_id) + ' - ' + ti.item_code + ' - '+ ti.item_desc
			else
				trd.rmad_Manual
			end [item_desc],
			isnull(tis.is_serial,'') [is_serial],
			trd.rmad_qty,

			CASE WHEN @cust IS NULL THEN
				case when @ctrl_price_supp = 1 then

						convert(varchar,tc.curr_symbol) +

						case when @bra_SaleOrderPricePlusTax = 'true'
							then
								convert(varchar,trd.rmad_originalPrice + (trd.rmad_originalPrice * isnull(ttn.tax_percentage,0) / 100))
							else
								convert(varchar,trd.rmad_originalPrice)
						END
				ELSE
						convert(varchar,'')
				end

				ELSE
					case when @ctrl_price_cust = 1 then

							convert(varchar,tc.curr_symbol) +

							case when @bra_SaleOrderPricePlusTax = 'true'
								then
									convert(varchar,trd.rmad_originalPrice + (trd.rmad_originalPrice * isnull(ttn.tax_percentage,0) / 100))
								else
									convert(varchar,trd.rmad_originalPrice)
							END
					ELSE
							convert(varchar,'')
					end

				END


			[rmafp_Price],

			ts.stor_desc,
			tc.curr_desc,
			trt.srpt_desc [curr_symbol],

			isnull(trs.rmas_desc,'')																[rmad_DiagnosticNote], -- es estado de rma pero lo agregamos en esta columna q se borró para no tener que agregar otra neuva
			isnull(trd.rmad_ReceptionNote,''),


			tu.user_firstname,
			trd.rmad_ProcNote,
			convert(VARCHAR,trd.rmad_id)																[rmad_id],
			max(tct.ct_date)																			[ct_date],

			--trd.user_id_Reception,
			isnull(tu.user_nick,'')																		[user_nick_Reception],
			trd.rmad_Date_Reception																		[rmad_Date_Reception],

		   --trd.user_id_Diagnostic,
		   isnull(tu2.user_nick,'')																		[user_nick_Diag],
		   trd.rmad_Date_Diagnostic																		[rmad_Date_Diagnostic],

		   --trd.user_id_Proc,
		   isnull(tu3.user_nick,'')																		[user_nick_Proc],
		   trd.rmad_Date_Proc																			[rmad_Date_Proc],

		   --trd.user_id_Delivery
		   isnull(tu4.user_nick, '')																	[user_nick_Delivery],
		   trd.rmad_Date_Delivery																		[rmad_Date_Delivery],
		   dbo.fnRMAHeader_getReportDetail_GetNC_Rm(trd.comp_id, trd.rmah_id, trd.rmad_id,@lang_id)		[Document4Cancel],
		   isnull(trwt.rmaw_desc,'')																	[rmaw_desc],
		   ISNULL(trfp.rmafp_desc,'')																	[rmafp_desc],
		   CONVERT(DECIMAL(19,2),ISNULL(trfp.rmafp_price,0))											[rmafp_priceFP],
		   isnull(trd.rmad_serial,'')																	[rmad_serial],
		   ISNULL(tov.optval_desc,'')																	[rmad_SheetDeliveryStatus]


	From	tbRMA_Detail							trd			WITH (NOLOCK)

			left Join tbItem						ti			WITH (NOLOCK)
			On  ti.comp_id			= trd.comp_id
			And ti.item_id			= trd.item_id

			left Join tbItemSerials					tis			WITH (NOLOCK)
			ON  tis.comp_id			= trd.comp_id
			And tis.is_id			= trd.is_id
			And tis.item_id			= trd.item_id

			Inner Join tbStorage					ts			WITH (NOLOCK)
			On  ts.comp_id			= trd.comp_id
			And ts.stor_id			= trd.stor_id

			Inner Join tbsysCurrency				tc			WITH (NOLOCK)
			On	tc.curr_id			= trd.curr_id

			Inner Join tbUser						tu			WITH (NOLOCK)
			On	tu.[user_id]		= trd.user_id_Reception

			Inner Join tbsysRMAProcType				trt			WITH (NOLOCK)
			On	trt.srpt_id			= trd.srpt_id

			LEFT JOIN tbItemTransactionSerials		tits		WITH (NOLOCK)
			ON	tits.comp_id		= trd.comp_id
			AND tits.is_id			= trd.is_id

			LEFT JOIN tbCommercialTransactions		tct			WITH (NOLOCK)
			ON	tct.comp_id			= trd.comp_id
			AND tct.bra_id			= tits.bra_id
			AND tct.ct_transaction	= tits.ct_transaction
			AND tct.sd_id			IN (1,101)

			left join vwItemTaxesOnlyOneIvaTax		vit			WITH (NOLOCK)
			on  vit.comp_id			= trd.comp_id
			and vit.item_id			= trd.item_id

			left join tbItemTaxes					tit			WITH (NOLOCK)
			on  tit.comp_id			= trd.comp_id
			and tit.item_id			= trd.item_id
			and vit.tax_id			= tit.tax_id

			left join tbTaxName						ttn			WITH (NOLOCK)
			on  ttn.comp_id			= trd.comp_id
			and ttn.tax_id			= vit.tax_id

			--STL GRUPO NUCLEO JOINS PARA USUARIOS

	--		LEFT JOIN tbUser						tu
	--		ON tu.user_id	 = trd.user_id_Reception

			LEFT JOIN tbUser						tu2			WITH (NOLOCK)
			ON tu2.user_id	 = trd.user_id_Diagnostic

			LEFT JOIN tbUser						tu3			WITH (NOLOCK)
			ON tu3.user_id	 = trd.user_id_Proc

			LEFT JOIN tbUser						tu4			WITH (NOLOCK)
			ON tu4.user_id	 = trd.user_id_Delivery

			LEFT JOIN tbRMA_WarrantyType			trwt		WITH (NOLOCK)
			ON  trwt.comp_id = trd.comp_id		AND
				trwt.rmaw_id = trd.rmaw_id

			LEFT JOIN tbRMA_FixPrices				trfp		WITH(NOLOCK)
			ON	trfp.comp_id	= trd.comp_id		AND
				trfp.rmafp_id	= trd.rmafp_id

			LEFT JOIN tbsysOptionsValues				tov
			ON	tov.lang_id		= @lang_id				AND
				tov.optval_id	= trd.sds_id4Delivery	AND
				tov.optval_class= 711

			LEFT JOIN tbRMA_Status AS trs						WITH(NOLOCK)
			ON trs.comp_id	= trd.comp_id				AND
				trs.rmas_id = trd.rmas_id


	--		LEFT JOIN tbsysCurrency					tcFix
	--		ON tc.curr_id		= trfp.curr_id




	Where	trd.comp_id		= @comp_id
	And		trd.rmah_id		= @rma


	GROUP BY trd.rmah_id,
			ti.item_id,
	   		 --when ti.item_id is not null then
			ti.item_code,
			ti.item_desc,
			--else
			trd.rmad_Manual,
			--end
			--[item_desc],
			--isnull(tis.is_serial,'')
			[is_serial],
			trd.rmad_qty,
			--convert(varchar,tc.curr_symbol) + convert(varchar,
			trd.rmad_originalPrice,
			--[rmafp_Price],
			ts.stor_desc,
			tc.curr_desc,
			trt.srpt_desc,
			[curr_symbol],

			trs.rmas_desc,
			trd.rmad_ReceptionNote,


			tu.user_firstname,
			trd.rmad_ProcNote,
			--convert(VARCHAR,trd.rmad_id)
			[rmad_id],
			ttn.tax_percentage,
			tu.user_nick,
			trd.rmad_Date_Reception,
			tu2.user_nick,
			trd.rmad_Date_Diagnostic,
			tu3.user_nick,
			trd.rmad_Date_Proc,
			tu4.user_nick,
			trd.rmad_Date_Delivery,
			trd.comp_id,
			trwt.rmaw_desc,
			trfp.rmafp_desc,
			trfp.rmafp_price,
			trd.rmad_serial,
			tov.optval_desc

	order by trd.rmad_id


	EXEC spReports_getData3 @comp_id, @bra_id, @lang_id, @page_id, 1


	-- -------------------------------------------------
	-- rn_note
	-- -------------------------------------------------
	SELECT
		TOP 1
		trn.rn_note,
		trn.rn_order
		FROM	tbRmaNotes trn				WITH (NOLOCK)
		WHERE	trn.comp_id = @comp_id AND
				trn.bra_id	= @bra
		ORDER BY trn.rn_order
	-- -------------------------------------------------
	-- -------------------------------------------------

		DECLARE @prli_id4RMA	INT,
				@lcurr_id		INT


		SELECT
			@prli_id4RMA		= tb.bra_RMA_prli_id4AdditionalItems,
			@lcurr_id			= tb.curr_id
			FROM tbBranch		tb
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

		-- -------------------------------------------------
		-- ARTÍCULOS ADICIONALES - TOTALES
		-- -------------------------------------------------
		DECLARE @tmpAdditionalItemsTotals TABLE(qty DECIMAL(19,4),price DECIMAL(19,4),curr_symbol nchar(10),pricewihtax DECIMAL(19,4))
		INSERT INTO @tmpAdditionalItemsTotals(qty,price,curr_symbol,pricewihtax)
		SELECT
			SUM(trdai.rmaa_qty)																							[rmaa_qty],
			SUM(convert(decimal(19,2),trdai.rmaa_qty * dbo.fnGetExchange2(@comp_id, tpli.prli_price, tc.curr_id, @lcurr_id, 0,0,0,0)))	[item_price],
			tc2.curr_symbol																								[curr_symbol],
			SUM(convert(decimal(19,2),trdai.rmaa_qty * dbo.fnGetExchange2(@comp_id, tpli.prli_price * dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,ti.item_id)), tc.curr_id, @lcurr_id, 0,0,0,0)))	[item_pricewithtax]

			--INTO #tmpAdditionalItems_Totals

			FROM tbRMA_Detail_AddItems			trdai		WITH (NOLOCK)
			INNER JOIN tbItem					ti			WITH (NOLOCK)
				ON	ti.comp_id		= trdai.comp_id	AND
					ti.item_id		= trdai.item_id
			LEFT JOIN tbPriceListItems			tpli		WITH (NOLOCK)
				ON	tpli.comp_id	= trdai.comp_id	AND
					tpli.prli_id	= @prli_id4RMA	AND
					tpli.item_id	= trdai.item_id
			LEFT JOIN tbsysCurrency				tc			WITH (NOLOCK)
				ON	tc.curr_id		= tpli.curr_id
			LEFT JOIN tbsysCurrency				tc2			WITH (NOLOCK)
				ON	tc2.curr_id		= @lcurr_id

			WHERE	trdai.comp_id	= @comp_id		AND
					trdai.rmah_id	= @rma

			GROUP BY tc2.curr_symbol


		-- -------------------------------------------------
		-- ARTÍCULOS ADICIONALES
		-- -------------------------------------------------

		SELECT
			ti.item_code						[item_code],
			ti.item_desc						[item_desc],
			ISNULL(tis.is_serial,'')			[is_serial],
			trdai.rmaa_qty						[rmaa_qty],
			tpli.prli_price						[item_price],
			tc.curr_symbol						[curr_symbol],
			0									[order],
			(tpli.prli_price * dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,ti.item_id)))[item_pricewithtax]

			FROM tbRMA_Detail_AddItems			trdai			WITH (NOLOCK)
			INNER JOIN tbItem					ti				WITH (NOLOCK)
				ON	ti.comp_id		= trdai.comp_id	AND
					ti.item_id		= trdai.item_id
			LEFT JOIN tbItemSerials			tis					WITH (NOLOCK)
				ON	tis.comp_id		= trdai.comp_id	AND
					tis.is_id		= trdai.is_id
			LEFT JOIN tbPriceListItems			tpli			WITH (NOLOCK)
				ON	tpli.comp_id	= trdai.comp_id	AND
					tpli.prli_id	= @prli_id4RMA	AND
					tpli.item_id	= trdai.item_id
			LEFT JOIN tbsysCurrency				tc				WITH (NOLOCK)
				ON	tc.curr_id		= tpli.curr_id
			WHERE	trdai.comp_id	= @comp_id		AND
					trdai.rmah_id	= @rma
			--ORDER BY trdai.rmaa_order
		-- -------------------------------------------------


		UNION ALL


		SELECT
			(SELECT tut.utexts_desc
			FROM tbsysUniqueTexts tut
			WHERE tut.lang_id = @lang_id AND tut.utexts_id = 203)		[item_code],
			''									[item_desc],
			''									[is_serial],
			tait.qty							[rmaa_qty],
			tait.price							[item_price],
			tait.curr_symbol					[curr_symbol],
			1									[order],
			tait.pricewihtax					[item_pricewithtax]

			FROM	@tmpAdditionalItemsTotals					tait

			ORDER BY [order]

END
GO




CREATE procedure [dbo].[spRMA_getReport3]
(
  @comp_id			int,
  @lang_id			int,
  @page_id			Int,
  @rma				int,
  @prof_id			int,
  @bra_id			int
)
as

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- - -----------------------------------------
	-- Testing
	-- - -----------------------------------------
	/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			Int,
			@rma				INT,
			@prof_id			INT,
			@bra_id				INT

	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10040,
			@rma				= 1121,
			@prof_id			= 1,
			@bra_id				= 1


	--DROP TABLE #tmpAdditionalItems_Totals
	*/
	-- - -----------------------------------------


	-- -----------------------------------------------
	-- CUENTO SI TIENE ARTÍCULOS ADICIONALES EL RMA
		DECLARE
			@AdditionalItems4RMA_Count	INT

		SELECT
			@AdditionalItems4RMA_Count	 = COUNT(*)
			FROM tbRMA_Detail_AddItems		trai
			WHERE	trai.comp_id = @comp_id AND
					trai.rmah_id = @rma

	-- -----------------------------------------------



	--Cabecera

	set DATEFORMAT 'ymd'

	Declare @bra INT
	Set @bra = (Select bra_id
				From tbRMA_Header trh
				Where trh.comp_id	= @comp_id
				And   trh.rmah_id   = @rma)

	-- Guardo el cliente del rma para saber en el detalle si el rma es de cliente o proveedor.
	Declare @cust INT
	Set @cust = (SELECT trh.cust_id
				From tbRMA_Header trh
				Where trh.comp_id	= @comp_id
				And   trh.rmah_id   = @rma)


	--Recupero en una variable el estado en controles por perfil . 0 - No Habilitado . 1 - Habilitado
	Declare @ctrl_price_cust INT
	Set @ctrl_price_cust = 1
	IF EXISTS(

					select 1
						from tbControlProfiles			WITH (NOLOCK)
						where	comp_id			= @comp_id	AND
								bra_id			= @bra		AND
								prof_id			= @prof_id	AND
								page_id			= 80000		AND
								ctrl_id			= 2784

				 )

			BEGIN

				Set @ctrl_price_cust = 0

			END

	Declare @ctrl_price_supp INT
	Set @ctrl_price_supp = 1
	IF EXISTS(

					select 1
						from tbControlProfiles			WITH (NOLOCK)
						where	comp_id			= @comp_id	AND
								bra_id			= @bra		AND
								prof_id			= @prof_id  AND
								page_id			= 80000		AND
								ctrl_id			= 2785

				 )

			BEGIN

				Set @ctrl_price_supp = 0

			END




	declare @bra_SaleOrderPricePlusTax	bit

	set @bra_SaleOrderPricePlusTax = (select isnull(tb.bra_SaleOrderPricePlusTax,'false')
									  from tbBranch					tb
									  where tb.comp_id = @comp_id
									  and   tb.bra_id  = @bra)

	---select @bra_SaleOrderPricePlusTax
	---Select @bra


	Select
			--customer
			CASE WHEN tc.cust_id IS NULL THEN ''
				ELSE '(' + convert(varchar,tc.cust_id) + ') - ' + ISNULL(tc.cust_name,'')
			END									[cust_name],
			tb.bra_desc,
			tc.cust_taxNumber ,
			tc.cust_address ,
			tc.cust_zip,
			tc.cust_city,
			tc.cust_Phone1,
			--supplier
			CASE WHEN ts.supp_id IS NULL THEN ''
				ELSE '(' + convert(varchar,ts.supp_id) + ') - ' + isnull(ts.supp_name,'')
			END									[supp_name],
			ts.supp_taxNumber,
			ts.supp_address,
			ts.supp_zip,
			ts.supp_city,
			ts.supp_Phone1,
			trh.rmah_isEditing,
			trh.rmah_cd,
			convert(VARCHAR,trh.rmah_id) [rmah_isEditingCD],
			isnull(td.dl_name,'')		 [dl_name],
			ISNULL(tc.cust_phone4RMA,'') [cust_phone4RMA], --,trn.rn_note,trn.rn_order
			@AdditionalItems4RMA_Count	[AdditionalItems4RMACount],

			-- -----------------------------------------------------------
			-- TICKET #3546 PEDIDO POR SINTAGMA
			-- -----------------------------------------------------------
			ISNULL(tb.bra_address,'')			[bra_address],
			ISNULL(tb.bra_zip, '')				[bra_zip],
			ts2.state_desc,
			ISNULL(tb.bra_phone,'')				[bra_phone],
			ISNULL(tb.bra_taxNumber,'')			[bra_taxNumber],
			ISNULL(tb.bra_taxNumber2,'')		[bra_taxNumbe2],
			ISNULL(tb.bra_taxNumber3,'')		[bra_taxNumber3]
			-- -----------------------------------------------------------



	FROM	dbo.tbRMA_Header						trh		WITH (NOLOCK)

			Inner Join tbCompany					tc2		WITH (NOLOCK)
			On	tc2.comp_id	= trh.comp_id

			left Join tbCustomer					tc		WITH (NOLOCK)
			On  tc.comp_id	= trh.comp_id
			And tc.cust_id	= trh.cust_id

			left Join tbSupplier					ts		WITH (NOLOCK)
			On  ts.comp_id	= trh.comp_id
			and ts.supp_id	= trh.supp_id

			Inner Join tbBranch						tb		WITH (NOLOCK)
			On	tb.comp_id	= trh.comp_id
			And tb.bra_id	= trh.bra_id

			LEFT JOIN tbDelivery					td		WITH (NOLOCK)
			ON	td.comp_id	= tc.comp_id AND
				td.dl_id	= tc.dl_id

			INNER JOIN tbsysState					ts2		WITH(NOLOCK)
			ON	ts2.country_id	= tb.country_id		AND
				ts2.state_id	= tb.state_id



	Where	trh.comp_id = trh.comp_id
	And		trh.rmah_id = @rma

	--Order By rn_order




	--Detalle
	Select	trd.rmah_id,
			ti.item_id,
	   		case when ti.item_id is not null then
				convert(varchar,ti.item_id) + ' - ' + ti.item_code + ' - '+ ti.item_desc
			else
				trd.rmad_Manual
			end [item_desc],
			isnull(tis.is_serial,'') [is_serial],
			trd.rmad_qty,

			CASE WHEN @cust IS NULL THEN
				case when @ctrl_price_supp = 1 then

						convert(varchar,tc.curr_symbol) +

						case when @bra_SaleOrderPricePlusTax = 'true'
							then
								convert(varchar,trd.rmad_originalPrice + (trd.rmad_originalPrice * isnull(ttn.tax_percentage,0) / 100))
							else
								convert(varchar,trd.rmad_originalPrice)
						END
				ELSE
						convert(varchar,'')
				end

				ELSE
					case when @ctrl_price_cust = 1 then

							convert(varchar,tc.curr_symbol) +

							case when @bra_SaleOrderPricePlusTax = 'true'
								then
									convert(varchar,trd.rmad_originalPrice + (trd.rmad_originalPrice * isnull(ttn.tax_percentage,0) / 100))
								else
									convert(varchar,trd.rmad_originalPrice)
							END
					ELSE
							convert(varchar,'')
					end

				END


			[rmafp_Price],

			ts.stor_desc,
			tc.curr_desc,
			tc.curr_symbol																				[curr_symbol],

			isnull(trd.rmad_DiagnosticNote,'')															[rmad_DiagnosticNote], -- es estado de rma pero lo agregamos en esta columna q se borró para no tener que agregar otra neuva
			isnull(trd.rmad_ReceptionNote,''),


			tu.user_firstname,
			trd.rmad_ProcNote,
			convert(VARCHAR,trd.rmad_id)																[rmad_id],
			max(tct.ct_date)																			[ct_date],

			--trd.user_id_Reception,
			isnull(tu.user_nick,'')																		[user_nick_Reception],
			trd.rmad_Date_Reception																		[rmad_Date_Reception],

		   --trd.user_id_Diagnostic,
		   isnull(tu2.user_nick,'')																		[user_nick_Diag],
		   trd.rmad_Date_Diagnostic																		[rmad_Date_Diagnostic],

		   --trd.user_id_Proc,
		   isnull(tu3.user_nick,'')																		[user_nick_Proc],
		   trd.rmad_Date_Proc																			[rmad_Date_Proc],

		   --trd.user_id_Delivery
		   isnull(tu4.user_nick, '')																	[user_nick_Delivery],
		   trd.rmad_Date_Delivery																		[rmad_Date_Delivery],
		   dbo.fnRMAHeader_getReportDetail_GetNC_Rm(trd.comp_id, trd.rmah_id, trd.rmad_id,@lang_id)		[Document4Cancel],
		   isnull(trwt.rmaw_desc,'')																	[rmaw_desc],
		   ISNULL(trfp.rmafp_desc,'')																	[rmafp_desc],
		   CONVERT(DECIMAL(19,2),ISNULL(trfp.rmafp_price,0))											[rmafp_priceFP],
		   isnull(trd.rmad_serial,'')																	[rmad_serial],
		   ISNULL(tov.optval_desc,'')																	[rmad_SheetDeliveryStatus],
		   isnull(trs.rmas_desc,'')																		[rmas_desc],
		   isnull(trt.srpt_desc,'')																		[srpt_desc],
		   CONVERT(VARCHAR(4),trt.srpt_desc,4)															[srpt_desc_Code],
		   isnull(trfailp.rmafailP_desc,'')																[rmafailP_desc],
		   dbo.fnGetEAN_Encode4EAN13(dbo.fnStrPADL(dbo.fnGetOnlyNumbers(ISNULL(tie.ie_ean,ti.item_code)),13, '0'),'False')	[item_code]

	From	tbRMA_Detail							trd			WITH (NOLOCK)

			left Join tbItem						ti			WITH (NOLOCK)
			On  ti.comp_id			= trd.comp_id
			And ti.item_id			= trd.item_id

			LEFT JOIN tbItemEAN						tie			WITH (NOLOCK)
			ON	tie.comp_id				= ti.comp_id	AND
				tie.item_id				= ti.item_id

			left Join tbItemSerials					tis			WITH (NOLOCK)
			ON  tis.comp_id			= trd.comp_id
			And tis.is_id			= trd.is_id
			And tis.item_id			= trd.item_id

			Inner Join tbStorage					ts			WITH (NOLOCK)
			On  ts.comp_id			= trd.comp_id
			And ts.stor_id			= trd.stor_id

			LEFT JOIN tbRMA_FailedPart				trfailp		WITH (NOLOCK)
			ON  trfailp.comp_id		= trd.comp_id
			AND trfailp.rmafailP_id	= trd.rmafailP_id

			Inner Join tbsysCurrency				tc			WITH (NOLOCK)
			On	tc.curr_id			= trd.curr_id

			Inner Join tbUser						tu			WITH (NOLOCK)
			On	tu.[user_id]		= trd.user_id_Reception

			Inner Join tbsysRMAProcType				trt			WITH (NOLOCK)
			On	trt.srpt_id			= trd.srpt_id

			LEFT JOIN tbItemTransactionSerials		tits		WITH (NOLOCK)
			ON	tits.comp_id		= trd.comp_id
			AND tits.is_id			= trd.is_id

			LEFT JOIN tbCommercialTransactions		tct			WITH (NOLOCK)
			ON	tct.comp_id			= trd.comp_id
			AND tct.bra_id			= tits.bra_id
			AND tct.ct_transaction	= tits.ct_transaction
			AND tct.sd_id			IN (1,101)

			left join vwItemTaxesOnlyOneIvaTax		vit			WITH (NOLOCK)
			on  vit.comp_id			= trd.comp_id
			and vit.item_id			= trd.item_id

			left join tbItemTaxes					tit			WITH (NOLOCK)
			on  tit.comp_id			= trd.comp_id
			and tit.item_id			= trd.item_id
			and vit.tax_id			= tit.tax_id

			left join tbTaxName						ttn			WITH (NOLOCK)
			on  ttn.comp_id			= trd.comp_id
			and ttn.tax_id			= vit.tax_id

			--STL GRUPO NUCLEO JOINS PARA USUARIOS

	--		LEFT JOIN tbUser						tu
	--		ON tu.user_id	 = trd.user_id_Reception

			LEFT JOIN tbUser						tu2			WITH (NOLOCK)
			ON tu2.user_id	 = trd.user_id_Diagnostic

			LEFT JOIN tbUser						tu3			WITH (NOLOCK)
			ON tu3.user_id	 = trd.user_id_Proc

			LEFT JOIN tbUser						tu4			WITH (NOLOCK)
			ON tu4.user_id	 = trd.user_id_Delivery

			LEFT JOIN tbRMA_WarrantyType			trwt		WITH (NOLOCK)
			ON  trwt.comp_id = trd.comp_id		AND
				trwt.rmaw_id = trd.rmaw_id

			LEFT JOIN tbRMA_FixPrices				trfp		WITH(NOLOCK)
			ON	trfp.comp_id	= trd.comp_id		AND
				trfp.rmafp_id	= trd.rmafp_id

			LEFT JOIN tbsysOptionsValues				tov
			ON	tov.lang_id		= @lang_id				AND
				tov.optval_id	= trd.sds_id4Delivery	AND
				tov.optval_class= 711

			LEFT JOIN tbRMA_Status AS trs						WITH(NOLOCK)
			ON trs.comp_id	= trd.comp_id				AND
				trs.rmas_id = trd.rmas_id


	--		LEFT JOIN tbsysCurrency					tcFix
	--		ON tc.curr_id		= trfp.curr_id




	Where	trd.comp_id		= @comp_id
	And		trd.rmah_id		= @rma
	AND
				  (
				 	-- No tenga EAN Adicionales o..
				 	isnull(tie.ie_ean,'')		= ''
				 	OR
				 	-- Controla si tiene mas de un ItemEan que salga solo el primero
				 	tie.ie_ean	= (SELECT TOP 1 tie.ie_ean
									   FROM tbItemEAN				tie
									   WHERE ti.comp_id		= @comp_id AND
											 tie.item_id	= ti.item_id)
				  )


	GROUP BY trd.rmah_id,
			ti.item_id,
	   		 --when ti.item_id is not null then
			ti.item_code,
			ti.item_desc,
			--else
			trd.rmad_Manual,
			--end
			--[item_desc],
			--isnull(tis.is_serial,'')
			[is_serial],
			trd.rmad_qty,
			--convert(varchar,tc.curr_symbol) + convert(varchar,
			trd.rmad_originalPrice,
			--[rmafp_Price],
			ts.stor_desc,
			tc.curr_desc,
			trt.srpt_desc,
			[curr_symbol],

			trs.rmas_desc,
			trd.rmad_ReceptionNote,


			tu.user_firstname,
			trd.rmad_ProcNote,
			--convert(VARCHAR,trd.rmad_id)
			[rmad_id],
			ttn.tax_percentage,
			tu.user_nick,
			trd.rmad_Date_Reception,
			tu2.user_nick,
			trd.rmad_Date_Diagnostic,
			tu3.user_nick,
			trd.rmad_Date_Proc,
			tu4.user_nick,
			trd.rmad_Date_Delivery,
			trd.comp_id,
			trwt.rmaw_desc,
			trfp.rmafp_desc,
			trfp.rmafp_price,
			trd.rmad_serial,
			tov.optval_desc,
			trd.rmad_DiagnosticNote,
			trfailp.rmafailP_desc,tie.ie_ean

	order by trd.rmad_id


	EXEC spReports_getData3 @comp_id, @bra_id, @lang_id, @page_id, 1


	-- -------------------------------------------------
	-- rn_note
	-- -------------------------------------------------
	SELECT
		TOP 1
		trn.rn_note,
		trn.rn_order
		FROM	tbRmaNotes trn				WITH (NOLOCK)
		WHERE	trn.comp_id = @comp_id AND
				trn.bra_id	= @bra
		ORDER BY trn.rn_order
	-- -------------------------------------------------
	-- -------------------------------------------------

		DECLARE @prli_id4RMA	INT,
				@lcurr_id		INT


		SELECT
			@prli_id4RMA		= tb.bra_RMA_prli_id4AdditionalItems,
			@lcurr_id			= tb.curr_id
			FROM tbBranch		tb
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id

		-- -------------------------------------------------
		-- ARTÍCULOS ADICIONALES - TOTALES
		-- -------------------------------------------------
		DECLARE @tmpAdditionalItemsTotals TABLE(qty DECIMAL(19,4),price DECIMAL(19,4),curr_symbol nchar(10),pricewihtax DECIMAL(19,4))
		INSERT INTO @tmpAdditionalItemsTotals(qty,price,curr_symbol,pricewihtax)
		SELECT
			SUM(trdai.rmaa_qty)																							[rmaa_qty],
			SUM(convert(decimal(19,2),trdai.rmaa_qty * dbo.fnGetExchange2(@comp_id, tpli.prli_price, tc.curr_id, @lcurr_id, 0,0,0,0)))	[item_price],
			tc2.curr_symbol																								[curr_symbol],
			SUM(convert(decimal(19,2),trdai.rmaa_qty * dbo.fnGetExchange2(@comp_id, tpli.prli_price * dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,ti.item_id)), tc.curr_id, @lcurr_id, 0,0,0,0)))	[item_pricewithtax]

			--INTO #tmpAdditionalItems_Totals

			FROM tbRMA_Detail_AddItems			trdai		WITH (NOLOCK)
			INNER JOIN tbItem					ti			WITH (NOLOCK)
				ON	ti.comp_id		= trdai.comp_id	AND
					ti.item_id		= trdai.item_id
			LEFT JOIN tbPriceListItems			tpli		WITH (NOLOCK)
				ON	tpli.comp_id	= trdai.comp_id	AND
					tpli.prli_id	= @prli_id4RMA	AND
					tpli.item_id	= trdai.item_id
			LEFT JOIN tbsysCurrency				tc			WITH (NOLOCK)
				ON	tc.curr_id		= tpli.curr_id
			LEFT JOIN tbsysCurrency				tc2			WITH (NOLOCK)
				ON	tc2.curr_id		= @lcurr_id

			WHERE	trdai.comp_id	= @comp_id		AND
					trdai.rmah_id	= @rma

			GROUP BY tc2.curr_symbol


		-- -------------------------------------------------
		-- ARTÍCULOS ADICIONALES
		-- -------------------------------------------------

		SELECT
			ti.item_code						[item_code],
			ti.item_desc						[item_desc],
			ISNULL(tis.is_serial,'')			[is_serial],
			trdai.rmaa_qty						[rmaa_qty],
			tpli.prli_price						[item_price],
			tc.curr_symbol						[curr_symbol],
			0									[order],
			(tpli.prli_price * dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient(@comp_id,ti.item_id)))[item_pricewithtax]

			FROM tbRMA_Detail_AddItems			trdai			WITH (NOLOCK)
			INNER JOIN tbItem					ti				WITH (NOLOCK)
				ON	ti.comp_id		= trdai.comp_id	AND
					ti.item_id		= trdai.item_id
			LEFT JOIN tbItemSerials			tis					WITH (NOLOCK)
				ON	tis.comp_id		= trdai.comp_id	AND
					tis.is_id		= trdai.is_id
			LEFT JOIN tbPriceListItems			tpli			WITH (NOLOCK)
				ON	tpli.comp_id	= trdai.comp_id	AND
					tpli.prli_id	= @prli_id4RMA	AND
					tpli.item_id	= trdai.item_id
			LEFT JOIN tbsysCurrency				tc				WITH (NOLOCK)
				ON	tc.curr_id		= tpli.curr_id
			WHERE	trdai.comp_id	= @comp_id		AND
					trdai.rmah_id	= @rma
			--ORDER BY trdai.rmaa_order
		-- -------------------------------------------------


		UNION ALL


		SELECT
			(SELECT tut.utexts_desc
			FROM tbsysUniqueTexts tut
			WHERE tut.lang_id = @lang_id AND tut.utexts_id = 203)		[item_code],
			''									[item_desc],
			''									[is_serial],
			tait.qty							[rmaa_qty],
			tait.price							[item_price],
			tait.curr_symbol					[curr_symbol],
			1									[order],
			tait.pricewihtax					[item_pricewithtax]

			FROM	@tmpAdditionalItemsTotals					tait

			ORDER BY [order]

END
GO





CREATE procedure [dbo].[spRMA_getReportByItem]
(
  @comp_id			int,
  @lang_id			int,
  @page_id			Int,
  @bra_id			INT,
  @prof_id			int,
  @rmah_id			int,
  @rmad_id			int
)
as


BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	-- - -----------------------------------------
	-- Testing
	-- - -----------------------------------------
	/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			Int,
			@rma				INT,
			@prof_id			INT,
			@bra_id				INT,
			@item_id			INT,
			@rmad_id			INT

	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@page_id			= 10040,
			@rma				= 534,
			@prof_id			= 1,
			@bra_id				= 1,
			@item_id			= 231,
			@rmad_id			= 84030
	*/
	-- - -----------------------------------------
	--Cabecera

	set DATEFORMAT 'ymd'

	Declare @bra INT
	Set @bra = (Select bra_id
				From tbRMA_Header trh
				Where trh.comp_id	= @comp_id
				And   trh.rmah_id   = @rmah_id)

	-- Guardo el cliente del rma para saber en el detalle si el rma es de cliente o proveedor.
	Declare @cust INT
	Set @cust = (SELECT trh.cust_id
				From tbRMA_Header trh
				Where trh.comp_id	= @comp_id
				And   trh.rmah_id   = @rmah_id)


	--Recupero en una variable el estado en controles por perfil . 0 - No Habilitado . 1 - Habilitado
	Declare @ctrl_price_cust INT
	Set @ctrl_price_cust = 1
	IF EXISTS(

					select 1
						from tbControlProfiles			WITH (NOLOCK)
						where	comp_id			= @comp_id	AND
								bra_id			= @bra		AND
								prof_id			= @prof_id	AND
								page_id			= 80000		AND
								ctrl_id			= 2784

				 )

			BEGIN

				Set @ctrl_price_cust = 0

			END

	Declare @ctrl_price_supp INT
	Set @ctrl_price_supp = 1
	IF EXISTS(

					select 1
						from tbControlProfiles			WITH (NOLOCK)
						where	comp_id			= @comp_id	AND
								bra_id			= @bra		AND
								prof_id			= @prof_id  AND
								page_id			= 80000		AND
								ctrl_id			= 2785

				 )

			BEGIN

				Set @ctrl_price_supp = 0

			END




	declare @bra_SaleOrderPricePlusTax	bit

	set @bra_SaleOrderPricePlusTax = (select isnull(tb.bra_SaleOrderPricePlusTax,'false')
									  from tbBranch					tb
									  where tb.comp_id = @comp_id
									  and   tb.bra_id  = @bra)

	---select @bra_SaleOrderPricePlusTax
	---Select @bra


	Select
			--customer
			CASE WHEN tc.cust_id IS NULL THEN ''
				ELSE '(' + convert(varchar,tc.cust_id) + ') - ' + ISNULL(tc.cust_name,'')
			END									[cust_name],
			tb.bra_desc,
			tc.cust_taxNumber ,
			ISNULL(tc.cust_address,'')			[cust_address],
			ISNULL(tc.cust_zip,'')				[cust_zip],
			ISNULL(tc.cust_city,'')				[cust_city],
			ISNULL(tc.cust_Phone1,'')			[cust_Phone1],
			--supplier
			CASE WHEN ts.supp_id IS NULL THEN ''
				ELSE '(' + convert(varchar,ts.supp_id) + ') - ' + isnull(ts.supp_name,'')
			END									[supp_name],
			ts.supp_taxNumber,
			ISNULL(ts.supp_address,'')			[supp_address],
			ISNULL(ts.supp_zip,'')				[supp_zip],
			ISNULL(ts.supp_city,'')				[supp_city],
			ISNULL(ts.supp_Phone1,'')			[supp_Phone1],


			trh.rmah_isEditing,
			trh.rmah_cd,
			convert(VARCHAR,trh.rmah_id) [rmah_isEditingCD],
			isnull(td.dl_name,'')		 [dl_name] --,trn.rn_note,trn.rn_order



	FROM	dbo.tbRMA_Header						trh		WITH (NOLOCK)

			Inner Join tbCompany					tc2		WITH (NOLOCK)
			On	tc2.comp_id	= trh.comp_id

			left Join tbCustomer					tc		WITH (NOLOCK)
			On  tc.comp_id	= trh.comp_id
			And tc.cust_id	= trh.cust_id

			left Join tbSupplier					ts		WITH (NOLOCK)
			On  ts.comp_id	= trh.comp_id
			and ts.supp_id	= trh.supp_id

			Inner Join tbBranch						tb		WITH (NOLOCK)
			On	tb.comp_id	= trh.comp_id
			And tb.bra_id	= trh.bra_id

			LEFT JOIN tbDelivery					td		WITH (NOLOCK)
			ON	td.comp_id	= tc.comp_id AND
				td.dl_id	= tc.dl_id



	Where	trh.comp_id = trh.comp_id
	And		trh.rmah_id = @rmah_id

	--Order By rn_order




	--Detalle
	Select	trd.rmah_id,
			ti.item_id,
	   		case when ti.item_id is not null then
				convert(varchar,ti.item_id) + ' - ' + ti.item_code + ' - '+ ti.item_desc
			else
				trd.rmad_Manual
			end [item_desc],
			isnull(tis.is_serial,'') [is_serial],
			trd.rmad_qty,

			CASE WHEN @cust IS NULL THEN
				case when @ctrl_price_supp = 1 then

						convert(varchar,tc.curr_symbol) +

						case when @bra_SaleOrderPricePlusTax = 'true'
							then
								convert(varchar,trd.rmad_originalPrice + (trd.rmad_originalPrice * isnull(ttn.tax_percentage,0) / 100))
							else
								convert(varchar,trd.rmad_originalPrice)
						END
				ELSE
						convert(varchar,'')
				end

				ELSE
					case when @ctrl_price_cust = 1 then

							convert(varchar,tc.curr_symbol) +

							case when @bra_SaleOrderPricePlusTax = 'true'
								then
									convert(varchar,trd.rmad_originalPrice + (trd.rmad_originalPrice * isnull(ttn.tax_percentage,0) / 100))
								else
									convert(varchar,trd.rmad_originalPrice)
							END
					ELSE
							convert(varchar,'')
					end

				END


			[rmafp_Price],

			ts.stor_desc,
			tc.curr_desc,
			trt.srpt_desc [curr_symbol],

			trd.rmad_DiagnosticNote,
			trd.rmad_ReceptionNote,


			tu.user_firstname,
			trd.rmad_ProcNote,
			convert(VARCHAR,trd.rmad_id)																[rmad_id],
			max(tct.ct_date)																			[ct_date],

			--trd.user_id_Reception,
			isnull(tu.user_nick,'')																		[user_nick_Reception],
			trd.rmad_Date_Reception																		[rmad_Date_Reception],

		   --trd.user_id_Diagnostic,
		   isnull(tu2.user_nick,'')																		[user_nick_Diag],
		   trd.rmad_Date_Diagnostic																		[rmad_Date_Diagnostic],

		   --trd.user_id_Proc,
		   isnull(tu3.user_nick,'')																		[user_nick_Proc],
		   trd.rmad_Date_Proc																			[rmad_Date_Proc],

		   --trd.user_id_Delivery
		   isnull(tu4.user_nick, '')																	[user_nick_Delivery],
		   trd.rmad_Date_Delivery																		[rmad_Date_Delivery],
		   dbo.fnRMAHeader_getReportDetail_GetNC_Rm(trd.comp_id, trd.rmah_id, trd.rmad_id,@lang_id)		[Document4Cancel],
		   isnull(trwt.rmaw_desc,'')																	[rmaw_desc]


	From	tbRMA_Detail							trd			WITH (NOLOCK)

			left Join tbItem						ti			WITH (NOLOCK)
			On  ti.comp_id			= trd.comp_id
			And ti.item_id			= trd.item_id

			left Join tbItemSerials					tis			WITH (NOLOCK)
			ON  tis.comp_id			= trd.comp_id
			And tis.is_id			= trd.is_id
			And tis.item_id			= trd.item_id

			Inner Join tbStorage					ts			WITH (NOLOCK)
			On  ts.comp_id			= trd.comp_id
			And ts.stor_id			= trd.stor_id

			Inner Join tbsysCurrency				tc			WITH (NOLOCK)
			On	tc.curr_id			= trd.curr_id

			Inner Join tbUser						tu			WITH (NOLOCK)
			On	tu.[user_id]		= trd.user_id_Reception

			Inner Join tbsysRMAProcType				trt			WITH (NOLOCK)
			On	trt.srpt_id			= trd.srpt_id

			LEFT JOIN tbItemTransactionSerials		tits		WITH (NOLOCK)
			ON	tits.comp_id		= trd.comp_id
			AND tits.is_id			= trd.is_id

			LEFT JOIN tbCommercialTransactions		tct			WITH (NOLOCK)
			ON	tct.comp_id			= trd.comp_id
			AND tct.bra_id			= tits.bra_id
			AND tct.ct_transaction	= tits.ct_transaction
			AND tct.sd_id			IN (1,101)

			left join vwItemTaxesOnlyOneIvaTax		vit			WITH (NOLOCK)
			on  vit.comp_id			= trd.comp_id
			and vit.item_id			= trd.item_id

			left join tbItemTaxes					tit			WITH (NOLOCK)
			on  tit.comp_id			= trd.comp_id
			and tit.item_id			= trd.item_id
			and vit.tax_id			= tit.tax_id

			left join tbTaxName						ttn			WITH (NOLOCK)
			on  ttn.comp_id			= trd.comp_id
			and ttn.tax_id			= vit.tax_id

			--STL GRUPO NUCLEO JOINS PARA USUARIOS

	--		LEFT JOIN tbUser						tu
	--		ON tu.user_id	 = trd.user_id_Reception

			LEFT JOIN tbUser						tu2			WITH (NOLOCK)
			ON tu2.user_id	 = trd.user_id_Diagnostic

			LEFT JOIN tbUser						tu3			WITH (NOLOCK)
			ON tu3.user_id	 = trd.user_id_Proc

			LEFT JOIN tbUser						tu4			WITH (NOLOCK)
			ON tu4.user_id	 = trd.user_id_Delivery

			LEFT JOIN tbRMA_WarrantyType			trwt		WITH (NOLOCK)
			ON  trwt.comp_id = trd.comp_id		AND
				trwt.rmaw_id = trd.rmaw_id




	Where	trd.comp_id		= @comp_id	AND
			trd.rmah_id		= @rmah_id	AND
			trd.rmad_id		= @rmad_id

	GROUP BY trd.rmah_id,
			ti.item_id,
	   		 --when ti.item_id is not null then
			ti.item_code,
			ti.item_desc,
			--else
			trd.rmad_Manual,
			--end
			--[item_desc],
			--isnull(tis.is_serial,'')
			[is_serial],
			trd.rmad_qty,
			--convert(varchar,tc.curr_symbol) + convert(varchar,
			trd.rmad_originalPrice,
			--[rmafp_Price],
			ts.stor_desc,
			tc.curr_desc,
			trt.srpt_desc,
			[curr_symbol],

			trd.rmad_DiagnosticNote,
			trd.rmad_ReceptionNote,


			tu.user_firstname,
			trd.rmad_ProcNote,
			--convert(VARCHAR,trd.rmad_id)
			[rmad_id],
			ttn.tax_percentage,
			tu.user_nick,
			trd.rmad_Date_Reception,
			tu2.user_nick,
			trd.rmad_Date_Diagnostic,
			tu3.user_nick,
			trd.rmad_Date_Proc,
			tu4.user_nick,
			trd.rmad_Date_Delivery,trd.comp_id,trwt.rmaw_desc

	order by trd.rmad_id

	--PONEMOS EL ID DE LA PAGINA EN DURO PARA QUE COPIE LOS TEXTOS DEL REPORTE ORIGINAL Y NO TENER QUE VOLVER A CARGARLOS
	EXEC spReports_getData3 @comp_id, @bra_id, @lang_id, 10040, 1


	Select	TOP 1
			trn.rn_note,
			trn.rn_order

	From	tbRmaNotes trn				WITH (NOLOCK)

	Where	trn.comp_id = @comp_id
	And		trn.bra_id	= @bra

	Order By trn.rn_order



END
GO




CREATE PROCEDURE [dbo].[spRMA_GetRMA2Assign]
(
	@comp_id		INT,
	@cust_id		INT,
	@item_id		INT,
	@datefrom		DATETIME,
	@dateto			DATETIME,
	@isCustomer		BIT
)
AS

SET NOCOUNT ON

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	SET DATEFORMAT 'ymd'

	-- ------------------------------------
	-- TESTING
	-- ------------------------------------
	/*
		DECLARE
			@comp_id		INT,
			@cust_id		INT,
			@item_id		INT,
			@datefrom		DATETIME,
			@dateto			DATETIME,
			@isCustomer		BIT

		SELECT
			@comp_id		= 1,
			@cust_id		= 24294,
			@item_id		= 492,
			@datefrom		= '2014-01-01',
			@dateto			= '2015-12-31',
			@isCustomer		= 'True'
	*/
	-- ------------------------------------

	IF @isCustomer = 'True'

		BEGIN

			SELECT
				' '														[ ],
				tc.cust_name,
				ti.item_code,
				ti.item_desc,
				trd.rmad_qty,
				ts.stor_desc,
				trh.rmah_cd,
				ISNULL(tu.user_lastname + ',' + tu.user_firstname,'')	[User],
				ISNULL(trt.srpt_desc,'')								[srpt_desc],

				CONVERT(VARCHAR,trd.rmad_id)			+ '-' +
				CONVERT(VARCHAR,trd.rmah_id)							[ID]
			FROM tbRMA_Header						trh

				LEFT JOIN tbRMA_Detail				trd
					ON	trd.comp_id = trh.comp_id	AND
						trd.rmah_id = trh.rmah_id

				LEFT JOIN tbItem					ti
					ON	ti.comp_id	= trd.comp_id	AND
						ti.item_id	= trd.item_id

				INNER JOIN	tbCustomer				tc
					ON	tc.comp_id	= trh.comp_id	AND
						tc.cust_id	= trh.cust_id

				LEFT JOIN tbStorage					ts
					ON	ts.comp_id	= tc.comp_id	AND
						ts.stor_id	= trd.stor_id

				LEFT JOIN tbUser					tu
					ON tu.[user_id]	= trd.user_id_Proc

				LEFT JOIN tbsysRMAProcType			trt
					ON trt.srpt_id	= trd.srpt_id


			WHERE	trh.comp_id = @comp_id			AND
					trh.cust_id = @cust_id			AND
					(@item_id	= -1 OR trd.item_id	= @item_id)	AND
					trh.rmah_cd BETWEEN @datefrom AND @dateto

			ORDER BY trh.rmah_cd	ASC

		END

	ELSE

		BEGIN

			SELECT
				' '														[ ],
				tc.cust_name,
				ti.item_code,
				ti.item_desc,
				trd.rmad_qty,
				ts.stor_desc,
				trh.rmah_cd,
				ISNULL(tu.user_lastname + ',' + tu.user_firstname,'')	[User],
				ISNULL(trt.srpt_desc,'')								[srpt_desc],
				CONVERT(VARCHAR,trd.rmad_id)			+ '-' +
				CONVERT(VARCHAR,trd.rmah_id)							[ID]

			FROM tbRMA_Header						trh

				LEFT JOIN tbRMA_Detail				trd
					ON	trd.comp_id = trh.comp_id	AND
						trd.rmah_id = trh.rmah_id

				LEFT JOIN tbItem					ti
					ON	ti.comp_id	= trd.comp_id	AND
						ti.item_id	= trd.item_id

				INNER JOIN tbCustomer				tc
					ON	tc.comp_id	= trh.comp_id	AND
						tc.cust_id	= trh.cust_id

				LEFT JOIN tbStorage					ts
					ON	ts.comp_id	= tc.comp_id	AND
						ts.stor_id	= trd.stor_id

				LEFT JOIN tbUser					tu
					ON tu.[user_id]	= trd.user_id_Proc

				LEFT JOIN tbsysRMAProcType			trt
					ON trt.srpt_id	= trd.srpt_id

			WHERE	trh.comp_id = @comp_id			AND
					trd.srpt_id IN (100,110)		AND
					(@cust_id	= -1 OR tc.cust_id = @cust_id)	AND
					(@item_id	= -1 OR trd.item_id	= @item_id)	AND
					trh.rmah_cd BETWEEN @datefrom AND @dateto

		END


END





GO





CREATE procedure [dbo].[spRMA_HasProcData4Delete]
(
	@comp_id	int,
	@rmah_id	INT
)

AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- ---------------------------------------
		-- TESTING
		-- ---------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@rmah_id	INT
			SELECT
				@comp_id	= 1,
				@rmah_id	= 536
		*/
		-- ---------------------------------------

		DECLARE @HasProc	INT
		SET		@HasProc	= 0

		IF EXISTS (SELECT
					1
					FROM tbRMA_Header						trh
					INNER JOIN tbRMA_Detail					trd
						ON		trd.comp_id = trh.comp_id	AND
								trd.rmah_id = trh.rmah_id
					WHERE	trh.comp_id		= @comp_id		AND
							trh.rmah_id		= @rmah_id		AND
							trd.srpt_id		<> 1
				  )
			BEGIN
				SET @HasProc = @HasProc + 1
			END
		ELSE
			BEGIN
				SET @HasProc = @HasProc + 0
			END

		IF EXISTS (SELECT
					1
					FROM tbRMA_BranchTransfers		trbt
					WHERE	trbt.comp_id = @comp_id AND
							trbt.rmah_id = @rmah_id)
			BEGIN
				SET @HasProc = @HasProc + 1
			END
		ELSE
			BEGIN
				SET @HasProc = @HasProc + 0
			END

		--DEVOLVEMOS EL RESULTADO
		SELECT @HasProc
	END
GO

CREATE PROCEDURE [dbo].[spRMA_Header_UpdateHeaderImage]
(
	@comp_id			INT,
	@lang_id			INT,
	@rmah_id			INT,
	@rmah_image			IMAGE
)
AS
	BEGIN
		SET NOCOUNT ON

		UPDATE tbRMA_Header
		SET rmah_image = @rmah_image
		WHERE	comp_id = @comp_id AND
				rmah_id = @rmah_id

	END
GO




CREATE PROCEDURE [dbo].[spRMA_Header_UpdateNewData]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,

	@rmap_id			INT,
	@user_id_assigned	INT,
	@rmah_id			INT
)

AS

	SET NOCOUNT ON

		BEGIN

			IF @user_id_assigned	= -1 SET @user_id_assigned	= NULL
			IF @rmap_id				= -1 SET @rmap_id			= NULL

			UPDATE tbRMA_Header
			SET
				rmap_id				= @rmap_id,
				user_id_assigned	= @user_id_assigned

			WHERE	comp_id = @comp_id AND
					rmah_id = @rmah_id

		END

GO


-- MOS 08-2009
CREATE  PROCEDURE [dbo].[spRMA_insertData]
(
	@rmadt_guid					UNIQUEIDENTIFIER,
	@comp_id					INT,
	@bra_id						INT,
	@cust_id					INT,
	@supp_id					INT,
	@rmah_cd					DATETIME,
	@user_id					INT,
	@rmah_isInSuppplier			BIT,
	@rmah_note1					NVARCHAR(2000),
	@rmah_note2					NVARCHAR(2000),
	@return_value				INT OUTPUT,
	@return_error				INT OUTPUT
)
AS

BEGIN



	SET NOCOUNT ON

	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*
	DECLARE @rmadt_guid					uniqueidentifier,
			@comp_id					int,
			@bra_id						int,
			@cust_id					int,
			@supp_id					INT,
			@rmah_cd					datetime,
			@user_id					INT,
			@return_value				int

	SELECT	@rmadt_guid					='9948a6a6-88e3-4833-8e80-1f1cad7aa9a8',--'9f0fc0c6-46f8-4666-9760-d6410aef92bb',
			@comp_id					= 1,
			@bra_id						= 1,
			@cust_id					= null,
			@supp_id					= 8103,
			@rmah_cd					= GETDATE(),
			@user_id					= 1
	*/
	-- ----------------------------------------------------------------


	-- ----------------------------------------------------------------
	-- Forros de FIESA y LPMQLP, quieren por CAPRICHO que si se ingresan desde el sitio web se acumulen x día.
	-- Para NO romper nada paso el parámetro de CLIENTE en negativo desde VS  **ewflkn0927340adnqwldkn
	-- ----------------------------------------------------------------
	DECLARE @bitFromWebSite AS BIT = 'False'
	IF @cust_id < 0
		BEGIN
			SET @cust_id		= @cust_id * -1
			SET @bitFromWebSite = 'True'
		END
	-- ----------------------------------------------------------------


	SET @return_value = 0
	SET @return_error = 0

	DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT		-- MOS 06-2020
    --SAVE TRANSACTION traPROTECT
    --BEGIN TRANSACTION
    BEGIN TRY



			-- ------------------------------------
			-- Bloquear la base antes de hacer nada
			-- ------------------------------------
			-- MOS 05-2022: Se comentó x tema performance
			--DECLARE @intLock AS INT
			--SELECT @intLock = tce.sb_id
			--	FROM tbsysBlockPage4IsoTran  tce
			-- ------------------------------------


		DECLARE @lrma_id INT = null
		DECLARE @intError AS INT


		IF @bitFromWebSite = 'True'  -- Forros de FIESA
			BEGIN
				-- Busco si YA hay un RMA para el día de hoy dado de alta. Si hay de debe insertar el nuevo item dentro del MISMO RMA
				SELECT @lrma_id = trh.rmah_id
					FROM tbRMA_Header AS trh	WITH (NOLOCK)
					WHERE	trh.comp_id = @comp_id		AND
							trh.bra_id	= @bra_id		AND
							trh.cust_id = @cust_id		AND
							DAY(trh.rmah_cd)	= DAY(GETDATE())	AND
							MONTH(trh.rmah_cd)	= MONTH(GETDATE())	AND
							YEAR(trh.rmah_cd)	= YEAR(GETDATE())

				IF @lrma_id IS NULL
					BEGIN
						insert into dbo.tbRMA_Header	WITH (ROWLOCK)
						(
							comp_id,
							bra_id,
							cust_id,
							supp_id,
							rmah_cd,
							rmah_isInSuppplier,
							rmah_note1,
							rmah_note2
						)
						values
						(
							@comp_id,
							@bra_id,
							@cust_id,
							@supp_id,
							@rmah_cd,
							@rmah_isInSuppplier,
							@rmah_note1,
							@rmah_note2
						)
						SET @lrma_id = @@identity
					END
			END
		ELSE	-- Como estaba pára todo el resto.
			BEGIN
				-- insertar datos en el Header de RMA
				EXEC dbo.spRMAHeader_insertData
						@comp_id,		@bra_id,
						@cust_id,		@supp_id,
						@rmah_cd,		@rmah_isInSuppplier,
						@rmah_note1,	@rmah_note2,
						@return_value = @lrma_id OUTPUT
			END


		IF	(@@ERROR = 0 AND @@ROWCOUNT = 1)
				OR
			 @bitFromWebSite = 'True' -- FIESA
			BEGIN

			DECLARE @intCustId AS INT =
										@cust_id *	CASE	-- Para que AGREGUE al DETAIL del RMA
														WHEN @bitFromWebSite = 'True' THEN -1
														ELSE								1
													END

				--proceso general de actualizaciones de RMA dependiendo de los estados
				EXEC dbo.spRMA_updateCommonData
						@comp_id,		@bra_id,
						@lrma_id,		@rmadt_guid,
						/*@cust_id*/
						@intCustId,		@supp_id,
						@rmah_cd,		@user_id,
						@return_value = @intError

			END


		-- retornar el valor del id insertado en la cabecera
		--	IF @intError = 0 SET @return_value = @lrma_id
		--	ELSE SET @return_value = @intError
		SET @return_value = @lrma_id


--==
--SELECT 1 / 0
--set @return_error = 10
--==

    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT
        IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT		-- MOS 06-2020
        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
   -- IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT


END
GO




create PROCEDURE [dbo].[spRMA_insertData_new]
(
	@rmadt_guid					UNIQUEIDENTIFIER,
	@comp_id					INT,
	@bra_id						INT,
	@cust_id					INT,
	@supp_id					INT,
	@rmah_cd					DATETIME,
	@user_id					INT,
	@return_value				INT OUTPUT
)
AS
SET NOCOUNT ON
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-08-02
-- Parte		: 420
-- Description	: Para cumplir el requerimiento solicitado, se modificó para que cuando el estado del RMA sea 10,20,
--				  30 o 40 queden los pedidos cerrados (ssos_id=201) y se carguen los seriales en tbSaleOrderSerials
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-08-06
-- Parte		: 448
-- Description	: Para cumplir el requerimiento solicitado, se actualiza el campo soh_isediting al valor 'False',
--				  luego de la actualización de tbSaleOrderSerials, porque el spSaleOrderSerials_insertData lo pone
--				  por defecto en 'True'
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-08-06
-- Parte		: 457
-- Description	: Se actualiza el ssos_id a 201 cuando el srpt_id = 35
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-09-16
-- Parte		: S/P Referencia: #1
-- Description	: Se cambia el orden de las monedas para la obtención del @ExchangeToCustomerCurrency
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-10-18
-- Parte		: S/P Referencia: #2
-- Description	: Se cambia lo realizado por el parte 457 y se actualiza el ssos_id a 200 cuando el srpt_id es 35
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2011-01-18
-- Parte		: S/P Referencia: #3
-- Description	: Se modifica la descripción del artículo cuando se realiza la actualización de Pedidos y el
--				  artículo es Manual
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2011-03-15
-- Parte		: 854
-- Description	: Para las opciones "Funciona MAL - Se cambia por igual mercadería -35" y
--				  "Funciona MAL - Se efectúa Nota de Crédito -40" se debe realizar la misma actualización que el estado
--				  "Funciona OK - Se devuelve al Depósito -70", esto es, se debe reingresar el artículo al stock y
--				  si estaba tomado un serial se debe liberar para un próximo uso.
-- =================================================================================================================





/*
DECLARE @rmadt_guid					uniqueidentifier,
		@comp_id					int,
		@bra_id						int,
		@cust_id					int,
		@supp_id					INT,
		@rmah_cd					datetime,
		@user_id					INT,
		@return_value				int


SELECT	@rmadt_guid					='9948a6a6-88e3-4833-8e80-1f1cad7aa9a8',--'9f0fc0c6-46f8-4666-9760-d6410aef92bb',
		@comp_id					= 1,
		@bra_id						= 1,
		@cust_id					= null,
		@supp_id					= 8103,
		@rmah_cd					= GETDATE(),
		@user_id					= 1


*/



DECLARE @lrma_id INT

-- insertar datos en el Header de RMA
EXEC dbo.spRMAHeader_insertData
		@comp_id,		@bra_id,
		@cust_id,		@supp_id,
		@rmah_cd,		@return_value = @lrma_id OUTPUT


IF @@ERROR = 0 AND @@ROWCOUNT = 1
BEGIN

	--proceso general de actualizaciones de RMA dependiendo de los estados
	EXEC dbo.spRMA_updateCommonData
			@comp_id,		@bra_id,
			@lrma_id,		@rmadt_guid,
			@cust_id,		@supp_id,
			@rmah_cd,		@user_id

END


-- retornar el valor del id insertado en la cabecera
SET @return_value = @lrma_id
GO





CREATE  PROCEDURE [dbo].[spRMA_insertData_original]
(
	@rmadt_guid					UNIQUEIDENTIFIER,
	@comp_id					INT,
	@bra_id						INT,
	@cust_id					INT,
	@supp_id					INT,
	@rmah_cd					DATETIME,
	@user_id					INT,
	@return_value				INT OUTPUT
)
AS
SET NOCOUNT ON
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-08-02
-- Parte		: 420
-- Description	: Para cumplir el requerimiento solicitado, se modificó para que cuando el estado del RMA sea 10,20,
--				  30 o 40 queden los pedidos cerrados (ssos_id=201) y se carguen los seriales en tbSaleOrderSerials
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-08-06
-- Parte		: 448
-- Description	: Para cumplir el requerimiento solicitado, se actualiza el campo soh_isediting al valor 'False',
--				  luego de la actualización de tbSaleOrderSerials, porque el spSaleOrderSerials_insertData lo pone
--				  por defecto en 'True'
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-08-06
-- Parte		: 457
-- Description	: Se actualiza el ssos_id a 201 cuando el srpt_id = 35
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-09-16
-- Parte		: S/P Referencia: #1
-- Description	: Se cambia el orden de las monedas para la obtención del @ExchangeToCustomerCurrency
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-10-18
-- Parte		: S/P Referencia: #2
-- Description	: Se cambia lo realizado por el parte 457 y se actualiza el ssos_id a 200 cuando el srpt_id es 35
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2011-01-18
-- Parte		: S/P Referencia: #3
-- Description	: Se modifica la descripción del artículo cuando se realiza la actualización de Pedidos y el
--				  artículo es Manual
-- =================================================================================================================





/*
DECLARE @rmadt_guid					uniqueidentifier,
		@comp_id					int,
		@bra_id						int,
		@cust_id					int,
		@supp_id					INT,
		@rmah_cd					datetime,
		@user_id					INT,
		@return_value				int

SELECT	@rmadt_guid					='9948a6a6-88e3-4833-8e80-1f1cad7aa9a8',--'9f0fc0c6-46f8-4666-9760-d6410aef92bb',
		@comp_id					= 1,
		@bra_id						= 1,
		@cust_id					= null,
		@supp_id					= 8103,
		@rmah_cd					= GETDATE(),
		@user_id					= 1
*/




--BEGIN TRANSACTION









DECLARE @bra_processingDate		DATETIME,
		@prli_id				INT

select	@bra_processingDate		= bra_processingDate,
		@prli_id				= br.bra_RMA_prli_Id4NoSerialItems
from	dbo.tbBranch			  br
where	br.bra_id				= @bra_id
AND		br.comp_id				= @comp_id





DECLARE @lrma_id INT
-- insertar datos en el Header de RMA
exec	dbo.spRMAHeader_insertData
		@comp_id,	@bra_id,
		@cust_id,	@supp_id,
		@rmah_cd,	@return_value = @lrma_id OUTPUT




IF @@ERROR = 0 AND @@ROWCOUNT = 1
BEGIN

	-- declaración de variables para obtener los datos del cursor
	declare	@lrmadt_id					int,
			@lit_transaction			int,
			@litem_id					int,
			@lstor_id					int,
			@lrmadt_Manual				VARCHAR(100),
			@lrmadt_originalPrice		DECIMAL(19,6),
			@lcurr_id					int,
			@lrmadt_qty					DECIMAL(19,5),
			@luser_id_Reception			int,
			@lrmadt_Date_Reception		datetime,
			@lrmadt_ReceptionNote		VARCHAR(8000),
			@lis_id						INT,
			@luser_id_Diagnostic		INT,
			@lrmadt_Date_Diagnostic		DATETIME,
			@lrmadt_DiagnosticNote		VARCHAR(8000),
			@lsrpt_id					INT,
			@lrmadt_ProcNote            VARCHAR(8000),
			@ldf_id4CreditNote			INT,
			@tis_id						INT,
			@lrv						INT,
			@lrmadt_isNew				BIT,
			@ltis_priority				DECIMAL(14,4),
			@litem_desc					VARCHAR(200)


	-- declaración del cursor para obtener los datos de la tabla detalle temporal
	declare cursor_RMA_iD_items cursor for
	select	rmadt_id,
			trdt.it_transaction,
			trdt.item_id,
			trdt.stor_id,
			rmadt_Manual,
			rmadt_originalPrice,
			trdt.curr_id,
			rmadt_qty,
			user_id_Reception,
			rmadt_Date_Reception,
			rmadt_ReceptionNote,
			trdt.is_id,
			user_id_Diagnostic,
			rmadt_Date_Diagnostic,
			rmadt_DiagnosticNote,
			srpt_id,
			rmadt_ProcNote,
			df_id4CreditNote,
			trdt.tis_id,
			rmadt_isNew,
			ISNULL(ttis.tis_priority,0),
			ISNULL(ti.item_desc,'')


	from	dbo.tbRMA_Detail_Tmp				trdt

			LEFT JOIN tbTempItemStock			ttis
			ON	ttis.comp_id	= trdt.comp_id
			AND ttis.tis_guid	= trdt.rmadt_guid

			LEFT JOIN tbItem					ti
			ON	ti.comp_id		= trdt.comp_id
			AND ti.item_id		= trdt.item_id

	where	rmadt_guid = @rmadt_guid



	OPEN cursor_RMA_iD_items



	-- lectura anticipada del cursor
	fetch	cursor_RMA_iD_items
	into	@lrmadt_id,
			@lit_transaction,
			@litem_id,
			@lstor_id,
			@lrmadt_Manual,
			@lrmadt_originalPrice,
			@lcurr_id,
			@lrmadt_qty,
			@luser_id_Reception,
			@lrmadt_Date_Reception,
			@lrmadt_ReceptionNote,
			@lis_id,
			@luser_id_Diagnostic,
			@lrmadt_Date_Diagnostic,
			@lrmadt_DiagnosticNote,
			@lsrpt_id,
			@lrmadt_ProcNote,
			@ldf_id4CreditNote,
			@tis_id,
			@lrmadt_isNew,
			@ltis_priority,
			@litem_desc



	DECLARE @it_order	INT
	SET @it_order = 0


	-- se recorre el cursor hasta el fin del mismo
	WHILE @@fetch_status = 0
	BEGIN

		SET @it_order = @it_order + 1

		-- por cada registro del cursor se realiza el insert en la tabla detalle de RMA
		DECLARE @lrmad_id	INT

		EXEC 	dbo.spRMADetail_insertData
				@comp_id,				@lrma_id,				@bra_id,
				@lit_transaction,		@litem_id,				@lstor_id,
				@lrmadt_Manual,			@lrmadt_originalPrice,	@lcurr_id,
				@lrmadt_qty,			@luser_id_Reception,	@lrmadt_ReceptionNote,
				@lis_id,				@luser_id_Diagnostic,	@lrmadt_Date_Diagnostic,
				@lrmadt_DiagnosticNote, @ldf_id4CreditNote,		@lsrpt_id,
				@lrmadt_ProcNote,		@return_value			= @lrmad_id OUTPUT


		IF @lrmadt_isNew = 'True'
		BEGIN

			-- Declaro variables
			DECLARE @intSm_id					INT
			DECLARE @intDisc_id					INT
			DECLARE @intCurr_id					INT
			DECLARE @intDl_id					INT
			DECLARE @intCurr_id_b				INT
			DECLARE @intStor_id_b				INT
			DECLARE @ct_CompanyCurrency			INT
			DECLARE @ExchangeToCustomerCurrency	DECIMAL(19,6)
			DECLARE @ExchangeToCompanyCurrency	DECIMAL(19,6)
			DECLARE @intSt_id					INT
			DECLARE @lsoh_id					INT
			DECLARE @total						DECIMAL(19,6)
			DECLARE @ct_transaction				INT
			DECLARE @ssos_id					INT
			DECLARE @tax_id						INT
			DECLARE @neto						DECIMAL(18,2)
			DECLARE	@rv							INT
			DECLARE @bra_RMA_dfId4Packing		INT
			--DECLARE @bra_RMA_dfId4Credit		INT
			DECLARE @bra_RMA_storId4OK			INT
			DECLARE @bra_RMA_storId4Scrap		INT
			DECLARE @now						DATETIME
			DECLARE @intCust_id					int


			-- obtener la fecha actual
			set @now	= getdate()


			-- recuperar la diferencia de cambio y la moneda en que realizó la cobranza
			Select 	@total	=  0

			-- recuperamos la moneda y depósito de la sucursal
			SELECT	@intCurr_id_b	= br.curr_id,
					@intStor_id_b	= br.stor_id
			FROM	dbo.tbBranch		br
			WHERE	br.comp_id		= @comp_id
			AND		br.bra_id		= @bra_id


			-- recupero el df_id
			SELECT @bra_RMA_dfId4Packing = tb.bra_RMA_dfId4Packing,
				   --@bra_RMA_dfId4Credit	 = tb.bra_RMA_dfId4Credit,
				   @bra_RMA_storId4OK	 = tb.bra_RMA_storId4OK,
				   @bra_RMA_storId4Scrap = tb.bra_RMA_storId4Scrap
			FROM tbBranch tb
			WHERE tb.comp_id = @comp_id
			AND tb.bra_id = @bra_id



			-- Customer
			SELECT	@intSm_id		= cu.sm_id,
					@intDisc_id		= cu.disc_id,
					@intCurr_id		= cu.curr_id,
					@intDl_id		= cu.dl_id,
					@intSt_id		= cu.st_id,
					@intSt_id		= cu.st_id,
					@intCust_id		= cu.cust_id
			FROM	dbo.tbCustomer		 cu
			WHERE	cu.comp_id		= @comp_id
			AND		cu.cust_id		= @cust_id



			-- Company
			SELECT	@ct_CompanyCurrency = comp.curr_id
			FROM	dbo.tbCompany comp
			WHERE	comp.comp_id	= @comp_id


			-- ===========================================================================================================
			-- 16-09-2010 - GGG - Referencia: #1
			-- tipo de cambio a moneda del cliente
			--SELECT @ExchangeToCustomerCurrency  = dbo.fnGetExchange(@comp_id, 1, @lcurr_id, @intCurr_id, 0, 0, 'False')
			-- MOS: 11-2010													-- No se sabe que MIERDA es cada monedaaaaaa!!!!
			DECLARE @CustomerCurrencyId AS INT
			DECLARE @BranchCurrencyId	AS INT
			SELECT	@customerCurrencyId = tc.curr_id
				FROM	tbCustomer tc
				WHERE	tc.comp_id			= @comp_id
					AND	tc.cust_id			= @cust_id
			SELECT @BranchCurrencyId = tb.curr_id
				FROM tbBranch tb
				WHERE	tb.comp_id			= @comp_id
					AND tb.bra_id			= @bra_id

			SELECT @ExchangeToCustomerCurrency  = dbo.fnGetExchange(@comp_id, 1, @BranchCurrencyId, @customerCurrencyId , 0, 0, 'False')
			-- ===========================================================================================================


			--tipo de cambio de la moneda de la sucursal a la moneda de la compañia
			--SELECT @ExchangeToCompanyCurrency = dbo.fnGetExchange


			DECLARE @df_id INT

			IF @lsrpt_id = 10 OR @lsrpt_id = 30 OR @lsrpt_id = 35 OR @lsrpt_id = 50
				SET @df_id	= @bra_RMA_dfId4Packing

			IF @lsrpt_id = 20 OR @lsrpt_id = 40
				/* cambio por NSG el 12-11-2009 */
				SET @df_id	= @ldf_id4CreditNote


			-- ========================================================================================================
			-- 2010-08-01 - GGG - Parte 420
			-- ========================================================================================================

			/*  ASI ESTABA ***************************************
			IF @lsrpt_id	= 40
				/* cambio solicitado por MOS el 10-08-2009 */
				/* original
				SELECT @ssos_id = 50*/
				SET @ssos_id = 201
			ELSE
				SET @ssos_id = 200
			******************************************************/


			SELECT	@ssos_id =	CASE
									WHEN @lsrpt_id = 10	THEN 201 -- funciona ok se devuelve la misma mercaderia
									WHEN @lsrpt_id = 20	THEN 201 -- funciona ok se efectúa NC
									WHEN @lsrpt_id = 30	THEN 201 -- funciona mal se devuelve al misma mercaderia
									WHEN @lsrpt_id = 35	THEN 200 -- funciona mal se cambia por igual mercadería		-- Ref: #2
									WHEN @lsrpt_id = 40	THEN 201 -- funciona mal se efectúa NC
									ELSE 200
			      	          	END
			-- ========================================================================================================



			-- ========================================================================================================
			-- Referencia: #3
			DECLARE @ldescription VARCHAR(200)
			IF @litem_desc IS NULL OR LEN(RTRIM(LTRIM(@litem_desc))) = 0
				BEGIN
					SET @ldescription = @lrmadt_Manual
				END
			ELSE
				BEGIN
					SET @ldescription = @litem_desc
				END
			-- ========================================================================================================



			-- ========================================================================================================
			-- 2010-08-23 - GGG - Parte S/P
			-- Se pasa la actualización de Pedidos a un sólo SPs
			-- ========================================================================================================
			EXEC spRMA_updateSaleOrder
				@comp_id,
				@bra_id,
				@rmadt_guid,
				@cust_id,
				@user_id,
				@bra_processingDate,
				@prli_id,
				@intSm_id,
				@intDisc_id,
				@intDl_id,
				@ExchangeToCustomerCurrency,
				@intSt_id,
				@lsoh_id,
				@total,
				@ssos_id,
				@tax_id,
				@neto,
				@now,
				@litem_id,
				@lstor_id,
				@lrmadt_originalPrice,
				@lrmadt_qty,
				@lis_id,
				@lsrpt_id,
				@lrmadt_ProcNote,
				@ldf_id4CreditNote,
				@tis_id,
				@ltis_priority,
				@ldescription,				-- Referencia: #3
				@customerCurrencyId,
				@df_id,
				@lrma_id,
				@lrmad_id,
				@lcurr_id

--			IF @lsrpt_id = 20 OR @lsrpt_id = 50
--			BEGIN
--
--				SET @lsoh_id = -1
--
--				-- está opción es para lo que tiene grabado TempItemStock
--
--
--				EXEC spSaleOrder_insertData
--					@lsoh_id,						@rmadt_guid,
--					@comp_id,						@bra_id,
--					@bra_processingDate,			@bra_processingDate,
--					@lrmadt_ProcNote,				'',
--					'',								'',
--					'False',						@intSm_id,
--					@cust_id,						@intSt_id,
--					@intDisc_id,					@intDl_id,
--					NULL,							@bra_processingDate,
--					NULL,							NULL,
--					NULL,							0,
--					@user_id,						'False',
--					NULL,							@total,
--					@ldf_id4CreditNote,				@ssos_id,
--					@ExchangeToCustomerCurrency,	@customerCurrencyId,
--					@rv								OUTPUT
--
--
--			END
--			ELSE
--			BEGIN
--
--				IF @lsrpt_id = 10 OR @lsrpt_id = 30 OR @lsrpt_id = 35 OR @lsrpt_id = 40 OR @lsrpt_id = 60 OR @lsrpt_id = 70
--				BEGIN
--
--
--					-- obtiene el próximo soh_id de la tabla tbCounters, con id 2
--					exec dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @lsoh_id OUTPUT
--
--
--					SET @total = CONVERT(DECIMAL(19,6),@lrmadt_qty) * @lrmadt_originalPrice --ggg
--
--					EXEC spSaleOrderHeader_insertData
--						@comp_id,						@bra_id,
--						@lsoh_id,						@bra_processingDate,
--						@bra_processingDate,			@lrmadt_ProcNote,
--						'',								'',
--						'',								'False',
--						@intSm_id,						@cust_id,
--						@intSt_id,						@intDisc_id,
--						@intDl_id,						NULL,
--						@bra_processingDate,			NULL,
--						NULL,							NULL,
--						0,								@user_id,
--						'False', 						NULL,
--						@total,
--						@df_id,
--						@ssos_id,						@ExchangeToCustomerCurrency,
--						@customerCurrencyId
--
--
--					EXEC spSaleOrderDetail_insertData
--						@comp_id,						@bra_id,
--						@lsoh_id, 						@ltis_priority,
--						@litem_id,
--						@litem_desc,
--						'',   							@customerCurrencyId, --ggg  --@ExchangeToCustomerCurrency,
--						1,								@lrmadt_qty,
--						@prli_id,						@lrmadt_originalPrice,
--						@lstor_id,						@user_id,
--						@now,							@tax_id,
--						@neto,							@rv OUTPUT,
--						@lrma_id,						@lrmad_id,
--						NULL,							NULL,
--						NULL,							NULL,
--						NULL,							'False'
--
--				END
--			END
--
--
--
--			-- ========================================================================================================
--			-- 2010-08-02 - GGG - Parte 420
--			-- 2010-08-22 - GGG - Parte 457 - Se agrega la opción 35 para que inserte en tbSaleOrderSerials
--			-- ========================================================================================================
--			IF (@lsrpt_id = 10 OR @lsrpt_id = 20 OR @lsrpt_id = 30 OR @lsrpt_id = 35 OR @lsrpt_id = 40) AND NOT @lis_id IS NULL
--			BEGIN
--
--				EXEC spSaleOrderSerials_insertData
--					@comp_id, 		@lis_id,
--					@bra_id,		@lsoh_id,
--					NULL,			@return_value OUTPUT
--
--
--				-- ====================================================================================================
--				-- 2010-08-06 - GGG - Parte 448
--				-- ====================================================================================================
--				UPDATE 	dbo.tbSaleOrderHeader
--				SET		soh_isEditing	= 'False'
--				WHERE   comp_id			= @comp_id
--				AND 	bra_id			= @bra_id
--				AND 	soh_id			= @lsoh_id
--				-- ====================================================================================================
--
--
--			END
--			-- ========================================================================================================
			-- ========================================================================================================


			-- Si tiene número de serie, ponerlo como no disponible
			IF @lsrpt_id = 60 AND (NOT @lis_id IS NULL)
			BEGIN
				UPDATE	tbItemSerials
				SET		is_available	= 'False'
				WHERE	comp_id			= @comp_id
				AND		is_id			= @lis_id
				AND		is_serial		<> ''
				AND		NOT is_serial IS NULL
			END


			IF @lsrpt_id = 70 AND (not @litem_id IS NULL OR NOT @lis_id IS NULL)
			BEGIN

				DECLARE @lct_transaction_rv		INT
				DECLARE @intDocumentNumber		AS INT
				DECLARE @ct_ACurrencyExchange	AS DECIMAL(19,4)
				DECLARE @ct_Branch2CompanyCurrencyExchange AS DECIMAL(19,4)


				exec dbo.spCounters_getNextValue @comp_id, @bra_id, 350, @intDocumentNumber OUTPUT

				-- recuperamos la moneda y depósito de la sucursal
				SELECT	@intCurr_id_b	= br.curr_id,
						@intStor_id_b	= br.stor_id
					FROM	dbo.tbBranch		br
					WHERE	br.comp_id		= @comp_id
						AND	br.bra_id		= @bra_id

				-- Customer
				SELECT	@intSm_id		= cu.sm_id,
						@intDisc_id		= cu.disc_id,
						@intCurr_id		= cu.curr_id,
						@intDl_id		= cu.dl_id,
						@intSt_id		= cu.st_id
					FROM	dbo.tbCustomer		 cu
					WHERE	cu.comp_id		= @comp_id
						AND cu.cust_id		= @cust_id

				-- Company
				SELECT	@ct_CompanyCurrency = comp.curr_id
					FROM	dbo.tbCompany comp
					WHERE	comp.comp_id	= @comp_id

				-- tipo de cambio a moneda del cliente
				SELECT @ct_ACurrencyExchange = dbo.fnGetExchange(@comp_id, 1, @intCurr_id, @lcurr_id, 0, 0, 'False')

				--tipo de cambio de la moneda de la sucursal a la moneda de la compañia
				SELECT @ct_Branch2CompanyCurrencyExchange = dbo.fnGetExchange (@comp_id, 1, @intCurr_id_b, @ct_CompanyCurrency, 0, 0, 'False')


				EXEC spCommercialTransactions_InsertData
					@comp_id,								@bra_id,
					@intDocumentNumber,						@now,
					@supp_id,								@intcust_id,
					NULL,									@user_id,
					0,										0,
					0,										0,
					@intCurr_id_b,							@intSm_id,
					@intDisc_id,							0,
					0,										@intCurr_id,
					@ct_ACurrencyExchange,					NULL,
					@intDl_id,								@intSt_id,
					NULL,									@ct_CompanyCurrency,
					@ct_Branch2CompanyCurrencyExchange ,	301,
					NULL,									NULL,
					NULL,									NULL,
					0,										@lct_transaction_rv OUTPUT,
					NULL,									NULL

				DECLARE @lit_transaction_rv INT

				-- Recupera Stock Anterior
				DECLARE @decStorePreviuos AS DECIMAL(19,6)
				SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
				FROM	tbItemStorage tis
				WHERE	tis.comp_id = @comp_id
				AND		tis.stor_id = @lstor_id
				AND		tis.item_id = @litem_id


				IF not @litem_id IS NULL
				BEGIN
					EXEC spItemStorage_insertData
						@comp_id,				@litem_id,
						@lstor_id,				@lrmadt_qty
				END


				INSERT INTO tbItemTransactions
				(
					comp_id,				bra_id,						ct_transaction,
					item_id,				it_qty,						it_priceWithOutOthers,
					it_price,				curr_id,					it_exchangeToBranchCurrency,
					it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
					it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
					it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
					stor_id,				it_storePrevious,			prli_id,
					byor_id,				it_isProduction,			it_isAssociation,
					it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
					it_order,				so_id,						it_guarantee,
					it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
					it_CreditIntPlus,		puco_id,					it_poh_bra_id,
					it_poh_id,				it_soh_id,					it_sod_id,
					rmah_id,				rmad_id,					it_qty_rma,
					it_tis_id_aux
				)
				VALUES
				(
					@comp_id,				@bra_id,					@lct_transaction_rv,
					@litem_id,				@lrmadt_qty,				0,
					@lrmadt_originalPrice,	@lcurr_id,					@lcurr_id,
					0,						0,							0,
					0,						0,							0,
					@lrmadt_originalPrice,	@lcurr_id,					1,
					@lstor_id,				isnull(@decStorePreviuos,0),NULL,
					NULL,					'False',					'False',
					NULL,					@now,						NULL,
					@it_order,				NULL,						0,
					0,						0,							0,
					0,						NULL,						NULL,
					NULL,					NULL,						NULL,
					@lrma_id,				@lrv,						@lrmadt_qty,
					NULL
				)


				UPDATE	tbItemSerials
					SET		is_available		= 'True',
							stor_id				= @lstor_id
					WHERE	comp_id				= @comp_id
					AND		is_id				= @lis_id
					AND		is_serial			<> ''
					AND		NOT is_serial		IS NULL


			END --end 70


			IF @lsrpt_id = 1010 OR @lsrpt_id = 1040
			BEGIN

				exec dbo.spCounters_getNextValue @comp_id, @bra_id, 350, @intDocumentNumber OUTPUT


				EXEC spCommercialTransactions_InsertData
					@comp_id,							@bra_id,
					@intDocumentNumber,					@now,
					@supp_id,							@intCust_id,
					null,								@user_id,
					0,									0,
					0,									0,
					@intCurr_id_b,						@intSm_id,
					@intDisc_id,						0,
					0,									@intCurr_id,
					@ct_ACurrencyExchange,				null,
					@intDl_id,							@intSt_id,
					null,								@ct_CompanyCurrency,
					@ct_Branch2CompanyCurrencyExchange,	301,
					null,								null,
					null,								null,
					0,									@lct_transaction_rv OUTPUT,
					null,								null


				--SELECT @bra_RMA_storId4Scrap
				-- Recupera Stock Anterior
				SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
				FROM	tbItemStorage tis
				WHERE	tis.comp_id = @comp_id
				AND		tis.stor_id = @lstor_id
				AND		tis.item_id = @litem_id


				IF not @litem_id IS NULL
				BEGIN
					EXEC spItemStorage_insertData
						 @comp_id,			 @litem_id,
						 @bra_RMA_storId4OK, @lrmadt_qty
				END


				INSERT INTO tbItemTransactions
				(
					comp_id,				bra_id,						ct_transaction,
					item_id,				it_qty,						it_priceWithOutOthers,
					it_price,				curr_id,					it_exchangeToBranchCurrency,
					it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
					it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
					it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
					stor_id,				it_storePrevious,			prli_id,
					byor_id,				it_isProduction,			it_isAssociation,
					it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
					it_order,				so_id,						it_guarantee,
					it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
					it_CreditIntPlus,		puco_id,					it_poh_bra_id,
					it_poh_id,				it_soh_id,					it_sod_id,
					rmah_id,				rmad_id,					it_qty_rma,
					it_tis_id_aux
				)
				VALUES
				(
					@comp_id,				@bra_id,					@lct_transaction_rv,
					@litem_id,				@lrmadt_qty,				0,
					@lrmadt_originalPrice,	@lcurr_id,					@lcurr_id,
					0,						0,							0,
					0,						0,							0,
					@lrmadt_originalPrice,	@lcurr_id,					1,
					@lstor_id,				isnull(@decStorePreviuos,0),NULL,
					NULL,					'False',					'False',
					NULL,					@now,						NULL,
					@it_order,				NULL,						0,
					0,						0,							0,
					0,						NULL,						NULL,
					NULL,					NULL,						NULL,
					@lrma_id,				@lrv,						@lrmadt_qty,
					NULL
				)


			END --1010 1040



			IF @lsrpt_id = 1020
			BEGIN

				exec dbo.spCounters_getNextValue @comp_id, @bra_id, 350, @intDocumentNumber OUTPUT


				EXEC spCommercialTransactions_InsertData
					@comp_id,								@bra_id,
					@intDocumentNumber,						@now,
					@supp_id,								@intCust_id,
					NULL,									@user_id,
					0,										0,
					0,										0,
					@intCurr_id_b,							@intSm_id,
					@intDisc_id,							0,
					0,										@intCurr_id,
					@ct_ACurrencyExchange,					NULL,
					@intDl_id,								@intSt_id,
					NULL,									@ct_CompanyCurrency,
					@ct_Branch2CompanyCurrencyExchange,		301,
					NULL,									NULL,
					NULL,									NULL,
					0,										@lct_transaction_rv OUTPUT,
					NULL,									NULL



				-- Recupera Stock Anterior
				SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
				FROM	tbItemStorage tis
				WHERE	tis.comp_id = @comp_id
				AND		tis.stor_id = @lstor_id
				AND		tis.item_id = @litem_id


				IF not @litem_id IS NULL
				BEGIN
					EXEC spItemStorage_insertData
					@comp_id,				@litem_id,
					@bra_RMA_storId4Scrap, @lrmadt_qty
				END


				INSERT INTO tbItemTransactions
				(
					comp_id,				bra_id,						ct_transaction,
					item_id,				it_qty,						it_priceWithOutOthers,
					it_price,				curr_id,					it_exchangeToBranchCurrency,
					it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
					it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
					it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
					stor_id,				it_storePrevious,			prli_id,
					byor_id,				it_isProduction,			it_isAssociation,
					it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
					it_order,				so_id,						it_guarantee,
					it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
					it_CreditIntPlus,		puco_id,					it_poh_bra_id,
					it_poh_id,				it_soh_id,					it_sod_id,
					rmah_id,				rmad_id,					it_qty_rma,
					it_tis_id_aux
				)
				VALUES
				(
					@comp_id,				@bra_id,					@lct_transaction_rv,
					@litem_id,				@lrmadt_qty,				0,
					@lrmadt_originalPrice,	@lcurr_id,					@lcurr_id,
					0,						0,							0,
					0,						0,							0,
					@lrmadt_originalPrice,	@lcurr_id,					1,
					@lstor_id,				isnull(@decStorePreviuos,0),NULL,
					NULL,					'False',					'False',
					NULL,					@now,						NULL,
					@it_order,				NULL,						0,
					0,						0,							0,
					0,						NULL,						NULL,
					NULL,					NULL,						NULL,
					@lrma_id,				@lrv,						@lrmadt_qty,
					NULL
				)


			END --1020


			--incrementando los it_qty_rma correspondientes de la tabla ItemTransactions
			--SELECT @lsrpt_id


			IF @lsrpt_id = 1030
			BEGIN

				SELECT @lrmadt_qty

				UPDATE	tbItemTransactions
				SET		it_qty_rma			= @lrmadt_qty--@qty + @lrmadt_qty

				WHERE	comp_id				= @comp_id
				AND		bra_id				= @bra_id
				AND		item_id				= @litem_id
				AND		it_qty				= @lrmadt_qty

			END	--1030


			--Generó registros de tbItemSerial en blanco
			IF @lsrpt_id = 1040 AND not @litem_id IS NULL
			BEGIN
				EXEC spItemSerials_insertQtyData

					@comp_id,				@bra_id,
					@lct_transaction_rv,	@lit_transaction_rv,
					@litem_id,				@bra_RMA_storId4OK,
					@lrmadt_qty

			END --1040


		END --End del campo rmadt_IsNew


		-- por cada registro del cursor se realiza el delete del registro de la tabla RMA detalle temporal
		exec    dbo.spRMADetailTmp_deleteData		@lrmadt_id





		-- próxima lectura del cursor
		fetch	cursor_RMA_iD_items
		into	@lrmadt_id,
				@lit_transaction,
				@litem_id,
				@lstor_id,
				@lrmadt_Manual,
				@lrmadt_originalPrice,
				@lcurr_id,
				@lrmadt_qty,
				@luser_id_Reception,
				@lrmadt_Date_Reception,
				@lrmadt_ReceptionNote,
				@lis_id,
				@luser_id_Diagnostic,
				@lrmadt_Date_Diagnostic,
				@lrmadt_DiagnosticNote,
				@lsrpt_id,
				@lrmadt_ProcNote,
				@ldf_id4CreditNote,
				@tis_id,
				@lrmadt_isNew,
				@ltis_priority,
				@litem_desc

		end

		close cursor_RMA_iD_items
		DEALLOCATE cursor_RMA_iD_items




		DELETE FROM tbTempItemStock
		WHERE tis_guid = @rmadt_guid

END

-- retornar el valor del id insertado en la cabecera
set	@return_value = @lrma_id





/*
if @@ERROR = 0
	commit TRANSACTION
ELSE
	ROLLBACK TRANSACTION
*/
GO










CREATE PROCEDURE [dbo].[spRMA_insertTransaction]
(
	@comp_id				INT,
	@bra_id					INT,
	@cust_id				INT,
	@supp_id				INT,
	@user_id				INT,
	@stor_id				INT,
	@item_id				INT,
	@rmadt_qty				DECIMAL(19,5),
	@rmadt_originalPrice	DECIMAL(19,5),
	@cust_curr_id			INT,
	@rmadt_curr_id			INT,
	@bra_curr_id			INT,
	@comp_curr_id			INT,
	@it_order				INT,
	@rmah_id				INT,
	@rmad_id				INT,
	@sm_id					INT,
	@disc_id				INT,
	@dl_id					INT,
	@st_id					INT,
	@now					DATETIME,
	@sd_id					INT,
	@ct_transaction_rv		INT OUTPUT,
	@it_transaction_rv		INT OUTPUT
)
AS


BEGIN


	SET NOCOUNT ON



	DECLARE --@lct_transaction_rv						INT,
			@intDocumentNumber						INT,
			@ct_ACurrencyExchange					DECIMAL(19,4),
			@ct_Branch2CompanyCurrencyExchange		DECIMAL(19,4),
			--@lit_transaction_rv						INT,
			@decStorePreviuos						DECIMAL(19,6)




	-- obtener el próximo número de ct_transaction en @intDocumentNumber
	EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 350, @intDocumentNumber OUTPUT


	-- tipo de cambio de la moneda del cliente a la moneda del artículo
	SELECT @ct_ACurrencyExchange				= dbo.fnGetExchange(@comp_id,1,@cust_curr_id,	@rmadt_curr_id,	0,0,'False')


	-- tipo de cambio de la moneda de la sucursal a la moneda de la compañia
	SELECT @ct_Branch2CompanyCurrencyExchange	= dbo.fnGetExchange(@comp_id,1,@bra_curr_id,	@comp_curr_id,	0,0,'False')



	EXEC spCommercialTransactions_InsertData
		@comp_id,							@bra_id,				@intDocumentNumber,
		@now,								@supp_id,				@cust_id,
		NULL,								@user_id,				0,
		0,									0,						0,
		@bra_curr_id,						@sm_id,					@disc_id,
		0,									0,						@cust_curr_id,
		@ct_ACurrencyExchange,				NULL,					@dl_id,
		@st_id,								NULL,					@comp_curr_id,
		@ct_Branch2CompanyCurrencyExchange,	 @sd_id /*301*/,		NULL,		-- MOS 08-2017
		NULL,								NULL,					NULL,
		0,									@ct_transaction_rv OUTPUT,
		NULL,								NULL



	-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
	SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
		FROM	tbItemStorage tis		-- NO poner with nolock !!
		WHERE	tis.comp_id = @comp_id
		AND		tis.stor_id = @stor_id
		AND		tis.item_id = @item_id



	INSERT INTO tbItemTransactions
	(
		comp_id,				bra_id,						ct_transaction,
		item_id,				it_qty,						it_priceWithOutOthers,
		it_price,				curr_id,					it_exchangeToBranchCurrency,
		it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
		it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
		it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
		stor_id,				it_storePrevious,			prli_id,
		byor_id,				it_isProduction,			it_isAssociation,
		it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
		it_order,				so_id,						it_guarantee,
		it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
		it_CreditIntPlus,		puco_id,					it_poh_bra_id,
		it_poh_id,				it_soh_id,					it_sod_id,
		rmah_id,				rmad_id,					it_qty_rma,
		it_tis_id_aux
	)
	VALUES
	(
		@comp_id,				@bra_id,					@ct_transaction_rv,
		@item_id,				@rmadt_qty,					0,
		@rmadt_originalPrice,	@rmadt_curr_id,				@rmadt_curr_id,
		0,						0,							0,
		0,						0,							0,
		@rmadt_originalPrice,	@rmadt_curr_id,				1,
		@stor_id,				isnull(@decStorePreviuos,0),NULL,
		NULL,					'False',					'False',
		NULL,					@now,						NULL,
		@it_order,				NULL,						0,
		0,						0,							0,
		0,						NULL,						NULL,
		NULL,					NULL,						NULL,
		@rmah_id,				@rmad_id,					@rmadt_qty,
		NULL
	)


	SET @it_transaction_rv = @@IDENTITY


END
GO






-- --------------------------------------------------------------
-- MOS  03-2009
-- Pone IsEditing en Falso de los RMA no usados
-- --------------------------------------------------------------

CREATE PROCEDURE [dbo].[spRMA_IsEditingPurgeStatus]
AS

-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2011-06-22
-- TN			: 908
-- Description	: Se habilita la actualización del isediting en tbRMA_Detail_Tmp
-- =================================================================================================================


BEGIN

	SET NOCOUNT ON
	DECLARE @DeleteTime		AS	DATETIME
	SET 	@DeleteTime		=	DATEADD(minute, -4, GETDATE())



	UPDATE	tbRMA_Header	WITH(ROWLOCK)

		SET		rmah_isEditing		= 'false',
				rmah_isEditingCD	= GETDATE()

		WHERE	rmah_isEditing		= 'True'
		AND		rmah_isEditingCD	< @DeleteTime



	-- ======================================================================================================
	-- TN: 908
	DELETE	tbRMA_Detail_Tmp	WITH(ROWLOCK)

		WHERE   rmadt_isEditing		= 'True'
		AND 	rmadt_isEditingCD	< @DeleteTime
	-- ======================================================================================================

END


GO




CREATE PROCEDURE [dbo].[spRMA_MerchandiseType_getCombo]
(
	@comp_id	INT
)

AS

SET NOCOUNT ON

	BEGIN

		-- ------------------------
		-- TESTING
		-- ------------------------
	/*
			DECLARE
				@comp_id	INT
			SELECT
				@comp_id	= 1
	*/
		-- ------------------------


		SELECT
			trmt.rmamt_id	[Id],
			trmt.rmamt_desc	[Desc]
		FROM tbRMA_MerchandiseType trmt

		WHERE	trmt.comp_id		= @comp_id	AND
				trmt.rmamt_disabled	= 'False'

		ORDER BY [Desc]

	END
GO





CREATE procedure [dbo].[spRMA_Notes_Cause_GetCombo]
(
	@comp_id	int
)

as set NOCOUNT on

	begin


		select
			trnc.rmanc_id		[Id],
			trnc.rmanc_desc		[Desc]
		from tbRMA_Notes_Cause	trnc

		where trnc.comp_id = @comp_id
		ORDER BY trnc.rmanc_desc

	end
GO





create PROCEDURE spRMA_Notes_DeleteData
(
	@comp_id		int,
	@rman_id		int
)
as set NOCOUNT on

-- -------------------------------------
-- TESTING
-- -------------------------------------
/*
	declare
		@comp_id	int,
		@rman_id	int

	select
		@comp_id	= 1,
		@rman_id	= 1

*/
-- -------------------------------------

begin

	delete from tbRMA_Notes

	where	comp_id = @comp_id
