CREATE PROCEDURE [dbo].[spRMA_Notes_GetData]
(
	@comp_id		int,
	@rmah_id		int,
	@rmad_id		int,
	@user_id		int
)
as set NOCOUNT on

-- -----------------------------------
-- TESTING
-- -----------------------------------
/*
	declare
		@comp_id		int,
		@rmah_id		int,
		@rmad_id		int,
		@user_id		int
	select
		@comp_id		= 1,
		@rmah_id		= 540,
		@rmad_id		= 84054,
		@user_id		= 1
*/
-- -----------------------------------


begin


	select
		' '					[ ],
		' '					[ ],
		--trn.comp_id,
		--trn.rmah_id,
		--trn.rmad_id,
		tu.user_nick,
		trn.rman_note,
		trnc.rmanc_desc,
		--trn.rman_cd,
		trn.rman_lastUpdate,
		trn.rman_id			[ID]


	from tbRMA_Notes					trn

	inner join tbRMA_Notes_Cause		trnc
	on  trnc.comp_id	= trn.comp_id
	AND trnc.rmanc_id	= trn.rmanc_id

	inner join tbUser					tu
	on tu.[user_id]		= trn.[user_id]

	where trn.comp_id	= @comp_id
	and   trn.rmah_id	= @rmah_id
	and   (@rmad_id		= -1		or	trn.rmad_id	= @rmad_id)
	--and   trn.[user_id]	= @user_id

end
GO





