CREATE PROCEDURE [dbo].[spRMA_Notes_UpdateData]
(
	@comp_id		int,
	@user_id		int,
	@rman_id		int,
	@rman_note		nvarchar(4000),
	@rmanc_id		INT,
	@rman_image		IMAGE
)
as set NOCOUNT on

-- -------------------------------------
-- TESTING
-- -------------------------------------
/*
	declare
		@comp_id	int,
		@rmah_id	int,
		@rmad_id	int,
		@user_id	int,
		@rman_note	nvarchar(4000),
