CREATE PROCEDURE [dbo].[spRMA_Repair2Supplier_GetItems2Repair]
(
	@comp_id	INT,
	@ItemGuid	UNIQUEIDENTIFIER,
	@bra_id		INT
)
AS

	SET NOCOUNT ON
		BEGIN
			-- -------------------------------------------
			-- TESTING
			-- -------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@ItemGuid	UNIQUEIDENTIFIER,
					@bra_id		INT

				SELECT
					@comp_id	= 1,
					@ItemGuid	= '25892e17-80f6-415f-9c65-7395632f0223',
					@bra_id		= 1
			*/
			-- -------------------------------------------

			-- -----------------------------------------------------------------------------
			-- Tabla para los artículos seleccionados
			-- -----------------------------------------------------------------------------
			DECLARE @lItemGuid AS UNIQUEIDENTIFIER
			SET @lItemGuid = CONVERT(UNIQUEIDENTIFIER,@ItemGuid)

			DECLARE @tblComplexFilter_AllItems TABLE (item_id INT PRIMARY KEY)
			IF (SELECT COUNT(*) FROM tbComplexFilter tcf WHERE tcf.sl_guid = @ItemGuid) > 0
				BEGIN
					INSERT INTO @tblComplexFilter_AllItems
					SELECT tcf.sl_id
						FROM tbComplexFilter tcf
						WHERE (tcf.sl_guid = @lItemGuid)    AND
							   tcf.sl_selected = 'True'
				END
			ELSE
				BEGIN
					INSERT INTO @tblComplexFilter_AllItems
					SELECT
						ti.item_id
					FROM tbItem ti
				END
			--SELECT * FROM @tblComplexFilter_AllItems
			-- -----------------------------------------------------------------------------

			SELECT
				' '										[ ],	--ACA VA UN BOTÓN PARA SELECCIONAR LOS ARTICULOS A CARGAR PARA EL ENVÍO
				CASE
					WHEN trd.rmad_guid IS NULL THEN
						CONVERT(BIT,'False')
				ELSE
						CONVERT(BIT,'True')
				END										[Is_Selected],
				ti.item_code,
				ti.item_desc,
				ISNULL(tis.is_serial,'')				[is_serial],
				trd.rmad_qty,
				trd.rmad_id								[ID]

			FROM tbRMA_Detail							trd

				INNER JOIN @tblComplexFilter_AllItems	tmp
					ON	tmp.item_id		= trd.item_id

				INNER JOIN tbItem						ti
					ON	ti.comp_id		= trd.comp_id	AND
						ti.item_id		= trd.item_id

				LEFT JOIN tbItemSerials					tis
					ON	tis.comp_id		= trd.comp_id   AND
						tis.is_id		= trd.is_id


			WHERE	trd.comp_id			= @comp_id		AND
					trd.srpt_id			= 100			AND --SE ENVÍA A REPARADOR EXTERNO
					--trd.bra_id			= @bra_id		AND
					trd.rmad_id			NOT IN (SELECT trrsd.rmad_id
		           								FROM tbRMA_Repair2SupplierDetail	trrsd
		           								WHERE	trrsd.comp_id = trd.comp_id	AND
		           										trrsd.rmah_id = trd.rmah_id	AND
		           										trrsd.rmad_id = trd.rmad_id	AND
														trrsd.rmastd_isReturned = 'False')

		END
GO



CREATE PROCEDURE [dbo].[spRMA_Repair2Supplier_GetReport]
(
	@comp_id		INT,
	@lang_id		INT,
	@page_id		INT,
	@rmast_id		INT,
	@intBranch4Lang	INT
)
AS

	SET NOCOUNT ON

	set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	--SELECT * FROM tbRMA_Repair2SupplierHeader AS trrsh



		BEGIN
			-- ----------------------------------------
			-- TESTING
			-- ----------------------------------------
			/*
				DECLARE
					@comp_id		INT,
					@lang_id		INT,
					@page_id		INT,
					@rmast_id		INT,
					@intBranch4Lang	INT
				SELECT
					@comp_id		= 1,
					@lang_id		= 2,
					@page_id		= 100954,
					@rmast_id		= 10,
					@intBranch4Lang	= 1
			*/
			-- -*---------------------------------------

			SELECT
				trrsh.rmast_id,
				trrsh.rmast_cd,
				tu.user_lastname + ',' + tu.user_firstname	[user_name],
				trrsh.rmast_note,
				ts.supp_name,
				tc.country_desc,
				ts2.state_desc,
				ts.supp_address,
				ts.supp_city,
				ts.supp_zip,
				ts.supp_Phone1,
				tb.bra_desc,
				tc2.country_desc						[branch_country],
				ts3.state_desc							[branch_state],
				tb.bra_address,
				tb.bra_zip,
				trrsh.rmast_isEnvied

			FROM tbRMA_Repair2SupplierHeader			trrsh		WITH (NOLOCK)

				INNER JOIN tbUser						tu			WITH (NOLOCK)
					ON tu.[user_id]	= trrsh.[user_id]

				INNER JOIN tbSupplier					ts			WITH (NOLOCK)
					ON	ts.comp_id	= trrsh.comp_id		AND
						ts.supp_id	= trrsh.supp_id

				INNER JOIN tbBranch						tb			WITH (NOLOCK)
					ON	tb.comp_id	= trrsh.comp_id		AND
						tb.bra_id	= trrsh.bra_id

				INNER JOIN tbsysCountry					tc			WITH (NOLOCK)
					ON tc.country_id	= ts.country_id

				INNER JOIN tbsysState					ts2			WITH (NOLOCK)
					ON	ts2.country_id	= ts.country_id AND
						ts2.state_id	= ts.state_id

				INNER JOIN tbsysCountry					tc2			WITH (NOLOCK)
					ON	tc2.country_id	= tb.country_id

				INNER JOIN tbsysState					ts3			WITH (NOLOCK)
					ON	ts3.country_id	= tb.country_id AND
						ts3.state_id	= tb.state_id

			WHERE	trrsh.comp_id	= @comp_id		AND
					trrsh.rmast_id	= @rmast_id


			EXEC [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id


			IF EXISTS( SELECT
						TOP 1 trrsd.rmad_id
						FROM tbRMA_Repair2SupplierDetail	trrsd		WITH (NOLOCK)
						WHERE	trrsd.comp_id		= @comp_id	AND
								trrsd.rmast_id		= @rmast_id
						)
				BEGIN
					SELECT
						trrsd.rmastd_id,
						trrsd.rmah_id,
						trrsd.rmad_id,
						ISNULL(trrsd.rmastd_note,'')																					[rmstd_note],
						trrsd.rmastd_estimatedReturnDate																				[rmastd_estimatedReturnDate],
						CASE WHEN ISNULL(trrsd.rmastd_isReturned,'False') = 'False' THEN
							(SELECT tov.optval_desc
								FROM tbsysOptionsValues tov WHERE tov.lang_id = @lang_id AND tov.optval_class = 1 AND tov.optval_id = 0)
						ELSE
								(SELECT tov.optval_desc
								FROM tbsysOptionsValues tov WHERE tov.lang_id = @lang_id AND tov.optval_class = 1 AND tov.optval_id = 1)
						END																												[rmastd_isReturned],
					--	trrsd.rmastd_isReturned																							[rmastd_isReturnedbit],

						CASE WHEN trrsd.user_id_4Return IS NULL THEN
							''
						ELSE
							tu.user_lastname + ',' + tu.user_firstname
						END																												[user_name],
						trrsd.rmastd_returnDate																							[rmastd_returnDate]

					FROM tbRMA_Repair2SupplierDetail										trrsd	WITH (NOLOCK)

					LEFT JOIN tbUser														tu		WITH (NOLOCK)
					ON	tu.[user_id]			= trrsd.user_id_4Return

					WHERE	trrsd.comp_id		= @comp_id	AND
							trrsd.rmast_id		= @rmast_id

					ORDER BY trrsd.rmad_id asc

				END
			ELSE
				BEGIN
					SELECT
						--'',
						--'',
						---1,
						--'',
						--'',
						--'',
						--'',
						--'',
						--''

						''		 [rmastd_id],
						''		 [rmah_id],
						-1		 [rmad_id],
						''		 [rmstd_note],
						''		 [rmastd_estimatedReturnDate],
						''		 [rmastd_isReturned],
						--''   [rmastd_isReturnedbit],
						''		 [user_name],
						''		 [rmastd_returnDate]
				END


		END




GO

