CREATE PROCEDURE [dbo].[spRMA_Repair2SupplierDetail_GetData]
(
	@comp_id	INT,
	@rmast_id	INT
)
AS

	SET NOCOUNT ON
		BEGIN

			-- -------------------------------
			-- TESTING
			-- -------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@rmast_id	INT
				SELECT
					@comp_id	= 1,
					@rmast_id	= 2
			*/
			-- -------------------------------
			SET DATEFORMAT 'YMD'

			SELECT
				' '												[ ],	--UPDATE
				CASE
					WHEN trrsd.rmastd_isReturned = 'False' THEN
						'True'
				ELSE
						'False'
				END												[ ],	--DELETE
				ti.item_code,
				ti.item_desc,
				trd.rmad_qty,
				trrsd.rmastd_note,
				trrsd.rmastd_estimatedReturnDate,
				trrsd.rmastd_isReturned,
				--NO PONER NADA ANTES QUE ESTO

				tc.cust_name,
				trh.rmah_id,

				CASE
					WHEN trrsd.user_id_4Return IS NULL THEN
						' '
				ELSE
					tu.user_lastname + ',' + tu.user_firstname
				END									[user_name],

				--NO PONER NADA DESPUES DE ESTO
				trrsd.rmastd_returnDate,								--COUNT -2
				trrsd.rmastd_id						[ID]

			FROM tbRMA_Repair2SupplierDetail		trrsd

				INNER JOIN tbRMA_Detail				trd
					ON	trd.comp_id = trrsd.comp_id AND
						trd.rmah_id = trrsd.rmah_id AND
						trd.rmad_id = trrsd.rmad_id

				INNER JOIN tbRMA_Header				trh
				ON		trh.comp_id = trd.comp_id	AND
						trh.rmah_id = trd.rmah_id

				INNER JOIN tbCustomer				tc
				ON		tc.comp_id	= trh.comp_id	AND
						tc.cust_id	= trh.cust_id

				INNER JOIN tbItem					ti
					ON	ti.comp_id	= trd.comp_id	AND
						ti.item_id	= trd.item_id

				LEFT JOIN tbUser					tu
					ON tu.[user_id]	= trrsd.user_id_4Return

			WHERE	trrsd.comp_id	= @comp_id AND
					trrsd.rmast_id	= @rmast_id
		END



GO



