CREATE PROCEDURE [dbo].[spRMA_Repair2SupplierDetail_UpdateData]
(
	@comp_id				INT,
	@rmastd_id				INT,
	@user_id				INT,
	@DetailNote				VARCHAR(4000),
	@EstimatedReturnDate	DATETIME,
	@isReturned				BIT
)
AS
	SET NOCOUNT ON
		BEGIN
			SET DATEFORMAT 'YMD'

			--SI LO MARCA COMO RETORNADO, ACTUALIZAMOS ADEMÁS LOS CAMPOS DE USUARIO Y DE FECHA DE RETORNO
			IF @isReturned = 'True'
				BEGIN
					UPDATE tbRMA_Repair2SupplierDetail
					SET
						rmastd_note					= @DetailNote,
						rmastd_isReturned			= @isReturned,
						user_id_4Return				= @user_id,
						rmastd_returnDate			= GETDATE()

					WHERE	comp_id		= @comp_id AND
							rmastd_id	= @rmastd_id

					-- VARIABLES DE TRABAJO
					DECLARE
						@rmah_id	INT,
						@rmad_id	INT
					--RECUPERAMOS RMAH_ID Y RMAD_ID
					SELECT
						@rmah_id = trrsd.rmah_id,
						@rmad_id = trrsd.rmad_id
					FROM tbRMA_Repair2SupplierDetail	trrsd
					WHERE	trrsd.comp_id	= @comp_id	AND
							trrsd.rmastd_id = @rmastd_id

					--UNA VEZ QUE EL ARTÍCULO ESTÁ COMO DEVUELTO, PUEDEN VOLVER A SELECCIONARLO PARA SER ENVIADO EN OTRO LOTE
					UPDATE tbRMA_Detail
					SET
						rmad_guid = NULL
					WHERE	comp_id = @comp_id AND
							rmah_id = @rmah_id AND
							rmad_id = @rmad_id
				END
			ELSE
				--SINO SOLO ACTUALIZAMOS LA NOTA DEL DETALLE Y LA FECHA TENTATIVA DE RETORNO
				BEGIN
					UPDATE tbRMA_Repair2SupplierDetail
					SET
						rmastd_note					= @DetailNote,
						rmastd_estimatedReturnDate	= @EstimatedReturnDate

					WHERE	comp_id		= @comp_id AND
							rmastd_id	= @rmastd_id
				END

		END
GO



