CREATE PROCEDURE [dbo].[spRMA_Repair2SupplierHeader_getDataByFilters]
(
	@comp_id		INT,
	@SupplierGuid	UNIQUEIDENTIFIER,
	@status			INT
)
AS

	SET NOCOUNT ON

		BEGIN
			-- ----------------------------------
			-- TESTING
			-- ----------------------------------
			/*
				DECLARE
					@comp_id		INT,
					@supp_id		INT,
					@status			INT,
					@SupplierGuid	UNIQUEIDENTIFIER
				SELECT
					@comp_id		= 1,
					@supp_id		= -1,
					@status			= -1,
					@SupplierGuid	= '25892e17-80f6-415f-9c65-7395632f0223'
			*/
			-- ----------------------------------

			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			-- -----------------------------------------------------------------------------

			-- -----------------------------------------------------------------------------
			-- Tabla para los clientes seleccionados
			-- -----------------------------------------------------------------------------
			DECLARE @lSupplierGuid AS UNIQUEIDENTIFIER
			SET @lSupplierGuid = CONVERT(UNIQUEIDENTIFIER,@SupplierGuid)

			DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)

				IF (SELECT COUNT(*) FROM tbComplexFilter tcf WHERE tcf.sl_guid = @SupplierGuid)  > 0
					BEGIN
						INSERT INTO @tblComplexFilter_Supplier
						SELECT tcf.sl_id
							FROM tbComplexFilter tcf
							WHERE tcf.sl_guid = @lSupplierGuid     AND
								  tcf.sl_selected = 'True'
					END
				ELSE
					BEGIN
						INSERT INTO @tblComplexFilter_Supplier
						SELECT
							ts.supp_id
						FROM tbSupplier ts
					END
			-- -----------------------------------------------------------------------------

			SELECT
				ISNULL(trrsh.rmast_isEnvied,'False')				[ ],	--Editar Detalle (SOLO SI NO SE ENCUENTRA CERRADO)
				(SELECT TOP 1 1
				 FROM tbRMA_Repair2SupplierDetail					trrsd
				 WHERE	trrsd.comp_id			= @comp_id			AND
						trrsd.rmast_id			= trrsh.rmast_id	AND
						ISNUll(trrsd.rmastd_isReturned,'False') = 'True')
															[ ],	--Borrar Lote (SOLO SI NINGUN ARTICULO FUE ENVIADO (OSEA IS_RETURNED = FALSE)
				' '											[ ],	--REPORTE
				trrsh.rmast_note,
				trrsh.rmast_cd,
				ts.supp_name,
				tb.bra_desc,
				tu.user_lastname + ',' + tu.user_firstname	[user_name],
				ISNULL(trrsh.rmast_isEnvied,'False')		[rmast_isEnvied],
				trrsh.rmast_id								[ID]

			FROM tbRMA_Repair2SupplierHeader				trrsh
				INNER JOIN tbUser							tu
					ON tu.[user_id] = trrsh.[user_id]

				INNER JOIN tbSupplier						ts
					ON	ts.comp_id	= trrsh.comp_id			AND
						ts.supp_id	= trrsh.supp_id

				INNER JOIN tbBranch							tb
					ON	tb.comp_id	= trrsh.comp_id			AND
						tb.bra_id	= trrsh.bra_id

				INNER JOIN @tblComplexFilter_Supplier		tmp
					ON	tmp.supp_id	= ts.supp_id


			WHERE	trrsh.comp_id	= @comp_id							AND
					(
						(@status = -1)																			OR	--TODOS

						(@status = 1		AND	(SELECT
												COUNT(*)
						       	   		     FROM tbRMA_Repair2SupplierDetail			trrsd
						       	   		     WHERE	trrsd.comp_id	= trrsh.comp_id		AND
						       	   					trrsd.rmast_id	= trrsh.rmast_id	AND
													ISNULL(trrsd.rmastd_isReturned,'False') = 'True') = 0)		OR	--ENVIADO SIN RECIBIR

						(@status	= 2		AND ((SELECT
													COUNT(*)
						       	   				 FROM tbRMA_Repair2SupplierDetail			trrsd
						       	   				 WHERE	trrsd.comp_id	= trrsh.comp_id		AND
						       	   						trrsd.rmast_id	= trrsh.rmast_id) <> (SELECT
																									COUNT(*)
					       	   																	 FROM tbRMA_Repair2SupplierDetail			trrsd
					       	   																	 WHERE	trrsd.comp_id	= trrsh.comp_id		AND
					       	   																			trrsd.rmast_id	= trrsh.rmast_id	AND
																										ISNULL(trrsd.rmastd_isReturned,'False') = 'True')))

																												OR 	--ENVIADO CON RECEPCIÓN PARCIAL

						(@status	= 3		AND (SELECT
													COUNT(*)
						       	   				 FROM tbRMA_Repair2SupplierDetail			trrsd
						       	   				 WHERE	trrsd.comp_id	= trrsh.comp_id		AND
						       	   						trrsd.rmast_id	= trrsh.rmast_id	AND
														ISNULL(trrsd.rmastd_isReturned,'False') = 'False') = 0)		--ENVIADO CON RECEPCIÓN TOTAL
					)
		END

GO



CREATE PROCEDURE spRMA_Repair2SupplierHeader_GetDataByID
(
	@comp_id	INT,
	@rmast_id	INT
)
AS
	SET NOCOUNT ON
		BEGIN

			SELECT
				trrsh.comp_id,
				trrsh.rmast_id,
