			FROM tbRMA_Repair2SupplierHeader	trrsh

			WHERE	trrsh.comp_id	= @comp_id	AND
					trrsh.rmast_id	= @rmast_id

		END


GO



CREATE PROCEDURE [dbo].[spRMA_Repair2SupplierHeader_InsertData]
(
	@comp_id	INT,
	@user_id	INT,
	@note		VARCHAR(4000),
	@supp_id	INT,
	@bra_id		INT
)
AS
	SET NOCOUNT ON

		BEGIN

			INSERT INTO tbRMA_Repair2SupplierHeader
			(
				comp_id,
				rmast_cd,
				user_id,
				rmast_note,
				supp_id,
				bra_id,
				rmast_isEnvied
			)
			VALUES
			(
