CREATE PROCEDURE spRMA_Repair2SupplierHeader_UpdateStatus
(
	@comp_id	INT,
	@rmast_id	INT
)
AS
	SET NOCOUNT ON
		BEGIN

			IF (SELECT
					COUNT(*)
				FROM tbRMA_Repair2SupplierDetail							trrsd
				WHERE	trrsd.comp_id							= @comp_id	AND
						trrsd.rmast_id							= @rmast_id	AND
						ISNULL(trrsd.rmastd_isReturned,'False') = 'False') = 0

				BEGIN
					UPDATE tbRMA_Repair2SupplierHeader
					SET
						rmast_isEnvied	= 'True'
					WHERE	comp_id		= @comp_id AND
							rmast_id	= @rmast_id
				END
			ELSE
				BEGIN
					UPDATE tbRMA_Repair2SupplierHeader
					SET
						rmast_isEnvied	= 'False'
					WHERE	comp_id		= @comp_id AND
							rmast_id	= @rmast_id
				END

		END

GO








CREATE PROCEDURE [dbo].[spRMA_reverseProcess]
(
	@comp_id		INT,
	@bra_id			INT,
	@soh_id			INT,
	@prof_id		INT
)
AS

BEGIN



	-- ATENCION, si es 80 o 90 se revertira SOLO cuando borren el pedido del REMITO
	-- que es el que tiene asoiado el RMA


	SET NOCOUNT ON

	-- ----------------------------------------------------------------
	-- Test
	-- ----------------------------------------------------------------
	/*
	DECLARE	@comp_id		INT,
			@bra_id			INT,
			@soh_id			INT
	SELECT 	@comp_id		=1,
			@bra_id			=1,
			@soh_id			=8488
	*/
	-- ----------------------------------------------------------------


	-- Si la reversion esta deshabilitada por perfil NO LA HACE.
	IF EXISTS(
					SELECT 1
						FROM tbControlProfiles tcp1		WITH (NOLOCK)
						WHERE	tcp1.page_id	= 80000		AND
								tcp1.ctrl_id	= 5093		AND
								tcp1.bra_id		= @bra_id	AND
								tcp1.prof_id	= @prof_id	AND
								tcp1.prop_id	= 20
			)
		BEGIN
			RETURN
		END




	DECLARE @lrmah_id					INT,
			@lrmad_id					INT,
			@lsrpt_id					INT,
			@lsod_qty					DECIMAL(19,5),
			@litem_id					INT,
			@now						DATETIME,
			@lstor_id_Stock				INT,
			@lcust_id					INT,
			@luser_id					INT,
			@lrmad_originalPrice		DECIMAL(19,5),
			@intSm_id					INT,
			@intDisc_id					INT,
			@intDl_id					INT,
			@intSt_id					INT,
			@ct_CompanyCurrency			INT,
			@CustomerCurrencyId			INT,
			@BranchCurrencyId			INT,
			@lrmad_curr_id				INT



	-- obtener la fecha actual
	SET @now	= GETDATE()



	-- recuperamos los datos de todos los RMA_Detail relacionados al nro. de Pedido recibido por parámetro
	DECLARE cursor_so CURSOR LOCAL FAST_FORWARD FOR
	SELECT	tsod.rmah_id,
			tsod.rmad_id,
			trd.srpt_id,
			tsod.sod_qty,
			tsod.item_id,
			trh.cust_id,
			tsod.[user_id],
			trd.rmad_originalPrice,
			tsod.curr_id

	FROM	tbSaleOrderDetail					tsod		WITH (NOLOCK)

			INNER JOIN tbRMA_Header				trh			WITH (NOLOCK)
			ON	trh.comp_id		= tsod.comp_id
			AND trh.rmah_id		= tsod.rmah_id

			INNER JOIN tbRMA_Detail				trd			WITH (NOLOCK)
			ON	trd.comp_id		= tsod.comp_id
			AND trd.rmah_id		= tsod.rmah_id
			AND trd.rmad_id		= tsod.rmad_id
			AND trd.srpt_id		IN (10,20,30,35,40,50,80,90)

	WHERE	tsod.comp_id		= @comp_id
	AND		tsod.bra_id			= @bra_id
	AND		tsod.soh_id			= @soh_id
	AND		NOT tsod.rmah_id	IS NULL
	AND		NOT tsod.rmad_id	IS NULL


	-- procesamiento del cursor generado
	OPEN cursor_so


	FETCH	cursor_so
	INTO	@lrmah_id,
			@lrmad_id,
			@lsrpt_id,
			@lsod_qty,
			@litem_id,
			@lcust_id,
			@luser_id,
			@lrmad_originalPrice,
			@lrmad_curr_id


	WHILE @@FETCH_STATUS = 0
	BEGIN


		--para todos los estados de los artículos en los RMA recuperado se debe modificar ese estado a: SIN PROCESAR-1
		UPDATE	tbRMA_Detail	WITH (ROWLOCK)
			SET		srpt_id		= 1
			WHERE	comp_id		= @comp_id
			AND		rmah_id		= @lrmah_id
			AND		rmad_id		= @lrmad_id




		IF @lsrpt_id = 35
		BEGIN

			--si el estado de los artículos en los RMA son:
			--		Funciona MAL - Se cambia por igual mercadería -35
			--se debe revertir el proceso realizado cuando se procesó


			--recuperamos datos de la Sucursal
			SELECT	@lstor_id_Stock	= bra_RMA_storId4Bad
   	 			FROM	tbBranch				tb		WITH (NOLOCK)
   	 			WHERE	tb.comp_id	= @comp_id
   	 			AND		tb.bra_id	= @bra_id




 			--recuperamos datos del Cliente
			SELECT	@intSm_id				= cu.sm_id,
					@intDisc_id				= cu.disc_id,
					@intDl_id				= cu.dl_id,
					@intSt_id				= cu.st_id,
					@customerCurrencyId		= cu.curr_id
				FROM	dbo.tbCustomer			cu	WITH (NOLOCK)
				WHERE	cu.comp_id				= @comp_id
				AND		cu.cust_id				= @lcust_id



   	 		DECLARE @it_order				INT,
					@lct_transaction_rv		INT,
					@lit_transaction_rv		INT

			SET		@it_order	= 1



			-- actualizar el depósito del artículo del rma
			EXEC spItemStorage_insertData @comp_id, @litem_id, @lstor_id_Stock, 0


			-- generación de comprobante
			EXEC dbo.spRMA_insertTransaction
					@comp_id,				@bra_id,				@lcust_id,			NULL,
					@luser_id,				@lstor_id_Stock,		@litem_id,			@lsod_qty,
					@lrmad_originalPrice,	@customerCurrencyId,	@lrmad_curr_id,		@BranchCurrencyId,
					@ct_CompanyCurrency,	@it_order,				@lrmah_id,			@lrmad_id,
					@intSm_id,
					@intDisc_id,			@intDl_id,				@intSt_id,			@now,
					302, -- MOS 08-2017
					@ct_transaction_rv = @lct_transaction_rv OUTPUT,
					@it_transaction_rv = @lit_transaction_rv OUTPUT


			-- se incorpora el artículo al depósito del detalle del rma
			UPDATE	tbItemStorage	WITH (ROWLOCK)
				SET		itst_cant	= itst_cant - @lsod_qty,
						itst_cd		= @now
				WHERE	comp_id		= @comp_id
				AND		stor_id		= @lstor_id_Stock
				AND		item_id		= @litem_id

		END



		FETCH	cursor_so
		INTO	@lrmah_id,
				@lrmad_id,
				@lsrpt_id,
				@lsod_qty,
				@litem_id,
				@lcust_id,
				@luser_id,
				@lrmad_originalPrice,
				@lrmad_curr_id

	END


	CLOSE cursor_so
	DEALLOCATE cursor_so



END
GO





CREATE procedure [dbo].[spRMA_Status_GetCombo]
(
	@comp_id	int
)

as set NOCOUNT on

begin

	select
		trs.rmas_id			[Id],
		trs.rmas_desc		[Desc]
	from tbRMA_Status trs

	where trs.comp_id  =	@comp_id
	ORDER BY trs.rmas_desc


end
GO






CREATE PROCEDURE [dbo].[spRMA_updateCommonData]
(
	@comp_id					INT,
	@bra_id						INT,
	@rmah_id					INT,
	@rmadt_guid					UNIQUEIDENTIFIER,
	@cust_id					INT,
	@supp_id					INT,
	@rmah_cd					DATETIME,
	@user_id					INT,
	@return_value				INT OUTPUT		-- NO USAR VALORES NEGATIVOS !!!!!
)
AS

BEGIN




	SET NOCOUNT ON
	-- MOS 08-2009
	-- =================================================================================================================
	-- Author		: STL
	-- Update Date	: 2013-12-09
	-- TN			: Referencia: #9
	-- Description	: SE REALIZÓ LA ACTUALIZACIÓN DE LOS CAMPOS DE RMA_FIXPRICES YA QUE NO SE ESTABAN CARGANDO EN LA
	--				  TABLA RMA_DETAIL DEFINITIVA
	-- =================================================================================================================

-- ----------------------------------------------------------
-- Testing
-- ----------------------------------------------------------
	/*
	DECLARE 	@comp_id					int,
				@bra_id						int,
				@rmah_id					INT,
				@rmadt_guid					uniqueidentifier,
				@cust_id					int,
				@supp_id					INT,
				@rmah_cd					datetime,
				@user_id					int
	SELECT		@comp_id					=1,
				@bra_id						=1,
				@rmah_id					=282,
				@rmadt_guid					='e8bbebca-3484-47e6-9dca-76ca15d1dace',
				@cust_id					=24288,
				@supp_id					=null,
				@rmah_cd					=GETDATE(),
				@user_id					=1
	*/
-- ----------------------------------------------------------






	-- ----------------------------------------------------------------
	-- Forros de FIESA y LPMQLP, quieren por CAPRICHO que si se ingresan desde el sitio web se acumulen x día.
	-- Para NO romper nada paso el parámetro de CLIENTE en negativo desde VS  **ewflkn0927340adnqwldkn
	-- ----------------------------------------------------------------
	DECLARE @bitFromWebSite AS BIT = 'False'
	IF @cust_id < 0
		BEGIN
			SET @cust_id		= @cust_id * -1
			SET @bitFromWebSite = 'True'
		END
	-- ----------------------------------------------------------------








		DECLARE @intBraId AS INT
		SET		@intBraId = @bra_id

		SET @return_value = 0

		DECLARE @bra_processingDate			DATETIME,
				@prli_id					INT,
				@intStor_id_b				INT,
				@bra_RMA_dfId4Packing		INT,
				--@bra_RMA_dfId4Credit		INT,
				@bra_RMA_storId4OK			INT,
				@bra_RMA_storId4Scrap		INT,
				@bra_RMA_storId4Bad			INT,
				@intSm_id					INT,
				@intDisc_id					INT,
				@intDl_id					INT,
				@intSt_id					INT,
				@ct_CompanyCurrency			INT,
				@CustomerCurrencyId			INT,
				@BranchCurrencyId			INT,
				@curItem_id					INT,
				@curstor_id					INT,
				@curRma_qty					DECIMAL(19,4),
				@intDf_Id4AddItems			INT,
				@curTaxId					INT,
				@curPrli_Id					INT,
				@curItemPrice				AS DECIMAL(19,6),
				@curItemCurrency			AS INT,
				@intSaleOrderHeaderUpdated	AS INT,
				@curErrorGenerator			AS INT,
				@curIs_ID					AS INT,
				@curIdofItemAdd				AS INT,
				@decFixPrice				AS DECIMAL(19,4),
				@intFixPriceCurrency		AS INT,
				@strFixPriceDesc			AS NVARCHAR(200),
				@intFixPriceTaxId			AS INT,
				@bra_RMA_useDFIdOfOriginalBranch AS BIT = 'False'




		-- Branch
		SELECT 	@bra_processingDate		= tb.bra_processingDate,
				@prli_id				= tb.bra_RMA_prli_Id4NoSerialItems,
				@intStor_id_b			= tb.stor_id,
				@bra_RMA_dfId4Packing	= tb.bra_RMA_dfId4Packing,
				--@bra_RMA_dfId4Credit	= tb.bra_RMA_dfId4Credit,
				@bra_RMA_storId4OK		= tb.bra_RMA_storId4OK,
				@bra_RMA_storId4Scrap	= tb.bra_RMA_storId4Scrap,
				@bra_RMA_storId4Bad		= tb.bra_RMA_storId4Bad,
				@BranchCurrencyId		= tb.curr_id,
				@bra_RMA_useDFIdOfOriginalBranch
									    = ISNULL(bra_RMA_useDFIdOfOriginalBranch,'False')
			FROM	dbo.tbBranch			tb			WITH (NOLOCK)
			WHERE	tb.comp_id				= @comp_id
			AND		tb.bra_id				= @bra_id


		-- Customer
		SELECT	@intSm_id				= cu.sm_id,
				@intDisc_id				= cu.disc_id,
				@intDl_id				= cu.dl_id,
				@intSt_id				= cu.st_id,
				@customerCurrencyId		= cu.curr_id
			FROM	dbo.tbCustomer			cu			WITH (NOLOCK)
			WHERE	cu.comp_id				= @comp_id
			AND		cu.cust_id				= @cust_id


		-- Company
		SELECT	@ct_CompanyCurrency		= comp.curr_id
			FROM	dbo.tbCompany			comp		WITH (NOLOCK)
			WHERE	comp.comp_id			= @comp_id



		-- ----------------------------------------------------------------
		-- Si por alguna casualidad deja de funcionar el isediting
		-- y se borran los contenidos del rma, no graba nada.
		-- ----------------------------------------------------------------
		IF NOT EXISTS(
						SELECT TOP 1 	1
							FROM	tbRMA_Detail_Tmp	trdt		WITH (NOLOCK)
							WHERE	trdt.rmadt_guid		= @rmadt_guid
		)
			BEGIN
					SET @return_value = 24
					RETURN
			END
		-- ----------------------------------------------------------------


		-- ========================================================================================================
		-- Borra los items que se borraron de la temporal.
		-- ========================================================================================================
		DELETE FROM tbRMA_AddItems			WITH (ROWLOCK)
			FROM	tbRMA_AddItems trd
			WHERE	trd.comp_id		= @comp_id
			AND		trd.rmah_id		= @rmah_id
			AND		NOT EXISTS (SELECT TOP 1 	1
										FROM	tbRMA_Detail_Tmp	trdt	WITH (NOLOCK)
										WHERE	trdt.comp_id		= trd.comp_id	AND
												trdt.rmah_id		= trd.rmah_id	AND
												trdt.rmadt_guid		= @rmadt_guid	AND
										        trdt.rmad_id        = trd.rmad_id)

		DELETE FROM tbRMA_Detail_attributesHistory			WITH (ROWLOCK)
			FROM	tbRMA_Detail_attributesHistory trd
			WHERE	trd.comp_id		= @comp_id
			AND		trd.rmah_id		= @rmah_id
			AND		NOT EXISTS (SELECT	TOP 1 1
										FROM	tbRMA_Detail_Tmp	trdt	WITH (NOLOCK)
										WHERE	trdt.comp_id		= trd.comp_id	AND
												trdt.rmah_id		= trd.rmah_id	AND
												trdt.rmadt_guid		= @rmadt_guid	AND
										        trdt.rmad_id        = trd.rmad_id)

		IF @bitFromWebSite = 'False'	-- FIESA, solo borra si NO es ingreso x website!!!	**ewflkn0927340adnqwldkn
			BEGIN
				DELETE FROM tbRMA_Detail			WITH (ROWLOCK)
					FROM	tbRMA_Detail trd
					WHERE	trd.comp_id		= @comp_id
					AND		trd.rmah_id		= @rmah_id
					AND		NOT EXISTS (SELECT	TOP 1 1
												FROM	tbRMA_Detail_Tmp	trdt	WITH (NOLOCK)
												WHERE	trdt.comp_id		= trd.comp_id	AND
														trdt.rmah_id		= trd.rmah_id	AND
														trdt.rmadt_guid		= @rmadt_guid	AND
														trdt.rmad_id        = trd.rmad_id)
			END
		-- ========================================================================================================




		-- declaración de variables para obtener los datos del cursor
		declare	@lrmadt_id					INT,
				@lit_transaction			INT,
				@litem_id					INT,
				@lstor_id					INT,
				@lrmadt_Manual				VARCHAR(100),
				@lrmadt_originalPrice		DECIMAL(19,6),
				@lrmadt_curr_id				INT,
				@lrmadt_qty					DECIMAL(19,5),
				@luser_id_Reception			INT,
				@lrmadt_Date_Reception		DATETIME,
				@lrmadt_ReceptionNote		VARCHAR(8000),
				@lis_id						INT,
				@luser_id_Diagnostic		INT,
				@lrmadt_Date_Diagnostic		DATETIME,
				@lrmadt_DiagnosticNote		VARCHAR(8000),
				@lsrpt_id					INT,
				@lrmadt_ProcNote            VARCHAR(8000),
				@ldf_id4CreditNote			INT,
				@tis_id						INT,
				@lrv						INT,
				@lrmadt_isNew				BIT,
				@ltis_priority				DECIMAL(14,4),
				@litem_desc					VARCHAR(200),
				@lrmadt_isNewItem			BIT,
				@l_rmah_id					INT,
				@l_rmad_id					INT,
				@lsupp_id					INT,
				@limpData_Custom_local		NVARCHAR(200),
				@limpData_Number_local		NVARCHAR(200),
				@lrmad_IncludeInPotentialStock	BIT,
				--STL PUNTO 22 NUCLEO
				@rmas_id					INT,
				@rmap_id					INT,
				@item_id4Replacement		INT,
				@rmaw_id					INT,
				@rmamt_id					INT,
				@user_id_Proc				INT,
				@user_id_Delivery			INT,
				@intIt_TransactionCN		INT,
				@rmafailP_id				INT,
				@rmadt_serial				VARCHAR(200),
				@stor_id4Replacement		INT,
				@RMA_Up2Price				DECIMAL(19,6),
				@case_id					INT,
				@rmad_relatedID				INT,
				@it_transaction_Origin		INT,
				@rmad_insertWarrantyDetail	NVARCHAR(1000),
				@rmad_insertWarrantyCertificates	NVARCHAR(100),
				@rmad_bra_id					 AS INT,
				@rmad_isAvailable4DeliverySheet		BIT,
				@sds_id4Delivery					INT,
				@sds_id4Picking						INT,
				@dl_id4Picking						INT,
				@dl_id4Delivery						INT,
				@rmad_deliveryDate4Picking			DATETIME,
				@rmad_deliveryDate4Delivery			DATETIME,
				@rmad_Date_estimatedFinalization	DATETIME,
				@rmad_handOverDate					DATETIME,
				@rmad_handOver_user_id				INT







		-- declaración del cursor para obtener los datos de tbRMADetailTmp
		declare cursor_RMA_iD_items CURSOR LOCAL  FAST_FORWARD for
		select	trdt.rmadt_id,
				trdt.it_transaction,
				trdt.item_id,
				trdt.stor_id,
				trdt.rmadt_Manual,
				trdt.rmadt_originalPrice,
				trdt.curr_id,
				trdt.rmadt_qty,
				trdt.user_id_Reception,
				trdt.rmadt_Date_Reception,
				trdt.rmadt_ReceptionNote,
				trdt.is_id,
				trdt.user_id_Diagnostic,
				trdt.rmadt_Date_Diagnostic,
				trdt.rmadt_DiagnosticNote,
				trdt.srpt_id,
				trdt.rmadt_ProcNote,
				trdt.df_id4CreditNote,
				trdt.tis_id,
				trdt.rmadt_isNew,
				ISNULL(ttis.tis_priority,0),
				ISNULL(ti.item_desc,''),
				trdt.rmadt_isNewItem,
				trdt.rmah_id,
				trdt.rmad_id,
				trdt.supp_id,
				trdt.impData_Custom_local,
				trdt.impData_Number_local,
				trdt.rmad_IncludeInPotentialStock,
				trdt.rmas_id,
				trdt.rmap_id,
				trdt.item_id4Replacement,
				trdt.rmaw_id,
				trdt.rmamt_id,
				trdt.user_id_Proc,
				trdt.user_id_Delivery,
				trdt.it_transaction_CN,
				trdt.rmafailP_id,
				ISNULL(trdt.rmadt_serial,''),
				trdt.stor_id4Replacement,
				ISNULL(trdt.rmadt_up2Price,0)		[rmadt_up2Price],
				trdt.case_id,
				trdt.rmad_relatedID,
				trdt.it_transaction_Origin,
				trdt.rmad_insertWarrantyDetail,
				trdt.rmad_insertWarrantyCertificates,
				trdt.bra_id_original,
				trdt.rmad_isAvailable4DeliverySheet,
				--CASE	WHEN trdt.sds_id4Delivery <> 0 AND trdt.dsd_id4Delivery IS not null	 THEN trdt.sds_id4Delivery
				--ELSE
				--		trdt.sds_id4Picking
				--END	 [sds_id4Delivery]
				trdt.sds_id4Delivery,
				trdt.sds_id4Picking,
				trdt.dl_id4Picking,
				trdt.dl_id4delivery,
				trdt.rmad_deliveryDate4Picking,
				trdt.rmad_deliveryDate4Delivery,
				trdt.rmad_Date_estimatedFinalization,
				trdt.rmad_handOverDate,
				trdt.rmad_handOver_user_id


			from	dbo.tbRMA_Detail_Tmp				trdt	WITH (ROWLOCK)

			LEFT JOIN tbTempItemStock					ttis	WITH (NOLOCK)
				ON	ttis.comp_id	= trdt.comp_id
				AND ttis.tis_guid	= trdt.rmadt_guid
				AND ttis.is_id		= trdt.is_id

			LEFT JOIN tbItem							ti		WITH (NOLOCK)
				ON	ti.comp_id		= trdt.comp_id
				AND ti.item_id		= trdt.item_id

			where	trdt.rmadt_guid		= @rmadt_guid


		--abrir cursor
		OPEN	cursor_RMA_iD_items



		-- lectura anticipada del cursor
		fetch	cursor_RMA_iD_items
		into	@lrmadt_id,
				@lit_transaction,
				@litem_id,
				@lstor_id,
				@lrmadt_Manual,
				@lrmadt_originalPrice,
				@lrmadt_curr_id,
				@lrmadt_qty,
				@luser_id_Reception,
				@lrmadt_Date_Reception,
				@lrmadt_ReceptionNote,
				@lis_id,
				@luser_id_Diagnostic,
				@lrmadt_Date_Diagnostic,
				@lrmadt_DiagnosticNote,
				@lsrpt_id,
				@lrmadt_ProcNote,
				@ldf_id4CreditNote,
				@tis_id,
				@lrmadt_isNew,
				@ltis_priority,
				@litem_desc,
				@lrmadt_isNewItem,
				@l_rmah_id,
				@l_rmad_id,
				@lsupp_id,
				@limpData_Custom_local,
				@limpData_Number_local,
				@lrmad_IncludeInPotentialStock,
				--STL PUNTO 22 NUCLEO
				@rmas_id,
				@rmap_id,
				@item_id4Replacement,
				@rmaw_id,
				@rmamt_id,
				@user_id_Proc,
				@user_id_Delivery,
				@intIt_TransactionCN,
				@rmafailP_id,
				@rmadt_serial,
				@stor_id4Replacement,
				@RMA_Up2Price,
				@case_id,
				@rmad_relatedID,
				@it_transaction_Origin,
				@rmad_insertWarrantyDetail,
				@rmad_insertWarrantyCertificates,
				@rmad_bra_id,
				@rmad_isAvailable4DeliverySheet,
				@sds_id4Delivery,
				@sds_id4Picking,
				@dl_id4Picking,
				@dl_id4Delivery,
				@rmad_deliveryDate4Picking,
				@rmad_deliveryDate4Delivery,
				@rmad_Date_estimatedFinalization,
				@rmad_handOverDate,
				@rmad_handOver_user_id





		DECLARE @it_order	INT
		SET		@it_order	= 0



		-- se recorre el cursor hasta el fin del mismo
		WHILE @@fetch_status = 0
			BEGIN

				SET @it_order = @it_order + 1

				DECLARE @lrmad_id	INT


				-- Si es RMA PROVEEDOREs este campo NO puede estar en TRUE
				IF @cust_id IS NULL
					BEGIN
						SET @lrmad_IncludeInPotentialStock = 'False'
					END


				-- ========================================================================================================
				-- Ref: #5
				IF @l_rmah_id IS NULL AND @l_rmad_id IS NULL
					BEGIN

						-- si es un item nuevo se realiza el insert en la tabla detalle de RMA
						EXEC 	dbo.spRMADetail_insertData
								@comp_id,					@rmah_id,					@bra_id,
								@lit_transaction,			@litem_id,					@lstor_id,
								@lrmadt_Manual,				@lrmadt_originalPrice,		@lrmadt_curr_id,
								@lrmadt_qty,				@luser_id_Reception,		@lrmadt_ReceptionNote,
								@lis_id,					@luser_id_Diagnostic,		@lrmadt_Date_Diagnostic,
								@lrmadt_DiagnosticNote,		@ldf_id4CreditNote,			@lsrpt_id,
								@lrmadt_ProcNote,			@lrmadt_isNewItem,			@lsupp_id,
								@limpData_Custom_local,		@limpData_Number_local,
								--STL PUNTO 22 NUCLEO
								@rmas_id, @rmap_id,
								@item_id4Replacement,
								@rmaw_id,
								@rmamt_id,
								@user_id_Proc,
								@user_id_Delivery,
								@return_value = @lrmad_id OUTPUT




						-- Si ponen un articulo que necesita tener el mismo articulo como adicional al ser ingresado lo hace aca
						IF @cust_id IS NOT NULL AND @litem_id IS NOT NULL
							BEGIN
								IF EXISTS(
											SELECT TOP 1 1
												FROM tbitem		WITH (NOLOCK)
												WHERE	comp_id = @comp_id AND
														item_id = @litem_id AND
														item_RMACloneItemInAdditionalPartsOnInsert = 'True'
										)
									BEGIN


										DECLARE @decRMAPrice	AS DECIMAL(19,6)
										DECLARE @intRMACurrency AS INT
										DECLARE @intRMAStor_id	AS INT
										SET		@intRMACurrency = 1
										SET		@decRMAPrice	= 0


										SELECT	@decRMAPrice	= tpli.prli_price,
												@intRMACurrency = tpli.curr_id,
												@intRMAStor_id  = tb.bra_RMA_stor_id4Reparation
											FROM tbBranch tb					WITH (NOLOCK)
											INNER JOIN tbPriceListItems tpli	WITH (NOLOCK)
											ON	tpli.comp_id = @comp_id AND
												tpli.prli_id = tb.bra_RMA_prli_id4AdditionalItems	AND
												tpli.item_id = @litem_id
											WHERE	tpli.comp_id = @comp_id AND
													tpli.item_id = @litem_id


										INSERT INTO tbRMA_Detail_AddItems		WITH (ROWLOCK)
										(
											comp_id,
											-- rmaa_id -- this column value is auto-generated,
											rmah_id,
											rmad_id,
											stor_id,
											item_id,
											rmaa_qty,
											is_id,
											rmaa_order
										)
										VALUES
										(
											@comp_id,
											@rmah_id,
											@lrmad_id,
											@intRMAStor_id,
											@litem_id,
											1,
											NULL,
											-1
										)


									END
							END




								--==STL PARA NO TOCAR EL SP ANTERIOR #7
								--==STL PRECIOS DE LA REPARACIÓN MOS #9
								-- Precios de la Reparacion.-
								-----------------------------------------------------

								DECLARE
									@lIntFixPriceId	INT,
									@rmafp_SOInPL	BIT = 'False'


								SELECT @decFixPrice			= trdt.rmafp_Price,
									   @intFixPriceCurrency = trdt.rmafp_curr_id,
									   @strFixPriceDesc		= trfp.rmafp_desc,
									   @lIntFixPriceId		= trfp.rmafp_id,
									   @rmadt_serial		= trdt.rmadt_serial,
									   @intFixPriceTaxId	= trfp.tax_id,
									   @rmafp_SOInPL		= ISNULL(trfp.rmafp_SOInPL,'False')
									FROM tbRMA_Detail_Tmp trdt						WITH (NOLOCK)
									INNER JOIN tbRMA_FixPrices trfp				WITH (NOLOCK)
										ON	trfp.comp_id  = @comp_id AND
											trfp.rmafp_id = trdt.rmafp_id
									WHERE	trdt.comp_id	= @comp_id AND
											trdt.rmadt_id	= @lrmadt_id
									/*
									WHERE	trdt.comp_id  = @comp_id		AND
											trdt.rmad_id  = @l_rmad_id		AND
											trdt.rmah_id  = @rmah_id
									*/
								-----------------------------------------------------

								--ACTUALIZAMOS LOS CAMPOS FALTANTES EN LA DETAIL

								UPDATE tbRMA_Detail			WITH (ROWLOCK)
									SET
										it_transaction_CN				= @intIt_TransactionCN,
										rmafailP_id						= @rmafailP_id,
										rmad_serial						= @rmadt_serial,
										stor_id4Replacement				= @stor_id4Replacement,
										rmad_up2Price					= @RMA_Up2Price,
										case_id							= @case_id,
										rmad_relatedID					= @rmad_relatedID,
										it_transaction_Origin			= @it_transaction_Origin,
										rmad_insertWarrantyDetail		= @rmad_insertWarrantyDetail,
										rmad_insertWarrantyCertificates = @rmad_insertWarrantyCertificates,
										bra_id_original					= @rmad_bra_id,
										rmad_isAvailable4DeliverySheet	= @rmad_isAvailable4DeliverySheet,
										sds_id4Picking					= @sds_id4Picking,   --(case when dsd_id4Picking IS NULL then sds_id4Picking else @sds_id4Delivery end),
										sds_id4Delivery					= @sds_id4Delivery, --(case WHEN dsd_id4Delivery IS NULL then sds_id4Delivery else @sds_id4Delivery end)
										dl_id4Picking					= @dl_id4Picking,
										dl_id4delivery					= @dl_id4Delivery,
										rmad_deliveryDate4Picking		= @rmad_deliveryDate4Picking,
										rmad_deliveryDate4Delivery		= @rmad_deliveryDate4Delivery,
										rmad_Date_estimatedFinalization = @rmad_Date_estimatedFinalization,
										rmad_handOverDate				= @rmad_handOverDate,
										rmad_handOver_user_id			= @rmad_handOver_user_id

									WHERE	comp_id		= @comp_id	AND
											rmad_id		= @lrmad_id

								--SOLO SI SE CANCELO POR 80 O POR 90
								IF (@lsrpt_id = 80) OR (@lsrpt_id = 90)
									BEGIN

										UPDATE tbRMA_Detail			WITH (ROWLOCK)
										SET
											rmafp_id			= @lIntFixPriceId,
											rmafp_Price			= @decFixPrice,
											rmafp_curr_id		= @intFixPriceCurrency,
											rmafp_tax_id		= @intFixPriceTaxId


										WHERE	comp_id		= @comp_id	AND
												rmad_id		= @lrmad_id

									END

								-- --------------------------------------------------------------------
								-- #STL 24-05-2016
								-- GRABAMOS EL REGISTRO PARA EL HISTÓRICO DE ESTADOS, PRIORIDADES,
								-- GARANTÍAS Y TIPO DE MERCADERÍA
								-- --------------------------------------------------------------------
									DECLARE @rmadh_id	INT
									SET		@rmadh_id	= 0
									EXEC	spRMA_Detail_AttributesHistory_InsertData
											@comp_id,	@rmah_id,		@lrmad_id,
											@user_id,	@lsrpt_id,		@rmas_id,
											@rmap_id,	@rmaw_id,		@rmamt_id,
											@rmadh_id
								-- --------------------------------------------------------------------

							IF EXISTS(
										SELECT TOP 1  1
											FROM tbitem		WITH (NOLOCK)
											WHERE	comp_id = @comp_id AND
													item_id = @litem_id
										)
								BEGIN
									DECLARE @decAddItem_Price	AS DECIMAL(19,4)
									DECLARE @intAddItem_CurrID	AS INT
									SELECT	@decAddItem_Price  = tpli.prli_price,
											@intAddItem_CurrID = tpli.curr_id
										FROM tbBranch tb						WITH (NOLOCK)
										INNER JOIN tbPriceListItems tpli		WITH (NOLOCK)
											ON	tpli.comp_id = tb.comp_id	AND
												tpli.prli_id = tb.bra_RMA_prli_id4AdditionalItems	AND
												tpli.item_id = @litem_id
										WHERE	tb.comp_id	 = @comp_id		AND
												tb.bra_id	 = @bra_id
									IF @decAddItem_Price IS NOT NULL
										BEGIN
											INSERT INTO tbRMA_AddItems		WITH (ROWLOCK)
											(
												comp_id,
												rmah_id,
												rmad_id,
												-- rmaai_id -- this column value is auto-generated,
												item_id,
												rmaai_qty,
												rmaai_price,
												curr_id
											)
											VALUES
											(
												@comp_id,
												@rmah_id,
												@lrmad_id,
												@litem_id,
												1,
												@decAddItem_Price,
												@intAddItem_CurrID
											)
										END
								END

					END

				ELSE
					BEGIN

						IF EXISTS (	SELECT TOP 1  1
										FROM	tbRMA_Detail trd				WITH (NOLOCK)
										WHERE	trd.comp_id	= @comp_id		AND		-- MOS 09-2024
												trd.rmah_id = @l_rmah_id	AND
												trd.rmad_id = @l_rmad_id)
							BEGIN

								--si existe se actualiza
								EXEC	dbo.spRMADetail_updateData
										@comp_id,					@l_rmah_id,						@l_rmad_id,
										@bra_id,					@lit_transaction,				@litem_id,
										@lstor_id,					@lrmadt_Manual,					@lrmadt_originalPrice,
										@lrmadt_curr_id,			@lrmadt_qty,					@luser_id_Reception,
										@lrmadt_ReceptionNote,		@lis_id,						@luser_id_Diagnostic,
										@lrmadt_Date_Diagnostic,	@lrmadt_DiagnosticNote,			@ldf_id4CreditNote,
										@lsrpt_id,					@lrmadt_ProcNote,				@lrmadt_isNewItem,
										@lsupp_id,					@limpData_Custom_local,			@limpData_Number_local,
										--STL PUNTO 22 NUCLEO
										@rmas_id, @rmap_id,
										@item_id4Replacement,
										@rmaw_id,
										@rmamt_id,
										@user_id_Proc,
										@user_id_Delivery

								--==STL PARA NO TOCAR EL SP ANTERIOR #7
								UPDATE tbRMA_Detail_Tmp			WITH (ROWLOCK)
								SET
									it_transaction_CN	= @intIt_TransactionCN,
									rmafailP_id			= @rmafailP_id,
									rmadt_serial		= @rmadt_serial
								WHERE	comp_id			= @comp_id	AND
										rmadt_id		= @l_rmad_id


								--UPDATE tbRMA_Detail_Tmp
								--SET
								--	sds_id4Picking		= @sds_id4Picking,
								--	sds_id4Delivery		= @sds_id4Delivery

								--WHERE	comp_id			= @comp_id	AND
								--		rmadt_id		= @l_rmad_id


								--==STL PARA NO TOCAR EL SP ANTERIOR #7
								--==STL PRECIOS DE LA REPARACIÓN MOS #9
								-- Precios de la Reparacion.-
								-----------------------------------------------------

								DECLARE
									@lIntFixPriceId2	INT

								SELECT @decFixPrice			= trdt.rmafp_Price,
									   @intFixPriceCurrency = trdt.rmafp_curr_id,
									   @strFixPriceDesc		= trfp.rmafp_desc,
									   @lIntFixPriceId2		= trfp.rmafp_id,
									   @intFixPriceTaxId	= trfp.tax_id
									FROM tbRMA_Detail_Tmp trdt						WITH (NOLOCK)
										INNER JOIN tbRMA_FixPrices trfp				WITH (NOLOCK)
											ON	trfp.comp_id  = @comp_id AND
												trfp.rmafp_id = trdt.rmafp_id
									WHERE	trdt.comp_id	= @comp_id AND
											trdt.rmadt_id	= @lrmadt_id
									/*
									WHERE	trdt.comp_id  = @comp_id		AND
											trdt.rmad_id  = @l_rmad_id		AND
											trdt.rmah_id  = @l_rmah_id
									*/
								-----------------------------------------------------
								--ACTUALIZAMOS LOS CAMPOS FALTANTES EN LA DETAIL

								UPDATE tbRMA_Detail		WITH (ROWLOCK)
									SET
										it_transaction_CN				= @intIt_TransactionCN,
										rmafailP_id						= @rmafailP_id,
										rmad_serial						= @rmadt_serial,
										stor_id4Replacement				= @stor_id4Replacement,
										rmad_up2Price					= @RMA_Up2Price,
										case_id							= @case_id,
										rmad_relatedID					= @rmad_relatedID,
										it_transaction_Origin			= @it_transaction_Origin,
										rmad_insertWarrantyDetail		= @rmad_insertWarrantyDetail,
										rmad_insertWarrantyCertificates = @rmad_insertWarrantyCertificates,
										rmad_isAvailable4DeliverySheet	= @rmad_isAvailable4DeliverySheet,
										sds_id4Delivery					= @sds_id4Delivery,
										sds_id4Picking					= @sds_id4Picking,
										dl_id4Picking					= @dl_id4Picking,
										dl_id4delivery					= @dl_id4Delivery,
										rmad_deliveryDate4Picking		= @rmad_deliveryDate4Picking,
										rmad_deliveryDate4Delivery		= @rmad_deliveryDate4Delivery,
										rmad_Date_estimatedFinalization = @rmad_Date_estimatedFinalization,
										rmad_handOverDate				= @rmad_handOverDate,
										rmad_handOver_user_id			= @rmad_handOver_user_id
									WHERE	comp_id		= @comp_id	AND
											rmad_id		= @l_rmad_id


								--SOLO SI SE CANCELO POR 80 O POR 90
								IF (@lsrpt_id = 80) OR (@lsrpt_id = 90)
									BEGIN

										UPDATE tbRMA_Detail		WITH (ROWLOCK)
										SET
											rmafp_id			= @lIntFixPriceId2,
											rmafp_Price			= @decFixPrice,
											rmafp_curr_id		= @intFixPriceCurrency,
											rmafp_tax_id		= @intFixPriceTaxId

										WHERE	comp_id		= @comp_id	AND
												rmad_id		= @l_rmad_id

									END


									-- --------------------------------------------------------------------
									-- #STL 24-05-2016
									-- GRABAMOS EL REGISTRO PARA EL HISTÓRICO DE ESTADOS, PRIORIDADES,
									-- GARANTÍAS Y TIPO DE MERCADERÍA
									-- --------------------------------------------------------------------
										SET		@rmadh_id	= 0
										EXEC	spRMA_Detail_AttributesHistory_InsertData
												@comp_id,	@l_rmah_id,		@l_rmad_id,
												@user_id,	@lsrpt_id,		@rmas_id,
												@rmap_id,	@rmaw_id,		@rmamt_id,
												@rmadh_id
									-- --------------------------------------------------------------------




									-----------------------------------------------------------------------------------------
									-----------------------------------------------------------------------------------------
									--#GA 20-04-2017
									-- ACTUALIZAMOS ESTADO EN EL DETALLE DE LA HOJA DE RUTA
									--------------------------------------------------------------------
									UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
										SET		sds_id				= @sds_id4Picking
										WHERE	comp_id				= @comp_id
										AND		bra_id				= @bra_id
										AND		rmad_id				= @l_rmad_id
										AND		dsd_isRMA4Picking	= 'True'

									UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
										SET		sds_id				= @sds_id4Delivery
										WHERE	comp_id				= @comp_id
										AND		bra_id				= @bra_id
										AND		rmad_id				= @l_rmad_id
										AND		dsd_isRMA4Picking	= 'False'

									IF @sds_id4Delivery = 0
										BEGIN
											UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
												SET
													dsd_status0_cd = GETDATE(),
													dsd_status0_user_id = @user_id
												WHERE	comp_id = @comp_id
												AND		bra_id  = @bra_id
												AND		rmad_id	= @l_rmad_id
										END

									IF @sds_id4Delivery = 1
										BEGIN
											UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
												SET
													dsd_status1_cd = GETDATE(),
													dsd_status1_user_id = @user_id
												WHERE	comp_id = @comp_id
												AND		bra_id  = @bra_id
												AND		rmad_id	= @l_rmad_id
										END

									IF @sds_id4Delivery = 2
										BEGIN
											UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
												SET
													dsd_status2_cd = GETDATE(),
													dsd_status2_user_id = @user_id
												WHERE	comp_id = @comp_id
												AND		bra_id  = @bra_id
												AND		rmad_id	= @l_rmad_id
										END

									IF @sds_id4Delivery = 3
										BEGIN
											UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
												SET
													dsd_status3_cd = GETDATE(),
													dsd_status3_user_id = @user_id
												WHERE	comp_id = @comp_id
												AND		bra_id  = @bra_id
												AND		rmad_id	= @l_rmad_id
										END

									IF @sds_id4Delivery = 4
										BEGIN
											UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
												SET
													dsd_status4_cd = GETDATE(),
													dsd_status4_user_id = @user_id
												WHERE	comp_id = @comp_id
												AND		bra_id  = @bra_id
												AND		rmad_id	= @l_rmad_id
										END

										IF @sds_id4Picking = 0
										BEGIN
											UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
												SET
													dsd_status0_cd = GETDATE(),
													dsd_status0_user_id = @user_id
												WHERE	comp_id = @comp_id
												AND		bra_id  = @bra_id
												AND		rmad_id	= @l_rmad_id
										END

									IF @sds_id4Picking = 11
										BEGIN
											UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
												SET
													dsd_status1_cd = GETDATE(),
													dsd_status1_user_id = @user_id
												WHERE	comp_id = @comp_id
												AND		bra_id  = @bra_id
												AND		rmad_id	= @l_rmad_id
										END

									IF @sds_id4Picking = 12
										BEGIN
											UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
												SET
													dsd_status2_cd = GETDATE(),
													dsd_status2_user_id = @user_id
												WHERE	comp_id = @comp_id
												AND		bra_id  = @bra_id
												AND		rmad_id	= @l_rmad_id
										END

									IF @sds_id4Picking = 13
										BEGIN
											UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
												SET
													dsd_status3_cd = GETDATE(),
													dsd_status3_user_id = @user_id
												WHERE	comp_id = @comp_id
												AND		bra_id  = @bra_id
												AND		rmad_id	= @l_rmad_id
										END

									IF @sds_id4Picking = 14
										BEGIN
											UPDATE tbDeliverySheetDetail		WITH (ROWLOCK)
												SET
													dsd_status4_cd = GETDATE(),
													dsd_status4_user_id = @user_id
												WHERE	comp_id = @comp_id
												AND		bra_id  = @bra_id
												AND		rmad_id	= @l_rmad_id
										END


									--IF @sds_id4Delivery = 5
									--	BEGIN
									--		UPDATE tbDeliverySheetDetail
									--			SET
									--				dsd_status5_cd = GETDATE(),
									--				dsd_status5_user_id = @user_id
									--			WHERE	comp_id = @comp_id
									--			AND		bra_id  = @bra_id
									--			AND		rmad_id	= @l_rmad_id
									--	END

								-----------------------------------------------------------------------------------------
								-----------------------------------------------------------------------------------------



								SET		@lrmad_id = @l_rmad_id

							END
						ELSE
							BEGIN

								--si no existe se elimina
								EXEC	dbo.spRMADetail_deleteData @comp_id,@l_rmad_id	-- MOS 05-2022, agregué comp_id, no se quien fue el DP q no lo puso !!!
							END
					END
				-- ========================================================================================================

				-- -----------------------------------------------------------------------
				-- Actualizacion de nuevo parametro en la TMP para no tocar el SP Anterior
				-- -----------------------------------------------------------------------
				UPDATE tbRMA_Detail		WITH (ROWLOCK)
					SET	rmad_IncludeInPotentialStock = @lrmad_IncludeInPotentialStock
					WHERE	comp_id = @comp_id		AND
							rmad_id = @lrmad_id

				UPDATE tbRMA_Detail		WITH (ROWLOCK)
					SET
					rmad_Date_Proc = @bra_processingDate
					WHERE	comp_id = @comp_id		AND
							rmad_id = @lrmad_id		AND
							rmad_Date_Proc IS NULL  AND
							srpt_id <> 1


				-- -----------------------------------------------------------------------



				DECLARE	@llrv			INT,
						@lseclog_id1	INT,
						@lseclog_id2	INT


				IF not @cust_id IS NULL
					BEGIN
						SET @lseclog_id1 = 1
						SET @lseclog_id2 = @cust_id
					END
				ELSE
					IF not @supp_id IS NULL
						BEGIN
							SET @lseclog_id1 = 2
							SET @lseclog_id2 = @supp_id
						END


				EXEC spSecurityLog_insertData
						@comp_id,
						@bra_id,
						@user_id,
						null,
						null,
						null,
						null,
						null,
						13,
						null,
						null,
						null,
						null,
						NULL,
						null, 			--prof_id
						null,
						null,
						@rmah_id,		--número de rma
						@lseclog_id2,	--número de cliente o proveedor
						@lsrpt_id,		--número de estado
						null,
						@return_value = @llrv









				-- ========================================================================================================
				-- Referencia: #4

				DECLARE @lstor_id_Stock				INT,
						@now						DATETIME,
						@lct_transaction_rv			INT,
						@lit_transaction_rv			INT


				-- obtener la fecha actual
				SET @now	= GETDATE()


				--es un nuevo artículo en el rma, tiene un artículo cargado y es rma proveedores y que sea
				--estado diferente de 1030-NC proveedores
				IF @lrmadt_isNewItem	= 'True'	AND NOT @litem_id	IS NULL		AND
					NOT @supp_id		IS NULL		AND @cust_id		IS NULL		AND
					@lsrpt_id			<> 1030
					BEGIN




						SELECT	@lstor_id_Stock	= @bra_RMA_storId4Bad


						-- actualizar el depósito del artículo del rma
						EXEC spItemStorage_insertData @comp_id, @litem_id, @lstor_id_Stock, 0


						-- genearación de comprobante
						EXEC dbo.spRMA_insertTransaction
								@comp_id,				@bra_id,				@cust_id,			@supp_id,
								@user_id,				@lstor_id_Stock,		@litem_id,			@lrmadt_qty,
								@lrmadt_originalPrice,	@customerCurrencyId,	@lrmadt_curr_id,	@BranchCurrencyId,
								@ct_CompanyCurrency,	@it_order,				@rmah_id,			@lrmad_id,
								@intSm_id,
								@intDisc_id,			@intDl_id,				@intSt_id,			@now,
								301,	-- MOS 08-2017
								@ct_transaction_rv = @lct_transaction_rv OUTPUT,
								@it_transaction_rv = @lit_transaction_rv OUTPUT


						-- se incorpora el artículo al depósito del detalle del rma
						UPDATE	tbItemStorage		WITH (ROWLOCK)
							SET		itst_cant	= itst_cant - @lrmadt_qty,
									itst_cd		= @now
							WHERE	comp_id		= @comp_id
							AND		stor_id		= @lstor_id_Stock
							AND		item_id		= @litem_id

					END
				-- ========================================================================================================



				-- -------------------------------------------------------
				-- MOS 26-01-2022 x Capacitacion y SecOne, que genere el pedido con la Sucursal de ORIGEN si es que está asi definido en la Sucursal, campo bra_RMA_useDFIdOfOriginalBranch
				-- -------------------------------------------------------
				DECLARE @intBranchID4SaleOrder AS INT		= @bra_id
				IF		@bra_RMA_useDFIdOfOriginalBranch	= 'True'
					BEGIN
						SET @intBranchID4SaleOrder			= @rmad_bra_id
					END
				-- -------------------------------------------------------




				-- ===========================================================================================================
				-- Selecciona cual es el df_id que debera usar.-
				DECLARE @df_id	INT
				SELECT  @df_id	=	CASE
										WHEN @lsrpt_id IN (10,30,35,50,80,90)	THEN @bra_RMA_dfId4Packing
										WHEN @lsrpt_id IN (20,40)				THEN @ldf_id4CreditNote
									END
				-- Si no hay df_id definido y es RMA CLIENTES
				IF	(@df_id IS NULL)		AND
					(@cust_id IS NOT NULL)	AND
					(@lsrpt_id IN (10,30,35,50,80,90,    20,40))
					BEGIN
						SET @return_value = 14
						RETURN
					END
				-- ===========================================================================================================



				-- ---------------------------------------------------------------------------------
				-- MOS 26-01-2022 x los FORROS de S1 para que les tome el PUTO remito de la PUTA sucursal de origen de la fc
				-- ---------------------------------------------------------------------------------
				IF @bra_RMA_useDFIdOfOriginalBranch = 'True'
					BEGIN
						IF @lsrpt_id IN (10,30,35,50,80,90)
							BEGIN
								SELECT Top 1 @df_id = df_id
									FROM dbo.fnDocumentsFile_GetDocumentsForPackingList(@comp_id,@intBranchID4SaleOrder /*@bra_id*/,@cust_id)
									ORDER BY df_order ASC
								IF @df_id IS NULL SET @df_id = @bra_RMA_dfId4Packing	-- x si no lo encuentra, pone el q esta x defecto definido.
							END
					END
				-- ---------------------------------------------------------------------------------





				IF @lrmadt_isNew = 'True'
					BEGIN


						-- Declaro variables
						DECLARE @ExchangeToCustomerCurrency		DECIMAL(19,6),
								@ExchangeToCompanyCurrency		DECIMAL(19,6),
								@lsoh_id						INT,
								@total							DECIMAL(19,6),
								@ssos_id						INT,
								@tax_id							INT,
								@neto							DECIMAL(18,2),
								@rv								INT




						-- recuperar la diferencia de cambio y la moneda en que realizó la cobranza
						SET @total	= 0



						-- ===========================================================================================================
						-- 16-09-2010 - NHP - Referencia: #1
						-- tipo de cambio a moneda del cliente
						SELECT @ExchangeToCustomerCurrency  = dbo.fnGetExchange(@comp_id, 1, @BranchCurrencyId, @customerCurrencyId , 0, 0, 'False')
						-- ===========================================================================================================







						-- ========================================================================================================
						-- Parte: 420 / Parte: 457
						-- ========================================================================================================
						SELECT	@ssos_id =	CASE
												WHEN @lsrpt_id = 10	THEN 201 -- funciona ok se devuelve la misma mercaderia
												WHEN @lsrpt_id = 20	THEN 201 -- funciona ok se efectúa NC
												WHEN @lsrpt_id = 30	THEN 201 -- funciona mal se devuelve al misma mercaderia
												WHEN @lsrpt_id = 35	THEN 200 -- funciona mal se cambia por igual mercadería		-- Ref: #2
												WHEN @lsrpt_id = 40	THEN 201 -- funciona mal se efectúa NC
												WHEN @lsrpt_id = 80	THEN 201 -- Reparacion, queda con Remito Listo para procesar
												WHEN @lsrpt_id = 90	THEN 201 -- Reparacion, queda con Remito Listo para procesar
												ELSE 200
			      	          				END
						-- ========================================================================================================




						-- ========================================================================================================
						-- Referencia: #3
						DECLARE @ldescription	VARCHAR(200)
						IF @litem_desc IS NULL OR LEN(RTRIM(LTRIM(@litem_desc))) = 0
							SET @ldescription = @lrmadt_Manual
						ELSE
							SET @ldescription = @litem_desc
						-- ========================================================================================================




						-- ========================================================================================================
						-- Para los estados 10,30,80 y 90 se pasan los items como manuales esto es el item_id = null
						DECLARE @litem_id_SO	INT
						SELECT  @litem_id_SO =	CASE
													WHEN @lsrpt_id IN (10,30,80,90) THEN NULL
													ELSE @litem_id
												END
						-- ========================================================================================================




						-- ========================================================================================================
						DECLARE @lstor_id_SO	INT
						SELECT  @lstor_id_SO =	CASE
													WHEN @lsrpt_id IN (40)			THEN @bra_RMA_storId4Bad
													WHEN @lsrpt_id IN (20,35,50)	THEN @lstor_id
													WHEN @lsrpt_id IN (10,30,80,90)	THEN NULL
												END
						-- ========================================================================================================






						-- ========================================================================================================
						-- 2010-08-23 - NHP - Parte S/P
						-- Se pasa la actualización de Pedidos a un sólo SPs
						--0010-Funciona OK - Se devuelve la misma mercadería
						--0020-Funciona OK - Se efectúa Nota de Crédito
						--0030-Funciona MAL- Se devuelve la misma mercadería
						--0035-Funciona MAL- Se cambia por igual mercadería
						--0040-Funciona MAL- Se efectúa Nota de Crédito
						--0050-Adelanto de Cambio
						--0080-Reparacion con Cargo, Se pudo Reparar
						--0090-Reparacion con Cargo, NO se pudo Reparar
						IF @lsrpt_id IN (10,20,30,35,40,50,80,90)
							BEGIN


								DECLARE @new_ProcNote	VARCHAR(MAX)
								SET @new_ProcNote = 'RMA: ' + CONVERT(VARCHAR,@rmah_id) + '-' + CONVERT(VARCHAR,@lrmad_id) + ' - ' + ltrim(rtrim(@lrmadt_ProcNote)) + ' '

								--STL SE PUSO EL CASE EN BASE A LA NECESIDAD DE QUE SI VIENE POR SRPT_ID = 35
								--GRABE EL ITEM_ID DE REEMPLAZO Y EL STOR_ID DE REEMPLAZO

								--ACA SETEAMOS EL ITEM Y EL STOR_ID QUE VA A UTILIZAR EL STORED PROCEDURE
								DECLARE
									@lINTItem_Id_SO	INT,
									@lINTStor_Id_SO	INT,
									@lVARCHARItem_Desc VARCHAR(200)


								IF @lsrpt_id = 35 AND @item_id4Replacement IS NOT NULL
									BEGIN
										SET @lINTItem_Id_SO = @item_id4Replacement
										SET @lINTStor_Id_SO = @stor_id4Replacement
										SELECT @lVARCHARItem_Desc = ti.item_desc
											FROM tbItem ti		WITH (NOLOCK)
											WHERE ti.item_id = @item_id4Replacement
									END
								ELSE
									BEGIN
										SET @lINTItem_Id_SO = @litem_id_SO
										SET @lINTStor_Id_SO = @lstor_id_SO
										SET @lVARCHARItem_Desc = @ldescription
									END




								EXEC spRMA_updateSaleOrder
									@comp_id,						@intBranchID4SaleOrder/*@bra_id*/,	@rmadt_guid,
									@cust_id,						@user_id,							@bra_processingDate,
									@prli_id,						@intSm_id,							@intDisc_id,
									@intDl_id,						@ExchangeToCustomerCurrency,		@intSt_id,
									@lsoh_id,						@total,								@ssos_id,
									@tax_id,						@neto,								@now,
									@lINTItem_Id_SO,				@lINTStor_Id_SO,					@lrmadt_originalPrice,
									@lrmadt_qty,					@lis_id,							@lsrpt_id,
									@new_ProcNote,
									@ldf_id4CreditNote,				@tis_id,
									@ltis_priority,					@lVARCHARItem_Desc,	-- Referencia: #3 STL ANTES ERA @lDESCRIPTION
									@customerCurrencyId,			@df_id,								@rmah_id,
									@lrmad_id,						@lrmadt_curr_id,					@intSaleOrderHeaderUpdated

							END
						-- ========================================================================================================





						-- ========================================================================================================
						--Funciona MAL - Se cambia por igual mercadería -35
						--Funciona MAL - R.M.A. -60
						--Funciona OK  - Se devuelve al Depósito -70
						IF (@lsrpt_id=35 OR @lsrpt_id=60 OR @lsrpt_id=70) AND NOT @litem_id IS NULL
							BEGIN


								SELECT	@lstor_id_Stock	=	CASE
																WHEN @lsrpt_id IN (35,60)	THEN @bra_RMA_storId4Bad
																WHEN @lsrpt_id IN (70)		THEN @bra_RMA_storId4OK
															END

								-- actualizar el depósito del artículo del rma
								EXEC spItemStorage_insertData @comp_id, @litem_id, @lstor_id_Stock, 0


								-- generación de comprobante
								EXEC dbo.spRMA_insertTransaction
										@comp_id,				@bra_id,				@cust_id,			@supp_id,
										@user_id,				@lstor_id_Stock,		@litem_id,			@lrmadt_qty,
										@lrmadt_originalPrice,	@customerCurrencyId,	@lrmadt_curr_id,	@BranchCurrencyId,
										@ct_CompanyCurrency,	@it_order,				@rmah_id,			@lrmad_id,
										@intSm_id,
										@intDisc_id,			@intDl_id,				@intSt_id,			@now,
										301,-- MOS 08-2017
										@ct_transaction_rv = @lct_transaction_rv OUTPUT,
										@it_transaction_rv = @lit_transaction_rv OUTPUT


								-- se incorpora el artículo al depósito del detalle del rma
								UPDATE	tbItemStorage	WITH (ROWLOCK)
									SET		itst_cant	= itst_cant + @lrmadt_qty,
											itst_cd		= @now
									WHERE	comp_id		= @comp_id
									AND		stor_id		= @lstor_id_Stock
									AND		item_id		= @litem_id

							END




						--Funciona MAL - R.M.A. -60
						--Funciona OK  - Se devuelve al Depósito -70
						IF (@lsrpt_id = 60 OR @lsrpt_id=70) AND NOT @lis_id IS NULL
							BEGIN


								DECLARE @lis_available	BIT
								SELECT	@lis_available	=	CASE
																WHEN @lsrpt_id = 60 THEN 'false'	--ponerlo como no disponible
																WHEN @lsrpt_id = 70 THEN 'true'		--ponerlo como disponible
															END

								-- actualizar número de serie
								UPDATE	tbItemSerials		WITH (ROWLOCK)
									SET		is_available	= @lis_available
									WHERE	comp_id			= @comp_id
									AND		is_id			= @lis_id
									AND		is_serial		<> ''
									AND		NOT is_serial	IS NULL

							END
						-- ========================================================================================================



						-- ----------------------------------------------------------
						-- MOS: 12-2019: Si se hace NC por OK, pone el nro de serie en el deposito
						-- para el que se hará el pedido de NC.
						-- ----------------------------------------------------------
						IF (@lsrpt_id = 20) AND NOT @lis_id IS NULL
							BEGIN

								-- actualizar Deposito del número de serie al mismo que se usa en el PEDIDO generado de NC
								UPDATE	tbItemSerials	WITH (ROWLOCK)
									SET stor_id = @lstor_id_SO
									WHERE	comp_id			= @comp_id
									AND		is_id			= @lis_id
									AND		is_serial		<> ''
									AND		NOT is_serial	IS NULL

							END
						-- ----------------------------------------------------------


						-- ========================================================================================================
						-- TN : 350
						-- Funciona MAL -Se transfiere del depósito 1 al 10 -110
						IF @lsrpt_id=110 AND NOT @litem_id IS NULL
						BEGIN

							DECLARE @decOriginalQty AS DECIMAL(19,4)
							SET @decOriginalQty = @lrmadt_qty
							SET @lrmadt_qty = @lrmadt_qty * -1

							-- actualizar el depósito 4Bad del artículo
							EXEC spItemStorage_insertData @comp_id, @litem_id, @lstor_id, 0


							-- generación de comprobante
							EXEC dbo.spRMA_insertTransaction
									@comp_id,				@bra_id,				@cust_id,			@supp_id,
									@user_id,				@lstor_id,				@litem_id, 			@lrmadt_qty,
									@lrmadt_originalPrice,	@customerCurrencyId,	@lrmadt_curr_id,	@BranchCurrencyId,
									@ct_CompanyCurrency,	@it_order,				@rmah_id,			@lrmad_id,
									@intSm_id,
									@intDisc_id,			@intDl_id,				@intSt_id,			@now,
									301, -- MOS 08-2017
									@ct_transaction_rv = @lct_transaction_rv OUTPUT,
									@it_transaction_rv = @lit_transaction_rv OUTPUT


							-- quita la cantidad del artículo seleccionado del depósito original
							UPDATE	tbItemStorage	WITH (ROWLOCK)
								SET		itst_cant	= itst_cant - @decOriginalQty ,--@lrmadt_qty,
										itst_cd		= @now
								WHERE	comp_id		= @comp_id
								AND		stor_id		= @lstor_id
								AND		item_id		= @litem_id




							SET @lrmadt_qty = @lrmadt_qty * -1

							-- actualizar el depósito 4Bad del artículo
							EXEC spItemStorage_insertData @comp_id, @litem_id, @bra_RMA_storId4Bad, 0


							-- generación de comprobante
							EXEC dbo.spRMA_insertTransaction
									@comp_id,				@bra_id,				@cust_id,			@supp_id,
									@user_id, 				@bra_RMA_storId4Bad,	@litem_id,			@lrmadt_qty,
									@lrmadt_originalPrice,	@customerCurrencyId,	@lrmadt_curr_id,	@BranchCurrencyId,
									@ct_CompanyCurrency,	@it_order,				@rmah_id,			@lrmad_id,
									@intSm_id,
									@intDisc_id,			@intDl_id,				@intSt_id,			@now,
									301, -- MOS 08-2017
									@ct_transaction_rv = @lct_transaction_rv OUTPUT,
									@it_transaction_rv = @lit_transaction_rv OUTPUT


							-- se incorpora la cantidad del artículo seleccionado al depósito 4Bad
							UPDATE	tbItemStorage	WITH (ROWLOCK)
								SET		itst_cant	= itst_cant + @decOriginalQty,--@lrmadt_qty,
										itst_cd		= @now
								WHERE	comp_id		= @comp_id
								AND		stor_id		= @bra_RMA_storId4Bad
								AND		item_id		= @litem_id

						END
						-- ========================================================================================================


						-- ========================================================================================================
						-- NOTA DE CREDITO - 1030 #8
						-- ========================================================================================================
						--==STL
						--COPIA EL IT_TRANSACTION ORIGINAL Y LO INSERTA EN LA ITEM_TRANSACTIONS CAMBIANDO EL SIGNO DE LA CANTIDAD
						--PARA PERMITIR LA ANULACIÓN DEL MISMO CON UNA ESPECIE DE CONTRAMOVIMIENTO

						IF (@lsrpt_id=1030 ) AND @litem_id IS NOT NULL
							BEGIN


								--VARIABLES LOCALES DE TRABAJO
								DECLARE
									@lIntStor_Id		INT,	--DEPOSITO EN EL QUE VA A ACTUALIZAR EL STOCK
									@lIntStore_Previous	INT,	--CANTIDAD ANTES DE DESCONTAR EL STOCK
									@lIntIt_Transaction	INT,	--IT_TRANSACTION DEL CLONADO DEL IT_TRANSACTION ORIGINAL
									@lIntRMADQty		INT		--QTY DEL ITEM EN LA RMA DETAIL


								--GRABAMOS EL STOR_ID DEL RMADETAIL y LA CANTIDAD
								SELECT
									@lIntStor_Id	= trdt.stor_id,
									@lIntRMADQty	= trdt.rmadt_qty
									FROM tbRMA_Detail_Tmp					trdt	WITH (NOLOCK)
									WHERE trdt.rmadt_id = @lrmadt_id


								-- ----------------------------------------------------
								-- Verifica de que manera va a trabajar
								-- ----------------------------------------------------
								DECLARE @bolSupplierCreditNotePostRMA AS BIT
								IF 	EXISTS(
											SELECT TOP 1  1
												FROM tbBranch tb	WITH (NOLOCK)
												WHERE	tb.comp_id								= @comp_id	AND
														tb.bra_id								= @bra_id	AND
														tb.bra_RMA_SupplierCreditNotePostRMA	= 'true'
										  )
									BEGIN
										SET @bolSupplierCreditNotePostRMA = 'True'
									END
								ELSE
									BEGIN
										SET @bolSupplierCreditNotePostRMA = 'False'
									END
								-- ----------------------------------------------------





								IF @bolSupplierCreditNotePostRMA = 'False'
									BEGIN


										--RECUPERAMOS EL STORE PREVIOUS DEL IT_TRANSACTION ORIGINAL
										SET @lIntStore_Previous = 0
										SELECT
											@lIntStore_Previous = tis.itst_cant
										FROM tbItemStorage					tis		WITH (NOLOCK)
										WHERE	tis.comp_id = @comp_id		AND
												tis.stor_id	= @lIntStor_Id	AND
												tis.item_id = @litem_id

										INSERT INTO tbItemTransactions
										(
											comp_id,
											bra_id,
											ct_transaction,
											-- it_transaction -- this column value is auto-generated,
											item_id,
											it_qty,
											it_priceWithOutOthers,
											it_price,
											curr_id,
											it_exchangeToBranchCurrency,
											it_priceOfCost,
											it_priceOfCostPP,
											it_priceOfCostLastPurchase,
											it_priceBOfCost,
											it_priceBOfCostPP,
											it_priceBOfCostLastPurchase,
											it_OriginalPrice,
											it_OriginalPriceCurrency,
											it_exchangeToOriginalPriceCurrency,
											stor_id,
											it_storePrevious,
											prli_id,
											byor_id,
											it_isProduction,
											it_isAssociation,
											it_isAssociationGroup,
											it_cd,
											it_packingInvoicePend,
											it_order,
											so_id,
											it_guarantee,
											it_itemDiscountTotal,
											it_totalDiscountTotal,
											it_CreditInt,
											it_CreditIntPlus,
											puco_id,
											it_poh_bra_id,
											it_poh_id,
											it_soh_id,
											it_sod_id,
											rmah_id,
											rmad_id,
											it_qty_rma,
											it_tis_id_aux,
											it_note1,
											it_note2,
											it_packingInvoiceSelected,
											it_cancelled,
											it_priceB,
											it_isMade,
											it_item_id_origin,
											tmp_tis_id,
											it_packingInvoicePendOriginal,
											it_packingInvoiceSelectedGuid,
											it_transaction_original,
											it_transaction_NoStockDiscount,
											it_SalesCurrId4exchangeToBranchCurrency,
											it_AllUseTag1,
											it_AllUseTag2,
											it_AllUseTag3,
											it_AllUseTag4,
											it_Discount1,
											it_Discount2,
											it_Discount3,
											it_Discount4,
											coslis_id,
											coslis_idB,
											supp_id,
											camp_id,
											it_transaction_originalEW,
											it_IsInternalTransfer,
											it_isRMASupplierCreditNote
										)
										SELECT
											tit.comp_id,
											tit.bra_id,
											tit.ct_transaction,
											--tit.it_transaction,
											tit.item_id,
											- tit.it_qty,
											tit.it_priceWithOutOthers,
											tit.it_price,
											tit.curr_id,
											tit.it_exchangeToBranchCurrency,
											tit.it_priceOfCost,
											tit.it_priceOfCostPP,
											tit.it_priceOfCostLastPurchase,
											tit.it_priceBOfCost,
											tit.it_priceBOfCostPP,
											tit.it_priceBOfCostLastPurchase,
											tit.it_OriginalPrice,
											tit.it_OriginalPriceCurrency,
											tit.it_exchangeToOriginalPriceCurrency,
											tit.stor_id,
											@lIntStore_Previous,--tit.it_storePrevious,
											tit.prli_id,
											tit.byor_id,
											tit.it_isProduction,
											tit.it_isAssociation,
											tit.it_isAssociationGroup,
											GETDATE(),                  --tit.it_cd,
											tit.it_packingInvoicePend,
											tit.it_order,
											tit.so_id,
											tit.it_guarantee,
											tit.it_itemDiscountTotal,
											tit.it_totalDiscountTotal,
											tit.it_CreditInt,
											tit.it_CreditIntPlus,
											tit.puco_id,
											tit.it_poh_bra_id,
											tit.it_poh_id,
											tit.it_soh_id,
											tit.it_sod_id,
											tit.rmah_id,
											tit.rmad_id,
											tit.it_qty_rma,
											tit.it_tis_id_aux,
											tit.it_note1,
											tit.it_note2,
											tit.it_packingInvoiceSelected,
											tit.it_cancelled,
											tit.it_priceB,
											tit.it_isMade,
											tit.it_item_id_origin,
											tit.tmp_tis_id,
											tit.it_packingInvoicePendOriginal,
											tit.it_packingInvoiceSelectedGuid,
											tit.it_transaction_original,
											tit.it_transaction_NoStockDiscount,
											tit.it_SalesCurrId4exchangeToBranchCurrency,
											tit.it_AllUseTag1,
											tit.it_AllUseTag2,
											tit.it_AllUseTag3,
											tit.it_AllUseTag4,
											tit.it_Discount1,
											tit.it_Discount2,
											tit.it_Discount3,
											tit.it_Discount4,
											tit.coslis_id,
											tit.coslis_idB,
											tit.supp_id,
											tit.camp_id,
											tit.it_transaction_originalEW,
											tit.it_IsInternalTransfer,
											tit.it_isRMASupplierCreditNote

										FROM tbItemTransactions tit	WITH (NOLOCK)
										WHERE	tit.comp_id			= @comp_id				AND
												tit.it_transaction	= @intIt_TransactionCN

										--RECUPERAMOS EL IT_TRANSACTION GRABADO EN BASE AL IT_TRANSACTION ORIGINAL (ESTE ES EL REGISTRO CLONADO CON LA QTY EN NEGATIVO)
										SET @lIntIt_Transaction = @@IDENTITY


										-- actualizar el depósito del artículo del rma /ATENCION NO ES DEFINITIVO NO GRABAR NO SE CUAL STOR_ID ES EL CORRECTO PREGUNTAR A MOS
										UPDATE tbItemStorage	WITH (ROWLOCK)
											SET
												itst_cant = itst_cant + @lIntRMADQty
											WHERE	comp_id = @comp_id		AND
													stor_id = @lIntStor_Id	AND
													item_id = @litem_id


									END

								ELSE

									BEGIN

										-- Grabado de NC de la manera nueva, o sea, se graba aqui una salida del deposito de NC de proveedor
										-- y se reingresara en el momento de cargar la nota de credito recuperando los items por el boton de RMA.!

										SELECT @lIntStor_Id = tb.bra_RMA_stor_id4SupplierCreditNote
											FROM tbBranch tb		WITH (NOLOCK)
											WHERE	tb.comp_id								= @comp_id	AND
													tb.bra_id								= @bra_id

										-- actualizar el depósito del artículo del rma
										EXEC spItemStorage_insertData @comp_id, @litem_id, @lIntStor_Id, 0


										-- genearación de comprobante
										EXEC dbo.spRMA_insertTransaction
												@comp_id,				@bra_id,				@cust_id,			@supp_id,
												@user_id,				@lIntStor_Id,			@litem_id,			@lIntRMADQty,
												@lrmadt_originalPrice,	@customerCurrencyId,	@lrmadt_curr_id,	@BranchCurrencyId,
												@ct_CompanyCurrency,	@it_order,				@rmah_id,			@lrmad_id,
												@intSm_id,
												@intDisc_id,			@intDl_id,				@intSt_id,			@now,
												301, -- MOS 08-2017
												@ct_transaction_rv = @lct_transaction_rv OUTPUT,
												@it_transaction_rv = @lit_transaction_rv OUTPUT


										-- se incorpora el artículo al depósito del detalle del rma
										UPDATE	tbItemStorage	WITH (ROWLOCK)
											SET		itst_cant	= itst_cant + @lIntRMADQty,
													itst_cd		= @now
											WHERE	comp_id		= @comp_id
											AND		stor_id		= @lIntStor_Id
											AND		item_id		= @litem_id


										INSERT INTO tbRMA_SupplierCreditNotePending
										(
											comp_id,
											-- rmanc_id -- this column value is auto-generated,
											rmah_id,
											rmad_id,
											supp_id,
											item_id,
											rmanc_price,
											rmanc_qty,
											rmanc_isProcessed,
											ct_transaction,
											curr_id,
											stor_id
										)
										VALUES
										(
											@comp_id,
											@rmah_id,
											ISNULL(@l_rmad_id,@lrmad_id), --CAMBIAR ESTO POR EL RMAD_ID
											@supp_id,
											@litem_id,
											@lrmadt_originalPrice,
											@lIntRMADQty,
											'False',
											NULL,
											@lrmadt_curr_id,
											@lIntStor_Id
										)



									END

						END --1030

						-- ========================================================================================================



						-- ========================================================================================================
						-- Funciona OK, se incorpora al Deposito -1010 // Cambio por Nueva Mercaderia (Mismo Artículo) -1040
						IF (@lsrpt_id=1010 OR @lsrpt_id=1020 OR @lsrpt_id=1040) AND  @litem_id IS NOT NULL
							BEGIN


								SELECT	@lstor_id_Stock	=	CASE
																WHEN @lsrpt_id IN (1020)		THEN @bra_RMA_storId4Scrap
																WHEN @lsrpt_id IN (1010,1040)	THEN @bra_RMA_storId4OK
															END


								-- actualizar el depósito del artículo del rma
								EXEC spItemStorage_insertData @comp_id, @litem_id, @lstor_id_Stock, 0

								-- POngo en que deposito fue a parar el nro de serie.  MOS  01-2020 x DS
								IF @lis_id IS NOT NULL AND (@lsrpt_id=1010 OR @lsrpt_id=1020)
									BEGIN
										UPDATE tbItemSerials	WITH (ROWLOCK)
											SET   stor_id   = @lstor_id_Stock
											WHERE comp_id   = @comp_id AND
												  is_id		= @lis_id
									END


								-- genearación de comprobante
								EXEC dbo.spRMA_insertTransaction
										@comp_id,				@bra_id,				@cust_id,			@supp_id,
										@user_id,				@lstor_id_Stock,		@litem_id,			@lrmadt_qty,
										@lrmadt_originalPrice,	@customerCurrencyId,	@lrmadt_curr_id,	@BranchCurrencyId,
										@ct_CompanyCurrency,	@it_order,				@rmah_id,			@lrmad_id,
										@intSm_id,
										@intDisc_id,			@intDl_id,				@intSt_id,			@now,
										301, -- MOS 08-2017
										@ct_transaction_rv = @lct_transaction_rv OUTPUT,
										@it_transaction_rv = @lit_transaction_rv OUTPUT


								-- se incorpora el artículo al depósito del detalle del rma
								UPDATE	tbItemStorage	WITH (ROWLOCK)
									SET		itst_cant	= itst_cant + @lrmadt_qty,
											itst_cd		= @now
									WHERE	comp_id		= @comp_id
									AND		stor_id		= @lstor_id_Stock
									AND		item_id		= @litem_id

							END --1010 1020 1040
						-- ========================================================================================================





						-- ========================================================================================================
						-- Funciona OK, se incorpora al Deposito -1010
						IF @lsrpt_id = 1010 AND NOT @lis_id IS NULL
							BEGIN

								UPDATE	tbItemSerials	WITH (ROWLOCK)
									SET		is_available	= 'true',
											stor_id			= @lstor_id_Stock  -- MOS 25-09-2019 x los forros de DS
									WHERE	comp_id		= @comp_id
									AND		is_id		= @lis_id

								UPDATE	tbImportData		WITH (ROWLOCK)
									SET		impData_ActualQty = impData_ActualQty + 1
									FROM	tbImportData				tid
											INNER JOIN tbItemSerials	tis
											ON	tis.comp_id			= tid.comp_id
											AND tis.ct_transaction	= tid.ct_transaction
											AND tis.it_transaction	= tid.it_transaction
											AND tis.is_id			= @lis_id
									WHERE	tid.comp_id		= @comp_id


							END --1010
						-- ========================================================================================================





						-- ========================================================================================================
						--Cambio por Nueva Mercaderia (Mismo Artículo) -1040 --Generó registros de tbItemSerial en blanco
						IF @lsrpt_id = 1040 AND NOT @litem_id IS NULL
							BEGIN


								EXEC spItemSerials_insertQtyData
									@comp_id,				@bra_id,
									@lct_transaction_rv,	@lit_transaction_rv,
									@litem_id,				@bra_RMA_storId4OK,
									@lrmadt_qty

								DECLARE @impData_ExpirationDate AS DATETIME
								SET		@impData_ExpirationDate = GETDATE()

								EXEC spImportData_insertData
										@comp_id,
										@litem_id,
										@lrmadt_qty,
										@lrmadt_qty,
										@lct_transaction_rv,
										@lit_transaction_rv,
										@bra_id,
										@limpData_Custom_local,
										@limpData_Number_local,
										NULL,
										NULL,
										@impData_ExpirationDate,
										''


							END --1040
						-- ========================================================================================================

					END --End del campo rmadt_IsNew



				-- ========================================================================================================
				-- Si tiene Articulos Asociados genera pedido para hacer
				-- una FACTURA de esos Items o se cancela por REPARACION con CARGO 80 / 90
				-- ========================================================================================================
				IF	(	EXISTS (
								SELECT TOP 1  1
									FROM tbRMA_Detail_AddItems trdai	   WITH (NOLOCK)
										WHERE trdai.rmad_id = @l_rmad_id
								)
						AND
					   (@lsrpt_id = 80 OR @lsrpt_id = 90)
					)
						OR  -- Redundante  pero para que se entienda  01-2016
					(@lsrpt_id = 80 OR @lsrpt_id = 90)

				BEGIN


					SELECT @curPrli_Id = tb.bra_RMA_prli_id4AdditionalItems
						FROM tbBranch tb   WITH (NOLOCK)
						WHERE	tb.comp_id = @comp_id AND
								tb.bra_id  = @bra_id
					IF @curPrli_Id IS NULL
						BEGIN -- Si no hay lista designada toma la del cliente.-
							SELECT @curPrli_Id = tc.prli_id
								FROM tbCustomer tc   WITH (NOLOCK)
								WHERE	tc.comp_id = @comp_id AND
										tc.cust_id = @cust_id
						END



					-- Precios de la Reparacion.-
					SELECT @decFixPrice			= trdt.rmafp_Price,
						   @intFixPriceCurrency = trdt.rmafp_curr_id,
						   @strFixPriceDesc		= trfp.rmafp_desc,
						   @intFixPriceTaxId	= trfp.tax_id
						FROM tbRMA_Detail_Tmp trdt			WITH (NOLOCK)
						INNER JOIN tbRMA_FixPrices trfp		WITH (NOLOCK)
							ON	trfp.comp_id  = @comp_id AND
								trfp.rmafp_id = trdt.rmafp_id
						WHERE	trdt.comp_id  = @comp_id		AND
								trdt.rmad_id  = @l_rmad_id	AND
								trdt.rmah_id  = @l_rmah_id








					-- Busca el primer documento del tipo FACTURA
					SET @intDf_Id4AddItems	= NULL
					IF  @rmafp_SOInPL		= 'True'	-- Si genera REMITO en lugar de FACTURA . . .    MOS 01-2021, algun IDIOTA pidio que se genere Remito SIEMPRE en lugar de factura...
						BEGIN
							SELECT Top 1 @intDf_Id4AddItems = df_id
								FROM dbo.fnDocumentsFile_GetDocumentsForPackingList(@comp_id,@intBranchID4SaleOrder /*@bra_id*/,@cust_id)
								ORDER BY df_order ASC
						END
					ELSE
						BEGIN
							SELECT Top 1 @intDf_Id4AddItems = df_id
								FROM dbo.fnDocumentsFile_GetDocumentsForInvoices(@comp_id,@intBranchID4SaleOrder/*@bra_id*/,@cust_id)
								ORDER BY df_order ASC
						END

					IF @intDf_Id4AddItems IS NULL
					BEGIN
						SET @return_value = 15
						RETURN
					END


					-- --------------------------------------------------------------
					-- Si tiene algun cargo de reparacion, se agrega al pedido ahora.
					-- --------------------------------------------------------------
					IF	((@lsrpt_id = 80) OR (@lsrpt_id = 90))	AND
						@decFixPrice IS NOT NULL				AND
						@intFixPriceCurrency IS NOT NULL		AND
						@strFixPriceDesc IS NOT NULL			AND
						@decFixPrice <> 0						AND
						@lrmadt_isNew = 'True'							-- MOS 06-2023: si procesabas de a uno volvia a cargar en cada proceso ... **ergln239857asfdkjn
						BEGIN
							EXEC spRMA_updateSaleOrder
												@comp_id,						@intBranchID4SaleOrder/*@bra_id*/,	@rmadt_guid,
												@cust_id,						@user_id,							@bra_processingDate,
												@curPrli_Id,					@intSm_id,							@intDisc_id,
												@intDl_id,						@ExchangeToCustomerCurrency,		@intSt_id,
												@lsoh_id,						0,								    201/*RMA OK para Facturar*/,
												@intFixPriceTaxId,				0,								    @now,
												NULL,							NULL,					 			@decFixPrice,
												1 /*QTY*/,						@curIs_ID,							@lsrpt_id,
												@new_ProcNote,
												@intDf_Id4AddItems ,			@tis_id,
												@ltis_priority,					@strFixPriceDesc,	-- Referencia: #3
												@customerCurrencyId,			@intDf_Id4AddItems,								@rmah_id,
												@lrmad_id,						@intFixPriceCurrency,					@intSaleOrderHeaderUpdated output

							-- Saca cual fue el ultimo soh_id para esa sucursal que se inserto asi pone los nuevos items solo en ese SOH_id
							SET @lsoh_id = @intSaleOrderHeaderUpdated


						END
					-- --------------------------------------------------------------

					-- *88885
					-- Añade los Items Adicionales a la reparacion.!
					DECLARE  curAdditionalItems CURSOR LOCAL FAST_FORWARD FOR
									SELECT	trdai.item_id,
											trdai.stor_id,
											trdai.rmaa_qty,
											vitooit.tax_id,
											trdai.is_id,
											trdai.rmaa_id
										FROM tbRMA_Detail_AddItems trdai						WITH (NOLOCK)
										INNER JOIN tbRMA_Detail_Tmp AS trd						WITH (NOLOCK)	-- MOS 06-2023: si procesabas de a uno volvia a cargar en cada proceso ...**ergln239857asfdkjn
											ON	trd.rmah_id = trdai.rmah_id AND
												trd.rmad_id = trdai.rmad_id AND
												trd.comp_id = trdai.comp_id
										LEFT JOIN vwItemTaxesOnlyOneIvaTax vitooit			    WITH (NOLOCK)
											ON	vitooit.comp_id		= trdai.comp_id AND
												vitooit.item_id		= trdai.item_id
										WHERE	trdai.comp_id		= @comp_id		AND
												trdai.rmah_id		= @l_rmah_id	AND
												trdai.rmad_id		= @l_rmad_id	AND
												trdai.isSOGenerated = 'False'		AND
												trd.rmadt_isNew		= 'True'									-- MOS 06-2023: si procesabas de a uno volvia a cargar en cada proceso ...**ergln239857asfdkjn
									ORDER BY	trdai.rmaa_order,
												trdai.rmaa_id

					OPEN curAdditionalItems
					FETCH NEXT FROM	 curAdditionalItems INTO	@curItem_id,
																@curStor_id,
																@curRma_qty,
																@curTaxId,
																@curIs_ID,
																@curIdofItemAdd
					WHILE @@FETCH_STATUS = 0
						BEGIN


							-- Busca el precio de ese item
							SET @curItemPrice			= NULL
							SELECT	@curItemPrice		= tpli.prli_price,
									@curItemCurrency	= tpli.curr_id
								FROM tbPriceListItems tpli			WITH (NOLOCK)
								WHERE	tpli.comp_id = @comp_id		AND
										tpli.prli_id = @curPrli_Id	AND
										tpli.item_id = @curItem_id

							-- Si alguno de estos datos esta mal cancela
							IF	@curItemPrice IS NULL	OR
								@curItemPrice = 0		OR
								@curStor_id IS NULL		OR
								@intDf_Id4AddItems IS NULL
								BEGIN
									-- fuerza un error
									IF      @curItemPrice      IS NULL					SET @return_value = 10
									ELSE IF @curStor_id        IS NULL					SET @return_value = 11
									ELSE IF @intDf_Id4AddItems IS NULL					SET @return_value = 12
									ELSE IF @curItemPrice      = 0   					SET @return_value = 13
									-- Solo Mas ARRIBA, aca esta para saber que el 14 esta tomado !
									-- ELSE IF @df_id IS NULL	AND @cust_id IS NOT NULL	SET @return_value = 14

									RETURN
								END


							SET @new_ProcNote = 'RMA:' + CONVERT(VARCHAR,@rmah_id) + '-' + CONVERT(VARCHAR,@lrmad_id) + ' - ' + ltrim(rtrim(@lrmadt_ProcNote)) + ' '

							IF @curItemCurrency IS NULL SET @curItemCurrency = @lrmadt_curr_id

							DECLARE @strItemDescription AS NVARCHAR(250)
							SELECT  @strItemDescription = ti.item_desc
								FROM tbItem ti WITH (NOLOCK)
								WHERE	ti.comp_id = @comp_id AND
										ti.item_id = @curItem_id


							EXEC spRMA_updateSaleOrder
								@comp_id,						@intBranchID4SaleOrder/*@bra_id*/,	@rmadt_guid,
								@cust_id,						@user_id,							@bra_processingDate,
								@curPrli_Id,					@intSm_id,							@intDisc_id,
								@intDl_id,						@ExchangeToCustomerCurrency,		@intSt_id,
								@lsoh_id,						0,								    201/*RMA OK para Facturar*/,
								@curTaxId,						0,								    @now,
								@curItem_id,					@curStor_id,					 	@curItemPrice,
						 		@curRma_qty  ,					@curIs_ID,							@lsrpt_id,
								@new_ProcNote,
								@intDf_Id4AddItems ,			@tis_id,
								@ltis_priority,					@strItemDescription /*@ldescription*/,	-- Referencia: #3
								@customerCurrencyId,			@intDf_Id4AddItems,
								@rmah_id,						@lrmad_id,
								@curItemCurrency /* MOS @lrmadt_curr_id*/,				@intSaleOrderHeaderUpdated OUTPUT

							SET @lsoh_id = @intSaleOrderHeaderUpdated -- los items adicionales que si o si se pongan en el mismo pedido


							-- POne como Ya Emitido para que no lo vuelva a generar si se guarda el rma nuevamente!
							UPDATE tbRMA_Detail_AddItems	WITH (ROWLOCK)
								SET	isSOGenerated = 1
								WHERE	comp_id = @comp_id AND
										rmaa_id = @curIdofItemAdd

							FETCH NEXT FROM	 curAdditionalItems INTO	@curItem_id,
																		@curStor_id,
																		@curRma_qty,
																		@curTaxId,
																		@curIs_ID,
																		@curIdofItemAdd

						END
						CLOSE		curAdditionalItems
						DEALLOCATE	curAdditionalItems


						SET @lsoh_id = NULL -- Debe liberarlo ya que aca no debe forzar mas el numero de pedido

						-- -------------------------------------------------
						-- que no los tome en cuenta para stock disponible
						-- -------------------------------------------------
						UPDATE tbRMA_Detail_AddItems
							SET	is4AbailableStock = 0
							WHERE	comp_id = @comp_id	AND
									rmah_id = @l_rmah_id	AND
									rmad_id = @l_rmad_id


						--DELETE FROM tbRMA_Detail_AddItems
						--	FROM tbRMA_Detail_AddItems	trdai
						--	WHERE	trdai.comp_id = @comp_id	AND
						--					trdai.rmah_id = @l_rmah_id	AND
						--					trdai.rmad_id = @l_rmad_id
						-- -------------------------------------------------


				END
				-- ========================================================================================================


				-- x las dudas ya que algun forro puede cancelar x algo q no sea 80 o 90 y dejar comprometiendo stock al pedo
				IF @lsrpt_id > 1
					BEGIN
						UPDATE tbRMA_Detail_AddItems			WITH (ROWLOCK)
							SET	is4AbailableStock = 0
							WHERE	comp_id = @comp_id	AND
									rmah_id = @l_rmah_id	AND
									rmad_id = @l_rmad_id
					END




				-- por cada registro del cursor se realiza el delete del registro de la tabla RMA detalle temporal
				EXEC    dbo.spRMADetailTmp_deleteData		@lrmadt_id



				-- próxima lectura del cursor
				FETCH 	cursor_RMA_iD_items
				INTO 	@lrmadt_id,
						@lit_transaction,
						@litem_id,
						@lstor_id,
						@lrmadt_Manual,
						@lrmadt_originalPrice,
						@lrmadt_curr_id,
						@lrmadt_qty,
						@luser_id_Reception,
						@lrmadt_Date_Reception,
						@lrmadt_ReceptionNote,
						@lis_id,
						@luser_id_Diagnostic,
						@lrmadt_Date_Diagnostic,
						@lrmadt_DiagnosticNote,
						@lsrpt_id,
						@lrmadt_ProcNote,
						@ldf_id4CreditNote,
						@tis_id,
						@lrmadt_isNew,
						@ltis_priority,
						@litem_desc,
						@lrmadt_isNewItem,
						@l_rmah_id,
						@l_rmad_id,
						@lsupp_id,
						@limpData_Custom_local,
						@limpData_Number_local,
						@lrmad_IncludeInPotentialStock,
						--STL PUNTO 22 NUCLEO
						@rmas_id,
						@rmap_id,
						@item_id4Replacement,
						@rmaw_id,
						@rmamt_id,
						@user_id_Proc,
						@user_id_Delivery,
						@intIt_TransactionCN,
						@rmafailP_id,
						@rmadt_serial,
						@stor_id4Replacement,
						@RMA_Up2Price,
						@case_id,
						@rmad_relatedID,
						@it_transaction_Origin,
						@rmad_insertWarrantyDetail,
						@rmad_insertWarrantyCertificates,
						@rmad_bra_id,
						@rmad_isAvailable4DeliverySheet,
						@sds_id4Delivery,
						@sds_id4Picking,
						@dl_id4Picking,
						@dl_id4Delivery,
						@rmad_deliveryDate4Picking,
						@rmad_deliveryDate4Delivery,
						@rmad_Date_estimatedFinalization,
						@rmad_handOverDate,
						@rmad_handOver_user_id


			END


		CLOSE cursor_RMA_iD_items
		DEALLOCATE cursor_RMA_iD_items


		DELETE FROM tbTempItemStock			WITH (ROWLOCK)
			WHERE tis_guid = @rmadt_guid

		-- Libera isEditing... cosa de Hijo de mil ptas, arreglar esta mierda !!!!
		UPDATE tbRMA_Header			WITH (ROWLOCK)
			SET
				rmah_isEditing = 'false'
			WHERE comp_id = @comp_id AND (cust_id = @cust_id OR supp_id = @supp_id)

END
GO






CREATE  PROCEDURE [dbo].[spRMA_updateData]
(
	@comp_id					INT,
	@bra_id						INT,
	@rmah_id					INT,
	@rmadt_guid					UNIQUEIDENTIFIER,
	@cust_id					INT,
	@supp_id					INT,
	@rmah_cd					DATETIME,
	@user_id					INT,
	@rmah_isInSuppplier			BIT,
	@rmah_note1					NVARCHAR(2000),
	@rmah_note2					NVARCHAR(2000),

	@return_value				DECIMAL(19,2)	OUTPUT,
	@ret_ErrorCode				INT 			OUTPUT,
	@strReturnDescription		NVARCHAR(1000)	OUTPUT



)
AS

BEGIN


	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-06
	-- Parte		: 448
	-- Description	: Para cumplir el requerimiento solicitado, se actualiza el campo soh_isediting al valor 'False',
	--				  luego de la actualización de tbSaleOrderSerials, porque el spSaleOrderSerials_insertData lo pone
	--				  por defecto en 'True'
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-06
	-- Parte		: 457
	-- Description	: Se actualiza el ssos_id a 201 cuando el srpt_id = 35
	--				  se actualizó que el ssos_id para que quede exactamente igual al spRMA_insertData
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-09-16
	-- Parte		: S/P Referencia: #1
	-- Description	: Se cambia el orden de las monedas para la obtención del @ExchangeToCustomerCurrency
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-10-18
	-- Parte		: S/P Referencia: #2
	-- Description	: Se cambia lo realizado por el parte 457 y se actualiza el ssos_id a 200 cuando el srpt_id es 35
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-06-23
	-- TN			: Referencia: #3
	-- Description	: Por el cambio de funcionalidad de no eliminación de la tbRMA_detail cuando se actualiza desde
	--				  la tbRMA_Detail_Tmp, sino que actualiza los registros existentes, se cargan los rmah_id y
	--				  rmad_id de la tbRMA_detail en la tbRMA_Detail_Tmp
	-- =================================================================================================================




-- -----------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------
	/*
	DECLARE 	@comp_id					int,
				@bra_id						int,
				@rmadt_id					int,
				@rmah_id					INT,
				@rmadt_guid					uniqueidentifier,
				@cust_id					int,
				@supp_id					INT,
				@rmah_cd					datetime,
				@user_id					int


	SELECT		@comp_id					=1,
				@bra_id						=1,
				@rmadt_id					=1233170,
				@rmah_id					=282,
				@rmadt_guid					='e8bbebca-3484-47e6-9dca-76ca15d1dace',
				@cust_id					=24288,
				@supp_id					=null,
				@rmah_cd					= GETDATE(),
				@user_id					=1
	*/
-- -----------------------------------------------------------------




	SET @strReturnDescription	= '*'
	SET @return_value			= 0
	SET @ret_ErrorCode			= 0
	SET NOCOUNT ON


    --SAVE TRANSACTION traPROTECT
    --BEGIN TRANSACTION
	DECLARE @intTranCounter AS INT = @@TRANCOUNT;
	IF		@intTranCounter > 0	SAVE TRANSACTION traPROTECT		-- MOS 06-2020
    BEGIN TRY


			-- ------------------------------------
			-- Bloquear la base antes de hacer nada
			-- ------------------------------------
			-- MOS 05-2022: Se comentó x tema performance
			--DECLARE @intLock AS INT
			--SELECT	@intLock = tce.sb_id
			--	FROM tbsysBlockPage4IsoTran  tce
			-- ------------------------------------



		--actualizar datos en el Header de RMA
		EXEC dbo.spRMAHeader_updateData
				@comp_id,
				@bra_id,
				@rmah_id,
				@cust_id,
				@supp_id,
				@rmah_cd,
				@rmah_isInSuppplier,
				@rmah_note1,
				@rmah_note2


		-- NOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOO
		--eliminar todos los registro detalle relacionados a la cabecera actualizada
		--EXEC dbo.[spRMADetail_deleteAllData]		-- Ref: #3
		--		@comp_id,	@rmah_id				-- Ref: #3


		DECLARE @intReturnError AS INT
		SET @intReturnError = -777
		--proceso general de actualizaciones de RMA dependiendo de los estados
		EXEC dbo.spRMA_updateCommonData
				@comp_id,	@bra_id,
				@rmah_id,	@rmadt_guid,
				@cust_id,	@supp_id,
				@rmah_cd,	@user_id,
				@intReturnError OUTPUT

		SET @return_value = @intReturnError

		--liberar el isediting
		EXEC dbo.spRMA_UpdateIsEditing
				@comp_id,	@rmah_id,
				'False',	@rmadt_guid



--==
	-- SELECT 1 / 0
	-- SET @return_value = 10
--==



	-- -------------------------------------------------------
	-- ATENCION: No poner nada debajo de este codigo!
	-- -------------------------------------------------------
		-- Si de updateCommondata viene un error
		IF @return_value < 0
			BEGIN
				--ROLLBACK TRANSACTION traPROTECT
				IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT		-- MOS 06-2020
			END
		--ELSE
		--	BEGIN
		--		IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT
		--	END
		RETURN

    END TRY
    BEGIN CATCH
        --ROLLBACK TRANSACTION traPROTECT
        IF @intTranCounter <> 0 AND XACT_STATE() <> -1	ROLLBACK TRANSACTION traPROTECT		-- MOS 06-2020
		SET @return_value = -5
		SET @strReturnDescription = ERROR_MESSAGE()

        DECLARE @ErrorMessage   NVARCHAR(4000)
        DECLARE @ErrorSeverity  INT
        DECLARE @ErrorState     INT
        SELECT  @ErrorMessage    = ERROR_MESSAGE(),
                @ErrorSeverity   = ERROR_SEVERITY(),
                @ErrorState      = ERROR_STATE()
        IF      @ErrorState      = 0 SET @ErrorState = 1
        RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

    END CATCH
	-- -------------------------------------------------------


--IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT

--	END
--	TRY BEGIN CATCH
--		ROLLBACK TRANSACTION
--		SET @return_value = -5
--		SET @strReturnDescription = ERROR_MESSAGE()
--	END CATCH



END
GO




create  PROCEDURE [dbo].[spRMA_updateData_new]
(
	@comp_id					INT,
	@bra_id						INT,
	@rmah_id					INT,
	@rmadt_guid					UNIQUEIDENTIFIER,
	@cust_id					INT,
	@supp_id					INT,
	@rmah_cd					DATETIME,
	@user_id					INT
)
AS
SET NOCOUNT ON
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2011-03-17
-- Parte		: S/P - Ref: #1
-- Description	: Como todo el procesamiento de los diferentes estados que puede tener cada artículo es el mismo,
--				  tanto para el Update o el Insert, se unificó todo el código en el spRMA_updateCommonData
-- =================================================================================================================



/*
DECLARE	@comp_id					int,
		@bra_id						int,
		@rmah_id					INT,
		@rmadt_guid					uniqueidentifier,
		@cust_id					int,
		@supp_id					INT,
		@rmah_cd					datetime,
		@user_id					int

SELECT	@comp_id					=1,
		@bra_id						=1,
		@rmah_id					=282,
		@rmadt_guid					='e8bbebca-3484-47e6-9dca-76ca15d1dace',
		@cust_id					=24288,
		@supp_id					=null,
		@rmah_cd					= GETDATE(),
		@user_id					=1
*/



--actualizar datos en el Header de RMA
EXEC dbo.spRMAHeader_updateData
		@comp_id,	@bra_id,
		@rmah_id,	@cust_id,
		@supp_id,	@rmah_cd



--eliminar todos los registro detalle relacionados a la cabecera actualizada
EXEC dbo.[spRMADetail_deleteAllData]
		@comp_id,	@rmah_id



--proceso general de actualizaciones de RMA dependiendo de los estados
EXEC dbo.spRMA_updateCommonData
		@comp_id,	@bra_id,
		@rmah_id,	@rmadt_guid,
		@cust_id,	@supp_id,
		@rmah_cd,	@user_id



--liberar el isediting
EXEC dbo.spRMA_UpdateIsEditing
		@comp_id,	@rmah_id,
		'False'
GO




create  PROCEDURE [dbo].[spRMA_updateData_original]
(
	@comp_id					INT,
	@bra_id						INT,
	@rmah_id					INT,
	@rmadt_guid					UNIQUEIDENTIFIER,
	@cust_id					INT,
	@supp_id					INT,
	@rmah_cd					DATETIME,
	@user_id					INT
)
AS
SET NOCOUNT ON
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-08-06
-- Parte		: 448
-- Description	: Para cumplir el requerimiento solicitado, se actualiza el campo soh_isediting al valor 'False',
--				  luego de la actualización de tbSaleOrderSerials, porque el spSaleOrderSerials_insertData lo pone
--				  por defecto en 'True'
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-08-06
-- Parte		: 457
-- Description	: Se actualiza el ssos_id a 201 cuando el srpt_id = 35
--				  se actualizó que el ssos_id para que quede exactamente igual al spRMA_insertData
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-09-16
-- Parte		: S/P Referencia: #1
-- Description	: Se cambia el orden de las monedas para la obtención del @ExchangeToCustomerCurrency
-- =================================================================================================================
-- Author		: GGG
-- Update Date	: 2010-10-18
-- Parte		: S/P Referencia: #2
-- Description	: Se cambia lo realizado por el parte 457 y se actualiza el ssos_id a 200 cuando el srpt_id es 35
-- =================================================================================================================






/*
DECLARE 	@comp_id					int,
			@bra_id						int,
			@rmadt_id					int,
			@rmah_id					INT,
			@rmadt_guid					uniqueidentifier,
			@cust_id					int,
			@supp_id					INT,
			@rmah_cd					datetime,
			@user_id					int


SELECT		@comp_id					=1,
			@bra_id						=1,
			@rmadt_id					=1233170,
			@rmah_id					=282,
			@rmadt_guid					='e8bbebca-3484-47e6-9dca-76ca15d1dace',
			@cust_id					=24288,
			@supp_id					=null,
			@rmah_cd					= GETDATE(),
			@user_id					=1

BEGIN TRANSACTION
*/




DECLARE @bra_processingDate AS DATETIME,
		@prli_id				INT

select	@bra_processingDate		= bra_processingDate,
		@prli_id				= br.bra_RMA_prli_Id4NoSerialItems
from	dbo.tbBranch			  br
where	br.bra_id				= @bra_id
AND		br.comp_id				= @comp_id






--actualizar cabecera
exec	dbo.[spRMAHeader_updateData]
		@comp_id,	@bra_id,
		@rmah_id,	@cust_id,
		@supp_id,	@rmah_cd



--eliminar todos los registro detalle relacionados a la cabecera actualizada
exec	dbo.[spRMADetail_deleteAllData]
		@comp_id,	@rmah_id



-- declareción de variables para obtener los datos del cursor
declare	@lcomp_id				INT,
		@lrmadt_guid			uniqueidentifier,
		@lrmadt_id				int,
		@lbra_id				INT,
		@lit_transaction		INT,
		@litem_id				int,
		@lstor_id				int,
		@lrmadt_Manual			VARCHAR(100),
		@lrmadt_originalPrice	DECIMAL(19,6),
		@lcurr_id				INT,
		@lrmadt_qty				DECIMAL(19,5),
		@luser_id_Reception		INT,
		@lrmadt_Date_Reception	datetime,
		@lrmadt_ReceptionNote	VARCHAR(8000),
		@lis_id					INT,
		@luser_id_Diagnostic	INT,
		@lrmadt_Date_Diagnostic	DATETIME,
		@lrmadt_DiagnosticNote	VARCHAR(8000),
		@lsrpt_id				INT,
		@lrmadt_ProcNote        VARCHAR(8000),
		@ldf_id4CreditNote		INT,
		@tis_id					INT,
		@lrv					INT,
		@lrmadt_isNew			BIT,
		@ltis_priority				DECIMAL(14,4),
		@litem_desc					VARCHAR(200)


-- declaración del cursor para obtener los datos de tbRMADetailTmp
declare cursor_RMA_uD_items cursor for
select	trdt.comp_id,
		trdt.rmadt_guid,
		trdt.rmadt_id,
		trdt.bra_id,
		trdt.it_transaction,
		trdt.item_id,
		trdt.stor_id,
		trdt.rmadt_Manual,
		trdt.rmadt_originalPrice,
		trdt.curr_id,
		trdt.rmadt_qty,
		trdt.user_id_Reception,
		trdt.rmadt_Date_Reception,
		trdt.rmadt_ReceptionNote,
		trdt.is_id,
		trdt.user_id_Diagnostic,
		trdt.rmadt_Date_Diagnostic,
		trdt.rmadt_DiagnosticNote,
		trdt.srpt_id,
		trdt.rmadt_ProcNote,
		trdt.df_id4CreditNote,
		trdt.tis_id,
		trdt.rmadt_isNew,
		isnull(ttis.tis_priority,0),
		isnull(ti.item_desc,'')

from	dbo.tbRMA_Detail_Tmp				trdt

		LEFT JOIN tbTempItemStock			ttis
		ON	ttis.comp_id	= trdt.comp_id
		AND ttis.tis_guid	= trdt.rmadt_guid

		LEFT JOIN tbItem					ti
		ON	ti.comp_id		= trdt.comp_id
		AND ti.item_id		= trdt.item_id

where	rmadt_guid = @rmadt_guid


--abrir cursor
open	cursor_RMA_uD_items


-- lectura anticipada del cursor
fetch	cursor_RMA_uD_items
into	@lcomp_id,
		@lrmadt_guid,
		@lrmadt_id,
		@lbra_id,
		@lit_transaction,
		@litem_id,
		@lstor_id,
		@lrmadt_Manual,
		@lrmadt_originalPrice,
		@lcurr_id,
		@lrmadt_qty,
		@luser_id_Reception,
		@lrmadt_Date_Reception,
		@lrmadt_ReceptionNote,
		@lis_id,
		@luser_id_Diagnostic,
		@lrmadt_Date_Diagnostic,
		@lrmadt_DiagnosticNote,
		@lsrpt_id,
		@lrmadt_ProcNote,
		@ldf_id4CreditNote,
		@tis_id,
		@lrmadt_isNew,
		@ltis_priority,
		@litem_desc



DECLARE @it_order	INT
SET @it_order = 0

	-- se recorre el cursor hasta el fin del mismo
	while   @@fetch_status = 0
	begin

		SET @it_order = @it_order + 1

		-- por cada registro del cursor se realiza el insert en la tabla detalle
		DECLARE @lrmad_id INT
		exec	dbo.[spRMADetail_insertData]
				@lcomp_id,					@rmah_id,
				@lbra_id,					@lit_transaction,
				@litem_id,					@lstor_id,
				@lrmadt_Manual,				@lrmadt_originalPrice,
				@lcurr_id,					@lrmadt_qty,
				@luser_id_Reception,		@lrmadt_ReceptionNote,
				@lis_id,					@luser_id_Diagnostic,
				@lrmadt_Date_Diagnostic,	@lrmadt_DiagnosticNote,
				@ldf_id4CreditNote,			@lsrpt_id,
				@lrmadt_ProcNote,			@return_value	= @lrmad_id output


		IF @lrmadt_isNew = 'True'
		BEGIN


		-- Declaro variables
		DECLARE @intSm_id					INT
		DECLARE @intDisc_id					INT
		DECLARE @intCurr_id					INT
		DECLARE @intDl_id					INT
		DECLARE @intCurr_id_b				INT
		DECLARE @intStor_id_b				INT
		DECLARE @ct_CompanyCurrency			INT
		DECLARE @ExchangeToCustomerCurrency	DECIMAL(19,4)
		DECLARE @ExchangeToCompanyCurrency	DECIMAL(19,4)
		DECLARE @intSt_id					INT
		DECLARE @lsoh_id					INT
		DECLARE @total						DECIMAL(19,4)
		DECLARE @ct_transaction				INT
		DECLARE @ssos_id					INT
		DECLARE @tax_id						INT
		DECLARE @neto						DECIMAL(18,2)
		DECLARE @tax						DECIMAL(18,2)
		DECLARE	@rv							INT
		DECLARE @bra_RMA_dfId4Packing		INT
		--DECLARE @bra_RMA_dfId4Credit		INT
		DECLARE @bra_RMA_storId4OK			INT
		DECLARE @bra_RMA_storId4Scrap		INT
		DECLARE @now						DATETIME
		DECLARE @lretval					INT

		-- obtener la fecha actual
		set @now		= getdate()


		-- recuperar la diferencia de cambio y la moneda en que realizó la cobranza
		Select 	@total	=  0

		-- recuperamos la moneda y depósito de la sucursal
		SELECT	@intCurr_id_b	= br.curr_id,
				@intStor_id_b	= br.stor_id
		FROM	dbo.tbBranch		br
		WHERE	br.comp_id		= @comp_id
		AND		br.bra_id		= @bra_id

		-- recupero el df_id
		SELECT @bra_RMA_dfId4Packing = tb.bra_RMA_dfId4Packing,
			   --@bra_RMA_dfId4Credit	 = tb.bra_RMA_dfId4Credit,
			   @bra_RMA_storId4OK	 = tb.bra_RMA_storId4OK,
			   @bra_RMA_storId4Scrap = tb.bra_RMA_storId4Scrap

		FROM tbBranch tb
		WHERE tb.comp_id = @comp_id
		AND tb.bra_id = @bra_id


		-- Customer
		SELECT	@intSm_id		= cu.sm_id,
				@intDisc_id		= cu.disc_id,
				@intCurr_id		= cu.curr_id,
				@intDl_id		= cu.dl_id,
				@intSt_id		= cu.st_id,
				@intSt_id		= cu.st_id
		FROM	dbo.tbCustomer		 cu
		WHERE	cu.comp_id		= @comp_id
		AND		cu.cust_id		= @cust_id

		-- Company
		SELECT	@ct_CompanyCurrency = comp.curr_id
		FROM	dbo.tbCompany		comp
		WHERE	comp.comp_id		= @comp_id


		-- ===========================================================================================================
		-- 16-09-2010 - GGG - Referencia: #1
		-- tipo de cambio a moneda del cliente
		SELECT @ExchangeToCustomerCurrency  = dbo.fnGetExchange(@comp_id, 1, @lcurr_id, @intCurr_id, 0, 0, 'False')
		-- ===========================================================================================================


		DECLARE @df_id INT

		-- Si son via remito
		IF @lsrpt_id = 10 OR @lsrpt_id = 30 OR @lsrpt_id = 35 OR @lsrpt_id = 50
			SET @df_id = @bra_RMA_dfId4Packing
		-- Si son via Nota de Credito
		IF @lsrpt_id = 20 OR @lsrpt_id = 40

			SET @df_id = @ldf_id4CreditNote


		-- ========================================================================================================
		-- 2010-08-06 - GGG - Parte 457
		-- ========================================================================================================

		/*  ASI ESTABA ***************************************
		/*
		-- obtengo ssos_id
		select	top 1 @ssos_id = ssos_id
		from	dbo.vwsysSaleOrderStatus_IsOkForEmmition

		IF @lsrpt_id = 40
			SELECT @ssos_id = 50
		*/
		******************************************************/

		SELECT	@ssos_id =	CASE
								WHEN @lsrpt_id = 10	THEN 201 -- funciona ok se devuelve la misma mercaderia
								WHEN @lsrpt_id = 20	THEN 201 -- funciona ok se efectúa NC
								WHEN @lsrpt_id = 30	THEN 201 -- funciona mal se devuelve al misma mercaderia
								WHEN @lsrpt_id = 35	THEN 200 -- funciona mal se cambia por igual mercadería		-- Ref: #2
								WHEN @lsrpt_id = 40	THEN 201 -- funciona mal se efectúa NC
								ELSE 200
		      	          	END
		-- ========================================================================================================




			DECLARE @customerCurrencyId AS INT

			SELECT	@customerCurrencyId = tc.curr_id
			FROM	tbCustomer tc
			WHERE	tc.comp_id			= @comp_id
			AND		tc.cust_id			= @cust_id




			-- ========================================================================================================
			-- 2010-08-23 - GGG - Parte S/P
			-- Se pasa la actualización de Pedidos a un sólo SPs
			-- ========================================================================================================
			EXEC spRMA_updateSaleOrder
				@comp_id,
				@bra_id,
				@rmadt_guid,
				@cust_id,
				@user_id,
				@bra_processingDate,
				@prli_id,
				@intSm_id,
				@intDisc_id,
				@intDl_id,
				@ExchangeToCustomerCurrency,
				@intSt_id,
				@lsoh_id,
				@total,
				@ssos_id,
				@tax_id,
				@neto,
				@now,
				@litem_id,
				@lstor_id,
				@lrmadt_originalPrice,
				@lrmadt_qty,
				@lis_id,
				@lsrpt_id,
				@lrmadt_ProcNote,
				@ldf_id4CreditNote,
				@tis_id,
				@ltis_priority,
				@litem_desc,
				@customerCurrencyId,
				@df_id,
				@rmah_id,
				@lrmad_id,
				@lcurr_id

--			IF @lsrpt_id = 20 OR @lsrpt_id = 50
--			BEGIN
--
--				SET @lsoh_id = -1
--
--				-- está opción es para lo que tiene grabado TempItemStock
--
--
--				EXEC spSaleOrder_insertData
--					@lsoh_id,						@rmadt_guid,
--					@comp_id,						@bra_id,
--					@bra_processingDate,			@bra_processingDate,
--					'',								'',
--					'',								'',
--					'False',						@intSm_id,
--					@cust_id,						@intSt_id,
--					@intDisc_id,					@intDl_id,
--					NULL,							@bra_processingDate,
--					NULL,							NULL,
--					NULL,							0,
--					@user_id,						'False',
--					NULL, 							@total,
--					@ldf_id4CreditNote,				@ssos_id,
--					@ExchangeToCustomerCurrency,	@customerCurrencyId,
--					@return_value = @lretval		OUTPUT
--
--
--			END
--			ELSE
--			BEGIN
--
--				IF @lsrpt_id = 10 OR @lsrpt_id = 30 OR @lsrpt_id = 35 OR @lsrpt_id = 40 OR @lsrpt_id = 60 OR @lsrpt_id = 70
--				BEGIN
--
--
--					-- obtiene el próximo soh_id de la tabla tbCounters, con id 2
--					exec dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @lsoh_id OUTPUT
--
--
--					SET @total = CONVERT(DECIMAL(19,6),@lrmadt_qty) * @lrmadt_originalPrice --ggg
--
--					EXEC spSaleOrderHeader_insertData
--						@comp_id,  						@bra_id,
--						@lsoh_id,						@bra_processingDate,
--						@bra_processingDate, 			@lrmadt_ProcNote,
--						'',								'',
--						'',								'False',
--						@intSm_id,						@cust_id,
--						@intSt_id,						@intDisc_id,
--						@intDl_id,						NULL,
--						@bra_processingDate,			NULL,
--						NULL,							NULL,
--						0,								@user_id,
--						'False',  						NULL,
--						@total, -- ggg
--						@df_id,
--						@ssos_id,  						@ExchangeToCustomerCurrency,
--						@customerCurrencyId	--ggg
--
--
--					EXEC spSaleOrderDetail_insertData
--						@comp_id, 						@bra_id,
--						@lsoh_id,  						@ltis_priority,
--						@litem_id,  --ggg
--						@litem_desc,
--						'',  							@customerCurrencyId, --ggg  --@ExchangeToCustomerCurrency ,
--						1,								@lrmadt_qty,
--						@prli_id,						@lrmadt_originalPrice,
--						@lstor_id,						@user_id,
--						@now,							@tax_id,
--						@neto,							@rv OUTPUT,
--						@rmah_id,						@lrmad_id,
--						NULL,							NULL,
--						NULL,							NULL,
--						NULL,							'False'
--
--				END
--			END
--
--
--
--
--
--
--
--			IF (@lsrpt_id = 20 OR @lsrpt_id = 40) AND NOT @lis_id IS NULL
--			BEGIN
--
--				--IF NOT @lis_id IS NULL
--				--BEGIN
--
--				DECLARE @lsos_id INT
--
--				EXEC spSaleOrderSerials_insertData
--					@comp_id,		@lis_id,
--					@bra_id, 		@lsoh_id,
--					null, 			@return_value = @lsos_id OUTPUT
--
--
--				-- ====================================================================================================
--				-- 2010-08-06 - GGG - Parte 448
--				-- ====================================================================================================
--				UPDATE 	dbo.tbSaleOrderHeader
--				SET		soh_isEditing	= 'False'
--				WHERE   comp_id			= @comp_id
--				AND 	bra_id			= @bra_id
--				AND 	soh_id			= @lsoh_id
--				-- ====================================================================================================
--
--				--END
--			END --end 20 40
			-- ========================================================================================================



			-- Funciona MAL - R.M.A. -60
			-- Si tiene número de serie, ponerlo como no disponible
			IF @lsrpt_id = 60 AND (NOT @lis_id IS NULL)
			BEGIN
				UPDATE	tbItemSerials
				SET		is_available	= 'False'
				WHERE	comp_id			= @comp_id
				AND		is_id			= @lis_id
				AND		is_serial		<> ''
				AND		NOT is_serial IS NULL
			END --end 60

	-- Funciona OK   - Se devuelve al Depósito -70
	IF @lsrpt_id = 70 AND (not @litem_id IS NULL OR NOT @lis_id IS NULL)
	BEGIN

		DECLARE @lct_transaction_rv		INT
		DECLARE @intDocumentNumber		AS INT
		DECLARE @ct_ACurrencyExchange	AS DECIMAL(19,4)
		DECLARE @ct_Branch2CompanyCurrencyExchange AS DECIMAL(19,4)


		exec dbo.spCounters_getNextValue @comp_id, @bra_id, 350, @intDocumentNumber OUTPUT

		-- recuperamos la moneda y depósito de la sucursal
		SELECT	@intCurr_id_b	= br.curr_id,
				@intStor_id_b	= br.stor_id
			FROM	dbo.tbBranch		br
			WHERE	br.comp_id		= @comp_id
				AND	br.bra_id		= @bra_id

		-- Customer
		SELECT	@intSm_id		= cu.sm_id,
				@intDisc_id		= cu.disc_id,
				@intCurr_id		= cu.curr_id,
				@intDl_id		= cu.dl_id,
				@intSt_id		= cu.st_id
			FROM	dbo.tbCustomer		 cu
			WHERE	cu.comp_id		= @comp_id
				AND cu.cust_id		= @cust_id

		-- Company
		SELECT	@ct_CompanyCurrency = comp.curr_id
			FROM	dbo.tbCompany comp
			WHERE	comp.comp_id	= @comp_id

		-- tipo de cambio a moneda del cliente
		SELECT @ct_ACurrencyExchange = dbo.fnGetExchange(@comp_id, 1, @intCurr_id, @lcurr_id, 0, 0, 'False')

		--tipo de cambio de la moneda de la sucursal a la moneda de la compañia
		SELECT @ct_Branch2CompanyCurrencyExchange = dbo.fnGetExchange (@comp_id, 1, @intCurr_id_b, @ct_CompanyCurrency, 0, 0, 'False')


		EXEC spCommercialTransactions_InsertData
			@comp_id,							@bra_id,		@intDocumentNumber,
			@now,								null,			@cust_id,
			null,								@user_id,		0,
			0,									0,				0,
			@intCurr_id_b,						@intSm_id,		@intDisc_id,
			0,									0,				@intCurr_id,
			@ct_ACurrencyExchange,				null,			@intDl_id,
			@intSt_id,							null,			@ct_CompanyCurrency,
			@ct_Branch2CompanyCurrencyExchange,	301,			null,
			null,								null,			null,
			0,									@lct_transaction_rv OUTPUT,
			null,								null

			DECLARE @lit_transaction_rv INT

			-- Recupera Stock Anterior
			DECLARE @decStorePreviuos AS DECIMAL(19,6)
			SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
				FROM tbItemStorage tis
				WHERE	tis.comp_id = @comp_id
					AND	tis.stor_id = @lstor_id
					AND tis.item_id = @litem_id

			IF not @litem_id IS NULL
			BEGIN
				EXEC spItemStorage_insertData
				@comp_id,				@litem_id,
				@lstor_id,				@lrmadt_qty
			END


			INSERT INTO tbItemTransactions
			(
				comp_id,				bra_id,						ct_transaction,
				item_id,				it_qty,						it_priceWithOutOthers,
				it_price,				curr_id,					it_exchangeToBranchCurrency,
				it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
				it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
				it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
				stor_id,				it_storePrevious,			prli_id,
				byor_id,				it_isProduction,			it_isAssociation,
				it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
				it_order,				so_id,						it_guarantee,
				it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
				it_CreditIntPlus,		puco_id,					it_poh_bra_id,
				it_poh_id,				it_soh_id,					it_sod_id,
				rmah_id,				rmad_id,					it_qty_rma,
				it_tis_id_aux
			)
			VALUES
			(
				@comp_id,				@bra_id,					@lct_transaction_rv,
				@litem_id,				@lrmadt_qty,				0,
				@lrmadt_originalPrice,	@lcurr_id,					@lcurr_id,
				0,						0,							0,
				0,						0,							0,
				@lrmadt_originalPrice,	@lcurr_id,					1,
				@lstor_id,				isnull(@decStorePreviuos,0),NULL,
				NULL,					'False',					'False',
				NULL,					@now,						NULL,
				@it_order,				NULL,						0,
				0,						0,							0,
				0,						NULL,						NULL,
				NULL,					NULL,						NULL,
				@rmah_id,				@lrv,						@lrmadt_qty,
				NULL
			)

			UPDATE	tbItemSerials
				SET		is_available		= 'True',
						stor_id				= @lstor_id
				WHERE	comp_id				= @comp_id
				AND		is_id				= @lis_id
				AND		is_serial			<> ''
				AND		NOT is_serial		IS NULL


		END --end 70



		-- Funciona OK, se incorpora al Deposito -1010
		-- Cambio por Nueva Mercaderia (Mismo Artículo) -1040
		IF @lsrpt_id = 1010 OR @lsrpt_id = 1040
		BEGIN

			exec dbo.spCounters_getNextValue @comp_id, @bra_id, 350, @intDocumentNumber OUTPUT

			EXEC spCommercialTransactions_InsertData
				@comp_id,				@bra_id,		@intDocumentNumber,
				@now,					null,			@cust_id,
				null,					@user_id,		0,
				0,						0,				0,
				@intCurr_id_b,			@intSm_id,		@intDisc_id,
				0,						0,				@intCurr_id,
				@ct_ACurrencyExchange, 	null,			@intDl_id,
				@intSt_id,				null,			@ct_CompanyCurrency,		@ct_Branch2CompanyCurrencyExchange ,
				301,					null,			null,
				null,					null,			0,
				@lct_transaction_rv OUTPUT,				null,
				null


			-- Recupera Stock Anterior
			SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
				FROM tbItemStorage tis
				WHERE	tis.comp_id = @comp_id
					AND	tis.stor_id = @lstor_id
					AND tis.item_id = @litem_id

			IF not @litem_id IS NULL
			BEGIN
				EXEC spItemStorage_insertData
				@comp_id,				@litem_id,
				@bra_RMA_storId4OK,		@lrmadt_qty
			END

			INSERT INTO tbItemTransactions
			(
				comp_id,				bra_id,						ct_transaction,
				item_id,				it_qty,						it_priceWithOutOthers,
				it_price,				curr_id,					it_exchangeToBranchCurrency,
				it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
				it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
				it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
				stor_id,				it_storePrevious,			prli_id,
				byor_id,				it_isProduction,			it_isAssociation,
				it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
				it_order,				so_id,						it_guarantee,
				it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
				it_CreditIntPlus,		puco_id,					it_poh_bra_id,
				it_poh_id,				it_soh_id,					it_sod_id,
				rmah_id,				rmad_id,					it_qty_rma,
				it_tis_id_aux
			)
			VALUES
			(
				@comp_id,				@bra_id,					@lct_transaction_rv,
				@litem_id,				@lrmadt_qty,				0,
				@lrmadt_originalPrice,	@lcurr_id,					@lcurr_id,
				0,						0,							0,
				0,						0,							0,
				@lrmadt_originalPrice,	@lcurr_id,					1,
				@lstor_id,				isnull(@decStorePreviuos,0),NULL,
				NULL,					'False',					'False',
				NULL,					@now,						NULL,
				@it_order,				NULL,						0,
				0,						0,							0,
				0,						NULL,						NULL,
				NULL,					NULL,						NULL,
				@rmah_id,				@lrv,						@lrmadt_qty,
				NULL
			)
		END --1010 1040

		-- Rechazo de Cambio, Incorporar a Deposito de Scrap
		IF @lsrpt_id = 1020
		BEGIN

			EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 350, @intDocumentNumber OUTPUT


			EXEC spCommercialTransactions_InsertData
				@comp_id,				@bra_id,				@intDocumentNumber,
				@now,					null,					@cust_id,
				null,					@user_id,				0,
				0,						0,						0,
				@intCurr_id_b,			@intSm_id,				@intDisc_id,
				0,0, @intCurr_id,		@ct_ACurrencyExchange,	null,
				@intDl_id,				@intSt_id,				null,
				@ct_CompanyCurrency,	@ct_Branch2CompanyCurrencyExchange,
				301,					null,					null,
				null,					null,					0,
				@lct_transaction_rv OUTPUT,						null,
				null


			-- Recupera Stock Anterior
			SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
				FROM tbItemStorage tis
				WHERE	tis.comp_id = @comp_id
					AND	tis.stor_id = @lstor_id
					AND tis.item_id = @litem_id

			IF not @litem_id IS NULL
			BEGIN
				EXEC spItemStorage_insertData
				@comp_id,				@litem_id,
				@bra_RMA_storId4Scrap,		@lrmadt_qty
			END


			INSERT INTO tbItemTransactions
			(
				comp_id,				bra_id,						ct_transaction,
				item_id,				it_qty,						it_priceWithOutOthers,
				it_price,				curr_id,					it_exchangeToBranchCurrency,
				it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
				it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
				it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
				stor_id,				it_storePrevious,			prli_id,
				byor_id,				it_isProduction,			it_isAssociation,
				it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
				it_order,				so_id,						it_guarantee,
				it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
				it_CreditIntPlus,		puco_id,					it_poh_bra_id,
				it_poh_id,				it_soh_id,					it_sod_id,
				rmah_id,				rmad_id,					it_qty_rma,
				it_tis_id_aux
			)
			VALUES
			(
				@comp_id,				@bra_id,					@lct_transaction_rv,
				@litem_id,				@lrmadt_qty,				0,
				@lrmadt_originalPrice,	@lcurr_id,					@lcurr_id,
				0,						0,							0,
				0,						0,							0,
				@lrmadt_originalPrice,	@lcurr_id,					1,
				@lstor_id,				isnull(@decStorePreviuos,0),NULL,
				NULL,					'False',					'False',
				NULL,					@now,						NULL,
				@it_order,				NULL,						0,
				0,						0,							0,
				0,						NULL,						NULL,
				NULL,					NULL,						NULL,
				@rmah_id,				@lrv,						@lrmadt_qty,
				NULL
			)
		END --1020

		--incrementando los it_qty_rma correspondientes de la tabla ItemTransactions
		SELECT @lsrpt_id


		-- Nota de Crédito -1030
		IF @lsrpt_id = 1030
		BEGIN
				SELECT @lrmadt_qty

				UPDATE	tbItemTransactions
				SET		it_qty_rma			= @lrmadt_qty--@qty + @lrmadt_qty

				WHERE	comp_id				= @comp_id
				AND		bra_id				= @bra_id
				AND		item_id				= @litem_id
				AND		it_qty				= @lrmadt_qty

		END	--1030


		-- Cambio por Nueva Mercaderia (Mismo Artículo) -1040
		--Genero registros de tbItemSerial en blanco
		IF @lsrpt_id = 1040 AND not @litem_id IS NULL
		BEGIN
			EXEC spItemSerials_insertQtyData
				@comp_id,
				@bra_id,
				@lct_transaction_rv,
				@lit_transaction_rv,
				@litem_id,
				@bra_RMA_storId4OK,
				@lrmadt_qty

		END --1040

		END

		-- por cada registro del cursor se realiza el delete de la tabla temporal
		exec	dbo.[spRMADetailTmp_deleteData]	@lrmadt_id


		-- próxima lectura del cursor
		fetch	cursor_RMA_uD_items
		into	@lcomp_id,
				@lrmadt_guid,
				@lrmadt_id,
				@lbra_id,
				@lit_transaction,
				@litem_id,
				@lstor_id,
				@lrmadt_Manual,
				@lrmadt_originalPrice,
				@lcurr_id,
				@lrmadt_qty,
				@luser_id_Reception,
				@lrmadt_Date_Reception,
				@lrmadt_ReceptionNote,
				@lis_id,
				@luser_id_Diagnostic,
				@lrmadt_Date_Diagnostic,
				@lrmadt_DiagnosticNote,
				@lsrpt_id,
				@lrmadt_ProcNote,
				@ldf_id4CreditNote,
				@tis_id,
				@lrmadt_isNew,
				@ltis_priority,
				@litem_desc

	END

close cursor_RMA_uD_items
deallocate cursor_RMA_uD_items



DELETE FROM tbTempItemStock
WHERE tis_guid = @rmadt_guid



--liberar el isediting
exec	dbo.spRMA_UpdateIsEditing @comp_id, @rmah_id, 'False'



/*
if @@ERROR = 0
	commit TRANSACTION
ELSE
	ROLLBACK TRANSACTION
*/
GO






-- MOS
-- 04-2009
-- Actualiza isEditing

CREATE  PROCEDURE [dbo].[spRMA_UpdateIsEditing]
(
	@comp_id				INT,
	@rmah_id				INT,
	@rmah_isEditing			BIT,
	@guid					UNIQUEIDENTIFIER	-- TN	: 908
)
AS
BEGIN

	SET NOCOUNT ON

	-- =================================================================================================================
	-- Author		:
	-- Update Date	: 2011-06-22
	-- TN			: 908
	-- Description	: Se habilita la actualización del isediting en tbRMA_Detail_Tmp
	-- =================================================================================================================


	-- -----------------------------------------------------------------------------
	 -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	 -- -----------------------------------------------------------------------------
	 SET LOCK_TIMEOUT 500
	 SET DEADLOCK_PRIORITY LOW
	 -- -----------------------------------------------------------------------------
	UPDATE tbRMA_Header				WITH (ROWLOCK)
		SET
			rmah_isEditing		= @rmah_isEditing,
			rmah_isEditingCD	= GETDATE()
	WHERE	comp_id		= @comp_id
		AND rmah_id		= @rmah_id




	-- =================================================================================================================
	-- TN	: 908
	UPDATE	tbRMA_Detail_Tmp		WITH (ROWLOCK)
	SET		rmadt_isEditing		= @rmah_isEditing,
			rmadt_isEditingCD	= GETDATE()
	WHERE	comp_id		= @comp_id
		AND rmadt_guid	= @guid
	-- =================================================================================================================


END
GO



CREATE PROCEDURE [dbo].[spRMA_updateSaleOrder]
(
	@comp_id						INT,
	@bra_id							INT,
	@rmadt_guid						UNIQUEIDENTIFIER,
	@cust_id						INT,
	@user_id						INT,
	@bra_processingDate				DATETIME,
	@prli_id						INT,
	@intSm_id						INT,
	@intDisc_id						INT,
	@intDl_id						INT,
	@ExchangeToCustomerCurrency		DECIMAL(19,6),
	@intSt_id						INT,
	@soh_id							INT,
	@total							DECIMAL(19,6),
	@ssos_id						INT,
	@tax_id							INT,
	@neto							DECIMAL(18,2),
	@now							DATETIME,
	@item_id						INT,
	@stor_id						INT,
	@rmadt_originalPrice			DECIMAL(19,6),
	@rmadt_qty						DECIMAL(19,5),
	@is_id							INT,
	@srpt_id						INT,
	@rmadt_ProcNote					VARCHAR(8000),
	@df_id4CreditNote				INT,				-- AL PEDO NO SE USA Y EL HDP LO DEJO IGUAL!!!
	@tis_id							INT,
	@tis_priority					DECIMAL(14,4),
	@item_desc						VARCHAR(200),
	@customerCurrencyId				INT,
	@df_id							INT,
	@rma_id							INT,
	@rmad_id						INT,
	@rmadt_curr_id					INT,
	@intSaleOrderHeaderUpdated      INT OUTPUT
)
AS

BEGIN


	SET NOCOUNT ON
	-- =======================================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-06
	-- Parte		: 448
	-- Description	: Para cumplir el requerimiento solicitado, se actualiza el campo soh_isediting al valor 'False',
	--				  luego de la actualización de tbSaleOrderSerials, porque el spSaleOrderSerials_insertData lo pone
	--				  por defecto en 'True'
	-- =================================================================================================================
	-- Author		: MOH
	-- Creation Date: 2010-08-23
	-- Parte		: S/P
	-- Description	: Generación de Pedidos desde RMA. Este código se extrajo de los SPs spRMA_insertData y
	--				  spRMA_updateData, para unificar codificación
	-- =======================================================================================================================================
	-- Author		: MOH
	-- Creation Date: 2010-09-16
	-- Parte		: S/P
	-- Description	: Se modifica la forma de generación de Pedidos, para los estados de RMA 10, 30, 35, 40, 60 y 70.
	--				  Originalmente se generaba un Pedido por cada RMA que lo solicite, ahora si ya existe un Pedido con
	--				  los siguientes valores iguales; comp_id, cust_id, st_id, bra_id, sm_id, ssos_id, df_id, soh_ExchangeToCustomerCurrency
	--				  y el soh_isEditing = 'False', se agregan los ítems del RMA al pedido existente sino se genera uno nuevo
	-- =======================================================================================================================================
	-- Author		: MOH
	-- Creation Date: 2010-09-21
	-- Parte		: S/P Referencia: #1
	-- Description	: Se modifican las condiciones de generación de los insert en spSaleOrder_insertData ahora lo ejecuta
	--				  para las opciones 20, 35 y 50
	-- =======================================================================================================================================
	-- Author		: MOH
	-- Creation Date: 2010-09-21
	-- Parte		: S/P Referencia: #2
	-- Description	: Como se agregaron nuevos parámetros al spSaleOrder_insertData se agregan los valores null para esos
	--				  parámetros, por favor a cualquiera que agregue parámetros a los stores procedures, realizar un análisis de impacto para
	--				  verificar si el sp se está ejecutando desde otro sp y verificar los parámetros si es que se está ejecutando desde
	--				  código servidor de la aplicación
	-- =======================================================================================================================================
	-- Author		: MOH
	-- Creation Date: 2010-10-04
	-- Parte		: S/P Referencia: #3
	-- Description	: Se vuelve a modificar las condiciones de generación de los insert en spSaleOrder_insertData ahora lo ejecuta
	--				  sólo para las opciones 35 y 50
	-- =======================================================================================================================================
	-- Author		: MOH
	-- Creation Date: 2010-10-07
	-- Parte		: S/P Referencia: #4
	-- Description	: Todos los estados ejecutan el mismo código
	-- =======================================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-10-18
	-- Parte		: S/P Referencia: #5
	-- Description	: Si el ssos_id a 200 y el srpt_id es 35 no se deben actualizar los seriales
	-- =================================================================================================================




	-- ---------------------------------------------------
	-- MOS 2-2017: Si es una SUCURSAL DIFERENTE al del DF
	-- Cambia los parametros pasados a los de la sucursal
	-- del DF
	-- ---------------------------------------------------
	IF EXISTS(
				SELECT TOP 1  1
					FROM tbDocumentsFile tdf	WITH (NOLOCK)
					WHERE	tdf.comp_id = @comp_id	AND
							tdf.df_id	= @df_id	AND
							tdf.bra_id  <> @bra_id
			)
		BEGIN
			SELECT @bra_id = tdf.bra_id
				FROM tbDocumentsFile tdf		WITH (NOLOCK)
				WHERE	tdf.comp_id = @comp_id	AND
						tdf.df_id	= @df_id

			SELECT @bra_processingDate = tb.bra_processingDate
				FROM tbBranch	 	 tb			WITH (NOLOCK)
				WHERE	tb.comp_id	= @comp_id AND
						tb.bra_id	= @bra_id

		END

	-- ---------------------------------------------------





	-- ---------------------------------------------------
	-- Si no tiene Prioridad asignada, la asigna ahora.!
	-- ---------------------------------------------------
	IF @tis_priority IS NULL OR @tis_priority = 0
		BEGIN

			EXEC spCounters_getNextValue
					@comp_id,
					@bra_id,
					1,
					@counter_value = @tis_priority OUTPUT

		END
	-- ---------------------------------------------------


	DECLARE @rv							INT





	-- Ref: #4
	--
	--IF  @srpt_id = 35 OR @srpt_id = 50		-- Referencia: #1
	--BEGIN
	--
	--		-- =====================================================================
	--		-- estados a procesar
	--		-- 35	Funciona MAL	- Se cambia por igual mercadería -35
	--		-- 50	Adelanto de Cambio -50
	--		-- =====================================================================
	--			  z
	--
	--		SET @soh_id = -1
	--
	--		-- está opción es para lo que tiene grabado TempItemStock
	--
	--
	--		EXEC spSaleOrder_insertData
	--				@soh_id,						@rmadt_guid,
	--				@comp_id,						@bra_id,
	--				@bra_processingDate,			@bra_processingDate,
	--				@rmadt_ProcNote,				'',
	--				'',								'',
	--				'False',						@intSm_id,
	--				@cust_id,						@intSt_id,
	--				@intDisc_id,					@intDl_id,
	--				NULL,							@bra_processingDate,
	--				NULL,							NULL,
	--				NULL,							0,
	--				@user_id,						'False',
	--				NULL,							@total,
	--				@df_id4CreditNote,				@ssos_id,
	--				@ExchangeToCustomerCurrency,	@customerCurrencyId,
	--				NULL,							NULL,					-- 21-09-2010 - MOH - Ref: #2
	--				@rv								OUTPUT
	--
	--
	--END
	--ELSE
	--BEGIN
	--Ref: #4


			DECLARE @srpt_id_char	VARCHAR(10)
			SET		@srpt_id_char	= CONVERT(VARCHAR(50),@srpt_id)

			SET @soh_id = ISNULL(@soh_id,-1)

			IF	@srpt_id IN (10,20,30,35,40,50,80,90)	-- Referencia: #1
				BEGIN

						-- =====================================================================
						-- estados a procesar
						-- 10	Funciona OK		- Se devuelve la misma mercadería -10
						-- 20	Funciona OK		- Se efectúa Nota de Crédito -20
						-- 30	Funciona MAL	- Se devuelve la misma mercadería -30
						-- 40	Funciona MAL	- Se efectúa Nota de Crédito -40
						-- 60	Funciona MAL	- R.M.A. -60
						-- 70	Funciona OK		- Se devuelve al Depósito -70
						-- =====================================================================


						DECLARE @SOD_Note1			NVARCHAR(100)
						SET		@SOD_Note1 = substring(@rmadt_ProcNote,1,70)


						IF  -- Si hay que ponerlo en un pedido especifico o si hay algun pedido igual abierto, actualizo ese pedido
							@soh_id > 0
							OR
							EXISTS(	SELECT TOP 1  	1
										FROM	tbSaleOrderHeader		tsoh		WITH (NOLOCK)
										INNER JOIN tbDocumentsFile tdf				WITH (NOLOCK)
											ON	tdf.comp_id = tsoh.comp_id AND
												tdf.df_id	= tsoh.df_id
										WHERE	tsoh.comp_id						= @comp_id
										AND		tsoh.cust_id						= @cust_id
										AND		tsoh.st_id							= @intSt_id
										AND		tsoh.bra_id							= @bra_id
										AND		tsoh.sm_id							= @intSm_id
										AND		tsoh.ssos_id						= @ssos_id
										AND		tsoh.df_id							= @df_id
										AND		tsoh.soh_isEditing					= 'False'
										AND	    tsoh.soh_observation2				= @srpt_id_char
										AND		tsoh.soh_ExchangeToCustomerCurrency	= @ExchangeToCustomerCurrency
										-- AND		tdf.df_RMASaleOrderInNewDocument	<> 1		MOS 08-2022 RF
										AND		tdf.df_RMASaleOrderInNewDocument	= 'False'
								)
							BEGIN

								IF  @soh_id <= 0   -- MOS 6-2017, si viene un soh_id informado se pone en este soh, sino ve de agarrar uno nuevo
									BEGIN

										SELECT	@soh_id	= tsoh.soh_id
											FROM	tbSaleOrderHeader		tsoh		WITH (NOLOCK)
											WHERE	tsoh.comp_id						= @comp_id
											AND		tsoh.cust_id						= @cust_id
											AND		tsoh.st_id							= @intSt_id
											AND		tsoh.bra_id							= @bra_id
											AND		tsoh.sm_id							= @intSm_id
											AND		tsoh.ssos_id						= @ssos_id
											AND		tsoh.df_id							= @df_id
											AND		tsoh.soh_isEditing					= 'False'
											AND	    tsoh.soh_observation2				= @srpt_id_char
											AND		tsoh.soh_ExchangeToCustomerCurrency	= @ExchangeToCustomerCurrency

									END

								--si ya existe un pedido con las mismas condiciones que el se intenta generar
								--se actualiza la observacion1 con la variable @rmadt_ProcNote que ahora trae
								--el rmah_id, rmad_id y procnote concatenados
								UPDATE	tbSaleOrderHeader	WITH (ROWLOCK)
									SET		soh_observation1 = substring(ltrim(rtrim(soh_observation1)) +  ' // ' +  @rmadt_ProcNote,1,100)
									WHERE	comp_id =	@comp_id
									AND		bra_id  =   @bra_id
									AND		soh_id	=	@soh_id




							END
						ELSE
							BEGIN

     								-- obtiene el próximo soh_id de la tabla tbCounters, con id 2
									EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @soh_id OUTPUT

									SET @total = CONVERT(DECIMAL(19,6),@rmadt_qty) * @rmadt_originalPrice

									DECLARE @observation NVARCHAR(100)
									SET     @observation = substring(@rmadt_ProcNote,1,100)

									DECLARE @customerNote3 AS NVARCHAR(100) = ''
									DECLARE @customerNote4 AS NVARCHAR(100) = ''
									SELECT	@customerNote3 = tc.cust_note3,
											@customerNote4 = tc.cust_note4
										FROM tbCustomer AS tc		WITH (NOLOCK)
										WHERE	tc.comp_id = @comp_id AND
												tc.cust_id = @cust_id

									EXEC spSaleOrderHeader_insertData
										@comp_id,						@bra_id,
										@soh_id,						@bra_processingDate,
										@bra_processingDate,   			@observation,
										@srpt_id_char ,					@customerNote3 ,
										@customerNote4,					'False' ,
										@intSm_id,						@cust_id,
										@intSt_id,						@intDisc_id,
										@intDl_id,						NULL,
										@bra_processingDate,			NULL,
										NULL,							NULL,
										0,								@user_id,
										'False', 						NULL,
										@total,
										@df_id,
										@ssos_id, 						@ExchangeToCustomerCurrency,
										@customerCurrencyId




									-- ------------------------------------------------------------
									DECLARE @intBranchCurrId			AS INT
									DECLARE @intBranchCurrId4Exchange	AS INT

									SELECT	@intBranchCurrId			= tb.curr_id,
											@intBranchCurrId4Exchange	= tb.curr_id4Exchange
										FROM	tbBranch tb		WITH (NOLOCK)
										WHERE	tb.comp_id	= @comp_id
										AND		tb.bra_id	= @bra_id


									UPDATE tbSaleOrderHeader	WITH (ROWLOCK)
										SET		soh_ATotal	= dbo.fnGetExchange2(	@comp_id,
																					@total,
																					@intBranchCurrId,
																					@intBranchCurrId4Exchange,
																					@intBranchCurrId,
																					@customerCurrencyId,
																					@ExchangeToCustomerCurrency,
																					'False'  )
										WHERE		comp_id	= @comp_id
											AND		bra_id	= @bra_id
											AND		soh_id	= @soh_id
									-- ------------------------------------------------------------


							END

						DECLARE @SOD_Note1Plus AS VARCHAR(100) = @SOD_Note1
						BEGIN TRY
							SET @SOD_Note1Plus = 'RMA:' + CONVERT(VARCHAR(12),@rma_id) + '-' + CONVERT(VARCHAR(12),@rmad_id)	+ ' -> ' + @SOD_Note1
						END TRY
						BEGIN CATCH
						END CATCH


						EXEC spSaleOrderDetail_insertData
							@comp_id,						@bra_id,
							@soh_id, 						@tis_priority,
							@item_id, 						@item_desc,
							 '',     						@rmadt_curr_id,		--MOH  --@ExchangeToCustomerCurrency,
							@rmadt_qty,						@rmadt_qty,
							@prli_id,						@rmadt_originalPrice,
							@stor_id,						@user_id,
							@now,							@tax_id,
							@neto,							@rv OUTPUT,
							@rma_id,						@rmad_id,
							NULL,  							@SOD_Note1Plus,  -- MOS 08-2022: sino manda frurta si cargan descripciones de otro rma. /*@SOD_Note1*/  /*@rmadt_ProcNote*/ ,
							@srpt_id_char ,					NULL,
							NULL, 							NULL


						EXEC spRMA_updateSaleOrder_DeliveryMethod @comp_id, @bra_id, @soh_id, @rv



						-- Recalcula Impuestos
						EXEC spSaleOrder_RecalculateTaxes
							@comp_id ,
							@bra_id,
							@soh_id,
							@user_id ,
							2
						/*
						EXEC spSaleOrder_insertAllData
							@comp_id,
							@bra_id,
							@soh_id,
							@user_id,
							2  --@lang_id
							   --no tenemos en toda la cadena de rma el lang_id, cuando se pueda agregarlo
							   --desde el sprma_insertdata y sprma_updatedata
							   --de cualquier manera en este caso no se utilizaría para nada
							   --sólo retorna un mensaje para mostrar en un mensaje
						*/


				END



	--END



	-- ========================================================================================================
	-- 2010-08-02 - MOH - Parte 420
	-- 2010-08-22 - MOH - Parte 457 - Se agrega la opción 35 para que inserte en tbSaleOrderSerials
	-- 2010-10-18 - MOH - Ref #4 -Se quita la opción 35  para actualización de seriales
	-- ========================================================================================================
	IF @srpt_id IN (10,20,30,40,80,90) AND  @is_id IS NOT NULL
		BEGIN


				-- =====================================================================
				-- estados a procesar
				-- 10	Funciona OK - Se devuelve la misma mercadería -10
				-- 20	Funciona OK - Se efectúa Nota de Crédito -20
				-- 30	Funciona MAL - Se devuelve la misma mercadería -30
				-- 40	Funciona MAL - Se efectúa Nota de Crédito -40
				-- =====================================================================


				-- Esto se pone para que, si un pedido se hace por un concepto, por mas que al principio tuviese
				-- asociado un articulo no se graben los numeros de serie, por ejemplo la opcion 10.!
				IF @item_id IS NOT NULL
					BEGIN
						EXEC	spSaleOrderSerials_insertData
								@comp_id, 		@is_id,
								@bra_id,		@soh_id,
								NULL,			@rv OUTPUT
					END


				-- ====================================================================================================
				-- 2010-08-06 - MOH - Parte 448 -- este update se ejecuta, ya que el spSaleOrderSerials_insertData
				-- anterior deja el soh_isEditing en 'True' y no permite la edición posterior del pedido
				-- ====================================================================================================
				UPDATE 	dbo.tbSaleOrderHeader	WITH (ROWLOCK)
					SET		soh_isEditing	= 'False'
					WHERE   comp_id			= @comp_id
					AND 	bra_id			= @bra_id
					AND 	soh_id			= @soh_id
				-- ====================================================================================================


		END
	-- ========================================================================================================


	SET @intSaleOrderHeaderUpdated = @soh_id -- MOS 06-2017





END


GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE spRMA_updateSaleOrder_deliveryMethod
	@comp_id	AS INT,
	@bra_id		AS INT,
	@soh_id		AS INT,
	@sod_id		AS INT

AS
BEGIN





	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	BEGIN TRY

		DECLARE @sdlmt_id	AS INT = 0

		SELECT	@sdlmt_id			= tdf.sdlmt_id4RMA
			FROM tbSaleOrderHeader				tsoh		WITH (NOLOCK)
			INNER JOIN tbDocumentsFile			tdf			WITH (NOLOCK)
			ON		tdf.comp_id		= tsoh.comp_id	AND
					tdf.df_id		= tsoh.df_id
			WHERE	tsoh.comp_id	= @comp_id		AND
					tsoh.bra_id		= @bra_id		AND
					tsoh.soh_id		= @soh_id


		IF @sdlmt_id > 0
			BEGIN
				UPDATE tbsaleorderdetail	 WITH (ROWLOCK)
					SET		sdlmt_id	= @sdlmt_id
					WHERE	comp_id		= @comp_id AND
							bra_id		= @bra_id AND
							soh_id		= @soh_id AND
							sod_id		= @sod_id
			END

	END TRY
	BEGIN CATCH
	END CATCH





END
GO








CREATE PROCEDURE [dbo].[spRMA_validateCustSupp]
(
	@comp_id			INT,
	@isSupplier			BIT,
	@CustSupp_id		INT,
	@return_value		INT OUTPUT
)
AS
SET NOCOUNT ON


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------
IF EXISTS (	SELECT	1
			FROM	tbRMA_Header trh
			WHERE	trh.comp_id			= @comp_id
			AND 	((@isSupplier = 'true'	AND trh.supp_id = @CustSupp_id)	OR
					 (@isSupplier = 'false'	AND trh.cust_id = @CustSupp_id))
			AND		trh.rmah_isEditing = 'true' )

		SET @return_value = 0
ELSE
		SET @return_value = 1
GO




