CREATE  PROCEDURE [dbo].[spRMADetail_deleteAllData]
(
	@comp_id		INT,
	@rmah_id		INT
)
as

BEGIN

	set nocount on

	/*
	DECLARE @rmah_id		INT,
			@comp_id		int

	SELECT	@rmah_id		= 234,
			@comp_id		= 1
	*/


	DECLARE @bitIsSupplierRMA AS BIT
	SELECT  @bitIsSupplierRMA = CASE
	                                WHEN trh.supp_id IS NOT NULL  THEN	'True'
	                                ELSE								'False'
	                            END
		FROM tbRMA_Header trh
		WHERE	trh.comp_id = @comp_id AND
				trh.rmah_id = @rmah_id



	UPDATE tbsaleorderdetail
			SET rmah_id = NULL,
				rmad_id = NULL
			WHERE	comp_id = comp_id
			AND		rmah_id = @rmah_id
			AND		rmad_id IN (SELECT	rmad_id
		   							FROM tbRMA_Detail trd		WITH (NOLOCK)
									WHERE	trd.comp_id = @comp_id
									AND		trd.rmah_id = @rmah_id )



	-- MOH y la re puta que te re mil pario!!!!!
	-- Solo se va a pertitir borrar si solo tiene 1 detail, sino se grisa el boton
	IF @bitIsSupplierRMA = 'True'
		BEGIN

			DECLARE @intItTransactionOriginal	AS INT
			DECLARE @intItTransactionDestiny	AS INT
			DECLARE @intStorId					AS INT
			DECLARE @decQty						AS DECIMAL(19,4)
			DECLARE @intItemId					AS INT
			DECLARE @decStorePrevious			AS DECIMAL(19,4)

			SELECT  @intItTransactionOriginal	= tit.it_transaction,
					@intStorId					= tit.stor_id,
					@decQty						= tit.it_qty,
					@intItemId					= tit.item_id,
					@decStorePrevious			= IsNull(tis.itst_cant,0)
				FROM	tbItemTransactions tit
				LEFT JOIN tbItemStorage tis
					ON	tis.comp_id = tit.comp_id AND
						tis.stor_id = tit.stor_id AND
						tis.item_id = tit.item_id
				WHERE	tit.comp_id = @comp_id AND
						tit.rmah_id = @rmah_id



			INSERT INTO tbItemTransactions
			(
				comp_id,
				bra_id,
				ct_transaction,
				-- it_transaction -- this column value is auto-generated,
				item_id,
				it_qty,
				it_priceWithOutOthers,
				it_price,
				curr_id,
				it_exchangeToBranchCurrency,
				it_priceOfCost,
				it_priceOfCostPP,
				it_priceOfCostLastPurchase,
				it_priceBOfCost,
				it_priceBOfCostPP,
				it_priceBOfCostLastPurchase,
				it_OriginalPrice,
				it_OriginalPriceCurrency,
				it_exchangeToOriginalPriceCurrency,
				stor_id,
				it_storePrevious,
				prli_id,
				byor_id,
				it_isProduction,
				it_isAssociation,
				it_isAssociationGroup,
				it_cd,
				it_packingInvoicePend,
				it_order,
				so_id,
				it_guarantee,
				it_itemDiscountTotal,
				it_totalDiscountTotal,
				it_CreditInt,
				it_CreditIntPlus,
				puco_id,
				it_poh_bra_id,
				it_poh_id,
				it_soh_id,
				it_sod_id,
				rmah_id,
				rmad_id,
				it_qty_rma,
				it_tis_id_aux,
				it_note1,
				it_note2,
				it_packingInvoiceSelected,
				it_cancelled,
				it_priceB,
				it_isMade,
				it_item_id_origin,
				tmp_tis_id,
				it_packingInvoicePendOriginal,
				it_packingInvoiceSelectedGuid,
				it_transaction_original,
				it_transaction_NoStockDiscount,
				it_SalesCurrId4exchangeToBranchCurrency,
				it_AllUseTag1,
				it_AllUseTag2,
				it_AllUseTag3,
				it_AllUseTag4,
				it_Discount1,
				it_Discount2,
				it_Discount3,
				it_Discount4,
				coslis_id,
				coslis_idB,
				supp_id,
				camp_id,
				it_transaction_originalEW
			)
				SELECT tit.comp_id,
					   tit.bra_id,
					   tit.ct_transaction,
					   tit.item_id,
				       @decQty * -1,
				       tit.it_priceWithOutOthers,
				       tit.it_price,
				       tit.curr_id,
				       tit.it_exchangeToBranchCurrency,
				       tit.it_priceOfCost,
				       tit.it_priceOfCostPP,
				       tit.it_priceOfCostLastPurchase,
				       tit.it_priceBOfCost,
				       tit.it_priceBOfCostPP,
				       tit.it_priceBOfCostLastPurchase,
				       tit.it_OriginalPrice,
				       tit.it_OriginalPriceCurrency,
				       tit.it_exchangeToOriginalPriceCurrency,
				       tit.stor_id,
				 @decStorePrevious,
				       tit.prli_id,
				       tit.byor_id,
				       tit.it_isProduction,
				       tit.it_isAssociation,
				       tit.it_isAssociationGroup,
				       tit.it_cd,
				       tit.it_packingInvoicePend,
				       tit.it_order,
				       tit.so_id,
				       tit.it_guarantee,
				       tit.it_itemDiscountTotal,
				       tit.it_totalDiscountTotal,
				       tit.it_CreditInt,
				       tit.it_CreditIntPlus,
				       tit.puco_id,
				       tit.it_poh_bra_id,
				       tit.it_poh_id,
				       tit.it_soh_id,
				       tit.it_sod_id,
				       tit.rmah_id,
				       tit.rmad_id,
				       tit.it_qty_rma,
				       tit.it_tis_id_aux,
				       tit.it_note1,
				       tit.it_note2,
				       tit.it_packingInvoiceSelected,
				       tit.it_cancelled,
				       tit.it_priceB,
				       tit.it_isMade,
				       tit.it_item_id_origin,
				       tit.tmp_tis_id,
				       tit.it_packingInvoicePendOriginal,
				       tit.it_packingInvoiceSelectedGuid,
				       tit.it_transaction_original,
				       tit.it_transaction_NoStockDiscount,
				       tit.it_SalesCurrId4exchangeToBranchCurrency,
				       tit.it_AllUseTag1,
				       tit.it_AllUseTag2,
				       tit.it_AllUseTag3,
				       tit.it_AllUseTag4,
				       tit.it_Discount1,
				       tit.it_Discount2,
				       tit.it_Discount3,
				       tit.it_Discount4,
				       tit.coslis_id,
				       tit.coslis_idB,
				       tit.supp_id,
				       tit.camp_id,
				       tit.it_transaction_originalEW
					FROM	tbItemTransactions tit
					WHERE	tit.comp_id			= @comp_id					AND
							tit.it_transaction	= @intItTransactionOriginal

					SET @intItTransactionDestiny = @@IDENTITY

					-- Reincorpora el stock al deposito de RMA
					UPDATE tbItemStorage
						SET
								itst_cant = itst_cant + @decQty
						WHERE	comp_id = @comp_id		AND
								stor_id = @intStorId	AND
								item_id = @intItemId

					UPDATE tbitemtransactions
						SET		rmah_id			= NULL,
								rmad_id			= NULL
						WHERE	comp_id			= @comp_id AND
								it_transaction	= @intItTransactionOriginal

					UPDATE tbitemtransactions
						SET		rmah_id			= NULL,
								rmad_id			= NULL
						WHERE	comp_id			= @comp_id AND
								it_transaction	= @intItTransactionDestiny




		END
	ELSE	-- Si es rma CLIENTES lo borra directamente, igual NO deberia haber nada aun. Es lo que habia antes puesto.-
		BEGIN
			DELETE	FROM tbItemTransactions
				WHERE	comp_id = @comp_id	AND
						rmah_id = @rmah_id
		END



	DELETE FROM tbRMA_AddItems
		WHERE	comp_id = @comp_id AND
				rmah_id = @rmah_id


	DELETE FROM tbRMA_Detail_AttributesHistory
		WHERE	comp_id = @comp_id AND
				rmah_id = @rmah_id

	DELETE 	dbo.tbRMA_Detail
		WHERE	comp_id = @comp_id AND
				rmah_id	= @rmah_id

END
GO







CREATE  PROCEDURE [dbo].[spRMADetail_deleteData]
(
		@comp_id			INT,
		@rmad_id			int
)
as

BEGIN

	set nocount on

	Delete	dbo.tbRMA_Detail
		FROM tbRMA_Detail trd	WITH (NOLOCK)
		where	trd.comp_id = @comp_id AND
				trd.rmad_id	= @rmad_id AND
				NOT EXISTS(
							SELECT TOP 1  1
								FROM tbItemTransactions tit	WITH (NOLOCK)
								WHERE	tit.comp_id = trd.comp_id AND
										tit.rmah_id = trd.rmah_id AND
										tit.rmad_id = trd.rmad_id
						  )

END
GO







