CREATE PROCEDURE [dbo].[spRMADetail_GetDataById]
(
    @comp_id		as  int,
	@bra_id			as	INT,
	@rmad_id		as	INT

)
AS

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	set nocount on


		select	rmad.*,
				c.cust_name,
				b.bra_desc,
				ISNULL(rmad.rmad_up2Price,0)		[rmad_up2Price]

		from	dbo.tbRMA_Detail					rmad

				left join dbo.tbCustomer			c
				on	c.comp_id			=	rmad.comp_id

				left join dbo.tbBranch				b
				on	b.comp_id			=	rmad.comp_id
				and	b.bra_id			=	rmad.bra_id

				left join dbo.tbItemTransactionSerials tits
				ON tits.comp_id			= rmad.comp_id
				AND tits.it_transaction	= rmad.it_transaction

				left join dbo.tbItemSerials			tis
				ON tis.comp_id			= tits.comp_id
				AND tis.is_id			= tits.is_id


		where	rmad.comp_id		= @comp_id
			and rmad.bra_id			= @bra_id
			and rmad.rmad_id		= @rmad_id






GO







