		@rmad_originalPrice		decimal(19,6),
		@curr_id				int,
		@rmad_qty				decimal(19,5),
		@user_id_Reception		int,
		@rmad_ReceptionNote		VARCHAR(8000),
		@is_id					INT,
		@user_id_Diagnostic     INT,
