		@user_id_Delivery		INT,
		@return_value			INT OUTPUT
)
AS


Insert Into dbo.tbRMA_Detail		WITH (ROWLOCK)
	(
		comp_id,
		rmah_id,
		bra_id,
		it_transaction,
		item_id,
		stor_id,
		rmad_Manual,
		rmad_originalPrice,
		curr_id,
		rmad_qty,
		user_id_Reception,
		rmad_Date_Reception,
		rmad_ReceptionNote,
		is_id,
		user_id_Diagnostic,
		rmad_Date_Diagnostic,
		rmad_DiagnosticNote	,
		df_id4CreditNote,
		srpt_id	,
		rmad_ProcNote,
		rmad_isNewItem,
		supp_id,
		impData_Custom_local,
		impData_Number_local,
		rmas_id,
		rmap_id,
		item_id4Replacement,
		rmaw_id,
		rmamt_id,
		user_id_Proc,
		user_id_Delivery
	)

	Values
	(
		@comp_id,
		@rmah_id,
		@bra_id,
		@it_transaction,
		@item_id,
		@stor_id,
		@rmad_Manual,
		@rmad_originalPrice,
		@curr_id,
		@rmad_qty,
		@user_id_Reception,
		GETDATE	(),
		@rmad_ReceptionNote,
		@is_id,
		@user_id_Diagnostic,
		@rmad_Date_Diagnostic,
		@rmad_DiagnosticNote,
		@df_id4CreditNote,
		@srpt_id,
		@rmad_ProcNote,
		@rmad_isNewItem,
		@supp_id,
		@impData_Custom_local,
		@impData_Number_local,
		@rmas_id,
		@rmap_id,
		@item_id4Replacement,
		@rmaw_id,
		@rmamt_id,
		@user_id_Proc,
		@user_id_Delivery
	)


	set	@return_value = @@identity






GO







