CREATE PROCEDURE [dbo].[spRMADetail_validateItemQtyOnStorBad]
(
	@comp_id			INT,
	@bra_id				INT,
	@item_id			INT,
	@serial				VARCHAR(100),
	@item_qty			DECIMAL(18,5),
	@return_value		INT OUTPUT
)
AS

BEGIN



	SET NOCOUNT ON

-- ---------------------------------------------------------
-- Testing
-- ---------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@bra_id				INT,
			@item_id			INT,
			@serial				VARCHAR(100),
			@item_qty			DECIMAL(18,5),
			@return_value		INT
	SELECT	@comp_id			=1,
			@bra_id				=1,
			@item_id			=-1,
			@serial				='V09300G10400510',
			@item_qty			=1
	*/
-- ---------------------------------------------------------


	SET		@return_value = 0

	declare @intStorId4Bad AS INT
	SELECT	@intStorId4Bad = tb.bra_RMA_storId4Bad
		FROM	tbBranch	tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
		AND		tb.bra_id	= @bra_id


	IF @item_id > 0 OR len(@serial) > 0
		BEGIN

			-- Obtengo el item_id a partir del Numero de serie
			IF @item_id = -1 AND len(@serial) > 0
			BEGIN
				SELECT	@item_id		= tis.item_id
					FROM	tbItemSerials						tis		WITH (NOLOCK)
					WHERE	tis.comp_id		= @comp_id
					AND		tis.is_serial	= @serial

			END



			SELECT	@return_value = 1
				FROM	tbItemStorage					tis		WITH (NOLOCK)
				WHERE	tis.comp_id		=	@comp_id
				AND		tis.stor_id		=   @intStorId4Bad
				AND		tis.item_id		=	@item_id
				AND		tis.itst_cant	>=	@item_qty

		END
	ELSE	-- Es item manual y retorna True
		SELECT	@return_value = 1


END
GO


--IMPORTANTE
--SI SE AGREGA ALGUN PARAMETRO ACA, TAMBIEN AGREGARLO EN spRMADetail_validateSerialFromSupplier
--YA QUE DESDE VISUAL COMPARTEN EL MISMO METODO

CREATE PROCEDURE [dbo].[spRMADetail_validateSerialFromCustomer]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@cust_id				INT,
	@serial					VARCHAR(100),
	@guid					UNIQUEIDENTIFIER,
	@prof_id				INT,
	@return_value			INT OUTPUT
)
AS


BEGIN

	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-08-02
	-- Parte		: 420
	-- Description	: Para cumplir el requerimiento solicitado, verificar que cuando se está cargando un número de serie
	--				  en un RMA, no esté en tbSaleOrderSerials, tbSaleOrderDetail y tbTempItemStock
	-- =================================================================================================================




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- -------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@cust_id			INT,
			@serial				VARCHAR(100),
			@guid				UNIQUEIDENTIFIER,
			@prof_id			INT,
			@return_value		INT
	SELECT	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@cust_id			=24300,
			@serial				='',
			@guid				='6bcf992b-0589-44b6-a329-224d0a4b2791',
			@prof_id			= 1
	*/
	-- -------------------------------------------------------------------------







	-- MOS 04-2022: Esto es MAS QUE MIERDA, el que lo hizo fue un RHDRMP y se sigui con la misma politica.  OJO al tocar algo, esto es TODO MIERDA.
	-- Esto es todo MIERDA, deberia rehacerse ya que se hacen las preguntas arriba y luego abajo se vuelven a hacer con los mens de error.
	-- Esto es MIERDA, se debe poner el return dentro del IUF de cada pregunta.
	-- POr eso daba esos errores del 999 y 998, porque es todo MIERDA y la busqueda DUPLICADA del error de abajo estaba armada DIFERENTE de la puta busqueda de arriba.
	-- Ver en el de supplier


	--IF dbo.fnStrAllTrim(@serial) = ''
	--	BEGIN
	--		SET @return_value = 1
	--		SELECT '001-Todo OK'
	--		RETURN
	--	END




	DECLARE @bitEnableSerialFromOtherERPCheck AS BIT = 'False'
	IF EXISTS (	SELECT TOP 1  1
					FROM tbControlProfiles tcp1	WITH(NOLOCK)
					WHERE	tcp1.comp_id	= @comp_id	AND
							tcp1.bra_id		= @bra_id	AND
							tcp1.prof_id	= @prof_id	AND
							tcp1.page_id	= 80000		AND
							tcp1.ctrl_id	= 6282)
		BEGIN
			SET @bitEnableSerialFromOtherERPCheck = 'True'
		END


	DECLARE @bitDisableThisCheck AS BIT = 'False'
	IF EXISTS (SELECT TOP 1  1
				FROM tbControlProfiles tcp1	WITH(NOLOCK)
				WHERE	tcp1.comp_id	= @comp_id	AND
						tcp1.bra_id		= @bra_id	AND
						tcp1.prof_id	= @prof_id	AND
						tcp1.page_id	= 80000		AND
						tcp1.ctrl_id	= 5718)
		BEGIN
			SET @bitDisableThisCheck = 'True'
		END


	SET @return_value = 0


	IF EXISTS	(

				--valida que exista el nro de serie	++++
				SELECT TOP 1 	1
					FROM	tbItemTransactionSerials					tits		WITH (NOLOCK)
							INNER JOIN tbItemSerials					tis			WITH (NOLOCK)
							ON	tis.comp_id			=	tits.comp_id
							AND tis.is_id			=	tits.is_id
							INNER JOIN tbCommercialTransactions			tct			WITH (NOLOCK)
							ON	tct.comp_id			=	tits.comp_id		AND
								tct.ct_transaction	=	tits.ct_transaction
							--AND tct.bra_id			=	tits.bra_id

					WHERE	tits.comp_id			=	@comp_id
					AND		tis.is_serial			=	@serial
					AND		tct.cust_id				=	@cust_id


				--valida que el serial no esté ingresado en el mismo RMA	++++
				AND		tis.is_id	NOT IN (SELECT	TOP 1	trdt.is_id
												FROM	tbRMA_Detail_Tmp				trdt		WITH (NOLOCK)
												WHERE	trdt.comp_id		=	tis.comp_id
												AND		trdt.rmadt_guid		=	@guid
												AND		trdt.is_id			=	tis.is_id)


				--valida que el serial no esté ingresado en otro RMA que se esté cargando en el mismo momento	++++
				AND		tis.is_id	NOT IN (SELECT  TOP 1	trdt.is_id
												FROM	tbRMA_Detail_Tmp				trdt		WITH (NOLOCK)
												WHERE	trdt.comp_id		=	tis.comp_id
												AND		trdt.rmadt_guid		<>	@guid
												AND		trdt.is_id			=	tis.is_id)


				--valida que el serial no esté ingresado en otro RMA y que su estado sea 30 o 35   ++++++
				AND	(
						@bitDisableThisCheck = 'True'
							OR
						tis.is_id	NOT IN (SELECT	TOP 1	trd.is_id
			   		             				FROM	tbRMA_Detail					trd		WITH (NOLOCK)
			   		             						INNER JOIN tbRMA_Header			trh		WITH (NOLOCK)
			   		             						ON	trh.comp_id		=	trd.comp_id
			   		             						AND trh.rmah_id		=	trd.rmah_id
			   		             						AND NOT trh.cust_id		IS NULL
			   		             				WHERE	trd.comp_id			=	tis.comp_id
												AND		trd.is_id			=	tis.is_id
												AND		trd.srpt_id			IN	(30,35))
					)
				--valida que el serial no esté ingresado en otro RMA y que su estado sea 1 = SIN PROCESAR
				AND		tis.is_id	NOT IN (SELECT	TOP 1   trd.is_id
			   		             				FROM	tbRMA_Detail					trd		WITH (NOLOCK)
			   		             						INNER JOIN tbRMA_Header			trh		WITH (NOLOCK)
			   		             						ON	trh.comp_id		=	trd.comp_id
			   		             						AND trh.rmah_id		=	trd.rmah_id
			   		             						AND NOT trh.cust_id		IS NULL
			   		             				WHERE	trd.comp_id			=	tis.comp_id
												AND		trd.is_id			=	tis.is_id
												AND		trd.srpt_id			=   1)


				-- =============================================================================================
				-- == 2010-08-02 - MOH - Parte 420
				-- =============================================================================================
				--valida que el id del serial ingresado no haya sido ingresado en algún pedido	++++
				AND		tis.is_id		NOT IN (SELECT	TOP 1	tsos.is_id
   													FROM	tbSaleOrderSerials				tsos		WITH (NOLOCK)
													WHERE	tsos.comp_id	= tis.comp_id	AND
													--AND		tsos.bra_id		= tis.bra_id	MOS 03-2017
															NOT tsos.is_id IS NULL )

				--valida que el id del serial ingresado no haya sido ingresado en algún pedido	++++
				AND		tis.is_id		NOT IN (SELECT	TOP 1	tsod.is_id
													FROM	tbSaleOrderDetail				tsod		WITH (NOLOCK)
			   		         						WHERE 	tsod.comp_id	= tis.comp_id	AND
													--AND		tsod.bra_id		= tis.bra_id  MOS 03-2017
															NOT tsod.is_id IS NULL )

				--valida que el id del serial no se esté ingresando en algún pedido	++++
				AND		tis.is_id		NOT IN (SELECT	TOP 1	ttis.is_id
													FROM	tbTempItemStock					ttis		WITH (NOLOCK)
													WHERE	ttis.comp_id	= tis.comp_id	AND
															NOT ttis.is_id IS NULL )
				-- =============================================================================================


				)

		BEGIN

			--Pasaron todas la validaciones correctamente

			--se agrega una nueva validación: Cuando dan de alta x numero de serie,	que la venta sea de la suc actual
			--si el campo de branch.bra_RMA_EnableAllBranchs es 'FALSE'
			IF EXISTS (
						SELECT	TOP 1 1
							FROM	tbItemTransactionSerials tits		WITH (NOLOCK)
									INNER JOIN tbItemSerials tis		WITH (NOLOCK)
									ON	tis.comp_id		= tits.comp_id
									AND tis.is_id		= tits.is_id
							WHERE	tits.comp_id	= @comp_id
							AND		tis.is_serial	= @serial
							AND		(
										('true'	=  (SELECT	isnull(tb1.bra_RMA_EnableAllBranchs,'false')
														FROM	tbBranch tb1		WITH (NOLOCK)
														WHERE	tb1.comp_id		= @comp_id
														AND		tb1.bra_id		= @bra_id))
										OR
										(tits.bra_id = @bra_id)
									)
					  )
				BEGIN

					--pasaron todas las validaciones y se actualiza el serial correspondiente
					SET @return_value = 1
					EXEC spItemTransactionSerials_getDataBySerials  @comp_id, @cust_id, @serial,@prof_id,@bra_id
					RETURN

				END

			ELSE

				BEGIN

					SET @return_value = 0
					--devolución de datos para el caso en que la sucursal de venta sea diferente de la activa y el campo
					-- tbbranch.bra_RMA_EnableAllBranchs es 'true'
					SELECT	tut.utexts_desc
						FROM	tbsysUniqueTexts tut			WITH (NOLOCK)
						WHERE	tut.lang_id		= @lang_id
						AND		tut.utexts_id	= 128
					RETURN

				END

		END

	ELSE ------

		BEGIN


			DECLARE @cust_isAvailable4InternalRMA AS BIT
			SELECT  @cust_isAvailable4InternalRMA = isnull(tc.cust_isAvailable4InternalRMA,'False')
				FROM tbCustomer tc							WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @cust_id


			-- ---------------------------------------------------------------------------------------
			-- Si es cliente para RMA de uso interno y existe el numero de serie x compras . . .
			-- ---------------------------------------------------------------------------------------
			IF @cust_isAvailable4InternalRMA = 'True'
				BEGIN
					IF 	EXISTS (	SELECT	TOP 1 1
										FROM	tbItemSerials							tis		WITH (NOLOCK)
										WHERE	tis.comp_id				= @comp_id
										AND		tis.is_serial			= @serial	)
						BEGIN
							SET @return_value = 1
							EXEC spItemTransactionSerials_getDataBySerials4RMAInternalCustomer  @comp_id,@bra_id, @cust_id, @serial
							RETURN
						END
				END
			-- ---------------------------------------------------------------------------------------






			SET @return_value = 0



			IF @bitEnableSerialFromOtherERPCheck = 'True'
				BEGIN
					-- Verifica si el Numero de Serie es de Otro ERP
					-- MOS 04-2022: Security One
					DECLARE @isfo_id AS INT = NULL
					SELECT TOP 1  @isfo_id = tisfoe.isfo_id
						FROM tbItemSerialsFromOtherERP AS tisfoe WITH (NOLOCK)
						WHERE tisfoe.isfo_serial = @serial
						ORDER BY tisfoe.isfo_id DESC
					IF @isfo_id IS NOT NULL
						BEGIN

							SELECT TOP 1
									tut.utexts_desc + ' ' +
									'(' + CONVERT(NVARCHAR(10),tc.cust_id) + ')' +
									tc.cust_name + ' <br/>' +
									ti.item_code + ' -> ' + ti.item_desc + ' -> ' + CONVERT(NVARCHAR(20),titfoe.ith_qty) + ' -> ' +
								   '$:' + CONVERT(NVARCHAR(20),titfoe.ith_pricePlusTax) + ' <br/>' +
								   td.sd_desc + ' ' + titfoe.ith_kindOf + ' ' + CONVERT(NVARCHAR(10),titfoe.ith_poitOfSale) + ' ' +  titfoe.ith_docNumber + ' -> ' +
								   CONVERT(NVARCHAR(30),titfoe.ith_date,101) + ' <br/>' +
								   titfoe.ith_desc	 + '<br/>' + '*136*'										[utexts_desc],
								   136																			[error_code],
								   ti.item_id,
								   ti.item_code,
								   @serial																		[serial],
								   ti.item_desc,
								   ISNULL(titfoe.ith_priceNoTax,0)												[ith_priceNoTax]
								FROM tbItemTransactionsFromOtherERP AS titfoe	WITH (NOLOCK)
								INNER JOIN tbsysDocuments		AS td	WITH (NOLOCK)
									ON td.sd_id = titfoe.sd_id
								INNER JOIN tbCustomer			AS tc	WITH (NOLOCK)
									ON	tc.cust_id = titfoe.cust_id AND
										tc.comp_id = titfoe.comp_id
								INNER JOIN tbItem				AS ti	WITH (NOLOCK)
									ON	ti.comp_id = titfoe.comp_id AND
										ti.item_id = titfoe.item_id
								INNER JOIN tbsysUniqueTexts		AS tut	WITH (NOLOCK)
									ON tut.lang_id = @lang_id AND tut.utexts_id = 136
								WHERE titfoe.isfo_id = @isfo_id
								ORDER BY titfoe.ith_id DESC

								RETURN
						END
				END







			IF NOT EXISTS (	SELECT	TOP 1 1
								FROM	tbItemSerials							tis		WITH (NOLOCK)
								WHERE	tis.comp_id				= @comp_id
								AND		tis.is_serial			= @serial	)
				BEGIN

					--devolución de datos para el caso en que no exista el serial
					-- Nº de Serie inexistente
					-- ATENCIÓN: ¡ El Número de Serie NO EXISTE !
					SELECT	tut.utexts_desc
						FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
						WHERE	tut.lang_id		= @lang_id
						AND		tut.utexts_id	= 121
					RETURN

				END

			ELSE

				BEGIN
					--ESTO SE HACE PARA DATASOFT, SI UN RMA YA FUE PROCESADO POR 30 o 35 Y ESTE HA SIDO DEVUELVO POR EL PROVEEDOR
					--Y EL MISMO ARTICULO SE VUELVE A VENDER A OTRA PERSONA Y FALLA, NO SE PODIA VOLVER A CARGAR UN SEGUNDO RMA CLIENTE
					--PORQUE YA ESE NUMERO DE SERIE HABIA SIDO PROCESADO EN OTRO RMA POR CUALQUIERA DE ESTOS DOS TIPOS



					IF
						EXISTS (	SELECT		TOP 1 trd.rmad_Manual
     									FROM	tbRMA_Detail		trd					WITH (NOLOCK)
     											INNER JOIN tbRMA_Header			trh		WITH (NOLOCK)
     											ON	trh.comp_id		=	trd.comp_id
     											AND trh.rmah_id		=	trd.rmah_id
     											AND NOT trh.cust_id		IS NULL
     									WHERE	trd.comp_id			=	@comp_id
										AND		trd.rmad_Manual		=	@serial
										AND		trd.srpt_id			IN (30,35))

						BEGIN

							DECLARE @text VARCHAR(500)
							SELECT	@text = tut.utexts_desc
								FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
								WHERE	tut.lang_id		= @lang_id
								AND		tut.utexts_id	= 122


							--devolución de datos para el caso en que exista el serial en otro RMA anterior
							SELECT	dbo.[fnSplitPosition](@text,'|',1) + convert(varchar,trh.rmah_id)			+ '  -  ' +
									dbo.[fnSplitPosition](@text,'|',2) + convert(VARCHAR(12),trh.rmah_cd,103)	+ '  -  ' +
									dbo.[fnSplitPosition](@text,'|',3) + tc.cust_name							+ '  -  ' +
									dbo.[fnSplitPosition](@text,'|',4) + trt.srpt_desc
								FROM	tbRMA_Detail						trd		WITH (NOLOCK)
										INNER JOIN tbRMA_Header				trh		WITH (NOLOCK)
										ON	trh.rmah_id		=	trd.rmah_id
										AND trh.comp_id		=	trd.comp_id
										AND NOT trh.cust_id		IS NULL
										LEFT JOIN tbCustomer				tc		WITH (NOLOCK)
										ON tc.comp_id		=	trh.comp_id
										AND tc.cust_id		=	trh.cust_id
										LEFT JOIN tbsysRMAProcType			trt		WITH (NOLOCK)
										ON trt.srpt_id		=	trd.srpt_id
								WHERE	trd.comp_id			=	@comp_id
								AND		trd.rmad_Manual		=	@serial
								AND		trd.srpt_id			IN	(30,35)

							RETURN

						END

					ELSE

						BEGIN
							-- Si justo se esta cargando el mismo serie en otro rma
							IF
								EXISTS (	SELECT	TOP 1 1
												FROM	tbRMA_Detail_Tmp	trdt		WITH (NOLOCK)
												WHERE	trdt.comp_id		= @comp_id
												AND		trdt.rmadt_guid		= @guid
												AND		trdt.rmadt_Manual	= @serial)
								BEGIN

									--devolución de datos para el caso en que exista en el mismo RMA que se está cargando
									SELECT	tut.utexts_desc
										FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
										WHERE	tut.lang_id		= @lang_id
										AND		tut.utexts_id	= 120
									RETURN

								END

							ELSE

								BEGIN

									IF
										EXISTS (	SELECT	TOP 1 1
													FROM	tbRMA_Detail_Tmp	trdt		WITH (NOLOCK)
													WHERE	trdt.comp_id		= @comp_id
													AND		trdt.rmadt_guid		<> @guid
													AND		trdt.rmadt_Manual	= @serial)
										BEGIN

											--devolución de datos para el caso en que exista en otro RMA que se esté cargando
											SELECT	tut.utexts_desc + ' ' + tu.user_lastname + ', ' + tu.user_firstname
												FROM	tbRMA_Detail_Tmp				trdt		WITH (NOLOCK)
														INNER JOIN tbUser				tu			WITH (NOLOCK)
														ON	tu.[user_id]	= trdt.user_id_Reception
														INNER JOIN tbsysUniqueTexts		tut			WITH (NOLOCK)
														on	tut.lang_id		= @lang_id
														AND	tut.utexts_id	= 124
												WHERE	trdt.comp_id		= @comp_id
												AND		trdt.rmadt_guid		<> @guid
												AND		trdt.rmadt_Manual	= @serial
											RETURN

										END

									ELSE

										BEGIN
											IF
												NOT EXISTS (	SELECT	TOP 1 1
																FROM	tbItemTransactionSerials					tits		WITH (NOLOCK)
																		INNER JOIN tbItemSerials					tis			WITH (NOLOCK)
																		ON	tis.comp_id			=	tits.comp_id
																		AND tis.is_id			=	tits.is_id
																		INNER JOIN tbCommercialTransactions			tct			WITH (NOLOCK)
																		ON	tct.comp_id			=	tits.comp_id		AND
																			tct.ct_transaction	=	tits.ct_transaction
																		--AND tct.bra_id			=	tits.bra_id

																WHERE	tits.comp_id			=	@comp_id
																AND		tis.is_serial			=	@serial
																AND		tct.cust_id				=	@cust_id)
												BEGIN

													--datos incongruentes entre tbItemsSerials y tbItemTransactions
													SELECT	tut.utexts_desc
														FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
														WHERE	tut.lang_id		= @lang_id
														AND		tut.utexts_id	= 126
													RETURN
												END

											ELSE

												BEGIN

													-- =============================================================================================
													-- == 2010-08-02 - MOH - Parte 420
													-- =============================================================================================
													IF	EXISTS (SELECT	TOP 1 1
																	FROM	tbItemSerials						tis		WITH (NOLOCK)
																			INNER JOIN tbSaleOrderSerials		tsos	WITH (NOLOCK)
																			ON	tsos.comp_id	= tis.comp_id
																			AND tsos.is_id		= tis.is_id
																	WHERE	tis.comp_id			= @comp_id
																	AND		tis.is_serial		= @serial ) OR
														EXISTS (SELECT	TOP 1 1
																	FROM	tbItemSerials						tis		WITH (NOLOCK)
																			INNER JOIN tbSaleOrderDetail		tsod	WITH (NOLOCK)
																			ON	tsod.comp_id	= tis.comp_id
																			--AND tsod.bra_id		= tis.bra_id	-- MOS 03-2017
																			AND tsod.is_id		= tis.is_id
																	WHERE	tis.comp_id			= @comp_id
																	AND		tis.is_serial		= @serial ) OR
														EXISTS (SELECT	TOP 1 1
																	FROM	tbItemSerials						tis		WITH (NOLOCK)
																			INNER JOIN tbTempItemStock			ttis	WITH (NOLOCK)
																			ON	ttis.comp_id	= tis.comp_id
																			AND ttis.is_id		= tis.is_id
																	WHERE	tis.comp_id			= @comp_id
																	AND		tis.is_serial		= @serial )
														BEGIN

															--El número de serie ingresado se encuentra tomado en algún Pedido
															SELECT	tut.utexts_desc
																FROM	tbsysUniqueTexts tut						WITH (NOLOCK)
																WHERE	tut.lang_id		= @lang_id
																AND		tut.utexts_id	= 127
															RETURN
														END
													ELSE
														BEGIN
															IF EXISTS(
																		SELECT TOP 1 1
																			FROM tbRMA_Detail_Tmp trdt				WITH (NOLOCK)
																				INNER JOIN tbItemSerials tis		WITH (NOLOCK)
																				ON	tis.comp_id = trdt.comp_id AND
																					tis.is_id	= trdt.is_id
																				WHERE	tis.comp_id		= @comp_id AND
																						tis.is_serial	= @serial
															)
															OR
																EXISTS(
																		SELECT TOP 1 1
																			FROM tbRMA_Detail				trd				WITH (NOLOCK)
																				INNER JOIN tbItemSerials	tis		WITH (NOLOCK)
																				ON	tis.comp_id = trd.comp_id AND
																					tis.is_id	= trd.is_id
																				WHERE	tis.comp_id		= @comp_id	AND
																						tis.is_serial	= @serial	AND
																						trd.srpt_id		= 1
																	  )

																BEGIN
																	--El número de serie ingresado se encuentra siendo tomado en un Alta de RMA como Número de Serie ( No Manual )
																	SELECT	tut.utexts_desc
																		FROM	tbsysUniqueTexts tut						WITH (NOLOCK)
																		WHERE	tut.lang_id		= @lang_id
																		AND		tut.utexts_id	= 566
																	RETURN
																END
															ELSE
																BEGIN
																	SELECT '998-XXX (Por favor, Reintentar en unos minutos)'
																END

														END
													-- =============================================================================================


												END

										END

								END

						END
				END
		END

	SELECT '999-XXX (Not Found, Try again)'

END
GO



--IMPORTANTE
--SI SE AGREGA ALGUN PARAMETRO ACA, TAMBIEN AGREGARLO EN spRMADetail_validateSerialFromCustomer
--YA QUE DESDE VISUAL COMPARTEN EL MISMO METODO
CREATE PROCEDURE [dbo].[spRMADetail_validateSerialFromSupplier]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@cust_id			INT,
	@serial				VARCHAR(100),
	@guid				UNIQUEIDENTIFIER,
	@prof_id			INT,
	@return_value		INT OUTPUT
)
AS

BEGIN


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@serial				VARCHAR(100),
			@guid				UNIQUEIDENTIFIER,
			@return_value		INT
	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@serial				= '820001',
			@guid				= 'D4082C8D-9E15-44B8-9539-B990AC633036'
	*/
	-- -----------------------------------------------------------------------

	DECLARE @is_id AS INT = NULL
	SELECT		@is_id = tis.is_id
		FROM	tbItemSerials	tis				WITH (NOLOCK)
		WHERE	tis.comp_id				= @comp_id	AND
				tis.is_serial			= @serial



	IF EXISTS	(

				--valida que exista el nro de serie
				SELECT	TOP 1 1
					FROM	tbItemSerials							tis		WITH (NOLOCK)
					WHERE	tis.comp_id				= @comp_id
					AND		tis.is_serial			= @serial

					--valida que el serial no esté ingresado en el mismo RMA
					AND		tis.is_id	NOT IN (SELECT	TOP 1 trdt.is_id
													FROM	tbRMA_Detail_Tmp	trdt
													WHERE	trdt.comp_id		= tis.comp_id
													AND		trdt.rmadt_guid		= @guid
													AND		trdt.is_id	= tis.is_id)

					--valida que el serial no esté ingresado en otro RMA que se esté cargando en el mismo momento
					AND		tis.is_id	NOT IN (SELECT	TOP 1 trdt.is_id
													FROM	tbRMA_Detail_Tmp	trdt
													WHERE	trdt.comp_id		= tis.comp_id
													AND		trdt.rmadt_guid		<> @guid
													AND		trdt.is_id	= tis.is_id)

				--valida que el serial no esté ingresado en otro RMA y que su estado sea 30 o 35
				/*AND		tis.is_serial	NOT IN (SELECT	trd.rmad_Manual
			   		             				FROM	tbRMA_Detail					trd
			   		             						INNER JOIN tbRMA_Header			trh
			   		             						ON	trh.comp_id		=	trd.comp_id
			   		             						AND trh.rmah_id		=	trd.rmah_id
			   		             						AND NOT trh.cust_id		IS NULL
			   		             				WHERE	trd.comp_id			=	tis.comp_id
												AND		trd.rmad_Manual		=	tis.is_serial
												AND		trd.srpt_id			IN (30,35))*/
				)

	BEGIN

		SET @return_value = 1

		declare @itemserial AS TABLE (	item_code			NVARCHAR(50),
										item_desc			NVARCHAR(300),
										is_id				INT,
										it_price			DECIMAL(19,5),
										curr_id				int,
										stor_id				int,
										bra_id				int,
										item_id				int,
										it_transaction		int,
										is_available		bit,
										stor_serial			INT,
										stor_desc			nvarchar(50),
										ct_date				datetime,
										aditional_data		NVARCHAR(1000)
									)

		INSERT INTO @itemserial (item_code,
										item_desc,
										is_id,
										it_price,
										curr_id,
										stor_id,
										bra_id,
										item_id,
										it_transaction,
										is_available,
										stor_serial,
										stor_desc,
										ct_date,
										aditional_data)
		EXEC spItemSerials_getDataBySerials	@comp_id, @serial





		IF @@ROWCOUNT = 0
		BEGIN

			SET @return_value = 0

			DECLARE @item_code NVARCHAR(50),
					@item_desc NVARCHAR(500)

			SELECT	@item_code = ti2.item_code,
					@item_desc = ti2.item_desc

			FROM	tbItemSerials tis		WITH (NOLOCK)

					INNER JOIN tbItem ti2		WITH (NOLOCK)
					ON	tis.comp_id = ti2.comp_id
					AND tis.item_id = ti2.item_id

			WHERE	tis.comp_id		= @comp_id
			AND		tis.is_serial	= @serial


			SELECT	tut.utexts_desc + @item_code + ':' + @item_desc
			FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
			WHERE	tut.lang_id		= @lang_id
			AND		tut.utexts_id	= 119

		END
		ELSE
		BEGIN


			SELECT	*
			FROM	@itemserial


		END

	END

	ELSE

	BEGIN

		SET @return_value = 0


		IF NOT EXISTS (	SELECT	TOP 1 1
						FROM	tbItemSerials							tis		WITH (NOLOCK)
						WHERE	tis.comp_id				= @comp_id
						AND		tis.is_serial			= @serial	)
			BEGIN

				--devolución de datos para el caso en que no exista el serial
				SELECT	tut.utexts_desc
				FROM	tbsysUniqueTexts tut
				WHERE	tut.lang_id		= @lang_id
				AND		tut.utexts_id	= 121

			END

		ELSE

			BEGIN

		--		IF EXISTS (SELECT	trd.rmad_Manual
		--     				FROM	tbRMA_Detail		trd
		--     						INNER JOIN tbRMA_Header			trh
		--     						ON	trh.comp_id		=	trd.comp_id
		--     						AND trh.rmah_id		=	trd.rmah_id
		--     						AND NOT trh.cust_id		IS NULL
		--     				WHERE	trd.comp_id			=	@comp_id
		--					AND		trd.rmad_Manual		=	@serial
		--					AND		trd.srpt_id			IN (30,35))
		--		BEGIN
		--
		--			DECLARE @text VARCHAR(500)
		--			SELECT	@text = tut.utexts_desc
		--			FROM	tbsysUniqueTexts tut
		--			WHERE	tut.lang_id		= @lang_id
		--			AND		tut.utexts_id	= 122
		--
		--
		--			--devolución de datos para el caso en que exista el serial en otro RMA anterior
		--			SELECT	dbo.[fnSplitPosition](@text,'|',1) + convert(varchar,trh.rmah_id)			+ '  -  ' +
		--					dbo.[fnSplitPosition](@text,'|',2) + convert(VARCHAR(12),trh.rmah_cd,103)	+ '  -  ' +
		--					dbo.[fnSplitPosition](@text,'|',3) + tc.cust_name							+ '  -  ' +
		--					dbo.[fnSplitPosition](@text,'|',4) + trt.srpt_desc
		--			FROM	tbRMA_Detail						trd
		--					INNER JOIN tbRMA_Header				trh
		--					ON	trh.rmah_id		=	trd.rmah_id
		--					AND trh.comp_id		=	trd.comp_id
		--					AND NOT trh.cust_id		IS NULL
		--					LEFT JOIN tbCustomer				tc
		--					ON tc.comp_id		=	trh.comp_id
		--					AND tc.cust_id		=	trh.cust_id
		--					LEFT JOIN tbsysRMAProcType			trt
		--					ON trt.srpt_id		=	trd.srpt_id
		--			WHERE	trd.comp_id			=	@comp_id
		--			AND		trd.rmad_Manual		=	@serial
		--			AND		trd.srpt_id			IN	(30,35)
		--
		--		END
		--
		--		ELSE
		--
		--		BEGIN

					IF EXISTS (SELECT	TOP 1 1
								FROM	tbRMA_Detail_Tmp	trdt		WITH (NOLOCK)
								WHERE	trdt.comp_id		= @comp_id
								AND		trdt.rmadt_guid		= @guid
								AND		trdt.is_id			= @is_id)
						BEGIN

							--devolución de datos para el caso en que exista en el mismo RMA que se está cargando
							SELECT	tut.utexts_desc
								FROM	tbsysUniqueTexts tut			WITH (NOLOCK)
								WHERE	tut.lang_id		= @lang_id
								AND		tut.utexts_id	= 120

						END

					ELSE

						BEGIN

							IF EXISTS (SELECT	TOP 1 1
									FROM	tbRMA_Detail_Tmp	trdt			WITH (NOLOCK)
									WHERE	trdt.comp_id		= @comp_id
									AND		trdt.rmadt_guid		<> @guid
									AND		trdt.is_id			= @is_id)
							BEGIN

								--devolución de datos para el caso en que exista en otro RMA que se esté cargando
								SELECT	tut.utexts_desc + ' ' + tu.user_lastname + ', ' + tu.user_firstname
								FROM	tbRMA_Detail_Tmp				trdt
										INNER JOIN tbUser				tu
										ON	tu.[user_id]	= trdt.user_id_Reception
										INNER JOIN tbsysUniqueTexts		tut
										on	tut.lang_id		= @lang_id
										AND	tut.utexts_id	= 124
								WHERE	trdt.comp_id		= @comp_id
								AND		trdt.rmadt_guid		<> @guid
								AND		trdt.is_id			= @is_id

							END

						END

		--		END
			END
	END

	--SELECT @return_value


END
GO






