CREATE PROCEDURE [dbo].[spRMADetailTmp_getData]
(
	@comp_id			INT,
	@lang_id			INT,
	@rmadt_guid			UNIQUEIDENTIFIER,
	@curr_id			INT
)
AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	-- -----------------------------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------------------
	/*
		declare @comp_id			int,
				@lang_id			INT,
				@rmadt_guid			uniqueidentifier,
				@curr_id			INT

		select	@comp_id			= 1,
				@lang_id			= 2,
				@rmadt_guid			= '0D106122-863D-4E0D-AF2F-E86BAB9762F8',
				@curr_id			= 1
*/
	-- -----------------------------------------------------------------------------------------

	select	' '											[ ],			--	7
			convert(int,rmadt.rmadt_isNewItem)			[ ],			--	8
			len(isnull(rmadt.rmadt_DiagnosticNote,''))	[ ],			--	9
			' '											[ ],			--	10
			convert(int,rmadt.rmadt_isNew)				[ ],			--	11	Se usa para grisar botones
			' '											[ ],			--	12	BOTON PARA REPARACIONES DE RMA
			' '											[ ],			--	13	BOTON PARA ANOTACIONES  DE RMA
			-- Ojo si se ponen mas botones modificar la variable de VB intRMADetailColumnId = (2*botones) - 1
			rmadt.rmad_id,
			rmadt.rmadt_guid,
			rmadt.item_id,
			i.item_code,
			i.item_desc,
			tis.is_serial,
			rmadt.rmadt_Manual,
			rmadt.it_transaction,
			rmadt.is_id,
			rmadt.rmadt_qty,
			rmadt.rmadt_originalPrice,
			c.curr_desc,
			rmadt.curr_id,
			rmadt.rmadt_Date_Reception,
			rmadt.bra_id,
			b.bra_desc,
			ts.stor_desc,
			rmadt.rmadt_DiagnosticNote,
			rmadt.rmadt_ReceptionNote,
			o.optval_desc,
			rmadt.srpt_id,
			rmadt.df_id4CreditNote,
			ts2.supp_name,
			tct.ct_date,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)	[description],
			DATEDIFF(DAY,tct.ct_date,GETDATE())													[date_diff],
			ISNULL(b.bra_RMA_ShowCostOnSupplier,'true')											[bra_RMA_ShowCostOnSupplier], --Parte:605 (Ticket=123)
			--rmadt.rmas_id,
			--rmadt.rmap_id,
			isnull(trs.rmas_desc,'') [rmas_desc],
			isnull(trp.rmap_desc,'') [rmap_desc],
			--trd.user_id_Reception,
			isnull(tu.user_nick,'')						[user_nick_Reception],
			rmadt.rmadt_Date_Reception					[rmad_Date_Reception],

			--trd.user_id_Diagnostic,
			isnull(tu2.user_nick,'')					[user_nick_Diag],
			rmadt.rmadt_Date_Diagnostic					[rmad_Date_Diagnostic],

			--trd.user_id_Proc,
			isnull(tu3.user_nick,'')					[user_nick_Proc],
			rmadt.rmadt_Date_Proc						[rmad_Date_Proc],

			--trd.user_id_Delivery
			isnull(tu4.user_nick, '')					[user_nick_Delivery],
			rmadt.rmadt_Date_Delivery					[rmad_Date_Delivery],

			dbo.fnRMAHeader_getReportDetail_GetNC_Rm(rmadt.comp_id, rmadt.rmah_id, rmadt.rmad_id,@lang_id)	[Document4Cancel],

			dbo.fnGetCommercialTransactionDescription(rmadt.comp_id, @lang_id, trscnp.ct_transaction)		[GeneralNote],


			-- ATENCION
			-- por favor, no poner NADA luego de esta linea.!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
			CASE
				WHEN rmadt.rmadt_DiagnosticNote <> '' THEN	1
				ELSE										0
			END											[*hD],		-- Count - 3  tiene Diagnostico ?
			rmadt.srpt_id,											-- Count - 2
			rmadt.rmadt_id								[ID]		-- Count - 1


	from	dbo.tbRMA_Detail_Tmp					rmadt		WITH (NOLOCK)

			left join dbo.tbItem					i		WITH (NOLOCK)
			on	i.comp_id		= rmadt.comp_id
			and	i.item_id		= rmadt.item_id

			left join dbo.tbsysCurrency				c		WITH (NOLOCK)
			on	c.curr_id		= rmadt.curr_id

			left join dbo.tbBranch					b		WITH (NOLOCK)
			on	b.comp_id		= rmadt.comp_id
			and b.bra_id		= rmadt.bra_id

			INNER JOIN dbo.tbsysOptionsValues		o		WITH (NOLOCK)
			ON	o.optval_id		= rmadt.srpt_id
			AND o.optval_class	= 109
			AND o.lang_id		= @lang_id

			LEFT JOIN tbItemSerials					tis		WITH (NOLOCK)
			ON	tis.comp_id		= rmadt.comp_id
			AND tis.is_id		= rmadt.is_id

			LEFT JOIN tbCommercialTransactions tct		WITH (NOLOCK)
			ON  tct.comp_id			= rmadt.comp_id
			AND tct.ct_transaction	= tis.ct_transaction

			LEFT JOIN tbStorage						ts		WITH (NOLOCK)
			ON	rmadt.comp_id	= ts.comp_id
			AND rmadt.stor_id	= ts.stor_id

			LEFT JOIN tbSupplier					ts2		WITH (NOLOCK)
			ON  ts2.comp_id = rmadt.comp_id
			AND ts2.supp_id = tct.supp_id

			left join tbRMA_Status					trs		WITH (NOLOCK)
			on  trs.comp_id = rmadt.comp_id
			AND trs.rmas_id = rmadt.rmas_id

			left join tbRMA_Priority				trp		WITH (NOLOCK)
			on  trp.comp_id = rmadt.comp_id
			AND trp.rmap_id = rmadt.rmap_id


			--STL GRUPO NUCLEO JOINS PARA USUARIOS

			LEFT JOIN tbUser						tu		WITH (NOLOCK)
			ON tu.user_id	 = rmadt.user_id_Reception

			LEFT JOIN tbUser						tu2		WITH (NOLOCK)
			ON tu2.user_id	 = rmadt.user_id_Diagnostic

			LEFT JOIN tbUser						tu3		WITH (NOLOCK)
			ON tu3.user_id	 = rmadt.user_id_Proc

			LEFT JOIN tbUser						tu4		WITH (NOLOCK)
			ON tu4.user_id	 = rmadt.user_id_Delivery

			LEFT JOIN tbRMA_SupplierCreditNotePending trscnp		WITH (NOLOCK)
				ON	trscnp.comp_id = rmadt.comp_id AND
					trscnp.rmah_id = rmadt.rmah_id AND
					trscnp.rmad_id = rmadt.rmad_id


	where	rmadt.comp_id		= @comp_id
	and		rmadt.rmadt_guid	= @rmadt_guid

	order by rmadt.rmadt_id


END

GO



CREATE PROCEDURE [dbo].[spRMADetailTmp_getDataById]
(
	@rmadt_id		int
)
AS

BEGIN



	set nocount on


	-- ----------------------------------------
	-- Testing
	-- ----------------------------------------
	/*
	declare		@rmadt_id		INT
	select		@rmadt_id		= 1243118
	*/
	-- ----------------------------------------


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	select	' ' [ ], ' ' [ ],
			rmadt.rmadt_guid,
			rmadt.item_id,
			isnull(i.item_desc,'')				[item_desc],
			isnull(i.item_code,'')				[item_code],
			rmadt.curr_id,
			c.curr_desc,
			rmadt.bra_id,
			b.bra_desc,
			rmadt.rmadt_qty,
			rmadt.rmadt_originalPrice,
			rmadt.stor_id,
			rmadt.it_transaction,
			rmadt.rmadt_Manual,
			isnull(rmadt.rmadt_ReceptionNote,'') [rmadt_ReceptionNote],
			rmadt.is_id,
			tis.is_serial,
			rmadt.user_id_Diagnostic,
			rmadt.rmadt_Date_Diagnostic,

			CASE	WHEN rmadt.rmadt_DiagnosticNote IS NULL	THEN ISNULL(trd.rmad_DiagnosticNote,'')
					WHEN rmadt.rmadt_DiagnosticNote = ''	THEN ISNULL(trd.rmad_DiagnosticNote,'')
					ELSE rmadt.rmadt_DiagnosticNote
			END					[rmadt_DiagnosticNote],

			rmadt.srpt_id,
			rmadt.rmadt_ProcNote,
			rmadt.df_id4CreditNote,
			rmadt.it_transaction_CN,
			rmadt.rmadt_isNewItem,
			rmadt.supp_id,
			rmadt.impData_Custom_local,
			rmadt.impData_Number_local,
			isnull(rmadt.rmad_IncludeInPotentialStock,'False')	[rmad_IncludeInPotentialStock],
			IsNull(rmadt.rmad_id,-1)							[rmad_id],
			ISNULL(rmadt.rmah_id,-1)							[rmah_id],
			rmadt.rmas_id,
			rmadt.rmap_id,
			rmadt.rmaw_id,
			rmadt.rmamt_id,
			rmadt.rmafailP_id,
			ISNULL(rmadt.rmadt_serial,'')							[rmadt_serial],
			ISNULL(rmadt.rmadt_up2Price,0)							[RMA_Up2Price],
			rmadt.rmafp_id,
			rmadt.rmafp_Price,
			rmadt.rmafp_curr_id,
			ISNULL(rmadt.bra_id_original,rmadt.bra_id)				[bra_id_original],
			rmadt.case_id,
			rmadt.rmad_relatedID,
			rmadt.it_transaction_Origin,
			ISNULL(rmadt.rmad_isAvailable4DeliverySheet, 'False')	[rmad_isAvailable4DeliverySheet],
			ISNULL(rmadt.sds_id4Delivery,0)							[sds_id4Delivery],
			rmadt.sds_id4Picking,
			rmadt.dl_id4Picking,
			rmadt.dl_id4delivery,
			rmadt.rmad_deliveryDate4Picking,
			rmadt.rmad_deliveryDate4Delivery,
			CASE
				WHEN rmadt.rmad_Date_estimatedFinalization IS NULL
				THEN ISNULL(trddate.rmad_Date_estimatedFinalization,GETDATE())
				ELSE rmadt.rmad_Date_estimatedFinalization
			END														[rmad_Date_estimatedFinalization],
			rmadt.rmad_handOverDate,
			tu.user_lastname + ',' + tu.user_firstname				[user_HandOver],
			ISNULL(CONVERT(NVARCHAR,rmadt.rmad_handOverDate),'')	[rmad_handOverDate],
			--rmadt.rmad_handOver_user_id,
			rmadt.rmadt_id	[ID]

	from	dbo.tbRMA_Detail_Tmp				rmadt		WITH (NOLOCK)

			left join dbo.tbItem				i		WITH (NOLOCK)
			on	i.comp_id		= rmadt.comp_id
			and	i.item_id		= rmadt.item_id

			left join dbo.tbsysCurrency			c		WITH (NOLOCK)
			on	c.curr_id		= rmadt.curr_id

			left join dbo.tbBranch				b		WITH (NOLOCK)
			on	b.comp_id		= rmadt.comp_id
			and b.bra_id		= rmadt.bra_id

			LEFT JOIN tbItemSerials				tis		WITH (NOLOCK)
			ON   tis.comp_id	= rmadt.comp_id
			AND	 tis.is_id		= rmadt.is_id

			LEFT JOIN tbRMA_Detail				trd		WITH (NOLOCK)
			ON	trd.comp_id		= rmadt.comp_id
			AND trd.is_id		= rmadt.is_id

			LEFT JOIN tbRMA_Detail				trddate		WITH (NOLOCK)
			ON	trddate.comp_id		= rmadt.comp_id
			AND trddate.rmah_id		= rmadt.rmah_id
			AND trddate.rmad_id		= rmadt.rmad_id

			LEFT JOIN tbUser					tu	WITH(NOLOCK)
			ON	tu.[user_id]		= rmadt.rmad_handOver_user_id

	where	rmadt.rmadt_id		= @rmadt_id

	order by rmadt.rmadt_id



END


















GO



CREATE PROCEDURE [dbo].[spRMADetailTmp_insertData]
(
	@comp_id				INT,
	@rmadt_guid				UNIQUEIDENTIFIER,
	@bra_id					INT,
	@it_transaction			INT,
	@item_id				INT,
	@stor_id				INT,
	@rmadt_Manual			VARCHAR(100),
	@rmadt_originalPrice	DECIMAL(19,6),
	@curr_id				INT,
	@rmadt_qty				DECIMAL(19,5),
	@user_id_Reception		INT,
	@rmadt_ReceptionNote	VARCHAR (8000),
	@is_id                  INT,
	@rmadt_ProcNote			VARCHAR(8000),
	@rmadt_DiagnosticNote	VARCHAR(8000),
	@srpt_id				INT,
	@df_id4CreditNote		INT,
	@rmadt_isNewItem		BIT,
	@rmah_id				INT,
	@rmad_id				INT,
	@supp_id				INT,
	@impData_Custom_local	NVARCHAR(200),
	@impData_Number_local	NVARCHAR(200),
	--STL NUCLEO PUNTO 22
	@rmas_id				int,
	@rmap_id				int,
	@rmaw_id				INT,
	@rmamt_id				INT,
	@user_id_Diagnostic		INT,
	@rmadt_Date_Diagnostic	DATETIME,
	@user_id_Proc			INT,
	@rmadt_Date_Proc		DATETIME,
	@user_id_Delivery		INT,
	@rmadt_Date_Delivery	DATETIME,
	@bitIs4Supplier			BIT,
	@return_value			INT OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2011-06-23
	-- TN			: Referencia: #1
	-- Description	: Por el cambio de funcionalidad de no eliminación de la tbRMA_detail cuando se actualiza desde
	--				  la tbRMA_Detail_Tmp, sino que actualiza los registros existentes, se cargan los rmah_id y
	--				  rmad_id de la tbRMA_detail en la tbRMA_Detail_Tmp
	-- =================================================================================================================


	-- ----------------------------------------------------------------------------
	-- PARAMETROS AGREGADOS POR STL, NO LOS ESTABA TENIENDO EN CUENTA Y NO LOS
	-- GRABABA POR ESO SE PISABA TODO EL TIEMPO Y QUEDABAN VACIOS CUANDO SE MODIF.
	-- ----------------------------------------------------------------------------

	DECLARE
		@luser_id_Diagnostic				INT,
		@lrmadt_Date_Diagnostic				DATETIME,
		@luser_id_Proc						INT,
		@lrmadt_Date_Proc					DATETIME,
		@luser_id_Delivery					INT,
		@lrmadt_Date_Delivery				DATETIME,
		@lrmad_Date_estimatedFinalization	DATETIME

			IF @user_id_Diagnostic	IS NULL
				BEGIN
					SET @luser_id_Diagnostic	= NULL
					SET @lrmadt_Date_Diagnostic = NULL
				END
			ELSE
				BEGIN
					SET @luser_id_Diagnostic	= @user_id_Diagnostic
					SET @lrmadt_Date_Diagnostic = @rmadt_Date_Diagnostic
				END



			IF @user_id_Proc		IS NULL
				BEGIN
					SET @luser_id_Proc			= NULL
					SET @lrmadt_Date_Proc		= NULL
				END
			ELSE
				BEGIN
					SET @luser_id_Proc			= @user_id_Proc
					SET @lrmadt_Date_Proc		= @rmadt_Date_Proc
				END




			IF @user_id_Delivery	IS NULL
				BEGIN
					SET @luser_id_Delivery		= NULL
					SET @lrmadt_Date_Delivery	= NULL
				END
			ELSE
				BEGIN
					SET @luser_id_Delivery		= @user_id_Delivery
					SET @lrmadt_Date_Delivery	= @rmadt_Date_Delivery
				END



			DECLARE @rmad_handOverDate		AS DATETIME
			DECLARE @rmad_handOver_user_id	AS INT
			SET @lrmad_Date_estimatedFinalization = NULL
			--IF EXISTS (	SELECT 1
			--				FROM tbRMA_Detail trd		WITH (NOLOCK)
			--           		WHERE	trd.comp_id = @comp_id AND
			--           				trd.rmah_id = @rmah_id AND
			--           				trd.rmad_id = @rmad_id)
			--	BEGIN

			SELECT
				@lrmad_Date_estimatedFinalization	= trd.rmad_Date_estimatedFinalization,
				@rmad_handOverDate					= trd.rmad_handOverDate,
				@rmad_handOver_user_id				= trd.rmad_handOver_user_id
				FROM tbRMA_Detail trd			WITH (NOLOCK)
				WHERE	trd.comp_id = @comp_id AND
						trd.rmah_id = @rmah_id AND
						trd.rmad_id = @rmad_id

				--END



			--**STL
			-- -----------------------------------------------
			-- SE MOSTRABA MAL LA FECHA DE RECEPCIÓN YA QUE SIEMPRE TOMABA
			-- EL GETDATE Y NO EL VALOR GRABADO EN LA RMA_DETAIL ORIGINAL
			DECLARE
				@lReceptionDate	DATETIME,
				@lControlValue	INT

			SET @lControlValue = -1

			IF EXISTS (	SELECT TOP 1  1
							FROM tbRMA_Detail trd		WITH (NOLOCK)
			           		WHERE	trd.comp_id = @comp_id AND
			           				trd.rmah_id = @rmah_id AND
			           				trd.rmad_id = @rmad_id)
				BEGIN

					SELECT
						@lReceptionDate = trd.rmad_Date_Reception
					FROM tbRMA_Detail trd			WITH (NOLOCK)
					WHERE	trd.comp_id = @comp_id AND
							trd.rmah_id = @rmah_id AND
							trd.rmad_id = @rmad_id

					SET @lControlValue = 1

				END


			--OBTENEMOS LA PROCESSING DATE DE LA SUCURSAL
			DECLARE
				@lBraProcessingDate	DATETIME

			SELECT
				@lBraProcessingDate = tb.bra_processingDate
			FROM tbBranch					tb		WITH (NOLOCK)
			WHERE	tb.comp_id = @comp_id	AND
					tb.bra_id	= @bra_id


			-- -----------------------------------------------

	-- ----------------------------------------------------------------------------


	INSERT INTO dbo.tbRMA_Detail_Tmp
	(
			comp_id,
			rmadt_guid,
			bra_id,
			it_transaction,
			item_id,
			stor_id,
			rmadt_Manual,
			rmadt_originalPrice,
			curr_id,
			rmadt_qty,
			user_id_Reception,
			rmadt_Date_Reception,
			rmadt_ReceptionNote,
			is_id,
			rmadt_ProcNote,
			rmadt_DiagnosticNote,
			srpt_id	,
			df_id4CreditNote,
			rmadt_isNewItem,
			rmah_id,	-- Ref: #1
			rmad_id,	-- Ref: #1
			supp_id,
			impData_Custom_local,
			impData_Number_local,
			--STL NUCLEO PUNTO 22
			rmas_id,
			rmap_id,
			rmaw_id,
			rmamt_id,
			user_id_Diagnostic,
			rmadt_Date_Diagnostic,
			user_id_Proc,
			rmadt_Date_Proc,
			user_id_Delivery,
			rmadt_Date_Delivery,
			bra_id_original,
			rmad_Date_estimatedFinalization,
			rmad_handOverDate,
			rmad_handOver_user_id
	)
	VALUES
	(
			@comp_id,
			@rmadt_guid,
			@bra_id,
			@it_transaction,
			@item_id,
			@stor_id,
			@rmadt_Manual,
			@rmadt_originalPrice,
			@curr_id,
			@rmadt_qty,
			@user_id_Reception,
			CASE @lControlValue WHEN -1 THEN
				@lBraProcessingDate
			ELSE
				@lReceptionDate
			END,	--AHORA LA GRABA ASI, IR AL PUNTO --**STL
			--GETDATE(), --ANTES GRABABA ASI LA FECHA DE RECEPCION
			@rmadt_ReceptionNote,
			@is_id,
			@rmadt_ProcNote,
			@rmadt_DiagnosticNote,
			@srpt_id,
			@df_id4CreditNote,
			@rmadt_isNewItem,
			@rmah_id,	-- Ref: #1
			@rmad_id,	-- Ref: #1
			@supp_id,
			@impData_Custom_local,
			@impData_Number_local,
			--STL NUCLEO PUNTO 22
			@rmas_id,
			@rmap_id,
			@rmaw_id,
			@rmamt_id,
			@luser_id_Diagnostic,
			@lrmadt_Date_Diagnostic,
			@luser_id_Proc,
			@lrmadt_Date_Proc,
			@luser_id_Delivery,
			@lrmadt_Date_Delivery,
			@bra_id,
			@lrmad_Date_estimatedFinalization,
			@rmad_handOverDate,
			@rmad_handOver_user_id
	)


	SET		@return_value = @@identity

END





	---- Si ponen un articulo que necesita tener el mismo articulo como adicional al ser ingresado lo hace aca
	--IF @bitIs4Supplier = 'False' AND @item_id IS NOT NULL
	--	BEGIN
	--		IF EXISTS(
	--					SELECT 1
	--						FROM tbitem
	--						WHERE	comp_id = @comp_id AND
	--								item_id = @item_id AND
	--								item_RMACloneItemInAdditionalPartsOnInsert = 'True'
	--				)
	--			BEGIN
	--				INSERT INTO tbrma
	--			END
	--	END
GO









CREATE PROCEDURE [dbo].[spRMADetailTmp_updateData]
(
		@rmadt_id				int,
		@bra_id					int,
		@item_id				int,
		@curr_id				int,
		@it_transaction			int,
		@stor_id				int,
		@rmadt_qty				decimal(19,5),
		@rmadt_Manual			varchar(100),
		@rmadt_originalPrice	decimal(19,6),
		@rmadt_ReceptionNote	varchar (8000),
		@rmadt_isNewItem		BIT,
		@is_id                  int,
		@impData_Custom_local	NVARCHAR(200),
		@impData_Number_local	NVARCHAR(200),
		--STL NUCLEO PUNTO 22
		@rmas_id				int,
		@rmap_id				int,
		@rmaw_id				INT,
		@rmamt_id				INT
)
as
	set nocount on

	update	dbo.tbRMA_Detail_Tmp

	set		bra_id					= @bra_id,
			item_id					= @item_id,
			curr_id					= @curr_id,
			it_transaction			= @it_transaction,
			stor_id					= @stor_id,
			rmadt_qty				= @rmadt_qty,
			rmadt_Manual			= @rmadt_Manual,
			rmadt_ReceptionNote		= @rmadt_ReceptionNote,
			rmadt_originalPrice		= @rmadt_originalPrice,
			rmadt_isNewItem			= @rmadt_isNewItem,
			is_id					= @is_id,
			impData_Custom_local	= @impData_Custom_local,
			impData_Number_local	= @impData_Number_local,
			--STL NUCLEO PUNTO 22
			rmas_id					= @rmas_id,
			rmap_id					= @rmap_id,
			rmaw_id					= @rmaw_id,
			rmamt_id				= @rmamt_id

	where	rmadt_id				= @rmadt_id

GO








CREATE PROCEDURE [dbo].[spRMADetailTmp_updateDataForDiagnostic]
(
		@rmadt_id				INT,
		@bra_id					INT,
		@user_id_Diagnostic		INT,
		@rmadt_DiagnosticNote	VARCHAR(8000),
		@rmas_id				int,
		@rmap_id				int,
		@rmaw_id				INT,
		@rmamt_id				INT,
		@rmafailP_id			INT
)
AS

BEGIN

	set nocount on

	update	dbo.tbRMA_Detail_Tmp
		set		bra_id					= @bra_id,
				user_id_Diagnostic		= @user_id_Diagnostic,
				rmadt_Date_Diagnostic	= GETDATE(),
				rmadt_DiagnosticNote	= @rmadt_DiagnosticNote,
				rmas_id					= @rmas_id,
				rmap_id					= @rmap_id,
				rmaw_id					= @rmaw_id,
				rmamt_id				= @rmamt_id,
				rmafailP_id				= @rmafailP_id
		where	rmadt_id				= @rmadt_id



END

GO






-- ATENCION:!!!!!!!!!!!!!!!!!!!!!!!!!!!
-- Las actualizaciones van al FINAL!!!!
CREATE PROCEDURE [dbo].[spRMADetailTmp_updateDataForProcessing]
(
		@comp_id				INT,
		@rmadt_id				INT,
		@bra_id					INT,
		@stor_id				INT,
		@rmadt_qty				DECIMAL(19,5),
		@rmadt_originalPrice	DECIMAL(19,6),
		@rmadt_DiagnosticNote	VARCHAR(8000),
		@srpt_id				INT,
		@rmadt_ProcNote			VARCHAR(8000),
		@df_id4CreditNote		INT,
		@guid					UNIQUEIDENTIFIER,
		@supp_id				INT,
		@impData_Custom_local	NVARCHAR(200),
		@impData_Number_local	NVARCHAR(200),
		@rmafp_id				int,
		@item_replacement		INT,
		@user_id				INT,
		@stor_id4Replacement	INT--,
		--@RMA_Up2Price			DECIMAL(19,6)
)
AS

BEGIN



	set nocount on
	-- =================================================================================================================
	-- Author		: MOH
	-- Creation Date: 2010-09-21
	-- Parte		: S/P Referencia: #1
	-- Description	: Se modifica la validación para la ejecución de spTempItemStock_insertData	eliminando la condición
	--				  trdt.rmadt_DiagnosticNote IS NULL
	-- =================================================================================================================
	-- Author		: MOH
	-- Creation Date: 2010-09-21
	-- Parte		: 562
	-- Description	: Si la cantidad a procesar es menor que la cantidad del item del rma original se debe generar un
	--				  nuevo item con la diferencia
	-- =================================================================================================================
	-- Author		: MOH
	-- Creation Date: 2010-10-06
	-- Parte		: S/P Referencia: #3
	-- Description	: Se vuelve a modificar las condiciones de generación de los insert en spSaleOrder_insertData ahora lo ejecuta
	--				  sólo para las opciones 35 y 50
	-- =======================================================================================================================================





-- ------------------------------------------------
-- TEsting
-- ------------------------------------------------
	/*
	DECLARE
			@comp_id				INT,
			@rmadt_id				INT,
			@bra_id					INT,
			@stor_id				INT,
			@rmadt_qty				DECIMAL(19,5),
			@rmadt_originalPrice	DECIMAL(19,6),
			@rmadt_DiagnosticNote	VARCHAR(8000),
			@srpt_id				INT,
			@rmadt_ProcNote			VARCHAR(8000),
			@df_id4CreditNote		INT,
			@guid					UNIQUEIDENTIFIER
			--@tis_id					INT
	SELECT
			@comp_id				= 1 ,
			@rmadt_id				= 1234093,
			@bra_id					= 1,
			@stor_id				= 1,
			@rmadt_qty				= 100.00000,
			@rmadt_originalPrice	= 140.000000,
			@rmadt_DiagnosticNote	= 'sdasd',
			@srpt_id				= 20,
			@rmadt_ProcNote			= 'rttwt',
			@guid					= '6D38C763-AF3F-4524-A813-DA9440DE8490'
	*/
-- ------------------------------------------------

	-- ----------------------------------------
	-- USUARIO QUE PROCESA, ANTES PISABA
	-- ----------------------------------------
	DECLARE @lintuser_id AS INT
	IF @user_id = -1
		SET @lintuser_id = NULL
	ELSE
		SET @lintuser_id = @user_id
	-- ----------------------------------------


	IF @df_id4CreditNote = -1 SET @df_id4CreditNote = NULL


	-- --------------------------------------
	-- ACA INGRESAMOS EL ARTICULO PARA REEMPLAZO
	-- --------------------------------------
	DECLARE
		@lItem_Replacement	INT

	IF @item_replacement = -1
		BEGIN
			SET @lItem_Replacement = NULL
		END
	ELSE
		BEGIN
			SET @lItem_Replacement = @item_replacement
		END

	-- --------------------------------------

	-- --------------------------------------
	-- ACA INGRESAMOS EL COSTO DE REPARACIÓN
	-- SI VIENE CON VALOR -1 LO PONEMOS EN NULL
	-- --------------------------------------
	DECLARE
		@lRMAFP_ID	INT

	IF @rmafp_id = -1
		BEGIN
			SET @lRMAFP_ID = NULL
		END
	ELSE
		BEGIN
			SET @lRMAFP_ID = @rmafp_id
		END

	-- --------------------------------------


	DECLARE @litem_id			INT,
			@ltis_priority		INT,
			@lcurr_id			INT,
			@tis_id				INT,
			@lstor_id			INT,
			@luser_id			INT,
			@litem_desc			VARCHAR(100),
			@lrmadt_qty			DECIMAL(19,5)	--21-09-2010 - MOH - Parte: 562



	/*
		35 - Funciona MAL - Se cambia por igual mercadería -35
		50 - Adelanto de Cambio -50
	*/
	If @srpt_id = 35 OR @srpt_id = 50  -- Ref: #3
	BEGIN


		-- Recuperamos el item_id, curr_id y stor_id
		SELECT	@litem_id		= trdt.item_id,
				@lcurr_id		= trdt.curr_id,
				@lstor_id		= trdt.stor_id,
				@litem_desc		= ti.item_desc,
				@lrmadt_qty		= trdt.rmadt_qty	--21-09-2010 - MOH - Parte: 562

		FROM	tbRMA_Detail_Tmp		trdt		WITH (NOLOCK)

				INNER JOIN tbItem		ti			WITH (NOLOCK)
				ON	ti.comp_id	= trdt.comp_id
				AND ti.item_id	= trdt.item_id

		WHERE	trdt.comp_id	= @comp_id
		AND		trdt.rmadt_guid = @guid
		AND		trdt.rmadt_id	= @rmadt_id




		-- se obtiene la prioridad del contador 1, pasando el depósito en el parámetro de la sucursal
		exec dbo.spCounters_getNextValue @comp_id, @lstor_id, 1, @ltis_priority OUTPUT





		/***********************************************************************************************/
		/***********************************************************************************************/
		/***********************************************************************************************/
		-- verificar este if ya que siempre existe el registro en la tbRMA_Detail_Tmp
		/***********************************************************************************************/
		/***********************************************************************************************/
		/***********************************************************************************************/
		IF EXISTS (SELECT 1 FROM tbRMA_Detail_Tmp trdt
					WHERE	trdt.comp_id		= @comp_id
					AND		trdt.rmadt_guid		= @guid
					AND		trdt.rmadt_id		= @rmadt_id)
					--AND		trdt.rmadt_DiagnosticNote IS NULL)		-- Referencia: #1
			BEGIN

				DECLARE @date DATETIME
				SET @date = GETDATE()


				DECLARE @wsID AS UNIQUEIDENTIFIER
				SET		@wsID = NEWID()

				EXEC spTempItemStock_insertData
						@comp_id,
						@guid,
						@ltis_priority,
						@litem_id,
						@litem_desc,
						null,
						@lcurr_id,
						@rmadt_qty,
						@rmadt_qty,
						 null,
						@rmadt_originalPrice,
						@lstor_id,
						null,
						@bra_id,
						@lintuser_id,
						--@luser_id,
						@date,
						@date,
						0,
						NULL ,
						NULL,
						NULL,
						'False',
						NULL,
						'false',
						@wsID, '',
						-1,
						@return_value	= @tis_id OUTPUT

			END
		ELSE
			BEGIN

				SELECT	@tis_id				= trdt.tis_id
					FROM	tbRMA_Detail_Tmp		trdt		WITH (NOLOCK)
					WHERE	trdt.comp_id		= @comp_id
					AND		trdt.rmadt_guid		= @guid
					AND		trdt.rmadt_id		= @rmadt_id



				EXEC spTempItemStock_updateData
						@tis_id,
						@ltis_priority,
						@litem_id,
						@litem_desc,
						null,
						@lcurr_id,
						@rmadt_qty,
						null,
						@rmadt_originalPrice,
						null,
						null,
						@lstor_id,
						@bra_id,
						null,
						@lintuser_id,
						--@luser_id,
						@comp_id,
						'false'

			END

	END
	ELSE
	BEGIN

		-- Recuperamos la cantidad original
		SELECT	@lrmadt_qty		= trdt.rmadt_qty	--21-09-2010 - MOH - Parte: 562

			FROM	tbRMA_Detail_Tmp		trdt		WITH (NOLOCK)

			WHERE	trdt.comp_id	= @comp_id
			AND		trdt.rmadt_guid = @guid
			AND		trdt.rmadt_id	= @rmadt_id

	END



	DECLARE @ldf_id INT, @lit_transaction INT

	IF @srpt_id = 1030 --proveedores
		BEGIN
			SET @ldf_id				= NULL
			SET @lit_transaction	= @df_id4CreditNote
		END
	ELSE
		BEGIN
			SET @ldf_id				= @df_id4CreditNote
			SET @lit_transaction	= NULL
		END





	-- ===========================================================================================
	-- Si se procesa una cantidad MENOR a la del RMA, se desdobla el item

	IF @rmadt_qty < @lrmadt_qty
	BEGIN


		INSERT INTO tbRMA_Detail_Tmp
		(
			comp_id,
			rmadt_guid,
			bra_id,
			it_transaction,
			item_id,
			stor_id,
			rmadt_Manual,
			rmadt_originalPrice,
			curr_id,
			rmadt_qty,
			user_id_Reception,
			rmadt_Date_Reception,
			rmadt_ReceptionNote,
			user_id_Diagnostic,
			rmadt_Date_Diagnostic,
			rmadt_DiagnosticNote,
			user_id_Proc,
			rmadt_Date_Proc,
			rmadt_ProcNote,
			user_id_Delivery,
			rmadt_Date_Delivery,
			rmadt_DelioveryNote,
			rmafp_id,
			rmafp_Price,
			rmafp_curr_id,
			srpt_id,
			is_id,
			tis_id,
			rmadt_isNew,
			it_transaction_CN,
			rmadt_srpt_id_previous,
			df_id4CreditNote,
			impData_Custom_local,
			impData_Number_local,
			item_id4Replacement
		)
		SELECT	trdt.comp_id,
				trdt.rmadt_guid,
				trdt.bra_id,
				trdt.it_transaction,
				trdt.item_id,
				trdt.stor_id,
				trdt.rmadt_Manual,
				trdt.rmadt_originalPrice,
				trdt.curr_id,
				trdt.rmadt_qty - @rmadt_qty,
				trdt.user_id_Reception,
				trdt.rmadt_Date_Reception,
				trdt.rmadt_ReceptionNote,
				trdt.user_id_Diagnostic,
				trdt.rmadt_Date_Diagnostic,
				trdt.rmadt_DiagnosticNote,
				trdt.user_id_Proc,
				trdt.rmadt_Date_Proc,
				trdt.rmadt_ProcNote,
				trdt.user_id_Delivery,
				trdt.rmadt_Date_Delivery,
				trdt.rmadt_DelioveryNote,
				trdt.rmafp_id,
				trdt.rmafp_Price,
				trdt.rmafp_curr_id,
				trdt.srpt_id,
				trdt.is_id,
				trdt.tis_id,
				trdt.rmadt_isNew,
				trdt.it_transaction_CN,
				trdt.rmadt_srpt_id_previous,
				trdt.df_id4CreditNote,
				trdt.impData_Custom_local,
				trdt.impData_Number_local,
				@lItem_Replacement

		FROM	tbRMA_Detail_Tmp		trdt WITH (NOLOCK)

		WHERE	trdt.comp_id		= @comp_id
		AND		trdt.rmadt_guid		= @guid
		AND     trdt.rmadt_id		= @rmadt_id

	END
	-- ===========================================================================================




	-- ----------------------------------------------------------------
	-- Actualizar AQUI rmafp_id y precios: rmafp_Price + rmafp_curr_id
	-- ----------------------------------------------------------------
	UPDATE 	dbo.tbRMA_Detail_Tmp

	SET 	bra_id					= @bra_id,
			stor_id					= @stor_id,
			rmadt_qty				= @rmadt_qty,
			rmadt_originalPrice		= @rmadt_originalPrice,
			rmadt_DiagnosticNote	= @rmadt_DiagnosticNote,
			srpt_id					= @srpt_id,
			rmadt_ProcNote			= @rmadt_ProcNote,
			df_id4CreditNote		= @ldf_id, --@df_id4CreditNote,
			it_transaction_CN		= @lit_transaction,
			rmadt_isNew				= 'true',
			tis_id					= @tis_id,
			supp_id					= @supp_id,
			impData_Custom_local	= @impData_Custom_local,
			impData_Number_local	= @impData_Number_local,
			item_id4Replacement		= @lItem_Replacement,
			user_id_Proc			= @lintuser_id--,
			--rmadt_Date_Proc			= GETDATE()

	WHERE	comp_id					= @comp_id
	AND		rmadt_guid				= @guid
	AND     rmadt_id				= @rmadt_id
	-- ----------------------------------------------------------------


	-- ----------------------------------------------------------------
	-- Aca si el rmafp_id es 80 o 90 tomamos un precio u el otro
	-- ----------------------------------------------------------------

		declare
			@lrmafp_price as decimal (19,6),
			@lrmafp_curr_id as integer,
			@bra_id_FP		AS INT = null

		if @srpt_id = 80
			begin
				select
						@lrmafp_price	= trfp.rmafp_price,
						@lrmafp_curr_id = trfp.curr_id,
						@bra_id_FP		= trfp.bra_id
					from tbRMA_FixPrices				trfp	WITH (NOLOCK)
					where	trfp.comp_id	= @comp_id
					and		trfp.rmafp_id	= @lRMAFP_ID
			end
		else
			begin
				if @srpt_id = 90
					begin
						select
								@lrmafp_price	= trfp.rmafp_NotFixPrice,
								@lrmafp_curr_id = trfp.curr_id,
								@bra_id_FP		= trfp.bra_id
							from tbRMA_FixPrices				trfp	WITH (NOLOCK)
							where	trfp.comp_id	= @comp_id
							and		trfp.rmafp_id	= @lRMAFP_ID
					end

			end

	if (@srpt_id = 80) or (@srpt_id = 90)
		begin

			UPDATE 	dbo.tbRMA_Detail_Tmp
				SET 	bra_id					= @bra_id_FP,	-- MOS 12-2021 x Security
						rmafp_id				= @lRMAFP_ID,
						rmafp_Price				= @lrmafp_price,
						rmafp_curr_id			= @lrmafp_curr_id,
						user_id_Proc			= @lintuser_id
				WHERE	comp_id					= @comp_id
				AND		rmadt_guid				= @guid
				AND     rmadt_id				= @rmadt_id

		END


	--STL ACTUALIZAMOS EL STOR_ID PARA REEMPLAZO QUE LLEGA COMO NUEVO PARAMETRO
	IF (@srpt_id = 35)
		BEGIN

			-- -------------------------------------------------------
			-- SI VIENE CON VALOR -1 LO PONEMOS EN NULL
			-- -------------------------------------------------------
			DECLARE
				@lINTStor_id4Replacement	INT

			IF @stor_id4Replacement = -1
				SET @lINTStor_id4Replacement = NULL
			ELSE
				SET @lINTStor_id4Replacement = @stor_id4Replacement

			-- -------------------------------------------------------

			UPDATE tbRMA_Detail_Tmp
			SET
					stor_id4Replacement = @lINTStor_id4Replacement
			WHERE	comp_id				= @comp_id	AND
					rmadt_guid			= @guid		AND
					rmadt_id			= @rmadt_id

		END
	-- ----------------------------------------------------------------



END
GO

