CREATE  PROCEDURE [dbo].[spRMADetailTmp_UpdateIsNew]
(
		@comp_id				INT,
		@bra_id					INT,
		@rmadt_id				INT,
		@guid					UNIQUEIDENTIFIER
)
AS

Set nocount ON

/*
DECLARE		@comp_id				INT,
			@bra_id					INT,
			@rmadt_id				INT,
			@tis_id					INT,
			@guid					UNIQUEIDENTIFIER


SELECT		@comp_id				= 1,
			@bra_id					= 1,
			@rmadt_id				= 1233444,
			@tis_id					= null,
			@guid					= 'EF21AC8D-714A-4EAA-A902-34CD229D374B'
*/

DECLARE @tis_id			AS INT
DECLARE @rmadt_isNew	AS bit


/*recuperamos el valor del proceso del registro a modificar*/

SELECT	@tis_id			= trd.tis_id,
		@rmadt_isNew    = trd.rmadt_isNew
FROM	tbRMA_Detail_tmp trd
WHERE	trd.comp_id		= @comp_id
AND		trd.rmadt_guid	= @guid
AND		trd.rmadt_id	= @rmadt_id


If @rmadt_isNew = 'True'
BEGIN

	update	dbo.tbRMA_Detail_Tmp		WITH (ROWLOCK)
	set		rmadt_isNew		= 'False',
			srpt_id			= 1,
			rmafp_id		= NULL,
			rmafp_Price		= 0,
			rmafp_curr_id	= NULL
	where	comp_id		= @comp_id
	AND		rmadt_guid	= @guid
	and		rmadt_id	= @rmadt_id


	IF EXISTS (	SELECT 1 FROM tbTempItemStock ttis	WITH (NOLOCK)
				WHERE	ttis.comp_id	= @comp_id
				AND		ttis.tis_id		= @tis_id
				AND		ttis.tis_guid	= @guid )

		exec spTempItemStock_deleteData  @comp_id,	 @tis_id

END


/*
SELECT *
FROM dbo.tbRMA_Detail_Tmp trdt
WHERE rmadt_id = 1233444
*/







GO





CREATE procedure [dbo].[spRMADetailTMP_UpdatePotentialStockData]
(
	@comp_id							INT,
	@bra_id								INT,
	@rmadt_id							INT,
	@rmad_IncludeInPotentialStoc		BIT,
	@AdditionalSerialNumber				VARCHAR(200),
	@RMA_Up2Price						DECIMAL(19,6),
	@case_id							INT,
	@rmad_id							INT,
	@it_transaction						INT,
	@WarrantyLegend						NVARCHAR(1000),
	@rmad_insertWarrantyCertificates	NVARCHAR(100),
	@rmad_isAvailable4DeliverySheet		BIT,
	--@sds_id4Delivery					INT,
	@dl_id4Picking						INT,
	@sds_id4Picking						INT,
	@dl_id4Delivery						INT,
	@sds_id4Delivery					INT,
	@rmad_deliveryDate4Picking			DATETIME,
	@rmad_deliveryDate4Delivery			DATETIME
)

AS
	BEGIN

		SET NOCOUNT ON

			IF @dl_id4Picking = -1
			BEGIN
				SET @dl_id4Picking = NULL
			END

			IF @sds_id4Picking = -1
				BEGIN
					SET @sds_id4Picking = NULL
				END

			IF @dl_id4Delivery = -1
				BEGIN
					SET @dl_id4Delivery = NULL
				END

			IF @sds_id4Delivery = -1
				BEGIN
					SET @sds_id4Delivery = NULL
				END


			UPDATE tbRMA_Detail_Tmp
			SET
				rmad_IncludeInPotentialStock	= @rmad_IncludeInPotentialStoc,
				rmadt_serial					= @AdditionalSerialNumber,
				rmadt_up2Price					= @RMA_Up2Price,
				case_id							= CASE @case_id			WHEN -1 THEN NULL ELSE @case_id			END,
				rmad_relatedID					= CASE @rmad_id			WHEN -1 THEN NULL ELSE @rmad_id			END,
				it_transaction_Origin			= CASE @it_transaction	WHEN -1 THEN NULL ELSE @it_transaction	END,
				rmad_insertWarrantyDetail		= @WarrantyLegend,
				rmad_insertWarrantyCertificates = @rmad_insertWarrantyCertificates,
				rmad_isAvailable4DeliverySheet	= @rmad_isAvailable4DeliverySheet,
				dl_id4Picking					= @dl_id4Picking,
				sds_id4Picking					= @sds_id4Picking,
				dl_id4delivery					= @dl_id4Delivery,
				sds_id4Delivery					= @sds_id4Delivery,
				rmad_deliveryDate4Picking		= @rmad_deliveryDate4Picking,
				rmad_deliveryDate4Delivery		= @rmad_deliveryDate4Delivery


			WHERE	comp_id		= @comp_id	AND
					bra_id		= @bra_id	AND
					rmadt_id	= @rmadt_id

	END
GO







