CREATE PROCEDURE [dbo].[spRMAHeader_getDataByFilters]
(
	@comp_id				INT ,
	@bra_id					INT ,
	@ispurchase				BIT,
	@selection_id			INT ,
	@srpt_id				INT ,
	@item_id				INT,
	@serial					VARCHAR(100),
	@datefrom				DATETIME,				-- Fecha de Creacion desde
	@dateto					DATETIME,				-- Fecha de Creacion hasta
	@rmah_id				INT,
	@rmah_isInSuppplier		INT,
	@rmad_id				INT,
	--STL RMA NUCLEO PUNTO 22
	@rmas_id				int,
	@rmap_id				int,

	@rmamt_id				int,
	@rmaw_id				INT,
	@sk_id					INT,
	@optionNote1			INT,
	@rmah_note1				VARCHAR(2000),
	@optionNote2			INT,
	@rmah_note2				VARCHAR(2000),
	@rmapheader_id			INT,
	@ObsOption				INT,
	@ReceptionNote			NVARCHAR(2000),
	@DiagOption				INT,
	@DiagnosticNote			NVARCHAR(2000),
	@AdditionalSerialNumber	VARCHAR(200),
	@user4RMAAssign			INT,
	@EstDeliveryDateFrom	DATETIME,				-- Fecha de Entrega Estimada Desde
	@EstDeliveryDateTo		DATETIME,				-- Fecha de Entrega Estimada Hasta
	@handOverDateFrom	DATETIME,					-- Fecha de Entrega Real
	@handOverDateTo		DATETIME,					-- Fecha de Entrega Real Hasta
	@handOverStatus		INT,							-- -1: Todos   1: Entregado   2: No Entregado
	@handOverUserID     INT
)
AS


BEGIN

	set nocount on
	set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	-- ---------------------------------------------------------------------------------
	-- TESTING
	-- ---------------------------------------------------------------------------------
	/*
		declare
			@comp_id			int,
			@bra_id				int,
			@ispurchase			BIT,
			@selection_id		int,
			@srpt_id			int,
			@item_id			INT,
			@serial				VARCHAR(100),
			@datefrom			datetime,
			@dateto				DATETIME,
			@rmah_id			int,
			@rmah_isInSuppplier	INT,
			@rmad_id			INT,
			--STL RMA NUCLEO PUNTO 22
			@rmas_id			int,
			@rmap_id			int,

			@rmamt_id			int,
			@rmaw_id			INT,
			@sk_id				INT,
			@optionNote1		INT,
			@rmah_note1			VARCHAR(2000),
			@optionNote2		INT,
			@rmah_note2			VARCHAR(2000),
			@rmapheader_id			INT,
			@ObsOption				INT,
			@ReceptionNote			NVARCHAR(2000),
			@DiagOption				INT,
			@DiagnosticNote			NVARCHAR(2000),
			@AdditionalSerialNumber	VARCHAR(200),
			@user4RMAAssign			INT	,
			@EstDeliveryDateFrom	DATETIME,
			@EstDeliveryDateTo		DATETIME,
			@handOverDateFrom	DATETIME,
			@handOverDateTo		DATETIME,
			@handOverStatus		INT	,
			@handOverUserID		INT

		select
			@comp_id			= 1,
			@bra_id				= -1,
			@ispurchase			= 'false',
			@selection_id		= -1,
			@srpt_id			=  1,
			@item_id			= -1,
			@datefrom			= '1999-01-01',
			@dateto				= '2999-12-31',
			@serial				= '',
			@rmah_id			= 0,
			@rmah_isInSuppplier	= -1,
			@rmad_id			= 0,
			--STL RMA NUCLEO PUNTO 22
			@rmas_id			= -1,
			@rmap_id			= -1,

			@rmamt_id			=-1,
			@rmaw_id			=-1,
			@sk_id				=-1,
			@optionNote1		= -1,
			@rmah_note1			= '',
			@optionNote2		= -1,
			@rmah_note2			= '',
			@AdditionalSerialNumber	='',
			@user4RMAAssign		=-1	,
			@rmapheader_id      = -1	,
			@ObsOption          = -1,
			@ReceptionNote      = '',
			@DiagOption			= -1,
			@DiagnosticNote		= '',
			@user4RMAAssign = -1,
			@EstDeliveryDateFrom	= '1999-01-01',
			@EstDeliveryDateTo		= '2999-12-31',
			@handOverDateFrom	= '1999-01-01',
			@handOverDateTo		= '2999-12-31',
			@handOverStatus		= -1,
			@handOverUserID		= -1
	*/
	-- ---------------------------------------------------------------------------------









	/***************************************************************************************************************/
	/* Cargamos en una temporal una marca para saber si está habilitado o no el botón eliminar en RMAAll           */
	/* Para saber si se puede eliminar tenemos que saber si todos los ítem de un RMA están en estado EN PROCESO=1  */
	/* Entonces si la cantidad de ítems de un RMA COUNT(*) es igual a la sumatoria de los srpt_id sum(trd.srpt_id) */
	/* retorna 1 (se puede eliminar) sino retorna 0 (no se puede eliminar)                                         */


	-- MOS 01-2022
	SET @EstDeliveryDateFrom	= dbo.fnGetEnd_or_BeginOfDate (@EstDeliveryDateFrom,'False')
	SET @EstDeliveryDateTo		= dbo.fnGetEnd_or_BeginOfDate (@EstDeliveryDateTo,'True')
	SET @handOverDateFrom		= dbo.fnGetEnd_or_BeginOfDate (@handOverDateFrom,'False')
	SET @handOverDateTo			= dbo.fnGetEnd_or_BeginOfDate (@handOverDateTo,'True')
	SET @datefrom				= dbo.fnGetEnd_or_BeginOfDate (@datefrom,'False')
	SET @dateto					= dbo.fnGetEnd_or_BeginOfDate (@dateto,'True')
	-- MOS 01-2022


	SET @serial = dbo.fnStrAllTrim(@serial)


	DECLARE		@tmp_srpt_id TABLE ( rmah_id INT PRIMARY KEY, [VALUE] INT, Qty DECIMAL(19,2) )
	INSERT INTO @tmp_srpt_id (rmah_id, [VALUE], Qty )

		SELECT	trd.rmah_id,
				CASE
					WHEN SUM(trd.srpt_id) = COUNT(*)  and COUNT(*) = 1 THEN 1	-- Solo se puede borrar si no esta procesado y solo es UN item!!!
					ELSE													0
				END								[value],
				isnull(sum(trd.rmad_qty),0)		[Qty]

			FROM	tbRMA_Detail trd				WITH (NOLOCK)
			INNER JOIN tbRMA_Header trh				WITH (NOLOCK)
				ON
					trh.comp_id = trd.comp_id	AND
					trh.rmah_id = trd.rmah_id

			Where	trh.comp_id		=   @comp_id
			AND		(@bra_id = -1	OR	trh.bra_id	=   @bra_id)
			and		(
					 (@ispurchase = 'True'  and (@selection_id = -1 or trh.supp_id = @selection_id) AND trh.cust_id IS null) or
					 (@ispurchase = 'False'	and (@selection_id = -1 or trh.cust_id = @selection_id) AND trh.supp_id IS null)
					)
			AND		trh.rmah_cd												BETWEEN @datefrom			 AND	@dateto
			-- NOOOOO miren que cuernos hacen.  parecemos PELOTUDOS con loos clientes !!!!!     MOS 09-2021
			--AND		ISNULL(trd.rmad_Date_estimatedFinalization,GETDATE())	BETWEEN @EstDeliveryDateFrom AND	@EstDeliveryDateTo
			AND		CASE
						WHEN @handOverStatus = -1											THEN 1
						WHEN @handOverStatus = 1 AND trd.rmad_handOver_user_id IS NOT NULL	THEN 1	-- entregados unicamente
						WHEN @handOverStatus = 2 AND trd.rmad_handOver_user_id IS     NULL	THEN 1	-- solo NO entregados
						ELSE																	 0
					END = 1
			AND     CASE
						WHEN @handOverStatus = -1 THEN 1
						WHEN @handOverStatus =  2 THEN 1
						WHEN @handOverStatus =  1 AND trd.rmad_handOverDate BETWEEN @handOverDateFrom AND @handOverDateTo	THEN 1
						ELSE 0
					END	= 1
			AND		CASE
						WHEN @handOverStatus = -1													THEN 1
						WHEN @handOverStatus =  2													THEN 1
						WHEN @handOverStatus = 1 AND @handOverUserID = trd.rmad_handOver_user_id	THEN 1
						ELSE																			 0
					END = 1

			GROUP BY trd.rmah_id
	/***************************************************************************************************************/

--==
--SELECT * FROM @tmp_srpt_id




	select	DISTINCT ' ' [ ], tmp.value [ ],' ' [ ],' ' [ ],
			CASE @ispurchase WHEN 'true'
				THEN	ts.supp_name
				else	cu.cust_name
			END [name],
			bra.bra_desc,
			rma.rmah_cd,
			/*isnull(sum(trd.rmad_qty),0)*/ tmp.Qty	[rmad_qty],

			CONVERT(DECIMAL(19,2),(	SELECT SUM(trd.rmad_qty)
										FROM tbRMA_Detail trd
										WHERE	trd.comp_id = @comp_id		AND
												trd.rmah_id = RMA.rmah_id	AND
												trd.srpt_id	= 1))	[NotProcessed],


			ISNULL(RMA.rmah_note1,'')					[rmah_note1],
			ISNULL(RMA.rmah_note2,'')					[rmah_note2],

			ISNULL(trp.rmap_desc,'')					[rmap_desc],

			(
				SELECT TOP 1
					tu.user_lastname + ',' + tu.user_firstname
					FROM tbRMA_Detail	trd	WITH(NOLOCK)
					LEFT JOIN tbUser	tu	WITH(NOLOCK)
					ON trd.user_id_Delivery		= tu.[user_id]
					WHERE	trd.comp_id			= RMA.comp_id AND
							trd.rmah_id			= RMA.rmah_id AND
							trd.user_id_Delivery IS NOT NULL
					ORDER BY trd.rmad_id	DESC
			) 											[user_id_Delivery], --CAMPO 16

			(
				SELECT TOP 1
					trd.rmad_Date_estimatedFinalization
					FROM tbRMA_Detail	trd	WITH(NOLOCK)
					WHERE	trd.comp_id = RMA.comp_id AND
							trd.rmah_id = RMA.rmah_id
					ORDER BY trd.rmad_id	DESC
			) 											[rmad_Date_estimatedFinalization], --FECHA ESTIMADA DE FINALIZACIÓN  --CAMPO 17

			(
				SELECT
					CONVERT(DECIMAL(19,2),
					SUM(trd.rmad_originalPrice * trd.rmad_qty))
					FROM tbRMA_Detail	trd	WITH(NOLOCK)
					WHERE	trd.comp_id = RMA.comp_id AND
							trd.rmah_id = RMA.rmah_id
			)											[rma_price],	--CAMPO 18

			--(
			--	SELECT TOP 1
			--		trd.
			--	FROM tbRMA_Detail AS trd
			--	WHERE	trd.comp_id = RMA.comp_id AND
			--			trd.rmah_id = RMA.rmah_id
			--)


			RMA.rmah_id					[ID]


	from	dbo.tbRMA_Header						RMA				WITH (NOLOCK)

			left JOIN dbo.tbRMA_Detail				trd				WITH (NOLOCK)
			ON		trd.comp_id		= RMA.comp_id
			AND		trd.rmah_id		= RMA.rmah_id


			left join dbo.tbCustomer				cu				WITH (NOLOCK)
			on		cu.cust_id		= RMA.cust_id
			And		cu.comp_id		= RMA.comp_id

			LEFT JOIN dbo.tbSupplier				ts				WITH (NOLOCK)
			ON		ts.comp_id		= rma.comp_id
			AND		ts.supp_id		= rma.supp_id

			LEFT JOIN tbSupplierKind				tsk				WITH (NOLOCK)
			ON		tsk.comp_id		= ts.comp_id
			AND		tsk.sk_id		= ts.sk_id

			left join dbo.tbBranch					bra				WITH (NOLOCK)
			on		bra.bra_id		= RMA.bra_id
			And		bra.comp_id		= RMA.comp_id

			LEFT JOIN @tmp_srpt_id					tmp
			ON		tmp.rmah_id		= rma.rmah_id

			LEFT JOIN tbRMA_Priority				trp				WITH (NOLOCK)
				ON	trp.comp_id = RMA.comp_id		AND
					trp.rmap_id = RMA.rmap_id

			--LEFT JOIN tbUser						AS tu			WITH(NOLOCK)
			--ON tu.[user_id]		= rma.user_id_assigned


	Where	RMA.comp_id		=   @comp_id
	AND		(@bra_id		= -1 OR RMA.bra_id	=   @bra_id)
	and		(
			 (@ispurchase = 'True'  and (@selection_id = -1 or RMA.supp_id = @selection_id) AND rma.cust_id IS null)
				or
			 (@ispurchase = 'False'	and (@selection_id = -1 or RMA.cust_id = @selection_id) AND rma.supp_id IS null)
			)
	AND		(@item_id	= -1  OR trd.item_id	= @item_id)
	AND		(@srpt_id   = -1  OR trd.srpt_id	= @srpt_id)
	--AND		(tis.is_serial	=   @serial		OR  len(@serial) = 0)
	AND		CASE
				WHEN @serial = ''											THEN 1
				WHEN EXISTS(	SELECT TOP 1  1
				            		FROM tbItemSerials tis WITH (NOLOCK)
				            		WHERE	tis.comp_id		= @comp_id	AND
				            				tis.is_id		= trd.is_id	AND
				            				tis.is_serial	= @serial)		THEN 1
				ELSE															 0
			END = 1



	AND		RMA.rmah_cd	between @datefrom  and	@dateto
	AND     (@rmah_id = '0' OR RMA.rmah_id		= @rmah_id)
	AND		(@rmah_isInSuppplier =-1 OR isnull(rma.rmah_isInSuppplier,'false') = @rmah_isInSuppplier)
	AND		(
				CASE
				    WHEN	@rmad_id = 0												THEN 1
				    WHEN	EXISTS(	SELECT TOP 1  1
	   		                        		FROM tbRMA_Detail trd2	WITH (NOLOCK)
	   		                        		WHERE	trd2.comp_id = rma.comp_id AND
	   		                        				trd2.rmah_id = rma.rmah_id AND
	   		                        				trd2.rmad_id = @rmad_id)			THEN 1
				    ELSE																	 0
				END = 1
			)


	--STL GRUPO NUCLEO RMA PUNTO 22
	AND		(
				CASE
				    WHEN	@rmas_id  = -1												THEN 1
				    WHEN	EXISTS(	SELECT TOP 1  1
	   		                          		from tbRMA_Detail trd2	WITH (NOLOCK)
	   		                          		WHERE	trd2.comp_id = rma.comp_id AND
	   		                          				trd2.rmah_id = rma.rmah_id		/*AND trd2.rmad_id = @rmad_id*/ and
	   		                          				trd2.rmas_id = @rmas_id)			THEN 1
				    ELSE																	 0
				END	= 1
			)
	AND		(
				CASE
				    WHEN	@rmap_id  = -1												THEN 1
				    WHEN	EXISTS(	SELECT TOP 1  1
	   		                          		from tbRMA_Detail trd2	WITH (NOLOCK)
	   		                          		WHERE	trd2.comp_id = rma.comp_id AND
	   		                          				trd2.rmah_id = rma.rmah_id /*AND trd2.rmad_id = @rmad_id*/ and
	   		                          				trd2.rmap_id = @rmap_id)			THEN 1
				    ELSE																	 0
				END	= 1
		     )

	AND		(
				CASE
				    WHEN	@rmaw_id  = -1												THEN 1
				    WHEN	EXISTS(	SELECT TOP 1  1
	   		                          		from tbRMA_Detail trd2	WITH (NOLOCK)
	   		                          		WHERE	trd2.comp_id = rma.comp_id AND
	   		                          				trd2.rmah_id = rma.rmah_id /*AND trd2.rmad_id = @rmad_id*/ and
	   		                          				trd2.rmaw_id = @rmaw_id)			THEN 1
				    ELSE																	 0
				END	= 1
			 )
	AND		(
				CASE
				    WHEN	@rmamt_id = -1												THEN 1
				    WHEN	EXISTS (	SELECT TOP 1  1
	   										from tbRMA_Detail trd2	WITH (NOLOCK)
	   		                           		WHERE	trd2.comp_id	= rma.comp_id AND
	   		                           				trd2.rmah_id	= rma.rmah_id /*AND trd2.rmad_id = @rmad_id*/ and
	   		                           				trd2.rmamt_id	= @rmamt_id)		THEN 1
				    ELSE																	 0
				END	= 1
			 )

	AND	(@rmapheader_id = -1 OR RMA.rmap_id = @rmapheader_id)


	--STL GRUPO NUCLEO RMA PARTE 88
	AND (
			CASE
			    WHEN	(@ObsOption	 = -1 )																	THEN 1
			    WHEN	(@ObsOption	 = 0 AND trd.rmad_ReceptionNote LIKE 			@ReceptionNote + '%')	THEN 1
			    WHEN	(@ObsOption	 = 1 AND trd.rmad_ReceptionNote LIKE '%' +		@ReceptionNote + '%')	THEN 1
			    WHEN	(@ObsOption	 = 2 AND trd.rmad_ReceptionNote =				@ReceptionNote )		THEN 1
			    WHEN	(@ObsOption	 = 3 AND trd.rmad_ReceptionNote <>				@ReceptionNote )		THEN 1
			    WHEN	(@ObsOption	 = 4 AND trd.rmad_ReceptionNote NOT LIKE '%' +	@ReceptionNote + '%')	THEN 1
			    ELSE																							 0
			END	= 1
		)

	AND (
			CASE
			    WHEN	(@DiagOption	 = -1 )																	THEN 1
			    WHEN	(@DiagOption	 = 0 AND trd.rmad_DiagnosticNote LIKE 			@DiagnosticNote + '%')	THEN 1
			    WHEN	(@DiagOption	 = 1 AND trd.rmad_DiagnosticNote LIKE '%' +		@DiagnosticNote + '%')	THEN 1
			    WHEN	(@DiagOption	 = 2 AND trd.rmad_DiagnosticNote =				@DiagnosticNote )		THEN 1
			    WHEN	(@DiagOption	 = 3 AND trd.rmad_DiagnosticNote <>				@DiagnosticNote )		THEN 1
			    WHEN	(@DiagOption	 = 4 AND trd.rmad_DiagnosticNote NOT LIKE '%' +	@DiagnosticNote + '%')	THEN 1
			    ELSE																								 0
			END	= 1
		)



	-- GA clase de proveedor . 10/10/13
	AND		(@sk_id    = -1 OR tsk.sk_id	=   @sk_id  )


	--FILTRADO POR NOTAS 1 y 2 / SE USO COMO EJEMPLO "spItem_getReport"

	AND (
			CASE
			    WHEN	(@optionNote1	 = -1														)		THEN 1
			    WHEN	(@optionNote1	 = 0 AND RMA.rmah_note1 LIKE 			@rmah_note1 + '%'	)		THEN 1
			    WHEN	(@optionNote1	 = 1 AND RMA.rmah_note1 LIKE '%' +		@rmah_note1 + '%'	)		THEN 1
			    WHEN	(@optionNote1	 = 2 AND RMA.rmah_note1 =				@rmah_note1			)		THEN 1
			    WHEN    (@optionNote1	 = 3 AND RMA.rmah_note1 <>				@rmah_note1			)		THEN 1
			    WHEN	(@optionNote1	 = 4 AND RMA.rmah_note1 NOT LIKE '%' +	@rmah_note1 + '%'	)		THEN 1
			    ELSE																							 0
			END	= 1
		)
	AND (
			CASE
			    WHEN	(@optionNote2	 = -1 )																THEN 1
			    WHEN	(@optionNote2	 = 0 AND RMA.rmah_note2 LIKE 			@rmah_note2 + '%')			THEN 1
			    WHEN	(@optionNote2	 = 1 AND RMA.rmah_note2 LIKE '%' +		@rmah_note2 + '%')			THEN 1
			    WHEN	(@optionNote2	 = 2 AND RMA.rmah_note2 =				@rmah_note2 )				THEN 1
			    WHEN	(@optionNote2	 = 3 AND RMA.rmah_note2 <>				@rmah_note2 )				THEN 1
			    WHEN	(@optionNote2	 = 4 AND RMA.rmah_note2 NOT LIKE '%' +	@rmah_note2 + '%')			THEN 1
			    ELSE																							 0
			END	= 1
		)


	AND
		--FILTRO POR EL NUEVO NUMERO DE SERIE ADICIONAL STL GRUPO NUCLEO
		(@AdditionalSerialNumber		= ''					OR trd.rmad_serial		= @AdditionalSerialNumber)
		--FILTRO POR EL USUARIO PARA RMA
	AND (@user4RMAAssign				= -1					OR rma.user_id_assigned = @user4RMAAssign)
	AND		ISNULL(trd.rmad_Date_estimatedFinalization,GETDATE())	BETWEEN @EstDeliveryDateFrom AND	@EstDeliveryDateTo
	ORDER BY RMA.rmah_id DESC -- [name], bra.bra_desc, rma.rmah_cd, RMA.rmah_id





END
GO







CREATE PROCEDURE [dbo].[spRMAHeader_getDataById]
(
	@lang_id			int,
	@rmah_id			int
)


as
set nocount on

/*
declare @lang_id			int,
		@rmah_id			int

select	@lang_id			= 2,
		@rmah_id			= 47

*/

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

SELECT
		' ' [ ], ' ' [ ],
		rma.comp_id,
		rma.rmah_id,
		rma.bra_id,
		rma.cust_id,
		rma.supp_id,
		rmah_cd,
		rmah_isEditing,
		rmah_isEditingCD,
		trd.srpt_id,
		isnull(rma.rmah_isInSuppplier,'false')	[rmah_isInSuppplier],
		isnull(rma.rmah_note1,'')				[rmah_note1],
		isnull(rma.rmah_note2,'')				[rmah_note2],
		ISNULL(rma.rmap_id,0)					[rmap_id],
		ISNULL(rma.user_id_assigned,0)			[user_id_assigned],
		rma.rmah_image


from	dbo.tbRMA_Header			rma			WITH (NOLOCK)

		INNER JOIN tbRMA_Detail trd				WITH (NOLOCK)
		ON	trd.comp_id = rma.comp_id
		AND trd.rmah_id = rma.rmah_id


where	rma.rmah_id		= @rmah_id
GO







CREATE PROCEDURE [dbo].[spRMAHeader_getReportDetail]
(
	@comp_id				INT,
	@lang_id		 		INT,
	@page_id				INT,
	@item_id				INT,
	@cust_id				int,
	@supp_id				int,
	@cat_id					INT,
	@subcat_id				INT,
	@brand_id				INT,
	@pdatefrom				NVARCHAR(30),
	@pdateto				NVARCHAR(30),
	@pdatefrom_Reception	NVARCHAR(30),
	@pdateto_Reception		NVARCHAR(30),
	@pdatefrom_Diagnostic	NVARCHAR(30),
	@pdateto_Diagnostic		NVARCHAR(30),
	@srpt_id				INT,
	@serial					VARCHAR(100),
	@is_purchase			INT,
	@bra_id					INT,
	@rmah_isInSuppplier		int,
	@rmamt_id				int,
	@rmaw_id				int,
	@coslis_id				int,
	@costtype				int,
	@curr_id				int,
	@chkDateProcess			BIT,
	@pdatefrom_Process		NVARCHAR(30),
	@pdateto_Process		NVARCHAR(30),
	@option					int,
	@rmah_note1				NVARCHAR(2000),
	@option2				int,
	@rmah_note2				NVARCHAR(2000),
	@intBranch4Lang			int
)
AS

BEGIN

	set nocount ON
	set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ---------------------------------------------------------
	-- TESTING
	-- ---------------------------------------------------------
	/*
	DECLARE	@comp_id				INT,
			@lang_id		 		INT,
			@page_id				INT,
			@item_id				INT,
			@cat_id					INT,
			@subcat_id				INT,
			@brand_id				INT,
			@pdatefrom				DATETIME,
			@pdateto				DATETIME,
			@pdatefrom_Reception	DATETIME,
			@pdateto_Reception		DATETIME,
			@pdatefrom_Diagnostic	DATETIME,
			@pdateto_Diagnostic		DATETIME,
			@srpt_id				INT,
			@serial					VARCHAR(100),
			@cust_id				int,
			@supp_id				int,
			@is_purchase			INT,
			@bra_id					INT,
			@rmah_isInSuppplier		int,
			@rmamt_id				int,
			@rmaw_id				int,
			@coslis_id				int,
			@costtype				int,
			@curr_id				int,
			@chkDateProcess			BIT,
			@pdatefrom_Process		NVARCHAR(30),
			@pdateto_Process		NVARCHAR(30),
			@option					int,
			@rmah_note1				NVARCHAR(2000),
			@option2				int,
			@rmah_note2				NVARCHAR(2000),
			@intBranch4Lang			int




	SELECT  @comp_id			 = 1,
			@lang_id			 = 2,
			@page_id			 = 10068,
			@item_id			 = -1,
			@cat_id				 = -1,
			@subcat_id			 = -1,
			@brand_id			 = -1,
			@pdatefrom			 = '1900-01-01',
			@pdateto			 = '9999-12-31',
			@pdatefrom_Reception  = '1900-01-01',
			@pdateto_Reception    = '9999-12-31',
			@pdatefrom_Diagnostic = '1900-01-01',
			@pdateto_Diagnostic	 = '9999-12-31',
			@srpt_id			 = -1,
			@serial				 = '',
			@cust_id			 = -1,
			@supp_id			 = -1,
			@is_purchase		 = 0,
			@bra_id				 = -1,
			@rmah_isInSuppplier	 = -1,
			@rmamt_id			 = -1,
			@rmaw_id			 = -1,
			@coslis_id			 = -1,
			@costtype			 = -1,
			@curr_id			 = 2,
			@intBranch4Lang		 = 0,
			@chkDateProcess			= 'false',
			@pdatefrom_Process		='1900-01-01',
			@pdateto_Process		='9999-12-31',
			@option					=-1,
			@rmah_note1				='',
			@option2				=-1,
			@rmah_note2				=''

			DROP TABLE #tmpRMA_Header
*/
	-- ---------------------------------------------------------
	-- ---------------------------------------------------------



	-- ---------------------------------------------------------
	-- Esto se tuvo que hacer para ejecutar desde la grilla
	-- generica que recibe un String SQL a ejecutar y los formatos
	-- de fecha pueden variar segun el SQL que este instalado
	-- Por lo que se pasan siempre en YMD y se convierten a fecha
	-- ---------------------------------------------------------
	DECLARE
		@datefrom			 DATETIME,
		@dateto				 DATETIME,
		@datefrom_Reception	 DATETIME,
		@dateto_Reception	 DATETIME,
		@datefrom_Diagnostic DATETIME,
		@dateto_Diagnostic	 DATETIME,

		@datefrom_Process    DATETIME,
		@dateto_Process		 DATETIME


	SET @datefrom			 = dbo.fnGetEnd_or_BeginOfDate(@pdatefrom,'False')
	SET @dateto				 = dbo.fnGetEnd_or_BeginOfDate(@pdateto,'True')
	SET @datefrom_Reception	 = dbo.fnGetEnd_or_BeginOfDate(@pdatefrom_Reception,'False')
	SET @dateto_Reception	 = dbo.fnGetEnd_or_BeginOfDate(@pdateto_Reception,'True')
	SET @datefrom_Diagnostic = dbo.fnGetEnd_or_BeginOfDate(@pdatefrom_Diagnostic,'False')
	SET @dateto_Diagnostic	 = dbo.fnGetEnd_or_BeginOfDate(@pdateto_Diagnostic,'True')
	-- ---------------------------------------------------------

	SET @datefrom_Process	 = dbo.fnGetEnd_or_BeginOfDate(@pdatefrom_Process,'False')
	SET @dateto_Process		 = dbo.fnGetEnd_or_BeginOfDate(@pdateto_Process,'True')



	DECLARE @fun_id INT
	SET @fun_id = 1


			SELECT trh.rmah_id,
					CASE
						WHEN trh.cust_id IS NULL THEN	'(' + convert(varchar,ts.supp_id) + ') - ' + isnull(ts.supp_name,'')
						ELSE								'(' + convert(varchar,tc.cust_id) + ') - ' + ISNULL(tc.cust_name,'')
					END										[name],
				    isnull(ti.item_code,'')					[item_code],
	   				case
	   					when ti.item_id is not null then	isnull(ti.item_desc,'')
						else								trd.rmad_Manual
					end										[item_desc],
				   isnull(ti.item_detail,'')				[item_detail],
				   isnull(tca.cat_desc,'')					[cat_desc],
				   isnull(tsc.subcat_desc,'')				[subcat_desc],
				   isnull(tb.brand_desc,'')					[brand_desc],
				   trh.rmah_cd								[rmah_cd],
				   trd.rmad_Date_Reception					[rmad_Date_Reception],
				   trd.rmad_Date_Diagnostic					[rmad_Date_Diagnostic],
				   trd.rmad_Date_Delivery					[rmad_Date_Delivery],
				   isnull(trd.rmad_qty,0)									[rmad_qty],
				   isnull(trd.rmafp_Price,0)								[rmafp_Price],
				   trd.curr_id,
				   tc2.curr_desc,
				   tc2.curr_symbol,
				   convert(varchar, tc2.curr_symbol) + ' ' + convert(varchar,isnull(trd.rmafp_Price,0)) [rmafp_Price_curr],
				   o.optval_desc							[srpt_desc],
				   trd.rmad_Date_Proc,

				   --trd.user_id_Reception,
				   isnull(tu.user_nick,'')					[user_nick_Reception],

				   --trd.user_id_Diagnostic,
				   isnull(tu2.user_nick,'')					[user_nick_Diag],

				   --trd.user_id_Proc,
				   isnull(tu3.user_nick,'')					[user_nick_Proc],

				   --trd.user_id_Delivery
				   isnull(tu4.user_nick, '')				[user_nick_Delivery],

					-- -----------------------------------
					-- STL CALCULOS PARA COSTO
					-- -----------------------------------
					trd.rmad_originalPrice,
					ti.item_id,
					trd.rmad_DiagnosticNote,
					trd.rmad_id,
					CASE
						WHEN trh.cust_id IS NULL THEN	isnull(ts.supp_Phone1,'')
						ELSE							isnull(tc.cust_phone1,'')
				   END										[Phone],
				   CASE
						WHEN trh.cust_id IS NULL THEN	CASE
				                                			WHEN isnull(ts.supp_eMail_RMA,'') = '' THEN ts.supp_email
				                                			ELSE										ts.supp_eMail_RMA
				                                		END
				   ELSE									CASE
				       										WHEN isnull(tc.cust_email4RMA,'') = '' THEN tc.cust_email
				       										ELSE										tc.cust_email4RMA
				       									END
				   END																							[Email],
				   tsk.sk_desc,
				   tck.ck_name,
				   ta.act_desc,
				   trs.rmas_desc,
				   tis.is_serial,
				   isnull(trd.rmad_qty,0) * isnull(trd.rmad_originalPrice,0)		[rmafp_PriceTotal],
				   trp.rmap_desc,
				   trwt.rmaw_desc,
				   trmt.rmamt_desc,
				   tb2.bra_desc,
				   ts2.stor_desc,
				   trh.rmah_note1,
				   trh.rmah_note2,
				   trh.cust_id,
				   tc.cust_name,
				   trh.supp_id,
				   ts.supp_name,
				   dbo.fnRMAHeader_getReportDetail_GetNC_Rm(trd.comp_id, trd.rmah_id, trd.rmad_id,@lang_id)	[Document4Cancel],
				   ISNULL(trfp.rmafailP_desc,'')															[rmafailP_desc],
				   isnull(trd.rmad_qty,0) * isnull(trd.rmad_originalPrice,0) + ( isnull(trd.rmad_qty,0) * isnull(trd.rmad_originalPrice,0) * ISNULL(ttn.tax_percentage,0) / 100)		[rmafp_PriceTotalWithTaxes]


			INTO #tmpRMA_Header

			FROM tbRMA_Header								trh		WITH (NOLOCK)

					inner JOIN tbRMA_Detail					trd		WITH (NOLOCK)
					ON   trd.comp_id   = trh.comp_id
					AND  trd.rmah_id   = trh.rmah_id

					LEFT JOIN vwItemTaxesOnlyOneIvaTax ttax			WITH (NOLOCK)
						ON	ttax.comp_id = trd.comp_id AND
							ttax.item_id = trd.item_id

					LEFT JOIN tbTaxName ttn							WITH (NOLOCK)
						ON	ttn.comp_id		= ttax.comp_id AND
							ttn.tax_id		= ttax.tax_id

					left JOIN dbo.tbItemSerials				tis		WITH (NOLOCK)
					ON	 trd.comp_id		=   tis.comp_id
					--AND  trd.it_transaction	=   tis.it_transaction
					AND	 trd.is_id			=   tis.is_id

					LEFT JOIN tbRMA_FailedPart trfp					WITH (NOLOCK)
						ON	trfp.comp_id		= trd.comp_id AND
							trfp.rmafailP_id	= trd.rmafailP_id

					LEFT JOIN tbCustomer					tc		WITH (NOLOCK)
					ON   tc.comp_id    = trh.comp_id
					AND  tc.cust_id    = trh.cust_id

					LEFT JOIN tbSupplier					ts		WITH (NOLOCK)
					ON   ts.comp_id    = trh.comp_id
					AND  ts.supp_id    = trh.supp_id

					LEFT JOIN tbItem						ti		WITH (NOLOCK)
					ON  ti.comp_id     = trh.comp_id
					AND ti.item_id	   = trd.item_id

					LEFT  JOIN tbCategory					tca		WITH (NOLOCK)
					ON  tca.comp_id    = trh.comp_id
					AND tca.cat_id     = ti.cat_id

					LEFT JOIN tbSubCategory					tsc		WITH (NOLOCK)
					ON  tsc.comp_id    = trh.comp_id
					AND tsc.cat_id     = ti.cat_id
					AND tsc.subcat_id  = ti.subcat_id

					LEFT JOIN tbBrand						tb		WITH (NOLOCK)
					ON  tb.comp_id			= ti.comp_id
					AND tb.brand_id			= ti.brand_id

					inner JOIN tbsysCurrency				tc2		WITH (NOLOCK)
					ON tc2.curr_id = trd.curr_id

					left join tbsysRMAProcType				trt		WITH (NOLOCK)
					on trt.srpt_id = trd.srpt_id

					INNER JOIN [tbsysOptionsValues]			o		WITH (NOLOCK)
					ON	o.[optval_id]		= trt.srpt_id
					AND o.lang_id			= @lang_id
					AND o.optval_class		= 109

					left join tbRMA_MerchandiseType			trmt	WITH (NOLOCK)
					on  trmt.comp_id  = trd.comp_id AND
						trmt.rmamt_id = trd.rmamt_id

					left join tbRMA_WarrantyType			trwt	WITH (NOLOCK)
					on  trwt.comp_id = trd.comp_id AND
						trwt.rmaw_id = trd.rmaw_id

					--STL GRUPO NUCLEO JOINS PARA USUARIOS

					LEFT JOIN tbUser						tu	WITH (NOLOCK)
					ON tu.user_id	 = trd.user_id_Reception

					LEFT JOIN tbUser						tu2	WITH (NOLOCK)
					ON tu2.user_id	 = trd.user_id_Diagnostic

					LEFT JOIN tbUser						tu3	WITH (NOLOCK)
					ON tu3.user_id	 = trd.user_id_Proc

					LEFT JOIN tbUser						tu4	WITH (NOLOCK)
					ON tu4.user_id	 = trd.user_id_Delivery


					LEFT JOIN tbSupplierKind tsk				WITH (NOLOCK)
						ON	tsk.comp_id = ts.comp_id AND
							tsk.sk_id	= ts.sk_id

					LEFT JOIN tbCustomerKind tck				WITH (NOLOCK)
						ON	tck.comp_id = tc.comp_id AND
							tck.ck_id	= tc.ck_id

					LEFT JOIN tbActivity ta						WITH (NOLOCK)
						ON	ta.comp_id	= tc.comp_id	AND
							ta.act_id	= tc.act_id


					LEFT JOIN tbRMA_Status trs					WITH (NOLOCK)
						ON	trs.comp_id = trd.comp_id AND
							trs.rmas_id = trd.rmas_id

					LEFT JOIN tbRMA_Priority trp				WITH (NOLOCK)
						ON	trp.comp_id = trd.comp_id AND
							trp.rmap_id = trd.rmap_id

					LEFT JOIN tbBranch tb2						WITH (NOLOCK)
						ON	tb2.comp_id = trh.comp_id AND
							tb2.bra_id	= trh.bra_id


					LEFT JOIN tbStorage ts2						WITH (NOLOCK)
						ON	ts2.comp_id = trd.comp_id AND
							ts2.stor_id = trd.stor_id


--					-- --------------------------------------------------------
--					-- Solo debe traer los RM y NC x RMA Clientes  **888
--					-- --------------------------------------------------------
--					LEFT JOIN tbItemTransactions tit			WITH (NOLOCK)
--						ON	tit.comp_id = trd.comp_id AND
--							tit.rmah_id = trd.rmah_id AND
--							tit.rmad_id = trd.rmad_id
--					LEFT JOIN tbCommercialTransactions tct
--						ON	tct.comp_id			= tit.comp_id	AND
--							tct.bra_id			= tit.bra_id	AND
--							tct.ct_transaction	= tit.ct_transaction	AND
--							tct.sd_id IN (2,3)
--					-- --------------------------------------------------------



			WHERE	trh.comp_id					= @comp_id
			AND		(@item_id					= -1 OR trd.item_id				= @item_id)
			AND		(@cat_id					= -1 OR ti.cat_id				= @cat_id)
			AND		(@subcat_id					= -1 OR ti.subcat_id			= @subcat_id)
			AND		(@brand_id					= -1 OR ti.brand_id				= @brand_id)
			AND		trh.rmah_cd					between @datefrom				and	@dateto
			AND		(@srpt_id					= -1 OR trd.srpt_id				= @srpt_id)
			AND		 trd.rmad_Date_Reception	between @datefrom_Reception		and  @dateto_Reception
			AND		 (trd.rmad_Date_Diagnostic	between @datefrom_Diagnostic	and  @dateto_Diagnostic or trd.rmad_Date_Diagnostic is NULL) --parte 786
			AND		(@serial = ''				OR									 tis.is_serial = @serial)

			and		((@is_purchase				= 0 AND NOT trh.cust_id is NULL) AND (@cust_id   = -1 OR trh.cust_id	= @cust_id) OR
					(@is_purchase				= 1 AND NOT trh.supp_id is NULL) AND (@supp_id   = -1 OR ts.supp_id	= @supp_id))

			AND		(@rmah_isInSuppplier =-1 OR isnull(trh.rmah_isInSuppplier,'false') = @rmah_isInSuppplier)

			and		(@bra_id	  = -1 or trh.bra_id = @bra_id)


			--tipo de mercaderia y tipo de garantia
			AND		(@rmamt_id					= -1 OR trmt.rmamt_id				= @rmamt_id)
			AND		(@rmaw_id					= -1 OR trwt.rmaw_id				= @rmaw_id)
			--AND		(tit.comp_id IS NULL OR (tit.comp_id IS NOT NULL AND tct.comp_id IS NOT NULL))	-- **888 Mas que importante. Es para que solo salgan los sd_id 2 y 3!!


			--Tarea ID 73. GA 24/02/14
			AND		 (@chkDateProcess	 = 'false'  OR (trd.rmad_Date_Proc	BETWEEN @datefrom_Process		and  @dateto_Process))
			AND	 (
							(@option	 = -1 ) or
							(@option	 = 0 and trh.rmah_note1 like @rmah_note1 + '%') or
							(@option	 = 1 and trh.rmah_note1 like '%' + @rmah_note1 + '%') or
							(@option	 = 2 and trh.rmah_note1 = @rmah_note1 ) or
							(@option	 = 3 and trh.rmah_note1 <> @rmah_note1 ) or
							(@option	 = 4 and trh.rmah_note1 not like '%' + @rmah_note1 + '%')
					)
			AND		(
							(@option2	 = -1 ) or
							(@option2	 = 0 and trh.rmah_note2 like @rmah_note2 + '%') or
							(@option2	 = 1 and trh.rmah_note2 like '%' + @rmah_note2 + '%') or
							(@option2	 = 2 and trh.rmah_note2= @rmah_note2 ) or
							(@option2	 = 3 and trh.rmah_note2 <> @rmah_note2 ) or
							(@option2	 = 4 and trh.rmah_note2 not like '%' + @rmah_note2 + '%')
					)

			ORDER BY  [name], trh.rmah_id




			IF @coslis_id = -1  -- NUNCA SE USA ya que si o si informa lista
				BEGIN
					SELECT
						rmah_id,
						[name],
						item_code,
	   					item_desc,
						item_detail,
						cat_desc,
						subcat_desc,
						brand_desc,
						rmah_cd,
						rmad_Date_Reception,
						rmad_Date_Diagnostic,
						rmad_Date_Delivery,
						convert(decimal(19,2),rmad_qty)									[rmad_qty],
						convert(decimal(19,2),rmafp_Price)								[rmafp_Price],
						tmpHeader.curr_id,
						tmpHeader.curr_desc,
						tmpHeader.curr_symbol,
						rmafp_Price_curr,
						srpt_desc,
						rmad_Date_Proc,
						user_nick_Reception,
						user_nick_Diag,
						user_nick_Proc,
			   			user_nick_Delivery,
						convert(decimal(19,2),rmad_originalPrice)						[rmad_originalPrice],
						item_id,
						rmad_DiagnosticNote,
						convert(decimal(19,2),dbo.fnGetExchange2(@comp_id, rmad_originalPrice, tmpHeader.curr_id, @curr_id, 0,0,0,0)) [Precio],
						tc.curr_symbol [curr_Total_Symb],
						rmad_id,
						[phone],
						[Email],
						sk_desc,
 					    ck_name,
 					    act_desc,
					    rmas_desc,
					    is_serial,
					    convert(decimal(35,2),rmafp_PriceTotal)							[rmafp_PriceTotal],
					    rmap_desc,
					    rmaw_desc,
					    rmamt_desc,
					    bra_desc,
					    stor_desc,
					    rmah_note1,
					    rmah_note2,
					    cust_id,
					    cust_name,
					    supp_id,
					    supp_name,
					    Document4Cancel,
   					  rmah_id				[IDLote],
					    rmad_id				[IDItem],
						[rmafailP_desc],
						[rmafp_PriceTotalWithTaxes]



					FROM #tmpRMA_Header								tmpHeader

						INNER JOIN tbsysCurrency tc
						on tc.curr_id = @curr_id

				END
			ELSE
				BEGIN

					SELECT
						rmah_id,
						[name],
						item_code,
   						item_desc,
						item_detail,
						cat_desc,
						subcat_desc,
						brand_desc,
						rmah_cd,
						rmad_Date_Reception,
						rmad_Date_Diagnostic,
						rmad_Date_Delivery,
						convert(decimal(19,2),rmad_qty)									[rmad_qty],
						convert(decimal(19,2),rmafp_Price)								[rmafp_Price],
						tmpHeader.curr_id,
						tmpHeader.curr_desc,
						tmpHeader.curr_symbol,
						rmafp_Price_curr,
						srpt_desc,
						rmad_Date_Proc,
						user_nick_Reception,
						user_nick_Diag,
						user_nick_Proc,
		   				user_nick_Delivery,
						convert(decimal(19,2),rmad_originalPrice)						[rmad_originalPrice],
						tmpHeader.item_id,
						CASE @costtype WHEN 1 THEN
							dbo.fnGetExchange2(@comp_id,isnull(ticl.coslis_price,0), isnull(ticl.curr_id,tmpHeader.curr_id) , @curr_id,0,0,0,0)
						ELSE
							dbo.fnGetExchange2(@comp_id,isnull(ticl.coslis_price_aw,0), isnull(ticl.curr_id,tmpHeader.curr_id), @curr_id,0,0,0,0)
						END											[Precio],
						tc.curr_symbol								[curr_Total_Symb],
						rmad_DiagnosticNote,
						rmad_id,
						[phone],
						[Email],
						sk_desc,
 					    ck_name,
 					    act_desc,
					    rmas_desc,
					    is_serial,
					    convert(decimal(19,2),rmafp_PriceTotal)							[rmafp_PriceTotal],
					    rmap_desc,
					    rmaw_desc,
					    rmamt_desc,
					    bra_desc,
					    stor_desc,
   					    rmah_note1,
					    rmah_note2,
					    cust_id,
					    cust_name,
					    supp_id,
					    supp_name,
					    Document4Cancel,
					    rmah_id				[IDLote],
					    rmad_id				[IDItem],
						[rmafailP_desc],
						[rmafp_PriceTotalWithTaxes],
						CASE @costtype WHEN 1 THEN
							dbo.fnGetExchange2(@comp_id,isnull(ticl.coslis_price,0), isnull(ticl.curr_id,tmpHeader.curr_id) , @curr_id,0,0,0,0)
						ELSE
							dbo.fnGetExchange2(@comp_id,isnull(ticl.coslis_price_aw,0), isnull(ticl.curr_id,tmpHeader.curr_id), @curr_id,0,0,0,0)
						END		* convert(decimal(19,2),rmad_qty)						[CostoTotalValorizado],
						tc.curr_symbol													[CurrId4CostoTotalValorizado]





					FROM #tmpRMA_Header								tmpHeader

						LEFT JOIN tbItemCostList					ticl
						on	ticl.item_id	= tmpHeader.item_id AND
							ticl.coslis_id	= @coslis_id

						LEFT JOIN tbItemCostListName				ticln
						on	ticln.comp_id = ticl.comp_id		AND
							ticln.coslis_id = ticl.coslis_id

						LEFT JOIN tbsysCurrency					tc
						ON	tc.curr_id		= @curr_id

					WHERE	ticl.comp_id	= @comp_id			AND
							ticl.coslis_id	= @coslis_id

				END




	exec [spReports_getData3]@comp_id,@intBranch4Lang,@lang_id,@page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

	--EXEC [sptexto de paginas] 2,213

	SELECT	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 103
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1					) [params1],

			CASE @item_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					  FROM	tbsysUniqueTexts tut
					  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	ti.item_desc
					 FROM	tbItem ti
					 WHERE	ti.comp_id = @comp_id
					 AND	ti.item_id = @item_id)
			END		[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 36
 		 and   t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			CASE @cat_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id   = @lang_id
					 AND	tut.utexts_id = 1)
				ELSE
					(SELECT	tc.cat_desc
					 FROM	tbCategory tc
					 WHERE	tc.comp_id = @comp_id
					 AND	tc.cat_id  = @cat_id)
			END		[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 38
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],
			CASE @subcat_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tsc.subcat_desc
						FROM	tbSubCategory tsc
						WHERE	tsc.comp_id = @comp_id AND tsc.subcat_id= @subcat_id)
			END		[params6],

		   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 73
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],
			CASE @brand_id WHEN -1 THEN
					(SELECT	 tut.utexts_desc
					 FROM	 tbsysUniqueTexts tut
					 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	tb.brand_desc
					 FROM	tbBrand tb
					 WHERE	tb.comp_id  = @comp_id
					 AND	tb.brand_id = @brand_id)
			END		[params8],

		   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 802
			and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],
			@serial [params10],

		   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 862
			and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],
			CASE @srpt_id WHEN -1 THEN
					(SELECT	 tut.utexts_desc
					 FROM	 tbsysUniqueTexts tut
					 WHERE	 tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT	trt.srpt_desc
					 FROM	tbsysRMAProcType trt
					 WHERE	trt.srpt_id = @srpt_id)
			END		[params12],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],
			 @datefrom [DateParams1],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params14],
			 @dateto   [DateParams2],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1387
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params15],
			 @datefrom_Reception [DateParams3],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1388
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params16],
			 @dateto_Reception   [DateParams4],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1389
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params17],
			 @datefrom_Diagnostic [DateParams5],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		 WHERE t.ctrl_id = 1390
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params18],
			 @dateto_Diagnostic   [DateParams6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 174
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1		)									[params19],
			CASE @cust_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(SELECT	tc.cust_name
					 FROM	tbCustomer tc
					 WHERE	tc.comp_id = @comp_id AND tc.cust_id= @cust_id)
			END		[params20],

		   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 392
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1		)									[params21],
			CASE @supp_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(SELECT	ts.supp_name
					 FROM	tbSupplier ts
					 WHERE	ts.comp_id = @comp_id AND ts.supp_id= @supp_id)
			END		[params22],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 685
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )		[params23],
			CASE @is_purchase WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc
						FROM	tbsysOptionsValues tov
						WHERE	tov.lang_id = @lang_id
						AND     tov.optval_id =@is_purchase
						AND     tov.optval_class = 1001)
			END		[params24],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 28
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1		)									[params25],
			CASE @bra_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(SELECT tb.bra_desc
					 FROM tbBranch tb
					 WHERE	tb.comp_id = @comp_id AND tb.bra_id= @bra_id)
			END		[params26],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 2263
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1		)									[params27],
			CASE @rmah_isInSuppplier WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(SELECT		tov.optval_desc
						FROM	tbsysOptionsValues tov
						WHERE	tov.lang_id = @lang_id
						AND     tov.optval_id =@rmah_isInSuppplier
						AND     tov.optval_class = 125)
			END		[params28],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 2329
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1		)									[params29],
			CASE @rmamt_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(SELECT trmt.rmamt_desc
					 FROM tbRMA_MerchandiseType trmt
					 WHERE	trmt.comp_id = @comp_id AND trmt.rmamt_id= @rmamt_id)
			END		[params30],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 2330
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1		)									[params31],
			CASE @rmaw_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(SELECT trwt.rmaw_desc
					 FROM tbRMA_WarrantyType trwt
					 WHERE	trwt.comp_id = @comp_id AND trwt.rmaw_id= @rmaw_id)
			END		[params32],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 391
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1		)									[params33],
			CASE @coslis_id WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
			ELSE
					(SELECT ticln.coslis_desc
					 FROM tbItemCostListName ticln
					 WHERE	ticln.comp_id	= @comp_id AND
							ticln.coslis_id	= @coslis_id)
			END		[params34],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 559
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1		)									[params35],
			CASE @costtype WHEN -1 THEN
					(SELECT	tut.utexts_desc
					 FROM	tbsysUniqueTexts tut
					 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 2)
			ELSE
					(select tov.optval_desc
					 from tbsysOptionsValues tov
					 where	tov.lang_id			= @lang_id	AND
							tov.optval_class	= 106		AND
							tov.optval_id		= @costtype)
			END		[params36],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 2362
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1		)									[params37],
	--		CASE @curr_id WHEN -1 THEN
	--				(SELECT	tut.utexts_desc
	--				 FROM	tbsysUniqueTexts tut
	--				 WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
	--		ELSE
					(SELECT tc.curr_desc
					 FROM tbsysCurrency tc
					 WHERE	tc.curr_id = @curr_id)
					[params38],


			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2777
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params39],
			 @datefrom_Process [DateParams7],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2778
			 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params40],
			 @dateto_Process   [DateParams8],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 43
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1					) [params41],

			CASE @option WHEN -1 THEN
					(SELECT	tut.utexts_desc
					  FROM	tbsysUniqueTexts tut
					  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		tov.optval_desc + ' '+ISNULL(@rmah_note1,'')
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 2
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @option)
			END		[params42],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id   = 45
      		 and   t.[page_id] = @related_page_id
      		 and   t.[type_id] = 1					) [params42],

			CASE @option2 WHEN -1 THEN
					(SELECT	tut.utexts_desc
					  FROM	tbsysUniqueTexts tut
					  WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 1)
				ELSE
				(SELECT		tov.optval_desc + ' '+ISNULL(@rmah_note2,'')
					FROM	dbo.tbsysOptionsValues tov
					WHERE	tov.optval_class	= 2
					AND		tov.lang_id			= @lang_id
					AND		tov.optval_id		= @option2)
			END		[params44]


END
GO







CREATE PROCEDURE [dbo].[spRMAHeader_insertData]
(
	@comp_id				INT,
	@bra_id					INT,
	@cust_id				INT,
	@supp_id				INT,
	@rmah_cd				DATETIME,
	@rmah_isInSuppplier		BIT,
	@rmah_note1				NVARCHAR(2000),
	@rmah_note2				NVARCHAR(2000),
	@return_value			INT OUTPUT
)
as


set nocount on
set dateformat 'ymd'


insert into dbo.tbRMA_Header	WITH (ROWLOCK)
(
	comp_id,
	bra_id,
	cust_id,
	supp_id,
	rmah_cd,
	rmah_isInSuppplier,
	rmah_note1,
	rmah_note2
)
values
(
	@comp_id,
	@bra_id,
	@cust_id,
	@supp_id,
	@rmah_cd,
	@rmah_isInSuppplier,
	@rmah_note1,
	@rmah_note2
)


set	@return_value = @@identity



























GO







CREATE PROCEDURE [dbo].[spRMAHeader_updateData]
(
	@comp_id				INT,
	@bra_id					INT,
	@rmah_id				INT,
	@cust_id				INT,
	@supp_id				INT,
	@rmah_cd				DATETIME,
	@rmah_isInSuppplier		BIT,
	@rmah_note1				NVARCHAR(2000),
	@rmah_note2				NVARCHAR(2000)
)
AS

BEGIN

	set nocount on

	update	dbo.tbRMA_Header	WITH (ROWLOCK)
		set		rmah_cd				= @rmah_cd,
				cust_id				= @cust_id,
				supp_id				= @supp_id,
				rmah_isInSuppplier	= @rmah_isInSuppplier,
				rmah_note1			= @rmah_note1,
				rmah_note2			= @rmah_note2

		where	comp_id				= @comp_id
		and	    rmah_id				= @rmah_id

END

























GO









