CREATE PROCEDURE [dbo].[spSaleOorderDetail_getPendingData]
(
	@comp_id	INT,
	@bra_id		INT,
	@lang_id	INT,
	@item_id	INT
)
AS SET NOCOUNT ON

SET DATEFORMAT 'ymd'
/*
DECLARE
	@comp_id	INT,
	@bra_id		INT,
	@lang_id	INT,
	@item_id	INT,
	@stor_id	INT

SELECT
	@comp_id	= 1,
	@bra_id		= 1,
	@lang_id	= 2,
	@item_id	= 223,
	@stor_id	= -1
*/

SELECT
	tb.bra_desc,
	tsod.sod_id,
	tsoh.soh_cd,
	tc.cust_name,
	tsod.sod_qty,
	tu.user_lastname + ',' + tu.user_firstname	[user_name],
	tsod.sod_priority							[sod_priority]


FROM tbSaleOrderDetail				tsod

INNER JOIN tbSaleOrderHeader		tsoh
ON  tsoh.comp_id	= tsod.comp_id
AND tsoh.bra_id		= tsod.bra_id
AND tsoh.soh_id		= tsod.soh_id

INNER JOIN tbCustomer				tc
ON  tc.comp_id		= tsoh.comp_id
AND tc.cust_id		= tsoh.cust_id

INNER JOIN tbStorage				ts
ON ts.comp_id		= tsod.comp_id
AND ts.stor_id		= tsod.stor_id

INNER JOIN tbUser					tu
ON tu.[user_id]		= tsod.[user_id]

INNER JOIN tbBranch					tb
ON tb.comp_id		= tsod.comp_id
AND tb.bra_id		= tsod.bra_id

WHERE	tsod.comp_id		= @comp_id
AND		tsod.bra_id			= @bra_id
AND		tsod.item_id		= @item_id
AND		tsod.sod_isEditing	= 'False'

UNION

SELECT
	tb.bra_desc,
	isnull(ttis.soh_id,' ')						[soh_id],
	' '											[soh_cd],
	tut.utexts_desc,
	ttis.tis_qty,
	tu.user_lastname + ',' + tu.user_firstname	[user_name],
	ttis.tis_priority							[sod_priority]



FROM tbTempItemStock					ttis

INNER JOIN tbsysUniqueTexts				tut
ON tut.lang_id		= @lang_id
AND tut.utexts_id	= 5000

INNER JOIN tbBranch						tb
ON  tb.comp_id		= ttis.comp_id
AND tb.bra_id		= ttis.bra_id

INNER JOIN tbUser						tu
ON tu.[user_id]		= ttis.[user_id]


WHERE	ttis.comp_id		= @comp_id
AND		ttis.bra_id			= @bra_id
AND		ttis.item_id		= @item_id
and		ttis.tis_IsEditing	= 'True'

ORDER BY [sod_priority]

/*Tiene que mostrar Sucursarl, Numero de Pedido (en la Header, fecha de pedido, Nombre del cliente, User_Name, Cant y Prioridad
* En el segundo query en lugar del Cust_Name poner 'Pedido en Edicion (POoner en la SysUnicTexts)'*/


GO



