CREATE PROCEDURE [dbo].[spSaleOrder_CheckBalanceInCeroBySalesTermsAndDeliveryRelations]
	@comp_id	AS INT,
	@st_id		AS INT,
	@dl_id		AS INT,
	@bra_id		AS INT,
	@prof_id	AS INT,
	@tis_guid   AS UNIQUEIDENTIFIER
AS



BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;



	-- -----------------------------------------------------------------------------
	-- tEST
	-- -----------------------------------------------------------------------------
	/*
	DECLARE
	@comp_id	AS INT,
	@st_id		AS INT,
	@dl_id		AS INT,
	@bra_id		AS INT,
	@prof_id	AS INT

	SET @comp_id	= 1
	SET @st_id		= 3
	SET @dl_id		= 1
	SET @bra_id		= 1
	SET @prof_id	= 1
	*/
	-- -----------------------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE @bitisOKBalance			AS BIT
	DECLARE @bitisOKStDlRelation	AS BIT
	DECLARE @strCustomerAndDocument AS NVARCHAR(MAX)
	SET		@strCustomerAndDocument = ''

	SET     @bitisOKBalance			= 'True'
	SET     @bitisOKStDlRelation	= 'True'


	DECLARE @datFrom	AS DATETIME
	DECLARE @datTo		AS DATETIME
	SELECT	@datFrom = dbo.fnGetEnd_or_BeginOfDate(tb.bra_processingDate,'False'),
			@datTo   = dbo.fnGetEnd_or_BeginOfDate(tb.bra_processingDate,'True')
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id


	-- ----------------------------------------------------------------------------------------------------------------------------------
	-- Verifica que si el transporte tiene alguna cond de vta relacionada debe haber una cond de vta relacionada si o si al transporte.!
	-- ----------------------------------------------------------------------------------------------------------------------------------
	IF EXISTS(
				SELECT	TOP 1 1
				 	FROM tbDeliverySalesTermsRelations tdstr
	          		WHERE	tdstr.comp_id	= @comp_id	AND
	          				tdstr.dl_id		= @dl_id	AND
	          				tdstr.bra_id	= @bra_id	AND
	          				(
	          					tdstr.prof_id	= @prof_id OR tdstr.prof_id IS NULL
	          				)							AND
	          				tdstr.dsr_disabled	= 'False'

			)
		AND
		NOT EXISTS (
						SELECT 1
				 			FROM tbDeliverySalesTermsRelations tdstr
	          				WHERE	tdstr.comp_id	= @comp_id	AND
	          						tdstr.dl_id		= @dl_id	AND
	          						tdstr.bra_id	= @bra_id	AND
	          						tdstr.st_id		= @st_id	AND

	          						(
	          							tdstr.prof_id	= @prof_id OR tdstr.prof_id IS NULL
	          						)							AND
	          						tdstr.dsr_disabled	= 'False'
					)

		BEGIN
			SET @bitisOKStDlRelation = 'False'
		END
	-- ----------------------------------------------------------------------------------------------------------------------------------






	-- ----------------------------------------------------------------------------------------------------------------------------------
	-- Verifica q si la con de vta dice q deben estar todos los cptes del dia saldados no tenga ninguno son saldar, sino cancela la emision del cpte.
	-- ----------------------------------------------------------------------------------------------------------------------------------
	IF EXISTS(
				SELECT 1
					FROM tbSalesTerms tst
					WHERE	tst.comp_id												= @comp_id	AND
							tst.st_id												= @st_id	AND
							tst.st_SaleOrder_CheckCeroBalanceOfPreviousDocuments	= 'True'
	)
		BEGIN

			DECLARE @tblBranch TABLE(bra_id INT PRIMARY KEY)
			INSERT INTO @tblBranch(bra_id) VALUES (@bra_id)

			INSERT INTO @tblBranch(bra_id)
				SELECT DISTINCT tbgd.bra_id
					FROM tbBranchGroupDetail tbgd
					INNER JOIN (SELECT tbgd2.brag_id
									FROM tbBranchGroupDetail tbgd2
									WHERE	tbgd2.comp_id	= @comp_id AND
											tbgd2.bra_id	= @bra_id  AND
											tbgd2.isOK4CheckCeroBalanceOfPrevDocuments = 'True') tbg
						ON tbg.brag_id = tbgd.brag_id
					WHERE	tbgd.comp_id = @comp_id AND
							tbgd.bra_id <> @bra_id	AND
							tbgd.isOK4CheckCeroBalanceOfPrevDocuments = 'True'



--==
--SELECT * FROM @tblBranch

			SELECT	@strCustomerAndDocument = dbo.fnGetCommercialTransactionDescription(tct.comp_id, 2, tct.ct_transaction) + ' (' + CONVERT(NVARCHAR(15),tc.cust_id) + ') ' + tc.cust_name,
					@bitisOKBalance			= 'False'
				FROM tbCommercialTransactions tct
				INNER JOIN @tblBranch kk
					ON kk.bra_id = tct.bra_id
				INNER JOIN tbCustomer tc
				ON	tc.comp_id = tct.comp_id						AND
					tc.cust_id = tct.cust_id
				WHERE	tct.comp_id = @comp_id						AND
						--tct.bra_id	= @bra_id						AND
						tct.ct_date BETWEEN @datFrom AND @datTo		AND
						tct.sd_id	= 1								AND
						tct.st_id	= @st_id						AND
						tct.ct_ABalance > 0
				ORDER BY tct.ct_transaction ASC
		END
	-- ----------------------------------------------------------------------------------------------------------------------------------



	-- Verifica que todos los articulos tengan un impuesto asociado
	DECLARE @bitItemWithNOTaxes AS BIT
	SET		@bitItemWithNOTaxes = 'False'


	SELECT @bitItemWithNOTaxes = 'True'
		FROM tbTempItemStock ttis				WITH (NOLOCK)
		INNER JOIN tbDocumentsFile tdf			WITH (NOLOCK)
			ON	tdf.comp_id		= ttis.comp_id AND
				tdf.df_id		= ttis.df_id
		LEFT JOIN tbtmpTax tt					WITH (NOLOCK)
			ON	tt.tis_id		= ttis.tis_id
		WHERE	ttis.tis_guid	= @tis_guid											AND
				tdf.df_SaleOrderDisableBlockEmmitionIfHasNoTaxMovements = 'False'	AND
				ttis.tis_isParentAssociate <> 'True'								AND
				tdf.sd_id IN (1,3,4,5,31,33,43,44)									AND
				tt.comp_id		IS NULL







	SELECT	@bitisOKBalance			[isOKBalance],
			@bitisOKStDlRelation	[isOKStDlRelation],
			@strCustomerAndDocument	[BalanceData],
			@bitItemWithNOTaxes		[hasItemsWithNoTaxes]

END
GO







CREATE PROCEDURE [dbo].[spSaleOrder_checkBasicData]
(
	@comp_id			INT,
	@bra_id				INT,
	@lang_id			INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	/*
	DECLARE @comp_id		INT
	DECLARE @lang_id		INT
	SELECT	@comp_id		=1,
			@lang_id		=2
	DROP TABLE #tmpData
	*/


	CREATE TABLE #tmpData ( [check] INT )

	/*
	por cada control que se realice al comienzo de las páginas y no esté correcto,
	hay que hacer un insert en la temporal creada arriba
	con el valor correspondiente al table_id de la tabla tbSysTables (siempre deberá ser un valor negativo)
	y este valor está relacionado con la tabla tbSysHelpPages que si tendrá el mensaje de error
	a mostrar al usuario
	*/


	if not exists (select 1 from tbSalesman					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-1)
	if not exists (select 1 from tbSalesTerms				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-2)
	if not exists (select 1 from tbDelivery					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-3)
	if not exists (select 1 from tbDiscount					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-4)
	if not exists (select 1 from tbPriceList				WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-5)
	if not exists (select 1 from tbCustomer					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-6)
	IF NOT EXISTS (SELECT 1 FROM tbDocumentsFile df
							inner join dbo.[vwsysDocuments_forSaleOrder]	sd on sd.[sd_id] = df.[sd_id]
							where	df.comp_id	= @comp_id
								and df.bra_id = @bra_id )							  INSERT INTO #tmpData ([check]) VALUES (-7)
	if not exists (select 1 from tbCurrencyExchange			WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-9)
	--if not exists (select 1 from tbCashNumber4Branch4User	WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-10)
	if not exists (select 1 FROM tbTaxName					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-14)
	if not exists (select 1 FROM tbStorage 					WHERE comp_id = @comp_id) INSERT INTO #tmpData ([check]) VALUES (-15)
	IF NOT EXISTS (SELECT 1 FROM tbCurrencyExchange tce
				   WHERE	tce.comp_id = @comp_id
				   AND		tce.curr_id_1 = (	SELECT	tc.curr_id
												FROM	tbCompany tc
												WHERE	tc.comp_id	= @comp_id)
				   AND		tce.curr_id_2 = (	SELECT	curr_id
												FROM	tbBranch tb
												WHERE	tb.comp_id	= @comp_id
												AND		tb.bra_id	= @bra_id))
	AND
	   NOT EXISTS (SELECT 1 FROM tbCurrencyExchange tce
				   WHERE	tce.comp_id = @comp_id
				   AND		tce.curr_id_2 = (	SELECT	tc.curr_id
												FROM	tbCompany tc
												WHERE	tc.comp_id	= @comp_id)
				   AND		tce.curr_id_1 = (	SELECT	curr_id
												FROM	tbBranch tb
												WHERE	tb.comp_id	= @comp_id
												AND		tb.bra_id	= @bra_id))		INSERT INTO #tmpData ([check]) VALUES (-16)


	SELECT	tut.utexts_desc, tut.utexts_id
	FROM	tbsysUniqueTexts tut
	WHERE	tut.lang_id			= @lang_id
	AND		tut.utexts_id		IN(4, 5, 6)
	AND		EXISTS(SELECT 1 FROM #tmpData)

	UNION

	SELECT	cast(thp.hp_desc AS NVARCHAR(MAX)), thp.page_id
	FROM	tbsysHelpPages			thp
			INNER JOIN #tmpData		td
			ON	td.[check]		= thp.table_id
	WHERE	thp.page_id			= -100040 --este valor está en duro e indica la funcionalidad que se está chequeando
	AND		thp.lang_id			= @lang_id

	ORDER BY 2 DESC



END
GO



CREATE PROCEDURE [dbo].[spSaleOrder_CheckSalesTermsDiscountBlockedByProfileAndBranch]

	@comp_id			AS INT,
	@lang_id			AS INT,
	@bra_id				AS INT,
	@prof_id			AS INT,
	@user_id			AS INT,
	@st_id				AS INT,
	@disc_id			AS INT


AS

BEGIN

SET NOCOUNT ON;
---------------------------------------------

/*
DECLARE
		@comp_id			AS INT,
		@lang_id			AS INT,
		@bra_id				AS INT,
		@prof_id			AS INT,
		@user_id			AS INT,
		@st_id				AS INT,
		@disc_id			AS INT


select
		@comp_id			=1,
		@lang_id			=2,
		@bra_id				=1,
		@prof_id			=1,
		@user_id			=1,
		@st_id				=34,
		@disc_id			=11
*/
---------------------------------------------

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	DECLARE @lstatus AS INT

	SET @lstatus = 0


	IF EXISTS(
				SELECT
					1
					FROM tbSalesTermsDiscountBlockedByProfileAndBranch tstdbbpab  WITH (NOLOCK)
					WHERE tstdbbpab.comp_id		= @comp_id	AND
						  tstdbbpab.bra_id		= @bra_id	AND
						  tstdbbpab.prof_id		= @prof_id	AND
						  tstdbbpab.st_id		= @st_id	AND
						  tstdbbpab.disc_id		= @disc_id  AND
						  tstdbbpab.isDisabled	= 'False'
				)

		BEGIN
					SET @lstatus = -1
		END


	SELECT @lstatus [status]

	-- -1 : Error , 0 = OK

END
GO





------------------------------------------------------------------
-- GA
-- Controlar Stock físico al emitir un pedido.
------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spSaleOrder_CheckStock4Emittion]
(
	@comp_id	INT,
	@tis_guid   UNIQUEIDENTIFIER,
	@lang_id    INT
)
AS



BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	-- --------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------
/*
		DECLARE
			@comp_id	INT,
			@tis_guid   UNIQUEIDENTIFIER
		SELECT
			@comp_id	= 1,
			@tis_guid	= '2A4A96E8-F039-483B-8EE5-D32979CC718E'
*/
	-- --------------------------------------------------------
	DECLARE @strDescError NVARCHAR(4000)
	SET @strDescError = ''


		--cantidad agrupada por guid,stor e item
	DECLARE @tmpQtyGroupedItemStock TABLE(tis_guid UNIQUEIDENTIFIER,stor_id INT,item_id INT, tis_qty DECIMAL(19,5))

	INSERT INTO @tmpQtyGroupedItemStock
		(
			tis_guid,
			stor_id,
			item_id,
			tis_qty
		)

		SELECT
			tis.tis_guid		[tis_guid],
			tis.stor_id			[stor_id],
			tis.item_id			[item_id],
			SUM(tis.tis_qty)	[tis_qty]
			FROM tbTempItemStock					tis							WITH (NOLOCK)

			-- MOS 08-2022: que no lo haga x items q no verifican stock
			INNER JOIN tbItem					 AS ti							WITH (NOLOCK)
				ON	ti.comp_id			= tis.comp_id AND
					ti.item_id			= tis.item_id

			-- Verifica que ESTE comp´robante SI verifique Stock
			INNER JOIN tbDocumentsFile				tdf2						WITH (NOLOCK)
				ON	tdf2.comp_id		= tis.comp_id			AND
					tdf2.df_id			= tis.df_id
			INNER JOIN tbsysDocuments				td2							WITH (NOLOCK)
				ON td2.sd_id			= tdf2.sd_id
			-- Verifica que si es la Factura de un Remito NO controle stock
			LEFT JOIN tbItemTransactions			tit							WITH (NOLOCK)
				ON	tit.comp_id			= tis.comp_id			AND
					tit.it_transaction	= tis.it_transaction
			LEFT JOIN tbCommercialTransactions		tct							WITH (NOLOCK)
				ON	tct.comp_id			= tit.comp_id			AND
					tct.bra_id			= tit.bra_id			AND
					tct.ct_transaction	= tit.ct_transaction
			LEFT JOIN tbDocumentsFile				tdf							WITH (NOLOCK)
				ON	tdf.comp_id			= tct.comp_id	AND
					tdf.bra_id			= tct.bra_id	AND
					tdf.df_id			= tct.df_id
			--
			WHERE  tis.comp_id				= @comp_id			AND
				   tis.tis_guid				= @tis_guid			AND
				   ti.item_NoStockCheck		= 'False'			AND
				   ti.item_SaleOrderSaveAndEmmition_BlockStockChk = 'False' AND
				   (
				   		tdf.comp_id IS NULL
				   			OR
						ISNULL(tdf.df_PackingInvoicePend,'False') = 'False'
				   )											AND
				   td2.sd_isCredit			= 'False'			AND
				   td2.sd_isQuotation		= 'False'

			GROUP BY tis.tis_guid,
						tis.item_id,
						tis.stor_id


--SELECT * FROM @tmpQtyGroupedItemStock

	SELECT
		@strDescError = @strDescError + '  ' +
						CASE WHEN LEN(ti.item_desc) > 20 THEN SUBSTRING(ti.item_desc,0,20) + '...' ELSE ti.item_desc END + '/' +
						CASE WHEN LEN(ts.stor_desc) > 20 THEN SUBSTRING(ts.stor_desc,0,20) + '...' ELSE ts.stor_desc END
		FROM @tmpQtyGroupedItemStock			tempqgis
		LEFT JOIN tbItemStorage					tis				WITH (NOLOCK)
			ON	tis.comp_id		= @comp_id		AND
				tis.item_id		= tempqgis.item_id	AND
				tis.stor_id		= tempqgis.stor_id
		LEFT JOIN tbItem						ti				WITH (NOLOCK)
			ON	ti.comp_id		= tis.comp_id	AND
				ti.item_id		= tis.item_id
		LEFT JOIN tbStorage						ts				WITH (NOLOCK)
			ON	ts.comp_id		= tis.comp_id	AND
				ts.stor_id		= tis.stor_id
		WHERE isnull(tis.itst_cant,0) < tempqgis.tis_qty


		IF @strDescError <> ''
			BEGIN
				--SELECT 'NO TIENE Stock físico'
				SELECT
					0											[Status],
					@strDescError								[message]
			END
		ELSE
			BEGIN
				--SELECT 'SI TIENE Stock físico'
				SELECT
					1											[Status],
					@strDescError								[message]
			END


END

GO





-- =============================================
-- Author:		MOS
-- Create date: 10-2008
-- Description:	Borra un Pedido
-- =============================================


CREATE PROCEDURE [dbo].[spSaleOrder_deleteData]
(
	@comp_id					INT,
	@bra_id						INT,
	@soh_id						INT,
	@user_id					INT,
	@deleteRMA					BIT,	--Ref: #1
	@guid						UNIQUEIDENTIFIER,
	@prof_id					INT,
	@intAction					INT,		-- 1-Emitir Pedido del Documento / 2-Borrar Pedido del documento
	@return_value				INT				OUTPUT,
	@ret_ErrorCode				INT 			OUTPUT,
	@ret_ErrorDescription		VARCHAR(200)	OUTPUT
)
AS


BEGIN
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2011-06-29
-- TN			: Reference #1
-- Description	: Ecución del spRMA_reverseProcess para volver a su estado original los RMA relacionados al Pedido
--				  si los tuviera
-- =================================================================================================================



	SET NOCOUNT ON



	-- Borrado del Grupo Definitivo

	-- Si siguen quedando items serializados que no pertenecen al pedido
	-- y por eso se cancela la facturacion de los mismos
	-- 1ro: verificar porque no se van x completo
	-- 2do: cjanchada, verificar de borrar los que sobren y no pertenezcan al pedido en cuestion.--


	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= '**687325687 Error in SO Delete'

	-- MOS 10-2020
	-- se usa para verificar si el documento que estoy EMITIENDO es el MISMO que tenia el pedido, por si entraron eon el boton amarillo, cambiaron el documento y trataron de emitirlo.
	DECLARE			@df_id AS INT = NULL
	SELECT TOP 1	@df_id = tdf.df_id
		FROM tbTempItemStock		AS ttis	WITH (NOLOCK)
		INNER JOIN  tbDocumentsFile AS tdf	WITH (NOLOCK)
		ON	tdf.comp_id = ttis.comp_id AND
			tdf.df_id	= ttis.df_id
		WHERE	ttis.comp_id	= @comp_id AND
				ttis.tis_guid	= @guid



	DECLARE @lang_id AS INT
	SET @lang_id = 2
	SELECT @lang_id = isnull(tc.lang_id,2)
		FROM tbCompany tc		WITH (NOLOCK)
		WHERE tc.comp_id = @comp_id


		-- -----------------------------
		-- Libera de IsEditing al Pedido
		-- -----------------------------
		UPDATE tbSaleOrderDetail			WITH (ROWLOCK)
		SET sod_isEditing = 'False'
			Where	comp_id     = @comp_id
				and bra_id      = @bra_id
				and soh_id	    = @soh_id
		UPDATE tbSaleOrderHeader			WITH (ROWLOCK)
		SET soh_isEditing = 'False'
			Where	comp_id     = @comp_id
				and bra_id      = @bra_id
				and soh_id	    = @soh_id
		-- -----------------------------


	-- -----------------------------------------------------------------------------------------------
	-- Si es un Pedido de Facturacion Adelantada y el comprobante actual es una Factura y el comprobante
	-- Destino es un REMITO de Facturacion Adelantada, deja el pedido cambiandolo al comprobante DESTINO
	-- -----------------------------------------------------------------------------------------------
	-- Aca debo reemplazar el documento de origen por el de destino si se da lo descripto arriba
	-- Antes de esto debo grabar en itemtrans items con el iva que se uso para los mnismos como Item Manual
	-- en lugar de items de stock
	DECLARE @cust_id									AS INT
	DECLARE @intSdId									AS INT
	DECLARE @intBraID									AS INT
	DECLARE @df_3rdSales_df_id4DebitNote				AS INT
	SET		@df_3rdSales_df_id4DebitNote				= NULL
	DECLARE @df_3rdSales_isAvailable4RegisterSale		AS BIT
	DECLARE @bolQuotationNoDeleteSaleOrderAtEmission	AS BIT
	DECLARE @ct_transaction_preCollection				AS INT = NULL
	SET		@bolQuotationNoDeleteSaleOrderAtEmission = 'False'


	SELECT	@cust_id								 = tsoh.cust_id,
			@intBraID								 = tdf.bra_id,
			@intSdId								 = tdf.sd_id,
			@bolQuotationNoDeleteSaleOrderAtEmission = CASE
															-- MOS 10-2020, MR, al emitir directo un pedido de presupuesto q no se borraba como Fc, seguia quedando el presupuesto sin borrar
														   WHEN tdf.sd_id = 5 AND tsoh.df_id = @df_id  THEN ISNULL(tdf.df_quotationNoDeleteSaleOrderAtEmission,'False')
			                                               --WHEN tdf.sd_id = 5  THEN ISNULL(tdf.df_quotationNoDeleteSaleOrderAtEmission,'False')
			                                               ELSE	'False'
			                                           END,
			--@df_3rdSales_df_id4DebitNote			 = ISNULL(tdf.df_3rdSales_df_id4DebitNote,-1),
			@df_3rdSales_isAvailable4RegisterSale    = ISNULL(tdf.df_3rdSales_isAvailable4RegisterSale,'False'),
			@ct_transaction_preCollection			 = tsoh.ct_transaction_preCollection
		FROM tbSaleOrderHeader tsoh				WITH (NOLOCK)
		INNER JOIN tbDocumentsFile tdf		WITH (NOLOCK)
			ON	tdf.comp_id = tsoh.comp_id AND
				tdf.df_id   = tsoh.df_id
		WHERE	tsoh.comp_id	= @comp_id	AND
				tsoh.bra_id		= @bra_id	AND
				tsoh.soh_id		= @soh_id





	-- ---------------------------------------------------------------------------------------------------
	-- Factura Anticipada - PreInvoice
	-- ---------------------------------------------------------------------------------------------------
	DECLARE @df_SaleOrder_InvoiceFirstPacking_df_id AS INT
	SET		@df_SaleOrder_InvoiceFirstPacking_df_id = NULL
	-- 	Obtengo el df_id destino SOLO si esta todo bien configurado, sino se seguira emitiendo como una factura normal.!!!

	-- MOS 05-2023: Se cambió esto al DOCUMENTO que se emite ya que si guardaban como pedido una fc anticipoada, entraban a modificar, seleccionaban un presupuesto y emitian, se emitia como presupuesto pero quedaba como rm de fc anticipada sin la fc emitida.
    --				Esto es porque no ponian el boton de Guardar y Emitir en el documento de Presupuesto.
	SELECT	@df_SaleOrder_InvoiceFirstPacking_df_id  = tdf.df_SaleOrder_InvoiceFirstPacking_df_id
		FROM	tbDocumentsFile   tdf				WITH (NOLOCK)
		LEFT JOIN tbDocumentsFile tdfPL				WITH (NOLOCK)
			ON	tdfPL.comp_id = tdf.comp_id		AND
				tdfPL.df_id   = tdf.df_SaleOrder_InvoiceFirstPacking_df_id
		WHERE
				tdf.comp_id		= @comp_id							AND
				tdf.df_id		= @df_id							AND
				tdf.sd_id		= 1									AND -- Solo si es FACTURA el oroginal
				tdfPL.sd_id		= 2									AND	-- y si el destino es REMITO
				tdfpl.df_SaleOrder_IsInvoiceFirstPacking = 'True'		-- y esta habilitado como remito de Fc. Adelantada



			--SELECT	@df_SaleOrder_InvoiceFirstPacking_df_id  = tdf.df_SaleOrder_InvoiceFirstPacking_df_id
			--	FROM tbSaleOrderHeader tsoh					WITH (NOLOCK)
			--	INNER JOIN tbDocumentsFile tdf			WITH (NOLOCK)
			--		ON	tdf.comp_id = tsoh.comp_id AND
			--			tdf.df_id   = tsoh.df_id
			--	LEFT JOIN tbDocumentsFile tdfPL			WITH (NOLOCK)
			--		ON	tdfPL.comp_id = tsoh.comp_id AND
			--			tdfPL.df_id = tdf.df_SaleOrder_InvoiceFirstPacking_df_id
			--	WHERE	tsoh.comp_id	= @comp_id	AND
			--			tsoh.bra_id		= @bra_id	AND
			--			tsoh.soh_id		= @soh_id	AND
			--			tdf.sd_id		= 1								  AND 	-- Solo si es FACTURA el oroginal
			--			tdfPL.sd_id		= 2								  AND	-- y si el destino es REMITO
			--			tdfpl.df_SaleOrder_IsInvoiceFirstPacking = 'True'		-- y esta habilitado como remito de Fc. Adelantada

	-- Si es factura adelantada cambia el documento del pedido y no hace mas nada. (NO DEBE BORRARLO!!!!!!)
	IF	@df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL			AND
		@intAction <> 2
		BEGIN
			UPDATE tbsaleorderheader		WITH (ROWLOCK)
				SET df_id	= @df_SaleOrder_InvoiceFirstPacking_df_id,
					ssos_id = 20 -- Queda en Preparacion para que se puedan tomar nros de serie asociados al momento de entregar la maercaderis.

			WHERE	comp_id = @comp_id	AND
					bra_id	= @bra_id	AND
					soh_id	= @soh_id
			RETURN
		END
	-- -----------------------------------------------------------------------------------------------












	-- -----------------------------------------------------------------------------------------------
	-- Si es un pedido que genera otro pedido para Documento Adicional, lo hace ahora.
	-- Se debe generar en la sucursal del documento destino.!!!!!!
	-- -----------------------------------------------------------------------------------------------
	DECLARE @intAddSaleOrder_df_id		AS INT
	DECLARE @intAddSaleOrder_coslis_id	AS INT
	DECLARE @intAddSaleOrder_bra_id     AS INT
	DECLARE @intAddSaleOrder_SOH_Id_New AS INT
	DECLARE @decSaleOrder_EmitionAddSaleOrder_DividePriceByCoeficient AS DECIMAL(19,6)
	SET @intAddSaleOrder_df_id			= NULL
	SET @intAddSaleOrder_coslis_id		= NULL
	SELECT	@intAddSaleOrder_df_id		= tdf.df_SaleOrder_EmitionAddSaleOrder_df_id,
			@intAddSaleOrder_coslis_id	= tdf.df_SaleOrder_EmitionAddSaleOrder_coslis_id,
			@intAddSaleOrder_bra_id     = tdfa.bra_id,
			@decSaleOrder_EmitionAddSaleOrder_DividePriceByCoeficient
										= IsNull(tdf.df_SaleOrder_EmitionAddSaleOrder_DividePriceByCoeficient,1)
		FROM tbSaleOrderHeader tsoh				WITH (NOLOCK)
			INNER JOIN tbDocumentsFile tdf		WITH (NOLOCK)
				ON	tdf.comp_id = tsoh.comp_id	AND
					tdf.df_id   = tsoh.df_id
			INNER JOIN tbDocumentsFile tdfa		WITH (NOLOCK)
				ON  tdfa.comp_id = tdf.comp_id AND
					tdfa.df_id   = tdf.df_SaleOrder_EmitionAddSaleOrder_df_id
		WHERE	tsoh.comp_id	= @comp_id		AND
				tsoh.bra_id		= @bra_id		AND
				tsoh.soh_id		= @soh_id		AND
				tdf.df_SaleOrder_EmitionAddSaleOrder_df_id IS NOT NULL

	IF	@intAddSaleOrder_df_id IS NOT NULL		AND
		@intAction <> 2
		BEGIN

			-- Si es 0 lo pone en 1
			IF @decSaleOrder_EmitionAddSaleOrder_DividePriceByCoeficient = 0 SET @decSaleOrder_EmitionAddSaleOrder_DividePriceByCoeficient = 1

			-- Obtengo el nuevo numero de documento.
			EXEC dbo.spCounters_getNextValue @comp_id, @intAddSaleOrder_bra_id, 2, @counter_value = @intAddSaleOrder_SOH_Id_New Output

			INSERT INTO tbSaleOrderHeader
			(
				comp_id,
				bra_id,
				soh_id,
				soh_cd,
				soh_deliveryDate,
				soh_observation1,
				soh_observation2,
				soh_observation3,
				soh_observation4,
				soh_quotation,
				sm_id,
				cust_id,
				st_id,
				disc_id,
				dl_id,
				cb_id,
				soh_lastUpdate,
				soh_limitDate,
				tt_id,
				tt_class,
				soh_StatusOf,
				[user_id],
				soh_isEditing,
				soh_isEditingCd,
				df_id,
				soh_total,
				ssos_id,
				soh_ExchangeToCustomerCurrency,
				chp_id,
				soh_PL_df_Id,
				soh_CustomerCurrency,
				soh_WithCollection,
				soh_WithCollectionGUID,
				soh_discount,
				soh_loan,
				soh_packagesQty,
				soh_internalAnnotation,
				curr_id4Exchange,
				curr_idExchange,
				soh_ATotal,
				df_id4PL,
				somp_id,
				soh_FEIdNumber,
				soh_inCash
			)
			SELECT tsoh.comp_id,
				   @intAddSaleOrder_bra_id,
				   @intAddSaleOrder_SOH_Id_New,
				   tsoh.soh_cd,
			       tsoh.soh_deliveryDate,
			       tsoh.soh_observation1,
			       tsoh.soh_observation2,
			       tsoh.soh_observation3,
			       tsoh.soh_observation4,
			       tsoh.soh_quotation,
			       tsoh.sm_id,
			       tsoh.cust_id,
			       tsoh.st_id,
			       tsoh.disc_id,
			       tsoh.dl_id,
			       tsoh.cb_id,
			       tsoh.soh_lastUpdate,
			       tsoh.soh_limitDate,
			       tsoh.tt_id,
			       tsoh.tt_class,
			       tsoh.soh_StatusOf,
			       tsoh.[user_id],
			       tsoh.soh_isEditing,
			       tsoh.soh_isEditingCd,
			  @intAddSaleOrder_df_id,
			       tsoh.soh_total,
			       50,  /*tsoh.ssos_id*/   -- OK para Emision.!
			       tsoh.soh_ExchangeToCustomerCurrency,
			       tsoh.chp_id,
			       NULL,
			       tsoh.soh_CustomerCurrency,
			       tsoh.soh_WithCollection,
			       tsoh.soh_WithCollectionGUID,
			       tsoh.soh_discount,
			   tsoh.soh_loan,
			       tsoh.soh_packagesQty,
			       tsoh.soh_internalAnnotation,
			       tsoh.curr_id4Exchange,
			       tsoh.curr_idExchange,
			       tsoh.soh_ATotal,
			       NULL,
			       tsoh.somp_id,
			   tsoh.soh_FEIdNumber,
			       tsoh.soh_inCash
				FROM tbSaleOrderHeader tsoh		WITH (NOLOCK)
				WHERE	tsoh.comp_id	= @comp_id		AND
						tsoh.bra_id		= @bra_id		AND
						tsoh.soh_id		= @soh_id


			INSERT INTO tbSaleOrderDetail
			(
				comp_id,
				bra_id,
				soh_id,
				sod_priority,
				item_id,
				sod_itemDesc,
				sod_detail,
				curr_id,
				sod_initQty,
				sod_qty,
				prli_id,
				sod_price,
				stor_id,
				sod_lastUpdate,
				sod_isEditing,
				sod_insertDate,
				[user_id],
				sod_quotation,
				sod_isCredit,
				sod_cost,
				sod_costTax,
				rmah_id,
				rmad_id,
				sod_note1,
				sod_note2,
				sod_itemDiscount,
				sod_tis_id_origin,
				sod_item_id_origin,
				sod_isParentAssociate,
				is_id,
				it_transaction,
				sod_isMade,
				sod_expirationDate,
				acc_count_id,
				sod_packagesQty
			)

			SELECT tsod.comp_id,
				   @intAddSaleOrder_bra_id,
				   @intAddSaleOrder_SOH_Id_New,
			       tsod.sod_priority,
			       NULL,
			       tsod.sod_itemDesc,
			       tsod.sod_detail,
			       tsod.curr_id,
			       tsod.sod_initQty,
			       tsod.sod_qty,
			       tsod.prli_id,
			       tsod.sod_price / dbo.fnNoZDiv( @decSaleOrder_EmitionAddSaleOrder_DividePriceByCoeficient),
			       tsod.stor_id,
			       tsod.sod_lastUpdate,
			       tsod.sod_isEditing,
			       tsod.sod_insertDate,
			       tsod.[user_id],
			       tsod.sod_quotation,
			       tsod.sod_isCredit,
			       CASE
						WHEN ticl.comp_id IS NULL			THEN tsod.sod_cost
						WHEN tb.bra_costlist_type='True'	THEN ticl.coslis_price_aw
						ELSE ticl.coslis_price
			       END,
			       -- Con respecto a los IVA, solo toma el primer IVA disponible en el documento

						 (select TOP 1 vitooit.tax_id
								FROM vwItemTaxesIvaTaxByDf_Id vitooit		WITH (NOLOCK)
								LEFT JOIN tbSaleOrderTaxes tsot
									ON	tsot.comp_id = tsod.comp_id    AND
										tsot.bra_id  = tsod.bra_id     AND
										tsot.soh_id  = tsod.soh_id     AND
										tsot.sod_id  = tsod.sod_id     AND
										tsot.tax_id  = vitooit.tax_id
								where	vitooit.comp_id = tsod.comp_id AND
										vitooit.df_id   = @intAddSaleOrder_df_id
						      ORDER BY tsot.tax_id DESC
							  )
			       ,
			       tsod.rmah_id,
			       tsod.rmad_id,
			       tsod.sod_note1,
			       tsod.sod_note2,
			       tsod.sod_itemDiscount,
			       tsod.sod_tis_id_origin,
			       tsod.sod_item_id_origin,
			       tsod.sod_isParentAssociate,
			       tsod.is_id,
			       tsod.it_transaction,
			       tsod.sod_isMade,
			       tsod.sod_expirationDate,
			       tsod.acc_count_id,
			       tsod.sod_packagesQty
				FROM tbSaleOrderDetail tsod			WITH (NOLOCK)
				INNER JOIN tbBranch tb				WITH (NOLOCK)
					ON	tb.comp_id		= tsod.comp_id AND
						tb.bra_id		= tsod.bra_id
				LEFT JOIN tbItemCostList ticl		WITH (NOLOCK)
					ON	ticl.comp_id	= @comp_id AND
						ticl.coslis_id	= @intAddSaleOrder_coslis_id AND
						ticl.item_id    = tsod.item_id

			WHERE	tsod.comp_id	= @comp_id	AND
					tsod.bra_id		= @bra_id	AND
					tsod.soh_id		= @soh_id



		END
	-- -----------------------------------------------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Si es un pedido de RMA se Revierte el proceso antes efectuado.!!!
	-- -----------------------------------------------------------------
	IF @deleteRMA = 'true' AND EXISTS (SELECT TOP 1	1
											FROM	tbRMA_Detail trd			WITH (NOLOCK)
											INNER JOIN tbSaleOrderDetail tsod	WITH (NOLOCK)
											ON  tsod.comp_id = trd.comp_id
											AND tsod.rmah_id = trd.rmah_id
											AND tsod.rmad_id = trd.rmad_id)
	BEGIN
		EXEC spRMA_reverseProcess @comp_id, @bra_id, @soh_id,@prof_id
	END
	-- -----------------------------------------------------------------


	-- -----------------------------------------------------------------
	-- poNGO EN UNA temporal LOS pEDIDOS A bORRAR
	-- -----------------------------------------------------------------
	DECLARE @tmpSaleOrderToDelete TABLE (	comp_id INT,
											bra_id INT,
											soh_id INT,
											sod_id INT,
											INDEX tmpSaleOrderToDeleteIDX NONCLUSTERED(comp_id,bra_id,soh_id,sod_id)
										)

	INSERT INTO @tmpSaleOrderToDelete(comp_id, bra_id, soh_id, sod_id)
		SELECT DISTINCT tso.comp_id,
						tso.bra_id,
						tso.soh_id,
						tso.sod_id
			FROM dbo.tbSaleOrderDetail		tso		WITH (NOLOCK)
				INNER JOIN tbTempItemStock	ttis	WITH (NOLOCK)
					ON	ttis.comp_id	= tso.comp_id
					AND ttis.soh_id		= tso.soh_id
					AND ttis.sod_id		= tso.sod_idOfThisEW
			Where		tso.comp_id		= @comp_id
					and tso.bra_id		= @bra_id
					and tso.soh_id		= @soh_id
					AND @bolQuotationNoDeleteSaleOrderAtEmission = 'False'
					AND ttis.tis_guid   = @guid
					AND tso.sod_idOfThisEW IS NOT NULL
			ORDER BY tso.sod_id

	INSERT INTO @tmpSaleOrderToDelete(comp_id, bra_id, soh_id, sod_id)
		SELECT DISTINCT tso.comp_id,
						tso.bra_id,
						tso.soh_id,
						tso.sod_id
			FROM dbo.tbSaleOrderDetail		tso			WITH (NOLOCK)
				INNER JOIN tbTempItemStock	ttis		WITH (NOLOCK)
					ON	ttis.comp_id	= tso.comp_id
					AND ttis.soh_id		= tso.soh_id
					AND ttis.sod_id		= tso.sod_id
			Where		tso.comp_id		= @comp_id
					and tso.bra_id		= @bra_id
					and tso.soh_id		= @soh_id
					AND @bolQuotationNoDeleteSaleOrderAtEmission = 'False'
					AND ttis.tis_guid   = @guid
			ORDER BY tso.sod_id



	INSERT INTO @tmpSaleOrderToDelete(comp_id, bra_id, soh_id, sod_id)
		SELECT DISTINCT tso.comp_id,
						tso.bra_id,
						tso.soh_id,
						tso.sod_id
			FROM dbo.tbSaleOrderDetail		tso			WITH (NOLOCK)
			Where		tso.comp_id		= @comp_id
					and tso.bra_id		= @bra_id
					and tso.soh_id		= @soh_id
					AND @bolQuotationNoDeleteSaleOrderAtEmission = 'False'
					AND tso.sod_DeliveryCharge = 'True'


	-- MOS 10-2019: Si en SOH dice que borre todo lo pendiente, lo borra.
	INSERT INTO @tmpSaleOrderToDelete(comp_id, bra_id, soh_id, sod_id)
		SELECT DISTINCT tso.comp_id,
						tso.bra_id,
						tso.soh_id,
						tso.sod_id
			FROM dbo.tbSaleOrderDetail		tso			WITH (NOLOCK)
			INNER JOIN tbSaleOrderHeader	tsoh		WITH (NOLOCK)
				ON	tsoh.comp_id		= tso.comp_id	AND
					tsoh.soh_id			= tso.soh_id	AND
					tsoh.bra_id			= tso.bra_id
			INNER JOIN tbDocumentsFile		tdf			WITH (NOLOCK)
				ON	tdf.comp_id			= tsoh.comp_id			AND
					tdf.df_id			= tsoh.df_id
			Where		tso.comp_id		= @comp_id
					and tso.bra_id		= @bra_id
					and tso.soh_id		= @soh_id
					AND tdf.df_SaleOrderEmittion_DeletePendingSO = 'True'





	DELETE FROM tbSaleOrderLoan					WITH (ROWLOCK)
		FROM dbo.tbSaleOrderLoan	tso
		INNER JOIN @tmpSaleOrderToDelete tmp
		ON	tmp.comp_id = tso.comp_id	AND
			tmp.bra_id	= tso.bra_id	AND
			tmp.soh_id	= tso.soh_id	AND
			tmp.sod_id	= tso.sod_id


	Delete dbo.tbSaleOrderTaxes					WITH (ROWLOCK)
		FROM dbo.tbSaleOrderTaxes	tso
		INNER JOIN @tmpSaleOrderToDelete tmp
			ON	tmp.comp_id = tso.comp_id	AND
				tmp.bra_id	= tso.bra_id	AND
				tmp.soh_id	= tso.soh_id	AND
				tmp.sod_id	= tso.sod_id

	Delete dbo.tbSaleOrderDetail				WITH (ROWLOCK)
	FROM dbo.tbSaleOrderDetail		tso
		INNER JOIN @tmpSaleOrderToDelete TMP
			ON	TMP.comp_id = tso.comp_id	AND
				TMP.bra_id	= tso.bra_id	AND
				TMP.soh_id	= tso.soh_id	AND
				TMP.sod_id	= tso.sod_id

	-- -----------------------------------------------------------------


	-- -----------------------------------------------------------------
	-- Si es el primer documento de la financiacion de ventas de terceros,
	-- cambia el documento al de Nota de Debito para que la procese el segundo llamado a fc el pedido
	-- -----------------------------------------------------------------
	IF @df_3rdSales_isAvailable4RegisterSale = 'True'
		BEGIN

			-- Obtengo el documento de Nota de Debito y si no esta retornoi error
			IF @df_3rdSales_df_id4DebitNote IS NULL
				BEGIN
					SELECT	 TOP 1
							 @df_3rdSales_df_id4DebitNote = tdf.df_id
						FROM fnDocumentsFile_GetDocumentsForDebitCreditNotes(@comp_id, @bra_id, @cust_id) tdf
						INNER JOIN tbDocumentsFile tdf2		WITH (NOLOCK)
							ON	tdf2.comp_id	= @comp_id AND
								tdf2.df_id		= tdf.df_id
						WHERE	tdf.sd_isDebitNote						= 1	AND
								tdf.Is4ExchangeDifference				= 0	AND
								tdf2.df_3rdSales_isDebitNoteDocument	= 'True'
						ORDER BY tdf.df_order
				END
			IF @df_3rdSales_df_id4DebitNote IS NULL
				BEGIN
					Set @return_value			= -1
					Set @ret_ErrorCode			= -1
					Set @ret_ErrorDescription	= (	SELECT tut.utexts_desc
					                         			FROM tbsysUniqueTexts tut
					                         	   		WHERE	tut.lang_id		= @lang_id AND
					                         	   				tut.utexts_id	= 382) --'Atención: NO hay definido un documento del tipo Nota de Débito para la sucursal del actual comprobante y la clase fiscal del cliente actual o el mismo NO está configurado para ser débito de una Financiación de Venta de Terceros.'
					RETURN
				END


			UPDATE tbSaleOrderHeader		WITH (ROWLOCK)
				SET		df_id		= @df_3rdSales_df_id4DebitNote,
						soh_inCash	= 0   -- En Efectivo solo va en el primer documento sino hace macanas...
				WHERE	comp_id		= @comp_id	AND
						bra_id		= @bra_id	AND
						soh_id		= @soh_id
		END
	-- -----------------------------------------------------------------




	---- ----------------------------------------------------
	---- Actualiza el tis_id con el que se asigno a su sod_id
	---- *KJH09744TFRX
	---- ----------------------------------------------------
	--UPDATE tbSaleOrderCreditCards
	--	SET		bra_id		= @bra_id,
	--			soh_id		= @soh_id
	--	WHERE	comp_id		= @comp_id	AND
	--			bra_id		= @bra_id	AND
	--			soh_id		= @soh_id
	---- ----------------------------------------------------



	-- ---------------------------------------
	-- Si ya se facturó todo el pedido
	-- ---------------------------------------
	IF NOT EXISTS(
					SELECT TOP 1  1
						FROM	tbSaleOrderDetail tso	WITH (NOLOCK)
						Where	tso.comp_id     = @comp_id
							and tso.bra_id      = @bra_id
							and tso.soh_id	    = @soh_id
	)
		BEGIN


			EXEC spSaleOrderExtendedDiscount_deleteData  @comp_id , @bra_id, @soh_id

			DECLARE @bitCanDeleteSerials AS BIT
			SET		@bitCanDeleteSerials = 'False'
			SELECT  @bitCanDeleteSerials = ISNULL(tdf.df_SaleOrderEmissionWithOutSerialization_DisPlusSerialsCtrlInSO,'False') --IsNull(tdf.df_SaleOrderEmissionWithOutSerialization,'False')
				FROM tbDocumentsFile tdf				WITH (NOLOCK)
				INNER JOIN tbSaleOrderHeader tsoh		WITH (NOLOCK)
					ON	tsoh.comp_id = tdf.comp_id	AND
						tsoh.bra_id  = tdf.bra_id	AND
						tsoh.df_id   = tdf.df_id
				Where	tsoh.comp_id = @comp_id
					and tsoh.bra_id  = @bra_id
					and tsoh.soh_id	 = @soh_id


			-- MOS 12-2013
			-- Solo se pueden borrar seriales no asignados si se especifica en el documento !!!
			IF @bitCanDeleteSerials = 'True'
				BEGIN


					-- Pone como DIDSPONIBLES los numeros de seria a borrar, si es que sobran.!
					UPDATE tbItemSerials			WITH (ROWLOCK)
						SET	is_available = 'True'
						FROM tbItemSerials tis
						INNER JOIN tbSaleOrderSerials tsos		WITH (NOLOCK)
							ON		tsos.comp_id	= tis.comp_id
								AND tsos.is_id		= tis.is_id
					WHERE	tsos.comp_id = @comp_id
						and tsos.bra_id  = @bra_id
						and tsos.soh_id	= @soh_id

					-- Borra los Numeros de Serie que SOBRAN
					DELETE FROM tbSaleOrderSerials
						Where	comp_id = @comp_id
							and bra_id  = @bra_id
							and soh_id	= @soh_id

				END


			 ---------------------------------------------------------
			 -- Borrar esta tabla si se esta borrando el pedido
			 ---------------------------------------------------------
			 IF @intAction = 2
				BEGIN

					-- Borrado del grupo temporal
					Delete		dbo.tbtmpTax
						From    dbo.tbtmpTax					TTAX
						Inner Join dbo.tbTempItemStock			TSTK
							On		TTAX.comp_id = TSTK.comp_id
								and	TTAX.tis_id	 = TSTK.tis_id
						Where	TTAX.comp_id = @comp_id
							and TSTK.bra_id  = @bra_id
							and TSTK.soh_id	 = @soh_id

					DELETE FROM tbSaleOrderLoanTMP				WITH (ROWLOCK)	-- MOS 03-2018
						WHERE tis_guid = @guid


					Delete dbo.tbTempItemStock
						Where	comp_id = @comp_id
							and bra_id  = @bra_id
							and soh_id	= @soh_id

				END
			 ---------------------------------------------------------



			-- INtenta borrar, si no puede es porque sobran Numeros
			BEGIN TRY
				Delete dbo.tbSaleOrderHeader	WITH (ROWLOCK)
					Where	comp_id = @comp_id
						and bra_id  = @bra_id
						and soh_id	= @soh_id
			END TRY
			BEGIN CATCH
				-- Sobran números de serie en el Pedido
				Set @return_value			= -1
				Set @ret_ErrorCode			= -1
				Set @ret_ErrorDescription	= ' - ' +
					(SELECT
					convert(varchar,ERROR_NUMBER())		+ '-' +
					convert(varchar,ERROR_SEVERITY())	+ '-' +
					convert(varchar,ERROR_STATE())		+ '-' +
					convert(varchar,ERROR_LINE())		+ '-' +
					ERROR_MESSAGE())
			END CATCH





		END

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 10-2008
-- Description:	Borra un Pedido
-- =============================================


CREATE PROCEDURE [dbo].[spSaleOrder_deleteDataDirect]
(
	@comp_id					INT,
	@bra_id						INT,
	@soh_id						INT,
	@user_id					INT
)
AS


BEGIN

	SET NOCOUNT ON


	DECLARE @tmpSaleOrderToDelete TABLE (	comp_id INT,
											bra_id INT,
											soh_id INT,
											sod_id INT,
										INDEX tmpSaleOrderToDeleteIDX NONCLUSTERED(comp_id,bra_id,soh_id,sod_id)
									)

	-- MOS 10-2019: Si en SOH dice que borre todo lo pendiente, lo borra.
	INSERT INTO @tmpSaleOrderToDelete(comp_id, bra_id, soh_id, sod_id)
		SELECT DISTINCT tso.comp_id,
						tso.bra_id,
						tso.soh_id,
						tso.sod_id
			FROM dbo.tbSaleOrderDetail		tso			WITH (NOLOCK)
			INNER JOIN tbSaleOrderHeader	tsoh		WITH (NOLOCK)
				ON	tsoh.comp_id		= tso.comp_id	AND
					tsoh.soh_id			= tso.soh_id	AND
					tsoh.bra_id			= tso.bra_id
			Where		tso.comp_id		= @comp_id
					and tso.bra_id		= @bra_id
					and tso.soh_id		= @soh_id



	DELETE FROM tbSaleOrderLoan					WITH (ROWLOCK)
		FROM dbo.tbSaleOrderLoan	tso
		INNER JOIN @tmpSaleOrderToDelete tmp
		ON	tmp.comp_id = tso.comp_id	AND
			tmp.bra_id	= tso.bra_id	AND
			tmp.soh_id	= tso.soh_id	AND
			tmp.sod_id	= tso.sod_id


	Delete dbo.tbSaleOrderTaxes					WITH (ROWLOCK)
		FROM dbo.tbSaleOrderTaxes	tso
		INNER JOIN @tmpSaleOrderToDelete tmp
			ON	tmp.comp_id = tso.comp_id	AND
				tmp.bra_id	= tso.bra_id	AND
				tmp.soh_id	= tso.soh_id	AND
				tmp.sod_id	= tso.sod_id


	EXEC spSaleOrderExtendedDiscount_deleteData  @comp_id , @bra_id, @soh_id

	DELETE FROM tbSaleOrderSerials
		Where	comp_id = @comp_id
			and bra_id  = @bra_id
			and soh_id	= @soh_id


	Delete dbo.tbSaleOrderDetail				WITH (ROWLOCK)
		FROM dbo.tbSaleOrderDetail		tso
		INNER JOIN @tmpSaleOrderToDelete TMP
			ON	TMP.comp_id = tso.comp_id	AND
				TMP.bra_id	= tso.bra_id	AND
				TMP.soh_id	= tso.soh_id	AND
				TMP.sod_id	= tso.sod_id


	Delete dbo.tbSaleOrderHeader	WITH (ROWLOCK)
		Where	comp_id = @comp_id
			and bra_id  = @bra_id
			and soh_id	= @soh_id




END
GO

-- =============================================
-- Author:		MOS, 03-2020
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spSaleOrder_deleteSaleOrder]
@comp_id AS INT,
@bra_id  AS INT,
@soh_id  AS INT



AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


			BEGIN

				--MODIFICAR tambien en : **lergnwerln9835564ergekjb786


				EXEC dbo.spSaleOrderHistory_InsertFromSaleOrder @comp_id, @bra_id, @soh_id, '30',NULL,NULL, ''

				DELETE FROM tbSaleOrderTimes		WITH (ROWLOCK)
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id

				-- ---------------------------------------
				-- Vuelve los numeros de seria a activo
				-- ---------------------------------------
				UPDATE tbItemSerials			WITH (ROWLOCK)
					SET	is_available = 'True'
					FROM tbItemSerials tis
					INNER JOIN tbSaleOrderSerials tsos		WITH (NOLOCK)
						ON	tsos.comp_id= tis.comp_id	AND
							tsos.is_id	= tis.is_id
				WHERE	tsos.comp_id	= @comp_id
					and tsos.bra_id		= @bra_id
					and tsos.soh_id		= @soh_id
				-- y los borra
				DELETE FROM tbSaleOrderSerials		WITH (ROWLOCK)
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id
				-- ---------------------------------------

				DELETE FROM tbSaleOrderCreditCards			WITH (ROWLOCK)
					WHERE	comp_id = @comp_id	AND
							bra_id	= @bra_id	AND
							soh_id	= @soh_id



				DELETE FROM tbSaleOrderAssemblyTurns		WITH (ROWLOCK)
					WHERE	comp_id = @comp_id	AND
							bra_id	= @bra_id	AND
							soh_id	= @soh_id


				DELETE FROM tbSaleOrderExtendedDiscount		WITH (ROWLOCK)
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id

				DELETE FROM tbSaleOrderTaxes				WITH (ROWLOCK)
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id

				DELETE FROM tbSaleOrderLoan					WITH (ROWLOCK)
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id


				DELETE FROM tbSaleOrderEmbarkOK
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id


				DELETE FROM tbSaleOrderExtendedDiscount
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id

				DELETE FROM tbSaleOrderStatus
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id

				DELETE FROM tbSaleOrder4Production
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id


				DELETE FROM tbSaleOrderDetail				WITH (ROWLOCK)
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id

				DELETE FROM tbSaleOrderHeader				WITH (ROWLOCK)
					WHERE	comp_id = @comp_id
					AND		bra_id	= @bra_id
					AND		soh_id	= @soh_id



			END



END
GO







CREATE PROCEDURE [dbo].[spSaleOrder_DivideByItem]
(
		@comp_id				INT,
		@bra_id					INT,
		@soh_id					INT,
		@return_value			INT OUTPUT,
		@ret_ErrorCode			INT OUTPUT,
		@ret_ErrorDescription	VARCHAR(200) OUTPUT
)
AS


BEGIN

	SET NOCOUNT ON


	-- ---------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------------------------------
/*
	DECLARE @return_value			INT
	DECLARE @ret_ErrorCode			INT
	DECLARE @ret_ErrorDescription	VARCHAR(200)


	DROP TABLE #tmpStorage
	DECLARE @comp_id				INT,
			@bra_id					INT,
			@soh_id					INT


	SELECT	@comp_id				= 1,
			@bra_id					= 1,
			@soh_id					= 1263
*/
	-- -----------------------------------------------------------------------------------------------


	SET @return_value			= 0
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''




	DECLARE		@lstor_id_branch	INT,
				@lsoh_id_new		INT,
				@lsod_id			INT,
				@lstor_id			INT,
				@lsod_id_new		INT,
				@lbra_id_new		INT,
				@ldf_id_new			INT,
				@lDf_Id_Original	INT



	--se realiza todo el proceso sólo si el ssos_id del pedido es < 200
	IF EXISTS(SELECT 1
				FROM	tbSaleOrderHeader		tsoh			WITH (NOLOCK)
				WHERE	tsoh.comp_id	= @comp_id
				AND		tsoh.bra_id		= @bra_id
				AND		tsoh.soh_id		= @soh_id
				AND		ISNULL(tsoh.ssos_id,999) < 200)
	BEGIN



		-- Deja Grabado el Stor Id de la sucursal.-
		SELECT @lstor_id_branch = tb.stor_id
			FROM tbBranch tb			WITH (NOLOCK)
			WHERE tb.comp_id =	@comp_id
			AND	  tb.bra_id	 =	@bra_id


		--si (1) y (2)
		IF EXISTS(SELECT 1
			          FROM tbBranch				WITH (NOLOCK)
					  WHERE comp_id							= @comp_id
						AND bra_id							= @bra_id
						AND bra_SaleOrderDivideByStorage	= 'true')

			BEGIN


				IF EXISTS(SELECT 1
							FROM tbSaleOrderDetail tsod				WITH (NOLOCK)
							WHERE tsod.comp_id	=	@comp_id
							 AND  tsod.bra_id	=	@bra_id
							 AND  tsod.soh_id	=	@soh_id
							 AND  tsod.item_id	IS NOT NULL)

					BEGIN


						-- Obtiene el Documento Original del Pedido
						SELECT @lDf_Id_Original = tsoh.df_id
							FROM tbSaleOrderHeader tsoh					WITH (NOLOCK)
							WHERE	tsoh.comp_id	= @comp_id
								AND tsoh.bra_id		= @bra_id
								AND tsoh.soh_id		= @soh_id

						--si (3)
						-- Obtiene la Cantidad Original de Depositos que tiene el Pedido
						SELECT tsod.stor_id, COUNT(*) [count]
							INTO #tmpStorage
							FROM tbSaleOrderDetail tsod				WITH (NOLOCK)
							WHERE	tsod.comp_id	= @comp_id
								AND tsod.bra_id		= @bra_id
								AND tsod.soh_id		= @soh_id
								AND tsod.stor_id    <> @lstor_id_branch
								AND tsod.stor_id    IS NOT NULL				-- Para que NO tome en cuenta Articulos MANUALES.!!
							GROUP BY tsod.stor_id


							-- Si tiene mas de un Deposito
							IF @@ROWCOUNT > 1
								BEGIN



				--SELECT @lstor_id_branch
								--recuperamos en un cursor los direntes storages que componen el pedido
								--diferentes del principal obtenido antes  @lstor_id_branch

								DECLARE cursor_storages CURSOR LOCAL FAST_FORWARD FOR
								SELECT      stor_id
									FROM  tbSaleOrderDetail			WITH (NOLOCK)
									WHERE comp_id	=	@comp_id
									  AND bra_id	=	@bra_id
									  AND soh_id    =	@soh_id
									  AND stor_id <>	@lstor_id_branch
									  AND stor_id  IS NOT NULL
									  AND NOT item_id IS NULL				--elimina los items manuales
									GROUP BY stor_id
									ORDER BY stor_id

								OPEN cursor_storages
				--SELECT 122
								FETCH cursor_storages INTO @lstor_id

								WHILE @@FETCH_STATUS = 0
								BEGIN


									-- Si el deposito a dividir dice que se debe asignar el pedido a otra sucursal, asigna la nueva
									-- de lo contrario usa la actual del pedido a dividir por deposito. (bra_SaleOrderDivideByStorage = True)
									SELECT @lbra_id_new = IsNull(ts.bra_id4DfId_OnDivideByStorage,@bra_id)
										FROM tbStorage ts			WITH (NOLOCK)
										WHERE	ts.comp_id = @comp_id
											AND ts.stor_id = @lstor_id


									--MOs: Verifica si hay otro documento fiscal de las mismas caracteristicas
									--	   en la sucursal de destino.
									SELECT Top 1 @ldf_id_new = tdf2.df_id,
												 @lbra_id_new = tdf2.bra_id
										FROM tbDocumentsFile tdf				WITH (NOLOCK)
										INNER JOIN tbDocumentsFile tdf2			WITH (NOLOCK)
										ON		tdf2.comp_id	= tdf.comp_id
											AND tdf2.sd_id		= tdf.sd_id
											AND tdf2.df_Kindof	= tdf.df_Kindof
										WHERE	tdf.comp_id		= @comp_id
											AND tdf.df_id		= @lDf_Id_Original
											and tdf2.df_id	   <> tdf.df_id
											AND tdf2.bra_id		= @lbra_id_new
										ORDER BY tdf2.df_order





									IF @ldf_id_new IS NULL
									BEGIN
										set @return_value			= -1
										set @ret_ErrorCode			= -1
										set @ret_ErrorDescription	= 'No hay Documentos Fiscales para Dividir el Pedido en la Sucursal definida en Depositos'
										Return
									END


									--					SELECT @lbra_id_new = ISNULL(tdf.bra_id,@bra_id),
									--						   @ldf_id_new  =        tdf.df_id
									--						FROM tbStorage ts
									--						INNER JOIN tbDocumentsFile tdf
									--							ON		tdf.comp_id = ts.comp_id
									--								AND tdf.df_id	= ts.df_id_OnDivideByStorage
									--						WHERE	ts.comp_id = @comp_id
									--							AND ts.stor_id = @lstor_id


									-- obtiene el próximo soh_id des la tabla tbCounters
									EXEC dbo.spCounters_getNextValue @comp_id, @lbra_id_new, 2, @counter_value = @lsoh_id_new OUTPUT


									  --generamos el nuevo pedido para los otros stor_id
									  INSERT INTO tbSaleOrderHeader
									  (
                  						comp_id,                  		bra_id,						soh_id,
                  						soh_cd,							soh_deliveryDate,			soh_observation1,
                  						soh_observation2,				soh_observation3,			soh_observation4,
                  						soh_quotation,		       		sm_id,						cust_id,
                  						st_id,							disc_id,					dl_id,
                  						cb_id,							soh_lastUpdate,				soh_limitDate,
                  						tt_id,							tt_class,					soh_StatusOf,
                  						[user_id],						soh_isEditing,				soh_isEditingCd,
                  						df_id,							soh_total,					ssos_id,
                  						soh_ExchangeToCustomerCurrency,	chp_id,					    soh_PL_df_Id,
                  						soh_CustomerCurrency,			soh_WithCollection,			soh_WithCollectionGUID,
                  						soh_discount,					soh_loan,					soh_packagesQty,
                  						soh_internalAnnotation
									  )

									  SELECT
                  						comp_id,                  		@lbra_id_new,				@lsoh_id_new,
                  						soh_cd,							soh_deliveryDate,			soh_observation1,
                  						soh_observation2,				soh_observation3,			soh_observation4,
                  						soh_quotation,		       		sm_id,						cust_id,
                  						st_id,							disc_id,					dl_id,
                  						cb_id,							soh_lastUpdate,				soh_limitDate,
                  						tt_id,							tt_class,					soh_StatusOf,
                  						[user_id],						soh_isEditing,				soh_isEditingCd,
                  						CASE
                  							WHEN @ldf_id_new is NULL THEN tsoh.df_id
                  							ELSE @ldf_id_new
                  						END [df_id],					soh_total,					ssos_id,
                  						soh_ExchangeToCustomerCurrency,	chp_id,					    soh_PL_df_Id,
                  						soh_CustomerCurrency,			soh_WithCollection,			soh_WithCollectionGUID,
                  						soh_discount,					soh_loan,					soh_packagesQty,
                  						soh_internalAnnotation
									   FROM tbSaleOrderHeader tsoh			WITH (NOLOCK)
									   WHERE tsoh.comp_id	= @comp_id
										AND	 tsoh.bra_id	= @bra_id
										AND	 tsoh.soh_id	= @soh_id


									  --recuperamos el nuevo soh

									 -- SET @lsoh_id_new = @@IDENTITY

									  --recuperamos en otro cursor todos los items del stor_id obtenidos en el cursor anterior

									  DECLARE cursor_items CURSOR LOCAL FAST_FORWARD FOR
									  SELECT      sod_id
										  FROM  tbSaleOrderDetail			WITH (NOLOCK)
										  WHERE comp_id = @comp_id
										  AND bra_id	= @bra_id
										  AND soh_id	= @soh_id
										  AND stor_id	= @lstor_id
										  GROUP BY sod_id

									  OPEN cursor_items
									  FETCH cursor_items INTO @lsod_id

									  WHILE @@FETCH_STATUS = 0
									  BEGIN

											--generamos un nuevo SOD en base a los datos del sod_id obtenido

											INSERT INTO tbSaleOrderDetail
											(
												 comp_id,					bra_id,					soh_id,
												 sod_priority,				item_id,				sod_itemDesc,
												 sod_detail,				curr_id,				sod_initQty,
												 sod_qty,					prli_id,				sod_price,
												 stor_id,					sod_lastUpdate,			sod_isEditing,
												 sod_insertDate,			[user_id],				sod_quotation,
												 sod_isCredit,				sod_cost,				sod_costTax,
												 rmah_id,					rmad_id,				sod_note1,
												 sod_note2,					sod_itemDiscount,		sod_tis_id_origin,
												 sod_item_id_origin,		sod_isParentAssociate,	is_id
											)

											SELECT
												 comp_id,					@lbra_id_new,			@lsoh_id_new,
												 sod_priority,				item_id,				sod_itemDesc,
												 sod_detail,				curr_id,				sod_initQty,
												 sod_qty,					prli_id,				sod_price,
												 stor_id,					sod_lastUpdate,			sod_isEditing,
												 sod_insertDate,			[user_id],				sod_quotation,
												 sod_isCredit,				sod_cost,				sod_costTax,
												 rmah_id,					rmad_id,				sod_note1,
												 sod_note2,					sod_itemDiscount,		sod_tis_id_origin,
												 sod_item_id_origin,		sod_isParentAssociate,	is_id

											FROM tbSaleOrderDetail tsod					WITH (NOLOCK)
											WHERE tsod.comp_id	= @comp_id
											AND	tsod.bra_id		= @bra_id
											AND tsod.sod_id		= @lsod_id


											--recuperamos el nuevo sod_id
											SET @lsod_id_new = @@IDENTITY

											--con el nuevo sod generamos los saleordertaxes existentes del anterior
											INSERT INTO tbSaleOrderTaxes
											(
												 comp_id,       bra_id,		soh_id,
												 sod_id,		tax_id,		tm_total,
												 curr_id,		percentaje
											)

											SELECT
												 comp_id,		@lbra_id_new,		@lsoh_id_new,
												 @lsod_id_new,	tax_id,				tm_total,
												 curr_id,		percentaje

											FROM tbSaleOrderTaxes tsot					WITH (NOLOCK)
											WHERE tsot.comp_id = @comp_id
											AND tsot.bra_id = @bra_id
											AND	tsot.soh_id = @soh_id
											AND tsot.sod_id = @lsod_id


											--eliminar el saleorderLoan anterior

											DELETE FROM tbSaleOrderLoan
											WHERE comp_id	= @comp_id
											AND	  bra_id	= @bra_id
											AND   soh_id	= @soh_id
											AND   sod_id	= @lsod_id

											--eliminar el saleordertaxes anterior

											DELETE FROM tbSaleOrderTaxes
											WHERE comp_id	= @comp_id
											AND	  bra_id	= @bra_id
											AND   soh_id	= @soh_id
											AND   sod_id	= @lsod_id


											--eliminar el saleorderdetail anterior
											DELETE FROM tbSaleOrderdetail
											WHERE comp_id	= @comp_id
											AND	  bra_id	= @bra_id
											AND   soh_id	= @soh_id
											AND   sod_id	= @lsod_id


											FETCH cursor_items INTO @lsod_id
									  END
									  CLOSE cursor_items
									  DEALLOCATE cursor_items



									  FETCH cursor_storages INTO @lstor_id
								END

								CLOSE cursor_storages
								DEALLOCATE cursor_storages

						  END
					END
		END





		-- ----------------------------------------------------------------------
		-- Borra el numero de pedido original si es que no quedaron items en el.-
		IF not EXISTS (SELECT 1
							FROM tbSaleOrderDetail tsod			WITH (NOLOCK)
							WHERE	tsod.comp_id	= @comp_id	AND
									tsod.bra_id		= @bra_id	AND
									tsod.soh_id		= @soh_id)
			BEGIN
				DELETE FROM tbSaleOrderHeader
				WHERE	comp_id = @comp_id
					AND bra_id	= @bra_id
					AND soh_id	= @soh_id
			END
		-- ----------------------------------------------------------------------


	END


END
GO






CREATE PROCEDURE [dbo].[spSaleOrder_Editing]
(
	@comp_id			INT,
	@bra_id				INT,
	@soh_id				INT,
	@packageqty			INT,
	@user_id			INT,
	@request_ip			VARCHAR(100),
	@request_name		VARCHAR(100),
	@return_value		INT OUTPUT
)
As

BEGIN



	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOH
	-- Update Date	: 2010-09-11
	-- Parte		: 550
	-- Description	: Se agregan los nuevos parámetros necesarios para ejecutar el sp spSecurityLog_insertData
	-- =================================================================================================================


-- ----------------------------------------------------
-- Testing
-- ----------------------------------------------------
	/*	Declare @comp_id			int,
				@bra_id				int,
				@soh_id				Int

		Select	@comp_id			= 1,
				@bra_id				= 1,
				@soh_id				= 7202
	*/
-- ----------------------------------------------------


	-- Si hay estados de pedidos que verifican que no se pueda cerrar un pedido y no esten aprobados, no lo cierra.-
	IF EXISTS(
			SELECT TOP 1  1
						FROM tbSaleOrderStatus				tsos2		WITH (NOLOCK)
						INNER JOIN tbSaleOrderStatusConcept tsosc		WITH (NOLOCK)
						ON		tsosc.comp_id	= @comp_id
							AND tsosc.sosc_id	= tsos2.sosc_id
							AND tsosc.sosc_blockSaleOrderPreparationClose = 'True'
					WHERE	tsos2.comp_id		= @comp_id
						AND tsos2.bra_id		= @bra_id
						AND tsos2.soh_id		= @soh_id
						AND tsos2.sos_ok		= 'False'
	)
		BEGIN
			set @return_value = -3
			RETURN
		END

	BEGIN TRANSACTION
	BEGIN TRY

		SET @return_value = 0


		Update	dbo.tbSaleOrderHeader		WITH (ROWLOCK)
			Set		ssos_id =	CASE
									WHEN ssos_id < 100 THEN (select top 1 ssos_id From dbo.vwsysSaleOrderStatus_IsOkForEmmition WITH (NOLOCK))
									WHEN ssos_id = 200 THEN 201
									ELSE ssos_id -- ** si no cierra bien hay que agregar el estado acá
								END,
					soh_isEditing	= 'false',
					soh_packagesQty = @packageqty
			Where	comp_id		= @comp_id
			and		bra_id		= @bra_id
			and		soh_id		= @soh_id



		INSERT INTO tbSaleOrderTimes	WITH (ROWLOCK)
		(
			comp_id,		bra_id,		soh_id,
			sot_cd,			ssot_id,	[user_id]
		)
		VALUES
		(
			@comp_id,		@bra_id,	@soh_id,
			GETDATE(),		40,			@user_id
		)



		DECLARE @rv INT

		EXEC spSecurityLog_insertData
			@comp_id,
			@bra_id,
			@user_id,
			'',
			'',
			'',
			'',
			NULL,
			400,
			NULL,
			@request_ip,
			@request_name,
			NULL,
			NULL,
			NULL,
			NULL,	-- Parte: 550
			NULL,	-- Parte: 550
			NULL,
			NULL,
			NULL,
			NULL,
			@return_value = @rv OUTPUT



		COMMIT TRANSACTION

	END TRY
	BEGIN CATCH

		ROLLBACK TRANSACTION
		set @return_value = -10

	END CATCH


END
GO

CREATE PROCEDURE [dbo].[spSaleOrder_ExistsMloID]
(
	@comp_id				INT,
	@bra_id					INT,
	@mlo_id					INT
)
AS
BEGIN

	SET NOCOUNT ON

	IF EXISTS(	SELECT TOP 1 1
		          	FROM tbSaleOrderDetail AS tsod		WITH (NOLOCK)
		          	WHERE	tsod.comp_id	= @comp_id AND
		          			tsod.bra_id		= @bra_id AND
		          			tsod.mlo_id		= @mlo_id
				)

		OR
		EXISTS(
				SELECT 1
					FROM tbSaleOrderHeader AS tsoh		WITH (NOLOCK)
					WHERE	tsoh.comp_id	= @comp_id	AND
							tsoh.bra_id		= @bra_id	AND
							tsoh.mlo_id		= @mlo_id
				)
		OR  -- MOS 05-2020
		EXISTS(
					SELECT TOP 1  1
					FROM tbItemTransactions AS tit  WITH (NOLOCK)
						WHERE	tit.comp_id	= @comp_id AND
								tit.mlo_id	= @mlo_id
		)
			OR
		EXISTS(
					SELECT TOP 1  1
					FROM tbCommercialTransactions  AS tit  WITH (NOLOCK)
						WHERE	tit.comp_id	= @comp_id AND
								tit.mlo_id	= @mlo_id
				)
		BEGIN
			SELECT 1	[result]
		END
	ELSE
		BEGIN
			SELECT 0	[result]
		END

END
GO






