CREATE PROCEDURE [dbo].[spSaleOrder_getData_Sales4Category]
(
	@comp_id	INT,
	@bra_id		INT,
	@lang_id	INT,
	@user_id	INT,
	@cust_id	INT,
	@df_id		INT
)
AS


BEGIN

	--------------------------------------------------------------------------------------------------
	-- Test
	--------------------------------------------------------------------------------------------------
	/*
		DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@lang_id	INT,
				@cust_id	INT,
				@df_id		INT,
				@user_id	INT

		SELECT	@comp_id	= 1,
				@bra_id		= 1,
				@lang_id	= 2,
				@cust_id	= 24294,
				@df_id		= 4,
				@user_id	= 3
		*/

	--------------------------------------------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON;


	DECLARE @dateFrom AS DATETIME

	SELECT @dateFrom = dateadd(  day , - tdf.df_SaleOrderPurchaseHistoryDays,GETDATE())
	FROM tbDocumentsFile tdf
		WHERE	tdf.comp_id = @comp_id AND
				tdf.df_id	= @df_id
	SET @dateFrom = dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'False')


		--DECLARE @ldf_SaleOrderPurchaseHistoryDays AS INT

		--set @ldf_SaleOrderPurchaseHistoryDays = (
		--											SELECT
		--												df_SaleOrderPurchaseHistoryDays
		--												FROM tbDocumentsFile tdf
		--												WHERE	tdf.comp_id = @comp_id	AND
		--														tdf.bra_id	= @bra_id	AND
		--														tdf.df_id	= @df_id
		--										)

		--DECLARE @fromDate as DATETIME
		--SET		@fromDate		= GETDATE() - @ldf_SaleOrderPurchaseHistoryDays


	SELECT
		convert(varchar,year(tct.ct_date))				[Year],
		convert(varchar,month(tct.ct_date))				[Month],
		--ti.item_desc									[item_desc],
		convert(decimal(10,0),sum(tit.it_qty))			[it_qty],
		tc.cat_desc										[cat_desc]

		FROM tbCommercialTransactions					tct			WITH (NOLOCK)


		INNER JOIN tbDocumentsFile						tdf			WITH (NOLOCK)
		ON	tdf.comp_id			= tct.comp_id		AND
			tdf.bra_id			= tct.bra_id		AND
			tdf.df_id			= tct.df_id

		INNER JOIN tbUsers4BranchFilter					 vubf		WITH (NOLOCK)
		 ON  vubf.comp_id		= tct.comp_id			AND
			 vubf.bra_id		= tct.bra_id			AND
			 vubf.[user_id]		= @user_id

		INNER JOIN tbItemTransactions					tit			WITH (NOLOCK)
		ON	tit.comp_id			= tct.comp_id		AND
			tit.bra_id			= tct.bra_id		AND
			tit.ct_transaction	= tct.ct_transaction

		INNER JOIN tbItem								ti			WITH (NOLOCK)
		ON	ti.comp_id			= tit.comp_id		AND
			ti.item_id			= tit.item_id

		INNER JOIN tbCategory							tc			WITH (NOLOCK)
		ON	tc.comp_id			= ti.comp_id		AND
			tc.cat_id			= ti.cat_id


		WHERE	tct.comp_id		= @comp_id			AND
				--tct.bra_id		= @bra_id			AND
				tct.cust_id		= @cust_id			AND
				--tdf.df_id		= @df_id
				--AND
				tct.ct_date		BETWEEN  @dateFrom and GETDATE()	AND
				(tct.sd_id = 1 OR tct.sd_id = 2)		-- Solo Facturas o Remitos


		GROUP BY tc.cat_desc,year(tct.ct_date),month(tct.ct_date)

		ORDER BY year(tct.ct_date),month(tct.ct_date)
END




GO



