CREATE PROCEDURE [dbo].[spSaleOrder_getData_Sales4Category_SaleOrderInGrid]
(
	@comp_id	INT,
	@bra_id		INT,
	@lang_id	INT,
	@user_id	INT,
	@tis_guid   UNIQUEIDENTIFIER
)
AS

BEGIN

	--------------------------------------------------------------------------------------------------
	-- Test
	--------------------------------------------------------------------------------------------------
	/*
		DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@lang_id	INT,
				@cust_id	INT,
				@df_id		INT,
				@user_id	INT,
				@tis_guid   UNIQUEIDENTIFIER

		SELECT	@comp_id	= 1,
				@bra_id		= 1,
				@lang_id	= 2,
				@cust_id	= 24294,
				@df_id		= 4,
				@user_id	= 3,
				@tis_guid	= 'D199FB32-4D64-4A4E-85C4-9864BB29EB69'

*/
	--------------------------------------------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON;




	SELECT
		convert(decimal(10,0),sum(tis.tis_qty))			[it_qty],
		tc.cat_desc										[cat_desc]

		FROM tbTempItemStock							tis			WITH (NOLOCK)

		INNER JOIN tbUsers4BranchFilter					vubf		WITH (NOLOCK)
		 ON  vubf.comp_id		= tis.comp_id		AND
			 vubf.bra_id		= tis.bra_id		AND
			 vubf.[user_id]		= @user_id

		INNER JOIN tbItem								ti			WITH (NOLOCK)
		ON	ti.comp_id			= tis.comp_id		AND
			ti.item_id			= tis.item_id

		INNER JOIN tbCategory							tc			WITH (NOLOCK)
		ON	tc.comp_id			= ti.comp_id		AND
			tc.cat_id			= ti.cat_id

		WHERE	tis.comp_id		= @comp_id			AND
				tis.tis_guid	= @tis_guid


		GROUP BY tc.cat_desc
END




GO



