-- MOS 06-2024: Filtro de Colecta



CREATE PROCEDURE [dbo].[spSaleOrder_getDataByFilters]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@sm_id				int,
	@cust_id			int,
	@dl_id				int,
	@Item_id			int,
	@cat_id				int,
	@subcat_id			Int,
	@option				INT,
	@custom				INT,
	@stor_id			INT,
	@st_id				INT,
	@str_serial			nvarchar(100),
	@ss_id				INT,				-- Area de ventas del cliente
	@prof_id			INT,
	@datFromDate		DATETIME,
	@datToDate			DATETIME,
	@df_id				INT,				-- -1:Todos, -2: Todos los pedidos que no sean de tiendas
	@sops_id			INT	,				-- -1: Con/Sin Motivos asignados , 0 : Sin Motivos asignados , 1 : Con Motivos asignados
	@fastSearch			BIT	,				-- Deprecated, se hace en el prerender de la pagina.
	@ssos_id			INT,				-- Tipo de Pedido
	@ss_id_cb_id		INT,				-- Area de ventas de la sucursal del cliente
	@mls_id				INT,				-- Tienda de ML
	@datFromDateItem	DATETIME,			-- Desde Fecha de Entrega del Artículo
	@datToDateItem		DATETIME,			-- Hasta Fecha de Entrega del Artículo
	@delivery_type		INT,				-- Envío
	@estado				INT,					-- Pendiente de Autorizacion
	@col_id				INT					-- MOS 06-2024: Colecta
)
as



BEGIN


	set nocount on
	SET DATEFORMAT 'ymd'

	-- --------------------------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------------------------
/*
	declare 	@comp_id			int,
				@lang_id			int,
				@bra_id				int,
				@sm_id				int,
				@cust_id			int,
				@dl_id				int,
				@Item_id			int,
				@cat_id				int,
				@subcat_id			Int,
				@option				int,
				@custom				INT,
				@stor_id			INT,
				@st_id				INT,
				@str_serial			nvarchar(100),
				@ss_id				INT,
				@prof_id			int,
				@datFromDate		DATETIME,
				@datToDate			DATETIME,
				@df_id				INT,
				@sops_id			INT



	select		@comp_id			=  1,
				@lang_id			=  2,
				@bra_id				= 1,
				@sm_id				= -1,
				@cust_id			= -1,
				@dl_id				= -1,
				@Item_id			= -1,
				@cat_id				= -1,
				@subcat_id			= -1,
				@option				= 20,
				@custom				= -1,
				@stor_id			= -1,
				@st_id				= -1,
				@str_serial			= '',
				@ss_id				= -1,
				@prof_id			= 1,
				@datFromDate		= '1900-01-01',
				@datToDate			= '2999-01-01',
				@df_id				= -1,
				@sops_id			= -1

	--DROP TABLE #tmpSerial
*/
	-- --------------------------------------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 100
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------

	-- -----------------------------------------------------------------------------
	-- -----------------------------------------------------------------------------
	SET @datFromDate	= dbo.fnGetEnd_or_BeginOfDate(@datFromDate,'False')
	SET @datToDate		= dbo.fnGetEnd_or_BeginOfDate(@datToDate,'True')

	DECLARE @bitDeliveryDateActivated AS BIT = 'False'
	IF YEAR(@datFromDateItem) <> 1900 OR YEAR(@datToDateItem)  <> 9999
		BEGIN
			SET @bitDeliveryDateActivated	= 'True'
			SET @datFromDateItem			= dbo.fnGetEnd_or_BeginOfDate(@datFromDateItem,'False')
			SET @datToDateItem				= dbo.fnGetEnd_or_BeginOfDate(@datToDateItem,'True')
		END
	-- -----------------------------------------------------------------------------






	-- -----------------------------------------------------------------------------
	-- Carga UNICAMENTE  los depositos q le correspondan
	-- -----------------------------------------------------------------------------
	DECLARE @tmpStorage  TABLE(stor_id INT NULL, UNIQUE NONCLUSTERED (stor_id) )

	IF @stor_id <> -1	-- Solo el deposito solicitado
		BEGIN
			INSERT INTO @tmpStorage(stor_id) VALUES (@stor_id)
		END
	ELSE
		BEGIN
			IF EXISTS(	SELECT TOP 1  1
			          		FROM tbStorage4Profile tsp	WITH (NOLOCK)
			          		WHERE	tsp.comp_id = @comp_id AND
			          				tsp.prof_id = @prof_id)
				BEGIN	-- Todos los depositos q tiene definidos x perfil
					INSERT INTO @tmpStorage(stor_id)
						SELECT tsp.stor_id
							FROM tbStorage4Profile tsp	WITH (NOLOCK)
			          			WHERE	tsp.comp_id = @comp_id AND
			          					tsp.prof_id = @prof_id
				END
			ELSE
				BEGIN
					INSERT INTO @tmpStorage(stor_id)	-- Todos los depositos
						SELECT ts.stor_id FROM tbStorage ts	WITH (NOLOCK) WHERE ts.comp_id = @comp_id
				END
		END
	-- Inserta el deposito NULL para loa articulos manuales.!
	IF NOT EXISTS(SELECT TOP 1 1 FROM @tmpStorage WHERE stor_id IS null)
		BEGIN
			INSERT INTO @tmpStorage(stor_id) VALUES (NULL)
		END
	-- -----------------------------------------------------------------------------


	-- ---------------------------------------------------------------------
	-- Pone en la tabla temporal el numero de pedido de ese numero de serie
	-- ---------------------------------------------------------------------
	DECLARE @tblSaleOrderSerials AS TABLE(comp_id INT,bra_id INT, soh_id INT, is_serial NVARCHAR(100) )
	IF @str_serial <> ''
		BEGIN
			INSERT INTO @tblSaleOrderSerials (comp_id, bra_id, soh_id, is_serial)
				SELECT tsos.comp_id, tsos.bra_id, tsos.soh_id,tis.is_serial
     				FROM tbSaleOrderSerials tsos	WITH (NOLOCK)
					INNER JOIN tbItemSerials tis	WITH (NOLOCK)
						ON	tis.comp_id = tsos.comp_id AND
							tis.is_id	= tsos.is_id
     				WHERE
     					tsos.comp_id	= @comp_id	AND
     					tis.is_serial	= @str_serial
		END
	-- ---------------------------------------------------------------------







	-- --------------------------------------------------------------
	-- Pedidos que NO deban Prepararse x estados pendientes de autorizar
	-- --------------------------------------------------------------
	DECLARE @tblSaleOrderStatus AS TABLE(	comp_id INT,
											bra_id	INT,
											soh_id	INT)
	INSERT INTO @tblSaleOrderStatus (comp_id, bra_id, soh_id)
		SELECT distinct tsos2.comp_id,
						tsos2.bra_id,
						tsos2.soh_id
			FROM tbSaleOrderStatus tsos2					WITH (NOLOCK)
			INNER JOIN tbSaleOrderStatusConcept tsosc		WITH (NOLOCK)
			ON		tsosc.comp_id	= tsos2.comp_id
				AND tsosc.sosc_id	= tsos2.sosc_id
				AND tsosc.sosc_blockSaleOrderPreparation = 'True'
		WHERE	tsos2.comp_id		= @comp_id
			--AND tsos2.bra_id		= soh.bra_id
			--AND tsos2.soh_id		= soh.soh_id
			AND tsos2.sos_ok		= 'False'
	-- --------------------------------------------------------------


	-- --------------------------------------------------------------
	-- Pedidos con Numeros de serie DIRECTOS
	-- --------------------------------------------------------------
	DECLARE @tblSODWithDirectSerial AS TABLE(	comp_id INT,
												bra_id	INT,
												soh_id	INT)

	INSERT INTO @tblSODWithDirectSerial
		(comp_id,bra_id,soh_id)
		SELECT DISTINCT tsod.comp_id,tsod.bra_id,tsod.soh_id
			FROM tbSaleOrderDetail tsod		WITH (NOLOCK)
			where not is_id is NULL
	-- --------------------------------------------------------------




	select
			CASE
				WHEN exists(SELECT TOP 1 1
								FROM @tblSODWithDirectSerial tmpR
								WHERE	tmpr.comp_id= soh.comp_id
									and tmpr.bra_id = soh.bra_id
									AND tmpR.soh_id = SOH.soh_id) THEN		1
				ELSE														0
			END								[ ],
			ISNULL(tmls.mls_accessToken,'')	[ ],
			ISNULL(tmlos.MLshippingID,0)	[ ],
			vsos.ssos_desc,
			BRA.[bra_desc],
			dbo.fnGetSaleOrderNumber(soh.comp_id,soh.bra_id,soh.soh_id)  [soh_id],
			CASE
				WHEN	tcb.custb_name IS NULL THEN cu.cust_name
				ELSE	tcb.custb_name
			END		+ ' (' + CONVERT( varCHAR(20), cu.cust_id ) + ')'											[cust_name] ,
			--CU.[cust_name],
			soh.soh_deliveryDate,

			(SELECT TOP 1
				tsoat.soa_turnDate
				FROM tbSaleOrderAssemblyTurns							tsoat
				WHERE	tsoat.comp_id					= soh.comp_id	AND
						tsoat.soh_bra_id				= soh.bra_id	AND		-- MOS 23-04-2020
						tsoat.soh_id					= soh.soh_id	AND
				ISNULL(tsoat.soa_isAssembled,'False')	= 'False'
				ORDER BY tsoat.soa_turnDate DESC)			[soa_turnDate],
			soh.soh_lastUpdate,

			SOH.soh_internalAnnotation,
			DL.[dl_name],
			tst.st_desc,
			SM.[sm_name],
			tss.ss_desc,
			tov.optval_desc,
			sum(SOD.sod_qty)								[sod_qty],


			-- ----------------------------------------------------------------------------
			-- Ultimo!!!!   OJOOOOOOO, no poner nada debajo de esto sin autorizacion de MOS
			-- ----------------------------------------------------------------------------
			CASE
				WHEN tmloh.mlo_status		= 'cancelled'										THEN 2222
				WHEN tmlos.MLturbo			= 'True' AND tmloh.mlo_status = 'delivered'			THEN 3334
				WHEN tmlos.MLturbo			= 'True' 											THEN 3333
				WHEN tmlos.MLfulfilled		= 'True' AND tmloh.mlo_status = 'delivered'			THEN 10
				WHEN tmlos.MLfulfilled		= 'True'											THEN 11
				WHEN tmlos.MLSelf_Service	= 'True' AND tmloh.mlo_status = 'delivered'			THEN 20
				WHEN tmlos.MLSelf_Service	= 'True' 											THEN 21
				WHEN ISNULL(tmlos.MLshippingID,30) = 0	AND tmloh.mlo_status = 'delivered'		THEN 30	-- retira en local, entregado
				WHEN ISNULL(tmlos.MLshippingID,30) = 0											THEN 31	-- retira en local
				WHEN tmloh.mlo_id > 0															THEN 40 -- Es pedido de Meli
				ELSE																				 0
			END																					[mlo_status],			-- Count - 8
			--ISNULL(tmloh.mlo_status,'')				[mlo_status],		-- Count - 8


			CASE
				WHEN ISNULL(soh.soh_isPrintedFromSOPreparation,'False') = 'True' THEN '*'
				ELSE ''
			END										[soh_isPrinted],	-- Count - 7
			CASE
				WHEN tdf.df_SaleOrder_IsInvoiceFirstPacking = 1 THEN		(
																				SELECT	TOP 1  -- MOS 31-05-2021
																							ISNULL(	CASE
																										WHEN tct.sd_id = 1 AND tct.ct_ABalance = 0 THEN tdf.sd_id
																										ELSE											100001		-- Fc Anticipada NO PAGA
																									END,tdf.sd_id)
																					FROM	tbCommercialTransactions AS tct	WITH (NOLOCK)
																					WHERE	tct.comp_id			= soh.comp_id	AND
																							tct.ct_soh_bra_id	= soh.bra_id	AND
																							tct.ct_soh_id		= soh.soh_id
																			)
				ELSE tdf.sd_id
			END									[sd_id],			-- Count - 6
			CONVERT(BIT,
						CASE
							WHEN EXISTS(SELECT TOP 1  1
											FROM tbSaleOrderSerials tsos			WITH (NOLOCK)
											WHERE	tsos.comp_id	= soh.comp_id
												AND tsos.bra_id		= soh.bra_id
												AND tsos.soh_id		= soh.soh_id )  THEN	1
							ELSE															0
						END
					)							[is],				-- 14, count - 5
			soh.ssos_id,											-- 15, count - 4


			--CASE -- Deprecvated, se hace en el PreRender de la PAgina
			--	WHEN @fastSearch = 'True' THEN 9
			--	ELSE dbo.fnSaleOrderGetStockStatus(@comp_id,soh.bra_id,soh.soh_id)
			--END
			CASE
				WHEN soh.ws_internalID IS NOT NULL	THEN 10
				WHEN soh.mlo_id		   IS NOT NULL	THEN 20
				-- MOS 10-2021 x MULTIPLICACION
				--WHEN sod.rmad_id	   IS NOT NULL THEN 30
				WHEN
						EXISTS(
								SELECT TOP 1 1
									FROM dbo.tbSaleOrderDetail		SOD2		WITH (NOLOCK)
									where	SOH.[comp_id]	= SOD2.[comp_id]	AND
											SOH.[bra_id]	= SOD2.[bra_id]		AND
											SOH.[soh_id]	= SOD2.[soh_id]		AND
											sod2.rmad_id	   IS NOT NULL
								)					THEN 30


				ELSE									1
			END																		[Color], -- Count - 3 --Parte 193 Aca devuelve el valor que será 1 : Verde, 2 : Amarillo y 3 : Rojo     Count - 3
			CASE
				WHEN tcw.cust_id is NULL THEN	2
				ELSE							1
			END																		[CustomerWaiting],	-- Count - 2
			convert(varchar,@comp_id) + '-' +	--Modificado por Sebastian, se borro el guion para controlar un error de conversion
			convert(varchar,SOH.bra_id) + '-' +
			convert(varchar,SOH.soh_id)				[ID]			-- Count - 1


	from	dbo.tbSaleOrderHeader					SOH		WITH (NOLOCK)

			INNER JOIN  dbo.tbSaleOrderDetail		SOD		WITH (NOLOCK)
				on  SOH.[comp_id]	= SOD.[comp_id]
				and SOH.[bra_id]	= SOD.[bra_id]
				and SOH.[soh_id]	= SOD.[soh_id]

			INNER JOIN @tmpStorage tmps
				ON tmps.stor_id = sod.stor_id

			INNER JOIN tbSalesTerms tst						WITH (NOLOCK)
				ON	tst.comp_id = soh.comp_id AND
					tst.st_id	= soh.st_id


			Inner Join tbDocumentsFile				tdf		WITH (NOLOCK)
				On  tdf.comp_id = soh.comp_id
				And tdf.df_id	= soh.df_id

			inner join dbo.tbBranch					BRA		WITH (NOLOCK)
				on  BRA.[comp_id]	= SOH.[comp_id]
				and BRA.[bra_id]	= SOH.[bra_id]

			inner join dbo.tbCustomer				CU		WITH (NOLOCK)
				ON  CU.[comp_id]	= SOH.[comp_id]
				AND CU.[cust_id]	= SOH.[cust_id]

			LEFT JOIN tbSaleSector					tss		WITH (NOLOCK)
				ON  tss.comp_id		= CU.comp_id
				AND tss.ss_id		= CU.ss_id

			LEFT JOIN tbCustomerBranch				tcb		WITH (NOLOCK)
				ON	tcb.comp_id = soh.comp_id
				AND tcb.cust_id = soh.cust_id
				AND tcb.cb_id	= soh.cb_id

			left join dbo.tbSalesman				SM		WITH (NOLOCK)
				on  SM.[comp_id]	= SOH.[comp_id]
				and SM.[sm_id]		= SOH.[sm_id]

			left join dbo.tbDelivery				DL		WITH (NOLOCK)
				on  DL.[comp_id]	= SOH.[comp_id]
				and DL.[dl_id]		= SOH.[dl_id]

			left join dbo.tbItem					IT		WITH (NOLOCK)
				on  IT.[comp_id]	= SOD.[comp_id]
				and IT.[item_id]	= SOD.[Item_id]

			left join dbo.tbCategory				CT		WITH (NOLOCK)
				on	CT.[comp_id]	= IT.[comp_id]
				and CT.[cat_id]		= IT.[cat_id]

			LEFT JOIN tbSubCategory					SCT		WITH (NOLOCK)
				ON	SCT.[comp_id]	=	IT.[comp_id]
				AND SCT.[cat_id]	=	IT.[cat_id]
				AND SCT.[subcat_id]	=	IT.[subcat_id]


			--Parte 660 Join a la tabla CustomerWaiting para saber si pinto de Azul la celda del cliente

			LEFT JOIN tbCustomerWaiting			tcw			WITH (NOLOCK)
				ON tcw.comp_id		= soh.comp_id
				AND tcw.bra_id		= soh.bra_id
				AND tcw.cust_id		= soh.cust_id


			-- Hay que ser muy HDP para hacer esto !!!!!!!  04-2020   se paso abajo al where
			--inner Join (
			--				Select ssos_id
			--					From  vwsysSaleOrderStatus_ForPreparation	WITH (NOLOCK)
			--					Union all
			--				Select ssos_id
			--					From  vwsysSaleOrderStatus_IsOkForEmmition	WITH (NOLOCK)
			--					UNION ALL
			--				Select ssos_id
			--					From  vwsysSaleOrderStatus_RMA4Preparation	WITH (NOLOCK)
			--					UNION ALL
			--				Select ssos_id
			--					From  vwsysSaleOrderStatus_RMAPrepared		WITH (NOLOCK)
			--			) vsosfp
			--	On vsosfp.ssos_id		=	soh.ssos_id

			Inner Join tbsysOptionsValues tov								WITH (NOLOCK)
				On tov.lang_id				=@lang_id
				And tov.optval_class		=53
				AND	(
						((soh.ssos_id = 20  OR soh.ssos_id = 200) and (tov.optval_id = 20))	OR
						((soh.ssos_id = 50  OR soh.ssos_id = 201) and (tov.optval_id = 50))
					)


			LEFT JOIN vwSaleOrderStatus			vsos						WITH (NOLOCK)
				ON	vsos.comp_id	= soh.comp_id
				AND vsos.bra_id		= soh.bra_id
				AND vsos.soh_id		= soh.soh_id
				AND vsos.lang_id	= @lang_id


			LEFT JOIN @tblSaleOrderStatus tsos2
				ON	tsos2.comp_id	= soh.comp_id	AND
					tsos2.bra_id	= soh.bra_id	AND
					tsos2.soh_id	= soh.soh_id


			LEFT JOIN tbMercadoLibre_ordersHeader	tmloh				WITH (NOLOCK)
				ON	tmloh.comp_id	= soh.comp_id	AND
					tmloh.mlo_id	= soh.mlo_id

			LEFT JOIN tbMercadoLibre_Branchs		tmlb				WITH (NOLOCK)
				ON	tmlb.comp_id	= tmloh.comp_id AND
					tmlb.mlbra_id	= tmloh.mlbra_id

			LEFT JOIN tbMercadoLibre_ordersShipping tmlos				WITH (NOLOCK)
				ON	tmlos.comp_id	= tmloh.comp_id	AND
					tmlos.mlo_id	= tmloh.mlo_id

			LEFT JOIN tbMercadoLibre_Stores AS tmls						WITH (NOLOCK)
				ON	tmls.comp_id = tmloh.comp_id AND
					tmls.mls_id	 = tmloh.mls_id



	Where	SOH.comp_id		=   @comp_id
	AND		( soh.ssos_id = 20 OR soh.ssos_id = 50 OR soh.ssos_id = 200 OR soh.ssos_id = 201 )  -- del Inner Join de MIERDA con las Vistas de arriba
	AND		(@bra_id		=   -1  OR 	SOH.bra_id		=   @bra_id		)
	AND		(@sm_id			=   -1  OR 	SOH.sm_id		=	@sm_id		)
	AND		(@cust_id		=   -1  OR	SOH.cust_id		=	@cust_id	)
	AND		(@dl_id			=   -1	OR	SOH.dl_id		=	@dl_id		)
	AND		(@Item_id		=   -1	OR	SOD.Item_id		=	@Item_id	)
	AND		(@cat_id		=   -1  OR	IT.[cat_id]		=	@cat_id		)
	AND		(@subcat_id		=   -1  OR	IT.[subcat_id]	=	@subcat_id	)
	AND		soh.soh_deliveryDate BETWEEN @datFromDate AND @datToDate

	AND		(@st_id			=   -1  OR  soh.st_id		=	@st_id		)
	AND     (@custom		=   -1  OR NOT tcw.cust_id	IS NULL)
	AND 	(
				 @option = -1														OR
				(@option = 20 and (soh.ssos_id = @option OR soh.ssos_id = 200 ))	OR
				(@option = 50 and (soh.ssos_id = @option OR soh.ssos_id = 201 ))
			)
	AND 	soh_isEditing	=	'False'
	AND	    (tdf.sd_id = 1 OR tdf.sd_id = 2 OR tdf.sd_id = 3 OR tdf.sd_id = 80 OR tdf.sd_id = 31)   -- MOS: 08-2010 Solamente pedidos para generar Fc,Nc,Rm
	AND     IsNull(cu.cust_inactive,'False') = 'False'

	AND (
			CASE
			    WHEN @str_serial = ''  THEN 1
			    WHEN
					EXISTS(	SELECT TOP 1  1
		         				FROM @tblSaleOrderSerials tsos
		         				WHERE
		         					tsos.comp_id	= soh.comp_id	AND
		         					tsos.bra_id		= soh.bra_id	AND
		         					tsos.soh_id     = soh.soh_id	AND
		         					tsos.is_serial	= @str_serial

						  ) THEN	1
			    ELSE				0
			END	= 1
		)

	--AND ( @ss_id		= -1 OR CU.ss_id	= @ss_id )		-- MOS 07-2020
	AND ( @ss_id		= -1 OR ISNULL(tcb.ss_id ,CU.ss_id)	= @ss_id )
	AND	( @ss_id_cb_id	= -1 OR tcb.ss_id	= @ss_id_cb_id )					-- AREA DE VENTAS DE LA SUCURSAL DEL CLIENTE ticket 9982



	-- --------------------------------------------------------------------------------------
	-- Que no tenga estados de Preparacion de pedidos Pëndientes que bloqueen la preparacion.-
	-- OJO que esto no ponga lento todo.!
	-- MOS: 01-2012
	-- --------------------------------------------------------------------------------------
	AND tsos2.comp_id IS NULL

	-- --------------------------------------------------------------------------------------

	AND		CASE
				WHEN @df_id		= -1		THEN 1
				WHEN @df_id		= soh.df_id	THEN 1
				ELSE							 0
			END	= 1

	AND		CASE
	   		    WHEN @sops_id = -1								THEN 1
	   		    WHEN @sops_id = 0  AND sod.sops_id IS NULL		THEN 1
	   		    WHEN @sops_id = 1  AND sod.sops_id IS NOT NULL	THEN 1
	   		    ELSE											     0
	   		END = 1


		-- -----------------------------------------------
		-- Todo esto es MIERDA LENTA
		-- -----------------------------------------------
		AND

		CASE
			WHEN @ssos_id = 0													THEN 1
			WHEN @ssos_id = 3		AND soh.ws_internalID IS NOT NULL			THEN 1
			WHEN @ssos_id = 200		AND sod.rmad_id IS NOT NULL					THEN 1
			WHEN @ssos_id = 1003	AND tdf.sd_id = 80							THEN 1
			WHEN @ssos_id = 2000	AND soh.mlo_id IS NOT NULL					THEN 1
			WHEN @ssos_id = 2030	AND 	tmloh.comp_id IS NOT NULL		AND
											tmlos.MLfulfilled	= 'True'	AND
											tmlos.MLstatus		= 'delivered'
																				THEN 1		--MercadoLibre©: FulFillment Entregados
			WHEN @ssos_id = 2066	AND 	tmloh.comp_id IS NOT NULL		AND
											tmlos.MLturbo		= 'True'
										     									THEN 1		-- MercadoLibre©: Entrega TURBO
			WHEN @ssos_id = 2060	AND 	tmloh.comp_id IS NOT NULL		AND
											tmlos.MLSelf_Service= 'True'
										     									THEN 1		-- MercadoLibre©: Entrega Flex
			WHEN @ssos_id = 2070	AND 	tmloh.comp_id IS NOT NULL		AND
											tmlb.comp_id  IS NOT NULL
										     									THEN 1		-- MercadoLibre©: Retiro en Sucursal

			WHEN @ssos_id = 2075	AND 	tmloh.comp_id IS NOT NULL		AND
											tmlb.comp_id  IS     NULL		AND
											ISNULL(tmloh.MLShippingID,0) = 0
										     									THEN 1		-- MercadoLibre©: Retiro en LOCAL
			-- NUEVOS MOS 09-2021
			WHEN	@ssos_id			= 101			AND
					soh.ws_internalID	IS NOT NULL		AND
					soh.ssos_id			= 50			AND
					soh.ws_paymentGateWayStatusID	= 51			THEN 1
			WHEN	@ssos_id			= 102			AND
					soh.ws_internalID	IS NOT NULL		AND
					soh.ssos_id			<> 50			AND
					soh.ws_paymentGateWayStatusID	= 51			THEN 1
			WHEN	@ssos_id			= 103			AND
					soh.ws_internalID	IS NOT NULL		AND
					soh.ws_paymentGateWayStatusID	= 50			THEN 1
			WHEN @ssos_id = soh.ssos_id								THEN 1  --4,5,2
			-- NUEVOS MOS 09-2021

			ELSE 0
		END = 1																						 -- TODOS los pedidos que NO SEAN ABONOS:!!!!!
		AND (@mls_id = -1 OR tmloh.mls_id = @mls_id)
		-- MOS 07-2021
		AND	CASE
				WHEN @bitDeliveryDateActivated = 'False'																THEN 1
				WHEN EXISTS(	SELECT TOP 1 1
				            		FROM tbSaleOrderDetail AS tsoda WITH (NOLOCK)
				            		WHERE
										tsoda.comp_id	= soh.comp_id	AND
		         						tsoda.bra_id	= soh.bra_id	AND
		         						tsoda.soh_id    = soh.soh_id	AND
		         						tsoda.sod_itemDeliveryDate BETWEEN @datFromDateItem	AND @datToDateItem
							)																							THEN 1
				ELSE																										 0
			END = 1
		AND	CASE
				WHEN	@delivery_type = -1																				THEN 1
				WHEN EXISTS(	SELECT TOP 1 1
				            		FROM tbSaleOrderDetail AS tsoda WITH (NOLOCK)
				            		WHERE
										tsoda.comp_id	= soh.comp_id	AND
		         						tsoda.bra_id	= soh.bra_id	AND
		         						tsoda.soh_id    = soh.soh_id	AND
		         						tsoda.sdlmt_id  = @delivery_type
							)																							THEN 1
				ELSE																										 0
			END = 1
		AND		(
					CASE
						WHEN @estado = -1														THEN 1
						WHEN @estado =  1 AND  EXISTS(	SELECT TOP 1  1
															FROM tbSaleOrderStatus tsos			WITH (NOLOCK)
					                              			WHERE	tsos.comp_id	= soh.comp_id
					                              				AND tsos.bra_id		= soh.bra_id
					                              				AND tsos.soh_id		= soh.soh_id
					                              				AND tsos.sos_ok		= 'False')	THEN 1 --  Pendientes de Autorizacion.
						WHEN @estado =  2 AND NOT EXISTS(	SELECT TOP 1 1
															FROM tbSaleOrderStatus tsos			WITH (NOLOCK)
					                              			WHERE	tsos.comp_id	= soh.comp_id
					                              				AND tsos.bra_id		= soh.bra_id
					                              				AND tsos.soh_id		= soh.soh_id
					                              				AND tsos.sos_ok		= 'False')	THEN 1 --  Pendientes de Autorizacion.
						ELSE																		 0
					END	 = 1
				)
		AND
				(
					CASE
						WHEN @col_id = -1 THEN 1
						WHEN EXISTS	(
										SELECT TOP 1 1
											FROM tbSaleOrderCollectDetail AS tsocd WITH (NOLOCK)
											WHERE	tsocd.comp_id		= soh.comp_id	AND
													tsocd.soh_bra_id	= soh.bra_id	AND
													tsocd.soh_id		= soh.soh_id
									)     THEN 1
						ELSE				   0
					END = 1
				)

	group by	-- NO USAR TABLAS QUE MULTIMPLIQUEN como tbSaleOrderDetail en el SELECT!!!!!!!!!!!!!!!!!!!!!!
				-- ni NINGUNA de sus asociadas !!!!!!!!!!
				-- sino LO UNICO QUE CAUSAN ES MULTIPLICACION DE RENGLONES !!!!!!!!!!!!!!!!!!!!!!!!!!!!
				BRA.[bra_desc],
				soh.soh_id,
				soh.bra_id,
				soh.comp_id,
				CU.[cust_name],
				SOH.soh_deliveryDate,
				SM.[sm_name],
				DL.[dl_name],
				tst.st_desc,
				tov.optval_desc,
				--tsos.comp_id,
				soh.ssos_id,
				SOH.soh_internalAnnotation,
				--tmp.soh_id,
				vsos.ssos_desc,
				SOH.bra_id,
				tcw.cust_id,
				tcb.custb_name,
				tss.ss_desc,
				tdf.sd_id,
				soh.soh_lastUpdate,
				soh.ws_internalID,
				soh.mlo_id		  ,
				--sod.rmad_id	,
				df_SaleOrder_IsInvoiceFirstPacking  ,
				tmlos.MLshippingID,
				tmls.mls_accessToken,
				soh.soh_isPrintedFromSOPreparation	,
				tmloh.mlo_status,cu.cust_id		,
				-- MOS 01-2023
				 tmlos.MLfulfilled	,
				 tmlos.MLSelf_Service		,
				 tmlos.MLshippingID		,
				 tmloh.mlo_id	,
				 tmlos.MLturbo

	order by soh_id

END


GO

