				ti.item_markup_1,
				ti.item_markup_2,
				ti.item_markup_3,
				ti.item_markup_4,
				ti.item_markup_5,
				ti.item_markup_6,
				ti.item_markup_7,
				ti.item_markup_8,
				ti.item_markup_9,
				ti.item_markup_10,
				ti.item_markup_11,
				ti.item_markup_12,
				ti.item_markup_13,
				ti.item_markup_14,
				ti.item_markup_15,
				ti.item_markup_16,
				ti.item_PriceLabel_Title,
				ti.item_PriceLabel_Desc1,
				ti.item_PriceLabel_Desc2,
				ti.item_PriceLabel_Desc3,
				ti.item_PriceLabel_Desc4,
				ti.item_PriceLabel_Desc5,
				ti.item_PriceLabel_Desc6,
				ti.item_PriceLabel_Desc7,
				ti.item_PriceLabel_Desc8,
				ti.item_PriceLabel_Desc9,
				ti.item_PriceLabel_Desc10,
				ti.item_PriceLabel_optionType,
				ti.item_NoStockCheck,
				ti.item_ML_isAvailable,
				ti.item_ML_desc,
				ti.item_ML_html4Publication,
				ti.acc_count_id4Purchase,
				ti.item_isEW,
				ti.df_id4EW,
				ti.item_insuranceDays,
				ti.insu_id,
				ti.item_EWDesc,
				ti.item_guarantee4PCConfig,
				ti.item_lastChanged,
				ti.posara_id,
				ti.user_id4Insert,
				ti.user_id4LastUpdate,
				ti.item_LastUpdate,
				ti.item_noAvailable4GeneralDiscount,
				ti.item_disablePrintInDocumentsPrint,
				ti.item_importCost_isExent4CostCalculation,
				ti.item_code4web,
				ti.item_ML_url4video,
				ti.brag_id
				FROM tbItem								ti	WITH(NOLOCK)
				WHERE	ti.comp_id = @comp_id			AND
						ti.item_id = @item_id4PCConfig

				DECLARE @intNewItemID	INT
				SET	@intNewItemID = IDENT_CURRENT('tbItem')   -- @@identity


				UPDATE tbItem
				SET
					item_IsCreatedBySaleOrderProductionComposition = 'True'
				WHERE	comp_id = @comp_id AND
						item_id = @intNewItemID




				SELECT @intNewItemID	[NewItemID]

		-- -----------------------------------------------------------------------------------------

	END
GO

CREATE PROCEDURE spSaleOrder_PCConfig_InsertOrUpdateItemCompositionRelation
(
	@comp_id	INT,
	@item_id	INT,
	@item_id1	INT,
	@qty		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT,
				@item_id1	INT,
				@qty		INT
		*/
		-- -----------------------------------------------------

		IF EXISTS (SELECT
						1
						FROM tbItemComposition				tic	WITH(NOLOCK)
						WHERE	tic.comp_id		= @comp_id	AND
								tic.item_id		= @item_id	AND
								tic.item_id_1	= @item_id1)
			BEGIN
				UPDATE tbItemComposition
				SET
					icomp_qty		= @qty
				WHERE	comp_id		= @comp_id AND
						item_id		= @item_id AND
						item_id_1	= @item_id1
			END
		ELSE
			BEGIN
				EXEC spItemComposition_InsertData
					@comp_id	= @comp_id,
					@Item_id	= @item_id,
					@Item_id_1	= @item_id1,
					@icomp_qty	= @qty,
					@color_id	= NULL
			END

	END
GO


