CREATE PROCEDURE [dbo].[spSaleOrder_PendingStatus_getDataByFilters]
(
	@comp_id			int,
	@lang_id			INT,
	@bra_id				int,
	@prof_id			int,
	@user_id			int,

	@sops_id			INT,		--Motivo
	@sops_bra_id		INT,		--Sucursal del motivo
	@sops_supp_id		INT,		--Proveedor del motivo
	@sops_datefrom		DATETIME,	--Fecha desde del motivo
	@sops_dateto		DATETIME,	--Fecha hasta del motivo
	@poh_bra_id			INT,		--Sucursal de la OC
	@poh_id				INT,		--Nro de OC

	@cust_id			INT,		--Cliente del pedido
	@soh_bra_id			INT,		--Sucursal del pedido
	@soh_id				INT,		--Nro de pedido


	@GuidCust			VARCHAR(50),--COmplex Filter de Clientes
	@GuidSupp			VARCHAR(50),--COmplex Filter de Proveedores
	@GuidItem			VARCHAR(50)	--COmplex Filter de Items
)
AS


BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on

	set dateformat 'ymd'

	-- ---------------------------------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------------------------------
	/*
	DECLARE
		@comp_id			int,
		@lang_id			INT,
		@bra_id				int,
		@prof_id			int,
		@user_id			int,

		@sops_id			INT,		--Motivo
		@sops_bra_id		INT,		--Sucursal del motivo
		@sops_supp_id		INT,		--Proveedor del motivo
		@sops_datefrom		DATETIME,	--Fecha desde del motivo
		@sops_dateto		DATETIME,	--Fecha hasta del motivo
		@poh_bra_id			INT,		--Sucursal de la OC
		@poh_id				INT,		--Nro de OC

		@cust_id			INT,		--Cliente del pedido
		@soh_bra_id			INT,		--Sucursal del pedido
		@soh_id				INT,		--Nro de pedido


		@GuidCust			VARCHAR(50),--COmplex Filter de Clientes
		@GuidSupp			VARCHAR(50),--COmplex Filter de Proveedores
		@GuidItem			VARCHAR(50)	--COmplex Filter de Items


	SELECT
		@comp_id			= 1,
		@lang_id			= 2,
		@bra_id				= 1,
		@prof_id			= 1,
		@user_id			= 3,

		@sops_id			= -1,
		@sops_bra_id		= -1,
		@sops_supp_id		= -1,
		@sops_datefrom		= '01/01/2000',
		@sops_dateto		= '12/31/2999',
		@poh_bra_id			= 0,
		@poh_id				= 0,

		@cust_id			= -1,
		@soh_bra_id			= 0,
		@soh_id				= 0,

		@GuidCust			= '0d75eae6-9867-46cd-b6c2-b0a95721aab0',
		@GuidSupp			= '0d75eae6-9867-46cd-b6c2-b0a95721aab0',
		@GuidItem			= '0d75eae6-9867-46cd-b6c2-b0a95721aab0'
		*/
	-- ---------------------------------------------------------------------------------------------


	SET @sops_datefrom	= dbo.fnGetEnd_or_BeginOfDate(@sops_datefrom,'False')
	SET @sops_dateto		= dbo.fnGetEnd_or_BeginOfDate(@sops_dateto,'True')


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN con CF de Clientes
	-- -------------------------------------------------------------
		DECLARE @lGuidCust AS UNIQUEIDENTIFIER

		SET @lGuidCust = CONVERT(UNIQUEIDENTIFIER,@GuidCust)


		DECLARE @tblComplexFilter_Cust TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Cust
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE	tcf.sl_guid = @lGuidCust     AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Cust
					SELECT tc.cust_id
					FROM tbCustomer tc
						WHERE tc.comp_id = @comp_id
			END
	-- ----------------------------------------------------------------
	-- -- -------------------------------------------------------------
	-- -- -------------------------------------------------------------

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN con CF de Items
	-- -------------------------------------------------------------
		DECLARE @lGuidItem AS UNIQUEIDENTIFIER
		SET @lGuidItem = CONVERT(UNIQUEIDENTIFIER,@GuidItem)

		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuidItem     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
	-- ----------------------------------------------------------------
	-- -- -------------------------------------------------------------
	-- -- -------------------------------------------------------------


	SELECT
		-- --------------------------------------------------------------------------------
		-- Botones de acciones de la grilla
		-- --------------------------------------------------------------------------------
		' ' [1],								-- Modificar Motivo y datos
		' ' [2],								-- Editar Pedido
		' ' [3],								-- Imprimir Pedido
		' ' [4],								-- Dividir
		' ' [5],								-- Imprimir OC
		' ' [6],								-- Eliminar
		-- --------------------------------------------------------------------------------
		tsopr.sops_desc												[sops_desc],		-- Motivo
		tsod.sops_date												[ct_date],			-- Fecha del Motivo
		dbo.fnGetSaleOrderNumber(soh.comp_id,soh.bra_id,soh.soh_id) +
		'¦' +
		convert(nvarchar(4),IsNull(sov.optval_desc,'')) +
		'¦' +
		IsNull(vsos.ssos_desc,'') 	+
		ISNULL(tss.ws_paymentGateWayShortStatusDescription,'')		[ssos_desc],		-- Estado y Desc del Pedido
		bra.bra_desc												[bra_desc],
		cu.cust_name												[cust_name],
		tsod.sod_itemDesc											[item_desc],
		tsod.sod_qty												[sod_qty],


		sopsbra.bra_desc											[sops_bra_id],		-- Sucursal del motivo
		sopsts.supp_name											[supp_name],		-- Proveedor del motivo
		IsNull(tsod.sops_note,'')									[sops_note],		-- Nota del motivo
		tu.user_lastname + ', ' + tu.user_firstname					[sops_user_name],	-- Usuario de ultima modificacion
		tsod.sops_lastUpdate										[sops_lastUpdate],  -- Fecha de ultima modificacion

		--NO PONER NADA DESPUES DE ESTA LINEA
		isnull(tsod.sops_poh_bra_id,0)								[sops_poh_bra_id],	-- OC del motivo
		isnull(tsod.sops_poh_id,0)									[sops_poh_id],		-- Nº de OC del motivo

		--ID---------------------
		Convert(Varchar,soh.comp_id) + '-' +
		Convert(Varchar,soh.bra_id)  + '-' +
		Convert(Varchar,soh.soh_id)  + '-' +
		Convert(Varchar,tsod.sod_id) + '-' +
		Convert(Varchar,tsod.sops_id)+ '-' +
		Convert(Varchar,tsod.item_id)							[ID]

		FROM dbo.tbSaleOrderHeader					soh				WITH (NOLOCK)

		INNER JOIN tbSaleOrderDetail				tsod			WITH (NOLOCK)
		ON	tsod.comp_id	= soh.comp_id
		AND tsod.bra_id		= soh.bra_id
		AND tsod.soh_id		= soh.soh_id

		LEFT JOIN dbo.tbBranch						sopsbra			WITH (NOLOCK)
		on	sopsbra.comp_id		= tsod.comp_id
		AND sopsbra.bra_id		= tsod.sops_bra_id

		LEFT JOIN dbo.tbSupplier 					sopsts			WITH (NOLOCK)
		on	sopsts.comp_id		= tsod.comp_id
		AND sopsts.supp_id		= tsod.sops_supp_id

		LEFT JOIN tbUser							tu				WITH (NOLOCK)
		ON tu.[user_id]		= tsod.sops_user_id

		INNER JOIN dbo.tbCustomer					cu				WITH (NOLOCK)
		on	cu.comp_id		= soh.comp_id
		AND cu.cust_id		= soh.cust_id

		INNER JOIN @tblComplexFilter_Cust			tempCust
		ON	tempCust.cust_id		= cu.cust_id

		INNER JOIN @tblComplexFilter_Items			tempITEM
		ON	tempitem.item_id		= tsod.item_id

		INNER JOIN tbSaleOrderPendingReason			tsopr			WITH (NOLOCK)
		ON	tsopr.comp_id			= tsod.comp_id AND
			tsopr.sops_id			= tsod.sops_id

		INNER JOIN dbo.tbBranch						bra				WITH (NOLOCK)
		on	bra.comp_id		= soh.comp_id
		And bra.bra_id		= soh.bra_id

		------------
		-- Todos joins para desc y estado del pedido
		INNER JOIN dbo.tbDocumentsFile				df				WITH (NOLOCK)
		on	df.comp_id		= soh.comp_id
		AND df.df_id		= soh.df_id

		LEFT JOIN dbo.tbsysOptionsValues			SOV				WITH (NOLOCK)
		On	SOV.lang_id		= @lang_id
		AND SOV.optval_class= 6
		AND SOV.optval_id	= df.sd_id

		LEFT JOIN vwSaleOrderStatus					vsos			WITH (NOLOCK)
		ON	vsos.comp_id	= soh.comp_id
		AND vsos.bra_id		= soh.bra_id
		AND vsos.soh_id		= soh.soh_id
		AND vsos.lang_id	= @lang_id

		LEFT JOIN tbSYSWebSiteII_paymentGatewayStatus tss			WITH (NOLOCK)
		ON tss.ws_paymentGateWayStatusID = soh.ws_paymentGateWayStatusID
		------------



	WHERE	soh.comp_id = @comp_id
	AND		(@sops_id			= -1	OR tsod.sops_id			= @sops_id)												--Motivo
	AND		(@sops_bra_id		= -1	OR tsod.sops_bra_id		= @sops_bra_id)											--Sucursal del Motivo
	AND		(@sops_supp_id		= -1	OR tsod.sops_supp_id	= @sops_supp_id)										--Proveedor del Motivo
	AND		(tsod.sops_date		BETWEEN		@sops_datefrom	AND	@sops_dateto)											--Fecha del motivo
	AND		(@poh_Bra_id = 0 OR @poh_id = 0 or (tsod.sops_poh_bra_id = @poh_Bra_id and tsod.sops_poh_id = @poh_id))		--Sucursal y Nº de OC

	AND		(@cust_id			= -1	OR soh.cust_id			= @cust_id)												--Cliente del pedido
	AND		(@soh_Bra_id = 0 OR @soh_id = 0 or (soh.bra_id = @soh_Bra_id and soh.soh_id= @soh_id))						--Sucursal y Nº de Pedido
	AND		soh.bra_id  = @bra_id																						--Pedidos de la sucursal de session


	ORDER BY soh.soh_deliveryDate desc

END
GO



CREATE PROCEDURE  [dbo].[spSaleOrder_PurificationOrders]
(


	@comp_id			Int,
	@bra_id				Int,
	@processing_date	datetime,
	@return_value		INT OUTPUT


)
AS



BEGIN


	set dateformat 'ymd'
	SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------------------
/*
	Declare @comp_id			Int,
			@bra_id				Int,
			@processing_date	DATETIME,
			@return_value		INT
	select	@comp_id			=1,
			@bra_id				=1,
			@processing_date	='2023-06-26'
*/
-- -----------------------------------------------------------------------------




	SET		@return_value = 0

--	-- Si los dias para depurado estan en CERO, NO DEPURA.!
--	IF NOT EXISTS(
--					SELECT 1
--						FROM tbBranch tb
--						WHERE	tb.comp_id	= @comp_id
--							AND tb.bra_id	= @bra_id
--							AND IsNull(tb.bra_SaleOrderDisposeLimitDays,0) > 0)
--		BEGIN
--			RETURN
--		END


	DECLARE @soh_id			INT,
			@lsm_id			INT,
			@luser_id		INT,
			@lrv			INT,
			@lprof_id		INT,
			@lutexts_desc	NVARCHAR(400) ,
			@sohBra_Id		AS INT,
			@sohComp_Id		AS INT



--	BEGIN TRANSACTION
	BEGIN TRY

		-- ----------------------------------------------------------------------------------------------------
		-- Actualiza el LimitDate segun la ultima fecha de modificacion	y los dias para depurado en Documentos.
		-- ----------------------------------------------------------------------------------------------------
		UPDATE tbSaleorderheader	WITH (ROWLOCK)
			SET soh_limitDate = dbo.fnMAXDate(soh.soh_deliveryDate,soh.soh_lastUpdate) +
								CASE




									-- Pedidos web MercadoPago NO PAGO ( 50 )
									when	soh.ws_paymentGateWayStatusID = 50					AND
											soh.ws_internalID IS NOT NULL						AND
											--soh.ssos_id IN (4,5)								AND
											tdf.df_SODays4DeletionWebMPNoPaymentRegistered_Enabled = 'True'	AND
										    IsNull(tdf.df_SODays4DeletionWebMPNoPaymentRegistered,0)		> 0				THEN tdf.df_SODays4DeletionWebMPNoPaymentRegistered

									-- Si Son PRESUPUESTOS
									WHEN	tdf.sd_id = 5 AND tdf.df_SODays4Deletion4Quotation_Enabled = 'True'
										and IsNull(tdf.df_SODays4Deletion4Quotation,0)	> 0					THEN IsNull(tdf.df_SODays4Deletion4Quotation,0)

									-- Si Son Pedidos de MercadoLibre
									WHEN	tdf.df_SODays4Deletion4MeLiSO_Enabled = 'True'	AND
											soh.mlo_id IS NOT NULL							AND
											IsNull(tdf.df_SODays4Deletion4MeLiSO,0)	> 0						THEN IsNull(tdf.df_SODays4Deletion4MeLiSO,0)



									-- Si Son Pedidos de MercadoLibre Cancelados
									WHEN	tdf.df_SODays4Deletion4MeLiCancelledSO_Enabled = 'True'	AND
											soh.mlo_id IS NOT NULL									AND
											tmloh.comp_id IS NOT NULL								AND
											IsNull(tdf.df_SODays4Deletion4MeLiCancelledSO,0)	> 0						THEN IsNull(tdf.df_SODays4Deletion4MeLiCancelledSO,0)

									WHEN	tdf.df_SODays4Deletion4MeLiCancelledSOOKEmission_Enabled = 'True'	AND
											soh.mlo_id IS NOT NULL												AND
											tmloh.comp_id IS NOT NULL											AND
											IsNull(tdf.df_SODays4Deletion4MeLiCancelledSOOKEmission,0)	> 0				THEN IsNull(tdf.df_SODays4Deletion4MeLiCancelledSOOKEmission,0)



									-- Si Son Pedidos en Area Comercial con Autorizaciones DENEGADAS
									WHEN	tdf.df_SODays4DeletionCommercialWithDeniedAuthorization_Enabled = 'True'	AND
											soh.ssos_id = 10 AND
											EXISTS(
														SELECT TOP 1 1
															FROM tbAutorizationRequest_PendingSaleOrders AS tarpso WITH (NOLOCK)
															WHERE	tarpso.comp_id		= soh.comp_id	AND
																	tarpso.soh_bra_id	= soh.bra_id	AND
																	tarpso.soh_id		= soh.soh_id	AND
																	tarpso.aure_isok	= 'U'
												  )
										and IsNull(tdf.df_SODays4DeletionCommercialWithDeniedAuthorization,0)	> 0						THEN IsNull(tdf.df_SODays4DeletionCommercialWithDeniedAuthorization,0)



									-- Pedidos Pendientes WEB
									when	soh.ssos_id IN (4,5)								AND
											tdf.df_SODays4DeletionWebPending_Enabled = 'True'	AND
										    IsNull(tdf.df_SODays4DeletionWebPending,0)		> 0				THEN tdf.df_SODays4DeletionWebPending

									-- Pedidos en Area Comercial
									when	soh.ssos_id = 10									AND
											tdf.df_SODays4DeletionCommercial_Enabled = 'True'	AND
										    IsNull(tdf.df_SODays4DeletionCommercial,0)		> 0				THEN tdf.df_SODays4DeletionCommercial

									-- Pedidos en Preparacion SIN Numeros de Serie Tomados
									when	soh.ssos_id = 20											AND
											tdf.df_SODays4DeletionPrepWithOutSerial_Enabled = 'True'	AND
										    IsNull(tdf.df_SODays4DeletionPrepWithOutSerial,0)	> 0		AND
										    NOT EXISTS(	SELECT TOP 1  1
															FROM tbSaleOrderSerials tsos	WITH (NOLOCK)
										               		WHERE	tsos.comp_id	= soh.comp_id
										               			AND tsos.bra_id		= soh.bra_id
										               			AND tsos.soh_id		= soh.soh_id)
																											THEN tdf.df_SODays4DeletionPrepWithOutSerial
									-- Pedidos en Preparacion CON Numeros de Serie Tomados
									when	soh.ssos_id = 20											AND
											tdf.df_SODays4DeletionPrepWithSerial_Enabled = 'True'		AND
										    IsNull(tdf.df_SODays4DeletionPrepWithSerial,0)	> 0			AND
										    EXISTS(		SELECT TOP 1  1
															FROM tbSaleOrderSerials tsos	WITH (NOLOCK)
										               		WHERE	tsos.comp_id	= soh.comp_id
										               			AND tsos.bra_id		= soh.bra_id
										               			AND tsos.soh_id		= soh.soh_id)
																											THEN tdf.df_SODays4DeletionPrepWithSerial

									-- Para TODOS los pedidos... ponerlo al FINAL !!!
									WHEN	tdf.df_SODays4Deletion4AllSO_Enabled = 'True'	AND
											IsNull(tdf.df_SODays4Deletion4AllSO,0)	> 0						THEN IsNull(tdf.df_SODays4Deletion4AllSO,0)

									-- Sino, le suma 10 años.
									ELSE 365
								END
			FROM tbSaleorderheader		soh
			LEFT JOIN tbMercadoLibre_ordersHeader AS tmloh		WITH (NOLOCK)	-- solo ORDENES CANCELADAS!!!
				ON 	tmloh.comp_id		= soh.comp_id	AND
					tmloh.mlo_id		= soh.mlo_id	AND
					tmloh.mlo_status   IN ('cancelled')
			INNER JOIN tbDocumentsFile			  AS tdf		WITH (NOLOCK)
				ON		tdf.comp_id = soh.comp_id	AND
						tdf.bra_id  = soh.bra_id	AND
						tdf.df_id	= soh.df_id
		WHERE	soh.comp_id = @comp_id	AND
				-- soh.bra_id	= @bra_id	AND  MOS 05-2020
				tdf.df_SODays4Deletion_BlockRecalculateLDBeforeDeletion = 'False'
		-- ----------------------------------------------------------------------------------------------------

		-- ----------------------------------------------------------------------------------------------------
		-- MOS 05-2022: Para tener el TOTAL de items depurados que DEBAN generar un movimiento de stock de AJUSTE para COMPENSAR los pedidos depuados
		--              que en realidad se DEBIERON EMITIR!!!!!!!!!
		-- ----------------------------------------------------------------------------------------------------
		DECLARE @tmpItemsSumarize TABLE(comp_id		INT,
										item_id		INT,
										stor_id		INT,
										qty			DECIMAL(30,6))

		INSERT INTO @tmpItemsSumarize
		(
			comp_id,
			item_id,
			stor_id,
			qty
		)
		SELECT ti.comp_id,ti.item_id,ts.stor_id,0
			FROM tbitem	AS ti	WITH (NOLOCK)
			LEFT JOIN tbStorage AS ts	WITH (NOLOCK)
				ON ts.comp_id = ti.comp_id
		--SELECT * FROM @tmpItemsSumarize ORDER BY item_id,stor_id
		-- ----------------------------------------------------------------------------------------------------

		DECLARE @df_SODays4Deletion_GenerateStockAdjustment			AS BIT = 'False'
		DECLARE @df_SODays4Deletion_GenerateStockAdjustmentFromDays AS INT = 0
		DECLARE @intSaleOrderLimitDiffDays							AS INT = 0
		DECLARE @curSD_Id AS INT  = 0
		DECLARE cursor_SO_PO_items CURSOR LOCAL  FAST_FORWARD FOR
												SELECT 	SOH.comp_id,
														SOH.bra_id,
														SOH.soh_id,
														tdf.df_SODays4Deletion_GenerateStockAdjustment,
														tdf.sd_id,
														ISNULL(tdf.df_SODays4Deletion_GenerateStockAdjustmentFromDays,0),
														ISNULL(DATEDIFF(DAY,dbo.fnMAXDate(soh.soh_deliveryDate,soh.soh_lastUpdate),@processing_date),0)
													FROM	dbo.tbSaleOrderHeader			SOH		WITH (NOLOCK)
													INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
														ON		tdf.comp_id = soh.comp_id	AND
																--tdf.bra_id  = soh.bra_id	AND
																tdf.df_id	= soh.df_id
													INNER JOIN tbBranch						tb		WITH (NOLOCK)
														ON	tb.comp_id	= soh.comp_id AND
															tb.bra_id	= soh.bra_id
													WHERE	SOH.comp_id			= @comp_id
													--AND		SOH.bra_id			= @bra_id  MOS 05-2020  Para que depure todo independientemente si se hace o no el cierre de alguna determinada sucursal.
													AND		SOH.soh_limitDate	< @processing_date
													AND		(
																soh.ssos_id IN (4,5,10,20)
																	OR
																tdf.sd_id = 5
																	OR
																(
																	soh.ssos_id = 50 AND tdf.df_SODays4Deletion4MeLiCancelledSOOKEmission_Enabled = 'True'
																)
																	OR	-- MOS 06-2023 para que depure segun esta conf.
																(
																	tdf.df_SODays4Deletion4MeLiSO_Enabled = 'True'	AND
																	soh.mlo_id IS NOT NULL							AND
																	IsNull(tdf.df_SODays4Deletion4MeLiSO,0)	> 0
																)
																OR -- MOS 06-2023: Para TODOS los pedidos... ponerlo al FINAL !!!
																(
																	tdf.df_SODays4Deletion4AllSO_Enabled	= 'True'	AND
																	IsNull(tdf.df_SODays4Deletion4AllSO,0)	> 0
																)
															)	-- Pendiente WEB,Comercial,Preparacion
													AND		tdf.sd_id	in (1,5)							-- Solo se depuran pedidos para Factura o Presupuesto
													AND		(


																(	-- Area Comercial con Autorizaciones Pendientes DENEGADAS
																	tdf.df_SODays4DeletionCommercialWithDeniedAuthorization_Enabled	= 'True'
																		AND
																		soh.ssos_id = 10 AND
																		EXISTS(
																					SELECT TOP 1 1
																						FROM tbAutorizationRequest_PendingSaleOrders AS tarpso WITH (NOLOCK)
																						WHERE	tarpso.comp_id		= soh.comp_id	AND
																								tarpso.soh_bra_id	= soh.bra_id	AND
																								tarpso.soh_id		= soh.soh_id	AND
																								tarpso.aure_isok	= 'U'
																			  )
																)
																OR
																(	-- es Pedido de Mercadolibre y debe depurarse
																	tdf.df_SODays4Deletion4MeLiSO_Enabled				= 'True'
																		AND
																	soh.mlo_id IS NOT NULL
																)
																OR
																(	-- es Pedido de Mercadolibre y debe depurarse
																	tdf.df_SODays4Deletion4MeLiCancelledSO_Enabled		= 'True'
																		AND
																	soh.mlo_id IS NOT NULL
																		AND
																	EXISTS(
																				SELECT TOP 1 1
																					FROM tbMercadoLibre_ordersHeader AS tmloh WITH (NOLOCK)
																						WHERE	tmloh.comp_id		= soh.comp_id	AND
																								tmloh.mlo_id		= soh.mlo_id	AND
																								tmloh.mlo_status IN ('cancelled')
																			)
																)
																OR
																(	-- es Pedido de Mercadolibre y debe depurarse
																	tdf.df_SODays4Deletion4MeLiCancelledSOOKEmission_Enabled		= 'True'
																		AND
																	soh.mlo_id IS NOT NULL
																		AND
																	EXISTS(
																				SELECT TOP 1 1
																					FROM tbMercadoLibre_ordersHeader AS tmloh WITH (NOLOCK)
																						WHERE	tmloh.comp_id		= soh.comp_id	AND
																								tmloh.mlo_id		= soh.mlo_id	AND
																								tmloh.mlo_status IN ('cancelled')
																			)
																)
																OR
																(	-- Presupuestos
																	tdf.df_SODays4Deletion4Quotation_Enabled			= 'True'
																		AND
																	tdf.sd_id = 5
																)
																OR
																(	-- en Area Comercial
																	tdf.df_SODays4DeletionCommercial_Enabled			= 'True'
																		AND
																	soh.ssos_id = 10
																)
																OR
																(	-- Preparacion CON numeros de serie tomados
																	tdf.df_SODays4DeletionPrepWithSerial_Enabled		= 'True'
																		AND
																	soh.ssos_id = 20
																		AND
																	EXISTS(	SELECT TOP 1 1
																					FROM tbSaleOrderSerials tsos	WITH (NOLOCK)
										               								WHERE	tsos.comp_id	= soh.comp_id
										               									AND tsos.bra_id		= soh.bra_id
										               									AND tsos.soh_id		= soh.soh_id)
																)
																OR
																(	-- Preparacion SIN numeros de serie tomados
																	 tdf.df_SODays4DeletionPrepWithOutSerial_Enabled	= 'True'
																		AND
  																	 soh.ssos_id = 20
  																		AND
																	 NOT EXISTS(	SELECT TOP 1 1
																						FROM tbSaleOrderSerials tsos	WITH (NOLOCK)
										               									WHERE	tsos.comp_id	= soh.comp_id
										               										AND tsos.bra_id		= soh.bra_id
										               										AND tsos.soh_id		= soh.soh_id)
																)
																OR
																(	-- Pendiente WEB
																	tdf.df_SODays4DeletionWebPending_Enabled			= 'True'
																		AND
																	soh.ssos_id IN (4,5)
																)
																OR
																(	-- Pedidos WEB MP No Ingresado
																	tdf.df_SODays4DeletionWebMPNoPaymentRegistered_Enabled			= 'True'
																		AND
																	soh.ws_paymentGateWayStatusID = 50 AND
																	soh.ws_internalID IS NOT NULL
																)
																OR	-- MOS 11-2022: todos los de area comercial sin importar la fecha.
																(
																	tdf.df_SODeletion4InvoicesInCommercial_Enabled	= 'True'				AND
																	SOH.ssos_id										= 10
																)
																OR -- todos los de preparacion sin series tomados sin importar la fecha.
																(
																	tdf.df_SODeletion4InvoicesInPreparationNOSerial_Enabled = 'True'		AND
																	SOH.ssos_id												= 20			AND
																	NOT EXISTS(	SELECT TOP 1 1
																					FROM tbSaleOrderSerials tsos	WITH (NOLOCK)
										               								WHERE	tsos.comp_id	= soh.comp_id
										               									AND tsos.bra_id		= soh.bra_id
										               									AND tsos.soh_id		= soh.soh_id)
																)
																OR -- MOS 06-2023: Para TODOS los pedidos... ponerlo al FINAL !!!
																(
																	tdf.df_SODays4Deletion4AllSO_Enabled	= 'True'	AND
																	IsNull(tdf.df_SODays4Deletion4AllSO,0)	> 0
																)
															)
													AND tb.bra_SaleOrderDepurationBlocked = 'False'

												UNION

													-- -------------------------------------------------------------
													-- Borra pedidos que esten sin detalle y solo header colgados.!
													-- -------------------------------------------------------------
													SELECT DISTINCT
															tsoh.comp_id,
															tsoh.bra_id,
															tsoh.soh_id,
															tdf.df_SODays4Deletion_GenerateStockAdjustment,
															tdf.sd_id,
															ISNULL(tdf.df_SODays4Deletion_GenerateStockAdjustmentFromDays,0),
															999999
														FROM tbSaleOrderHeader		tsoh		WITH (NOLOCK)
														INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
															ON		tdf.comp_id = tsoh.comp_id	AND
																	--tdf.bra_id  = tsoh.bra_id	AND
																	tdf.df_id	= tsoh.df_id
														LEFT JOIN tbSaleOrderDetail tsod		WITH (NOLOCK)
															ON	tsod.comp_id	= tsoh.comp_id	AND
																tsod.bra_id		= tsoh.bra_id	AND
																tsod.soh_id		= tsoh.soh_id
														WHERE	tsoh.comp_id	= @comp_id		AND
																--tsoh.bra_id		= @bra_id		AND
																tsod.comp_id IS NULL
													-- -------------------------------------------------------------






		DECLARE @bolupdateInPurification AS BIT = 'False'



		OPEN	cursor_SO_PO_items

		FETCH NEXT FROM cursor_SO_PO_items	INTO @sohComp_Id,@sohBra_Id,@soh_id,@df_SODays4Deletion_GenerateStockAdjustment,@curSD_Id,@df_SODays4Deletion_GenerateStockAdjustmentFromDays,@intSaleOrderLimitDiffDays

		WHILE	@@FETCH_STATUS = 0

			BEGIN



--==
--SELECT @sohComp_Id,@sohBra_Id,@soh_id,@df_SODays4Deletion_GenerateStockAdjustment


				-- MOS 05-2022:  Unifico los SP de depurado de pedidos para que SOLO deba modificarse uno de los dos
				BEGIN TRY


					-- MOS 05-2024: Avisa que se estan depurando pedidos que deben mantener stock para que, por ejemplo,
					--              no se ejecute el processqueue de MeLi.
					IF @df_SODays4Deletion_GenerateStockAdjustment = 'True' AND @bolupdateInPurification = 'False'
						BEGIN
							UPDATE tbSystem_DatabaseVersion SET closeDaily_PurificatingOrders = 1
							SET @bolupdateInPurification = 'True'
						END




					IF	@df_SODays4Deletion_GenerateStockAdjustment = 'True'	AND
						@curSD_Id IN (1,2,3,4)									AND
						@df_SODays4Deletion_GenerateStockAdjustmentFromDays > 0 AND
						@intSaleOrderLimitDiffDays >= @df_SODays4Deletion_GenerateStockAdjustmentFromDays

						BEGIN

							;WITH cteSUM(item_id,stor_id,soQTY) AS
											(
												SELECT	tsod.item_id,
														tsod.stor_id,
														SUM(tsod.sod_qty * td.sd_plusOrminus)
													FROM tbSaleOrderHeader		 AS tsoh		WITH (NOLOCK)
													INNER JOIN tbSaleOrderDetail AS tsod		WITH (NOLOCK)
														ON	tsod.comp_id	= tsoh.comp_id	AND
															tsod.bra_id		= tsoh.bra_id	AND
															tsod.soh_id		= tsoh.soh_id
													INNER JOIN tbStorage		 AS ts			WITH (NOLOCK)
														ON  ts.comp_id		= tsod.comp_id	AND
															ts.stor_id		= tsod.stor_id
													INNER JOIN tbDocumentsFile	 AS tdf			WITH (NOLOCK)
														ON	tdf.comp_id		= tsoh.comp_id	AND
															tdf.df_id		= tsoh.df_id
													INNER JOIN tbsysDocuments	 AS td			WITH (NOLOCK)
														ON td.sd_id			= tdf.sd_id
													WHERE	tsoh.comp_id	= @sohComp_Id	AND
															tsoh.bra_id		= @sohBra_Id	AND
															tsoh.soh_id		= @soh_id
													GROUP BY	tsod.item_id,
																tsod.stor_id
											)

							UPDATE @tmpItemsSumarize
								SET tmp.qty = tmp.qty + tt.soQTY
								FROM @tmpItemsSumarize tmp
								INNER JOIN cteSUM      tt
									ON	tt.item_id = tmp.item_id AND
										tt.stor_id = tmp.stor_id

							-- MOS 06-2023: Se hizo con el CTE porque si habia DOS iguales de item_id en el MISMO update, solo suma uno.  una GTRAN cagada ya que esto se usa así en VAARIOS lugares del sistema..
							--UPDATE @tmpItemsSumarize
							--	SET tmp.qty = tmp.qty + (tsod.sod_qty * td.sd_plusOrminus)
							--	FROM @tmpItemsSumarize tmp
							--	INNER JOIN tbSaleOrderHeader AS tsoh		WITH (NOLOCK)
							--		ON	tsoh.comp_id	= @sohComp_Id	AND
							--			tsoh.bra_id		= @sohBra_Id	AND
							--			tsoh.soh_id		= @soh_id
							--	INNER JOIN tbSaleOrderDetail AS tsod		WITH (NOLOCK)
							--		ON	tsod.comp_id	= tsoh.comp_id	AND
							--			tsod.bra_id		= tsoh.bra_id	AND
							--			tsod.soh_id		= tsoh.soh_id
							--	INNER JOIN tbStorage		 AS ts			WITH (NOLOCK)
							--		ON  ts.comp_id		= tsod.comp_id	AND
							--			ts.stor_id		= tsod.stor_id
							--	INNER JOIN tbDocumentsFile	 AS tdf			WITH (NOLOCK)
							--		ON	tdf.comp_id		= tsoh.comp_id	AND
							--			tdf.df_id		= tsoh.df_id
							--	INNER JOIN tbsysDocuments	 AS td			WITH (NOLOCK)
							--		ON td.sd_id			= tdf.sd_id
							--WHERE	tmp.comp_id = tsod.comp_id			AND
							--		tmp.item_id = tsod.item_id			AND
							--		tmp.stor_id = tsod.stor_id

						END

						EXEC spSaleOrder_deleteSaleOrder @sohComp_Id,@sohBra_Id,@soh_id

				END TRY
				BEGIN CATCH
				END CATCH



				FETCH NEXT FROM cursor_SO_PO_items INTO @sohComp_Id,@sohBra_Id,@soh_id,@df_SODays4Deletion_GenerateStockAdjustment,@curSD_Id,@df_SODays4Deletion_GenerateStockAdjustmentFromDays,@intSaleOrderLimitDiffDays

			END

		CLOSE cursor_SO_PO_items
		DEALLOCATE cursor_SO_PO_items

	-- Fin Depurado de Pedidos.!













		-- -----------------------------------------------------------------------------------------------------------------------
		-- MOS 05-2022
		-- Borro todos los que NO deben generar ningun ajuste por no haber tenido o por dar el total de ajustes 0
		-- -----------------------------------------------------------------------------------------------------------------------
		DELETE FROM @tmpItemsSumarize WHERE qty = 0

		IF EXISTS(
					SELECT TOP 1 1
						FROM @tmpItemsSumarize AS tis
				 )
			BEGIN
				DECLARE @datProcessingDate AS DATETIME		= GETDATE()
				DECLARE @intAdjustCounter  AS INT			= 0
				DECLARE @strAdjustCounter  AS VARCHAR(10)   = ''
				DECLARE @intCTTransaction  AS INT
				DECLARE @currency_id	   AS INT			= 1

				SELECT @currency_id = curr_id
					FROM tbBranch AS tb	WITH (NOLOCK)
					WHERE	tb.comp_id	= @comp_id AND
							tb.bra_id	= @bra_id

				EXEC    spCounters_getNextValue @comp_id,@bra_id,8,@intAdjustCounter OUTPUT  --Counter_NumberForStockAdjustment
				SET		@strAdjustCounter					= CONVERT(VARCHAR(10),@intAdjustCounter)

				EXEC spCommercialTransactions_InsertData @comp_id,
														 @bra_id,
														 @strAdjustCounter,
														 @datProcessingDate,
														 NULL ,
														 NULL ,
														 NULL ,
														 NULL ,
														 0,
														 0,
														 0,
														 0,
														 @currency_id ,
														 NULL   ,
														 NULL ,
														 0 ,
														 0,
														 @currency_id,
														 0,
														 NULL ,
														 NULL ,
														 NULL ,
														 NULL ,
														 @currency_id,
														 0,
														 350 ,
														 '',
														 '',
														 '',
														 '',
														 0,
														 @intCTTransaction OUTPUT,
														 0,
														 ''


				DECLARE @cur_comp_id AS INT
				DECLARE @cur_item_id AS INT
				DECLARE @cur_stor_id AS INT
				DECLARE @cur_qty     AS DECIMAL(30,6)

				DECLARE cursor_SO_ADJ_items CURSOR LOCAL  FAST_FORWARD FOR
					SELECT	tis.comp_id,
							tis.item_id,
							tis.stor_id,
							tis.qty
						FROM @tmpItemsSumarize AS tis

				OPEN		cursor_SO_ADJ_items
				FETCH NEXT FROM cursor_SO_ADJ_items	INTO @cur_comp_id,@cur_item_id,@cur_stor_id,@cur_qty

				WHILE @@FETCH_STATUS = 0
					BEGIN

						SET @cur_qty = @cur_qty * -1  -- se debe DESCONTAR un pedido para FACTURA y SUMAR uno de NC ...
						-- 91: Depurado de Pedidos: Ajuste de Stock por Depurado - StkSOPurge

						BEGIN TRY
							EXEC spItemTransactions_InsertStock4StorageFastAdjustment	@comp_id,
																						@bra_id,
																						@intCTTransaction,
																						@cur_item_id,
																						@cur_qty,
																						NULL,
																						@cur_stor_id,
																						-1,
																						91,
																						0,
																						0,
																						''
						END TRY
						BEGIN CATCH
						END CATCH

						FETCH NEXT FROM cursor_SO_ADJ_items	INTO @cur_comp_id,@cur_item_id,@cur_stor_id,@cur_qty
					END
				CLOSE		cursor_SO_ADJ_items
				DEALLOCATE	cursor_SO_ADJ_items

			END
		-- -----------------------------------------------------------------------------------------------------------------------



















-- POner esto cuando funcione la workflow para ver que pedidos se van a depurar al dia siguiente.!
/*
		DECLARE cursor_SO_PO_workflow CURSOR FOR
			(SELECT TOP 0	SOH.user_id
			FROM	dbo.tbSaleOrderHeader							SOH

     				INNER JOIN vwsysSaleOrderStatus_InCommercial	vsosic
					ON vsosic.ssos_id	= soh.ssos_id

			WHERE	SOH.comp_id			= @comp_id
			AND		SOH.bra_id			= @bra_id
			AND 	NOT EXISTS			(SELECT	TOP 1 1
   										FROM	tbSaleOrderSerials	tsos
   										WHERE	tsos.comp_id	= SOH.comp_id
										AND		tsos.bra_id		= SOH.bra_id
										AND		tsos.soh_id		= SOH.soh_id)
