*/



		--COMMIT TRANSACTION


	END
	TRY BEGIN CATCH

		--ROLLBACK TRANSACTION
		SET @return_value = -1

	END CATCH

	--SELECT @return_value

END


-- MOS 05-2024: Avisa que TErnmino el Depurado de Pedidos
UPDATE tbSystem_DatabaseVersion SET closeDaily_PurificatingOrders = 0 WHERE closeDaily_PurificatingOrders = 1
GO







-- ----------------------------------------------------------------------------
-- No usdar mas el spSaleOrder_insertAllData
--
-- ATENCION:   este SP recalcula los importes de un pedido dado
--             Usarlo cuando inserto un pedido desde algun lugar y se quiera
--			   que recalcule los impuestos, gastos, intereses, etc.
--             Por ejemplo, cuando RMA genera un pedido, al final se llama
--             a este SP.
-- ----------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spSaleOrder_RecalculateTaxes]
(
	@comp_id		INT,
	@bra_id			INT,
	@soh_id			INT,
	@user_id		INT,
	@lang_id		INT
)

AS


BEGIN


	SET NOCOUNT ON



	-- --------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------
	/*
	DECLARE	@comp_id		INT = 1,
			@bra_id			INT = 1,
			@soh_id			INT = 34904,
			@user_id		INT = 1,
			@lang_id		INT = -2
	*/
	-- --------------------------------------------------------------







	-- ------------------------------------------------------------------------------
	-- MOS: 12-2022
	-- Para que NO retorne nada , se usa en RecalculateTaxes para poder recalcular al IMPRIMIR un pedido
	-- ------------------------------------------------------------------------------
	DECLARE @bitNoReturnTable AS BIT = 'False'
	IF @lang_id < 0
		BEGIN
			SET @bitNoReturnTable = 'True'
			SET @lang_id = @lang_id * -1
		END
	-- ------------------------------------------------------------------------------







	DECLARE @limitdate		 DATETIME	= GETDATE()
	DECLARE @deliveryDate    DATETIME	= GETDATE()

	DECLARE @cust_id	INT,
			@intCustomerCurr_id	INT,
			@intBranchCurr_Id	INT,
			@disc_id	INT,
			@st_id		INT,
			@df_id		INT,
			@dl_id		INT,
			@sm_id		INT,
			@cb_id		INT,
			@tt_id		INT,
			@tt_class	VARCHAR(2),
			@ssos_id	INT,
			@guid		UNIQUEIDENTIFIER  ,
			@strNote1   NVARCHAR(2000),
			@strNote2   NVARCHAR(2000),
			@strNote3   NVARCHAR(2000),
			@strNote4   NVARCHAR(2000),
			@bra_PriceDecimalPlaces		AS INT,
			@ccp_id						AS INT
	DECLARE @df_id4PL					AS INT = NULL
	DECLARE @soh_loan					AS DECIMAL(19,6) = 0
	DECLARE @soh_internalAnnotation		AS NVARCHAR(100) = ''
	DECLARE @country_id		INT,
			@state_id		INT,
			@cust_curr_id	INT

	SELECT @guid		= newid()


	-- CONFIRMADO POR MARTIN QUE ES ASÍ   --   11-2018
	-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
	DECLARE @ExchangeToCustomerCurrency FLOAT --	'DECIMAL(19,6)



	SELECT  @cust_id			= tsoh.cust_id,
			--@intCustomerCurr_id			= tc.curr_id,   11-2018
			@intCustomerCurr_id			= ISNULL(tsoh.soh_CustomerCurrency,tc.curr_id),
			@ExchangeToCustomerCurrency = tsoh.soh_ExchangeToCustomerCurrency,
			@intBranchCurr_Id   = tb.curr_id,
			@disc_id			= tsoh.disc_id,
			@st_id				= tsoh.st_id,
			@df_id				= tsoh.df_id,
			@dl_id				= tsoh.dl_id,
			@sm_id				= tsoh.sm_id,
			@cb_id				= tsoh.cb_id,
			@tt_id				= tsoh.tt_id,
			@tt_class			= tsoh.tt_class,
			@ssos_id			= tsoh.ssos_id,
			@strNote1			= tsoh.soh_observation1,
			@strNote2			= tsoh.soh_observation2,
			@strNote3			= tsoh.soh_observation3,
			@strNote4			= tsoh.soh_observation4,
			@bra_PriceDecimalPlaces = tdf.df_PriceDecimalPlaces,
			@ccp_id				= ISNULL(tsoh.ccp_id,-1),
			@user_id			= CASE
			        			      WHEN @user_id = -1  THEN tsoh.[user_id]
			        			      ELSE @user_id
			        			  END,
			@df_id4PL				= tsoh.df_id4PL,
			@soh_internalAnnotation = tsoh.soh_internalAnnotation,
			@limitdate			= tsoh.soh_limitDate,
			@deliveryDate		= tsoh.soh_deliveryDate

		FROM	tbSaleOrderHeader		tsoh			WITH (NOLOCK)
		INNER JOIN tbCustomer tc						WITH (NOLOCK)
			ON	tc.comp_id = tsoh.comp_id AND
				tc.cust_id = tsoh.cust_id
		INNER JOIN tbBranch tb							WITH (NOLOCK)
			ON	tb.comp_id = tsoh.comp_id AND
				tb.bra_id  = tsoh.bra_id
		INNER JOIN tbDocumentsFile tdf					WITH (NOLOCK)
			ON	tdf.comp_id = tsoh.comp_id AND
				tdf.df_id	= tsoh.df_id
		WHERE	tsoh.comp_id	= @comp_id
		AND		tsoh.bra_id		= @bra_id
		AND		tsoh.soh_id		= @soh_id





	SELECT	@country_id		= tc.country_id,
			@state_id		= tc.state_id,
			@cust_curr_id	= ISNULL(@intCustomerCurr_id,tc.curr_id)  --/*tc.curr_id*/  11-2018
		FROM	tbCustomer				tc			WITH (NOLOCK)
		WHERE	tc.comp_id		= @comp_id
		AND		tc.cust_id		= @cust_id



	DECLARE @bra_curr_id					INT,
			@bra_SaleOrderDisposeLimitDay	INT

	SELECT	@bra_curr_id					= tb.curr_id,
			@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays--,
			--@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces
		FROM	tbBranch				tb			WITH (NOLOCK)
		WHERE	tb.comp_id		= @comp_id
		AND		tb.bra_id		= @bra_id




	DECLARE @errormessage		VARCHAR(100)
	SET @errormessage = ''


	-- MOS 12-2022 x los HDP de MF 17941
	DECLARE @parLANGID AS INT =		@lang_id *	CASE
													WHEN @bitNoReturnTable = 'True' THEN	-1
													ELSE									 1
												END


	EXEC spSaleOrder_GetDataByIdforSaleOrderEdit
		@comp_id,
		@bra_id,
		@soh_id,
		@guid,
		@user_id,
		@errormessage OUTPUT,
		@parLANGID,
		'false',
		@bra_id





	IF LEN(@errormessage) = 0 --procesa
		BEGIN




			---- CONFIRMADO POR MARTIN QUE ES ASÍ   11-2018
			---- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
			--DECLARE @ExchangeToCustomerCurrency	DECIMAL(19,6)
			--SELECT  @ExchangeToCustomerCurrency = dbo.fnGetExchange(@comp_id, 1, @bra_curr_id, @cust_curr_id, 0, 0, 'false')


			CREATE TABLE #tmpGetTotalsData
			(
				t1		INT,
				t2		DECIMAL(18,2),
				t3		DECIMAL(19,6),
				t4		DECIMAL(19,6),
				t5		DECIMAL(19,6),
				t6		DECIMAL(18,2),
				t7		DECIMAL(19,5),
				t8		INT,
				t9		DECIMAL(19,6),
				T10		NVARCHAR(4000),
				TotalNoInterest		DECIMAL(25,6)
			)


			INSERT INTO #tmpGetTotalsData
			EXEC sptmpTax_calculate
				@comp_Id,
				@bra_Id,
				@cust_Id,
				@guid,
				@intBranchCurr_Id,
				@disc_Id,
				@country_Id,
				@state_Id,
				@st_id,
				@bra_curr_Id,
				@cust_curr_id,
				@ExchangeToCustomerCurrency,
				'false',
				@df_id,
				'true',
				@dl_id,
				0,
				'false',
				'false',
				-1,
				@ccp_id





			DECLARE @total			DECIMAL(19,6),
					@soh_discount	DECIMAL(19,6)

			SELECT	@total			= t2,
					@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces),
					@soh_loan		= ROUND(t5, @bra_PriceDecimalPlaces)		-- MOS 07-2022 x DM
				FROM	#tmpGetTotalsData


			DROP TABLE #tmpGetTotalsData

			-- actualizar saleorderheader ?


			DECLARE @getdate		DATETIME
			DECLARE @onlydate		DATETIME

			SET		@getdate	= GETDATE()
			SELECT	@onlydate	= DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
			-- SET		@limitdate	= @onlydate + @bra_SaleOrderDisposeLimitDay


			DECLARE @rv		INT

			EXEC spSaleOrder_insertData
				@soh_id,
				@guid,
				@comp_id,
				@bra_id,
				@onlydate,
				@deliveryDate,
				@strNote1,
				@strNote2,
				@strNote3,
				@strNote4,
				'false',
				@sm_id,
				@cust_id,
				@st_id,
				@disc_id,
				@dl_id,
				@cb_id,
				@onlydate,
				@limitdate,
				@tt_id,
				@tt_class,
				1,					-- NOOO
				@user_id,
				'false',
				@getdate,
				@total,
				@df_id,
				@ssos_id,
				@ExchangeToCustomerCurrency,
				@cust_curr_id,
				NULL,
				-99,
				@return_value = @rv OUTPUT




			EXEC spSaleOrderHeader_updatePL_df_id
				@comp_id,
				@bra_id,
				@rv,
				@df_id4PL,
				@soh_loan, -- -- MOS 07-2022 x DM, estaba en NULL
				@soh_discount,
				@soh_internalAnnotation



			EXEC spSaleOrder_updateCurrExchange
				@comp_id,
				@bra_id,
				@rv,
				@cust_curr_id,
				@ExchangeToCustomerCurrency,
				0 --@decInCash


			EXEC spSaleOrder_UpdateIsEditing
				@comp_id,
				@bra_id,
				@soh_id,
				@guid,
				'False',
				'False',
				'False'

			EXEC spCustomer_updateIsEditing
				@comp_id,
				@cust_id,
				@user_id,
				'False',
				'False'


		END

END
GO






-- NO USAR, esto es un FIX de un Bug !!!!!!!
-- Se usa SOLO en [spCommercialTransactions_FixData]
-- ----------------------------------------------------------------------------
-- MOS 06-2024: el HIJO DE RECONTRA RE MIL REPUTAS NO sabe ni MATEMATICA x lo que hay q arreglar TODOS
-- los pedidos de NC y ND x dif de cot recalculando os TOTALES de los items y llevandolos al total del pedido
-- de manera proporcional usando los SP que ya hacen eso de wfmSaleOrder
-- NUNCA se pudieron emitir por FE x lo que no había saltado hasta ahora.
-- ----------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spSaleOrder_RecalculateTaxes_FixByTotal]
(
	@comp_id		INT,
	@bra_id			INT,
	@soh_id			INT,
	@user_id		INT,
	@lang_id		INT
)

AS


BEGIN


	SET NOCOUNT ON



	-- --------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------
	/*
	DECLARE	@comp_id		INT = 1,
			@bra_id			INT = 1,
			@soh_id			INT = 34904,
			@user_id		INT = 1,
			@lang_id		INT = -2
	*/
	-- --------------------------------------------------------------







	-- ------------------------------------------------------------------------------
	-- MOS: 12-2022
	-- Para que NO retorne nada , se usa en RecalculateTaxes para poder recalcular al IMPRIMIR un pedido
	-- ------------------------------------------------------------------------------
	DECLARE @bitNoReturnTable AS BIT = 'False'
	IF @lang_id < 0
		BEGIN
			SET @bitNoReturnTable = 'True'
			SET @lang_id = @lang_id * -1
		END
	-- ------------------------------------------------------------------------------







	DECLARE @limitdate		 DATETIME	= GETDATE()
	DECLARE @deliveryDate    DATETIME	= GETDATE()

	DECLARE @cust_id	INT,
			@intCustomerCurr_id	INT,
			@intBranchCurr_Id	INT,
			@disc_id	INT,
			@st_id		INT,
			@df_id		INT,
			@dl_id		INT,
			@sm_id		INT,
			@cb_id		INT,
			@tt_id		INT,
			@tt_class	VARCHAR(2),
			@ssos_id	INT,
			@guid		UNIQUEIDENTIFIER  ,
			@strNote1   NVARCHAR(2000),
			@strNote2   NVARCHAR(2000),
			@strNote3   NVARCHAR(2000),
			@strNote4   NVARCHAR(2000),
			@bra_PriceDecimalPlaces		AS INT,
			@ccp_id						AS INT
	DECLARE @df_id4PL					AS INT = NULL
	DECLARE @soh_loan					AS DECIMAL(19,6) = 0
	DECLARE @soh_internalAnnotation		AS NVARCHAR(100) = ''
	DECLARE @country_id		INT,
			@state_id		INT,
			@cust_curr_id	INT

	SELECT @guid		= newid()


	-- CONFIRMADO POR MARTIN QUE ES ASÍ   --   11-2018
	-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
	DECLARE @ExchangeToCustomerCurrency FLOAT --	'DECIMAL(19,6)
	DECLARE @decNewTotal AS DECIMAL(19,4) = 0
	DECLARE @decOldTotal AS DECIMAL(19,4) = 0


	SELECT  @decNewTotal		= tsoh.soh_total,
			@cust_id			= tsoh.cust_id,
			--@intCustomerCurr_id			= tc.curr_id,   11-2018
			@intCustomerCurr_id			= ISNULL(tsoh.soh_CustomerCurrency,tc.curr_id),
			@ExchangeToCustomerCurrency = tsoh.soh_ExchangeToCustomerCurrency,
			@intBranchCurr_Id   = tb.curr_id,
			@disc_id			= tsoh.disc_id,
			@st_id				= tsoh.st_id,
			@df_id				= tsoh.df_id,
			@dl_id				= tsoh.dl_id,
			@sm_id				= tsoh.sm_id,
			@cb_id				= tsoh.cb_id,
			@tt_id				= tsoh.tt_id,
			@tt_class			= tsoh.tt_class,
			@ssos_id			= tsoh.ssos_id,
			@strNote1			= tsoh.soh_observation1,
			@strNote2			= tsoh.soh_observation2,
			@strNote3			= tsoh.soh_observation3,
			@strNote4			= tsoh.soh_observation4,
			@bra_PriceDecimalPlaces = tdf.df_PriceDecimalPlaces,
			@ccp_id				= ISNULL(tsoh.ccp_id,-1),
			@user_id			= CASE
			        			      WHEN @user_id = -1  THEN tsoh.[user_id]
			        			      ELSE @user_id
			        			  END,
			@df_id4PL				= tsoh.df_id4PL,
			@soh_internalAnnotation = tsoh.soh_internalAnnotation,
			@limitdate			= tsoh.soh_limitDate,
			@deliveryDate		= tsoh.soh_deliveryDate

		FROM	tbSaleOrderHeader		tsoh			WITH (NOLOCK)
		INNER JOIN tbCustomer tc						WITH (NOLOCK)
			ON	tc.comp_id = tsoh.comp_id AND
				tc.cust_id = tsoh.cust_id
		INNER JOIN tbBranch tb							WITH (NOLOCK)
			ON	tb.comp_id = tsoh.comp_id AND
				tb.bra_id  = tsoh.bra_id
		INNER JOIN tbDocumentsFile tdf					WITH (NOLOCK)
			ON	tdf.comp_id = tsoh.comp_id AND
				tdf.df_id	= tsoh.df_id
		WHERE	tsoh.comp_id	= @comp_id
		AND		tsoh.bra_id		= @bra_id
		AND		tsoh.soh_id		= @soh_id





	SELECT	@country_id		= tc.country_id,
			@state_id		= tc.state_id,
			@cust_curr_id	= ISNULL(@intCustomerCurr_id,tc.curr_id)  --/*tc.curr_id*/  11-2018
		FROM	tbCustomer				tc			WITH (NOLOCK)
		WHERE	tc.comp_id		= @comp_id
		AND		tc.cust_id		= @cust_id



	DECLARE @bra_curr_id					INT,
			@bra_SaleOrderDisposeLimitDay	INT

	SELECT	@bra_curr_id					= tb.curr_id,
			@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays--,
			--@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces
		FROM	tbBranch				tb			WITH (NOLOCK)
		WHERE	tb.comp_id		= @comp_id
		AND		tb.bra_id		= @bra_id




	DECLARE @errormessage		VARCHAR(100)
	SET @errormessage = ''


	-- MOS 12-2022 x los HDP de MF 17941
	DECLARE @parLANGID AS INT =		@lang_id *	CASE
													WHEN @bitNoReturnTable = 'True' THEN	-1
													ELSE									 1
												END


	EXEC spSaleOrder_GetDataByIdforSaleOrderEdit
		@comp_id,
		@bra_id,
		@soh_id,
		@guid,
		@user_id,
		@errormessage OUTPUT,
		@parLANGID,
		'false',
		@bra_id





	IF LEN(@errormessage) = 0 --procesa
		BEGIN


			-- ---------------------------------------------------------------------------------------------
			-- MOS 06-2024: Fix tema del Reverendo hijo de reonctra re mil PUTASSSSSS
			-- ---------------------------------------------------------------------------------------------
			CREATE TABLE #tmpGetTotalsDataTMP
			(
				t1		INT,
				t2		DECIMAL(18,2),
				t3		DECIMAL(19,6),
				t4		DECIMAL(19,6),
				t5		DECIMAL(19,6),
				t6		DECIMAL(18,2),
				t7		DECIMAL(19,5),
				t8		INT,
				t9		DECIMAL(19,6),
				T10		NVARCHAR(4000),
				TotalNoInterest		DECIMAL(25,6)
			)


			INSERT INTO #tmpGetTotalsDataTMP
			EXEC sptmpTax_calculate
				@comp_Id,
				@bra_Id,
				@cust_Id,
				@guid,
				@intBranchCurr_Id,
				@disc_Id,
				@country_Id,
				@state_Id,
				@st_id,
				@bra_curr_Id,
				@cust_curr_id,
				@ExchangeToCustomerCurrency,
				'false',
				@df_id,
				'true',
				@dl_id,
				0,
				'false',
				'false',
				-1,
				@ccp_id


			-- aca tengo el total calculado x los ITEMS
			SELECT  @decOldTotal		= tmp.t2
				FROM	#tmpGetTotalsDataTMP		tmp			WITH (NOLOCK)

			DROP TABLE #tmpGetTotalsDataTMP


			-- Hago que los ITEMS se recalculen por el TOTAL ORIGINAL q estaba BINE cancluado
			EXEC spTempItemStock_setNewTotal  @comp_id, @bra_id, @guid,@decOldTotal,@decNewTotal, 1

			-- ---------------------------------------------------------------------------------------------






			---- CONFIRMADO POR MARTIN QUE ES ASÍ   11-2018
			---- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
			--DECLARE @ExchangeToCustomerCurrency	DECIMAL(19,6)
			--SELECT  @ExchangeToCustomerCurrency = dbo.fnGetExchange(@comp_id, 1, @bra_curr_id, @cust_curr_id, 0, 0, 'false')


			CREATE TABLE #tmpGetTotalsData
			(
				t1		INT,
				t2		DECIMAL(18,2),
				t3		DECIMAL(19,6),
				t4		DECIMAL(19,6),
				t5		DECIMAL(19,6),
				t6		DECIMAL(18,2),
				t7		DECIMAL(19,5),
				t8		INT,
				t9		DECIMAL(19,6),
				T10		NVARCHAR(4000),
				TotalNoInterest		DECIMAL(25,6)
			)


			INSERT INTO #tmpGetTotalsData
			EXEC sptmpTax_calculate
				@comp_Id,
				@bra_Id,
				@cust_Id,
				@guid,
				@intBranchCurr_Id,
				@disc_Id,
				@country_Id,
				@state_Id,
				@st_id,
				@bra_curr_Id,
				@cust_curr_id,
				@ExchangeToCustomerCurrency,
				'false',
				@df_id,
				'true',
				@dl_id,
				0,
				'false',
				'false',
				-1,
				@ccp_id





			DECLARE @total			DECIMAL(19,6),
					@soh_discount	DECIMAL(19,6)

			SELECT	@total			= t2,
					@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces),
					@soh_loan		= ROUND(t5, @bra_PriceDecimalPlaces)		-- MOS 07-2022 x DM
				FROM	#tmpGetTotalsData


			DROP TABLE #tmpGetTotalsData

			-- actualizar saleorderheader ?


			DECLARE @getdate		DATETIME
			DECLARE @onlydate		DATETIME

			SET		@getdate	= GETDATE()
			SELECT	@onlydate	= DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
			-- SET		@limitdate	= @onlydate + @bra_SaleOrderDisposeLimitDay


			DECLARE @rv		INT

			EXEC spSaleOrder_insertData
				@soh_id,
				@guid,
				@comp_id,
				@bra_id,
				@onlydate,
				@deliveryDate,
				@strNote1,
				@strNote2,
				@strNote3,
				@strNote4,
				'false',
				@sm_id,
				@cust_id,
				@st_id,
				@disc_id,
				@dl_id,
				@cb_id,
				@onlydate,
				@limitdate,
				@tt_id,
				@tt_class,
				1,					-- NOOO
				@user_id,
				'false',
				@getdate,
				@total,
				@df_id,
				@ssos_id,
				@ExchangeToCustomerCurrency,
				@cust_curr_id,
				NULL,
				-99,
				@return_value = @rv OUTPUT




			EXEC spSaleOrderHeader_updatePL_df_id
				@comp_id,
				@bra_id,
				@rv,
				@df_id4PL,
				@soh_loan, -- -- MOS 07-2022 x DM, estaba en NULL
				@soh_discount,
				@soh_internalAnnotation



			EXEC spSaleOrder_updateCurrExchange
				@comp_id,
				@bra_id,
				@rv,
				@cust_curr_id,
				@ExchangeToCustomerCurrency,
				0 --@decInCash


			EXEC spSaleOrder_UpdateIsEditing
				@comp_id,
				@bra_id,
				@soh_id,
				@guid,
				'False',
				'False',
				'False'

			EXEC spCustomer_updateIsEditing
				@comp_id,
				@cust_id,
				@user_id,
				'False',
				'False'


		END

END
GO


-- -----------------------------------------------------------------------------------
-- date : 04-09-2015
-- desc :  Grilla para mostrar todos los pedidos de la sucusal o grupo de sucusales que
--		   tengan algun articulo en la detail en el deposito de pcconfig .

-- En este módulo se podrá hacer la Recepción de Armado de PC, para buscar los pedidos
-- tiene que estar relacionado el Depósito para Módulo de Armado de Configuraciones de PC
-- en la Sucursal activa ( Solapa Pedidos ) con el Depósito del Artículo del pedido,
-- con el botón de Confirmar Recepción se abrirá una pantalla donde se pueden ver
-- los datos y al aceptar se realizará la transferencia entre el depósito de salida de armado
-- y el depósito de ingreso a sucursal de venta de los artículos de ese pedido.
-- -----------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spSaleOrder_ReceptionFromPCConfig_getDataByFilters]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@item_id			INT,
	@soh_id				INT,
	@guid4Cust			UNIQUEIDENTIFIER,
	@dateFrom			DATETIME,
	@dateTo				DATETIME

)
AS

	BEGIN

		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- ---------------------------------------------------------------------------------------------
		-- Testing
		-- ---------------------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@item_id			INT,
				@soh_id				INT,
				@guid4Cust			UNIQUEIDENTIFIER,
				@dateFrom			DATETIME,
				@dateTo				DATETIME

			SELECT
				@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@item_id			= -1,
				@soh_id				= 0,
				@guid4Cust			= '1166cb71-03d1-49db-8547-036f23be222f',
				@datefrom			= '2016-01-01',
				@dateto				= '2016-09-30'
*/
		-- ---------------------------------------------------------------------------------------------




		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET DEADLOCK_PRIORITY LOW
		SET LOCK_TIMEOUT 500
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------

		DECLARE @lGuidCust AS UNIQUEIDENTIFIER
		SET		@lGuidCust = CONVERT(UNIQUEIDENTIFIER,@guid4Cust)
		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de CLIENTEs para Filtros
		-- -------------------------------------------------------------
			DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
			INSERT INTO @tblComplexFilter_Customer
				SELECT tcf.sl_id
					FROM tbComplexFilter tcf
					WHERE tcf.sl_guid = @lGuidCust     AND
								  tcf.sl_selected = 'True'
			IF @@ROWCOUNT = 0
				BEGIN
					INSERT INTO @tblComplexFilter_Customer
						SELECT tc.cust_id
						FROM tbCustomer tc
							WHERE tc.comp_id = @comp_id
				END
		-- -------------------------------------------------------------


		-- TRAIGO TODOS LOS PEDIDOS CUYOS TURNOS DE ARMADO SE ENCUENTREN TERMINADOS
		-- PARA REALIZAR LA TRANSFERENCIA
		SELECT DISTINCT
			' '																					[ ], --BOTÓN PARA TRANSFERIR EL PEDIDO
			' '																					[ ], --BOTÓN PARA MOSTRAR LOS ARTÍCULOS DEL PEDIDO
			'# Pedido ' + CONVERT(VARCHAR(30), tsoh.soh_id)										[Pedido],
			tc.cust_name,
			tsoh.soh_deliveryDate,
			CONVERT(VARCHAR(30),tsoh.bra_id) + '-' + CONVERT(VARCHAR(30),tsoh.soh_id)			[ID]
			FROM tbSaleOrderHeader						tsoh	WITH(NOLOCK)
				--ESTE JOIN POSIBLEMENTE LO VUELE
				INNER JOIN tbSaleOrderDetail			tsod	WITH(NOLOCK)
					ON	tsod.comp_id	= tsoh.comp_id	AND
						tsod.bra_id		= tsoh.bra_id	AND
						tsod.soh_id		= tsoh.soh_id
				INNER JOIN tbSaleOrderAssemblyTurns		tsoat	WITH(NOLOCK)
					ON	tsoat.comp_id		= tsoh.comp_id	AND
						tsoat.soh_bra_id	= tsoh.bra_id	AND
						tsoat.soh_id		= tsoh.soh_id
				INNER JOIN @tblComplexFilter_Customer	tctmp
					ON	tctmp.cust_id	= tsoh.cust_id
				INNER JOIN tbCustomer					tc		WITH(NOLOCK)
					ON	tc.comp_id		= tsoh.comp_id	AND
						tc.cust_id		= tctmp.cust_id

			WHERE	tsoh.comp_id							= @comp_id				AND
					(@soh_id  = 0 OR tsoh.soh_id	= @soh_id)						AND
					tsoat.soa_turnDate BETWEEN @dateFrom AND @dateTo				AND
					tsod.sod_isFromPCConfigCTRLId IS NOT NULL						AND
					isnull(tsod.sod_PCCOnfigIsTransfered2Branch,'False') = 	'False'	AND
					--SI EL TOTAL DE TURNOS, ES IGUAL AL TOTAL DE TURNOS TERMINADOS
					--INDICA QUE EL PEDIDO YA HA SIDO PREPARADO EN SU TOTALIDAD
					--Y LO PONEMOS EN LA GRILLA PARA QUE LO MUESTRE PARA SER TRANSFERIDO
					(
						--TOTAL DE TURNOS QUE ESTAN TERMINADOS
						(SELECT
							COUNT(*)
							 FROM tbSaleOrderAssemblyTurns			tsoat2
							 WHERE	tsoat2.comp_id		= tsoh.comp_id	AND
									tsoat2.soh_bra_id	= tsoh.bra_id	AND
									tsoat2.soh_id		= tsoh.soh_id	AND
									ISNULL(tsoat2.soa_isAssembled,'False') = 'True'
						)
						=
						--TOTAL DE TURNOS DE ARMADO
						(SELECT
							COUNT(*)
							 FROM tbSaleOrderAssemblyTurns			tsoat3
							 WHERE	tsoat3.comp_id		= tsoh.comp_id		AND
									tsoat3.soh_bra_id	= tsoh.bra_id		AND
									tsoat3.soh_id		= tsoh.soh_id
						)
					)
					--AND COMO HAGO PARA QUE NO TRAIGA MÁS LOS PEDIDOS QUE YA SE ENVIARON????
					--DONDE TENGO ALGUN CAMPO QUE ME DIGA QUE YA SE ENVIÓ?????




		--	GROUP BY	tc.cust_name,
		--				tsoat.soa_turnDate,
		--				tsoh.soh_deliveryDate,
		--				tsoh.soh_id











		--VERSION ANTERIOR HECHA POR GA
		/*
		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET DEADLOCK_PRIORITY LOW
		SET LOCK_TIMEOUT 500
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------

		DECLARE @lGuidCust AS UNIQUEIDENTIFIER
		SET		@lGuidCust = CONVERT(UNIQUEIDENTIFIER,@guid4Cust)
		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de CLIENTEs para Filtros
		-- -------------------------------------------------------------
			DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
			INSERT INTO @tblComplexFilter_Customer
				SELECT tcf.sl_id
					FROM tbComplexFilter tcf
					WHERE tcf.sl_guid = @lGuidCust     AND
								  tcf.sl_selected = 'True'
			IF @@ROWCOUNT = 0
				BEGIN
					INSERT INTO @tblComplexFilter_Customer
						SELECT tc.cust_id
						FROM tbCustomer tc
							WHERE tc.comp_id = @comp_id
				END
		-- -------------------------------------------------------------

		-- --------------------------------------------------------------
		-- Pone las sucursales validas para incluir pedidos
		-- --------------------------------------------------------------
			DECLARE @tmpBranch TABLE(bra_id INT PRIMARY KEY)
			INSERT INTO @tmpBranch(bra_id) VALUES (@bra_id)
			DECLARE @brag_id AS INT
			SELECT @brag_id = tb.brag_id4SaleOrderALL
				FROM tbbranch tb
				WHERE	comp_id = @comp_id AND
						bra_id	= @bra_id
			IF @brag_id IS NOT NULL
				BEGIN
					INSERT INTO @tmpBranch(bra_id)
						SELECT tbgd.bra_id
							FROM tbBranchGroupDetail tbgd
							WHERE	tbgd.comp_id = @comp_id AND
									tbgd.brag_id = @brag_id AND
									tbgd.bra_id <> @bra_id
				END
		-- --------------------------------------------------------------

		SELECT
			' '												[ ],
			tb.bra_desc										[bra_desc],
			cu.cust_name									[cust_name],
			soh.soh_deliveryDate							[soh_deliveryDate],
			soh.soh_internalAnnotation						[soh_internalAnnotation],
			soh.soh_id										[ID]
			FROM dbo.tbSaleOrderHeader						soh		WITH (NOLOCK)
				INNER JOIN dbo.tbBranch						tb		WITH (NOLOCK)
					ON	tb.comp_id			= soh.comp_id	AND
						tb.bra_id			= soh.bra_id
				INNER JOIN tbCustomer						cu		WITH (NOLOCK)
					ON	cu.cust_id			= soh.cust_id	AND
						cu.comp_id			= soh.comp_id
				INNER JOIN @tmpBranch						tmpB
					ON	tmpB.bra_id			= soh.bra_id
				INNER JOIN @tblComplexFilter_Customer		tcfc
					ON	tcfc.cust_id		= cu.cust_id
			WHERE	soh.comp_id				= @comp_id							AND
					(@soh_id = 0 OR soh.soh_id = @soh_id)						AND
					(soh.soh_deliveryDate	BETWEEN @datefrom  AND	@dateto)	AND
					(
						 EXISTS (SELECT 1
									FROM	tbSaleOrderDetail								sod	WITH (NOLOCK)
									WHERE	sod.comp_id		= @comp_id						AND
											sod.bra_id		= @bra_id						AND
											sod.soh_id		= soh.soh_id					AND
											sod.stor_id		= ISNULL(tb.stor_id4PCConfig,-1)AND
											(@item_id = -1 OR sod.item_id		= @item_id)
								)
					)
			ORDER BY soh.comp_id,
					 soh.bra_id,
					 soh.soh_id
		-- ----------------------------------------------------------------------------------------
		*/

	END
GO



-- =============================================
-- Author:		GA
-- Create date: 07/30/2010
-- Description:	Reporte de pedidos pendientes
-- =============================================




-- =============================================
-- Author:		GA
-- Create date: 17/01/2021
-- Description:	ticket 14263 - Se agregó el CF de Clientes,  Proveedores de Artículo, y el de Items
-- =============================================



CREATE PROCEDURE [dbo].[spSaleOrder_Report]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,
	@cust_id			int,
	@item_id			int,
	@datefrom			datetime,
	@dateto				datetime,
	@sm_id				int,
	@user_id			int,
	@disc_id			int,
	@dl_id				int,
	@df_id				int,
	@stor_id			int,
	@st_id				int,
	@ssos_id			INT,
	@bra_id				INT,

	@CustomerGuid		VARCHAR(50),
	@SupplierGuid		VARCHAR(50),					-- Proveedores de Artículos
	@ItemGuid			VARCHAR(50),




	@intBranch4Lang		INT,
	@prof_id			INT



)

AS

SET NOCOUNT ON


SET DATEFORMAT 'ymd'

BEGIN

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


--------------------------------------------------------------------------------
-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
--------------------------------------------------------------------------------
/*
DECLARE @comp_id			int,
		@lang_id			int,
		@page_id			int,

		@cust_id			int,
		@item_id			int,
		@datefrom			datetime,
		@dateto				datetime,
		@sm_id				int,
		@user_id			int,
		@disc_id			int,
		@dl_id				int,
		@df_id				int,
		@stor_id			int,
		@st_id				int,
		@ssos_id			int,
		@bra_id				INT,
		@intBranch4Lang		INT



SELECT	@comp_id			=1,
		@lang_id			=2,
		@page_id			=10066,

		@user_id            =-1,
		@cust_id			=-1,
		@item_id			=-1,
		@sm_id				=-1,
		@disc_id			=-1,
		@stor_id			=-1,
		@datefrom			='1900-01-01',
		@dateto				='9999-12-31',
		@ssos_id			= 0,
		@dl_id				= -1,
		@df_id				= -1,
		@st_id				= -1,
		@bra_id				= 1,
		@intBranch4Lang		= 2
*/
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------




		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @lGuidCustomer AS UNIQUEIDENTIFIER
		SET		@lGuidCustomer = CONVERT(UNIQUEIDENTIFIER,@CustomerGuid)
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuidCustomer     AND
							  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0 AND @cust_id > 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer(cust_id)
					SELECT @cust_id
			END

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT tc.cust_id
					FROM tbCustomer tc
					WHERE tc.comp_id = @comp_id
			END
		-- -------------------------------------------------------------

		 -- -------------------------------------------------------------
		 -- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
		 -- -------------------------------------------------------------
		 DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
		 INSERT INTO @tblComplexFilter_Supplier
		  SELECT tcf.sl_id
		   FROM tbComplexFilter tcf
		   WHERE tcf.sl_guid = @SupplierGuid     AND
				tcf.sl_selected = 'True'
		 IF @@ROWCOUNT = 0
		  BEGIN
		   INSERT INTO @tblComplexFilter_Supplier
				SELECT
					ts.supp_id
					FROM tbSupplier ts
					WHERE ts.comp_id = @comp_id
		  END
		 -- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Items para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @lGuidItems AS UNIQUEIDENTIFIER
		SET		@lGuidItems = CONVERT(UNIQUEIDENTIFIER,@ItemGuid)
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuidItems     AND
							  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0 AND @item_id > 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items(item_id)
					SELECT @item_id
			END

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ts.item_id
					FROM tbItem ts
						WHERE ts.comp_id = @comp_id
			END
		-- -------------------------------------------------------------


		--Recupero en una variable el estado en controles por perfil . Con "(*)" Por defecto deshabilitado.
		-- (*) Ocultar precio.

		Declare @ctrl_hidecolumns INT
		Set @ctrl_hidecolumns = 0
		IF EXISTS(

						select 1
							from tbControlProfiles			WITH (NOLOCK)
							where	comp_id			= @comp_id			AND
									bra_id			= @intBranch4Lang	AND
									prof_id			= @prof_id			AND
									page_id			= 212				AND
									ctrl_id			= 6105

					 )

				BEGIN

					Set @ctrl_hidecolumns = 1

				END



	set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	select		convert(varchar,tsoh.bra_id) + '-' + convert(varchar,tsoh.soh_id) [soh_id],
				tsoh.soh_deliveryDate [soh_cd],
				tsoh.soh_internalAnnotation,
				td.disc_desc,
				sm.sm_name,
				us.user_lastname + ', ' + user_firstname [User_Name],
				ts.stor_desc,
				tsos.ssos_desc,
				ti.item_code,
				isnull(ti.item_desc,tsod.sod_itemDesc)[item_desc],
				tsod.sod_qty,



				case when @ctrl_hidecolumns = 0 then
						tsod.sod_price * tsod.sod_qty
				ELSE
						0
				END																[sod_price],

				--tsod.sod_price * tsod.sod_qty [sod_price],






				cc.curr_symbol [curr_desc],
				tsod.sod_itemDiscount,
				--tsot.tm_total,
				case when ti.item_expser = 'true' then
					(select tov.optval_desc
					from tbsysOptionsValues tov
					where tov.lang_id		=@lang_id
					and   tov.optval_class  = 1
					and   tov.optval_id		= 1)
				else
					(select tov.optval_desc
					from tbsysOptionsValues tov	WITH (NOLOCK) where tov.lang_id = @lang_id and tov.optval_class = 1 and tov.optval_id = 0)
				end [serialized],
				cu.cust_name,
				dbo.fnGetExchange(@comp_id, tsod.sod_price * tsod.sod_qty ,tsod.[curr_id],tb.[curr_id] , 0, 0, 'FALSE')[sod_price2]





	from tbSaleOrderDetail								tsod		WITH (NOLOCK)


	inner join tbSaleOrderHeader						tsoh		WITH (NOLOCK)
	on  tsoh.comp_id			= tsod.comp_id
	AND tsoh.bra_id				= tsod.bra_id
	AND tsoh.soh_id				= tsod.soh_id

	inner join tbSalesman								sm			WITH (NOLOCK)
	on  sm.comp_id				= tsoh.comp_id
	and sm.sm_id				= tsoh.sm_id

	inner  join tbCustomer								cu			WITH (NOLOCK)
	on  cu.comp_id				= tsoh.comp_id
	and cu.cust_id				= tsoh.cust_id

	INNER JOIN @tblComplexFilter_Customer				tmpS
	ON tmpS.cust_id				= cu.cust_id

	inner join dbo.tbBranch								tb			WITH (NOLOCK)
	on	tb.comp_id				= tsoh.comp_id
	And tb.bra_id				= tsoh.bra_id

	inner join dbo.tbUser								us	WITH (NOLOCK)
	on	us.[user_id]			= tsod.[user_id]

	inner join tbsysCurrency			 				cc	WITH (NOLOCK)
	ON	cc.curr_id				= tsod.curr_id

	left join tbItem									ti	WITH (NOLOCK)
	on  ti.comp_id				= tsod.comp_id
	AND ti.item_id				= tsod.item_id

	LEFT JOIN @tblComplexFilter_Items 					tmpi
	ON tmpi.item_id				= ti.item_id

	LEFT JOIN @tblComplexFilter_Supplier 				tmpsi
	ON tmpsi.supp_id			= ti.supp_id --OR
	   --ti.supp_id				IS NULL

	left join tbStorage									ts	WITH (NOLOCK)
	on  ts.comp_id				= tsod.comp_id
	AND ts.stor_id				= tsod.stor_id

	inner join tbsysSaleOrderStatus						tsos	WITH (NOLOCK)
	on  tsos.ssos_id			= tsoh.ssos_id

	inner join tbDiscount								td	WITH (NOLOCK)
	on	td.comp_id				= tsoh.comp_id
	and td.disc_id				= tsoh.disc_id

	inner join tbDocumentsFile							tdf	WITH (NOLOCK)
	on  tdf.comp_id				= tsoh.comp_id
	and tdf.bra_id				= tsoh.bra_id
	and tdf.df_id				= tsoh.df_id

	inner join tbsysDocuments							td2	WITH (NOLOCK)
	on	td2.sd_id				= tdf.sd_id
	and td2.sd_isQuotation		= 'False'


	WHERE	tsoh.comp_id	=	@comp_id
	AND 	(@ssos_id		= 1000 OR
			 @ssos_id		= 0	   OR
			 @ssos_id		= 1001 OR
			 @ssos_id		= 1002 OR
			 @ssos_id		= 1003 OR
			 tsoh.ssos_id	=	@ssos_id)

	AND 	(@cust_id		= -1   OR cu.cust_id	=	@cust_id	)
	AND 	(@item_id		= -1   OR ti.item_id	=	@item_id	)
	AND		(tmpi.item_id IS NOT NULL  OR tsod.item_id IS NULL		)
	AND		(tmpsi.supp_id IS NOT NULL OR tsod.item_id IS NULL		)
	AND		(@user_id	    = -1   OR us.[user_id]	=	@user_id	)
	AND		(@sm_id			= -1   OR sm.sm_id		=	@sm_id		)
	AND		(@stor_id		= -1   OR ts.stor_id	=	@stor_id    )
	AND		(@disc_id		= -1   OR td.disc_id	=	@disc_id	)
	AND		(@dl_id			= -1   OR tsoh.dl_id	=	@dl_id		)
	AND		(@df_id			= -1   OR tsoh.df_id	=	@df_id		)
	AND		(@st_id			= -1   OR tsoh.st_id	=	@st_id		)
	AND		 tsoh.soh_cd		between @datefrom  and	@dateto
	--TICKET 6340
	AND		(
				@bra_id		= -1 OR
				tsoh.bra_id = @bra_id
			)
	--and		tsod.soh_id = 7562

	exec [spReports_getData3]@comp_id,@intBranch4Lang, @lang_id,	@page_id



	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

	SELECT	(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 174 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)				[params1],

			 CASE @cust_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
			    			WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select	tc2.cust_name FROM tbCustomer tc2
							WHERE tc2.comp_id = @comp_id AND tc2.cust_id = @cust_id) END									[params2],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 103 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)				[params3],

			 CASE @item_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
			    			WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select	ti.item_desc FROM tbItem ti
							WHERE ti.comp_id = @comp_id AND ti.item_id = @item_id) END										[params4],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 177
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =1 )									[params5],

      			-- @datefrom [DateParams1],
				convert(varchar,day(@datefrom))+'/'+convert(varchar,month(@datefrom))+'/'+convert(varchar,year(@datefrom))		[DateParams1],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				 WHERE t.ctrl_id = 384
      				 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =1 )								[params6],

      				-- @dateto [DateParams2],
	convert(varchar,day(@dateto))+'/'+convert(varchar,month(@dateto))+'/'+convert(varchar,year(@dateto))		[DateParams2],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 172 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)				[params7],

			 CASE @sm_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
			    			WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select	ts.sm_name FROM tbSalesman ts
							WHERE ts.comp_id = @comp_id AND ts.sm_id= @sm_id) END											[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 1 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params9],

			 CASE @user_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    				WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select	tu.user_lastname + ', ' + tu.user_firstname [User_Name] FROM tbUser tu
							WHERE tu.comp_id = @comp_id AND tu.[user_id]= @user_id) END										[params10],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 173 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params11],

			 CASE @disc_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    				WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select td.disc_desc FROM tbDiscount td
							WHERE td.comp_id = @comp_id AND td.disc_id= @disc_id) END										[params12],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 170 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params13],

			 CASE @dl_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    				WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select td.dl_name FROM tbDelivery td
							WHERE td.comp_id = @comp_id AND td.dl_id= @dl_id) END											[params14],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 171 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params15],

			 CASE @df_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    				WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select tdf.df_desc FROM tbDocumentsFile tdf
							WHERE tdf.comp_id = @comp_id AND tdf.df_id= @df_id) END											[params16],



			(SELECT tswn.word_desc FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 111 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params17],

			 CASE @stor_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    				WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select ts.stor_desc FROM tbStorage ts
							WHERE ts.comp_id = @comp_id AND ts.stor_id= @stor_id) END										[params18],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 225 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params19],

			 CASE @st_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    				WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select tst.st_desc FROM tbSalesTerms tst
							WHERE tst.comp_id = @comp_id AND tst.st_id= @st_id) END											[params20],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 116 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params21],

			 CASE @ssos_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    				WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(select DISTINCT tov.optval_desc from tbsysOptionsValues tov
						  where tov.optval_id = @ssos_id and tov.optval_class = 110 and tov.lang_id=@lang_id)		END		[params22],

		--TICKET 6340
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t
					INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      				WHERE t.ctrl_id = 28 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params23],

			 CASE @bra_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    				WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(SELECT tb.bra_desc
				    	   FROM tbBranch tb WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id)		END					[params24]

END

GO






-- =============================================
-- Author:
--              MOS  09/2014
-- Create date: <Create Date,,>
-- Description:
-- =============================================


CREATE  PROCEDURE [dbo].[spSaleOrder_SaveAuthorizations]
(
	@tis_guid					as	uniqueidentifier,
    @comp_id					as	int,
	@bra_id						as	int,
	@soh_id						AS  INT
)
as

BEGIN


	DELETE FROM tbAutorizationRequest_PendingSaleOrders
		WHERE	comp_id		= @comp_id	AND
				soh_bra_id	= @bra_id	AND
				soh_id		= @soh_id


	INSERT INTO tbAutorizationRequest_PendingSaleOrders	WITH (ROWLOCK)
	(
		comp_id,
		aut_id,
		[user_id],
		aure_cd,
		aure_isok,
		aure_obs_1,
		aure_obs_2,
		aure_obs_3,
		aure_obs_4,
		aure_image,
		sysCode_id,
		aure_user_id,
		aure_guid,
		aure_genericId,
		aure_genericGuid,
		bra_id,
		aure_isEditing,
		aure_isEditingCd,
		aure_pageHTML,
		aure_guid_postBack,
		prof_id,
		aure_TypeOfReq,
		aure_Link,
		aure_auxValueInt,
		aure_auxValueDecimal,
		aure_auxValueDecimal2,
		aure_auxString,
		aure_transactionID,
		aure_pageHTMLPlus,
		sessionGUID,
		aure_pageHTMLIsSaved,
		aure_pageHTMLIsMailSended,
		aure_originalURL,
		aure_remoteGUID,
		soh_bra_id,
		soh_id,
		cust_id,
		aure_valueCheck
	)
	SELECT tar.comp_id, tar.aut_id, tar.[user_id], tar.aure_cd, tar.aure_isok,
	       tar.aure_obs_1, tar.aure_obs_2, tar.aure_obs_3, tar.aure_obs_4,
	       tar.aure_image, tar.sysCode_id, tar.aure_user_id, tar.aure_guid,
	       tar.aure_genericId, tar.aure_genericGuid, tar.bra_id,
	       tar.aure_isEditing, tar.aure_isEditingCd, tar.aure_pageHTML,
	       tar.aure_guid_postBack, tar.prof_id, tar.aure_TypeOfReq, tar.aure_Link,
	       tar.aure_auxValueInt, tar.aure_auxValueDecimal,
	       tar.aure_auxValueDecimal2, tar.aure_auxString, tar.aure_transactionID,
	       tar.aure_pageHTMLPlus, tar.sessionGUID, tar.aure_pageHTMLIsSaved,
	       tar.aure_pageHTMLIsMailSended, tar.aure_originalURL,
	       tar.aure_remoteGUID,@bra_id,@soh_id , tar.cust_id,
	       tar.aure_valueCheck
		FROM tbAutorizationRequest tar	WITH (NOLOCK)
		WHERE tar.aure_guid = @tis_guid AND
			  tar.aure_isok <> 'A'

	DELETE FROM tbAutorizationRequest
		WHERE	aure_guid = @tis_guid AND
				aure_isok <> 'A'


END
GO




-- Log:
-- MOS 01-2024: Ticket 20759; Se agregó la posibilidad de serializar x EAN en Pedidos de Producción.



CREATE PROCEDURE [dbo].[spSaleOrder_setSerials]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@soh_id				int,
	@serial				varchar(100),
	@qty				int,
	@errormessage		varchar(200) output,
	@return_value		int output
)
as


BEGIN



	SET NOCOUNT ON


-- -----------------------------------------------------
-- Testing
-- -----------------------------------------------------
/*
	declare @comp_id		int,
			@lang_id		int,
			@bra_id			int,
			@soh_id			int,
			@serial			varchar(100),
			@qty			INT = 1,
			@errormessage	varchar(200),
			@return_value	int

	select  @comp_id		=  1,
			@lang_id		=  2,
			@bra_id			=  1,
			@soh_id			=  180664,
			@serial			=  'AD01'

	DROP TABLE #tmp_count
*/
-- -----------------------------------------------------


	-- Opciones en tbBranch para búsqueda de artículos que DIGAN que van por EAN.!
	--0	5004	Todas las opciones de Búsqueda
	--1	5004	Por Código  de Artículo/EAN únicamente
	--2	5004	Por Código  de Fabricante  únicamente
	--3	5004	Por Código  Alternativo únicamente
	--4	5004	Por Códigos Alternativos únicamente
	--5 5004    Por EAN Asignados Unicamente
	DECLARE @bra_SaleOrderPreparation_EANSearchOption AS INT
	SELECT  @bra_SaleOrderPreparation_EANSearchOption = IsNull(tb.bra_SaleOrderPreparation_EANSearchOption,0)
		FROM tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id



	--NO COMENTAR
	set	@return_value = 0
	set	@errormessage = ''


	--LLamo al store q verifica si el numero de serie y actualiza en tbitemserials
	EXEC [spItemSerialsFromOtherERP_UpdateSerial] @comp_id,	@bra_id	,@soh_id ,@serial



	--	Valida si el Nro de Serie es Inexistente.
	DECLARE @bitExpSer			AS BIT
	DECLARE @bitExpEAN			AS BIT
	DECLARE @intExpEANDUNQty	AS INT = 0
	DECLARE @item_id			AS INT
	DECLARE @sd_id				AS INT
	declare @is_id				as INT
	DECLARE @isAvailable		AS BIT
	DECLARE @intStorID4SO		AS INT
	DECLARE @intStorID4Serial	AS INT
	DECLARE @bitStorID4Serial	AS BIT		-- Permite numeros de serie de diferentes depositos?
	DECLARE @bitIsAvailableForced AS BIT

	SET		@bitStorID4Serial = dbo.fnGetIsItemSerial4DifStorage(@comp_id,@bra_id)



	select	@item_id			= tis.item_id ,
			@isAvailable		= tis.is_available,
			@sd_id				= tdf.sd_id,
			@intStorID4Serial	= tis.stor_id,
			@is_id				= tis.is_id,
			@bitExpSer			  = IsNull(ti.item_expser,'False'),
			@bitIsAvailableForced = ISNULL(tdf.df_SaleOrderPreparation_ForceIsAvailable2True,'False')
		from	dbo.tbItemSerials tis				WITH (NOLOCK)
		INNER JOIN tbItem ti						WITH (NOLOCK)
			ON	ti.comp_id = tis.comp_id	AND
				ti.item_id = tis.item_id
		INNER JOIN tbSaleOrderHeader tsoh			WITH (NOLOCK)
			ON  tsoh.comp_id = tis.comp_id
			AND tsoh.bra_id  = @bra_id
			AND tsoh.soh_id  = @soh_id
		INNER JOIN tbDocumentsFile tdf				WITH (NOLOCK)
			ON  tdf.comp_id = tsoh.comp_id
			AND tdf.bra_id  = tsoh.bra_id
			AND tdf.df_id   = tsoh.df_id
		where	tis.is_serial = @serial	AND
				tis.comp_id	  = @comp_id


	-- MOS 01-2024
	IF @sd_id IS NULL
		BEGIN
			SELECT 	@sd_id				= tdf.sd_id
				FROM 	tbSaleOrderHeader tsoh			WITH (NOLOCK)
				INNER JOIN tbDocumentsFile tdf				WITH (NOLOCK)
					ON  tdf.comp_id		= tsoh.comp_id
					AND tdf.bra_id		= tsoh.bra_id
					AND tdf.df_id		= tsoh.df_id
				WHERE	tsoh.comp_id	= @comp_id AND
						tsoh.bra_id		= @bra_id AND
						tsoh.soh_id		= @soh_id
		END



	IF @item_id IS NULL
	BEGIN
		set @return_value	= 1
	END

	IF @bitExpSer = 'False' AND @item_id IS NOT NULL
	BEGIN
		set @return_value	= 8
	END




	-- ----------------------------------------------------------
	-- Valida si está Disponible
	-- ----------------------------------------------------------
	IF @bitIsAvailableForced = 'True'		-- Si se fuerza el estado segun el documento
		BEGIN
			IF @sd_id = 3
				BEGIN
					SET @isAvailable = 'False'	-- Si es NC lo pone el Falso
				END
			ELSE
				BEGIN
					SET @isAvailable = 'True'	-- Sino como disponible
				END
		END
	ELSE
		BEGIN
			IF @return_value  = 0 AND ((@sd_id = 3 AND @isAvailable = 'True') OR (@sd_id <> 3 AND @isAvailable = 'False'))
				BEGIN
					set @return_value = 4
					set	@errormessage = 'ATENCIÓN: El número de serie seleccionado NO ESTÁ DISPONIBLE.'
				END
		END
	-- ----------------------------------------------------------




	--	Valida si el Artículo pertenece al Pedido.
	IF @return_value = 0
	BEGIN

		if  not exists (SELECT TOP 1 	1
							from	tbsaleorderdetail	WITH (NOLOCK)
							where		comp_id = @comp_id
								and		bra_id	= @bra_id
								and		soh_id	= @soh_id
								and		item_id = @item_id
								)
			/*
			* AGREGADO PARA QUE PERMITA INGRESAR SERIALES DE ITEMS ASOCIADOS A LOS ARTíCULOS
			* INGRESADOS EN UN PEDIDO DE PRODUCCIÓN
			* */
			AND
			NOT EXISTS (SELECT TOP 1 	1
						FROM	tbSaleOrderDetail					tsod		WITH (NOLOCK)

								INNER JOIN tbItemComposition		tic			WITH (NOLOCK)
								ON	tic.comp_id		= tsod.comp_id
								AND tic.item_id		= tsod.item_id
								AND tic.item_id_1	= @item_id

						WHERE	tsod.comp_id	= @comp_id
						AND 	tsod.bra_id		= @bra_id
						AND 	tsod.soh_id		= @soh_id
						)

			--set	@errormessage = 'ATENCIÓN: El Artículo NO pertenece al Pedido.'
			set @return_value = 2

	END




	--	Valida si hay pendientes en el pedido del artículo seleccionado
	IF @return_value = 0
	BEGIN

		DECLARE @intQtyOfItemsInSO			AS INT
		DECLARE @intQTYOfItemsSerialized	AS INT

		--SELECT @item_id,@bitStorID4Serial,@intStorID4Serial


		--si el artículo pertenece al pedido se realiza una validación
		--si el artículo está asociado a un artículo que pertenece al pedido se realiza otra validación
		IF EXISTS (SELECT TOP 1 1
		           from	dbo.tbSaleOrderDetail		WITH (NOLOCK)
					where	comp_id = @comp_id
					and		bra_id	= @bra_id
					and		soh_id	= @soh_id
					and		item_id = @item_id
					)
			BEGIN

				SET @intQtyOfItemsInSO = ISNULL((	select	 sum(sod_qty)
														from	dbo.tbSaleOrderDetail	WITH (NOLOCK)
														where	comp_id = @comp_id
														and		bra_id	= @bra_id
														and		soh_id	= @soh_id
														and		item_id = @item_id

														AND ( @bitStorID4Serial = 'True' OR (stor_id = @intStorID4Serial))
											),0)


				SET @intQTYOfItemsSerialized = ISNULL((SELECT COUNT(*)
														 FROM	tbSaleOrderSerials tsos		WITH (NOLOCK)
														 INNER JOIN tbItemSerials tis		WITH (NOLOCK)
														 ON		tis.comp_id = tsos.comp_id
															AND tis.is_id	= tsos.is_id
														 WHERE	tsos.comp_id= @comp_id
															AND tsos.bra_id = @bra_id
															AND tsos.soh_id = @soh_id
															AND tis.item_id = @item_id
															AND ( @bitStorID4Serial = 'True' OR (tis.stor_id = @intStorID4Serial))
												),0)


				IF	@intQtyOfItemsInSO - @intQTYOfItemsSerialized <= 0 set @return_value = 3

			END
		ELSE
			BEGIN

				SET @intQtyOfItemsInSO = ISNULL((	select	 sum(tsod.sod_qty * tic.icomp_qty)
														from	dbo.tbSaleOrderDetail tsod				WITH (NOLOCK)
																INNER JOIN tbItemComposition tic		WITH (NOLOCK)
																ON  tic.comp_id = tsod.comp_id
																AND tic.item_id = tsod.item_id
																AND tic.item_id_1 = @item_id
														where	tsod.comp_id = @comp_id
														and		tsod.bra_id	 = @bra_id
														and		tsod.soh_id	 = @soh_id

														AND ( @bitStorID4Serial = 'True' OR (tsod.stor_id = @intStorID4Serial))
											),0)


				SET @intQTYOfItemsSerialized = ISNULL((SELECT COUNT(*)
														 FROM	tbSaleOrderSerials tsos		WITH (NOLOCK)
														 INNER JOIN tbItemSerials tis		WITH (NOLOCK)
														 ON		tis.comp_id = tsos.comp_id
															AND tis.is_id	= tsos.is_id
														 WHERE	tsos.comp_id= @comp_id
															AND tsos.bra_id = @bra_id
															AND tsos.soh_id = @soh_id
															AND tis.item_id = @item_id
															AND ( @bitStorID4Serial = 'True' OR (tis.stor_id = @intStorID4Serial))
												),0)


				IF	@intQtyOfItemsInSO - @intQTYOfItemsSerialized <= 0 set @return_value = 3

			END
		--select @intQtyOfItemsInSO, @intQTYOfItemsSerialized

	END



	-- ----------------------------------------------------------------------------------------------------------
	-- Si se permite serializar items de cualquier deposito solo debe haber items de UN deposito en el pedido.-!
	-- Esto es porque luego se fija en el deposito del numero de serie que ahora pertenece al NUEVO DEPOSITO.
	-- Si hubiese mas de un deposito el sistema no sabria que deposito ponerle al nro. de serie.!!!!!!!!!!!!!!!!
	-- ----------------------------------------------------------------------------------------------------------
	IF @bitStorID4Serial = 'True'
		BEGIN

			SELECT	COUNT(*) [count], tsod.stor_id
			INTO	#tmp_count
			FROM	tbSaleOrderDetail tsod		WITH (NOLOCK)
			INNER JOIN tbItem ti				WITH (NOLOCK)
				ON		ti.comp_id		= tsod.comp_id
					AND ti.item_id		= tsod.item_id
					AND ti.item_expser	= 'True'
			WHERE	tsod.comp_id	= @comp_id
				AND	tsod.bra_id		= @bra_id
				AND	tsod.soh_id		= @soh_id

			GROUP BY tsod.stor_id


  				IF @@ROWCOUNT > 1
  					BEGIN

  						-- Pone el deposito del primer item que encuentre en el pedido
  						-- Esto antes tiraba el error arriba descripto
  						-- 04-2015 x Nucleo
						SELECT TOP 1	@intStorID4SO =  tsod.stor_id
  							FROM	tbSaleOrderDetail tsod		WITH (NOLOCK)
  							INNER JOIN tbItem ti				WITH (NOLOCK)
  								ON		ti.comp_id		= tsod.comp_id
  									AND ti.item_id		= tsod.item_id
  									AND ti.item_expser	= 'True'
  							WHERE	tsod.comp_id	= @comp_id
	  							AND	tsod.bra_id		= @bra_id
  								AND	tsod.soh_id		= @soh_id
  								AND tsod.item_id	= @item_id

  							GROUP BY tsod.stor_id

  						-- SET @return_value = 6
  					END
  				ELSE
  					BEGIN
						SELECT TOP 1	@intStorID4SO =  tsod.stor_id
  							FROM	tbSaleOrderDetail tsod		WITH (NOLOCK)
  							INNER JOIN tbItem ti				WITH (NOLOCK)
  								ON		ti.comp_id		= tsod.comp_id
  									AND ti.item_id		= tsod.item_id
  									AND ti.item_expser	= 'True'
  							WHERE	tsod.comp_id	= @comp_id
	  							AND	tsod.bra_id		= @bra_id
  								AND	tsod.soh_id		= @soh_id

  							GROUP BY tsod.stor_id
  					END

		END
	-- ----------------------------------------------------------------------------------------------------------


	-- verificar que el serial ya no esté tomado
	If	@return_value = 0
	BEGIN
		IF EXISTS (SELECT TOP 1 1
				   FROM tbSaleOrderSerials tsos		WITH (NOLOCK)
				   WHERE tsos.comp_id = @comp_id
					AND  tsos.is_id   = @is_id)

		SET @return_value = 5
		set	@errormessage = 'ATENCIÓN: El número de serie está tomado en un pedido.'
	END



	-- verificar que el Lote NO ESTE BLOQUEADO si es un Serial via Compras, Bloquear Lotes para Preparacion
	If	@return_value = 0	AND @is_id IS NOT NULL
	BEGIN
		IF EXISTS (	SELECT TOP 1 1
		           		FROM tbItemSerials		tis			WITH (NOLOCK)
		           		INNER JOIN tbImportData tid			WITH (NOLOCK)
		           			ON	tid.it_transaction	= tis.it_transaction
						WHERE	tis.comp_id			= @comp_id		AND
								tid.comp_id			= tis.comp_id	AND
								tis.is_id			= @is_id		AND
								tid.impdata_blocked4SOPreparation = 'True'
					)
			BEGIN
				DECLARE @intImpData_ID AS INT = 0
					SELECT @intImpData_ID = tid.impData_id
		           		FROM tbItemSerials		tis			WITH (NOLOCK)
		           		INNER JOIN tbImportData tid			WITH (NOLOCK)
		           			ON	tid.it_transaction	= tis.it_transaction
						WHERE	tis.comp_id			= @comp_id		AND
								tid.comp_id			= tis.comp_id	AND
								tis.is_id			= @is_id		AND
								tid.impdata_blocked4SOPreparation = 'True'

				set	@return_value = 20
				set	@errormessage = 'ATENCIÓN: El Lote al que pertenece el Número de Serie se encuentra Bloqueado. ID Lote: ' + CONVERT(NVARCHAR(10),@intImpData_ID)
				RETURN
			END

	END






	--	si está todo Ok se actualizan las tablas correspondientes
	If	@return_value = 0
		BEGIN

			exec [spSaleOrderSerials_insertData]
														@comp_id,
														@is_id,
														@bra_id,
														@soh_id,
														null,
														@return_value

			exec [spItemSerials_updateData_isAvailable]
														@comp_id,
														@serial,
														'False'

			IF @bitStorID4Serial = 'True'	-- Si permite numeros de serie de cualquier deposito le pone al numero de serie el deposito al que se lo esta llevando ( el del pedido)
				BEGIN
					UPDATE tbItemSerials
						SET stor_id = @intStorID4SO
					WHERE	comp_id = @comp_id
						AND is_id	= @is_id


				END

		END

	ELSE

		-- ---------------------------------
		-- Control por EAN
		-- ---------------------------------
		BEGIN

			SET @serial = dbo.fnStrAllTrim(@serial)
			declare @intItem_Id as INT
			SET @intItem_Id			= NULL
			SET @intExpEANDUNQty	= 1

			IF @bra_SaleOrderPreparation_EANSearchOption IN (5)
				BEGIN
					--SELECT 1 / 0
					select @intItem_Id		= ti.item_id,
						   @bitExpEAN		= IsNull(ti.item_expean,'False'),
						   @intExpEANDUNQty =	CASE
													WHEN tie.ie_ean	= @serial AND tie.ie_isDUC = 'True' AND tie.ie_DUNQty > 0 THEN tie.ie_DUNQty
													ELSE 1
												END
									from tbItem ti							WITH (NOLOCK)
									INNER JOIN tbItemEAN tie				WITH (NOLOCK)
										ON	tie.comp_id = ti.comp_id AND
											tie.item_id = ti.item_id
									where	tie.comp_id	= @comp_id	AND
											tie.ie_ean	= @serial	AND
											ti.item_expean  = 'True'
					IF @intItem_Id IS NULL
						BEGIN
							--select 1 / 0
							select @intItem_Id = ti.item_id,
								   @bitExpEAN  = 'True'   --IsNull(ti.item_expean,'False')
											from tbItem ti					WITH (NOLOCK)
											where	ti.comp_id		= @comp_id	AND
													ti.item_code	= @serial	AND
													--ti.item_expean  = 'True'	AND	-- MOS 07-2022: Debe toimar en True o False, estaba en False antes...
													ti.item_expser  = 'False'
						END
				END

			IF @bra_SaleOrderPreparation_EANSearchOption IN (0,1)
				BEGIN
					select @intItem_Id = ti.item_id,
						   @bitExpEAN  = IsNull(ti.item_expean,'False')
									from tbItem ti							WITH (NOLOCK)
									where	ti.comp_id		= @comp_id	AND
											ti.item_code	= @serial	AND
											ti.item_expean  = 'True'
				END


			IF @intItem_Id IS NULL AND @bra_SaleOrderPreparation_EANSearchOption IN (0,3)
				BEGIN
					select	@intItem_Id = ti.item_id,
							@bitExpEAN  = IsNull(ti.item_expean,'False')
								from tbItem ti								WITH (NOLOCK)
								where	ti.comp_id				= @comp_id	AND
										ti.item_codeAlternative	= @serial	AND
										ti.item_expean			= 'True'

				END



			IF @intItem_Id IS NULL AND @bra_SaleOrderPreparation_EANSearchOption IN (0,2)
				BEGIN
					select	@intItem_Id = ti.item_id,
							@bitExpEAN  = IsNull(ti.item_expean,'False')
								from tbItem ti								WITH (NOLOCK)
								where	ti.comp_id			= @comp_id	AND
										ti.item_vendorCode	= @serial	AND
										ti.item_expean		= 'True'

				END

			IF @intItem_Id IS NULL AND @bra_SaleOrderPreparation_EANSearchOption IN (0,4)
				BEGIN
					select @intItem_Id	= ti.item_id,
							@bitExpEAN  = IsNull(ti.item_expean,'False')
								from tbItem ti								WITH (NOLOCK)
								LEFT JOIN tbItem_codeAlternative tica		WITH (NOLOCK)
									ON	tica.comp_id = ti.comp_id AND
										tica.item_id = ti.item_id
								where	ti.comp_id		= @comp_id														 AND
								       (tica.comp_id IS NOT NULL AND tica.item_codeAlternative LIKE '%' + @serial + '%') AND
										ti.item_expean		= 'True'
				END

--==
--SELECT @intItem_Id

			if @intItem_Id is not NULL

				BEGIN

					set	@return_value = 0
					set	@errormessage = ''

					IF @bitExpEAN = 'False'
						BEGIN
							SET @return_value = 9
						END
					ELSE
						BEGIN

							declare @intSODTId as int
							DECLARE @intSODId  as INT
							DECLARE @bitDUNExceedQTYPending AS BIT = 'False'
							select	@intSODTId = tsodT.sodt_id,
									@intSODId  = tsod.sod_id,
									@bitDUNExceedQTYPending =	CASE		-- MOS 07-2022: para que NO se pase de cantidad si es DUN
																	WHEN (ISNULL(tsodt.sodt_qty,0) + ISNULL(@intExpEANDUNQty,1)) > tsod.sod_qty THEN 'True'
																	ELSE 'False'
																END
									from tbSaleOrderDetail tsod					WITH (NOLOCK)
									LEFT join tbSaleOrderDetailTMP tsodT		WITH (NOLOCK)
										on	tsod.comp_id	= tsodT.comp_id
										and tsod.bra_id		= tsodT.bra_id
										and tsod.soh_id		= tsodT.soh_id
										and tsod.sod_id		= tsodT.sod_id
									where tsod.comp_id	= @comp_id		and
										  tsod.bra_id	= @bra_id		and
										  tsod.soh_id	= @soh_id		and
										  tsod.item_id	= @intItem_Id	and
										  IsNull(tsodT.sodt_qty,0) < tsod.sod_qty


							-- ------------------------------------------------------------------------------------------------------------
							-- MOS 01-2024 Si NO lo encuentra como principal, trata de ver si es COMPOSICION si es un Pedido de Produccion
							-- ------------------------------------------------------------------------------------------------------------
							DECLARE @bitIsProductionEAN AS BIT = 'False'
							IF	@sd_id		= 80	AND
								@intSODId IS NULL
								BEGIN

									select	--@intSODTId = tsodT.sodt_id,
											@intSODId  = tsod.sod_id,
											@bitDUNExceedQTYPending =	CASE		-- MOS 07-2022: para que NO se pase de cantidad si es DUN
																			WHEN (ISNULL(tsodt.sodt_qty,0) + ISNULL(@intExpEANDUNQty,1)) > tsod.sod_qty THEN 'True'
																			ELSE 'False'
																		END,
											@bitIsProductionEAN =	CASE
																		WHEN tic.item_id_1 = @intItem_Id THEN	'True'
																		ELSE									'False'
																	END
											from tbSaleOrderDetail tsod					WITH (NOLOCK)
											LEFT join tbSaleOrderDetailTMP tsodT		WITH (NOLOCK)
												on	tsod.comp_id	= tsodT.comp_id
												and tsod.bra_id		= tsodT.bra_id
												and tsod.soh_id		= tsodT.soh_id
												and tsod.sod_id		= tsodT.sod_id
											LEFT JOIN tbItemComposition		AS tic		WITH (NOLOCK)
												ON	tic.comp_id = tsodT.comp_id AND
													tic.item_id = tsodT.item_id
											where tsod.comp_id	= @comp_id		and
												  tsod.bra_id	= @bra_id		and
												  tsod.soh_id	= @soh_id		and
												  (
													  --tsod.item_id	= @intItem_Id
													  --OR
													  tic.item_id_1 = @intItem_Id
												  )
								END
							-- ------------------------------------------------------------------------------------------------------------


							-- ------------------------------------------------------------------------------------------------------------
							-- MOS 01-2024: Para que se pueda serializar x EAN en Pedidos de Produccion
							-- ------------------------------------------------------------------------------------------------------------
							IF	@sd_id				= 80		AND
								@bitIsProductionEAN = 'True'	AND
								@intSODTId IS NULL AND @intSODId IS NOT NULL
								BEGIN

									IF EXISTS (	SELECT TOP 1 1
													FROM tbSaleOrderDetailtmp
								           			WHERE	comp_id = @comp_id	AND
								           					bra_id	= @bra_id	AND
								           					soh_id	= @soh_id	AND
								           					sod_id	= @intSODId AND
								           					item_id = @intItem_Id)
										BEGIN
											update tbSaleOrderDetailtmp
												SET		sodt_qty	= sodt_qty +	CASE	-- MOS 05-2023 x Sec One 11128 - cliente 301, ticket 18983 (Adicional al 17824 ), 2 horas
																						WHEN @intExpEANDUNQty IS NOT NULL THEN  @intExpEANDUNQty * @qty
																						ELSE									@qty
																					END						--ISNULL(@intExpEANDUNQty,1) -- MOS 07-2022:  1    se puso que incremente de a qty de DUN o 1
											WHERE	comp_id = @comp_id	AND
								           			bra_id	= @bra_id	AND
								           			soh_id	= @soh_id	AND
								           			sod_id	= @intSODId AND
								           			item_id = @intItem_Id
										END
									ELSE
										BEGIN
											insert into tbSaleOrderDetailtmp
												(
													comp_id,
													bra_id,
													soh_id,
													sod_id,
													sodt_qty,
													item_id
												)
												VALUES
												(
													@comp_id,
													@bra_id,
													@soh_id,
													@intSODId,
													CASE	-- MOS 05-2023 x Sec One 11128 - cliente 301, ticket 18983 (Adicional al 17824 ), 2 horas
														WHEN @intExpEANDUNQty IS NOT NULL THEN  @intExpEANDUNQty * @qty
														ELSE									@qty
													END	,
													--CASE	-- MOS 07-2022 para que incremente de a DUN en caso de encontrarlo x ese metodo.
													--	WHEN ISNULL(@intExpEANDUNQty,1) > 1 THEN ISNULL(@intExpEANDUNQty,1)
													--	ELSE @qty
													--END,
													--@qty,  -- 1
													@intItem_Id

												)
										END


								END
							-- ------------------------------------------------------------------------------------------------------------

							-- MOS 01-2024: El Resto queda EXACTAMENTE tal como estaba, solo se agrego el ELSE adelante.
							ELSE if @intSODTId IS NOT NULL AND @bitDUNExceedQTYPending = 'False'

								BEGIN
										update tbSaleOrderDetailtmp
											SET		sodt_qty	= sodt_qty +	CASE	-- MOS 05-2023 x Sec One 11128 - cliente 301, ticket 18983 (Adicional al 17824 ), 2 horas
																					WHEN @intExpEANDUNQty IS NOT NULL THEN  @intExpEANDUNQty * @qty
																					ELSE									@qty
																				END						--ISNULL(@intExpEANDUNQty,1) -- MOS 07-2022:  1    se puso que incremente de a qty de DUN o 1
											where	sodt_id		= @intSODTId
								END


							else if @intSODId IS NOT NULL AND @bitDUNExceedQTYPending = 'False'

								BEGIN
										insert into tbSaleOrderDetailtmp
										(
											comp_id,
											bra_id,
											soh_id,
											sod_id,
											sodt_qty,
											item_id
										)
										VALUES
										(
											@comp_id,
											@bra_id,
											@soh_id,
											@intSODId,
											CASE	-- MOS 05-2023 x Sec One 11128 - cliente 301, ticket 18983 (Adicional al 17824 ), 2 horas
												WHEN @intExpEANDUNQty IS NOT NULL THEN  @intExpEANDUNQty * @qty
												ELSE									@qty
											END	,
											--CASE	-- MOS 07-2022 para que incremente de a DUN en caso de encontrarlo x ese metodo.
											--	WHEN ISNULL(@intExpEANDUNQty,1) > 1 THEN ISNULL(@intExpEANDUNQty,1)
											--	ELSE @qty
											--END,
											--@qty,  -- 1
											@intItem_Id

										)

								END

							else
								BEGIN
									--No hay pendientes de preparar para ese artículo en ítems NO Serializables.
									set @return_value = 7
								END

						END

				END


	END


	If	@return_value <> 0

				BEGIN
					-- aquí llega sólo por algún error de validación
					select	@errormessage	= ltrim(rtrim(optval_desc))
						from 	tbSysOptionsValues		WITH (NOLOCK)
						where	lang_id			= @lang_id
						and		optval_id		= @return_value
						and		optval_class	= 46
				END


	--select @return_value, @errormessage

END
GO







-- SOlo usado en SaleOrder.  Si se duplica un pedido debe sacarse atributos peligrosos del pedido original.
create  PROCEDURE [dbo].spSaleOrder_Update4wucDuplicate
(
	@comp_id					int,
	@bra_id						int,
	@soh_id						INT
)
AS


BEGIN

	set nocount on

	UPDATE tbSaleOrderdetail
		SET	 it_transaction = NULL

		where	comp_id			= @comp_id
		and		bra_id			= @bra_id
		and	    soh_id			= @soh_id

END
GO








----------------------------------------------------------------------------------------
-- Usado para poner cosas adicionales del pedido sin tocar la clase principal.
----------------------------------------------------------------------------------------
CREATE  PROCEDURE [dbo].[spSaleOrder_updateAdditionalData]
(
	@comp_id					int,
	@bra_id						int,
	@soh_id						int,
	@custf_id					INT,
	@cust_id_guarantor			INT,
	@ccp_id						INT,
	@deliveryAddress			VARCHAR(4000),
	@pro_id						INT,
	@html_Note					NTEXT,
	@prli_id					INT,
	@stor_id					INT,
	@dc_id						INT
)
AS


BEGIN

	set nocount on

	IF @dc_id				= -1    SET @dc_id				= NULL
	IF @pro_id				= -1	SET @pro_id				= NULL
	IF @custf_id			= -1	SET @custf_id			= NULL
	IF @cust_id_guarantor	= -1	SET @cust_id_guarantor	= NULL
	IF @ccp_id			   <= 0		SET @ccp_id				= NULL

	UPDATE tbSaleOrderHeader		WITH (ROWLOCK)
		SET custf_id			= @custf_id,
			cust_id_guarantor	= @cust_id_guarantor,
			ccp_id				= @ccp_id,
			soh_deliveryAddress = @deliveryAddress,
			pro_id				= @pro_id,
			soh_htmlNote		= @html_Note,
			prli_id				= @prli_id,
			stor_id				= @stor_id,
			dc_id				= @dc_id
		where	comp_id			= @comp_id
		and		bra_id			= @bra_id
		and	    soh_id			= @soh_id


	-- MOS 07-2022: si el documento lo requiere pone la fecha de entrega del pedido igual al maximo de las de entrega de las partes.
	IF EXISTS(
				SELECT TOP 1  1
					FROM tbSaleOrderHeader		AS tsoh		WITH (NOLOCK)
					INNER JOIN tbDocumentsFile	AS tdf		WITH (NOLOCK)
						ON	tdf.comp_id		= tsoh.comp_id AND
							tdf.df_id		= tsoh.df_id
					WHERE 	tsoh.comp_id	= @comp_id
					and		tsoh.bra_id		= @bra_id
					and	    tsoh.soh_id		= @soh_id	AND
							tdf.df_saleOrder_setDeliveryDate2MaxInItem = 'True'
			)
		BEGIN

			DECLARE @datDeliveryDate AS DATETIME = GETDATE()
			SELECT  @datDeliveryDate = MAX(tsod.sod_itemDeliveryDate)
				FROM tbSaleOrderDetail AS tsod	WITH (NOLOCK)
				WHERE	tsod.comp_id	= @comp_id	AND
						tsod.bra_id		= @bra_id	AND
						tsod.soh_id		= @soh_id
			SET @datDeliveryDate		= ISNULL(@datDeliveryDate,GETDATE())

			UPDATE tbSaleOrderHeader		WITH (ROWLOCK)
				SET  soh_deliveryDate   = CASE
											  WHEN soh_deliveryDate > @datDeliveryDate THEN soh_deliveryDate
											  ELSE											@datDeliveryDate
										  END
				WHERE 	comp_id			= @comp_id
				and		bra_id			= @bra_id
				and	    soh_id			= @soh_id
		END



END
GO








-- ----------------------------------------------------------------------------------------
-- ----------------------------------------------------------------------------------------
-- ATENCIÓN:-------------------------------------------------------------------------------
-- SI SE MODIFICAN LOS PARÄMETROS DE ESTE SP POR FAVOR VERIFICAR QUE TAMBIËN ES LLAMADO----
-- POR EL SP spSaleOrder_insertDataFromWeb-------------------------------------------------
-- ----------------------------------------------------------------------------------------
-- ----------------------------------------------------------------------------------------
CREATE  PROCEDURE [dbo].[spSaleOrder_updateCurrExchange]
(
	@comp_id					int,
	@bra_id						int,
	@soh_id						int,
	@curr_id4Exchange			INT,
	@curr_idExchange			DECIMAL(38,27),	-- MOS 03-2023 era 19,6
	@decInCash					DECIMAL(19,4)
)
AS


BEGIN

	set nocount on

	UPDATE tbSaleOrderHeader	WITH (ROWLOCK)
		SET	curr_id4Exchange = @curr_id4Exchange,
			curr_idExchange	 = @curr_idExchange,
			soh_inCash		 = @decInCash

		where	comp_id			= @comp_id
		and		bra_id			= @bra_id
		and	    soh_id			= @soh_id

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 006-2008
-- Update 10-2008
-- Description:	Update de la fecha y hora de
-- IsEditing
-- =============================================

CREATE PROCEDURE [dbo].[spSaleOrder_UpdateIsEditing]

	(
    @comp_id			as  int,
	@bra_id				as	int,
	@soh_id				as	int,
	@guid				as	Uniqueidentifier,
	@isEditing			As	Bit,
	@OnlyHeader			As  BIT,
	@ForceActualization AS  BIT
	)

AS
BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON;

	Declare @date as datetime
	Set		@Date = getdate()

    Update	dbo.tbSaleOrderHeader		WITH (ROWLOCK)
				Set soh_isEditing	= @isEditing,
					soh_isEditingCd = @Date
				Where  comp_id		= @comp_id
					and bra_id		= @bra_id
					and soh_id		= @soh_id
					AND (@ForceActualization='True' OR soh_isEditing = 'True')

	SELECT   @isEditing		=	ISNULL(tsoh.soh_isEditing,'True')
		FROM tbSaleOrderHeader tsoh			WITH (NOLOCK)
		Where  comp_id		=	@comp_id
		   and bra_id		=	@bra_id
		   and soh_id		=	@soh_id

	If @OnlyHeader = 'False'
		Begin
		  Update	dbo.tbSaleOrderDetail		WITH (ROWLOCK)
						Set sod_isEditing	= @isEditing
						Where  comp_id		= @comp_id
							and bra_id		= @bra_id
							and soh_id		= @soh_id


		  Update	dbo.tbTempItemStock			WITH (ROWLOCK)
						Set tis_isEditing	= @isEditing,
							tis_isEditingCd = @Date
						Where   --comp_id		= @comp_id
								tis_guid	= @guid

			IF @isEditing = 'False'  -- MOS: 10-2010
				BEGIN

					-- =============================================================
					-- 30-06-2011 - MOH - agregado para evitar cancelación cuando se
					-- elimina tbTempItemStock en la instrucción siguiente
					DELETE FROM tbtmpTax
					WHERE	comp_id		= @comp_id
					AND		tis_guid	= @guid
					-- =============================================================

					DELETE FROM tbTempItemStock
					WHERE	tis_guid	= @guid
						--AND comp_id		= @comp_id
				END

		END


		-- Actualiza los Turnos de Ensamblado que esten activos.!
		UPDATE tbAssembly_Turns4Assembly		WITH (ROWLOCK)
			SET ta_isEditingCD = GETDATE()
			FROM tbAssembly_Turns4Assembly tas	--WITH (NOLOCK)
			INNER JOIN tbTempItemStock ttis		WITH (NOLOCK)
				ON	ttis.comp_id	= tas.comp_id	AND
					ttis.tis_id		= tas.tis_id
			WHERE ttis.tis_guid = @guid

		-- Actualiza los Turnos de Armado de Pedidos que esten activos.!
		UPDATE tbSaleOrderAssemblyTurns		WITH (ROWLOCK)
			SET	soa_isEditingCD = GETDATE()
			FROM tbSaleOrderAssemblyTurns tas	--WITH (NOLOCK)
			--INNER JOIN tbTempItemStock ttis		WITH (NOLOCK)
			--	ON ttis.tis_id = tas.tis_id
			WHERE tas.soa_guid = @guid


END
GO

-- =============================================
-- Author:		STL
-- Create date: 04-2019
-- Update		04-2019
-- Description:	Update de la fecha y hora de
-- IsEditing
-- =============================================

CREATE PROCEDURE [dbo].[spSaleOrder_UpdateIsEditing4FullJaus]

	(
    @comp_id			as  int,
