	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON;

	Declare @date as datetime
	Set		@Date = getdate()

    Update	dbo.tbSaleOrderHeader		WITH (ROWLOCK)
				Set soh_isEditing	= @isEditing,
					soh_isEditingCd = @Date
				Where  comp_id		= @comp_id
					and bra_id		= @bra_id
					and soh_id		= @soh_id
