						Set sod_isEditing	= @isEditing
						Where  comp_id		= @comp_id
							and bra_id		= @bra_id
							and soh_id		= @soh_id


		  Update	dbo.tbTempItemStock			WITH (ROWLOCK)
						Set tis_isEditing	= @isEditing,
							tis_isEditingCd = @Date
						Where   --comp_id		= @comp_id
								tis_guid	= @guid

			IF @isEditing = 'False'  -- MOS: 10-2010
				BEGIN

					-- =============================================================
					-- 30-06-2011 - MOH - agregado para evitar cancelación cuando se
					-- elimina tbTempItemStock en la instrucción siguiente
					DELETE FROM tbtmpTax
					WHERE	comp_id		= @comp_id
					AND		tis_guid	= @guid
					-- =============================================================

					DELETE FROM tbTempItemStock
					WHERE	tis_guid	= @guid
						--AND comp_id		= @comp_id
				END

		END


		-- Actualiza los Turnos de Ensamblado que esten activos.!
		UPDATE tbAssembly_Turns4Assembly		WITH (ROWLOCK)
			SET ta_isEditingCD = GETDATE()
			FROM tbAssembly_Turns4Assembly tas	--WITH (NOLOCK)
			INNER JOIN tbTempItemStock ttis		WITH (NOLOCK)
				ON	ttis.comp_id	= tas.comp_id	AND
					ttis.tis_id		= tas.tis_id
			WHERE ttis.tis_guid = @guid

		-- Actualiza los Turnos de Armado de Pedidos que esten activos.!
		UPDATE tbSaleOrderAssemblyTurns		WITH (ROWLOCK)
			SET	soa_isEditingCD = GETDATE()
			FROM tbSaleOrderAssemblyTurns tas	--WITH (NOLOCK)
			--INNER JOIN tbTempItemStock ttis		WITH (NOLOCK)
			--	ON ttis.tis_id = tas.tis_id
			WHERE tas.soa_guid = @guid


END
GO

CREATE PROCEDURE [dbo].[spSaleOrder_UpdateIsEditing4Producteca]

	(
    @comp_id			as  int,
	@bra_id				as	int,
	@soh_id				as	int,
	@guid				as	Uniqueidentifier,
	@isEditing			As	Bit,
	@OnlyHeader			As  BIT,
	@ForceActualization AS  BIT
	)

AS
BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON;

	Declare @date as datetime
	Set		@Date = getdate()

    Update	dbo.tbSaleOrderHeader		WITH (ROWLOCK)
				Set soh_isEditing	= @isEditing,
					soh_isEditingCd = @Date
				Where  comp_id		= @comp_id
					and bra_id		= @bra_id
					and soh_id		= @soh_id
					AND (@ForceActualization='True' OR soh_isEditing = 'True')

	SELECT   @isEditing		=	ISNULL(tsoh.soh_isEditing,'True')
		FROM tbSaleOrderHeader tsoh			WITH (NOLOCK)
		Where  comp_id		=	@comp_id
		   and bra_id		=	@bra_id
		   and soh_id		=	@soh_id

	If @OnlyHeader = 'False'
		Begin
		  Update	dbo.tbSaleOrderDetail		WITH (ROWLOCK)
						Set sod_isEditing	= @isEditing
						Where  comp_id		= @comp_id
							and bra_id		= @bra_id
							and soh_id		= @soh_id


		  Update	dbo.tbTempItemStock			WITH (ROWLOCK)
						Set tis_isEditing	= @isEditing,
							tis_isEditingCd = @Date
						Where   --comp_id		= @comp_id
								tis_guid	= @guid

			IF @isEditing = 'False'  -- MOS: 10-2010
				BEGIN

					-- =============================================================
					-- 30-06-2011 - MOH - agregado para evitar cancelación cuando se
					-- elimina tbTempItemStock en la instrucción siguiente
					DELETE FROM tbtmpTax
					WHERE	comp_id		= @comp_id
					AND		tis_guid	= @guid
					-- =============================================================

					DELETE FROM tbTempItemStock
					WHERE	tis_guid	= @guid
						--AND comp_id		= @comp_id
				END

		END


		-- Actualiza los Turnos de Ensamblado que esten activos.!
		UPDATE tbAssembly_Turns4Assembly		WITH (ROWLOCK)
			SET ta_isEditingCD = GETDATE()
			FROM tbAssembly_Turns4Assembly tas	--WITH (NOLOCK)
			INNER JOIN tbTempItemStock ttis		WITH (NOLOCK)
				ON	ttis.comp_id	= tas.comp_id	AND
					ttis.tis_id		= tas.tis_id
			WHERE ttis.tis_guid = @guid

		-- Actualiza los Turnos de Armado de Pedidos que esten activos.!
		UPDATE tbSaleOrderAssemblyTurns		WITH (ROWLOCK)
			SET	soa_isEditingCD = GETDATE()
			FROM tbSaleOrderAssemblyTurns tas	--WITH (NOLOCK)
			--INNER JOIN tbTempItemStock ttis		WITH (NOLOCK)
			--	ON ttis.tis_id = tas.tis_id
			WHERE tas.soa_guid = @guid


END
GO







-- ====================================================================================
-- Author:		GA.
-- Create date: 04/28/2011.
-- Description:	Orden de Venta - Orden .
-- ====================================================================================


CREATE PROCEDURE [dbo].[spSaleOrder_UpdateOrder]

(
	@comp_id		int,
	@tis_id			int,
	@tis_guid		uniqueidentifier,
	@tis_order		decimal(19,3)

)

AS


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

--------------------------------------------------------------------------------
-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
--------------------------------------------------------------------------------

/*
	DECLARE

		@comp_id		int,
		@tis_id			int,
		@tis_guid		uniqueidentifier,
		@tis_order		decimal(19,3)


	SELECT

		@comp_id		=1,
		@tis_id			= 20,
		@tis_guid		= '6b114ea4-7de0-4654-a7cd-12c9e871bceb',
		@tis_order		= 12


*/


--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------


		UPDATE tbTempItemStock

		SET		tis_order = @tis_order

		WHERE	comp_id		= @comp_id
		and		tis_id		= @tis_id
		and		tis_guid    = @tis_guid



END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spSaleOrder_UserIDConfirm]
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbSalesOrderBranchByProfileUserConfirm ts  WITH (NOLOCK)
					WHERE	ts.comp_id	= @comp_id	AND
							ts.bra_id	= @bra_id	AND
							ts.prof_id	= @prof_id
			 )
		BEGIN
			SELECT 'True'
		END
	ELSE
		BEGIN
			SELECT 'False'
		END
END
GO





------------------------------------------------------------------
-- MOS
-- Controles Varios
------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spSaleOrder_Verification]
(
	@comp_id	INT,
	@tis_guid   UNIQUEIDENTIFIER,
	@lang_id    INT,
	@option     INT,			-- 1-Guardar como pedido  2- Emitir el Pedido
	@user_id	INT,
	@prof_id	INT,
	@bra_id		INT,
	@st_id		INT,
	@dl_id		INT,
	@disc_id	INT,
	@sm_id		INT,
	@forcedExchangeCurrency		INT,
    @forcedExchange				DECIMAL(19,5),
    @saleOrderTotal				DECIMAL(19,4),
    @bitIsProcessNow			BIT	,
    @decInCash					DECIMAL(25,2)
)
AS


BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	-- --------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------
/*
		DECLARE
			@comp_id	INT,
			@tis_guid   UNIQUEIDENTIFIER
		SELECT
			@comp_id	= 1,
			@tis_guid	= '2A4A96E8-F039-483B-8EE5-D32979CC718E'
*/
	-- --------------------------------------------------------



		-- --------------------------------------------------------
		-- Detecta si se presionó Guardar y Emitir ya que en este caso la cond de venta llega en NEGATIVO
		-- --------------------------------------------------------
		DECLARE @bitIsSaveAndEmittion AS BIT = 'False'
		IF @st_id < 0
			BEGIN
				SET @st_id					= @st_id * -1
				SET @bitIsSaveAndEmittion	= 'True'
			END
		-- --------------------------------------------------------


		DECLARE @strDescError NVARCHAR(4000)
		SET @strDescError = ''



		-- --------------------------------------------------------
		-- Detecta si esta bloqueada la emision de cptes electronicos
		-- --------------------------------------------------------
		IF @option = 2	AND @strDescError = ''
			BEGIN

				IF EXISTS (
							SELECT TOP 1 	1
								FROM tbTempItemStock					ttis	WITH (NOLOCK)
								INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
									ON	tdf.comp_id = ttis.comp_id		AND
										tdf.df_id	= ttis.df_id
								INNER JOIN tbCompany AS tc						WITH (NOLOCK)
									ON tc.comp_id = ttis.comp_id
								WHERE	ttis.comp_id											= @comp_id	AND
										ttis.tis_guid											= @tis_guid AND
										tdf.df_isElectronicInvoice								= 'True'	AND
										tc.comp_blockElectronicInvoice							= 'True'
						  )
				BEGIN


							--La EMISIÓN de Comprobantes Electrónicos ha sido BLOQUEADA desde el Archivo de Compañías, Solapa Emisión de Comprobantes
							SELECT @strDescError	= @strDescError + ' ' + tut.utexts_desc + '<br/> '
								FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
								WHERE	tut.lang_id		= @lang_id	AND
										tut.utexts_id	= 40436


				END

			END
		-- --------------------------------------------------------


		-- --------------------------------------------------------
		-- Detecta si esta relacionado a OC y NO es factura o remito
		-- --------------------------------------------------------
		IF @option IN (1,2)	AND @strDescError = ''
			BEGIN

				IF EXISTS (
							SELECT TOP 1 	1
								FROM tbTempItemStock									ttis		WITH (NOLOCK)
								INNER JOIN tbDocumentsFile								tdf			WITH (NOLOCK)
									ON	tdf.comp_id = ttis.comp_id		AND
										tdf.df_id	= ttis.df_id
								LEFT JOIN  tbSaleOrderHeader_PurchaseOrderRelation AS	tsohpor		WITH (NOLOCK)
									ON	tsohpor.comp_id	= ttis.comp_id AND
										tsohpor.tis_id	= ttis.tis_id
								WHERE	ttis.comp_id											= @comp_id	AND
										ttis.tis_guid											= @tis_guid AND
										tdf.sd_id NOT IN (1,2)												AND
										(
											tsohpor.comp_id IS NOT NULL
												OR
											ttis.tis_pending4pod_IdRelation = 'True'
										)
						  )
				BEGIN

							--ATENCIÓN: El comprobante MiPyme Seleccionado tiene un MODO Diferente al configurado en el Cliente.
							set @strDescError	= 'ATENCIÓN: Solo se puede Procesar o Guardar un pedido Relacionado o Pendiente a Relacionar a <br/>Órdenes de Compra si es del tipo FACTURA o REMITO. <br/> '

				END

			END
		-- --------------------------------------------------------









		-- --------------------------------------------------------
		-- Detecta si esta bloqueada la emision de cptes electronicos
		-- --------------------------------------------------------
		IF @option = 2	AND @strDescError = ''
			BEGIN

				IF EXISTS (
							SELECT TOP 1 	1
								FROM tbTempItemStock					ttis	WITH (NOLOCK)
								INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
									ON	tdf.comp_id = ttis.comp_id		AND
										tdf.df_id	= ttis.df_id
								INNER JOIN tbCustomer AS tc						WITH (NOLOCK)
									ON	tc.comp_id	= ttis.comp_id AND
										tc.cust_id	= ttis.cust_id
								WHERE	ttis.comp_id											= @comp_id	AND
										ttis.tis_guid											= @tis_guid AND
										tdf.df_isElectronicInvoice								= 'True'	AND
										(
											tc.cust_ElectronicInvoice_MiPyme_Mode IS NOT NULL AND
											tdf.df_ElectronicInvoice_MiPyme_Mode IS NOT NULL AND
											tc.cust_ElectronicInvoice_MiPyme_Mode <> tdf.df_ElectronicInvoice_MiPyme_Mode
										)
						  )
				BEGIN

							--ATENCIÓN: El comprobante MiPyme Seleccionado tiene un MODO Diferente al configurado en el Cliente.
							set @strDescError	= 'ATENCIÓN: El comprobante MiPyme Seleccionado tiene un MODO Diferente al configurado en el Cliente. <br/> '

				END

			END
		-- --------------------------------------------------------







		-- --------------------------------------------------------
		-- Bloquea EMISION de Monotributo en B
		-- --------------------------------------------------------
		IF @option = 2	AND @strDescError = ''
			BEGIN

				IF EXISTS (
							SELECT TOP 1 	1
								FROM tbTempItemStock					ttis	WITH (NOLOCK)
								INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
									ON	tdf.comp_id = ttis.comp_id		AND
										tdf.df_id	= ttis.df_id
								INNER JOIN tbCustomer AS tc						WITH (NOLOCK)
									ON	tc.comp_id	= ttis.comp_id AND
										tc.cust_id	= ttis.cust_id
								WHERE	ttis.comp_id											= @comp_id	AND
										ttis.tis_guid											= @tis_guid AND
										tdf.df_SaleOrder_DisableMonotributoInB					= 1			AND
										tc.fc_id												= 3
						  )
				BEGIN


							--ATENCIÓN: La EMISIÓN de Este Comprobante a un MONOTRUBUTISTA está BLOQUEADA en la solapa Pedidos del Documento.
							SELECT @strDescError	= @strDescError + ' ATENCIÓN: La EMISIÓN de Este Comprobante a un MONOTRUBUTISTA está BLOQUEADA en la solapa Pedidos del Documento.  '  + '<br/> '

				END

			END
		-- --------------------------------------------------------





		--ATENCIÓN: El pedido posee un artículo con atributo de bloqueo de emisión cuyo código es:
		IF @option = 2 AND @strDescError = ''
			BEGIN
				SELECT @strDescError = @strDescError + ' ' + tut.utexts_desc + ': ' + ti.item_code
					FROM tbTempItemStock	ttis		WITH (NOLOCK)
					INNER JOIN tbItem		ti			WITH (NOLOCK)
						ON	ti.comp_id		= ttis.comp_id	AND
							ti.item_id		= ttis.item_id
					INNER JOIN tbsysUniqueTexts tut		WITH (NOLOCK)
						ON	tut.lang_id		= @lang_id AND
							tut.utexts_id	= 686
					WHERE	ttis.comp_id	= @comp_id	AND
							ttis.tis_guid	= @tis_guid	AND
							ti.item_SOBlock = 'True'
			END




		--ATENCIÓN: El pedido tiene Artículos con Markup menor al Mínimo definido para:
		IF @option = 1	AND @strDescError = ''
			BEGIN


				SELECT @strDescError = @strDescError + ' ' + tut.utexts_desc + '<br/> ' + ti.item_code + ' -> ' + ttis.tis_itemDesc
					FROM tbTempItemStock	ttis							WITH (NOLOCK)
					INNER JOIN tbSaleOrderItemMinMarkupByProfStDiPrli mkm	WITH (NOLOCK)
						ON	mkm.comp_id		= @comp_id		AND
							mkm.prof_id		= @prof_id		AND
							mkm.prli_id		= ttis.prli_id	AND
							mkm.disc_id		= @disc_id		AND
							mkm.st_id		= ttis.st_id	AND
							mkm.item_id		= ttis.item_id
					INNER JOIN tbBranch tb									WITH (NOLOCK)
						ON	tb.comp_id	= @comp_id AND
							tb.bra_id	= @bra_id
					INNER JOIN tbItem		ti								WITH (NOLOCK)
						ON	ti.comp_id		= ttis.comp_id	AND
							ti.item_id		= ttis.item_id
					LEFT JOIN tbStorage ts									WITH (NOLOCK)
						ON		ts.comp_id = ttis.comp_id
							AND ts.stor_id = ttis.stor_id
					INNER JOIN tbsysUniqueTexts tut							WITH (NOLOCK)
						ON	tut.lang_id		= @lang_id AND
							tut.utexts_id	= 691
					LEFT JOIN tbCustomer tc									WITH (NOLOCK)
						ON		tc.comp_id = @comp_id
							AND tc.cust_id = ttis.cust_id
					LEFT JOIN vwItemCostList			ticl				WITH (NOLOCK)
						ON	ticl.comp_id	= ti.comp_id	AND
							ticl.item_id	= ti.item_id	AND
							ticl.coslis_id	= ISNULL(tc.coslis_id,isnull(ts.coslis_id, tb.coslis_id))
					WHERE	ttis.comp_id	= @comp_id	AND
							ttis.tis_guid	= @tis_guid	AND
							CONVERT(DECIMAL(19,4),
								CASE WHEN tb.bra_costlist_type = 'false'	THEN
									case
										when isnull(ticl.coslis_price,0) = 0 THEN 0
										ELSE	((ttis.tis_priceInBranchCurrencyWithDiscount /
												dbo.fnNoZDiv(	dbo.fnGetExchange2(ttis.comp_id,ticl.coslis_price,ticl.curr_id,tb.curr_id,@forcedExchangeCurrency, tb.curr_id, @forcedExchange,'false')	)
												) - 1) * 100
									 END
								ELSE
									case
										when isnull(ticl.coslis_price_aw,0) = 0 THEN 0
 										ELSE	 ((ttis.tis_priceInBranchCurrencyWithDiscount /
														dbo.fnNoZDiv(	dbo.fnGetExchange2(ttis.comp_id,ticl.coslis_price_aw,ticl.curr_id,tb.curr_id,@forcedExchangeCurrency, tb.curr_id, @forcedExchange,'false') )
													 ) - 1) * 100
									END
								END) < 	mkm.somm_minimumMarkup AND
							mkm.somm_isDisabled = 'False'




			END


		--

		IF @option = 2	AND @strDescError = ''
			BEGIN

				IF EXISTS (
							SELECT TOP 1 	1
								FROM tbTempItemStock					ttis	WITH (NOLOCK)
								INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
									ON	tdf.comp_id = ttis.comp_id		AND
										tdf.df_id	= ttis.df_id
								WHERE	ttis.comp_id											= @comp_id AND
										ttis.tis_guid											= @tis_guid AND
										tdf.df_SaleOrder_validateSalesTermsByProfileAtEmission	= 'True'
						  )
				BEGIN

				--buscar que el st_id que viene arriba esté adentro de salestermsbyprofile
				--si no está devuelvo el error
					IF NOT EXISTS (
									SELECT TOP 1 	1
										FROM tbSalesTerms4Profile tstp			WITH (NOLOCK)
										WHERE	tstp.comp_id	= @comp_id	AND
												tstp.st_id		= @st_id	AND
												tstp.prof_id	= @prof_id
								   )
						BEGIN
							--El perfil con el que intenta emitir el comprobante no posee asignada la Condición de Venta por perfil.
							SELECT @strDescError	= @strDescError + ' ' + tut.utexts_desc + '<br/> '
								FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
								WHERE	tut.lang_id		= @lang_id	AND
										tut.utexts_id	= 30915
						END


				END

			END







		-- --------------------------------------------------------------------------------------
		-- Si es de Mercadolibre verifica que este pago segun la condicion de venta
		-- Si es correcto que debe tener pago y esta pago la Condifion de venta DEBE SER
		-- de Cobranza Directa
		-- --------------------------------------------------------------------------------------
		IF @option = 2	AND @strDescError = ''
				BEGIN

					DECLARE			@intMLO_Id AS INT
					SELECT TOP 1	@intMLO_Id =	CASE
														WHEN	ttis.mlo_id IS NOT NULL THEN ttis.mlo_id
														WHEN	tsoh.mlo_id IS NOT NULL THEN tsoh.mlo_id
														ELSE								 NULL
													END
						FROM tbTempItemStock		ttis		WITH (NOLOCK)
						LEFT JOIN tbDocumentsFile	tdf			WITH (NOLOCK)	-- MOS 12-2023: Para que si es de ML pero cambiaron a ND o NC NO haga este control. (20494)
							ON	tdf.comp_id = ttis.comp_id		AND
								tdf.df_id	= ttis.df_id
						LEFT JOIN tbSaleOrderHeader tsoh		WITH (NOLOCK)
							ON	tsoh.comp_id	= ttis.comp_id	AND
								tsoh.bra_id		= ttis.bra_id	AND
								tsoh.soh_id		= ttis.soh_id
						WHERE	ttis.comp_id	= @comp_id		AND
								ttis.tis_guid	= @tis_guid		AND
								(
									ttis.mlo_id	IS NOT NULL	 OR
									tsoh.mlo_id IS NOT NULL
								)								AND
								(
									tdf.sd_id		NOT IN (3,4)
										OR
									tdf.comp_id IS NULL		-- x las dudas
								)												-- MOS 12-2023: Para que si es de ML pero cambiaron a ND o NC NO haga este control. (20494)
					-- SI es un pedido de MercadoLibre
					IF @intMLO_Id IS NOT NULL
						BEGIN

							-- ----------------------------------------------------------------------------
							-- Pongo en una Tabla Temporal TODAS las Ordenes que pertenecen a este pedido
							-- ----------------------------------------------------------------------------
							DECLARE		@MLShippingID BIGINT
							SELECT		@MLShippingID = WWW.MLshippingID
								FROM	tbMercadoLibre_ordersShipping WWW			WITH (NOLOCK)
								WHERE	comp_id = @comp_id AND
										mlo_id	= @intMLO_Id
							DECLARE		@tmpOrdersOfThisShippment TABLE(mlo_id INT PRIMARY KEY)
							INSERT INTO @tmpOrdersOfThisShippment(mlo_id)
								SELECT TMLOS.mlo_id
									FROM tbMercadoLibre_ordersShipping tmlos		WITH (NOLOCK)
									WHERE	tmlos.comp_id		= @comp_id  AND
											tmlos.MLshippingID	= @MLShippingID
							IF @@ROWCOUNT = 0
								BEGIN
									INSERT INTO @tmpOrdersOfThisShippment(mlo_id) VALUES (@intMLO_Id)
								END
							-- ----------------------------------------------------------------------------


							DECLARE		@cc_id			     AS INT
							DECLARE		@bolDirectCollection AS BIT
							DECLARE		@st_directCollectionSelectLastCTTransaction BIT = 'False'
							SET			@bolDirectCollection = 'False'
							DECLARE		@bitSt_ML_disableBlockIfNoPayed AS BIT
							SELECT		@bitSt_ML_disableBlockIfNoPayed = ISNULL(tst.st_ML_disableBlockIfNoPayed,'False'),
										@bolDirectCollection			= ISNULL(tst.st_directCollection,'False'),
										@cc_id							= tst.cc_id,
										@st_directCollectionSelectLastCTTransaction
																		= tst.st_directCollectionSelectLastCTTransaction
								FROM	tbSalesTerms tst	WITH (NOLOCK)
								WHERE	tst.comp_id = @comp_id AND
										tst.st_id	= @st_id


							-- MOS 08-2023: 19435
							IF @bitSt_ML_disableBlockIfNoPayed = 'False'
								BEGIN
									IF  EXISTS (	SELECT TOP 1 1											-- MOS 08-2022, SOne
														FROM tbControlProfiles AS tcp1	WITH (NOLOCK)
														WHERE	tcp1.comp_id = @comp_id AND
										               			tcp1.bra_id  = @bra_id  AND
										               			tcp1.prof_id = @prof_id AND
										               			tcp1.page_id = 20 AND
										               			tcp1.ctrl_id = 6501
												)
										BEGIN
											SET @bitSt_ML_disableBlockIfNoPayed = 'True'
										END
								END






							DECLARE @df_favorite4ML AS BIT	= 'False'
							DECLARE @df_mercadoLibreInvoiceMessage AS NVARCHAR(4000)
							SELECT	TOP 1
										@df_favorite4ML					= tdf.df_favorite4ML ,
										@df_mercadoLibreInvoiceMessage	= dbo.fnStrAllTrim( ISNULL(tdf.df_mercadoLibreInvoiceMessage,''))
										FROM tbTempItemStock					ttis	WITH (NOLOCK)
										INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
											ON	tdf.comp_id = ttis.comp_id		AND
												tdf.df_id	= ttis.df_id
										WHERE	ttis.comp_id											= @comp_id AND
												ttis.tis_guid											= @tis_guid


							IF @bitSt_ML_disableBlockIfNoPayed = 'False'
								BEGIN


									-- ---------------------------------------------------------
									-- Verifica si el pedido figura como PAGO segun MercadoLibre
									-- ---------------------------------------------------------
									DECLARE @mlo_isPaid AS BIT
									SET		@mlo_isPaid = NULL
									SELECT	@mlo_isPaid = ISNULL(tmloh.mlo_isPaid,'False')
										FROM tbMercadoLibre_ordersHeader tmloh		WITH (NOLOCK)
										INNER JOIN @tmpOrdersOfThisShippment	tmp
											ON tmp.mlo_id = tmloh.mlo_id
										WHERE	tmloh.comp_id		= @comp_id AND
												tmloh.mlo_isPaid	= 'False'
									IF  ISNULL(@mlo_isPaid,'True')  = 'False'
										BEGIN

											IF NOT EXISTS (	SELECT TOP 1 1											-- MOS 11-2022, ticket 17494
										               			FROM tbControlProfiles AS tcp1	WITH (NOLOCK)
										               			WHERE	tcp1.comp_id = @comp_id AND
										               					tcp1.bra_id  = @bra_id  AND
										               					tcp1.prof_id = @prof_id AND
										               					tcp1.page_id = 20 AND
										               					tcp1.ctrl_id = 6387
														)
												BEGIN
													SELECT @strDescError		= @strDescError + ' ' + tut.utexts_desc + '<br/> '
														FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
														WHERE	tut.lang_id		= @lang_id	AND
																tut.utexts_id	= 720
												END
										END




									-- ---------------------------------------------------------
									-- Si es FulFillment y NO esta entregado,
									-- NO permite facturar el pedido			  MOS 13-03-2019
									-- ---------------------------------------------------------
									DECLARE @fulfillmentPending AS BIT	= 'False'
									SELECT	@fulfillmentPending			= 'True'
										FROM tbMercadoLibre_ordersShipping		tmloh		WITH (NOLOCK)
										INNER JOIN @tmpOrdersOfThisShippment	tmp
											ON tmp.mlo_id = tmloh.mlo_id
										WHERE	tmloh.comp_id		= @comp_id	AND
												tmloh.MLfulfilled   = 'True'	AND
												(
													tmloh.MLstatus		<> 'delivered'
														AND
													tmloh.MLstatus		<> 'shipped'
												)
									IF  @fulfillmentPending  = 'True'
										BEGIN
											IF NOT EXISTS (	SELECT TOP 1 1											-- GS ticket 9674
										               			FROM tbControlProfiles AS tcp1	WITH (NOLOCK)
										               			WHERE	tcp1.comp_id = @comp_id AND
										               					tcp1.bra_id  = @bra_id  AND
										               					tcp1.prof_id = @prof_id AND
										               					tcp1.page_id = 20 AND
										               					tcp1.ctrl_id = 6014
														)
												BEGIN
													SELECT @strDescError		= @strDescError + ' ' + tut.utexts_desc + '<br/> '
														FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
														WHERE	tut.lang_id		= @lang_id	AND
																tut.utexts_id	= 732
												END
										END


									-- ---------------------------------------------------------
									-- Si la ORDEN esta CANCELADA NO permite EMITIR el PEDIDO
									-- ---------------------------------------------------------
									IF @strDescError = ''
										BEGIN
											DECLARE @mlo_isCancelled AS BIT
											SET		@mlo_isCancelled = 'False'
											SELECT	@mlo_isCancelled = 'True',--ISNULL(tmloh.mlo_isCancelled,'False'),  MOS 08-2020
													@strDescError	 = 'ID#:' + CONVERT(NVARCHAR(10),tmloh.mlo_id) +  'Order#:' + CONVERT(NVARCHAR(20),tmloh.MLorder_id)
												FROM tbMercadoLibre_ordersHeader tmloh		WITH (NOLOCK)
												INNER JOIN @tmpOrdersOfThisShippment	tmp
													ON tmp.mlo_id = tmloh.mlo_id
												WHERE	tmloh.comp_id			= @comp_id AND
														tmloh.mlo_status		= 'cancelled'
														--tmloh.mlo_isCancelled	= 'True'
											IF  @mlo_isCancelled = 'True'
												BEGIN
													SELECT @strDescError		= @strDescError + ' <br/> ' + tut.utexts_desc + '<br/> '
														FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
														WHERE	tut.lang_id		= @lang_id	AND
																tut.utexts_id	= 728
												END
										END

									-- ---------------------------------------------------------
									-- La condicion de venta asignada debe ser del tipo de Cobranza Directa ! ! !
									-- ---------------------------------------------------------
									IF @strDescError = ''
										BEGIN
											IF @bolDirectCollection = 'False'
												BEGIN
													SELECT @strDescError		= @strDescError + ' ' + tut.utexts_desc + '<br/> '
														FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
														WHERE	tut.lang_id		= @lang_id	AND
																tut.utexts_id	= 721
												END
										END


									-- ---------------------------------------------------------
									-- La condicion de venta asignada debe ser del tipo de Cobranza Directa ! ! !
									-- ---------------------------------------------------------
									IF @strDescError = ''
										BEGIN
											IF @df_favorite4ML = 'False'
												BEGIN
													SELECT @strDescError		= 'ATENCIÓN: El Documento Asignado NO está seleccionado como Favorito para MercadoLibre(r) en la solapa Favoritos del archivo de Documentos.'
												END
										END

									-- ---------------------------------------------------------
									-- Eliminado x MOS 06-2020
									-- ---------------------------------------------------------
									--IF @strDescError = ''
									--	BEGIN
									--		IF @df_mercadoLibreInvoiceMessage = '' OR 1 = 2
									--			BEGIN
									--				SELECT @strDescError		= 'ATENCIÓN: El Documento Asignado NO tiene definido un mensaje de Agradecimiento de compra en la solapa MerdadoLibre del archivo de Documentos'
									--			END
									--	END




									-- ---------------------------------------------------------
									-- La condicion de venta asignada debe ser del tipo de Cobranza Directa y seleccionar el ultimo comprobante emitido! ! !
									-- ---------------------------------------------------------
									IF @strDescError = ''
										BEGIN
											IF @st_directCollectionSelectLastCTTransaction = 'False'
												BEGIN
													SELECT @strDescError		= 'ATENCIÓN: La Condición de Venta DEBE tener seleccionada en la solapa COBRANZAS la Cobranza Directa con Facturación y Seleccionar el último Comprobante Emitido !'
												END
										END



									 -- La condicion de venta asignada debe tener una tarjeta de credito asignada (MERCADOPAGO) ! ! !
									 IF @strDescError = ''
										BEGIN
											IF @cc_id IS NULL
												BEGIN
													SELECT @strDescError		= @strDescError + ' ' + tut.utexts_desc + '<br/> '
														FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
														WHERE	tut.lang_id		= @lang_id	AND
																tut.utexts_id	= 722
												END
										END




									-- El IMPORTE TOTAL Cobrado por MP debe ser mayor o igual al total del Pedido
									-- ***654654**KJNKJN   Ver aca tambien este calculo !!!!
									DECLARE @decPrice AS DECIMAL(19,4)
									SET		@decPrice	= 0

									SELECT @decPrice	= SUM(ISNULL(tmlod.mlo_unit_price,0) * ISNULL(tmlod.mlo_quantity,0))
										FROM tbMercadoLibre_ordersDetail tmlod		WITH (NOLOCK)
										INNER JOIN @tmpOrdersOfThisShippment	tmp
											ON tmp.mlo_id = tmlod.mlo_id
										WHERE	tmlod.comp_id	= @comp_id --AND
												--tmlod.mlo_id	= @intMLO_Id

									DECLARE @MLcoupon_amount AS DECIMAL(19,4) = 0
									DECLARE @decPayments	 AS DECIMAL(19,4) = 0
									-- SELECT	@decPayments				= SUM(tmlop.MLtransaction_amount + ISNULL(tmlop.MLcoupon_amount,0))
									SELECT	@decPayments				= SUM(ISNULL(tmlop.MLtransaction_amount,0))	,	-- 28-06-2021 MOS agrego + ISNULL(tmlop.MLcoupon_amount,0))
											@MLcoupon_amount			= SUM(ISNULL(tmlop.MLcoupon_amount,0))			-- 28-06-2021 MOS agrego + ISNULL(tmlop.MLcoupon_amount,0))
										FROM tbMercadoLibre_ordersPayments		tmlop	WITH (NOLOCK)
										INNER JOIN @tmpOrdersOfThisShippment	tmp
											ON tmp.mlo_id = tmlop.mlo_id
										INNER JOIN tbMercadoLibre_ordersHeader AS tmloh	WITH (NOLOCK)
											ON	tmloh.comp_id			= tmlop.comp_id AND
												tmloh.mlo_id			= tmlop.mlo_id
										WHERE	tmlop.comp_id			= @comp_id				AND
												--tmlop.mlo_id			= @intMLO_Id			AND
												tmlop.MLoperation_type	= 'regular_payment'		AND
												tmlop.MLstatus			= 'approved'			AND
												tmlop.MLstatus_detail   = 'accredited'

									IF ISNULL(@MLcoupon_amount,0) <> 0	-- si tiene CUPONEs pongo el total pago informado x meli (Precio TOTAL SIN incluir el Cupon de Descuento)
										BEGIN
											SELECT	@decPayments		= 	ISNULL(tmloh.mlo_total_paid_amount,0)			-- 28-06-2021 MOS agrego + ISNULL(tmlop.MLcoupon_amount,0))
												FROM tbMercadoLibre_ordersPayments		tmlop	WITH (NOLOCK)
												INNER JOIN @tmpOrdersOfThisShippment	tmp
													ON tmp.mlo_id = tmlop.mlo_id
												INNER JOIN tbMercadoLibre_ordersHeader AS tmloh	WITH (NOLOCK)
													ON	tmloh.comp_id			= tmlop.comp_id AND
														tmloh.mlo_id			= tmlop.mlo_id
												INNER JOIN tbMercadoLibre_Stores AS		  tmls	WITH (NOLOCK)
													ON	tmls.comp_id			= tmloh.comp_id AND
														tmls.mls_id				= tmloh.mls_id
												WHERE	tmlop.comp_id			= @comp_id				AND
														tmls.mls_OrdersWithDiscountCouponIncludeInPrice = 'False'	AND -- MOS 03-2023 x ADMA **wqlkn142231lklnk
														--tmlop.mlo_id			= @intMLO_Id			AND
														tmlop.MLoperation_type	= 'regular_payment'		AND
														tmlop.MLstatus			= 'approved'			AND
														tmlop.MLstatus_detail   = 'accredited'
										END
									SET @decPayments = ISNULL(@decPayments,0) + 1




									DECLARE @decAdditionalPayments AS DECIMAL(19,4)
									SET		@decAdditionalPayments = 0

									SELECT @decAdditionalPayments		= SUM(tmlop.MLtransaction_amount)
										FROM tbMercadoLibre_ordersPayments		tmlop WITH (NOLOCK)
										INNER JOIN @tmpOrdersOfThisShippment	tmp
											ON tmp.mlo_id = tmlop.mlo_id
										WHERE	tmlop.comp_id			= @comp_id				AND
												--tmlop.mlo_id			= @intMLO_Id				AND
												tmlop.MLoperation_type	= 'payment_addition'	AND
												tmlop.MLstatus			= 'approved'
									-- ***654654**KJNKJN   Ver aca tambien este calculo !!!!


									DECLARE @decShipmentPayedByCustomer AS DECIMAL(19,4) = 0
									IF EXISTS(
										SELECT TOP 1  1
											FROM tbMercadoLibre_ordersDetail tmlod			WITH (NOLOCK)
											INNER JOIN @tmpOrdersOfThisShippment tmp
												ON tmp.mlo_id = tmlod.mlo_id
											INNER JOIN tbMercadoLibre_ItemsPublicados tmlip	WITH (NOLOCK)
												ON	tmlip.comp_id	= tmlod.comp_id		AND
													tmlip.mlp_id	= tmlod.mlp_id
											INNER JOIN tbMercadoLibre_Stores tmls			WITH (NOLOCK)
												ON	tmls.comp_id	= tmlip.comp_id AND
													tmls.mls_id		= tmlip.mls_id
											WHERE	tmlod.comp_id   = @comp_id      AND
													tmls.item_id4UserPayDelivery IS NOT NULL
											)
										BEGIN
											SELECT @decShipmentPayedByCustomer = tmlos.MLShippmentCost4Buyer
												FROM tbMercadoLibre_ordersShipping tmlos	WITH (NOLOCK)
												WHERE	tmlos.comp_id	= @comp_id AND
														tmlos.mlo_id	= @intMLO_Id
										END



									-- ATENCIÓN: La suma de los valores pagos mediante  MercadoPago©  no cubren el importe del pedido ($). <br/> Solicitar al Cliente que agregue mas dinero a su compra. <br/><br/> <STRONG>ATENCIÓN, Leer! : </STRONG>Puede ingresar importes Adicionales Pendientes a Registrar en Cobranzas en el campo: EN EFECTIVO lo cual solo hará que pase la validación de Importes Acreditados para esta Venta.
									IF @strDescError = ''
										BEGIN					    -- MOS 12/2017
											IF (	ISNULL(@decPayments/*@decPrice*/,0) +
													ISNULL(@decAdditionalPayments,0) +
													ISNULL(@decShipmentPayedByCustomer,0) +
													ISNULL(@decInCash,0)
											   ) < (@saleOrderTotal - 1)		-- 0.5
												BEGIN
													SELECT @strDescError		= @strDescError + ' ' + tut.utexts_desc
														FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
														WHERE	tut.lang_id		= @lang_id	AND
																tut.utexts_id	= 725
													SET @strDescError = @strDescError + '<br/>MercadoPago:' + CONVERT(NVARCHAR(100),
																																	(
																																		ISNULL(@decPayments,0) +
																																		ISNULL(@decAdditionalPayments,0) +
																																		ISNULL(@decShipmentPayedByCustomer,0)
																																	)
																													 )
												END
										END

								END
						END
				END
		-- ----------------------5----------------------------------------------------------------

--==
--IF @strDescError = '' set @strDescError = 'bbbb'
--==



		-- --------------------------------------------------------------------------------------
		-- Si es con un Boton de PAgo asociado solo permite emitir si el boton tiene todo
		-- debidamente configurado.
		-- --------------------------------------------------------------------------------------
		IF @option = 2	AND @strDescError = ''
			BEGIN

				DECLARE @intCompId			AS INT
				DECLARE @intCN_Id			AS INT
				DECLARE @intUserID			AS INT
				DECLARE @intDFId4Collection AS INT
				DECLARE @mls_ID				AS INT


				SELECT	@intCN_Id			= tcnbu.cn_id,
						@intUserID			= tcnbu.[user_id],
						@intDFId4Collection = tdf.df_id,
						@intCompId			= tst.comp_id,
						@mls_ID				= tmls.mls_id
					FROM tbSalesTerms					tst						WITH (NOLOCK)
					INNER JOIN tbCreditCard				tcc						WITH (NOLOCK)
					ON	tcc.comp_id = tst.comp_id					AND
						tcc.cc_id	= tst.cc_id
					LEFT JOIN tbMercadoLibre_Stores		tmls					WITH (NOLOCK)
						ON	tmls.comp_id		= tcc.comp_id		AND
							tmls.mls_id			= tcc.mls_id
					LEFT JOIN tbDocumentsFile			tdf						WITH (NOLOCK)
						ON	tdf.comp_id = tmls.comp_id				AND
							tdf.bra_id	= tmls.bra_id				AND
							tdf.df_id	= tmls.df_id4MPCollection	AND
							tdf.sd_id IN (6,13)
					LEFT JOIN tbCashNumber4Branch4User	tcnbu					WITH (NOLOCK)
						ON	tcnbu.comp_id		= tmls.comp_id		AND
							tcnbu.bra_id		= tmls.bra_id		AND
							tcnbu.[user_id]		= tmls.[user_id]
					WHERE	TST.comp_id			= @comp_id			AND
							TST.st_id			= @st_id			AND
							tcc.cc_MPType		= 2					AND  -- Si es con BOTON DE PAGO
							tcc.cc_MPIsEnabled  = 'True'


				-- Si no estan definidas estas cosas que luego causran error en la cobranza, sale error.
				IF @intCompId IS NOT NULL
					BEGIN

						IF @intCN_Id IS NULL AND @strDescError = ''
							BEGIN
								SET @strDescError = 'ATENCIÓN: Botón de Pago de MercadoPago, No existe una caja relacionada al usuario y sucursal definidos en la Tienda de MercadoLibre asociada a la Tarjeta de Crédito Seleccionada'
							END

						IF @intDFId4Collection IS NULL AND @strDescError = ''
							BEGIN
								SET @strDescError = 'ATENCIÓN: Botón de Pago de MercadoPago, No existe una Documento del tipo Cobranza en la Tienda de MercadoLibre asociada a la Tarjeta de Crédito Seleccionada'
							END

						IF @mls_ID IS NULL AND @strDescError = ''
							BEGIN
								SET @strDescError = 'ATENCIÓN: Botón de Pago de MercadoPago, No existe una Tienda de MercadoLibre asociada a la Tarjeta de Crédito Seleccionada'
							END

					END

			END





		-- --------------------------------------------------------------------------------------
		-- Si es una NC y tiene percepciones verifica que no tenga articulos provenientes de una
		-- fc que sean de un mes y año diferentes
		-- --------------------------------------------------------------------------------------
		IF @option IN (1,2)AND @strDescError = ''
			BEGIN



				DECLARE @bitHasItemsFromOtherTransaction	AS BIT
				SET		@bitHasItemsFromOtherTransaction	= 'False'
				DECLARE @datDateOfItems						AS DATE
				DECLARE @datProcessingDate					AS date
				SELECT	@bitHasItemsFromOtherTransaction	= 'True',
						@datDateOfItems						= CASE
						               						      WHEN @datDateOfItems IS NULL			THEN	tct.ct_taxDate
						               						      WHEN @datDateOfItems > tct.ct_taxDate THEN	tct.ct_taxDate
						               						      ELSE											@datDateOfItems
						               						  END,
						@datProcessingDate					= tb.bra_processingDate
					FROM tbTempItemStock					ttis		WITH (NOLOCK)
					INNER JOIN tbtmpTax						tmptax		WITH (NOLOCK)
						ON	tmptax.comp_id		= ttis.comp_id AND
							tmptax.tis_id		= ttis.tis_id
					INNER JOIN tbTaxName					ttn			WITH (NOLOCK)
						ON	ttn.comp_id			= tmptax.comp_id	AND
							ttn.tax_id			= tmptax.tax_id
					INNER JOIN vwsysTaxClassALL_Perceptions vtcap		WITH (NOLOCK)
						ON vtcap.tax_class		= ttn.tax_class
					INNER JOIN tbItemTransactions			tit			WITH (NOLOCK)
						ON	tit.comp_id			= ttis.comp_id			AND
							tit.it_transaction	= ttis.it_transaction
					INNER JOIN tbCommercialTransactions		tct			WITH (NOLOCK)
					ON	tct.comp_id				= tit.comp_id AND
						tct.ct_transaction		= tit.ct_transaction
					INNER JOIN tbdocumentsfile				tdf			WITH (NOLOCK)
						ON	tdf.comp_id			= ttis.comp_id			AND
							tdf.df_id			= ttis.df_id
					INNER JOIN tbBranch						tb			WITH (NOLOCK)
						ON	tb.comp_id			= tit.comp_id AND
							tb.bra_id			= tit.bra_id
					WHERE	ttis.tis_guid		= @tis_guid				AND
							tdf.sd_id			= 3						AND
							ttis.it_transaction IS NOT NULL


					IF	@bitHasItemsFromOtherTransaction = 'True'	AND
						(
							MONTH(@datDateOfItems) <> MONTH(@datProcessingDate)
							OR
							YEAR(@datDateOfItems)  <> YEAR(@datProcessingDate)
						)
						BEGIN

							IF NOT EXISTS(	SELECT TOP 1  1
							              		FROM tbControlProfiles tcp1		WITH (NOLOCK)
							              		WHERE	tcp1.comp_id	= @comp_id AND
							              				tcp1.bra_id		= @bra_id AND
							              				tcp1.prof_id	= @prof_id AND
							              				tcp1.page_id	= 20 AND
							              				tcp1.ctrl_id	= 5071
										)

								BEGIN

									SELECT @strDescError		= @strDescError + ' ' + tut.utexts_desc + '<br/> '
										FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
										WHERE	tut.lang_id		= @lang_id	AND
												tut.utexts_id	= 726

								END

						END


			END
		-- --------------------------------------------------------------------------------------



		-- --------------------------------------------------------------------------------------
		-- Si se debe dividir por cond de venta y algun item NO esta dividido pide que se GRABE
		-- asi se divide si o si
		-- --------------------------------------------------------------------------------------
		IF @option = 2 AND @strDescError = '' AND @bitIsProcessNow = 'False'
			BEGIN
				IF EXISTS(
							SELECT TOP 1  1
								FROM tbTempItemStock						ttis		WITH (NOLOCK)
								INNER JOIN tbSaleOrderDivisionConfiguration tsodc		WITH (NOLOCK)
									ON	tsodc.comp_id		= @comp_id	AND
										tsodc.st_id			= @st_id	AND
										tsodc.df_id_origin	= ttis.df_id
								WHERE	ttis.comp_id		= @comp_id		AND
										ttis.tis_guid		= @tis_guid		AND
										ttis.tis_isDivided	= 'False'
						)
					BEGIN

						SELECT @strDescError		= @strDescError + ' ' + tut.utexts_desc + '<br/> '
							FROM tbsysUniqueTexts				tut						WITH (NOLOCK)
							WHERE	tut.lang_id		= @lang_id	AND
									tut.utexts_id	= 727

					END
			END
		-- --------------------------------------------------------------------------------------


		-- --------------------------------------------------------------------------------------
		-- Atención: faltan autorizar estados del pedido actual, por lo tanto no podrá emitirse hasta que las mismas se cumplimenten
		-- --------------------------------------------------------------------------------------
		IF @option = 2 AND @strDescError = '' AND @bitIsProcessNow = 'False'
			BEGIN
				--DECLARE @lintSoh_ID	INT
				--SELECT	TOP 1
				--	@lintSoh_ID				= ttis.soh_id
				--	FROM tbTempItemStock				ttis			WITH (NOLOCK)
				--	WHERE	ttis.comp_id	= @comp_id	AND
				--			ttis.tis_guid	= @tis_guid


				IF EXISTS(
							SELECT  TOP 1  1
								FROM tbControlProfiles			tcp1	WITH (NOLOCK)
								WHERE	tcp1.comp_id	= @comp_id	AND
										tcp1.bra_id		= @bra_id	AND
										tcp1.prof_id	= @prof_id	AND
										tcp1.page_id	= 20		AND
										tcp1.ctrl_id	= 5131
						)
					BEGIN


						DECLARE @lintSoh_ID	INT
						SELECT	TOP 1
							@lintSoh_ID				= ttis.soh_id
							FROM tbTempItemStock				ttis			WITH (NOLOCK)
							WHERE	ttis.comp_id	= @comp_id	AND
									ttis.tis_guid	= @tis_guid

						IF EXISTS(
									SELECT  TOP 1  1
										FROM tbSaleOrderStatus					tsos	WITH (NOLOCK)
										INNER JOIN tbSaleOrderStatusConcept AS	tsosc	WITH (NOLOCK)
											ON	tsosc.comp_id	= tsos.comp_id AND
												tsosc.sosc_id	= tsos.sosc_id
										INNER JOIN tbSaleOrderHeader		AS  tsoh	WITH (NOLOCK)
											ON	tsoh.comp_id	= tsos.comp_id	AND
												tsoh.bra_id		= tsos.bra_id	AND
												tsoh.soh_id		= tsos.soh_id
										INNER JOIN tbDocumentsFile			AS	tdf		WITH (NOLOCK)
											ON  tdf.comp_id		= tsoh.comp_id  AND
												tdf.df_id		= tsoh.df_id
										WHERE	tsos.comp_id	= @comp_id		AND
												tsos.bra_id		= @bra_id		AND
												tsos.soh_id		= @lintSoh_ID	AND
												tsos.sos_ok		= 0				AND
												-- --------------------------------------------------------------------------------------------
												-- MOS 05-2021 x FIESA	ticket 10952
												-- Permite emitir si tiene un estado No Aprobado pero el pedido es una Factura Anticipada.
												-- --------------------------------------------------------------------------------------------
												(
													tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NULL
														OR
													(
														tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL
															AND
														tsosc.sosc_emmitionApproveIfPreInvoice = 0   -- si NO permite rmitir Fc Anticipada debe encontrarlo
													)
												)
												-- --------------------------------------------------------------------------------------------
									)
							BEGIN

								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 30970

							END

					END
			END
		-- --------------------------------------------------------------------------------------




		-- --------------------------------------------------------------------------------------
		-- Si es Credito Personal Verifica que la suma de las cuotas sea igual al total
		-- Paso en Authogar y se arreeglo solo que era mas el importe de cuotas
		-- durante media hora. Como ALGO seguro pasó o alguien tocó algo se pone
		-- esta verificación
		-- --------------------------------------------------------------------------------------
		IF @option = 2 AND @strDescError = ''
			BEGIN

				DECLARE @decLoanTotal AS DECIMAL(29,4)
				SELECT  @decLoanTotal = SUM(tsolt.ln_loanPayTotal)
					FROM tbSaleOrderLoanTMP tsolt	WITH (NOLOCK)
					WHERE tsolt.tis_guid = @tis_guid
				IF @decLoanTotal <> 0
					BEGIN
						IF ABS(ROUND( @decLoanTotal,0) - ROUND(@saleOrderTotal,0)) > 5
							BEGIN
								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 40294
							END
					END
			END
		-- --------------------------------------------------------------------------------------


		-- --------------------------------------------------------------------------------------
		-- Verifica si es Fc Electronica con CAEA que esté dentro de las fechas VALIDAS
		-- --------------------------------------------------------------------------------------
		IF @option = 2	AND @strDescError = ''
			BEGIN
				DECLARE
						@df_CAEA_isAvailable		BIT,
						@df_CAEA_fromDate			DATETIME,
						@df_CAEA_toDate				DATETIME ,
						@df_CAEA_CAEANumber			NVARCHAR(50),
						@bra_processingDate			DATETIME

				SELECT	TOP 1
						@df_CAEA_isAvailable	= ISNULL(tdf.df_CAEA_isAvailable,'False'),
						@df_CAEA_fromDate		= dbo.fnGetEnd_or_BeginOfDate(ISNULL(tdf.df_CAEA_fromDate	,GETDATE()),'False'),
						@df_CAEA_toDate			= dbo.fnGetEnd_or_BeginOfDate(ISNULL(tdf.df_CAEA_toDate		,GETDATE()),'True'),
						@df_CAEA_CAEANumber		= ISNULL(tdf.df_CAEA_CAEANumber,''),
						@bra_processingDate		= tb.bra_processingDate
					FROM tbTempItemStock					ttis	WITH (NOLOCK)
					INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
						ON	tdf.comp_id = ttis.comp_id		AND
							tdf.df_id	= ttis.df_id
					INNER JOIN tbBranch						tb		WITH (NOLOCK)
						ON	tb.comp_id	= tdf.comp_id AND
							tb.bra_id	= tdf.bra_id
					WHERE	ttis.comp_id											= @comp_id	AND
							ttis.tis_guid											= @tis_guid

				IF @df_CAEA_isAvailable = 'True'
					BEGIN
						IF (NOT @bra_processingDate BETWEEN @df_CAEA_fromDate AND @df_CAEA_toDate) OR
								dbo.fnStrAllTrim(@df_CAEA_CAEANumber) = ''
							BEGIN
								-- ATENCIÓN: los Parámetros de Factura Electrónica por CAEA en el Archivo de Documentos no pueden ser validados, se requiere verificación de los mismos.
								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 731
							END
					END
			END
		-- --------------------------------------------------------------------------------------


		-- --------------------------------------------------------------------------------------
		--  Si es una Factura de Remitos Pendientes NO puede guardar como pedido ! ! !
		-- **lfwehwh0293784aksjdnhkqwdn
		-- --------------------------------------------------------------------------------------
		IF @option = 1 AND @strDescError = ''
			BEGIN

				IF EXISTS(	SELECT TOP 1 1
								FROM tbTempItemStock					ttis	WITH (NOLOCK)
								INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
									ON	tdf.comp_id		= ttis.comp_id		AND
										tdf.df_id		= ttis.df_id
								WHERE	ttis.comp_id	= @comp_id	AND
										ttis.tis_guid	= @tis_guid	AND
										ttis.it_transaction	IS NOT NULL		AND
										tdf.sd_id		= 1
						)
							BEGIN
								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 40351
							END
			END
		-- --------------------------------------------------------------------------------------



		-- --------------------------------------------------------------------------------------
		-- Si es un REMITO de Fc Adelantada y la Fc Adelantada Ya tiene una NC con el
		-- IT_transaction de la Fc Adelantada
		-- NO permite emitirla.  4-11-2019
		-- --------------------------------------------------------------------------------------
		IF @option = 2 AND @strDescError = ''
			BEGIN

				IF EXISTS(	SELECT TOP 1 1
								FROM tbTempItemStock					ttis	WITH (NOLOCK)
								INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)	-- Busco MI documento a Amitir, solo si es Remoto de Fc Adelantada
									ON	tdf.comp_id			= ttis.comp_id		AND
										tdf.df_id			= ttis.df_id
								INNER JOIN tbItemTransactions			tit		WITH (NOLOCK)	-- Mov de Stock de la Fc Adelantada
									ON	tit.comp_id			= ttis.comp_id		AND
										tit.bra_id			= ttis.bra_id		AND
										tit.it_soh_id		= ttis.soh_id		AND
										tit.it_sod_id		= ttis.sod_id
								INNER JOIN tbCommercialTransactions		tct		WITH (NOLOCK)	-- Fc Adelantada
									ON	tct.comp_id			= tit.comp_id AND
										tct.ct_transaction	= tit.ct_transaction
								INNER JOIN tbDocumentsFile				tdf2	WITH (NOLOCK)	-- Documento de la Fc Adelantada
									ON	tdf2.comp_id		= tct.comp_id AND
										tdf2.df_id			= tct.df_id
								INNER JOIN tbItemTransactions			titNC	WITH (NOLOCK)
									ON	titNC.comp_id					= tit.comp_id AND
										titNC.it_transaction_original	= tit.it_transaction
								INNER JOIN tbCommercialTransactions		tctNC	WITH (NOLOCK)
									ON	tctNC.comp_id					= titNC.comp_id AND
										tctNC.ct_transaction			= titNC.ct_transaction
								WHERE	ttis.comp_id								= @comp_id	AND
										ttis.tis_guid								= @tis_guid	AND
										tdf.sd_id									= 2			AND	-- Si el ACTUAl es un REMITO
										tdf.df_SaleOrder_IsInvoiceFirstPacking		= 'True'	AND -- de Factura ANTICIPADA
										tdf2.sd_id									= 1			AND -- el documento original es FACTURA
										tdf2.df_SaleOrder_InvoiceFirstPacking_df_id = tdf.df_id	AND	-- esa FActura es del remito ACTUAL de factura anticipada.
										tctNC.sd_id									= 3
							)
							BEGIN
								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 40353
							END
			END
		-- --------------------------------------------------------------------------------------



		-- --------------------------------------------------------------------------------------
		-- Si EMITO y el campo  esta en True, verifico que los depositos de tempitemstock
		-- esten en Mis Depositos
		-- --------------------------------------------------------------------------------------
		IF @option = 2 AND @strDescError = ''
			BEGIN

				IF EXISTS(	SELECT TOP 1 1
								FROM tbTempItemStock						ttis	WITH (NOLOCK)
								INNER JOIN tbDocumentsFile					tdf		WITH (NOLOCK)	-- Busco MI documento a Amitir, solo si es Remoto de Fc Adelantada
									ON	tdf.comp_id			= ttis.comp_id	AND
										tdf.df_id			= ttis.df_id
								LEFT JOIN tbStorage_TransferConfiguration4Send 	tstc	WITH (NOLOCK)
									ON	tstc.comp_id		= ttis.comp_id	AND
										tstc.bra_id			= @bra_id		AND
										tstc.[user_id]		= @user_id		AND
										tstc.prof_id		= @prof_id		AND
										tstc.stor_id		= ttis.stor_id
								WHERE	ttis.comp_id											= @comp_id	AND
										ttis.tis_guid											= @tis_guid	AND
										ttis.item_id IS NOT NULL											AND
										tdf.df_SaleOrder_showButton_DeleteItemNoBranchStorage	= 'True'	AND
										tstc.comp_id IS NULL
							)
							BEGIN
								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 40388
							END
			END
		-- --------------------------------------------------------------------------------------




		-- --------------------------------------------------------------------------------------
		-- Si se hacen x ejemplo Notas de Credito de Facturas, verifica que la condicion
		-- de MiPyme sea la misma en los dos documentos
		-- ATENCIÓN: Se está intentando emitir un Documento a partir de otro con configuraciones de Factura Electrónica MiPyme Diferentes. <br/> Seleccionar items emitidos con el documento correspondiente o seleccionar otro documento en función a los items seleccionados.
		-- --------------------------------------------------------------------------------------
		IF @option = 2 AND @strDescError = ''
			BEGIN

				IF EXISTS(	SELECT TOP 1 1
								FROM tbTempItemStock						ttis	WITH (NOLOCK)
								INNER JOIN tbDocumentsFile					tdf		WITH (NOLOCK)	-- Busco MI documento a Amitir, solo si es Remoto de Fc Adelantada
									ON	tdf.comp_id			= ttis.comp_id	AND
										tdf.df_id			= ttis.df_id
								INNER JOIN tbItemTransactions			 AS tit2	WITH (NOLOCK)
									ON	tit2.comp_id		= ttis.comp_id	AND
										tit2.it_transaction	= ttis.it_transaction
								INNER JOIN tbCommercialTransactions		 AS tct2	WITH (NOLOCK)
									ON	tct2.comp_id		= tit2.comp_id		AND
										tct2.ct_transaction = tit2.ct_transaction
								INNER JOIN tbDocumentsFile				 AS tdf2	WITH (NOLOCK)
									ON	tdf2.comp_id		= tct2.comp_id	AND
										tdf2.df_id			= tct2.df_id
								WHERE	ttis.comp_id											= @comp_id	AND
										ttis.tis_guid											= @tis_guid	AND
										ISNULL(tdf.df_electronicInvoiceFCCredito_Enabled,'False')
											<>
										ISNULL(tdf2.df_electronicInvoiceFCCredito_Enabled,'False') 	AND
										(
											(tdf.sd_id = 3 AND tdf2.sd_id = 1)	-- Si se hace una NC de una Fc
												OR
											(tdf.sd_id = 4 AND tdf2.sd_id = 3)	-- Si se hace una ND de una NC
										)
						)
							BEGIN
								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 40389
							END
			END
		-- --------------------------------------------------------------------------------------


		-- --------------------------------------------------------------------------------------
		-- Verificar que el Cliente NO sea para Carga Inicial de Valores
		-- --------------------------------------------------------------------------------------
		IF @option = 2 AND @strDescError = ''
			BEGIN

				IF EXISTS(	SELECT TOP 1 1
								FROM tbTempItemStock						ttis	WITH (NOLOCK)
								INNER JOIN tbCustomer tc							WITH (NOLOCK)
									ON		tc.comp_id = @comp_id
										AND tc.cust_id = ttis.cust_id
								WHERE	ttis.comp_id	= @comp_id	AND
										ttis.tis_guid	= @tis_guid	AND
										tc.cust_4InitialValues = 1
						)
							BEGIN
								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 40417
							END
			END
		-- --------------------------------------------------------------------------------------


		-- --------------------------------------------------------------------------------------
		-- Verifico si es un Rm de Fc Anticipada que se quiere generar DIRECTAMENTE   6290-dinSaleOrder_PreInvoice_PL_CanEmitWithNewItems
		-- --------------------------------------------------------------------------------------
		IF   @strDescError = ''
			BEGIN
				DECLARE @2sd_id									AS INT = -1
				DECLARE @2df_SaleOrder_IsInvoiceFirstPacking	AS BIT = 'False'
				DECLARE @2soh_id								AS INT = -1
				SELECT TOP 1 	@2sd_id									= tdf.sd_id,
								@2df_SaleOrder_IsInvoiceFirstPacking	= ISNULL(tdf.df_SaleOrder_IsInvoiceFirstPacking,'False'),
								@2soh_id								= ISNULL(ttis.soh_id,-1)
					FROM tbTempItemStock					ttis	WITH (NOLOCK)
					INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
						ON	tdf.comp_id = ttis.comp_id		AND
							tdf.df_id	= ttis.df_id
					WHERE	ttis.comp_id											= @comp_id	AND
							ttis.tis_guid											= @tis_guid
				IF @2sd_id = 2 AND @2df_SaleOrder_IsInvoiceFirstPacking = 'True' AND @2soh_id = -1
					BEGIN

						IF NOT EXISTS (	SELECT TOP 1 1											-- GS ticket 9674
										    FROM tbControlProfiles AS tcp1	WITH (NOLOCK)
										    WHERE	tcp1.comp_id = @comp_id AND
										            tcp1.bra_id  = @bra_id  AND
										            tcp1.prof_id = @prof_id AND
										            tcp1.page_id = 20 AND
										            tcp1.ctrl_id = 6290
									)
							BEGIN
								-- ATENCIÓN: Se está intentando Emitir o Guardar como Pedido un Remito de Factura Anticipada Generado de manera DIRECTA, lo cual NO se permite ya que se debe generar por la EMISIÓN de una Factura Anticipada.
								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 40441
							END
					END
			END
		-- --------------------------------------------------------------------------------------




		-- --------------------------------------------------------------------------------------
		-- Verificar si tiene valores precargados SIN los datos de tarjeta requeridos.
		-- --------------------------------------------------------------------------------------
		IF   @strDescError = ''
			BEGIN

				IF EXISTS (
							SELECT TOP 1 	1
								FROM tbSalesTerms AS tst		WITH (NOLOCK)
								WHERE	tst.comp_id											= @comp_id  AND
										tst.st_id											= @st_id	AND
										tst.st_collectionDiscountsAvailable					= 'True'
							)
					BEGIN


						DECLARE @sd_id								AS INT = -1
						DECLARE @df_SaleOrder_IsInvoiceFirstPacking AS BIT = 'False'
						SELECT TOP 1 	@sd_id								= tdf.sd_id,
										@df_SaleOrder_IsInvoiceFirstPacking = ISNULL(tdf.df_SaleOrder_IsInvoiceFirstPacking,'False')
							FROM tbTempItemStock					ttis	WITH (NOLOCK)
							INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
								ON	tdf.comp_id = ttis.comp_id		AND
									tdf.df_id	= ttis.df_id
							WHERE	ttis.comp_id											= @comp_id	AND
									ttis.tis_guid											= @tis_guid



						IF	-- --------
							(
								(
									(
										@option = 2   -- veriuficar 1ro q la cond vta sea de planes y (si le faltan datos o si NO tiene nada cargado en plan, dar el error )
											OR
										(
											@option = 1
												AND
											@bitIsSaveAndEmittion = 'True'
										)
									)

										AND

									EXISTS(	SELECT TOP 1 1				-- Verifica si EXISTE la necesidad de verificar los
				          						FROM tbSaleOrderCreditCardsTMP	AS tsocct	WITH (NOLOCK)
				          						INNER JOIN tbSalesTerms			AS tst		WITH (NOLOCK)
				          							ON	tst.comp_id = @comp_id AND
				          								tst.st_id	= @st_id
				          						WHERE	tst.st_discountPlanCheckPaymentData = 'True'		AND
				          								tsocct.tis_guid						= @tis_guid		AND
				          								tsocct.sohp_position				IN (1,2,3,4,5)	AND
				          								(
				          									tsocct.cmm_lote = ''
				          										OR
				          									tsocct.ccm_cardNumber = ''
				          										--OR
				          									--tsocct.ccm_customerName = ''
				          								)
										)
								)
							-- --------
										OR
							-- --------
								NOT EXISTS(	SELECT TOP 1 1
				          							FROM tbSaleOrderCreditCardsTMP	AS tsocct	WITH (NOLOCK)
				          							WHERE	tsocct.tis_guid					= @tis_guid
										  )
							)
								AND
							(@sd_id <> 2 OR (@sd_id = 2 AND @df_SaleOrder_IsInvoiceFirstPacking = 'False'))		-- MOS 10-2021 para que NO noleste con Rm de Fc anticipada que se Dividieron en Preparación de pedidos
							-- --------
							BEGIN
								-- ATENCIÓN: Se está intentando emitir un Documento con un Plan de Pagos / Descuentos asociado al cual le faltan ingresar datos de las tarjetas de crédito definidas o se intenta Guardar o Emitir un pedido sin un Plan de Pagos / Descuentos Ingresado.
								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 40429
							END
					END


			END
		-- --------------------------------------------------------------------------------------




		-- --------------------------------------------------------------------------------------
		-- Verificar que NO sea un documento del tipo REMITO
		-- --------------------------------------------------------------------------------------
		IF @option = 2 AND @strDescError = ''
			BEGIN

				IF EXISTS(	-- Si es un REMITO
							SELECT TOP 1 1
								FROM tbTempItemStock					ttis		WITH (NOLOCK)
								INNER JOIN tbdocumentsfile				tdf			WITH (NOLOCK)
									ON	tdf.comp_id			= ttis.comp_id			AND
										tdf.df_id			= ttis.df_id
								WHERE	ttis.tis_guid		= @tis_guid				AND
										tdf.sd_id			= 2
						)
					BEGIN	-- y TIENE para abajo la verificacion de NO poder emitirlos..
						IF  EXISTS (	SELECT TOP 1 1											-- GS ticket 9674
											FROM tbControlProfiles AS tcp1	WITH (NOLOCK)
											WHERE	tcp1.comp_id = @comp_id AND
													tcp1.bra_id  = @bra_id  AND
													tcp1.prof_id = @prof_id AND
													tcp1.page_id = 20 AND
													tcp1.ctrl_id = 6156
									)
							BEGIN
								SELECT @strDescError		= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 40439
							END
					END
			END
		-- --------------------------------------------------------------------------------------




		-- --------------------------------------------------------------------------------------
		-- Atención: Verificar al EMITIR que TENGA stock DIOSPONIBLE de todos los items
		-- --------------------------------------------------------------------------------------
		IF /*@option = 2 AND*/ @strDescError = '' --AND @bitIsProcessNow = 'False'
			BEGIN

				--IF EXISTS(
				--			SELECT  TOP 1  1
				--				FROM tbControlProfiles			tcp1	WITH (NOLOCK)
				--				WHERE	tcp1.comp_id	= @comp_id	AND
				--						tcp1.bra_id		= @bra_id	AND
				--						tcp1.prof_id	= @prof_id	AND
				--						tcp1.page_id	= 20		AND
				--						tcp1.ctrl_id	= 5131
				--		)
					BEGIN
						IF EXISTS(
									SELECT TOP 1 1
										FROM tbTempItemStock AS					ttis	WITH (NOLOCK)
										INNER JOIN tbItem	 AS ti						WITH (NOLOCK)
											ON	ti.comp_id		= ttis.comp_id AND
												ti.item_id		= ttis.item_id
										INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
											ON	tdf.comp_id		= ttis.comp_id				AND
												tdf.df_id		= ttis.df_id
										WHERE	ttis.comp_id	= @comp_id					AND
												ttis.tis_guid	= @tis_guid					AND
												ti.item_NoStockCheck							= 'False'	AND
												ti.item_SaleOrderSaveAndEmmition_BlockStockChk	= 'False'	AND

												(
													( @option = 1 AND tdf.df_SaleOrderSave_ChkAStk		= 'True'	)
														OR
													( @option = 2 AND tdf.df_SaleOrderEmittion_ChkAStk	= 'True'	)
												)											AND
												ttis.item_id IS NOT NULL					AND
												ttis.tis_StockStatus < 0
								 )
							BEGIN

								SELECT
									@strDescError			= @strDescError + ' ' + tut.utexts_desc + '<br/> '
									FROM tbsysUniqueTexts				tut			WITH (NOLOCK)
									WHERE	tut.lang_id		= @lang_id	AND
											tut.utexts_id	= 31000

							END

					END
			END
		-- --------------------------------------------------------------------------------------









		IF @strDescError <> ''
			BEGIN
				SELECT
					0											[Status],
					@strDescError								[message]
			END
		ELSE
			BEGIN
				SELECT
					1											[Status],
					@strDescError								[message]
			END








END

GO




create PROCEDURE [dbo].[spSaleOrderAssemblyPreparation_UpdateData]
(

	@comp_id					INT,
	@soa_turndate				DATETIME,
	@bra_id						INT,
	@tis_id						INT,
	@soa_guid					UNIQUEIDENTIFIER,
	@soh_bra_id					INT,
	@soh_id						INT,
	@sod_id						INT,
	@soa_is4AllItems			BIT,
	@user_id4Creation			INT,
	@user_id4lastUpdate			INT,
	@soa_isAssembled			BIT,
	@soa_isAssembledCD			DATETIME,
	@user_id4Assembly			INT,
	@ct_transaction				INT,
	@it_transaction				INT,
	@soa_isInAssembly			BIT,
	@soa_isInAssemblyCD			DATETIME,
	@qtyTurn					INT,
	@soa_id						INT,
	@isautomatic				BIT



)
AS

BEGIN

	SET NOCOUNT ON
    set DATEFORMAT 'ymd'

   	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
/*
	declare	@comp_id					INT,
			@soa_turndate				DATETIME,
			@bra_id						INT,
			@tis_id						INT,
			@soa_guid					UNIQUEIDENTIFIER,
			@soh_bra_id					INT,
			@soh_id						INT,
			@sod_id						INT,
			@soa_is4AllItems			BIT,
			@user_id4Creation			INT,
			@user_id4lastUpdate			INT,
			@soa_isAssembled			BIT,
			@soa_isAssembledCD			DATETIME,
			@user_id4Assembly			INT,
			@ct_transaction				INT,
			@it_transaction				INT,
			@soa_isInAssembly			BIT,
			@soa_isInAssemblyCD			DATETIME,
			@qtyTurn					INT,
			@soa_id						INT,
			@isautomatic				BIT




	select	@comp_id					=1,
			@soa_turndate				='2016-10-11 11:30:00',
			@bra_id						=234,
			@tis_id						=-1,
			@soa_guid					='7ba1e7a4-e014-4169-a3af-11024cbebe41',
			@soh_bra_id					=-1,
			@soh_id						=-1,
			@sod_id						=NULL,
			@soa_is4AllItems			='True',
			@user_id4Creation			=119,
			@user_id4lastUpdate			=119,
			@soa_isAssembled			='false',
			@soa_isAssembledCD			='2015-06-08',
			@user_id4Assembly			=1,
			@ct_transaction				=0,
			@it_transaction				=0,
			@soa_isInAssembly			='false',
			@soa_isInAssemblyCD			='2015-06-08',
			@qtyTurn					=4,
			@soa_id						=3354,
			@isautomatic				= 'False'


	drop table #tmpSaleOrderAssemblyTurns
	drop table #tmpSaleOrderAssemblyTurnsAutomatic
*/
	-- ------------------------------------------------------
	-- ------------------------------------------------------

	DECLARE @lintcountqty AS INT

	SET @lintcountqty = @qtyTurn


		IF @isautomatic = 'False'

			BEGIN
				--Asginar turnos mediante la fecha seleccionada

					IF @soa_is4AllItems	= 'True'

						BEGIN

							-- No es para todos los articulos ,@soa_is4AllItems	= 'false'

							--------------------------------------------------------------------------------------------------------
							-- guardamos en una temporal los datos ya filtrados por la fecha
							--------------------------------------------------------------------------------------------------------

							SELECT  TOP (@qtyTurn) *

							INTO #tmpSaleOrderAssemblyTurns

							FROM tbSaleOrderAssemblyTurns								tso		WITH (NOLOCK)

							WHERE (tso.comp_id			= @comp_id)		AND
								  (tso.bra_id			= @bra_id)		AND
								 -- (tso.soa_turnDate		>= @soa_turndate	AND tso.soa_turnDate <= dbo.fnGetEnd_or_BeginOfDate(@soa_turndate,'true')) AND
								  (tso.soa_turnDate >=  @soa_turndate /*AND tso.soa_turnDate <= dbo.fnGetEnd_or_BeginOfDate(@soa_turndate,'true')*/) AND --ESTO SOLO
								  (tso.soa_guid			IS NULL )

							ORDER BY tso.soa_turnDate,
									 tso.soa_id

							--------------------------------------------------------------------------------------------------------

							--------------------------------------------------------------------------------------------------------
							-- actualizamos la tabla de turnos
							--------------------------------------------------------------------------------------------------------
							UPDATE tbSaleOrderAssemblyTurns
							SET
									soa_guid			= @soa_guid,
									user_id4Creation	= @user_id4Creation,
									user_id4lastUpdate	= @user_id4lastUpdate

							FROM tbSaleOrderAssemblyTurns tso		WITH (NOLOCK)

							INNER JOIN #tmpSaleOrderAssemblyTurns tmpsoa		WITH (NOLOCK)
							ON tmpsoa.comp_id			= tso.comp_id AND
							   tmpsoa.soa_id			= tso.soa_id
							--------------------------------------------------------------------------------------------------------

						END

					 ELSE
							BEGIN
					 			SELECT 1
								-- Para todos los articulos ,@soa_is4AllItems	= 'True'
							END

			END

			ELSE

				BEGIN
				-- Asignar turnos Automaticamente


						--------------------------------------------------------------------------------------------------------
						-- guardamos en una temporal los datos ya filtrados por la fecha
						--------------------------------------------------------------------------------------------------------

						SET @soa_turndate = dbo.fnGetEnd_or_BeginOfDate(@soa_turndate,'False')

						SELECT  TOP (@qtyTurn) *

						INTO #tmpSaleOrderAssemblyTurnsAutomatic

						FROM tbSaleOrderAssemblyTurns								tso		WITH (NOLOCK)

						WHERE (tso.comp_id			= @comp_id)		AND
							  (tso.bra_id			= @bra_id)		AND
							  (tso.soa_turnDate >=  @soa_turndate /*AND tso.soa_turnDate <= dbo.fnGetEnd_or_BeginOfDate(@soa_turndate,'true')*/) AND
							  (tso.soa_guid		IS NULL AND tso.soh_id IS NULL )

						ORDER BY tso.soa_turnDate,
								 tso.soa_id

						--SELECT * FROM #tmpSaleOrderAssemblyTurnsAutomatic
						--------------------------------------------------------------------------------------------------------

						--------------------------------------------------------------------------------------------------------
						-- actualizamos la tabla de turnos
						--------------------------------------------------------------------------------------------------------
						UPDATE tbSaleOrderAssemblyTurns
						SET
								soa_guid			= @soa_guid,
								user_id4Creation	= @user_id4Creation,
								user_id4lastUpdate	= @user_id4lastUpdate

						FROM tbSaleOrderAssemblyTurns tso

						INNER JOIN #tmpSaleOrderAssemblyTurnsAutomatic tmpsoa
						ON tmpsoa.comp_id			= tso.comp_id AND
						   tmpsoa.soa_id			= tso.soa_id

						--------------------------------------------------------------------------------------------------------

				END

END
GO


CREATE PROCEDURE spSaleOrderAssemblyTurns_CanInsertANewTurn
(
	@comp_id	INT,
	@lang_id	INT,
	@soa_guid	UNIQUEIDENTIFIER,
	@turnQty	INT,
	@qty2Insert	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@soh_bra_id	INT,
				@soh_id		INT,
				@turnQty	INT,
				@qty2Insert	INT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@soh_bra_id	= 1,
				@soh_id		= 1,
				@turnQty	= 1,
				@qty2Insert	= 1
		*/
		-- --------------------------------------------

		DECLARE
			@StrErrorMessage1	NVARCHAR(400),
			@strErrorMessage2	NVARCHAR(400)
		SET @StrErrorMessage1 = ''
		SET @strErrorMessage2 = ''

		SELECT
			@StrErrorMessage1	= tut.utexts_desc
		FROM tbsysUniqueTexts						tut WITH(NOLOCK)
		WHERE	tut.lang_id		= @lang_id AND
				tut.utexts_id	= 40345

		SELECT
			@StrErrorMessage2	= tut.utexts_desc
		FROM tbsysUniqueTexts						tut WITH(NOLOCK)
		WHERE	tut.lang_id		= @lang_id AND
				tut.utexts_id	= 40346

		-- -------------------------------------------------------------------------
		-- RECUPERO LOS TURNOS QUE YA TENGA GRABADOS ESTE PEDIDO
		-- -------------------------------------------------------------------------
			DECLARE @QtyTurnsInserted	INT
			SET		@QtyTurnsInserted	= 0
			SELECT
				@QtyTurnsInserted			= COUNT(*)
				FROM tbSaleOrderAssemblyTurns				tsoat	WITH(NOLOCK)
				WHERE	tsoat.comp_id		= @comp_id		AND
						tsoat.soa_guid		= @soa_guid
		-- -------------------------------------------------------------------------

		--SI LA CANTIDAD DE TURNOS QUE QUIERE GRABAR DE UN SAQUE, ES MAYOR A LA CANTIDAD DE MAQUINAS A ARMAR; NO SE LO TENGO QUE PERMITIR
		IF	@qty2Insert > @turnQty
			BEGIN
				SELECT
					'False'	[CanInsertNewTurn] ,
					@StrErrorMessage1 + CONVERT(VARCHAR,@turnQty)	 [Error_Message]
				RETURN
			END

		--SI YA TIENE TURNOS CARGADOS Y LA CANTIDAD ES IGUAL AL TOTAL DE MAQUINAS A ARMAR SEGUN EL PEDIDO, TAMPOCO TENGO QUE DEJARLO GRABAR UN TURNO
		IF @QtyTurnsInserted < @turnQty
			BEGIN
				SELECT 'True'	[CanInsertNewTurn],
				''				[Error_Message]
				RETURN
			END
		ELSE
			BEGIN
				SELECT 'False'	[CanInsertNewTurn],
				@strErrorMessage2 + CONVERT(VARCHAR,@turnQty)	 [Error_Message]
				RETURN
			END
	END
GO



