--Desc: Data para saber si se habilita el asignar automaticamente o no.
------------------------------------------------------------------------------------------------------


CREATE procedure [dbo].[spSaleOrderAssemblyTurns_CheckAutomaticTurns]
(
	@comp_id					INT,
	@soa_guid					UNIQUEIDENTIFIER,
	@soh_bra_id					INT,
	@soh_id						INT


)
as
SET NOCOUNT ON


-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id					INT,
				@soa_guid					UNIQUEIDENTIFIER,
				@soh_bra_id					INT,
				@soh_id						INT


	SELECT		@comp_id					= 1,
				@soa_guid					= 'B2A5B83F-7786-46F7-B9B6-43CCF6BE8988',
				@soh_bra_id					= 1,
				@soh_id						= 23132
*/
-------------------------------------------------------------------------------------------

BEGIN

	DECLARE @ldate AS DATETIME

	IF EXISTS (	SELECT top 1 tsoat.soa_turnDate

	           	FROM tbSaleOrderAssemblyTurns tsoat	WITH (NOLOCK)

	          	WHERE	tsoat.comp_id			= @comp_id AND
	          			tsoat.soa_guid			= @soa_guid

	          	ORDER BY soa_turnDate asc

				)

			BEGIN
				-- NO HABILITA BOTON ASIGNAR AUTOMATICAMENTE
				set @ldate = (SELECT top 1 tsoat.soa_turnDate

	           					FROM tbSaleOrderAssemblyTurns tsoat	WITH (NOLOCK)

	          					WHERE	tsoat.comp_id			= @comp_id AND
	          							tsoat.soa_guid			= @soa_guid

	          					ORDER BY soa_turnDate asc
							  )

				SELECT 0 [AutomaticStatus] , @ldate [date]
			END

		ELSE
		BEGIN
			-- HABILITA ASIGNAR AUTOMATICAMENTE

				SELECT 1 [AutomaticStatus]
			END





END
GO





