CREATE PROCEDURE spSaleOrderAssemblyTurns_GetDataByFilters2Transfer
(
	@comp_id	INT,
	@lang_id	INT,
	@user_id	INT,
	@prof_id	INT,
	@bra_id		INT,
	@custGuid	UNIQUEIDENTIFIER,
	@ItemGuid	UNIQUEIDENTIFIER,
	@datefrom	DATETIME,
	@dateto		DATETIME,
	@soh_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		SET DATEFORMAT 'YMD'

		-- -----------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@user_id	INT,
				@prof_id	INT,
				@bra_id		INT,
				@custGuid	UNIQUEIDENTIFIER,
				@ItemGuid	UNIQUEIDENTIFIER,
				@datefrom	DATETIME,
				@dateto		DATETIME,
				@soh_id		INT

			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@user_id	= 119,
				@prof_id	= 1,
				@bra_id		= 1,
				@custGuid	= '25892e17-80f6-415f-9c65-7395632f0223',
				@ItemGuid	= 'a53e98e4-0197-4513-be6d-49836e406aaa',
				@datefrom	= '2016-01-01',
				@dateto		= '2016-01-31',
				@soh_id		= 0
		*/
		-- -----------------------------------------------------------------

		-- ------------------------------------------------------------------------
		-- CLIENTES
		-- ------------------------------------------------------------------------
		DECLARE
			@tblCustomers TABLE(
								CustId			INT PRIMARY KEY
								)

		IF EXISTS (SELECT 1 FROM tbComplexFilter tcf WHERE tcf.sl_guid = @custGuid)
			BEGIN
				INSERT INTO @tblCustomers
				(
					CustId
				)
				SELECT
					tcf.sl_id
  					FROM tbComplexFilter tcf	WITH(NOLOCK)
  					WHERE tcf.sl_guid = @custGuid
			END
		ELSE
			BEGIN
				--SI NO HAY NADA EN LA COMPLEXFILTERS CARGAMOS TODOS LOS CLIENTES
				INSERT INTO @tblCustomers (CustId)
				SELECT tc.cust_id
					FROM tbCustomer tc		WITH(NOLOCK)
				    WHERE tc.comp_id = @comp_id
			END
		-- ------------------------------------------------------------------------

		-- ------------------------------------------------------------------------
		-- ARTÍCULOS
		-- ------------------------------------------------------------------------
		DECLARE
			@tblItems TABLE(
							ItemId			INT PRIMARY KEY
							)

		IF EXISTS (SELECT 1 FROM tbComplexFilter tcf WHERE tcf.sl_guid = @ItemGuid)
			BEGIN
				INSERT INTO @tblItems
				(
					ItemId
				)
				SELECT
					tcf.sl_id
  					FROM tbComplexFilter tcf	WITH(NOLOCK)
  					WHERE tcf.sl_guid = @ItemGuid
			END
		ELSE
			BEGIN
				--SI NO HAY NADA EN LA COMPLEXFILTERS CARGAMOS TODOS LOS ARTÍCULOS
				INSERT INTO @tblItems (ItemId)
				SELECT ti.item_id
				FROM tbItem ti		WITH(NOLOCK)
				    WHERE ti.comp_id = @comp_id
			END
		-- ------------------------------------------------------------------------






		SELECT
			' ' [ ],	--IMPRIMIR PEDIDO
			' ' [ ],	--TRANSFERIR A SUCURSAL
			dbo.fnGetCommercialTransactionDescription(tsoat.comp_id,
													  @lang_id,
													  tsoat.ct_transaction)	[Document],
			tsoat.soa_turnDate,
			tsoat.soa_isAssembled,
			tsoat.soa_isAssembledCD,
			tu2.user_lastname + ',' +tu2.user_firstname						[User],
			tsoat.soa_note,
			CONVERT(VARCHAR(30),tsoat.soa_id)								+ '-' +
			CONVERT(VARCHAR(30),tsoat.soh_id)								+ '-' +
			CONVERT(VARCHAR(30),tsoat.sod_id)								[ID]

		FROM tbSaleOrderHeader												tsoh	WITH(NOLOCK)
			INNER JOIN tbSaleOrderDetail									tsod	WITH(NOLOCK)
				ON	tsod.comp_id	= tsoh.comp_id							AND
					tsod.soh_id		= tsoh.soh_id
			INNER JOIN tbSaleOrderAssemblyTurns								tsoat	WITH(NOLOCK)
				ON	tsoat.comp_id	= tsod.comp_id							AND
					tsoat.soh_id	= tsod.soh_id							AND
					tsoat.sod_id	= tsod.sod_id
			LEFT JOIN tbUser												tu		WITH(NOLOCK)
				ON	tu.[user_id]	= tsoat.user_id4lastUpdate
			LEFT JOIN tbUser												tu2		WITH(NOLOCK)
				ON	tu2.[user_id]	= tsoat.user_id4isAssembled
			INNER JOIN @tblCustomers										tmpCust
				ON	tmpCust.CustId	= tsoh.cust_id
			INNER JOIN @tblItems											tmpItem
				ON	tmpItem.ItemId	= tsod.item_id



		WHERE	tsoh.comp_id							= @comp_id			AND
				ISNULL(tsoat.soa_isAssembled,'False')	= 'True'			AND
				(@bra_id	= -1 OR tsoat.bra_id		= @bra_id)			AND
				(@soh_id	= 0  OR tsoat.soh_id		= @soh_id)			AND
				tsoat.soa_turnDate BETWEEN @datefrom AND @dateto
	END
GO





