CREATE PROCEDURE [dbo].[spSaleOrderAssemblyTurns_getDataById]
(
	@comp_id			INT,
	@bra_id				INT,
	@soa_id				INT

)
AS

--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
/*
declare 	@comp_id	INT,
			@bra_id		INT,
			@soa_id		INT

select 		@comp_id	= 1,
			@soa_id		= 6767,
			@bra_id		= 234
*/
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------

BEGIN

	SELECT	tsoat.soa_id,
			tsoat.bra_id,
			tsoat.tis_id,
			tsoat.soa_guid,
			tsoat.soh_bra_id,
			isnull(tsoat.soh_id,-1)										[soh_id],
			tsoat.sod_id												[sod_id],
			isnull(tsoat.soa_is4AllItems,'false')						[soa_is4AllItems],
			tsoat.soa_cd												[soa_cd],
			tsoat.soa_isEditingCD										[soa_isEditingCD],
			tsoat.user_id4Creation										[user_id4Creation],
			tsoat.user_id4lastUpdate									[user_id4lastUpdate],
			isnull(tsoat.soa_isAssembled,'false')						[soa_isAssembled],
			tsoat.soa_isAssembledCD										[soa_isAssembledCD],
			tsoat.user_id4Assembly										[user_id4Assembly],
			isnull(tsoat.ct_transaction,-1)								[ct_transaction],
			tsoat.it_transaction										[it_transaction],
			isnull(tsoat.soa_isInAssembly,'false')						[soa_isInAssembly],
			tsoat.soa_isInAssemblyCD									[soa_isInAssemblyCD],
			tsoat.comp_id												[comp_id],
			tsoat.soa_turnDate											[soa_turnDate],
			right(convert(char(8),tsoat.soa_turnDate,8),8)				[Onlytime],
			isnull(tsoat.soa_note,'')									[soa_note]

	FROM	tbSaleOrderAssemblyTurns		tsoat		WITH (NOLOCK)

	where		tsoat.comp_id			 =	@comp_id
	and			tsoat.soa_id			 =  @soa_id
	AND			tsoat.bra_id			 =  @bra_id



END












GO


CREATE PROCEDURE spSaleOrderAssemblyTurns_GetQtyOfPendingTurns2AssembleBySohId
(
	@comp_id	INT,
	@soh_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------
		-- TESTING
		-- -------------------------
		/*
			DECLARE
				@comp_id	INT,
				@soh_id		INT
			SELECT
				@comp_id	= 1,
				@soh_id		= 123
		*/
		-- -------------------------

		--EN BASE AL NUMERO DE PEDIDO, VAMOS A CHECKEAR SI TODOS LOS TURNOS DE ARMADO
		--ASOCIADOS AL MISMO ESTAN FINALIZADOS, EN CASO DE NO ESTARLO, NO PERMITIREMOS
		--QUE SE REALICE LA TRANSFERENCIA HACIA LA SUCURSAL
		--SI EL COUNT ES MAYOR A 0(cero) IMPLICA QUE AL MENOS UN TURNO NO HA SIDO FINALIZADO

		SELECT
			COUNT(*)
		FROM tbSaleOrderAssemblyTurns								tsoat
		WHERE	tsoat.comp_id							= @comp_id	AND
				tsoat.soh_id							= @soh_id	AND
				ISNULL(tsoat.soa_isAssembled,'False')	= 'False'


	END


GO

CREATE PROCEDURE spSaleOrderAssemblyTurns_SendMail4BeginOrEndOfTurn
(

	@comp_id		INT,
	@user_id		INT,
	@soa_id			INT,
	@bitAssemblyEnd	BIT

)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------
		-- TESTING
		-- -----------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@user_id		INT,
				@soa_id			INT,
				@bitAssemblyEnd	BIT
		*/
		-- -----------------------------------------------

		-- VARIABLES DE TRABAJO
		DECLARE
			@lcust_id		INT,
			@lcust_email	NVARCHAR(100)

		IF @bitAssemblyEnd = 'False'
			BEGIN
				-- ---------------------------------------------------------
				-- ACA ARMAMOS Y ENVIAMOS EL MAIL CUANDO INICIA EL ARMADO
				-- ---------------------------------------------------------
					SELECT
						@lcust_id		= tsoh.cust_id,
						@lcust_email	= ISNULL(tc.cust_email,'')
					FROM tbSaleOrderAssemblyTurns		AS tsoat	WITH(NOLOCK)
					INNER JOIN tbSaleOrderHeader		AS tsoh		WITH(NOLOCK)
					ON	tsoh.comp_id = tsoat.comp_id	AND
						tsoh.soh_id = tsoat.soh_id
					INNER JOIN tbCustomer				AS tc		WITH (NOLOCK)
					ON	tc.comp_id	= tsoh.comp_id AND
						tc.cust_id	= tsoh.cust_id
					WHERE	tsoat.comp_id	= @comp_id	AND
							tsoat.soa_id	= @soa_id


					INSERT INTO tbsendEMailQueue
					(
						comp_id,
						-- smtpJob_id -- this column value is auto-generated
						[user_id],
						replyTo,
						sendTo,
						sendToCC,
						sendToCCO,
						[subject],
						body,
						displayName,
						attachment1_FileName,
						attachment1_FileContent,
						sq_cd,
						smtpJob_priority
					)
					VALUES
					(
						@comp_id,
						@user_id,
						'',
						@lcust_email,
						NULL,
						NULL,
						'Inicio de armado de PC',
						'Le informamos que el turno de armado de Equipo que tiene asignado ha iniciado',
						'Test',
						NULL,
						NULL,
						GETDATE(),
						1
					)

					--exec spSystem_sendEMail
					--			@compId					= @comp_id,
					--			@precipients			= @lcust_email,
					--			@pcopy_recipients		= NULL,
					--			@psubject				= 'Inicio de armado de PC',
					--			@pbody_format			= 'HTML',
					--			@pbody					= 'Le informamos que el turno de armado de Equipo que tiene asignado ha iniciado',
					--			@pfile_attachments		= NULL,
					--			@pReplyTo				= NULL,
					--			@pblind_copy_recipients	= NULL,
					--			@pUser_Id				= 0

				-- ---------------------------------------------------------

			END

		IF @bitAssemblyEnd = 'True'
			BEGIN
				-- ---------------------------------------------------------
				-- ACA ARMAMOS Y ENVIAMOS EL MAIL CUANDO FINALIZA EL ARMADO
				-- ---------------------------------------------------------
					SELECT
						@lcust_id		= tsoh.cust_id,
						@lcust_email	= ISNULL(tc.cust_email,'')
					FROM tbSaleOrderAssemblyTurns		AS tsoat	WITH(NOLOCK)
					INNER JOIN tbSaleOrderHeader		AS tsoh		WITH(NOLOCK)
					ON	tsoh.comp_id = tsoat.comp_id	AND
						tsoh.soh_id = tsoat.soh_id
					INNER JOIN tbCustomer				AS tc		WITH (NOLOCK)
					ON	tc.comp_id	= tsoh.comp_id AND
						tc.cust_id	= tsoh.cust_id
					WHERE	tsoat.comp_id	= @comp_id	AND
							tsoat.soa_id	= @soa_id


					INSERT INTO tbsendEMailQueue
					(
						comp_id,
						-- smtpJob_id -- this column value is auto-generated
						[user_id],
						replyTo,
						sendTo,
						sendToCC,
						sendToCCO,
						[subject],
						body,
						displayName,
						attachment1_FileName,
						attachment1_FileContent,
						sq_cd,
						smtpJob_priority
					)
					VALUES
					(
						@comp_id,
						@user_id,
						'',
						@lcust_email,
						NULL,
						NULL,
						'Finalización de armado de PC',
						'Le informamos que el turno de armado de Equipo que tiene asignado ha finalizado',
						'Test',
						NULL,
						NULL,
						GETDATE(),
						1
					)

					--exec spSystem_sendEMail
