CREATE PROCEDURE [dbo].[spSaleOrderCollect_GetSaleOrdersByFilters]
(
	@comp_id			INT,
	@ItemsGuid			UNIQUEIDENTIFIER,
	@CustGuid			UNIQUEIDENTIFIER,
	@df_id				INT,
	@status				INT,
	@DeliveryDateFrom	DATETIME,
	@DeliveryDateTo		DATETIME,
	@ssos_id			INT,				-- Tipo de Pedido
	@brag_id			INT,
	@dl_id				INT,
	@mlStatus			INT
)
AS
	--@mlStatus
	--ready_to_ship		- Listo para Enviar	-	1
	--pending			- Pendiente			- 	2
	--not_delivered		- No Entregado		-	3
	--delivered			- Entregado			-	4
	--cancelled			- Cancelado			-	5
	--shipped			- Enviado			-	6


	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@status				INT,
				@comp_id			INT,
				@ItemsGuid			UNIQUEIDENTIFIER,
				@CustGuid			UNIQUEIDENTIFIER,
				@df_id				INT,
				@DeliveryDateFrom	DATETIME,
				@DeliveryDateTo		DATETIME
			SELECT
				@comp_id			= 1,
				@ItemsGuid			= 'dc015b85-ad3d-40cc-9f27-bcee42f54a43',
				@CustGuid			= 'a022c389-95f7-49ed-ba0c-52fd2833eff3',
				@df_id				= -1,
				@status				= -1,
				@DeliveryDateFrom	= '2020-01-01',
				@DeliveryDateTo		= '2020-12-31'
		*/
		-- ---------------------------------------------

		--SP PARA FILTRAR PEDIDOS POR LOS PARAMETROS ABAJO MENCIONADOS PARA LUEGO INSERTAR EN LA COLECTA

		SET @DeliveryDateFrom	= dbo.fnGetEnd_or_BeginOfDate(@DeliveryDateFrom,'False')
		SET @DeliveryDateTo		= dbo.fnGetEnd_or_BeginOfDate(@DeliveryDateTo,	'True')

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Clientes para Filtros
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter					tcf			WITH (NOLOCK)
				WHERE	tcf.sl_guid		= @CustGuid     AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT tc.cust_id
					FROM tbCustomer tc				WITH (NOLOCK)
						WHERE tc.comp_id = @comp_id
			END
		-- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de ARTICULOS para Filtros
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter					tcf			WITH (NOLOCK)
				WHERE	tcf.sl_guid		= @ItemsGuid    AND
						tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
					FROM tbItem							AS ti		WITH (NOLOCK)
						WHERE ti.comp_id = @comp_id
			END
		-- -------------------------------------------------------------




		-- MOS 12-2022
		DECLARE @tabBranch as TABLE(bra_id INT PRIMARY KEY)
		IF @brag_id > 0
			BEGIN
				INSERT INTO @tabBranch
				(
					bra_id
				)
					SELECT tbg.bra_id
						FROM tbBranchGroupDetail	AS tbg WITH (NOLOCK)
						INNER JOIN tbbranch			AS	tb WITH (NOLOCK)
							ON	tb.comp_id		= tbg.comp_id	AND
								tb.bra_id		= tbg.bra_id
						WHERE	tbg.comp_id		= @comp_id		AND
								tbg.brag_id		= @brag_id		AND
								tb.bra_disabled = 'False'
			END
		ELSE
			BEGIN
				INSERT INTO @tabBranch
				(
					bra_id
				)
					SELECT bra_id
						FROM tbBranch AS tb	WITH (NOLOCK)
						WHERE	tb.comp_id		= @comp_id AND
								tb.bra_disabled = 'False'
			END







		SELECT DISTINCT
			' '																		[ ], --AGREGAR PEDIDO
			tc.cust_name,
			tsoh.soh_deliveryDate,
			tmlos.MLstatus,
			tmloh.MLorder_id,
			tmlos.MLshippingID,
			ISNULL(td.dl_name,'')													[dl_name],
			CONVERT(VARCHAR,tsoh.bra_id) + '-' + CONVERT(VARCHAR,tsoh.soh_id)		[ID]
			FROM tbSaleOrderHeader					AS tsoh	WITH(NOLOCK)
			INNER JOIN @tabBranch					AS tbg
				ON tbg.bra_id = tsoh.bra_id
			INNER JOIN tbDocumentsFile				AS tdf	WITH (NOLOCK)
			ON  tdf.comp_id		= tsoh.comp_id		AND
				tdf.df_id		= tsoh.df_id
			INNER JOIN tbSaleOrderDetail			AS tsod WITH(NOLOCK)
			ON	tsod.comp_id	= tsoh.comp_id		AND
				tsod.bra_id		= tsoh.bra_id		AND
				tsod.soh_id		= tsoh.soh_id
			INNER JOIN @tblComplexFilter_Customer	tmpCust
			ON	tmpCust.cust_id = tsoh.cust_id
			INNER JOIN tbCustomer					AS tc	WITH(NOLOCK)
			ON	tc.comp_id		= tsoh.comp_id		AND
				tc.cust_id		= tmpCust.cust_id
			INNER JOIN @tblComplexFilter_Items		tmpItems
			ON	tmpItems.item_id = tsod.item_id

			LEFT JOIN tbSaleOrderCollectDetail		AS tsocd	WITH(NOLOCK)
			ON	tsocd.comp_id		= tsoh.comp_id	AND
				tsocd.soh_bra_id	= tsoh.bra_id	AND
				tsocd.soh_id		= tsoh.soh_id

			LEFT JOIN tbMercadoLibre_ordersHeader	tmloh				WITH (NOLOCK)
			ON	tmloh.comp_id		= tsoh.comp_id	AND
				tmloh.mlo_id		= tsoh.mlo_id   AND
				ISNULL(tmloh.mlo_isCancelled,'False') = 'False'

			LEFT JOIN tbMercadoLibre_Branchs		tmlb				WITH (NOLOCK)
				ON	tmlb.comp_id	= tmloh.comp_id AND
					tmlb.mlbra_id	= tmloh.mlbra_id

			LEFT JOIN tbMercadoLibre_ordersShipping tmlos				WITH (NOLOCK)
				ON	tmlos.comp_id	= tmloh.comp_id	AND
					tmlos.mlo_id	= tmloh.mlo_id  AND
					tmlos.MLstatus	= 'ready_to_ship'
			LEFT JOIN tbDelivery					AS td				WITH(NOLOCK)
				ON	td.comp_id		= tsoh.comp_id	AND
					td.dl_id		= tsoh.dl_id

			WHERE	tsoh.comp_id = @comp_id												AND
					(
						@df_id		= -1 OR
						tsoh.df_id	= @df_id
					)																	AND
					tdf.sd_id IN (1,2,80)												AND -- MOS 08-2024: Solo Remitos y Facturas
					CASE
						WHEN @status = -1 THEN 'true'
						WHEN @status =  1 AND  EXISTS(	SELECT TOP 1  1
															FROM tbSaleOrderStatus tsos			WITH (NOLOCK)
					                              			WHERE	tsos.comp_id	= tsoh.comp_id
					                              				AND tsos.bra_id		= tsoh.bra_id
					                              				AND tsos.soh_id		= tsoh.soh_id
					                              				AND tsos.sos_ok		= 'False') THEN 'true' --  Pendientes de Autorizacion.
						WHEN @status =  2 AND NOT EXISTS(	SELECT TOP 1 1
															FROM tbSaleOrderStatus tsos			WITH (NOLOCK)
					                              			WHERE	tsos.comp_id	= tsoh.comp_id
					                              				AND tsos.bra_id		= tsoh.bra_id
					                              				AND tsos.soh_id		= tsoh.soh_id
					                              				AND tsos.sos_ok		= 'False') THEN 'True' --  Pendientes de Autorizacion.
						ELSE 'False'
					END	 = 'true'														AND
					tsoh.soh_deliveryDate BETWEEN @DeliveryDateFrom AND @DeliveryDateTo	AND
					tsocd.comp_id IS NULL												AND
					CASE
						WHEN @ssos_id = 0													THEN 1
						WHEN @ssos_id = 3		AND tsoh.ws_internalID IS NOT NULL			THEN 1
						WHEN @ssos_id = 200		AND tsod.rmad_id IS NOT NULL					THEN 1
						WHEN @ssos_id = 1003	AND tdf.sd_id = 80							THEN 1
						WHEN @ssos_id = 2000	AND tsoh.mlo_id IS NOT NULL					THEN 1
						WHEN @ssos_id = 2030	AND 	tmloh.comp_id IS NOT NULL		AND
														tmlos.MLfulfilled	= 'True'	AND
														tmlos.MLstatus		= 'delivered'
																							THEN 1		--MercadoLibre©: FulFillment Entregados
						WHEN @ssos_id = 2060	AND 	tmloh.comp_id IS NOT NULL		AND
														tmlos.MLSelf_Service= 'True'
										     												THEN 1		-- MercadoLibre©: Entrega Flex
						WHEN @ssos_id = 2070	AND 	tmloh.comp_id IS NOT NULL		AND
														tmlb.comp_id  IS NOT NULL
										     												THEN 1		-- MercadoLibre©: Retiro en Sucursal

						WHEN @ssos_id = 2075	AND 	tmloh.comp_id IS NOT NULL		AND
														tmlb.comp_id  IS     NULL		AND
														ISNULL(tmloh.MLShippingID,0) = 0
										     												THEN 1		-- MercadoLibre©: Retiro en LOCAL
						-- NUEVOS MOS 09-2021
						WHEN	@ssos_id			= 101			AND
								tsoh.ws_internalID	IS NOT NULL		AND
								tsoh.ssos_id			= 50			AND
								tsoh.ws_paymentGateWayStatusID	= 51			THEN 1
						WHEN	@ssos_id			= 102			AND
								tsoh.ws_internalID	IS NOT NULL		AND
								tsoh.ssos_id			<> 50			AND
								tsoh.ws_paymentGateWayStatusID	= 51			THEN 1
						WHEN	@ssos_id			= 103			AND
								tsoh.ws_internalID	IS NOT NULL		AND
								tsoh.ws_paymentGateWayStatusID	= 50			THEN 1
						WHEN @ssos_id = tsoh.ssos_id								THEN 1  --4,5,2
						-- NUEVOS MOS 09-2021
						-- NUEVOS SL 04-2023
						WHEN @ssos_id = 2100
							AND 	tmloh.comp_id IS NOT NULL		AND
														tmloh.mlo_ismshops = 'True'
																				THEN 1					-- MercadoShops© - Todos los pedidos para MercadoShops©
						ELSE 0
					END = 1																				-- TODOS los pedidos que NO SEAN ABONOS:!!!!!
																				AND
					(								--SI ES AREA COMERCIAL U OK EMISION NO DEBERIA TRAERLOS  -->> Este parentesis esta AL PEDO!!
						tsoh.ssos_id <> 10
							AND
						tsoh.ssos_id <> 50
					)															AND
					(
						@dl_id		= -1 OR
						tsoh.dl_id	= @dl_id
					)															AND
					(
						@mlStatus		= -1										OR
						(@mlStatus		=  1 AND tmlos.MLstatus = 'ready_to_ship')	OR
						(@mlStatus		=  2 AND tmlos.MLstatus = 'pending')		OR
						(@mlStatus		=  3 AND tmlos.MLstatus = 'not_delivered')	OR
						(@mlStatus		=  4 AND tmlos.MLstatus = 'delivered')		OR
						(@mlStatus		=  5 AND tmlos.MLstatus = 'cancelled')		OR
						(@mlStatus		=  6 AND tmlos.MLstatus = 'shipped')
					)
	END

GO


CREATE PROCEDURE [dbo].[spSaleOrderCollectDetail_DeleteData]
(
	@comp_id	INT,
	@cold_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------
		-- TESTING
		-- ----------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@cold_id	INT
			SELECT
				@comp_id	= 1,
				@cold_id	= 214
		*/
		-- ----------------------------------
		DECLARE @lcol_id	INT

		SELECT
			TOP 1
			@lcol_id = tsocd.col_id
		FROM tbSaleOrderCollectDetail		AS tsocd	WITH(NOLOCK)
		WHERE	tsocd.comp_id = @comp_id	AND
				tsocd.cold_id = @cold_id

		IF EXISTS(SELECT TOP 1 1
		          FROM tbSaleOrderCollectItems		AS tsoci	WITH(NOLOCK)
		          WHERE tsoci.comp_id	= @comp_id	AND
						tsoci.col_id	= @lcol_id)
			BEGIN
				SELECT 'False' [CanDelete]
			END
		ELSE
			BEGIN
				DELETE FROM tbSaleOrderCollectDetail
				WHERE	comp_id = @comp_id AND
						cold_id = @cold_id
				SELECT 'True' [CanDelete]
			END

		--IF @lcol_id IS NULL
		--	BEGIN
		--		DELETE FROM tbSaleOrderCollectDetail
		--		WHERE	comp_id = @comp_id AND
		--				cold_id = @cold_id
		--		SELECT 'True' [CanDelete]
		--	END
		--ELSE
		--	BEGIN
		--		SELECT 'False' [CanDelete]
		--	END
	END

GO


CREATE PROCEDURE [dbo].[spSaleOrderCollectDetail_GetData]
(
	@comp_id	INT,
	@lang_id	INT,
	@col_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------
		-- TESTING
		-- -----------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@col_id		INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@col_id		= 7
		*/
		-- -----------------------------------------------

		SELECT
			' '																						[ ], --ELIMINAR
			' '																						[ ], --PREPARAR Y SERIALIZAR
			tb.bra_desc,
			tsocd.soh_id,
			tc.cust_name,
			ISNULL(tu.user_lastname,'') + ISNULL(tu.user_firstname,'')								[user_name],
			--tsocd.cold_id																			[ID]
			CONVERT(VARCHAR,tsocd.cold_id)		+ '|' +
			CONVERT(VARCHAR,tsocd.comp_id)		+ '|' +
			CONVERT(VARCHAR,tsocd.soh_bra_id)	+ '|' +
			CONVERT(VARCHAR,tsocd.soh_id)															[ID]
			FROM tbSaleOrderCollectDetail			AS tsocd	WITH(NOLOCK)
			LEFT JOIN tbSaleOrderHeader			AS tsoh		WITH(NOLOCK)
			ON	tsoh.comp_id	= tsocd.comp_id		AND
				tsoh.bra_id		= tsocd.soh_bra_id	AND
				tsoh.soh_id		= tsocd.soh_id
			LEFT JOIN tbBranch						AS tb		WITH(NOLOCK)
			ON	tb.comp_id		= tsoh.comp_id		AND
				tb.bra_id		= tsoh.bra_id
			INNER JOIN tbUser						AS tu		WITH(NOLOCK)
			ON	tu.[user_id]	= tsocd.[user_id]
			LEFT JOIN tbCustomer					AS tc		WITH(NOLOCK)
			ON  tc.comp_id		= tsoh.comp_id		AND
				tc.cust_id		= tsoh.cust_id

			WHERE	tsocd.comp_id	= @comp_id		AND
					tsocd.col_id	= @col_id

	END





GO


CREATE PROCEDURE [dbo].[spSaleOrderCollectDetail_GetPendingItems]
(
	@comp_id	INT,
	@col_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@col_id		INT
			SELECT
				@comp_id	= 1,
				@col_id		= 210
		*/
		-- -------------------------------------------

		--ACA TENGO QUE TRAER PARA LA "HOJA" TODOS LOS ARTICULOS SUMARIZADOS
		--A SU VEZ HACER LA SUMA DE CUANTOS LLEVO RECOLECTADOS PARA PDOER HACER LA TRANSFERENCIA
		--HACER VALIDACIÒN EN OTRO SP PARA NO TOMAR ART DE MAS
		DECLARE @tblTotalQty2Count TABLE
			(
				comp_id		INT,
				item_id		INT,
				stor_id		INT,
				TotalQty	INT
			)
		INSERT INTO @tblTotalQty2Count
			(
				comp_id,
				item_id,
				stor_id,
				TotalQty
			)

		SELECT
			ti.comp_id,
			ti.item_id,
			ts.stor_id,
			SUM(tsod.sod_qty)
		FROM tbSaleOrderCollectDetail		AS tsocd	WITH(NOLOCK)
		INNER JOIN tbSaleOrderDetail		AS tsod		WITH(NOLOCK)
		ON	tsod.comp_id	= tsocd.comp_id AND
			tsod.soh_id		= tsocd.soh_id
		INNER JOIN tbStorage				AS ts		WITH(NOLOCK)
		ON	ts.comp_id		= tsod.comp_id	AND
			ts.stor_id		= tsod.stor_id
		INNER JOIN tbItem					AS ti		WITH(NOLOCK)
		ON	ti.comp_id		= tsod.comp_id	AND
			ti.item_id		= tsod.item_id
		WHERE	tsocd.comp_id	= @comp_id AND
				tsocd.col_id	= @col_id
		GROUP BY ti.comp_id, ti.item_id, ts.stor_id



		SELECT
			--' ' [ ],
			--' ' [ ],
			' ' [ ],
			ti.item_id,
			ti.item_code,
			ISNULL(ti.item_vendorCode,'')				[item_vendorCode],
			ti.item_desc,
			ts.stor_desc,
			ISNULL(tis.itst_StorageLocation,'')			[itst_StorageLocation],
			CONVERT(INT,SUM(ISNULL(tsoci.coli_qty,0)))	[CountedQty],
			tmp.TotalQty								[TotalQty]
		FROM @tblTotalQty2Count				AS tmp
		INNER JOIN tbStorage				AS ts		WITH(NOLOCK)
		ON	ts.comp_id	= tmp.comp_id		AND
			ts.stor_id	= tmp.stor_id
		INNER JOIN tbItemStorage			AS tis		WITH(NOLOCK)
		ON	tis.comp_id	= ts.comp_id		AND
			tis.stor_id	= ts.stor_id		AND
			tis.item_id	= tmp.item_id
		INNER JOIN tbItem AS ti
		ON	ti.comp_id	= tmp.comp_id		AND
			ti.item_id	= tmp.item_id
		LEFT JOIN tbSaleOrderCollectItems	AS tsoci	WITH(NOLOCK)
		ON	tsoci.comp_id = tmp.comp_id		AND
			tsoci.item_id = tmp.item_id		AND
			tsoci.stor_id = tmp.stor_id		AND
			tsoci.col_id  = @col_id
		GROUP BY ti.item_id, ti.item_code, ti.item_vendorCode, item_desc, ts.stor_desc, tis.itst_StorageLocation, tmp.TotalQty
		ORDER BY ti.item_code


		--SELECT
		--	' ' [ ],
		--	' ' [ ],
		--	' ' [ ],
		--	ti.item_code,
		--	ti.item_desc,
		--	ts.stor_desc,
		--	SUM(ISNULL(tsoci.coli_qty,0))	[CountedQty],
		--	SUM(tsod.sod_qty)				[TotalQty]
		--FROM tbSaleOrderCollectDetail		AS tsocd	WITH(NOLOCK)
		--INNER JOIN tbSaleOrderDetail		AS tsod		WITH(NOLOCK)
		--ON	tsod.comp_id	= tsocd.comp_id AND
		--	tsod.soh_id		= tsocd.soh_id
		--INNER JOIN tbItem					AS ti		WITH(NOLOCK)
		--ON	ti.comp_id		= tsod.comp_id	AND
		--	ti.item_id		= tsod.item_id
		--INNER JOIN tbStorage				AS ts		WITH(NOLOCK)
		--ON	ts.comp_id		= tsod.comp_id	AND
		--	ts.stor_id		= tsod.stor_id


		--LEFT JOIN tbSaleOrderCollectItems	AS tsoci	WITH(NOLOCK)
		--ON	tsoci.comp_id	= tsocd.comp_id AND
		--	tsoci.col_id	= tsocd.col_id	AND
		--	tsoci.item_id	= tsod.item_id


		--WHERE	tsocd.comp_id	= @comp_id	AND
		--		tsocd.col_id	= @col_id

		--GROUP BY item_code, item_desc, ts.stor_desc

		--ORDER BY ti.item_code

	END
GO


