CREATE PROCEDURE [dbo].[spSaleOrderCollectDetail_InsertDataByShippingOrOrderID]
(
	@comp_id			INT,
	@col_id				INT,
	@user_id			INT,
	@ShippIdOrOrderID	BIGINT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------------------
		-- TESTING
		-- --------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@col_id				INT,
				@user_id			INT,
				@ShippIdOrOrderID	BIGINT
			SELECT
				@comp_id			= 1,
				@col_id				= 7,
				@user_id			= 1,
				@ShippIdOrOrderID	= 2355811874
				--MLShippingID		= 28280441490,
				--MLOrderID			= 2355811874
		*/
		-- --------------------------------------------------

		--SI BUSCA POR SHIPPING	RECUPERO E INSERTO
		--RECUPERA TODAS LAS ORDENES QUE TENGAN ASOCIADO ESE SHIPPING ID
		--Y LAS INSERTA SIEMPRE Y CUANDO NO EXISTAN YA EN OTRA COLECTA
		IF EXISTS (SELECT TOP 1 1
					FROM tbMercadoLibre_ordersShipping		AS tmlos	WITH(NOLOCK)
					INNER JOIN tbMercadoLibre_ordersHeader	AS tmloh	WITH(NOLOCK)
					ON	tmloh.comp_id			= tmlos.comp_id AND
						tmloh.mlo_id			= tmlos.mlo_id
					INNER JOIN tbSaleOrderHeader			AS tsoh		WITH(NOLOCK)
					ON	tsoh.comp_id			= tmloh.comp_id AND
						tsoh.mlo_id				= tmloh.mlo_id
					LEFT JOIN tbSaleOrderCollectDetail		AS tsocd	WITH(NOLOCK)
					ON	tsocd.comp_id			= tsocd.comp_id AND
						tsocd.soh_bra_id		= tsoh.bra_id	AND
						tsocd.soh_id			= tsoh.soh_id

					WHERE	tmlos.comp_id		= @comp_id			AND
							tmlos.MLshippingID	= @ShippIdOrOrderID	AND
							tsocd.col_id		IS NULL	)
			BEGIN

				INSERT INTO tbSaleOrderCollectDetail
				(
					comp_id,
					col_id,
					-- cold_id -- this column value is auto-generated
					soh_bra_id,
					soh_id,
					[user_id]
				)
				SELECT
					tsoh.comp_id,
					@col_id,
					tsoh.bra_id,
					tsoh.soh_id,
					@user_id
				FROM tbMercadoLibre_ordersShipping		AS tmlos	WITH(NOLOCK)
				INNER JOIN tbMercadoLibre_ordersHeader	AS tmloh	WITH(NOLOCK)
				ON	tmloh.comp_id			= tmlos.comp_id AND
					tmloh.mlo_id			= tmlos.mlo_id
				INNER JOIN tbSaleOrderHeader			AS tsoh		WITH(NOLOCK)
				ON	tsoh.comp_id			= tmloh.comp_id AND
					tsoh.mlo_id				= tmloh.mlo_id
				LEFT JOIN tbSaleOrderCollectDetail		AS tsocd	WITH(NOLOCK)
				ON	tsocd.comp_id			= tsocd.comp_id AND
					tsocd.soh_bra_id		= tsoh.bra_id	AND
					tsocd.soh_id			= tsoh.soh_id

				WHERE	tmlos.comp_id		= @comp_id			AND
						tmlos.MLshippingID	= @ShippIdOrOrderID	AND
						tsocd.col_id		IS NULL

				SELECT
					'True'	[Exists],
					'Ship'	[Source]
			END
		ELSE
			IF EXISTS(SELECT TOP 1 1
						FROM tbMercadoLibre_ordersHeader		AS tmloh	WITH(NOLOCK)
						INNER JOIN tbSaleOrderHeader			AS tsoh		WITH(NOLOCK)
						ON	tsoh.comp_id			= tmloh.comp_id AND
							tsoh.mlo_id				= tmloh.mlo_id
						LEFT JOIN tbSaleOrderCollectDetail		AS tsocd	WITH(NOLOCK)
						ON	tsocd.comp_id			= tsoh.comp_id AND
							tsocd.soh_bra_id		= tsoh.bra_id	AND
							tsocd.soh_id			= tsoh.soh_id
						WHERE	tmloh.comp_id		= @comp_id			AND
								tmloh.MLorder_id	= @ShippIdOrOrderID	AND
								tsocd.comp_id		IS NULL)
				BEGIN
					--SI BUSCA POR MLORDERID RECUPERO E INSERTO
					--RECUPERA TODAS LAS ORDENES QUE TENGAN ASOCIADO ESE ORDER ID
					--Y LAS INSERTA SIEMPRE Y CUANDO NO EXISTAN YA EN OTRA COLECTA
					INSERT INTO tbSaleOrderCollectDetail
					(
						comp_id,
						col_id,
						-- cold_id -- this column value is auto-generated
						soh_bra_id,
						soh_id,
						[user_id]
					)
					SELECT
						tsoh.comp_id,
						@col_id,
						tsoh.bra_id,
						tsoh.soh_id,
						@user_id
					FROM tbMercadoLibre_ordersHeader		AS tmloh	WITH(NOLOCK)
					INNER JOIN tbSaleOrderHeader			AS tsoh		WITH(NOLOCK)
					ON	tsoh.comp_id			= tmloh.comp_id AND
						tsoh.mlo_id				= tmloh.mlo_id
					LEFT JOIN tbSaleOrderCollectDetail		AS tsocd	WITH(NOLOCK)
					ON	tsocd.comp_id			= tsoh.comp_id AND
						tsocd.soh_bra_id		= tsoh.bra_id	AND
						tsocd.soh_id			= tsoh.soh_id
					WHERE	tmloh.comp_id		= @comp_id			AND
							tmloh.MLorder_id	= @ShippIdOrOrderID	AND
							tsocd.comp_id		IS NULL

					SELECT
						'True'	[Exists],
						'Order'	[Source]
				END
			ELSE
				BEGIN
					SELECT
						'False'		[Exists],
						'NotFound'	[Source]
				END

	END

GO

CREATE PROCEDURE spSaleOrderCollectDetail_InsertSaleOrder
(
	@comp_id	INT,
	@col_id		INT,
	@soh_bra_id	INT,
	@soh_id		INT,
	@user_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		--ESTE INSERTE EL PEDIDO SELECCIONADO EN LA DETAIL SIEMPRE Y CUAUNDO ESTE NO EXISTA
		IF NOT EXISTS (SELECT TOP 1 1
						FROM tbSaleOrderCollectDetail AS tsocd	WITH(NOLOCK)
						WHERE	tsocd.comp_id		= @comp_id AND
								tsocd.col_id		= @col_id AND
								tsocd.soh_bra_id	= @soh_bra_id AND
								tsocd.soh_id		= @soh_id)
			BEGIN
				INSERT INTO tbSaleOrderCollectDetail
				(
					comp_id,
					col_id,
					-- cold_id -- this column value is auto-generated
					soh_bra_id,
					soh_id,
					[user_id]
				)
				VALUES
				(
					@comp_id,
					@col_id,
					@soh_bra_id,
					@soh_id,
					@user_id
				)

				SELECT
					'True'		[Exists],
					'SaleOrder'	[Source]

			END
		ELSE
			BEGIN
				SELECT
					'False'		[Exists],
					'SaleOrder'	[Source]
			END
	END
GO


CREATE PROCEDURE [dbo].[spSaleOrderCollectDetail_IsItemInSheet]
(
	@comp_id		INT,
	@col_id			INT,
	@ItemCodeOrEan	VARCHAR(100),
	@bra_id			INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@col_id		INT,
				@ItemCodeOrEan	VARCHAR(50),
				@bra_id			INT
			SELECT
				@comp_id		= 1,
				@col_id			= 212,
				@ItemCodeOrEan	= 'D1',
				@bra_id			= 1
		*/
		-- -----------------------------------------

		--RECUPERAMOS EL ITEM_ID EN BASE AL CODIGO QUE NOS ENVIAN
		--PARA SABER SI ESTA EN LA HOJA DE COLECTA
		DECLARE @lItem_Id			INT
		SELECT TOP 1
			@lItem_Id = ti.item_id
			FROM tbItem									ti	WITH(NOLOCK)
				LEFT JOIN tbItemEAN						tie	WITH(NOLOCK)
					ON	tie.comp_id = ti.comp_id		AND
						tie.item_id = ti.item_id
				--LEFT JOIN tbItemSerials					tis	WITH(NOLOCK)	--ESTO LO SAQUE PORQUE ESTABA BUSCANDO POR SERIAL, PERO NO SI EL SERIAL QUE ESTABA INGRESANDO CORRESPONDIA A UN SERIAL
				--	ON  tis.comp_id		= ti.comp_id	AND						--DE LOS PEDIDOS QUE CONFORMAN LA HOJA DE COLECTA
				--		tis.item_id		= ti.item_id
			WHERE	ti.comp_id = @comp_id AND
					(
						ti.item_code	= @ItemCodeOrEan OR
						tie.ie_ean		= @ItemCodeOrEan --OR
						--tis.is_serial	= @ItemCodeOrEan
					)
		-- ---------------------------------------------------------------------
		-- busca x Codigo del Proveedor o Alternativo si lo Admite la Sucursal.
		-- ---------------------------------------------------------------------
		IF @lItem_Id IS NULL
			BEGIN
				SET @lItem_Id = ( select TOP 1 ti.item_id
										from tbItem		ti		WITH (NOLOCK)
										INNER JOIN tbBranch tb	WITH (NOLOCK)
											ON	tb.comp_id	= @comp_id	AND
												tb.bra_id	= @bra_id
										WHERE	ti.comp_id	= @comp_id									AND
												tb.bra_StockControlSearchByAlternativeCodes = 'True'	AND
											(
												ti.item_vendorCode			= @ItemCodeOrEan
											OR
												ti.item_codeAlternative		= @ItemCodeOrEan
											)
				)
			END
		-- ---------------------------------------------------------------------

		-- ---------------------------------------------------------------------
		-- BUSCAR POR NRO DE SERIE
		-- ---------------------------------------------------------------------
			DECLARE @lItemFoundBySerial	BIT
			SET @lItemFoundBySerial = 'False'
			-- SI NO LO ENCONTRO POR LOS MEDIOS ANTERIORES
			IF @lItem_Id IS NULL
				BEGIN
					SELECT
						@lItem_Id = tis.item_id
						FROM tbSaleOrderSerials						AS tsos		WITH(NOLOCK)
						INNER JOIN tbSaleOrderCollectDetail			AS tsocd	WITH(NOLOCK)
							ON	tsocd.comp_id		= tsos.comp_id	AND
								tsocd.soh_bra_id	= tsos.bra_id	AND
								tsocd.soh_id		= tsos.soh_id
						INNER JOIN tbItemSerials					AS tis		WITH(NOLOCK)
							ON	tis.is_id			= tsos.is_id
						WHERE	tsos.comp_id		= @comp_id		AND
								tsocd.col_id		= @col_id		AND
								tis.is_serial		= @ItemCodeOrEan
					IF @lItem_Id IS NOT NULL
						BEGIN
							SET @lItemFoundBySerial = 'True'
						END
				END
		-- ---------------------------------------------------------------------


		IF EXISTS (SELECT TOP 1 1
					FROM tbSaleOrderCollectDetail			AS tsocd	WITH(NOLOCK)
					INNER JOIN tbSaleOrderDetail			AS tsod		WITH(NOLOCK)
					ON	tsod.comp_id		= tsocd.comp_id AND
						tsod.soh_id			= tsocd.soh_id
					WHERE	tsod.comp_id	= @comp_id		AND
							tsocd.col_id	= @col_id		AND
							tsod.item_id	= @lItem_Id)
			BEGIN
				SELECT
					'True'				[IsItemInSheet],
					@lItem_Id			[item_id],
					@lItemFoundBySerial	[IsItemFoundBySerial]
			END
		ELSE
			BEGIN
				SELECT
					'False'				[IsItemInSheet],
					-1					[item_id],
					@lItemFoundBySerial	[IsItemFoundBySerial]
			END

	END
GO

CREATE PROCEDURE [dbo].[spSaleOrderCollectHeader_CloseCollect]
(
	@comp_id	INT,
	@col_id		INT,
	@user_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ACA DEBERÏA HACER TODO EL PROCESO Y SI ESTA OK, RECIEN AHÍ CIERRA TODO
		DECLARE @lbitIsProcessOK AS BIT
		SET		@lbitIsProcessOK = 'False'

		--== ESTO ES TEST DESPUES HAY QUE BORRARLO
			SET @lbitIsProcessOK = 'True'
		--==





		-- SI PROCESÓ TODO OK ENTONCES PUEDE DAR EL CIERRE A LA HOJA DE COLECTA
		IF @lbitIsProcessOK = 'True'
			BEGIN
				--ESTE SP ES PARA LLAMAR CUANDO SE TERMINA DE COLECTAR EL ULTIMOA RTICULO Y NO QUEDA NADA MAS PENDIENTE
				UPDATE tbSaleOrderCollectHeader
				SET
					col_closed		= 'True',
					col_closeDate	= GETDATE(),
					user_id_4close	= @user_id
					WHERE	comp_id			= @comp_id AND
							col_id			= @col_id

			END
		SELECT @lbitIsProcessOK [IsProcessed]


	END

GO

CREATE PROCEDURE [dbo].[spSaleOrderCollectHeader_DeleteData]
(
	@comp_id	INT,
	@col_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		--SI ESTA COLECTA TIENE COSAS RELACIONADAS NO SE LO TENGO QUE DEJAR BORRAR

		DECLARE @bolCanDeleteCollectHeader AS BIT
		SET		@bolCanDeleteCollectHeader = 'True'
		IF (SELECT
				COUNT(*)
				FROM tbSaleOrderCollectDetail		AS tsocd	WITH(NOLOCK)
				WHERE	tsocd.comp_id	= @comp_id	AND
						tsocd.col_id	= @col_id) > 0
			BEGIN
				SET @bolCanDeleteCollectHeader = 'False'
			END
		ELSE
			BEGIN
				DELETE FROM  tbSaleOrderCollectHeader
				WHERE	comp_id = @comp_id AND
						col_id	= @col_id
			END
		SELECT @bolCanDeleteCollectHeader CanDeleteRecord

	END


GO

CREATE PROCEDURE [dbo].[spSaleOrderCollectHeader_GetCombo]
(
	@comp_id	INT,
	@intStatus	INT -- -1 TODAS / 1 Cerradas / 2 Abiertas / 3 No cerradas, No tomadas por WMS
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id	INT
			SELECT
				@comp_id	= 1
		*/
		-- -------------------------------------------------
		--ESTE ES EL GETCOMBO PARA LA PAGINA DE COLECTA DE ARTICULOS
		--VA A TRAER DEPENDIENDO DE UN PARAMETRO LOS QUE ESTEN AUN ABIERTOS O LOS CERRADOS
		--TAMBIEN PODRIA TRAER TODAS
		SELECT	DISTINCT
			tsoch.col_desc	[Desc],
			tsoch.col_id	[Id]
			FROM tbSaleOrderCollectHeader							AS tsoch	WITH(NOLOCK)
			INNER JOIN tbSaleOrderCollectDetail						AS tsocd	WITH (NOLOCK)
				ON	tsocd.comp_id	= tsoch.comp_id AND
					tsocd.col_id	= tsoch.col_id
			WHERE	tsoch.comp_id	= @comp_id		AND
					(
						@intStatus = -1														OR
						@intStatus =  1	AND ISNULL(tsoch.col_closed,'False')	= 'True'	OR
						@intStatus =  2	AND ISNULL(tsoch.col_closed,'False')	= 'False'	OR

						@intStatus =  3 AND ISNULL(tsoch.col_closed,'False')	= 'False'
										AND ISNULL(tsoch.col_isCollected4WMS,'False')	= 'False'
					)


	END
GO

CREATE PROCEDURE [dbo].[spSaleOrderCollectHeader_getCombo4SaleOrderFilter]
(
	@comp_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------
		-- TESTING
		-- -------------------------------------------------
		/*
			DECLARE
				@comp_id	INT = 1
		*/
		-- -------------------------------------------------


		-- Trae las colectas TERMINADAS para luego filtrar los pedidos QUE AUN ESTEN de esas colectas.
		SELECT	DISTINCT
			tsoch.col_desc	[Desc],
			tsoch.col_id	[Id]
			FROM tbSaleOrderCollectHeader							AS tsoch	WITH(NOLOCK)
			INNER JOIN tbSaleOrderCollectDetail						AS tsocd	WITH (NOLOCK)
				ON	tsocd.comp_id	= tsoch.comp_id		AND
					tsocd.col_id	= tsoch.col_id
			INNER JOIN tbSaleOrderHeader							AS tsoh		WITH (NOLOCK)
				ON	tsoh.comp_id	= tsocd.comp_id		AND
					tsoh.bra_id		= tsocd.soh_bra_id	AND
					tsoh.soh_id		= tsocd.soh_id
			WHERE	tsoch.comp_id	= @comp_id			AND
					tsoch.col_closed= 'True'


	END
GO


CREATE PROCEDURE [dbo].[spSaleOrderCollectHeader_GetDataByFilters]
(
	@comp_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@user_id4Close	INT,
	@dateFrom		DATETIME,
	@dateTo			DATETIME,
	@status			INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@user_id		INT,
				@user_id4Close	INT,
				@dateFrom		DATETIME,
				@dateTo			DATETIME,
				@status			INT
			SELECT
				@comp_id		= 1,
				@bra_id			= -1,
				@user_id		= -1,
				@user_id4Close	= -1,
				@dateFrom		= '2020-09-01',
				@dateTo			= '2021-09-30',
				@status			= -1
		*/
		-- -----------------------------------------------------------------------------

		SET @dateFrom = dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'False')
		SET @dateTo =	dbo.fnGetEnd_or_BeginOfDate(@dateTo,'True')

		SELECT
			' '									[ ], --Modificar Encabezado
			' '									[ ], --Agregar pedidos a la Hoja de Colecta
			(SELECT
					ISNULL(SUM(ISNULL(tsod.sod_qty,0)),0)
				 FROM tbSaleOrderCollectDetail			AS tsocd	WITH(NOLOCK)
					INNER JOIN tbSaleOrderDetail		AS tsod		WITH(NOLOCK)
					ON  tsod.comp_id = tsocd.comp_id	AND
						tsod.soh_id = tsocd.soh_id		AND
						tsod.bra_id = tsocd.soh_bra_id
					WHERE	tsocd.comp_id	= tsoch.comp_id AND
							tsocd.col_id	= tsoch.col_id
			)									[ ], --Eliminar Hoja de Colecta			// TOTAL DE ITEMS A CONTAR EN PEDIDOS DE LA HOJA
			(SELECT
					ISNULL(SUM(ISNULL(tsoci.coli_qty,0)),0)
				 FROM tbSaleOrderCollectItems			AS tsoci	WITH(NOLOCK)
				 WHERE	tsoci.comp_id	= tsoch.comp_id AND
						tsoci.col_id	= tsoch.col_id
			)									[ ], --Cerrar Colecta + Proceso			// TOTAL DE ARTICULOS CONTADOS EN COLLECT ITEMS
			tsoch.col_desc,
			tb.bra_desc,
			ISNULL(tu.user_lastname,'') + ',' + ISNULL(tu.user_lastname,'') [user_name],
			tsoch.col_cd,
			tsoch.col_closed,
			tsoch.col_closeDate,
			tu2.user_lastname + ',' + tu2.user_firstname [user_id_4close],
			tsoch.col_id						[ID]
			FROM tbSaleOrderCollectHeader		AS tsoch	WITH(NOLOCK)
			INNER JOIN tbBranch					AS tb		WITH(NOLOCK)
			ON	tb.comp_id			= tsoch.comp_id AND
				tb.bra_id			= tsoch.bra_id
			LEFT JOIN tbUser					AS tu		WITH(NOLOCK)
			ON	tu.[user_id]		= tsoch.[user_id]
			LEFT JOIN tbUser					AS tu2		WITH(NOLOCK)
			ON	tu2.[user_id]		= tsoch.user_id_4close
			WHERE	tsoch.comp_id	= @comp_id					AND
					(
						@bra_id			= -1 OR
						tsoch.bra_id	= @bra_id
					)											AND
					(
						@user_id				= -1 OR
						tsoch.[user_id]			= @user_id
					)											AND
					(
						@user_id4Close			= -1 OR
						tsoch.user_id_4close	= @user_id4Close
					)											AND
					tsoch.col_cd BETWEEN @dateFrom AND @dateTo	AND
					(
						@status					= -1 OR
						ISNULL(tsoch.col_closed,'False') = @status
					)


	END

GO

