CREATE PROCEDURE [dbo].[spSaleOrderCollectItems_RecountItemByItemID]
(
	@comp_id	INT,
	@col_id		INT,
	@item_id	INT,
	@stor_id	INT,
	@user_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ----------------------------------
		-- TESTING
		-- ----------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@col_id		INT,
				@item_id	INT,
				@stor_id	INT,
				@qty		INT,
				@user_id	INT
			SELECT
				@comp_id	= 1,
				@col_id		= 214,
				@item_id	= 15549,
				@stor_id	= 689,
				@user_id	= 134
		*/
		-- ----------------------------------



		--PRIMERO TENGO QUE VER.... EXISTE un registro en colecta? Tiene un ID?
		DECLARE	@lcoli_id	INT
		SET		@lcoli_id	= -1

		IF EXISTS (SELECT TOP 1 1
					FROM tbSaleOrderCollectItems		AS tsoci	WITH(NOLOCK)
					WHERE	tsoci.comp_id	= @comp_id	AND
							tsoci.col_id	= @col_id	AND
							tsoci.stor_id	= @stor_id	AND
							tsoci.item_id	= @item_id)
			BEGIN
				SELECT
					@lcoli_id = tsoci.coli_id
					FROM tbSaleOrderCollectItems		AS tsoci	WITH(NOLOCK)
					WHERE	tsoci.comp_id	= @comp_id	AND
							tsoci.col_id	= @col_id	AND
							tsoci.stor_id	= @stor_id	AND
							tsoci.item_id	= @item_id
			END

		-- SI EXISTE EL REGISTRO, ENTONCES LE PONGO LA CANTIDAD EN 0
		IF @lcoli_id > 0
		BEGIN
			UPDATE tbSaleOrderCollectItems
			SET
				coli_qty	= 0
			WHERE	comp_id = @comp_id	AND
					coli_id = @lcoli_id
		END

	END
GO


CREATE PROCEDURE [dbo].[spSaleOrderCollectItems_UpdateQty]
(
	@comp_id	INT,
	@col_id		INT,
	@item_id	INT,
	@stor_id	INT,
	@qty		INT,
	@user_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ----------------------------------
		-- TESTING
		-- ----------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@col_id		INT,
				@item_id	INT,
				@stor_id	INT,
				@qty		INT,
				@user_id	INT
			SELECT
				@comp_id	= 1,
				@col_id		= 214,
				@item_id	= 15549,
				@stor_id	= 689,
				@qty		= 1,
				@user_id	= 134
		*/
		-- ----------------------------------

		-- PRIMERO GRABO EN UNA TEMPORAL LOS DATOS A CONTAR PARA LA HOJA SELECCIONADA
		-- TENGO QUE VALIDAR TANTO EN INSERT COMO EN UPDATE

		-- ACA VOY A METER EN UNA TEMPORAL LOS DATOS SEPARADOS POR STOR ID para poder sumar y corroborar
		-- ---------------------------------------------------
		-- TEMPORAL CON LOS DATOS ACTUALES SEPARADOS POR STOR
		-- ---------------------------------------------------
			DECLARE @tblCountedDataInfo TABLE
			(
				item_id		INT,
				stor_id		INT,
				CountedQty	INT,
				TotalQty	INT
			)

			INSERT INTO @tblCountedDataInfo
			(
				item_id,
				stor_id,
				CountedQty,
				TotalQty
			)
			SELECT
				ti.item_id,
				ts.stor_id,
				0,
				--SUM(ISNULL(tsoci.coli_qty,0))	[CountedQty],
				SUM(tsod.sod_qty)				[TotalQty]
				FROM tbSaleOrderCollectDetail		AS tsocd WITH(NOLOCK)
				LEFT JOIN tbSaleOrderDetail			AS tsod WITH(NOLOCK)
				ON	tsod.comp_id	= tsocd.comp_id AND
					tsod.soh_id		= tsocd.soh_id
				--LEFT JOIN tbSaleOrderCollectItems	AS tsoci WITH(NOLOCK)
				--ON	tsoci.comp_id	= tsocd.comp_id	AND
				--	tsoci.col_id	= tsocd.col_id	AND
				--	tsoci.item_id	= tsod.item_id
				INNER JOIN tbStorage				AS ts	WITH(NOLOCK)
				ON	ts.comp_id		= tsod.comp_id	AND
					ts.stor_id		= tsod.stor_id
				INNER JOIN tbItem					AS ti	WITH(NOLOCK)
				ON	ti.item_id		= tsod.item_id	AND
					ti.comp_id		= tsod.comp_id
				WHERE	tsocd.comp_id	= @comp_id	AND
						tsocd.col_id	= @col_id
				GROUP BY ti.item_id, ts.stor_id

			DECLARE @tblCountedQty TABLE
			(
				item_id		INT,
				CountedQty	INT
			)
			INSERT INTO @tblCountedQty
			(
				item_id,
				CountedQty
			)
			SELECT
				tsoci.item_id,
				SUM(ISNULL(tsoci.coli_qty,0))	[CountedQty]
				FROM tbSaleOrderCollectItems	AS tsoci WITH(NOLOCK)
				WHERE	tsoci.comp_id	= @comp_id	AND
						tsoci.col_id	= @col_id
				GROUP BY tsoci.item_id

			UPDATE @tblCountedDataInfo
			SET CountedQty = tbl2.CountedQty
			FROM @tblCountedDataInfo tbl
				INNER JOIN @tblCountedQty tbl2
					ON tbl2.item_id = tbl.item_id


		DECLARE
			@lTotalQty4Storage		INT,
			@lQtyCounted4Storage	INT

		SELECT
			@lQtyCounted4Storage		= tmp.CountedQty,
			@lTotalQty4Storage			= tmp.TotalQty
		FROM @tblCountedDataInfo tmp
		WHERE	tmp.item_id = @item_id AND
				tmp.stor_id = @stor_id

		-- ---------------------------------------------------


		--SEGUNDO TENGO QUE VER.... EXISTE un registro en colecta? Tiene un ID?
		DECLARE	@lcoli_id	INT
		SET		@lcoli_id	= -1

		IF EXISTS (SELECT TOP 1 1
					FROM tbSaleOrderCollectItems		AS tsoci	WITH(NOLOCK)
					WHERE	tsoci.comp_id	= @comp_id	AND
							tsoci.col_id	= @col_id	AND
							tsoci.stor_id	= @stor_id	AND
							tsoci.item_id	= @item_id)
			BEGIN
				SELECT
					@lcoli_id = tsoci.coli_id
					FROM tbSaleOrderCollectItems		AS tsoci	WITH(NOLOCK)
					WHERE	tsoci.comp_id	= @comp_id	AND
							tsoci.col_id	= @col_id	AND
							tsoci.stor_id	= @stor_id	AND
							tsoci.item_id	= @item_id
			END

			IF @lcoli_id = -1
			BEGIN
				IF @lQtyCounted4Storage + @qty <= @lTotalQty4Storage
					BEGIN
						-- --------------------------------
						-- STL26032024
						-- SI PASA UNA CANTIDAD NEGATIVA Y EL RESULTADO ES MENOR QUE CERO, LE PONGO 0
						-- --------------------------------
						IF @lQtyCounted4Storage + @qty < 0
							SET @qty = 0
						-- --------------------------------

						INSERT INTO tbSaleOrderCollectItems
						(
							comp_id,
							col_id,
							-- coli_id -- this column value is auto-generated
							stor_id,
							item_id,
							coli_qty,
							[user_id]
						)
						VALUES
						(
							@comp_id,
							@col_id,
							@stor_id,
							@item_id,
							@qty,
							@user_id
						)
						SELECT 'True' [WasQtyUpdated]
					END
				ELSE
					BEGIN
						SELECT 'False' [WasQtyUpdated]
					END
			END
		ELSE
			BEGIN
				-- ---------------------------------------------------
				-- ACA VALIDO SI LO QUE QUIERO SUMAR PARA EL DEPOSITO
				-- ACTUAL ES POSIBLE O NO
				-- SI SE PASA O YA ESTA TODO CONTADO
				-- ---------------------------------------------------
				IF @lQtyCounted4Storage + @qty <= @lTotalQty4Storage
					BEGIN
						-- --------------------------------
						-- STL26032024
						-- SI PASA UNA CANTIDAD NEGATIVA Y EL RESULTADO ES MENOR QUE CERO, LE PONGO 0
						-- --------------------------------
						IF @lQtyCounted4Storage + @qty < 0
							SET @qty = 0
						-- --------------------------------

						UPDATE tbSaleOrderCollectItems
						SET
							coli_qty	= coli_qty + @qty
						WHERE	comp_id = @comp_id	AND
								coli_id = @lcoli_id
						SELECT 'True' [WasQtyUpdated]
					END
				ELSE
					BEGIN
						SELECT 'False' [WasQtyUpdated]
					END
		END
	END
GO







