CREATE PROCEDURE [dbo].[spSaleOrderConfirm_GetDataforProduction]
(
	@comp_id			INT,
	@bra_id				INT,
	@soh_id				INT,
	@sod_id				INT,
	@order				INT,
	@guid				uniqueidentifier
)
AS

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


SET NOCOUNT ON

BEGIN

--------------------------------------------------------------------------------
-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
--------------------------------------------------------------------------------
/*
DECLARE     @comp_id			INT,
			@guid				uniqueidentifier


SELECT		@comp_id			=1,
			@guid				='8c3f852b-de5d-4958-8388-bf990dfcac6e'
*/
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------

	SELECT	' '												[ ],
			ISNULL(tis.is_serial,'')						[is_serial],
			ti.item_desc									[Item_desc],
			tsosp.is_id										[ID]

	FROM    tbSaleOrderSerial4Production				tsosp		WITH (NOLOCK)

			INNER JOIN tbSaleOrderHeader				tsoh		WITH (NOLOCK)
				ON  tsoh.comp_id	= tsosp.comp_id
				AND tsoh.bra_id		= tsosp.bra_id
				AND tsoh.soh_id		= tsosp.soh_id

			INNER JOIN tbItemSerials					tis			WITH (NOLOCK)
				ON  tis.comp_id		= tsosp.comp_id	AND 	-- MOS 12-2021, estaba sin esto no se por que...  lo volví a poner
					tis.is_id		= tsosp.is_id

			INNER JOIN tbItem							ti			WITH (NOLOCK)
				ON	ti.comp_id		= tis.comp_id
				AND ti.item_id		= tis.item_id

	WHERE   tsosp.comp_id		= @comp_id		AND
			tsosp.bra_id		= @bra_id		AND
			tsosp.soh_id		= @soh_id		AND
			tsosp.sod_id		= @sod_id		AND
			tsosp.sosp_order	= @order



END
GO








