-- Author:		GA.
-- Create date: 18/07/2011.
-- Ticket:		92.
-- Description:	Recuperar is_id verificando que sea para el pedido actual .
-- ====================================================================================

CREATE PROCEDURE [dbo].[spSaleOrderConfirm_GetDataItemSerial]
(
	@comp_id				INT,
	@soh_id					INT,
	@sod_id					INT,
	@is_serial				NVARCHAR(100),
	@guid					UNIQUEIDENTIFIER
)
AS
SET NOCOUNT ON

BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

--------------------------------------------------------------------------------
-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
--------------------------------------------------------------------------------
/*
DECLARE  		@comp_id				INT,
				@soh_id					INT,
				@sod_id					INT,
				@is_serial				NVARCHAR(100),
				@guid					UNIQUEIDENTIFIER
SELECT			@comp_id				=1,
				@soh_id					=5527,
				@sod_id					=81183,
				@is_serial				='N68SBM3S''11 62030R13103531',
				@guid					='d183211f-778a-4f60-aee0-1e0eabb7bad2'
*/
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------



	DECLARE @cant		INT,
			@item_id	INT,
			@bra_id		int



	select	@bra_id = bra_id

	from	tbSaleOrderDetail

	where	comp_id = @comp_id
	and		soh_id	= @soh_id
	and		sod_id	= @sod_id



	SELECT	@item_id		= 	tis.item_id

	FROM	tbItemSerials	tis		WITH (NOLOCK)

	WHERE	tis.comp_id		= @comp_id
	AND		tis.is_serial	= @is_serial





	-- si la cantidad necesaria para componer el artículo padre del que se intenta cargar es mayor que la cantidad
	-- ya cargada se permite la carga
	IF	(	SELECT	CONVERT(INT,tic.icomp_qty)
				FROM	tbSaleOrderDetail				tsod		WITH (NOLOCK)
				INNER JOIN tbItemComposition	tic		WITH (NOLOCK)
					ON	tic.comp_id		= tsod.comp_id
					AND tic.item_id		= tsod.item_id
					AND tic.item_id_1	= @item_id
			WHERE	tsod.comp_id	= @comp_id
			AND		tsod.soh_id		= @soh_id
			AND		tsod.sod_id		= @sod_id			) > (	SELECT	ISNULL(COUNT(*),0)

																FROM	tbSaleOrderSerial4Production	tsosp		WITH (NOLOCK)

																		INNER JOIN tbItemSerials		tis		WITH (NOLOCK)
																		ON	tis.comp_id		= tsosp.comp_id
																		AND tis.is_id		= tsosp.is_id

																WHERE	tsosp.comp_id		= @comp_id
																AND		tsosp.sosp_guid		= @guid
																AND		tis.item_id			= @item_id	)
	BEGIN


			SELECT	tis.is_id

			FROM    tbItemSerials							tis		WITH (NOLOCK)

					INNER JOIN tbSaleOrderSerials			tsos		WITH (NOLOCK)
					ON  tsos.comp_id	= tis.comp_id
					AND tsos.is_id		= tis.is_id


			WHERE   tis. comp_id	= @comp_id
			AND 	tsos.soh_id		= @soh_id
			AND		tsos.bra_id		= @bra_id
			AND 	tis.is_serial	= @is_serial


			-- evita que se cargue 2 veces el mismo serial en alguna producción simultánea
			AND		tis.is_id NOT IN (	SELECT	tsosp.is_id
			   							FROM	tbSaleOrderSerial4Production	tsosp		WITH (NOLOCK)
			   							WHERE	tsosp.comp_id	= @comp_id
										AND		tsosp.sosp_guid = @guid)

			-- evita que se cargue 2 veces el mismo serial en la misma producción
			AND		tis.is_id NOT IN (	SELECT	tisp.is_idPart
			   		                  	FROM	tbItemSerials4Production		tisp		WITH (NOLOCK)
			   		                  	WHERE	tisp.comp_id	= @comp_id
			 		                  	AND		tisp.soh_id		= @soh_id	)

	END


END
GO







