-- Author:		GA.
-- Create date: 15/07/2011.
-- Ticket:		92.
-- Description:	Alta en la tabla tbSaleOrderSerial4Production
-- ====================================================================================



CREATE PROCEDURE [dbo].[spSaleOrderConfirm_InsertData]
(

	@comp_id			INT,
	@guid				uniqueidentifier,
	@is_id				INT,
	@soh_id				INT,
	@sod_id				INT,
	@number				INT,
	@bra_id				INT


)
AS
SET NOCOUNT ON





BEGIN


--------------------------------------------------------------------------------
-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
--------------------------------------------------------------------------------
/*
DECLARE     	@comp_id			INT,
				@guid				uniqueidentifier,
				@is_id				INT,
				@soh_id				INT,
				@sod_id				INT,
				@number				INT

SELECT			@comp_id			=1,
				@guid				='',
				@is_id				=1,
				@soh_id				=2,
				@sod_id				=3,
				@number				=1
*/
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------


	DECLARE @date	DATETIME
	SET 	@date = GETDATE()


	-- Si no se tomo ese serial para ese pedido
	IF NOT EXISTS(
					SELECT 1
					FROM tbSaleOrderSerial4Production sop	WITH (NOLOCK)
					WHERE	sop.comp_id		= @comp_id	AND
							sop.bra_id		= @bra_id	AND
							sop.soh_id		= @soh_id	AND
							sop.sod_id		= @sod_id	AND
							sop.sosp_order	= @number	AND
							sop.is_id		= @is_id
				)

		BEGIN


			-- y no se uso para ningun otro pedido
			IF NOT EXISTS(
							SELECT 1
								FROM tbSaleOrderSerial4Production sod	WITH (NOLOCK)
								WHERE	sod.comp_id = @comp_id AND
										sod.is_id	= @is_id
							)

				BEGIN



					INSERT INTO tbSaleOrderSerial4Production	WITH (ROWLOCK)
					(
						comp_id,
						sosp_guid,
						is_id,
						soh_id,
						sod_id,
						sosp_order,
						sosp_isEditing,
						sosp_isEditingCD,
						bra_id
					)
					VALUES
					(
						@comp_id,
						@guid,
						@is_id,
						@soh_id,
						@sod_id,
						@number,
						'true',
						@date,
						@bra_id
					)

				END

		END

END
GO



