CREATE PROCEDURE [dbo].[spSaleOrderCreditCards_InsertData]
(
	@comp_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@bra_id				INT,
	@soh_id				INT,
	@cc_id				INT,
	@ccp_id				INT,
	@sohp_total			DECIMAL(19,5),
	@sohp_percentage	DECIMAL(19,5),
	@sohp_position		INT,
	@ct_transaction		INT,
	@return_value		INT OUTPUT
)
AS
	BEGIN
		SET NOCOUNT ON


		--SELECT	@bra_id = tsocct.bra_id,
		--		@soh_id	= tsocct.soh_id
		--	FROM tbSaleOrderCreditCardsTMP tsocct
		--	WHERE tsocct.tis_guid = @guid

		-- SI EL SOH_ID O EL CT_TRANSACTION VIENEN CON -1 LOS PONEMOS EN NULL
		-- -------------------------------------------------------------------
		DECLARE
			@lSOH_ID	INT,
			@lCT_TRANS	INT

			IF @soh_id = -1
				BEGIN
					SET @lSOH_ID = NULL
				END
			ELSE
				BEGIN
					SET @lSOH_ID = @soh_id
				END

			IF @ct_transaction = -1
				BEGIN
					SET @lCT_TRANS = NULL
				END
			ELSE
				BEGIN
					SET @lCT_TRANS = @ct_transaction
				END
		-- -------------------------------------------------------------------


		--SI EL CC_ID O EL CCP_ID SON -1 ENTONCES GRABAMOS EN NULL
		--ESTO ES PARA LOS REGISTROS DE ÓRDEN 7
		-- -------------------------------------------------------------------
		DECLARE
			@lCC_ID		INT,
			@lCCP_ID	INT

			IF @cc_id = -1
				BEGIN
					SET @lCC_ID = NULL
				END
			ELSE
				BEGIN
					SET @lCC_ID = @cc_id
				END

			IF @ccp_id = -1
				BEGIN
					SET @lCCP_ID = NULL
				END
			ELSE
				BEGIN
					SET @lCCP_ID = @ccp_id
				END
		-- -------------------------------------------------------------------




		INSERT INTO tbSaleOrderCreditCardsTMP	WITH (ROWLOCK)
		(
			comp_id,
			-- sohp_id -- this column value is auto-generated,
			tis_guid,
			bra_id,
			soh_id,
			cc_id,
			ccp_id,
			sohp_total,
			--sohp_percentage,
			sohp_position,
			ct_transaction
		)
		VALUES
		(
			@comp_id,
			@guid,
			@bra_id,
			@lSOH_ID,
			@lCC_ID,
			@lCCP_ID,
			@sohp_total,
			--@sohp_percentage,
			@sohp_position,
			@lCT_TRANS
		)

		SET @return_value = @@IDENTITY

	END


GO



CREATE PROCEDURE [dbo].[spSaleOrderCreditCardsTMP_GetAdvanceReceipt]
(
	@comp_id			INT,
	@bra_id				INT,
	@cust_id			INT,
	@ct_pointOfSale		INT,
	@ct_docNumber		NVARCHAR(50)
)
AS
	BEGIN
		SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	-- --------------------------------------------------------------------------
	-- Moneda de la sucursal
	-- --------------------------------------------------------------------------
	declare @bra_curr_id	INT

	select
		@bra_curr_id		=	tb.curr_id

		from	[tbBranch] tb			WITH (NOLOCK)
		where	tb.bra_id	= @bra_id
	-- --------------------------------------------------------------------------

	SET @ct_docNumber = dbo.fnStrAllTrim(@ct_docNumber)


		SELECT TOP 1

				dbo.fnGetExchange2( @comp_id,
									tct.ct_ABalance,
									tct.ct_ACurrency,
									@bra_curr_id,
									0,
									0,
									0,
									'FALSE')						[ct_ABalance],
				--tct.ct_ABalance					[ct_total],
				tct.ct_transaction									[ct_transaction],
				ISNULL(tct.ct_discountPlanCoeficient,1)				[ct_discountPlanCoeficient]

		FROM tbCommercialTransactions						AS tct		WITH (NOLOCK)

		INNER JOIN tbsysDocuments							AS td		WITH (NOLOCK)
		ON td.sd_id			= tct.sd_id


		WHERE	tct.comp_id					= @comp_id						AND
				tct.bra_id					= @bra_id						AND
				tct.cust_id					= @cust_id						AND
				(td.sd_id					= 6 OR td.sd_id = 13)			AND
				tct.ct_ABalance				> 0								AND
				tct.ct_pointOfSale			= @ct_pointOfSale				AND
				tct.ct_docNumber			= @ct_docNumber




	END
GO



