CREATE PROCEDURE [dbo].[spSaleOrderCreditCardsTMP_UpdateData]
(

	@comp_id							INT,
	@guid								UNIQUEIDENTIFIER,
	@bra_id								INT,

	@ccm_cardNumber						NVARCHAR(50),
	@ccm_cardEmissionDate				Date,
	@ccm_cardExpirationDate				Date,
	@ccm_customerDocumentNumber			NVARCHAR(50),
	@ccm_customerName					NVARCHAR(100),
	@ccm_AutorizationCode				NVARCHAR(50),
	@ccm_receiptNumber					NVARCHAR(50),
	@cmm_lote							NVARCHAR(50),
	@sohp_id							INT



)
AS
	BEGIN
		SET NOCOUNT ON

		UPDATE tbSaleOrderCreditCardsTMP
		SET

			ccm_cardNumber					= @ccm_cardNumber,
			ccm_cardEmissionDate			= @ccm_cardEmissionDate,
			ccm_cardExpirationDate			= @ccm_cardExpirationDate,
			ccm_customerDocumentNumber		= @ccm_customerDocumentNumber,
			ccm_customerName				= @ccm_customerName,
			ccm_AutorizationCode			= @ccm_AutorizationCode,
			ccm_receiptNumber				= @ccm_receiptNumber,
			cmm_lote						= @cmm_lote


		WHERE comp_id = @comp_id AND
			  sohp_id = @sohp_id

	END


GO



CREATE PROCEDURE [dbo].[spSaleOrderCreditCardsTMP_UpdateDataAdvanceReceipt]
(

	@comp_id							INT,
	@guid								UNIQUEIDENTIFIER,
	@bra_id								INT,

	@ct_transaction_Rc					INT,
	@AdvanceReceipt						NVARCHAR(50),  -- Recibo de Anticipo
	@sohp_id							INT



)
AS
	BEGIN
		SET NOCOUNT ON

		UPDATE tbSaleOrderCreditCardsTMP
		SET
			 ct_transaction_Rc	= @ct_transaction_Rc,
			 ccm_cardNumber		= @AdvanceReceipt     -- lo guardo en este campo ya que no se usa, para luego recuperarlo

		WHERE comp_id = @comp_id AND
			  sohp_id = @sohp_id

	END


GO






create procedure [dbo].[spSaleOrderDelivery_QueryPending]
(


	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@stor_id				INT,
	@datefrom				DATETIME,
	@dateto					DATETIME



)
as set NOCOUNT on

set dateformat 'ymd'



-- --------------------------------------------
-- Testing
-- --------------------------------------------
/*
	declare		@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@prof_id				INT,
				@user_id				INT,
				@stor_id				INT,
				@datefrom				DATETIME,
				@dateto					DATETIME

	select		@comp_id				= 1,
				@bra_id					= 1,
				@lang_id				= 2,
				@prof_id				= 1,
				@user_id				= 1,
				@stor_id				= -1,
				@datefrom				= '2012-01-01',
				@dateto					= '2013-12-31'
*/
-- --------------------------------------------


	select	titd.itd_deliveryDate,
			ti.item_code,
			ti.item_desc,
			tit.it_qty


	FROM tbItemTransactionsDelivery								titd


	INNER JOIN tbItemTransactions								tit
	ON	tit.comp_id			= titd.comp_id			AND
		tit.bra_id			= titd.bra_id			AND
		tit.ct_transaction	= titd.ct_transaction	AND
		tit.it_transaction	= titd.it_transaction

	INNER JOIN tbItem											ti
	ON	ti.comp_id			= tit.comp_id			AND
		ti.item_id			= tit.item_id



where	titd.comp_id				= @comp_id
and		titd.bra_id					= @bra_id
and		titd.itd_deliveryDate between @datefrom		and @dateto
and     (@stor_id				= -1	or titd.stor_id	= @stor_id)

GO



