-- wfmMercadoLibre_PrintLabels_ItemsData
-- 10/02/2020
-- Datos para mostrar en la etiqueta adicional de pedido mediante MLO_ID
-- desde (00796) Mercadolibre©: Gestionar y Procesar Ordenes
-----------------------------------------------------

CREATE PROCEDURE [dbo].[spSaleOrderDetail_ByMLO_ID]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@mlo_id				int
)
AS

	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------
		-- TESTING
		-- --------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@mlo_id				BIGINT
			SELECT
				@comp_id			= 1,
				@mlo_id				= 5755
		*/
		-- --------------------------------------

		SELECT
			tc.comp_MainDesc2									[comp_name],	-- NOMBRE DE LA EMPRESA
			tmls.mls_desc										[mls_desc],		-- NOMBRE DE LA TIENDA
			convert(decimal(19,0),tsod.sod_qty)					[qty],			-- CANTIDAD
			ti.item_code										[item_code],	-- CODIGO
			ti.item_desc										[item_desc]		-- DESCRIPCION

			FROM tbSaleOrderHeader								tsoh	WITH(NOLOCK)

			INNER JOIN tbSaleOrderDetail						tsod	WITH(NOLOCK)
			ON	tsod.comp_id		= tsoh.comp_id		AND
				tsod.bra_id			= tsoh.bra_id		AND
				tsod.soh_id			= tsoh.soh_id

			INNER JOIN tbItem									ti		WITH(NOLOCK)
			ON	ti.comp_id			= tsod.comp_id		AND
				ti.item_id			= tsod.item_id

			INNER JOIN tbCompany								tc		WITH(NOLOCK)
			ON  tc.comp_id		    = tsoh.comp_id

			INNER JOIN tbMercadoLibre_ordersHeader				tmloh	WITH(NOLOCK)
			ON	tmloh.comp_id		= tsoh.comp_id		AND
				tmloh.mlo_id		= tsoh.mlo_id

			INNER JOIN tbMercadoLibre_Stores					tmls	WITH(NOLOCK)
			ON	tmls.comp_id		= tmloh.comp_id		AND
				tmls.mls_id			= tmloh.mls_id


		WHERE	tsoh.comp_id		= @comp_id			AND
				tsoh.mlo_id			= @mlo_id



	END
GO



create PROCEDURE [dbo].[spSaleOrderDetail_DeleteSOPS]
(
	@comp_id			INT,
	@bra_id				INT,
	@soh_id				INT,
	@sod_id				INT,
	@sops_user_id		INT,
	@sops_lastUpdate	DATETIME



)
AS


BEGIN

SET NOCOUNT ON

set dateformat 'ymd'

---------------------------------------------------------------------------------------------------------------------------
--testing
---------------------------------------------------------------------------------------------------------------------------
/*

DECLARE
		@comp_id			INT,
		@bra_id				INT,
		@soh_id				INT,
		@sod_id				INT,
		@sops_id			INT,
		@sops_supp_id		INT,
		@sops_bra_id		INT,
		@sops_date			DATETIME,
