CREATE PROCEDURE [dbo].[spSaleOrderDetail_DivideOrder]

  (
  	  @comp_id			int,
  	  @bra_id			int,
  	  @soh_id 			int
  )

AS

BEGIN

	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOS
	-- Update Date	: 2010-09-30
	-- Parte		: 585
	-- Description	: Para que se pueda realizar la división de pedidos cuando el pedido tiene ítems serializables,
	--				  se modifican los inner join por left join en el select de validación
	-- =================================================================================================================


	-- ---------------------------------------------------------------
	-- ---------------------------------------------------------------
	/*
		Declare	@comp_id	INT,
  				@bra_id		INT,
  				@soh_id		INT
		Select	@comp_id	= 1,
  				@bra_id		= 1,
  				@soh_id		= 8050

		DROP TABLE #tmp_serialized
		DROP TABLE #tbSaleOrderDetail
	*/
	-- ---------------------------------------------------------------




	DECLARE @soh_id_new INT
	SET		@soh_id_new	= 0
	-- ----------------------------------------------------------------------------------------------
	-- ----------------------------------------------------------------------------------------------
	-- Paso 0 MOS:
	-- Chequear si hay que dividir el pedido o no
	-- **1 OJO, ver en paso 0
	-- ----------------------------------------------------------------------------------------------
	-- Verifica que tenga algun item que no este preparado
	IF NOT EXISTS	(
						SELECT TOP 1  1
							FROM   dbo.tbSaleOrderDetail				sod	WITH (NOLOCK)
							LEFT JOIN dbo.tbItem				it
								ON		it.comp_id	= sod.comp_id
									AND it.item_id	= sod.item_id

							/*
							* Jorge.
							-- Cambié el inner por el left,porque sino no joineaba
							-- los item de la detail con la temp no traía nada
								*/
							LEFT join dbo.tbSaleOrderDetailtmp	Sodt	WITH (NOLOCK)
								on		sodt.comp_id	= sod.comp_id
									and sodt.bra_id		= sod.bra_id
									and sodt.soh_id		= sod.soh_id
									and sodt.sod_id		= sod.sod_id

							WHERE 	sod.comp_id			= @comp_id
								AND sod.bra_id			= @bra_id
								AND sod.soh_id			= @soh_id
								AND	isnull(it.item_expser,'false')	= 'false'
								AND isnull(sod.sod_qty,0)  <>   isnull(sodt.sodt_qty,0)
					)
		AND
		-- Verifica que tenga algun item que si tome numeros de serie
		NOT EXISTS	(
					SELECT SUM(tsod.sod_qty) - count(tsos.is_id )
						FROM tbSaleOrderDetail				tsod	WITH (NOLOCK)
						INNER JOIN tbItem ti
							ON		ti.comp_id		= tsod.comp_id
								AND ti.item_id		= tsod.item_id
						LEFT JOIN tbSaleOrderSerials		tsos		WITH (NOLOCK)-- Parte : 585
							ON		tsos.comp_id	= tsod.comp_id
								AND tsos.bra_id		= tsod.bra_id
								AND tsos.soh_id		= tsod.soh_id
						LEFT JOIN tbItemSerials				tis			WITH (NOLOCK)-- Parte : 585
							ON		tis.comp_id		= tsos.comp_id
								AND tis.is_id		= tsos.is_id
						LEFT JOIN tbItem					ti2	WITH (NOLOCK)
							ON		ti2.comp_id		= tsos.comp_id
								AND ti2.item_id		= tis.item_id
						WHERE	tsod.comp_id		= @comp_id
							AND tsod.bra_id			= @bra_id
							AND tsod.soh_id			= @soh_id
							AND ti.item_expser      = 'True'		-- Parte : 585
						GROUP BY tsod.item_id,ti.item_id
						HAVING (SUM(tsod.sod_qty) - count(tsos.is_id )) > 0
					)

	BEGIN
		-- Si no existe nada para dividir, solo retorna.-
		SELECT @soh_id_new
		RETURN
	END
	-- ----------------------------------------------------------------------------------------------
	-- ----------------------------------------------------------------------------------------------



	DECLARE @intSops_id AS INT	= NULL
	SELECT TOP 1 @intSops_id	=  tt.sops_id
		FROM tbSaleOrderPendingReason tt		WITH (NOLOCK)
		WHERE	tt.comp_id				= @comp_id AND
				tt.sops_isDefaultReason = 'True'
		ORDER BY tt.sops_desc




	-- Paso 1.- generar un nuevo pedido insertando en saleorderheader con los datos del saleorderheader original

	--recuperar un nuevo número de pedido

	EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @soh_id_new OUTPUT
	--SELECT 1
	--generamos el nuevo pedido con el número obtenido a partir de los datos del pedido original
	INSERT INTO tbSaleOrderHeader
	(
		comp_id,
		bra_id,
		soh_id,
		soh_cd,
		soh_deliveryDate,
		soh_observation1,
		soh_observation2,
		soh_observation3,
		soh_observation4,
		soh_quotation,
		sm_id,
		cust_id,
		st_id,
		disc_id,
		dl_id,
		cb_id,
		soh_lastUpdate,
		soh_limitDate,
		tt_id,
		tt_class,
		soh_StatusOf,
		[user_id],
		soh_isEditing,
		soh_isEditingCd,
		df_id,
		soh_total,
		ssos_id,
		soh_ExchangeToCustomerCurrency,
		chp_id,
		soh_PL_df_Id,
		soh_CustomerCurrency,
		soh_WithCollection,
		soh_WithCollectionGUID,
		soh_discount,
		soh_loan,
		soh_packagesQty,
		soh_internalAnnotation,


		curr_id4Exchange,
		curr_idExchange,
		soh_ATotal,
		df_id4PL,
		somp_id,
		soh_FEIdNumber,
		soh_inCash,
		custf_id,
		cust_id_guarantor,
		ccp_id,
		soh_MLdeliveryLabel,
		soh_deliveryAddress,
		soh_MLQuestionsAndAnswers,
		soh_MLId,
		soh_MLGUIA,
		pro_id,
		aux_collectionInterest_lastCTTransaction,
		ws_cust_Id,
		ws_internalID,
		ws_paymentGateWayStatusID,
		ws_paymentGateWayReferenceID,
		ws_IPFrom,
		ws_st_id,
		ws_dl_id,
		soh_htmlNote,
		prli_id,
		stor_id,
		mlo_id
	)
	SELECT
		comp_id,
		bra_id,
		@soh_id_new,
		GETDATE(),
		soh_deliveryDate,
		soh_observation1,
		soh_observation2,
		soh_observation3,
		soh_observation4,
		soh_quotation,
		sm_id,
		cust_id,
		st_id,
		disc_id,
		dl_id,
		cb_id,
		soh_lastUpdate,
		soh_limitDate,
		tt_id,
		tt_class,
		soh_StatusOf,
		[user_id],
		soh_isEditing,
		soh_isEditingCd,
		df_id,
		soh_total,
		ssos_id,
		soh_ExchangeToCustomerCurrency,
		chp_id,
		soh_PL_df_Id,
		soh_CustomerCurrency,
		soh_WithCollection,
		soh_WithCollectionGUID,
		soh_discount,
