		curr_id4Exchange,
		curr_idExchange,
		soh_ATotal,
		df_id4PL,
		somp_id,
		soh_FEIdNumber,
		soh_inCash,
		custf_id,
		cust_id_guarantor,
		ccp_id,
		soh_MLdeliveryLabel,
		soh_deliveryAddress,
		soh_MLQuestionsAndAnswers,
		tsoh.soh_MLId,
		tsoh.soh_MLGUIA,
		pro_id,
		aux_collectionInterest_lastCTTransaction,
		ws_cust_Id,
		ws_internalID,
		ws_paymentGateWayStatusID,
		ws_paymentGateWayReferenceID,
		ws_IPFrom,
		ws_st_id,
		ws_dl_id,
		soh_htmlNote,
		prli_id,
		stor_id,
		mlo_id

	FROM	tbSaleOrderHeader tsoh

	WHERE	tsoh.comp_id	= @comp_id
	  AND	tsoh.bra_id		= @bra_id
	  AND	tsoh.soh_id		= @soh_id


	-- Paso 2. Generar los ítems del nuevo pedido a partir de los que NO están confirmados del pedido original

	SELECT tsod.sod_id,
		   tsod.item_id,
		   tsod.sod_qty,
		   0 [serialized]
		INTO #tbSaleOrderDetail
		FROM tbSaleOrderDetail tsod
		--INNER JOIN tbItem ti
		LEFT JOIN tbItem ti
			ON		ti.comp_id		 = tsod.comp_id
				AND ti.item_id		 = tsod.item_id
		WHERE tsod.comp_id   = @comp_id
		  AND tsod.bra_id    = @bra_id
		  AND tsod.soh_id	 = @soh_id
		  AND ti.item_expser = 'True'

		  --AND isnull(ti.item_expser,'False') = 'False'
		ORDER BY	tsod.item_id,
					tsod.sod_id
	--SELECT *  FROM #tbSaleOrderDetail


	-- Ahora recuperamos los items que están serializados
	SELECT it.item_id
		INTO	#tmp_serialized
		FROM  dbo.tbSaleOrderSerials	sose
		INNER JOIN dbo.tbItemSerials	its	WITH (NOLOCK)
  			ON 	its.is_id			= sose.is_id
		INNER JOIN dbo.tbItem			it	WITH (NOLOCK)
			ON		it.comp_id		= sose.comp_id
				AND it.item_id		= its.item_id
		WHERE sose.comp_id			= @comp_id
		  AND sose.bra_id			= @bra_id
		  AND sose.soh_id			= @soh_id


	DECLARE @litem_id int,
			@lqty_pending INT

	DECLARE cur_pendientes CURSOR FOR
		SELECT item_id
			FROM   #tmp_serialized
			ORDER BY item_id

	OPEN cur_pendientes
	FETCH cur_pendientes INTo @litem_id
	WHILE @@FETCH_STATUS = 0
	BEGIN

		DECLARE @i int
		SELECT  @i = min(tsod.sod_id)
			FROM	#tbSaleOrderDetail tsod
			WHERE	tsod.item_id	= @litem_id
				AND	tsod.serialized < tsod.sod_qty


		UPDATE 	#tbSaleOrderDetail
			SET serialized = serialized + 1
			WHERE sod_id = @i

		FETCH cur_pendientes INTo @litem_id
	END
	CLOSE cur_pendientes
	DEALLOCATE cur_pendientes

