					isnull(sod.sod_qty,0) - isnull(sodt.sodt_qty,0),
					isnull(sod.sod_qty,0) - isnull(sodt.sodt_qty,0),
					sod.prli_id,
					sod.sod_price,
					sod.stor_id,
					sod.sod_lastUpdate,
					sod.sod_isEditing,
					sod.sod_insertDate,
					sod.[user_id],
					sod.sod_quotation,
					sod.sod_isCredit,
					sod.sod_cost,
					sod.sod_costTax,
					sod.rmah_id,
					sod.rmad_id,
					sod.sod_note1,
					sod.sod_note2,
					sod.sod_itemDiscount,
