					sod.sod_packagesQty,
					sod.item_id_EW,
					sod.tis_idOfThisEW,
					sod.camp_id,
					sod.sdlmt_id,
					sod.sreas_id,
					sod.sod_loanNumberOfPays,
					sod.sod_loanDateOfFirstPay,
					sod.sod_loanDayOfMonthOfNextPays,
					sod.sod_itemDeliveryDate,
					sod.sod_idOfThisEW,
					sod.sod_isFromPCConfigCTRLId,
