						WHEN sod.sops_id IS NULL THEN	@intSops_id
						ELSE 							sod.sops_id
					END,
					sod.sod_id


			FROM   dbo.tbSaleOrderDetail				sod		WITH (NOLOCK)

					left JOIN dbo.tbItem				it		WITH (NOLOCK)
					ON	it.comp_id	= sod.comp_id
					AND it.item_id	= sod.item_id

					left JOIN dbo.tbSaleOrderDetailtmp	Sodt	WITH (NOLOCK)
					on	sodt.comp_id	= sod.comp_id
					and sodt.bra_id		= sod.bra_id
					and sodt.soh_id		= sod.soh_id
					and sodt.sod_id		= sod.sod_id


			WHERE 	sod.comp_id		= @comp_id
			AND 	sod.bra_id		= @bra_id
			AND 	sod.soh_id		= @soh_id
			AND 	isnull(it.item_expser,'false')  = 'False'
			AND		isnull(sod.sod_qty,0)  <>   isnull(sodt.sodt_qty,0)

