	BEGIN TRY
		INSERT INTO tbSaleOrderHeader_PurchaseOrderRelation
		(
			comp_id,
			so_bra_id,
			so_soh_id,
			so_sod_id,
			it_transaction,
			po_bra_id,
			po_poh_id,
			po_pod_id,
			posor_POReceived,
			tis_id
		)
		SELECT
			sor.comp_id,
			@bra_id,
			@soh_id_new,
			tsod.sod_id,	-- NUEVO sod Importado al nuevo pedido
			NULL,
			sor.po_bra_id,
			sor.po_poh_id,
			sor.po_pod_id,
			sor.posor_POReceived,
			NULL
			FROM tbSaleOrderHeader_PurchaseOrderRelation	AS sor	WITH (NOLOCK)
			INNER JOIN tbSaleOrderDetail					AS tsod	WITH (NOLOCK)	-- Relaciono con los items migrados al NUEVO pedido por el sod_id ANTERIOR que quedó mas arriba guardado en el campo sod_auxTMPValue
				ON	tsod.comp_id			= sor.comp_id	AND
					tsod.bra_id				= sor.so_bra_id AND
					tsod.soh_id				= @soh_id_new	AND
					tsod.sod_auxTMPValue	= sor.so_sod_id
			WHERE	sor.comp_id		= @comp_id		AND
					sor.so_bra_id	= @bra_id		AND
					sor.so_soh_id	= @soh_id

	END TRY
	BEGIN CATCH
	END CATCH
