	-- Paso 3. Eliminar los ítems NO confirmados del pedido original
	--actualizo el pedido original con la cantidad confirmada de los items q no necesitan serialización
	--bien
	/*
	update tbSaleOrderDetail

	SET sod_qty = isnull(sod.sod_qty,0) - isnull(sodt.sodt_qty,0)
	--SELECT isnull(sodt.sodt_qty,0) ,sod.sod_qty,isnull(sod.sod_qty,0) - isnull(sodt.sodt_qty,0) [resultado]
	FROM   dbo.tbSaleOrderDetail				sod

	INNER JOIN dbo.tbItem				it
	ON  it.comp_id	= sod.comp_id
	AND it.item_id	= sod.item_id

	left join dbo.tbSaleOrderDetailtmp	Sodt
	on	sodt.comp_id	= sod.comp_id
	and sodt.bra_id		= sod.bra_id
	and sodt.soh_id		= sod.soh_id
	and sodt.sod_id		= sod.sod_id

	WHERE 	sod.comp_id		= @comp_id
	AND 	sod.bra_id		= @bra_id
	AND 	sod.soh_id		= @soh_id
	AND 	it.item_expser  = 'false'
	AND     isnull(sod.sod_qty,0)  <>   isnull(sodt.sodt_qty,0)
	 */

	update tbSaleOrderDetail
		SET sod_qty = isnull(sodt.sodt_qty,0)
		FROM   dbo.tbSaleOrderDetail				sod
		LEFT JOIN dbo.tbItem				it			WITH (NOLOCK)
			ON		it.comp_id	= sod.comp_id
				AND it.item_id	= sod.item_id
		left join dbo.tbSaleOrderDetailtmp	Sodt		WITH (NOLOCK)
			on		sodt.comp_id	= sod.comp_id
				and sodt.bra_id		= sod.bra_id
				and sodt.soh_id		= sod.soh_id
				and sodt.sod_id		= sod.sod_id
		WHERE 	sod.comp_id		= @comp_id
			AND sod.bra_id		= @bra_id
			AND sod.soh_id		= @soh_id
			AND  isnull(it.item_expser,'false')  = 'false'
			AND    isnull(sod.sod_qty,0)  <>   isnull(sodt.sodt_qty,0)


	DELETE tbSaleOrderTaxes
		FROM tbSaleOrderTaxes tsot
		INNER JOIN tbSaleOrderDetail tsod
			ON		tsod.comp_id = tsot.comp_id
				AND tsod.bra_id = tsot.bra_id
				and tsod.soh_id = tsot.soh_id
				AND tsod.sod_id = tsot.sod_id
		WHERE	tsot.comp_id = @comp_id
			AND tsot.bra_id  = @bra_id
			AND tsot.soh_id  = @soh_id
			AND tsot.sod_id  = tsod.sod_id


	DELETE tbSaleOrderLoan
		FROM tbSaleOrderLoan tsot
		INNER JOIN tbSaleOrderDetail tsod
			ON		tsod.comp_id = tsot.comp_id
				AND tsod.bra_id = tsot.bra_id
				and tsod.soh_id = tsot.soh_id
				AND tsod.sod_id = tsot.sod_id
		WHERE	tsot.comp_id = @comp_id
			AND tsot.bra_id  = @bra_id
			AND tsot.soh_id  = @soh_id
			AND tsot.sod_id  = tsod.sod_id

	DELETE tbSaleOrderDetail
		WHERE 		comp_id		= @comp_id
			AND 	bra_id		= @bra_id
			AND 	soh_id		= @soh_id
			AND      isnull(sod_qty,0) 		= 0



	/*
	update tbSaleOrderDetailtmp
	 SET sodt_qty = isnull(sod.sod_qty,0)

	FROM   dbo.tbSaleOrderDetailtmp				Sodt
	inner join dbo.tbSaleOrderDetail	Sod
	on	sod.comp_id	= sodt.comp_id
	and sod.bra_id	= sodt.bra_id
	and sod.soh_id	= sodt.soh_id
	and sod.sod_id	= sodt.sod_id
	INNER JOIN dbo.tbItem				it
	ON  it.comp_id	= sod.comp_id
	AND it.item_id	= sod.item_id
	WHERE 	sodt.comp_id	= @comp_id
	AND 	sodt.bra_id		= @bra_id
	AND 	sodt.soh_id		= @soh_id
	AND     sodt.sodt_id    = Sod.sod_id
	AND 	it.item_expser  = 'false'
	--AND     isnull(sod.sod_qty,0)  <>
	--AND     isnull(sodt.sodt_qty,0)  >   0
	--SELECT *  FROM #tbSaleOrderDetail
	*/
	---------------------------------------------------------------------------------------------------
	---------------------------------------------------------------------------------------------------

	--borro items serializados..
	UPDATE tbSaleOrderDetail
		SET sod_qty = isnull(tsod2.[serialized],0)   --isnull(tsod2.sod_qty,0) - isnull(tsod2.[serialized],0)
		FROM   tbSaleOrderDetail tsod
		INNER JOIN #tbSaleOrderDetail tsod2
			ON		tsod2.sod_id  = tsod.sod_id
				AND tsod2.item_id = tsod.item_id
		WHERE tsod.comp_id	= @comp_id
		AND tsod.bra_id	= @bra_id
		AND tsod.soh_id	= @soh_id
		AND tsod.sod_id = tsod2.sod_id


		DELETE FROM tbSaleOrderDetail
		WHERE	comp_id	= @comp_id
		AND		bra_id	= @bra_id
		AND		soh_id	= @soh_id
		AND		sod_qty = 0

		DELETE FROM tbSaleOrderDetail
		WHERE	comp_id	= @comp_id
		AND		bra_id	= @bra_id
		AND		soh_id	= @soh_id_new
		AND		sod_qty = 0



		-- Header
		Update dbo.tbSaleOrderHeader	WITH (ROWLOCK)
			Set soh_isEditing = 'False'
			WHERE	comp_id			= @comp_id
			AND		bra_id			= @bra_id
			AND		soh_id			= @soh_id_new
			AND     soh_isEditing	= 'True'

		-- los Detalles
		Update dbo.tbSaleOrderDetail	WITH (ROWLOCK)
			Set sod_isEditing = 'False'
			WHERE	comp_id			= @comp_id
			AND		bra_id			= @bra_id
			AND		soh_id			= @soh_id_new
			AND     sod_isEditing	= 'True'




		-- ----------------------------------------------
		-- Recalcula valores del pedido 07-2022 MOS x GN
		-- ----------------------------------------------
		BEGIN TRY
			DECLARE @user_id AS INT
			SELECT  @user_id = tsoh.[user_id]
				FROM tbSaleOrderHeader AS tsoh		WITH (NOLOCK)
				WHERE	tsoh.comp_id	= @comp_id AND
						tsoh.bra_id		= @bra_id AND
						tsoh.soh_id		= @soh_id_new

			-- Recalcula Importes del NUEVO Pedido
			EXEC spSaleOrder_RecalculateTaxes
				@comp_id ,
				@bra_id,
				@soh_id_new,
				@user_id ,
				2

			-- Recalcula Importes del VIEJO Pedido
			EXEC spSaleOrder_RecalculateTaxes
				@comp_id ,
				@bra_id,
				@soh_id,
				@user_id ,
				2

		END TRY
		BEGIN CATCH
		END CATCH
		-- ----------------------------------------------




	SELECT @soh_id_new

END
GO


CREATE PROCEDURE [dbo].[spSaleOrderDetail_DivideOrderByDivisionConfiguration]

  (
  	  @comp_id				INT,
  	  @bra_id				INT,
  	  @soh_id 				INT,
  	  @user_id				INT,
  	  @prof_id				INT
  )

AS

BEGIN

	SET NOCOUNT ON
	-- =================================================================================================================
	-- Author		: MOS
	-- Update Date	: 2017-09
	-- Description	: Divide el pedido segun lo configurado en la tabla tbSaleOrderDivisionConfiguration
	--					Se llama despoues de cerrar la transaccion de dividir como pedido
	--					Se ejecuta SOLO UNA VEZ por cada item
	-- =================================================================================================================


	-- -----------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------
	/*
	DECLARE
		@comp_id				INT,
  		@bra_id				INT,
  		@soh_id 				INT,
  		@user_id				INT,
  		@prof_id				INT
	SELECT
		@comp_id			= 1,
  		@bra_id				= 1,
  		@soh_id 			= 34026,
  		@user_id			= 41,
  		@prof_id			= 1
	*/
	-- -----------------------------------------------------------------


	DECLARE @option AS INT
	SET		@option = 2
	DECLARE @tabSaleOrderCreated TABLE(	comp_id			INT,
										df_id_ori		INT,	-- todo lo que era de este df_id original
										df_id_dest		INT,	-- y va a este df_id destiny
										bra_id			INT,	-- debo ponerlo en esta sucursal
										soh_id			INT		-- y este pedido
									   )


	DECLARE @intDF_IdOriginal		AS INT
	DECLARE @intDF_IdDestiny		AS INT
	DECLARE @bitStockWDecimals		AS BIT
	DECLARE @intSOD_Id				AS INT
	DECLARE @intDivisionMethod		AS INT
	DECLARE @decDivisionPercentaje	AS DECIMAL(19,4)
	DECLARE @intBraIdDestiny		AS INT
	DECLARE @intSodi_Id				AS INT
	DECLARE @bitDoSomething			AS BIT
	DECLARE @sodi_divisionMethod_1_CostInMainSO AS BIT = 'False'		-- MOS 07-2023 x Fiesa ** wefn34987534wnkwefkln tocket 18340
	SET		@bitDoSomething			= 'False'

	DECLARE curDivideOrder CURSOR LOCAL FAST_FORWARD FOR
		SELECT
				tsod.sod_id,
				tsodc.df_id_origin,
				tsodc.df_id_destiny,
				tsodc.sodi_divisionMethod,
				tsodc.sodi_divisionPercentage,
				tdf.bra_id,
				tsodc.sodi_id,
				ISNULL(ti.item_withDecimal,'False'),
				ISNULL(tsodc.sodi_divisionMethod_1_CostInMainSO,'False')
		FROM	tbSaleOrderHeader						tsoh	WITH (NOLOCK)
		INNER JOIN tbSaleOrderDetail					tsod	WITH (NOLOCK)
			ON	tsod.comp_id			= tsoh.comp_id AND
				tsod.bra_id				= tsoh.bra_id AND
				tsod.soh_id				= tsoh.soh_id
			INNER JOIN tbSaleOrderDivisionConfiguration tsodc	WITH (NOLOCK)
				ON	tsodc.comp_id		= tsoh.comp_id		AND
					tsodc.st_id			= tsoh.st_id		AND
					tsodc.df_id_origin	= tsoh.df_id
			INNER JOIN tbDocumentsFile					tdf		WITH (NOLOCK)
				ON	tdf.comp_id			= tsodc.comp_id		AND
					tdf.df_id			= tsodc.df_id_destiny
			INNER JOIN tbBranch							tb		WITH (NOLOCK)
				ON	tb.comp_id			= tdf.comp_id		AND
					tb.bra_id			= tdf.bra_id
			LEFT JOIN tbItem							ti		WITH (NOLOCK)
				ON	ti.comp_id				= tsoh.comp_id	AND
					ti.item_id				= tsod.item_id
			WHERE	tsoh.comp_id			= @comp_id		AND
					tsoh.bra_id				= @bra_id		AND
					tsoh.soh_id				= @soh_id		AND
					tsod.sod_isDivided		= 'False'		AND
					tsodc.sodi_isDisabled	= 'False'		AND
					(
						(tsodc.sdlmt_id IS NULL		OR tsodc.sdlmt_id	= tsod.sdlmt_id)
							AND
						(tsodc.brand_id IS NULL		OR tsodc.brand_id	= ti.brand_id)
							AND
						(tsodc.cat_id	IS NULL		OR tsodc.cat_id		= ti.cat_id)
							AND
						(tsodc.subcat_id IS NULL	OR tsodc.subcat_id	= ti.subcat_id)
							AND
						(tsodc.subcataux_id IS NULL	OR tsodc.subcataux_id	= ti.subcataux_id)
							AND
						(tsodc.item_id	IS NULL		OR tsodc.item_id	= ti.item_id)
							AND
						(tsodc.stor_id	IS NULL		OR tsodc.stor_id	= tsod.stor_id)
							AND
						(tsodc.disc_id	IS NULL		OR tsodc.disc_id	= tsoh.disc_id)
							AND
						(tsodc.prli_id	IS NULL		OR tsodc.prli_id	= tsod.prli_id)
					)										AND
					(
						(tsodc.sodi_divideAtSave				= 'True'	AND @option = 2 AND tsoh.ssos_id <> 10 )
							OR
						(tsodc.sodi_divideAtSaveInCommercial	= 'True'	AND @option = 2 AND tsoh.ssos_id  = 10 )
							--OR
						    --(tsodc.sodi_divideAtEmmition			= 'True'	AND @option = 1 )
					)										--AND
				-- MOS 04-2022: Lo saque x SO
				--	tsodc.df_id_origin <> tsodc.df_id_destiny		-- Anti Forros
			ORDER BY	tsodc.sodi_order,
						tsod.sod_id


	OPEN			curDivideOrder

	FETCH NEXT FROM curDivideOrder INTO
		@intSOD_Id		,
		@intDF_IdOriginal,
		@intDF_IdDestiny,
		@intDivisionMethod,
		@decDivisionPercentaje,
		@intBraIdDestiny,
		@intSodi_Id ,
		@bitStockWDecimals,
		@sodi_divisionMethod_1_CostInMainSO



	-- MOS 04-2022
	-- Si se divide por Tipo de entrega, SI O SI debe haber mas de un tipo de entrega en los items del pedido, sino, no debe hacer nada.
	IF @intDivisionMethod = 4
		BEGIN
			IF (	SELECT COUNT(*)
					    FROM tbSaleOrderDetail AS tsoh
						WHERE	tsoh.comp_id		= @comp_id	AND
								tsoh.bra_id			= @bra_id	AND
								tsoh.soh_id			= @soh_id
					    GROUP BY tsoh.sdlmt_id
				) <= 1
			BEGIN
				RETURN
			END
		END







	DECLARE @intSOHIdDestiny INT

	WHILE @@FETCH_STATUS = 0
		BEGIN

			SET		@bitDoSomething			= 'True'

			SET		@intSOHIdDestiny = NULL
			SELECT	@intSOHIdDestiny = soh_id
				FROM @tabSaleOrderCreated
				WHERE	comp_id		= @comp_id AND
						df_id_ori	= @intDF_IdOriginal AND
						df_id_dest	= @intDF_IdDestiny


--==
--SELECT @comp_id,@intBraIdDestiny, @intDF_IdOriginal,@intDF_IdDestiny,@intSOHIdDestiny

			IF @intSOHIdDestiny IS NULL
				BEGIN

					EXEC dbo.spCounters_getNextValue @comp_id, @intBraIdDestiny, 2, @counter_value = @intSOHIdDestiny Output

--==
--SELECT @comp_id,@intBraIdDestiny, @intDF_IdOriginal,@intDF_IdDestiny,@intSOHIdDestiny

					-- INserta en esta tabla temporal para luego ir insertando nuevos details en la misma y poder recalcular abajo los totales de todos los pedidos generados.
					INSERT INTO @tabSaleOrderCreated
					(
						comp_id,
						df_id_ori,
						df_id_dest,
						bra_id,
						soh_id
					)
					VALUES
					(
						@comp_id,
						@intDF_IdOriginal,
						@intDF_IdDestiny,
						@intBraIdDestiny,
						@intSOHIdDestiny
					)

					INSERT INTO tbSaleOrderHeader
					(
						comp_id,
						bra_id,
						soh_id,
						soh_cd,
						soh_deliveryDate,
						soh_observation1,
						soh_observation2,
						soh_observation3,
						soh_observation4,
						soh_quotation,
						sm_id,
						cust_id,
						st_id,
						disc_id,
						dl_id,
						cb_id,
						soh_lastUpdate,
						soh_limitDate,
						tt_id,
						tt_class,
						soh_StatusOf,
						[user_id],
						soh_isEditing,
						soh_isEditingCd,
						df_id,
						soh_total,
						ssos_id,
						soh_ExchangeToCustomerCurrency,
						chp_id,
						soh_PL_df_Id,
						soh_CustomerCurrency,
						soh_WithCollection,
						soh_WithCollectionGUID,
						soh_discount,
						soh_loan,
						soh_packagesQty,
						soh_internalAnnotation,
						curr_id4Exchange,
						curr_idExchange,
						soh_ATotal,
						df_id4PL,
						somp_id,
						soh_FEIdNumber,
						soh_inCash,
						custf_id,
						cust_id_guarantor,
						ccp_id,
						soh_MLdeliveryLabel,
						soh_deliveryAddress,
						soh_MLQuestionsAndAnswers,
						aux_3RDSales_lastCTTransaction,
						soh_MLId,
						soh_MLGUIA,
						pro_id,
						aux_collectionInterest_lastCTTransaction,
						ws_cust_Id,
						ws_internalID,
						ws_paymentGateWayStatusID,
						ws_paymentGateWayReferenceID,
						ws_IPFrom,
						ws_st_id,
						ws_dl_id,
						soh_htmlNote,
						prli_id,
						stor_id,
						mlo_id
					)
					SELECT 
						tsoh.comp_id,
						@intBraIdDestiny,
						@intSOHIdDestiny,
						soh_cd,
						soh_deliveryDate,
						soh_observation1,
						soh_observation2,
						soh_observation3,
						soh_observation4,
						soh_quotation,
						sm_id,
						cust_id,
						st_id,
						disc_id,
						dl_id,
						cb_id,
						soh_lastUpdate,
						soh_limitDate,
						tt_id,
						tt_class,
						soh_StatusOf,
						[user_id],
						soh_isEditing,
						soh_isEditingCd,
						@intDF_IdDestiny,
						soh_total,
						ssos_id,
						soh_ExchangeToCustomerCurrency,
						chp_id,
						soh_PL_df_Id,
						soh_CustomerCurrency,
						soh_WithCollection,
						soh_WithCollectionGUID,
						soh_discount,
						soh_loan,
						soh_packagesQty,
						soh_internalAnnotation,
						curr_id4Exchange,
						curr_idExchange,
						soh_ATotal,
						tdfDestiny.df_SaleOrderPL_df_Id,
						somp_id,
						soh_FEIdNumber,
						soh_inCash,
						custf_id,
						cust_id_guarantor,
						ccp_id,
						soh_MLdeliveryLabel,
						soh_deliveryAddress,
						soh_MLQuestionsAndAnswers,
						aux_3RDSales_lastCTTransaction,
						soh_MLId,
						soh_MLGUIA,
						pro_id,
						aux_collectionInterest_lastCTTransaction,
						ws_cust_Id,
						ws_internalID,
						ws_paymentGateWayStatusID,
						ws_paymentGateWayReferenceID,
						ws_IPFrom,
						ws_st_id,
						ws_dl_id,
						soh_htmlNote,
						prli_id,
						CASE
							WHEN tdfDestiny.stor_id IS NOT NULL THEN tdfDestiny.stor_id
							ELSE									 tsoh.stor_id
						END,
						mlo_id
					FROM tbSaleOrderHeader		tsoh				WITH (NOLOCK)
					INNER JOIN tbDocumentsFile	tdfDestiny			WITH (NOLOCK)
						ON	tdfDestiny.comp_id	= @comp_id AND
							tdfDestiny.df_id	= @intDF_IdDestiny
					WHERE	tsoh.comp_id		= @comp_id	AND
							tsoh.bra_id			= @bra_id	AND
							tsoh.soh_id			= @soh_id


				END




				INSERT INTO tbSaleOrderDetail
				(
					comp_id,
					bra_id,
					soh_id,
					-- sod_id -- this column value is auto-generated,
					sod_priority,
					item_id,
					sod_itemDesc,
					sod_detail,
					curr_id,
					sod_initQty,
					sod_qty,
					prli_id,
					sod_price,
					stor_id,
					sod_lastUpdate,
					sod_isEditing,
					sod_insertDate,
					[user_id],
					sod_quotation,
					sod_isCredit,
					sod_cost,
					sod_costTax,
					rmah_id,
					rmad_id,
					sod_note1,
					sod_note2,
					sod_itemDiscount,
					sod_tis_id_origin,
					sod_item_id_origin,
					sod_isParentAssociate,
					is_id,
					it_transaction,
					sod_isMade,
					sod_expirationDate,
					acc_count_id,
					sod_packagesQty,
					item_id_EW,
					tis_idOfThisEW,
					camp_id,
					sdlmt_id,
					sreas_id,
					sod_loanNumberOfPays,
					sod_loanDateOfFirstPay,
					sod_loanDayOfMonthOfNextPays,
					sod_itemDeliveryDate,
					sod_idOfThisEW,
					sod_isFromPCConfigCTRLId,
					sod_EWAddress,
					sod_PCCOnfigIsTransfered2Branch,
					sod_MLCost,
					sod_itemAssociationCoeficient,
					ws_price,
					ws_curr_Id,
					sops_id,
					mlo_id,
					sops_supp_id,
					sops_bra_id,
					sops_date,
					sod_MECost,
					sod_MPCost,
					sod_isDivided,
					sod_isDivided_Date,
					user_id_division,
					sodi_id,
					sod_isDivided_costCoeficient
				)
				SELECT
					tsod.comp_id,
					@intBraIdDestiny,
					@intSOHIdDestiny,
					-- sod_id -- this column value is auto-generated,
					tsod.sod_priority,
					CASE
						WHEN @intDivisionMethod = 1 THEN	NULL
						ELSE								tsod.item_id
					END,
					tsod.sod_itemDesc,
					tsod.sod_detail,
					tsod.curr_id,
					tsod.sod_initQty,
					CASE
						WHEN @intDivisionMethod = 2 AND @bitStockWDecimals = 'False' THEN ROUND(tsod.sod_qty * (1-(@decDivisionPercentaje / 100)),0)
						WHEN @intDivisionMethod = 2 AND @bitStockWDecimals = 'True'  THEN		tsod.sod_qty * (1-(@decDivisionPercentaje / 100))
						ELSE																	tsod.sod_qty
					END,
					tsod.prli_id,
					CASE
						WHEN @intDivisionMethod = 1 THEN tsod.sod_price * (1-(@decDivisionPercentaje / 100))
						ELSE							 tsod.sod_price
					END,
					CASE
						WHEN tdfDestiny.stor_id IS NOT NULL THEN tdfDestiny.stor_id
						ELSE									 tsod.stor_id
					END,
					tsod.sod_lastUpdate,
					tsod.sod_isEditing,
					tsod.sod_insertDate,
					tsod.[user_id],
					tsod.sod_quotation,
					tsod.sod_isCredit,
					CASE
						WHEN @intDivisionMethod = 1 THEN	dbo.fnGetExchange2(tsod.comp_id,ticl.coslis_price, ticl.curr_id, tsod.curr_id, 0, 0, 0, 'False')
						ELSE								tsod.sod_cost
					END,
					CASE
						WHEN @intDivisionMethod = 1 THEN	(SELECT TOP 1 1
						                                		FROM	vwItemTaxesOnlyOneIvaTax vit	WITH (NOLOCK)
						                                		WHERE	vit.comp_id = tsod.comp_id AND
						                                				vit.item_id = tsod.item_id )
						ELSE								tsod.sod_costTax
					END,
					tsod.rmah_id,
					tsod.rmad_id,
					tsod.sod_note1,
					tsod.sod_note2,
					tsod.sod_itemDiscount,
					tsod.sod_tis_id_origin,
					tsod.sod_item_id_origin,
					tsod.sod_isParentAssociate,
					tsod.is_id,
					tsod.it_transaction,
					tsod.sod_isMade,
					tsod.sod_expirationDate,
					tsod.acc_count_id,
					tsod.sod_packagesQty,
					tsod.item_id_EW,
					tsod.tis_idOfThisEW,
					tsod.camp_id,
					tsod.sdlmt_id,
					tsod.sreas_id,
					tsod.sod_loanNumberOfPays,
					tsod.sod_loanDateOfFirstPay,
					tsod.sod_loanDayOfMonthOfNextPays,
					tsod.sod_itemDeliveryDate,
					tsod.sod_idOfThisEW,
					tsod.sod_isFromPCConfigCTRLId,
					tsod.sod_EWAddress,
					tsod.sod_PCCOnfigIsTransfered2Branch,
					tsod.sod_MLCost,
					tsod.sod_itemAssociationCoeficient,
					tsod.ws_price,
					tsod.ws_curr_Id,
					tsod.sops_id,
					tsod.mlo_id,
					tsod.sops_supp_id,
					tsod.sops_bra_id,
					tsod.sops_date,
					tsod.sod_MECost,
					tsod.sod_MPCost,
					'True' /*sod_isDivided*/,
					getdate() /*sod_isDivided_Date*/,
					@user_id /*user_id_division*/,
					@intSodi_Id ,
					CASE
						WHEN @intDivisionMethod = 1 AND @sodi_divisionMethod_1_CostInMainSO = 'True'	THEN 0.001
						WHEN @intDivisionMethod = 1														THEN 1-(@decDivisionPercentaje / 100) -- Se guarda como Coeficiente solo si es por PRECIO
						ELSE																				 1
					END
				FROM tbSaleOrderDetail		tsod			WITH (NOLOCK)
				INNER JOIN tbDocumentsFile	tdfDestiny		WITH (NOLOCK)
					ON	tdfDestiny.comp_id	= @comp_id	AND
						tdfDestiny.df_id	= @intDF_IdDestiny
				INNER JOIN tbBranch			tb				WITH (NOLOCK)
					ON	tb.comp_id		= tsod.comp_id	AND
						tb.bra_id		= tsod.bra_id
				LEFT JOIN tbItemCostList	ticl			WITH (NOLOCK)
					ON	ticl.comp_id    = tb.comp_id	AND
						ticl.coslis_id	= tb.coslis_id	AND
						ticl.item_id	= tsod.item_id
				WHERE	tsod.comp_id	= @comp_id	AND
						tsod.bra_id		= @bra_id	AND
						tsod.soh_id		= @soh_id	AND
						tsod.sod_id		= @intSOD_Id


				-- MOS 03-2022 para los &%$&%$ de SO, que puedan dividir por el POUTO tipo de Entrega
				IF @intDivisionMethod = 4	-- si divide x tipo de entrega debe BORRAR del pedido original los items
					BEGIN

						DELETE FROM tbSaleOrderTaxes
							WHERE	comp_id		= @comp_id	AND
									bra_id		= @bra_id	AND
									soh_id		= @soh_id	AND
									sod_id		= @intSOD_Id

						DELETE FROM tbSaleOrderAssemblyTurns
							WHERE	comp_id		= @comp_id	AND
									soh_bra_id	= @bra_id	AND
									soh_id		= @soh_id	AND
									sod_id		= @intSOD_Id

						DELETE FROM tbsaleorderdetail
							WHERE	comp_id		= @comp_id	AND
									bra_id		= @bra_id	AND
									soh_id		= @soh_id	AND
									sod_id		= @intSOD_Id

					END
				ELSE
					BEGIN
						-- Actualizo el Pedido Original
						UPDATE tbSaleOrderDetail					WITH (ROWLOCK)
							SET
							sod_qty							=
							CASE
								WHEN @intDivisionMethod = 2 AND @bitStockWDecimals = 'False'  THEN ROUND(sod_qty	* (@decDivisionPercentaje / 100),0)
								WHEN @intDivisionMethod = 2 AND @bitStockWDecimals = 'True'	  THEN       sod_qty	* (@decDivisionPercentaje / 100)
								ELSE																	 sod_qty
							END,
							sod_price						=
							CASE
								WHEN @intDivisionMethod = 1 THEN sod_price	* (@decDivisionPercentaje / 100)
								ELSE							 sod_price
							END,
							sod_isDivided					= 'True',
							sod_isDivided_Date				= getdate(),
							sodi_id							= @intSodi_Id,
							user_id_division				= @user_id ,
							sod_isDivided_costCoeficient	=	CASE
																	WHEN @intDivisionMethod = 1 AND @sodi_divisionMethod_1_CostInMainSO = 'True'	THEN 99.999
																	WHEN @intDivisionMethod = 1 THEN @decDivisionPercentaje / 100 -- Se guarda como Coeficiente solo si es por PRECIO
																	ELSE							   1
																END
							WHERE	comp_id		= @comp_id	AND
									bra_id		= @bra_id	AND
									soh_id		= @soh_id	AND
									sod_id		= @intSOD_Id
					END




				FETCH NEXT FROM curDivideOrder INTO
					@intSOD_Id		,
					@intDF_IdOriginal,
					@intDF_IdDestiny,
					@intDivisionMethod,
					@decDivisionPercentaje,
					@intBraIdDestiny,
					@intSodi_Id ,
					@bitStockWDecimals	,
					@sodi_divisionMethod_1_CostInMainSO
		END


	CLOSE		curDivideOrder
	DEALLOCATE	curDivideOrder


	-- --------------------------------------------------------
	-- Hace recalculo de Totales de todos los pedidos generados
	-- --------------------------------------------------------
	IF @bitDoSomething = 'True'
		BEGIN


			EXEC spSaleOrder_RecalculateTaxes @comp_id, @bra_id, @soh_id, @user_id, 2

			DECLARE curRecalculo CURSOR LOCAL FAST_FORWARD FOR
				SELECT tsoc.bra_id, tsoc.soh_id
					FROM @tabSaleOrderCreated tsoc

			OPEN		curRecalculo
			FETCH NEXT
				FROM	curRecalculo INTO
				@intBraIdDestiny,
				@intSOHIdDestiny
			WHILE @@FETCH_STATUS = 0
				BEGIN

					EXEC spSaleOrder_RecalculateTaxes @comp_id, @intBraIdDestiny, @intSOHIdDestiny, @user_id, 2

					FETCH NEXT
						FROM	curRecalculo INTO
						@intBraIdDestiny,
						@intSOHIdDestiny

				END
			CLOSE		curRecalculo
			DEALLOCATE	curRecalculo
		END
	-- --------------------------------------------------------




	SELECT 	@bitDoSomething

END
GO




CREATE  PROCEDURE [dbo].[spSaleOrderDetail_divideSaleOrderbySOD_Id]

  (
  	  @comp_id			int,
  	  @bra_id			int,
  	  @soh_id 			INT,
  	  @sod_id			INT,
  	  @decNewQTY		DECIMAL(19,4),
  	  @sod_IDNew     AS INT OUTPUT
  )

AS

BEGIN

SET NOCOUNT ON
-- =================================================================================================================
-- Author		: MOS
-- Update Date	: 08-2022  **lwqhf973249%&$#%$#%lkjnlkh  CM y LRCDTPM!
-- =================================================================================================================


-- --------------------------------------------------------------------------------
-- TEST
-- --------------------------------------------------------------------------------
/*
	Declare	@comp_id	INT,
  			@bra_id		INT,
  			@soh_id		INT,
  			@sod_id		int = 3333
	Select	@comp_id	= 1,
  			@bra_id		= 1,
  			@soh_id		= 8050

	DROP TABLE #tmp_serialized
	DROP TABLE #tbSaleOrderDetail
*/
-- --------------------------------------------------------------------------------




	DECLARE @decActualQTY AS DECIMAL(19,4) = 0

	SELECT  @decActualQTY = sod.sod_qty
		FROM   dbo.tbSaleOrderDetail		sod	WITH (NOLOCK)
		WHERE 	sod.comp_id		= @comp_id
			AND sod.bra_id		= @bra_id
			AND sod.soh_id		= @soh_id
			AND sod.sod_id		= @sod_id


	IF @decActualQTY <= @decNewQTY
		BEGIN
			RETURN
		END





	-- INserta el nuevo item dividido con la cantidad arriba informada
	INSERT INTO tbSaleOrderDetail
		(
			comp_id,
			bra_id,
			soh_id,
			sod_priority,
			item_id,
			sod_itemDesc,
			sod_detail,
			curr_id,
			sod_initQty,
