			sod_isCredit,
			sod_cost,
			sod_costTax,
			rmah_id,
			rmad_id,
			sod_note1,
			sod_note2,
			sod_itemDiscount,
			sod_tis_id_origin,
			sod_item_id_origin,
			sod_isParentAssociate,
			is_id,
			it_transaction,
			sod_isMade,
			sod_expirationDate,
			acc_count_id,
			sod_packagesQty,
			item_id_EW,
			tis_idOfThisEW,
			camp_id,
			sdlmt_id,
			sreas_id,
			sod_loanNumberOfPays,
			sod_loanDateOfFirstPay,
			sod_loanDayOfMonthOfNextPays,
			sod_itemDeliveryDate,
			sod_idOfThisEW,
			sod_isFromPCConfigCTRLId,
			sod_EWAddress,
			sod_PCCOnfigIsTransfered2Branch,
			sod_MLCost,
			sod_itemAssociationCoeficient,
			ws_price,
			ws_curr_Id,
			mlo_id,
			sops_supp_id,
			sops_bra_id,
			sops_date,
			sod_MECost,
			sod_MPCost,
			sod_isDivided,
			sod_isDivided_Date,
			user_id_division,
			sodi_id,
			sod_isDivided_costCoeficient,
			sod_DeliveryCharge,
			sops_poh_bra_id,
			sops_poh_id,
			sops_note,
			sops_user_id,
			sops_lastUpdate,
			sops_id,ct_transaction_SelectFromPacking, sodt_qty,
			sod_disablePrintInEmmition, sod_discountByItem, sod_discountByTotal,
			sod_creditInt, sod_creditIntPlus, sod_priceNeto, sod_comboCoeficient,
			sod_montlyPaymentFrom, sod_montlyPaymentTo, wscup_id,
			sod_canDeleteCOMBOInSO, sod_exclude4AvailableStock, sod_discountPlan,
			tax_id4IVA, sod_pending4pod_IdRelation,
			sod_MercadoLibre_MustUpdateStock
		)
			SELECT  @comp_id,
					@bra_id,
					@soh_id,
					sod.sod_priority,
					sod.item_id,
					sod.sod_itemDesc,
					sod.sod_detail,
					sod.curr_id,
					@decNewQTY,   --@decActualQTY - @decNewQTY,
					@decNewQTY,	  --@decActualQTY - @decNewQTY,
					sod.prli_id,
					sod.sod_price,
					sod.stor_id,
					sod.sod_lastUpdate,
					sod.sod_isEditing,
					sod.sod_insertDate,
					sod.[user_id],
					sod.sod_quotation,
					sod.sod_isCredit,
					sod.sod_cost,
					sod.sod_costTax,
					sod.rmah_id,
					sod.rmad_id,
					sod.sod_note1,
					sod.sod_note2,
					sod.sod_itemDiscount,
					sod.sod_tis_id_origin,
					sod.sod_item_id_origin,
					sod.sod_isParentAssociate,
					sod.is_id,
					sod.it_transaction,
					sod.sod_isMade,
					sod.sod_expirationDate,
					sod.acc_count_id,
					sod.sod_packagesQty,
					sod.item_id_EW,
					sod.tis_idOfThisEW,
					sod.camp_id,
					sod.sdlmt_id,
					sod.sreas_id,
					sod.sod_loanNumberOfPays,
