					sod.sod_MLCost,
					sod.sod_itemAssociationCoeficient,
					sod.ws_price,
					sod.ws_curr_Id,
					sod.mlo_id,
					sod.sops_supp_id,
					sod.sops_bra_id,
					GETDATE(),
					sod.sod_MECost,
					sod.sod_MPCost,
					sod.sod_isDivided,
					sod.sod_isDivided_Date,
					sod.user_id_division,
					sod.sodi_id,
					sod.sod_isDivided_costCoeficient,
