					sod.sops_id,
					ct_transaction_SelectFromPacking, sodt_qty,
					sod_disablePrintInEmmition, sod_discountByItem, sod_discountByTotal,
					sod_creditInt, sod_creditIntPlus, sod_priceNeto, sod_comboCoeficient,
					sod_montlyPaymentFrom, sod_montlyPaymentTo, wscup_id,
					sod_canDeleteCOMBOInSO, sod_exclude4AvailableStock, sod_discountPlan,
					tax_id4IVA, sod_pending4pod_IdRelation,
					sod_MercadoLibre_MustUpdateStock
			FROM   dbo.tbSaleOrderDetail				sod		WITH (NOLOCK)
			WHERE 	sod.comp_id		= @comp_id
			AND 	sod.bra_id		= @bra_id
			AND 	sod.soh_id		= @soh_id
			AND 	sod.sod_id		= @sod_id

		SET @sod_IDNew = @@IDENTITY
	-----------------------------------------------------------------------------------



	-- Deja el ORIGINAL con la cantidad menos la dividida
	update tbSaleOrderDetail
		SET sod_qty = @decActualQTY - @decNewQTY --@decNewQTY
		FROM   dbo.tbSaleOrderDetail				sod
		WHERE 	sod.comp_id		= @comp_id
