CREATE PROCEDURE [dbo].[spSaleOrderDetail_GetData4PendingStatus]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@soh_bra_id			INT,
	@soh_id				INT
)
AS

	SET NOCOUNT ON

	BEGIN


		-------------------------------------------
		----testing
		-------------------------------------------
		/*
		DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@soh_bra_id			INT,
			@soh_id				INT
		SELECT
			@comp_id	= 1,
			@soh_bra_id	= 1 ,
			@soh_id		= 33867
*/
		-------------------------------------------
		-------------------------------------------


		SELECT
			''														[ ],
			ti.item_desc											[Item_desc],		-- Item del Pedido
			isnull(tsops.sops_desc,'')								[status],			-- Motivo
			tsod.sops_date											[ct_date],			-- Fecha del Motivo
			isnull(sopsbra.bra_desc,'')								[bra_desc],			-- Sucursal del Motivo
			isnull(sopsts.supp_name,'')								[supp_name],		-- Proveedor del Motivo
			tsod.sops_poh_bra_id									[sops_poh_bra_id],	-- OC del motivo
			tsod.sops_poh_id										[sops_poh_id],		-- Nº de OC del motivo
			IsNull(tsod.sops_note,'')								[sops_note],		-- Nota del motivo
			tu.user_lastname + ', ' + tu.user_firstname				[sops_user_name],	-- Usuario de ultima modificacion
			tsod.sops_lastUpdate									[sops_lastUpdate],  -- Fecha de ultima modificacion

			--ID
			CONVERT(VARCHAR,tsod.comp_id)		+ '-' +
			CONVERT(VARCHAR,tsod.bra_id)		+ '-' +
			CONVERT(VARCHAR,tsod.soh_id)		+ '-' +
			CONVERT(VARCHAR,tsod.sod_id)		+ '-' +
			CONVERT(VARCHAR,ti.item_id)					[ID]

			FROM tbSaleOrderDetail						tsod				WITH (NOLOCK)

			left join dbo.tbBranch						sopsbra				WITH (NOLOCK)
			on	sopsbra.comp_id		= tsod.comp_id
			And sopsbra.bra_id		= tsod.sops_bra_id

			left join dbo.tbSupplier 					sopsts				WITH (NOLOCK)
			on	sopsts.comp_id		= tsod.comp_id
			And sopsts.supp_id		= tsod.sops_supp_id

			INNER JOIN tbItem							ti					WITH (NOLOCK)
			ON		ti.comp_id		= tsod.comp_id
			AND		ti.item_id		= tsod.item_id

			LEFT JOIN tbUser							tu					WITH (NOLOCK)
			ON tu.[user_id]		= tsod.sops_user_id

			LEFT JOIN tbSaleOrderPendingReason			tsops				WITH (NOLOCK)
			ON		tsops.sops_id	= tsod.sops_id

			WHERE	tsod.comp_id	= @comp_id		AND
					tsod.bra_id		= @soh_bra_id	AND
					tsod.soh_id		= @soh_id

	END
GO








CREATE PROCEDURE [dbo].[spSaleOrderDetail_getDataById]
(
    @comp_id		INT,
	@bra_id			INT,
	@soh_id			INT,
	@sod_id			INT,
	@item_id		INT
)
AS
SET NOCOUNT ON



BEGIN


	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
	/*
	declare	@comp_id		int,
			@bra_id			int,
			@soh_id			int,
			@sod_id			int,
			@item_id		int
	select  @comp_id		= 1,
			@bra_id			= 1,
			@soh_id			= 32631,
			@sod_id			= 20895,
			@item_id		= 222
	*/
	-- -----------------------------------------------------------------------




	SELECT	SOD.comp_id,
			SOD.bra_id,
			SOD.soh_id,
			SOD.sod_id,

			CASE WHEN isnull(tsod.sodt_qty,0) = 0
				THEN SOD.sod_qty * isnull(tic.icomp_qty,1)
				ELSE tsod.sodt_qty
			END												[sod_qty],

			SOD.sod_qty * isnull(tic.icomp_qty,1)			[sod_max_qty],
			SOD.item_id


	FROM	dbo.tbSaleOrderDetail				SOD

--			Inner join tbSaleOrderHeader		SOH
--			ON  SOD.comp_id		=	SOH.comp_id
--			AND SOD.bra_id		=	SOH.bra_id
--			AND	SOD.soh_id		=	SOH.soh_id

			LEFT JOIN tbItemComposition		tic
			ON	tic.comp_id		= SOD.comp_id
			AND tic.item_id		= SOD.item_id
			AND tic.item_id_1	= @item_id

			LEFT JOIN tbSaleOrderDetailtmp		tsod
			ON  tsod.comp_id	= SOD.comp_id
			AND tsod.bra_id		= SOD.bra_id
			AND tsod.soh_id		= SOD.soh_id
			AND tsod.sod_id		= SOD.sod_id
			AND tsod.item_id	= @item_id


	WHERE	SOD.comp_id	= @comp_id
	and		SOD.bra_id	= @bra_id
	and		SOD.soh_id	= @soh_id
	and		SOD.sod_id	= @sod_id



END
GO


