		(	item_desc	VARCHAR(200),
			soh_id		INT,
			sod_id		INT,
			item_id		INT,
			number		INT,
			stor_desc	VARCHAR(50),
			prli_desc	VARCHAR(50),
			sod_priority	INT ,
			stor_id			INT)




		DECLARE @sod_id			INT,
				@sod_qty		DECIMAL(18,5)

		DECLARE cursor1 CURSOR LOCAL FAST_FORWARD FOR
			SELECT  tsod.soh_id,
					tsod.sod_id,
					tsod.sod_qty
				FROM  tbSaleOrderDetail tsod			WITH (NOLOCK)
				WHERE	tsod.comp_id = @comp_id AND
						tsod.bra_id  = @bra_id  AND
						tsod.soh_id  = @soh_id


		OPEN cursor1

		FETCH cursor1 INTO @soh_id , @sod_id, @sod_qty

		WHILE @@FETCH_STATUS = 0
		BEGIN

			  WHILE @sod_qty > 0
			  BEGIN

					INSERT INTO #tmpData4Production
					SELECT distinct
							substring(ti.item_code + '-' + ti.item_desc,1,200),
							tsod.soh_id,
							tsod.sod_id,
							tsod.item_id,
							@sod_qty ,
							ts.stor_desc,
							tpl.prli_desc,
							tsod.sod_priority,
							tsod.stor_id

					FROM tbSaleOrderDetail tsod				WITH (NOLOCK)

						INNER JOIN tbItem ti				WITH (NOLOCK)
						ON	ti.comp_id	= tsod.comp_id
						AND ti.item_id	= tsod.item_id

						INNER JOIN tbStorage ts				WITH (NOLOCK)
						ON ts.comp_id	= tsod.comp_id
						AND ts.stor_id	= tsod.stor_id

						INNER JOIN tbPriceList tpl			WITH (NOLOCK)
						ON tpl.comp_id	= tsod.comp_id
						AND tpl.prli_id = tsod.prli_id

						INNER JOIN tbItemComposition tic	WITH (NOLOCK)
						ON tic.comp_id	= ti.comp_id
						AND tic.item_id = ti.item_id


					WHERE	tsod.comp_id	= @comp_id	AND
							tsod.soh_id		= @soh_id	AND
							tsod.sod_id		= @sod_id


					SET @sod_qty = @sod_qty - 1

			  END


			  FETCH cursor1 INTO @soh_id , @sod_id, @sod_qty


		END

		CLOSE cursor1
		DEALLOCATE cursor1



		-- -----------------------------------------------
		-- A T E N C I O N !!!!!!!!
		--
		-- sI SE MODIFICA O AGREGA AQUÍ ALGUNA COLUMNA
		-- SE DEBERÁ ACTUALIZAR EN **kl987
		-- -----------------------------------------------
		-- en la primer columna retornamos 1 si el registro ya está siendo producido o si ya fué producido
		-- en caso contrario retornamos 0
		SELECT	ISNULL(CONVERT(INT,tsosip.sosip_isEditing), ISNULL(tsosp.sosp_order,0)) [ ],
				tmp.number,
				CONVERT(BIT,
						CASE
							WHEN tsosp.comp_id IS NULL THEN 'False'
							ELSE							'True'
						END	)										[Producido] ,
				tmp.item_desc,
				IsNull(mse.sod_serial,'')							[sod_serial],
				tmp.soh_id,
				tmp.sod_id,
				tmp.item_id,
				tmp.stor_desc,
				tmp.prli_desc,
				tmp.sod_priority,
				tmp.stor_id,
				CONVERT(VARCHAR,@comp_id)		+ '-' +
				CONVERT(VARCHAR,@bra_id)		+ '-' +
				CONVERT(VARCHAR,tmp.soh_id)		+ '-' +
				CONVERT(VARCHAR,tmp.sod_id)		+ '-' +
				CONVERT(VARCHAR,tmp.number)		+ '-' +
				CONVERT(VARCHAR,tmp.item_id)	+ '-' +
				CONVERT(VARCHAR,isnull(ti.item_expser,'0'))			[ID]

			FROM	#tmpData4Production							tmp

					LEFT JOIN tbItem							ti			    WITH (NOLOCK)
					ON  ti.comp_id = @comp_id				AND
						ti.item_id = tmp.item_id

					LEFT JOIN tbSaleOrderSerialInProduction		tsosip			WITH (NOLOCK)
					ON	tsosip.comp_id		= @comp_id		AND
						tsosip.soh_id		= tmp.soh_id	AND
						tsosip.sod_id		= tmp.sod_id	AND
						tsosip.sosip_order	= tmp.number

					LEFT JOIN tbSaleOrderSerialProduced			tsosp			WITH (NOLOCK)
					ON	tsosp.comp_id		= @comp_id		AND
						tsosp.soh_id		= tmp.soh_id	AND
						tsosp.sod_id		= tmp.sod_id	AND
						tsosp.sosp_order	= tmp.number

					LEFT JOIN tbSaleOrderSerial4Production_MasterSerial mse		WITH (NOLOCK)
					ON	mse.comp_id		= @comp_id		AND
						mse.soh_id		= tmp.soh_id	AND
						mse.sod_id		= tmp.sod_id	AND
						mse.sod_order	= tmp.number


			WHERE		(@sod_serial		= '' OR mse.sod_serial			= @sod_serial)


			ORDER BY 	tmp.soh_id,
						tmp.sod_id,
						tmp.item_id,
						tmp.number




END
GO

CREATE PROCEDURE [dbo].[spSaleOrderDetail_GetDataforProduction_byQty]
(
    @comp_id			INT,
	@bra_id				INT,
	@soh_id				INT,
	@sod_id				INT
)
AS

BEGIN



	SET NOCOUNT ON

	-- ---------------------------------------------------------------------------------------
	-- Test: CLon del FORRROOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOO
	-- ---------------------------------------------------------------------------------------
	/*

	DECLARE		@comp_id			INT,
				@bra_id				INT,
				@soh_id				INT,
				@sod_serial			NVARCHAR(50)



	SELECT		@comp_id			= 1,
				@bra_id				= 1,
				@soh_id				= 33260,
				@sod_serial			= 'GLOTESTYA'



	--IF NOT OBJECT_ID('tempdb.dbo.#tmpData4Production')		IS NULL DROP TABLE #tmpData4Production


	*/
	-- ---------------------------------------------------------------------------------------

		CREATE TABLE #tmpData4Production
		(	item_desc	VARCHAR(200),
			soh_id		INT,
			sod_id		INT,
			item_id		INT,
			number		INT,
			stor_desc	VARCHAR(50),
			prli_desc	VARCHAR(50),
			sod_priority	INT ,
			stor_id			INT)

			INSERT INTO #tmpData4Production
			SELECT DISTINCT
				SUBSTRING(ti.item_code + '-' + ti.item_desc,1,200),
				tsod.soh_id,
				tsod.sod_id,
				tsod.item_id,
				tsod.sod_qty ,
				ts.stor_desc,
				tpl.prli_desc,
				tsod.sod_priority,
				tsod.stor_id
			FROM tbSaleOrderDetail					tsod	WITH (NOLOCK)
				INNER JOIN tbItem					ti		WITH (NOLOCK)
					ON	ti.comp_id	= tsod.comp_id	AND
						ti.item_id	= tsod.item_id
				INNER JOIN tbStorage				ts		WITH (NOLOCK)
					ON	ts.comp_id	= tsod.comp_id	AND
						ts.stor_id	= tsod.stor_id
				INNER JOIN tbPriceList				tpl		WITH (NOLOCK)
					ON	tpl.comp_id	= tsod.comp_id	AND
						tpl.prli_id = tsod.prli_id
				INNER JOIN tbItemComposition		tic		WITH (NOLOCK)
					ON	tic.comp_id	= ti.comp_id	AND
						tic.item_id = ti.item_id
			WHERE	tsod.comp_id	= @comp_id		AND
					tsod.bra_id		= @bra_id		AND
					tsod.soh_id		= @soh_id		AND
					(
						@sod_id = -1		-- Para llenar la grilla con todos los DETAILO de este pedido de Produccion x Lotes.
						OR
						tsod.sod_id		= @sod_id
					)

		-- -----------------------------------------------
		-- A T E N C I O N !!!!!!!!
		--
		-- sI SE MODIFICA O AGREGA AQUÍ ALGUNA COLUMNA
		-- SE DEBERÁ ACTUALIZAR EN **kl987
		-- -----------------------------------------------
		-- en la primer columna retornamos 1 si el registro ya está siendo producido o si ya fué producido
		-- en caso contrario retornamos 0
		SELECT
			--ISNULL(CONVERT(INT,tsosip.sosip_isEditing), ISNULL(tsosp.sosp_order,0)) [ ],
			ISNULL(CONVERT(INT,tsosip.sosip_isEditing), ISNULL(tsosp.sosp_order,0)),
			tmp.number,
			CONVERT(BIT,
					CASE
						WHEN tsosp.comp_id IS NULL THEN 'False'
						ELSE							'True'
					END	)										[Producido] ,
			tmp.item_desc,
			ISNULL(mse.sod_serial,'')							[sod_serial],
			tmp.soh_id,
			tmp.sod_id,
			tmp.item_id,
			tmp.stor_desc,
			tmp.prli_desc,
			tmp.sod_priority,
			tmp.stor_id,
			CONVERT(VARCHAR,@comp_id)		+ '-' +
			CONVERT(VARCHAR,@bra_id)		+ '-' +
			CONVERT(VARCHAR,tmp.soh_id)		+ '-' +
			CONVERT(VARCHAR,tmp.sod_id)		+ '-' +
			CONVERT(VARCHAR,tmp.number)		+ '-' +
			CONVERT(VARCHAR,tmp.item_id)	+ '-' +
			CONVERT(VARCHAR,isnull(ti.item_expser,'0'))			[ID]

			FROM	#tmpData4Production							tmp

			LEFT JOIN tbItem							ti			    WITH (NOLOCK)
				ON  ti.comp_id = @comp_id				AND
					ti.item_id = tmp.item_id

			LEFT JOIN tbSaleOrderSerialInProduction		tsosip			WITH (NOLOCK)
				ON	tsosip.comp_id		= @comp_id		AND
					tsosip.soh_id		= tmp.soh_id	AND
					tsosip.sod_id		= tmp.sod_id	AND
					tsosip.sosip_order	= tmp.number

			LEFT JOIN tbSaleOrderSerialProduced			tsosp			WITH (NOLOCK)
				ON	tsosp.comp_id		= @comp_id		AND
					tsosp.soh_id		= tmp.soh_id	AND
					tsosp.sod_id		= tmp.sod_id	AND
					tsosp.sosp_order	= tmp.number

			LEFT JOIN tbSaleOrderSerial4Production_MasterSerial mse		WITH (NOLOCK)
				ON	mse.comp_id		= @comp_id		AND
					mse.soh_id		= tmp.soh_id	AND
					mse.sod_id		= tmp.sod_id	AND
					mse.sod_order	= tmp.number


		--	WHERE		(@sod_serial		= '' OR mse.sod_serial			= @sod_serial)


			ORDER BY 	tmp.soh_id,
						tmp.sod_id,
						tmp.item_id,
						tmp.number




END
GO




CREATE PROCEDURE [dbo].[spSaleOrderDetail_GetHTMLTableOfItems4Mail]
(
 @comp_id  INT,
 @lang_id  INT,
 @bra_id   INT,
 @soh_id   INT,
 @HTMLItemsTable NVARCHAR(MAX) OUTPUT
)
AS



 BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON
	-- ------------------------------------------------
	-- TESTING
	-- ------------------------------------------------
	/*
	DECLARE
	 @comp_id INT,
	 @lang_id INT,
	 @bra_id  INT,
	 @soh_id  INT ,
	 @HTMLItemsTable NVARCHAR(MAX)
	SELECT
	 @comp_id = 1,
	 @lang_id = 2,
	 @bra_id  = 1,
	 @soh_id  = 33680
	 */
	-- ------------------------------------------------

	DECLARE @bodyMsg NVARCHAR(MAX)
	DECLARE @subject NVARCHAR(MAX)
	DECLARE @tableHTML NVARCHAR(MAX)
	DECLARE @Table  NVARCHAR(MAX) = N''

	SET @subject = ''

	--style="background-color:'+ CASE WHEN (ROW_NUMBER() OVER (ORDER BY tsod.sod_id))%2 =1 THEN '#A3E0FF' ELSE '#8ED1FB' END +';">' +


	-- CARGAMOS LOS TEXTOS PARA LOS HEADER DE LA GRILLA
	DECLARE
	@ItemCode VARCHAR(100),
	@ItemDesc VARCHAR(100),
	@ItemQty VARCHAR(100)

	SELECT
	@ItemCode = tsut.utexts_desc
	FROM tbsysUniqueTexts    tsut
	WHERE tsut.lang_id = @lang_id AND
	 tsut.utexts_id = 30799

	SELECT
	@ItemDesc = tsut.utexts_desc
	FROM tbsysUniqueTexts    tsut
	WHERE tsut.lang_id = @lang_id AND
	 tsut.utexts_id = 400007

	SELECT
	@ItemQty = tsut.utexts_desc
	FROM tbsysUniqueTexts    tsut
	WHERE tsut.lang_id = @lang_id AND
	 tsut.utexts_id = 961




	SELECT @Table = @Table + '
	<tr >' +
	'<td><face="verdana">' + ti.item_code + ' </font></td>' +
	'<td><face="verdana">' + ti.item_desc + ' </font></td>' +
	'<td align="right"><face="verdana">' + CONVERT(VARCHAR,CONVERT(DECIMAL(25,2),tsod.sod_qty)) + CHAR(10) + CHAR(13) + '</font></td>' +
	'</tr>'
	FROM tbSaleOrderDetail     tsod
	INNER JOIN tbItem     ti
	 ON  ti.comp_id = tsod.comp_id AND
	  ti.item_id = tsod.item_id
	WHERE tsod.comp_id = @comp_id  AND
	 tsod.bra_id  = @bra_id  AND
	 tsod.soh_id  = @soh_id

	SET @tableHTML =   '<br/> <p>'  +
	--N'<H3><font-color:black; align:"center" font-family:Verdana;>Título de la Tabla</H3>' +
	--N'<H4><font-color:black; align:"center" font-family:Verdana;>Caca</H3>' +
	N'<table border="0" align="left" cellpadding="5" cellspacing="1" style=";font-family:Verdana;text-align:left;" >' +
	N'<tr style ="font-size: small;color:White;font-weight: bold;background:gray;">
	<th>'+ @ItemCode +'</th>
	<th>'+ @ItemDesc +'</th>
	<th>'+ @ItemQty +'</th>
	</tr>' + @Table + N'</table> <br/>  </p>'



	SET @HTMLItemsTable = ISNULL(@tableHTML,'')



 END
GO







-- Updated MOS  03-2010
CREATE PROCEDURE [dbo].[spSaleOrderDetail_getLastPrice]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@item_id	INT,
	@cust_id	INT
)
AS

BEGIN



	SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

-- ------------------------------------------------------
-- Testing
-- ------------------------------------------------------
		/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@item_id	INT,
			@cust_id	INT
		SELECT
			@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@item_id	=492,
			@cust_id	=24510
		*/
-- ------------------------------------------------------



	DECLARE @bitCostPlusTax AS BIT
	SELECT  @bitCostPlusTax	= IsNull(tb.bra_SaleOrderPricePlusTax,'False')
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id





			SELECT		TOP 1
					dbo.fnSplitPosition(tut.utexts_desc,'|',1) + ' ' + CONVERT(VARCHAR(12),tsod.sod_insertDate,105)	+ ' ' +
					tdf.df_desc + ' #' + CONVERT(NVARCHAR(10),tdf.bra_id) + '-' + CONVERT(NVARCHAR(10),tsoh.soh_id) + ' ' +
					dbo.fnSplitPosition(tut.utexts_desc,'|',2) + '' + --LTRIM(RTRIM(tc.curr_symbol))				+

					CONVERT(VARCHAR,CONVERT(DECIMAL(19,4), (tsod.sod_price  + (
																																CASE
																																	WHEN @bitCostPlusTax = 'True' THEN (tsod.sod_price ) * IsNull(ttn.tax_percentage,0) / 100
																																	ELSE 0
																																END
																																)
										   )))  + ' ' + tc1.curr_symbol 				 [desc]

			FROM tbSaleOrderDetail tsod
				INNER JOIN tbSaleOrderHeader tsoh
					ON	tsoh.comp_id	= tsod.comp_id	AND
						tsoh.bra_id		= tsod.bra_id	AND
						tsoh.soh_id		= tsod.soh_id

				INNER JOIN tbDocumentsFile tdf
					ON	tdf.comp_id = tsoh.comp_id AND
						tdf.df_id	= tsoh.df_id

				INNER JOIN tbsysCurrency tc1
					ON tc1.curr_id = tsod.curr_id


				INNER JOIN tbBranch							tb
				ON tb.bra_id = @bra_id

				INNER JOIN tbsysUniqueTexts tut
				ON   	tut.lang_id = @lang_id
				AND		tut.utexts_id = 629


				left JOIN vwItemTaxesOnlyOneIvaTax	vit
					ON		vit.comp_id = tsod.comp_id
						AND vit.item_id = tsod.item_id
				LEFT JOIN tbTaxName ttn
					ON		ttn.comp_id = vit.comp_id
						AND ttn.tax_id	= vit.tax_id

			WHERE	tsod.comp_id = @comp_id
			AND		tsod.item_id = @item_id
			AND		tsoh.cust_id = @cust_id
			AND		tdf.sd_id	 = 5				-- Solo Presupuestos


			ORDER BY tsod.sod_insertDate DESC


END
GO






CREATE PROCEDURE [dbo].[spSaleOrderDetail_getPendingData]
(
	@comp_id	INT,
	@bra_id		INT,
	@lang_id	INT,
	@item_id	INT,
	@stor_id	INT
)
AS


BEGIN



	-- ---------------------------------------------------
	-- Testing
	-- ---------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@bra_id		INT,
			@lang_id	INT,
			@item_id	INT,
			@stor_id	INT

		SELECT
			@comp_id	= 1,
			@bra_id		= 1,
			@lang_id	= 2,
			@item_id	= 6784,
			@stor_id	= 1
	*/
	-- ---------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON;
	SET DATEFORMAT 'ymd'


	-- -----------------------------------------------------------------------------
	-- MOS 08-2024: Referencia **wenfk2398572390451235 de esta MIERDAAAAAA
	-- -----------------------------------------------------------------------------
	SELECT  @stor_id =	CASE
							WHEN tb.stor_id4OverwriteSelItem IS NOT NULL THEN tb.stor_id4OverwriteSelItem
							ELSE @stor_id
						END
   		FROM tbBranch tb		WITH (NOLOCK)
	   	WHERE	tb.comp_id	= @comp_id AND
	   			tb.bra_id	= @bra_id
	-- -----------------------------------------------------------------------------







	DECLARE @tblStorage AS TABLE(intStorageId INT PRIMARY KEY)
	IF @stor_id = -1
		BEGIN
			INSERT INTO @tblStorage(intStorageId)		SELECT ts.stor_id
															FROM tbStorage ts	WITH (NOLOCK)
			                                   				WHERE	ts.comp_id		= @comp_id --AND
			                                   						--ts.stor_web4ALL = 'True'		-- MOS 08-2024: Esto es MIERDA, en algun momento serviria pero es pre storage_group
		END
	ELSE
		BEGIN
			-- ----------------------------------------------------------------------------------
			-- NOTA, un deposito SOLO puede pertenecer a un grupo de Depositos para POTENCIAL!!!!
			-- Para que se incluya todo el grupo a un grupo de depositos debe tener el campo
			-- stor_IncludeStockOfStorageGroupMembers en TRUE
			-- ----------------------------------------------------------------------------------
			DECLARE @intStorageGroups AS INT
			SET		@intStorageGroups = NULL
			--SELECT Top 1 @intStorageGroups = tsgd.storg_id
			--	FROM tbStorageGroupDetail tsgd
   --      		WHERE	tsgd.comp_id = @comp_id AND
   --      				tsgd.stor_id = @stor_id
			-- ----------------------------------------------------------------------------------
			DECLARE @bitIncludeStorageGroups BIT
			SELECT	@bitIncludeStorageGroups =	CASE
													WHEN ts.storg_id IS NULL THEN 'False'
													ELSE IsNull(ts.stor_IncludeStockOfStorageGroupMembers,'False')
												END,
					@intStorageGroups		 = ts.storg_id
				FROM tbStorage ts	WITH (NOLOCK)
			WHERE	ts.comp_id = @comp_id AND
					ts.stor_id = @stor_id

			INSERT INTO @tblStorage(intStorageId)		SELECT Distinct ts.stor_id
			                                   				FROM tbStorage ts					WITH (NOLOCK)
			                                   				LEFT JOIN tbStorageGroupDetail tsgd	WITH (NOLOCK)
																ON  tsgd.comp_id  = @comp_id AND
																	tsgd.storg_id = @intStorageGroups
				                                   			WHERE	 ts.comp_id = @comp_id AND
				                                   					(ts.stor_id = @stor_id OR
				                                   						(	tsgd.stor_id IS NOT NULL	AND
				                                   							ts.stor_id <> @stor_id		AND
				                                   							ts.stor_id = tsgd.stor_id   AND
				                                   							@bitIncludeStorageGroups = 'True'
				                                   						)
				                                   					)
		END
	-- ----------------------------------------------------------------------------------------------


	-- -----------------------------------------------------------------------------------------------------------
	-- Selecciono en una tabla temporal todos los items compuestos que esten compuestos por el @item_id solicitado
	-- -----------------------------------------------------------------------------------------------------------
	DECLARE		@tblItem			AS TABLE(intItemId INT PRIMARY KEY)
	INSERT INTO @tblItem (intItemId)
		SELECT DISTINCT tic.item_id
			FROM tbItemComposition tic	WITH (NOLOCK)
			WHERE	tic.comp_id		= @comp_id and
					tic.item_id_1	= @item_id
	IF NOT EXISTS (
						SELECT TOP 1  1
							FROM @tblItem
							WHERE intItemId = @item_id
				  )
		BEGIN
			INSERT INTO @tblItem (intItemId) VALUES (@item_id)
		END

	DECLARE		@tblItemAssociation AS TABLE(intItemId INT PRIMARY KEY)
	INSERT INTO @tblItemAssociation (intItemId)
		SELECT DISTINCT tic.item_id
			FROM tbItemAssociation AS tic	WITH (NOLOCK)
			WHERE	tic.comp_id		= @comp_id and
					tic.item_id_1	= @item_id
			UNION
		SELECT DISTINCT tic.item_id_1
			FROM tbItemAssociation AS tic	WITH (NOLOCK)
			WHERE	tic.comp_id		= @comp_id and
					tic.item_id	    = @item_id
	-- -----------------------------------------------------------------------------------------------------------


	-- Pedidos
	SELECT
		tb.bra_desc,
		convert(varchar,tsoh.bra_id) + ' - '+ convert(varchar,tsod.soh_id) [sod_id],
		tsoh.soh_cd,
		tc.cust_name,
		CASE	WHEN td.sd_isCredit = 'true' THEN tsod.sod_qty * -1
				ELSE tsod.sod_qty
		END																	[sod_qty],
		ISNULL(tu.user_lastname,'*') + ',' + ISNULL(tu.user_firstname,'*')	[user_name],
		tsod.sod_priority													[sod_priority],
		tdf.df_desc,
		ts.stor_desc,
		IsNull(tis.itst_cant,0)												[ActualQty],



		-- ATENCION, NO AGREGAR NADA, MOS 10-2021
		CASE
			WHEN IsNull(tsod.sod_exclude4AvailableStock,'False')	= 'True' THEN '*'
			ELSE ''
		END																	[sod_exclude4AvailableStock],	-- Count - 2
		(
			SELECT TOP 1 convert(varchar,tsohpor.po_bra_id) + ' - '+ convert(varchar,tsohpor.po_poh_id)
				FROM tbSaleOrderHeader_PurchaseOrderRelation AS tsohpor WITH (NOLOCK)
				WHERE	tsohpor.comp_id		= tsod.comp_id	AND
						tsohpor.so_bra_id	= tsod.bra_id	AND
						tsohpor.so_soh_id	= tsod.soh_id	AND
						tsohpor.so_sod_id	= tsod.sod_id
		)																	[PurchaseOrderRelated]			-- Count - 1
		FROM tbSaleOrderDetail				tsod		WITH (NOLOCK)

		INNER JOIN tbSaleOrderHeader		tsoh		WITH (NOLOCK)
		ON  tsoh.comp_id	= tsod.comp_id
		AND tsoh.bra_id		= tsod.bra_id
		AND tsoh.soh_id		= tsod.soh_id

		Inner JOIN tbDocumentsFile tdf					WITH (NOLOCK)
		ON	tdf.comp_id		= tsod.comp_id
		AND tdf.df_id		= tsoh.df_id

		INNER JOIN tbsysDocuments			td			WITH (NOLOCK)
		ON td.sd_id			= tdf.sd_id

		INNER JOIN tbCustomer				tc			WITH (NOLOCK)
		ON  tc.comp_id		= tsoh.comp_id
		AND tc.cust_id		= tsoh.cust_id


		INNER JOIN @tblStorage tmps
			ON tmps.intStorageId = tsod.stor_id


		INNER JOIN tbStorage				ts			WITH (NOLOCK)
		ON ts.comp_id		= tsod.comp_id
		AND ts.stor_id		= tsod.stor_id

		LEFT JOIN tbItemStorage tis						WITH (NOLOCK)
			ON		tis.comp_id = tsod.comp_id
				AND tis.stor_id = tsod.stor_id
				AND tis.item_id = tsod.item_id

		LEFT JOIN tbUser					tu			WITH (NOLOCK)
		ON tu.[user_id]		= tsod.[user_id]

		INNER JOIN tbBranch					tb			WITH (NOLOCK)
		ON tb.comp_id		= tsod.comp_id
		AND tb.bra_id		= tsod.bra_id

		WHERE		tsod.comp_id		= @comp_id
			--AND		((@stor_id = -1 and tsod.bra_id = @bra_id) OR (@stor_id <> -1))	-- MOS 07-2010
			AND
					CASE
						WHEN tsod.item_id = @item_id															THEN 1
						WHEN (					 tsod.item_id	 IN (	SELECT tmp.intItemId
			   		            											FROM @tblItemAssociation tmp)	)	THEN 1
						WHEN (tdf.sd_id = 80 AND tsod.item_id	 IN (	SELECT tmp.intItemId
			   		            											FROM @tblItem tmp)	)				THEN 1
			   		    ELSE 0
					END	= 1
					--((tdf.sd_id = 80 AND tsod.item_id	 IN (	SELECT tmp.intItemId
			  -- 		            									FROM @tblItem tmp)	)
			  -- 		  OR
			  -- 		 (tsod.item_id = @item_id)
					--)							--= @item_id
			AND		IsNull(tsod.sod_isEditing,'False')	= 'False'
			AND		(@stor_id = -1 or tsod.stor_id		= @stor_id)
			AND		tdf.sd_id IN (1,2,3,4,12,31,33,43,44,80)


	UNION	ALL

		-- Pedidos en ALTA o Modificacion
		SELECT
			tb.bra_desc,
			convert(varchar,ttis.bra_id) + ' - ' + convert(VARCHAR,isnull(ttis.soh_id,' '))		[soh_id],
			' '											[soh_cd],
			tut.utexts_desc,
			ttis.tis_qty,
			tu.user_lastname + ',' + tu.user_firstname	[user_name],
			ttis.tis_priority							[sod_priority],
			'' [df_desc],
			''[stor_desc],
			IsNull(tis.itst_cant,0)						[ActualQty],
			''											[sod_exclude4AvailableStock],
			''											[PurchaseOrderRelated]




		FROM tbTempItemStock					ttis		WITH (NOLOCK)

		INNER JOIN tbsysUniqueTexts				tut		WITH (NOLOCK)
		ON tut.lang_id		= @lang_id
		AND tut.utexts_id	= 5000

		INNER JOIN tbBranch						tb		WITH (NOLOCK)
		ON  tb.comp_id		= ttis.comp_id
		AND tb.bra_id		= ttis.bra_id

		INNER JOIN tbUser						tu		WITH (NOLOCK)
		ON tu.[user_id]		= ttis.[user_id]

		INNER JOIN tbDocumentsFile tdf					WITH (NOLOCK)
		ON		tdf.comp_id = ttis.comp_id
			AND tdf.df_id	= ttis.df_id

		INNER JOIN @tblStorage tmps
			ON tmps.intStorageId = ttis.stor_id

		LEFT JOIN tbItemStorage tis						WITH (NOLOCK)
			ON		tis.comp_id = ttis.comp_id
				AND tis.stor_id = ttis.stor_id
				AND tis.item_id = ttis.item_id


		WHERE	ttis.comp_id		= @comp_id
			--AND		ttis.bra_id		= @bra_id

			AND
					CASE
						WHEN ttis.item_id = @item_id															THEN 1
						WHEN (					 ttis.item_id	 IN (	SELECT tmp.intItemId
			   		            											FROM @tblItemAssociation tmp)	)	THEN 1
						WHEN (tdf.sd_id = 80 AND ttis.item_id	 IN (	SELECT tmp.intItemId
			   		            											FROM @tblItem tmp)	)				THEN 1
			   		    ELSE 0
					END	= 1
							--((tdf.sd_id = 80 AND ttis.item_id	 IN (	SELECT tmp.intItemId
			   	--	            												FROM @tblItem tmp)	)
			   	--				  OR (ttis.item_id = @item_id)
							--	)

--			AND		ttis.item_id		IN (SELECT tmp.intItemId
--			   		            				FROM @tblItem tmp)	--= @item_id
			and		ttis.tis_IsEditing	= 'True'
			--AND		(@stor_id = -1 or ttis.stor_id		= @stor_id)
			AND		tdf.sd_id IN (1,2,3,4,80)

	UNION	ALL

		-- Pedidos de RMA
		SELECT
			tb.bra_desc,
			tb.bra_desc + ' RMA# ' + convert(VARCHAR,isnull(ttis.rmah_id,' ')) + ' - ' + convert(VARCHAR,isnull(ttis.rmad_id,' '))		[soh_id],
			' '											[soh_cd],
			tut.utexts_desc,
			ttis.rmad_qty,
			tu.user_lastname + ',' + tu.user_firstname	[user_name],
			0											[sod_priority],
			'' [df_desc],
			''[stor_desc],
			IsNull(tis.itst_cant,0)						[ActualQty],
			''											[sod_exclude4AvailableStock],
			''											[PurchaseOrderRelated]

		FROM tbRMA_Detail	 					ttis	WITH (NOLOCK)

		INNER JOIN tbsysUniqueTexts				tut		WITH (NOLOCK)
			ON tut.lang_id		= @lang_id
			AND tut.utexts_id	= 5001

		INNER JOIN tbBranch						tb		WITH (NOLOCK)
			ON  tb.comp_id		= ttis.comp_id
			AND tb.bra_id		= ttis.bra_id

		INNER JOIN tbUser						tu		WITH (NOLOCK)
			ON tu.[user_id]		= ttis.user_id_Reception

		INNER JOIN @tblStorage tmps
			ON tmps.intStorageId = ttis.stor_id

		LEFT JOIN tbItemStorage tis						WITH (NOLOCK)
			ON		tis.comp_id = ttis.comp_id
				AND tis.stor_id = tb.stor_id
				AND tis.item_id = ttis.item_id


		WHERE	ttis.comp_id		= @comp_id	AND
			   (ttis.rmad_IncludeInPotentialStock = 'True' AND ttis.srpt_id = 1)	AND
				CASE
					WHEN ttis.item_id = @item_id										THEN 1
					WHEN (ttis.item_id	 IN (	SELECT tmp.intItemId
			   										FROM @tblItemAssociation tmp)	)	THEN 1
			   		ELSE 0
				END	= 1
			--AND	ttis.item_id		= @item_id



	UNION	ALL

	-- Articulos adicionales de RMA
	SELECT
			tb.bra_desc,
			tb.bra_desc + ' RMA# ' + convert(VARCHAR,isnull(trd.rmah_id,' ')) + ' - ' + convert(VARCHAR,isnull(trd.rmad_id,' '))		[soh_id],
			' '																															[soh_cd],
			'Artículos Adicionales de R.M.A.'																							[utexts_desc],
			trdai.rmaa_qty,
			ISNULL(tu.user_lastname,'*') + ',' + ISNULL(tu.user_firstname,'*')															[user_name],
			0																															[sod_priority],
			''																															[df_desc],
			''																															[stor_desc],
			IsNull(tis.itst_cant,0)																										[ActualQty]	,
			''																															[sod_exclude4AvailableStock],
			''											[PurchaseOrderRelated]

		FROM tbRMA_Detail_AddItems trdai			WITH (NOLOCK)
		INNER JOIN tbRMA_Detail trd					WITH (NOLOCK)
			ON	trd.comp_id = trdai.comp_id AND
				trd.rmah_id = trdai.rmah_id AND
				trd.rmad_id = trdai.rmad_id
		INNER JOIN tbBranch tb						WITH (NOLOCK)
			ON	tb.comp_id	= trd.comp_id AND
				tb.bra_id	= trd.bra_id_original
		LEFT JOIN tbUser tu							WITH (NOLOCK)
			ON tu.[user_id] = trd.user_id_Reception
		INNER JOIN @tblStorage tmps								-- MOS 03-2022
			ON tmps.intStorageId = trdai.stor_id
		LEFT JOIN tbItemStorage tis					WITH (NOLOCK)
			ON		tis.comp_id = trdai.comp_id
				AND tis.stor_id = trdai.stor_id --tb.stor_id
				AND tis.item_id = trdai.item_id
		WHERE	trdai.comp_id			= @comp_id	AND
				trdai.is4AbailableStock = 1			AND
				--trdai.stor_id			= @stor_id	AND			-- MOS 03-2022
				CASE
					WHEN  trdai.item_id = @item_id										THEN 1
					WHEN (trdai.item_id	 IN (	SELECT tmp.intItemId
			   		            					FROM @tblItemAssociation tmp)	)	THEN 1
			   		ELSE 0
				END	= 1
				--trdai.item_id			= @item_id	AND


	UNION	ALL


	-- Articulos de ML Pendientes a ser ingresados
	SELECT
			tb.bra_desc,
				tb.bra_desc + ' ML Orden#' + convert(VARCHAR,isnull(tmlod.mlo_id,' ')) + ' Publicación:#' + convert(VARCHAR,isnull(tmlod.mlp_id,' ')) 															[mlp_id],
			' '																															[soh_cd],
			'Artículos Pendientes de Ordenes de MercadoLibre'																			[utexts_desc],
			tmlod.mlo_quantity,
			'*'															[user_name],
			tmlod.mlod_id																												[sod_priority],
			''																															[df_desc],
			''																															[stor_desc],
			IsNull(tis.itst_cant,0)																										[ActualQty]	,
			''																															[sod_exclude4AvailableStock],
			''											[PurchaseOrderRelated]

	FROM tbMercadoLibre_ordersDetail			tmlod	WITH (NOLOCK)
	INNER JOIN tbMercadoLibre_ordersHeader		tmloh	WITH (NOLOCK)
		ON	tmloh.comp_id	= tmlod.comp_id	AND
			tmloh.mlo_id	= tmlod.mlo_id
	LEFT JOIN tbMercadoLibre_ItemsPublicados	tmlip	WITH (NOLOCK)
		ON	tmlip.comp_id	= tmlod.comp_id AND
			tmlip.mlp_id	= tmlod.mlp_id
	LEFT JOIN tbBranch							tb		WITH (NOLOCK)
		ON	tb.comp_id	= tmlip.comp_id AND
			tb.bra_id	= tmlip.bra_id

	INNER JOIN @tblStorage tmps
		ON tmps.intStorageId = tmlod.stor_id

	LEFT JOIN tbItemStorage						tis		WITH (NOLOCK)
		ON		tis.comp_id = tmlod.comp_id
			AND tis.stor_id = tmlod.stor_id
			AND tis.item_id = tmlod.item_id
	WHERE	tmlod.comp_id			= @comp_id	AND
			--tmlod.stor_id			= @stor_id	AND		-- MOS 03-2022
			tmlod.mlo_is4AvailableStock = 1		AND
			tmlod.item_id			= @item_id	AND		-- MOS 03-2022, antes era tmlip
			tmloh.mlo_isCancelled   = 'False'





		ORDER BY [sod_priority]


END
GO






-- =================================================================
-- Author:		MOH
-- Modif:		MOS  29-2-08
-- Description:	Trae Valores por ID de conf. del sistema
-- Si no encuentra el dato por compañia y por sucursal
-- lo busca solo por compañia y sucursal 1
-- la cual estara cargada por script inicial del sistema
-- Como  lo pide por rango, tiene que respetar esto ultimo
-- =================================================================

CREATE  PROCEDURE [dbo].[spSaleOrderDetail_insertData]
(
	@comp_id			int,
	@bra_id				int,
    @soh_id				int,
    @sod_priority		decimal(14,4),
    @item_id			int,
    @sod_itemDesc		varchar(500),
	@sod_detail			varchar(100),
	@curr_id			int,
	@sod_initQty		decimal(19,5),
	@sod_qty			decimal(19,5),
	@prli_id			int,
	@sod_price			decimal(19,6),
	@stor_id			int,
	@user_id			int,
	@insertdate			datetime,
	@tis_costTax		int,
	@tis_cost			decimal(19,6),
	@return_value		int OUTPUT,
	@rmah_id			int,
	@rmad_id			INT,
	@sod_itemDiscount	DECIMAL(10,6),
	@sod_note1			VARCHAR(100),
	@sod_note2			VARCHAR(100),
	@sod_tis_id_origin	INT,
	@sod_item_id_origin	INT,
	@sod_isParentAssociate	BIT
)
as

	--Begin Transaction spSaleOrderDetail_insertData

	Declare @datetime	datetime
	Select	@datetime = getdate()

	Insert Into dbo.tbSaleOrderDetail	WITH (ROWLOCK )
				(	comp_id,
					bra_id,
					soh_id,
					sod_priority,
					item_id,
					sod_itemDesc,
					sod_detail,
					curr_id,
					sod_initQty,
					sod_qty,
					prli_id,
					sod_price,
					stor_id,
					sod_lastUpdate,
					sod_insertDate,
					user_id,
					sod_cost,
					sod_costTax,
					rmah_id,
					rmad_id,
					sod_itemDiscount,
					sod_note1,
					sod_note2,
					sod_tis_id_origin,
					sod_item_id_origin,
					sod_isParentAssociate)

	Values
				(	@comp_id,
					@bra_id,
					@soh_id,
					@sod_priority,
					@item_id,
					@sod_itemDesc,
					@sod_detail,
					@curr_id,
					@sod_initQty,
					@sod_qty,
					@prli_id,
					@sod_price,
					@stor_id,
					@datetime,
					@insertdate,
					@user_id,
					@tis_cost,
					@tis_costTax,
					@rmah_id,
					@rmad_id,
					@sod_itemDiscount,
					@sod_note1,
					@sod_note2,
					@sod_tis_id_origin,
					@sod_item_id_origin,
					@sod_isParentAssociate)

	set	@return_value = @@identity


	--
	--IF @@Error = 0
	--	Commit Transaction spSaleOrderDetail_insertData
	--Else
	--	ROLLBACK TRANSACTION spSaleOrderDetail_insertData
	--




GO






-- -----------------------------------------------------------------
-- title  : ACTUALIZACION DE IMPORTES DE ABONOS
-- date   : 22/06/15
-- Author : MOS
-- -----------------------------------------------------------------



CREATE PROCEDURE [dbo].[spSaleOrderDetail_MontlyPayments_UpdateData]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@guid4Cust				UNIQUEIDENTIFIER,
	@guid4Item				UNIQUEIDENTIFIER,
	@OptionUpdate			INT,
	@ValueUpdate			DECIMAL(19,5),
	@Round					BIT,
	@curr_id				INT
)
as


BEGIN
	-------------------------------------------------------------------------------------------------
	--TESTING
	-------------------------------------------------------------------------------------------------
	/*
	DECLARE 	@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@guid4Cust				UNIQUEIDENTIFIER,
				@guid4Item				UNIQUEIDENTIFIER,
				@OptionUpdate			INT,
				@ValueUpdate			DECIMAL(19,5),
				@Round					BIT,
				@curr_id				int


	SELECT		@comp_id				= 1,
				@lang_id				= 2,
				@bra_id					= 36,
				@guid4Cust				= 'BE41D364-AD65-4FC0-960B-6C036FF5D1C9',
				@guid4Item				= 'BE41D364-AD65-4FC0-960B-6C036FF5D1C9',
				@OptionUpdate			= 1,
				@ValueUpdate			= 10,
				@Round					='True',
				@curr_id				= 1

	--DROP TABLE #tmpMonthlyPayments
	*/
	-------------------------------------------------------------------------------------------------


	--@Option = 1 SUMAR PORCENTAJE
	--@Option = 2 SUMAR IMPORTE
	--@Option = 3 REEMPLAZAR

	--@Round = True para redondear



	BEGIN TRANSACTION
	BEGIN TRY



		DECLARE @lGuidCust AS UNIQUEIDENTIFIER

		SET @lGuidCust = CONVERT(UNIQUEIDENTIFIER,@guid4Cust)


		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de CLIENTEs para Filtros
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuidCust     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT tc.cust_id
					FROM tbCustomer tc
						WHERE tc.comp_id = @comp_id
			END
		-- -------------------------------------------------------------



		DECLARE @lGuidItem AS UNIQUEIDENTIFIER

		SET @lGuidItem = CONVERT(UNIQUEIDENTIFIER,@guid4Item)

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros
		-- -------------------------------------------------------------
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid	  = @lGuidItem     AND
					  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
		-- -------------------------------------------------------------

		--@Option = 1 SUMAR PORCENTAJE
		--@Option = 2 SUMAR IMPORTE
		--@Option = 3 REEMPLAZAR

		--@Round = True para redondear


		SELECT  tsoh.comp_id,
				tsoh.bra_id,
				tsoh.soh_id,
				tsod.sod_id
			INTO #tmpMonthlyPayments
			FROM tbSaleOrderHeader									tsoh		WITH (NOLOCK)
			INNER JOIN tbSaleOrderDetail							tsod		WITH (NOLOCK)
				ON	tsod.comp_id		= tsoh.comp_id		AND
					tsod.bra_id			= tsoh.bra_id		AND
					tsod.soh_id			= tsoh.soh_id
			INNER JOIN @tblComplexFilter_Customer					tcfc
				ON	tcfc.cust_id		= tsoh.cust_id
			INNER JOIN @tblComplexFilter_Items						tcfi
				ON	tcfi.item_id		= tsod.item_id
			INNER JOIN tbDocumentsFile								tdf			WITH (NOLOCK)
				ON	tdf.comp_id			= tsoh.comp_id		AND
					tdf.df_id			= tsoh.df_id
			WHERE tsoh.comp_id	= @comp_id	AND
				  tsoh.bra_id	= @bra_id	AND
				  tdf.sd_id		= 15		AND
				  tsod.curr_id  = @curr_id



		IF @OptionUpdate = 1
			--SUMAR PORCENTAJE
			BEGIN

				--SELECT 1
				UPDATE	dbo.tbSaleOrderDetail
					SET		sod_price = ISNULL(sod_price,0)  + (ISNULL(sod_price,0) * @ValueUpdate / 100)
					FROM dbo.tbSaleOrderDetail						tsod
					INNER JOIN #tmpMonthlyPayments					tmpmp
					ON tmpmp.comp_id		= tsod.comp_id	AND
					   tmpmp.bra_id			= tsod.bra_id	AND
					   tmpmp.soh_id			= tsod.soh_id	AND
					   tmpmp.sod_id			= tsod.sod_id

			END
		ELSE IF @OptionUpdate = 2
			--SUMAR IMPORTE
			BEGIN

				--SELECT 2
				UPDATE	dbo.tbSaleOrderDetail
					SET sod_price = ISNULL(sod_price,0) + @ValueUpdate
					FROM dbo.tbSaleOrderDetail						tsod
					INNER JOIN #tmpMonthlyPayments					tmpmp
					ON tmpmp.comp_id		= tsod.comp_id	AND
					   tmpmp.bra_id			= tsod.bra_id	AND
					   tmpmp.soh_id			= tsod.soh_id	AND
					   tmpmp.sod_id			= tsod.sod_id

			END

		ELSE
			--REEMPLAZAR
			BEGIN

				--SELECT 3
				UPDATE	dbo.tbSaleOrderDetail
					SET sod_price = @ValueUpdate
					FROM dbo.tbSaleOrderDetail						tsod
					INNER JOIN #tmpMonthlyPayments					tmpmp
					ON tmpmp.comp_id		= tsod.comp_id	AND
					   tmpmp.bra_id			= tsod.bra_id	AND
					   tmpmp.soh_id			= tsod.soh_id	AND
					   tmpmp.sod_id			= tsod.sod_id


			END




		IF @Round = 'True'
			BEGIN

				UPDATE	dbo.tbSaleOrderDetail
					SET		sod_price = CASE
											-- Redondeo de Item
											WHEN tsod.item_id IS NOT NULL	THEN	ROUND(dbo.fnGetPriceListItemTaxesCoeficient( tsod.comp_id, tsod.item_id) * ISNULL(sod_price,0),0) / dbo.fnNoZDiv(dbo.fnGetPriceListItemTaxesCoeficient( tsod.comp_id, tsod.item_id))
											-- Redondeo de Item Manual
											--WHEN ttn.tax_id   IS NOT NULL   THEN    ROUND(tsod.sod_price * (1+(ttn.tax_percentage / 100)),2) / dbo.fnNoZDiv(1+(ttn.tax_percentage / 100))
											-- Nunca deberia entrar x aca pero si enra no hace nada
											ELSE									Round(tsod.sod_price,0)
										END

					FROM dbo.tbSaleOrderDetail						tsod
					INNER JOIN #tmpMonthlyPayments					tmpmp
					--LEFT JOIN tbTaxName								ttn
					--	ON ttn.comp_id			= tsod.comp_id AND
					--	   ttn.tax_id			= tsod.sod_costTax
						ON tmpmp.comp_id		= tsod.comp_id	AND
						   tmpmp.bra_id			= tsod.bra_id	AND
						   tmpmp.soh_id			= tsod.soh_id	AND
						   tmpmp.sod_id			= tsod.sod_id

			END







		-- --------------------------------------------------------------------
		-- Recalcula los importes para dejarlos en la grilla de los pedidos
		-- Para los FORROS de LPNK
		-- --------------------------------------------------------------------

		DECLARE @soh_id		INT
		DECLARE @sod_id		INT
		DECLARE @user_id	INT

		DECLARE saleOrderCURSOR CURSOR LOCAL FAST_FORWARD FOR
			SELECT	tmp.comp_id,
					tmp.bra_id,
					tmp.soh_id,
					tmp.sod_id
				FROM #tmpMonthlyPayments tmp

		OPEN saleOrderCURSOR

		FETCH NEXT FROM saleOrderCURSOR
			INTO	@comp_id,
					@bra_id,
					@soh_id,
					@sod_id

		WHILE @@FETCH_STATUS = 0
			BEGIN

				--select
				--	@comp_id ,
				--	@bra_id,
				--	@soh_id


				-- Hacer esto para todos los abonos actualizados
				EXEC spSaleOrder_RecalculateTaxes
					@comp_id ,
					@bra_id,
					@soh_id,
					-1 ,
					2	-- español


				FETCH NEXT FROM saleOrderCURSOR
					INTO	@comp_id,
							@bra_id,
							@soh_id,
							@sod_id
			END



		CLOSE		saleOrderCURSOR
		DEALLOCATE	saleOrderCURSOR



		DROP TABLE #tmpMonthlyPayments
		-- --------------------------------------------------------------------

		COMMIT TRANSACTION
		Select 'True'
	END TRY
	BEGIN CATCH
		ROLLBACK TRANSACTION
		Select 'False'
	END CATCH





END
GO



