-- 02/01/17
---

CREATE  PROCEDURE [dbo].[spSaleOrderDetail_MontlyPayments_UpdateData_ChangeItems]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT,
	@df_id					INT, -- documentos
	@item_id_from			INT, -- que contegan este item
	@item_id_to				INT, -- al item
	@chkreplaceprices		BIT  -- reemplazar los precios de la lista
)
as


BEGIN
	-------------------------------------------------------------------------------------------------
	--TESTING
	-------------------------------------------------------------------------------------------------
	/*
	DECLARE
			@comp_id				INT,
			@lang_id				INT,
			@bra_id					INT,
			@prof_id				INT,
			@user_id				INT,
			@df_id					INT, -- documentos
			@item_id_from			INT, -- que contegan este item
			@item_id_to				INT, -- al item
			@chkreplaceprices		BIT  -- reemplazar los precios de la lista

	SELECT
			@comp_id				= 1,
			@lang_id				= 2,
			@bra_id					= 1,
			@guid4Cust				= 'BE41D364-AD65-4FC0-960B-6C036FF5D1C9',
			@guid4Item				= 'BE41D364-AD65-4FC0-960B-6C036FF5D1C9',
			@OptionUpdate			= 1,
			@ValueUpdate			= 20,
			@Round					='FALSE'

	*/
	-------------------------------------------------------------------------------------------------
	-------------------------------------------------------------------------------------------------


	IF @chkreplaceprices = 'True'
		BEGIN

			UPDATE tbsaleorderdetail	 WITH (ROWLOCK)
				SET		item_id			= @item_id_to,
						sod_itemDesc	= ti.item_desc ,
						sod_price		= tpli.prli_price,
						curr_id			= tpli.curr_id
				FROM tbsaleorderdetail sod
				INNER JOIN tbSaleOrderHeader tsoh						WITH (NOLOCK)
					ON	tsoh.comp_id	= sod.comp_id	AND
						tsoh.bra_id		= sod.bra_id	AND
						tsoh.soh_id		= sod.soh_id
				INNER JOIN tbItem ti									WITH (NOLOCK)
					ON	ti.comp_id		= @comp_id AND
						ti.item_id		= @item_id_to
				INNER JOIN tbPriceListItems tpli						WITH (NOLOCK)
					ON	tpli.comp_id	= sod.comp_id	AND
						tpli.prli_id	= sod.prli_id	AND
						tpli.item_id	= sod.item_id
				WHERE	sod.comp_id		= @comp_id		AND
						sod.bra_id		= @bra_id		AND
						sod.item_id		= @item_id_from AND
						tsoh.df_id		= @df_id

		END
	ELSE
		BEGIN

			UPDATE tbsaleorderdetail	 WITH (ROWLOCK)
				SET		item_id			= @item_id_to,
						sod_itemDesc	= ti.item_desc
				FROM tbsaleorderdetail sod
				INNER JOIN tbSaleOrderHeader tsoh						WITH (NOLOCK)
					ON	tsoh.comp_id	= sod.comp_id	AND
						tsoh.bra_id		= sod.bra_id	AND
						tsoh.soh_id		= sod.soh_id
				INNER JOIN tbItem ti									WITH (NOLOCK)
					ON	ti.comp_id		= @comp_id AND
						ti.item_id		= @item_id_to

				WHERE	sod.comp_id		= @comp_id		AND
						sod.bra_id		= @bra_id		AND
						sod.item_id		= @item_id_from AND
						tsoh.df_id		= @df_id

		END





END
GO



