--              MOS  06-18
-- ==============================================


CREATE PROCEDURE [dbo].[spSaleOrderDetail_recalculateComboCoeficient]
(
    @comp_id			INT,
	@bra_id				INT,
	@soh_id				INT
)

AS

BEGIN


	WITH saleOrderCTE(sod_tis_id_origin,Total)
		AS
			(
				SELECT  sod_tis_id_origin,
						SUM(tsod.sod_qty * tsod.sod_price)
					FROM tbSaleOrderDetail tsod		WITH (NOLOCK)
					WHERE	tsod.comp_id	= @comp_id	AND
							tsod.bra_id		= @bra_id	AND
							tsod.soh_id		= @soh_id	AND
							tsod.sod_tis_id_origin		IS NOT NULL AND
							tsod.sod_isParentAssociate	= 0
					GROUP BY tsod.sod_tis_id_origin
			)


	UPDATE tbsaleorderdetail
		SET sod_comboCoeficient =  sod_price / dbo.fnNoZDiv(Total)
		FROM tbSaleOrderDetail tsod	WITH (NOLOCK)
		INNER JOIN saleOrderCTE tmp	WITH (NOLOCK)
			ON tmp.sod_tis_id_origin = tsod.sod_tis_id_origin
		WHERE	tsod.comp_id	= @comp_id	AND
				tsod.bra_id		= @bra_id	AND
				tsod.soh_id		= @soh_id	AND
				tsod.sod_tis_id_origin		IS NOT NULL AND
				tsod.sod_isParentAssociate	= 0


END
GO




