CREATE PROCEDURE [dbo].[spSaleOrderDetail_Report]
(

	@comp_id						int,
	@lang_id						int,
	@page_id						int,


	@CustomerGuid					VARCHAR(50),					-- CF Customers
	@SupplierGuid					VARCHAR(50),					-- CF Proveedores de Artículos??
	@ItemGuid						VARCHAR(50),					-- CF Items

	@datefrom						datetime,						-- Fecha de Pedido Desde
	@dateto							datetime,						-- Fecha de Pedido Hasta

	@datefromDelivery				datetime,						-- Fecha de Entrega de Pedido Desde
	@datetoDelivery					datetime,						-- Fecha de Entrega de Pedido Hasta

	@datefromItemDelivery			datetime,						-- Fecha de Entrega del Artículo Desde
	@datetoItemDelivery				datetime,						-- Fecha de Entrega del Artículo Hasta

	@sm_id							int,							-- Vendedor
	@user_id						int,							-- Usuario
	@disc_id						int,							-- Descuento
	@dl_id							int,							-- Entrega
	@df_id							int,							-- Documento a emitir
	@stor_id						int,							-- Deposito

	@Stock							int,							-- Stock  = -1 = Todos, 1 = Sólo con Stock Físico, 2 = Sólo con Stock Disponible
	@Orderby						int,							-- Ordenar por
	        						    							--	1 = Alfabeticamente
	        						    							--	2 = N° de Pedido
	        						    							--	3 = Entrega del Pedido
	        						    							--	4 = Entrega del Artículo

	@Status							INT,							-- Estado de Pedido = -1 = Todos , 1 = Pendientes de Autorizar , 2 = No Pendientes de Autorizar
	@ssos_id						INT,							-- Tipo

	@bra_id							INT,							-- Sucursal -1 = Todos
	@sd_id							INT,							-- -1:todos traer de la traduccion de tbsysdocuments con 1 x defecto( Facturas )  TIPO DE DOCUMENTO

	@delivery_type					INT	,							-- Envío, -1 Todos , 1 Retira ya, 2 envio , etc

	@intBranch4Lang					int
)

AS

SET NOCOUNT ON


--SET DATEFORMAT 'ymd'

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


--------------------------------------------------------------------------------
-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
--------------------------------------------------------------------------------
/*
DECLARE
	@comp_id						int,
	@lang_id						int,
	@page_id						int,


	@CustomerGuid					VARCHAR(50),					-- CF Customers
	@SupplierGuid					VARCHAR(50),					-- CF Proveedores de Artículos??
	@ItemGuid						VARCHAR(50),					-- CF Items

	@datefrom						datetime,						-- Fecha de Pedido Desde
	@dateto							datetime,						-- Fecha de Pedido Hasta

	@datefromDelivery				datetime,						-- Fecha de Entrega de Pedido Desde
	@datetoDelivery					datetime,						-- Fecha de Entrega de Pedido Hasta

	@datefromItemDelivery			datetime,						-- Fecha de Entrega del Artículo del Pedido Desde
	@datetoItemDelivery				datetime,						-- Fecha de Entrega del Artículo del Pedido Hasta

	@sm_id							int,
	@user_id						int,
	@disc_id						int,
	@dl_id							int,
	@df_id							int,							-- Documento
	@stor_id						int,
	@st_id							INT,
	@ssos_id						INT,							-- Tipo

	@stock							int,							-- Stock  = -1 = Todos, 1 = Sólo con Stock Físico, 2 = Sólo con Stock Disponible
	@Orderby						int,							-- Ordenar por
	        						    							--	1 = Alfabeticamente
	        						    							--	2 = N° de Pedido
	        						    							--	3 = Entrega del Pedido
	        						    							--	4 = Entrega del Artículo


	@bra_id							INT,							-- Sucursal -1 = Todos
	@sd_id							INT,							-- -1:todos traer de la traduccion de tbsysdocuments con 1 x defecto( Facturas )  TIPO DE DOCUMENTO

	@intBranch4Lang					int




SELECT	@comp_id			=1,
		@lang_id			=2,
		@page_id			=10069,

		@user_id            = -1,
		@sm_id				= -1,
		@disc_id			= -1,
		@stor_id			= -1,
		@datefrom			='2000-01-01',
		@dateto				='9999-12-31',
		@datefromDelivery			='2000-01-01',
		@datetoDelivery				='9999-12-31',
		@datefromItemDelivery			='2000-01-01',
		@datetoItemDelivery				='9999-12-31',

		@ssos_id			= 1000,
		@dl_id				= -1,
		@df_id				= -1,
		@st_id				= -1,
		@bra_id				= -1,
		@sd_id = -1

*/
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------




		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @lGuidCustomer AS UNIQUEIDENTIFIER
		SET		@lGuidCustomer = CONVERT(UNIQUEIDENTIFIER,@CustomerGuid)
		DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Customer
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuidCustomer     AND
							  tcf.sl_selected = 'True'
		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Customer
					SELECT tc.cust_id
					FROM tbCustomer tc
					WHERE tc.comp_id = @comp_id
			END
		-- -------------------------------------------------------------

		 -- -------------------------------------------------------------
		 -- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
		 -- -------------------------------------------------------------
		 DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
		 INSERT INTO @tblComplexFilter_Supplier
		  SELECT tcf.sl_id
		   FROM tbComplexFilter tcf
		   WHERE tcf.sl_guid = @SupplierGuid     AND
				tcf.sl_selected = 'True'
		 IF @@ROWCOUNT = 0
		  BEGIN
		   INSERT INTO @tblComplexFilter_Supplier
				SELECT ts.supp_id
					FROM tbSupplier ts
						WHERE ts.comp_id = @comp_id
		  END
		 -- -------------------------------------------------------------

		-- -------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Items para Filtros #8600
		-- -------------------------------------------------------------
		DECLARE @lGuidItems AS UNIQUEIDENTIFIER
		SET		@lGuidItems = CONVERT(UNIQUEIDENTIFIER,@ItemGuid)
		DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
		INSERT INTO @tblComplexFilter_Items
			SELECT tcf.sl_id
				FROM tbComplexFilter tcf
				WHERE tcf.sl_guid = @lGuidItems     AND
							  tcf.sl_selected = 'True'

		IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ts.item_id
					FROM tbItem ts
						WHERE ts.comp_id = @comp_id
			END
		-- -------------------------------------------------------------




		set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
		set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

		set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefromDelivery,'False')
		set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@datetoDelivery,'True')

		set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefromItemDelivery,'False')
		set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@datetoItemDelivery,'True')


	select
			convert(varchar,bra.bra_id) + '-' + convert(varchar,tsoh.soh_id)	[idPedido],
			bra.bra_desc														[Sucursal],

			tsoh.soh_internalAnnotation											[AnotacionInterna],
			--td.disc_desc,
			sm.sm_name															[Vendedor],
			us.user_lastname + ', ' + user_firstname							[Usuario],
			ts.stor_desc														[Deposito],
			tsos.ssos_desc														[Estado],
			CONVERT(VARCHAR,cu.cust_id)											[idCliente],
			cu.cust_name														[Cliente],
			tsoh.soh_deliveryDate												[entregaPedido],
			tsod.sod_itemDeliveryDate											[entregaArticulo],
			ISNULL(tov2.optval_desc,'')											[envioArticulo],

			ti.item_code														[Codigo],
			ti.item_desc														[Descripcion],
			tsod.sod_itemDesc													[descripcionPedido],
			tsod.sod_detail														[detallePedido],
			tsod.sod_initQty													[cantidadInicial],
			tsod.sod_qty														[cantidadPendiente],
			tpl.prli_desc														[Lista],
			dbo.fnGetStock(tsod.comp_id,tsod.stor_id,tsod.item_id)				[stockFisico],
			dbo.fnGetAStock(tsod.comp_id,tsod.stor_id ,tsod.item_id, tsod.sod_priority)
																				[stockDisponible],
			tsod.sod_price														[itemPrecio],
			tsod.sod_discountByItem												[descuentoItem],
			tsod.sod_discountByTotal											[descuentoPedido],
			tsod.sod_creditInt													[Interes],
			tsod.sod_creditIntPlus												[InteresAdicional],
			tsod.sod_discountPlan												[descuentoPlan],
			tsod.sod_priceNeto													[precioNeto],
			(
				tsod.sod_priceNeto +
				(
					SELECT SUM(tsot.tm_total)
						FROM tbSaleOrderTaxes							tsot	WITH (NOLOCK)
						WHERE		tsot.comp_id			= tsod.comp_id
								AND tsot.bra_id				= tsod.bra_id
								AND tsot.soh_id				= tsoh.soh_id
								AND tsot.sod_id             = tsod.sod_id
				) / dbo.fnNoZDiv(tsod.sod_qty)
			)																	[itemTotal],
			cc.curr_symbol														[Moneda],

			-- tsoh.soh_deliveryAddress											[domicilioEntrega],
			CASE
				WHEN dbo.fnStrAllTrim(ISNULL(tsoh.soh_deliveryAddress,'')) <> ''	THEN tsoh.soh_deliveryAddress
				WHEN tcb.comp_id IS NOT NULL										THEN ISNULL(tcb.custb_address,'')	+ ' (' + ISNULL(tcb.custb_zip,'') + ') '	+ ISNULL(tcb.custb_city,'') + ' ' + ISNULL(tsB.state_desc,'')
				WHEN dbo.fnStrAllTrim(ISNULL(cu.cust_address4Delivery,'')) <> ''	THEN cu.cust_address4Delivery
				WHEN cu.comp_id  IS NOT NULL										THEN ISNULL(cu.cust_address,'')		+ ' (' + ISNULL(cu.cust_zip,'') + ') '		+ ISNULL(cu.cust_city,'')	+ ' ' + ISNULL(tsC.state_desc,'')
				ELSE '*'
			END																	[domicilioEntrega],
			tsoh.soh_cd															[altaPedido],
			tsod.sod_note1														[nota1],
			tsod.sod_note2														[nota2],
			tsoh.soh_observation1												[observacion1],
			tsoh.soh_observation2												[observacion2],
			tsoh.soh_observation3												[observacion3],
			tsoh.soh_observation4												[observacion4],
			--tsoh.soh_lastUpdate,
			--tsoh.soh_limitDate,
			--cc.curr_symbol [curr_desc],
			--tsot.tm_total,
            case when ti.item_expser = 'true' then
				(select tov.optval_desc
				from tbsysOptionsValues tov	WITH (NOLOCK)
				where tov.lang_id		= 2
				and   tov.optval_class  = 1
				and   tov.optval_id		= 1)
			else
				(select tov.optval_desc
				from tbsysOptionsValues  tov WITH (NOLOCK) where tov.lang_id = @lang_id and tov.optval_class = 1 and tov.optval_id = 0)
			end [Serializado],
			dbo.fnGetCommercialTransactionDescription(vr.comp_id,2, vr.ct_transaction_preInvoice)		[facturaAnticipada],
			tct2.ct_ATotal																				[Importe-FA],
			tct2.ct_ABalance																			[Saldo-FA],
			tc.curr_symbol																				[Moneda-FA]

			from tbSaleOrderHeader								tsoh	WITH (NOLOCK)

			inner join tbSaleOrderDetail						tsod	WITH (NOLOCK)
			on  tsod.comp_id			= tsoh.comp_id
			AND tsod.bra_id				= tsoh.bra_id
			AND tsod.soh_id				= tsoh.soh_id

			INNER JOIN tbDocumentsFile						 AS tdf		WITH (NOLOCK)
				ON	tdf.comp_id = tsoh.comp_id AND
					tdf.df_id	= tsoh.df_id


			left join tbItem									ti	WITH (NOLOCK)
			on  ti.comp_id				= tsod.comp_id
			AND ti.item_id				= tsod.item_id

			left JOIN @tblComplexFilter_Items 					tmpi
			ON tmpi.item_id				= ti.item_id

			LEFT  JOIN @tblComplexFilter_Supplier 				tmpsi
			ON tmpsi.supp_id			= ti.supp_id --OR
			   --ti.supp_id				IS NULL


			left join tbSalesman								sm	WITH (NOLOCK)
			on  sm.comp_id				= tsoh.comp_id
			and sm.sm_id				= tsoh.sm_id

			left join tbCustomer								cu	WITH (NOLOCK)
			on  cu.comp_id				= tsoh.comp_id
			and cu.cust_id				= tsoh.cust_id

			LEFT JOIN tbsysState AS tsC	WITH (NOLOCK)
				ON	tsC.country_id		= cu.country_id AND
					tsC.state_id		= cu.state_id


			LEFT JOIN tbCustomerBranch						AS tcb	WITH (NOLOCK)
				ON	tcb.comp_id = tsoh.comp_id AND
					tcb.cust_id = tsoh.cust_id AND
					tcb.cb_id	= tsoh.cb_id


			LEFT JOIN tbsysState AS tsB	WITH (NOLOCK)
				ON	tsB.country_id		= tcb.country_id AND
					tsB.state_id		= tcb.state_id


			INNER JOIN @tblComplexFilter_Customer				tmpS
			ON tmpS.cust_id				= cu.cust_id

			inner join dbo.tbBranch								bra	WITH (NOLOCK)
			on	bra.comp_id				= tsoh.comp_id
			And bra.bra_id				= tsoh.bra_id

			left join dbo.tbUser								us	WITH (NOLOCK)
			on	us.[user_id]			= tsoh.[user_id]

			left join tbsysCurrency								cc	WITH (NOLOCK)
			ON	cc.curr_id				= cu.curr_id



			left join tbStorage									ts	WITH (NOLOCK)
			on  ts.comp_id				= tsod.comp_id
			AND ts.stor_id				= tsod.stor_id

			LEFT JOIN tbPriceList							AS tpl	WITH (NOLOCK)
				ON	tpl.comp_id = tsod.comp_id AND
					tpl.prli_id = tsod.prli_id

			--inner join tbSaleOrderTaxes							tsot	WITH (NOLOCK)
			--on  tsot.comp_id			= tsod.comp_id
			--AND tsot.bra_id				= tsod.bra_id
			--AND tsot.soh_id				= tsoh.soh_id
			--AND tsot.sod_id             = tsod.sod_id

			inner join tbsysSaleOrderStatus						tsos	WITH (NOLOCK)
			on  tsos.ssos_id			= tsoh.ssos_id

			left join tbDiscount								td	WITH (NOLOCK)
			on	td.comp_id				= tsoh.comp_id
			and td.disc_id				= tsoh.disc_id

			LEFT JOIN tbsysOptionsValues AS tov2	WITH (NOLOCK)
				ON	tov2.lang_id		= bra.lang_id		AND
					tov2.optval_class	= 520				AND
					tov2.optval_id		= tsod.sdlmt_id

			LEFT JOIN vwCommercialTransactions_preInvoice_PackingListRelation vr	WITH (NOLOCK)
				ON	vr.comp_id	= tsod.comp_id	AND
					vr.bra_id	= tsod.bra_id	AND
					vr.soh_id	= tsod.soh_id	AND
					vr.sod_id	= tsod.sod_id

			LEFT JOIN tbCommercialTransactions AS tct2	WITH (NOLOCK)
				ON	tct2.comp_id		= vr.comp_id		AND
					tct2.ct_transaction = vr.ct_transaction_preInvoice

			LEFT JOIN tbsysCurrency AS tc	WITH (NOLOCK)
				ON tc.curr_id = tct2.ct_ACurrency

			WHERE	tsoh.comp_id	=	@comp_id
			AND 	(@ssos_id		= 1000 OR
					 @ssos_id		= 0	   OR
					 @ssos_id		= 1001 OR
					 @ssos_id		= 1002 OR
					 @ssos_id		= 1003 OR
					 tsoh.ssos_id	=	@ssos_id)
			AND		(@sd_id = -1		   OR tdf.sd_id		= @sd_id)
			AND		(tmpi.item_id IS NOT NULL  OR tsod.item_id IS NULL		)
			AND		(tmpsi.supp_id IS NOT NULL OR tsod.item_id IS NULL		)
			AND		(@user_id	    = -1   OR us.[user_id]	=	@user_id	)
			AND		(@sm_id			= -1   OR sm.sm_id		=	@sm_id		)
			AND		(@stor_id		= -1   OR ts.stor_id	=	@stor_id    )
			AND		(@disc_id		= -1   OR td.disc_id	=	@disc_id	)
			AND		(@dl_id			= -1   OR tsoh.dl_id	=	@dl_id		)
			AND		(@df_id			= -1   OR tsoh.df_id	=	@df_id		)
			AND		(@bra_id		= -1 OR tsoh.bra_id = @bra_id)
			AND		(tsoh.soh_cd		between @datefrom  and	@dateto)
			AND		(tsoh.soh_deliveryDate BETWEEN @datefromDelivery AND @datetoDelivery)
			--AND		(tsod.sod_itemDeliveryDate BETWEEN @datefromItemDelivery AND @datefromItemDelivery )-- fecha de entrega del articulo

			AND		(@delivery_type			= -1   OR tsod.sdlmt_id		=	@delivery_type		)

			AND		(
					CASE
						WHEN @Status = -1														THEN 1
						WHEN @Status =  1 AND  EXISTS(	SELECT TOP 1  1
															FROM tbSaleOrderStatus tsos			WITH (NOLOCK)
					                              			WHERE	tsos.comp_id	= tsoh.comp_id
					                              				AND tsos.bra_id		= tsoh.bra_id
					                              				AND tsos.soh_id		= tsoh.soh_id
					                              				AND tsos.sos_ok		= 'False')	THEN 1 --  Pendientes de Autorizacion.
						WHEN @Status =  2 AND NOT EXISTS(	SELECT TOP 1 1
															FROM tbSaleOrderStatus tsos			WITH (NOLOCK)
					                              			WHERE	tsos.comp_id	= tsoh.comp_id
					                              				AND tsos.bra_id		= tsoh.bra_id
					                              				AND tsos.soh_id		= tsoh.soh_id
					                              				AND tsos.sos_ok		= 'False')	THEN 1 --  Pendientes de Autorizacion.
						ELSE																		 0
					END	 = 1
					)	AND

				CASE	-- Stock  = -1 = Todos, 1 = Sólo con Stock Físico, 2 = Sólo con Stock Disponible
					WHEN @Stock = -1																					THEN 1
					WHEN @Stock = 1 AND dbo.fnGetStock(tsod.comp_id,tsod.stor_id,tsod.item_id) > 0						THEN 1
					WHEN @Stock = 2 AND dbo.fnGetAStock(tsod.comp_id,tsod.stor_id ,tsod.item_id, tsod.sod_priority) > 0 THEN 1
					ELSE 0
				END = 1


				AND tsod.sod_itemDeliveryDate BETWEEN @datefromItemDelivery AND @datetoItemDelivery -- fecha de entrega del articulo

		ORDER BY
			CASE
				WHEN @Orderby = 1 THEN CONVERT(VARCHAR,tsod.sod_itemDesc)
				WHEN @Orderby = 2 THEN CONVERT(VARCHAR,tsod.soh_id)
				WHEN @Orderby = 3 THEN CONVERT(VARCHAR,tsoh.soh_deliveryDate)
				WHEN @Orderby = 4 THEN CONVERT(VARCHAR,tsod.sod_itemDeliveryDate)
			END,tsod.soh_id,tsod.sod_id
																	--	1 = Alfabeticamente
	        						    							--	2 = N° de Pedido
	        						    							--	3 = Entrega del Pedido
	        						    							--	4 = Entrega del Artículo


exec [spReports_getData3]@comp_id,@intBranch4Lang,@lang_id,@page_id



/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

SELECT	(SELECT tswn.word_desc FROM [tbsysTextsNew] t
			INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 174 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)				[params1],

		 ' '									[params2],


	(SELECT tswn.word_desc FROM [tbsysTextsNew] t
			INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 103 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)				[params3],

		 ' '									[params4],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =1 )									[params5],

      		-- @datefrom [DateParams1],
			convert(varchar,day(@datefrom))+'/'+convert(varchar,month(@datefrom))+'/'+convert(varchar,year(@datefrom))		[DateParams1],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			 WHERE t.ctrl_id = 384
      			 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =1 )								[params6],

      			-- @dateto [DateParams2],
convert(varchar,day(@dateto))+'/'+convert(varchar,month(@dateto))+'/'+convert(varchar,year(@dateto))		[DateParams2],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t
			INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 172 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)				[params7],

		 CASE @sm_id WHEN -1
			THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
			    		WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE	(Select	ts.sm_name FROM tbSalesman ts
						WHERE ts.comp_id = @comp_id AND ts.sm_id= @sm_id) END											[params8],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 1 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params9],

		 CASE @user_id WHEN -1
			THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    			WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE	(Select	tu.user_lastname + ', ' + tu.user_firstname [User_Name] FROM tbUser tu
						WHERE tu.comp_id = @comp_id AND tu.[user_id]= @user_id) END										[params10],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 173 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params11],

		 CASE @disc_id WHEN -1
			THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    			WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE	(Select td.disc_desc FROM tbDiscount td
						WHERE td.comp_id = @comp_id AND td.disc_id= @disc_id) END										[params12],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 170 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params13],

		 CASE @dl_id WHEN -1
			THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    			WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE	(Select td.dl_name FROM tbDelivery td
						WHERE td.comp_id = @comp_id AND td.dl_id= @dl_id) END											[params14],


		(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 171 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params15],

		 CASE @df_id WHEN -1
			THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    			WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE	(Select tdf.df_desc FROM tbDocumentsFile tdf
						WHERE tdf.comp_id = @comp_id AND tdf.df_id= @df_id) END											[params16],



		(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 111 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params17],

		 CASE @stor_id WHEN -1
			THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    			WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE	(Select ts.stor_desc FROM tbStorage ts
						WHERE ts.comp_id = @comp_id AND ts.stor_id= @stor_id) END										[params18],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 225 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params19],

		 ' '										[params20],

	(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 116 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params21],

		 CASE @ssos_id WHEN -1
			THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
		    			WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE	(select DISTINCT tov.optval_desc from tbsysOptionsValues tov
					  where tov.optval_id = @ssos_id and tov.optval_class = 110 and tov.lang_id=@lang_id)		END				[params22]


--WHERE vsos.comp_id = @comp_id AND vsos.ssos_id = @ssos_id and vsos.lang_id = @lang_id
GO






