CREATE  PROCEDURE [dbo].[spSaleOrderDetail_updateData]
(
	@bra_id			int,
    @soh_id			int,
	@sod_id			int,
    @sod_priority	decimal(14,4),
    @item_id		int,
    @sod_itemDesc	varchar(100),
	@sod_detail		varchar(100),
	@curr_id		int,
	@sod_initQty	decimal(19,5),
	@sod_qty		decimal(19,5),
	@prli_id		int,
	@sod_price		decimal(19,6),
	@stor_id		int
)
as

update	dbo.tbSaleOrderDetail	WITH (ROWLOCK)

set	    bra_id			= @bra_id,
		soh_id			= @soh_id,
        sod_priority	= @sod_priority,
		item_id			= @item_id,
		sod_itemDesc	= @sod_itemDesc,
		sod_detail		= @sod_detail,
		curr_id			= @curr_id,
		sod_initQty		= @sod_initQty,
		sod_qty			= @sod_qty,
		prli_id			= @prli_id,
		sod_price		= @sod_price,
		stor_id			= @stor_id


where	sod_id			= @sod_id


GO



CREATE PROCEDURE [dbo].[spSaleOrderDetail_UpdateSODItems_IsTransfered2Branch]
(
	@comp_id INT,
	@bra_id INT,
	@soh_id INT,
	@sod_id INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------
		-- TESTING
		-- --------------------------------
		/*
			DECLARE
				@comp_id INT,
				@bra_id INT,
				@soh_id INT,
				@sod_id INT

			SELECT
				@comp_id		=1,
				@bra_id			=1,
				@soh_id			=10084,
				@stor_id		=19,
				@user_id		=1,
				@return_value	=0
		*/
		-- --------------------------------
		UPDATE dbo.tbSaleOrderDetail		WITH(ROWLOCK)
			SET sod_PCCOnfigIsTransfered2Branch = 'True'
			WHERE	comp_id = @comp_id AND
					bra_id  = @bra_id  AND
					soh_id  = @soh_id  AND
					sod_id  = @sod_id

END

GO



CREATE PROCEDURE [dbo].[spSaleOrderDetail_UpdateSOPS]
(
	@comp_id			INT,
	@bra_id				INT,
	@soh_id				INT,
	@sod_id				INT,
	@sops_id			INT,
	@sops_supp_id		INT,
	@sops_bra_id		INT,
	@sops_date			DATETIME,
	@sops_poh_bra_id	INT,
	@sops_poh_id		INT,
	@sops_note			NVARCHAR(500),
	@sops_user_id		INT,
	@sops_lastUpdate	DATETIME,
	@prof_id			INT



)
AS


BEGIN

SET NOCOUNT ON

set dateformat 'ymd'

---------------------------------------------------------------------------------------------------------------------------
--testing
---------------------------------------------------------------------------------------------------------------------------
/*

DECLARE
		@comp_id			INT,
		@bra_id				INT,
		@soh_id				INT,
		@sod_id				INT,
		@sops_id			INT,
		@sops_supp_id		INT,
		@sops_bra_id		INT,
		@sops_date			DATETIME,
		@sops_poh_bra_id	INT,
		@sops_poh_id		INT,
		@sops_note			NVARCHAR(500),
		@sops_user_id		INT,
		@sops_lastUpdate	DATETIME,
		@prof_id			INT

SELECT 	@comp_id			=1,
		@bra_id				=1,
		@soh_id				=34062,
		@sod_id				=30621,
		@sops_id			=9,
		@sops_supp_id		=-1,
		@sops_bra_id		=-1,
		@sops_poh_bra_id	=0,
		@sops_poh_id		=0,
		@sops_note			='',
		@sops_user_id		=1,
		@prof_id			=1,
		@sops_date			= '01/01/2000',
		@sops_lastUpdate	= '01/01/2000'


*/
---------------------------------------------------------------------------------------------------------------------------
---------------------------------------------------------------------------------------------------------------------------



	-- ----------------------------------------------------------------------
	if	(@sops_id		= -1)		set	@sops_id			= NULL
	if	(@sops_supp_id	= -1)		set	@sops_supp_id		= NULL
	if	(@sops_bra_id	= -1)		set	@sops_bra_id		= NULL

	if	(@sops_poh_bra_id	= 0)	set	@sops_poh_bra_id	= NULL
	if	(@sops_poh_id	= 0)		set	@sops_poh_id		= NULL

	-- ----------------------------------------------------------------------


	--------------------------------------------------------------------------------
	--Actualizamos el Motivo

	UPDATE	dbo.tbSaleOrderDetail

	SET		sops_id				= @sops_id,
			sops_supp_id		= @sops_supp_id,
			sops_bra_id			= @sops_bra_id,
			sops_date			= @sops_date,
			sops_poh_bra_id		= @sops_poh_bra_id,
			sops_poh_id			= @sops_poh_id,
			sops_note			= @sops_note,
			sops_user_id		= @sops_user_id,
			sops_lastUpdate		= @sops_lastUpdate


	WHERE	comp_id = @comp_id	AND
			bra_id	= @bra_id	AND
			sod_id	= @sod_id	AND
			soh_id	= @soh_id

	--------------------------------------------------------------------------------



	DECLARE
			@ldf_id_soh				INT,	--Doc del pedido
			@ldf_id_new_reason		INT,	--Doc nuevo destino de tbSaleOrderPendingReasonDivideByDocument
			@lsoh_id_new			INT,	--ID del pedido nuevo
			@lbra_id_df_destiny		INT		--Sucursal del Documento Destino

	SET		@ldf_id_soh				= 0
	SET		@lsoh_id_new			= 0
	SET		@ldf_id_new_reason		= 0
	SET		@lbra_id_df_destiny		= 0



	SELECT
		@ldf_id_soh			=  tsoh.df_id
		FROM tbSaleOrderHeader					tsoh	WITH(NOLOCK)
		WHERE tsoh.comp_id	= @comp_id	AND
			  tsoh.bra_id	= @bra_id	AND
			  tsoh.soh_id   = @soh_id


	SELECT
		@ldf_id_new_reason =  tsoprdbd.df_id_destiny
		FROM tbSaleOrderPendingReasonDivideByDocument	tsoprdbd	WITH(NOLOCK)
		WHERE tsoprdbd.comp_id			 = @comp_id		AND
		      tsoprdbd.sops_id			 = @sops_id		AND
		      tsoprdbd.df_id_origin		 = @ldf_id_soh	AND
		      tsoprdbd.prof_id			 = @prof_id		AND
			  tsoprdbd.sopsr_isDisabled	 = 'False'



		SELECT
			@lbra_id_df_destiny			=  tdf.bra_id
			FROM tbDocumentsFile				tdf				WITH(NOLOCK)
			WHERE tdf.comp_id	= @comp_id	AND
				  tdf.df_id		= @ldf_id_new_reason


		IF @ldf_id_new_reason IS NOT NULL AND @ldf_id_new_reason <> 0 AND @ldf_id_soh <> @ldf_id_new_reason
			BEGIN

				EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @lsoh_id_new OUTPUT

				--Insertar un nuevo soh con el @lbra_id_df_destiny y @ldf_id_new_reason y @lsoh_id_new
				--SELECT 1,@ldf_id_new_reason,@ldf_id_soh

					INSERT INTO tbSaleOrderHeader
						(
							comp_id,
							bra_id,
							soh_id,
							soh_cd,
							soh_deliveryDate,
							soh_observation1,
							soh_observation2,
							soh_observation3,
							soh_observation4,
							soh_quotation,
							sm_id,
							cust_id,
							st_id,
							disc_id,
							dl_id,
							cb_id,
							soh_lastUpdate,
							soh_limitDate,
							tt_id,
							tt_class,
							soh_StatusOf,
							[user_id],
							soh_isEditing,
							soh_isEditingCd,
							df_id,
							soh_total,
							ssos_id,
							soh_ExchangeToCustomerCurrency,
							chp_id,
							soh_PL_df_Id,
							soh_CustomerCurrency,
							soh_WithCollection,
							soh_WithCollectionGUID,
							soh_discount,
							soh_loan,
							soh_packagesQty,
							soh_internalAnnotation,
							curr_id4Exchange,
							curr_idExchange,
							soh_ATotal,
							df_id4PL,
							somp_id,
							soh_FEIdNumber,
							soh_inCash,
							custf_id,
							cust_id_guarantor,
							ccp_id,
							soh_MLdeliveryLabel,
							soh_deliveryAddress,
							soh_MLQuestionsAndAnswers,
							soh_MLId,
							soh_MLGUIA,
							pro_id,
							aux_collectionInterest_lastCTTransaction,
							ws_cust_Id,
							ws_internalID,
							ws_paymentGateWayStatusID,
							ws_paymentGateWayReferenceID,
							ws_IPFrom,
							ws_st_id,
							ws_dl_id,
							soh_htmlNote,
							prli_id,
							stor_id,
							mlo_id
						)
				SELECT
							comp_id,
							@lbra_id_df_destiny,		-- Sucursal destino
							@lsoh_id_new,				-- Pedido Nuevo
							GETDATE(),
							soh_deliveryDate,
							soh_observation1,
							soh_observation2,
							soh_observation3,
							soh_observation4,
							soh_quotation,
							sm_id,
							cust_id,
							st_id,
							disc_id,
							dl_id,
							cb_id,
							soh_lastUpdate,
							soh_limitDate,
							tt_id,
							tt_class,
							soh_StatusOf,
							[user_id],
							soh_isEditing,
							soh_isEditingCd,
							@ldf_id_new_reason,			-- Documento destino
							soh_total,
							ssos_id,
							soh_ExchangeToCustomerCurrency,
							chp_id,
							soh_PL_df_Id,
							soh_CustomerCurrency,
							soh_WithCollection,
							soh_WithCollectionGUID,
							soh_discount,
							soh_loan,
							soh_packagesQty,
							soh_internalAnnotation,

							curr_id4Exchange,
							curr_idExchange,
							soh_ATotal,
							df_id4PL,
							somp_id,
							soh_FEIdNumber,
							soh_inCash,
							custf_id,
							cust_id_guarantor,
							ccp_id,
							soh_MLdeliveryLabel,
							soh_deliveryAddress,
							soh_MLQuestionsAndAnswers,
							tsoh.soh_MLId,
							tsoh.soh_MLGUIA,
							pro_id,
							aux_collectionInterest_lastCTTransaction,
							ws_cust_Id,
							ws_internalID,
							ws_paymentGateWayStatusID,
							ws_paymentGateWayReferenceID,
							ws_IPFrom,
							ws_st_id,
							ws_dl_id,
							soh_htmlNote,
							prli_id,
							stor_id,
							mlo_id

						FROM	tbSaleOrderHeader				tsoh		WITH(NOLOCK)

						WHERE	tsoh.comp_id	= @comp_id
						  AND	tsoh.bra_id		= @bra_id
						  AND	tsoh.soh_id		= @soh_id





				--detaila update del de arriba con bra nuevo y soh nuevo


				INSERT INTO tbSaleOrderDetail
							(
								comp_id,
								bra_id,
								soh_id,
								sod_priority,
								item_id,
								sod_itemDesc,
								sod_detail,
								curr_id,
								sod_initQty,
								sod_qty,
								prli_id,
								sod_price,
								stor_id,
								sod_lastUpdate,
								sod_isEditing,
								sod_insertDate,
								[user_id],
								sod_quotation,
								sod_isCredit,
								sod_cost,
								sod_costTax,
								rmah_id,
								rmad_id,
								sod_note1,
								sod_note2,
								sod_itemDiscount,
								sod_tis_id_origin,
								sod_item_id_origin,
								sod_isParentAssociate,
								is_id,
								it_transaction,
								sod_isMade,
								sod_expirationDate,
								acc_count_id,
								sod_packagesQty,
								item_id_EW,
								tis_idOfThisEW,
								camp_id,
								sdlmt_id,
								sreas_id,
								sod_loanNumberOfPays,
								sod_loanDateOfFirstPay,
								sod_loanDayOfMonthOfNextPays,
								sod_itemDeliveryDate,
								sod_idOfThisEW,
								sod_isFromPCConfigCTRLId,
								sod_EWAddress,
								sod_PCCOnfigIsTransfered2Branch,
								sod_MLCost,
								sod_itemAssociationCoeficient,
								ws_price,
								ws_curr_Id,
								mlo_id,
								sops_supp_id,
								sops_bra_id,
								sops_date,
								sod_MECost,
								sod_MPCost,
								sod_isDivided,
								sod_isDivided_Date,
								user_id_division,
								sodi_id,
								sod_isDivided_costCoeficient,
								sod_DeliveryCharge,
								sops_poh_bra_id,
								sops_poh_id,
								sops_note,
								sops_user_id,
								sops_lastUpdate,
								sops_id

							)
						SELECT  @comp_id,
								@lbra_id_df_destiny,	-- Sucursal Nuevo
								@lsoh_id_new,			-- Pedido Nuevo
								sod.sod_priority,
								sod.item_id,
								sod.sod_itemDesc,
								sod.sod_detail,
								sod.curr_id,
								sod.sod_qty,
								sod.sod_qty,
								sod.prli_id,
								sod.sod_price,
								sod.stor_id,
								sod.sod_lastUpdate,
								sod.sod_isEditing,
								sod.sod_insertDate,
								sod.[user_id],
								sod.sod_quotation,
								sod.sod_isCredit,
								sod.sod_cost,
								sod.sod_costTax,
								sod.rmah_id,
								sod.rmad_id,
								sod.sod_note1,
								sod.sod_note2,
								sod.sod_itemDiscount,
								sod.sod_tis_id_origin,
								sod.sod_item_id_origin,
								sod.sod_isParentAssociate,
								sod.is_id,
								sod.it_transaction,
								sod.sod_isMade,
								sod.sod_expirationDate,
								sod.acc_count_id,
								sod.sod_packagesQty,
								sod.item_id_EW,
								sod.tis_idOfThisEW,
								sod.camp_id,
								sod.sdlmt_id,
								sod.sreas_id,
								sod.sod_loanNumberOfPays,
								sod.sod_loanDateOfFirstPay,
								sod.sod_loanDayOfMonthOfNextPays,
								sod.sod_itemDeliveryDate,
								sod.sod_idOfThisEW,
								sod.sod_isFromPCConfigCTRLId,
								sod.sod_EWAddress,
								sod.sod_PCCOnfigIsTransfered2Branch,
								sod.sod_MLCost,
								sod.sod_itemAssociationCoeficient,
								sod.ws_price,
								sod.ws_curr_Id,
								sod.mlo_id,
								sod.sops_supp_id,
								sod.sops_bra_id,
								GETDATE(),
								sod.sod_MECost,
								sod.sod_MPCost,
								sod.sod_isDivided,
								sod.sod_isDivided_Date,
								sod.user_id_division,
								sod.sodi_id,
								sod.sod_isDivided_costCoeficient,
								sod.sod_DeliveryCharge,
								sod.sops_poh_bra_id,
								sod.sops_poh_id,
								sod.sops_note,
								sod.sops_user_id,
								sod.sops_lastUpdate,
								sod.sops_id


						FROM   dbo.tbSaleOrderDetail				sod		WITH (NOLOCK)

						WHERE 	sod.comp_id		= @comp_id
						AND 	sod.bra_id		= @bra_id
						AND 	sod.soh_id		= @soh_id
						AND		sod.sod_id		= @sod_id



				--UPDATE tbSaleOrderDetail
				--SET
				--	bra_id = @lbra_id_df_destiny,
				--	soh_id = @lsoh_id_new

				--WHERE 	comp_id		= @comp_id
				--AND 	bra_id		= @bra_id
				--AND 	soh_id		= @soh_id
				--AND		sod_id		= @sod_id


				----verficiar q el soh veijo no tiene nada en la detail lo borra


				--IF NOT EXISTS (SELECT
				--					 tsod.sod_id
				--					FROM tbSaleOrderDetail tsod		WITH (NOLOCK)
				--					WHERE 	tsod.comp_id		= @comp_id
				--					AND 	tsod.bra_id		= @bra_id
				--					AND 	tsod.soh_id		= @soh_id
				--					AND		tsod.sod_id		= @sod_id )

				EXEC dbo.spSaleOrderHistory_InsertFromSaleOrder @comp_id, @bra_id, @soh_id, '300',NULL,NULL, ''

				DELETE FROM tbSaleOrderAssemblyTurns
					WHERE	comp_id		= @comp_id	AND
							soh_bra_id	= @bra_id	AND
							soh_id		= @soh_id

				DELETE FROM tbAssembly_Turns4Assembly
					WHERE	comp_id		= @comp_id	AND
							bra_id		= @bra_id	AND
							soh_id		= @soh_id

				DELETE FROM tbSaleOrderLoan
					WHERE	comp_id		= @comp_id	AND
							bra_id		= @bra_id	AND
							soh_id		= @soh_id

				DELETE FROM tbSaleOrderTaxes
					WHERE	comp_id		= @comp_id	AND
							bra_id		= @bra_id	AND
							soh_id		= @soh_id

				DELETE FROM tbSaleOrderDetail
					WHERE	comp_id		= @comp_id	AND
							bra_id		= @bra_id	AND
							soh_id		= @soh_id

				DELETE FROM tbSaleOrderHeader
					WHERE	comp_id		= @comp_id	AND
							bra_id		= @bra_id	AND
							soh_id		= @soh_id



			END










END

GO




CREATE PROCEDURE [dbo].[spSaleOrderDetail_updateStorage4Transfer]
(
	@comp_id		INT,
	@bra_id			INT,
	@soh_id			INT,
	@stor_id		int,
	@user_id		INT,
	@return_value	INT output
)
AS
SET NOCOUNT ON



/*
DECLARE @comp_id		INT,
		@bra_id			INT,
		@soh_id			INT,
		@stor_id		INT,
		@user_id		INT,
		@return_value	INT
SELECT 	@comp_id		=1,
		@bra_id			=1,
		@soh_id			=10084,
		@stor_id		=19,
		@user_id		=1,
		@return_value	=0
*/





BEGIN TRANSACTION
BEGIN TRY


	DECLARE		@lsod_id								INT,
				@lstor_id								INT,
				@litem_id								INT,
				@lsod_qty								DECIMAL(19,5),
				@lsod_price								DECIMAL(19,5),
				@lcurr_id								INT,
				@ct_docNumber							INT,
				@processingDate							DATETIME,
				@curr_id_branch							INT,
				@curr_id_company						INT,
				@rv										INT,
				@ret_ErrorCode							INT,
				@ret_ErrorDescription					VARCHAR(200),
				@brach2companyexchange					DECIMAL(19,5),
				@now									DATETIME,
				@it_order								INT,
				@intDocumentNumber						INT,
				@ct_ACurrencyExchange					DECIMAL(19,4),
				@ct_Branch2CompanyCurrencyExchange		DECIMAL(19,4),
				@decStorePreviuos						DECIMAL(19,6)




	SET @now		= GETDATE()
	SET	@it_order	= 0




	-- si el pedido es de producción se realiza la misma operación pero con relación a los artículos asociados
	-- a los que están cargados en pedido
	IF EXISTS (
				SELECT TOP 1 	1
				FROM	tbSaleOrderHeader					tsoh	WITH(NOLOCK)
						INNER JOIN tbDocumentsFile			tdf		WITH(NOLOCK)
						ON	tdf.comp_id		= tsoh.comp_id
						AND	tdf.df_id		= tsoh.df_id
						AND tdf.sd_id		= 80
				WHERE	tsoh.comp_id		= @comp_id
				AND		tsoh.soh_id			= @soh_id

	)
	BEGIN

		/***********************************************************************************************************/
		-- se realiza el proceso para pedidos de producción, por lo que se debe tener en cuenta los artículos
		-- asociados al item cargado en el pedido


		-- si hay algún artículo del pedido con el dépósito diferente del seleccionado se realiza el proceso
		IF EXISTS (
					SELECT TOP 1 	1
					FROM	tbSaleOrderDetail				tsod		WITH(NOLOCK)
					WHERE	tsod.comp_id		= @comp_id
					AND		tsod.soh_id			= @soh_id
					AND		tsod.stor_id		<> @stor_id
					AND		NOT tsod.stor_id	IS NULL
				  )
		BEGIN



			/******************************************************************************************************/
			--generación del commercialtransaction relacionado al proceso


			EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 8, @ct_docNumber OUTPUT


			SELECT	@processingDate			= tb.bra_processingDate,
					@curr_id_branch			= tb.curr_id
				FROM	tbBranch tb		WITH(NOLOCK)
				WHERE	tb.comp_id	= @comp_id
				AND		tb.bra_id	= @bra_id


			SELECT	@curr_id_company		= curr_id
				FROM	tbCompany tc		WITH(NOLOCK)
				WHERE	tc.comp_id	= @comp_id


			SELECT @brach2companyexchange =
					dbo.fnGetExchange2(@comp_id,1,
										@curr_id_branch,@curr_id_company,
										@curr_id_branch,@curr_id_company, 1, 'false')


			EXEC spCommercialTransactions_InsertData
				@comp_id,
				@bra_id,
				@ct_docNumber,
				@processingDate,
				null,
				null,
				null,
				@user_id,
				0,
				0,
				0,
				0,
				@curr_id_branch,
				null,
				null,
				0,
				0,
				@curr_id_branch,
				0,
				null,  --df_id
				null,
				null,
				null,
				@curr_id_company,
				@brach2companyexchange,
				350,
				null,
				null,
				null,
				null,
				0,
				@rv OUTPUT,
				@ret_ErrorCode OUTPUT,
				@ret_ErrorDescription OUTPUT
			/******************************************************************************************************/






			DECLARE cursor_sod  CURSOR LOCAL FAST_FORWARD FOR
			SELECT	tsod.sod_id,		tsod.stor_id,
					tic.item_id_1,		tsod.sod_qty * tic.icomp_qty,
					tsod.sod_price,		tsod.curr_id

			FROM	tbSaleOrderDetail					tsod		WITH(NOLOCK)
					INNER JOIN tbItemComposition		tic		WITH(NOLOCK)
					ON	tic.comp_id = tsod.comp_id
					AND	tic.item_id = tsod.item_id

			WHERE	tsod.comp_id	= @comp_id
			AND		tsod.soh_id		= @soh_id
			AND		tsod.stor_id	<> @stor_id
			AND		not tsod.stor_id	IS NULL


			OPEN cursor_sod

			FETCH cursor_sod INTO @lsod_id, @lstor_id, @litem_id, @lsod_qty, @lsod_price, @lcurr_id

			WHILE @@FETCH_STATUS = 0
			BEGIN

				--SELECT @lsod_id, @lstor_id, @litem_id, @lsod_qty, @lsod_price, @lcurr_id





				/******************************************************************************************************/
				-- se quita el artículo al depósito original

				-- actualizar el depósito del artículo
				EXEC spItemStorage_insertData @comp_id, @litem_id, @lstor_id, 0


				-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
				SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
					FROM	tbItemStorage tis		WITH(NOLOCK)
					WHERE	tis.comp_id = @comp_id
					AND		tis.stor_id = @lstor_id
					AND		tis.item_id = @litem_id


				SET @it_order = @it_order + 1


				INSERT INTO tbItemTransactions
				(
					comp_id,				bra_id,						ct_transaction,
					item_id,				it_qty,						it_priceWithOutOthers,
					it_price,				curr_id,					it_exchangeToBranchCurrency,
					it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
					it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
					it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
					stor_id,				it_storePrevious,			prli_id,
					byor_id,				it_isProduction,			it_isAssociation,
					it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
					it_order,				so_id,						it_guarantee,
					it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
					it_CreditIntPlus,		puco_id,					it_poh_bra_id,
					it_poh_id,				it_soh_id,					it_sod_id,
					rmah_id,				rmad_id,					it_qty_rma,
					it_tis_id_aux
				)
				VALUES
				(
					@comp_id,				@bra_id,					@rv,
					@litem_id,				@lsod_qty * -1,				0,
					@lsod_price,			@lcurr_id,					@lcurr_id,
					0,						0,							0,
					0,						0,							0,
					@lsod_price,			@lcurr_id,				1,
					@lstor_id,				isnull(@decStorePreviuos,0),NULL,
					NULL,					'False',					'False',
					NULL,					@now,						NULL,
					@it_order,				NULL,						0,
					0,						0,							0,
					0,						NULL,						NULL,
					NULL,					NULL,						NULL,
					NULL,					NULL,						NULL,
					NULL
				)


				-- se quita el artículo al depósito del detalle del pedido
				UPDATE	tbItemStorage	WITH (ROWLOCK)
				SET		itst_cant	= itst_cant - @lsod_qty,
						itst_cd		= @now
				WHERE	comp_id		= @comp_id
				AND		stor_id		= @lstor_id
				AND		item_id		= @litem_id
				/******************************************************************************************************/





				/******************************************************************************************************/
				-- se agrega el artículo al depósito seleccionado


				-- actualizar el depósito del artículo
				EXEC spItemStorage_insertData @comp_id, @litem_id, @stor_id, 0



				-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
				SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
				FROM	tbItemStorage tis
				WHERE	tis.comp_id = @comp_id
				AND		tis.stor_id = @stor_id
				AND		tis.item_id = @litem_id


				SET @it_order = @it_order + 1


				INSERT INTO tbItemTransactions
				(
					comp_id,				bra_id,						ct_transaction,
					item_id,				it_qty,						it_priceWithOutOthers,
					it_price,				curr_id,					it_exchangeToBranchCurrency,
					it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
					it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
					it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
					stor_id,				it_storePrevious,			prli_id,
					byor_id,				it_isProduction,			it_isAssociation,
					it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
					it_order,				so_id,						it_guarantee,
					it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
					it_CreditIntPlus,		puco_id,					it_poh_bra_id,
					it_poh_id,				it_soh_id,					it_sod_id,
					rmah_id,				rmad_id,					it_qty_rma,
					it_tis_id_aux
				)
				VALUES
				(
					@comp_id,				@bra_id,					@rv,
					@litem_id,				@lsod_qty,					0,
					@lsod_price,			@lcurr_id,					@lcurr_id,
					0,						0,							0,
					0,						0,							0,
					@lsod_price,			@lcurr_id,				1,
					@stor_id,				isnull(@decStorePreviuos,0),NULL,
					NULL,					'False',					'False',
					NULL,					@now,						NULL,
					@it_order,				NULL,						0,
					0,						0,							0,
					0,						NULL,						NULL,
					NULL,					NULL,						NULL,
					NULL,					NULL,						NULL,
					NULL
				)


				-- se incorpora el artículo al depósito seleccionado
				UPDATE	tbItemStorage	WITH (ROWLOCK)
				SET		itst_cant	= itst_cant + @lsod_qty,
						itst_cd		= @now
				WHERE	comp_id		= @comp_id
				AND		stor_id		= @stor_id
				AND		item_id		= @litem_id
				/******************************************************************************************************/








				FETCH cursor_sod INTO @lsod_id, @lstor_id, @litem_id, @lsod_qty, @lsod_price, @lcurr_id

			END

			CLOSE cursor_sod
			DEALLOCATE cursor_sod




			/******************************************************************************************************/
			-- actualización del depósito del artículo en el pedido

			UPDATE	tbSaleOrderDetail	WITH (ROWLOCK	)
				SET		stor_id = @stor_id
				WHERE   comp_id = @comp_id
				AND		soh_id	= @soh_id
				AND		stor_id <> @stor_id
				AND		not stor_id IS NULL
			/******************************************************************************************************/




		END


	END

	ELSE

	BEGIN
		/***********************************************************************************************************/
		-- se realiza el proceso para pedidos que no son de producción


		-- si hay algún artículo del pedido con el dépósito diferente del seleccionado se realiza el proceso
		IF EXISTS (
					SELECT TOP 1 	1
						FROM	tbSaleOrderDetail				tsod		WITH(NOLOCK)
						WHERE	tsod.comp_id		= @comp_id
						AND		tsod.soh_id			= @soh_id
						AND		tsod.stor_id		<> @stor_id
						AND		NOT tsod.stor_id	IS NULL
				  )
		BEGIN



			/******************************************************************************************************/
			--generación del commercialtransaction relacionado al proceso


			EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 8, @ct_docNumber OUTPUT


			SELECT	@processingDate			= tb.bra_processingDate,
					@curr_id_branch			= tb.curr_id
				FROM	tbBranch tb		WITH(NOLOCK)
				WHERE	tb.comp_id	= @comp_id
				AND		tb.bra_id	= @bra_id


			SELECT	@curr_id_company		= curr_id
				FROM	tbCompany tc		WITH(NOLOCK)
				WHERE	tc.comp_id	= @comp_id


			SELECT @brach2companyexchange =
					dbo.fnGetExchange2(@comp_id,1,
										@curr_id_branch,@curr_id_company,
										@curr_id_branch,@curr_id_company, 1, 'false')


			EXEC spCommercialTransactions_InsertData
				@comp_id,
				@bra_id,
				@ct_docNumber,
				@processingDate,
				null,
				null,
				null,
				@user_id,
				0,
				0,
				0,
				0,
				@curr_id_branch,
				null,
				null,
				0,
				0,
				@curr_id_branch,
				0,
				null,  --df_id
				null,
				null,
				null,
				@curr_id_company,
				@brach2companyexchange,
				350,
				null,
				null,
				null,
				null,
				0,
				@rv OUTPUT,
				@ret_ErrorCode OUTPUT,
				@ret_ErrorDescription OUTPUT
			/******************************************************************************************************/





			DECLARE cursor_sod  CURSOR LOCAL FAST_FORWARD FOR
			SELECT	tsod.sod_id, tsod.stor_id, tsod.item_id, tsod.sod_qty,
					tsod.sod_price, tsod.curr_id
				FROM	tbSaleOrderDetail tsod		WITH(NOLOCK)
				WHERE	tsod.comp_id	= @comp_id
				AND		tsod.soh_id		= @soh_id
				AND		tsod.stor_id	<> @stor_id
				AND		not tsod.stor_id	IS NULL


			OPEN cursor_sod

			FETCH cursor_sod INTO @lsod_id, @lstor_id, @litem_id, @lsod_qty, @lsod_price, @lcurr_id

			WHILE @@FETCH_STATUS = 0
			BEGIN

				--SELECT @lsod_id, @lstor_id






				/******************************************************************************************************/
				-- se quita el artículo al depósito original

				-- actualizar el depósito del artículo
				EXEC spItemStorage_insertData @comp_id, @litem_id, @lstor_id, 0


				-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
				SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
					FROM	tbItemStorage tis		WITH(NOLOCK)
					WHERE	tis.comp_id = @comp_id
					AND		tis.stor_id = @lstor_id
					AND		tis.item_id = @litem_id


				SET @it_order = @it_order + 1


				INSERT INTO tbItemTransactions
				(
					comp_id,				bra_id,						ct_transaction,
					item_id,				it_qty,						it_priceWithOutOthers,
					it_price,				curr_id,					it_exchangeToBranchCurrency,
					it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
					it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
					it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
					stor_id,				it_storePrevious,			prli_id,
					byor_id,				it_isProduction,			it_isAssociation,
					it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
					it_order,				so_id,						it_guarantee,
					it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
					it_CreditIntPlus,		puco_id,					it_poh_bra_id,
					it_poh_id,				it_soh_id,					it_sod_id,
					rmah_id,				rmad_id,					it_qty_rma,
					it_tis_id_aux
				)
				VALUES
				(
					@comp_id,				@bra_id,					@rv,
					@litem_id,				@lsod_qty * -1,				0,
					@lsod_price,			@lcurr_id,					@lcurr_id,
					0,						0,							0,
					0,						0,							0,
					@lsod_price,			@lcurr_id,				1,
					@lstor_id,				isnull(@decStorePreviuos,0),NULL,
					NULL,					'False',					'False',
					NULL,					@now,						NULL,
					@it_order,				NULL,						0,
					0,						0,							0,
					0,						NULL,						NULL,
					NULL,					NULL,						NULL,
					NULL,					NULL,						NULL,
					NULL
				)


				-- se quita el artículo al depósito del detalle
				UPDATE	tbItemStorage	WITH (ROWLOCK)
					SET		itst_cant	= itst_cant - @lsod_qty,
							itst_cd		= @now
					WHERE	comp_id		= @comp_id
					AND		stor_id		= @lstor_id
					AND		item_id		= @litem_id
				/******************************************************************************************************/





				/******************************************************************************************************/
				-- agregamos el artículo al depósito seleccionado

				-- actualizar el depósito del artículo
				EXEC spItemStorage_insertData @comp_id, @litem_id, @stor_id, 0


				-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
				SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
					FROM	tbItemStorage tis		WITH(NOLOCK)
					WHERE	tis.comp_id = @comp_id
					AND		tis.stor_id = @stor_id
					AND		tis.item_id = @litem_id


				SET @it_order = @it_order + 1


				INSERT INTO tbItemTransactions
				(
					comp_id,				bra_id,						ct_transaction,
					item_id,				it_qty,						it_priceWithOutOthers,
					it_price,				curr_id,					it_exchangeToBranchCurrency,
					it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
					it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
					it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
					stor_id,				it_storePrevious,			prli_id,
					byor_id,				it_isProduction,			it_isAssociation,
					it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
					it_order,				so_id,						it_guarantee,
					it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
					it_CreditIntPlus,		puco_id,					it_poh_bra_id,
					it_poh_id,				it_soh_id,					it_sod_id,
					rmah_id,				rmad_id,					it_qty_rma,
					it_tis_id_aux
				)
				VALUES
				(
					@comp_id,				@bra_id,					@rv,
					@litem_id,				@lsod_qty,					0,
					@lsod_price,			@lcurr_id,					@lcurr_id,
					0,						0,							0,
					0,						0,							0,
					@lsod_price,			@lcurr_id,				1,
					@lstor_id,				isnull(@decStorePreviuos,0),NULL,
					NULL,					'False',					'False',
					NULL,					@now,						NULL,
					@it_order,				NULL,						0,
					0,						0,							0,
					0,						NULL,						NULL,
					NULL,					NULL,						NULL,
					NULL,					NULL,						NULL,
					NULL
				)


				-- se incorpora el artículo al depósito seleccionado
				UPDATE	tbItemStorage	WITH (ROWLOCK)
					SET		itst_cant	= itst_cant + @lsod_qty,
							itst_cd		= @now
					WHERE	comp_id		= @comp_id
					AND		stor_id		= @stor_id
					AND		item_id		= @litem_id
				/******************************************************************************************************/





				/******************************************************************************************************/
				-- actualización del depósito del artículo en el pedido

				UPDATE	tbSaleOrderDetail	with (ROWLOCK)

					SET		stor_id = @stor_id

					WHERE   comp_id = @comp_id
					AND		soh_id	= @soh_id
					AND		sod_id	= @lsod_id
				/******************************************************************************************************/





				FETCH cursor_sod INTO @lsod_id, @lstor_id, @litem_id, @lsod_qty, @lsod_price, @lcurr_id

			END

			CLOSE cursor_sod
			DEALLOCATE cursor_sod


		END

	END


	SET		@return_value		= 1
	--SELECT	1

	COMMIT TRANSACTION


END
TRY BEGIN CATCH
	ROLLBACK TRANSACTION
	SET		@return_value		= 0
	--SELECT	ERROR_MESSAGE()
END CATCH


--SELECT @return_value
GO

CREATE PROCEDURE [dbo].[spSaleOrderDetail_UpdateStorID4PCConfigItemTransferred]
(
	@comp_id		INT,
	@bra_id			INT,
	@soh_id			INT,
	@sod_id			INT,
	@stor_idFrom	INT,
	@stor_idTo		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------
		-- TESTING
		-- ----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@soh_id		INT,
				@sod_id		INT,
				@stor_id	INT
		*/
		-- ----------------------------------------
		UPDATE tbSaleOrderDetail	WITH(ROWLOCK)
			SET
				stor_id			= @stor_idTo
				WHERE	comp_id	= @comp_id	AND
						bra_id	= @bra_id	AND
						soh_id	= @soh_id	AND
						sod_id	= @sod_id	AND
						stor_id = @stor_idFrom

	END
GO

CREATE PROCEDURE spSaleOrderDetail_ValidateData4ExcelInsert
(
	@comp_id	INT,
	@item_ean	NVARCHAR(50),
	@curr_id	INT,
	@cont_id	INT,
	@intDjai	INT,
	@simi_id	INT,
	@simid_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_ean	NVARCHAR(30),
				@curr_id	INT,
				@cont_id	INT,
				@intDjai	INT,
				@simi_id	INT,
				@simid_id	INT
		*/
		-- -----------------------------------------------------------

		DECLARE
			@strErrorMessage	NVARCHAR(4000),
			@bolHasErrores		BIT
		SET @strErrorMessage	= ''
		SET @bolHasErrores		= 'False'
		-- -----------------------------------------------------------------
		-- VALIDAR EAN DEL ARTICULO
		-- -----------------------------------------------------------------
		DECLARE @lintItemID AS integer = NULL
		SELECT
			@lintItemID = ti.item_id
		FROM tbItem							AS ti WITH(NOLOCK)
		WHERE	ti.comp_id		= @comp_id	AND
				ti.item_code	= @item_ean

		IF @lintItemID IS NULL
			BEGIN
				SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El Código EAN ingresado no corresponde con ningún artículo existente en el sistema.'
				SET @bolHasErrores		= 'True'
			END
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------
		-- VALIDAR ID DE MONEDA
		-- -----------------------------------------------------------------
		IF @curr_id <> -1
			BEGIN
				IF NOT EXISTS (SELECT 1 FROM tbsysCurrency AS tc WHERE tc.curr_id = @curr_id)
					BEGIN
						SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El ID de Moneda ingresado no corresponde con ningún ID de moneda existente en el Sistema.'
						SET @bolHasErrores		= 'True'
					END
			END
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------
		-- VALIDO CONTENEDOR
		-- -----------------------------------------------------------------
		IF @cont_id <> -1
			BEGIN
				IF NOT EXISTS (SELECT
								1
								FROM tbContainer					AS tc WITH(NOLOCK)
								WHERE	tc.comp_id = @comp_id	AND
										tc.cont_id = @cont_id)
					BEGIN
						SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El ID de Contenedor  ingresado no corresponde con ningún ID de Contenedor existente en el Sistema.'
						SET @bolHasErrores		= 'True'
					END
			END
		-- -----------------------------------------------------------------


		-- -----------------------------------------------------------------
		-- VALIDO LAS DJAI
		-- -----------------------------------------------------------------
		IF @intDjai <> -1
			BEGIN
				IF NOT EXISTS (SELECT
								1
								FROM tbCustoms_DJAI				AS tcd WITH(NOLOCK)
								WHERE	tcd.comp_id = @comp_id	AND
										tcd.djai_id = @intDjai)
					BEGIN
						SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El ID de DJAI  ingresado no corresponde con ningún ID de DJAI existente en el Sistema.'
						SET @bolHasErrores		= 'True'
					END
			END
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------
		-- VALIDO LAS SIMI
		-- -----------------------------------------------------------------
		IF @simi_id <> -1 --SI INGRESO UN SIMI
			BEGIN
				IF NOT EXISTS (SELECT
								1
								FROM tbImport_SIMIHeader		AS tis WITH (NOLOCK)
								WHERE	tis.comp_id = @comp_id	AND
										tis.simi_id = @simi_id)
					BEGIN
						SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El ID de S.I.M.I  ingresado no corresponde con ningún ID de S.I.M.I existente en el Sistema.'
						SET @bolHasErrores		= 'True'
					END
				ELSE
					BEGIN
						IF @simid_id <> -1 --SI INGRESO UN SIMID
							BEGIN
								IF NOT EXISTS(SELECT
												1
												FROM tbImport_SIMIDetail			AS tis WITH(NOLOCK)
												WHERE	tis.comp_id		= @comp_id	AND
														tis.simi_id		= @simi_id	AND
														tis.simid_id	= @simid_id)
									BEGIN
										SET @strErrorMessage	= @strErrorMessage + ' / ' + 'El ID de S.I.M.I Detalle  ingresado no corresponde con ningún ID de S.I.M.I Detalle existente en el Sistema.'
										SET @bolHasErrores		= 'True'
									END
							END
						ELSE
							BEGIN --SI INGRESO UN SIMI PERO NO INGRESO UN SIMID
								SET @strErrorMessage	= @strErrorMessage + ' / ' + 'Si selecciona un ID de S.I.M.I deberá también elegir un ID de S.I.M.I Detalle.'
								SET @bolHasErrores		= 'True'
							END
					END
			END
		-- -----------------------------------------------------------------


		SELECT
			@lintItemID			[item_id],
			@bolHasErrores		[HasErrors],
			@strErrorMessage	[ErrorMessage]


	END
GO





CREATE PROCEDURE spSaleOrderDetail_validateItemComposition
(
	@comp_id	INT,
	@item_id	INT
)
AS SET NOCOUNT ON

BEGIN

	-- -----------------------------
	-- Testing
	-- -----------------------------
	/*
	DECLARE
		@comp_id	INT,
		@item_id	INT
	SELECT
		@comp_id	=1,
		@item_id	=488
	*/
	-- -----------------------------



	SELECT
		1
	FROM tbSaleOrderDetail						tsod

		INNER JOIN tbSaleOrderHeader			tsoh
		ON	tsoh.comp_id	= tsod.comp_id	AND
			tsoh.bra_id		= tsod.bra_id	AND
			tsoh.soh_id		= tsod.soh_id

		INNER JOIN tbDocumentsFile				tdf
		ON	tdf.comp_id		= tsoh.comp_id	AND
			tdf.bra_id		= tsoh.bra_id	AND
			tdf.df_id		= tsoh.df_id

	WHERE	tsod.comp_id	= @comp_id		AND
			tsod.item_id	= @item_id		AND
			tdf.sd_id		= 80

END
GO


CREATE PROCEDURE [dbo].[spSaleOrderDetailHistory_getLastPrice]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@item_id	INT,
	@cust_id	INT
)
AS

BEGIN
	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@item_id	INT,
				@cust_id	INT
			SELECT
				@comp_id	=1,
				@lang_id	=2,
				@bra_id		=1,
				@item_id	=492,
				@cust_id	=24294
	*/
	-- ------------------------------------------------------



		DECLARE @bitCostPlusTax AS BIT
		SELECT  @bitCostPlusTax	= IsNull(tb.bra_SaleOrderPricePlusTax,'False')
			FROM tbBranch tb
			WHERE	tb.comp_id	= @comp_id
				AND tb.bra_id	= @bra_id





				SELECT	TOP 1
						dbo.fnSplitPosition(tut.utexts_desc,'|',1) + ' ' + CONVERT(VARCHAR(12),tsod.sod_insertDate,105)	+ ' ' +
						tdf.df_desc + ' #' + CONVERT(NVARCHAR(10),tdf.bra_id) + '-' + CONVERT(NVARCHAR(10),tsoh.soh_id) + ' ' +
						dbo.fnSplitPosition(tut.utexts_desc,'|',2) + '' + --LTRIM(RTRIM(tc.curr_symbol))				+

						CONVERT(VARCHAR,CONVERT(DECIMAL(19,4), (tsod.sod_price  + (
																																	CASE
																																		WHEN @bitCostPlusTax = 'True' THEN (tsod.sod_price ) * IsNull(ttn.tax_percentage,0) / 100
																																		ELSE 0
																																	END
																																	)
											   )))  + ' ' + tc1.curr_symbol 				 [desc]

				FROM tbSaleOrderDetailHistory				tsod		WITH (NOLOCK)
					INNER JOIN tbSaleOrderHeader			tsoh		WITH (NOLOCK)
					ON	tsoh.comp_id	= tsod.comp_id		AND
						tsoh.bra_id		= tsod.bra_id		AND
						tsoh.soh_id		= tsod.soh_id
					INNER JOIN tbDocumentsFile				tdf		WITH (NOLOCK)
					ON	tdf.comp_id		= tsoh.comp_id		AND
						tdf.df_id		= tsoh.df_id
					INNER JOIN tbsysCurrency				tc1		WITH (NOLOCK)
					ON	tc1.curr_id		= tsod.curr_id
					INNER JOIN tbBranch						tb		WITH (NOLOCK)
					ON	tb.bra_id		= @bra_id
					INNER JOIN tbsysUniqueTexts				tut		WITH (NOLOCK)
					ON  tut.lang_id		= @lang_id			AND
						tut.utexts_id	= 30877
					LEFT JOIN vwItemTaxesOnlyOneIvaTax		vit		WITH (NOLOCK)
					ON	vit.comp_id		= tsod.comp_id		AND
						vit.item_id		= tsod.item_id
					LEFT JOIN tbTaxName						ttn		WITH (NOLOCK)
					ON	ttn.comp_id		= vit.comp_id		AND
						ttn.tax_id		= vit.tax_id
					WHERE	tsod.comp_id = @comp_id
					AND		tsod.item_id = @item_id
					AND		tsoh.cust_id = @cust_id
					AND		tdf.sd_id	 = 5				-- Solo Presupuestos
				ORDER BY tsod.sohh_id DESC


END
GO

CREATE PROCEDURE [dbo].[spSaleOrderDetailImport_AvailableLote_GetCombo]
(
	@comp_id	INT,
	@item_id	INT,
	@qty		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ---------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT,
				@qty		INT
			SELECT
				@comp_id	= 1,
				@item_id	= 492,
				@qty		= 10

			DROP TABLE #tmpAvailableImportdataForDebit
			DROP TABLE #tmpSaleOrderDetailImportDataGroupedByItem
		*/
		-- ---------------------------------------------------------

		--TABLA TEMPORAL DE CADA LOTE PARA ESE ITEM_ID
		SELECT
			tia.impData_id													[impData_id],
			tia.impData_ActualQty											[CantDisponible],
			tia.impdata_LotNumber											[Lote],
			tia.item_id														[ItemID]
			--tia.impdata_InitialQty										[CantidadInicial],
			--vwiai.import_id,
			--tia.impData_Id,
			--ti.import_cd
			INTO #tmpAvailableImportdataForDebit
			FROM tbImportData												tia			WITH (NOLOCK)
				--LEFT JOIN vwImportdata_ImportId								vwiai		WITH (NOLOCK)
				--	ON	vwiai.comp_id						= tia.comp_id	AND
				--		vwiai.ct_transaction				= tia.ct_transaction
				--LEFT JOIN dbo.tbImport										ti			WITH (NOLOCK)
				--	ON  ti.comp_id							= tia.comp_id	AND
				--		ti.import_id						= vwiai.import_id
			WHERE		tia.comp_id							= @comp_id		AND
						tia.item_id							= @item_id		AND
						tia.impData_ActualQty				> 0				AND
						tia.impData_id						IS NOT NULL		AND
						ISNULL(tia.impdata_LotNumber,'')	<> ''
			ORDER BY tia.impdata_Priority--,ti.import_cd


		--SELECT * FROM #tmpAvailableImportdataForDebit


		--SUM DE LOS ASIGNADOS EN LA TABLA NUEVA
		SELECT
			tsodid.impData_id,
			ISNULL(SUM(ISNULL(tsod.sod_qty,0)),0)		[StockOnSODI]
		INTO #tmpSaleOrderDetailImportDataGroupedByItem
		FROM tbSaleOrderDetailImportData				AS tsodid	WITH(NOLOCK)
			INNER JOIN tbSaleOrderDetail				AS tsod	WITH(NOLOCK)
				ON	tsod.comp_id	= tsodid.comp_id	AND
					tsod.soh_id		= tsodid.soh_id		AND
					tsod.sod_id		= tsodid.sod_id
		WHERE	tsodid.comp_id		= @comp_id AND
				tsod.item_id		= @item_id
		GROUP BY tsodid.impData_id

		--SELECT * FROM #tmpSaleOrderDetailImportDataGroupedByItem

		--Y DESPUES HAGO UN LEFT JOIN CONTRA ESTA TABLA Y LA CANTIDAD PENDIENTE - LA CANTIDAD ASIGNADA EN LA NUEVA TABLA
		--SEA MAYOR A LA CANTIDAD QUE YO QUIERO ASIGNAR A UN LOTE
		SELECT
			tmp.impData_id																										[ID],
			'Lote #: ' + tmp.Lote  + ' | Disponible: ' + CONVERT(VARCHAR, (tmp.CantDisponible - ISNULL(tmp2.StockOnSODI,0)))	[DESC]
		FROM #tmpAvailableImportdataForDebit						tmp
			LEFT JOIN #tmpSaleOrderDetailImportDataGroupedByItem	tmp2
				ON tmp2.impData_id = tmp.impData_id
		WHERE (tmp.CantDisponible - ISNULL(tmp2.StockOnSODI,0)) >= @qty

	END

GO


CREATE PROCEDURE [dbo].[spSaleOrderDetailImport_AvailableLoteByQty_GetData]
(
	@comp_id				INT,
	@item_id				INT,
	@qty					INT,
	@bolCantDispMayorOIgual	BIT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@item_id				INT,
				@qty					INT,
				@bolCantDispMayorOIgual	BIT
			SELECT
				@comp_id				= 1,
				@item_id				= 492,
				@qty					= 10,
				@bolCantDispMayorOIgual	= 'False'

			DROP TABLE #tmpAvailableImportdataForDebit
			DROP TABLE #tmpSaleOrderDetailImportDataGroupedByItem
		*/
		-- ---------------------------------------------------------

		-- -----------------------------------------------------------------------------------
		-- TABLA TEMPORAL DE CADA LOTE PARA ESE ITEM_ID
		-- -----------------------------------------------------------------------------------
		SELECT
			tia.impData_id													[impData_id],
			tia.impData_ActualQty											[CantDisponible],
			tia.impdata_LotNumber											[Lote],
			tia.item_id														[ItemID],
			CONVERT(VARCHAR, tia.impData_ExpirationDate, 103)				[impData_ExpirationDate]
			--tia.impdata_InitialQty										[CantidadInicial],
			--vwiai.import_id,
			--tia.impData_Id,
			--ti.import_cd
			INTO #tmpAvailableImportdataForDebit
			FROM tbImportData												tia			WITH (NOLOCK)
				--LEFT JOIN vwImportdata_ImportId								vwiai		WITH (NOLOCK)
				--	ON	vwiai.comp_id						= tia.comp_id	AND
				--		vwiai.ct_transaction				= tia.ct_transaction
				--LEFT JOIN dbo.tbImport										ti			WITH (NOLOCK)
				--	ON  ti.comp_id							= tia.comp_id	AND
				--		ti.import_id						= vwiai.import_id
			WHERE		tia.comp_id							= @comp_id		AND
						tia.item_id							= @item_id		AND
						tia.impData_ActualQty				> 0				AND
						tia.impData_id						IS NOT NULL		AND
						ISNULL(tia.impdata_LotNumber,'')	<> ''
			ORDER BY tia.impData_ExpirationDate, tia.impdata_Priority--,ti.import_cd
		-- -----------------------------------------------------------------------------------



		-- -----------------------------------------------------------------------------------
		-- SUM DE LOS ASIGNADOS EN LA TABLA NUEVA
		-- -----------------------------------------------------------------------------------
			SELECT
				tsodid.impData_id,
				ISNULL(SUM(ISNULL(tsod.sod_qty,0)),0)		[StockOnSODI]
			INTO #tmpSaleOrderDetailImportDataGroupedByItem
			FROM tbSaleOrderDetailImportData				AS tsodid	WITH(NOLOCK)
				INNER JOIN tbSaleOrderDetail				AS tsod	WITH(NOLOCK)
					ON	tsod.comp_id	= tsodid.comp_id	AND
						tsod.soh_id		= tsodid.soh_id		AND
						tsod.sod_id		= tsodid.sod_id
			WHERE	tsodid.comp_id		= @comp_id AND
					tsod.item_id		= @item_id
			GROUP BY tsodid.impData_id
		-- -----------------------------------------------------------------------------------

		IF @bolCantDispMayorOIgual = 'True'
			BEGIN
				--Y DESPUES HAGO UN LEFT JOIN CONTRA ESTA TABLA Y LA CANTIDAD PENDIENTE - LA CANTIDAD ASIGNADA EN LA NUEVA TABLA
				--SEA MAYOR A LA CANTIDAD QUE YO QUIERO ASIGNAR A UN LOTE
				SELECT
					tmp.impData_id																				[ID],
					'Lote #: ' + tmp.Lote  +
					' | Disponible: ' + CONVERT(VARCHAR, (tmp.CantDisponible - ISNULL(tmp2.StockOnSODI,0)))	+
					' | Fecha de Vencimiento: ' + ISNULL(tmp.impData_ExpirationDate,'')							[DESC]
				FROM #tmpAvailableImportdataForDebit						tmp
					LEFT JOIN #tmpSaleOrderDetailImportDataGroupedByItem	tmp2
						ON tmp2.impData_id = tmp.impData_id
				WHERE (tmp.CantDisponible - ISNULL(tmp2.StockOnSODI,0)) >= @qty
			END
		ELSE
			BEGIN
				--Y DESPUES HAGO UN LEFT JOIN CONTRA ESTA TABLA Y LA CANTIDAD PENDIENTE - LA CANTIDAD ASIGNADA EN LA NUEVA TABLA
				--SEA MENOR A LA CANTIDAD QUE YO QUIERO ASIGNAR A UN LOTE
				SELECT
					tmp.impData_id																				[ID],
					'Lote #: ' + tmp.Lote  +
					' | Disponible: ' + CONVERT(VARCHAR, (tmp.CantDisponible - ISNULL(tmp2.StockOnSODI,0)))	+
					' | Fecha de Vencimiento: ' + ISNULL(tmp.impData_ExpirationDate,'')							[DESC]
				FROM #tmpAvailableImportdataForDebit						tmp
					LEFT JOIN #tmpSaleOrderDetailImportDataGroupedByItem	tmp2
						ON tmp2.impData_id = tmp.impData_id
				WHERE (tmp.CantDisponible - ISNULL(tmp2.StockOnSODI,0)) < @qty
			END

	END

GO

