CREATE procedure [dbo].[spSaleOrderDetailStockComposition_getGenericGridData]
(

	@comp_id	INT,
	@item_id	INT,
	@stor_id	INT,
	@df_id		INT

)
as set nocount on


BEGIN
-- -----------------------------------------
-- Testing
-- -----------------------------------------
/*
	declare
		@comp_id	INT,
		@item_id	INT,
		@stor_id	INT,
		@df_id		int

	select
		@comp_id		= 1,
		@stor_id		= 4,
		@item_id		= 256,
		@df_id			= 56
*/
-- -----------------------------------------


DECLARE	@sd_id	INT

SELECT @sd_id = tdf.sd_id FROM tbDocumentsFile tdf WHERE tdf.df_id = @df_id


	SELECT		ti.item_code															[item_code],
				ti.item_desc															[item_desc],
				dbo.fnGetAStock(@comp_id,@stor_id, ti.item_id, 99999999)				[StockActual]

		FROM tbItemComposition						tic

		INNER JOIN tbItem							ti
		ON	ti.comp_id = tic.comp_id
		AND ti.item_id = tic.item_id_1


	where	tic.comp_id = @comp_id
	and		tic.item_id = @item_id
	AND		@sd_id		= 80


	ORDER BY	ti.item_code,ti.item_desc


END

GO








CREATE PROCEDURE [dbo].[spSaleOrderDetailtmp_DeleteData]
(
    @comp_id		int,
	@bra_id			int,
	@soh_id			int,
	@sod_id			int,
	@sodt_qty		DECIMAL,
	@item_id		INT
)
as
set nocount ON

BEGIN


	UPDATE tbSaleOrderDetail					WITH (ROWLOCK)
		SET	sodt_qty = 0
		where	comp_id		= @comp_id
		and		bra_id		= @bra_id
		and		soh_id		= @soh_id
		AND		sod_id		= @sod_id


	DELETE  FROM dbo.tbSaleOrderDetailtmp		WITH (ROWLOCK)
		where	comp_id		= @comp_id
		and		bra_id		= @bra_id
		and		soh_id		= @soh_id
		AND		sod_id		= @sod_id
		AND		(item_id		= @item_id OR item_id IS NULL)




	UPDATE	tbSaleOrderHeader					WITH (ROWLOCK)
		SET		ssos_id = 20
		WHERE	comp_id = @comp_id
		AND		bra_id  = @bra_id
		AND		soh_id  = @soh_id


end





GO



CREATE PROCEDURE [dbo].[spSaleOrderDetailtmp_insertData]
(
    @comp_id		INT,
	@bra_id			INT,
	@soh_id			INT,
	@sod_id			INT,
	@item_id		INT,
	@sodt_qty		DECIMAL(19,5)
)
AS

BEGIN

	SET NOCOUNT ON

	IF @item_id = 0 SET @item_id = NULL


	---VERIFICAMOS LA EXISTENCIA DEL REGISTRO
	---SI EXISTE ACTUALIZAMOS, SINO INSERTAMOS REGISTRO
	if exists (SELECT TOP 1	1
				from	dbo.tbSaleOrderDetailtmp WITH (NOLOCK)
				where	comp_id		= @comp_id
				and		bra_id		= @bra_id
				and		soh_id		= @soh_id
				and		sod_id		= @sod_id
				AND		(item_id		= @item_id OR item_id IS NULL))

		BEGIN

			update  dbo.tbSaleOrderDetailtmp	WITH (ROWLOCK)
				set		sodt_qty	= @sodt_qty
				where	comp_id		= @comp_id
				and		bra_id		= @bra_id
				and		soh_id		= @soh_id
				and		sod_id		= @sod_id
				AND		(item_id		= @item_id OR item_id IS NULL)


			UPDATE tbSaleOrderDetail			WITH (ROWLOCK)
				SET	sodt_qty = @sodt_qty
				where	comp_id		= @comp_id
				and		bra_id		= @bra_id
				and		soh_id		= @soh_id
				AND		sod_id		= @sod_id

		END

	ELSE

	   BEGIN

			 insert into dbo.tbSaleOrderDetailtmp	WITH (ROWLOCK)
				 (
	 				comp_id,
	 				bra_id,
	 				soh_id,
	 				sod_id,
	 				sodt_qty,
	 				item_id
				 )
				 values
				 (
	 				@comp_id,
	 				@bra_id,
	 				@soh_id,
	 				@sod_id,
	 				@sodt_qty,
	 				@item_id
				 )

			UPDATE tbSaleOrderDetail				WITH (ROWLOCK)
				SET	sodt_qty = @sodt_qty
				where	comp_id		= @comp_id
				and		bra_id		= @bra_id
				and		soh_id		= @soh_id
				AND		sod_id		= @sod_id

	   END




	--ACTUALIZAMOS EL ESTADO DEL PEDIDO, EN PREPARACIÓN - 20
	UPDATE tbSaleOrderHeader	WITH (ROWLOCK)
		SET	  ssos_id = 20
		WHERE comp_id = @comp_id
		AND   bra_id  = @bra_id
		AND   soh_id  = @soh_id


END
GO







CREATE PROCEDURE [dbo].[spSaleOrderDetailtmp_insertData4NoStockItems]
(
    @comp_id		INT,
	@bra_id			INT,
	@soh_id			INT,
	@sod_id			INT,
	@item_id		INT,
	@sodt_qty		DECIMAL(19,5)
)
AS

BEGIN

	SET NOCOUNT ON

	---VERIFICAMOS LA EXISTENCIA DEL REGISTRO
	---SI EXISTE ACTUALIZAMOS, SINO INSERTAMOS REGISTRO

	DECLARE @bitExiste AS BIT
	SET		@bitExiste = 'False'

	IF @item_id IS NULL OR @item_id = 0
		BEGIN
			select	@bitExiste = 'True'
				from	dbo.tbSaleOrderDetailtmp	WITH (NOLOCK)
				where	comp_id		= @comp_id
				and		bra_id		= @bra_id
				and		soh_id		= @soh_id
				and		sod_id		= @sod_id
				AND		item_id		IS NULL
			select	@bitExiste = 'True'
				from	dbo.tbSaleOrderDetailtmp	WITH (NOLOCK)
				where	comp_id		= @comp_id
				and		bra_id		= @bra_id
				and		soh_id		= @soh_id
				and		sod_id		= @sod_id
				AND		item_id		= 0
			SET @item_id = 0
		END
	ELSE
		BEGIN
			select	@bitExiste = 'True'
				from	dbo.tbSaleOrderDetailtmp	WITH (NOLOCK)
				where	comp_id		= @comp_id
				and		bra_id		= @bra_id
				and		soh_id		= @soh_id
				and		sod_id		= @sod_id
				AND		item_id		= @item_id
		END


	if @bitExiste = 'True'
		BEGIN

			update  dbo.tbSaleOrderDetailtmp	WITH (ROWLOCK)
				set		sodt_qty	= @sodt_qty
				where	comp_id		= @comp_id
				and		bra_id		= @bra_id
				and		soh_id		= @soh_id
				and		sod_id		= @sod_id
				AND		item_id		= @item_id

		END

	ELSE

	   BEGIN

		 insert into dbo.tbSaleOrderDetailtmp	WITH (ROWLOCK)
		 (
	 		comp_id,
	 		bra_id,
	 		soh_id,
	 		sod_id,
	 		sodt_qty,
	 		item_id
		 )
		 values
		 (
	 		@comp_id,
	 		@bra_id,
	 		@soh_id,
	 		@sod_id,
	 		@sodt_qty,
	 		CASE
	 			WHEN @item_id = 0 THEN NULL
	 			ELSE @item_id
	 		END    --  MOS 06-2023: HIJO DE RE MIL PUTAS, ENFERMO DE MIERDA....    llegaba CERO!!!!!!   @item_id
		 )

	   END


END
GO







