CREATE PROCEDURE [dbo].[spSaleOrderDivision_ChangePriority]
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT,
	@sod_id		INT,
	@checked	BIT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@soh_id		INT,
				@sod_id		INT,
				@checked	BIT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@soh_id		= 33432,
				@sod_id		= 30402,
				@checked	= 'False'
		*/
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- -----------------------------------------------------------------
			DECLARE
				@lsoh_id		INT,
				@lstor_id		INT,
				@lintPriority	INT
		-- -----------------------------------------------------------------

		IF (SELECT
				COUNT(*)
				FROM tbSaleOrderDetail				tsod
				WHERE	tsod.comp_id	= @comp_id	AND
						tsod.bra_id		= @bra_id	AND
						tsod.soh_id		= @soh_id)	= 1
			BEGIN
				SET @checked = 'False'
			END

		IF @checked = 'True'
			BEGIN
				--RECUPERO EL STOR_ID DE LA SALEORDER_DETAIL PARA PODER RECALCULAR LA PRIORIDAD
				SELECT
					@lstor_id			= tsod.stor_id
				FROM tbSaleOrderDetail					tsod
				WHERE	tsod.comp_id	= @comp_id		AND
						tsod.bra_id		= tsod.bra_id	AND
						tsod.soh_id		= @soh_id		AND
						tsod.sod_id		= @sod_id

				--NUEVO SOH_ID
				EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @lsoh_id OUTPUT
				--PRIORIDAD
				EXEC spCounters_getNextValue @comp_id, @lstor_id, 1,@counter_value = @lintPriority OUTPUT


				--CLONO EL HEADER
				INSERT INTO tbSaleOrderHeader
				(
					comp_id,										bra_id,								soh_id,
					soh_cd,											soh_deliveryDate,					soh_observation1,
					soh_observation2,								soh_observation3,					soh_observation4,
					soh_quotation,									sm_id,								cust_id,
					st_id,											disc_id,							dl_id,
					cb_id,											soh_lastUpdate,						soh_limitDate,
					tt_id,											tt_class,							soh_StatusOf,
					[user_id],										soh_isEditing,						soh_isEditingCd,
					df_id,											soh_total,							ssos_id,
					soh_ExchangeToCustomerCurrency,					chp_id,								soh_PL_df_Id,
					soh_CustomerCurrency,							soh_WithCollection,					soh_WithCollectionGUID,
					soh_discount,									soh_loan,							soh_packagesQty,
					soh_internalAnnotation,							curr_id4Exchange,					curr_idExchange,
					soh_ATotal,										df_id4PL,							somp_id,
					soh_FEIdNumber,									soh_inCash,							custf_id,
					cust_id_guarantor,								ccp_id,								soh_MLdeliveryLabel,
					soh_deliveryAddress,							soh_MLQuestionsAndAnswers,			aux_3RDSales_lastCTTransaction,
					soh_MLId,										soh_MLGUIA,							pro_id,
					aux_collectionInterest_lastCTTransaction,		ws_cust_Id,							ws_internalID,
					ws_paymentGateWayStatusID,						ws_paymentGateWayReferenceID,		ws_IPFrom,
					ws_st_id,										ws_dl_id,							soh_htmlNote,
					prli_id,										stor_id,
					mlo_id, MLShippingID,
					soh_Currency4Total, soh_exchange2Currency4Total
				)
				SELECT
					tsoh.comp_id,									tsoh.bra_id,						@lsoh_id,
					tsoh.soh_cd,									tsoh.soh_deliveryDate,				tsoh.soh_observation1,
					tsoh.soh_observation2,							tsoh.soh_observation3,				tsoh.soh_observation4,
					tsoh.soh_quotation,								tsoh.sm_id,							tsoh.cust_id,
					tsoh.st_id,										tsoh.disc_id,						tsoh.dl_id,
					tsoh.cb_id,										tsoh.soh_lastUpdate,				tsoh.soh_limitDate,
					tsoh.tt_id,										tsoh.tt_class,						tsoh.soh_StatusOf,
					tsoh.[user_id],									tsoh.soh_isEditing,					tsoh.soh_isEditingCd,
					tsoh.df_id,										tsoh.soh_total,						tsoh.ssos_id,
					tsoh.soh_ExchangeToCustomerCurrency,			tsoh.chp_id,						tsoh.soh_PL_df_Id,
					tsoh.soh_CustomerCurrency,						tsoh.soh_WithCollection,			tsoh.soh_WithCollectionGUID,
					tsoh.soh_discount,								tsoh.soh_loan,						tsoh.soh_packagesQty,
					tsoh.soh_internalAnnotation,					tsoh.curr_id4Exchange,				tsoh.curr_idExchange,
					tsoh.soh_ATotal,								tsoh.df_id4PL,						tsoh.somp_id,
					tsoh.soh_FEIdNumber,							tsoh.soh_inCash,					tsoh.custf_id,
					tsoh.cust_id_guarantor,							tsoh.ccp_id,						tsoh.soh_MLdeliveryLabel,
					tsoh.soh_deliveryAddress,						tsoh.soh_MLQuestionsAndAnswers,		tsoh.aux_3RDSales_lastCTTransaction,
					tsoh.soh_MLId,									tsoh.soh_MLGUIA,					tsoh.pro_id,
					tsoh.aux_collectionInterest_lastCTTransaction,	tsoh.ws_cust_Id,					tsoh.ws_internalID,
					tsoh.ws_paymentGateWayStatusID,					tsoh.ws_paymentGateWayReferenceID,	tsoh.ws_IPFrom,
					tsoh.ws_st_id,									tsoh.ws_dl_id,						tsoh.soh_htmlNote,
					tsoh.prli_id,									tsoh.stor_id,
					mlo_id, MLShippingID,
					soh_Currency4Total, soh_exchange2Currency4Total

				FROM tbSaleOrderHeader				tsoh	WITH (NOLOCK)
				WHERE	tsoh.comp_id	= @comp_id	AND
						tsoh.bra_id		= @bra_id	AND
						tsoh.soh_id		= @soh_id



				--CON EL ID OBTENIDO DE LA CLONACIÓN, ACTUALIZO EL SOD Y LE ASIGNO ESE NÚMERO DE PEDIDO Y LA NUEVA PRIORIDAD
				UPDATE tbSaleOrderDetail
				SET
					soh_id				= @lsoh_id,
					sod_priority		= @lintPriority
					WHERE	comp_id		= @comp_id	AND
							bra_id		= @bra_id	AND
							soh_id		= @soh_id	AND
							sod_id		= @sod_id

			END
		ELSE
			BEGIN
				--RECUPERO EL STOR_ID DE LA SALEORDER_DETAIL PARA PODER RECALCULAR LA PRIORIDAD
				SELECT
					@lstor_id			= tsod.stor_id
				FROM tbSaleOrderDetail					tsod
				WHERE	tsod.comp_id	= @comp_id		AND
						tsod.bra_id		= tsod.bra_id	AND
						tsod.soh_id		= @soh_id		AND
						tsod.sod_id		= @sod_id

				--PRIORIDAD
				EXEC spCounters_getNextValue @comp_id, @lstor_id, 1,@counter_value = @lintPriority OUTPUT

				UPDATE tbSaleOrderDetail
				SET
					sod_priority	= @lintPriority
					WHERE	comp_id = @comp_id	AND
							bra_id	= @bra_id	AND
							soh_id	= @soh_id	AND
							sod_id	= @sod_id

			END

	END

GO

