			sops_date,
			sops_poh_bra_id,
			sops_poh_id,
			sops_note,
			sops_user_id,
			sops_lastUpdate,
			ct_transaction_SelectFromPacking, sodt_qty,
			sod_disablePrintInEmmition, sod_discountByItem, sod_discountByTotal,
			sod_creditInt, sod_creditIntPlus, sod_priceNeto, sod_comboCoeficient,
			sod_montlyPaymentFrom, sod_montlyPaymentTo, wscup_id
		)
		SELECT
			tsod.comp_id,
			tsod.bra_id,
			tsod.soh_id,
			tsod.sod_priority,
			tsod.item_id,
			tsod.sod_itemDesc,
			tsod.sod_detail,
			tsod.curr_id,
			tsod.sod_initQty,
			@qty,
			tsod.prli_id,
			tsod.sod_price,
			tsod.stor_id,
			tsod.sod_lastUpdate,
			tsod.sod_isEditing,
			tsod.sod_insertDate,
			tsod.[user_id],
			tsod.sod_quotation,
			tsod.sod_isCredit,
			tsod.sod_cost,
			tsod.sod_costTax,
			tsod.rmah_id,
			tsod.rmad_id,
			tsod.sod_note1,
			tsod.sod_note2,
			tsod.sod_itemDiscount,
			tsod.sod_tis_id_origin,
			tsod.sod_item_id_origin,
			tsod.sod_isParentAssociate,
			tsod.is_id,
			tsod.it_transaction,
			tsod.sod_isMade,
			tsod.sod_expirationDate,
			tsod.acc_count_id,
			tsod.sod_packagesQty,
			tsod.item_id_EW,
			tsod.tis_idOfThisEW,
			tsod.camp_id,
			tsod.sdlmt_id,
			tsod.sreas_id,
			tsod.sod_loanNumberOfPays,
			tsod.sod_loanDateOfFirstPay,
			tsod.sod_loanDayOfMonthOfNextPays,
			tsod.sod_itemDeliveryDate,
			tsod.sod_idOfThisEW,
			tsod.sod_isFromPCConfigCTRLId,
			tsod.sod_EWAddress,
			tsod.sod_PCCOnfigIsTransfered2Branch,
			tsod.sod_MLCost,
			tsod.sod_itemAssociationCoeficient,
			tsod.ws_price,
			tsod.ws_curr_Id,
			tsod.sops_id,
			tsod.mlo_id,
			tsod.sops_supp_id,
			tsod.sops_bra_id,
			tsod.sops_date,
			tsod.sops_poh_bra_id,
			tsod.sops_poh_id,
			tsod.sops_note,
			tsod.sops_user_id,
			tsod.sops_lastUpdate,
			ct_transaction_SelectFromPacking, sodt_qty,
			sod_disablePrintInEmmition, sod_discountByItem, sod_discountByTotal,
			sod_creditInt, sod_creditIntPlus, sod_priceNeto, sod_comboCoeficient,
			sod_montlyPaymentFrom, sod_montlyPaymentTo, wscup_id

			FROM tbSaleOrderDetail				tsod	WITH (NOLOCK)
			WHERE	tsod.comp_id	= @comp_id	AND
					tsod.bra_id		= @bra_id	AND
					tsod.soh_id		= @soh_id	AND
					tsod.sod_id		= @sod_id

		--UNA VEZ CREADO EL NUEVO REGISTRO, ACTUALIZO EL ANTERIOR
		UPDATE tbSaleOrderDetail	WITH (ROWLOCK)
		SET
			sod_qty = sod_qty - @qty
			WHERE	comp_id = @comp_id AND
					bra_id	= @bra_id AND
					soh_id	= @soh_id AND
					sod_id	= @sod_id
	END
GO

CREATE PROCEDURE [dbo].[spSaleOrderDivision_GetDataByFilters]
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT,
	@ItemGuid	UNIQUEIDENTIFIER,
	@cust_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- -----------------------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@soh_id		INT,
				@ItemGuid	UNIQUEIDENTIFIER,
				@cust_id
		*/
		-- -----------------------------------------------------------------

		-- -----------------------------------------------------------------
		-- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
		-- -----------------------------------------------------------------
			DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)
			INSERT INTO @tblComplexFilter_Items
				SELECT tcf.sl_id
					FROM tbComplexFilter tcf
					WHERE tcf.sl_guid = @ItemGuid     AND
						  tcf.sl_selected = 'True'
			IF @@ROWCOUNT = 0
				BEGIN
					INSERT INTO @tblComplexFilter_Items
						SELECT ti.item_id
							FROM tbItem ti
							WHERE ti.comp_id = @comp_id
				END

			--SELECT * FROM @tblComplexFilter_Items
		-- -----------------------------------------------------------------

		SELECT
			' '										[ ],
			' '										[ ],
			tc.cust_name,
			tsoh.soh_id,
			tb.bra_desc,
			ti.item_code,
			ti.item_desc,
			tsod.sod_qty,
			tst.st_desc,
			td.disc_desc,
			tsod.sod_itemDeliveryDate,
			tsod.sod_priority,
			CONVERT(VARCHAR,tsod.comp_id)			+ '-' +
			CONVERT(VARCHAR,tsod.bra_id)			+ '-' +
			CONVERT(VARCHAR,tsod.soh_id)			+ '-' +
			CONVERT(VARCHAR,tsod.sod_id)			+ '-' +
			CONVERT(VARCHAR,tsod.item_id)			[ID]

		FROM tbSaleOrderHeader						tsoh	WITH(NOLOCK)
		INNER JOIN tbSaleOrderDetail				tsod	WITH(NOLOCK)
			ON	tsod.comp_id	= tsoh.comp_id		AND
				tsod.bra_id		= tsoh.bra_id		AND
				tsod.soh_id		= tsoh.soh_id
		INNER JOIN @tblComplexFilter_Items			tmp
			ON	tmp.item_id		= tsod.item_id
		INNER JOIN tbItem							ti
			ON	ti.comp_id		= tsod.comp_id		AND
				ti.item_id		= tsod.item_id
		INNER JOIN tbBranch							tb
			ON	tb.comp_id		= tsoh.comp_id		AND
				tb.bra_id		= tsoh.bra_id
		INNER JOIN tbCustomer						tc
			ON	tc.comp_id		= tsoh.comp_id		AND
				tc.cust_id		= tsoh.cust_id
		INNER JOIN tbSalesTerms						tst
			ON	tst.comp_id		= tsoh.comp_id		AND
				tst.st_id		= tsoh.st_id
		LEFT JOIN tbDiscount						td
			ON	td.comp_id		= tsoh.comp_id		AND
				td.disc_id		= tsoh.disc_id
		WHERE	tsoh.comp_id	= @comp_id			AND
				tsoh.bra_id		= @bra_id			AND
				(
					@soh_id		= 0				OR
					tsoh.soh_id = @soh_id
				)									AND
				(
					@cust_id		= -1		OR
					tsoh.cust_id	= @cust_id
				)

	END
GO

