CREATE PROCEDURE [dbo].[spSaleOrderEmbarkOK_getDataByFilters]
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT
)

as
BEGIN


	SET NOCOUNT ON



	-- ------------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@bra_id		INT,
		@soh_id		INT

	SELECT
		@comp_id	= 1,
		@bra_id		= 1,
		@soh_id		= 2248
	*/
	-- ------------------------------------------------------------

	SELECT
		tb.bra_desc,
		tsoeo.peem_Number,
		tsoeo.peem_id,
		tsoeo.fecountry_id,
		tfi.fecountry_desc


		FROM tbSaleOrderEmbarkOK tsoeo		WITH (NOLOCK)

		INNER JOIN tbsysFECountryID tfi		WITH (NOLOCK)
			ON tfi.fecountry_id = tsoeo.fecountry_id

		INNER JOIN tbBranch tb				WITH (NOLOCK)
		ON tb.comp_id = tsoeo.comp_id
		AND tb.bra_id = tsoeo.bra_id


	WHERE tsoeo.comp_id = @comp_id
	AND tsoeo.bra_id = @bra_id
	AND tsoeo.soh_id = @soh_id

END
GO

