CREATE PROCEDURE [dbo].[spSaleOrderGetNumberOfDocuments4ThisSaleOrder]
(
	@comp_id	INT,
	@df_id		INT,
	@soh_Bra_id	INT,
	@soh_id		INT
)

AS


BEGIN

	SET NOCOUNT ON

	DECLARE  @intItemsOfDF AS INT = 25

	SELECT @intItemsOfDF = ISNULL(tdf.df_maxItems,25)
		FROM tbDocumentsFile tdf		WITH (NOLOCK)
			WHERE	tdf.comp_id = @comp_id AND
					tdf.df_id	= @df_id


	DECLARE @intSaleOrderItemns AS INT = 1

	SELECT @intSaleOrderItemns  = COUNT(*)
		FROM tbSaleOrderDetail tsod		WITH (NOLOCK)
		WHERE	tsod.comp_id	= @comp_id		AND
				tsod.bra_id		= @soh_Bra_id	AND
				tsod.soh_id		= @soh_id


	SELECT  CEILING(@intSaleOrderItemns / dbo.fnNoZDiv(@intItemsOfDF))	[TotalDocuments]


END
GO





