CREATE PROCEDURE spSaleOrderHeader_getCustomerImageData
	@comp_id	AS INT,
	@bra_id		AS INT,
	@soh_id		AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;



	SELECT	CASE
				WHEN tsoh.custf_id		IS NOT NULL AND tcf.custf_picture IS NOT NULL	THEN 	3
				WHEN tsoh.cb_id			IS NOT NULL AND tcb.custb_picture IS NOT NULL	THEN	2
				WHEN tc.cust_picture	IS NOT NULL										THEN	1
				ELSE																			0
			END					[customerPhotoType],
			tsoh.cust_id,
			tsoh.cb_id,
			tsoh.custf_id

		FROM tbSaleOrderHeader tsoh					WITH (NOLOCK)
		INNER JOIN tbCustomer tc					WITH (NOLOCK)
			ON	tc.comp_id	= tsoh.comp_id	AND
				tc.cust_id	= tsoh.cust_id

		LEFT  JOIN tbCustomerBranch tcb				WITH (NOLOCK)
			ON	tcb.comp_id = tsoh.comp_id	AND
				tcb.cust_id = tsoh.cust_id	AND
				tcb.cb_id	= tsoh.cb_id

		LEFT  JOIN tbCustomerFamily tcf				WITH (NOLOCK)
			ON	tcf.comp_id = tsoh.comp_id	AND
				tcf.cust_id = tsoh.cust_id	AND
				tcf.custf_id= tsoh.custf_id

		WHERE	tsoh.comp_id= @comp_id		AND
				tsoh.bra_id = @bra_id		AND
				tsoh.soh_id = @soh_id



END
GO




















CREATE PROCEDURE [dbo].[spSaleOrderHeader_getData]
(
	@comp_id			int,
	@bra_id				int
)
as

/*
declare @comp_id			int,
	@bra_id				int
select @comp_id			=1,
	@bra_id				= 1

*/
select	' ' [ ], ' ' [ ],
		soh.comp_id,
		soh.bra_id,
		soh.soh_cd,
		soh.soh_deliveryDate,
		soh.soh_quotation,
		sa.sm_name,
		soh.sm_id,
		cu.cust_name,
		soh.cust_id,
		st.st_desc,
		br.bra_desc,
		soh.st_id,
		soh.disc_id,
		di.disc_desc,
		soh.dl_id,
		soh.cb_id,
		soh.soh_lastUpdate,
		soh.soh_limitDate,
		soh.tt_id,
		soh.tt_class,
		soh.soh_StatusOf,
		soh.user_id,
		soh.soh_isEditing,
		soh.soh_isEditingCd,
		soh.df_id,
		stor.stor_desc,
		soh.soh_observation1,
		soh.soh_observation2,
		soh.soh_observation3,
		soh.soh_observation4,
		soh.soh_id [ID]



from	dbo.tbSaleOrderHeader				soh

		inner join dbo.tbSalesman			sa
		on	sa.sm_id   = soh.sm_id

		inner join dbo.tbCustomer			cu
		on	cu.cust_id = soh.cust_id

		inner join dbo.tbSalesTerms			st
		on  st.st_id   = soh.st_id

		inner join dbo.tbDiscount			di
		on di.disc_id  = soh.disc_id

		inner join dbo.tbBranch				br
		on br.bra_id   = soh.bra_id

		inner join dbo.tbStorage			stor
		on stor.comp_id	= soh.comp_id

where	soh.comp_id		=	@comp_id
and		soh.bra_id  	=	@bra_id
and     soh.soh_quotation = 'false'

order by soh.soh_id


























GO








CREATE PROCEDURE [dbo].[spSaleOrderHeader_getDataAllRMA]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@lang_id			INT,
	@cust_id			int,
	@ssos_id			int

)
AS



BEGIN

set nocount on

set dateformat 'ymd'

--------------------------------------------------------------
/*
--------------------------------------------------------------
declare		@comp_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@lang_id			INT,
			@cust_id			int,
			@ssos_id			int


select		@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@prof_id			=1,
			@user_id			=1,
			@cust_id			=24288,
			@ssos_id			=1001

--------------------------------------------------------------
*/
--------------------------------------------------------------

DECLARE @intBranchCurrId			AS INT
DECLARE @intBranchCurrId4Exchange	AS INT
SELECT	@intBranchCurrId			= tb.curr_id,
		@intBranchCurrId4Exchange	= tb.curr_id4Exchange
  FROM tbBranch tb
	WHERE	tb.comp_id	= @comp_id
		AND tb.bra_id	= @bra_id

DECLARE @SaleOrderBraId4Update AS INT
SELECT @SaleOrderBraId4Update = tb.bra_SaleOrderBraId4Update
	FROM tbBranch tb
	WHERE	tb.comp_id	= @comp_id
		AND tb.bra_id	= @bra_id



SELECT ' ' [ ],
	   '#' + dbo.fnGetSaleOrderNumber(soh.comp_id,soh.bra_id,soh.soh_id) + '¦' +
		convert(nvarchar(4),IsNull(sov.optval_desc,'')) + '¦' + vsos.ssos_desc 									[ssos_desc],
	    soh.soh_deliveryDate																					[soh_deliveryDate],
	    LTRIM(RTRIM(isnull(tc2.curr_symbol,''))) + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),soh.soh_Atotal))	[soh_total_curr_id4Exchange],
		Convert(Varchar,soh.bra_id) + '-' + Convert(Varchar,soh.soh_id)											[ID]

FROM dbo.tbSaleOrderHeader					soh


		inner join dbo.tbCustomer			cu
		on	cu.cust_id		= soh.cust_id
		And cu.comp_id		= soh.comp_id

		LEFT JOIN tbCustomerBranch			tcb
		ON	tcb.comp_id		= soh.comp_id
		AND tcb.cust_id		= soh.cust_id
		AND tcb.cb_id		= soh.cb_id

		inner join dbo.tbBranch				bra
		on	bra.comp_id		= soh.comp_id
		And bra.bra_id		= soh.bra_id

		INNER join dbo.tbDocumentsFile		df
		on	df.comp_id		= soh.comp_id
		and df.df_id		= soh.df_id

		Left Join dbo.tbsysOptionsValues	SOV
		On	SOV.lang_id		= @lang_id
		and SOV.optval_class= 6
		and SOV.optval_id	= df.sd_id

		left join dbo.tbUser				us
		on	us.[user_id]	= soh.[user_id]

		LEFT JOIN vwSaleOrderStatus			vsos
		ON	vsos.comp_id	= soh.comp_id
		AND vsos.bra_id		= soh.bra_id
		AND vsos.soh_id		= soh.soh_id
		AND vsos.lang_id	= @lang_id

		INNER JOIN tbsysCurrency			tc
		ON	tc.curr_id		= bra.curr_id

		INNER JOIN tbsysCurrency			tc2
		ON	tc2.curr_id		= @intBranchCurrId4Exchange

		LEFT JOIN tbCustomerWaiting			tcw
		ON	tcw.comp_id		= soh.comp_id
		AND tcw.bra_id		= soh.bra_id
		AND tcw.cust_id		= soh.cust_id


where	soh.comp_id		=   @comp_id
AND		(cu.cust_id		=	@cust_id	OR	@cust_id	= -1)
		AND		(
					(@ssos_id = 1000						AND IsNull(soh.ssos_id,10) < 100								) OR		-- Parte		: 450
					(@ssos_id = 1001						AND IsNull(soh.ssos_id,10) BETWEEN 200 AND 205					) OR		-- Parte		: 450
					(((@ssos_id < 1000 AND @ssos_id <> 15)  AND IsNull(soh.ssos_id,10) = @ssos_id	)	OR @ssos_id = 15	) OR		-- Parte		: 450
					(@ssos_id = 1002						AND df.sd_id IN (5))											  OR -- Presupuestos
					(@ssos_id = 1003						AND df.sd_id = 80)
				)


order by soh.soh_deliveryDate



END
GO



