*/
-- -----------------------------------------------------------------------------------------------------------------------







	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 300
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on
	set dateformat 'ymd'
	-- =================================================================================================================
	-- Author		: MOS
	-- Update Date	:
	-- Parte		: 450
	-- Description	: Para cumplir el requerimiento solicitado, se modificaron las condiciones en el where relacionadas
	--				  al campo @ssos_id
	-- =================================================================================================================


	-- ---------------------------------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------------------------------
	/*
	declare 	@comp_id			int,
				@lang_id			INT,
				@bra_id				int,
				@sm_id				int,
				@cust_id			int,
				@st_id				int,
				@disc_id			int,
				@stor_id			int,
				@df_id				int,
				@dl_id				int,
				@user_id			int,
				@datefrom			datetime,--varchar(10),
				@dateto				datetime,--varchar(10),
				@item_id			INT,
				@ssos_id			INT,
				@option				INT,
				@NumberFrom			VARCHAR(40),
				@cust_id_Op			INT,
				@estado				INT,
				@ss_id				INT,

				@page_size			INT,
				@page_number		INT,
				@order_by			VARCHAR(8000),
				@prof_id			INT,
				@bitAuthorizationPending	BIT,
				@pro_id				INT,
				@perceptionOptions	INT	,
				@soh_note4ExternalUse	NVARCHAR(20) = 'icbc',
				@bitExcludeIsEditingSO		BIT = 'False',
				@dc_id						INT = -1,
				@datFromInsertDate			DATETIME,
				@datToInsertDate			DATETIME,

				@ss_id_bra					INT = -1,			-- Area de Ventas de la Sucursal
				@mls_id						INT = -1,			-- Tienda de ML
				@item_id_exclude			INT = -1,				-- Excluir Pedidos con Artículo
				@datFromDateItem			DATETIME = '1900-01-01',
				@datToDateItem				DATETIME = '2999-12-31',
				@delivery_type				INT	= -1


	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@sm_id				= -1,--8,
				@cust_id			= -1,
				@st_id				= -1,--3,
				@disc_id			= -1,--5,
				@stor_id			= -1,
				@df_id				= -1,
				@dl_id				= -1,
				@user_id			= -1,
				@datefrom			= '1900-01-01',--convert(datetime,),
				@dateto				= '2999-12-31',--convert(datetime,'2008-12-31'),
				@item_id			= -1,
				@ssos_id			= 1000,
				@option             = -1,
				@NumberFrom			= '',
				@cust_id_Op			= -1,
				@estado				= -1,
				@page_size			=100,
				@page_number		=0,
				@order_by			='',
				@ss_id				= -1,
				@prof_id			=	1,
				@bitAuthorizationPending	=0,
				@pro_id				= -1,
				@perceptionOptions	= -1,
				@datFromInsertDate	= '1900-01-01',--convert(datetime,),
				@datToInsertDate	= '2999-12-31'--convert(datetime,'2008-12-31')

				--DROP TABLE #tmpSOS
				--DROP TABLE #tmpStBySoh
				--DROP TABLE #tmpSerials
	*/
	-- ---------------------------------------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- -----------------------------------------------------------------------------
	DECLARE @bitDeliveryDateActivated AS BIT = 'False'
	IF YEAR(@datFromDateItem) <> 1900 OR YEAR(@datToDateItem)  <> 9999
		BEGIN
			SET @bitDeliveryDateActivated	= 'True'
			SET @datFromDateItem			= dbo.fnGetEnd_or_BeginOfDate(@datFromDateItem,'False')
			SET @datToDateItem				= dbo.fnGetEnd_or_BeginOfDate(@datToDateItem,'True')
		END
	-- -----------------------------------------------------------------------------



	SET  @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET  @dateTo	= dbo.fnGetEnd_or_BeginOfDate(@dateTo  ,'True')
	SET  @datFromInsertDate	= dbo.fnGetEnd_or_BeginOfDate(@datFromInsertDate,'False')
	SET  @datToInsertDate	= dbo.fnGetEnd_or_BeginOfDate(@datToInsertDate  ,'True')




	SET @soh_note4ExternalUse = dbo.fnStrAllTrim(@soh_note4ExternalUse)


	-- -----------------------------------------------------------------
	-- Obtengo las sucursal que debe permitir modificar un pedido de la
	-- sucursal actual
	-- -----------------------------------------------------------------
	DECLARE @SaleOrderBraId4Update AS INT
	--SELECT  @SaleOrderBraId4Update = tb.bra_SaleOrderBraId4Update
	--	FROM tbBranch tb		WITH (NOLOCK)
	--	WHERE	tb.comp_id	= @comp_id
	--		AND tb.bra_id	= @bra_id
	-- -----------------------------------------------------------------


	-- -----------------------------------------------------------------
	-- Asignacion de variables
	-- -----------------------------------------------------------------
	DECLARE @intBranchCurrId			AS INT
	DECLARE @intBranchCurrId4Exchange	AS INT
	--SELECT	@intBranchCurrId			= tb.curr_id,
	--			@intBranchCurrId4Exchange	= tb.curr_id4Exchange
	--  FROM tbBranch tb					 WITH (NOLOCK)
	--	WHERE	tb.comp_id	= @comp_id
	--		AND tb.bra_id	= @bra_id
	-- -----------------------------------------------------------------


	-- --------------------------------------------------------------
	-- Pone las sucursales validas para incluir pedidos
	-- --------------------------------------------------------------
	DECLARE		@tmpBranch			TABLE(bra_id INT PRIMARY KEY)
	DECLARE		@tmpBranch4Update	TABLE(bra_id INT PRIMARY KEY)
	INSERT INTO @tmpBranch(bra_id)  VALUES (@bra_id)
	DECLARE		@brag_id		AS INT
	DECLARE		@brag_id4Update AS INT


	SELECT  @brag_id					= tb.brag_id4SaleOrderALL,
			@brag_id4Update				= tb.brag_id4SaleOrderALLUpdate,
			@SaleOrderBraId4Update		= tb.bra_SaleOrderBraId4Update,
			@intBranchCurrId			= tb.curr_id,
			@intBranchCurrId4Exchange	= tb.curr_id4Exchange
		FROM tbbranch tb										WITH (NOLOCK)
		WHERE	comp_id = @comp_id AND
				bra_id	= @bra_id


	IF @brag_id IS NOT NULL
		BEGIN
			INSERT INTO @tmpBranch(bra_id)
				SELECT tbgd.bra_id
					FROM tbBranchGroupDetail tbgd				WITH (NOLOCK)
					WHERE	tbgd.comp_id = @comp_id AND
							tbgd.brag_id = @brag_id AND
							tbgd.bra_id <> @bra_id
		END
	INSERT INTO @tmpBranch4Update(bra_id)
		SELECT tbgd.bra_id
			FROM tbBranchGroupDetail tbgd					WITH (NOLOCK)
			WHERE	tbgd.comp_id = @comp_id			AND
					tbgd.brag_id = @brag_id4Update
	-- --------------------------------------------------------------



	-- --------------------------------------------------------------
	-- Pone los Vendedores relacionados al usuario para, si tiene q ver solo sus pedidos,
	-- incluya los de los vendedores relacionados a su usuario
	-- --------------------------------------------------------------
	DECLARE		@tmpUsers  TABLE(sm_id INT PRIMARY KEY)
	INSERT INTO @tmpUsers(sm_id)
		SELECT DISTINCT tusr.sm_id
			FROM tbUserSalesmanRelation tusr		WITH (NOLOCK)
			WHERE	tusr.comp_id	= @comp_id	AND
					tusr.bra_id		= @bra_id	AND
					tusr.[user_id]	= @user_id
	-- --------------------------------------------------------------

--==
--SELECT 10,GETDATE()

	-- --------------------------------------------------------------
	-- Solo docuentos que puedan mostrarse con el perfil actual
	-- --------------------------------------------------------------
	DECLARE @tmpDocumentsByProfile AS TABLE(df_id	INT	PRIMARY KEY)
	INSERT INTO @tmpDocumentsByProfile(df_id)
		SELECT DISTINCT tdf.df_id
		FROM tbDocumentsFile tdf							WITH (NOLOCK)
		LEFT JOIN tbDocumentsFileByProfile tdfbp				WITH (NOLOCK)
			ON	tdfbp.comp_id	= tdf.comp_id	AND
				tdfbp.bra_id	= tdf.bra_id	AND
				tdfbp.df_id		= tdf.df_id
		WHERE	CASE
				    WHEN tdf.df_SaleOrder_Selection_ShowOnlyByProfile = 'False'		THEN	'True'
				    WHEN tdf.df_SaleOrder_Selection_ShowOnlyByProfile = 'True'  AND
			    		 tdfbp.comp_id	= @comp_id								AND
						 tdfbp.bra_id	= @bra_id								AND
						 tdfbp.prof_id	= @prof_id
																		     		THEN	'True'
				    ELSE																	'False'
				END	= 'true'

	-- --------------------------------------------------------------





	-- --------------------------------------------------------------
	-- Pedidos que NO deban Prepararse x estados pendientes de autorizar
	-- --------------------------------------------------------------
	DECLARE @tblSaleOrderStatus AS TABLE(	comp_id INT,
											bra_id	INT,
											soh_id	INT, UNIQUE CLUSTERED(comp_id,bra_id,soh_id))
	INSERT INTO @tblSaleOrderStatus (comp_id, bra_id, soh_id)
		SELECT distinct tsos2.comp_id,
						tsos2.bra_id,
						tsos2.soh_id
			FROM tbSaleOrderStatus			tsos2			WITH (NOLOCK)
			INNER JOIN tbSaleOrderHeader AS tsoh			WITH (NOLOCK)			-- MOS 09-2024: x FORRADA de MR y HR con no se quien MIERDA DE FORRRO
				ON	tsoh.comp_id	= tsos2.comp_id AND
					tsoh.bra_id		= tsos2.bra_id	AND
					tsoh.soh_id		= tsos2.soh_id
			INNER JOIN tbDocumentsFile	AS  tdf				WITH (NOLOCK)			-- MOS 09-2024: x FORRADA de MR y HR con no se quien MIERDA DE FORRRO
				ON	tdf.comp_id		= tsoh.comp_id	AND
					tdf.df_id		= tsoh.df_id
			INNER JOIN tbSaleOrderStatusConcept tsosc		WITH (NOLOCK)
			ON		tsosc.comp_id						= tsos2.comp_id	AND
					tsosc.sosc_id						= tsos2.sosc_id	AND
					tsosc.sosc_blockSaleOrderEmmition	= 'True'		AND
					CASE		-- MOS 09-2024: Si tiene ese check y es una PUTA FACTURA ANTICIPADA que Permita Emitir.
						WHEN tsosc.sosc_emmitionApproveIfPreInvoice = 'True' AND tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL	THEN 0
						WHEN tsosc.sosc_emmitionApproveIfPreInvoice = 'False'	THEN 1
						ELSE 1
					END = 1
			WHERE	tsos2.comp_id		= @comp_id
				--AND tsos2.bra_id		= soh.bra_id
				--AND tsos2.soh_id		= soh.soh_id
				AND tsos2.sos_ok		= 'False'
	-- --------------------------------------------------------------


--==
--SELECT 20,GETDATE()

	-- ---------------------------------
	-- Generacion de Tablas Temporales
	-- ---------------------------------
	DECLARE @tmpDeliveryStatus	as table(	comp_id	int,
											bra_id	int,
											soh_id	INT,
											UNIQUE CLUSTERED(comp_id,bra_id,soh_id)
								)
	DECLARE @tmpStBySoh as table(	comp_id	int,
									bra_id	int,
									soh_id	int,
									qty		INT,
									UNIQUE CLUSTERED(comp_id,bra_id,soh_id)
								)

	DECLARE @tmpSOS		as table(	comp_id	int,
									bra_id	int,
									soh_id	int,
									[count]	INT,
									UNIQUE CLUSTERED(comp_id,bra_id,soh_id)
								)
	DECLARE @tmpSerials	as table(	comp_id	int,
									bra_id	int,
									soh_id	INT,
									UNIQUE CLUSTERED(comp_id,bra_id,soh_id)
								)
	DECLARE @tmpAuthorizationPending AS TABLE(
									comp_id	int,
									bra_id	int,
									soh_id	INT,
									UNIQUE CLUSTERED(comp_id,bra_id,soh_id)
									         )
	-- ---------------------------------

	-- ---------------------------------
	-- Autorizaciones Pendientes
	-- ---------------------------------
	--DECLARE @bitAuthorizationPending	BIT
	--SET @bitAuthorizationPending		= 'False'
	INSERT INTO @tmpAuthorizationPending(comp_id, bra_id, soh_id)
		SELECT	DISTINCT
				tarpso.comp_id,
				tarpso.soh_bra_id,
				tarpso.soh_id
			FROM tbAutorizationRequest_PendingSaleOrders tarpso				WITH (NOLOCK)
			WHERE tarpso.aure_isok <> 'A'
	-- ---------------------------------


	-- MOS 05-2023: se pone mas arriba para no llamar al pedo 2 veces
	---- -----------------------------------------------------------------
	---- Obtengo las sucursal que debe permitir modificar un pedido de la
	---- sucursal actual
	---- -----------------------------------------------------------------
	--DECLARE @SaleOrderBraId4Update AS INT
	--SELECT  @SaleOrderBraId4Update = tb.bra_SaleOrderBraId4Update
	--	FROM tbBranch tb		WITH (NOLOCK)
	--	WHERE	tb.comp_id	= @comp_id
	--		AND tb.bra_id	= @bra_id
	---- -----------------------------------------------------------------


	-- -----------------------------------------------------------------
	--obtengo la cantidad de estados aprobados que debe tener cada Pedido
	-- -----------------------------------------------------------------
	DECLARE @sos_qty	DECIMAL(19,6)
	INSERT INTO @tmpStBySoh	(	comp_id,
								bra_id,
								soh_id,
								qty)
	SELECT
			tsoh.comp_id,
			tsoh.bra_id,
			tsoh.soh_id,
			sum(case
					when isnull(tsos.sos_id,0) = 0 THEN 0
					ELSE 1
				END)							[qty]
		FROM	tbSaleOrderHeader tsoh									WITH (NOLOCK)
		LEFT JOIN tbSaleOrderStatus tsos								WITH (NOLOCK)
			ON  tsos.comp_id	= tsoh.comp_id
			AND tsos.soh_id		= tsoh.soh_id
			AND tsos.bra_id		= tsoh.bra_id
			-- MOS 05-2023: MIrando vi que esto está al PEDO, si arriba esta con = y NO da igual, es al pedo comparar x null.  tal vez sea un futuro bug
			-- AND		(tsos.bra_id = @bra_id OR tsos.bra_id IS NULL)
		WHERE	tsoh.comp_id = @comp_id	AND
				-- MOS 12-2020 para acotar estas busquedas en gente que tiene 100000 pedidos AL PEDO
				tsoh.soh_deliveryDate BETWEEN  @datefrom			AND @dateto				AND
				tsoh.soh_lastUpdate	  BETWEEN  @datFromInsertDate   AND @datToInsertDate
		GROUP BY	tsoh.comp_id,
					tsoh.bra_id,
					tsoh.soh_id
	-- -----------------------------------------------------------------



--==
--SELECT 30,GETDATE()


	-- -----------------------------------------------------------------
	-- recupero solo los Pedidos que tienen todos los estados aprobados
	-- -----------------------------------------------------------------
	insert into @tmpSOS (	comp_id,
							bra_id,
							soh_id,
							[count])
		SELECT	tsos.comp_id,
				tsos.bra_id,
				tsos.soh_id,
				0 /*COUNT(*)*/	[count]

		FROM	tbSaleOrderStatus tsos				WITH (NOLOCK)
				INNER JOIN @tmpStBySoh tsbs
				ON		tsos.comp_id= tsbs.comp_id
					AND tsos.bra_id = tsbs.bra_id
					and	tsos.soh_id = tsbs.soh_id

		WHERE	tsos.comp_id	= @comp_id
			--AND	(tsos.bra_id	= @bra_id OR tsos.bra_id IS NULL)
			AND  tsos.sos_ok	= 'True'
		GROUP BY	tsos.comp_id,
					tsos.bra_id,
					tsos.soh_id,
					tsbs.[qty]
		HAVING COUNT(*) = tsbs.[qty]

	INSERT INTO @tmpSOS (	comp_id,
							bra_id,
							soh_id,
							[COUNT])
		SELECT	comp_id,
				bra_id,
				soh_id,
				qty
		FROM @tmpStBySoh
		WHERE	qty = 0
	-- -----------------------------------------------------------------


--==
--SELECT 32,GETDATE()


	-- -----------------------------------------------------------------
	-- Articulos que tienen algun metodo de entrega diferente a Retira
	-- Ya
	-- -----------------------------------------------------------------
	insert into @tmpDeliveryStatus (	comp_id,
										bra_id,
										soh_id)
		SELECT		DISTINCT
				tsoh.comp_id,
				tsoh.bra_id,
				tsoh.soh_id
			FROM tbSaleOrderHeader tsoh						WITH (NOLOCK)
			INNER JOIN tbSaleOrderDetail tsod				WITH (NOLOCK)
			ON	tsod.comp_id	= tsoh.comp_id	AND
				tsod.bra_id		= tsoh.bra_id	AND
				tsod.soh_id		= tsoh.soh_id
			INNER JOIN tbDocumentsFile tdf					WITH (NOLOCK)
				ON		tdf.comp_id		= tsoh.comp_id	AND
						tdf.bra_id		= tsoh.bra_id	AND		-- MOS 05-2023: x speed
						tdf.df_id		= tsoh.df_id
			WHERE	tsoh.comp_id		= @comp_id
				AND	tsoh.bra_id			= @bra_id		AND
				-- MOS 12-2020 para acotar estas busquedas en gente que tiene 100000 pedidos AL PEDO
				tsoh.soh_deliveryDate BETWEEN  @datefrom			AND @dateto				AND
				tsoh.soh_lastUpdate	  BETWEEN  @datFromInsertDate   AND @datToInsertDate
				--MOS 05-2023: x Speed AND tdf.sd_id IN (1,2,3,4,80)
				AND (tdf.sd_id =  1 OR tdf.sd_id = 2 OR tdf.sd_id = 3 OR tdf.sd_id = 4 OR tdf.sd_id = 80)
				AND tsod.sdlmt_id > 1
	-- -----------------------------------------------------------------


	-- -----------------------------------------------------------------
	-- Recupero los pedidos que tienen tomados numeros de serie
	-- MOS: 31-5-2012
	-- -----------------------------------------------------------------
	insert into @tmpSerials (	comp_id,
								bra_id,
								soh_id)
		SELECT		DISTINCT
				tsoh.comp_id,
				tsoh.bra_id,
				tsoh.soh_id
			FROM tbSaleOrderHeader tsoh						WITH (NOLOCK)
			INNER JOIN tbSaleOrderSerials tsos				WITH (NOLOCK)
				ON		tsos.comp_id	= tsoh.comp_id	AND
						tsos.bra_id		= tsoh.bra_id	AND
						tsos.soh_id		= tsoh.soh_id
			INNER JOIN tbDocumentsFile tdf					WITH (NOLOCK)
				ON		tdf.comp_id		= tsoh.comp_id	AND
						tdf.bra_id		= tsoh.bra_id	AND	-- MOS 05-2023: x Speed
					    tdf.df_id		= tsoh.df_id
			WHERE	tsoh.comp_id		= @comp_id
				AND	tsoh.bra_id			= @bra_id		AND
				-- MOS 12-2020 para acotar estas busquedas en gente que tiene 100000 pedidos AL PEDO
				tsoh.soh_deliveryDate BETWEEN  @datefrom			AND @dateto				AND
				tsoh.soh_lastUpdate	  BETWEEN  @datFromInsertDate   AND @datToInsertDate
				AND (tdf.sd_id =  1 OR tdf.sd_id = 2 OR tdf.sd_id = 3 OR tdf.sd_id = 4 OR tdf.sd_id = 80)
				-- MOS 05-2023: x Speed       AND tdf.sd_id IN (1,2,3,4,80)
	-- -----------------------------------------------------------------

--==
--SELECT 34,GETDATE()


	-- MOS 05-2023: Arriba x Speed
	---- -----------------------------------------------------------------
	---- Asignacion de variables
	---- -----------------------------------------------------------------
	--DECLARE @intBranchCurrId			AS INT
	--DECLARE @intBranchCurrId4Exchange	AS INT
	--SELECT	@intBranchCurrId			= tb.curr_id,
	--		@intBranchCurrId4Exchange	= tb.curr_id4Exchange
	--  FROM tbBranch tb					 WITH (NOLOCK)
	--	WHERE	tb.comp_id	= @comp_id
	--		AND tb.bra_id	= @bra_id
	---- -----------------------------------------------------------------






	-- -----------------------------------------------------------------
	-- Borra los estados para que se des-habilite el boton procesar si
	-- el cliente esta INACTIVO
	-- -----------------------------------------------------------------
	DELETE  @tmpSOS
		FROM @tmpSOS tmp
		INNER JOIN tbSaleOrderHeader tsoh					WITH (NOLOCK)
			ON	tmp.comp_id = tsoh.comp_id	AND
				tmp.bra_id	= tsoh.bra_id	AND
				tmp.soh_id	= tsoh.soh_id
		INNER JOIN tbCustomer tc							WITH (NOLOCK)
			ON	tc.comp_id	= tsoh.comp_id	AND
				tc.cust_id	= tsoh.cust_id
		WHERE tc.cust_inactive = 'True'
	-- -----------------------------------------------------------------

--==
--SELECT 36,GETDATE()


	-- -----------------------------------------------------------------
	-- Borra los estados si el Comprobante es Factura Adelantada
	-- -----------------------------------------------------------------
	DELETE  @tmpSOS
		FROM @tmpSOS tmp
		INNER JOIN tbSaleOrderHeader tsoh				WITH (NOLOCK)
			ON	tmp.comp_id = tsoh.comp_id	AND
				tmp.bra_id	= tsoh.bra_id	AND
				tmp.soh_id	= tsoh.soh_id
		INNER JOIN tbDocumentsFile tdf					WITH (NOLOCK)
			ON	tdf.comp_id = tsoh.comp_id	AND
				tdf.bra_id	= tsoh.bra_id	AND
				tdf.df_id	= tsoh.df_id
		WHERE tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL
	-- -----------------------------------------------------------------

--==
--SELECT 40,GETDATE()


	-- ---------------------------------------------------------------------------------
	-- ATENCION:    Aqui va el WHERE
	-- Genera una Tabla Temporal con los pedidos a Filtrar
	-- ---------------------------------------------------------------------------------
	declare @tmpSOFilter as table	(
								comp_id	 int,
								bra_id	 int,
								soh_id	 INT,
								UNIQUE CLUSTERED(comp_id,bra_id,soh_id)
								)
	insert  @tmpSOFilter	(comp_id,bra_id,soh_id)
	SELECT	soh.comp_id,soh.bra_id,soh.soh_id

		FROM	dbo.tbSaleOrderHeader				soh			WITH (NOLOCK)

				INNER JOIN @tmpDocumentsByProfile tmpdoc
					ON tmpdoc.df_id = soh.df_id

				INNER JOIN tbCustomer				cu				WITH (NOLOCK)
				ON	cu.comp_id		= soh.comp_id AND
					cu.cust_id		= soh.cust_id

				INNER JOIN tbDocumentsFile			df				WITH (NOLOCK)
				on	df.comp_id		= soh.comp_id	AND
					df.bra_id		= soh.bra_id	AND		-- MOS 05-2023: x Speed
				    df.df_id		= soh.df_id

				LEFT  JOIN tbsysCurrency			tc2						WITH (NOLOCK)	-- MOS 07-2024 left
				ON	tc2.curr_id		= @intBranchCurrId4Exchange


				LEFT JOIN @tmpUsers					tmp
					ON tmp.sm_id = soh.sm_id

				LEFT JOIN tbSaleSector				tss				WITH (NOLOCK)
				ON	tss.comp_id		= cu.comp_id AND
					tss.ss_id		= cu.ss_id

				LEFT JOIN tbCustomerBranch			tcb				WITH (NOLOCK)
				ON	tcb.comp_id		= soh.comp_id
				AND tcb.cust_id		= soh.cust_id
				AND tcb.cb_id		= soh.cb_id



				LEFT JOIN vwSaleOrderStatus			vsos			WITH (NOLOCK)		-- ? speed?
				ON	vsos.comp_id	= soh.comp_id
				AND vsos.bra_id		= soh.bra_id
				AND vsos.soh_id		= soh.soh_id
				AND vsos.lang_id	= @lang_id

				LEFT JOIN @tmpBranch tmpB
					ON tmpB.bra_id = soh.bra_id

				LEFT JOIN tbCustomerWaiting			cw						WITH (NOLOCK)
				ON	cw.comp_id		= soh.comp_id
				AND cw.bra_id		= soh.bra_id
				AND cw.cust_id		= soh.cust_id


				LEFT JOIN tbSaleOrderProcess_DocumentsExcluded exd			WITH (NOLOCK)
					ON	exd.comp_id = soh.comp_id AND
						exd.bra_id  = @bra_id	 AND
						exd.prof_id = @prof_id	 AND
						exd.df_id   = soh.df_id

				LEFT JOIN @tmpAuthorizationPending tmpa
					ON	tmpa.comp_id	= soh.comp_id	AND
						tmpa.bra_id		= soh.bra_id	AND
						tmpa.soh_id		= soh.soh_id

				LEFT JOIN tbMercadoLibre_ordersHeader	tmloh				WITH (NOLOCK)
					ON	tmloh.comp_id	= soh.comp_id	AND
						tmloh.mlo_id	= soh.mlo_id

				LEFT JOIN tbMercadoLibre_Branchs		tmlb				WITH (NOLOCK)
					ON	tmlb.comp_id	= tmloh.comp_id AND
						tmlb.mlbra_id	= tmloh.mlbra_id

				LEFT JOIN tbMercadoLibre_ordersShipping tmlos				WITH (NOLOCK)
					ON	tmlos.comp_id	= soh.comp_id	AND	-- MOS 12-2020 estaba con tmloh
						tmlos.mlo_id	= soh.mlo_id

				LEFT JOIN tbTiendaNube_Orders		 AS ttno				WITH (NOLOCK,INDEX(IX_tbTiendaNube_Orders_SaleOrderHeader))
					ON	ttno.comp_id	= soh.comp_id	AND
						ttno.bra_id		= soh.bra_id	AND
						ttno.soh_id		= soh.soh_id


		Where	soh.comp_id		=   @comp_id

		AND		CASE	-- MOS 07-2015
					WHEN soh.bra_id			= @bra_id					THEN 1
					WHEN tmpB.bra_id IS NOT NULL						THEN 1
					WHEN cu.bra_id4Emmition	= @bra_id					THEN 1
					WHEN soh.bra_id			= @SaleOrderBraId4Update	THEN 1
					ELSE												     0
				END   = 1

				--(	-- Selecciona de cuales sucursales va a mostrar los pedidos.
				--	soh.bra_id			= @bra_id	OR
				--   (tmpB.bra_id IS NOT NULL)		OR -- Agregado MOS 07-2015 x Grupo de Sucursales Permitido
				--	cu.bra_id4Emmition	= @bra_id	OR
				--	soh.bra_id			= @SaleOrderBraId4Update
				--)

		AND		(@sm_id		= -1 OR soh.sm_id		=	@sm_id			)
		AND		(@cust_id	= -1 OR cu.cust_id		=	@cust_id		)
		AND		(@st_id		= -1 OR soh.st_id		=	@st_id			)
		AND		(@disc_id	= -1 OR soh.disc_id		=	@disc_id		)
		AND		(@df_id		= -1 OR df.df_id		=	@df_id			)
		AND		(@dl_id		= -1 OR soh.dl_id		=	@dl_id			)
		AND		(@user_id	= -1 OR  soh.[user_id]	=	@user_id	OR	tmp.sm_id IS NOT NULL)
		AND		soh.soh_deliveryDate between @datefrom  and	@dateto
		AND		soh.soh_lastUpdate	 between @datFromInsertDate AND @datToInsertDate

		AND		(@cust_id_Op  = -1   OR NOT cw.cust_id IS NULL	)

		AND
					CASE
					    WHEN @item_id		= -1												THEN	1
					    WHEN EXISTS (SELECT TOP 1  1
										FROM	tbSaleOrderDetail sod			WITH (NOLOCK)
										WHERE	sod.comp_id		= @comp_id
										AND     sod.bra_id      = soh.bra_id /*MOS 07-2015 @bra_id*/
										AND		sod.soh_id		= soh.soh_id
										AND		sod.item_id		= @item_id	)					THEN	1
					    ELSE																			0
					END = 1


		AND
					CASE
					    WHEN @stor_id	    = -1												THEN	1
					    WHEN EXISTS (SELECT TOP 1 1
										FROM	tbSaleOrderDetail sod			WITH (NOLOCK)
										WHERE	sod.comp_id		= @comp_id
										AND		sod.soh_id		= soh.soh_id
										AND     sod.bra_id      = soh.bra_id /*MOS 07-2015 @bra_id*/
										AND		sod.stor_id		= @stor_id	)					THEN	1
					    ELSE																			0
					END = 1



		-- -----------------------------------------------
		-- Todo esto es MIERDA LENTA
		-- -----------------------------------------------
		AND

		CASE
			WHEN		@ssos_id = 1000						AND soh.ssos_id < 100					THEN 1
			WHEN		@ssos_id BETWEEN 2000 AND 2999												THEN 1	-- Estados de MercadoLibre
			WHEN		@ssos_id BETWEEN 5000 AND 5100	AND ttno.comp_id IS NOT NULL 				THEN 1	-- Estados de Tienda Nube
			WHEN
				(
					(
						(@ssos_id < 1000 AND @ssos_id <> 15)
							AND
						soh.ssos_id = @ssos_id
					)
						OR
					@ssos_id = 15
				)
																									THEN 1

			-- MOS 05-2023: x defecto solo compara variable q no se compara arriba, x lo q debe ir 1ro.WHEN		@ssos_id BETWEEN 2000 AND 2999												THEN 1
			-- MOS 05-2023: x defecto viene en 100 asi 1 debe ir 1ro...WHEN		@ssos_id = 1000						AND soh.ssos_id < 100					THEN 1		-- Parte		: 450
			WHEN		@ssos_id = 3						AND soh.ws_internalID IS NOT NULL 		THEN 1		-- Todos los Pedidos WEB
			WHEN		@ssos_id = 1001						AND soh.ssos_id BETWEEN 200 AND 205		THEN 1		-- Parte		: 450
	-- Parte		: 450
			WHEN		@ssos_id = 1002						AND df.sd_id = 5						THEN 1		-- Presupuestos
			WHEN		@ssos_id = 1003						AND df.sd_id = 80						THEN 1		-- Pedidos de Produccion
			WHEN		@ssos_id = 0000 OR @ssos_id = 1004											THEN 1

			WHEN	@ssos_id			= 101			AND
					soh.ws_internalID	IS NOT NULL		AND
					soh.ssos_id			= 50			AND
					soh.ws_paymentGateWayStatusID	= 51			THEN 1
			WHEN	@ssos_id			= 102			AND
					soh.ws_internalID	IS NOT NULL		AND
					soh.ssos_id			<> 50			AND
					soh.ws_paymentGateWayStatusID	= 51			THEN 1
			WHEN	@ssos_id			= 103			AND
					soh.ws_internalID	IS NOT NULL		AND
					soh.ws_paymentGateWayStatusID	= 50			THEN 1

			WHEN	@ssos_id			= 150			AND											-- Factura Anticipada
					df.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL		THEN 1

			ELSE			 0
		END	= 1																						 -- TODOS los pedidos que NO SEAN ABONOS:!!!!!


		AND		( (@ssos_id <> 15	and df.sd_id <> 15)	OR (@ssos_id	= 15	and df.sd_id = 15))										 -- Excluye Abono Mensual de TODOS
		AND		( (@ssos_id <> 1002 and df.sd_id <> 5)	OR ((@ssos_id	= 1002	OR	@ssos_id = 1004) and df.sd_id = 5))										 -- Excluye Presupuestos de TODO
		AND		( (@ssos_id <> 1003 and df.sd_id <> 80) OR (@ssos_id	= 1003	and df.sd_id IN (80,145)))										 -- Excluye Presupuestos de TODO
		AND

		-- -----------------------------------------------

		-- Filtros para MercadoLibre, varios
		CASE
			-- TiendaNube
			WHEN @ssos_id = 5000 AND	ttno.comp_id IS NOT NULL 				THEN 1	-- Tienda Nube Todos los Pedidos.
			WHEN @ssos_id < 2000 OR		@ssos_id > 2999							THEN 1		-- x Velocidad si no es MeLi pasa de largo
			WHEN @ssos_id = 2000 AND	tmloh.comp_id IS NOT NULL				THEN 1		-- MercadoLibre©: Todos los Pedidos
			WHEN @ssos_id = 2010 AND 	tmloh.comp_id IS NOT NULL		AND
										soh.ssos_id			= 50		AND
										tmlos.MLfulfilled	= 'False'	AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Todos los Pedidos para Facturar Preparados
			WHEN @ssos_id = 2020 AND	tmloh.comp_id IS NOT NULL		AND
										tmlos.MLfulfilled	= 'False'	AND
										tmloh.mlo_status    <> 'cancelled' 			THEN 1		-- MercadoLibre©: Todos los Pedidos para Facturar

			WHEN @ssos_id = 2030 AND 	tmloh.comp_id IS NOT NULL			AND
										tmlos.MLfulfilled	= 'True'		AND
										tmlos.MLstatus		= 'delivered'	AND
										tmloh.mlo_status    <> 'cancelled'
																				THEN 1		--MercadoLibre©: FulFillment Entregados
			WHEN @ssos_id = 2040 AND	tmloh.comp_id IS NOT NULL			AND
										tmlos.MLfulfilled	= 'True'		AND
										tmlos.MLstatus		<> 'delivered'	AND
										tmloh.mlo_status    <> 'cancelled'		THEN 1		--MercadoLibre©: FulFillment NO Entregados

			WHEN @ssos_id = 2050 AND 	tmloh.comp_id IS NOT NULL		AND
										soh.ssos_id			= 50		AND
										tmlos.MLSelf_Service= 'True'	AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Entrega Flex Preparados
			WHEN @ssos_id = 2060 AND 	tmloh.comp_id IS NOT NULL		AND
										tmlos.MLSelf_Service= 'True'	AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Entrega Flex


			WHEN @ssos_id = 2061 AND 	tmloh.comp_id IS NOT NULL		AND
										tmlos.MLSelf_Service  = 'True'	AND
										(
										 tmlos.MLstatus  = 'delivered'
											OR
										 tmloh.mlo_isDelivered = 'True'
										)								AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Entrega Flex	ENTREGADO


			-- ---------------
			-- TURBO  MOS 03-2024
			-- ---------------
			WHEN @ssos_id = 2065 AND 	tmloh.comp_id IS NOT NULL		AND
										soh.ssos_id			= 50		AND
										tmlos.MLturbo		= 'True'	AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Entrega TURBO - Preparados
			WHEN @ssos_id = 2066 AND 	tmloh.comp_id IS NOT NULL		AND
										tmlos.MLturbo		= 'True'	AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Entrega TURBO


			WHEN @ssos_id = 2067 AND 	tmloh.comp_id IS NOT NULL		AND
										tmlos.MLturbo		= 'True'	AND
										(
										 tmlos.MLstatus  = 'delivered'
											OR
										 tmloh.mlo_isDelivered = 'True'
										)								AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Entrega TURBO - Entregados
			-- ---------------



			WHEN @ssos_id = 2070 AND 	tmloh.comp_id IS NOT NULL		AND
										tmlb.comp_id  IS NOT NULL		AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Retiro en Sucursal

			WHEN @ssos_id = 2075 AND 	tmloh.comp_id IS NOT NULL			AND
										tmlb.comp_id  IS     NULL			AND
										ISNULL(tmloh.MLShippingID,0) = 0	AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Retiro en LOCAL

			WHEN @ssos_id = 2076 AND 	tmloh.comp_id IS NOT NULL			AND
										tmlb.comp_id  IS     NULL			AND
										(
											tmlos.MLstatus			= 'delivered'
										 -- MOS 04-2022: es pedidos Entregados no Enviados.
										 --OR
										 --	tmlos.MLstatus			= 'shipped'
										 OR
											tmloh.mlo_isDelivered	= 'True'
										)									AND
										ISNULL(tmloh.MLShippingID,0) = 0	AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Retiro en LOCAL


			WHEN @ssos_id = 2077 AND 	tmloh.comp_id IS NOT NULL			AND
										tmlb.comp_id  IS     NULL			AND
										(
											tmlos.MLstatus			= 'delivered'
										 -- MOS 04-2022: es pedidos Entregados no Enviados.
										 --OR
										 --	tmlos.MLstatus			= 'shipped'
										 OR
											tmloh.mlo_isDelivered	= 'True'
										)									AND
										tmloh.mlo_status    <> 'cancelled'
										     									THEN 1		-- MercadoLibre©: Todos los pedidos ENTREGADOS

			WHEN @ssos_id IN (2080,2085)										THEN		-- MercadoLibre, Reclamos o Mediaciones
										CASE
											WHEN @ssos_id = 2080 AND EXISTS(SELECT TOP 1 1 FROM tbMercadoLibre_Claims tmlc	WITH (NOLOCK) WHERE tmlc.comp_id = @comp_id AND tmlc.mlo_id = soh.mlo_id)							THEN 1
											WHEN @ssos_id = 2085 AND EXISTS(SELECT TOP 1 1 FROM tbMercadoLibre_Claims tmlc	WITH (NOLOCK) WHERE tmlc.comp_id = @comp_id AND tmlc.mlo_id = soh.mlo_id AND tmlc.claim_closed = 0)	THEN 1
											ELSE 0
										END

			WHEN @ssos_id = 2090 AND 	tmloh.comp_id IS NOT NULL		AND
										tmlb.comp_id  IS     NULL		AND
										tmloh.mlo_status = 'cancelled'
										     									THEN 1		-- MercadoLibre©: Cancelado

			WHEN @ssos_id = 2095 AND 	tmloh.comp_id IS NOT NULL										AND
										tmlos.MLfulfilled		= 'False'								AND
										tmlos.ML_logistic_type	IN ('xd_drop_off', 'cross_docking','drop_off')		AND
										tmlos.MLstatus			NOT IN ('delivered')					AND
										-- MOS 04-2022: es pedidos Entregados no Enviados.
										--tmlos.MLstatus			NOT IN ('delivered','shipped')			AND
										tmloh.mlo_status    <> 'cancelled'
																				THEN 1		--MercadoLibre©: Envío mediante MercadoEnvíos - Pendiente de entregar

			WHEN @ssos_id = 2096 AND 	tmloh.comp_id IS NOT NULL											AND
										tmlos.MLfulfilled		= 'False'									AND
										tmlos.ML_logistic_type	IN ('xd_drop_off', 'cross_docking','drop_off')	 		AND
										tmlos.MLstatus			IN ('delivered')							AND
										-- MOS 04-2022: es pedidos Entregados no Enviados.
										--tmlos.MLstatus			IN ('delivered','shipped')					AND
										tmloh.mlo_status    <> 'cancelled'
																				THEN 1		--MercadoLibre©: Envío mediante MercadoEnvíos - Entregado

			WHEN @ssos_id = 2098 AND	cu.fc_id = 3 AND df.df_Kindof = 'A'			THEN 1
			WHEN @ssos_id = 2099 AND	cu.fc_id = 3 AND df.df_Kindof = 'B'			THEN 1
			WHEN @ssos_id = 2101 AND
				 ISNULL(soh.soh_note4ExternalUse,'') <> '' AND
				 vsos.ssos_id = 50													THEN 1
			WHEN @ssos_id = 2100 AND
				 ISNULL(soh.soh_note4ExternalUse,'') <> ''							THEN 1




			ELSE 0
		END	= 1
		-- Filtros para MercadoLibre


		AND

			CASE
				WHEN @option = -1	THEN 1
				WHEN
					(@option = 0 and soh.soh_id like			@NumberFrom + '%')	    or
					(@option = 1 and soh.soh_id like '%' +		@NumberFrom + '%')	    or
					(@option = 2 and soh.soh_id =				@NumberFrom)			or
					(@option = 3 and soh.soh_id <>				@NumberFrom)			or
					(@option = 4 and soh.soh_id not like '%' +	@NumberFrom + '%')
									THEN 1
				ELSE					 0
			END = 1


		AND		(
					CASE
						WHEN @estado = -1														THEN 1
						WHEN @estado =  1 AND  EXISTS(	SELECT TOP 1  1
															FROM tbSaleOrderStatus tsos			WITH (NOLOCK)
					                              			WHERE	tsos.comp_id	= soh.comp_id
					                              				AND tsos.bra_id		= soh.bra_id
					                              				AND tsos.soh_id		= soh.soh_id
					                              				AND tsos.sos_ok		= 'False')	THEN 1 --  Pendientes de Autorizacion.
						WHEN @estado =  2 AND NOT EXISTS(	SELECT TOP 1 1
															FROM tbSaleOrderStatus tsos			WITH (NOLOCK)
					                              			WHERE	tsos.comp_id	= soh.comp_id
					                              				AND tsos.bra_id		= soh.bra_id
					                              				AND tsos.soh_id		= soh.soh_id
					                              				AND tsos.sos_ok		= 'False')	THEN 1 --  Pendientes de Autorizacion.
						ELSE																		 0
					END	 = 1
				)
		AND		( @pro_id	 = -1 OR soh.pro_id = @pro_id )
		AND		( @ss_id	 = -1 OR ISNULL(tcb.ss_id,CU.ss_id) = @ss_id ) 				-- AREA DE VENTAS DEL CLLIENTE  (LENTO, si jode sacarlo y q se cague el de Misma Sangre)
		AND		( @ss_id_bra = -1 OR ISNULL(tcb.ss_id,-1)		= @ss_id_bra ) AND 		-- AREA DE VENTAS DE LA SUCURSAL ticket 9982

		exd.comp_id IS NULL	AND	-- El documento NO este excluido
		CASE
			WHEN @bitAuthorizationPending = 'False' 								THEN 'True'
			WHEN @bitAuthorizationPending = 'True'  AND tmpa.comp_id IS NOT NULL	THEN 'True'
			ELSE																		 'False'
		END	= 'True'
		AND		(@bitExcludeIsEditingSO = 'False' OR (@bitExcludeIsEditingSO = 'True' AND soh.soh_isEditing <> 'True'))
		AND  (@dc_id = -1		OR @dc_id = soh.dc_id)
		AND  (@mls_id = -1		OR tmloh.mls_id = @mls_id )
		AND
			CASE	-- MOS 10-2020
				WHEN @item_id_exclude	= -1												THEN	1
				WHEN NOT EXISTS (SELECT TOP 1  1
									FROM	tbSaleOrderDetail sod			WITH (NOLOCK)
									WHERE	sod.comp_id		= @comp_id
									AND     sod.bra_id      = soh.bra_id
									AND		sod.soh_id		= soh.soh_id
									AND		sod.item_id		= @item_id_exclude	)			THEN	1
				ELSE																			0
			END = 1
		-- MOS 07-2021
		AND	CASE
				WHEN @bitDeliveryDateActivated = 'False'																THEN 1
				WHEN EXISTS(	SELECT TOP 1 1
				            		FROM tbSaleOrderDetail AS tsoda WITH (NOLOCK)
				            		WHERE
										tsoda.comp_id	= soh.comp_id	AND
		         						tsoda.bra_id	= soh.bra_id	AND
		         						tsoda.soh_id    = soh.soh_id	AND
		         						tsoda.sod_itemDeliveryDate BETWEEN @datFromDateItem	AND @datToDateItem
							)																							THEN 1
				ELSE																										 0
			END = 1
		AND	CASE
				WHEN	@delivery_type = -1																				THEN 1
				WHEN EXISTS(	SELECT TOP 1 1
				            		FROM tbSaleOrderDetail AS tsoda WITH (NOLOCK)
				            		WHERE
										tsoda.comp_id	= soh.comp_id	AND
		         						tsoda.bra_id	= soh.bra_id	AND
		         						tsoda.soh_id    = soh.soh_id	AND
		         						tsoda.sdlmt_id  = @delivery_type
							)																							THEN 1
				ELSE																										 0
			END = 1
		AND
				(
					CASE
						WHEN @col_id = -1 THEN 1
						WHEN EXISTS	(
										SELECT TOP 1 1
											FROM tbSaleOrderCollectDetail AS tsocd WITH (NOLOCK)
											WHERE	tsocd.comp_id		= soh.comp_id	AND
													tsocd.soh_bra_id	= soh.bra_id	AND
													tsocd.soh_id		= soh.soh_id
									)     THEN 1
						ELSE				   0
					END = 1
				)

	order by comp_id,bra_id,soh_id
	-- ---------------------------------------------------------------------------------


-- select CHARINDEX('[cust_name] asc', @order_by)


--==
--SELECT 50,GETDATE()


	-- ---------------------------------------------------------------------------------
	-- Filtro por Percepciones
	-- ---------------------------------------------------------------------------------
	IF @perceptionOptions = 0  -- Solo SIN Percepciones
		BEGIN
			WITH tmpSalesOrdersWithPerceptions (comp_id, bra_id, soh_id)
			AS
			-- Define the CTE query.
			(
				SELECT DISTINCT tmp.comp_id,
								tmp.bra_id,
								tmp.soh_id
					FROM @tmpSOFilter tmp
				INNER JOIN tbSaleOrderTaxes tsot	WITH (NOLOCK)
					ON	tsot.comp_id	= tmp.comp_id	AND
						tsot.bra_id		= tmp.bra_id	AND
						tsot.soh_id		= tmp.soh_id
				INNER JOIN tbTaxName		ttn		WITH (NOLOCK)
					ON	ttn.comp_id		= tsot.comp_id AND
						ttn.tax_id		= tsot.tax_id
				INNER JOIN vwsysTaxClassALL_Perceptions vtcap	WITH (NOLOCK)
					ON vtcap.tax_class	= ttn.tax_class

			)
			DELETE   @tmpSOFilter
				FROM @tmpSOFilter			tmp
				INNER JOIN tmpSalesOrdersWithPerceptions tmp2
					ON	tmp.comp_id = tmp2.comp_id AND
						tmp.bra_id  = tmp2.bra_id  AND
						tmp.soh_id  = tmp2.soh_id
				--WHERE tmp2.comp_id IS NOT NULL

		END

	IF @perceptionOptions = 1  -- Solo CON Percepciones
		BEGIN
			WITH tmpSalesOrdersWithPerceptions (comp_id, bra_id, soh_id)
			AS
			-- Define the CTE query.
			(
				SELECT DISTINCT tmp.comp_id,
								tmp.bra_id,
								tmp.soh_id
					FROM @tmpSOFilter tmp
				INNER JOIN tbSaleOrderTaxes tsot	WITH (NOLOCK)
					ON	tsot.comp_id	= tmp.comp_id	AND
						tsot.bra_id		= tmp.bra_id	AND
						tsot.soh_id		= tmp.soh_id
				INNER JOIN tbTaxName		ttn		WITH (NOLOCK)
					ON	ttn.comp_id		= tsot.comp_id AND
						ttn.tax_id		= tsot.tax_id
				INNER JOIN vwsysTaxClassALL_Perceptions vtcap	WITH (NOLOCK)
					ON vtcap.tax_class	= ttn.tax_class

			)
			DELETE   @tmpSOFilter
				FROM @tmpSOFilter			tmp
				LEFT JOIN tmpSalesOrdersWithPerceptions tmp2
					ON	tmp.comp_id = tmp2.comp_id AND
						tmp.bra_id  = tmp2.bra_id  AND
						tmp.soh_id  = tmp2.soh_id
				WHERE tmp2.comp_id IS NULL
		END
	-- ---------------------------------------------------------------------------------


	-- -----------------------------------------------------------------
	--Borra todos llos que no sean de determinada Tienda
	-- -----------------------------------------------------------------
	IF @soh_note4ExternalUse <> ''
		BEGIN
			DELETE  @tmpSOFilter
				FROM @tmpSOFilter tmp
				INNER JOIN tbSaleOrderHeader tsoh					WITH (NOLOCK)
					ON	tmp.comp_id = tsoh.comp_id	AND
						tmp.bra_id	= tsoh.bra_id	AND
						tmp.soh_id	= tsoh.soh_id
				INNER JOIN tbSaleOrderDetail		AS tsod			WITH (NOLOCK)
					ON	tsod.comp_id	= tsoh.comp_id	AND
						tsod.bra_id		= tsoh.bra_id	AND
						tsod.soh_id		= tsoh.soh_id
				LEFT JOIN tbMercadoLibre_ordersHeader AS tmloh		WITH (NOLOCK)
					ON	tmloh.comp_id	= tsod.comp_id AND
						tmloh.mlo_id	= tsod.mlo_id
				LEFT JOIN tbMercadoLibre_ordersShipping AS tmlos	WITH (NOLOCK)
					ON	tmlos.comp_id	= tsod.comp_id AND
						tmlos.mlo_id	= tsod.mlo_id
				WHERE	tsoh.soh_note4ExternalUse NOT LIKE '%' +  @soh_note4ExternalUse + '%'							AND
						CONVERT(NVARCHAR(30),ISNULL(tmloh.ML_id,0))			<> @soh_note4ExternalUse					AND
						CONVERT(NVARCHAR(30),ISNULL(tmlos.MLshippingID,0))	<> @soh_note4ExternalUse					AND
						CONVERT(NVARCHAR(30),ISNULL(tsoh.MLShippingID,0))	<> @soh_note4ExternalUse					AND
						ISNULL(tsoh.soh_MLGUIA,0)		<> @soh_note4ExternalUse
		END
	-- -----------------------------------------------------------------


--==
--SELECT 60,GETDATE()

	-- ---------------------------------------------------------------------------------
	-- CTE, Aqui se crea un CTE para poder seleccionar la Pagina que se va a mostrar
	-- unicamente
	-- ---------------------------------------------------------------------------------
	DECLARE		@resultado_total TABLE(comp_id INT,bra_id INT,soh_id INT,RowNumber INT, unique clustered (comp_id,bra_id,soh_id))		--  MOS 05-2023 x Speed, no se usaba el rownumber para el join
	--DECLARE		@resultado_total TABLE(comp_id INT,bra_id INT,soh_id INT,RowNumber INT, unique clustered (comp_id,bra_id,soh_id,rownumber))
	INSERT INTO @resultado_total(comp_id, bra_id, soh_id, RowNumber)
	--WITH resultado_total AS
		--(
			select	soh.comp_id,
				soh.bra_id,
				soh.soh_id,
				-- ATENCION.!  Hacer esto mismo en el order.!!!!  **5
				CASE
					WHEN CHARINDEX('[soh_deliveryDate] asc',  @order_by)	> 0	THEN ROW_NUMBER() 		OVER ( ORDER BY soh.soh_deliveryDate )
					WHEN CHARINDEX('[soh_deliveryDate] desc', @order_by)	> 0	THEN ROW_NUMBER() 		OVER ( ORDER BY soh.soh_deliveryDate DESC )
					WHEN CHARINDEX('[cust_name] asc',  @order_by)	> 0			THEN ROW_NUMBER() 		OVER ( ORDER BY tc.cust_name )
					WHEN CHARINDEX('[cust_name] desc', @order_by)	> 0			THEN ROW_NUMBER() 		OVER ( ORDER BY tc.cust_name DESC )
					WHEN CHARINDEX('[soh_total] asc',  @order_by)	> 0			THEN ROW_NUMBER() 		OVER ( ORDER BY soh.soh_total )
					WHEN CHARINDEX('[soh_total] desc', @order_by)	> 0			THEN ROW_NUMBER() 		OVER ( ORDER BY soh.soh_total DESC )
					else															 ROW_NUMBER() 		OVER ( ORDER BY soh.comp_id, soh.bra_id, soh.soh_id )
				end			[RowNumber]

		FROM dbo.tbSaleOrderHeader				soh				WITH (NOLOCK)

			INNER JOIN @tmpSOFilter				tmpSO
				on		soh.comp_id = tmpSO.comp_id
					and soh.bra_id  = tmpSO.bra_id
					and soh.soh_id  = tmpSO.soh_id
			INNER JOIN tbCustomer tc							WITH (NOLOCK)
				ON		tc.comp_id = soh.comp_id
					AND tc.cust_id = soh.cust_id

		--)



	DECLARE @intFromRowNumber	AS integer =	(@page_size  *  @page_number  + 1)
	DECLARE @intToRowNumber		AS integer =	(@page_size  * (@page_number  + 1))
	DECLARE @indexOrder AS INT =
									CASE
										WHEN CHARINDEX('[soh_deliveryDate] asc',  @order_by)	> 0	THEN 1
										WHEN CHARINDEX('[soh_deliveryDate] desc', @order_by)	> 0	THEN 2
										WHEN CHARINDEX('[cust_name]', @order_by)				> 0	THEN 3
										WHEN CHARINDEX('[soh_total]', @order_by)				> 0	THEN 4
										else															 5
									END





	-- ----------------------------------------------------------------------------------------
	--	Select PRINICPAL
	-- ----------------------------------------------------------------------------------------
	SELECT
			-- --------------------------------------------------------------------------------
			-- Botones de acciones de la grilla **4
			-- --------------------------------------------------------------------------------
			' ' [U],								-- Modifica
			isnull(tmp2.soh_id,0) [D],				-- borra
			' ' [?],								--
			isnull(tmp.count,-1)  [P],				-- Procesar  **999   OJO, verificar en wfmSaleOrderAll si se agrega un boton !!!!!!!
			' ' [E],								-- eMail
			' ' [I],								-- Imprimir
			' ' [T],								-- Transferir de Depósito,
			' ' [C],								-- Llamadas a CRM
			-- --------------------------------------------------------------------------------
			CASE
				WHEN tcf.comp_id IS NOT NULL	THEN tcf.custf_name +  '->' + cu.cust_name
				WHEN tcb.custb_name IS NULL		THEN cu.cust_name
				ELSE	cu.cust_name + ' / ' + tcb.custb_name
			END		+
			CASE
				WHEN tmlud.MLUser_Id IS NULL THEN ''
				ELSE	' (' + tmlud.nickname + ')'
			END																	[cust_name] ,
			CASE
				WHEN tmpa.comp_id IS NOT NULL   THEN	'A'
				ELSE									'#'
			END +
					dbo.fnGetSaleOrderNumber(soh.comp_id,soh.bra_id,soh.soh_id) +
					'¦' +
					convert(nvarchar(4),IsNull(sov.optval_desc,'')) +
					'¦' +
					IsNull(vsos.ssos_desc,'') 	+
					ISNULL(tss.ws_paymentGateWayShortStatusDescription,'')		[ssos_desc],
			soh.soh_deliveryDate,

			CASE
				WHEN df.sd_id = 1 OR df.sd_id = 2 OR df.sd_id = 5 OR df.sd_id = 15
										THEN
										LTRIM(RTRIM(isnull(tc.curr_symbol,''))) + ' ' +
										CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),soh.soh_total))
				ELSE ''
			END																												[soh_total],
			 LTRIM(RTRIM(isnull(tc2.curr_symbol,''))) + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),soh.soh_Atotal))		[soh_total_curr_id4Exchange],
			CASE
				WHEN dbo.fnGetMyExchange(soh.soh_ExchangeToCustomerCurrency) = 1 THEN ''
				ELSE CONVERT(VARCHAR,CONVERT(DECIMAL(19,4),dbo.fnGetMyExchange(soh.soh_ExchangeToCustomerCurrency)))
			END																												[soh_ExchangeToCustomerCurrency],
			IsNull(soh.soh_internalAnnotation,'')																			[soh_internalAnnotation],
			st.st_desc +
							CASE
								WHEN tcclp.comp_id IS NOT NULL THEN ' / ' + ISNULL(tcclp.ccp_desc,'')
								ELSE ''
							END																								[st_desc],
			di.disc_desc,
			df.df_desc,
			dl.dl_name,
			us.user_lastname + ', ' + user_firstname																		[Name],
			soh.comp_id,
			soh.bra_id,
			soh.soh_cd,
			soh.soh_quotation,
			sm.sm_name,
			soh.sm_id,
			soh.cust_id,
			--st.st_desc,
			bra.bra_desc,
			soh.st_id,
			soh.disc_id,
			--di.disc_desc,
			soh.dl_id,
			soh.cb_id,
			soh.soh_lastUpdate,
			soh.soh_limitDate,
			soh.tt_id,
			soh.tt_class,
			soh.soh_StatusOf,
			soh.user_id,
			soh.soh_isEditingCd,
			soh.df_id,
			soh.soh_observation1,
			soh.soh_observation2,
			soh.soh_observation3,
			soh.soh_observation4,

			ISNULL(DATEDIFF(DAY, bra.bra_processingDate, soh.soh_limitDate), 0)												[depura],
			soh.soh_MLId,
			soh.soh_MLGUIA,


			-- ------------------------------------------------------------------------------------------
			-- ATENCION!!!!! **2
			-- Por Favor, no poner nada a partir de este campo.!!  Se toman por orden en SaleOrderAll!!
			-- Ocultar en wfmSaleOrderAll: subSetgrdDataHideColumns
			-- ------------------------------------------------------------------------------------------
			-----------
			-- MOS 02-2022: MIERD de TP3D, si pone lento todo, SE VA A LA PUTA QUE LO PARIO y se BORRA
			CASE
				WHEN soh.soh_iseMailEnvied = 'True' THEN '1'
				ELSE '0'
			END																												[soh_iseMailEnvied],-- Count - 21
			CASE
				WHEN df.sd_id <> 2												THEN 0
				WHEN df.df_SaleOrder_IsInvoiceFirstPacking		= 'False'		THEN 0
				WHEN
							EXISTS(	SELECT TOP 1 1
										FROM tbSaleOrderHeader					ttis	WITH (NOLOCK)
										INNER JOIN tbDocumentsFile				tdfRM		WITH (NOLOCK)	-- Busco MI documento a Amitir, solo si es Remoto de Fc Adelantada
											ON	tdfRM.comp_id			= ttis.comp_id		AND
												tdfRM.df_id				= ttis.df_id
										INNER JOIN tbItemTransactions			titFA		WITH (NOLOCK,INDEX = IX_tbItemTransactions_it_soh_id)	-- Mov de Stock de la Fc Adelantada
											ON	titFA.comp_id			= ttis.comp_id		AND
												titFA.bra_id			= ttis.bra_id		AND
												titFA.it_soh_id			= ttis.soh_id		--AND
												--titFA.it_sod_id			= ttis.sod_id
										INNER JOIN tbCommercialTransactions		tct		WITH (NOLOCK)	-- Fc Adelantada
											ON	tct.comp_id			= titFA.comp_id AND
												tct.ct_transaction	= titFA.ct_transaction
										INNER JOIN tbDocumentsFile				tdf2	WITH (NOLOCK)	-- Documento de la Fc Adelantada
											ON	tdf2.comp_id		= tct.comp_id AND
												tdf2.df_id			= tct.df_id
										INNER JOIN tbItemTransactions			titNC	WITH (NOLOCK)
											ON	titNC.comp_id					= titFA.comp_id AND
												titNC.it_transaction_original	= titFA.it_transaction
										INNER JOIN tbCommercialTransactions		tctNC	WITH (NOLOCK)
											ON	tctNC.comp_id					= titNC.comp_id AND
												tctNC.ct_transaction			= titNC.ct_transaction
										WHERE	ttis.comp_id								= soh.comp_id 	AND
												ttis.bra_id									= soh.bra_id	AND
												ttis.soh_id									= soh.soh_id	AND
												tdfRM.sd_id									= 2				AND	-- Si el ACTUAl es un REMITO
												tdfRM.df_SaleOrder_IsInvoiceFirstPacking		= 'True'		AND -- de Factura ANTICIPADA
												tdf2.sd_id									= 1				AND -- el documento original es FACTURA
												tdf2.df_SaleOrder_InvoiceFirstPacking_df_id = tdfRM.df_id		AND	-- esa FActura es del remito ACTUAL de factura anticipada.
												tctNC.sd_id									= 3
									)
																				THEN 1

																				ELSE 0
			END																					[df_SaleOrder_InvoiceFirstPacking_PLHasCN],	-- Count - 20

			-----------
			ISNULL(soh.soh_note4ExternalUse,'')													[soh_note4ExternalUse]	,	-- Count - 19
			ISNULL(tmlos.MLstatus ,'*')															[MLstatus],					-- Count - 18
			CASE
				-- Tienda Nube
				WHEN ttno.comp_id IS NOT NULL				THEN 5000	-- Tienda Nube, era mas facil colgar aca los estados y no poner forradas nuevas..

				-- MercadoLibre
				WHEN tmloh.comp_id IS NULL 					THEN 0	-- MOS 05-2023 x Speed
				WHEN tmloh.mlo_status		= 'cancelled'	THEN 2222
				WHEN tmlos.MLturbo			= 'True'		THEN 3333
				WHEN tmlos.MLfulfilled		= 'True'		THEN 10
				WHEN tmlos.MLSelf_Service	= 'True'		THEN 20
				--
				ELSE											 0
			END																					[MLlogistic_type],			-- Count - 17					wfmSaleOrderAll: bolFulFillment, bolCross_Docking
			ISNULL(tmloh.MLShippingID,0)														[MLShippingID],				-- Count - 16
			ISNULL(tmlb.mlbra_desc,'')															[mlbra_desc],				-- Count - 15
			ISNULL(soh.mlo_id,-1)																[mlo_id],					-- Count - 14
			CASE
				WHEN tmpDS.comp_id IS NOT NULL THEN '1'
				ELSE								'0'
			END			[soh_hasDLMTGreaterThan1],		--	tiene algun articulo con Metodo de Entrega Mayor a 1 Retira YA	-- Count - 13
			CASE
				WHEN EXISTS(
							SELECT TOP 1  1
									FROM tbSaleOrderStatus tsos2		WITH (NOLOCK)
									WHERE	tsos2.comp_id		= soh.comp_id
										AND tsos2.bra_id		= soh.bra_id
										AND tsos2.soh_id		= soh.soh_id
										--AND tsos2.sos_ok		= 'False'

							) THEN '1'
				ELSE '0'
			END			[soh_hasSOS],					--	tiene algun estado	-- Count - 12
			CASE
				WHEN
					EXISTS(
							SELECT TOP 1  1
								FROM @tblSaleOrderStatus tsos2
								WHERE	tsos2.comp_id	= soh.comp_id	AND
										tsos2.bra_id	= soh.bra_id	AND
										tsos2.soh_id	= soh.soh_id
							)
																			THEN '1'
				WHEN df.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL	THEN '-5'
				WHEN df.df_SaleOrder_IsInvoiceFirstPacking = 'True'			THEN '-6'
				ELSE															 '0'
			END			[soh_hasSOS4EmmitionPending],	--  tiene estado pendiente que bloquee emision?	-- Count - 11
			df.sd_id,																		-- Count - 10
			--Parte 659 STL acá se devolverá 1 = Espera o 2 = No espera para colorear la grilla de SALEORDERALL
			CASE
				WHEN tcw.cust_id is NULL THEN	2
				ELSE							1
			END	+
			CASE	-- MOS 02-2023 ticket 18312
				WHEN soh.soh_internalAnnotation <> '' THEN 1000
				ELSE 0
			END

														[CustomerWaiting],					-- Count - 9
			Case IsNull(cu.cust_inactive,'False')
				WHEN 'True' THEN '1'
				ELSE			 '0'
			END											[cust_inactive],					-- Count - 8
			case
				when	isnull(tmp2.soh_id,0) = 0 THEN 0
				ELSE	1
			END											[IsSerialized],						-- Count - 7
			isnull(tmp.count,-1)						[StatusOK],							-- Count - 6
			CASE
				WHEN tmpU.bra_id IS NOT NULL THEN	-2
				ELSE								@SaleOrderBraId4Update
			END											[SaleOrderBraId4Update],			-- Count - 5
			cu.bra_id4Emmition,																-- Count - 4
			CASE
				WHEN soh.ws_internalID IS NOT NULL AND soh.ssos_id <> 4 AND soh.ssos_id <> 5 THEN IsNull(soh.ssos_id,10) * -1
				ELSE																			  IsNull(soh.ssos_id,10)
			END																	[ssos_id],												-- Count - 3
			soh.soh_isEditing,																-- Count - 2
			Convert(Varchar,soh.bra_id) + '-' + Convert(Varchar,soh.soh_id)		[ID]		-- Count - 1

	FROM dbo.tbSaleOrderHeader				soh				WITH (NOLOCK)

		INNER JOIN @resultado_total			CTE				--WITH (NOLOCK)
			on		cte.comp_id = soh.comp_id
				and cte.bra_id	= soh.bra_id
				and cte.soh_id	= soh.soh_id

		left join dbo.tbSalesman			sm				WITH (NOLOCK)
		on	sm.comp_id		= soh.comp_id	AND
			sm.sm_id		= soh.sm_id

		inner join dbo.tbCustomer			cu				WITH (NOLOCK)
		on	cu.comp_id		= soh.comp_id AND
			cu.cust_id		= soh.cust_id

		LEFT JOIN tbCustomerBranch			tcb				WITH (NOLOCK)
		ON	tcb.comp_id		= soh.comp_id
		AND tcb.cust_id		= soh.cust_id
		AND tcb.cb_id		= soh.cb_id

		inner join dbo.tbBranch				bra				WITH (NOLOCK)
		on	bra.comp_id		= soh.comp_id
		And bra.bra_id		= soh.bra_id

		left join dbo.tbSalesTerms			st				WITH (NOLOCK)
		on  st.comp_id		= soh.comp_id
		and st.st_id		= soh.st_id

		left join dbo.tbDiscount			di				WITH (NOLOCK)
		on	di.comp_id		= soh.comp_id AND
			di.disc_id		= soh.disc_id

		INNER join dbo.tbDocumentsFile		df				WITH (NOLOCK)
		on	df.comp_id		= soh.comp_id	AND
			df.bra_id		= soh.bra_id	AND		--	MOS 07-2024:
			df.df_id		= soh.df_id

		Left Join dbo.tbsysOptionsValues	SOV				WITH (NOLOCK)
		On	SOV.lang_id		= @lang_id
		and SOV.optval_class= 6
		and SOV.optval_id	= df.sd_id

		left join dbo.tbUser				us				WITH (NOLOCK)
		on	us.[user_id]	= soh.[user_id]

		left join dbo.tbDelivery			dl				WITH (NOLOCK)
		on	dl.comp_id		= soh.comp_id AND
			dl.dl_id		= soh.dl_id

		LEFT JOIN vwSaleOrderStatus			vsos			WITH (NOLOCK)
		ON	vsos.comp_id	= soh.comp_id
		AND vsos.bra_id		= soh.bra_id
		AND vsos.soh_id		= soh.soh_id
		AND vsos.lang_id	= @lang_id

		LEFT JOIN @tmpSOS					tmp
		ON		tmp.comp_id		= soh.comp_id
			AND tmp.bra_id		= soh.bra_id
			and tmp.soh_id		= soh.soh_id

		left JOIN @tmpSerials				tmp2
		ON		tmp2.comp_id	= soh.comp_id
			AND tmp2.bra_id		= soh.bra_id
			and tmp2.soh_id		= soh.soh_id

		left JOIN @tmpDeliveryStatus		tmpDS
		ON		tmpDS.comp_id	= soh.comp_id
			AND tmpDS.bra_id	= soh.bra_id
			and tmpDS.soh_id	= soh.soh_id

		LEFT JOIN @tmpBranch4Update tmpU
			ON tmpU.bra_id = soh.bra_id

		LEFT JOIN tbsysCurrency			tc				WITH (NOLOCK)			--	MOS 07-2024: zx left
		ON	tc.curr_id		= bra.curr_id

		LEFT  JOIN tbsysCurrency			tc2				WITH (NOLOCK)		--	MOS 07-2024: zx left
		ON	tc2.curr_id		= @intBranchCurrId4Exchange

--		LEFT JOIN tbCustomerWaiting			cw
--		ON	cw.comp_id		= soh.comp_id
--		AND cw.bra_id		= soh.bra_id
--		AND cw.cust_id		= soh.cust_id

		LEFT JOIN tbCustomerWaiting			tcw					WITH (NOLOCK)
		ON	tcw.comp_id		= soh.comp_id
		AND tcw.bra_id		= soh.bra_id
		AND tcw.cust_id		= soh.cust_id

		LEFT JOIN @tmpAuthorizationPending tmpa
			ON	tmpa.comp_id	= soh.comp_id	AND
				tmpa.bra_id		= soh.bra_id	AND
				tmpa.soh_id		= soh.soh_id

		LEFT JOIN tbSYSWebSiteII_paymentGatewayStatus tss			WITH (NOLOCK)
			ON tss.ws_paymentGateWayStatusID = soh.ws_paymentGateWayStatusID

		LEFT JOIN tbMercadoLibre_ordersHeader	tmloh				WITH (NOLOCK)
			ON	tmloh.comp_id	= soh.comp_id	AND
				tmloh.mlo_id	= soh.mlo_id

		LEFT JOIN tbMercadoLibre_Branchs		tmlb				WITH (NOLOCK)
			ON	tmlb.comp_id	= tmloh.comp_id AND
				tmlb.mlbra_id	= tmloh.mlbra_id

		LEFT JOIN tbMercadoLibre_ordersShipping tmlos				WITH (NOLOCK)
			ON	tmlos.comp_id	= soh.comp_id	AND --tmloh.comp_id	AND
				tmlos.mlo_id	= soh.mlo_id		--tmloh.mlo_id

		LEFT JOIN tbMercadoLibre_UsersData AS tmlud					WITH (NOLOCK)
			ON tmlud.MLUser_Id = tmloh.MLUser_Id

		LEFT JOIN tbCreditCardLoanPlan AS				tcclp		WITH (NOLOCK)
			ON	tcclp.comp_id	= soh.comp_id AND
				tcclp.ccp_id	= soh.ccp_id

		LEFT JOIN tbTiendaNube_Orders		 AS ttno				WITH (NOLOCK)
			ON	ttno.comp_id	= soh.comp_id	AND
				ttno.bra_id		= soh.bra_id	AND
				ttno.soh_id		= soh.soh_id

		LEFT JOIN tbCustomerFamily			AS tcf					WITH (NOLOCK)
			ON	tcf.comp_id		= soh.comp_id	AND
				tcf.cust_id		= soh.cust_id	AND
				tcf.custf_id	= soh.custf_id


	WHERE cte.RowNumber	BETWEEN @intFromRowNumber AND @intToRowNumber
	-- MOS 05-2023 x Speed
	--WHERE cte.RowNumber	BETWEEN (	@page_size  *  @page_number  + 1)
	--									AND (@page_size  * (@page_number  + 1)
	--								)
	ORDER BY
					CASE	-- Pone al final las que en un procesamiento automatico se cancelan x algun motivo.
						WHEN @bitExcludeIsEditingSO = 'False'											THEN 0
						WHEN @bitExcludeIsEditingSO = 'True' AND soh.soh_autoprocessLastOrder = 'True'	THEN 1
						ELSE																				 0
					END,
				-- ATENCION.!  Hacer esto mismo en el CTE.!!!!  **5
					CASE	-- MOS 05-2023: puse el orden en una variable arriba y aca lo ordeno segun la variable por claridad y velocidad
						WHEN @indexOrder = 1	THEN convert(varchar(50),soh.soh_deliveryDate,112 )
						WHEN @indexOrder = 2	THEN convert(varchar(50),soh.soh_deliveryDate,112 )
						WHEN @indexOrder = 3	THEN convert(varchar(50),cu.cust_name )
						WHEN @indexOrder = 4	THEN convert(varchar(50),soh.soh_total)
						ELSE 						 convert(varchar(50),soh.soh_id )
					end


	-- ----------------------------------------------------------------------------------------


--==
--SELECT 70,GETDATE()


	-- ----------------------------------------------------------------------------------------
	-- Retorna la Cantidad de Registros que tyiene la consulta
	-- ----------------------------------------------------------------------------------------
	select count(1)  FROM @tmpSOFilter
	-- ----------------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------------------------
	-- MOS 12-2022 x los PUTOS graficos
	-- ----------------------------------------------------------------------------------------
	SELECT	COUNT(*)					[intQTY],
			soh.ssos_id					[ssos_id],
			CASE
				WHEN soh.mlo_id > 0 THEN 1
				ELSE 0
			END							[intMLO_Id],
			CASE
				WHEN tmlos.comp_id IS NOT NULL THEN 1
				ELSE 0
			END							[intMLShippingID],
			ISNULL(tmlos.MLfulfilled,'False')		[MLfulfilled],
			ISNULL(tmlos.MLSelf_Service,'False')	[MLSelf_Service],
			ISNULL(tmlos.MLstatus,'')				[MLstatus]
		FROM dbo.tbSaleOrderHeader				AS soh		WITH (NOLOCK)
		INNER JOIN @resultado_total				AS CTE
			on		cte.comp_id = soh.comp_id	AND
					cte.bra_id	= soh.bra_id	AND
					cte.soh_id	= soh.soh_id
		LEFT JOIN tbMercadoLibre_ordersShipping AS tmlos	WITH (NOLOCK)
			ON	tmlos.comp_id		= soh.comp_id AND
				tmlos.mlo_id		= soh.mlo_id
		GROUP BY	ssos_id,
					CASE
						WHEN soh.mlo_id > 0 THEN 1
						ELSE 0
					END,
					CASE
						WHEN tmlos.comp_id IS NOT NULL THEN 1
						ELSE 0
					END,
					tmlos.MLfulfilled,
					tmlos.MLSelf_Service,
					tmlos.MLstatus
		ORDER BY
					CASE
						WHEN ssos_id = 10 THEN 0
						WHEN ssos_id = 20 THEN 5
						WHEN ssos_id = 50 THEN 10
						ELSE 100
					END
	-- ----------------------------------------------------------------------------------------





END
GO


CREATE PROCEDURE [dbo].[spSaleOrderHeader_GetDataById]
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			tsoh.comp_id,
			tsoh.bra_id,
			tsoh.soh_id,
			tsoh.soh_cd,
			tsoh.soh_deliveryDate,
			tsoh.soh_observation1,
			tsoh.soh_observation2,
			tsoh.soh_observation3,
			tsoh.soh_observation4,
			tsoh.soh_quotation,
			tsoh.sm_id,
			tsoh.cust_id,
			tsoh.st_id,
			tsoh.disc_id,
			tsoh.dl_id,
			tsoh.cb_id,
			tsoh.soh_lastUpdate,
			tsoh.soh_limitDate,
			tsoh.tt_id,
			tsoh.tt_class,
			tsoh.soh_StatusOf,
			tsoh.user_id,
			tsoh.soh_isEditing,
			tsoh.soh_isEditingCd,
			tsoh.df_id,
			tsoh.soh_total,
			tsoh.ssos_id,
			tsoh.soh_ExchangeToCustomerCurrency,
			tsoh.chp_id,
			tsoh.soh_PL_df_Id,
			tsoh.soh_CustomerCurrency,
			tsoh.soh_WithCollection,
			tsoh.soh_WithCollectionGUID,
			tsoh.soh_discount,
			tsoh.soh_loan,
			tsoh.soh_packagesQty,
			tsoh.soh_internalAnnotation,
			tsoh.curr_id4Exchange,
			tsoh.curr_idExchange,
			tsoh.soh_ATotal,
			tsoh.df_id4PL,
			tsoh.somp_id,
			tsoh.soh_FEIdNumber,
			tsoh.soh_inCash,
			tsoh.custf_id,
			tsoh.cust_id_guarantor,
			tsoh.ccp_id,
			tsoh.soh_MLdeliveryLabel,
			tsoh.soh_deliveryAddress,
			tsoh.soh_MLQuestionsAndAnswers,
			tsoh.aux_3RDSales_lastCTTransaction,
			tsoh.soh_MLId,
			tsoh.soh_MLGUIA,
			tsoh.pro_id,
			tsoh.aux_collectionInterest_lastCTTransaction,
			tsoh.ws_cust_Id,
			tsoh.ws_internalID,
			ISNULL(tsoh.ws_paymentGateWayStatusID,-1)						[ws_paymentGateWayStatusID],
			ISNULL(tss.ws_paymentGateWayStatusBlockEmission,'False')		[ws_paymentGateWayStatusBlockEmission],
			ISNULL(tss.ws_paymentGateWayStatusDescription,'')				[ws_paymentGateWayStatusDescription],
			tsoh.mlo_id,
			ISNULL(tmloh.mlo_status,'')										[mlo_status],
			ISNULL(tdf.df_printInCR_rptName4SO,'')							[df_printInCR_rptName4SO]

			FROM tbSaleOrderHeader							tsoh		WITH (NOLOCK)
			INNER JOIN tbDocumentsFile					 AS tdf			WITH (NOLOCK)
				ON	tdf.comp_id		= tsoh.comp_id	AND
					tdf.df_id		= tsoh.df_id
			LEFT JOIN tbSYSWebSiteII_paymentGatewayStatus	tss			WITH (NOLOCK)
				ON tss.ws_paymentGateWayStatusID = tsoh.ws_paymentGateWayStatusID
			LEFT JOIN tbMercadoLibre_ordersHeader		    tmloh		WITH (NOLOCK)
				ON	tmloh.comp_id	= tsoh.comp_id	AND
					tmloh.mlo_id	= tsoh.mlo_id
			WHERE	tsoh.comp_id	= @comp_id		AND
					tsoh.bra_id		= @bra_id		AND
					tsoh.soh_id		= @soh_id

	END
GO





-- RECUPERAMOS EL Nº DE PEDIDO SEGUN EN Nº DE GUIA DE ML



CREATE PROCEDURE [dbo].[spSaleOrderHeader_getDatabyMLGuia]
(

	@comp_id			INT,
	@bra_id				INT,
	@soh_MLGUIA			NVARCHAR(50)

)
AS



BEGIN

	set nocount on

	--------------------------------------------------------------
	-- TEST
	--------------------------------------------------------------
	/*
	declare
			@comp_id			INT,
			@bra_id				INT,
			@soh_MLGUIA			NVARCHAR(50)


	select
			@comp_id			=1,
			@bra_id				=1,
			@soh_MLGUIA			= 'dasads'
	*/
	--------------------------------------------------------------


		SET @soh_MLGUIA = dbo.fnStrAllTrim(@soh_MLGUIA)


		SELECT TOP 1
			tsoh.comp_id,
			tsoh.bra_id,
			tsoh.soh_id						[soh_id]
			FROM tbSaleOrderHeader			tsoh				WITH (NOLOCK)
			INNER JOIN tbSaleOrderDetail		AS tsod			WITH (NOLOCK)
				ON	tsod.comp_id	= tsoh.comp_id	AND
					tsod.bra_id		= tsoh.bra_id	AND
					tsod.soh_id		= tsoh.soh_id
			LEFT JOIN tbMercadoLibre_ordersHeader AS tmloh		WITH (NOLOCK)
				ON	tmloh.comp_id	= tsod.comp_id AND
					tmloh.mlo_id	= tsod.mlo_id
			LEFT JOIN tbMercadoLibre_ordersShipping AS tmlos	WITH (NOLOCK)
				ON	tmlos.comp_id	= tsod.comp_id AND
					tmlos.mlo_id	= tsod.mlo_id
			WHERE
					tsoh.comp_id					= @comp_id		AND
					tsoh.bra_id						= @bra_id       AND
					(
						tsoh.soh_note4ExternalUse  LIKE '%' +  @soh_MLGUIA + '%'		OR
						ISNULL(tmloh.ML_id,0)			= @soh_MLGUIA					OR
						ISNULL(tmlos.MLshippingID,0)	= @soh_MLGUIA					OR
						ISNULL(tsoh.MLShippingID,0)		= @soh_MLGUIA					OR
						ISNULL(tsoh.soh_MLGUIA,0)		= @soh_MLGUIA
					)


		--SELECT
		--	tsoh.soh_id						[soh_id]

		--	FROM tbSaleOrderHeader			tsoh		WITH (NOLOCK)

		--	WHERE tsoh.comp_id		= @comp_id		AND
		--		  tsoh.bra_id		= @bra_id       AND
		--		  tsoh.soh_MLGUIA	= @soh_MLGUIA



END
GO


