CREATE PROCEDURE [dbo].[spSaleOrderHeader_getDataForCollection]
(
	@comp_id			int,
	@bra_id				int,
	@cust_id			INT,
	@guid				UNIQUEIDENTIFIER
)
AS

BEGIN



	set nocount on
	-- =================================================================================================================
	-- Author		: MOS
	-- Update Date	: 2010-08-09
	-- Parte		: 454
	-- Description	: Se modifica la condición de filtro (where) de soh.soh_statusof = 20 por soh.ssos_id = 20
	-- =================================================================================================================



	-- ----------------------------------------------------
	-- ----------------------------------------------------
	/*
	DECLARE 	@comp_id		int,
				@bra_id			int,
				@cust_id		INT--,
				--@guid			UNIQUEIDENTIFIER
	SELECT		@comp_id		= 1,
				@bra_id			= 1,
				@cust_id		= 24288--,
				--@guid			= ''
	*/
	-- ----------------------------------------------------



	select	case when tctt.ctct_transaction IS NULL THEN 1 ELSE 0 END	[ ],
			case when tctt.ctct_transaction IS NULL THEN 0 ELSE 1 END	[ ],
			sm.sm_name,
			soh.soh_total												[total],
			soh.soh_cd,
			soh.soh_deliveryDate,
			soh.soh_id													[Nro.Pedido]

		from	dbo.tbSaleOrderHeader							soh				WITH (NOLOCK)

		INNER JOIN tbDocumentsFile							 AS tdf				WITH (NOLOCK)
			ON	tdf.comp_id					= soh.comp_id	AND
				tdf.df_id					= soh.df_id
		LEFT JOIN dbo.tbCommercialTransactionsTmp		tctt					WITH (NOLOCK)
			ON	tctt.comp_id							= soh.comp_id
			AND tctt.bra_id								= soh.bra_id
			AND tctt.ctct_transaction					= SOH.soh_id
			AND UPPER(tctt.ctct_origin)					= UPPER('s')
			AND tctt.ctct_guid							= @guid
		LEFT JOIN dbo.tbSalesman						sm						WITH (NOLOCK)
			on	sm.comp_id								= soh.comp_id AND
				sm.sm_id								= soh.sm_id
		Where	soh.comp_id								=	@comp_id
		AND		soh.bra_id								=	@bra_id
		AND		soh.cust_id								=	@cust_id
		AND		soh.ssos_id								IN	(20,50)				-- MOS 06-2024: Se cambio = 20 por IN (20,50)
		AND		ISNULL(soh.soh_WithCollection,'False')	=	'False'	AND
				tdf.sd_id NOT IN (2,3,5,23,33,43,80)	-- MOS 05-2022: solo pedidos de cosas que generen DEUDA.


	END
GO






CREATE PROCEDURE [dbo].[spSaleOrderHeader_GetDataProduction]
(
	@comp_id		INT,
	@bra_id			INT,
	@lang_id		INT,
	@datefrom		DATETIME,
	@dateto			DATETIME,
	@Cust_id		INT,
	@item_id		INT
)
AS


SET NOCOUNT ON

SET DATEFORMAT 'ymd'

	-- ---------------------------------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------------------------------
	/*
	DECLARE 	@comp_id		INT,
				@bra_id			INT,
				@datefrom		DATETIME,
				@dateto			DATETIME,
				@Cust_id		INT,
				@item_id		INT,
				@lang_id        INT


	SELECT
				@comp_id		= 1,
				@bra_id			= -1 ,
				@datefrom		='2000-01-01',
				@dateto			='9999-12-31',
				@Cust_id		=-1,
				@item_id		=-1,
				@lang_id		= 2
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsProduced')		IS NULL DROP TABLE #tmpItemsProduced
	*/
	-- ---------------------------------------------------------------------------------------------






	SELECT  isnull(tsosp.soh_id,tsod.soh_id)					[soh_id],
			tsod.item_id										[item_id],

			CASE WHEN tsod.sod_qty = SUM(CASE WHEN tsosp.soh_id IS NULL
											THEN 0
											ELSE 1
			                             END)
					THEN 1
					ELSE 0
			END													[isProduced]


--			,tsod.sod_qty, SUM(1) [u],
--			CASE WHEN tsosp.soh_id IS NULL THEN 0 ELSE 1 END	[ii]

	INTO	#tmpItemsProduced

	FROM	tbSaleOrderDetail					tsod					WITH (NOLOCK)

			INNER JOIN tbSaleOrderHeader		tsoh					WITH (NOLOCK)
			ON	tsoh.comp_id	= tsod.comp_id
			AND tsoh.bra_id		= tsod.bra_id
			AND tsoh.soh_id		= tsod.soh_id

			INNER JOIN tbDocumentsFile			tdf						WITH (NOLOCK)
			ON	tdf.df_id		= tsoh.df_id
			AND tdf.comp_id		= tsoh.comp_id

			LEFT JOIN tbSaleOrderSerialProduced tsosp					WITH (NOLOCK)
			ON	tsod.comp_id	= tsosp.comp_id
			AND tsod.soh_id		= tsosp.soh_id
			AND tsod.sod_id		= tsosp.sod_id

	WHERE	tdf.sd_id	= 80
	GROUP BY tsosp.soh_id, tsod.soh_id, tsod.item_id, tsod.sod_qty

	--SELECT * FROM #tmpItemsProduced




	SELECT	CASE
				WHEN tdf.df_SaleOrderProduction_ProduceByTotalQTY = 'True' THEN '1'
				ELSE '0'
			END				[C1],
			' '				[C2],
			' '				[C3],
			' '				[C4],
			tsoh.soh_deliveryDate,
			tb.bra_desc,
			tc.cust_name,
			vsos.ssos_desc + '¦' + dbo.fnGetSaleOrderNumber(tsoh.comp_id,tsoh.bra_id,tsoh.soh_id)	[ssos_desc],
			tdf.df_desc																				[Document],
			convert(varchar, tsoh.bra_id) + '-' + CONVERT(VARCHAR, tsoh.soh_id)						[ID]


	FROM	tbSaleOrderHeader					tsoh		WITH (NOLOCK)

			INNER JOIN tbDocumentsFile			tdf			WITH (NOLOCK)
			ON  tdf.comp_id		= tsoh.comp_id
			AND tdf.df_id		= tsoh.df_id

			INNER JOIN tbCustomer				tc			WITH (NOLOCK)
			ON	tc.comp_id		= tsoh.comp_id
			AND tc.cust_id		= tsoh.cust_id

			INNER JOIN tbBranch					tb			WITH (NOLOCK)
			ON	tb.comp_id		= tsoh.comp_id
			AND tb.bra_id		= tsoh.bra_id

			LEFT JOIN vwSaleOrderStatus			vsos		WITH (NOLOCK)
			ON	vsos.comp_id	= tsoh.comp_id
			AND vsos.bra_id		= tsoh.bra_id
			AND vsos.soh_id		= tsoh.soh_id
			AND vsos.lang_id	= @lang_id

			INNER JOIN #tmpItemsProduced		tip			WITH (NOLOCK)
			ON	tip.soh_id		= tsoh.soh_id


	WHERE	tsoh.comp_id			= @comp_id
	AND		(tsoh.bra_id			= @bra_id	OR @bra_id  = -1)
	AND 	tsoh.soh_deliveryDate	between  @datefrom and	@dateto
	AND		(tsoh.cust_id			= @cust_id	OR @cust_id	= -1)
	AND		tdf.sd_id				= 80
	AND		(@item_id				= -1 OR EXISTS (SELECT item_id
	   		         									FROM	tbSaleOrderDetail sod		WITH (NOLOCK)
	         											WHERE	sod.comp_id		= @comp_id
	         											AND		sod.soh_id		= tsoh.soh_id
	         											AND		sod.item_id		= @item_id	))
	AND		tip.isProduced			= 0
	AND		tsoh.ssos_id			= 50


	GROUP BY	tsoh.soh_deliveryDate,
				tb.bra_desc,
				tc.cust_name,
				vsos.ssos_desc,
				tdf.df_desc,
				tsoh.soh_id,
				tsoh.comp_id,
				tsoh.bra_id,tdf.df_SaleOrderProduction_ProduceByTotalQTY

	ORDER BY tsoh.soh_id
GO






CREATE procedure [dbo].[spSaleOrderHeader_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int
)
as


SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

/*
DECLARE @comp_id			int,
		@lang_id			int,
		@page_id			int

SELECT	@comp_id			=1,
		@lang_id			=2,
		@page_id			=10006

*/
SELECT	SOH.[soh_cd],
		DF.[df_desc],
		SM.[sm_name],
		SOH.[soh_lastUpdate],
		SOH.[soh_deliveryDate],
		SOH.[soh_observation1],
		SOH.[soh_observation2],
		SOH.[soh_observation3],
		SOH.[soh_observation4],
		SOH.[soh_quotation],
		CU.[cust_phone1],
		CU.[cust_address],
		CU.[cust_city],
		SC.[country_desc],
		I.[item_code],
		I.[item_desc],
		IT.[it_qty],
		IT.[it_price],
		ST.[st_desc],
		D.[disc_desc],
		DL.[dl_name],
		FC.[fc_desc],
	    (IT.[it_qty] * IT.[it_price])[subtotal]


FROM	dbo.tbSaleOrderHeader	SOH				WITH (NOLOCK)

inner join tbDocumentsFile		DF	WITH (NOLOCK)
on  DF.[comp_id]				= SOH.[comp_id]
and DF.[bra_id]					= SOH.[bra_id]
and DF.[df_id]					= SOH.[df_id]

left join tbSalesman			SM	WITH (NOLOCK)
on  SM.[comp_id]				= SOH.[comp_id]
and SM.[sm_id]					= SOH.[sm_id]

left join tbCustomer			CU	WITH (NOLOCK)
on  CU.[comp_id]				= SOH.[comp_id]
and CU.[cust_id]				= SOH.[cust_id]

LEFT JOIN tbsysCurrency			CC	WITH (NOLOCK)
ON	CC.[curr_id]				=	CU.[curr_id]

left join tbSaleOrderDetail		SOD	WITH (NOLOCK)
on SOD.[comp_id]				= SOH.[comp_id]
and SOD.[bra_id]				= SOH.[bra_id]
and SOD.[soh_id]				= SOH.[soh_id]

left join tbItem				I	WITH (NOLOCK)
on  I.[comp_id]					= SOD.[comp_id]
and I.[item_id]					= SOD.[item_id]

inner join tbItemTransactions  IT	WITH (NOLOCK)
on IT.[comp_id]					= I.[comp_id]
and IT.[item_id]				= I.[item_id]

left join tbDelivery			DL	WITH (NOLOCK)
on DL.[comp_id]					= SOH.[comp_id]
and DL.[dl_id]					= SOH.[dl_id]

left join tbDiscount			D	WITH (NOLOCK)
on	D.[comp_id]					= SOH.[comp_id]
and D.[disc_id]					= SOH.[disc_id]

INNER join tbsysFiscalClass		FC	WITH (NOLOCK)
on FC.[fc_id]					=	CU.[fc_id]

left join tbsysCountry			SC	WITH (NOLOCK)
on SC.[country_id]				= CU.[country_id]

left join tbSalesTerms			ST	WITH (NOLOCK)
on  ST.[comp_id]				= SOH.[comp_id]
and ST.[st_id]					= SOH.[st_id]


group by SOH.[soh_cd],
		DF.[df_desc],
		SM.[sm_name],
		SOH.[soh_lastUpdate],
		SOH.[soh_deliveryDate],
		SOH.[soh_observation1],
		SOH.[soh_observation2],
		SOH.[soh_observation3],
		SOH.[soh_observation4],
		SOH.[soh_quotation],
		CU.[cust_phone1],
		CU.[cust_address],
		CU.[cust_city],
		SC.[country_desc],
		I.[item_code],
		I.[item_desc],
		IT.[it_qty],
		IT.[it_price],
		ST.[st_desc],
		D.[disc_desc],
		DL.[dl_name],
		FC.[fc_desc]

order by SOH.[soh_cd]

exec [spReports_getData]@comp_id, @lang_id,	@page_id
GO


CREATE procedure [dbo].[spSaleOrderHeader_getReportOrders]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,
	@bra_id				int,
	@soh_id				int,
	@intBranch4Lang		int
)
AS

BEGIN

	SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

-- -------------------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------------------
/*
	DECLARE @comp_id			int,
			@lang_id			int,
			@page_id			int,
			@bra_id				int,
			@soh_id				INT,
			@intBranch4Lang		int

	SELECT	@comp_id			=1,
			@lang_id			=2,
			@page_id			=10032,
			@bra_id				=1,
			@soh_id				=34493,
			@intBranch4Lang		= 1
*/
-- -------------------------------------------------------------------------------

	-- ----------------------------------------------------
	-- TIPO DE CAMBIO Y MONEDA PARA PEDIDO DE DEPCO
	-- ----------------------------------------------------
		DECLARE
			@curr_id_USD_Cotizacion	DECIMAL(19,2),
			@curr_id_USD_Symbol		VARCHAR(10)

		SELECT
			@curr_id_USD_Symbol = tc.curr_symbol
			FROM tbsysCurrency	tc
			WHERE tc.curr_id	= 2

		SELECT
			@curr_id_USD_Cotizacion = dbo.fnGetExchange2(@comp_id,1,tb.curr_id4Exchange,tb.curr_id,0,0,0,'False')
			FROM tbBranch					tb	WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id	AND
					tb.bra_id	= @bra_id
	-- ----------------------------------------------------


	DECLARE @tmpSaleOrderTaxes TABLE(	sod_id INT PRIMARY KEY,
										taxes_item_curr	DECIMAL(19,4),
										taxes_item_cust	DECIMAL(19,4))


	DECLARE @tmpSaleOrderTaxesIVA TABLE(	sod_id INT PRIMARY KEY,
											taxes_item_curr	DECIMAL(19,4),
											taxes_item_cust	DECIMAL(19,4))


	-- ---------------------------------------------------
	-- Selecciona cual va a ser la moneda del total
	-- Solo LOS TOTALES deben estar en esta moneda!!!
	-- @curr_id4Total
	-- ---------------------------------------------------
	DECLARE @curr_id4Total			as INT
	DECLARE @intCustomerCurrency	AS INT
	DECLARE @df_id					AS INT
	DECLARE @soh_exchange2Currency4Total	AS DECIMAL(19,6)
	DECLARE @soh_Currency4Total				AS INT
	SELECT @df_id						= tsoh.df_id,
		   @intCustomerCurrency			= tc.curr_id,
		   @soh_exchange2Currency4Total = tsoh.soh_exchange2Currency4Total,
		   @soh_Currency4Total			= tsoh.soh_Currency4Total
		FROM tbSaleOrderHeader tsoh				WITH (NOLOCK)
		INNER JOIN tbCustomer tc				WITH (NOLOCK)
			ON		tc.comp_id	= @comp_id
				AND tc.cust_id	= tsoh.cust_id
		WHERE	tsoh.comp_id	= @comp_id
			AND tsoh.bra_id		= @bra_id
			AND tsoh.soh_id		= @soh_id


	DECLARE @df_SaleOrder_Print_RecalculateTaxes AS BIT = 'False'
	DECLARE @intPrintOrder AS INT
	SET		@intPrintOrder		= 0
	SELECT  @curr_id4Total		= IsNull(tdf.df_SaleOrderEnableCurrency4Total,@intCustomerCurrency),
			@intPrintOrder		= ISNULL(tdf.df_SaleOrder_printOrderMode,0),
			@df_SaleOrder_Print_RecalculateTaxes = ISNULL(df_SaleOrder_Print_RecalculateTaxes,'False')
		FROM tbDocumentsFile tdf				WITH (NOLOCK)
		WHERE	tdf.comp_id = @comp_id
			AND tdf.df_id	= @df_id




	-- -----------------------------------------------------------------------------------
	-- MOS: 12-2022 x Latamly ticket 17941
	-- Si los totales se imprimen en una moneda diferente a la de la sucursal
	-- recalcula todo ya que los impuestos estan guardados en la moneda
	-- de la sucursal, siempre y cuando NO se este editando ahora el pedido.
	-- -----------------------------------------------------------------------------------
	IF	@df_SaleOrder_Print_RecalculateTaxes = 'True' --@df_SaleOrderEnableCurrency4Total <> @intCurrIdTo	AND
		BEGIN
			BEGIN TRY
				DECLARE @user_id2	   AS INT
				DECLARE @soh_isEditing AS BIT = 'False'
				SELECT  @user_id2			= tsoh.[user_id],
						@soh_isEditing		= tsoh.soh_isEditing
					FROM tbSaleOrderHeader tsoh			WITH (NOLOCK)
					WHERE	tsoh.comp_id	= @comp_id  -- Ref #1
					AND		tsoh.bra_id		= @bra_id
					AND		tsoh.soh_id		= @soh_id	-- Ref #1
				IF @soh_isEditing = 'False'
					BEGIN
						EXEC spSaleOrder_RecalculateTaxes
							@comp_id ,
							@bra_id,
							@soh_id,
							@user_id2 ,
							-2
					END
			END TRY
			BEGIN CATCH
			END CATCH
		END
		-- -----------------------------------------------------------------------------------






--==
--SELECT @curr_id4Total
--==

	-- ---------------------------------------------------
	-- Ticket 197 STL
	-- Obtengo la moneda de la sucursal para forzar
	-- los totales
	-- ---------------------------------------------------

		DECLARE @bra_curr4exchange	INT
		DECLARE @bra_curr_id		INT



		SELECT  @bra_curr4exchange	= tb.bra_SaleOrderCurrId4TotalShow,
				@bra_curr_id		= tb.curr_id
			FROM tbBranch tb					WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id
			AND		tb.bra_id	= @bra_id

		--En caso de existir una moneda forzada, reemplazo el valor de la variable anterior

--		IF @bra_curr4exchange <> 0
--			SET @curr_id4Total = @bra_curr4exchange
--==
--select @curr_id4Total
--==
	-- ---------------------------------------------------

	-- ---------------------------------------------------
	-- DATASOFT
	-- ARMO LAS LEYENDAS DEL PEDIDO
	-- ---------------------------------------------------
		DECLARE
			@Leyenda_Precios	NVARCHAR(MAX),
			@Leyenda_Garantia	NVARCHAR(MAX),
			@Garantia_1			NVARCHAR(150),
			@Garantia_2			NVARCHAR(150),
			@Garantia_3			NVARCHAR(150)

		SELECT
			@Leyenda_Precios = sut.utexts_desc
		FROM tbSysUniqueTexts				sut		WITH (NOLOCK)
		WHERE	sut.lang_id		= @lang_id	AND
				sut.utexts_id	= 30800

		SELECT
			@Garantia_1 = sut.utexts_desc
		FROM tbSysUniqueTexts				sut
		WHERE	sut.lang_id		= @lang_id	AND
				sut.utexts_id	= 30801

		SELECT
			@Garantia_2 = sut.utexts_desc
		FROM tbSysUniqueTexts				sut
		WHERE	sut.lang_id		= @lang_id	AND
				sut.utexts_id	= 30802

		SELECT
			@Garantia_3 = sut.utexts_desc
		FROM tbSysUniqueTexts				sut
		WHERE	sut.lang_id		= @lang_id	AND
				sut.utexts_id	= 30803

		SET
			@Leyenda_Garantia = '<table>
								   <tr align="center">
										<td align="center">' +
											@Garantia_1		 +
										'</td>
								   </tr>
								   <tr align="center">
										<td align="center">' +
											@Garantia_2		 +
										'</td>
								   </tr>
								   <tr align="center">
										<td align="center">' +
											@Garantia_3		 +
										'</td>
								   </tr>
								</table>'

	-- ---------------------------------------------------



	DECLARE @strInCash AS NVARCHAR(100)
	SELECT @strInCash = tut.utexts_desc
		FROM tbsysUniqueTexts tut		WITH (NOLOCK)
		WHERE	tut.lang_id		= @lang_id AND
				tut.utexts_id	= 20507



	-- ---------------------------------------------------

	-- Obtiene Tipo de Cambio Forzado
	DECLARE @bitSaleOrder_printpriceNeto AS BIT
	DECLARE @bitSaleOrder_printWithTaxes AS BIT
	DECLARE @df_SaleOrderEnableCurrency4Total AS INT
	DECLARE @intCurrIdFrom AS INT
	DECLARE @intCurrIdTo   AS INT
	DECLARE @decCurrIdTo   AS DECIMAL(25,10)
	DECLARE @user_id	   AS INT
	SELECT  @intCurrIdTo	= tb.curr_id,
			@intCurrIdFrom	= tsoh.curr_id4Exchange,
			@decCurrIdTo    = tsoh.curr_idExchange,
			@bitSaleOrder_printWithTaxes		= ISNULL(tdf.df_SaleOrder_printWithTaxes,'False'),
			@df_SaleOrderEnableCurrency4Total	= ISNULL(tdf.df_SaleOrderEnableCurrency4Total,tb.curr_id),
			@user_id							= tsoh.[user_id],
			@bitSaleOrder_printpriceNeto		= ISNULL(tdf.df_SaleOrder_printpriceNeto,'False')
		FROM tbSaleOrderHeader tsoh			WITH (NOLOCK)
		INNER JOIN tbDocumentsFile tdf		WITH (NOLOCK)
			ON	tdf.comp_id = tsoh.comp_id AND
				tdf.df_id	= tsoh.df_id
		INNER JOIN tbBranch tb				WITH (NOLOCK)
		ON		tb.comp_id	= tsoh.comp_id
			AND tb.bra_id	= tsoh.bra_id

		WHERE	tsoh.comp_id	= @comp_id  -- Ref #1
		AND		tsoh.bra_id		= @bra_id
		AND		tsoh.soh_id		= @soh_id	-- Ref #1


	DECLARE @bitIsExchangeForced AS BIT
	IF @intCurrIdTo <> @intCurrIdFrom
		BEGIN
			SET @bitIsExchangeForced = 'True'
		END









	IF @intCurrIdFrom IS NULL OR
	   @intCurrIdTo   IS NULL OR
	   IsNull(@decCurrIdTo,0) = 0
	   BEGIN
	   		SET @intCurrIdFrom = 0
	   		SET @intCurrIdTo   = 0
	   		SET @decCurrIdTo   = 0
	   END


--==
--SELECT 'LPM',@intCurrIdTo,@intCurrIdFrom
--==

	-- ------------------------------------------------------------------------------
	-- De no haberse fijado el tipo de cambio, se pone el de la sucursal a grabar
	-- ------------------------------------------------------------------------------
	IF @intCurrIdTo = @intCurrIdFrom
		BEGIN
			--SELECT 1 / 0
			SELECT	@intCurrIdTo	= tb.curr_id4Exchange,
					@intCurrIdFrom	= tb.curr_id
				 FROM tbBranch tb										WITH (NOLOCK)
				 WHERE		tb.comp_id	= @comp_id	AND
							tb.bra_id	= @bra_id
			SET @decCurrIdTo = dbo.fnGetExchange2(@comp_id,1,@intCurrIdTo,@intCurrIdFrom,0,0,0,'false')
			set @bitIsExchangeForced = 'False'
		END

	-- MOS 03-2018, para que si cambia el tipo de cambio las conversiones las haga al tipo de cambio guardado para informar los totales.
	-- HDP de Irion
	IF	@soh_Currency4Total IS NOT NULL   AND
		@curr_id4Total		= @soh_Currency4Total
		BEGIN
			IF @bitIsExchangeForced = 'False'
				BEGIN
					SET @decCurrIdTo   =  dbo.fnNoZDiv( @soh_exchange2Currency4Total )
				END
			ELSE
				BEGIN
					SET @decCurrIdTo   = 1 / dbo.fnNoZDiv( @soh_exchange2Currency4Total )
				END
		END
	-- ------------------------------------------------------------------------------

--==
--SELECT 'LPM',@intCurrIdTo,@intCurrIdFrom
--==



	/**************************************************************************************************************************************/
	/* recuperamos en una temporal la sumatoria de los impuestos de cada item del pedido en la moneda del item y en la moneda del cliente */
	INSERT INTO @tmpSaleOrderTaxes (sod_id, taxes_item_curr, taxes_item_cust)
		SELECT  tsot.sod_id,
				SUM(dbo.fnGetExchange2(@comp_id, tsot.tm_total ,tsot.curr_id, tsod.[curr_id] ,@intCurrIdTo, @intCurrIdFrom, @decCurrIdTo, 'FALSE')) [taxes_item_curr],	-- Ref #1
				SUM(dbo.fnGetExchange2(@comp_id, tsot.tm_total ,tsot.curr_id, @curr_id4Total ,@intCurrIdTo, @intCurrIdFrom, @decCurrIdTo, 'FALSE')) [taxes_item_cust]	-- Ref #1
	--			SUM(dbo.fnGetExchange2(@comp_id, tsot.tm_total ,tsot.curr_id, tc.[curr_id]   ,@intCurrIdTo, @intCurrIdFrom, @decCurrIdTo, 'FALSE')) [taxes_item_cust]	-- Ref #1
			FROM 	tbSaleOrderTaxes					tsot		WITH (NOLOCK)
					INNER JOIN tbSaleOrderDetail		tsod		WITH (NOLOCK)
					ON	tsod.comp_id		= tsot.comp_id
					AND tsod.bra_id			= tsot.bra_id
					AND tsod.soh_id			= tsot.soh_id
					AND tsod.sod_id			= tsot.sod_id
					INNER JOIN tbSaleOrderHeader		tsoh		WITH (NOLOCK)
					ON	tsoh.comp_id		= tsot.comp_id
					AND tsoh.bra_id			= tsot.bra_id
					AND tsoh.soh_id			= tsot.soh_id
					INNER JOIN tbCustomer				tc			WITH (NOLOCK)
					ON	tc.cust_id			= tsoh.cust_id
					AND tc.comp_id			= tsoh.comp_id

			WHERE	tsot.comp_id			= @comp_id
			AND		tsot.bra_id				= @bra_id
			AND		tsot.soh_id				= @soh_id
			GROUP BY  tsot.sod_id

	--SELECT * FROM #tmpSaleOrderTaxes
	/***************************************************************************************************************************************/



	/**************************************************************************************************************************************/
	/* recuperamos en una temporal la sumatoria de los impuestos de cada item del pedido en la moneda del item y en la moneda del cliente */
	-- IDEM pero solo de IVA
	INSERT INTO @tmpSaleOrderTaxesIVA(sod_id, taxes_item_curr, taxes_item_cust)
		SELECT  tsot.sod_id,
				SUM(dbo.fnGetExchange2(@comp_id, tsot.tm_total ,tsot.curr_id, tsod.[curr_id] ,@intCurrIdTo, @intCurrIdFrom, @decCurrIdTo, 'FALSE')) [taxes_item_curr],	-- Ref #1
				SUM(dbo.fnGetExchange2(@comp_id, tsot.tm_total ,tsot.curr_id, @curr_id4Total ,@intCurrIdTo, @intCurrIdFrom, @decCurrIdTo, 'FALSE')) [taxes_item_cust]	-- Ref #1
			FROM 	tbSaleOrderTaxes					tsot			WITH (NOLOCK)
					INNER JOIN tbSaleOrderDetail		tsod			WITH (NOLOCK)
						ON	tsod.comp_id		= tsot.comp_id
						AND tsod.bra_id			= tsot.bra_id
						AND tsod.soh_id			= tsot.soh_id
						AND tsod.sod_id			= tsot.sod_id
					INNER JOIN tbSaleOrderHeader		tsoh			WITH (NOLOCK)
						ON	tsoh.comp_id		= tsot.comp_id
						AND tsoh.bra_id			= tsot.bra_id
						AND tsoh.soh_id			= tsot.soh_id
					INNER JOIN tbCustomer				tc				WITH (NOLOCK)
						ON	tc.cust_id			= tsoh.cust_id
						AND tc.comp_id			= tsoh.comp_id
					INNER JOIN tbTaxName ttn							WITH (NOLOCK)
						ON		ttn.comp_id= @comp_id
							AND ttn.tax_id = tsot.tax_id


			WHERE	tsot.comp_id			= @comp_id
			AND		tsot.bra_id				= @bra_id
			AND		tsot.soh_id				= @soh_id
			AND		ttn.tax_class			= 1  -- IVA
			GROUP BY tsot.sod_id

	--SELECT * FROM #tmpSaleOrderTaxes
	/***************************************************************************************************************************************/



	-- -----------------------------------------------
	-- Calculo de los TOTALES en monda de la sucursal
	-- -----------------------------------------------
	DECLARE @decSubtotal AS	DECIMAL(18,2)
	SELECT	@decSubtotal  =
			-- Muestra importes NETOS
			CASE WHEN @bitSaleOrder_printWithTaxes = 'false' THEN
				(Select	SUM(SOD1.[sod_qty] * (
												 dbo.fnGetExchange2(@comp_id,
																	SOD1.[sod_price] ,
																	SOD1.[curr_id],
																	@curr_id4Total,  --tc1.[curr_id] ,
																	@intCurrIdTo,
																	@intCurrIdFrom, -- Ref #1
																	@decCurrIdTo,	-- Ref #1
																	'FALSE')
												--	+			-- MOS 07-2022 x DM
												--sod1.sod_creditInt
												--    +
												--sod1.sod_creditIntPlus
											  )
						   )
				From	tbSaleOrderDetail SOD1						WITH (NOLOCK)
						INNER JOIN tbSaleOrderHeader tsoh1			WITH (NOLOCK)
							ON		tsoh1.bra_id	= SOD1.bra_id
								AND tsoh1.soh_id	= SOD1.soh_id
								AND tsoh1.comp_id	= SOD1.comp_id
						INNER JOIN tbCustomer tc1					WITH (NOLOCK)
							ON		tc1.comp_id		= tsoh1.comp_id
								AND tc1.cust_id		= tsoh1.cust_id
				Where	SOD1.comp_id	= @comp_id
					And SOD1.bra_id		= @bra_id
					And SOD1.soh_id		= @soh_id)
			ELSE
				-- muestra importes TOTALES
				(Select	Sum( SOD1.[sod_qty] * (
													dbo.fnGetExchange2(@comp_id,
																 SOD1.[sod_price] ,
																 SOD1.[curr_id],
																 @curr_id4Total, --tc1.[curr_id] ,
																 @intCurrIdTo,
																 @intCurrIdFrom, -- Ref #1
																 @decCurrIdTo,	 -- Ref #1
																 'FALSE')
												--	+			-- MOS 07-2022 x DM
												--sod1.sod_creditInt
												--    +
												--sod1.sod_creditIntPlus
													+
													(isnull(tmpSOT.[taxes_item_cust],0) / dbo.fnNoZDiv((SOD1.[sod_qty])))
											  )
				           )
					From	tbSaleOrderDetail				SOD1		WITH (NOLOCK)
							INNER JOIN tbSaleOrderHeader	tsoh1		WITH (NOLOCK)
								ON		tsoh1.bra_id	= SOD1.bra_id
									AND tsoh1.soh_id	= SOD1.soh_id
									AND tsoh1.comp_id	= SOD1.comp_id
							INNER JOIN tbCustomer			tc1			WITH (NOLOCK)
								ON tc1.comp_id			= tsoh1.comp_id
									AND tc1.cust_id		= tsoh1.cust_id
							LEFT JOIN @tmpSaleOrderTaxes	tmpSOT
								ON tmpSOT.sod_id		= SOD1.sod_id
					Where	SOD1.comp_id	= @comp_id
						And SOD1.bra_id		= @bra_id
						And SOD1.soh_id		= @soh_id)
			END

	FROM	tbBranch tb
	WHERE		tb.comp_id	= @comp_id
		AND		tb.bra_id	= @bra_id
	-- -----------------------------------------------
	--SELECT  @decSubtotal




	DECLARE @cantitems INT

	DECLARE @ldf_id	INT
	DECLARE	@sd_id	INT

	SELECT @ldf_id = tsoh.df_id
		FROM tbSaleOrderHeader tsoh		WITH (NOLOCK)
		WHERE	tsoh.comp_id	= @comp_id	AND
				tsoh.bra_id		= @bra_id	AND
				tsoh.soh_id		= @soh_id

	SELECT		@sd_id = tdf.sd_id
		FROM	tbDocumentsFile tdf		WITH (NOLOCK)
		WHERE	tdf.df_id = @ldf_id


		IF @page_id = 11032
					SET @cantitems = 1
		ELSE
			SELECT @cantitems = COUNT(*)
				FROM tbSaleOrderDetail tsod		WITH (NOLOCK)
				WHERE	tsod.comp_id	= @comp_id AND
						tsod.soh_id		= @soh_id

--SELECT @cantitems



	DECLARE @strSalesOrderTitle AS NVARCHAR(22)
	DECLARE @intSdId			AS int
	SET @strSalesOrderTitle = ''
	SELECT	@strSalesOrderTitle = ISNULL(tdf.df_SalesOrderTitle,''),
			@intSdId			= tdf.sd_id
		FROM tbDocumentsFile tdf
		WHERE	tdf.comp_id = @comp_id AND
				tdf.df_id	= @ldf_id

	IF @strSalesOrderTitle = ''
		BEGIN
			IF @intSdId = 5  -- Si es Presupuesto y no tiene titulo asignado en el documento.
				BEGIN
					SELECT @strSalesOrderTitle = tut.utexts_desc
						FROM tbsysUniqueTexts tut					WITH (NOLOCK)
						WHERE	tut.lang_id		= @lang_id AND
								tut.utexts_id	= 23301
				END
			ELSE
				BEGIN
					SELECT @strSalesOrderTitle = tut.utexts_desc
						FROM tbsysUniqueTexts tut					WITH (NOLOCK)
						WHERE	tut.lang_id		= @lang_id AND
								tut.utexts_id	= 23300
				END
		END

	SELECT	TOP (@cantitems)
			SOH.[soh_cd],
			df.df_desc,
			convert(int,@bitSaleOrder_printWithTaxes)							[bra_SaleOrderWithTaxes],

			CONVERT(VARCHAR,SOH.bra_id) + '-' + CONVERT(VARCHAR,SOH.soh_id)		[soh_id],

			ISNULL(I.[item_code],ISNULL(Isod.[item_code],''))					[item_code],

			CASE WHEN ISNUMERIC(SOD.sod_tis_id_origin)=1 AND NOT I.item_code IS NULL
				THEN '╚══> ' + CASE WHEN SOD.sod_itemDesc<>'' THEN SOD.sod_itemDesc ELSE I.item_desc END
				ELSE ''		 + CASE WHEN SOD.sod_itemDesc<>'' THEN SOD.sod_itemDesc ELSE I.item_desc END
			END																	[item_desc],

			SM.[sm_name],
			SOH.[soh_lastUpdate],
			SOH.[soh_deliveryDate],
			SOH.[soh_observation1],
			SOH.[soh_observation2],
			SOH.[soh_observation3],
			SOH.[soh_observation4],
			SOH.[soh_quotation],


			CONVERT(VARCHAR,CU.cust_id)+ '-' + CONVERT(VARCHAR,CU.cust_name)	[cust_name],
			CU.[cust_phone1],
			CU.[cust_address],
			CU.[cust_city] + ' ' + '(' + cu.[cust_zip]+ ')'						[cust_city],
			SC.[country_desc],
			SOD.[sod_qty],
			ST.[st_desc] +
							CASE
							    WHEN soh.soh_inCash IS NOT NULL AND soh.soh_inCash <> 0 THEN '  ' + @strInCash + CONVERT(NVARCHAR(50),convert(decimal(19,2),soh.soh_inCash)) + ' *'
							    ELSE	''
							END													[st_desc],
			D.[disc_desc],
			DL.[dl_name],
			FC.[fc_desc],

			CU.cust_taxNumber [cust_taxNumber],
			CU.cust_email [cust_email],


			/*
			CASE when isnull(br.bra_SaleOrderWithTaxes,'false') = 'true' then
					isnull(SOD.[sod_qty],0) * (isnull(SOD.[sod_price],0) + (isnull(tmpSOT.[taxes_item_curr],0)  / isnull(SOD.[sod_qty],0)))
			ELSE	isnull(SOD.[sod_qty],0) *  isnull(SOD.[sod_price],0)
			END		[subtotal],



			CASE when isnull(br.bra_SaleOrderWithTaxes,'false') = 'true' then
					isnull(SOD.[sod_price],0) + (isnull(tmpSOT.[taxes_item_curr],0)  / isnull(SOD.[sod_qty],0))
			ELSE    isnull(SOD.[sod_price],0)
			END 	[sod_price],*/


			--23-09-2010 - MB - Se cambio la condicion de comparacion , de 'true' a 'false'
			CASE
				WHEN df.df_SaleOrder_printForceCurrency4Items = 1 THEN
							dbo.fnGetExchange2( @comp_id,
												(
														CASE  -- ***LKHLKHLKHL
															when @bitSaleOrder_printWithTaxes = 'false' AND @bitSaleOrder_printpriceNeto = 'False' then	ISNULL(isnull(SOD.sod_price    ,sod_price),0)
															when @bitSaleOrder_printWithTaxes = 'false' AND @bitSaleOrder_printpriceNeto = 'True'  then	ISNULL(isnull(SOD.sod_priceNeto,sod_price),0)
															ELSE																						ISNULL(isnull(SOD.sod_priceNeto,sod_price),0) + (isnull(tmpSOT.[taxes_item_curr],0)  / dbo.fnNoZDiv( isnull(SOD.[sod_qty],0)))
														END		* isnull(SOD.[sod_qty],0)
													--CASE
													--	when @bitSaleOrder_printWithTaxes = 'false' then	isnull(SOD.[sod_qty],0) *  isnull(SOD.[sod_price],0)
													--	ELSE												isnull(SOD.[sod_qty],0) * (isnull(SOD.[sod_price],0) + (isnull(tmpSOT.[taxes_item_curr],0)  / dbo.fnNoZDiv( isnull(SOD.[sod_qty],0))))
													--END
												),
												SOD.[curr_id],
												ISNULL(df.df_SaleOrderEnableCurrency4Total,BR.curr_id) , -- MOS 07-2017
												@intCurrIdTo ,
												@intCurrIdFrom,
												@decCurrIdTo,
												'FALSE')
				ELSE
					(
						CASE	-- ***LKHLKHLKHL
							when @bitSaleOrder_printWithTaxes = 'false' AND @bitSaleOrder_printpriceNeto = 'False' then	ISNULL(isnull(SOD.sod_price    ,sod_price),0)
							when @bitSaleOrder_printWithTaxes = 'false' AND @bitSaleOrder_printpriceNeto = 'True'  then	ISNULL(isnull(SOD.sod_priceNeto,sod_price),0)
							ELSE																						ISNULL(isnull(SOD.sod_priceNeto,sod_price),0) + (isnull(tmpSOT.[taxes_item_curr],0)  / dbo.fnNoZDiv( isnull(SOD.[sod_qty],0)))
						END	 * isnull(SOD.[sod_qty],0)
						--CASE
						--	when @bitSaleOrder_printWithTaxes = 'false' then	isnull(SOD.[sod_qty],0) *  isnull(SOD.[sod_price],0)
						--	ELSE												isnull(SOD.[sod_qty],0) * (isnull(SOD.[sod_price],0) + (isnull(tmpSOT.[taxes_item_curr],0)  / dbo.fnNoZDiv( isnull(SOD.[sod_qty],0))))
						--END
					)
			END																						[subtotal],

			--23-09-2010 - MB - Se cambio la condicion de comparacion , de 'true' a 'false'
			CASE
				WHEN df.df_SaleOrder_printForceCurrency4Items = 1 THEN

						dbo.fnGetExchange2(			@comp_id,
													(
														CASE  -- ***LKHLKHLKHL
															when @bitSaleOrder_printWithTaxes = 'false' AND @bitSaleOrder_printpriceNeto = 'False' then	ISNULL(isnull(SOD.sod_price    ,sod_price),0)
															when @bitSaleOrder_printWithTaxes = 'false' AND @bitSaleOrder_printpriceNeto = 'True'  then	ISNULL(isnull(SOD.sod_priceNeto,sod_price),0)
															-- FORRA SONNOS: when @bitSaleOrder_printWithTaxes = 'True' AND @bitSaleOrder_printpriceNeto = 'False' then	ISNULL(isnull(SOD.sod_price    ,sod_price),0)
															ELSE																						ISNULL(isnull(SOD.sod_priceNeto,sod_price),0) + (isnull(tmpSOT.[taxes_item_curr],0)  / dbo.fnNoZDiv( isnull(SOD.[sod_qty],0)))
														END
														--CASE
														--	when @bitSaleOrder_printWithTaxes = 'false' then	isnull(SOD.[sod_price],0)
														--	ELSE												isnull(SOD.[sod_price],0) + (isnull(tmpSOT.[taxes_item_curr],0)  / dbo.fnNoZDiv( isnull(SOD.[sod_qty],0)))
														--END
													)
													,SOD.[curr_id],
													ISNULL(df.df_SaleOrderEnableCurrency4Total,BR.curr_id) , -- MOS 07-2017
													@intCurrIdTo ,
													@intCurrIdFrom,
													@decCurrIdTo,
													'FALSE')

				ELSE
					 (
						CASE	-- ***LKHLKHLKHL
							when @bitSaleOrder_printWithTaxes = 'false' AND @bitSaleOrder_printpriceNeto = 'False' then	ISNULL(isnull(SOD.sod_price    ,sod_price),0)
							when @bitSaleOrder_printWithTaxes = 'false' AND @bitSaleOrder_printpriceNeto = 'True'  then	ISNULL(isnull(SOD.sod_priceNeto,sod_price),0)
							ELSE																						ISNULL(isnull(SOD.sod_priceNeto,sod_price),0) + (isnull(tmpSOT.[taxes_item_curr],0)  / dbo.fnNoZDiv( isnull(SOD.[sod_qty],0)))
						END
					 )
			END																					[sod_price],

			CASE
				WHEN df.df_SaleOrder_printForceCurrency4Items = 1 THEN @intCurrIdTo
				ELSE SOD.curr_id
			END																					[curr_id],

			CASE
				WHEN df.df_SaleOrder_printForceCurrency4Items = 1 THEN cc2.curr_symbol
				ELSE CC.curr_symbol
			END																					[curr_symbol],



			dbo.fnGetExchange2(@comp_id, SOD.[sod_price] ,SOD.[curr_id],BR.[curr_id] ,
								@intCurrIdTo ,@intCurrIdFrom, @decCurrIdTo, 'FALSE') [Currency], -- Ref #1


			CU.curr_id																				[curr_id2],

			CC2.curr_symbol																			[curr_symbol2],

			@decSubtotal																			[ST1],



			--isnull(Round((soh.soh_discount * SOH.soh_ExchangeToCustomerCurrency),2),0)

			dbo.fnGetExchange2(	@comp_id,
								SOH.soh_discount,
								/*SOH.soh_CustomerCurrency*/ br.curr_id ,
								@curr_id4Total,
								@intCurrIdTo,
								@intCurrIdFrom,
								@decCurrIdTo,
								'false')															[soh_discount1],



			CASE when @bitSaleOrder_printWithTaxes = 'false' then
				Round((SELECT	ISNULL(sum(
										  dbo.fnGetExchange2(@comp_id,SOT.tm_total, SOT.curr_id, @curr_id4Total, @intCurrIdTo, @intCurrIdFrom, @decCurrIdTo,'false') -- Ref #1
										  --dbo.fnGetExchange2(@comp_id,SOT.tm_total, SOT.curr_id, tc1.curr_id, @intCurrIdTo, @intCurrIdFrom, @decCurrIdTo,'false') -- Ref #1
										   ),0)



						From	tbSaleOrderTaxes SOT
								INNER JOIN tbSaleOrderHeader tsoh
								ON  tsoh.comp_id = sot.comp_id AND tsoh.bra_id = sot.bra_id AND tsoh.soh_id = sot.soh_id

								INNER JOIN tbCustomer tc1
								ON  tc1.comp_id	 = tsoh.comp_id
								AND tc1.cust_id  = tsoh.cust_id

						Where	SOT.comp_id = SOD.comp_id
						and		SOT.bra_id	= SOD.bra_id
						and		SOT.soh_id	= SOD.soh_id),2)
				ELSE 0
			END																				[totalTaxes1],

				ltrim(rtrim(BR.bra_address)) + ' - ' + ltrim(rtrim(BR.bra_address1)) + ' (' + ltrim(rtrim(BR.bra_zip)) + ')'		[bra_address],

				BR.bra_phone,
				tis.itst_StorageLocation,
				tis.itst_PickingLocation,
				ISNULL(SOD.sod_note1,'') + ' ' + ISNULL(SOD.sod_note2,'')											[sod_note1],

				(SELECT TOP 1 ttn.tax_percentage
					FROM tbSaleOrderTaxes			tsot2		WITH (NOLOCK)
					INNER JOIN tbTaxName	ttn					WITH (NOLOCK)
						ON	ttn.comp_id = tsot2.comp_id
						AND ttn.tax_id	= tsot2.tax_id
					WHERE		tsot2.comp_id	= SOH.comp_id
						AND		tsot2.bra_id	= SOH.bra_id
						AND		tsot2.soh_id	= SOH.soh_id
						AND		tsot2.sod_id	= SOD.sod_id
						AND		ttn.tax_class	= 1)				[tax_desc],
					ISNULL(tcb.custb_name,'')					[custb_name],




				/*Agregados pedidos por MOS, realizados por STL 17/03/2010*/


				--Datos de las nuevas columnas
				sod.sod_qty/dbo.fnNoZDiv(isnull(i.item_upb,0))	[Boxes],
				sod.sod_qty * ISNULL(i.item_volume,0)			[Volume],
				sod.sod_qty * ISNULL(i.item_weight,0)			[Weight],

				--Datos nuevos de la Sucursal y del Delivery
				ISNULL(DL.dl_city,'')							[dl_city],



				CASE WHEN br.country_id = 54 THEN
					'X'
				ELSE
					''
				END [Letter],
				ISNULL(i.item_upb,0) [item_upb],

				CASE WHEN br.country_id = 54 THEN
					(SELECT tut.utexts_desc
					FROM tbsysUniqueTexts tut WHERE tut.lang_id = 2 AND tut.utexts_id = 710)
				ELSE
					''
				END [Text],


				ISNULL(dl.dl_address,'False')								[dl_address],
				ISNULL(dl.dl_zip,'')										[dl_zip],


				--ticket 193 STL


				CASE
					WHEN sod.sod_qty < =  dbo.fnGetAStock(@comp_id,-1,I.item_id,9999999999.9999)	THEN 'P'
					WHEN sod.sod_qty < =  dbo.fnGetStock(@comp_id,-1,I.item_id)					THEN 'F'
					ELSE
																										 'N'
				END															[StockLetter],
				ts.stor_desc												[stor_desc],
				vsos.ssos_desc,

				dbo.fnGetExchange2(	@comp_id,
									ISNULL(soh.soh_loan,0),
									br.curr_id /*cu.curr_id  14-06-2019 MOS, se cambio a la moneda de la sucursal porque es la que tiene los totales.  Ver si llama alguien por este tema*/		,
									@curr_id4Total  /*@curr_id4Total*/,
									@intCurrIdTo,
									@intCurrIdFrom,
									@decCurrIdTo,
									'false')								[soh_loan],

				cu.cust_address4Delivery,
				@strSalesOrderTitle											[df_SalesOrderTitle],
				ISNULL(
					(SELECT TOP 1 ts2.stor_desc
						FROM tbStorage_TransferTransactions tstt			WITH (NOLOCK)
						INNER JOIN tbStorage ts2							WITH (NOLOCK)
							ON	ts2.comp_id = tstt.comp_id			AND
								ts2.stor_id = tstt.stor_id_From

						where	tstt.comp_id	= SOD.comp_id		AND
								tstt.soh_bra_id = sod.bra_id		AND
								tstt.soh_id		= sod.soh_id		AND
								tstt.item_id	= sod.item_id
					)
				,'')														[stor_descFromInternalTransfer],
				ISNULL(tss.state_desc,'')									[state_desc],
				'*' + ' ' + dbo.fnStrPADL(sod.sod_id,10, '0') + ' ' + '*'	[sod_id],
				us.user_lastname + ', ' + us.user_firstname					[User_Name],
				SOH.soh_deliveryAddress										[soh_deliveryAddress],
				ISNULL(I.item_picture,Isod.item_picture)					[item_picture],
				DF.df_image,
				ISNULL(I.item_descHTML,'')									[item_descHTML],
				ISNULL(SM.sm_email,'')										[sm_email],
				ISNULL(us.user_email,'')									[user_email],
				@Leyenda_Precios											[Leyenda_Precios],
				@Leyenda_Garantia											[Leyenda_Garantia],
				DF.df_reportOrders_Footer,
				--ACA PONDRÍA LA FUNCIÓN QUE DEVUELVE LA GARANTÍA
				dbo.fnGetGuaranteeDaysInYearsAndMonths(sod.comp_id, @lang_id, sod.item_id)	[Guarantee],
				--ACÁ MANDAMOS LA COTIZACIÓN DEL DOLAR PARA MULTIPLICAR EN EL REPORTE
				dbo.fnGetReciprocoIfNeed(@decCurrIdTo)						[Curr_Id_USD_Cotizacion],		-- x HDP Depco 12-2018 MOS.  Si jode a otros SACARLO !!!
				--@curr_id_USD_Cotizacion										[Curr_Id_USD_Cotizacion],
				@curr_id_USD_Symbol											[Curr_ID_USD_Symbol],
				ISNULL(tp.pro_desc,'')										[pro_desc],
				ISNULL(CU.cust_contact4Alternative,'')						[cust_contact4Alternative],
				ISNULL(CU.cust_email4Alternative,'')						[cust_email4Alternative],
				ISNULL(CU.cust_contact4AlternativeII,'')					[cust_contact4AlternativeII],
				ISNULL(CU.cust_email4AlternativeII,'')						[cust_email4AlternativeII],
				soh.soh_limitDate,
				isnull(i.item_vendorCode,'')								[item_vendorCode],
				ISNULL(SOH.soh_htmlNote,'')									[soh_htmlNote],
				BR.bra_taxNumber											[bra_taxNumber],
				isnull(tcf.custf_name,'')									[custf_name],
				ISNULL(CU.cust_note1,'')									[cust_note1],
				ISNULL(CU.cust_note2,'')									[cust_note2],
				ISNULL(CU.cust_note3,'')									[cust_note3],
				ISNULL(CU.cust_note4,'')									[cust_note4],
				ISNULL(tb.brand_desc,'')									[brand_desc],
				dbo.fnGetEAN_Encode4EAN13(dbo.fnStrPADL(dbo.fnGetOnlyNumbers(dbo.fnStrPADL(soh.bra_id,5, '0') + dbo.fnStrPADL(soh.soh_id,8, '0')),13, '0'),'False') [CodeSoh_id],
				--dbo.fnGetEAN_Encode4EAN13(dbo.fnStrPADr(dbo.fnGetOnlyNumbers(dbo.fnStrPADr(5500320,7, '0') + dbo.fnStrPADl(25608,6, '0')),13, '0'),'False') [CodeSoh_id],
			    --SOD.sod_price + (SOD.sod_price	* ISNULL(ttn.tax_percentage,0) / 100)						[sod_price_plusii], --Precio con impuestos internos




				-- MOS 01-2023 + GA x SOne: Idem abajo en un solo paso:  PRECIO MAS IMPUESTOS INTERNOS
			    CASE
					WHEN df.df_SaleOrder_printForceCurrency4Items = 1  THEN --IMPRESIÓN: Forzar moneda de Items a moneda del TOTAL
							dbo.fnGetExchange2(	@comp_id,
												SOD.sod_price + (SOD.sod_price	* ISNULL(ttn.tax_percentage,0) / 100) , -- MOS 07-2017
												SOD.[curr_id],
												ISNULL(df.df_SaleOrderEnableCurrency4Total,BR.curr_id) , -- MOS 07-2017
												@intCurrIdTo ,
												@intCurrIdFrom,
												@decCurrIdTo,
												'FALSE')

					ELSE	 SOD.sod_price + (SOD.sod_price	* ISNULL(ttn.tax_percentage,0) / 100)
				END		* dbo.fnNoZDiv(1-(ISNULL(sod.sod_itemDiscount,0) / 100))										[sod_price_plusii],
			 --   CASE
				--	WHEN df.df_SaleOrder_printForceCurrency4Items = 1 THEN --IMPRESIÓN: Forzar moneda de Items a moneda del TOTAL
				--			dbo.fnGetExchange2(@comp_id,
				--			SOD.sod_price
				--			,SOD.[curr_id],
				--			ISNULL(df.df_SaleOrderEnableCurrency4Total,BR.curr_id) , -- MOS 07-2017
				--			@intCurrIdTo ,
				--			@intCurrIdFrom,
				--			@decCurrIdTo,
				--			'FALSE') + (dbo.fnGetExchange2(	@comp_id,
				--											SOD.sod_price
				--											,SOD.[curr_id],
				--											ISNULL(df.df_SaleOrderEnableCurrency4Total,BR.curr_id) , -- MOS 07-2017
				--											@intCurrIdTo ,
				--											@intCurrIdFrom,
				--											@decCurrIdTo,
				--											'FALSE')	* ISNULL(ttn.tax_percentage,0) / 100)

				--	ELSE	 SOD.sod_price + (SOD.sod_price	* ISNULL(ttn.tax_percentage,0) / 100)
				--END																							[sod_price_plusii], --Precio con impuestos internos con condicion df_SaleOrder_printForceCurrency4Items






				I.item_guarantee																			[item_guarantee],
				dbo.fnGetStock(@comp_id,sod.stor_id, i.item_id)												[Stock], -- Fisico
				--SOD.sod_price																				[sod_price_withouttaxes], -- Precio sin impuestos
				--SOD.sod_price * sod.sod_qty																	[subtotal_withouttaxes]   -- Subtotal del item sin impuestos

			--	23-09-2010 - MB - Se cambio la condicion de comparacion , de 'true' a 'false'
			CASE
				WHEN df.df_SaleOrder_printForceCurrency4Items = 1 THEN

						dbo.fnGetExchange2(	@comp_id,
											SOD.sod_price,
											SOD.[curr_id],
											ISNULL(df.df_SaleOrderEnableCurrency4Total,BR.curr_id) , -- MOS 07-2017
											@intCurrIdTo ,
											@intCurrIdFrom,
											@decCurrIdTo,
											'FALSE')

				ELSE
						SOD.sod_price
			END																					[sod_price_withouttaxes],
			CASE
				WHEN df.df_SaleOrder_printForceCurrency4Items = 1 THEN
							dbo.fnGetExchange2( @comp_id,
												SOD.sod_price * sod.sod_qty,
												SOD.[curr_id],
												ISNULL(df.df_SaleOrderEnableCurrency4Total,BR.curr_id) , -- MOS 07-2017
												@intCurrIdTo ,
												@intCurrIdFrom,
												@decCurrIdTo,
												'FALSE')
				ELSE							SOD.sod_price * sod.sod_qty
			END																						[subtotal_withouttaxes],
			SOD.sod_itemDiscount																	[item_discountByItem],

			(SELECT TOP 1 SUM(tsot2.tm_total)
					FROM tbSaleOrderTaxes			tsot2		WITH (NOLOCK)
					INNER JOIN tbTaxName	ttn					WITH (NOLOCK)
						ON	ttn.comp_id = tsot2.comp_id
						AND ttn.tax_id	= tsot2.tax_id
					WHERE		tsot2.comp_id	= SOH.comp_id
						AND		tsot2.bra_id	= SOH.bra_id
						AND		tsot2.soh_id	= SOH.soh_id
						AND		tsot2.sod_id	= SOD.sod_id
						AND		ttn.tax_class	= 1
				GROUP BY	tsot2.tax_id,
							ttn.tax_desc,
							ttn.tax_class
				ORDER BY ttn.tax_class )													[tm_total],




				(SELECT TOP 1 tut.utexts_desc
				   FROM tbsysUniqueTexts tut WHERE tut.lang_id = 2 AND tut.utexts_id = 1013)		[TextLeyenda],
				ISNULL(br.bra_Mailing4CustOverdueDebt_FromEmail,'')									[bra_Mailing4CustOverdueDebt_FromEmail],
				ISNULL(tc.cat_desc,'')																[cat_desc],
				ISNULL(tsc.subcat_desc,'')															[subcat_desc],
				ISNULL(tsca.subcataux_desc,'')														[subcataux_desc],
				CC.curr_symbol																		[curr_symboltotal],
				CASE
					WHEN df.df_SaleOrder_printForceCurrency4Items = 1 THEN

						dbo.fnGetExchange2(	@comp_id,
											SOD.sod_price
											,SOD.[curr_id],
											ISNULL(df.df_SaleOrderEnableCurrency4Total,BR.curr_id) , -- MOS 09-2022
											@intCurrIdTo ,
											@intCurrIdFrom,
											@decCurrIdTo,
											'FALSE')

					ELSE
						SOD.sod_price
				END		* dbo.fnNoZDiv(1-(ISNULL(sod.sod_itemDiscount,0) / 100))																			[sod_price_netoWithDiscount],
				ISNULL(df.df_reportAdditionalFooter,'')																										[df_reportAdditionalFooter],


					-- MOS 12-2022: x SO le puse la funcion de tipo de cambio
				(SELECT TOP 1 SUM(dbo.fnGetExchange2(	@comp_id,
														tsot2.tm_total / dbo.fnNoZDiv(tsod.sod_qty),
														tsot2.curr_id,
														@curr_id4Total,
														@intCurrIdTo ,
														@intCurrIdFrom,
														@decCurrIdTo,
														'FALSE')	)
						FROM tbSaleOrderTaxes			tsot2		WITH (NOLOCK)
						INNER JOIN tbSaleOrderDetail AS tsod		WITH (NOLOCK)
							ON	tsod.comp_id	= tsot2.comp_id AND
								tsod.bra_id		= tsot2.bra_id AND
								tsod.soh_id		= tsot2.soh_id AND
								tsod.sod_id		= tsot2.sod_id
						INNER JOIN tbTaxName			ttn			WITH (NOLOCK)
							ON	ttn.comp_id		= tsot2.comp_id
							AND ttn.tax_id		= tsot2.tax_id
						WHERE		tsot2.comp_id	= SOH.comp_id
							AND		tsot2.bra_id	= SOH.bra_id
							AND		tsot2.soh_id	= SOH.soh_id
							AND		tsot2.sod_id	= SOD.sod_id
							AND		ttn.tax_class	= 1
					GROUP BY	tsot2.tax_id,
								ttn.tax_desc,
								ttn.tax_class
					ORDER BY ttn.tax_class )													[tm_totalInForcedCurrency],



				-- MOS 01-2023 + GA x SOne: SOLO Impuestos Internos del Precio.sod_discountByItem
			    CASE
					WHEN df.df_SaleOrder_printForceCurrency4Items = 1  THEN									-- IMPRESIÓN: Forzar moneda de Items a moneda del TOTAL
							dbo.fnGetExchange2(	@comp_id,
												(SOD.sod_price	* ISNULL(ttn.tax_percentage,0) / 100) ,		-- MOS 07-2017
												SOD.[curr_id],
												ISNULL(df.df_SaleOrderEnableCurrency4Total,BR.curr_id) ,	-- MOS 07-2017
												@intCurrIdTo ,
												@intCurrIdFrom,
												@decCurrIdTo,
												'FALSE')

					ELSE	 SOD.sod_price + (SOD.sod_price	* ISNULL(ttn.tax_percentage,0) / 100)
					END		* dbo.fnNoZDiv(1-(ISNULL(sod.sod_itemDiscount,0) / 100))				[sod_priceInternalTaxes],
				SOH.soh_uniqueID																	[soh_uniqueID],
				ISNULL(i.item_detail,ISNULL(isod.item_detail,''))									[item_detail],			-- tkt :21183
				ISNULL(i.tipi_id,isod.tipi_id)														[tipi_id],				-- tkt :21171
				ISNULL(tit.tipi_desc,ISNULL(titsod.tipi_desc,''))									[tipi_desc],			-- tkt :21171
				sod.sod_discountByItem																[sod_discountByItem],	-- tkt :21183
				sod.sod_discountByTotal																[sod_discountByTotal],	-- tkt :21183
				br.bra_desc																			[bra_desc]				-- tkt :21562

	FROM	dbo.tbSaleOrderHeader			SOH					WITH (NOLOCK)

			INNER Join tbSaleOrderDetail	SOD					WITH (NOLOCK)
			on  SOD.[comp_id]				= SOH.[comp_id]
			and SOD.[bra_id]				= SOH.[bra_id]
			and SOD.[soh_id]				= SOH.[soh_id]

			INNER Join tbDocumentsFile		DF					WITH (NOLOCK)
			on  DF.[comp_id]				= SOH.[comp_id]
			and DF.[df_id]					= SOH.[df_id]

			INNER  Join tbSalesman			SM					WITH (NOLOCK)
			on  SM.[comp_id]				= SOH.[comp_id]
			and SM.[sm_id]					= SOH.[sm_id]

			INNER Join tbCustomer			CU					WITH (NOLOCK)
			on  CU.[comp_id]				= SOH.[comp_id]
			and CU.[cust_id]				= SOH.[cust_id]

			LEFT JOIN tbCustomerFamily		tcf					WITH (NOLOCK)
			ON	tcf.comp_id					= SOH.comp_id	AND
				tcf.custf_id				= SOH.custf_id

			INNER Join tbsysCurrency		CC					WITH (NOLOCK)
			on	CC.[curr_id]				= sod.curr_id

			INNER join tbDelivery			DL					WITH (NOLOCK)
			on  DL.[comp_id]				= SOH.[comp_id]
			and DL.[dl_id]					= SOH.[dl_id]

			INNER join tbDiscount			D					WITH (NOLOCK)
			on	D.[comp_id]					= SOH.[comp_id]
			and D.[disc_id]					= SOH.[disc_id]

			INNER Join tbsysFiscalClass		FC					WITH (NOLOCK)
			on FC.[fc_id]					= CU.[fc_id]

			INNER Join tbsysCountry			SC					WITH (NOLOCK)
			on SC.[country_id]				= CU.[country_id]

			INNER JOIN tbsysState			TSS					WITH (NOLOCK)
			ON tss.state_id					= cu.state_id

			INNER Join tbSalesTerms			ST					WITH (NOLOCK)
			on  ST.[comp_id]				= SOH.[comp_id]
			and ST.[st_id]					= SOH.[st_id]

			INNER Join tbBranch				BR					WITH (NOLOCK)
			on  BR.[comp_id]				= SOD.[comp_id]
			and BR.[bra_id]					= SOD.[bra_id]

			Left Join tbItem				I					WITH (NOLOCK)
			on  I.[comp_id]					= SOD.[comp_id]
			and I.[item_id]					= SOD.[item_id]

			Left Join tbItem				Isod				WITH (NOLOCK)
			on  Isod.[comp_id]				= SOD.[comp_id]
			and Isod.[item_id]				= SOD.sod_item_id_origin

			LEFT JOIN tbItemType			tit					WITH (NOLOCK)
			ON	tit.comp_id					= I.comp_id AND
				tit.tipi_id					= I.tipi_id

			LEFT JOIN tbItemType			titsod				WITH (NOLOCK)
			ON	titsod.comp_id				= Isod.comp_id AND
				titsod.tipi_id				= Isod.tipi_id

			LEFT Join tbsysCurrency			CC2					WITH (NOLOCK)
			on	CC2.[curr_id]				= @curr_id4Total	-- CU.[curr_id]

			LEFT JOIN @tmpSaleOrderTaxesIVA	tmpSOT
			ON tmpSOT.sod_id				= SOD.sod_id

			left join tbItemStorage			tis					WITH (NOLOCK)
			on  tis.comp_id					= sod.comp_id
			and tis.stor_id					= sod.stor_id
			AND tis.item_id					= sod.item_id

			left join tbCustomerBranch		tcb					WITH (NOLOCK)
			on  tcb.comp_id					= SOH.comp_id
			AND tcb.cust_id					= SOH.cust_id
			AND tcb.cb_id					= SOH.cb_id

			LEFT JOIN tbStorage				ts					WITH (NOLOCK)
			ON  ts.comp_id					= SOD.comp_id
			AND ts.stor_id					= SOD.stor_id

			LEFT JOIN vwSaleOrderStatus			vsos			WITH (NOLOCK)
			ON	vsos.comp_id				= soh.comp_id
			AND vsos.bra_id					= soh.bra_id
			AND vsos.soh_id					= soh.soh_id
			AND vsos.lang_id				= @lang_id

			LEFT JOIN dbo.tbUser				us				WITH (NOLOCK)
			on	us.[user_id]				= soh.[user_id]

			LEFT JOIN tbProject					tp
			ON	tp.comp_id					= soh.comp_id	AND
				tp.pro_id					= soh.pro_id

			LEFT JOIN tbBrand					tb				WITH(NOLOCK)
			ON	tb.comp_id					= I.comp_id		AND
				tb.brand_id					= I.brand_id

			LEFT JOIN tbCategory				tc				WITH(NOLOCK)
			ON tc.comp_id					= I.comp_id		AND
			  tc.cat_id						= I.cat_id

			LEFT JOIN tbSubCategory				tsc				WITH(NOLOCK)
			ON tsc.comp_id				    = I.comp_id		AND
				tsc.cat_id					= I.cat_id		AND
				tsc.subcat_id				= I.subcat_id

			LEFT JOIN tbSubCategoryAux			 tsca			WITH(NOLOCK)
			ON  tsca.subcataux_id			= I.subcataux_id AND
				tsca.comp_id				= I.comp_id

			LEFT JOIN vwItemTaxesOnlyOneInternalTax		itii	WITH (NOLOCK)
				ON	itii.comp_id			= i.comp_id AND
					itii.item_id			= i.item_id

			LEFT JOIN tbTaxName							ttn		WITH (NOLOCK)
				ON 	ttn.comp_id				= itii.comp_id AND
					ttn.tax_id				= itii.tax_id

	where	SOH.[comp_id]		=	@comp_id
	and		SOH.[bra_id]		=	@bra_id
	and		SOH.[soh_id]		=	@soh_id

	ORDER BY
			CASE
				WHEN @intPrintOrder = 0 THEN convert(char(10),sod.sod_id)												-- Normal
				WHEN @intPrintOrder = 1 THEN sod.sod_itemDesc															-- Descripcion de articulo
				WHEN @intPrintOrder = 2 AND ISNULL(tis.itst_PickingLocation,'') <> '' THEN tis.itst_PickingLocation		-- Ubicacion
				WHEN @intPrintOrder = 2 AND ISNULL(tis.itst_StorageLocation,'') <> '' THEN tis.itst_StorageLocation		-- Ubicacion
				ELSE ''
			END



	--DROP TABLE #tmpSaleOrderTaxesIVA



	exec [spReports_getData3]@comp_id,@intBranch4Lang, @lang_id,10032



	-- ----------------------------------------------------
	-- Leyenda de tipo de cambio
	-- ----------------------------------------------------
	DECLARE @strCurrIdTo   AS nVARCHAR(40)
	DECLARE @strCurrIdFrom AS nVARCHAR(40)
	DECLARE @strText1	   AS NVARCHAR(20)
	DECLARE @strText2      AS NVARCHAR(20)


	-- MOS 03-2018, se paso para ARRIBA, esto es todo MIERDA, sos un REvERENDO HIJO DE RE MIL PUTAS ENFERMO FORRO MENTAL !!!!!!
	-- De no haberse fijado el tipo de cambio, se pone el de la sucursal a grabar
	--IF @intCurrIdTo = @intCurrIdFrom
	--	BEGIN


	--		SELECT	@intCurrIdTo	= tb.curr_id4Exchange,
	--				@intCurrIdFrom	= tb.curr_id
	--			 FROM tbBranch tb										WITH (NOLOCK)
	--			 WHERE		tb.comp_id	= @comp_id	AND
	--						tb.bra_id	= @bra_id
	--		SET @decCurrIdTo = dbo.fnGetExchange2(@comp_id,1,@intCurrIdTo,@intCurrIdFrom,0,0,0,'false')

	--		-- MOS 03-2018, para que si cambia el tipo de cambio las conversiones las haga al tipo de cambio guardado para informar los totales.
	--		-- HDP de Irion
	--		-- Ver **ldklfndqlfnqfln EN ESTE SP !!!
	--		IF	@soh_Currency4Total IS NOT NULL   AND
	--			@curr_id4Total		= @soh_Currency4Total
	--			BEGIN
	--				SET @intCurrIdTo   = @soh_Currency4Total
	--   				SET @decCurrIdTo   = @soh_exchange2Currency4Total
	--			END

	--	END
	--

	SELECT @strCurrIdTo = dbo.fnStrAllTrim(tc.curr_symbol)
		FROM tbsysCurrency tc											WITH (NOLOCK)
		WHERE tc.curr_id = @intCurrIdTo

	SELECT @strCurrIdFrom = dbo.fnStrAllTrim(tc.curr_symbol)
		FROM tbsysCurrency tc											WITH (NOLOCK)
		WHERE tc.curr_id = @intCurrIdFrom

	SELECT @strText1 = dbo.fnStrAllTrim(tut.utexts_desc)
		FROM tbsysUniqueTexts tut										WITH (NOLOCK)
		WHERE tut.lang_id = @lang_id AND tut.utexts_id = 166

	SELECT @strText2 = dbo.fnStrAllTrim(tut.utexts_desc)
		FROM tbsysUniqueTexts tut										WITH (NOLOCK)
		WHERE tut.lang_id = @lang_id AND tut.utexts_id = 167

--	IF @decCurrIdTo < 1
--		BEGIN
--			select @strText1 + ' ' + convert( NVARCHAR , CONVERT(DECIMAL(18,4), 1 / dbo.fnNoZDiv( @decCurrIdTo))) + ' ' + @strCurrIdTo + ' ' + @strText2 + ' ' + @strCurrIdFrom [leyenda]
--		END
--	ELSE
--		BEGIN
--			select @strText1 + ' ' + convert( NVARCHAR ,CONVERT(DECIMAL(18,4),@decCurrIdTo)) + ' ' + @strCurrIdFrom + ' ' + @strText2 + ' ' + @strCurrIdTo [leyenda]
--		END


	-- ----------------------------------------------------
	-- ----------------------------------------------------------------------------------------------------
	-- Descripción de los Items que conforman el Artículo pedido
	-- ----------------------------------------------------------------------------------------------------

	DECLARE @discounts AS NVARCHAR(4000)
	SET @discounts = ''
	SELECT @discounts = @discounts + ' ' +  tst.st_desc + ' :$ ' + convert(varchar,Convert(Decimal(19,2),dbo.fnGetExchange2(@comp_id,tsoed.total, @bra_curr_id, @bra_curr4exchange, @intCurrIdTo, @intCurrIdFrom, @decCurrIdTo,'false'))) + ' / '
	FROM tbSaleOrderExtendedDiscount tsoed
	INNER JOIN tbSalesTerms tst
	ON tst.comp_id = tsoed.comp_id AND tst.st_id = tsoed.st_id
	WHERE tsoed.comp_id = @comp_id AND tsoed.bra_id = @bra_id AND tsoed.soh_id = @soh_id

	IF @sd_id = 80 AND @page_id = 11032
		BEGIN
			DECLARE
				@message1	NVARCHAR(500),
				@message2	NVARCHAR(500),
				@message3	NVARCHAR(500),
				@message4	NVARCHAR(500)

				-- -----------------------------------------------------
				-- Titulos del Subreporte
				-- -----------------------------------------------------
				SELECT @message1 = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 960
				SELECT @message2 = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 961
				SELECT @message3 = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 962
				SELECT @message4 = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 964

				SELECT
					'' [leyenda],
					ti.item_code,
					ti.item_desc,
					sum(tic.icomp_qty * tsod.sod_qty)										[icomp_qty],
					@message1																[message1],
					@message2																[message2],
					@message3																[message3],
					@discounts																[discounts],
					@message4																[message4],
					dbo.fnGetAStock(@comp_id,tsod.stor_id, ti.item_id, tsod.sod_priority)	[StockAvailable]

				FROM  tbSaleOrderDetail tsod			WITH (NOLOCK)

				INNER JOIN tbItemComposition tic		WITH (NOLOCK)
				ON	tic.comp_id = tsod.comp_id
				AND tic.item_id = tsod.item_id

				INNER JOIN tbItem ti					WITH (NOLOCK)
				ON	ti.comp_id = tsod.comp_id
				AND ti.item_id = tic.item_id_1


				WHERE	tsod.comp_id	= @comp_id
				AND		tsod.bra_id		= @bra_id
				AND		tsod.soh_id		= @soh_id

				GROUP BY ti.item_code,
						 ti.item_desc,dbo.fnGetAStock(@comp_id,tsod.stor_id, ti.item_id, tsod.sod_priority)

				ORDER BY	ti.item_code,
							ti.item_desc



		END
	ELSE
		BEGIN
				IF @decCurrIdTo < 1
					BEGIN
						select @strText1 + ' ' + convert( NVARCHAR , CONVERT(DECIMAL(18,4), 1 / dbo.fnNoZDiv( @decCurrIdTo))) + ' ' + @strCurrIdTo + ' ' + @strText2 + ' ' + @strCurrIdFrom [leyenda],
						'' [item_code],
						'' [item_desc],
						0  [icomp_qty],
						'' [message1],
						'' [message2],
						'' [message3],
						@discounts					[discounts],
						'' [message4],
						0							[StockAvailable]

					END
				ELSE
					BEGIN
						select @strText1 + ' ' + convert( NVARCHAR ,CONVERT(DECIMAL(18,4),@decCurrIdTo)) + ' ' + @strCurrIdFrom + ' ' + @strText2 + ' ' + @strCurrIdTo [leyenda],
						'' [item_code],
						'' [item_desc],
						0  [icomp_qty],
						'' [message1],
						'' [message2],
						'' [message3],
						@discounts					[discounts],
						'' [message4],
						0							[StockAvailable]
					END
		END

-- ----------------------------------------------------------------------------------------------------

	-- ----------------------------------------------------------------------------------------------------
	--Resumen por Categoría de Cantidades del Pedido
	-- ----------------------------------------------------------------------------------------------------
	DECLARE @strResumen	NVARCHAR(4000)
	SET @strResumen = ''

	SELECT
		@strResumen =  	@strResumen + ' ' +
						CONVERT(NVARCHAR,CONVERT(DECIMAL(10,0),sum(tsod.sod_qty)))	+ ' ' +
						tc.cat_desc													+ ' / '

		From	tbSaleOrderDetail						tsod		WITH (NOLOCK)

		INNER JOIN tbItem								ti			WITH (NOLOCK)
		ON		ti.comp_id			= tsod.comp_id		AND
				ti.item_id			= tsod.item_id

		INNER JOIN tbCategory							tc			WITH (NOLOCK)
		ON		tc.comp_id			= ti.comp_id		AND
				tc.cat_id			= ti.cat_id

		WHERE	tsod.comp_id			= @comp_id
		AND		tsod.bra_id				= @bra_id
		AND		tsod.soh_id				= @soh_id


		GROUP BY tc.cat_desc

		SELECT 0 [sod_qty],@strResumen [cat_desc]


	-- ----------------------------------------------------------------------------------------------------
	-- ----------------------------------------------------------------------------------------------------



	-- ----------------------------------------------------------------------------------------------------
	-- Resumen por plan de pagos
	-- ----------------------------------------------------------------------------------------------------

	SELECT
		CASE
			--Resto Tarjeta
			WHEN tsocc.sohp_position = 6 THEN
				(SELECT
					tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE tut.lang_id = 2
					AND tut.utexts_id = 40394) + ': ' + isnull(tcc.cc_desc,'')  + ' , ' + isnull(tcclp.ccp_desc,'')

			--Resto Efectivo
			WHEN tsocc.sohp_position = 7 THEN
				(SELECT
					tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE tut.lang_id = 2
					AND tut.utexts_id = 40395) + ': ' + isnull(tcc.cc_desc,'')  + ' , ' + isnull(tcclp.ccp_desc,'')
			ELSE
				isnull(tcc.cc_desc,'')  + ' , ' + isnull(tcclp.ccp_desc,'')
		END 																	[sohp_desc],
		isnull(tsocc.sohp_total,0)												[sohp_total],
		(SELECT
					tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE tut.lang_id = 2
					AND tut.utexts_id = 40396)									[sohp_tittle] -- Plan de Pagos: , lo paso por aca pq no hay mas rptcolumns y rptmessage no lo muestra
		FROM tbSaleOrderCreditCards			tsocc	WITH (NOLOCK)

		left JOIN tbSaleOrderHeader			tsoh	WITH (NOLOCK)
		ON	tsoh.comp_id	= tsocc.comp_id
		AND tsoh.bra_id		= tsocc.bra_id
		AND tsoh.soh_id		= tsocc.soh_id

		LEFT JOIN tbCreditCard				tcc		WITH (NOLOCK)
		ON	tcc.comp_id		= tsocc.comp_id
		AND tcc.cc_id		= tsocc.cc_id

		LEFT JOIN tbCreditCardLoanPlan		tcclp	WITH (NOLOCK)
		ON	tcclp.comp_id	= tsocc.comp_id
		AND tcclp.cc_id		= tsocc.cc_id
		AND tcclp.ccp_id	= tsocc.ccp_id

		WHERE	tsocc.comp_id				= @comp_id
		AND		tsocc.bra_id				= @bra_id
		AND		tsocc.soh_id				= @soh_id
		AND		tsocc.sohp_total			<> 0

		ORDER BY tsocc.sohp_position

	-- ----------------------------------------------------------------------------------------------------
	-- ----------------------------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------------------------------------
	--Resumen por Impuestos tbSaleOrderTaxes
	-- ----------------------------------------------------------------------------------------------------

	SELECT
		SUM(tsot.tm_total)							[tm_total],
		ttn.tax_desc								[tax_desc],
		-- MOS 09-2022: Impuestos en Moneda de Impresión
		dbo.fnGetExchange2(@comp_id, SUM(tsot.tm_total) ,@bra_curr_id,@curr_id4Total ,
						   @intCurrIdTo ,@intCurrIdFrom, @decCurrIdTo, 'FALSE')	[tm_totalinBranchCurrency]
		From	tbSaleOrderTaxes 						tsot		WITH (NOLOCK)
		INNER JOIN tbTaxName							ttn			WITH (NOLOCK)
			ON	ttn.comp_id					= tsot.comp_id	AND
				ttn.tax_id					= tsot.tax_id
		WHERE	tsot.comp_id		= @comp_id		AND
				tsot.bra_id			= @bra_id		AND
				tsot.soh_id			= @soh_id
		GROUP BY	tsot.tax_id,
					ttn.tax_desc,
					ttn.tax_class
		ORDER BY ttn.tax_class

	-- ----------------------------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------------------------------------
	--Resumen por Impuestos tbSaleOrderTaxes  con condicion de moneda
	-- ----------------------------------------------------------------------------------------------------
	/*
	SELECT
		--SUM(tsot.tm_total)			[tm_total],


		CASE
				WHEN df.df_SaleOrder_printForceCurrency4Items = 1 THEN

						dbo.fnGetExchange2(	@comp_id,
											SUM(tsot.tm_total),
											SOD.[curr_id],
											ISNULL(df.df_SaleOrderEnableCurrency4Total,BR.curr_id) , --
											@intCurrIdTo ,
											@intCurrIdFrom,
											@decCurrIdTo,
											'FALSE')

				ELSE
						SUM(tsot.tm_total)
			END										[tm_total],





		ttn.tax_desc								[tax_desc]

		From	tbSaleOrderTaxes 						tsot		WITH (NOLOCK)

		INNER JOIN tbTaxName							ttn			WITH (NOLOCK)
			ON	ttn.comp_id					= tsot.comp_id	AND
				ttn.tax_id					= tsot.tax_id

		INNER JOIN tbSaleOrderHeader					tsoh		WITH (NOLOCK)
			ON  tsoh.comp_id				= tsot.comp_id
			AND tsoh.bra_id					= tsot.bra_id
			AND	tsoh.soh_id					= tsot.soh_id

		INNER Join tbSaleOrderDetail	SOD							WITH (NOLOCK)
			on  SOD.[comp_id]				= tsoh.[comp_id]
			and SOD.[bra_id]				= tsoh.[bra_id]
			and SOD.[soh_id]				= tsoh.[soh_id]

		INNER Join tbDocumentsFile		DF							WITH (NOLOCK)
			on  DF.[comp_id]				= tsoh.[comp_id]
			and DF.[df_id]					= tsoh.[df_id]

		INNER Join tbBranch				BR							WITH (NOLOCK)
			on  BR.[comp_id]				= SOD.[comp_id]
			and BR.[bra_id]					= SOD.[bra_id]


		WHERE	tsot.comp_id		= @comp_id		AND
				tsot.bra_id			= @bra_id		AND
				tsot.soh_id			= @soh_id
		GROUP BY	tsot.tax_id,
					ttn.tax_desc,
					ttn.tax_class,
					df_SaleOrder_printForceCurrency4Items,
					SOD.[curr_id] ,df.df_SaleOrderEnableCurrency4Total,BR.curr_id
		ORDER BY ttn.tax_class
		*/
	-- ----------------------------------------------------------------------------------------------------





END
GO


