CREATE  PROCEDURE [dbo].[spSaleOrderHeader_insertData]
(
	@comp_id			int,
	@bra_id				int,
	@soh_id				int,
	@soh_cd             datetime,
	@soh_deliveryDate   datetime,
	@soh_observation1	varchar(350),
	@soh_observation2	varchar(350),
	@soh_observation3	varchar(350),
	@soh_observation4	varchar(350),
	@soh_quotation      bit,
	@sm_id				int,
	@cust_id			int,
	@st_id				int,
	@disc_id			int,
	@dl_id				int,
	@cb_id				int,
	@soh_lastUpdate		datetime,
	@soh_limitDate		datetime,
	@tt_id				int,
	@tt_class			varchar,
	@soh_StatusOf		int,
	@user_id			int,
	@soh_isEditing		bit,
	@soh_isEditingCd    datetime,
	@soh_Total			DECIMAL(19,6),
	@df_id				int,
	@ssos_id			INT,
	@ExchangeToCustomerCurrency AS FLOAT, -- --MOS 01-2024: No se x q MIERDA no graba mas decimales como SI lo hace el sp spSaleOrder_updateCurrExchange que tiene la MISMA cantidad y pasa el MISMO valor...  DECIMAL(38,27),
	@customerCurrencyId AS INT)

as

BEGIN

	--declare @datetime	datetime
	--select	@datetime = getdate()

	SET @soh_lastUpdate = GETDATE()
	SET @soh_cd			= GETDATE()
	--CUSTOM_GN_001

	insert into dbo.tbSaleOrderHeader	WITH (ROWLOCK)
	(	comp_id			,bra_id,
		soh_id			,soh_cd,
		soh_deliveryDate,soh_observation1,
		soh_observation2,soh_observation3,
		soh_observation4,soh_quotation,
		sm_id,cust_id	,st_id,disc_id,
	    dl_id,cb_id		,soh_lastUpdate,
	    soh_limitDate	,tt_id,
	    tt_class		,soh_StatusOf,
	    USER_ID			,soh_isEditing,
	    soh_isEditingCd	,soh_Total,
	    df_id			,ssos_id,
	    soh_ExchangeToCustomerCurrency,soh_CustomerCurrency)

	values
	(   @comp_id		,@bra_id,
		@soh_id,@soh_cd	,@soh_deliveryDate,
		@soh_observation1,@soh_observation2,
		@soh_observation3,@soh_observation4,
		@soh_quotation	,@sm_id,
		@cust_id		,@st_id,
		@disc_id		,@dl_id,
		@cb_id			,@soh_lastUpdate,
		@soh_limitDate	,@tt_id,
		@tt_class		,@soh_StatusOf,
		@user_id		,@soh_isEditing,
		@soh_isEditingCd,@soh_Total,
		@df_id			,@ssos_id,
		@ExchangeToCustomerCurrency,@customerCurrencyId)

	-- Actualiza Estados a Verificar Según condicion de venta
	EXEC spSaleOrderStatus_InsertUpdateData @comp_id ,
												@bra_id ,
												--@st_id ,
												@soh_id

END





GO




