-- ======================================================================
-- Author:		MOS
-- Create date: 26/07/2011
-- Description:	Generacion de abonos mensuales--wfmMonthlyPayments
-- ======================================================================

CREATE PROCEDURE [dbo].[spSaleOrderHeader_MonthlyPayments]
(

	@comp_id	int,
	@lang_id	int,
	@bra_id		int,
	@df_id		int,
	@Note1		nvarchar(50),
	@Note2		nvarchar(50),
	@intMonth	INT,
	@date		datetime

)
as

BEGIN

	-- -------------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------------
	/*
		declare  	@comp_id int,
					@lang_id int,
					@bra_id  int,
					@df_id	 int,
					@Note1   nvarchar(50),
					@Note2   nvarchar(50)



		select   	@comp_id =1,
					@lang_id = 2,
					@bra_id  =1,
					@df_id	 =96,
					@Note1   ='Correspondiente',
					@Note2   ='AGOSTO'
	*/
	-- -------------------------------------------------------------------------------------

	SET DATEFORMAT 'ymd'




	declare @lsoh_id				as INT
	declare @ldf_id_new				as	INT
	declare @lbra_processingDate	as DATETIME
	declare @lsoh_id_new			as int
	declare @return_value			as int
	declare @errormessage			as varchar(200)
	declare @message				as varchar(50)
	DECLARE @intStor_Id				AS INT
	DECLARE @datGenerationDate		AS DATETIME
	DECLARE @intCustId				AS INT
	DECLARE @bitPreparationEnabled	AS bit




	-- Selecciona el Deposito a Utiulizar
	SELECT @intStor_Id			= tb.stor_id,
		   @lbra_processingDate = tb.bra_processingDate
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id

	/*Proc Date + 365*/
	declare @ldateLimit as DATETIME
	set @ldateLimit = dateadd(day,365,@date)
    set @lbra_processingDate = @date
	--------------------------------

	SET @datGenerationDate = CONVERT(DATETIME,
									CONVERT(VARCHAR(4),YEAR(@lbra_processingDate)) + '-' +
									CONVERT(VARCHAR(2),@intMonth) + '-' +
									'01'
									)


	set @return_value = 0
	set @errormessage = (select tut.utexts_desc FROM tbsysUniqueTexts tut
												WHERE tut.lang_id   = @lang_id
												AND   tut.utexts_id = 20415)

	set @message = (select tut.utexts_desc FROM tbsysUniqueTexts tut
												WHERE tut.lang_id   = @lang_id
												AND   tut.utexts_id = 20417)

	set @message = convert(varchar,@message) + ' ' +  convert(varchar,@Note2)

	DECLARE	@dfmp_putInterest		AS BIT
	DECLARE @item_id4interest		AS INT
	DECLARE @dfmp_interestPercent	AS DECIMAL(10,2)
	DECLARE @user_id4interest		AS INT
	DECLARE @cust_id				AS INT
	DECLARE @bra_processingDate		AS DATETIME
	DECLARE @curr_id				AS INT
	DECLARE @dfmp_minBalance4interest AS DECIMAL(19,2)

	declare cursor_SaleorderHeader CURSOR LOCAL FAST_FORWARD FOR
			select tb.bra_processingDate,
				   tsoh.soh_id,
				   tdfmp.df_id_mp,
				   IsNull(tdf.df_SaleOrderEnablePreparation,'False'),
				   ISNULL(tdfmp.dfmp_putInterest,'False')				[dfmp_putInterest],
				   tdfmp.item_id4interest,
				   tdfmp.dfmp_interestPercent,
				   tdfmp.user_id4interest,
				   tsoh.cust_id,
				   tb.curr_id,
				   tb.bra_processingDate,
				   ISNULL(tdfmp.dfmp_minBalance4interest,0)				[dfmp_minBalance4interest]
				FROM tbSaleOrderHeader											tsoh		WITH (NOLOCK)
					inner join tbDocumentsFile4MonthlyPayments					tdfmp		WITH (NOLOCK)
					on		tdfmp.comp_id		= tsoh.comp_id and
							tdfmp.df_id			= tsoh.df_id
					INNER JOIN tbDocumentsFile									tdf			WITH (NOLOCK)
						ON tdf.df_id = tdfmp.df_id_mp
					inner join tbBranch											tb			WITH (NOLOCK)
						on	tb.comp_id			= tsoh.comp_id and
							tb.bra_id			= tsoh.bra_id
					INNER JOIN tbCustomer										tc			WITH (NOLOCK)
						ON		tc.comp_id = tsoh.comp_id
							AND tc.cust_id = tsoh.cust_id
				WHERE	tsoh.comp_id			= @comp_id
				AND     tsoh.bra_id				= @bra_id
				AND		tsoh.df_id				= @df_id
				AND		IsNull(tsoh.soh_deliveryDate,@lbra_processingDate) <= @lbra_processingDate
				AND		IsNull(tc.cust_inactive,'False') = 'False'
				AND		(tsoh.ssos_id <> 5 AND tsoh.ssos_id <> 10)  -- No sea WEB ni este en area Comercial!!!
				--  Mira que adentro tenga algo valido para la fecha de generacion.
				AND      EXISTS(
									SELECT TOP 1 1
										FROM tbSaleOrderDetail tsod		WITH (NOLOCK)
										WHERE	tsod.comp_id	= tsoh.comp_id AND
												tsod.bra_id		= tsoh.bra_id AND
												tsod.soh_id		= tsoh.soh_id AND
												@datGenerationDate BETWEEN  tsod.sod_montlyPaymentFrom AND tsod.sod_montlyPaymentTo
								)

			open	cursor_SaleorderHeader

			FETCH	cursor_SaleorderHeader
				INTO	@lbra_processingDate,
						@lsoh_id,
						@ldf_id_new,
						@bitPreparationEnabled,
						@dfmp_putInterest,
						@item_id4interest,
						@dfmp_interestPercent,
						@user_id4interest,
						@cust_id,
						@curr_id,
						@bra_processingDate	,
						@dfmp_minBalance4interest


			WHILE @@fetch_status = 0
			BEGIN

				-- Si ya se genero para el mes del año en curso, no lo vuelve a generar
				IF EXISTS(	SELECT 1
								FROM tbSaleOrderMontlyPaymentsGenerationHistory tsompgh		WITH (NOLOCK)
				          		WHERE	tsompgh.comp_id = @comp_id
				          			AND tsompgh.bra_id	= @bra_id
				          			AND tsompgh.soh_id	= @lsoh_id
				          			AND tsompgh.ma_cd	= @datGenerationDate)
					BEGIN
						--FETCH	cursor_SaleorderHeader INTO @lbra_processingDate,@lsoh_id,@ldf_id_new,@bitPreparationEnabled
						FETCH	cursor_SaleorderHeader
							INTO	@lbra_processingDate,
									@lsoh_id,
									@ldf_id_new,
									@bitPreparationEnabled,
									@dfmp_putInterest,
									@item_id4interest,
									@dfmp_interestPercent,
									@user_id4interest,
									@cust_id,
									@curr_id,
									@bra_processingDate	,
									@dfmp_minBalance4interest
						CONTINUE
					END




			-- ----------------------------------------------------------------------------------------------------------
			-- Por si hay algun error en la tabla de contadores busca un hueco para insertar la SO
			-- ----------------------------------------------------------------------------------------------------------
			WHILE 1 = 1
				BEGIN
					EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @lsoh_id_new Output
					IF EXISTS(
								SELECT 1
									FROM tbSaleOrderHeader tsoh		WITH (NOLOCK)
									WHERE	tsoh.comp_id	= @comp_id	AND
											tsoh.bra_id		= @bra_id	AND
											tsoh.soh_id		= @lsoh_id_new
							 )
							OR
						EXISTS(
								SELECT 1
									FROM tbSaleOrderMontlyPaymentsGenerationHistory
									WHERE	comp_id			= @comp_id AND
											bra_id			= @bra_id AND
											soh_id			= @lsoh_id_new
							  )
						BEGIN
							CONTINUE
						END
					ELSE
						BEGIN
							BREAK
						END
				END
			-- ----------------------------------------------------------------------------------------------------------


				-- NO FORRO, ESTO ES MIERDA !!!!
				-- MOS, 5-2018
				--EXEC spCounters_getNextValue
				--							@comp_id = @comp_id,
				--							@auxiliary_id = @intStor_Id,
				--							@counter_id = 1,
				--							@counter_value = @lsoh_id_new OUTPUT



				if @lsoh_id is NOT NULL
					begin

						insert into tbSaleOrderHeader
						(
											comp_id,bra_id,soh_id,soh_cd,soh_deliveryDate,soh_observation1,
											soh_observation2,soh_observation3,soh_observation4,soh_quotation,
											sm_id,cust_id,st_id,disc_id,dl_id,cb_id,soh_lastUpdate,soh_limitDate,
											tt_id,tt_class,soh_StatusOf,user_id,soh_isEditing,soh_isEditingCd,
											df_id,soh_total,
											ssos_id,
											soh_ExchangeToCustomerCurrency,chp_id,
											soh_PL_df_Id,soh_CustomerCurrency,soh_WithCollection,soh_WithCollectionGUID,
											soh_discount,soh_loan,soh_packagesQty,soh_internalAnnotation,curr_id4Exchange,
											curr_idExchange,soh_ATotal,df_id4PL,somp_id

						)
						select				comp_id,bra_id,@lsoh_id_new,@lbra_processingDate,@lbra_processingDate,soh_observation1,
											soh_observation2,soh_observation3,soh_observation4,soh_quotation,
											sm_id,cust_id,st_id,disc_id,dl_id,cb_id,soh_lastUpdate,@ldateLimit,
											tt_id,tt_class,soh_StatusOf,user_id,soh_isEditing,soh_isEditingCd,
											@ldf_id_new,soh_total,
											CASE
												WHEN @bitPreparationEnabled = 'False' OR 1 = 1 THEN 50
												ELSE ssos_id
											end ,
											soh_ExchangeToCustomerCurrency,chp_id,
											soh_PL_df_Id,soh_CustomerCurrency,soh_WithCollection,soh_WithCollectionGUID,
											soh_discount,soh_loan,soh_packagesQty,soh_internalAnnotation,curr_id4Exchange,
											curr_idExchange,soh_ATotal,df_id4PL,somp_id



							from tbSaleOrderHeader						tsoh		WITH (NOLOCK)
						WHERE	tsoh.comp_id	= @comp_id AND
								tsoh.soh_id		= @lsoh_id AND
								tsoh.bra_id		= @bra_id


						insert into tbSaleOrderDetail
						(
										comp_id,
										bra_id,
										soh_id,
										sod_priority,
										item_id,
										sod_itemDesc,
										sod_detail,
										curr_id,
										sod_initQty,
										sod_qty,
										prli_id,
										sod_price,
										stor_id,
										sod_lastUpdate,
										sod_isEditing,
										sod_insertDate,
										user_id,
										sod_quotation,
										sod_isCredit,
										sod_cost,
										sod_costTax,
										rmah_id,
										rmad_id,
										sod_note1,
										sod_note2,
										sod_itemDiscount,
										sod_tis_id_origin,
										sod_item_id_origin,
										sod_isParentAssociate,
										is_id,
										it_transaction,
										sod_isMade
						)
						select 			comp_id,
										bra_id,
										@lsoh_id_new,
										sod_priority,
										item_id,
										dbo.fnStrAllTrim(convert(NVARCHAR(250),sod_itemDesc)) + ' -> ' + dbo.fnStrAllTrim( convert(VARCHAR(100),ISNULL(@Note1,''))) ,
										sod_detail,
										curr_id,
										sod_initQty,
										sod_qty,
										prli_id,
										sod_price,
										stor_id,
										sod_lastUpdate,
										sod_isEditing,
										sod_insertDate,
										user_id,
										sod_quotation,
										sod_isCredit,
										sod_cost,
										sod_costTax,
										rmah_id,rmad_id,
										tsod.sod_note1,
										tsod.sod_note2,
										sod_itemDiscount,
										sod_tis_id_origin,
										sod_item_id_origin,
										sod_isParentAssociate,
										is_id,
										it_transaction,
										sod_isMade

						from tbSaleOrderDetail tsod			WITH (NOLOCK)
						where	tsod.soh_id		= @lsoh_id	AND
								tsod.bra_id		= @bra_id	AND
								tsod.comp_id	= @comp_id	AND
								@datGenerationDate BETWEEN  tsod.sod_montlyPaymentFrom AND tsod.sod_montlyPaymentTo
						ORDER BY tsod.sod_id

						set @return_value = 1
						set @errormessage = (select tut.utexts_desc
												FROM tbsysUniqueTexts tut
												WHERE tut.lang_id   = @lang_id
												AND   tut.utexts_id = 20416)

						SELECT @intCustId = tsompgh.cust_id
									FROM tbSaleOrderHeader tsompgh
				          			WHERE	tsompgh.comp_id = @comp_id
				          				AND tsompgh.bra_id	= @bra_id
				          				AND tsompgh.soh_id	= @lsoh_id


						INSERT INTO tbSaleOrderMontlyPaymentsGenerationHistory
						(
							comp_id,
							bra_id,
							soh_id,
							ma_cd,
							cust_id
						)
						VALUES
						(
							@comp_id,
							@bra_id,
							@lsoh_id,
							@datGenerationDate,
							@intCustId
						)



					end

					-- ------------------------------------------------------------------------------------------------------------------
					-- Verifica si el cliente tiene saldos Vencidos y si debe agregar un item por Saldo Vencido al final del pedido.
					-- ------------------------------------------------------------------------------------------------------------------
					IF @dfmp_putInterest = 'True'
						BEGIN
							DECLARE @decSaldoVencido AS DECIMAL(19,2)
							DECLARE @decSaldoTotal   AS DECIMAL(19,2)
							DECLARE @strLeyenda		 AS NVARCHAR(200)
							SELECT  @decSaldoVencido = fcgbs.cust_credit_balance_OverCome,
									@decSaldoTotal   = fcgbs.cust_credit_balance

								FROM dbo.fnCustomer_getBalanceStatus(@comp_id,@curr_id,@cust_id,@user_id4interest,@bra_processingDate, @bra_id,-4) fcgbs
							IF	@decSaldoVencido > 0				AND
								@decSaldoTotal > 0					AND
								@item_id4interest IS NOT NULL		AND
								@decSaldoVencido > @dfmp_minBalance4interest
								BEGIN

									SELECT @strLeyenda = ti.item_desc
										FROM tbItem ti	WITH (NOLOCK)
											WHERE	ti.comp_id = @comp_id			AND
													ti.item_id = @item_id4interest

									insert into tbSaleOrderDetail
									(
													comp_id,
													bra_id,
													soh_id,
													sod_priority,
													item_id,
													sod_itemDesc,
													sod_detail,
													curr_id,
													sod_initQty,
													sod_qty,
													prli_id,
													sod_price,
													stor_id,
													sod_lastUpdate,
													sod_isEditing,
													sod_insertDate,
													user_id,
													sod_quotation,
													sod_isCredit,
													sod_cost,
													sod_costTax,
													rmah_id,
													rmad_id,
													sod_note1,
													sod_note2,
													sod_itemDiscount,
													sod_tis_id_origin,
													sod_item_id_origin,
													sod_isParentAssociate,
													is_id,
													it_transaction,
													sod_isMade
									)
									select 			TOP 1
													comp_id,
													bra_id,
													@lsoh_id_new,
													sod_priority,
													@item_id4interest ,
													@strLeyenda ,
													'',
													@curr_id,
													1,
													1,
													prli_id,
													round(@decSaldoVencido * @dfmp_interestPercent / 100,0)  ,
													stor_id,
													sod_lastUpdate,
													sod_isEditing,
													sod_insertDate,
													user_id,
													sod_quotation,
													sod_isCredit,
													sod_cost,
													sod_costTax,
													rmah_id,rmad_id,
													tsod.sod_note1,
													tsod.sod_note2,
													0,
													sod_tis_id_origin,
													sod_item_id_origin,
													sod_isParentAssociate,
													is_id,
													it_transaction,
													'False'

									from tbSaleOrderDetail tsod			WITH (NOLOCK)
									where	tsod.soh_id		= @lsoh_id	AND
											tsod.bra_id		= @bra_id	AND
											tsod.comp_id	= @comp_id

								END

						END
					-- ------------------------------------------------------------------------------------------------------------------




					--FETCH	cursor_SaleorderHeader INTO @lbra_processingDate,@lsoh_id,@ldf_id_new,@bitPreparationEnabled
					FETCH	cursor_SaleorderHeader
						INTO	@lbra_processingDate,
								@lsoh_id,
								@ldf_id_new,
								@bitPreparationEnabled,
								@dfmp_putInterest,
								@item_id4interest,
								@dfmp_interestPercent,
								@user_id4interest,
								@cust_id,
								@curr_id,
								@bra_processingDate,
								@dfmp_minBalance4interest



			END

			CLOSE cursor_SaleorderHeader
			DEALLOCATE cursor_SaleorderHeader


--		-- Actualiza la leyenda agregandole el mes de generacion atras de la descripcion.-
--		UPDATE tbSaleOrderDetail
--			SET
--			sod_itemDesc = convert(varchar,sod_itemDesc) + ' -> ' +  convert(varchar,ISNULL(@Note2,''))
--			WHERE soh_id = @lsoh_id_new AND bra_id = @bra_id
--


		SELECT @return_value [Value], @errormessage [Error]







END
GO


CREATE PROCEDURE [dbo].[spSaleOrderHeader_PurchaseOrderRelation_deleteData]
(
	@comp_id	INT,
	@posor_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- MOS 06-2021 x C Muebles
		UPDATE tbTempItemStock
			SET
				tis_exclude4AvailableStock = 0,
				tis_pending4pod_IdRelation = 0
			FROM tbTempItemStock									tmp		WITH (NOLOCK)
			INNER JOIN tbSaleOrderHeader_PurchaseOrderRelation AS	tsohpor WITH (NOLOCK)
				ON	tsohpor.comp_id  = @comp_id		AND
					tsohpor.posor_id = @posor_id	AND
					tsohpor.tis_id	 = tmp.tis_id


		DELETE FROM tbSaleOrderHeader_PurchaseOrderRelation
			WHERE	comp_id		= @comp_id AND
					posor_id	= @posor_id
	END
GO


CREATE  PROCEDURE [dbo].[spSaleOrderHeader_PurchaseOrderRelation_GetData4SaleOrderItemAssociation]
(
	@comp_id	INT,
	@bra_id		INT,
	@user_id	INT,
	@prof_id	INT,
	@tis_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- -------------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@user_id	INT,
				@prof_id	INT,
				@tis_id		INT

			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@user_id	= 1,
				@prof_id	= 1,
				@tis_id		= 51627
		*/
		-- -------------------------------------------------------------

		-- ------------------------------------------------------------------------------------------------------
		-- POR TIS ID BUSCO EN TEMP ITEM STOCK
		-- CON ESTO SE SI TIENE O NO UN SOD CARGADO
		-- ------------------------------------------------------------------------------------------------------
			DECLARE
				@lsod_id	INT,
				@litem_id	INT,
				@lqty		INT
			--SOD ITEM ID
			SELECT
				@lsod_id	= ttis.sod_id,
				@litem_id	= ttis.item_id,
				@lqty		= ttis.tis_qty
				FROM tbTempItemStock AS ttis	WITH(NOLOCK)
				WHERE	ttis.comp_id = @comp_id AND
						ttis.tis_id  = @tis_id


--==
	--SELECT
	--	@lsod_id	[lSOD_ID],
	--	@litem_id	[LITEM_ID],
	--	@lqty		[LQTY]
--==

		-- ------------------------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------------------------
		-- AHORA RECUPERO LOS DATOS DE LA TABLA DE RELACIONES
		-- SI EL SOD NO ES NULL TENGO QUE BUSCAR SI ESTA METIDO O NO EL TIS ID
		-- TABLA TEMPORAL EN LA QUE VOY A TIRAR EN BASE AL SOD SI TIENE UN POD RELACIONADO PARA PODER JOINEAR
		-- ------------------------------------------------------------------------------------------------------
			DECLARE @tblRelatedPOD TABLE (
											comp_id		INT,
											posor_id	INT,
											sod_id		INT,
											poh_id		INT,
											pod_id		INT
										 )
			INSERT INTO @tblRelatedPOD
			(
				comp_id,
				sod_id,
				posor_id,
				poh_id,
				pod_id
			)
			SELECT
				tsohpor.comp_id,
				tsohpor.so_sod_id,
				tsohpor.posor_id,
				tsohpor.po_poh_id,
				tsohpor.po_pod_id
				FROM	tbSaleOrderHeader_PurchaseOrderRelation AS tsohpor	WITH(NOLOCK)
				WHERE	tsohpor.comp_id		= @comp_id AND
						(
							tsohpor.so_sod_id	= @lsod_id OR
							tsohpor.tis_id		= @tis_id
						)



--==
	--SELECT '@tblRelatedPOD',* FROM @tblRelatedPOD
	--SELECT * FROM @tblRelatedPOD
--==

		-- ------------------------------------------------------------------------------------------------------


		-- ------------------------------------------------------------------------------------------------------
		-- ACA TENGO QUE RECUPERAR CUANTOS ARTICULOS DISPONIBLES QUEDAN PARA CADA POD
		-- EN BASE A CUANTOS TENGO ASOCIADOS EN LA TABAL DE RELACIONES
		-- TODO ESTO SE PUEDE MEJORAR PREGUNTAR A MOS PORQUE CREO QUE HICE MUCHA VUELTA AL PEDO
		-- ------------------------------------------------------------------------------------------------------

			DECLARE @tblAvailableQtys4PurchaseOrder TABLE (
															comp_id		INT,
															poh_id		INT,
															pod_id		INT,
															qty			INT
														  )

			--PODRIA RECUPERAR PRIMERO TODOS LOS POH Y POD PARA UN ITEM EN PARTICULAR
			INSERT INTO @tblAvailableQtys4PurchaseOrder
			(
				comp_id,
				poh_id,
				pod_id,
				qty
			)
			SELECT DISTINCT
				tpod.comp_id,
				tpod.poh_id,
				tpod.pod_id,
				tpod.pod_qty
				FROM tbPurchaseOrderDetail							AS tpod		WITH(NOLOCK)
				INNER JOIN tbPurchaseOrderHeader					AS tpoh		WITH(NOLOCK)
				ON	tpoh.comp_id		= tpod.comp_id				AND
					tpoh.poh_id			= tpod.poh_id
				INNER JOIN tbSaleOrderHeader_PurchaseOrderRelation	AS tsohpor	WITH(NOLOCK)
				ON	tsohpor.comp_id		= tpod.comp_id				AND
					tsohpor.po_poh_id	= tpod.poh_id				AND
					tsohpor.po_pod_id	= tpod.pod_id
				WHERE	tpod.comp_id			= @comp_id			AND
						tpod.pod_isProcessed	= 'False'			AND
						tpoh.poh_quotation		= 'False'			AND
						tpod.item_id			= @litem_id


			--==
			--	SELECT '@tblAvailableQtys4PurchaseOrder' [TABLE], * FROM @tblAvailableQtys4PurchaseOrder
			--==

			--ACA DEJO GUARDADO EL DISPONIBLE EN CASO DE QUE TENGA ASOCIADOS REGISTROS
			DECLARE @tblAvailableQtys4PurchaseOrderMinusSaleOrder TABLE (
																			comp_id			INT,
																			poh_id			INT,
																			pod_id			INT,
																			QtyAvailable	INT
																		)
			INSERT INTO @tblAvailableQtys4PurchaseOrderMinusSaleOrder
			(
				comp_id,
				poh_id,
				pod_id,
				QtyAvailable
			)
			SELECT
				tmp.comp_id,
				tmp.poh_id,
				tmp.pod_id,
				tmp.qty - SUM( ISNULL(TTIS2.tis_qty,ISNULL(ttis.tis_qty,ISNULL(tsod.sod_qty,0)))) 			[TotalAvailable]
				--tmp.qty - SUM(ISNULL(ttis.tis_qty,ISNULL(tsod.sod_qty,0))) 			[TotalAvailable]
				FROM @tblAvailableQtys4PurchaseOrder				tmp
				INNER JOIN tbSaleOrderHeader_PurchaseOrderRelation	AS tsohpor	WITH(NOLOCK)	-- Todas las OC YA Relacionadas
					ON	(
							tsohpor.comp_id		= tmp.comp_id	AND
							tsohpor.po_poh_id	= tmp.poh_id	AND
							tsohpor.po_pod_id	= tmp.pod_id
						)
						--	OR
						--tsohpor.tis_id = @tis_id

				LEFT JOIN tbSaleOrderDetail						AS tsod		WITH(NOLOCK)
					ON	tsod.comp_id	= tsohpor.comp_id AND
						tsod.soh_id		= tsohpor.so_soh_id AND
						tsod.sod_id		= tsohpor.so_sod_id

				LEFT JOIN tbTempItemStock						AS ttis		WITH(NOLOCK)
					ON	ttis.comp_id	= tsohpor.comp_id			AND
						ttis.bra_id		= tsohpor.so_bra_id			AND
						ttis.soh_id		= tsohpor.so_soh_id			AND
						ttis.sod_id		= tsohpor.so_sod_id
				LEFT JOIN tbTempItemStock						AS ttis2	WITH(NOLOCK)
					ON	ttis2.comp_id	= tsohpor.comp_id			AND
						ttis2.tis_id		= tsohpor.tis_id
				GROUP BY tmp.comp_id, tmp.poh_id, tmp.pod_id, tmp.qty--, ttis.tis_qty







--==
	--SELECT '@tblAvailableQtys4PurchaseOrderMinusSaleOrder' [TABLA], * FROM @tblAvailableQtys4PurchaseOrderMinusSaleOrder
--==

		-- ------------------------------------------------------------------------------------------------------

		-- ------------------------------------------------------------------------------------------------------
		-- SI ENCONTRO UN REGISTRO, ENTONCES NO VA A PODER INSERTAR NINGUNA RELACION
		-- ------------------------------------------------------------------------------------------------------
			DECLARE @bitCanInsert	BIT = 'True'
			IF (SELECT COUNT(*) FROM @tblRelatedPOD) > 0
				BEGIN
					SET @bitCanInsert = 'False'
				END
		-- ------------------------------------------------------------------------------------------------------


--==
	--SELECT '@tblRelatedPOD',* FROM @tblRelatedPOD
--==

			--	BEGIN
					--SI EXISTE ENTONCES TRAIGO EL REGISTRO PARA QUE LO PUEDA BORRAR
					--MUESTRO TODAS LAS PO DISPONIBLES, PERO NINGUNA VA A TENER BOTON VERDE DISPONIBLE Y LA QUE MATCHEE POR POH_ID y POD_ID ES LA QUE VA A TENER EL BOTON ROJO HABILITADO

		SELECT
			@bitCanInsert										[BOTON VERDE 1],
			CONVERT(VARCHAR,tpod.poh_id) + '|' +
			CONVERT(VARCHAR,tpod.pod_id) + '|' +
			CONVERT(VARCHAR,tpod.bra_id) 						[BOTON VERDE 2],
			''													[BOTON ROJO],
			tpod.poh_id,
			--tpod.pod_id,
			ts.supp_name,
			--tpod.item_id,
			ti.item_code,
			ti.item_desc,
			--CONVERT(DECIMAL(19,2),
			--CASE
			--	WHEN tmpPOMinusSO.comp_id IS NULL THEN	tpod.pod_qty
			--ELSE										tmpPOMinusSO.QtyAvailable
			--END)													[AvailableQty],
			ISNULL(tmpPOMinusSO.QtyAvailable,tpod.pod_qty)			[AvailableQty],
			CONVERT(DECIMAL(19,2),tpod.pod_qty,2)									[TotalQTY],
			CASE
				WHEN tpod.pod_isProcessed = 'True' THEN 'RECIBIDA'
				ELSE ''
			END																		[Status],
			tpoh.poh_estDeliveryDate,



			--  NO CAMBIAR ORDENES DESPUES DE ESTE BOTON ! ! !
			CASE
				WHEN ISNULL(tmpPOMinusSO.QtyAvailable,tpod.pod_qty) 	>= @lqty THEN	1
				ELSE																	0
			END																		[isAvailable4Relation],		-- Count - 1
			tmp.posor_id															[ID DE RELACION] --SI TIENE UN ID PUEDE BORRAR, SINO NO
			FROM tbPurchaseOrderHeader							AS tpoh	WITH(NOLOCK)
			INNER JOIN tbPurchaseOrderDetail					AS tpod WITH(NOLOCK)
			ON	tpod.comp_id		= tpoh.comp_id				AND
				tpod.bra_id			= tpoh.bra_id				AND
				tpod.poh_id			= tpoh.poh_id
			INNER JOIN tbSupplier								AS ts	WITH(NOLOCK)
			ON	ts.comp_id			= tpoh.comp_id				AND
				ts.supp_id			= tpoh.supp_id
			INNER JOIN tbItem									AS ti	WITH(NOLOCK)
			ON	ti.comp_id			= tpod.comp_id				AND
				ti.item_id			= tpod.item_id
			LEFT JOIN @tblRelatedPOD							tmp
			ON	tmp.comp_id				= tpod.comp_id				AND
				tmp.poh_id				= tpod.poh_id				AND
				tmp.pod_id				= tpod.pod_id
			LEFT JOIN @tblAvailableQtys4PurchaseOrderMinusSaleOrder	tmpPOMinusSO
			ON	tmpPOMinusSO.comp_id	= tpod.comp_id				AND
				tmpPOMinusSO.poh_id		= tpod.poh_id				AND
				tmpPOMinusSO.pod_id		= tpod.pod_id

			-- MOS 07-2022** para que si una OC ya fue recibida se siga viendo como para poder anularla   Relaciona las OC y ESTE RENGLON de Pedidos
			LEFT JOIN tbSaleOrderHeader_PurchaseOrderRelation	AS tsohpor	WITH(NOLOCK)
			ON	tsohpor.comp_id		= tpod.comp_id				AND
				tsohpor.po_poh_id	= tpod.poh_id				AND
				tsohpor.po_pod_id	= tpod.pod_id				AND
				tsohpor.comp_id		= tmp.comp_id				AND
				tsohpor.so_sod_id	= tmp.sod_id

			WHERE	tpoh.comp_id						= @comp_id	AND
					(
						tpod.pod_isProcessed				= 'False'
						OR
						tsohpor.comp_id IS NOT NULL	-- MOS 07-2022:** CM: para que pueda ANULAR una OC ya recibida que esta relacionada.
					)
					AND
					tpoh.poh_quotation					= 'False'	AND
					--tpod.pod_includeInAvailableStock	= 'True'	AND


					-- MOS 07-2022 x CM:  se agrego isAvailable4Relation arriba para que si esta en 0 GRISE el boton y no permita relacionarlo pero que SI se vea que hay disponibles para relacionar.
					--(
					--	--tpod.pod_qty >= @lqty --STL11042022
					--	ISNULL(tmpPOMinusSO.QtyAvailable,tpod.pod_qty) 	>= @lqty
					--		OR
					--	tmp.comp_id IS NOT NULL
					--)	AND


					tpod.item_id						= @litem_id

		ORDER BY	CASE
						WHEN tmp.comp_id IS NULL THEN 1
						ELSE 0
					END,
					tpoh.bra_id,tpoh.poh_id,
					 ti.item_id, ts.supp_name

	END
GO

CREATE PROCEDURE spSaleOrderHeader_PurchaseOrderRelation_getDataById
(
	@comp_id	INT,
	@posor_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			tsohpor.comp_id,
			tsohpor.posor_id,
			tsohpor.so_bra_id,
			tsohpor.so_soh_id,
			tsohpor.so_sod_id,
			tsohpor.it_transaction,
			tsohpor.po_bra_id,
			tsohpor.po_poh_id,
			tsohpor.po_pod_id,
			tsohpor.posor_POReceived
			FROM tbSaleOrderHeader_PurchaseOrderRelation	AS tsohpor	WITH(NOLOCK)
			WHERE	tsohpor.comp_id		= @comp_id			AND
					tsohpor.posor_id	= @posor_id

	END
GO

CREATE PROCEDURE [dbo].[spSaleOrderHeader_PurchaseOrderRelation_getDataBySODId]
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT,
	@sod_id		INT,
	@tis_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		DECLARE @bitExist AS BIT = 'False'

		SELECT @bitExist = 'True'
			FROM tbSaleOrderHeader_PurchaseOrderRelation AS tsohpor	WITH (NOLOCK)
			WHERE
					(
						tsohpor.comp_id		= @comp_id	AND
						tsohpor.so_bra_id	= @bra_id	AND
						tsohpor.so_soh_id	= @soh_id	AND
						tsohpor.so_sod_id	= @sod_id
					)
						OR
					(
						tsohpor.comp_id		= @comp_id	AND
						tsohpor.tis_id		= @tis_id
					)

		SELECT @bitExist [bitExists]

	END
GO

CREATE PROCEDURE [dbo].spSaleOrderHeader_PurchaseOrderRelation_getDataByTIS_Id
(
	@comp_id	INT,
	@tis_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		DECLARE @bitExist AS BIT = 'False'

		SELECT @bitExist = 'True'
			FROM tbTempItemStock								AS ttis		WITH (NOLOCK)
			INNER JOIN  tbSaleOrderHeader_PurchaseOrderRelation	AS por		WITH (NOLOCK)
				ON
					(por.comp_id = ttis.comp_id AND por.tis_id = ttis.tis_id)
						OR
					(por.comp_id = ttis.comp_id AND por.so_bra_id = ttis.bra_id AND por.so_soh_id = ttis.soh_id AND por.so_sod_id = ttis.sod_id)
			WHERE		ttis.comp_id		= @comp_id	AND
						ttis.tis_id			= @tis_id

		SELECT @bitExist [bitExists]

	END
GO

CREATE PROCEDURE [dbo].[spSaleOrderHeader_PurchaseOrderRelation_GetDataForPurchaseOrderConsultation]
(
	@comp_id	INT,
	@poh_id		INT--,
	--@pod_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		--ACA ES SI ENTRA DESDE UNA PO
		--ESTO ES SOLO INFORMATIVO

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@poh_id		INT--,
				--@pod_id		INT
			SELECT
				@comp_id	= 1,
				@poh_id		= 1--,
				--@pod_id		= 1 --ESTE ES NECESARIO? O CON EL POH_ID ES SUFICIENTE' PORQUE SI ES PARA CONSULTA CON EL POH RECUPERO TODO LO QUE TENGA ASOCIADO
		*/
		-- ------------------------------------------------

		--LO QUE TENGO ES EL POD, CON ESE POD TENGO EL ITEM ID Y POR ENDE PUEDO BUSCAR LOS PEDIDOS QUE TENGAN ESE  ITEM_ID Y QUE TENGAN UNA CANTIDAD MENOR O IGUAL
		--PRIMERO GRABO UNA TEMPORAL EN LA QUE VOY A BUSCAR PARA ESE POH_ID TODOS LOS ARTICULOS RELACIONADOS A SUS POD

		-- ------------------------------------------------------------------------------------------------------
		-- AHORA RECUPERO LOS DATOS DE LA TABLA DE RELACIONES
		-- ------------------------------------------------------------------------------------------------------
			DECLARE @tblRelatedPOD TABLE (
											comp_id		INT,
											posor_id	INT,
											soh_id		INT,
											sod_id		INT,
											poh_id		INT,
											pod_id		INT,
											tis_id		INT
											)
			INSERT INTO @tblRelatedPOD
			(
				comp_id,
				posor_id,
				soh_id,
				sod_id,
				poh_id,
				pod_id,
				tis_id
			)
			SELECT
				tsohpor.comp_id,
				tsohpor.posor_id,
				tsohpor.so_soh_id,
				tsohpor.so_sod_id,
				tsohpor.po_poh_id,
				tsohpor.po_pod_id,
				tsohpor.tis_id
				FROM	tbSaleOrderHeader_PurchaseOrderRelation AS tsohpor	WITH(NOLOCK)
				WHERE	tsohpor.comp_id		= @comp_id	AND
						tsohpor.po_poh_id	= @poh_id	--AND
						--tsohpor.po_pod_id	= @pod_id
		-- ------------------------------------------------------------------------------------------------------

		--ACA ME TRAIGO TODOS LOS ARTICULOS DE PEDIDOS QUE ESTEN ASOCIADOS A ESTA ORDEN DE COMPRA Y TENGAN UN SOD (LO QUE SIGNIFICA QUE YA SON PEDIDOS GRABADOS)
		SELECT
			'Pedido # ' + CONVERT(VARCHAR,tsoh.soh_id)	[soh_id],
			ti.item_code,
			ti.item_desc,
			tsod.sod_qty
			FROM tbSaleOrderDetail				AS tsod	WITH(NOLOCK)
			INNER JOIN @tblRelatedPOD			tmp
			ON	tmp.comp_id		= tsod.comp_id	AND
				tmp.sod_id		= tsod.sod_id
			INNER JOIN tbSaleOrderHeader		AS tsoh WITH(NOLOCK)
			ON	tsoh.comp_id	= tsod.comp_id	AND
				tsoh.soh_id		= tsod.soh_id	AND
				tsoh.bra_id		= tsod.bra_id
			INNER JOIN tbItem					AS ti	WITH(NOLOCK)
			ON	ti.comp_id		= tsod.comp_id	AND
				ti.item_id		= tsod.item_id
			WHERE tsod.comp_id	= @comp_id

	END


GO

CREATE PROCEDURE [dbo].[spSaleOrderHeader_PurchaseOrderRelation_InsertData]
(
	@comp_id				INT,
	@so_bra_id				INT,
	@so_soh_id				INT,
	@so_sod_id				INT,
	@it_transaction			INT,
	@po_bra_id				INT,
	@po_poh_id				INT,
	@po_pod_id				INT,
	@posor_POReceived		INT,
	@tis_id					INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@so_bra_id				INT,
				@so_soh_id				INT,
				@so_sod_id				INT,
				@it_transaction			INT,
				@po_bra_id				INT,
				@po_poh_id				INT,
				@po_pod_id				INT,
				@posor_POReceived		INT,
				@tis_id					INT
		*/
		-- ------------------------------------------------

		-- -----------------------------------------------------------------------------------------------------
		-- SI NO TENGO UN PEDIDO GENERADO, LA SUCURSAL, EL HEADER Y EL DETAIL PUEDEN GRABARSE EN NULL
		-- LO QUE NUNCA PUEDE VENIR EN NULL SON LOS DATOS DE LAS PURCHASEORDER, EL TIS_ID Y LA CANTIDAD
		-- IT TRANSACTION QUE ONDA?
		-- -----------------------------------------------------------------------------------------------------
			IF @so_bra_id = -1
				BEGIN
					SET @so_bra_id = NULL
				END
			IF @so_soh_id = -1
				BEGIN
					SET @so_soh_id = NULL
				END
			IF @so_sod_id = -1
				BEGIN
					SET @so_sod_id = NULL
				END
			IF @it_transaction = -1
				BEGIN
					SET @it_transaction = NULL
				END
		-- -----------------------------------------------------------------------------------------------------




		-- -----------------------------------------------------------------------------------
		-- MR quiere q se ponga UN DIA DESPUES de la recepcion estimada.  Ticket 13399  Claudia Muebles
		-- -----------------------------------------------------------------------------------
		DECLARE @poh_estDeliveryDate AS DATETIME = NULL

		SELECT  @poh_estDeliveryDate = DATEADD( DAY,1, ISNULL(tpod.poh_estDeliveryDate,GETDATE()))
			FROM tbPurchaseOrderHeader	AS tpod	WITH (NOLOCK)
			WHERE	tpod.comp_id	= @comp_id		AND
					tpod.bra_id		= @po_bra_id	AND
					tpod.poh_id		= @po_poh_id

		DECLARE @bitPOD_includeInAvailableStock AS BIT = 'False'
		SELECT  @bitPOD_includeInAvailableStock = ISNULL(tpod.pod_includeInAvailableStock,'False')
			FROM tbPurchaseOrderDetail AS tpod WITH (NOLOCK)
			WHERE	tpod.comp_id	= @comp_id AND
					tpod.bra_id		= @po_bra_id AND
					tpod.poh_id		= @po_poh_id AND
					tpod.pod_id		= @po_pod_id


		DECLARE @deliveryDate AS DATETIME	= NULL
		IF @tis_id > 0
			BEGIN
				UPDATE tbTempItemStock SET sod_itemDeliveryDate			=	DATEADD(DAY,ti.item_repositionInternalDays,
																			CASE	-- MOS 01-2022 Claudia 14495
																				WHEN @poh_estDeliveryDate > sod_itemDeliveryDate THEN @poh_estDeliveryDate
																				WHEN @poh_estDeliveryDate < sod_itemDeliveryDate THEN sod_itemDeliveryDate
																				ELSE @poh_estDeliveryDate
		                                                 					END
																			),
											tis_exclude4AvailableStock	=	CASE
																				WHEN @bitPOD_includeInAvailableStock = 'False'	THEN 	'True' -- Si NO incluye en stock disponibla a la OC, que SAQUE del disponible al pedido ya que va a incluirse cuando INGRESE la OC.
																				WHEN @bitPOD_includeInAvailableStock = 'True'	THEN 	tis_exclude4AvailableStock
																			END,
											tis_pending4pod_IdRelation	= 'False'    /*{ tis_pending4pod_IdRelation }*/
					FROM tbTempItemStock ttis	WITH (NOLOCK)
					LEFT JOIN tbItem  AS ti		WITH (NOLOCK)
						ON	ti.comp_id		= ttis.comp_id AND
							ti.item_id		= ttis.item_id
					WHERE	ttis.comp_id	= @comp_id AND
							ttis.tis_id		= @tis_id

				-- Atrapa la fecha para poder devolverla a la pagina
				SELECT  @deliveryDate = sod_itemDeliveryDate
					FROM tbTempItemStock ttis	WITH (NOLOCK)
					WHERE	comp_id = @comp_id AND
							tis_id	= @tis_id

			END



		-- MOS 14-01-2022 Para que quede IGUAL a -- **GFG23940723094723njm
		UPDATE tbsaleorderdetail
			SET 	sod_itemDeliveryDate		=	CASE	-- MOS 01-2022 Claudia 14495
														WHEN @poh_estDeliveryDate > sod_itemDeliveryDate THEN @poh_estDeliveryDate
														WHEN @poh_estDeliveryDate < sod_itemDeliveryDate THEN sod_itemDeliveryDate
														ELSE @poh_estDeliveryDate
													END
			WHERE	comp_id = @comp_id		AND
					bra_id	= @so_bra_id	AND
					soh_id	= @so_soh_id	AND
					sod_id	= @so_sod_id


		-- Si NO se actualizo en tbTempItemStock la toma de acá
		IF @deliveryDate IS NULL
			BEGIN
				SELECT 	@deliveryDate	=	sod_itemDeliveryDate
					FROM tbsaleorderdetail WITH (NOLOCK)
					WHERE	comp_id = @comp_id		AND
							bra_id	= @so_bra_id	AND
							soh_id	= @so_soh_id	AND
							sod_id	= @so_sod_id
			END

		-- Si NO la encuentra le pone la de hoy
		IF @deliveryDate IS NULL
			BEGIN
				SET @deliveryDate = GETDATE()
			END




		--UPDATE tbsaleorderdetail
		--	SET 	sod_itemDeliveryDate		= ISNULL(@datReceptionDate,sod_itemDeliveryDate)
		--	WHERE	comp_id = @comp_id		AND
		--			bra_id	= @so_bra_id	AND
		--			soh_id	= @so_soh_id	AND
		--			sod_id	= @so_sod_id
		-- -----------------------------------------------------------------------------------




		INSERT INTO tbSaleOrderHeader_PurchaseOrderRelation
		(
			comp_id,
			-- posor_id -- this column value is auto-generated
			so_bra_id,
			so_soh_id,
			so_sod_id,
			it_transaction,
			po_bra_id,
			po_poh_id,
			po_pod_id,
			posor_POReceived,
			tis_id
		)
		VALUES
		(
			@comp_id,
			@so_bra_id,
			@so_soh_id,
			@so_sod_id,
			@it_transaction,
			@po_bra_id,
			@po_poh_id,
			@po_pod_id,
			@posor_POReceived,
			@tis_id
		)

		SELECT	@@IDENTITY		[returnValue],
				@deliveryDate	[deliveryDate]

	END





GO

CREATE PROCEDURE [dbo].[spSaleOrderHeader_PurchaseOrderRelation_IntegrityVerification]

-- que se ejecute al modificar o borrar una OC y en el cierre diario
-- **lwqhf973249%&$#%$#%lkjnlkh  CM y LRCDTPM!

AS

BEGIN

	BEGIN TRY


		SET NOCOUNT ON


		IF NOT EXISTS (SELECT TOP 1 1 FROM tbSaleOrderHeader_PurchaseOrderRelation WITH (NOLOCK)) RETURN


		-- BORRA las Relaciones: OK
		-- Las que tienen un pedido en ALTA relacionado (Tis_Id) que ya no existe y NO tienen ningun pedido ni venta relacionado
		DELETE		tbSaleOrderHeader_PurchaseOrderRelation
			FROM	tbSaleOrderHeader_PurchaseOrderRelation pohr	WITH (NOLOCK)
			LEFT JOIN tbPurchaseOrderDetail AS tpod					WITH (NOLOCK)
				ON	tpod.comp_id	= pohr.comp_id AND
					tpod.bra_id		= pohr.po_bra_id AND
					tpod.poh_id		= pohr.po_poh_id AND
					tpod.pod_id		= pohr.po_pod_id
			LEFT JOIN tbTempItemStock AS ttis						WITH (NOLOCK)
				ON ttis.tis_id		= pohr.tis_id
			WHERE	pohr.it_transaction IS NULL		AND
					pohr.so_sod_id		IS NULL		AND
					pohr.tis_id			IS NOT NULL	AND
					ttis.tis_id			IS NULL
						-- (Las que tienen un pedido en alta y lo cerraron de la X)




		-- BORRA las Relaciones: OK
		-- Las que le BORRARON el pedido relacionado
		DELETE		tbSaleOrderHeader_PurchaseOrderRelation
			FROM	tbSaleOrderHeader_PurchaseOrderRelation AS pohr	WITH (NOLOCK)
			LEFT JOIN tbPurchaseOrderDetail					AS tpod	WITH (NOLOCK)
				ON	tpod.comp_id	= pohr.comp_id		AND
					tpod.bra_id		= pohr.po_bra_id	AND
					tpod.poh_id		= pohr.po_poh_id	AND
					tpod.pod_id		= pohr.po_pod_id
			LEFT JOIN tbSaleOrderDetail						AS tsod	WITH (NOLOCK)
				ON	tsod.comp_id	= pohr.comp_id		AND
					tsod.bra_id		= pohr.so_bra_id	AND
					tsod.soh_id		= pohr.so_soh_id	AND
					tsod.sod_id		= pohr.so_sod_id
			LEFT JOIN tbTempItemStock						AS ttis	WITH (NOLOCK)
				ON ttis.tis_id		= pohr.tis_id
			WHERE	pohr.it_transaction IS NULL			AND
					pohr.so_sod_id		IS NOT NULL		AND
					tsod.sod_id			IS NULL			AND
					ttis.tis_id			IS NULL


		---- Saca los tis_id que ya NO estan editandose.
		--IF DATEPART(hour,GETDATE()) BETWEEN 2 AND 8
		--	BEGIN
		--		UPDATE		tbSaleOrderHeader_PurchaseOrderRelation
		--			SET tis_id = ttis.tis_id
		--			FROM	tbSaleOrderHeader_PurchaseOrderRelation pohr		WITH (NOLOCK)
		--			LEFT JOIN tbTempItemStock AS ttis							WITH (NOLOCK)
		--				ON ttis.tis_id		= pohr.tis_id
		--			WHERE	pohr.it_transaction IS NULL AND
		--					pohr.so_sod_id		IS NULL	AND
		--					ttis.tis_id			IS NULL	AND
		--					pohr.tis_id			IS NOT NULL

		--	END






		-- ----------------------------------------------------------------------
		-- -- Las que NO  tienen Orden de Compra relacionada ( LAS BORRARON )
		--
		-- ----------------------------------------------------------------------
		DECLARE @curcomp_id		AS INT
		DECLARE @curposor_id	AS INT
		DECLARE @curso_bra_id	AS INT
		DECLARE @curso_soh_id	AS INT
		DECLARE @curso_sod_id	AS INT
		DECLARE @curso_sod_qty	AS DECIMAL(19,4) = 0
		DECLARE @qtyRELATED		AS DECIMAL(19,4) = 0



			BEGIN

				DECLARE curSORelated CURSOR LOCAL FORWARD_ONLY FOR
					SELECT	pohr.comp_id,
							pohr.posor_id,
							pohr.so_bra_id,
							pohr.so_soh_id,
							pohr.so_sod_id
						FROM tbSaleOrderHeader_PurchaseOrderRelation	pohr	WITH (NOLOCK)
						LEFT JOIN tbPurchaseOrderDetail					tpod	WITH (NOLOCK)
							ON	tpod.comp_id	= pohr.comp_id AND
								tpod.bra_id		= pohr.po_bra_id AND
								tpod.poh_id		= pohr.po_poh_id AND
								tpod.pod_id		= pohr.po_pod_id
						WHERE	tpod.comp_id IS NULL																	-- Las que NO  tienen Orden de Compra relacionada ( LAS BORRARON )
						ORDER BY pohr.tis_id,pohr.so_sod_id,pohr.it_transaction



					OPEN			curSORelated
					FETCH NEXT FROM curSORelated INTO
						@curcomp_id,
						@curposor_id,
						@curso_bra_id,
						@curso_soh_id,
						@curso_sod_id
					WHILE @@FETCH_STATUS = 0
						BEGIN

							-- Envio eMail con los Cambios
							BEGIN TRY
								INSERT INTO tbsendEMailQueue(comp_id,
																[user_id],
																replyTo,
																sendTo,
																[subject],
																body,
																displayName,
																sq_cd)
									SELECT	tb.comp_id,
											tb.user_id_ProcessingDate,
											tb.bra_purchaseOrder_eMail4UnRelation2SO,
											tb.bra_purchaseOrder_eMail4UnRelation2SO,
											'Orden de Compra: ' + CONVERT(VARCHAR(10),ort.po_bra_id) + '-' + CONVERT(VARCHAR(10),ort.po_poh_id) + ' Modificada',
											'Orden de Compra: ' + CONVERT(VARCHAR(10),ort.po_bra_id) + '-' + CONVERT(VARCHAR(10),ort.po_poh_id) + ' Modificada <br/>' +
											'Artículo: ' + ti.item_code + ' - ' + ti.item_desc + ' desvinculado del Pedido:' + CONVERT(VARCHAR(10),ort.so_bra_id) + '-' + CONVERT(VARCHAR(10),ort.so_soh_id) + ' <br/>' +
											'Cliente: ('   + CONVERT(VARCHAR(10),tc.cust_id) + ') ' + tc.cust_name,
											tb.bra_purchaseOrder_eMail4UnRelation2SO,
											GETDATE()
										FROM tbBranch										AS tb	WITH (NOLOCK)
										INNER JOIN tbSaleOrderHeader_PurchaseOrderRelation	AS ort	WITH (NOLOCK)
											ON	ort.comp_id		= @curcomp_id	AND
												ort.posor_id	= @curposor_id
										INNER JOIN tbPurchaseOrderDetail					AS tpod	WITH (NOLOCK)
											ON	tpod.comp_id	= ort.comp_id	AND
												tpod.bra_id		= ort.po_bra_id AND
												tpod.poh_id		= ort.po_poh_id AND
												tpod.pod_id		= ort.po_pod_id
										INNER JOIN tbSaleOrderHeader						AS tsoh	WITH (NOLOCK)
											ON	tsoh.comp_id	= ort.comp_id	AND
												tsoh.bra_id		= ort.so_bra_id AND
												tsoh.soh_id		= ort.so_soh_id
										INNER JOIN tbCustomer								AS tc	WITH (NOLOCK)
											ON	tc.comp_id		= tsoh.comp_id	AND
												tc.cust_id		= tsoh.cust_id
										INNER JOIN tbItem									AS ti	WITH (NOLOCK)
											ON	ti.comp_id		= tpod.comp_id	AND
												ti.item_id		= tpod.item_id
										WHERE	tb.comp_id		= @curcomp_id	AND
												tb.bra_id		= @curso_bra_id	AND
												ISNULL(tb.bra_purchaseOrder_eMail4UnRelation2SO,'') <> ''

							END TRY
							BEGIN CATCH
							END CATCH
							-- Envio eMail con los Cambios


							-- Borro la relacion
							DELETE FROM tbSaleOrderHeader_PurchaseOrderRelation
								WHERE	comp_id		= @curcomp_id	AND
										posor_id	= @curposor_id

							-- POngo el pedido como pendiente a relacionar nuevamente
							UPDATE tbSaleOrderDetail
								SET sod_pending4pod_IdRelation = 'True',
									sod_exclude4AvailableStock = 'True'
								WHERE	comp_id		= @curcomp_id	AND
										bra_id		= @curso_bra_id AND
										soh_id		= @curso_soh_id AND
										sod_id		= @curso_sod_id


							FETCH NEXT FROM curSORelated INTO
								@curcomp_id,
								@curposor_id,
								@curso_bra_id,
								@curso_soh_id,
								@curso_sod_id
						END

					CLOSE		curSORelated
					DEALLOCATE	curSORelated
			END

		-- ----------------------------------------------------------------------




		-- ----------------------------------------------------------------------
		-- MOS 09-2022
		-- tilda en la base si esta relacionadop a una OC NO RECIBIDA el check de excluir de stock disponible
		-- ----------------------------------------------------------------------
		UPDATE tbSaleOrderDetail
			SET sod_exclude4AvailableStock = 'True'
			FROM tbSaleOrderDetail								AS sod	WITH (NOLOCK)
			INNER JOIN tbSaleOrderHeader_PurchaseOrderRelation	AS sohr	WITH (NOLOCK)
				ON	sohr.comp_id	= sod.comp_id	AND
					sohr.so_bra_id	= sod.bra_id	AND
					sohr.so_soh_id	= sod.soh_id	AND
					sohr.so_sod_id	= sod.sod_id
			WHERE	sohr.posor_POReceived			= 'False' AND
					sod.sod_exclude4AvailableStock	= 'False'
		-- ----------------------------------------------------------------------





	END TRY
	BEGIN CATCH
	END CATCH



END
GO

