CREATE  PROCEDURE [dbo].[spSaleOrderHeader_updateData]
(
	@comp_id			int,
	@bra_id				int,
	@soh_id				int,
	@soh_cd             datetime,
	@soh_deliveryDate   datetime,
	@soh_observation1	varchar(350),
	@soh_observation2	varchar(350),
	@soh_observation3	varchar(350),
	@soh_observation4	varchar(350),
	@soh_quotation      bit,
	@sm_id				int,
	@cust_id			int,
	@st_id				int,
	@disc_id			int,
	@dl_id				int,
	@cb_id				int,
	@soh_lastUpdate		datetime,
	@soh_limitDate		datetime,
	@tt_id				int,
	@tt_class			varchar,
	@soh_StatusOf		int,
	@user_id			int,
	@soh_isEditing		bit,
	@soh_isEditingCd    datetime,
	@soh_Total			DECIMAL(19,6),
	@df_id				int,
	@ssos_id			INT,
	@ExchangeToCustomerCurrency AS FLOAT ,--MOS 01-2024: No se x q MIERDA no graba mas decimales como SI lo hace el sp spSaleOrder_updateCurrExchange que tiene la MISMA cantidad y pasa el MISMO valor... DECIMAL(38,27),
	@customerCurrencyId AS INT)

as

BEGIN

--	declare @datetime	datetime
--	select	@datetime = getdate()

	SET @soh_lastUpdate = GETDATE()

	Update tbSaleOrderHeader	WITH (ROWLOCK)
		SET
			--soh_cd				= @soh_cd,
			soh_deliveryDate	= @soh_deliveryDate,
			soh_observation1	= @soh_observation1,
			soh_observation2	= @soh_observation2,
			soh_observation3	= @soh_observation3,
			soh_observation4	= @soh_observation4,
			soh_quotation		= @soh_quotation,
			sm_id				= @sm_id,
			cust_id				= @cust_id,
			st_id				= @st_id,
			disc_id				= @disc_id,
			dl_id				= @dl_id,
			cb_id				= @cb_id,
			soh_lastUpdate		= @soh_lastUpdate,
			soh_limitDate		= @soh_limitDate,
			tt_id				= @tt_id,
			tt_class			= @tt_class,
			soh_StatusOf		= @soh_StatusOf,
			[user_id]			= @user_id,
			soh_isEditing		= @soh_isEditing,
			soh_isEditingCd		= @soh_isEditingCd,
			df_id				= @df_id,
			soh_total			= @soh_Total,
			ssos_id				= @ssos_id,
			soh_ExchangeToCustomerCurrency = @ExchangeToCustomerCurrency,
			soh_CustomerCurrency = @customerCurrencyId

	Where	comp_id				= @comp_id
		And	bra_id				= @bra_id
		And	soh_id				= @soh_id

	-- Inserta Estados a Verificar Según condicion de venta
	EXEC spSaleOrderStatus_InsertUpdateData @comp_id ,
											@bra_id ,
											--@st_id ,
											@soh_id

END





GO





