CREATE PROCEDURE [dbo].[spSaleOrderHeader_UpdateNewPaymentGatewayStatus]
(
	@ws_paymentGateWayStatusID		INT,
	@ws_paymentGateWayReferenceID	UNIQUEIDENTIFIER	,
	@ws_paymentType					NVARCHAR(50),
	@comp_id					AS	INT,
	@cc_id						AS	INT,
	@ccp_id						AS	INT,
	@st_id						AS	INT,
	@cust_id					AS	INT,
	@total						AS	DECIMAL(25,4)	,
	@creditCardName				AS	NVARCHAR(250),
	@collection_id				AS  NVARCHAR(30)				-- No se graba... ver si hace falta, grabarla en la HEADER
)
AS
	BEGIN

		SET NOCOUNT ON

		INSERT INTO tbWebSiteII_paymentStatusLog	WITH (ROWLOCK)
		(
			ws_paymentGateWayReferenceID,
			ws_paymentGateWayStatusID,
			ws_paymentType,
			ws_paymentCD,
			cust_id,
			cc_id,
			ccp_id,
			st_id,
			comp_id,
			wspsl_Total,
			creditCardName
		)
		VALUES
		(
			@ws_paymentGateWayReferenceID,
			@ws_paymentGateWayStatusID,
			@ws_paymentType,
			GETDATE(),
			@cust_id,
			@cc_id,
			@ccp_id,
			@st_id,
			@comp_id,
			@total,
			@creditCardName
		)


		UPDATE tbsaleorderheader WITH (ROWLOCK)
			SET		ws_paymentGateWayStatusID		= @ws_paymentGateWayStatusID
			WHERE	ws_paymentGateWayReferenceID	= @ws_paymentGateWayReferenceID


		-- Aca se puede hacer que si el pedido YA fuer facturado genere un mail avisando o ponga tarea en el crm o algo.




		-- Retorna el Pedido
		SELECT	tsoh.comp_id,
				tsoh.bra_id,
				tsoh.soh_id,
				tsoh.cust_id,
				CASE	--
					WHEN @ws_paymentGateWayStatusID = 51 THEN	tst.cc_id
					ELSE										sl.cc_id
				END															[cc_id],
				--sl.cc_id,
				sl.ccp_id,
				sl.st_id,
				sl.wspsl_Total,
				sl.creditCardName,
				tc.cust_name

			FROM tbSaleOrderHeader					tsoh	WITH (NOLOCK)
			INNER JOIN tbSalesTerms				 AS tst		WITH (NOLOCK)
				ON	tst.comp_id = tsoh.comp_id AND
					tst.st_id	= tsoh.st_id
			INNER JOIN tbWebSiteII_paymentStatusLog sl		WITH (NOLOCK)
				ON sl.ws_paymentGateWayReferenceID		= @ws_paymentGateWayReferenceID
			INNER JOIN tbCustomer tc						WITH (NOLOCK)
				ON	tc.comp_id = tsoh.comp_id AND
					tc.cust_id = tsoh.cust_id
			WHERE	tsoh.ws_paymentGateWayReferenceID	= @ws_paymentGateWayReferenceID	AND
					sl.ws_paymentGateWayStatusID		= 50


	END
GO








