----------------------------------------------------------------------------------
-- Historial de Pedidos
-- 28/08/13
-- GA
-- ** ATENCION **, No agregar campos despues de los campos del final bra_id ,soh_id y ID.
----------------------------------------------------------------------------------

CREATE procedure [dbo].[spSaleOrderHeaderHistory_getDataByFilters]
(

	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@datefrom		DATETIME,
	@dateto			DATETIME,
	@cust_id		INT,
	@item_id		INT,
	@sm_id			INT,
	@soh_id			INT,
	@TypeOfHistory  INT


)

as


BEGIN


	 set nocount on

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


-- -----------------------------------------
-- Testing
-- ----------------------------------------
/*
	declare
			@comp_id		INT,
			@lang_id		INT,
			@bra_id			INT,
			@user_id		INT,
			@datefrom		DATETIME,
			@dateto			DATETIME,
			@cust_id		INT,
			@item_id		INT,
			@sm_id			INT,
			@soh_id			INT,
			@TypeOfHistory  INT

	select
			@comp_id		= 1,
			@lang_id		= 2,
			@bra_id			= 1,
			@user_id		= 1,
			@datefrom		= '01-01-1900',
			@dateto			= '22-10-2015',
			@cust_id		= -1,
			@item_id		= -1,
			@sm_id			= -1,
			@soh_id			= 0,
			@TypeOfHistory  = -1
*/
-- -----------------------------------------


	SET @datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto   = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True' )

		SELECT
			'' [1],
			'' [2],
			dbo.fnStrPADL( CONVERT(VARCHAR,tsohh.bra_id),4,'0') + '-' + dbo.fnStrPADL( CONVERT(VARCHAR, tsohh.soh_id),10,'0') + ' / ' + dbo.fnStrAllTrim( CONVERT(NVARCHAR,tsohh.sohh_id))  [SaleOrderNumber],
			tov.optval_desc												[Accion],
			tdf.df_desc,
			ti.item_code,
			ti.item_desc,
			tsod.sod_qty,
			tsod.sod_price												[price],
			tc.curr_symbol,
			tsohh.soh_deliveryDate,
			tsohh.cust_id,
			tcu.cust_name,
			IsNull(tcb.custb_name,'')									[CustomerBranch],
			tst.st_desc,
			td.disc_desc,
			ts.sm_name,
			td2.dl_name,
			tsohh.soh_lastUpdate,
			tsohh.soh_limitDate,
			tsohh.soh_total,
			tsohh.soh_observation1,
			tsohh.soh_observation2,
			tsohh.soh_observation3,
			tsohh.soh_observation4,
			tb.bra_desc	,
			tsohh.sohh_cd,
			tsohh.soh_cd,
			tu.user_lastname + ', ' + tu.user_firstname					[updateUser],
			-- ATENCION!!!!!!
			-- No poner nada detras de este campo(bra_id) ya que se hacen controles de Count en la pagina 	wfmSaleOrderHeaderHistory
			tsohh.bra_id												[bra_id],	-- Count -3
			tsohh.soh_id												[soh_id],	-- Count -2
			tsohh.sohh_id												[ID]

			from tbSaleOrderHeaderHistory									tsohh			WITH (NOLOCK)


			INNER JOIN tbcustomer											tcu
				ON	tcu.comp_id = tsohh.comp_id AND
					tcu.cust_id = tsohh.cust_id

			INNER JOIN tbBranch												tb				WITH (NOLOCK)
				ON	tb.comp_id = tsohh.comp_id AND
					tb.bra_id = tsohh.bra_id

			inner join tbSaleOrderDetailHistory								tsod			WITH (NOLOCK)
				on  tsod.comp_id	= tsohh.comp_id
				AND tsod.bra_id		= tsohh.bra_id
				AND tsod.soh_id		= tsohh.soh_id
				AND tsod.sohh_id	= tsohh.sohh_id

			inner join tbsysCurrency										tc				WITH (NOLOCK)
				on	tc.curr_id		= tsod.curr_id

			inner join tbItem												ti				WITH (NOLOCK)
				on	ti.comp_id		= tsod.comp_id
				AND ti.item_id		= tsod.item_id

			inner join tbDocumentsFile										tdf				WITH (NOLOCK)
				ON  tdf.comp_id		= tsohh.comp_id
				AND tdf.df_id		= tsohh.df_id

			INNER JOIN tbSalesman											ts				WITH (NOLOCK)
				ON	ts.comp_id	= tsohh.comp_id AND
					ts.sm_id	= tsohh.sm_id

			INNER JOIN tbDiscount											td				WITH (NOLOCK)
				ON	td.comp_id = tsohh.comp_id and
					td.disc_id = tsohh.disc_id

			INNER JOIN tbSalesTerms											tst				WITH (NOLOCK)
				ON	tst.comp_id = tsohh.comp_id AND
					tst.st_id	= tsohh.st_id

			INNER JOIN tbDelivery											td2				WITH (NOLOCK)
				ON	td2.comp_id = tsohh.comp_id AND
					td2.dl_id	= tsohh.dl_id

			LEFT JOIN tbCustomerBranch										tcb				WITH (NOLOCK)
				ON	tcb.comp_id = tsohh.comp_id AND
					tcb.cust_id = tsohh.cust_id AND
					tcb.cb_id	= tsohh.cb_id

			LEFT JOIN tbsysOptionsValues									tov				WITH (NOLOCK)
				ON	tov.lang_id			= @lang_id		AND
					tov.optval_class	= 999			AND
					tov.optval_id		= tsohh.sohh_TypeOfHistory

			LEFT JOIN tbUser												tu				WITH (NOLOCK)
				ON tu.[user_id] = tsohh.sohh_user_id

		where	tsohh.comp_id	= @comp_id
		AND		(tsohh.sohh_cd			BETWEEN		@datefrom	AND	@dateto)
		AND		(@cust_id		= -1	OR tsohh.cust_id				= @cust_id)
		And		(@bra_id		= -1	OR tsohh.bra_id					= @bra_id)
		AND		(@sm_id			= -1    OR tsohh.sm_id					= @sm_id)
		AND		(@user_id		= -1    OR tu.[user_id]					= @user_id)
		AND		(@item_id		= -1	OR ti.item_id					= @item_id)
		and		(@soh_id		= 0		OR tsohh.soh_id					= @soh_id)
		AND		(@TypeOfHistory	= -1	OR tsohh.sohh_TypeOfHistory		= @TypeOfHistory)


		ORDER BY tsohh.sohh_id DESC



END
GO






CREATE procedure [dbo].[spSaleOrderHeaderHistory_getGenericGridData]
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT
)
as set nocount on


-- -----------------------------------------
-- Testing
-- -----------------------------------------
/*
	declare
		@comp_id	INT,
		@bra_id		INT,
		@soh_id		INT

	select
		@comp_id	= 1,
		@bra_id		= 1,
		@soh_id		= 32847
*/
-- -----------------------------------------


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


select
	--tsohh.soh_id,
	tov.optval_desc				[Accion],
	tdf.df_desc,
	ti.item_desc,
	tsod.sod_qty,
	tc.curr_symbol + ' ' + convert(varchar,tsod.sod_price) [price],
	tsohh.soh_deliveryDate,


	tsohh.cust_id,
	IsNull(tcb.custb_name,'')	[CustomerBranch],
	tst.st_desc,
	td.disc_desc,
	ts.sm_name,
	td2.dl_name,
	tsohh.soh_lastUpdate,
	tsohh.soh_limitDate,
	tsohh.soh_total,

	tsohh.soh_observation1,
	tsohh.soh_observation2,
	tsohh.soh_observation3,
	tsohh.soh_observation4,

	tsohh.sohh_cd									[updateDate],
	tu.user_lastname + ', ' + tu.user_firstname		[updateUser],
	tsohh.sohh_id									[id]

from tbSaleOrderHeaderHistory			tsohh

--	inner join tbSaleOrderHeader		tsoh
--	on	tsoh.comp_id	= tsohh.comp_id
--	and tsoh.bra_id		= tsohh.bra_id
--	and tsoh.soh_id		= tsohh.soh_id

	inner join tbSaleOrderDetailHistory		tsod
	on  tsod.comp_id	= tsohh.comp_id
	AND tsod.bra_id		= tsohh.bra_id
	AND tsod.soh_id		= tsohh.soh_id

	inner join tbsysCurrency			tc
	on	tc.curr_id		= tsod.curr_id

	inner join tbItem					ti
	on	ti.comp_id		= tsod.comp_id
	AND ti.item_id		= tsod.item_id

	inner join tbDocumentsFile			tdf
	on	tdf.bra_id		= tsohh.bra_id
	AND tdf.comp_id		= tsohh.comp_id
	AND tdf.df_id		= tsohh.df_id

	INNER JOIN tbSalesman ts
		ON	ts.comp_id	= tsohh.comp_id AND
			ts.sm_id	= tsohh.sm_id

	INNER JOIN tbDiscount td
		ON	td.comp_id = tsohh.comp_id and
			td.disc_id = tsohh.disc_id

	INNER JOIN tbSalesTerms tst
		ON	tst.comp_id = tsohh.comp_id AND
			tst.st_id	= tsohh.st_id

	INNER JOIN tbDelivery td2
		ON	td2.comp_id = tsohh.comp_id AND
			td2.dl_id	= tsohh.dl_id

	LEFT JOIN tbCustomerBranch tcb
		ON	tcb.comp_id = tsohh.comp_id AND
			tcb.cust_id = tsohh.cust_id AND
			tcb.cb_id	= tsohh.cb_id

	LEFT JOIN tbsysOptionsValues tov
		ON	tov.lang_id		= 2		AND
			tov.optval_class = 999	AND			-- POner Bien
			tov.optval_id    = tsohh.sohh_TypeOfHistory

	LEFT JOIN tbUser tu
		ON tu.[user_id] = tsohh.sohh_user_id

where	tsohh.comp_id	= @comp_id
and		tsohh.bra_id	= @bra_id
and		tsohh.soh_id	= @soh_id

ORDER BY tsohh.sohh_id
GO





CREATE PROCEDURE [dbo].[spSaleOrderHeaderHistory_Times_getGenericGridData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@soh_id		INT
)

AS


BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


	-- ----------------------------------------
	-- TESTING
	-- ----------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@soh_id		INT


		SELECT
			@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@soh_id		= 33260
*/
	-- ----------------------------------------

	SET NOCOUNT ON



		SELECT
			tsot.sot_cd													[Date],
			tov.optval_desc												[MovType],
			tu.user_lastname + ', ' + tu.user_firstname					[User],
			tsot.sot_id													[ID]

			FROM tbSaleOrderTimes									tsot			WITH (NOLOCK)

			LEFT JOIN tbsysOptionsValues							tov				WITH (NOLOCK)
			ON	tov.lang_id			= @lang_id			AND
				tov.optval_class	= 536				AND
				tov.optval_id		= tsot.ssot_id

			LEFT JOIN tbUser										tu				WITH (NOLOCK)
			ON	  tu.[user_id]		= tsot.[user_id]


			WHERE tsot.comp_id		= @comp_id		AND
				  tsot.bra_id		= @bra_id		AND
				  tsot.soh_id		= @soh_id

			ORDER BY tsot.sot_cd


END
GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2009
-- Description:	Graba el historial del pedido
--				y pone cual es el motivo
--				1- Modificacion
--				2- Baja
--				3- Procesamiento
-- =============================================
CREATE PROCEDURE [dbo].[spSaleOrderHistory_InsertFromSaleOrder]
	@comp_id			as int,
	@bra_id				as int,
	@soh_id				as int,
	@sohh_TypeOfHistory as INT,
	@ct_transaction		AS INT,
	@user_id			AS INT,
	@htmlNote			AS NTEXT

AS
BEGIN
	SET NOCOUNT ON;

	Declare @sohh_id	as int


	IF @ct_transaction = -1 SET @ct_transaction = NULL
	IF @user_id		   = -1 SET @user_id		= NULL


	-- --------------------------------------------------------------------------------------------------------------------
	-- MOS 05-2022: Para que auto aplique la cobranza de una factura que se genero desde un pedido COBRADO desde cobranzas.
	-- --------------------------------------------------------------------------------------------------------------------
	BEGIN TRY
		DECLARE @ct_transaction_preCollection				AS INT = NULL
		SELECT	@ct_transaction_preCollection = ct_transaction_preCollection
			FROM tbSaleOrderHeader AS tsoh	WITH (NOLOCK)
			WHERE	tsoh.comp_id	= @comp_id AND
					tsoh.bra_id		= @bra_id AND
					tsoh.soh_id		= @soh_id
		IF @ct_transaction_preCollection IS NOT NULL
			BEGIN
				DECLARE @guid AS UNIQUEIDENTIFIER = NEWID()
				EXEC spCollection_insertApplicationByCTTransactionLoan @comp_id,@ct_transaction_preCollection,@ct_transaction,NULL,@guid
			END
	END TRY
	BEGIN CATCH
	END CATCH
	-- --------------------------------------------------------------------------------------------------------------------




	Insert Into dbo.tbSaleOrderHeaderHistory	WITH (ROWLOCK)
		(comp_id,
		 bra_id,
		 soh_id,
         sohh_TypeOfHistory,
         soh_cd,
         soh_deliveryDate,
         soh_observation1,
         soh_observation2,
         soh_observation3,
         soh_observation4,
         soh_quotation,
         sm_id,
         cust_id,
         st_id,
         disc_id,
         dl_id,
         cb_id,
         soh_lastUpdate,
         soh_limitDate,
         tt_id,
         tt_class,
         soh_StatusOf,
         user_id,
         soh_isEditing,
         soh_isEditingCd,
         df_id,
         soh_total,
         ssos_id,
 		 soh_ExchangeToCustomerCurrency,
		 chp_id,
		 soh_PL_df_Id,
		 soh_CustomerCurrency,
		 soh_WithCollection,
		 soh_WithCollectionGUID,
		 soh_discount,
		 soh_loan,
		 soh_packagesQty,
		 soh_internalAnnotation,
		 curr_id4Exchange,
		 curr_idExchange,
		 soh_ATotal,
		 df_id4PL,
		 somp_id,
		 soh_FEIdNumber,
		 soh_inCash,
		 ct_transaction,
		 sohh_user_id,
		 soh_MLQuestionsAndAnswers,
		 soh_MLId,
		 soh_MLGUIA,
		 ws_paymentGateWayStatusID,
		 ws_paymentGateWayReferenceID,
		 soh_deliveryAddress,
		 stor_id,
		 mlo_id,
		 ws_IPFrom,
		 ws_cust_Id,
		 ws_internalID,
		 soh_note4ExternalUse,
		 ccp_id,
		 sohh_isPackingOfPreInvoice,
		 soh_uniqueID

		)

			Select   tit.comp_id,
					 tit.bra_id,
					 tit.soh_id,
					 @sohh_TypeOfHistory,
					 tit.soh_cd,
					 tit.soh_deliveryDate,
					 tit.soh_observation1,
					 tit.soh_observation2,
					 tit.soh_observation3,
					 tit.soh_observation4,
					 tit.soh_quotation,
					 tit.sm_id,
					 tit.cust_id,
					 tit.st_id,
					 tit.disc_id,
					 tit.dl_id,
					 tit.cb_id,
					 tit.soh_lastUpdate,
					 tit.soh_limitDate,
					 tit.tt_id,
					 tit.tt_class,
					 tit.soh_StatusOf,
					 tit.user_id,
					 tit.soh_isEditing,
					 GETDATE(),			--21-01-2013 -- Confirmado por Martín
					 tit.df_id,
					 tit.soh_total,
					 tit.ssos_id,
					 tit.soh_ExchangeToCustomerCurrency,
					 tit.chp_id,
					 tit.soh_PL_df_Id,
					 tit.soh_CustomerCurrency,
					 tit.soh_WithCollection,
					 tit.soh_WithCollectionGUID,
					 tit.soh_discount,
					 tit.soh_loan,
					 tit.soh_packagesQty,
					 tit.soh_internalAnnotation,
					 tit.curr_id4Exchange,
					 tit.curr_idExchange,
					 tit.soh_ATotal,
					 tit.df_id4PL,
					 tit.somp_id,
					 tit.soh_FEIdNumber,
					 tit.soh_inCash,
					 @ct_transaction,
					 @user_id,
					 tit.soh_MLQuestionsAndAnswers,
					 tit.soh_MLId,
					 tit.soh_MLGUIA,
					 tit.ws_paymentGateWayStatusID,
					 tit.ws_paymentGateWayReferenceID,
					 tit.soh_deliveryAddress,
					 tit.stor_id,
					 tit.mlo_id,
					 tit.ws_IPFrom,
					 tit.ws_cust_Id,
					 tit.ws_internalID,
					 tit.soh_note4ExternalUse,
					 tit.ccp_id	,
					 CASE	-- MOS 01-2022: Pone en True este campo si es un Remito de Fc Anticipada para poder ver en el historial, para el MISMO pedido, cual es de la Fc Anticipada y cual es del Remito de Fc Anticipada y usarlo en la vista  vwCommercialTransactions_preInvoice_PackingListRelation SIN que duplique filas.
						WHEN tdf.df_SaleOrder_IsInvoiceFirstPacking = 'True' THEN	'True'
						ELSE														'False'
					 END,
					 tit.soh_uniqueID
				From dbo.tbSaleOrderHeader AS tit		WITH (NOLOCK)
				INNER JOIN tbDocumentsFile AS tdf		WITH (NOLOCK)	-- MOS 01-2022
					ON	tdf.comp_id = tit.comp_id AND
						tdf.df_id	= tit.df_id
				Where	tit.comp_id = @comp_id
					and tit.bra_id  = @bra_id
					and tit.soh_id  = @soh_id

	Set @sohh_id = @@Identity

	-- Solo los items que se procesaron en éste comprobante.!
	Insert Into dbo.tbSaleOrderDetailHistory	WITH (ROWLOCK)
		(comp_id,
		 bra_id,
         soh_id,
         sohh_id,
         sod_id,
         sod_priority,
         item_id,
         sod_itemDesc,
         sod_detail,
         curr_id,
         sod_initQty,
         sod_qty,
         prli_id,
         sod_price,
         stor_id,
         sod_lastUpdate,
         sod_isEditing,
         sod_insertDate,
         user_id,
         sod_quotation,
         sod_isCredit,
         sod_cost,
         sod_costTax,
         rmah_id,
         rmad_id,
         sod_note1,
 		 sod_note2,
		 sod_itemDiscount,
		 sod_tis_id_origin,
		 sod_item_id_origin,
		 sod_isParentAssociate,
		 is_id,
		 it_transaction,
		 sod_isMade,
		 sod_expirationDate,
		 acc_count_id,
		 sod_packagesQty,
		 item_id_EW,
		 tis_idOfThisEW,
		 camp_id,
		 sod_EWAddress,
		 sod_MLCost,
		 sdlmt_id,
		 sops_id,
		 sops_supp_id,
		 sops_bra_id,
		 sops_date,
		 mlo_id,
		 sod_MECost,
		 sod_MPCost,
		 sod_isDivided,
		 sod_isDivided_Date,
		 user_id_division,
		 sodi_id,
		 sod_isDivided_costCoeficient,
		 sops_poh_bra_id,
		 sops_poh_id,
		 sops_note,
		 sops_user_id,
		 sops_lastUpdate
		)
		Select
			 tit.comp_id,
			 tit.bra_id,
			 tit.soh_id,
			 @sohh_id,
			 tit.sod_id,
			 tit.sod_priority,
			 tit.item_id,
			 tit.sod_itemDesc,
			 tit.sod_detail,
			 tit.curr_id,
			 tit.sod_initQty,
			 tit.sod_qty,
			 tit.prli_id,
			 tit.sod_price,
			 tit.stor_id,
			 tit.sod_lastUpdate,
			 tit.sod_isEditing,
			 tit.sod_insertDate,
			 tit.user_id,
			 tit.sod_quotation,
			 tit.sod_isCredit,
			 tit.sod_cost,
			 tit.sod_costTax,
	         tit.rmah_id,
		     tit.rmad_id,
		     tit.sod_note1,
		     tit.sod_note2,
		     tit.sod_itemDiscount,
		     tit.sod_tis_id_origin,
		     tit.sod_item_id_origin,
		     tit.sod_isParentAssociate,
		     tit.is_id,
		     tit.it_transaction,
		     tit.sod_isMade,
		     tit.sod_expirationDate,
		     tit.acc_count_id,
		     tit.sod_packagesQty,
		     tit.item_id_EW,
		     tit.tis_idOfThisEW,
		     tit.camp_id,
		     tit.sod_EWAddress,
		     tit.sod_MLCost,
		     tit.sdlmt_id,
			 tit.sops_id,
			 tit.sops_supp_id,
			 tit.sops_bra_id,
			 tit.sops_date,
			 tit.mlo_id,
			 tit.sod_MECost,
			 tit.sod_MPCost,
			 tit.sod_isDivided,
			 tit.sod_isDivided_Date,
			 tit.user_id_division,
			 tit.sodi_id,
			 tit.sod_isDivided_costCoeficient,
			 tit.sops_poh_bra_id,
			 tit.sops_poh_id,
			 tit.sops_note,
			 tit.sops_user_id,
			 sops_lastUpdate


			From dbo.tbSaleOrderDetail tit		WITH (NOLOCK)

			Where		tit.comp_id = @comp_id
					and tit.bra_id  = @bra_id
					and tit.soh_id  = @soh_id


		IF @ct_transaction IS NOT NULL
			BEGIN
				-- Nota HTML
				UPDATE tbCommercialTransactionNotes	WITH (ROWLOCK)
					SET			ctn_htmlNote = @htmlNote
					WHERE	comp_id				= @comp_id AND
							bra_id				= @bra_id AND
							ct_transaction		= @ct_transaction


				-- Obtiene datos de la factura recien guardada.
				DECLARE @isPreInvoice AS BIT
				SET		@isPreInvoice = 'False'

				SELECT @isPreInvoice =	CASE
											WHEN tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL THEN 'True'
											ELSE															 'False'
										END
					FROM tbCommercialTransactions	tct		WITH (NOLOCK)
					INNER JOIN tbDocumentsFile		tdf		WITH (NOLOCK)
						ON	tdf.comp_id		= tct.comp_id AND
							tdf.bra_id		= tct.bra_id AND
							tdf.df_id		= tct.df_id
					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ct_transaction


				-- ---------------------------------------------------------------------------------------------------------------
				-- si NO es Factura Adelantada o Anticipada reemplaza los turnos de armado del pedido.
				-- ---------------------------------------------------------------------------------------------------------------
				IF @isPreInvoice = 'False'
					BEGIN

						-- Si posee turnos de armado reemplaza el ID de pedido por un ct_transaction
						UPDATE tbSaleOrderAssemblyTurns		WITH (ROWLOCK)
							SET
								soh_bra_idHistory	= soh_bra_id,
								soh_id_History		= soh_id,
								sod_id_History		= sod_id,
								soh_bra_id			= NULL,
								soh_id				= NULL,
								sod_id				= NULL,
								ct_transaction		= @ct_transaction
							WHERE	comp_id			= @comp_id AND
									soh_bra_id		= @bra_id AND
									soh_id			= @soh_id

					END
				-- ---------------------------------------------------------------------------------------------------------------

			END

END
GO





