create PROCEDURE [dbo].[spSaleOrderLoan_GetData_CheckAmountsNegatives]
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT
)
AS



BEGIN

	SET NOCOUNT ON


	-- --------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@bra_id		INT,
			@soh_id		INT
		SELECT
			@comp_id	= 1,
			@bra_id		= 1 ,
			@soh_id		= 33601842
	*/
	-- --------------------------------------------------------

		IF EXISTS (
					SELECT
						tsol.sol_id
						FROM tbSaleOrderLoan					tsol

						WHERE	tsol.comp_id			= @comp_id		AND
								tsol.bra_id				= @bra_id       AND
								tsol.soh_id				= @soh_id		AND
								tsol.ln_loanPayTotal	< 0
					)
			BEGIN
				--SELECT ' SI TIENE CUOTAS CON IMPORTE NEGATIVO ( NO DEJAR GRABAR Y/O EMITIR )'
				SELECT
					0																		[Status],
					' SI TIENE CUOTAS CON IMPORTE NEGATIVO ( NO DEJAR GRABAR Y/O EMITIR )'  [message]
			END
		ELSE
			BEGIN
				--SELECT 'NO TIENE CUOTAS CON IMPORTE NEGATIVO'
				SELECT
					1										[Status],
					'NO TIENE CUOTAS CON IMPORTE NEGATIVO'  [message]
			END
END

GO





