CREATE PROCEDURE [dbo].[spSaleOrderLoanTmp_GetData_CheckAmountsNegatives]
(
	@comp_id	INT,
	@tis_guid   UNIQUEIDENTIFIER
)
AS



BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	-- --------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@tis_guid   UNIQUEIDENTIFIER
		SELECT
			@comp_id	= 1,
			@tis_guid	= 'C573BEC3-C39A-468D-9CF4-B6F9AED797EF'
	*/
	-- --------------------------------------------------------




		IF EXISTS (
					SELECT
						SUM(tsolt.ln_loanPayTaxes + tsolt.ln_loanPayTotal)

						FROM tbSaleOrderLoanTMP						tsolt

						WHERE	tsolt.comp_id									= @comp_id		AND
								tsolt.tis_guid									= @tis_guid
					GROUP BY tsolt.ln_loanPayNumber
					HAVING SUM(tsolt.ln_loanPayTaxes + tsolt.ln_loanPayTotal) < 0


					)
			BEGIN
				--SELECT ' TIENE CUOTAS CON IMPORTE NEGATIVO ( NO DEJAR GRABAR Y/O EMITIR )'
				SELECT
					0																			[Status],
					'ERROR, TIENE CUOTAS CON IMPORTE NEGATIVO ( NO DEJAR GRABAR Y/O EMITIR )'	[message]
			END
		ELSE
			BEGIN
				--SELECT 'NO TIENE CUOTAS CON IMPORTE NEGATIVO'
				SELECT
					1													[Status],
					'TODO OK , NO TIENE CUOTAS CON IMPORTE NEGATIVO'	[message]
			END




END

GO





