CREATE PROCEDURE spSaleOrderLoanTmp_GetData_CheckLoanQuoteDates
(
	@comp_id	INT,
	@tis_guid   UNIQUEIDENTIFIER,
	@st_id		INT
)
AS



BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	-- --------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@tis_guid   UNIQUEIDENTIFIER
		SELECT
			@comp_id	= 1,
			@tis_guid	= 'C573BEC3-C39A-468D-9CF4-B6F9AED797EF'
	*/
	-- --------------------------------------------------------


	IF EXISTS(	SELECT 1
	          		FROM tbSalesTerms tst WITH (NOLOCK)
	          		WHERE	tst.comp_id = @comp_id	AND
	          				tst.st_id	= @st_id	AND
	          				ISNULL(tst.credit_quoteLoanMaxDays,0) > 0
			)
		BEGIN
			DECLARE @credit_quoteLoanMaxDays AS INT
			SELECT @credit_quoteLoanMaxDays = tst.credit_quoteLoanMaxDays
				FROM tbSalesTerms tst WITH (NOLOCK)
				WHERE	tst.comp_id = @comp_id	AND
						tst.st_id	= @st_id

			DECLARE @datDate0 AS DATETIME
			DECLARE @datDate1 AS DATETIME
			DECLARE @datDate2 AS DATETIME
			SELECT @datDate0 = ISNULL(ts.ln_loanPayDate,GETDATE())
				FROM tbSaleOrderLoanTMP ts WITH (NOLOCK)
				WHERE	ts.comp_id			= @comp_id	AND
						ts.tis_guid			= @tis_guid	AND
						ts.ln_loanPayNumber = 0

			SELECT @datDate1 = ISNULL(ts.ln_loanPayDate,GETDATE())
				FROM tbSaleOrderLoanTMP ts WITH (NOLOCK)
				WHERE	ts.comp_id			= @comp_id	AND
						ts.tis_guid			= @tis_guid	AND
						ts.ln_loanPayNumber = 1

			SELECT @datDate2 = ISNULL(ts.ln_loanPayDate,GETDATE())
				FROM tbSaleOrderLoanTMP ts WITH (NOLOCK)
				WHERE	ts.comp_id			= @comp_id	AND
						ts.tis_guid			= @tis_guid	AND
						ts.ln_loanPayNumber = 2


			IF	ABS(DATEDIFF(DAY, @datDate0, @datDate1)) > @credit_quoteLoanMaxDays OR
				ABS(DATEDIFF(DAY, @datDate1, @datDate2)) > @credit_quoteLoanMaxDays
				BEGIN
					SELECT
						0																			[Status],
						'ERROR, TIENE CUOTAS CON MAS DIAS DEL MAXIMO PERMITIDO ( NO DEJAR GRABAR Y/O EMITIR )'	[message]
				END
			ELSE
				BEGIN
					SELECT
						1													[Status],
						'TODO OK '											[message]
				END
		END


END

GO


