CREATE PROCEDURE [dbo].[spSaleOrderLoanTmp_GetData_CheckNC4AdvanceInvoice]

	@comp_id			AS INT,
	@lang_id			AS INT,
	@bra_id				AS INT,
	@prof_id			AS INT,
	@user_id			AS INT,

	@tis_guid			as UNIQUEIDENTIFIER


AS

BEGIN

SET NOCOUNT ON;
---------------------------------------------

/*
DECLARE
		@comp_id			AS INT,
		@lang_id			AS INT,
		@bra_id				AS INT,
		@prof_id			AS INT,
		@user_id			AS INT,
		@st_id				AS INT,
		@disc_id			AS INT


select
		@comp_id			=1,
		@lang_id			=2,
		@bra_id				=1,
		@prof_id			=1,
		@user_id			=1,
		@st_id				=34,
		@disc_id			=11
*/
---------------------------------------------

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

	DECLARE @lstatus AS INT

	SET @lstatus = 0


	IF EXISTS(
				SELECT 1 
					FROM tbtempitemstock tis
					INNER JOIN tbItemTransactions tit
						ON	tit.comp_id			= tis.comp_id			AND 
							tit.it_transaction	= tis.it_transaction
					INNER JOIN tbCommercialTransactions tct
						ON	tct.comp_id			= tit.comp_id			AND 
							tct.ct_transaction	= tit.ct_transaction
					INNER JOIN tbDocumentsFile			tdf
						ON	tdf.comp_id			= tct.comp_id			AND 
							tdf.df_id			= tct.df_id
					WHERE	tdf.comp_id					= @comp_id		AND 
							tis.tis_guid				= @tis_guid		AND
							tdf.df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL
				)

		BEGIN
					SET @lstatus = -1
		END


	SELECT @lstatus [status]

	-- -1 : Error , 0 = OK

END
GO




CREATE PROCEDURE [dbo].[spSaleOrderLoanTMP_GetDataByGuid_Grouped]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS

	SET NOCOUNT ON

		BEGIN

			SET DATEFORMAT 'ymd'

			-- --------------------------------------------------------
			-- Testing
			-- --------------------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@guid		UNIQUEIDENTIFIER
				SELECT
					@comp_id	= 1,
					@guid		= 'A076ADAD-94D0-4A18-95A5-E9CAFB618B4A'
			*/
			-- --------------------------------------------------------


			SELECT
				' '																[ ],
				'#' + ' ' + CONVERT(VARCHAR,tsolt.ln_loanPayNumber)				[ln_loanPayNumber],
				tsolt.ln_loanPayDate											[ln_loanPayDate],
				SUM (tsolt.ln_loanPayTotal) + SUM(tsolt.ln_loanPayTaxes)		[Total]

			FROM tbSaleOrderLoanTMP					tsolt		WITH (NOLOCK)

				INNER JOIN tbSalesTerms				tst			WITH (NOLOCK)
				ON	tst.comp_id		= tsolt.comp_id AND
					tst.st_id		= tsolt.st_id

				INNER JOIN tbTempItemStock			ttis		WITH (NOLOCK)
				ON	ttis.comp_id	= tsolt.comp_id AND
					ttis.tis_id		= tsolt.tis_id

				INNER JOIN tbItem					ti			WITH (NOLOCK)
				ON	ti.comp_id		= tsolt.comp_id	AND
					ti.item_id		= ttis.item_id

			WHERE	tsolt.comp_id	= @comp_id		AND
					tsolt.tis_guid	= @guid


			GROUP BY tsolt.ln_loanPayDate,tsolt.ln_loanPayNumber
			ORDER BY tsolt.ln_loanPayDate ASC



		END
GO




CREATE PROCEDURE [dbo].[spSaleOrderLoanTMP_GetDataByGuid_NoGrouping]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS

	SET NOCOUNT ON

		BEGIN

			SET DATEFORMAT 'ymd'

			-- --------------------------------------------------------
			-- Testing
			-- --------------------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@guid		UNIQUEIDENTIFIER
				SELECT
					@comp_id	= 1,
					@guid		= 'A076ADAD-94D0-4A18-95A5-E9CAFB618B4A'
			*/
			-- --------------------------------------------------------

			SELECT
				' '									[ ],
				CONVERT(VARCHAR,ISNULL(tsolt.ln_loanPayNumber,0)) + '/' + CONVERT(VARCHAR,(SELECT COUNT(*)
																			  FROM tbSaleOrderLoanTMP				tsolt2
																			  WHERE tsolt2.comp_id	= tsolt.comp_id AND
																					tsolt2.tis_id	= tsolt.tis_id	AND
																					tsolt2.tis_guid = @guid))					[ln_loanPayNumber],
				ti.item_code,
				ti.item_desc,
				tsolt.ln_loanPayDate,
				--tst.st_desc,
				tsolt.ln_loanPayTotal				[Total]--,
				--tsolt.ln_loanPayTaxes

			FROM tbSaleOrderLoanTMP					tsolt		WITH (NOLOCK)

				INNER JOIN tbSalesTerms				tst			WITH (NOLOCK)
				ON	tst.comp_id		= tsolt.comp_id AND
					tst.st_id		= tsolt.st_id

				INNER JOIN tbTempItemStock			ttis		WITH (NOLOCK)
				ON	ttis.comp_id	= tsolt.comp_id AND
					ttis.tis_id		= tsolt.tis_id

				INNER JOIN tbItem					ti			WITH (NOLOCK)
				ON	ti.comp_id		= tsolt.comp_id	AND
					ti.item_id		= ttis.item_id

			WHERE	tsolt.comp_id	= @comp_id		AND
					tsolt.tis_guid	= @guid

			ORDER BY tsolt.tis_id ASC

		END

GO




CREATE PROCEDURE [dbo].[spSaleOrderPendingReason_Divide]

  (
  	  @comp_id			INT,
  	  @bra_id			INT,
  	  @soh_id 			INT
  )

AS


BEGIN

SET NOCOUNT ON

-- =================================================================================================================
-- Testing
-- =================================================================================================================

/*
	Declare	@comp_id	INT,
  			@bra_id		INT,
  			@soh_id		INT


	Select	@comp_id	= 1,
  			@bra_id		= 1,
  			@soh_id		= 34034


*/

-- =================================================================================================================
-- =================================================================================================================


	DECLARE @soh_id_new INT
	SET		@soh_id_new	= 0

	DECLARE @df_id_soh INT
	SET		@df_id_soh	= 0


	EXEC dbo.spCounters_getNextValue @comp_id, @bra_id, 2, @counter_value = @soh_id_new OUTPUT




	SELECT @soh_id_new


	SELECT
		@df_id_soh =  tsoh.df_id
		FROM tbSaleOrderHeader					tsoh	WITH(NOLOCK)
		WHERE tsoh.comp_id	= @comp_id	AND
			  tsoh.bra_id	= @bra_id	AND
			  tsoh.soh_id   = @soh_id




	IF EXISTS	(SELECT
						tbsoprd.df_id_destiny
						FROM   dbo.tbSaleOrderPendingReasonDivideByDocument			tbsoprd		WITH(NOLOCK)
						WHERE 	tbsoprd.comp_id			 = @comp_id			AND
								tbsoprd.df_id_origin	 = @df_id_soh


				)
	BEGIN
		SELECT 1
	END


	SELECT * FROM tbSaleOrderPendingReasonDivideByDocument tsoprdbd







END
GO




