create PROCEDURE [dbo].[spSaleOrderPendingReason_ValidatePurchaseOrder]
(
	@comp_id				int,
	@bra_id					int,
	@poh_id					INT

)
as

BEGIN

	set nocount on

	-- --------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------
/*
	  DECLARE
		@comp_id				INT,
		@bra_id					INT,
		@poh_id					INT
	  SELECT
		@comp_id				= 1,
		@bra_id					= 1,
		@poh_id					= 208
*/
	-- --------------------------------------------------------------------------


	DECLARE @bolIsOK AS BIT
	SET     @bolIsOK = 'False'


	IF NOT EXISTS ( SELECT
						tpoh.poh_id
						FROM tbPurchaseOrderHeader					tpoh	WITH (NOLOCK)
						WHERE	tpoh.comp_id	= @comp_id	AND
								tpoh.bra_id		= @bra_id	AND
								tpoh.poh_id		= @poh_id
					)

		BEGIN
			SET  @bolIsOK = 'False'
		END
	ELSE
		BEGIN
			SET  @bolIsOK = 'True'
		END

	SELECT @bolIsOK [IsOK]



END

GO








