CREATE PROCEDURE [dbo].[spSaleOrderPreparation_AlertIfHasRMAPending]
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT
)
AS

	BEGIN



		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		SET NOCOUNT ON

		-- -----------------------------------
		-- TESTING
		-- -----------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@soh_id		INT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@soh_id		= 33694
		*/
		-- -----------------------------------

		DECLARE @intCustID AS INT = NULL
		SELECT @intCustID = tsoh.cust_id
			FROM tbSaleOrderHeader tsoh			WITH (NOLOCK)
			WHERE	tsoh.comp_id	= @comp_id	AND
					tsoh.bra_id		= @bra_id	AND
					tsoh.soh_id		= @soh_id



		DECLARE
			@lHasPendingRMA	INT
		SET @lHasPendingRMA	= 0

		IF EXISTS (	SELECT
						tsod.rmad_id
		           		FROM tbSaleOrderHeader						tsoh			WITH (NOLOCK)
		           		INNER JOIN tbSaleOrderDetail				tsod			WITH (NOLOCK)
		           		ON	tsod.comp_id	= tsoh.comp_id	AND
		           			tsod.bra_id		= tsoh.bra_id	AND
		           			tsod.soh_id		= tsoh.soh_id
		           		INNER JOIN tbRMA_Header						trh				WITH (NOLOCK)
		           		ON trh.comp_id		= tsod.comp_id	AND
		           		   trh.bra_id		= tsod.bra_id	AND
		           		   trh.rmah_id		= tsod.rmah_id

						WHERE    tsoh.comp_id			= @comp_id		AND
								 tsoh.cust_id			= @intCustID
								 --tsoh.bra_id			= @bra_id		AND
								 --tsoh.soh_id			= @soh_id
				)
			BEGIN
				SET @lHasPendingRMA = 1
			END

		-- 0 : No tiene rma
		-- 1 : Tiene pedidos de rma pendientes.
		SELECT @lHasPendingRMA						[HasPendingRMA]

	END
GO



CREATE PROCEDURE [dbo].[spSaleOrderPreparation_BlockIfHasNoStock]
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT
)
AS

	BEGIN



		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		SET NOCOUNT ON

		-- -----------------------------------
		-- TESTING
		-- -----------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@soh_id		INT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@soh_id		= 33694
		*/
		-- -----------------------------------

		DECLARE
			@lIntValidator	INT
		SET @lIntValidator	= 0

		--SI ESTA VARIABLE QUEDA > 0 ENTONCES ES QUE AL MENOS UN ARTÏCULO NO TIENE STOCK
		--SI LA VARIABLE QUEDA = 0 ENTONCES TODOS LOS ARTÍCULOS TIENEN STOCK
		SELECT
			@lIntValidator = @lIntValidator +
											CASE
												WHEN dbo.fnGetAStock(@comp_id,tsod.stor_id, tsod.item_id, tsod.sod_priority) < 0 THEN	1
												ELSE																					0
											END
			FROM tbSaleOrderDetail				tsod
			INNER JOIN tbItem ti
				ON  ti.comp_id		= tsod.comp_id	AND
					ti.item_id		= tsod.item_id
			WHERE	tsod.comp_id	= @comp_id	AND
					tsod.bra_id		= @bra_id	AND
					tsod.soh_id		= @soh_id	AND
					tsod.item_id	IS NOT NULL AND
					tsod.sod_qty	<> 0		AND
					ISNULL(ti.item_NoStockCheck,'False') = 'False'

		SELECT @lIntValidator

	END
GO






