------------------------------------------------------------------------
-- Date : 23/08/2013
-- Description : Si en transferencias internas no estan completas todas
--				 las transferencias muestra o no mje.
-- GA
------------------------------------------------------------------------
------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spSaleOrderPreparation_BlockIfInternalTransferIncomplete]
(
    @comp_id		    int,
	@bra_id				int,
	@soh_id				int
)
as
set nocount on



BEGIN

	-- -------------------------------
	-- Parámetros de Prueba
	-- -------------------------------
/*
	DECLARE	@comp_id		as  int,
			@bra_id			as	int,
			@soh_id			as	int


	SELECT  @comp_id		=1,
			@bra_id			=1,
			@soh_id			=32968
*/

	-- -------------------------------

			declare @lstatus INT
			SET @lstatus	= 	1

			declare @lBlockIfInternalTransferIncomplete BIT

			SET @lBlockIfInternalTransferIncomplete =(SELECT isnull(tdf.df_SaleOrderPreparation_BlockIfInternalTransferIncomplete,'false')

														from	dbo.tbSaleOrderHeader				soh		WITH (NOLOCK)


														LEFT JOIN tbDocumentsFile			tdf				WITH (NOLOCK)
														ON	tdf.comp_id		= soh.comp_id
														AND tdf.df_id		= soh.df_id


														where	soh.comp_id		= @comp_id
														and		soh.bra_id		= @bra_id
														and		soh.soh_id		= @soh_id)

			--SELECT @lBlockIfInternalTransferIncomplete


			IF 	@lBlockIfInternalTransferIncomplete = 'True'
			BEGIN

				set	@lstatus	= null

				--si existe en el pedido una transferencia que no este recibida

				IF exists (	SELECT tstt.soh_id
				   	            	FROM tbStorage_TransferTransactions tstt				WITH (NOLOCK)
									WHERE    tstt.comp_id			= @comp_id		AND
											 tstt.soh_bra_id		= @bra_id		AND
											 tstt.soh_id			= @soh_id		AND
											 tstt.stt_isCompleted	= 'False'
							)

						--Hay alguno que no esta recibido o ninguno esta recibido !
						BEGIN
							SET @lstatus	= 	0
						END



				ELSE
					BEGIN
						IF  exists (	SELECT tstt.soh_id
				   	            			FROM tbStorage_TransferTransactions tstt			WITH (NOLOCK)
											WHERE     tstt.comp_id			= @comp_id		AND
													  tstt.soh_bra_id		= @bra_id		AND
													  tstt.soh_id			= @soh_id
									)

							BEGIN
								SET @lstatus	= 	1	-- Hay transferencia y ya esta aceptada
							END
						ELSE
							BEGIN
								SET @lstatus	= 	0	-- No hay ninguna solicitud de transferencia
							END

					END

			END

			-- 0 Hay alguno que no esta recibido o ninguno esta recibido !
			-- 1 ESTAN TODOS RECIBIDOS !
			--
			SELECT @lstatus [Status]
			----






END
GO


