CREATE PROCEDURE [dbo].[spSaleOrderPreparation_checkCRMCallUnfinished]
	@comp_id			AS INT,
	@bra_id				AS INT,
	@prof_id			AS INT,
	@user_id			AS INT,
	@df_id				AS INT,
	@soh_bra_id			AS INT,
	@soh_id				AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	IF EXISTS(
				SELECT 1
				FROM tbCRM_Call_SaleOrderEmmitionBlock  tctsoeb WITH (NOLOCK)
					WHERE	tctsoeb.comp_id		= @comp_id	AND
							tctsoeb.df_id		= @df_id	AND
							tctsoeb.isDisabled	= 'False'
				)

		BEGIN

			IF EXISTS(
						SELECT 1
						FROM tbCRM_Call  tct						WITH (NOLOCK)
							INNER JOIN tbCRM_CallStatus tcts		WITH (NOLOCK)
								ON	tcts.comp_id			= tct.comp_id AND
									tcts.callst_id			= tct.callst_id
							WHERE	tct.comp_id				= @comp_id		AND
									tct.soh_Bra_id			= @soh_bra_id	AND
									tct.soh_soh_id			= @soh_id		AND
									tcts.callst_isFinalStatus = 'False'
					)
				BEGIN
					SELECT -1 [status]
				END

		END


	SELECT 0 [status]

END
GO


