-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spSaleOrderPreparation_checkCRMTaskUnfinished]
	@comp_id			AS INT,
	@bra_id				AS INT,
	@prof_id			AS INT,
	@user_id			AS INT,
	@df_id				AS INT,
	@soh_bra_id			AS INT,
	@soh_id				AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	IF EXISTS(
				SELECT 1
					FROM tbCRM_Task_SaleOrderEmmitionBlock tctsoeb WITH (NOLOCK)
					WHERE	tctsoeb.comp_id		= @comp_id	AND
							tctsoeb.df_id		= @df_id	AND
							tctsoeb.isDisabled	= 'False'
				)

		BEGIN

			IF EXISTS(
						SELECT 1
							FROM tbCRM_Task tct						WITH (NOLOCK)
							INNER JOIN tbCRM_TaskStatus tcts		WITH (NOLOCK)
								ON	tcts.comp_id			= tct.comp_id AND
									tcts.tast_id			= tct.tast_id
							WHERE	tct.comp_id				= @comp_id		AND
									tct.soh_Bra_id			= @soh_bra_id	AND
									tct.soh_soh_id			= @soh_id		AND
									tcts.tast_isFinalStatus = 'False'
					)
				BEGIN
					SELECT -1 [status]
				END

		END


	SELECT 0 [status]

END
GO







CREATE PROCEDURE [dbo].[spSaleOrderPreparation_getDataForGenericGrid]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@soh_id		INT
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


		-- ----------------------------------------------------------
		-- Testing
		-- ----------------------------------------------------------
/*
			DECLARE
				@comp_id	INT,
				@soh_id		INT,
				@lang_id	INT,
				@bra_id		int
			SELECT
				@comp_id	= 1,
				@soh_id		= 33650,
				@lang_id	= 2,
				@bra_id		= 1
*/
		-- ----------------------------------------------------------


		-- ----------------------------------------------------------
		-- Se cargan las definiciones de Stock
		-- ----------------------------------------------------------
		DECLARE
			@message1	VARCHAR (200),
			@message2	VARCHAR (200),
			@message3	VARCHAR (200)

		SELECT
			@message1 = tov.optval_desc
		FROM tbsysOptionsValues tov
		WHERE tov.optval_class = 100
		AND tov.optval_id = 0
		AND tov.lang_id = @lang_id

		SELECT
			@message2 = tov.optval_desc
		FROM tbsysOptionsValues tov
		WHERE tov.optval_class = 100
		AND tov.optval_id = 1
		AND tov.lang_id = @lang_id

		SELECT
			@message3 = tov.optval_desc
		FROM tbsysOptionsValues tov
		WHERE tov.optval_class = 100
		AND tov.optval_id = 2
		AND tov.lang_id = @lang_id

		-- ----------------------------------------------------------


		SELECT
			ti.item_code,
			ti.item_desc,
			ts.stor_desc,
			tsod.sod_qty,
			CASE
			    WHEN ti.item_expser = 'True'	THEN	'*'
			    ELSE									' '
			END																			[item_expser],
			CASE
				WHEN ti.item_expean = 'True'	THEN	'*'
				ELSE									' '
			END																			[item_expean],
			CASE
				WHEN ti.item_NoStockCheck = 'True'	THEN	'*'
				ELSE									' '
			END																			[item_NoStockCheck],
			tu.user_lastname + ' ,' + tu.user_firstname									[name],
			CASE
				WHEN dbo.fnGetAStock(tsod.comp_id,tsod.stor_id,tsod.item_id,tsod.sod_priority)	< 0							THEN @message1
				WHEN tsod.sod_qty																> IsNull(tis.itst_cant,0)	THEN @message2
				ELSE																											 @message3
			END																			[Disp],
			dbo.fnGetAStock(tsod.comp_id,tsod.stor_id,tsod.item_id,tsod.sod_priority)	[Potential],
			tsod.sod_note1,
			tsod.sod_note2,
			tsod.sod_itemDeliveryDate,
			tsod.sod_priority															[priority]

			FROM tbSaleOrderDetail tsod

				INNER JOIN tbItem ti
				ON  ti.comp_id = tsod.comp_id
				AND ti.item_id = tsod.item_id

				INNER JOIN tbUser tu
				ON	tu.[user_id] = tsod.[user_id]

				INNER JOIN tbItemStorage tis
					ON		tis.comp_id = tsod.comp_id
						AND tis.item_id = tsod.item_id
						AND tis.stor_id = tsod.stor_id

				INNER JOIN tbStorage ts
					ON	ts.comp_id = @comp_id AND
						ts.stor_id = tsod.stor_id

			WHERE	tsod.comp_id	= @comp_id
				AND tsod.bra_id		= @bra_id
				AND	tsod.soh_id		= @soh_id
			ORDER BY ts.stor_desc,tsod.sod_id,ti.item_desc

	-- NO va esto.  MOS
	--	UNION
	--
	--
	--	SELECT
	--		ti.item_desc,
	--		ttis.tis_qty,
	--		tu.user_lastname + ' ,' + tu.user_firstname [name],
	--		ttis.tis_priority [priority]
	--
	--	FROM tbTempItemStock ttis
	--
	--		INNER JOIN tbItem ti
	--		ON ti.comp_id = ttis.comp_id
	--		AND ti.item_id = ttis.item_id
	--
	--		INNER JOIN tbUser tu
	--		ON tu.[user_id] = ttis.[user_id]
	--
	--	WHERE	ttis.comp_id	= @comp_id
	--	AND		ttis.soh_id		= @soh_id

		--ORDER BY  tsod. DESC



END
GO







CREATE procedure [dbo].[spSaleOrderPreparation_getLabels]
(
	@comp_id			INT,
	@lang_id			INT,

	@cust_id			INT,
	@copias				INT,
	@bultos				INT,
	@bra_id				INT,
	@dl_id				INT,
	@soh_id				INT
)
AS
BEGIN
	SET NOCOUNT ON
	-- -----------------------------------------------------
	-- TESTING
	-- -----------------------------------------------------
	/*
		DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@page_id			INT,

			@cust_id			INT,
			@copias				INT,
			@bultos				INT,
			@bra_id				INT,
			@dl_id				INT


		SELECT
			@comp_id			=1,
			@lang_id			=2,
			@page_id			=10059,

			@cust_id			=24288,
			@copias				=1,
			@bultos				=1,
			@bra_id				=1,
			@dl_id				=4

		--	DROP TABLE #tmpLabels
	*/
	-- -----------------------------------------------------

	/* ANOTACIÓN
	* ***************************************************************************************************
	Esto es si te ponen 2 copias y 3 bultos y la definición pide 4 etiqueta por hoja, se debería imprimir

	Hoja 1

			 Etiqueta 1      bulto 1 de 3 (cada etiqueta con los datos que se indican arriba)
			 Etiqueta 2      bulto 1 de 3
			 Etiqueta 3      bulto 2 de 3
			 Etiqueta 4      bulto 2 de 3

	Hoja 2

			 Etiqueta 1      bulto 3 de 3
			 Etiqueta 2      bulto 3 de 3

	--         Nombre del Cliente, domicilio, CP, provincia, Pais, Teléfono
	--         Transporte (dl_id) tomado de tbDelivety (Nombre, domicilio, teléfono)
	* ***************************************************************************************************
	*/

	CREATE TABLE #tmpLabels
	(
		[description]	NVARCHAR(200) NULL,
		[cust_name]		NVARCHAR(200) NULL,
		[cust_address]	NVARCHAR(400) NULL,
		[delivery]		NVARCHAR(400) NULL,
		[remite]		NVARCHAR(400) NULL,
		[company]		NVARCHAR(400) NULL,				--STL se agrega la desc de la comp
		[cust2record]	NVARCHAR(400) NULL				--STL segundo renglon del Cliente
	)

	-- ----------------------------------------
	-- VARIABLES DE TRABAJO
	-- ----------------------------------------
		DECLARE
			@cust_name		NVARCHAR(200),
			@cust_address	NVARCHAR(400),
			@delivery		NVARCHAR(400),
			@remite			NVARCHAR(400),
			@company		NVARCHAR(400),
			@cust2rec		NVARCHAR(400)
	-- ----------------------------------------

	-- -----------------------
	-- INDICES
	-- -----------------------
		DECLARE
			@intBultos	INT,
			@intCopias	INT
	-- -----------------------

	-- --------------------------------------------------------------------------------------
	-- REEMPLAZO ESTAS VARIABLES POR LAS DE ARRIBA PORQUE NO SE ENTIENDE QUE SON NI QUE HACEN
	-- --------------------------------------------------------------------------------------
		--DECLARE @i AS integer
		--DECLARE @j AS integer
	-- --------------------------------------------------------------------------------------

	-- ---------------------------------------
	-- TEXTOS
	-- ---------------------------------------
		DECLARE
			@bulto   		NVARCHAR(20),
			@de				NVARCHAR(10),
			@transporte		NVARCHAR(20),
			@remite_text    NVARCHAR(20),

			@salesman		NVARCHAR(20), -- Vendedor:
			@date	        NVARCHAR(20)  -- Fecha:

	-- ---------------------------------------


	SET @bulto = (SELECT tut.utexts_desc
					  FROM tbsysUniqueTexts tut			WITH (NOLOCK)
					  WHERE tut.lang_id = @lang_id
					  AND tut.utexts_id = 224008)
	--SELECT @bulto

	SET @de = (SELECT tut.utexts_desc
				   FROM tbsysUniqueTexts tut			WITH (NOLOCK)
				   WHERE tut.lang_id = @lang_id
				   AND tut.utexts_id = 224007)
	--SELECT @de
	SET @transporte = (SELECT tut.utexts_desc
						   FROM tbsysUniqueTexts tut		WITH (NOLOCK)
						   WHERE tut.lang_id = @lang_id
						   AND tut.utexts_id = 224009)

	--SET @date = (SELECT tut.utexts_desc
	--						FROM tbsysUniqueTexts tut		WITH (NOLOCK)
	--						WHERE tut.lang_id = @lang_id
	--						AND tut.utexts_id = 6001)

	--SELECT @remite_text
	SET @remite_text = (SELECT tut.utexts_desc
						   FROM tbsysUniqueTexts tut		WITH (NOLOCK)
						   WHERE tut.lang_id = @lang_id
						   AND tut.utexts_id = 224010)

	--Agregar en tbsysuniquetexts 'BULTO' y 'DE'
	--Recuperarlos en 2 variables con 2 getdatabyid


	-------------------------

	SET @salesman = (SELECT
					  tut.utexts_desc
					  FROM tbsysUniqueTexts tut			WITH (NOLOCK)
					  WHERE tut.lang_id = @lang_id
					  AND tut.utexts_id = 300011) + ':'

	--SET @bulto = (SELECT
	--				tut.utexts_desc
	--				FROM tbsysUniqueTexts tut			WITH (NOLOCK)
	--				WHERE tut.lang_id = @lang_id
	--				AND tut.utexts_id = 224008)

	SET @date = (SELECT tut.utexts_desc
							FROM tbsysUniqueTexts tut		WITH (NOLOCK)
							WHERE tut.lang_id = @lang_id
							AND tut.utexts_id = 6001)

	--OBTENEMOS EL SALEORDER NUMBER CON LA FUNCIÓN
	DECLARE
		@soh_NUMBER	VARCHAR(20),
		@strNUMBER	VARCHAR(50),
		@custb_id	INT,
		@soh_deliveryAddress AS NVARCHAR(4000)



	SELECT
		@soh_NUMBER				= dbo.fnGetSaleOrderNumber(@comp_id, @bra_id, @soh_id),
		@custb_id				=  tsoh.cb_id,
		@soh_deliveryAddress	= tsoh.soh_deliveryAddress
		FROM tbSaleOrderHeader				tsoh	WITH(NOLOCK)
		WHERE	tsoh.comp_id	= @comp_id	AND
				tsoh.bra_id		= @bra_id	AND
				tsoh.soh_id		= @soh_id

	SET @soh_deliveryAddress = dbo.fnStrAllTrim( ISNULL(@soh_deliveryAddress,'') )

	set @intBultos = 1

	WHILE @intBultos <= @bultos
	  BEGIN

  		set @intCopias = 1
		 WHILE @intCopias <= @copias
			BEGIN

				SELECT
					@cust_name    =		CASE
											WHEN tcb.comp_id IS NOT NULL THEN tcb.custb_name
											ELSE  ISNULL(tc.cust_name,'')
										END,

					@cust_address =
									CASE
										WHEN @soh_deliveryAddress <> ''					THEN @soh_deliveryAddress
										WHEN tcb.comp_id IS NOT NULL					THEN tcb.custb_address + ' / ' + tcb.custb_zip + ' / ' + tcb.custb_city
										WHEN ISNULL(tc.cust_address4Delivery,'') <> ''	THEN
											tc.cust_address4Delivery
										ELSE
												ISNULL(tc.cust_address,'')  + ' / ' +
												ISNULL(tc.cust_zip,'')	   + ' / ' +
												ISNULL(tc.cust_city, '')
									END,

					@delivery     =
												ISNULL(td.dl_name,'')       + ' / ' +
												ISNULL(td.dl_address,'')    + ' / ' +
												ISNULL(td.dl_phone,'')											,


					@remite		 =  CASE	-- MOS 10-2021
										WHEN dbo.fnStrAllTrim( ISNULL(tb.bra_SOPrep_FromAddress,'')) <> ''	THEN tb.bra_SOPrep_FromAddress
										ELSE
																												ISNULL(tb.bra_address,'')   + ' / ' +
																												ISNULL(tb.bra_address1,'')  + ' / ' +
																												ISNULL(tb.bra_zip, '')		+ ' / ' +
																												ISNULL(tb.bra_desc,'')      + ' / ' +
																												ISNULL(tb.bra_phone,'')
									END
,


					@company	=
									CASE
										WHEN dbo.fnStrAllTrim( ISNULL(tb.bra_SOPrep_FromBranchsName,'')) <> ''	THEN tb.bra_SOPrep_FromBranchsName
										ELSE
																													ISNULL(tb.bra_MainDesc,'')
									END
					,

					@cust2rec	=	CASE	-- MOS 10-2021
										WHEN @soh_deliveryAddress <> '' THEN	ISNULL(tc.cust_phone1,'')
										ELSE 									ISNULL(ts2.state_desc,ISNULL(ts.state_desc,''))    + ' / ' +
																				ISNULL(tc2.country_desc,'') + ' / ' +
																				ISNULL(tc.cust_phone1,'')
									END

    				FROM tbCustomer								tc		WITH(NOLOCK)
    					LEFT JOIN tbCustomerBranch			 AS tcb		WITH (NOLOCK)
    						ON	tcb.comp_id = @comp_id AND
    							tcb.cust_id = @cust_id AND
    							tcb.cb_id	= @custb_id
						INNER JOIN tbsysCountry					tc2		WITH(NOLOCK)
							ON tc2.country_id	= tc.country_id
						INNER JOIN tbsysState					ts		WITH(NOLOCK)
							ON	ts.country_id	= tc.country_id	AND
								ts.state_id		= tc.state_id
						LEFT JOIN tbsysState					ts2		WITH(NOLOCK)
							ON	ts2.country_id	= tcb.country_id	AND
								ts2.state_id	= tcb.state_id
						INNER JOIN tbDelivery					td		WITH(NOLOCK)
							ON  td.comp_id		= tc.comp_id	AND
								td.dl_id		= @dl_id
						LEFT JOIN tbBranch						tb		WITH(NOLOCK)
							ON  tb.comp_id		= tc.comp_id	AND
								tb.bra_id		= @bra_id
		--		    LEFT JOIN tbCities tc3
		--		    ON  tc3.country_id = tb.country_id
		--		    AND tc3.state_id   = tb.state_id		--STL Se quita el Join debido a que la tabla TBBRANCH no tiene un CITY_ID
					WHERE		tc.[comp_id]	= @comp_id		AND
								tc.cust_id		= @cust_id


				INSERT INTO #tmpLabels
					(
						[description],
						[cust_name],
						[cust_address],
						[delivery],
						[remite],
						[company],
						[cust2record]
					)
				VALUES
					(
						 @bulto + ' ' + CONVERT(VARCHAR,@intBultos) + ' ' + @de + ' ' +CONVERT(VARCHAR,@bultos),
						 @cust_name,
						 @cust_address,
						 @transporte + ' ' + @delivery,
						 @remite_text + ' ' + @company,	--@remite
						 @remite,
						 @cust2rec
					)

			SET @intCopias = @intCopias + 1
		  END
		SET @intBultos = @intBultos + 1
	  END





	--RECUPERAMOS LA LEYENDA
	SELECT
		@strNUMBER = tut.utexts_desc
		FROM tbsysUniqueTexts			tut		WITH(NOLOCK)
		WHERE	tut.lang_id		= 2		AND
				tut.utexts_id	= 30577


	--SELECT FINAL
	SELECT
		*,
		@soh_NUMBER	[soh_NUMBER],
		@strNUMBER	[soh_NUMBER_TITLE]
		FROM #tmpLabels

END
GO



CREATE procedure [dbo].[spSaleOrderPreparation_getLabels_Aditional]
(
	@comp_id			INT,
	@lang_id			INT,

	@cust_id			INT,
	@copias				INT,
	@bultos				INT,
	@bra_id				INT,
	@dl_id				INT,
	@soh_id				INT
)
AS


BEGIN
	SET NOCOUNT ON
	-- -----------------------------------------------------
	-- TESTING
	-- -----------------------------------------------------
	/*
		DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@page_id			INT,

			@cust_id			INT,
			@copias				INT,
			@bultos				INT,
			@bra_id				INT,
			@dl_id				INT,
			@soh_id				INT


		SELECT
			@comp_id			=1,
			@lang_id			=2,
			@page_id			=10059,

			@cust_id			=24288,
			@copias				=1,
			@bultos				=1,
			@bra_id				=1,
			@dl_id				=4,
			@soh_id				= 34620 --34602

			DROP TABLE #tmpLabels
			*/
	-- -----------------------------------------------------

	/* ANOTACIÓN
	* ***************************************************************************************************
	Esto es si te ponen 2 copias y 3 bultos y la definición pide 4 etiqueta por hoja, se debería imprimir

	Hoja 1

			 Etiqueta 1      bulto 1 de 3 (cada etiqueta con los datos que se indican arriba)
			 Etiqueta 2      bulto 1 de 3
			 Etiqueta 3      bulto 2 de 3
			 Etiqueta 4      bulto 2 de 3

	Hoja 2

			 Etiqueta 1      bulto 3 de 3
			 Etiqueta 2      bulto 3 de 3

	--         Nombre del Cliente, domicilio, CP, provincia, Pais, Teléfono
	--         Transporte (dl_id) tomado de tbDelivety (Nombre, domicilio, teléfono)
	* ***************************************************************************************************
	*/

	CREATE TABLE #tmpLabels
	(
		[description]	NVARCHAR(200) NULL,
		[cust_name]		NVARCHAR(200) NULL,
		[cust_address]	NVARCHAR(400) NULL,
		[delivery]		NVARCHAR(400) NULL,
		[remite]		NVARCHAR(400) NULL,
		[company]		NVARCHAR(400) NULL,				--STL se agrega la desc de la comp
		[cust2record]	NVARCHAR(400) NULL,				--STL segundo renglon del Cliente
		[salesman]		NVARCHAR(400) NULL,				-- vendedor
		[date]			NVARCHAR(400) NULL				-- fecha de cierre del pedido

	)

	-- ----------------------------------------
	-- VARIABLES DE TRABAJO
	-- ----------------------------------------
		DECLARE
			@cust_name		NVARCHAR(200),
			@cust_address	NVARCHAR(400),
			@delivery		NVARCHAR(400),
			@remite			NVARCHAR(400),
			@company		NVARCHAR(400),
			@cust2rec		NVARCHAR(400),
			@salesman		NVARCHAR(400),
			@date			NVARCHAR(400)

	-- ----------------------------------------

	-- -----------------------
	-- INDICES
	-- -----------------------
		DECLARE
			@intBultos	INT,
			@intCopias	INT
	-- -----------------------

	-- --------------------------------------------------------------------------------------
	-- REEMPLAZO ESTAS VARIABLES POR LAS DE ARRIBA PORQUE NO SE ENTIENDE QUE SON NI QUE HACEN
	-- --------------------------------------------------------------------------------------
		--DECLARE @i AS integer
		--DECLARE @j AS integer
	-- --------------------------------------------------------------------------------------

	-- ---------------------------------------
	-- TEXTOS
	-- ---------------------------------------
		DECLARE
			@bulto   		NVARCHAR(20),
			@de				NVARCHAR(10),
			@transporte		NVARCHAR(20),
			@remite_text    NVARCHAR(20),

			@salesman_text	NVARCHAR(20), -- Vendedor:
			@date_text	    NVARCHAR(20)  -- Fecha:

	-- ---------------------------------------


	SET @bulto = (SELECT tut.utexts_desc
					  FROM tbsysUniqueTexts tut			WITH (NOLOCK)
					  WHERE tut.lang_id = @lang_id
					  AND tut.utexts_id = 224008)
	--SELECT @bulto

	SET @de = (SELECT tut.utexts_desc
				   FROM tbsysUniqueTexts tut			WITH (NOLOCK)
				   WHERE tut.lang_id = @lang_id
				   AND tut.utexts_id = 224007)
	--SELECT @de
	SET @transporte = (SELECT tut.utexts_desc
						   FROM tbsysUniqueTexts tut		WITH (NOLOCK)
						   WHERE tut.lang_id = @lang_id
						   AND tut.utexts_id = 224009)

	--SELECT @remite_text
	SET @remite_text = (SELECT tut.utexts_desc
						   FROM tbsysUniqueTexts tut		WITH (NOLOCK)
						   WHERE tut.lang_id = @lang_id
						   AND tut.utexts_id = 224010)

	--Agregar en tbsysuniquetexts 'BULTO' y 'DE'
	--Recuperarlos en 2 variables con 2 getdatabyid


	-------------------------

	SET @salesman_text = (SELECT
					  tut.utexts_desc
					  FROM tbsysUniqueTexts tut			WITH (NOLOCK)
					  WHERE tut.lang_id = @lang_id
					  AND tut.utexts_id = 300011) + ':'

	SET @date_text = (SELECT tut.utexts_desc
							FROM tbsysUniqueTexts tut		WITH (NOLOCK)
							WHERE tut.lang_id = @lang_id
							AND tut.utexts_id = 6001)

	--OBTENEMOS EL SALEORDER NUMBER CON LA FUNCIÓN
	DECLARE
		@soh_NUMBER	VARCHAR(20),
		@strNUMBER	VARCHAR(50),
		@custb_id	INT,
		@soh_deliveryAddress AS NVARCHAR(4000),
		@sm_name	VARCHAR(200),
		@sot_cd     DATETIME



	SELECT top 1
		@soh_NUMBER				= dbo.fnGetSaleOrderNumber(@comp_id, @bra_id, @soh_id),
		@custb_id				= tsoh.cb_id,
		@soh_deliveryAddress	= tsoh.soh_deliveryAddress,
		@sm_name				= ts.sm_name,
		@sot_cd					= tsot.sot_cd

		FROM tbSaleOrderHeader				tsoh	WITH(NOLOCK)

		LEFT JOIN tbSalesman			    ts		WITH(NOLOCK)
		ON  ts.comp_id  = tsoh.comp_id		AND
			ts.sm_id	= tsoh.sm_id

		left join tbSaleOrderTimes			tsot	WITH (NOLOCK)
		ON  tsot.comp_id = tsoh.comp_id	    AND
			tsot.bra_id  = tsoh.bra_id	    AND
			tsot.soh_id  = tsoh.soh_id		AND
			tsot.ssot_id	= 40

		WHERE	tsoh.comp_id	= @comp_id	AND
				tsoh.bra_id		= @bra_id	AND
				tsoh.soh_id		= @soh_id

	SET @soh_deliveryAddress = dbo.fnStrAllTrim( ISNULL(@soh_deliveryAddress,'') )

	set @intBultos = 1

	WHILE @intBultos <= @bultos
	  BEGIN

  		set @intCopias = 1
		 WHILE @intCopias <= @copias
			BEGIN

				SELECT
					@cust_name    =		CASE
											WHEN tcb.comp_id IS NOT NULL THEN tcb.custb_name
											ELSE  ISNULL(tc.cust_name,'')
										END,

					@cust_address =
									CASE
										WHEN @soh_deliveryAddress <> ''					THEN @soh_deliveryAddress
										WHEN tcb.comp_id IS NOT NULL					THEN tcb.custb_address + ' / ' + tcb.custb_zip + ' / ' + tcb.custb_city
										WHEN ISNULL(tc.cust_address4Delivery,'') <> ''	THEN
											tc.cust_address4Delivery
										ELSE
												ISNULL(tc.cust_address,'')  + ' / ' +
												ISNULL(tc.cust_zip,'')	   + ' / ' +
												ISNULL(tc.cust_city, '')
									END,

					@delivery     =
												ISNULL(td.dl_name,'')       + ' / ' +
												ISNULL(td.dl_address,'')    + ' / ' +
												ISNULL(td.dl_phone,'')											,


					@remite		 =  CASE	-- MOS 10-2021
										WHEN dbo.fnStrAllTrim( ISNULL(tb.bra_SOPrep_FromAddress,'')) <> ''	THEN tb.bra_SOPrep_FromAddress
										ELSE
																												ISNULL(tb.bra_address,'')   + ' / ' +
																												ISNULL(tb.bra_address1,'')  + ' / ' +
																												ISNULL(tb.bra_zip, '')		+ ' / ' +
																												ISNULL(tb.bra_desc,'')      + ' / ' +
																												ISNULL(tb.bra_phone,'')
									END
					,


					@company	=
									CASE
										WHEN dbo.fnStrAllTrim( ISNULL(tb.bra_SOPrep_FromBranchsName,'')) <> ''	THEN tb.bra_SOPrep_FromBranchsName
										ELSE
																													ISNULL(tb.bra_MainDesc,'')
									END
					,

					@cust2rec	=	CASE	-- MOS 10-2021
										WHEN @soh_deliveryAddress <> '' THEN	ISNULL(tc.cust_phone1,'')
										ELSE 									ISNULL(ts2.state_desc,ISNULL(ts.state_desc,''))    + ' / ' +
																				ISNULL(tc2.country_desc,'') + ' / ' +
																				ISNULL(tc.cust_phone1,'')
					         	 	END
					,

					@salesman   = @salesman_text + ' ' + @sm_name	      -- vendedor
					,
					@date		= @date_Text     + ' ' +
								  convert(varchar,day(@sot_cd))+'/'+
								  convert(varchar,month(@sot_cd))+'/'+
								  convert(varchar,year(@sot_cd))  -- 'fecha de cierre del pedido'


    				FROM tbCustomer								tc		WITH(NOLOCK)
    					LEFT JOIN tbCustomerBranch				tcb		WITH (NOLOCK)
    						ON	tcb.comp_id		= @comp_id		AND
    							tcb.cust_id		= @cust_id		AND
    							tcb.cb_id		= @custb_id
						INNER JOIN tbsysCountry					tc2		WITH(NOLOCK)
							ON tc2.country_id	= tc.country_id
						INNER JOIN tbsysState					ts		WITH(NOLOCK)
							ON	ts.country_id	= tc.country_id	AND
								ts.state_id		= tc.state_id
						LEFT JOIN tbsysState					ts2		WITH(NOLOCK)
							ON	ts2.country_id	= tcb.country_id	AND
								ts2.state_id	= tcb.state_id
						INNER JOIN tbDelivery					td		WITH(NOLOCK)
							ON  td.comp_id		= tc.comp_id	AND
								td.dl_id		= @dl_id
						LEFT JOIN tbBranch						tb		WITH(NOLOCK)
							ON  tb.comp_id		= tc.comp_id	AND
								tb.bra_id		= @bra_id
		--		    LEFT JOIN tbCities tc3
		--		    ON  tc3.country_id = tb.country_id
		--		    AND tc3.state_id   = tb.state_id		--STL Se quita el Join debido a que la tabla TBBRANCH no tiene un CITY_ID
					WHERE		tc.[comp_id]	= @comp_id		AND
								tc.cust_id		= @cust_id


				INSERT INTO #tmpLabels
					(
						[description],
						[cust_name],
						[cust_address],
						[delivery],
						[remite],
						[company],
						[cust2record],
						[salesman],
						[date]
					)
				VALUES
					(
						 @bulto + ' ' + CONVERT(VARCHAR,@intBultos) + ' ' + @de + ' ' + CONVERT(VARCHAR,@bultos),
						 @cust_name,
						 @cust_address,
						 @transporte    + ' ' + @delivery,
						 @remite_text   + ' ' + @company,	--@remite
						 @remite,
						 @cust2rec,
						 @salesman,
						 @date
					)

			SET @intCopias = @intCopias + 1
		  END
			SET @intBultos = @intBultos + 1
	  END





	--RECUPERAMOS LA LEYENDA " Pedido # "
	SELECT
		@strNUMBER = tut.utexts_desc
		FROM tbsysUniqueTexts			tut		WITH(NOLOCK)
		WHERE	tut.lang_id		= 2		AND
				tut.utexts_id	= 30577


	--SELECT FINAL
	SELECT
		*,
		@soh_NUMBER	[soh_NUMBER],
		@strNUMBER	[soh_NUMBER_TITLE]
		FROM #tmpLabels

END
GO





