-- 24/04/2017
-- Preparar y serializar pedidos - Insertar nº de serie desde archivo de txt.
--------------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spSaleOrderPreparation_InsertSerial]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id    INT,
	@user_id    INT,
	@soh_id		INT,
	@is_serial  NVARCHAR(100),
	@guid		UNIQUEIDENTIFIER


)
AS



BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	-- --------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@prof_id    INT,
			@user_id    INT,
			@soh_id		INT,
			@is_serial  NVARCHAR(100),
			@guid		VARCHAR(50)

		SELECT
			@comp_id	=1,
			@lang_id	=2,
			@bra_id		=1,
			@prof_id    =1,
			@user_id    =1,
			@soh_id		=33477,
			@is_serial  ='V09300G10400494'


*/

	-- --------------------------------------------------------

	--Recuperamos el is_id si existe y si esta disponible el serial.
	DECLARE @lis_id AS INT
	SET @lis_id = (SELECT
					top 1 tis.is_id
					FROM tbItemSerials						tis		WITH (NOLOCK)
					WHERE	tis.comp_id		= @comp_id		AND
							tis.is_serial	= @is_serial	AND
							tis.is_available = 'True')

	IF @lis_id IS NOT NULL
			BEGIN
				--AHORA VERIFICAMOS Si NO existe EN tbSaleOrderSerials
				IF	NOT EXISTS (
								SELECT
									tsos.sose_id
									FROM tbSaleOrderSerials tsos		WITH (NOLOCK)
									WHERE	tsos.comp_id		= @comp_id		AND
											--tsos.bra_id			= @bra_id		AND
											--tsos.soh_id			= @soh_id		AND
											tsos.is_id			= @lis_id
								)	AND
					NOT EXISTS (
								SELECT 1
									FROM tbTempItemStock ttis			WITH (NOLOCK)
									WHERE	ttis.comp_id	= @comp_id AND
											ttis.is_id		= @lis_id
								)

					BEGIN

						-- SI NO EXISTE LO AGREGAMOS.

						INSERT INTO tbSaleOrderSerials	WITH (ROWLOCK)
						(
							comp_id,
							is_id,
							bra_id,
							soh_id,
							sose_guid
						)
						VALUES
						(
							@comp_id,
							@lis_id,
							@bra_id,
							@soh_id,
							@guid
						)

					END

			END





END


		--IF EXISTS (
		--			SELECT
		--				tis.is_id
		--				FROM tbItemSerials						tis
		--				WHERE	tis.comp_id		= @comp_id		AND
		--						tis.is_serial	= @is_serial	AND
		--						tis.is_available = 'True'
		--			)
		--	BEGIN
		--	END

GO




-- ----------------------------------------------------
-- Author : MOS
-- Date   : 02/06/15
-- Desc   : Preparacion de Turnos en base a la fecha
-- ----------------------------------------------------

CREATE procedure [dbo].[spSaleOrderPreparation_Turns_GenerateTurns]
(
		@comp_id			int,
		@lang_id			int,
		@bra_id				int,
		@prof_id			int,
		@user_id			int,
		@date4Turn			DATETIME
)
as


BEGIN


		SET NOCOUNT ON
		set DATEFORMAT 'ymd'



		--  --------------------------------------------------------------------------------------------------
		-- Testing
		--  --------------------------------------------------------------------------------------------------
		/*
		DECLARE 		@comp_id			int,
						@lang_id			int,
						@bra_id				int,
						@prof_id			int,
						@user_id			int,
						@date4Turn			DATETIME

		SELECT			@comp_id			= 1,
						@lang_id			= 2,
						@bra_id				= 1,
						@prof_id			= 1,
						@user_id			= 1,
						@date4Turn			= '06/22/2015'
		*/
		-- --------------------------------------------------------------------------------------------------




		SET DATEFIRST 7 -- Domingo x Defecto


		DECLARE @intDayofweek AS INT
		SET		@intDayofweek	= datepart(dw,@date4Turn)
		SET		@date4Turn		= dbo.fnGetEnd_or_BeginOfDate(@date4Turn,'False')


		INSERT INTO tbSaleOrderAssemblyTurns
		(
			comp_id,
			soa_turnDate,
			bra_id
		)
			SELECT	tso.comp_id,
					DATEADD(minute,DATEPART(minute,tso.soam_time), DATEADD(  hour,DATEPART(hour,tso.soam_time),@date4Turn)) [tmpDateTurn],
					@bra_id
				FROM tbSaleOrderAssemblyTurnsMask tso		WITH (NOLOCK)
				LEFT JOIN tbCompany_unWorkDays tcuwd		WITH (NOLOCK)
					ON	tcuwd.comp_id	= tso.comp_id AND
						tcuwd.nld_date	= @date4Turn
				LEFT JOIN tbSaleOrderAssemblyTurns t1		WITH (NOLOCK)
					ON	t1.comp_id		= @comp_id	AND
						t1.bra_id		= @bra_id	AND
						t1.soa_turnDate = DATEADD(minute,DATEPART(minute,tso.soam_time), DATEADD(  hour,DATEPART(hour,tso.soam_time),@date4Turn))

				WHERE	tso.comp_id				= @comp_id		AND
						tso.soam_turnDayOfWeek	= @intDayofweek AND
						(
							tso.bra_id			= @bra_id
							OR
							tso.bra_id IS NULL
						)										AND
						t1.comp_id		IS NULL					AND
						tcuwd.comp_id	IS NULL




END

GO




-- ----------------------------------------------------
-- Author : GA
-- Date   : 02/06/15
-- Desc   : Preparacion de Turnos en base a la fecha
-- ----------------------------------------------------



CREATE procedure [dbo].[spSaleOrderPreparation_Turns_getData]
(
		@comp_id			int,
		@lang_id			int,
		@bra_id				int,
		@prof_id			int,
		@user_id			int,
		@date4Turn			DATETIME
)
as

SET NOCOUNT ON

set DATEFORMAT 'ymd'

----------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------
/*
DECLARE 		@comp_id			int,
				@lang_id			int,
				@bra_id				int,
				@prof_id			int,
				@user_id			int,
				@date4Turn			DATETIME

SELECT			@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@prof_id			= 1,
				@user_id			= 1,
				@date4Turn			= '2015-12-27'
*/
----------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------




BEGIN

		SET DATEFIRST 7		-- Domingo x Defecto
		DECLARE @intDayofweek AS INT
		SET		@intDayofweek = datepart(dw,@date4Turn)


		DECLARE @fromDate4Turn as DATETIME
		DECLARE @toDate4Turn   as DATETIME
		SET		@fromDate4Turn		= dbo.fnGetEnd_or_BeginOfDate(@date4Turn,'False')
		SET		@toDate4Turn	    = dbo.fnGetEnd_or_BeginOfDate(@date4Turn,'True')

		--SET		@date4Turn	= dbo.fnGetEnd_or_BeginOfDate(@date4Turn,'False')

			SELECT  ''																							[1],
					''																							[2],
					''																							[3],
					''																							[4],
					right(convert(char(5),tsoat.soa_turnDate,8),8)												[soam_Time],
					tsoh.soh_id																					[soh_id],
					dbo.fnGetSaleOrderNumber(tsoh.comp_id,tsoh.bra_id,tsoh.soh_id) +
					'¦' +
					convert(nvarchar(4),IsNull(sov.optval_desc,'')) +
					'¦' +
					IsNull(vsos.ssos_desc,'') 																	[ssos_desc],
					sm.sm_name																					[Sm_name],
					cu.cust_name																				[Cust_Name],
					CASE WHEN tsoat.ct_transaction IS NULL THEN
							''
					ELSE
						 dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tsoat.ct_transaction)
					END																								[Comprobante],
					CASE isnull(tsoat.soa_isAssembled,0) WHEN 1 THEN
								sovstatus2.optval_desc --finalizado
					ELSE
						CASE isnull(tsoat.soa_isInAssembly,0) WHEN 1 THEN
								sovstatus1.optval_desc -- comenzado
						ELSE
								''	-- sin procesar
						END
					END																								[StatusAssembly],
					tu_Creation.user_lastname + ',' + tu_Creation.user_firstname									[User_Creation],
					tu_LastUpdate.user_lastname + ',' + tu_LastUpdate.user_firstname								[User_LastUpdate],
					tu_Assembly.user_lastname + ',' + tu_Assembly.user_firstname									[User_Assembly],
					tsoat.soa_isInAssemblyCD																		[soa_isInAssemblyCD],
					tu_Assembled.user_lastname + ',' + tu_Assembled.user_firstname									[user_id4isAssembled],
					tsoat.soa_isAssembledCD																			[soa_isAssembledCD],
					isnull(tsoat.soa_note,'')																		[soa_note],
				--	isnull(tsoat.ct_transaction,0)																	[ct_transaction],


					isnull(tsoat.soa_id,0)																			[ID]



			FROM tbSaleOrderAssemblyTurns								tsoat			WITH (NOLOCK)


			LEFT JOIN tbSaleOrderHeader									tsoh			WITH (NOLOCK)
			ON  tsoh.comp_id		= tsoat.comp_id		AND
			    tsoh.bra_id			= tsoat.soh_bra_id	AND
			    tsoh.soh_id			= tsoat.soh_id

			LEFT JOIN dbo.tbDocumentsFile								df				WITH (NOLOCK)
			on	df.comp_id			= tsoh.comp_id		AND
				df.df_id			= tsoh.df_id

			LEFT JOIN dbo.tbSalesman									sm				WITH (NOLOCK)
			on	sm.comp_id			= tsoh.comp_id		AND
				sm.sm_id			= tsoh.sm_id

			LEFT JOIN dbo.tbCustomer									cu				WITH (NOLOCK)
			on	cu.cust_id			= tsoh.cust_id		AND
				cu.comp_id			= tsoh.comp_id

			LEFT JOIN dbo.tbsysOptionsValues							sov				WITH (NOLOCK)
			On	sov.lang_id			= @lang_id			AND
				sov.optval_class	= 6					AND
				sov.optval_id		= df.sd_id

			LEFT JOIN vwSaleOrderStatus									vsos			WITH (NOLOCK)
			ON	vsos.comp_id		= tsoh.comp_id		AND
				vsos.bra_id			= tsoh.bra_id		AND
				vsos.soh_id			= tsoh.soh_id		AND
				vsos.lang_id		= @lang_id

			LEFT JOIN dbo.tbsysOptionsValues							sovstatus0		WITH (NOLOCK)
			On	sovstatus0.lang_id		= @lang_id			AND
				sovstatus0.optval_class	= 532				AND
				sovstatus0.optval_id		= 0

			LEFT JOIN dbo.tbsysOptionsValues							sovstatus1		WITH (NOLOCK)
			On	sovstatus1.lang_id		= @lang_id			AND
				sovstatus1.optval_class	= 532				AND
				sovstatus1.optval_id		= 1

			LEFT JOIN dbo.tbsysOptionsValues							sovstatus2		WITH (NOLOCK)
			On	sovstatus2.lang_id		= @lang_id			AND
				sovstatus2.optval_class	= 532				AND
				sovstatus2.optval_id		= 2

			LEFT JOIN dbo.tbUser										tu_Creation		WITH (NOLOCK)
			ON	tu_Creation.[user_id]	= tsoat.user_id4Creation

			LEFT JOIN dbo.tbUser										tu_LastUpdate	WITH (NOLOCK)
			ON	tu_LastUpdate.[user_id]	= tsoat.user_id4lastUpdate

			LEFT JOIN dbo.tbUser										tu_Assembly		WITH (NOLOCK)
			ON	tu_Assembly.[user_id]	= tsoat.user_id4Assembly

			LEFT JOIN dbo.tbUser										tu_Assembled	WITH (NOLOCK)
			ON	tu_Assembled.[user_id]	= tsoat.user_id4isAssembled



			WHERE tsoat.comp_id										= @comp_id		AND
				  tsoat.bra_id										= @bra_id		AND
				  --Convert(varchar(10),tsoat.soa_turnDate,101)       = @date4Turn
				  tsoat.soa_turnDate  BETWEEN @fromDate4Turn and @toDate4Turn

			ORDER BY tsoat.soa_turnDate
END

GO








CREATE procedure [dbo].[spSaleorderPreparationOk_close]
(
	@comp_id			int,
	@bra_id				int,
	@soh_id				int
)
as
SET NOCOUNT ON

/*
DECLARE @comp_id			int,
		@bra_id				int,
		@soh_id				int

SELECT	@comp_id			=1,
		@bra_id				=1,
		@soh_id				=7562
DROP TABLE #tmp_loaded
*/




SELECT	sod.item_id, COUNT(*) [load_qty]

INTO	#tmp_loaded

FROM 	dbo.tbSaleOrderDetail				   SOD

	    LEFT JOIN tbSaleOrderSerials tsos
		ON	tsos.comp_id	= SOD.comp_id
		AND	tsos.bra_id		= SOD.bra_id
		AND	tsos.soh_id		= SOD.soh_id

WHERE	SOD.comp_id			= @comp_id
and		SOD.bra_id			= @bra_id
and		SOD.soh_id			= @soh_id

GROUP BY sod.item_id




SELECT	ti.item_code,
		SOD.sod_itemDesc,
		convert(int,isnull(sum(SOD.sod_qty),0))		[qty],
		ISNULL([loaded].[load_qty],0)				[qty2]

FROM 	dbo.tbSaleOrderDetail				   SOD

		INNER JOIN tbItem ti
		ON	ti.item_id = SOD.item_id
		AND ti.comp_id = SOD.comp_id

		LEFT JOIN #tmp_loaded	[loaded]
		ON 	[loaded].item_id = SOD.item_id

WHERE	SOD.comp_id			= @comp_id
and		SOD.bra_id			= @bra_id
and		SOD.soh_id			= @soh_id

GROUP BY ti.item_code, SOD.sod_itemDesc, [load_qty]



GO





