CREATE PROCEDURE [dbo].[spSaleOrderPreparationTurns_UpdateData]
(

	@comp_id					INT,
	@soa_turndate				DATETIME,
	@bra_id						INT,
	@tis_id						INT,
	@soa_guid					UNIQUEIDENTIFIER,
	@soh_bra_id					INT,
	@soh_id						INT,
	@sod_id						INT,
	@soa_is4AllItems			BIT,
	@user_id4Creation			INT,
	@user_id4lastUpdate			INT,
	@soa_isAssembled			BIT,
	@soa_isAssembledCD			DATETIME,
	@user_id4Assembly			INT,
	@ct_transaction				INT,
	@it_transaction				INT,
	@soa_isInAssembly			BIT,
	@soa_isInAssemblyCD			DATETIME,
	@qtyTurn					INT,
	@soa_id						INT,
	@isautomatic				BIT



)
AS

BEGIN

	SET NOCOUNT ON
    set DATEFORMAT 'ymd'

   	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
/*
	declare	@comp_id					INT,
			@soa_turndate				DATETIME,
			@bra_id						INT,
			@tis_id						INT,
			@soa_guid					UNIQUEIDENTIFIER,
			@soh_bra_id					INT,
			@soh_id						INT,
			@sod_id						INT,
			@soa_is4AllItems			BIT,
			@user_id4Creation			INT,
			@user_id4lastUpdate			INT,
			@soa_isAssembled			BIT,
			@soa_isAssembledCD			DATETIME,
			@user_id4Assembly			INT,
			@ct_transaction				INT,
			@it_transaction				INT,
			@soa_isInAssembly			BIT,
			@soa_isInAssemblyCD			DATETIME,
			@qtyTurn					INT,
			@soa_id						INT,
			@isautomatic				BIT




	select	@comp_id					=1,
			@soa_turndate				='2016-10-11 11:30:00',
			@bra_id						=234,
			@tis_id						=-1,
			@soa_guid					='7ba1e7a4-e014-4169-a3af-11024cbebe41',
			@soh_bra_id					=-1,
			@soh_id						=-1,
			@sod_id						=NULL,
			@soa_is4AllItems			='True',
			@user_id4Creation			=119,
			@user_id4lastUpdate			=119,
			@soa_isAssembled			='false',
			@soa_isAssembledCD			='2015-06-08',
			@user_id4Assembly			=1,
			@ct_transaction				=0,
			@it_transaction				=0,
			@soa_isInAssembly			='false',
			@soa_isInAssemblyCD			='2015-06-08',
			@qtyTurn					=4,
			@soa_id						=3354,
			@isautomatic				= 'False'


	drop table #tmpSaleOrderAssemblyTurns
	drop table #tmpSaleOrderAssemblyTurnsAutomatic
*/
	-- ------------------------------------------------------

	DECLARE @lintcountqty AS INT

	SET @lintcountqty = @qtyTurn


		IF @isautomatic = 'False'

			BEGIN
				--Asginar turnos mediante la fecha seleccionada

					IF @soa_is4AllItems	= 'True'

						BEGIN

							-- No es para todos los articulos ,@soa_is4AllItems	= 'false'

							--------------------------------------------------------------------------------------------------------
							-- guardamos en una temporal los datos ya filtrados por la fecha
							--------------------------------------------------------------------------------------------------------

							SELECT  TOP (@qtyTurn) *

							INTO #tmpSaleOrderAssemblyTurns

							FROM tbSaleOrderAssemblyTurns								tso		WITH (NOLOCK)

							WHERE (tso.comp_id			= @comp_id)		AND
								  (tso.bra_id			= @bra_id)		AND
								 -- (tso.soa_turnDate		>= @soa_turndate	AND tso.soa_turnDate <= dbo.fnGetEnd_or_BeginOfDate(@soa_turndate,'true')) AND
								  (tso.soa_turnDate >=  @soa_turndate /*AND tso.soa_turnDate <= dbo.fnGetEnd_or_BeginOfDate(@soa_turndate,'true')*/) AND --ESTO SOLO
								 --(tso.soa_guid			IS NULL )
								  (
							  		tso.soa_guid		IS NULL AND
							  		tso.soh_id			IS NULL AND
							  		tso.ct_transaction	IS NULL
								  )
							ORDER BY tso.soa_turnDate,
									 tso.soa_id

							--------------------------------------------------------------------------------------------------------

							--------------------------------------------------------------------------------------------------------
							-- actualizamos la tabla de turnos
							--------------------------------------------------------------------------------------------------------
							UPDATE tbSaleOrderAssemblyTurns
							SET
									soa_guid			= @soa_guid,
									user_id4Creation	= @user_id4Creation,
									user_id4lastUpdate	= @user_id4lastUpdate

							FROM tbSaleOrderAssemblyTurns tso		WITH (NOLOCK)

							INNER JOIN #tmpSaleOrderAssemblyTurns tmpsoa		WITH (NOLOCK)
							ON tmpsoa.comp_id			= tso.comp_id AND
							   tmpsoa.soa_id			= tso.soa_id
							--------------------------------------------------------------------------------------------------------

						END

					 ELSE
							BEGIN
					 			SELECT 1
								-- Para todos los articulos ,@soa_is4AllItems	= 'True'
							END

			END

		ELSE

			BEGIN
			-- Asignar turnos Automaticamente


					--------------------------------------------------------------------------------------------------------
					-- guardamos en una temporal los datos ya filtrados por la fecha
					--------------------------------------------------------------------------------------------------------

					SET @soa_turndate = dbo.fnGetEnd_or_BeginOfDate(@soa_turndate,'False')

					SELECT  TOP (@qtyTurn) *
						INTO #tmpSaleOrderAssemblyTurnsAutomatic
						FROM tbSaleOrderAssemblyTurns								tso		WITH (NOLOCK)
						WHERE (tso.comp_id			= @comp_id)		AND
							  (tso.bra_id			= @bra_id)		AND
							  (tso.soa_turnDate >=  @soa_turndate /*AND tso.soa_turnDate <= dbo.fnGetEnd_or_BeginOfDate(@soa_turndate,'true')*/) AND
							  (
							  	tso.soa_guid		IS NULL AND
							  	tso.soh_id			IS NULL AND
							  	tso.ct_transaction	IS NULL
							  )
						ORDER BY tso.soa_turnDate,
								 tso.soa_id

					--SELECT * FROM #tmpSaleOrderAssemblyTurnsAutomatic
					--------------------------------------------------------------------------------------------------------

					--------------------------------------------------------------------------------------------------------
					-- actualizamos la tabla de turnos
					--------------------------------------------------------------------------------------------------------
					UPDATE tbSaleOrderAssemblyTurns	WITH (ROWLOCK)
						SET
								soa_guid			= @soa_guid,
								user_id4Creation	= @user_id4Creation,
								user_id4lastUpdate	= @user_id4lastUpdate

						FROM tbSaleOrderAssemblyTurns tso

						INNER JOIN #tmpSaleOrderAssemblyTurnsAutomatic tmpsoa
						ON tmpsoa.comp_id			= tso.comp_id AND
						   tmpsoa.soa_id			= tso.soa_id

					--------------------------------------------------------------------------------------------------------

			END

END
GO

CREATE PROCEDURE spSaleOrderProduction_GetItemFormula
(
	@comp_id	INT,
	@item_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SELECT
			ti.item_code,
			ti.item_desc,
			tic.icomp_qty,
			ISNULL(tc.color_desc,'')		[color_desc]
		FROM tbItemComposition				AS tic	WITH(NOLOCK)
			INNER JOIN tbItem				AS ti	WITH(NOLOCK)
			ON	ti.comp_id = tic.comp_id	AND
				ti.item_id = tic.item_id_1
			LEFT JOIN tbColor				AS tc	WITH(NOLOCK)
			ON	tc.comp_id = tic.comp_id	AND
				tc.color_id = tic.color_id
		WHERE	tic.comp_id = @comp_id		AND
				tic.item_id = @item_id
	END
GO

CREATE PROCEDURE [dbo].[spSaleOrderProduction_InsertFinalPrice]
(
	@comp_id	INT,
	@bra_id		INT,
	@item_id	INT,
	@prli_id	INT,
	@price		DECIMAL(25,2)
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@item_id	INT,
				@prli_id	INT,
				@price		DECIMAL(25,2)
		*/
		-- -----------------------------------------------------

		-- -----------------------------------------------------
		-- RECUPERO LA MONEDA DEL ARTÍCULO
		-- -----------------------------------------------------
			DECLARE
				@Item_Curr_Id	INT

			SELECT
				@Item_Curr_Id		= ti.curr_id
				FROM tbItem						ti	WITH(NOLOCK)
				WHERE	ti.comp_id	= @comp_id	AND
						ti.item_id	= @item_id
		-- -----------------------------------------------------

		-- -----------------------------------------------------------------------------------------
		-- GRABO EL PRECIO DE VENTA
		-- PRECIO DE VENTA = SUMA DEL PRECIO DE VENTA DE LOS ARTICULOS QUE LO CONFORMAN
		-- -----------------------------------------------------------------------------------------


		--stl 28-05-2020 QUE PASA SI YA EXISTE EL PRECIO? Lo actualizo
		IF NOT EXISTS (SELECT 1 FROM tbPriceListItems AS tpli WHERE tpli.comp_id = @comp_id AND tpli.prli_id = @prli_id AND tpli.item_id = @item_id)
			BEGIN
				INSERT INTO tbPriceListItems
				(
					comp_id,
					prli_id,
					item_id,
					prli_price,
					curr_id,
					bra_id
				)
				VALUES
				(
					@comp_id,
					@prli_id,
					@item_id,
					@price,
					@Item_Curr_Id,
					@bra_id
				)
			END
		ELSE
			BEGIN
				UPDATE tbPriceListItems
				SET
						prli_price	= @price
				WHERE	comp_id		= @comp_id AND
						prli_id		= @prli_id AND
						item_id		= @item_id
			END
		-- -----------------------------------------------------------------------------------------
	END
GO

