CREATE PROCEDURE [dbo].[spSaleOrderProductionCompositionTMPDetail_GetDataByFilters]
(
	@comp_id	INT,
	@prmt_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------
		-- TESTING
		-- -- -----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@prmt_id	INT
			SELECT
				@comp_id	= 1,
				@prmt_id	= 1
		*/
		-- -----------------------------------------------------

		SELECT
			' '													[1],
			' '													[2],
			--tsopct2.prmt_desc,
			ti.item_code,
			ti.item_desc,
			tsopct.prmtd_qty,
			tsopct.prmtd_id										[ID]
			FROM tbSaleOrderProductionCompositionTMPDetail		tsopct
			INNER JOIN tbItem									ti
			ON	ti.comp_id			= tsopct.comp_id			AND
				ti.item_id			= tsopct.item_id
			INNER JOIN tbSaleOrderProductionCompositionTMPHead	tsopct2
			ON	tsopct2.comp_id		= tsopct.comp_id			AND
				tsopct2.prmt_id		= tsopct.prmt_id
			WHERE	tsopct.comp_id	= @comp_id AND
					tsopct.prmt_id	= @prmt_id

	END
GO

