		*/
		-- -----------------------------------------------------

		IF EXISTS (SELECT
						1
						FROM tbItemComposition				tic	WITH(NOLOCK)
						WHERE	tic.comp_id		= @comp_id	AND
								tic.item_id		= @item_id	AND
								tic.item_id_1	= @item_id1)
			BEGIN
				UPDATE tbItemComposition
				SET
					icomp_qty		= @qty
				WHERE	comp_id		= @comp_id AND
						item_id		= @item_id AND
						item_id_1	= @item_id1
			END
		ELSE
			BEGIN
				EXEC spItemComposition_InsertData
					@comp_id	= @comp_id,
					@Item_id	= @item_id,
					@Item_id_1	= @item_id1,
					@icomp_qty	= @qty,
					@color_id	= NULL
			END

	END
GO

