CREATE PROCEDURE [dbo].[spSaleOrderProductionCompositionTMPHead_InsertData]
(
	@comp_id				INT,
	@prmt_desc				NVARCHAR(200),
	@prmt_qty				INT,
	@prli_id				INT,
	@stor_id				INT,
	@prmt_guid				UNIQUEIDENTIFIER,
	@prmt_item_id			INT,
	@prmt_item_useFormula	BIT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@prmt_desc		NVARCHAR(200),
				@prmt_qty		INT,
				@prli_id		INT,
				@stor_id		INT
		*/
		-- ---------------------------------------------------

		IF @prmt_item_id = -1
			BEGIN
				SET @prmt_item_id = NULL
			END

		INSERT INTO tbSaleOrderProductionCompositionTMPHead
		(
			comp_id,
			prmt_desc,
			prmt_qty,
			prli_id,
			stor_id,
			prmt_guid,
			prmt_isProcessed,
			prmt_item_id,
			prmt_item_useFormula
		)
		VALUES
		(
			@comp_id,
			@prmt_desc,
			@prmt_qty,
			@prli_id,
			@stor_id,
			@prmt_guid,
			'False',
			@prmt_item_id,
			@prmt_item_useFormula
		)

		DECLARE
			@lPrmtIT INT

		SET @lPrmtIT = @@IDENTITY

		IF @prmt_item_id <> -1
			BEGIN
				--CARGO LOS ARTICULOS QUE LO COMPONEN JUNTO CON EL PRECIO QUE TENGAN EN LA LISTA DE PRECIOS QUE TIENE DEFINIDO EL ARTICULO PRINCIPAL
				INSERT INTO tbSaleOrderProductionCompositionTMPDetail
				(
					comp_id,
					-- prmtd_id -- this column value is auto-generated
					prmt_id,
					item_id,
					prmtd_qty,
					prmtd_price,
					prmtd_price_withTaxes
				)
				SELECT
					tic.comp_id,
					@lPrmtIT,
					tic.item_id_1,
					tic.icomp_qty,
					tpli.prli_price,
					dbo.fnGetPriceListItemTaxesCoeficient(tic.comp_id, tic.item_id_1) * tpli.prli_price
				FROM tbItemComposition						AS tic	WITH(NOLOCK)
				INNER JOIN tbPriceListItems					AS tpli WITH(NOLOCK)
				ON	tpli.comp_id		= tic.comp_id		AND
					tpli.item_id		= tic.item_id_1
				WHERE	tic.comp_id		= @comp_id			AND
						tic.item_id		= @prmt_item_id		AND
						tpli.prli_id	= @prli_id
			END

	END
GO

