CREATE procedure [dbo].[spSaleOrderSerial_DeleteSerial]
(
	@comp_id			int,
	@is_serial			varchar(200)


)
AS



BEGIN

	SET NOCOUNT ON

	-- --------------------------------------------
	-- Testing
	-- --------------------------------------------
	/*
	DECLARE @comp_id			int,
			@is_serial			varchar(200)


	SELECT	@comp_id			=1,
			@is_serial			='a2'
	*/
	-- --------------------------------------------

	DECLARE @intIs_ID     INT
	DECLARE @intSOH_ID    INT
	DECLARE @intBRA_ID	  INT

	-- Obtengo Is_ID del numero a borrar del pedido
	SET @intIs_ID=(	SELECT tis.is_id
						FROM tbItemSerials tis		WITH (NOLOCK)
						WHERE	tis.comp_id		= @comp_id
							AND tis.is_serial	= @is_serial)

--	SELECT TOP 1
--			@intSOH_ID = isnull(tsos.soh_id,0),
--			@intBRA_ID = ISNULL(tsos.bra_id,0)
--				FROM tbSaleOrderSerials tsos
--				inner join tbItemSerials tis
--					oN		tis.comp_id		= tsos.comp_id
--						AND tis.is_id		= tsos.is_id
--			   WHERE	tis.comp_id		= @comp_id
--				   AND	tis.is_id		= @intIs_ID

	--SELECT @get_idsoh
	--SELECT @get_idserial

	-- Pone al Pedido como Abierto.-
	UPDATE tbSaleOrderHeader
		SET	 ssos_id = 20
		FROM		tbSaleOrderHeader	tsoh		WITH (NOLOCK)
		INNER JOIN	tbSaleOrderSerials	tsos		WITH (NOLOCK)
			ON	tsos.comp_id	= tsoh.comp_id	AND
				tsos.bra_id		= tsoh.bra_id	AND
				tsos.soh_id		= tsoh.soh_id
		WHERE	tsos.comp_id	= @comp_id AND
				tsos.is_id		= @intIs_ID

	-- Borra el Numero de serie de los numeros tomados por pedidos.
	DELETE tbSaleOrderSerials
		WHERE	comp_id = @comp_id
			--AND soh_id  = @intSOH_ID
			--AND bra_id  = @intBRA_ID
			AND is_id   = @intIs_ID


	-- ---------------------------------------------------------------------------------------------
	-- Pone @bitIsAvailable en true si es una factura y en false si es pedido para nota de credito.-
	-- ---------------------------------------------------------------------------------------------
	DECLARE @bitIsAvailable AS BIT
	SELECT @bitIsAvailable = case
								when td.sd_isCredit = 'False' then 'True'
								ELSE 'False'
							 END
		FROM tbSaleOrderHeader tsoh			WITH (NOLOCK)
		INNER JOIN tbDocumentsFile tdf		WITH (NOLOCK)
			ON		tdf.comp_id = tsoh.comp_id
				AND tdf.df_id	= tsoh.df_id
		INNER JOIN tbsysDocuments td		WITH (NOLOCK)
			ON td.sd_id = tdf.sd_id
		WHERE	tsoh.comp_id	= @comp_id
			AND tsoh.soh_id		= @intSOH_ID
			AND tsoh.bra_id		= @intBRA_ID

	SET @bitIsAvailable = ISNULL(@bitIsAvailable,'True')
	-- ---------------------------------------------------------------------------------------------


	-- Pone como disponible al Numero de Serie.-
	UPDATE tbItemSerials
		SET   is_available = @bitIsAvailable --'True'
		WHERE	comp_id = @comp_id
			AND	is_id   = @intIs_ID



END
GO








CREATE procedure [dbo].[spSaleOrderSerial_ValidateSerial]
(
	@comp_id			int,
	@is_serial			varchar(200),
	@return_value		INT OUTPUT

)
AS

BEGIN



	SET NOCOUNT ON

	-- --------------------------------------------
	-- Testing
	-- --------------------------------------------
	/*
	DECLARE @comp_id			int,
			@is_serial			varchar(200),
			@return_value		INT OUTPUT

	SELECT	@comp_id			=1,
			@is_serial			='a2'
	*/
	-- --------------------------------------------


	DECLARE @get_idserial INT

	SET @get_idserial=(SELECT tis.is_id
						   FROM tbItemSerials tis		WITH (NOLOCK)
						   WHERE tis.comp_id =@comp_id
						   AND tis.is_serial = @is_serial)

	IF EXISTS(SELECT TOP 1  1
				  FROM tbSaleOrderSerials tsos		WITH (NOLOCK)
				  INNER JOIN tbItemSerials tis		WITH (NOLOCK)
					  ON	tis.comp_id = tsos.comp_id	AND
							tis.is_id	= tsos.is_id
				  WHERE tsos.comp_id = @comp_id			AND
						tsos.is_id   = @get_idserial)

		SET @return_value=1
	ELSE
		SET @return_value=0


END
GO









