CREATE PROCEDURE [dbo].[spSaleOrderSerial4Production_UpdateMasterSerial]
(
    @comp_id				INT,
	@bra_id					INT,
	@soh_id					INT,
	@sod_id					INT,
	@sod_order				INT,
	@sod_serial				NVARCHAR(100)
)
AS


BEGIN

	SET NOCOUNT ON

--------------------------------------------------------------------------------
-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
--------------------------------------------------------------------------------
/*

DECLARE         @comp_id				INT,
				@bra_id					INT,
				@soh_id					INT,
				@sod_id					INT,
				@sod_order				INT,
				@sod_serial				NVARCHAR(100)

SELECT			@comp_id				= 1,
				@bra_id					= 1,
				@soh_id					= 33260,
				@sod_id					= 23070,
				@sod_order				= 10,
				@sod_serial				= 'GLOTESTYA'

*/

--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------


DECLARE @lisok  INT

set @lisok = 0


	IF NOT EXISTS ( SELECT TOP 1  1
						FROM tbItemSerials tis		WITH (NOLOCK)
						WHERE	tis.comp_id		= @comp_id AND
								tis.is_serial	= @sod_serial
					)


			BEGIN

				IF NOT EXISTS ( SELECT TOP 1  1

								FROM tbSaleOrderSerial4Production_MasterSerial tispms		WITH (NOLOCK)

								WHERE	tispms.sod_serial	= @sod_serial

							   )

							BEGIN


							  IF  EXISTS ( SELECT TOP 1  1

											FROM tbSaleOrderSerial4Production_MasterSerial tispms		WITH (NOLOCK)

											WHERE	tispms.comp_id		= @comp_id		AND
													tispms.bra_id		= @bra_id		AND
													tispms.soh_id		= @soh_id		AND
													tispms.sod_id		= @sod_id		AND
													tispms.sod_order	= @sod_order

								   )

									BEGIN

										UPDATE 	dbo.tbSaleOrderSerial4Production_MasterSerial

											SET sod_serial	= @sod_serial

										 WHERE	comp_id		= @comp_id		AND
												bra_id		= @bra_id		AND
												soh_id		= @soh_id		AND
												sod_id		= @sod_id		AND
												sod_order	= @sod_order

											set @lisok = 1
									END


								ELSE

										BEGIN

											INSERT INTO tbSaleOrderSerial4Production_MasterSerial
											(
												comp_id,
												bra_id,
												soh_id,
												sod_id,
												sod_order,
												sod_serial
											)
											VALUES
											(
												@comp_id,
												@bra_id,
												@soh_id,
												@sod_id,
												@sod_order,
												@sod_serial
											)

											set @lisok = 1

										END
							END

				ELSE
					BEGIN

						set @lisok = 0

					END
			END


		ELSE
			BEGIN

				set @lisok = 0

			END


			--0 -- Ya existe el serial ya sea en la tabla itemserials o en la masterserial
			--1 -- Actualizo o Inserto correctamente

			SELECT @lisok [isok]



END
GO







