CREATE PROCEDURE [dbo].[spSaleOrderSerialInProduction_UpdateIsEditing]
(
    @comp_id				INT,
	@soh_id					INT,
	@sod_id					INT,
	@order					INT,
	@isEditing				BIT,
	@user_id				INT,
	@bra_id					INT,
	@return_value			INT OUTPUT
)
AS
BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	 -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	 -- -----------------------------------------------------------------------------
	 SET LOCK_TIMEOUT 500
	 SET DEADLOCK_PRIORITY LOW
	 -- -----------------------------------------------------------------------------

	Declare @date as datetime
	Set		@Date = getdate()

	IF EXISTS (	SELECT 1
	           	FROM tbSaleOrderSerialInProduction tsosip
				WHERE   comp_id			= @comp_id
				AND		soh_id			= @soh_id
				AND		sod_id			= @sod_id
				AND		sosip_order		= @order
				/*AND		isnull(tsosip.[user_id],-1) = @user_id	*/  )

		BEGIN

				UPDATE 	dbo.tbSaleOrderSerialInProduction

					SET		sosip_isEditing 	= @isEditing,
							sosip_isEditingCD	= @Date

					WHERE   comp_id			= @comp_id
					AND		soh_id			= @soh_id
					AND		sod_id			= @sod_id
					AND		sosip_order		= @order

				SET @return_value = 1
		END

	ELSE

		BEGIN

			IF EXISTS (	SELECT 1
	           				FROM tbSaleOrderSerialInProduction tsosip
							WHERE   comp_id			= @comp_id
							AND		soh_id			= @soh_id
							AND		sod_id			= @sod_id
							AND		sosip_order		= @order
							AND		isnull(tsosip.[user_id],-1) <> @user_id	  )

				BEGIN

					SET @return_value = 0

				END

			ELSE

				BEGIN

					INSERT INTO tbSaleOrderSerialInProduction
					(

						comp_id,
						soh_id,
						sod_id,
						sosip_order,
						sosip_isEditing,
						sosip_isEditingCD,
						[user_id],
						bra_id

					)
					VALUES
					(

						@comp_id,
						@soh_id,
						@sod_id,
						@order,
						@isEditing,
						@Date,
						@user_id,
						@bra_id

					)

					SET @return_value = 1

				END
		END
END
GO







create PROCEDURE [dbo].[spSaleOrderSerialInProduction_UpdateIsEditingOnly]
(
	@comp_id				INT,
	@soh_id					INT,
	@sod_id					INT,
	@order					INT


)
AS
BEGIN

SET NOCOUNT ON


	Declare @date as datetime
	Set		@Date = getdate()


	UPDATE tbSaleOrderSerialInProduction
	SET
			sosip_isEditing		= 'False',
			sosip_isEditingCD	= @Date


	WHERE	comp_id				= @comp_id AND
			soh_id				= @soh_id  AND
			sod_id				= @sod_id  AND
			sosip_order			= @order



END
GO







