CREATE PROCEDURE [dbo].[spSaleOrderSerialProduced_getDataProduced]
(
    @comp_id					INT,
    @bra_id						INT,
	@soh_id						INT,
	@tis_guid					UNIQUEIDENTIFIER,
	@return_value				INT	OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON

	-- ---------------------------------------------
	-- Test
	-- ---------------------------------------------
	/*
	DECLARE	@comp_id					INT,
			@bra_id						INT,
			@soh_id						INT,
			@return_value				INT
	SELECT 	@comp_id					=1,
			@bra_id						=1,
			@soh_id						=10016
	*/
	-- ---------------------------------------------



	IF EXISTS (	SELECT	1
	           	FROM tbTempItemStock							ttis
					LEFT JOIN tbItemComposition					tic
						ON	tic.comp_id		= ttis.comp_id	AND
							tic.item_id		= ttis.item_id
       				INNER JOIN tbDocumentsFile					tdf		WITH (NOLOCK)
   						ON	tdf.comp_id		= @comp_id		AND
   							tdf.df_id		= ttis.df_id
           			WHERE	ttis.comp_id	= @comp_id		AND
           					ttis.tis_guid	= @tis_guid		AND
							tdf.sd_id		= 80			AND
							tic.comp_id     IS NULL)
		BEGIN
			SET @return_value	= 1
			RETURN
		END
	ELSE
		BEGIN
			SET @return_value	= 0
		END




	IF EXISTS (	SELECT	1
	           	FROM	tbSaleOrderSerialProduced			tsosp			WITH (NOLOCK)

	           			INNER JOIN tbSaleOrderHeader		tsoh			WITH (NOLOCK)
	           			ON	tsoh.comp_id	= tsosp.comp_id
	           			AND tsoh.soh_id		= tsosp.soh_id

	           			INNER JOIN tbDocumentsFile			tdf				WITH (NOLOCK)
	           			ON	tdf.comp_id		= tsoh.comp_id
	           			AND tdf.df_id		= tsoh.df_id

	           	WHERE	tsosp.comp_id	= @comp_id
				AND		tsosp.soh_id	= @soh_id
				AND		tsoh.bra_id		= @bra_id
				AND		tdf.sd_id		= 80)

		SET @return_value	= 1
	ELSE
		SET @return_value	= 0


	--SELECT @return_value

END
GO



