-- MOS 12-2012
-- MOS, fix varios de soh_id    08-2013
CREATE PROCEDURE [dbo].[spSaleOrderSerialProduced_produceSerialData]
(
    @comp_id					INT,
    @lang_id					INT,
    @bra_id						INT,
    @user_id					INT,
	@soh_id						INT,
	@sod_id						INT,
	@order						INT,
	@guid						UNIQUEIDENTIFIER,
	@return_value				INT				OUTPUT,
	@ret_ErrorCode				INT 			OUTPUT,
	@ret_ErrorDescription		NVARCHAR(MAX)	OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id					INT,
			@lang_id					INT,
			@bra_id						INT,
			@user_id					INT,
			@soh_id						INT,
			@sod_id						INT,
			@order						INT,
			@guid						UNIQUEIDENTIFIER,
			@return_value				INT,
			@ret_ErrorCode				INT,
			@ret_ErrorDescription		VARCHAR(500)
	select	@comp_id					=1,
			@lang_id					=2,
			@bra_id						=1,
			@user_id					=1,
			@soh_id						=32634,
			@sod_id						=20899,
			@order						=3,
			@guid						='886883ed-582c-4e8b-99d0-d5769ec7c8bc'
			--@return_value				INT,
			--@ret_ErrorCode			INT,
			--@ret_ErrorDescription		VARCHAR(200)

	IF NOT OBJECT_ID('tempdb.dbo.#tmpValidation')		IS NULL DROP TABLE #tmpValidation
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsNeeded')		IS NULL DROP TABLE #tmpItemsNeeded
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsFree')		IS NULL DROP TABLE #tmpItemsFree
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsToProduce')	IS NULL DROP TABLE #tmpItemsToProduce
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsProduced')	IS NULL DROP TABLE #tmpItemsProduced
	*/
	-- -------------------------------------------------------------------------------


	BEGIN TRANSACTION T2
	BEGIN TRY


		SET @return_value			= 0
		set @ret_ErrorCode			= 0
		set @ret_ErrorDescription	= ''



		/*********************************************************************************************************/
		-- verificamos si hay algún proveedor definido para producción
		IF EXISTS (	SELECT	TOP 1 1
	           			FROM	dbo.tbSupplier			ts		WITH (NOLOCK)
						WHERE	ts.comp_id = @comp_id
						AND		ISNULL(ts.supp_isSupp4Production,'false') = 'true' )
			BEGIN


				DECLARE @bra_processingDate			DATETIME,
						@prli_id					INT,
						@intStor_id_b				INT,
						@intSm_id					INT,
						@intDisc_id					INT,
						@intDl_id					INT,
						@intSt_id					INT,
						@ct_CompanyCurrency			INT,
						@supplierCurrencyId			INT,
						@BranchCurrencyId			INT,
						@supp_id					INT,
						@ct_transaction_rv			INT,
						@it_transaction_rv			INT,
						@stor_id					INT,
						@item_id					INT,
						@bra_checkSerialNumber		BIT,
						@it_order					INT,
						@ret_ErrorCode_rv			INT,
						@ret_ErrorDescription_rv	VARCHAR(200),
						@branch_country_id			INT,
						@branch_state_id			INT,
						@itemToProduceIsSerializable	BIT,
						@bititem_expserInBlankWhenProduced AS BIT




				/*********************************************************************************************************/
				--seteamos en una variable si el artículo a producir es serializable o no

				SELECT	@itemToProduceIsSerializable		= IsNull(ti.item_expser,'False'),
						@bititem_expserInBlankWhenProduced	= isnull(ti.item_expserInBlankWhenProduced,'False')
				   FROM tbSaleOrderDetail tsod			WITH (NOLOCK)
							INNER JOIN tbItem ti		WITH (NOLOCK)
							ON	ti.comp_id = tsod.comp_id	AND
								ti.item_id = tsod.item_id
				   WHERE	tsod.comp_id = @comp_id
					AND		tsod.bra_id = @bra_id
					AND		tsod.soh_id = @soh_id
					AND		tsod.sod_id = @sod_id

				--SELECT @itemToProduceIsSerializable
				/********************************************************************************************************/





				/********************************************************************************************************/
				-- Obtenemos datos de la sucursal
				SELECT 	@bra_processingDate		= tb.bra_processingDate,
						@intStor_id_b			= tb.stor_id,
						@BranchCurrencyId		= tb.curr_id,
						--@stor_id				= tb.stor_id,
						@bra_checkSerialNumber	= isnull(tb.bra_checkSerialNumber,'false'),
						@branch_country_id		= tb.country_id,
						@branch_state_id		= tb.state_id
					FROM	dbo.tbBranch			tb			WITH (NOLOCK)
					WHERE	tb.comp_id				= @comp_id
					AND		tb.bra_id				= @bra_id
				/********************************************************************************************************/


				/********************************************************************************************************/
				-- obtenemos el depósito del artículo del pedido
				SELECT	@stor_id			= tsod.stor_id
					FROM	tbSaleOrderDetail	tsod			WITH (NOLOCK)
					WHERE	tsod.comp_id	= @comp_id
					AND		tsod.bra_id     = @bra_id
					AND		tsod.soh_id		= @soh_id
					AND		tsod.sod_id		= @sod_id
				/********************************************************************************************************/



				--SELECT '@bra_checkSerialNumber', @bra_checkSerialNumber
				-- si @bra_checkSerialNumber = 'true' se deben generar la producción a partir de los datos cargados
				-- en la página actual, sino se deben cargar todos los artículos definidos en la tabla tbSaleOrderSerial4Production
				-- (verificar en que momento se graba esta tabla tbSaleOrderSerial4Production)
				DECLARE @sumEstado			INT
				SET @sumEstado = 0
				IF @bra_checkSerialNumber = 'true'
					BEGIN



						/********************************************************************************************************/
						/* GENERACIÓN DE TABLA TEMPORAL PARA VALIDACIÓN DE CANTIDAD CORRECTA DE ARTÍCULOS ASOCIADOS				*/
						/* SI LA CANTIDAD DE UN ART. ASOCIADO QUE COMPONE AL PADRE MENOS LA CANTIDAD TOMADA ES DIFERENTE DE		*/
						/* CERO GRABA 1 EN CASO CONTRARIO GRABA 0 EN CAMPO [estado]												*/
						SELECT	tsod.item_id,
								tic.item_id_1,
								CASE
									WHEN	tic.icomp_qty - SUM(case
																	when isnull(tis.item_id,0) = 0 THEN 0
																	ELSE 1
																END) <> 0 THEN 1
									ELSE 0
								END [estado]

						INTO	#tmpValidation

						FROM	tbSaleOrderDetail							tsod		WITH (NOLOCK)

								INNER JOIN tbItemComposition				tic			WITH (NOLOCK)
								ON  tic.comp_id			= tsod.comp_id
								AND tic.item_id			= tsod.item_id

								INNER JOIN tbItem							ti			WITH (NOLOCK)
								ON ti.comp_id = tsod.comp_id
								AND ti.item_id = tic.item_id_1
								AND ti.item_expser = 'true'

								INNER JOIN tbSaleOrderSerial4Production		tsosp		WITH (NOLOCK)
								ON	tsosp.comp_id		= tsod.comp_id
								AND tsosp.soh_id		= tsod.soh_id
								AND tsosp.sod_id		= tsod.sod_id	-- Es Identity, no molesta q n tenga Bra_Id
								AND tsosp.sosp_order	= @order
								-- MOD 09-2014AND tsosp.sosp_guid		= @guid

								LEFT JOIN tbItemSerials						tis			WITH (NOLOCK)
								ON	tis.comp_id			= tsosp.comp_id
								AND tis.is_id			= tsosp.is_id
								AND tis.item_id			= tic.item_id_1

						WHERE	tsod.comp_id	= @comp_id
						AND		tsod.bra_id		= @bra_id
						AND		tsod.soh_id		= @soh_id
						AND		tsod.sod_id		= @sod_id

						GROUP BY tsod.item_id, tic.item_id_1, tic.icomp_qty

						--SELECT * FROM #tmpValidation
						/******************************************************************************************************/


						SELECT @sumEstado = SUM([estado]) FROM  #tmpValidation
						DROP TABLE #tmpValidation

					END
					--SET @sumEstado = ISNULL(@sumEstado,0)
				--SELECT @sumEstado [@sumEstado]








					/******************************************************************************************************/
					-- Si la sumatoria del campo [estado] de la temporal es = 0 significa que se tomaron todos los seriales
					-- asociados al artículo padre con las cantidades correctas o que no había artículos serializables
					IF (@sumEstado = 0 OR @bra_checkSerialNumber = 'false')
						BEGIN
							--validación correcta o no necesaria para el caso "@bra_checkSerialNumber = 'false'"



							/****************************************************************************************************/
							-- Se graba el artículo producido en la tabla tbSaleOrderSerialProduced
							--SELECT 'insert into tbSaleOrderSerialProduced', @comp_id,@soh_id,@sod_id,@order

							INSERT INTO tbSaleOrderSerialProduced
							(
									comp_id,
									soh_id,
									sod_id,
									sosp_order
							)
							VALUES
							(
									@comp_id,
									@soh_id,
									@sod_id,
									@order
							)

							/****************************************************************************************************/




							/****************************************************************************************************/
							-- recuperamos la descripción para el mensaje por la producción del artículo
							SELECT	@ret_ErrorDescription	= tut.utexts_desc
								FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
								WHERE	tut.lang_id		= @lang_id
								AND		tut.utexts_id	= 20
							--SELECT	@ret_ErrorDescription
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- se recupera un número desde el contador 11, es para generar el serial correspondiente para el
							-- producto a generar, al contador se le suma 980000000, para generar un serial con el formato 980000001, 980000002, etc
							DECLARE @serial INT
							SET	@serial				= 0
							DECLARE @strGlobalSerial AS NVARCHAR(100)
							SET @strGlobalSerial	= ''

							IF EXISTS (
										SELECT TOP 1  1
											FROM  tbSaleOrderSerial4Production_MasterSerial mse	WITH (NOLOCK)
											WHERE	mse.comp_id		= @comp_id	AND
													mse.bra_id		= @bra_id	AND
													mse.soh_id		= @soh_id	AND
													mse.sod_id		= @sod_id	AND
													mse.sod_order	= @order	AND
													ISNULL(mse.sod_serial,'')  <> ''
										)
								BEGIN
									SELECT @strGlobalSerial = mse.sod_serial
										FROM  tbSaleOrderSerial4Production_MasterSerial mse	WITH (NOLOCK)
										WHERE	mse.comp_id		= @comp_id	AND
												mse.bra_id		= @bra_id	AND
												mse.soh_id		= @soh_id	AND
												mse.sod_id		= @sod_id	AND
												mse.sod_order	= @order
									IF @strGlobalSerial <> ''
										BEGIN
											SET @ret_ErrorDescription	= @ret_ErrorDescription + ' ' + @strGlobalSerial
										END
								END

							ELSE IF @itemToProduceIsSerializable = 'true' AND  @bititem_expserInBlankWhenProduced = 'False'
								BEGIN

									DECLARE @counter INT
									EXEC dbo.spCounters_getNextValue @comp_id, 0, 11, @counter_value = @counter OUTPUT
									--SELECT @counter

									SET @serial = 980000000 + @counter
									--SELECT 'nro de serial generado', @serial

									-- si no hay ningún error queda cargado el serial generado en la variable de retorno de mensajes de error
									SET @ret_ErrorDescription	= @ret_ErrorDescription + CONVERT(VARCHAR(100),@serial)
									SET @strGlobalSerial		= CONVERT(VARCHAR(100),@serial)
								END

							/****************************************************************************************************/




							/****************************************************************************************************/
							-- recuperamos el item_id del artículo a producir
							SET @item_id = (SELECT	item_id
												FROM	tbsaleorderdetail	WITH (NOLOCK)
												WHERE	comp_id = @comp_id
												AND		bra_id	= @bra_id
												AND		soh_id	= @soh_id
												AND		sod_id	= @sod_id)
							--SELECT @item_id
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- recuperamos datos del proveedor
							SELECT	TOP 1
									@supplierCurrencyId		= ts.curr_id,
									@supp_id				= ts.supp_id
								FROM	dbo.tbSupplier			ts		WITH (NOLOCK)
								WHERE	ts.comp_id = @comp_id
								AND		ISNULL(ts.supp_isSupp4Production,'false') = 'true'
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- recuperar datos de la compañía
							SELECT	@ct_CompanyCurrency	= c.curr_id
								FROM	dbo.tbCompany			c		WITH (NOLOCK)
								WHERE	c.comp_id	= @comp_id
							/****************************************************************************************************/






							/****************************************************************************************************/
							-- recuperar datos para el insert en tbCommercialTransaction
							DECLARE --@lct_transaction_rv						INT,
									@ct_docNumber							INT,
									@ct_ACurrencyExchange					DECIMAL(19,4),
									@ct_Branch2CompanyCurrencyExchange		DECIMAL(19,4),
									--@lit_transaction_rv						INT,
									@decStorePreviuos						DECIMAL(19,6),
									@now									DATETIME


							-- obtener la fecha actual
							SET @now	= GETDATE()



							-- obtener el próximo número de ct_docNumber en @ct_docNumber
							EXEC dbo.spCounters_getNextValue @comp_id, 0, 12, @counter_value = @ct_docNumber OUTPUT


							-- tipo de cambio de la moneda del cliente a la moneda del artículo
							SELECT @ct_ACurrencyExchange				= dbo.fnGetExchange(@comp_id,1,@supplierCurrencyId,	@ct_CompanyCurrency,	0,0,'False')


							-- tipo de cambio de la moneda de la sucursal a la moneda de la compañia
							SELECT @ct_Branch2CompanyCurrencyExchange	= dbo.fnGetExchange(@comp_id,1,@BranchCurrencyId,	@ct_CompanyCurrency,	0,0,'False')
							/****************************************************************************************************/





							/****************************************************************************************************/
							-- se genera un nuevo comprobante para toda la transacción si no existía uno anterior para el mismo soh_id

							IF EXISTS (SELECT TOP 1 	1
											FROM tbCommercialTransactions tct		WITH (NOLOCK)
											WHERE	tct.comp_id			= @comp_id
											AND		tct.ct_soh_bra_id	= @bra_id
											AND		tct.ct_soh_id		= @soh_id)
								BEGIN

									SELECT	@ct_transaction_rv	= tct.ct_transaction
										FROM	tbCommercialTransactions	tct		WITH (NOLOCK)
										WHERE	tct.comp_id			= @comp_id
										AND		tct.ct_soh_bra_id	= @bra_id
										AND		tct.ct_soh_id		= @soh_id

								END

							ELSE

								BEGIN

									EXEC spCommercialTransactions_InsertPurchaseData
											@comp_id,
											@bra_id,
											0,
											'',
											@ct_docNumber,
											@bra_processingDate,
											@bra_processingDate,
											@bra_processingDate,
											@supp_id,
											NULL,
											NULL,
											NULL,
											@user_id,
											0,									--@ct_subtotal = null,
											0,									--@ct_total = null,
											0,									--@ct_discount = null,
											0,									--@ct_adjust = null,
											0,									--@ct_taxes = null,
											@BranchCurrencyId,					--@curr_id_transaction = null, --moneda de la sucursal
											NULL,								--@hacc_transaction = null,
											NULL,								--@sm_id = null,
											NULL,								--@disc_id = null,
											0,									--@ct_ATotal = null,
											0,									--@ct_ABalance = null,
											@supplierCurrencyId,				--@ct_ACurrency = null, --moneda del proveedor
											@ct_ACurrencyExchange,				--@ct_ACurrencyExchange = null,
											NULL,								--@df_id = null,
											NULL,								--@dl_id = null,
											NULL,								--@st_id = null,
											145,								--@sd_id = null,
											NULL,								--@puco_id = null,
											@ct_CompanyCurrency,				--@ct_CompanyCurrency = null,
											@ct_Branch2CompanyCurrencyExchange, --@ct_Branch2CompanyCurrencyExchange = null,
											NULL,								--@ct_Pending = null,
											@branch_country_id,					--@country_id = null,
											@branch_state_id,					--@state_id = null,
											'false',							--@ct_isAvailableForImport = null,
											NULL,								--@ct_CAI = null,
											NULL,								--@ct_CAIDate = null,
											'',									--@observation1 = null,
											'',									--@observation2 = null,
											'',									--@observation3 = null,
											'',									--@observation4 = null,
											@supplierCurrencyId,				--@curr_id4Exchange = null,
											@ct_ACurrencyExchange,				--@ct_curr_IdExchange = null,

											@return_value			= @ct_transaction_rv		OUTPUT,
											@ret_ErrorCode			= @ret_ErrorCode_rv			OUTPUT,
											@ret_ErrorDescription	= @ret_ErrorDescription_rv	OUTPUT

									--SET @ret_ErrorCode_rv = -2
									IF @ret_ErrorCode_rv <> 0
									BEGIN
										SET @ret_ErrorCode			= @ret_ErrorCode_rv - 100
										SET @ret_ErrorDescription	= @ret_ErrorDescription_rv
										SELECT 1/0
									END



									-- se actualiza la transacción generada con el soh_id correspondiente

									UPDATE	tbCommercialTransactions
										SET		ct_soh_bra_id	= @bra_id,
												ct_soh_id		= @soh_id
										WHERE	comp_id			= @comp_id
										AND		bra_id			= @bra_id
										AND		ct_transaction	= @ct_transaction_rv

								END

							--SELECT '@ct_transaction_rv', @ct_transaction_rv
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- se actualiza el stock, se carga en la trasacción y se genera el serial del artículo producido

							-- actualizar el depósito con el artículo a generar, si existe no lo modifica y si
							-- no existe lo genera con stock en 0 (cero)
							EXEC spItemStorage_insertData @comp_id, @item_id, @stor_id, 0



							-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
							SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
								FROM	tbItemStorage tis		WITH (NOLOCK)
								WHERE	tis.comp_id = @comp_id
								AND		tis.stor_id = @stor_id
								AND		tis.item_id = @item_id



							SET @it_order = 1



							INSERT INTO tbItemTransactions
							(
								comp_id,				bra_id,						ct_transaction,
								item_id,				it_qty,						it_priceWithOutOthers,
								it_price,				curr_id,					it_exchangeToBranchCurrency,
								it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
								it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
								it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
								stor_id,				it_storePrevious,			prli_id,
								byor_id,				it_isProduction,			it_isAssociation,
								it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
								it_order,				so_id,						it_guarantee,
								it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
								it_CreditIntPlus,		puco_id,					it_poh_bra_id,
								it_poh_id,				it_soh_id,					it_sod_id,
								rmah_id,				rmad_id,					it_qty_rma,
								it_tis_id_aux
							)
							VALUES
							(
				 				@comp_id,				@bra_id,					@ct_transaction_rv,
								@item_id,				1,							0,
								0,						@supplierCurrencyId,		@supplierCurrencyId,
								0,						0,							0,
								0,						0,							0,
								0,						@supplierCurrencyId,		1,
								@stor_id,				isnull(@decStorePreviuos,0),NULL,
								NULL,					'False',					'False',
								NULL,					@now,						NULL,
								@it_order,				NULL,						0,
								0,						0,							0,
								0,						NULL,						NULL,
								NULL, 					@soh_id, 					@sod_id,
								NULL,					NULL,						NULL,
								NULL
							)

							SET @it_transaction_rv = @@IDENTITY



							-- se incorpora el artículo al depósito
							UPDATE	tbItemStorage
								SET		itst_cant	= itst_cant + 1,
										itst_cd		= @now
								WHERE	comp_id		= @comp_id
								AND		stor_id		= @stor_id
								AND		item_id		= @item_id



							IF @itemToProduceIsSerializable = 'true'
								BEGIN
									DECLARE @is_id INT




									-- se carga el artículo producido en tbItemSerial con el serial recién generado
									INSERT INTO tbItemSerials
									(
										comp_id,
										-- is_id -- this column value is auto-generated,
										bra_id,
										ct_transaction,
										it_transaction,
										item_id,
										is_serial,
										is_cd,
										is_available,
										stor_id,
										is_guid,
										is_IsOwnGeneration,
										is_checked,
										is_printed
									)
									VALUES
									(
										@comp_id,
										@bra_id,
										@ct_transaction_rv,
										@it_transaction_rv,
										@item_id,
										CASE
											WHEN @bititem_expserInBlankWhenProduced = 'True' AND @strGlobalSerial = '' THEN ''
											ELSE @strGlobalSerial  --convert(varchar,@serial)
										END,
										@now,
										CASE
											WHEN @bititem_expserInBlankWhenProduced = 'True' AND @strGlobalSerial = '' THEN 'False'
											ELSE 'True'
										END,
										@stor_id,
										@guid,
										'true',
										'false',
										'false'
									)

									SET @is_id = @@IDENTITY

									-- si no hay ningún tipo de error, se retorna el is_id generado en el return_value
									SET @return_value = @is_id

								END

							ELSE

								BEGIN

									SET @return_value = 999999999

								END


							-- Se relacionan los numeros de serie de las partes a los numeros de serie generados.-
							IF @itemToProduceIsSerializable = 'true'
								BEGIN

									IF @bra_checkSerialNumber = 'true'
										BEGIN

											-- se cargan las relaciones del artículo producido con los artículos que lo componen
											-- si se tomaron los seriales en la página
											INSERT INTO tbItemSerials4Production
											(
												comp_id,
												is_idProduced,
												is_idPart,
												-- is4p_id -- this column value is auto-generated,
												soh_id,
												sod_id,
												is4p_order,
												[user_id],
												bra_id
											)
											SELECT	@comp_id,
													@is_id,
													tsosp.is_id,
													@soh_id,
													@sod_id,
													@order,
													@user_id,
													@bra_id
												FROM	tbSaleOrderSerial4Production tsosp
												WHERE	tsosp.comp_id		= @comp_id
												-- MOS 09.2014 AND		tsosp.sosp_guid		= @guid
												AND		tsosp.soh_id		= @soh_id
												AND		tsosp.sod_id		= @sod_id
												AND		tsosp.sosp_order	= @order

										END
									ELSE
										BEGIN

											-- se cargan las relaciones del artículo producido con todos artículos que componen
											-- el lote completo de lo que serializó en el pedido
											INSERT INTO tbItemSerials4Production
											(
												comp_id,
												is_idProduced,
												is_idPart,
												-- is4p_id -- this column value is auto-generated,
												soh_id,
												sod_id,
												is4p_order,
												[user_id],
												bra_id
											)
											SELECT	@comp_id,
													@is_id,
													tis.is_id,
													@soh_id,
													@sod_id,
													@order,
													@user_id,
													@bra_id

											FROM	tbSaleOrderDetail					tsod		WITH (NOLOCK)

													INNER JOIN tbItemComposition		tic			WITH (NOLOCK)
													ON	tic.comp_id		= tsod.comp_id
													AND tic.item_id		= tsod.item_id
													INNER JOIN tbSaleOrderSerials		tsos		WITH (NOLOCK)
													ON	tsos.comp_id	= tsod.comp_id
													AND tsos.bra_id		= tsod.bra_id
													AND tsos.soh_id		= tsod.soh_id
													INNER JOIN tbItemSerials			tis			WITH (NOLOCK)
													ON	tis.is_id		= tsos.is_id
													AND tis.comp_id		= tsod.comp_id
													AND tis.item_id		= tic.item_id_1

											WHERE	tsod.comp_id		= @comp_id
											AND		tsod.bra_id			= @bra_id
											AND		tsod.soh_id			= @soh_id
											AND		tsod.sod_id			= @sod_id
											--AND		tis.is_available	= 'false'			MOS, si esta en tbSaleOrderSerials debe ir igual ya que siempre deberia estar en false en ese estado.-

											ORDER BY tis.item_id

										END

							END
							/****************************************************************************************************/




							/****************************************************************************************************/
							--este query no estaba en el sp original, el anterior a la modificación
							--			SELECT	DISTINCT tic.item_id_1, tic.icomp_qty
							--
							--			FROM	tbSaleOrderSerial4Production		tsosp
							--					INNER JOIN tbSaleOrderDetail		tsod
							--					ON	tsod.comp_id	= tsosp.comp_id
							--					AND tsod.soh_id		= @soh_id
							--					AND tsod.sod_id		= @sod_id
							--					INNER JOIN tbItemComposition tic
							--					ON	tic.comp_id		= tsod.comp_id
							--					AND tic.item_id		= tsod.item_id
							--
							--			WHERE	tsosp.comp_id	= @comp_id
							--			AND		tsosp.sosp_guid = @guid
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- cursor para recuperar los artículos que componen el artículo a producir, y actualizar los stocks
							-- correspondientes

							DECLARE @litem_id_1			INT,
									@licomp_qty			DECIMAL(19,6)


							DECLARE cursor_itemsComposition CURSOR LOCAL FAST_FORWARD FOR
															SELECT	DISTINCT	tic.item_id_1,
																				tic.icomp_qty
																FROM	tbItemComposition					tic
																WHERE	tic.comp_id	= @comp_id
																AND		tic.item_id = @item_id



							OPEN cursor_itemsComposition

							FETCH NEXT FROM cursor_itemsComposition INTO @litem_id_1, @licomp_qty

							WHILE @@FETCH_STATUS = 0
							BEGIN

								-- se actualiza el stock de los artículos que componen el artículo generado

								-- actualizar el depósito con el artículo a generar, si existe no lo modifica y si
								-- no existe lo genera con stock en 0 (cero)
								EXEC spItemStorage_insertData @comp_id, @litem_id_1, @stor_id, 0



								-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
								SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
									FROM	tbItemStorage tis		-- NOOO  		WITH (NOLOCK)
									WHERE	tis.comp_id = @comp_id
									AND		tis.stor_id = @stor_id
									AND		tis.item_id = @litem_id_1



								SET @it_order = @it_order + 1


		--
		-- ATENCION, aca se deberia buscar si ya hay un itemtrans para ese itemId asi no se generan cientos de registros
		-- al pedo cuando se produce un lote de eq	uipos.
		--

								INSERT INTO tbItemTransactions
								(
									comp_id,				bra_id,						ct_transaction,
									item_id,				it_qty,						it_priceWithOutOthers,
									it_price,				curr_id,					it_exchangeToBranchCurrency,
									it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
									it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
									it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
									stor_id,				it_storePrevious,			prli_id,
									byor_id,				it_isProduction,			it_isAssociation,
									it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
									it_order,				so_id,						it_guarantee,
									it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
									it_CreditIntPlus,		puco_id,					it_poh_bra_id,
									it_poh_id,				it_soh_id,					it_sod_id,
									rmah_id,				rmad_id,					it_qty_rma,
									it_tis_id_aux
								)
								VALUES
								(
					 				@comp_id,				@bra_id,					@ct_transaction_rv,
									@litem_id_1,			@licomp_qty * -1,			0,
									0,						@supplierCurrencyId,		@supplierCurrencyId,
									0,						0,							0,
									0,						0,							0,
									0,						@supplierCurrencyId,		1,
									@stor_id,				isnull(@decStorePreviuos,0),NULL,
									NULL,					'False',					'False',
									NULL,					@now,						NULL,
									@it_order,				NULL,						0,
									0,						0,							0,
									0,						NULL,						NULL,
									NULL, 					@soh_id, 					@sod_id,
									NULL,					NULL,						NULL,
									NULL
								)





								-- se incorpora el artículo al depósito
								UPDATE	tbItemStorage
								SET		itst_cant	= itst_cant - @licomp_qty,
										itst_cd		= @now
								WHERE	comp_id		= @comp_id
								AND		stor_id		= @stor_id
								AND		item_id		= @litem_id_1




								FETCH NEXT FROM cursor_itemsComposition INTO @litem_id_1, @licomp_qty

							END

							CLOSE cursor_itemsComposition
							DEALLOCATE cursor_itemsComposition
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- se envía a la history el pedido original y se borra el pedido original si ya se produjeron
							-- todos los artículos


							-- se recuperan todos los artículos a producir
							SELECT	tsod.comp_id,  tsod.soh_id,  tsod.sod_id,  CONVERT(INT,tsod.sod_qty) [sod_qty]
								INTO	#tmpItemsToProduce
								FROM	tbSaleOrderDetail tsod		WITH (NOLOCK)
								WHERE	tsod.comp_id	= @comp_id
								AND		tsod.bra_id		= @bra_id
								AND		tsod.soh_id		= @soh_id


							-- se recuperan todos los artículos producidos
							SELECT	tsosp.comp_id, tsosp.soh_id, tsosp.sod_id, COUNT(*) [sod_qty]
								INTO	#tmpItemsProduced
								FROM	tbSaleOrderSerialProduced tsosp		WITH (NOLOCK)
								WHERE	tsosp.comp_id	= @comp_id
								AND		tsosp.soh_id	= @soh_id
								GROUP BY tsosp.comp_id, tsosp.soh_id, tsosp.sod_id
							--SELECT '#tmpItemsProduced', * FROM #tmpItemsProduced


							-- se obtiene la cantidad de artículos a producir
							DECLARE @ItemsToProduce			INT
							SELECT	@ItemsToProduce = COUNT(*)
							FROM	#tmpItemsToProduce titp


							-- se obtiene la cantidad de items producidos en su totalidad
							DECLARE @ItemsProduced			INT

							SELECT	@ItemsProduced	= COUNT(*)
								FROM	#tmpItemsToProduce titp
										INNER JOIN #tmpItemsProduced tip
								ON		titp.comp_id	= tip.comp_id
								AND		titp.soh_id		= tip.soh_id
								AND		titp.sod_id		= tip.sod_id
								AND		titp.sod_qty	= tip.sod_qty

							DROP TABLE #tmpItemsToProduce
							DROP TABLE #tmpItemsProduced
							--SELECT @ItemsToProduce,  @ItemsProduced






							/****************************************************************************************************/
							--actualización de costos del artículo producido con la sumatoria de los costos de los artículos que
							--lo componen desde la lista de costos a la lista de costos definidas en el documento de producción
							------------------------------------------------------------------------------------------------------

							--validamos que en el documento del pedido estén definidas las listas de costos de donde tomar los
							--costos (origen) y donde grabar ese costo (destino)
							IF EXISTS	(
										SELECT TOP 1 	1
											FROM	tbSaleOrderHeader					tsoh		WITH (NOLOCK)

													INNER JOIN 	tbDocumentsFile			tdf			WITH (NOLOCK)
													ON	tdf.comp_id					= tsoh.comp_id
													AND tdf.df_id					= tsoh.df_id
													AND NOT tdf.coslis_id_origin	IS NULL
													AND NOT tdf.coslis_id_destiny	IS NULL

											WHERE	tsoh.comp_id	= @comp_id	AND
													tsoh.bra_id		= @bra_id	AND
													tsoh.soh_id		= @soh_id
										)
							BEGIN

								DECLARE @costlis_id_origin		INT,
										@costlis_id_destiny		INT,
										@curr_id				INT


								-- recuperamos las listas de costos de origen y destino
								SELECT	@costlis_id_origin		= tdf.coslis_id_origin,
										@costlis_id_destiny		= tdf.coslis_id_destiny

									FROM	tbSaleOrderHeader					tsoh			WITH (NOLOCK)

											INNER JOIN 	tbDocumentsFile			tdf				WITH (NOLOCK)
											ON	tdf.comp_id					= tsoh.comp_id
											AND tdf.df_id					= tsoh.df_id
											AND NOT tdf.coslis_id_origin	IS NULL
											AND NOT tdf.coslis_id_destiny	IS NULL

									WHERE	tsoh.comp_id	= @comp_id	AND
											tsoh.bra_id		= @bra_id	AND
											tsoh.soh_id		= @soh_id




								-- si no existe el artículo generado en la lista de costos destino, se lo incluye
								IF NOT EXISTS	(
												SELECT	1
													FROM	tbItemCostList		ticl		WITH (NOLOCK)
													WHERE	ticl.comp_id	= @comp_id
													AND		ticl.coslis_id	= @costlis_id_destiny
													AND		ticl.item_id	= @item_id
												)
								BEGIN

									-- recuperamos la moneda del artículo a generar
									SELECT	@curr_id	= ti.curr_id
										FROM	tbItem						ti		WITH (NOLOCK)
										WHERE	ti.comp_id	= @comp_id
										AND		ti.item_id	= @item_id



									INSERT INTO tbItemCostList
									(
										comp_id,
										coslis_id,
										item_id,
										coslis_price,
										coslis_price_aw,
										curr_id,
										coslis_cd,
										coslis_price_Original,
										coslis_price_Disc1,
										coslis_price_Disc2,
										coslis_price_Disc3,
										coslis_price_Disc4
									)
									VALUES
									(
										@comp_id,
										@costlis_id_destiny,
										@item_id,
										0,
										0,
										@curr_id,
										GETDATE(),
										0,
										0,
										0,
										0,
										0
									)

								END




								-- actualizamos los costos del artículo generado en base a la suma de los costos
								-- de los artículos que lo componen

								DECLARE @coslis_price		DECIMAL(19,5),
										@coslis_price_aw	DECIMAL(19,5)


								SELECT 	@coslis_price		= SUM(tic.icomp_qty * dbo.fnGetExchange2(	@comp_id,
																										ticl2.coslis_price,
																										ticl2.curr_id, ticl.curr_id,
																										ticl2.curr_id, ticl.curr_id,
																										0, 'false')),
										@coslis_price_aw	= SUM(tic.icomp_qty * dbo.fnGetExchange2(	@comp_id,
																										ticl2.coslis_price_aw,
																										ticl2.curr_id, ticl.curr_id,
																										ticl2.curr_id, ticl.curr_id,
																										0, 'false'))

								FROM	tbItemCostList						ticl		WITH (NOLOCK)

										INNER JOIN tbItemComposition	 	tic			WITH (NOLOCK)
										ON	tic.comp_id		= ticl.comp_id
										AND tic.item_id		= ticl.item_id

										INNER JOIN tbItemCostList			ticl2		WITH (NOLOCK)
										ON	ticl2.comp_id	= ticl.comp_id
										AND ticl2.coslis_id = @costlis_id_origin
										AND ticl2.item_id	= tic.item_id_1

								WHERE	ticl.comp_id		= @comp_id
								AND		ticl.coslis_id		= @costlis_id_destiny
								AND		ticl.item_id		= @item_id




								UPDATE	tbItemCostList

								SET		coslis_price		= IsNull(@coslis_price,0),
										coslis_price_aw		= IsNull(@coslis_price_aw,0),
										coslis_cd			= GETDATE()

								WHERE	comp_id		= @comp_id
								AND		coslis_id	= @costlis_id_destiny
								AND		item_id		= @item_id


							END
							/****************************************************************************************************/





								/*****************************************************************************************************************************/
								-- FALTA:
								-- Aqui se debe generar los tbImportData correspondientes a cada tbItemTransaction de la transaccion de produccion
								-- Lo que hay que hacer es tomar todos los numeros de serie y descontar uno del tbimportdata correspondiente
								-- (OJO, agrupados por is_id asi
								-- no se duplican cuando la serializacion es del total de los numeros de serie por cada item producido).
								-- Para los items que no tienen expser en true se debe descontar de los despachos mas viejos segun el ejemplo.
								-- (o sea de los despachos que tengan impData_ActualQty > 0)
								-- Por cada despacho descontado hay que generar un impData_id para la it_transaction del item (que es una por cada
								-- item producido) con la concatenacion de los numeros
								-- de despacho de cada una de sus partes (en si con impData_Custom_local y el resto que son varchar(200)
								--
								-- Hay un tema cuando se toman los numeros de serie globales para todos los items producidos que es que puede haber
								-- mas de un despacho por cada item por lo que la concatenacion
								-- podria ser gigante y no entrar en los 200 caracteres del item producido.  la actitud a tomar en este caso es la siguiente:
								--		ir marcando como ya usadop en una temporal los numeros de serie de cada parte y tomar solo los de un serial
								--		correspondiente (o los que la qty de itemComposition diga!!)
								--      de esta manera solo habra un despacho por componente del equipo final.
								-- Como se vera el equipo final tendra un despacho DIFERENTE por cada componente los que tendran que ir conatenados
								-- y quedar grabados en la tbImportdata del it_transaction producido.
								--	Por esto se debe verificar cuando, item por item del ct_transaction producido, en un cursor, al grabar su importdata,
								--	que al concatenar, no este ya ese numero de despacho ya que podrian haber varias partes con el mismo.  hacer este
								--	control para todos los campos varchar(200)
								-- Como ejemplo de los despachos sin numero de serie tenes la linea 515 del sp : [spItemTransactionImportData_InsertData]
								-- y para los que si tienen serial la linea 234, aunque ese es el mas facil porque buscas el impdata_id del it_transaction
								-- del is_id en la tabla tbItemSerials
								/*****************************************************************************************************************************/
								/*****************************************************************************************************************************/
								--SELECT 'ok'

								DECLARE @llitem_id_1					INT,
										@llicomp_qty					DECIMAL(18,5),
										@llitem_expser					BIT,
										@llimpData_id					INT,

										@llimpData_Custom_local			VARCHAR(200),
										@llimpData_Custom_local_all		VARCHAR(200),

										@llimpData_Number_local			VARCHAR(200),
										@llimpData_Number_local_all		VARCHAR(200),

										@llimpData_Origin				VARCHAR(200),
										@llimpData_Origin_all			VARCHAR(200),

										@llimpData_From					VARCHAR(200),
										@llimpData_From_all				VARCHAR(200),

										@llimpdata_Stamp				VARCHAR(200),
										@llimpdata_Stamp_all			VARCHAR(200)



								SELECT	@llimpData_Custom_local			= '',
										@llimpData_Custom_local_all		= '',
										@llimpData_Number_local			= '',
										@llimpData_Number_local_all		= '',
										@llimpData_Origin				= '',
										@llimpData_Origin_all			= '',
										@llimpData_From					= '',
										@llimpData_From_all				= '',
										@llimpdata_Stamp				= '',
										@llimpdata_Stamp_all			= ''



								--obtenemos los artículos que componen el artículo producido
								DECLARE cursor_icomposition CURSOR LOCAL FAST_FORWARD FOR
									SELECT	tic.item_id_1,
											tic.icomp_qty,
											ti.item_expser
										FROM	tbSaleOrderDetail				tsod		WITH (NOLOCK)
												INNER JOIN tbItemComposition	tic
													ON	tic.comp_id	= tsod.comp_id	AND
														tic.item_id	= tsod.item_id
												INNER JOIN tbItem				ti			WITH (NOLOCK)
													ON	ti.comp_id	= tsod.comp_id	AND
														ti.item_id	= tic.item_id_1
										WHERE	tsod.comp_id	= @comp_id
										AND		tsod.soh_id		= @soh_id
										AND		tsod.sod_id		= @sod_id



								OPEN cursor_icomposition

								FETCH NEXT FROM cursor_icomposition INTO
																@llitem_id_1,
																@llicomp_qty,
																@llitem_expser


								--recorremos la composición del artículo producido
								WHILE @@FETCH_STATUS = 0
								BEGIN


										-- -----------------------------------------------------------
										-- aca grabamos la composicion de este item al producirlo
										-- por si se cambia en el medio de un lote
										-- item_id es el nuevo item producido
										-- item_id_1 son las partes
										-- -----------------------------------------------------------
										INSERT INTO tbItemtransactionsProductionParts
										(
											comp_id,
											-- itp_id -- this column value is auto-generated,
											bra_id,
											ct_transaction,
											it_transaction,
											item_id_produced,
											item_id_partOf,
											item_id_partOf_qty,
											itp_loteNumber,
											itp_note, soh_id, sod_id, itp_order
										)
										SELECT 	@comp_id,
												@bra_id,
												@ct_transaction_rv,
												@it_transaction_rv,
												tic.item_id,
												tic.item_id_1,
												tic.icomp_qty,
												@order,
												'Nota',
												@soh_id,
												@sod_id,
												@order
											FROM tbItemComposition tic		WITH (NOLOCK)
											WHERE	tic.comp_id = @comp_id AND
													tic.item_id = @item_id

										-- -----------------------------------------------------------


										IF @llitem_expser = 'true'
											BEGIN
												-- proceso para los artículos que componene el producido que son serializados



												-- obtenemos los importData relacionados a la serialización del pedido de producción  MOS 07-2013
												DECLARE cursor_import_data CURSOR LOCAL FAST_FORWARD FOR
													SELECT	tid.impData_id
														FROM	tbImportData					tid		WITH (NOLOCK)
															INNER JOIN tbItemSerials			tis		WITH (NOLOCK)
																ON	tis.comp_id			= tid.comp_id
																AND tis.ct_transaction	= tid.ct_transaction
																AND tis.it_transaction	= tid.it_transaction
															INNER JOIN tbSaleOrderSerials		tsos	WITH (NOLOCK)
																ON	tsos.comp_id		= tid.comp_id
																AND tsos.is_id			= tis.is_id
														WHERE	tid.comp_id				= @comp_id
															AND tis.item_id				= @llitem_id_1
															AND tsos.comp_id			= @comp_id
															AND	tsos.bra_id				= @bra_id
															AND	tsos.soh_id				= @soh_id

												OPEN cursor_import_data

												FETCH cursor_import_data INTO @llimpData_id


												-- recorremos los importData obtenidos
												WHILE @@FETCH_STATUS = 0
												BEGIN

													SET @llimpData_Number_local = ''
													SET @llimpData_Custom_local	= ''
													SET @llimpData_Origin		= ''
													SET @llimpData_From			= ''
													SET @llimpdata_Stamp		= ''


													--obtenemos el número de despacho
													SELECT	@llimpData_Number_local	= ltrim(rtrim(ISNULL(tid.impData_Number_local,''))),
															@llimpData_Custom_local	= ltrim(rtrim(ISNULL(tid.impData_Custom_local,''))),
															@llimpData_Origin		= ltrim(rtrim(ISNULL(tid.impData_Origin,''))),
															@llimpData_From			= ltrim(rtrim(ISNULL(tid.impData_From,''))),
															@llimpdata_Stamp		= ltrim(rtrim(ISNULL(tid.impdata_Stamp,'')))
														FROM	tbImportData				tid		WITH (NOLOCK)
														INNER JOIN tbItem					ti		WITH (NOLOCK)
															ON	ti.comp_id = tid.comp_id AND
																ti.item_id = tid.item_id
														WHERE	tid.comp_id		= @comp_id		AND
																tid.impData_id	= @llimpData_id	AND
																ISNULL(ti.impData_ExcludeWhenProduce,'False') = 'False'


													--si los números no existen en cada acumulado se almacenan en el mismo
													IF CHARINDEX(@llimpData_Number_local,@llimpData_Number_local_all) = 0 AND @llimpData_Number_local <> ''
														SET @llimpData_Number_local_all = @llimpData_Number_local_all + @llimpData_Number_local + '*'

													IF CHARINDEX(@llimpData_Custom_local,@llimpData_Custom_local_all) = 0 AND @llimpData_Custom_local <> ''
														SET @llimpData_Custom_local_all = @llimpData_Custom_local_all + @llimpData_Custom_local + '*'

													IF CHARINDEX(@llimpData_Origin,@llimpData_Origin_all) = 0
														SET @llimpData_Origin_all = @llimpData_Origin_all + @llimpData_Origin + '*'

													IF CHARINDEX(@llimpData_From,@llimpData_From_all) = 0 AND @llimpData_Origin <> ''
														SET @llimpData_From_all = @llimpData_From_all + @llimpData_From + '*'

													IF CHARINDEX(@llimpdata_Stamp,@llimpdata_Stamp_all) = 0 AND @llimpdata_Stamp <> ''
														SET @llimpdata_Stamp_all = @llimpdata_Stamp_all + @llimpdata_Stamp + '*'


													--se resta 1 de la cantidad disponible del imprtData obtenido
													UPDATE	tbImportData
														SET		impData_ActualQty	= impData_ActualQty - 1
														WHERE	comp_id		= @comp_id
														AND		impData_id	= @llimpData_id


													FETCH cursor_import_data INTO @llimpData_id

												END

												CLOSE cursor_import_data
												DEALLOCATE cursor_import_data



											END

										ELSE

											BEGIN
												-- proceso para los artículos que componene el producido que NO son serializados


												--loop de proceso por la cantidad de cada artículo que compone el producido
												WHILE @llicomp_qty > 0
												BEGIN


													--obtenemos el importData que primero de fecha más vieja que tenga cantidad disponible del artículo a procesar
													SELECT	TOP 1 @llimpData_id = tid.impData_id

														FROM	tbImportData tid						WITH (NOLOCK)
														INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
															ON	tct.comp_id			= tid.comp_id
															AND tct.bra_id			= tid.bra_id
															AND tct.ct_transaction	= tid.ct_transaction

														WHERE	tid.comp_id = @comp_id
														AND 	tid.item_id = @llitem_id_1
														AND		tid.impData_ActualQty > 0
														ORDER BY tid.impdata_Priority,tct.ct_date ASC


													--obtenemos el número de despacho
													SELECT	@llimpData_Number_local	= ltrim(rtrim(tid.impData_Number_local)),
															@llimpData_Custom_local	= ltrim(rtrim(tid.impData_Custom_local)),
															@llimpData_Origin		= ltrim(rtrim(tid.impData_Origin)),
															@llimpData_From			= ltrim(rtrim(tid.impData_From)),
															@llimpdata_Stamp		= ltrim(rtrim(tid.impdata_Stamp))
														FROM	tbImportData				tid		WITH (NOLOCK)
														WHERE	tid.comp_id		= @comp_id
														AND		tid.impData_id	= @llimpData_id


														--si los números no existen en cada acumulado se almacenan en el mismo
														IF CHARINDEX(@llimpData_Number_local,@llimpData_Number_local_all) = 0 AND @llimpData_Number_local <> ''
															SET @llimpData_Number_local_all = @llimpData_Number_local_all + @llimpData_Number_local + '*'

														IF CHARINDEX(@llimpData_Custom_local,@llimpData_Custom_local_all) = 0 AND @llimpData_Custom_local <> ''
															SET @llimpData_Custom_local_all = @llimpData_Custom_local_all + @llimpData_Custom_local + '*'

														IF CHARINDEX(@llimpData_Origin,@llimpData_Origin_all) = 0 AND @llimpData_Origin <> ''
															SET @llimpData_Origin_all = @llimpData_Origin_all + @llimpData_Origin + '*'

														IF CHARINDEX(@llimpData_From,@llimpData_From_all) = 0 AND @llimpData_From <> ''
															SET @llimpData_From_all = @llimpData_From_all + @llimpData_From + '*'

														IF CHARINDEX(@llimpdata_Stamp,@llimpdata_Stamp_all) = 0 AND @llimpdata_Stamp <> ''
															SET @llimpdata_Stamp_all = @llimpdata_Stamp_all + @llimpdata_Stamp + '*'


													--se resta 1 de la cantidad disponible del imprtData obtenido
													UPDATE	tbImportData
														SET		impData_ActualQty	= impData_ActualQty - 1
														WHERE	comp_id		= @comp_id
														AND		impData_id	= @llimpData_id


													SET @llicomp_qty = @llicomp_qty - 1

												END
											END


									FETCH NEXT FROM cursor_icomposition INTO @llitem_id_1, @llicomp_qty, @llitem_expser
								END

								CLOSE cursor_icomposition
								DEALLOCATE cursor_icomposition





								-- MOS 07-2013.  Genera un importdata x cada it_transaction
								-- Mas adelante para ascelerar esto deberia producir un solo it_transaction
								-- por cada sod_id y un solo importdata.
								INSERT INTO tbImportData
									(
									comp_id,
									item_id,
									-- impData_id -- this column value is auto-generated,
									impData_InitialQty,
									impData_ActualQty,
									ct_transaction,
									it_transaction,
									bra_id,
									impData_Custom_local,
									impData_Number_local,
									/* impData_ExpirationDate,  --por default getdate() */
									impData_Origin,
									impData_From,
									impdata_Stamp
									)
								VALUES(
										@comp_id,
										@item_id,
										1,
										1,
										@ct_transaction_rv,
										@it_transaction_rv,
										@bra_id,
										@llimpData_Custom_local_all,
										@llimpData_Number_local_all,
										/* impData_ExpirationDate	*/
										@llimpData_Origin_all,
										@llimpData_From_all,
										@llimpdata_Stamp_all
									  )




							-- ------------------------------------------------------------------------------------------
							-- si la cantidad de artículos a producir es la misma que la cantidad de artículos producidos
							-- entonces se envía el pedido al histórico y se elimina el pedido original
							-- ------------------------------------------------------------------------------------------
							IF @ItemsToProduce = @ItemsProduced
							BEGIN

								EXEC spSaleOrderHistory_InsertFromSaleOrder
									@comp_id,
									@bra_id,
									@soh_id,
									100,
									NULL,
									@user_id,''

								DELETE FROM tbSaleOrderExtendedDiscount
								WHERE	comp_id = @comp_id
								AND		bra_id	= @bra_id
								AND		soh_id	= @soh_id

								DELETE FROM tbSaleOrderTaxes
								WHERE	comp_id = @comp_id
								AND		bra_id	= @bra_id
								AND		soh_id	= @soh_id

								DELETE FROM tbSaleOrderLoan
								WHERE	comp_id = @comp_id
								AND		bra_id	= @bra_id
								AND		soh_id	= @soh_id

								DELETE FROM tbSaleOrderSerialProduced
								WHERE	comp_id = @comp_id
								AND		soh_id	= @soh_id

								DELETE FROM tbSaleOrderSerials
								WHERE	comp_id = @comp_id
								AND		bra_id	= @bra_id
								AND		soh_id	= @soh_id

								DELETE FROM tbSaleOrderDetail
								WHERE	comp_id = @comp_id
								AND		bra_id	= @bra_id
								AND		soh_id	= @soh_id

								DELETE FROM tbSaleOrderHeader
								WHERE	comp_id = @comp_id
								AND		bra_id	= @bra_id
								AND		soh_id	= @soh_id

								DELETE FROM tbSaleOrderSerial4Production
								WHERE	comp_id = @comp_id
								AND		bra_id	= @bra_id
								AND		soh_id	= @soh_id

								DELETE FROM tbSaleOrderSerialInProduction
								WHERE	comp_id = @comp_id
								AND		bra_id	= @bra_id
								AND		soh_id	= @soh_id

								DELETE FROM tbSaleOrderSerial4Production_MasterSerial
								WHERE	comp_id = @comp_id
								AND		bra_id	= @bra_id
								AND		soh_id	= @soh_id

							END
							-- ------------------------------------------------------------------------------------------




						END

					ELSE
						BEGIN

							--validación incorrecta, no están todos los artículos asociados tomados


							SET		@return_value			= -2
							SET		@ret_ErrorCode			= -2
							SELECT	@ret_ErrorDescription	= tut.utexts_desc
								FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
								WHERE	tut.lang_id		= @lang_id
								AND		tut.utexts_id	= 19

							--==
							--SELECT @sumEstado , @bra_checkSerialNumber
							--SELECT '*', @return_value,@ret_ErrorCode	,@ret_ErrorDescription
							--==
								COMMIT TRANSACTION T2
							--ROLLBACK TRANSACTION T2
							RETURN
						END

			END

		ELSE

			BEGIN

				-- no hay definido ningún proveedor para producción entonces retornamos el mensaje correspondiente
				SET		@return_value			= -3
				SET		@ret_ErrorCode			= -3
				SELECT	@ret_ErrorDescription	= tut.utexts_desc
					FROM	tbsysUniqueTexts tut	WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id
					AND		tut.utexts_id	= 17

			END


		COMMIT TRANSACTION T2


	END
	TRY BEGIN CATCH

		IF @ret_ErrorCode < -100
			BEGIN

				SET @return_value			= @ct_transaction_rv
				SET @ret_ErrorCode			= @ret_ErrorCode_rv
				SET @ret_ErrorDescription	= @ret_ErrorDescription_rv

			END
		ELSE
			BEGIN

				SET @return_value			= -1
				SET @ret_ErrorCode			= ERROR_NUMBER()
				SET @ret_ErrorDescription	= ERROR_MESSAGE()
			END

		ROLLBACK TRANSACTION T2

	END CATCH

END

GO




-- Log
-- MOS 08-2024: Creado en base a spSaleOrderSerialProduced_produceSerialData  ticket 21434
-- El original era MIERDA PURA HECHA POR UN ENFERMO HIOjo de RECONTRA RE NMIPL PUTAS que decia que sabia progamar y era un FORRRRRRRRRRRROOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOO


CREATE PROCEDURE [dbo].[spSaleOrderSerialProduced_produceSerialData_ByQty]
(
    @comp_id					INT,
    @lang_id					INT,
    @bra_id						INT,
    @user_id					INT,
	@soh_id						INT,
	@sod_id						INT,
	@order						INT,
	@guid						UNIQUEIDENTIFIER,
	@return_value				INT				OUTPUT,
	@ret_ErrorCode				INT 			OUTPUT,
	@ret_ErrorDescription		NVARCHAR(MAX)	OUTPUT
)
AS

BEGIN

	SET NOCOUNT ON


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id					INT,
			@lang_id					INT,
			@bra_id						INT,
			@user_id					INT,
			@soh_id						INT,
			@sod_id						INT,
			@order						INT,
			@guid						UNIQUEIDENTIFIER,
			@return_value				INT,
			@ret_ErrorCode				INT,
			@ret_ErrorDescription		VARCHAR(500)
	select	@comp_id					=1,
			@lang_id					=2,
			@bra_id						=1,
			@user_id					=1,
			@soh_id						=32634,
			@sod_id						=20899,
			@order						=3,
			@guid						='886883ed-582c-4e8b-99d0-d5769ec7c8bc'
			--@return_value				INT,
			--@ret_ErrorCode			INT,
			--@ret_ErrorDescription		VARCHAR(200)

	IF NOT OBJECT_ID('tempdb.dbo.#tmpValidation')		IS NULL DROP TABLE #tmpValidation
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsNeeded')		IS NULL DROP TABLE #tmpItemsNeeded
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsFree')		IS NULL DROP TABLE #tmpItemsFree
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsToProduce')	IS NULL DROP TABLE #tmpItemsToProduce
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsProduced')	IS NULL DROP TABLE #tmpItemsProduced
	*/
	-- -------------------------------------------------------------------------------


	BEGIN TRANSACTION T2
	BEGIN TRY


		SET @return_value			= 0
		set @ret_ErrorCode			= 0
		set @ret_ErrorDescription	= ''



		/*********************************************************************************************************/
		-- verificamos si hay algún proveedor definido para producción
		IF EXISTS (	SELECT	TOP 1 1
	           			FROM	dbo.tbSupplier			ts		WITH (NOLOCK)
						WHERE	ts.comp_id = @comp_id
						AND		ISNULL(ts.supp_isSupp4Production,'false') = 'true' )
			BEGIN


				DECLARE @bra_processingDate			DATETIME,
						@prli_id					INT,
						@intStor_id_b				INT,
						@intSm_id					INT,
						@intDisc_id					INT,
						@intDl_id					INT,
						@intSt_id					INT,
						@ct_CompanyCurrency			INT,
						@supplierCurrencyId			INT,
						@BranchCurrencyId			INT,
						@supp_id					INT,
						@ct_transaction_rv			INT,
						@it_transaction_rv			INT,
						@stor_id					INT,
						@item_id					INT,
						@bra_checkSerialNumber		BIT,
						@it_order					INT,
						@ret_ErrorCode_rv			INT,
						@ret_ErrorDescription_rv	VARCHAR(200),
						@branch_country_id			INT,
						@branch_state_id			INT,
						@itemToProduceIsSerializable	BIT,
						@bititem_expserInBlankWhenProduced	AS BIT,
						@decQTY								AS DECIMAL(19,4)




				/*********************************************************************************************************/
				--seteamos en una variable si el artículo a producir es serializable o no

				SELECT	@itemToProduceIsSerializable		= IsNull(ti.item_expser,'False'),
						@bititem_expserInBlankWhenProduced	= isnull(ti.item_expserInBlankWhenProduced,'False'),
						@stor_id							= tsod.stor_id,
						@decQTY								= tsod.sod_qty,
						@item_id							= tsod.item_id
				   FROM tbSaleOrderDetail tsod			WITH (NOLOCK)
					INNER JOIN tbItem ti				WITH (NOLOCK)
						ON	ti.comp_id		= tsod.comp_id	AND
							ti.item_id		= tsod.item_id
				   WHERE	tsod.comp_id	= @comp_id
					AND		tsod.bra_id		= @bra_id
					AND		tsod.soh_id		= @soh_id
					AND		tsod.sod_id		= @sod_id

				--SELECT @itemToProduceIsSerializable
				/********************************************************************************************************/



				-- Para compensar la FORRADA del RHDRMP
				DECLARE @tmpItTransactionByItemId TABLE(item_id INT, it_transaction INT, sod_id INT,ct_transaction INT)




				/********************************************************************************************************/
				-- Obtenemos datos de la sucursal
				SELECT 	@bra_processingDate		= tb.bra_processingDate,
						@intStor_id_b			= tb.stor_id,
						@BranchCurrencyId		= tb.curr_id,
						--@stor_id				= tb.stor_id,
						@bra_checkSerialNumber	= isnull(tb.bra_checkSerialNumber,'false'),
						@branch_country_id		= tb.country_id,
						@branch_state_id		= tb.state_id
					FROM	dbo.tbBranch			tb			WITH (NOLOCK)
					WHERE	tb.comp_id				= @comp_id
					AND		tb.bra_id				= @bra_id
				/********************************************************************************************************/


				/********************************************************************************************************/
				-- obtenemos el depósito del artículo del pedido
				-- FORRO, arriba haces lo mismo !!!
				--SELECT	@stor_id			= tsod.stor_id
				--	FROM	tbSaleOrderDetail	tsod			WITH (NOLOCK)
				--	WHERE	tsod.comp_id	= @comp_id
				--	AND		tsod.bra_id     = @bra_id
				--	AND		tsod.soh_id		= @soh_id
				--	AND		tsod.sod_id		= @sod_id
				/********************************************************************************************************/



				--SELECT '@bra_checkSerialNumber', @bra_checkSerialNumber
				-- si @bra_checkSerialNumber = 'true' se deben generar la producción a partir de los datos cargados
				-- en la página actual, sino se deben cargar todos los artículos definidos en la tabla tbSaleOrderSerial4Production
				-- (verificar en que momento se graba esta tabla tbSaleOrderSerial4Production)
				DECLARE @sumEstado			INT = 0
				--IF @bra_checkSerialNumber = 'true'
					--BEGIN



					--	/********************************************************************************************************/
					--	/* GENERACIÓN DE TABLA TEMPORAL PARA VALIDACIÓN DE CANTIDAD CORRECTA DE ARTÍCULOS ASOCIADOS				*/
					--	/* SI LA CANTIDAD DE UN ART. ASOCIADO QUE COMPONE AL PADRE MENOS LA CANTIDAD TOMADA ES DIFERENTE DE		*/
					--	/* CERO GRABA 1 EN CASO CONTRARIO GRABA 0 EN CAMPO [estado]												*/
					--	SELECT	tsod.item_id,
					--			tic.item_id_1,
					--			CASE
					--				WHEN	tic.icomp_qty - SUM(case
					--												when isnull(tis.item_id,0) = 0 THEN 0
					--												ELSE 1
					--											END) <> 0 THEN 1
					--				ELSE 0
					--			END [estado]

					--	INTO	#tmpValidation

					--	FROM	tbSaleOrderDetail							tsod		WITH (NOLOCK)

					--			INNER JOIN tbItemComposition				tic			WITH (NOLOCK)
					--			ON  tic.comp_id			= tsod.comp_id
					--			AND tic.item_id			= tsod.item_id

					--			INNER JOIN tbItem							ti			WITH (NOLOCK)
					--			ON ti.comp_id = tsod.comp_id
					--			AND ti.item_id = tic.item_id_1
					--			AND ti.item_expser = 'true'

					--			INNER JOIN tbSaleOrderSerial4Production		tsosp		WITH (NOLOCK)
					--			ON	tsosp.comp_id		= tsod.comp_id
					--			AND tsosp.soh_id		= tsod.soh_id
					--			AND tsosp.sod_id		= tsod.sod_id	-- Es Identity, no molesta q n tenga Bra_Id
					--			AND tsosp.sosp_order	= @order
					--			-- MOD 09-2014AND tsosp.sosp_guid		= @guid

					--			LEFT JOIN tbItemSerials						tis			WITH (NOLOCK)
					--			ON	tis.comp_id			= tsosp.comp_id
					--			AND tis.is_id			= tsosp.is_id
					--			AND tis.item_id			= tic.item_id_1

					--	WHERE	tsod.comp_id	= @comp_id
					--	AND		tsod.bra_id		= @bra_id
					--	AND		tsod.soh_id		= @soh_id
					--	AND		tsod.sod_id		= @sod_id

					--	GROUP BY tsod.item_id, tic.item_id_1, tic.icomp_qty

					--	--SELECT * FROM #tmpValidation
					--	/******************************************************************************************************/


					--	SELECT @sumEstado = SUM([estado]) FROM  #tmpValidation
					--	DROP TABLE #tmpValidation

					--END
					--SET @sumEstado = ISNULL(@sumEstado,0)
				--SELECT @sumEstado [@sumEstado]








					/******************************************************************************************************/
					-- Si la sumatoria del campo [estado] de la temporal es = 0 significa que se tomaron todos los seriales
					-- asociados al artículo padre con las cantidades correctas o que no había artículos serializables
					IF (@sumEstado = 0 OR @bra_checkSerialNumber = 'false')
						BEGIN
							--validación correcta o no necesaria para el caso "@bra_checkSerialNumber = 'false'"



							/****************************************************************************************************/
							-- Se graba el artículo producido en la tabla tbSaleOrderSerialProduced
							--SELECT 'insert into tbSaleOrderSerialProduced', @comp_id,@soh_id,@sod_id,@order

							INSERT INTO tbSaleOrderSerialProduced
							(
									comp_id,
									soh_id,
									sod_id,
									sosp_order
							)
							VALUES
							(
									@comp_id,
									@soh_id,
									@sod_id,
									@order
							)

							/****************************************************************************************************/




							/****************************************************************************************************/
							-- recuperamos la descripción para el mensaje por la producción del artículo
							SELECT	@ret_ErrorDescription	= tut.utexts_desc
								FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
								WHERE	tut.lang_id		= @lang_id
								AND		tut.utexts_id	= 20
							--SELECT	@ret_ErrorDescription
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- se recupera un número desde el contador 11, es para generar el serial correspondiente para el
							-- producto a generar, al contador se le suma 980000000, para generar un serial con el formato 980000001, 980000002, etc
							--DECLARE @serial INT
							--SET	@serial				= 0
							DECLARE @strGlobalSerial AS VARCHAR(100) = ''
							--SET @strGlobalSerial	= ''

							--IF EXISTS (
							--			SELECT TOP 1  1
							--				FROM  tbSaleOrderSerial4Production_MasterSerial mse	WITH (NOLOCK)
							--				WHERE	mse.comp_id		= @comp_id	AND
							--						mse.bra_id		= @bra_id	AND
							--						mse.soh_id		= @soh_id	AND
							--						mse.sod_id		= @sod_id	AND
							--						mse.sod_order	= @order	AND
							--						ISNULL(mse.sod_serial,'')  <> ''
							--			)
							--	BEGIN
							--		SELECT @strGlobalSerial = mse.sod_serial
							--			FROM  tbSaleOrderSerial4Production_MasterSerial mse	WITH (NOLOCK)
							--			WHERE	mse.comp_id		= @comp_id	AND
							--					mse.bra_id		= @bra_id	AND
							--					mse.soh_id		= @soh_id	AND
							--					mse.sod_id		= @sod_id	AND
							--					mse.sod_order	= @order
							--		IF @strGlobalSerial <> ''
							--			BEGIN
							--				SET @ret_ErrorDescription	= @ret_ErrorDescription + ' ' + @strGlobalSerial
							--			END
							--	END

							--ELSE IF @itemToProduceIsSerializable = 'true' AND  @bititem_expserInBlankWhenProduced = 'False'
							--	BEGIN

							--		DECLARE @counter INT
							--		EXEC dbo.spCounters_getNextValue @comp_id, 0, 11, @counter_value = @counter OUTPUT
							--		--SELECT @counter

							--		SET @serial = 980000000 + @counter
							--		--SELECT 'nro de serial generado', @serial

							--		-- si no hay ningún error queda cargado el serial generado en la variable de retorno de mensajes de error
							--		SET @ret_ErrorDescription	= @ret_ErrorDescription + CONVERT(VARCHAR(100),@serial)
							--		SET @strGlobalSerial		= CONVERT(VARCHAR(100),@serial)
							--	END

							/****************************************************************************************************/




							/****************************************************************************************************/
							-- recuperamos el item_id del artículo a producir
							--SET @item_id = (SELECT	item_id
							--					FROM	tbsaleorderdetail	WITH (NOLOCK)
							--					WHERE	comp_id = @comp_id
							--					AND		bra_id	= @bra_id
							--					AND		soh_id	= @soh_id
							--					AND		sod_id	= @sod_id)
							--SELECT @item_id
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- recuperamos datos del proveedor
							SELECT	TOP 1
									@supplierCurrencyId		= ts.curr_id,
									@supp_id				= ts.supp_id
								FROM	dbo.tbSupplier			ts		WITH (NOLOCK)
								WHERE	ts.comp_id = @comp_id
								AND		ISNULL(ts.supp_isSupp4Production,'false') = 'true'
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- recuperar datos de la compañía
							SELECT	@ct_CompanyCurrency	= c.curr_id
								FROM	dbo.tbCompany			c		WITH (NOLOCK)
								WHERE	c.comp_id	= @comp_id
							/****************************************************************************************************/






							/****************************************************************************************************/
							-- recuperar datos para el insert en tbCommercialTransaction
							DECLARE --@lct_transaction_rv						INT,
									@ct_docNumber							INT,
									@ct_ACurrencyExchange					DECIMAL(19,4),
									@ct_Branch2CompanyCurrencyExchange		DECIMAL(19,4),
									--@lit_transaction_rv						INT,
									@decStorePreviuos						DECIMAL(19,6),
									@now									DATETIME


							-- obtener la fecha actual
							SET @now	= GETDATE()



							-- obtener el próximo número de ct_docNumber en @ct_docNumber
							EXEC dbo.spCounters_getNextValue @comp_id, 0, 12, @counter_value = @ct_docNumber OUTPUT


							-- tipo de cambio de la moneda del cliente a la moneda del artículo
							SELECT @ct_ACurrencyExchange				= dbo.fnGetExchange(@comp_id,1,@supplierCurrencyId,	@ct_CompanyCurrency,	0,0,'False')


							-- tipo de cambio de la moneda de la sucursal a la moneda de la compañia
							SELECT @ct_Branch2CompanyCurrencyExchange	= dbo.fnGetExchange(@comp_id,1,@BranchCurrencyId,	@ct_CompanyCurrency,	0,0,'False')
							/****************************************************************************************************/





							/****************************************************************************************************/
							-- se genera un nuevo comprobante para toda la transacción si no existía uno anterior para el mismo soh_id

							IF EXISTS (SELECT TOP 1 	1
											FROM tbCommercialTransactions tct		WITH (NOLOCK)
											WHERE	tct.comp_id			= @comp_id
											AND		tct.ct_soh_bra_id	= @bra_id
											AND		tct.ct_soh_id		= @soh_id)
								BEGIN

									SELECT	@ct_transaction_rv	= tct.ct_transaction
										FROM	tbCommercialTransactions	tct		WITH (NOLOCK)
										WHERE	tct.comp_id			= @comp_id
										AND		tct.ct_soh_bra_id	= @bra_id
										AND		tct.ct_soh_id		= @soh_id

								END

							ELSE

								BEGIN

									EXEC spCommercialTransactions_InsertPurchaseData
											@comp_id,
											@bra_id,
											0,
											'',
											@ct_docNumber,
											@bra_processingDate,
											@bra_processingDate,
											@bra_processingDate,
											@supp_id,
											NULL,
											NULL,
											NULL,
											@user_id,
											0,									--@ct_subtotal = null,
											0,									--@ct_total = null,
											0,									--@ct_discount = null,
											0,									--@ct_adjust = null,
											0,									--@ct_taxes = null,
											@BranchCurrencyId,					--@curr_id_transaction = null, --moneda de la sucursal
											NULL,								--@hacc_transaction = null,
											NULL,								--@sm_id = null,
											NULL,								--@disc_id = null,
											0,									--@ct_ATotal = null,
											0,									--@ct_ABalance = null,
											@supplierCurrencyId,				--@ct_ACurrency = null, --moneda del proveedor
											@ct_ACurrencyExchange,				--@ct_ACurrencyExchange = null,
											NULL,								--@df_id = null,
											NULL,								--@dl_id = null,
											NULL,								--@st_id = null,
											145,								--@sd_id = null,
											NULL,								--@puco_id = null,
											@ct_CompanyCurrency,				--@ct_CompanyCurrency = null,
											@ct_Branch2CompanyCurrencyExchange, --@ct_Branch2CompanyCurrencyExchange = null,
											NULL,								--@ct_Pending = null,
											@branch_country_id,					--@country_id = null,
											@branch_state_id,					--@state_id = null,
											'false',							--@ct_isAvailableForImport = null,
											NULL,								--@ct_CAI = null,
											NULL,								--@ct_CAIDate = null,
											'',									--@observation1 = null,
											'',									--@observation2 = null,
											'',									--@observation3 = null,
											'',									--@observation4 = null,
											@supplierCurrencyId,				--@curr_id4Exchange = null,
											@ct_ACurrencyExchange,				--@ct_curr_IdExchange = null,

											@return_value			= @ct_transaction_rv		OUTPUT,
											@ret_ErrorCode			= @ret_ErrorCode_rv			OUTPUT,
											@ret_ErrorDescription	= @ret_ErrorDescription_rv	OUTPUT

									--SET @ret_ErrorCode_rv = -2
									IF @ret_ErrorCode_rv <> 0
									BEGIN
										SET @ret_ErrorCode			= @ret_ErrorCode_rv - 100
										SET @ret_ErrorDescription	= @ret_ErrorDescription_rv
										SELECT 1/0
									END



									-- se actualiza la transacción generada con el soh_id correspondiente

									UPDATE	tbCommercialTransactions
										SET		ct_soh_bra_id	= @bra_id,
												ct_soh_id		= @soh_id
										WHERE	comp_id			= @comp_id
										AND		bra_id			= @bra_id
										AND		ct_transaction	= @ct_transaction_rv

								END

							--SELECT '@ct_transaction_rv', @ct_transaction_rv
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- se actualiza el stock, se carga en la trasacción y se genera el serial del artículo producido

							-- actualizar el depósito con el artículo a generar, si existe no lo modifica y si
							-- no existe lo genera con stock en 0 (cero)
							EXEC spItemStorage_insertData @comp_id, @item_id, @stor_id, 0



							-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
							SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
								FROM	tbItemStorage tis		WITH (NOLOCK)
								WHERE	tis.comp_id = @comp_id
								AND		tis.stor_id = @stor_id
								AND		tis.item_id = @item_id



							SET @it_order = 1



							INSERT INTO tbItemTransactions
							(
								comp_id,				bra_id,						ct_transaction,
								item_id,				it_qty,						it_priceWithOutOthers,
								it_price,				curr_id,					it_exchangeToBranchCurrency,
								it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
								it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
								it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
								stor_id,				it_storePrevious,			prli_id,
								byor_id,				it_isProduction,			it_isAssociation,
								it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
								it_order,				so_id,						it_guarantee,
								it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
								it_CreditIntPlus,		puco_id,					it_poh_bra_id,
								it_poh_id,				it_soh_id,					it_sod_id,
								rmah_id,				rmad_id,					it_qty_rma,
								it_tis_id_aux
							)
							VALUES
							(
				 				@comp_id,				@bra_id,					@ct_transaction_rv,
								@item_id,				@decQTY,					0,
								0,						@supplierCurrencyId,		@supplierCurrencyId,
								0,						0,							0,
								0,						0,							0,
								0,						@supplierCurrencyId,		1,
								@stor_id,				isnull(@decStorePreviuos,0),NULL,
								NULL,					'False',					'False',
								NULL,					@now,						NULL,
								@it_order,				NULL,						0,
								0,						0,							0,
								0,						NULL,						NULL,
								NULL, 					@soh_id, 					@sod_id,
								NULL,					NULL,						NULL,
								NULL
							)

							SET @it_transaction_rv = @@IDENTITY



							-- se incorpora el artículo al depósito
							UPDATE	tbItemStorage
								SET		itst_cant	= itst_cant + @decqTY,
										itst_cd		= @now
								WHERE	comp_id		= @comp_id
								AND		stor_id		= @stor_id
								AND		item_id		= @item_id



							--IF @itemToProduceIsSerializable = 'true'
								--BEGIN
								--	DECLARE @is_id INT




								--	-- se carga el artículo producido en tbItemSerial con el serial recién generado
								--	INSERT INTO tbItemSerials
								--	(
								--		comp_id,
								--		-- is_id -- this column value is auto-generated,
								--		bra_id,
								--		ct_transaction,
								--		it_transaction,
								--		item_id,
								--		is_serial,
								--		is_cd,
								--		is_available,
								--		stor_id,
								--		is_guid,
								--		is_IsOwnGeneration,
								--		is_checked,
								--		is_printed
								--	)
								--	VALUES
								--	(
								--		@comp_id,
								--		@bra_id,
								--		@ct_transaction_rv,
								--		@it_transaction_rv,
								--		@item_id,
								--		CASE
								--			WHEN @bititem_expserInBlankWhenProduced = 'True' AND @strGlobalSerial = '' THEN ''
								--			ELSE @strGlobalSerial  --convert(varchar,@serial)
								--		END,
								--		@now,
								--		CASE
								--			WHEN @bititem_expserInBlankWhenProduced = 'True' AND @strGlobalSerial = '' THEN 'False'
								--			ELSE 'True'
								--		END,
								--		@stor_id,
								--		@guid,
								--		'true',
								--		'false',
								--		'false'
								--	)

								--	SET @is_id = @@IDENTITY

								--	-- si no hay ningún tipo de error, se retorna el is_id generado en el return_value
								--	SET @return_value = @is_id

								--END

							--ELSE

							--	BEGIN

							--		SET @return_value = 999999999

							--	END


							-- Se relacionan los numeros de serie de las partes a los numeros de serie generados.-
							--IF @itemToProduceIsSerializable = 'true'
							--	BEGIN

							--		IF @bra_checkSerialNumber = 'true'
							--			BEGIN

							--				-- se cargan las relaciones del artículo producido con los artículos que lo componen
							--				-- si se tomaron los seriales en la página
							--				INSERT INTO tbItemSerials4Production
							--				(
							--					comp_id,
							--					is_idProduced,
							--					is_idPart,
							--					-- is4p_id -- this column value is auto-generated,
							--					soh_id,
							--					sod_id,
							--					is4p_order,
							--					[user_id],
							--					bra_id
							--				)
							--				SELECT	@comp_id,
							--						@is_id,
							--						tsosp.is_id,
							--						@soh_id,
							--						@sod_id,
							--						@order,
							--						@user_id,
							--						@bra_id
							--					FROM	tbSaleOrderSerial4Production tsosp
							--					WHERE	tsosp.comp_id		= @comp_id
							--					-- MOS 09.2014 AND		tsosp.sosp_guid		= @guid
							--					AND		tsosp.soh_id		= @soh_id
							--					AND		tsosp.sod_id		= @sod_id
							--					AND		tsosp.sosp_order	= @order

							--			END
							--		ELSE
							--			BEGIN

							--				-- se cargan las relaciones del artículo producido con todos artículos que componen
							--				-- el lote completo de lo que serializó en el pedido
							--				INSERT INTO tbItemSerials4Production
							--				(
							--					comp_id,
							--					is_idProduced,
							--					is_idPart,
							--					-- is4p_id -- this column value is auto-generated,
							--					soh_id,
							--					sod_id,
							--					is4p_order,
							--					[user_id],
							--					bra_id
							--				)
							--				SELECT	@comp_id,
							--						@is_id,
							--						tis.is_id,
							--						@soh_id,
							--						@sod_id,
							--						@order,
							--						@user_id,
							--						@bra_id

							--				FROM	tbSaleOrderDetail					tsod		WITH (NOLOCK)

							--						INNER JOIN tbItemComposition		tic			WITH (NOLOCK)
							--						ON	tic.comp_id		= tsod.comp_id
							--						AND tic.item_id		= tsod.item_id
							--						INNER JOIN tbSaleOrderSerials		tsos		WITH (NOLOCK)
							--						ON	tsos.comp_id	= tsod.comp_id
							--						AND tsos.bra_id		= tsod.bra_id
							--						AND tsos.soh_id		= tsod.soh_id
							--						INNER JOIN tbItemSerials			tis			WITH (NOLOCK)
							--						ON	tis.is_id		= tsos.is_id
							--						AND tis.comp_id		= tsod.comp_id
							--						AND tis.item_id		= tic.item_id_1

							--				WHERE	tsod.comp_id		= @comp_id
							--				AND		tsod.bra_id			= @bra_id
							--				AND		tsod.soh_id			= @soh_id
							--				AND		tsod.sod_id			= @sod_id
							--				--AND		tis.is_available	= 'false'			MOS, si esta en tbSaleOrderSerials debe ir igual ya que siempre deberia estar en false en ese estado.-

							--				ORDER BY tis.item_id

							--			END

							--END
							/****************************************************************************************************/




							/****************************************************************************************************/
							--este query no estaba en el sp original, el anterior a la modificación
							--			SELECT	DISTINCT tic.item_id_1, tic.icomp_qty
							--
							--			FROM	tbSaleOrderSerial4Production		tsosp
							--					INNER JOIN tbSaleOrderDetail		tsod
							--					ON	tsod.comp_id	= tsosp.comp_id
							--					AND tsod.soh_id		= @soh_id
							--					AND tsod.sod_id		= @sod_id
							--					INNER JOIN tbItemComposition tic
							--					ON	tic.comp_id		= tsod.comp_id
							--					AND tic.item_id		= tsod.item_id
							--
							--			WHERE	tsosp.comp_id	= @comp_id
							--			AND		tsosp.sosp_guid = @guid
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- cursor para recuperar los artículos que componen el artículo a producir, y actualizar los stocks
							-- correspondientes

							DECLARE @litem_id_1			INT,
									@licomp_qty			DECIMAL(19,6)


							DECLARE cursor_itemsComposition CURSOR LOCAL FAST_FORWARD FOR
															SELECT	DISTINCT	tic.item_id_1,
																				tic.icomp_qty * @decQTY
																FROM	tbItemComposition					tic	WITH (NOLOCK)
																WHERE	tic.comp_id	= @comp_id
																AND		tic.item_id = @item_id



							OPEN cursor_itemsComposition

							FETCH NEXT FROM cursor_itemsComposition INTO @litem_id_1, @licomp_qty

							WHILE @@FETCH_STATUS = 0
							BEGIN

								-- se actualiza el stock de los artículos que componen el artículo generado

								-- actualizar el depósito con el artículo a generar, si existe no lo modifica y si
								-- no existe lo genera con stock en 0 (cero)
								EXEC spItemStorage_insertData @comp_id, @litem_id_1, @stor_id, 0



								-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
								SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
									FROM	tbItemStorage tis		-- NOOO  		WITH (NOLOCK)
									WHERE	tis.comp_id = @comp_id
									AND		tis.stor_id = @stor_id
									AND		tis.item_id = @litem_id_1



								SET @it_order = @it_order + 1


		--
		-- ATENCION, aca se deberia buscar si ya hay un itemtrans para ese itemId asi no se generan cientos de registros
		-- al pedo cuando se produce un lote de eq	uipos.
		--

								INSERT INTO tbItemTransactions
								(
									comp_id,				bra_id,						ct_transaction,
									item_id,				it_qty,						it_priceWithOutOthers,
									it_price,				curr_id,					it_exchangeToBranchCurrency,
									it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
									it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
									it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
									stor_id,				it_storePrevious,			prli_id,
									byor_id,				it_isProduction,			it_isAssociation,
									it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
									it_order,				so_id,						it_guarantee,
									it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
									it_CreditIntPlus,		puco_id,					it_poh_bra_id,
									it_poh_id,				it_soh_id,					it_sod_id,
									rmah_id,				rmad_id,					it_qty_rma,
									it_tis_id_aux
								)
								VALUES
								(
					 				@comp_id,				@bra_id,					@ct_transaction_rv,
									@litem_id_1,			@licomp_qty * -1,			0,
									0,						@supplierCurrencyId,		@supplierCurrencyId,
									0,						0,							0,
									0,						0,							0,
									0,						@supplierCurrencyId,		1,
									@stor_id,				isnull(@decStorePreviuos,0),NULL,
									NULL,					'False',					'False',
									NULL,					@now,						NULL,
									@it_order,				NULL,						0,
									0,						0,							0,
									0,						NULL,						NULL,
									NULL, 					@soh_id, 					@sod_id,
									NULL,					NULL,						NULL,
									NULL
								)


								-- MOS 08-2024:como el FORRO DE MIERDA hizo por separado esto, lo uso abajo
								INSERT INTO @tmpItTransactionByItemId(	item_id,
																		it_transaction,
																		sod_id,
																		ct_transaction)
									VALUES(@litem_id_1,@@IDENTITY,@sod_id,@ct_transaction_rv)

								-- se incorpora el artículo al depósito
								UPDATE	tbItemStorage
								SET		itst_cant	= itst_cant - @licomp_qty,
										itst_cd		= @now
								WHERE	comp_id		= @comp_id
								AND		stor_id		= @stor_id
								AND		item_id		= @litem_id_1




								FETCH NEXT FROM cursor_itemsComposition INTO @litem_id_1, @licomp_qty

							END

							CLOSE cursor_itemsComposition
							DEALLOCATE cursor_itemsComposition
							/****************************************************************************************************/




							/****************************************************************************************************/
							-- se envía a la history el pedido original y se borra el pedido original si ya se produjeron
							-- todos los artículos


							-- se recuperan todos los artículos a producir
							SELECT	tsod.comp_id,  tsod.soh_id,  tsod.sod_id,  CONVERT(INT,tsod.sod_qty) [sod_qty]
								INTO	#tmpItemsToProduce
								FROM	tbSaleOrderDetail tsod		WITH (NOLOCK)
								WHERE	tsod.comp_id	= @comp_id
								AND		tsod.bra_id		= @bra_id
								AND		tsod.soh_id		= @soh_id


							-- se recuperan todos los artículos producidos
							SELECT	tsosp.comp_id, tsosp.soh_id, tsosp.sod_id, COUNT(*) [sod_qty]
								INTO	#tmpItemsProduced
								FROM	tbSaleOrderSerialProduced tsosp		WITH (NOLOCK)
								WHERE	tsosp.comp_id	= @comp_id
								AND		tsosp.soh_id	= @soh_id
								GROUP BY tsosp.comp_id, tsosp.soh_id, tsosp.sod_id
							--SELECT '#tmpItemsProduced', * FROM #tmpItemsProduced


							-- se obtiene la cantidad de artículos a producir
							DECLARE @ItemsToProduce			INT
							SELECT	@ItemsToProduce = COUNT(*)
							FROM	#tmpItemsToProduce titp


							-- se obtiene la cantidad de items producidos en su totalidad
							DECLARE @ItemsProduced			INT

							SELECT	@ItemsProduced	= COUNT(*)
								FROM	#tmpItemsToProduce titp
										INNER JOIN #tmpItemsProduced tip
								ON		titp.comp_id	= tip.comp_id
								AND		titp.soh_id		= tip.soh_id
								AND		titp.sod_id		= tip.sod_id
								AND		titp.sod_qty	= tip.sod_qty

							DROP TABLE #tmpItemsToProduce
							DROP TABLE #tmpItemsProduced
							--SELECT @ItemsToProduce,  @ItemsProduced






							/****************************************************************************************************/
							--actualización de costos del artículo producido con la sumatoria de los costos de los artículos que
							--lo componen desde la lista de costos a la lista de costos definidas en el documento de producción
							------------------------------------------------------------------------------------------------------

							--validamos que en el documento del pedido estén definidas las listas de costos de donde tomar los
							--costos (origen) y donde grabar ese costo (destino)
							IF EXISTS	(
										SELECT TOP 1 	1
											FROM	tbSaleOrderHeader					tsoh		WITH (NOLOCK)

													INNER JOIN 	tbDocumentsFile			tdf			WITH (NOLOCK)
													ON	tdf.comp_id					= tsoh.comp_id
													AND tdf.df_id					= tsoh.df_id
													AND NOT tdf.coslis_id_origin	IS NULL
													AND NOT tdf.coslis_id_destiny	IS NULL

											WHERE	tsoh.comp_id	= @comp_id	AND
													tsoh.bra_id		= @bra_id	AND
													tsoh.soh_id		= @soh_id
										)
							BEGIN

								DECLARE @costlis_id_origin		INT,
										@costlis_id_destiny		INT,
										@curr_id				INT


								-- recuperamos las listas de costos de origen y destino
								SELECT	@costlis_id_origin		= tdf.coslis_id_origin,
										@costlis_id_destiny		= tdf.coslis_id_destiny
									FROM	tbSaleOrderHeader					tsoh			WITH (NOLOCK)
									INNER JOIN 	tbDocumentsFile			tdf				WITH (NOLOCK)
										ON	tdf.comp_id					= tsoh.comp_id
										AND tdf.df_id					= tsoh.df_id
										AND NOT tdf.coslis_id_origin	IS NULL
										AND NOT tdf.coslis_id_destiny	IS NULL
									WHERE	tsoh.comp_id	= @comp_id	AND
											tsoh.bra_id		= @bra_id	AND
											tsoh.soh_id		= @soh_id




								-- si no existe el artículo generado en la lista de costos destino, se lo incluye
								IF NOT EXISTS	(
												SELECT TOP 1 	1
													FROM	tbItemCostList		ticl		WITH (NOLOCK)
													WHERE	ticl.comp_id	= @comp_id
													AND		ticl.coslis_id	= @costlis_id_destiny
													AND		ticl.item_id	= @item_id
												)
								BEGIN

									-- recuperamos la moneda del artículo a generar
									SELECT	@curr_id	= ti.curr_id
										FROM	tbItem						ti		WITH (NOLOCK)
										WHERE	ti.comp_id	= @comp_id
										AND		ti.item_id	= @item_id



									INSERT INTO tbItemCostList
									(
										comp_id,
										coslis_id,
										item_id,
										coslis_price,
										coslis_price_aw,
										curr_id,
										coslis_cd,
										coslis_price_Original,
										coslis_price_Disc1,
										coslis_price_Disc2,
										coslis_price_Disc3,
										coslis_price_Disc4
									)
									VALUES
									(
										@comp_id,
										@costlis_id_destiny,
										@item_id,
										0,
										0,
										@curr_id,
										GETDATE(),
										0,
										0,
										0,
										0,
										0
									)

								END




								-- actualizamos los costos del artículo generado en base a la suma de los costos
								-- de los artículos que lo componen

								DECLARE @coslis_price		DECIMAL(19,5),
										@coslis_price_aw	DECIMAL(19,5)


								SELECT 	@coslis_price		= SUM(tic.icomp_qty * dbo.fnGetExchange2(	@comp_id,
																										ticl2.coslis_price,
																										ticl2.curr_id, ticl.curr_id,
																										ticl2.curr_id, ticl.curr_id,
																										0, 'false')),
										@coslis_price_aw	= SUM(tic.icomp_qty * dbo.fnGetExchange2(	@comp_id,
																										ticl2.coslis_price_aw,
																										ticl2.curr_id, ticl.curr_id,
																										ticl2.curr_id, ticl.curr_id,
																										0, 'false'))

								FROM	tbItemCostList						ticl		WITH (NOLOCK)

								INNER JOIN tbItemComposition	 	tic			WITH (NOLOCK)
									ON	tic.comp_id		= ticl.comp_id
									AND tic.item_id		= ticl.item_id

								INNER JOIN tbItemCostList			ticl2		WITH (NOLOCK)
									ON	ticl2.comp_id	= ticl.comp_id
									AND ticl2.coslis_id = @costlis_id_origin
									AND ticl2.item_id	= tic.item_id_1

								WHERE	ticl.comp_id		= @comp_id
								AND		ticl.coslis_id		= @costlis_id_destiny
								AND		ticl.item_id		= @item_id




								UPDATE	tbItemCostList

								SET		coslis_price		= IsNull(@coslis_price,0),
										coslis_price_aw		= IsNull(@coslis_price_aw,0),
										coslis_cd			= GETDATE()

								WHERE	comp_id		= @comp_id
								AND		coslis_id	= @costlis_id_destiny
								AND		item_id		= @item_id


							END
							/****************************************************************************************************/





								/*****************************************************************************************************************************/
								-- FALTA:
								-- Aqui se debe generar los tbImportData correspondientes a cada tbItemTransaction de la transaccion de produccion
								-- Lo que hay que hacer es tomar todos los numeros de serie y descontar uno del tbimportdata correspondiente
								-- (OJO, agrupados por is_id asi
								-- no se duplican cuando la serializacion es del total de los numeros de serie por cada item producido).
								-- Para los items que no tienen expser en true se debe descontar de los despachos mas viejos segun el ejemplo.
								-- (o sea de los despachos que tengan impData_ActualQty > 0)
								-- Por cada despacho descontado hay que generar un impData_id para la it_transaction del item (que es una por cada
								-- item producido) con la concatenacion de los numeros
								-- de despacho de cada una de sus partes (en si con impData_Custom_local y el resto que son varchar(200)
								--
								-- Hay un tema cuando se toman los numeros de serie globales para todos los items producidos que es que puede haber
								-- mas de un despacho por cada item por lo que la concatenacion
								-- podria ser gigante y no entrar en los 200 caracteres del item producido.  la actitud a tomar en este caso es la siguiente:
								--		ir marcando como ya usadop en una temporal los numeros de serie de cada parte y tomar solo los de un serial
								--		correspondiente (o los que la qty de itemComposition diga!!)
								--      de esta manera solo habra un despacho por componente del equipo final.
								-- Como se vera el equipo final tendra un despacho DIFERENTE por cada componente los que tendran que ir conatenados
								-- y quedar grabados en la tbImportdata del it_transaction producido.
								--	Por esto se debe verificar cuando, item por item del ct_transaction producido, en un cursor, al grabar su importdata,
								--	que al concatenar, no este ya ese numero de despacho ya que podrian haber varias partes con el mismo.  hacer este
								--	control para todos los campos varchar(200)
								-- Como ejemplo de los despachos sin numero de serie tenes la linea 515 del sp : [spItemTransactionImportData_InsertData]
								-- y para los que si tienen serial la linea 234, aunque ese es el mas facil porque buscas el impdata_id del it_transaction
								-- del is_id en la tabla tbItemSerials
								/*****************************************************************************************************************************/
								/*****************************************************************************************************************************/
								--SELECT 'ok'

								DECLARE @llitem_id_1					INT,
										@llicomp_qty					DECIMAL(18,5),
										@llitem_expser					BIT,
										@llimpData_id					INT,

										@llimpData_Custom_local			VARCHAR(200),
										@llimpData_Custom_local_all		VARCHAR(200),

										@llimpData_Number_local			VARCHAR(200),
										@llimpData_Number_local_all		VARCHAR(200),

										@llimpData_Origin				VARCHAR(200),
										@llimpData_Origin_all			VARCHAR(200),

										@llimpData_From					VARCHAR(200),
										@llimpData_From_all				VARCHAR(200),

										@llimpdata_Stamp				VARCHAR(200),
										@llimpdata_Stamp_all			VARCHAR(200)



								SELECT	@llimpData_Custom_local			= '',
										@llimpData_Custom_local_all		= '',
										@llimpData_Number_local			= '',
										@llimpData_Number_local_all		= '',
										@llimpData_Origin				= '',
										@llimpData_Origin_all			= '',
										@llimpData_From					= '',
										@llimpData_From_all				= '',
										@llimpdata_Stamp				= '',
										@llimpdata_Stamp_all			= ''



								--obtenemos los artículos que componen el artículo producido
								DECLARE cursor_icomposition CURSOR LOCAL FAST_FORWARD FOR
									SELECT	tic.item_id_1,
											tic.icomp_qty,
											ti.item_expser,
											tsod.sod_id
										FROM	tbSaleOrderDetail				tsod		WITH (NOLOCK)
										INNER JOIN tbItemComposition			tic			WITH (NOLOCK)
											ON	tic.comp_id	= tsod.comp_id	AND
												tic.item_id	= tsod.item_id
										INNER JOIN tbItem						ti			WITH (NOLOCK)
											ON	ti.comp_id	= tsod.comp_id	AND
												ti.item_id	= tic.item_id_1
										WHERE	tsod.comp_id	= @comp_id
										AND		tsod.soh_id		= @soh_id
										AND		tsod.sod_id		= @sod_id



								DECLARE @curSod_Id AS INT

								OPEN cursor_icomposition

								FETCH NEXT FROM cursor_icomposition INTO
																@llitem_id_1,
																@llicomp_qty,
																@llitem_expser,
																@curSod_Id


								--recorremos la composición del artículo producido
								WHILE @@FETCH_STATUS = 0
								BEGIN


										-- -----------------------------------------------------------
										-- aca grabamos la composicion de este item al producirlo
										-- por si se cambia en el medio de un lote
										-- item_id es el nuevo item producido
										-- item_id_1 son las partes
										-- -----------------------------------------------------------
										INSERT INTO tbItemtransactionsProductionParts
										(
											comp_id,
											-- itp_id -- this column value is auto-generated,
											bra_id,
											ct_transaction,
											it_transaction,
											item_id_produced,
											item_id_partOf,
											item_id_partOf_qty,
											itp_loteNumber,
											itp_note, soh_id, sod_id, itp_order
										)
										SELECT 	@comp_id,
												@bra_id,
												@ct_transaction_rv,
												@it_transaction_rv,
												tic.item_id,
												tic.item_id_1,
												tic.icomp_qty * @decQTY,
												@order,
												'Nota',
												@soh_id,
												@sod_id,
												@order
											FROM tbItemComposition tic		WITH (NOLOCK)
											WHERE	tic.comp_id = @comp_id AND
													tic.item_id = @item_id

										-- -----------------------------------------------------------


										--IF @llitem_expser = 'true'
											BEGIN
												-- proceso para los artículos que componene el producido que NO son serializados


												--loop de proceso por la cantidad de cada artículo que compone el producido
												WHILE @llicomp_qty > 0
												BEGIN


													--obtenemos el importData que primero de fecha más vieja que tenga cantidad disponible del artículo a procesar
													SELECT	TOP 1 @llimpData_id = tid.impData_id

														FROM	tbImportData tid						WITH (NOLOCK)
														INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
															ON		tct.comp_id			= tid.comp_id
																AND tct.bra_id			= tid.bra_id
																AND tct.ct_transaction	= tid.ct_transaction

														WHERE	tid.comp_id = @comp_id
														AND 	tid.item_id = @llitem_id_1
														AND		tid.impData_ActualQty > 0
														ORDER BY tid.impdata_Priority,tct.ct_date ASC


													--obtenemos el número de despacho
													SELECT	@llimpData_Number_local	= ltrim(rtrim(tid.impData_Number_local)),
															@llimpData_Custom_local	= ltrim(rtrim(tid.impData_Custom_local)),
															@llimpData_Origin		= ltrim(rtrim(tid.impData_Origin)),
															@llimpData_From			= ltrim(rtrim(tid.impData_From)),
															@llimpdata_Stamp		= ltrim(rtrim(tid.impdata_Stamp))
														FROM	tbImportData				tid		WITH (NOLOCK)
														WHERE	tid.comp_id		= @comp_id
														AND		tid.impData_id	= @llimpData_id


														--si los números no existen en cada acumulado se almacenan en el mismo
														IF CHARINDEX(@llimpData_Number_local,@llimpData_Number_local_all) = 0 AND @llimpData_Number_local <> ''
															SET @llimpData_Number_local_all = @llimpData_Number_local_all + @llimpData_Number_local + '*'

														IF CHARINDEX(@llimpData_Custom_local,@llimpData_Custom_local_all) = 0 AND @llimpData_Custom_local <> ''
															SET @llimpData_Custom_local_all = @llimpData_Custom_local_all + @llimpData_Custom_local + '*'

														IF CHARINDEX(@llimpData_Origin,@llimpData_Origin_all) = 0 AND @llimpData_Origin <> ''
															SET @llimpData_Origin_all = @llimpData_Origin_all + @llimpData_Origin + '*'

														IF CHARINDEX(@llimpData_From,@llimpData_From_all) = 0 AND @llimpData_From <> ''
															SET @llimpData_From_all = @llimpData_From_all + @llimpData_From + '*'

														IF CHARINDEX(@llimpdata_Stamp,@llimpdata_Stamp_all) = 0 AND @llimpdata_Stamp <> ''
															SET @llimpdata_Stamp_all = @llimpdata_Stamp_all + @llimpdata_Stamp + '*'


													--se resta 1 de la cantidad disponible del imprtData obtenido
													UPDATE	tbImportData
														SET		impData_ActualQty	= impData_ActualQty - @decQTY -- 1
														WHERE	comp_id		= @comp_id
														AND		impData_id	= @llimpData_id


													-- MOS 08-2024: Guardo la transacciond e Importacion que en el ORIGINAL el FORRO de mierda NO la habia puesto.
													INSERT INTO tbItemTransactionImportData
													(
														comp_id,
														it_transaction,
														bra_id,
														ct_transaction,
														impData_id,
														itid_qty,
														impData_Custom_local,
														impData_Number_local,
														impData_Number_localPreAssignedByFiscal,
														impData_Custom_localPreAssignedByFiscal
													)
													SELECT TOP 1 @comp_id,tmp.it_transaction,@bra_id,tmp.ct_transaction, @llimpData_id,@decQTY * tic.icomp_qty,'','','',''
														FROM @tmpItTransactionByItemId tmp
														INNER JOIN tbItemComposition AS tic WITH (NOLOCK)
															ON	tic.comp_id		= @comp_id AND
																tic.item_id		= @item_id AND
																tic.item_id_1	= tmp.item_id
														WHERE	tmp.item_id = @llitem_id_1 AND
																tmp.sod_id	= @curSod_Id



													SET @llicomp_qty = @llicomp_qty - @decQTY -- 1

												END
											END


									FETCH NEXT FROM cursor_icomposition INTO	@llitem_id_1,
																				@llicomp_qty,
																				@llitem_expser,
																				@curSod_Id
								END

								CLOSE cursor_icomposition
								DEALLOCATE cursor_icomposition





								-- MOS 07-2013.  Genera un importdata x cada it_transaction
								-- Mas adelante para ascelerar esto deberia producir un solo it_transaction
								-- por cada sod_id y un solo importdata.
								INSERT INTO tbImportData
									(
									comp_id,
									item_id,
									-- impData_id -- this column value is auto-generated,
									impData_InitialQty,
									impData_ActualQty,
									ct_transaction,
									it_transaction,
									bra_id,
									impData_Custom_local,
									impData_Number_local,
									/* impData_ExpirationDate,  --por default getdate() */
									impData_Origin,
									impData_From,
									impdata_Stamp
									)
								VALUES(
										@comp_id,
										@item_id,
										1 * @decQTY,
										1 * @decQTY,
										@ct_transaction_rv,
										@it_transaction_rv,
										@bra_id,
										@llimpData_Custom_local_all,
										@llimpData_Number_local_all,
										/* impData_ExpirationDate	*/
										@llimpData_Origin_all,
										@llimpData_From_all,
										@llimpdata_Stamp_all
									  )




							-- ------------------------------------------------------------------------------------------
							-- si la cantidad de artículos a producir es la misma que la cantidad de artículos producidos
							-- entonces se envía el pedido al histórico y se elimina el pedido original
							-- ------------------------------------------------------------------------------------------
							IF @ItemsToProduce = @ItemsProduced OR 1 = 1
							BEGIN






								DELETE FROM tbSaleOrderTaxes
									WHERE	comp_id = @comp_id	AND
											bra_id	= @bra_id	AND
											soh_id	= @soh_id	AND
											sod_id = @sod_id

								DELETE FROM tbSaleOrderLoan
									WHERE	comp_id = @comp_id
									AND		bra_id	= @bra_id
									AND		soh_id	= @soh_id AND
											sod_id  = @sod_id

								DELETE FROM tbSaleOrderSerialProduced
									WHERE	comp_id = @comp_id
									AND		soh_id	= @soh_id AND
											sod_id	= @sod_id



								DELETE FROM tbSaleOrderDetail
									WHERE	comp_id = @comp_id
									AND		bra_id	= @bra_id
									AND		soh_id	= @soh_id AND
											sod_id	= @sod_id



								DELETE FROM tbSaleOrderSerial4Production
									WHERE	comp_id = @comp_id
									AND		bra_id	= @bra_id
									AND		soh_id	= @soh_id AND
											sod_id	= @sod_id

								DELETE FROM tbSaleOrderSerialInProduction
									WHERE	comp_id = @comp_id
									AND		bra_id	= @bra_id
									AND		soh_id	= @soh_id AND
											sod_id	= @sod_id

								DELETE FROM tbSaleOrderSerial4Production_MasterSerial
									WHERE	comp_id = @comp_id
									AND		bra_id	= @bra_id
									AND		soh_id	= @soh_id AND
											sod_id	= @sod_id



								-- si ya NO QUEDAN REGISTROS para procesar, borro todo el pedido
								IF (
										SELECT COUNT(*)
											FROM tbSaleOrderDetail AS tsoh	WITH (NOLOCK)
											WHERE	tsoh.comp_id	= @comp_id	AND
													tsoh.bra_id		= @bra_id	AND
													tsoh.soh_id		= @soh_id
								) < 1
									BEGIN

										EXEC spSaleOrderHistory_InsertFromSaleOrder
											@comp_id,
											@bra_id,
											@soh_id,
											100,
											NULL,
											@user_id,''

										DELETE FROM tbSaleOrderSerials
										WHERE	comp_id = @comp_id
										AND		bra_id	= @bra_id
										AND		soh_id	= @soh_id

										DELETE FROM tbSaleOrderExtendedDiscount
										WHERE	comp_id = @comp_id
										AND		bra_id	= @bra_id
										AND		soh_id	= @soh_id

										DELETE FROM tbSaleOrderHeader
										WHERE	comp_id = @comp_id
										AND		bra_id	= @bra_id
										AND		soh_id	= @soh_id

									END


							END
							-- ------------------------------------------------------------------------------------------




						END

					ELSE
						BEGIN

							--validación incorrecta, no están todos los artículos asociados tomados


							SET		@return_value			= -2
							SET		@ret_ErrorCode			= -2
							SELECT	@ret_ErrorDescription	= tut.utexts_desc
								FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
								WHERE	tut.lang_id		= @lang_id
								AND		tut.utexts_id	= 19

							--==
							--SELECT @sumEstado , @bra_checkSerialNumber
							--SELECT '*', @return_value,@ret_ErrorCode	,@ret_ErrorDescription
							--==
								COMMIT TRANSACTION T2
							--ROLLBACK TRANSACTION T2
							RETURN
						END

			END

		ELSE

			BEGIN

				-- no hay definido ningún proveedor para producción entonces retornamos el mensaje correspondiente
				SET		@return_value			= -3
				SET		@ret_ErrorCode			= -3
				SELECT	@ret_ErrorDescription	= tut.utexts_desc
					FROM	tbsysUniqueTexts tut	WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id
					AND		tut.utexts_id	= 17

			END


		COMMIT TRANSACTION T2


	END
	TRY BEGIN CATCH

		IF @ret_ErrorCode < -100
			BEGIN

				SET @return_value			= @ct_transaction_rv
				SET @ret_ErrorCode			= @ret_ErrorCode_rv
				SET @ret_ErrorDescription	= @ret_ErrorDescription_rv

			END
		ELSE
			BEGIN

				SET @return_value			= -1
				SET @ret_ErrorCode			= ERROR_NUMBER()
				SET @ret_ErrorDescription	= ERROR_MESSAGE()
			END

		ROLLBACK TRANSACTION T2

	END CATCH

END

GO







-- Produce un LOTE completo de Pedidos de Produccion SIN Numeros de serie
-- MOS 06-2013

CREATE PROCEDURE [dbo].[spSaleOrderSerialProduced_produceSOData]
(
    @comp_id					INT,
    @lang_id					INT,
    @bra_id						INT,
    @user_id					INT,
	@soh_id						INT,
	@guid						UNIQUEIDENTIFIER,
	@return_value				INT				OUTPUT,
	@ret_ErrorCode				INT 			OUTPUT,
	@ret_ErrorDescription		NVARCHAR(MAX)	OUTPUT
)
AS


BEGIN

	SET NOCOUNT ON


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id						INT,
			@lang_id						INT,
			@bra_id							INT,
			@user_id						INT,
			@soh_id							INT,
			@guid							UNIQUEIDENTIFIER,
			@return_value					INT,
			@ret_ErrorCode					INT,
			@ret_ErrorDescription			VARCHAR(200)
	select	@comp_id						=1,
			@lang_id						=2,
			@bra_id							=1,
			@user_id						=42,
			@soh_id							=33260,
			@guid							='9b98946d-9552-48c3-8de9-bc40783a2a25'
			--@return_value					INT,
			--@ret_ErrorCode				INT,
			--@ret_ErrorDescription			VARCHAR(200)
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsToProduce')	IS NULL DROP TABLE #tmpItemsToProduce
	*/
	-- --------------------------------------------------------------------------------



	DECLARE	@lreturn_value				INT,
			@lret_ErrorCode				INT,
			@lret_ErrorDescription		NVARCHAR(MAX)

	SET		@lreturn_value				= 0
	SET		@lret_ErrorCode				= 0
	SET		@lret_ErrorDescription		= ''


	BEGIN TRANSACTION T1
	BEGIN TRY


		SET @return_value			= 0
		SET @ret_ErrorCode			= 0
		SET @ret_ErrorDescription	= ''

		DECLARE	@bitItemsWithOutStock AS BIT
		DECLARE	@intItemsWithStock AS INT
		SET @bitItemsWithOutStock	= 'False'
		SET @intItemsWithStock		= 0



		/*********************************************************************************************************/
		-- verificamos si hay algún proveedor definido para producción
		IF EXISTS (	SELECT	TOP 1 1
	           			FROM	dbo.tbSupplier			ts			WITH (NOLOCK)
						WHERE	ts.comp_id = @comp_id
						AND		ISNULL(ts.supp_isSupp4Production,'false') = 'true' )
			BEGIN


				DECLARE
						@ct_transaction_rv			INT,
						@it_transaction_rv			INT,
						@ret_ErrorCode_rv			INT,
						@ret_ErrorDescription_rv	VARCHAR(200)



				-- -----------------------------------------------
				-- A T E N C I O N !!!!!!!!
				--
				-- sI SE MODIFICA O AGREGA AQUÍ ALGUNA COLUMNA
				-- SE DEBERÁ ACTUALIZAR EN **kl987
				-- -----------------------------------------------
				CREATE TABLE #tmpItemsToProduce
				(
					[unUsed1]		INT,
					[number]		INT				NULL,
					[IsProduced]	BIT				NULL,
					[item_desc]		VARCHAR(200)	NULL,
					[sod_serial]	VARCHAR(50)		NULL,
					[soh_id]		INT				NULL,
					[sod_id]		INT				NULL,
					[item_id]		INT				NULL,
					[stor_desc]		VARCHAR(100)	NULL,
					[prli_desc]		VARCHAR(100)	NULL,
					[sod_priority]	INT				NULL,
					[stor_id]		INT				NULL,
					[ID]			VARCHAR(100)	NULL
				)


				INSERT #tmpItemsToProduce
					(
						[unUsed1],
						[number],
						[IsProduced],
						[item_desc],
						[sod_serial],
						[soh_id],
						[sod_id],
						[item_id],
						[stor_desc],
						[prli_desc],
						[sod_priority],
						[stor_id],
						[ID]
					)
					EXEC spSaleOrderDetail_GetDataforProduction	@comp_id, @bra_id, @soh_id,''

--==
--SELECT * FROM #tmpItemsToProduce
--==

				DECLARE @bra_SaleOrderProduction_ChkStByStorGPhisical AS BIT
				SET @bra_SaleOrderProduction_ChkStByStorGPhisical = 'False'
				SELECT @bra_SaleOrderProduction_ChkStByStorGPhisical = isnull(tb.bra_SaleOrderProduction_ChkStByStorGPhisical,'False')
					FROM tbBranch tb		WITH (NOLOCK)
					WHERE	tb.comp_id	= @comp_id AND
							tb.bra_id	= @bra_id


				DECLARE		@number			INT,
							@sod_id			INT,
							@stor_id		INT,
							@intItemId		AS	INT,
							@intPriority	AS	INT,
							@bitIsProduced  AS  BIT


				DECLARE cursor_items CURSOR LOCAL FAST_FORWARD FOR
				SELECT	sod_id,
						item_id,
						stor_id,
						sod_priority,
						IsProduced,
						--CASE
						--    WHEN IsProduced = 0  THEN 'False'
						--    ELSE 'True'
						--END ,
					   [number]
					FROM #tmpItemsToProduce
					ORDER BY [number]

				OPEN cursor_items

				FETCH NEXT FROM	 cursor_items
					INTO @sod_id, @intItemId, @stor_id, @intPriority,@bitIsProduced,@number


				WHILE @@FETCH_STATUS = 0 AND @lreturn_value > -1 AND @bitItemsWithOutStock = 'False'
					BEGIN

						IF @bitIsProduced = 'False'
						BEGIN

							-- Se cambio a control por Stock FISICO!!, luego es CONFIGURABLE
							--IF dbo.fnGetAStock4MaxComposition(@comp_id, @stor_id, @intItemId, @intPriority) > 0
							IF CASE
							       WHEN @bra_SaleOrderProduction_ChkStByStorGPhisical = 'True'  AND
										dbo.fnGetStock4MaxComposition(@comp_id, @stor_id, @intItemId, @intPriority) >= 0	  THEN 1		-- MOS 04-2024 para q permita prod con solo 1 de stock
										--dbo.fnGetStock4MaxComposition(@comp_id, @stor_id, @intItemId, @intPriority) > 0	  THEN 1
							       WHEN @bra_SaleOrderProduction_ChkStByStorGPhisical = 'False' AND
										dbo.fnGetAStock4MaxComposition(@comp_id, @stor_id, @intItemId, @intPriority) >= 0  THEN 1			-- MOS 04-2024 para q permita prod con solo 1 de stock
										--dbo.fnGetAStock4MaxComposition(@comp_id, @stor_id, @intItemId, @intPriority) > 0  THEN 1
							       ELSE																						   0
							   END	 = 1



								BEGIN

--==
--SELECT @number,@sod_id
--==
									EXEC spSaleOrderSerialProduced_produceSerialData
										@comp_id,
										@lang_id,
										@bra_id,
										@user_id,
										@soh_id,
										@sod_id,
										@number,
										@guid,
										@return_value			= @lreturn_value			OUTPUT,
										@ret_ErrorCode			= @lret_ErrorCode			OUTPUT,
										@ret_ErrorDescription	= @lret_ErrorDescription	OUTPUT

									-- ----------------------------------------------
									-- Si hubo algun error cancela la produccion
									-- ----------------------------------------------
									IF @lreturn_value < 0
										BEGIN
											SET @return_value			= @lreturn_value
											SET @ret_ErrorCode			= @lret_ErrorCode
											SET @ret_ErrorDescription	= @lret_ErrorDescription
											ROLLBACK TRANSACTION T1
											RETURN
										END
									-- ----------------------------------------------

									SET @intItemsWithStock		= @intItemsWithStock + 1

								END

							ELSE
								BEGIN
									SET @bitItemsWithOutStock = 'True'
								END

						END

						FETCH NEXT FROM cursor_items
							INTO @sod_id, @intItemId, @stor_id,@intPriority,@bitIsProduced, @number

					END


				CLOSE cursor_items
				DEALLOCATE cursor_items

--==
--SELECT 1 / 0
--==
				-- Se ha producido el lote completo.
				SELECT	@ret_ErrorDescription	= tut.utexts_desc
					FROM	tbsysUniqueTexts tut			WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id
					AND		tut.utexts_id	= 21


				IF @bitItemsWithOutStock = 'True'
					BEGIN
						SET @ret_ErrorDescription = 'ATENCIÓN: La producción fué CANCELADA ya que no hay stock para producir el lote completo. Solo se podian producir ' + convert( NVARCHAR ,@intItemsWithStock) + ' artículos. ** NO '
													+ @ret_ErrorDescription

						ROLLBACK TRANSACTION T1
						RETURN
					END

			END

		ELSE

			BEGIN

				-- No se puede realizar la producción requerida ya que no hay definido ningún Proveedor para producción en el archivo de proveedores.
				SET		@return_value			= -3
				SET		@ret_ErrorCode			= -3
				SELECT	@ret_ErrorDescription	= tut.utexts_desc
					FROM	tbsysUniqueTexts tut			WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id
					AND		tut.utexts_id	= 17
				ROLLBACK TRANSACTION T1
				RETURN
			END

			COMMIT TRANSACTION T1

	END
	TRY BEGIN CATCH

		IF @ret_ErrorCode < 0
			BEGIN

				SET @return_value			= @lreturn_value
				SET @ret_ErrorCode			= @lret_ErrorCode
				SET @ret_ErrorDescription	= @lret_ErrorDescription

			END
		ELSE
			BEGIN

				SET @return_value			= -1
				SET @ret_ErrorCode			= ERROR_NUMBER()
				SET @ret_ErrorDescription	= ERROR_MESSAGE()

			END

		ROLLBACK TRANSACTION T1

	END CATCH

END

--==
--SELECT @return_value, @ret_ErrorCode, @ret_ErrorDescription
--==
GO



