CREATE PROCEDURE [dbo].[spSaleOrderSerialProduced_produceSOData2]
(
    @comp_id					INT,
    @lang_id					INT,
    @bra_id						INT,
    @user_id					INT,
	@soh_id						INT,
	@guid						UNIQUEIDENTIFIER,
	@return_value				INT				OUTPUT,
	@ret_ErrorCode				INT 			OUTPUT,
	@ret_ErrorDescription		VARCHAR(200)	OUTPUT
)
AS



BEGIN

	SET NOCOUNT ON

	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id						INT,
			@lang_id						INT,
			@bra_id							INT,
			@user_id						INT,
			@soh_id							INT,
			@guid							UNIQUEIDENTIFIER,
			@return_value					INT,
			@ret_ErrorCode					INT,
			@ret_ErrorDescription			VARCHAR(200)
	select	@comp_id						=1,
			@lang_id						=2,
			@bra_id							=1,
			@user_id						=1,
			@soh_id							=1683,
			@guid							='2B7195FA-7CE3-4F8A-8FCB-AA96B0B0B5AC'
			--@return_value					INT,
			--@ret_ErrorCode				INT,
			--@ret_ErrorDescription			VARCHAR(200)

	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsNeeded')		IS NULL DROP TABLE #tmpItemsNeeded
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsFree')		IS NULL DROP TABLE #tmpItemsFree
	IF NOT OBJECT_ID('tempdb.dbo.#tmpItemsToProduce')	IS NULL DROP TABLE #tmpItemsToProduce
	*/
	-- -------------------------------------------------------------------------------



	SET @return_value			= 0
	set @ret_ErrorCode			= 0
	set @ret_ErrorDescription	= ''




	--si todos los productos a producir no son serializables, ejecutamos el spSaleOrderSerialProduced_produceSOData
	--sino, se ejecuta el código de este sp
	IF EXISTS (	SELECT TOP 1 	1
				FROM	tbSaleOrderDetail tsod		WITH (NOLOCK)
						INNER JOIN tbItem ti		WITH (NOLOCK)
						ON	ti.comp_id		= tsod.comp_id
						AND ti.item_id		= tsod.item_id
						AND IsNull(ti.item_expser,'False')	= 'false'
				WHERE	tsod.comp_id	= @comp_id
				AND		tsod.bra_id		= @bra_id
				AND		tsod.soh_id		= @soh_id	)
		BEGIN



			EXEC spSaleOrderSerialProduced_produceSOData
					@comp_id,
					@lang_id,
					@bra_id,
					@user_id,
					@soh_id,
					@guid,
					@return_value			OUTPUT,
					@ret_ErrorCode			OUTPUT,
					@ret_ErrorDescription	OUTPUT


		END
	ELSE


		BEGIN


			SET @return_value			= -1
			set @ret_ErrorCode			= -1
			set @ret_ErrorDescription	= 'Solo se puede producir por LOTE Artículos que NO se serializan'
			RETURN

				BEGIN TRANSACTION
				BEGIN TRY


					/*********************************************************************************************************/
					-- verificamos si hay algún proveedor definido para producción
					IF EXISTS (	SELECT	TOP 1 1
	           					FROM	dbo.tbSupplier			ts		WITH (NOLOCK)
								WHERE	ts.comp_id = @comp_id
								AND		ISNULL(ts.supp_isSupp4Production,'false') = 'true' )
						BEGIN


							DECLARE @bra_processingDate			DATETIME,
									@prli_id					INT,
									@intStor_id_b				INT,
									@intSm_id					INT,
									@intDisc_id					INT,
									@intDl_id					INT,
									@intSt_id					INT,
									@ct_CompanyCurrency			INT,
									@supplierCurrencyId			INT,
									@BranchCurrencyId			INT,
									@supp_id					INT,
									@ct_transaction_rv			INT,
									@it_transaction_rv			INT,
									@stor_id					INT,
									@item_id					INT,
									@bra_checkSerialNumber		BIT,
									@it_order					INT,
									@sod_id						INT,
									@sod_qty					DECIMAL(19,6),
									@sod_qty_index				DECIMAL(19,6),
									@itemComposition_qty		DECIMAL(19,6),
									@item_id_1					INT,
									@ret_ErrorCode_rv			INT,
									@ret_ErrorDescription_rv	VARCHAR(200),
									@branch_country_id			INT,
									@branch_state_id			INT





							/********************************************************************************************************/
							-- Obtenemos datos de la sucursal
							SELECT 	@bra_processingDate		= tb.bra_processingDate,
									@intStor_id_b			= tb.stor_id,
									@BranchCurrencyId		= tb.curr_id,
									@stor_id				= tb.stor_id,
									@bra_checkSerialNumber	= isnull(tb.bra_checkSerialNumber,'false'),
									@branch_country_id		= tb.country_id,
									@branch_state_id		= tb.state_id

								FROM	dbo.tbBranch			tb		WITH (NOLOCK)

								WHERE	tb.comp_id				= @comp_id
								AND		tb.bra_id				= @bra_id
							/********************************************************************************************************/




							--SELECT @bra_checkSerialNumber [@bra_checkSerialNumber]
							/********************************************************************************************************/
							-- si @bra_checkSerialNumber = 'true' se deben generar la producción a partir de los datos cargados
							-- en la página actual, sino se deben cargar todos los artículos definidos en la tabla tbSaleOrderSerial4Production
							-- (verificar en que momento se graba esta tabla tbSaleOrderSerial4Production)
							IF @bra_checkSerialNumber = 'false'
								BEGIN
									-- si @bra_checkSerialNumber = 'false' se deben generar la producción a partir de los artículos
									-- definidos en la tabla tbSaleOrderSerial



									/********************************************************************************************************/
									-- recuperamos todos los artículos necesarios para producir el pedido completo
									SELECT	tic.item_id_1,
											convert(int,tsod.sod_qty * tic.icomp_qty) [qty],
											tsod.sod_qty
										INTO	#tmpItemsNeeded
										FROM	tbSaleOrderDetail			tsod		WITH (NOLOCK)
												INNER JOIN tbItemComposition tic		WITH (NOLOCK)
												ON tsod.comp_id = tic.comp_id
												AND tic.item_id = tsod.item_id

										WHERE	tsod.comp_id	= @comp_id
										AND		tsod.bra_id		= @bra_id
										AND		tsod.soh_id		= @soh_id



									-- Items SERIALIZADOS que no esten siendo producidos.-
									-- recuperamos todos los artículos disponibles del pedido a producir quitando los que están siendo
									-- producidos (tbSaleOrderSerial4Production) y los que ya fueron producidos (tbSaleOrderSerialProduced)
									SELECT	tis.item_id, COUNT(*) [qty]
										INTO	#tmpItemsFree
										FROM	tbSaleOrderSerials						tsos		WITH (NOLOCK)

												INNER JOIN tbItemSerials				tis			WITH (NOLOCK)
												ON  tis.comp_id		= tsos.comp_id
												AND tis.is_id		= tsos.is_id

												LEFT JOIN tbSaleOrderSerial4Production	tsosp		WITH (NOLOCK)
												ON	tsosp.comp_id	= tis.comp_id
												AND tsosp.is_id		= tis.is_id

												LEFT JOIN tbSaleOrderSerialProduced		tsosp2		WITH (NOLOCK)
												ON	tsos.comp_id	= tsosp2.comp_id
												AND tsos.soh_id		= tsosp2.soh_id

										WHERE	tsos.comp_id	= @comp_id
										AND		tsos.soh_id		= @soh_id
										AND		tsosp.soh_id	IS NULL
										AND		tsosp2.sod_id	IS NULL

										GROUP BY tis.item_id, tsosp.sod_id


									SELECT * FROM #tmpItemsNeeded
									SELECT * FROM #tmpItemsFree
									/********************************************************************************************************/





									/********************************************************************************************************/
									-- en la variable @validationQuantity almacenamos la diferencia entre la cantidad de artículos aociados y la cantidad
									-- de artículos asociados que están serializados y disponibles

									DECLARE @validationQuantity		INT
									-- Verifica que de los items SERIALIZABLES esten TODOS SERIALIZADOS
									SELECT	@validationQuantity  = COUNT(*) - sum(	CASE
																						WHEN itneed.[qty] <= itfree.[qty] THEN 1
																						ELSE 0
									      	           	END)
										FROM	#tmpItemsNeeded					itneed
											INNER JOIN tbItem				ti			WITH (NOLOCK)
												ON	ti.item_id			= itneed.item_id_1
											LEFT JOIN  #tmpItemsFree		itfree		WITH (NOLOCK)
												ON	itneed.item_id_1	=	itfree.item_id
										WHERE ti.item_expser = 1

									SELECT @validationQuantity [@validationQuantity]
									/********************************************************************************************************/





									/********************************************************************************************************/
									-- si las cantidades necesarias de cada artículo que compone el artículo a producir son
									-- mayores o iguales que las cantidades disponibles se procesa todo el pedido
									IF EXISTS (	SELECT	1
												FROM	#tmpItemsNeeded					itneed
												WHERE	@validationQuantity <=0 )
										BEGIN

											SELECT 'llego 1'





											/****************************************************************************************************/
											-- recuperamos todos los artículos a producir
											CREATE TABLE #tmpItemsToProduce (	[ ]				VARCHAR(2) NULL,
																				[item_desc]		VARCHAR(200) NULL,
																				[soh_id]		INT NULL,
																				[sod_id]		INT NULL,
																				[item_id]		INT NULL,
																				[number]		INT NULL,
																				[stor_desc]		VARCHAR(100) NULL,
																				[prli_desc]		VARCHAR(100) NULL,
																				[ID]			VARCHAR(100) NULL)

											INSERT #tmpItemsToProduce
												(
													[ ],
													[item_desc],
													[soh_id],
													[sod_id],
													[item_id],
													[number],
													[stor_desc],
													[prli_desc],
													[ID]
												)
											EXEC spSaleOrderDetail_GetDataforProduction @comp_id, @bra_id, @soh_id


											SELECT * FROM #tmpItemsToProduce
											/********************************************************************************************************/




				/*
				/****************************************************************************************************/
				-- cargamos las temporales para reservar todos los seriales y artículos para que no sean tomados por otros usuarios

				BEGIN TRY

					INSERT INTO tbSaleOrderSerialInProduction
					(
						comp_id,
						soh_id,
						sod_id,
						sosip_order,
						sosip_isEditing,
						sosip_isEditingCD
					)
					SELECT	@comp_id, t.soh_id,t.sod_id,t.number, 'True', GETDATE()
					FROM	#tmpItemsToProduce t

				END TRY
				BEGIN CATCH
					--SELECT 'error'
					SET @ct_transaction_rv			= -111
					SET @ret_ErrorCode_rv			= -111
					SET @ret_ErrorDescription_rv	= '01 - ya tiene artículos tomados'
					Set @ret_ErrorCode				= -111

					SELECT 1/0
				END CATCH
				--SELECT 'error1'
				--SELECT * FROM tbSaleOrderSerialInProduction WHERE soh_id = @soh_id




				INSERT INTO tbSaleOrderSerial4Production
				(
					comp_id,
					sosp_guid,
					is_id,
					soh_id,
					sod_id,
					sosp_order,
					sosp_isEditing,
					sosp_isEditingCD
				)
				SELECT	distinct
						@comp_id,
						@guid,
						tsos.is_id,
						t.soh_id,
						t.sod_id,
						1,
						'True',
						GETDATE()

				FROM	#tmpItemsToProduce					t

						INNER JOIN tbItemComposition		tic
						ON	tic.item_id		= t.item_id

						INNER JOIN tbSaleOrderSerials		tsos
						ON	tsos.comp_id	= tic.comp_id
						AND tsos.soh_id		= t.soh_id

						INNER JOIN tbItemSerials			tis
						ON	tis.comp_id		= tic.comp_id
						AND tis.is_id		= tsos.is_id
						AND tic.item_id_1	= tis.item_id

				WHERE	t.number	= 1
				AND		tic.comp_id	= @comp_id

				--SELECT * FROM tbSaleOrderSerial4Production WHERE soh_id = @soh_id
				/****************************************************************************************************/







				/****************************************************************************************************/
				-- se carga la tabla de artículos producidos
				INSERT INTO tbSaleOrderSerialProduced
				(
					comp_id,
					soh_id,
					sod_id,
					sosp_order
				)
				SELECT	@comp_id, soh_id, sod_id, number
				FROM	#tmpItemsToProduce

				--SELECT 'tbSaleOrderSerialProduced', * FROM tbSaleOrderSerialProduced WHERE soh_id = @soh_id
				/****************************************************************************************************/






				/****************************************************************************************************/
				-- recuperamos todos los datos necesarios para cargar tbCommercialTransaction

				-- datos del proveedor
				SELECT	TOP 1
						@supplierCurrencyId		= ts.curr_id,
						@supp_id				= ts.supp_id

				FROM	dbo.tbSupplier			ts

				WHERE	ts.comp_id = @comp_id
				AND		ISNULL(ts.supp_isSupp4Production,'false') = 'true'



				-- recuperar datos de la compañía
				SELECT	@ct_CompanyCurrency	= c.curr_id

				FROM	dbo.tbCompany			c

				WHERE	c.comp_id	= @comp_id



				-- recuperar datos para el insert en tbCommercialTransaction
				DECLARE --@lct_transaction_rv					INT,
						@ct_docNumber							INT,
						@ct_ACurrencyExchange					DECIMAL(19,4),
						@ct_Branch2CompanyCurrencyExchange		DECIMAL(19,4),
						--@lit_transaction_rv					INT,
						@decStorePreviuos						DECIMAL(19,6),
						@now									DATETIME



				-- obtener la fecha actual
				SET @now	= GETDATE()


				-- obtener el próximo número de ct_docNumber en @ct_docNumber
				EXEC dbo.spCounters_getNextValue @comp_id, 0, 12, @counter_value = @ct_docNumber OUTPUT


				-- tipo de cambio de la moneda del proveedor a la moneda de la sucursal
				SELECT @ct_ACurrencyExchange				= dbo.fnGetExchange(@comp_id,1,@supplierCurrencyId,	@BranchCurrencyId, 0,0,'False')


				-- tipo de cambio de la moneda de la sucursal a la moneda de la compañia
				SELECT @ct_Branch2CompanyCurrencyExchange	= dbo.fnGetExchange(@comp_id,1,@BranchCurrencyId,	@ct_CompanyCurrency,	0,0,'False')
				/****************************************************************************************************/





				/****************************************************************************************************/
				-- se genera un nuevo comprobante para toda la transacción

				EXEC spCommercialTransactions_InsertPurchaseData
					@comp_id,
					@bra_id,
					0,
					'',
					@ct_docNumber,
					@bra_processingDate,
					@bra_processingDate,
					@bra_processingDate,
					@supp_id,
					NULL,
					NULL,
					NULL,
					@user_id,
					0,									--@ct_subtotal = null,
					0,									--@ct_total = null,
					0,									--@ct_discount = null,
					0,									--@ct_adjust = null,
					0,									--@ct_taxes = null,
					@BranchCurrencyId,					--@curr_id_transaction = null, --moneda de la sucursal
					NULL,								--@hacc_transaction = null,
					NULL,								--@sm_id = null,
					NULL,								--@disc_id = null,
					0,									--@ct_ATotal = null,
					0,									--@ct_ABalance = null,
					@supplierCurrencyId,				--@ct_ACurrency = null, --moneda del proveedor
					@ct_ACurrencyExchange,				--@ct_ACurrencyExchange = null,
					NULL,								--@df_id = null,
					NULL,								--@dl_id = null,
					NULL,								--@st_id = null,
					145,								--@sd_id = null,
					NULL,								--@puco_id = null,
					@ct_CompanyCurrency,				--@ct_CompanyCurrency = null,
					@ct_Branch2CompanyCurrencyExchange, --@ct_Branch2CompanyCurrencyExchange = null,
					NULL,								--@ct_Pending = null,
					@branch_country_id,					--@country_id = null,
					@branch_state_id,					--@state_id = null,
					'false',							--@ct_isAvailableForImport = null,
					NULL,								--@ct_CAI = null,
					NULL,								--@ct_CAIDate = null,
					'',									--@observation1 = null,
					'',									--@observation2 = null,
					'',									--@observation3 = null,
					'',									--@observation4 = null,
					@supplierCurrencyId,				--@curr_id4Exchange = null,
					@ct_ACurrencyExchange,				--@ct_curr_IdExchange = null,

					@return_value			= @ct_transaction_rv		OUTPUT,
					@ret_ErrorCode			= @ret_ErrorCode_rv			OUTPUT,
					@ret_ErrorDescription	= @ret_ErrorDescription_rv	OUTPUT

				--SET @ret_ErrorCode_rv = -2
				IF @ret_ErrorCode_rv <> 0
				BEGIN
					SET @ret_ErrorCode			= @ret_ErrorCode_rv - 100
					SET @ret_ErrorDescription	= @ret_ErrorDescription_rv
					SELECT 1/0
				END





				UPDATE	tbCommercialTransactions

				SET		ct_soh_id	= @soh_id

				WHERE	comp_id			= @comp_id
				AND		bra_id			= @bra_id
				AND		ct_transaction	= @ct_transaction_rv

				--SELECT 'spCommercialTransactions_InsertPurchaseData', @ct_transaction_rv
				/****************************************************************************************************/





				/****************************************************************************************************/
				-- recuperamos la descripción para el mensaje por la producción de artículos
				SELECT	@ret_ErrorDescription	= tut.utexts_desc

				FROM	tbsysUniqueTexts tut

				WHERE	tut.lang_id		= @lang_id
				AND		tut.utexts_id	= 18
				/****************************************************************************************************/






				/****************************************************************************************************/
				-- cursor para recorrer todos los items de tbSaleOrderDetail original que son os artículos a producir
				DECLARE cursor_items CURSOR FOR
				SELECT	tsod.item_id, tsod.sod_id, tsod.sod_qty
				FROM	tbSaleOrderDetail			tsod
				WHERE	tsod.comp_id = @comp_id
				AND		tsod.soh_id  = @soh_id

				OPEN cursor_items

				FETCH cursor_items INTO @item_id, @sod_id, @sod_qty

				WHILE @@FETCH_STATUS = 0
				BEGIN


					/****************************************************************************************************/
					-- se actualiza el stock, se carga en la trasacción y se genera el serial del artículo producido

					-- actualizar el depósito con el artículo a generar, si existe no lo modifica y si
					-- no existe lo genera con stock en 0 (cero)
					EXEC spItemStorage_insertData @comp_id, @item_id, @stor_id, 0



					-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
					SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
					FROM	tbItemStorage tis
					WHERE	tis.comp_id = @comp_id
					AND		tis.stor_id = @stor_id
					AND		tis.item_id = @item_id



					SET @it_order = 1



					INSERT INTO tbItemTransactions
					(
						comp_id,				bra_id,						ct_transaction,
						item_id,				it_qty,						it_priceWithOutOthers,
						it_price,				curr_id,					it_exchangeToBranchCurrency,
						it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
						it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
						it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
						stor_id,				it_storePrevious,			prli_id,
						byor_id,				it_isProduction,			it_isAssociation,
						it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
						it_order,				so_id,						it_guarantee,
						it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
						it_CreditIntPlus,		puco_id,					it_poh_bra_id,
						it_poh_id,				it_soh_id,					it_sod_id,
						rmah_id,				rmad_id,					it_qty_rma,
						it_tis_id_aux
					)
					VALUES
					(
						@comp_id,				@bra_id,					@ct_transaction_rv,
						@item_id, 				@sod_qty,					0,
						0,						@supplierCurrencyId,		@supplierCurrencyId,
						0,						0,							0,
						0,						0,							0,
						0,						@supplierCurrencyId,		1,
						@stor_id,				isnull(@decStorePreviuos,0),NULL,
						NULL,					'False',					'False',
						NULL,					@now,						NULL,
						@it_order,				NULL,						0,
						0,						0,							0,
						0,						NULL,						NULL,
						NULL, 					@soh_id, 					@sod_id,
						NULL,					NULL,						NULL,
						NULL
					)

					SET @it_transaction_rv = @@IDENTITY
					--SELECT '@it_transaction_rv', @it_transaction_rv


					-- se incorpora el artículo al depósito
					UPDATE	tbItemStorage
					SET		itst_cant	= itst_cant + @sod_qty,
							itst_cd		= @now
					WHERE	comp_id		= @comp_id
					AND		stor_id		= @stor_id
					AND		item_id		= @item_id

					/****************************************************************************************************/







					/****************************************************************************************************/
					-- se generan tantos seriales como indica el @sod_qty
					-- se recupera un número desde el contador 11, es para generar el serial correspondiente para el
					-- producto a generar, al contador se le suma 980000000, para generar un serial con el formato 980000001, 980000002, etc
					-- se agrega el serial en tbItemSerials

					DECLARE @counter	INT
					DECLARE @is_id		INT

					SET @sod_qty_index = @sod_qty


					WHILE @sod_qty_index > 0
					BEGIN


						EXEC dbo.spCounters_getNextValue @comp_id, 0, 11, @counter_value = @counter OUTPUT
						--SELECT @counter


						DECLARE @serial INT
						SET @serial = 980000000 + @counter
						--SELECT 'nro de serial generado', @serial

						-- si no hay ningún error queda cargado el serial generado en la variable de retorno de mensajes de error
						SET @ret_ErrorDescription = @ret_ErrorDescription + CONVERT(VARCHAR,@serial) + ' # '




						INSERT INTO tbItemSerials
						(
							comp_id,
							-- is_id -- this column value is auto-generated,
							bra_id,
							ct_transaction,
							it_transaction,
							item_id,
							is_serial,
							is_cd,
							is_available,
							stor_id,
							is_guid,
							is_IsOwnGeneration,
							is_checked,
							is_printed
						)
						VALUES
						(
							@comp_id,
							@bra_id,
							@ct_transaction_rv,
							@it_transaction_rv,
							@item_id,
							convert(varchar,@serial),
							@now,
							'true',
							@stor_id,
							@guid,
							'true',
							'false',
							'false'
						)

						SET @is_id = @@IDENTITY




						INSERT INTO tbItemSerials4Production
						(
							comp_id,
							is_idProduced,
							is_idPart,
							-- is4p_id -- this column value is auto-generated,
							soh_id,
							sod_id,
							is4p_order
						)

						SELECT	@comp_id,
								@is_id,
								tsosp.is_id,
								@soh_id,
								@sod_id,
								titp.number
						FROM	tbSaleOrderSerial4Production tsosp
								INNER JOIN #tmpItemsToProduce titp
								ON	titp.soh_id = tsosp.soh_id
								AND titp.sod_id = tsosp.sod_id
						WHERE	tsosp.comp_id		= @comp_id
						AND		tsosp.sosp_guid		= @guid
						AND		tsosp.soh_id		= @soh_id
						AND		tsosp.sod_id		= @sod_id
						AND		tsosp.sosp_order	= 1




						SET @sod_qty_index = @sod_qty_index - 1

					END
					/****************************************************************************************************/






					/****************************************************************************************************/
					-- se actualiza el stock, se carga en la trasacción de los artículos asociados al artículo producido

					DECLARE cursor_itemsComposition CURSOR FOR
					SELECT	DISTINCT tic.item_id_1, tic.icomp_qty * tsod.sod_qty

					FROM	tbSaleOrderSerial4Production		tsosp
							INNER JOIN tbSaleOrderDetail		tsod
							ON	tsod.comp_id	= tsosp.comp_id
							AND tsod.soh_id		= @soh_id
							AND tsod.sod_id		= @sod_id
							INNER JOIN tbItemComposition tic
							ON	tic.comp_id		= tsod.comp_id
							AND tic.item_id		= tsod.item_id

					WHERE	tsosp.comp_id	= @comp_id
					AND		tsosp.sosp_guid = @guid

					OPEN cursor_itemsComposition

					FETCH cursor_itemsComposition INTO @item_id_1, @itemComposition_qty

					WHILE @@FETCH_STATUS = 0
					BEGIN

						-- se actualiza el stock de los artículos que componen el artículo generado

						-- actualizar el depósito con el artículo que compone el artículo a generar, si existe no lo modifica y si
						-- no existe lo genera con stock en 0 (cero)
						EXEC spItemStorage_insertData @comp_id, @item_id_1, @stor_id, 0


						-- Recupera Stock Anterior para utilizarlo en el insert de tbItemTransaction
						SELECT	@decStorePreviuos = isnull(tis.itst_cant,0)
						FROM	tbItemStorage tis
						WHERE	tis.comp_id = @comp_id
						AND		tis.stor_id = @stor_id
						AND		tis.item_id = @item_id_1



						SET @it_order = @it_order + 1



						INSERT INTO tbItemTransactions
						(
							comp_id,				bra_id,						ct_transaction,
							item_id,				it_qty,						it_priceWithOutOthers,
							it_price,				curr_id,					it_exchangeToBranchCurrency,
							it_priceOfCost,			it_priceOfCostPP,			it_priceOfCostLastPurchase,
							it_priceBOfCost,		it_priceBOfCostPP,			it_priceBOfCostLastPurchase,
							it_OriginalPrice,		it_OriginalPriceCurrency,	it_exchangeToOriginalPriceCurrency,
							stor_id,				it_storePrevious,			prli_id,
							byor_id,				it_isProduction,			it_isAssociation,
							it_isAssociationGroup,	it_cd,						it_packingInvoicePend,
							it_order,				so_id,						it_guarantee,
							it_itemDiscountTotal,	it_totalDiscountTotal,		it_CreditInt,
							it_CreditIntPlus,		puco_id,					it_poh_bra_id,
							it_poh_id,				it_soh_id,					it_sod_id,
							rmah_id,				rmad_id,					it_qty_rma,
							it_tis_id_aux
						)
						VALUES
						(
							@comp_id,				@bra_id,					@ct_transaction_rv,
							@item_id_1,				@itemComposition_qty * -1,	0,
							0,						@supplierCurrencyId,		@supplierCurrencyId,
							0,						0,							0,
							0,						0,							0,
							0,						@supplierCurrencyId,		1,
							@stor_id,				isnull(@decStorePreviuos,0),NULL,
							NULL,					'False',					'False',
							NULL,					@now,						NULL,
							@it_order,				NULL,						0,
							0,						0,							0,
							0,						NULL,						NULL,
							NULL, 					@soh_id, 					@sod_id,
							NULL,					NULL,						NULL,
							NULL
						)

						SET @it_transaction_rv = @@IDENTITY
						--SELECT '@it_transaction_rv', @it_transaction_rv


						-- se incorpora el artículo al depósito
						UPDATE	tbItemStorage
						SET		itst_cant	= itst_cant - @itemComposition_qty,
								itst_cd		= @now
						WHERE	comp_id		= @comp_id
						AND		stor_id		= @stor_id
						AND		item_id		= @item_id_1




						FETCH cursor_itemsComposition INTO @item_id_1, @itemComposition_qty

					END

					CLOSE cursor_itemsComposition
					DEALLOCATE cursor_itemsComposition
					/****************************************************************************************************/



					FETCH cursor_items INTO @item_id, @sod_id, @sod_qty

				END

				CLOSE cursor_items
				DEALLOCATE cursor_items
				/****************************************************************************************************/





				/****************************************************************************************************/
				-- se vuelven a actualizar los isAvailable de la tabla tbItemSerials

				UPDATE	tbItemSerials

				SET		is_available = 'false'

				FROM	tbItemSerials								tis

						INNER JOIN tbSaleOrderSerial4Production		tsosp
						ON	tsosp.comp_id	= tis.comp_id
						AND tsosp.is_id		= tis.is_id

				WHERE	tis.comp_id		= @comp_id
				AND		tsosp.sosp_guid = @guid
				/****************************************************************************************************/




				/****************************************************************************************************/
				-- se envía a la history el pedido original y se borra el pedido original

				EXEC spSaleOrderHistory_InsertFromSaleOrder
					@comp_id,
					@bra_id,
					@soh_id,
					100


				DELETE FROM tbSaleOrderExtendedDiscount
				WHERE	comp_id = @comp_id
				AND		bra_id	= @bra_id
				AND		soh_id	= @soh_id

				DELETE FROM tbSaleOrderTaxes
				WHERE	comp_id = @comp_id
				AND		bra_id	= @bra_id
				AND		soh_id	= @soh_id

				DELETE FROM tbSaleOrderDetail
				WHERE	comp_id = @comp_id
				AND		bra_id	= @bra_id
				AND		soh_id	= @soh_id

				DELETE FROM tbSaleOrderSerials
				WHERE	comp_id = @comp_id
				AND		bra_id	= @bra_id
				AND		soh_id	= @soh_id

				DELETE FROM tbSaleOrderHeader
				WHERE	comp_id = @comp_id
				AND		bra_id	= @bra_id
				AND		soh_id	= @soh_id
				/****************************************************************************************************/

				*/



										END
									ELSE
										BEGIN

											-- si las cantidades necesarias de cada artículo que compone el artículo a producir no están
											-- disponibles no se procesa el pedido entonces retornamos el mensaje correspondiente
											SET		@return_value			= -2
											SET		@ret_ErrorCode			= -2
											SELECT	@ret_ErrorDescription	= tut.utexts_desc
											FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
											WHERE	tut.lang_id		= @lang_id
											AND		tut.utexts_id	= 16

										END

								END
						END
					ELSE
						BEGIN

----==
--SET @return_value			= 0
--set @ret_ErrorCode			= 0
--set @ret_ErrorDescription	= 'La re puta madre que te pario MOH'
--RETURN
----==

							-- no hay definido ningún proveedor para producción entonces retornamos el mensaje correspondiente
							SET		@return_value			= -3
							SET		@ret_ErrorCode			= -3
							SELECT	@ret_ErrorDescription	= tut.utexts_desc
							FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
							WHERE	tut.lang_id		= @lang_id
							AND		tut.utexts_id	= 17

						END





					/****************************************************************************************************/
					-- se eliminan todos lo registros generados para la reserva de la producción seleccionada

					DELETE FROM tbSaleOrderSerialInProduction
					WHERE	comp_id		= @comp_id
					AND		soh_id		= @soh_id

					DELETE FROM tbSaleOrderSerial4Production
					WHERE	comp_id		= @comp_id
					AND		sosp_guid	= @guid

					/****************************************************************************************************/

----==
--SET @return_value			= 0
--set @ret_ErrorCode			= 0
--set @ret_ErrorDescription	= '3 La re puta madre que te pario MOH ' + CONVERT(VARCHAR,@validationQuantity)
--ROLLBACK TRANSACTION
--RETURN
----==




					COMMIT TRANSACTION


				END
				TRY BEGIN CATCH
					--SELECT @ret_ErrorCode [@ret_ErrorCode]
					IF @ret_ErrorCode < -100
					BEGIN

						SET @return_value			= @ct_transaction_rv
						SET @ret_ErrorCode			= @ret_ErrorCode_rv
						SET @ret_ErrorDescription	= @ret_ErrorDescription_rv

					END
					ELSE
					BEGIN

						SET @return_value			= -1
						SET @ret_ErrorCode			= ERROR_NUMBER()
						SET @ret_ErrorDescription	= ERROR_MESSAGE()

					END

					ROLLBACK TRANSACTION

				END CATCH

		END


END


GO







CREATE PROCEDURE [dbo].[spSaleOrderSerials_DeleteAllSerials]
  (
  	  @comp_id			int,
  	  @bra_id			int,
  	  @soh_id 			int
  )

AS

BEGIN

	SET NOCOUNT ON

-- ------------------------------------------------------------
-- Testing
-- ------------------------------------------------------------
	/*
	DECLARE @comp_id			int,
  			@bra_id				int,
  			@soh_id 			INT


	SELECT @comp_id		= 1,
		   @bra_id		= 1,
  		   @soh_id 		= 7962
  		   DROP TABLE #tmp
	  */
-- ------------------------------------------------------------


	--Actualizo el estado en preparación.
	UPDATE tbSaleOrderHeader
	SET ssos_id   = 20
	WHERE comp_id = @comp_id
	AND   bra_id  = @bra_id
	AND	  soh_id  = @soh_id

	-- ---------------------------------------------------------------------------------------------
	-- Pone @bitIsAvailable en true si es una factura y en false si es pedido para nota de credito.-
	-- ---------------------------------------------------------------------------------------------
	DECLARE @bitIsAvailable AS BIT
	SELECT @bitIsAvailable = case
								when td.sd_isCredit = 'False' then 'True'
								ELSE 'False'
							 END
		FROM tbSaleOrderHeader tsoh
		INNER JOIN tbDocumentsFile tdf
			ON		tdf.comp_id = tsoh.comp_id
				AND tdf.df_id	= tsoh.df_id
		INNER JOIN tbsysDocuments td
			ON td.sd_id		= tdf.sd_id
	WHERE	tsoh.comp_id	= @comp_id
		AND tsoh.soh_id		= @soh_id
		AND tsoh.bra_id		= @bra_id

	SET @bitIsAvailable = ISNULL(@bitIsAvailable,'True')
	-- ---------------------------------------------------------------------------------------------



	-- habilito los items serializados de tbitemserials, is_available = true.
	UPDATE tbItemSerials
		SET
			is_available = @bitIsAvailable      --'True'
		FROM tbItemSerials tis
		INNER JOIN tbSaleOrderSerials tsos
			ON		tsos.comp_id	= tis.comp_id
				AND tsos.is_id      = tis.is_id
		WHERE       tsos.bra_id		= @bra_id
				AND tsos.soh_id		= @soh_id
				AND tsos.comp_id    = @comp_id


	--Borro todos los seriales de este pedido
	DELETE tbSaleOrderSerials
		WHERE  comp_id = @comp_id
		AND	   bra_id  = @bra_id
		AND	   soh_id  = @soh_id

END
GO









CREATE PROCEDURE [dbo].[spSaleOrderSerials_deleteData]
(
    @comp_id		INT,
	@is_id			INT,
	@bra_id			INT,
	@sose_id		INT,
	@serial			VARCHAR(100),
	@return_value	INT OUTPUT
)
AS

SET NOCOUNT ON


DECLARE @lsoh_id INT
DECLARE @lbra_id int

BEGIN TRANSACTION
BEGIN TRY


	-- recuperamos el soh_id del registro que se va a eliminar
	SELECT	Top 1
			@lsoh_id = tsos.soh_id ,
			@lbra_id = tsos.bra_id
	FROM	dbo.tbSaleOrderSerials			tsos		WITH (NOLOCK)
	WHERE	tsos.comp_id	= @comp_id
	AND		tsos.is_id		= @is_id
	--AND		tsos.sose_id	= @sose_id  MOS



	-- eliminamos el serial seleccionado
	DELETE	dbo.tbSaleOrderSerials
	WHERE	comp_id			= @comp_id
	AND		is_id			= @is_id
	--AND		sose_id			= @sose_id   -- MOS



	-- ---------------------------------------------------------------------------------------------
	-- Pone @bitIsAvailable en true si es una factura y en false si es pedido para nota de credito.-
	-- ---------------------------------------------------------------------------------------------
	DECLARE @bitIsAvailable AS BIT
	SELECT @bitIsAvailable = case
								when td.sd_isCredit = 'False' then 'True'
								ELSE 'False'
							 END
		FROM tbSaleOrderHeader	tsoh		WITH (NOLOCK)
		INNER JOIN tbDocumentsFile tdf		WITH (NOLOCK)
			ON		tdf.comp_id = tsoh.comp_id
				AND tdf.df_id	= tsoh.df_id
		INNER JOIN tbsysDocuments td		WITH (NOLOCK)
			ON td.sd_id = tdf.sd_id
		WHERE	tsoh.comp_id	= @comp_id
			AND tsoh.soh_id		= @lsoh_id
			AND tsoh.bra_id		= @lbra_id

	SET @bitIsAvailable = ISNULL(@bitIsAvailable,'True')
	-- ---------------------------------------------------------------------------------------------




	-- ponemos como disponible el serial seleccionado para poder volver a utilizarlo
	UPDATE	dbo.tbItemSerials
	SET		is_available	= @bitIsAvailable
	WHERE	comp_id			= @comp_id
	AND		(is_serial		= @serial or is_id = @is_id)



	-- ponemos el pedido relacionado al serial que se elimina en estado EN PROCESO - 20
	UPDATE	dbo.tbSaleOrderHeader
	SET		ssos_id			= 20
	WHERE	comp_id			= @comp_id
	AND		bra_id			= @lbra_id
	AND		soh_id			= @lsoh_id



	SET @return_value = 1
	COMMIT TRANSACTION


END
TRY BEGIN CATCH
	SET @return_value = 0
	ROLLBACK TRANSACTION
END CATCH
GO








CREATE PROCEDURE [dbo].[spSaleOrderSerials_get]
(
		@comp_id			int,
		@bra_id				int,
		@soh_id 			int
)
as

set nocount on

/*
declare	@comp_id	int,
		@bra_id		int,
		@soh_id		int

select	@comp_id	= 1,
		@bra_id		= 1,
		@soh_id		= 7150
*/

select	' ',
		it.item_code,
		it.item_desc,
		its.is_serial,
		convert(varchar, ISID.import_id) + '-' +
		CONVERT(varchar, ISID.impData_id) + '-' +
		convert(varchar, sose.is_id) + '-' +
		convert(varchar, sose.sose_id) as ID

from	dbo.tbSaleOrderSerials				sose		WITH (NOLOCK)

		inner join dbo.tbItemSerials		its		WITH (NOLOCK)
		on	its.comp_id			= @comp_id
--			its.import_id		= sose.import_id
--		and	its.impData_id		= sose.impData_id
		and	its.is_id			= sose.is_id

		Inner Join dbo.vwItemSerialsImportData ISID		WITH (NOLOCK)
			On		ISID.comp_id = its.comp_id
				and ISID.ct_transaction = its.ct_transaction
				and ISID.it_transaction = its.it_transaction

		inner join dbo.tbItem				it		WITH (NOLOCK)
		on	it.comp_id			= sose.comp_id
		and	it.item_id			= its.item_id

where	sose.comp_id	=	 @comp_id
and		sose.bra_id		=	 @bra_id
and		sose.soh_id		=	 @soh_id

order by it.item_desc
GO





CREATE PROCEDURE [dbo].[spSaleOrderSerials_getDataByFilters]
(
  @comp_id			int,
  @bra_id			int,
  @soh_id 			int,
  @user_id			INT,
  @prof_id			INT,
  @bitNoStorageByProfileControl AS BIT
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON



	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
	/*
	Declare	@comp_id	INT,
  			@bra_id		INT,
  			@soh_id		INT,
			  @user_id			INT = 1,
			  @prof_id			INT = 1,
			  @bitNoStorageByProfileControl AS BIT = 0
	Select	@comp_id	= 1,
  			@bra_id		= 27,
  			@soh_id		= 6542

	IF NOT OBJECT_ID('tempdb.dbo.#tmp_serialized')				IS NULL DROP TABLE #tmp_serialized
	IF NOT OBJECT_ID('tempdb.dbo.#tmp_pending_serialized')		IS NULL DROP TABLE #tmp_pending_serialized
	IF NOT OBJECT_ID('tempdb.dbo.#tmp_pending_serialized1')		IS NULL DROP TABLE #tmp_pending_serialized1
	IF NOT OBJECT_ID('tempdb.dbo.#tmp_to_serialize')			IS NULL DROP TABLE #tmp_to_serialize
	IF NOT OBJECT_ID('tempdb.dbo.#tmp_sumserialized')			IS NULL DROP TABLE #tmp_sumserialized
	IF NOT OBJECT_ID('tempdb.dbo.#tmpSaleOrderDetail')			IS NULL DROP TABLE #tmpSaleOrderDetail
	IF NOT OBJECT_ID('tempdb.dbo.#tmpSaleOrderDetail2')			IS NULL DROP TABLE #tmpSaleOrderDetail2
	IF NOT OBJECT_ID('tempdb.dbo.#tmp_pending_serialized2')		IS NULL DROP TABLE #tmp_pending_serialized2
	*/
	-- -----------------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Carga UNICAMENTE  los depositos q le correspondan
	-- -----------------------------------------------------------------------------
	DECLARE @tmpStorage  TABLE(stor_id INT NULL, UNIQUE NONCLUSTERED (stor_id) )
	IF	(
			@bitNoStorageByProfileControl = 'False' AND
			EXISTS(	SELECT TOP 1  1
	          			FROM tbStorage4Profile tsp	WITH (NOLOCK)
	          			WHERE	tsp.comp_id = @comp_id AND
	          					tsp.prof_id = @prof_id)
		)
		BEGIN	-- Todos los depositos q tiene definidos x perfil
			INSERT INTO @tmpStorage(stor_id)
				SELECT DISTINCT tsp.stor_id
					FROM tbStorage4Profile tsp		WITH (NOLOCK)
	          			WHERE	tsp.comp_id = @comp_id AND
	          					tsp.prof_id = @prof_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpStorage(stor_id)	-- Todos los depositos
				SELECT ts.stor_id FROM tbStorage ts
		END

	-- Inserta el deposito NULL para loa articulos manuales.!
	IF NOT EXISTS(SELECT TOP 1  1 FROM @tmpStorage WHERE stor_id IS null)
		BEGIN
			INSERT INTO @tmpStorage(stor_id) VALUES (NULL)
		END
	-- Inserta el deposito NULL para loa articulos manuales.!
	IF NOT EXISTS(SELECT TOP 1  1 FROM @tmpStorage WHERE stor_id = 0)
		BEGIN
			INSERT INTO @tmpStorage(stor_id) VALUES (0)
		END
	-- -----------------------------------------------------------------------------






	SELECT	' '											[.],
			1											[qty],
			it.item_code,
			it.item_desc,
			it.item_id,
			sose.comp_id,
			sose.bra_id,
			sose.soh_id,
			isnull(its.is_serial,'')					[is_serial],
			convert(varchar, sose.is_id) + '-' +
			convert(varchar, sose.sose_id)				[ID]

		INTO	#tmp_serialized
		FROM	dbo.tbSaleOrderSerials				sose			WITH (NOLOCK)
		INNER JOIN dbo.tbItemSerials		its				WITH (NOLOCK)
			ON 	its.is_id			= sose.is_id
		INNER JOIN dbo.tbItem				it				WITH (NOLOCK)
			ON	it.comp_id			= sose.comp_id
			and	it.item_id			= its.item_id
		where	sose.comp_id	=	 @comp_id
		and		sose.bra_id		=	 @bra_id
		and		sose.soh_id		=	 @soh_id --AND it.item_NoStockCheck='False'


		CREATE CLUSTERED INDEX IXtmp_serialized ON #tmp_serialized ([item_id]);




		SELECT 	[.],
				[qty],
				item_code,
				item_desc,
				item_id,
				--sose.comp_id,
				--sose.bra_id,
				--sose.soh_id,
				[is_serial],
				[ID]
		FROM	#tmp_serialized




	-- obtenemos el sd_id del pedido para determinar si es un pedido de producción o no
	DECLARE @sd_id integer

	SELECT	@sd_id = tdf.sd_id
		FROM	tbSaleOrderHeader				tsoh	WITH (NOLOCK)
				INNER JOIN tbDocumentsFile		tdf		WITH (NOLOCK)
				ON	tdf.comp_id = tsoh.comp_id
				AND tdf.df_id	= tsoh.df_id
		WHERE	tsoh.comp_id	= @comp_id
		AND		tsoh.bra_id		= @bra_id
		AND		tsoh.soh_id		= @soh_id
	--SELECT @sd_id





	-- -----------------------------------
	-- Si es un Pedido NORMAL
	-- -----------------------------------
	IF @sd_id <> 80
		BEGIN

			DECLARE @intQTYStorageByItem AS INT
			SELECT	@intQTYStorageByItem = COUNT(tsod.stor_id)
				FROM tbSaleOrderDetail tsod			WITH (NOLOCK)
				INNER JOIN tbItem ti				WITH (NOLOCK)
					ON	ti.comp_id = tsod.comp_id AND
						ti.item_id = tsod.item_id
				WHERE	tsod.comp_id	= @comp_id	AND
						tsod.bra_id		= @bra_id	AND
						tsod.soh_id		= @soh_id	AND
						ti.item_expser	= 'True'
				--GROUP BY tsod.stor_id




			IF @intQTYStorageByItem  <= 1
				BEGIN

					SELECT  sod.item_id, sum(sod.sod_qty) sod_qty, it.item_code, it.item_desc,  sod.stor_id,
							ISNULL(tis.itst_PickingLocation,'')			[itst_PickingLocation],
							ISNULL(tis.itst_StorageLocation,'')			[itst_StorageLocation]
						into	#tmpSaleOrderDetail
						FROM 	dbo.tbSaleOrderDetail				sod	WITH (NOLOCK)
						INNER JOIN @tmpStorage tmps
							ON tmps.stor_id = sod.stor_id
						INNER JOIN dbo.tbItem				it	WITH (NOLOCK)
							ON 	it.comp_id		= sod.comp_id
							AND it.item_id		= sod.item_id
							AND it.item_expser  = 'true'
						LEFT JOIN tbItemStorage AS					tis	WITH (NOLOCK)
							ON	tis.comp_id = @comp_id		AND
								tis.stor_id = tmps.stor_id	AND
								tis.item_id = sod.item_id
						WHERE	sod.comp_id			= @comp_id
						AND 	sod.bra_id			= @bra_id
						and 	sod.soh_id			= @soh_id
						-- CTRL de DEPOSITO ACA!!! de PENDIENTES!!!
						group by	sod.item_id, it.item_code, it.item_desc, sod.stor_id,
									tis.itst_PickingLocation,
									tis.itst_StorageLocation





					-- recupera lo pendiente
					SELECT  (ISNULL(sod.sod_qty,0) - SUM(ISNULL(tmps.qty,0)))				[qty]		,
							isnull(sod.item_code, tmps.item_code)							[item_code]	,
							isnull(sod.item_desc, tmps.item_desc)							[item_desc],
							dbo.fnGetStockOfStorageGroup(@comp_id, sod.stor_id, sod.item_id)	[PhisicalStock],
							sod.stor_id,
							sod.itst_PickingLocation										[itst_PickingLocation],
							sod.itst_StorageLocation										[itst_StorageLocation]

						INTO	#tmp_pending_serialized
						FROM 	#tmpSaleOrderDetail				sod
						FULL OUTER JOIN #tmp_serialized     tmps
							ON	tmps.item_id	=	sod.item_id

								--AND tmps.comp_id	= @comp_id
								-- MOS 10/2017 AND tmps.bra_id		= @bra_id
								-- MOS 10/2017 AND (tmps.soh_id	= @soh_id OR tmps.soh_id IS NULL)

						GROUP BY	ISNULL(sod.sod_qty	, 0				),
									ISNULL(sod.item_code	, tmps.item_code),
									ISNULL(sod.item_desc	, tmps.item_desc) ,
									sod.item_id,
									sod.stor_id,
									sod.itst_PickingLocation,
									sod.itst_StorageLocation


--==
--select 555,* from #tmp_pending_serialized



					-- Retorna los items Pendientes de serializar y los numeros de serie que sobran.
					-- Esto puede pasar si se serializo un pedido con 5 items y luego lo modifican
					-- a 3 items, por lo que sobraran 2 items.  Si sobran, no se debe permitir cerrar
					-- el pedido.-
					SELECT	CONVERT(DECIMAL(18,2),tmp.qty)	[qty],
							tmp.item_code,
							tmp.item_desc,
  							convert(decimal(20,2),ISNULL(tmp.PhisicalStock,0))		[PhisicalStock],
  							ISNULL(ts.stor_desc,'*')								[stor_desc],
							tmp.itst_PickingLocation								[itst_PickingLocation],
							tmp.itst_StorageLocation + ' (1)'						[itst_StorageLocation]
						FROM	#tmp_pending_serialized tmp
						LEFT JOIN tbStorage ts	WITH (NOLOCK)
							ON	ts.comp_id = @comp_id AND
								ts.stor_id = tmp.stor_id
						WHERE	[qty] > 0 OR [qty] < 0
						--SELECT 'aca 2'



					--ESTOS SON LOS PENDIENTES
					SELECT  convert(decimal(18,2),isnull(sod.sod_qty,0))	[sod_qty],
							convert(decimal(18,2),isnull(sodt.sodt_qty,0))	[confirmed_qty],
  							it.item_code,
  							isnull(it.item_desc,sod.sod_itemDesc)			[item_desc],
							tov.optval_desc									[sod_DeliveryMethod],
							sod.sod_itemDeliveryDate
						FROM	dbo.tbSaleOrderDetail		sod	WITH (NOLOCK)
						INNER JOIN tbBranch AS tb	WITH (NOLOCK)
							ON	tb.comp_id		= sod.comp_id AND
								tb.bra_id		= sod.bra_id
						LEFT JOIN dbo.tbItem				it	WITH (NOLOCK)
							ON  it.comp_id	= sod.comp_id
							AND it.item_id	= sod.item_id
						left join dbo.tbSaleOrderDetailtmp	Sodt	WITH (NOLOCK)
							on	sodt.comp_id	= sod.comp_id
							and sodt.bra_id		= sod.bra_id
							and sodt.soh_id		= sod.soh_id
							and sodt.sod_id		= sod.sod_id
						LEFT JOIN tbsysOptionsValues AS tov
							ON	tov.lang_id			= tb.lang_id	AND
								tov.optval_class	= 520			AND
								tov.optval_id		= sod.sdlmt_id
						WHERE 	sod.comp_id		= @comp_id
						AND 	sod.bra_id		= @bra_id
						AND 	sod.soh_id		= @soh_id
						and		ISNULL(it.item_expser,'False')			=	'false'
						--and		ISNULL(it.item_NoStockCheck,'False')	=	'false'
						AND		isnull(sod.sod_qty,0)			<>  isnull(sodt.sodt_qty,0)


				END

			ELSE

				-- Si hay items con mas de un deposito en el mismo pedido no informa los totales de stock ya que es IMPOSIBLE,
				-- NO TRATAR PLS ya que es p[erder el tiempo al pedo
				BEGIN

					SELECT  sod.item_id, sum(sod.sod_qty) sod_qty, it.item_code, it.item_desc,
							ISNULL(tis.itst_PickingLocation,'')			[itst_PickingLocation],
							ISNULL(tis.itst_StorageLocation,'')			[itst_StorageLocation]
						into	#tmpSaleOrderDetail2
						FROM 	dbo.tbSaleOrderDetail				sod	WITH (NOLOCK)
						INNER JOIN @tmpStorage tmps
							ON tmps.stor_id = sod.stor_id
						INNER JOIN dbo.tbItem						it	WITH (NOLOCK)
							ON 	it.comp_id		= sod.comp_id
							AND it.item_id		= sod.item_id
							AND it.item_expser  = 'true'
						LEFT JOIN tbItemStorage AS					tis	WITH (NOLOCK)
							ON	tis.comp_id = @comp_id		AND
								tis.stor_id = tmps.stor_id	AND
								tis.item_id = sod.item_id
						WHERE	sod.comp_id			= @comp_id
						AND 	sod.bra_id			= @bra_id
						and 	sod.soh_id			= @soh_id
						-- CTRL de DEPOSITO ACA!!! de PENDIENTES!!!
						group by sod.item_id, it.item_code, it.item_desc,tis.itst_PickingLocation,tis.itst_StorageLocation


					-- recupera lo pendiente
					SELECT  (ISNULL(sod.sod_qty,0) - SUM(ISNULL(tmps.qty,0)))				[qty]		,
							isnull(sod.item_code, tmps.item_code)							[item_code]	,
							isnull(sod.item_desc, tmps.item_desc)							[item_desc],
							sod.itst_PickingLocation										[itst_PickingLocation],
							sod.itst_StorageLocation										[itst_StorageLocation]
						INTO	#tmp_pending_serialized2
						FROM 	#tmpSaleOrderDetail2				sod
						FULL OUTER JOIN #tmp_serialized     tmps	WITH (NOLOCK)
							ON	tmps.item_id		= sod.item_id
								AND tmps.bra_id		= @bra_id
								AND (tmps.soh_id	= @soh_id OR tmps.soh_id IS NULL)
						GROUP BY	ISNULL(sod.sod_qty	, 0				),
									ISNULL(sod.item_code	, tmps.item_code),
									ISNULL(sod.item_desc	, tmps.item_desc),
									sod.itst_PickingLocation,
									sod.itst_StorageLocation



					-- Retorna los items Pendientes de serializar y los numeros de serie que sobran.
					-- Esto puede pasar si se serializo un pedido con 5 items y luego lo modifican
					-- a 3 items, por lo que sobraran 2 items.  Si sobran, no se debe permitir cerrar
					-- el pedido.-
					SELECT	CONVERT(DECIMAL(18,2),[qty])	[qty],
							item_code,
							item_desc,
							itst_PickingLocation				[itst_PickingLocation],
							itst_StorageLocation + ' (2)'		[itst_StorageLocation]
						FROM	#tmp_pending_serialized2
						WHERE	[qty] > 0 OR [qty] < 0
						--SELECT 'aca 2'






					--ESTOS SON LOS PENDIENTES
					SELECT  convert(decimal(18,2),isnull(sod.sod_qty,0))	[sod_qty],
							convert(decimal(18,2),isnull(sodt.sodt_qty,0))	[confirmed_qty],
  							it.item_code,
  							isnull(it.item_desc,sod.sod_itemDesc)			[item_desc]

						FROM	dbo.tbSaleOrderDetail				sod	WITH (NOLOCK)

						LEFT JOIN dbo.tbItem				it	WITH (NOLOCK)
							ON  it.comp_id	= sod.comp_id
							AND it.item_id	= sod.item_id

						left join dbo.tbSaleOrderDetailtmp	Sodt	WITH (NOLOCK)
							on	sodt.comp_id	= sod.comp_id
							and sodt.bra_id		= sod.bra_id
							and sodt.soh_id		= sod.soh_id
							and sodt.sod_id		= sod.sod_id

						WHERE 	sod.comp_id		= @comp_id
						AND 	sod.bra_id		= @bra_id
						AND 	sod.soh_id		= @soh_id
						and		ISNULL(it.item_expser,'False')			=	'false'
						--AND		ISNULL(it.item_NoStockCheck,'False')	=	'False'
						AND		isnull(sod.sod_qty,0)					<>  isnull(sodt.sodt_qty,0)

				END





		END

			-- -----------------------------------
	ELSE	-- Si es un Pedido de Produccion
			-- -----------------------------------


		-- Si es un Pedido de Produccion...
		BEGIN

			--sumatoria de lo serializado
			select	sum(ser.qty)	[qty],
					ser.item_code,
					ser.item_desc

				into	#tmp_sumserialized

				FROM	#tmp_serialized		ser
				group by	ser.item_code,
							ser.item_desc
				--select 'a', * from #tmp_sumserialized




			--sumatoria de que se necesita serializar
			select	sum(isnull(sod.sod_qty,0) * tic.icomp_qty)	[qty],
					it.item_code,
					it.item_desc--,
					---
					--ISNULL((select sum(ser.qty) FROM #tmp_serialized ser where ser.item_code = it.item_code),0)
					--sod.sod_qty * tic.icomp_qty [qty1],
					--(select sum(ser.qty) FROM #tmp_serialized ser where ser.item_code = it.item_code) [qty]
					,
							ISNULL(tis.itst_PickingLocation,'')			[itst_PickingLocation],
							ISNULL(tis.itst_StorageLocation,'')			[itst_StorageLocation]
				INTO	#tmp_to_serialize
				FROM	dbo.tbSaleOrderDetail				sod	WITH (NOLOCK)
				INNER JOIN tbItemComposition		tic	WITH (NOLOCK)
					ON tic.comp_id = sod.comp_id
					AND tic.item_id = sod.item_id
				INNER JOIN dbo.tbItem				it	WITH (NOLOCK)
					ON 	it.comp_id	= sod.comp_id
					AND it.item_id	= tic.item_id_1
				LEFT JOIN tbItemStorage AS					tis	WITH (NOLOCK)
					ON	tis.comp_id = @comp_id		AND
						tis.stor_id = sod.stor_id	AND
						tis.item_id = sod.item_id

				where	sod.comp_id		= @comp_id
				and		sod.bra_id		= @bra_id
				and		sod.soh_id		= @soh_id
				and		it.item_expser  = 'true'
				--AND		sod.is_id		IS NULL
				GROUP BY	it.item_code, it.item_desc,tis.itst_PickingLocation,tis.itst_StorageLocation
				--, tic.icomp_qty
				--select 'b', * from #tmp_to_serialize




			select  isnull(tts.qty,0) - isnull(tss.qty,0)	[qty],
					isnull(tts.item_code,tss.item_code)		[item_code],
					isnull(tts.item_desc,tss.item_desc)		[item_desc],
					tts.itst_PickingLocation				[itst_PickingLocation],
					tts.itst_StorageLocation				[itst_StorageLocation]
					--tts.item_desc
				into	#tmp_pending_serialized1
				from	#tmp_to_serialize						tts
				FULL OUTER JOIN #tmp_sumserialized		tss		--Left join #tmp_sumserialized	tss
					ON	tts.item_code = tss.item_code
				--select 'c', * from #tmp_pending_serialized1	order by 2







			-- Retorna los items Pendientes de serializar y los numeros de serie que sobran.
			-- Esto puede pasar si se serializo un pedido con 5 items y luego lo modifican
			-- a 3 items, por lo que sobraran 2 items.  Si sobran, no se debe permitir cerrar
			-- el pedido.-
			SELECT	sum(CONVERT(DECIMAL(18,2),[qty]))	[qty],
					item_code,
					item_desc,
					itst_PickingLocation				[itst_PickingLocation],
					itst_StorageLocation	+ ' (3)'	[itst_StorageLocation]
				FROM	#tmp_pending_serialized1
				WHERE	[qty] > 0 OR [qty] < 0
				group by	item_code,
							item_desc,
							itst_PickingLocation,
							itst_StorageLocation




			--recuperamos los pendientes no serializables
			SELECT  CONVERT(DECIMAL(18,2),ISNULL(sod.sod_qty,0) * ISNULL(tic.icomp_qty,0))	[sod_qty],
					CONVERT(DECIMAL(18,2),ISNULL(sodt.sodt_qty,0))							[confirmed_qty],
  					it.item_code,
  					ISNULL(it.item_desc,sod.sod_itemDesc)									[item_desc]
				FROM	dbo.tbSaleOrderDetail				sod	WITH (NOLOCK)
				INNER JOIN tbItemComposition		tic	WITH (NOLOCK)
					ON	tic.comp_id		= sod.comp_id
					AND tic.item_id		= sod.item_id
				LEFT JOIN dbo.tbItem				it	WITH (NOLOCK)
					ON  it.comp_id		= sod.comp_id
					AND it.item_id		= tic.item_id_1
				LEFT JOIN dbo.tbSaleOrderDetailtmp	sodt	WITH (NOLOCK)
					on	sodt.comp_id	= sod.comp_id
					and sodt.bra_id		= sod.bra_id
					and sodt.soh_id		= sod.soh_id
					and sodt.sod_id		= sod.sod_id
					AND sodt.item_id	= tic.item_id_1
				WHERE 	sod.comp_id								=	@comp_id
				AND 	sod.bra_id								=	@bra_id
				AND 	sod.soh_id								=	@soh_id
				AND 	ISNULL(it.item_expser,'False')			=	'False'
				AND		ISNULL(sod.sod_qty * tic.icomp_qty,0)	<>	ISNULL(sodt.sodt_qty,0)


		END







END
GO








CREATE PROCEDURE [dbo].[spSaleOrderSerials_getDataByFilters2]
(
	@comp_id		int,
	@bra_id			int,
	@soh_id 		int
)
AS
SET NOCOUNT ON



BEGIN


	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
	/*
	Declare	@comp_id	INT,
  			@bra_id		INT,
  			@soh_id		INT

	Select	@comp_id	= 1,
  			@bra_id		= 1,
  			@soh_id		= 32628

	DROP TABLE #tmp_serialized
	*/
	-- -----------------------------------------------------------------------



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	SELECT 	it.item_code,
			it.item_desc,
			isnull(its.is_serial,'')	[is_serial]

	INTO	#tmp_serialized


	FROM	dbo.tbSaleOrderSerials				sose		WITH (NOLOCK)

			INNER JOIN dbo.tbItemSerials		its		WITH (NOLOCK)
			ON 	its.is_id	= sose.is_id

			INNER JOIN dbo.tbItem				it		WITH (NOLOCK)
			ON	it.comp_id	= sose.comp_id
			AND it.item_id	= its.item_id


	WHERE	sose.comp_id	= @comp_id
	AND 	sose.bra_id		= @bra_id
	AND 	sose.soh_id		= @soh_id



	SELECT * FROM #tmp_serialized


END
GO

CREATE PROCEDURE [dbo].[spSaleOrderSerials_ImportSerialsFromAnotherDocument]
(
	@comp_id		INT,
	@bra_id			INT,
	@df_id			INT,
	@docNumber		INT,
	@soh_id_Destino	INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@bra_id			INT,
				@df_id			INT,
				@docNumber		INT,
				@soh_id_Destino	INT
			SELECT
				@comp_id		= 1,
				@bra_id			= 1,
				@df_id			= 226,
				@docNumber		= 11,
				@soh_id_Destino = 82
		*/
		-- --------------------------------------------
		--RECUPERO EL BRA_ID DEL DF_ID



		DECLARE	@dfBra_Id	INT
		SELECT	@dfBra_Id =  df.bra_id
			FROM tbDocumentsFile		df		WITH (NOLOCK)
			WHERE	comp_id = @comp_id AND
					df_id	= @df_id


		DECLARE	@ct_transaction	INT = NULL

		SELECT TOP 1	@ct_transaction		= tct.ct_transaction
			FROM tbCommercialTransactions				tct			WITH (NOLOCK)
			WHERE	tct.comp_id			= @comp_id		AND
					tct.bra_id			= @dfBra_Id		AND
					tct.ct_docNumber	= @docNumber	AND
					tct.df_id			= @df_id


		IF @ct_transaction IS NULL RETURN	-- MOS 09-2024 x q tal vez sea esto lo q explota en newtree


		INSERT INTO tbSaleOrderSerials
		(
			comp_id,
			is_id,
			-- sose_id -- this column value is auto-generated,
			bra_id,
			soh_id--,
			--sose_guid
		)
		SELECT
			tits.comp_id,
			tits.is_id,
			@bra_id,
			@soh_id_Destino
			FROM tbItemTransactionSerials					tits			WITH (NOLOCK)
			INNER JOIN tbItemTransactions tit								WITH (NOLOCK)
				ON	tit.comp_id			= tits.comp_id AND
					tit.it_transaction	= tits.it_transaction
			WHERE	tits.comp_id		= @comp_id			AND
					tits.ct_transaction = @ct_transaction	AND
					-- Verifica que ya no este dado de alta este nro de serie en el pedido
					NOT EXISTS			(SELECT TOP 1 1
											FROM tbSaleOrderSerials						tsos2	WITH (NOLOCK)
											WHERE	tsos2.comp_id	= @comp_id			AND
													tsos2.bra_id	= @bra_id			AND
													tsos2.soh_id	= @soh_id_Destino	AND
													tsos2.is_id		= tits.is_id
										)
					AND
					---- Verifica que el pedido tenga ese Item Asociado.
					 EXISTS			(SELECT TOP 1 1
											FROM tbSaleOrderDetail						tsos3	WITH (NOLOCK)
											WHERE	tsos3.comp_id	= @comp_id			AND
													tsos3.bra_id	= @bra_id			AND
													tsos3.soh_id	= @soh_id_Destino	AND
													tsos3.item_id	= tit.item_id
										)

	END

GO







CREATE PROCEDURE [dbo].[spSaleOrderSerials_incrementSerials]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@soh_id					INT,
	@initialSerial			VARCHAR(200),
	@finalSerial			VARCHAR(200),
	@return_value			INT				OUTPUT,
	@ret_ErrorCode			INT 			OUTPUT,
	@ret_ErrorDescription	VARCHAR(200)	OUTPUT
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON

	-- --------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------
	/*
	Declare	@comp_id				INT,
			@lang_id				INT,
			@bra_id					INT,
			@soh_id					INT,
			@initialSerial			VARCHAR(200),
			@finalSerial			VARCHAR(200),
			@Guid					UNIQUEIDENTIFIER,
			@return_value			INT,
			@ret_ErrorCode			INT,
			@ret_ErrorDescription	VARCHAR(200)
	Select	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@soh_id				=32642,
			@initialSerial		='0000003670',
			@finalSerial		='0000003679'

	IF NOT OBJECT_ID('tempdb.dbo.#tmp_serialized')		IS NULL DROP TABLE #tmp_serialized
	IF NOT OBJECT_ID('tempdb.dbo.#tmp_serialized1')		IS NULL DROP TABLE #tmp_serialized1
	*/
	-- --------------------------------------------------------------------------





	Set		@return_value			= 0
	Set		@ret_ErrorCode			= 0
	Set		@ret_ErrorDescription	= ''


	DECLARE @item_IdFrom	INT
	DECLARE @item_IdTo		INT




	--validar que los números inicio y fin existan*
	--validar que los números inicio y fin estén libres*
	--validar que los números inicio y fin estén asociados al mismo artículo*
	--con el artículo asociado recuperar de la grilla de pendientes la cantidad
	--validar que entre inicio y fin (incluídos) haya la misma cantidad libres que la cantidad
	--de pendientes
	BEGIN TRY



		--====================================================================================================
		--recuperamos la longitud de la parte alfanumérica si es que la hubiera

		DECLARE @posInitial INT
		SET		@posInitial = LEN(@initialSerial)

		--SELECT SUBSTRING(@initialSerial, @posInitial, 1)
		WHILE not ISNUMERIC(SUBSTRING(@initialSerial, @posInitial,1)) =0
		BEGIN
			SET @posInitial = @posInitial - 1
		END
		SET @posInitial = @posInitial + 1

		DECLARE @posFinal INT
		SET		@posFinal = LEN(@finalSerial)

		WHILE not ISNUMERIC(SUBSTRING(@finalSerial, @posFinal,1)) =0
		BEGIN
			SET @posFinal = @posFinal - 1
		END
		SET @posFinal = @posFinal + 1

		--SELECT @posInitial, @posFinal
		--====================================================================================================




		--====================================================================================================
		--Ejecutamos el sp que recupera los seriales recuperados en la migración
		DECLARE @intIndex			INT
		DECLARE @intSerialsQty		INT
		DECLARE @nextSerial			VARCHAR(200)


		SET 	@intSerialsQty		=	CONVERT (BIGINT ,SUBSTRING(@finalSerial,@posFinal,	  LEN(@finalSerial)	  - @posFinal + 1)) -
										CONVERT (BIGINT ,SUBSTRING(@initialSerial,@posInitial,LEN(@initialSerial) - @posFinal + 1))	 -- TN: 391


		SET		@intIndex			= 0
		WHILE (@intIndex <= @intSerialsQty)
  		BEGIN

  			SET @nextSerial  = dbo.fnGetSerialNumber4Incremental(@initialSerial,@intIndex)
			--SELECT @nextSerial

  			SET @intIndex	= @intIndex + 1

			EXEC [spItemSerialsFromOtherERP_UpdateSerial] @comp_id,	@bra_id	,@soh_id ,@nextSerial

  		END
		--====================================================================================================




		DECLARE @tmpItemIds AS TABLE (item_id INT)
		INSERT INTO @tmpItemIds (item_id)
		SELECT	DISTINCT CASE
							WHEN tdf.sd_id = 80 THEN tic.item_id_1
							ELSE tsod.item_id
	      				 END
		FROM	tbSaleOrderHeader				tsoh			WITH (NOLOCK)
				INNER JOIN tbSaleOrderDetail	tsod			WITH (NOLOCK)
				ON	tsod.soh_id = tsoh.soh_id
				INNER JOIN tbDocumentsFile		tdf				WITH (NOLOCK)
				ON	tdf.df_id	= tsoh.df_id
				LEFT JOIN tbItemComposition		tic				WITH (NOLOCK)
				ON	tic.item_id	= tsod.item_id
		WHERE	tsoh.comp_id	= @comp_id	AND
				tsoh.bra_id		= @bra_id	AND
				tsoh.soh_id		= @soh_id     -- El muy hijo de mil putas habia puesto de filtro solo esto !!!!!
		--SELECT * FROM @tmpItemIds





  		--validar que los números inicio y fin existan y recuperar el item_id correspondiente
  		SELECT	@item_IdFrom	= tis.item_id
			FROM	tbItemSerials	tis		WITH (NOLOCK),
					@tmpItemIds		tmpII
			WHERE	tis.is_serial   = @initialSerial
			AND		tis.item_id		= tmpII.item_id


  		SELECT	@item_IdTo		= tis.item_id
			FROM	tbItemSerials	tis		WITH (NOLOCK),
					@tmpItemIds		tmpII
			WHERE	tis.is_serial   = @finalSerial
			AND		tis.item_id		= tmpII.item_id








		IF @item_IdFrom IS NULL
  			BEGIN
  				SET @return_value = -2
  				SET @ret_ErrorCode =-2

  				SELECT	@ret_ErrorDescription = tut.utexts_desc
					FROM	tbsysUniqueTexts tut			WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id
					AND		tut.utexts_id	= 22406

  				RETURN
  			END
  		--SELECT @item_IdFrom , @item_IdTo





  		--validar que los números inicio y fin estén asociados al mismo artículo
  		-- NOTA: se puede resumir con el punto 1
  		IF (@item_IdFrom <> @item_IdTo)
  			BEGIN
  				SET @return_value = -3
  				SET @ret_ErrorCode =-3

  				SELECT @ret_ErrorDescription = tut.utexts_desc
  					FROM tbsysUniqueTexts tut			WITH (NOLOCK)
  					WHERE	tut.lang_id		= @lang_id
  						AND tut.utexts_id	= 22407
  				RETURN
  			END




  		/*********************************************************************************************************************************/
		--==OJO
		-- Vericicar aca que si la funcion [fnGetIsItemSerial4DifStorage] es true,
		-- todos los items del pedido deben tener el mismo deposito, sino rtetornar error
		DECLARE @stor_id					INT
		DECLARE @bitForceStorageOfSerial AS BIT = 'True'	-- MOS 05-2023: Para que si usa nros de dif sucursales, NO actualice el deposito del nro de serie del pedido **ejknf239847asdknqlkn2432
  		IF dbo.fnGetIsItemSerial4DifStorage(@comp_id,@bra_id) = 'true'
  			BEGIN

	--==
	--SELECT ' Dif Deposito Activo'
	--==



  				SELECT	COUNT(*) [cantidad], tsod.stor_id
  					FROM	tbSaleOrderDetail tsod				WITH (NOLOCK)
  					INNER JOIN tbItem ti						WITH (NOLOCK)
  						ON		ti.comp_id		= tsod.comp_id
  							AND ti.item_id		= tsod.item_id
  							AND ti.item_expser	= 'True'
  					WHERE	tsod.comp_id	= @comp_id
	  					AND	tsod.bra_id		= @bra_id
  						AND	tsod.soh_id		= @soh_id
  					GROUP BY tsod.stor_id



  				IF @@ROWCOUNT > 1 --significa que hay más de un stor_id en los artículos del pedido
  					BEGIN

  							SET @bitForceStorageOfSerial = 'False'	-- MOS 05-2023

  							SELECT TOP 1 @stor_id = tsod.stor_id
  								FROM	tbSaleOrderDetail tsod				WITH (NOLOCK)
  								WHERE	tsod.comp_id	= @comp_id
  									AND	tsod.bra_id		= @bra_id
  									AND	tsod.soh_id		= @soh_id
  									AND tsod.item_id IS NOT NULL
  								GROUP BY tsod.stor_id
  							-- MOS 05-20233
  							--SET @return_value = -6
  							--SET @ret_ErrorCode =-6

  							--SELECT @ret_ErrorDescription = tut.utexts_desc
  							--	FROM tbsysUniqueTexts tut			WITH (NOLOCK)
  							--	WHERE	tut.lang_id		= @lang_id
  							--		AND tut.utexts_id	= 22410

  							--RETURN
  					END

  				ELSE

  					BEGIN
  							SELECT TOP 1 @stor_id = tsod.stor_id
  								FROM	tbSaleOrderDetail tsod				WITH (NOLOCK)
  								WHERE	tsod.comp_id	= @comp_id
  									AND	tsod.bra_id		= @bra_id
  									AND	tsod.soh_id		= @soh_id
  									AND tsod.item_id IS NOT NULL
  								GROUP BY tsod.stor_id
  					END

  			END
  		ELSE		-- Deposito del Pedido
  			BEGIN
				SELECT	Top 1 @stor_id  = tsod.stor_id
					FROM	tbSaleOrderDetail tsod						WITH (NOLOCK)
					WHERE	tsod.comp_id	= @comp_id
						AND	tsod.bra_id		= @bra_id
						AND	tsod.soh_id		= @soh_id
						AND tsod.item_id IS NOT NULL
					GROUP BY tsod.stor_id
  			END
		/*********************************************************************************************************************************/



		--con el artículo asociado recuperar de la grilla de pendientes, la cantidad



		/*****************************************************************************************	*/
		-- obtenemos el sd_id del pedido para determinar si es un pedido de producción o no
		DECLARE @sd_id integer

		SELECT	@sd_id = tdf.sd_id

		FROM	tbSaleOrderHeader				tsoh			WITH (NOLOCK)

				INNER JOIN tbDocumentsFile		tdf				WITH (NOLOCK)
				ON	tdf.comp_id = tsoh.comp_id
				AND tdf.df_id	= tsoh.df_id

		WHERE		tsoh.comp_id	= @comp_id
			AND		tsoh.bra_id		= @bra_id
			AND		tsoh.soh_id		= @soh_id


		--==
		--SELECT	@sd_id		[sd_id],			@stor_id	[stor_id]
		--==
		/*****************************************************************************************	*/




		DECLARE @lCant INT




		IF @sd_id <> 80	--artículos que NO componen otro artículo
			BEGIN


			--==
			--SELECT 'GENERACION DE TEMPORAL'


				--se recupera la cantidad de lo que ya está serializado para el pedido y para el
				--artículo correspondiente
				SELECT 	' '												[ ],
						1												[qty],
						it.item_code,
						it.item_desc,
						its.is_serial,
						convert(varchar, sose.is_id) + '-' +
						convert(varchar, sose.sose_id)					[ID]

				INTO	#tmp_serialized

				FROM 	dbo.tbSaleOrderSerials					sose		WITH (NOLOCK)

						INNER JOIN dbo.tbItemSerials			its			WITH (NOLOCK)
						ON 		its.comp_id     = @comp_id
						AND		its.is_id		= sose.is_id

						INNER JOIN dbo.tbItem					it			WITH (NOLOCK)
						ON 		it.comp_id		= sose.comp_id
						AND 	it.item_id		= its.item_id

				WHERE	sose.comp_id			= @comp_id
				AND 	sose.bra_id				= @bra_id
				AND 	sose.soh_id				= @soh_id
				AND		its.item_id				= @item_IdFrom
				AND 	it.item_expser		    = 'true'

				--==
				--SELECT 1,* FROM #tmp_serialized
				--==


				--recuperar la cantidad pendiente del pedido y para el artículo correspondiente
				SET @lCant =	(
								SELECT	SUM(sod.sod_qty) -
										ISNULL((SELECT SUM(ser.qty)	FROM #tmp_serialized ser),0)

								FROM	dbo.tbSaleOrderDetail				sod			WITH (NOLOCK)

										INNER JOIN dbo.tbItem				it			WITH (NOLOCK)
										ON	it.comp_id		= sod.comp_id
										AND it.item_id		= sod.item_id

										INNER JOIN tbItemSerials			tis			WITH (NOLOCK)
										ON  tis.comp_id		= sod.comp_id
										AND tis.item_id		= sod.item_id
										AND tis.is_serial	= @initialSerial

								WHERE 	sod.comp_id			= @comp_id
								AND 	sod.bra_id			= @bra_id
								AND 	sod.soh_id			= @soh_id
								AND     it.item_id			= @item_IdFrom
								AND 	it.item_expser		= 'true'

								GROUP BY	it.item_code,
											it.item_desc
				)


				--==
				--SELECT @lCant
				--==

			END

		ELSE

			--artículos que componen otro artículo
			BEGIN

				--se recupera la cantidad de lo que ya está serializado para el pedido y para el
				--artículo correspondiente
				SELECT 	' '												[ ],
						1												[qty],
						it.item_code,
						it.item_desc,
						its.is_serial,
						convert(varchar, sose.is_id) + '-' +
						convert(varchar, sose.sose_id)					[ID]

				INTO	#tmp_serialized1

				FROM 	dbo.tbSaleOrderSerials					sose		WITH (NOLOCK)

						INNER JOIN dbo.tbItemSerials			its			WITH (NOLOCK)
						ON 		its.comp_id     = @comp_id
						AND		its.is_id		= sose.is_id

						INNER JOIN dbo.tbItem					it			WITH (NOLOCK)
						ON 		it.comp_id		= sose.comp_id
						AND 	it.item_id		= its.item_id

				WHERE	sose.comp_id			= @comp_id
				AND 	sose.bra_id				= @bra_id
				AND 	sose.soh_id				= @soh_id
				AND		its.item_id				= @item_IdFrom
				AND 	it.item_expser		    = 'true'

				--SELECT * FROM #tmp_serialized1


				--recuperar la cantidad pendiente del pedido y para el artículo correspondiente
				SET @lCant =	(
								SELECT (SUM(sod.sod_qty) * tic.icomp_qty) -
										ISNULL((SELECT SUM(ser.qty) FROM #tmp_serialized1 ser),0)

								FROM	dbo.tbSaleOrderDetail				sod		WITH (NOLOCK)

										INNER JOIN tbItemComposition		tic		WITH (NOLOCK)
										ON  tic.comp_id		= sod.comp_id
										AND tic.item_id		= sod.item_id

										INNER JOIN dbo.tbItem				it		WITH (NOLOCK)
										ON	it.comp_id		= sod.comp_id
										AND it.item_id		= tic.item_id_1

										INNER JOIN tbItemSerials			tis		WITH (NOLOCK)
										ON  tis.comp_id		= sod.comp_id
										AND tis.item_id		= tic.item_id_1
										AND tis.is_serial	= @initialSerial

								WHERE 	sod.comp_id			= @comp_id
								AND 	sod.bra_id			= @bra_id
								AND 	sod.soh_id			= @soh_id
								AND     it.item_id			= @item_IdFrom
								AND 	it.item_expser		= 'true'

								GROUP BY	it.item_code,
											it.item_desc,
											tic.icomp_qty
								)

				--SELECT @lCant [@lCant]
			END





		-- ---------------------------------------
		-- Calculo del total de numeros a Generar
		-- ---------------------------------------
		declare @intLen			AS INT
		declare @strLen			AS NVARCHAR(100)
		declare @intValorI		AS INT
		declare @intValorF		AS INT
		declare @intDif			AS INT
		--SET @intTotalLen			= LEN(@strOriginalSerialNumber)
		--set @nIncrementFromOriginal = @nIncrementFromOriginal - 1
		set @intLen		= dbo.fnGetLenSerTrueNumber(@initialSerial)    --//Len(aStr(nCant))+2
		set @strLen		= Right(@initialSerial,@intLen)
		set @intValorI	= CONVERT(int,@strLen)
		set @intLen		= dbo.fnGetLenSerTrueNumber(@finalSerial)    --//Len(aStr(nCant))+2
		set @strLen		= Right(@finalSerial,@intLen)
		set @intValorF	= CONVERT(int,@strLen)
		SET @intDif = @intValorF - @intValorI + 1
		-- ---------------------------------------







		--validar que entre inicio y fin (incluídos) haya la misma cantidad libres que la cantidad
		--de pendientes
		DECLARE @lis_id			INT
		DECLARE @intCounter		INT
		SET		@intCounter	= 0
		DECLARE @newSerial		VARCHAR(200)





		--verifica que los seriales que va a generar existan en tbItemSerials
		--SELECT	@intCounter [@intCounter], @lCant [@lCant], @intCounter [@intCounter], @intDif [@intDif]

		WHILE ((@intCounter < @lCant) AND (@intCounter < @intDif))
  		BEGIN
  			SET @newSerial  = dbo.fnGetSerialNumber4Incremental(@initialSerial,@intCounter)
  			SET @intCounter	= @intCounter+1


  			-- Si NO EXISTE el numero de serie
  			IF NOT EXISTS(SELECT TOP 1  1
  						  FROM   dbo.tbItemSerials tis			WITH (NOLOCK)
  						  WHERE  tis.comp_id	= @comp_id
  						  AND    tis.is_serial  = @newSerial
  						  AND	 tis.is_available = 'true'
  						 )
  			BEGIN
  				SET @return_value = -4
  				SET @ret_ErrorCode =-4

  				SELECT @ret_ErrorDescription = isnull(tut.utexts_desc,'')
  					FROM tbsysUniqueTexts tut			WITH (NOLOCK)
  					WHERE   tut.lang_id   = @lang_id
  						AND tut.utexts_id = 22408

				--SELECT @ret_ErrorDescription
  				RETURN
  			END
  		END


		--==
		--SELECT 'aCA lLEGA'
		--SELECT @lCant [@lCant], @intDif [@intDif]
		--==



  		--se verifica que la cantidad de seriales a generar por el rango ingresado sea igual o menor que la cantidad
  		--de ìtems pendientes de serialización en el pedido
  		IF (@lCant >= @intDif)
  		BEGIN

			--SELECT 'llego'

			--si pasaron todas las validaciones se debe actualizar tbSaleOrderSerial con lis is_id de tbItemSerials
			SET @intCounter = 0



			WHILE ((@intCounter < @lCant) AND (@intCounter < @intDif))
  			BEGIN

  				SET @newSerial	= dbo.fnGetSerialNumber4Incremental(@initialSerial,@intCounter)
  				SET @intCounter	= @intCounter+1



				/**************************************************************************************************************************/
				--==OJO
				-- Verificar aca que el numero de serie sea del mismo deposito que el pedido !!!!!!!!!!!!!!
				-- si la funcion [fnGetIsItemSerial4DifStorage] es false   sod.stor_id = itemserial.stor_id del @newSerial si no es igual no
				-- hacer ni el insert ni el update posterior


				--SELECT dbo.fnGetIsItemSerial4DifStorage(@comp_id,@bra_id) [fnGetIsItemSerial4DifStorage]
				--si la funcion [fnGetIsItemSerial4DifStorage] es true en el update poner el deposito del tbsaleorderdetail.stor_id
		 		IF dbo.fnGetIsItemSerial4DifStorage(@comp_id,@bra_id) = 'false'	-- Si El Deposito del NUmero de serie debe ser el MISMO que el del pedido, (segun sucursal), verifica eso y lo incorpora.-
		 			BEGIN

		 				--SELECT 'a'
					--==
					--SELECT '*1',@newSerial, @intCounter,@stor_id,'**'
					--==


		 				IF EXISTS (SELECT TOP 1 	1
		 						   FROM		tbItemSerials				tis		WITH (NOLOCK)
		 						   WHERE	tis.comp_id		= @comp_id
		 						   AND		tis.is_serial	= @newSerial
		 						   AND		tis.item_id		= @item_IdFrom
		 						   AND		tis.stor_id		= @stor_id
		 							)
		 					BEGIN

								-- Se inserta el numero generado en tbSaleOrderSerials
  								INSERT INTO tbSaleOrderSerials
  								(
  									comp_id,
  									is_id,
  									bra_id,
  									soh_id,
  									sose_guid
  								)
  								SELECT	@comp_id,
  										tis.is_id,
  										@bra_id,
  										@soh_id,
  										NULL
								FROM	tbItemSerials tis			WITH (NOLOCK)
								WHERE	tis.comp_id			= @comp_id
								AND		tis.is_serial		= @newSerial
								AND		tis.item_id			= @item_IdFrom
								AND		tis.is_available	= 'true'
								--AND	tis.bra_id			= @bra_id   NOOOO  MOS, 10-2011



								-- Se pone el numero sde serie como NO DISPONIBLE
								UPDATE	tbItemSerials

								SET		is_available	= 'false'

								WHERE	comp_id			= @comp_id
								AND		is_serial		= @newSerial
								AND		item_id			= @item_IdFrom
								AND		is_available	= 'true'


		 					END


		 			END
		 		ELSE
		 			BEGIN

						--SELECT 'b'


						-- Se inserta el numero generado en tbSaleOrderSerials (Idem Arriba)
						INSERT INTO tbSaleOrderSerials
						(
							comp_id,
							is_id,
							bra_id,
							soh_id,
							sose_guid
						)
						SELECT	@comp_id,
								tis.is_id,
								@bra_id,
								@soh_id,
								NULL
						FROM	tbItemSerials tis			WITH (NOLOCK)
						WHERE	tis.comp_id			= @comp_id
						AND		tis.is_serial		= @newSerial
						AND		tis.item_id			= @item_IdFrom
						AND		tis.is_available	= 'true'
						--AND	tis.bra_id			= @bra_id   NOOOO  MOS, 10-2011



						-- Se pone el numero sde serie como NO DISPONIBLE
						-- Ademas fuerza el numero de deposito del numero de serie al deposito del pedido.-
						IF @bitForceStorageOfSerial = 'True'
							BEGIN
								UPDATE	tbItemSerials
									SET		is_available	= 'false',
											stor_id			= @stor_id
									WHERE	comp_id			= @comp_id
									AND		is_serial		= @newSerial
									AND		item_id			= @item_IdFrom
									AND		is_available	= 'true'
							END
						ELSE
							BEGIN
								UPDATE	tbItemSerials
									SET		is_available	= 'false'
									WHERE	comp_id			= @comp_id
									AND		is_serial		= @newSerial
									AND		item_id			= @item_IdFrom
									AND		is_available	= 'true'
							END



			 			-- Ademas fuerza el numero de deposito del numero de serie al deposito del pedido.-
						/*UPDATE	tbItemSerials
							SET		is_available	= 'false',
									stor_id			= @stor_id
							--SELECT * FROM tbItemSerials
							WHERE	comp_id			= @comp_id
							AND		is_serial		= @newSerial
							AND		item_id			= @item_IdFrom*/


		 			END






  			END





  		END

  		ELSE

  		BEGIN

			SET @return_value = -5
			SET @ret_ErrorCode =-5

			SELECT	@ret_ErrorDescription = isnull(tut.utexts_desc,'')
			FROM	tbsysUniqueTexts tut
			WHERE   tut.lang_id   = @lang_id
			AND		tut.utexts_id = 224018

			RETURN

  		END

	END TRY
	BEGIN CATCH




		--DECLARE @internalError VARCHAR(8000)

		--SET @internalError = (SELECT
		--		convert(varchar,ERROR_NUMBER())		+ '-' +
		--		convert(varchar,ERROR_SEVERITY())	+ '-' +
		--		convert(varchar,ERROR_STATE())		+ '-' +
		--		convert(varchar,ERROR_LINE())		+ '-' +
		--		ERROR_MESSAGE())
		SET @return_value = -1
		SET @ret_ErrorCode =-1

		SELECT	@ret_ErrorDescription = isnull(tut.utexts_desc,'t')
		FROM	tbsysUniqueTexts tut		WITH (NOLOCK)
		WHERE	tut.lang_id   = @lang_id
		AND		tut.utexts_id = 22411 --error inesperado

		--SET @ret_ErrorDescription = @ret_ErrorDescription + '-' + @internalError


		RETURN

	END CATCH


	--SELECT @return_value, @ret_ErrorDescription

END
GO








CREATE PROCEDURE [dbo].[spSaleOrderSerials_insertData]
(
    @comp_id		as  int,
	@is_id			as  int,
	@bra_id			as	int,
	@soh_id			as	int,
	@sose_guid		as	uniqueidentifier,
	@return_value	as	int output
)
as

set nocount on


insert into dbo.tbSaleOrderSerials
	(comp_id,   is_id,  bra_id,  soh_id,  sose_guid)
values
	(@comp_id,  @is_id, @bra_id, @soh_id, @sose_guid)

--Cambio el estado de soh_isediting
		Update	dbo.tbSaleOrderHeader

			Set  soh_isEditing	= 'true'
				Where  comp_id		= @comp_id
					and	bra_id		= @bra_id
					and	soh_id		= @soh_id

set @return_value = @@identity



GO




-- Desc : PAGINA (00093) Artículos No Serializables ( Según Depósitos por Perfil ) - Boton Confirmar Todos
-- Date : 12/08/2020
--

CREATE PROCEDURE [dbo].[spSaleOrderSerialsNS_ConfirmAll]
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@prof_id			INT,
	@user_id			INT,
	@soh_id 			INT

)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON



	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
	declare
			@comp_id			int,
			@lang_id			int,
			@bra_id				int,
			@prof_id			INT,
			@user_id			INT,
			@soh_id 			INT




	select	@comp_id	= 1,
			@bra_id		= 42,
			@soh_id		= 31329,
			@user_id	= 4,
			@prof_id	= 1
*/
	-- -----------------------------------------------------------------------


			INSERT INTO tbSaleOrderDetailtmp (	comp_id,
												bra_id,
												soh_id,
												sod_id,
												sodt_qty,
												item_id,
												sodt_sod_qty)
				SELECT	tsod.comp_id,
						tsod.bra_id,
						tsod.soh_id,
						tsod.sod_id,
						tsod.sodt_qty,
						tsod.item_id ,
						tsod.sod_qty
					FROM tbSaleOrderDetail			  tsod			WITH (NOLOCK)
					LEFT JOIN tbSaleOrderDetailtmp AS tsodT			WITH (NOLOCK)
						ON	tsodT.comp_id	= tsod.comp_id	AND
							tsodT.bra_id	= tsod.bra_id	AND
							tsodT.soh_id	= tsod.soh_id	AND
							tsodT.sod_id	= tsod.sod_id
					LEFT JOIN tbItem			   AS ti			WITH (NOLOCK)
						ON	ti.comp_id		= tsod.comp_id  AND
							ti.item_id		= tsod.item_id
					WHERE	tsod.comp_id	= @comp_id		AND
							tsod.bra_id		= @bra_id		AND
							tsod.soh_id		= @soh_id		AND
							tsod.sodt_qty   IS NOT NULL		AND
							tsodT.comp_id   IS NULL			AND
							ti.comp_id      IS NOT NULL     AND
							ti.item_expser  = 'False'



	UPDATE tbSaleOrderDetailtmp			WITH (rowlock)
		SET	sodt_qty = sodt_sod_qty
		FROM tbSaleOrderDetailtmp tmp
		LEFT JOIN tbItem AS ti			WITH (NOLOCK)
		ON	ti.comp_id	= tmp.comp_id AND
			ti.item_id	= tmp.item_id
		WHERE	tmp.comp_id = @comp_id	AND
				tmp.bra_id	= @bra_id	AND
				tmp.soh_id	= @soh_id	AND
				ISNULL(ti.item_expser,'False') = 'False'


END
GO



-- Log
-- MOS 06-2024: 					ISNULL(it.item_expLote,'False')						[item_expLote],	-- Count - 3

-- Serializacion de pedidos, pagina 93
CREATE PROCEDURE [dbo].[spSaleOrderSerialsNS_getDataByFilters]
(
	@comp_id			int,
	@bra_id				int,
	@soh_id 			INT,
	@user_id			INT,
	@prof_id			INT
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON



	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
	declare	@comp_id	int,
			@bra_id		int,
			@soh_id		int,
	@user_id			INT,
	@prof_id			INT
	select	@comp_id	= 1,
			@bra_id		= 42,
			@soh_id		= 31329,
			@user_id	= 4,
			@prof_id	= 1
*/
	-- -----------------------------------------------------------------------






	-- -----------------------------------------------------------------------------
	-- Marca como Preparados a los que NO necesitan preparacion
	-- -----------------------------------------------------------------------------
	DECLARE @curSOD_ID	AS INT
	DECLARE @curItemID	AS INT
	DECLARE @curQTY		AS DECIMAL(19,4)
	DECLARE sodCursor CURSOR LOCAL  FAST_FORWARD FOR
	SELECT tsod.sod_id, tsod.item_id, tsod.sod_qty
		FROM tbSaleOrderDetail tsod		WITH (NOLOCK)
		LEFT JOIN tbItem ti				WITH (NOLOCK)
			ON	ti.comp_id = tsod.comp_id AND
				ti.item_id = tsod.item_id
		WHERE	tsod.comp_id	= @comp_id	AND
				tsod.bra_id		= @bra_id	AND
				tsod.soh_id		= @soh_id	AND
				CASE
					WHEN ti.comp_id IS NOT NULL AND  ti.item_NoStockCheck = 'True'	THEN 1
					WHEN tsod.sod_isFromPCConfigCTRLId = 99							THEN 1
					WHEN tsod.sod_isParentAssociate = 'True'						THEN 1
					ELSE																 0
				END = 1
	OPEN		sodCursor
	FETCH NEXT FROM sodCursor INTO @curSOD_ID, @curItemID, @curQTY
	WHILE @@FETCH_STATUS = 0
		BEGIN

			EXEC spSaleOrderDetailtmp_insertData4NoStockItems	@comp_id,
																@bra_id,
																@soh_id,
																@curSOD_ID,
																@curItemID,
																@curQTY
			FETCH NEXT FROM sodCursor INTO @curSOD_ID, @curItemID, @curQTY

		END
	CLOSE		sodCursor
	DEALLOCATE	sodCursor
	-- -----------------------------------------------------------------------------






	-- -----------------------------------------------------------------------------
	-- Carga UNICAMENTE  los depositos q le correspondan
	-- -----------------------------------------------------------------------------
	DECLARE @tmpStorage  TABLE(stor_id INT NULL, UNIQUE NONCLUSTERED (stor_id) )
	IF EXISTS(	SELECT TOP 1  1
	          		FROM tbStorage4Profile tsp		WITH (NOLOCK)
	          		WHERE	tsp.comp_id = @comp_id AND
	          				tsp.prof_id = @prof_id)
		BEGIN	-- Todos los depositos q tiene definidos x perfil
			INSERT INTO @tmpStorage(stor_id)
				SELECT tsp.stor_id
					FROM tbStorage4Profile tsp		WITH (NOLOCK)
	          			WHERE	tsp.comp_id = @comp_id AND
	          					tsp.prof_id = @prof_id
		END
	ELSE
		BEGIN
			INSERT INTO @tmpStorage(stor_id)	-- Todos los depositos
				SELECT ts.stor_id FROM tbStorage ts
		END

	-- Inserta el deposito NULL para loa articulos manuales.!
	-- Inserta el deposito NULL para loa articulos manuales.!
	IF NOT EXISTS(SELECT TOP 1  1 FROM @tmpStorage WHERE stor_id IS null)
		BEGIN
			INSERT INTO @tmpStorage(stor_id) VALUES (NULL)
		END
	-- Inserta el deposito NULL para loa articulos manuales.!
	IF NOT EXISTS(SELECT TOP 1  1 FROM @tmpStorage WHERE stor_id = 0)
		BEGIN
			INSERT INTO @tmpStorage(stor_id) VALUES (0)
		END
	-- -----------------------------------------------------------------------------




	IF NOT EXISTS(
					SELECT TOP 1  1
						FROM tbSaleOrderDetailtmp tsod		WITH (NOLOCK)
						WHERE	tsod.comp_id	= @comp_id	AND
								tsod.bra_id		= @bra_id	AND
								tsod.soh_id		= @soh_id
				)
		BEGIN
			INSERT INTO tbSaleOrderDetailtmp (	comp_id,
												bra_id,
												soh_id,
												sod_id,
												sodt_qty,
												item_id,
												sodt_sod_qty)
				SELECT	tsod.comp_id,
						tsod.bra_id,
						tsod.soh_id,
						tsod.sod_id,
						tsod.sodt_qty,
						tsod.item_id ,
						tsod.sod_qty
					FROM tbSaleOrderDetail tsod			WITH (NOLOCK)
					WHERE	tsod.comp_id	= @comp_id	AND
							tsod.bra_id		= @bra_id	AND
							tsod.soh_id		= @soh_id	AND
							tsod.sodt_qty   IS NOT NULL

		END





	-- obtenemos el sd_id del pedido para determinar si es un pedido de producción o no
	DECLARE @sd_id integer

	SELECT	@sd_id = tdf.sd_id

	FROM	tbSaleOrderHeader				tsoh		WITH (NOLOCK)

			INNER JOIN tbDocumentsFile		tdf			WITH (NOLOCK)
			ON	tdf.comp_id = tsoh.comp_id
			AND tdf.df_id	= tsoh.df_id

	WHERE	tsoh.comp_id	= @comp_id
	AND		tsoh.bra_id		= @bra_id
	AND		tsoh.soh_id		= @soh_id
	--SELECT @sd_id




	IF @sd_id <> 80
		BEGIN

			select	'' [ ], '' [ ], '' [ ],
					convert(decimal(18,2), sod.sod_qty)					[qty],
					convert(decimal(18,2),isnull(sodt.sodt_qty,0))		[confirmed_qty],
					isnull(it.item_code,'')								[item_code],
					ISNULL(it.item_desc,sod.sod_itemDesc)				[item_desc],
					isnull(tis.itst_StorageLocation,'')					[itst_StorageLocation],
					dbo.fnGetStockOfStorageGroup(sod.comp_id, sod.stor_id, sod.item_id)	[PhisicalStock],
					ts.stor_desc,
					tov.optval_desc										[sod_DeliveryMethod],
					sod.sod_itemDeliveryDate,


					-- Agregar todo antes de esta linea
					ISNULL(it.item_expLote,'False')						[item_expLote],	-- Count - 3
					isnull(it.item_expean, 'False')						[item_expean],  -- COUNT - 2
					convert(varchar, sod.comp_id) + '-' +
					convert(varchar, sod.bra_id)  + '-' +
					convert(varchar, sod.sod_id)  + '-' +
					convert(varchar, sod.soh_id)  + '-' +
					convert(varchar, isnull(sod.item_id,0))				[ID]	-- COUNT - 1



			from	dbo.tbSaleOrderDetail				sod	WITH (NOLOCK)

					INNER JOIN tbBranch AS tb	WITH (NOLOCK)
					ON	tb.comp_id		= sod.comp_id AND
						tb.bra_id		= sod.bra_id
					INNER JOIN @tmpStorage tmps
						ON tmps.stor_id = sod.stor_id
							OR
						 ( tmps.stor_id IS NULL AND sod.stor_id IS NULL )

					LEFT JOIN dbo.tbItem				it	WITH (NOLOCK)
					on	it.comp_id		= sod.comp_id
					and	it.item_id		= sod.item_id

					LEFT JOIN dbo.tbSaleOrderDetailtmp	Sodt	WITH (NOLOCK)
					on	sodt.comp_id	= sod.comp_id
					and sodt.bra_id		= sod.bra_id
					and sodt.soh_id		= sod.soh_id
					and sodt.sod_id		= sod.sod_id

					left JOIN tbItemStorage				tis	WITH (NOLOCK)
					on  tis.comp_id		= sod.comp_id
					and tis.stor_id		= sod.stor_id
					AND tis.item_id		= sod.item_id

					LEFT JOIN tbStorage ts	WITH (NOLOCK)
					ON	ts.comp_id = tis.comp_id AND
						ts.stor_id = tis.stor_id

					LEFT JOIN tbsysOptionsValues AS tov
						ON	tov.lang_id			= tb.lang_id	AND
							tov.optval_class	= 520			AND
							tov.optval_id		= sod.sdlmt_id

			where	sod.comp_id		= @comp_id
			and		sod.bra_id		= @bra_id
			and		sod.soh_id		= @soh_id
			and		isnull(it.item_expser,'False')  = 'False'	--AND
					--it.item_NoStockCheck = 'False'

			order by	it.item_desc,
						tis.itst_StorageLocation


		END
	ELSE
		BEGIN


			SELECT	'' [ ], '' [ ], '' [ ],
					CONVERT(DECIMAL(18,2), sod.sod_qty * tic.icomp_qty)		[qty],
					CONVERT(DECIMAL(18,2), ISNULL(sodt.sodt_qty,0))			[confirmed_qty],
					ISNULL(it.item_code, '')								[item_code],
					ISNULL(it.item_desc,sod.sod_itemDesc)					[item_desc],
					ISNULL(tis.itst_StorageLocation,'')						[itst_StorageLocation],

					dbo.fnGetStockOfStorageGroup(sod.comp_id, sod.stor_id, sod.item_id)	[PhisicalStock],
					ts.stor_desc,
					tov.optval_desc											[sod_DeliveryMethod],
					sod.sod_itemDeliveryDate,

					-- Agregar todo antes de esta linea
					ISNULL(it.item_expLote,'False')							[item_expLote],	-- Count - 3
					isnull(it.item_expean, 'False')							[item_expean],	-- COUNT - 2
					CONVERT(VARCHAR, sod.comp_id) + '-' +
					CONVERT(VARCHAR, sod.bra_id)  + '-' +
					CONVERT(VARCHAR, sod.sod_id)  + '-' +
					CONVERT(VARCHAR, sod.soh_id)  + '-' +
					CONVERT(VARCHAR, isnull(tic.item_id_1,0))				[ID]		-- COUNT - 1


			FROM 	dbo.tbSaleOrderDetail				sod	WITH (NOLOCK)

					INNER JOIN tbBranch AS tb	WITH (NOLOCK)
					ON	tb.comp_id		= sod.comp_id AND
						tb.bra_id		= sod.bra_id

					INNER JOIN tbItemComposition		tic	WITH (NOLOCK)
					ON	tic.comp_id = sod.comp_id
					AND tic.item_id = sod.item_id

					INNER JOIN dbo.tbItem				it	WITH (NOLOCK)
					ON	it.comp_id	= sod.comp_id
					AND	it.item_id	= tic.item_id_1

					LEFT JOIN dbo.tbSaleOrderDetailtmp	Sodt	WITH (NOLOCK)
					ON	sodt.comp_id	= sod.comp_id
					AND sodt.bra_id		= sod.bra_id
					AND sodt.soh_id		= sod.soh_id
					AND sodt.sod_id		= sod.sod_id
					AND Sodt.item_id	= tic.item_id_1

					LEFT JOIN tbItemStorage				tis	WITH (NOLOCK)
					ON  tis.comp_id		= sod.comp_id
					AND tis.stor_id		= sod.stor_id
					AND tis.item_id		= sod.item_id

					LEFT JOIN tbStorage ts	WITH (NOLOCK)
					ON	ts.comp_id = tis.comp_id AND
						ts.stor_id = tis.stor_id

					LEFT JOIN tbsysOptionsValues AS tov
						ON	tov.lang_id			= tb.lang_id	AND
							tov.optval_class	= 520			AND
							tov.optval_id		= sod.sdlmt_id

			WHERE 	sod.comp_id			= @comp_id
			AND		sod.bra_id			= @bra_id
			AND		sod.soh_id			= @soh_id
			AND		isnull(it.item_expser,'False')  = 'False' --AND
					--it.item_NoStockCheck = 'False'

			ORDER BY	it.item_desc,
						tis.itst_StorageLocation

		END


END
GO






CREATE PROCEDURE [dbo].[spSaleOrderState_getDataByFilters]
(
	@comp_id			INT,
	@bra_id				INT,
	@soh_id				INT,
	@user_id			INT
)
AS

BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on

	-- --------------------------------------------------------------------------------------------------------------------
	-- Test
	-- --------------------------------------------------------------------------------------------------------------------
	/*
	declare @comp_id			int,
			@bra_id				int,
			@soh_id				INT,
			@prof_id			INT,
			@user_id			INT
	select	@comp_id			=1,
			@bra_id				=1,
			@soh_id				=7431,
			@prof_id			=3,
			@user_id			=1
	*/
	-- --------------------------------------------------------------------------------------------------------------------




	-- --------------------------------------------------------------------------------------------------------------------
	-- JAMAS cambiar el orden ni agregar algo entre medio, el HDP que hizo esta MIERDA puso las putas columnas en duro !!!!
	-- --------------------------------------------------------------------------------------------------------------------
	SELECT	tsosc.sos_desc,				-- 0
			tsos.sos_ok,				-- 1
			tsos.sos_id,				-- 2
			CASE
				WHEN (tsosc.bra_id IS NULL OR tsosc.bra_id = @bra_id)	AND tucp.comp_id IS NOT NULL	THEN	1
				ELSE																							0
			END				[enable]	-- 3


		FROM	tbSaleOrderStatus						tsos		WITH (NOLOCK)

		INNER JOIN tbSaleOrderStatusConcept		tsosc				WITH (NOLOCK)
		ON	tsosc.comp_id	=	tsos.comp_id	AND
			tsosc.sosc_id	=	tsos.sosc_id

		left JOIN tbUserCompanyProfile			tucp				WITH (NOLOCK)
			ON	tucp.comp_id	=	@comp_id
			AND tucp.bra_id		=	@bra_id
			AND tucp.prof_id	=	tsosc.prof_id
			AND	tucp.[user_id]	=	@user_id

		WHERE	tsos.comp_id		=	@comp_id	AND
				tsos.bra_id			=	@bra_id		AND
				tsos.soh_id			=	@soh_id




END
GO





CREATE PROCEDURE [dbo].[spSaleOrderState_updateData]
(
		@comp_id			int,
		@bra_id				int,
		@soh_id				int,
		@sos_id				INT,
		@sos_ok				BIT,
		@prof_id			INT,
		@user_id			INT
)
AS

BEGIN



	set nocount on

	-- -----------------------------------------------
	-- Test
	-- -----------------------------------------------
	/*
	declare @comp_id			int,
			@bra_id				int,
			@soh_id				int,
			@sos_id				INT,
			@sos_ok				BIT

	select	@comp_id			=1,
			@bra_id				=1,
			@soh_id				=84,
			@sos_id				=3,
			@sos_ok				='False'
	*/
	-- -----------------------------------------------



	UPDATE	tbSaleOrderStatus	WITH (ROWLOCK)
		SET		sos_ok				= @sos_ok,
				sos_lastUpdated		= GETDATE(),
				user_id_lastUpdated = @user_id
		WHERE	comp_id		=	@comp_id
		AND		bra_id		=	@bra_id
		AND		soh_id		=	@soh_id
		AND		sos_id		=	@sos_id


	INSERT INTO tbSaleOrderStatusHistory(	comp_id,
											sos_id,
											bra_id,
											soh_id,
											sosc_id,
											sos_ok,
											prof_id,
											[user_id])
		SELECT	tsos.comp_id,
				tsos.sos_id,
				tsos.bra_id,
				tsos.soh_id,
				tsos.sosc_id,
				tsos.sos_ok,
				@prof_id,
				@user_id
		FROM  tbSaleOrderStatus AS tsos	WITH (NOLOCK)
			WHERE	comp_id		=	@comp_id
			AND		bra_id		=	@bra_id
			AND		soh_id		=	@soh_id
			AND		sos_id		=	@sos_id

END
GO





