-- =============================================
-- Author:		MOS
-- Create date: 10-2009
--              01-2012, se agrega tabla de relaciones ya que nadie aun lo usaba.
-- Description:	Actualiza tbSaleOrderStatus
--				en funcion de la condicion de
--				venta seleccionada
-- =============================================
CREATE PROCEDURE [dbo].[spSaleOrderStatus_InsertUpdateData]
	@comp_id AS INT,
	@bra_id AS INT,
	--@st_id AS INT,
	@soh_id AS INT

AS
BEGIN

	SET NOCOUNT ON

	-- Recupera el df_id
	DECLARE @df_id AS INT
	DECLARE @st_id AS INT
	SELECT	@df_id = tsoh.df_id,
			@st_id = tsoh.st_id
		FROM tbSaleOrderHeader tsoh	WITH (NOLOCK)
		WHERE	tsoh.comp_id = @comp_id
			AND tsoh.bra_id  = @bra_id
			AND tsoh.soh_id  = @soh_id

	-- Borra estados anteriores
	DELETE FROM tbSaleOrderStatus
		WHERE	comp_id = @comp_id
			AND bra_id	= @bra_id
			AND soh_id	= @soh_id

	-- Inserta Nuevos Estados
	INSERT INTO tbSaleOrderStatus	WITH (ROWLOCK)
	(
		comp_id,
		bra_id,
		soh_id,
		sosc_id,
		sos_ok
	)
	SELECT	@comp_id,
			@bra_id,
			@soh_id,
			sc.sosc_id,
			'false'
		FROM tbSaleOrderStatusConcept sc			WITH (NOLOCK)

		INNER JOIN tbSaleOrderStatusRelations tsosr	WITH (NOLOCK)
			ON		tsosr.comp_id = sc.comp_id
				AND tsosr.sosc_id = sc.sosc_id
				AND tsosr.st_id   = @st_id
				AND tsosr.df_id   = @df_id

		WHERE	sc.comp_id = @comp_id



END

GO





CREATE PROCEDURE [dbo].[spSaleOrderStatusConcept_getCombo]
(
	@comp_id	INT
)

AS

BEGIN



	SET NOCOUNT ON

