CREATE procedure [dbo].[spSaleOrderStockComposition_getGenericGridData]
(
	@comp_id	INT,
	@tis_id		INT
)
as set nocount on



-- -----------------------------------------
-- Testing
-- -----------------------------------------
/*
	declare
		@comp_id	INT,
		@bra_id		INT,
		@tis_id		INT

	select
		@comp_id	= 1,
		@bra_id		= 1,
		@tis_id		= 9260
*/

-- -----------------------------------------


	SELECT		ti.item_code															[item_code],
				ti.item_desc															[item_desc],
				dbo.fnGetAStock(@comp_id,ttis.stor_id, ti.item_id, ttis.tis_priority)	[StockActual]

		FROM tbTempItemStock						ttis

		INNER JOIN tbItemComposition				tic
		ON	tic.comp_id = ttis.comp_id
		AND tic.item_id = ttis.item_id

		INNER JOIN tbItem							ti
		ON	ti.comp_id = ttis.comp_id
		AND ti.item_id = tic.item_id_1



	WHERE	ttis.comp_id	= @comp_id
	AND		ttis.tis_id		= @tis_id



	ORDER BY	ti.item_code,ti.item_desc

GO



