CREATE PROCEDURE spSaleOrderStorageByProfile_getDataById
	@comp_id AS INT,
	@bra_id AS INT,
	@prof_id AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	SELECT TOP 1 *
		FROM tbSaleOrderStorageByProfile tt WITH (NOLOCK)
		WHERE	tt.comp_id		= @comp_id	AND
				tt.bra_id		= @bra_id	AND
				tt.prof_id		= @prof_id	AND
				tt.spr_disabled = 'False'

END
GO







CREATE procedure [dbo].[spSaleOrderTypesByProfile_getCombo]
(
	@comp_id	int,
	@lang_id	int,
	@bra_id		int,
	@prof_id	int
)
as

BEGIN


	------------------------------------------------------------------------------------
	/*
	declare	@comp_id	int,
			@lang_id	int,
			@bra_id		int,
			@prof_id	int


	select	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@prof_id	= 1

		*/
	------------------------------------------------------------------------------------

	SELECT  tov.optval_id					[id],
			ltrim(rtrim(tov.optval_desc))	[desc]
		FROM tbSaleOrderTypesByProfile tsotbp					WITH (NOLOCK)
		LEFT JOIN tbsysOptionsValues tov						WITH (NOLOCK)
		ON tov.optval_id	= tsotbp.optval_id  AND
		   tov.optval_class = 110				AND
		   tov.lang_id		= @lang_id
		WHERE tsotbp.comp_id		= @comp_id  AND
			  tsotbp.bra_id			= @bra_id	AND
			  tsotbp.prof_id		= @prof_id
		order by tov.optval_order


END
GO







