GO







CREATE PROCEDURE [dbo].[spSaleOrderWS_CustCurrAcc]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@wst_id				INT,
	@user_id			INT,
	@cust_id			INT
)
AS


SET NOCOUNT ON

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@user_id			INT,
			@cust_id			INT

	SELECT	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@user_id			=1,
			@cust_id			=24288
	*/
	-- -------------------------------------------------------------------------------


	SET DATEFORMAT 'YMD'

	SELECT	dbo.fnGetCommercialTransactionDescription(tct.comp_id,@lang_id, tct.ct_transaction)  [ct_docNumber],
			tct.ct_ATotal,
			tct.ct_ABalance,
			tct.ct_ACurrency,
			tc.curr_symbol,
			CONVERT(CHAR(10),tct.ct_date,	111)								[ct_date],
			CONVERT(CHAR(10),tct.ct_payDate,111)								[ct_payDate],

			ISNULL(tdf.df_url4Reprint,'') +
				'wfmDocumentsPrint.aspx' +
					ISNULL(tctn.ctn_link4Reprint,'')							[ct_reprint]




	FROM	tbCommercialTransactions				tct

			INNER JOIN tbsysCurrency				tc
			ON	tc.curr_id		= tct.ct_ACurrency

			INNER JOIN tbUsers4BranchFilter			vubf
			ON	vubf.comp_id	= tct.comp_id
			AND vubf.bra_id		= tct.bra_id
			AND vubf.[user_id]	= @user_id

			LEFT JOIN tbCommercialTransactionNotes	tctn
			ON	tctn.comp_id		= tct.comp_id
			AND tctn.bra_id			= tct.bra_id
			AND tctn.ct_transaction = tct.ct_transaction

			LEFT JOIN tbDocumentsFile				tdf
			ON tdf.comp_id = tct.comp_id
			AND tdf.df_id = tct.df_id

	WHERE	tct.comp_id = @comp_id
	AND		tct.bra_id	= @bra_id
	AND		tct.cust_id	= @cust_id
	AND		tct.sd_id	IN (1,3,4,6,13)

	ORDER BY tct.ct_transaction




END
GO


CREATE PROCEDURE [dbo].[spSaleOrderWS_deleteItem]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@wst_id				INT,
	@guid				UNIQUEIDENTIFIER,
	@item_id			INT
)
AS
SET NOCOUNT ON



BEGIN




	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@guid				UNIQUEIDENTIFIER,
			@item_id			INT

	SELECT	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@guid				='73511EB5-3D7E-402D-AF4F-7183109847A6',
			@item_id			=256
	*/
	-- -------------------------------------------------------------------------------




	declare @return_value		INT,
			@errormessage		NVARCHAR(1000)

	set		@return_value = 0
	set		@errormessage = 'Artículo Eliminado'




	--eliminamos el tax correspondiente
	DELETE FROM tbtmpTax

	FROM	tbtmpTax							tt

			INNER JOIN tbTempItemStock			ttis
			ON	ttis.comp_id	= tt.comp_id
			AND ttis.tis_guid	= tt.tis_guid
			AND ttis.tis_id		= tt.tis_id

	WHERE	ttis.comp_id	= @comp_id
	AND		ttis.tis_guid	= @guid
	AND		ttis.item_id	= @item_id




	--eliminamos el artículo seleccionado
	DELETE	FROM tbTempItemStock

	WHERE	comp_id		= @comp_id
	AND		tis_guid	= @guid
	AND		item_id		= @item_id




	IF @@ROWCOUNT = 0
	BEGIN

		SET 	@return_value = -1
		SET 	@errormessage = 'No se encotró el artículo a eliminar'

	END





	SELECT	@return_value, @errormessage



END
GO

CREATE PROCEDURE spSaleOrderWS_deleteItem_WithCombos
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@wst_id				INT,
	@guid				UNIQUEIDENTIFIER,
	@tis_id				INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------------------------------------------
		-- Testing
		-- -------------------------------------------------------------------------------
		/*
			DECLARE	@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@guid				UNIQUEIDENTIFIER,
					@tis_id				INT

			SELECT	@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@guid				= '89A50C9F-C468-4B0D-81DC-015731896CE1',
					@tis_id				= 1473478
		*/
		-- -------------------------------------------------------------------------------


		-- ---------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- ---------------------------------------------------
		DECLARE @return_value		INT,
				@errormessage		NVARCHAR(1000)
		SET		@return_value = 0
		SET		@errormessage = 'Artículo Eliminado'
		-- ---------------------------------------------------

		-- ---------------------------------------------------
		-- ME FIJO SI EL TIS_ID QUE QUIERE BORRAR ES PARTE
		-- DE UN COMBO
		-- ---------------------------------------------------
		DECLARE
			@litem_id			INT,
			@ltis_id_Origin		INT,
			@ltis_id			INT
		SELECT
			@ltis_id		= ttis.tis_id,
			@litem_id		= ttis.item_id,
			@ltis_id_Origin	= ttis.tis_id_origin
		FROM tbTempItemStock				AS ttis
		WHERE	ttis.comp_id	= @comp_id	AND
				ttis.tis_guid	= @guid		AND
				ttis.tis_id		= @tis_id

		-- SI ITEM_ID = NULL significa que es el MAIN ITEM del COMBO
		IF @litem_id IS NULL
			BEGIN
				SET @tis_id = @ltis_id
			END

		-- SI ITEM_ID IS NOT NULL Y TIS_ID_ORIGIN IS NOT NULL ES PARTE DE UN COMBO
		IF (@litem_id IS NOT NULL) AND (@ltis_id_Origin IS NOT NULL)
			BEGIN
				SET @tis_id = @ltis_id_Origin
			END
		-- ---------------------------------------------------

		-- ---------------------------------------------------
		-- eliminamos el tax correspondiente
		-- ---------------------------------------------------
		DELETE FROM tbtmpTax
			FROM	tbtmpTax						tt
				INNER JOIN tbTempItemStock			ttis
				ON	ttis.comp_id	= tt.comp_id 	AND
					ttis.tis_guid	= tt.tis_guid   AND
					ttis.tis_id		= tt.tis_id
			WHERE	ttis.comp_id	= @comp_id		AND
					ttis.tis_guid	= @guid			AND
					(
						ttis.tis_id			= @tis_id OR
						ttis.tis_id_origin	= @tis_id
					)
		-- ---------------------------------------------------

		-- ---------------------------------------------------
		-- eliminamos el artículo seleccionado
		-- ---------------------------------------------------
		DELETE	FROM tbTempItemStock
		WHERE	comp_id		= @comp_id	AND
				tis_guid	= @guid		AND
				(
					tis_id			= @tis_id OR
					tis_id_origin	= @tis_id
				)
		-- ---------------------------------------------------

		IF @@ROWCOUNT = 0
			BEGIN
				SET 	@return_value = -1
				SET 	@errormessage = 'No se encotró el artículo a eliminar'
			END

		SELECT	@return_value, @errormessage

	END
GO







CREATE PROCEDURE [dbo].[spSaleOrderWS_deleteSaleOrder]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@soh_id				INT
)
AS
SET NOCOUNT ON


SET NOCOUNT ON

BEGIN


	/*
	DECLARE @comp_id			INT,
			@soh_id				INT

	SELECT 	@comp_id			=1,
			@soh_id				=32758
	*/




	DECLARE @return_value		INT,
			@error_message		NVARCHAR(200)



	IF EXISTS(	SELECT  1
				from	tbsaleorderheader
				WHERE	comp_id		= @comp_id
				AND		soh_id		= @soh_id
				AND		ssos_id		= 5) --Pendiente WEB
	BEGIN
		--select 'el pedido se puede eliminar'

		BEGIN TRANSACTION
		BEGIN TRY

			DELETE FROM tbSaleOrderExtendedDiscount	WHERE comp_id = @comp_id AND soh_id = @soh_id
			DELETE FROM tbSaleOrderLoan				WHERE comp_id = @comp_id AND soh_id = @soh_id
			DELETE FROM tbSaleOrderTaxes			WHERE comp_id = @comp_id AND soh_id = @soh_id
			DELETE FROM tbSaleOrderDetail			WHERE comp_id = @comp_id AND soh_id = @soh_id
			DELETE FROM tbSaleOrderHeader			WHERE comp_id = @comp_id AND soh_id = @soh_id

			COMMIT TRANSACTION

			SET @return_value	= 0
			SET @error_message	= 'Pedido: ' +  CONVERT(VARCHAR, @soh_id) + ' eliminado.'

		END
		TRY BEGIN CATCH
			--SELECT ERROR_LINE(), ERROR_MESSAGE(), ERROR_NUMBER()
			ROLLBACK TRANSACTION
			SET @return_value	= -1
			SET @error_message = ERROR_MESSAGE()

		END CATCH

	END
	ELSE
	BEGIN
			IF NOT EXISTS(	SELECT  1
							from	tbsaleorderheader
							WHERE	comp_id		= @comp_id
							AND		soh_id		= @soh_id)
			BEGIN

				--select 'pedido inexistente'
				SET @return_value	= -2
				SET @error_message	= 'Pedido: ' +  CONVERT(VARCHAR, @soh_id) + ' inexistente.'

			END
			ELSE
			BEGIN
					IF EXISTS(	SELECT  1
									from	tbsaleorderheader
									WHERE	comp_id		= @comp_id
									AND		soh_id		= @soh_id
									AND ssos_id <> 5)
					BEGIN

						--select 'el pedido se encuentra en un estado que no permite ser eliminado'
						SET @return_value	= -3
						SET @error_message	= 'Pedido: ' +  CONVERT(VARCHAR, @soh_id) + ' se encuentra en un estado que no permite ser eliminado.'

					END
					ELSE
					BEGIN

						--select 'error interno', @soh_id
						SET @return_value	= -4
						SET @error_message	= 'Pedido: ' +  CONVERT(VARCHAR, @soh_id) + ' no se puede procesar la solicitud.'

					END

			END

	END


	SELECT	@return_value	[return_code],
			@error_message	[return_message]


END
GO







CREATE PROCEDURE [dbo].[spSaleOrderWS_getDataByCustomer]
(
	@comp_id			INT ,
	@lang_id			INT ,
	@bra_id				INT ,
	@cust_id			INT
)
AS


BEGIN

	set nocount on

	set dateformat 'ymd'



	-- ---------------------------------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------------------------------
	/*
	declare 	@comp_id			int,
				@lang_id			INT,
				@bra_id				int,
				@cust_id			int

	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@cust_id			= 24288
	*/
	-- ---------------------------------------------------------------------------------------------







	-- ----------------------------------------------------------------------------------------
	--	Select PRINICPAL
	-- ----------------------------------------------------------------------------------------
	SELECT
			CASE
				WHEN	tcb.custb_name IS NULL THEN cu.cust_name
				ELSE	tcb.custb_name
			END																					[cust_name],
			'#' + dbo.fnGetSaleOrderNumber(soh.comp_id,soh.bra_id,soh.soh_id) + '¦' +
					convert(nvarchar(4),IsNull(sov.optval_desc,'')) + '¦' + vsos.ssos_desc 		[doc_desc],

			soh.soh_deliveryDate,

			CASE
				WHEN df.sd_id = 1 THEN
										LTRIM(RTRIM(isnull(tc.curr_symbol,''))) + ' ' +
										CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),soh.soh_total))
				ELSE ''
			END																												[soh_total],
			--LTRIM(RTRIM(isnull(tc2.curr_symbol,''))) + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),soh.soh_Atotal))		[soh_total_curr_id4Exchange],
			CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),dbo.fnGetMyExchange(soh.soh_ExchangeToCustomerCurrency)))					[soh_ExchangeToCustomerCurrency],
			--IsNull(soh.soh_internalAnnotation,'')																			[soh_internalAnnotation],
			st.st_desc,
			di.disc_desc,
			df.df_desc,
			dl.dl_name,
			--us.user_lastname + ', ' + user_firstname																		[Name],
			--soh.comp_id,
			--soh.bra_id,
			--soh.soh_cd,
			--soh.soh_quotation,
			sm.sm_name,
			--soh.sm_id,
			--soh.cust_id,
			--st.st_desc,
			bra.bra_desc,
			--soh.st_id,
			--soh.disc_id,
			--di.disc_desc,
			--soh.dl_id,
			--soh.cb_id,
			--soh.soh_lastUpdate,
			--soh.soh_limitDate,
			--soh.tt_id,
			--soh.tt_class,
			--soh.soh_StatusOf,
			--soh.user_id,
			--soh.soh_isEditingCd,
			--soh.df_id,
			--soh.soh_observation1,
			--soh.soh_observation2,
			--soh.soh_observation3,
			--soh.soh_observation4,

			ISNULL(DATEDIFF(DAY, bra.bra_processingDate, soh.soh_limitDate), 0)												[depura],
			/*
			-- ------------------------------------------------------------------------------------------
			-- ATENCION!!!!!
			-- Por Favor, no poner nada a partir de este campo.!!  Se toman por orden en SaleOrderAll!!
			-- Ocultar en wfmSaleOrderAll: subSetgrdDataHideColumns
			-- ------------------------------------------------------------------------------------------
			CASE
				WHEN EXISTS(
							SELECT 1
									FROM tbSaleOrderStatus tsos2
									WHERE	tsos2.comp_id		= soh.comp_id
										AND tsos2.bra_id		= soh.bra_id
										AND tsos2.soh_id		= soh.soh_id
										--AND tsos2.sos_ok		= 'False'

							) THEN '1'
				ELSE '0'
			END			[soh_hasSOS],					--	tiene algun estado	-- Count - 12
			CASE
				WHEN EXISTS(
							SELECT 1
										FROM tbSaleOrderStatus tsos2
										INNER JOIN tbSaleOrderStatusConcept tsosc
										ON		tsosc.comp_id	= @comp_id
											AND tsosc.sosc_id	= tsos2.sosc_id
											--AND tsosc.sosc_blockSaleOrderEmmition = 'True'
									WHERE	tsos2.comp_id		= soh.comp_id
										AND tsos2.bra_id		= soh.bra_id
										AND tsos2.soh_id		= soh.soh_id
										AND tsos2.sos_ok		= 'False'

							) THEN '1'
				ELSE '0'
			END			[soh_hasSOS4EmmitionPending],	--  tiene estado pendiente que bloquee emision?	-- Count - 11
			df.sd_id,																		-- Count - 10
			--Parte 659 STL acá se devolverá 1 = Espera o 2 = No espera para colorear la grilla de SALEORDERALL
			CASE WHEN tcw.cust_id is NULL THEN
				2
			ELSE
				1
			END											[CustomerWaiting],					-- Count - 9
			Case IsNull(cu.cust_inactive,'False')
				WHEN 'True' THEN '1'
				ELSE			 '0'
			END
													[cust_inactive],					-- Count - 8
			--case
			--	when	isnull(tmp2.soh_id,0) = 0 THEN 0
			--	ELSE	1
			--END											[IsSerialized],
									-- Count - 7
			--isnull(tmp.count,-1)						[StatusOK],							-- Count - 6
			cu.bra_id4Emmition,																-- Count - 4
			IsNull(soh.ssos_id,10) [ssos_id],												-- Count - 3
			--soh.soh_isEditing,																-- Count - 2
			*/
			--Convert(Varchar,soh.bra_id) + '-' +
			Convert(Varchar,soh.soh_id)		[ID Pedido],		-- Count - 1

			ti.item_code,
			ti.item_desc,
			tc2.curr_symbol,
			tsod.sod_price,
			tsod.sod_qty

	FROM	dbo.tbSaleOrderHeader				soh

			INNER JOIN tbSaleOrderDetail		tsod
			ON  tsod.comp_id	= soh.comp_id
			AND tsod.bra_id		= soh.bra_id
			AND tsod.soh_id		= soh.soh_id

			LEFT JOIN tbItem					ti
			ON	ti.comp_id		= tsod.comp_id
			AND ti.item_id		= tsod.item_id

			LEFT JOIN tbsysCurrency				tc2
			ON	tc2.curr_id		= tsod.curr_id


			left join dbo.tbSalesman			sm
			on	sm.sm_id		= soh.sm_id
			And sm.comp_id		= soh.comp_id

			inner join dbo.tbCustomer			cu
			on	cu.cust_id		= soh.cust_id
			And cu.comp_id		= soh.comp_id

			LEFT JOIN tbCustomerBranch			tcb
			ON	tcb.comp_id		= soh.comp_id
			AND tcb.cust_id		= soh.cust_id
			AND tcb.cb_id		= soh.cb_id

			inner join dbo.tbBranch				bra
			on	bra.comp_id		= soh.comp_id
			And bra.bra_id		= soh.bra_id

			left join dbo.tbSalesTerms			st
			on  st.comp_id		= soh.comp_id
			and st.st_id		= soh.st_id

			left join dbo.tbDiscount			di
			on	di.disc_id		= soh.disc_id
			And di.comp_id		= soh.comp_id

			INNER join dbo.tbDocumentsFile		df
			on	df.comp_id		= soh.comp_id
			and df.df_id		= soh.df_id

			Left Join dbo.tbsysOptionsValues	SOV
			On	SOV.lang_id		= @lang_id
			and SOV.optval_class= 6
			and SOV.optval_id	= df.sd_id

			--left join dbo.tbUser				us
			--on	us.[user_id]	= soh.[user_id]

			left join dbo.tbDelivery			dl
			on	dl.dl_id		= soh.dl_id
			And dl.comp_id		= soh.comp_id

			LEFT JOIN vwSaleOrderStatus			vsos
			ON	vsos.comp_id	= soh.comp_id
			AND vsos.bra_id		= soh.bra_id
			AND vsos.soh_id		= soh.soh_id
			AND vsos.lang_id	= @lang_id

			INNER JOIN tbsysCurrency			tc
			ON	tc.curr_id		= bra.curr_id

			--LEFT JOIN tbCustomerWaiting			tcw
			--ON	tcw.comp_id		= soh.comp_id
			--AND tcw.bra_id		= soh.bra_id
			--AND tcw.cust_id		= soh.cust_id


	WHERE	soh.comp_id		= @comp_id
	AND		soh.bra_id		= @bra_id
	AND		soh.cust_id		= @cust_id
	AND		soh.ssos_id		= 5


	ORDER BY soh.soh_id

END
GO







CREATE PROCEDURE [dbo].[spSaleOrderWS_getDataByCustomerByOne]
(
	@comp_id			INT ,
	@lang_id			INT ,
	@bra_id				INT ,
	@cust_id			INT
)
AS


BEGIN

	set nocount on

	set dateformat 'ymd'



	-- ---------------------------------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------------------------------
	/*
	declare 	@comp_id			int,
				@lang_id			INT,
				@bra_id				int,
				@cust_id			int

	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@cust_id			= 24288
	*/
	-- ---------------------------------------------------------------------------------------------







	-- ----------------------------------------------------------------------------------------
	--	Select PRINICPAL
	-- ----------------------------------------------------------------------------------------
	SELECT
			CASE
				WHEN	tcb.custb_name IS NULL THEN cu.cust_name
				ELSE	tcb.custb_name
			END																					[cust_name],
			'#' + dbo.fnGetSaleOrderNumber(soh.comp_id,soh.bra_id,soh.soh_id) + '¦' +
					convert(nvarchar(4),IsNull(sov.optval_desc,'')) + '¦' + vsos.ssos_desc 		[doc_desc],

			soh.soh_deliveryDate,

			CASE
				WHEN df.sd_id = 1 THEN
										LTRIM(RTRIM(isnull(tc.curr_symbol,''))) + ' ' +
										CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),soh.soh_total))
				ELSE ''
			END																												[soh_total],
			--LTRIM(RTRIM(isnull(tc2.curr_symbol,''))) + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),soh.soh_Atotal))		[soh_total_curr_id4Exchange],
			CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),dbo.fnGetMyExchange(soh.soh_ExchangeToCustomerCurrency)))					[soh_ExchangeToCustomerCurrency],
			--IsNull(soh.soh_internalAnnotation,'')																			[soh_internalAnnotation],
			st.st_desc,
			di.disc_desc,
			df.df_desc,
			dl.dl_name,
			--us.user_lastname + ', ' + user_firstname																		[Name],
			--soh.comp_id,
			--soh.bra_id,
			--soh.soh_cd,
			--soh.soh_quotation,
			sm.sm_name,
			--soh.sm_id,
			--soh.cust_id,
			--st.st_desc,
			bra.bra_desc,
			--soh.st_id,
			--soh.disc_id,
			--di.disc_desc,
			--soh.dl_id,
			--soh.cb_id,
			--soh.soh_lastUpdate,
			--soh.soh_limitDate,
			--soh.tt_id,
			--soh.tt_class,
			--soh.soh_StatusOf,
			--soh.user_id,
			--soh.soh_isEditingCd,
			--soh.df_id,
			--soh.soh_observation1,
			--soh.soh_observation2,
			--soh.soh_observation3,
			--soh.soh_observation4,

			ISNULL(DATEDIFF(DAY, bra.bra_processingDate, soh.soh_limitDate), 0)												[depura],
			--Convert(Varchar,soh.bra_id) + '-' +
			Convert(Varchar,soh.soh_id)		[ID Pedido]		-- Count - 1



	FROM	dbo.tbSaleOrderHeader				soh

--			INNER JOIN tbSaleOrderDetail		tsod
--			ON  tsod.comp_id	= soh.comp_id
--			AND tsod.bra_id		= soh.bra_id
--			AND tsod.soh_id		= soh.soh_id
--
--			LEFT JOIN tbItem					ti
--			ON	ti.comp_id		= tsod.comp_id
--			AND ti.item_id		= tsod.item_id
--
--			LEFT JOIN tbsysCurrency				tc2
--			ON	tc2.curr_id		= tsod.curr_id


			left join dbo.tbSalesman			sm
			on	sm.sm_id		= soh.sm_id
			And sm.comp_id		= soh.comp_id

			inner join dbo.tbCustomer			cu
			on	cu.cust_id		= soh.cust_id
			And cu.comp_id		= soh.comp_id

			LEFT JOIN tbCustomerBranch			tcb
			ON	tcb.comp_id		= soh.comp_id
			AND tcb.cust_id		= soh.cust_id
			AND tcb.cb_id		= soh.cb_id

			inner join dbo.tbBranch				bra
			on	bra.comp_id		= soh.comp_id
			And bra.bra_id		= soh.bra_id

			left join dbo.tbSalesTerms			st
			on  st.comp_id		= soh.comp_id
			and st.st_id		= soh.st_id

			left join dbo.tbDiscount			di
			on	di.disc_id		= soh.disc_id
			And di.comp_id		= soh.comp_id

			INNER join dbo.tbDocumentsFile		df
			on	df.comp_id		= soh.comp_id
			and df.df_id		= soh.df_id

			Left Join dbo.tbsysOptionsValues	SOV
			On	SOV.lang_id		= @lang_id
			and SOV.optval_class= 6
			and SOV.optval_id	= df.sd_id

			--left join dbo.tbUser				us
			--on	us.[user_id]	= soh.[user_id]

			left join dbo.tbDelivery			dl
			on	dl.dl_id		= soh.dl_id
			And dl.comp_id		= soh.comp_id

			LEFT JOIN vwSaleOrderStatus			vsos
			ON	vsos.comp_id	= soh.comp_id
			AND vsos.bra_id		= soh.bra_id
			AND vsos.soh_id		= soh.soh_id
			AND vsos.lang_id	= @lang_id

			INNER JOIN tbsysCurrency			tc
			ON	tc.curr_id		= bra.curr_id

			--LEFT JOIN tbCustomerWaiting			tcw
			--ON	tcw.comp_id		= soh.comp_id
			--AND tcw.bra_id		= soh.bra_id
			--AND tcw.cust_id		= soh.cust_id


	WHERE	soh.comp_id		= @comp_id
	AND		soh.bra_id		= @bra_id
	AND		soh.cust_id		= @cust_id
	AND		soh.ssos_id		= 5


	ORDER BY soh.soh_id

END
GO






CREATE PROCEDURE [dbo].[spSaleOrderWS_getDataByGuid]
(
	@comp_id		INT,
	@lang_id		INT,
	@guid			UNIQUEIDENTIFIER
)
AS

SET NOCOUNT ON

BEGIN


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@lang_id	INT,
			@guid		UNIQUEIDENTIFIER

	SELECT	@comp_id	= 1,
			@lang_id	= 2,
			@guid		= '28253F43-C96D-4314-9BBA-DF748E5CA2A8'
	*/
	-- -------------------------------------------------------------------------------


	SELECT	ttis.item_id,
			ti.item_code,
			ti.item_desc,

			ttis.tis_qty,

			ttis.curr_id,
			tc.curr_symbol,
			ttis.stor_id,
			ttis.tis_price


	FROM	tbTempItemStock				ttis	WITH(NOLOCK)

			INNER JOIN tbItem			ti		WITH(NOLOCK)
			ON	ti.comp_id	= ttis.comp_id
			AND ti.item_id	= ttis.item_id

			INNER JOIN tbsysCurrency	tc		WITH(NOLOCK)
			ON tc.curr_id	= ttis.curr_id

	WHERE	ttis.comp_id	= @comp_id
	AND		ttis.tis_guid	= @guid



END

GO


CREATE PROCEDURE [dbo].[spSaleOrderWS_getDataByGuid_WithCombo]
(
	@comp_id		INT,
	@lang_id		INT,
	@guid			UNIQUEIDENTIFIER
)
AS

SET NOCOUNT ON

BEGIN


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@lang_id	INT,
			@guid		UNIQUEIDENTIFIER

	SELECT	@comp_id	= 1,
			@lang_id	= 2,
			@guid		= 'D99B0ED0-48BC-478C-8BF1-1D9F32C7BC9F'
	*/
	-- -------------------------------------------------------------------------------


	SELECT

		ISNULL(ttis.item_id, ti2.item_id)	[item_id],
		ISNULL(ti.item_code, ti2.item_code)	[item_code],
		ISNULL(ti.item_desc, ti2.item_desc)	[item_desc],

		ttis.tis_qty,

		ttis.curr_id,
		tc.curr_symbol,
		ttis.stor_id,
		ttis.tis_price,
		CASE
			WHEN ttis.item_id IS NULL AND ttis.tis_item_id_origin IS NOT NULL THEN	'True'
			ELSE																	'False'
		END [isComboItem],

		ttis.tis_id,
		ttis.tis_id_origin



	FROM	tbTempItemStock					AS ttis	WITH(NOLOCK)

			LEFT JOIN tbItem				AS ti	WITH(NOLOCK)
			ON	ti.comp_id	= ttis.comp_id 	AND
				ti.item_id	= ttis.item_id

			LEFT JOIN tbItem				AS ti2	WITH(NOLOCK)
			ON	ti2.comp_id	= ttis.comp_id	AND
				ti2.item_id = ttis.tis_item_id_origin

			LEFT JOIN tbsysCurrency		AS tc		WITH(NOLOCK)
			ON tc.curr_id	= ttis.curr_id

	WHERE	ttis.comp_id	= @comp_id 		AND
			ttis.tis_guid	= @guid



END

GO





