CREATE PROCEDURE [dbo].[spSaleOrderWS_getItemsBySaleOrder]
(
	@comp_id			INT ,
	@lang_id			INT ,
	@bra_id				INT ,
	@soh_id				INT
)
AS


BEGIN

	set nocount on

	set dateformat 'ymd'



	-- ---------------------------------------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------------------------------------
	/*
	declare 	@comp_id			int,
				@lang_id			INT,
				@bra_id				int,
				@soh_id				int

	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@soh_id				= 32738
	*/
	-- ---------------------------------------------------------------------------------------------



	SELECT	--tsod.item_id,
			ti.item_code,
			ti.item_desc,
			tsod.sod_qty,
			--tsod.curr_id,
			tc.curr_symbol,
			tsod.sod_price,
			--tsod.stor_id,
			tsod.sod_id

	FROM	tbSaleOrderDetail			tsod

			INNER JOIN tbItem			ti
