	ORDER BY tsod.sod_id



END
GO








CREATE PROCEDURE [dbo].[spSaleOrderWS_getSaleOrderTotals]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@wst_id				INT,
	@guid				UNIQUEIDENTIFIER,
	@cust_id			INT,
	@sd_id				INT
)
AS




BEGIN


	SET NOCOUNT ON

	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@guid				UNIQUEIDENTIFIER,
			@wst_id				INT,
			@cust_id			INT,
			@sd_id				INT

	SELECT	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@guid				='1A39612C-8202-4E70-8532-9526114580F7',
			@wst_id				=10,
			@cust_id			=24288,
			@sd_id				=1

	IF NOT OBJECT_ID('tempdb.dbo.#tmpGetTotalsData') IS NULL DROP TABLE #tmpGetTotalsData
	*/
	-- -------------------------------------------------------------------------------




	/*
	declare @return_value		INT,
			@errormessage		NVARCHAR(1000)

	set		@return_value = 0
	set		@errormessage = ''
	*/




	--obtenemos el df_id para generar el pedido
	DECLARE @df_id		INT

	SELECT	TOP 1 @df_id	= df_id

	FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)

	WHERE	sd_id			= @sd_id

	ORDER BY df_order





/*

	--se controla que haya artículos cargados en la temporal
	IF NOT EXISTS (SELECT TOP 1 1
					FROM tbTempItemStock ttis
					WHERE ttis.comp_id = @comp_id AND ttis.tis_guid = @guid)

		BEGIN

			SET @return_value = -2
			SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 99

		END

	ELSE

		IF @df_id IS NULL
			BEGIN

				SET @return_value = -3
				SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 91

			END

		ELSE

*/

	--si no hubo errores recupera totales e impuestos
	--IF @return_value = 0
	--BEGIN

		/*
		BEGIN TRANSACTION
		BEGIN TRY
		*/

			DECLARE @rv								INT



			DECLARE @sm_id							INT,
					@st_id							INT,
					@disc_id						INT,
					@dl_id							INT,
					@curr_id_cust					INT

			SELECT	@sm_id			= tc.sm_id,
					@st_id			= tc.st_id,
					@disc_id		= tc.disc_id,
					@dl_id			= tc.dl_id,
					@curr_id_cust	= tc.curr_id

			FROM	tbCustomer		tc

			WHERE	tc.comp_id		= @comp_id
			AND		tc.cust_id		= @cust_id





			DECLARE @curr_id_branch					INT,
					@bra_PriceDecimalPlaces			INT,
					@bra_SaleOrderDisposeLimitDay	INT,
					@country_id						INT,
					@state_id						INT

			SELECT	@curr_id_branch					= tb.curr_id,
					@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
					@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
					@country_id						= tb.country_id,
					@state_id						= tb.state_id

			FROM	tbBranch		tb	WITH (NOLOCK)

			WHERE	tb.comp_id		= @comp_id
			AND		tb.bra_id		= @bra_id





			DECLARE @user_id		INT

			SELECT	@user_id	= tws.[user_id]
			FROM	tbWebServices tws
			WHERE	tws.comp_id = @comp_id
			AND		tws.wst_id	= @wst_id




			/******************************************************************************************/

			CREATE TABLE #tmpGetTotalsData
			(
				ErrorCode			INT				,
				Total				DECIMAL(18,2)	,
				TotalTaxes			DECIMAL(19,6)	,
				TotalDiscount		DECIMAL(19,6)	,
				TotalCCard			DECIMAL(19,6)	,
				TotalNeto			DECIMAL(18,2)	,
				TotalItemsQty		DECIMAL(19,5)	,
				CurrId4TotalShow	INT				,
				IVATaxes			DECIMAL(19,6)	,
				strTAXES			NVARCHAR(4000)	,
				TotalNoInterest		DECIMAL(25,6)
			)


			--INSERT INTO #tmpGetTotalsData
				--EXEC spTempItemStock_getDataForWebSite @comp_id, @guid, @ws_id, @cust_id, 3



			-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
			DECLARE	@exchange		DECIMAL(19,6)

			SELECT @exchange = dbo.fnGetExchange(@comp_id,1,@curr_id_branch,@curr_id_cust,0,0,'false')




			--SELECT @curr_id_branch,	@curr_id_cust, @exchange

			-- recuperar los totales generales
			INSERT INTO #tmpGetTotalsData
				EXEC	sptmpTax_calculate
						@comp_id,
						@bra_id,
						@cust_id,
						@guid,
						@curr_id_branch,
						@disc_id,
						@country_id,
						@state_id,
						@st_id,
						@curr_id_branch,
						@curr_id_cust,
						@exchange,
						'false',
						@df_id,
						'true',
						@dl_id,
						0,
						'false',
						'false',
						-1,
						-1 -- @ccp_id NO INFORMADO en este SP

			-- ----------------------
			-- Calcula Importe en USD
			-- ----------------------
			DECLARE @decTotalInUSD AS DECIMAL(19,2)
			SELECT	@decTotalInUSD	= IsNull(tmp.Total,0)  FROM #tmpGetTotalsData tmp
			SET		@decTotalInUSD	= dbo.fnGetExchange(@comp_id,@decTotalInUSD,@curr_id_branch,2,0,0,'false')
			-- ----------------------

			DECLARE @lcurr_id_alternative INT

			SET @lcurr_id_alternative = CASE WHEN @curr_id_cust = 1 THEN 2 ELSE 1 END

			UPDATE #tmpGetTotalsData SET CurrId4TotalShow = @curr_id_branch

			SELECT	tmpGTD.*,

					@lcurr_id_alternative	[curr_id_2],
					tmpGTD.Total			* CASE WHEN isnull(tce.ce_exchange,1) < 1 THEN 1/tce.ce_exchange ELSE tce.ce_exchange END [Total_2],
					tmpGTD.TotalTaxes		* CASE WHEN isnull(tce.ce_exchange,1) < 1 THEN 1/tce.ce_exchange ELSE tce.ce_exchange END [TotalTaxes_2],
					tmpGTD.TotalDiscount	* CASE WHEN isnull(tce.ce_exchange,1) < 1 THEN 1/tce.ce_exchange ELSE tce.ce_exchange END [TotalDiscount_2],
					tmpGTD.TotalCCard		* CASE WHEN isnull(tce.ce_exchange,1) < 1 THEN 1/tce.ce_exchange ELSE tce.ce_exchange END [TotalCCard_2],
					tmpGTD.TotalNeto		* CASE WHEN isnull(tce.ce_exchange,1) < 1 THEN 1/tce.ce_exchange ELSE tce.ce_exchange END [TotalNeto_2],
					tmpGTD.IVATaxes			* CASE WHEN isnull(tce.ce_exchange,1) < 1 THEN 1/tce.ce_exchange ELSE tce.ce_exchange END [IVATaxes_2],
					@decTotalInUSD			[TotalInUSD]

			FROM	#tmpGetTotalsData				tmpGTD
					LEFT JOIN tbCurrencyExchange	tce	WITH (NOLOCK)
					ON tce.comp_id = @comp_id
					AND (
							(tce.curr_id_1 = @curr_id_cust AND tce.curr_id_2 = @lcurr_id_alternative) OR
							(tce.curr_id_1 = @lcurr_id_alternative AND tce.curr_id_2 = @curr_id_cust)
						)


END
GO











CREATE PROCEDURE [dbo].[spSaleOrderWS_insertItem]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@wst_id			INT, --webservice
	@guid			UNIQUEIDENTIFIER,
	@stor_id		INT,
	@item_id		INT,
	@prli_id		INT,
	@item_qty		DECIMAL(18,5)
)
AS
SET NOCOUNT ON

BEGIN


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@wst_id		INT,
			@stor_id	INT,
			@item_id	INT,
			@prli_id	INT,
			@item_qty	INT,
			@guid		UNIQUEIDENTIFIER

	SELECT	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@wst_id		= 10,
			@stor_id	= 3,
			@item_id	= 256,
			@prli_id	= 1,
			@item_qty	= 2,
			@guid		= '1ADEA5E1-C9B7-4A76-834D-C8919D74E552'
	*/
	-- -------------------------------------------------------------------------------





	BEGIN TRY


		DECLARE @ret_ErrorDescription	VARCHAR(1000)
		SET		@ret_ErrorDescription	= ''



		DECLARE @tis_priority INT
		EXEC spCounters_getNextValue
				@comp_id,
				@stor_id,
				1, --contador prioridades
				@counter_value = @tis_priority OUTPUT



		DECLARE @tis_itemDesc NVARCHAR(100)
		SELECT	@tis_itemDesc = ti.item_desc
		FROM	tbItem ti
		WHERE	ti.comp_id	= @comp_id
		AND		ti.item_id	= @item_id



		DECLARE @curr_id	INT,
				@tis_price  DECIMAL(19,5)
		SELECT	@curr_id	= tpli.curr_id,
				@tis_price	= tpli.prli_price
		FROM	tbPriceListItems tpli
		WHERE	tpli.comp_id	= @comp_id
		AND		tpli.prli_id	= @prli_id
		AND		tpli.item_id	= @item_id



		DECLARE	@getdate	DATETIME
		SET @getdate = GETDATE()



		DECLARE @user_id INT
		SELECT	@user_id	= tws.[user_id]
		FROM	tbWebServices tws
		WHERE	tws.comp_id	= @comp_id
		AND		tws.wst_id	= @wst_id



		DECLARE @rv INT

		DECLARE @wsID AS UNIQUEIDENTIFIER
		SET		@wsID = NEWID()

		EXEC spTempItemStock_insertData
			@comp_id,
			@guid,
			@tis_priority,
			@item_id,
			@tis_itemDesc,
			@tis_itemDesc,
			@curr_id,
			@item_qty,
			@item_qty,
			@prli_id,
			@tis_price,
			@stor_id,
			0,						--@doc_id
			@bra_id,
			@user_id,
			@getdate,				--@insertDate = null,
			@getdate,				--@lastUpdate = null,
			0,						--@tis_cost = null,
			1,						--@tis_costTax = null,
			null,					--@soh_id = null,
			null,					--@sod_id = null,
			'true',					--@to_associate = null,
			null,					--@is_id = null,
			'false',				--@tis_isMade = null,
			@wsID,'',
			-1,
			@return_value = @rv OUTPUT



		--para que no borre los items el depurador
		UPDATE tbTempItemStock
		SET	tis_IsEditingCd = DATEADD(hour,1,GETDATE())
		WHERE tis_id = @rv


		SET		@ret_ErrorDescription	= 'Insert OK'
		--SELECT @rv [code],



	END TRY
	BEGIN CATCH

			Set @rv			= -1
			Set @ret_ErrorDescription	= 'Item_Insert - ' +
				(SELECT
				convert(varchar,ERROR_NUMBER())		+ '-' +
				convert(varchar,ERROR_SEVERITY())	+ '-' +
				convert(varchar,ERROR_STATE())		+ '-' +
				convert(varchar,ERROR_LINE())		+ '-' +
				ERROR_MESSAGE())

	END CATCH


	SELECT	@rv						[code],
			@ret_ErrorDescription	[error_description]

END

GO

CREATE PROCEDURE [dbo].[spSaleOrderWS_insertItem_WithPrice]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@wst_id			INT, --webservice
	@guid			UNIQUEIDENTIFIER,
	@stor_id		INT,
	@item_id		INT,
	@prli_id		INT,
	@item_qty		DECIMAL(18,5),
	@price			DECIMAL(25,10),
	@curr_id		INT
)
AS
SET NOCOUNT ON

BEGIN


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@wst_id		INT,
			@stor_id	INT,
			@item_id	INT,
			@prli_id	INT,
			@item_qty	INT,
			@guid		UNIQUEIDENTIFIER

	SELECT	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@wst_id		= 10,
			@stor_id	= 3,
			@item_id	= 256,
			@prli_id	= 1,
			@item_qty	= 2,
			@guid		= '1ADEA5E1-C9B7-4A76-834D-C8919D74E552'
	*/
	-- -------------------------------------------------------------------------------





	BEGIN TRY


		DECLARE @ret_ErrorDescription	VARCHAR(1000)
		SET		@ret_ErrorDescription	= ''



		DECLARE @tis_priority INT
		EXEC spCounters_getNextValue
				@comp_id,
				@stor_id,
				1, --contador prioridades
				@counter_value = @tis_priority OUTPUT



		DECLARE @tis_itemDesc NVARCHAR(100)
		SELECT	@tis_itemDesc = ti.item_desc
		FROM	tbItem ti
		WHERE	ti.comp_id	= @comp_id
		AND		ti.item_id	= @item_id



		--DECLARE @curr_id	INT,
		--		@tis_price  DECIMAL(19,5)
		--SELECT	@curr_id	= tpli.curr_id,
		--		@tis_price	= tpli.prli_price
		--FROM	tbPriceListItems tpli
		--WHERE	tpli.comp_id	= @comp_id
		--AND		tpli.prli_id	= @prli_id
		--AND		tpli.item_id	= @item_id



		DECLARE	@getdate	DATETIME
		SET @getdate = GETDATE()



		DECLARE @user_id INT
		SELECT	@user_id	= tws.[user_id]
		FROM	tbWebServices tws
		WHERE	tws.comp_id	= @comp_id
		AND		tws.wst_id	= @wst_id



		DECLARE @rv INT

		DECLARE @wsID AS UNIQUEIDENTIFIER
		SET		@wsID = NEWID()

		EXEC spTempItemStock_insertData
			@comp_id,
			@guid,
			@tis_priority,
			@item_id,
			@tis_itemDesc,
			@tis_itemDesc,
			@curr_id,
			@item_qty,
			@item_qty,
			@prli_id,
			@price,
			@stor_id,
			0,						--@doc_id
			@bra_id,
			@user_id,
			@getdate,				--@insertDate = null,
			@getdate,				--@lastUpdate = null,
			0,						--@tis_cost = null,
			1,						--@tis_costTax = null,
			null,					--@soh_id = null,
			null,					--@sod_id = null,
			'true',					--@to_associate = null,
			null,					--@is_id = null,
			'false',				--@tis_isMade = null,
			@wsID,'',
			-1,
			@return_value = @rv OUTPUT



		--para que no borre los items el depurador
		UPDATE tbTempItemStock
		SET	tis_IsEditingCd = DATEADD(hour,1,GETDATE())
		WHERE tis_id = @rv


		SET		@ret_ErrorDescription	= 'Insert OK'
		--SELECT @rv [code],



	END TRY
	BEGIN CATCH

			Set @rv			= -1
			Set @ret_ErrorDescription	= 'Item_Insert - ' +
				(SELECT
				convert(varchar,ERROR_NUMBER())		+ '-' +
				convert(varchar,ERROR_SEVERITY())	+ '-' +
				convert(varchar,ERROR_STATE())		+ '-' +
				convert(varchar,ERROR_LINE())		+ '-' +
				ERROR_MESSAGE())

	END CATCH


	SELECT	@rv						[code],
			@ret_ErrorDescription	[error_description]

END

GO





