CREATE PROCEDURE [dbo].[spSaleOrderWS_insertItemNoCost]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@wst_id			INT, --webservice
	@guid			UNIQUEIDENTIFIER,
	@stor_id		INT,
	@item_id		INT,
	@prli_id		INT,
	@item_qty		DECIMAL(18,5),
	@tis_price		DECIMAL(19,6),
	@curr_id		INT--,
	--@decMLCost		DECIMAL(19,4)
)
AS
	BEGIN
		SET NOCOUNT ON
		BEGIN


			-- -------------------------------------------------------------------------------
			-- Testing
			-- -------------------------------------------------------------------------------
			/*
			DECLARE @comp_id	INT,
					@lang_id	INT,
					@bra_id		INT,
					@wst_id		INT,
					@stor_id	INT,
					@item_id	INT,
					@prli_id	INT,
					@item_qty	INT,
					@guid		UNIQUEIDENTIFIER

			SELECT	@comp_id	= 1,
					@lang_id	= 2,
					@bra_id		= 1,
					@wst_id		= 10,
					@stor_id	= 3,
					@item_id	= 256,
					@prli_id	= 1,
					@item_qty	= 2,
					@guid		= '1ADEA5E1-C9B7-4A76-834D-C8919D74E552'
			*/
			-- -------------------------------------------------------------------------------
			BEGIN TRY
				DECLARE @ret_ErrorDescription	VARCHAR(1000)
				SET		@ret_ErrorDescription	= ''


				DECLARE @storg_id AS INT = NULL
				DECLARE @user_id INT
				SELECT	@user_id	= tws.[user_id],
						@stor_id	= ISNULL(tws.stor_id4FullJaus4ItemInsert,@stor_id),		-- MOS 12-2021 para Arg para que el ALTA del item se haga en Otro Deposito
						@storg_id   = storg_id
					FROM	tbWebServices tws			WITH (NOLOCK)
					WHERE	tws.comp_id	= @comp_id
					AND		tws.wst_id	= @wst_id




				---- ----------------------------------------------------------------------------------
				-- **wlfkn23904723aNDQN4355
				-- MOS: 09-2024: 21820 IDEM a Ticket 11482, Colucci, para que tome del deposito del grupo que Tenga Stock Disponible
				---- ----------------------------------------------------------------------------------
				IF	@storg_id IS NOT NULL	AND
					@storg_id			> 0 -- MOS 12-2022: x Colucci, si tenian definidos los grupos de deposito a cambiar, NO le da pelota si es FULL
					BEGIN
						DECLARE			@stor_idTMP AS integer = NULL
						SELECT TOP 1	@stor_idTMP = stor_id
							FROM tbStorageGroupDetail AS tsgd	WITH (NOLOCK)
							WHERE	tsgd.comp_id	= @comp_id		AND
									tsgd.storg_id	= @storg_id		AND
									dbo.fnGetAStock4MaxAssociation(tsgd.comp_id,tsgd.stor_id,@item_id,999999999) > 0
							ORDER BY tsgd.storg_order4MercadoLibre	ASC

						IF @stor_idTMP IS NOT NULL
							BEGIN
								SET @stor_id = @stor_idTMP
							END
					END
				---- ----------------------------------------------------------------------------------





				DECLARE @tis_priority INT
				EXEC spCounters_getNextValue
						@comp_id,
						@stor_id,
						1, --contador prioridades
						@counter_value = @tis_priority OUTPUT



				DECLARE @tis_itemDesc NVARCHAR(100)
				SELECT	@tis_itemDesc = ti.item_desc
					FROM	tbItem ti			WITH (NOLOCK)
					WHERE	ti.comp_id	= @comp_id
					AND		ti.item_id	= @item_id

				DECLARE	@getdate	DATETIME
				SET @getdate = GETDATE()



				DECLARE @rv INT

				DECLARE @wsID AS UNIQUEIDENTIFIER
				SET		@wsID = NEWID()


				IF @item_id IS NOT NULL
					BEGIN
						SET @tis_price = @tis_price / dbo.fnNoZDiv( dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id) )
					END


				DECLARE @intUserID AS INT
				SET		@intUserID = @user_id * -1

				EXEC spTempItemStock_insertData
					@comp_id,
					@guid,
					@tis_priority,
					@item_id,
					@tis_itemDesc,
					@tis_itemDesc,
					@curr_id,
					@item_qty,
					@item_qty,
					@prli_id,
					@tis_price,
					@stor_id,
					0,						--@doc_id
					@bra_id,
					@intUserID /*@user_id*/,
					@getdate,				--@insertDate = null,
					@getdate,				--@lastUpdate = null,
					0,						--@tis_cost = null,
					1,						--@tis_costTax = null,
					null,					--@soh_id = null,
					null,					--@sod_id = null,
					'true',					--@to_associate = null,
					null,					--@is_id = null,
					'false',				--@tis_isMade = null,
					@wsID,'',
					-1,
					@return_value = @rv OUTPUT


				-- ----------------------------------------------------
				-- Se actualiza el precio con el valor FINAL
				-- ----------------------------------------------------
				UPDATE tbTempItemStock
				SET
					tis_price	= @tis_price
				WHERE	comp_id = @comp_id		AND
						tis_id	= @rv			AND
						item_id IS NOT NULL
				-- ----------------------------------------------------


				--para que no borre los items el depurador
				--UPDATE tbTempItemStock	WITH (ROWLOCK)
				--	SET	tis_IsEditingCd = DATEADD(hour,1,GETDATE()),
				--		sod_MLCost		= ISNULL(@decMLCost,0)

				--	WHERE tis_id = @rv
				SET		@ret_ErrorDescription	= 'Insert OK'
				--SELECT @rv [code],
			END TRY
			BEGIN CATCH

					Set @rv			= -1
					Set @ret_ErrorDescription	= 'Item_Insert - ' +
						(SELECT
						CONVERT(varchar,ERROR_NUMBER())		+ '-' +
						CONVERT(varchar,ERROR_SEVERITY())	+ '-' +
						CONVERT(varchar,ERROR_STATE())		+ '-' +
						CONVERT(varchar,ERROR_LINE())		+ '-' +
						ERROR_MESSAGE())
			END CATCH

			SELECT	@rv						[code],
					@ret_ErrorDescription	[error_description]
		END
END
GO

